INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 1, '{"id":1,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":1,"q":"Maximum contribution to the floor of orbit is by:","o":["Maxillary","Zygomatic","Sphenoid","Palatine"],"a":0,"e":"Ans. A. Maxillary The maxillae are the largest of the facial bones, other than the mandible, and jointly form the whole of the upper jaw. Each bone forms the greater part of the floor and lateral wall of the nasal cavity, and of the floor of the orbit \"Orbital surface of maxilla is smooth and triangular, and forms most of the floor of the orbit\" Also know: Maxilla is also the most commonly fractured bone of orbital floor. The floor (inferior wall) is formed by the orbital surface of maxilla, the orbital surface of Zygomatic bone and the orbital process of palatine bone The seven bones that articulate to the orbit are","pyqMatches":[{"year":"2012","no":94,"q":"Maximum contribution to the floor of orbit is by:","o":["Maxillary","Zygomatic","Sphenoid","Palatine"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2, 'Anatomy', 'Abdomen', 'Moderate', 'Anatomy', 2, '{"id":2,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Moderate","source":"Anatomy","sourceNo":2,"q":"Structures passing through Calot''s triangle are all EXCEPT:","o":["Portal vein","Cystic artery","Right hepatic artery","Lymph node of Lund"],"a":0,"e":"Portal vein THE HEPATOBILIARY TRIANGLE OR CYSTOHEPATIC TRIANGLE OR CALOT''S TRIANGLE: Boundaries: Common hepatic duct medially Cystic duct inferiorly Inferior surface of liver superiorly Contents: Cystic artery Right hepatic artery Lymph node of Lund","pyqMatches":[{"year":"2015","no":156,"q":"Structures passing through Calot''s triangle are all EXCEPT:","o":["Portal vein","Cystic artery","Right hepatic artery","Lymph node of Lund"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 3, '{"id":3,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":3,"q":"Which is a typical intercostal nerve?","o":["First","Second","Third","Seventh"],"a":2,"e":"Third \"Typical intercostal nerves are the ones that are confined to their own intercostal spaces in the thoracic wall. The third, fourth, fifth and sixth intercostal nerves are the typical nerves\"","pyqMatches":[{"year":"2016","no":70,"q":"Which is a typical intercostal nerve?","o":["First","Second","Third","Seventh"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 4, '{"id":4,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":4,"q":"Trendelenburg test is positive due to injury to which of the following nerve?","o":["Obturator","Sciatic","Superior Gluteal","Inferior Gluteal"],"a":2,"e":"Ans. C. Superior Gluteal A positive Trendelenburg is relatively non-specific and may indicate: Pain (e.g. due to osteoarthritis of the hip joint) Weak hip abductors (gluteus medius, gluteus minimus) Short femoral neck/ fracture of neck Dislocation or subluxation of the hip Neuropathy Gluteus medius and minimus are supplied by Superior Gluteal nerve. Trendelenburg test Normally when a person is made to stand on one leg, the hip abductors of the ipsilateral side raise the opposite and the unsupported side of the pelvis. If the abductor mechanism is defective, the unsupported side of the pelvis drops and this is known as positive Trendelenburg test.","pyqMatches":[{"year":"2016","no":1482,"q":"Trendelenburg test is positive due to injury to which of the following nerve?","o":["Obturator","Sciatic","Superior Gluteal","Inferior Gluteal"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 5, '{"id":5,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":5,"q":"Lateral boundary of cubital fossa is formed by:","o":["Brachioradialis","Pronator teres","Brachialis","Biceps"],"a":0,"e":"Brachioradialis Boundaries of cubital fossa- Laterally - Medial border of brachioradialis. Medially - Lateral border of pronator teres. Base - It is directed upwards, and is represented by an imaginary line joining the front of two epicondyles of the humerus. Apex - It is directed downwards, and is formed by the area where brachioradialis crosses the pronator teres muscle.","pyqMatches":[{"year":"2015","no":12,"q":"Lateral boundary of cubital fossa is formed by:","o":["Brachioradialis","Pronator teres","Brachialis","Biceps"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6, 'Anatomy', 'Head & Neck', 'Moderate', 'Anatomy', 6, '{"id":6,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Moderate","source":"Anatomy","sourceNo":6,"q":"All of the following are structures associated with pterygopalatine fossa, EXCEPT:","o":["Pterygopalatine ganglion","Mid third of maxillary artery","Maxillary nerve","Greater petrosal nerve"],"a":1,"e":"The pterygopalatine fossa is the region between the pterygomaxillary fissure and the nasal cavity. * The fossa accommodates branches of the maxillary nerve [cranial nerve (CN) V-2], the pterygopalatine ganglion, the terminal branches of the maxillary artery, and greater superficial petrosal nerve.","pyqMatches":[{"year":"2012","no":79,"q":"All of the following are structures associated with pterygopalatine fossa, EXCEPT:","o":["Pterygopalatine ganglion","Mid third of maxillary artery","Maxillary nerve","Greater petrosal nerve"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7, 'Anatomy', 'Head & Neck', 'Moderate', 'Anatomy', 7, '{"id":7,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Moderate","source":"Anatomy","sourceNo":7,"q":"Which of the following is NOT a branch of 1st part of maxillary artery?","o":["Middle meningeal artery","Accessory meningeal artery","Inferior alveolar artery","Greater palatine artery"],"a":3,"e":"Branches of maxillary artery: The maxillary artery consists of three parts; mandibular part, pterygoid part, pterygopalatine part. Branches of mandibular part: Inferior alveolar artery Middle meningeal artery Deep auricular artery Anterior tympanic artery Occasionally an accessory meningeal branch. Branches of pterygoid part: Masseteric artery Deep temporal branches Pterygoid branches Buccal artery Branches of pterygopalatine part: Posterior superior alveolar artery Infraorbital artery Descending palatine artery Greater palatine artery Lesser palatine artery Sphenopalatine artery Lateral posterior nasal arteries Posterior septal branches","pyqMatches":[{"year":"2012","no":108,"q":"Which of the following is NOT a branch of 1st part of maxillary artery?","o":["Middle meningeal artery","Accessory meningeal artery","Inferior alveolar artery","Greater palatine artery"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 8, '{"id":8,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":8,"q":"Ophthalmic artery is a branch of ?","o":["Cavernous part of ICA","Cerebral part of ICA","MCA","Facial artery"],"a":1,"e":"The common carotid arteries bifurcate at the level of the thyroid cartilage into the external and internal carotid arteries. The external carotid artery sends branches to the neck and face, whereas the internal carotid artery ascends to the base of the skull, entering the carotid canal. Upon exiting the carotid canal, the internal carotid artery courses horizontally over the foramen lacerum and enters the cavernous sinus and, after turning superiorly, divides into its terminal branches. Internal carotid artery It is the main artery supplying structures inside the cranial cavity and orbit. It is divided into 4 parts :? * Cervical part :- It extends from upper border of thyroid cartilage to the base of skull. This part gives no branch. * Petrous part :- It lies in bony carotid canal in the petrous temporal bone. It gives two branches (i)Caroticotympanic, and (ii) pterygoid. * Cavernous part :- It runs through the medial wall of cavernous sinus. It gives three branches : (i) Meningeal branch, (ii) hypophyseal branch and (iii) cavernous branch. * Cerebral part :- It is related to inferior surface of cerebrum. It gives following branches: (i) Ophthalmic artery,(ii) posterior communicating artery, (iii) anterior choroidal artery, (iv) anterior cerebral artery and (v) middle cerebral artery.","pyqMatches":[{"year":"2012","no":97,"q":"Ophthalmic artery is a branch of ?","o":["Cavernous part of ICA","Cerebral part of ICA","MCA","Facial artery"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 9, '{"id":9,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":9,"q":"Postganglionic fibres to parotid gland is supplied by?","o":["Glossopharyngeal nerve","Auriculotemporal nerve","Both of the above","None of the above"],"a":1,"e":"Preganglionic nerves travel in the lesser petrosal branch of the glossopharyngeal nerve and synapse in the otic ganglion. Postganglionic fibers reach the gland via the auriculotemporal nerve. Nerve supply of parotid gland Innervation of the salivary gland is as follows:- Parasympathetic (secretomotor) : → They reach the gland through auriculotemporal nerve as the following route:- Preganglionic fibers - Originate in the inferior salivary nucleus; pass through glossopharyngeal nerve; its tympanic branch; tympanic plexus, and lesser petrosal nerve. Relay ganglion:- Otic ganglion. Postganglionic fibers:- Pass through the auriculotemporal nerve to reach the gland. Sympathetic (Vasomotor) : → Derived from the plexus around the middle meningeal artery. Sensory: derived from the auriculotemporal nerve, except for parotid fascia and overlying skin which are innervated by the great auricular nerve(c2, c3)","pyqMatches":[{"year":"2015","no":108,"q":"Postganglionic fibres to parotid gland is supplied by?","o":["Glossopharyngeal nerve","Auriculotemporal nerve","Both of the above","None of the above"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (10, 'Anatomy', 'Embryology', 'Moderate', 'Anatomy', 10, '{"id":10,"subject":"Anatomy","chapter":"Embryology","difficulty":"Moderate","source":"Anatomy","sourceNo":10,"q":"Sensory supply to tongue is by all, EXCEPT?","o":["Lingual nerve","Vagus nerve","Glossopharyngeal nerve","None of the above"],"a":3,"e":"The sensory innervation of the tongue reflects its embryological development. The nerve of general sensation to the presulcal part is the lingual nerve, which also carries taste sensation derived from the chorda tympani branch of the facial nerve. The nerve supplying both general and taste sensation to the postsulcal part is the glossopharyngeal nerve. An additional area in the region of the valleculae is supplied by the internal laryngeal branch of the vagus nerve.","pyqMatches":[{"year":"2015","no":54,"q":"Sensory supply to tongue is by all, EXCEPT?","o":["Lingual nerve","Vagus nerve","Glossopharyngeal nerve","None of the above"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (11, 'Anatomy', 'Head & Neck', 'Moderate', 'Anatomy', 11, '{"id":11,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Moderate","source":"Anatomy","sourceNo":11,"q":"Cranial part of accessory nerve supplies all palatal muscles, EXCEPT?","o":["Palatoglossus","Palato pharyngeus","Tensor veli palatini","Tensor veli tympani"],"a":2,"e":"The cranial root of the accessory nerve is smaller than the spinal root. It exits the skull through the jugular foramen and unites for a short distance with the spinal root. Its fibers innervate the pharyngeal and palatal muscles, except tensor veli palatini. Because the cranial part of accessory nerve (CN XI) leaves the jugular foramen as joining the CN X, it is sometimes considered part of the plexus as well The tensor veli palatini is supplied by the medial pterygoid nerve, a branch of mandibular nerve, the third branch of the trigeminal nerve - the only muscle of the palate not innervated by the pharyngeal plexus","pyqMatches":[{"year":"2012","no":110,"q":"Cranial part of accessory nerve supplies all palatal muscles, EXCEPT?","o":["Palatoglossus","Palato pharyngeus","Tensor veli palatini","Tensor veli tympani"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (12, 'Anatomy', 'Upper Limb', 'Hard', 'Anatomy', 12, '{"id":12,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Hard","source":"Anatomy","sourceNo":12,"q":"A patient is found to have a melanoma originating in the skin of the left forearm. After removal of the tumor from the forearm, all axillary lymph nodes lateral to the medial edge of the pectoralis minor muscle are removed. Which axillary nodes would not be removed?","o":["Apical lymph nodes","Central lymph nodes","Lateral lymph nodes","Pectoral lymph nodes"],"a":0,"e":"The lymph nodes lateral to the LATERAL edge of the pectoralis minor are the lateral axillary nodes. Pectoral or anterior axillary nodes are deep to the lateral edge of the pectoralis major muscle. Central axillary nodes are found directly under pectoralis minor, while subscapular or posterior axillary nodes are adjacent to the subscapularis muscle. The apical axillary nodes are medial to the medial edge of pectoralis minor and so it won''t be removed. level Part of axilla Lymph nodes I Low axilla Lymph nodes lateral to the lateral border of pectoralis minor(central group, lateral group, anterior group, posterior group) II Mid axilla Lymph nodes between the lateral and medial borders of pectoralis minor. plus interpectoral lymph nodes III Apical axilla Lymph nodes medial to medial margin of pectoralis minor (including subclavicular, infraclavicular or apical).","pyqMatches":[{"year":"2012","no":38,"q":"A patient is found to have a melanoma originating in the skin of the left forearm. After removal of the tumor from the forearm, all axillary lymph nodes lateral to the medial edge of the pectoralis minor muscle are removed. Which axillary nodes would not be removed?","o":["Apical lymph nodes","Central lymph nodes","Lateral lymph nodes","Pectoral lymph nodes"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (13, 'Anatomy', 'Upper Limb', 'Hard', 'Anatomy', 13, '{"id":13,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Hard","source":"Anatomy","sourceNo":13,"q":"A patient has a herniated intervertebral disc impinging on the right C5 nerve roots. Which of the following movements would most likely be affected?","o":["Extension of the fingers","Extension of the shoulder","Flexion of the elbow","Flexion of the wrist"],"a":2,"e":"C5 helps mediate flexion, abduction, and lateral rotation of the shoulder, and flexion of the elbow. Both C5 and C6 mediate extension of the elbow. Extension of the fingers is mediated by C7 and 8. Extension of the shoulder is mediated by C7 and 8. Flexion of the wrist is mediated by C6 and 7.","pyqMatches":[{"year":"2015","no":9,"q":"A patient has a herniated intervertebral disc impinging on the right C5 nerve roots. Which of the following movements would most likely be affected?","o":["Extension of the fingers","Extension of the shoulder","Flexion of the elbow","Flexion of the wrist"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (14, 'Anatomy', 'Lower Limb', 'Moderate', 'Anatomy', 14, '{"id":14,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Moderate","source":"Anatomy","sourceNo":14,"q":"All are true about femoral triangle, EXCEPT?","o":["Lateral margin is formed by sartorius","Floor is formed by adductor longus","Contains the femoral vessels","None of the above"],"a":3,"e":"All are true about the femoral triangle The femoral triangle is a depressed area of the thigh lying distal to the inguinal fold. Its apex is distal, its limits are the medial margin of sartorius laterally, the medial margin of adductor longus medially and the inguinal ligament proximally (the base). Its floor is provided laterally by iliacus and psoas major, medially by pectineus and adductor longus. The femoral vessels, passing from mid base to apex, are in the deepest part of the triangle. Lateral to the artery the femoral nerve divides. The triangle also contains fat and lymph nodes.","pyqMatches":[{"year":"2015","no":19,"q":"All are true about femoral triangle, EXCEPT?","o":["Lateral margin is formed by sartorius","Floor is formed by adductor longus","Contains the femoral vessels","None of the above"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (15, 'Anatomy', 'Lower Limb', 'Moderate', 'Anatomy', 15, '{"id":15,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Moderate","source":"Anatomy","sourceNo":15,"q":"In walking, gravity tends to tilt pelvis and trunk to the unsupported side, major factor in preventing this unwanted movement is?","o":["Adductor muscles","Quadriceps","Gluteus maximus","Gluteus medius and minimus"],"a":3,"e":"The gluteus medius muscle abducts and medially rotates the femur at the hip joint. In addition, the gluteus medius holds the pelvis secure over the stance leg, preventing pelvic drop on the opposite swing side during gait. The superior gluteal nerve (L4, L5, S1) innervates this muscle. The action of the gluteus minimus muscle is the same as that of the gluteus medius—it abducts the femur at the hip joint, holding the pelvis secure over the stance leg and preventing pelvic drop on the opposite swing side during gait and hip medial rotation. The inferior gluteal nerve (L5, S1, S2) innervates this muscle.","pyqMatches":[{"year":"2012","no":42,"q":"In walking, gravity tends to tilt pelvis and trunk to the unsupported side, major factor in preventing this unwanted movement is?","o":["Adductor muscles","Quadriceps","Gluteus maximus","Gluteus medius and minimus"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (16, 'Anatomy', 'Head & Neck', 'Moderate', 'Anatomy', 16, '{"id":16,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Moderate","source":"Anatomy","sourceNo":16,"q":"Which of the following represent the commonest variation in the arteries arising from the arch of aorta?","o":["Absence of brachiocephalic trunk","Left vertebral artery arising from the arch","Presence of retroesophageal subclavian artery","Left common carotid artery arising from brachiocephalic trunk"],"a":3,"e":"Most common anomaly of the aortic arch seen in 10-20% individuals is characterized by the origin of the left common carotid artery from the brachiocephalic (innominate) trunk. Other common anomalies include: A four vessel arch with separate origins for the right common carotid and right subclavian arteries (2.5%), Origin of the left vertebral artery directly from a four vessel aortic arch typically between the ostia of the left common carotid and subclavian arteries ( 2.4- 5.8%).","pyqMatches":[{"year":"2015","no":37,"q":"Which of the following represent the commonest variation in the arteries arising from the arch of aorta?","o":["Absence of brachiocephalic trunk","Left vertebral artery arising from the arch","Presence of retroesophageal subclavian artery","Left common carotid artery arising from brachiocephalic trunk"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (17, 'Anatomy', 'Head & Neck', 'Moderate', 'Anatomy', 17, '{"id":17,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Moderate","source":"Anatomy","sourceNo":17,"q":"Which among the following is NOT a branch of Arch of Aorta?","o":["Brachiocephalic","Right common carotid","Left common carotid","Left Subclavian"],"a":1,"e":"The arch of the aorta begins at the level of the upper border of the second sternocostal articulation of the right side. The branches given off from the arch of the aorta are three in number: the brachiocephalic artery (innominate), the left common carotid, and the left subclavian. Brachiocephalic Artery is the largest branch of the arch of the aorta. It divides into the right common carotid and right subclavian arteries.","pyqMatches":[{"year":"2015","no":36,"q":"Which among the following is NOT a branch of Arch of Aorta?","o":["Brachiocephalic","Right common carotid","Left common carotid","Left Subclavian"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (18, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 18, '{"id":18,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":18,"q":"The key to the root of the neck is the scalenus anterior muscle. Which among the following is TRUE about scalenus anterior?","o":["Not Pierced by phrenic nerve","Attached to scalene tubercle on 2nd rib","Separates subclavian artery from subclavian vein","Pierced by phrenic nerve"],"a":0,"e":"Ans. (A) Not pierced by phrenic nerve The subclavian vein forms an arch across the pleura at a level below the arch of subclavian artery. The two arches are separated from each other by scalenus anterior muscle. Scalenus anterior arises from the anterior tubercles of C3-C6 and attaches to the scalene tubercle and adjacent ridge on the inner border and upper surface of the first rib. Phrenic nerve passes vertically down across the obliquity of the muscle, plastered there to by the prevertebral fascia. Transcervical and suprascapular arteries lie between the scalenus anterior and the carotid sheath.","pyqMatches":[{"year":"2014","no":91,"q":"The key to the root of the neck is the scalenus anterior muscle. Which among the following is TRUE about scalenus anterior?","o":["Not Pierced by phrenic nerve","Attached to scalene tubercle on 2nd rib","Separates subclavian artery from subclavian vein","Pierced by phrenic nerve"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (19, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 19, '{"id":19,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":19,"q":"Most common diaphragmatic hernia is:","o":["Bochdalek hernia","Morgagni hernia","Paraesophagel hernia","None of the above"],"a":0,"e":"Diaphragmatic hernias are of various types. The most common is a posterolateral (Bochdalek) hernia, which occurs as a result of a defect in the posterior diaphragm in the region of the tenth or eleventh ribs.","pyqMatches":[{"year":"2012","no":1146,"q":"Most common diaphragmatic hernia is:","o":["Bochdalek hernia","Morgagni hernia","Paraesophagel hernia","None of the above"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (20, 'Anatomy', 'Thorax', 'Moderate', 'Anatomy', 20, '{"id":20,"subject":"Anatomy","chapter":"Thorax","difficulty":"Moderate","source":"Anatomy","sourceNo":20,"q":"Boundary of the Koch''s triangle is not formed by?","o":["Tricuspid valve ring","Coronary sinus","Tendon of todaro","Limbus fossa ovalis"],"a":3,"e":"Koch''s Triangle is a triangle enclosed by the septal leaflet of the tricuspid valve, the coronary sinus, and the membranous part of the interatrial septum. Koch’s triangle: Walter Karl Koch (1880–1962) was a distinguished German surgeon who discovered a triangular-shaped area in the right atrium of the heart that marks the atrioventricular node (known as Koch''s triangle). The three sides of the triangle are defined by the following structures within the right atrium: The ostium of the coronary sinus, posteriorly; The anterior portion of the tricuspid valve annulus; and The tendon of Todaro (a tendinous structure connecting the valve of the inferior vena cava ostium to the central fibrous body), posteriorly. Importance: Used as an anatomical landmark for location of the atrioventricular node during electrophysiology procedures such as pacing or ablation.","pyqMatches":[{"year":"2012","no":63,"q":"Boundary of the Koch''s triangle is not formed by?","o":["Tricuspid valve ring","Coronary sinus","Tendon of todaro","Limbus fossa ovalis"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (21, 'Anatomy', 'Miscellaneous', 'Moderate', 'Anatomy', 21, '{"id":21,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anatomy","sourceNo":21,"q":"Esophagus is constricted at 4 anatomic locations. Narrowest part of esophagus lies at which of the following constriction?","o":["At the level of cricopharyngeal sphincter","At the crossing of aortic arch","At the crossing of left bronchus","At the level of opening in the diaphragm"],"a":0,"e":"Narrowest part of esophagus is at its commencement at the cricopharyngeal sphincter which is 15cm from the incisor teeth. Other sites of esophagus where it is slightly constricted includes: Crossing by the aortic arch which is 22cm from the teeth. Crossing by the left principal bronchus which is 27cm from the teeth At the opening in the diaphragm which is 38cm from the teeth","pyqMatches":[{"year":"2016","no":946,"q":"Esophagus is constricted at 4 anatomic locations. Narrowest part of esophagus lies at which of the following constriction?","o":["At the level of cricopharyngeal sphincter","At the crossing of aortic arch","At the crossing of left bronchus","At the level of opening in the diaphragm"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (22, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 22, '{"id":22,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":22,"q":"Sympathetic supply to the heart arises from which of the following spinal segments?","o":["T1 to T5","T2 to T6","T3 to T7","T4 to T8"],"a":0,"e":"Sympathetic nerve cells supplying the heart are located in the intermediolateral horn of spinal segments T1 to T5. Sympathetic supply is cardio-acceleratory, and on stimulation, they increase the heart rate, and also dilate coronary arteries. Both parasympathetic and sympathetic nerves form the superficial and deep cardiac plexuses, the branches of which run along the coronary arteries to reach the myocardium.","pyqMatches":[{"year":"2012","no":59,"q":"Sympathetic supply to the heart arises from which of the following spinal segments?","o":["T1 to T5","T2 to T6","T3 to T7","T4 to T8"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (23, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 23, '{"id":23,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":23,"q":"All of the following are branches of splenic artery, except?","o":["Hilar branches","Short Gastric Artery","Arteria Pancreatica Magna","Right Gastroepiploic Artery"],"a":3,"e":"Right Gastroepiploic artery is a branch of superior mesentric artery, a branch of hepatic artery. The left Gastroepiploic artery is a branch of splenic artery which anastomoses with the right Gastroepiploic artery.","pyqMatches":[{"year":"2015","no":62,"q":"All of the following are branches of splenic artery, except?","o":["Hilar branches","Short Gastric Artery","Arteria Pancreatica Magna","Right Gastroepiploic Artery"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (24, 'Anatomy', 'Pelvis & Perineum', 'Hard', 'Anatomy', 24, '{"id":24,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Hard","source":"Anatomy","sourceNo":24,"q":"A patient with external hemorrhoids develops pain while passing stools. Which of the following nerve mediating this pain?","o":["Pudendal nerve","Hypogastric nerve","Sympathetic plexus","Splanchnic visceral nerve"],"a":0,"e":"External hemorrhoids are covered by the mucous membrane of the lower half of the anal canal or the skin, and they are innervated by the inferior rectal nerves. Inferior rectal nerve is a branch of pudendal nerve. Lower half of anal canal is sensitive to pain, temperature, touch, and pressure. The pectinate line indicates the level where the upper half of the anal canal joins the lower half. The mucous membrane of the upper half is sensitive to stretch and is innervated by sensory fibers that ascend through the hypogastric plexuses. The involuntary internal sphincter is supplied by sympathetic fibers from the inferior hypogastric plexuses. The voluntary external sphincter is supplied by the inferior rectal nerve, a branch of the pudendal nerve and the perineal branch of the fourth sacral nerve.","pyqMatches":[{"year":"2014","no":1591,"q":"A patient with external hemorrhoids develops pain while passing stools. Which of the following nerve mediating this pain?","o":["Pudendal nerve","Hypogastric nerve","Sympathetic plexus","Splanchnic visceral nerve"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (25, 'Anatomy', 'Abdomen', 'Moderate', 'Anatomy', 25, '{"id":25,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Moderate","source":"Anatomy","sourceNo":25,"q":"The boundaries of the interconnection between greater sac and lesser sac of peritoneum known as ''Foramen of Winslow'' are all, EXCEPT:","o":["Caudate lobe of liver","Inferior vena cava","Free border of lesser omentum","4th part of Duodenum"],"a":3,"e":"Interconnection between greater sac and lesser sac of peritoneum is known as Foramen of Winslow. It has the following boundaries: Superior boundary: Caudate lobe of liver Anterior boundary: Free edge of lesser omentum containing common bile duct, hepatic artery andportal vein. Inferior boundary: First part of duodenum Posterior boundary: Inferior vena cava and abdominal aorta","pyqMatches":[{"year":"2015","no":67,"q":"The boundaries of the interconnection between greater sac and lesser sac of peritoneum known as ''Foramen of Winslow'' are all, EXCEPT:","o":["Caudate lobe of liver","Inferior vena cava","Free border of lesser omentum","4th part of Duodenum"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (26, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 26, '{"id":26,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":26,"q":"What is the number of layers in greater omentum?","o":["1","2","3","4"],"a":3,"e":"The greater omentum is folded back on itself and is therefore made up of four layers of closely applied visceral peritoneum, which are separated by variable amounts of adipose tissue.","pyqMatches":[{"year":"2016","no":80,"q":"What is the number of layers in greater omentum?","o":["1","2","3","4"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (27, 'Anatomy', 'Pelvis & Perineum', 'Moderate', 'Anatomy', 27, '{"id":27,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Moderate","source":"Anatomy","sourceNo":27,"q":"All pass through deep inguinal ring, EXCEPT?","o":["Spermatic cord","Internal spermatic fascia","Round ligament","Ilioinguinal nerve"],"a":3,"e":"It transmits the spermatic cord in the male and the round ligament of the uterus in the female into the inguinal canal. Internal spermatic fascia is present in the spermatic cord. Ilio inguinal nerve passes only through the superficial inguinal canal and not through deep. Inguinal canal: contains the spermatic cord and the ilioinguinal nerve in the male, and the round ligament of the uterus and the ilioinguinal nerve in the female. It is an oblique canal of about 4 cm. long, slanting downward and medialward, and placed parallel with and a little above the inguinal ligament; it extends from the deep inguinal ring laterally to the superficial inguinal ring medially. Deep inguinal ring: a hole in transversalis fascia lying 3cm superior to the midpoint of the inguinal ligament. Contents: Spermatic cord in males Round ligament in females Superficial inguinal ring: V-shaped defect in the lower medial fibres of the external oblique just superior and lateral to the pubic tubercle. Ilioinguinal nerve passes through superficial inguinal ring. Contents of inguinal canal Spermatic cord in males Round ligament in females Ilioinguinal nerve in both males and females","pyqMatches":[{"year":"2015","no":90,"q":"All pass through deep inguinal ring, EXCEPT?","o":["Spermatic cord","Internal spermatic fascia","Round ligament","Ilioinguinal nerve"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (28, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 28, '{"id":28,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":28,"q":"All of the following arteries are the branches of coeliac trunk, EXCEPT?","o":["Left gastric artery","Right gastric artery","Splenic artery","Hepatic artery"],"a":1,"e":"Branches of the coeliac trunk are left gastric artery, splenic artery, and common hepatic artery. The coeliac trunk arises from the abdominal aorta, immediately below the aortic hiatus of the diaphragm at the T12 vertebral level. Right gastric artery is a branch of common hepatic artery. Branches of common hepatic artery are: Proper hepatic artery Right gastric artery Gastroduodenal artery: right gastroomental artery, superior pancreaticoduodenal artery are branches of gastroduodenal artery. Cystic artery Branches of splenic artery: Left gastroepiploic artery Short gastric branches Pancreatic branches","pyqMatches":[{"year":"2012","no":67,"q":"All of the following arteries are the branches of coeliac trunk, EXCEPT?","o":["Left gastric artery","Right gastric artery","Splenic artery","Hepatic artery"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (29, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 29, '{"id":29,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":29,"q":"Inferior pancreaticoduodenal artery is a branch of which of the following artery?","o":["Splenic artery","Left gastric artery","Gastroduodenal artery","Superior mesenteric artery"],"a":3,"e":"Inferior pancreaticoduodenal artery is a branch of superior mesenteric artery. It supplies the pancreas and adjoining part of the duodenum. Its anterior and posterior branches anastomose with the branches of superior pancreaticoduodenal artery. This anastomosis is the only communication between the arteries of foregut and midgut. Branches of superior mesenteric artery are: Inferior pancreaticoduodenal artery Jejunal and ileal branches Ileocolic artery Right colic artery Middle colic artery","pyqMatches":[{"year":"2015","no":60,"q":"Inferior pancreaticoduodenal artery is a branch of which of the following artery?","o":["Splenic artery","Left gastric artery","Gastroduodenal artery","Superior mesenteric artery"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (30, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 30, '{"id":30,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":30,"q":"Portal vein is formed by union of which of the following veins?","o":["Superior mesenteric vein & Splenic vein","Superior mesenteric vein & inferior mesenteric vein","Inferior mesenteric vein & Splenic vein","inferior mesenteric vein & Hepatic vein"],"a":0,"e":"Portal vein is formed by the union of Superior mesenteric vein (SMV) and splenic vein posterior to the neck of pancreas. The inferior mesenteric vein drains into the splenic vein. * The hepatic portal vein pass posterior to the first part of duodenum, in the free edge of lesser omentum. * At the porta hepatis, it divides into right and left branches supplying the right and left lobes of the liver. * Within the sinusoids of the liver, hepatic portal blood and oxygenated blood from the hepatic artery mix together and come into contact with the hepatocytes, where metabolites such as products of digestion are exchanged. * Blood from the sinusoids empties into hepatic veins draining the liver and in turn drain into IVC, and blood is returned to heart.","pyqMatches":[{"year":"2012","no":80,"q":"Portal vein is formed by union of which of the following veins?","o":["Superior mesenteric vein & Splenic vein","Superior mesenteric vein & inferior mesenteric vein","Inferior mesenteric vein & Splenic vein","inferior mesenteric vein & Hepatic vein"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (31, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 31, '{"id":31,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":31,"q":"Uvula vesicae seen in bladder is formed from the following structure ?","o":["Median lobe of prostate","Lateral lobe of prostate","Anterior lobe of prostate","Posterior lobe of prostate"],"a":0,"e":"Uvula vesicae is a small elevation situated immediately behind the urethral orifice, which is produced by the underlying median lobe of the prostate. It enlarges with age due to enlargement of the underlying median lobe of the prostate and may inhibit complete bladder emptying.","pyqMatches":[{"year":"2015","no":80,"q":"Uvula vesicae seen in bladder is formed from the following structure ?","o":["Median lobe of prostate","Lateral lobe of prostate","Anterior lobe of prostate","Posterior lobe of prostate"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (32, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 32, '{"id":32,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":32,"q":"Facial nerve is a derivative of which of the following branchial arch?","o":["First arch","Second arch","Third arch","Fourth arch"],"a":1,"e":"Facial nerve is a derivative of second branchial arch. Muscles of facial expression derived from it are buccinator, auricularis, frontalis, platysma, orbicularis oris and orbicularis oculi. Additional muscles supplied by it are stapedius, stylohyoid, and posterior belly of digastric. Branchial arch Cranial nerve Muscles First mandibular Trigeminal Muscles of mastication: masseter, temporalis, medial and lateral pterygoid. Additional muscles: mylohyoid, anterior belly of digastric, tensor tympani, tensor veli palatini Third Glossopharyngeal Stylopharyngeus Fourth and sixth Superior laryngeal, recurrent laryngeal branches of vagus Pharyngeal and laryngeal muscles: cricothyroid, levator veli palatini, constrictors of pharynx, intrinsic muscles of larynx Ref: Neuroscience for the Study of Communicative Disorders By Subhash Chandra Bhatnagar page 279.","pyqMatches":[{"year":"2016","no":13,"q":"Facial nerve is a derivative of which of the following branchial arch?","o":["First arch","Second arch","Third arch","Fourth arch"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (33, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 33, '{"id":33,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":33,"q":"Which of the following nuclei belong to the general visceral afferent column?","o":["Facial nerve nucleus","Trigeminal nucleus","Dorsal nucleus of vagus","Nucleus ambiguus"],"a":2,"e":"Visceral afferent fibers, also called general visceral afferent fibers, convey sensation from the alimentary tract, heart, vessels, and lungs by way of nerves IX and X. A specialized visceral afferent component is involved with the sense of taste; fibers carrying gustatory impulses are present in cranial nerves VII, IX, and X. The general visceral afferent column is represented by part of the dorsal nucleus of the vagus nerve. Ref: Waxman S.G. (2010). Chapter 8. Cranial Nerves and Pathways. In S.G. Waxman (Ed), Clinical Neuroanatomy, 26e.","pyqMatches":[{"year":"2016","no":108,"q":"Which of the following nuclei belong to the general visceral afferent column?","o":["Facial nerve nucleus","Trigeminal nucleus","Dorsal nucleus of vagus","Nucleus ambiguus"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (34, 'Anatomy', 'Miscellaneous', 'Moderate', 'Anatomy', 34, '{"id":34,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anatomy","sourceNo":34,"q":"Which of the following statement regarding cell division is NOT TRUE?","o":["Produces haploid number of chromosomes","Produces same number of chromosomes","Produces 2 cells","None of the above"],"a":0,"e":"Mitosis is a nuclear division in which daughter cells receive the same number of chromosomes as that of parent cell. The daughter cells resulting from mitosis are identical to each other and also to the parent cell in the quantity and quality of genetic material. Mitosis: It is the process that facilitates equal partitioning of replicated chromosomes into two identical groups. As a result of this two new daughter cells arise from one original cell. All the cells created through mitosis are genetically identical to one another and to the cell from where they came. The main purpose of mitosis in eukaryotic cells are growth of the individual, repair of tissue and asexual reproduction.","pyqMatches":[{"year":"2016","no":681,"q":"Which of the following statement regarding cell division is NOT TRUE?","o":["Produces haploid number of chromosomes","Produces same number of chromosomes","Produces 2 cells","None of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (35, 'Anatomy', 'Miscellaneous', 'Moderate', 'Anatomy', 35, '{"id":35,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anatomy","sourceNo":35,"q":"All the following features are seen in neurons from dorsal root ganglia, EXCEPT:","o":["They are multipolar","They contain lipofuscin granules","They have centrally located nuclei","They are derived from neural crest cells"],"a":0,"e":"Dorsal root ganglion consist of sensory neurons which are pseudounipolar and have no synaptic connections in the ganglion. They are classified as pseudounipolar because it lacks dendrites and has a single axon that bifurcate into a centrally efferent branch that functions as a dendrite to carry afferent sensory signals.","pyqMatches":[{"year":"2012","no":161,"q":"All the following features are seen in neurons from dorsal root ganglia, EXCEPT:","o":["They are multipolar","They contain lipofuscin granules","They have centrally located nuclei","They are derived from neural crest cells"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (36, 'Anatomy', 'Abdomen', 'Moderate', 'Anatomy', 36, '{"id":36,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Moderate","source":"Anatomy","sourceNo":36,"q":"Suprarenal gland gets its blood supply from all of the following arteries except:","o":["Aorta","Renal artery","Inferior phrenic artery","Superior mesentric artery"],"a":3,"e":"D. i.e. Superior Mesenteric artery Right suprarenal vein drain into IVC ; and left suprarenal vein drain into left Renal vein Suprarenal gland is supplied by suprarenal, renal, inferior phrenic artery and aorta","pyqMatches":[{"year":"2015","no":59,"q":"Suprarenal gland gets its blood supply from all of the following arteries except:","o":["Aorta","Renal artery","Inferior phrenic artery","Superior mesentric artery"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (37, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 37, '{"id":37,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":37,"q":"Internal anal sphincter is a apart of:","o":["Puborectalis muscle","Deep perineal muscles","Internal longitudinal fibers","Internal circular fibers"],"a":3,"e":"D. i.e. Internal circular fibres Involuantry internal anal sphincter is formed by thickening of circular muscle layer (i.e. circular layer of muscularis externa, a smooth muscle) of upper end (2/3 or 3/4) of anal canal. This sphincter remains in the state of tonic contraction most of the time to maintain resting tone or pressures (-90 cm H20) & to prevent leakage of fluid or flatus. Its contraction (tonus) is maintained by sympathetic fibers from superior rectal (periarterial) and hypogastric plexuses; and inhibited (i.e. sphincter relaxed) by parasympathetic pelvic splanchnic nerves.","pyqMatches":[{"year":"2015","no":55,"q":"Internal anal sphincter is a apart of:","o":["Puborectalis muscle","Deep perineal muscles","Internal longitudinal fibers","Internal circular fibers"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (38, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 38, '{"id":38,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":38,"q":"During incision & drainage of ischiorectal abscess, which nerve is/are affected/injured:","o":["Superior rectal nerve","Inferior rectal nerve","Superior gluteal nerve","Inferior gluteal nerve"],"a":1,"e":"B i.e. Inferior rectal nerve Through a posterior horse shoe shaped recess both ischiorectal fossae are connected behind the anal canal; so a unilateral abscess may become bilateral. During dissection of ischio rectal fossa, inferior rectal, pudendal, posterior scrotal or labial nerve & vessels along with perforating branches of S2-S3 and perineal branches of S4 nerve may get damaged.","pyqMatches":[{"year":"2012","no":77,"q":"During incision & drainage of ischiorectal abscess, which nerve is/are affected/injured:","o":["Superior rectal nerve","Inferior rectal nerve","Superior gluteal nerve","Inferior gluteal nerve"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (39, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 39, '{"id":39,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":39,"q":"Which structure(s) passes behind the inguinal ligament:","o":["Femoral branch of genitofemoral nerve","Femoral vein","Psoas major","All"],"a":3,"e":"A i.e. Femoral branch of genitofemoral nerve; B i.e. Femoral vein ; C i.e. Psoas major","pyqMatches":[{"year":"2012","no":45,"q":"Which structure(s) passes behind the inguinal ligament:","o":["Femoral branch of genitofemoral nerve","Femoral vein","Psoas major","All"],"a":3,"source":"NEET_2012_Paper.pdf"},{"year":"2015","no":24,"q":"Which structure(s) passes behind the inguinal ligament:","o":["Femoral branch of genitofemoral nerve","Femoral vein","Psoas major","All"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2012","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (40, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 40, '{"id":40,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":40,"q":"Structure crossing dorsal surface of ischial spine are A/E :","o":["Internal pudendal vessel","Pudendal nerve","Obturator nerve","Nerve to obturator internus"],"a":2,"e":"C. i.e. Obturator nerve Psoas major, iliacus & pectineus muscles, femoral vessels and nerve, femoral branch of genitofemoral nerve, lateral cutaneous nerve of thigh and lymphatics pass below inguinal ligament. ''PIN'' structures i.e. Pudendal nerve, Internal Pudendal vessels, Nerve to obturator internus come out of greater sciatic foramen, cross the dorsal surface of ischial spine & enter into lesser sciatic foramen.","pyqMatches":[{"year":"2012","no":84,"q":"Structure crossing dorsal surface of ischial spine are A/E :","o":["Internal pudendal vessel","Pudendal nerve","Obturator nerve","Nerve to obturator internus"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (41, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 41, '{"id":41,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":41,"q":"The muscles attached to perineal body are A/E","o":["Ischiocavernosum","Bulbospongiosm","Superficial transverse perinea","Deep transverse perinea"],"a":0,"e":"A. i.e. Ischiocavernosus Ten muscles of the perineum converge and interlace in the perineal body - a) Two unpaired : (i) External anal sphincter, (ii) Fibres of longitudinal muscle coat of anal canal. b) Four paired:- (i) Bulbospongiosus, (ii) Superficial transverse perenei, (iii) Deep transversus perenei, (iv) levator ani, In females, sphincter urethrovaginalis is also attached here.","pyqMatches":[{"year":"2015","no":75,"q":"The muscles attached to perineal body are A/E","o":["Ischiocavernosum","Bulbospongiosm","Superficial transverse perinea","Deep transverse perinea"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (42, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 42, '{"id":42,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":42,"q":"All are components of Spermatic cord except :","o":["Poupart''s ligament","Genito-femoral nerve","Vas deferens","Pampiniform plexus"],"a":0,"e":"A i.e. Poupart''s ligament Poupart''s ligament is also called as inguinal ligament. It forms the base of inguinal canal. Constituents of spermatic cord are: Ductus deferens Testicular and cremasteric arteries, and the artery of the ductus deferens Pampiniform plexus of veins Lymph vessels from the testis Genital branch of the genitofemoral nerve and the sympathetic nerve plexus around the artery to the ductus deferens and visceral afferent nerve fibres. Remains of the processus vaginalis.","pyqMatches":[{"year":"2015","no":92,"q":"All are components of Spermatic cord except :","o":["Poupart''s ligament","Genito-femoral nerve","Vas deferens","Pampiniform plexus"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (43, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 43, '{"id":43,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":43,"q":"Shortest part of male urethra is :","o":["Prostatic","Membranous","Bulbar","Penile"],"a":1,"e":"B i.e. Membranous - Membranous urethra is shortest & Penile urethra is longest part. Prostatic urethra is widest & most dilatable portion & Urethral orifice f/19 membranous urethra is narrowest & least dilatable part","pyqMatches":[{"year":"2015","no":56,"q":"Shortest part of male urethra is :","o":["Prostatic","Membranous","Bulbar","Penile"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (44, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 44, '{"id":44,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":44,"q":"Posterior communicating artery a branch of","o":["Internal carotid","External carotid","Middle cerebral","Posterior superior cerebellar"],"a":0,"e":"A i.e. Internal carotid","pyqMatches":[{"year":"2012","no":95,"q":"Posterior communicating artery a branch of","o":["Internal carotid","External carotid","Middle cerebral","Posterior superior cerebellar"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (45, 'Anatomy', 'Abdomen', 'Moderate', 'Anatomy', 45, '{"id":45,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Moderate","source":"Anatomy","sourceNo":45,"q":"All are lateral branches of abdominal aorta, EXCEPT","o":["Right testicular artery","Left renal artery","Inferior mesenteric artery","Middle suprarenal artery"],"a":2,"e":"C. i.e. Inferior mesenteric artery Ovarian or Testicular artery is lateral branch of abdominal aorta and uterine artery is a branch of internal iliac artery (anterior division). Lateral branches of abdominal aorta are - Inferior phrenic, Middle Suprarenal, Renal & Gonadal (testicular or ovarian) arteries. Mnemonic - \"Inferior MS Ruin Gonads\"","pyqMatches":[{"year":"2012","no":127,"q":"All are lateral branches of abdominal aorta, EXCEPT","o":["Right testicular artery","Left renal artery","Inferior mesenteric artery","Middle suprarenal artery"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (46, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 46, '{"id":46,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":46,"q":"Arterial branches which supply the head and neck of the femur is/are:","o":["Medial circumflex artery","Lateral circumflex artery","Profunda femoris artery","All"],"a":3,"e":"A. i.e. Medial circumflex artery; B. i.e. Lateral circumflex artery; C. i.e. Profunda femoris artery Proximal femur (head & neck) is supplied by artery of ligamentum teres (branch of obturator artery), medial (main) & lateral circumflex femoral artery (both arise from profunda femoris artery, give rise to ascending cervical (+ metaphyseal) and retinacular (+ epiphyseal:lateral & inferior) arteries and form extracapsular & intracapsular​ subsynovial arterial rings","pyqMatches":[{"year":"2015","no":26,"q":"Arterial branches which supply the head and neck of the femur is/are:","o":["Medial circumflex artery","Lateral circumflex artery","Profunda femoris artery","All"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (47, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 47, '{"id":47,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":47,"q":"True about Corpus callosum :","o":["Unite far area of two sides of brain","Connect two frontal lobe","Unite two hemisphere","All"],"a":3,"e":"A i.e. Unite far area of two sides of brain; B i.e. Connect two frontal lobe ; C i.e. Unite two hemisphere","pyqMatches":[{"year":"2012","no":125,"q":"True about Corpus callosum :","o":["Unite far area of two sides of brain","Connect two frontal lobe","Unite two hemisphere","All"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (48, 'Anatomy', 'Miscellaneous', 'Moderate', 'Anatomy', 48, '{"id":48,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anatomy","sourceNo":48,"q":"All are neural plate inducers except","o":["Notochord appearance","High BMP","FGF upregulation","Prechordal mesoderm"],"a":1,"e":"B i.e. High BMP","pyqMatches":[{"year":"2012","no":544,"q":"All are neural plate inducers except","o":["Notochord appearance","High BMP","FGF upregulation","Prechordal mesoderm"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (49, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 49, '{"id":49,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":49,"q":"Structures derived from the neural crest are?","o":["Pia","Dental papillae","Adrenal medulla","All of the above"],"a":3,"e":"D i.e. All of the above","pyqMatches":[{"year":"2015","no":137,"q":"Structures derived from the neural crest are?","o":["Pia","Dental papillae","Adrenal medulla","All of the above"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (50, 'Anatomy', 'Thorax', 'Moderate', 'Anatomy', 50, '{"id":50,"subject":"Anatomy","chapter":"Thorax","difficulty":"Moderate","source":"Anatomy","sourceNo":50,"q":"Jelly formed around the heart tube during early development, contributes to the formation of:","o":["Pericardium","Mesocardium","Myocardium","Endocardium"],"a":2,"e":"C i.e. Myocardium Dorsal mesocardium forms transverse pericardial sinus; somatopleuric mesoderm forms parietal pericardium; splanchnopluric mesoderm forms myocardium & conduction system of hearts (i.e. Purkinje fibers) ; neural creast cells form subpulmonary infundibulum. Cardiac jelly forms endocardial cushion and myocardium","pyqMatches":[{"year":"2013","no":7,"q":"Jelly formed around the heart tube during early development, contributes to the formation of:","o":["Pericardium","Mesocardium","Myocardium","Endocardium"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (51, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 51, '{"id":51,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":51,"q":"Primary and secondary palates are divided by","o":["Greater palatine foramen","Canine teeth","Alveolar arch","Incisive foramen"],"a":3,"e":"D. i.e. Incisive foramen The incisive foramen is dividing landmark between the primary & secondary palateQ; and anterior & posterior cleft deformities","pyqMatches":[{"year":"2012","no":115,"q":"Primary and secondary palates are divided by","o":["Greater palatine foramen","Canine teeth","Alveolar arch","Incisive foramen"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (52, 'Anatomy', 'Abdomen', 'Hard', 'Anatomy', 52, '{"id":52,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Hard","source":"Anatomy","sourceNo":52,"q":"''Obstruction of Inferior vena cava'' presents :","o":["Paraumblical dilatation","Thoraco-epigastric dilatation","Oesophagus varies","Haemorrhoides"],"a":0,"e":":B A. Paraumbilicus vein dilation and B i.e. Thoraco-epigastric dilation The thoracoepigastric vein is unique in that it drains to both the Superior Vena Cava (SVC) and to the Inferior Vena Cava (IVC). Hence, it serves as an anastomotic caval-caval link between the two. Furthermore, the thoracoepigastric vein is connected to the portal vein via the paraumbilical vein and thereby serves as a portocaval anastomosis as well. When a patient experiences portal hypertension, there can be congestion (backup) of blood that enters into the caval system via the thoracoepigastric vein. When this occurs, there can be an externally visible dilation of the paraumbilical (and perhaps even the thoracoepigastric veins) which leads to the appearance of \"Caput Medusae\"","pyqMatches":[{"year":"2012","no":71,"q":"''Obstruction of Inferior vena cava'' presents :","o":["Paraumblical dilatation","Thoraco-epigastric dilatation","Oesophagus varies","Haemorrhoides"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (53, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 53, '{"id":53,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":53,"q":"The right suprarenal vein drains into the","o":["Inferior vena cava","Right renal vein","Right Gonadal vein","Left Renal vein"],"a":0,"e":"A i.e. Inferior vena cava Left testicular, ovarian or suprarenal vein usually drains into left renal vein, before entering the IVC Organ VeinDrain into Rt. Suprarenal gland Rt. Suprarenal veinIVC Lt. Suprarenal gland Lt. Suprarenal veinLeft Renal Vein Same is true for gonads (testis /ovary) i.e. Lt. Gonad (testis or ovary) Lt. Gonadal (testicular or ovarian) vein Left renal vein Rt. Gonad (testis or ovary) Rt. Gonadal (testicular or ovarian) vein IVC","pyqMatches":[{"year":"2015","no":58,"q":"The right suprarenal vein drains into the","o":["Inferior vena cava","Right renal vein","Right Gonadal vein","Left Renal vein"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (54, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 54, '{"id":54,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":54,"q":"True about the anatomy of great saphenous vein:","o":["Starts as a continuation of medial marginal vein","Ends of femoral vein 2.5 cm below the inguinal ligament","There are 2 - 5 valves below the knee.","Ascends 2.5 - 3 cm behind tibial malleolus"],"a":0,"e":"A i.e. Starts as continuation- of medial marginal vein","pyqMatches":[{"year":"2015","no":87,"q":"True about the anatomy of great saphenous vein:","o":["Starts as a continuation of medial marginal vein","Ends of femoral vein 2.5 cm below the inguinal ligament","There are 2 - 5 valves below the knee.","Ascends 2.5 - 3 cm behind tibial malleolus"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (55, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 55, '{"id":55,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":55,"q":"Lymphatic drainage of cervix is to","o":["Iliac lymph nodes","Para aortic lymph nodes","Superficial inguinal lymph nodes","Deep inguinal lymph nodes"],"a":0,"e":"A. i.e. Iliac lymph nodes","pyqMatches":[{"year":"2012","no":93,"q":"Lymphatic drainage of cervix is to","o":["Iliac lymph nodes","Para aortic lymph nodes","Superficial inguinal lymph nodes","Deep inguinal lymph nodes"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (56, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 56, '{"id":56,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":56,"q":"The thoracic duct crosses from the right to the left at the level of","o":["T12 vertebra","T 6 vertebra","T5 vertebra","T2 vertebra"],"a":2,"e":"C i.e. T5 vertebrae Thoracic duct begins as continuation of the upper end of the cisterna chyli near the lower border of T12 vertebra and enters the thorax through the aortic opening of diaphragm (at T12 ). It then ascends through the posterior mediastinum and at T5 level crosses from right side to the left side and ascends along left margin ofoesophagus to enter the neck","pyqMatches":[{"year":"2012","no":56,"q":"The thoracic duct crosses from the right to the left at the level of","o":["T12 vertebra","T 6 vertebra","T5 vertebra","T2 vertebra"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (57, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 57, '{"id":57,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":57,"q":"Which of the following prevents hyperextension of thigh","o":["Ischiofemoral ligament","Iliofemoral ligament","Patellofemoral ligament","Puboischial ligament"],"a":1,"e":"B. i.e. Iliofemoral ligament Hip extension is limited by the iliofemoral ligament, which passes over the front of the hip joint and connects the ilium (hip bone) to the femur (thigh bone). This ligament elongates when the pelvis is tilted backwards, restricting the distance the joint can be extended. The iliofemoral ligament also limits external (outward) rotation of the hip joint when flexed, and it restrains both internal (inward) and external rotation when the joint is extended","pyqMatches":[{"year":"2015","no":32,"q":"Which of the following prevents hyperextension of thigh","o":["Ischiofemoral ligament","Iliofemoral ligament","Patellofemoral ligament","Puboischial ligament"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (58, 'Anatomy', 'Head & Neck', 'Moderate', 'Anatomy', 58, '{"id":58,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Moderate","source":"Anatomy","sourceNo":58,"q":"Deltoid ligament is attached to all except:","o":["Medial malleolus","Medial cuneiform","spring ligament","sustentaculum tali"],"a":1,"e":"Ans. B i.e. Medial cuneiform Medial collateral ligament (deltoid ligament) attaches to the medial malleolus of the tibia and the navicular, talus, and calcaneus bones. This ligament prevents medial distraction (eversion) and excessive range of motion. It is subdivided into four parts: Tibionavicular part attaches the margin of the plantar calcaneonavicular ligament (spring ligament). Tibiocalcaneal part attaches to the sustentaculum tali of the calcaneus bone. Posterior tibiotalar part attaches to the medial side and medial tubercle of the talus. Anterior tibiotalar part attaches to the medial surface of the talus.","pyqMatches":[{"year":"2012","no":46,"q":"Deltoid ligament is attached to all except:","o":["Medial malleolus","Medial cuneiform","spring ligament","sustentaculum tali"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (59, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 59, '{"id":59,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":59,"q":"Ansa nephroni is lined by ?","o":["Columnar","Squamous epithelium","Cuboidal and columnar epithelium","Stratified squamous epithelium"],"a":1,"e":"B i.e. Squamous epithelium","pyqMatches":[{"year":"2016","no":28,"q":"Ansa nephroni is lined by ?","o":["Columnar","Squamous epithelium","Cuboidal and columnar epithelium","Stratified squamous epithelium"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (60, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 60, '{"id":60,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":60,"q":"Auerbachs plexus is present in the -","o":["Colon","Esophagus","Stomach","All of the above"],"a":3,"e":"All of the above","pyqMatches":[{"year":"2016","no":22,"q":"Auerbachs plexus is present in the","o":["Colon","Esophagus","Stomach","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (61, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 61, '{"id":61,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":61,"q":"Intercalated disc is present in:","o":["Cardiac muscle","Smooth muscle","Skeletal muscle","All"],"a":0,"e":"A. i.e. Cardiac muscle","pyqMatches":[{"year":"2015","no":281,"q":"Intercalated disc is present in:","o":["Cardiac muscle","Smooth muscle","Skeletal muscle","All"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (62, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 62, '{"id":62,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":62,"q":"Which is true about synovial joint ?","o":["Stability is inversely proportional to mobility","Hyaline cartilage covers articular surface of all synovial joints.","Metacarpo-phalangeal joint is a hinge joint","\"Cartilage usually divides the joint into two cavities\"."],"a":0,"e":"A i.e. Stability is inversely proportional to mobility","pyqMatches":[{"year":"2012","no":37,"q":"Which is true about synovial joint ?","o":["Stability is inversely proportional to mobility","Hyaline cartilage covers articular surface of all synovial joints.","Metacarpo-phalangeal joint is a hinge joint","\"Cartilage usually divides the joint into two cavities\"."],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (63, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 63, '{"id":63,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":63,"q":"What is the uppermost structure in left lung hilum?","o":["Pulmonary artery","Pulmonary vein","Bronchial artery","Left mainstem bronchus"],"a":0,"e":"A i.e., Pulmonary artery Arrangement of structures in the hilum is as follows - l. Anterior to posterior (same on both side) :-(i) Superior pulmonary (ii) Pulmonary artery, (iii) Bronchus","pyqMatches":[{"year":"2015","no":47,"q":"What is the uppermost structure in left lung hilum?","o":["Pulmonary artery","Pulmonary vein","Bronchial artery","Left mainstem bronchus"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (64, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 64, '{"id":64,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":64,"q":"Level of lower border of lung at mid axillary line is","o":["6th rib","8th rib","10th rib","12th rib"],"a":1,"e":"B i.e. 8th rib","pyqMatches":[{"year":"2012","no":61,"q":"Level of lower border of lung at mid axillary line is","o":["6th rib","8th rib","10th rib","12th rib"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (65, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 65, '{"id":65,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":65,"q":"True about anatomy of right ventricle:","o":["TV & PV Share fibrous continuity","More prominent trabeculation","Crista supraventricularis Separate Tricuspid valve & Pulmonary valve and Apex trabeculated both","All"],"a":3,"e":"All Correct Right ventricle is situated anteriorlyQ. As the anterior (sternocostal) surface of heart consists mainly of right ventricleQ with right atrium on its right and a narrow strip of left ventricle left border. The tip of left auricular appendage peeps over the to of this border.","pyqMatches":[{"year":"2015","no":53,"q":"True about anatomy of right ventricle:","o":["TV & PV Share fibrous continuity","More prominent trabeculation","Crista supraventricularis Separate Tricuspid valve & Pulmonary valve and Apex trabeculated both","All"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (66, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 66, '{"id":66,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":66,"q":"Which of the following is not supplied by the anterior division of mandibular nerve (V3)?","o":["Temporalis","Medial pterygoid","Lateral pterygoid","Masseter"],"a":1,"e":"B i.e. Medial pterygoid Temporalis, messeter and lateral pterygoid musclesQ are supplied by anterior division of mandibular nerve whereas medial pterygoid muscleQ is supplied by the main trunk of mandibular nerve.","pyqMatches":[{"year":"2012","no":106,"q":"Which of the following is not supplied by the anterior division of mandibular nerve (V3)?","o":["Temporalis","Medial pterygoid","Lateral pterygoid","Masseter"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (67, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 67, '{"id":67,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":67,"q":"Nerve supply of stapedius is:","o":["2nd nerve","3rd nerve","5th nerve","7th nerve"],"a":3,"e":"D. i.e. 7th nerve","pyqMatches":[{"year":"2015","no":98,"q":"Nerve supply of stapedius is:","o":["2nd nerve","3rd nerve","5th nerve","7th nerve"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (68, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 68, '{"id":68,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":68,"q":"Small muscles of hand are supplied by:","o":["C3","C4","C6","C5-7 , C-8 to T1"],"a":3,"e":"All small muscles of hand i.e. thener, hypothenar, interossei & lumbricals are supplied by median and ulnar nerves which originate from C5-7 and C8 and T1 nerves.","pyqMatches":[{"year":"2014","no":6,"q":"Small muscles of hand are supplied by:","o":["C3","C4","C6","C5-7 , C-8 to T1"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (69, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 69, '{"id":69,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":69,"q":"Nerve damaged due to lunate dislocation (in carpal tunnel):","o":["Median & ulnar","Median","Ulnar","Radial"],"a":1,"e":"B. i.e. Median nerve Common causes of median nerve palsy in carpal tunnel are carpal tunnel syndrome (most common) and Innate dislocation.","pyqMatches":[{"year":"2015","no":1487,"q":"Nerve damaged due to lunate dislocation (in carpal tunnel):","o":["Median & ulnar","Median","Ulnar","Radial"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (70, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 70, '{"id":70,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":70,"q":"Tibial nerve injury/palsy causes:","o":["Dorsiflexion of foot at ankle joint","Planter flexion of the foot at ankle joint","Loss of sensation of dorsum of foot","Paralysis of muscles of anterior compartment of leg"],"a":0,"e":"A i.e. Dorsiflexion of foot at ankle joint * Tibial nerve (the larger component of sciatic nerve) supplies all muscles of posterior compartment of leg (gastrocnemius, soleus, plantaris, popliteus, tibialis posterior, FHL & FDL) planti flexing the ankle & foot. Therefore, tibial nerve injury results in loss of planter flexion along with calcaneo-valgus attitude of foot (ie dorsiflexion & eversion d/t unopposed anterior compartment muscles). - Deep peroneal (fibular) nerve supplies all anterior leg compartment muscles (tibialis anterior, EHL, EDL, EDB, PT) dorsiflexing the ankle & foot. - Sole is supplied by medial & lateral plantar and sural branches of tibial nerveQ anteriorly (from medial to lateral) and calcaneal branches of tibial nerve0 posteriorly (i.e. over heel). - It then passes along lateral side of foot and little toeQ supplying the overlying skin. - Anterolateral aspect of leg, and dorsum of foot including 2\" - 4th zveb spacesQ are supplied by superficial peroneal nerve. - Whereas deep peroneal (fibular) nerve supplies 1st web space (i.e. adjacent sides of great and second toes)Q","pyqMatches":[{"year":"2012","no":48,"q":"Tibial nerve injury/palsy causes:","o":["Dorsiflexion of foot at ankle joint","Planter flexion of the foot at ankle joint","Loss of sensation of dorsum of foot","Paralysis of muscles of anterior compartment of leg"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (71, 'Anatomy', 'Lower Limb', 'Hard', 'Anatomy', 71, '{"id":71,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Hard","source":"Anatomy","sourceNo":71,"q":"A patient presents with defective adduction of the hip joint and pains in the hip and knee joint. Which nerve is involved","o":["Obturator nerve","Femoral nerve","Saphenous nerve","Sciatic nerve"],"a":0,"e":"A. i.e. Obturator nerve Adductors of thigh are mainly supplied by obturator nerveQ. A disease in hip joint may cause referred pain in knee & medial thigh because of their common nerve supply by obturator nerveQ.","pyqMatches":[{"year":"2015","no":21,"q":"A patient presents with defective adduction of the hip joint and pains in the hip and knee joint. Which nerve is involved","o":["Obturator nerve","Femoral nerve","Saphenous nerve","Sciatic nerve"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (72, 'Anatomy', 'Neuroanatomy', 'Moderate', 'Anatomy', 72, '{"id":72,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":72,"q":"All the following are characteristics of oculomotor nerve except:","o":["Carries parasympathetic nerve fibres","Supplies inferior oblique muscle","Enters orbit through the inferior orbital fissure","Causes constriction of pupil"],"a":2,"e":"C i.e. Enters orbit through the inferior orbital fissure Oculomotor nerve enters orbit through the superior orbital fissure. The visceral motor component controls parasympathetic innervation (nerves related to involuntary actions) of the ciliary muscles and constrictor papillae, aiding in accommodation and pupillary light reflexes. The III cranial nerve supplies all extraocular muscles except Lateral rectus and superior oblique muscle.","pyqMatches":[{"year":"2012","no":124,"q":"All the following are characteristics of oculomotor nerve except:","o":["Carries parasympathetic nerve fibres","Supplies inferior oblique muscle","Enters orbit through the inferior orbital fissure","Causes constriction of pupil"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (73, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 73, '{"id":73,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":73,"q":"Locking of knee joint can be caused by:","o":["Osgood Schlatter","Loose body in knee joint","Tuberculosis of knee","a and b both"],"a":3,"e":"Ans. is. d. a and b both Locking of knee joint (i.e. joint held in flexion) is seen in meniscus tear, loose body (d/t osteochondral fracture) and fractures of tibial spine Mechanism of Locking Normally the medial meniscus or at least its anterior movable portion glides slightly backwards towards the interior of joint as the knee is flexed. If the tibia is at the same time abducted (valgus) and the medial compartment of the knee thus opened up, the mobility of the meniscus is still further increased. Sudden medial rotation of femur on the fixed tibia forces the medial meniscus towards back of joint and causes medial ligament to become taut and it may undergo variety of transverse or oblique tear. The inner fragment slips into the interior of the joint and when , extension is attempted and the knee begins to screw home'' the fragment is nipped between the condyles and the joint is ''locked'' i.e. held in flexion.","pyqMatches":[{"year":"2012","no":44,"q":"Locking of knee joint can be caused by:","o":["Osgood Schlatter","Loose body in knee joint","Tuberculosis of knee","a and b both"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (74, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 74, '{"id":74,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":74,"q":"Primordial germ cells are derived from:","o":["Neural crest","Genital ridge","Somatopleuritic mesoderm","Yolk sac"],"a":3,"e":"Formation of primordial germ cells Structures derived from neural crest are neurons of spinal posterior (dorsal) nerve root ganglia, neurons of sensory ganglia of the 5 to 10th cranial nerves, neurons and satellite cells of sympathetic ganglia etc. In the region where testes is to develop, the germinal epithelium gets thickened and is known as genital ridge. The cells of germinal epithelium proliferate and forms sex cords which gets converted into medullary cords and finally gets canalized to form seminiferous tubules Chorion is formed by the parital/ somatopleuric extraembryonic mesoderm (on the inside) and the overlying Trophoblast The cells of the ovaries and the testes, from which germ cells are formed, are believed to be segregated early in the life of the embryo.","pyqMatches":[{"year":"2012","no":130,"q":"Primordial germ cells are derived from:","o":["Neural crest","Genital ridge","Somatopleuritic mesoderm","Yolk sac"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (75, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 75, '{"id":75,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":75,"q":"Ligamentum arteriosum is derived from:","o":["Ductus arteriosus","Ductus venosus","Ductus utriculosaccularis","Ductus reunions"],"a":0,"e":"Ans. A: Ductus arteriosus The ductus arteriosus represents the distal portion of the sixth left aortic arch and connects the left pulmonary artery to the beginning of the descending aorta. During fetal life, blood passes through it from the pulmonary artery to the aorta, thus bypassing the lungs. After birth, it normally constricts, later closes, and becomes the ligamentum arteriosum. A persistent patent ductus arteriosus results in high-pressure aortic blood passing into the pulmonary artery, which raises the pressure in the pulmonary circulation. A patent ductus arteriosus is life threatening and should be ligated and divided surgically.","pyqMatches":[{"year":"2015","no":50,"q":"Ligamentum arteriosum is derived from:","o":["Ductus arteriosus","Ductus venosus","Ductus utriculosaccularis","Ductus reunions"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (76, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 76, '{"id":76,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":76,"q":"Trigone of urinary bladder develops from:","o":["Mesoderm","Ectoderm","Endoderm of urachus","None of the above"],"a":0,"e":"With differential growth of the dorsal bladder wall, the ureters come to open through the lateral angles of the bladder, and the mesonephric ducts open close together in what will be the urethra. That part of the dorsal bladder wall marked off by the openings of these four ducts forms the trigone of the bladder. Thus, lining of the bladder over the trigone is mesodermal in origin; The smooth muscle of the bladder wall is derived from the splanchnopleuric mesoderm. The apex of the bladder is continuous with the allantois, which now becomes obliterated and forms a fibrous core, the urachus. The urachus persists throughout life as a ligament that runs from the apex of the bladder to the umbilicus and is called the median umbilical ligament o Linining epithelium of bladder mucosa is transitional epithelium. When empty mucosa is thrown into rugae except in trigone, where mucosa is smooth and firmly adherent. o just beneath the mucosa of trigone there is layer of smooth muscle, Trtgonal muscle of Bell which replaces the submucous coat in trigone area","pyqMatches":[{"year":"2014","no":63,"q":"Trigone of urinary bladder develops from:","o":["Mesoderm","Ectoderm","Endoderm of urachus","None of the above"],"a":0,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":76,"q":"Trigone of urinary bladder develops from:","o":["Mesoderm","Ectoderm","Endoderm of urachus","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (77, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 77, '{"id":77,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":77,"q":"Structure passes through upper triangular space:","o":["Profunda brachii","Anterior circumflex humeral artery","Posterior circumflex humeral artery","Circumflex scapular artery"],"a":3,"e":"Upper Quadrangular space It has the following boundaries: – the teres major inferiorly – the long head of the triceps laterally For the superior border, some sources list the teres minor, while others list the subscapularis. It contains the scapular circumflex vessels.","pyqMatches":[{"year":"2012","no":35,"q":"Structure passes through upper triangular space:","o":["Profunda brachii","Anterior circumflex humeral artery","Posterior circumflex humeral artery","Circumflex scapular artery"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (78, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 78, '{"id":78,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":78,"q":"Nerve roots involved in Erb''s palsy:","o":["C5, C6","C6, C7","C7,C8,T1","C5,C6,C7,C8,T1"],"a":0,"e":"Erb-Duchenne Palsy Upper lesions of the brachial plexus are injuries resulting from excessive displacement of the head to the opposite side and depression of the shoulder on the same side. This causes excessive traction or even tearing of C5 and C6 roots of the plexus. It occurs in the newborn during a difficult delivery or in adults after a blow to or fall on the shoulder. The suprascapular nerve, the nerve to the subclavius, and the musculocutaneous and axillary nerves all possess nerve fibers derived from C5 and C6 roots and will therefore be functionless. The following muscles will consequently be paralyzed: the supraspinatus (abductor of the shoulder) and infraspinatus (lateral rotator of the shoulder); the subclavius (depresses the clavicle); the biceps brachii (supinator of the forearm, flexor of the elbow, weak flexor of the shoulder) and the greater part of the brachialis (flexor of the elbow) and the coracobrachialis (flexes the shoulder); and the deltoid (abductor of the shoulder) and the teres minor (lateral rotator of the shoulder). Thus, the limb will hang limply by the side, medially rotated by the unopposed sternocostal part of the pectoralis major; the forearm will be pronated because of loss of the action of the biceps. The position of the upper limb in this condition has been likened to that of a porter or waiter hinting for a tip In addition there will be a that of a porter or waiter hinting for a tip. In addition, there will be a loss of sensation down the lateral side of the arm. Treatment The three most common treatments from Erb''s Palsy are: Nerve transfers (usually from the opposite leg), subscapularis releases and latissimus dorsi tendon transfers.","pyqMatches":[{"year":"2015","no":2,"q":"Nerve roots involved in Erb''s palsy:","o":["C5, C6","C6, C7","C7,C8,T1","C5,C6,C7,C8,T1"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (79, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 79, '{"id":79,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":79,"q":"Structure passing deep to flexor retinaculum at wrist:","o":["Ulnar nerve","Median nerve","Radial nerve","Ulnar artery"],"a":1,"e":"The flexor retinaculum stretches across the front of the wrist and converts the concave anterior surface of the hand into an osteofascial tunnel, the carpal tunnel, for the passage of: The median nerve Flexor tendons of the thumb (flexor pollicis longus ) and fingers (flexor digitorum superficialis and profundus). Radial and the ulnar bursa It is attached medially to the pisiform bone and the hook of the hamate and laterally to the tubercle of the scaphoid and the trapezium bones. The attachment to the trapezium consists of superficial and deep parts and forms a synovial-lined tunnel for passage of the tendon of the flexor carpi radialis. The lower border is attached to the palmar aponeurosis.","pyqMatches":[{"year":"2016","no":38,"q":"Structure passing deep to flexor retinaculum at wrist:","o":["Ulnar nerve","Median nerve","Radial nerve","Ulnar artery"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (80, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 80, '{"id":80,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":80,"q":"Azygous vein drains into:","o":["Right subcostal vein","Superior vena cava","Braciocephalic","Right ascending lumbar vein"],"a":1,"e":"The origin of the azygos vein is variable. It is often formed by the union of the right ascending lumbar vein and the right subcostal vein. It ascends through the aortic opening in the diaphragm on the right side of the aorta to the level of the fifth thoracic vertebra. Here it arches forward above the root of the right lung to empty into the posterior surface of the superior vena cava. The azygos vein has numerous tributaries, including the fifth to eleventh right posterior intercostal veins, the right superior intercostal vein, the hemiazygos and the accessory hemiazygos veins, and numerous esophageal, mediastinal and pericardial veins.","pyqMatches":[{"year":"2015","no":34,"q":"Azygous vein drains into:","o":["Right subcostal vein","Superior vena cava","Braciocephalic","Right ascending lumbar vein"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (81, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 81, '{"id":81,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":81,"q":"Arch of aorta begins and ends at which level:","o":["T2","T3","T4","T5"],"a":2,"e":"The arch of the aorta (Transverse Aorta) begins at the level of the upper border of the second sternocostal articulation of the right side, and runs at first upward, backward, and to the left in front of the trachea; it is then directed backward on the left side of the trachea and finally passes downward on the left side of the body of the fourth thoracic vertebra, at the lower border of which it becomes continuous with the descending aorta.","pyqMatches":[{"year":"2015","no":35,"q":"Arch of aorta begins and ends at which level:","o":["T2","T3","T4","T5"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (82, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 82, '{"id":82,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":82,"q":"Azygos vein drains into:","o":["Left brachiocephalic vein","Inferior vena cava","Superior vena cava","Right brachiocephalic vein"],"a":2,"e":"The azygos vein ends by joining the posterior aspect of the superior vena cava The Azygos Vein The azygos vein connects the superior and inferior venae cavae, either directly by joining the IVC or indirectly by the hemiazygos and accessory hemiazygos veins. The azygos vein drains blood from the posterior walls of the thorax and abdomen. It ascends in the posterior mediastinum It is covered anteriorly by the oesophagus as it passes posterior to the root of the right lung. It then arches over the superior aspect of this root to join the SVC. In addition to the posterior intercostal veins, the azygos vein communicates with the vertebral venous plexuses. This vein also receives the mediastinal, oesophageal, and bronchial veins.","pyqMatches":[{"year":"2012","no":64,"q":"Azygos vein drains into:","o":["Left brachiocephalic vein","Inferior vena cava","Superior vena cava","Right brachiocephalic vein"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (83, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 83, '{"id":83,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":83,"q":"Vein used in bypass Surgery:","o":["Great saphenous vein","Short saphenous vein","Femoral vein","Brachial vein"],"a":0,"e":"In patients with occlusive coronary disease caused by atherosclerosis, the diseased arterial segment can be bypassed by inserting a graft consisting of a portion of the great saphenous vein. The venous segment is reversed so that its valves do not obstruct the arterial flow. Following removal of the great saphenous vein at the donor site, the superficial venous blood ascends the lower limb by passing through perforating veins and entering the deep veins. The great saphenous vein can also be used to bypass obstructions of the brachial or femoral arteries.","pyqMatches":[{"year":"2012","no":1103,"q":"Vein used in bypass Surgery:","o":["Great saphenous vein","Short saphenous vein","Femoral vein","Brachial vein"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (84, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 84, '{"id":84,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":84,"q":"Superficial inguinal ring is a defect in the:","o":["Internal oblique aponeurosis","External oblique aponeurosis","Transverse abdominis aponeurosis","Internal oblique muscle"],"a":1,"e":"The inguinal canal is an oblique passage through the lower part of the anterior abdominal wall. The canal is about 1.5 in. (4 cm) long in the adult and extends from the deep inguinal ring, a hole in the fascia transversalis, downward and medially to the superficial inguinal ring, a hole in the aponeurosis of the external oblique muscle. In the males, it allows structures to pass to and from the testis to the abdomen. In females it allows the round ligament of the uterus to pass from the uterus to the labium majus.","pyqMatches":[{"year":"2015","no":91,"q":"Superficial inguinal ring is a defect in the:","o":["Internal oblique aponeurosis","External oblique aponeurosis","Transverse abdominis aponeurosis","Internal oblique muscle"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (85, 'Anatomy', 'Abdomen', 'Moderate', 'Anatomy', 85, '{"id":85,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Moderate","source":"Anatomy","sourceNo":85,"q":"True about fallopian tubes are all except :","o":["Lined by cuboidal epithelium","Isthmus is the narrower part of the tube that links to the uterus","Tubal ostium is the point where the tubal canal meets the peritoneal cavity","MUllerian ducts develops in females into the Fallopian tubes"],"a":0,"e":"The two uterine tubes are each about 4 in. (10 cm) long and lie in the upper border of the broad ligament. Each connects the peritoneal cavity in the region of the ovary with the cavity of the uterus. The uterine tube is divided into four parts: The infundibulum is the funnel-shaped lateral end that projects beyond the broad ligament and overlies the ovary. The tubal ostium is the point where the tubal canal meets the peritoneal cavity. The ampulla is the widest part of the tube. The isthmus is the narrowest part of the tube and lies just lateral to the uterus. The intramural part is the segment that pierces the uterine wall. Function The uterine tube receives the ovum from the ovary and provides a site where fertilization of the ovum can take place (usually in the ampulla). The inner mucous membrane of the uterine tube is lined by the ciliated columnar epithelium mixed with the nonciliated secretory cells or peg cells The Mullerian ducts develops in females into the fallopian tubes, uterus and vagina while the Wolffian ducts develops in males into uterus and vagina, while the Wolffian ducts develops in males into the epididymis and vas deferens","pyqMatches":[{"year":"2015","no":124,"q":"True about fallopian tubes are all except :","o":["Lined by cuboidal epithelium","Isthmus is the narrower part of the tube that links to the uterus","Tubal ostium is the point where the tubal canal meets the peritoneal cavity","MUllerian ducts develops in females into the Fallopian tubes"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (86, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 86, '{"id":86,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":86,"q":"Ovarian artery is a branch of:","o":["Renal artery","Internal iliac artery","Abdominal part of the aorta","External iliac artery"],"a":2,"e":"The ovarian artery arises from the abdominal part of the aorta at the level of the first lumbar vertebra. The artery is long and slender and passes downward and laterally behind the peritoneum. It crosses the external iliac artery at the pelvic inlet and enters the suspensory ligament of the ovary. It then passes into the broad ligament and enters the ovary by way of the mesovarium.","pyqMatches":[{"year":"2015","no":84,"q":"Ovarian artery is a branch of:","o":["Renal artery","Internal iliac artery","Abdominal part of the aorta","External iliac artery"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (87, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 87, '{"id":87,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":87,"q":"Parotid duct opens opposite to:","o":["Upper 1st molar","Upper 2nd molar","Upper 2nd premolar","Upper 1st premolar"],"a":1,"e":"Ans. B: Upper 2nd molar","pyqMatches":[{"year":"2012","no":116,"q":"Parotid duct opens opposite to:","o":["Upper 1st molar","Upper 2nd molar","Upper 2nd premolar","Upper 1st premolar"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (88, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 88, '{"id":88,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":88,"q":"Largest cranial nerve is:","o":["Trochlear","Trigeminal","Oculomotor","Vagus"],"a":1,"e":"Trigeminal Longest intracranial course Trochlear nerve Longest course overall and most widely distributed Vagus Smallest (thinnest) cranial nerve Trochlear nerve Largest (thickest) cranial nerve Trigeminal nerve The only cranial nerve arising from dorsal aspect Trochlear nerve Only cranial nerve decussating completely before emerging Trochlear nerve Cranial nerve most commonly involved in basal skull fracture Facial nerve Cranial nerve most commonlv involved in raised intracranial tension Abducent nerve Commonest cranial nerve affected in spinal anaesthesia Abducent nerve Cranial nerve most commonly involved in intracranial aneurysm Oculomotor nerve Cranial nerves carrying 3,7 , 9, 10 paraslrrnpathetic fibers","pyqMatches":[{"year":"2015","no":112,"q":"Largest cranial nerve is:","o":["Trochlear","Trigeminal","Oculomotor","Vagus"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (89, 'Anatomy', 'Neuroanatomy', 'Moderate', 'Anatomy', 89, '{"id":89,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":89,"q":"Nucleus ambiguus is not associated with which cranial nerve:","o":["X","XI","IX","XII"],"a":3,"e":"Ans. D: XII Nucleus Ambiguus Function: * Motor innervation of ipsilateral muscles of the soft palate, pharynx, larynx and upper esophagus. Pathway: * Axons of motor neurons in the nucleus ambiguus course with three cranial nerves: C.N. IX (glossopharyngeal), C.N. X (vagus), C.N. XI (the rostral or cranial portion of spinal accessory) to innervate striated muscles of the soft palate, pharynx, larynx and upper esophagus. Deficits: * Lesion of nucleus ambiguus results in atrophy (lower motor neuron) and paralysis of innervated muscles, producing nasal speech, dysphagia, dysphonia, and deviation of the uvula toward the opposite side (strong side). * No affection of the Sternocleidomastoid or Trapezius. These muscles are innervated by cells in the rostral spinal cord (caudal portion C.N. XI).","pyqMatches":[{"year":"2012","no":107,"q":"Nucleus ambiguus is not associated with which cranial nerve:","o":["X","XI","IX","XII"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (90, 'Anatomy', 'Upper Limb', 'Moderate', 'Anatomy', 90, '{"id":90,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Moderate","source":"Anatomy","sourceNo":90,"q":"Which of the following is not the part of ethmoid bone?","o":["Agger nasi","Crista galli","Uncinate process","Inferior turbinate"],"a":3,"e":"Ans. d. Inferior turbinate Inferior turbinate is not the part of ethmoid bone. `Lateral nasal wall has 3 bony projections called as turbinates or conchae. From below upwards, they are inferior, middle and superior turbinates. The inferior turbinate is a separate bone, while rest of the turbinates are part of ethmoidal labyrinths.'' The agger nasi air cells, are the most anterior ethmoidal air cells, lying anterolateral and inferior to the frontoethmoidal recess and anterior and above the attachment of the middle turbinate. They are located within the lacrimal bone and therefore have as lateral relations the orbit, the lacrimal sac and the nasolacrimal duct.'' The crista galli is a median ridge of bone that projects from the cribriform plate of the ethmoid bone. It is where the falx cerebri attaches anteriorly to the skull. The olfactory bulbs lie on either side of the crista galli on top of the cribriform plate.'' In the ethmoid bone, a curved lamina, the uncinate process, projects downward and backward from this part of the labyrinth; it forms a small part of the medial wall of the maxillary sinus, and articulates with the ethmoidal process of the inferior nasal concha.''","pyqMatches":[{"year":"2012","no":105,"q":"Which of the following is not the part of ethmoid bone?","o":["Agger nasi","Crista galli","Uncinate process","Inferior turbinate"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (91, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 91, '{"id":91,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":91,"q":"Meckel''s cave is related to ?","o":["Submandibular ganglion","Trigeminal ganglion","Otic ganglion","Pterygopalatine ganglion"],"a":1,"e":"Ans. is ''b'' i.e., Trigeminal ganglion Trigeminal ganglion (Gasserion ganglion or semilunar ganglion) lies in a dural pouch, the cavum trigeminale (Meckel''s cave).","pyqMatches":[{"year":"2014","no":72,"q":"Meckel''s cave is related to ?","o":["Submandibular ganglion","Trigeminal ganglion","Otic ganglion","Pterygopalatine ganglion"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (92, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 92, '{"id":92,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":92,"q":"Medulla oblongata is derived from ?","o":["Telencephalon","Diencephalon","Mesencephalon","Myelencephalon"],"a":3,"e":"Ans. is d i.e., Myelencephalon Nervous system develops from ectoderm (neuroectoderm). Nervous system develops from neural tube which in turn develops by process of neurulation, i.e. formation of neural plate and its infolding into neural tube. Structures formed from neural tube are :? A) From cranial part (enlarged cephalic part) Gives rise to brain. Developmental parts are : i) Forebrain (prosencephalon) Telencephalon : Cerebral hemisphere and lateral ventricle. Diencephalon : Optic cup and stalk (gives rise to retina), pituitary, thalamus, hypothalamus, epithalamus, pineal gland, and third ventricle. ii) Midbrain (mesencephalon) Cerebral aqueduct. iii) Hindbrain (rhombencephalon) Metencephalon : Cerebellum, pons Myelencephalon Medulla oblongata B) From caudal part Gives rise to spinal cord.","pyqMatches":[{"year":"2014","no":104,"q":"Medulla oblongata is derived from ?","o":["Telencephalon","Diencephalon","Mesencephalon","Myelencephalon"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (93, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 93, '{"id":93,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":93,"q":"Morula is how many celled -","o":["4","8","12","16"],"a":3,"e":"Ans. is ''d'' i.e., 16 At about 16 cells stage the blastomeres tightly align by the process of compaction to form a compact ball of cells called morula (mulberry). This process of compaction leads to segregation of cells into two groups :","pyqMatches":[{"year":"2014","no":105,"q":"Morula is how many celled","o":["4","8","12","16"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (94, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 94, '{"id":94,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":94,"q":"Anterior interosseous nerve is a branch of?","o":["Radial nerve","Median nerve","Ulnar nerve","Axillary nerve"],"a":1,"e":"Ans. is ''b'' i.e., Median nerve Anterior interosseous nerve is a branch of median nerve. Anterior interosseous artery is a branch of ulnar artery.","pyqMatches":[{"year":"2014","no":1,"q":"Anterior interosseous nerve is a branch of?","o":["Radial nerve","Median nerve","Ulnar nerve","Axillary nerve"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (95, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 95, '{"id":95,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":95,"q":"Olecranon process of ulna helps in formation of?","o":["Radial notch","Trochlear notch","Olecranon fossa","Coronoid fossa."],"a":1,"e":"Ans. is ''b'' i.e., Trochlear notch Inner surface of olecranon process forms trochlear notch for articulation of trochlea of humerus. Radial notch is seen in lateral part of upper end of shaft (not on olecronon). Olecranon fossa and coronoid fossa are part of lower end of humerus.","pyqMatches":[{"year":"2014","no":2,"q":"Olecranon process of ulna helps in formation of?","o":["Radial notch","Trochlear notch","Olecranon fossa","Coronoid fossa."],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (96, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 96, '{"id":96,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":96,"q":"True about cremasteric reflex?","o":["Afferent: genital branch of genitofemoral nerve","Efferent: genital branch of genitofermoral nerve","Efferent: femoral branch of genitofemoral nerve","Afferent: pudendal nerve"],"a":1,"e":"Ans. is ''b'' i.e., Efferent : genital branch of genitofemoral nerve","pyqMatches":[{"year":"2014","no":45,"q":"True about cremasteric reflex?","o":["Afferent: genital branch of genitofemoral nerve","Efferent: genital branch of genitofermoral nerve","Efferent: femoral branch of genitofemoral nerve","Afferent: pudendal nerve"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (97, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 97, '{"id":97,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":97,"q":"Longest spinous process is seen in ?","o":["C2","C4","C5","C7"],"a":3,"e":"Ans. is ''d'' i.e., C7 Cervical Vertebrae There are 7 cervical vertebrae of which 3-6 are typical and 1st, 2nd and 7th are atypical. Characteristic features of typical cervical vertebra are : - i. Foramen transversarium is present in the transverse process. Foramina transversaria of Cl to C6 vertebrae transmit vertebral artery, vertebral vein and sympathetic plexus, and that of C7 transmits only vertebral veins. i. Body is small and broad transversely (side to side). i. Spinous process is small and bifid. v. Vertebral foramen is large and triangular. v. Superior articular facet is directed backwards and upwards, and inferior facet is directed downwards and forwards. Articular process are placed horizontally, So that dislocation can occur without fracture. i. The anterior tubercle on transverse process of C6 vertebra is prominent and is called carotid tubercle or chaissagnac''s tubercle. It is related to common carotid artery which can be palpated against it. Erb''s point is opposite chassaignac''s tubercle. Cricoid cartilage is at same level (C6 vertebra). Important features of atypical vertebrae are : ?","pyqMatches":[{"year":"2014","no":73,"q":"Longest spinous process is seen in ?","o":["C2","C4","C5","C7"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (98, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 98, '{"id":98,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":98,"q":"Malleus and incus are derived from ?","o":["1st Arch","2nd Arch","3rd Arch","4th Arch"],"a":0,"e":"Ans. is ''a'' i.e., 1st Arch lst (mandibular arch):- Muscular Contribution:-Muscles of mastication, Anterior belly of the digastric, Mylohyoid, Tensor tympani, Tensor veli palatini. Skeletal Contributions:- Maxilla, mandible (only as a model for mandible ), Incus and malleus, Meckel''s cartilage, Ant. ligament of malleus, Sphenomandibular ligament. Nerve:- Trigeminal nerve (V2 and V3). Artery:- Maxillary artery, external carotid artery.","pyqMatches":[{"year":"2014","no":107,"q":"Malleus and incus are derived from ?","o":["1st Arch","2nd Arch","3rd Arch","4th Arch"],"a":0,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":143,"q":"Malleus and incus are derived from ?","o":["1st Arch","2nd Arch","3rd Arch","4th Arch"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (99, 'Anatomy', 'Thorax', 'Moderate', 'Anatomy', 99, '{"id":99,"subject":"Anatomy","chapter":"Thorax","difficulty":"Moderate","source":"Anatomy","sourceNo":99,"q":"First rib is not related to ?","o":["Sympathetic chain","Scalenus anterior","Suprapleural membrane","T2 Nerve"],"a":3,"e":"Ans. is `d'' i.e., T2 Nerve Anteriorly, the neck of the first rib is related to (from medial to lateral) :- (1) Sympathetic chain, (ii) Ist posterior intercostal vein, (iii) Supeior intercostal artery, and (iv) 1st thoracic nerve. These structures are between neck of first rib (posteriorly) and apex of lung (anteriorly). Following are attached to first rib :- Scalenus anterior, scalenus medius, subclavius, serratus anterior ( lst digitation), costo-clavicular ligament and suprapleural membrane.","pyqMatches":[{"year":"2014","no":34,"q":"First rib is not related to ?","o":["Sympathetic chain","Scalenus anterior","Suprapleural membrane","T2 Nerve"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (100, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 100, '{"id":100,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":100,"q":"Optic cup is derived from ?","o":["Neural ectoderm","Surface ectoderm","Mesoderm","Neural crest"],"a":0,"e":"Ans. is ''a'' i.e., Neural ectoderm","pyqMatches":[{"year":"2014","no":108,"q":"Optic cup is derived from ?","o":["Neural ectoderm","Surface ectoderm","Mesoderm","Neural crest"],"a":0,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":150,"q":"Optic cup is derived from ?","o":["Neural ectoderm","Surface ectoderm","Mesoderm","Neural crest"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (101, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 101, '{"id":101,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":101,"q":"Pyramidalis is supplied by ?","o":["Subcostal nerve","Ilioinguinal nerve","Iliohypogastric nerve","Genitofemoral nerve"],"a":0,"e":"Ans. is ''a'' i.e., Subcostal nerve","pyqMatches":[{"year":"2014","no":47,"q":"Pyramidalis is supplied by ?","o":["Subcostal nerve","Ilioinguinal nerve","Iliohypogastric nerve","Genitofemoral nerve"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (102, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 102, '{"id":102,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":102,"q":"Excretory system of kidney is derived from ?","o":["Ureteric bud","Mesonephros","Metanephros","None"],"a":2,"e":"Ans. is ''c'' i.e., Metanephros Development of kidney Ureteric bud (mesonephros) arise from mesonephric duct and gives rise to collecting system of kidney (renal pelvis, major and minor calyces, collecting tubule) and ureter. Metanephric mesoderm (blastema or metanephors) arise from nephrogenic cord which in turn is derived from intermediate mesoderm. It gives rise to excretory unit (nephron), i.e. glomeruli, PCT, Loop of henle and DCT.","pyqMatches":[{"year":"2014","no":110,"q":"Excretory system of kidney is derived from ?","o":["Ureteric bud","Mesonephros","Metanephros","None"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (103, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 103, '{"id":103,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":103,"q":"Derivative of vitelline vein?","o":["IVC","SVC","Ligamentum venosum","Ligamentum teres"],"a":0,"e":"Ans. is ''a'' i.e., IVC","pyqMatches":[{"year":"2014","no":112,"q":"Derivative of vitelline vein?","o":["IVC","SVC","Ligamentum venosum","Ligamentum teres"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (104, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 104, '{"id":104,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":104,"q":"Sternochondral joint is ?","o":["Primary cartilaginous","Secondary cartilaginous","Fibrous","Synovial"],"a":0,"e":"Ans. is ''a'' i.e., Primary cartilaginous Costochondral (sternochondral) joints are primary cartilaginous joints. Cartilaginous joints 1) Primary cartilaginous joints (synchondrosis, or hyaline cartilage joint) : These are :- i. Joint between epiphysis and diaphysis of a growing long bone, i.e. physis. i. Spheno-occipital joint i. 1st costosternal joint (1st chondrosternal joint) v. Costochondral joints 2) Secondary cartilaginous joints (Symphyses or fibrocartilaginous joints) : These are :- i. Symphysis pubis i. manubriosternal joint i. Symphysis menti v. Sacroccygeal joint v. intervertebral disc","pyqMatches":[{"year":"2014","no":128,"q":"Sternochondral joint is ?","o":["Primary cartilaginous","Secondary cartilaginous","Fibrous","Synovial"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (105, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 105, '{"id":105,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":105,"q":"Sweat gland near the lid margins","o":["Moll","Zeis","Meibomian","Krause"],"a":0,"e":"Ans. is ''a'' i.e., Moll Glands of Moll (Moll''s gland) are apocrine sweat glands just next to the eyelashes. Zeis glands are sebaceous glands near lid margins. Meibomian gland (tarsal glands) are specialized sebaceous gland at the rim of eyelids inside the tarsal plate. Krause''s glands are accessory lacrimal glands underneath the eyelid.","pyqMatches":[{"year":"2014","no":74,"q":"Sweat gland near the lid margins","o":["Moll","Zeis","Meibomian","Krause"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (106, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 106, '{"id":106,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":106,"q":"Anterior lymphatics from the nose drain into ?","o":["Pretracheal nodes","Submandibular nodes","Sublingual nodes","Superficial cervical nodes"],"a":1,"e":"Ans. is ''b'' i.e., Submandibular nodes Submandibular nodes These nodes lie deep to investing layer of deep cervical fascia in submandibular triangle, between the deep fascia and submandibular gland. These nodes receive afferents from centre of forehead; anterior part of nasal cavity; frontal, maxillary and ethmoidal air sinuses; inner canthus (medial angle of eye); whole of upper lip and anterior part of cheek with underlying gum and teeth; outer part of lower lip with lower gums and teeth excluding incisors; anterior two third of tongue excluding the tip; floor of mouth; and angle of mouth. These nodes also receives efferents of submental nodes. Submandibular nodes drain into (efferent) upper and lower deep cervical nodes.","pyqMatches":[{"year":"2014","no":75,"q":"Anterior lymphatics from the nose drain into ?","o":["Pretracheal nodes","Submandibular nodes","Sublingual nodes","Superficial cervical nodes"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (107, 'Anatomy', 'Abdomen', 'Moderate', 'Anatomy', 107, '{"id":107,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Moderate","source":"Anatomy","sourceNo":107,"q":"Appendices epiploicae is seen in all part of large intestine except -","o":["Sigmoid colon","Ascending colon","Caecum","Transverse colon"],"a":2,"e":"Ans. is ''c'' i.e., Caecum Small bags of peritoneum filled with fat, called appendices epiploicae are present over the surface of large intestine, except for appendix, caecum and rectum.","pyqMatches":[{"year":"2014","no":49,"q":"Appendices epiploicae is seen in all part of large intestine except","o":["Sigmoid colon","Ascending colon","Caecum","Transverse colon"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (108, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 108, '{"id":108,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":108,"q":"Innervated structures of joints are all except ?","o":["Synovium","Capsule","Articular cartilage","Ligaments"],"a":2,"e":"Ans. is ''c'' i.e., Articular cartilage Characteristic features of articular cartilage 1) Hyaline cartilage 2) No innervation (no nerve supply). 3) No blood supply (avascular). 4) No lymphatics 5) Only hyaline cartilage which has no perichondrium. 6) No ability to repair or regenerate itself.","pyqMatches":[{"year":"2014","no":129,"q":"Innervated structures of joints are all except ?","o":["Synovium","Capsule","Articular cartilage","Ligaments"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (109, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 109, '{"id":109,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":109,"q":"Not true about inferior extensor retinaculum?","o":["Y shaped","Superior slip attached to lower end of fibula","Inferior slip attached to deep fascia of sole","Lateral attached to calcaneum"],"a":1,"e":"Ans. is ''b'' i.e., Superior slip attached to the lower end of the fibula Inferior extensor retinaculum It is a Y-shaped band lying in front of the ankle joint. Attachments:- The stem of the inferior extensor retinaculum is attached to the upper surface of the calcaneus in front of sulcus calcanei. Passing medially, the stem divides into two bands. The upper band passes upwards and medially to be attached to tibial malleolus. The lower band extends downwards and medially to blend with plantar aponeurosis. Structures passing deep to it are : 1) Tibialis anterior tendon. 2) Extensor hallucis longus tendon. 3) Dorsalis pedis vessels. 4) The deep peroneal nerve. 5) Extensor digitorum longus tendons. 6) Peroneus Tertius tendon.","pyqMatches":[{"year":"2014","no":21,"q":"Not true about inferior extensor retinaculum?","o":["Y shaped","Superior slip attached to lower end of fibula","Inferior slip attached to deep fascia of sole","Lateral attached to calcaneum"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (110, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 110, '{"id":110,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":110,"q":"Inferior rectal artery is a branch of?","o":["Inferior mesenteric artery","Superior mesenteric artery","Coeliac trunk","Internal pudendal artery"],"a":3,"e":"Ans. is ''d'' i.e., Internal pudendal artery","pyqMatches":[{"year":"2014","no":50,"q":"Inferior rectal artery is a branch of?","o":["Inferior mesenteric artery","Superior mesenteric artery","Coeliac trunk","Internal pudendal artery"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (111, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 111, '{"id":111,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":111,"q":"Superficial epigastric artery is a branch of?","o":["Internal pudendal artery","External pudendal artery","Internal iliac artery","Femoral artery"],"a":3,"e":"Ans. is ''d'' i.e., Femoral artery Branches of femoral artery 1) Superficial :- Superficial external pudendal, superficial epigastric, superficial circumflex iliac. 2) Deep branches :- Profunda femoris, deep external pudendal, muscular branches, descending genicular branch (last branch in the adductor canal). Note: Superior epigastric artery is a branch of internal thoracic artery.","pyqMatches":[{"year":"2014","no":52,"q":"Superficial epigastric artery is a branch of?","o":["Internal pudendal artery","External pudendal artery","Internal iliac artery","Femoral artery"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (112, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 112, '{"id":112,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":112,"q":"Inferior epigastric vein drains into?","o":["Femoral vein","External iliac vein","Internal iliac vein","Internal pudendal vein"],"a":1,"e":"Ans. is ''b'' i.e., External iliac vein Inferior epigastric vein drains into External iliac vein. Superior epigastic vein drains into Internal thoracic vein.","pyqMatches":[{"year":"2014","no":53,"q":"Inferior epigastric vein drains into?","o":["Femoral vein","External iliac vein","Internal iliac vein","Internal pudendal vein"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (113, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 113, '{"id":113,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":113,"q":"Superior rectal vein drains into?","o":["Inferior mesenteric vein","External iliac vein","Internal iliac vein","Internal pudendal vein"],"a":0,"e":"Ans. is ''a'' i.e., Inferior mesenteric vein Superior rectal vein drains into inferior mesenteric vein. Inferior rectal vein drains into internal pudendal vein.","pyqMatches":[{"year":"2014","no":54,"q":"Superior rectal vein drains into?","o":["Inferior mesenteric vein","External iliac vein","Internal iliac vein","Internal pudendal vein"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (114, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 114, '{"id":114,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":114,"q":"Killian''s dehisence is seen in ?","o":["Oropharynx","Nasopharynx","Cricopharynx","Vocal cords"],"a":2,"e":"Ans. is ''c'' i.e., Cricopharynx Inferior constrictor muscle has two parts :- (i) Thyropharyngeous with oblique fibres, and (ii) Cricopharyngeous with transverse fibres. Between these two parts of inferior constrictor exists a potential gap called Killan''s dehiscence. It is also called the gateway to tear as perforation can occur at this site during esophagoscopy. It is also the site for herniation of pharyngeal mucosa in case of pharyngeal pouch.","pyqMatches":[{"year":"2014","no":76,"q":"Killian''s dehisence is seen in ?","o":["Oropharynx","Nasopharynx","Cricopharynx","Vocal cords"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (115, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 115, '{"id":115,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":115,"q":"Fossa incudis is related to ?","o":["Head of malleus","Long process of incus","Short process of incus","Foot process of stapes"],"a":2,"e":"Fossa incudis contains short process of Incus. Head of malleus is attached to epitympanum by ligament of head of malleus. Long process of incus is attached to head of stapes. Footplate of stapes lies over oval window.","pyqMatches":[{"year":"2014","no":77,"q":"Fossa incudis is related to ?","o":["Head of malleus","Long process of incus","Short process of incus","Foot process of stapes"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (116, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 116, '{"id":116,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":116,"q":"Unpaired laryngeal cartilage ?","o":["Arytenoid","Corniculate","Cuneiform","Epiglottis"],"a":3,"e":"The skeletal supports of larynx is provided by Six cartilages, 3 out of which are paired (so there are total 9 cartilages). i) Unpaired :- Thyroid, cricoid, epiglottis. ii) Paired :- Arytenoid, Corniculate, cuneiform.","pyqMatches":[{"year":"2014","no":78,"q":"Unpaired laryngeal cartilage ?","o":["Arytenoid","Corniculate","Cuneiform","Epiglottis"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (117, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 117, '{"id":117,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":117,"q":"Which is the only nerve which exits the brainstem on dorsal side ?","o":["Facial","Trigeminal","Trochlear","Abducent"],"a":2,"e":"Unique features of trochlear nerve are :? i) Most selender cranial nerve. ii) Only cranial nerve to emerge on the dorsal aspect of brain. iii) Only cranial nerve to undergo complete internal decussation before emerging i.e. right trochlear nerve arises from left trochlear nucleus and vice versa. iv) Has''longest intracranial course (Vagus nerve has overall longest course). v) Thinnest cranial nerve (smallest nerve in terms of the number of axons it contains).","pyqMatches":[{"year":"2014","no":79,"q":"Which is the only nerve which exits the brainstem on dorsal side ?","o":["Facial","Trigeminal","Trochlear","Abducent"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (118, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 118, '{"id":118,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":118,"q":"Ureteric bud arises from ?","o":["Paramesonephric Dut","Mullerian duct","Mesonephric duct","Mesonephric tubule"],"a":2,"e":"Genital duct system During 5th and 6th weeks, both male and females have two genital duct systems, deriverd from mesoderm :","pyqMatches":[{"year":"2014","no":111,"q":"Ureteric bud arises from ?","o":["Paramesonephric Dut","Mullerian duct","Mesonephric duct","Mesonephric tubule"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (119, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 119, '{"id":119,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":119,"q":"Pisiform articulates with -","o":["Scaphoid","Trapezium","Triquetral","Lunate"],"a":2,"e":"Triquetral","pyqMatches":[{"year":"2015","no":154,"q":"Pisiform articulates with","o":["Scaphoid","Trapezium","Triquetral","Lunate"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (120, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 120, '{"id":120,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":120,"q":"True about popliteus are all except?","o":["Flexor of knee","Intracapsular origin","Supplied by tibial nerve","Causes locking of knee"],"a":3,"e":"Popliteus Popliteus is a deep muscle of posterior compartment of leg. Features of popletius are - Origin Lateral surface of lateral condyle of femur, origin is intracapsular. Outer margin of lateral meniscus of knee. Insertion Posterior surface of shaft of tibia above soleal line. Nerve supply Tibial nerve Action Ulocks knee joint by lateral rotation of femur on tibia prior flexion. Accessory flexor of knee.","pyqMatches":[{"year":"2012","no":47,"q":"True about popliteus are all except?","o":["Flexor of knee","Intracapsular origin","Supplied by tibial nerve","Causes locking of knee"],"a":3,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":22,"q":"True about popliteus are all except?","o":["Flexor of knee","Intracapsular origin","Supplied by tibial nerve","Causes locking of knee"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (121, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 121, '{"id":121,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":121,"q":"1st carpometacarpal joint is?","o":["Pivot","Hinge","Ball and Socket","Saddle"],"a":3,"e":"Saddle","pyqMatches":[{"year":"2012","no":34,"q":"1st carpometacarpal joint is?","o":["Pivot","Hinge","Ball and Socket","Saddle"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (122, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 122, '{"id":122,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":122,"q":"Most common location of accessory spleen?","o":["Hilum of spleen","Greater omentum","Lesser omentum","None"],"a":0,"e":"Accessory spleen may be found at :- i) Hilum of spleen (most common site). ii) Tail of pancrease. iii) Derivatives of dorsal mesogastrium :- Greater omentum, gastrophrenic ligament, gastrosplenic ligament, linorenal ligament. iv) Broad ligament of uterus (in males) and spermatic cord (in female); both left side.","pyqMatches":[{"year":"2014","no":55,"q":"Most common location of accessory spleen?","o":["Hilum of spleen","Greater omentum","Lesser omentum","None"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (123, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 123, '{"id":123,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":123,"q":"Testis lies at deep inguinal ring upto ?","o":["4 months","5 months","7 months","9 months"],"a":2,"e":"The testes develop in relation to the lumbar region of the posterior abdominal wall. During fetal life, they gradually descend to the scrotum. They reach the iliac fossa during third month, and lie at the site of deep inguinal ring upto 7 month of intrauterine life. They pass through inguinal canal during seven month, and are normally in the scrotum by the end of eighth month.","pyqMatches":[{"year":"2014","no":114,"q":"Testis lies at deep inguinal ring upto ?","o":["4 months","5 months","7 months","9 months"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (124, 'Anatomy', 'Embryology', 'Moderate', 'Anatomy', 124, '{"id":124,"subject":"Anatomy","chapter":"Embryology","difficulty":"Moderate","source":"Anatomy","sourceNo":124,"q":"Not true about development of ovary ?","o":["Develops in genital ridge","Sex cords are derived from coelomic epithelium","Oocytes are mesodermal in origin","At birth ovary contains 2 million follicles"],"a":2,"e":"Development of ovary Coelomic epithelium on medial side of the mesonephros becomes thickened to form genital ridge, the site where ovary develops. Genital ridge is covered by germinal epithelium (previous coelomic epithelium). From these germinal epithelium, cords of cells (sex cords or medullary cords) proliferate and grow into the underlying mesoderm. Primordial germ cells which are developed from endodermal cells of hindgut (part of yolk sac), migrate to region of developing ovary (genital ridge area) and give rise to oocytes. The sex cords become broken up into small masses. The cells of each mass surround one oocyte to form primordial follicle. At birth each ovary contains about 2 million primary follicles.","pyqMatches":[{"year":"2014","no":113,"q":"Not true about development of ovary ?","o":["Develops in genital ridge","Sex cords are derived from coelomic epithelium","Oocytes are mesodermal in origin","At birth ovary contains 2 million follicles"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (125, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 125, '{"id":125,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":125,"q":"Root value of supinator jerk -","o":["C3 C4","C4C5","C5 C6","C8 T1"],"a":2,"e":"C5 C6","pyqMatches":[{"year":"2014","no":5,"q":"Root value of supinator jerk","o":["C3 C4","C4C5","C5 C6","C8 T1"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (126, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 126, '{"id":126,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":126,"q":"True regarding semitendinosus ?","o":["Supplied by common peroneal part of sciatic nerve","Proximal flashy distal thin","Distal flashy proximal thin","Proximal and distal thin middle fleshy"],"a":3,"e":"Semitendinosus is a fusiform (spinadle shaped) muscles with main mass in middle of it. It arises in thin tendon from ischial tuberosity and ends in a long tendon to insert on medial surface of proximal part of tibia. o It is supplied by tibial part of sciatic nerve.","pyqMatches":[{"year":"2014","no":23,"q":"True regarding semitendinosus ?","o":["Supplied by common peroneal part of sciatic nerve","Proximal flashy distal thin","Distal flashy proximal thin","Proximal and distal thin middle fleshy"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (127, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 127, '{"id":127,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":127,"q":"True about blood supply of scaphoid?","o":["Mainly through ulnar artery","Major supply from ventral surface","Major supply from dorsal surface","Proximal supply in antegrade fashion"],"a":2,"e":"Major blood supply (70-80%) of scaphoid comes through dorsal surface via dorsal branches of radial artery. These dorsal vessels enter the scaphoid at or just distal to waist area and supply the proximal pole in retrograde fashion.","pyqMatches":[{"year":"2014","no":18,"q":"True about blood supply of scaphoid?","o":["Mainly through ulnar artery","Major supply from ventral surface","Major supply from dorsal surface","Proximal supply in antegrade fashion"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (128, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 128, '{"id":128,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":128,"q":"Which of the following dorsiflexes the foot -","o":["Tibialis posterior","Tibialis anterior","Peroneus brevis","Extensor digitorum brevis"],"a":1,"e":"Tibialis anterior","pyqMatches":[{"year":"2014","no":24,"q":"Which of the following dorsiflexes the foot","o":["Tibialis posterior","Tibialis anterior","Peroneus brevis","Extensor digitorum brevis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (129, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 129, '{"id":129,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":129,"q":"Bare area of liver is related to -","o":["Aorta","Hepatic vein","Portal vein","Gall bladder"],"a":1,"e":"Hepatic vein Between two layers of coronary ligaments, there is a large triangular area in diaphragmatic surface of liver which is not covered by peritoneum. It is called ''bare area of liver''. It is related to inferior vena cava (IVC). The hepatic veins (usually three) leave the liver in bare area. This area is clinically important as it is a site where infection can spread from abdominal cavity to thoracic cavity.","pyqMatches":[{"year":"2014","no":57,"q":"Bare area of liver is related to","o":["Aorta","Hepatic vein","Portal vein","Gall bladder"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (130, 'Anatomy', 'Neuroanatomy', 'Moderate', 'Anatomy', 130, '{"id":130,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":130,"q":"Blood supply of putamen includes all except?","o":["Medial striate arteries","Lateral striate arteries","Anterior choroidal artery","Posterior communicating artery"],"a":3,"e":"Blood supply of basal ganglia Caudate nucleus and putamen are supplied by lateral and medial striate branches of anterior, medial and posterior cerebral arteries. Putamen receives additional supply from anterior choroidal artery. o Globus pallidus is supplied by lateral striate and anterior choroidal arteries.","pyqMatches":[{"year":"2014","no":80,"q":"Blood supply of putamen includes all except?","o":["Medial striate arteries","Lateral striate arteries","Anterior choroidal artery","Posterior communicating artery"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (131, 'Anatomy', 'Embryology', 'Moderate', 'Anatomy', 131, '{"id":131,"subject":"Anatomy","chapter":"Embryology","difficulty":"Moderate","source":"Anatomy","sourceNo":131,"q":"True about notochord are all except?","o":["Defines axis of embryo","Serves as primary inductor","Derived from hypoblast","Remains as nucleus pulposus"],"a":2,"e":"Notochord is a bud like structure formed by epiblast cells extending from cranial end of primitive streak to caudal end of prochordal plate, in between the ectoderm and endoderm. Siginificances of notochord includes following :- i. It defines the axis of embryo. i. It functions as the primary inductor, inducing the overlying ectoderm to develop into neural plate (the primordium of CNS). i. It serves as the basis for development of axial skeleton. The notochord is an intricate structure around which vertebral column is formed and indicates future site of vertebral bodies. However, the notochord does not give rise to vertebral column, after development of vertebral bodies, the notochord degenerates and disappears, but parts of it persist as the nucleus pulposus of intervertebral disc.","pyqMatches":[{"year":"2014","no":116,"q":"True about notochord are all except?","o":["Defines axis of embryo","Serves as primary inductor","Derived from hypoblast","Remains as nucleus pulposus"],"a":2,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":136,"q":"True about notochord are all except?","o":["Defines axis of embryo","Serves as primary inductor","Derived from hypoblast","Remains as nucleus pulposus"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (132, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 132, '{"id":132,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":132,"q":"Length of Eustachian tube?","o":["12 mm","24mm","36mm","48mm"],"a":2,"e":"Length of Eustachian tube is 36 mm. (reached by the age of 7 years) Lateral third (i.e. 12 mm) is bony. Medial 2/3 (i.e. 24 mm) is fibrocartilaginous.","pyqMatches":[{"year":"2014","no":82,"q":"Length of Eustachian tube?","o":["12 mm","24mm","36mm","48mm"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (133, 'Anatomy', 'Neuroanatomy', 'Moderate', 'Anatomy', 133, '{"id":133,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":133,"q":"Right coronary artery supplies all, except?","o":["Anterior 2/3 of ventricular septum","SA node","AV node","LBB"],"a":0,"e":"Right coronary artery supplies * SA node (in 65%), * whole conducting system (AV bundle, bundle of his, part of left bundle branch) except RBB and part of left branch of AV bundle, * posterior part of ventricular septum, * most of right ventricle except small part adjoining anterior interventricular groove and small part of left ventricle adjoining posterior interventricular groove. Left coronary artery supplies * most of the left atrium, * most of the left ventricle including apex, * small part of right ventricle odjoining anterior interventricular septum, * anterior 2/3 of ventricular septum, * RBB, LBB * SA node in 35% of cases.","pyqMatches":[{"year":"2012","no":55,"q":"Right coronary artery supplies all, except?","o":["Anterior 2/3 of ventricular septum","SA node","AV node","LBB"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (134, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 134, '{"id":134,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":134,"q":"Bicipital aponeurosis lies over which structure in cubital fossa?","o":["Ulnar nerve","Radial nerve","Brachial artery","Anterior interosseous artery"],"a":2,"e":"Bicipital aponeurosis passes superficial to the brachial artery and median nerve. It lies deep to superficial veins. During venipuncture, the bicipital aponeurosis provides limited protection for brachial artery and median nerve.","pyqMatches":[{"year":"2014","no":7,"q":"Bicipital aponeurosis lies over which structure in cubital fossa?","o":["Ulnar nerve","Radial nerve","Brachial artery","Anterior interosseous artery"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (135, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 135, '{"id":135,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":135,"q":"Structure over bicipital aponeurosis in cubital fossa?","o":["Ulnar nerve","Radial nerve","Brachial artery","Veins"],"a":3,"e":"Veins","pyqMatches":[{"year":"2014","no":8,"q":"Structure over bicipital aponeurosis in cubital fossa?","o":["Ulnar nerve","Radial nerve","Brachial artery","Veins"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (136, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 136, '{"id":136,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":136,"q":"2ndpart of duodenum is derived from ?","o":["Foregut","Midgut","Both foregut & midgut","Hindgut"],"a":2,"e":"Both foregut & midgut","pyqMatches":[{"year":"2014","no":118,"q":"2ndpart of duodenum is derived from ?","o":["Foregut","Midgut","Both foregut & midgut","Hindgut"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (137, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 137, '{"id":137,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":137,"q":"Artery piercing the oblique popliteal ligament of knee -","o":["Superior genicular","Inferior genicular","Middle genicular","Popliteal"],"a":2,"e":"Middle genicular Oblique popliteal ligament is an expansion from the tendon of semimembranosus attachment to intercondylar line of femur. It is closely related to popliteal artery and is pierced by middle genicular vessels and nerve and the terminal part of the posterior division of the obturator nerve.","pyqMatches":[{"year":"2014","no":25,"q":"Artery piercing the oblique popliteal ligament of knee","o":["Superior genicular","Inferior genicular","Middle genicular","Popliteal"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (138, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 138, '{"id":138,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":138,"q":"True about circumcaval ureter ?","o":["Developmental anomaly of ureter","Ureter passes in front of IVC from lateral to medial","Mostly involves right ureter","Type 2 is more common"],"a":2,"e":"Circumcaval (retrocaval) ureter results from altered vasculature rather than ureteral development. Thus, preureteral vena-cava is more appropriate term. This disorder involves right ureter which passes behind IVC winding about and crosses in front of it from medial to lateral direction. The anomaly is divided into two types :? 1) Type 1 : It is more common and has hydronephrosis with a typically obstructing pattern demonstrating some degree of fish-hook shaped deformity of ureter. 2) Type 2 : It has lesser degree of hydronephrosis or not at all.","pyqMatches":[{"year":"2014","no":58,"q":"True about circumcaval ureter ?","o":["Developmental anomaly of ureter","Ureter passes in front of IVC from lateral to medial","Mostly involves right ureter","Type 2 is more common"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (139, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 139, '{"id":139,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":139,"q":"Which of the following is a retroperitoneal structure?","o":["Ileum","Jejunum","Ureter","Appendix"],"a":2,"e":"Ureter","pyqMatches":[{"year":"2014","no":59,"q":"Which of the following is a retroperitoneal structure?","o":["Ileum","Jejunum","Ureter","Appendix"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (140, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 140, '{"id":140,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":140,"q":"Falciparum ligament contains?","o":["Ligamentum venosus","Ligamentum teres","Linorenal ligament","None of the above"],"a":1,"e":"Peritoneal ligaments","pyqMatches":[{"year":"2014","no":60,"q":"Falciparum ligament contains?","o":["Ligamentum venosus","Ligamentum teres","Linorenal ligament","None of the above"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (141, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 141, '{"id":141,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":141,"q":"Parasympathetic supply to lacrimal glands are passed through ?","o":["Lesser petorsal nerve","Chorda tympani","Greater petorsal nerve","Lingual nerve"],"a":2,"e":"Greater petorsal nerve","pyqMatches":[{"year":"2014","no":83,"q":"Parasympathetic supply to lacrimal glands are passed through ?","o":["Lesser petorsal nerve","Chorda tympani","Greater petorsal nerve","Lingual nerve"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (142, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 142, '{"id":142,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":142,"q":"Anterior part of interventricular septum is supplied by -","o":["Right coronary artery","Left coronary artery","Posterior descending coronary artery","None"],"a":1,"e":"Anterior 2/3rd of septum is supplied by LCA and posterior 1/3rd is by RCA","pyqMatches":[{"year":"2015","no":40,"q":"Anterior part of interventricular septum is supplied by","o":["Right coronary artery","Left coronary artery","Posterior descending coronary artery","None"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (143, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 143, '{"id":143,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":143,"q":"Part of colon with no mesentery?","o":["Transverse colon","Sigmoid colon","Ascending colon","Rectum"],"a":2,"e":"Mesenteries in intestine 1) Mesentery proper :- Mesentery of small intestine (jejunum and ileum) is fan shaped double layered peritoneal fold which suspends the coils of jejunum and ileum. Mesentery has :? i) Attached border (root of mesentery) :- It is 15 cm long and extends from duodenojejunal flexure (on left side of L2) to upper part of right sacroiliac joint. Root of mesentery crosses following structures :- (i) 3rd part (horizontal part) of duodenum, (ii) abdominal aorta, (iii) IVC, (iv) right ureter, and (v) right psoas major. ii) Free border (intestinal border) :- It is 6 meters long and is attached to gut forming its visceral peritoneum (serous coat). 2) Transverse mesocolon :- It connects transverse colon to posterior abdominal wall and contains middle colic vessels. 3) Mesoappendix :- It connects the appendix to the ileal mesentery and contains appendicular vessels. 4) Sigmoid mesocolon :- It connects sigmoid colon to posterior pelvic wall and contains sigmoid vessels. 5) Mesorectum : It contains superior rectal vessels (artery & veins) i h h i b h l h i l d l h d l with their branches, lymphatic vessels and lymph nodes along superior rectal artery, and branches from inferior mesenteric plexus.","pyqMatches":[{"year":"2014","no":61,"q":"Part of colon with no mesentery?","o":["Transverse colon","Sigmoid colon","Ascending colon","Rectum"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (144, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 144, '{"id":144,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":144,"q":"True about right principal bronchus ?","o":["Narrower","Horizontal","Shorter","All are true"],"a":2,"e":"Features of right bronchus (in comparison to left bronchus) 1) Shorter 2) Wider 3) Vertical (in the line of trachea).","pyqMatches":[{"year":"2014","no":36,"q":"True about right principal bronchus ?","o":["Narrower","Horizontal","Shorter","All are true"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (145, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 145, '{"id":145,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":145,"q":"Stroma of cornea develops from ?","o":["Neural ectoderm","Surface ectoderm","Mesoderm","Neural crest"],"a":2,"e":"Corneal epithelium develops from Surface ectoderm. Corneal stroma develops from Mesoderm.","pyqMatches":[{"year":"2014","no":119,"q":"Stroma of cornea develops from ?","o":["Neural ectoderm","Surface ectoderm","Mesoderm","Neural crest"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (146, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 146, '{"id":146,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":146,"q":"Female genital tract develops from ?","o":["Mesonephric duct","Mesonephric tubules","Mullerian duct","None"],"a":2,"e":"Mesonephric duct (Wolffian duct) is the main genital duct in males as it gives rise to mainly male genital system. Paramesonephric duct (Mullerian duct) gives rise to mainly female genital tract","pyqMatches":[{"year":"2014","no":120,"q":"Female genital tract develops from ?","o":["Mesonephric duct","Mesonephric tubules","Mullerian duct","None"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (147, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 147, '{"id":147,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":147,"q":"Lateral dislocation of patella is prevented by ?","o":["Rectus femoris","Vastus intermedius","Vastus lateralis","Vastus medialis"],"a":3,"e":"Vastus medialis","pyqMatches":[{"year":"2014","no":26,"q":"Lateral dislocation of patella is prevented by ?","o":["Rectus femoris","Vastus intermedius","Vastus lateralis","Vastus medialis"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (148, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 148, '{"id":148,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":148,"q":"Onodi cells are seen in?","o":["Sphenoid sinus","Maxillary sinus","Anterior ethmoidal sinus","Posterior ethmoidal sinus"],"a":3,"e":"Ethmoidal sinuses are divided into two groups : A) Anterior group i) Anterior ethmoidal air cells Anterior ethmoidal air cells drain into- either the ethmoidal infundibulum or the frontonasal duct. Some air cells may invade the orbital floor. These are known as the Haller'' cells. ii) Middle ethmoidal air cells Also known as bullar sinuses. The middle ethmoidal air cells drain- into the middle meatus by one or more orifices on or above the ethmoidal bulla. B) Posterior group Posterior ethmoidal air cells usually drain- into the superior meatus. The posterior group lies very close to the optic canal and optic nerve. The Onodi cell is usually regarded as the most posterior ethmoid cell that pneumatizes lateral and superior to the sphenoid sinus and is intimately associated with the optic nerve.","pyqMatches":[{"year":"2014","no":84,"q":"Onodi cells are seen in?","o":["Sphenoid sinus","Maxillary sinus","Anterior ethmoidal sinus","Posterior ethmoidal sinus"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (149, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 149, '{"id":149,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":149,"q":"Which valve is present at opening of nasolacrimal duct?","o":["Hasner''s valve","Heister valve","Spiral valve","None"],"a":0,"e":"Nasolacrimal duct opens into inferior meatus and is closed by a mucosal flap called Hasner''s valve. Heister valve (spiral valve) is present in cyctic duct.","pyqMatches":[{"year":"2014","no":86,"q":"Which valve is present at opening of nasolacrimal duct?","o":["Hasner''s valve","Heister valve","Spiral valve","None"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (150, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 150, '{"id":150,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":150,"q":"Thoracic duct is formed by?","o":["Union of left subclavian and left internal jugular vein.","Union of brachiocephalic vein and internal jugular vein","Continuation of upper end of cisterna chyli","None of the above"],"a":2,"e":"Thoracic duct is also called as Pecquet duct. It is the largest lymphatic duct in body, about 45 cm (18 inches) long. It has a beaded appearance because of the presence of many valves in its lumen. Thoracic duct begins as a continuation of the upper end of the cisterna chyli near the lower border of T12 vertebra and enters the thorax through the aortic opening of diaphragm (at T12 ). It then ascends through the posterior mediastinum and at T5 level crosses from right side to the left side and ascends along left margin of oesophagus to enter the neck. At the level of C7 vertebrae, arches towards left side to open into left brachiocephalic vein at the angle of union of left subclavian and left internal jugular veins.","pyqMatches":[{"year":"2014","no":37,"q":"Thoracic duct is formed by?","o":["Union of left subclavian and left internal jugular vein.","Union of brachiocephalic vein and internal jugular vein","Continuation of upper end of cisterna chyli","None of the above"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (151, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 151, '{"id":151,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":151,"q":"Thoracic duct opens into ?","o":["Subclavian vein","Internal jugular vein","Right brachiocephalic vein","Left brachiocephalic vein"],"a":3,"e":"Left brachiocephalic vein","pyqMatches":[{"year":"2014","no":38,"q":"Thoracic duct opens into ?","o":["Subclavian vein","Internal jugular vein","Right brachiocephalic vein","Left brachiocephalic vein"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (152, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 152, '{"id":152,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":152,"q":"Submucosal plexus is ?","o":["Myenteric plexus","Auerbach''s plexus","Meissner''s plexus","Tympanic plexus"],"a":2,"e":"Innervation of GIT The gastrointestinal tract has a nervous system all its own called the enteric nervous system. It lies entirely in the wall of the gut, begining in the esophagus and extending all the way to the anus. The enteric nervous system is composed mainly of two plexus : - i) Myenteric plexus orAuerbach''s plexus ii) Meissner''s plexus or submucosal plexus Extrinsic nerves (Parasympathetic and sympathetic) are connected to both myenteric and submucosal plexuses. Enteric nervous system can function independently of these extrinsic nerves and these extrinsic nerves only modify the activity of the enteric nervous system. Therefore, peristalsis is present even if the intestine is deprived of extrinsic innervation. Parasympathetic stimulation enhances GI motility and secretion where as sympathetic stimulation inhibits motility and secretions.","pyqMatches":[{"year":"2014","no":130,"q":"Submucosal plexus is ?","o":["Myenteric plexus","Auerbach''s plexus","Meissner''s plexus","Tympanic plexus"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (153, 'Anatomy', 'Lower Limb', 'Moderate', 'Anatomy', 153, '{"id":153,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Moderate","source":"Anatomy","sourceNo":153,"q":"Femoral nerve supplies all except ?","o":["Pectineus","Sartorius","Vastus medialis","Obturator externus"],"a":3,"e":"Branches of femoral nerve are :?","pyqMatches":[{"year":"2015","no":27,"q":"Femoral nerve supplies all except ?","o":["Pectineus","Sartorius","Vastus medialis","Obturator externus"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (154, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 154, '{"id":154,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":154,"q":"Cribriform plate forms ?","o":["Roof of olfactory region","Floor of olfactory region","Nasal septum","All of the above"],"a":0,"e":"Internal nose Internal nose has following parts i) Nasal cavity proper :- Internal nose is divided into right and left nasal cavities by nasal septum. Each nasal cavity communicates with the exterior through naris or nostrils and with nasopharynx through posterior nasal aperture or posterior ?tares or choana. ii) Vestibule of nose :- Anterior and inferior part of the nasal cavity is lined by skin and is called vestibule of nose. It contains sebaceous glands, hair follicles and the hair called vibrissae. Each nasal cavity has a lateral wall, a medial wall (nasal septum), a roof, and a floor. The olfactory mucosa lines upper 1/3 of nasal cavity including the roof formed by cribriform plate, and medial and lateral wall up to the level of superior concha.","pyqMatches":[{"year":"2014","no":87,"q":"Cribriform plate forms ?","o":["Roof of olfactory region","Floor of olfactory region","Nasal septum","All of the above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (155, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 155, '{"id":155,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":155,"q":"Dental papilla give rise to ?","o":["Enamel","Dental cuticle","Tooth pulp","None"],"a":2,"e":"Repeat from previous sessions. See explanation-5 of session-1","pyqMatches":[{"year":"2014","no":106,"q":"Dental papilla give rise to ?","o":["Enamel","Dental cuticle","Tooth pulp","None"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (156, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 156, '{"id":156,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":156,"q":"True about iliotibial tract all except?","o":["Receives insertion of gluteus maximus","Derived from fascia lata","Inserted on lateral tibial condyle","None"],"a":3,"e":"Iliotibial Tract The fascia lata is thickened laterally where it forms a 5 cm wide band called the iliotibial tract. Superiorly the tract splits into two laters. The superficial lamina is attached to tubercle of iliac crest, and deep lamina to the capsule of hip joint. Inferiorly, the tract is attached to a smooth area on anterior surface of the lateral condyle of tibia. The importance of the iliotibial tract is as follows. a) Two important muscles are inserted into its upper part, between the superficial and deep laminae. These are the three-fourths part of the gluteus maximus; and the tensor fasciae latae. b) The iliotibial tract stabilizes the knee both in extension and in partial flexion; and is, therefore, used constantly during walking and running.","pyqMatches":[{"year":"2014","no":28,"q":"True about iliotibial tract all except?","o":["Receives insertion of gluteus maximus","Derived from fascia lata","Inserted on lateral tibial condyle","None"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (157, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 157, '{"id":157,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":157,"q":"False about sternocleidomastoid?","o":["Arises from sternum and clavicle","Insertes on mastoid process","Motor supply by spinal accessory nerve","Tilt the head on opposite side"],"a":3,"e":"Sternocleidomastoid tsternomastoidl Origin","pyqMatches":[{"year":"2014","no":90,"q":"False about sternocleidomastoid?","o":["Arises from sternum and clavicle","Insertes on mastoid process","Motor supply by spinal accessory nerve","Tilt the head on opposite side"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (158, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 158, '{"id":158,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":158,"q":"False regarding trigone of bladder ?","o":["Lined by transitional epithelium","Mucosa smooth and firmly adherent.","Internal urethral orifice lies at lateral angle of base","Developed from mesonephric duct"],"a":2,"e":"Trigone of bladder has following features : 1) Lined by transitional epithelium 2) Mucosa is smooth and firmly adherent 3) Ureters open at lateral angles of base and internal urethral orifice lies at apex. 4) Has Trigonal muscle of bell (smooth muscle layer just beneath mucosa). 5) Derived from absorbed part of mesonephric duct (Wolffian duct).","pyqMatches":[{"year":"2014","no":62,"q":"False regarding trigone of bladder ?","o":["Lined by transitional epithelium","Mucosa smooth and firmly adherent.","Internal urethral orifice lies at lateral angle of base","Developed from mesonephric duct"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (159, 'Anatomy', 'Head & Neck', 'Moderate', 'Anatomy', 159, '{"id":159,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Moderate","source":"Anatomy","sourceNo":159,"q":"Boundaries of quadrilateral space include all except?","o":["Teres major","Long head of triceps","Neck of humerus","Deltoid"],"a":3,"e":"Deltoid","pyqMatches":[{"year":"2014","no":10,"q":"Boundaries of quadrilateral space include all except?","o":["Teres major","Long head of triceps","Neck of humerus","Deltoid"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (160, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 160, '{"id":160,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":160,"q":"Lamina papyracea is between ?","o":["Optic nerve and orbit","Maxillary sinus and orbit","Ethmoid sinus and orbit","Cranial cavity and orbit"],"a":2,"e":"The thinnest portion of medial wall of orbit is the lamina papyracea which separates ethmoid sinuses from orbit. o Infection from ethmoidal sinus can easily breach this paper thin bone and affect the orbital contents.","pyqMatches":[{"year":"2014","no":89,"q":"Lamina papyracea is between ?","o":["Optic nerve and orbit","Maxillary sinus and orbit","Ethmoid sinus and orbit","Cranial cavity and orbit"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (161, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 161, '{"id":161,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":161,"q":"Glomus cells are derived from ?","o":["Surface ectoderm","Neuroectoderm","Mesoderm","Endoderm"],"a":1,"e":"Glomus cells are derived from neural crest which itself is derivative of neuroectoderm. Other derivates of neural crest are? a) Neural derivatives Sensory neurons of spinal dorsal root ganglia. Sympathetic chain ganglia and plexus (celiac/preaortic/renal ganglia, enteric plexus in GIT, i.e. Auerbachs and Meissner''s) Parasympathetic ganglia and plexus of GIT. Schwann cells of peripheral nerves, satellite cells of all ganglia. Adrenal medulla, chromaffin cells, para follicular C-cells of thyroid gland. Melanocytes and melanoblasts. b) Mesenchymal derivatives Dermal bones of skull : Frontal, parietal, temporal, nasal, vomer, palatine, mandible, maxillae. Leptomeninges : arachnoid and pia mater (Durameter is mesodermal). Dentine of teeth (odontoblasts). Eye : choroid, sclera, iris epithelium, pupillary muscles (sphincter and dilator pupillae, ciliary muscles). Pharyngeal arch cartilages. Retinal pigmented epithelium. Connective tissues of head including dermis, tendon, ligaments. Bulbar and conal ridges of heart.","pyqMatches":[{"year":"2014","no":121,"q":"Glomus cells are derived from ?","o":["Surface ectoderm","Neuroectoderm","Mesoderm","Endoderm"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (162, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 162, '{"id":162,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":162,"q":"Axillary artery is divided into three parts by?","o":["1st rib","Clavicle","Pectoralis minor muscle","Teres minor muscle"],"a":2,"e":"Axillary artery It is the main artery of upper limb. It begins at the level of outer border of first rib as a continuation of subclavian artery. It ends at the level of lower border of teres major to continue as brachial artery. The axillary artery is covered anteriorly by pectoralis minor, which divides it into three parts:? 1) First part :- This part is proximal to upper border of pectoralis minor, i.e. extends from outer border of first rib to upper border of pectoralis minor. The branch of first part is Superior thoracic artery. 2) Second part :- This part is behind pectoral is minor. It gives following branches. A) Thoracoacromial artery :- It pierces clavipectoral foscia and gives following branches :- (i) Acromial (ii) Pectoral, (iii) Clavicular and deltoid. B) Lateral thoracic artery 3) Third part :- This part is distal to lower border of pectoralis minor, i.e. extends from pectoralis minor (lower border) to teres major (lower border). It gives following branches ? A) Subscapular artery:- It gives off circumflex scapular artery and then continues us thoracodorsal artery. B) Anterior circumflex humeral artery. C) Posterior circumflex humeral artery. Anterior and posterior circumflex arteries (both are branches of 3rd part of axillary artery) forms anastomosis around surgical neck of humerus.","pyqMatches":[{"year":"2014","no":11,"q":"Axillary artery is divided into three parts by?","o":["1st rib","Clavicle","Pectoralis minor muscle","Teres minor muscle"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (163, 'Anatomy', 'Embryology', 'Moderate', 'Anatomy', 163, '{"id":163,"subject":"Anatomy","chapter":"Embryology","difficulty":"Moderate","source":"Anatomy","sourceNo":163,"q":"Tongue muscle which is not developed from occipital myotome ?","o":["Styloglossus","Hyoglossus","Genioglossus","Palatoglossus"],"a":3,"e":"DEVELOPMENT OF THE TONGUE :? I. Epithelium a) Ant 2/3 -- lingual swellings of 1st arch and tuberculum impar b) Post 1/3 -- large dorsal part of hypobranchial eminence, Le. 3rd arch c) Posterior most part -- small dorsal part of the hypobranchial eminence, i.e. 4th arch II. Muscles From occipital myotomes except palatoglossus which is derived from the 6th arch.","pyqMatches":[{"year":"2014","no":92,"q":"Tongue muscle which is not developed from occipital myotome ?","o":["Styloglossus","Hyoglossus","Genioglossus","Palatoglossus"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (164, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 164, '{"id":164,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":164,"q":"Korner''s septum is seen in ?","o":["Petrosquamous suture","Temporosquamous suture","Petromastoid suture","Frontozygomatic suture"],"a":0,"e":"Mastoid develops from squamous and petrous bone. Korner''s septum is persistence of petrosquamous suture in the form of a bony plate. Korner''s septum is surgically important as it may cause difficulty in locating the antrum and the deeper (ells, and thus lead to incomplete removal of disease at mastoidectomy. Mastoid antrum cannot be reached unless the Korners septum has been removed.","pyqMatches":[{"year":"2014","no":93,"q":"Korner''s septum is seen in ?","o":["Petrosquamous suture","Temporosquamous suture","Petromastoid suture","Frontozygomatic suture"],"a":0,"source":"NEET_2014_Paper.pdf"},{"year":"2016","no":922,"q":"Korner''s septum is seen in ?","o":["Petrosquamous suture","Temporosquamous suture","Petromastoid suture","Frontozygomatic suture"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2014","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (165, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 165, '{"id":165,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":165,"q":"False about tibia-fibula is ?","o":["Nutrient artery of tibia is from posterior tibial artery","Nutrient artery of fibula is from peroneal artery","Proximal end of tibia is related to common peroneal nerve","Tibia is the most common site of osteomyelitis"],"a":2,"e":"Common peroneal nerve is related to neck of fibula (not tibia). Nutrient artery of tibia is a branch of posterior tibial artery. Nutrient artery of fibula is a branch of peroneal artery. Tibia is the commonest site of osteomyelitis.","pyqMatches":[{"year":"2014","no":30,"q":"False about tibia-fibula is ?","o":["Nutrient artery of tibia is from posterior tibial artery","Nutrient artery of fibula is from peroneal artery","Proximal end of tibia is related to common peroneal nerve","Tibia is the most common site of osteomyelitis"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (166, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 166, '{"id":166,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":166,"q":"Posterior wall of axilla is formed by","o":["Pectoralis major","Pectoralis major","Subscapularis","Intercostal muscles"],"a":2,"e":"Axilla (armpit) The axilla is apyramidal space situated between the upper part of the arm and the chest wall. It resembles afour sided pyramid, and has following : (i) an apex (ii) a base (iii) four walls (anterior, posterior, medial and lateral).","pyqMatches":[{"year":"2014","no":12,"q":"Posterior wall of axilla is formed by","o":["Pectoralis major","Pectoralis major","Subscapularis","Intercostal muscles"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (167, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 167, '{"id":167,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":167,"q":"Intracapsular but extrasynovial is ?","o":["Long head of triceps","Long head of biceps","Short head of biceps","Medial head of biceps"],"a":1,"e":"Origin of long head of biceps is intracapsular but extrasynovial, enclosed by a prolongation of synovial membrane of shoulder joint.","pyqMatches":[{"year":"2014","no":14,"q":"Intracapsular but extrasynovial is ?","o":["Long head of triceps","Long head of biceps","Short head of biceps","Medial head of biceps"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (168, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 168, '{"id":168,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":168,"q":"Posterior relation of hilum of lung ?","o":["Azygous vein","SVC","Vagus nerve","Arch of aorta"],"a":2,"e":"Vagus nerve","pyqMatches":[{"year":"2014","no":39,"q":"Posterior relation of hilum of lung ?","o":["Azygous vein","SVC","Vagus nerve","Arch of aorta"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (169, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 169, '{"id":169,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":169,"q":"What is true about chorda tympani?","o":["Postganglionic sympathetic","Preganglionic sympathetic","Preganglionic parasympathetic","Postgalglionic parasympathetic"],"a":2,"e":"Chorda tympani arises from intratemporal part (in fallopion canal) of facial nerve. * It carries preganglionic secretomotor fibers (not postganglionic) to submandibular and sublingual glands. * It joins lingual nerve in infratemporal fossa. * It carries taste sensations from anterior 2/3 of tongue.","pyqMatches":[{"year":"2012","no":98,"q":"What is true about chorda tympani?","o":["Postganglionic sympathetic","Preganglionic sympathetic","Preganglionic parasympathetic","Postgalglionic parasympathetic"],"a":2,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":94,"q":"What is true about chorda tympani?","o":["Postganglionic sympathetic","Preganglionic sympathetic","Preganglionic parasympathetic","Postgalglionic parasympathetic"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (170, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 170, '{"id":170,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":170,"q":"Nephron is derived from ?","o":["Ureteric bud","Mesonephric duct","Metanephros","Mesonephros"],"a":2,"e":"Development of kidney Ureteric bud (mesonephros) arise from mesonephric duct and gives rise to collecting system of kidney (renal pelvis, major and minor calyces, collecting tubule) and ureter. Metanephric mesoderm (blastema or metanephors) arise from nephrogenic cord which in turn is derived from intermediate mesoderm. It gives rise to excretory unit (nephron), i.e. glomeruli, PCT, Loop of henle and DCT.","pyqMatches":[{"year":"2015","no":133,"q":"Nephron is derived from ?","o":["Ureteric bud","Mesonephric duct","Metanephros","Mesonephros"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (171, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 171, '{"id":171,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":171,"q":"Position of testis at 24-28 weeks of intrauterine life?","o":["Inguinal canal","Lumbar region","Superficial inguinal ring","Deep inguinal ring"],"a":3,"e":"Deep inguinal ring","pyqMatches":[{"year":"2014","no":115,"q":"Position of testis at 24-28 weeks of intrauterine life?","o":["Inguinal canal","Lumbar region","Superficial inguinal ring","Deep inguinal ring"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (172, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 172, '{"id":172,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":172,"q":"Watershed zone of large intestine ?","o":["Cecum","Ascending colon","Rectosigmoid","Transverse colon"],"a":2,"e":"There are areas of colon with poor blood supply resulting from incomplete anastomosis of marginal arteries. These are watershed areas of colon and include :","pyqMatches":[{"year":"2014","no":64,"q":"Watershed zone of large intestine ?","o":["Cecum","Ascending colon","Rectosigmoid","Transverse colon"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (173, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 173, '{"id":173,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":173,"q":"Skin over hypothenar eminence is supplied by?","o":["Radial nerve","Median nerve","Anterior interosseous nerve","Ulnar nerve"],"a":3,"e":"Ulnar nerve","pyqMatches":[{"year":"2014","no":135,"q":"Skin over hypothenar eminence is supplied by?","o":["Radial nerve","Median nerve","Anterior interosseous nerve","Ulnar nerve"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (174, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 174, '{"id":174,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":174,"q":"Cremasteric artery is a branch of?","o":["Internal pudendal artery","External pudendal artery","Inferior epigastric artery","Superior epigastric artery"],"a":2,"e":"Inferior epigastric artery","pyqMatches":[{"year":"2014","no":51,"q":"Cremasteric artery is a branch of?","o":["Internal pudendal artery","External pudendal artery","Inferior epigastric artery","Superior epigastric artery"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (175, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 175, '{"id":175,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":175,"q":"Ligament extending from cervix and vagina to lateral pelvic wall ?","o":["Broad ligament","Pubocervical ligament","Round ligament","Transverse cervical ligament"],"a":3,"e":"Transverse cervical ligaments of Mackenrodt are fan-shaped condensation of endopelvic fascia on each side of cervix above the levator ani and around uterine vessels. They connect lateral aspect of cervix and upper vaginal wall to lateral pelvic wall. They form a ''hammock'' that supports the uterus.","pyqMatches":[{"year":"2014","no":65,"q":"Ligament extending from cervix and vagina to lateral pelvic wall ?","o":["Broad ligament","Pubocervical ligament","Round ligament","Transverse cervical ligament"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (176, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 176, '{"id":176,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":176,"q":"Epithelium of vagina arises from?","o":["Ectoderm","Wolffian duct","Mesoderm","Mesonephric duct"],"a":2,"e":"Vagina is derived from two sources :-","pyqMatches":[{"year":"2014","no":122,"q":"Epithelium of vagina arises from?","o":["Ectoderm","Wolffian duct","Mesoderm","Mesonephric duct"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (177, 'Anatomy', 'Thorax', 'Moderate', 'Anatomy', 177, '{"id":177,"subject":"Anatomy","chapter":"Thorax","difficulty":"Moderate","source":"Anatomy","sourceNo":177,"q":"Not related to hilum of right lung?","o":["Azygous vein","Vagus nerve","SVC","Arch of aorta"],"a":3,"e":"Arch of aorta is related to left lung.","pyqMatches":[{"year":"2014","no":40,"q":"Not related to hilum of right lung?","o":["Azygous vein","Vagus nerve","SVC","Arch of aorta"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (178, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 178, '{"id":178,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":178,"q":"Anterior axillary fold is due to which muscle ?","o":["Pectoralis major","Pectoralis minor","Subscapularis","Teres major"],"a":0,"e":"Anterior axillary fold is rounded in shaped and is formed by pectoralis major (lower border). Posterior axillary fold is formed by teres major and latisimus dorsi.","pyqMatches":[{"year":"2014","no":13,"q":"Anterior axillary fold is due to which muscle ?","o":["Pectoralis major","Pectoralis minor","Subscapularis","Teres major"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (179, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 179, '{"id":179,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":179,"q":"True about Scarpa''s fascia ?","o":["Deep fascia of anterior abdominal wall","Also called Buck''s fascia","Attached to Iliotibial tract","Forms suspensory ligament of penis"],"a":3,"e":"Fascia of anterior abdominal wall A) Superficial fascia The superficial fascia of anterior abdominal wall (below the level of umblicus) is divided into : Superficial fatty layer (fascia of camper or camper''s fascia), and deep membraneus layer (fascia of scarpa or scarpa''s fascia). The fatty layer (fascia of camper) is continuous with the superficial fascia of adjoining part of the body. However, in the penis it is devoid of fat and in scrotum it is replaced by dartos muscle, i.e., in scrotum dartos muscle is present instead of fatty layer of superficial fascia. B) Deep fascia It is present in the form of a thin layer covering the muscles and their aponeuroses and large neurovascular structures. At superficial inguinal ring it continues over the spermatic cord as external spermatic fascia into scrotum and continue over the penis as deep fascia of penis (Buck''s fascia).","pyqMatches":[{"year":"2014","no":66,"q":"True about Scarpa''s fascia ?","o":["Deep fascia of anterior abdominal wall","Also called Buck''s fascia","Attached to Iliotibial tract","Forms suspensory ligament of penis"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (180, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 180, '{"id":180,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":180,"q":"Skeletal derivative of Ist arch ?","o":["Stapes","Hyoid","Maxilla","Laryngeal cortilages"],"a":2,"e":"Maxilla","pyqMatches":[{"year":"2014","no":124,"q":"Skeletal derivative of Ist arch ?","o":["Stapes","Hyoid","Maxilla","Laryngeal cortilages"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (181, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 181, '{"id":181,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":181,"q":"Which of the following is derived from Ist arch?","o":["Frontonasal process","Maxillary process","Mandibular process","Both maxillary & mandibular processes"],"a":3,"e":"Face is developed from five facial primordia appear as prominences of mesenchyme:?","pyqMatches":[{"year":"2014","no":123,"q":"Which of the following is derived from Ist arch?","o":["Frontonasal process","Maxillary process","Mandibular process","Both maxillary & mandibular processes"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (182, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 182, '{"id":182,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":182,"q":"Woodruff''s area is located at ?","o":["Antero-inferior part of nasal septum","Posteroinferior part of nasal septum","Superior part of nasal septum","Posteroinferior part of lateral nasal wall"],"a":3,"e":"Posteriorly on the lateral nasal wall is the area known as Woodruff''s area. It is situated under the posterior end of inferior turbinate. Sphenopalatine artery anastomoses with posterior pharyngeal artery, in this area.","pyqMatches":[{"year":"2014","no":96,"q":"Woodruff''s area is located at ?","o":["Antero-inferior part of nasal septum","Posteroinferior part of nasal septum","Superior part of nasal septum","Posteroinferior part of lateral nasal wall"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (183, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 183, '{"id":183,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":183,"q":"Scutum is present in middle ear ?","o":["Roof","Lateral wall","Medial wall","Floor"],"a":1,"e":"Lateral wall","pyqMatches":[{"year":"2014","no":97,"q":"Scutum is present in middle ear ?","o":["Roof","Lateral wall","Medial wall","Floor"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (184, 'Anatomy', 'Pelvis & Perineum', 'Moderate', 'Anatomy', 184, '{"id":184,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Moderate","source":"Anatomy","sourceNo":184,"q":"Ovarian fossa is formed by all except?","o":["Obliterated umbilical artery","Internal iliac artery","Ureter","Round ligament of ovary"],"a":3,"e":"Each ovary lies in ovarian fossa on lateral pelvic wall which is bounded :?","pyqMatches":[{"year":"2012","no":89,"q":"Ovarian fossa is formed by all except?","o":["Obliterated umbilical artery","Internal iliac artery","Ureter","Round ligament of ovary"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (185, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 185, '{"id":185,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":185,"q":"Appendices epiploicae is a feature of ?","o":["Duodenum","Stomach","Colon","Jejunum"],"a":2,"e":"Characteristic features of large intestine i) 3 longitudinal bands, formed by longitudinal muscle coat, called Taeniae coli. ii) Sacculation or haustration iii) Fat filled peritoneal pouches called appendices epiploicae. These are not found in appendix, caecum, and rectum. iv) Greater part is fixed except for appendix, transverse colon and sigmoid colon. v) Pyere''s patches (present in small intestine) are not present.","pyqMatches":[{"year":"2014","no":48,"q":"Appendices epiploicae is a feature of ?","o":["Duodenum","Stomach","Colon","Jejunum"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (186, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 186, '{"id":186,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":186,"q":"Nerve entering the inguinal canal through deep inguinal ring ?","o":["Ilioinguinal nerve","Pudendal nerve","Genital branch of genitofemoral","Superior rectal nerve"],"a":2,"e":"The spermatic cord in males and round ligament of uterus in females, enter the inguinal canal through the deep inguinal ring and pass out through superficial inguinal ring. Thus consituents of spermatic cord are also components of inguinal canal; these are ductus deferens (vas deferens), testicular artery, cremestric artery, artery to ductus deference, pampiniform plexus, lymphatics, sympathetic plexus, genital branch of genitofemoral nerve, remains of process vaginalis. Note: Ili oiguinal nerve enters inguinal canal through interval between external and internal oblique muscles (not through deep inguinal ring).","pyqMatches":[{"year":"2014","no":68,"q":"Nerve entering the inguinal canal through deep inguinal ring ?","o":["Ilioinguinal nerve","Pudendal nerve","Genital branch of genitofemoral","Superior rectal nerve"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (187, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 187, '{"id":187,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":187,"q":"How many lactiferous ducts open in nipple ?","o":["0 -10","15 -20","25 -50","50 -75"],"a":1,"e":"The nipple is pierced by 15-20 lectiferous ducts.","pyqMatches":[{"year":"2014","no":15,"q":"How many lactiferous ducts open in nipple ?","o":["0 -10","15 -20","25 -50","50 -75"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (188, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 188, '{"id":188,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":188,"q":"Optic cup give rise to ?","o":["Lens","Retina","Cornea","Sclera"],"a":1,"e":"Retina","pyqMatches":[{"year":"2014","no":109,"q":"Optic cup give rise to ?","o":["Lens","Retina","Cornea","Sclera"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (189, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 189, '{"id":189,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":189,"q":"Not a part of bony labyrinth?","o":["Cochlea","Vestibule","Utricle","Semicircular canal"],"a":2,"e":"The inner ear within the petrous part of temporal bone consists of a membranous labyrinth enclosed in a bony (osseous) labyrinth. So, inner ear has two parts : ? Bony labyrinth :- Cochlea, Vestibule, Semicircular canals. Membranous labyrinth :- Cochlear duct, utricle, Saccules, three semicircular ducts, and endolymphatic duct & sac.","pyqMatches":[{"year":"2014","no":98,"q":"Not a part of bony labyrinth?","o":["Cochlea","Vestibule","Utricle","Semicircular canal"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (190, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 190, '{"id":190,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":190,"q":"Lymphatic drainage of thyroid gland is mainly ?","o":["Sublingual nodes","Submandibular nodes","Deep cervical nodes","Submental nodes"],"a":2,"e":"Lymphatic drainage of thyroid Lymph from the upper part of the gland reaches the upper deep cervical lymph nodes either directly or through the prelaryngeal nodes. Lymph from the lower part of the gland drains to the lower deep cervical nodes directly, and also through the pretracheal and paratracheal nodes.","pyqMatches":[{"year":"2014","no":99,"q":"Lymphatic drainage of thyroid gland is mainly ?","o":["Sublingual nodes","Submandibular nodes","Deep cervical nodes","Submental nodes"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (191, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 191, '{"id":191,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":191,"q":"Hunter''s canal is seen in?","o":["Cubital fossa","Popliteal fossa","Thigh","Calf"],"a":2,"e":"Ans. is ''c'' i.e., Thigh","pyqMatches":[{"year":"2014","no":27,"q":"Hunter''s canal is seen in?","o":["Cubital fossa","Popliteal fossa","Thigh","Calf"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (192, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 192, '{"id":192,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":192,"q":"Organ of corti is situated in ?","o":["Basilar membrane","Utricle","Saccule","None of the above"],"a":0,"e":"Scala media (cochlear duct or membranous labyrinth) has 3 walls : - The basilar membrane, which supports the organ of corti. The Reissner''s membrane which separates it from the scala vestibuli. The stria vascularis which contains vascular epithelium and is concerned with secretion of endolymph.","pyqMatches":[{"year":"2014","no":100,"q":"Organ of corti is situated in ?","o":["Basilar membrane","Utricle","Saccule","None of the above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (193, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 193, '{"id":193,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":193,"q":"Initially, renal arteries are branches of ?","o":["Internal pudendal artery","External iliac artery","Common iliac artery","Aorta"],"a":2,"e":"Due to ascent of kidneys during development, the blood supply of kidney changes:? 1) Initially when the kidneys are in pelvis, the renal arteries are branches of common iliac arteries. 2) With progressive ascent, the arteries to kidneys are derived from different levels of aorta.","pyqMatches":[{"year":"2014","no":69,"q":"Initially, renal arteries are branches of ?","o":["Internal pudendal artery","External iliac artery","Common iliac artery","Aorta"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (194, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 194, '{"id":194,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":194,"q":"In a neonate, kidney is supplied by?","o":["Internal pudendal artery","External iliac artery","Common iliac artery","Aorta"],"a":3,"e":"Upto 5th week of intrauterine life, kidney is in lumbar region and renal arteries are branches of common iliac artery (see above explanation). After that, differential growth of abdominal wall causes the kidney to ascent to lumbar region. Adult position (lumbar region of abdomen) is attained by 9th week. Druing progressive ascent, the arteries to kidney are derived from different levels of aorta. After full ascent, definitive renal artery is branch of aorta at 2nd lumbar segment. Thus, neonatal kidney is supplied by aorta.","pyqMatches":[{"year":"2014","no":70,"q":"In a neonate, kidney is supplied by?","o":["Internal pudendal artery","External iliac artery","Common iliac artery","Aorta"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (195, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 195, '{"id":195,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":195,"q":"Hassall''s corpuscles are found in?","o":["Lymph nodes","Spleen","Liver","Thymus"],"a":3,"e":"The dominant feature of medulla of thymus is its epithelial components, which are onion like structures called Hassall''s Corpuscles, which have an intensely eosinophilic core of dead material,","pyqMatches":[{"year":"2014","no":131,"q":"Hassall''s corpuscles are found in?","o":["Lymph nodes","Spleen","Liver","Thymus"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (196, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 196, '{"id":196,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":196,"q":"Bronchopulmonary segments in right and left lungs respectively ?","o":["9, 11","11,9","10,10","8, 10"],"a":2,"e":"Each lung has 10 bronchopulmonary segments.","pyqMatches":[{"year":"2014","no":42,"q":"Bronchopulmonary segments in right and left lungs respectively ?","o":["9, 11","11,9","10,10","8, 10"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (197, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 197, '{"id":197,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":197,"q":"Vidian nerve is formed by union of?","o":["Superficial petrosal nerve and deep petrosal nerve","Greater petrosal nerve and superficial petrosal nerve","Greater petrosal nerve and deep petrosal nerve","Greater petrosal nerve and external petrosal nerve"],"a":2,"e":"Greater petorsal nerve units with deep petrosal nerve to form nerve to pterygoid canal (also called vidian nerve).","pyqMatches":[{"year":"2014","no":95,"q":"Vidian nerve is formed by union of?","o":["Superficial petrosal nerve and deep petrosal nerve","Greater petrosal nerve and superficial petrosal nerve","Greater petrosal nerve and deep petrosal nerve","Greater petrosal nerve and external petrosal nerve"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (198, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 198, '{"id":198,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":198,"q":"Structure related to deltopectoral groove ?","o":["Axillary artery","Cephalic vein","Baselic vein","Radial nerve"],"a":1,"e":"Ans. is b'' i.e., Cephalic vein Deltopectoral groove is a groove between deltoid muscle and pectoralis major muscle. It is traversed by cephalic vein","pyqMatches":[{"year":"2014","no":16,"q":"Structure related to deltopectoral groove ?","o":["Axillary artery","Cephalic vein","Baselic vein","Radial nerve"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (199, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 199, '{"id":199,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":199,"q":"3rd and 4th lumbrical (lateral two lumbricals) of foot are supplied by ?","o":["Medial plantar nerve","Lateral plantar nerve","Peroneal nerve","None of the above"],"a":1,"e":"Behind the medial malleolus, beneath the flexor retinaculum the tibial nerve divides into its two terminal branches : i) Medial plantar nerve :- It corresponds approximately to the median nerve in the hand as far as skin and muscle supplies are concerned. It supplies medial part of sole, plantar surface of medial 3rd A digits, and innervates flexor digitorum brevis, abductor hallucis, flexor hallucis brevis and the first lumbrical. ii) Lateral plantar nerve :- It correspods approximately to the ulnar nerve. It supplies the lateral part of sole, plantar surface of lateral digits and innervates flexor digitorum accesorius, abductor digiti minimi, flexor digiti minimi brevis, adductor hallucis, all intcrossei and 2nd,3rd,4th lumbricals.","pyqMatches":[{"year":"2014","no":19,"q":"3rd and 4th lumbrical (lateral two lumbricals) of foot are supplied by ?","o":["Medial plantar nerve","Lateral plantar nerve","Peroneal nerve","None of the above"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (200, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 200, '{"id":200,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":200,"q":"Which of the following is a derivative of paramesonephric duct in males ?","o":["Trigone of bladder","Paraphoron","Prostatic utricle","Gartner''s duct"],"a":2,"e":"Two structures are derived from paramesonephric duct in males :-","pyqMatches":[{"year":"2015","no":141,"q":"Which of the following is a derivative of paramesonephric duct in males ?","o":["Trigone of bladder","Paraphoron","Prostatic utricle","Gartner''s duct"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (201, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 201, '{"id":201,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":201,"q":"Floor of 4th ventricle has ?","o":["Infundibulum","Vagal triangle","Mammillary body","Tuber cincrium"],"a":1,"e":"Floor of 4th ventricle (Rhomboid fossa) It is diamond or rhomboidal shaped and is formed by posterior surface of pons (upper triangular part or pontine part) and dorsal surface of medulla (lower triangular part or medullary part) junction of pons and medulla forms intermediate part. Features of 4th ventricle are :? i. Median sulcus (a midline groove) divides the floor into two symmetrical halves. i. Medial eminence is present an each side of median sulcus. It presents facial colliculus formed by genu (recurving fibers) of facial nerve looping around abducent nucleus. Facial colliculus lies in pons (i.e. in pontine part of floor). i. Hypoglossal triangle overlying hypoglossal nucleus and vagal triangle overlying dorsal nucleus of vagus. Both of these triangle lie in the medulla (medullary part of floor). v. Vestibular area overlies vestibular nuclei, partly in pons and partly in medulla. v. Sulcus coeruleus, a bluish area due to presence of pigmented neurons containing substantia ferruginea. i. Superior and inferior favea.","pyqMatches":[{"year":"2014","no":101,"q":"Floor of 4th ventricle has ?","o":["Infundibulum","Vagal triangle","Mammillary body","Tuber cincrium"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (202, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 202, '{"id":202,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":202,"q":"Breast is a ?","o":["Endocrine gland","Modified sweat gland","Modified sehaceous gland","Holocrine gland"],"a":1,"e":"Breast is a modified sweat gland. It is apocrine type of sweat gland.","pyqMatches":[{"year":"2014","no":133,"q":"Breast is a ?","o":["Endocrine gland","Modified sweat gland","Modified sehaceous gland","Holocrine gland"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (203, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 203, '{"id":203,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":203,"q":"Nerve which loops around submandibular duct?","o":["Mandibular nerve","Lingual nerve","Hypoglossal nerve","Recurrent laryngeal nerve"],"a":1,"e":"Submandibular duct It is 5 cm long duct and runs forwards on hyoglossus, between lingual and hypoglossal nerves. At the anterior border of the hyoglossus muscle it is crossed by lingual nerve which loops around it. It opens into the floor of mouth, on the summit of the sublingual papilla at the side of frenulum of tongue.","pyqMatches":[{"year":"2014","no":103,"q":"Nerve which loops around submandibular duct?","o":["Mandibular nerve","Lingual nerve","Hypoglossal nerve","Recurrent laryngeal nerve"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (204, 'Anatomy', 'Miscellaneous', 'Moderate', 'Anatomy', 204, '{"id":204,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anatomy","sourceNo":204,"q":"At the level of Arch of aorta, the relationship of left vagus nerve and left phrenic nerve?","o":["Phrenic nerve anterior, vagus nerve posterior","Phrenic nerve posterior, vagus nerve anterior","Both in same plane anteroposteriorly","Variable in relationship"],"a":0,"e":"Phrenic nerve anterior, vagus nerve posterior","pyqMatches":[{"year":"2014","no":43,"q":"At the level of Arch of aorta, the relationship of left vagus nerve and left phrenic nerve?","o":["Phrenic nerve anterior, vagus nerve posterior","Phrenic nerve posterior, vagus nerve anterior","Both in same plane anteroposteriorly","Variable in relationship"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (205, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 205, '{"id":205,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":205,"q":"Pharyngeal muscles are derived from which pharyngeal arch ?","o":["1st","2nd","3rd","5th"],"a":2,"e":"3rd","pyqMatches":[{"year":"2013","no":2,"q":"Pharyngeal muscles are derived from which pharyngeal arch ?","o":["1st","2nd","3rd","5th"],"a":2,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":126,"q":"Pharyngeal muscles are derived from which pharyngeal arch ?","o":["1st","2nd","3rd","5th"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (206, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 206, '{"id":206,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":206,"q":"Styloid process is derived from ?","o":["1st arch","2nd arch","3rd arch","4th arch"],"a":1,"e":"Styloid process is derived from 2nd pharyngeal arch.","pyqMatches":[{"year":"2014","no":125,"q":"Styloid process is derived from ?","o":["1st arch","2nd arch","3rd arch","4th arch"],"a":1,"source":"NEET_2014_Paper.pdf"},{"year":"2016","no":952,"q":"Styloid process is derived from ?","o":["1st arch","2nd arch","3rd arch","4th arch"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2014","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (207, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 207, '{"id":207,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":207,"q":"Common interosseous artery is a branch of -","o":["Brachial artery","Radial artery","Ulnar artery","Profunda branchii artery"],"a":2,"e":"Branches of ulnar artery A) In cubital fossa 1) Anterior ulnar recurrent :- Anastomoses with inferior ulnar collateral in from of medial epicondyle. 2) Posterior ulnar recurrent :- Anastomoses with superior ulnar collateral behind medial cpicondyle. 3) Common interosseous :- Divides into i) Anterior interosseous : It is the deepest artery of front of forearm. It is accompanied by anterior interosseous nerve (a branch of median nerve). It pierces interosseous membrane at upper border of pronator quadratus to enter into extensor (dorsal) compartment. Its branches are : (a) muscular branches for deep muscles of front of forearm; (b) nutrient artery to radius and ulna; and (c) median artery. ii) Posterior interosseous : Near its origin, it gives of interosseous recurrent artery which ends by anastomosing with middle collateral artery. B) In forearm 1) Palmar carpal branch 2) Dorsal carpal branch C) In palm :- These are terminal branches. i) Deep branch :- Completes the deep palmar arch on medial side by joining the terminal part of radial artery. ii) Superficial branch :- Forms the major part of superficial palmar arch.","pyqMatches":[{"year":"2014","no":17,"q":"Common interosseous artery is a branch of","o":["Brachial artery","Radial artery","Ulnar artery","Profunda branchii artery"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (208, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 208, '{"id":208,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":208,"q":"Haller cells are seen in?","o":["Roof of nose","Orbital floor","Lateral nasal wall","Maxillary sinus"],"a":1,"e":"The Onodi and Haller cells are ethmoidal air cells. Some air cells may invade the orbital floor. These are known as the Haller'' cells. The Onodi cell is usually regarded as the most posterior ethmoid cell that pneumatizes lateral and superior to the sphenoid sinus and is intimately associated with the optic nerve.","pyqMatches":[{"year":"2014","no":85,"q":"Haller cells are seen in?","o":["Roof of nose","Orbital floor","Lateral nasal wall","Maxillary sinus"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (209, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 209, '{"id":209,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":209,"q":"True about clavicle?","o":["Endochondral ossification","Vertical","No medullary cavity","Rarely fractures"],"a":2,"e":"Ans:C.)No medullary cavity. Peculiarities of Clavicle: 1.It has no medullary cavity","pyqMatches":[{"year":"2014","no":3,"q":"True about clavicle?","o":["Endochondral ossification","Vertical","No medullary cavity","Rarely fractures"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (210, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 210, '{"id":210,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":210,"q":"Secondary ossification center for lower end of femur?","o":["Present at birth","Appears at 6 months of age","Appears at 1 year of age","Appears at 5 years of age"],"a":0,"e":"Secondary center of lower end of femur appears at 9th month of intrauterine life (present at birth). Ossification of femur The femur ossifies from one primary and four secondary centres. The primary centre for the shaft appears in the seventh week of intrauterine life. The secondary centres appear, one for the lower end at the end of the ninth month of intrauterine life, one for the head during the first six months of life, one for the greater trochanter during the fourth year, and one for the lesser trochanter during the twelfth year. There are three epiphyses at the upper end and one epiphysis at the lower end. The upper epiphyses; lesser trochanter, greater trochanter and head, in that order, fuse with the shaft at about eighteen years. The lower epiphysis fuses by the twentieth year.","pyqMatches":[{"year":"2014","no":127,"q":"Secondary ossification center for lower end of femur?","o":["Present at birth","Appears at 6 months of age","Appears at 1 year of age","Appears at 5 years of age"],"a":0,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":31,"q":"Secondary ossification center for lower end of femur?","o":["Present at birth","Appears at 6 months of age","Appears at 1 year of age","Appears at 5 years of age"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (211, 'Anatomy', 'Lower Limb', 'Moderate', 'Anatomy', 211, '{"id":211,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Moderate","source":"Anatomy","sourceNo":211,"q":"All are branches of lumbar plexus except?","o":["Iliohypogastric nerve","Ilioinguinal nerve","Obturator nerve","Subcostal nerve"],"a":3,"e":"Ans. is ''d'' i.e., Subcostal nerve","pyqMatches":[{"year":"2014","no":31,"q":"All are branches of lumbar plexus except?","o":["Iliohypogastric nerve","Ilioinguinal nerve","Obturator nerve","Subcostal nerve"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (212, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 212, '{"id":212,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":212,"q":"External oblique forms all except?","o":["Lacunar ligament","Pectineal ligament","Conjoint tendon","Inguinal ligament"],"a":2,"e":"Inguinal ligament (Poupart''s ligament) is the folded lower border of external oblique aponeurosis Lacunar ligament (Gimbernats ligament) is the crescent shaped expansion from the medial end of inguinal ligament attached to pectineal line of pubis. Pectineal ligament (Cooper''s ligament) is strong fibrous band extending laterally from the lacunar ligament along pectineal line of pubis. Similar to lacunar ligament, it is made of external oblique aponeurosis. Reflected part of inguinal ligament extends from the lateral crus of superficial inguinal ring formed by inguinal ligament upwards to linea alba. It forms the posterior wall of inguinal canal. Conjoint tendon (falx inguinalis) is formed by the aponeuroses of internal oblique and transversus abdominis muscle and is attached to pubic crest.","pyqMatches":[{"year":"2014","no":71,"q":"External oblique forms all except?","o":["Lacunar ligament","Pectineal ligament","Conjoint tendon","Inguinal ligament"],"a":2,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":65,"q":"External oblique forms all except?","o":["Lacunar ligament","Pectineal ligament","Conjoint tendon","Inguinal ligament"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (213, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 213, '{"id":213,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":213,"q":"Posterior to transverse pericardial sinus?","o":["Aorta","Pulmonary trunk","SVC","Left atrium"],"a":2,"e":"Ans. is ''c'' i.e., SVC Transverse sinus is a short passage that lies between the reflection of serous pericardium (epicardium) around arterial (aorta and pulmonary trunk) and venous ends of the heart tube. Transverse sinus is bounded anteriorly by ascending aorta and pulmonary trunk, posteriorly by SVC, and inferiorly by left atrium.","pyqMatches":[{"year":"2014","no":44,"q":"Posterior to transverse pericardial sinus?","o":["Aorta","Pulmonary trunk","SVC","Left atrium"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (214, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 214, '{"id":214,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":214,"q":"Medulla is supplied by all except?","o":["Basilar artery","Anterior spinal artery","Vertebral artery","Posterior cerebral artery"],"a":3,"e":"Posterior cerebral artery","pyqMatches":[{"year":"2014","no":81,"q":"Medulla is supplied by all except?","o":["Basilar artery","Anterior spinal artery","Vertebral artery","Posterior cerebral artery"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (215, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 215, '{"id":215,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":215,"q":"Articular surface of the sarum extends upto how many vertebrae in males ?","o":["1 to 11/2","2 to 21/2","3 to 31/2","4 to 41/2"],"a":2,"e":"Articular surface of sacrum: the rough articular surface on the lateral aspects of the sacrum that articulates with the ilium on each side.","pyqMatches":[{"year":"2014","no":32,"q":"Articular surface of the sarum extends upto how many vertebrae in males ?","o":["1 to 11/2","2 to 21/2","3 to 31/2","4 to 41/2"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (216, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 216, '{"id":216,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":216,"q":"Lower limit of sacro iliac joint lies upto which level in females ?","o":["1 to 1 1/2","2 to 2 1/2","3 to 3 1/2","4 to 4 1/2"],"a":1,"e":", 2 to 2 1/2","pyqMatches":[{"year":"2014","no":33,"q":"Lower limit of sacro iliac joint lies upto which level in females ?","o":["1 to 1 1/2","2 to 2 1/2","3 to 3 1/2","4 to 4 1/2"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (217, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 217, '{"id":217,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":217,"q":"Fibrin is degraded by ?","o":["Thrombin","Fibrin","Plasmin","None"],"a":2,"e":"Coagulation must be balanced with fibrinolysis to limit the hemostatic plug to the site of injury. Injured vascular endothelium secret plasminogen activator that converts inactive plasminogen to active plasmin. Plasmin breaks down fibrin resulting in production of fibrin degradation products. Fibrinolytic system is regulated by plasminogen activator inhibitors (PAIs) that are secreted by endothelium.","pyqMatches":[{"year":"2014","no":231,"q":"Fibrin is degraded by ?","o":["Thrombin","Fibrin","Plasmin","None"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (218, 'Anatomy', 'Miscellaneous', 'Moderate', 'Anatomy', 218, '{"id":218,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anatomy","sourceNo":218,"q":"Which is not an extrapyramidal tract ?","o":["Reticulospinal tract","Rubrospinal tract","Corticospinal tract","Tectospinal tract"],"a":2,"e":"Ans. is ''c'' i.e., Corticospinal tract","pyqMatches":[{"year":"2014","no":163,"q":"Which is not an extrapyramidal tract ?","o":["Reticulospinal tract","Rubrospinal tract","Corticospinal tract","Tectospinal tract"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (219, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 219, '{"id":219,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":219,"q":"Sensory perception involves Brodmann''s area ?","o":["3, 1, 2","4, 6","44, 45","41, 42"],"a":0,"e":"Ans.A. 3,1,2 Processing of general sensory inputs primarily occurs in primary somatosensory area of parietal lobe. Primary somatosensory area is Brodmann''s area 3, 1, 2.","pyqMatches":[{"year":"2014","no":166,"q":"Sensory perception involves Brodmann''s area ?","o":["3, 1, 2","4, 6","44, 45","41, 42"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (220, 'Anatomy', 'Miscellaneous', 'Moderate', 'Anatomy', 220, '{"id":220,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anatomy","sourceNo":220,"q":"Gastric acid secretion is stimulated by all except-","o":["Gastric distension","Gastrin","Smell of food","Somatostatin"],"a":3,"e":"There are following phases of gastric acid secretion : ?","pyqMatches":[{"year":"2014","no":228,"q":"Gastric acid secretion is stimulated by all except","o":["Gastric distension","Gastrin","Smell of food","Somatostatin"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (221, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 221, '{"id":221,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":221,"q":"Hangman''s fracture is the fracture involving which cervical vertebra?","o":["C1","C2","C3","C4"],"a":1,"e":"Ans. is ''b'' i.e., C2 Hangman''s fracture is a bilateral fracture of the pars interarticularis of the axis (C2) with a traumatic spondylolisthesis of axis (C2) over the C3 vertebrae. Thus Hangman''s fracture is not simply a fracture, but fracture-dislocation of the axis (C2). The mechanism of injury is an extension with distraction (in true, judicial hangman''s fracture) and hyper-extension, axial compression & flexion (in civilian injuries, which are now more common). It is the second most common type of Axis (C2) fracture, second only to odontoid fractures. Fatalities are common, However, neurological deficit is unusual as the fracture of the posterior arch decompresses the spinal cord. Most of the fatalities occur at the scene of injury, acute post- admission mortality is low. Successful healing of C2 traumatic spondylolisthesis is reported to approach 95%. This is most commonly achieved with non-operative measures, even in the presence of displacement of pars inter- articularis.","pyqMatches":[{"year":"2014","no":1730,"q":"Hangman''s fracture is the fracture involving which cervical vertebra?","o":["C1","C2","C3","C4"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (222, 'Anatomy', 'Neuroanatomy', 'Moderate', 'Anatomy', 222, '{"id":222,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":222,"q":"Which of the following does not directly drain into right atrium ?","o":["Great cardiac vein","Anterior cardiac vein","Thebasian vein","Venae cordis minimi"],"a":0,"e":"Ans. (A) Great cardiac vein Great cardiac vein does not directly drain into right atrium. It drains into coronary sinus, which in turn drains into right atrium. Veinous drainage of heart Coronary sinus : Opens into right atrium and has following tributaries : (i) Great cardiac vein, (ii) Middle cardiac vein, (iii) Posterior vein of left ventricle, (iv) Small cardiac vein, (v) Oblique vein of left atrium and (vi) Sometimes right marginal vein. Anterior cardiac vein : Opens into right atrium. Venae cardis minimi (thebasian veins) : All these are extremely small veins in the walls of all the 4 chambers of the heart. They open directly into the respective chambers. They’re most numerous in the right atrium. Right marginal vein : More often opens into right atrium but sometimes into coronary sinus.","pyqMatches":[{"year":"2015","no":44,"q":"Which of the following does not directly drain into right atrium ?","o":["Great cardiac vein","Anterior cardiac vein","Thebasian vein","Venae cordis minimi"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (223, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 223, '{"id":223,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":223,"q":"Gastrosplenic ligament contains ?","o":["Splenic vessels","Tail of pancreas","Short gastric artery","Portal vein"],"a":2,"e":"Short gastric artery","pyqMatches":[{"year":"2015","no":95,"q":"Gastrosplenic ligament contains ?","o":["Splenic vessels","Tail of pancreas","Short gastric artery","Portal vein"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (224, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 224, '{"id":224,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":224,"q":"Where is the Cave of Retzius present?","o":["Between urinary bladder and rectum","Between urinary bladder and cervix","In front of the bladder","Between the cervix and the rectum"],"a":2,"e":"Space of Retzius is a horse-shoe shaped potential space which intervenes between the antero-lateral pelvic wall and the sides of the bladder and prostate.","pyqMatches":[{"year":"2014","no":67,"q":"Where is the Cave of Retzius present?","o":["Between urinary bladder and rectum","Between urinary bladder and cervix","In front of the bladder","Between the cervix and the rectum"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (225, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 225, '{"id":225,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":225,"q":"Incudomalleolar joint is a ?","o":["Ellipsoid joint","Pivot joint","Hinge joint","Saddle joint"],"a":3,"e":"Synovial joints are classified as follows : 1) Plane synovial joints (flat joints) 2) Hinge joints (Ginglymus joints or ginglymi) 3) Pivot or trochoid joints 4) Condylar (bicondylar) joints 5) Ellipsoid joints Note : Metacarpophalangeal joints are ellipsoid joints functionally, but structurally they belong to condylar joints. 6) Saddle (sellar) joints The articular surfaces are reciprocally saddle shaped, i.e. concavo- convex. Examples are first (thumb) carpometacarpal joint, sternoclavicular joint, calcaneocuboid joint, incudomalleolar joint (smallest saddle joint) and patellofemoral joint. 7) Ball and socket (spheroidal) joints","pyqMatches":[{"year":"2015","no":128,"q":"Incudomalleolar joint is a ?","o":["Ellipsoid joint","Pivot joint","Hinge joint","Saddle joint"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (226, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 226, '{"id":226,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":226,"q":"Right border of heart is formed by ?","o":["Right ventricle","Right atrium","SVC","IVC"],"a":1,"e":"Ans. (B) Right atrium External features of heart The heart has following borders and surfaces :- A) Borders Right border :- Formed by right atrium. Left border (obtuse margin):- Formed mainly by left ventricle and partly by left auricle (in its upper most part). Inferior border (acute margin):- Formed mainly by right ventricle and partly by left ventricle near apex. Upper border :- Mainly by left atrium and partly by right atrium where SVC enters. Apex :- Formed by left ventricle. B) Surfaces Anterior (sternocostal) surface :- Formed mostly by right ventricle (major) and right auricle and partly by left ventricle and left auricle. Inferior (diaphragmatic) surface :- It is formed by left ventricle (left 2/3) and right ventricle (right 1/3). It is traversed by posterior interventricular groove (PIV) containing PIV branch of RCA.","pyqMatches":[{"year":"2015","no":52,"q":"Right border of heart is formed by ?","o":["Right ventricle","Right atrium","SVC","IVC"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (227, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 227, '{"id":227,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":227,"q":"Which leaves the pelvis ?","o":["Piriformis","Sciatic nerve","Superior gluteal vessel","Inferior gluteal vessel"],"a":1,"e":"Sciatic nerve leaves the pelvis and runs posteriorly in the thigh. In the upper angle of popliteal fossa, sciatic nerve divides into tibial nerve and common peroneal nerve","pyqMatches":[{"year":"2015","no":17,"q":"Which leaves the pelvis ?","o":["Piriformis","Sciatic nerve","Superior gluteal vessel","Inferior gluteal vessel"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (228, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 228, '{"id":228,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":228,"q":"Structure developing from Mullerian duct in males?","o":["Seminal vesicle","Epididymis","Prostatic utricle","Ureter"],"a":2,"e":"Ans. (C) Prostatic utricle Remnants of Mullerian duct (paramesonephric duct) in males are:- Appendix of testis (Hydatid of Morgagni) Prostatic utricle.","pyqMatches":[{"year":"2015","no":149,"q":"Structure developing from Mullerian duct in males?","o":["Seminal vesicle","Epididymis","Prostatic utricle","Ureter"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (229, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 229, '{"id":229,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":229,"q":"Tributary of coronary sinus ?","o":["Anterior cardiac vein","Thebesion vein","Smallest cardiac vein","Great cardiac vein"],"a":3,"e":"Ans. (D) Great cardiac vein Coronary sinus It opens in the posterior wall of right atrium, in the posterior part of coronary sulcus. Itopens in the right atrium between IVC and tricuspid orifices. Coronary sinus is guarded by Thebesian valve (Thebesian valve (incomplete semilunar valve) guards the orifice of coronary sinus.) Tributaries of coronary sinus are : Great cardiac vein :- Lies in the anterior interventricular groove. Left marginal vein drains into it. Middle cardiac vein :- Lies in the posterior interventricular groove. Posterior vein of left ventricle. Small cardiac vein :- It lies in the posterior part of coronary sulcus with RCA. Right marginnal vein may sometimes open into small cardiac vein, more often, however, right marginal vein opens directly into right atrium. Oblique vein of left atrium (vein of marshall) :- It is continuous above with ligament of IVC. These two structures are embryological remnants of left common cardinal vein (duct of cuvier).","pyqMatches":[{"year":"2012","no":62,"q":"Tributary of coronary sinus ?","o":["Anterior cardiac vein","Thebesion vein","Smallest cardiac vein","Great cardiac vein"],"a":3,"source":"NEET_2012_Paper.pdf"},{"year":"2015","no":45,"q":"Tributary of coronary sinus ?","o":["Anterior cardiac vein","Thebesion vein","Smallest cardiac vein","Great cardiac vein"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2012","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (230, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 230, '{"id":230,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":230,"q":"Wrist drop is due to injury to ?","o":["Radial nerve","Ulnar nerve","Median nerve","Posterior interosseous nerve"],"a":0,"e":"Ans. (A) Radial nerve Clinical features of radial nerve palsy Clinical features depend upon the site of lesion. 1) If lesion is high Wrist drop, thumb drop and finger drop. Inability to extend elbow, wrist, thumb & fingers (MP joint) Patient can extend interphalangeal joints due to action of lumbricals and interossei. Sensory loss over posterior surface of arm & forearm and lower lateral half of forearm. 2) If lesion is low a) Type I Wrist drop, thumb drop and finger drop. Elbow extension is preserved. Sensory loss over the dorsum of first web space. b) Type II Thumb drop and finger drop Elbow and wrist extension is preserved Sensory loss over the dorsum of first web space.","pyqMatches":[{"year":"2015","no":1471,"q":"Wrist drop is due to injury to ?","o":["Radial nerve","Ulnar nerve","Median nerve","Posterior interosseous nerve"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (231, 'Anatomy', 'Lower Limb', 'Moderate', 'Anatomy', 231, '{"id":231,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Moderate","source":"Anatomy","sourceNo":231,"q":"All are true about short saphenous vein except?","o":["Runs behind lateral malleolus","Runs on lateral side of leg","Accompanied by sural nerve","Achillis tendon is medial to vein"],"a":1,"e":"Short saphanous vein runs in the back (posteriorly) of leg (not laterally). It enters the back of leg by passing behind the lateral malleolus and is accompanied by sural nerve. In leg it ascends lateral to tendocalcaneous (tendoachillis). Thus tendoachillis is medial to vein.","pyqMatches":[{"year":"2014","no":20,"q":"All are true about short saphenous vein except?","o":["Runs behind lateral malleolus","Runs on lateral side of leg","Accompanied by sural nerve","Achillis tendon is medial to vein"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (232, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 232, '{"id":232,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":232,"q":"Nerve suply of cremastric muscle ?","o":["Pudendal nerve","Femoral branch of genitofemoral","Genital branch of genitofemoral nerve","Ilioinguinal nerve"],"a":2,"e":"Genital branch of genitofemoral nerve Cremastric muscle is a muscle of scrotum. It is supplied by genital branch of genitofemoral nerve.","pyqMatches":[{"year":"2015","no":86,"q":"Nerve suply of cremastric muscle ?","o":["Pudendal nerve","Femoral branch of genitofemoral","Genital branch of genitofemoral nerve","Ilioinguinal nerve"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (233, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 233, '{"id":233,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":233,"q":"Trigone of bladder is derived from ?","o":["Mesonephric duct","Paramesonephric duct","Absorbed anal membrane","Mullerian duct"],"a":0,"e":"Mesonephric duct","pyqMatches":[{"year":"2015","no":153,"q":"Trigone of bladder is derived from ?","o":["Mesonephric duct","Paramesonephric duct","Absorbed anal membrane","Mullerian duct"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (234, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 234, '{"id":234,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":234,"q":"Bartholin gland situated in ?","o":["Superficial perineal pouch","Deep perineal pouch","Inguinal canal","Ischiorecal fossa"],"a":0,"e":"Superficial perineal pouch","pyqMatches":[{"year":"2012","no":92,"q":"Bartholin gland situated in ?","o":["Superficial perineal pouch","Deep perineal pouch","Inguinal canal","Ischiorecal fossa"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (235, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 235, '{"id":235,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":235,"q":"Vasa Vasorum of ascending aorta arises from ?","o":["Left coronary artery","Anterior interventricular artery","Posterior interventricular artery","Left atrium"],"a":0,"e":"Clinical anatomy \"Both coronary arteries supply vasa vasorum of ascending aorta\" \"Coronary arteries are vasa vasorum of ascending aorta\" Vasa vasorum of ascending aorta and arch of aorta arise from : Coronary arteries (at their ostia). Brachiocephalic trunk. Bronchial artery. Vasa vasorum of descending aorta arise from'': Intercostal arteries (thoracic part). Lumbar and mesenteric arteries (abdominal part).","pyqMatches":[{"year":"2012","no":32,"q":"Vasa Vasorum of ascending aorta arises from ?","o":["Left coronary artery","Anterior interventricular artery","Posterior interventricular artery","Left atrium"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (236, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 236, '{"id":236,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":236,"q":"Middle meningeal artery passes through ?","o":["Foramen ovale","Foramen lacerum","Foramen rotundum","Foramen spinosum"],"a":3,"e":"Foramen spinosum","pyqMatches":[{"year":"2014","no":102,"q":"Middle meningeal artery passes through ?","o":["Foramen ovale","Foramen lacerum","Foramen rotundum","Foramen spinosum"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (237, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 237, '{"id":237,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":237,"q":"Structure which lies outside the femoral sheath","o":["Femoral artery","Femoral nerve","Femoral vein","Genitofemoral nerve"],"a":1,"e":"Femoral nerve Femoral sheath Femoral sheath is a funnel shaped fascial prolongation around proximal part of femoral vessels, situated in the femoral triangle, below the inguinal ligament. It is 3-4 cm long. It is formed by fascia iliaca. Femoral sheath is divided into 3 separate fascial compartements by septa :? Lateral compartment :- It contains femoral artery and femoral branch of genitofemoral nerve. Intermediate compartment :- Femoral vein. Medial compartment (femoral canal) :- It is conical in shape, wider above adn narrow below. The wider upper opening is known as femoral ring, which is potentially a weak point in lower abdomen and is the site for femoral hernia. Femoral ring is bounded : Anteriorly by inguinal ligament, medially by lacunar ligament, posteriorly by pectineus with its covering fascia, and laterally by septum separating it from femoral vein. Femoral canal contains lymph node of cloquet or Rosenmuller and lymphatics.","pyqMatches":[{"year":"2015","no":22,"q":"Structure which lies outside the femoral sheath","o":["Femoral artery","Femoral nerve","Femoral vein","Genitofemoral nerve"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (238, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 238, '{"id":238,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":238,"q":"Lateral border of ischeorectal fossa is formed by?","o":["Gluteus maximus","Perineal membrane","Pelvic diaphram","Obturator internus"],"a":3,"e":"Ans. is ''d'' i.e., Obturator internus Boundries of ischeoanal (ischeorectal) fossa are :- Anteriorly :- Posterior border of perineal membrane . Posteriorly :- Gluteus maximus muscle, sacrotuberous ligament. Laterally :- Ischial tuberosity and obturator internus. Medially :- Sphincter ani externus (external anal sphincter) and pelvic diaphragm (levator ani).","pyqMatches":[{"year":"2015","no":25,"q":"Lateral border of ischeorectal fossa is formed by?","o":["Gluteus maximus","Perineal membrane","Pelvic diaphram","Obturator internus"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (239, 'Anatomy', 'Lower Limb', 'Moderate', 'Anatomy', 239, '{"id":239,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Moderate","source":"Anatomy","sourceNo":239,"q":"Superior gluteal nerve does not supply ?","o":["Tensor fasciae latae","Gluteus medius","Gluteus minimus","Gluteus maximus"],"a":3,"e":"Ans. is ''d'' i.e., Gluteus maximus Nerve supplying muscles of gluteal region are :- Inferior gluteal nerve : Gluteus maximus. Superior gluteal nerve : Gluteus medius and minimus. Nerve to piriformis : Piriformis Nerve to obturator internus : Obturator internus, Gemellus superior. Nerve to quadratus femoris : Quadratus femoris, Gemellus inferior. Tensor fascia latae is supplied by superior gluteal nerve.","pyqMatches":[{"year":"2015","no":28,"q":"Superior gluteal nerve does not supply ?","o":["Tensor fasciae latae","Gluteus medius","Gluteus minimus","Gluteus maximus"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (240, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 240, '{"id":240,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":240,"q":"Muscle of Arm with additional supinator action?","o":["Brachialis","Biceps","Coracobrachialis","Triceps"],"a":1,"e":"Ans. is ''b'' i.e., Biceps","pyqMatches":[{"year":"2015","no":13,"q":"Muscle of Arm with additional supinator action?","o":["Brachialis","Biceps","Coracobrachialis","Triceps"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (241, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 241, '{"id":241,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":241,"q":"Lymphatic drainage of ovary?","o":["Deep inguinal","Superficial inguinal","Obturator","Paraaortic"],"a":3,"e":"Ans. is ''d'' i.e., Para-aortic Lymphatics of the ovary drain to para-aortic nodes alongside the origin of the ovarian artery (L2).","pyqMatches":[{"year":"2015","no":48,"q":"Lymphatic drainage of ovary?","o":["Deep inguinal","Superficial inguinal","Obturator","Paraaortic"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (242, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 242, '{"id":242,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":242,"q":"Anal valve is found in which part of anal canal ?","o":["Upper","Middle","Lower","At anus"],"a":0,"e":"Ans. is ''a'' i.e., Upper","pyqMatches":[{"year":"2012","no":65,"q":"Anal valve is found in which part of anal canal ?","o":["Upper","Middle","Lower","At anus"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (243, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 243, '{"id":243,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":243,"q":"Which muscle is inserted into the floor of the intertubercular sulcus of the humerus?","o":["Latissimus dorsi","Teres major","Pectoralis major","Deltoid"],"a":0,"e":"Ans. is ''a'' i.e., Latissimus dorsi The shaft of humerus is cylindrical in the upper half and triangular on cross-section in the lower half. The upper part has intertubercular sulcus (bicipital groove) anteriorly. Bicipital groove contains long head of biceps with its synovial sheath and an ascending branch of anterior circumflex humeral artery. Middle third of posterior surface of shaft of the humerus has a spiral groove (radial groove) which contains radial nerve and profunda brachi vessels. Attachment to shafts are ? * Insertions of pectoralis major (on lateral lip of bicipital groove), latissimus dorsi (on floor of bicipital groove), teres major (on deltoid tuberosity) and coracobrachialis (medially on mid shaft). * Origin of brachialis (anterior surface); Lateral and medial head of triceps (posterior surface); pronater teres (from medial supracondylar ridge); brachioradialis (from lateral supracondylar ridge) and ECRL (from lateral supracondylar ridge).","pyqMatches":[{"year":"2012","no":1,"q":"Which muscle is inserted into the floor of the intertubercular sulcus of the humerus?","o":["Latissimus dorsi","Teres major","Pectoralis major","Deltoid"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (244, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 244, '{"id":244,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":244,"q":"Ventral pancreatic duct give rise to ?","o":["Body","Tail","Neck","Uncinate process"],"a":3,"e":"Ans. is ''d'' i.e., Uncinate process Development of pancreas Pancreas is developed from the two pancreatic buds.","pyqMatches":[{"year":"2015","no":72,"q":"Ventral pancreatic duct give rise to ?","o":["Body","Tail","Neck","Uncinate process"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (245, 'Anatomy', 'Histology', 'Moderate', 'Anatomy', 245, '{"id":245,"subject":"Anatomy","chapter":"Histology","difficulty":"Moderate","source":"Anatomy","sourceNo":245,"q":"All are derived from neural crest except ?","o":["Adrenal medulla","Pigment cell in skin","Corneal stroma","Retinal pigmented epithelium"],"a":3,"e":"Ans. is `d'' i.e., Retinal pigmented epithelium Derivatives of neuroectoderm","pyqMatches":[{"year":"2016","no":5,"q":"All are derived from neural crest except ?","o":["Adrenal medulla","Pigment cell in skin","Corneal stroma","Retinal pigmented epithelium"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (246, 'Anatomy', 'Neuroanatomy', 'Moderate', 'Anatomy', 246, '{"id":246,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":246,"q":"True about atrioventricular groove are all except ?","o":["Contains left anterior descending coronary artery","Also called coronary sulcus","Contains right coronary artery","Contains circumflex branch of left coronary artery"],"a":0,"e":"Ans. is ''a'' i.e., Contains left anterior descending coronary artery Grooves (sulci) of heart A) Atrioventricular groove Atria are separated by ventricles by atrioventricular Sulcus (atrioventricular groove, also called coronary sulcus). It is divided into anterior and posterior parts. The right half of anterior part is large and lodges right coronary artery. Left half of anterior part is small and lodges circumflex branch of left coronary artery. B) Interventricular grooves Right and left ventricles are separated by interventricular grooves. Anterior interventricular groove is nearer to left margin of heart and contains anterior interventricular artery (also called left anterior descending artery). Posterior interventricular groove is situated on diaphragmatic (inferior) surface. It contains posterior interventricular artery (continuation of RCA).","pyqMatches":[{"year":"2015","no":42,"q":"True about atrioventricular groove are all except ?","o":["Contains left anterior descending coronary artery","Also called coronary sulcus","Contains right coronary artery","Contains circumflex branch of left coronary artery"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (247, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 247, '{"id":247,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":247,"q":"Intercostal nerve is a branch of ?","o":["Brachial plexus","Dorsal rami of thoracic spinal nerves","Ventral rami of thoracic spinal nerves","Ventral rami of cervical spinal nerves"],"a":2,"e":"Ans. is ''c'' i.e., Ventral rami of thoracic spinal nerves Ventral rami of upper 11th thoracic spinal nerves are known as intercostal nerves and ventral ramus of T12 is known as subcostal nerve. Upper six intercostal nerves supply thoracic wall whereas lower five intercostal nerves and subcostal nerve supply thoracic and anterior abdominal walls and hence known as thoracoabdominal nerves. Upper two intercostal nerves also supply the upper limb. Thus only 3rd to 6th are called typical intercostal nerves.","pyqMatches":[{"year":"2015","no":38,"q":"Intercostal nerve is a branch of ?","o":["Brachial plexus","Dorsal rami of thoracic spinal nerves","Ventral rami of thoracic spinal nerves","Ventral rami of cervical spinal nerves"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (248, 'Anatomy', 'Abdomen', 'Moderate', 'Anatomy', 248, '{"id":248,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Moderate","source":"Anatomy","sourceNo":248,"q":"All are true about 1st part of duodenum, except ?","o":["5 cm long","Is superior part","Develops from foregut","Supplied by superior mesenteric artery"],"a":3,"e":"Ans. is ''d'' i.e., Supplied by superior mesenteric artery Duodenum Duodenum is ''C'' shaped, shortest, widest and most fixed part of small intestine. It is 25 cm long. It is devoid of mesentery. Most of the duodenum is retroperitoneal and fixed, except at its two ends where it is suspended by folds of peritoneum, and is therefore mobile. Duodenum lies opposite Ll, L2 and L3 vertebrae. Duodenum is C-shaped curve which encloses the head of pancreas and is subdivided into four parts :","pyqMatches":[{"year":"2015","no":71,"q":"All are true about 1st part of duodenum, except ?","o":["5 cm long","Is superior part","Develops from foregut","Supplied by superior mesenteric artery"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (249, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 249, '{"id":249,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":249,"q":"Which of the following is a derivative of ventral mesogastrium ?","o":["Greater omentum","Gastrosplenic ligament","Linorenal ligament","Lesser omentum"],"a":3,"e":"Ans. is ''d'' i.e., Lesser omentum","pyqMatches":[{"year":"2015","no":96,"q":"Which of the following is a derivative of ventral mesogastrium ?","o":["Greater omentum","Gastrosplenic ligament","Linorenal ligament","Lesser omentum"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (250, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 250, '{"id":250,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":250,"q":"Number of vertebrae is usually constant in","o":["Cervical","Thoracic","Lumbar","Sacral"],"a":0,"e":"Ans. a. Cervical Author please provide * Illustrated Encyclopedia of Human Anatomic Variation: Opus V: Skeletal Systems: Vertebral column; Numerical Variation in Vertebral Column by Ronald A. Bergman, PhD; Adel K. Afifi, MD, MS; Ryosuke Miyauchi, MD. * The usual grouping formula of 7 cervical, 12 thoracic, 5 lumbar, 5 sacral, and 4 coccygeal vertebrae is found in only about * The cervical region is reported to be the most constantQ, the coccygeal the most variable 20% of individuals studied. * The number of elements of the vertebral column has been reported to vary between 32 and 35. Addition to a group is frequently seen, which occurs through the reduction in number of vertebrae of an adjacent group, the total number being * The location of such a vertebra is predominately at the ends of the column and at the levels of transition between its regions. Thus, sacralization of the fifth lumbar, lumbar-like articular processes in the eleventh thoracic, and thoracic costal facets on the seventh cervical are observed. *unchanged. In this variation, the vertebra added is usually intermediate in form between the adjacent groups. * The levels of transition may be shifted cephalad, resulting in 23 mobile vertebrae, or shifted caudad, resulting in 25 presacral vertebrae. Such variations may occur in 2-11% of the population * The number of vertebrae comprising the sacrum maybe increased to six, resulting from the fusion of the first coccygeal (50% in whites, 30% in Negroes) or, less often, of the last lumbar (sacralization) (8% in whites, 11% in Negroes); or it maybe increased to seven, resulting from the fusion of the first coccygeal and the last lumbar (4% in whites, 1.5% in Negroes). The number maybe reduced to four, apparently by the lumbarization of the first sacral (0.4% in whites, 1.5% in Negroes). Number of vertebrae * Most constant: Cervical region° * Most variable: coccygeal region°","pyqMatches":[{"year":"2012","no":96,"q":"Number of vertebrae is usually constant in","o":["Cervical","Thoracic","Lumbar","Sacral"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (251, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 251, '{"id":251,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":251,"q":"Which of the following structures seen in the cavernous sinus?","o":["Maxillary division of V nerve","Mandibular division of V nerve","Internal carotid artery","Facial nerve"],"a":2,"e":"Ans. c. Internal carotid artery Contents of the cavernous sinus Structures in the lateral wall of the sinus Oculomotor (lll) nerve Trochlear (lV) nerve Ophthalmic (1st division of V) nerve Trigeminal ganglion Internal carotid artery Abducent (Vl) nerve","pyqMatches":[{"year":"2012","no":68,"q":"Which of the following structures seen in the cavernous sinus?","o":["Maxillary division of V nerve","Mandibular division of V nerve","Internal carotid artery","Facial nerve"],"a":2,"source":"NEET_2012_Paper.pdf"},{"year":"2015","no":123,"q":"Which of the following structures seen in the cavernous sinus?","o":["Maxillary division of V nerve","Mandibular division of V nerve","Internal carotid artery","Facial nerve"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2012","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (252, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 252, '{"id":252,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":252,"q":"Valve of heister is seen in","o":["Cystic duct","Common bile duct","Common hepatic duct","Pancreatic duct"],"a":0,"e":"Ans. is ''a'' i.e., Cystic duct The mucous membrane of the cystic duct forms a series of 5-12 crescentic folds, arranged spirally to form the so called spiral valve of Heister. This is not a true valve. Also know Hartmanns pouch - dilated posteromedial wall of neck of gall bladder. Sphincter choledochus - always present - terminal part of bile duct Sphincter pancreaticus - usually present - terminal part of pancreatic duct Sphincter ampullae (of Oddi) - surrounds the hepatopancreatic ampulla","pyqMatches":[{"year":"2014","no":134,"q":"Valve of heister is seen in","o":["Cystic duct","Common bile duct","Common hepatic duct","Pancreatic duct"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (253, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 253, '{"id":253,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":253,"q":"Eustachian tube opens in middle ear in ?","o":["Floor","Anterior wall","Superior wall","Posterior wall"],"a":1,"e":"Ans. is ''b'' i.e., Anterior wall The middle ear is shaped like a cube. When seen in the coronal section, the cavity of the middle ear is biconcave. The boundaries of the middle ear are as follows :","pyqMatches":[{"year":"2012","no":99,"q":"Eustachian tube opens in middle ear in ?","o":["Floor","Anterior wall","Superior wall","Posterior wall"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (254, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 254, '{"id":254,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":254,"q":"Which of the following is related to mediastinal part of right lung ?","o":["Arch of aorta","SVC","Pulmonary trunk","Left ventricle"],"a":1,"e":"Ans. is \"b.'''' i.e., SVC","pyqMatches":[{"year":"2013","no":63,"q":"Which of the following is related to mediastinal part of right lung ?","o":["Arch of aorta","SVC","Pulmonary trunk","Left ventricle"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (255, 'Anatomy', 'Thorax', 'Moderate', 'Anatomy', 255, '{"id":255,"subject":"Anatomy","chapter":"Thorax","difficulty":"Moderate","source":"Anatomy","sourceNo":255,"q":"Esophagus is present in all except ?","o":["Superior mediastinum","Middle mediastinum","Anterior mediastinum","Posterior mediastinum"],"a":2,"e":"Ans. is ''c'' i.e., Anterior mediastinum Esophagus mainly descends in superior and posterior mediastinum. Esophagus is usually not a content of middle mediastinum, but it forms posterior boundry of middle mediastinum (BDC Vol.-1, 6`\"/e p. 246). Esophagus has no relation to anterior mediastinum. Thus, among the given options, best answer is anterior mediastinum.","pyqMatches":[{"year":"2013","no":61,"q":"Esophagus is present in all except ?","o":["Superior mediastinum","Middle mediastinum","Anterior mediastinum","Posterior mediastinum"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (256, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 256, '{"id":256,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":256,"q":"Skeletal derivative of 2°'' pharyngeal arch -","o":["Malleus","Incus","Stapes","Maxilla"],"a":2,"e":"Ans. is `c'' i.e., Stapes","pyqMatches":[{"year":"2012","no":7,"q":"Skeletal derivative of 2°'' pharyngeal arch","o":["Malleus","Incus","Stapes","Maxilla"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (257, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 257, '{"id":257,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":257,"q":"Clavipectoral fascia is derived from which ligament ?","o":["Coracoacromial","Coracoclavicular","Costoclavicular","Costocoracoid"],"a":3,"e":"Ans. is ''d'' i.e., Costocoracoid","pyqMatches":[{"year":"2013","no":21,"q":"Clavipectoral fascia is derived from which ligament ?","o":["Coracoacromial","Coracoclavicular","Costoclavicular","Costocoracoid"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (258, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 258, '{"id":258,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":258,"q":"Nerve supply of larynx above level of vocal cord","o":["Superior laryngeal","Recurrent laryngeal","Glossopharyngeal","External laryngeal"],"a":0,"e":"Ans. is ''a'' i.e., Superior laryngeal Nerve supply of larynx The main cranial nerve innervating the larynx is the vagus nerve via its branches; superior laryngeal nerve (SLN) and recurrent laryngeal nerve (RLN). Sensory supply of larynx Above the level of vocal cords, larynx is supplied by internal laryngeal nerve, a branch of superior laryngeal nerve. Below the vocal cord, larynx is supplied by recurrent laryngeal nerve. Motor supply of larynx All the intrinsic muscles of larynx are supplied by recurrent laryngeal nerve except for cricothyroid muscle. Cricothyroid is supplied by external laryngeal nerve, a branch of superior laryngeal nerve.","pyqMatches":[{"year":"2013","no":88,"q":"Nerve supply of larynx above level of vocal cord","o":["Superior laryngeal","Recurrent laryngeal","Glossopharyngeal","External laryngeal"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (259, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 259, '{"id":259,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":259,"q":"Root value of thoracodorsal nerve ?","o":["C5,C6,C7","C8,T1","C6,C7,C8","Ti T2"],"a":2,"e":"Ans. is ''c'' i.e., C6C7C8 Branches of brachial plexus Branches of brachial plexus arises from different anatomical segments : -","pyqMatches":[{"year":"2013","no":23,"q":"Root value of thoracodorsal nerve ?","o":["C5,C6,C7","C8,T1","C6,C7,C8","Ti T2"],"a":2,"source":"NEET_2013_Paper.pdf"},{"year":"2015","no":3,"q":"Root value of thoracodorsal nerve ?","o":["C5,C6,C7","C8,T1","C6,C7,C8","Ti T2"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2013","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (260, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 260, '{"id":260,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":260,"q":"Length of Posterior vaginal wall is","o":["Variable","Same as anterior vaginal wall","Less than anterior vaginal wall","More than anterior vaginal wall"],"a":3,"e":"Ans. is ''d'' i.e., More than anterior vaginal wall Vagina The vagina is a fibromuscular, canal forming the female copulatory organ. It extends from vulva to uterus. Mucous membrane is lined by nonkeratinized stratified squamous epithelium. The anterior wall is about 8 cm long and the posterior wall is about 10 cm long. The lumen is circular at the upper end because of the protrusion of the cervix into it. Below the cervix, anterior and posterior walls are in contact. The interior of the upper end of the vagina (or vaginal vault) is in the form of a circular groove that surrounds the protrudng cervix. The groove becomes progressively deeper form before backwards and is arbitrarily divided into four parts called the vaginal fornices : Anterior fornix lies in front of the cervix and is shallowest. Posterior fornix lies behind the cervix and is deepest. Two lateral fornices lie one on each side of the cervix. Lateral fornix is related to the transverse cervical ligament of pelvic fascia in which are embedded a network of vaginal vein and the ureter gets crossed by the uterine artery. Relations of vagina Anterior wall Upper half is related to the base of the bladder. Lower half to the urethra. Posterior wall Upper one-fourth is separated from the rectum by the rectouterine pouch. Middle two-fourths are separated from the rectum by loose connective tissue. Lower one-fourths is separated from the anal canal by the perineal body and the muscles attached to it. Lateral walls One each side : Upper one-third is related to the transverse cervical ligament of pelvic fascia in which are embedded a network of vaginal veins, and the ureter gets crossed by the uterine artery. Middle one-third is related the pubococcygeus part of the levator ani. Lower one-third pierces the perineal membrane, below which it is related to the bulb of the vestibule, the bulbospongiosus and the duct of greater vestibular gland of bartholin. Arterial supply Vaginal branch of internal iliac (main supply) Cervicovaginal branch of uterine artery (in upper part). Middle rectal and internal pudendal arteries (in lower part).","pyqMatches":[{"year":"2014","no":56,"q":"Length of Posterior vaginal wall is","o":["Variable","Same as anterior vaginal wall","Less than anterior vaginal wall","More than anterior vaginal wall"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (261, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 261, '{"id":261,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":261,"q":"Which lymph nodes drain upper vagina & cervix?","o":["Para aortic","External iliac","Superior inguinal","Deep inguinal"],"a":1,"e":"Ans. is ''b'' i.e., External iliac The lymphatics from the cervix drain into the external iliac, internal iliac and sacral nodes. Lymphatic Drainage of uterus: Fundus and upper body - aortic nodes and superficial inguinal nodes Lower body - external iliac nodes Cervix - external iliac, internal iliac and sacral nodes. Lymphatic drainage of Vagina: Upper 1/3 - external iliac nodes Middle 1/3 - internal iliac nodes Lower 1/3- superficial inguinal nodes","pyqMatches":[{"year":"2013","no":72,"q":"Which lymph nodes drain upper vagina & cervix?","o":["Para aortic","External iliac","Superior inguinal","Deep inguinal"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (262, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 262, '{"id":262,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":262,"q":"Posterior surface of heart is formed by -","o":["RA","LA","LV","RV"],"a":1,"e":"Ans. is ''b>a'' i.e., LA>RA Surfaces of the heart","pyqMatches":[{"year":"2013","no":64,"q":"Posterior surface of heart is formed by","o":["RA","LA","LV","RV"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (263, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 263, '{"id":263,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":263,"q":"Largest branch of brachial plexus is","o":["Ulnar","Medial","Radial","Axillary"],"a":2,"e":"Ans. is ''c'' i.e., Radial Radial nerve is the largest branch of brachial plexus and is the continuation of posterior cord (root value C5_8 T1).","pyqMatches":[{"year":"2013","no":24,"q":"Largest branch of brachial plexus is","o":["Ulnar","Medial","Radial","Axillary"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (264, 'Anatomy', 'Head & Neck', 'Moderate', 'Anatomy', 264, '{"id":264,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Moderate","source":"Anatomy","sourceNo":264,"q":"Which muscle of larynx is not supplied by recurrent laryngeal nerve ?","o":["Vocalis","Thyroarytenoid","Cricothyroid","Interarytenoid"],"a":2,"e":"Ans. is ''c'' i.e., Cricothyroid All intrinsic muscles are supplied by the reccurrent laryngeal nerve except cricothyroid which is supplied by the external laryngeal nerve","pyqMatches":[{"year":"2013","no":89,"q":"Which muscle of larynx is not supplied by recurrent laryngeal nerve ?","o":["Vocalis","Thyroarytenoid","Cricothyroid","Interarytenoid"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (265, 'Anatomy', 'Upper Limb', 'Moderate', 'Anatomy', 265, '{"id":265,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Moderate","source":"Anatomy","sourceNo":265,"q":"All are infraclavicular branches of brachial plexus except ?","o":["Ulnar nerve","Long thoracic nerve","Axillary nerve","Thoracodorsal nerve"],"a":1,"e":"Ans. is `b'' i.e., Long thoracic nerve","pyqMatches":[{"year":"2013","no":22,"q":"All are infraclavicular branches of brachial plexus except ?","o":["Ulnar nerve","Long thoracic nerve","Axillary nerve","Thoracodorsal nerve"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (266, 'Anatomy', 'Miscellaneous', 'Moderate', 'Anatomy', 266, '{"id":266,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anatomy","sourceNo":266,"q":"A surgeon removes a part of liver to left of falciparum ligament, which segment of liver is removed ?","o":["1 & 4","2 & 3","1 & 4","1 & 3"],"a":1,"e":"Ans. is ''b'' i.e., 2 & 3","pyqMatches":[{"year":"2013","no":73,"q":"A surgeon removes a part of liver to left of falciparum ligament, which segment of liver is removed ?","o":["1 & 4","2 & 3","1 & 4","1 & 3"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (267, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 267, '{"id":267,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":267,"q":"Esophagus is present in which mediastinum ?","o":["Anterior","Posterior","Middle","None"],"a":1,"e":"Ans. is ''b'' i.e., Posterior","pyqMatches":[{"year":"2013","no":62,"q":"Esophagus is present in which mediastinum ?","o":["Anterior","Posterior","Middle","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (268, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 268, '{"id":268,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":268,"q":"Posterior to sternum is ?","o":["Left atrium","Left ventricle","Right atrium","Right ventricle"],"a":3,"e":"Ans. is ''d'' i.e., Right ventricle Normally, most of the anterior portion of right ventricle is in contact with sternum. It is for this reason that sternal and parasternal injury commonly results in right vantricular injury.","pyqMatches":[{"year":"2013","no":66,"q":"Posterior to sternum is ?","o":["Left atrium","Left ventricle","Right atrium","Right ventricle"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (269, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 269, '{"id":269,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":269,"q":"Location of testis is higher on ?","o":["Right side","Left side","May be on right or left side","Same level on both sides"],"a":0,"e":"Ans. A Right Right testis is located at a higher position than left .","pyqMatches":[{"year":"2013","no":75,"q":"Location of testis is higher on ?","o":["Right side","Left side","May be on right or left side","Same level on both sides"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (270, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 270, '{"id":270,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":270,"q":"Distal end of humerous develops from how many centres ?","o":["2","5","3","4"],"a":3,"e":"Ans. is ''d'' i.e., 4 Part of humerus → Ossification Shaft → One primary center Upper end Three secondary centers ?","pyqMatches":[{"year":"2013","no":28,"q":"Distal end of humerous develops from how many centres ?","o":["2","5","3","4"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (271, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 271, '{"id":271,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":271,"q":"Clavipectoral fascia is pierced by all except ?","o":["Lateral pectoral nerve","Median pectoral nerve","Thoracoacromial vessels","Cephalic vein"],"a":1,"e":"Ans. is ''b'' i.e., Median pectoral nerve Clavipectoral fascia is pierced by - Thoraco-Acromial vessels. Lateral pectoral nerve. Lymphatics passing from breast and pectoral region to apical-axillary 1.n. Cephalic vein.","pyqMatches":[{"year":"2014","no":4,"q":"Clavipectoral fascia is pierced by all except ?","o":["Lateral pectoral nerve","Median pectoral nerve","Thoracoacromial vessels","Cephalic vein"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (272, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 272, '{"id":272,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":272,"q":"Stomach is supplied by ?","o":["Coeliac trunk","Splenic artery","Gastroduodenal artery","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above","pyqMatches":[{"year":"2016","no":79,"q":"Stomach is supplied by ?","o":["Coeliac trunk","Splenic artery","Gastroduodenal artery","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (273, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 273, '{"id":273,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":273,"q":"Which muscle plays a role in winking","o":["Levator labi superioris","Orbicularis oculi","Corrugator supercilli","Levator palpebrae"],"a":1,"e":"Ans. is ''b'' i.e., Orbicularis oculi","pyqMatches":[{"year":"2013","no":90,"q":"Which muscle plays a role in winking","o":["Levator labi superioris","Orbicularis oculi","Corrugator supercilli","Levator palpebrae"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (274, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 274, '{"id":274,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":274,"q":"Muscle attached to lateral surface of greater trochanter -","o":["Gluteus maximus","Gluteus medius","Gluteus minimus","Piriformis"],"a":1,"e":"Ans. is ''b'' i.e., Gluteus medius Attachments of greater trochanter (GT) All are insertions Part of GT Muscle inserted Apex (tip) of GT Piriformis Anterior surface (lateral part)Gluteus minimus Lateral surface Gluteus medius Medial surface Obturator internus & two gemelli Trochanteric fossa Obturator externus","pyqMatches":[{"year":"2013","no":53,"q":"Muscle attached to lateral surface of greater trochanter","o":["Gluteus maximus","Gluteus medius","Gluteus minimus","Piriformis"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (275, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 275, '{"id":275,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":275,"q":"Support of prostate is ?","o":["Pubococcygeus","Ischiococcygeus","Ilioccygeus","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Pubococcygeus Levator ani muscle is divisible into following parts :​1) Puboccygeus part Anterior fibers of this part closely surround the prostate, in males, to form, levator prostatae. In the female these fibres surround the vagina and form sphincter vaginae. In both cases these anterior fibres are inserted into the perineal body. Middle fibers constitute the puborectalis. They partly form a loop or sling around the anorectal junction; and are partly continuous with longitudinal muscle coat of the rectum. Posterior fibers are attached to anococcygeal ligament and tip of coccyx. Iliococcygeus part This is inserted to anococcygeal ligament and last two pieces of coccyx. Ischiococcygeus part (or coccygeus) It forms posterior part of pelvic floor.","pyqMatches":[{"year":"2013","no":76,"q":"Support of prostate is ?","o":["Pubococcygeus","Ischiococcygeus","Ilioccygeus","None of the above"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (276, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 276, '{"id":276,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":276,"q":"Collagen found in hyaline cartilage is ?","o":["Type I","Type II","Type IV","Type v"],"a":1,"e":"Ans. is ''b'' i.e., Type II","pyqMatches":[{"year":"2013","no":13,"q":"Collagen found in hyaline cartilage is ?","o":["Type I","Type II","Type IV","Type v"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (277, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 277, '{"id":277,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":277,"q":"Galen''s anastomosis is between ?","o":["Recurrent laryngeal nerve and external laryngeal nerve","Recurrent laryngeal nerve and internal laryngeal nerve","Internal laryngeal nerve and external laryngeal nerve","None of the above"],"a":1,"e":"Ans. is ''b'' i.e., Recurrent laryngeal nerve and internal laryngeal nerve There are two types of important anastmosis between laryngeal branches of vagus :?","pyqMatches":[{"year":"2013","no":91,"q":"Galen''s anastomosis is between ?","o":["Recurrent laryngeal nerve and external laryngeal nerve","Recurrent laryngeal nerve and internal laryngeal nerve","Internal laryngeal nerve and external laryngeal nerve","None of the above"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":88,"q":"Galen''s anastomosis is between ?","o":["Recurrent laryngeal nerve and external laryngeal nerve","Recurrent laryngeal nerve and internal laryngeal nerve","Internal laryngeal nerve and external laryngeal nerve","None of the above"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (278, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 278, '{"id":278,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":278,"q":"Radial bursa is the synovial sheath covering the tendon of ?","o":["FDS","FDP","FPL","FCR"],"a":2,"e":"Ans. is ''c'' i.e., FPL","pyqMatches":[{"year":"2013","no":29,"q":"Radial bursa is the synovial sheath covering the tendon of ?","o":["FDS","FDP","FPL","FCR"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (279, 'Anatomy', 'Upper Limb', 'Moderate', 'Anatomy', 279, '{"id":279,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Moderate","source":"Anatomy","sourceNo":279,"q":"Which muscle will be paralyzed when radial nerve is injured in just below be spiral groove ?","o":["Lateral head of triceps","Medial head of triceps","Long head of triceps","ECRL"],"a":3,"e":"Ans. is ''d'' i.e., ECRL Radial nerve injury Radial nerve injury may be high or low.","pyqMatches":[{"year":"2013","no":26,"q":"Which muscle will be paralyzed when radial nerve is injured in just below be spiral groove ?","o":["Lateral head of triceps","Medial head of triceps","Long head of triceps","ECRL"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (280, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 280, '{"id":280,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":280,"q":"Which are segments of upper lobe of right lung ?","o":["Anterior, posterior, media","Lateral, medial, superior","Apical, anterior, posterior","Basal, medial, lateral"],"a":2,"e":"Ans. is ''c'' i.e., Apical, anterior, posterior","pyqMatches":[{"year":"2015","no":46,"q":"Which are segments of upper lobe of right lung ?","o":["Anterior, posterior, media","Lateral, medial, superior","Apical, anterior, posterior","Basal, medial, lateral"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (281, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 281, '{"id":281,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":281,"q":"Centroacinar cells are present in ?","o":["Pancreas","Parotid gland","Prostate","None"],"a":0,"e":"Ans. is ''a'' i.e., Pancreas Pancreas It is a mixed exocrine and endocrine gland. A . Exocrine part The exocrine portion is a compound acinar gland, consists of pancreatic acini. The acini of pancreas consist of a group of pyramid-shaped acinar cells'' (pancreatic parenchymal cells) arranged around a small lumen. The centroacinar-cells are seen at the centre of acini where the duct system begins. These cells are an extension of the intercalated duct cells into the acinus. They add bicarbonate ions to pancreatic juce. Individual acini are drained by intercalated ducts (interalobular ducts), which drain into larger interlobular ducts, found in connective tissue septa. B. Endocrine part Islets of Langerhans constitute the endocrine part and are scattered throughout the exocrine part, most abundandly in tail region.","pyqMatches":[{"year":"2013","no":227,"q":"Centroacinar cells are present in ?","o":["Pancreas","Parotid gland","Prostate","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (282, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 282, '{"id":282,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":282,"q":"Billorth''s cord are present in which part of spleen?","o":["White pulp","Red pulp","Both","Capsule"],"a":1,"e":"Ans. is `b'' i.e., Red pulp Histology of spleen Spleen has a capsule which is mainly composed of collagen with some elastin. Trabeculae are septae pass inwards from the capsule. Spleen is mainly composed of two parts :","pyqMatches":[{"year":"2013","no":14,"q":"Billorth''s cord are present in which part of spleen?","o":["White pulp","Red pulp","Both","Capsule"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (283, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 283, '{"id":283,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":283,"q":"B-cells are dispersed in which part of spleen?","o":["White pulp","Red pulp","Capsule","None"],"a":0,"e":"Ans. is ''a'' i.e., White pulp","pyqMatches":[{"year":"2013","no":15,"q":"B-cells are dispersed in which part of spleen?","o":["White pulp","Red pulp","Capsule","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (284, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 284, '{"id":284,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":284,"q":"Neurovascular bundle of anterior compartment of leg passes between the tendons of ?","o":["EHL and EDL","EDL and peroneus tertius","Tibialis anterior and EHL","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., EHL and EDL","pyqMatches":[{"year":"2013","no":47,"q":"Neurovascular bundle of anterior compartment of leg passes between the tendons of ?","o":["EHL and EDL","EDL and peroneus tertius","Tibialis anterior and EHL","None of the above"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (285, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 285, '{"id":285,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":285,"q":"True statement about great sphenous vein","o":["It begins at lateral end of dorsal venous arch","It runs anterior to medial malleolus","It is accomponied by sural nerve","Terminates into popliteal vein"],"a":1,"e":"Ansis ''b'' i.e., It runs anteiror to medial malleolus","pyqMatches":[{"year":"2013","no":46,"q":"True statement about great sphenous vein","o":["It begins at lateral end of dorsal venous arch","It runs anterior to medial malleolus","It is accomponied by sural nerve","Terminates into popliteal vein"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (286, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 286, '{"id":286,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":286,"q":"In arm ulnar nerve gives muscular branch to which muscle ?","o":["FCU","FDP","Both","None"],"a":2,"e":"Ans. is ''C'' i.e., both Reference BDC 4th edition volume 1 , pg 157.","pyqMatches":[{"year":"2013","no":27,"q":"In arm ulnar nerve gives muscular branch to which muscle ?","o":["FCU","FDP","Both","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (287, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 287, '{"id":287,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":287,"q":"Vertebral arteries of both sides unite to form","o":["Anterior spinal artery","Posterior spinal artery","Medullary artery","Basilar artery"],"a":3,"e":"Ans. is ''d'' i.e., Basilar artery Vertebral Artery It arises from 1st part of subclavian artery First Part : Origin to the foramen transversarium of C6 vertebra. It lies in the scalenovertebral/vertebral triangle (triangle of vertebral artery) between scalemus anterior and longus colli muscles. Second Part : This part passes through foramina transversaria of upper 6 cervical vertebrae (C6 to C1). Third Part : It extends from foramen transversarium of Ci to foramen magnum, lying in a groove on the upper surface of posterior arch of atlas.This part of the artery lies in the suboccipital triangle. It then enters the vertebral canal by passing deep to the lower arched margin of posterior atlanto-occipital membrance. Fourth Part : It lies in the posterior cranial fossa extending from the foramen magnum to the lower border of pons. In the vertebral canal, it pierces the dura and arachnid and ascends in front of hypoglossal nerve roots. At the lower border of pons both vertebral arteries unite to form the basilar artery. Cervical branches","pyqMatches":[{"year":"2013","no":105,"q":"Vertebral arteries of both sides unite to form","o":["Anterior spinal artery","Posterior spinal artery","Medullary artery","Basilar artery"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (288, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 288, '{"id":288,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":288,"q":"Follicles are present in which part of lymph nodes ?","o":["Red pulp","White pulp","Cortex","Medulla"],"a":2,"e":"Ans. is ''c'' i.e., Cortex","pyqMatches":[{"year":"2013","no":16,"q":"Follicles are present in which part of lymph nodes ?","o":["Red pulp","White pulp","Cortex","Medulla"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (289, 'Anatomy', 'Embryology', 'Moderate', 'Anatomy', 289, '{"id":289,"subject":"Anatomy","chapter":"Embryology","difficulty":"Moderate","source":"Anatomy","sourceNo":289,"q":"Remnant of notochord is ?","o":["Annulus fibrosus","Nucleus pulposus","Ligament flavum","Intertransverse ligament"],"a":1,"e":"Ans. is ''b'' i.e., Nucleus pulposus Notochord is a bud like structure formed by epihlast cells extending from cranial end of primitive streak to caudal endof prochordal plate, in between the ectoderm and endoderm. Siginificances of notochord includes following :- It defines the axis of embryo. It functions as the primary inductor, inducing the overlying ectoderm to develop into neural plate (the primordium of CNS). It serves as the basis for development of axial skeleton. The notochord is an intricate structure around which vertebral column is formed and indicates future site of vertebral bodies. However, the notochord does not give rise to vertebral column, after development of vertebral bodies, the notochord degenerates and disappears, but parts of it persist as the nucleus pulposus of intervertebral disc.","pyqMatches":[{"year":"2014","no":117,"q":"Remnant of notochord is ?","o":["Annulus fibrosus","Nucleus pulposus","Ligament flavum","Intertransverse ligament"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (290, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 290, '{"id":290,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":290,"q":"Structure passing deep to flexor retinaculum is ?","o":["Post tibial artery","Long saphenous vein","Tibialis ant. tendon","Peroneus tertius"],"a":0,"e":"Ans. is ''a'' i.e., Post tibial artery","pyqMatches":[{"year":"2013","no":48,"q":"Structure passing deep to flexor retinaculum is ?","o":["Post tibial artery","Long saphenous vein","Tibialis ant. tendon","Peroneus tertius"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (291, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 291, '{"id":291,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":291,"q":"Which muscles is known as ''Triceps surae''","o":["Gastro-soleus","Popliteus","EHL","EDL"],"a":0,"e":"Ans. is ''a'' i.e., Gastro-soleus Gastrocnemius and soleus together (gastro-soleus) are known as triceps surae. Soleus is known as peripheral heart helping in venous return from lower limb","pyqMatches":[{"year":"2013","no":49,"q":"Which muscles is known as ''Triceps surae''","o":["Gastro-soleus","Popliteus","EHL","EDL"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (292, 'Anatomy', 'Upper Limb', 'Moderate', 'Anatomy', 292, '{"id":292,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Moderate","source":"Anatomy","sourceNo":292,"q":"All are true regarding axillary lymph nodes except?","o":["Posterior group lies along subscapular vessels","Lateral group lies along lateral thoracic vessels","Apical group lies along axillary vessels","Apical group is terminal lymph nodes"],"a":1,"e":"Ans. is ''b'' i.e., Lateral group lies along lateral thoracic vessels Axillary lymph nodes The axillary lymph nodes are divided into 5 groups :?","pyqMatches":[{"year":"2013","no":30,"q":"All are true regarding axillary lymph nodes except?","o":["Posterior group lies along subscapular vessels","Lateral group lies along lateral thoracic vessels","Apical group lies along axillary vessels","Apical group is terminal lymph nodes"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (293, 'Anatomy', 'Thorax', 'Moderate', 'Anatomy', 293, '{"id":293,"subject":"Anatomy","chapter":"Thorax","difficulty":"Moderate","source":"Anatomy","sourceNo":293,"q":"Thoracic duct does not drains ?","o":["Right upper part of body","Left upper part of body","Right lower part of body","Left lower part of body"],"a":0,"e":"Ans. is ''a'' i.e., Right upper part of body Thoracic duct Thoracic duct is also called as Pecquet duct. It is the largest lymphatic duct in body, about 45 cm (18 inches) long. It has a beaded appearance because of the presence of many valves in its lumen. Thoracic duct begins as a continuation of the upper end of the cisterna chyli near the lower border of T12 vertebra and enters the thorax through the aortic opening of diaphragm (at T12). It then ascends through the posterior mediastinum and at T5 level crosses from right side to the left side and ascends along left margin of oesophagus to enter the neck. At the level of C7 vertebrae, arches towards left side to open into left brachiocephalic vein at the angle of union of left subclavian and left internal jugular veins. Thoracic duct receives lymph from both halves of the body below the diaphragm and the left half above the diaphragm. Its tributaries are :-","pyqMatches":[{"year":"2013","no":68,"q":"Thoracic duct does not drains ?","o":["Right upper part of body","Left upper part of body","Right lower part of body","Left lower part of body"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (294, 'Anatomy', 'Thorax', 'Moderate', 'Anatomy', 294, '{"id":294,"subject":"Anatomy","chapter":"Thorax","difficulty":"Moderate","source":"Anatomy","sourceNo":294,"q":"Not true about right bronchus","o":["Shorter","Wider","More horizontal","In the line of trachea"],"a":2,"e":"Ans. is ''c'' i.e., More horizontal Trachea bifurcates at Carina (at lower border of T4 vertebra at T4-T, disc space) into right and left principal (primary) bronchi. Right principal bronchus is wider, shorter (2.5 cm long), and more vertical in the line of trachea (25° with median plane. Therefore a foreign body is most likely to lodge in the right bronchus. Right bronchus divides into epiarterial and hyparterial bronchi, passing respectively above and below the pulmonary artery, before entering the hilum. Left principal bronchus is narrower, longer (5 cm long) and more horizontal (45° with median plane). Left bronchus crosses in front of the esophagus producing a slight constriction. Inside the lung it divides into 2 lobar bronchi: upper and lower.","pyqMatches":[{"year":"2013","no":67,"q":"Not true about right bronchus","o":["Shorter","Wider","More horizontal","In the line of trachea"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (295, 'Anatomy', 'Thorax', 'Moderate', 'Anatomy', 295, '{"id":295,"subject":"Anatomy","chapter":"Thorax","difficulty":"Moderate","source":"Anatomy","sourceNo":295,"q":"All are true about mammary gland, except ?","o":["Is a modified sweat gland","Extends from 2nd to 6th rib vertically","Supplied by internal mammary artery","Nipple is supplied by 6th intercostal nerve"],"a":3,"e":"Ans. is ''d'' i.e., Nipple is supplied by 6th intercostal nerve Mammary gland Breast (mammary gland) is a modified sweat gland present in the superficial fascia of pectoral region. Vertically it extend from 2nd to 6th ribs at midclavicular line and horizonal extent is from sternal margin to midaxillary line at the level of 4th rib Arterial supply of breast includes ? Perforating branches of internal mammary artery in II,III, IV intercostal spaces. Thoracoacromial, lateral thoracic and superior thoracic branches of axillary. Mammary branches, from 2nd, 3rd and 4th posterior intercostal arteries. Venous Drainage There is an anastomotic circle of veins around the base of nipple-the circulus venosus of Haller. Veins from this and from the glandular tissue radiate to the circumference of the gland and drain into axillary, internal mammary and posterior intercostal veins. Nerve supply Sensory and sympathetic innervation is via anterior and lateral cutaneous branches of 4th,5th and 6th intercostal nerves. Nipple is mainly innervated by the 4th intercostal nerve.","pyqMatches":[{"year":"2013","no":31,"q":"All are true about mammary gland, except ?","o":["Is a modified sweat gland","Extends from 2nd to 6th rib vertically","Supplied by internal mammary artery","Nipple is supplied by 6th intercostal nerve"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (296, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 296, '{"id":296,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":296,"q":"The nerve supply of nail bed of index finger is ?","o":["Superficial br of radial nerve","Deep br of radial nerve","Median nerve","Ulnar nerve"],"a":2,"e":"Ans. is ''c'' i.e., Median nerve","pyqMatches":[{"year":"2013","no":32,"q":"The nerve supply of nail bed of index finger is ?","o":["Superficial br of radial nerve","Deep br of radial nerve","Median nerve","Ulnar nerve"],"a":2,"source":"NEET_2013_Paper.pdf"},{"year":"2015","no":14,"q":"The nerve supply of nail bed of index finger is ?","o":["Superficial br of radial nerve","Deep br of radial nerve","Median nerve","Ulnar nerve"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2013","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (297, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 297, '{"id":297,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":297,"q":"The blood supply to femoral head is mostly by ?","o":["Lateral epiphyseal artery","Medial epiphyseal artery","Ligamentous teres artery","Profunda femoris"],"a":3,"e":"Ans. is ''d'' i.e., Profunda femoris Arterial supply of femoral head?","pyqMatches":[{"year":"2013","no":50,"q":"The blood supply to femoral head is mostly by ?","o":["Lateral epiphyseal artery","Medial epiphyseal artery","Ligamentous teres artery","Profunda femoris"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (298, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 298, '{"id":298,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":298,"q":"All pass through jugular foramen except","o":["Emissary vein","Vagus nerve","Mandibular nerve","Internal jugular vein"],"a":2,"e":"Ans. is ''c'' i.e., Mandibular nerve","pyqMatches":[{"year":"2013","no":92,"q":"All pass through jugular foramen except","o":["Emissary vein","Vagus nerve","Mandibular nerve","Internal jugular vein"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (299, 'Anatomy', 'Upper Limb', 'Moderate', 'Anatomy', 299, '{"id":299,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Moderate","source":"Anatomy","sourceNo":299,"q":"Bounderies of anatomical snuff box are all except","o":["APL","EPL","EPB","ECU"],"a":3,"e":"Ans. is ''d'' i.e., ECU Anatomical Snuffbox Triangular depression on the dorsal and radial aspect of the hand become visible when thumb is fully extended. Boundaries Medial/Posterior → Tendon of the extensor pollicis longus. Lateral/Anterior → Tendon of the extensor pollicis brevis and abductor pollicis longus. Roof Skin and → fascia with beginning of cephalic vein and crossed by superficial branch of the radial nerve. Floor → Styloid process of radius, trapezium, scaphoid and base of 1st metacarpal. Contents → The radial artery.","pyqMatches":[{"year":"2013","no":33,"q":"Bounderies of anatomical snuff box are all except","o":["APL","EPL","EPB","ECU"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (300, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 300, '{"id":300,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":300,"q":"Medial boundry of Cubital fossa ?","o":["Brachioradialis","Pronator teres","Supinator","None"],"a":1,"e":"Ans. is ''b'' i.e., Pronator teres","pyqMatches":[{"year":"2015","no":10,"q":"Medial boundry of Cubital fossa ?","o":["Brachioradialis","Pronator teres","Supinator","None"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (301, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 301, '{"id":301,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":301,"q":"Superficial perineal space contains ?","o":["Sphincter urethrae muscle","Ischiocavernosus muscle","Deep transverse perinei muscle","Bulbourethral gland"],"a":1,"e":"Ans. is ''b'' i.e., Ischiocavernosus muscle","pyqMatches":[{"year":"2015","no":93,"q":"Superficial perineal space contains ?","o":["Sphincter urethrae muscle","Ischiocavernosus muscle","Deep transverse perinei muscle","Bulbourethral gland"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (302, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 302, '{"id":302,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":302,"q":"Caudate lobe of liver is ?","o":["I","III","IV","VI"],"a":0,"e":"Ans. is ''a'' i.e., I The caudate lobe (posterior hepatic segment I, Spigelian lobe) is situated upon the postero-superior surface of the liver on the right lobe of the liver, opposite the tenth and eleventh thoracic vertebrae.","pyqMatches":[{"year":"2013","no":74,"q":"Caudate lobe of liver is ?","o":["I","III","IV","VI"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (303, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 303, '{"id":303,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":303,"q":"Spinal cord develops from ?","o":["Neural tube","Mesencephalon","Rhombencephalon","Prosencephalon"],"a":0,"e":"Ans. is ''a'' i.e., Neural tube Nervous system develops from ectoderm (neuroectoderm). Nervous system develops from neural tube which in turn develops by process of neurulation, i.e. formation of neural plate and its infolding into neural tube. Structures formed from neural tube are :?","pyqMatches":[{"year":"2013","no":3,"q":"Spinal cord develops from ?","o":["Neural tube","Mesencephalon","Rhombencephalon","Prosencephalon"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (304, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 304, '{"id":304,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":304,"q":"Hyoid lies at the level of ?","o":["C3","C,","C7","T2"],"a":0,"e":"Ans. is ''a'' i.e., C3 Surface anatomy of larynx are : C, Level of body of hyoid and its greater cornu. C3 -C, Junction Level of upper border of thyroid cartilage and bifurcation of common carotid artery. C4- C, Junction Level of thyroid cartilage. C6 Level of cricoid cartilage.","pyqMatches":[{"year":"2013","no":17,"q":"Hyoid lies at the level of ?","o":["C3","C,","C7","T2"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (305, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 305, '{"id":305,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":305,"q":"Which of the following muscle is not in the pectoral region ?","o":["Pectoralis major","Infraspinatus","Pectoralis minor","Subclavius"],"a":1,"e":"Ans. is ''b'' i.e., Infraspinatus","pyqMatches":[{"year":"2013","no":34,"q":"Which of the following muscle is not in the pectoral region ?","o":["Pectoralis major","Infraspinatus","Pectoralis minor","Subclavius"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (306, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 306, '{"id":306,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":306,"q":"True about linea aspera ?","o":["Forms lateral border of femur","Forms medial border of femur","Continues as gluteal tuberostiy","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., Continues as gluteal tuberostiy","pyqMatches":[{"year":"2013","no":52,"q":"True about linea aspera ?","o":["Forms lateral border of femur","Forms medial border of femur","Continues as gluteal tuberostiy","None of the above"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (307, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 307, '{"id":307,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":307,"q":"Hunterian perforators are seen in ?","o":["Upper thigh","Lower thigh","Calf","Mid thigh"],"a":3,"e":"Ans. is ''d'' i.e., Mid thigh Mid-thigh (Mid-hunter) - Adductor canal- Great saphenous with femoral Hunter perforator (Hunterian perforator or adductor canal perforator) is seen in mid thigh.","pyqMatches":[{"year":"2014","no":1590,"q":"Hunterian perforators are seen in ?","o":["Upper thigh","Lower thigh","Calf","Mid thigh"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (308, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 308, '{"id":308,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":308,"q":"Internal spermatic fascia is derived from ?","o":["External oblique muscle","Internal oblique muscle","Fascia transversalis","Colle''s fascia"],"a":2,"e":"Ans. is ''c'' i.e., Fascia transversalis Layers of the scrotum The scrotum is made up of the following layers from outside inwards.","pyqMatches":[{"year":"2013","no":78,"q":"Internal spermatic fascia is derived from ?","o":["External oblique muscle","Internal oblique muscle","Fascia transversalis","Colle''s fascia"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (309, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 309, '{"id":309,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":309,"q":"Portal vein supplies ?","o":["Spleen","Liver","Pancreas","Colon"],"a":1,"e":"Ans. is ''b'' i.e., Liver Portal vein is a vein, still it supply blood to liver (usually a vein drains blood from an organ or tissue). The liver has dual blood supply :- 20% of blood supply is through the hepatic artery. 80% of blood supply is through the portal vein.","pyqMatches":[{"year":"2013","no":79,"q":"Portal vein supplies ?","o":["Spleen","Liver","Pancreas","Colon"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (310, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 310, '{"id":310,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":310,"q":"Collecting part of kidney develops from ?","o":["Pronephrons","Mesonephros","Metanephros","Ureteric bud"],"a":3,"e":"Ans. is ''d'' i.e., Ureteric bud Development of kidney Kidneys develop from two sources : Metanephros (metanephric mesoderm or blastema) : It is the lowest part of nephrogenic cord which is derived from intermediate mesoderm. It forms the excretory unit of kidney i.e. glomeruls, proximal convoluted tubule, loop of henle and distal convoluted tubule. Ureteric bud : It arises from lower part of mesonephric duct. It forms collecting part of kidney (pelvis, major calyes, minor calyces, collecting tubules) and ureter.","pyqMatches":[{"year":"2013","no":4,"q":"Collecting part of kidney develops from ?","o":["Pronephrons","Mesonephros","Metanephros","Ureteric bud"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (311, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 311, '{"id":311,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":311,"q":"Nerve running along with profunda brachii artery, in spiral groove ?","o":["Ulnar","Median","Radial","None"],"a":2,"e":"Ans. is ''c'' i.e., Radial Profunda brachii is a branch of brachial artery. It accompanies radial nerve in spiral groove. Branches of profunda brachii artery are :?","pyqMatches":[{"year":"2013","no":36,"q":"Nerve running along with profunda brachii artery, in spiral groove ?","o":["Ulnar","Median","Radial","None"],"a":2,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":9,"q":"Nerve running along with profunda brachii artery, in spiral groove ?","o":["Ulnar","Median","Radial","None"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (312, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 312, '{"id":312,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":312,"q":"In which of the following vessels transverse mesocolon seen ?","o":["Right colic artery","Left colic artery","Middle colic artery","Iliocolic artery"],"a":2,"e":"Ans. is ''c'' i.e., Middle colic artery Mesentery of gut Vessels contained by mesentery Mesentery proper (Mesentery of small intestine) Jejunal and Ileal branches of superior mesenteric vessels Transverse mesocolon Middle colic vessel Mesoappendix Appendicular vessels Sigmoid mesocolon Sigmoid vessels","pyqMatches":[{"year":"2015","no":83,"q":"In which of the following vessels transverse mesocolon seen ?","o":["Right colic artery","Left colic artery","Middle colic artery","Iliocolic artery"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (313, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 313, '{"id":313,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":313,"q":"Main blood supply to the head and neck of femur comes from","o":["Lateral circumflex femoral Artery","Medial circumflex femoral Artery","Artery of Ligamentum Teres","Popliteal Artery"],"a":1,"e":"Ans. is ''b'' i.e., Medial circumflex femoral Artery The medial circumflex femoral artery along with its retinacular and epiphyseal branches supplies most of the blood supply to the head and neck of femur. Arterial supply of femoral head has been explained in details in previous sessions.","pyqMatches":[{"year":"2013","no":51,"q":"Main blood supply to the head and neck of femur comes from","o":["Lateral circumflex femoral Artery","Medial circumflex femoral Artery","Artery of Ligamentum Teres","Popliteal Artery"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (314, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 314, '{"id":314,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":314,"q":"Pubic symphysis is which type of joint ?","o":["Gomphosis","Fibrous joint","Primary cartilaginous","Secondary cartilaginous"],"a":3,"e":"Ans. is ''d'' i.e., Secondary cartilaginous Pubic symphysis is a secondary cartilaginous joint (symphses or fibrocartilaginous joint).","pyqMatches":[{"year":"2013","no":18,"q":"Pubic symphysis is which type of joint ?","o":["Gomphosis","Fibrous joint","Primary cartilaginous","Secondary cartilaginous"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (315, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 315, '{"id":315,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":315,"q":"which level the somites initially form ?","o":["Thoracic level","Cervical level","Lumbar level","Sacral level"],"a":1,"e":"Ans. is ''b'' i.e., Cervical level The first pair of somites develop a short distance posterior to the cranial end of the notochord, and the rest of the somites from caudally. \"By the 20\" day, the first pair of somites have formed in neck region.\" Textbook of embryology Paraxial mesoderm differentiates into somites. By the end of 20th day, the first pair of somites have formed in neck region. After this, about 3 pairs of somites are formed per day and by the end of 5\" week about 42-44 somite pairs are formed (4-occipital, 8-cervical, 12-thoracic, 5-lumbar, 5-sacral and 8-10 cooccygeal). Somites are further differentiated into :- Dermatomyotome :- Give rise to skeletal muscles and dermis. Sclerotomes :- Give rise to vertebral column.","pyqMatches":[{"year":"2013","no":5,"q":"which level the somites initially form ?","o":["Thoracic level","Cervical level","Lumbar level","Sacral level"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (316, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 316, '{"id":316,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":316,"q":"Double inferior vena cava is formed due to?","o":["Persistence of sacrocardinal veins","Persistance of supracardinal veins","Persistance of subcardinal veins","Persistance of both supracardinal and subcardinal veins"],"a":3,"e":"Ans. is ''d'' i.e., Persistance of both supracardinal and subcardinal veins Developmental anomalies of veins A. Anomalies of SVC Left superior vena cava is formed when left anterior cardinal and common cardinal veins persist and the right ones obliterate. Left SVC opens into right atrium through the coronary sinus. Double superior vena cava occurs due to persistence of left anterior cardinal vein. The right SVC opens directly into right atrium while left one opens through coronary sinus. B. Anomalies of IVC Absence of inferior vena cava above renal veins occurs when the anastomotic channel between right subcardinal vein and right lepatocardinal channel fails to develop. Double inferior vena cava is formed below renal veins due to persistence of both the subcardinal and supracardinal veins below the kidney. Left inferior vena cava, i.e. infrarenal part of IVC is formed on left side instead of right. Preureteric IVC is formed when infrarenal part of IVC develops from subcardinal vein (which lies anterior to ureter) instead of supracardinal vein (which lies posterior to ureter).","pyqMatches":[{"year":"2013","no":6,"q":"Double inferior vena cava is formed due to?","o":["Persistence of sacrocardinal veins","Persistance of supracardinal veins","Persistance of subcardinal veins","Persistance of both supracardinal and subcardinal veins"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (317, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 317, '{"id":317,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":317,"q":"All of the following muscles have dual nerve supply except ?","o":["Subscapularis","Pectoralis major","Pronator teres","Flexor digitorum profundus"],"a":2,"e":"Ans. is ''c'' i.e., Pronator teres","pyqMatches":[{"year":"2013","no":37,"q":"All of the following muscles have dual nerve supply except ?","o":["Subscapularis","Pectoralis major","Pronator teres","Flexor digitorum profundus"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (318, 'Anatomy', 'Upper Limb', 'Moderate', 'Anatomy', 318, '{"id":318,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Moderate","source":"Anatomy","sourceNo":318,"q":"A person had injury to right upper limb he is not able to extend fingers but able to extend wrist and elbow. Nerve injured is ?","o":["Radial","Median","Ulnar","Posterior interosseus"],"a":3,"e":"Ans. is ''d'' i.e., Posterior interosseus In posterior interosseus nerve injury, wrist extension is preserved due to spared ECRL, hence there is no wrist drop. There is loss of extension of metacarpophalangeal joints, hence thumb and finger drop occurs. o In radial nerve injury, there is wrist drop. Clinical features of radial nerve palsy Clinical features depend upon the site of lesion.","pyqMatches":[{"year":"2013","no":25,"q":"A person had injury to right upper limb he is not able to extend fingers but able to extend wrist and elbow. Nerve injured is ?","o":["Radial","Median","Ulnar","Posterior interosseus"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (319, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 319, '{"id":319,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":319,"q":"The retina is an out growth of the ?","o":["Mesencephalon","Diencephalon","Telencephalon","Pons"],"a":1,"e":"Ans. is ''b'' i.e., Diencephalon Diancephalon forms - optic cup and stalk, pituitary, thalmus, hypothalmus, epithalmus, pineal gland (or epiphysis), and 3rd ventricle (most part). Retina develops from walls of optic cup. The outer thinner layer becomes retinal pigmented epithelium and inner thicker layer forms neural layer of retina. Forebrain (prosencephalon) consists of telencephalon (anterior or rostral part) and diencephalon (posterior or caudal part).","pyqMatches":[{"year":"2013","no":8,"q":"The retina is an out growth of the ?","o":["Mesencephalon","Diencephalon","Telencephalon","Pons"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (320, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 320, '{"id":320,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":320,"q":"All are contents of occipital triangle except ?","o":["Great auricular nerve","Suprascapular nerve","Lesser occipital nerve","Occipital artery"],"a":1,"e":"Ans. is ''b'' i.e., Suprascapular nerve","pyqMatches":[{"year":"2013","no":93,"q":"All are contents of occipital triangle except ?","o":["Great auricular nerve","Suprascapular nerve","Lesser occipital nerve","Occipital artery"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (321, 'Anatomy', 'Upper Limb', 'Moderate', 'Anatomy', 321, '{"id":321,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Moderate","source":"Anatomy","sourceNo":321,"q":"Contents of midpalmar space are all except","o":["2nd lumbrical","FDP of 3rd finger","1st lumbrical","FDP of 4th finger"],"a":2,"e":"Ans. is ''c'' i.e., 1st lumbrical Boundaries of midpalmar space are: Anterior- Flexor tendons of 3rd, 4th , and 5th fingers 2nd, 3rd and 4th lumbricals Palmar aponeurosis Posterior- Fascia covering interossei and metacarpals Lateral - Intermediate palmar septum Medial- Medial palmar septum 1st lumbrical is present in the thenar space","pyqMatches":[{"year":"2013","no":39,"q":"Contents of midpalmar space are all except","o":["2nd lumbrical","FDP of 3rd finger","1st lumbrical","FDP of 4th finger"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (322, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 322, '{"id":322,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":322,"q":"Axillary nerve is accompanied by which artery ?","o":["Axillary","Subscapular","Anterior circumflex humeral","Posterior circumflex humeral"],"a":3,"e":"Ans. is ''d'' i.e., Posterior circumflex humeral Axillary nerve Axillary nerve is a branch of the posterior cord of brachial plexus with root value C5 and C6. It leaves the posterior wall of axilla along with the posterior circumflex humeral vessels throuth the quadrangular space. While passing through the quadrangular space it gives its first branch, an articular twig to the shoulder joint. Then it divides into?","pyqMatches":[{"year":"2013","no":40,"q":"Axillary nerve is accompanied by which artery ?","o":["Axillary","Subscapular","Anterior circumflex humeral","Posterior circumflex humeral"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (323, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 323, '{"id":323,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":323,"q":"The roof of the olfactory region is formed by ?","o":["Nasal bone","Cribriform plate of ethmoid","Sphenoid","Temporal bone"],"a":1,"e":"Ans. is ''b'' i.e., Cribriform plate of ethmoid The olfactory mucosa lines the upper one-third of nasal cavity including the roof formed by cribriform plate and the medial and lateral walls up to the level of superior concha (turbinate).","pyqMatches":[{"year":"2013","no":94,"q":"The roof of the olfactory region is formed by ?","o":["Nasal bone","Cribriform plate of ethmoid","Sphenoid","Temporal bone"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (324, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 324, '{"id":324,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":324,"q":"Superior pancreaticoduodenal artery is a branch of?","o":["Hepatic artery","Splenic artery","Gastroduodenal artery","Inferior mesenteric artery"],"a":2,"e":"Ans. is ''c'' i.e., Gastroduodenal artery Gastroduodenal artery gives following branches :-","pyqMatches":[{"year":"2015","no":61,"q":"Superior pancreaticoduodenal artery is a branch of?","o":["Hepatic artery","Splenic artery","Gastroduodenal artery","Inferior mesenteric artery"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (325, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 325, '{"id":325,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":325,"q":"Helicine artery are branch of ?","o":["Deep artery of penis","Femoral artery","External pudendal artery","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Deep artery of penis Helicine arteries of penis are five branches of cavernosal artery (deep artery of penis) that fill sinusoidal space of corpora covernosa. Helicine arteries of uterus are extremely tortuous terminal branches of uterine artery supplying uterine muscle.","pyqMatches":[{"year":"2013","no":81,"q":"Helicine artery are branch of ?","o":["Deep artery of penis","Femoral artery","External pudendal artery","None of the above"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (326, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 326, '{"id":326,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":326,"q":"The superficial external pudendal artery is a branch of ?","o":["Femoral artery","External iliac artery","Internal iliac artery","Aorta"],"a":0,"e":"Ans. is ''a'' i.e., Femoral artery Femoral artery It is the main artery of the lower limb. It begins as a continuation of external iliac artery below the inguinal ligament at midinguinal point midway between pubic symphysis and anterior superior iliac spine. It descends through femoral triangle and then through adductor canal. After that it ends by passing through adductor hiatus in the adductor magnus muscle to continue as popliteal artery. Branches of femoral artery are :? A. In femoral triangle","pyqMatches":[{"year":"2013","no":55,"q":"The superficial external pudendal artery is a branch of ?","o":["Femoral artery","External iliac artery","Internal iliac artery","Aorta"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (327, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 327, '{"id":327,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":327,"q":"Nerve supply to the muscles of flexor compartment of arm ?","o":["Radial nerve","Median nerve","Musculocutaneous nerve","Ulnar nerve"],"a":2,"e":"Ans. is ''c'' i.e., Musculocutaneous nerve","pyqMatches":[{"year":"2013","no":41,"q":"Nerve supply to the muscles of flexor compartment of arm ?","o":["Radial nerve","Median nerve","Musculocutaneous nerve","Ulnar nerve"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (328, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 328, '{"id":328,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":328,"q":"Tributaries of cavernous sinus are all except ?","o":["Inferior cerebral vein","Central vein of retina","Sphenoparietal sinus","Superior cerebral vein"],"a":3,"e":"Ans. is ''d'' i.e., Superior cerebral vein Tributaries (incoming channels) of cavernous sinus","pyqMatches":[{"year":"2013","no":106,"q":"Tributaries of cavernous sinus are all except ?","o":["Inferior cerebral vein","Central vein of retina","Sphenoparietal sinus","Superior cerebral vein"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (329, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 329, '{"id":329,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":329,"q":"Line from midinguinal point to adductor tubercle represent ?","o":["Inferior epigastric artery","Femoral artery","Superior epigastric artery","None of the above"],"a":1,"e":"Ans. is ''b'' i.e., Femoral artery Femoral artery enters the thigh behind the inguinal ligament at the mid-inguinal point. /t is represented by the upper two-third of a line joining the mid-inguinal point to adductor tubercle. Femoral vein has same markings as femoral artery except that the upper point is taken 1 cm medial to mid-inguinal point and lower point 1 cm lateral to adductor tubercle. Inferior epigastric vessels is represented by the upper two-third of a line joining the mid-inguinal point to umblicus.","pyqMatches":[{"year":"2013","no":56,"q":"Line from midinguinal point to adductor tubercle represent ?","o":["Inferior epigastric artery","Femoral artery","Superior epigastric artery","None of the above"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (330, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 330, '{"id":330,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":330,"q":"Pineal gland forms ?","o":["Floor of third ventricle","Anterior wall of third ventricle","Posterior wall of third ventricle","Roof of third ventricle"],"a":2,"e":"Ans. is ''c'' i.e., Posterior wall of third ventricle Boundries of third ventricle are :-","pyqMatches":[{"year":"2013","no":107,"q":"Pineal gland forms ?","o":["Floor of third ventricle","Anterior wall of third ventricle","Posterior wall of third ventricle","Roof of third ventricle"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (331, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 331, '{"id":331,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":331,"q":"Epithelial lining of urinary bladder ?","o":["Squamous","Transitional","Cuboidal","Columnar"],"a":1,"e":"Ans. is ''b'' i.e., Transitional Urothelium (transitional epithelium) is found in renal pelvis, calyces, ureter, urinary bladder, proximal part of urethra.","pyqMatches":[{"year":"2013","no":19,"q":"Epithelial lining of urinary bladder ?","o":["Squamous","Transitional","Cuboidal","Columnar"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2016","no":9,"q":"Epithelial lining of urinary bladder ?","o":["Squamous","Transitional","Cuboidal","Columnar"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2013","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (332, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 332, '{"id":332,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":332,"q":"Chorda tympani is a part of ?","o":["Middle ear","Inner ear","External auditory canal","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Middle ear Contents of middle ear Contents of middle ear (tympanic cavity) are :?","pyqMatches":[{"year":"2013","no":95,"q":"Chorda tympani is a part of ?","o":["Middle ear","Inner ear","External auditory canal","None of the above"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (333, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 333, '{"id":333,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":333,"q":"Greater petrosal nerve is formed from ?","o":["Geniculate ganglion","Plexus around ICA","Plexus around middle meningeal artery","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Geniculate ganglion Petrosal nerves Greater petrosal nerve First branch of facial nerve Arises from geniculate ganglion In foramen lacerum it joins deep petorsal nerve and forms the nerve to pterygoid canal Supplies lacrimal glands, nose, mucosal glands of pharynx, palate. Lesser petrosal nerve Branch of 9th cranial nerve through tympanic plexus (passes via otic ganglion) It suplies parotid gland. Deep petrosal nerve It is a branch of sympathetic plexus around internal carotid artery. It contains cervical sympathetic fibers. External petrosal nerve It is an inconsistaent branch of sympathetic plexus around middle meningeal artery.","pyqMatches":[{"year":"2015","no":114,"q":"Greater petrosal nerve is formed from ?","o":["Geniculate ganglion","Plexus around ICA","Plexus around middle meningeal artery","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (334, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 334, '{"id":334,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":334,"q":"Base of the heart is formed by ?","o":["Right atrium","Right ventricle","Left atrium","Left ventricle"],"a":2,"e":"Ans. is `c > a'' i.e., Left atrium > Right atrium Base (posterior surface) is formed mainly by left atrium and partly by right atrium. It is separated from T5 to T8 vertebrae by pericardium The apex (the most inferior, anterior, and lateral part as the heart lies in situ) is located on the midclavicular line, in the fifth intercostal space. It is formed by the left ventricle. Anterior (sternocostal) surface is formed mostly by right ventricle (major) and right auricle and partly by left ventricle and left auricle.","pyqMatches":[{"year":"2015","no":51,"q":"Base of the heart is formed by ?","o":["Right atrium","Right ventricle","Left atrium","Left ventricle"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (335, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 335, '{"id":335,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":335,"q":"True about cardiac muscle is ?","o":["Spindle shaped","Large central nucleus","No gap junctions","Arranged in sheets"],"a":1,"e":"Ans. is ''b'' i.e., Large central nucleus","pyqMatches":[{"year":"2013","no":20,"q":"True about cardiac muscle is ?","o":["Spindle shaped","Large central nucleus","No gap junctions","Arranged in sheets"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (336, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 336, '{"id":336,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":336,"q":"Muscle causing supination of forearm ?","o":["Biceps brachii","Brachioradialis","FDS","Anconeus"],"a":0,"e":"Ans. is ''a'' i.e., Biceps brachii Movement Muscles causing movement Pronation Pronator quadratus (strong pronator), Pronator teres (Rapid pronator). Supination Supinator (when elbow is extended), Biceps (when elbow is flexed","pyqMatches":[{"year":"2013","no":42,"q":"Muscle causing supination of forearm ?","o":["Biceps brachii","Brachioradialis","FDS","Anconeus"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (337, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 337, '{"id":337,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":337,"q":"3rd extensor compartment of wrist contains tendon of ?","o":["ECRL","ECRB","EPL","EPB"],"a":2,"e":"Ans. C) EPL The third compartment contains the extensor pollicis longus tendon, which originates at the mid-ulna and inserts at the base of the first distal phalanx. In combination with the EPB tendon, it extends the thumb at the first carpometacarpal and first interphalangeal joints.","pyqMatches":[{"year":"2013","no":43,"q":"3rd extensor compartment of wrist contains tendon of ?","o":["ECRL","ECRB","EPL","EPB"],"a":2,"source":"NEET_2013_Paper.pdf"},{"year":"2015","no":16,"q":"3rd extensor compartment of wrist contains tendon of ?","o":["ECRL","ECRB","EPL","EPB"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2013","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (338, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 338, '{"id":338,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":338,"q":"Ligament supporting the talus is ?","o":["Spring ligament","Deltoid ligament","LCL","Cervical ligament"],"a":0,"e":"Ans. A) Spring ligament Spring ligament (Plantar calcaneonavicular ligament) connects the calcaneum with the navicular bone. However, its principal job is to provide a sling for the talus, to support the head of talus (though it has no attachment to talus). This aids in supporting the weight of the body. Weaknes or lengthening along this ligament can cause flat foot","pyqMatches":[{"year":"2014","no":29,"q":"Ligament supporting the talus is ?","o":["Spring ligament","Deltoid ligament","LCL","Cervical ligament"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (339, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 339, '{"id":339,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":339,"q":"Upper two posterior intercostal arteries arise from ?","o":["Aorta","Superior intercostal artery","Internal mammary artery","Bronchial artery"],"a":1,"e":"Ans. B) Superior intercostal artery The 1st and 2nd posterior intercostal arteries arise from the supreme intercostal artery, a branch of the costocervical trunk of the subclavian artery. The lower nine arteries are the aorticintercostals, so called because they arise from the back of the thoracic aorta.","pyqMatches":[{"year":"2013","no":69,"q":"Upper two posterior intercostal arteries arise from ?","o":["Aorta","Superior intercostal artery","Internal mammary artery","Bronchial artery"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (340, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 340, '{"id":340,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":340,"q":"Which thalamic nuclei connects with neocortex?","o":["Palvinar","Intralaminar","Anterior","All"],"a":3,"e":"Ans. is ''d'' i.e., All","pyqMatches":[{"year":"2013","no":108,"q":"Which thalamic nuclei connects with neocortex?","o":["Palvinar","Intralaminar","Anterior","All"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (341, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 341, '{"id":341,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":341,"q":"Stapedius nerve is a branch of ?","o":["Trigeminal nerve","Facial nerve","Vagus nerve","None"],"a":1,"e":"Ans. is ''b'' i.e., Facial nerve Branches of facial nerve","pyqMatches":[{"year":"2013","no":96,"q":"Stapedius nerve is a branch of ?","o":["Trigeminal nerve","Facial nerve","Vagus nerve","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (342, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 342, '{"id":342,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":342,"q":"Deep injury of neck always involves","o":["Platysma","Tropezius","Sternocleidomastoid","Longus colli"],"a":0,"e":"Ans. is ''a'' i.e., Platysma The neck is invested by two major fascial layers :?","pyqMatches":[{"year":"2013","no":97,"q":"Deep injury of neck always involves","o":["Platysma","Tropezius","Sternocleidomastoid","Longus colli"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (343, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 343, '{"id":343,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":343,"q":"Glomus cells are found in -","o":["Bladder","Brain","Chemoreceptors","Kidney"],"a":2,"e":"Ans. is ''c'' i.e., Chemoreceptors Arterial chemoreceptors consist of globular aggregations of chemoreceptive cells (glomus cells), and supportive cells, separated from one another by fibrous tissue septa. In these setpa and between glomus cells, numerous capillaries and nerve fibers are seen. The glomus cells have the structure of endocrine amine hormone secreting cells.","pyqMatches":[{"year":"2012","no":517,"q":"Glomus cells are found in","o":["Bladder","Brain","Chemoreceptors","Kidney"],"a":2,"source":"NEET_2012_Paper.pdf"},{"year":"2013","no":110,"q":"Glomus cells are found in","o":["Bladder","Brain","Chemoreceptors","Kidney"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2012","2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (344, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 344, '{"id":344,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":344,"q":"Most dependent part of abdomen in standing position is ?","o":["Vesicouterine pouch","Pouch of douglas","Rectouterine pouch","b & c"],"a":3,"e":"Ans. is ''d'' i.e., b & c In males, rectovesicle pouch of peritoneum intervenes between rectum and urinary bladder. Obliterated part of rectovesical pouch is called fascia of Denonviller''s which separates posterior surface of prostate from rectum. In females rectouterine pouch (pouch of Douglas) lies between rectum (posteriorly) and uterus and posterior fornix of vagina (anteiorly). In females vesicouterine pouch lies between urinary bladder (anteriorly) and uterus posteriorly. The rectovesical pouch (in males) and rectouterine pouch (in females) are the most dependent portions of peritoneal cavity in erect posture","pyqMatches":[{"year":"2013","no":82,"q":"Most dependent part of abdomen in standing position is ?","o":["Vesicouterine pouch","Pouch of douglas","Rectouterine pouch","b & c"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (345, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 345, '{"id":345,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":345,"q":"Carina is situated at which level ?","o":["T3","T4","T6","T9"],"a":0,"e":"Ans. is ''13'' i.e., T4 Trachea bifurcates at carina, at the level of lower border of T4 or T4- Ts disc space. Structure Cervico thoracic level Tracheal bifurcation T4-T5 Arch of aorta Begins and ends at T4 Xiphoid process T9 Splenic axis Along 10th rib Carotid bifurcation, Hyoid bone C3 Upper border of thyroid cartilage C4 Level of cricoids cartilage C6 Lumbar level Celiac trunk T12 - L I Superior mesenteric artery Ll Transpyloric plane Lower border of Ll","pyqMatches":[{"year":"2013","no":71,"q":"Carina is situated at which level ?","o":["T3","T4","T6","T9"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (346, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 346, '{"id":346,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":346,"q":"Pelvic pain is mediated by ?","o":["Pudendal nerve","Sciatic nerve","Autonomic nerves","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., Autonomic nerves Visceral afferent fibers of pelvis travel with autonomic nerve fibers. Visceral afferent fibers conducting reflexive sensations (information that does not reach consciousness) travel with parasympathetic fibers to spinal sensory ganglia of S2- S4. The route taken by visceral afferent fibers conducting pain sensation differs in relation to an imaginary line, the pelvic pain line, that corresponds to the inferior limit of peritoneum, except in case of large intestine, where pain line occurs midway along length of sigmoid colon. Visceral afferent fibers that transmit pain sensations from the viscera inferior to pelvic pain line travel in parasympathetic fibers of the spinal ganglia S, - S4 (via pelvic splanchnic nerve or nerve erigentes). Visceral afferent fiber conducting pain from the viscera superior to pelvic pain line follow the sympatheitc fibers reterogradely to inferior thoracic and superior lumbar (Ti - Li 0,2 )spinal ganglia.","pyqMatches":[{"year":"2013","no":83,"q":"Pelvic pain is mediated by ?","o":["Pudendal nerve","Sciatic nerve","Autonomic nerves","None of the above"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (347, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 347, '{"id":347,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":347,"q":"Posterior relation of neck of pancreas ?","o":["IVC","Origin of postal vein","Aorta","Common bile duct"],"a":1,"e":"Ans. is ''b'' i.e., Origin of portal vein","pyqMatches":[{"year":"2015","no":57,"q":"Posterior relation of neck of pancreas ?","o":["IVC","Origin of postal vein","Aorta","Common bile duct"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (348, 'Anatomy', 'Miscellaneous', 'Moderate', 'Anatomy', 348, '{"id":348,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anatomy","sourceNo":348,"q":"Protrusion of tongue not possible in damage of ?","o":["Styloglossus","Hyoglossus","Palatoglossus","Genioglossus"],"a":3,"e":"Ans. is ''d i.e., Genioglossus","pyqMatches":[{"year":"2013","no":99,"q":"Protrusion of tongue not possible in damage of ?","o":["Styloglossus","Hyoglossus","Palatoglossus","Genioglossus"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (349, 'Anatomy', 'Head & Neck', 'Moderate', 'Anatomy', 349, '{"id":349,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Moderate","source":"Anatomy","sourceNo":349,"q":"Terminal branches of internal carotid artery are all except ?","o":["Anterior cerebral artery","Middle cerebral artery","Posterior communicating artery","Cavernous artery"],"a":3,"e":"Ans. is ''d > c'' i.e., Cavernous artery > Posterior communicating artery This question has not been framed properly. Internal carotid artery has two terminal branches, i.e. ICA ends by dividing into :?","pyqMatches":[{"year":"2013","no":100,"q":"Terminal branches of internal carotid artery are all except ?","o":["Anterior cerebral artery","Middle cerebral artery","Posterior communicating artery","Cavernous artery"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (350, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 350, '{"id":350,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":350,"q":"Little''s area is ?","o":["Anteroinferior lateral wall","Anteroinferior nasal septum","Posteroinferior lateral wall","Posteroinferior nasal septum."],"a":1,"e":"Ans. is ''b'' i.e., Anteroinferior nasal septum Little''s area is situated in the anterior inferior part of nasal septum, just above the vestibule. Woodruff''s plexus is situated in the posterior inferior part of lateral wall","pyqMatches":[{"year":"2012","no":113,"q":"Little''s area is ?","o":["Anteroinferior lateral wall","Anteroinferior nasal septum","Posteroinferior lateral wall","Posteroinferior nasal septum."],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (351, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 351, '{"id":351,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":351,"q":"Anterosuperior sternal part of heart is made up of ?","o":["Right atrium and auricle","Left atrium.","Left ventricle","Right ventricle"],"a":3,"e":"Ans. is ''d'' i.e., Right ventricle","pyqMatches":[{"year":"2013","no":65,"q":"Anterosuperior sternal part of heart is made up of ?","o":["Right atrium and auricle","Left atrium.","Left ventricle","Right ventricle"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (352, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 352, '{"id":352,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":352,"q":"Arch of Aorta develops from which aortic arch artery ?","o":["Right Pt","Right 3rd","Left 4th","Left 3rd"],"a":2,"e":"Ans. is ''c'' i.e., Left 4th","pyqMatches":[{"year":"2013","no":9,"q":"Arch of Aorta develops from which aortic arch artery ?","o":["Right Pt","Right 3rd","Left 4th","Left 3rd"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (353, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 353, '{"id":353,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":353,"q":"Skin and fascia of great toe drains into ?","o":["Superficial inguinal lymph nodes","External iliac nodes","Internal iliac nodes","Deep inguinal nodes"],"a":0,"e":"Ans. is ''a'' i.e., Superficial inguinal lymph nodes","pyqMatches":[{"year":"2013","no":57,"q":"Skin and fascia of great toe drains into ?","o":["Superficial inguinal lymph nodes","External iliac nodes","Internal iliac nodes","Deep inguinal nodes"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (354, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 354, '{"id":354,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":354,"q":"Implantation occurs at ?","o":["2-3 days","6-7 days","15-20 days","20-25 days"],"a":1,"e":"Ans. is ''b'' i.e., 6-7 days","pyqMatches":[{"year":"2014","no":192,"q":"Implantation occurs at ?","o":["2-3 days","6-7 days","15-20 days","20-25 days"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (355, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 355, '{"id":355,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":355,"q":"Lower end of femur is ossified from how many ossification centers :?","o":["1","2","3","4"],"a":0,"e":"Ans. is ''a'' i.e., 1 There are three ossification centers in the proximal femoral end located in its head, greater and lesser trochanters, whereas there exists only one ossification center in the distal femoral end.","pyqMatches":[{"year":"2013","no":58,"q":"Lower end of femur is ossified from how many ossification centers :?","o":["1","2","3","4"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (356, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 356, '{"id":356,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":356,"q":"Muscle of third arch ?","o":["Tensor tympani","Stylopharyngeus","Cricothyroid","None"],"a":1,"e":"Ans. is ''b'' i.e., Stylopharyngeus Stylopharyngeus is the muscle of 3rd pharyngeal arch.","pyqMatches":[{"year":"2013","no":10,"q":"Muscle of third arch ?","o":["Tensor tympani","Stylopharyngeus","Cricothyroid","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (357, 'Anatomy', 'Thorax', 'Moderate', 'Anatomy', 357, '{"id":357,"subject":"Anatomy","chapter":"Thorax","difficulty":"Moderate","source":"Anatomy","sourceNo":357,"q":"Sinus venosus receives blood from all except ?","o":["Vitelline vein","Umbilical vein","Common cardinal vein","Subcardinal vein"],"a":3,"e":"Ans. is ''d'' i.e., Subcardinal vein Sinus venosus : It is the caudal most part of tubular heart. At its lower end it presents right and left horns. Each horn receives blood from following three veins :","pyqMatches":[{"year":"2013","no":11,"q":"Sinus venosus receives blood from all except ?","o":["Vitelline vein","Umbilical vein","Common cardinal vein","Subcardinal vein"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (358, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 358, '{"id":358,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":358,"q":"Cochleate uterus is ?","o":["Large uterus","Acute anteflexion","Acute retroflexion","Large cervix"],"a":1,"e":"Ans. is ''b'' i.e., Acute anteflexion Cochleate uterus is acutely anteflexed uterus with pin hole os. It is a small adult uterus with a conical cervix and a body that is small, globular and acutely flexed. It can cause primary dysmenorrhea.","pyqMatches":[{"year":"2013","no":84,"q":"Cochleate uterus is ?","o":["Large uterus","Acute anteflexion","Acute retroflexion","Large cervix"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (359, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 359, '{"id":359,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":359,"q":"Which muscle originates from tendon of other muscle","o":["Palmaris longus","FCR","Lumbricals","Adductor pollicis"],"a":2,"e":"Ans. is ''c'' i.e., Lumbricals","pyqMatches":[{"year":"2013","no":35,"q":"Which muscle originates from tendon of other muscle","o":["Palmaris longus","FCR","Lumbricals","Adductor pollicis"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (360, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 360, '{"id":360,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":360,"q":"True about anterior intercostal artery ?","o":["Present in 1st to 11th intercostal space","Each intercostal space has two anterior intercostal arteries","Branch of internal thoracic artery","Branch of aorta"],"a":2,"e":"Ans. is ''c'' i.e., Branch of internal thoracic artery Each of upper nine intercostal spaces (1 to 9) have one posterior and two anterior intercostal arteries. The 10\"and 11\" spaces have one posterior intercostal artery (no anterior intercostal artery) Posterior intercostal artery is the main artery of intercostal space and runs in the costal groove along the upper border of an intercostal space, lying between posterior intercostal vein and intercostal nerve (relationship from above downward VAN). 1\" and 2'' posterior intercostal arteries are branches of superior intercostal artery (a branch of costocervical trunk from 2\"d part of subclavian artery* 05)).Lower nine (3rd to 11`\") posterior intercostal arteries are branches of descending thoracic aorta. Right posterior intercostal arteries are longer than the left. Anterior intercostal arteries for upper six spaces (two in each space) arise from internal thoracic or internal mammary artery. For 7th to 9th spaces, these are branches of musculophrenic artery (terminal branch of internal thoracic artery).","pyqMatches":[{"year":"2013","no":70,"q":"True about anterior intercostal artery ?","o":["Present in 1st to 11th intercostal space","Each intercostal space has two anterior intercostal arteries","Branch of internal thoracic artery","Branch of aorta"],"a":2,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":35,"q":"True about anterior intercostal artery ?","o":["Present in 1st to 11th intercostal space","Each intercostal space has two anterior intercostal arteries","Branch of internal thoracic artery","Branch of aorta"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (361, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 361, '{"id":361,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":361,"q":"Medulla oblongata arises from ?","o":["Prosencephalon","Rhombencephalon","Mesencephalon","None"],"a":1,"e":"Ans. ''B'' i.e., Rhombencephalon Medulla oblongata develops from caudal myelenphalon part of the rhombencephalic vesicle. Neuroblasts from the alar plate of the neural tube at this level will produce the sensory nuclei of the medulla. The basal plate neuroblasts will give rise to motor nuclei.","pyqMatches":[{"year":"2013","no":109,"q":"Medulla oblongata arises from ?","o":["Prosencephalon","Rhombencephalon","Mesencephalon","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (362, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 362, '{"id":362,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":362,"q":"Interosseous membrane of forearm is piereced by?","o":["Brachial artery","Anterior interosseous artery","Posterior interosseous artery","Ulnar recurrent artery"],"a":1,"e":"Ans. is ''b'' i.e., Anterior interosseous artery The anterior interosseous artery is the deepest artery on the front of forearm. It is one of the terminal branch of common interosseous artery, which in turn is a branch of ulnar artery. It is accompoined by anterior interosseous nerve, a branch of median nerve. It descends on the surface of the interosseous membrane between the FDP and FPL. It pierces the interosseous membrane at the upper border of the pronator quadratus to enter the extensor (dorsal) compartment. Branches of anterior interosseous artery are :?","pyqMatches":[{"year":"2013","no":45,"q":"Interosseous membrane of forearm is piereced by?","o":["Brachial artery","Anterior interosseous artery","Posterior interosseous artery","Ulnar recurrent artery"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (363, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 363, '{"id":363,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":363,"q":"Mastoid process is which type of epiphysis","o":["Pressure","Aberrant","Atavistic","Traction"],"a":3,"e":"Ans. is ''d'' i.e., Traction Types of epiphysis The epiphysis are of following four types :?","pyqMatches":[{"year":"2013","no":12,"q":"Mastoid process is which type of epiphysis","o":["Pressure","Aberrant","Atavistic","Traction"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (364, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 364, '{"id":364,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":364,"q":"Number of muscles in middle ear -","o":["1","2","3","4"],"a":1,"e":"Ans. is ''b'' i.e., 2 Tensor tympani and Stapedius are the two muscles in middle ear. They both work to dampen the intensity of high pitched sound waves and thus protect inner ear.","pyqMatches":[{"year":"2013","no":101,"q":"Number of muscles in middle ear","o":["1","2","3","4"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (365, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 365, '{"id":365,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":365,"q":"Ratio of connective tissue : smooth muscle in cervix is ?","o":["2:1","5:1","8:1","None"],"a":2,"e":"Ans. is ''c'' i.e., 8:1","pyqMatches":[{"year":"2013","no":80,"q":"Ratio of connective tissue : smooth muscle in cervix is ?","o":["2:1","5:1","8:1","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (366, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 366, '{"id":366,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":366,"q":"Inferior epigastric artery forms the boundry of ?","o":["Femoral triangle","Hesselbach''s triangle","Adductor canal","Popliteal triangle"],"a":1,"e":"Ans. is ''b'' i.e., Hesselbach''s triangle The inguinal triangle (Hesselbach’s triangle) is a region in the anterior abdominal wall. It is alternatively known as the medial inguinal fossa. It was first described by Frank Hesselbach, a German surgeon and anatomist, in 1806. The inguinal triangle is located within the inferomedial aspect of the abdominal wall. It has the following boundaries: Medial – lateral border of the rectus abdominis muscle. Lateral – inferior epigastric vessels. Inferior – inguinal ligament.","pyqMatches":[{"year":"2015","no":66,"q":"Inferior epigastric artery forms the boundry of ?","o":["Femoral triangle","Hesselbach''s triangle","Adductor canal","Popliteal triangle"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (367, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 367, '{"id":367,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":367,"q":"Superior wall of middle ear is formed by ?","o":["Tympanic membrane","Jugular bulb","Tegmen tympani","None"],"a":2,"e":"Ans. is ''c'' i.e., Tegmen tympani Roof (superior wall) of middle ear is formed by tegmen tympani.","pyqMatches":[{"year":"2013","no":87,"q":"Superior wall of middle ear is formed by ?","o":["Tympanic membrane","Jugular bulb","Tegmen tympani","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (368, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 368, '{"id":368,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":368,"q":"Muscle causing flexion of hip ?","o":["Biceps femoris","Psoas major","Gluteus maximus","TFL"],"a":1,"e":"Ans. is ''b'' i.e., Psoas major","pyqMatches":[{"year":"2012","no":119,"q":"Muscle causing flexion of hip ?","o":["Biceps femoris","Psoas major","Gluteus maximus","TFL"],"a":1,"source":"NEET_2012_Paper.pdf"},{"year":"2013","no":59,"q":"Muscle causing flexion of hip ?","o":["Biceps femoris","Psoas major","Gluteus maximus","TFL"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2012","2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (369, 'Anatomy', 'Head & Neck', 'Moderate', 'Anatomy', 369, '{"id":369,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Moderate","source":"Anatomy","sourceNo":369,"q":"Not true about facial vein is ?","o":["Drains in EJV","Largest vein of face","Formed from angular vein","Has no valves"],"a":0,"e":"Ans. is ''a'' i.e., Drains in EJV The facial vein is the largest vein of the face with no valves. It begins as the angular vein at the medial angle of the eye. Angular vein is formed by the union of supraorbital and supratrochlear veins. The angular vein continues as facial veins. Which joins the anterior division of retromandubular vein (i.e. deep facial vein) below the angle of the mandible to form common facial vein. Common facial vein drains into the internal jugular vein.","pyqMatches":[{"year":"2013","no":102,"q":"Not true about facial vein is ?","o":["Drains in EJV","Largest vein of face","Formed from angular vein","Has no valves"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (370, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 370, '{"id":370,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":370,"q":"Structure passing through superior orbital fissure?","o":["Oculomotor nerve","Trochlear nerve","Superior ophthalmic vein","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above Structures passing through superior orbital fissure are :-","pyqMatches":[{"year":"2013","no":103,"q":"Structure passing through superior orbital fissure?","o":["Oculomotor nerve","Trochlear nerve","Superior ophthalmic vein","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (371, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 371, '{"id":371,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":371,"q":"Length of anal canal","o":["10 - 15 mm","15 - 20 mm","25 - 30 mm","35 - 40 mm"],"a":3,"e":"Ans. is ''d'' i.e., 35 - 40 mm The anal canal is the terminal part of the alimentary canal. It begins at ano-rectal junction which is situated 2-3 cm in front and slightly below the tip of coccyx. From ano-rectal junction anal canal passes downwards and backwards through the pelvic diaphragm and opens at anal oriface (anus) which is situated in the cleft between the buttocks about 4 cm below and in front of the tip of coccyx. Sacculations and taeniae are absent in anal canal. The length of anal canal is 3.8 cm.","pyqMatches":[{"year":"2013","no":85,"q":"Length of anal canal","o":["10 - 15 mm","15 - 20 mm","25 - 30 mm","35 - 40 mm"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (372, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 372, '{"id":372,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":372,"q":"Most common congenital anomaly of kidney","o":["Ectopic kidney","Renal duplication","Horse shoe kidney","Renal agenesis"],"a":2,"e":"Ans. is ''c'' i.e., Horse shoe kidney Horse shoe kidney is the most common congenital renal anomaly, with an incidence of 1 in 400 live births. Fusion typically occurs at lower poles, with subsequent arrest of ascend of kidney, due to restriction at the inferior mesenteric artery. As a result, kidneys are lower in abdomen.","pyqMatches":[{"year":"2013","no":86,"q":"Most common congenital anomaly of kidney","o":["Ectopic kidney","Renal duplication","Horse shoe kidney","Renal agenesis"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (373, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 373, '{"id":373,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":373,"q":"Sacral promontory is the landmark for","o":["Origin of superior mesenteric artery","Termination of presacaral nerve","Origin of inferior mesenteric artery","None of the above"],"a":1,"e":"Ans. is ''b'' i.e., Termination of presacaral nerve At the sacral promontory level or just caudal to it, the presacral nerves terminate and give rise to right and left hypogastric nerves, which will joint the inferior hypogastric plexus at the level of S2-S3- S4.","pyqMatches":[{"year":"2013","no":60,"q":"Sacral promontory is the landmark for","o":["Origin of superior mesenteric artery","Termination of presacaral nerve","Origin of inferior mesenteric artery","None of the above"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (374, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 374, '{"id":374,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":374,"q":"Upper limb deformity in Erb''s palsy?","o":["Adduction and lateral rotation of arm","Adduction and medial rotation of arm","Abduction and lateral rotation of arm","Abduction and medial rotation of arm"],"a":1,"e":"Deformity in Erb''s palsy (position of the limb): Arm: Hanges by the side; it is adducted & medially rotated Forearm: Extended and pronated The deformity is known as ‘policeman’s tip hand'' or ‘porter’s tip hand’","pyqMatches":[{"year":"2015","no":1,"q":"Upper limb deformity in Erb''s palsy?","o":["Adduction and lateral rotation of arm","Adduction and medial rotation of arm","Abduction and lateral rotation of arm","Abduction and medial rotation of arm"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (375, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 375, '{"id":375,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":375,"q":"Cholecystocaval line separates:","o":["Right & Left liver lobe","Liver with Gall Bladder","Right Lobe of Liver with Gall Bladder","Left Lobe of Liver with Gall Bladder"],"a":0,"e":"Answer A. Right & Left liver lobe Functional lobes and segments of the liver The functional right and left lobes of the liver are separated by an imaginary plane passing along the floor of fossa for gall bladder and the groove for inferior vena cava (cholecysto-caval line). On the anterosuperior surface of the liver, the plane passes little right to the attachment of falciform ligament. The functional right and left lobes of the liver are more or less of equal size.","pyqMatches":[{"year":"2019","no":4,"q":"Cholecystocaval line separates:","o":["Right & Left liver lobe","Liver with Gall Bladder","Right Lobe of Liver with Gall Bladder","Left Lobe of Liver with Gall Bladder"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (376, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 376, '{"id":376,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":376,"q":"Structure derived from first pharyngeal arch:","o":["Levator palatini","Buccinator","Stylohyoid","Anterior belly of digastric"],"a":3,"e":"Answer D. Anterior belly of digastric MESODERMAL DERIVATIVES OF PHARYNGEAL ARCHES Pharyngeal arch Muscular contributions Skeletal contributions Nerve Ist (also called “mandibular arch”) Mylohyoid Muscles of mastication Anterior belly of digastric Tensor veli palatini Tensor tympani Maxilla Zygomatic bone Part of temporal and vomer, sphenoid, mandible Meckel’s cartilage:- Malleus, incus Anterior ligament of malleus Sphenomandibular ligament Mandibular division of Trigeminal Nerv (V3). Stapedius Stylohyoid Reichert’s cartilage, stapes (except footplate) IInd (also called the “hyoid arch”) Posterior belly of digastric Facial expression muscles Styloid process Stylohyoid ligament Smaller cornu of hyoid Superior part of body of hyoid Facial IIIrd Stylopharyngeus Greater cornu of hyoid Lower part of body of hyoid Glossopharynge IVth Pharyngeal muscles Cricothyroid Cartilage of larynx except arytenoids superior parathyroids, epiglottic cartilage Superior larynge branch of Vagus VIth Intrinsic muscles of larynx (except cricothyroid) Arytenoid cartilage of larynx Recurrent laryngeal nerve (branch of vagus)","pyqMatches":[{"year":"2019","no":10,"q":"Structure derived from first pharyngeal arch:","o":["Levator palatini","Buccinator","Stylohyoid","Anterior belly of digastric"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (377, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 377, '{"id":377,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":377,"q":"Joint involved in movement of head from left to right.","o":["Atlanto axial","Atlanto occipital","C2- C3 Joint","C3- C4 Joint"],"a":0,"e":"Answer A. Atlanto axial Atlanto-occipital (between skull and C1) joint permits nodding of head ( as when indicating approval or YES) and Atlanto-axial joint permits the head to be turned from side to side (as indicating disapproval or NO).","pyqMatches":[{"year":"2019","no":11,"q":"Joint involved in movement of head from left to right.","o":["Atlanto axial","Atlanto occipital","C2- C3 Joint","C3- C4 Joint"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (378, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 378, '{"id":378,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":378,"q":"What is the nerve supply of Submandibular gland:","o":["Auriculotemporal nerve","Lingual nerve","Glossopharyngeal nerve","Inferior alveolar nerve"],"a":1,"e":"Answer B. Lingual Nerve The submandibular glands receive autonomic innervation through parasympathetic and sympathetic fibres, which directly and indirectly regulate salivary secretions respectively. Parasympathetic Parasympathetic innervation originates from the superior salivatory nucleus through pre-synaptic fibres, which travel via the chorda tympani branch of the facial nerve (CN VII). The chorda tympani then unifies with the lingual branch of the mandibular nerve (CNVIII) before synapsing at the submandibular ganglion and suspending it by two nerve filaments. Post-ganglionic innervation consists of secretomotor fibres which directly induce the gland to produce secretions, and vasodilator fibres which accompany arteries to increase blood supply to the gland. Increased parasympathetic drive promotes saliva secretion. Sympathetic Sympathetic innervation originates from the superior cervical ganglion, where post-synaptic vasoconstrictive fibres travel as a plexus on the internal and external carotid arteries, facial artery and finally the submental arteries to enter each gland. Increased sympathetic drive reduces glandular blood flow through vasoconstriction and decreases the volume of salivary secretions, resulting in a more mucus and enzyme-rich saliva.","pyqMatches":[{"year":"2019","no":12,"q":"What is the nerve supply of Submandibular gland:","o":["Auriculotemporal nerve","Lingual nerve","Glossopharyngeal nerve","Inferior alveolar nerve"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (379, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 379, '{"id":379,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":379,"q":"Parathyroid gland is implanted in which muscle?","o":["Sartorius","Supinator","Deltoid","Brachioradialis"],"a":3,"e":"Answer D. Brachioradialis Parathyroid surgery: Autotransplantation The most common places for auto-implantation of parathyroid glands are the brachioradialis muscle and the presternal region. Other locations can also be used: the sternocleidomastoid, the subcutaneous tissue of upper limbs and abdominal fat.","pyqMatches":[{"year":"2019","no":13,"q":"Parathyroid gland is implanted in which muscle?","o":["Sartorius","Supinator","Deltoid","Brachioradialis"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (380, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 380, '{"id":380,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":380,"q":"Right coronary artery arises from?","o":["Right Aortic Sinus","Left Aortic Sinus","Posterior coronary sinus","Anterior coronary sinus"],"a":0,"e":"Answer A. Right Aortic Sinus RCA arises from anterior aortic sinus aka Right aortic sinus. LCA arises from left posterior aortic sinus.","pyqMatches":[{"year":"2019","no":14,"q":"Right coronary artery arises from?","o":["Right Aortic Sinus","Left Aortic Sinus","Posterior coronary sinus","Anterior coronary sinus"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (381, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 381, '{"id":381,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":381,"q":"Duct of Bellini are present in:","o":["Pancreas","Liver","Kidney","Salivary gland"],"a":2,"e":"Answer C. Kidney Papillary (collecting) ducts are anatomical structures of the kidneys, previously known as the ducts of Bellini. Papillary ducts represent the most distal portion of the collecting duct. They receive renal filtrate (precursor to urine) from several medullary collecting ducts and empty into a minor calyx.","pyqMatches":[{"year":"2014","no":132,"q":"Duct of Bellini are present in:","o":["Pancreas","Liver","Kidney","Salivary gland"],"a":2,"source":"NEET_2014_Paper.pdf"},{"year":"2019","no":9,"q":"Duct of Bellini are present in:","o":["Pancreas","Liver","Kidney","Salivary gland"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2014","2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (382, 'Anatomy', 'Thorax', 'Moderate', 'Anatomy', 382, '{"id":382,"subject":"Anatomy","chapter":"Thorax","difficulty":"Moderate","source":"Anatomy","sourceNo":382,"q":"Which of the following exocrine glandular ducts are not obstructed in cystic fibrosis:","o":["Pancreas","Lung","Sweat gland","All of above"],"a":2,"e":"Answer C. Sweat gland Most CF patients have 3 distinct abnormal characteristics: The ducts of the mucus-secreting glands are obstructed due to an increase in viscosity of these secretions leading to glandular dilatation and destruction. CF patients are prone to chronic bacterial colonization and infections. The sweat glands are not obstructed in CF patients because in serous glands such as sweat glands there are abnormal concentrations of inorganic ions, rather than glandular obstruction with thick mucus. The quantitative pilocarpine iontophoresis sweat test is a uniformly accepted method for diagnosing CF. The sweat gland ducts must be patent for this test. Obstruction of airways leads to bronchiectasis and atelectasis; pancreatic duct obstruction leads to pancreatitis and malabsorption; and plugging of bile ducts leads to obstructive jaundice.","pyqMatches":[{"year":"2019","no":5,"q":"Which of the following exocrine glandular ducts are not obstructed in cystic fibrosis:","o":["Pancreas","Lung","Sweat gland","All of above"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (383, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 383, '{"id":383,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":383,"q":"Boot shape of heart in TOF is due to:","o":["Left atrial enlargement","Right atrial enlargement","Right ventricular hypertrophy","Biventricular hypertrophy"],"a":2,"e":"Answer C. Right ventricular hypertrophy Boot shaped heart. A ‘boot-shaped’ heart (“cœur en sabot” in French) is the description given to the appearance of the heart on plain film in some cases of Tetralogy of Fallot. It describes the appearances of an upturned cardiac apex due to right ventricular hypertrophy and a concave pulmonary arterial segment.","pyqMatches":[{"year":"2019","no":6,"q":"Boot shape of heart in TOF is due to:","o":["Left atrial enlargement","Right atrial enlargement","Right ventricular hypertrophy","Biventricular hypertrophy"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (384, 'Anatomy', 'Abdomen', 'Moderate', 'Anatomy', 384, '{"id":384,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Moderate","source":"Anatomy","sourceNo":384,"q":"Which of the following structure is not derived from external oblique muscle:","o":["Inguinal ligament","Lacunar ligament","Cooper ligament","Linea Semilunaris"],"a":3,"e":"Answer D. Linea Semilunaris The external oblique muscle (of the abdomen) (also external abdominal oblique muscle) is the largest and the outermost of the three flat muscles of the lateral anterior abdomen. Inguinal ligament (Poupart’s ligament) is the folded lower border of external oblique aponeurosis Lacunar ligament (Gimbernat ligament) is the crescent shaped expansion from the medial end of inguinal ligament attached to pectineal line of pubis. Pectineal ligament (Cooper’s ligament) is strong fibrous band extending laterally from the lacunar ligament along pectineal line of pubis. Similar to lacunar ligament, it is made of external oblique aponeurosis. Reflected part of inguinal ligament extends from the lateral crus of superficial inguinal ring formed by inguinal ligament upwards to linea alba. It forms the posterior wall of inguinal canal. The linea semilunaris (also semilunar line or Spigelian line) is a curved tendinous intersection found on either side of the rectus abdominis muscle.","pyqMatches":[{"year":"2019","no":7,"q":"Which of the following structure is not derived from external oblique muscle:","o":["Inguinal ligament","Lacunar ligament","Cooper ligament","Linea Semilunaris"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (385, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 385, '{"id":385,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":385,"q":"Contralateral loss of pain and temperature is due to injury to:","o":["Anterior spinothalamic tract","Lateral spinothalamic tract","Fasciculus gracilis","Fasciculus cuneatus"],"a":1,"e":"Answer B. Lateral spinothalamic tract Damage to lateral spinothalamic tract leads to loss of pain and temperature on the opposite side of the body below the level of lesion, since the neurons of this tract crosses to the opposite side in the spinal cord. Anterior spinothalamic tract carries crude touch and pressure sensations. Fasciculus gracilis and fasciculus cuneatus carries conscious proprioception, fine touch, stereognosis and vibration sensations.","pyqMatches":[{"year":"2019","no":8,"q":"Contralateral loss of pain and temperature is due to injury to:","o":["Anterior spinothalamic tract","Lateral spinothalamic tract","Fasciculus gracilis","Fasciculus cuneatus"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (386, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 386, '{"id":386,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":386,"q":"Space of Disse is in:","o":["Spleen","Lymph node","Liver","Bone"],"a":2,"e":"Ans. C. Liver The perisinusoidal space (or space of Disse) is a location in the liver between a hepatocyte and a sinusoid. It contains the blood plasma. Microvilli of hepatocytes extend into this space, allowing proteins and other plasma components from the sinusoids to be absorbed by the hepatocytes.","pyqMatches":[{"year":"2019","no":2,"q":"Space of Disse is in:","o":["Spleen","Lymph node","Liver","Bone"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (387, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 387, '{"id":387,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":387,"q":"What are Gitter cells:","o":["Macroglia","Modified macrophages in CNS","Astrocytes","Oligodendrocytes"],"a":1,"e":"Answer B. Modified macrophages in CNS Gitter cells: These cells are macrophages and because of their appearance they are called “Gitter cells”. They look this way because they are lipid-laden. These macrophages are thought to be mainly derived from circulating blood monocytes, but some probably originate from resident microglia. Any time there is parenchymal damage (e.g. inflammation, infarction, parasite migration) these cells will phagocytose lipid from degenerated myelin and cellular debris. These lipid-laden macrophages migrate to the perivascular spaces and leave the CNS via the blood or CSF.","pyqMatches":[{"year":"2019","no":3,"q":"What are Gitter cells:","o":["Macroglia","Modified macrophages in CNS","Astrocytes","Oligodendrocytes"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (388, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 388, '{"id":388,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":388,"q":"Syndrome associated with posterior inferior cerebellar artery thrombosis:","o":["Wallenberg syndrome","Medial medullary syndrome","Inferior alternating syndrome","Dejerine syndrome"],"a":0,"e":"Answer A. Wallenberg syndrome Wallenberg syndrome is also known as lateral medullary syndrome or the posterior inferior cerebellar artery syndrome. Wallenberg described the first case in 1895. This neurological disorder is associated with a variety of symptoms that occur as a result of damage to the lateral segment of the medulla posterior to the inferior olivary nucleus. It is the most typical posterior circulation ischemic stroke syndrome in clinical practice. Etiology: Wallenberg syndrome is caused most commonly by atherothrombotic occlusion of the vertebral artery, followed most frequently by the posterior inferior cerebellar artery, and least often, the medullary arteries. Hypertension is the commonest risk factor followed by smoking and diabetes. Medial medullary syndrome, also known as inferior alternating syndrome, hypoglossal alternating hemiplegia, lower alternating hemiplegia, or Dejerine syndrome, is a type of alternating hemiplegia characterized by a set of clinical features resulting from occlusion of the anterior spinal artery.","pyqMatches":[{"year":"2019","no":1,"q":"Syndrome associated with posterior inferior cerebellar artery thrombosis:","o":["Wallenberg syndrome","Medial medullary syndrome","Inferior alternating syndrome","Dejerine syndrome"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (389, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 389, '{"id":389,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":389,"q":"Urethral crest is an elevation seen in urethra due to:","o":["Prostatic glands","Insertion of detrusor muscle","Insertion of trigone","Preprostatic internal sphincter"],"a":0,"e":"Answer- A (Prostatic glands) The urethral crest is an anatomical feature present in the urinary system of both males and females. The prostatic portion (pars prostatica), the widest and most dilatable part of the canal, is about 3 cm long. Upon the posterior wall or floor is a narrow longitudinal ridge, the urethral crest, formed by an elevation of the mucous membrane and its subjacent tissue. On either side of the crest is a slightly depressed fossa, the prostatic sinus, the floor of which is perforated by numerous apertures, the orifices of the prostatic ducts from the lateral lobes of the prostate; the ducts of the middle lobe open behind the crest.","pyqMatches":[{"year":"2014","no":46,"q":"Urethral crest is an elevation seen in urethra due to:","o":["Prostatic glands","Insertion of detrusor muscle","Insertion of trigone","Preprostatic internal sphincter"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (390, 'Anatomy', 'Upper Limb', 'Moderate', 'Anatomy', 390, '{"id":390,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Moderate","source":"Anatomy","sourceNo":390,"q":"Maxillary bone does not articulate with:","o":["Ethmoid","Sphenoid","Frontal","Lacrimal"],"a":1,"e":"Ans: B. Sphenoid (Ref Gray''s 41/e p484, 40/e p473-476) Maxillary bone does not articulate with sphenoid. Articulation of maxilla: Each maxilla articulates with nine bones: Two of cranium: Frontal & ethmoid. Seven of the face: Nasal, zygomatic, lacrimal, inferior nasal concha, palatine, vomer & adjacent fused maxilla. Sometimes articulates with orbital surface & with lateral pterygoid plate of sphenoid.","pyqMatches":[{"year":"2012","no":114,"q":"Maxillary bone does not articulate with:","o":["Ethmoid","Sphenoid","Frontal","Lacrimal"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (391, 'Anatomy', 'Neuroanatomy', 'Moderate', 'Anatomy', 391, '{"id":391,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":391,"q":"All of the following are true about location of otic ganglia except:","o":["Inferior to foramen ovale","Lateral to tensor veli palatini","Lateral to mandibular nerve","Anterior to middle meningeal artery"],"a":2,"e":"Ans: C. Lateral to mandibular nerve (Ref Gray 41/e p552. 40/e p543) Mandibular nerve lies lateral to otic ganglion. Ie., Ganglion lies medial to mandibular nerve. Otic ganglion: Small, oval, flat reddish-grey ganglion. Situated just below foramen ovate. Peripheral parasympathetic ganglion located in the infratemporal fosse. Functionally associated with glossopharyngeal nerve & innervates parotid gland for salivation. Connected to chorda tympani nerve & to nerve of pterygoid canal. Pathways provide an alternate pathway of taste from anterior two- thirds of tongue.","pyqMatches":[{"year":"2012","no":109,"q":"All of the following are true about location of otic ganglia except:","o":["Inferior to foramen ovale","Lateral to tensor veli palatini","Lateral to mandibular nerve","Anterior to middle meningeal artery"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (392, 'Anatomy', 'Miscellaneous', 'Moderate', 'Anatomy', 392, '{"id":392,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anatomy","sourceNo":392,"q":"In spermatogenesis, independent assortment of paternal and maternal chromosomes occurs during-","o":["Primary to secondary spermatocyte","Spermatogonia to primary spermatocyte","Secondary spermatocyte to spermatids","Spermatids to spermatozoa"],"a":0,"e":"Answer- A. Primary to secondary spermatocyte In spermatogenesis, independent assortment of paternal and maternal chromosomes occurs during meiosis I, in which primary spematocyte) to (2n) is converted into two secondary spermatocytes (In).","pyqMatches":[{"year":"2016","no":2,"q":"In spermatogenesis, independent assortment of paternal and maternal chromosomes occurs during","o":["Primary to secondary spermatocyte","Spermatogonia to primary spermatocyte","Secondary spermatocyte to spermatids","Spermatids to spermatozoa"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (393, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 393, '{"id":393,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":393,"q":"Sacrotuberous ligament is pierced by","o":["Perforating cutaneous nerve","Posterior femoral cutaneous","Superior gluteal nerve","Sciatic nerve"],"a":0,"e":"Ans: A Perforating cutaneous nerve Sacrotuberous ligament (STL) - Stabiliser of sacro-iliac joint. Connects bony pelvis to vertebral column. Structure piercing via STL - Perforating cutaneous nerve. Perforating cutaneous nerve: Cutaneous nerve that arises from the 52 and 53 nerve roots of the sacral plexus. Supplies lower medial part of buttock.","pyqMatches":[{"year":"2013","no":54,"q":"Sacrotuberous ligament is pierced by","o":["Perforating cutaneous nerve","Posterior femoral cutaneous","Superior gluteal nerve","Sciatic nerve"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (394, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 394, '{"id":394,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":394,"q":"Lining epithelium of vagina is","o":["Squamous epithelium","Columnar epithelium","Transitional epithelium","Secretory epithelium"],"a":0,"e":"Ans: A Squamous epithelium (Ref: Ramesh Babu p. 24] Vaginal mucous membrane is lined by nonkeratinized stratified squamous epithelium.","pyqMatches":[{"year":"2015","no":125,"q":"Lining epithelium of vagina is","o":["Squamous epithelium","Columnar epithelium","Transitional epithelium","Secretory epithelium"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (395, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 395, '{"id":395,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":395,"q":"Tongue muscles are derived from","o":["Lateral plate mesoderm","Occipital myotome","Intermediate mesoderm","Cervical myotome"],"a":1,"e":"Ans: B Occipital myotome Development of the tongue:- I. Epithelium: Ant 2/3 -- lingual swellings of 1st arch and tuberculum impar. Post 1/3 -- large dorsal part of hypobranchial eminence, i.e, 3rd arch. Posterior most part -- small dorsal part of the hypobranchial eminence, i.e. 4th arch. II. Muscles: Derived from occipital myotomes except palatoglossus which is derived from the 6th arch.","pyqMatches":[{"year":"2016","no":3,"q":"Tongue muscles are derived from","o":["Lateral plate mesoderm","Occipital myotome","Intermediate mesoderm","Cervical myotome"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (396, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 396, '{"id":396,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":396,"q":"Insertion of levator scapulae is ?","o":["Lateral border of scapula","Suprolateral part of scapula","Superior part of medial scapula border","Inferior angle of scapula"],"a":2,"e":"Ans. is''c'' i.e., Superior part of medial scapula border [Ref Rockwood, Charles A.; Matsen, (2009). The shoulder, VoI. 1] Origin: * Posterior tubercles of transverse processes of C 1 - C4 vertebrae. Insertion: * Superior part of medial border of scapula","pyqMatches":[{"year":"2015","no":5,"q":"Insertion of levator scapulae is ?","o":["Lateral border of scapula","Suprolateral part of scapula","Superior part of medial scapula border","Inferior angle of scapula"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (397, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 397, '{"id":397,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":397,"q":"Which muscle steadies the clavicle during movement of shoulder ?","o":["Pectoralis major","Latissimus dorsi","Subclavius","Serratus anterior"],"a":2,"e":"Ans. is''c''i.e., Subclavius (Ref: Clinical anatomy j''d/e p. 1367) Subclavius steadies the clavicle during movements of shoulder.","pyqMatches":[{"year":"2012","no":39,"q":"Which muscle steadies the clavicle during movement of shoulder ?","o":["Pectoralis major","Latissimus dorsi","Subclavius","Serratus anterior"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (398, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 398, '{"id":398,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":398,"q":"What is attached to the superior nuchal line?","o":["Trapezius","Scalenus anticus","Coracobrachialis","Biceps Brachii"],"a":0,"e":"Ans. is''a''i.e., Trapezius [Ref: Snell''s th/e p. 3a2l Muscles attached to superior nuchal line Occipitalis muscle, The splenius capitis muscle Trapezius muscle, Sternocleidomastoid muscle","pyqMatches":[{"year":"2015","no":103,"q":"What is attached to the superior nuchal line?","o":["Trapezius","Scalenus anticus","Coracobrachialis","Biceps Brachii"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (399, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 399, '{"id":399,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":399,"q":"Sensory supply of the palm is from which nerves -","o":["Median nerve and Radial nerve","Radial nerve and ulnar nerve","Ulnar nerve and Median nerve","Musculocutaneous nerve and Radial nerve"],"a":2,"e":"Ans. is''c''i.e., Ulnar nerve and Median nerve (Rel BDC 5''h/e VoL I p. 108-111) On Palm side: Lateral 2/3 of the palm and lateral three and half fibers → Median nerve. Medial 1/3 of the palm and medial one and half fingers → Ulnar nerve.","pyqMatches":[{"year":"2012","no":104,"q":"Sensory supply of the palm is from which nerves","o":["Median nerve and Radial nerve","Radial nerve and ulnar nerve","Ulnar nerve and Median nerve","Musculocutaneous nerve and Radial nerve"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (400, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 400, '{"id":400,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":400,"q":"Nerve supply of cervical esophagus ?","o":["Vagus","Left recurrent larynageal nerve","Right recurrent larynageal nerve","All of the above"],"a":3,"e":"Ans. is d''., All of the above [Ref Clinical anatomy 3''d/e p. 2891 Nerve supply of esophagus: Esophagus is supplied by both parasympathetic and sympathetic fibers. A) Parasympathetic supply It provides sensory, motor and secretomotor supply to esophagus. Complete parasympathetic innervation is provided by vagus nerve:-","pyqMatches":[{"year":"2012","no":49,"q":"Nerve supply of cervical esophagus ?","o":["Vagus","Left recurrent larynageal nerve","Right recurrent larynageal nerve","All of the above"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (401, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 401, '{"id":401,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":401,"q":"Which vein is found at the apex of the heart ?","o":["Great cardiac vein","Coronary Sinus","Anterior cardiac vein","Middle cardiac vein"],"a":0,"e":"Ans. is''a''i.e., Great cardiac vein [Rel BDC 4n/e VoI. I p. 251-252; Keith Moore 4e/e p. 136-137; Snell''s 9/e p. 1211 Great Cardiac Vein: The great cardiac vein (left coronary vein) begins at the apex of heart and ascends along the anterior longitudinal sulcus to the base of ventricle.","pyqMatches":[{"year":"2015","no":43,"q":"Which vein is found at the apex of the heart ?","o":["Great cardiac vein","Coronary Sinus","Anterior cardiac vein","Middle cardiac vein"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (402, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 402, '{"id":402,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":402,"q":"Right hepatic vein drains which segment of the liver?","o":["I","II","IV","VII"],"a":3,"e":"Ans. is''d'' i.e., VII [Rel Gray''s 4fh/e p. 1163-1167; Sabaton 18h/e p. 15841 Segmental anatomy of the liver: Based on the distribution of portal vein and hepatic vein, Couinaud divided each physiological (functional) lobe of liver into 4 segments each and hence liver is divided into 8 segments. The physiological left lobe is composed of 4 segments designated I to IV and is supplied by left branch of hepatic artery, Ieft branch of portal vein and drained by left hepatic duct and left hepatic vein. The physiological right lobe consists of segment V, VI, VII and VIII and is supplied by right hepatic artery, right branch of portal vein and drained by right hepatic duct and right hepatic vein.","pyqMatches":[{"year":"2012","no":78,"q":"Right hepatic vein drains which segment of the liver?","o":["I","II","IV","VII"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (403, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 403, '{"id":403,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":403,"q":"Lymphatic drainage of lateral wall of nose","o":["Submandibular nodes","Retropharyngeal nodes","Deep cervical nodes","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above Lymphatic drainage of nose is BY Anterior half of nasal cavity (Both septum and lateral wall) -s Submandibular nodes Posterior half of nasal cavity (Both septum and lateral wall)Retropharyngeal nodes and upper deep cervical nodes.","pyqMatches":[{"year":"2012","no":91,"q":"Lymphatic drainage of lateral wall of nose","o":["Submandibular nodes","Retropharyngeal nodes","Deep cervical nodes","All of the above"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (404, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 404, '{"id":404,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":404,"q":"Part of neural tube from which corpus callosum develops","o":["Basal lamina","Alar lamina","Lamina terminalis","Basal plate"],"a":2,"e":"Ans. is ''c'' i.e., Lamina terminalis The development of the corpus callosum occurs between the 12th and 16-20th weeks of gestation 6. It begins with the genu and then continues posteriorly along the body to the splenium. The rostrum is the last part to be formed. Myelination of the corpus callosum occurs in the opposite direction, from the splenium forwards. They develop from lamina terminalis which is cranial part of neural tube and later lies in the anterior wall of 3''d ventricle. The corpus callosum, the largest of cerebral commissures, takes the form of an arch over the third ventricle. It connects the neocortices of both sides.","pyqMatches":[{"year":"2016","no":8,"q":"Part of neural tube from which corpus callosum develops","o":["Basal lamina","Alar lamina","Lamina terminalis","Basal plate"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (405, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 405, '{"id":405,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":405,"q":"Gene for eye morphogenesis","o":["Pax-6","BMP-4","HOX-D13","HOX-A13"],"a":0,"e":"Ans. is ''a'' i.e., Pax-6 The Pax-6 gene locus is a transcription factor for various genes and growth factors involved in eye formation.Pax-6 is a master control gene for eye morphogenesis and encodes for Paired box protein Pax-6 (also called aniridia type II protein or oculorhombin).","pyqMatches":[{"year":"2016","no":978,"q":"Gene for eye morphogenesis","o":["Pax-6","BMP-4","HOX-D13","HOX-A13"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (406, 'Anatomy', 'Upper Limb', 'Moderate', 'Anatomy', 406, '{"id":406,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Moderate","source":"Anatomy","sourceNo":406,"q":"Not attached on medial border of scapula ?","o":["Serratus anterior","Levator scapulae","Rhamboides major","Teres major"],"a":3,"e":"Ans. is ''d'' i.e., Teres major Muscles attached to scapula are :- Coracoid process :- Tip of the coracoid process gives origin to coracobrachialis (medially) and short head of the biceps laterally. The upper surface receives insertion of pectoralis minor. Spine of scapula and acromion process :- There is origin of Deltoid and insertion of trapezius. Glenoid tubercle :- Supraglenoid tubercle gives origin to the long head of biceps and infra glenoid tubercle gives origin to long head of triceps. Lateral border :- Origins of teres minor and teres major. Medial border :- Insertions of serattus anterior (anteriorly); and rhomboideus major, rhomboideus minor and levator scapulae (posteriorly). Costal (anterior) surface (origin) Subscapularis. Dorsal surface (origins) Supraspinatus, infraspinatus and at inferior angle latissimus dorsi.","pyqMatches":[{"year":"2015","no":8,"q":"Not attached on medial border of scapula ?","o":["Serratus anterior","Levator scapulae","Rhamboides major","Teres major"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (407, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 407, '{"id":407,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":407,"q":"Floor of Petit triangle is formed by?","o":["Sacrospinalis","Internal oblique","Rectus abdominis","Fascia Transversalis"],"a":1,"e":"Ans. is ''b'' i.e., Internal oblique [Ref Text book of surgical anatomy p. 148] Boundaries of Petit triangle (inferior lumbar triangle) are? Base - Iliac crest Anterior boundary (abdominal boundary) → Posterior border of external oblique muscle. Posterior boundary (lumbar boundary) - Anterior border of latissimus dorsi. Floor is formed by internal oblique muscle.","pyqMatches":[{"year":"2015","no":82,"q":"Floor of Petit triangle is formed by?","o":["Sacrospinalis","Internal oblique","Rectus abdominis","Fascia Transversalis"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (408, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 408, '{"id":408,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":408,"q":"Which of the following arises from infraglenoid tubercle -","o":["Longheadofbiceps","Longheadoftriceps","Shortheadofbiceps","Coracobrachialis"],"a":1,"e":"Ans. is''b'' i.e., Long head of triceps Supraglenoid tubercle of scapula : origin oflong head ofbiceps. Infraglenoid tubercle of scapula : origin of long head of triceps","pyqMatches":[{"year":"2015","no":7,"q":"Which of the following arises from infraglenoid tubercle","o":["Longheadofbiceps","Longheadoftriceps","Shortheadofbiceps","Coracobrachialis"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (409, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 409, '{"id":409,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":409,"q":"What is true about adductors of thigh –","o":["Ischial head of adductor magnus is an adductor","Profunda femoris artery is the main blood supply","Ischial head of adductor magnus originates from adductor tubercle","Adductor magnus is the largest muscle"],"a":3,"e":"Ans. is''d''i.e., Adductor magnus is the largest muscle Ischial head of adductor magnus is a hamstring muscle (not adductor). Ischial head of adductor magnus originates from inferolateral aspect of Ischial tuberosity (not from adductor tubercle). Main artery of adductor (medial) compartment of thigh is obturator artery (not profunda femoris). Adductor magnus is the largest muscle of the adductor compartment.","pyqMatches":[{"year":"2015","no":29,"q":"What is true about adductors of thigh –","o":["Ischial head of adductor magnus is an adductor","Profunda femoris artery is the main blood supply","Ischial head of adductor magnus originates from adductor tubercle","Adductor magnus is the largest muscle"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (410, 'Anatomy', 'Upper Limb', 'Moderate', 'Anatomy', 410, '{"id":410,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Moderate","source":"Anatomy","sourceNo":410,"q":"All are supplied by anterior interosseous nerve except –","o":["Flexor carpi ulnaris","Brachioradialis","Abductor pollicis brevis","Flexor pollicis longus e) Flexor digitorum superficialis"],"a":0,"e":":B:C:E Ans. is''a''i''e., Flexor carpi ulnaris ''b'' i.e.,Brachioradialis;''c'' i.e., Abductor pollicis brevis; &''e'' i.e., Flexor digitorum superficial The anterior interosseous nerve (volar interosseous nerve) is a branch of the median nerve that supplies the deep muscles on the anterior of the forearm, except the ulnar (medial) half of the flexor digitorumprofundus.","pyqMatches":[{"year":"2013","no":44,"q":"All are supplied by anterior interosseous nerve except –","o":["Flexor carpi ulnaris","Brachioradialis","Abductor pollicis brevis","Flexor pollicis longus e) Flexor digitorum superficialis"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (411, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 411, '{"id":411,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":411,"q":"Teres minor is supplied by","o":["Suprascapular nerve","Infrascapular nerve","Thoracodorsal nerve","Axillary nerve"],"a":3,"e":"Ans. is''d''i.e., Axillary nerve [Ref:BDC 6h/e VoI.l p. 671 Axillary nerve supplies teres minor and deltoid.","pyqMatches":[{"year":"2015","no":4,"q":"Teres minor is supplied by","o":["Suprascapular nerve","Infrascapular nerve","Thoracodorsal nerve","Axillary nerve"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (412, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 412, '{"id":412,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":412,"q":"Number of lobes in breast","o":["5","10","15","30"],"a":2,"e":"Ans. is''c''i.e., 15lRef; BDC tr/eVol.I p. 361 Breast (mammary gland) is a modifeil sweat glaad present in the superficial fascia of pectoral region. It consists of 15-20 lobes. Vertically it extends from 2nd to 6th ribs at midclavicular line and horizontal extent is from sternal margin to midaxillary line at the level of 4h rib.","pyqMatches":[{"year":"2015","no":6,"q":"Number of lobes in breast","o":["5","10","15","30"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (413, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 413, '{"id":413,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":413,"q":"Content of anatomical snuffbox","o":["Radial artery","Brachial artery","Ulnar artery","Interosseus artery"],"a":0,"e":"Ans. is ''a'' i.e., Radial artery [Ref: AK Dutta p. 861] Triangular depression on the dorsal and radial aspect of the hand become visible when thumb is fully extended. Boundaries Media/Posterior → Tendon of the extensor pollicis longus. Lateral/Anterior → tendon of the extensor pollicis brevis and abductor pollicis longus, Roof → Skin and fascia with beginning of cephalic vein and crossed by superficial branch of the radial nerve Floor → Styloid process of radius, trapezium, scaphoid and base of first metacarpal Contents → The radial artery","pyqMatches":[{"year":"2015","no":15,"q":"Content of anatomical snuffbox","o":["Radial artery","Brachial artery","Ulnar artery","Interosseus artery"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (414, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 414, '{"id":414,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":414,"q":"Abduction and adduction of foot occurs at which joints","o":["Ankle","Subtalar","Tarso-metatarsal","None"],"a":1,"e":"Ans. is''b''i.e., Subtalar [Ret Clinical arthopaedics p. 7861 Adduction and abduction of foot occurs mainly at subtalar joint. Movements take place at ankle are dorsiflexion and plantarflexion. Inversion and eversion take place at Subtalar joint and midtarsal joints.","pyqMatches":[{"year":"2015","no":18,"q":"Abduction and adduction of foot occurs at which joints","o":["Ankle","Subtalar","Tarso-metatarsal","None"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (415, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 415, '{"id":415,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":415,"q":"Content of femoral canal","o":["Femoral branch of genitofemoral nerve","Genital branch of genitofemoral nerve","Femoral vein","Lymph node"],"a":3,"e":"Ans. is''d''i.e., Lymph node [Ref BDC 5th/e VoI.2 p. 53, 54] Femoral sheath is a funnel shaped fascial prolongation around proximal part of femoral vessels, situated in the femoral triangle, below the inguinal ligament. It is 3-4 cm long. lt is formed by fascia iliaca. Femoral ring b bounded: Anteriorly by inguinal ligament, medially by the lacunar ligament, posterior / by pectineus with its covering fascia, and laterally by septum separating it from femoral vein. Femoral canal contains lymph node of cloquet or Rosenmuller and lymphatics.","pyqMatches":[{"year":"2015","no":20,"q":"Content of femoral canal","o":["Femoral branch of genitofemoral nerve","Genital branch of genitofemoral nerve","Femoral vein","Lymph node"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (416, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 416, '{"id":416,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":416,"q":"Most common ligament damaged in knee injury is","o":["ACL","PCL","MCL","LCL"],"a":2,"e":"Ans. is ''c'' i.e., MCL [lRef; Textbook of sports medicine &/e p. l38l] Most commonly injured ligament in knee -+ Medial collateral ligament (MCL). MCL tear is the most common knee ligament injury\" MCL injury is the most common ligament injury to the knee\" Practical orthopaedics sports medicine MCL is the most commonly injured knee ligament\" ACL is the 2nd most commonly injured knee ligament, almost as frequent as MCL.","pyqMatches":[{"year":"2015","no":23,"q":"Most common ligament damaged in knee injury is","o":["ACL","PCL","MCL","LCL"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (417, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 417, '{"id":417,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":417,"q":"Distance of cricopharynx from incisor teeth","o":["15 cm","22.5 cm","27.5 cm","40 cm"],"a":0,"e":"Ans. is''a''i.e., 15 cm [Ref- BDC Sn/e Vol.l p. 269] Cricopharynx is at the level of pharyngo-esophageal junction i.e. beginning of esophagus. Its distance is 15 cm (6 inches) from incisor. Cardiac end is lower end of esophagus which is at 40 cm from incisors.","pyqMatches":[{"year":"2015","no":39,"q":"Distance of cricopharynx from incisor teeth","o":["15 cm","22.5 cm","27.5 cm","40 cm"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (418, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 418, '{"id":418,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":418,"q":"All veins open in sinus venarum except -","o":["SVC","Coronary sinus","Anterior cardiac vein","Small cardiac vein"],"a":3,"e":"Ans. is''d''i.e., Small cardiac vein [Ref: Gray''s 38e/e p. 14791 Small cardiac vein does not open into sinus venarum (Posterior smooth part of right atrium).","pyqMatches":[{"year":"2015","no":41,"q":"All veins open in sinus venarum except","o":["SVC","Coronary sinus","Anterior cardiac vein","Small cardiac vein"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (419, 'Anatomy', 'Thorax', 'Moderate', 'Anatomy', 419, '{"id":419,"subject":"Anatomy","chapter":"Thorax","difficulty":"Moderate","source":"Anatomy","sourceNo":419,"q":"Which structure does not pass through superior thoracic aperture -","o":["Right vagus","Right brachiocephalic artery","Thoracic duct","Right recurrent laryngeal nerve"],"a":3,"e":"Ans- Ans. is ''d'' i.e., Right recurrent laryngeal nerve [Ref- BDC 6h/e Vol.l p. 192] Thoracic inlet (superior aperture) The narrow upper end of the thorax, which is continuous with the neck is called the inlet of the thorax'' The structure passing through the inlet are : -l. Vkcera:- Trachea, esophagus, apex of lung with pleura, remains of the thymus, thoracic duct.","pyqMatches":[{"year":"2015","no":49,"q":"Which structure does not pass through superior thoracic aperture","o":["Right vagus","Right brachiocephalic artery","Thoracic duct","Right recurrent laryngeal nerve"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (420, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 420, '{"id":420,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":420,"q":"Common hepatic artery is a branch of -","o":["Splenic artery","Superior mesenteric artery","Inferior mesenteric artery","Coeliac trunk"],"a":3,"e":"Ans. is''d''i.e., Coeliac trunk [Ref BDC 6h/eVoI.2 p. 2761 Common hepatic artery is a branch of coeliac trunk.","pyqMatches":[{"year":"2015","no":63,"q":"Common hepatic artery is a branch of","o":["Splenic artery","Superior mesenteric artery","Inferior mesenteric artery","Coeliac trunk"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (421, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 421, '{"id":421,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":421,"q":"Esophageal varices occur in which portion of esophagus?","o":["Upper","Middle","Lower","All sites"],"a":2,"e":"Ans. is ''c'' i.e., Lower [Ref: AK Dutta P. 275, 2761 Esophageal varices occurs at lower end ofesophagus due to porto-caval anastomosis.","pyqMatches":[{"year":"2015","no":64,"q":"Esophageal varices occur in which portion of esophagus?","o":["Upper","Middle","Lower","All sites"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (422, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 422, '{"id":422,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":422,"q":"Anorectal angle is formed due to action of -","o":["Internal anal sphincter","Circular muscle layer of smooth muscles","Longitudinal muscle layer of smooth muscle","Puborectalis"],"a":3,"e":"Ans. is''d'' i.e., Puborectalis The ano-rectal angle (ARA) is the angle between longitudinal axis ofrectum (which is represented by posterior rectal line) and longitudinal axis ofanal canal. The normal average value is 95-96\" (physiological range 65- 100''). ARA is an indirect indicator of the puborectalis muscle activity. During muscle contraction, ARA becomes more acute, while during relaxing phase it becomes obtuse.","pyqMatches":[{"year":"2015","no":68,"q":"Anorectal angle is formed due to action of","o":["Internal anal sphincter","Circular muscle layer of smooth muscles","Longitudinal muscle layer of smooth muscle","Puborectalis"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (423, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 423, '{"id":423,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":423,"q":"Prostate analogue in female is -","o":["Skene gland","Bulbourethral gland","Great vestibular gland","Bartholin''s gland"],"a":0,"e":"Ans. is''a''i.e., Skene gland lRef: Clinical anatomy p.421] Prostate anolog in femal → > Skene glands (Periurethral glands). Uterus and vagina analog in male → > Prostatic utricle.","pyqMatches":[{"year":"2015","no":69,"q":"Prostate analogue in female is","o":["Skene gland","Bulbourethral gland","Great vestibular gland","Bartholin''s gland"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (424, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 424, '{"id":424,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":424,"q":"Tail of pancrease develops from -","o":["Hepatic diverticulum","Dorsal pancreatic duct","Ventral pancreatic duct","All of the above"],"a":1,"e":"Ans. is''b''i.e., Dorsal pancreatic duct [Ref I.B. Singh Vh/e p. 28]","pyqMatches":[{"year":"2015","no":73,"q":"Tail of pancrease develops from","o":["Hepatic diverticulum","Dorsal pancreatic duct","Ventral pancreatic duct","All of the above"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (425, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 425, '{"id":425,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":425,"q":"Haustrations are present in -","o":["Duodenum","Ileum","Jejunum","Colon"],"a":3,"e":"Ans. is ''d''i.e., Colon [Rel BDC #/e Vol.2 p. 2661","pyqMatches":[{"year":"2015","no":74,"q":"Haustrations are present in","o":["Duodenum","Ileum","Jejunum","Colon"],"a":3,"source":"NEET_2015_Paper.pdf"},{"year":"2016","no":25,"q":"Haustrations are present in","o":["Duodenum","Ileum","Jejunum","Colon"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2015","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (426, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 426, '{"id":426,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":426,"q":"Anterior relation to upper part of rectum in male is-","o":["Rectovesical pouch","Sacrum","Seminal vesicle","Ductus deference"],"a":0,"e":"Answer-is''a'' i.e., Rectovesical pouch lRef; BDC Ple Vol.2 p. 408} Anteriorly In males The upper two-thirds of the rectum is related to the rectovesical pouch with coils of intestine and sigmoid colon. The lower one-third of the rectum is related to the base of the urinary bladder, the terminal parts of the ureters, the seminal vesicles, the different ducts and the prostate.","pyqMatches":[{"year":"2015","no":77,"q":"Anterior relation to upper part of rectum in male is","o":["Rectovesical pouch","Sacrum","Seminal vesicle","Ductus deference"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (427, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 427, '{"id":427,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":427,"q":"Sensory nerve supply of gall bladder is through -","o":["Vagus nerve","Trigeminal nerve","Parasympathetic nerve","Facial nerve"],"a":0,"e":"Ans. is ''a'' i.e., Vagus nerve [Rel BDC &/e Vol.3 p. 2901 Pain sensory fibers to gall bladder are through Vagus, synpathetic and phrmic nerves. Thus gall bladder pain may be referred to-a) Through vagus to the stomach (epigastrium). Through the sympathetic nerves to the inferior angle of the right scapula. Lateral horn of thoracic 7 segment of spinal cord gives sympathetic fibres to coeliac ganglion through greater splanchnic nerve. T7 segment receives pain fibres from skin over inferior angle of scapula. So visceral pain is referred to somatic area. Through the phrenic nerve to the right shoulder (C4 gives fibres to phrenic nerve and supraclavicular nerves).","pyqMatches":[{"year":"2015","no":79,"q":"Sensory nerve supply of gall bladder is through","o":["Vagus nerve","Trigeminal nerve","Parasympathetic nerve","Facial nerve"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (428, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 428, '{"id":428,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":428,"q":"Ligament which prevents spleen to fall in left iliac fossa -","o":["Leinorenal ligament","Phrenicolic ligament","Upper pole of right kidney","Sigmoid colon"],"a":1,"e":"Answer- ''b''i.e., Phrenicolic ligament [Ref: Gruy''s 4Uh/e p. 1107, 1108, 12141 Spleen lies in left side of abdomen (left hypochondrium). But enlargment of spleen (splenomegaly) does not cause extension into left iliac fossa. A pathologically enlarged spleen extends downward and medially towards right iliac fossa because prenicocolic ligament and left colic flexure prevent a direct downward enlargement.","pyqMatches":[{"year":"2015","no":81,"q":"Ligament which prevents spleen to fall in left iliac fossa","o":["Leinorenal ligament","Phrenicolic ligament","Upper pole of right kidney","Sigmoid colon"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (429, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 429, '{"id":429,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":429,"q":"Labour pain in uterus is carried by","o":["Parasympathetic nerves","Sympathetic nerves","Pudendal nerve","Splanchnic nerve"],"a":1,"e":"Ans. is ''b''i.e., Sympathetic nerves [Ref: Clinical obstetics 3d/e p. 9121 Nerve supply of uterus: The uterus is supplied by both systems, sympathetic and parasyrnpathetic. Sympathetic system fibers arisefom Tn, Lt segments and carry painful sensations from the body of the uterus. Parasyrnpathetic fibers arise from S2, S3, S4 (in pelvic splanchnic nerve) and carry painful sensations from cenix.","pyqMatches":[{"year":"2015","no":85,"q":"Labour pain in uterus is carried by","o":["Parasympathetic nerves","Sympathetic nerves","Pudendal nerve","Splanchnic nerve"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (430, 'Anatomy', 'Head & Neck', 'Moderate', 'Anatomy', 430, '{"id":430,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Moderate","source":"Anatomy","sourceNo":430,"q":"Posterior relation of right kidney are all except -","o":["Diaphragm","Subcostal nerve","11th rib","Ilioinguinal nerve"],"a":2,"e":"Ans. is ''c'' i.e., 11th rib Posterior surface of both kidney is related to diaphragm, medial and lateral arcuate ligament, psoas major, quadratus lumborum, transversus abdominis, subcostal vessels, subcostal nerve, iliohypogastric nerve, and ilioinguinal nerve. In addition, the right kidney is related to 12th rib and the left kidney is related to 11th and 12th ribs.","pyqMatches":[{"year":"2015","no":88,"q":"Posterior relation of right kidney are all except","o":["Diaphragm","Subcostal nerve","11th rib","Ilioinguinal nerve"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (431, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 431, '{"id":431,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":431,"q":"Not True about blood supply of kidney -","o":["Renal vein drains into IVC","Renal artery is a branch of common iliac artery","Right renal artery passes behind IVC","Branches of renal artery are end arteries"],"a":1,"e":"Ans. is ''b''i.e., Renal artery is a branch of common iliac artery [Re/ BDC &/eVol.2 p. 313-3171 Each kidney is supplied by renal artery (branch of abdominal aorta) and is drained by renal vein to IVC. Renal artery:- Right renal artery is longer and passes behind IVC. Branches of the renal artery are end arteries.","pyqMatches":[{"year":"2015","no":89,"q":"Not True about blood supply of kidney","o":["Renal vein drains into IVC","Renal artery is a branch of common iliac artery","Right renal artery passes behind IVC","Branches of renal artery are end arteries"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (432, 'Anatomy', 'Abdomen', 'Moderate', 'Anatomy', 432, '{"id":432,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Moderate","source":"Anatomy","sourceNo":432,"q":"3''d part of duodenum is not related -","o":["Superior mesenteric vessels","Right ureter","Head of pancreas","Quadrate lobe of liver"],"a":3,"e":"Ans. is ''d'' i.e.,Quadrate lobe of liver [Ref BDC 6h/e VoL2 p.2sg_262] Anterior:- Superior mesenteric vessel Root of mesentery Posterior Right ureter Right psoas major Right testicular or ovarian vessels IVC Abdominal aorta with origin of inferior mesenteric artery Superior Head of pancreas with uncinate process. Inferior Coils of jejunum","pyqMatches":[{"year":"2015","no":94,"q":"3''d part of duodenum is not related","o":["Superior mesenteric vessels","Right ureter","Head of pancreas","Quadrate lobe of liver"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (433, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 433, '{"id":433,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":433,"q":"Correct sequence of uterine blood flow -","o":["Uterine A - Arcuate A Radial A Spiral A","Uterine A Radial A - Arcuate A Spiral A","Uterine A Spiral A Radial A Arcuate A","Uterine A Arcuate A → Spiral A - Radial A"],"a":0,"e":"Answer- is''a ''i.e., Uterine A - Arcuate A Radial A Spiral A [Ref: Textbook of OBG p. 3061 just Prior to contact with uterus, the uterine artery gives descending uterine artery Oaginal artery) which supply the isthmus, cervix and upper vagina. After joining the uterus, the uterine artery ascends along the lateral margin of uterus as ascending uterine artery. Asending uterine artery gives several branches between middle and outer thirds of myometrium. These are called arcuate arteries because of their semicircular course. Arcuate arteries give radial arteries which in turn terminate as spiral arteriole.","pyqMatches":[{"year":"2015","no":97,"q":"Correct sequence of uterine blood flow","o":["Uterine A - Arcuate A Radial A Spiral A","Uterine A Radial A - Arcuate A Spiral A","Uterine A Spiral A Radial A Arcuate A","Uterine A Arcuate A → Spiral A - Radial A"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (434, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 434, '{"id":434,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":434,"q":"Sternocleidomastoid muscle is examined by","o":["Turning the head towards the same side","Turning the head towards opposite side","Shrugging of shoulder","Overhead abduction"],"a":1,"e":"Ans. is ''b'' i.e., Turning the head towards opposite side [Rel BDC 6h/e VoI.3 p. 89] Contraction of one side of sternocleidomastoid causes :","pyqMatches":[{"year":"2015","no":100,"q":"Sternocleidomastoid muscle is examined by","o":["Turning the head towards the same side","Turning the head towards opposite side","Shrugging of shoulder","Overhead abduction"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (435, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 435, '{"id":435,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":435,"q":"Stapedius pulls stapes in which direction -","o":["Anterior","Superior","Inferior","Posterior"],"a":3,"e":"Ans. is ''d'' i.e., Posterior [Ref: Textbook of auditory processing p. 361 Contraction ofthe stapedius muscle pulls the stapes head in posterior direction. Contraction of tensor tympani pulls the malleus and tympanic membrane inward with a lateral to medial motion. Contraction of these muscles stiffen the tympanic membrane and ossicular chain thereby reducing the mobility of the middle ear and decreasing the sensitIVIty of ear to air-conducted sound.","pyqMatches":[{"year":"2015","no":99,"q":"Stapedius pulls stapes in which direction","o":["Anterior","Superior","Inferior","Posterior"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (436, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 436, '{"id":436,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":436,"q":"Major central nucleus of sympathetic system is","o":["Nucleus ambiguus","Nucleus tractus solitarius","Edinger-Westphal nucleus","Hypothalamus"],"a":3,"e":"Ans. is''d''i.e., Hypothalamus The highest seat of regulation of autonomic nervous system (both sympathetic & parasympathetic) is hypothalamus.","pyqMatches":[{"year":"2015","no":102,"q":"Major central nucleus of sympathetic system is","o":["Nucleus ambiguus","Nucleus tractus solitarius","Edinger-Westphal nucleus","Hypothalamus"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (437, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 437, '{"id":437,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":437,"q":"Dangerous area of scalp is -","o":["Superficial facia","Aponeurosis","Subaponeurotic tissue","Pericranium"],"a":2,"e":"Ans. is''c''i.e., Subaponeurotic tissue Loose subaponeurotic areolar tissue (4s layer) is called dangerous area of scalp because it contains emissary veins throughwhich infection in subaponeurotic space may spread readily to intracranial venous sinuses","pyqMatches":[{"year":"2015","no":104,"q":"Dangerous area of scalp is","o":["Superficial facia","Aponeurosis","Subaponeurotic tissue","Pericranium"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (438, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 438, '{"id":438,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":438,"q":"Which nerve is preserved in dissecting the superficial and deep lobes of parotid gland -","o":["Glossopharyngeal","Hypoglossal","Lingual","Facial"],"a":3,"e":"Ans. is ''d'' i.e., Facial [Ref- Anatomy recall by jared Antevil] The facial nerve separates parotid gland into superficial and deep lobes. Mandibular branch of facial nerve is most vulnerable to injury during parotid surgery","pyqMatches":[{"year":"2015","no":105,"q":"Which nerve is preserved in dissecting the superficial and deep lobes of parotid gland","o":["Glossopharyngeal","Hypoglossal","Lingual","Facial"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (439, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 439, '{"id":439,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":439,"q":"Which intrinsic ocular muscle is supplied by parasympathetic innervation -","o":["Superior rectus","Superior oblique","Constrictor pupillae","Dilator pupillae"],"a":2,"e":"Ans. is''c''i.e., Constrictor pupillae [Ref: Gray''s 39h/e p. 7101 Intraocular muscles (intraocular muscles) → Intraocular muscles are - A) Muscles of iris → There are two types of muscles in iris that control the size of pupil:","pyqMatches":[{"year":"2015","no":106,"q":"Which intrinsic ocular muscle is supplied by parasympathetic innervation","o":["Superior rectus","Superior oblique","Constrictor pupillae","Dilator pupillae"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (440, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 440, '{"id":440,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":440,"q":"Lips does not drain into which group of lymph nodes?","o":["Submandibular nodes","Sublingual nodes","Preauricular parotid","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., Preauricular parotid [Ref: BDC fi/e Vol. 3 p. 72-751 → The face possesses three areas from which lymphatic drainage is as follows :-","pyqMatches":[{"year":"2015","no":107,"q":"Lips does not drain into which group of lymph nodes?","o":["Submandibular nodes","Sublingual nodes","Preauricular parotid","None of the above"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (441, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 441, '{"id":441,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":441,"q":"Secretomotor fibers to parotid glands are through -","o":["Tympanic plexus","Geniculate ganglion","Greater petrosal nerve","None"],"a":0,"e":"Ans. is''A i.e., Tympanic plexus (Ref: BDC @/e Vol. 3 p. 111).","pyqMatches":[{"year":"2015","no":109,"q":"Secretomotor fibers to parotid glands are through","o":["Tympanic plexus","Geniculate ganglion","Greater petrosal nerve","None"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (442, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 442, '{"id":442,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":442,"q":"Features of facial nerve palsy are all except -","o":["Loss of salivation","Loss of lacrimation","Facial muscle paralysis","Loss of taste sensation from posterior tongue"],"a":3,"e":"Ans. is ''d'' i.e., Loss of taste sensation from posterior tongue [Ref: Dhingra 5''h/e p. 105, 106; Gray''s 39h/e p. 12131 Facial nerve paralysis produces following manifestations : → Weakness of the muscles of facial expression and eve closure. which results in :","pyqMatches":[{"year":"2015","no":110,"q":"Features of facial nerve palsy are all except","o":["Loss of salivation","Loss of lacrimation","Facial muscle paralysis","Loss of taste sensation from posterior tongue"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (443, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 443, '{"id":443,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":443,"q":"Nerve 3td ventricle is the cavity of -","o":["Mesencephalon","Rhombencephalon","Diencephalon","Telencephalon"],"a":2,"e":"Ans. is ''c'' i.e., Diencephalon (Ref: BDC Vol.-3 6h/e p. 324, 441) Part of Brain Cavity A)- forebrain (prosencephalon) i. Telencephalon(cerebrum) ii. Diencephalon (Thalamencephalon) Lateral ventricle Third ventricle B)- midbrain(mesencephalon) Cerebral aqueduct C)- Hindbrain (rhombencephalon) Fourth Ventricle","pyqMatches":[{"year":"2015","no":115,"q":"Nerve 3td ventricle is the cavity of","o":["Mesencephalon","Rhombencephalon","Diencephalon","Telencephalon"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (444, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 444, '{"id":444,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":444,"q":"Occulomotor nucleus is located in -","o":["Forebrain","Midbrain","Pons","Medulla"],"a":1,"e":"Ans. is''b'' i.e., Midbrain lRef: BDC 6/e Vol. 3 p'' 3501 Cranial nerves I, II → Forebrain Cranial nerves III, IV → Midbrain Cranial nerves V, VI, VII, VUI → Pons Cranial nerves IX, X, Xl, Xll → Medulla","pyqMatches":[{"year":"2015","no":116,"q":"Occulomotor nucleus is located in","o":["Forebrain","Midbrain","Pons","Medulla"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (445, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 445, '{"id":445,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":445,"q":"Which of the following is pure sensory nerve ?","o":["Trigeminal","Abducent","Trochlear","Olfactory"],"a":3,"e":"Ans. is''d''i.e., Olfactory Cranial nerves Pure sensory Pure motor Mixed Olfactory (I) Optic (II) Oculomotor (III) Trochlear (IV) Abducent (VI) Vestibulocochlear (VIII) Accessory (XI) Hypoglossal (XII) Trigeminal (V) Facial (VII) Glossopharyngeal (IX) Vagus (X)","pyqMatches":[{"year":"2015","no":117,"q":"Which of the following is pure sensory nerve ?","o":["Trigeminal","Abducent","Trochlear","Olfactory"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (446, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 446, '{"id":446,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":446,"q":"Olfactory Great cerebral vein of Galen drains into -","o":["Cavernous sinus","Basal vein","Internal cerebral vein","Straight sinus"],"a":3,"e":"Ans. is ''d'' i.e., Straight sinus Great cerebral vein of Galen is formed by the union of two internal cerebral veins. It is 2 cm long. It is drains into the straight sinus.","pyqMatches":[{"year":"2015","no":118,"q":"Olfactory Great cerebral vein of Galen drains into","o":["Cavernous sinus","Basal vein","Internal cerebral vein","Straight sinus"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (447, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 447, '{"id":447,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":447,"q":"Superficial middle cerebral vein drains into -","o":["Internal cerebral vein","Cavernous sinus","Great cerebral vein of Galen","Straight sinus"],"a":1,"e":"Ans. is ''b'' i.e., Cavernous sinus [Ref Textbook of neuroanatomy p. 189] Superficial middle cerebral vein It runs along the posterior ramus and stem of lateral sulcus. It drains blood from superolateral surface of the cerebral hemisphere into the cavernous sinus. It communicates with the superior sagittal and transverse sinus through vein of Trolard and vein of Labbe respectively.","pyqMatches":[{"year":"2015","no":119,"q":"Superficial middle cerebral vein drains into","o":["Internal cerebral vein","Cavernous sinus","Great cerebral vein of Galen","Straight sinus"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (448, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 448, '{"id":448,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":448,"q":"Major supply of medial surface of cerebral hemisphere","o":["Anterior cerebral artery","Posterior cerebral artery","Middle cerebral artery","Posterior inferior cerebellar artery"],"a":0,"e":"Ans. is ''a'' i.e., Anterior cerebral artery [Ref: BDC 6th/e Vol. 3 p. 461, 462] Cerebral cortex is supplied by branches of all three cerebral arteries. All the three surface receive branches from all three arteries. But each surface is supplied predominantly by one artery :?","pyqMatches":[{"year":"2015","no":120,"q":"Major supply of medial surface of cerebral hemisphere","o":["Anterior cerebral artery","Posterior cerebral artery","Middle cerebral artery","Posterior inferior cerebellar artery"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (449, 'Anatomy', 'Neuroanatomy', 'Moderate', 'Anatomy', 449, '{"id":449,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":449,"q":"Which nucleus is not seen in floor of the 4th ventricle -","o":["Abducens nucleus","Facial nucleus","Dorsal vagal nucleus","Hypoglossal nucleus"],"a":1,"e":"Ans.is''b''i.e.,Facial nucleus {RefBDC VoI.3 &/e p.410; Last''s l2n/e p. 482, 483} Medial eminence is present in each side of median sulcus. It presents facial colliculus formed by genu (recurving fibers) of facial nerve looping around abducens nucleus. Facial colliculus lies in pons (i.e. in pontine part of floor). Hypoglossal triangle overlying the hypoglossal nucleus and vagal triangle overlying dorsal nucleus of vagus. Both of these triangle lies in the medulla (medullary part of floor)","pyqMatches":[{"year":"2015","no":121,"q":"Which nucleus is not seen in floor of the 4th ventricle","o":["Abducens nucleus","Facial nucleus","Dorsal vagal nucleus","Hypoglossal nucleus"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (450, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 450, '{"id":450,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":450,"q":"Ventral tegmental decussation in cerebral peduncle is due to -","o":["Tectospinal tract","Tectobulbar tract","Vestibulospinal tract","Rubrospinal tract"],"a":3,"e":"Ans. is d''ie., Rubrospinal tract [Ref: BDC 6th/e Vol.3 p.398] Ventral tegmental decussation → Formed by decussation of rubrospinal tract. Dorsal tegmental decussation → Formed by decussation of tectospinal and tectobulbar tracts.","pyqMatches":[{"year":"2015","no":122,"q":"Ventral tegmental decussation in cerebral peduncle is due to","o":["Tectospinal tract","Tectobulbar tract","Vestibulospinal tract","Rubrospinal tract"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (451, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 451, '{"id":451,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":451,"q":"Oxyntic cells are present in -","o":["Pylorus","Cardiac notch","Body","None"],"a":2,"e":"Ans. is''c''i.e., Body Oxyntic.cells are present in principal glands of body and fundus. These glands are found in body and fundus. These glands contain mainly chief (peptic or zymogen) cells and parietal (oxyntic) cells. These glands also contain mucous neck cells, stem cells and enteroendocrine cells (argentaffin cells).","pyqMatches":[{"year":"2015","no":126,"q":"Oxyntic cells are present in","o":["Pylorus","Cardiac notch","Body","None"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (452, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 452, '{"id":452,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":452,"q":"First bone to start ossifying -","o":["Femur","Tibia","Scapula","Mandible"],"a":3,"e":"Ans. is''d''i.e., Mandible [Ref: T*tbook of anatomy with color Atlas p. I32l ''The mandible is one of the first bones in the body to start ossifying being next in this respect only to the clavicle.. Thus, First bone to start ossifying Clavicle. Second bone to start ossifying → Mandible.","pyqMatches":[{"year":"2015","no":127,"q":"First bone to start ossifying","o":["Femur","Tibia","Scapula","Mandible"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (453, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 453, '{"id":453,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":453,"q":"Hilton''s law is related to -","o":["Venous drainage","Blood supply","Nerve innervation","All of the above"],"a":2,"e":"Ans. is ''c'' i.e., Nerve innervation [Rel Textbook operative orthopaedics p. 7861 Hilton,s law states that nerves crossing a joint supplies that joint by giving branching to that joint","pyqMatches":[{"year":"2015","no":129,"q":"Hilton''s law is related to","o":["Venous drainage","Blood supply","Nerve innervation","All of the above"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (454, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 454, '{"id":454,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":454,"q":"Spermatogenesis begins at -","o":["Birth","5 years","Puberty","18 years"],"a":2,"e":"Ans. is''c''i.e., Puberty [Ref: Clinical embryology 3''d/e p'' 311] Spermatogenesis refers to the process of formation of spermatozoa (sperm) from primitite germ cells (spetmatogonia)'' spermatogenesis begins at puberty and continues throughout adult life to decline in old age.","pyqMatches":[{"year":"2015","no":130,"q":"Spermatogenesis begins at","o":["Birth","5 years","Puberty","18 years"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (455, 'Anatomy', 'Miscellaneous', 'Moderate', 'Anatomy', 455, '{"id":455,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anatomy","sourceNo":455,"q":"Which is not a stage of prophase -","o":["Diakinesis","Leptotene","Zygotene","Arachytene"],"a":3,"e":"Ans. is''d'' i.e., Arachytene lRef: Essentials of medical genetics by A''K'' Dutta 4''h/e p'' 111","pyqMatches":[{"year":"2015","no":131,"q":"Which is not a stage of prophase","o":["Diakinesis","Leptotene","Zygotene","Arachytene"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (456, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 456, '{"id":456,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":456,"q":"Fossa ovalis is a remnant of -","o":["Septum primum","Septum secundum","Septum spurium","AV cushion"],"a":0,"e":"Ans. is''a''i.e., Septum primum lRef: Readbeloul Actually ''floor of the fossa ovalis represents septum primum. Full fossa ovalis is a remnant of foramen ovale","pyqMatches":[{"year":"2012","no":20,"q":"Fossa ovalis is a remnant of ?","o":["Septum primum","Septum secundum","Ductus arteriosus","Ductus venosus"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2015","no":132,"q":"Fossa ovalis is a remnant of","o":["Septum primum","Septum secundum","Septum spurium","AV cushion"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2012","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (457, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 457, '{"id":457,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":457,"q":"Fibrous stroma of liver is derived from -","o":["Foregut endoderm","Midgut endoderm","Hindgut endoderm","Septum transversum"],"a":3,"e":"Ans. is''d i.e., Septum transversum Development Of liver Liver is developed from -i) Endoderm of foregut (endodermal diverticulum): Most of the liver (including hepatocytes) is derived from foregut endoderm. ii) Septnm transversum mesenchyme (mesoderm) : It gives rise to ligaments of the liver (except ligamentum teres), kupffer cells, hematopoietic cells, sinusoids and fibrous-areolar stroma of liver'' Ligamentum teres is derived from left umbilical vein.","pyqMatches":[{"year":"2015","no":134,"q":"Fibrous stroma of liver is derived from","o":["Foregut endoderm","Midgut endoderm","Hindgut endoderm","Septum transversum"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (458, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 458, '{"id":458,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":458,"q":"Heart tube is formed at -","o":["3 weeks","6 weeks","10 weeks","12 weeks"],"a":0,"e":"Ans. is''a''i.e., 3 weeks [Ref: Embryology by Indu Khurana p. 209] ''Tubular heart is formed at the end of 3d week\"","pyqMatches":[{"year":"2015","no":138,"q":"Heart tube is formed at","o":["3 weeks","6 weeks","10 weeks","12 weeks"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (459, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 459, '{"id":459,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":459,"q":"Heart tube is formed in","o":["Hyaluronic acid secreted by endocardium","Chondroitin sulfate secreted by endocardium","Hyaluronic acid secreted by myocardium","Chondroitin sulfate secreted by myocardium"],"a":2,"e":"Ans-Ans. is''c''i.e., Hyaluronic acid secreted by myocardium [Ref Textbook of Human Embryolog p. 7861 Cardiac jelly is a thick extracellular matrix rich in hyaluronic acid. It separates endothelial heart tube from myocardium. Cardiac jelly is secreted by myocardium.","pyqMatches":[{"year":"2015","no":139,"q":"Heart tube is formed in","o":["Hyaluronic acid secreted by endocardium","Chondroitin sulfate secreted by endocardium","Hyaluronic acid secreted by myocardium","Chondroitin sulfate secreted by myocardium"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (460, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 460, '{"id":460,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":460,"q":"Remnant of umbilical artery","o":["Ligamentum arteriosum","Ligament teres","Ligamentum venosum","Medial umbilical ligament"],"a":3,"e":"Ans. is''d''i.e., Medial umbilical ligament {Ref:Garg 2d/e p. 2151} Embryonic part Remnants Ductus arteriosus Ligamentum arteriosum Umbilical artery Proximal part : - Superior vesical artery. Distal part : - Medial umbilical ligament Umbilical vein (left) Ligamentum teres Ductus venosus Ligamentum venosus Septum prim urn Floor offossa ovalis Septum seconclum Annulus ovalis / Limbus fossa ovalis","pyqMatches":[{"year":"2015","no":140,"q":"Remnant of umbilical artery","o":["Ligamentum arteriosum","Ligament teres","Ligamentum venosum","Medial umbilical ligament"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (461, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 461, '{"id":461,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":461,"q":"False about limbus fossa ovalis -","o":["Situated above fossa ovalis","In right atrium","Derived from septum primum","Also called Annulus ovalis"],"a":2,"e":"Ans. is ''c'' i.e., Derived from septum primum Limbus fossa ovalis (also called annulus ovalis) is a thickened rim in right atrium, present above the fossa ovalis. It represents the lower free margin of septum secundum. (not septum primum.","pyqMatches":[{"year":"2015","no":144,"q":"False about limbus fossa ovalis","o":["Situated above fossa ovalis","In right atrium","Derived from septum primum","Also called Annulus ovalis"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (462, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 462, '{"id":462,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":462,"q":"Sertoli cells are derived from -","o":["Genital tubercle","Genital swelling","Primordial germ cells","Germinal epithelium"],"a":3,"e":"Ans. is ''d'' i.e., Germinal epithelium [Ref I.B.Singh embryology 9thie p. 278] Testis develops at genital ridge (urogenital ridge). ''Primordial germ cells'' are developed in the 4th week by proliferation of endodermal cells of the dorsal wall of hindgut (part of yolk sac). The primordial germ cells migrate into genital ridge, where proliferation of both germinal and nongerminal cells leads to formation of gonads. Genital ridge is covered by germinal epithelium (previous coelomic epithelium), which proliferates and forms sex cords (primitive seminiferous cords). Large number of sertoli cells are derived from these sex cords. Lyedig cells are also derived from sex cord, which in turn is derived from germinal epithelium.","pyqMatches":[{"year":"2015","no":145,"q":"Sertoli cells are derived from","o":["Genital tubercle","Genital swelling","Primordial germ cells","Germinal epithelium"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (463, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 463, '{"id":463,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":463,"q":"Prolactin secreting gland develops from -","o":["Infundibulum","Rathke''s pouch","Tuber cinereum","3rd ventricle"],"a":1,"e":"Ans. is ''b'' i.e., Rathke''s pouch Prolactin is secreted by anterior lobe of pituitary which develops from Rathke''s pouch.","pyqMatches":[{"year":"2015","no":146,"q":"Prolactin secreting gland develops from","o":["Infundibulum","Rathke''s pouch","Tuber cinereum","3rd ventricle"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (464, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 464, '{"id":464,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":464,"q":"Posterior cardinal vein develops into -","o":["Common iliac vein","Superior vena cava","Internal jugular vein","External jugular vein"],"a":0,"e":"Answer- a'' i.e., Common iliac vein fRef: Textbook of embryology p. 786 Derivatives of posterior cardinal veins, subcardinal veins and supracardinal veins are :","pyqMatches":[{"year":"2015","no":147,"q":"Posterior cardinal vein develops into","o":["Common iliac vein","Superior vena cava","Internal jugular vein","External jugular vein"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (465, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 465, '{"id":465,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":465,"q":"Superior vena cava develops from -","o":["Right anterior cardinal vein","Left anterior cardinal vein","Left common cardinal vein","Right subcardinal vein"],"a":0,"e":"Ans. is ''a'' i.e., Right anterior cardinal vein lRef: Textbook of embryologlt p. 7861 Superior vena cava (SVC) is derived from","pyqMatches":[{"year":"2015","no":148,"q":"Superior vena cava develops from","o":["Right anterior cardinal vein","Left anterior cardinal vein","Left common cardinal vein","Right subcardinal vein"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (466, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 466, '{"id":466,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":466,"q":"Which of the following is a derivative of Rathke''s pouch -","o":["Pars tuberalis","Neurohypophysis","Posterior pituitary","Pineal gland"],"a":0,"e":"Ans. is ''a'' i.e., Pars tuberalis lRef: Textbook of embryology p. 7861 The Rathke''s pouch is an ectodermal upgrowth from the stomodaeum in front of buccopharyngeal membrane The derivatives of Rathke''s pouch give rise to the various components of the anterior pituitary:","pyqMatches":[{"year":"2015","no":151,"q":"Which of the following is a derivative of Rathke''s pouch","o":["Pars tuberalis","Neurohypophysis","Posterior pituitary","Pineal gland"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (467, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 467, '{"id":467,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":467,"q":"Which of glial cell is mesodermal in origin -","o":["Macroglial cells","Microglial cells","Oligodendrocytes","Ependymal cells"],"a":1,"e":"Ans. is''b''i.e., Microglial cells Microglial cells are derived from mesenchymal (mesodermal) cells","pyqMatches":[{"year":"2015","no":152,"q":"Which of glial cell is mesodermal in origin","o":["Macroglial cells","Microglial cells","Oligodendrocytes","Ependymal cells"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (468, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 468, '{"id":468,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":468,"q":"What structure passes through the quandrangular space ?","o":["Axillary nerve","Radial nerve","Median nerve","Brachial Artery"],"a":0,"e":"Ans. is ''a'' i.e., Axillary nerve lRef Campbell''s 12h/e p. 22131 Axillary nerve and posterior circumflex humeral vessels are transmitted through quadrangular space","pyqMatches":[{"year":"2015","no":157,"q":"What structure passes through the quandrangular space ?","o":["Axillary nerve","Radial nerve","Median nerve","Brachial Artery"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (469, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 469, '{"id":469,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":469,"q":"Lower limit of superior mediastinum is at which level -","o":["Ti","T1","T8","T10"],"a":1,"e":"Ans. is ''b'' i.e., T1 [Ref. BDC &/e vol.l p. 245] Mediastinum is intrapleural space bounded on either side by mediastinal pleura, anteriorly by sternum and posteriorly by thoracic vertebral column. It is divided into superior and inferior mediastinum by a line passing through sternal angle and lower border ofTnvertebra.","pyqMatches":[{"year":"2015","no":33,"q":"Lower limit of superior mediastinum is at which level","o":["Ti","T1","T8","T10"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (470, 'Anatomy', 'Upper Limb', 'Moderate', 'Anatomy', 470, '{"id":470,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Moderate","source":"Anatomy","sourceNo":470,"q":"Which of the following is not the muscles of superfical anterior compartment of forearm ?","o":["FDS","FPL","FCR","Palmaris longus"],"a":1,"e":"Ans. B. FPL Muscles of superficial anterior compartment of forearm: ECR, FDS, FCU, Pronator teres, palmaris longus Muscles of deep anterior compartment of forearm: FDP, FPL, Pronator quadrantus.","pyqMatches":[{"year":"2013","no":38,"q":"Which of the following is not the muscles of superfical anterior compartment of forearm ?","o":["FDS","FPL","FCR","Palmaris longus"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (471, 'Anatomy', 'Lower Limb', 'Hard', 'Anatomy', 471, '{"id":471,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Hard","source":"Anatomy","sourceNo":471,"q":"In case of aberrant obturator artery, it arises most commonly from ?","o":["Common iliac artery","Femoral artery","Profunda femoris artery","Inferior epigastric artery"],"a":3,"e":"Ans. D. Inferior epigastric artery","pyqMatches":[{"year":"2013","no":77,"q":"In case of aberrant obturator artery, it arises most commonly from ?","o":["Common iliac artery","Femoral artery","Profunda femoris artery","Inferior epigastric artery"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (472, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 472, '{"id":472,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":472,"q":"Chief artery of lateral surface of cerebral hemisphere ?","o":["Anterior cerebral artery","Posterior cerebral artery","Middle cerebral artery","Posterior inferior cerebellar artery"],"a":2,"e":"Ans. C. Middle cerebral artery","pyqMatches":[{"year":"2013","no":104,"q":"Chief artery of lateral surface of cerebral hemisphere ?","o":["Anterior cerebral artery","Posterior cerebral artery","Middle cerebral artery","Posterior inferior cerebellar artery"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (473, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 473, '{"id":473,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":473,"q":"Which of the following is remnant of distal umbilical artery?","o":["Ligamentum Teres","Superior Vescical artery","Medial umbilical Ligament","Ligamentum arteriosum"],"a":2,"e":"Ans.C. Medial umbilical Ligament Remnant of umbilical artery:-","pyqMatches":[{"year":"2016","no":4,"q":"Which of the following is remnant of distal umbilical artery?","o":["Ligamentum Teres","Superior Vescical artery","Medial umbilical Ligament","Ligamentum arteriosum"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (474, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 474, '{"id":474,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":474,"q":"Female urethra develops from -","o":["Urogenital sinus","Mesonephric duct","Ureteric bud","Metanephric Blastema"],"a":0,"e":"Ans. A. Urogenital sinus The female urethra is mainly derived from the urogenital sinus while the urethral plate forms the vestibule and labia minora.","pyqMatches":[{"year":"2016","no":10,"q":"Female urethra develops from","o":["Urogenital sinus","Mesonephric duct","Ureteric bud","Metanephric Blastema"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (475, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 475, '{"id":475,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":475,"q":"All of the following help in formation of IVC except -","o":["The posterior intercardinal anastomosis","Terminal portion of right vitelline vein","Segment of right cardinal vein","Subcardinal sinus"],"a":3,"e":"Ans. D. Subcardinal sinus The inferior vena cava is composed of (from caudal to cranial):","pyqMatches":[{"year":"2016","no":11,"q":"All of the following help in formation of IVC except","o":["The posterior intercardinal anastomosis","Terminal portion of right vitelline vein","Segment of right cardinal vein","Subcardinal sinus"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (476, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 476, '{"id":476,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":476,"q":"Kidney parenchyma is derived from -","o":["Ureteric bud","Mesonephros","Metanephros","Paramesonephros"],"a":2,"e":"Ans. C. Metanephros Metanephros : This system will form the nephrons and parenchyma of the definitive kidney.","pyqMatches":[{"year":"2016","no":12,"q":"Kidney parenchyma is derived from","o":["Ureteric bud","Mesonephros","Metanephros","Paramesonephros"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (477, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 477, '{"id":477,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":477,"q":"Leptotene and pachytene are stages ofwhich phases of meiosis -","o":["Prophase I","Metaphase I","Anaphase II","Telophase II"],"a":0,"e":"Ans. A. Prophase I Meiosis 1 is divided into following phases :- l) Prophase 1: It is further divided into following stages:-","pyqMatches":[{"year":"2016","no":14,"q":"Leptotene and pachytene are stages ofwhich phases of meiosis","o":["Prophase I","Metaphase I","Anaphase II","Telophase II"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (478, 'Anatomy', 'Pelvis & Perineum', 'Moderate', 'Anatomy', 478, '{"id":478,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Moderate","source":"Anatomy","sourceNo":478,"q":"Pelvic kidneys are due to all except ?","o":["Inability to ascend during fetal life","Fusion of the lower poles","Being blocked by branches of the aorta","p53 mutation"],"a":3,"e":"Ans. D. p53 mutation Pelvic kidney A fetal pelvic kidney is a condition that results when the kidneys fail to ascend to their normal position above the waist and remain in the pelvis because they are blocked by blood vessels in the aorta. Developing kidneys may also fuse together causing what is known as a ''horseshoe kidney\" A fetal pelvic kidney or horseshoe kidney is generally diagnosed by ultrasound (sonogram) examination before birth. Evaluation of the kidneys is part of the routine ultrasound examination done by many obstetricians as part of their prenatal care around the 20s week of pregnancy.","pyqMatches":[{"year":"2016","no":15,"q":"Pelvic kidneys are due to all except ?","o":["Inability to ascend during fetal life","Fusion of the lower poles","Being blocked by branches of the aorta","p53 mutation"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (479, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 479, '{"id":479,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":479,"q":"Crypta magna develops from which pouch?","o":["1st","2nd","3rd","4th"],"a":1,"e":"Ans. B. 2nd Medial surface of each tonsil has 15-20 crypts, the largest of which is called Intratonsillar cleft or crypto magna (which represents persistence of the ventral portion of the second pharyngeal pouch).","pyqMatches":[{"year":"2016","no":16,"q":"Crypta magna develops from which pouch?","o":["1st","2nd","3rd","4th"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (480, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 480, '{"id":480,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":480,"q":"Which of the following is a traction epiphysis?","o":["Distal Radius","Mastoid process","Tibial Condyles","Coracoid Process"],"a":1,"e":"Ans. B. Mastoid process","pyqMatches":[{"year":"2012","no":26,"q":"Which of the following is a traction epiphysis ?","o":["Tibial condyles","Trochanter of femur","Coracoid process of scapula","Head of femur"],"a":1,"source":"NEET_2012_Paper.pdf"},{"year":"2016","no":17,"q":"Which of the following is a traction epiphysis?","o":["Distal Radius","Mastoid process","Tibial Condyles","Coracoid Process"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2012","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (481, 'Anatomy', 'Miscellaneous', 'Moderate', 'Anatomy', 481, '{"id":481,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anatomy","sourceNo":481,"q":"All of the following are true about the liver except ?","o":["It is covered by Glisson''s capsule","Stellate cells are present in the space of Disse","Kupfer cells are the defense cells","The lobules in the liver are pentagonal"],"a":3,"e":"Ans. D. The lobules in the liver are pentagonal Liver has hexagonal lobules","pyqMatches":[{"year":"2016","no":18,"q":"All of the following are true about the liver except ?","o":["It is covered by Glisson''s capsule","Stellate cells are present in the space of Disse","Kupfer cells are the defense cells","The lobules in the liver are pentagonal"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (482, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 482, '{"id":482,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":482,"q":"Hering''s canal is present in ?","o":["Spleen","Liver","Kidney","Lung"],"a":1,"e":"Ans, B. Liver 1he canal of Hering or intrahepatic bile ductules are part of outflow system of exocrine bile product from the liver. They are found between the bile canaliculi and interlobular bile ducts near the outer edge ofliver lobule.","pyqMatches":[{"year":"2016","no":19,"q":"Hering''s canal is present in ?","o":["Spleen","Liver","Kidney","Lung"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (483, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 483, '{"id":483,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":483,"q":"Herring''s bodies are present in?","o":["Pars tuberalis","Pars intermedia","Neurohypophysis","Pars terminal is"],"a":2,"e":"Ans. C. Neurohypophysis Herring bodies or neurosecretory bodies are structures found in the posterior pituitary (neurohypophysis).","pyqMatches":[{"year":"2016","no":20,"q":"Herring''s bodies are present in?","o":["Pars tuberalis","Pars intermedia","Neurohypophysis","Pars terminal is"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (484, 'Anatomy', 'Miscellaneous', 'Moderate', 'Anatomy', 484, '{"id":484,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anatomy","sourceNo":484,"q":"All of the following are true about thymus except?","o":["The cortical portion is mainly composed of lymphocytes","The medulla contains Hassall''s Corpuscles","It is derived from the fourth Pharyngeal pouch","It undergoes atrophy puberty onwards"],"a":2,"e":"Ans. C. It is derived from the fourth Pharyngeal pouch The thymus is a specialized primary lymphoid organ of the immune system. Within the thymus, T cells or T lymphocytes mature. The thymus is largest and most active during the neonatal and pre- adolescent periods. By the early teens, the thymus begins to atrophy and thymic stroma is mostly replaced by adipose (fat) tissue Thymus is derived from the third pharyngeal pouch","pyqMatches":[{"year":"2016","no":21,"q":"All of the following are true about thymus except?","o":["The cortical portion is mainly composed of lymphocytes","The medulla contains Hassall''s Corpuscles","It is derived from the fourth Pharyngeal pouch","It undergoes atrophy puberty onwards"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (485, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 485, '{"id":485,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":485,"q":"Which of the followinglayer is absent in the esophagusa -","o":["Adventitia","Serosa","Muscularis propria","Mucosa"],"a":1,"e":"Ans. B. Serosa The esophagus also has an adventitia, but not a serosa","pyqMatches":[{"year":"2016","no":23,"q":"Which of the followinglayer is absent in the esophagusa","o":["Adventitia","Serosa","Muscularis propria","Mucosa"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
