INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (487, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 487, '{"id":487,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":487,"q":"What is the lining of the lacrimal gland alveoli?","o":["Ciliated columnar cells","Pyramidal cells","Non keratinizing squamous epithelium","None"],"a":1,"e":"Ans. B. Pyramidal cells Alveoli of the gland are lined by pyramidal cells, which show lightly stained apical secretary granules.","pyqMatches":[{"year":"2016","no":26,"q":"What is the lining of the lacrimal gland alveoli?","o":["Ciliated columnar cells","Pyramidal cells","Non keratinizing squamous epithelium","None"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
