INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (489, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 489, '{"id":489,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":489,"q":"What is the level of the spine of scapula?","o":["T7","T I 0","T4","T2"],"a":2,"e":"Ans. C. T4 Spine of scapula is at T3T4level","pyqMatches":[{"year":"2016","no":30,"q":"What is the level of the spine of scapula?","o":["T7","T I 0","T4","T2"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (490, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 490, '{"id":490,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":490,"q":"Which of the following muscles carries out shoulder abduction from 15 to 90 degrees?","o":["Suprapinatus","Trapezius","Deltoid","Serratus Anterior"],"a":2,"e":"Ans. C. Deltoid","pyqMatches":[{"year":"2016","no":31,"q":"Which of the following muscles carries out shoulder abduction from 15 to 90 degrees?","o":["Suprapinatus","Trapezius","Deltoid","Serratus Anterior"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (491, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 491, '{"id":491,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":491,"q":"Which muscle acting on the thumb has dual nerve supply?","o":["Flexor Pollicis Longus","Flexor Pollicis brevis","Adductor Pollicis","Opponens Pollicis"],"a":1,"e":"Ans. B. Flexor Pollicis brevis","pyqMatches":[{"year":"2016","no":32,"q":"Which muscle acting on the thumb has dual nerve supply?","o":["Flexor Pollicis Longus","Flexor Pollicis brevis","Adductor Pollicis","Opponens Pollicis"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (492, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 492, '{"id":492,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":492,"q":"What is Wartenberg''s sign?","o":["Inability to maintain Intrinsic plus position","Inability to adduct small finger against the ring finger","Inability to grasp a book between the thumb and index finger","Inability to move the middle finger sideways"],"a":1,"e":"Ans, B. Inability to adduct small finger against the ring finger Wartenberg’s sign is inability to adduct the small finger in against the ring fnger due to weakness of palmar interosseous muscles.","pyqMatches":[{"year":"2016","no":33,"q":"What is Wartenberg''s sign?","o":["Inability to maintain Intrinsic plus position","Inability to adduct small finger against the ring finger","Inability to grasp a book between the thumb and index finger","Inability to move the middle finger sideways"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (493, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 493, '{"id":493,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":493,"q":"Sensory region of the ulnar nerve is?","o":["Tip of little finger","Tip of index finger","1st web space","Lateral upper aspect of arm"],"a":0,"e":"Ans. A. Tip of little finger","pyqMatches":[{"year":"2016","no":34,"q":"Sensory region of the ulnar nerve is?","o":["Tip of little finger","Tip of index finger","1st web space","Lateral upper aspect of arm"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (494, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 494, '{"id":494,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":494,"q":"Pulp of the index finger is supplied by","o":["Median nerve","Radial nerve","Ulnar nerve","Axillary nerve"],"a":0,"e":"Ans, A. Median nerve","pyqMatches":[{"year":"2016","no":35,"q":"Pulp of the index finger is supplied by","o":["Median nerve","Radial nerve","Ulnar nerve","Axillary nerve"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (495, 'Anatomy', 'Upper Limb', 'Moderate', 'Anatomy', 495, '{"id":495,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Moderate","source":"Anatomy","sourceNo":495,"q":"Low radial nerve [just after spiral groove] palsy does not produce ?","o":["Loss of wrist extention","Loss of elbow extention","Loss of finger extention","Loss of thumb extention"],"a":1,"e":"Ans. B. Loss of elbow extention Low radial nerve palsy Injury is after the spird groove. Low radial nerve palsy may be of two types : i) Type I: - Injury occurs between the spiral groove and elbow joint. Muscles involvement is : -","pyqMatches":[{"year":"2016","no":36,"q":"Low radial nerve [just after spiral groove] palsy does not produce ?","o":["Loss of wrist extention","Loss of elbow extention","Loss of finger extention","Loss of thumb extention"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (496, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 496, '{"id":496,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":496,"q":"Infraspinous fossa of scapula contains which of the following muscles?","o":["Subscapularis","Infraspinatus","Teres major","Supraspinatus"],"a":1,"e":"Ans. B. Infraspinatus Infraspinatus attaches medially to the infraspinous fossa of the scapula and laterally to the middle facet of the greater tubercle of the humerus.","pyqMatches":[{"year":"2016","no":37,"q":"Infraspinous fossa of scapula contains which of the following muscles?","o":["Subscapularis","Infraspinatus","Teres major","Supraspinatus"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (497, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 497, '{"id":497,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":497,"q":"Coracoacromial ligament resists which movements?","o":["Upward displacement of humeral head","Abduction of shoulder","Inferior displacement of humerus","External rotation"],"a":0,"e":"Ans. A. Upward displacement of humeral head The coracoacromial ligament is a flat triangular band that plays a supportive role for the shoulder joint. Coracoacromial prevents Upward displacement of humeral head. It has two part, conoid (medial) and trapezoid (lateral). The weight of the upper limb is transmitted to the medial two-third of the clavicle and thence to the axial skeleton through the coraco-clavicular ligment.","pyqMatches":[{"year":"2016","no":39,"q":"Coracoacromial ligament resists which movements?","o":["Upward displacement of humeral head","Abduction of shoulder","Inferior displacement of humerus","External rotation"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (498, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 498, '{"id":498,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":498,"q":"Coracohumeral ligament inserts on?","o":["Greater tuberosity","Lesser and greater tuberosities","Anatomical neck of humerus","Bicepetal groove"],"a":1,"e":"Ans. B. Lesser and greater tuberosities Coracohumeral ligament : An extraarticular ligament on the lateral surface ofcoracoid and inserts into the greater and lesser tuberosities, spanning the bicipital groove. Sectioning of coracohumeral ligaments produces anteroinferior instability. Represents folded thickening of glenohumeral capsule in area of rotator interval between subscapularis & supraspinatus. W/body upright & arm in dependent position, coracohumeral & MGHL play important roles in resisting inf translation.","pyqMatches":[{"year":"2016","no":40,"q":"Coracohumeral ligament inserts on?","o":["Greater tuberosity","Lesser and greater tuberosities","Anatomical neck of humerus","Bicepetal groove"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (499, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 499, '{"id":499,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":499,"q":"What is the action of anconeus?","o":["Primary elbow extensor","Assists Extension of elbow","Wrist extension","Thumb Abduction"],"a":1,"e":"Ans. B. Assists Extension of elbow Anconeus = Its role in elbow extension is trivial in humans. It assists in extension of the elbow, where the triceps brachii is the principal agonist, and supports the elbow in full extension.","pyqMatches":[{"year":"2016","no":41,"q":"What is the action of anconeus?","o":["Primary elbow extensor","Assists Extension of elbow","Wrist extension","Thumb Abduction"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (500, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 500, '{"id":500,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":500,"q":"Which muscle helps in climbing a tree ?","o":["Latissimus Dorsi","Rhomboideus","Trapezius","Levator scapulae"],"a":0,"e":"Ans. A. Latissimus Dorsi Climbing of tree is helped by:","pyqMatches":[{"year":"2016","no":42,"q":"Which muscle helps in climbing a tree ?","o":["Latissimus Dorsi","Rhomboideus","Trapezius","Levator scapulae"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (501, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 501, '{"id":501,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":501,"q":"Posterior interosseus artery is a branch of ?","o":["Common interosseus artery","Radial artery","Median artery","Brachial artery"],"a":0,"e":"Ans. A. Common interosseus artery The common interosseous artery, about 1 cm. in length, arises immediately below the tuberosity of the radius from the ulnar artery.","pyqMatches":[{"year":"2016","no":43,"q":"Posterior interosseus artery is a branch of ?","o":["Common interosseus artery","Radial artery","Median artery","Brachial artery"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (502, 'Anatomy', 'Upper Limb', 'Hard', 'Anatomy', 502, '{"id":502,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Hard","source":"Anatomy","sourceNo":502,"q":"Which muscle protects the brachial plexus in case of clavicle fractures?","o":["Subclavius","Supraspinatus","Subscapularius","Teres Minor"],"a":0,"e":"Ans. A. Subclavius The subclavius protects the underlying brachial plexus and subclavian vessels from a broken clavicle.","pyqMatches":[{"year":"2016","no":44,"q":"Which muscle protects the brachial plexus in case of clavicle fractures?","o":["Subclavius","Supraspinatus","Subscapularius","Teres Minor"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (503, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 503, '{"id":503,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":503,"q":"Which of the following is true about deep palmar arch?","o":["Mainly formed by the radial artery","Ulnar artery has no contribution to it","It gives off 5 perforating branches","It does not anastomose with the superficial palmar arch"],"a":0,"e":"Ans. A. Mainly formed by the radial artery Deep palmar arch It lies across the base of metacarpal bones. It is formed mainly by radial artery and completed by a deep branch of the ulnar artery. Its branches are:- Three palmar metacarpal arteries Three perforating arteries Recurrent branches The deep palmar arch lies deep to the oblique head of adductor pollicis, long flexor tendon, and lumbrical muscles and passes across the base of metacarpal and interossei.","pyqMatches":[{"year":"2016","no":45,"q":"Which of the following is true about deep palmar arch?","o":["Mainly formed by the radial artery","Ulnar artery has no contribution to it","It gives off 5 perforating branches","It does not anastomose with the superficial palmar arch"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (504, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 504, '{"id":504,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":504,"q":"Which part of scapula can be palpated in the infraclavicular fossa?","o":["Coracoid process","Spine of scapula","Inferior angle","Supraspinous fossa"],"a":0,"e":"Ans. A. Coracoid process The coracoid process is a thick curved process attached by a broad base to the upper part of the neck of the scapula; it runs at first upward and medial ward; then, becoming smaller, it changes its direction, and projects forward and lateralward. It is palpable just below the clavicle.","pyqMatches":[{"year":"2016","no":46,"q":"Which part of scapula can be palpated in the infraclavicular fossa?","o":["Coracoid process","Spine of scapula","Inferior angle","Supraspinous fossa"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (505, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 505, '{"id":505,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":505,"q":"Flexor carpi radialis inserts into ?","o":["Base of 5th metatarsal","Base of 2nd and 3rd metacarpal","Scaphoid and trapezium","Capitate and hamate"],"a":1,"e":"Ans., B. Base of 2nd and 3rd metacarpal Flexor carpi radialis Origin: Medial epicondyle of the humerus. Insertion: Base of second and third metacarpals. Nerve supply: Median nerve. Action: Pronator of the forearm, weak flexor of elbow.","pyqMatches":[{"year":"2016","no":47,"q":"Flexor carpi radialis inserts into ?","o":["Base of 5th metatarsal","Base of 2nd and 3rd metacarpal","Scaphoid and trapezium","Capitate and hamate"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (506, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 506, '{"id":506,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":506,"q":"What is true about lateral tibial condyle ?","o":["Iliotibial tract is attached to the lateral condyle of tibia","Ligamentum patellae inserts on it","Medial collateral ligament is attached to it","Semimembranosus is attached to it"],"a":0,"e":"Ans. A. Iliotibial tract is attached to the lateral condyle of tibia * Tibia is the second longest bone (after femur). * Proximal end (upper end) - Proximal (upper) end of tibia includes medial and lateral condyles, forming tibial plateau. It also includes tibial tuberosity and intercondylar area (area between medial and lateral condyle). - Distal end * Medial malleolus gives attachment to deltoid ligament (medial collateral ligament) of ankle.","pyqMatches":[{"year":"2016","no":48,"q":"What is true about lateral tibial condyle ?","o":["Iliotibial tract is attached to the lateral condyle of tibia","Ligamentum patellae inserts on it","Medial collateral ligament is attached to it","Semimembranosus is attached to it"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (507, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 507, '{"id":507,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":507,"q":"Weakness of extensor Hallucis longus is due to which nerve root mainly?","o":["L5","L4","S1","S2"],"a":0,"e":"Ans. A. L5","pyqMatches":[{"year":"2016","no":49,"q":"Weakness of extensor Hallucis longus is due to which nerve root mainly?","o":["L5","L4","S1","S2"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (508, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 508, '{"id":508,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":508,"q":"Which of the following is common between the medial and lateral plantar arch?","o":["Flexor Digitorum Brevis","Plantar Fascia","Spring Ligamnet","Deltoid Ligament"],"a":1,"e":"Ans, B. Plantar Fascia Plantar fascia acts as a tie beam for both medial and lateral plantar arches.","pyqMatches":[{"year":"2016","no":50,"q":"Which of the following is common between the medial and lateral plantar arch?","o":["Flexor Digitorum Brevis","Plantar Fascia","Spring Ligamnet","Deltoid Ligament"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (509, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 509, '{"id":509,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":509,"q":"Which tendon is lodged in the groove on posterior surface of lateral malleolus?","o":["Peroneus longus","Tibialis anterior","Tibialis posterior","Flexor Hallucis Longus"],"a":0,"e":"Ans, A. Peroneus longus Peroneus longus ends in a long tendon, which runs behind thelateral malleolus, in a groove common to it.","pyqMatches":[{"year":"2016","no":51,"q":"Which tendon is lodged in the groove on posterior surface of lateral malleolus?","o":["Peroneus longus","Tibialis anterior","Tibialis posterior","Flexor Hallucis Longus"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (510, 'Anatomy', 'Lower Limb', 'Moderate', 'Anatomy', 510, '{"id":510,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Moderate","source":"Anatomy","sourceNo":510,"q":"All of the following are true about tibialis anterior except ?","o":["It is supplied by the superficial peroneal nerve","It dorsiflexes the foot","It is closely related to the anterior tibial vessels","It inserts on the medial cuneiform"],"a":0,"e":"Ans. A. It is supplied by the superficial peroneal nerve Tibialis anterior It is situated on the lateral side of the tibia; it is thick and fleshy above, tendinous below. The tibialis anterior overlaps the anterior tibial vessels and deep peroneal nerve in the upper part of the leg.","pyqMatches":[{"year":"2016","no":52,"q":"All of the following are true about tibialis anterior except ?","o":["It is supplied by the superficial peroneal nerve","It dorsiflexes the foot","It is closely related to the anterior tibial vessels","It inserts on the medial cuneiform"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (511, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 511, '{"id":511,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":511,"q":"Attachment on posterior surface of sacrum?","o":["Multifidus Lumborum","Iliacus","Coccygeus","Piriformis"],"a":0,"e":"Ans, A. Multifidus Lumborum Attachements on sacrum A) Posterior Surface Multifidus lumborum – The deepest muscle arising from the sacrum. Some of its fibers cover the uPper two sacral foramina. This muscle attaches to the transverse processes of the superior vertebrae and is therefore able to help stabilize the spine. Erector spinae – Partly arises from the posterior sacrum and the sacrospinous ligament. It is essential in achieving extension and lateral bending of the head and vertebral column","pyqMatches":[{"year":"2016","no":53,"q":"Attachment on posterior surface of sacrum?","o":["Multifidus Lumborum","Iliacus","Coccygeus","Piriformis"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (512, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 512, '{"id":512,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":512,"q":"Structures passing through sacral hiatus are ?","o":["S4 nerve root","S2 nerve root","S3 nerve root","S5 nerve root"],"a":3,"e":"Ans. D. S5 nerve root Sacral hiatus The sacral hiatus corresponds to the posterior caudal opening at the end ofthe sacral canal, which usually occurs at the fifth sacral vertebra (S5), at the posterior surface ofthe sacrum.","pyqMatches":[{"year":"2016","no":54,"q":"Structures passing through sacral hiatus are ?","o":["S4 nerve root","S2 nerve root","S3 nerve root","S5 nerve root"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (513, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 513, '{"id":513,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":513,"q":"Longest cutaneous nerve in body ?","o":["Lateral cutaneous nerve of thigh","Medial cutaneous nerve of thigh","Saphenous nerve","Sural nerve"],"a":2,"e":"Ans, C. Saphenous nerve The saphenous branch of the femoral nerve (saphenous nerve) is the longest cutaneous nerve. It runs with the great saphenous vein in front of medial malleolus and supplies the skin of anteromedial aspect of the leg and medial border of the foot. The saphenous nerve may be damaged in front of the medial malleolus during venesection of the long saphenous vein. Therefore, femoral nerve damage can cause sensory loss over the area of the great saphenous vein in the leg.","pyqMatches":[{"year":"2016","no":55,"q":"Longest cutaneous nerve in body ?","o":["Lateral cutaneous nerve of thigh","Medial cutaneous nerve of thigh","Saphenous nerve","Sural nerve"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (514, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 514, '{"id":514,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":514,"q":"Oblique popliteal ligament is derived from ?","o":["Semitendinosus","Biceps femoris","Adductor magnus","Semimembranosus"],"a":3,"e":"Ans, D. Semimembranosus Oblique popliteal ligament It is an expansion from the tendon of semimembranosus attachment to intercondylar line of femur. It is closely related to popliteal artery and is pierced by middle genicular vessels and nerve and the terminal part of the posterior division of the obturator nerve.","pyqMatches":[{"year":"2016","no":56,"q":"Oblique popliteal ligament is derived from ?","o":["Semitendinosus","Biceps femoris","Adductor magnus","Semimembranosus"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (515, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 515, '{"id":515,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":515,"q":"Lateral border of the foot receives its sensory supply from ?","o":["Saphenous nerve","Sural nerve","Deep peroneal nerve","Sciatic nerve"],"a":1,"e":"Ans. B. Sural nerve","pyqMatches":[{"year":"2016","no":57,"q":"Lateral border of the foot receives its sensory supply from ?","o":["Saphenous nerve","Sural nerve","Deep peroneal nerve","Sciatic nerve"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (516, 'Anatomy', 'Thorax', 'Moderate', 'Anatomy', 516, '{"id":516,"subject":"Anatomy","chapter":"Thorax","difficulty":"Moderate","source":"Anatomy","sourceNo":516,"q":"All of the following is included in chest wall except?","o":["Ribs","Thoracic Vertebrae","Sternum","Lumbar vertebrae"],"a":3,"e":"Ans, D. Lumbar vertebrae","pyqMatches":[{"year":"2016","no":58,"q":"All of the following is included in chest wall except?","o":["Ribs","Thoracic Vertebrae","Sternum","Lumbar vertebrae"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (517, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 517, '{"id":517,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":517,"q":"Respiratory bronchioles are formed from ?","o":["Principal bronchus","Terminal bronchioles","Tertiary Bronchus","Lobar bronchioles"],"a":1,"e":"Ans, B. Terminal bronchioles Terminal bronchiole emnate into respiratory bronchioles. Repiratory bronchioles proceed into the alveolar ducts, which immediately branch into alveolar sacs (alveoli).","pyqMatches":[{"year":"2016","no":59,"q":"Respiratory bronchioles are formed from ?","o":["Principal bronchus","Terminal bronchioles","Tertiary Bronchus","Lobar bronchioles"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (518, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 518, '{"id":518,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":518,"q":"Segment of bronchi distal to primary bifurcation?","o":["Primary bronchi","Terminal bronchiole","Respiratory bronchiole","Sencondary bronchi"],"a":0,"e":"Ans. A. Primary bronchi","pyqMatches":[{"year":"2016","no":60,"q":"Segment of bronchi distal to primary bifurcation?","o":["Primary bronchi","Terminal bronchiole","Respiratory bronchiole","Sencondary bronchi"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (519, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 519, '{"id":519,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":519,"q":"The cricopharyngeal sphincter is how far from the central incisor?","o":["15cm","25cm","40cm","50cm"],"a":0,"e":"Ans, A. 15cm At the level of T1O vertebra, its passage through esophageal hiatus of diaphram lower esophageal sphincter- 37.5-40 cm (f5-f6 inches) from incisor","pyqMatches":[{"year":"2016","no":61,"q":"The cricopharyngeal sphincter is how far from the central incisor?","o":["15cm","25cm","40cm","50cm"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (520, 'Anatomy', 'Thorax', 'Moderate', 'Anatomy', 520, '{"id":520,"subject":"Anatomy","chapter":"Thorax","difficulty":"Moderate","source":"Anatomy","sourceNo":520,"q":"Which of the following structures is related to the esophagus 22.5cm from the incisor teeth?","o":["Arch of aorta","Right principal broncus","Thoracic Duct","Azygous Vein"],"a":0,"e":"Ans, A. Arch of aorta 2d constriction is at T4 level where arch of aorta crosses esophagus.","pyqMatches":[{"year":"2016","no":62,"q":"Which of the following structures is related to the esophagus 22.5cm from the incisor teeth?","o":["Arch of aorta","Right principal broncus","Thoracic Duct","Azygous Vein"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (521, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 521, '{"id":521,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":521,"q":"Thoracic duct opens into systemic circulation at?","o":["junction of SVC and left brachiocephalic vein","Junction of left internal jugular and left subclavian vein","Directly into coronary sinus","Into azygous vein"],"a":1,"e":"Ans. B. Junction of left internal jugular and left subclavian vein Thoracic duct begins as a continuation of the upper end of the cisternachy linear the lower border of T12 vertebra and enters the thorax through the aortic opening of diaphragrn (at T12). It then ascends through the posterior mediastinum and at T5 level crosses from right side to the left side and ascends along left margin of oesophagus to enter the neck. At the level of C7 vertebrae, arches towards left side to open into left brachiocephalic vein at the angle of union of left subclavian and left internal jugular veins.","pyqMatches":[{"year":"2016","no":63,"q":"Thoracic duct opens into systemic circulation at?","o":["junction of SVC and left brachiocephalic vein","Junction of left internal jugular and left subclavian vein","Directly into coronary sinus","Into azygous vein"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (522, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 522, '{"id":522,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":522,"q":"Sympathetic supply of the heart is from ?","o":["Vagus","Thoracic sympathetic fibres [T1 to T5]","Lumbar sympathetic fibres","Cervical ganglion"],"a":1,"e":"Ans, B. Thoracic sympathetic fibres [T1 to T5]","pyqMatches":[{"year":"2016","no":64,"q":"Sympathetic supply of the heart is from ?","o":["Vagus","Thoracic sympathetic fibres [T1 to T5]","Lumbar sympathetic fibres","Cervical ganglion"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (523, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 523, '{"id":523,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":523,"q":"Which of the following are cusps of the aortic valves?","o":["Left, right and Anterior","Anterior, Right and Posterior","Posterior, Left and Right","Anterior, Posterior and Left"],"a":2,"e":"Ans, C. Posterior, Left and Right The aortic valve is a semilunar valve with three cusps which include left, right and posterior.","pyqMatches":[{"year":"2016","no":65,"q":"Which of the following are cusps of the aortic valves?","o":["Left, right and Anterior","Anterior, Right and Posterior","Posterior, Left and Right","Anterior, Posterior and Left"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (524, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 524, '{"id":524,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":524,"q":"Which is the widow''s artery in myocardial infarction?","o":["Left anterior descending artery","Right coronary artery","Posterior interventricular artery","Left circumflex artery"],"a":0,"e":"Ans, A. Left anterior descending artery The anterior interventricular branch of the left coronary artery, (also left anterior descending artery (LAD), or anterior descending branch) is a branch of the left coronary artery. Occlusion of this artery is often called the widow-maker infarction and hence this artery is called a widow’s artery.","pyqMatches":[{"year":"2016","no":66,"q":"Which is the widow''s artery in myocardial infarction?","o":["Left anterior descending artery","Right coronary artery","Posterior interventricular artery","Left circumflex artery"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (525, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 525, '{"id":525,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":525,"q":"Which of the following passes posterior to the hilum of the lung?","o":["Vagus","Phrenic nerve","SVC","Right atrium"],"a":0,"e":"Ans, A. Vagus","pyqMatches":[{"year":"2016","no":67,"q":"Which of the following passes posterior to the hilum of the lung?","o":["Vagus","Phrenic nerve","SVC","Right atrium"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (526, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 526, '{"id":526,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":526,"q":"What is the level of the pulmonary valve?","o":["3rd intercostal space","4th costal cartilage","3rd costal cartilage","2nd intercostal space"],"a":2,"e":"Ans, C. 3rd costal cartilage","pyqMatches":[{"year":"2016","no":68,"q":"What is the level of the pulmonary valve?","o":["3rd intercostal space","4th costal cartilage","3rd costal cartilage","2nd intercostal space"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (527, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 527, '{"id":527,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":527,"q":"Lower limit of the inferior border of the lung in the midaxillary line is ?","o":["6th rib","8th rib","10th rib","12th rib"],"a":1,"e":"Ans, B. 8th rib The lower limit of the inferior border of the lung is 2 ribs above the reflection of the pleural. In the midaxillary line the pleura reflects at the 10th rib and hence the lower limit of the lung is 8th rib.","pyqMatches":[{"year":"2016","no":69,"q":"Lower limit of the inferior border of the lung in the midaxillary line is ?","o":["6th rib","8th rib","10th rib","12th rib"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (528, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 528, '{"id":528,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":528,"q":"Great cardiac vein lies in ?","o":["Tricuspid valve","Anterior interventricular sulcus","Posterior interventricular sulcus","None"],"a":1,"e":"Ans. is ''B'' i.e., Anterior interventricular sulcus [Ref BDC 4th/e Vol. I, p. 251-252; Keith Moore Clinical Anatomy hlth/e p. 136-137; Snell''s Clinical Anatomy9th/e p. 121] (Atrioventricular) sulcus → Great cardiac vein, coronary sinus, Small cardiac vein, RCA, LCX. Anterior interventricular sulcus → Great cardiac vein, left anterior descending (interventricular) artery. Posterior interventricular sulcus → Middle cardiac vein, Posterior interventricular branch of RCA.","pyqMatches":[{"year":"2016","no":71,"q":"Great cardiac vein lies in ?","o":["Tricuspid valve","Anterior interventricular sulcus","Posterior interventricular sulcus","None"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (529, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 529, '{"id":529,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":529,"q":"Apex at of the lung lies at what level?","o":["Above the clavicle","Below the clavicle","At the level of the clavicle","None"],"a":0,"e":"Ans. is ''a'' i.e., Above the clavicle [Ref BDC 4thie p. 222-228] Apex lies in the inlet of thorax, 2-5 cm above the clavicle. It is related anteriorly to subclavian artery and vein. Posteriorly it is separated from neck of first rib by (from medial to lateral) sympathetic trunk, fist posterior intercostal vein, superior intercostal artery, and ascending branch of ventral ramus of 1\" thoracic nerve.","pyqMatches":[{"year":"2016","no":72,"q":"Apex at of the lung lies at what level?","o":["Above the clavicle","Below the clavicle","At the level of the clavicle","None"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (530, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 530, '{"id":530,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":530,"q":"Diaphragm is supplied by ?","o":["Phrenic nerve","C2,C3,C4 Roots","Thoracodorsal nerve","Long thoracic nerve"],"a":0,"e":"Ans. is ''a'' i.e.,Phrenic nerve [Ref BDC 6th/e Vol I p. 192, fig. 12.12] Nerve supply Motor :- Phrenic nerve (C3C4C5). Sensory :- i) centrally by phrenic nerve. Peripherally by lower 6 intercostal nerves.","pyqMatches":[{"year":"2016","no":73,"q":"Diaphragm is supplied by ?","o":["Phrenic nerve","C2,C3,C4 Roots","Thoracodorsal nerve","Long thoracic nerve"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (531, 'Anatomy', 'Miscellaneous', 'Moderate', 'Anatomy', 531, '{"id":531,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anatomy","sourceNo":531,"q":"Midpoint between suprasternal notch and pubic symphyses passes through which plane?","o":["Transpyloric plane","Transtubercular plane","Trnasxiphoid plane","None"],"a":0,"e":"Ans. is ''a'' i.e.,Transpyloric plane [Ref BDC Vol-2 6th/e p. 229] Anterior abdominal wall is divided into 9 regions with the help of two vertical and two horizontal planes. The horizontal planes include : -","pyqMatches":[{"year":"2016","no":74,"q":"Midpoint between suprasternal notch and pubic symphyses passes through which plane?","o":["Transpyloric plane","Transtubercular plane","Trnasxiphoid plane","None"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (532, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 532, '{"id":532,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":532,"q":"Muscle lying between anterior and middle layer of thoracolumbar fascia is ?","o":["Psoas major","Quadratus Lumborum","Obdurator internus","External oblique"],"a":1,"e":"Ans. is ''b'' i.e., Quadratus Lumborum [Ref BDC 6th le Vol. 2 p. 343; Snell 9\" /e p. 695] Quadratus lomborum is enclosed between anterior and middle layers. Erector spinae (paraspinal muscle) is enclosed between middle and posterior layer.","pyqMatches":[{"year":"2016","no":75,"q":"Muscle lying between anterior and middle layer of thoracolumbar fascia is ?","o":["Psoas major","Quadratus Lumborum","Obdurator internus","External oblique"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (533, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 533, '{"id":533,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":533,"q":"Anterior Rectus Sheath just above pubic symphysis is formed by ?","o":["External Oblique Aponeurosis","The aponeurosis of three muscles including External Oblique, Internal Oblique, and Transversus Abdominis","Linea Alba","Internal Oblique only"],"a":1,"e":"Ans. is ''B'' i.e., Aponeurosis of three muscles including External Oblique, Internal Oblique, and Transversus Abdominis The anterior wall just above the symphysis pubis (area below the arcuate line) → is formed by aponeurosis of all three muscles (external oblique, internal oblique, transversus abdominis). Three aponeurotic layers forming rectus sheath of both sides interlace with each other to form a tendinous raphe, Linea alba. It extends from the xiphoid process to pubic symphysis. Linea alba is narrow and indistinct below the umbilicus, as two recti lie in close contact. Linea alba broadens out above the level of the umbilicus.","pyqMatches":[{"year":"2016","no":76,"q":"Anterior Rectus Sheath just above pubic symphysis is formed by ?","o":["External Oblique Aponeurosis","The aponeurosis of three muscles including External Oblique, Internal Oblique, and Transversus Abdominis","Linea Alba","Internal Oblique only"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (534, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 534, '{"id":534,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":534,"q":"Right suprarenal vein drains into ?","o":["Inferior vena cava","Right renal vein","Left renal vein","Accessory Hemiazygous vein"],"a":0,"e":"Ans. is ''a'' i.e., Inferior vena cava Arterial supply of adrenal gland is by three arteries:-","pyqMatches":[{"year":"2016","no":77,"q":"Right suprarenal vein drains into ?","o":["Inferior vena cava","Right renal vein","Left renal vein","Accessory Hemiazygous vein"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (535, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 535, '{"id":535,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":535,"q":"Which of the following is not derived from the external oblique aponeurosis?","o":["Inguinal Ligament","Lacunar ligament","Line Semilunaris","Pectineal Ligament"],"a":2,"e":"Ans. is ''c'' i.e., Line Semilunaris [Ref BDC 6th/e Vol 2 p. 343; Snell 91Ve p. 695] External oblique → Inguinal (Pouparts) ligament Lacunar ligament Mnemonic : IPL Pectineal (cooper''s) ligament Superficial inguinal ring External spermatic fascia Internal oblique → Cremasteric fascia & muscle Along with tendon of transversus abdominis forms conjoint tendon","pyqMatches":[{"year":"2016","no":78,"q":"Which of the following is not derived from the external oblique aponeurosis?","o":["Inguinal Ligament","Lacunar ligament","Line Semilunaris","Pectineal Ligament"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (536, 'Anatomy', 'Abdomen', 'Moderate', 'Anatomy', 536, '{"id":536,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Moderate","source":"Anatomy","sourceNo":536,"q":"Stomach wall is mainly drained by all lymphnodes except?","o":["Pyloric nodes","Short gastric vessel nodal group","Right gastroepiploic nodes","Inguinal nodes"],"a":3,"e":"Ans. is ''d'' i.e., Inguinal nodes [Ref Gray''s anatomy 20th edition] The stomach is drained by four groups of lymph nodes :","pyqMatches":[{"year":"2016","no":81,"q":"Stomach wall is mainly drained by all lymphnodes except?","o":["Pyloric nodes","Short gastric vessel nodal group","Right gastroepiploic nodes","Inguinal nodes"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (537, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 537, '{"id":537,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":537,"q":"All lymph of stomach drains into ?","o":["Pyloric nodes","Short gastric vessel nodal group","Right gastroepiploic nodes","Coeliac nodes"],"a":3,"e":"Ans. ''D'' i.e., Coeliac nodes All the vessels enter into the celiac node. From these nodes, they pass into the intestinal lymph trunks, which then enter the cisterna chyli or the abdominal confluence of lymph trunks. The cisterna chyli drains into the thoracic duct.","pyqMatches":[{"year":"2016","no":82,"q":"All lymph of stomach drains into ?","o":["Pyloric nodes","Short gastric vessel nodal group","Right gastroepiploic nodes","Coeliac nodes"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (538, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 538, '{"id":538,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":538,"q":"Gall bladder is realted to which segment of the liver?","o":["I","II","III","IV"],"a":3,"e":"Ans. is ''d'' i.e., IV [Ref Gray''s 40th le p. 1163-1167; Sabiston 18th/e p. 1584] The gall bladder lies on the inferior surface of the liver closely related to segment IV or the quadrate lobe. Anatomically liver is divided into a large right lobe and a small left lobe by line of attachment of falciform ligament (anterosuperiorly), fissure for ligamentum teres (inferiorly), and fissure for ligamentum venosum (posteriorly). Right lobe is much larger and forms five sixth of liver and left lobe forms only one sixth. Caudate lobe and quadrate lobe are parts of anatomical right lobe. The physiological left lobe is composed of 4 segments designated Ito IV and is supplied by left branch of hepatic artery, left branch of portal vein and drained by left hepatic duct. The physiological right lobe consists of segment V, VI, VII and VIII and is supplied by right hepatic artery, right branch of portal vein and drained by right hepatic duct.","pyqMatches":[{"year":"2016","no":83,"q":"Gall bladder is realted to which segment of the liver?","o":["I","II","III","IV"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (539, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 539, '{"id":539,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":539,"q":"Which segment of liver drains on both sides ?","o":["I","II","III","IV"],"a":0,"e":"Ans. is ''A'' i.e., I Caudate lobe (segment I) It is situated on the posterior surface of the right lobe. It is bounded on right by a groove for IVC, on left by fissure for ligamentum venosum, and inferiorly by porta hepatis (containing hepatic artery, portal vein, hepatic duct bile duct, nerve plexus, and lymphatics). Just behind the porta hepatis, the caudate lobe is connected to the rest of the right lobe by the caudate process. There is a small rounded elevation to the left, called the papillary process. Caudate lobe lies in the superior recess of lesser sac and is related to the crura of the diaphragm, right inferior phrenic artery, and coeliac trunk. Caudate lobe (anatomical part of the right lobe) belongs physiologically to both right and left lobes because it receives blood from the right and left hepatic arteries; right and left branches of the portal vein, and drains bile into both the right and left hepatic duct. Thus it is considered as the physiologically independent lobe.","pyqMatches":[{"year":"2016","no":84,"q":"Which segment of liver drains on both sides ?","o":["I","II","III","IV"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (540, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 540, '{"id":540,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":540,"q":"Caudate lobe of the liver - True is?","o":["It receives blood supply from both right and left hepatic arteries","It is Segment II of the liver","It is situated on the anterior surface of liver","It lies between the aorta and ligamentum venosum"],"a":0,"e":"Ans. is ''a'' i.e., It receives blood supply from both right and left hepatic arteries [Ref Ramesh Babu p. 249] Caudate tube (segment I) is situated on posterior surface of liver between IVC & ligamentum venosum. It receives blood supply from right & left arteries.","pyqMatches":[{"year":"2016","no":85,"q":"Caudate lobe of the liver - True is?","o":["It receives blood supply from both right and left hepatic arteries","It is Segment II of the liver","It is situated on the anterior surface of liver","It lies between the aorta and ligamentum venosum"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (541, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 541, '{"id":541,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":541,"q":"Superior border of epiploic foramen formed by -","o":["Caudate lobe","Hepatic artery","Bile duct","IVC"],"a":0,"e":"Ans. is ''a'' i.e., Caudate lobe Epiploic foramen (foramen of Winslow or aditus to lesser sac) is a slit-like opening through which lesser sac communicates with greater sac. It is situated at the level of T12 vertebra. Its boundaries are:- Anterior:- Right free margin of lesser omentum (contains portal vein, hepatic artery proper and bile duct). Posterior:- IVC, right suprarenal gland and T12 vertebra. Superior:- Caudate lobe of the liver. Inferior:- 1st part of the duodenum and horizontal part of the hepatic artery.","pyqMatches":[{"year":"2016","no":86,"q":"Superior border of epiploic foramen formed by","o":["Caudate lobe","Hepatic artery","Bile duct","IVC"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (542, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 542, '{"id":542,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":542,"q":"Internal anal Sphincter is formed by ?","o":["Puborectalis","Circular muscles from lower rectum","Longitudinal Involuntary muscles","None"],"a":1,"e":"Ans. is ''b'' i.e., Circular muscles from lower rectum [Ref BDC 4th/e Vol. H p. 383; Gray''s Anatomy 40thie Chapter 67] External sphincter is contributed by fibers from puborectalis part of levator ani muscle (in upper most part); superficial transverse perineal muscles anteriorly and anococcygeal raphe posteriorly (in upper third) and anococcygeal ligament (in middle third).","pyqMatches":[{"year":"2016","no":87,"q":"Internal anal Sphincter is formed by ?","o":["Puborectalis","Circular muscles from lower rectum","Longitudinal Involuntary muscles","None"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (543, 'Anatomy', 'Abdomen', 'Moderate', 'Anatomy', 543, '{"id":543,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Moderate","source":"Anatomy","sourceNo":543,"q":"All of the following are true about duodenum except?","o":["Fourth part is the shortest part","Ampulla of Vater opens through the second part","Minor duodenal papilla is in the third part","First part appears like a duodenal cap on barium studies"],"a":2,"e":"Ans. is ''c'' i.e., Minor duodenal papilla is in the third part [Ref BDC 6''1* Vol. 2 p. 259-262] Third part (Horizonal part) : It is 10 cm (4 inches) long. It begins at inferior duodenal flexure and passes towards the left in front of IVC behind superior mesenteric vessels and root of mesentery to meet 4th part of duodenum.","pyqMatches":[{"year":"2016","no":88,"q":"All of the following are true about duodenum except?","o":["Fourth part is the shortest part","Ampulla of Vater opens through the second part","Minor duodenal papilla is in the third part","First part appears like a duodenal cap on barium studies"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (544, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 544, '{"id":544,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":544,"q":"Which of the following is a branch of the inferior mesenteric artery?","o":["Sigmoid artery","Middle colic artery","Renal artery","Right Colic artery"],"a":0,"e":"Ans. is ''a'' i.e., Sigmoid artery [Ref BDC 6th/e yoi. 2 p. 276] Inferior mesentric artery gives following branches ?","pyqMatches":[{"year":"2016","no":89,"q":"Which of the following is a branch of the inferior mesenteric artery?","o":["Sigmoid artery","Middle colic artery","Renal artery","Right Colic artery"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (545, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 545, '{"id":545,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":545,"q":"Waldeyer''s fascia connects ?","o":["Rectum to sacrum","Rectum to uterus","Rectum to lateral wall of pelvis","Rectum to bladder"],"a":0,"e":"Ans. is ''a'' i.e., Rectum to sacrum [Ref Clinical anotomy 2\"d le p. 786] Support of rectum include","pyqMatches":[{"year":"2016","no":90,"q":"Waldeyer''s fascia connects ?","o":["Rectum to sacrum","Rectum to uterus","Rectum to lateral wall of pelvis","Rectum to bladder"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (546, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 546, '{"id":546,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":546,"q":"Content of Alcock''s canal is ?","o":["Internal pudendal artery","Internal iliac artery","Inferior rectal vein","Inferior mesenteric vein"],"a":0,"e":"Ans. is ''a'' i.e.,Internal pudendal artery [Ref BDC 6th/e Vol-2 p. 362] Pudendal canal (Alcock''s canal) is a fascial canal in the lateral wall of ischeorectal (ischeo-anal) fossa, enclosing pudendal nerve and internal pudendal vessels (artery and vein). It is a space between obturator fascia and lunate fascia. Other believe that it is formed by splitting of the obturator fascia.","pyqMatches":[{"year":"2016","no":91,"q":"Content of Alcock''s canal is ?","o":["Internal pudendal artery","Internal iliac artery","Inferior rectal vein","Inferior mesenteric vein"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (547, 'Anatomy', 'Abdomen', 'Moderate', 'Anatomy', 547, '{"id":547,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Moderate","source":"Anatomy","sourceNo":547,"q":"All of the following organs are in direct contact with the spleen except?","o":["Duodenum","Stomach","Left kidney","Colon"],"a":0,"e":"Ans. is ''a'' i.e., Duodenum Gross morphology of the spleen Spleen has two ends (anterior or lateral and posterior or medial), three borders (superior, inferior and intermediate), two surfaces (visceral and diaphragmatic), two angles (anterobasal angle and posterobasal angle) and hilum. The anterior end is supported by the phrenicocolic ligament. The superior border is characteristically notched near its anterior end. The visceral surface is related to the fundus of stomach (at gastric impression), left kidney (at renal impression), splenic flexure of the colon (at colic impression) and tail of the pancreas (at pancreatic impression). Its lower end is related to the phrenicocolic ligament. The diaphragmatic surface is related to the diaphragm.","pyqMatches":[{"year":"2016","no":92,"q":"All of the following organs are in direct contact with the spleen except?","o":["Duodenum","Stomach","Left kidney","Colon"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (548, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 548, '{"id":548,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":548,"q":"Glans penis is a continuation of -","o":["Corpus spongiosum","Ischiocavernosus","Corpora Cavernosa","Puborectalis"],"a":0,"e":"Ans. is ''A'' i.e., Corpus spongiosum The penis is the male organ of copulation. The penis has a root and a body. The root of the penis is situated in the superficial perinea! pouch, attached to the inferior surface of the perineal membrane. It consists of three masses of erectile tissue: the bulb of the penis and two crura. Each crus continues forward to become the corpus cavernusum (in the body) and the bulb is the posterior end of the corpus spongiosum (of the body). The body of the penis is the free portion of the penis. It is composed of three elongated masses of erectile tissues:- right and left corpora cavernosa, and median corpus spongiosum. Corpora cavernosae are enveloped by tunica albuginea and corpus spongiosum is also surrounded by tunica albuginea. The penile urethra runs through the whole length of the corpus spongiosum from the bulb at the back to the terminal expanded part of the corpus spongiosum, called the glans penis.","pyqMatches":[{"year":"2016","no":93,"q":"Glans penis is a continuation of","o":["Corpus spongiosum","Ischiocavernosus","Corpora Cavernosa","Puborectalis"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (549, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 549, '{"id":549,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":549,"q":"Which muscle causes opening of the upper end of esophagus?","o":["Epiglottis","Thyropharungeus","Stylopharyngeus","Cricopharyngeus of inferior constrictor"],"a":3,"e":"Ans. is ''d'' i.e., Cricopharyngeus of inferior constrictor [Ref Hall, Arthur C. Guyton, John E. (2005). Textbook of medical physiology (11th ed.). Philadelphia: W.B. Saunders. p. 782-784.] Upper esophageal sphinctor The upper esophageal sphincter surrounds the upper part of the esophagus. It consists of skeletal muscle, but is not under voluntary control. Opening of the upper esophageal sphincter is triggered by the swallowing reflex. The primary muscle of the upper esophageal sphincter is the cricopharyngeal part of the inferior pharyngeal constrictor.","pyqMatches":[{"year":"2016","no":94,"q":"Which muscle causes opening of the upper end of esophagus?","o":["Epiglottis","Thyropharungeus","Stylopharyngeus","Cricopharyngeus of inferior constrictor"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (550, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 550, '{"id":550,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":550,"q":"Posterior perforation of stomach, collection of contents occurs in which pouch ?","o":["Greater sac","Left subhepatic and hepatorenal spaces [pouch of Morrison]","Omental bursa","Right subphrenic space"],"a":2,"e":"Ans. is ''B'' i.e., Left subhepatic and hepatorenal spaces [pouch of Morrison] A posterior gastric ulcer may perforate into the lesser sac (omental bursa). The leaking fluid passes out through epiploic foramen to reach the hepatorenal pouch. Sometimes in these cases the epiploic foramen is closed by adhesions. Then the lesser sac becomes distended, and can be drained by a tube passed through the lesser omentum.","pyqMatches":[{"year":"2016","no":95,"q":"Posterior perforation of stomach, collection of contents occurs in which pouch ?","o":["Greater sac","Left subhepatic and hepatorenal spaces [pouch of Morrison]","Omental bursa","Right subphrenic space"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (551, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 551, '{"id":551,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":551,"q":"Cremastric muscle is formed from ?","o":["Fascia from internal oblique","Fascia from external oblique","Fascia from rectus abdominis","Fascia from transversus abdominis"],"a":0,"e":"Ans. is ''a'' i.e., Fascia from internal oblique The layers of scrotum from outside to inside are :-","pyqMatches":[{"year":"2016","no":96,"q":"Cremastric muscle is formed from ?","o":["Fascia from internal oblique","Fascia from external oblique","Fascia from rectus abdominis","Fascia from transversus abdominis"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (552, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 552, '{"id":552,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":552,"q":"Kidney is covered by what fascia?","o":["Sibson''s fascia","Buck''s Fascia","Gerota''s Fascia","None"],"a":2,"e":"Ans. is ''c'' i.e., Gerota''s Fascia [Ref Farlex Partner Medical Dictionary Farlex 2012] Renal fascia There are four coverings around the kidney (from within outwords) :- True capsule (fibrous capsule) It is formed by the condensation of fibrous stroma of kidney. False capsule (renal fascia or fascia of Gerota) It is formed by condensation of extra-peritoneal connective tissue around kidney and is continuous laterally with fascia transversalis. False capsule consists of two layers : anterior \"fascia of Toldt\" and posterior \"fascia of Zuckerkendl\".","pyqMatches":[{"year":"2016","no":97,"q":"Kidney is covered by what fascia?","o":["Sibson''s fascia","Buck''s Fascia","Gerota''s Fascia","None"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (553, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 553, '{"id":553,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":553,"q":"Narrowest part of ureter is ?","o":["Brim of the pelvis","Crossing by gonadal vessels","Vesicouretric junction","Crossing by ductus deferens"],"a":2,"e":"Ans. is ''c'' i.e., Vesicouretric junction [Ref Campbellis urology 6thle p. 2123; Gray''s Anatomy for students 1\"/e p. 325] Ureter measures about 3 mm in diameter, but is constricted at five places","pyqMatches":[{"year":"2016","no":98,"q":"Narrowest part of ureter is ?","o":["Brim of the pelvis","Crossing by gonadal vessels","Vesicouretric junction","Crossing by ductus deferens"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (554, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 554, '{"id":554,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":554,"q":"What is the total length of the colon?","o":["1 metre","1.5 metres","2 metres","4 metres"],"a":1,"e":"Ans. is ''b'' i.e., 1.5 metres [Ref BDC Vol. II ele p. 269-273] The large intestine extends from the ileocaecal junction to anus. It is 1.5 meters long and is divided into caecum, ascending colon, right colic (hepatic) flexure, transverse colon, left colic (splenic)flexure, descending colon, sigmoid colon, the rectum and anal canal. Transverse colon is longest part (50 cm) and anal canal shortest (3.8 cm). Caecum → 6 cm Sigmoid colon→ 37.5 cm Ascending colon -› 12.5 cm Rectum → 12 cm Transverse colon → 50 cm Anal canal → 3.8 cm Descending colon → 25 cm","pyqMatches":[{"year":"2016","no":99,"q":"What is the total length of the colon?","o":["1 metre","1.5 metres","2 metres","4 metres"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (555, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 555, '{"id":555,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":555,"q":"Submandibular lymphnodes drain the following areas of the face except?","o":["Medial half of eyelids","Central part of lower lip","Medial part of cheek","Central part of fore head"],"a":1,"e":"Ans. is ''b'' i.e., Central part of lower lip [Ref BDC Vol. III 6th/e p. 73] Lymphatic drainage of face The face possesses three areas from which lymphatic drainage is as follows:?","pyqMatches":[{"year":"2016","no":100,"q":"Submandibular lymphnodes drain the following areas of the face except?","o":["Medial half of eyelids","Central part of lower lip","Medial part of cheek","Central part of fore head"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (556, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 556, '{"id":556,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":556,"q":"Larynx below the vocal cords drain into ?","o":["Pretracheal lymph nodes","Occipital lymphnodes","Mediastinal nodes","Lymphatics along the superior laryngeal vein"],"a":0,"e":"Ans. is ''a'' i.e., Pretracheal lymph nodes Supraglottic part (Above vocal cord) Lymphatics along the superior laryngeal vein and nodes adjacent to the thyrohyoid membrane Infraglottic part (Below vocal cord) Pretracheal and prelaryngeal nodes Vocal cords Devoid of lymphatic supply","pyqMatches":[{"year":"2016","no":101,"q":"Larynx below the vocal cords drain into ?","o":["Pretracheal lymph nodes","Occipital lymphnodes","Mediastinal nodes","Lymphatics along the superior laryngeal vein"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (557, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 557, '{"id":557,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":557,"q":"Nerve supply to the angle of the mandible is by ?","o":["Posterior primary rami of C2, C3","Greater auricular nerve","Maxillary nerve","Mandibular nerve"],"a":1,"e":"Ans. is ''b'' i.e., Greater auricular nerve The skin over the angle of the jaw (mandible) is supplied by the anterior division of the greater auricular nerve.","pyqMatches":[{"year":"2016","no":102,"q":"Nerve supply to the angle of the mandible is by ?","o":["Posterior primary rami of C2, C3","Greater auricular nerve","Maxillary nerve","Mandibular nerve"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (558, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 558, '{"id":558,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":558,"q":"Nerve supply to the tip of the nose is from?","o":["The ophthalmic division of the trigeminal nerve","Greater auricular nerve","The maxillary division of the trigeminal nerve","Mandibular nerve"],"a":0,"e":"Ans. is ''a'' i.e., Ophthalmic division of the trigeminal nerve Tip of the nose and lower part of the dorsum of the nose are supplied by the external nasal branch of the ophthalmic division of the trigeminal nerve.","pyqMatches":[{"year":"2016","no":103,"q":"Nerve supply to the tip of the nose is from?","o":["The ophthalmic division of the trigeminal nerve","Greater auricular nerve","The maxillary division of the trigeminal nerve","Mandibular nerve"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (559, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 559, '{"id":559,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":559,"q":"Dangerous space in the neck is found between?","o":["Buccopharyngeal fascia and alar fascia","Prevertebral fascia and alar fascia","Buccopharyngeal fascia and Prevertebral fascia","None"],"a":1,"e":"Ans. is ''b'' i.e.,Prevertebral fascia and alar fascia [Ref \"Severe soft tissue infections of the head and neck: a primer for critical care physicians\". Lung. 187 (5): 271-9.] The danger space or alar space, is a region of the neck. The common name originates from the risk that an infection in this space can spread directly to the thorax, and, due to being a space continuous on the left and right, can furthermore allow infection to spread easily to either side. It is bounded superiorly by the skull base, anteriorly by the alar fascia and posteriorly by the prevertebral fascia. It comes to an end at the level of the diaphragm. The retropharyngeal space is found anterior to the danger zone, between the alar fascia and buccopharyngeal fascia","pyqMatches":[{"year":"2016","no":104,"q":"Dangerous space in the neck is found between?","o":["Buccopharyngeal fascia and alar fascia","Prevertebral fascia and alar fascia","Buccopharyngeal fascia and Prevertebral fascia","None"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (560, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 560, '{"id":560,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":560,"q":"Which muscle is attached to the disc of the temporomandibular joint?","o":["Buccinator","Lateral pterygoid","Masseter","Temporalis"],"a":1,"e":"Ans. is ''B i.e., Lateral pterygoid [Ref BDC 415/e Vol. 3 p. 145; Last''s anatomy 11''\"/e Lateral pterygoid origin→ Upper head: Infra temporal surface & crest of greater wing of sphenoid. Lower head: Lateral surface of lateral pterygoid plate. Nerve supply→ Pterygoid fovea on Anterior division of the neck of man → mandibular nerve. an audible, Articular disc and capsule of temporomandibular joint. Action → Depresses the mandible. Protrusion and side to side movement.","pyqMatches":[{"year":"2016","no":105,"q":"Which muscle is attached to the disc of the temporomandibular joint?","o":["Buccinator","Lateral pterygoid","Masseter","Temporalis"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (561, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 561, '{"id":561,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":561,"q":"Maxillary tubercle gives attachment to ?","o":["Lateral pterygoid","Medial pterygoid","Temporalis","Masseter"],"a":1,"e":"Ans. is ''b'' i.e., Medial pterygoid [Ref BDC Vol III 6th le p. 116] Medial Pterygoid Origin: Superficial head: Tuberosity of maxilla. Deep head: Medial surface of lateral pterygoid plate & pyramidal process of palatine bone. Insertion: Medial surface of angle mandible & adjoining ramus. Nerve supply: Branch from trunk of mandibular nerve Action : Elevates the mandible, Protection & side to side movement.","pyqMatches":[{"year":"2016","no":106,"q":"Maxillary tubercle gives attachment to ?","o":["Lateral pterygoid","Medial pterygoid","Temporalis","Masseter"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (562, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 562, '{"id":562,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":562,"q":"Vidian nerve is also known as?","o":["Nerve of Pterygoid canal","Greater Petrosal nerve","Lesser Petrosal nerve","Greater Auricular nerve"],"a":0,"e":"Ans. is ''a'' i.e., Nerve of Pterygoid canal The nerve of the pterygoid canal (Vidian nerve) is formed by the junction of the greater petrosal nerve and the deep petrosal nerve within the pterygoid canal containing the cartilaginous substance, which fills the foramen lacerum. It passes forward through the pterygoid canal with its corresponding artery (artery of the pterygoid canal) and is joined by a small ascending sphenoidal branch from the otic ganglion. It then enters the pterygopalatine fossa and joins the posterior angle of the pterygopalatine ganglion.","pyqMatches":[{"year":"2016","no":107,"q":"Vidian nerve is also known as?","o":["Nerve of Pterygoid canal","Greater Petrosal nerve","Lesser Petrosal nerve","Greater Auricular nerve"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (563, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 563, '{"id":563,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":563,"q":"Right Recurrent laryngeal nerve loops around?","o":["Right subclavian artery","Right axillary artery","Right External carotid artery","Right Superior thyroid artery"],"a":0,"e":"Ans. is ''a'' i.e., Right subclavian artery [Ref Larsen, William J. (1993). Human embryology] Recurrent laryngeal nerve On right side it arises in the root of neck and winds around first part of right subclavian artery. It may be anterior (superficial) or posterior (deep) to inferior thyroid artery. On left side it arises in thorax (superior mediastinum) and wind''s around the arch of aorta immediately behind the attachment of ligamentum arteriosum. It is usually posterior (deep) to inferior thyroid artery or between its branches. Recurrent laryngeal nerve supplies all intrinsic muscles of larynx (except cricothyroid) and mucous membrane of larynx below vocal fold. It also gives branches to deep cardiac plexus, trachea, esophagus and inferior constrictior. Inferior thyroid artery is ligated away from gland to avoid injury to nerve. Left nerve is more liable to damage.","pyqMatches":[{"year":"2016","no":109,"q":"Right Recurrent laryngeal nerve loops around?","o":["Right subclavian artery","Right axillary artery","Right External carotid artery","Right Superior thyroid artery"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (564, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 564, '{"id":564,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":564,"q":"Left recurrent laryngeal passes between ?","o":["Trachea & larynx","Trachea & esophagus","Esophagus and bronchi","Esophagus and aorta"],"a":1,"e":"Ans. is ''b'' i.e., Trachea & esophagus [Ref Gray''s 38th/e p. 786] The paths of the left and right recurrent laryngeal nerves very slightly with the left recurrent laryngeal nerve dividing from the main vegus nerve at the level of the aortic arch. The left recurrent laryngeal nerve than dips posteriorly around the arotic arch to assend through the superior mediastinum to enter the groove between the esophagus and trachea. The right recurrent laryngeal nerve divides from the main vagus nerve at the level of the right subclavian artery to enter the superior mediastinum. The right recurrent laryngeal nerve then dips posteriorly around the subclavian artery to assend in the grove between the esophagus and trachea.","pyqMatches":[{"year":"2016","no":110,"q":"Left recurrent laryngeal passes between ?","o":["Trachea & larynx","Trachea & esophagus","Esophagus and bronchi","Esophagus and aorta"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (565, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 565, '{"id":565,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":565,"q":"Structures pierced by the parotid duct are all except?","o":["Buccopharyngeal fascia","Buccinator muscle","Buccal fat pad","Investing layer of deep cervical fascia"],"a":3,"e":"Ans. ''d'' i.e., Investing layer of deep cervical fascia The parotid duct (Stenson''s duct) Parotid duct emerges from the anterior border of the gland and passes forward over the lateral surface of the masseter and can be palpated at the tense anterior margin of the masseter muscle. In its course duct pierces buccal fat pad, buccopharyngeal fascia and buccinator muscle (obliquely) and opens on the mucous membrane of cheek opposite to second upper molar tooth. When intraoral pressure is raised (during blowing) the duct is compressed between the buccinator and mucous membrane, preventing inflation of the duct.","pyqMatches":[{"year":"2016","no":111,"q":"Structures pierced by the parotid duct are all except?","o":["Buccopharyngeal fascia","Buccinator muscle","Buccal fat pad","Investing layer of deep cervical fascia"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (566, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 566, '{"id":566,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":566,"q":"Which layer of the scalp is vascular?","o":["Pericranium","Superficial fascia","Skin","Aponeurosis"],"a":1,"e":"Ans. is ''b'' i.e., Superficial fascia The scalp is a soft tissue that covers the calvaria of the skull. It consists of five layers and can be memorized by a mnemonic using the initial letters of the word. SCALP:? Skin Close network of connective tissue (superficial fascia) Aponeurosis (galea aponeurotica) with occipitofrontalis muscles Loose areolar (subaponeurotic) tissue Pericranium (outer periosteum of the skull)","pyqMatches":[{"year":"2016","no":112,"q":"Which layer of the scalp is vascular?","o":["Pericranium","Superficial fascia","Skin","Aponeurosis"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (567, 'Anatomy', 'Head & Neck', 'Moderate', 'Anatomy', 567, '{"id":567,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Moderate","source":"Anatomy","sourceNo":567,"q":"All of the following pass through the Sinus of morgagni except -","o":["Auditory tube","Levator veli palatini","Ascending palatine artery","Stylopharyngeus"],"a":3,"e":"Ans. ''d'' i.e., Stylopharyngeus Sinus of Morgagni is the large gap between the upper concave border of the superior constrictor and the base of the skull. The structures passing through it are:","pyqMatches":[{"year":"2016","no":113,"q":"All of the following pass through the Sinus of morgagni except","o":["Auditory tube","Levator veli palatini","Ascending palatine artery","Stylopharyngeus"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (568, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 568, '{"id":568,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":568,"q":"Chorda tympani is a branch of ?","o":["Facial nerve","Trigeminal nerve","Greater auricular nerve","External laryngeal nerve"],"a":0,"e":"Ans. is ''a'' i.e., Facial nerve [Ref: BDC 6th le Vol 3 p. 371] Branches of facial nerve","pyqMatches":[{"year":"2016","no":114,"q":"Chorda tympani is a branch of ?","o":["Facial nerve","Trigeminal nerve","Greater auricular nerve","External laryngeal nerve"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (569, 'Anatomy', 'Histology', 'Moderate', 'Anatomy', 569, '{"id":569,"subject":"Anatomy","chapter":"Histology","difficulty":"Moderate","source":"Anatomy","sourceNo":569,"q":"Chorda-tympani does not carry which fibers?","o":["Preganglionic parasympathetic fibers for sublingual glands","Preganglionic parasympathetic fibers for submandibular gland","Preganglionic parasympathetic fibers for parotid gland","Taste fibers from anterior two third of tongue"],"a":2,"e":"Ans. is ''c'' i.e., Preganglionic parasympathetic fibers for parotid gland Chorda tympani is a branch of facial nerve mainly carrying taste sensations from the anterior 2/3rd of the tongue The chorda tympani carries two types of nerve fibers from their origin with the facial nerve to the lingual nerve that carries them to their destinations: Special sensory fibers providing taste sensation from the anterior two-thirds of the tongue. Preganglionic parasympathetic fibers to the submandibular ganglion, providing secretomotor innervation to two salivary glands: the submandibular gland and sublingual gland and to the vessels of the tongue, which when stimulated, cause dilation of blood vessels of the tongue.","pyqMatches":[{"year":"2016","no":115,"q":"Chorda-tympani does not carry which fibers?","o":["Preganglionic parasympathetic fibers for sublingual glands","Preganglionic parasympathetic fibers for submandibular gland","Preganglionic parasympathetic fibers for parotid gland","Taste fibers from anterior two third of tongue"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (570, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 570, '{"id":570,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":570,"q":"Which of the following pass through the Hypoglossal canal?","o":["Hypoglossal nerve","External jugular vein","Facial nerve","Mandibular nerve"],"a":0,"e":"Ans. is ''a'' i.e., Hypoglossal nerve [Ref BDC 6th/e Vol. 3 p. 18-20]","pyqMatches":[{"year":"2016","no":116,"q":"Which of the following pass through the Hypoglossal canal?","o":["Hypoglossal nerve","External jugular vein","Facial nerve","Mandibular nerve"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (571, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 571, '{"id":571,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":571,"q":"Which muscle is antagonist to orbicularis oculi that is not supplied by facial nerve?","o":["Levator Palpebrae superioris","Orbicularis oris","Superior oblique","Inferior oblique"],"a":0,"e":"Ans. is ''a'' i.e., Levator Palpebrae superioris Orbicularis oculi closes the eye and is supplied by the facial nerve. Levator Palpebrae superioris opens the eyelid and is supplied by the oculomotor nerve.","pyqMatches":[{"year":"2016","no":117,"q":"Which muscle is antagonist to orbicularis oculi that is not supplied by facial nerve?","o":["Levator Palpebrae superioris","Orbicularis oris","Superior oblique","Inferior oblique"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (572, 'Anatomy', 'Upper Limb', 'Moderate', 'Anatomy', 572, '{"id":572,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Moderate","source":"Anatomy","sourceNo":572,"q":"All of the following are main branches of Trigeminal nerve except ?","o":["Mandibular nerve","Maxillary nerve","Ophthalmic nerve","Optic nerve"],"a":3,"e":"Ans. is ''d'' i.e., Optic nerve [Ref BDC 6th/e Vol 3 p. 369] Divisions of trigeminal nerve","pyqMatches":[{"year":"2016","no":118,"q":"All of the following are main branches of Trigeminal nerve except ?","o":["Mandibular nerve","Maxillary nerve","Ophthalmic nerve","Optic nerve"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (573, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 573, '{"id":573,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":573,"q":"Extension of the retropharyngeal space is between ?","o":["Alar fascia and buccopharyngeal fascia","buccopharyngeal fascia and prevertebral fascia","Alar fascia and Prevertebral fascia","None"],"a":0,"e":"Ans. is ''a'' i.e., Alar fascia and buccopharyngeal fascia Retropharyngeal space The retropharyngeal space is a potential space of the head and neck, bounded by the buccopharyngeal fascia anteriorly and the alar fascia posteriorly. Together with the lateral pharyngeal space, these spaces are termed the parapharyngeal spaces. It contains the retropharyngeal lymph nodes. Because serious infections of teeth can spread down this space into the posterior mediastinum, it is often confused with the danger space. The danger space is actually between the alar fascia and the prevertebral fascia and extends from the cranial base above to the level of the diaphragm. It is limited above by the base of the skull, and below where the alar fascia fuses with the buccopharyngeal fascia at about the level of T4 and the carina.","pyqMatches":[{"year":"2016","no":119,"q":"Extension of the retropharyngeal space is between ?","o":["Alar fascia and buccopharyngeal fascia","buccopharyngeal fascia and prevertebral fascia","Alar fascia and Prevertebral fascia","None"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (574, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 574, '{"id":574,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":574,"q":"Delphian nodes are ?","o":["Prelaryngeal nodes","Occipital nodes","Coeliac nodes","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Prelaryngeal nodes The Delphian node (prelaryngeal) along with paratracheal nodes, pretracheal nodes, perithyroidal nodes makeup level VI cervical lymph nodes, and is not routinely excised in radical neck dissections. It receives lymph from the thyroid and larynx. The Delphian node gains its name from the Oracle of Delphi, whose prophecy, in this case, would be of an unpleasant death secondary to laryngeal cancer. The involvement of this node can be a result of diffuse nodal involvement in head and neck squamous cell carcinoma or isolation from the direct lymphatic spread of laryngeal cancer through the anterior commissure. Thyroid carcinomas may also involve this node.","pyqMatches":[{"year":"2016","no":120,"q":"Delphian nodes are ?","o":["Prelaryngeal nodes","Occipital nodes","Coeliac nodes","None of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (575, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 575, '{"id":575,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":575,"q":"Straight sinus is formed by?","o":["Inferior Sagittal Sinus","Internal Jugular veins","Superior Sagittal Sinus","Tranverse sinus"],"a":0,"e":"Ans. is ''a'' i.e., Inferior Sagittal Sinus The straight sinus, also known as tentorial sinus or the sinus rectus, is an area within the skull beneath the brain that receives venous blood. Straight sinus is formed by the union of the inferior sagittal sinus with the great cerebral vein. It is considered a continuation of the inferior sagittal sinus. It drains into the transverse sinus, most commonly in the left one. The straight sinus is situated within the dura mater, where the falx cerebri meets the midline of tentorium cerebelli. In cross-section, it is triangular, contains a few transverse bands across its interior, and increases in size as it proceeds backward.","pyqMatches":[{"year":"2016","no":121,"q":"Straight sinus is formed by?","o":["Inferior Sagittal Sinus","Internal Jugular veins","Superior Sagittal Sinus","Tranverse sinus"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (576, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 576, '{"id":576,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":576,"q":"Which artery supplies the paracentral lobule?","o":["Medial Striate artery","Calloso Marginal artery","Pericallosal artery","Frontopolar artery"],"a":1,"e":"Ans. is ''b'' i.e., Calloso Marginal artery [Ref BDC Vol. 3 6th/e p. 461, 462] Calloso marginal artery is a branch of anterior cerebral artery that supplies the paracentral lobule which has a role in control of micturition Anterior cerebral artery Has following branches :-","pyqMatches":[{"year":"2016","no":122,"q":"Which artery supplies the paracentral lobule?","o":["Medial Striate artery","Calloso Marginal artery","Pericallosal artery","Frontopolar artery"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (577, 'Anatomy', 'Abdomen', 'Moderate', 'Anatomy', 577, '{"id":577,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Moderate","source":"Anatomy","sourceNo":577,"q":"Which of the following is not a permanent mucosal fold?","o":["Heister''s valves","Transverse rectal fold","Plicae circularis","Gastric rugae"],"a":3,"e":"Ans. is ''d'' i.e., Gastric rugae [Ref Inderbir Singh Histology p. 240; BDC 4th/e Vol. H p. 241, 245, 274, 378; Gray''s 40th le p. 1138, 1120, 1151, 1132, 1178] Gastric rugae of stomach, and longitudinal folds in mucosa of upper rectum and colon are temporary mucosal folds and are obliterated by distension. Whereas, plica circularis (valves of kerkring) of small intestine, crescentic mucosal folds of cystic duct (spiral valve of Heister), transverse (horizontal) rectal folds (Houston''s valves or plica transversalis) and permanent longitudanal rectal columns or folds (found in","pyqMatches":[{"year":"2016","no":139,"q":"Which of the following is not a permanent mucosal fold?","o":["Heister''s valves","Transverse rectal fold","Plicae circularis","Gastric rugae"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (578, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 578, '{"id":578,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":578,"q":"Most lateral nucleus of cerebellum is ?","o":["Dentate","Globose","Fastigial","Emboliform"],"a":0,"e":"Ans. is ''A'' i.e., Dentate There are four deep cerebellar nuclei (from lateral to medial) : dentate, emboliform, globose, and fastigial. The globose and the emboliform nuclei are sometimes lumped together as the interpositus nucleus.","pyqMatches":[{"year":"2016","no":124,"q":"Most lateral nucleus of cerebellum is ?","o":["Dentate","Globose","Fastigial","Emboliform"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (579, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 579, '{"id":579,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":579,"q":"Superior marginal gyrus is a part of?","o":["Parietal lobe","Frontal lobe","Temporal lobe","Occipital lobe"],"a":0,"e":"Ans. is ''a'' i.e., Parietal lobe The superior marginal gyrus is a portion of the parietal lobe. This area of the brain is also known as Brodmann area 40 based on the universally used brain map created by Korbinian Brodmann to define the structures in the cerebral cortex.","pyqMatches":[{"year":"2016","no":125,"q":"Superior marginal gyrus is a part of?","o":["Parietal lobe","Frontal lobe","Temporal lobe","Occipital lobe"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (580, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 580, '{"id":580,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":580,"q":"Spinal segmental artery is a branch of ?","o":["Ascending spinal artery","Basilar artery","Posterior spinal artery","Anterior spinal artery"],"a":0,"e":"Ans. is ''a'' i.e.,Ascending spinal artery [Ref Spinal Cord Medicine. Demos Medical Publishing.] Arterial supply of spinal cord","pyqMatches":[{"year":"2016","no":138,"q":"Spinal segmental artery is a branch of ?","o":["Ascending spinal artery","Basilar artery","Posterior spinal artery","Anterior spinal artery"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (581, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 581, '{"id":581,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":581,"q":"Pars dorsalis is a part of ?","o":["Cerebrum","Cerebellum","Pons","Thalamus"],"a":2,"e":"Ans. is ''c'' i.e., Pons [Ref Farlex Partner Medical Dictionary Farlex 2012] Pars Dorsalis The part of the pons bounded laterally by the middle cerebellar peduncles and anteriorly by the ventral part of pons; it is continuous with the tegmentum of the mesencephalon and contains long tracts such as the medialand lateral lemnisci, cranial nerve nuclei, and reticular formatin.","pyqMatches":[{"year":"2016","no":126,"q":"Pars dorsalis is a part of ?","o":["Cerebrum","Cerebellum","Pons","Thalamus"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (582, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 582, '{"id":582,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":582,"q":"Movement occuring at atlanto-axial joint?","o":["Flexion","Bending","Rotation","Nodding"],"a":2,"e":"Ans. is ''c'' i.e.,Rotation [Ref: Clinical anatomy 3rdie p. 786] Movments permitted at atlanto-occipital joint are : - Flexion and extension (nodding of head), and (ii) Lateral flexion (bending of neck). Movements permitted at atlanto-axial joints are side-to-side rotation of head (looking towards right-or-left).","pyqMatches":[{"year":"2016","no":137,"q":"Movement occuring at atlanto-axial joint?","o":["Flexion","Bending","Rotation","Nodding"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (583, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 583, '{"id":583,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":583,"q":"Arbor vitae are seen in ?","o":["Cerebrum","Cerebellum","Pons","Thalamus"],"a":1,"e":"Ans. is ''b'' i.e.,Cerebellum The arborvitae is the cerebellar white matter, so-called for its branched, tree-like appearance. In some ways, it more resembles a fern and is present in both the cerebellar hemispheres. It brings sensory and motor information to and from the cerebellum. The arborvitae is located deep in the cerebellum. Situated within the arborvitae are the deep cerebellar nuclei; the dentate, globose, emboliform and the fastigial nuclei. These four different structures lead to the efferent projections of the cerebellum.","pyqMatches":[{"year":"2016","no":127,"q":"Arbor vitae are seen in ?","o":["Cerebrum","Cerebellum","Pons","Thalamus"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (584, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 584, '{"id":584,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":584,"q":"Long spinous process is seen in ?","o":["Cervical vertebrae","Thoracic Vertebrae","Lumbar Vertebrae","Sacrum"],"a":1,"e":"Ans. is ''b'' i.e., Thoracic Vertebrae [Ref: BDC 5th/e Vol. 3 p. 40]","pyqMatches":[{"year":"2016","no":136,"q":"Long spinous process is seen in ?","o":["Cervical vertebrae","Thoracic Vertebrae","Lumbar Vertebrae","Sacrum"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (585, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 585, '{"id":585,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":585,"q":"Total volume of CSF is?","o":["150 ml","500 ml","50 ml","800 ml"],"a":0,"e":"Ans. is ''a'' i.e., 150ml The major source of CSF is the choroidal plexus of all 4 ventricles, mainly in two lateral ventricles. Other sources of CSF are ependymal cells of the ventricles and the brain itself, via perivascular spaces. The total volume of CSF in an adult is about 125-150 ml. The rate of formation of CSF is about 500-550 ml/day. Thus the CSF is replaced 3-4 times every day. The watery part of CSF is secreted by transduction but each of its constitutions is actively transported. Na. is secreted into the CSF with the help of Na+ ATPase. Glucose enters CSF through facilitated diffusion mediated by GLUT-1. HCO3 is secreted with the help of carbonic anhydrase.","pyqMatches":[{"year":"2016","no":128,"q":"Total volume of CSF is?","o":["150 ml","500 ml","50 ml","800 ml"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (586, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 586, '{"id":586,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":586,"q":"Lateral lemniscus terminates into ?","o":["Lateral geniculate body","Superior colliculus","Inferior colliculus","Inferior olivary complex"],"a":2,"e":"Ans is ''c'' i.e., Inferior colliculus [Ref BDC 6th /e Vol. .3 p. 374]","pyqMatches":[{"year":"2016","no":129,"q":"Lateral lemniscus terminates into ?","o":["Lateral geniculate body","Superior colliculus","Inferior colliculus","Inferior olivary complex"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (587, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 587, '{"id":587,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":587,"q":"Cerebellovestibular fibres pass through ?","o":["Superior cerebellar peduncle","Middle cerebellar peduncle","Inferior cerebellar peduncle","None"],"a":2,"e":"Ans. is ''c'' i.e.,Inferior cerebellar peduncle [Ref BDC Vol. III 6th le p. 405] Inferior cerebellar peduncle →","pyqMatches":[{"year":"2016","no":135,"q":"Cerebellovestibular fibres pass through ?","o":["Superior cerebellar peduncle","Middle cerebellar peduncle","Inferior cerebellar peduncle","None"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (588, 'Anatomy', 'Miscellaneous', 'Moderate', 'Anatomy', 588, '{"id":588,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anatomy","sourceNo":588,"q":"Internal capsule- All of the following are parts except ?","o":["Anterior limb","Sublentiform part","Retrolentiform","Prelentiform"],"a":3,"e":"Ans. is ''d'' i.e., Prelentiform The internal capsule is divided from before backwards into following parts: Anterior limb Posterior limb Retrolentiform part Genu Sublentiform part","pyqMatches":[{"year":"2016","no":130,"q":"Internal capsule- All of the following are parts except ?","o":["Anterior limb","Sublentiform part","Retrolentiform","Prelentiform"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (589, 'Anatomy', 'Neuroanatomy', 'Moderate', 'Anatomy', 589, '{"id":589,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":589,"q":"Which of the following is derived from the neural tube except?","o":["Retina","Brain","Dorsal root ganglia","Pineal gland"],"a":2,"e":"Ans. is ''c'' i.e.,Dorsal root ganglia [Ref Textbook of human embryology -786] Nervous system develops from ectoderm (neuroectoderm). Nervous system develops from neural tube which in turn devtlops by process of neurulation, i.e. formation of neural plate and its infolding into neural tube.","pyqMatches":[{"year":"2016","no":134,"q":"Which of the following is derived from the neural tube except?","o":["Retina","Brain","Dorsal root ganglia","Pineal gland"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (590, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 590, '{"id":590,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":590,"q":"Which of the following is a complete sulcus in the brain?","o":["Calcarine sulcus","Paracentral sulcus","Both","None"],"a":0,"e":"Ans. is ''a'' i.e., Calcarine sulcus The calcarine sulcus (or calcarine fissure) is an anatomical landmark located at the caudal end of the medial surface of the brain of humans and other primates. Its name comes from the Latin \"calcar\" meaning \"spur\". It is a complete sulcus. For accommodation in a limited space within the rigid cranial box, the cerebral cortex is folded into numerous gyri or convolutions separated by sulci or fissures. Eventually the total surface area of the cortex of human brain is increased to about 2200 cm2, in which only about one third of the cortex is exposed as gyri and two third is hidden in the sulci.","pyqMatches":[{"year":"2016","no":133,"q":"Which of the following is a complete sulcus in the brain?","o":["Calcarine sulcus","Paracentral sulcus","Both","None"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (591, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 591, '{"id":591,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":591,"q":"Substantia ferruginea is found in -","o":["Fourth ventricle","Thalamus","Midbrain","Third ventricle"],"a":0,"e":"Ans. is ''a'' i.e.,Fourth ventricle [Ref Medical Dictionary, 2009 Farlex and Partners] It is a shallow depression, of a blue color in the fresh brain, lying laterally in the most rostral portion of the rhomboidal fossa near the cerebral aqueduct; it lies near the lateral wall of the fourth ventricle and consists of about 20,000 melanin- pigmented neuronal cell bodies the norepinephrine-containing axons of which have a remarkably wide distribution in the cerebellum as well as in the hypothalamus and cerebral cortex. Also called as locus cinereus, locus ferrugineus.","pyqMatches":[{"year":"2016","no":131,"q":"Substantia ferruginea is found in","o":["Fourth ventricle","Thalamus","Midbrain","Third ventricle"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (592, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 592, '{"id":592,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":592,"q":"Infundibular diverticulum is an extention of ?","o":["1st and 2th ventricles","3rd ventricle","4th ventricle","None"],"a":1,"e":"Ans. is ''B'' i.e., 3rd ventricle Third ventricle is a midline cavity of diencephalon. It is a median cleft between two thalami. Anterosuperiorly it communicates with lateral ventricle through the interventricular foramen (foramen of Monro). Posteroinferiorly it communicates with fourth ventricle through cerebral aqueduct (Duct of Sylvius). There are four extensions (recesses) of third ventricle : (a) Suprapineal recess, (b) Pineal recess, (c) Infundibular recess, and (d) Optic recess.","pyqMatches":[{"year":"2016","no":132,"q":"Infundibular diverticulum is an extention of ?","o":["1st and 2th ventricles","3rd ventricle","4th ventricle","None"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (593, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 593, '{"id":593,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":593,"q":"Osseocartilagenous junction is present at ?","o":["Nasion","Rhinion","Radix","Columella"],"a":1,"e":"Ans. is ''b'' i.e., Rhinion [Ref Textbook of general anatomy p. 10] Nasion → The depression at the junction of nose with forehead. Rhinion → The point located at the osseocartilagenous junction over the dorsum of the nose. Radix → Junction between the frontal bone and nasal bone. Columella → Column between the nostrils at the base of the nose..","pyqMatches":[{"year":"2012","no":129,"q":"Osseocartilagenous junction is present at ?","o":["Nasion","Rhinion","Radix","Columella"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (594, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 594, '{"id":594,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":594,"q":"At what level does the trachea bifurcates ?","o":["Upper border of T4","Lower border of T4","27.5 cm from the incisors","Lower border of T5"],"a":1,"e":"Ans. is ''b'' i.e., Lower border of T4 [Ref BDC Sth/e Volume 1 p. 267] Trachea bifurcates at carina, at the level of lower border of T, or T4 - T5 disc space.","pyqMatches":[{"year":"2012","no":2,"q":"At what level does the trachea bifurcates ?","o":["Upper border of T4","Lower border of T4","27.5 cm from the incisors","Lower border of T5"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (595, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 595, '{"id":595,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":595,"q":"Cricoid cartilage lies at which vertebral level ?","o":["C3","C6","T1","T4"],"a":1,"e":"Ans. is ''b'' i.e., C6 [Ref BDC 5I''Ve Vol. III, p. 237]","pyqMatches":[{"year":"2012","no":3,"q":"Cricoid cartilage lies at which vertebral level ?","o":["C3","C6","T1","T4"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (596, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 596, '{"id":596,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":596,"q":"Which of the following is true about vertebral development -","o":["The notochord forms the annulus fibrosus","The sclerotome forms the nucleus pulposus","The sclerotome surrounds the notochord only","The sclerotome surrounds the notochord and the neural tube"],"a":3,"e":"Ans. is ''d'' i.e., The sclerotome surrounds the notochord and the neural tube [Ref Langman''s embryology 10th/e p. 140] Development of vertebral column The human nervous system develops from neuroectoderm. During development, behind the neuroectoderm lies the mesoderm (paraxial mesoderm) that encloses the notochord (a derivative of endoderm). This paraxial mesoderm give rise to somites. Somites further differentrated into : Dermatomyotome :- Give rise to skeletal muscles and dermis. Sclerotomes :- Give rise to vertebral column. Sclerotornes which surround notochord starts projecting posteriorly (dorsally) to surround neural tube and forms. Ventral sclerotomes :- Give rise to vertebral body and annulus fibrosus, Lateral sclerotomes :- Give rise to vertebral arch (pedicle and lamina). Dorsal sclerotomes :- Give rise to spinous process. The notochord forms the nucleus pulposus.","pyqMatches":[{"year":"2012","no":4,"q":"Which of the following is true about vertebral development","o":["The notochord forms the annulus fibrosus","The sclerotome forms the nucleus pulposus","The sclerotome surrounds the notochord only","The sclerotome surrounds the notochord and the neural tube"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (597, 'Anatomy', 'Embryology', 'Moderate', 'Anatomy', 597, '{"id":597,"subject":"Anatomy","chapter":"Embryology","difficulty":"Moderate","source":"Anatomy","sourceNo":597,"q":"Which of the following is not a congenital anomaly?","o":["Amastia","Polymastia","Polythelia","Mastitis"],"a":3,"e":"Ans. is ''d'' i.e., Mastitis [Ref Human embryology by Inderbir Singh 8th/e p. 103] Developmental anomalies of the mammary glands :","pyqMatches":[{"year":"2012","no":5,"q":"Which of the following is not a congenital anomaly?","o":["Amastia","Polymastia","Polythelia","Mastitis"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (598, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 598, '{"id":598,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":598,"q":"Rectum develops from","o":["Cloaca","Hind gut","Allantoic remnants","Urogeital sinus"],"a":0,"e":":B Ans. is `b > a'' i.e., Hind gut > Cloaca [Ref : Inderbir Singh human embryology Sth/e p. 149] Postallantoic part of hind gut is the dilated endodermal cloaca, which is separated from the surface by cloacal membrane. Urorectal septum divides endodermal cloacae into Anterior part, known as primitive urogenital sinus, which develops into urinary bladder and urethra. Posterior part, known as primitive rectum, which gives rise to lower part of rectum and upper part of anal canal.","pyqMatches":[{"year":"2012","no":6,"q":"Rectum develops from","o":["Cloaca","Hind gut","Allantoic remnants","Urogeital sinus"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (599, 'Anatomy', 'Neuroanatomy', 'Moderate', 'Anatomy', 599, '{"id":599,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":599,"q":"All are derived from ectoderm except -","o":["Hypophysis","Retina","Spinal cord","Adrenal cortex"],"a":3,"e":"Ans. is ''d'' i.e., Adrenal cortex [Ref Inderbir Singh Human Embryology Sth/e p. 300] The cells of the adrenal cortex arise from the coelomic epithelium (mesoderm). The cells of the medulla are derived from the neural crest cells (ectoderm). The anterior pituitary is derived from the surface ectoderm lining the oral cavity as it is an outgrowth from the Rathke''s pouch. The posterior pituitary is actually a continuation of the hypothalamus and so it is derived from the neural ectoderm.· The spinal cord and brain are derived from the neural ectoderm. The retina is also derived from the neural ectoderm.","pyqMatches":[{"year":"2012","no":8,"q":"All are derived from ectoderm except","o":["Hypophysis","Retina","Spinal cord","Adrenal cortex"],"a":3,"source":"NEET_2012_Paper.pdf"},{"year":"2012","no":13,"q":"All are derived from ectoderm except ?","o":["Lens","Eustachian tube","Brain","Retina"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (600, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 600, '{"id":600,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":600,"q":"Development of labia majora is from -","o":["Urogenital sinus","Mullerian duct","Genital ridge","Genital swelling"],"a":3,"e":"Ans. is ''d'' i.e., Genital swelling [Ref: Inderbir Singh Human Embryology Sth/e p. 256] Embryogical structure Fate in female Fate in male Genital swelling Labia majora Scrotum Genital fold Labia minora Ventral aspect of penis, penile urethra Genital tubercle Clitoris Glans penis","pyqMatches":[{"year":"2012","no":9,"q":"Development of labia majora is from","o":["Urogenital sinus","Mullerian duct","Genital ridge","Genital swelling"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (601, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 601, '{"id":601,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":601,"q":"Blastocyst makes contact with endometrium on ?","o":["< 3 days","5 - 7 days","8 - 11 days","15 -16 days"],"a":1,"e":"Ans. is ''b'' i.e., 5 -7 days [Ref: Text book of Human embryology - 286] Contact of blastocyst with endometrium occurs at the time of implantation. Implantation occurs at around 6 -7 days.","pyqMatches":[{"year":"2012","no":10,"q":"Blastocyst makes contact with endometrium on ?","o":["< 3 days","5 - 7 days","8 - 11 days","15 -16 days"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (602, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 602, '{"id":602,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":602,"q":"Haploid number of chromosomes is seen in ?","o":["Spermatogonia","Primary spermatocytes","Secondary spermatocyte","None"],"a":2,"e":"Ans. is ''c'' i.e., Secondary spermatocyte [Ref Ganong 23''d% p. 403, 404] Diploid means that cell contains 46 chromosomes (diploid of 23) and haploid means that cell contains 23 chromosomes. Development of sperm is as follows : - Spermatogonia(Diploid-46) → Primary spermatocyte (Diploid-46) Primary spermatocyte (Diploid-46) is of 2 types-","pyqMatches":[{"year":"2012","no":11,"q":"Haploid number of chromosomes is seen in ?","o":["Spermatogonia","Primary spermatocytes","Secondary spermatocyte","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (603, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 603, '{"id":603,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":603,"q":"Sperm chromosome faster is -","o":["X chromosome","Y chromosome","Both same","None"],"a":1,"e":"Ans. is ''b'' i.e., Y chromosome [Ref Priciple of medical physiology - 51] The human Y chromosome is smaller than X chromosome. Hence, the sperms containing Y chromosomes are lighter and swim faster up the female genital tract, reaching the ovum earlier than the Y bearing sperms. This probably contributes to the fact that the global male birth rate is slightly higher then the female birth rate.","pyqMatches":[{"year":"2012","no":12,"q":"Sperm chromosome faster is","o":["X chromosome","Y chromosome","Both same","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (604, 'Anatomy', 'Histology', 'Moderate', 'Anatomy', 604, '{"id":604,"subject":"Anatomy","chapter":"Histology","difficulty":"Moderate","source":"Anatomy","sourceNo":604,"q":"All are derived from ectoderm except ?","o":["Lens","Eustachian tube","Brain","Retina"],"a":1,"e":"Ans. is ''b'' i.e., Eustachian tube [Ref HUMAN EMBR YOLOGY edited by Krishna Garg, 2\"dle p. 56, 133] Eustachian tube originates from the first pharyngeal pouch i.e. Endoderm. Endoderm Ectoderm Mesoderm Epithelium of whole g.i.t. Resp.tract (Eustachian tube) Pharyngeal pouches Liver & GB Urethra UB Lower part of vagins Ducts & acimi of pancreas Most endocrinal glands (except adr. medulla & Brain Neural Crest Adrenal Medulla Pharyngeal clefts Oligodendrocytes Lens (from surface E-) Iris muscles (Sphincter & dilator pupillae) Epithelium of cornea, conjunctiva outer Lids Renal pigment epithelium Sensory retina Membranous Labyrinth LN & Spleen Mesenchyme Mesothelium Pharyngeal aches CVS, blood, BM Duramater Trigone of UB Monocyte dery (Ex- Microglia) Cillary body & iris stroma (except epithelium) Sclera, choroid, vitreous Stroma of cornea Lids (Muscles) Adrenal Cortex Bony orbit pituitary which are ectoderm) y","pyqMatches":[{"year":"2012","no":8,"q":"All are derived from ectoderm except","o":["Hypophysis","Retina","Spinal cord","Adrenal cortex"],"a":3,"source":"NEET_2012_Paper.pdf"},{"year":"2012","no":13,"q":"All are derived from ectoderm except ?","o":["Lens","Eustachian tube","Brain","Retina"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (605, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 605, '{"id":605,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":605,"q":"Which of the following is derived from endoderm?","o":["Gall bladder","Lens","Spleen","Lymph nodes"],"a":0,"e":"Ans. is ''a'' i.e., Gall bladder [Ref Embryology Garg 2\"/e various pages]","pyqMatches":[{"year":"2012","no":14,"q":"Which of the following is derived from endoderm?","o":["Gall bladder","Lens","Spleen","Lymph nodes"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (606, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 606, '{"id":606,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":606,"q":"Development of peritoneal cavity is from ?","o":["Mesenchyme","Intraembryonic coelom","Ectoderm","Endoderm"],"a":1,"e":"Ans. is ''b'' i.e., Intraembyonic coelom [Ref Embryology by Indu Khuran 2\"dle p. 96] All body cavities develop from intraembryonic coelum. These cavities are peritoneal cavity, pleural cavity and pericardial cavity. The peritoneum develops ultimately from the mesoderm of the trilaminar embryo. Lateral plate mesoderm splits to form two layers separated by an intraembryonic coelom. These two layers develop later into the visceral and parietal layers found in all serous cavities including peritoneum. And the potential space of intraembryonic coelom between these two layers become the body cavities like peritoneal cavity, pleural cavity and pericardial cavity. As embryo develops, the various abdominal organs grow into the abdominal cavity from structures in the abdominal wall. In this process they become enveloped in a layer of peritoneum, i.e. visceral layer. Peritoneal folds develop from the ventral and dorsal mesentery of the embryo. Peritoneum, pericardium and pleura develop from -, Mesoderm (lateral plate mesoderm) Peritoneal cavity, pericardial cavity and pleural cavity develop from Intraembryonic coelom.","pyqMatches":[{"year":"2012","no":15,"q":"Development of peritoneal cavity is from ?","o":["Mesenchyme","Intraembryonic coelom","Ectoderm","Endoderm"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (607, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 607, '{"id":607,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":607,"q":"Cytotrophoblasts invades ?","o":["D parietalis","D basal is","D capularis","None"],"a":1,"e":"Ans. is ''b'' i.e., D basalis [Ref Human Embryology by Rani Kumar p. 37] After embedding of blastocyt in the endometrial stroma, the trophoblast differentiates into - Cytotrophoblast Syncytiotrophoblast Syncytiotrophoblast invades uterine epithelial cells. Cytotrophoblast invades Decidua basalis (D basalis) after passing through overlying syncytotrophoblast.","pyqMatches":[{"year":"2012","no":16,"q":"Cytotrophoblasts invades ?","o":["D parietalis","D basal is","D capularis","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (608, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 608, '{"id":608,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":608,"q":"Coronary sinus develops from ?","o":["Truncus arteriosus","Conus","Sinus venosus","AV canal"],"a":2,"e":"Ans. is ''c'' i.e., Sinus venosus [Ref Essentials of human embryology p. 873] The Coronary sinus develops from the Sinus venosus segment of embryonic heart. Left horn of sinus venosus retrogresses to form part of coronary sinus","pyqMatches":[{"year":"2012","no":17,"q":"Coronary sinus develops from ?","o":["Truncus arteriosus","Conus","Sinus venosus","AV canal"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (609, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 609, '{"id":609,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":609,"q":"Which is derived from wolfian duct ?","o":["Appendix of testis","Uterus","Appendix of epididymis","Hydatid of margagni"],"a":2,"e":"Ans. is ''c'' i.e.,Appendix of epididymis [Ref IB singh 8r\"/e - 260] Appendix of epididymis develops from mesonephric (wolffian) duct. Appendix of testis (also called hydatid of margagni) and uterus develop from paramesonephric duct.","pyqMatches":[{"year":"2012","no":18,"q":"Which is derived from wolfian duct ?","o":["Appendix of testis","Uterus","Appendix of epididymis","Hydatid of margagni"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (610, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 610, '{"id":610,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":610,"q":"Artery of 2nd pharyngeal arch is ?","o":["Maxillary artery","Stapedial artery","Subclavian artery","Common carotid artery"],"a":1,"e":"Ans. is ''b'' i.e.,Stapedial artery [Ref Garg 2\"/e - 223; Langman''s - 185] 2nd (hyoid arch) : Stapedial artery 3rd:- Common carotid/internal carotid 4th:- : Right 4th aortic arch, subclavian artery, Left 4th aortic arch: aortic arch 6th:- Right aortic arch: pulmonary artery, Left 6th aortic arch: Pulmonary artstxand ductus arteriosus","pyqMatches":[{"year":"2012","no":19,"q":"Artery of 2nd pharyngeal arch is ?","o":["Maxillary artery","Stapedial artery","Subclavian artery","Common carotid artery"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (611, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 611, '{"id":611,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":611,"q":"Fossa ovalis is a remnant of ?","o":["Septum primum","Septum secundum","Ductus arteriosus","Ductus venosus"],"a":0,"e":"Ans. is ''a'' i.e., Septum primum [Ref BDC 5th/e Volume 1 p. 247; IBS 7\"Ve p. 265; Garg 2\"/e p. 215] Fossa ovalis is a remnant of foramen ovale. Floor of fossa ovalis is remnant of septum primum.","pyqMatches":[{"year":"2012","no":20,"q":"Fossa ovalis is a remnant of ?","o":["Septum primum","Septum secundum","Ductus arteriosus","Ductus venosus"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2015","no":132,"q":"Fossa ovalis is a remnant of","o":["Septum primum","Septum secundum","Septum spurium","AV cushion"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2012","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (612, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 612, '{"id":612,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":612,"q":"Y chromosome is ?","o":["Metacentric","Submetacentric","Acrocentric","None"],"a":2,"e":"Ans. is ''c'' i.e.,Acrocentric Each chromosome has two arms :-","pyqMatches":[{"year":"2012","no":21,"q":"Y chromosome is ?","o":["Metacentric","Submetacentric","Acrocentric","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (613, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 613, '{"id":613,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":613,"q":"The outer layer of the blastocyst forms ?","o":["Primitive streak","Yolk sac","Embryo proper","Trophoblast"],"a":3,"e":"Ans. is ''d'' i.e.,Trophoblast [Ref Singh IB, Human embryology Stile p. 38] Blastocyst possesses an inner cell mass called embryoblast which subsequently forms the embryo proper, and an outer layer of cells, or trophoblast, which helps to provide nutrition to the embryo.","pyqMatches":[{"year":"2012","no":22,"q":"The outer layer of the blastocyst forms ?","o":["Primitive streak","Yolk sac","Embryo proper","Trophoblast"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (614, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 614, '{"id":614,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":614,"q":"Inferior parathyroid develops from which arch ?","o":["1st","2nd","3rd","4th"],"a":2,"e":"Ans. is ''c'' i.e., 3rd [Ref Langman''s 11th/e p. 269]","pyqMatches":[{"year":"2012","no":23,"q":"Inferior parathyroid develops from which arch ?","o":["1st","2nd","3rd","4th"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (615, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 615, '{"id":615,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":615,"q":"Mesodermal in origin ?","o":["Astrocytes","Oligodendrocytes","Ependymal cells","Microglial cells"],"a":3,"e":"Ans. is ''d'' i.e., Microglial cells [Ref I.B. singh p. 319-321] Microglial cells are the nervous system counterpart of the monocyte macrophage system. The unique feature about microglia is that unlike other neuroglial cells it is not developed from neuroectoderm. These cells are mesodermal in origin.","pyqMatches":[{"year":"2012","no":24,"q":"Mesodermal in origin ?","o":["Astrocytes","Oligodendrocytes","Ependymal cells","Microglial cells"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (616, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 616, '{"id":616,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":616,"q":"Fossa ovalis closes because of fusion of ?","o":["Septum primum + Endocardial cushion","Septum secundum + Endocardial cushion","Septum primum + Septum secundum","None"],"a":2,"e":"Ans. is ''c'' i.e., Septum primum + Septum secundum [Ref Essentials of human embryology — 213-215] After birth, the foramen ovale closes by fusion of septum primum with septum secundum.","pyqMatches":[{"year":"2012","no":25,"q":"Fossa ovalis closes because of fusion of ?","o":["Septum primum + Endocardial cushion","Septum secundum + Endocardial cushion","Septum primum + Septum secundum","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (617, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 617, '{"id":617,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":617,"q":"Which of the following is a traction epiphysis ?","o":["Tibial condyles","Trochanter of femur","Coracoid process of scapula","Head of femur"],"a":1,"e":"Ans. is ''b'' i.e., Trochanter of femur [Ref BDC handbook of general anatomy 3r4/e p. 34]","pyqMatches":[{"year":"2012","no":26,"q":"Which of the following is a traction epiphysis ?","o":["Tibial condyles","Trochanter of femur","Coracoid process of scapula","Head of femur"],"a":1,"source":"NEET_2012_Paper.pdf"},{"year":"2016","no":17,"q":"Which of the following is a traction epiphysis?","o":["Distal Radius","Mastoid process","Tibial Condyles","Coracoid Process"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2012","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (618, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 618, '{"id":618,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":618,"q":"Corpora arenacea is seen in ?","o":["Prostrate","Pineal","Seminal vesicle","Breast"],"a":1,"e":"Ans. is ''b'' i.e., Pineal [Ref Textbook of human histology-323] Corpora arenacea (or brain sand) are calcified structures in Pineal gland and other areas of brain such as choroid plexus.","pyqMatches":[{"year":"2012","no":29,"q":"Corpora arenacea is seen in ?","o":["Prostrate","Pineal","Seminal vesicle","Breast"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (619, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 619, '{"id":619,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":619,"q":"Nutrient artery runs ?","o":["Towards metaphysis","Away from metaphysis","Away from epiphysis","None"],"a":0,"e":"Ans. is ''a'' i.e., Towards metaphysis [Ref Textbook of general anatomy p. 80] Nutrient artery It enters the middle of the shaft through a nutrient foramen, runs obliquely through the cortex, and then divides into ascending and desending branches that run towards metaphysis. Each branch subdivides into a number of smaller parallel vessels which enter the metaphysis and form hair-pin loops. The loops anostomose with epiphyseal,metaphyseal and periosteal arteries. Therefore, metaphysis is the most vascular zone of the long bone. The nutrient artery supplies the medullary cavity and inner-two third of cortical bone of diaphysis and metaphysis","pyqMatches":[{"year":"2012","no":30,"q":"Nutrient artery runs ?","o":["Towards metaphysis","Away from metaphysis","Away from epiphysis","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (620, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 620, '{"id":620,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":620,"q":"Multi-unit smooth muscle present at all except ?","o":["Blood vessels","Iris","Gut","Ductus deferens"],"a":2,"e":"Ans. is ''c'' i.e., Gut [Ref BDC genral anatomy 4\"/e p. 96; Fundamental of humen anatomy p. 6]","pyqMatches":[{"year":"2012","no":31,"q":"Multi-unit smooth muscle present at all except ?","o":["Blood vessels","Iris","Gut","Ductus deferens"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (621, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 621, '{"id":621,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":621,"q":"Renal papilla opens into -","o":["Cortex","Pyramid","Minor calyx","Major calyx"],"a":2,"e":"Ans. is ''c'' i.e., Minor calyx Each kidney has two distinct zones :","pyqMatches":[{"year":"2012","no":33,"q":"Renal papilla opens into","o":["Cortex","Pyramid","Minor calyx","Major calyx"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (622, 'Anatomy', 'Upper Limb', 'Hard', 'Anatomy', 622, '{"id":622,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Hard","source":"Anatomy","sourceNo":622,"q":"Following a deep cut overlying the hypothenar eminence, it is observed that the patient cannot hold a sheet of paper between the 2nd and 3rd digits. Which of the following nerves is most likely damaged?","o":["Deep branch of ulnar nerve","Deep branch of the radial nerve","Superficial branch of ulnar nerve","Median nerve"],"a":0,"e":"Ans. is ''a'' i.e., Deep branch of ulnar nerve [Ref BDC 5th le Volume I p. 110-111] Inability to hold paper sheet signifies inability to adduct the fingers. It is nothing else but card test. Deep branch of ulnar nerve supplies the palmar interossei which control the adduction between fingers.","pyqMatches":[{"year":"2012","no":36,"q":"Following a deep cut overlying the hypothenar eminence, it is observed that the patient cannot hold a sheet of paper between the 2nd and 3rd digits. Which of the following nerves is most likely damaged?","o":["Deep branch of ulnar nerve","Deep branch of the radial nerve","Superficial branch of ulnar nerve","Median nerve"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (623, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 623, '{"id":623,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":623,"q":"During heel touch phase of walking pressure in calf compartment is ?","o":["More than resting pressure","Less than resting pressure","No change in pressure","First rises and then falls"],"a":2,"e":"Ans. is ''c'' i.e., No change in pressure In heel strike, the ankle is dorsiflexed and the main muscle acting on ankle is tibialis anterior. Muscles of posterior compartment of leg (Gastrocnemius-soleus) are at their normal length. So, the pressure in posterior compartment does not change. On the other hand, In push off phase Gastrocnemius-soleus are contracted which results in increased pressure of posterior compartment (whenever there is contraction of muscles of a compartment, pressure of that compartment is increased).","pyqMatches":[{"year":"2012","no":40,"q":"During heel touch phase of walking pressure in calf compartment is ?","o":["More than resting pressure","Less than resting pressure","No change in pressure","First rises and then falls"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (624, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 624, '{"id":624,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":624,"q":"The nutrient artery to the femur is?","o":["Profunda femoris artery","Femoral artery","Popliteal artery","Middle circumflex femoral artery"],"a":0,"e":"Ans. is ''a'' i.e., Profunda femoris artery Nutrient Arteries The femur is supplied by 2nd perforating branch of profunda femoris artery. Tibia is supplied by a branch of posterior tibial The fibula is supplied by the peroneal artery which is a branch of posterior tibial artery. The humerus is supplied by a branch of profunda brachii artery Radius/ulna are supplied by the anterior interosseous artery which is a branch of the ulnar artery.","pyqMatches":[{"year":"2012","no":41,"q":"The nutrient artery to the femur is?","o":["Profunda femoris artery","Femoral artery","Popliteal artery","Middle circumflex femoral artery"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (625, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 625, '{"id":625,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":625,"q":"Site of injection in gluteus ?","o":["Inferomedial","Superomedial","Superolateral","Superomedial"],"a":2,"e":"Ans. is ''c'' i.e., Superolateral level Part of axilla Lymph nodes I Upper arm (Deltoid) 5 cm distal to the acromion or 4 cm proximal to the insertion of deltoid. This is to prevent injury to circumflex humeral nerve. II Gluteal region Upper outer (superolateral) quadrant. This is to avoid damage to superior and inferior gluteal vessels and sciatic nerve. III Thigh (lateral aspect) (vastus lateralis) Infant :- Upper lateral quadrant of thigh below GT Adult :- Middle third of lateral aspect.","pyqMatches":[{"year":"2012","no":43,"q":"Site of injection in gluteus ?","o":["Inferomedial","Superomedial","Superolateral","Superomedial"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (626, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 626, '{"id":626,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":626,"q":"Waldeyer''s fascia lies ?","o":["In front of the bladder","Behind the rectum","Between bladder and uterus","Between uterus and rectum"],"a":1,"e":"Ans. is ''B'' i.e., Behind the rectum * The cave of Retzius is a fat-filled retropubic space that allows for the accommodation of a distended bladder. * The Waldeyer''s fascia, also known as the presacral fascia, accommodates the distended rectum. * The pouch of Douglas is a fold of peritoneum between the uterus and the rectum. * The pouch of Dunn is a fold of peritoneum between the bladder and the uterus. * The fascia of Denonvillier lies between the bladder in front and rectum behind.","pyqMatches":[{"year":"2012","no":54,"q":"Waldeyer''s fascia lies ?","o":["In front of the bladder","Behind the rectum","Between bladder and uterus","Between uterus and rectum"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (627, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 627, '{"id":627,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":627,"q":"The transverse sinus is present posterior to which structures?","o":["Right atrium","Left atrium","Upper pulmonary artery","Aorta"],"a":3,"e":"Ans. ''D'' i.e., Aorta Pericardial sinuses * On the posterior surface of the heart, the reflection of the serous pericardium (epicardium) around large veins forms a recess called the oblique sinus. * Oblique sinus is bounded anteriorly by the left atrium, and posteriorly by the parietal pericardium and esophagus. * The transverse sinus is a short passage that lies between the reflection of the serous pericardium (epicardium) around arterial (aorta and pulmonary trunk) and venous ends of the heart tube. * The transverse sinus is bounded anteriorly by ascending aorta and pulmonary trunk, posteriorly by SVC, and inferiorly by the left atrium","pyqMatches":[],"pyqYears":[]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (628, 'Anatomy', 'Thorax', 'Moderate', 'Anatomy', 628, '{"id":628,"subject":"Anatomy","chapter":"Thorax","difficulty":"Moderate","source":"Anatomy","sourceNo":628,"q":"Surface marking of the oblique fissure of the lung include all except","o":["T3","5th rib","7th rib","6th costal cartilage"],"a":2,"e":"Ans. is ''c'' i.e., 7th rib Surface marking of fissures The oblique fissure can be drawn by joining: A point 8 cm lateral to 3rd thoracic vertebrae. Another point on the 5th rib in the midaxillary line. A third point on the 6th costal cartilage 7.5 cm from the median plane.","pyqMatches":[{"year":"2012","no":60,"q":"Surface marking of the oblique fissure of the lung include all except","o":["T3","5th rib","7th rib","6th costal cartilage"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (629, 'Anatomy', 'Abdomen', 'Moderate', 'Anatomy', 629, '{"id":629,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Moderate","source":"Anatomy","sourceNo":629,"q":"Anterior relations of the right kidney are all except?","o":["Liver","4th part of duodenum","Hepatic flexure","Adrenal gland"],"a":1,"e":"Ans. is ''b'' i.e., 4th part of the duodenum The posterior surface of both kidneys is related to the diaphragm, medial and lateral arcuate ligament, psoas major, quadratus lumborum, transversus abdominis, subcostal vessels, subcostal nerve, iliohypogastric nerve, and ilioinguinal nerve. In addition, the right kidney is related to the 12th rib and the left kidney is related to 11th and 12th ribs. The medial border of each kidney is related to the suprarenal gland above the hilus and ureter below the hilus. The lateral border of the right kidney is related to the right lobe of the liver and hepatic flexure of the colon. On the left side, it is related to spleen and descending colon.","pyqMatches":[{"year":"2012","no":69,"q":"Anterior relations of the right kidney are all except?","o":["Liver","4th part of duodenum","Hepatic flexure","Adrenal gland"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (630, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 630, '{"id":630,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":630,"q":"Pancreas divisum indicates which of the following ?","o":["Duplication of the pancreas","Failure of fusion of dorsal & ventral pancreatic buds","Formation of more than two pancreatic buds","Formation of only one pancreatic bud"],"a":1,"e":"Answer-. is ''b'' i.e., Failure of fusion of dorsal & ventral pancreatic buds [Ref Inderbir Singh Human Embryology 8thle p. 168] Anomalies of pancreatic development may be:","pyqMatches":[{"year":"2012","no":70,"q":"Pancreas divisum indicates which of the following ?","o":["Duplication of the pancreas","Failure of fusion of dorsal & ventral pancreatic buds","Formation of more than two pancreatic buds","Formation of only one pancreatic bud"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (631, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 631, '{"id":631,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":631,"q":"Right ovarian artery is a branch of ?","o":["Abdominal aorta","Right internal iliac","Common iliac","External iliac"],"a":0,"e":"Ans. ''a'' i.e., Abdominal aorta [Ref BDC 5th/e Volume .3 p. 343] Lateral branches: * Inferior phrenic artery * Middle suprarenal artery * Renal artery * Testicular / ovarian artery","pyqMatches":[{"year":"2012","no":72,"q":"Right ovarian artery is a branch of ?","o":["Abdominal aorta","Right internal iliac","Common iliac","External iliac"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (632, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 632, '{"id":632,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":632,"q":"Structure immediately posterior to pancreatic head?","o":["Right renal vein","Splenic artery","Inferior mesenteric vein","Coeliac trunk"],"a":0,"e":"Ans. is ''a'' i.e., Right renal vein [Ref BDC 5`Ve volume 2 p. 306] Terminal part of right renal vein is posterior to head of pancreatic","pyqMatches":[{"year":"2012","no":73,"q":"Structure immediately posterior to pancreatic head?","o":["Right renal vein","Splenic artery","Inferior mesenteric vein","Coeliac trunk"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (633, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 633, '{"id":633,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":633,"q":"Which of these best describes the renal angle ?","o":["The angle between the lattissimus dorsi and the 12th rib","The angle between the erector spinae and the iliac crest","The angle between the 12th rib and the erector spinae","The angle between the 12th rib and the rectus abdominis"],"a":2,"e":"Answer-. is ''C'' i.e., The angle between the 12th rib and the erector spinae The angle between the lower border of the 12th rib and the outer border of the erector spinae is known as the renal angle. Overlies the lower part of the kidney. Tenderness in the kidney is elicited by applying pressure over this area.","pyqMatches":[{"year":"2012","no":74,"q":"Which of these best describes the renal angle ?","o":["The angle between the lattissimus dorsi and the 12th rib","The angle between the erector spinae and the iliac crest","The angle between the 12th rib and the erector spinae","The angle between the 12th rib and the rectus abdominis"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (634, 'Anatomy', 'Pelvis & Perineum', 'Hard', 'Anatomy', 634, '{"id":634,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Hard","source":"Anatomy","sourceNo":634,"q":"In patients with penile injury, Colle''s fascia prevents extravasation of urine in ?","o":["Ischiorectal fossa","Perineum","Abdomen","None"],"a":0,"e":"Ans. is ''a'' i.e., Ischiorectal fossa [Ref BDC 5th/e Volume H p. 211]","pyqMatches":[{"year":"2012","no":76,"q":"In patients with penile injury, Colle''s fascia prevents extravasation of urine in ?","o":["Ischiorectal fossa","Perineum","Abdomen","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (635, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 635, '{"id":635,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":635,"q":"Neurovascular plane in anterior abdominal wall -","o":["Between ext oblique and internal oblique","Between int. oblique and transversus abdominis","Below transversus abdominis","Above ext. oblique"],"a":1,"e":"Ans. is ''b'' i.e., Between int. oblique and transverses abdominis [Ref: Human anatomy 5th/p. 73] The muscles of the anterior abdominal wall consist of three broad thin sheets that are aponeurotic in front, from exterior to interior they are external oblique, internal oblique and transversus. The nerve and accompanying intercostal vessels lie between the internal oblique and trannsverse abdominis. i.e. neurovascular plane.","pyqMatches":[{"year":"2012","no":82,"q":"Neurovascular plane in anterior abdominal wall","o":["Between ext oblique and internal oblique","Between int. oblique and transversus abdominis","Below transversus abdominis","Above ext. oblique"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (636, 'Anatomy', 'Pelvis & Perineum', 'Moderate', 'Anatomy', 636, '{"id":636,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Moderate","source":"Anatomy","sourceNo":636,"q":"In bladder injury, pain is referred to all except ?","o":["Upper part of thigh","Lower abdominal wall","Flank","Penis"],"a":2,"e":"Ans. is ''c'' i.e., Flank [Ref B.D.C. Vol II 6th/e p. 375; Clinical Anatomy - 912] Pain fibers from bladder pass through both parasympathetic and sympathetic pathway and enter T11- L2 and S2- S4 cord segments. Hence referred pain is felt in the lower part of anterior abdominal wall (hypogastrium), upper part of front of thighs, scrotum or labium majus, penis or clitoris, and perineum.","pyqMatches":[{"year":"2012","no":85,"q":"In bladder injury, pain is referred to all except ?","o":["Upper part of thigh","Lower abdominal wall","Flank","Penis"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (637, 'Anatomy', 'Miscellaneous', 'Moderate', 'Anatomy', 637, '{"id":637,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anatomy","sourceNo":637,"q":"Structure not seen at L3 level ?","o":["Iliac vessels","Aorta","Coeliac trunk","IVC"],"a":2,"e":"Ans. is ''C'' i.e., Coeliac trunk Coeliac trunk is at T12 - L 1level. The transverse section at the level of L3 shows lower abdominal organs.","pyqMatches":[{"year":"2012","no":86,"q":"Structure not seen at L3 level ?","o":["Iliac vessels","Aorta","Coeliac trunk","IVC"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (638, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 638, '{"id":638,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":638,"q":"Spleen extends from ?","o":["5th to 9th rib","9 th to 11th rib","2nd to 5th rib","11th to 12th rib"],"a":1,"e":"Ans. is ''b'' i.e., 9th to 11th rib [Ref BDC Vol. II SthIe p. 431] Surface marking of spleen","pyqMatches":[{"year":"2012","no":87,"q":"Spleen extends from ?","o":["5th to 9th rib","9 th to 11th rib","2nd to 5th rib","11th to 12th rib"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (639, 'Anatomy', 'Abdomen', 'Moderate', 'Anatomy', 639, '{"id":639,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Moderate","source":"Anatomy","sourceNo":639,"q":"All are branches of the inferior mesenteric artery except ?","o":["Left colic","Sigmoidal artery","Middle rectal","Superior rectal"],"a":2,"e":"Ans. ''C'' i.e., Middle rectal Inferior mesenteric artery branches:","pyqMatches":[{"year":"2012","no":90,"q":"All are branches of the inferior mesenteric artery except ?","o":["Left colic","Sigmoidal artery","Middle rectal","Superior rectal"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (640, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 640, '{"id":640,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":640,"q":"Rouviere nodes are situated in ?","o":["Nasopharynx","Oral cavity","Retropharynx","Clavicular nodes"],"a":2,"e":"Ans. is ''c'' i.e., Retropharynx The Rouviere''s node is the most superior of the lateral group of the retropharyngeal lymph nodes, and is found at the base of the skull. The krewse''s nodes are lymph nodes situated in the jugular foramen. Enlargement of these nodes compress on cranial nerves IX, X and XI, causing jugular foramen syndrome.","pyqMatches":[{"year":"2012","no":100,"q":"Rouviere nodes are situated in ?","o":["Nasopharynx","Oral cavity","Retropharynx","Clavicular nodes"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (641, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 641, '{"id":641,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":641,"q":"Risorius is a muscle of ?","o":["Mastication","Deglutition","Facial expression","Eye movement"],"a":2,"e":"Ans. is ''c'' i.e., Facial expression [Ref BDC Vol. III, 5th /e p. 57] The risorius (also risorius muscle, latin: musculus risorius) is a muscle of facial expression located laterally to the mouth opening, which pulls the angle of the mouth laterally. * Origin - The risorius originates from the masseteric fascia. * Insertion - The risorius inserts into the skin of the angle of the mouth. * Action - Upon activation the risorius pulls the angle of the mouth laterally. - Contractions of the risorius muscle produce facial expression of pleasure and laughter. * Innervation - The risorius is innervated by the buccal branch of the facial nerve (CN VII). * Blood supply - The risorius is mainly supplied by the superior labial branch of the facial artery.","pyqMatches":[{"year":"2012","no":118,"q":"Risorius is a muscle of ?","o":["Mastication","Deglutition","Facial expression","Eye movement"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (642, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 642, '{"id":642,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":642,"q":"The thyrocervical trunk is a branch of which part of subclavian artery?","o":["1st","2nd","3rd","None"],"a":0,"e":"Ans. ''a'' i.e., 1st Branches of the subclavian artery:?","pyqMatches":[{"year":"2012","no":120,"q":"The thyrocervical trunk is a branch of which part of subclavian artery?","o":["1st","2nd","3rd","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (643, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 643, '{"id":643,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":643,"q":"Nucleus fasciculatus is seen in ?","o":["Frontal lobe","Medulla","Temporal lobe","Midbrain"],"a":1,"e":"Ans. is ''b'' i.e., Medulla [Ref Quantitative Human physiology : An introduction p. 327] It has not been mentioned in any textbook. But according to the above mentioned reference nucleus fasciculatus is the other name of nucleus cuneatus. \"The sensory fibers of dorsal column travel in tracts, fasciculus gracilis and fasciculus Cuneatus in the Cord and these fibers make synapses with second order neurons in the nucleus gracilis and the nucleus fasciculatus\". — Quantitative Human physiology. Nucleus gracilis and nucleus fasciculus are found in the medulla.","pyqMatches":[{"year":"2012","no":122,"q":"Nucleus fasciculatus is seen in ?","o":["Frontal lobe","Medulla","Temporal lobe","Midbrain"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (644, 'Anatomy', 'Miscellaneous', 'Easy', 'Anatomy', 644, '{"id":644,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Easy","source":"Anatomy","sourceNo":644,"q":"Which of the following is an operculated sulcus ?","o":["Calcarine","Collateral","Lunate","Central"],"a":2,"e":"Ans. is ''c'' i.e., Lunate Operculated sulcus separates by its lips into two areas and contains a third area in the walls of the sulcus e.g. lunate sulcus is an operculated sulcus, separating the striate and parastriate areas. Axial → Posterior part of calcarine sulcus Limiting → Central sulcus Anterior part of calcarine sulcus Operculated → Lunate sulcus Complete → Collateral sulcus, Anterior part of calcarine sulcus","pyqMatches":[{"year":"2012","no":123,"q":"Which of the following is an operculated sulcus ?","o":["Calcarine","Collateral","Lunate","Central"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (645, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 645, '{"id":645,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":645,"q":"Chamberlains line is ?","o":["Palate to occiput","Palate to temporal","Palate to foramen magnum","Palate to parietal"],"a":2,"e":"Ans. is ''c'' i.e., Palate to foramen magnum [Ref: Atlas of radiographic measurement] The Chamberlain line is drawn from the posterior surface of the hard palate to the tip of the opisthion (posterior aspect of the foramen magnum). It is used to measure the distance of how much the odontoid tip extends above this line. If the tip of the dens extends > 3 mm above this line then it helps to recognize the presence of basilar invagination (a craniocervical junction abnormality where the tip of the dens project up into the foramen magnum)","pyqMatches":[{"year":"2012","no":128,"q":"Chamberlains line is ?","o":["Palate to occiput","Palate to temporal","Palate to foramen magnum","Palate to parietal"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (646, 'Anatomy', 'Thorax', 'Moderate', 'Anatomy', 646, '{"id":646,"subject":"Anatomy","chapter":"Thorax","difficulty":"Moderate","source":"Anatomy","sourceNo":646,"q":"Structures not passing through Aortic opening:","o":["Azygos vein","Aorta","Thoracic duct","Vagus"],"a":3,"e":"Answer - D. Vagus Aortic opening (Aortic hiatus) is one of the three major apertures through the diaphragm & lies at the level of T12. Several structures pass through the aortic hiatus: aorta, azygos vein, thoracic duct. Vagus passes through the oesophageal hiatus.","pyqMatches":[{"year":"2018","no":10,"q":"Structures not passing through Aortic opening:","o":["Azygos vein","Aorta","Thoracic duct","Vagus"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (647, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 647, '{"id":647,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":647,"q":"Nerves of Branchial arch derived from:","o":["Mesoderm","Endoderm","Neural crest","Neuroectoderm"],"a":2,"e":"Answer -C. Neural crest Branchial or pharyngeal arches are masses of mesoderm covered by ectoderm and lined by endoderm. Within these masses, muscular and skeletal components develop, as well as aortic arches and nerve networks. The arches are separated by grooves, visible on the surface of the embryo as pharyngeal clefts and in the interior as the pharyngeal pouches In the human embryo, the arches are first seen during the 4th week of development. They appear as a series of outpouchings of mesoderm on both sides of developing pharynx. The neural crest are bilaterally paired strips of cells arising in the ectoderm at the margins of the neural tube. These cells migrate to many different locations and differentiate into many cell types within the embryo. Neural Crest Derivatives A key feature of neural crest is the migration into other embryonic tissues to form specific neural and non-neural populations and structures. Cranial neural crest migration - dorsolaterally and into pharyngeal arches craniofacial mesenchyme - cartilage, bone, cranial neurons, glia, and connective tissues of the face pharyngeal arches and pouches - thymic cells, tooth odontoblasts, middle ear bones (ossicles), stria vascularis cells, and jaw (mandible) In the body region, neural crest cells also contribute the peripheral nervous system (both neurons and glia) consisting of sensory ganglia (dorsal root ganglia), sympathetic and parasympathetic ganglia and neural plexuses within specific tissues/organs. In the head region, neural crest cells migrate into the pharyngeal arches forming ectomesenchyme contributing tissues which in the body region are typically derived from mesoderm (cartilage, bone, and connective tissue). Neural Crest Origin System Cell Type PeripheralNervous System (PNS) Neurons - sensory ganglia, sympathetic and parasympathetic ganglia, enteric nervous system, and plexuses Neuroglial cells, olfactory ensheathing cells Schwann cells Endocrine Adrenal medulla Calcitonin-secreting cells Carotid body type I cells Integumentary Epidermal pigment cells Facial cartilage and bone Facial and anterior ventral skull cartilage and bones Sensory Inner ear, corneal endothelium and stroma Connective tissue Tooth papillae smooth muscle, and adipose tissue of skin of head and neck Connective tissue of meninges, salivary, lacrimal, thymus, thyroid, and pituitary glands Connective tissue and smooth muscle in arteries of aortic arch origin","pyqMatches":[{"year":"2017","no":2,"q":"Nerves of Branchial arch derived from:","o":["Mesoderm","Endoderm","Neural crest","Neuroectoderm"],"a":2,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":1,"q":"Nerves of Branchial arch derived from:","o":["Mesoderm","Endoderm","Neural crest","Neuroectoderm"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (648, 'Anatomy', 'Upper Limb', 'Easy', 'Anatomy', 648, '{"id":648,"subject":"Anatomy","chapter":"Upper Limb","difficulty":"Easy","source":"Anatomy","sourceNo":648,"q":"Acute tonsillitis effects which nerve:","o":["Glossopharyngeal Nerve","Facial Nerve","Trigeminal nerve","Vagus Nerve"],"a":0,"e":"Answer- A. Glossopharyngeal Nerve The nerves supplying the palatine tonsils come from the maxillary division of the trigeminal nerve via the lesser palatine nerves, and the tonsillar branches of the glossopharyngeal nerve. The glossopharyngeal nerve continues past the palatine tonsil and innervates the posterior 1/3 of the tongue to provide general and taste sensation. This nerve is most likely to be damaged during a tonsillectomy, which leads to reduced or lost general sensation and taste sensation to the posterior third of the tongue. Relations of tonsillar bed","pyqMatches":[{"year":"2018","no":9,"q":"Acute tonsillitis effects which nerve:","o":["Glossopharyngeal Nerve","Facial Nerve","Trigeminal nerve","Vagus Nerve"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (649, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 649, '{"id":649,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":649,"q":"Hard palate contains:","o":["Keratinised, submucosa, minor salivary gland","Keratinised, absent submucosal layer, minor salivary gland","Non keratinised, submucosal layer, minor salivary gland","Non keratinised, absent submucosa, minor salivary gland"],"a":0,"e":"Answer - A. Keratinised, submucosa, minor salivary gland The hard palate is located on the roof of the oral cavity, posterior and medial to the alveolar process of the maxilla. The bony structure is formed by the palatine processes of the maxilla and the horizontal plates of the palatine bones. The periosteum is covered by a firmly attached mucosa centrally, although a submucosa is apparent laterally containing vessels. The hard palate is continuous with the soft palate posteriorly. Macroscopic Features The hard palate is typically a pale pink colour and may have an orange peel appearance from the palatine salivary glands (more common posteriorly). Microscopic Features The hard palate is lined with a keratinising stratified squamous epithelium, tightly bound to the underlying periosteum of the palatine bone/maxilla. There is minimal submucosa, which becomes more prominent posteriorly.","pyqMatches":[{"year":"2017","no":3,"q":"Hard palate contains:","o":["Keratinised, submucosa, minor salivary gland","Keratinised, absent submucosal layer, minor salivary gland","Non keratinised, submucosal layer, minor salivary gland","Non keratinised, absent submucosa, minor salivary gland"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":2,"q":"Hard palate contains:","o":["Keratinised, submucosa, minor salivary gland","Keratinised, absent submucosal layer, minor salivary gland","Non keratinised, submucosal layer, minor salivary gland","Non keratinised, absent submucosa, minor salivary gland"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (650, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 650, '{"id":650,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":650,"q":"Broca’s area situated in:","o":["Inferior frontal gyrus","Superior temporal gyrus","Angular gyrus","None of the above"],"a":0,"e":"Answer- A. Inferior frontal gyrus Broca''s area or the Broca area (44) is a region in the frontal lobe of the dominant hemisphere (usually the left) of the hominid brain with functions linked to speech production. Inability to speak after injury to the posteriorinferior frontal gyrus of the brain. Pierre Paul Brocahe identified this region, known as Broca''s area. Difficulty in language production as Broca''s aphasia, also called expressive aphasia. Broca''s area is now typically defined in terms of the pars opercularis and pars triangularis of the inferior frontal gyrus. BROCA’S AREA(shown in red). Colored region is pars opercularis and pars triangularis of the inferior frontal gyrus. Broca''s area is now typically defined in terms of the pars opercularis and pars triangularis of the inferior frontal gyrus.","pyqMatches":[{"year":"2018","no":8,"q":"Broca’s area situated in:","o":["Inferior frontal gyrus","Superior temporal gyrus","Angular gyrus","None of the above"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (651, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 651, '{"id":651,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":651,"q":"Thrombosis of posterior inferior cerebellar artery causes:","o":["Lateral medullary syndrome","Weber syndrome","Medial medullary syndrome","none"],"a":0,"e":"Answer- A. Lateral medullary syndrome The posterior inferior cerebellar artery (PICA), the largest branch of the vertebral artery, is one of the three main arterial blood supplies for the cerebellum, part of the brain. Occlusion of the posterior inferior cerebellar artery or one of its branches, or of the vertebral artery leads to lateral medullary syndrome also called Wallenberg syndrome","pyqMatches":[{"year":"2018","no":7,"q":"Thrombosis of posterior inferior cerebellar artery causes:","o":["Lateral medullary syndrome","Weber syndrome","Medial medullary syndrome","none"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (652, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 652, '{"id":652,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":652,"q":"What is the tensor of vocal cords:","o":["Cricothyroid","Lateral Cricoarytenoid","Thyroarytenoids","Posterior cricoarytenoids"],"a":0,"e":"Answer- A. Cricothyroid Cricothyroid : Tensor of vocal cords. Lateral cricoarytenoid: Abductor of vocal cords. Thyroarytenoid: Relaxor of vocal cords. Posterior cricoarytenoid: Abductor of vocal cords Muscles acting on the Larynx Movement Muscles Elevation of Larynx Thyrohyoid, mylohyoid Depression of larynx Sternothyroid, sternohyoid Opening inlet of larynx Thyroepiglotticus Closing inlet of larynx Aryepiglotticus Abductor of vocal cords Posterior cricoarytenoid only Adductor of vocal cords Lateral cricoarytenoid transverse & oblique arytenoids Tensor of vocal cords Cricothyroid Relaxer of vocal cords Thyroarytenoid","pyqMatches":[{"year":"2017","no":4,"q":"What is the tensor of vocal cords:","o":["Cricothyroid","Lateral Cricoarytenoid","Thyroarytenoids","Posterior cricoarytenoids"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":3,"q":"What is the tensor of vocal cords:","o":["Cricothyroid","Lateral Cricoarytenoid","Thyroarytenoids","Posterior cricoarytenoids"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (653, 'Anatomy', 'Thorax', 'Easy', 'Anatomy', 653, '{"id":653,"subject":"Anatomy","chapter":"Thorax","difficulty":"Easy","source":"Anatomy","sourceNo":653,"q":"About Sibson’s fascia which is incorrect:","o":["Attached to the inner border of 2nd rib","Covers apical part of lung","Part of scalenus anterior muscle","Vessel pass above the fascia"],"a":0,"e":"Answer-A. Attached to the inner border of 2nd rib The suprapleural membrane is known as Sibson''s fascia. It refers to a thickening of connective tissue that covers the apex of each human lung. It attaches to the internal border of the first rib and the transverse processes of vertebra C7. Suprapleural membrane/Sibson''s fascia","pyqMatches":[{"year":"2018","no":6,"q":"About Sibson’s fascia which is incorrect:","o":["Attached to the inner border of 2nd rib","Covers apical part of lung","Part of scalenus anterior muscle","Vessel pass above the fascia"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (654, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 654, '{"id":654,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":654,"q":"Ureteric bud develops from:","o":["Mesonephros","Metanephros","Pronephros","Genital sinus"],"a":0,"e":"Answer- A. Mesonephros The ureteric bud, also known as the metanephrogenic diverticulum, is a protrusion from the mesonephric duct during the development of the urinary and reproductive organs. It later develops into a conduit (channel) for urine drainage from the kidneys, which, in contrast, originate from the metanephric blastema. The metanephrogenic blastema or metanephric blastema (or metanephric mesenchyme, or metanephric mesoderm) is one of the two embryological structures that give rise to the kidney, the other being the ureteric bud.","pyqMatches":[{"year":"2017","no":5,"q":"Ureteric bud develops from:","o":["Mesonephros","Metanephros","Pronephros","Genital sinus"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":4,"q":"Ureteric bud develops from:","o":["Mesonephros","Metanephros","Pronephros","Genital sinus"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (655, 'Anatomy', 'Neuroanatomy', 'Easy', 'Anatomy', 655, '{"id":655,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Easy","source":"Anatomy","sourceNo":655,"q":"About Weber’s syndrome which is incorrect:","o":["Contralateral hemiplegia","Ipsilateral Oculomotor nerve palsy","Contralateral Parkinsonism","Anterior cerebral peduncle"],"a":3,"e":"Answer - D. Anterior cerebral peduncle Weber''s syndrome (superior alternating hemiplegia) is a form of stroke characterized by the presence of an ipsilateral oculomotor nerve palsy and contralateral hemiparesis or hemiplegia. It is caused by midbrain infarction as a result of occlusion of the paramedian branches of the posterior cerebral artery or basilar bifurcation perforating arteries. This lesion is usually unilateral and affects several structures in the midbrain: Contralateral parkinsonism because its dopaminergic projections to the basal ganglia innervate the ipsilateral hemisphere motor field, leading to a movement disorder of the contralateral body. Contralateral hemiparesis and typical upper motor neuron findings. It is contralateral because it occurs before the decussation in the medulla. Difficulty with contralateral lower facial muscles and hypoglossal nerve functions. Ipsilateral Oculomotor nerve palsy with a drooping eyelid and fixed wide pupil pointed down and out. This leads to diplopia.","pyqMatches":[{"year":"2017","no":6,"q":"About Weber’s syndrome which is incorrect:","o":["Contralateral hemiplegia","Ipsilateral Oculomotor nerve palsy","Contralateral Parkinsonism","Anterior cerebral peduncle"],"a":3,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":5,"q":"About Weber’s syndrome which is incorrect:","o":["Contralateral hemiplegia","Ipsilateral Oculomotor nerve palsy","Contralateral Parkinsonism","Anterior cerebral peduncle"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (656, 'Anatomy', 'Neuroanatomy', 'Moderate', 'Anatomy', 656, '{"id":656,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":656,"q":"All are special visceral efferent column except -","o":["Glossopharyngeal n","Nucleus ambiguus","vagus nerve","trigeminal nerve"],"a":1,"e":"Answer: B. Nucleus ambiguus Special visceral efferent fibers (SVE) are the efferent nerve fibers that provide motor innervation to the muscles of the pharyngeal arches in humans,The only nerves containing SVE fibers are cranial nerves: the trigeminal nerve (V), the facial nerve (VII), the glossopharyngeal nerve (IX), the vagus nerve (X) and the accessory nerve","pyqMatches":[{"year":"2017","no":243,"q":"All are special visceral efferent column except","o":["Glossopharyngeal n","Nucleus ambiguus","vagus nerve","trigeminal nerve"],"a":1,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":285,"q":"All are special visceral efferent column except","o":["Glossopharyngeal n","Nucleus ambiguus","vagus nerve","trigeminal nerve"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (657, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 657, '{"id":657,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":657,"q":"Which of the following statements is not true about iliolumbar ligament?","o":["Upper fibres attached to iliac crest","Lower fibres attached to base of sacrum","Help in maintaining lumbosacral joint stability","Upper attachment to transverse process of T12"],"a":3,"e":"Answer: D - Upper attachment to transverse process of T12 The ligament attaches to L5 Iliolumbar ligament: Strong ligament passing from the tip of transverse process of fifth lumbar vertebra to posterior part of inner lip of iliac crest Upper bands gets attached to the iliac crest. Lower bands gets attached to base of sacrum. Major function is to strengthen the lumbosacral joint.","pyqMatches":[{"year":"2018","no":287,"q":"Which of the following statements is not true about iliolumbar ligament?","o":["Upper fibres attached to iliac crest","Lower fibres attached to base of sacrum","Help in maintaining lumbosacral joint stability","Upper attachment to transverse process of T12"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (658, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 658, '{"id":658,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":658,"q":"Which of the following structure develops from dorsal mesentery?","o":["Greater omentum","Lesser omentum","Liver","Diaphragm"],"a":0,"e":"Ans. A. Greater omentum The portion of the dorsal mesentery that attaches to the greater curvature of the stomach, is known as the dorsal mesogastrium. The part of the dorsal mesentery that suspends the colon is termed the mesocolon. The dorsal mesogastrium develops into the greater omentum.","pyqMatches":[{"year":"2018","no":280,"q":"Which of the following structure develops from dorsal mesentery?","o":["Greater omentum","Lesser omentum","Liver","Diaphragm"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (659, 'Anatomy', 'Head & Neck', 'Easy', 'Anatomy', 659, '{"id":659,"subject":"Anatomy","chapter":"Head & Neck","difficulty":"Easy","source":"Anatomy","sourceNo":659,"q":"Chordoma arises from:","o":["Pharyngeal bursa","Notochord","Rathke’s pouch","Luschka''s bursa"],"a":1,"e":"Answer: - B. Notochord Chordoma is a rare slow-growing neoplasm thought to arise from cellular remnants of the notochord. Chordomas can arise from bone in the skull base and anywhere along the spine. The two most common locations are cranially at the clivus and in the sacrum at the bottom of the spine. There are three histological variants of chordoma: classical (or \"conventional\"), chondroid and dedifferentiated.","pyqMatches":[{"year":"2018","no":239,"q":"Chordoma arises from:","o":["Pharyngeal bursa","Notochord","Rathke’s pouch","Luschka''s bursa"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (660, 'Anatomy', 'Pelvis & Perineum', 'Easy', 'Anatomy', 660, '{"id":660,"subject":"Anatomy","chapter":"Pelvis & Perineum","difficulty":"Easy","source":"Anatomy","sourceNo":660,"q":"Seminal colliculus is present in ?","o":["Testis","Prostate","Urethra","Scrotum"],"a":2,"e":"Ans. is ''c'' i.e., Urethra Seminal colliculus or colliculus seminalis or verumontanum is present in the prostatic urethra. Features of the prostatic urethra Urethral crest - median longitudinal mucous fold. Colliculus seminalis (verumontanum): An elevation in the middle of the urethral crest with the opening of a prostatic utricle at its summit and an ejaculatory duct on each side. Openings of ejaculatory ducts: These are present on each side of the orifice of the utricle. Prostatic sinuses: These are vertical grooves present on each side of the urethral crest. They are present with openings of prostatic glands.","pyqMatches":[{"year":"2015","no":158,"q":"Seminal colliculus is present in ?","o":["Testis","Prostate","Urethra","Scrotum"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (661, 'Anatomy', 'Abdomen', 'Moderate', 'Anatomy', 661, '{"id":661,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Moderate","source":"Anatomy","sourceNo":661,"q":"Which of the following is not a derivative of foregut?","o":["Cecum","duodenum","Liver","Pancreas"],"a":0,"e":"Ans. is ''a'' i.e., Cecum [Ref Langman 11th/e p. 223]:- Derivatives are:- Pharynx Lower respiratory tract Esophagus Stomach Duodenum upto the opening of the main pancreatic duct Liver Pancreas","pyqMatches":[{"year":"2015","no":159,"q":"Which of the following is not a derivative of foregut?","o":["Cecum","duodenum","Liver","Pancreas"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (662, 'Anatomy', 'Histology', 'Easy', 'Anatomy', 662, '{"id":662,"subject":"Anatomy","chapter":"Histology","difficulty":"Easy","source":"Anatomy","sourceNo":662,"q":"Upward movement of the thyroid gland is prevented due to?","o":["Berry ligament","Pretracheal fascia","Sternothyroid muscle","Thyrohyoid membrane"],"a":1,"e":"Ans: B. Pretracheal fascia The thyroid gland is covered by a thin fibrous capsule, which has an inner and an outer layer. The inner layer extrudes into the gland and forms the septum that divides the thyroid tissue into microscopic lobules. The outer layer is continuous with the pretracheal fascia, attaching the gland to the cricoid and thyroid cartilages via a thickening of the fascia to form the posterior suspensory ligament of the thyroid gland also known as Berry''s ligament. This causes the thyroid to move up and down with the movement of these cartilages when swallowing occurs. Gray''s Anatomy: The Anatomical Basis of Clinical Practice, 41e ,Page no 470","pyqMatches":[{"year":"2020","no":1,"q":"Upward movement of the thyroid gland is prevented due to?","o":["Berry ligament","Pretracheal fascia","Sternothyroid muscle","Thyrohyoid membrane"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (663, 'Anatomy', 'Embryology', 'Moderate', 'Anatomy', 663, '{"id":663,"subject":"Anatomy","chapter":"Embryology","difficulty":"Moderate","source":"Anatomy","sourceNo":663,"q":"The reason for the long left recurrent laryngeal nerve is due to the persistence of which arch artery?","o":["3rd arch","4th arch","5th arch","2nd arch"],"a":1,"e":"Ans: B. 4th arch Left RLN winds around the arch of aorta Arch of aorta is derived from the 4th arch Langmans Medical Embryology 13th edition (Page no 88,239)","pyqMatches":[{"year":"2020","no":2,"q":"The reason for the long left recurrent laryngeal nerve is due to the persistence of which arch artery?","o":["3rd arch","4th arch","5th arch","2nd arch"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (664, 'Anatomy', 'General Anatomy', 'Easy', 'Anatomy', 664, '{"id":664,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Easy","source":"Anatomy","sourceNo":664,"q":"Ligation of the hepatic artery will impair blood supply in","o":["Right gastric and Right gastroepiploic artery","Right gastric and Left gastric artery","Right gastroepiploic and short gastric vessels","Right gastric and short gastric vessels"],"a":0,"e":"Ans: A. Right gastric and Right gastroepiploic artery The right gastric artery is a branch of the common hepatic artery The right gastroepiploic artery is a branch of the gastroduodenal artery which is a branch of the common hepatic artery The left gastric artery is a branch of the celiac trunk Short gastric vessels arise from the splenic artery Gray''s Anatomy: The Anatomical Basis of Clinical Practice, 41st Edition (Page nos 1116 and 1117)","pyqMatches":[{"year":"2020","no":3,"q":"Ligation of the hepatic artery will impair blood supply in","o":["Right gastric and Right gastroepiploic artery","Right gastric and Left gastric artery","Right gastroepiploic and short gastric vessels","Right gastric and short gastric vessels"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (665, 'Anatomy', 'Embryology', 'Easy', 'Anatomy', 665, '{"id":665,"subject":"Anatomy","chapter":"Embryology","difficulty":"Easy","source":"Anatomy","sourceNo":665,"q":"Wolffian duct remnant in female is","o":["Pouch of Douglas","Uterovesical pouch","Gartner’s cyst","Broad ligament"],"a":2,"e":"Ans: C. Gartner’s cyst Gartner’s cysts, sometimes incorrectly referred to as vaginal inclusion cysts, are the most common benign cystic lesions of the vagina. They represent embryological remnants of the caudal end of the mesonephric( Wolffian) duct. Gartner’s ducts are found in about 25% of adult women. Almost one percent of these ducts evolve into Gartner’s duct cyst. Ref: A case of Gartner’s cyst of vagina, J. Anesth Crit care Open Access, 2017, 00259.","pyqMatches":[{"year":"2020","no":4,"q":"Wolffian duct remnant in female is","o":["Pouch of Douglas","Uterovesical pouch","Gartner’s cyst","Broad ligament"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (666, 'Anatomy', 'Neuroanatomy', 'Moderate', 'Anatomy', 666, '{"id":666,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":666,"q":"Nerve supply of the extraocular muscles is constituted by all except","o":["Ophthalmic nerve","Oculomotor nerve","Trochlear nerve","Abducent nerve"],"a":0,"e":"Ans: A. Ophthalmic nerve Lateral rectus is supplied by 6th cranial nerve( abducent nerve) Superior rectus is supplied by 4th cranial nerve (trochlear nerve) All of the remaining extraocular muscles are supplied by the oculomotor nerve. The ophthalmic nerve is a branch of the trigeminal nerve and is purely sensory in nature. BDC 7th edition, volume 3, pg no. 215.","pyqMatches":[{"year":"2020","no":5,"q":"Nerve supply of the extraocular muscles is constituted by all except","o":["Ophthalmic nerve","Oculomotor nerve","Trochlear nerve","Abducent nerve"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (667, 'Anatomy', 'Lower Limb', 'Easy', 'Anatomy', 667, '{"id":667,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Easy","source":"Anatomy","sourceNo":667,"q":"Claudication due to popliteal femoral incompetence is primarily seen in","o":["Thigh","Calf","Buttocks","Feet"],"a":1,"e":"Ans: B. Calf Calf Aorta and Common Iliac- Buttocks Femoral Artery- Thigh Superficial femoral artery- Calf and popliteal artery Posterior tibial Artery- Feet BDC 7th edition, volume 2, page no 137.","pyqMatches":[{"year":"2020","no":6,"q":"Claudication due to popliteal femoral incompetence is primarily seen in","o":["Thigh","Calf","Buttocks","Feet"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (668, 'Anatomy', 'General Anatomy', 'Moderate', 'Anatomy', 668, '{"id":668,"subject":"Anatomy","chapter":"General Anatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":668,"q":"Which muscle is paralyzed if there is hyperextension of metacarpophalangeal joint and flexion of the interphalangeal joint?","o":["Extensor digitorum","Interossei and lumbricals","Adductor pollicis","Pronator quadratus muscle"],"a":1,"e":"Ans: B. Interossei and lumbricals Hyperextension of metacarpophalangeal joint and flexion of the interphalangeal joint is due to palsy of lumbricals and interossei muscles. The action of Lumbricals: Flexion of MCP, Extension of IP joint The action of Palmar interossei: Adduction of fingers The action of Dorsal interossei: Abduction of fingers Ref: BDC, 7th edition, volume 1, pg no. 163.","pyqMatches":[{"year":"2020","no":7,"q":"Which muscle is paralyzed if there is hyperextension of metacarpophalangeal joint and flexion of the interphalangeal joint?","o":["Extensor digitorum","Interossei and lumbricals","Adductor pollicis","Pronator quadratus muscle"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (669, 'Anatomy', 'Abdomen', 'Easy', 'Anatomy', 669, '{"id":669,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Easy","source":"Anatomy","sourceNo":669,"q":"Tumour of the uncinate process of the pancreas will compress which artery","o":["Portal vein","Superior mesenteric artery","Inferior mesenteric artery","Common hepatic artery"],"a":1,"e":"Ans: B. Superior mesenteric artery The superior mesenteric artery passes anterior to the uncinate process Posteriorly, the uncinate process is related to aorta. Ref: BDC , 7th edition, vol 2, page- 328.","pyqMatches":[{"year":"2020","no":8,"q":"Tumour of the uncinate process of the pancreas will compress which artery","o":["Portal vein","Superior mesenteric artery","Inferior mesenteric artery","Common hepatic artery"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (670, 'Anatomy', 'Neuroanatomy', 'Moderate', 'Anatomy', 670, '{"id":670,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Moderate","source":"Anatomy","sourceNo":670,"q":"A boy met with a motorbike accident. CT brain shows injury to the posterior end of the superior temporal gyrus. He is likely to suffer from","o":["Fluent aphasia","Non-fluent aphasia","Conduction aphasia","None of the above"],"a":0,"e":"Ans: A. Fluent aphasia Fluent aphasia Lesions in the posterior portion of the left STG were associated with the loss of the ability to comprehend and produce spoken words which are called as “fluent aphasia” BDC 7th edition, volume 4, page no 129.","pyqMatches":[{"year":"2020","no":9,"q":"A boy met with a motorbike accident. CT brain shows injury to the posterior end of the superior temporal gyrus. He is likely to suffer from","o":["Fluent aphasia","Non-fluent aphasia","Conduction aphasia","None of the above"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (671, 'Anatomy', 'Miscellaneous', 'Hard', 'Anatomy', 671, '{"id":671,"subject":"Anatomy","chapter":"Miscellaneous","difficulty":"Hard","source":"Anatomy","sourceNo":671,"q":"A 65-year-old lady presents with a vascular injury to the inferior frontal gyrus. Which functional area would mostly be affected","o":["Visual","Auditoryss","Wernicke","Motor speech"],"a":3,"e":"Ans: D. Motor speech Motor speech defect is also called apraxia of speech. Injury to the Broca’s area/left inferior frontal gyrus causes motor speech defect. BDC 7th edition, volume 4, page no 129.","pyqMatches":[{"year":"2020","no":10,"q":"A 65-year-old lady presents with a vascular injury to the inferior frontal gyrus. Which functional area would mostly be affected","o":["Visual","Auditoryss","Wernicke","Motor speech"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (672, 'Anatomy', 'Neuroanatomy', 'Hard', 'Anatomy', 672, '{"id":672,"subject":"Anatomy","chapter":"Neuroanatomy","difficulty":"Hard","source":"Anatomy","sourceNo":672,"q":"Where is the highest oxygen concentration presents in fetal circulation","o":["SVC","IVC","Right ventricle","Aorta"],"a":1,"e":"Ans: B. IVC Highly oxygenated blood from the placenta is carried to the fetus by the umbilical vein, which is shunted to the inferior vena cava. Nelson Textbook of Pediatrics 20th Edition (Page no 2161)","pyqMatches":[{"year":"2020","no":11,"q":"Where is the highest oxygen concentration presents in fetal circulation","o":["SVC","IVC","Right ventricle","Aorta"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (673, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 1, '{"id":673,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":1,"q":"Ether was first used as an anaesthetic by?","o":["Priesly","Morton","Wells","Simpson"],"a":1,"e":"Morton REF: http://en.wikipedia.org/wiki/William_T. G_Morton William Thomas Green Morton (August 9, 1819 - July 15, 1868) was an American dentist who first publicly demonstrated the use of inhaled ether as a surgical anaesthetic in 1846","pyqMatches":[{"year":"2013","no":1701,"q":"Ether was first used as an anaesthetic by?","o":["Priesly","Morton","Wells","Simpson"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (674, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 2, '{"id":674,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":2,"q":"The following increases Intra Ocular pressure:","o":["Thiopentone","Althesin","Ketamine","Barbiturate"],"a":2,"e":"Ketamine","pyqMatches":[{"year":"2013","no":1703,"q":"The following increases Intra Ocular pressure:","o":["Thiopentone","Althesin","Ketamine","Barbiturate"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (675, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 3, '{"id":675,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":3,"q":"Composition of soda lime is: NaOH - Ca (OH)2 - KOH - Moisture","o":["4% - 90% - 1% - 5%","4% - 80% - 1% - 15%","80% - 10% - 5% - 5%","15% - 80% - 1% - 4%"],"a":1,"e":"Soda lime is the more common absorbent and is capable of absorbing up to 23 L of CO2 per 100 g of absorbent. It consists primarily of calcium hydroxide (80%), along with sodium hydroxide (4%), water, and a small amount of potassium hydroxide (1%). Commercial soda lime has a water content of 14% to 19%. CO2 absorbents (eg, soda lime or calcium hydroxide lime) contain hydroxide salts that are capable of neutralizing carbonic acid. Reaction end products include heat (the heat of neutralization), water, and calcium carbonate. Ref: Butterworth IV J.F., Butterworth IV J.F., Mackey D.C., Wasnick J.D., Mackey D.C., Wasnick J.D. (2013). Chapter 3. Breathing Systems. In J.F. Butterworth IV, J.F. Butterworth IV, D.C. Mackey, J.D. Wasnick, D.C. Mackey, J.D. Wasnick (Eds), Morgan & Mikhail''s Clinical Anesthesiology, 5e.","pyqMatches":[{"year":"2015","no":1634,"q":"Composition of soda lime is: NaOH - Ca (OH)2 - KOH - Moisture","o":["4% - 90% - 1% - 5%","4% - 80% - 1% - 15%","80% - 10% - 5% - 5%","15% - 80% - 1% - 4%"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (676, 'Anesthesia', 'General Anesthesia', 'Moderate', 'Anaesthesia', 4, '{"id":676,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Moderate","source":"Anaesthesia","sourceNo":4,"q":"All of the following are correct about ketamine, EXCEPT:","o":["It functionally \"dissociates\" the thalamus","It increases arterial blood pressure","It is a potent bronchoconstrictor","It inhibits polysynaptic reflexes in the spinal cord"],"a":2,"e":"Ketamine functionally \"dissociates\" the thalamus (which relays sensory impulses from the reticular activating system to the cerebral cortex) from the limbic cortex (which is involved with the awareness of sensation). Ketamine increases arterial blood pressure, heart rate, and cardiac output. Racemic ketamine is a potent bronchodilator, making it a good induction agent for asthmatic patients. It inhibits polysynaptic reflexes in the spinal cord as well as excitatory neurotransmitter effects in selected areas of the brain. Ref: Butterworth IV J.F., Butterworth IV J.F., Mackey D.C., Wasnick J.D., Mackey D.C., Wasnick J.D. (2013). Chapter 9. Intravenous Anesthetics. In J.F. Butterworth IV, J.F. Butterworth IV, D.C. Mackey, J.D. Wasnick, D.C. Mackey, J.D. Wasnick (Eds), Morgan & Mikhail''s Clinical Anesthesiology, 5e.","pyqMatches":[{"year":"2012","no":1401,"q":"All of the following are correct about ketamine, EXCEPT:","o":["It functionally \"dissociates\" the thalamus","It increases arterial blood pressure","It is a potent bronchoconstrictor","It inhibits polysynaptic reflexes in the spinal cord"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (677, 'Anesthesia', 'Local Anesthesia', 'Hard', 'Anaesthesia', 5, '{"id":677,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Hard","source":"Anaesthesia","sourceNo":5,"q":"A patient undergoing a minor surgical procedure is given lignocaine injection. Assertion: Local anaesthetics acts by blocking nerve conduction. Reason: Small fibers and non myelinated fibers are blocked more easily than large myelinated fibers.","o":["Both Assertion and Reason are true, and Reason is the correct explanation for Assertion","Both Assertion and Reason are true, and Reason is not the correct explanation for Assertion","Assertion is true, but Reason is false","Assertion is false, but Reason is true"],"a":1,"e":"Local anaesthetics blocks nerve conduction by decreasing the entry of sodium ions during upstroke of action potential. Finally it blocks depolarization to reach threshold potential and conduction block occurs. Small fibers are more sensitive to local anaesthetics than large fibers and non myelinated fibers are blocked easily than myelinated fibers. Ref: Essentials of Medical Pharmacology by K D Tripathi, 5th Edition, Pages 321-3","pyqMatches":[{"year":"2015","no":1260,"q":"A patient undergoing a minor surgical procedure is given lignocaine injection. Assertion: Local anaesthetics acts by blocking nerve conduction. Reason: Small fibers and non myelinated fibers are blocked more easily than large myelinated fibers.","o":["Both Assertion and Reason are true, and Reason is the correct explanation for Assertion","Both Assertion and Reason are true, and Reason is not the correct explanation for Assertion","Assertion is true, but Reason is false","Assertion is false, but Reason is true"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (678, 'Anesthesia', 'Airway Management', 'Hard', 'Anaesthesia', 6, '{"id":678,"subject":"Anesthesia","chapter":"Airway Management","difficulty":"Hard","source":"Anaesthesia","sourceNo":6,"q":"The laryngeal mask airway used for securing the airway of a patient in all of the following conditions, EXCEPT:","o":["In a difficult intubation","In cardiopulmonary resuscitation","In a child undergoing an elective/routine eye surgery","In a patient with a large tumour in the oral cavity"],"a":3,"e":"Oropharyngeal abscess or mass is a contraindication to the use of laryngeal mask airway. Ref: Short Textbook of Anaesthesia By Ajay Yadav, 2nd Edition, Page 36","pyqMatches":[{"year":"2014","no":1991,"q":"The laryngeal mask airway used for securing the airway of a patient in all of the following conditions, EXCEPT:","o":["In a difficult intubation","In cardiopulmonary resuscitation","In a child undergoing an elective/routine eye surgery","In a patient with a large tumour in the oral cavity"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (679, 'Anesthesia', 'Muscle Relaxants', 'Moderate', 'Anaesthesia', 7, '{"id":679,"subject":"Anesthesia","chapter":"Muscle Relaxants","difficulty":"Moderate","source":"Anaesthesia","sourceNo":7,"q":"All of the following statements about neuromuscular blockage produced by succinylcholine are true, except:","o":["No fade on Train of four stimulation","Fade on tetanic stimulation","No post tetanic facilitation","Train of four ratio > 0.4"],"a":1,"e":"Succinylcholine is a depolarizing neuromuscular blocker. With succinylcholine no fading is observed after train of four or tetanic stimulation. All four stimulatory responses after TOF stimulation are suppressed to the same extent. Ref: Neuromuscular Monitoring in Clinical Practice and Research By Thomas Fuchs-Buder, Page 16","pyqMatches":[{"year":"2015","no":1637,"q":"All of the following statements about neuromuscular blockage produced by succinylcholine are true, except:","o":["No fade on Train of four stimulation","Fade on tetanic stimulation","No post tetanic facilitation","Train of four ratio > 0.4"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (680, 'Anesthesia', 'Miscellaneous', 'Moderate', 'Anaesthesia', 8, '{"id":680,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anaesthesia","sourceNo":8,"q":"Mechanism of action of theophylline in Bronchial asthma include all of the following Except ?","o":["Phosphodiesterase inhibition","Adenosine receptor antagonism","Increased histone deacetylation","Beta-2 receptor stimulation"],"a":3,"e":"Ans. is ''d'' i.e., Beta-2 receptor stimulation Proposed mechanisms of action of theophylline Phosphodiesterase inhibition (Non selective) Adenosine receptor antagonism (A1, A2) Increased histone Deacetylase activity (↑red efficacy of corticosteroids) Inhibition of intracellular calcium release Stimulation of catecholamine release Inhibition of NF - alpha Beta translocation into the nucleus (nuclear translocation) Mediator inhibition (Prostaglandins, TNF alpha)","pyqMatches":[{"year":"2012","no":532,"q":"Mechanism of action of theophylline in Bronchial asthma include all of the following Except ?","o":["Phosphodiesterase inhibition","Adenosine receptor antagonism","Increased histone deacetylation","Beta-2 receptor stimulation"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (681, 'Anesthesia', 'Monitoring & Perioperative Care', 'Easy', 'Anaesthesia', 9, '{"id":681,"subject":"Anesthesia","chapter":"Monitoring & Perioperative Care","difficulty":"Easy","source":"Anaesthesia","sourceNo":9,"q":"Best to monitor intraoperative myocardial ischemia (infarction) is","o":["ECG","CVP monitoring","Transesophageal echocardiography","Invasive intracarotid arterial pressure"],"a":2,"e":"C i.e. Transesophageal echocardiography Tranoesophageal echocardiography provides a real time picture of all 4 cardiac chambers and valves. It can identify any malfunctioning valves in addition to any wall motion abnormalities related to myocardia ischemia. It is very useful during anesthesia. Abnormal motion of ventricular wall detected in this way is a reliable index of myocardial ischemia and may guide drug therapy, can identify if therapy has successfully treated the ischemia or indicate the need for further surgical revascularization CVP (catherter in central vein) measures right sided filling pressure whereas pulmonary artery catheter measures/monitors left heart filling pressure. Arterial cannulation measures direct systemic arterial pressure and facilitate sampling of arterial blood for analysis.","pyqMatches":[{"year":"2013","no":1253,"q":"Best to monitor intraoperative myocardial ischemia (infarction) is","o":["ECG","CVP monitoring","Transesophageal echocardiography","Invasive intracarotid arterial pressure"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (682, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 10, '{"id":682,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":10,"q":"Which of the following drugs produces dissociative anesthesia","o":["Ketamine","Propofol","Thiopentone","Enflurane"],"a":0,"e":"A i.e. Ketamine","pyqMatches":[{"year":"2015","no":1618,"q":"Which of the following drugs produces dissociative anesthesia","o":["Ketamine","Propofol","Thiopentone","Enflurane"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (683, 'Anesthesia', 'General Anesthesia', 'Moderate', 'Anaesthesia', 11, '{"id":683,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Moderate","source":"Anaesthesia","sourceNo":11,"q":"Ketamine can be used in all of the situations except","o":["Status asthamaticus","For analgesia & sedation","Obstetric hemorrhage","Ischemic heart disease"],"a":3,"e":"D i.e. Ischemic heart disease Ketamine causes profound analgesiaQ, disociative anesthesiaQ, and emergence psychomimetic hallucinations and delirium Q. Ketamine increases cerebral metabolism, 02 consumption, blood flow & intracranial pressure.Q Ketamine * It causes profound analgesiaQ and dissociative anesthesiaQ (i.e. patient appears conscious e.g. eye opening, swallowing but unable to process or respond to sensory input). Ketamine causes Dissociative AnesthesiaQ by acting on cortex and subcortical areas (not on RAS) l/t feeling of dissociation from ones own body and surroundings. Post Operative Delirium and HallucinationQ is part of this Dissociative phenomenon. Drug of choice for post op. delirium & hallucination is Lorazepam.Q * It is closest to being a complete anesthetic since it induces analgesia, amnesia & unconsciousness. * It is associated with emergence psychotomimetic side effects (delirium, illusions, hallucination)Q. It is less common in children and pretreatment with lorazepam (drug of choice)Q.","pyqMatches":[{"year":"2015","no":1621,"q":"Ketamine can be used in all of the situations except","o":["Status asthamaticus","For analgesia & sedation","Obstetric hemorrhage","Ischemic heart disease"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (684, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 12, '{"id":684,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":12,"q":"Anesthetic agent (s) safe to use in TICP","o":["Halothane","Thiopentone","Ketamine","Ether"],"a":1,"e":"B i.e. Thiopentone Anesthetic agents safe to use in raised intracranial pressure (ICP) are thiopentone, propofol & etomidateQ","pyqMatches":[{"year":"2015","no":1620,"q":"Anesthetic agent (s) safe to use in TICP","o":["Halothane","Thiopentone","Ketamine","Ether"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (685, 'Anesthesia', 'General Anesthesia', 'Moderate', 'Anaesthesia', 13, '{"id":685,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Moderate","source":"Anaesthesia","sourceNo":13,"q":"All of the following cause myocardial depression except:","o":["Halothane","Etomidate","Thiopentone","Ketamine"],"a":1,"e":"B i.e. Etomidate - Etomidate causes adreno - cortical suppressionQ by inhibiting enzymes 11/3 hydroxylase (mainly) & 17 a hydroxylase involved in cortisol and aldosterone (mineralocorticoid) productionQ. Vit C supplimentation restores cortisol level. - Etomidate and midazolam provide cardiovascular stabilityQ. But etomidate is most cardiostable agentQ that causes the least hemodynamic disturbance of any of the intravenous anesthetic agents. So it is intravenous anesthetic agent of choice for patients with cardiac disease and aneurysm surgeryQ. - Direct myocardial depression is caused by halothane (severe), nitrous oxide (moderate), iso/sevo/des-flurane (mild), thiopental (marked), propofol (dose dependent) and ketamineQ (but this is masked by cardiotonic sympathetic stimulatory action). Etomidate > midazolem are most cardiostable agentsQ.","pyqMatches":[{"year":"2012","no":1407,"q":"All of the following cause myocardial depression except:","o":["Halothane","Etomidate","Thiopentone","Ketamine"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (686, 'Anesthesia', 'Airway Management', 'Hard', 'Anaesthesia', 14, '{"id":686,"subject":"Anesthesia","chapter":"Airway Management","difficulty":"Hard","source":"Anaesthesia","sourceNo":14,"q":"At the end of anaesthesia after discontinuation of nitrous oxide and removal of endotracheal tube, 1000/0 oxygen is administered to the patient to prevent:","o":["Diffusion Hypoxia","Second gas effect","Hyperoxia","Bronchospasm"],"a":0,"e":"A i.e. Diffusion Hypoxia (Ref : Willer 8/e p656, 3401) On discontinuation of N2O administration, nitrous oxide gas can diffuse from blood to the alveoli, diluting O2 in the lung. Produce an effect called “Diffusional hypoxia”. To avoid hypoxia, 100% O2, rather than air should be administered when N2O discontinued.","pyqMatches":[{"year":"2015","no":1624,"q":"At the end of anaesthesia after discontinuation of nitrous oxide and removal of endotracheal tube, 1000/0 oxygen is administered to the patient to prevent:","o":["Diffusion Hypoxia","Second gas effect","Hyperoxia","Bronchospasm"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (687, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 15, '{"id":687,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":15,"q":"Stages of anesthesia were established by","o":["Ether","N20","Halothane","Chloroform"],"a":0,"e":"A i.e. Ether","pyqMatches":[{"year":"2012","no":1397,"q":"Stages of anesthesia were established by","o":["Ether","N20","Halothane","Chloroform"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (688, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 16, '{"id":688,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":16,"q":"Hepatotoxic agent is","o":["Ketamine","Ether","N20","Halothane"],"a":3,"e":"D i.e. Halothane","pyqMatches":[{"year":"2015","no":1617,"q":"Hepatotoxic agent is","o":["Ketamine","Ether","N20","Halothane"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (689, 'Anesthesia', 'Local Anesthesia', 'Easy', 'Anaesthesia', 17, '{"id":689,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":17,"q":"Shortest acting local anesthetic agent is","o":["Procaine","Lidocaine","Tetracaine","Bupivacaine"],"a":0,"e":"A i.e. Procaine","pyqMatches":[{"year":"2015","no":1630,"q":"Shortest acting local anesthetic agent is","o":["Procaine","Lidocaine","Tetracaine","Bupivacaine"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (690, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 18, '{"id":690,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":18,"q":"Pudendal Nerve Block Involve","o":["LiL2L3","L2L3L4","SiS2S3","S2S3S4"],"a":3,"e":"D i.e. S2 S3 S4","pyqMatches":[{"year":"2014","no":1968,"q":"Pudendal Nerve Block Involve","o":["LiL2L3","L2L3L4","SiS2S3","S2S3S4"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (691, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 19, '{"id":691,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":19,"q":"Which of the following anesthetic agents have analgesic property:","o":["Ketamine","Nitrous oxide","Thiopentone","a and b"],"a":3,"e":"A i.e. Ketamine; B i.e. Nitrous oxide","pyqMatches":[{"year":"2013","no":1726,"q":"Which of the following anesthetic agents have analgesic property:","o":["Ketamine","Nitrous oxide","Thiopentone","a and b"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (692, 'Anesthesia', 'Miscellaneous', 'Moderate', 'Anaesthesia', 20, '{"id":692,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anaesthesia","sourceNo":20,"q":"Contraindication of bag and mask ventilation are all of the following except: March 2009","o":["Tracheo-esophageal fistula","Hiatus hernia","Pregnancy","Empty stomach"],"a":3,"e":"Ans. D: Empty Stomach Bag-mask ventilation can produce gastric inflation with complications, including regurgitation, aspiration, and pneumonia. Conditions predisposing to aspiration are: Full stomach patients Hiatus hernia, pregnancy Intestinal obstruction Tracheo-esophageal fistula Meconium aspiration syndrome Gastric inflation can elevate the diaphragm, restrict lung movement, and decrease respiratory system compliance","pyqMatches":[{"year":"2016","no":1348,"q":"Contraindication of bag and mask ventilation are all of the following except: March 2009","o":["Tracheo-esophageal fistula","Hiatus hernia","Pregnancy","Empty stomach"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (693, 'Anesthesia', 'Muscle Relaxants', 'Moderate', 'Anaesthesia', 21, '{"id":693,"subject":"Anesthesia","chapter":"Muscle Relaxants","difficulty":"Moderate","source":"Anaesthesia","sourceNo":21,"q":"Following is true about halothane except?","o":["Volatile liquid with sweet odour","Sensitises heart to adrenaline","Constricts bronchii","Causes malignant hyperthermia"],"a":2,"e":"Ans. is ''c'' i.e., Constricts bronchii Halothane It is a volatile liquid with sweet odour, nonirritating and noninflammable. It is a potent anaesthetic with poor analgesic and muscle relaxant properties. Halothane causes direct depression of myocardial contractility by reducing intracellular Ca. It causes fall in BP and CO. Heart rate decreases due to vagal stimulation. It tends to sensitize the heart to arrhythmogenic action of adrenaline → contraindicated in pheochromocytoma. It causes greater depression of respiration and ventilation perfusion mismatch. It dilates the bronchi → inhalation agent of choice in asthmatics (intravaneous anaesthetic of choice in asthmatics is ketamine). It is a hepatotoxic drug and can also cause malignant hyperthermia (Succinylcholine accentuate it). Recovery is smooth and reasonably quick. It causes postanaesthetic shivering and chills. It inhibits intestinal and uterine contractions → agent of choice for assisting external or internal version during late pregnancy. Because its uterine relaxant action it is contraindicated during labour. It is particularly suitable for induction and maintenance in children and as maintenance anaesthetic in adults.","pyqMatches":[{"year":"2012","no":1406,"q":"Following is true about halothane except?","o":["Volatile liquid with sweet odour","Sensitises heart to adrenaline","Constricts bronchii","Causes malignant hyperthermia"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (694, 'Anesthesia', 'General Anesthesia', 'Moderate', 'Anaesthesia', 22, '{"id":694,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Moderate","source":"Anaesthesia","sourceNo":22,"q":"Midazolam causes all except:","o":["Anterograde amnesia","Retrograde amnesia","Causes tachyphylaxis during high dose infusions","Decreased cardiovascular effects as compared to propofol"],"a":1,"e":"Ans. b. Retrograde amnesia At the time of peak concentration in plasma, hypnotic doses of benzodiazepines (midazolam) can be expected to cause varying degrees of lightheadedness, lassitude, increased reaction time, motor incoordination, impairment of mental and motor functions, confusion, and anterograde amnesia.\" Midazolam: It causes anterograde amnesiaQ Tolerance and tachyphylaxis may occur, particularly with longer-term infusionsQ(Shafer A. Complications of sedation with midazolam in the intensive care unit and a comparison with other sedative regimens. Crit Care Med. 1998;26(5): 947-56) Benzodiazepine withdrawal syndrome has also been associated with high dose/ long-term midazolam infusionsQ Compared with propofol infusions, midazolam infusions have been associated with a decreased occurrence of hypotension° but a more variable time course for recovery of function after the cessation of the infusion.","pyqMatches":[{"year":"2012","no":1408,"q":"Midazolam causes all except:","o":["Anterograde amnesia","Retrograde amnesia","Causes tachyphylaxis during high dose infusions","Decreased cardiovascular effects as compared to propofol"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (695, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 23, '{"id":695,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":23,"q":"Which of the following inhalational agent sensitizes myocardium to catecholamine","o":["Sevoflurane","Isoflurane","Ether","Halothane"],"a":3,"e":"Ans. is ''d'' i.e., Halothane Some inhalational agent sensitize the heart to adrenaline —> Arrhythmias can occur —> Therefore these agents are contraindicated in Pheochromocytoma and along with adrenaline. Halothane has maximum propensity . Other agents sensitizing the heart to adrenaline are Trilene, Cyclopropane, Chloroform, Enflurane","pyqMatches":[{"year":"2014","no":1953,"q":"Which of the following inhalational agent sensitizes myocardium to catecholamine","o":["Sevoflurane","Isoflurane","Ether","Halothane"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (696, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 24, '{"id":696,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":24,"q":"Gas used in rapid airbag inflation","o":["Sodium azide","Nitrocellulose","Mercuric nitrate","Potassium nitrate"],"a":0,"e":"Ans. is ''a'' i.e., Sodium azide Chemistry of air bags The inclusion of air bags in the modern automobiles has led to decrease in the automobile injures. The term air bag is a misnomer as air is not involved in the inflation process. Rather an air bag inflates rapidly (in about 30ms) due to explosive production of N2 gas. Sodium azide is used which is rapidly decomposed to Nitrogen gas.","pyqMatches":[{"year":"2014","no":1949,"q":"Gas used in rapid airbag inflation","o":["Sodium azide","Nitrocellulose","Mercuric nitrate","Potassium nitrate"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (697, 'Anesthesia', 'Local Anesthesia', 'Moderate', 'Anaesthesia', 25, '{"id":697,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Moderate","source":"Anaesthesia","sourceNo":25,"q":"Which of the following is not primarily used to anesthetize mucosa ?","o":["Benzocaine","Lidocaine","Bupivacain","Tetracaine"],"a":2,"e":"Ans. is ''c'' i.e., Bupivacaine","pyqMatches":[{"year":"2014","no":1954,"q":"Which of the following is not primarily used to anesthetize mucosa ?","o":["Benzocaine","Lidocaine","Bupivacain","Tetracaine"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (698, 'Anesthesia', 'Airway Management', 'Easy', 'Anaesthesia', 26, '{"id":698,"subject":"Anesthesia","chapter":"Airway Management","difficulty":"Easy","source":"Anaesthesia","sourceNo":26,"q":"Post spinal headache lasts for ?","o":["10 min","I hrs","10 days","1 week"],"a":2,"e":"Ans. is ''c'' i.e., 10 days Post dural puncture headache is due to CSF leak. Typical location is bifrontal or occipital. Headache gets worsen on sitting or upright posture and is relieved by lying down position and abdominal pressure —> The hallmark of postdural puncture headache i.e., association with body position. The onset of headache is usually 12-72 hours following the procedure, however, it may be seen almost immediately. In most cases it lasts for 7-10 days. PDPH is believed to result from leakage of CSF from a dural defect and decreased ICT. Loss of CSF at a rate faster that it can be produced causes traction on structure supporting the brain, particularly dura and tentorium. Traction on cranial nerve (particularly 6th nerve) produces diplopia. Factors that increase the incidence of PDPH are young age, female sex, Pregnancy, large bore needle and multiple punctures. Use of small bore needle can prevent PDPH . Intially conservative treatment is given which includes analgesics (NSAIDs), oral or i.v., fluids, Sumatriptan, cosyntropin, caffeine and recumbent position. If conservative treatment fails, epidural blood patch can be used. It involves injecting 15-20 ml of autologus blood into the epidural space which stop leakage of CSF by coagulation and mass effect","pyqMatches":[{"year":"2014","no":1955,"q":"Post spinal headache lasts for ?","o":["10 min","I hrs","10 days","1 week"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (699, 'Anesthesia', 'Airway Management', 'Moderate', 'Anaesthesia', 27, '{"id":699,"subject":"Anesthesia","chapter":"Airway Management","difficulty":"Moderate","source":"Anaesthesia","sourceNo":27,"q":"Laryngeal mask airway not used in ?","o":["Baby weighing < 1500gms","Pregnant Patients","Ocular Surgeries","Difficult airway"],"a":1,"e":"Ans. is `b'' i.e., Pregnant Patients Indications of LMA","pyqMatches":[{"year":"2014","no":1990,"q":"Laryngeal mask airway not used in ?","o":["Baby weighing < 1500gms","Pregnant Patients","Ocular Surgeries","Difficult airway"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (700, 'Anesthesia', 'Local Anesthesia', 'Easy', 'Anaesthesia', 28, '{"id":700,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":28,"q":"Local anaesthetic causing methemoglobinuria is?","o":["Dibucaine","Chlorprocaine","Procaine","Benzocaine"],"a":3,"e":"Ans. is ''d'' i.e., Benzocaine Important facts about LAs Chlorprocaine is the shortest acting LA. Dibucaine is the longest acting, most potent and most toxic LA. Procaine & chlorprocaine are least potent LAs. Bupivacaine is the most cardiotoxic LA (Ropivacaine is a newer bupivacaine congener with less cardiotoxicity). Levobupivacaine (The S (-) enantiomer of bupivacaine) is less cardiotoxic and less prone to cause seizure. Prilocaine and Benzocaine can cause Methaemoglobinemia Lignocaine is the most commonly used LA. Bupivacaine has the highest local tissue irritancy. Chlorprocaine is contraindicated in spinal anaesthesia as it can cause paraplegia due to presence of neurotoxic preservative sodium metabisulphite. Procaine is the LA of choice in malignant hyperthermia","pyqMatches":[{"year":"2014","no":1958,"q":"Local anaesthetic causing methemoglobinuria is?","o":["Dibucaine","Chlorprocaine","Procaine","Benzocaine"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (701, 'Anesthesia', 'Airway Management', 'Easy', 'Anaesthesia', 29, '{"id":701,"subject":"Anesthesia","chapter":"Airway Management","difficulty":"Easy","source":"Anaesthesia","sourceNo":29,"q":"Which of the following are features of pulmonary oxygen toxicity?","o":["Increased capillary endothelial permeability","Decreased mucociliary transport in airways","Inhibition of phagocytosis function of alveolar macrophages","All the above"],"a":3,"e":"Ans. is ''d'' i.e., All the above","pyqMatches":[{"year":"2014","no":2003,"q":"Which of the following are features of pulmonary oxygen toxicity?","o":["Increased capillary endothelial permeability","Decreased mucociliary transport in airways","Inhibition of phagocytosis function of alveolar macrophages","All the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (702, 'Anesthesia', 'Airway Management', 'Easy', 'Anaesthesia', 30, '{"id":702,"subject":"Anesthesia","chapter":"Airway Management","difficulty":"Easy","source":"Anaesthesia","sourceNo":30,"q":"Which of the following systems can be used to produce PEEP?","o":["Spring system","Ball valve system","Pneumatic system","All the above"],"a":3,"e":"Ans. is ''d'' i.e., All the above anesthesia by Hartigan p. 179] PEEP Valve A PEEP Valve is a device which maintains the airway at end exhalation. Spring valve system is the simplest PEEP valve system. Other valve systems for PEEP are electronic, magnetic, pneumatic and ball vale. PEEP devices may be integrated into ventilator or may be separate devices that are attached directly into anesthesia circuit, CPAP device or manual resuscitation bag.","pyqMatches":[{"year":"2014","no":1992,"q":"Which of the following systems can be used to produce PEEP?","o":["Spring system","Ball valve system","Pneumatic system","All the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (703, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 31, '{"id":703,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":31,"q":"Which of the following is contraindicated in head injury?","o":["Ketamine","Halothane","N,0","Propofol"],"a":0,"e":"Ans. is ''a'' i.e., Ketamine","pyqMatches":[{"year":"2014","no":1970,"q":"Which of the following is contraindicated in head injury?","o":["Ketamine","Halothane","N,0","Propofol"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (704, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 32, '{"id":704,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":32,"q":"Percentage of tetracaine used in eye surgery?","o":["0.5%","1%","2%","4%"],"a":0,"e":"Ans. is ''a'' i.e., 0.5% Cataract surgery can be performed using topical anaesthesia alone. Tetracaine 0.5% and Lidocaine 4% can be used. Advantages of this method is that it avoids the potential complications with retorbulbar and peribulbar injections. Dsadvantages include the potential for eye movement during surgery, increased patient anxiety, and discomfort from the microscope light","pyqMatches":[{"year":"2014","no":1960,"q":"Percentage of tetracaine used in eye surgery?","o":["0.5%","1%","2%","4%"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (705, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 33, '{"id":705,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":33,"q":"What is the pressure at which oxygen is stored?","o":["75 psi","1600 psi","760 psi","2200 psi"],"a":3,"e":"Ans. is ''d'' i.e., 2200 psi","pyqMatches":[{"year":"2014","no":1993,"q":"What is the pressure at which oxygen is stored?","o":["75 psi","1600 psi","760 psi","2200 psi"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (706, 'Anesthesia', 'Miscellaneous', 'Moderate', 'Anaesthesia', 34, '{"id":706,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anaesthesia","sourceNo":34,"q":"True about post dural headache is all except:?","o":["Orienting beveled edge needle parallel to long axis prevents it","Thin bore needle prevents it","It is more common in males","Timing of ambulation has no effect over its incidence"],"a":2,"e":"Ans. is `c'' i.e., It is more common in males FACTORS THAT INCREASE THE INCIDENCE OF HEADACHE AFTER SPINAL PUNCTURE Age : Younger, more frequent. Sex : Females > males Needle size : Larger > smaller Needle bevel : Less when the needle bevel is placed in the long axis of the neuraxis Pregnancy : More when pregnant Dural punctures : More with multiple punctures FACTORS THAT DO NOT INCREASE THE INCIDENCE OF HEADACHE AFTER SPINAL PUNCTURE Insertion and use of catheters for continuous spinal anaesthesia Timing of ambulation About option a Orienting a needle bevel parallel with the axis of the spine, such that the longitudinal fibres of the dura would more likely be separated than cut, results in a lower incidence of postspinal puncture headache.","pyqMatches":[{"year":"2014","no":1957,"q":"True about post dural headache is all except:?","o":["Orienting beveled edge needle parallel to long axis prevents it","Thin bore needle prevents it","It is more common in males","Timing of ambulation has no effect over its incidence"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (707, 'Anesthesia', 'General Anesthesia', 'Moderate', 'Anaesthesia', 35, '{"id":707,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Moderate","source":"Anaesthesia","sourceNo":35,"q":"Ketamine contraindicated in all except?","o":["Head injury","Hypertension","Asthma","Glaucoma"],"a":2,"e":"Ans. is `c'' i.e., Asthma Ketamine increases cerebral blood flow, metabolism, oxygen consumption and intracranial tension, unlike thiopentone, propofol&etomidate, which have cerebroprotectiveeffect, therefore ketamine is contraindicated in head injury, intracranial space occupying lesions and for neuroanaesthesia. Cerebrovascular responsiveness to CO2 is preserved, and reducing the arterial CO2 tension by hyperventilation attenuates the ketamine induced rise in ICT. Ketamine has direct myocardial depressant (negative ionotropic) & vasodilator effect. However, ketamine also has indirect sympathomimetic effect. Indirect sympathomimetic effect predominates over direct myocardial depressant &vasodilator effect; usual response is increased BP, cardiac output and heart rate- Cardiac 02 demand is increased. Ketamine is contraindicated in aortic aneurysm, hypertensive and ischemic heart disease. Ketamine also sensitizes the heart to adrenaline - arrhythmias may occur. As ketamine cause sympathetic stimulation, it is the intravenous anaesthetic of choice in patients with shock and hypovolemia. Ketamine increases intra-ocular tension - Contraindicated in glaucoma & open eye surgery. It is a potent bronchodilator and relieves bronchospasm - Intravenous anesthetic agent of choice in asthmatic (inhalational anaesthetic agent of choice in asthmatics is halothane) It increases uterine tone and intensity of uterine contraction - agent of choice in patients with obstetric haemorrhage and flaccid uterus. Injection of ketamine is not painful (all other i.v. inducing agents cause pain on injection).","pyqMatches":[{"year":"2014","no":1971,"q":"Ketamine contraindicated in all except?","o":["Head injury","Hypertension","Asthma","Glaucoma"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (708, 'Anesthesia', 'Local Anesthesia', 'Easy', 'Anaesthesia', 36, '{"id":708,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":36,"q":"In Bier''s block aesthetic agent given by which route?","o":["Intravenous","Peribulbar region","Retrobulbar area","Dermal"],"a":0,"e":"Ans. is ''a'' i.e., Intravenous Intravenous regional anaesthesia (IVRA) is used most often for surgery of the forearm and hand, but can also be used for distal leg and foot. First IV cannula is inserted usually in the dorsum of hand. Then tourniquet cuff is applied to proximal arm. Limb is elevated and exsanguinated with the help of an elastic bandage (Esmarch). Now tourniquet cuff is inflated above systolic pressure (so that no blood can enter in that limb and the limb remains exsanguinated). Now the local anaesthetic solution is slowly injected into cannula. The veins are filled with only local anaesthetic as there is no blood —> local anaesthetic can not be drained out form upper limb and can not enter in systemic circulation because of inflated cuff in proximal arm. The arm is anaesthetized in 6-8 minutes. Lidocaine without adrenaline is the DOC for this technique.- Goodman & Gilman Ilth/e p. 381 A few clinician prefers prilocaine over lidocaine because of its higher therapeutic index - least toxic LA. Tornique cuff deflation, premature release or failure of torniquet can cause release of LA into circulation and toxicity may occur —> So, cardiotoxic LAs like bupivacaine and etidocaine are contraindicated for Bier''s block.","pyqMatches":[{"year":"2014","no":1969,"q":"In Bier''s block aesthetic agent given by which route?","o":["Intravenous","Peribulbar region","Retrobulbar area","Dermal"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (709, 'Anesthesia', 'Airway Management', 'Hard', 'Anaesthesia', 37, '{"id":709,"subject":"Anesthesia","chapter":"Airway Management","difficulty":"Hard","source":"Anaesthesia","sourceNo":37,"q":"What is the next step in management in managing a child with difficult intubation with 4 failed attempts at intubation?","o":["Use LMA","Abandon the procedure","Try ET tube intibation again","Cricothyrotomy"],"a":0,"e":"Ans. is ''a'' i.e., Use LMA","pyqMatches":[{"year":"2014","no":1950,"q":"What is the next step in management in managing a child with difficult intubation with 4 failed attempts at intubation?","o":["Use LMA","Abandon the procedure","Try ET tube intibation again","Cricothyrotomy"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (710, 'Anesthesia', 'Miscellaneous', 'Hard', 'Anaesthesia', 38, '{"id":710,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Hard","source":"Anaesthesia","sourceNo":38,"q":"Following group of drugs is not the first line in the management of chronic pain?","o":["Opioids","Antiepileptics","Serotonergic drugs","Dopamine antagonist"],"a":3,"e":"Ans. is ''d'' i.e., Dopamine antagonist","pyqMatches":[{"year":"2014","no":2002,"q":"Following group of drugs is not the first line in the management of chronic pain?","o":["Opioids","Antiepileptics","Serotonergic drugs","Dopamine antagonist"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (711, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 39, '{"id":711,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":39,"q":"Anaesthetic of choice for day care srgery is?","o":["Thiopentone","Nitrous oxide","Propofol","Halothane"],"a":2,"e":"Ans. is ''c'' i.e., Propofol","pyqMatches":[{"year":"2014","no":1981,"q":"Anaesthetic of choice for day care srgery is?","o":["Thiopentone","Nitrous oxide","Propofol","Halothane"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (712, 'Anesthesia', 'Monitoring & Perioperative Care', 'Easy', 'Anaesthesia', 40, '{"id":712,"subject":"Anesthesia","chapter":"Monitoring & Perioperative Care","difficulty":"Easy","source":"Anaesthesia","sourceNo":40,"q":"Macintosh indicator is used for ?","o":["To assess degree of NM blockade","Localization of extradural space","To assess level of GA","To monitor respiratory depression"],"a":1,"e":"Ans. is ''b'' i.e., Localization of extradural space Various methods have been used to locate the epidural (extra dural space), most of which rely on subatmospheric pressure. These are :- Loss of resistance to air or saline (most common technique). Gutierrez''s method : A hanging drop of saline on the hub of needle is drawn in as the epidural space is entered (more reliable in thorocic than lumbar region). Odom ''s indicator : A fine-bore glass tube filled with saline and a bubble that moves in response to a drop in pressure. Macintosh''s indicator : A small rubber balloon filled with air connected to an adaptor causing it to deflate on entering the epidural space. Macintosh''s spring-loaded needle. Ultrasonic localization. Oxford epidular space detector.","pyqMatches":[{"year":"2014","no":2001,"q":"Macintosh indicator is used for ?","o":["To assess degree of NM blockade","Localization of extradural space","To assess level of GA","To monitor respiratory depression"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (713, 'Anesthesia', 'Muscle Relaxants', 'Easy', 'Anaesthesia', 41, '{"id":713,"subject":"Anesthesia","chapter":"Muscle Relaxants","difficulty":"Easy","source":"Anaesthesia","sourceNo":41,"q":"Atracurium is excreted by","o":["Renal excretion","Hepatic elimination","Nonenzymatic degradation","All of the above"],"a":2,"e":"Ans. is ''c'' i.e., Nonenzymatic degradation The unique feature of atracurium is inactivation in plasma by spontaneous nonenzymatic degradation (Hofmann elimination) in addition to that by alkaline ester hydrolysis. Consequently its duration of action is not altered in patients with hepatic / renal insufficiency or hypodynamic circulation Preferred muscle relaxant for such patients as well as for neonates and the elderly.o Atracurium is metabolised to laudanosine that is responsible for seizures. It can cause histamine release Hypotension & bronchoconstriction.","pyqMatches":[{"year":"2014","no":1985,"q":"Atracurium is excreted by","o":["Renal excretion","Hepatic elimination","Nonenzymatic degradation","All of the above"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (714, 'Anesthesia', 'Local Anesthesia', 'Easy', 'Anaesthesia', 42, '{"id":714,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":42,"q":"Local anaesthetic with prolonged action ?","o":["Procaine","Cocaine","Lidocaine","Dibucaine"],"a":3,"e":"Ans. is ''d'' i.e., Dibuca Dibucaine is the longest acting local anaesthetic Chlorprocaine is the shortest acting local anaesthetic Decreasing order of duration : - Dibucaine > Bupivacine = Tetracaine = Ropivacaine = Etidocaine > Prilocaine = Lignocaine = Mepivacaine = Cocaine > Procaine > Chlorprocaine .","pyqMatches":[{"year":"2014","no":1962,"q":"Local anaesthetic with prolonged action ?","o":["Procaine","Cocaine","Lidocaine","Dibucaine"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (715, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 43, '{"id":715,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":43,"q":"Drug used to prolong action of LA in Hypertensive pts?","o":["Clonidine","Felypressin","Dexmeditomidate","Noradrenalin"],"a":1,"e":"Ans. is ''b''.e., Felypressin","pyqMatches":[{"year":"2014","no":1963,"q":"Drug used to prolong action of LA in Hypertensive pts?","o":["Clonidine","Felypressin","Dexmeditomidate","Noradrenalin"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (716, 'Anesthesia', 'Muscle Relaxants', 'Easy', 'Anaesthesia', 44, '{"id":716,"subject":"Anesthesia","chapter":"Muscle Relaxants","difficulty":"Easy","source":"Anaesthesia","sourceNo":44,"q":"Which among the following is a depolarising muscle relaxant?","o":["Decamethonium","D tubocurarine","Doxacurium","Atracurium"],"a":0,"e":"Ans. is ''a'' i.e., Decamethonium Morgan 4th/e p. 214] See explanation-4 of session-3.","pyqMatches":[{"year":"2014","no":1983,"q":"Which among the following is a depolarising muscle relaxant?","o":["Decamethonium","D tubocurarine","Doxacurium","Atracurium"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (717, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 45, '{"id":717,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":45,"q":"Which of the following is fastest acting inhalational anaesthetic agent?","o":["Halothane","Desflurane","Sevoflurane","Isoflurane"],"a":1,"e":"Ans. is ''b'' i.e., Desflurane Blood : Gas partition coefficient (B:G cofflcient) It is the measure of solubility of the agent in the blood. Agent with low blood solubility (low B : G coefficient) will have high concentration in alveolar air as it will diffuse less through the alveolar capillary membrane because of low blood solubility. Since alveolar concentration determines the induction and recovery, induction & recovery will be fast with agent with less B : G partition coefficient; and induction & recovery will be slower with agents with high B : G partition coefficient. Desflurane has minimum B : G partition coefficient (least blood solubility) Has Fastest onset and recovery. o Methoxyflurane has maximum B : G partition coefficient (Maximum blood solubility) -4 Has slowest onset & recovery. Speed of onset & recovery in decreasing order (Increasing order of B: G partition coefficient and blood solubility):? Desflurane (0.42) > Cyclopropane (0.44) > N2O (0.47) > Sevoflurane (0.69)> Isoflurane (1.38) > Enflurane (1.8) > Halothane (2.4) > Chloroform (8) > Trilene (9) > Ether (12) > Methoxyflurane (15)","pyqMatches":[{"year":"2014","no":1972,"q":"Which of the following is fastest acting inhalational anaesthetic agent?","o":["Halothane","Desflurane","Sevoflurane","Isoflurane"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (718, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 46, '{"id":718,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":46,"q":"Current mode of analgesia best for intrapartum pain relief?","o":["Epidural analgesia","Spinal anaesthesia","Inhalational","Local analgesia"],"a":0,"e":"Ans. is ''a'' i.e., Epidural Analgesia Continuous lumbar epidural analgesia is the procedure of choice for pain relief during normal labour and vaginal delivery (Intrapartum pain).","pyqMatches":[{"year":"2014","no":1951,"q":"Current mode of analgesia best for intrapartum pain relief?","o":["Epidural analgesia","Spinal anaesthesia","Inhalational","Local analgesia"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (719, 'Anesthesia', 'Miscellaneous', 'Moderate', 'Anaesthesia', 47, '{"id":719,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anaesthesia","sourceNo":47,"q":"The most appropriate circuit for ventilating a spontaneously breathing infant during anaesthesia is?","o":["jackson Rees modification of Ayre''s T piece","Mapleson A or Magill''s circuit","Mapleson C or Waters to and fro canister","Bains circuit"],"a":0,"e":"Ans. is ''a'' i.e., Jackson Rees modification","pyqMatches":[{"year":"2014","no":1994,"q":"The most appropriate circuit for ventilating a spontaneously breathing infant during anaesthesia is?","o":["jackson Rees modification of Ayre''s T piece","Mapleson A or Magill''s circuit","Mapleson C or Waters to and fro canister","Bains circuit"],"a":0,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":1615,"q":"The most appropriate circuit for ventilating a spontaneously breathing infant during anaesthesia is?","o":["jackson Rees modification of Ayre''s T piece","Mapleson A or Magill''s circuit","Mapleson C or Waters to and fro canister","Bains circuit"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (720, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 48, '{"id":720,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":48,"q":"Characteristic EEC pattern seen in surgical tolerance stage of anesthesia is?","o":["Alpha","Beta","Delta","Theta"],"a":2,"e":"Ans. is ''c'' i.e., Delta","pyqMatches":[{"year":"2014","no":1973,"q":"Characteristic EEC pattern seen in surgical tolerance stage of anesthesia is?","o":["Alpha","Beta","Delta","Theta"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (721, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 49, '{"id":721,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":49,"q":"Supraclavicular block is used for surgery of ?","o":["Shoulder","Forearm","Arm","All"],"a":3,"e":"Ans. is D.`(A) Shoulder (B) Forearm (C) Arm","pyqMatches":[{"year":"2014","no":1964,"q":"Supraclavicular block is used for surgery of ?","o":["Shoulder","Forearm","Arm","All"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (722, 'Anesthesia', 'Miscellaneous', 'Moderate', 'Anaesthesia', 50, '{"id":722,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anaesthesia","sourceNo":50,"q":"All of the following about thiopentone are true except?","o":["It decreases ICT","It has anticonvulsant action","IV injection is painless","It can cause reflex tachycardia"],"a":2,"e":"Ans. is ''c'' i.e., IV injection is painless","pyqMatches":[{"year":"2014","no":1975,"q":"All of the following about thiopentone are true except?","o":["It decreases ICT","It has anticonvulsant action","IV injection is painless","It can cause reflex tachycardia"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (723, 'Anesthesia', 'Miscellaneous', 'Moderate', 'Anaesthesia', 51, '{"id":723,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anaesthesia","sourceNo":51,"q":"Thiopentone is not used in?","o":["Induction of anesthesia","Medically induced coma","As truth serum","As antidepressant"],"a":3,"e":"Ans. is ''d'' i.e., As antidepressant","pyqMatches":[{"year":"2014","no":1974,"q":"Thiopentone is not used in?","o":["Induction of anesthesia","Medically induced coma","As truth serum","As antidepressant"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (724, 'Anesthesia', 'Airway Management', 'Easy', 'Anaesthesia', 52, '{"id":724,"subject":"Anesthesia","chapter":"Airway Management","difficulty":"Easy","source":"Anaesthesia","sourceNo":52,"q":"IV dose of 1: 10000 concentration of epinephrine in pre term baby is?","o":["0.1m1","0.2 ml","0.3 ml","0.4 ml"],"a":1,"e":"Ans. is ''b'' i.e., 0-2 ml Epinephrine The IV dose of 1: 10,000 concentration is 0.1m1/Kg. Thus it is about 0.5ml for term baby and 0.2 ml for pre term baby. Endotracheal tube dosing is 1m1/ Kg. thus it is about 3m1 for term baby and 1 ml for preterm.","pyqMatches":[{"year":"2014","no":2000,"q":"IV dose of 1: 10000 concentration of epinephrine in pre term baby is?","o":["0.1m1","0.2 ml","0.3 ml","0.4 ml"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (725, 'Anesthesia', 'Muscle Relaxants', 'Easy', 'Anaesthesia', 53, '{"id":725,"subject":"Anesthesia","chapter":"Muscle Relaxants","difficulty":"Easy","source":"Anaesthesia","sourceNo":53,"q":"Longest acting among muscle relaxant is?","o":["Doxacurium","Rocuronium","Vecuronium","Atracurium"],"a":0,"e":"Ans. is ''a'' i.e., Doxacurium Among the given options, only doxacurium is long acting. See explanation- 4 of session- 3.","pyqMatches":[{"year":"2014","no":1984,"q":"Longest acting among muscle relaxant is?","o":["Doxacurium","Rocuronium","Vecuronium","Atracurium"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (726, 'Anesthesia', 'Monitoring & Perioperative Care', 'Easy', 'Anaesthesia', 54, '{"id":726,"subject":"Anesthesia","chapter":"Monitoring & Perioperative Care","difficulty":"Easy","source":"Anaesthesia","sourceNo":54,"q":"Warfarin to be stopped____________ days before surgery?","o":["2 to 3 days","4 to 5 days","6 to 7 days","8 to 9 days"],"a":1,"e":"Ans. is ''b'' i.e., 4 to 5 days Warfarin may increase peri- operative bleeding, except for minor procedures such as cataract surgery without bulbar blocks. No consensus exists on the optimal perioperative management of patients receiving warfarin. The usual recommendation is to withhold warfarin starting 4 to 5 days preoperatively (if the INR is between 2.0 and 3.0) to allow the INR to decrease to less than 1.5, which is a level considered safe for surgical procedures and neuraxial blockade. If the INR is greater than 3.0, it is usually necessary to withhold warfarin longer than 4 to 5 days. If the INR is measured the day before the surgical procedure and remains higher than 1.8, a small dose of vitamin K (1 to 5 mg administrated orally or subcutaneously) can reverse anticoagulation. Vitamin K has an effect within 6 to 10 hours after oral or subcutaneous administration (more predictable with oral administration), and it peaks within 24 hours to 48 hours. Administration of higher doses may lead to warfarin resistance when therapy is initiated again.","pyqMatches":[{"year":"2014","no":1999,"q":"Warfarin to be stopped____________ days before surgery?","o":["2 to 3 days","4 to 5 days","6 to 7 days","8 to 9 days"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (727, 'Anesthesia', 'Local Anesthesia', 'Easy', 'Anaesthesia', 55, '{"id":727,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":55,"q":"False about local anesthetics","o":["Prilocaine is less toxic than lignocaine","Lignocaine is used as an antiarrhythmic","Mixture of ligno + prilocaine is known as eutectic","Lidocaine is shorter acting than bupivacaine"],"a":0,"e":"Ans. is ''a'' i.e., Prilocaine is less toxic than lignocaine","pyqMatches":[{"year":"2014","no":1966,"q":"False about local anesthetics","o":["Prilocaine is less toxic than lignocaine","Lignocaine is used as an antiarrhythmic","Mixture of ligno + prilocaine is known as eutectic","Lidocaine is shorter acting than bupivacaine"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (728, 'Anesthesia', 'Monitoring & Perioperative Care', 'Easy', 'Anaesthesia', 56, '{"id":728,"subject":"Anesthesia","chapter":"Monitoring & Perioperative Care","difficulty":"Easy","source":"Anaesthesia","sourceNo":56,"q":"Most common complication of coeliac plexus block ?","o":["Hypotension","Parasthesias","Diarrhea","Pneumothorax"],"a":0,"e":"Ans. is ''a'' i.e., Hypotension Celiac plexus block The celiac plexus is situated retroperitoneally in the upper abdomen. It is at the level of T12 and L, vertebrae anterior to the crura of the diaphragm. It contains visceral afferent and efferent fibers divided from T5 to T1, by means of greater, lesser and least splanchnic nerves. Celiac plexus innervates most of the abdominal viscera, therefore this procedure blocks the nerves which come from the pancreas, liver, gall bladder, stomach, intestine, spleen, kidney and adrenal glands. A celiac plexus block can be combined with an intercostal block to provide anesthesia for intra-abdominal surgery. Because celiac plexus block results in blockade of the autonomic nervous system, this block may help to reduce stress and endocrine responses to surgery. For the same reason, the most common complication of celiac plexus block is postural hypotenstion because of blockade of lumbar sympathetic chain leading to upper abdominal vessel dilation and venous pooling. Celiac plexus block can be done by following three approaches : - Retrocrural (classic) approach, anterocrural approach and splanchnic nerve block. Celiac plexus block is given to treat intractable pain in chronic pancreatitis, gastric & pancreatic malignancies. It can be combined with an intercostal block to provide anesthesia for intra-abdomival surgery. Postural hypotension is the Most common complication of classic retrocrural and splanchnic nerve block, Where as most common complication of Anterocrural approach is transient diarrhoea","pyqMatches":[{"year":"2014","no":1965,"q":"Most common complication of coeliac plexus block ?","o":["Hypotension","Parasthesias","Diarrhea","Pneumothorax"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (729, 'Anesthesia', 'Miscellaneous', 'Moderate', 'Anaesthesia', 57, '{"id":729,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anaesthesia","sourceNo":57,"q":"True about malignant hyperthermia is all except","o":["Most common cause is Sch","Dantrolene is the drug of choice","End tidal CO, is increased","Bradycardia occurs"],"a":3,"e":"Ans. is ''d'' i.e., Bradycardia","pyqMatches":[{"year":"2014","no":1988,"q":"True about malignant hyperthermia is all except","o":["Most common cause is Sch","Dantrolene is the drug of choice","End tidal CO, is increased","Bradycardia occurs"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (730, 'Anesthesia', 'Miscellaneous', 'Hard', 'Anaesthesia', 58, '{"id":730,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Hard","source":"Anaesthesia","sourceNo":58,"q":"Elderly patient with fracture right hip anesthetic of choice","o":["Spinal/ epidural","General","Local infiltration","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Spinal/epidural","pyqMatches":[{"year":"2014","no":1952,"q":"Elderly patient with fracture right hip anesthetic of choice","o":["Spinal/ epidural","General","Local infiltration","None of the above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (731, 'Anesthesia', 'Muscle Relaxants', 'Easy', 'Anaesthesia', 59, '{"id":731,"subject":"Anesthesia","chapter":"Muscle Relaxants","difficulty":"Easy","source":"Anaesthesia","sourceNo":59,"q":"Which is a safe muscle relaxant in renal failure ?","o":["Cisatracurium","Rocuronum","Vecuronium","Succinylcholine"],"a":0,"e":"Ans. is ''a'' i.e., Cisatracurium The unique feature of atracurium and cisatracurium is inactivation in plasma by spontaneous nonenzymatic degradation (Hofman elimination) in addition to that by alkaline ester hydrolysis. Therefore both of these do not require hepatic or renal routes for elimination therefore can be used safely in hepatic and renal failure. Moreover, cisatracurium does not provoke histamine release, therefore it is preferred over atracurium.","pyqMatches":[{"year":"2014","no":1986,"q":"Which is a safe muscle relaxant in renal failure ?","o":["Cisatracurium","Rocuronum","Vecuronium","Succinylcholine"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (732, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 60, '{"id":732,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":60,"q":"Onset of post spinal headache is usually at hours after spinal anesthesia","o":["0 - 6","6-12","12 - 72","72 - 96"],"a":2,"e":"Ans. is ''c'' i.e., 12 - 72","pyqMatches":[{"year":"2014","no":1956,"q":"Onset of post spinal headache is usually at hours after spinal anesthesia","o":["0 - 6","6-12","12 - 72","72 - 96"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (733, 'Anesthesia', 'Monitoring & Perioperative Care', 'Easy', 'Anaesthesia', 61, '{"id":733,"subject":"Anesthesia","chapter":"Monitoring & Perioperative Care","difficulty":"Easy","source":"Anaesthesia","sourceNo":61,"q":"DISS is used for ?","o":["Correct application of cylinder to anaesthesia machine","To provide analgesia","To monitor BP","To monitor CVP"],"a":0,"e":"Ans. is `a'' i.e., Correct application of cylinder to anaesthesia machine","pyqMatches":[{"year":"2014","no":1989,"q":"DISS is used for ?","o":["Correct application of cylinder to anaesthesia machine","To provide analgesia","To monitor BP","To monitor CVP"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (734, 'Anesthesia', 'General Anesthesia', 'Moderate', 'Anaesthesia', 62, '{"id":734,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Moderate","source":"Anaesthesia","sourceNo":62,"q":"Drugs used for day care surgery are all except?","o":["Propofol","Sevoflurane","Doxacurium","Desflurane"],"a":2,"e":"Ans. is ''c'' i.e., Doxacurium","pyqMatches":[{"year":"2014","no":1980,"q":"Drugs used for day care surgery are all except?","o":["Propofol","Sevoflurane","Doxacurium","Desflurane"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (735, 'Anesthesia', 'Muscle Relaxants', 'Easy', 'Anaesthesia', 63, '{"id":735,"subject":"Anesthesia","chapter":"Muscle Relaxants","difficulty":"Easy","source":"Anaesthesia","sourceNo":63,"q":"Shortest acting non depolarizing muscle relaxant is?","o":["Mivacurium","Doxacuronium","Pipecurium","Vecuronium"],"a":0,"e":"Ans. is ''a'' i.e., Mivacurium Suxamethonium (succinylcholine) is the shortest acting skeletal muscle relaxant. o Mivacurium is the shortest acting nondepolarizing skeletal muscle relaxant.","pyqMatches":[{"year":"2014","no":1987,"q":"Shortest acting non depolarizing muscle relaxant is?","o":["Mivacurium","Doxacuronium","Pipecurium","Vecuronium"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (736, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 64, '{"id":736,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":64,"q":"Henrys law states that?","o":["At a constant temperature gas dissolves in solution in proportion to its partial pressure","At a constant Pressure gas dissolves in solution in proportion to its temperature","At a constant temperature gas dissolves in solution in proportion to its fat solubility","At a constant pressure gas dissolves in solution in proportion to its fat solubility"],"a":0,"e":"Ans. is ''a'' i.e., At a constant temperature gas dissolves in so lution in proportion to its partial pressure","pyqMatches":[{"year":"2014","no":1998,"q":"Henrys law states that?","o":["At a constant temperature gas dissolves in solution in proportion to its partial pressure","At a constant Pressure gas dissolves in solution in proportion to its temperature","At a constant temperature gas dissolves in solution in proportion to its fat solubility","At a constant pressure gas dissolves in solution in proportion to its fat solubility"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (737, 'Anesthesia', 'General Anesthesia', 'Moderate', 'Anaesthesia', 65, '{"id":737,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Moderate","source":"Anaesthesia","sourceNo":65,"q":"Propofol infusion syndrome all except?","o":["Occurs with infusion of propofol for 48 hours or longer","Occurs in critically ill patients","Features are nausea and vomiting","Features are cardiomyopathy, hepatomegaly"],"a":2,"e":"Ans. is ''c'' i.e., Features are nausea and vomiting Propofol infusion syndrome A lethal syndrome, associated with infusion of propofol for 48 hours or longer. Occurs in children and critically ill. Occurs as a result of failure of free fatty acid metabolism and failure of the mitochondrial respiratory chain. Features are-cardiomyopathy with acute cardiac failure, metabolic acidosis, skeletal myopathy, hyperkalemia, hepatomegaly and lipemia.","pyqMatches":[{"year":"2014","no":1976,"q":"Propofol infusion syndrome all except?","o":["Occurs with infusion of propofol for 48 hours or longer","Occurs in critically ill patients","Features are nausea and vomiting","Features are cardiomyopathy, hepatomegaly"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (738, 'Anesthesia', 'Miscellaneous', 'Moderate', 'Anaesthesia', 66, '{"id":738,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anaesthesia","sourceNo":66,"q":"Hyperbaric oxygen is not useful in?","o":["Anemia","Vertigo","Gas gangrene","Compartment Syndrome"],"a":1,"e":"Ans. is ''b'' i.e., Vertigo","pyqMatches":[{"year":"2014","no":1997,"q":"Hyperbaric oxygen is not useful in?","o":["Anemia","Vertigo","Gas gangrene","Compartment Syndrome"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (739, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 67, '{"id":739,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":67,"q":"Treatment in post operative shivering?","o":["Pethidine","Piritramide","Methadone","Pentazocine"],"a":0,"e":"Ans. is ''a'' i.e., Pethidine Post-anaesthesia shivering (PAS) Post anaesthesia (post operative) shivering occurs in 40% of patients recovering from general anaesthesia. Some time it is preceded by central hypothermia and peripheral vasoconstriction, indicating that it is a thermoregulatory mechanism Pethidine is most effective drug for treatment of PAS. Other drugs used are --clonidine, doxapram, ketanserin, alfentonil, butorphanol, chlorpromazine.","pyqMatches":[{"year":"2014","no":1996,"q":"Treatment in post operative shivering?","o":["Pethidine","Piritramide","Methadone","Pentazocine"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (740, 'Anesthesia', 'Airway Management', 'Easy', 'Anaesthesia', 68, '{"id":740,"subject":"Anesthesia","chapter":"Airway Management","difficulty":"Easy","source":"Anaesthesia","sourceNo":68,"q":"Standard method to differentiate between endotracheal and esophageal intubation is?","o":["End tidal CO2","Chest X-rays","Auscultation","Partial pressure of 02"],"a":0,"e":"Ans. is ''a'' i.e., End tidal CO2","pyqMatches":[{"year":"2014","no":1995,"q":"Standard method to differentiate between endotracheal and esophageal intubation is?","o":["End tidal CO2","Chest X-rays","Auscultation","Partial pressure of 02"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (741, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 69, '{"id":741,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":69,"q":"Anesthetic agent/s which have tocolytic effect are?","o":["Halothane","Enflurane","Isoflurane","All the above"],"a":3,"e":"Ans. is ''d'' i.e., All the above Halothane, enflurane and isoflurane produce a dose dependent decrease in uterine tone (tocolysis). Studies of isoflurane demonstrate that halogenated compounds reduce both the frequency of uterinecontractions and the interval between them.","pyqMatches":[{"year":"2014","no":1977,"q":"Anesthetic agent/s which have tocolytic effect are?","o":["Halothane","Enflurane","Isoflurane","All the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (742, 'Anesthesia', 'General Anesthesia', 'Moderate', 'Anaesthesia', 70, '{"id":742,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Moderate","source":"Anaesthesia","sourceNo":70,"q":"Following are hepatotoxic anesthetic agents except?","o":["Halothane","Chloroform","Ether","Propofol"],"a":3,"e":"Ans. is `d'' i.e., Propofol Zimmermann p. 458] Following are the groups of hepatotoxic anesthetic agents: Group I : Drugs with well known hepatotoxic potential and containing Chlorine or bromine. Eg: chloroform. Group II : Drugs which contain fluorine Eg: halothane, methoxyflurane. Desflurane, enflurane, sevoflurane, isoflurane, nitrous oxide and carbon tetrachloride are also linked with hepatotoxicity.","pyqMatches":[{"year":"2014","no":1979,"q":"Following are hepatotoxic anesthetic agents except?","o":["Halothane","Chloroform","Ether","Propofol"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (743, 'Anesthesia', 'Muscle Relaxants', 'Easy', 'Anaesthesia', 71, '{"id":743,"subject":"Anesthesia","chapter":"Muscle Relaxants","difficulty":"Easy","source":"Anaesthesia","sourceNo":71,"q":"Action of which anesthetic agent is through NMDA receptors?","o":["Xenon","NO","Succinylcholine","Etomidate"],"a":0,"e":"Ans. is ''a'' i.e., Xenon Xenon It exerts anaesthetic action by non competitive blockade of NMDA receptors. Xenon has been used as a general anesthetic. Xenon interacts with many different receptors and ion channels and like many theoretically","pyqMatches":[{"year":"2014","no":1978,"q":"Action of which anesthetic agent is through NMDA receptors?","o":["Xenon","NO","Succinylcholine","Etomidate"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (744, 'Anesthesia', 'Muscle Relaxants', 'Moderate', 'Anaesthesia', 72, '{"id":744,"subject":"Anesthesia","chapter":"Muscle Relaxants","difficulty":"Moderate","source":"Anaesthesia","sourceNo":72,"q":"All of the following are Nondepolarising muscular blockers except","o":["Pancuranium","Dexacurium","D-Tubocurarine","Succinylcholine"],"a":3,"e":"Ans. is ''d'' i.e., Succinylcholine","pyqMatches":[{"year":"2014","no":1982,"q":"All of the following are Nondepolarising muscular blockers except","o":["Pancuranium","Dexacurium","D-Tubocurarine","Succinylcholine"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (745, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 73, '{"id":745,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":73,"q":"In epidural anaesthesia drug is injected ?","o":["Outside the dura","Inside the duramater","Inside arachnoidmater","Inside piamater"],"a":0,"e":"Ans. is ''a'' i.e., Outside the dura","pyqMatches":[{"year":"2014","no":1961,"q":"In epidural anaesthesia drug is injected ?","o":["Outside the dura","Inside the duramater","Inside arachnoidmater","Inside piamater"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (746, 'Anesthesia', 'Miscellaneous', 'Moderate', 'Anaesthesia', 74, '{"id":746,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anaesthesia","sourceNo":74,"q":"Celiac plexus block all the following is true except ?","o":["Relieved pain from gastric malignancy","Cause hypotention","Can be used to provide anesthesia for intra abdominal surgery","Can be given only by retrocrural (classic) approach"],"a":3,"e":"Ans. is ''d'' i.e., Can be given only by retrocrural (classic) approach Celiac plexus block can be done by following three approaches : Retrocrural (classic) approach, anterocrural approach and splanchnic nerve block. See explanation- 4 of session- 8 of Anaesthesia of All India 2014-15 pattern of this book.","pyqMatches":[{"year":"2012","no":83,"q":"Celiac plexus block all the following is true except ?","o":["Relieved pain from gastric malignancy","Cause hypotention","Can be used to provide anesthesia for intra abdominal surgery","Can be given only by retrocrural (classic) approach"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (747, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 75, '{"id":747,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":75,"q":"Best uterine relaxation is seen with ?","o":["Chloroform","Nitrous oxide","Ether","Halothane"],"a":3,"e":"Ans. ''d'' i.e., Halothane Halogenated inhalational anaesthetic agents like halothane are powerful tocolytic agents. Halothane is anaesthetic of choice for internal version and manual removal of placenta.","pyqMatches":[{"year":"2015","no":1616,"q":"Best uterine relaxation is seen with ?","o":["Chloroform","Nitrous oxide","Ether","Halothane"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (748, 'Anesthesia', 'Muscle Relaxants', 'Easy', 'Anaesthesia', 76, '{"id":748,"subject":"Anesthesia","chapter":"Muscle Relaxants","difficulty":"Easy","source":"Anaesthesia","sourceNo":76,"q":"Dibucain number refers to ?","o":["Ach cholinestrase activity derangement","Potency of muscle relaxants","Potency of general anaesthetics","None"],"a":0,"e":"Ans. is ''a'' i.e., Ach chlinestrase activity derangement Dibucain number : Dibucain (a local anaesthetic) inhibits 80% of normal pseudocholinesterase and 20% of atypical (non-functional) pseudocholinesterase. Therefore normal dibucain number is 70- 80%. Dibucain number is used to measure the activity of atypical pseudocholinesterase.","pyqMatches":[{"year":"2012","no":1396,"q":"Dibucain number refers to ?","o":["Ach cholinestrase activity derangement","Potency of muscle relaxants","Potency of general anaesthetics","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (749, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 77, '{"id":749,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":77,"q":"Percentage of lidocaine in Eutectic mixture -","o":["1%","2.5%","5%","10%"],"a":1,"e":"Ans. is ''b'' i.e., 2-5% Eutectic mixture of local Anaesthetics This is unique topical preparation which can anaesthetise intact skin. It is a mixture of 2.5% lidocaine and 2.5 prilocaine. It acts slowly and the cream must held in contact with skin for at least 1 hour. EMLA is used : to make venepuncture painless especially in children, and for procedure like skin grafting & circumcision. As systemic absorption of prilocaine can cause methemoglobinemia, EMLA should not be used on mucocutaneous membrane or in very small child.","pyqMatches":[{"year":"2014","no":1959,"q":"Percentage of lidocaine in Eutectic mixture","o":["1%","2.5%","5%","10%"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (750, 'Anesthesia', 'Local Anesthesia', 'Easy', 'Anaesthesia', 78, '{"id":750,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":78,"q":"Long acting local anaesthetic ?","o":["Procaine","Lignocaine","Prilocaine","Dibucaine"],"a":3,"e":"Ans. is ''d'' i.e., Dibucaine","pyqMatches":[{"year":"2015","no":1629,"q":"Long acting local anaesthetic ?","o":["Procaine","Lignocaine","Prilocaine","Dibucaine"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (751, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 79, '{"id":751,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":79,"q":"Hepatotoxic inhalational agent ?","o":["Halothane","Enflurane","Desflurane","Sevoflurane"],"a":0,"e":"Ans. is ''a'' i.e., Halothane All inhalational agent cause mild hepatotoxicity by decreasing hepatic blood flow. Isoflurane is the agent of choice in liver disease as it has least effect on Hepatic blood flow. Direct hepatotoxicity (Hepatitis,Hepatic necrosis) is caused by :- Halothane, Chloroform, trilene, methoxyflurane","pyqMatches":[{"year":"2013","no":1717,"q":"Hepatotoxic inhalational agent ?","o":["Halothane","Enflurane","Desflurane","Sevoflurane"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (752, 'Anesthesia', 'General Anesthesia', 'Hard', 'Anaesthesia', 80, '{"id":752,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Hard","source":"Anaesthesia","sourceNo":80,"q":"A patient after giving inhalational anaestheia developed fulminant hepatitis, patient was exposed to same drug previously. Which is the drug?","o":["Halothane","N20","Enflurane","Isoflurane"],"a":0,"e":"Ans. is ''a'' i.e., Halothane Halothane It is a volatile liquid with sweet odour, nonirritating and noninflammable. It is a potent anaesthetic with poor analgesic and muscle relaxant properties. Halothane causes direct depression of myocardial contractility by reducing intracellular Ca+2. It causes fall in BP and CO. Heart rate decreases due to vagal stimulation. It tends to sensitize the heart to arrhythmogenic action of adrenaline —* contraindicated in pheochromocytoma. It causes greater depression of respiration and ventilation perfusion mismatch. It dilates the bronchi —> inhalation agent of choice in asthmatics (intravaneous anaesthetic of choice in asthmatics is ketamine). It is a hepatotoxic drug and can also cause malignant hyperthermia (Succinylcholine accentuate it). Recovery is smooth and reasonably quick. It causes postanaesthetic shivering and chills. It inhibits intestinal and uterine contractions —> agent of choice for assisting external or internal version during late pregnancy. Because its uterine relaxant action it is contraindicated during labour. It is particularly suitable for induction and maintenance in children and as maintenance anaesthetic in adults.","pyqMatches":[{"year":"2013","no":1718,"q":"A patient after giving inhalational anaestheia developed fulminant hepatitis, patient was exposed to same drug previously. Which is the drug?","o":["Halothane","N20","Enflurane","Isoflurane"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (753, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 81, '{"id":753,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":81,"q":"Least MAC is of which inhalational agent?","o":["Xenon","Halothane","Sevoflurane","Isoflurane"],"a":0,"e":"Ans. is ''a'' i.e., Xenon Agent MAC (%) Ether Halothane Enflurane Isoflurane Desflurane Sevoflurane Nitrous oxide 1.9 0.75 1.68 1.2 6.0 2.0 105 \"Xenon has MAC of 71%\" — Morgan Methoxyflurone (MAC = 0.16%) > Trilene (0.2%) > Halothane (0.74%) > Chloroform (0.8%) > Isoflurane (1.15%)> Entlurane (1.68%) > Ether (1.92%) > Sevoflurane (2.0%) > Desflurane (6,0%) > Cyclopropane (9.2%) > N20 (104%).","pyqMatches":[{"year":"2013","no":1714,"q":"Least MAC is of which inhalational agent?","o":["Xenon","Halothane","Sevoflurane","Isoflurane"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (754, 'Anesthesia', 'Muscle Relaxants', 'Easy', 'Anaesthesia', 82, '{"id":754,"subject":"Anesthesia","chapter":"Muscle Relaxants","difficulty":"Easy","source":"Anaesthesia","sourceNo":82,"q":"In pseudocholinesterase deficiency, drug to be used cautiously is-","o":["Barbiturate","Succinylcholine","Halothane","Gallamine"],"a":1,"e":"Ans. is ''b'' i.e., Succinylcholine Cholinesterase At cholinergic nerve endings, in erythrocytes, and gray matter there is an enzyme that specfically destroys acetylcholine, true cholinesterase or acetylcholinestrase. In various tissues, especially in plasma, liver, white matter & intestine, there are other esterases which are not specific for acetylcholine but which also destroy other esters, these are called nonspecific or pseudocholinesterase or butyrylcholinesterase. The drugs hydrolyzed by pseudocholinesterase are (Miller 5th/e p. 419, 420)","pyqMatches":[{"year":"2013","no":1711,"q":"In pseudocholinesterase deficiency, drug to be used cautiously is","o":["Barbiturate","Succinylcholine","Halothane","Gallamine"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (755, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 83, '{"id":755,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":83,"q":"Blood : Gas partition coefficient is a measure of ?","o":["Potency of anaesthetic agent","Speed of induction and recovery","Lipid solubility of agent","None"],"a":1,"e":"Ans. is ''b'' i.e., Speed of induction and recovery Minimum alveolar concentration (MAC) —> Measure of potency. Blood : Gas partition coefficient Blood solubility of anaesthetic agent and determines the speed of induction & recovery. Oil : Gas partition coefficient -4 Lipid solubility of anaesthetic agent and is related to potency of anaesthetic agent.","pyqMatches":[{"year":"2013","no":1713,"q":"Blood : Gas partition coefficient is a measure of ?","o":["Potency of anaesthetic agent","Speed of induction and recovery","Lipid solubility of agent","None"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2015","no":1623,"q":"Blood : Gas partition coefficient is a measure of ?","o":["Potency of anaesthetic agent","Speed of induction and recovery","Lipid solubility of agent","None"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2013","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (756, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 84, '{"id":756,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":84,"q":"Inhalational agent of choice for neurosurgery ?","o":["Halothane","Enflurane","Isoflurane","N20"],"a":2,"e":"Ans. is ''c'' i.e., Isoflurane Anaesthetic agents of choice for vaous conditions Day care : Ischemic heart disease : Congenital heart disease Left to right shunt : Right to left shunt : CHF : Shock To produce delibrate hypotenion Epilepsy : For electroconvulsive therapy : Thyrotoxicosis : Cardiac surgery : Neurosurgery : Propofol Etomidate Isoflurane Ketamine Ketamine Ketamine Isoflurane Thiopentone Methohexitone Thiopentone Isoflurane Isoflurane","pyqMatches":[{"year":"2013","no":1719,"q":"Inhalational agent of choice for neurosurgery ?","o":["Halothane","Enflurane","Isoflurane","N20"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (757, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 85, '{"id":757,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":85,"q":"Regarding propofol, which one of the following is false?","o":["It is used as an intravenous induction agent","It causes severe vomiting","It is painful on injecting intravenously","It has no muscle relaxant property"],"a":1,"e":"Ans. is ''b'' i.e., It causes severe vomiting Propofol Propofol is a milky white powder that is preservative free; therefore, it must be used within 6 hours. It is an oil based preparation, therefore injection is painful. Propofol is the most frequently used intravenous anaesthetic today. —Miller 6thie - 318 It can be used for both induction as well as maintenace. It does not possess anticonvulsive action (unlike thiopentone). It causes fall in BP and bradycardia. Like thiopental it does not possess muscle relaxant action. Propofol possess significant antiemetic and antipruritic action.→Miller 6th/e - 324 Propofol decreases polymorphonuclear leukocyte chemotoxis but not aherence, phagocytosis and killing (Thiopentone blocks all these) —) increased life threatning infections. Propofol is particularly suitable for outpatient surgery. Intermittent injection or continuous infusion of propofol is frequently used for total Lv. anaesthesia (TINA) when supplemented by fentanyl. It is anaesthetics of choice for intubation in ICU and for patients with malignant hyperthermia. Side effects - pain on injection, myoclonus, apnea, L BP and rarely thrombophlebitis. Propofol infusion syndrome","pyqMatches":[{"year":"2013","no":1723,"q":"Regarding propofol, which one of the following is false?","o":["It is used as an intravenous induction agent","It causes severe vomiting","It is painful on injecting intravenously","It has no muscle relaxant property"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (758, 'Anesthesia', 'Miscellaneous', 'Moderate', 'Anaesthesia', 86, '{"id":758,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anaesthesia","sourceNo":86,"q":"Not a sign of stellate ganglion block?","o":["Miosis","Exopthalomos","Nasal congestion","Conjunctival redness"],"a":1,"e":"Ans. is ''b'' i.e., Exopthalomos There is enophthalmos (not exophthalmos) Stellate ganglion block Stellate ganglion is formed by fusion of lower cervical and first thoracic ganglion. It is blocked anterior to the tubercle of transverse process of C6 vertebra i.e., chassaignac tubercle at the level of cricoid cartilage. Signs of successful block are : - Horner syndrome (miosis, ptosis, anhydrosis, enophthalmos, absence of ciliospinal reflex), flushing of face, conjuctival congestion, Nasal stuffiness (Gutman''s sign), Injection of tympanic membrane (muller''s syndrome), Increased skin temprature and lacrimation. Stellate ganglion block is indicated in : -","pyqMatches":[{"year":"2013","no":1737,"q":"Not a sign of stellate ganglion block?","o":["Miosis","Exopthalomos","Nasal congestion","Conjunctival redness"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (759, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 87, '{"id":759,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":87,"q":"The term \"balanced anaesthesia\" has been given by?","o":["Simpson","Fischer","Lundy","Mortan"],"a":2,"e":"Ans. is ''c'' i.e., Lundy Term ''balanced anaesthesia'' was introduced by Lundy in 1926. Balanced anaesthesia The cardinal feature of general anaesthetics are : ?","pyqMatches":[{"year":"2013","no":1700,"q":"The term \"balanced anaesthesia\" has been given by?","o":["Simpson","Fischer","Lundy","Mortan"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (760, 'Anesthesia', 'Monitoring & Perioperative Care', 'Easy', 'Anaesthesia', 88, '{"id":760,"subject":"Anesthesia","chapter":"Monitoring & Perioperative Care","difficulty":"Easy","source":"Anaesthesia","sourceNo":88,"q":"High spinal anaesthesia is associated with?","o":["Decreased BP & decreased heart rate","Increased BP & decreased heart rate","Decreased BP & increased heart rate","Increased BP & increased heart rate"],"a":0,"e":"Ans. is ''a'' i.e., Decreased BP & decreased heart rate Spinal anesthesia ascending into the cervical levels (high spinal anesthesia) causes severe hypotension, bradycardia and respiratory insufficiency.Complications of spinal anaesthesia Intraoperative Postoperative Hypotension (mostcommon) Bradycardia10th Respiratorydepression Cardiac arrest Hypothermia in elderly Haedache (post dural puncture headach) - most common Cranial nerve palsies (any cranial nerve except the 1st,9th & most commonly 6th nerve is involved) Cauda equina equina syndrome Arachnoiditis","pyqMatches":[{"year":"2013","no":1739,"q":"High spinal anaesthesia is associated with?","o":["Decreased BP & decreased heart rate","Increased BP & decreased heart rate","Decreased BP & increased heart rate","Increased BP & increased heart rate"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (761, 'Anesthesia', 'Local Anesthesia', 'Easy', 'Anaesthesia', 89, '{"id":761,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":89,"q":"Eutectic mixture of local anaesthetic (EMLA) cream is","o":["Bupivacaine 2.0% + Prilocaine 2.5%","Lidocaine 2.5% + Prilocaine 2.5%","Lidocaine 2.5% + Prilocaine 5%","Bupivacaine 0.5% + Lidocaine 2.5%"],"a":1,"e":"Ans. is ''b'' i.e., Lidocaine 2.5% + Prilocaine 2.5% Eutectic mixture of local anaesthetic (EMLA) This is unique topical preparation which can anaesthetise intact skin. It is a mixture of 2.5% lidocaine and 2.5 prilocaine. It acts slowly and the cream must held in contact with skin for at least 1 hour. EMLA is used : to make venepuncture painless especially in children, and for procedure like skin grafting & circumcision. As systemic absorption of prilocaine can cause methemoglobinemia, EMLA should not be used on mucocutaneous membrane or in very small child.","pyqMatches":[{"year":"2013","no":1735,"q":"Eutectic mixture of local anaesthetic (EMLA) cream is","o":["Bupivacaine 2.0% + Prilocaine 2.5%","Lidocaine 2.5% + Prilocaine 2.5%","Lidocaine 2.5% + Prilocaine 5%","Bupivacaine 0.5% + Lidocaine 2.5%"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (762, 'Anesthesia', 'Local Anesthesia', 'Easy', 'Anaesthesia', 90, '{"id":762,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":90,"q":"Which anaesthetic belongs to ester group?","o":["Procaine","Times New Roman","Lignocaine","Propofol"],"a":0,"e":"Ans. is ''a'' i.e., Procaine Esters (aminoesters) :- Procaine, chlorprocaine, tetracaine (amethocaine), Benzocaine, Cocaine. Amides (aminoamides) Lignocaine, Mepivacaine, Prilocaine, Bupivacaine, Etidocaine, Ropivacaine , Dibucaine.","pyqMatches":[{"year":"2013","no":1709,"q":"Which anaesthetic belongs to ester group?","o":["Procaine","Times New Roman","Lignocaine","Propofol"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (763, 'Anesthesia', 'Miscellaneous', 'Moderate', 'Anaesthesia', 91, '{"id":763,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anaesthesia","sourceNo":91,"q":"The latest AHA 2010 for CPCR in basic life support by two individuals for cardiac external massage & ventilation in adult is?","o":["30-2","15-1","15-2","30-1"],"a":0,"e":"Ans. is ''a'' i.e., 30-2","pyqMatches":[{"year":"2013","no":1747,"q":"The latest AHA 2010 for CPCR in basic life support by two individuals for cardiac external massage & ventilation in adult is?","o":["30-2","15-1","15-2","30-1"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (764, 'Anesthesia', 'Local Anesthesia', 'Easy', 'Anaesthesia', 92, '{"id":764,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":92,"q":"Best local anaesthetic for ophthalmic surgery is","o":["Tetracaine","Prilocaine","Procaine","Bupivacaine"],"a":3,"e":"Ans. is ''d'' i.e., Bupivacaine The choice of local anaesthetic for ocular surgery varies. But lidocaine (2%) and bupivacaine (0.5-0.75%) are used most commonly. Generally the use of 1:1 mixture of 2% lidocaine (xylocaine) and 0.50% bupivacaine along with adrenaline and hyaluronidase in facial, retrobulbar and peribulbar blocks is common.","pyqMatches":[{"year":"2013","no":1741,"q":"Best local anaesthetic for ophthalmic surgery is","o":["Tetracaine","Prilocaine","Procaine","Bupivacaine"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (765, 'Anesthesia', 'Local Anesthesia', 'Easy', 'Anaesthesia', 93, '{"id":765,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":93,"q":"Percentage of adrenaline with lignocaine for local infilteration is?","o":["1:1000","1:10000","1:100","1:50000"],"a":3,"e":"Ans. is ''d'' i.e., 1:50000 The most common concentrations of epinephrine combined with local anaesthetics are 1:50,000 (0.02 mg/ml), 1:100,000 (0.01 mg/ml) and :200000 (0.005 mg/ml). The 1:50000 concentration is manufactured in combination with 2% lidocaine. The 1:100,000 concentration is manufactured in combination with 2% lidocaine and 4% articaine. The 1:200,000 concentration is manufacture in combination with 4% prilocaine, 4% articaine and 0.5% bupivacaine","pyqMatches":[{"year":"2013","no":1742,"q":"Percentage of adrenaline with lignocaine for local infilteration is?","o":["1:1000","1:10000","1:100","1:50000"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (766, 'Anesthesia', 'Local Anesthesia', 'Easy', 'Anaesthesia', 94, '{"id":766,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":94,"q":"Local anaesthesia causing methemoglobinemia ?","o":["Procaine","Prilocaine","Etodicaine","Ropivacaine"],"a":1,"e":"Ans. is ''b'' i.e., Prilocaine Prilocaine and benzocaine can cause methemoglobinemia. Important facts Chlorprocaine is the shortest acting LA. Dibucaine is the longest acting, most potent and most toxic LA. Bupivacaine is the most cardiotoxic LA (Ropivacaine is a newer bupivacaine congener with less cardiotoxicity). o Levobupivacaine (The S (-) enantiomer of bupivacaine) is less cardiotoxic and less prone to cause seizure. o Prilocaine can cause Met haemoglobinemia. Lignocaine is the most commonly used LA. Bupivacaine has the highest local tissue irritancy. Chlorprocaine is contraindicated in spinal anaesthesia as it can cause paraplegia due to presence of neurotoxic preservative sodium metabisulphite. Procaine is the LA of choice in malignant hyperthermia","pyqMatches":[{"year":"2013","no":1736,"q":"Local anaesthesia causing methemoglobinemia ?","o":["Procaine","Prilocaine","Etodicaine","Ropivacaine"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (767, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 95, '{"id":767,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":95,"q":"Intraocular pressure is increased by which anaesthetic?","o":["Ketamine","Propofol","N20","Isoflurane"],"a":0,"e":"Ans. is ''a'' i.e., Ketamine","pyqMatches":[{"year":"2013","no":1727,"q":"Intraocular pressure is increased by which anaesthetic?","o":["Ketamine","Propofol","N20","Isoflurane"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (768, 'Anesthesia', 'Muscle Relaxants', 'Hard', 'Anaesthesia', 96, '{"id":768,"subject":"Anesthesia","chapter":"Muscle Relaxants","difficulty":"Hard","source":"Anaesthesia","sourceNo":96,"q":"A 6 year old boy taken for ophthalmic examination under anaesthesia. His father told that he has lower limb weakness & his elder brother died at 14 years of age. Which anaethetic drug has to be avoided-","o":["Succinylcholine","Pancuronium","Atracurium","Dexacurium"],"a":0,"e":"Ans. is ''a'' i.e., Succinylcholine Succinylcholine SCh is a depolarising skeletal muscle relaxant. It causes sustained partial depolarization of muscle end plate —> intially produce twitching and fasciculation followed by flaccid paralysis. It is the shortest and fastest acting skeletal muscle relaxant. It is the only muscle relaxant which stimulate autonomic ganglia and vagus. SCh is the most commonly used muscle relaxant for passing endotracheal tube (mivacurium and rocuronium are alternatives). SCh is rapidly hydrolysed by plasma cholinesterase, some patients have genetically determined abnormality or deficiency of pseudocholinesterase, in them, SCh causes phase II block. It can cause muscle fasiculations and soreness, change in BP and HR, arrythmia, histamine release and IC efflux from muscles. Dangerous hyperkalemia can occur in patients with burn, crush injury, muscular dystrophy, GB. Syndrome, paraplegia or hemiplagia, mysthenia gravis and rhabdomyolysis contraindicated in such patients. o It can accentuate malignant hyperthermia caused by halothane. SCh causes increase in all pressures —> inraocular, intracranial, BP, and intrabdominal —> contraindicated in glaucoma, head injury.","pyqMatches":[{"year":"2013","no":1712,"q":"A 6 year old boy taken for ophthalmic examination under anaesthesia. His father told that he has lower limb weakness & his elder brother died at 14 years of age. Which anaethetic drug has to be avoided","o":["Succinylcholine","Pancuronium","Atracurium","Dexacurium"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (769, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 97, '{"id":769,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":97,"q":"Critical temperature of oxygen is?","o":["20","118","36.5","400C"],"a":1,"e":"Ans. is ''b'' i.e., -118","pyqMatches":[{"year":"2013","no":1707,"q":"Critical temperature of oxygen is?","o":["20","118","36.5","400C"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (770, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 98, '{"id":770,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":98,"q":"Disadvantage of ketamine is?","o":["Increased heart rate","Increased ICT","Delirium","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above When administered to adult patients as a sole anaesthetic agent, ketamine frequently cause emergence reaction characterized by anxiety, hallucination, delirium. Moreover, ketamine shows cardiovascular stimulant property (increases heart rate and BP), increases salivary and bronchial secretions, and may increase intracranial, intraocular and pulmonary pressure. All of these features have been advocated as limitations for its usefulness.","pyqMatches":[{"year":"2013","no":1728,"q":"Disadvantage of ketamine is?","o":["Increased heart rate","Increased ICT","Delirium","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (771, 'Anesthesia', 'Muscle Relaxants', 'Moderate', 'Anaesthesia', 99, '{"id":771,"subject":"Anesthesia","chapter":"Muscle Relaxants","difficulty":"Moderate","source":"Anaesthesia","sourceNo":99,"q":"All are false about N20 except?","o":["Least potent","Good muscle relaxant","Lighter than air","No diffusion hypoxia"],"a":0,"e":"Ans. is ''a'' i.e., Least potent Nitrous oxide N2Q It is colourless, odourless, heavier than air, nonirritating and noninflammable gas. o It is also called laughing gas. MAC is 105% (least potent) - even pure N20 at 1 atmospheric pressure can not produce adequate anaesthesia. o It has good analgesic but poor muscle relaxant activity. It is supplied under pressure in blue coloured steel cyclinders. It has very low blood solubility —> induction is quick and smooth with rapid recovery. Second gas effect and diffusion hypoxia occur with N20 only. N20 is generally used as a carrier and adjuvant to other anaesthetics —> A mixture of 70% N20 + 25 - 30% 02+ 0.2 - 2% another potent anaesthetic is employed for most of the surgical procedures. Entonox is a mixture of 50% N20 and 50% 02. It has little effect on respiration, heart and BP. It can cause bone marrow depression and vit B12 deficiency. N20 is the only anaesthetic reported to produce hematologic toxicity and neurotoxicity with long term administration. Both toxicities are the result of the interaction of N20 with vit B12. Complete bone marrow failure can be expected after several days of continuous exposure. Bone marrow changes are preventable by pretreating patients with large doses of folinic acid. Other manifestations of vit B 12 deficiency eg. megaloblastic anemia, subacute combined degeneration of cord may also occur. Methemoglobinemia and laryngospasm may occur. It is contraindicated in patients with air cavities like pneumothorax, pneumoperitoneum and volvulus —> expansion and increase in pressure occur.","pyqMatches":[{"year":"2013","no":1716,"q":"All are false about N20 except?","o":["Least potent","Good muscle relaxant","Lighter than air","No diffusion hypoxia"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (772, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 100, '{"id":772,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":100,"q":"Which anaesthetic is contraindicated in renal failure?","o":["Isoflurane","Desflurane","Halothane","Methoxyflurne"],"a":3,"e":"Ans. is ''d'' i.e., Methoxyflurne Methoxyflurane It was most potent inhalation agent (least MAC), but not used not (now Halothane is most potent). o It should not be used in closed circuit (reacts with rubber tubing of the losed circuit). It has slowest onset & recovery (however now ether has slowest onset & recovery as methoxyflurane is not used). o Boiling point is more than water (104°C). Intrarenal metabolism of methoxyflurane and subsequent intrarenal production of fluoride ion is the significant cause of methoxyflurane renal toxicity. It can cause high output renal failure and hepatotoxicity","pyqMatches":[{"year":"2013","no":1729,"q":"Which anaesthetic is contraindicated in renal failure?","o":["Isoflurane","Desflurane","Halothane","Methoxyflurne"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (773, 'Anesthesia', 'Airway Management', 'Easy', 'Anaesthesia', 101, '{"id":773,"subject":"Anesthesia","chapter":"Airway Management","difficulty":"Easy","source":"Anaesthesia","sourceNo":101,"q":"Conscious sedation is ?","o":["CNS depression with uncociousness","Sedation with inability to respond to command","Sedation with ability to respond to command","Any of the above"],"a":2,"e":"Ans. is ''c'' i.e., Sedation with ability to respond to command Conscious sedation is a technique in which drugs are used to produce a state of CNS depression (but not unconsciousness), enabling surgical procedure to be carried out while maintaining communication with the patient who is able to respond purposefully to commands and maintain a patent airway throughout. The protective airway reflexes are not lost, therefore conscious sedation is safer. However, by itself, it is not able to suppress pain of dental procedures; local anaesthetic must be injected in addition. Drugs used for conscious sedation are -","pyqMatches":[{"year":"2013","no":1745,"q":"Conscious sedation is ?","o":["CNS depression with uncociousness","Sedation with inability to respond to command","Sedation with ability to respond to command","Any of the above"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (774, 'Anesthesia', 'Airway Management', 'Easy', 'Anaesthesia', 102, '{"id":774,"subject":"Anesthesia","chapter":"Airway Management","difficulty":"Easy","source":"Anaesthesia","sourceNo":102,"q":"During rapid induction of anesthesia ?","o":["Sellick''s maneuver is not required","Pre-oxygenation is mandatory","Suxamethonium is contraindicated","Patient is mechanically ventilated before endotracheal intubation"],"a":1,"e":"Ans. is ''b'' i.e., Pre-oxygenation is mandatory During rapid sequence induction preoxygenation is done for full 3 minutes. Sch is the muscle relaxant of choice for intubation. Sallieck''s maneuver is done to prevent aspiration. Manual ventilation before intubation is avoided as this inflates the stomach and encourages regurgitation & aspiration. Rapid sequence anaesthesia When anaesthesia is given for emergency surgery, it is called a \"rapid sequence anaesthesia\". The patients have full stomach because there is no starvation for anaesthesia (it is an emergency surgery) and gastric emptying is delayed due to trauma, acute abdomen. Therefore, the objective of rapid sequence anaesthesia is to secure the airway rapidly and prevent aspiration of gastric contents. Procedure of rapid sequence has following steps : - Li The patient is preoxygenatedfor full 3 minutes. Intravenous induction agent (thiopentone or propofol) is given. Sellick''s maneuver (cricoid/pressure) is done to prevent aspiration. After ensuring the correct position of tube cricoid pressure is released and maintenance anaesthesia (NCO 66%, 02% 33%, & inhalational agent) is given. A non-depolarizing blocker is now added. Suxamethenium (succinylcholine) is given as it quickly relaxes the laryngeal muscles so that rapid intubation can be done. Not done during rapid sequence anaesthesia : ?","pyqMatches":[{"year":"2013","no":1730,"q":"During rapid induction of anesthesia ?","o":["Sellick''s maneuver is not required","Pre-oxygenation is mandatory","Suxamethonium is contraindicated","Patient is mechanically ventilated before endotracheal intubation"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (775, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 103, '{"id":775,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":103,"q":"Who coined term anaesthesia ?","o":["Morton","Holmes","Morgan","Priestly"],"a":0,"e":"Ans. is ''a'' i.e., Morton Second gas effect and diffusion hypoxia In initial part of induction, diffusion gradient from alveoli to blood is high and larger quantity of anaesthetic is entering blood. If the inhaled Concentration of anaesthetic is high (eg N20), Substantial loss of alveolar gas volume will occur and it creates negative intralveolar pressure that leads to removal of more gas from cylinder to alveoli --> Concentration effect. If another inhalation agent is (eg Halothane) is being given at the same time, it also will be delivered to lung from the cylinder (due to negative intraalveolar pressure) —> Second gas effect. During recovery reverse occurs - N20 having low blood solubility, rapidly diffuses into alveoli and dilutes the alveolar air —> partial pressure of oxygen in alveoli is reduced. The resulting hypoxia is known as diffusion hypoxia. Diffusion hypoxia can be prevented by continuing 100% 02 inhalation for a few minutes after discontinuing N20, instead of straight away switching over to air. Remember Concentration effect and secondary gas effect during induction. Diffusion hypoxia —> during recovering. All these occur with N20 only","pyqMatches":[{"year":"2013","no":1702,"q":"Who coined term anaesthesia ?","o":["Morton","Holmes","Morgan","Priestly"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (776, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 104, '{"id":776,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":104,"q":"Drug used for emergency intubation is ?","o":["Propofol","Ketamine","Eomidate","None"],"a":0,"e":"Ans. is ''a'' i.e., Propofol Emergency intubation in anaesthesia refers to rapid sequence anaesthesia (or rapid sequence intubation). Any inducing agent can be used, but thiopental and propofol are the preferred agent.","pyqMatches":[{"year":"2013","no":1731,"q":"Drug used for emergency intubation is ?","o":["Propofol","Ketamine","Eomidate","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (777, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 105, '{"id":777,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":105,"q":"Maximum global warming is by?","o":["Desflurane","Isoflurane","Sevoflurane","Halothane"],"a":0,"e":"Ans. is ''a'' i.e., Desflurane Desflurane is a greenhouse gas. It causes maximum global warming. Global warming potential (as an equal amount of O2) Isoflurane 210 times Sevoflurane 510 times Desflurane 1620 times","pyqMatches":[{"year":"2013","no":1721,"q":"Maximum global warming is by?","o":["Desflurane","Isoflurane","Sevoflurane","Halothane"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (778, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 106, '{"id":778,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":106,"q":"Which anaesthetic drug contributes to green house effect?","o":["Enflurane","Desflurane","Sevoflurane","Halothane"],"a":1,"e":"Ans. is ''b'' i.e., Desflurane","pyqMatches":[{"year":"2013","no":1722,"q":"Which anaesthetic drug contributes to green house effect?","o":["Enflurane","Desflurane","Sevoflurane","Halothane"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (779, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 107, '{"id":779,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":107,"q":"Most commonly used approach of brachial plexus block?","o":["Interscalene","Supraclavicular","Infraclavicular","Axillary"],"a":1,"e":"Ans. is `B'' i.e., Supraclavicular Brachial plexus block This is the second most commonly practised block after central neuraxial block (spinal & epidural anaesthesia). Brachial plexus block is used for upper limb surgeries. Brachial plexus can be blocked by 4 approaches : -","pyqMatches":[{"year":"2013","no":1738,"q":"Most commonly used approach of brachial plexus block?","o":["Interscalene","Supraclavicular","Infraclavicular","Axillary"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (780, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 108, '{"id":780,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":108,"q":"Which of the following is safe even if injected intraarterial?","o":["Thiopentone","Propofol","Mida7olam","Methohexitone"],"a":1,"e":"Ans. is ''b'' i.e., Propofol Accidental extravasation or intra-arterial injection of propofol does not cause adverse reactions\" Primer of Anaesthesia \"Intraartierial injection of propofol does not cause vascular injury\" – Essentials of Anaesthesia Etomidate is also safe. –Miller''s Drugs associated with sever complications after intraarterial injection","pyqMatches":[{"year":"2013","no":1720,"q":"Which of the following is safe even if injected intraarterial?","o":["Thiopentone","Propofol","Mida7olam","Methohexitone"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (781, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 109, '{"id":781,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":109,"q":"Critical temperature for liquid nitrogen is ?","o":["36.5°C","-20°C","-147°C","-242°C"],"a":2,"e":"Ans. is ''c'' i.e., -147° C Critical temperature (Tc) of a substance is the temperature at and above which vapour of that substance can not be liquified, no matter how much pressure is applied (Note : Below critical temprature a substance can exist as a liquid or gas depending on pressure). Critical temperature of N2 is -146.9° C; that means N2 can be liquified below -146.9° C --> So, liquid nitrogen must be stored below -146.9° C.","pyqMatches":[{"year":"2013","no":1708,"q":"Critical temperature for liquid nitrogen is ?","o":["36.5°C","20°C","147°C","242°C"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (782, 'Anesthesia', 'Airway Management', 'Easy', 'Anaesthesia', 110, '{"id":782,"subject":"Anesthesia","chapter":"Airway Management","difficulty":"Easy","source":"Anaesthesia","sourceNo":110,"q":"Supreme LMA characteristic is","o":["Has no bite block","Used in infants","High pressure, low volume","Has built in drain tube"],"a":3,"e":"Ans. is ''d'' i.e., Has built in drain tube LMA supreme is one of the most advanced laryngeal mask airway (LMA). It has features of usual LMA with additional Built-in drain tube and a bite block. It has high volume/low pressure cuff which generates higher seal pressure. o It also provides a conduit for active suctioning of stomach. It can be used in infants as well as in adults.","pyqMatches":[{"year":"2013","no":1706,"q":"Supreme LMA characteristic is","o":["Has no bite block","Used in infants","High pressure, low volume","Has built in drain tube"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (783, 'Anesthesia', 'Miscellaneous', 'Moderate', 'Anaesthesia', 111, '{"id":783,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anaesthesia","sourceNo":111,"q":"In pediatric epidural anaestheisia, volume of local anaesthetic given to cause sacral dermatome block is?","o":["0.5 -1 ml/kg","2 - 4 ml/kg","5 - 10 ml/kg","None"],"a":0,"e":"Ans. is ''a'' i.e., 0.5 - 1 ml/kg Two most commonly used local anaesthetics for caudal block in children are :-","pyqMatches":[{"year":"2013","no":1732,"q":"In pediatric epidural anaestheisia, volume of local anaesthetic given to cause sacral dermatome block is?","o":["0.5 -1 ml/kg","2 - 4 ml/kg","5 - 10 ml/kg","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (784, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 112, '{"id":784,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":112,"q":"Fastest induction and recovery is seen with ?","o":["Desflurane","N,0","Halothane","Enflurane"],"a":0,"e":"Ans. is ''a'' i.e., Desflurane decreasing order (Increasing order of B : G partition coefficient and blood solubility) : - Desflurane (0.42)Q > Cyclopropane (0.44) > N20 (0.47) > Sevoflurane (0.69)Q > Isoflurane (1.38) > Enflurane (1.8) > Halothane (2.4) > Chloroform (8) > Trilene (9) > Ether (12) > Methoxyflurane (15)Q.","pyqMatches":[{"year":"2013","no":1715,"q":"Fastest induction and recovery is seen with ?","o":["Desflurane","N,0","Halothane","Enflurane"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (785, 'Anesthesia', 'Local Anesthesia', 'Easy', 'Anaesthesia', 113, '{"id":785,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":113,"q":"Shortest acting local anaesthetics ?","o":["Lignocaine","Bupivacaine","Etidocaine","Chlorprocaine"],"a":3,"e":"Ans. is ''d'' i.e., Chlorprocaine Short duration Low potency Intermediate duration (30-90 min) Intermediate potency Long duration (> 120 min) High potency Chloiprocaine (shortest acting) Procaine Lignocaine o Mepivacaine o Prilocaine a Cocaine Bupivacaine o Tetracaine o Etodicaine o Ropivacaine Dibucaine (longest acting)","pyqMatches":[{"year":"2013","no":1733,"q":"Shortest acting local anaesthetics ?","o":["Lignocaine","Bupivacaine","Etidocaine","Chlorprocaine"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (786, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 114, '{"id":786,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":114,"q":"Circuit of choice for controlled ventilation ?","o":["Magill circuit","Type C","Type D","Type E"],"a":2,"e":"Ans. is ''c'' i.e., Type D","pyqMatches":[{"year":"2013","no":1704,"q":"Circuit of choice for controlled ventilation ?","o":["Magill circuit","Type C","Type D","Type E"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (787, 'Anesthesia', 'Local Anesthesia', 'Moderate', 'Anaesthesia', 115, '{"id":787,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Moderate","source":"Anaesthesia","sourceNo":115,"q":"All are used for local infiltration except ?","o":["Lidocaine","Ropivacaine","Dibucaine","Bupivacaine"],"a":2,"e":"Ans. is ''c'' i.e., Dibucaine","pyqMatches":[{"year":"2013","no":1734,"q":"All are used for local infiltration except ?","o":["Lidocaine","Ropivacaine","Dibucaine","Bupivacaine"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (788, 'Anesthesia', 'Local Anesthesia', 'Easy', 'Anaesthesia', 116, '{"id":788,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":116,"q":"Drug of choice for Bier''s block ?","o":["Bupivacaine","Etidocaine","Ropivacaine","Lidocaine"],"a":3,"e":"Ans. is ''d'' i.e., Lidocaine Intravenous regional Anaesthesia (Bier''s block) Intravenous regional anaesthesia (IVRA) is used most often for surgery of the forearm and hand, but can also be used for distal leg and foot. First IV canula is inserted usually in the dorsum of hand. Then tourniquet cuff is applied to proximal arm. Limb is elevated and exsanguinated with the help of an elastic bandage (Esmarch). Now tourniquet cuff is inflated above systolic pressure (so that no blood can enter in that limb and the limb remains exsanguinated). Now the local anaesthetic solution is slowly injected into cannula. The veins are filled with only local anaesthetic as there is no blood →ocal anaesthetic can not be drained out from upper limb and can not enter in systemic circulation because of inflated cuff in proximal arm. The arm is anaesthetized in 6-8 minutes. Lidocaine without adrenaline is the DOC for this technique. —Goodman & Gilman llthie 381 o A few clinician prefers prilocaine over lidocaine because of its higher therapeutic index - least toxic LA. Torniquet cuff deflation, premature release or failure of torniquet can cause release of LA into circulation and toxicity may occur→ So, cardiotoxic LAs like bupivacaine and etidocaine are contraindicated for Bier''s block.","pyqMatches":[{"year":"2013","no":1744,"q":"Drug of choice for Bier''s block ?","o":["Bupivacaine","Etidocaine","Ropivacaine","Lidocaine"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (789, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 117, '{"id":789,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":117,"q":"Smooth induction is seen by -","o":["Ether","Halothane","Isoflurane","Enflurane"],"a":2,"e":"Ans. is ''c'' i.e., Isoflurane Induction by inhalation agents Unpleasant Intermediate Smooth Ether Halothane Isoflurane En flurane Desflurane Sevoflurane Nitrous oxide","pyqMatches":[{"year":"2013","no":1740,"q":"Smooth induction is seen by","o":["Ether","Halothane","Isoflurane","Enflurane"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (790, 'Anesthesia', 'Miscellaneous', 'Moderate', 'Anaesthesia', 118, '{"id":790,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anaesthesia","sourceNo":118,"q":"True about conscious sedation are all except ?","o":["CNS depression","Patient is conscious","Protective reflexes are abolished","Patient can obey commands"],"a":2,"e":"Ans. is ''c'' i.e., Protective reflexes are abolished conscious sedation, protective reflexes are intact (has been explained in previous sessions).","pyqMatches":[{"year":"2013","no":1746,"q":"True about conscious sedation are all except ?","o":["CNS depression","Patient is conscious","Protective reflexes are abolished","Patient can obey commands"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (791, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 119, '{"id":791,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":119,"q":"Longest part of optic nerve ?","o":["Intraocular","Intracranial","Intraorbital","Intracranial"],"a":2,"e":". Ans. is ''c'' i.e., Intraorbital Optic nerve Each optic nerve (second cranial nerve) starts from the optic disc and extends up to optic chiasma, where the two nerves meet. It is the backward continuation of the nerve fibre layer of the retina, which consists of the second order neurons i.e., axon originating from the ganglion cells. It also contains the afferent fibres of the papillary light reflex. Morphologically and embryologically, the optic nerve is comparable to a sensory tract. Unlike peripheral nerves it is not covered by neurilemma (so it does not regenerate when cut). The fibres of optic nerve, numbering about a million, are very fine (2- 10 m in diameter as compared to 20 mm of sensory nerves). Optic nerve is about 47-50 mm in length and can be divided into 4 parts : ? Intraocular part (1 mm) : - It begins at optic disc (optic nerve head) and exits the nerve through a hole in sclera that is occupied by a mesh like structure called the lamina cribrosa. The nerve fibres from the retina leave the eye through pores (holes) in lamina cribrosa, a sieve-like structure made up of collagen meshwork. Intraorbital part (30 mm) : - Extends from back of the eyeball (at lamina cribrosa) to the optic foramina. Intracanalicular part (6-9 mm) : - It lies within the optic canal and closely related to ophthalmic artery which crosses obliquely over it. Intracranial part (10 mm) : - It lies above the cavernous sinus and converges with its fellow from contralateral side to form optic chiasma. Like other parts of CNS, the optic nerve is covered by meningeal sheaths (Pia, archnoid and dura mater) as soon as the nerve leaves the eyeball.","pyqMatches":[{"year":"2013","no":1189,"q":"Longest part of optic nerve ?","o":["Intraocular","Intracranial","Intraorbital","Intracranial"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (792, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 120, '{"id":792,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":120,"q":"Stocker''s line is seen in?","o":["Pterygium","Glaucoma","Posterior scleritis","Diabetic retinopathy"],"a":0,"e":"Ans. is ''a'' i.e., Pterygium is line of iron deposition in the corneal epithelium seen adjacent to the head of the pterygium.","pyqMatches":[{"year":"2013","no":1136,"q":"Stocker''s line is seen in?","o":["Pterygium","Glaucoma","Posterior scleritis","Diabetic retinopathy"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (793, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 121, '{"id":793,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":121,"q":"Most common infection in contact lens users is?","o":["Streptococcus","Pseudomonas","Staphylococcus","Neisseria"],"a":1,"e":"Ans. is ''b'' i.e., Pseudomonas Complications of contact lens wear Complications of contact lens wearing are : ? Intolerance :- Some people find wearing contact lenses intolerable. Corneal complications :- Corneal abrasion, Corneal edema, Corneal vascularization, Microbial keratitis (Pseudomonas, acanthamoeba), Sterile corneal infiltrate. Giant papillary conjunctivitis Hypoxia :- Cornea is deprived of oxygen from the tear film by the presence of the contact lens. The cornea becomes edematous and new vessels may develop in the limbal area. Sensitivity :- This may develop in response to the preservative (thiomersal) in the cleaning and soaking solution. This results in allergic conjunctivitis.","pyqMatches":[{"year":"2013","no":1146,"q":"Most common infection in contact lens users is?","o":["Streptococcus","Pseudomonas","Staphylococcus","Neisseria"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (794, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 122, '{"id":794,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":122,"q":"Polyopia/diplopia is seen in which type of cataract?","o":["Nuclear","Cortical","Posterior subcapsular","Anterior polar"],"a":1,"e":"Ans. is ''b'' i.e., Cortical","pyqMatches":[{"year":"2013","no":1161,"q":"Polyopia/diplopia is seen in which type of cataract?","o":["Nuclear","Cortical","Posterior subcapsular","Anterior polar"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (795, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 123, '{"id":795,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":123,"q":"Pulsatile proptosis is a feature of ?","o":["Orbital varix","Retinoblastoma","Cortico-cavernous fistula","Covernous sinus thrombosis"],"a":2,"e":"Ans. is ''c'' i.e., Cortico-cavernous fistula Proptosis Proptosis is bulging of the eyeball (forward bulging) beyond the orbital margins. Though the word exophthalmos is synonymous with proptosis; some source define xophthalmos as a protrusion of globe greater than 18mm and proptosis as a protrusion equal to or less than 18 mm. Proptosis may be classified as follows : ? Unilateral Proptosis Proptosis of one eye. Inflammatory lesions :- Orbital cellulitis, abscess, cavernous sinus thrombosis, etc. Vascular disturbances :- Haemorrhage, varicose orbital veins, haemangioma, etc. Cysts and tumour :- Dermoid cyst, osteoma, lymphoma, lymphosarcoma, glioma, meningioma of optic nerve, retinoblastoma and metastatic deposits in orbit Neuroblastoma, breast, prostate, lung, GIT, Kidney, Ewing''s tumor, melanoma, wilms tumor (Nephroblastoma)]. Systemic diseases - Leukemias and endocrine disturbances such as Graves'' disease and thyrotropic exophthalmos in initial stages. Paralysis of extraocular muscles as in complete ophthalmoplegia. Mucocele of PNS'' - Frontal (most common), ethmoid, maxillary. Bilateral Proptosis Proptosis of both eyes. evelopmental anomalies of the skull- Oxycephaly (tower skull). Endocrine exophthalmos, both thyrotoxic and thyrotropic. Inflammatory lesions - Cavernous sinus thrombosis. Tumours - lymphosarcoma, lymphoma, pseudotumour, nephroblastoma, Ewing''s sarcoma. Systemic disease - Histocytosis (Hand - schuller christon disease), amyloidosis, wegner''s granulomatosis. Intermittent proptosis Proptosis developing intermittently and rapidly in one eye when venous stasis is induced by forward bending or lowering the head, turning the head forcibly, hyperextension of the neck, coughing, forced expiration with or without compression of the nostrils, or pressure on jugular veins. The most important casue is orbital varix (varicocele). Pulsatile proptosis : - Pulsatile proptosis is seen in caroticocovernous fistula; saccular aneurysm of ophthalmic artery; and due to transmitted cerebral pulsation as seen in meningocele, neurofibromatosis and traumatic or operative hiatus.","pyqMatches":[{"year":"2014","no":1221,"q":"Pulsatile proptosis is a feature of ?","o":["Orbital varix","Retinoblastoma","Cortico-cavernous fistula","Covernous sinus thrombosis"],"a":2,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":1064,"q":"Pulsatile proptosis is a feature of ?","o":["Orbital varix","Retinoblastoma","Cortico-cavernous fistula","Covernous sinus thrombosis"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (796, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 124, '{"id":796,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":124,"q":"Photoretinitis is due to?","o":["Snow reflection","Solar eclipse","Blunt trauma","None of the above"],"a":1,"e":"Ans. is b i.e., Solar eclipse Photoretitins Photoretinitis refers to damage to the retina resulting from exposure to the sunlight without adequate protection. In recent years it has become clear that photoretinitis is the result of photochemical reaction following exposure of the retina to shorter wave-length in the visible spectrum (i.e. blue/violet-blue light) with a small contribution by UV-A rays (and not by infrared rays which was thought earlier). Therefore, photoretinitis is also called as blue-light retinal injury. Photoretinitis is associated with religious sun gazing, solar eclipse observing, telescopy solar viewing, watching bright sunlight, or exposure to the flash of the short-circuiting of a strong current. The symptoms are persistent of the after image, progressing later into positive scotoma, and metamorphosia. Ophthalmoscopically, there may be no sign at first, or a pale spot is seen at the fovea with a brownish-red ring around it. Later there are deposit of pigments and small, grey punctate spots around the fovea, or even the formation of retinal hole","pyqMatches":[{"year":"2013","no":1185,"q":"Photoretinitis is due to?","o":["Snow reflection","Solar eclipse","Blunt trauma","None of the above"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (797, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 125, '{"id":797,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":125,"q":"Parachute lesions are seen in ?","o":["Eale''s disease","Diabetes","Sickle cell anemia","All of the above"],"a":3,"e":"Ans. is d i.e., All of the above","pyqMatches":[{"year":"2013","no":1222,"q":"Parachute lesions are seen in ?","o":["Eale''s disease","Diabetes","Sickle cell anemia","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (798, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 126, '{"id":798,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":126,"q":"Foster Kennedy syndrome is","o":["I/L Papilloedema CiL optic atrophy","I/L Optic atrophy C/L papilloedema","I/L Optic atrophy and papilloedema","UL Papilloedema C/L papilitis"],"a":1,"e":"Ans. is ''c ib., I/L Optic atrophy C/L papilloedema Foster-Kennedy syndrome : - The frontal lobe, pituitary and middle- ear tumor such as meningiomata of the oflactory groove are sometimes associated with Ipsilateral pressure atrophy of the optic nerve and contralateral papilledema. Pseudo-Foster-kennedy syndrome : - It is characterized by occurence of unilateral papilloedema associated with raised ICT (due to any cause) and a pre-existing optic atrophy (due to any cause) on the other side.","pyqMatches":[{"year":"2013","no":1193,"q":"Foster Kennedy syndrome is","o":["I/L Papilloedema CiL optic atrophy","I/L Optic atrophy C/L papilloedema","I/L Optic atrophy and papilloedema","UL Papilloedema C/L papilitis"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (799, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 127, '{"id":799,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":127,"q":"Enucleation of the eyeball is contraindicated in ?","o":["ndophthalmitis","Panophthalmitis","Intraocular tumours d","Painful blind eye"],"a":1,"e":"Ans. is ''b'' i.e., Panophthalmitis Enucleation Enucleation is the removal of eyeball with a portion of optic nerve from the orbit while preserving all other orbital structures. Indications Absolute :- Retinoblastoma, malignant melanoma. Relative :- Painful blind eye, mutilating ocular injury, anterior staphyloma,phthisis bulbi, endophthalmitis, congenital anophthalmia or severe microphthalmia. Contraindications Enucleation is contraindicated :- After the onset of sympathetic ophthalmia Panophthalmitis :- Infection can spread via the cut ends of optic nerve sheath causing meningitis","pyqMatches":[{"year":"2013","no":1221,"q":"Enucleation of the eyeball is contraindicated in ?","o":["ndophthalmitis","Panophthalmitis","Intraocular tumours d","Painful blind eye"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (800, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 128, '{"id":800,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":128,"q":"Type of laser used for iridotomy ?","o":["Excimer","Krypton red","Nd:YAG","Diode"],"a":2,"e":"Ans. is ''c'' i.e., Nd:YAG","pyqMatches":[{"year":"2013","no":1223,"q":"Type of laser used for iridotomy ?","o":["Excimer","Krypton red","Nd:YAG","Diode"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (801, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 129, '{"id":801,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":129,"q":"Most common cause of ptosis ?","o":["Myasthenia gravis","Paralysis of 3rd nerve","Idiopathic","Congenital"],"a":3,"e":"Ans. is ''d'' i.e., Congenital Ptosis Ptosis is drooping of upper eyelid. Ptosis occurs when the muscles that raise the eyelid (levator palpebrae superiors and muller''s nuscles) are not strong enough to do so properly. Etiology of Ptosis may be :? A) Congenital myogenic ptosis :- It is the most common type of ptosis and is often bilateral. It is associated with maldevelopment or congenital weakness of levator palpebrae sperioris. Congenital myogenic ptosis is characterized by drooping of one or both lids at birth, with a diminished or absent lid crease and lid lag on downgaze due to tethering effect of abnormal muscle. It may occur in following forms Simple congenital ptosis :- Not associated with other anomaly Congenital ptosis with superior rectus weakness Blepharophimosis syndrome Congenital ptosis, blepharophimosis, telecanthus and epicanthus inversus. Congenital synkinetic ptosis (Marcus Gunn jaw- winking Ptosis):- Retraction of ptotic lid with jaw movement like chewing, i.e., with stimulation of ipsilateral pterygoid muscle. B) Acquird ptosis :- Depending upon the cause acquired ptosis may be Neurogenic :- It is due to paralysis of 3rd nerve, Horner''s syndrome, ophthalmoplegic migraine, multiple sclerosis. Neurogenic ptosis may also occur due to lesion of sympathetic nerve) supplying muller''s muscle. Myogenic :- It is due to acquired defect of LPS muscle and may be seen in myasthenia gravis, dystrophia myotonica, ocular myopathy, oculopharyngeal muscular dystrophy, thyrotoxicosis, Lambert - Eaton mysthenia syndrome Mechanical:- It is due to excessive weight on the upper lid e.g in lid tumors, multiple chalazia, lid edema. It may also occur due to scarring (cicatracial ptosis) in atients with ocular pemphigoid and trachoma. Aponeurotic ptosis :- It is due to defect of the levator aponeurosis in the presence of normal functioning muscle, e.g. involutional (senile) ptosis, post-operative ptosis.","pyqMatches":[{"year":"2013","no":1208,"q":"Most common cause of ptosis ?","o":["Myasthenia gravis","Paralysis of 3rd nerve","Idiopathic","Congenital"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (802, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 130, '{"id":802,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":130,"q":"Nerve carrying motor component of light reflex?","o":["1St nerve","2\" nerve","3'' nerve","4th nerve"],"a":2,"e":"Ans. is `C'' i.e., 3rd nerve","pyqMatches":[{"year":"2013","no":1190,"q":"Nerve carrying motor component of light reflex?","o":["1St nerve","2\" nerve","3'' nerve","4th nerve"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (803, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 131, '{"id":803,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":131,"q":"Altitudinal visual field defect is seen in ?","o":["Papilloedema","Retinitis pigmentosa","Anterior ischemic neuropathy","Buphthalmos"],"a":2,"e":"Ans. is ''c'' i.e., Anterior ischemic neuropathy Anterior ischemic optic neuropathv (AION) It is a condition of local anoxia of the anterior region of the optic nerve. It is due to the involvement of posterior ciliary artery and may be central retinal artery causing infarct of the anterior part of the optic nerve and retina. It occurs commonly in neglected acute attack of closed angle glaucoma, severe anemia, after a massive haemorrhage, and temporal arteritis. There is sudden loss of vision. On examination there is swelling of the disc resulting in optic atrophy. Permanent altitudinal visual field defects are present. These involve two quadrants of either the superior or inferior visual field.","pyqMatches":[{"year":"2013","no":1194,"q":"Altitudinal visual field defect is seen in ?","o":["Papilloedema","Retinitis pigmentosa","Anterior ischemic neuropathy","Buphthalmos"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (804, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 132, '{"id":804,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":132,"q":"Upper Lid Retractors include","o":["Muller muscle and superior rectus","Levator palpabrae superioris and superior oblique","Superior oblique and superior rectus","Levator palpabrae superioris & muller muscle"],"a":3,"e":"Ans. is ''d'' i.e., Levator palpabrae superioris & muller muscle The levator palpebrae superioris is the important upper eye lid retractor. Injury or weakness to this muscle leads to ptosis. This muscle is supplied by occulomotor (3'') nerve. Deep part of the elevator muscle is the Muller''s muscle, which is sympathetically innvervated. In hyperthyroidism, sensitization of the Muller muscle leads to upper eyelid retraction and pseudoproptosis. On the other hand, in Horner''s syndrome loss of this muscle action leads to ptosis. The capsulopalpebral fascia assists in lower eyelid retraction and coordinates with eyeball movement. It arises as an extension of the inferior rectus and inserts into the lower edge of the lower tarsus and the adjacent orbital septum.","pyqMatches":[{"year":"2013","no":1209,"q":"Upper Lid Retractors include","o":["Muller muscle and superior rectus","Levator palpabrae superioris and superior oblique","Superior oblique and superior rectus","Levator palpabrae superioris & muller muscle"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (805, 'Anesthesia', 'Miscellaneous', 'Hard', 'Anaesthesia', 133, '{"id":805,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Hard","source":"Anaesthesia","sourceNo":133,"q":"A patient with ptosis, upper 4 mm of cornea is covered by upper eyelid. Grade of Ptosis is ?","o":["Mild","Moderat","Severe","Profound"],"a":0,"e":"Ans. is ''a'' i.e., Mild In unilateral cases of ptosis, difference between the vertical height of palpebral fissures of the two sides indicates the degree of ptosis. In bilateral cases it can be determined by measuring the amount of cornea covered by the upper eyelid and then substracting 2 mm. Depending upon its amount the ptosis is graded as - 1:1 Mild : 2 mm Moderate : 3 mm Severe : 4 mm In this question, 4 mm of cornea is covered by upper eyelid. Substracting 2 mm from this means there is 2 mm of ptosis, i.e. mild grade","pyqMatches":[{"year":"2013","no":1210,"q":"A patient with ptosis, upper 4 mm of cornea is covered by upper eyelid. Grade of Ptosis is ?","o":["Mild","Moderat","Severe","Profound"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (806, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 134, '{"id":806,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":134,"q":"Schwable''s ring is seen in which layer of cornea","o":["Bowmann''s membrane","Stroma","Descemet''s membrane","Substantia propria"],"a":2,"e":"Ans. is ''c'' i.e., Descemet''s membrane Histology of cornea The cornea has five distinct layers (from superficial to deep) : ? Epithelium : - It is the outermost part of cornea and is composed of stratified squamous non-keratinized epithelial cells. Bowman''s membrane : - It is not a true membrane but simply a condensed superficial part of stroma. destroyed, it does not regenerate. Stroma (Substantia propria) : - This layer constitutes most of the cornea (90% of thickness). It consists of collagen fibrils (lamellae) embedded in hydrated matrix ofproteoglycans. Descemet''s membrane : - This layer bounds the stroma posteriorly. In the periphery it appears to end at the anterior limit of trabecular meshwork as Schwahle''s ring. Endothelium : - It is a single layer of flat polygnonal cells. The endothelial cells contain ''active-pump'' mechanism and is the most important layer in maintaining the transparency of cornea.","pyqMatches":[{"year":"2013","no":1141,"q":"Schwable''s ring is seen in which layer of cornea","o":["Bowmann''s membrane","Stroma","Descemet''s membrane","Substantia propria"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (807, 'Anesthesia', 'Muscle Relaxants', 'Easy', 'Anaesthesia', 135, '{"id":807,"subject":"Anesthesia","chapter":"Muscle Relaxants","difficulty":"Easy","source":"Anaesthesia","sourceNo":135,"q":"Phase II block is seen with -","o":["SCh infusion","Single dose SCh","Mivacurium","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., SCh infusion Under certain conditions depolarizing agents produce dual mechanism of neuromuscular blockade which can be divided into two phases : a. Phase I block Rapid in onset Result from persistant depolarization of muscle end plate. b. Phase II block Slow in onset Results from desensitization of receptor to ACh. Phase II block is seen when fluorinated anaesthetics have been given or when SCh is injected in high dose or infused continuously. SCh also produces phase II block in patients with atypical or deficient pseudocholinesterase.","pyqMatches":[{"year":"2013","no":563,"q":"Phase II block is seen with","o":["SCh infusion","Single dose SCh","Mivacurium","None of the above"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (808, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 136, '{"id":808,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":136,"q":"Anaesthetic gas with maximum respiratory irritation","o":["Halothane","Enflurane","Desflurane","Sevoflurane"],"a":2,"e":"Ans:C. Desflurane Desflurane and isofurane when used for induction cause respiratory irritation due to their pungent smell leading to breath holding and coughing. Halothane and sevoflurane do not cause such effects.","pyqMatches":[{"year":"2019","no":228,"q":"Anaesthetic gas with maximum respiratory irritation","o":["Halothane","Enflurane","Desflurane","Sevoflurane"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (809, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 137, '{"id":809,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":137,"q":"IV administration of which anesthetic drug is most painful among the following?","o":["Methohexital","Ketamine","Propofol","Etomidate"],"a":2,"e":"Ans: c. Propofol Propofol preparation: Oil-based preparation (soybean oil, egg lecithin & glycerol). Hence, pain on injection & rarely thrombophlebitis.","pyqMatches":[{"year":"2019","no":229,"q":"IV administration of which anesthetic drug is most painful among the following?","o":["Methohexital","Ketamine","Propofol","Etomidate"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (810, 'Anesthesia', 'General Anesthesia', 'Moderate', 'Anaesthesia', 138, '{"id":810,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Moderate","source":"Anaesthesia","sourceNo":138,"q":"Which of the following is not cardiodepressive?","o":["Propofol","Thiopentone","Ketamine","Etomidate"],"a":3,"e":"Ans:D. Etomidate Major advantage of etomidate: Cardiovascular stability after induction. Effects of etomidate induction dose: Negligible increase in heart rate. Little decrease in blood pressure/cardiac output. Little effect on coronary perfusion pressure, while reducing myocardial O2 consumption.","pyqMatches":[{"year":"2019","no":230,"q":"Which of the following is not cardiodepressive?","o":["Propofol","Thiopentone","Ketamine","Etomidate"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (811, 'Anesthesia', 'Monitoring & Perioperative Care', 'Easy', 'Anaesthesia', 139, '{"id":811,"subject":"Anesthesia","chapter":"Monitoring & Perioperative Care","difficulty":"Easy","source":"Anaesthesia","sourceNo":139,"q":"Which of the following is the most common method used to know depth of anaesthesia?","o":["BIS","Oesophageal contractility","Depressed responses","Hypotension"],"a":0,"e":"Ans:A. BIS Bispectral index: * 1st scientifically validated & commercially available monitor to check depth of anaesthesia. * Utilizes many parameters (EEG signals, eye blinks) to calculate depth score. Adequate depth: * Score of 45-60. Fully awake state: * Score of 100 Completely silent brain: 0.","pyqMatches":[{"year":"2019","no":231,"q":"Which of the following is the most common method used to know depth of anaesthesia?","o":["BIS","Oesophageal contractility","Depressed responses","Hypotension"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (812, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 140, '{"id":812,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":140,"q":"MRP 2 associated with which of the following?","o":["Rotor syndrome","Dubin-Johnson syndrome","Crigler-Najjar syndrome","Gilbert syndrome"],"a":1,"e":"Ans:B. Dubin-Johnson syndrome. Dubin-Johnson syndrome: An autosomal recessive disorder. Caused by gene mutation responsible for human canalicular multispecific organic anion transporter (cMOAT) protein/ also referred “multidrug resistance protein 2 (MRP2)” or ABCC2.","pyqMatches":[{"year":"2019","no":232,"q":"MRP 2 associated with which of the following?","o":["Rotor syndrome","Dubin-Johnson syndrome","Crigler-Najjar syndrome","Gilbert syndrome"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (813, 'Anesthesia', 'Local Anesthesia', 'Hard', 'Anaesthesia', 141, '{"id":813,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Hard","source":"Anaesthesia","sourceNo":141,"q":"In ophthalmology a patient is allergic to aminoesters. What can be used?","o":["Cocaine","Procaine","Prilocaine","Bupivacaine e) Tetracaine"],"a":2,"e":":D Ans. is''c''i.e., Prilocaine &''d''i.e., Bupivacaine [Ref: Lee''s 13th/e p. 486] Prilocaine & bupivacaine are amides (amcinonide). Other three are aminoesters.","pyqMatches":[{"year":"2013","no":1710,"q":"In ophthalmology a patient is allergic to aminoesters. What can be used?","o":["Cocaine","Procaine","Prilocaine","Bupivacaine e) Tetracaine"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (814, 'Anesthesia', 'Miscellaneous', 'Moderate', 'Anaesthesia', 142, '{"id":814,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anaesthesia","sourceNo":142,"q":"Drug(s) not given as transdermal patch:","o":["Fentanyl","Diclofenac","Morphine","Clonidine e) Buprenorphine"],"a":1,"e":":C Ans.B,Diclofenac & C,Morphine [Ref: KDT 7th/476 Transdermal fentanyl (Durogesic) has become available for use in cancer/terminal illness. Butrans skin patches contain buprenorphine an opioid pain medication. Clonidine transdermal delivery (patch) systems have been available since the 1980","pyqMatches":[{"year":"2015","no":548,"q":"Drug(s) not given as transdermal patch:","o":["Fentanyl","Diclofenac","Morphine","Clonidine e) Buprenorphine"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (815, 'Anesthesia', 'Airway Management', 'Easy', 'Anaesthesia', 143, '{"id":815,"subject":"Anesthesia","chapter":"Airway Management","difficulty":"Easy","source":"Anaesthesia","sourceNo":143,"q":"Mallampatti''s classification is for?","o":["Mobility of cervical spine","Mobility of atlanto axial joint","Assessment of free rotation of neck before intubation","Inspection of oral cavity before intubation"],"a":3,"e":"Ans. D. Inspection of oral cavity before intubation [Ref Morgan 4thie p. 113] Mallampati score (Mallampati oropharyngeal scale): Mallampati grading is used to evaluate the visibility of tonsil and tonsillar fossa which in turn assess the adequate mouth opening depending upon the grade. Indications of Mallampati score are Oral cavity assessment to rule out difficult intubation (Inspection of oral cavity before intubation) & Sleep apnea evaluation.","pyqMatches":[{"year":"2016","no":1724,"q":"Mallampatti''s classification is for?","o":["Mobility of cervical spine","Mobility of atlanto axial joint","Assessment of free rotation of neck before intubation","Inspection of oral cavity before intubation"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (816, 'Anesthesia', 'General Anesthesia', 'Hard', 'Anaesthesia', 144, '{"id":816,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Hard","source":"Anaesthesia","sourceNo":144,"q":"Anesthetic agent of choice in asthma patient is?","o":["Thiopentone","Methexitone","Ketamine","Propofol"],"a":2,"e":"Ans. C. Ketamine [Ref Miller''s 7\"le p. 744-746] Ketamine is a potent bronchodilator; therefore it is the anesthetic agent of choice in bronchial asthma patients. Halothane is the inhalational agent of choice in asthmatics.","pyqMatches":[{"year":"2016","no":1723,"q":"Anesthetic agent of choice in asthma patient is?","o":["Thiopentone","Methexitone","Ketamine","Propofol"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (817, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 145, '{"id":817,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":145,"q":"Pin index system is a safety feature adopted in anesthesia machines to prevent?","o":["Incorrect attachment of anesthesia machines","Incorrect attachment of anesthesia face masks","Incorrect inhalation agent delivery","Incorrect gas cylinder attachment"],"a":3,"e":"Ans. D. Incorrect gas cylinder attachment [Ref Lee 13th/e p. 85] Pin index system: - This is the safety mechanism so that one cylinder cannot be fitted at the other''s position.","pyqMatches":[{"year":"2016","no":1722,"q":"Pin index system is a safety feature adopted in anesthesia machines to prevent?","o":["Incorrect attachment of anesthesia machines","Incorrect attachment of anesthesia face masks","Incorrect inhalation agent delivery","Incorrect gas cylinder attachment"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (818, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 146, '{"id":818,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":146,"q":"Propofol shows following effect on EEG?","o":["Activation","Depression","Depression in low doses and activation in high doses","None of the above"],"a":1,"e":"Ans. B. Depression EEG changes during anesthesia: EEG Depression caused by, Inhalational agents (1-2 MAC) Barbiturates Opioids Etomidate Propofol Hypocapnia Marked hypercapnia Hypothermia Late hypoxia, ischemia","pyqMatches":[{"year":"2016","no":1721,"q":"Propofol shows following effect on EEG?","o":["Activation","Depression","Depression in low doses and activation in high doses","None of the above"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (819, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 147, '{"id":819,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":147,"q":"Type E circuit is used for?","o":["Spontaneous ventilation","Controlled ventilation","Children","An used for all of the above indications"],"a":2,"e":"Ans. C. Children [Ref Ajay Yadav 4th/e p. 29, 30] Circuit of choice for spontaneous ventilation in adult -4 Mapleson A Circuit of choice for controlled ventilation in adult Mapleson D (Bain circuit) Circuit of choice for children - Type F, i.e. Jackson-Rees (first choice) and type E, i.e. Ayre''s T piece (second choice)","pyqMatches":[{"year":"2016","no":1720,"q":"Type E circuit is used for?","o":["Spontaneous ventilation","Controlled ventilation","Children","An used for all of the above indications"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (820, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 148, '{"id":820,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":148,"q":"Anesthetic agent leading to bradycardia is?","o":["Pancuronium","Vecuronium","Atracurium","Propofol"],"a":3,"e":"Ans. D. Propofol Bradycardia causing anesthetic agents: Succinylcholine Propofol Opioids anesthetics (fentanyl and its congers)","pyqMatches":[{"year":"2016","no":1719,"q":"Anesthetic agent leading to bradycardia is?","o":["Pancuronium","Vecuronium","Atracurium","Propofol"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (821, 'Anesthesia', 'Airway Management', 'Easy', 'Anaesthesia', 149, '{"id":821,"subject":"Anesthesia","chapter":"Airway Management","difficulty":"Easy","source":"Anaesthesia","sourceNo":149,"q":"Size of LMA for a 15kg child is?","o":["1","2","3","4"],"a":1,"e":"Ans. B. 2 LMA according to patient’s weight and age: 10-20kgs, infants & children","pyqMatches":[{"year":"2016","no":1718,"q":"Size of LMA for a 15kg child is?","o":["1","2","3","4"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (822, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 150, '{"id":822,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":150,"q":"Intra-arterial thiopentone injection leads to?","o":["Ischemia","Vasodilatation","Vomiting","Hypertension"],"a":0,"e":"Ans. A. Ischemia [Ref Ajay Yadav 4th/e p. 80; Lee 13thie p. 155] Ischemia Inadvertent intra-arterial injection of thiopentone is a very dreadful complication. It produces thrombosis, vasospasm, ischemia, necrosis and finally gangrene. The first symptom is burning pain. The first sign is blanching of the hand due to vasospasm.","pyqMatches":[{"year":"2016","no":1717,"q":"Intra-arterial thiopentone injection leads to?","o":["Ischemia","Vasodilatation","Vomiting","Hypertension"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (823, 'Anesthesia', 'Airway Management', 'Moderate', 'Anaesthesia', 151, '{"id":823,"subject":"Anesthesia","chapter":"Airway Management","difficulty":"Moderate","source":"Anaesthesia","sourceNo":151,"q":"In mechanical ventilation, peak pressure in inspiration denotes ?","o":["Compliance of lung","Capacity of inspiratory muscles","Airway resistance","All of the above"],"a":2,"e":"Ans. C. Airway resistance [Ref: Essentials of anaesthesia-786] Pressures in mechanical ventilation Peak pressure Peak pressure applies when there is airflow in the circuit, i.e., during inspiration. Peak pressure determines airway resistance.","pyqMatches":[{"year":"2016","no":1701,"q":"In mechanical ventilation, peak pressure in inspiration denotes ?","o":["Compliance of lung","Capacity of inspiratory muscles","Airway resistance","All of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (824, 'Anesthesia', 'Monitoring & Perioperative Care', 'Easy', 'Anaesthesia', 152, '{"id":824,"subject":"Anesthesia","chapter":"Monitoring & Perioperative Care","difficulty":"Easy","source":"Anaesthesia","sourceNo":152,"q":"Hypotension following spinal anesthesia can be best prevented by?","o":["Preloading with colloids","Using small size needle","Preloading with crystalloids","All of the above"],"a":0,"e":"Ans. A. Preloading with colloids [Ref Lee 13th/e p. 509, 510; Morgan 4th/e p. 297] Hypotension is the most common complication of spinal anesthesia. It arises due to blocking of sympathetic root fibers and is usually accompanied by bradycardia (Preganglionic block of the sympathetic nerves to heart T1-T4) and nausea. Hypotension can be prevented by preloading the patient with colloids, Preloading with crystalloid does not prevent hypotension because large volumes of crystalloids quickly redistribute from intravascular to extravascular space. Beach chair position also prevents hypotension.","pyqMatches":[{"year":"2016","no":1716,"q":"Hypotension following spinal anesthesia can be best prevented by?","o":["Preloading with colloids","Using small size needle","Preloading with crystalloids","All of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (825, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 153, '{"id":825,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":153,"q":"Propofol vial, once opened, should be used within?","o":["2 hours","4 hours","6 hours","8 hours"],"a":2,"e":"ANs. C. 6 hours [Ref: Lee 13th/e p. 158-160; Morgan 4thle p. 200-202] Propofol is oil based preparation containing soybean oil, egg lecithin, and glycerol. The color of solution is milky white. Solution should be used within 6 hours after opening the vial because there have been death reports following the use of contaminated solution as egg lecithin is a good medium for bacterial growth. To prevent this problem recently available propofol preparations have disodium edetate or sodium metabisulfite as antimicrobial agent.","pyqMatches":[{"year":"2016","no":1702,"q":"Propofol vial, once opened, should be used within?","o":["2 hours","4 hours","6 hours","8 hours"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (826, 'Anesthesia', 'Muscle Relaxants', 'Easy', 'Anaesthesia', 154, '{"id":826,"subject":"Anesthesia","chapter":"Muscle Relaxants","difficulty":"Easy","source":"Anaesthesia","sourceNo":154,"q":"Which of the following agent is associated with maximum histamine release?","o":["d-Tubocurarine","Cisatracurium","Pancronium","Rocuronium"],"a":0,"e":"Ans. A. d-Tubocurarine Histamine release is caused by → D-TC (maximum tendency), succinylcholine, mivacurium, doxacurium, atracurium, tubocurarine can cause bronchoconstriction.","pyqMatches":[{"year":"2016","no":1715,"q":"Which of the following agent is associated with maximum histamine release?","o":["d-Tubocurarine","Cisatracurium","Pancronium","Rocuronium"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (827, 'Anesthesia', 'Airway Management', 'Easy', 'Anaesthesia', 155, '{"id":827,"subject":"Anesthesia","chapter":"Airway Management","difficulty":"Easy","source":"Anaesthesia","sourceNo":155,"q":"What is the intubation dose of pancuronium?","o":["0.1 mg/kg","1 mg/kg","10 mg/kg","20 mg/kg"],"a":0,"e":"Ans. A. 0.1 mg/kg","pyqMatches":[{"year":"2016","no":1714,"q":"What is the intubation dose of pancuronium?","o":["0.1 mg/kg","1 mg/kg","10 mg/kg","20 mg/kg"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (828, 'Anesthesia', 'Local Anesthesia', 'Easy', 'Anaesthesia', 156, '{"id":828,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":156,"q":"Relative contraindication of neuraxial/regional anesthesia is?","o":["Hypertension","Renal disease","Sepsis","Diabetes"],"a":2,"e":"Ans. C. Sepsis [Ref Morgan 4th/e p. 299] Contraindications to neuraxial block (spinal & epidural) Absolute :- Infection at the site of injection, patient refusal, coagulopathy or other bleeding disorder, severe hypovolemia, increased ICT, severe aortic or mitral stenosis. Relative :- Sepsis, unto-operative patient, pre-existing neurological deficit, demyelinating lesions, severe spinal deformity, stenotic valvular heart disease.","pyqMatches":[{"year":"2016","no":1703,"q":"Relative contraindication of neuraxial/regional anesthesia is?","o":["Hypertension","Renal disease","Sepsis","Diabetes"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (829, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 157, '{"id":829,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":157,"q":"\"Triangle of Petit\" is a landmark for which block?","o":["Spinal block","Bier''s block","TAP block","Epidural block"],"a":2,"e":"Ans. C. TAP block [Ref Miller''s anesthesia E-book p. 1735] * Transverse abdominis plane (TAP) block - It is a peripheral nerve block designed to anesthetize the nerves supplying the anterior abdominal wall (T6 to L1). - The point of entry for the blind TAP block is the lumbar triangle of Petit. - This is situated between the lower costal margin and iliac crest. - It is bound anteriorly by the external oblique muscle and posteriorly by the latissmis dorsi.","pyqMatches":[{"year":"2016","no":1713,"q":"\"Triangle of Petit\" is a landmark for which block?","o":["Spinal block","Bier''s block","TAP block","Epidural block"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (830, 'Anesthesia', 'Local Anesthesia', 'Easy', 'Anaesthesia', 158, '{"id":830,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":158,"q":"CNS affection of a local anesthetic agent leads to?","o":["Convulsion","Perioral numbness","Depression","All of the above"],"a":3,"e":"Ans. D. All of the above [Ref Morgan 4thle p. 270] Manifestations of local anesthetic toxicity Early symptoms (Prodrome) Circumoral numbness, dizziness, tongue paresthesia, restlesness, tinnitus, agitation. CNS symptoms :- These are biphasic i.e. excitation (convulsions, restlessness, agitation & tinnitus), followed by depression (drowsiness, disorientation, respiratory depression, unconciousness). Cardiovascular manifestations :- hypotension, cardiac arrest, coma","pyqMatches":[{"year":"2016","no":1704,"q":"CNS affection of a local anesthetic agent leads to?","o":["Convulsion","Perioral numbness","Depression","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (831, 'Anesthesia', 'Muscle Relaxants', 'Easy', 'Anaesthesia', 159, '{"id":831,"subject":"Anesthesia","chapter":"Muscle Relaxants","difficulty":"Easy","source":"Anaesthesia","sourceNo":159,"q":"Succinylcholine is contraindicated in?","o":["Hyperkalemia","Hypokalemia","Hypercalcemia","Hypocalcemia"],"a":0,"e":"Ans. A. Hyperkalemia [Ref Morgan Pie p. 214] Sch can cause dangerous hyperkalemia in and is contraindicated in: Burn, massive trauma, crush injury, Severe intraabdominal infection (sepsis).","pyqMatches":[{"year":"2016","no":1712,"q":"Succinylcholine is contraindicated in?","o":["Hyperkalemia","Hypokalemia","Hypercalcemia","Hypocalcemia"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (832, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 160, '{"id":832,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":160,"q":"Benzocaine is used in which type of anesthesia?","o":["Topical","Spinal","Epidural","All of the above"],"a":0,"e":"Ans. A. Topical [Ref Morgan 4th/e p. 270] Benzocaine and cocaine are used only in topical anesthesia .","pyqMatches":[{"year":"2016","no":1711,"q":"Benzocaine is used in which type of anesthesia?","o":["Topical","Spinal","Epidural","All of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (833, 'Anesthesia', 'Muscle Relaxants', 'Hard', 'Anaesthesia', 161, '{"id":833,"subject":"Anesthesia","chapter":"Muscle Relaxants","difficulty":"Hard","source":"Anaesthesia","sourceNo":161,"q":"A patient with normal succinylcholine metabolism will have Dibucaine number between?","o":["20-30","40-45","50-60","70-80"],"a":3,"e":"Ans. D. 70-80 Dibucain number : Dibucain (a local anaesthetic) inhibits 80% of normal pseudocholinesterase and 20% of atypical (non-functional) pseudocholinesterase. Therefore normal dibucain number is 70- 80%.","pyqMatches":[{"year":"2016","no":1710,"q":"A patient with normal succinylcholine metabolism will have Dibucaine number between?","o":["20-30","40-45","50-60","70-80"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (834, 'Anesthesia', 'Miscellaneous', 'Moderate', 'Anaesthesia', 162, '{"id":834,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anaesthesia","sourceNo":162,"q":"American anesthetic association says that clopidogrel should be withheld how many days before surgery?","o":["1 day","1 week","3 weeks","4 weeks"],"a":1,"e":"Ans. B. 1 week [Ref Ajay Yadav 3''/e p. 46] Preoperative modifications of pre-existing drugs Drugs which can be stopped Drugs which can be continued till the day of surgery Conventional dose aspirin & clopidogrel (antiplatelets)-I Antianginal (except aspirin) week before surgery Antiepileptics Oral anticoagulants - 4 days before & switch to heparin, which is stopped 12 hours prior to surgery Antihypertensives (except AT-II antagoists) Levodopa Oral hypoglycemic (metformin) - 48 hours before urgery Digitalis and switch to insulin TCAs AT-II antagonists (losartan, valsarton) - 1 day prior Low dose aspirin Lithium - 48-72 hours before surgery MAO inhibitors - 3 weeks before surgery Note: Antiplatelet drugs like clopidogrel and conventional dose of aspirin should be stopped 7 days prior to surgery. But low dose aspirin can be continued till the day of surgery.","pyqMatches":[{"year":"2016","no":1705,"q":"American anesthetic association says that clopidogrel should be withheld how many days before surgery?","o":["1 day","1 week","3 weeks","4 weeks"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (835, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 163, '{"id":835,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":163,"q":"Among the following agents, maximum boiling point is associated with?","o":["Sevoflurane","Isofurane","Methoxyflurane","Desflurane"],"a":2,"e":"Ans. C. Methoxyflurane [Ref Ajay Yadav 4th/e p. 63] Boiling point of methoxyflurane is more than water (104°C)","pyqMatches":[{"year":"2016","no":1709,"q":"Among the following agents, maximum boiling point is associated with?","o":["Sevoflurane","Isofurane","Methoxyflurane","Desflurane"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (836, 'Anesthesia', 'General Anesthesia', 'Moderate', 'Anaesthesia', 164, '{"id":836,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Moderate","source":"Anaesthesia","sourceNo":164,"q":"Which of the following inhalational anesthetic agent most easily crosses blood brain barrier?","o":["Methoxyflurane","Sevoflurane","Desflurane","Nitrous oxide"],"a":0,"e":"Ans. A. Methoxyflurane [Ref Ajay Yadav 4th/e p. 63] Oil : gas partition coefficient measures the lipid solubility of the agent and therefore solubility in the fat-rich tissues of the CNS (ability to cross BBB). Methoxyflurane has maximum oil : Gas partition coefficient —> Most lipid soluble & most easily crosses BBB. 1120 has minimum oil : Gas partition coefficient -p Least lipid soluble & therefore likely to cross BBB.","pyqMatches":[{"year":"2016","no":1706,"q":"Which of the following inhalational anesthetic agent most easily crosses blood brain barrier?","o":["Methoxyflurane","Sevoflurane","Desflurane","Nitrous oxide"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (837, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 165, '{"id":837,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":165,"q":"Which of the following anesthetic agent most is lipid soluble?","o":["Nitrous oxide","Methoxyflurane","Isoflurane","Halothane"],"a":1,"e":"Ans.B. Methoxyflurane Oil : gas partition coefficient measures the lipid solubility of the agent and therefore solubility in the fat-rich tissues of the CNS (ability to cross BBB). Methoxyflurane has maximum oil : Gas partition coefficient —> Most lipid soluble & most easily crosses BBB. 1120 has minimum oil : Gas partition coefficient -p Least lipid soluble & therefore likely to cross BBB.","pyqMatches":[{"year":"2016","no":1707,"q":"Which of the following anesthetic agent most is lipid soluble?","o":["Nitrous oxide","Methoxyflurane","Isoflurane","Halothane"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (838, 'Anesthesia', 'Miscellaneous', 'Moderate', 'Anaesthesia', 166, '{"id":838,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anaesthesia","sourceNo":166,"q":"Etomidate is not used for long term infusion because?","o":["Results in adrenal suppression","May cause vasospasm","Results in cardiac arrhythmias","May cause increase in ICT"],"a":0,"e":"Ans. A. Results in adrenal suppression [Ref Morgan 4th/e p. 200] Etomidate suppresses corticosteroid synthesis in the adrenal cortex by reversibly inhibiting 1113-hydroxylase, which coverts 11- deoxycortisol to cortisol and by a relative minor effect on 17a - hydroxylase. Using a continuous etomidate infusion for sedation of critically ill trauma patients in intensive care units has been associated with increased mortality due to adrenal suppression. The mortality of patients exposed to a continuous infusion of etomidate for more than 5 days increased from 25% to 44%, mainly due to infectious causes such as pneumonia.","pyqMatches":[{"year":"2016","no":1708,"q":"Etomidate is not used for long term infusion because?","o":["Results in adrenal suppression","May cause vasospasm","Results in cardiac arrhythmias","May cause increase in ICT"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (839, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 167, '{"id":839,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":167,"q":"Arm tongue time is ?","o":["13 secs","15 secs","20 secs","40 secs"],"a":0,"e":"Ans. A. 13 secs Arm to tongue time is method for knowing the circulation time i.e. time taken by a particle in the blood to flow from one point in circulation to other. It measures the linear velocity of blood. To calculate-the arm to tongue time 5 ml of 2% of decholine is injected into cubital vein. As soon as drug reaches the tongue, patient feels a bitter taste. The total time taken from arm to tongue is 13 seconds. Similarly arm to lung time is calculated with the help of ether. It is d seconds.","pyqMatches":[{"year":"2015","no":1609,"q":"Arm tongue time is ?","o":["13 secs","15 secs","20 secs","40 secs"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (840, 'Anesthesia', 'Monitoring & Perioperative Care', 'Hard', 'Anaesthesia', 168, '{"id":840,"subject":"Anesthesia","chapter":"Monitoring & Perioperative Care","difficulty":"Hard","source":"Anaesthesia","sourceNo":168,"q":"Respiratory failure in a post operative patient is ?","o":["Type 1","Type 2","Type 3","Type 4"],"a":2,"e":"Ans. C. Type 3 Type 3 or perioperative respiratory failure Increased atelectasis due to low functional residual capacity (FRC) in the setting of abnormal abdominal wall mechanics. Often results in type I or type II respiratory failure. Can be ameliorated by anesthetic or operative technique, posture posture, incentive spirometry, post -operative analgesia, attempts to rower intra - abdominal-pressure.","pyqMatches":[{"year":"2015","no":1610,"q":"Respiratory failure in a post operative patient is ?","o":["Type 1","Type 2","Type 3","Type 4"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (841, 'Anesthesia', 'Airway Management', 'Easy', 'Anaesthesia', 169, '{"id":841,"subject":"Anesthesia","chapter":"Airway Management","difficulty":"Easy","source":"Anaesthesia","sourceNo":169,"q":"Laryngeal mask airway [LMA] is contraindicated in?","o":["Difficult airways","Ocular surgeries","Pregnant female","In CPR"],"a":2,"e":"Ans. C. Pregnant female Contraindications of LMA","pyqMatches":[{"year":"2015","no":1611,"q":"Laryngeal mask airway [LMA] is contraindicated in?","o":["Difficult airways","Ocular surgeries","Pregnant female","In CPR"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (842, 'Anesthesia', 'Airway Management', 'Moderate', 'Anaesthesia', 170, '{"id":842,"subject":"Anesthesia","chapter":"Airway Management","difficulty":"Moderate","source":"Anaesthesia","sourceNo":170,"q":"All of the following are advantages of LMA except?","o":["More reliable than face mask","Prevent aspiration","Alternative to Endotracheal intubation","Does not require laryngoscope & visualization"],"a":1,"e":"Ans. B. Prevent aspiration LMA is intermediate between the face mask and Endotracheal intubation in terms of reliability, invasiveness and facilitation of gas exchange (face mask has minimum and endotracheal intubation has maximum). LMA does not prevent asPiration + should not be used in full stomach patients. LMA can be used as an alternative to endotracheal intubation for minor surgeries, where anaesthetist wants to avoid intubation. LMA is introduced blindly (without laryngoscopy)","pyqMatches":[{"year":"2015","no":1612,"q":"All of the following are advantages of LMA except?","o":["More reliable than face mask","Prevent aspiration","Alternative to Endotracheal intubation","Does not require laryngoscope & visualization"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (843, 'Anesthesia', 'Muscle Relaxants', 'Easy', 'Anaesthesia', 171, '{"id":843,"subject":"Anesthesia","chapter":"Muscle Relaxants","difficulty":"Easy","source":"Anaesthesia","sourceNo":171,"q":"Only available depolarizing muscle relaxant is ?","o":["Decamethonium","Suxamethonium","Mivacurium","None"],"a":1,"e":"Ans. B. Suxamethonium Suxamethonium (succinylcholine) and decamethonium come under depolarizing muscle relaxants. Out of these only suxamethonium is avalaible for clinical use.","pyqMatches":[{"year":"2015","no":1636,"q":"Only available depolarizing muscle relaxant is ?","o":["Decamethonium","Suxamethonium","Mivacurium","None"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (844, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 172, '{"id":844,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":172,"q":"Which anesthetic gas was used by WTG Morton in his experiment ?","o":["Nitrous oxide","Ammonia","Diethyl ether","Trichloroethylene"],"a":2,"e":"Ans. C. Diethyl ether William Thomas Green Morton, a dentist and medical student at Boston, after experimenting pon animals, gave a demonstration of general anesthesia, In 1846.","pyqMatches":[{"year":"2015","no":1613,"q":"Which anesthetic gas was used by WTG Morton in his experiment ?","o":["Nitrous oxide","Ammonia","Diethyl ether","Trichloroethylene"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (845, 'Anesthesia', 'Muscle Relaxants', 'Easy', 'Anaesthesia', 173, '{"id":845,"subject":"Anesthesia","chapter":"Muscle Relaxants","difficulty":"Easy","source":"Anaesthesia","sourceNo":173,"q":"Suxamethonium acts through which channels ?","o":["Sodium channels","Potassium channels","Calcium channels","Chloride channels"],"a":0,"e":"Ans. A. Sodium channels Suxamethonium (succinylcholine) is a depolarizing neuromuscular blocking agent which act by opening the Na+ channels at muscle end Plate.","pyqMatches":[{"year":"2015","no":1635,"q":"Suxamethonium acts through which channels ?","o":["Sodium channels","Potassium channels","Calcium channels","Chloride channels"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (846, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 174, '{"id":846,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":174,"q":"Mouth to mouth respiration provides what percentage of oxygen ?","o":["10%","16%","21%","100%"],"a":1,"e":"Ans. B. 16% Mouth to mouth breathing provides 0.8 to 1.2 liters of exhaled air per breath and 16% of oxygen which is enough to sustain life. The use of Ambu bag and room air provides 21% O2. The American Heart Association recommends tidal volumes of 700 to 1000 mL during mouth-to-mouth ventilation, but smaller tidal volumes of 500 mL may be of advantage to decrease the likelihood of stomach inflation, as mouth-to-mouth ventilation gas contains only 17% oxygen, but 4% carbon dioxide.","pyqMatches":[{"year":"2015","no":1614,"q":"Mouth to mouth respiration provides what percentage of oxygen ?","o":["10%","16%","21%","100%"],"a":1,"source":"NEET_2015_Paper.pdf"},{"year":"2020","no":234,"q":"Mouth to mouth respiration provides what percentage of oxygen ?","o":["10%","16%","21%","100%"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2015","2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (847, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 175, '{"id":847,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":175,"q":"Which of the following anesthetic agent is a potent bronchodilator -","o":["Propofol","Ketamine","Thiopentone","Methoxytone"],"a":1,"e":"Ans. B. Ketamine Ketamine is a potent bronchodilator, therefore it is the i.v. anaesthetic agent of choice in bronchial asthma patients.","pyqMatches":[{"year":"2015","no":1622,"q":"Which of the following anesthetic agent is a potent bronchodilator","o":["Propofol","Ketamine","Thiopentone","Methoxytone"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (848, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 176, '{"id":848,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":176,"q":"Landmark for pudendal nerve block is ?","o":["Ischial tuberosity","Iliac spine","Sacroiliac joint","None of the above"],"a":0,"e":"Ans. A. Ischial tuberosity Pudendal block: When performing a transvaginal pudendal nerve block, the ischial spine is the palpated through the wall of the vagina and the needle is then passed through the vaginal mucous membrane toward the ischial spine. In a perineal pudendal nerve block, the ischial tuberosity is palpated through the buttock and the needle is inserted into the pudendal canal about one inch deep medial to the ischial tuberosity.","pyqMatches":[{"year":"2015","no":1625,"q":"Landmark for pudendal nerve block is ?","o":["Ischial tuberosity","Iliac spine","Sacroiliac joint","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (849, 'Anesthesia', 'Airway Management', 'Hard', 'Anaesthesia', 177, '{"id":849,"subject":"Anesthesia","chapter":"Airway Management","difficulty":"Hard","source":"Anaesthesia","sourceNo":177,"q":"Post dural puncture headache usually presents with in ?","o":["0-6 Hrs","6-12 Hrs","12-72 Hrs","72-96 Hrs"],"a":2,"e":"Ans. C. 12-72 Hrs Post dural puncture headache is due to CSF leak. Typical location is bifrontal or occipital. Headache gets worsen on sitting or upright posture and is relieved by lying down position and abdominal pressure ). The hallmark of postdural puncture headache i.e., association with body position. The onset of headache is usually 12-72 hrs following the procedure, however, it may be seen almost immediately. In most cases it lasts for 7_10 days.","pyqMatches":[{"year":"2015","no":1626,"q":"Post dural puncture headache usually presents with in ?","o":["0-6 Hrs","6-12 Hrs","12-72 Hrs","72-96 Hrs"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (850, 'Anesthesia', 'Local Anesthesia', 'Easy', 'Anaesthesia', 178, '{"id":850,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":178,"q":"Cauda equina syndrome is associated with ?","o":["Lidocaine","Halothane","N20","Ether"],"a":0,"e":"Ans. A. Lidocaine Caudaequina syndrome may occur as a rare devastating complication of spinal anesthesia due to maldistribution of injected local anesthesiaaround caudaequina nerve roots resulting in loss offunction ofthe lumbar plexus. Associated with all local anesthetic like lidocaine, bupivacaine, chlorprocaine etc.","pyqMatches":[{"year":"2015","no":1632,"q":"Cauda equina syndrome is associated with ?","o":["Lidocaine","Halothane","N20","Ether"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (851, 'Anesthesia', 'Local Anesthesia', 'Moderate', 'Anaesthesia', 179, '{"id":851,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Moderate","source":"Anaesthesia","sourceNo":179,"q":"Not included in neuraxial block ?","o":["Spinal block","Epidural block","Bier''s block","Caudal block"],"a":2,"e":"Ans, C. Bier''s block Central neuraxial block, as the name suggests, is the pertains to local anaesthetics placed forwaround the nerves of the central nervous system. Examples are spinal anaesthesia, Epidural anaesthesia and caudallaesthesia. BIER’s block or intravenous regional anesthesia (IVRA) is a form of regional anesthesia used most often for surgery of the forearm and hand.","pyqMatches":[{"year":"2015","no":1627,"q":"Not included in neuraxial block ?","o":["Spinal block","Epidural block","Bier''s block","Caudal block"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (852, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 180, '{"id":852,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":180,"q":"Contraindication to neruaxial block is ?","o":["Hypertension","Renal disease","Clotting disorders","Diabetes"],"a":2,"e":"Ans. C. Clotting disorders Contraindications of central neuroaxial block: Absolute :- Infection at the site of injection, patient refusal, coagulopathyor other bleeding disorder, severe hypovolemia, increased ICT, severe aortic or mitral stenosis. Relative :- Sepsis, unco-operative patient, pre-existing neurological deficit, demyelinating lesions, severe spinal deformity, stenotic valvular heart disease","pyqMatches":[{"year":"2015","no":1628,"q":"Contraindication to neruaxial block is ?","o":["Hypertension","Renal disease","Clotting disorders","Diabetes"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (853, 'Anesthesia', 'Monitoring & Perioperative Care', 'Easy', 'Anaesthesia', 181, '{"id":853,"subject":"Anesthesia","chapter":"Monitoring & Perioperative Care","difficulty":"Easy","source":"Anaesthesia","sourceNo":181,"q":"Most common cause of maternal mortality in spinal anesthesia is ?","o":["Allergy to local anesthesia","Nerve injury","High block","Hypotension"],"a":2,"e":"Ans. C. High block Most common cause of maternal death or brain damage in neuraxial anesthesia claims was high block\"","pyqMatches":[{"year":"2015","no":1631,"q":"Most common cause of maternal mortality in spinal anesthesia is ?","o":["Allergy to local anesthesia","Nerve injury","High block","Hypotension"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (854, 'Anesthesia', 'Local Anesthesia', 'Easy', 'Anaesthesia', 182, '{"id":854,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":182,"q":"Cocaine was first used as local anaesthetic by ?","o":["Carl kollar","Holmer wells","Morton","None"],"a":0,"e":"Ans. A. Carl kollar Cocaine was the first local anesthetic used by Carl Koller. It was used for anaesthetizing cornea.","pyqMatches":[{"year":"2012","no":1387,"q":"Cocaine was first used as local anaesthetic by ?","o":["Carl kollar","Holmer wells","Morton","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (855, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 183, '{"id":855,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":183,"q":"Levels of ether anesthesia were demonstrated by whom?","o":["Morton","Guedel","Thompson","None"],"a":1,"e":"Ans. B. Guedel Guedel described four stages of ether anesthesia known as Guedel stages.","pyqMatches":[{"year":"2012","no":1388,"q":"Levels of ether anesthesia were demonstrated by whom?","o":["Morton","Guedel","Thompson","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (856, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 184, '{"id":856,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":184,"q":"Infant circuit for anaesthesia ?","o":["Bains circuit","Magill circuit","Ayres t piece","Water''s circuit"],"a":2,"e":"Ans. C. Ayres t piece","pyqMatches":[{"year":"2012","no":1389,"q":"Infant circuit for anaesthesia ?","o":["Bains circuit","Magill circuit","Ayres t piece","Water''s circuit"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (857, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 185, '{"id":857,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":185,"q":"Ayre''s T-piece is which type of circuit","o":["Type A","Type B","Type E","Type D"],"a":2,"e":"Ans. C. Type E","pyqMatches":[{"year":"2012","no":1390,"q":"Ayre''s T-piece is which type of circuit","o":["Type A","Type B","Type E","Type D"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (858, 'Anesthesia', 'Airway Management', 'Easy', 'Anaesthesia', 186, '{"id":858,"subject":"Anesthesia","chapter":"Airway Management","difficulty":"Easy","source":"Anaesthesia","sourceNo":186,"q":"Most reliable indicator to prevent oesophageal intubation ?","o":["Oxygen saturation on pulse oximeter","Measurement of CO2 in exhaled air (Etco2)","Direct visualization of passing tube beneath vocal cords","Auscultation over chest"],"a":1,"e":"Ans, B. Measurement of CO2 in exhaled air (Etco2)","pyqMatches":[{"year":"2012","no":1391,"q":"Most reliable indicator to prevent oesophageal intubation ?","o":["Oxygen saturation on pulse oximeter","Measurement of CO2 in exhaled air (Etco2)","Direct visualization of passing tube beneath vocal cords","Auscultation over chest"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (859, 'Anesthesia', 'Airway Management', 'Moderate', 'Anaesthesia', 187, '{"id":859,"subject":"Anesthesia","chapter":"Airway Management","difficulty":"Moderate","source":"Anaesthesia","sourceNo":187,"q":"All are features of difficult airway except ?","o":["Miller''s sign","Micrognathia with macroglossia","TMJ ankylosis","Increased thyromental distance"],"a":3,"e":"Ans. D. Increased thyromental distance Decreased thyromental distance predicts difficult airway (not increased TM distance).","pyqMatches":[{"year":"2012","no":1392,"q":"All are features of difficult airway except ?","o":["Miller''s sign","Micrognathia with macroglossia","TMJ ankylosis","Increased thyromental distance"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (860, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 188, '{"id":860,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":188,"q":"Ratio of 02: N20 in Entonox is ?","o":["50 : 50","60 : 40","40 : 60","25 : 75"],"a":0,"e":"Ans. A. 50 : 50 Entonox contain equal amount (50/50) of N2O and O2.","pyqMatches":[{"year":"2012","no":1393,"q":"Ratio of 02: N20 in Entonox is ?","o":["50 : 50","60 : 40","40 : 60","25 : 75"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (861, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 189, '{"id":861,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":189,"q":"Which is the critical temperature of N20 ?","o":["-118°C","-88°C","-26°C","-36.5°C"],"a":3,"e":"Ans. D. -36.5°C Critical temperature of N2O - 36.5 Critical pressure of N2O - 214.7 atm","pyqMatches":[{"year":"2012","no":1394,"q":"Which is the critical temperature of N20 ?","o":["118°C","88°C","26°C","36.5°C"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (862, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 190, '{"id":862,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":190,"q":"Which anaesthetic agent is neither metabolised by liver nor by kidney ?","o":["Atracurium","Vecuronium","Pancuronium","Rocuronium"],"a":0,"e":"Ans. A. Atracurium","pyqMatches":[{"year":"2012","no":1395,"q":"Which anaesthetic agent is neither metabolised by liver nor by kidney ?","o":["Atracurium","Vecuronium","Pancuronium","Rocuronium"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (863, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 191, '{"id":863,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":191,"q":"Fast induction and recovery is seen in?","o":["Methoxyflurane","Ether","Halothane","N2O"],"a":3,"e":"Ans. D. N2O Speed of onset & recovery in decreasing order (Increasing order of B : G partition coefficient and blood solubility).","pyqMatches":[{"year":"2012","no":1398,"q":"Fast induction and recovery is seen in?","o":["Methoxyflurane","Ether","Halothane","N2O"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (864, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 192, '{"id":864,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":192,"q":"MAC of desflurane is ?","o":["1.15","2","4","6"],"a":3,"e":"Ans. D. 6","pyqMatches":[{"year":"2012","no":1399,"q":"MAC of desflurane is ?","o":["1.15","2","4","6"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (865, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 193, '{"id":865,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":193,"q":"Which can replace N20 as 02 carrier?","o":["Argon","Xenon","Helium","None"],"a":2,"e":"Ans. C. Helium Helium can be used to replace nitrogen, as the carrier gas for oxygen (Helium) to reduce the work of breathing.","pyqMatches":[{"year":"2012","no":1400,"q":"Which can replace N20 as 02 carrier?","o":["Argon","Xenon","Helium","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (866, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 194, '{"id":866,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":194,"q":"Benefit of ketamine ?","o":["Causes decrease in BP","Good analgesic action","Decrease ICT","Decrease IOT"],"a":1,"e":"Ans. B. Good analgesic action Ketamine is different from most other anaesthetic induction agents in that it has significant analgesic action","pyqMatches":[{"year":"2012","no":1404,"q":"Benefit of ketamine ?","o":["Causes decrease in BP","Good analgesic action","Decrease ICT","Decrease IOT"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (867, 'Anesthesia', 'General Anesthesia', 'Easy', 'Anaesthesia', 195, '{"id":867,"subject":"Anesthesia","chapter":"General Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":195,"q":"Which of the following is a sympathomimetic ?","o":["Propofol","Etomidate","Ketamine","N2O"],"a":2,"e":"Ans. C. Ketamine Ketamine has an indirect sympathomimetic action.","pyqMatches":[{"year":"2012","no":1405,"q":"Which of the following is a sympathomimetic ?","o":["Propofol","Etomidate","Ketamine","N2O"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (868, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 196, '{"id":868,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":196,"q":"Which cant be given by Epidural anaesthesia ?","o":["Morphine","Remifentanil","Alfentanil","Fentanyl"],"a":1,"e":"Ans. B. Remifentanil Opioids used for epidural analgesia are morphine, Fentanyl, Tramadol, Buprenorphine, alfentanil, sulfentanil, pentazocine. Ramifentanil contains glycine which can cause motor weakness --à hence not suitable for epidural analgesia.","pyqMatches":[{"year":"2012","no":1409,"q":"Which cant be given by Epidural anaesthesia ?","o":["Morphine","Remifentanil","Alfentanil","Fentanyl"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (869, 'Anesthesia', 'Local Anesthesia', 'Easy', 'Anaesthesia', 197, '{"id":869,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":197,"q":"Addition of epinephrine to lignocaine?","o":["Increaseses distribution of LA","Decreases absorption of LA","Decreases duration of LA","Increases metabolism of LA"],"a":1,"e":"Ans. B. Decreases absorption of LA Vasoconstrictors are used along with LA which prolongs duration of action as rate of absorption is decreased due to vasoconstriction. For the same reason, metabolism of LA is reduced and toxicity is decreased as there is lesser absorption of LA,","pyqMatches":[{"year":"2012","no":1411,"q":"Addition of epinephrine to lignocaine?","o":["Increaseses distribution of LA","Decreases absorption of LA","Decreases duration of LA","Increases metabolism of LA"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (870, 'Anesthesia', 'Local Anesthesia', 'Easy', 'Anaesthesia', 198, '{"id":870,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":198,"q":"Maximum concentration for epidural block ?","o":["Bupivacaine","Lidocaine","Ropivacaine","Chlorprocaine"],"a":3,"e":"Ans, D. Chlorprocaine","pyqMatches":[{"year":"2012","no":1412,"q":"Maximum concentration for epidural block ?","o":["Bupivacaine","Lidocaine","Ropivacaine","Chlorprocaine"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (871, 'Anesthesia', 'Local Anesthesia', 'Easy', 'Anaesthesia', 199, '{"id":871,"subject":"Anesthesia","chapter":"Local Anesthesia","difficulty":"Easy","source":"Anaesthesia","sourceNo":199,"q":"Vasoconstricator L.A. is ?","o":["Cocaine","Procaine","Lidocaine","Chlorprocaine"],"a":0,"e":"Ans. A. Cocaine All LAs are vasodilator except cocaine. Cocaine causes vasoconstriction'' \"Ropivacaine and bupivacaine also cause vasoconstriction\"''","pyqMatches":[{"year":"2012","no":1413,"q":"Vasoconstricator L.A. is ?","o":["Cocaine","Procaine","Lidocaine","Chlorprocaine"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (872, 'Anesthesia', 'Miscellaneous', 'Moderate', 'Anaesthesia', 200, '{"id":872,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anaesthesia","sourceNo":200,"q":"All are contraindications of spinal anaesthesia Except?","o":["Bleeding disorder","Raised intracranial tension","Hypertension","Infection at injection site"],"a":2,"e":"Ans, C. Hypertension","pyqMatches":[{"year":"2012","no":1414,"q":"All are contraindications of spinal anaesthesia Except?","o":["Bleeding disorder","Raised intracranial tension","Hypertension","Infection at injection site"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (873, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 201, '{"id":873,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":201,"q":"For prevention of headache during spinal anaesthesia?","o":["Diluted solution of local anaesthetic should be used","Preloading with crystalloids","Finer I.P. needle should be used","Head end should be elevated"],"a":2,"e":"Ans, C. Finer I.P. needle should be used As single most imPortant predisposing factor is large bore needle use of fine needle prevents PDPH.","pyqMatches":[{"year":"2012","no":1415,"q":"For prevention of headache during spinal anaesthesia?","o":["Diluted solution of local anaesthetic should be used","Preloading with crystalloids","Finer I.P. needle should be used","Head end should be elevated"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (874, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 202, '{"id":874,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":202,"q":"In newborn, chest compression should be started if heart rate is ?","o":["< 120/min","< 100/min","< 80/min","< 60/min"],"a":3,"e":"Ans, D. < 60/min Compression for new born should be started if HR < 60/min''","pyqMatches":[{"year":"2012","no":1416,"q":"In newborn, chest compression should be started if heart rate is ?","o":["< 120/min","< 100/min","< 80/min","< 60/min"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (875, 'Anesthesia', 'Airway Management', 'Easy', 'Anaesthesia', 203, '{"id":875,"subject":"Anesthesia","chapter":"Airway Management","difficulty":"Easy","source":"Anaesthesia","sourceNo":203,"q":"Murphy''s eye is seen in -","o":["Macintosh laryngoscope","Endotracheal tube","LMA","Flexible laryngoscope"],"a":1,"e":"Answer: B - Endotracheal Tube The “Murphy eye” is the eponymous name for a hole on the side of most endotracheal tubes (ETTs) that functions as a vent, and prevents the complete obstruction of the patient''s airway, should the primary distal opening of an ETT become occluded","pyqMatches":[{"year":"2018","no":192,"q":"Murphy''s eye is seen in","o":["Macintosh laryngoscope","Endotracheal tube","LMA","Flexible laryngoscope"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (876, 'Anesthesia', 'Airway Management', 'Easy', 'Anaesthesia', 204, '{"id":876,"subject":"Anesthesia","chapter":"Airway Management","difficulty":"Easy","source":"Anaesthesia","sourceNo":204,"q":"Modified MallamPati grading is used in assessment of -","o":["Difficult intubation","Airway obstruction","Death due to aspiration","Intubation"],"a":0,"e":"Answer: A - Difficulty in intubation Modified Mallampati classification Class 0: Ability to see any part of the epiglottis upon mouth opening and tongue protrusion Class I: Soft palate, fauces, uvula, pillars visible Class II:Soft palate, fauces, uvula visible Class III: Soft palate, base of uvula visible Class IV: Soft palate not visible at all Test: The assessment is performed with the patient sitting up straight, mouth open and tongue maximally protruded, without speaking or saying “ahh.” Difficult laryngoscopy:Good accuracy (area under Summary Receiver Operating Characteristic [SROC] curve 0.89 ± 0.05) Difficult intubation: Good accuracy (area under SROC curve 0.83 ± 0.03) Difficult mask ventilation: Poor predictor Used alone, the Mallampati tests have limited accuracy for predicting the difficult airway and thus are not useful screening tests Mallampati classification is only one of 11 nonreassuring findings during airway examination","pyqMatches":[{"year":"2018","no":193,"q":"Modified MallamPati grading is used in assessment of","o":["Difficult intubation","Airway obstruction","Death due to aspiration","Intubation"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (877, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 205, '{"id":877,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":205,"q":"Which nerve is tested for adequacy of anaesthesia -","o":["Median Nerve","Ulnar Nerve","Radial nerve","Mandibular nerve"],"a":0,"e":"Answer: A - Median nerve Median nerve block can be evaluated by testing the lateral aspect of the ring finger","pyqMatches":[{"year":"2018","no":194,"q":"Which nerve is tested for adequacy of anaesthesia","o":["Median Nerve","Ulnar Nerve","Radial nerve","Mandibular nerve"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (878, 'Anesthesia', 'Miscellaneous', 'Easy', 'Anaesthesia', 206, '{"id":878,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Easy","source":"Anaesthesia","sourceNo":206,"q":"Most effective circuit in spontaneous anaesthesia is -","o":["Mapleson A","Mapleson B","Mapleson C","Mapleson D"],"a":0,"e":"Answer: A - Mapleson A MAPLESON A - (Magill) CIRCUIT Useful in spontaneous ventilation The patient inspires whatever is in the tube, using the bag as a volume reservoir. On eated tube and incoming fresh gas. When the bag is full, exhaled alveolar gas is vented frxpiration, the bag refills from a combination of expired gas going back up the corrugom the exhale valve, and then during any expiratory pause, FGF pushes the remaining alveolar gas out. Theoretically FGF = 0.7 x Valv should prevent significant rebreathing because deadspace gas (fresh) is not wasted, but FGF = VA more reliably prevents rebreathing. Tube volume must exceed (Vt-Vd) or alveolar gas could contaminate the bag. Inadequate FGF causes rebreathing . Difficult to detect from the CO2 waveform alone - all that happens is that the rapid fall on inspiration is delayed. If VA exceeds tubing volume, CO2 enters the bag and will be seen on inspiration on the capnogram. Controlled ventilation If the anaesthetist fully closed the valve while squeezing the bag and didn''t open it until just before the bag filled, this circuit would be OK. More commonly the valve is partially closed - enough to permit adequate tidal volumes despite parallel loss of gas out the valve. FGF must be increased to compensate for gas lost during inspiration - typically 2.5x minute ventilation. The Lack system A co-axial Magill, with the expiratory valve brought coaxially back to the Fresh Gas outlet. Not popular due to inefficiency during controlled ventilation.","pyqMatches":[{"year":"2018","no":195,"q":"Most effective circuit in spontaneous anaesthesia is","o":["Mapleson A","Mapleson B","Mapleson C","Mapleson D"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (879, 'Anesthesia', 'Muscle Relaxants', 'Easy', 'Anaesthesia', 207, '{"id":879,"subject":"Anesthesia","chapter":"Muscle Relaxants","difficulty":"Easy","source":"Anaesthesia","sourceNo":207,"q":"What is mechanism of action of Curanium drugs as muscle relaxant?","o":["Persistently depolarizing at Neuromuscular junction","Act competitively on Ach receptors blocking post-synaptically","Repetitive stimulation of Ach receptors on muscle end plate","Inhibiting the calcium channel on presynaptic membrane"],"a":1,"e":"Answer: B - Act competitively on Ach receptors blocking post- synaptically Candocuronium iodide is an aminosteroid neuromuscular-blocking drug or skeletal muscle relaxant in the category of non-depolarizing neuromuscular-blocking drugs. Acts on Ach receptors competitively post-synaptically blocking them. Potential adjunctive use in anaesthesia to facilitate endotracheal intubation & provide skeletal muscle relaxation. Candocuronium demonstrated a short duration and a rapid onset of action, with little or no ganglion blocking activity, and it was only slightly less potent than pancuronium","pyqMatches":[{"year":"2018","no":196,"q":"What is mechanism of action of Curanium drugs as muscle relaxant?","o":["Persistently depolarizing at Neuromuscular junction","Act competitively on Ach receptors blocking post-synaptically","Repetitive stimulation of Ach receptors on muscle end plate","Inhibiting the calcium channel on presynaptic membrane"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (880, 'Anesthesia', 'Miscellaneous', 'Hard', 'Anaesthesia', 208, '{"id":880,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Hard","source":"Anaesthesia","sourceNo":208,"q":"During squint surgery, anesthesiologist sees the machine and see the bp suddenly drops to 40. What will be best immediate management -","o":["Give atropine","Increase level of anesthesia","Ask the surgeon to stop the surgery","Give adrenaline"],"a":3,"e":"Answer: D. Give adrenaline Adrenaline should be given to raise the blood pressure. Epinephrine, also known as adrenalin or adrenaline, is a hormone, neurotransmitter, and medication. Epinephrine is normally produced by both the adrenal glands and certain neurons. It plays an important role in the fight-or-flight response by increasing blood flow to muscles, output of the heart, pupil dilation, and blood sugar. It does this by binding to alpha and beta receptors. Physiologic responses to epinephrine by organ Organ Effects Heart Increases heart rate; contractility; conduction across AV node Lungs Increases respiratory rate; bronchodilation Systemic Vasoconstriction and vasodilation Liver Stimulates glycogenolysis Systemic Triggers lipolysis Systemic Muscle contraction","pyqMatches":[{"year":"2017","no":242,"q":"During squint surgery, anesthesiologist sees the machine and see the bp suddenly drops to 40. What will be best immediate management","o":["Give atropine","Increase level of anesthesia","Ask the surgeon to stop the surgery","Give adrenaline"],"a":3,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":284,"q":"During squint surgery, anesthesiologist sees the machine and see the bp suddenly drops to 40. What will be best immediate management","o":["Give atropine","Increase level of anesthesia","Ask the surgeon to stop the surgery","Give adrenaline"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (881, 'Anesthesia', 'Miscellaneous', 'Moderate', 'Anaesthesia', 209, '{"id":881,"subject":"Anesthesia","chapter":"Miscellaneous","difficulty":"Moderate","source":"Anaesthesia","sourceNo":209,"q":"Oxygen therapy may not be useful in","o":["Asthma","Pneumonia","Subglottic stenosis","Pulmonary fibrosis"],"a":3,"e":"Ans: D.Pulmonary fibrosis Many EMS protocols indicate that oxygen should not be withheld from any patient, while other protocols are more specific or circumspect. However, there are certain situations in which oxygen therapy is known to have a negative impact on a patient’s condition like paraquat poisoning,pulmonary fibrosis and lung damage resulting from bleomycin treatment.","pyqMatches":[{"year":"2018","no":254,"q":"Oxygen therapy may not be useful in","o":["Asthma","Pneumonia","Subglottic stenosis","Pulmonary fibrosis"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (882, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 1, '{"id":882,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":1,"q":"Plasminogen domain resembles","o":["Fibrinogen","LDL receptor","Apolipoprotein (a)","Prothrombin"],"a":2,"e":"Apolipoprotein (a) REF: http://onlinelibrary.wiley.com/doi/10.1002/pro.5560031222/pdf,http://ww Phylogeny of the serine proteinase domains and analysis of intron- exon boundaries and Kringle sequences indicate that hepatocyte growth factor/scatter factor (HGF/SF), hepatocyte growth factor- like/macrophage stimulating protein (HGFVMSP), plasminogen, and apolipoprotein (a) have evolved from a common ancestral gene. The name Kringle comes from the Scandinavian pastry that these structures resemble.","pyqMatches":[{"year":"2015","no":321,"q":"Plasminogen domain resembles","o":["Fibrinogen","LDL receptor","Apolipoprotein (a)","Prothrombin"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (883, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 2, '{"id":883,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":2,"q":"Boiled cabbage or rancid butter smelling urine is seen in","o":["Phenylketonuria","Tyrosinemia","Isovaleric Acidaemia","Multiple carboxylase deficiency"],"a":1,"e":"Tyrosinemia REF: Sapira''s art & science of bedside diagnosis - Page 138, Textbook of Pediatric Emergency Medicine by Gary R. Fleisher, Stephen Ludwig Page 1566 Tyrosinaemia is an error of metabolism, inherited, in which the body cannot effectively break down the amino acid tyrosine, found in most animal and plant proteins. It is an autosomal recessive, which means two copies of an abnormal gene must be present in order for this to develop. There are three types of tyrosinemia, each with distinctive symptoms and caused by the deficiency of a different enzyme. One of the symptoms of Tyrodinaemia type 1 is an odor like cabbage or rancid butter.","pyqMatches":[{"year":"2015","no":351,"q":"Boiled cabbage or rancid butter smelling urine is seen in","o":["Phenylketonuria","Tyrosinemia","Isovaleric Acidaemia","Multiple carboxylase deficiency"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (884, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 3, '{"id":884,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":3,"q":"True about G protein coupled receptors is:","o":["G proteins bind to hormones on the cell surface","All the three subunits alpha, beta and gamma should bind to each other for G protein to act","G proteins act as inhibitory and excitatory because of difference in alpha subunit","G protein is bound to GTP in resting state"],"a":2,"e":"G proteins act as inhibitory and excitatory because of difference in alpha subunit [Ref: Harper 26/e p458; Lippincott Biochem 3/e p93; Ganong 22/e p41] G-protein coupled receptors (GPCR) are the largest superfamily of cell surface receptors. They typically have seven helices that traverse the membrane. These receptors are integral membrane proteins characterized by an extracellular ligand-binding region, seven transmembrane helices, and an intracellular domain that interacts with G-proteins. The function of GPCR is to transduce signals that induce a cellular response to the environment. Mechanism: The ligand binds to a site on the extracellular portion of the receptor. Binding of the ligand to the receptor * activates a G protein associated with the cytoplasmic C-terminal. This initiates the production of a \"second messenger\". The most common of these are * cyclic AMP, (cAMP) which is produced by adenylyl cyclase from ATP and * inositol 1,4,5-trisphosphate (IP3) The second messenger, in turn, initiates a series of intracellular events such as * phosphorylation and activation of enzymes * release of Ca2+ into the cytosol from stores within the endoplasmic reticulum G proteins G proteins are so-called because they bind the guanine nucleotides GDP and GTP. They are heterotrimers (i.e., made of three different subunits) The three subunits are: * Ga, which carries the binding site for the nucleotide. At least 21 different kinds of Ga molecules are found in mammalian cells. * GP * Gy How They Work In the inactive state G protein has GDP bound to its Ga. subunit. When a hormone or other ligand binds to the associated GPCR the GDP is exchanged for GTP GTP activates Ga causing it to dissociate from GI3Gy (which remain linked as a dimer). Activated Ga in turn activates an effector molecule (adenylyl cyclase- an enzyme in the inner. sface of the plasma membrane which catalyzes the conversion of ATP into the \"second messenger\" cyclic AMP). The beta and gamma subunit do not separate from each other, and Gi3Gy dimer also activates a variety of effectors. The actions of the Ga-GTP complex are short lived because the G- protein has an inherent GTPase activity, resulting in the rapid hydrolysis of GTP to GDP. This leads to reassociation of the Ga unit with the GI3Gy dimer. This inactivates the G protein. The ability of a ligand to stimulate or inhibit the second messenger depends on the type of G-protein that is linked to the receptor. One family of G-proteins, designated Gs, is specific for stimulation of adenylyl cyclase; another family, designated Gi, causes inhibition of the enzyme. These different actions of G proteins are attributed to different alpha subunits. Gs contains a, and Gi contains Some Types of Ga Subunits Gas_This type stimulates (s = \"stimulatory\") adenylyl cyclase. Gas is the target of the toxin liberated by Vibrio cholerae, the bacterium that causes cholera. Binding of cholera toxin to Gas keeps it turned \"on\". The resulting continuous high levels of cAMP causes a massive loss of salts from the cells of the intestinal epithelium. Massive amounts of water follow by osmosis causing a diarrhea that can be fatal if the salts and water are not quickly replaced. Ga;-This inhibits (i = \"inhibitory\") adenylyl cyclase lowering the level of cAMP in the cell. Gag_This activates phospholipase C (PLC) which generates the second messengers: * inositol trisphosphate (IP3) * diacylglycerol (DAG) Gat_The \"t\" is for transducin, the molecule responsible for generating a signal in the rods of the retina in response to light.","pyqMatches":[{"year":"2013","no":228,"q":"True about G protein coupled receptors is:","o":["G proteins bind to hormones on the cell surface","All the three subunits alpha, beta and gamma should bind to each other for G protein to act","G proteins act as inhibitory and excitatory because of difference in alpha subunit","G protein is bound to GTP in resting state"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (885, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 4, '{"id":885,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":4,"q":"Respiratory quotient of carbohydrate is:","o":["0.5","0.8","0.75","1"],"a":3,"e":"Ans: D. 1 The respiratory quotient (or RQ or respiratory coefficient), is a dimensionless number used in calculations of basal metabolic rate (BMR) when estimated from carbon dioxide production. It is calculated from the ratio of carbon dioxide produced by the body to oxygen consumed by the body. Such measurements, like measurements of oxygen uptake, are forms of indirect calorimetry. It is measured using a respirometer. The respiratory quotient (RQ) is the ratio: RQ = CO2 eliminated / O2 consumed","pyqMatches":[{"year":"2015","no":336,"q":"Respiratory quotient of carbohydrate is:","o":["0.5","0.8","0.75","1"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (886, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 5, '{"id":886,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":5,"q":"Essential fatty acids are except:","o":["Arachidonic acid","Linoleic acid","Palmitic acid","Linolenic acid"],"a":0,"e":"The essential fatty acids are polyunsaturated fatty acids, linoleic acid (18:26) and linolenic acid (18:33). Arachidonic acid (20:46) is derived from dietary linoleic acid and is present primarily in membrane phospholipids. Important derivatives of linolenic acid are eicosapentaenoic acid (20:63) and docosahexaenoic acid (DHA, 22:63) found in human milk and brain lipids.Palmitic acid is a common saturated fatty acid. Arachidonic acid (20C: ro6) is not nutritionally essential because chain elongase system can convert linoleic acid (l8C: <o6) into Arachidonic acid (20C: o6). So arachidonic acid is considered as conditionally essential, because it has to be supplied in the diet if linoleic acid is not supplemented. Ref : Botham K.M., Mayes P.A. (2011). Chapter 23. Biosynthesis of Fatty Acids & Eicosanoids. In D.A. Bender, K.M. Botham, P.A. Weil, P.J. Kennelly, R.K. Murray, V.W. Rodwell (Eds), Harper''s Illustrated Biochemistry, 29e.","pyqMatches":[{"year":"2016","no":262,"q":"Essential fatty acids are except:","o":["Arachidonic acid","Linoleic acid","Palmitic acid","Linolenic acid"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (887, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 6, '{"id":887,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":6,"q":"The predominant isozyme of LDH in Lung is:","o":["LD-1","LD-2","LD-3","LD-5"],"a":2,"e":"Isoenzymes of Lactate Dehydrogenase: Lactate dehydrogenase is a tetrameric enzyme and consists of four subunits. These subunits can occurs in two isoforms i.e. H isoform (for heart), M isoform (for muscle). LDH-1 (4H) - in the heart and RBCs LDH-2 (3H1M) - in the reticuloendothelial system LDH-3 (2H2M) - in the lungs LDH-4 (1H3M) - in the kidneys, placenta, and pancreas LDH-5 (4M) - in the liver and striated muscle Normal value of LDH in serum is 100-200 U/L. LDH level is 100 times more inside the RBC than in plasma, and therefore minor amount of hemolysis will result in a false positive test. Ref: Harper’s Illustrated Biochemistry, 26th Edition, Page 57; Textbook of Biochemistry By Vasudevan, 5th Edition, Page 53","pyqMatches":[{"year":"2015","no":479,"q":"The predominant isozyme of LDH in Lung is:","o":["LD-1","LD-2","LD-3","LD-5"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (888, 'Biochemistry', 'Carbohydrate Metabolism', 'Moderate', 'Biochemistry', 7, '{"id":888,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":7,"q":"Substrate level phosphorylation occur in step catalysed by which of the following enzyme in TCA cycle?","o":["Isocitrate dehydrogenase","Malate dehydrogenase","Aconitase","Succinate thiokinase"],"a":3,"e":"Succinate thiokinase is the enzyme that generates ATP directly by substrate-level phosphorylation. In Krebs cycle succinate thiokinase catalyze the conversion of Succinyl CoA into succinate. In this step GDP is phosphorylated to GTP. GTP can then be converted to ATP by reacting with an ADP molecule. Substrate-level phosphorylation is a type of metabolism that results in the formation and creation of adenosine triphosphate (ATP) or guanosine triphosphate (GTP) by the direct transfer and donation of a phosphoryl (P03) group to adenosine diphosphate (ADP) or guanosine diphosphate (GDP) from a phosphorylated reactive intermediate. In glycolysis substrate level phosphorylation occur in two steps: Conversion of 1,3 BPG to 3 Phosphoglycerate catalyzed by Phosphoglycerate kinase Conversion of Phosphoenolpyruvate to pyruvate catalyzed by Pyruvate kinase Ref: Textbook of Biochemistry By D M Vasudevan, 3rd Edition, Page 195","pyqMatches":[{"year":"2012","no":252,"q":"Substrate level phosphorylation occur in step catalysed by which of the following enzyme in TCA cycle?","o":["Isocitrate dehydrogenase","Malate dehydrogenase","Aconitase","Succinate thiokinase"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (889, 'Biochemistry', 'Carbohydrate Metabolism', 'Hard', 'Biochemistry', 8, '{"id":889,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Hard","source":"Biochemistry","sourceNo":8,"q":"Phosphofructokinase-1 occupies a key position in regulating glycolysis and is also subjected to feedback control. Which among the following is the allosteric activators of phosphofructokinase-1?","o":["Fructose 2, 3 bisphosphate","Fructose 2, 6 bisphosphate","Glucokinase","PEP"],"a":1,"e":"The most potent positive allosteric activator of phosphofructokinase-1 and inhibitor of fructose 1,6-bisphosphatase in the liver is fructose 2,6-bisphosphate. It relieves inhibition of phosphofructokinase-1 by ATP and increases the affinity for fructose 6-phosphate. It inhibits fructose 1,6-bisphosphatase by increasing the Km for fructose 1,6-bisphosphate. Its concentration is under both substrate (allosteric) and hormonal control (covalent modification). Phosphofructokinase-1 is inhibited by citrate and by normal intracellular concentrations of ATP and is activated by 5'' AMP. Ref: Bender D.A., Mayes P.A. (2011). Chapter 20. Gluconeogenesis & the Control of Blood Glucose. In D.A. Bender, K.M. Botham, P.A. Weil, P.J. Kennelly, R.K. Murray, V.W. Rodwell (Eds), Harper''s Illustrated Biochemistry, 29e.","pyqMatches":[{"year":"2013","no":266,"q":"Phosphofructokinase-1 occupies a key position in regulating glycolysis and is also subjected to feedback control. Which among the following is the allosteric activators of phosphofructokinase-1?","o":["Fructose 2, 3 bisphosphate","Fructose 2, 6 bisphosphate","Glucokinase","PEP"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (890, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 9, '{"id":890,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":9,"q":"Enzymes of glycolysis are found in:","o":["Cytosol","Cell membrane","Mitochondria","Ribososmes"],"a":0,"e":"All of the enzymes of glycolysis are found in the cytosol. Ref: Harper 28th edition, chapter 18.","pyqMatches":[{"year":"2012","no":260,"q":"Enzymes of glycolysis are found in:","o":["Cytosol","Cell membrane","Mitochondria","Ribososmes"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (891, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 10, '{"id":891,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":10,"q":"The Fenton reaction leads to free radical generation when:","o":["Radiant energy is absorbed by water","Ferrous ions are converted to ferric ions","Nitric oxide is converted to peroxynitrite anion","Hydrogen peroxide is formed by, myeloperoxidase"],"a":1,"e":"Fenton reaction involves the ferrous iron catalyzed conversion of hydrogen peroxide into a hydroxide ion and a hydroxyl free radical with the concurrent oxidation of ferrous iron to ferric iron. Fenton reaction: H.J.H Fenton discovered in 1894 that several metals have a special oxygen transfer properties which improve the use of hydrogen peroxide. Actually, some metals have a strong catalytic power to generate highly reactive hydroxyl radicals (.OH). Since this discovery, the iron catalyzed hydrogen peroxide has been called Fenton''s reaction. Hydrogen peroxide is converted to hydroxyl radicals in the Fenton reaction. The iron can exist in a number of different oxdation states. Therefore the oxidation of fe2+ by h2o2 can proceed through a one electron transfer or a two electron transfer. Fentons reaction is an inner sphere one electron transfer process. The h2o2 forms a complex with fe2+ before electron transfer takes place. After addition of the iron and the hydrogen peroxide, they are going to react together to generate some hydroxyl radicals as it shows in the following equations: Fe2+ + H2O2 ----> Fe3+ + .OH + OH- Fe3+ + H2O2 ----> Fe2+ + .OOH + H+ Importance: Hydroxyl radicals are the most powerful of the reactive oxygen species.It is capable of destroying any organic molecule. Uses: Used to treat a large variety of water pollution such as phenols, formaldehyde, BTEX, pesticides and rubber chemicals. Ref: Free Radicals in Medicine, By Radu Olinescu, Dr. Terrance L. Smith, Page 28","pyqMatches":[{"year":"2014","no":378,"q":"The Fenton reaction leads to free radical generation when:","o":["Radiant energy is absorbed by water","Ferrous ions are converted to ferric ions","Nitric oxide is converted to peroxynitrite anion","Hydrogen peroxide is formed by, myeloperoxidase"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (892, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 11, '{"id":892,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":11,"q":"The mechanism of action of uncouplers of oxidative phosphorylation involves:","o":["Inhibition of ATP synthase","Stimulation of ATP synthase","Disruption of proton gradient across the inner membrane","Disruption of proton gradient across outer membrane"],"a":2,"e":"Uncouplers are protein carriers that can freely pass through the inner mitochondrial membrane. It allows translocation of the protons into the intermembranous space during the electron transport in the respiratory chain but blocks the formation of proton gradient across the inner mitochondrial membrane. Thermogenin a protein present in the inner mitochondrial membrane of adipocytes is an example of physiologic uncouplers of oxidative phosphorylation. Examples of uncouplers are: 2,4 dinitrophenol, pentachlorophenol, nigericin, thyroxin and thermogenin. Ref: Jaypee''s Review of Med. Biochemistry By S. M. Raju page 102.","pyqMatches":[{"year":"2015","no":300,"q":"The mechanism of action of uncouplers of oxidative phosphorylation involves:","o":["Inhibition of ATP synthase","Stimulation of ATP synthase","Disruption of proton gradient across the inner membrane","Disruption of proton gradient across outer membrane"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (893, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 12, '{"id":893,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":12,"q":"Which of the following is the rate limiting step in cholesterol synthesis?","o":["HMG CoA synthase","HMG CoA reductase","Thiokinase","Mevalonate kinase"],"a":1,"e":"Initially in cholesterol synthesis, two molecules of acetyl-CoA condense to form acetoacetyl- CoA catalyzed by cytosolic thiolase. Acetoacetyl-CoA condenses with a further molecule of acetyl-CoA catalyzed by HMG-CoA synthase to form HMG-CoA, which is reduced to mevalonate by NADPH in a reaction catalyzed by HMG-CoA reductase. This last step is the principal regulatory step in the pathway of cholesterol synthesis and is the site of action of the most effective class of cholesterol-lowering drugs, the statins, which are HMG-CoA reductase inhibitors. Ref: Botham K.M., Mayes P.A. (2011). Chapter 26. Cholesterol Synthesis, Transport, & Excretion. In D.A. Bender, K.M. Botham, P.A. Weil, P.J. Kennelly, R.K. Murray, V.W. Rodwell (Eds), Harper''s Illustrated Biochemistry, 29e.","pyqMatches":[{"year":"2014","no":304,"q":"Which of the following is the rate limiting step in cholesterol synthesis?","o":["HMG CoA synthase","HMG CoA reductase","Thiokinase","Mevalonate kinase"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (894, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 13, '{"id":894,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":13,"q":"Which one of the following can be a homologous substitution for isoleucine in a protein sequence?","o":["Methionine","Aspartic acid","Valine","Arginine"],"a":2,"e":"Isoleucine is one of the aminoacid with an aliphatic side chain. Other aminoacids with an aliphatic side chain is glycine, alanine, valine and leucine. Among the options provided, valine is the only aminoacid with an aliphatic side chain and so it can be a homologous substitution for isoleucine in a protein sequence. Ref: Harper’s Illustrated Biochemistry, 26th Edition, Chapter 3, Page 15; Human Gene Evolution By David N. Cooper, 1999, Page 299.","pyqMatches":[{"year":"2014","no":318,"q":"Which one of the following can be a homologous substitution for isoleucine in a protein sequence?","o":["Methionine","Aspartic acid","Valine","Arginine"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (895, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 14, '{"id":895,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":14,"q":"Albinism is due to deficiency of the following enzyme?","o":["Phenylalanine hydroxylase","Homogentisic acid oxidase","Tyrosinase","Decarboxylase"],"a":2,"e":"The most common cause of albinism is a defect in tyrosinase, the enzyme most responsible for the synthesis of melanin. Albinism is an inborn error due to lack of synthesis of melanin. It is an autosomal recessive disorder with a frequency of 1 in 20,000. Ref: Textbook of Biochemistry and Human Biology by G. P. Talwar, 3rd Ed, Page 452","pyqMatches":[{"year":"2016","no":1376,"q":"Albinism is due to deficiency of the following enzyme?","o":["Phenylalanine hydroxylase","Homogentisic acid oxidase","Tyrosinase","Decarboxylase"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (896, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 15, '{"id":896,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":15,"q":"Which among the following glucose transporter present in beta cells ?","o":["GLUT1","GLUT2","GLUT3","GLUT4"],"a":1,"e":"GLUT2 is the glucose transporter present in the betacells and liver cells.It has a high Km for glucose.Hence entry of glucose is directly proportional to the glucose level.It is an insul;in independent transport. GLUT3 is present in brain and GLUT4 medites insulin dependent transport of glucose into muscle and adipose tissue. Ref: Murray R.K., Granner D.K. (2011). Chapter 40. Membranes: Structure & Function. In D.A. Bender, K.M. Botham, P.A. Weil, P.J. Kennelly, R.K. Murray, V.W. Rodwell (Eds), Harper''s Illustrated Biochemistry, 29e.","pyqMatches":[{"year":"2016","no":248,"q":"Which among the following glucose transporter present in beta cells ?","o":["GLUT1","GLUT2","GLUT3","GLUT4"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (897, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 16, '{"id":897,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":16,"q":"What is the role of catabolite activator protein (CAP) in LAC operon?","o":["Positive regulator","Negative regulator","Attenuation","Constitutive expression"],"a":0,"e":"Catabolite activator protein, CAP is an activator required for high level transcription of the lac operon. CAP protein exerts positive control and lac repressor exerts negative control. What is an Operon? In prokaryotes, the genes coding for proteins involved in a particular metabolic pathway are often sequentially arranged- together on the chromosome along with a single promoter or regulatory region. This entire cluster is termed as an operon, for eg, the lac operon (coding proteins for metabolism of lactose) or trp operon (coding proteins needed for the synthesis of tryptophan). Lac operon: Lac operon contains lacZ, lacY and lacA genes encoding beta galactosidase, galactose permease and thiogalactoside transacetylase and is preced by an operator (O) site and promoter (P) site. The operon is transcribed by RNA polymerase to produce a single polycistronic mRNA that is translated to produce all three enzymes which are involved in lactose metabolism.","pyqMatches":[{"year":"2016","no":336,"q":"What is the role of catabolite activator protein (CAP) in LAC operon?","o":["Positive regulator","Negative regulator","Attenuation","Constitutive expression"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (898, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 17, '{"id":898,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":17,"q":"True about glutamate dehydrogenase is A/E","o":["Liver mitochondrial enzyme","Use both NAD* or NADP+ coenzyme","Inhibited by ADP & activated by GTP","Reversible oxidative deamination"],"a":2,"e":"C i.e. Inhibited by ADP & activated by GTP During first few days of fasting, there is rapid breakdown of muscle protein, providing aminoacids (alanine & glutamine mainly) that are used by liver for gluconeognesisQ. In the fasting state, the output of alanine from skeleton muscle is in far excess of its concentration in the muscle proteins that are being catabolized. Because it is also formed by transamination of pyruvate produced by glycolysis of muscle glycogen. Alanine is exported to the liver, where it is transaminated back to pyruvate, which serves as a substrate for gluconeogenesisQ.","pyqMatches":[{"year":"2016","no":287,"q":"True about glutamate dehydrogenase is A/E","o":["Liver mitochondrial enzyme","Use both NAD* or NADP+ coenzyme","Inhibited by ADP & activated by GTP","Reversible oxidative deamination"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (899, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 18, '{"id":899,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":18,"q":"Among the following, the maximum redox potential is for:","o":["NADH/NAD","Succinate/Fumarate","Ubiquinone","Fe+3/ Fe+2"],"a":3,"e":"Ans. D i.e. Fe+3/ Fe+2 Because electrons tend to flow spontaneously from carries of lower redox potential (E°) to carries of higher redox potential. The order (sequence) of electron carriers in ETC of mitochondria (and so the increasing order of redox potential) is Substrate --> NADP+ /NADPH —> NADVNADH —› NADH dehydrogenase (FMN) / NADH dehydrogenase (FMNH2) —> FAD/FADH2 —> Ubiquinone or Coenzyme Q —> Fe3+ / Fee* in cytochromes b —> C —> a -+ a3 —> 02","pyqMatches":[{"year":"2012","no":256,"q":"Among the following, the maximum redox potential is for:","o":["NADH/NAD","Succinate/Fumarate","Ubiquinone","Fe+3/ Fe+2"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (900, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 19, '{"id":900,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":19,"q":"(β-oxidation of palmitic acid yields","o":["3 acetyl CoA","129 ATP net","131 ATP net","16 Acetyl CoA"],"a":1,"e":"B i.e. 129 ATP net","pyqMatches":[{"year":"2015","no":319,"q":"(β-oxidation of palmitic acid yields","o":["3 acetyl CoA","129 ATP net","131 ATP net","16 Acetyl CoA"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (901, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 20, '{"id":901,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":20,"q":"Refsum''s disease is due to deficiency of which of the following enzyme?","o":["Malonate dehydrogease","Thiophorase","Succinate thiokinase","Phytanic alpha oxidase"],"a":3,"e":"D i.e. Phytanic alpha oxidase Refsum''s disease is a rare autosomal recessive disorder caused by deficiency of phytanic a oxides (Nelson) / a?hydroxylase (Lippincot) / Phytanoyl CoA hydroxylase (Lehninger) results in accumulation of phytanic acid due to its decreased a - oxidation (i.e. hydroxnlation at a carbon by fatty acid a hydroxylase)","pyqMatches":[{"year":"2016","no":274,"q":"Refsum''s disease is due to deficiency of which of the following enzyme?","o":["Malonate dehydrogease","Thiophorase","Succinate thiokinase","Phytanic alpha oxidase"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (902, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 21, '{"id":902,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":21,"q":"Energy source used by brain in later days of Starvation is","o":["Glucose","Ketone bodies","Glycogen","Fatty acids"],"a":1,"e":"B i.e. Ketone bodies","pyqMatches":[{"year":"2015","no":339,"q":"Energy source used by brain in later days of Starvation is","o":["Glucose","Ketone bodies","Glycogen","Fatty acids"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (903, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 22, '{"id":903,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":22,"q":"In starvation, nitrogen is carried from muscle to liver and kidney by:","o":["Alanine","Aspartic acid and Serine","Glycine","Asparagines"],"a":0,"e":"A i.e. Alanine In starvation , alanine and glutamine are quantitatively the most important gluconeogenic aminoacidsQ. So alanine carries nitrogen from muscle to liver & kidney for further metabolism & energy production during starvation.","pyqMatches":[{"year":"2012","no":343,"q":"In starvation, nitrogen is carried from muscle to liver and kidney by:","o":["Alanine","Aspartic acid and Serine","Glycine","Asparagines"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (904, 'Biochemistry', 'Enzymes', 'Moderate', 'Biochemistry', 23, '{"id":904,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Moderate","source":"Biochemistry","sourceNo":23,"q":"The gaps between segments of DNA on the lagging strand produced by restriction enzymes are rejoined sealed by:","o":["DNA Ligases","DNA Helicase","DNA topoisomerase","DNA phosphorylase"],"a":0,"e":"A i.e. DNA Ligases","pyqMatches":[{"year":"2015","no":361,"q":"The gaps between segments of DNA on the lagging strand produced by restriction enzymes are rejoined sealed by:","o":["DNA Ligases","DNA Helicase","DNA topoisomerase","DNA phosphorylase"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (905, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 24, '{"id":905,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":24,"q":"Replication and transcription are similar processes in mechanistic terms because both :","o":["Use RNA primers for initiation.","Use deoxyribonucleotides as precursors.","Are semi conserved events","Involve phosphodiester bond formation with elongation occurring in the 5'' - 3'' direction"],"a":3,"e":"D i.e. Involve phosphodiester bond formation with elongation occurring in the 5''- 3'' direction. In both DNA and RNA synthesis, the general steps of initiation, elongation and termination occur in 5''- 3'' direction with the formation of phosphodiester bondsQ.","pyqMatches":[{"year":"2015","no":355,"q":"Replication and transcription are similar processes in mechanistic terms because both :","o":["Use RNA primers for initiation.","Use deoxyribonucleotides as precursors.","Are semi conserved events","Involve phosphodiester bond formation with elongation occurring in the 5'' - 3'' direction"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (906, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 25, '{"id":906,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":25,"q":"The anticodon region is an important part of the","o":["r-RNA","m-RNa","t-RNa","hn-RNa"],"a":2,"e":"C i.e. t - RNA","pyqMatches":[{"year":"2012","no":377,"q":"The anticodon region is an important part of the","o":["r-RNA","m-RNa","t-RNa","hn-RNa"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (907, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 26, '{"id":907,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":26,"q":"Km value is defined as:","o":["Substrate concentration at Vmax/2","Substrate concentration of twice Vmax","Substrate concentration of thrice Vmax","Substrate concentration of one third Vmax"],"a":0,"e":"Ans. A. Substrate concentration at Vmax/2","pyqMatches":[{"year":"2012","no":246,"q":"Km value is defined as:","o":["Substrate concentration at Vmax/2","Substrate concentration of twice Vmax","Substrate concentration of thrice Vmax","Substrate concentration of one third Vmax"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (908, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 27, '{"id":908,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":27,"q":"Enzyme activity is expressed as:","o":["Millimoles /lit?","Milli gm/lit?","Mg/ dl","Micromoles/min"],"a":3,"e":"Ans. is. D. Micromoles/min","pyqMatches":[{"year":"2015","no":295,"q":"Enzyme activity is expressed as:","o":["Millimoles /lit?","Milli gm/lit?","Mg/ dl","Micromoles/min"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (909, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 28, '{"id":909,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":28,"q":"Which of the following is a serine protease","o":["Chymotrypsin","Pepsin","Carboxypeptidase","Caspases"],"a":0,"e":"Ans. is''a''i.e., Chymotrypsin lRef: Chatterjee 7h/e p. 4j5-361 * The term Protease is used to represent the group of enzymes that catalyze the cleavage ofpeptide bonds in proteins and peptide molecules with the participation of water as co-reactant. In simple words, proteases catalyze the cleavage of peptide bonds by hydrolysis (addition of water Serine proteases:- * These posses a critical serine residue at the active site. - Example of serine proteases are trypsin, chymotrypsin, elastase, and thrombin. * Serine proteases are inhibited by disopropylphosphofluridate which binds covalently to serine residue. - The active site of serine proteases contain three critical amino acids serine, histidine and aspartate. These residues are often referred to as catalytic triad","pyqMatches":[{"year":"2016","no":261,"q":"Which of the following is a serine protease","o":["Chymotrypsin","Pepsin","Carboxypeptidase","Caspases"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (910, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 29, '{"id":910,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":29,"q":"Creatinine is formed from :","o":["Arginine","Lysine","Leucine","Histamine"],"a":0,"e":"Glycine, arginine and methionine all participate in creatine biosynthesis","pyqMatches":[{"year":"2015","no":331,"q":"Creatinine is formed from","o":["Glycine","Lysine","Leucine","Histamine"],"a":0,"source":"NEET_2015_Paper.pdf"},{"year":"2016","no":281,"q":"Creatinine is formed from :","o":["Arginine","Lysine","Leucine","Histamine"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2015","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (911, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 30, '{"id":911,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":30,"q":"Acidic amino acids are -","o":["Asparagine","Arginine","None","Lysine"],"a":0,"e":"Proline is a unique amino acid and has an immino group (=NH) instead of an amino (NH2) group found in other amino acid. Methionine & Cysteine are sulfur containing aminoacids. The property of photochromicity (i.e. absorbance of ultraviolet light at 250-290nm esp 280nm) is seen with aromatic amino acid (tryptophan > tyrosine > phenylalanine). Hydrophobic (non polar) aminoacids have no charge on their R group or side chain. Aliphatic (eg methyl, methylene, thioether & imino) side chains and aromatic side chains are nonpolar. So methyl (CH3) side chain of alanine; propyl (C3H7) side chain of valine; butyl (C4H9) side chain of leuicine & isoleucine; thioether side chain of methionine; and imino group/ pyrrolidine containing side chain of proline are nonpolar. Methyl (CH3) side chain of alanine is nonpolar. Serine, threonine, tyrosine containing hydroxyl group and cysteine containing sulfhydryl group, are polar aminoacids with neutral/uncharged/nonionic side chain. Positively charged basic amino (NH 3 +)group side chain of histidine, arginine and lysine ; and negatively acidic carboxyl (COO-) side chain of aspartic acid and glutamic acid is polar.","pyqMatches":[{"year":"2016","no":282,"q":"Acidic amino acids are","o":["Asparagine","Arginine","None","Lysine"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (912, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 31, '{"id":912,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":31,"q":"Non-Essential amino acid is -","o":["Tyrosine","Phenylalanine","Lysine","Threonine"],"a":0,"e":"Ans. A. Tyrosine","pyqMatches":[{"year":"2012","no":316,"q":"Non-Essential amino acid is","o":["Tyrosine","Phenylalanine","Lysine","Threonine"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (913, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 32, '{"id":913,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":32,"q":"Detergent action of bile salts is due to:","o":["Hydropathic","Acts as a zwitter ion","Amphipathic","All"],"a":2,"e":"Ans. C. Amphipathic","pyqMatches":[{"year":"2013","no":185,"q":"Detergent action of bile salts is due to:","o":["Hydropathic","Acts as a zwitter ion","Amphipathic","All"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (914, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 33, '{"id":914,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":33,"q":"Heme synthesis requires","o":["Ferrous iron","Glycine","Succhyl CoA","All"],"a":3,"e":"No separate explanation was provided in the source.","pyqMatches":[{"year":"2014","no":362,"q":"Heme synthesis requires","o":["Ferrous iron","Glycine","Succhyl CoA","All"],"a":3,"source":"NEET_2014_Paper.pdf"},{"year":"2016","no":343,"q":"Heme synthesis requires","o":["Ferrous iron","Glycine","Succhyl CoA","All"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2014","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (915, 'Biochemistry', 'Molecular Biology', 'Moderate', 'Biochemistry', 34, '{"id":915,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Moderate","source":"Biochemistry","sourceNo":34,"q":"Tumor suppressor gene is not involved in ?","o":["Breast cancers","Neurofibromatosis","Multiple endocrine neoplasia","Retinoblastoma"],"a":2,"e":"o Multiple endocrine neoplasia involves RET protooncogene (not tumor suppressor gene).","pyqMatches":[{"year":"2013","no":430,"q":"Tumor suppressor gene is not involved in ?","o":["Breast cancers","Neurofibromatosis","Multiple endocrine neoplasia","Retinoblastoma"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (916, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 35, '{"id":916,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":35,"q":"In Endometrial carcinoma, which of the following tumor suppressor gene occurs?","o":["P53","Rb","PTEN","APC"],"a":2,"e":"PTEN is a tumor suppressor gene which is implicated in the causation of endometrial and prostate carcinoma.","pyqMatches":[{"year":"2016","no":490,"q":"In Endometrial carcinoma, which of the following tumor suppressor gene occurs?","o":["P53","Rb","PTEN","APC"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (917, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 36, '{"id":917,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":36,"q":"Telomerase -","o":["RNA polymerase","Causes carcinogenesis","Present in somatic cells","Absent in germ cells"],"a":1,"e":"Telomerase is a DNA polymerase (RNA dependent DNA polymerase) which is present in germ cells and is absent from most somatic cells. Thus telomerase activity and maintenance of telomere length are essential for the replicative potential in cancer cells.","pyqMatches":[{"year":"2012","no":440,"q":"Telomerase","o":["RNA polymerase","Causes carcinogenesis","Present in somatic cells","Absent in germ cells"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (918, 'Biochemistry', 'Genetics', 'Easy', 'Biochemistry', 37, '{"id":918,"subject":"Biochemistry","chapter":"Genetics","difficulty":"Easy","source":"Biochemistry","sourceNo":37,"q":"E cadherin gene deficiency is seen in -","o":["Gastric ca","Intestinal ca","Thyroid ca","Pancreatic ca"],"a":0,"e":"The majority of gastric cancers are not hereditary, the mutations identified in familial gastric cancer have provided important insights into mechanism of carcinogenesis in sporadic cancers. Germline mutations in CDHI, which encodes E cadherin, a protein that contributes to epithelial intercellular adhesion are associated with familial gastric cancers, which are usually of diffuse type. Mutations in CDH 1 are present in about 50% of sporadic cases of diffuse gastric cancers, while E cadherin expression is drastically decreased in the rest, often by methylation of the CDH I promotor. Lobular carcinoma of breast which also tends to infilterate as single cells, & individuals with BRCA2 mutations are at increased risk of developing diffuse gastric cancers.","pyqMatches":[{"year":"2012","no":488,"q":"E cadherin gene deficiency is seen in","o":["Gastric ca","Intestinal ca","Thyroid ca","Pancreatic ca"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (919, 'Biochemistry', 'Genetics', 'Easy', 'Biochemistry', 38, '{"id":919,"subject":"Biochemistry","chapter":"Genetics","difficulty":"Easy","source":"Biochemistry","sourceNo":38,"q":"Li–Fraumeni syndrome is due to mutation of which gene -","o":["P 21","P 53","P 41","P 43"],"a":1,"e":"Cancer arises through a series of somatic alterations in DNA that result in uncontrolled cell division. Human cancers have following important etiological factors ? Genetic predisposition to cancer Non-hereditary predisposing conditions Geographic and environmental factors Genetic (Hereditary or inherited) predisposition to cancer A large number of cancers have hereditary predispositions. Genetic predisposition may be of three types. Autosomal dominant Inherited cancer syndromes This is the most common type of genetic predisposition. The mechanism involves uncontrolled cell division due to germline mutation of cancer suppressor gene. Gene Inherited predisposition RB Retinoblastoma p53 Li-fraumeni syndrome pl6INK4A Melanoma APC Familial adenomatous polyposis/colon cancer NF-1, NF-2 Neurofibromatosis 1 and 2 BRAC 1 BRAC 2 Neurofibromatosis 1 and 2 BRAC-1, BRAC-2 Neurofibromatosis 1 and 2 MEN 1, RET Multiple endocrine neoplasia MSN 2, MLH 1, MSH 6 Heriditary nonpolyposis colon cancer PATCH Nevoid basal cell carcinoma syndrome","pyqMatches":[{"year":"2012","no":437,"q":"Li–Fraumeni syndrome is due to mutation of which gene","o":["P 21","P 53","P 41","P 43"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (920, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 39, '{"id":920,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":39,"q":"Which element is required by phosphofructokinase?","o":["Magnesium","Inorganic phosphate","Manganese","Copper"],"a":0,"e":"Phosphofructokinase (PFK) is —300 amino acids in length, and structural studies of the bacterial enzyme have shown it comprises two similar (alpha/beta) lobes: one involved in ATP binding and the other housing both the substrate-binding site and the allosteric site (a regulatory binding site distinct from the active site, but that affects enzyme activity). The identical tetramer subunits adopt 2 different conformations: in a ''closed'' state, the bound magnesium ion bridges the phosphoryl groups of the enzyme products (ADP and fructose- 1,6- bisphosphate); and in an ''open'' state, the magnesium ion binds only the ADP, as the 2 products are now further apart","pyqMatches":[{"year":"2013","no":245,"q":"Which element is required by phosphofructokinase?","o":["Magnesium","Inorganic phosphate","Manganese","Copper"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (921, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 40, '{"id":921,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":40,"q":"Carbamoyl phosphate synthetase I is:","o":["Lysosolic enzyme","Cytosolic enzyme","Mitochondrial enzyme","All of the above"],"a":2,"e":"Mitochondrial carbamoyl phosphate synthetase I is an enzyme that catalyzes a reaction that produces carbamoyl phosphate. This enzyme catalyzes the reaction of ATP and bicarbonate to produce carbonyl phosphate and ADP. Carbonyl phosphate reacts with ammonia to give carbamate Cytosolic carbamoyl phosphate synthetase II uses glutamine rather than ammonia as the nitrogen donor and functions in pyrimidine synthesis.","pyqMatches":[{"year":"2016","no":291,"q":"Carbamoyl phosphate synthetase I is:","o":["Lysosolic enzyme","Cytosolic enzyme","Mitochondrial enzyme","All of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (922, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 41, '{"id":922,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":41,"q":"Which of the following is required for proper effects of Insulin?","o":["Selenium","Iron","Copper","Chromium"],"a":3,"e":"In association with insulin, chromium promotes the utilization of glucose Chromium is a component of a protein namely chromodulin which facilitates the binding of insulin to cell receptor sites Chromium It is an essential nutrient for the maintenance of normal glucose tolerance Its deficiency causes insulin resistance. Chromium administration has also been shown in several studies to lower glucose and insulin levels in patients with type 2 diabetes. It has been classified as not essential for mammals. (Cr (III) or Cr3+). Chromium deficiency is controversial or is at least extremely rare. It has been attributed to only three people on parenteral nutrition, which is when a patient is fed a liquid diet through intravenous drips. In contrast, hexavalent chromium (Cr (VI) or Cr6+) is very toxic and mutagenic when inhaled. Cr (VI) has not been established as a carcinogen when in solution, although it may cause allergic contact dermatitis (ACD). Dietary supplements for chromium include chromium (III) picolinate, chromium (III) polynicotinate, and related materials. Glutathione peroxidase requires selenium Copper is an important constituent of catalse, cytochrome oxidase and tyrosinase. Zinc is also necessary for the storage and secretion of insulin","pyqMatches":[{"year":"2015","no":1133,"q":"Which of the following is required for proper effects of Insulin?","o":["Selenium","Iron","Copper","Chromium"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (923, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 42, '{"id":923,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":42,"q":"Glycemic index is defined as:","o":["Glucose control in last 3 months","Measure of the change in the blood glucose following ingestion of proteins","Measure of the change in the blood glucose following ingestion of carbohydrate","Measure of the change in the blood glucose following ingestion of fats."],"a":2,"e":"The Glycemic index (GI) of a carbohydrate containing food is a measure of the change in the blood glucose following its ingestion","pyqMatches":[{"year":"2015","no":890,"q":"Glycemic index is defined as:","o":["Glucose control in last 3 months","Measure of the change in the blood glucose following ingestion of proteins","Measure of the change in the blood glucose following ingestion of carbohydrate","Measure of the change in the blood glucose following ingestion of fats."],"a":2,"source":"NEET_2015_Paper.pdf"},{"year":"2016","no":352,"q":"Glycemic index is defined as:","o":["Glucose control in last 3 months","Measure of the change in the blood glucose following ingestion of proteins","Measure of the change in the blood glucose following ingestion of carbohydrate","Measure of the change in the blood glucose following ingestion of fats."],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2015","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (924, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 43, '{"id":924,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":43,"q":"Which of the following is known as suicidal enzyme?","o":["Lipoxygenase","Cyclooxygenase","Thromboxane synthatase","5'' nucleotidase"],"a":1,"e":"Suicidal enzyme is one, which undergoes self-destruction in order to terminate its own acitivity, e.g. Cyclooxygenase. Suicidal Inhibition is conversion of a substrate by the enzyme into a metabolite, which is a potent inhibitor of the enzyme; example: Xanthine oxidase converts allopurinol to alloxanthine (oxypurinol), which is a more potent inhibitor of allopurinol. Cycloorygenase is known as suicide enzyme because it catalyzes its own destruction.","pyqMatches":[{"year":"2015","no":293,"q":"Which of the following is known as suicidal enzyme?","o":["Lipoxygenase","Cyclooxygenase","Thromboxane synthatase","5'' nucleotidase"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (925, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 44, '{"id":925,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":44,"q":"Which of the following enzyme is not a component of fatty acid synthase complex?","o":["Acetyl Co-A carboxylase","Ketoacyl synthase","Enoyl reductase","Acetoacetyl"],"a":0,"e":"The Fatty Acid Synthase Complex Is a Homodimer of Two Polypeptide Chains Containing Six Enzyme Activities and the Acyl Carrier Protein. The 6 enzymes are- Ketoacyl synthase Ketoacyl reductase Malonyl transacylase Dehydratase Enoyl reductase Thioesterase Acetyl Co-A carboxylase is the rate-limiting enzyme of fatty acid synthesis and is an enzyme, which is not a component of fatty acid synthase complex.","pyqMatches":[{"year":"2015","no":323,"q":"Which of the following enzyme is not a component of fatty acid synthase complex?","o":["Acetyl Co-A carboxylase","Ketoacyl synthase","Enoyl reductase","Acetoacetyl"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (926, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 45, '{"id":926,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":45,"q":"Umami taste is evoked by ?","o":["Glucose","Glutamic acid","Quinine","Sodium chloride"],"a":1,"e":"Ans. is ''b'' i.e., Glutamic acid There are four basic tastes namely Sweet, bitter Salty and Sour. There mechanisms of sensory transduction are : 1) Sweet receptor is a G protein coupled receptor and leads to an increase in cAMP concentration in the sensory cells which results in closure of K+ channels and depolarization. 2) Bitter receptors are also G protein coupled receptors and causes rise in intracellular Ca'' by IP3-DAG system. Rise in intracellular Ca+2 triggers neurotransmitter release. 3) Salty-tasting substances depolarize taste cells by activating amiloride-sensitive Na+ channels. 4) Sour-tasting substances depolarize taste cells by raising the intracellular H + ion concentration, which causes closure of K+ channels. The umami taste is the fifth taste which is unique. The proposed mechanism of umami taste is through glutamate taste sensors (glutamate receptors) with release of neuronal glutamic acid. In nature, there are three umami substances :- i) Monosodium glutamate (MSG) ii) Disodium 51-guanosine mosphosphate (GMP) iii) Disodium 51-ionsine monophosphate (IMP)","pyqMatches":[{"year":"2014","no":161,"q":"Umami taste is evoked by ?","o":["Glucose","Glutamic acid","Quinine","Sodium chloride"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (927, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 46, '{"id":927,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":46,"q":"Sirtuins are associated with ?","o":["Memory","Metabolism","Vision","Olfaction"],"a":1,"e":"Ans. is ''b'' i.e., Metabolism Sirtuins are a family of highly conserved NAD+ dependent deacetylase 5 that act as cellular sensors to detect energy availability and modulate metabolic process. Two mammalian sirtuins are involved in controling metabolic process : SIRT-1 (in nucleus) and SIRT-2 (in mitochondria). They are activated by high NAD± levels (low cellular energy status). They, then, deacetylate a variety of proteins causing induction of catabolic processes and inhibition of anabolic processes. SIRT-1 and SIRT-3 coordinately increase cellular energy stores and ultimately maintain cellular energy homeostasis. Genetic variant in SIRT-1 gene is associated lower risk of cardiovascular mortality and with better cognitive functioning. SIRT-1 variants are associated with decreased basal energy expenditure and a lower lipid peroxidation rate. Therefore, it has been proposed that genetic variation in SIRT-1 may determine the response rates of individuales undergoing caloric restriction and increased physical activity. Genetic variants of SIRT-3 may be associated with increased longevity (increased lifespan), but there is no evidence of such an association.","pyqMatches":[{"year":"2013","no":244,"q":"Sirtuins are associated with ?","o":["Memory","Metabolism","Vision","Olfaction"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":233,"q":"Sirtuins are associated with ?","o":["Memory","Metabolism","Vision","Olfaction"],"a":1,"source":"NEET_2014_Paper.pdf"},{"year":"2014","no":234,"q":"Sirtuins are associated with ?","o":["Antioxidant mechanism in body","Logetivity of life span","Regeneration of liver after partial resection","Carcinogenesis in human"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (928, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 47, '{"id":928,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":47,"q":"Normal uric acid level is ?","o":["1-2 mg/dl","2-3 mg/dl","3-6 mg/dl","10-15"],"a":2,"e":"Ans. is ''c'' i.e., 3-6 mg/dl","pyqMatches":[{"year":"2014","no":235,"q":"Normal uric acid level is ?","o":["1-2 mg/dl","2-3 mg/dl","3-6 mg/dl","10-15"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (929, 'Biochemistry', 'Miscellaneous', 'Moderate', 'Biochemistry', 48, '{"id":929,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Biochemistry","sourceNo":48,"q":"All are true about phosphorus except ?","o":["Comprises 1 % of the total body weight","85% remains in the bones","Diet is not a common source","Parathormone acts on NaPiIIc receptors"],"a":3,"e":"Ans. is ''d'' i.e., Parathormone acts on NaPilic receptors","pyqMatches":[{"year":"2014","no":256,"q":"All are true about phosphorus except ?","o":["Comprises 1 % of the total body weight","85% remains in the bones","Diet is not a common source","Parathormone acts on NaPiIIc receptors"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (930, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 49, '{"id":930,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":49,"q":"Carbohydrate in ABO blood group antigens is ?","o":["Glucose","Fructose","Inulin","Maltose"],"a":1,"e":"Ans.''b'' Fructose ABO antigens are glycoproteins, i.e. saccharides (carbohydrates) linked with polypeptides. There are four main groups : Blood group A: Containing A antigen Blood group B : Containing B antigen Blood group AB : Containing both ''A'' and ''EV antigen Blood group 0 : No ABO antigen ''A'' and ''EV antigens are derived from H-antigen. H-antigen is formed by adding fucose to terminal galactose of backbone strucuture. The addition of N-acetyl-D-galactosamine or D-galactose to the galactose residue of H-antigen confers ''A'' or ''B'' antigen, respectively.","pyqMatches":[{"year":"2014","no":259,"q":"Carbohydrate in ABO blood group antigens is ?","o":["Glucose","Fructose","Inulin","Maltose"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (931, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 50, '{"id":931,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":50,"q":"In argininosuccinase deficiency, what should be supplemented to continue the urea cycle ?","o":["Aspartate","Arginine","Citrullin","Argininosuccinate"],"a":1,"e":"Argininosuccinase (argininosuccinate lyase) catalyzes the cleavage of argininosuccinate into arginine and fumarate. Thus, in argininosuccinase deficiency, arginine cannot be produced. Supplementation with arginine base helps replenish this amino acid.","pyqMatches":[{"year":"2014","no":316,"q":"In argininosuccinase deficiency, what should be supplemented to continue the urea cycle ?","o":["Aspartate","Arginine","Citrullin","Argininosuccinate"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (932, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 51, '{"id":932,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":51,"q":"Tay-Sach disease is due to deficiency of","o":["Hexosaminidase A","Hexosaminidase B","Sphingomyelinase","α-galactosidase"],"a":0,"e":"Ans. is. A. Hexosaminidase A","pyqMatches":[{"year":"2014","no":310,"q":"Tay-Sach disease is due to deficiency of","o":["Hexosaminidase A","Hexosaminidase B","Sphingomyelinase","α-galactosidase"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (933, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 52, '{"id":933,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":52,"q":"Maximum energy is liberated by hydrolysis of ?","o":["Creatine phosphate","ATP","Phosphoenol pyruvate","Glucose-6-phosphate"],"a":2,"e":"Ans . C. Phosphoenol pyruvate A compound that liberates 7 Kcal/n:ol or more on hydrolysis is called high energy compound, or a compound that on hydrolysis undergoes a large (. 7 kcal/mol) decrease in free energy (AG) under standard condition is called high energy compound, i.e., AG - 7 Kcal/mol. Sugar Number of carbon Atoms Aldoses Ketoses Trioses 3 Glyceraldehyde Dihydroxyacetone Tetroses 4 Erythrose Erythrulose Pentoses 5 Ribose,Xylose Ribulose,Xylulose Hexoses 6 Glucose,Galactose,Mannose Fructose Heptoses7 Glucoheptose Sdoheptulose","pyqMatches":[{"year":"2014","no":272,"q":"Maximum energy is liberated by hydrolysis of ?","o":["Creatine phosphate","ATP","Phosphoenol pyruvate","Glucose-6-phosphate"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (934, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 53, '{"id":934,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":53,"q":"Which of the following is an aldose sugar?","o":["Ribulose","Fructose","Glyceraldehyde","All of the above"],"a":2,"e":"Ans. C. Glyceraldehyde","pyqMatches":[{"year":"2014","no":273,"q":"Which of the following is an aldose sugar?","o":["Ribulose","Fructose","Glyceraldehyde","All of the above"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (935, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 54, '{"id":935,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":54,"q":"Bond involved in formation of primary structure of protein/polypeptide ?","o":["Hydrogen","Peptide","Disulfide","a and b both"],"a":3,"e":"Ans: D. a and b both The primary structure is stabilized by a peptide bond, which is a type of covalent bond Bonds responsible for protein structure Two types of bonds stabilize protein structure : - Covalent (strong):- Peptide bonds, Disulfide bond. Non-covalent (weak):- Hydrogen bond, hydrophobic interactions, electrostatic (or ionic or salt) bond, Van der Waals interactions.","pyqMatches":[{"year":"2014","no":319,"q":"Bond involved in formation of primary structure of protein/polypeptide ?","o":["Hydrogen","Peptide","Disulfide","a and b both"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (936, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 55, '{"id":936,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":55,"q":"Main source of energy in 1 min is ?","o":["Glycogen","FFA","Phosphates","Glucose"],"a":0,"e":"Source of energy for muscular activity The immediate source of energy for all muscle contractions is ATP, followed immediately by creatine phosphate. In strenuous exercise, the ATP store is sufficient only for 1-2 seconds and creatine phosphate for another 5-7 seconds. Thus, energy-rich phosphagen stores (ATP and creatine phosphate) permit severe muscle contraction for 8-10 seconds only. After this, energy is obtained from the metabolism of stored glycogen or from circulating glucose and free fatty acids, depending upon the availability of oxygen. Energy source during in exercise can be summarized by : - i) The short burst of intense activity (e.g., 100-meter sprint or weight lifting) : - All energy comes from ATP and creatine phosphate. The breakdown of these compounds is anaerobic processes. ii) Little longer intense exercise (e.g., 200-meter sprint or 100-meter swim):- Besides ATP and creatine phosphate, glycogen is metabolized by anaerobic glycolytic pathways to provide a ready source of en​ergy. So, muscle work is anaerobic. iii) Longer duration exercise (e.g., jogging, marathon run): - The muscle work is aerobic and energy comes from aerobic utilization of glucose and free fatty acids. More glucose is utilized at the initial stage, but as the exercise is prolonged, free fatty acids become the predominant fuel.","pyqMatches":[{"year":"2014","no":299,"q":"Main source of energy in 1 min is ?","o":["Glycogen","FFA","Phosphates","Glucose"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (937, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 56, '{"id":937,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":56,"q":"Quarternary ammonium compound disinfectants are ?","o":["Anionic","Cationic","Neutral","Gases"],"a":1,"e":"Quaternary ammonium compounds are cationic detergents. They have microcidal and viricidal activities. They can be used for instrument disinfection and skin antisepsis.","pyqMatches":[{"year":"2014","no":358,"q":"Quarternary ammonium compound disinfectants are ?","o":["Anionic","Cationic","Neutral","Gases"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (938, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 57, '{"id":938,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":57,"q":"Not a component of PCR ?","o":["Primer","Taq polymerase","DNA Polymerase","Restriction enzyme"],"a":3,"e":"Steps in PCR PCR uses DNA polymerase to repetitively amlify targeted portion of DNA. Each cycle doubles the amout of DNA in the sample, leading to exponential increase with repeated cycles of amplification. Thus amplification after ''n'' number of cycle in (2)\". Twenty cycles provide an amplification of 106 (million) and 30 cycles of 109 (billion). PCR occurs in following steps - i) Isolation of target DNA sequence :- ii) Primers construction:- iii) Denaturation of DNA :- iv) Annealing of primers to single stranded DNA :- v) Chain extension:- Thus following are required in PCR :- Target double stranded DNA, two specific primers, a thermostable DNA polymerase (Taq polymerase), deoxyribonucleotides (dNTP).","pyqMatches":[{"year":"2014","no":349,"q":"Not a component of PCR ?","o":["Primer","Taq polymerase","DNA Polymerase","Restriction enzyme"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (939, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 58, '{"id":939,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":58,"q":"Which of the following is increased in lipoprotein lipase deficiency?","o":["VLDL","LDL","HDL","Chylomicrons"],"a":3,"e":"Type 1 hyperlipoproteinemias Lipoprotein fraction elevated- Chylomicrons Metabolic defect- Lipoprotein lipase or Apo CII deficiency. Features- Eruptive xanthoma, hepatomegaly, Pain abdomen. Management- Restriction of fat intake, supplementation with MCT","pyqMatches":[{"year":"2014","no":300,"q":"Which of the following is increased in lipoprotein lipase deficiency?","o":["VLDL","LDL","HDL","Chylomicrons"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (940, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 59, '{"id":940,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":59,"q":"NADH CoQ reductase is inhibited by ?","o":["Rotenone","Carbonmonoxide","Antimycin","Atractyloside"],"a":0,"e":"Rotenone inhibits complex I (NADH-CoQ reductase). Inhibitors of electron transport chain? Inhibitors of respiratory chain may be divided into three groups : ? 1) Inhibitors of electron transport chain proper These inhibitors inhibit the flow of electrons through the respiratory chain. This occurs at following sites. i) Complex I (NADH to CoQ) is inhibited by : - Barbiturates (amobarbital), Piericidin A (an antibiotic), rotenone (an insectiside), chlorpromazine (a tranquilizer), and guanethidine (an antihypertensive). These inhibitors block the transfer of reducing equivalents from FeS protein to Coe. ii) Complex II is inhibited by : - Carboxin and TTFA inhibit transfer of electon from FADH2 to CoQ, whereas malanate competitively inhibit from succinate to complex II. iii) Complex III (Cytochrome b to cytochrome C1) is inhibited by : - Dimercaprol, antimycin A, BAL (British antilewisite), Naphthyloquinone. These inhibitors block the transfer of electrons from cytochrome b to cytochrome CI. iv) Complex IV (cytochrome C oxidase) is inhibited by : - Carbon monoxide, CN–, H2S and azide (N3). These inhibitors block the transfer of electrons from cytochrome aa3 to molecular oxygen and therefore can totally arrest cellular respiration. 2) Inhibitors of oxidative phosphorylation These compounds directly inhibit phosphorylation of ADP to ATP. Oligomycin inhibits Fo component of Fo F1 ATPase. Atractiloside inhibits translocase, a transport protein that transports ADP into mitochondria for phosphorylation into ATP. 3) Uncouples As the name suggests, these componds block the coupeling of oxidation with phosphorylation. These compounds allow the transfer of reducing equivalents in respiratory chain but prevent the phosphorylation of ADP to ATP by uncoupling the linkage between ETC and phosphorylation. Thus the energy instead of being trapped by phosphorylation is dissipated as heat. Uncouplers may be :- i) Natural :- Thermogenin, thyroxine ii) Synthetic :- 2, 4-dinitrophenol (2, 4-DNP), 2, 4-dinitrocresol (2, 4- DNC), and CCCP (chlorocarbonylcyanidephenyl hydrazone).","pyqMatches":[{"year":"2014","no":268,"q":"NADH CoQ reductase is inhibited by ?","o":["Rotenone","Carbonmonoxide","Antimycin","Atractyloside"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (941, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 60, '{"id":941,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":60,"q":"Rate limiting step in urea cycle is catalyzed by ?","o":["Arginase","Argininosuccinase","Carbamoyl-phosphate synthase","Ornithine transcarbamylase"],"a":2,"e":"Ans. is ''c'' i.e., Carbamoyl-phosphate synthase Biosynthesis of urea occurs in five steps. 1) Carbamoyl phosphate synthase-I (CPS-I), a mitochondria! enzyme, catalyzes the formation of carbamoyl phosphate by condensation of CO, and ammonia. Two molecules of ATP are required for the reaction. CPS-I is the rate limiting enzyme of urea cycle. It is an allosteric enzyme and allosterically activated by N- acetyl glutamate. There is one cytosolic carbamyl phosphate synthase-II (CPS-II) which uses glutamine rather than ammonia as the nitrogen donor and functions in pyrimidine synthesis. 2) Ornithine transcarbamoylase catalyzes the formation of citrulline from carbamoyl phosphate and ornithine. 3) Arginosuccinate synthase catalyzes the formation of arginosuccinate from citrulline and aspartate. This reaction requires I ATP, but 2 high energy phosphate bonds are consumed as ATP is converted to AMP + PPi. The amino group of aspartate provides one of the two nitrogen atoms that appear in urea (The other one is provided by ammonia NH4). 4) Arginosuccinate lyase (arginosuccinase) catalyses the cleavage of arginosuccinate into arginine and fumarate. Fumarate enters in TCA cycle. 5) Arginase catalyses the formation of urea from arginine by hydrolytic cleavage of arginine to yield urea and ornithine. Ornithine is thus regenerated and can enter mitochondria to initiate another round of the urea cycle.","pyqMatches":[{"year":"2014","no":321,"q":"Rate limiting step in urea cycle is catalyzed by ?","o":["Arginase","Argininosuccinase","Carbamoyl-phosphate synthase","Ornithine transcarbamylase"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (942, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 61, '{"id":942,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":61,"q":"Citrullinemia is due to deficiency of ?","o":["Argininosuccinate lyase","Argininosuccinate synthase","Arginase","Ornithine transcarbamylase"],"a":1,"e":"Ans. is. B. Argininosuccinate synthase","pyqMatches":[{"year":"2014","no":322,"q":"Citrullinemia is due to deficiency of ?","o":["Argininosuccinate lyase","Argininosuccinate synthase","Arginase","Ornithine transcarbamylase"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (943, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 62, '{"id":943,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":62,"q":"Urease is a/an ?","o":["Oxidoreductase","Lyase","Ligase","Hydrolase"],"a":3,"e":"functionally, belong to the superfamily of amidohydrolases and phosphotriesterases Hydrolases --> All digestive enzymes (Pepsin,trypsin'', Lipases, esterases), lysosomal enzymes''urease''and phosphatase.","pyqMatches":[{"year":"2014","no":264,"q":"Urease is a/an ?","o":["Oxidoreductase","Lyase","Ligase","Hydrolase"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (944, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 63, '{"id":944,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":63,"q":"Vitamin involved in decarboxylation ?","o":["Biotin","Pyridoxine","Niacin","Thiamine"],"a":1,"e":"Ans. is. B. Pyridoxine Pyridoxal phosphate is a coenzyme for many enzymes involved in amino 1309 acid metabolism, especially transamination and decarboxylation. It is also the cofactor of glycogen phosphorylase, where the phosphate group is catalytically important. In addition, it is important in steroid hormone action. Pyridoxal phosphate removes the hormone-receptor complex from DNA binding, terminating the action of the hormones.","pyqMatches":[{"year":"2014","no":344,"q":"Vitamin involved in decarboxylation ?","o":["Biotin","Pyridoxine","Niacin","Thiamine"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (945, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 64, '{"id":945,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":64,"q":"Nitrogen-9 of purine ring is provided by ?","o":["Glycine","Aspartate","Glutamine","CO2"],"a":2,"e":"In de novo synthesis, purine ring is formed from variety of precursors is assembled on ribose-5-phosphate. Precursors for de novo synthesis are - i) Glycine provides C4, C5 and N7 ii) Aspartate provides N1 iii) Glutamine provides N3 and N9 iv) Tetrahydrofolate derivatives furnish C2 and C8 v) Carbon dioxide provides C6","pyqMatches":[{"year":"2014","no":339,"q":"Nitrogen-9 of purine ring is provided by ?","o":["Glycine","Aspartate","Glutamine","CO2"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (946, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 65, '{"id":946,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":65,"q":"Rate limiting step in fatty acid synthesis is ?","o":["Production of acetyl CoA","Production of oxaloacetate","Production of malonyl-CoA","Production of citrate"],"a":2,"e":"Production of malonyl-CoA is the initial and rate-limiting step in the fatty acid synthesis. Acetyl-CoA needs to be converted to the activated form, which will serve as the donor of carbon units to the growing fatty acid chain. Malonyl-CoA, a 3-carbon compound is such an activated form. It is produced by carboxylation of acetyl-CoA, a reaction catalyzed by acetyl-CoA carboxylase. Acetyl-CoA carboxylase requires biotin as a cofactor. The reaction also requires HCO3- and ATP The reaction takes place in two steps: (i) Carboxylation of biotin involving HCO3 and ATP. (ii) transfer of the carboxyl group to acetyl-CoA to form malonyl-CoA.","pyqMatches":[{"year":"2014","no":303,"q":"Rate limiting step in fatty acid synthesis is ?","o":["Production of acetyl CoA","Production of oxaloacetate","Production of malonyl-CoA","Production of citrate"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (947, 'Biochemistry', 'Carbohydrate Metabolism', 'Moderate', 'Biochemistry', 66, '{"id":947,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":66,"q":"Which is not a common enzyme for glycolysis and gluconeogenesis?","o":["Aldolase","Glucose-6-phosphatase","Phosphoglycerate mutase","Phosphoglycerate kinase"],"a":1,"e":"Seven of the reactions of glycolysis are reversible and are used in the synthesis of glucose by gluconeogenesis. Thus, seven enzymes are common to both glycolysis and gluconeogenesis :","pyqMatches":[{"year":"2014","no":286,"q":"Which is not a common enzyme for glycolysis and gluconeogenesis?","o":["Aldolase","Glucose-6-phosphatase","Phosphoglycerate mutase","Phosphoglycerate kinase"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (948, 'Biochemistry', 'Carbohydrate Metabolism', 'Moderate', 'Biochemistry', 67, '{"id":948,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":67,"q":"Which is not a step of gluconeogenesis?","o":["Conversion of glucose-6-phosphate to glucose","Carboxylation of pyruvate","Conversion of oxaloacetate to phosphoenolpyruvate","Conversion of phosphoenolpyruvate to pyruvate"],"a":3,"e":"Ans.'' D'' Conversion of phosphoenolpyruvate to pyruvate Conversion of phosphoenolpyruvate to pyruvate is a step of glycolysis (not of gluconeogenesis). Reaction in gluconeogenesis Seven reactions of glycolysis are reversible and therefore are used with the same enzyme in the synthesis of glucose by gluconeogenesis. However, three of the reactions of glycolysis are irreversible and must be circumvented by four special reactions that are unique to gluconeogenesis and catalyzed by (I) Pyruvate carboxylase, (ii) Phosphoenolpyruvate carboxykinase, iii) fructose- I,6-bisphosphatase, (iv) Glucose-6-phosphatase. All three irreversible steps of glycolysis should be bypassed for gluconeogenesis to occur. These three bypass steps are circumvented by four special reactions. A) First bypass (conversion of pyruvate into phosphoenolpyruvate):- Conversion of pyruvate into phosphoenolpyruvate takes place through two reactions:? i) Carboxylation of pyruvate: - First, pyruvate enters the mitochondria and is converted into oxaloacetate by pyruvate carboxylase. Pyruvate carboxylase is a mitochondrial enzyme, therefore this reaction oc​curs in mitochondria only. ii) Conversion of oxaloacetate to phosphoenolpyruvate: - Oxaloacetate produced in the mitochondria cannot cross the membrane. It is first reduced to malate, which then moves across the mitochondrial membrane into the cytosol. Malate is, then, reoxidized to oxaloacetate in the cytosol. Oxaloacetate is converted to phosphoenolpyruvate by phosphoenolpyruvate (PEP) carboxykinase. B) Second bypass: - Conversion of fructose-1,6-bisphosphate into fructose-6-phosphate is catalyzed by fructose-1,6-bisphosphatase. Its presence determines whether tissue is capable of synthesizing glucose (gluconeogenesis) or glycogen (gluconeogenesis) not only from pyruvate but also from triose phosphate. It is present in the liver, kidney, and skeletal muscle, but is probably absent from heart and smooth muscle. C) Third bypass: - Conversion of glucose-6-phosphate to glucose is catalyzed by glucose-6-phosphatase.","pyqMatches":[{"year":"2014","no":287,"q":"Which is not a step of gluconeogenesis?","o":["Conversion of glucose-6-phosphate to glucose","Carboxylation of pyruvate","Conversion of oxaloacetate to phosphoenolpyruvate","Conversion of phosphoenolpyruvate to pyruvate"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (949, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 68, '{"id":949,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":68,"q":"Vitamin C is required for ?","o":["Posttranslational modification","Synthesis of epinephrine","Tyrosine metabolism","All of the above"],"a":3,"e":"Vitamin C (ascorbic acid) Ascorbic acid (Vitamin C) is also called antiscorbutic factor. It is very heat labile, especially in basic medium. Ascorbic acid itself is an active form. Maximum amount of vitamin C is found in adrenal cortex. Ascorbic acid functions as a reducing agent and scavanger of free radicals (antioxidant). Its major functions are :- i) In collagen synthesis :- Vitamin C is required for post-translational modification by hydroxylation of proline and lysine residues converting them into hydroxyproline and hydroxylysine. Thus vitamin C is essential for the conversion of procollagen to collagen, which is rich in hydroxyproline and hydroxylysine. Through collagen synthesis, it plays a role in formation of matrix of bone, cartilage, dentine and connec​tive tissue. ii) Synthesis of norepinephrine from dopamine by dopamine-(3- monoxygenase (dopamine-13-hydroxylase) requires Vitamin C. iii) Carnitine synthesis iv) Bile acid synthesis :- 7-a-hydroxylase requires vitamin C. v) Absorption of iron is stimulated by ascorbic acid by conversion of ferric to ferrous ions. vi) During adrenal steroid synthesis, ascorbic acid is required during hydroxylation reactions. vii) Tyrosine metabolism - Oxidation of P-hydroxy-phenylpyruvate to homogentisate. viii) Folate metabolism - Folic acid is converted to its active form tetrahydrofolate by help of Vitamin C.","pyqMatches":[{"year":"2014","no":345,"q":"Vitamin C is required for ?","o":["Posttranslational modification","Synthesis of epinephrine","Tyrosine metabolism","All of the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (950, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 69, '{"id":950,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":69,"q":"First product of purine metabolism","o":["Uric acid","Xanthine","P-alanine","CO2"],"a":1,"e":"Humans catabolize purines to uric acid. But, first purines are catabolized to xanthine, which is further catabolized to purine.","pyqMatches":[{"year":"2014","no":340,"q":"First product of purine metabolism","o":["Uric acid","Xanthine","P-alanine","CO2"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (951, 'Biochemistry', 'Carbohydrate Metabolism', 'Moderate', 'Biochemistry', 70, '{"id":951,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":70,"q":"Which of the following metabolic pathway in carbohydrate metabolism is required for synthesis of nucleic acids?","o":["Gluconeogenesis","Glycolysis","HMP shunt","Glycogenesis"],"a":2,"e":"Ans. ''C'' HMP Shunt. HMP is an alternative route for the oxidation of glucose (beside glycolysis). It is also called a \"pentose phosphate pathway\", \"Dickens - Horecker pathway\", \"Shunt pathway\" or \"phosphogluconate oxidative pathway\" Metabolic Role of NADPH formed by HMP Shunt Pathway","pyqMatches":[{"year":"2014","no":292,"q":"Which of the following metabolic pathway in carbohydrate metabolism is required for synthesis of nucleic acids?","o":["Gluconeogenesis","Glycolysis","HMP shunt","Glycogenesis"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (952, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 71, '{"id":952,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":71,"q":"Mineral required for cholesterol biosynthesis ?","o":["Fe","Mn","Mg","Cu"],"a":2,"e":"Mg is required in stage 2 of cholesterol synthesis. Biosynthesis (De Novo Synthesis) of cholesterol The liver is the major site for cholesterol biosynthesis. Some cholesterol is also synthesized in the intestine adrenal cortex, gonads and skin. The microsomal (smooth endoplasmic reticulum) and cytosol fraction of cell are responsible for fir cholesterol synthesis; However, most of the reactions in synthesis occur in the cytosol. Cholesterol is a C-27 compound. All 27-carbon atoms of cholesterol are derived from a single precursor, i.e. acetyl-CoA (activated acetate). The first two molecules of acetyl-CoA condense to form acetoacetyl- CoA. Next, the third molecule of acetyl- CoA condenses with acetoacetyl-CoA to form 3-hydroxy-3-methylglutaryl-CoA (HMG- CoA). Then HMG-CoA is converted to mevalonate by HMG-CoA reductase, the key regulatory enzyme of cholesterol synthesis.","pyqMatches":[{"year":"2014","no":305,"q":"Mineral required for cholesterol biosynthesis ?","o":["Fe","Mn","Mg","Cu"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (953, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 72, '{"id":953,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":72,"q":"Source of energy in Kreb''s cycle is -","o":["NAD","NADP","NADPH","NADH"],"a":3,"e":"Ans.''D'' NADH Energetics of TCA cycles (Kreb''s cycle) Alpha-ketoglutarate is oxidatively decarboxylated to form succinyl CoA by the enzyme alpha-ketoglutarate dehydrogenase. The NADH thus generated enters into ETC to generate ATPs. Another molecule of CO2 is removed in this step. This is the irreversible step in the whole reaction cycle.","pyqMatches":[{"year":"2014","no":279,"q":"Source of energy in Kreb''s cycle is","o":["NAD","NADP","NADPH","NADH"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (954, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 73, '{"id":954,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":73,"q":"Coenzyme used in Kreb''s cycle ?","o":["NAD","NADP","NADPH","NADH"],"a":0,"e":"Niacin is used as coenzyme nicotinamide adenine dinucleotide (NAD'') for transfer of hydrogen.","pyqMatches":[{"year":"2014","no":281,"q":"Coenzyme used in Kreb''s cycle ?","o":["NAD","NADP","NADPH","NADH"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (955, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 74, '{"id":955,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":74,"q":"Mousy odor of urine is seen in ?","o":["Alkaptunuria","Phenylketonuria","Hartnup disease","Albinism"],"a":1,"e":"No separate explanation was provided in the source.","pyqMatches":[{"year":"2014","no":324,"q":"Mousy odor of urine is seen in ?","o":["Alkaptunuria","Phenylketonuria","Hartnup disease","Albinism"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (956, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 75, '{"id":956,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":75,"q":"Cabbage-like odour is seen in ?","o":["Alkaptonuria","Phenylketonuria","Hartnup disease","Tyrosinemia"],"a":3,"e":"Ans. is. D. Tyrosinemia","pyqMatches":[{"year":"2014","no":325,"q":"Cabbage-like odour is seen in ?","o":["Alkaptonuria","Phenylketonuria","Hartnup disease","Tyrosinemia"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (957, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 76, '{"id":957,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":76,"q":"Immediate energy supply for muscle contraction ?","o":["GTP","ATP","Creatine phosphate","Fatty acid"],"a":2,"e":"The immediate source of energy for all muscle contraction is ATP, followed immediately by creatine phosphate. The immediate source of energy for all muscle contraction is ATP, followed immediately by creatine phosphate. In sternous exercise ATP store is sufficient only for 1-2 seconds and creatine phosphate for another 5-7 seconds. Thus, energy rich phosphagen stores (ATP and creatine phosphate) permit severe muscle contraction for 8-10 seconds only. After this, energy is obtained from the metabolism of stored glycogen or from circulating glucose and free fatty acids, depending upon the availability of oxygen. Energy source during in exercise can be summarized by :- i) Short burst of intense activity (e.g., 100 meter sprint or weight lifting) :- All energy comes from ATP and creatine phosphate. Breakdown of these compound is an anaerobic processes. ii) Little longer intense exercise (e.g., 200 meter sprint or 100 meter swim) :- Besides ATP and creatine phosphate, glycogen is metabolised by anerobic glycolytic pathways to provide a ready source of energy. So, muscle work is anaerobic. iii) Longer duration exercise (e.g., jogging, marathan run) : - The muscle work is aerobic and energy comes from aerobic utilization of glucose and free fatty acids. More glucose is utilized at the initial stage, but as the exercise is prolonged, free fatty acids become the predominant fuel.","pyqMatches":[{"year":"2014","no":298,"q":"Immediate energy supply for muscle contraction ?","o":["GTP","ATP","Creatine phosphate","Fatty acid"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (958, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 77, '{"id":958,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":77,"q":"Cofactor for dopamine hydroxylase ?","o":["Fe","Mg","Mn","Cu"],"a":3,"e":"Dopamine 8-hydroxylase is a ''copper'' containing monooxygenase that requires ascorbic acid and molecular oxygen. It catalyzes the formation of norepinephrine.","pyqMatches":[{"year":"2014","no":328,"q":"Cofactor for dopamine hydroxylase ?","o":["Fe","Mg","Mn","Cu"],"a":3,"source":"NEET_2014_Paper.pdf"},{"year":"2016","no":284,"q":"Cofactor for dopamine hydroxylase ?","o":["Fe","Mg","Mn","Cu"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2014","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (959, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 78, '{"id":959,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":78,"q":"Lipoprotein involved in reverse cholesterol transport?","o":["LDL","VLDL","IDL","HDL"],"a":3,"e":"The HDL particles are referred to as scavengers because their primary role is to remove free (unesterified) cholesterol from the extrahepatic tissues. HDL particles transport cholesterol from extrahepatic tissues to the liver (i.e. reverse cholesterol transport) which is then excreted through bile. Reverse cholesterol transport All nucleated cells in different tissues synthesize cholesterol, but the excretion of cholesterol is mainly by the liver in the bile or by enterocytes in the gut lumen. So, cholesterol must be transported from peripheral tissue to the liver for excretion. This is facilitated by HDL and is called reverse cholesterol transport because it transports the cholesterol in reverse direction to that is transported from the liver to peripheral tissues through the VLDL → LDL cycle. Process HDL is synthesized in the liver and small intestine. Nascent HDL contains phospholipids and unesterified cholesterol and Apo-A, C, E. This nascent HDL is secreted into circulation where it acquires additional unesterified cholesterol from peripheral tissues. Within the HDL particle, the cholesterol is esterified by lecithin - cholesterol acetyltransferase (LCAT) to form cholesteryl ester and additional lipid is transported to HDL from VLDL and chylomicrons. Apo- A1 activates LCAT.","pyqMatches":[{"year":"2014","no":306,"q":"Lipoprotein involved in reverse cholesterol transport?","o":["LDL","VLDL","IDL","HDL"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (960, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 79, '{"id":960,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":79,"q":"Allantoin is the end product of metabolism of ?","o":["Glycogen","Purine","Pyrimidine","Histidine"],"a":1,"e":"In non-primate mammals, end product of purine metabolism is allantoin due to presence of enzyme uricase. Uricase convertes uric acid to allantoin. Humans lack the enzyme uricase. Therefore, end product of purine catabolism in humans is uric acid.","pyqMatches":[{"year":"2014","no":341,"q":"Allantoin is the end product of metabolism of ?","o":["Glycogen","Purine","Pyrimidine","Histidine"],"a":1,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":353,"q":"Allantoin is the end product of metabolism of ?","o":["Glycogen","Purine","Pyrimidine","Histidine"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (961, 'Biochemistry', 'Vitamins & Minerals', 'Moderate', 'Biochemistry', 80, '{"id":961,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Moderate","source":"Biochemistry","sourceNo":80,"q":"Pyruvate dehydrogenase contains all, except -","o":["NAD","FAD","Biotin","CoA"],"a":2,"e":"PDH complex is made up of three enzymes and requires five coenzymes. The enzymes are : i) E1 : Pyruvate dehydrogenase or pyruvate decarboxylase ii) E2 : Dihydrolipoyl transacetylase iii) E3 : Dihydrolipoyl dehydrogenase. The coenzyme required are thiamine pyrophosphate (APP), lipoic acid, FAD, NAD, and CoA.","pyqMatches":[{"year":"2014","no":284,"q":"Pyruvate dehydrogenase contains all, except","o":["NAD","FAD","Biotin","CoA"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (962, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 81, '{"id":962,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":81,"q":"Northern blot is used to detect ?","o":["Protein","Immunoglobulin","RNA","DNA"],"a":2,"e":"Ans: C. RNA Visualization of a specific DNA or RNA fragment among the many thousand of contaminating molecules requires the convergence of number of techniques collectively termed the blot transfer. Southern blot → Detects DNA Northern blot → Detects RNA Western blot → Detects proteins (proteins are separated by electrophoresis, renatured and analysed for an interaction by hybridization with a specific labelled DNA probe).","pyqMatches":[{"year":"2014","no":351,"q":"Northern blot is used to detect ?","o":["Protein","Immunoglobulin","RNA","DNA"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (963, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Moderate', 'Biochemistry', 82, '{"id":963,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":82,"q":"Not an essential amino acid ?","o":["Arginine","Histidine","Glutamate","Lysine"],"a":2,"e":"Ans ''C'' Glutamate Essential or Indispensable The amino acids may further be classified according to their essentiality for growth. They are Isoleucine Leucine Threonine Lysine Methionine Phenylalanine Tryptophan Valine","pyqMatches":[{"year":"2014","no":329,"q":"Not an essential amino acid ?","o":["Arginine","Histidine","Glutamate","Lysine"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (964, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 83, '{"id":964,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":83,"q":"Enzyme deficient in gangliosidoses ?","o":["β-glucuronidase","Iduronidase","β-galactosidase","Hyaluronidase"],"a":2,"e":"Ans. ''C'' β-galactosidase Generalized gangliosidoses is a lipid storage disorder. Enzyme defect- β-galactosidase Lipid accumulates- Ganglioside (GM1) Clinical features- Mental retardation, hepatomegaly, skeletal deformities. Foam cells in the bone marrow. Cherry red spot in the retina.","pyqMatches":[{"year":"2014","no":308,"q":"Enzyme deficient in gangliosidoses ?","o":["β-glucuronidase","Iduronidase","β-galactosidase","Hyaluronidase"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (965, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 84, '{"id":965,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":84,"q":"Defect in type II hyperlipidemia","o":["Apo-E","Lipoprotein lipase","LDL receptor","None"],"a":2,"e":"Also called Familial hypercholesterolemia. Type II A (Primary familial hypercholesterolemia) There is an elevation of LDL. Patients seldom survive in the second decade of life due to ischemic heart disease. The cause is the LDL receptor defect. Receptor deficiency in the liver and peripheral tissues will result in the elevation of LDL levels in plasma, leading to hypercholesterolemia. The LDL receptor defect may be due to the following reasons:","pyqMatches":[{"year":"2014","no":302,"q":"Defect in type II hyperlipidemia","o":["Apo-E","Lipoprotein lipase","LDL receptor","None"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (966, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 85, '{"id":966,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":85,"q":"Major source of energy for brain in fasting/ starvation ?","o":["Glucose","Glycogen","Fatty acids","Ketone bodies"],"a":3,"e":"There is no stored fuel in the brain, but it utilized 60% of total energy under resting conditions. Glucose is virtually the sole fuel for the brain, except in prolonged starving when ketone bodies are the major source. Fatty acids do not serve as fuel for the brain, because they are bound to albumin in plasma; hence cannot cross the blood-brain barrier.","pyqMatches":[{"year":"2012","no":347,"q":"Major source of energy for brain in fasting/ starvation ?","o":["Glucose","Glycogen","Fatty acids","Ketone bodies"],"a":3,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":301,"q":"Major source of energy for brain in fasting/ starvation ?","o":["Glucose","Glycogen","Fatty acids","Ketone bodies"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (967, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 86, '{"id":967,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":86,"q":"Nicotinic acid is derived from ?","o":["Glutamine","Tryptophan","Glutathione","Phenylalanine"],"a":1,"e":"Ans. ''B'' Tryptophan. Nicotinic Acid Pathway of Tryptophan- About 97% of molecules of tryptophan are metabolized in the major pathway. About 3% of molecules are diverted at the level of 3- hydroxy anthranilic acid, to form NAD+. The enzyme, QPRT (quinolinate phosphoribosyltransferase) is the rate-limiting step. About 60 mg of tryptophan will be equivalent to 1 mg of nicotinic acid. The development of pellagra like symptoms in the maize eating population is due to tryptophan deficiency in maize. Hydroxy anthranilate production is dependent on pyridoxal phosphate. Hence in vitamin B6 deficiency, nicotinamide deficiency is also manifested.","pyqMatches":[{"year":"2014","no":330,"q":"Nicotinic acid is derived from ?","o":["Glutamine","Tryptophan","Glutathione","Phenylalanine"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (968, 'Biochemistry', 'Genetics', 'Easy', 'Biochemistry', 87, '{"id":968,"subject":"Biochemistry","chapter":"Genetics","difficulty":"Easy","source":"Biochemistry","sourceNo":87,"q":"Sex determining region is located on ?","o":["Long arm of Y chromosome","Short arm of Y chromosome","Long arm of X chromosome","Short arm of X chromosome"],"a":1,"e":"Product of SRY gene is sex-determining region Y protein. This protein is involved in male sexual development.","pyqMatches":[{"year":"2014","no":352,"q":"Sex determining region is located on ?","o":["Long arm of Y chromosome","Short arm of Y chromosome","Long arm of X chromosome","Short arm of X chromosome"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (969, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 88, '{"id":969,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":88,"q":"Transferases are classified as ?","o":["EC-1","EC-2","EC-3","EC-4"],"a":1,"e":"Ans. B. EC-2","pyqMatches":[{"year":"2014","no":265,"q":"Transferases are classified as ?","o":["EC-1","EC-2","EC-3","EC-4"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (970, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 89, '{"id":970,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":89,"q":"True about acid phosphatase is ?","o":["Acts at pH 8-9","Prostate isoform is tartarate resistant","Erythrocyte isoform is inhibited by cupric ions","All of the above"],"a":2,"e":"Acid phosphatase Acid phosphatase (ACP) hydrolyzes phosphoric acid esters at pH 5-","pyqMatches":[{"year":"2014","no":266,"q":"True about acid phosphatase is ?","o":["Acts at pH 8-9","Prostate isoform is tartarate resistant","Erythrocyte isoform is inhibited by cupric ions","All of the above"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (971, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 90, '{"id":971,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":90,"q":"Alcohol is metabolized by ?","o":["Alcohol dehydrogenase","MEOS","Catalase","All of the above"],"a":3,"e":"Ethyl alcohol (ethanol) is readily absorbed from GIT and degraded by oxidation (oxidative process). Liver is the major site for ethanol oxidation. At least three enzyme systems are capable of ethanol oxidation :- i) Alcohol dehydrogenase (ADH) → Major pathway ii) Microsomal ethanol oxidising system (MEOS) : It involves cytochrome P450. iii) Catalase of peroxisomes. The product of all three oxidation pathways is acetaldehyde, which is rapidly oxidized to acetate by aldehyde dehydrogenase (ALDH).","pyqMatches":[{"year":"2014","no":311,"q":"Alcohol is metabolized by ?","o":["Alcohol dehydrogenase","MEOS","Catalase","All of the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (972, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 91, '{"id":972,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":91,"q":"Amino acid which is optically inert ?","o":["Valine","Alanine","Glycine","Threonine"],"a":2,"e":"Ans. ''C'' Glycine The a-carbon of amino acids has four different groups attached to it and so is a chiral or asymmetric carbon. Hence, there are two possible enantiomers, L and D, i.e., mirror image with reference to α-carbon. The chiral carbon is also responsible for optical activity and stereoisomerism. The only exception is glycine, which is the simplest amino acid. Glycine has no chiral carbon (chirality) because a-carbon of glycine does not have four different groups attached to it. Therefore glycine does not have optical activity or D and L forms (enantiomers).","pyqMatches":[{"year":"2014","no":334,"q":"Amino acid which is optically inert ?","o":["Valine","Alanine","Glycine","Threonine"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (973, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 92, '{"id":973,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":92,"q":"First purine nucleotide, which is synthesized in purine biosynthesis ?","o":["AMP","GMP","IMP","UMP"],"a":2,"e":"The biosynthesis of purine begins with ribose-5-phosphate, derived from pentose phosphate pathway (PPP). First intermediate formed in this pathway, 5-phosphoribosyl- pyrophosphate (PRPP), is also an intermediate in purine salvage pathway.","pyqMatches":[{"year":"2014","no":342,"q":"First purine nucleotide, which is synthesized in purine biosynthesis ?","o":["AMP","GMP","IMP","UMP"],"a":2,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":357,"q":"First purine nucleotide, which is synthesized in purine biosynthesis ?","o":["AMP","GMP","IMP","UMP"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (974, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 93, '{"id":974,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":93,"q":"Rate limiting step in heme synthesis is catalyzed by ?","o":["ALA dehydratase","ALA synthase","UPG decarboxylase","Ferrochelatase"],"a":1,"e":"Ans. B. ALA synthase Synthesis of heme Heme synthesis takes place in all cells, but occurs to greatest extent in bone marrow and liver. The first step in the synthesis of heme is the condensation of glycine and succinyl Co-A to form &-aminolevulinic acid (Delta-ALA), which occurs in mitochondria. This reaction is catalyzed by Delta-ALA synthase which requires pyridoxal phosphate (PLP) as cofactor. This is the rate limiting step in heme synthesis.","pyqMatches":[{"year":"2014","no":360,"q":"Rate limiting step in heme synthesis is catalyzed by ?","o":["ALA dehydratase","ALA synthase","UPG decarboxylase","Ferrochelatase"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (975, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 94, '{"id":975,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":94,"q":"Rate limiting step in porphyrine synthesis -","o":["ALA dehydratase","ALA synthase","UPG decarboxylase","Ferrochelatase"],"a":1,"e":"Ans. is. B. ALA synthase","pyqMatches":[{"year":"2014","no":361,"q":"Rate limiting step in porphyrine synthesis","o":["ALA dehydratase","ALA synthase","UPG decarboxylase","Ferrochelatase"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (976, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 95, '{"id":976,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":95,"q":"Oxidation of very long chain fatty acids takes place in ?","o":["Cytosol","Mitochondria","Ribosomes","Peroxisomes"],"a":3,"e":"A modified form of β-oxidation is found in peroxisomes and leads to the breakdown of very-long-chain fatty acids (eg, C20, C22) with the formation of acetyl-CoA and H2O2, which is broken down by catalase. This system is not linked directly to phosphorylation and the generation of ATP, and also does not attack shorter-chain fatty acids. The peroxisomal enzymes are induced by high-fat diets and in some species by hypolipidemic drugs such as clofibrate. Another role of peroxisomal β-oxidation is to shorten the side chain of cholesterol in bile acid formation","pyqMatches":[{"year":"2014","no":312,"q":"Oxidation of very long chain fatty acids takes place in ?","o":["Cytosol","Mitochondria","Ribosomes","Peroxisomes"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (977, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 96, '{"id":977,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":96,"q":"Salvage pathway of purine biosynthesis is important for ?","o":["Liver","RBCs","Kidney","Lung"],"a":1,"e":"Purine nucleotide synthesis occurs by two pathways : 1.De novo synthesis 2.Salvage pathway Liver is the major site of purine nucleotide biosynthesis (de novo). Certain tissues cannot synthesize purine nucleotides by de novo patyway, e g. brain, erythrocytes and polymor​phonuclear leukocytes. These are dependent on salvage pathway for synthesis of purine nucleotides by using exogenous purines, which are formed by degradation of purine nucleotides synthesized in liver.","pyqMatches":[{"year":"2014","no":343,"q":"Salvage pathway of purine biosynthesis is important for ?","o":["Liver","RBCs","Kidney","Lung"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (978, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 97, '{"id":978,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":97,"q":"Lipoprotein associated with carrying cholesterol from peripheral tissues to liver is ?","o":["HDL","LDL","VLDL","IDL"],"a":0,"e":"The total body cholesterol content varies from 130-150 grams. LDL (low-density lipoprotein) transports cholesterol from the liver to the peripheral tissues and HDL (high-density lipoprotein) transports cholesterol from tissues to the liver. Cells of extrahepatic tissues take up cholesterol from LDL.","pyqMatches":[{"year":"2014","no":307,"q":"Lipoprotein associated with carrying cholesterol from peripheral tissues to liver is ?","o":["HDL","LDL","VLDL","IDL"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (979, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 98, '{"id":979,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":98,"q":"Which of the following is a nucleoside?","o":["Adenine","Uridine","Thymine","Guanine"],"a":1,"e":"Ans. is. B. Uridine","pyqMatches":[{"year":"2014","no":353,"q":"Which of the following is a nucleoside?","o":["Adenine","Uridine","Thymine","Guanine"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (980, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 99, '{"id":980,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":99,"q":"Amino acids with extra NH2 (amino group) in structure-","o":["Aspartate","Glutamate","Histidine","Alanine"],"a":2,"e":"Ans. is. C. Histidine The amino acids will undergo alpha decarboxylation to form the corresponding amine. Some important amines are produced from amino acids. For example, Histidine → Histamine + CO2 Tyrosine → Tyramine + CO2 Tryptophan → Tryptamine + CO2 Lysine → Cadaverine + CO2 Glutamic acid → Gamma-aminobutyric acid (GABA) + CO2","pyqMatches":[{"year":"2014","no":331,"q":"Amino acids with extra NH2 (amino group) in structure","o":["Aspartate","Glutamate","Histidine","Alanine"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (981, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 100, '{"id":981,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":100,"q":"Number of ATP produced by RBC when Glycolysis occurs through Rapoport Leubering pathway-","o":["2","6","8","0"],"a":3,"e":"Ans. ''D'' 0 Net number of ATPs produced from 1 mol of Glucose by Anaerobic Glycolysis- 2 ATPs Aerobic Glycolysis - 7 ATPs Aerobic oxidation- 32 ATPs Rapaport-LeuberingCycle- Zero","pyqMatches":[{"year":"2014","no":275,"q":"Number of ATP produced by RBC when Glycolysis occurs through Rapoport Leubering pathway","o":["2","6","8","0"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (982, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 101, '{"id":982,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":101,"q":"Most important vitamin, which promotes wound healing ?","o":["Vitamin C","Vitamin D","Vitamin A","Niacin"],"a":0,"e":"Vitamin C is required for collagen synthesis. Due to its important role in collagen synthesis, vitamin C is required for adequate wound healing.","pyqMatches":[{"year":"2014","no":346,"q":"Most important vitamin, which promotes wound healing ?","o":["Vitamin C","Vitamin D","Vitamin A","Niacin"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (983, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 102, '{"id":983,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":102,"q":"Which of the following is not a glycerosphingolipid?","o":["Lecithin","Cardiolipin","Plasmalogens","Sphingomyelin"],"a":3,"e":"Phospholipids are : i. Glycerophospholipids (glycerol containing) :- Phosphatidylcholine (lecithin), phosphatidylethanolamine (cephaline), phosphatidylserine, phosphatidylinositol, plasmalogens, lysophospholipids, cardiolipin. i. Sphingophospholipids (sphingosine containing) :- Sphingomyelin","pyqMatches":[{"year":"2014","no":314,"q":"Which of the following is not a glycerosphingolipid?","o":["Lecithin","Cardiolipin","Plasmalogens","Sphingomyelin"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (984, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 103, '{"id":984,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":103,"q":"Immediate precursor of creatine","o":["Carbamoyl phosphate","Arginosuccinate","Guanidoacetate","Citrulline"],"a":2,"e":"Ans. ''C'' Guanidoacetate Creatine and creatinine are not amino acids, but specialized products of amino acids. Creatine is synthesized from glycine, arginine, and methionine. The synthesis starts with the formation of guanidinoacetate from glycine and arginine in the kidney. Further reactions take place in the liver and muscle.","pyqMatches":[{"year":"2014","no":317,"q":"Immediate precursor of creatine","o":["Carbamoyl phosphate","Arginosuccinate","Guanidoacetate","Citrulline"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (985, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 104, '{"id":985,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":104,"q":"Tyrosine enters gluconeogenesis by forming which substrate","o":["Succinyl CoA","Alpha-ketoglutarate","Fumarate","Citrate"],"a":2,"e":"Ans. ''C'' Fumarate TCA cycle intermediates are the substrate for gluconeogenesis. Gluconeogenic amino acids enter the TCA cycle after their transamination into various intermediates of the TCA cycle:? Histidine, proline, glutamine and arginine are converted to glutamate which is then transaminated to α-​ketoglutarate. Isoleucine, methionine and valine enter by conversion into succinyl CoA. Propionate (a short chain fatty acid) also enter at this level. Tyrosine, and phenylalanine enter by conversion into fumarate. Tryptophan is converted to alanine which is then transaminated to pyruvate. Hydroxyproline, serine, cysteine, threonine and glycine enter by conversion into pyruvate.","pyqMatches":[{"year":"2014","no":290,"q":"Tyrosine enters gluconeogenesis by forming which substrate","o":["Succinyl CoA","Alpha-ketoglutarate","Fumarate","Citrate"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (986, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 105, '{"id":986,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":105,"q":"Fumarate of TCA is derived from transmination of which amino acid","o":["Phenylalanine","Methionine","Valine","Glutamine"],"a":0,"e":"Ans. is. A. Phenylalanine","pyqMatches":[{"year":"2014","no":291,"q":"Fumarate of TCA is derived from transmination of which amino acid","o":["Phenylalanine","Methionine","Valine","Glutamine"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (987, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 106, '{"id":987,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":106,"q":"Alpha helix and Beta pleated sheet are examples of?","o":["Primary","Secondary structure","Tertiary","Quaternary structure"],"a":1,"e":"Ans. ''B'' Secondary structure Structural organization of proteins Every protein has a unique three -dimensional structure, which is referred to as its native conformation and made up of only 20 different amino acids. Protein structure can be classified into four levels of the organization. 1) Primary structures The linear sequence of amino acid residues and the location of disulfide bridges, if any, in a polypep​tide chain constitute its primary structure. In simple words, the primary structure of proteins refers to the specific sequence of amino acids. The primary structure is maintained by the covalent ''peptide'' bond. 2) Secondary structure For stability of the primary structure, hydrogen bonding between the hydrogen of NH and oxygen of C = 0 groups of the polypeptide chain occurs, which gives rise to twisting, folding or bending of the primary structure. Thus, regular folding and twisting of the polypeptide chain brought about by hydrogen bonding is called secondary structure. Important types of secondary structures are a-helix, beta-pleated sheet, and beta-bends. 3) Tertiary structure The peptide chain, with its secondary structure, maybe further folded and twisted about itself forming three-dimensional arrangement of the polypeptide chain, i.e., tertiary structure refers to the overall folding pattern of a polypeptide which forms the three-dimensional shape. The tertiary structure (three-dimensional shape) is maintained by weak non-covalent interactions which include hydrogen bonds, hydrophobic interactions, ionic bond (electrostatic bonds or salt bridges) and Van-der wall forces. Covalent linkage (disulfide bond) also plays some (but minor) role. 4) Quaternary structure Many proteins are made up of more than one polypeptide chain (polymers). Each polypeptide chain is known as protomer (or subunit). The subunit is linked with each other by non-covalent bonds. The structure formed by the union of subunits is known as quaternary structure, i.e., the spatial relation of subunits (peptide chains) with one another is called the quaternary structure. Mainly three non-covalent bonds stabilize quaternary structure: Hydrophobic, hydrogen and ionic (electrostatic). Dimeric proteins contain two polypeptide chains. Homodimers contain two copies of the same polypeptide chain, while in a heterodimer the polypeptides differ.","pyqMatches":[{"year":"2014","no":335,"q":"Alpha helix and Beta pleated sheet are examples of?","o":["Primary","Secondary structure","Tertiary","Quaternary structure"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (988, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 107, '{"id":988,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":107,"q":"RNA polymerase has which activity","o":["Primase","Helicase","Ligase","Topoisomerase"],"a":0,"e":"DNA synthesis cannot commence with deoxyribonucleotides because DNA polymerase cannot add a mononucleotide to another mononucleotide. Thus, DNA polymerase cannot initiate synthesis of complementary DNA synthesis strand of DNA on a totally single stranded template. For this, they require RNA primer, which is a short piece of RNA formed by enzyme primase (RNA polymerase) using DNA as a template. RNA primer is then extended by addition of deoxyribonucleotides. Later on, the ribonucleotides of the primer are replaced by deoxyribonucleotides. Primase is actually a DNA primase which has RNA polymerase activity. This DNA primase is also called DNA polymerase.","pyqMatches":[{"year":"2014","no":354,"q":"RNA polymerase has which activity","o":["Primase","Helicase","Ligase","Topoisomerase"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (989, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 108, '{"id":989,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":108,"q":"which of the following occurs only in mitochondria","o":["ECT","Ketogenesis","Urea cycle","Steroid synthesis"],"a":2,"e":"Ans. D. Urea Cycle Ketogenesis occurs primarily in the mitochondria of liver cells. Fatty acids are brought into the mitochondria via carnitine palmitoyltransferase (CPT-1) and then broken down into acetyl CoA via beta-oxidation In eukaryotes, an important electron transport chain is found in the inner mitochondrial membrane where it serves as the site of oxidative phosphorylation through the action of ATP synthase. Mitochondria are essential sites for steroid hormone biosynthesis. Mitochondria in the steroidogenic cells of the adrenal, gonad, placenta and brain contain the cholesterol side- chain cleavage enzyme, P450scc, and its two electron-transfer partners, ferredoxin reductase and ferredoxin. This enzyme system converts cholesterol to pregnenolone and determines net steroidogenic capacity, so that it serves as the chronic regulator of steroidogenesis. urea is produced through a series of reactions occurring in the cytosol and mitochondrial matrix of liver cells both","pyqMatches":[{"year":"2014","no":313,"q":"which of the following occurs only in mitochondria","o":["ECT","Ketogenesis","Urea cycle","Steroid synthesis"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (990, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 109, '{"id":990,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":109,"q":"Number of structural gene in Lac operon","o":["3","4","5","6"],"a":0,"e":"Lactose operone or Lac operon The lac operon is a region of DNA in the genome of E. coli that contains following genetic elements ? i) Three structural genes :- These code for 3 proteins that are involved in catabolism of lactose. These genes are ''Z'' gene (codes for P-galactosidase), ''Y'' gene (codes for galactoside permease), and ''A'' gene (codes for thiogalactoside transacetylase). ii) Regulatory gene (lac i) It produces repressor protein. iii) A promotor site (P) :- It is the binding site for RNA polymerase. It contains two specific regions ? a) CAP site (Catabolite activator protein binding site). b) RNA polymerase binding site iv) An operator site (0) :- Repressor binds to this site and blocks transcription. 3 Structural genes are expressed only when ''0'' site is empty (repressor is not bound) and the CAP site is bound by a complex of cAMP and CAP (catabolite gene activator protein).","pyqMatches":[{"year":"2014","no":355,"q":"Number of structural gene in Lac operon","o":["3","4","5","6"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (991, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 110, '{"id":991,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":110,"q":"The enzyme involved in initiation of peptide chain synthesis-","o":["Topoisomerase","Transformylase","RNA polymerase","Peptidyl transferase"],"a":1,"e":"Ans. ''B'' Transformylase Steps in eukaryotic translation (protein synthesis) There are three major steps, in protein synthesis (translation):- (i) Initiation, (ii) Elongation; and (iii) Termination. In prokaryotes and in mitochondria, the first amino acid methionine is modified by formylation, i.e. the initiator tRNA carries an N- formylated methionine. The formyl group is added by the enzyme transformylase (formyl-transferase). In Eukaryotes, the initiator tRNA carries a methionine that is not formylated.","pyqMatches":[{"year":"2014","no":356,"q":"The enzyme involved in initiation of peptide chain synthesis","o":["Topoisomerase","Transformylase","RNA polymerase","Peptidyl transferase"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (992, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 111, '{"id":992,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":111,"q":"Strongest interactions among the following","o":["Covalent","Hydrogen","Electrostatic","Van der Waals"],"a":0,"e":"Ans. A. Covalent Strongest bond → Covalent Weakest bond → Van der wals forces Moleucular interactions There are two types of interactions between molecules that stabilize molecular structures :-","pyqMatches":[{"year":"2014","no":364,"q":"Strongest interactions among the following","o":["Covalent","Hydrogen","Electrostatic","Van der Waals"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (993, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 112, '{"id":993,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":112,"q":"Highest mobility on electrophoresis","o":["HDL","VLDL","LDL","Chylomicrons"],"a":0,"e":"As in lipoprotein electrophoresis, HDL shows the highest mobility followed by VLDL, IDL, and LDL. Chylomicrons migrate according to their net-charge between HDL and VLDL because isotachophoresis has negligible molecular sieve effects.","pyqMatches":[{"year":"2014","no":315,"q":"Highest mobility on electrophoresis","o":["HDL","VLDL","LDL","Chylomicrons"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (994, 'Biochemistry', 'Carbohydrate Metabolism', 'Moderate', 'Biochemistry', 113, '{"id":994,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":113,"q":"Regulating enzymes in Gluconeogenesis are all, except","o":["Pyruvate carboxylase","PEP carboxykinase","PFK-1","Glucose-6-phosphatase"],"a":2,"e":"Ans. is. C. PFK-1","pyqMatches":[{"year":"2014","no":288,"q":"Regulating enzymes in Gluconeogenesis are all, except","o":["Pyruvate carboxylase","PEP carboxykinase","PFK-1","Glucose-6-phosphatase"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (995, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 114, '{"id":995,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":114,"q":"Glucagon stimulates","o":["Gluconeogenesis","Glycogenesis","Fatty acid synthesis","Glycolysis"],"a":0,"e":"Ans. ''A'' Gluconeogenesis. Glucagon is a polypeptide hormone that is secreted by the A cells of the islets of Langerhans of the pancreas. It acts by increasing cAMP. 1) Glucagon stimulates glycogenolysis in the liver but not in muscle. Breakdown of glycogen yields glucose. 2) Glucagon stimulates the production of glucose from amino acids (gluconeogenesis). Both glycogenolysis and gluconeogenesis tend to raise plasma glucose levels. 3) Glucagon stimulates lipolysis. Breakdown of lipids yields free fatty acids, which may be oxidized completely to carbon dioxide, or incompletely to form ketone bodies.","pyqMatches":[{"year":"2013","no":193,"q":"Glucagon stimulates","o":["Gluconeogenesis","Glycogenesis","Fatty acid synthesis","Glycolysis"],"a":0,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":297,"q":"Glucagon stimulates","o":["Gluconeogenesis","Glycogenesis","Fatty acid synthesis","Glycolysis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (996, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 115, '{"id":996,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":115,"q":"Which of the following amino acids is purely ketogenic?","o":["Phenylalanine","Leucine","Proline","Tyrosine"],"a":1,"e":"Ans:B.)Leucine Amino acids: Ketogenic : Leucine, Lysine Glucogenic: Valine, Cysteine, Serine,Alanine, Histidine,Threonine, Arginine, Glycine, Glutamate, Proline/Hydroxy proline Both Glucogenic & Ketogenic : Isoleucine, Tyrosine ,Tryptophan , Phenylalanine","pyqMatches":[{"year":"2014","no":333,"q":"Which of the following amino acids is purely ketogenic?","o":["Phenylalanine","Leucine","Proline","Tyrosine"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (997, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 116, '{"id":997,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":116,"q":"Cystathionine lyase requires which cofactor ?","o":["Thiamine","Riboflavin","Pyridoxine","Niacin"],"a":2,"e":"Ans. ''C'' Pyridoxine Hydrolytic cleavage (hydrolysis) of cystathionine forms Homoserine plus cysteine. This reaction is catalyzed by the enzyme cystathionine lyase (cystathionase), which requires cofactor pyridoxal phosphate (the active form of pyridoxine).","pyqMatches":[{"year":"2014","no":336,"q":"Cystathionine lyase requires which cofactor ?","o":["Thiamine","Riboflavin","Pyridoxine","Niacin"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (998, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 117, '{"id":998,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":117,"q":"Most common physiological form of DNA","o":["A-form","B-form","Z-form","C-form"],"a":1,"e":"DNA can exist in at least six forms, i.e. A, B, C, D, E and Z. The B-form of DNA is the most common form of DNA and is right- handed helix. It is the strandard DNA structure with 10 base pairs per turn. Watson and Crick model describes the B-form of DNA. Other forms of DNA are A-form (contains 11 base pairs per turn and is right handed helix) and Z-form (contains 12 base pairs per turn and is left handed helix). Z-form is favored by alternating G-C sequences in alcohol and high salt solution; and is inhibited by alternating A-T sequnces (Note-B form has minimum base pairs per turn, i.e. 10).","pyqMatches":[{"year":"2014","no":357,"q":"Most common physiological form of DNA","o":["A-form","B-form","Z-form","C-form"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (999, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 118, '{"id":999,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":118,"q":"CO acts by inhibiting which component of respiratory chain ?","o":["Cytochrome b","Cytochrome C oxidase","NADH CoQ reductase","Oxidative phosphorylation"],"a":1,"e":"Ans. ''B'' Cytochrome C oxidase Inhibitors of Electron transport chain (Respiratory chain) Complex I:- Barbiturates (amobarbital), piericidin A, rotenone, chlorpromazine, guanethidine. Complex II:- Carboxin, TTFA, malonate. Complex III:- Dimercaprol, BAL, actinomycin A, Naphthyloquinone. Complex IV (cytochrome c oxidase) :- Carbon monoxide (CO), cyanide (CN), H2S, azide (N3-)","pyqMatches":[{"year":"2014","no":267,"q":"CO acts by inhibiting which component of respiratory chain ?","o":["Cytochrome b","Cytochrome C oxidase","NADH CoQ reductase","Oxidative phosphorylation"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1000, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 119, '{"id":1000,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":119,"q":"Specific inhibitor of succinate dehydrogenase?","o":["Fluoroacetate","Arsenite","Malonate","Fluoride"],"a":2,"e":"Ans. C. Malonate Inhibition of the enzyme succinate dehydrogenase by malonate illustrates competitive inhibition by a substrate analog. Succinate dehydrogenase catalyzes the removal of one hydrogen atom from each of the two methylene carbons of succinate.","pyqMatches":[{"year":"2014","no":285,"q":"Specific inhibitor of succinate dehydrogenase?","o":["Fluoroacetate","Arsenite","Malonate","Fluoride"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1001, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 120, '{"id":1001,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":120,"q":"In citric acid cycle, NADH is produced by-","o":["Succinate thiokinase","Succinate dehydrogenase","Isocitrate dehydrogenase","Fumarase"],"a":2,"e":"Ans ''C'' Fumarase NADH is produced and CO2 is liberated at 3 steps : i) Conversion of isocitrate to a-ketoglutarate by isocitrate dehydrogenase ii) Conversion of alpha-ketoglutarate to succinyl CoA by alpha- ketoglutarate dehydrogenase iii) Conversion of L-malate to oxaloacetate by malate dehydrogenase.","pyqMatches":[{"year":"2014","no":283,"q":"In citric acid cycle, NADH is produced by","o":["Succinate thiokinase","Succinate dehydrogenase","Isocitrate dehydrogenase","Fumarase"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1002, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Moderate', 'Biochemistry', 121, '{"id":1002,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":121,"q":"Urea is synthesized in all except","o":["Liver","Brain","Kidney","Spleen"],"a":3,"e":"Urea is synthesized in liver but small quantities (not significant) may be formed in brain and kidney also. Ammonia is ultimately disposed of by formation of urea by \"Kreb''s Henseleit urea cycle\" in the liver. Urea cycle takes place both in mitochondria and cytosol. First two reactions of urea cycle occur in the mitochondria, and remaining reactions occurs in cytosol","pyqMatches":[{"year":"2014","no":320,"q":"Urea is synthesized in all except","o":["Liver","Brain","Kidney","Spleen"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1003, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 122, '{"id":1003,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":122,"q":"Which of the following step is specific for gluconeogenesis","o":["Pyrovate to acetyl CoA","Oxaloacetate to citrate","Oxaloacetate to PEP","Oxaloacetate to PEP"],"a":2,"e":"Ans. is ''c'' i.e., Oxaloacetate to PEP","pyqMatches":[{"year":"2014","no":289,"q":"Which of the following step is specific for gluconeogenesis","o":["Pyrovate to acetyl CoA","Oxaloacetate to citrate","Oxaloacetate to PEP","Oxaloacetate to PEP"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1004, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 123, '{"id":1004,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":123,"q":"Pyruvate can be a substrate for","o":["Fatty acid synthesis","TCA cycle","Cholesterol synthesis","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above Pyruvate a It is a degradation product of glucose (glycolysis) and glycogenic aminoacids. It can be converted to glucose (gluconeogenesis through oxaloacetate) and acetyl CoA (therefore all biosynthetic products which arise from acetyl CoA)","pyqMatches":[{"year":"2014","no":294,"q":"Pyruvate can be a substrate for","o":["Fatty acid synthesis","TCA cycle","Cholesterol synthesis","All of the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1005, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 124, '{"id":1005,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":124,"q":"In oxidative pathway, NADPH is produced in ?","o":["Cytosol","Mitochondria","Ribosome","Peroxisomes"],"a":0,"e":"Ans. is ''a'' i.e., Cytosol NADPH is produced mainly in HMP shunt, which occurs cytosol. HMP is an alternative route for the oxidation of glucose (beside glycolysis). It is also called as \"pentose phosphate pathway\", \"Dickens - Horecker pathway\", \"Shunt pathway\" or \"phosphogluconate oxidative pathway\". HMP shunt is required for provision of reduced NADPH and fiver- carbon sugars e.g. ribose (Pentose phosphates) for nucleic acid synthesis. Normally, 90% of glucose is oxidized by glycolysis and 10% is oxidized by HMP shunt. However, in liver and RBCs HMP shunt accounts for oxidation of 30% glucose. HMP shunt occurs in the cytosol. It is highly active in liver, adipose tissue, adrenal cortex, lens, cornea, lactating (but not the nonlactating) mammary gland. Gonads (testis, ovary) and erythrocytes. Activity of this pathway is minimal in muscle and brain, where almost all of the glucose is degraded by glycolysis.","pyqMatches":[{"year":"2014","no":269,"q":"In oxidative pathway, NADPH is produced in ?","o":["Cytosol","Mitochondria","Ribosome","Peroxisomes"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1006, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 125, '{"id":1006,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":125,"q":"Glucose is converted to sorbitol by ?","o":["Aldolase B","Aldose reductase","Sorbitol dehydrogenase","All of these"],"a":1,"e":"Ans. is ''b'' i.e., Aldose reductase","pyqMatches":[{"year":"2014","no":295,"q":"Glucose is converted to sorbitol by ?","o":["Aldolase B","Aldose reductase","Sorbitol dehydrogenase","All of these"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1007, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 126, '{"id":1007,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":126,"q":"Lactose intolerance is due to ?","o":["Deficiency of Galactokinase","Deficiency of Uridyl transferase","Deficiency of Lactase","Deficiency of Enteropeptidase"],"a":2,"e":"Ans. is ''c'' i.e., Deficiency of Lactase Lactose intolerance It occurs due to deficiency of lactase, the most important member of β-galactosidase enzymatic class. Lactase hydrolyses lactose into glucose and galactose in the small intestine. Lactose is present in milk. Therefore, deficiency of lactase, (β-galactosidase) results in intolerance to milk and other dairy products. Clinical features are bloating, diarrhea, failure to thrive, abdominal distension and abdominal cramp.","pyqMatches":[{"year":"2014","no":296,"q":"Lactose intolerance is due to ?","o":["Deficiency of Galactokinase","Deficiency of Uridyl transferase","Deficiency of Lactase","Deficiency of Enteropeptidase"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1008, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 127, '{"id":1008,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":127,"q":"Deficiency of which vitamin causes excretion of xantheurenic acid in urine ?","o":["Folic acid","Pyridoxin","Niacin","Vitamin B12"],"a":1,"e":"Ans. is ''b'' i.e., Pyridoxin","pyqMatches":[{"year":"2014","no":347,"q":"Deficiency of which vitamin causes excretion of xantheurenic acid in urine ?","o":["Folic acid","Pyridoxin","Niacin","Vitamin B12"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1009, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 128, '{"id":1009,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":128,"q":"Total number of dehydrogenases Krebs cycle ?","o":["3","2","4","5"],"a":2,"e":"Ans. is ''c'' i.e., 4","pyqMatches":[{"year":"2014","no":282,"q":"Total number of dehydrogenases Krebs cycle ?","o":["3","2","4","5"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1010, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 129, '{"id":1010,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":129,"q":"Number of ATP generated in one TCA cycle ?","o":["2","8","10","11"],"a":2,"e":"Ans. is ''c'' i.e., 10 In a single TCA cycle 10 molecules of ATP are produced (12 molecules according to older calculations). One turn of the TCA cycle, starting with acetyl CoA produces 10 ATPs. When the starting molecule is pyruvate, the oxidative decarboxylation of pyruvate, the oxidative decarboxylation of pyruvate yields 2.5 ATPs and therefore, 12.5 ATPs are produced when starting compound is pyruvate. Since, two molecules of pyruvate enter the TCA cycle when glucose is metabolized (glycolysis produces 2 molecules of pyruvate), the number of ATPs is doubled. Therefore, 25 ATP molecules, per glucose molecule, are produced when pyruvate enters the TCA cycle. Note : Previously calculations were made assuming that NADH produces 3 ATPs and FADH generates 2 ATPs. This will amount a net generation of 30 ATP molecules in TCA per molecule glucose and total 38 molecules from starting. Recent experiments show that these values are overestimates and NADH produces 2.5 ATPs and FADH produces 1.5 ATPs. Therefore, net generation during TCA is 25 ATPs and complete oxidation of glucose through glycolysis plus citric acid cycle yield a net 32 ATPs. Energy yield (number of ATP generated) per molecule of glucose when it is completely oxidized through glycoly​sis plus citric acid cycle, under aerobic conditions, is as follows :-","pyqMatches":[{"year":"2014","no":280,"q":"Number of ATP generated in one TCA cycle ?","o":["2","8","10","11"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1011, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Hard', 'Biochemistry', 130, '{"id":1011,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Hard","source":"Biochemistry","sourceNo":130,"q":"If urine sample darkens on standing: the most likely conditions is ?","o":["Phenylketonuria","Alkaptonuria","Maple syrup disease","Tyrosinemia"],"a":1,"e":"Ans. is ''b'' i.e., Alkaptonuria Alkaptonuria It is due to deficiency of homogentisate oxidase. As a result homogentisic acid (homogentisate) is excreted execessively in urine. There arc three important characteristic features in alkaptonuria? i) Urine becomes dark after being exposed to air. It is due spontaneous oxidation of homogentisate into benzoquinone acetate, which polymerse to form black-brown pigment alkapton which imparts a characteristic black-brown colour to urine. ii) Alkapton deposition occurs in sclera, ear, nose, cheeks and intervertebral disc space. A condition called ochronosis. There may be calcification of intervertebral discs. iii) Onchronosis arthritis affecting shoulder, hips, knee. Benedict''s test is strongly positive in urine and so is the ferric chloride (FeC1 3)test. Benedict''s reagent gives a greenish brown precipitate with brownish black supernatent. Fehling''s reagent (FeC13) gives blue green colour.","pyqMatches":[{"year":"2014","no":326,"q":"If urine sample darkens on standing: the most likely conditions is ?","o":["Phenylketonuria","Alkaptonuria","Maple syrup disease","Tyrosinemia"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1012, 'Biochemistry', 'Carbohydrate Metabolism', 'Moderate', 'Biochemistry', 131, '{"id":1012,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":131,"q":"Which of the following enzyme does not catalyzes irreversible step in glycolysis ?","o":["Hexokinase","Phosphoglycerate kinase","Pyruvate kinase","Phosphofructokinase"],"a":1,"e":"Ans. is ''b'' i.e., Phosphoglycorate kinase Glycolysis is regulated at 3 steps which are irreversible. These reactions are catalyzed by following key enzymes :? 1) Hexokinase and glucokinase 2) Phosphofructokinase - I 3) Pyruvate kinase.","pyqMatches":[{"year":"2014","no":277,"q":"Which of the following enzyme does not catalyzes irreversible step in glycolysis ?","o":["Hexokinase","Phosphoglycerate kinase","Pyruvate kinase","Phosphofructokinase"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1013, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 132, '{"id":1013,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":132,"q":"Taurine is made from ?","o":["Glycine","Tyrosine","Cysteine","Phenylalanine"],"a":2,"e":"Ans. is ''c'' i.e., Cysteine Taurine is synthesized from cysteine.","pyqMatches":[{"year":"2014","no":337,"q":"Taurine is made from ?","o":["Glycine","Tyrosine","Cysteine","Phenylalanine"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1014, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 133, '{"id":1014,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":133,"q":"Amino acid carrying ammonia from muscle to liver?","o":["Alanine","Glutamine","Arginine","Lysine"],"a":0,"e":"Ans. is ''a'' i.e., Alanine. DISPOSAL/DETOXIFICATION OF AMMONIA","pyqMatches":[{"year":"2014","no":323,"q":"Amino acid carrying ammonia from muscle to liver?","o":["Alanine","Glutamine","Arginine","Lysine"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1015, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 134, '{"id":1015,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":134,"q":"FIGLU excretion test is used for assessment of deficiency of ?","o":["Vitamin B12","Niacin","Folic acid","Pyridoxin"],"a":2,"e":"Ans. is ''c'' i.e., Folic acid Assessment of folate deficiency Following tests arc used for assessment of folate deficiency. i) Blood level :- Normal level in serum is about 2-20 nanogram/ml and about 200 micorgram/ml of packed cells. ii) Histidine load test or FIGLU excretion test :- Histidine is normally metabolized to formimino glutamic acid (FIGLU) from which formimino group is removed by THF. Therefore in folate deficiency, FIGLU excretion is increased in urine.","pyqMatches":[{"year":"2014","no":348,"q":"FIGLU excretion test is used for assessment of deficiency of ?","o":["Vitamin B12","Niacin","Folic acid","Pyridoxin"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1016, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 135, '{"id":1016,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":135,"q":"Role of molecular oxygen in ETC ?","o":["Transfer of reducing equivalent to CoQ","Transfer of reducing equivalent from cytosol to mitochondria","To act as last electron acceptor","Generation of ATP"],"a":2,"e":"Ans. is ''c'' i.e., To act as last electron acceptor Structural organizations of components of ETC 3 Components of respiratory chain do not function as discrete carriers of reducing equivalent but are organized into four complexes each of which acts as a specific oxidoreductase. Coenzyme Q and cytochrome C are not parts of any complex and are not fixed in the inner mitochondria! membrane. The other components are fixed in the membrane. These components are arranged in order of increasing redox potential. Therefore, reducing equivalents (electrons) flow in one direction, I ---> II --> III --> IV, only because redox couple with low redox potential is better electron donor where as the one with high redox potential is electron acceptor. Thus, reducing equivalents (electrons) flow through the chain from the components of more negative redox potential to the components of more positive redox potential. i) Complex I (NADH - CoQ reductase) catalyzes the transfer of electron from NADH to coenzyme Q (CoQ). ii) Complex II (Succinate - CoQ reductase or succinate dehydrogenase) transfers electrons from succinate to coenzyme Q. iii) Complex III (CoQ - cytochrome C reductase), transfers electron from CoQ to cytochrome C. iv) Complex IV (cytochrome C oxidase) transfers electrons from cytochrome C to 02 cytochrome C to 02.","pyqMatches":[{"year":"2014","no":270,"q":"Role of molecular oxygen in ETC ?","o":["Transfer of reducing equivalent to CoQ","Transfer of reducing equivalent from cytosol to mitochondria","To act as last electron acceptor","Generation of ATP"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1017, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 136, '{"id":1017,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":136,"q":"Which of the following is a homopolysaccharide?","o":["Heparin","Chitin","Hyaluronic acid","Chondroitin sulfate"],"a":1,"e":"Ans. is ''b'' i.e., Chitin Polysaccharides are classified into ? a) Homopolysaccharides (Homoglycans) :- This type of polysaccharide is made up of several units of same monosaccharide unit only. Examples are starch (multiple units of glucose), glycogen (multiple units of glucose), cellulose (multiple units of glucose), Inulin (multiple unit of fructose), Dextrin, Dextran (multiple units of glucose), and chitin. b) Heteropolysaccharides (Heteroglycans) :- This type of polysaccharide contains two or more different types of monosacharide units. Examples are heparin, heparan sulfate, chondroitin sulfate, dermatan sulfate, hyaluronic acid, keratan sulfate and blood group polysaccharides.","pyqMatches":[{"year":"2014","no":365,"q":"Which of the following is a homopolysaccharide?","o":["Heparin","Chitin","Hyaluronic acid","Chondroitin sulfate"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1018, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Moderate', 'Biochemistry', 137, '{"id":1018,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":137,"q":"If tyrosine level in blood is normal without external supplementation, deficiency of which of the following is ruled out ?","o":["Tryptophan","Phenylalanine","Histidine","Isoleucine"],"a":1,"e":"Ans. is ''b'' i.e., Phenylalanine Tyrosine is synthesized from phenylalanine. In phenylalanine deficiency or in disorders in which phenylalanine cannot be converted into tyrosine (phenylketonuria), tyrosine becomes an essential amino acid and should be supplemented from outside.","pyqMatches":[{"year":"2014","no":338,"q":"If tyrosine level in blood is normal without external supplementation, deficiency of which of the following is ruled out ?","o":["Tryptophan","Phenylalanine","Histidine","Isoleucine"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1019, 'Biochemistry', 'Clinical Biochemistry', 'Easy', 'Biochemistry', 138, '{"id":1019,"subject":"Biochemistry","chapter":"Clinical Biochemistry","difficulty":"Easy","source":"Biochemistry","sourceNo":138,"q":"End product of porphyrin metabolism ?","o":["Albumin","CO2 & NH2","Bilirubin","None"],"a":2,"e":"Ans. is ''c'' i.e., Bilirubin Heme is the most important porphyrin. It is degraded into bilirubin.","pyqMatches":[{"year":"2014","no":363,"q":"End product of porphyrin metabolism ?","o":["Albumin","CO2 & NH2","Bilirubin","None"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1020, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 139, '{"id":1020,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":139,"q":"Hunter syndrome is due to deficiency of","o":["Beta galactosidase","Sphingomyelinase","Iduronate Sulfatase","Hyaluronidase"],"a":2,"e":"Ans. is ''c'' i.e., Iduronate Sulfatase","pyqMatches":[{"year":"2012","no":315,"q":"Hunter syndrome is due to deficiency of","o":["Beta galactosidase","Sphingomyelinase","Iduronate Sulfatase","Hyaluronidase"],"a":2,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":309,"q":"Hunter syndrome is due to deficiency of","o":["Beta galactosidase","Sphingomyelinase","Iduronate Sulfatase","Hyaluronidase"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1021, 'Biochemistry', 'Carbohydrate Metabolism', 'Moderate', 'Biochemistry', 140, '{"id":1021,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":140,"q":"UDP glucose is not used in ?","o":["Uronic acid pathway","Glycogen synthesis","Galactose metabolism","HMP shunt"],"a":3,"e":"Ans. is ''d'' i.e., HMP shunt UDP-glucose is derived from glucose-6-phosphate via glucose-l- phosphate. The major fate of UDP-glucose is the synthesis of glycogen. Other uses of UDP-glucose are -","pyqMatches":[{"year":"2014","no":278,"q":"UDP glucose is not used in ?","o":["Uronic acid pathway","Glycogen synthesis","Galactose metabolism","HMP shunt"],"a":3,"source":"NEET_2014_Paper.pdf"},{"year":"2016","no":259,"q":"UDP glucose is not used in ?","o":["Uronic acid pathway","Glycogen synthesis","Galactose metabolism","HMP shunt"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2014","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1022, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 141, '{"id":1022,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":141,"q":"Number of ATP molecules and NADH formed in each cycle of glycolysis ?","o":["4 ATP, 2 NADH","2 ATP, 2 NADH","4 ATP, 4 NADH","2 ATP, 4 NADH"],"a":0,"e":"Ans. is ''a'' i.e., 4 ATP, 2 NADH Enegetics of glvcolysis During glycolysis 2 ATP are utilized and 4 ATP are produced at substrate level. 2 reducing equalents NADH'' are produced and reoxidized by electron transport chain, to generata 5 ATP molecules (2.5 ATP per NADH'' molecule). Thus total 9 ATP molecules are produced and 2 are utilized, i.e., There is net gain of 7 ATP molecules in aerobic glycolysis. In anaerobic conditions, the reoxidation of NADH by electron transport chain is prevented and NADH gets reoxidized by conversion of pyruvate to lactate by lactate dehydrogenase. Thus, in anaerobic glycolysis only 4 ATP are produced at substrate level. Therefore, there is net gain of 2 ATP molecules in anaerobic glycolysis. Note : - Previous calculations were made assuming that NADH produces 3 ATPs and FADH2 generates 2 ATPs. This will amount to a net generation of 8ATPs per glucose molecule during glycolysis. Recent experiments show that these old values are overestimates and NADH produces 2.5 ATPs and FADH2 produces 1.5 ATPs. Thus, net generation is only 7ATPs during glycolysis.","pyqMatches":[{"year":"2012","no":262,"q":"Number of ATP molecules and NADH formed in each cycle of glycolysis ?","o":["4 ATP, 2 NADH","2 ATP, 2 NADH","4 ATP, 4 NADH","2 ATP, 4 NADH"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":276,"q":"Number of ATP molecules and NADH formed in each cycle of glycolysis ?","o":["4 ATP, 2 NADH","2 ATP, 2 NADH","4 ATP, 4 NADH","2 ATP, 4 NADH"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1023, 'Biochemistry', 'Molecular Biology', 'Moderate', 'Biochemistry', 142, '{"id":1023,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Moderate","source":"Biochemistry","sourceNo":142,"q":"Which of the following is not true regarding ETC?","o":["Occurs in mitochondria","Generates ATP","No role of inorganic phosphate","Involves transport of reducing equivalent"],"a":2,"e":"Ans. is ''c'' i.e., No role of inorganic phosphate Inorganic phosphate (Pi) is required in ETC to generate ATP. ADP+pi --> ATP ETC occurs in mitochondria and involves transfer of reducing equivalent to generate ATP","pyqMatches":[{"year":"2014","no":271,"q":"Which of the following is not true regarding ETC?","o":["Occurs in mitochondria","Generates ATP","No role of inorganic phosphate","Involves transport of reducing equivalent"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1024, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 143, '{"id":1024,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":143,"q":"Proteins are separated on the basis of charge in ?","o":["SDS-PAGE","Ultracentrifugation","Affinity chromatography","HPLC"],"a":3,"e":"Ans. is ''d'' i.e., HPLC","pyqMatches":[{"year":"2014","no":366,"q":"Proteins are separated on the basis of charge in ?","o":["SDS-PAGE","Ultracentrifugation","Affinity chromatography","HPLC"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1025, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 144, '{"id":1025,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":144,"q":"Isoform of LDH in skeletal muscles ?","o":["LDH-1","LDH-2","LDH-3","LDH-4"],"a":3,"e":"Ans. is ''d'' i.e., LDH-4 Skeletal muscles contain LDH-4 and LDH-5","pyqMatches":[{"year":"2014","no":263,"q":"Isoform of LDH in skeletal muscles ?","o":["LDH-1","LDH-2","LDH-3","LDH-4"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1026, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 145, '{"id":1026,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":145,"q":"Following is true regarding sulhydryl groups except?","o":["They are present in coenzyme A and lipoic acid","They are present in Captopril and penicillamine","They are not involved in reduction of peroxides","They are present in cysteine"],"a":2,"e":"Ans. is ''c'' i.e., They are not involved in reduction of peroxides Sulfhydryl Group (or thiol group) It is an SH group of organic compounds. Sulfhydryl groups have great and varied reactivity. They oxidize easily, with the formation of disulfides and sulfenic, sulfinic, or sulfonic acids, and they readily undergo alkylation, acylation, and thiol-disulfide exchange. They form mercaptides upon reacting with the ions of heavy metals, and they form mercaptals and mercaptols upon reacting with aldehydes and ketones, respectively. Sulfhydryl groups play an important role in biochemical processes. The sulfhydryl groups of coenzyme A, lipoic acid, and 4''- phosphopantotheine participate in enzymatic reactions for the formation and transfer of acyl residues that are related to lipid and carbohydrate metabolism. The sulfhydryl groups of glutathione play an important role in the neutralization of foreign organic compounds and the reduction of peroxides; they are also of major importance in the fulfillment by glutathione of its function as a coenzyme. In proteins, residues of the amino acid cysteine have sulfhydryl groups. As components of the active centers of a number of enzymes, sulfhydryl groups participate in the catalytic effect of the enzymes and in the binding of substrates, coenzymes, and metal ions. Drugs containing sulfhydryl groups are: captopril, zofenopril and penicillamine.","pyqMatches":[{"year":"2014","no":367,"q":"Following is true regarding sulhydryl groups except?","o":["They are present in coenzyme A and lipoic acid","They are present in Captopril and penicillamine","They are not involved in reduction of peroxides","They are present in cysteine"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1027, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 146, '{"id":1027,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":146,"q":"Cause of Herpes Zoster ?","o":["Primary infection with VZV","Recurrent infection with VZV","Reactivation of latent infection of VZV","Multiple infection with VZV"],"a":2,"e":"Ans. is ''c'' i.e., Reactivation of latent infection of VZV Varicella zoster virus infection Varicella (Chicken pox) and Herpes zoster are different manifestations of the same virus infection. The virus is therefore called varicella zoster virus (VZA) Primary infection with VZV causes chicken pox. Reactivation of latent VZV, when immunity has fallen to ineffective levels causes-Herpes zoster The virus remains dormant in sensory ganglion of trigeminal nerve and reaches the eye along one or more branches of the opthalmic division of the 5th nerve Herpes Zoster (Shingles) Occurs in old age 60 years or above As a consequence of reactivation of latent infection from the dorsal root ganglion. o Unilateral vesicular eruptions within a dermatomal distribution Dermatomes from T3 to L3 and trigeminal nerve (especially ophthalmic branch) are involved. o Zoster ophthalmicus - due to reactivation in ophthalmic branch of trigeminal (gasserian) ganglia o Ramsay Hunt Syndrome - due to reactivation in geniculate ganglion of facial nerve. o Complications Post herpetic neuralgia - most debilitating complication","pyqMatches":[{"year":"2014","no":798,"q":"Cause of Herpes Zoster ?","o":["Primary infection with VZV","Recurrent infection with VZV","Reactivation of latent infection of VZV","Multiple infection with VZV"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1028, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 147, '{"id":1028,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":147,"q":"Bile acids are synthesized from ?","o":["Heme","Cholesterol","Ribulose","Arachidonic acid"],"a":1,"e":"Ans. is ''b'' i.e., Cholesterol Primary bile acids are cholic acid and chenodeoxycholic acid, which are synthesized from cholesterol in liver. In the intestine some of the primary bile acids are converted into secondary bile acids, i.e., deoxycholic acid (formed from cholic acid) and lithocholic acid (derived from chenodexoxycholic acid). Glycine and taurine conjugates of these bile acids are called as bile salts. For example, cholic acid is a bile acid, and its glycine conjugate (glycocholic acid) is a bile salt. Bile salts help in digestion and absorption of fat by emulsification and micelles formation. Bile salts act as detergents, i.e., they have surface tension lowering action. Detergent action is due to amphipathic nature of bile salts (Note : Amphipathic molecules are molecules that contain both hydrophobic non-polar as well as hydrophilic-polar ends).","pyqMatches":[{"year":"2015","no":315,"q":"Bile acids are synthesized from ?","o":["Heme","Cholesterol","Ribulose","Arachidonic acid"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1029, 'Biochemistry', 'Carbohydrate Metabolism', 'Moderate', 'Biochemistry', 148, '{"id":1029,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":148,"q":"Not a substrate for gluconeogenesis -","o":["Glycerol","Leucine","Lactate","Propionate"],"a":1,"e":"Ans. is ''b'' i.e., Leucine Substrates for gluconeognesis ?","pyqMatches":[{"year":"2015","no":303,"q":"Not a substrate for gluconeogenesis","o":["Glycerol","Leucine","Lactate","Propionate"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1030, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 149, '{"id":1030,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":149,"q":"Rate limiting enzyme in bile acid synthesis ?","o":["Desmolase","21 α-hydroxylase","7α-hydroxylase","12α-hydroxylase"],"a":2,"e":"Ans. is ''c'' i.e., 7α-hydroxylase About half of the cholesterol in the body is ultimately metabolized to bile acids. The primary bile acids are synthesized from cholesterol in liver. These are cholic acid and chenodeoxycholic acid. Rate limiting enzyme in primary bile acids synthesis is 7α - hydroxylase (cholesterol 7α - hydroxylase). This enzyme is inhibited by bile acids and induced by cholesterol. Thyroid hormones induce transcription of 7a-hydroxylase, thus in patients with hypothyroidism plasma cholesterol tends to rise (because of inhibition of 7α-hydroxylase which in turn inhibits conversion of cholesterol to bile acids).","pyqMatches":[{"year":"2015","no":294,"q":"Rate limiting enzyme in bile acid synthesis ?","o":["Desmolase","21 α-hydroxylase","7α-hydroxylase","12α-hydroxylase"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1031, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 150, '{"id":1031,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":150,"q":"Rate limiting enzyme in catecholamine synthesis?","o":["Dopa decarboxylase","N-methyltransferase","Dopamine hydroxylase","Tyrosine hydroxylase"],"a":3,"e":"Ans. is ''d'' i.e., Tyrosine hydroxylase","pyqMatches":[{"year":"2016","no":285,"q":"Rate limiting enzyme in catecholamine synthesis?","o":["Dopa decarboxylase","N-methyltransferase","Dopamine hydroxylase","Tyrosine hydroxylase"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1032, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 151, '{"id":1032,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":151,"q":"NAD+ Acts as a coenzyme for ?","o":["Xanthine oxidase","L-amino acid oxidase","Succinate dehydrogenase","Malate dehydrogenase"],"a":3,"e":"Ans. ''D'' Malate dehydrogenase NAD -linked dehydrogenases Pyruvate dehydrogenase, isocitrate dehydrogenase, malate dehydrogenase, a-ketoglutarate dehydrogenase, glutamate dehydrogenase, glyceraldehyde-3-P dehydrogenase, lactate dehy​drogenase, 13-hydroxy acyl CoA dehydrogenase, glycerol 3-P dehydrogenase (cytoplasmic). NADP*-linked dehydrogenases Glucose-6-P dehydrogenase, 6- Phosphogluconate dehydrogenase, 3-ketoacyl reductase, Enoyl reductase, gulonate dehydrogenase. FAD-linked dehydrogenases Succinate dehydrogenase, fatty acyl CoA dehydrogenase, glycerol-3P dehydro​genase (mitochondrial).","pyqMatches":[{"year":"2016","no":238,"q":"NAD+ Acts as a coenzyme for ?","o":["Xanthine oxidase","L-amino acid oxidase","Succinate dehydrogenase","Malate dehydrogenase"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1033, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 152, '{"id":1033,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":152,"q":"True about tRNA ?","o":["80% of total RNA","Contains 50-60 nucleotides","CCA sequence is transcribed","Longest RNA"],"a":2,"e":"\"The CCA tail is a CCA sequence at 3'' end of the tRNA molecule. In prokaryotes, CCA sequence is transcribed. In eukaryotes, the CCA sequence is added during processing\". \"tRNA is the smallest of three major species of RNAs\" — Dinesh puri tRNA comprises 15% of total RNA in the cell. It contains 73-93 nucleotide residue.","pyqMatches":[{"year":"2016","no":333,"q":"True about tRNA ?","o":["80% of total RNA","Contains 50-60 nucleotides","CCA sequence is transcribed","Longest RNA"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1034, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 153, '{"id":1034,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":153,"q":"Selenocysteine is associated with ?","o":["Carbonic anhydrase","Catalase","Deiodinase","Transferase"],"a":2,"e":"Ans. C. Deiodinase Selenocysteine is considered as 21 standard amino acid. It is present at the active site of some enzymes that catalyze redox reactions, e.g. thioredoxin reductase, glutathione peroxidase, and the deiodinase (converts thyroxin to triiodothyronine). Biosynthesis of selenocysteine requires cysteine, serine, ATP and a specific t-RNA. Serine provides the carbon skeleton of selenocysteine. Selenocysteine has a structure similar to cysteine, but containing the trace element selenium in place of sulfur atom of cysteine.","pyqMatches":[{"year":"2012","no":320,"q":"Selenocysteine is associated with ?","o":["Carbonic anhydrase","Catalase","Deiodinase","Transferase"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1035, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 154, '{"id":1035,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":154,"q":"Which vitamin is required for transfer of 1-carbon unit?","o":["Vitamin A","Folic acid","Vitamin B12","Niacin"],"a":1,"e":"Folic acid [Ref Harper 29m/e p. 537-539, Vasudevan ele p. 400- 402] Goups, containing a single carbon atom are called one carbon groups. One carbon groups are formed from following amino acids during their metabolism:- Serine, glycine, histidine and tryptophan. One carbon groups formed during metabolism are: methyl (C113), methylene (CH,), methenyl (C H), formyl (CHO) and formimino (CH=NH) These one carbon groups are transferred by way of tetrahydrofolate (THF), which is derivative of folic acid°. One carbon groups carried by THF are attached either to nitrogen N5 or Mc'' or to both N5 and N\"). Different one corbon derivatives of THF are- N5- methyl THF, N5, N''°-methylene THF, N5, N\"-methenyl THF, N5-formyl THF and N5-formimino THE These derivatives are interconvertable.","pyqMatches":[{"year":"2013","no":342,"q":"Which vitamin is required for transfer of 1-carbon unit?","o":["Vitamin A","Folic acid","Vitamin B12","Niacin"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1036, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 155, '{"id":1036,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":155,"q":"Heme is synthesized from ?","o":["Lysine + succinyl CoA","Glycine + succinyl CoA","Arginine + Malonyl CoA","Glycine + Malonyl CoA"],"a":1,"e":"Ans. B. Glycine + succinyl CoA Organelle: Partly cytoplasmic and partly mitochondrial Starting materials: Succinyl CoA and Glycine","pyqMatches":[{"year":"2016","no":351,"q":"Heme is synthesized from ?","o":["Lysine + succinyl CoA","Glycine + succinyl CoA","Arginine + Malonyl CoA","Glycine + Malonyl CoA"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1037, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 156, '{"id":1037,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":156,"q":"Splicing is a process of ?","o":["Activation of protein","Removal of introns","Synthesis of protein","Replication of DNA"],"a":1,"e":"In molecular biology and genetics, splicing is a modification of an RNA after transcription, in which introns are removed and exons are joined. This is needed for the typical eukaryotic messenger RNA before it can be used to produce a correct protein through translation. For many eukaryotic introns, splicing is done in a series of reactions which are catalyzed by the spliceosome a complex of small nuclear ribonucleoproteins (snRNAs), but there are also self-splicing introns.","pyqMatches":[{"year":"2016","no":330,"q":"Splicing is a process of ?","o":["Activation of protein","Removal of introns","Synthesis of protein","Replication of DNA"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1038, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 157, '{"id":1038,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":157,"q":"Creatinine is formed from -","o":["Glycine","Lysine","Leucine","Histamine"],"a":0,"e":"Ans. A. Glycine Creatinine and creatine are synthesized from glycine, arginine, and methionine. Synthesis of creatine and creatinine Creatine and creatinine are not amino acids, but specialized products of amino acids. Creatine is synthesized from glycine, arginine, and methionine. The synthesis starts with the formation of guanidinoacetate from glycine and arginine in the kidney. Further reactions take place in the liver and muscle.","pyqMatches":[{"year":"2015","no":331,"q":"Creatinine is formed from","o":["Glycine","Lysine","Leucine","Histamine"],"a":0,"source":"NEET_2015_Paper.pdf"},{"year":"2016","no":281,"q":"Creatinine is formed from :","o":["Arginine","Lysine","Leucine","Histamine"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2015","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1039, 'Biochemistry', 'Genetics', 'Easy', 'Biochemistry', 158, '{"id":1039,"subject":"Biochemistry","chapter":"Genetics","difficulty":"Easy","source":"Biochemistry","sourceNo":158,"q":"Most commonly used vector for DNA cloning ?","o":["Plasmid","Virus","Cosmid","Phage"],"a":0,"e":"Ans: A. Plasmid A cloning vector is a carrier DNA molecule to which human DNA fragment is attached. Normally, foreign DNA fragments cannot self- replicate within host cell. Therefore, they are joined to a vector DNA, that can replicate within host cell. The five major types of cloning vectors used are - * Plasmids * Viral vectors/Bacteriophages * Cosmids * Bacterial Artificial Chromosomes (BACs) * Yeast artificial chromosomes (YACs)","pyqMatches":[{"year":"2016","no":334,"q":"Most commonly used vector for DNA cloning ?","o":["Plasmid","Virus","Cosmid","Phage"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1040, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 159, '{"id":1040,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":159,"q":"Richest source of vitamin B12 ?","o":["Meat","Green leafy vegetables","Corn oil","Sunflower oil"],"a":0,"e":"Ans. is ''a'' i.e., Meat Vitamin B12 is naturally found in animal products, including fish, meat, poultry, eggs, milk, and milk products. Vitamin B12 is generally not present in plant foods, but fortified breakfast cereals are a readily available source of vitamin B12 with high bioavailability for vegetarians. Rich source of vitamin B12→ Beef, liver, and chicken. Fish and shellfish such as trout, salmon, tuna fish, and clams. Fortified breakfast cereal. Low-fat milk, yogurt, and cheese. Eggs.","pyqMatches":[{"year":"2016","no":314,"q":"Richest source of vitamin B12 ?","o":["Meat","Green leafy vegetables","Corn oil","Sunflower oil"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1041, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 160, '{"id":1041,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":160,"q":"Keshan disease in due to deficiency of","o":["Selenium","Copper","Zinc","Iron"],"a":0,"e":"Ans. ''a'' Selenium Selenium is required for the synthesis of the amino acid selenocysteine. Selenocysteine is present at the active site of several human enzymes that catalyze redox reactions. Impairments in human selenoproteins have been implicated in tumorigenesis and atherosclerosis, and are associated with selenium deficiency cardiomyopathy (Keshan disease)","pyqMatches":[{"year":"2014","no":1633,"q":"Keshan disease in due to deficiency of","o":["Selenium","Copper","Zinc","Iron"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1042, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 161, '{"id":1042,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":161,"q":"PFK-I inhibitor ?","o":["AMP","Citrate","Glucose 6 phosphate","Insulin"],"a":1,"e":"Ans. is ''b'' i.e., Citrate","pyqMatches":[{"year":"2013","no":265,"q":"PFK-I inhibitor ?","o":["AMP","Citrate","Glucose 6 phosphate","Insulin"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1043, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 162, '{"id":1043,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":162,"q":"All are used in gluconeogenesis except ?","o":["Oleate","Succinate","Glutamate","Aspartate"],"a":0,"e":"Ans. is ''a'' i.e., Oleate Substrate of gluconeogenesis are : Lactate (lactic acid) Pyruvate All amino acids (except leucine and lysine) Propionate Intermediates of citric acid cycle Fatty acids are not substrates for gluconeogenesis. Coming to the question Fatty acids (oleate in the question) is not a substrate for gluconeogenesis. Succinate is an intermediate of TCA cycle, and is a substrate for gluconeogenesis. All amino acids (in the question glutamate and aspartate), except leucine and lysine are substrates for gluconeogenesis.","pyqMatches":[{"year":"2013","no":269,"q":"All are used in gluconeogenesis except ?","o":["Oleate","Succinate","Glutamate","Aspartate"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1044, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 163, '{"id":1044,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":163,"q":"Main enzyme for glycogen metabolism ?","o":["Glucose-6-phosphatase","Glycogen synthase","PFK - 1","None of the above"],"a":1,"e":"Ans. is ''b'' i.e., Glycogen synthase","pyqMatches":[{"year":"2013","no":374,"q":"Main enzyme for glycogen metabolism ?","o":["Glucose-6-phosphatase","Glycogen synthase","PFK - 1","None of the above"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1045, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 164, '{"id":1045,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":164,"q":"Action of metalloproteinase ?","o":["Degradation of collagen","Polymerization of collagen","Oxidation of collagen","Stimulation of collagen"],"a":0,"e":"Ans. is ''a'' i.e., Degradation of collagen Degradation of collagen and other ECM (extracellular matrix) proteins is achieved by matrix metalloproteinases (MMPs). MMPs is a family of enzymes that have in common a 180-residue zinc protease domain. Matrix metalloproteinases include :- Interstitial collagenase (MMP-1, 2, and 3) : Cleave the fibrillar collagen types I, II and III. Gelatinases (MMP-2 and 9) : Degrade amorphous collagen and fibronectin. Stromelysins (MMP-3, 10 and 11) : Act on proteoglycans, laminin, fibronectin and amorphous collagen. Membrane-bound MMPs (ADAMs) : Cleave membrane-bound precursor forms of TNF and TGF-a, releasing the active molecule.","pyqMatches":[{"year":"2013","no":361,"q":"Action of metalloproteinase ?","o":["Degradation of collagen","Polymerization of collagen","Oxidation of collagen","Stimulation of collagen"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1046, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 165, '{"id":1046,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":165,"q":"Protein catabolism is increased in ?","o":["Starvation","Burns","Surgery","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above Conditions causing increased protein catabolism Multiple trauma Infection and sepsis Burns Fever Surgery Long bone fracture Prolonged starvation Prolonged corticosteroid therapy","pyqMatches":[{"year":"2013","no":362,"q":"Protein catabolism is increased in ?","o":["Starvation","Burns","Surgery","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1047, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 166, '{"id":1047,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":166,"q":"TATA box is seen in ?","o":["Promoter region","Palindromic region","Enhancer region","Silencer region"],"a":0,"e":"Ans. is ''a'' i.e., Promoter region","pyqMatches":[{"year":"2013","no":329,"q":"TATA box is seen in ?","o":["Promoter region","Palindromic region","Enhancer region","Silencer region"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1048, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 167, '{"id":1048,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":167,"q":"Frame shift mutation does not effect complete amino acid sequence if it occurs in multiple of ?","o":["I","2","3","None"],"a":2,"e":"Ans. is ''c'' i.e., 3 Frame-shift mutation Frameshift mutationsQ occur due to insertion or deletionQ of one or two bases which causes change in the reading frame distal to the mutation. If I or 2 base pair change, whole reading frame is changed distal to the mutation, resulting into entirely different protein molecule. If 3 base pairs change, single amino acid is incorporated or deleted. The rest of amino acid sequence is same. This is because the genetic code is read in form of triplets of nucleotides (i.e. codons). If one or two base pairs from the code are removed or inserted, the genetic code will be misread from that change onwards because genetic code is not punctate. Therefore the amino acid sequence translated from the change onwards will be completely changed. However if the removal/insertion happens in multiple of three, rest of the reading from does not change and hence the amino acid sequence will not change.","pyqMatches":[{"year":"2013","no":338,"q":"Frame shift mutation does not effect complete amino acid sequence if it occurs in multiple of ?","o":["I","2","3","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1049, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 168, '{"id":1049,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":168,"q":"Coris disease is due to defect in","o":["Branching enzyme","Debranching enzyme","Myophosphorylase","Hepatic phosphorylase"],"a":1,"e":"Ans. is ''b'' i.e., Debranching enzyme Type Enzyme deficiency Organ (s) affected I von Gierke''s disease Glucose 6- phosphatase Liver, kidney II Pompe''s disease a (1 –44) Glucosidase All organs (acid maltase) III Cori''s disease/Forbe''s disease Debranching enzyme Muscle, liver IV Andersen''s disease Branching enzyme Liver, myocardium V McArdle''s disease Phosphorylase Muscle VI Hers'' disease Phosphorylase Liver VII Tarui''s disease PhosphofructokinaseMuscle, RBCs VIII Phosphorylase kinase Liver There is also on X-linked form of phosphorylase kinase deficiency. This is sole exception as all other glycogen storage diseases are inherited as autosomal recessive trait.","pyqMatches":[{"year":"2013","no":284,"q":"Coris disease is due to defect in","o":["Branching enzyme","Debranching enzyme","Myophosphorylase","Hepatic phosphorylase"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1050, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 169, '{"id":1050,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":169,"q":"Oxidative deamination is catalyzed by ?","o":["Glutaminase","Glutamine synthase","Glutamate dehydrogenase","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., Glutamate dehydrogenase","pyqMatches":[{"year":"2013","no":312,"q":"Oxidative deamination is catalyzed by ?","o":["Glutaminase","Glutamine synthase","Glutamate dehydrogenase","None of the above"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1051, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 170, '{"id":1051,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":170,"q":"Glucose is transported in pancreas through whichreceptor ?","o":["GLUT 1","GLUT 2","GLUT 3","GLUT 4"],"a":1,"e":"Ans. is ''b'' i.e., GLUT 2 Glucose enters the B cells of pancreatic islets via GLUT2 transporter and this stimulate the release of insulin.","pyqMatches":[{"year":"2013","no":286,"q":"Glucose is transported in pancreas through whichreceptor ?","o":["GLUT 1","GLUT 2","GLUT 3","GLUT 4"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1052, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 171, '{"id":1052,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":171,"q":"Immediate source of energy is ?","o":["Cori''s cycle","HMP","ATP","TCA cycle"],"a":2,"e":"Ans. is ''c'' i.e., ATP There are three energy systems to provide energy for muscular activities. Immediate energy system : Energy is provided by stored ATP and creatine phosphate. Anaerobic glycolytic system (lactic acid system) : Energy is generated by utilization of glucose or glycogen by anaerobic glycolysis. This energy is also generated early. Aerobic or oxidative system : Energy is generated by utilization of glucose/glycogen, and fatty acids through oxidative pathways, e.g. TCA cycle. These three energy systems operate as a continuum; each system is always functioning, even at rest. o What varies is the relative contribution each system makes to total ATP production at any given time. Substrates Immediate energy system ATP, creatine phosphate An erobic glycolytic system Glucose or glycogen Oxidative (aerobic) system Glucose or glycogen, fatty acids Energy production Very fast Fast Slow k i Peak at 0-30 sec. 20-180 sec. >3 min Limiting factor Depletion of CrP, ATP Lactic acid as_. vitiation Glycogen depletion Activity example Powerlifting & weight Longer sprints Endurance events lifting, short sprints Middle distance team sports Team sports Jumping, throwing Ball games (Soccer, rugby) Ball games (Soccer, field hockey)","pyqMatches":[{"year":"2013","no":356,"q":"Immediate source of energy is ?","o":["Cori''s cycle","HMP","ATP","TCA cycle"],"a":2,"source":"NEET_2013_Paper.pdf"},{"year":"2015","no":299,"q":"Immediate source of energy is ?","o":["Cori''s cycle","HMP","ATP","TCA cycle"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2013","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1053, 'Biochemistry', 'Vitamins & Minerals', 'Moderate', 'Biochemistry', 172, '{"id":1053,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Moderate","source":"Biochemistry","sourceNo":172,"q":"Which of the following vitamins does not participate in oxidative decarboxylation of pyruvate to acetyl CoA ?","o":["Thiamine","Niacine","Riboflavin","Biotin"],"a":3,"e":"Ans. is `d'' i.e., Biotin","pyqMatches":[{"year":"2012","no":360,"q":"Which of the following vitamins does not participate in oxidative decarboxylation of pyruvate to acetyl CoA ?","o":["Thiamine","Niacine","Riboflavin","Biotin"],"a":3,"source":"NEET_2012_Paper.pdf"},{"year":"2013","no":270,"q":"Which of the following vitamins does not participate in oxidative decarboxylation of pyruvate to acetyl CoA ?","o":["Thiamine","Niacine","Riboflavin","Biotin"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2012","2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1054, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 173, '{"id":1054,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":173,"q":"Salvage pathway of purine nucleotide synthesis are used by all except ?","o":["Brain","Liver","RBC","Leukocytes"],"a":1,"e":"Ans. is ''b'' i.e., Liver Purine nucleotide synthesis occurs by two pathways : De novo synthesis Salvage pathway Liver is the major site of purine nucleotide biosynthesis (de novo). Certain tissues cannot synthesize purine nucleotides by de novo patyway, e g. brain, erythrocytes and polymorphonuclear leukocytes. These are dependent on salvage pathway for synthesis of purine nucleotides by using exogenous purines, which are formed by degradation of purine nucleotides synthesized in liver.","pyqMatches":[{"year":"2013","no":322,"q":"Salvage pathway of purine nucleotide synthesis are used by all except ?","o":["Brain","Liver","RBC","Leukocytes"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1055, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 174, '{"id":1055,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":174,"q":"Carboxypeptidase contains which mineral ?","o":["Copper","Zinc","Iron","None"],"a":1,"e":"Ans. is ''b'' i.e., Zinc Zinc containing enzymes are carboxypeptidase, carbonic anhydrase, alkaline phosphatase, lactate dehydrogenase, alcohol dehydrogenase, glutamate dehydrogenase, RNA polymerase and superoxide dismutase.","pyqMatches":[{"year":"2013","no":246,"q":"Carboxypeptidase contains which mineral ?","o":["Copper","Zinc","Iron","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1056, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 175, '{"id":1056,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":175,"q":"Krabbes disease is due to deficiency of ?","o":["Sphingomyelinase","Beta galactocerebrosidase","Hexosaminidase","Arylsulfatase"],"a":1,"e":"Ans. is ''b'' i.e., Beta galactocerebrosidase","pyqMatches":[{"year":"2013","no":294,"q":"Krabbes disease is due to deficiency of ?","o":["Sphingomyelinase","Beta galactocerebrosidase","Hexosaminidase","Arylsulfatase"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1057, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 176, '{"id":1057,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":176,"q":"True about gluconeogenesis ?","o":["Occurs mainly in muscle","It is reverse of glycolysis","Alanine & lactate both can serve as substrate","Glycerol is not a substrate"],"a":2,"e":"Ans. is ''c'' i.e., Alanine & lactate both can serve as substrate Synthesis of glucose from noncarbohydrate precursors is called gluconeogenesis i.e., synthesis of new glucose. The major noncarbohydrate precursors (substrate) for gluconeogenesis are lactate, pyruvate, glycerol, glucogenic amino acids, propionate and intermediates of the citric acid cycle. All aminoacids, except for leucine and lysine, are substrate for gluconeogenesis. Alanine is the most important gluconeogenic amino acid. Gluconeogenesis occurs mainly in the liver and to a lesser extent in renal cortex. Some gluconeogenesis can also occur in small intestine, but it is not significant. Some of the reactions of gluconeogenesis occurs in the mitochondria but most occur in cytosol. Gluconeogenesis involves glycolysis, the citric acid cycle plus some special reactions. Glycolysis and gluconeogenesis share the same pathway but in opposite direction. Seven reactions of glycolysis are reversible and therefore are used with same enzyme in the synthesis of glucose by gluconeogenesis. However, three of the reactions of glycolysis are irreversible and must be circumvented by four special reactions which are unique to gluconeogenesis and catalyzed by : (1) Pyruvate carboxylase, (ii) Phosphoenolpyruvate carboxykinase, (iii) Fructose-1,6- bisphosphatase, (iv) Glucose-6-phosphatase. These four enzymes are the key enzymes of gluconeogenesis (or gluconeogenesis enzymes). Among these four, pyruvate carboxylase is a mitocondrial enzyme and other three are cytoplasmic enzymes.","pyqMatches":[{"year":"2013","no":272,"q":"True about gluconeogenesis ?","o":["Occurs mainly in muscle","It is reverse of glycolysis","Alanine & lactate both can serve as substrate","Glycerol is not a substrate"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1058, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 177, '{"id":1058,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":177,"q":"Which enzyme polymerises okazaki fragments ?","o":["DNA polymerase I","DNA polymerase II","DNA polymerase III","RNA polymerase"],"a":2,"e":"Ans. is ''c'' i.e., DNA polymerase III Two DNA polymerases act on Okazaki fragments :? DNA polymerase :- Causes polymerization of okazaki fragments, i.e. synthesis of DNA on lagging strand. It also causes synthesis of leading strand. DNA polymerase I :- It fills the gap between okazaki fragments when their polymerization is completed, i.e. when the synthesis on lagging strand is completed, DNA polymerase I fills the gap between fully polymerized okazaki fragments. Thus, DNA polymerase III is involved during ''elongation'' (polymerization of okazaki fragments) and DNA polymerase I is involved during ''termination'' (filling the gaps between okazaki fragments).","pyqMatches":[{"year":"2013","no":331,"q":"Which enzyme polymerises okazaki fragments ?","o":["DNA polymerase I","DNA polymerase II","DNA polymerase III","RNA polymerase"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1059, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 178, '{"id":1059,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":178,"q":"Riboflavin deficiency is assessed by ?","o":["Transketolase","Glutathione reductase","PDH","None"],"a":1,"e":"Ans. is ''b'' i.e., Glutathione reductase Riboflavin (Vitamin B2) Riboflavin is also called Warburg yellow enzyme. Riboflavin provides the reactive moieties of the coenzymes flavin mononucleotide (FMN) and flavin adenine dinucleotide (FAD). Flavin coenzymes are involved in oxidoreduction reactions as electron carriers. These reactions include the mitochondrial respiratory chain, key enzymes in fatty acid and amino acid oxidation and the citric acid cycle. Flavin dependent (flavoprotein) enzymes are : FMN dependent : L-amino acid oxidase, NADH dehydrogenase. FAD dependent : Complex II of respiratory chain, microsomal hydroxylase system, D-amino acid oxidase, xanthine oxidase, succinate dehydrogenase, acyl-CoA dehydrogenase, glycerol-3- phosphate dehydrognenase, pyruvate dehydrognenase, a- ketoglutarate dehydrogenase. Deficiency of riboflavin is charcterized by cheilosis, desquamation and inflammation of tongue, and a seborrheic dermatitis. Riboflavin nutritional status is assessed by measurement of activation ofglutathione reductase by FAD added in vitro.","pyqMatches":[{"year":"2013","no":344,"q":"Riboflavin deficiency is assessed by ?","o":["Transketolase","Glutathione reductase","PDH","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1060, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 179, '{"id":1060,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":179,"q":"Heme is which porphyrin ?","o":["Type I","Type II","Type III","Type IV"],"a":2,"e":"Ans. is ''c'' i.e., Type III","pyqMatches":[{"year":"2013","no":363,"q":"Heme is which porphyrin ?","o":["Type I","Type II","Type III","Type IV"],"a":2,"source":"NEET_2013_Paper.pdf"},{"year":"2016","no":344,"q":"Heme is which porphyrin ?","o":["Type I","Type II","Type III","Type IV"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2013","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1061, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 180, '{"id":1061,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":180,"q":"Which of the following is a lyase ?","o":["Decarboxylase","Synthetase","Kinase","Oxygenase"],"a":0,"e":"Ans. is ''a'' i.e., Decarboxylase Enzyme class Important enzymes OxidoreductaseOxidases, Dehydrogenases, Hydroperoxidases, (catalase, peroxidase), oxygenases Transferase Amino transferase or transaminase, e.g., SGOT (AST) and SGPT (ALT), kinases (Hexokinaseo glucokinase, pyruvate kinase etc), Transketolases, transaldolases, transcarboxylase Hydrolases All digestive enzymes (Pepsin, trypsin, lipases, esterases), lysosomal enzymes, urease, and phosphatase Lyases DecarboxylasesQ, aldolases, hydratases, enolase, fumaraseQ, Arginosuccinase lsomerases Racemases, epimerases, cis- trans- isomerases, mutases Ligases SynthatasesQ, Carboxylases, DNA ligase","pyqMatches":[{"year":"2013","no":250,"q":"Which of the following is a lyase ?","o":["Decarboxylase","Synthetase","Kinase","Oxygenase"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1062, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 181, '{"id":1062,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":181,"q":"Not present in DNA ?","o":["Uracil","Thymine","Cytosine","Adenine"],"a":0,"e":"Ans. is ''a'' i.e., Uracil Two types of bases are found in nucleotides : (i) purines and (ii) pyrimidines.","pyqMatches":[{"year":"2013","no":326,"q":"Not present in DNA ?","o":["Uracil","Thymine","Cytosine","Adenine"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1063, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 182, '{"id":1063,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":182,"q":"Neutral amino acid is ?","o":["Aspartate","Arginine","Glycine","Histidine"],"a":2,"e":"Ans. is ''c'' i.e., Glycine Neutral amino acids Alanine Asparging Cysteine Glycine Glutamine Isoleucine Leucine Methionine Proline Phenylalanine Serine Threonine Tyrosine Tryptophan Valine","pyqMatches":[{"year":"2013","no":305,"q":"Neutral amino acid is ?","o":["Aspartate","Arginine","Glycine","Histidine"],"a":2,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":332,"q":"Neutral amino acid is ?","o":["Aspartate","Arginine","Glycine","Histidine"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1064, 'Biochemistry', 'Enzymes', 'Moderate', 'Biochemistry', 183, '{"id":1064,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Moderate","source":"Biochemistry","sourceNo":183,"q":"All are true about ketone bodies except ?","o":["Acetoacetate is primary ketone body","Synthesized in mitochondria","Synthesized in liver","HMG CoA reductase is the rate-limiting enzyme"],"a":3,"e":"Ans. is ''d'' i.e., HMG CoA reductase is the rate-limiting enzyme","pyqMatches":[{"year":"2013","no":290,"q":"All are true about ketone bodies except ?","o":["Acetoacetate is primary ketone body","Synthesized in mitochondria","Synthesized in liver","HMG CoA reductase is the rate-limiting enzyme"],"a":3,"source":"NEET_2013_Paper.pdf"},{"year":"2016","no":276,"q":"All are true about ketone bodies except ?","o":["Acetoacetate is primary ketone body","Synthesized in mitochondria","Synthesized in liver","HMG CoA reductase is the rate-limiting enzyme"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2013","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1065, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 184, '{"id":1065,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":184,"q":"The mineral having action like vitamin E ?","o":["Calcium","Iron","Selenium","Magnesium"],"a":2,"e":"Ans. is ''c'' i.e., Selenium Selenium functions as an antioxidant along with vitamin E. Selenium is a constituent of glutathione peroxidase, an antioxidant enzyme which prevents against oxidative damage. Selenium also is a constituent of iodothyronine deiodinase, the enzyme that converts thyroxine triiodothyronine.","pyqMatches":[{"year":"2013","no":350,"q":"The mineral having action like vitamin E ?","o":["Calcium","Iron","Selenium","Magnesium"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1066, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 185, '{"id":1066,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":185,"q":"Which is an abnormal lipoprotein ?","o":["VLDL","Chylomicron","Lp (a)","LDL"],"a":2,"e":"Ans. is ''c'' i.e., Lp (a) Some people have a special type of abnormal LDL called lipoprotein (a) or Lp (a), containing an additional protein, apoprotein-a. Elevated LPa levels are associated with an increased risk of CHD.","pyqMatches":[{"year":"2013","no":295,"q":"Which is an abnormal lipoprotein ?","o":["VLDL","Chylomicron","Lp (a)","LDL"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1067, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 186, '{"id":1067,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":186,"q":"Okazaki fragments are formed during ?","o":["Transcription","Translation","DNA replication","None"],"a":2,"e":"Ans. is ''c'' i.e., DNA replication","pyqMatches":[{"year":"2013","no":330,"q":"Okazaki fragments are formed during ?","o":["Transcription","Translation","DNA replication","None"],"a":2,"source":"NEET_2013_Paper.pdf"},{"year":"2016","no":329,"q":"Okazaki fragments are formed during ?","o":["Transcription","Translation","DNA replication","None"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2013","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1068, 'Biochemistry', 'Clinical Biochemistry', 'Easy', 'Biochemistry', 187, '{"id":1068,"subject":"Biochemistry","chapter":"Clinical Biochemistry","difficulty":"Easy","source":"Biochemistry","sourceNo":187,"q":"Hay''s sulpher test is used to detect which of the following ?","o":["Bile salts in urine","Reducing sugar in urine","Ketone bodies in urine","Urobilinogen in urine"],"a":0,"e":"Ans. is ''a'' i.e., Bile salts in urine Tests Used for Rothera''s test (nitroprusside test) Ketone bodies in urine :- acetone and acetocetate Gerhardt''s test (ferric chloride test) Ketone bodies in urine :- acetoacetate. Benedict''s test Reducing sugars in urine Fehling''s test Reducing sugars in urine Hay''s sulpher test Bile salts in urine Fouchet''s (borium sulphate test) Bile pigment : bilirubin Gmelin''s (nitric acid) test Bile pigment : bilirubin Vanden Bergh test Bile pigment : bilirubin Ehrlich''s test Bilinogens (stercobilinogen, urobilinogen) Schlesinger''s test Bilins (stercobilin, urobilin). Ehrlich''s aldehyde test Porphobilinogen and urobilinogen in urine","pyqMatches":[{"year":"2013","no":365,"q":"Hay''s sulpher test is used to detect which of the following ?","o":["Bile salts in urine","Reducing sugar in urine","Ketone bodies in urine","Urobilinogen in urine"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1069, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 188, '{"id":1069,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":188,"q":"Which of the following accumulates in maple syrup urine disease","o":["Leucine","Valine","Isoleucine","All"],"a":3,"e":"Ans. is `d'' i.e., All Maple syrup urine disease (MSUD) or branched-chain ketoaciduria * It is an inborn error of metabolism of branched-chain amino acids valine, leucine and isoleucine. * It is due to deficiency of an enzyme that catalyzes the second reaction in these amino acids metabolism i.e. branched chain-a keto acid dehydrogenase which catalyzes the decarboxylation of branched-chain amino acids. * As a result, the branched-chain amino acids, leucine, isoleucine and valine, and their a-keto acids accumulate in the blood, urine, and CSF. * There is a characteristic maple syrup odour to the urine. * In maple syrup urine disease there is the excretion of branched- chain amino acids (isoleucine, leucine, valine) and their keto acids (α-keto β-methyl valerate, α-ketoisocaproate, α-ketoisovalerate) in the urine.","pyqMatches":[{"year":"2013","no":316,"q":"Which of the following accumulates in maple syrup urine disease","o":["Leucine","Valine","Isoleucine","All"],"a":3,"source":"NEET_2013_Paper.pdf"},{"year":"2016","no":350,"q":"Which of the following accumulates in maple syrup urine disease","o":["Leucine","Valine","Isoleucine","All"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2013","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1070, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 189, '{"id":1070,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":189,"q":"Keratin is a ?","o":["Globular protein","Cylindrical protein","Fibrous protein","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., Fibrous protein Based on their three-dimensional shape (i.e., conformation), the proteins are divided into two classes :","pyqMatches":[{"year":"2013","no":317,"q":"Keratin is a ?","o":["Globular protein","Cylindrical protein","Fibrous protein","None of the above"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1071, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 190, '{"id":1071,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":190,"q":"Keratin contains ?","o":["Arginine","Histidine","Lysine","All"],"a":3,"e":"Ans. is ''d'' i.e., All Amino acids required for specialized products Creatine → Glycine + Arginine + Methionine Glutathione → Glycine + Cysteine + Glutamate Cystine → Cysteine + Cysteine Purine → Glycine + Aspartate + Glutamate + Serine Pyrinidine → Asparatate + Glutamine Carnosine → 13-Alanine + histidine Choline → Formed with the help of methionine, glycine, serine, B6 Nitric oxide → Arginine Heme → Glycinc, Succinyl CoA Carnitine → Methionine + lysine Keratin → Histidine; arginine; lysine (1 : 12 : 4) Glutamate → Gamma-amino butyric acid (GABA)","pyqMatches":[{"year":"2013","no":318,"q":"Keratin contains ?","o":["Arginine","Histidine","Lysine","All"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1072, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 191, '{"id":1072,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":191,"q":"Which of the following is high energy compound?","o":["ADP","Glucose-6-phosphate","Creatine phosphate","Fructose-6-phosphate"],"a":2,"e":"Ans. is ''c'' i.e., Creatine phosphate High energy compounds The energy released during oxidation of monosaccharides, fatty acids and amino acids may not be required immediately. Therefore, there must be some way of storing energy. The energy released during catabolism is captured in the form of a group of compounds known as \"high-energy phosphates\". The most important member of this groupis ATP. A compound that liberates 7 Kcal/mol or more on hydrolysis is called high energy compound, or a compound that on hydrolysis undergoes a large ( 7 kcal/mol) decrease in free energy (AG) under standard condition is called high energy compound, i.e., AG ?- 7 Kcal/mol. For example, ATP liberates 7.3 Kcal/mol on hydrolysis. High energy compounds are : ? Phosphate compounds : Nucleotides (ATP Q,GTP, UTP, UDP- glucose), Creatinine phosphate, arginine phosphate, 1,3- bisphosphoglycerate, Phosphoenol pyruvate, inorganic pyrophosphate, Carbamoyl phosphatee,amino acyl adenylate (amino acyl AMP). Sulfur compounds : - CoA derivatives (acetyl CoAe, Succinyl CoA, fatty acyl CoA, HMG CoA), S-adenosyl methionine (SAM), adenosine phosphosulfate. A compound which liberates < 7 Kcal/mol on hydrolysis is called low energy compound, i.e., a decrease in free energy is < 7 Kcal/mol, i.e., AG < -7 Kcal/mol. Low energy compounds are glucose- 1- phosphate, fructose-6​phosphate, glucose-6-phosphate, glycerol-3- phosphate, AMP, ADPQ.","pyqMatches":[{"year":"2013","no":256,"q":"Which of the following is high energy compound?","o":["ADP","Glucose-6-phosphate","Creatine phosphate","Fructose-6-phosphate"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1073, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 192, '{"id":1073,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":192,"q":"True statement about hemoglobin is ?","o":["Each hemoglobin molecule is made of 4 polypep tides of each subunit","Two alpha and two beta subunits having a 02 attached to each subunit","Each hemoglobin molecule binds to only one 02 molecule","Each hemoglobin has one heme molecule"],"a":0,"e":"Ans. is ''a'' i.e., Each hemoglobin molecule is made of 4 polypeptides of each subunit","pyqMatches":[{"year":"2013","no":366,"q":"True statement about hemoglobin is ?","o":["Each hemoglobin molecule is made of 4 polypep tides of each subunit","Two alpha and two beta subunits having a 02 attached to each subunit","Each hemoglobin molecule binds to only one 02 molecule","Each hemoglobin has one heme molecule"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1074, 'Biochemistry', 'Lipid Metabolism', 'Moderate', 'Biochemistry', 193, '{"id":1074,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":193,"q":"All are true about LDL except ?","o":["More dense than chylomicron","Smaller than VLDL","Transports maximum amount of lipid","Contains maximum cholesterol"],"a":2,"e":"Ans. is ''c'' i.e., Transports maximum amount of lipid","pyqMatches":[{"year":"2013","no":296,"q":"All are true about LDL except ?","o":["More dense than chylomicron","Smaller than VLDL","Transports maximum amount of lipid","Contains maximum cholesterol"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1075, 'Biochemistry', 'Carbohydrate Metabolism', 'Moderate', 'Biochemistry', 194, '{"id":1075,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":194,"q":"Gluconeogenesis from lactate needs all except ?","o":["Transport of lactate from muscle to liver","Conversion of lactate to pyruvate","Transamination of pyruvate to alanine","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., Transamination of pyruvate to alanine","pyqMatches":[{"year":"2013","no":273,"q":"Gluconeogenesis from lactate needs all except ?","o":["Transport of lactate from muscle to liver","Conversion of lactate to pyruvate","Transamination of pyruvate to alanine","None of the above"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1076, 'Biochemistry', 'Vitamins & Minerals', 'Moderate', 'Biochemistry', 195, '{"id":1076,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Moderate","source":"Biochemistry","sourceNo":195,"q":"All are true about Vitamin B12,except ?","o":["Active form is methylcobalamine","Requires for conversion of homocysteine to methionine","Requires in metabolism of methylmalonyl CoA","Requires for conversion of pyruvate to lactate"],"a":3,"e":"Ans. is''d'' i.e., Requires for conversion of pyruvate to lactate","pyqMatches":[{"year":"2013","no":258,"q":"All are true about Vitamin B12,except ?","o":["Active form is methylcobalamine","Requires for conversion of homocysteine to methionine","Requires in metabolism of methylmalonyl CoA","Requires for conversion of pyruvate to lactate"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1077, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 196, '{"id":1077,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":196,"q":"Polar amino acids are all except ?","o":["Glutamic acid","Histidine","Glutamine","Methionine"],"a":3,"e":"Ans. is ''d'' i.e., Methionine","pyqMatches":[{"year":"2013","no":306,"q":"Polar amino acids are all except ?","o":["Glutamic acid","Histidine","Glutamine","Methionine"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1078, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 197, '{"id":1078,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":197,"q":"Major form of folic acid to transfer one carbon is ?","o":["Methylene THF","Formyl THF","Methyl THF","All"],"a":0,"e":"Ans. is ''a'' i.e., Methylene THF Folic acid The active form of folic acid (pteroyl glutamate) is tetrahydrofolate (THF). THF serves as a carrier of one-carbon (C1) unit0 during several biosynthetic reactions like nucleic acidQ and amino acid metabolism. Two other cofactors are also known to be involved in the addition of one carbon (C1) unit to a metabolic precursor, biotin in carboxylation reaction and S-adenosylmethionine (SAM) as methylating agent. However, folic acid is more versatile than either of these two because it can transfer the C, units in several oxidation states. THF acts as a carrier of one carbon unit0. The one carbon units can be : Methyl (C.113), methylene (CH2), methenyl (CH), formyl (CHO), orformimino (CH =NH). One carbon unit binds to THF through N5 or N1° or both N5, N''° position. For example, if formyl unit is attached to N-5, it is cal led N5-formyl THF; if methylene unit is attached to both N5 and 1\\l''°, it is called N5, N''° methylene THF. Carbon units attached to N5 are formyl, formimino, or methyl; attached to N''° is formyl; and attached to both N5-N10 are methylene or methenyl. So, various possible THF are : - N5-Formyl THF, N5-formimino THF, N5-methyl THF, N1°-formyl THF, N5-N10​methylene THF and N5-N''°- methenyl THF. THF receives the C, units from various donor molecules during catabolic reactions and can transfers them to specific acceptors for the synthesis of various compounds. The major point of entry for one-carbon unit into substituted folates is methylene THF, which is formed by the reaction of glycine, serine and choline. Serine is the most important source of substituted folates for biosynthetic reactions, and activity of serine hydroxymethyltransferase is regulated by the state of folate substitution and availability of folate.","pyqMatches":[{"year":"2013","no":343,"q":"Major form of folic acid to transfer one carbon is ?","o":["Methylene THF","Formyl THF","Methyl THF","All"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1079, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 198, '{"id":1079,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":198,"q":"During starvation, muscle uses ?","o":["Fatty acids","Ketone bodies","Glucose","Proteins"],"a":0,"e":"Ans. is ''a'' i.e., Fatty acids","pyqMatches":[{"year":"2013","no":358,"q":"During starvation, muscle uses ?","o":["Fatty acids","Ketone bodies","Glucose","Proteins"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1080, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 199, '{"id":1080,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":199,"q":"Serotonin is derived from -","o":["Tyrosine","Tryptophan","Phenylalanine","Methionine"],"a":1,"e":"Ans. is ''b'' i.e., Tryptophan [Ref Harper 29''/e p. 300] Tryptophan is a precursor for synthesis of niacin (nicotinic acid), serotonin and melatonin.","pyqMatches":[],"pyqYears":[]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1081, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 200, '{"id":1081,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":200,"q":"Major apolipoprotein of chylomicrons ?","o":["B-100","D","B-48","None"],"a":2,"e":"Ans. is ''c'' i.e., B-48","pyqMatches":[{"year":"2013","no":297,"q":"Major apolipoprotein of chylomicrons ?","o":["B-100","D","B-48","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1082, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 201, '{"id":1082,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":201,"q":"True about Glutathione except ?","o":["Tripeptide","Formed from glutamic acid, glycine, cysteine","Act as antioxidant in reduced state","All of the above"],"a":3,"e":"Ans. is `d'' i.e., All of the above Glutathione Glutathione is a tripeptide of glutamie acid, cysteine, and glycine. The molecule has a sulfhydryl (-SH) or thiol group on the cysteine, which accounts for its strong electron-donating character. It exists in two forms : reduced glutathione or GSH. In the reduced state, the thiol group of cysteine is able to donate a reducing equivalent (H+ e-) to other unstable molecules, such as reactive oxygen species. In donating an electron, glutathione itself becomes reactive, but readily reacts with another reactive glutathione to form glutathione disulfide (GSSG) or oxidized glutathione. GSH can be regenerated from GSSG by the enzyme glutathione reductase. While all cells in the human body are capable of synthesizing glutathione, liver glutathione synthesis has been shown to be essential. The liver is the largest GSH reservoir. Because of its reducing property, reduced glutathione has potent antioxidant action. Functions : GSH is an extremely important cell protectant. It directly reduces reactive hydroxyl free radicals, other oxygen centered free radicals, and radical centers on DNA and other biomolecules. GSH is the essential cofactor for many enzymes which require thiol- reducing equivalents, and helps keep redox-sensitive active sites on enzymes in the necessary reduced state. GSH is used as a cofactor by ? Multiple peroxidase enzymes, to detoxify peroxides generated from oxygen radical attack on biological molecules; Transhydrogenases, to reduce oxidized centers on DNA, proteins, and other biomolecules; and Glutathione S-transferases (GST) to conjugate GSH with endogenous substances (e.g., estrogens) and to exogenous electrophiles (e.g., arene oxides, unsaturated carbonyls, organic halides), and diverse xenobiotics. GSH is a primary protectant of skin, lens, cornea, and retina against radiation damage, and the biochemical foundation of P450 detoxication in the liver, kidneys, lungs, intestinal epithelia, and other organs. GSH acts as a carrier in transport of certain amino acids across membranes in the kidney. Glutathione (GSH) participates in leukotriene synthesis.","pyqMatches":[{"year":"2013","no":319,"q":"True about Glutathione except ?","o":["Tripeptide","Formed from glutamic acid, glycine, cysteine","Act as antioxidant in reduced state","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1083, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 202, '{"id":1083,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":202,"q":"Concentration of which is inversely related to the risk of coronary heart disease ?","o":["VLDL","LDL","HDL","None"],"a":2,"e":"Ans. is ''c'' i.e., HDL The level of HDL in serum is inversely related to the incidence of MI. As it is \"antiatherogenic\" or \"protective\" in nature, HDL is known as \"good cholesterol\". HDL has its beneficial effect by reverse cholesterol transport.","pyqMatches":[{"year":"2013","no":298,"q":"Concentration of which is inversely related to the risk of coronary heart disease ?","o":["VLDL","LDL","HDL","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1084, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 203, '{"id":1084,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":203,"q":"Maximum cholesterol is seen in ?","o":["VLDL","LDL","HDL","Chylomicrons"],"a":1,"e":"Ans. is ''b'' i.e., LDL Maximum triglyceride content → Chylomicrons Maximum exogenous triglyceride → Chylomicrons Maximum endogenous triglyceride → VLDL Maximum cholesterol content → LDL","pyqMatches":[{"year":"2013","no":299,"q":"Maximum cholesterol is seen in ?","o":["VLDL","LDL","HDL","Chylomicrons"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1085, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 204, '{"id":1085,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":204,"q":"In humans, end product of purine metabolism","o":["Allantoin","Uric acid","CO2","None"],"a":1,"e":"Ans. is ''b'' i.e., Uric acid","pyqMatches":[{"year":"2013","no":323,"q":"In humans, end product of purine metabolism","o":["Allantoin","Uric acid","CO2","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1086, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 205, '{"id":1086,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":205,"q":"All are true about chaperones except ?","o":["Cause folding of proteins","Are lipid in nature","May have ATPase activity","Include heat shock proteins"],"a":1,"e":"Ans. is ''b'' i.e., Are lipid in nature Chaperones are proteins (not lipid). Chaperones Certain proteins play a role in the assembly or proper folding of other proteins without themselves being components of the latter. Such proteins are called molecular chaperones. Most chaperones exhibit ATPase activity and bind ADP and ATP. This activity is important for their effect on folding. Some Properties of Chaperone Proteins Present in a wide range of species from bacteria to humans Many are so-called heat shock proteins (Hsp) Some are inducible by conditions that cause unfolding of newly synthesized proteins (eg, elevated temperature and various chemicals) They blind to predominantly hydrophobic regions of infolded proteins and prevent their aggregation They act in part as a quality control or editing mechanism for detecting misfolded or otherwise defective proteins Most chapersones show associated ATPase activity, with ATP or ADP being involved in the protein-chaperone interaction Found in various cellular compartments such as cytosol, mitochondria, and the lumen of the endoplasmic reticulum","pyqMatches":[{"year":"2013","no":367,"q":"All are true about chaperones except ?","o":["Cause folding of proteins","Are lipid in nature","May have ATPase activity","Include heat shock proteins"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1087, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 206, '{"id":1087,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":206,"q":"Which Vitamin is involved in Redox reactions","o":["Pyridoxin","Biotin","Folic acid","Riboflavin"],"a":3,"e":"Ans. is ''d'' i.e., Riboflavin Riboflavin and niacin are involved in redox (reduction and oxidation) reactions.","pyqMatches":[{"year":"2013","no":354,"q":"Which Vitamin is involved in Redox reactions","o":["Pyridoxin","Biotin","Folic acid","Riboflavin"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1088, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 207, '{"id":1088,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":207,"q":"Ninhydrin test is used for ?","o":["Bile salts","Amino acids","Nucleic acid","Lipids"],"a":1,"e":"Ans. is ''b'' i.e., Amino acids Important chemical reactions of amino acids Following are some important chemical reactions. A. Reaction used to determine amino acid sequence in polypeptide chain : - Generally, amino terminal (N-terminal) of amino acid is tagged with some reagent. It is split off by hydrolysis and tagged amino acid is identified. The reaction is, then, repeated with new N- terminal of subsequent amino acid and so on. The two reactions are used for identification of amino acid sequence : ? Sanger''s reaction : - Uses Sanger''s reagent ( 1 -fluoro-2,4- dinitrobenzene) to tag amino terminal. Edman''s reaction : - Uses Edman''s reagent (phenylisothiocyanate) to tag amino terminal. B. Reaction used to identification of individual or group of amino acids : - These reactions are frequently used for qualitative detection and quantitative measurement of various amino acids. Ninhydrin tese : - All a-amino acids. Xanthophoretic reaction : - Aromatic amino acidse (Tyrosine, tryptophan, phenylalanine). Millan''s teste (Millon-Nasse reaction) : - Tyrosine° (phenol group of tyrosine). Therefore millon''s test is positive in tyrosinosis°. Aldehyde test : - Tryptophan (indole ring) Hopkins-tole reaction : - Tryptophan (indole ring) Sakaguch''s reaction : - Arginine (guanidinium group of arginine). Sulphur test : - Cysteine (sulphydryl group) Nitroprusside test : - Cysteine (sulphydryl group) Pauly''s test : - Histidine (imidazole group) Biuret reaction : - Peptide bond Diazo reaction Q (Pauli''s) : - Histidine or tyrosine.","pyqMatches":[{"year":"2013","no":311,"q":"Ninhydrin test is used for ?","o":["Bile salts","Amino acids","Nucleic acid","Lipids"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1089, 'Biochemistry', 'Miscellaneous', 'Moderate', 'Biochemistry', 208, '{"id":1089,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Biochemistry","sourceNo":208,"q":"Which is not a dietary fiber ?","o":["Lignin","Lactulose","Pectin","Cellulose"],"a":1,"e":"Ans. is ''b'' i.e., Lactulose Dietary fibres (Review) Dietary fibre consists of unabsorbable cell wall and other consititutents of vegetable food like celluloseQ, lignin, hemicellulosee, gums, pectins°, aliginates and other polysaccharides. In herbivorous animals, intestinal microoganism breakdown these polysaccharides into acetate, propionate and butyrate. These polysaccharides contain 13-glycosidic linkages. Therefore, they cannot be digested by a-amylase present in human saliva and pancreatic juice because a-amylase breaks a-glycosidic bond (especially 1-4 a linkage). So, dietary fibers are not digested or hydrolyzed but are fermented by colonic bacteria except for lignin, which is neither digested nor fermented by intestinal microorganisms°. Dietary fibre absorbes water in the intestine, swells, increase bulk of stool by increasing water content of faeces and soften it, decreases transit time by facilitating colonic tansit. \"The presence of fibre shortens the transit timese and increases the stool bulk\". Dietary fibre is of two types : -","pyqMatches":[{"year":"2013","no":355,"q":"Which is not a dietary fiber ?","o":["Lignin","Lactulose","Pectin","Cellulose"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1090, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 209, '{"id":1090,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":209,"q":"ATP is generated in ETC by ?","o":["Na'' ATPase","Cl- ATPase","FoF, ATPase","ADP Kinase"],"a":2,"e":"Ans. is `c'' i.e., FoFi ATPase","pyqMatches":[{"year":"2013","no":259,"q":"ATP is generated in ETC by ?","o":["Na'' ATPase","Cl- ATPase","FoF, ATPase","ADP Kinase"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1091, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 210, '{"id":1091,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":210,"q":"Atractiloside act as ?","o":["Uncoupler","Inhibitor of oxidative phosphorylation","Inhibitor of complex I of ETC","Inhibitor of complex III of ETC"],"a":1,"e":"Ans. is ''b'' i.e., Inhibitor of oxidative phosphorylation Inhibitors of electron transport chain? Inhibitors of respiratory chain may be divided into three groups : ?","pyqMatches":[{"year":"2013","no":260,"q":"Atractiloside act as ?","o":["Uncoupler","Inhibitor of oxidative phosphorylation","Inhibitor of complex I of ETC","Inhibitor of complex III of ETC"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2016","no":244,"q":"Atractiloside act as ?","o":["Uncoupler","Inhibitor of oxidative phosphorylation","Inhibitor of complex I of ETC","Inhibitor of complex III of ETC"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2013","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1092, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 211, '{"id":1092,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":211,"q":"Riboflavin is a constituent of ?","o":["FMN","NAD","PLP","THF"],"a":0,"e":"Ans. is ''a'' i.e., FMN Riboflavin is also called Warburg yellow enzyme. Riboflavin provides the reactive moieties of the coenzymes flavin mononucleotide (FMN) and flavin adenine dinucleotide (FAD). Flavin coenzymes are involved in oxidoreduction reactions as electron carriers. These reactions include the mitochondrial respiratory chain, key enzymes in fatty acid and amino acid oxidation and the citric acid cycle.","pyqMatches":[{"year":"2013","no":345,"q":"Riboflavin is a constituent of ?","o":["FMN","NAD","PLP","THF"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1093, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 212, '{"id":1093,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":212,"q":"Rate limiting step in pyrimidine synthesis ?","o":["Dihydro-orotase","Ornithine transcarbomoylase","Aspartate transcarbomoylase","Carbamoyl phosphate synthase-I"],"a":2,"e":"Ans. is ''c'' i.e., Aspartate transcarbomoylase","pyqMatches":[{"year":"2013","no":324,"q":"Rate limiting step in pyrimidine synthesis ?","o":["Dihydro-orotase","Ornithine transcarbomoylase","Aspartate transcarbomoylase","Carbamoyl phosphate synthase-I"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1094, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 213, '{"id":1094,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":213,"q":"All are characteristics of genetic code ?","o":["Overlapping","Nonambiguous","Universal","Degeneracy"],"a":0,"e":"Ans. is ''a'' i.e., Overlapping Characteristic of genetic codes Genetic codes have following characteristics ?","pyqMatches":[{"year":"2013","no":336,"q":"All are characteristics of genetic code ?","o":["Overlapping","Nonambiguous","Universal","Degeneracy"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1095, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 214, '{"id":1095,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":214,"q":"Which of the following is an example of Trinucleotide repeat mutation ?","o":["Huntington''s chorea","Fragile-X-syndrome","Friedreich ataxia","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above Trinucleotide repeat mutation In this type of mutation a codon (i.e. trinucleotide sequence) undergoes amplification and the same codon is repeated continuously so many times in the chain. Diseases associated with trinucleotide repeat mutation are Huntington''s disease (CAG repeat), Spinocerebellar ataxia (CAG repeat), friedreich ataxia (GAA repeat), fragile-X-syndrome (GGG or GCC repeat), dystrophia myotonica (CTG/CUG repeat), X-linked spinobulbar muscular atrophy (CAG repeat) and dentorubral pallidolusian atrophy (CAG repeat).","pyqMatches":[{"year":"2013","no":337,"q":"Which of the following is an example of Trinucleotide repeat mutation ?","o":["Huntington''s chorea","Fragile-X-syndrome","Friedreich ataxia","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1096, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 215, '{"id":1096,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":215,"q":"Which of the following is the major proteoglycan of synovial fluid ?","o":["Chondroitin sulfate","Dermatan sulfate","Heparan sulfate","Hyaluronic acid"],"a":3,"e":"Ans. is ''d'' i.e., Hyaluronic acid Distribution Hyaluronic acid Synovial fluid (provides viscosity), vitreous humor, loose connective tissue) Chondroitin sulfate Cartilage, bone, tendon, ligament, cornea Dermatan sulfate Pliability of skin, and heart valves, wide distribution Keratan sulfate Horny structures like hair, nails, claws, horn, hoofs Also present in cornea Heparin Heparan Mast cells sulfate Skin fibroblast, aortic wall","pyqMatches":[{"year":"2013","no":368,"q":"Which of the following is the major proteoglycan of synovial fluid ?","o":["Chondroitin sulfate","Dermatan sulfate","Heparan sulfate","Hyaluronic acid"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1097, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 216, '{"id":1097,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":216,"q":"The main function of Vitamin C in the body is","o":["Coenzyme for energy metabolism","Regulation of lipid synthesis","Involvement as antioxidant","Inhibition of cell growth"],"a":2,"e":"Ans. is ''c'' i.e., Involvement as antioxidant Vitamin C (Ascorbic acid) Ascorbic acid (Vitamin C) is also called antiscorbutic factor. It is very heat labile, especially in basic medium. Ascorbic acid itself is an active form. Maximum amount of vitamin C is found in adrenal cortex. Ascorbic acid functions as a reducing agent and scavanger of free radicals (antioxidant). Its major functions are:- In collagen synthesis : - Vitamin C is required for post-translational modification by hydroxylation of proline and lysine residues converting them into hydroxyproline and hydroxylysine. Thus vitamin C is essential for the conversion of procollagen to collagen, which is rich in hydroxyproline and hydroxylysine. Through collagen synthesis, it plays a role in formation of matrix of bone, cartilage, dentine and connective tissue.","pyqMatches":[{"year":"2013","no":346,"q":"The main function of Vitamin C in the body is","o":["Coenzyme for energy metabolism","Regulation of lipid synthesis","Involvement as antioxidant","Inhibition of cell growth"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1098, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 217, '{"id":1098,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":217,"q":"Enzyme specificity is given by ?","o":["Km","Vrm„","Both","None"],"a":0,"e":"Ans. is ''a'' i.e., Km. The Km of an enzyme is the concentration of the substrate that enables the enzyme to function at half maximum activity and is therefore a measure of the specificity of a substrate.for the enzyme\" Clinical biochemistry Actually enzyme specificity is not measured by Km alone. It is measured by the ratio Kcat/Km which is a second order rate constant for the reaction between substrate and free enzyme. This ratio is important, for it provides a direct measure of enzyme efficiency and specificity. Note : Kcat is turnover number and measures the rate of the catalytic process.","pyqMatches":[{"year":"2013","no":247,"q":"Enzyme specificity is given by ?","o":["Km","Vrm„","Both","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1099, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 218, '{"id":1099,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":218,"q":"Natural uncoupler is ?","o":["Thermogonin","2, 4 nitrophenol","2, 4 Dinitrophenol","Oligomycin"],"a":0,"e":"Ans. is ''a'' i.e., Thermogenin Amongst the given options, a, b and c are uncouplers. However, only thermogenin, among these three is a natural (physiological) uncoupler. Uncouples As the name suggests, these componds block the coupeling of oxidation with phosphorylation. These compounds allow the transfer of reducing equivalents in respiratory chain but prevent the phosphorylation of ADP to ATP° by uncoupling the linkage between ETC and phosphorylation. Thus the energy instead of being trapped by phosphorylation is dissipated as heat. Uncouplers may be :- Natural :- Thermogenin, thyroxine Synthetic :- 2, 4-dinitrophenol (2, 4-DNP), 2, 4-dinitrocresol (2, 4- DNC), and CCCP (chlorocarbonylcyanidephenyl hydrazone).","pyqMatches":[{"year":"2013","no":261,"q":"Natural uncoupler is ?","o":["Thermogonin","2, 4 nitrophenol","2, 4 Dinitrophenol","Oligomycin"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1100, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 219, '{"id":1100,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":219,"q":"Lipid with highest mobility is ?","o":["HDL","LDL","VLDL","Chylomicrons"],"a":0,"e":"Ans. is `a'' i.e., HDL HDL :- Has maximum electrophoretic mobility, has maximum density, has minimum lipid content, has maximum protein (apoprotein) content, are smallest in size, has maximum phospholipid, has minimum triglycerides. Chylomicrons :- Have no electrophoretic mobility, have minimum density, have maximum lipid content, have minimum protein content, are largest in size, have minimum phospholipids, have maximum triglycerides.","pyqMatches":[{"year":"2013","no":300,"q":"Lipid with highest mobility is ?","o":["HDL","LDL","VLDL","Chylomicrons"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1101, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 220, '{"id":1101,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":220,"q":"Apolipoprotein E is rich in ?","o":["Lysine","Arginine","Histidine","Methionine"],"a":1,"e":"Ans. is ''b'' i.e., Arginine Arginine rich apo-E is isolated from VLDL. It contains arginine to the extent of 10 per cent of the total amino acids and accounts for 5 to 10 per cent of total VLDL apoproteins in normal subjects.","pyqMatches":[{"year":"2013","no":301,"q":"Apolipoprotein E is rich in ?","o":["Lysine","Arginine","Histidine","Methionine"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1102, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 221, '{"id":1102,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":221,"q":"Which energy molecule gives 10.5 kcal/ molecule?","o":["ATP","GTP","Creatine phosphate","Glucose-6-phosphate"],"a":2,"e":"Ans. is ''c'' i.e., Creatine phosphate A compound that liberates 7 Kcal/mol or more on hydrolysis is called high energy compound, or a compound that on hydrolysis undergoes a large ( 7 kcal/mol) decrease in free energy (AG) under standard condition is called high energy compound, i.e., AG 7 Kcal/mol. For example, ATP liberates 7.3 Kcal/mol on hydrolysis Metabolite A G Liberated energy in Kcallmole Phosphoenol pyruvate -14.8 14.8 Carbamoyl phosphate -12.3 12.3 1, 3-Bisphosphoglycerate-11-811.8 Acid phosphate -112 112 Creatine phosphate -10.3 10.3 Arginine phosphate -7.6 7.6 ATP to ADP + Pi -7.3 7.3 ATP to AMP + PPi -7-7 7.7 Glucose-1 -phosphate -5.0 5.0 Glucose-6-phosphate -3.3 3.3 Glycerol-l-phosphate -2.2 2.2","pyqMatches":[{"year":"2013","no":257,"q":"Which energy molecule gives 10.5 kcal/ molecule?","o":["ATP","GTP","Creatine phosphate","Glucose-6-phosphate"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1103, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 222, '{"id":1103,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":222,"q":"Branching enzyme is found in ?","o":["Glycogenesis","Glucogenesis","Glycogenolysis","Glycolysis"],"a":0,"e":"Ans. is ''a'' i.e., Glycogenesis","pyqMatches":[{"year":"2013","no":281,"q":"Branching enzyme is found in ?","o":["Glycogenesis","Glucogenesis","Glycogenolysis","Glycolysis"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1104, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 223, '{"id":1104,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":223,"q":"Which of the following is not a phospholipid ?","o":["Lecithine","Plasmalogen","Cardiolipin","Ganglioside"],"a":3,"e":"Ans. is ''d'' i.e., Ganglioside Phospholipids are :","pyqMatches":[{"year":"2013","no":289,"q":"Which of the following is not a phospholipid ?","o":["Lecithine","Plasmalogen","Cardiolipin","Ganglioside"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1105, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 224, '{"id":1105,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":224,"q":"The mechanism by which mercury causes damage ?","o":["Binds to -SH group of enzyme","Directly toxic","Inhibits ETC","Inhibits protein synthesis"],"a":0,"e":"Ans. is ''a'' i.e., Binds to -SH group of enzyme Heavy metal toxicity is caused by tight binding of a metal such as mercury (Hg), lead (Pb), aluminium (Al), or iron (Fe) to a functional group of enzyme. Mercury, for example, binds to reactive sulfhydryl groups (-SH) in the active site of so many enzymes, that it has been difficult to determine which of the inhibited enzyme is responsible for mercury toxicity. Lead also has high affinity for sulfhydryl group.","pyqMatches":[{"year":"2013","no":369,"q":"The mechanism by which mercury causes damage ?","o":["Binds to -SH group of enzyme","Directly toxic","Inhibits ETC","Inhibits protein synthesis"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1106, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 225, '{"id":1106,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":225,"q":"Q10 in enzyme matches with ?","o":["2","4","8","10"],"a":0,"e":"Ans. is ''a'' i.e., 2 Most enzyme show a 50-300% (average 200%) increase in reaction rate when the temperature is increased by 10°, and the ratio of rate constant at two temperatures 10° apart is usually between 1.5 to 4 (average 2) for most enzymes. This value is termed as Q10. \"The rate of enzymatic reaction doubles with every 10° rise in temperature. \"","pyqMatches":[{"year":"2013","no":249,"q":"Q10 in enzyme matches with ?","o":["2","4","8","10"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1107, 'Biochemistry', 'Miscellaneous', 'Moderate', 'Biochemistry', 226, '{"id":1107,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Biochemistry","sourceNo":226,"q":"Creatine is made up of all, except ?","o":["Glycine","Alanine","Methionine","Arginine"],"a":1,"e":"Ans. is ''b'' i.e., Alanine","pyqMatches":[{"year":"2013","no":310,"q":"Creatine is made up of all, except ?","o":["Glycine","Alanine","Methionine","Arginine"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1108, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 227, '{"id":1108,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":227,"q":"In urea cycle which defect is an X linkeddisease ?","o":["Ornithine transcarbamylase","Aspartate transcarbamylase","Arginase","Argininosuccinate synthase"],"a":0,"e":"Ans. is ''a'' i.e., Ornithine transcarbamylase","pyqMatches":[{"year":"2013","no":314,"q":"In urea cycle which defect is an X linkeddisease ?","o":["Ornithine transcarbamylase","Aspartate transcarbamylase","Arginase","Argininosuccinate synthase"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1109, 'Biochemistry', 'Miscellaneous', 'Moderate', 'Biochemistry', 228, '{"id":1109,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Biochemistry","sourceNo":228,"q":"True regarding collagen synthesis is all except ?","o":["Synthesized in ribosomes as preprocollagen","Hydroxylation of proline occurs in Golgi apparatus","Hydroxylation of lysine occurs in ER","Triple helix assembly occurs in ER"],"a":1,"e":"Ans. is ''b'' i.e., Hydroxylation of proline occurs in Golgi apparatus","pyqMatches":[{"year":"2013","no":370,"q":"True regarding collagen synthesis is all except ?","o":["Synthesized in ribosomes as preprocollagen","Hydroxylation of proline occurs in Golgi apparatus","Hydroxylation of lysine occurs in ER","Triple helix assembly occurs in ER"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1110, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 229, '{"id":1110,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":229,"q":"Type of collagen found in space of Disse in liver is -","o":["Collagen I & II","Collagen III & IV","Collagen II &","Collagen II & V"],"a":1,"e":"Ans. is ''b'' i.e., Collagen III & IV","pyqMatches":[{"year":"2013","no":371,"q":"Type of collagen found in space of Disse in liver is","o":["Collagen I & II","Collagen III & IV","Collagen II &","Collagen II & V"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1111, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 230, '{"id":1111,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":230,"q":"Which is predominant in normal healthyhuman ?","o":["LDH 1","LDH2","LDH 3","LDH4"],"a":1,"e":"Ans. is ''b'' i.e., LDH2 IsoenzymeSubmit composition Issue Percentage in serrum LDH I HHHH Myocardium, RBC 30 LDH2 HHHM Myocardium, RBC 35 LDH3 HHMM Brain, Kidney 20 LDH4 HMMM Skeletal muscle, Liver 10 LDH 5 MMMM Skeletal muscle, Liver 5","pyqMatches":[{"year":"2013","no":252,"q":"Which is predominant in normal healthyhuman ?","o":["LDH 1","LDH2","LDH 3","LDH4"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1112, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 231, '{"id":1112,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":231,"q":"Physiological uncoupler is ?","o":["Thyroxine","Free fatty acids","Thermogenin","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above","pyqMatches":[{"year":"2013","no":262,"q":"Physiological uncoupler is ?","o":["Thyroxine","Free fatty acids","Thermogenin","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1113, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 232, '{"id":1113,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":232,"q":"Which of the following is Aldosugar ?","o":["Fructose","Erythrulose","Glucose","None"],"a":2,"e":"Ans. is `c'' i.e., Glucose Sugar Number of carbon atoms Aldoses (Aldosugars) Ketoses (ketosugars) Trioses 2 Glyceraldehyde Dihydroxyacetone Tetroses 4 Erythrose Erythrulose Pentoses 5 Ribose, Xylose Ribulose, xylulose Hexoses 6 Glucose, galactase, mannose Fructose Heptoses 7 Glucoheptose Sedoheptulose","pyqMatches":[{"year":"2013","no":264,"q":"Which of the following is Aldosugar ?","o":["Fructose","Erythrulose","Glucose","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1114, 'Biochemistry', 'Carbohydrate Metabolism', 'Moderate', 'Biochemistry', 233, '{"id":1114,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":233,"q":"Key enzyme of gluconeogenesis are all except?","o":["Pyruvate carboxylase","PEP carboxykinase","Pyruvate kinase","Glucose-6-phosphatase"],"a":2,"e":"Ans. is ''c'' i.e., Pyruvate kinase Mitochondrial pyruvate carboxylase catalyzes the carboxylation of Pyruvate to Oxaloacetate, It is an ATP-requiring reaction, Biotin is the coenzyme. Phosphoenolpyruvate Carboxykinase: Catalyzes the decarboxylation and phosphorylation of oxaloacetate to phosphoenolpyruvate(PEPCK) (Cytosol) using GTP as the phosphate donor. The conversion of glucose-6-phosphate to glucose is catalyzed by glucose 6-phosphatase","pyqMatches":[{"year":"2016","no":257,"q":"Key enzyme of gluconeogenesis are all except?","o":["Pyruvate carboxylase","PEP carboxykinase","Pyruvate kinase","Glucose-6-phosphatase"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1115, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 234, '{"id":1115,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":234,"q":"Fructose intolerance is due to deficiency of ?","o":["Aldolase B","Fructokinas","Triokinas","Aldolase A"],"a":0,"e":"Ans. is ''a'' i.e., Aldolase B Disease Dificient enzymes Essential fructosuria Fructokinase Hereditary fructose intolerance Aldolase-B Galactosemia Galactose-l-phosphate uridyl transferase (most common), Galactokinase UDP-galactose-4- epimerase Lactose intolerance Lactase ((3-galactosidase) Essential pentosuria L-xylulose dehydrogenase (xylulose reductase)","pyqMatches":[{"year":"2013","no":285,"q":"Fructose intolerance is due to deficiency of ?","o":["Aldolase B","Fructokinas","Triokinas","Aldolase A"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1116, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 235, '{"id":1116,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":235,"q":"What is essential for transfer of fatty acid across mitochondrial membrane -","o":["Creatine","Creatinine","Carnitine","None"],"a":2,"e":"Ans. is ''c'' i.e., Carnitine","pyqMatches":[{"year":"2013","no":293,"q":"What is essential for transfer of fatty acid across mitochondrial membrane","o":["Creatine","Creatinine","Carnitine","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1117, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 236, '{"id":1117,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":236,"q":"Hexokinase is ?","o":["Ligase","Transferase","Oxidoreductase","Reductase"],"a":1,"e":"Ans. is `b'' i.e., Transferase","pyqMatches":[{"year":"2013","no":251,"q":"Hexokinase is ?","o":["Ligase","Transferase","Oxidoreductase","Reductase"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1118, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 237, '{"id":1118,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":237,"q":"Ketone body formation without glycosuria is seen in ?","o":["Diabetes mellitus","Diabetes insipidus","Starvation","Obesity"],"a":2,"e":"Ans. is ''c'' i.e., Starvation Amongst the given options, DM and starvation are the causes of ketosis","pyqMatches":[{"year":"2013","no":292,"q":"Ketone body formation without glycosuria is seen in ?","o":["Diabetes mellitus","Diabetes insipidus","Starvation","Obesity"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1119, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 238, '{"id":1119,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":238,"q":"Amino acid with double chiral is ?","o":["Phenyalanine","Threonine","Tryptophane","Tyrosine"],"a":1,"e":"Ans. is ''b'' i.e., Threonine","pyqMatches":[{"year":"2013","no":304,"q":"Amino acid with double chiral is ?","o":["Phenyalanine","Threonine","Tryptophane","Tyrosine"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1120, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 239, '{"id":1120,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":239,"q":"At physiological pH DNA is ?","o":["Acidic","Negatively charged","Amphipathic","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above DNA is amphipathic Amphipathic molecule is one which contains both polar (hydrophilic) and nonpolar (hydrophobic) regions in its structure, i.e. the part of molecule is water soluble and part is water insoluble. In DNA helix Hydrophilic (polar) deoxyribose-phosphate of each chain is on outside of molecule. Hydrophobic (nonpolar) bases are stacked in. Thus DNA is regarded as amphipathic in nature. DNA is negatively charged and acidic Phosphate group lies on outside of molecule of DNA. Each phosphate group has a negative charge at physiological pH, making DNA a negatively charge (anion) at physilogical pH. \"Histones are strongly cationic and can bind non-specifically to strongly aniomic DNA\" Harper \"At physiological pH DNA is negatively charged, and is associated with positively charged (basic) histones\" Ronald Hofmann. o Anionic molecules are acidic in nature.","pyqMatches":[{"year":"2013","no":325,"q":"At physiological pH DNA is ?","o":["Acidic","Negatively charged","Amphipathic","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1121, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 240, '{"id":1121,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":240,"q":"Source of ammonia in urine ?","o":["Glutaminase","Urease","Glutamate dehydrogenase","Arginase"],"a":0,"e":"Ans. is ''a'' i.e., Glutaminase In many tissues like liver, kidney and brain, ammonia combines with glutamate to yield glutamine, by the action of glutamine synthase. The brain is a rich source of glutamine synthase and it predominantly detoxifies ammonia by this route. ATP ADP+Pi Glutamate + NH, 4 Glutamine Glutamine synthetase Glutamine is a nontoxic major transport form of ammonia. The glutamine is transported by blood to liver where deamination (removal of amino group) of glutamine takes place. Glutaminase cleaves glutamine to yield glutamate and free ammonia (ammonium ion). The ammonia is converted by liver to urea. 0 H2 Glutamine ________________________ Glutamate + NH, Glutaminase Formation and secretion ammonia by renal tubular cells maintain acid base balance. Ammonia is formed from glutamine by glutaminase. Excretion of ammonia increases in metabolic acidosis and decreases in metabolic alkalosis.","pyqMatches":[{"year":"2013","no":315,"q":"Source of ammonia in urine ?","o":["Glutaminase","Urease","Glutamate dehydrogenase","Arginase"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1122, 'Biochemistry', 'Miscellaneous', 'Moderate', 'Biochemistry', 241, '{"id":1122,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Biochemistry","sourceNo":241,"q":"Albumin binds with all except ?","o":["Steroid","Calcium","FFA","Thyroxine"],"a":3,"e":"Ans. is '' d'' i.e., Thyroxine Albumin is involved in transport of several substances because of its predominantly polar nature. Nearly 40% of plasma calcium is bound-up with albumin. Other substances which are Bound-up and/or tranported by albumin are :?","pyqMatches":[{"year":"2013","no":372,"q":"Albumin binds with all except ?","o":["Steroid","Calcium","FFA","Thyroxine"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1123, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 242, '{"id":1123,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":242,"q":"Chemical process involved in conversion of progesterone to glucocorticoids is","o":["Methylation","Hydroxylation","Carboxylation","None"],"a":1,"e":"Ans. is `b'' i.e., Hydroxylation","pyqMatches":[{"year":"2013","no":339,"q":"Chemical process involved in conversion of progesterone to glucocorticoids is","o":["Methylation","Hydroxylation","Carboxylation","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1124, 'Biochemistry', 'Carbohydrate Metabolism', 'Moderate', 'Biochemistry', 243, '{"id":1124,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":243,"q":"Gluconeogenesis occurs in all except ?","o":["Liver","Kidney","Gut","Muscle"],"a":3,"e":"Ans. is ''d'' i.e., Muscle Gluconeogenesis occurs mainly in the liver and to a lesser extent in renal cortex. Some gluconeogenesis can also occur in small intestine, but it is not significant. Some of the reactions of gluconeogenesis occurs in the mitochondria but most occur in cytosol. Gluconeogenesis cannot occur in muscles. Glucose-6-phosphatase is absent in muscles therefore, glucose-6- phosphate cannot be degraded to free glucose in muscles. Moreover, glucose-6-phosphate cannot diffuse out of the muscles. Therefore, muscle cannot provide glucose to maintain blood glucose level. Rather, muscle glycogen acts as a source of energy; the glucose-6​phosphate enters the glycolysis to produce energy.","pyqMatches":[{"year":"2013","no":271,"q":"Gluconeogenesis occurs in all except ?","o":["Liver","Kidney","Gut","Muscle"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1125, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 244, '{"id":1125,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":244,"q":"GLUT 2 receptors ?","o":["Insulin dependent","Insulin independent","Found in cardiac muscle","Found in brain"],"a":1,"e":"Ans. is ''b'' i.e., Insulin independent GLUT - 2 is insulin independent (insulin dependent GLUT is GLUT- 4). It is found in B-cells of islets of pancreas, liver, epithelial cells of small intestine and kidney. Also see explanation-4 of session-2.","pyqMatches":[{"year":"2013","no":287,"q":"GLUT 2 receptors ?","o":["Insulin dependent","Insulin independent","Found in cardiac muscle","Found in brain"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1126, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 245, '{"id":1126,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":245,"q":"Which of the following has antioxidant property?","o":["Selenium","Copper","Zinc","All"],"a":3,"e":"Ans. is ''d'' i.e., All The activity of the antioxidant enzymes depends on supply of minerals :?","pyqMatches":[{"year":"2015","no":346,"q":"Which of the following has antioxidant property?","o":["Selenium","Copper","Zinc","All"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1127, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 246, '{"id":1127,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":246,"q":"The number of ATPs generated in krebs cycleare ?","o":["12","24","15","30"],"a":1,"e":"Ans. is ''b'' > b'' i.e., 24 One turn of the TCA cycle, starting with acetyl CoA produces 10 ATPs. When the starting molecule is pyruvate, the oxidative decarboxylation of pyruvate, the oxidative decarboxylation of pyruvate yields 2.5 ATPs and therefore, 12.5 ATPs are produced when starting compound is pyruvate. Since, two molecules of pyruvate enter the TCA cycle when glucose is metabolized (glycolysis produces 2 molecules of pyruvate), the number of ATPs is doubled. Therefore, 25 ATP molecules, per glucose molecule, are produced when pyruvate enters the TCA cycle. Note : Previously calculations were made assuming that NADH produces 3 ATPs and FADH generates 2 ATPs. This will amount a net generation of 30 ATP molecules in TCA per molecule glucose and total 38 molecules from starting. Recent experiments show that these values are overestimates and NADH produces 2.5 ATPs and FADH produces 1.5 ATPs. Therefore, net generation during TCA is 25 ATPs and complete oxidation of glucose through glycolysis plus citric acid cycle yield a net 32 ATPs. Energy yield (number of ATP generated) per molecule of glucose when it is completely oxidized through glycolysis plus citric acid cycle, under aerobic conditions, is as follows :- Method of No of ATPs No of ATPs Pathway StepEnzyme Source ATP formation gained perglucose (new calculation) As per old calculatio Glycolysis1 Hexokinase Minus Minus Do 3 Phosphofructokinase Minus Minus Do 5 Glyceraldehyde-3-p DH NADH Respiratory chain 2.5 x 2 = 5 3 x 2 = 6 Do 6 1,3-BPGkinase ATP Substrate level 1 x 2 -- 2 1 x 2 = 2 Do 9 Pyruvate kinase ATP Substrate level 1 x 2 = 2 1 x 2 = 2 Pyruvate to ? Pyruvate NADH Respiratory chain 2.5x2= 5 3x2= 6 Acetyl CoA Dehydrogenase TCA cycle 3 Isocitrate DH NADH Respiratory chain 2.5x2= 5 3 x 2= 6 Do 4 Alpha keto glutarate DH NADH Respiratory chain 2.5x2= 5 3x2= 6 Do 5 Succinate thiokinase GTP Substrate level 1 x 2 = 2 1 x 2 = 2 Do 6 Succicinate DHFADH2 Respiratory chain 1.5x2= 3 2 x 2= 4 Do 8 Malate DH NADH Respiratory chain 2.5x2= 5 3 x 2= Net generation in glycolytic pathway 9 minus 2= 7 10 minus 2= 8 Generation in pyruvate dehydrogenase reaction 5 • 6 Generation in citric acid cycle 20 • 24 Net generation of ATP from one glucose mole 32 • 38","pyqMatches":[{"year":"2013","no":277,"q":"The number of ATPs generated in krebs cycleare ?","o":["12","24","15","30"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1128, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 247, '{"id":1128,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":247,"q":"One Krebs cycle generates how many ATP ?","o":["6","12","24","36"],"a":1,"e":"Ans. is ''b'' i.e., 12 This question is slightly different from previous one. Here the examiner is asking about the generaion of ATPs per TCA cycle. In a single TCA cycle 10 molecules of ATP are produced (12 molecules according to older calculations).","pyqMatches":[{"year":"2013","no":278,"q":"One Krebs cycle generates how many ATP ?","o":["6","12","24","36"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1129, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 248, '{"id":1129,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":248,"q":"Glutathione requires which vitamin to act as antioxidant ?","o":["Vitamin E","Niacin","Vitamin C","Vitamin A"],"a":1,"e":"Ans. is ''b'' i.e., Niacin","pyqMatches":[{"year":"2013","no":348,"q":"Glutathione requires which vitamin to act as antioxidant ?","o":["Vitamin E","Niacin","Vitamin C","Vitamin A"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1130, 'Biochemistry', 'Carbohydrate Metabolism', 'Moderate', 'Biochemistry', 249, '{"id":1130,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":249,"q":"Metabolic change seen in starvation are all except?","o":["Increased gluconeogenesis","Increased glycolysis","Ketogenesis","Protien degradation"],"a":1,"e":"Ans. is ''b'' i.e., Increased glycolysis","pyqMatches":[{"year":"2013","no":360,"q":"Metabolic change seen in starvation are all except?","o":["Increased gluconeogenesis","Increased glycolysis","Ketogenesis","Protien degradation"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1131, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 250, '{"id":1131,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":250,"q":"Catecholamines are synthesized from ?","o":["Tryptophan","Tyrosine","Methionine","Histidine"],"a":1,"e":"Ans. is ''b'' i.e., Tyrosine Catecholamines (epinephrine, norepinephrine and dopamine) are synthesized from tyrosin. Has been explained in previous seesions.","pyqMatches":[{"year":"2013","no":309,"q":"Catecholamines are synthesized from ?","o":["Tryptophan","Tyrosine","Methionine","Histidine"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1132, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 251, '{"id":1132,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":251,"q":"Which of the enzyme of glycolysis is a part ofgluconeogenesis ?","o":["Pyruvate kinase","PFK","Hexokinase","Phosphoglycerate kinase"],"a":3,"e":"Ans. is ''d'' i.e., Phosphoglycerate kinase Seven of the reactions of glycolysis are reversible and are used in the synthesis of glucose by gluconeogenesis. Thus, seven enzymes are common to both glycolysis and gluconeogenesis: (i) Phosphohexose isomerase; (ii) Aldolase; (iii) Phosphotriose isomerase, (iv) Glyceraldehyde 3-phosphate dehydrogenase; (v) Phosphoglycerate kinase; (vi) Phosphoglycerate mutase; (vii) Enolase. Three reactions of glycolysis are irreversible which are circumvented in gluconeogenesis by four reactions. So, enzymes at these steps are different in glycolysis and gluconeogenesis. Reactions Enzyme in glycolysis Enzyme in gluconeogenesis Glucose – Glucose-6-P Hexokinase/glucokinase Glucose-6-phosphatase Fructose-6-P – Fructose- I ,6-BP Phosphofructokinase Fructose-1-6-bisphosphatase Phosphoenolpyruvate – Pyruvate Pyruvate kinase Pyruvate carboxylase PEP carboxykinase","pyqMatches":[{"year":"2013","no":274,"q":"Which of the enzyme of glycolysis is a part ofgluconeogenesis ?","o":["Pyruvate kinase","PFK","Hexokinase","Phosphoglycerate kinase"],"a":3,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":274,"q":"Which of the enzyme of glycolysis is a part ofgluconeogenesis ?","o":["Pyruvate kinase","PFK","Hexokinase","Phosphoglycerate kinase"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1133, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 252, '{"id":1133,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":252,"q":"Molecular interaction, found in the structure ofDNA -","o":["Hydrogen bond","Glycosidic bond","Covalent interactions","All of the above"],"a":3,"e":"Ans. is''d'' i.e., All of the above","pyqMatches":[{"year":"2013","no":328,"q":"Molecular interaction, found in the structure ofDNA","o":["Hydrogen bond","Glycosidic bond","Covalent interactions","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1134, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 253, '{"id":1134,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":253,"q":"Pyridoxine is used in treatment of ?","o":["Galactosemia","Phenylketonuria","Propionic acidemia","Homocystinuria"],"a":3,"e":"Ans. is ''d'' i.e., Homocystinuria Inborn error of metabolism and Treatment Alkaptonuria Vitamin C, Folic acid Homocystinuria Pyridoxine + Folic acid Cystinuria Alkalization of urine + d-Penicillamine, Captopril Hartnup disease Nicotinamide Multiple carboxylase eficiency Biotin Methyl malonic academia Vitamin B 12 Hyperoxaluria Pyridoxine Tyrosinemia NTBC, Liver Transplantation","pyqMatches":[{"year":"2013","no":625,"q":"Pyridoxine is used in treatment of ?","o":["Galactosemia","Phenylketonuria","Propionic acidemia","Homocystinuria"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1135, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 254, '{"id":1135,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":254,"q":"Membrane proteins are synthesized in ?","o":["Free ribosome","Bound ribosome","Nucleolus","Mitochondria"],"a":1,"e":"Ans. is ''b'' i.e., Bound ribosome Ribosomes Ribosomes are the actual sites of protein synthesisQ. The ribosomes are small granules of RNAs. Ribosomes are usually occur in clusters called polyribosomes attached to one mRNA molecule, an arrangement that increases the rate of polypeptide synthesis. There are two types of polyribosomes : -","pyqMatches":[{"year":"2013","no":341,"q":"Membrane proteins are synthesized in ?","o":["Free ribosome","Bound ribosome","Nucleolus","Mitochondria"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1136, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 255, '{"id":1136,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":255,"q":"Transmination of Aspartate forms ?","o":["Pyruvate","Acetly-CoA","Oxaloacetate","Alanine"],"a":2,"e":"Ans. is ''c'' i.e., Oxaloacetate Transamination Transamination involves the reversible transfer of a-amino group of a-amino acid to an a-keto acid('' to form a new amino acid and a new keto acid. The enzyme catalyze the reaction is called aminotransferase (transaminase). Most transaminases use a- ketoglutarate (a-keto acid) as a common acceptor of a-amino group of a-amino acids. All transaminases require pyridoxal phosphate (Vitamin B6) as a coenzymneQ. Some of the most important transaminases are : - Alanine transaminase (ALT) also called glutamate pyruvate transaminase (GPT) : - It catalyzes the transfer of amino group of alanine to a-ketoglutarate resulting in formation of pyruvate and L- glutamate Q. ALT L-Alanine Q+ a-ketoglutarate Q _____ Pyruvate Q + L-glutamate Q PLP Aspartate transaminase (AST) also called glutamate oxaloacetate transaminase (GOT) : It catalyzes the transfer of amino group of aspartate to a-ketoglutarate resulting in formation of oxaloacetate and L-glutamate. AST L-Aspartate + a-ketoglutarate Oxaloacetate + L-glutamate PLP Most amino acids undergo transamination reaction except lysine, threonine, proline and hydroxyproline. All the amino groups from amino acids that undergo transamination are collected into one common amino acid, i.e., glutamate. This is important because L-glutamate is the only amino acid that undergoes oxidative deamination at an appreciable rate in mammalian tissue. Thus, formation of ammonia from amino acids occurs mainly via the a-amino nitrogen of glutamate. Transamination is not restricted to a-amino groups. The 6-amino group of ornithine (but not the E-amino group of lysine) undergoes transmination.","pyqMatches":[{"year":"2013","no":313,"q":"Transmination of Aspartate forms ?","o":["Pyruvate","Acetly-CoA","Oxaloacetate","Alanine"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1137, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 256, '{"id":1137,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":256,"q":"Interaction involved in primary structure of protein ?","o":["Hydrogen bond","Disulfide bond","Peptide bond","Electrostatic bond"],"a":2,"e":"Ans. is `c'' i.e., Peptide bond","pyqMatches":[{"year":"2013","no":303,"q":"Interaction involved in primary structure of protein ?","o":["Hydrogen bond","Disulfide bond","Peptide bond","Electrostatic bond"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1138, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 257, '{"id":1138,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":257,"q":"All are true about vitamin E except ?","o":["Act as antioxidant","Prevent lipid peroxidation of cell membrane","Water soluble vitamin","Chemically tocopheral"],"a":2,"e":"Ans. is ''c'' i.e., Water soluble vitamin Vitamin E is a fat soluble vitamin (not water soluble). All other options are correct.","pyqMatches":[{"year":"2013","no":349,"q":"All are true about vitamin E except ?","o":["Act as antioxidant","Prevent lipid peroxidation of cell membrane","Water soluble vitamin","Chemically tocopheral"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1139, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 258, '{"id":1139,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":258,"q":"Blood form of folic acid is -","o":["Folinic acid","Pteroglutamate","Methyl THE","None"],"a":2,"e":"Ans. is ''c'' i.e., Methyl THE Folic acid is absorbed in the jejunum. Following absorption, folic acid is transported in blood by two (3- globulins. The major circulating form is methyltetrahydrofolate and the normal concentration range is 5-15 ng/ml. Once it arrives in the liver, the methyl derivates are taken up by hepatocytes where various coenzyme are produced. o Folic acid is not stored in the body. Remembers Major circulating form of folic acid —0 methyl THE Major point of entery for 1 carbon transfer by substitued folate -4 methylene THE","pyqMatches":[{"year":"2013","no":351,"q":"Blood form of folic acid is","o":["Folinic acid","Pteroglutamate","Methyl THE","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1140, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 259, '{"id":1140,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":259,"q":"Primary hypercholesterolemia is ?","o":["Type I","Type Ha","Type IIb","Type III"],"a":1,"e":"Ans. is ''b'' i.e., Type Ha","pyqMatches":[{"year":"2013","no":302,"q":"Primary hypercholesterolemia is ?","o":["Type I","Type Ha","Type IIb","Type III"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1141, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 260, '{"id":1141,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":260,"q":"Salvage purine synthesis refers to ?","o":["Synthesis of purine from ribose-5-phosphate","Synthesis of purine from pyrimidine","Synthesis of purine nucleotides from purine bases","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., Synthesis of purine nucleotides from purine bases Two important purine nucleotides are synthesized : (i) adenosine monophosphate (AMP) and (ii) guanosine monophosphate (GMP). Then AMP and GMP are converted to other purine nucleotides like ADP, ATP, GDP, GTP etc. Purine nucleotides can be synthesized by two pathways - (1) De novo synthesis and (2) Salvage pathway. De novo pathway (De novo synthesis) In de novo pathway, the purine nucleotides are synthesized from amphibolic intermediates. Amphibolic intermediates are the intermediary metabolites of amphibolic pathways (eg. citric acid cycle) which have dual purposes, i e. they serve in catabolism as well as in anabolism. In de novo synthesis, purine ring is formed from variety of precursors is assembled on ribose-5-phosphate. Precursors for de novo synthesis are ?","pyqMatches":[{"year":"2013","no":321,"q":"Salvage purine synthesis refers to ?","o":["Synthesis of purine from ribose-5-phosphate","Synthesis of purine from pyrimidine","Synthesis of purine nucleotides from purine bases","None of the above"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1142, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 261, '{"id":1142,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":261,"q":"RNA which contains codon for speicific amino acid ?","o":["tRNA","rRNA","mRNA","None"],"a":2,"e":"Ans. is ''c'' i.e., m RNA The m RNA carries genetic information in the form of codons. Codons are a group of three adjacent nucleotides that code for the amino acids of protein. Each mRNA molecule is a transcript of antisense or template strand of a particular gene. Its nucleotide sequence is complementary to that of antisense or template strand of the gene, i.e. adenine for thyamine, guanine for cytosine, uracil for adenine (as RNA does not contain thymine) and cytosine for guanine. For example, if antisense strand of DNA has a gene with sequence 5''-TTACGTAC-3'', its complementary RNA transcript will be 5 ''- GUACGUAA-3''.","pyqMatches":[{"year":"2013","no":333,"q":"RNA which contains codon for speicific amino acid ?","o":["tRNA","rRNA","mRNA","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1143, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 262, '{"id":1143,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":262,"q":"Glycine is required in formation of all except ?","o":["Heme","Purines","Glutathione","Thyroxine"],"a":3,"e":"Ans. is ''d'' i.e., Thyroxine Glycine lycine is a nonessential amino acid which is synthesized from serine. Glycine is metabolized by following three pathways - It can be converted to serine, a reaction that require tetrahydrofolate (derivative of folic acid and pyridoxal phosphate as coenzyme. Further serine is metabolized by serine dehydratase into pyruvate and NH 4+. The major pathway of glycine degradation is oxidative cleavage into CO, and NH: by glycine cleavage complex of liver. H4 folate is required which is converted to N5, N10-methylene H4 folate. Thus folic acid is required for glycine metabolism. Glycine may be oxidatively deaminated by glycine oxidase to glyoxylic acid. Glycine is necessary for the formation of following products:- Heme, purine ring, bile acids conjugation (formation of glycocholic acid, and glyco-chenodeoxycholic acid), creatine, glutathione, glucose (by gluconeogenesis).","pyqMatches":[{"year":"2015","no":333,"q":"Glycine is required in formation of all except ?","o":["Heme","Purines","Glutathione","Thyroxine"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1144, 'Biochemistry', 'Carbohydrate Metabolism', 'Moderate', 'Biochemistry', 263, '{"id":1144,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":263,"q":"True about glycolysis are all except ?","o":["Provide nutrition to cancer cells","Substrate level phosphorylation at pyruvate kinase","Two carbon end product is formed","NADPH is formed by glyceraldhyde-3-phosphate dehydrogenase"],"a":2,"e":"Ans. is ''c'' i.e., Two carbon end product is formed Important facts about glycolysis An important biochemical significance is the ability of glycolysis to provide ATP in the absence of oxygen (anerobic glycolysis) and allows tissues to survive anoxic episodes. It occurs in cytosol 3 Carbon atoms end product (pyruvate or lactate) is produced. Irreversible steps are catalyzed by : - Glucokinase/Hexokinase, phosphofructohnase-I, and pyruvate kinase. Reversible steps are catalyzed by : - Phosphohexose isomerase, aldolase, phosphotriose isomerase, glyceraldehyde 3-phosphate dehydrogenase, Phosphoglycerate kinase, Phosphoglycerate mutase, Enolase. Energy (ATP) using steps are catalyzee by : - Hexokinase/glucokinase, phosphofurctokinase. Energy (ATP) production at substrate level are catalyzed by : Phosphoglycerate kinase, Pyruvate kinase. Reducing equivalent (NADH) production is catalyzed by : Glyceraldehyde 3-phosphate dehydrogenase. Cancer cells derive nutrition from glycolysis as they have lack of 02 supply because of lack of capillary network. Glycolysis (anaerobic glycolysis) is the only metabolic pathway in the body which can provide energy by glucose metabolism in anerobic conditions.","pyqMatches":[{"year":"2013","no":275,"q":"True about glycolysis are all except ?","o":["Provide nutrition to cancer cells","Substrate level phosphorylation at pyruvate kinase","Two carbon end product is formed","NADPH is formed by glyceraldhyde-3-phosphate dehydrogenase"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1145, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 264, '{"id":1145,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":264,"q":"Instant energy to muscle is provided by which pathway?","o":["HMP shunt","Embden mayerhoff pathway","Cori cycle","TCA cycle"],"a":1,"e":"Ans. is '' b'' i.e., Embden mayerhoff pathway ATP and creatine phosphate provide immediate energy.. Anaerobic glycolysis (EMP) provides early energy.","pyqMatches":[{"year":"2013","no":357,"q":"Instant energy to muscle is provided by which pathway?","o":["HMP shunt","Embden mayerhoff pathway","Cori cycle","TCA cycle"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1146, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 265, '{"id":1146,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":265,"q":"Which steroid is formed from cholesterol with​out hydroxylation ?","o":["Progesterone","Glucocorticoid","Mineralocorticoid","Estradiol"],"a":0,"e":"Ans. is ''a'' i.e., Progesterone Progesterone is formed before hydroxylation step.","pyqMatches":[{"year":"2013","no":340,"q":"Which steroid is formed from cholesterol with​out hydroxylation ?","o":["Progesterone","Glucocorticoid","Mineralocorticoid","Estradiol"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1147, 'Biochemistry', 'Vitamins & Minerals', 'Moderate', 'Biochemistry', 266, '{"id":1147,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Moderate","source":"Biochemistry","sourceNo":266,"q":"Not obtained from plant source ?","o":["Cobalamine","Riboflavin","Thiamine","Vitamin A"],"a":0,"e":"Ans. is ''a'' i.e., Cobalamine Vitamin B12 (cobalamin or cynocobalmin) is present only in food of animal origin. Other three vitamins can be taken from plant source.","pyqMatches":[{"year":"2013","no":352,"q":"Not obtained from plant source ?","o":["Cobalamine","Riboflavin","Thiamine","Vitamin A"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1148, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 267, '{"id":1148,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":267,"q":"Pseudouridine found in?","o":["DNA","rRNA","mRNA","tRNA"],"a":3,"e":"Ans. is ''d'' i.e., tRNA Modified bases found in tRNA are -","pyqMatches":[{"year":"2013","no":334,"q":"Pseudouridine found in?","o":["DNA","rRNA","mRNA","tRNA"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1149, 'Biochemistry', 'Lipid Metabolism', 'Moderate', 'Biochemistry', 268, '{"id":1149,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":268,"q":"Fatty acids used by all except ?","o":["Liver","Muscle","Brain","Kidney"],"a":2,"e":"Ans. is `c'' i.e., Brain There is no stored fuel in brain, but it utilized 60% of total energy under resting conditions. Glucose is virtually the sole fuel for the brain, except in prolonged starving when ketone bodies are the major source. Fatty acids do not serve as fuel for the brain, because they are bound to albumin in plasma; hence cannot cross blood-brain barrier.","pyqMatches":[{"year":"2013","no":359,"q":"Fatty acids used by all except ?","o":["Liver","Muscle","Brain","Kidney"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1150, 'Biochemistry', 'Vitamins & Minerals', 'Moderate', 'Biochemistry', 269, '{"id":1150,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Moderate","source":"Biochemistry","sourceNo":269,"q":"Vitamin not required in TCA cycle ?","o":["Niacin","Riboflavin","Thiamine","Folic acid"],"a":3,"e":"Ans. is ''d'' i.e., Folic acid Four of the B vitamins are essential in the citric acid cycle :","pyqMatches":[{"year":"2013","no":279,"q":"Vitamin not required in TCA cycle ?","o":["Niacin","Riboflavin","Thiamine","Folic acid"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1151, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 270, '{"id":1151,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":270,"q":"Uric acid is formed by ?","o":["Catabolism of proteins","Catabolism of ketones","Catabolism of purines","Catabolism fo pyrimidines"],"a":2,"e":"Ans. is ''c'' i.e., Catabolism of purines","pyqMatches":[{"year":"2012","no":372,"q":"Uric acid is formed by ?","o":["Catabolism of proteins","Catabolism of ketones","Catabolism of purines","Catabolism fo pyrimidines"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1152, 'Biochemistry', 'Carbohydrate Metabolism', 'Moderate', 'Biochemistry', 271, '{"id":1152,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":271,"q":"Anaerobic glycolysis occurs in all places except","o":["Muscles","RBCs","Brain","Kidney"],"a":2,"e":"Ans. is ''c'' i.e., Brain There are two types of glycolysis : -","pyqMatches":[{"year":"2013","no":276,"q":"Anaerobic glycolysis occurs in all places except","o":["Muscles","RBCs","Brain","Kidney"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1153, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 272, '{"id":1153,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":272,"q":"Sweaty feet odor in urine is seen in ?","o":["Phenylketonuria","Maple syrup urine","Isovaleric acidemia","Alkaptonuria"],"a":2,"e":"Ans. is ''c'' i.e., Isovaleric acidemia \"Sweaty Feet\" odour is seen in isovaleric acidemia & glutaric aciduria \"Mousy or Musty Odour\" of skin, hair and urine is seen in PKU. Burnt sugar like odour is seen in MSU disease (Branched chain ketonuria). Boiled cabbage like urinary odour is seen in - Tyrosinemia & hypermethioninemia. Swimming pool urine odour is seen in - Hawkinsinuria","pyqMatches":[{"year":"2013","no":320,"q":"Sweaty feet odor in urine is seen in ?","o":["Phenylketonuria","Maple syrup urine","Isovaleric acidemia","Alkaptonuria"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1154, 'Biochemistry', 'Lipid Metabolism', 'Moderate', 'Biochemistry', 273, '{"id":1154,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":273,"q":"Ketone bodies are not used by ?","o":["Muscle","Brain","RBC","Renal cortex"],"a":2,"e":"Ans. is ''c'' i.e., RBC Only glucose is the sole fuel for RBCs. As RBCs have no mitochondria, they oxidize glucose anaerobically to lactate. Liver also cannot use ketone bodies because of lack of succinyl- CoA-acetoacetate-CoA transferase, which is required for activation of ketone bodies.","pyqMatches":[{"year":"2013","no":291,"q":"Ketone bodies are not used by ?","o":["Muscle","Brain","RBC","Renal cortex"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1155, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 274, '{"id":1155,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":274,"q":"Which collagen produces sheets ?","o":["I","II","IV","VI"],"a":2,"e":"Ans. is ''c'' i.e., IV Various structure produced by collagens Fibrils Sheets Beaded filamentsAnchoring fibrils Collagen I Collagen IV Collagen VI Collagen VII Collagen II Collagen VIII Collagen III Collagen X Collagen V Collagen XI","pyqMatches":[{"year":"2013","no":373,"q":"Which collagen produces sheets ?","o":["I","II","IV","VI"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1156, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 275, '{"id":1156,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":275,"q":"The energy for glycogenesis is provided by -","o":["GTP","GDP","UTP","AMP"],"a":2,"e":"Ans. is ''c'' i.e., UTP","pyqMatches":[{"year":"2013","no":280,"q":"The energy for glycogenesis is provided by","o":["GTP","GDP","UTP","AMP"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1157, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 276, '{"id":1157,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":276,"q":"The function of vitamin K largely depends on which mineral ?","o":["Selenium","Calcium","Iron","Magnesium"],"a":1,"e":"Ans. is ''b'' i.e., Calcium Vitamin K plays an important role in blood coagulation for it is required for the post-translational processing of several clotting factors (factor II, VII, IX and X). Maturation of these clotting factors requires the conversion of glutamyl residues of precursor proteins into ''y​carboxyglutamate (Gla) residues by addition of carboxylate group. This carboxylation of glutamyl resdiue is vitamin K dependent. The y-carboxyglutamate (Gla) residues so formed serve as binding site for calcium ions. Each Gla contains two negative charges which chelate the positive calcium ion. After binding to Gla residue on activated clotting factor, calcium binds with negatively charged phospholipids present on the platelet cell membrane. In this way, bridging of the phospholipids the Gla residue of prothromin occurs via calcium ion.","pyqMatches":[{"year":"2013","no":353,"q":"The function of vitamin K largely depends on which mineral ?","o":["Selenium","Calcium","Iron","Magnesium"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1158, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 277, '{"id":1158,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":277,"q":"Amino acid with aliphatic side chain is?","o":["Serine","Leucine","Threonine","Aspartate"],"a":1,"e":"Ans. ''B'' Leucine Based on the chemical structure of side chain, amino acids are classified into ? Aliphatic amino acids:- Alanine, glycine, isoleucine, leucine, valine. Hydroxy amino acids:- serine, threonine, tyrosine. Sulfur-containing amino acids:- Cysteine, methionine. Dicarboxylic amino acids:- Aspartic acid (aspartate), glutamic acid (glutamate). Amide containing amino acids:- Glutamine, aspargine (these are amides of dicarboxylic amino acids. Glutamine is an amide of glutamic acid and aspargine is an amide of aspartic acid). Aromatic amino acids:- Phenylalanine, tyrosine, tryptophan. Imino acids or heterocyclic amino acids:- One of the 20 amino acids, proline is an imino (-NH) acid not an amino (-NH) acid, as are other","pyqMatches":[{"year":"2013","no":307,"q":"Amino acid with aliphatic side chain is?","o":["Serine","Leucine","Threonine","Aspartate"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1159, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 278, '{"id":1159,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":278,"q":"According to IUB system, hydrolases belong to which class ?","o":["EC-1","EC-2","EC-3","EC-4"],"a":2,"e":"Ans. is ''c'' i.e., EC-3 IUB classification Enzyme code number (EC number)Enzyme EC-1 Oxidoreductase EC-2 Transferase EC-3 Hydrolases EC-4 Lyases EC-5 Isomerases EC-6 Ligases","pyqMatches":[{"year":"2013","no":253,"q":"According to IUB system, hydrolases belong to which class ?","o":["EC-1","EC-2","EC-3","EC-4"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1160, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 279, '{"id":1160,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":279,"q":"Which of the following is serine protease ?","o":["Pepsin","Trypsin","Carboxypeptidase","None"],"a":1,"e":"Ans. is ''b'' i.e., Trypsin","pyqMatches":[{"year":"2013","no":254,"q":"Which of the following is serine protease ?","o":["Pepsin","Trypsin","Carboxypeptidase","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1161, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 280, '{"id":1161,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":280,"q":"Reducing equivalants produced in glycolysis are transported from cytosol to mitochondria by ?","o":["Carnitine","Creatine","Malate shuttle","Glutamate shuttle"],"a":2,"e":"Ans. is ''c'' i.e., Malate shuttle Most of the NADH and FADH2, entering the mitochondrial electron transport chain arise from citric acid cycle and 13-oxidation of fatty acids, located in the mitochondria itself. However, NADH is also produced in the cytosol during glycolysis. To get oxidized, NADH has to be transported into the mitochondria as respiratory chain (ETC) is located inside the mitochondria. Since, the inner mitochondrial membrane is not permeable to cytoplasmic NADH, there are special shuttle systems which carry reducing equivalents from cytosolic NADH (rather than NADH itself) into the mitochondria by an indirect route. Two such shuttle systems that can lead to transport of reducing equivalent from the cytoplasm into mitochondria are : -","pyqMatches":[{"year":"2013","no":263,"q":"Reducing equivalants produced in glycolysis are transported from cytosol to mitochondria by ?","o":["Carnitine","Creatine","Malate shuttle","Glutamate shuttle"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1162, 'Biochemistry', 'Carbohydrate Metabolism', 'Moderate', 'Biochemistry', 281, '{"id":1162,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":281,"q":"HMP shunt occurs in all organs except ?","o":["Liver","Adipose tissue","RBC","Brain"],"a":3,"e":"Ans. is ''d'' i.e., Brain HMP is an alternative route for the oxidation of glucose (beside glycolysis). It is also called as \"pentose phosphate pathway\", \"Dickens - Horecker pathway\", \"Shunt pathway\" or \"phosphogluconate oxidative pathway\". HMP shunt is required for provision of reduced NADPH and fiver- carbon sugars (Pentose phosphates) for nucleic acid synthesis. Normally, 90% of glucose is oxidized by glycolysis and 10% is oxidized by HMP shunt. However, in liver and RBCs HMP shunt accounts for oxidation of 30% glucose. HMP shunt occurs in the cytosol. It is highly active in liver, adipose tissue, adrenal cortex, lens, cornea, lactating (but not the nonlactating) mammag gland, Gonads (testis, ovary) and erythrocytes. Activity of this pathway is minimal in muscle and brain, where almost all of the glucose is degraded by glycolysis.","pyqMatches":[{"year":"2013","no":282,"q":"HMP shunt occurs in all organs except ?","o":["Liver","Adipose tissue","RBC","Brain"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1163, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 282, '{"id":1163,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":282,"q":"Fastest acting enzyme ?","o":["LDH","Trypsin","Catalase","None"],"a":2,"e":"Ans. is ''c'' i.e., Catalase Measurement of enzyme activity The activity of enzyme is measured in terms of the following : Unit of enzyme activity : - By international agreement, one unit enzyme activity is defined as the amount causing transformation of 1.0 micro mole of substrate per minute at 25° C. It is usually expressed as mole of substrate disappeared or mole of product formed per minute. Specific activity : - It refers to the number of enzyme units per milligram of protein. It is a measure of enzyme purity; higher the enzyme purity, more is the specific activity. Turn over number : - This refers to the number of substrate molecules transformed per unit time by a single enzyme molecule (or by a single catalytic site), when the enzyme concentration alone is rate-limiting factor. Catalase has the highest turnover number and hence is the fastest active enzyme. Carbonic anydrase has the 2\" fastest turnover number; therefore, it is 2nd fastest active enzyme (after catalase). Lysozyme has the lowest turnover number and therefore is slowest acting.","pyqMatches":[{"year":"2013","no":255,"q":"Fastest acting enzyme ?","o":["LDH","Trypsin","Catalase","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1164, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 283, '{"id":1164,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":283,"q":"Inhibition of glycolysis by increased supply of 02 is called ?","o":["Crabtree effect","Pasteur effect","Lewis effect","None"],"a":1,"e":"Ans. is ''b'' i.e., Pasteur effect Pasteur effect It has been observed that under anaerobic condition a tissue or microorganism utilizes more glucose than it does under aerobic conditions. It reflects inhibition of glycolysis by oxygen and is called pasteure effect. The Pasteur effect is due to inhibition of the enzyme phosphofructokinase because of inhibitory effect caused by citrate and ATP, the compounds produced in presence of oxygen due to operation of TCA cycle. Crabtree effect This is opposite of Pasteur effect, which represents decreased respiration of cellular systems caused by high concentration of glucose. When oxygen supply is kept constant and glucose concentration is increased, the oxygen consumption by cells falls, i.e., relative anaerobiosis is produced when glucose concentration is increased in constant supply of oxygen. It is seen in cells that have a high rate of aerobic glycolysis. In such cells the glycolytic sequence consumes much of the available Pi and NAD+, which limits their availability for oxidative phosphorylation. As a result, rate of oxidative phosphorylation decreases, and oxygen consumption also shows a corresponding fall.","pyqMatches":[{"year":"2013","no":288,"q":"Inhibition of glycolysis by increased supply of 02 is called ?","o":["Crabtree effect","Pasteur effect","Lewis effect","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1165, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 284, '{"id":1165,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":284,"q":"RNA is present in ?","o":["Cytoplasm","Nucleus","Ribosome","All of the above"],"a":3,"e":"Ans. is `d'' i.e., All of the above mRNA is synthesized from DNA by the process of transcription in the nucleus. After formation mRNA transport out of the nucleus into cytoplasm. t-RNA is also synthesized in nucleus and is transported to cytoplasm. Protein synthesis (translation) occurs in ribosomes, and requires both mRNA and tRNA. rRNA is present in ribosomes. rRNA is synthesized in nucleolus Thus, RNA can be found in -","pyqMatches":[{"year":"2013","no":335,"q":"RNA is present in ?","o":["Cytoplasm","Nucleus","Ribosome","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1166, 'Biochemistry', 'Carbohydrate Metabolism', 'Moderate', 'Biochemistry', 285, '{"id":1166,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":285,"q":"All are reducing sugars except-","o":["Sucrose","Lactose","Glucose","Fructose"],"a":0,"e":"Ans. A. Sucrose Disaccharides Sugar Units Linkage Trehalose (Sugar of insect hemolymph, yeast and fungi) αDGlucose + αDGlucose α1 ------- α1 linkage Sucrose (Cane Sugar) αDGlucose +β DFructose α1 ------- β2 linkage","pyqMatches":[{"year":"2012","no":282,"q":"All are reducing sugars except","o":["Sucrose","Lactose","Glucose","Fructose"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1167, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 286, '{"id":1167,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":286,"q":"Reducing sugar in urine can be detected by-","o":["a) Benedicts test","b) Fehling solution","c) Glucose-oxidase test","d) All of the above"],"a":3,"e":"Explanation- Reducing sugar can be detected by- benedict’s test, fehling’s test, gluco-oxidase test.","pyqMatches":[{"year":"2013","no":283,"q":"Reducing sugar in urine can be detected by","o":["a) Benedicts test","b) Fehling solution","c) Glucose-oxidase test","d) All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1168, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 287, '{"id":1168,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":287,"q":"Substrate level phosphorylation is by","o":["Pyruvate kinase","Phosphofructokinase","Hexokinase","ATP synthase"],"a":0,"e":"Ans. ''A'' Pyruvate kinase Substrate Level Phosphorylation- In Glycolysis- Phosphoglycerate kinase Pyruvate kinase In Citric Acid Cycle- Succinate thiokinase","pyqMatches":[{"year":"2012","no":251,"q":"Substrate level phosphorylation is by","o":["Pyruvate kinase","Phosphofructokinase","Hexokinase","ATP synthase"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1169, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 288, '{"id":1169,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":288,"q":"Type VI glycogen storage disease is due to the deficiency of –","o":["Muscle phosphorylase","Glucose-6-phosphatase","Liver phosphorylase","Branching enzyme"],"a":2,"e":"Type VI glycogen is also called Her’s disease and it is caused by enzyme defect liver phosphorylase. Clinical features are hepatomegaly, accumulation of glycogen in the liver and mild hypoglycemia.","pyqMatches":[{"year":"2014","no":293,"q":"Type VI glycogen storage disease is due to the deficiency of –","o":["Muscle phosphorylase","Glucose-6-phosphatase","Liver phosphorylase","Branching enzyme"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1170, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 289, '{"id":1170,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":289,"q":"Xanthoproteic reaction involves-","o":["Carbolic acid","H2SO4","HCL","Nitric acid"],"a":3,"e":"Ans. ''D'' Nitric acid Xanthoproteic test: The ring systems in phenylalanine, tyrosine and tryptophan undergo nitration on treatment with concentrated nitric acid when heated. The end product is yellow in color which is intensified in strong alkaline medium. This reaction causes the yellow stain in the skin by nitric acid.","pyqMatches":[{"year":"2012","no":318,"q":"Xanthoproteic reaction involves","o":["Carbolic acid","H2SO4","HCL","Nitric acid"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1171, 'Biochemistry', 'Vitamins & Minerals', 'Moderate', 'Biochemistry', 290, '{"id":1171,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Moderate","source":"Biochemistry","sourceNo":290,"q":"Coenzyme not required in formation of glutamate-","o":["Thiamine pyrophosphate","Pyridoxial phosphate","Niacin","None of the above"],"a":0,"e":"Ans. ''A'' Thiamine pyrophosphate NAD+ is derived from nicotinic acid, a member of the vitamin B complex, used in the synthesis of GABA. During transamination reaction glutamate is formed. Pyridoxal Phosphate acts as a coenzyme.","pyqMatches":[{"year":"2015","no":348,"q":"Coenzyme not required in formation of glutamate","o":["Thiamine pyrophosphate","Pyridoxial phosphate","Niacin","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1172, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 291, '{"id":1172,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":291,"q":"Zewellger syndrone is due to absence of","o":["Lysosomal","Mitochondria","Peroxisome","Nucleus"],"a":2,"e":"Answer. C. Peroxisome Zellweger syndrome, also called cerebrohepatorenal syndrome, is a rare congenital disorder characterized by the reduction or absence of functional peroxisomes in the cells of an individual. Zellweger syndrome is associated with impaired neuronal migration, neuronal positioning, and brain development. In addition, individuals with Zellweger syndrome can show a reduction in central nervous system (CNS) myelin (particularly cerebral), which is referred to as hypomyelination.","pyqMatches":[{"year":"2019","no":32,"q":"Zewellger syndrone is due to absence of","o":["Lysosomal","Mitochondria","Peroxisome","Nucleus"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1173, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 292, '{"id":1173,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":292,"q":"Urea, creatinine, nitric oxide formed by which amino acid","o":["Histidine","Glycine","Cysteine","Arginine"],"a":3,"e":"Answer: D. Arginine Arginine, a semiessential or conditionally essential amino acid in humans, is one of the most metabolically versatile amino acids. It serves as a precursor for the synthesis of urea, nitric oxide, polyamines, proline, glutamate, creatine, and agmatine.","pyqMatches":[{"year":"2019","no":33,"q":"Urea, creatinine, nitric oxide formed by which amino acid","o":["Histidine","Glycine","Cysteine","Arginine"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1174, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 293, '{"id":1174,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":293,"q":"Which of the following is not the source of cytosolic NADPH ?","o":["Isocitrate dehydrogenase","ATP citrate lyase","Malic enzyme","G6PD"],"a":1,"e":"Answer. B. ATP citrate lyase NADPH is a cofactor used in anabolic reactions, such as lipid and nucleic acid synthesis, which require NADPH as a reducing agent. The major source of NADPH in animals and other non- photosynthetic organisms is the pentose phosphate pathway. The key enzymes in these processes are: NADP-linked malic enzyme, NADP-linked isocitrate dehydrogenase, NADP-linked glutamate dehydrogenase and nicotinamide nucleotide transhydrogenase.","pyqMatches":[{"year":"2012","no":355,"q":"Which of the following is not the source of cytosolic NADPH ?","o":["Isocitrate dehydrogenase","ATP citrate lyase","Malic enzyme","G6PD"],"a":1,"source":"NEET_2012_Paper.pdf"},{"year":"2019","no":34,"q":"Which of the following is not the source of cytosolic NADPH ?","o":["Isocitrate dehydrogenase","ATP citrate lyase","Malic enzyme","G6PD"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2012","2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1175, 'Biochemistry', 'Genetics', 'Moderate', 'Biochemistry', 294, '{"id":1175,"subject":"Biochemistry","chapter":"Genetics","difficulty":"Moderate","source":"Biochemistry","sourceNo":294,"q":"All are true regarding mitochondrial DNA, EXCEPT ?","o":["Double stranded","Inherited from mother","High mutation rate","All respiratory proteins are synthesized within mitochondria itself"],"a":3,"e":"Answer. D. All respiratory proteins are synthesized within mitochondria itself Mt DNA is organized as a circular, covalently closed, double- stranded DNA. In sexual reproduction, mitochondria are normally inherited exclusively from the mother; the mitochondria in mammalian sperm are usually destroyed by the egg cell after fertilization. Mutations of mitochondrial DNA can lead to a number of illnesses including exercise intolerance and Kearns–Sayre syndrome(KSS), which causes a person to lose full function of heart, eye, and muscle movements.","pyqMatches":[{"year":"2019","no":35,"q":"All are true regarding mitochondrial DNA, EXCEPT ?","o":["Double stranded","Inherited from mother","High mutation rate","All respiratory proteins are synthesized within mitochondria itself"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1176, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 295, '{"id":1176,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":295,"q":"Which apolipoprotein is responsible for Alzeihmers disease","o":["APOE4","APOE3","APOE2","APOE1"],"a":0,"e":"ANSWER. A. APOE4 Three common polymorphisms in the APOE gene, e2, e3, and e4, result in single amino changes in the ApoE protein. The e4 allele of apolipoprotein E (APOE) is the major genetic risk factor for Alzheimer’s disease (AD). the differential effects of apoE isoforms on Aß aggregation and clearance play the major role in AD pathogenesis. In particular, APOE e4 is associated with increased risk for AD, whereas APOEe2 is associated with decreased risk.","pyqMatches":[{"year":"2019","no":36,"q":"Which apolipoprotein is responsible for Alzeihmers disease","o":["APOE4","APOE3","APOE2","APOE1"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1177, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 296, '{"id":1177,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":296,"q":"Hyperammonaemia inhibit TCA cycle by depleting?","o":["succinate","a keto glutarate","malate","fumarate"],"a":1,"e":"Answer: B. a keto glutarate The urea cycle and the citric acid cycle are independent cycles but are linked. To detoxify ammonia in hyperammonemia, more glutamate is required. This glutamate is formed from c-ketoglutarate. a-ketoglutarate ?Transamination ?glutamate + NH4+? glutamine. Thus excessive a–ketoglutarate is consumed leading to decrease availability of a–ketoglutarate for TCA cycle","pyqMatches":[{"year":"2019","no":37,"q":"Hyperammonaemia inhibit TCA cycle by depleting?","o":["succinate","a keto glutarate","malate","fumarate"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1178, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 297, '{"id":1178,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":297,"q":"which amino acid is used to synthesise Nitric oxide ?","o":["glycine","arginine","tyrosine","threonine"],"a":1,"e":"ANSWER: B. Arginine Nitric oxide is produced by a group of enzymes called nitric oxide synthases. These enzymes convert arginine into citrulline, producing NO in the process. Oxygen and NADPH are necessary co-factors. three distinct genes encode NOS isozymes: neuronal (nNOS or NOS-1), cytokine-inducible (iNOS or NOS-2) and endothelial(eNOS or NOS-3)","pyqMatches":[{"year":"2019","no":38,"q":"which amino acid is used to synthesise Nitric oxide ?","o":["glycine","arginine","tyrosine","threonine"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1179, 'Biochemistry', 'Genetics', 'Easy', 'Biochemistry', 298, '{"id":1179,"subject":"Biochemistry","chapter":"Genetics","difficulty":"Easy","source":"Biochemistry","sourceNo":298,"q":"Menkes disease is associated with which enzyme deficiency.","o":["lysyl oxidase","Methionine synthase","Glutamyl aminopeptidase","Lysyl hydroxylase"],"a":0,"e":"Answers: A. lysyl oxidase One of the enzymes, lysyl oxidase, requires copper for proper function. This enzyme cross-links tropocollagen into strong collagen fibrils. Menkes disease (MNK), also known as Menkes syndrome, is an X- linked recessive disorder caused by mutations in genes coding for the copper-transport protein ATP7A, leading to copper deficiency. The decreased supply of copper can reduce the activity of numerous copper-containing enzymes. These are necessary for the structure and function of bone, skin, hair, blood vessels and the nervous system such as lysyl oxidase.","pyqMatches":[{"year":"2019","no":39,"q":"Menkes disease is associated with which enzyme deficiency.","o":["lysyl oxidase","Methionine synthase","Glutamyl aminopeptidase","Lysyl hydroxylase"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1180, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 299, '{"id":1180,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":299,"q":"LCAT deficiency increases the following","o":["HDL","LDL","VLDL","Chylomicron"],"a":0,"e":"Answer: A. HDL Lecithin cholesterol acyltransferase deficiency (LCAT deficiency) is a disorder of lipoprotein metabolism. A deficiency of LCAT causes accumulation of unesterified cholesterol in certain body tissues. Cholesterol effluxes from cells as free cholesterol and is transported in HDL as esterified cholesterol. LCAT is the enzyme that esterifies the free cholesterol on HDL to cholesterol ester and allows the maturation of HDL. LCAT is the enzyme that esterifies the free cholesterol on HDL to cholesterol ester and allows the maturation of HDL. LCAT deficiency does not allow for HDL maturation resulting in its rapid catabolism of circulating apoA-1 and apoA-2. The remaining form of HDL resembles nascent HDL.","pyqMatches":[{"year":"2012","no":300,"q":"LCAT deficiency increases the following","o":["HDL","LDL","VLDL","Chylomicron"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2019","no":40,"q":"LCAT deficiency increases the following","o":["HDL","LDL","VLDL","Chylomicron"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2012","2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1181, 'Biochemistry', 'Vitamins & Minerals', 'Hard', 'Biochemistry', 300, '{"id":1181,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Hard","source":"Biochemistry","sourceNo":300,"q":"A 25 year old alcoholic presented with edema,hypertension, ocular disturbance,and changes in mental state was observed, diagnosis of high output cardiac failure was made with Wet Beri Beri, this is due to deficiency of?","o":["Vit B3","Vit B6","Vit B9","Vit B1"],"a":3,"e":"Answer: D. Vit B1 Wet beriberi is the term used for thiamine deficiency with cardiovascular involvement. In the first stage, peripheral vasodilation occurs, leading to a high cardiac output state. This leads to salt and water retention mediated through the renin-angiotensin-aldosterone system in the kidneys. A more rapid form of wet beriberi is termed acute fulminant cardiovascular beriberi, or Shoshin beriberi. The predominant injury is to the heart, and rapid deterioration follows the inability of the heart muscle to satisfy the body’s demands because of its own injury. In this case, edema may not be present. Instead, cyanosis of the hands and feet, tachycardia, distended neck veins, restlessness, and anxiety occur.","pyqMatches":[{"year":"2019","no":41,"q":"A 25 year old alcoholic presented with edema,hypertension, ocular disturbance,and changes in mental state was observed, diagnosis of high output cardiac failure was made with Wet Beri Beri, this is due to deficiency of?","o":["Vit B3","Vit B6","Vit B9","Vit B1"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1182, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 301, '{"id":1182,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":301,"q":"Glutamine is Increase in CSF, blood and urine, this is due to deficiency of","o":["CPS-I","Arginase","OTC","Argininosuccinate synthetase"],"a":0,"e":"Answer: A. CPS-I CPS I deficiency is one of the proximal urea cycle defects and is due to a complete or partial deficiency of the mitochondrial enzyme carbamyl phosphate synthetase I (CPS I) which produces carbamyl phosphate from ammonia, ATP, and HCO3. Carbamoyl phosphate synthetase I (CPS1 or CPSI) transfers an ammonia molecule from glutamine or glutamate to a molecule of bicarbonate that has been phosphorylated by a molecule of ATP. The resulting carbamate is then phosphorylated with another molecule of ATP. The resulting molecule of carbamoyl phosphate leaves the enzyme. CPS-I is the rate limiting (pacemaker) enzyme this pathway. CPS-I is active only in the presence of N-Acetyl Glutamate, an allosteric activator.","pyqMatches":[{"year":"2019","no":42,"q":"Glutamine is Increase in CSF, blood and urine, this is due to deficiency of","o":["CPS-I","Arginase","OTC","Argininosuccinate synthetase"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1183, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 302, '{"id":1183,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":302,"q":"True about type 1 diabetes mellitus","o":["Decreased protein catabolism","Decreased hepatic Glucose output","Increased lipolysis","Increase glucose uptake"],"a":2,"e":"Answer: C. Increased lipolysis Uncontrolled insulin-dependent diabetes mellitus (type I diabetes) involves decreased glucose utilization, with hyperglycemia, and increased fatty acid oxidation. Increased fatty acid oxidation leads to excessive production of acetoacetic and 3-hydroxybutyric acids and of acetone, which are known as ketone bodies.","pyqMatches":[{"year":"2019","no":43,"q":"True about type 1 diabetes mellitus","o":["Decreased protein catabolism","Decreased hepatic Glucose output","Increased lipolysis","Increase glucose uptake"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1184, 'Biochemistry', 'Enzymes', 'Moderate', 'Biochemistry', 303, '{"id":1184,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Moderate","source":"Biochemistry","sourceNo":303,"q":"Protein which is not synthesised In liver is","o":["Phase protein","Immunoglobulins","Albumin","Plasma hormone"],"a":1,"e":"Answer: B. Immunoglobulins The liver serves several metabolic functions within the body including protein synthesis and metabolism. The liver is responsible for an array of proteins. Immunoglobulins are synthesised in plasma cells which are believed to be end products of the differentiation of cells called B- lymphocytes. The liver plays a crucial role in the production of nearly all plasma proteins (albumin, alpha-1-acid glycoprotein, majority of coagulation cascade, and fibrinolytic pathways). Notable exceptions include: globulins, factor III, IV, VIII. Proteins produced by the liver: protein S, protein C, protein Z, plasminogen activator inhibitor, antithrombin III. Vitamin K dependent proteins synthesized by the liver include: Factors II, VII, IX, and X, protein S and C.","pyqMatches":[{"year":"2019","no":44,"q":"Protein which is not synthesised In liver is","o":["Phase protein","Immunoglobulins","Albumin","Plasma hormone"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1185, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 304, '{"id":1185,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":304,"q":"type of cholesterol present in gallstones?","o":["Amorphous cholesterol monohydrate.","Amorphous cholesterol dihydrate.","Crystalline Cholesterol dihydrate.","Crystalline cholesterol monohydrate."],"a":3,"e":"Answer: D. Crystalline cholesterol monohydrate. Gallstones are hardened deposits of digestive fluid that can form in your gallbladder. The most common type of gallstone, called a cholesterol gallstone, often appears yellow in color. These gallstones are composed mainly of undissolved cholesterol. Precipitation of solid cholesterol crystals from supersaturated bile has an essential role in cholesterol gallstone formation. Gallstones are composed principally of cholesterol monohydrate crystals (cholesterol stones) or the acid salt of calcium bilirubinate (pigment stones). When bile is concentrated in the gallbladder, it can become supersaturated with these substances, which then precipitate from the solution as microscopic crystals. The crystals are trapped in gallbladder mucus, producing gallbladder sludge.","pyqMatches":[{"year":"2019","no":45,"q":"type of cholesterol present in gallstones?","o":["Amorphous cholesterol monohydrate.","Amorphous cholesterol dihydrate.","Crystalline Cholesterol dihydrate.","Crystalline cholesterol monohydrate."],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1186, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 305, '{"id":1186,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":305,"q":"collagen present in skin is","o":["Type II","Type I","Type III","Type IV"],"a":1,"e":"Answer: B. Type I Collagen is a protein that is part of cartilage, bone, and other tissues in animals and humans. As the main component of connective tissue, it is the most abundant protein in mammals. Collagen consists of amino acids wound together to form triple- helices l of elongated fibrils.It is, mostly, found in fibrous tissues such as tendons, ligaments, and skin. So far, 28 types of collagen have been identified and described. The five most common types are: Type I: skin, tendon, vasculature, organs, bone (main component of the organic part of bone) Type II: cartilage (main collagenous component of cartilage) Type III: reticulate (main component of reticular fibers), commonly found alongside type I. Type IV: forms basal lamina, the epithelium-secreted layer of the basement membrane. Type V: cell surfaces, hair, and placenta","pyqMatches":[{"year":"2019","no":46,"q":"collagen present in skin is","o":["Type II","Type I","Type III","Type IV"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1187, 'Biochemistry', 'Molecular Biology', 'Moderate', 'Biochemistry', 306, '{"id":1187,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Moderate","source":"Biochemistry","sourceNo":306,"q":"which of the following is not Ribozyme?","o":["Ploy A polymerase","Ribonuclease","Transpeptidase","Peptidyl Transferase"],"a":0,"e":"Answer: A. Ploy A polymerase Polyadenylation is the addition of a poly(A) tail to a messenger RNA. The poly(A) tail consists of multiple adenosine monophosphates; in other words, it is a stretch of RNA that has only adenine bases. polyadenylation is part of the process that produces mature messenger RNA (mRNA) for translation. It, therefore, forms part of the larger process of gene expression.","pyqMatches":[{"year":"2019","no":47,"q":"which of the following is not Ribozyme?","o":["Ploy A polymerase","Ribonuclease","Transpeptidase","Peptidyl Transferase"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1188, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 307, '{"id":1188,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":307,"q":"Type-I hyperlipoproteinemia is characterized by","o":["Elevated LDL","Elevated HDL","Elevated chylomicrons","Elevated lipoprotein lipase"],"a":2,"e":"Answer C. Elevated chylomicrons Lipoprotein lipase deficiency (Type I hyperlipoproteinemia) results in increased level of chylomicrones. Lipoprotein lipase deficiency is a genetic disorder in which a person has a defective gene for lipoprotein lipase, which leads to very high triglycerides, which in turn causes stomach pain and deposits of fat under the skin, and which can lead to problems with the pancreas and liver, which in turn can lead to diabetes. The disorder only occurs if a child acquires the defective gene from both parents (it is autosomal recessive). It is managed by restricting fat in diet to less than 20 g/day. The disease often presents in infancy with colicky pain, failure to thrive, and other symptoms and signs of the chylomicronemia syndrome. The condition has also been called familial chylomicronemia syndrome, chylomicronemia, chylomicronemia syndrome. and hyperlipoproteinem type Ia.","pyqMatches":[{"year":"2019","no":48,"q":"Type-I hyperlipoproteinemia is characterized by","o":["Elevated LDL","Elevated HDL","Elevated chylomicrons","Elevated lipoprotein lipase"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1189, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 308, '{"id":1189,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":308,"q":"In Kreb’s cycle and Urea cycle the linking amino acid is","o":["Fumarate","Alanine","Arginine","Aspartate"],"a":3,"e":"Answer: D. Aspartate Aspartate helps in condensation with citrulline to form argino succinic acid. Arginosuccinic acid undergoes a lytic reaction to form Arginine and fumarate. oxaloacetate , the keto acid obtained from aspartate is intermediate of TCA cycle. Hence aspartate is a common intermediate of TCA cycle through oxaloacetate and urea cycle (directly)","pyqMatches":[{"year":"2019","no":49,"q":"In Kreb’s cycle and Urea cycle the linking amino acid is","o":["Fumarate","Alanine","Arginine","Aspartate"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1190, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 309, '{"id":1190,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":309,"q":"The cofactor vitamin B12 is required for the following conversion:","o":["Dopamine to Norepinephrine","Propionyl CoA to methyl malonyl CoA","Methyl malonyl CoA to succinyl CoA","Cysteine to homocysteine"],"a":2,"e":"Ans: C. Methyl malonyl CoA to succinyl CoA (Ref: Harper 30/e p550, 558, 28ie p346) Vitamin B12 as Cofactor for: Methylmalonyl CoA mutase - Isomerization of methylmalonyl co-A to succinyl co-A. Methionine synthase - Methylation of pyrimidine ring to form thymine. Homocysteine methyl transferase - Methylation of homocysteine to methionine Metabolism of diol. In bacteria for interconversion of glutamate & beta-methyl aspartate°","pyqMatches":[{"year":"2012","no":365,"q":"The cofactor vitamin B12 is required for the following conversion:","o":["Dopamine to Norepinephrine","Propionyl CoA to methyl malonyl CoA","Methyl malonyl CoA to succinyl CoA","Cysteine to homocysteine"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1191, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 310, '{"id":1191,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":310,"q":"Which of the following enzyme activity decreases in fasting?","o":["Hormone sensitive lipase","Glycogen phosphorylase","Acetyl CoA Carboxylase","Phosphofructokinase I"],"a":3,"e":"Ans: D. Phosphofructokinase I Ans: D. Phosphofructokinase I Phosphofructokinase 1 (PFK1) provides the first enzymatic step at which a glucose molecule becomes committed to glycolysis and therefore is subject to regulation (Nelson & Cox, 2008). PFK1 activity depends on the concentrations of AMP, ADP, and ATP with allosteric activation by AMP and ADP and allosteric inhibition by ATP. In the fasting state, glucagon causes the liver to mobilize glucose from glycogen (glycogenolysis) and to synthesize glucose from oxaloacetate and glycerol (gluconeogenesis). Glucagon stimulates an increase in cAMP, leading to an increase in phosphorylation by protein kinase A. The wave of phosphorylation that spreads through the liver cell activates enzymes such as glycogen phosphorylase that are involved in glycogen degradation while simultaneously inhibiting glycogen synthesis. Inhibition of glycogen synthase prevents futile resynthesis of glycogen from glucose 1-phosphate (G1P) via UDP-Glc. Glucose-6- phosphatase (G6Pase), a gluconeogenic enzyme that is present in the liver but not in muscle, then converts G6P to glucose for release into the blood. Ref: Harper''s illustrated biochemistry,3a,ed., pg. I88 and Lippincott''s illustratet! reviewsr 6''t'' ed., pg. 107","pyqMatches":[{"year":"2015","no":340,"q":"Which of the following enzyme activity decreases in fasting?","o":["Hormone sensitive lipase","Glycogen phosphorylase","Acetyl CoA Carboxylase","Phosphofructokinase I"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1192, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 311, '{"id":1192,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":311,"q":"Which micronutrient deficiency causes anemia?","o":["Copper","Molybdenum","Selenium","Flurine"],"a":0,"e":"Ans. is ''a'' i.e., Copper Copper containing protein ceruloplasmin is necessary for transport of iron in the Ferric form across membranes Copper is an integral component of ALA synthase, which is necessary for heme synthesis Copper helps in the uptake of iron across normoblasts","pyqMatches":[{"year":"2012","no":370,"q":"Which micronutrient deficiency causes anemia?","o":["Copper","Molybdenum","Selenium","Flurine"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1193, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 312, '{"id":1193,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":312,"q":"True about sigma factor?","o":["Subunit of 50s ribosome","Subunit of DNA polymerase","Subunit of RNA polymerase","Initiates DNA replication"],"a":2,"e":"Ans- ''C'' Subunit of RNA polymerase The basic DNA-dependent RNA polymerase of the bacterium Escherichia coli exists as an approximately 400-kDa core complex consisting of two identical α subunits, two large β, and β′ subunits, and a ω subunit. The core RNA polymerase, ββ′α2ω, often termed E, associates with a specific protein factor (the sigma [σ] factor) to form holoenzyme, ββ′α2σ, or Eσ. Sigma factors have a dual role in the process of promoter recognition; σ association with core RNA polymerase decreases its affinity for non-promoter DNA, while simultaneously increasing holoenzyme affinity for promoter DNA.","pyqMatches":[{"year":"2015","no":354,"q":"True about sigma factor?","o":["Subunit of 50s ribosome","Subunit of DNA polymerase","Subunit of RNA polymerase","Initiates DNA replication"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1194, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 313, '{"id":1194,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":313,"q":"In ETC, cyanide inhibits ?","o":["Complex I","Cytochrome C oxidase","Complex IV","Complex III"],"a":1,"e":":C Ans. is ''b'' i.e., Cytochrome C oxidase & ''c'' i.e., Complex IV [Ref Harper 29th/e p. 127, 28th/e p. 108, 109; Vasudevan 6th le p. 234] * Complex I :- Barbiturates (amobarbital), piercidin A, rotenone, chlorpromazine, guanithidine. * Complex II :- Carboxin, TTFA, malonate. * Complex III:- Dimercaprol, BAL, actinomycin A, Naphthyloquinone. * Complex IV (cytochrome c oxidase) :- Carbon monoxide (CO), cyanide (CN-), H2S, azide (N'' )","pyqMatches":[{"year":"2012","no":253,"q":"In ETC, cyanide inhibits ?","o":["Complex I","Cytochrome C oxidase","Complex IV","Complex III"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1195, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 314, '{"id":1195,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":314,"q":"HHH syndrome is due to defect in ?","o":["Tryptophan metabolism","Histidine transporter","Branched chain AA metabolism","Ornithine transporter"],"a":3,"e":"Ans. is ''d'' i.e., Ornithine transporter [Ref Textbook of clinical paediatrics p. 496] Hyperornithinaemia, hyperammonaemia, homocitrullinuria (HHH) syndrome is an autosomal recessive disorder of ornithine transport caused by mutations in gene SLC 25A15 encoding the ornithine transorter protein (ORNT1). There is defective activity of the ornithine transporter across the mitochondrial membrane, which causes a functional deficiency of two mitochondrial enzymes: Ornithine transcarbomylase : Which catalyses the condensation of ornithine and carbamoylphosphate to citrulline. Ornithine-8-aminotransferase (OAT) : Which metabolizes the ornithine to .''-pyrroline-5-carboxylate and ultimately glutamate and proline. Ornithine accumulates in the cytoplasm and its deficiency in mitochondria causes a secondary urea cycle disorder and hyperammonemia. Carbamoylphosphate accumulates and undergoes allternate metabolism to form :","pyqMatches":[{"year":"2016","no":292,"q":"HHH syndrome is due to defect in ?","o":["Tryptophan metabolism","Histidine transporter","Branched chain AA metabolism","Ornithine transporter"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1196, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 315, '{"id":1196,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":315,"q":"Earliest symptom of Tay sach disease","o":["Exaggerated startle response","Bone deformation","Hepatomegaly","Excessive bleeding"],"a":0,"e":"Ans. is ''a'' i.e., Exaggerated startle response [Ref Illustrated medical biochemistry p. 330] Tay-Sach disease Clinical symptoms are usually evident in the first year of life Initial signs are not dramatic and present as enfeeblement, spasticity and slow development. An exaggerated startle response to sound may be the most significant early sign of which a parent is aware. Other features are mental retardation, deterioration of vision and early death. \"Affected infants usually develop normally until 4-5 months of age when decreased eye contact and an exaggerated startle response to noise (hyperacusis) are noted.\" ---Nelson. Patients with the infantile form of Tay-Sachs disease have clinical manifestations in infancy including loss of motor skills, increased startle reaction, and macular pallor and retinal cherry-red spots.","pyqMatches":[{"year":"2016","no":1379,"q":"Earliest symptom of Tay sach disease","o":["Exaggerated startle response","Bone deformation","Hepatomegaly","Excessive bleeding"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1197, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 316, '{"id":1197,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":316,"q":"Most important tool used in genetic engineering","o":["Halicase","Topoisomerase","DNA Ligase","Restriction endonuclease"],"a":3,"e":"Ans. is ''d'' i.e., Restriction endonuclease[Ref Satyanarayan p. 579] Genetic engineering simply means manipulation of genetic material to achieve the desired goal in a predetermined way. Most important molecular tools in genetic engineering are enzymes used in recombinant DNA technology. (also called genetic engineering). Most important of these enzymes is restriction endonuclease. At the heart of genetic engineering is the ability to cut DNA molecules at precisely defined sites. This is usually done with purified bacterial enzyme, the restrication endonuclease.","pyqMatches":[{"year":"2015","no":359,"q":"Most important tool used in genetic engineering","o":["Halicase","Topoisomerase","DNA Ligase","Restriction endonuclease"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1198, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 317, '{"id":1198,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":317,"q":"Chromosomal instability syndrome is","o":["Fanconi syndrome","Ataxia Telangectasia","Bloom syndrome","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above [Ref Talwar G P p. 855] Chromosomal instability syndromes are a group of disorders characterized by chromosomal instability and breakage. There are :","pyqMatches":[{"year":"2015","no":423,"q":"Chromosomal instability syndrome is","o":["Fanconi syndrome","Ataxia Telangectasia","Bloom syndrome","All of the above"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1199, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 318, '{"id":1199,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":318,"q":"Vitamin B1 is required for which reaction","o":["Transamination","Oxidative decarboxylation","Carboxylation","All of the above"],"a":1,"e":"Ans. is ''b'' i.e.,Oxidative decarboxylation [Ref Harper 29th/e p. 534] * Active form (coenzyme form) of thiamine is thiamine pyrophosphate (TPP), also called thiamine diphosphate (TDP). * TPP acts as coenzyme for - Oxidative decarboxylation:- Pyruvate dehydrogenase, a- ketoglutarate dehydrogenase, brached-chain keto acid dehydrogenase. - Transketolase in PPP.","pyqMatches":[{"year":"2012","no":366,"q":"Vitamin B1 is required for which reaction","o":["Transamination","Oxidative decarboxylation","Carboxylation","All of the above"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1200, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 319, '{"id":1200,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":319,"q":"Hyperammonemia type-1 is due to deficiency of","o":["Arginase","Arginosuccinate lyase","Arginosuccinate synthase","CPS-1"],"a":3,"e":"Ans. is ''d'' i.e., CPS-1 [Ref Dinesh Puri 3''/e p. 275] Disorders caused by genetic defects of urea cycle enzymes Hyperammonemia type-I Hyperammonemia type-II Citrullinemia Argininosuccinic aciduria Argi ninemia Defective enzyme Carbamoyl phosphate synthase-I Ornithine transcarbamoylase Argininosuccinate synthase Argininosuccinate lyase Arginase Products accumulated Ammonia Ammonia Citrulline Argininosuccinate Arginine.","pyqMatches":[{"year":"2012","no":331,"q":"Hyperammonemia type-1 is due to deficiency of","o":["Arginase","Arginosuccinate lyase","Arginosuccinate synthase","CPS-1"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1201, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 320, '{"id":1201,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":320,"q":"Major site of protein glycosylation is ?","o":["ER and golgi body","Ribosome and golgi body","ER and ribosome","Ribosome and cytoplasm"],"a":0,"e":"Ans. is ''a'' i.e., ER and golgi body [Ref Harper 28aVe p. 514, 515; Lippincotts 5thle p. 167,168] N- Glycosylation occurs in ER and O-glycosylation occurs in golgi apparatus.","pyqMatches":[{"year":"2013","no":242,"q":"Major site of protein glycosylation is ?","o":["ER and golgi body","Ribosome and golgi body","ER and ribosome","Ribosome and cytoplasm"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1202, 'Biochemistry', 'Molecular Biology', 'Moderate', 'Biochemistry', 321, '{"id":1202,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Moderate","source":"Biochemistry","sourceNo":321,"q":"Which is not a step of PCR ?","o":["Annealing","Extension","Transformation","Denaturation"],"a":2,"e":"Ans. is ''c'' i.e., Transformation [Ref Lippincott'' s 5thle p. 479-83; Harper 28th/e p. 395] Steps in PCR Isolation of target DNA sequence→ Primer construction → Denaturation of DNA→ Annealing of primers to single stranded DNA→ Chain extension.","pyqMatches":[{"year":"2014","no":350,"q":"Which is not a step of PCR ?","o":["Annealing","Extension","Transformation","Denaturation"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1203, 'Biochemistry', 'Molecular Biology', 'Moderate', 'Biochemistry', 322, '{"id":1203,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Moderate","source":"Biochemistry","sourceNo":322,"q":"Which does not play a role in protein synthesis?","o":["Exon","Intron","m-RNA","ATP"],"a":1,"e":"Ans. is ''b'' i.e., Intron [Ref Lippincott''s 5tve p. 426] Primary transcript contains introns & exons. Splicing removes introns (segment of gene that is not represented in mature m-RNA) from primary transcript. Synthesis of protein from mRNA is called translation. Translation is the process by which ribosomes convert the information (genetic code) carried by mRNA to the synthesis of new protein. Translation occurs in ribosomes. Basic requirements for translation include mRNA, tRNAs, ribosomes, energy (ATP and GTP), enzymes, and specific protein factors like initiation factors, elongation factors etc.","pyqMatches":[{"year":"2012","no":391,"q":"Which does not play a role in protein synthesis?","o":["Exon","Intron","m-RNA","ATP"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1204, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 323, '{"id":1204,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":323,"q":"Pyridoxine deficiency leads to altered metabolism of?","o":["Phenylalanine","Tryptophan","Methionine","Tyrosine"],"a":1,"e":"Ans. is ''b'' i.e., Tryptophan [Ref Dineshpuri 3rd le p. 378] Tryptophan load test is used for pyridoxin. In pyridoxin (vitamin B6) deficiency, xanturenic acid excretion is increased after giving tryptophan load dose.","pyqMatches":[{"year":"2012","no":367,"q":"Pyridoxine deficiency leads to altered metabolism of?","o":["Phenylalanine","Tryptophan","Methionine","Tyrosine"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1205, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 324, '{"id":1205,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":324,"q":"Kcat/km is a measure of -","o":["Enzyme efficiency","Speed of enzymatic reaction","Concentration of substrate","Enzyme turn over"],"a":3,"e":"Answer-D. Enzyme efficiency \"The Km of an enzyme is the concentration of the substrate that enables the enzyme to Function at half maximum activity and is therefore a measure of the specificity of a substrate for the enzyme\" . Actually enzyme specificity is not measured by alone. It is measured by the ratio Kcat /Km which is a second order rate constant for the reaction between substrate and free enzyme. This ratio is important, for it provides a direct measure of enzyme eficiency and specificity. Note: Km, is turnover number and measures tJre rate of the catalytic process","pyqMatches":[{"year":"2013","no":248,"q":"Kcat/km is a measure of","o":["Enzyme efficiency","Speed of enzymatic reaction","Concentration of substrate","Enzyme turn over"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1206, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 325, '{"id":1206,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":325,"q":"Enzyme involved in the transfer of hydrogen ion is","o":["Hydratase","Oxidase","Peroxidase","Dehydrogenase"],"a":1,"e":":D Ans. is ''b'' i.e., Oxidase & ''d'' i.e., Dehydrogenase [Ref Harper 30th/e p. 198; Vasudevan 5th/e p. 210] Enzyme involved in oxidation-reaction are :? Cause removal of hydrogen Dehydrogenases : Use NAD or FAD as acceptor Oxidases : Use oxgen as acceptor, Add oxygen Oxygenases","pyqMatches":[{"year":"2016","no":239,"q":"Enzyme involved in the transfer of hydrogen ion is","o":["Hydratase","Oxidase","Peroxidase","Dehydrogenase"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1207, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 326, '{"id":1207,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":326,"q":"Which of the following is a constitutive enzyme?","o":["Hexokinase","Glucokinase","p galactosidase","Cyclooxygenase-2"],"a":0,"e":"Ans. is ''a'' i.e.,Hexokinase","pyqMatches":[{"year":"2016","no":240,"q":"Which of the following is a constitutive enzyme?","o":["Hexokinase","Glucokinase","p galactosidase","Cyclooxygenase-2"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1208, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 327, '{"id":1208,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":327,"q":"Sequence of complexes in the electron transport chain is -","o":["NADH dehydrogenase → Q → Cytochrome bc1 → Cytochrome aa3 → O,","NADH dehydrogenase → Q → Cytochrome aa3 → Cytochrome bcl→ O,","NADH dehydrogenase → Cytochrome aa3 → Q → Cytochrome bcl→ O,","NADH dehydrogenase → Cytochrome bcl → Q → Cytochrome aa3 → O,"],"a":0,"e":"Ans. is ''a'' i.e., NADH dehydrogenase → Q → Cytochrome bcl → Cytochrome aa3→ 02 Electron transport chain is made up of 5 stationary complexes and 2 mobile complexes","pyqMatches":[{"year":"2016","no":241,"q":"Sequence of complexes in the electron transport chain is","o":["NADH dehydrogenase → Q → Cytochrome bc1 → Cytochrome aa3 → O,","NADH dehydrogenase → Q → Cytochrome aa3 → Cytochrome bcl→ O,","NADH dehydrogenase → Cytochrome aa3 → Q → Cytochrome bcl→ O,","NADH dehydrogenase → Cytochrome bcl → Q → Cytochrome aa3 → O,"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1209, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 328, '{"id":1209,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":328,"q":"Regarding energy production by the electron transport chain, which is true?","o":["The complexes are arranged in a decreasing order of redox potential","The complexes are arranged in a decreasing order of ability to get reduced","The complexes are arranged in a decreasing order of state of oxidation","The complexes are arranged in a decreasing order of energy level"],"a":3,"e":"Ans. is ''d'' i.e., The complexes are arranged in a decreasing order of energy level [Ref Essential of biochemistry p. 712] ETC help in ATP generation It is explained by Mitchell''s chemiosmotic theory. According to this theory, the complexes are arranged in an increasing order of redox potential. Redox potential is a measure of ability to get reduced. So the complexes are arranged in an increasing order of ability to get reduced. As more a substance is oxidised higher will be the ability to get reduced, the complexes are arranged in an increasing order of state of oxidation. As state of oxidation is inversely proportional to energy level, the complexes are arranged in a decreasing order of energy level. So, when electrons move from one complex to another, it means electrons move from a complex of high energy to a complex of low energy and that liberates energy. This energy is used for pumping hydrogen ions from the mitochondrial matrix to just outside the inner mitochondrial membrane. After hydrogen ions accumulate outside the inner mitochondrial membrane, hydrogen ions go through FO Component of ATP synthase.","pyqMatches":[{"year":"2016","no":242,"q":"Regarding energy production by the electron transport chain, which is true?","o":["The complexes are arranged in a decreasing order of redox potential","The complexes are arranged in a decreasing order of ability to get reduced","The complexes are arranged in a decreasing order of state of oxidation","The complexes are arranged in a decreasing order of energy level"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1210, 'Biochemistry', 'Molecular Biology', 'Moderate', 'Biochemistry', 329, '{"id":1210,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Moderate","source":"Biochemistry","sourceNo":329,"q":"Electron transport chain all are true except","o":["Complexes are arranged in an increasing order of redox potential;","Mitochondrial Glycerol phosphate dehydrogenase sends its electron directly to Q","l0 Hydrogen ions are translocated when NADH enters into an electron transport chain","7 Hydrogen ions are translocated when FADH2 electrons get into electron transport chain."],"a":3,"e":"Ans. is ''d'' i.e., 7 Hydrogen ions are translocated when FADH2 electrons get into electron transport chain NADH electrons get into electron transport chain through complex I. Energy difference between NADH and Q is in such a way that when electrons move from complex I to Q, 4 hydrogen ions get translocated. Similarly 4 ions get translocated when electrons move from Q to complex III and 2 1-1'' ions get translocated when electrons move from complex III to IV. So totally 10 1-1+ ions get translocated when electrons from NADH get into electron transport chain. Complex V or ATP synthase complex works in such a way that when 10 H* ions go through F0 component, 1 ATP is generated. So when 10 Hydrogen ions are translocated, 2.5 ATPs can be generated. FADH, electrons get into electron transport chain through either complex II or they directly get into Q, in either case, no energy is liberated. No hydrogen ions are translocated. When electrons move from Q to Complex III, 4 hydrogen ions and when electrons move from III to IV 2 hydrogen ions are translocated. So totally 6 hydrogen ions are translocated when FADH2 gets into electron transport chain. ATP synthase complex generates 1 ATP for every 4 hydrogen ions translocated through F, component. So for 6 hydrogen ions, it is 1.5 ATP","pyqMatches":[{"year":"2016","no":243,"q":"Electron transport chain all are true except","o":["Complexes are arranged in an increasing order of redox potential;","Mitochondrial Glycerol phosphate dehydrogenase sends its electron directly to Q","l0 Hydrogen ions are translocated when NADH enters into an electron transport chain","7 Hydrogen ions are translocated when FADH2 electrons get into electron transport chain."],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1211, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 330, '{"id":1211,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":330,"q":"Which of the following is the respiratory centre of cell?","o":["Mitochondria","Microsome","Lysosome","Nucleus"],"a":0,"e":"Ans. is ''a'' i.e., Mitochondria As mitochondria harbours the electron transport chain. In electron transport chain, the electrons from NADH and FADH2 are transferred through the various complexes to finally Oxygen. Oxygen is then converted to water. This way all fuels get oxidised to Carbondioxide. In other words in miotochondria, Oxygen is utilised and Carbon dioxide generation is supported. Hence it is called as the respiratory centre of the cell.","pyqMatches":[{"year":"2016","no":245,"q":"Which of the following is the respiratory centre of cell?","o":["Mitochondria","Microsome","Lysosome","Nucleus"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1212, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 331, '{"id":1212,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":331,"q":"Cellulose is biochemically -","o":["β (1,4) L glucose","?, (14) D glucose","β(1,4) D glucose","? (1,4) L glucose"],"a":0,"e":"Ans. is ''a'' i.e., β (1,4) L glucose Cellulose is a component of cell wall. Cellulose is a structural homopolysaccharide made up of glucose molecules linked by 13(1,4) linkages. Humans cannot digest cellulose because human digestive enzymes cannot break 43(1,4) linkages present in oligosaccharides and polysaccharides. This is why vegetarian diet is considered to provide fibre to the diet.","pyqMatches":[{"year":"2016","no":246,"q":"Cellulose is biochemically","o":["β (1,4) L glucose","?, (14) D glucose","β(1,4) D glucose","? (1,4) L glucose"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1213, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 332, '{"id":1213,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":332,"q":"D and L isomerism is -","o":["Optical isomerism","Functional isomerism","Epimerism","Enantiomerism"],"a":3,"e":"Ans. is d.i.e., Enantiomerism Enantiomerism is a type of stereoisomerism in which two molecules have the same molecular formula and the same structural formula but they differ in spatial orientation with respect to all the carbon atoms and they are named based on the orientation in the penultimate carbon atom. In the penultimate carbon atom, if OH is on the right side, it is D form, if OH is on the left side, it is L form. The other name for enantiomerism is Racemism.","pyqMatches":[{"year":"2016","no":247,"q":"D and L isomerism is","o":["Optical isomerism","Functional isomerism","Epimerism","Enantiomerism"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1214, 'Biochemistry', 'Miscellaneous', 'Moderate', 'Biochemistry', 333, '{"id":1214,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Biochemistry","sourceNo":333,"q":"All of the following are converted to cr-ketoglutarate on catabolism except-","o":["Glutamate","Histidine","Proline","Glycine"],"a":3,"e":"Ans. is ''d'' i.e., Glycine [Ref Harper 30th/e p. 162, 250/e p. 166, 167]","pyqMatches":[{"year":"2016","no":249,"q":"All of the following are converted to cr-ketoglutarate on catabolism except","o":["Glutamate","Histidine","Proline","Glycine"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1215, 'Biochemistry', 'Miscellaneous', 'Moderate', 'Biochemistry', 334, '{"id":1215,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Biochemistry","sourceNo":334,"q":"Glucogenic aminoacids give rise to all of the following intermediates of citric acid cycle except-","o":["Isocitrate","c ketoglutarate","Succinyl CoA","Fumarates"],"a":0,"e":"Ans. is ''a'' i.e., Isocitrate","pyqMatches":[{"year":"2016","no":250,"q":"Glucogenic aminoacids give rise to all of the following intermediates of citric acid cycle except","o":["Isocitrate","c ketoglutarate","Succinyl CoA","Fumarates"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1216, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 335, '{"id":1216,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":335,"q":"What is the precursor of proline in Krebs cycle?","o":["Oxaloacetate","c ketoglutarate","Succinyl CoA","Fumarates"],"a":1,"e":"Ans. is ''b'' i.e., c ketoglutarate [Ref Essentials of Biochemistry p. 232; Harper 29`''/e p. Proline is an alpha aminoacid with a pyrrolidine ring It is a non polarimino acid with NH as one of its functional groups It disrupts a helix It is a nonessential amino acid and is synthesized from a non- essential aminoacid glutamate Glutamate in the presence of y glutamate kinase gets converted to glutamate 5 phosphate, which in the presence of y glutamate dehydrogenase gets converted to y glutamate semialdehyde. y glutamate semialdehyde spontaneously cyclises to form y pyrroline carboxylate which in the presence of reductase forms proline","pyqMatches":[{"year":"2016","no":251,"q":"What is the precursor of proline in Krebs cycle?","o":["Oxaloacetate","c ketoglutarate","Succinyl CoA","Fumarates"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1217, 'Biochemistry', 'Enzymes', 'Moderate', 'Biochemistry', 336, '{"id":1217,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Moderate","source":"Biochemistry","sourceNo":336,"q":"used in citric acid cycle are all except-","o":["NAD","FAD","NADP","GDP"],"a":2,"e":"Ans. C. NADP Enzyme Reducing equivalentATP Isocitrate dehydrogenase 1 NADH 2.5 alpha ketoglutarate dehydrogenase 1 NADH 2.5 Succinyl CoA ATP/GTP 1 Succinate dehydrogenase FADH2 1.5 Malate dehydrogenase NADH 2.5 total 10","pyqMatches":[{"year":"2016","no":252,"q":"used in citric acid cycle are all except","o":["NAD","FAD","NADP","GDP"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1218, 'Biochemistry', 'Miscellaneous', 'Moderate', 'Biochemistry', 337, '{"id":1218,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Biochemistry","sourceNo":337,"q":"All of the following steps act as sources of energy in citric acid cycle except -","o":["Citrate synthase","Isocitrate dehydrogenase","Succinyl Thiokinase","Succinate Dehydrogenase"],"a":0,"e":"Ans. is ''a'' i.e.,Citrate synthase","pyqMatches":[{"year":"2016","no":253,"q":"All of the following steps act as sources of energy in citric acid cycle except","o":["Citrate synthase","Isocitrate dehydrogenase","Succinyl Thiokinase","Succinate Dehydrogenase"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1219, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 338, '{"id":1219,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":338,"q":"True about glucokinase is -","o":["It is present in all cells","It is a constitutive enzyme","It has a high km","It is inhibited by glucose 6 phosphate"],"a":2,"e":"Ans. is ''c'' i.e.,It has a high km S. No. Property Hexokinase Glucokinase 1 Location All cells Liver and Pancreatic (3 cells 2 Affinity High Low 3 Km Low High 4 Inhibition by glucose 6 phosphate Yes No 5 Induction by Insulin No (Constitutive enzyme) Yes (Inducible Enzyme)","pyqMatches":[{"year":"2016","no":254,"q":"True about glucokinase is","o":["It is present in all cells","It is a constitutive enzyme","It has a high km","It is inhibited by glucose 6 phosphate"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1220, 'Biochemistry', 'Carbohydrate Metabolism', 'Moderate', 'Biochemistry', 339, '{"id":1220,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":339,"q":"All of the following are true about lactate utilisation in liver except -","o":["Total net number of ATP formed because of cori''s cycle is 6","Cori''s cycle shifts the metabolic burden from muscle to liver","Cori''s cycle can not be sustained indefinitely because it is energetically unfavourable","Cori''s cycle is linked to glycogen synthesis in muscle"],"a":0,"e":"Ans. is ''a'' i.e., Total net number of ATP formed because of coil''s cycle is 6 CORI''S CYCLE Muscle uses a molecule of glucose through anaerobic glycolysis and gets 2 ATPs. In this process, glucose becomes two molecules of lactate. The 2 lactate molecules through circulation reach liver. In liver, the two molecules of lactate are utilised through gluconeogenesis to form a glucose molecule at the expense of 6 ATPs. The glucose formed in liver reaches muscle and is utilised for again anaerobic glycolysis if the muscle is still exercising. In case muscle is done with exercising, the glucose which reaches the muscle from liver is used for glycogen synthesis.","pyqMatches":[{"year":"2016","no":255,"q":"All of the following are true about lactate utilisation in liver except","o":["Total net number of ATP formed because of cori''s cycle is 6","Cori''s cycle shifts the metabolic burden from muscle to liver","Cori''s cycle can not be sustained indefinitely because it is energetically unfavourable","Cori''s cycle is linked to glycogen synthesis in muscle"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1221, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 340, '{"id":1221,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":340,"q":"Which of the following is true about effect of insulin and glucagon on gluconeogenesis?","o":["Insulin favours the formation of fructose 2,6 bisphosphate","Fructose 2, 6 bisphosphate is an inhibitor of glycolysis","Insulin acts through a kinase","Glucagon stimulates PFK.2 activity of the tandem enzyme"],"a":0,"e":"Ans. is ''a'' i.e., Insulin favours the formation of fructose 2,6 bisphosphate Glycolysis and gluconeogenesis are reversal of each other. Hence the two pathways should be regulated in such a way that when one pathway is active, the other one has to be inactive. Otherwise they will end up in futile cycles.","pyqMatches":[{"year":"2016","no":256,"q":"Which of the following is true about effect of insulin and glucagon on gluconeogenesis?","o":["Insulin favours the formation of fructose 2,6 bisphosphate","Fructose 2, 6 bisphosphate is an inhibitor of glycolysis","Insulin acts through a kinase","Glucagon stimulates PFK.2 activity of the tandem enzyme"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1222, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 341, '{"id":1222,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":341,"q":"In glycogen synthesis the active form of glucose used is-","o":["Glucose 6 phosphate","Glucose I phosphate","UDP glucose","UTP glucose"],"a":2,"e":"Ans. is ''c'' i.e., UDP glucose Glycogen synthesis occurs in liver and Skeletal Muscle UDP glucose is the active form of glucose which gets added to the growing glycogen The number of high energy phosphates required for attaching a glucose molecule to growing glycogen is 3 The rate limiting enzyme of glycogen synthesis is glycogen synthase Glycogen synthase gets activated by dephosphorylation Glycogen synthase attaches glucose residues one by one along a straight chain, linked by a(1,4) linkages. This continues until 11 to 13 residues are attached in a straight chain. At branch points in glycogen, a(1,6) linkages should be formed.","pyqMatches":[{"year":"2016","no":258,"q":"In glycogen synthesis the active form of glucose used is","o":["Glucose 6 phosphate","Glucose I phosphate","UDP glucose","UTP glucose"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1223, 'Biochemistry', 'Carbohydrate Metabolism', 'Moderate', 'Biochemistry', 342, '{"id":1223,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":342,"q":"Neonatal hypoglycaemia which does not respond to counter regulatory hormone administration is diagnostic of -","o":["Her''s disease","Cori''s disease","Anderson''s disease","Von Gierke''s disease"],"a":3,"e":"Ans. is ''d'' i.e.,Von Gierke''s disease Glycogen storage disorders presenting with hypoglycaemia are Type I (Von Gierke''s disease), Type III (Cori''s disease or Forbe''s disease), Type VI (Her''s disease), Type IX (Fanconi Bickel syndrome) The only Glycogen storage disorder which presents as hypoglycaemia not responding to counter regulatory hormone administration is Von Gierke''s disease Muscle involvement is not a feature of Type I(Von Gierke''s disease), Type IV (Andersoen disease), Type VI (Her''s disease), Type IX (Fanconi Bickel syndrome) Andersen disease or Type IV is the only glycogen storage disease which presents with neither hypoglycaemia nor with muscle involvement. It presents as hepatomegaly and cirrhosis","pyqMatches":[{"year":"2016","no":260,"q":"Neonatal hypoglycaemia which does not respond to counter regulatory hormone administration is diagnostic of","o":["Her''s disease","Cori''s disease","Anderson''s disease","Von Gierke''s disease"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1224, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 343, '{"id":1224,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":343,"q":"Which of the following is a transfatty acid?","o":["Oleic acid","Elaidic acid","Stearic acid","Arachidonic acid"],"a":1,"e":"Ans. is ''b'' i.e., Elaidic acid [Ref Harper 30\"/e p. 213] There are two types of fatty acids : Saturated Unsaturated Cis - trans isomerism is for unsaturated fatty acids. Stearic acid is a saturated fatty acid (No cis-trans isomerism) Only important unsaturated trans-fatty acid is Elaidic acid (trans-9- octadecenoic)","pyqMatches":[{"year":"2016","no":263,"q":"Which of the following is a transfatty acid?","o":["Oleic acid","Elaidic acid","Stearic acid","Arachidonic acid"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1225, 'Biochemistry', 'Miscellaneous', 'Moderate', 'Biochemistry', 344, '{"id":1225,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Biochemistry","sourceNo":344,"q":"Activators of Acetyl CoA carboxylase are all except","o":["Acyl coA","Citrate","Glutamate","Dicarboxylic acid"],"a":0,"e":"Ans. is ''a'' i.e., Acyl CoA [Ref Harper 29thle p. 217, 220] Allosteric modulation of acetyl CoA carboxylase","pyqMatches":[{"year":"2016","no":264,"q":"Activators of Acetyl CoA carboxylase are all except","o":["Acyl coA","Citrate","Glutamate","Dicarboxylic acid"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1226, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 345, '{"id":1226,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":345,"q":"Arachidonic acid oxidation involves how many cycles of beta oxidation?","o":["l0","20","9","8"],"a":2,"e":"Ans. is ''c'' i.e., 9 Number of acetyl CoA formed in (3-oxidation of fatty acids = Number of carbon atoms/2. Number of cycles of (beta-oxidation required -No of carbon / 2(-1) Hence arachidonic acid with 20 carbon atoms undergoes p oxidation to form 10 acetyl CoA by going through (20/2) - 1 cycles i.e., 9 cycles.","pyqMatches":[{"year":"2016","no":265,"q":"Arachidonic acid oxidation involves how many cycles of beta oxidation?","o":["l0","20","9","8"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1227, 'Biochemistry', 'Lipid Metabolism', 'Moderate', 'Biochemistry', 346, '{"id":1227,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":346,"q":"All are true about beta oxidation of fatty acids except -","o":["Carnitine acyl transferase I is the rate limiting enzyme of fatty acid oxidation","Carnitine acyl transferase I is stimulated by Acyl CoA","Carnitine Acyl transferase I is stimulated by malonyl CoA","Carnitine Acyl transferase I defect causes a decrease in acylcarnitine levels"],"a":2,"e":"Ans. is ''c'' i.e., Carnitine Acyl transferase I is stimulated by malonyl CoA As CATI is the rate limiting enzyme of fatty acid oxidation, its substrate is acyl CoA. As we know that all enzymes get stimulated by their substrates, acyl CoA stimulates CATI. Malonyl CoA is a product of acetyl CoA carboxylase (ACC). ACC is the rate limiting enzyme of fatty acid synthesis, an anabolic pathway. So, malonyl CoA is an intermediate of anabolic pathway. Hence it is a signal of high energy (Anabolism happens only in high energy status). When the energy is already high, we do not want fatty acids to be further oxidised. We want fatty acids to be only stored. So, malonyl CoA, a signal of high energy inhibits CATI. In short, anything which signals low energy stimulates fatty acid oxidation (CATI). So, ADP, NAD, FAD, Glucagon , Acyl CoA stimulate fatty acid oxidation Anything which signal high energy inhibit fatty acid oxidation. So, ATP, NADH, FADH2, Insulin and malonyl CoA inhibit fatty acid oxidation. Fatty acid oxidation defects present as non ketotic hypoglycaemia, hyperammonemia, dicarboxylic aciduria. And all fatty acid oxidation defects also present with increase in acyl carnitine levels. One exception is CATI defect. In CATI defect, as acyl CoA is not converted to acyl Carnitine, free carnitine levels are high and acyl carnitine levels are low.","pyqMatches":[{"year":"2016","no":266,"q":"All are true about beta oxidation of fatty acids except","o":["Carnitine acyl transferase I is the rate limiting enzyme of fatty acid oxidation","Carnitine acyl transferase I is stimulated by Acyl CoA","Carnitine Acyl transferase I is stimulated by malonyl CoA","Carnitine Acyl transferase I defect causes a decrease in acylcarnitine levels"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1228, 'Biochemistry', 'Lipid Metabolism', 'Moderate', 'Biochemistry', 347, '{"id":1228,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":347,"q":"AII are true about beta oxidation of fats acids except -","o":["Occurs in mitochondria","Occurs in peroxisome","Results in hydrogen peroxide generation","Fatty acid oxidation defects present with ketosis"],"a":3,"e":"Ans. is ''d'' i.e., Fatty acid oxidation defects present with ketosis Fatty acid oxidation defect causes non-ketotic hypoglycemia. Fatty acid oxidation happens in mitochondria and in peroxisomes. The difference between mitochondrial oxidation and peroxisomal oxidation is that in mitochondria, when the 13 carbon atom is oxidised, the hydrogen atoms are removed. Those hydrogen atoms are used for reducing NAD and FAD to form NADH and FADH2. NADH and FADH2 enter into electron transport chain to form ATP. In peroxisome, the hydrogen atom removed from (3 carbon atom is used to reduce 02 forming F1202. Only because 11202 is formed in peroxisome by (beta oxidation the organism is called so)","pyqMatches":[{"year":"2016","no":267,"q":"AII are true about beta oxidation of fats acids except","o":["Occurs in mitochondria","Occurs in peroxisome","Results in hydrogen peroxide generation","Fatty acid oxidation defects present with ketosis"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1229, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 348, '{"id":1229,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":348,"q":"Which of the following is true about Beta oxidation of fatty acids?","o":["Stearic acid on oxidation provides 106 ATPs","Odd chain fatty acid oxidation provides only propionyl coA","Fatty acid oxidation defects cause hypoglycemia","Ketone bodies are formed by incomplete oxidation of fatty acid during starvation to increase energy production"],"a":2,"e":"Ans. is ''c'' i.e., Fatty acid oxidation defects cause hypoglycaemia Defect in fatty acid oxidation causes hypoglycemia. About other options Stearic acid oxidation produces 122 ATPs. Even chain fatty acids are (3-oxidized to acetyl CoA. Odd chain fatty acids are also (3-oxidized normally but the last step produces a 3- carbon propionyl CoA along with an acetyl CoA (instead of 2 molecules acetyl CoA that occurs in even chain fatty acids). Ketone body formation (ketogenesis) occurs when there is a high rate of fatty acid oxidation in liver which provides excessive acetyl CoA, substrate for ketogenesis. When ketone bodies are formed, as we can''t expect the 10 ATPs which we get from every acetyl CoA through citric acid cycle, the formula for energetics of incomplete oxidation of fatty acids is :","pyqMatches":[{"year":"2016","no":268,"q":"Which of the following is true about Beta oxidation of fatty acids?","o":["Stearic acid on oxidation provides 106 ATPs","Odd chain fatty acid oxidation provides only propionyl coA","Fatty acid oxidation defects cause hypoglycemia","Ketone bodies are formed by incomplete oxidation of fatty acid during starvation to increase energy production"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1230, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 349, '{"id":1230,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":349,"q":"Which of the following is true about properties of VLDL/LDL-","o":["In electrophoresis, VLDL migrates more cathodal than LDL","LDL is formed from liver","LDL is formed from Chylomicron","VLDL remnants reach extrahepatic tissues"],"a":1,"e":"Ans. is ''b'' i.e., LDL is formed from liver Lipoprotein electrophoresis of a fasting sample shows three bands - HDL, VLDL, LDL in that order from anode to cathode. VLDL is synthesized in liver that contains high triglyceride, ChE, cholesterol, phospholipid and Apo B-100. (VLDL particles resemble chylomicrones in composition except that VLDL contains Apo B-100 instead of Apo B-48). VLDL particles are secreted in the plasma and as with chylomicron, Apo E and Apo C are transferred from HDL to VLDL. Now VLDL contains Apo B-100, Apo E and Apo C. In plasma, triglycerides of VLDL are hydrolysed by same lipoprotein lipase (see above) and apo C is transferred to HDL and the remmants are called IDL. 40-60% of IDL is removed by liver via LDL receptor mediated endocytosis, this process require Apo E which acts as ligand for LDL receptors. Remaining IDL is remodeled by hepatic (liver) lipase which hydrolyzes more triglyceride to form LDL that contains maximum cholesterol. 70% of LDL is removed by liver via LDL receptor and 30% is utilized by peripheral tissues as a source of cholesterol.","pyqMatches":[{"year":"2016","no":269,"q":"Which of the following is true about properties of VLDL/LDL","o":["In electrophoresis, VLDL migrates more cathodal than LDL","LDL is formed from liver","LDL is formed from Chylomicron","VLDL remnants reach extrahepatic tissues"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1231, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 350, '{"id":1231,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":350,"q":"Reverse cholesterol transport - all are true except-","o":["Transport of cholesterol from extrahepatic tissues to liver","ATP Binding Cassette Transporter protein is involved in the conversion of HDL3 to HDL2","Lecithin Cholesterol Acyl Transferase helps in the conversion of Spheroidal HDL to Discoidal HDL","Cholesterol Ester Transfer Protein helps in increasing HDL level"],"a":3,"e":"Ans. is ''d'' i.e., Cholesterol Ester Transfer Protein helps in increasing HDL level Reverse Cholesterol Transport is the transport of Cholesterol ester and phospholipid from extrahepatic tissues to liver. HDL is released by both liver and intestinal cells. In both the cases, they are released as discoidal HDL Apo Al activates Lecithin Cholesterol Acyl Transferase and it converts discoidal HDL to Spheroidal HDL (HDL3) HDL3 activates ABC1 (ATP Binding Casette Transporter 1) to collect cholesterol and phospholipids from extra hepatic tissue membranes. This way HDL3 size increases and density decreases. Hence it forms HDL2. This HDL2 reaches liver to empty its contents into liver. On the way to liver, if HDL2 encounters IDL, Cholesterol Ester Transfer Protein (CETP) transfers Choelsterol ester from HDL2 to IDL, converting IDL to LDL. Hence CETP decreases HDL level and increases LDL level.","pyqMatches":[{"year":"2016","no":270,"q":"Reverse cholesterol transport - all are true except","o":["Transport of cholesterol from extrahepatic tissues to liver","ATP Binding Cassette Transporter protein is involved in the conversion of HDL3 to HDL2","Lecithin Cholesterol Acyl Transferase helps in the conversion of Spheroidal HDL to Discoidal HDL","Cholesterol Ester Transfer Protein helps in increasing HDL level"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1232, 'Biochemistry', 'Clinical Biochemistry', 'Easy', 'Biochemistry', 351, '{"id":1232,"subject":"Biochemistry","chapter":"Clinical Biochemistry","difficulty":"Easy","source":"Biochemistry","sourceNo":351,"q":"True about coproporphyrin I and coproporphyrin III is -","o":["Coproporphyrin I is excreted in urine","Coproporphyrin III is excreted in bile","In Dubin Johnson Syndrome, Coproporphyrin I in urine is 80% of the total coproporphyrin","In Dubin Johnson Syndrome, total coproporphyrin levels is elevated"],"a":2,"e":"Ans. is ''c'' i.e., In Dubin Johnson Syndrome, Coproporphyrin I in urine is 80% of the total coproporphyrin Coproporphyrins are intermediates of heme synthesis Normally coproporphyrin I is excreted in bile and is lost in feces Coproporphyrin III is excreted in urine Hence in normal urine Coproporphyrin I is 25% of total coproporphyrin levels in urine Dubin Johson syndrome, is a form of conjugated hyperbilirubinemia and is caused by a defect of Multi Drug Resistant Protein 2 (MRP-2), which is responsible for secreting bile components (conjugated bile pigments) from hepatocytes into biliary canaliculi. In this disorder, the ratio of Coproporphyrin I : Coproporphyrin III is reversed and coproporhyrin I is more than 80% of the total Coproporphyrin levels. But the total coproporphyrin levels is normal. Possible mechanism is Coproporphyrin I is secreted into bile through MRP-2.","pyqMatches":[{"year":"2016","no":353,"q":"True about coproporphyrin I and coproporphyrin III is","o":["Coproporphyrin I is excreted in urine","Coproporphyrin III is excreted in bile","In Dubin Johnson Syndrome, Coproporphyrin I in urine is 80% of the total coproporphyrin","In Dubin Johnson Syndrome, total coproporphyrin levels is elevated"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1233, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 352, '{"id":1233,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":352,"q":"Synthetic oxygen carrier is ?","o":["2,4 dinitrophenol","Chloflurocarbon","Perflurocarbon","1 fluro 2,4 dinitrophenol"],"a":1,"e":"Ans. is ''b'' i.e., Chloflurocarbon Blood doping is a form of fraudulent increase in the oxygen carrying capacity of a person, widely used to improve the aerobic capacity of athletes This is done by various methods Autologous blood transfusion Homologous blood transfusion Erythropoietin or Continuous Erythropoietin Receptor Activator","pyqMatches":[{"year":"2016","no":348,"q":"Synthetic oxygen carrier is ?","o":["2,4 dinitrophenol","Chloflurocarbon","Perflurocarbon","1 fluro 2,4 dinitrophenol"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1234, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 353, '{"id":1234,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":353,"q":"Abetalipoproteinemia affects ?","o":["Retinal pigment epithelium","Optic nerve","Occipital cortex","Bipolar neurons"],"a":0,"e":"Ans. is ''a'' i.e., Retinal pigment epithelium Abetalipoproteinemia or Bassen-Kornzweig syndrome is caused by a defect of Microsomal Triglyceride Transfer Protein (MTTP). In abetalipoproteinemia, both chylomicron and VLDL formation get affected. As a result, fat absorption is affected and the affected child presents with steatorrhea in the first few months of life. All fat soluble vitamin absorption also get affected. Hence Vitamin A, D, E and K deficiency is expected, however Vitamin E deficiency is found to have profound effects. Vitamin E deficiency presents as retinitis pigmentosa and subacute combined degeneration. Other features of abetalipoproteinemia are acanthocytes (star shaped RBCs in peripheral smear caused because the lipid composition of RBC membrane gets affected), hypocholesterolemia. Treatment involves vitamin E administration.","pyqMatches":[{"year":"2016","no":347,"q":"Abetalipoproteinemia affects ?","o":["Retinal pigment epithelium","Optic nerve","Occipital cortex","Bipolar neurons"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1235, 'Biochemistry', 'Lipid Metabolism', 'Moderate', 'Biochemistry', 354, '{"id":1235,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":354,"q":"Genetically mediated VLDL overproduction is a feature of all except ?","o":["Familial combined hyperlipidemia","Hypoapobetalipoproteinemia","Familial dyslipidemic hypertension","LDL subclass B"],"a":1,"e":"Ans. is ''b'' i.e., Hypoapobetalipoproteinemia [Ref Essentials of Biochemistry p. 712] Familial combined hyperlipidemia or Type lib Familial hyperlipoproteinemia is characterised by genetically determined overproduction of triglyceride rich VLDL (VLDL 1) and small dense LDL particles. It is the most commonly inherited disorder. Please remember Acquired combined hyperlipidemia with same features is caused by metabolic syndrome or insulin resistance. Hyperapobetalipoproteinemia is characterized by an increased number of small, dense LDL particles and an elevated LDL-B level with normal or borderline high LDL-C levels. Patients with Hyperapobetalipoproteinemia may have normal or high triglycerides. Hyperapobetalipoproteinemiahas been found to be the most common phenotype (34%) associated with premature CAD ;Hyperapobetalipoproteinemia with hypertriglyceridemiais found to be even more strongly associated with CAD than Hyperapobetalipoproteinemia with normal triglycerides.","pyqMatches":[{"year":"2016","no":346,"q":"Genetically mediated VLDL overproduction is a feature of all except ?","o":["Familial combined hyperlipidemia","Hypoapobetalipoproteinemia","Familial dyslipidemic hypertension","LDL subclass B"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1236, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 355, '{"id":1236,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":355,"q":"Gerhardt''s test is used to detect ?","o":["Reducing sugar","Ketone body","Protein","Blood"],"a":1,"e":"Ans. is ''b'' i.e., Ketone body Gerhardt''s test is a test used to detect acetoacetate in urine (acetone and (3 hydroxybutyrate do not answer this test). Reagents used for Gerhardt''s test include Concentrated nitric acid and 10% Ferric chloride","pyqMatches":[{"year":"2016","no":345,"q":"Gerhardt''s test is used to detect ?","o":["Reducing sugar","Ketone body","Protein","Blood"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1237, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 356, '{"id":1237,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":356,"q":"Folds in collagen are due to-","o":["Glycine","Proline","Hydroxyproline","Lysine"],"a":0,"e":":B Ans. is `b > a'' i.e., Proline > Glycine [Ref Essentials of biochemisty p. 868] Two amino acids are involved in producing folds in collagen : proline and glycine. In order to form a triple-helix a polypeptide chain (a-chain) must contain glycine as every third residue in the sequence. This is because only the glycine is small enough to be accommodated in the limited space available down the central core of the triple helix. Each turn of polypeptide chain (a-chain) contains three amino acid residues, and glycine (Gly) is present at every third position. Thus glycine constitutes 33% of the total amino acid residues. The repeating amino acid residues, represented as (Gly-X-Y)n, is an absolute requirement for formation of triple helix. X and Y can be any amino acids, but most of the time Xis proline (10% of the total amino acid residues) and most of the time Y is hydroxyproline. Other important amino acids found in collagen are lysine and hydroxylysine.","pyqMatches":[{"year":"2016","no":342,"q":"Folds in collagen are due to","o":["Glycine","Proline","Hydroxyproline","Lysine"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1238, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 357, '{"id":1238,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":357,"q":"Progesterone synthesis requires -","o":["LDL","VLDL","HDL","Chylomicron"],"a":2,"e":"Ans. is ''c'' i.e.,HDL Granulosa cells use follicular fluid HDL as a source of cholesterol for the synthesis of progesterone. Under the influence of LH, corpus luteal cells take up cholesterol from follicular fluid HDL and convert cholesterol into progesterone.","pyqMatches":[{"year":"2016","no":271,"q":"Progesterone synthesis requires","o":["LDL","VLDL","HDL","Chylomicron"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1239, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 358, '{"id":1239,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":358,"q":"The most abundant aminoacid of collagen is -","o":["Glycine","Proline","Lysine","Tryptophan"],"a":0,"e":"Ans. is ''a'' i.e., Glycine","pyqMatches":[{"year":"2016","no":341,"q":"The most abundant aminoacid of collagen is","o":["Glycine","Proline","Lysine","Tryptophan"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1240, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 359, '{"id":1240,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":359,"q":"Site of small chain fatty acid absorption is -","o":["Ileum","Duodenum","Ascending colon","Rectum"],"a":2,"e":"Ans. is ''c'' i.e., Ascending colon Short chain fatty acids (SCFA) are fatty acids with 2 to 6 carbon atoms. They are the major end-products of the microbial digestion of carbohydrates in the alimentary canal. These short chain fatty acids, butyrate particularly is important for colon health because it is the primary energy source for colonic cells and has anti-carcinogenic as well as anti-inflammatory properties that are important for keeping colon cells healthy. Butyrate inhibits the growth and proliferation of tumor cell lines in vitro, induces differentiation of tumor cells, producing a phenotype similar to that of the normal mature cell, and induces apoptosis or programmed cell death of human colorectal cancer cells The highest concentrations are observed in the large intestine (caecum and colon) of all the mammals. Human caecum and proximal colon have high luminal concentrations of organic nutrients (non-starch polysaccharides from plant cell walls, and proteins not absorbed by the small intestine) which maintain high bacterial growth rates. Against this fermentative background, antiperistalsis ensures retention and thorough mixing of faeces in the proximal colon, which is the site of maximal SCFA production. SCFA absorption is concentration dependent and occurs most readily in the proximal colon (Includes cecum, ascending colon and transverse colon).","pyqMatches":[{"year":"2016","no":272,"q":"Site of small chain fatty acid absorption is","o":["Ileum","Duodenum","Ascending colon","Rectum"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1241, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 360, '{"id":1241,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":360,"q":"All of the following are true about collagen structure except -","o":["Collagen is secreted by fibroblasts as procollagen","Lysyl oxidase is dependent on Vitamin C","Hydroxylysine undergoes glycosylation","Glycine is the most abundant aminoacid of collagen"],"a":1,"e":"Ans. is ''b'' i.e., Lysyl oxidase is dependent on Vitamin C Collagen is the most abundant protein in the body. Collagen is a triple helix. It is made up of 3 polypeptide chains - Each polypeptide chain has about 1000 amino acids. It is made up of repetitive units of (Gly- X - Y), where X and Y are most commonly proline and hydroxyproline. Hence 33% of aminoacid residues of collagen is glycine - the most abundant aminoacid of collagen. Collagen is synthesised as procollagen by fibroblasts intracellularly. After translation of mRNA of collagen in ribosomes, the polypeptide chains undergo posttranslational modifications in the form of hydroxylation and glycosylation.","pyqMatches":[{"year":"2016","no":340,"q":"All of the following are true about collagen structure except","o":["Collagen is secreted by fibroblasts as procollagen","Lysyl oxidase is dependent on Vitamin C","Hydroxylysine undergoes glycosylation","Glycine is the most abundant aminoacid of collagen"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1242, 'Biochemistry', 'Lipid Metabolism', 'Moderate', 'Biochemistry', 361, '{"id":1242,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":361,"q":"HMG CoA is precursor of all except-","o":["Ubiquinone","Dolichol","Bile pigments","Ketone body"],"a":2,"e":"Ans. is ''c'' i.e., Bile pigments 3 - Hydroxy 3 methyl glutaryl CoA or HMG CoA is formed from acetyl CoA.","pyqMatches":[{"year":"2016","no":273,"q":"HMG CoA is precursor of all except","o":["Ubiquinone","Dolichol","Bile pigments","Ketone body"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1243, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 362, '{"id":1243,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":362,"q":"Small RNAs are ?","o":["Between 200 and 500 bps in length","Coded by small exons","A mode of regulation of gene expression","Always endogenously synthesised"],"a":2,"e":"Ans. is ''c'' i.e., A mode of regulation of gene expression Small RNAs are less than 200 nucleotides in length. They are coded by intronic sequences of genes. They help in regulation of gene expression through GENE SILENCING mechanism The miRNA gene sequences located within intronic sequences are transcribed by RNA polymerase III to form Pri-miRNA. Pri- miRNA is processed by microprocessor complex to form a stem loop structure, Pre-miRNA.","pyqMatches":[{"year":"2016","no":339,"q":"Small RNAs are ?","o":["Between 200 and 500 bps in length","Coded by small exons","A mode of regulation of gene expression","Always endogenously synthesised"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1244, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 363, '{"id":1244,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":363,"q":"What is the parameter that is used to assess lipid peroxidation?","o":["Malondialdehyde","CRP","hsCRP","Carboxymethyl lysine"],"a":0,"e":"Ans. is ''a'' i.e.,Malondialdehyde ROS can be produced by either breakage of covalent bond, addition of electrons to a molecule or removal of hydrogen by other radicals. They are generally highly reactive species and typically act as electrophilic species or oxidant agents. The most important radicals or pro-oxidant molecules involved in disease processes are superoxide (02-), hydroxyl radical (OH), hydrogen peroxide (H202) and certain oxides of nitrogen, like nitric oxide (NO) and peroxynitrite (ONOO-)2 Since it is complex measuring free radicals directly in vivo, it is necessary to carry out the quantification of cellular components which can react with these free radicals, such as proteins, DNA and mainly lipids. Once lipid peroxides are unstable compounds, they tend to degrade rapidly in a variety of sub products. MDA (Malondialdehyde) is one of the most known secondary products of lipid peroxidation, and it can be used as a marker of cell membrane injury. MDA is a three-carbon, low-molecular weight aldehyde formed by cyclization of aldehydes which have unsaturation in a or 13 positions Several methods have been developed to assess MDA, including quantitative methods using spectrophotometry or fluorimetric detection, high performance liquid chromatography (HPLC), gas chromatography and immunological techniques Other markers of oxidative stress include conjugated dienes, ethane and pentane gases, isoprostanes and 4-HNE (4 - hydroxy 2- nonenal)","pyqMatches":[{"year":"2016","no":275,"q":"What is the parameter that is used to assess lipid peroxidation?","o":["Malondialdehyde","CRP","hsCRP","Carboxymethyl lysine"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1245, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 364, '{"id":1245,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":364,"q":"Ubiquitin Proteasome pathway is used for degradation of ?","o":["Extracellular long lived proteins","Intracellular long lived proteins","Intracellular short lived proteins","Extracellular short lived proteins"],"a":2,"e":"Ans. is ''c'' i.e., Intracellular short lived proteins Extracellular proteins and intracellular long lived proteins get degraded in lysosomes with the help of cathepsin Intracellular short lived proteins get labelled with ubiquitin once their life span gets over.","pyqMatches":[{"year":"2016","no":338,"q":"Ubiquitin Proteasome pathway is used for degradation of ?","o":["Extracellular long lived proteins","Intracellular long lived proteins","Intracellular short lived proteins","Extracellular short lived proteins"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1246, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 365, '{"id":1246,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":365,"q":"Amino acid in synthesis of neurotransmitter","o":["Glutamate","Proline","Cysteine","Alanine"],"a":0,"e":"Ans. is ''a'' i.e.,Glutamate Aminoacid Neurotransmitter Glutamate Glutamate & GABA Glycine Glycine Phenylalanine & TyrosineDopamine, Norepinephrine &Epinephrine Tryptophan Serotonin","pyqMatches":[{"year":"2016","no":278,"q":"Amino acid in synthesis of neurotransmitter","o":["Glutamate","Proline","Cysteine","Alanine"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1247, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 366, '{"id":1247,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":366,"q":"Maximum buffering capacity of a buffer is maximum at pH","o":["Less than pka","More than pka","Equal to pka","Has no relation with pka"],"a":2,"e":"Ans. is ''c'' i.e., Equal to pka [Ref Harper 30th/e p. 21 & 29''11e p. 20, 21, 18; Vasudevan 6thie p. 22, 23] Maximal buffering capacity occurs at pH equal to pka of buffer. Therefore, to work as a best buffer at physiological pH amino acid should have pka value close to physiological pH (7.4). Amino acids can have buffering action due to three ionizable groups :- a-carboxyl group :- Different amino acids have pka value of a- carboxyl group between 3.5-4. So, carboxyl group of amino acids has maximum buffering capacity between pH 3.5-4. a-amino group :- Different amino acids have pka value of a-amino group between 8.0-9.0. Thus, a-amino group has maximum buffering capacity between pH 8.0-9.0. Special ionizable group (in some amino acids) :- Among special ionizable group of amino acids, imidazole group of histidine has pka value 6.5-7.4, which is closest to physiological pH. Hence, histidine (due to imidazole group) has maximum buffering capacity at physiologial pH.","pyqMatches":[{"year":"2016","no":279,"q":"Maximum buffering capacity of a buffer is maximum at pH","o":["Less than pka","More than pka","Equal to pka","Has no relation with pka"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1248, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 367, '{"id":1248,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":367,"q":"LacY in Lac Operon codes for ?","o":["B Galactosidase","Galactoside Permease","Thiogalactoside Transacetylase","Repressor"],"a":1,"e":"Ans. is ''b'' i.e., Galactoside Permease These code for 3 proteins that are involved in catabolism of lactose. These genes are ''Z'' gene (codes for P-galactosidase), ''Y'' gene (codes for galactoside permease), and ''A'' gene (codes for thiogalactoside transacetylase).","pyqMatches":[{"year":"2016","no":337,"q":"LacY in Lac Operon codes for ?","o":["B Galactosidase","Galactoside Permease","Thiogalactoside Transacetylase","Repressor"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1249, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 368, '{"id":1249,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":368,"q":"Essential amino-acid deficiency affect nitrogen balance by","o":["Increasing protein degradation","Decreasing protein degradation","Decreasing protein synthesis","Increasing protein synthesis"],"a":2,"e":"Ans. is ''c'' i.e., Decreasing protein synthesis [Ref Principles of medical Biochemistry p. 464] Nitrogen balance is the difference between ingested nitrogen and excreted nitrogen. Nitrogen balance = N ingested - N excreted Because dietary proteins are an important source of nitrogen, nitrogen balance is an important index of protein and amino acid metabolism. In healthy adults, nitrogen balance is zero, i.e. a state of nitrogen equlibrium exists, where nitrogen intake is equal to nitrogen excretion. Negative nitrogen balance (excretion exceeds intake) in dietary protein deficiency In adult, even of protein starved, at least 30-40 gm of amino acids are degraded each day; this amount defines the minimum dietary requirment. If dietary supply drops below this limit, a negative nitrogen balance occurs and the body protein is lost. Essential amino acid deficiency has the same effect because relative deficiency.","pyqMatches":[{"year":"2016","no":280,"q":"Essential amino-acid deficiency affect nitrogen balance by","o":["Increasing protein degradation","Decreasing protein degradation","Decreasing protein synthesis","Increasing protein synthesis"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1250, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 369, '{"id":1250,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":369,"q":"Function of tyrosinase is","o":["Synthesis of norepinephrine","Synthesis of dopamine","Synthesis of melanin","All of the above"],"a":2,"e":"Ans. is ''c'' i.e., Synthesis of melanin [Ref Harper 29th/e p. 288- 290] Note- Tyrosine hydroxylase and tyrosinase catalyzes the conversion of tyrosine to Dopa, but both are defferent enzymes. Tyrosine hydroxylase is involved in catecholamines synthesis in adrenal medulla and sympathetic ganglia, whereas tyrosinase is involved in melanin synthesis in melanoblasts of skin.","pyqMatches":[{"year":"2016","no":283,"q":"Function of tyrosinase is","o":["Synthesis of norepinephrine","Synthesis of dopamine","Synthesis of melanin","All of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1251, 'Biochemistry', 'Molecular Biology', 'Moderate', 'Biochemistry', 370, '{"id":1251,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Moderate","source":"Biochemistry","sourceNo":370,"q":"Chimeric DNA true are all except ?","o":["Formed by linking DNA fragments of unrelated genome","Sticky end producing restriction endonucleases favour formation of chimeric DNA","They don''t require DNA ligases","The organism harbouring a chimeric DNA has features of themselves and the properties of the insert"],"a":2,"e":"Ans. is ''c'' i.e., They don''t require DNA ligases Chimeric DNA or recombinant DNA is formed by linking DNA fragments of two unrelated genome. It is a step involved in recombinant DNA technology. It is done to introduce a favourable quality into an organism like ability to produce insulin by E.Coli (Done by linking insulin cDNA into a vector and introducing the recombinant vector or chimeric DNA into E.Coli) or insect resistance in crops (done my introducing the gene fragment capable of producing Bacillus thurengiensis) into Ti plasmid and introducing the chimeric DNA or recombinant DNA into growing plants).","pyqMatches":[{"year":"2016","no":335,"q":"Chimeric DNA true are all except ?","o":["Formed by linking DNA fragments of unrelated genome","Sticky end producing restriction endonucleases favour formation of chimeric DNA","They don''t require DNA ligases","The organism harbouring a chimeric DNA has features of themselves and the properties of the insert"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1252, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 371, '{"id":1252,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":371,"q":"Enzyme which acts on aspartate","o":["Serum Glutamate Pyruvate Transaminase (SGPT)","Serum Glutamate Oxaloacetate Transaminase (SGOT)","Ornithine transcarbmaylase (OTC)","Argininosuccinate lyase (ASL)"],"a":1,"e":"Ans. is ''b'' i.e., Serum Glutamate Oxaloacetate Transaminase (SGOT) SGPT catalayses the transamination between Alanine and a Ketoglutarate. Alanine + a Ketoglutarate Pyruvate + Glutamate It is in no way related to aspartate. SGOT catalyses the transamination between Aspartate and a Ketoglutarate","pyqMatches":[{"year":"2016","no":286,"q":"Enzyme which acts on aspartate","o":["Serum Glutamate Pyruvate Transaminase (SGPT)","Serum Glutamate Oxaloacetate Transaminase (SGOT)","Ornithine transcarbmaylase (OTC)","Argininosuccinate lyase (ASL)"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1253, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 372, '{"id":1253,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":372,"q":"Proteins are stored as ?","o":["Structural proteins","Functional proteins","Fats","Lysosomal enzymes"],"a":2,"e":"Ans. is ''c'' i.e., Fats There is no storage form of protein Hence the aminoacids formed by breakdown of proteins undergo catabolism During catabolism, most of the aminoacids give off their amino groups and then the carbon skeleton undergoes catabolism On catabolism, the carbon skeleton of aminoacids give rise to glycolytic intermediate or citric acid cycle intermediates.","pyqMatches":[{"year":"2016","no":331,"q":"Proteins are stored as ?","o":["Structural proteins","Functional proteins","Fats","Lysosomal enzymes"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1254, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 373, '{"id":1254,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":373,"q":"Allosteric stimulator of glutamate dehydrogenase is","o":["ATP","GTP","Palmitoyl CoA","Leucine"],"a":3,"e":"Ans. is ''d'' i.e.,Leucine GLDH is allosterically stimulated by ADP, GDP, leucine, valine and isoleucine. It is inhibited by ATP, GTP, palmitoyl CoA and Zinc.","pyqMatches":[{"year":"2016","no":288,"q":"Allosteric stimulator of glutamate dehydrogenase is","o":["ATP","GTP","Palmitoyl CoA","Leucine"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1255, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 374, '{"id":1255,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":374,"q":"Aminoacyl tRNA gets attached to which site of ribosome?","o":["P site of 40s ribosome","A site of 60s ribosome","A site of 40s ribosome","P site of 60s ribosome"],"a":1,"e":"Ans. is ''b'' i.e., A site of 60s ribosome Translation is a process by which nucleotide bases of mRNA get translated as aminoacid sequences of polypeptide chain. It takes part in free ribosome. Free ribosome reads the mRNA from 5'' end to 3'' end. It reads the codons of mRNA one by one. Depending upon the codon that is present in mRNA, ribosome is capable of attaching a complementary anticodon containing tRNA. This tRNA carries a corresponding aminoacid. This way the polypeptide chain grows from amino terminal end to carboxy terminal end. Eukaryotic ribosome is a 80s unit. It dissociates into 40s and 60s subunits. 60s subunit contains P site and A site. When ribosome enters into chain elongation, on the P site of 60s, is attached the AUG codon of mRNA, to which initiation methionine tRNA is attached and A site is free","pyqMatches":[{"year":"2016","no":328,"q":"Aminoacyl tRNA gets attached to which site of ribosome?","o":["P site of 40s ribosome","A site of 60s ribosome","A site of 40s ribosome","P site of 60s ribosome"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1256, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 375, '{"id":1256,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":375,"q":"Which of the following is a biologically important tripeptide?","o":["Thyrotropin releasing hormone","Thyroid stimulating hormone","Gonadotropin releasing hormone","Follicle Stimulating hormone"],"a":0,"e":"Ans. is ''a'' i.e., Thyrotropin releasing hormone Tripeptide is a peptide with 3 aminoacids and 2 peptide linkages. Biologically important tripeptides include glutathione, TRH (Thyrotropin Releasing Hormone) and melanostatin. TSH is a glycoprotein not a peptide. It is made up of two subunits - a and (I a subunit is a polypeptide with about 92 aminoacids. It is a structural analogue of a subunit of FSH. LH and HCG. B subunit is a polypeptide made up of 118 aminoacids. GnRH (Gonadotropin releasing Hormone) is a decapeptide with 10 aminocids. FSH is a glycoprotein with two subunits - a and p. a subunit is a polypeptide with about 96 aminoacids. It is a structural analogue of a subunit of TSH. LH and HCG. p subunit is a polypeptide made up of 111 aminoacids.","pyqMatches":[{"year":"2016","no":289,"q":"Which of the following is a biologically important tripeptide?","o":["Thyrotropin releasing hormone","Thyroid stimulating hormone","Gonadotropin releasing hormone","Follicle Stimulating hormone"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1257, 'Biochemistry', 'Genetics', 'Easy', 'Biochemistry', 376, '{"id":1257,"subject":"Biochemistry","chapter":"Genetics","difficulty":"Easy","source":"Biochemistry","sourceNo":376,"q":"Left handed helix is seen in -","o":["B DNA","A DNA","Z DNA","F DNA"],"a":2,"e":"Ans. is ''c'' i.e., Z DNA Based on quartenary structure of DNA many conformations are possible out of the common three forms are – B DNA, A DNA and Z DNA. Z DNA It is found in those regions of chromosomes which are rich in GC sequences It is a left handed helix Every full turn has 12 base pairing.","pyqMatches":[{"year":"2016","no":327,"q":"Left handed helix is seen in","o":["B DNA","A DNA","Z DNA","F DNA"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1258, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 377, '{"id":1258,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":377,"q":"DNA fragments are separated by ?","o":["Ultracentrifugation","Agarose gel electrophoresis","Paper chromatography","High pressure liquid chromatography"],"a":1,"e":"Ans. is ''b'' i.e., Agarose gel electrophoresis [Ref Essentials of biochemistry p. 756] DNA is cut into large fragments, using restriction enzymes. These fragments are then separated by gel electrophoresis (either agarose or polyacrylamide gel electrophoresis).","pyqMatches":[{"year":"2016","no":326,"q":"DNA fragments are separated by ?","o":["Ultracentrifugation","Agarose gel electrophoresis","Paper chromatography","High pressure liquid chromatography"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1259, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 378, '{"id":1259,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":378,"q":"Carbamoyl Phosphate synthetase I [CPSI] true is","o":["It is present in cytoplasm","It is involved in pyrimidine synthesis","N- Acetyl Glutamate is an allosteric stimulator of CPSI","Glutamine is the amino group donor for CPSI"],"a":2,"e":"Ans. is ''c'' i.e., N- Acetyl Glutamate is an allosteric stimulator of CPSI PROPERTYCPS - I CPS - II Pathway Urea cycle Pyrimidine synthesis Subcellular location Mitochondria Cytoplasm Amino Group donor Ammonia Glutamine Allosteric regulation Stimulated by N - Acetyl Glutamate(NAG) Inhibited by the products - pyrimidine nucleotides,Uridine,Cyti & Thymidine","pyqMatches":[{"year":"2016","no":290,"q":"Carbamoyl Phosphate synthetase I [CPSI] true is","o":["It is present in cytoplasm","It is involved in pyrimidine synthesis","N- Acetyl Glutamate is an allosteric stimulator of CPSI","Glutamine is the amino group donor for CPSI"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1260, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 379, '{"id":1260,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":379,"q":"Molecular mimicry is established in the presence of ?","o":["Cysteine","Alanine","Glycine","Tryptophan"],"a":0,"e":"Ans. is ''a'' i.e., Cysteine Molecular mimicry is caused by structural homology or similarity between foreign antigens and self-antigens. As a result of structural similarity a T cell or B cell activated against a foreign antigen cross reacts with self-antigen and causes autoimmunity. Molecular mimicry does not always expect a sequence similarity to get initiated. It is found to be induced even when the self antigens and exogenous antigens share the same binding motif with MHC (Major Histocompatibility Complex). This binding motif similarity is more often found in the presence of cysteine (forms disulphide bridges), arginine or lysine (form hydrogen bonds) in the binding site of antigens.","pyqMatches":[{"year":"2016","no":325,"q":"Molecular mimicry is established in the presence of ?","o":["Cysteine","Alanine","Glycine","Tryptophan"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1261, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 380, '{"id":1261,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":380,"q":"All of the following can determine protein structure except","o":["Edman''s Sequencing","X ray crystallography","Optical rotatory dispersion","Spectrophotometry"],"a":3,"e":"Ans. is ''d'' i.e., Spectrophotometry Methods used for studying primary structure : A) Sanger''s sequencing Sanger''s reagent is (1 fluro 2,4 Dinitrobenzene) B) Edman''s Sequencing Edman''s reagent is Phenylisothiocyanate C) Reverse Sequencing It has to be supplemented by Mass Spectrometry Methods used for studying secondary structure:","pyqMatches":[{"year":"2016","no":293,"q":"All of the following can determine protein structure except","o":["Edman''s Sequencing","X ray crystallography","Optical rotatory dispersion","Spectrophotometry"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1262, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 381, '{"id":1262,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":381,"q":"Edman''s reagent is used for","o":["DNA sequencing","Protein sequencing","Protein Denaturation","DNA denaturation"],"a":1,"e":"Ans. is ''b'' i.e., Protein sequencing Edman''s reagent is Phenyl isothiocyanate. Phenyl isothiocyanate is used for sequencing proteins Phenyl isothiocyanate binds to a aminogroups. In a protein, only aminoterminal aminoacid''s a aminogroup will be free. Hence when Phenylisothiocyanate is added to a peptide which is adsorbed on to a glass fibre coated with a polymer, in the presence of 12% trimethylamine, it reacts with the amine group of N terminal aminoacid. By acid hydrolysis, the first aminoacid is cleaved from the polypeptide chain and the aminoacid is identified by chromatography. The cycle is continued. This way 50 aminoacids can be sequenced.","pyqMatches":[{"year":"2016","no":294,"q":"Edman''s reagent is used for","o":["DNA sequencing","Protein sequencing","Protein Denaturation","DNA denaturation"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1263, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 382, '{"id":1263,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":382,"q":"Most abundant aminoacid in brain is","o":["Glutamate","Aspartate","Glutamine","Asparagine"],"a":0,"e":"Ans. is ''a'' i.e., Glutamate Glutamate is the most abundant free alpha aminoacid found in Brain. It is an acidic polar aminoacid. It is the predominant excitatory neurotransmitter of brain. It is synthesised in brain from glutamine and a Ketoglutarate. Glutamate is released from presynaptic excitatory neurons in a calcium dependent manner. Glutamate acts on both inotropic and metabotropic receptors. Inotropic receptors of glutamate include : Kainate receptors AMPA receptors NMDA receptors","pyqMatches":[{"year":"2016","no":295,"q":"Most abundant aminoacid in brain is","o":["Glutamate","Aspartate","Glutamine","Asparagine"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1264, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 383, '{"id":1264,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":383,"q":"Cystine has how many molecules of cysteine?","o":["1","2","3","4"],"a":1,"e":"Ans. is ''b'' i.e., 2 Cysteine is a sulphur containing aminoacid It is a polar but uncharged aminoacid Cysteine with a sulfhydryl group can get oxidised and forms a dimer (2) called as cystine. Cysteine acquires its polar nature only by virtue of its sulfhydryl group.","pyqMatches":[{"year":"2016","no":296,"q":"Cystine has how many molecules of cysteine?","o":["1","2","3","4"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1265, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 384, '{"id":1265,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":384,"q":"Jumping genes are ?","o":["Moderately repetitive sequences","Highly repetitive sequences","Satellite sequences","Simple segment repeat sequences"],"a":0,"e":"Ans. is ''a'' i.e., Moderately repetitive sequences","pyqMatches":[{"year":"2016","no":324,"q":"Jumping genes are ?","o":["Moderately repetitive sequences","Highly repetitive sequences","Satellite sequences","Simple segment repeat sequences"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1266, 'Biochemistry', 'Vitamins & Minerals', 'Moderate', 'Biochemistry', 385, '{"id":1266,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Moderate","source":"Biochemistry","sourceNo":385,"q":"Vitamin given in homocysteinuria are all except","o":["Vitamin B6","Vitamin B12","Folate","Thiamine"],"a":3,"e":"Ans. is ''d'' i.e., Thiamine Major fate of homocysteine is that it gets converted into cysteine in the presence of cystathionine I synthase. Cystathionine p synthase is dependent on pyridoxal phosphate. Hence defect of cystathionine p synthase can result in homocysteinuria. This is called as classical homocysteinuria. This condition responds to B6 administration, as the enzyme cystathione p synthase is dependent on B6. Minor fate of homocysteine is that it gets converted into methionine in the presence of methionine synthase. Methionine synthase is dependent on methyl cobalamine (coenzyme form of Vitamin B12). Methyl group donor for methylcobalamine is methyl THFA. Homocysteinuria is also caused by defect of methionine synthase. As this enzyme is dependent on Vitamin B12 and THFA, homocysteinuria responds to B12 and THFA administration","pyqMatches":[{"year":"2016","no":297,"q":"Vitamin given in homocysteinuria are all except","o":["Vitamin B6","Vitamin B12","Folate","Thiamine"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1267, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 386, '{"id":1267,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":386,"q":"Glutathione is used to detoxify which free radical?","o":["Hydrogen peroxide","Superoxide","Peroxyl radical","Singlet Oxygen"],"a":0,"e":"Ans. is ''a'' i.e., Hydrogen peroxide Glutathione is a tripeptide. It is gamma glutamyl cysteinyl glycine It is denoted as GSH - because it has cysteine with a sulphydryl group It is used to detoxify hydrogen peroxide and lipid peroxides in the presence of glutathione peroxidase. Glutathione can also detoxify peroxyl radical. Peroxyl radical can not get reduced by enzymatic reactions. They get detoxified by antioxidants like vitamin E and Glutathione Singlet oxygen gets detoxified principally by polyphenol antioxidants Superoxide radicals are detoxified by Superoxide dismutase (SOD) using Zinc as electron acceptor or donor (Some classes of SODs use iron or Nickel as electron acceptor or donor)","pyqMatches":[{"year":"2016","no":298,"q":"Glutathione is used to detoxify which free radical?","o":["Hydrogen peroxide","Superoxide","Peroxyl radical","Singlet Oxygen"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1268, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 387, '{"id":1268,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":387,"q":"Ataxia telangiectasia is caused by a defect of ?","o":["Base Excision Repair","Nucleotide Excision repair","Mismatch repair","ds DNA break repair"],"a":3,"e":"Ans. is ''d'' i.e., ds DNA break repair DNA repair Defect associated Mismatch repair Hereditary Non polyposis Colon Cancer Nucleotide Excision Repair Xeroderma pigmentosa, Cockayne syndrome Double Stranded DNA Break Ataxia Telangiectasia, Bloom''s syndrome, Repair Fanconi''s anemia","pyqMatches":[{"year":"2016","no":323,"q":"Ataxia telangiectasia is caused by a defect of ?","o":["Base Excision Repair","Nucleotide Excision repair","Mismatch repair","ds DNA break repair"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1269, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 388, '{"id":1269,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":388,"q":"Bond formation between ribose sugar and nitrogen is ?","o":["Acidanhydride linkage","Phosphodiester linkage","Phosphoester linkage","Glycosidic linkage"],"a":3,"e":"Ans. is ''d'' i.e., Glycosidic linkage Pentose sugar (ribose or deoxyribose) is linked to a nitrogenous base (purine or pyrimidine) via covalent N-glycosidic bond to form nucleoside","pyqMatches":[{"year":"2016","no":322,"q":"Bond formation between ribose sugar and nitrogen is ?","o":["Acidanhydride linkage","Phosphodiester linkage","Phosphoester linkage","Glycosidic linkage"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1270, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 389, '{"id":1270,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":389,"q":"The linkage which links individual nucleotides in a polynucleotide chain is -","o":["p N- Glycosidic linkage","a N - glycosidic linkage","3''5'' Phosphodiester linkage","5''3'' Phosphodiester linkages"],"a":2,"e":"Ans. is ''c'' i.e., 3''5'' Phosphodiester linkage Nucleoside N-glycosidic bond between pentose sugar and nitrogenous base. Nucleotide (monophasphate nucleatide) Posphoester linkage (not phosphodiester) between nucleoside and phosphate grp. Diphosphate & polyphosphate nucleotides Acid anhydride linkage between monophosphate & other phosphate grp Polynucleotide chain 3''5'' phosphodiester linkage between 3'' hydroxyl group nucleotide with 5'' phosphate group of next nucleotide.","pyqMatches":[{"year":"2016","no":321,"q":"The linkage which links individual nucleotides in a polynucleotide chain is","o":["p N- Glycosidic linkage","a N - glycosidic linkage","3''5'' Phosphodiester linkage","5''3'' Phosphodiester linkages"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1271, 'Biochemistry', 'Molecular Biology', 'Moderate', 'Biochemistry', 390, '{"id":1271,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Moderate","source":"Biochemistry","sourceNo":390,"q":"All of the following are true about Nucleic Acid Sequence Based Amplification except ?","o":["It is a specific amplification of RNA","It is a replacement for reverse transcriptase PCR","Denaturation is carried out at 94°C","It requires Reverse transcriptase."],"a":2,"e":"Ans. is ''c'' i.e., Denaturation is carried out at 94°C Nucleic Acid Sequence Based Amplification (NASBA) or Isothermal RNA amplification is a replacement for Reverse transcriptase PCR (RT-PCR). Both NASBA and RT-PCR are used for amplifying desired or specific RNA fragments. In RT-PCR, first the desired RNA is converted to dsDNA using reverse transcriptase and then the dsDNA is amplified using PCR technique","pyqMatches":[{"year":"2016","no":320,"q":"All of the following are true about Nucleic Acid Sequence Based Amplification except ?","o":["It is a specific amplification of RNA","It is a replacement for reverse transcriptase PCR","Denaturation is carried out at 94°C","It requires Reverse transcriptase."],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1272, 'Biochemistry', 'Genetics', 'Moderate', 'Biochemistry', 391, '{"id":1272,"subject":"Biochemistry","chapter":"Genetics","difficulty":"Moderate","source":"Biochemistry","sourceNo":391,"q":"Regarding FISH all are true except ?","o":["Used to detect copy number variations","Used to detect balanced translocations","Requires oligonucleotides","Requires DNA polymerase"],"a":3,"e":"Ans. is ''d'' i.e., Requires DNA polymerase Fluoroscent in Situ Hybridisation is a cytogenetic technique used to detect chromosomal abnormalities. This technique uses fluorescently labelled oligonucleotides or DNA probes. These probes bind to specific sequences of a chromosome. Attached to the probes are reporter fluorescent dyes which under fluorescence microscopy confirm the presence or absence of a particular chromosomal aberration. In FISH, the target is the nuclear DNA of either interphase cells or of metaphase chromosomes affixed to a microscope slide. When a specific probe is added, it anneals to its complementary sequence in the affixed DNA. As the probe is labelled with a reporter molecule it is visualized by fluorescence microscopy","pyqMatches":[{"year":"2016","no":319,"q":"Regarding FISH all are true except ?","o":["Used to detect copy number variations","Used to detect balanced translocations","Requires oligonucleotides","Requires DNA polymerase"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1273, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 392, '{"id":1273,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":392,"q":"True about pyrimidine catabolism is ?","o":["It is a source of uric acid","β aminoisobutyrate is generated","Unlike other catabolic pathways, it does not generate intermediates of citric acid cycle","Increased pyrimidine catabolism causes decreased synthesis of carnosine"],"a":1,"e":"Ans. is ''b'' i.e., β aminoisobutyrate is generated In pyrimidine catabolism, first cytidine and thymidine are converted to uridine by deamination and demethylation respectively. Uridine in the presence of phosphorylase gets converted into uracil. Uracil undergoes hydrogenation in the presence of dihydrouracil dehydrogenase to form dihydrouracil Dihydrouracil hydratase opens the ring of dihydrouracil to form a linear structure","pyqMatches":[{"year":"2016","no":318,"q":"True about pyrimidine catabolism is ?","o":["It is a source of uric acid","β aminoisobutyrate is generated","Unlike other catabolic pathways, it does not generate intermediates of citric acid cycle","Increased pyrimidine catabolism causes decreased synthesis of carnosine"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1274, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 393, '{"id":1274,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":393,"q":"True about Purine synthesis ?","o":["Glutamine is the amino group donor for N9","PRPP synthetase is the rate limiting enzyme of purine synthesis","THFA is necessary for forming C6 of purine ring","GMP is the first nucleotide to be formed during purine synthesis"],"a":0,"e":"Ans. is ''a'' i.e.,Glutamine is the amino group donor for N9 In purine nucleotide synthesis, first Ribose 5 phosphate is activated by PRPP synthetase to form PRPP. This PRPP gets attached to N9 (source is glutamine) in the presence of PRPP glutamine amido transferase. This is the rate limiting enzyme of purine synthesis. PRPP synthetase is a common enzyme of pyrimidine nucleotide synthesis and of niacin adenine dinucleotide synthesis. As PRPP synthetase is not committed for Purine nucleotide synthesis, it can not be considered as the rate limiting enzyme of purine synthesis. In purine synthesis, Inosine monophosphate (IMP) is first formed IMP on amination with Aspartate gives rise to AMP in the presence of adenylosuccinate synthetase. This step needs GTP as a source of energy IMP on dehydrogenation by IMP dehydrogenase followed by amination with glutamine will give rise to GMP. This step used ATP as a source of energy","pyqMatches":[{"year":"2016","no":317,"q":"True about Purine synthesis ?","o":["Glutamine is the amino group donor for N9","PRPP synthetase is the rate limiting enzyme of purine synthesis","THFA is necessary for forming C6 of purine ring","GMP is the first nucleotide to be formed during purine synthesis"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1275, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 394, '{"id":1275,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":394,"q":"Antistress Vitamin is?","o":["Vitamin B1","Vitamin B2","Vitamin B3","Vitamin B5"],"a":3,"e":"Ans. is ''d'' i.e., Vitamin B5 Vitamin B5 or pantothenic acid is called as an antistress vitamin as it is found to have an impact on cortisol release and is found to support our immune system.","pyqMatches":[{"year":"2016","no":316,"q":"Antistress Vitamin is?","o":["Vitamin B1","Vitamin B2","Vitamin B3","Vitamin B5"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1276, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Hard', 'Biochemistry', 395, '{"id":1276,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Hard","source":"Biochemistry","sourceNo":395,"q":"Match enzyme with the disease caused due to its deficiency - Enzyme Disease Fumarylacetoacetate Tyrosine transaminase Tyrosinase Alkaptonuria A. Tyrosinemia Type II hydroxylase B. Homogentisate Oxidase C. Tyrosinemia Type I D- Albinism","o":["I→ D, 2 → C, 3 → A, 4→ B","I → A,2 → C,3 →D, 4 → B","1 → C,2→ D,3 → A,4 → B","l→ C, 2→ A, 3→ D, 4→ B"],"a":3,"e":"Ans. is ''d'' i.e., 1 -p C, 2 → A, 3 → D, 4 → B [Ref Harper 29th/e p. 289]","pyqMatches":[{"year":"2016","no":299,"q":"Match enzyme with the disease caused due to its deficiency - Enzyme Disease Fumarylacetoacetate Tyrosine transaminase Tyrosinase Alkaptonuria A. Tyrosinemia Type II hydroxylase B. Homogentisate Oxidase C. Tyrosinemia Type I D- Albinism","o":["I→ D, 2 → C, 3 → A, 4→ B","I → A,2 → C,3 →D, 4 → B","1 → C,2→ D,3 → A,4 → B","l→ C, 2→ A, 3→ D, 4→ B"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1277, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 396, '{"id":1277,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":396,"q":"Regarding NAD and NADP, true is ?","o":["Precursor is tyrosine","Malic enzyme is an NAD dependent enzyme","High leucine causes niacin deficiency","Niacin deficiency causes cutaneous vasodilatation"],"a":2,"e":"Ans. is ''c'' i.e., High leucine causes niacin deficiency NAD and NADP are nicotinic acid derivatives which is synthesized from tryptophan (not tyrosin) Malic enzyme is NADP dependent enzyme (not NAD dependent) Excess of leucine inhibits the conversion of tryptophan into niacin and causes pellagra. Niacin deficiency causes Pellagra. Pellagra characterised by the three Ds - Diarrhoea, Dermatitis and Dementia is caused by niacin or vitamin B3 deficiency.","pyqMatches":[{"year":"2016","no":315,"q":"Regarding NAD and NADP, true is ?","o":["Precursor is tyrosine","Malic enzyme is an NAD dependent enzyme","High leucine causes niacin deficiency","Niacin deficiency causes cutaneous vasodilatation"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1278, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 397, '{"id":1278,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":397,"q":"Which of the following has two amino groups-","o":["Glycine","Arginine","Lysine","Asparagine"],"a":1,"e":"Histidine has two imino groups. Lysine has one amino group. Arginine has two amino groups","pyqMatches":[{"year":"2016","no":300,"q":"Which of the following has two amino groups","o":["Glycine","Arginine","Lysine","Asparagine"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1279, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 398, '{"id":1279,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":398,"q":"Deficiency of which vitamin during pregnancy predisposes to meningomyelocele?","o":["Folic acid","Biotin","Pyridoxine","Thiamine"],"a":0,"e":"Ans. is ''a'' i.e.,Folic acid Folic acid deficiency in pregnancy predisposed to NTD (e.g. myelomeningocele, meningocele, spina bifida).","pyqMatches":[{"year":"2016","no":313,"q":"Deficiency of which vitamin during pregnancy predisposes to meningomyelocele?","o":["Folic acid","Biotin","Pyridoxine","Thiamine"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1280, 'Biochemistry', 'Vitamins & Minerals', 'Moderate', 'Biochemistry', 399, '{"id":1280,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Moderate","source":"Biochemistry","sourceNo":399,"q":"Vitamin B12 deficiency causes all except ?","o":["Homocysteinuria","Methylmalonic aciduria","Subacute combined degeneration","Epinephrine excess"],"a":3,"e":"Ans. is ''d'' i.e.,Epinephrine excess [Ref Dinesh Puri 3rd le p. 381] Deficiency of vitamin B12 causes Pernicious anemia, megaloblastic anemia (secondary to functional folate deficiency due to folate trap), methylmalonic aciduria due to accumulation of methylmalonyl-CoA, and neuropathy, like subacute combined degeneration (SACD) and demyelination. There may homocysteinuria as methionine synthase, a methylcobalamine dependent enzyme, is defective.","pyqMatches":[{"year":"2016","no":312,"q":"Vitamin B12 deficiency causes all except ?","o":["Homocysteinuria","Methylmalonic aciduria","Subacute combined degeneration","Epinephrine excess"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1281, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 400, '{"id":1281,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":400,"q":"Alternate fuel for brain is","o":["Glucose","Ketone bodies","Fatty acid","Aminoacid"],"a":1,"e":"Ans. is ''b'' i.e., Ketone bodies There is no stored fuel in brain, but it utilizes 60% of total energy under resting conditions. Glucose is virtually the sole fuel for the brain, except in prolonged starving when ketone bodies are the major source. Fatty acids do not serve as fuel for the brain, because they are bound to albumin in plasma; hence cannot cross the blood-brain barrier.","pyqMatches":[{"year":"2016","no":301,"q":"Alternate fuel for brain is","o":["Glucose","Ketone bodies","Fatty acid","Aminoacid"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1282, 'Biochemistry', 'Carbohydrate Metabolism', 'Moderate', 'Biochemistry', 401, '{"id":1282,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":401,"q":"Pyruvate can be a substrate of all except","o":["Lactate Dehydrogenase","Malic enzyme","Aspartate transaminase","Alanine transaminase"],"a":2,"e":"Ans. is ''c'' i.e., Aspartate transaminase There are several pathways into which pyruvate can enter. The pathway chosen in a given tissue depends on its state of oxygenation and prevailing metabolic conditions, as described below : Oxidative decarboxylation to acetyl CoA In tissues that are adequately perfused with oxygen (i.e., under aerobic conditions), pyruvate undergoes oxidative decarboxylation to form acetyl CoA, which is further catabolized to CO2 and H20 via citric acid cycle (Krebs cycle). This reaction serves as a bridge between glycolysis and Kreb''s cycle. Thus, pyruvate serves as the source of substrate of first reaction of TCA (Citric acid cycle), i.e., acetyl CoA.","pyqMatches":[{"year":"2016","no":302,"q":"Pyruvate can be a substrate of all except","o":["Lactate Dehydrogenase","Malic enzyme","Aspartate transaminase","Alanine transaminase"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1283, 'Biochemistry', 'Vitamins & Minerals', 'Moderate', 'Biochemistry', 402, '{"id":1283,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Moderate","source":"Biochemistry","sourceNo":402,"q":"Which of the following elements is known to influence the body''s ability to handle oxidative stress?","o":["Fluride","Iron","Copper","Selenium"],"a":3,"e":"Ans. is ''d'' i.e., Selenium [Ref: Pankaj Naik p. 382] The activity of the antioxidant enzymes depends on supply of minerals:? * Manganese * Zinc * Copper * Selenium - Manganese, copper and zinc are required for the activity of superoxide dismutase. - Selenium is required for the activity of glutathione peroxidase.","pyqMatches":[{"year":"2016","no":311,"q":"Which of the following elements is known to influence the body''s ability to handle oxidative stress?","o":["Fluride","Iron","Copper","Selenium"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1284, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 403, '{"id":1284,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":403,"q":"Gas released from oligosaccharide metabolism by intestinal bacteria is","o":["Carbondioxide","Sulphur dioxide","Nitric oxide","Methane"],"a":3,"e":"Ans. is ''d'' i.e., Methane Some food items are high in indigestible oligosaccharides . Eg, transgalactooligosaccharides, fructooligosaccharides (Inulin) Since these oligosaccharides do not get digested in the small intestine, they reach the large intestine. Large intestinal microorganisms breakdown these oligosaccharides to form short chain fatty acids like propionate, butyrate. These short chain fatty acids are found to be trophic to intestinal mucosa. It has anti-inflammatory effects too. Hence these are found to protect intestinal malignancy. This is the basis of prebiotics being supplemented to people with intestinal inflammatory disorders and to maintain intestinal flora. But the downside of these indigestible oligosaccharides is that, when microorganisms act on these oligiosaccharides, they result in gas production. The gases produced includes the usual hydrogen, nitrogen and carbondioxide. Apart from that when oligosaccharides are acted upon by microorganisms, it results in methane production. This methane is found to have the bloating and flatulence effect.","pyqMatches":[{"year":"2016","no":303,"q":"Gas released from oligosaccharide metabolism by intestinal bacteria is","o":["Carbondioxide","Sulphur dioxide","Nitric oxide","Methane"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1285, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 404, '{"id":1285,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":404,"q":"Chain breaking antioxidants are all except -","o":["Tocopherol","Ascorbic acid","Polyphenolic flavinols","Superoxide dismutase"],"a":3,"e":"Ans. is ''d'' i.e., Superoxide dismutase Chain breaking antioxidants are molecules which can donate an electron or accept electron from unstable intermediates of lipid peroxidation converting them into stable intermediates. They are of two two types Lipid phase chain breaking antioxidant Aqueous phase chain breaking antioxidant Lipid phase chain breaking antioxidant The most important lipid phase chain breaking antioxidant is a tocopherol. a tocopherol reacts with peroxyl radical to form tocopheroxyl radical with excess charge associated with extra electron being distributed along the chromane ring. Aqueous phase chain breaking antioxidant The most important chain breaking antioxidant of this type is ascorbic acid or vitamin C. It can scavenge many superoxide radicals. Most importantly it helps by regenerating tocopherol after it is oxidised during the process of reducing peroxyl radicals. Apart from vitamin C we have a group of polyphenol flavinols like epitachin gallate which can reduce oxidant species in aqueous phase. These are present in green tea and some antioxidant supplements Superoxide dismutase is an antioxidant enzyme which helps in detoxifying superoxides to form molecular oxygen and hydrogen peroxide. It is not a chain breaking antioxidant","pyqMatches":[{"year":"2016","no":310,"q":"Chain breaking antioxidants are all except","o":["Tocopherol","Ascorbic acid","Polyphenolic flavinols","Superoxide dismutase"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1286, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 405, '{"id":1286,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":405,"q":"Which vitamin is required for conversion of serine to glycine?","o":["Vit C","B12","Pyridoxine","Thiamine"],"a":2,"e":"Ans. is ''c'' i.e., Pyridoxine [Ref Harper 290/e p. 267-268] Glycine is a non essential amino acid synthesized from another nonessential aminoacid serine Serine in the presence of Serine hydroxyl methyltransferase (SHMT) gets converted to glycine. SHMT is a pyridoxine dependent enzyme. This step uses tetrahydrofolate as coenzyme and it gets converted to N5, N10 methylene THFA, which then acts as 1 carbon donor and helps in the conversion of uridine to thymidine.","pyqMatches":[{"year":"2016","no":304,"q":"Which vitamin is required for conversion of serine to glycine?","o":["Vit C","B12","Pyridoxine","Thiamine"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1287, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 406, '{"id":1287,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":406,"q":"Which of the following vitamins is significantly synthesised in gut by intestinal flora?","o":["Folate","B12","Biotin","B6"],"a":0,"e":":B:C Ans. is ''c > ''b'' & ''a'' i.e., Biotin > B12 & Folate Though vitamins are supposed to be essential micronutrients which are supposed to be supplied in the diet, some vitamins like Vitamin D and Niacin are endogenously synthesised. Vitamin D3 or cholecalciferol is synthesised in the skin epidermis when UV light acts on 7 dehydrocholesterol which is present in the malphigian layer. UV light opens up one of the rings of cholesterol, converting cholesterol into a secosteroid which is cholecalciferol. Cholecalciferol reaches liver. In liver it is hydroxylated at 25th position by 25 a hydroxylase to form 25 hydroxycholecalciferol 25 hydroxycholecalciferol reaches the kidney. It is hydroxylated at 1st position by 1 a hydroxylase to form 1,25 dihydroxycholecalciferol, the active form of vitamin D. Niacin''s active coenzyme forms NAD and NADP are synthesised endogenously from aminoacid tryptophan Apart from these two vitamins synthesised by human metabolic pathways, there are vitamins like Biotin, Vitamin K which are synthesised to significant amount in large intestine by intestinal microorganisms. Research has identified synthesis of folate and B12 as well in large intestine. Though they are synthesised in large intestine, as all water soluble vitamins get absorbed in small intestine, only endogenously synthesised Biotin and Vitamin K are found to contribute significantly to metabolic pathways. That is why biotin and vitamin K deficiencies are relatively rare.","pyqMatches":[{"year":"2016","no":309,"q":"Which of the following vitamins is significantly synthesised in gut by intestinal flora?","o":["Folate","B12","Biotin","B6"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1288, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 407, '{"id":1288,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":407,"q":"Headache and papilledema are features of toxicity of which vitamin?","o":["Vitamin A","Vitamin D","Vitamin C","Vitamin E"],"a":0,"e":"Ans. is ''a'' i.e., Vitamin A Hypervitaminosis A Caused by consumption of food rich in vitamin A like fish or liver (not by excessive intake of carotenoids as the conversion of carotene to vitamin A is regulated). Mechanism of toxicity: Suppresses osteoblasts and stimulates osteoclasts. High retinol concentrations stimulate lysosomal enzyme release and cause local tissue damage. Features include anorexia, irritability, headache, skin peeling, vomiting. Headache, vomiting and papilledema are found to be caused by increase in intracranial tension. Hence this condition is called as pseudotumourcerebri. As vitamin A stimulates osteoclasts, hypercalcemia, bony projections, pathological fractures are also observed as features.","pyqMatches":[{"year":"2016","no":305,"q":"Headache and papilledema are features of toxicity of which vitamin?","o":["Vitamin A","Vitamin D","Vitamin C","Vitamin E"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1289, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 408, '{"id":1289,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":408,"q":"Vitamin B12 is required for all of the following except ?","o":["Conversion of homocysteine to methionine","Conversion of homocysteine to cysteine","Conversion of propionyl coA to succinyl CoA","Conversion of methyl THFA to THFA"],"a":1,"e":"Ans. is ''b'' i.e., Conversion of homocysteine to cysteine Active form of vitamin B12 are methylcobalamine and deoxyadenosylcobalamine. Following reactions require vitamin B12 coenzyme : i) Isomerization of methylmalonyl CoA to succinyl CoA : In this reaction, active form of vitamin B12 is deoxyadenosyl cobalamine. Propionyl-CoA is produced as catabolic end product of some alipathic amino acids and (3-oxidation of odd chain fatty acids. Propionyl CoA is then converted to succinyl CoA through methylmalonyl-CoA. Thus methylmalonyl-CoA is accumulated and excreted in urine as methylmalonic acid (methylmalonate) in vitamin B12 deficiency, i.e. methylmalonic aciduria. ii) Conversion of homocystein to methionine In this reaction, active form is methylcobalamine. This is the only reaction which requires both vitamin 812 (as methylcobalamine) and folic acid (as N5-methyl-114-folate). The reaction is catalyzed by the enzyme cobalamin-dependent methionine synthase also called 5- methyltetrahydrofolate - homocysteine methyltransferase.","pyqMatches":[{"year":"2016","no":308,"q":"Vitamin B12 is required for all of the following except ?","o":["Conversion of homocysteine to methionine","Conversion of homocysteine to cysteine","Conversion of propionyl coA to succinyl CoA","Conversion of methyl THFA to THFA"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1290, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 409, '{"id":1290,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":409,"q":"Alcoholism leads to deficiency of which vitamin ?","o":["Vitamin A","Vitamin B1","Vitamin D","Vitamin B6"],"a":1,"e":"Ans. is ''b'' i.e.,Vitamin B1 Of all the micronutrients, thiamine will be the first micronutrient to become deficient. Reason is, apart from the person missing his mixed balanced diet, alcohol is also found to interfere with thiamine absorption. The third reason related to thiamine deficiency in a chronic alcoholic is that alcohol interferes with magnesium absorption. Magnesium is necessary for activation of thiamine to its coenzyme form thiamine pyrophosphate in the presence of thiamine kinase.","pyqMatches":[{"year":"2016","no":307,"q":"Alcoholism leads to deficiency of which vitamin ?","o":["Vitamin A","Vitamin B1","Vitamin D","Vitamin B6"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1291, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 410, '{"id":1291,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":410,"q":"AST/ALT > 2 occurs in deficiency of","o":["Glucose-6-phosphotase","Branching enzyme","Acid maltase","Liver phosphorylase"],"a":2,"e":"Ans. is ''c'' i.e., Acid maltase [Ref Read below] In liver diseases, ALT (alanine transaminase) is elevated more than AST (aspartate transaminase). So, in liver diseases ALT/ AST ratio is elevated. But, when AST is higher than ALT, a muscle, source of these enzymes should be considered. Among the given options, only acid maltase deficiency (Pompe''s disease) is myopathic form of glycogen storage disease (muscular glycogenosis). Thus, AST/ALT ratio may be more than 2. Other three options are liver glycogenoses (AST/ALT < 1, as ALT is raised more than AST).","pyqMatches":[{"year":"2014","no":359,"q":"AST/ALT > 2 occurs in deficiency of","o":["Glucose-6-phosphotase","Branching enzyme","Acid maltase","Liver phosphorylase"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1292, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 411, '{"id":1292,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":411,"q":"LDH has how many isoenzymes","o":["3, based on B and M polypeptide subunits","5, based on B and M polypeptide subunits","7, based on H and M polypeptide subunits","5, based on H and M polypeptide subunits"],"a":3,"e":"Ans. is ''d'' i.e., 5, based on H and M polypeptide subunits lRef: Dinesh puri 3''d/e p. 1221 LDH is a tetramer with two types of polypeptide units : (H) (for heart) and M (for muscle). lt has five isoenzymes: LDH 1 (HHHH), LDH 2 (HHHM), LDH3 (HHMM), LDH 4 (HMMM), and LDH s (MMMM). LDH-I and LDH-2 are the predominant isozymes in myocardium, therefore these are raised in MI (LDHf > LDH2), LDH-f is more specific for myocardium (as it has 4H) than LDH-2. The predominent isoenzyme in liver is LDH5; Hence LDH5 is raised in liver diseases like viral hepatitis. Normal LDH pattern on electrophoresis is LDH2 > LDHI > LDH 3 > LDH 4 > LDH5. In MI LDHI is raised more thar LDHz, So, pattern becomes LDHI > LDH2 > LDH3 > LDH4 > LDH5. Increase in total LDH level is also seen in hemolytic anemia, hepatocellular damage, muscular dystrophies, leukemia, carcinomas, cerebrovascular accident, pancreatitis, kidney disease, intestinal and pulmonary infarction, megaloblastic anemia and infectious mononucleosis. Therefore study of specific isozyme is more significant.","pyqMatches":[{"year":"2015","no":292,"q":"LDH has how many isoenzymes","o":["3, based on B and M polypeptide subunits","5, based on B and M polypeptide subunits","7, based on H and M polypeptide subunits","5, based on H and M polypeptide subunits"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1293, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 412, '{"id":1293,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":412,"q":"Example of allosteric inhibition","o":["Inactivation of glycogen synthase by phosphorylation","Decreased synthesis of glucokinase by glucagon","Inhibition of PFK-1 by citrate","All of the above"],"a":2,"e":"Answer-Ans. is ''c'' i.e., Inhibition of PFK-l by citrate [lRef, Dinesh puri 3d/e p. 1161 ] Enzyme:-Phosphofructokinase I Pathway:- Glycolysis Stimulator:- AMP, ADP, fructose-6-phosphaie, fuctose-2,6- bisphophate. Inhibitor:- ATP, citrate, Ca2+, Mg+","pyqMatches":[{"year":"2015","no":296,"q":"Example of allosteric inhibition","o":["Inactivation of glycogen synthase by phosphorylation","Decreased synthesis of glucokinase by glucagon","Inhibition of PFK-1 by citrate","All of the above"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1294, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 413, '{"id":1294,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":413,"q":"Lysyl oxidase requires which cofactor -","o":["Zn","Cu","Se","Fe"],"a":1,"e":"Ans. is''b''i.e., Cu [Rel Harper 27t''/e p. 546] metal metalloenzymes Calcium Lipase, Lecithinase Copper Cytochrome oxidase, Tyrosinase, Lysyl oxidase, Superoxide dismutase, Ascorbic acid oxidase, Ferroxidase (ceruloplasmin) iron Cytochrome oxidase, Xanthine oxidase, Catalase, Peroxidase Zinc Carbonic anhydrase, alkaline phosphatase, RNA polymerase, alcohol dehydrogenase, Carboxypeptidase, Prophobilinogen synthase, glutamate dehydrogenase, lactate dehydrogenase, Superoxide dismutase Magnesium Hexokinase, phosphofructokinase, glucose-6- phosphatase, enolase, creatinine kinase, Phosphatases, kinase Manganese Arginase, Pyruvate carboxylase, phosphoglucomutase, Glycosyl transferase, Hexokinase, Enolase Potassium Pyruvate kinase Selenium Glutathione peroxidase Nickel Urease molybednumXanthine oxidase molybednumXanthine oxidase","pyqMatches":[{"year":"2015","no":297,"q":"Lysyl oxidase requires which cofactor","o":["Zn","Cu","Se","Fe"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1295, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 414, '{"id":1295,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":414,"q":"Mechanism of conversion of trypsinogen to trypsin -","o":["Hydrolysis","Phosphorylation","Removal of part of protein","Removal of Carboxyl group"],"a":2,"e":"Ans. is''c''i.e., Removal of part of protein [Ref: Dinesh puri 3''d/e p- 1181 All zymogens (including trypsinogen) are activated by removal of a small length of protein (few amino acids) from one end of the molecule. Trypsinogen → → Trypsin + peptide fragent Pepsinogen → → pepsin +peptide fragment","pyqMatches":[{"year":"2015","no":298,"q":"Mechanism of conversion of trypsinogen to trypsin","o":["Hydrolysis","Phosphorylation","Removal of part of protein","Removal of Carboxyl group"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1296, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 415, '{"id":1296,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":415,"q":"True about NADP -","o":["Acts as coenzyme form of Niacin","Involved in HMP shunt","Not involved in glycolysis","All are true"],"a":3,"e":"Ans. is''d''i.e., All are true Niacin, in the form of nicotinamide, is incorporated into the structure of two coenzymes: nicotinamide adenine dinucleotide (NAD+ ) and nicotinamide adenine dinucleotide phosphate (NADP+) NADP is involved in HMP shunt and NAPDH is produced. In glycolysis NAD is involved (not NADP).","pyqMatches":[{"year":"2015","no":301,"q":"True about NADP","o":["Acts as coenzyme form of Niacin","Involved in HMP shunt","Not involved in glycolysis","All are true"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1297, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 416, '{"id":1297,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":416,"q":"In malate shuttle, NADH Produces how many ATPs","o":["1","1-5","2","2.5"],"a":3,"e":"Ans-is''d''i.e., 2.5 (Ref : Harp* 2*/e p. 129-130) In glycerophosphate shuttle, the mitochondrial ennlme is linked to respiratory chain (ETC) via a flavoprotein, So only l.5 mol of ATP are produced (According to older calculations,2 ATP mol of ATP are produced). In malate shuttle, the mitochondrial enzyme is linked to ETC via NAD, so 2.5 mol of ATP are produced (according to older calculations 3 mol of ATP are produced).","pyqMatches":[{"year":"2015","no":302,"q":"In malate shuttle, NADH Produces how many ATPs","o":["1","1-5","2","2.5"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1298, 'Biochemistry', 'Enzymes', 'Moderate', 'Biochemistry', 417, '{"id":1298,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Moderate","source":"Biochemistry","sourceNo":417,"q":"Pyruvate dehydrogenase requires all cofactors except","o":["Thiamin","Riboflavin","Niacin","Pyridoxin"],"a":3,"e":"Ans. is ''d'' i.e., Pyridoxin [Ref Harper 29thle p. 176] Pyruvate dehydrogenase catalyses oxidative decarboxylation of pyruvate to acetyl CoA. The coenzyme required by PDH are :-","pyqMatches":[{"year":"2015","no":304,"q":"Pyruvate dehydrogenase requires all cofactors except","o":["Thiamin","Riboflavin","Niacin","Pyridoxin"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1299, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 418, '{"id":1299,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":418,"q":"Lactate produced anaerobically is used by","o":["Gluconeogenesis & Glycolysis","Cori cycle & gluconeogenesis","TCA cycle & Glycogenolysis","Cori cycle only"],"a":1,"e":"Ans. is ''b''i.e., cori cycle & gluconeogenesis [Ref Lehninger 4h/e p. 523,53g-391 Cori cycle or lactic acid cycle Anaerobic glycolysis in muscles results in the production of lactate, which cannot be converted into glucose, as gluconeogenesis does not occur in muscles. Through blood, Lactate is transported to the liver where it is oxidized to pyruvate. pynrvate so produced, is converted to glucose by gluconeogenesis, which is then transported to the muscle. The glucose thus reformed from lactate again becomes available for energy purpose in skeletal muscle.","pyqMatches":[{"year":"2015","no":305,"q":"Lactate produced anaerobically is used by","o":["Gluconeogenesis & Glycolysis","Cori cycle & gluconeogenesis","TCA cycle & Glycogenolysis","Cori cycle only"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1300, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 419, '{"id":1300,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":419,"q":"Citrate synthase is inhibited by -","o":["ATP","ADP","Insulin","Glucagon"],"a":0,"e":"Ans. is''a''i.e., ATP [Ref Chatterjee & Shinde Vh/e p. 171,166- 180; Harper 28th/e p. 145-147","pyqMatches":[{"year":"2015","no":306,"q":"Citrate synthase is inhibited by","o":["ATP","ADP","Insulin","Glucagon"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1301, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 420, '{"id":1301,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":420,"q":"Fumarate is formed from which amino acid","o":["Methionine","Valine","Histidine","Tyrosine"],"a":3,"e":"Ans. is ''d'' i.e., Tyrosine [Ref Harper 29th/e p. 166-67] All major members of the citric acid cycle from citrate to oxaloacetate are glucogenic and therefore, are involved in gluconeogenesis. Some glucogenic amino acids enters the TCA cycle after transamination e.g.:","pyqMatches":[{"year":"2015","no":307,"q":"Fumarate is formed from which amino acid","o":["Methionine","Valine","Histidine","Tyrosine"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1302, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 421, '{"id":1302,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":421,"q":"The major role of 2, 3 bisphosphoglycerate in RBCs is -","o":["Acid-base balance","Reversal of glycolysis","Release of oxygen","Binding of oxygen"],"a":2,"e":"Ans. is ''c'' i.e.,Release of Oxygen [Ref Lehninger ilthie p. 171] Rapoport Luebering cycle (Bisphosphoglycerate shunt) This cycle occurs in erythrocytes (ABCs). In this production of ATP by substrate phosphorylation from 1,3-BPG is bypassed by taking diversion pathways, i.e., side reaction of glycolytic pathway. In this cycle, 1,3-BPG is converted to 2,3 BPG by an enzyme bisphosphoglycerate mutase. Then 2,3 BPG is converted to 3- phospholycerate by 2,3-bisphosphoglycerate phosphatase.","pyqMatches":[{"year":"2015","no":308,"q":"The major role of 2, 3 bisphosphoglycerate in RBCs is","o":["Acid-base balance","Reversal of glycolysis","Release of oxygen","Binding of oxygen"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1303, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 422, '{"id":1303,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":422,"q":"Enzyme deficient in Hers disease -","o":["Muscle phosphorylase","Liver phosphorylase","Acid maltase","Debranching enzyme"],"a":1,"e":"Ans. is B'' i.e., Liver phosphorylase [Ref Harper 250/e p. 181 ] Type Enzyme deficiency Organ (s) affected I von Gierke''s disease Glucose 6-phosphatase Liver, kidney II Pompe''s disease alpha (1 → 4) Glucosidase (acid maltase) All organs III Cori''s disease/Forbe''s disease Debranching enzyme Muscle, liver IV Andersen''s disease Branching enzyme Liver, myocardium V McArdle''s disease Phosphorylase Muscle VI Hers'' disease Phosphorylase Liver VII Tarui''s disease Phosphofructokinase Muscle, RBCs VIII Phosphorylase kinase Liver","pyqMatches":[{"year":"2015","no":309,"q":"Enzyme deficient in Hers disease","o":["Muscle phosphorylase","Liver phosphorylase","Acid maltase","Debranching enzyme"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1304, 'Biochemistry', 'Miscellaneous', 'Moderate', 'Biochemistry', 423, '{"id":1304,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Biochemistry","sourceNo":423,"q":"Immediate metabolic products during conversion of Fructus 1-6 bisphosphate to 2 molecules of pyruvate -","o":["Glyceraldehyde-3-phosphate and 1,3-bisphosphoglycerate","Dihydroxyacetone phosphate and 1,3 bisphos​phoglycerate","Glyceraldehyde-3-phosphate and dihydroxy-acetone phosphate","3-phosphoglycerate and 1,3 bisphosglycerate"],"a":2,"e":"Ans. is ''c'' i.e., Glyceraldehyde-3-phosphate and dihydroxyacetone phosphate (Ref: Harper 29h/e p. 170-177).","pyqMatches":[{"year":"2015","no":310,"q":"Immediate metabolic products during conversion of Fructus 1-6 bisphosphate to 2 molecules of pyruvate","o":["Glyceraldehyde-3-phosphate and 1,3-bisphosphoglycerate","Dihydroxyacetone phosphate and 1,3 bisphos​phoglycerate","Glyceraldehyde-3-phosphate and dihydroxy-acetone phosphate","3-phosphoglycerate and 1,3 bisphosglycerate"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1305, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 424, '{"id":1305,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":424,"q":"In conversion of glucose to glucose-6- phosphate in glycolysis true is","o":["Glucokinase has low km","Hexokinase is found only in liver","Glucokinase is induced by insulin","Hexokinase is not specific for glucose"],"a":2,"e":":D Ans. is ''c'' i.e., Glucokinase is induced by insulin & ''d'' i.e., Hexokinase is not specific for glucose (Ref: Harper 29h/e p. 170-177; Vasudevan #/e p. 98) Hexokinase is not specific for glucose metabolism. It is found in most tissues except glucose. Glucokinase has high KM. It is induced by insulin.","pyqMatches":[{"year":"2015","no":311,"q":"In conversion of glucose to glucose-6- phosphate in glycolysis true is","o":["Glucokinase has low km","Hexokinase is found only in liver","Glucokinase is induced by insulin","Hexokinase is not specific for glucose"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1306, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 425, '{"id":1306,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":425,"q":"Major carbohydrate store in the body -","o":["Blood glucose","Glycogen in adipose tissue","Hepatic glycogen","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., Hepatic glycogen (Ref: Harper 29/e p. 161; Dinesh puri 3d/e p. 320) Major Carbohydrate source of body is hepatic glycogen. Humans carry supplies of fuel within their body. Calories are stored in the body as fat (triglycerides), glycogen and some protein.","pyqMatches":[{"year":"2015","no":312,"q":"Major carbohydrate store in the body","o":["Blood glucose","Glycogen in adipose tissue","Hepatic glycogen","None of the above"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1307, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 426, '{"id":1307,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":426,"q":"Most abundant source of fuel in starvation -","o":["Liver glycogen","Muscle glycogen","Adipose tissue","Blood glucose"],"a":2,"e":"Ans. is ''c'' i.e., Adipose tissue [Ref Harper 29thle p. 161 & 28th le p. 134, 140; Vasudevan 6th/e p. 84, 85] Fat (triglycerides) in the adipose tissue is the largest store of energy of the body.","pyqMatches":[{"year":"2015","no":313,"q":"Most abundant source of fuel in starvation","o":["Liver glycogen","Muscle glycogen","Adipose tissue","Blood glucose"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1308, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 427, '{"id":1308,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":427,"q":"Major metabolism of saturated fatty acids in the mitochondria is called as -","o":["β-oxidation","α-oxidation","ω-oxidation","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., β-oxidation [Ref Harper 29\"''/e p. 208] β-oxidation is the principal pathway for catabolism of saturated fatty acids. P-oxidation mainly occurs in the mitochondrial matrix (whereas fatty acid synthesis occurs in cytosol).","pyqMatches":[{"year":"2015","no":314,"q":"Major metabolism of saturated fatty acids in the mitochondria is called as","o":["β-oxidation","α-oxidation","ω-oxidation","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1309, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 428, '{"id":1309,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":428,"q":"Which method is used to separate a mixture of lipids -","o":["Electrophoresis","Chromatography","Isoelectric focusing","PAGE"],"a":1,"e":"Ans. is ''b'' i.e., Chromatography [Ref Clinical biochemistry p. 719] Extracted lipids are separated into individual class by chromatography. Chromatography can separate a complex mixture of lipids into simpler group. Various types of chromatography, used to separate, lipids are - Adsorption (solid-liquid) chromatography Partition (liquid-liquid) chromatography Thin layer chromatography (TLC) Gas chromatography (GC) High performance liquid chromatography (HPLC) -› method of choice if available.","pyqMatches":[{"year":"2015","no":316,"q":"Which method is used to separate a mixture of lipids","o":["Electrophoresis","Chromatography","Isoelectric focusing","PAGE"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1310, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 429, '{"id":1310,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":429,"q":"Chylomicrons core is formed by ?","o":["Triglyceride","Triglyceride and Cholesterol","Triglyceride, Cholesterol and Phospholipids","Free fatty acids"],"a":1,"e":"Ans. is ''B'' i.e., Triglyceride and Cholesterol [Ref Harper 27th/e p. 218; Lehninger 4th/e p. 633] The surface is a layer of phospholipids, with head groups facing the aqueous phase. Triacylglycerols sequestered in the interior make up more than 80% of the mass. Several apolipoproteins that protrude from the surface (B-48, C-III, C-II) act as signals in the uptake and metabolism of chylomicron contents. The diameter of chylomicrons ranges from about 100 to 500 nm. Core: It''s made up of neutral lipids like triacylglycerols and cholesterol/cholesterol esters. Shell: composed of apolipoproteins, phospholipids.","pyqMatches":[{"year":"2015","no":318,"q":"Chylomicrons core is formed by ?","o":["Triglyceride","Triglyceride and Cholesterol","Triglyceride, Cholesterol and Phospholipids","Free fatty acids"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1311, 'Biochemistry', 'Miscellaneous', 'Moderate', 'Biochemistry', 430, '{"id":1311,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Biochemistry","sourceNo":430,"q":"All are true about Niemann- Pick disease except -","o":["Due to deficiency of sphingomyelinase","CNS symptoms in type A","Histiocytes showing PAS positive inclusions and Type B is less severe","None"],"a":3,"e":"Ans. is D. None [Ref Clinical biochemistry 4th/e p. 786] Niemann-Pick disease is an autosomal recessive `lysosomal storage disease due to deficiency of sphingomyelinase. Characteristic histopathological feature is histiocytes showing PAS positive diastase resistant inclusions which on microscopy shows concentric or parrallel lamellar arrangement. Clinical cases are divided into -","pyqMatches":[{"year":"2015","no":320,"q":"All are true about Niemann- Pick disease except","o":["Due to deficiency of sphingomyelinase","CNS symptoms in type A","Histiocytes showing PAS positive inclusions and Type B is less severe","None"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1312, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 431, '{"id":1312,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":431,"q":"Acetyl CoA Carboxylase is stimulated by -","o":["Starvation","Glucagon","Citrate","All of the above"],"a":2,"e":"Ans. is ''c'' i.e., Citrate [Ref Harper 29th/e p. 219] Activator Inhibitor Allosteric (palmitoyl CoA)Citrate Long chain acyl-CoA Covalent Insulin Glucagon, epinephrine","pyqMatches":[{"year":"2015","no":322,"q":"Acetyl CoA Carboxylase is stimulated by","o":["Starvation","Glucagon","Citrate","All of the above"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1313, 'Biochemistry', 'Lipid Metabolism', 'Moderate', 'Biochemistry', 432, '{"id":1313,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":432,"q":"Cholesterol is not a precursor for synthesis of -","o":["Vitamin D","Progesterone","Bile acids","Lipocortin"],"a":3,"e":"Ans. is ''d'' i.e., Lipocortin Cholesterol is an important precursor for the synthesis of :-","pyqMatches":[{"year":"2015","no":324,"q":"Cholesterol is not a precursor for synthesis of","o":["Vitamin D","Progesterone","Bile acids","Lipocortin"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1314, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 433, '{"id":1314,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":433,"q":"HDL is called good cholesterol because -","o":["Removes cholesterol from extrahepatic tissues","Causes transport of cholesterol to extrahepatic tissues","Stimulate hepatic TGs synthesis","Activates lipoprotein lipase"],"a":0,"e":"Ans. is ''a'' i.e., Removes cholesterol from extrahepatic tissues The HDL particles are referred to as scavengers because their primary role is to remove free (unesterified) cholesterol from extrahepatic tissues, which is then excreted through bile. This is a crucial mechanism that prevents the inappropriate accumulation of cholesterol in peripheral tissues. Because accumulation of cholesterol in tissues is strongly associated with the development of atherosclerosis, the level of HDL in serum is inversely related to the incidence of MI (myocardial infarction). Thus, HDL is cardioprotective and anti-atherogenic in nature, and is referred to as \"good cholesterol\". Therefore, HDL-Cholesterol appears to be the best independent predictor of coronary artery disease (inverse relationship) than any other known risk factor. That means low HDL is a much stronger predictor of coronary artery disease than increased LDL cholesterol or increased total cholesterol.","pyqMatches":[{"year":"2015","no":325,"q":"HDL is called good cholesterol because","o":["Removes cholesterol from extrahepatic tissues","Causes transport of cholesterol to extrahepatic tissues","Stimulate hepatic TGs synthesis","Activates lipoprotein lipase"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1315, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 434, '{"id":1315,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":434,"q":"Amide group is present in which part of protein -","o":["Amino-terminal","Carboxy-terminal","Peptide bond","Disulfide bond"],"a":2,"e":"Ans. is ''c'' i.e., Peptide bond [Ref Text book of biochemistry by Talwar - p. 30] A peptide bond is a chemical bond that connects amino acids to each other. A peptide bond essentially results from a dehydration synthesis reaction. It is formed between two amino acids when the carboxyl group of one amino acid reacts with the amino group of the other, releasing a molecule of water (H20). Peptide bond is the resulting CO-NH bond and the resulting molecule is an amide. The four-atom functional group - C (=0) NH- is called an amide group or peptide group. Peptide bond is a partial double bond. Partial double bond nature renders the amide group planar and rigid, making all the atoms that are involved in the peptide bond lie in a flat plane.","pyqMatches":[{"year":"2015","no":326,"q":"Amide group is present in which part of protein","o":["Amino-terminal","Carboxy-terminal","Peptide bond","Disulfide bond"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1316, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Moderate', 'Biochemistry', 435, '{"id":1316,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":435,"q":"Non- essential amino-acids are all except -","o":["Basic amino acids","Acidic amino acids","Neutral amino acids","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Basic amino acids [Ref Harper 29th/e p. 266] There, are three basic amino acids (Arginine, Histidine and lysine), all of them are essential amino acids Essential amino acids (PVT. TIM. HALL) : Phenylalanine, valine, threonine, tryptophan, isoleucine, methionine, histidine, arginine, lysine, leucine. Among these, arginine and histidine are semiessential amino acids. Nonessential amino acids : alanine, aspartic acid, aspargine, cysteine, glutamine, glutamic acid, glycine, proline, tyrosine, serine. Neutral amino acids: Alanine , asparagine, cysteine, glycine, glutamine, isoleucine, leucine, methionine, proline, phenylalanine, serine, threonine, tyrosine, tryptophan, valine. Acidic amino acids (negatively charged or anion) : Aspartic acid (aspartate), glutamic acid (glutamate). Basic amino acids (positively charged or cation) : Arginine, histidine, lysine.","pyqMatches":[{"year":"2015","no":327,"q":"Non- essential amino-acids are all except","o":["Basic amino acids","Acidic amino acids","Neutral amino acids","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1317, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 436, '{"id":1317,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":436,"q":"Amino acid which can be used in both gluconeogenesis and ketogenesis -","o":["Threonine","Valine","Tyrosine","Arginine"],"a":2,"e":"Ans. is ''c'' i.e., Tyrosine [Ref Chatterjee 5''''/e p. 448] Amino acids which can be used both in gluconeogenesis and ketogenesis (Both glucogenic & ketogenic amino acids) are :-","pyqMatches":[{"year":"2015","no":328,"q":"Amino acid which can be used in both gluconeogenesis and ketogenesis","o":["Threonine","Valine","Tyrosine","Arginine"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1318, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 437, '{"id":1318,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":437,"q":"In phenylketonuria, diet restriction is advised for -","o":["Tyrosine","Phenylalanine","Maize","All"],"a":1,"e":"Ans. is ''b'' i.e., Phenylalanine, The main treatment is a phenylalanine restricted diet for life.","pyqMatches":[{"year":"2015","no":329,"q":"In phenylketonuria, diet restriction is advised for","o":["Tyrosine","Phenylalanine","Maize","All"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1319, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 438, '{"id":1319,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":438,"q":"Guanidinium group is associated with -","o":["Tyrosine","Arginine","Histidine","Lysine"],"a":1,"e":"Some amino acids contain a special functional group in their side chain which provides some specific functions to that amino acids. These are","pyqMatches":[{"year":"2015","no":330,"q":"Guanidinium group is associated with","o":["Tyrosine","Arginine","Histidine","Lysine"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1320, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 439, '{"id":1320,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":439,"q":"Coenzyme for phenylalanine hydroxylase is -","o":["Tetrahydrofolate","Pyridoxal phosphate","S-adenosyl methionine","Tetrahydrobiopterin"],"a":3,"e":"Ans. is ''d'' i.e., Tetrahydrobiopterin Phenylalanine metabolism is initiated by its oxidation to tyrosine which then undergoes oxidative degradation","pyqMatches":[{"year":"2015","no":332,"q":"Coenzyme for phenylalanine hydroxylase is","o":["Tetrahydrofolate","Pyridoxal phosphate","S-adenosyl methionine","Tetrahydrobiopterin"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1321, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 440, '{"id":1321,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":440,"q":"Which of the following is required in the synthesis of acetylcholine -","o":["Inositol","Carnitine","Glycine","Choline"],"a":3,"e":"Ans. is ''d'' i.e., Choline [Ref Principles of medical physiology p. 96] Acetylcholine is synthesized in the cytosol of nerve terminal from acetyl-CoA and choline, in the presence of choline-0- acetyltransferase","pyqMatches":[{"year":"2015","no":334,"q":"Which of the following is required in the synthesis of acetylcholine","o":["Inositol","Carnitine","Glycine","Choline"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1322, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 441, '{"id":1322,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":441,"q":"Most important factor which causes lactic acidosis in alcoholics -","o":["Pruduction of NADH","Formation of acetaldehyde","Production of acetate","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Production of NADH [Ref Pankaj Naik 3rd/e p. 351] Excess intake of alcohol leads to excessive production of NADH with a concomitant decrease in NAD.. The increased availability of NADH favours the reduction of pyruvate to lactate and oxaloacetate to malate and decreasing its availability for gluconeogenesis and decrease synthesis of glucose. This results in Hypoglycemia. Excess of lactate production leads to lactic acidosis","pyqMatches":[{"year":"2015","no":335,"q":"Most important factor which causes lactic acidosis in alcoholics","o":["Pruduction of NADH","Formation of acetaldehyde","Production of acetate","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1323, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 442, '{"id":1323,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":442,"q":"Insulin dependant cells are -","o":["Pituitocytes","Myocytes","Adipocytes","RBCs"],"a":1,"e":":C Ans. is ''b'' i.e., Myocytes & ''c'' i.e., Adipocytes [Ref Ganong 24th/e p. 435] Insulin stimulates the uptake of glucose by myocytes (skeletal muscle, cardiac muscle), adipocytes (adipose tissue) and hepatocytes. Tissues that do not depend on insulin for glucose uptake include brain, erythrocytes (RBC), the epithelial cells of kidney & intestine, Liver, and Cornea & lens of the eye. In the liver, insulin stimulates glucose entry into hepatocytes indirectly by induction of glucokinase so that the glucose entering the liver cells is promptly converted to glucose - 6 - phosphate (glucose trapping). This keeps the intracellular glucose concentration low and favours entry of glucose into the liver. Thus, though the liver do not depend on insulin for glucose uptake, insulin stimulates glucose entry into hepatocytes. That means glucose entry can occur in liver without the action of insulin, but this is facilitated by insulin. On the other hand, myocytes (skeletal and cardiac muscles) and adipocytes (adipose tissue) are dependent on insulin for glucose uptake.","pyqMatches":[{"year":"2015","no":337,"q":"Insulin dependant cells are","o":["Pituitocytes","Myocytes","Adipocytes","RBCs"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1324, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 443, '{"id":1324,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":443,"q":"Epinephrine increases free fatty acid level by causing -","o":["Increased fatty acid synthesis","Increasing lipolysis","Increasing cholesterol catabolism","All of the above"],"a":1,"e":"Ans. is ''b'' i.e., Increasing lipolysis [Ref Pankaj Naik %tale p. 248] Epinephrine and glucagon accelerate lipolysis in adipose tissue by activating hormone sensitive lipase. In starvation and diabetes, glucagon is high (and insulin is low), leading to enhanced lipolysis.","pyqMatches":[{"year":"2015","no":338,"q":"Epinephrine increases free fatty acid level by causing","o":["Increased fatty acid synthesis","Increasing lipolysis","Increasing cholesterol catabolism","All of the above"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1325, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 444, '{"id":1325,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":444,"q":"Vitamin formed in the body -","o":["B 1","B 3","B 6","B 12"],"a":0,"e":":B:D Ans. is ''b > a & d'' i.e., B3 > B1 & B12 This question is confusing one (Read text below). Niacin (Vitamin B3) is synthesized from tryptophan inside the body(endogenous). Some vitamins are also formed by bacterial activity in colon :-","pyqMatches":[{"year":"2015","no":341,"q":"Vitamin formed in the body","o":["B 1","B 3","B 6","B 12"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1326, 'Biochemistry', 'Carbohydrate Metabolism', 'Moderate', 'Biochemistry', 445, '{"id":1326,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":445,"q":"Which of the following is not seen in 12 days of fasting -","o":["Gluconeogenesis","Ketogenesis","Lipolysis","Glycolysis"],"a":3,"e":"Ans. is i.d.e., Glycolysis [Ref Harper 28''Ve p. 140; Dinesh purl 3''/e p. 414] Duration Early stage Intermediate stage (3-24 d) Late state {> 24 d} Pathways enhanced Glycogenolysis Gluconeogenesis Lipolysis Ketogenesis↑ Protein degradation ↑ Gluconeogenesis Lipolysis↑ Ketogenesis ↑ Ketone body oxidation ↑↑ Ketone body oxidation By brain ↑↑ By other tissues↑↑↑ Fatty acid utilization↑↑ Gluconeogenesis ↑↑ Pathways slowed Protein degradation Protein synthesis Glycolysis TCA Protein synthesis and degradation Glycogen synthesis and degradation","pyqMatches":[{"year":"2015","no":342,"q":"Which of the following is not seen in 12 days of fasting","o":["Gluconeogenesis","Ketogenesis","Lipolysis","Glycolysis"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1327, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 446, '{"id":1327,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":446,"q":"Pyridoxine is required in -","o":["Glycolysis","TCA cycle","Glycogenesis","Glycogenolysis"],"a":3,"e":"Ans. is ''d'' i.e., Glycogenolysis [Ref Dinesh puri p. 187; Harper 29th/e p. 180 & 27th/e p. 159-160] PLP is a cofactor for glycogen phosphorylase, hence it favors glycogenolysis.","pyqMatches":[{"year":"2015","no":343,"q":"Pyridoxine is required in","o":["Glycolysis","TCA cycle","Glycogenesis","Glycogenolysis"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1328, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 447, '{"id":1328,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":447,"q":"Pruritis [Itching] is caused by deficiency of -","o":["HMB synthase","5-ALA dehydratase","Uroporphyrinogen - I synthase","Uroporphyrinogen - III synthase"],"a":3,"e":"Ans. is ''d'' i.e., Uroporphyrinogen - III synthase [Ref Rooks 7th/e p. 12.7, 12.8] Cutaneous (erythropoietic) porphyrias cause skin manifestations like photosensitivity, rash and pruritus. Among the given options, Uroporphyrinegen III synthase deficiency causes cutaneous porphyria (Congenital erythropoietic porphyria).","pyqMatches":[{"year":"2015","no":344,"q":"Pruritis [Itching] is caused by deficiency of","o":["HMB synthase","5-ALA dehydratase","Uroporphyrinogen - I synthase","Uroporphyrinogen - III synthase"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1329, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 448, '{"id":1329,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":448,"q":"Vitamin acting on intranuclear receptors -","o":["Vitamin K","Vitamin D","Vitamin E","Vitamin E"],"a":1,"e":"Ans. is ''b'' i.e.,Vitamin D [Ref Understandings medical physiology p. 408] Two vitamins are considered as hormones which act on intranuclear receptors (steroid receptor family). There are :-","pyqMatches":[{"year":"2015","no":345,"q":"Vitamin acting on intranuclear receptors","o":["Vitamin K","Vitamin D","Vitamin E","Vitamin E"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1330, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 449, '{"id":1330,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":449,"q":"Niacin acts as coenzyme -","o":["TPP","FAQ","NAD","NAD"],"a":2,"e":"Ans. is ''c'' i.e.,NAD Niacin, in the form of nicotinamide, is incorporated into the structure of two coenzymes : nicotinamide adenine dinucleotide (NAD*) and nicotinamide adenine dinucleotide phosphate (NADI)*).","pyqMatches":[{"year":"2015","no":347,"q":"Niacin acts as coenzyme","o":["TPP","FAQ","NAD","NAD"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1331, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Moderate', 'Biochemistry', 450, '{"id":1331,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":450,"q":"Not a metabolic product of urea cycle -","o":["Citrulline","Ornithine","Alanine","Arginine"],"a":2,"e":"Ans. is ''c'' i.e., Alanine Metabolic products in urea cycle are carbamoyl phosphate, ornithine, citrulline, argininosuccinate, arginine and fumarate. Biosynthesis of urea occurs in five steps 1- Carbamoyl phosphate synthetase-I (CPS-I), a mitochondrial enzyme, catalyzes the formation of carbamoyl phosphate by condensation of CO, and ammonia. 2- Ornithine transcarbamoylase catalyzes the formation of citrulline from carbamoyl phosphate and ornithine. 3- Argininosuccinate synthase catalyzes the formation of argininosuccinate from citrulline and aspartate. This reaction requires !ATP, 4- Argininosuccinate lyase (arginosuccinase) catalyses the cleavage of argininosuccinate into arginine and fumarate. Fumarate enters TCA cycle. 5- ) Arginase catalyses the formation of urea from arginine by hydrolytic cleavage of arginine to yield urea and ornithine. Ornithine is thus regenerated and can enter mitochondria to initiate another round of the urea cycle.","pyqMatches":[{"year":"2015","no":349,"q":"Not a metabolic product of urea cycle","o":["Citrulline","Ornithine","Alanine","Arginine"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1332, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 451, '{"id":1332,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":451,"q":"Which amino acid is not involved in transamination -","o":["Alanine","Aspartate","Lysine","Histidine"],"a":2,"e":"Ans. is ''c'' i.e.,Lysine Most amino acids undergo transamination reaction except lysine, threonine, proline and hydroxyproline.","pyqMatches":[{"year":"2015","no":350,"q":"Which amino acid is not involved in transamination","o":["Alanine","Aspartate","Lysine","Histidine"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1333, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 452, '{"id":1333,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":452,"q":"Apo B48 is synthesized in -","o":["Liver","Kidney","Intestine","RBCs"],"a":2,"e":"Ans. is ''c'' i.e.,Intestine It mediate uptake of LDL by LDL receptors of liver,","pyqMatches":[{"year":"2015","no":352,"q":"Apo B48 is synthesized in","o":["Liver","Kidney","Intestine","RBCs"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1334, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 453, '{"id":1334,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":453,"q":"What are okazzaki fragments -","o":["Long pieces of DNA on lagging strand","Long pieces of DNA on leading strand","Short pieces of DNA on lagging strand","Short pieces of DNA on leading strand"],"a":2,"e":"Ans. is ''c'' i.e., Short pieces of DNA on lagging strand [Ref: Lippincott''s 5thie p. 399, 401, 406] DNA polymerases responsible for copying the DNA templates are only able to \"read\" the parental nucleotide sequence in 3'' - 5'' direction, and they synthesize the new DNA strands only in 5'' - 3''direction. Therefore, 2 newly synthesized chains must grow in opposite directions :?","pyqMatches":[{"year":"2015","no":356,"q":"What are okazzaki fragments","o":["Long pieces of DNA on lagging strand","Long pieces of DNA on leading strand","Short pieces of DNA on lagging strand","Short pieces of DNA on leading strand"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1335, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 454, '{"id":1335,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":454,"q":"C4, C5, N7 in purine ring are derived from -","o":["Aspartate","Glutamine","Glutamine","CO"],"a":2,"e":"Ans. is ''c'' i.e., Glycine [Ref Harper 29th/e p. 332] In de novo synthesis, purine ring is formed from a variety of precursors is assembled on ribose-5-phosphate. Precursors for de novo synthesis are ?","pyqMatches":[{"year":"2015","no":358,"q":"C4, C5, N7 in purine ring are derived from","o":["Aspartate","Glutamine","Glutamine","CO"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1336, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 455, '{"id":1336,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":455,"q":"If content of A is 15%, what is the amount of G in DNA according to Chargaff s rule?","o":["15%","85%","35%","70%"],"a":2,"e":"Ans. is ''c'' i.e., 35% [Ref Harper''s Illustrated biochemistry 27th/e p. 311-313] Chargaff''s rule: Amount of purine = Amount of pyrimidine (A + G = T + C) Also A+G+T+C= 100 Since A = T, Therefore 15 + G + 15 + C = 100 Since G = C, Therefore 30, + 2G = 100 2G = 70 4 G = 35","pyqMatches":[{"year":"2015","no":360,"q":"If content of A is 15%, what is the amount of G in DNA according to Chargaff s rule?","o":["15%","85%","35%","70%"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1337, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 456, '{"id":1337,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":456,"q":"cDNA from RNA is synthesized by -","o":["Helicase","DNA dependent DNA polymerase","Topoisomerase","Reverse transcriptase"],"a":3,"e":"Ans. is ''d'' i.e., Reverse transcriptase [Ref Satyanarayan 4th/e p. 550] The enzyme RNA dependent DNA polymerase (reverse transcriptase) is responsible for the formation of DNA from RNA. This DNA is complementary (c DNA) to viral RNA and can be transmitted into host DNA.","pyqMatches":[{"year":"2015","no":362,"q":"cDNA from RNA is synthesized by","o":["Helicase","DNA dependent DNA polymerase","Topoisomerase","Reverse transcriptase"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1338, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 457, '{"id":1338,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":457,"q":"Which is not a chaperon protein -","o":["Calnexin","Protein disulfide isomerase","Calreticulin","Calbindin"],"a":3,"e":"Ans. is ''d'' i.e., Calbindin [Ref Harper 29thle p. 598-599 & 28th/e p. 497] Some Chaperones and Enzymes Involved in Folding that are Located in the Rough Endoplasmic Reticulum:- BiP (immunoglobulin heavy chain binding protein) GRP94 (glucose-regulated protein) Calnexin Calreticulin PDI (protein disulfide isomerase) PPI (peptidyl prolyl cis-trans isomerase)","pyqMatches":[{"year":"2015","no":363,"q":"Which is not a chaperon protein","o":["Calnexin","Protein disulfide isomerase","Calreticulin","Calbindin"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1339, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 458, '{"id":1339,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":458,"q":"All are functions of glycosaminglycans except -","o":["Lubrication","Wound healing","Anticoagulant","Transport of lipids"],"a":3,"e":"Ans. is ''d'' i.e., Transport of lipids [Ref Pankaj Naik 4th/e p. 29]","pyqMatches":[{"year":"2015","no":364,"q":"All are functions of glycosaminglycans except","o":["Lubrication","Wound healing","Anticoagulant","Transport of lipids"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1340, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 459, '{"id":1340,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":459,"q":"Bile salts help in absorption of fat by -","o":["Micelles formation","Activation of transporter protein","Creation of concentration gradient","All of the above"],"a":0,"e":"Ans. is ''a'' i.e., Micelles formation [RefGangong24th le p. 465] Emulsification is the process which breaks down ingested fats (mainly triglycerides) into smaller droplets so that they can be digested more efficiently. Thus emulsification mainly helps in digestion of ingested fats. Micelles formation is the process in which digested fats (FFAs and monoglycerides) are incorporated into much smaller droplets (micelles) so that they can be absorbed more efficiently. Thus, micelles formation helps in absorption of digested fats. Detergent action of bile salts is necessary for both emulsification and micelles formation.","pyqMatches":[{"year":"2015","no":365,"q":"Bile salts help in absorption of fat by","o":["Micelles formation","Activation of transporter protein","Creation of concentration gradient","All of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1341, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 460, '{"id":1341,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":460,"q":"a-aminolevulinic acid is a metabolic product in synthesis of -","o":["Tryptophan","Collagen","Glycosaminoglycans","Heme"],"a":3,"e":"Ans. is ''d'' i.e., Heme Heme synthesis takes place in all cells, but occurs to greatest extent in bone marrow and liver. The first step in the synthesis of heme is the condensation of glycine and succinyl Co-A to form 6- aminolevulinic acid (6-ALA), which occurs in mitochondria. This reaction is catalyzed by 6-ALA synthase which requires pyridoxal phosphate (PLP) as cofactor. This is the rate limiting step in heme synthesis.","pyqMatches":[{"year":"2015","no":366,"q":"a-aminolevulinic acid is a metabolic product in synthesis of","o":["Tryptophan","Collagen","Glycosaminoglycans","Heme"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1342, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 461, '{"id":1342,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":461,"q":"Which is an inhibitor of ferrochelatase ?","o":["Lead","Mercury","Iron","Arsenic"],"a":0,"e":"Ans. is ''a'' i.e., Lead [Ref Essentials of biochemistry 4thie p. 919] Ferrochelatase, also called heme synthase, catalyses the last reaction in heme synthesis. Lead inhibits ALA dehydratase. Therefore, lead poisoning causes inhibition of heme synthesis and excessive amount of 6-ALA is excreted in urine. Lead can also inhibit ferrochelatase (heme synthase).","pyqMatches":[{"year":"2015","no":367,"q":"Which is an inhibitor of ferrochelatase ?","o":["Lead","Mercury","Iron","Arsenic"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1343, 'Biochemistry', 'Lipid Metabolism', 'Moderate', 'Biochemistry', 462, '{"id":1343,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":462,"q":"Bile acids consist of all except -","o":["Lithocholic acid","Taurocholic acid","Deoxycholic acid","Chendeoxycholic acid"],"a":1,"e":"Ans. is ''b'' i.e., Taurocholic acid [Ref Ganong 22na le ch. 26] Taurocholic acid is bile salt (not bile acid). Bile acids are mainly presents as sodium or potassium salts which are conjugated with glycine or taurine to form bile salts. Primary bile acids are cholic acid and chenodeoxycholic acid, which are synthesized from cholesterol in liver. In the intestine some of the primary bile acids are converted into secondary bile acids, i.e., deoxycholic acid (formed from cholic acid) and lithocholic acid (derived from chenodexoxycholic acid). Glycine and taurine conjugates of these bile acids are called as bile salts. For example, cholic acid is a bile acid, and its glycine conjugate (glycocholic acid) is a bile salt.","pyqMatches":[{"year":"2015","no":368,"q":"Bile acids consist of all except","o":["Lithocholic acid","Taurocholic acid","Deoxycholic acid","Chendeoxycholic acid"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1344, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 463, '{"id":1344,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":463,"q":"True about cAMP and cGMP -","o":["Second messengers","Act on membrane receptors","Act by post-translational modification","All of the above"],"a":3,"e":"Ans. is ''d'' i.e.,All of the above Second messengers Second messengers are molecules that relay signals from the membrane receptors to target molecules inside the cells. In above described receptors second messengers are cAMP, cGMP, Phosphatidylinositol, diacylgleceral, IP3, Ca. Secondary messengers of membrane receptors act by posttranslation modification, i.e., modification of proteins (e.g., enzymes) after they have already formed (i.e., after translation).","pyqMatches":[{"year":"2015","no":369,"q":"True about cAMP and cGMP","o":["Second messengers","Act on membrane receptors","Act by post-translational modification","All of the above"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1345, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 464, '{"id":1345,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":464,"q":"Spectroscopy is used for interaction of -","o":["Electromagnetic radiation","Protons","Alpha particles","Positrons"],"a":0,"e":"Ans. is ''a'' i.e.,Electromagnetic radiation Spectroscopy is the study of the structure of atoms/molecules from studying their interaction with electromagnetic radiation.","pyqMatches":[{"year":"2015","no":370,"q":"Spectroscopy is used for interaction of","o":["Electromagnetic radiation","Protons","Alpha particles","Positrons"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1346, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 465, '{"id":1346,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":465,"q":"Abnormal proteins which are bound to ubiquitin are degraded in -","o":["Proteosomes","Golgi apparatus","Smooth ER","Lysosomes"],"a":0,"e":"Ans. is ''a'' i.e.,Proteosomes [Ref Harper 250/e p. 560-561 & 28th/e p. 498-99] Ubiquitin plays major role in degradation of proteins and is particularly associated with disposal of misfoldedproteins. It is small, highly conserved protein that plays a key role in marking various proteins for subsequent degradation in proteosomes","pyqMatches":[{"year":"2015","no":371,"q":"Abnormal proteins which are bound to ubiquitin are degraded in","o":["Proteosomes","Golgi apparatus","Smooth ER","Lysosomes"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1347, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 466, '{"id":1347,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":466,"q":"Enzyme degradation is caused by -","o":["Ubiquitin","RNAse","Zymase","Chaperone"],"a":0,"e":"Ans. is ''a'' i.e., Ubiquitin [Ref Harper 29thie p. 560-561] Degradation of defective (misfolded) proteins (including enzymes) is caused by ubiquitin","pyqMatches":[{"year":"2015","no":372,"q":"Enzyme degradation is caused by","o":["Ubiquitin","RNAse","Zymase","Chaperone"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1348, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 467, '{"id":1348,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":467,"q":"G1cNAc-P-P- oligosacharride is -","o":["Proteoglycan","Glycoprotein","Collagen","Phospholipid"],"a":1,"e":"Ans. is ''b'' i.e., Glycoprotein [Ref Medical Biochemistry by Bhagvan p. 312] Dolichol plays a role in post-translational modification of protein by glycosylation to form glycoproteins. It acts in the form of Dolichol pyrophosphate (Dolichol PP) and transfer Oligosaccharide from dolichol to glycoproteins N-acetylgalactosamine-P-P-Dolichol (GLc NAc-P-P-dol) compound formed in the bionsynthesis of lipid-linked oligosaccharides. Dolichol -P-P acts as a carrier of oligosaccharide and transfer it to glycoprotein.","pyqMatches":[{"year":"2015","no":373,"q":"G1cNAc-P-P- oligosacharride is","o":["Proteoglycan","Glycoprotein","Collagen","Phospholipid"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1349, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 468, '{"id":1349,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":468,"q":"Prolyl hydroxylase require which cofactor -","o":["Sc","Vitamin C","Mo","Vitamin K"],"a":1,"e":"Ans. is ''b'' i.e., Vitamin C [Ref Harper 29''Ve p. 590-593] Hydroxylation of proline and lysine residue takes place during post- translational modification in rough ER. The enzyme catalyzing the reactions are prolyl hydroxylase (for proline) and lysyl hydroxylase (for lysine). Both these enzymes are dioxygenases using molecular oxygen (02) and cofactor for both these enzymes is vitamin C (ascorbic acid). a-Ketoglutatrate is a coreductant, which is oxidized to succinate.","pyqMatches":[{"year":"2015","no":374,"q":"Prolyl hydroxylase require which cofactor","o":["Sc","Vitamin C","Mo","Vitamin K"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1350, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 469, '{"id":1350,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":469,"q":"Side chain linkage in proteoglycons -","o":["Covalent","Hydrogen bond","Electrostatic bond","Van-der Waal''s force"],"a":0,"e":"Ans. is ''a'' i.e.,Covalent [Ref Essentials of biochemistry p. 712] Among the given options two bonds are involved in proteoglycan structure :","pyqMatches":[{"year":"2015","no":375,"q":"Side chain linkage in proteoglycons","o":["Covalent","Hydrogen bond","Electrostatic bond","Van-der Waal''s force"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1351, 'Biochemistry', 'Miscellaneous', 'Moderate', 'Biochemistry', 470, '{"id":1351,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Biochemistry","sourceNo":470,"q":"Which of following is not a free radical -","o":["H202","(M?","Superoxide anion","HOC1-"],"a":3,"e":"Ans. is ''d'' i.e., HOC1– [Ref Principles in medical pathology p. 391] Free radicals are chemical species that have a single unpaired electron in the outer orbit. Most of these are partially reduced reactive oxygen forms that are produced as an unavoidable byproduct of mitochondria! respiration - also known as reactive oxygen species. The most important are hydrogen peroxide (1120), Superoxide anion (02) and hydroxyl radical (OH).","pyqMatches":[{"year":"2015","no":376,"q":"Which of following is not a free radical","o":["H202","(M?","Superoxide anion","HOC1"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1352, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 471, '{"id":1352,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":471,"q":"In type la maple syrup urine disease, gene mutation seen is ?","o":["Ela","Elb","E2","E3"],"a":0,"e":"Ans. is ''a'' i.e., Ela [Ref Harper 27\"/e ch. 29; Nelson 18th/e ch. 85.6; Medical biochemistry by sheriff 1\"/e p. 513] Metabolic disorders of branched-chain amino acid catabolism As the name implies, the odor of urine in maple syrup urine disease (branched-chain ketonuria) suggests maple syrup or burnt sugar. Decarboxylation of leucine, isoleucine, and valine is accomplished by a complex enzyme system (branched-chain a-ketoacid dehydrogenase) using thiamine pyrophosphate (vitamin 81) as a conzyme. This mitochondrial enzyme consists of four subunits: Ha, El (3, E2, and E3. Deficiency of this enzyme system causes MSUD. Based on clinical findings and response to thiamine administration, five phenotypes MSUD have been identified classical, intermediate, intermittent, thiamine responsive and E3 deficiency. All forms of MSUD are inherited as an autosomal recessive trait.","pyqMatches":[{"year":"2013","no":243,"q":"In type la maple syrup urine disease, gene mutation seen is ?","o":["Ela","Elb","E2","E3"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1353, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 472, '{"id":1353,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":472,"q":"Hexokinase is inhibited by ?","o":["Glucose-6-phosphate","Glucagon","Glucose","Insulin"],"a":0,"e":"Ans. is ''a'' i.e., Glucose-6-phosphate [Ref: Harper 29\"/e p. 171, 190]","pyqMatches":[{"year":"2013","no":267,"q":"Hexokinase is inhibited by ?","o":["Glucose-6-phosphate","Glucagon","Glucose","Insulin"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1354, 'Biochemistry', 'Enzymes', 'Moderate', 'Biochemistry', 473, '{"id":1354,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Moderate","source":"Biochemistry","sourceNo":473,"q":"All of the following are inhibited during fasting/ starvation, except ?","o":["Hexokinase","Glucokinase","PDH","Pyruvate kinase"],"a":0,"e":"Ans. is ''a'' i.e.,Hexokinase [Ref Harper 29th/e p. 190] Hexokinase (in contrast to glycokinase) is not affected by feeding/insulin or starvation. Other three enzymes activity is decreased in starvation.","pyqMatches":[{"year":"2013","no":268,"q":"All of the following are inhibited during fasting/ starvation, except ?","o":["Hexokinase","Glucokinase","PDH","Pyruvate kinase"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1355, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 474, '{"id":1355,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":474,"q":"Hereditary orotic aciduria Type-I is due to deficiency of ?","o":["Orotate phosphoribosyl transferase","Orotic acid decarboxylase","UMP synthase","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above [Ref Pankaj Naik p. 310] Orotic aciduria is a hereditary disorder which can result from a defective enzyme in pyrimidine synthesis. There is a defect in the multifunctional enzyme UMP synthase which has two activities :?","pyqMatches":[{"year":"2013","no":327,"q":"Hereditary orotic aciduria Type-I is due to deficiency of ?","o":["Orotate phosphoribosyl transferase","Orotic acid decarboxylase","UMP synthase","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1356, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 475, '{"id":1356,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":475,"q":"Replication of mitochondrial DNA is caused by which type of DNA polymerase ?","o":["a","p","S","y"],"a":3,"e":"Ans. is ''d'' i.e., y [Ref Pankaj Naik p. 314] DNA polymerase a :- It has primase activity (i.e. synthesizes RNA primer), and initiates DNA synthes DNA polymerase :- It is a DNA repair enzyme ? DNA polymerase y :- Replicates mitochondrial DNA DNA polymerase 6 :- Helps DNA synthesis on lagging strand, i.e. elongation of okazaki fragments on lagging strand. It also has 5''3'' exonuclease activity for proof reading. DNA polymerase c :- Helps in DNA synthesis on leading strand. It also has 5''->3''exonuclease activity for proof reading.","pyqMatches":[{"year":"2013","no":332,"q":"Replication of mitochondrial DNA is caused by which type of DNA polymerase ?","o":["a","p","S","y"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1357, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 476, '{"id":1357,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":476,"q":"Which isoform of LDH is raised in Anemia ?","o":["LDH 5","LDH 4","LDH 3","LDH 2"],"a":3,"e":"Ans. is ''d'' i.e., LDH 2 [Ref Chatterjea 7th/e p. 600-605, Harper 28th/e p. 59] LDH-2 is found in RBCs and is increased in megaloblastic anemia.","pyqMatches":[{"year":"2012","no":416,"q":"Which isoform of LDH is raised in Anemia ?","o":["LDH 5","LDH 4","LDH 3","LDH 2"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1358, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 477, '{"id":1358,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":477,"q":"Digestive enzymes are","o":["Hydrolases","Oxidoreductases","Dehydrogenases","Ligases"],"a":0,"e":"Ans. is ''a'' i.e., Hydrolases [Ref Harper''s 29thle p. 518-19] All digestive enzymes are hydrolases.","pyqMatches":[{"year":"2012","no":236,"q":"Digestive enzymes are","o":["Hydrolases","Oxidoreductases","Dehydrogenases","Ligases"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1359, 'Biochemistry', 'Enzymes', 'Moderate', 'Biochemistry', 478, '{"id":1359,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Moderate","source":"Biochemistry","sourceNo":478,"q":"Enzymes that move a molecular group from one molecule to another are known as -","o":["Ligases","Oxido-reductases","Transferases","Dipeptidases"],"a":2,"e":"Ans. is C. i.e., Transferase [Ref Chatterjea 8th/e p. 123; Harper 28th/e p. 52] Transferases Catalyze transfer of C-N-, or P-containing group from one substrate to another,","pyqMatches":[{"year":"2012","no":237,"q":"Enzymes that move a molecular group from one molecule to another are known as","o":["Ligases","Oxido-reductases","Transferases","Dipeptidases"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1360, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 479, '{"id":1360,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":479,"q":"Glucose-6-phosphate dehydrogenase need -","o":["NAD","NADP","FAD","FMN"],"a":1,"e":"Ans. is ''b'' i.e., NADP [Ref : Harper 29th/e p. 197] NAD* -linked dehydrogenases Pyruvate dehydrogenase, isocitrate dehydrogenase, malate dehydrogenase, a-ketoglutarate dehydrogenase, glutamate dehydrogenase, glyceraldehyde-3-P dehydrogenase, lactate dehydrogenase, p-hydroxy acyl CoA dehydrogenase, glycerol 3-P dehydrogenase (cytoplasmic). NADP''-linked dehydrogenases Glucose-6-P dehydrogenase, 6- Phosphogluconate dehydrogenase, 3-ketoacyl reductase, Enoyl reductase, gulonate dehydrogenase. FAD-linked dehydrogenases Succinate dehydrogenase, fatty acyl CoA dehydrogenase, glycerol-3P et* hydrogenase (mitochondrial).","pyqMatches":[{"year":"2012","no":238,"q":"Glucose-6-phosphate dehydrogenase need","o":["NAD","NADP","FAD","FMN"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1361, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 480, '{"id":1361,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":480,"q":"Which of the following is NADP linked","o":["G6PD","APDH","a-keto glutarate dehydrogenaes","None"],"a":0,"e":"Ans. is ''a'' i.e.,G6PD [Ref Harper 28\"le p. 175] Amongst the given options, only G6-PD (glucose-6-phosphate dehydrogenase) is NADP linked enzyme.","pyqMatches":[{"year":"2012","no":239,"q":"Which of the following is NADP linked","o":["G6PD","APDH","a-keto glutarate dehydrogenaes","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1362, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 481, '{"id":1362,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":481,"q":"Oxidative deamination occurs in ?","o":["Cytoplasm of all cells","Mitochondria of all cells","Cytoplasm of hepatocytes","Mitochondria of hepatocytes"],"a":3,"e":"Ans. is ''d'' i.e., Mitochondria of Hepatocytes [Ref : Harper 29''/e p. 274] Deamination means removal of amino group of amino acid in the form of ammonia. Thus, an amino acid is converted to a keto acid. Deamination coupled with oxidation is called oxidative deamination. It occurs in the mitochondria. Oxidative deamination occurs primarily in the liver (major organ) and kidney.","pyqMatches":[{"year":"2012","no":415,"q":"Oxidative deamination occurs in ?","o":["Cytoplasm of all cells","Mitochondria of all cells","Cytoplasm of hepatocytes","Mitochondria of hepatocytes"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1363, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 482, '{"id":1363,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":482,"q":"Aldehyde dehydrogenase requires NAD as ?","o":["Cofactor","Apoenzyme","Coenzyme","None"],"a":2,"e":"Ans. is C. i.e., Coenzyme [Ref Read below] The complete enzyme, i.e. protein part (apoenzyme) with its non- protein part is called Holoenzyme. Alcohol dehydrogenase is the enzyme (protein) part of complete enzyme (Holoenzyme). Thus, alcohol dedydrogenase itself is apoenzyme. It requires non-protein part NAD, which is an organic component. So, NAD acts as coenzyme for alcohol dehydrogenase.","pyqMatches":[{"year":"2012","no":240,"q":"Aldehyde dehydrogenase requires NAD as ?","o":["Cofactor","Apoenzyme","Coenzyme","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1364, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 483, '{"id":1364,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":483,"q":"In FITC the color emitted after blue light absorption? \\","o":["Yellow green","Orange red","Apple green","Golden brown"],"a":0,"e":"Ans. is ''a'' i.e., Yellow green Fluorescein isothiocyanate (FITC) is a derivative of fluorescein used in wide-ranging applications including flow cytometry. FITC is the original fluorescein molecule functionalized with an isothiocyanate reactive group (-N=C=S), replacing a hydrogen atom on the bottom ring of the structure. This derivative is reactive towards nucleophiles including amine and sulfhydryl groups on proteins. FITC (fluorescein isothiocyanate) is a fluorochrome dye that absorbs ultraviolet or blue light causing molecules to become excited and emit a visible yellow green light. This emission ceases upon removal of the light causing the excitation.","pyqMatches":[{"year":"2012","no":414,"q":"In FITC the color emitted after blue light absorption? \\","o":["Yellow green","Orange red","Apple green","Golden brown"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1365, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 484, '{"id":1365,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":484,"q":"Apoenzyme is ?","o":["Cofactor","Coenzyme","Protein moiety","None"],"a":2,"e":"Ans. is ''c'' i.e., Protein moiety [Ref Harper 2815/e p. 52] The complete enzyme (Holoenzyme) is made of protein portion (apoenzyme) and cofactor/coenzyme.","pyqMatches":[{"year":"2012","no":241,"q":"Apoenzyme is ?","o":["Cofactor","Coenzyme","Protein moiety","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1366, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 485, '{"id":1366,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":485,"q":"In xanthine oxidase co factor is ?","o":["Selenium","Zn","Molybdenum","Mg"],"a":2,"e":"Ans. is ''c'' i.e., Molybdenum [Ref : Essential biochemistry p. 786] Two important enzymes using molybdenum are xanthine oxidase and sulfite oxidase.","pyqMatches":[{"year":"2012","no":242,"q":"In xanthine oxidase co factor is ?","o":["Selenium","Zn","Molybdenum","Mg"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1367, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 486, '{"id":1367,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":486,"q":"What are isoenzyme -","o":["Physically same forms of different enzymes","Physically disinct forms of same enzyme","Forms of same enzyme that catalyze different reactions","Forms of different enzyme that catalyze same reactions"],"a":1,"e":"Ans. is ''b'' i.e., Physically disinct forms of same enzyme Isoenzymes are the physically distince forms of the same enzyme. They catalyze the same chemical reaction or reactions but differ from each other structurally°, electrophoretically° and immunologically. Isoenzymes possess quaternary structure, and are made up of two or three different subunit° (multimericQ ). The subunits have slightly different primary structures. Isoenzymes catalyze the same reaction and act on same substrate°, but with different Km° and Vmax values, i.e., isozymes have different kinetics°. The isoenzymes can be separated from each other by electrophoretic, chromatographic or immunochemical techniques. Separation and quantitation of isoenzymes can give information of great diagnostic importance as the tissue distribution of isoenzymes is quite specific","pyqMatches":[{"year":"2012","no":243,"q":"What are isoenzyme","o":["Physically same forms of different enzymes","Physically disinct forms of same enzyme","Forms of same enzyme that catalyze different reactions","Forms of different enzyme that catalyze same reactions"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1368, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 487, '{"id":1368,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":487,"q":"Enzyme causing covalent bond cleavage without hydrolysis ?","o":["Lyase","Ligase","Hydrolase","Transferase"],"a":0,"e":"Ans. is ''a'' i.e., Lyase [Ref Classification of enzymes from your notes] Cleavage by hydrolysis (addition of water) Hydrolases Cleavage without hydrolysis (without addition of water)→Lyases","pyqMatches":[{"year":"2012","no":244,"q":"Enzyme causing covalent bond cleavage without hydrolysis ?","o":["Lyase","Ligase","Hydrolase","Transferase"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1369, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 488, '{"id":1369,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":488,"q":"Enzymes act by ?","o":["Increase in activation energy","Decrease in activation energy","Shift equilbrium constant","None"],"a":1,"e":"Ans. is ''b'' i.e., Decrease in activation energy In a chemical reaction, the substrate has to be converted to a higher energy form (called transition form) before it can form the reaction products. The transition state is structurally an intermediate between the substrate and the product, and represents the highest energy arrangement of atoms. Therefore, it is unstable; once formed, it decomposes almost immediately to form the reaction product. So, this high energy intermediate acts as energy barrier, separating the substrates and the products. This barrier, called the free energy of action, is the energy difference between the energy of the substrates and high energy intermediates. In other words, initially some energy must be put into the substrate for conversion into transition state (high-energy intermediate); this is the free energy of activation. The enzymes speed up the chemical reaction by lowering the magnitude of the activation energy barrier, i.e., free energy of activation.","pyqMatches":[{"year":"2012","no":245,"q":"Enzymes act by ?","o":["Increase in activation energy","Decrease in activation energy","Shift equilbrium constant","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1370, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 489, '{"id":1370,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":489,"q":"Shortest peptide ?","o":["Angiotensin II","Angiotensin III","Oxytocin","Vasopressin"],"a":1,"e":"Ans. is ''b'' i.e., Angiotensin III [Ref Essentials of biochemistry p. 627]","pyqMatches":[{"year":"2012","no":413,"q":"Shortest peptide ?","o":["Angiotensin II","Angiotensin III","Oxytocin","Vasopressin"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1371, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 490, '{"id":1371,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":490,"q":"The predominant isoenzyme of LDH occuring in liver injury is ?","o":["LDH-1","LDH-2","LDH-4","LDH-5"],"a":3,"e":"Ans. is ''d'' i.e., LDH-5 [Ref: Essentials of biochemistry p. 756] Predominant form in liver is LDH5.","pyqMatches":[{"year":"2012","no":247,"q":"The predominant isoenzyme of LDH occuring in liver injury is ?","o":["LDH-1","LDH-2","LDH-4","LDH-5"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1372, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 491, '{"id":1372,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":491,"q":"Specific activity of enzyme is ?","o":["limo'' of enzyme per gram of substrate","Enzyme units per mg of protein","Conc. of substrate transformed per minute","None"],"a":1,"e":"Ans. is ''b'' i.e., Enzyme units per mg of protein [Ref Lippincott''s 3\"1/e p.","pyqMatches":[{"year":"2012","no":248,"q":"Specific activity of enzyme is ?","o":["limo'' of enzyme per gram of substrate","Enzyme units per mg of protein","Conc. of substrate transformed per minute","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1373, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 492, '{"id":1373,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":492,"q":"Type of inhibition of aconitase by Transaconitate is?","o":["Non-competitive","Competitive","Allosteric","None"],"a":1,"e":"Ans. is ''b'' i.e., Competitive [Ref Essentials of Biochemistry p. 685] enzymes competitive inhibitors 1 Lactate dehydrogenase Oxamate 2 Aconitase Transaconitate 3 Succinate dehydrogenase MalanateQ 4 HMG-CoA reductase HMG, Lovastatin 5 Dihydrofolate reductase Amethopterin, Methotrexate 6 Xanthine oxidase Allopurinol 7 Alcohol dehydrogenase Ethanol 8 Carbonic anhydrase Acetazolamide 9 Digoxin Na-K ATPase 10 5 - Fluorouracil Thymidylate synthase","pyqMatches":[{"year":"2012","no":249,"q":"Type of inhibition of aconitase by Transaconitate is?","o":["Non-competitive","Competitive","Allosteric","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1374, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 493, '{"id":1374,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":493,"q":"Functional plasma enzyme is ?","o":["Fibrinogen","LDH","SGOT","SGPT"],"a":0,"e":"Ans. is ''a'' i.e., Fibrinogen [Ref harper''s 28th/e p. 59] Cloting factors (including fibrinogen) are functional plasma enzymes.","pyqMatches":[{"year":"2012","no":250,"q":"Functional plasma enzyme is ?","o":["Fibrinogen","LDH","SGOT","SGPT"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1375, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 494, '{"id":1375,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":494,"q":"NADPH via glycerophosphate shunt makes how many ATP?","o":["1","2","3","4"],"a":1,"e":"Ans. is > b'' i.e., 2 [Ref : Harper 29\"/e p. 129-130] In glycerophosphate shuttle, the mitochondrial enzyme is linked to respiratory chain (ETC) via a flavoprotein, So only 1.5 mol of ATP are produced (According to older calculations, 2 ATP mol of ATP are produced). In malate shuttle, the mitochondrial enzyme is linked to ETC via NAD, so 2.5 mol of ATP are produced (according to older calculations 3 mol of ATP are produced).","pyqMatches":[{"year":"2012","no":254,"q":"NADPH via glycerophosphate shunt makes how many ATP?","o":["1","2","3","4"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1376, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 495, '{"id":1376,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":495,"q":"Which of the following tripeptide ?","o":["Glutathione","Angiotensin","Glucagon","Oxytocin"],"a":0,"e":"Ans. is ''a'' i.e.,Glutathione [Ref Harper 28thle p. 679-680] Angiotensin IIIHeptapeptide (6 amino acids) Angiotensin II Octapeptide (8 amino acids) Oxytocin Nonapeptide (9 amino acids) Bradykinin Nonapeptide (9 amino acids) Vasopressin Nonapeptide (9 amino acids) Glucagon Decapeptide (10 amino acids) Angiotensin I Decapeptide (10 amino acids)","pyqMatches":[{"year":"2012","no":412,"q":"Which of the following tripeptide ?","o":["Glutathione","Angiotensin","Glucagon","Oxytocin"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1377, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 496, '{"id":1377,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":496,"q":"Enzyme involved in oxidative phosphorylation ?","o":["Pyruvate kinase","Succinyl CoA thiokinase","NADH dehydrogenase","None"],"a":2,"e":"Ans. is ''c'' i.e., NADH dehydrogenase [Ref Harper 29''/e p. 126- 128, Vasudevan 6th le p. 234] Oxidative phosphorylation takes phase along the electron transport chain (respiratory chain), where the ATP is synthesized indirectly from creation of a protein gradient and movement of protiens across inner mitochondrial membrane helps in formation of ATP. The protein gradient is created by large change in free energy due to transport of electron in ETC. Electrons enter the ETC via NAD'' or FAD. Complex I (NADH - CoQ reductase) catalyzes the transfer of electron from NADH to coenzyme Q (CoQ). {NADH-CoQ reductase is also called NADH dehydrogenase.}.","pyqMatches":[{"year":"2012","no":255,"q":"Enzyme involved in oxidative phosphorylation ?","o":["Pyruvate kinase","Succinyl CoA thiokinase","NADH dehydrogenase","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1378, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 497, '{"id":1378,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":497,"q":"Protein segregation occurs in ?","o":["Golgi appparatus","Peroxisomes","ER","Mitochondria"],"a":0,"e":"Ans. is ''a'' i.e.,Golgi appparatus [Ref Harper 29th/e p. 549] Golgi apparatus plays a major role in sorting of proteins.","pyqMatches":[{"year":"2012","no":411,"q":"Protein segregation occurs in ?","o":["Golgi appparatus","Peroxisomes","ER","Mitochondria"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1379, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 498, '{"id":1379,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":498,"q":"Weakest bond is ?","o":["Covalent","Hydrogen","Electrostatic","Vander wall"],"a":3,"e":"Ans. is ''d'' i.e., Vander wall [Ref: Harper 28thle p. 9; Basics of molecular biology p. 786] Strongest bond Covalent Weakest bond -4 Van der walls forces Covalent (strongest)° > Electrostatic0 (ionic or salt linkage) > hydrogen> hydrophobic > Van der waal''s (weakest)°","pyqMatches":[{"year":"2012","no":410,"q":"Weakest bond is ?","o":["Covalent","Hydrogen","Electrostatic","Vander wall"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1380, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 499, '{"id":1380,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":499,"q":"In ETC NADH generates -","o":["1 ATPs","2 ATPs","3 ATPs","4 ATPs"],"a":2,"e":"Ans. is ''> c'' i.e., 3 ATPs [Ref : Harper 28''\"/e p. 106, Vasudevan 5thie p. 231] The energy liberated of site I (complex I) is used to synthesize 1 ATP molecule, at site II (complex III) is used to synthesize 1 ATP molecule and at site III (Complex IV) is used to synthesize 1/2 ATP molecule. Thus,when 1 NADH molecule enters the respiratory chain, it produce 2.5 molecules of ATP°. When I molecule of FADH2 enters the respiratory chain only 1.5 molecules of ATP are produced° as site I of energy liberation is bypassed. Note : Previously it was assumed the NADH produces 3 ATPs and FAD generates 2 ATPs. Recent experiments show-that these old values are overestimates and NADH produces 2.5 ATPs° and FADH2 produces 1.5 ATPs°.","pyqMatches":[{"year":"2012","no":257,"q":"In ETC NADH generates","o":["1 ATPs","2 ATPs","3 ATPs","4 ATPs"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1381, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 500, '{"id":1381,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":500,"q":"This attaches to protein before destruction ?","o":["Ubiquitin","RNAseF","Zymase","Chaperone"],"a":0,"e":"Ans. is ''a'' i.e., Ubiquitin [Ref Harper 291Ve p. 560-561] Ubiquitin Is a Key Molecule in Protein Degradation There are two major pathways of protein degradation in eukaryotes. One involves lysosomal proteases and does not require ATP. The other pathway involves ubiquitin and is ATP-dependent. It plays the major role in the degradation of proteins, and is particularly associated with disposal of misfolded proteins and regulatory enzymes that have short half-lives.","pyqMatches":[{"year":"2012","no":409,"q":"This attaches to protein before destruction ?","o":["Ubiquitin","RNAseF","Zymase","Chaperone"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1382, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 501, '{"id":1382,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":501,"q":"In glycolysis, inorganic phosphate is used reaction, catalyzed by ?","o":["Enolase","Pyruvate kinase","Glyceraldehyde-3-p dehydrogenase","Aldolase"],"a":2,"e":"Ans. is ''c'' i.e.,Glyceraldehyde-3-p dehydrogenase [Ref Harper''s 250/e p. 171]","pyqMatches":[{"year":"2012","no":258,"q":"In glycolysis, inorganic phosphate is used reaction, catalyzed by ?","o":["Enolase","Pyruvate kinase","Glyceraldehyde-3-p dehydrogenase","Aldolase"],"a":2,"source":"NEET_2012_Paper.pdf"},{"year":"2012","no":336,"q":"In glycolysis, inorganic phosphate is used reaction, catalyzed by ?","o":["Enolase","Pyruvate kinase","Glyceraldehyde-3-p dehydrogenase","Aldolase"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1383, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 502, '{"id":1383,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":502,"q":"Protein glycosylation occurs in ?","o":["ER","Golgi bodies","Mitochondria","Peroxisomes"],"a":0,"e":":B Ans. is ''b > a'' i.e., Golgi bodies > ER [Ref Harper''s 29th/e p. 549, 572] The endoplasmic reticulum and the Golgi apparatus are the major sites involved in glycosylation processes. However, 0-glycosylation occurs only in the Golgi apparatus and so it is the organelle where all types of glycosylation reactions can take place","pyqMatches":[{"year":"2012","no":408,"q":"Protein glycosylation occurs in ?","o":["ER","Golgi bodies","Mitochondria","Peroxisomes"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1384, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 503, '{"id":1384,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":503,"q":"True about glycolysis?","o":["Hexokinase produce ATP","1 cycle produces 2 ATP","It produces directly 2 molecules of lactate","Aldolase produces irreversible polymerization"],"a":2,"e":"Ans. is ''c'' i.e.,It produces directly 2 molecules of lactate [Ref Harper 29th/e p. 170-177] Each cycle of anaerobic glycolysis produces 2 molecules of lactate (lactic acid) whereas in aerobic condition it produces 2 molecules of pyruvate. Option b is tricky one. Each glycolytic cycle produces 4 ATPs (not 2 ATPs). But out of these 4 ATPs, 2 are used in the cycle itself. Therefore, there is net gain of 2 ATPs. So,:-","pyqMatches":[{"year":"2012","no":259,"q":"True about glycolysis?","o":["Hexokinase produce ATP","1 cycle produces 2 ATP","It produces directly 2 molecules of lactate","Aldolase produces irreversible polymerization"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1385, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 504, '{"id":1385,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":504,"q":"The rate limiting step in glycolysis is catalyzed by?","o":["Pyruvate kinase","Enolase","Glucokinase","Phosphofructokinase"],"a":0,"e":":C:D Ans. is ''d> a & c'' i.e., Phosphofructokinase > Pyruvate kinase & Glucokinase [Ref Lippincott''s 5th le p. 99] Phosphofructokinase, glucokinase and pyruvate kinase are rate limiting enzymes of glycolysis. However, phosphofructokinase is the most important one.","pyqMatches":[{"year":"2012","no":261,"q":"The rate limiting step in glycolysis is catalyzed by?","o":["Pyruvate kinase","Enolase","Glucokinase","Phosphofructokinase"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1386, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 505, '{"id":1386,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":505,"q":"Rate limiting enzyme in heme synthesis ?","o":["ALA synthase","Hmg coa reductase","ALA dehydratase","Uroporphyrinogen 1 synthase"],"a":0,"e":"Ans. is ''a'' i.e.,ALA synthase [Ref Harper''s 29'' le p. 309] Heme synthesis takes place in all cells, but occurs to greatest extent in bone marrow and liver. The first step in the synthesis of heme is the condensation of glycine and succinyl Co-A to form 6- aminolevulinic acid (6-ALA), which occurs in mitochondria. This reaction is catalyzed by 6-ALA synthase which requires pyridoxal phosphate (PLP) as cofactor. This is the rate limiting step in heme synthesis.","pyqMatches":[{"year":"2012","no":407,"q":"Rate limiting enzyme in heme synthesis ?","o":["ALA synthase","Hmg coa reductase","ALA dehydratase","Uroporphyrinogen 1 synthase"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1387, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 506, '{"id":1387,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":506,"q":"Reverse folding of proteins is carried out by ?","o":["Valine","Threonine","Chaperone","Aspartate"],"a":2,"e":"Ans. is ''c'' i.e.,Chaperone [Ref Harper''s 29th/e p. 558, 559] Certain proteins play a role in the assembly or proper folding of other proteins without themselves being components of the latter. Such proteins are called molecular chaperones. Most chaperones exhibit ATPase activity and bind ADP and ATP. This activity is important for their effect on folding","pyqMatches":[{"year":"2012","no":406,"q":"Reverse folding of proteins is carried out by ?","o":["Valine","Threonine","Chaperone","Aspartate"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1388, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 507, '{"id":1388,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":507,"q":"Myoglobin contains ?","o":["Iron","Copper","Zink","Selenium"],"a":0,"e":"Ans. is ''a'' i.e.,Iron [Ref Harper 29th/e p. 308, Vasudevan 6th/e p. 242] Hemoproteins are proteins which have heme as prosthetic group. Important hemoproteins are hemoglobie, myoglobinQ, cytochromesQ (cytochrome CQ, cytochrome P450Q), catalaseQ, peroxidase, tryptophan pyrrolase and nitric oxide synthase. All hemoproteins contain iron as iron is the central component of heme","pyqMatches":[{"year":"2012","no":405,"q":"Myoglobin contains ?","o":["Iron","Copper","Zink","Selenium"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1389, 'Biochemistry', 'Lipid Metabolism', 'Moderate', 'Biochemistry', 508, '{"id":1389,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":508,"q":"All are activated by insulin except ?","o":["Lipoprotein lipase","Pyruvate kinase","Hormone sensitive lipase","Acetyl-CoA carboxylase"],"a":2,"e":"Ans. is C. i.e., Hormone sensitive lipase Enzymes /Pathways activated by insulin Glycolysis : PFK-1, Pyruvate kinase, glucokinase, PDH. Glycogenesis : Glycogen synthase. Lipogenesis : Acetyl-Co-carboxylase, Fatty acid synthase. Cholesterol synthesis : HMG - CoA reductase. Triglyceride synthesis : Acyl - CoA glycerol-3-P transferase, glycerol kinase. Lipoprotein degradation : Lipoprotein lipase","pyqMatches":[{"year":"2012","no":263,"q":"All are activated by insulin except ?","o":["Lipoprotein lipase","Pyruvate kinase","Hormone sensitive lipase","Acetyl-CoA carboxylase"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1390, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 509, '{"id":1390,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":509,"q":"Acute intermittent porphyria is due to deficiency of?","o":["Uroporphyrinogen I synthase","Uroporphyrinogen III synthase","Ferrochelatase","ALA synthase"],"a":0,"e":"Ans. is ''a'' i.e.,Uroporphyrinogen I synthase [Ref Harper 29tVe p. 313]","pyqMatches":[{"year":"2012","no":404,"q":"Acute intermittent porphyria is due to deficiency of?","o":["Uroporphyrinogen I synthase","Uroporphyrinogen III synthase","Ferrochelatase","ALA synthase"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1391, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 510, '{"id":1391,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":510,"q":"Nonsense codons bring about ?","o":["Elongation of polypeptide chain","Pre-translational modificastion of protein","Initiation of protein synthesis","Termination of protein synthesis"],"a":3,"e":"Ans. is D. i.e., Termination of protein synthesis [Ref Harper 28\"le p. 353, 354] Stop or termination or nonsense codons:- Three of the 64 possible nucleotide triplets UAAQ (amber 0),UAGQ (Ochre) and UGAQ (opal) do not code for any amino acid. They are called nonsense codons that normally signal termination of polypeptide chains0. Thus, though there are 64 possible triplet codons, only 61 codes for 20 amino acids (as remaining three are non-sense codons).","pyqMatches":[{"year":"2012","no":264,"q":"Nonsense codons bring about ?","o":["Elongation of polypeptide chain","Pre-translational modificastion of protein","Initiation of protein synthesis","Termination of protein synthesis"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1392, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 511, '{"id":1392,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":511,"q":"Repeatitive chains of glucosamine with uronic acid are seen in ?","o":["NANA","Heparan sulphate","Keratan sulphate","None of these"],"a":1,"e":"Ans. is `b'' i.e., Heparan sulphate [Ref Dinesh puri Yale p. 31, 32] Proteoglycans are made up of core protein, core trisaccharide and glycosaminoglycans. Proteoglycans = Glycosaminoglycans + Core trisaccharide + Core protein. Glycosaminoglycans (mucopolysaccharides) are made up of repeating diasaccharide units. Each diasaccharide unit contains?","pyqMatches":[{"year":"2012","no":403,"q":"Repeatitive chains of glucosamine with uronic acid are seen in ?","o":["NANA","Heparan sulphate","Keratan sulphate","None of these"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1393, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 512, '{"id":1393,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":512,"q":"ATP is consumed at which step of glycolysis","o":["Enolase","Hexokinase","Pyruvate kinase","Isomerase"],"a":1,"e":"Ans. is ''b'' i.e., Hexokinase ATP is consumed at reactions catalysed by - hexokinase, phosphofructokinase I. ATP is produced at reactions catalyzed by -> phosphoglycerate kinase, pyruvate kinase.","pyqMatches":[{"year":"2012","no":265,"q":"ATP is consumed at which step of glycolysis","o":["Enolase","Hexokinase","Pyruvate kinase","Isomerase"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1394, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 513, '{"id":1394,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":513,"q":"Which of the following GAG is not sulphated ?","o":["Chondroitin","Dermatan","Keratan","Hyaluronic acid"],"a":3,"e":"Ans. is ''d'' i.e., Hyaluronic acid [Ref: Harper''s 29thle p. 596] A Glycosaminoglycan(GAG) is an unbranched polysaccharide made up of repeating disaccharides, one component of which is always an amino sugar (hence the name GAG), either D-glucosamine or D- galactosamine. The other component of the repeating disaccharide (except in the case of keratan sulfate) is a uronic acid, either L-glucuronic acid (GlcUA) or its 5''-epimer, L-iduronic acid (IdUA). Proteoglycans are proteins that contain covalently linked glycosaminoglycans. The proteins bound covalently to glycosaminoglycans are called \"core proteins\". With the exception of hyaluronic acid, all the GAGs contain sulfate groups, either as 0-esters or as N-sulfate (in heparin and heparan sulfate). Hyaluronic acid affords another exception because there is no clear evidence that it is attached covalently to protein, as the definition of a proteoglycan given above specifies.","pyqMatches":[{"year":"2012","no":402,"q":"Which of the following GAG is not sulphated ?","o":["Chondroitin","Dermatan","Keratan","Hyaluronic acid"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1395, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 514, '{"id":1395,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":514,"q":"Methionine can entre the TCA cycle at which level?","o":["Fumarate","Oxabacetate","Succinyl - CoA","Citrate"],"a":2,"e":"Ans. is ''c'' i.e., Succinyl - CoA","pyqMatches":[{"year":"2012","no":266,"q":"Methionine can entre the TCA cycle at which level?","o":["Fumarate","Oxabacetate","Succinyl - CoA","Citrate"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1396, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 515, '{"id":1396,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":515,"q":"Rate limiting steps in TCA cycle ?","o":["a–Ketoglutarate Succinyl CoA","Citrate - Isocitrate","Succinyl CoA 4 Succinate","Succinate - Fumarate"],"a":0,"e":"Ans. is ''a'' i.e., alpha-Ketoglutarade - Succinyl CoA [Ref Harper''s 28th/e p. 147, 154] Regulating steps in TCA Cycle are catalyzed by : a) Citrate Synthase : Catalyzes condensation of acetyl CoA & oxaloacetate to from citrate. Isocitrate dehydrogenase : Catalyzes the conversion of isocitrate to a-ketoglutarate by decarboxylation. a-ketoglutarate dehydrogenase : Catalyzes the conversion of a- ketoglutarate to succinyl CoA","pyqMatches":[{"year":"2012","no":267,"q":"Rate limiting steps in TCA cycle ?","o":["a–Ketoglutarate Succinyl CoA","Citrate - Isocitrate","Succinyl CoA 4 Succinate","Succinate - Fumarate"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1397, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 516, '{"id":1397,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":516,"q":"The folds in collagen is due to ?","o":["Glycine","Alanine","Arginine","Histidine"],"a":0,"e":"Ans. is ''a'' i.e., Glycine [Ref Essentials of biochemisty p. 868] In order to form a triple-helix a polypeptide chain (a-chain) must contain glycine as every third residue in the sequence. This is because only the glycine is small enough to be accommodated in the limited space available down the central core of the triple helix. Each turn of polypeptide chain (a-chain) contains three amino acid residues, and glycine (Gly) is present at every third positions. Thus glycine constitutes 33% of the total amino acid residues. The repeating amino acid residues, represented as (Gly-X-Y)n, is an absolute requirement for formation of triple helix. X and Y can be any amino acids, but most of the time X is proline (10% of the total amino acid residues) and most of the time Y is hydroxyproline.","pyqMatches":[{"year":"2012","no":401,"q":"The folds in collagen is due to ?","o":["Glycine","Alanine","Arginine","Histidine"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1398, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 517, '{"id":1398,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":517,"q":"Rate limiting step in TCA cycle is catalyzed by -","o":["a-ketoglotarate synthase","Fumarase","Aconitase","Thiokinase"],"a":0,"e":"Ans. is ''a'' i.e., a-ketoglotarate synthase [Ref Harper 28th/e p. 147, 154]","pyqMatches":[{"year":"2012","no":268,"q":"Rate limiting step in TCA cycle is catalyzed by","o":["a-ketoglotarate synthase","Fumarase","Aconitase","Thiokinase"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1399, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 518, '{"id":1399,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":518,"q":"Which of the following statements regarding mature cytoplasmic messenger RNA is true ?","o":["Transcribed from Nuclear DNA","Has Thiamine in place of Uracil","Sugar is Deoxy Ribose","Its molecular weight is more than hn-RNA"],"a":0,"e":"Ans. is ''a'' i.e., Transcribed from Nuclear DNA [Ref: Lippincott''s Biochemistry 5thp.428;Fundamentals of Cytogenetics & Genetics (2010) p. 444] Mesenger RNA (mRNA) is formed by the process of ''transcription'' from one of the strands of double stranded nuclear DNA and carries genetic information from the nuclear DNA to the cytosol where it is used as a template for protein synthesis. mRNA comprises only 5-10% of total cellular RNA. It carries the information (massage) from the nucleus to the ribosome. mRNA is synthesized in the nucleus as lieterogenous RNA (hn RNA)'', which is processed into functional m RNA.","pyqMatches":[{"year":"2012","no":400,"q":"Which of the following statements regarding mature cytoplasmic messenger RNA is true ?","o":["Transcribed from Nuclear DNA","Has Thiamine in place of Uracil","Sugar is Deoxy Ribose","Its molecular weight is more than hn-RNA"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1400, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 519, '{"id":1400,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":519,"q":"Fluroacetate inhibits ?","o":["Citrate synthetase","Aconitase","Succinate dehydrogenase","Alphaketoglutarate dehydrogenase"],"a":1,"e":"Ans. is ''b'' i.e., Aconitase [Ref Harper 28thIe p. 145]","pyqMatches":[{"year":"2012","no":269,"q":"Fluroacetate inhibits ?","o":["Citrate synthetase","Aconitase","Succinate dehydrogenase","Alphaketoglutarate dehydrogenase"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1401, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 520, '{"id":1401,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":520,"q":"Identification of individed by their DNA was invented by ?","o":["Shapiro","Lewis","Jeffreys","Pasture"],"a":2,"e":"Ans. is ''c'' i.e.,Jeffreys [Ref Lippicott''s Sthie p. 83, 474, Lehniger 5thie p. 319-21] The DNA fingerprinting was first reported in 1984 by Sir Alec Jeffreys° at the university of leicester in England.","pyqMatches":[{"year":"2012","no":399,"q":"Identification of individed by their DNA was invented by ?","o":["Shapiro","Lewis","Jeffreys","Pasture"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1402, 'Biochemistry', 'Enzymes', 'Moderate', 'Biochemistry', 521, '{"id":1402,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Moderate","source":"Biochemistry","sourceNo":521,"q":"Inhibitors of glycolysis are all except ?","o":["Fluoride","Fluoroacetate","Arsenite","Iodoacetate"],"a":1,"e":"Ans. is ''b'' i.e., Fluoroacetate [Ref Harper'' s 28`\"/e p 151] Fluoroacetate is an inhibitor of TCA cycle.","pyqMatches":[{"year":"2012","no":270,"q":"Inhibitors of glycolysis are all except ?","o":["Fluoride","Fluoroacetate","Arsenite","Iodoacetate"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1403, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 522, '{"id":1403,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":522,"q":"Which of following is an analouge guanosine ?","o":["Abacavir","Allopurinol","Bromodeoxyuridine","None"],"a":0,"e":"Ans. is ''a'' i.e., Abacavir [Ref Essentials of biochemistry p. 888]","pyqMatches":[{"year":"2012","no":398,"q":"Which of following is an analouge guanosine ?","o":["Abacavir","Allopurinol","Bromodeoxyuridine","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1404, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 523, '{"id":1404,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":523,"q":"DNA microarrays allow detection of Gene mutations using?","o":["Polymerase chain Reaction","Cloning","Southern Blotting","Hybridization"],"a":3,"e":"Ans. is ''d'' i.e.,Hybridization [Ref Biology by Raven Tata p. 331] DNA Microarray (DNA-Chips) DNA microarrays contain thusands (500-5000) of immobilized DNA probes/sequences (few dozen to hundreds of nucleotide long) from known genes organized in an area no longer than a microscope slide. DNA segments (from DNA libraries) are amplified by PCR and placed on small wells in a solid polystyrene plates, using robotic devices. Upto million such spots are deposited in a predesigned array on a surface area of just few cm''. An alternate way is to synthesize DNA directly on the solid surface using photolithography. C-DNA (obtained directly or from mRNA of patients particular cell type or stage) is added to each well, hybridize and fluorescence is assessed to assess genes being expressed in those cells/stage. This is based on principles of nucleic acid hybridization like southern or northern blot tests but allows simultaneous study of multiple genes or entire genome rather than single. Hybridization means binding of complementary strands of nucleic acid according to Watson-Crick rules (i.e. A = T and G =C binding). Southern blot for DNA and Northern blot for RNA allows the study/detection of single gene whereas microarray technique (for DNA & RNA) allows detection of multiple genes or entire genome. So it can be considered as multiple Southern or Northern blot analysis running in parallel.","pyqMatches":[{"year":"2012","no":397,"q":"DNA microarrays allow detection of Gene mutations using?","o":["Polymerase chain Reaction","Cloning","Southern Blotting","Hybridization"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1405, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 524, '{"id":1405,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":524,"q":"The biosynthesis of the enzyme pyruvate carboxylase is repressed by ?","o":["Insulin","Glucagon","Cortisol","Epinephrine"],"a":0,"e":"Ans. is ''a'' i.e., Insulin [Ref : Harper 28th/e p. 168] Gluconeogenesis is regulated by four key enzymes : (i) Pyruvate carboxylase; (ii) Phosphoenolpyruvate carboxykinase; (iii) Fructose- 1, 6-bisphosphatase; and (iv) Glucose-6-phosphatase. The hormone glucagon, epinephrine and glucocorticoids stimulate gluconeogenesis, by inducing these enzymes. Conversely, insulin inhibits gluconeogenesis by repressing their synthesis.","pyqMatches":[{"year":"2012","no":271,"q":"The biosynthesis of the enzyme pyruvate carboxylase is repressed by ?","o":["Insulin","Glucagon","Cortisol","Epinephrine"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1406, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 525, '{"id":1406,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":525,"q":"Termination codon is ?","o":["AUG","UAA","AUA","AGG"],"a":1,"e":"Ans. is ''b'' i.e., UAA Initiation codon .4AUG Stop codons (termination codons or nonsense codons) → UAA, UGA, UAG","pyqMatches":[{"year":"2012","no":396,"q":"Termination codon is ?","o":["AUG","UAA","AUA","AGG"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1407, 'Biochemistry', 'Carbohydrate Metabolism', 'Moderate', 'Biochemistry', 526, '{"id":1407,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":526,"q":"Where can glucose 6 phosphate not be converted to glucose ?","o":["Muscle","Liver","Adipose tissue","Kidney"],"a":0,"e":"Ans. is ''a'' i.e., Muscle [Ref : Harper 250 le p. 178-179] Glucose-6-phosphatase is absent in muscles therefore, glucose-6- phosphate cannot be degraded to free glucose in muscles. Moreover, glucose-6-phosphate cannot diffuse out of the muscles. Therefore, muscle cannot provide glucose to maintain blood glucose level. Rather, muscle glycogen acts as a source of energy; the glucose-6-phosphate enters the glycolysis to produce energy.","pyqMatches":[{"year":"2012","no":272,"q":"Where can glucose 6 phosphate not be converted to glucose ?","o":["Muscle","Liver","Adipose tissue","Kidney"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1408, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 527, '{"id":1408,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":527,"q":"Common intermediate between gluconeogenesis and fatty acid synthesis ?","o":["Glucose-6-phosphate","Acetyl-CoA","Citrate","Succinyl-CoA"],"a":2,"e":"Ans. is ''c'' i.e., Citrate [Ref Harper 29th le p. 188] Citrate in Gluconeogenesis Gluconeogenesis involves glycolysis, the citric acid cycle and some special reactions. Citrate is an intermediary metabolism of gluconeogenesis (through TCA cycle).","pyqMatches":[{"year":"2012","no":273,"q":"Common intermediate between gluconeogenesis and fatty acid synthesis ?","o":["Glucose-6-phosphate","Acetyl-CoA","Citrate","Succinyl-CoA"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1409, 'Biochemistry', 'Genetics', 'Easy', 'Biochemistry', 528, '{"id":1409,"subject":"Biochemistry","chapter":"Genetics","difficulty":"Easy","source":"Biochemistry","sourceNo":528,"q":"Chromosomal study is best carried out in ?","o":["Prophase","Metaphase","Telophase","Anaphase"],"a":1,"e":"Ans. is `b'' i.e., Metaphase [Ref: Anderson 10thle p. 225, 226, Robbins 8thie p. 158] Method of karyotyping Karyotyping is the study of coromosone. Dividing cells are arrested in metaphase by addition of colchicine or colcemid (deacetylmethylcolchicine). Subsequently, cells are exposed to a hypotonic solution to induce swelling of the cell for enhancing spreading of the chromosomes. The metaphase cells are then fixed with methanol/glacial acetic acid mixture and stained by one of the several banding techniques. After staining chromosomes are analysed under a microscope and photographed. Finally, a karyotype is constructed by manual or automated pattern. Chromosomes are arranged in pairs and decreasing order of length","pyqMatches":[{"year":"2012","no":395,"q":"Chromosomal study is best carried out in ?","o":["Prophase","Metaphase","Telophase","Anaphase"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1410, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 529, '{"id":1410,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":529,"q":"Glycogen synthase is activated by ?","o":["Insulin","Glucagon","Epinophrine","AMP"],"a":0,"e":"Ans. is ''a'' i.e.,Insulin [Ref Harper 28th/e p. 159-161, Lehinger 5th/e p. 603, 604]","pyqMatches":[{"year":"2012","no":274,"q":"Glycogen synthase is activated by ?","o":["Insulin","Glucagon","Epinophrine","AMP"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1411, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 530, '{"id":1411,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":530,"q":"Which of the following usually require a RNA intermediate for cloning/replication?","o":["Transposons","Plasmids","Phages","Cosmids"],"a":0,"e":"Ans. is ''a'' i.e., Transposons [Ref : Lippincot 4th/e p. 461 & Harper 29tVe p. 436, 437] Transposons (Tn) are mobile segments of DNA that move in an essentially random manner from one site to another on the same or a different chromosome. Movement is mediated by transposase, an enzyme encoded by Tn itself. Movement can be :- (i) direct, in which transposase cuts out and then inserts Tn at a new site, or (ii) replicative, in which the Tn is copied and the copy inserted else where while the origin remains in place. In eukaryotes, including humans, replicative transposition frequently involves a RNA intermediate, in which case the transposon is called a retrotransposon i.e. tronsposons that involve a RNA intermediate are called retrotransposons","pyqMatches":[{"year":"2012","no":394,"q":"Which of the following usually require a RNA intermediate for cloning/replication?","o":["Transposons","Plasmids","Phages","Cosmids"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1412, 'Biochemistry', 'Carbohydrate Metabolism', 'Hard', 'Biochemistry', 531, '{"id":1412,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Hard","source":"Biochemistry","sourceNo":531,"q":"Glycogen storage disease which presents as lysosomal storage disease ?","o":["Von gierke''s disease","Pompes disease","Mcardle''s disease","Andersen''s disease"],"a":1,"e":"Ans. is ''b'' i.e., Pompes disease [Ref Lippincott''s 4th/e p. 129- 131] Type II glycogen storage disease (Pompes disease) is the only glycogen storage disease that is a lysosomal storage disease","pyqMatches":[{"year":"2012","no":275,"q":"Glycogen storage disease which presents as lysosomal storage disease ?","o":["Von gierke''s disease","Pompes disease","Mcardle''s disease","Andersen''s disease"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1413, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 532, '{"id":1413,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":532,"q":"In sickle cell anemia, translocation on codon 6 is due to substitution of ?","o":["Valine for glutamate","Glutamate for valine","Isoleucine for valine","Valine for isoleucine"],"a":0,"e":"Ans. is ''a'' i.e., Valine for glutamate [Ref Harper''s 29th/e p. 444] Sickle cell disease, is caused by mutation of a single base out of the 3 x 109 in the genome, a T-to-A DNA substitution, which in turn results in an A-to-U change in the mRNA corresponding to the sixth codon of the 13-globin gene. The altered codon specifies a different amino acid (valine rather than glutamic acid), and this causes a structural abnormality of the p-globin molecule.","pyqMatches":[{"year":"2012","no":393,"q":"In sickle cell anemia, translocation on codon 6 is due to substitution of ?","o":["Valine for glutamate","Glutamate for valine","Isoleucine for valine","Valine for isoleucine"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1414, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 533, '{"id":1414,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":533,"q":"Aldolase-B is involved in metabolism of ?","o":["Galactose","Fructose","Sucrose","None"],"a":1,"e":"Ans. is ''b'' i.e., Fructose [Ref Harper''s 28th /e p. 179)","pyqMatches":[{"year":"2012","no":276,"q":"Aldolase-B is involved in metabolism of ?","o":["Galactose","Fructose","Sucrose","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1415, 'Biochemistry', 'Enzymes', 'Moderate', 'Biochemistry', 534, '{"id":1415,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Moderate","source":"Biochemistry","sourceNo":534,"q":"In humans, ascorbic acid cannot be synthesized because of ?","o":["Deficiency of G6PD","Deficiency of xylulose kinase","Deficiency of L-gulonolactone oxidase","Deficiency of phosphoglucomutase"],"a":2,"e":"Ans. is ''c'' i.e., Deficiency of L-gulonolactone oxidase In man, other primates and guinea pigs, ascorbic acid can be synthesized due to absence of L-glucanolactone oxidase, an enzyme used in lower animals to synthesise ascorbic acid as a byproduct of uronic acid pathway (glucuronic acid cycle).","pyqMatches":[{"year":"2012","no":277,"q":"In humans, ascorbic acid cannot be synthesized because of ?","o":["Deficiency of G6PD","Deficiency of xylulose kinase","Deficiency of L-gulonolactone oxidase","Deficiency of phosphoglucomutase"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1416, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 535, '{"id":1416,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":535,"q":"Function of exonuclease -","o":["Polymerization","Proof reading","Chain elongation","Termination"],"a":1,"e":"Ans. is ''b'' i.e., Proof reading [Ref Dinesh puri 3rd /e p. 455, 456] Nucleases refers to an enzyme that catalyzes hydrolysis of phosphodiester bond in a nucleic acid. The nucleses are of two types : * Endonucleases : Cleave the internal phosphodiester bonds. * Exonucleases : Cleave bonds at ends. Some exonucleases cleave only at the 3'' end (the 3''-exonuclease activity) while other cleave at the 5'' end (the 5''-exonuclease activity). - 31-exonuclease activity is responsible for proofreading. 3''- exonuclease activity is present in DNA polymerase I, II and III. - 51-exonuclease activity is responsible for error correction in damaged DNA.","pyqMatches":[{"year":"2012","no":392,"q":"Function of exonuclease","o":["Polymerization","Proof reading","Chain elongation","Termination"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1417, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 536, '{"id":1417,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":536,"q":"Glucose oxidase converts glucose to?","o":["Gluconic acid","Glucuronic acid","Iduronic acid","Galactic acid"],"a":0,"e":"Ans. is ''a'' i.e., Gluconic acid [Ref : Internet] Oxidase-peroxidase enzyme system is used to determine glucose in urine & blood. Glucose oxidase enzyme produces hydrogen peroxide & gluconic acid from glucose.Peroxidase catalyses the reaction of H202 with colourless potassium iodide to brown iodide. This produces a colour change, the intensity of which may indicate glucose concentration in some tests(such as Boehringer, Diastix).","pyqMatches":[{"year":"2012","no":278,"q":"Glucose oxidase converts glucose to?","o":["Gluconic acid","Glucuronic acid","Iduronic acid","Galactic acid"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1418, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 537, '{"id":1418,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":537,"q":"Glucose is converted to glucuronate by ?","o":["Oxidation of aldehyde group","Oxidation of terminal alcohol","Oxidation of both","None"],"a":1,"e":"Ans. is ''b'' i.e., Oxidation of terminal alcohol [Ref Chatterjee 8th/e p. 29] When aldose sugars are oxidized they may form three different sugar acid, depending upon oxidation of aldehyde group (at C-1) or terminal alcohol group (at C-6).","pyqMatches":[{"year":"2012","no":279,"q":"Glucose is converted to glucuronate by ?","o":["Oxidation of aldehyde group","Oxidation of terminal alcohol","Oxidation of both","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1419, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 538, '{"id":1419,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":538,"q":"Enzyme require for cutting the strand DNA synthesis?","o":["DNA polymerase","DNA ligase","Topoisomerase","Helicase"],"a":2,"e":"Ans. is ''c'' i.e., Topoisomerase [Ref Lippincott''s 5thie p. 400, 401] As the two strands of DNA are separated a problem is encountered, i.e. appearance of positive supercoils (supertwists) in the region of DNA aheud of replication form. The accumulation of positive supercoiling interferes with further unwinding of the double helix. To solve this problem, there is a group of enzymes called DNA topoisomerases which are resonsible for removing supercoils in the helix. DNA topoisomerases are nick and seal enzymes, i.e. they have both nuclease (strand-cutting) and ligase (strand-resealing) activities.","pyqMatches":[{"year":"2012","no":390,"q":"Enzyme require for cutting the strand DNA synthesis?","o":["DNA polymerase","DNA ligase","Topoisomerase","Helicase"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1420, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 539, '{"id":1420,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":539,"q":"Increased uric acid levels are seen in which glycogen storage disease ?","o":["Type I","Type II","Type III","Type IV"],"a":0,"e":"Ans. is ''a'' i.e., Type I [Ref Harper 29m/e p. 339] Purine overproduction and hyperuricemia in von Gierke disease (glucose-6-phosphatase deficiency) occurs secondary to enhanced generation of PRPP precursor, i.e. ribose-5-phosphate (a pentose). In glucose-6-phosphatase deficiency, glucose-6-phosphate cannot be converted to glucose. Accumulated glucose-6-phosphate is then metabolized via HMP shunt, which in turn generates large amounts of ribose-5-phosphate, a precursor of PRPP. The increased synthesis of PRPP then enhances de novo synthesis of purine nucleotides","pyqMatches":[{"year":"2012","no":280,"q":"Increased uric acid levels are seen in which glycogen storage disease ?","o":["Type I","Type II","Type III","Type IV"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1421, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 540, '{"id":1421,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":540,"q":"Gulonate dehydrogenase requires ?","o":["NADP","NAD","FAD","FMN"],"a":0,"e":"Ans. is ''a'' i.e., NADP [Rep Harper 29t5/e p. 201-204] Gulonate dehydrogenase is an enzyme in glucuronic acid pathway (uronic acid pathway) that requires NADP''.","pyqMatches":[{"year":"2012","no":281,"q":"Gulonate dehydrogenase requires ?","o":["NADP","NAD","FAD","FMN"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1422, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 541, '{"id":1422,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":541,"q":"Reverse transcription involves ?","o":["RNA dependent DNA synthesis","DNA dependent RNA synthesis","DNA dependent DNA synthesis","RNA dependent RNA synthesis"],"a":0,"e":"Ans. is ''a'' i.e., RNA dependent DNA synthesis [Ref Harper 29thle p. 348] Synthesis of RNA from DNA is called transcription. In transcription, RNA is synthesized by RNA polymerase. RNA polymerase is also called DNA dependent RNA polymerase because it is dependent on DNA (non-coding strand) for RNA synthesis. Reverse transcription, as the name suggests, is the reverse of transcription i.e. synthesis of DNA form RNA. In reverse transcription DNA is synthesized by reverse transcriptase. Reverse transcriptase is also called RNA dependent DNA polymerase because it is dependent on RNA for DNA synthesis.","pyqMatches":[{"year":"2012","no":389,"q":"Reverse transcription involves ?","o":["RNA dependent DNA synthesis","DNA dependent RNA synthesis","DNA dependent DNA synthesis","RNA dependent RNA synthesis"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1423, 'Biochemistry', 'Genetics', 'Easy', 'Biochemistry', 542, '{"id":1423,"subject":"Biochemistry","chapter":"Genetics","difficulty":"Easy","source":"Biochemistry","sourceNo":542,"q":"Mutation in GLUT-2 causes ?","o":["Dandy walker syndrome","Fanconi becker syndrome","Beckwith syndrome","Menke''s disease"],"a":1,"e":"Ans. is ''b'' i.e., Fanconi becker syndrome [Ref Diagnostic of Endocrine function is children and adolescents p. 271] GLUT 2 is expressed in pancreatic 13-cells, hepatocytes and in epithelial cells of kidney and intestine. Fanconi-Bickel syndrome is caused by GLUT 2 mutation, a disease characterized by proximal renal tubulopathy, impaired glucose homeostasis and hepatomegaly.","pyqMatches":[{"year":"2012","no":283,"q":"Mutation in GLUT-2 causes ?","o":["Dandy walker syndrome","Fanconi becker syndrome","Beckwith syndrome","Menke''s disease"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1424, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 543, '{"id":1424,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":543,"q":"Amino sugar are formed forms ?","o":["Glucose- 1 -phosphate","Glucose-6-phosphate","Fructose- 1 -phosphate","Fructose-6-phosphate"],"a":3,"e":"Ans. is ''d'' i.e., Fructose-6-phosphate [Ref Dinesh puri 3rdle p. 170] Amino sugars are dervatives of monosaccharides in which an amino group replaces the -OH residue on carbon-2 of hexose, such as glucose, galactose and mannose, The corresponding compounds are glucosamine, galactosamine and mannosamine, respectively. The amino acid group is usually acetylated, e.g. N- acetylglucosamine or N-actylgalactosamine. The amino sugars are required for the synthesis of glycolipids, glycoproteins and proteoglycans. They are synthesized from fructose-6-phosphate","pyqMatches":[{"year":"2012","no":284,"q":"Amino sugar are formed forms ?","o":["Glucose- 1 -phosphate","Glucose-6-phosphate","Fructose- 1 -phosphate","Fructose-6-phosphate"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1425, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 544, '{"id":1425,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":544,"q":"Difference between ganglioside & cerebroside, all except?","o":["Charge","Presence of NANA","Presence of carbohydrate","Native tissue"],"a":2,"e":"Ans. is ''c'' i.e., Presence of carbohydrate [Ref Lippincott''s 4th/e p. 208-210] Both ganglioside and cerebroside contain carbohydrate as both are glycolipids. NANA is present in ganglioside (not in cerebroside).","pyqMatches":[{"year":"2012","no":285,"q":"Difference between ganglioside & cerebroside, all except?","o":["Charge","Presence of NANA","Presence of carbohydrate","Native tissue"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1426, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 545, '{"id":1426,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":545,"q":"In glycolysis, NADH is produced at ?","o":["Pyruvate kinase","Enolase","Glyceraledehyde-3-P-dehydrogenase","PFK-1"],"a":2,"e":"Ans. is ''c'' i.e., Glyceraledehyde-3-P-dehydrogenase [Ref Harper 28th/e p. 151-152] Reducing equivalent (NADH) production is catalyzed by : Glyceraldehyde 3-phosphate dehydrogenase","pyqMatches":[{"year":"2012","no":388,"q":"In glycolysis, NADH is produced at ?","o":["Pyruvate kinase","Enolase","Glyceraledehyde-3-P-dehydrogenase","PFK-1"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1427, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 546, '{"id":1427,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":546,"q":"1\" acetyl group donor in fatty acid synthesis is ?","o":["Malonyl CoA","Palmitate","Acetyl CoA","Citrate"],"a":2,"e":"Ans. is ''c'' i.e., Acetyl CoA [Ref : Harper 29\"le p. 216-217] Acetyl-CoA acts as a primer to donate 1st 2 carbon atoms (C-15 and C-16) of palmitate. The addition of all the subsequent C2 units is via malonyl-CoA. Propionyl-CoA acts as primer (for donating first 3 carbon atoms) in the synthesis of odd-carbon number fatty acids.","pyqMatches":[{"year":"2012","no":286,"q":"1\" acetyl group donor in fatty acid synthesis is ?","o":["Malonyl CoA","Palmitate","Acetyl CoA","Citrate"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1428, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 547, '{"id":1428,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":547,"q":"Chargaff''s rule states that ?","o":["A=T, G=C","A=G, T=C","A=C, G=T","Any combination possible"],"a":0,"e":"Ans. is ''a'' i.e., A=T, G=C [Ref : Harper 29th/e p. 344 & 28thle p. 302; Essentials of biochemistry p. 915] Chargaffs rule states that in DNA of all species quantities of purines is the same as that of pyrimidines, i.e. A+G = T+C","pyqMatches":[{"year":"2012","no":387,"q":"Chargaff''s rule states that ?","o":["A=T, G=C","A=G, T=C","A=C, G=T","Any combination possible"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1429, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 548, '{"id":1429,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":548,"q":"Only vitamin that help in carbon fixation ?","o":["Folic acid","Pantothenic acid","Niacin","Thiamine"],"a":0,"e":"Ans. is ''a'' i.e., Folic acid","pyqMatches":[{"year":"2012","no":287,"q":"Only vitamin that help in carbon fixation ?","o":["Folic acid","Pantothenic acid","Niacin","Thiamine"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1430, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 549, '{"id":1430,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":549,"q":"Rate controlling enzyme of fatty acid synthesis -","o":["Thioesterase","Transacetylase","Acetyl-CoA carboxylase","Ketacyl synthase"],"a":2,"e":"Ans. is ''c'' i.e., Acetyl-CoA carboxylase [Ref Harper 29th/e p. 217, 220] Production of malonyl-CoA is the initial° and rate limiting step in fatty acid synthesis. Acetyl-CoA needs to be converted to activated form, which will serve as the donor of carbon units to growing fatty acid chain. Malonyl-CoA°) a 3- carbon compound is such activated form. It is produced by carboxylation of acetyl-CoA, a reaction catalyzed by acetyl-CoA caroxylase°. Acetyl-CoA carboxylase requires biotin as a cofactor°.","pyqMatches":[{"year":"2012","no":288,"q":"Rate controlling enzyme of fatty acid synthesis","o":["Thioesterase","Transacetylase","Acetyl-CoA carboxylase","Ketacyl synthase"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1431, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 550, '{"id":1431,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":550,"q":"Primer function is in ?","o":["Transcription","Translation","Initiation of DNA replication","Termination of DNA replication"],"a":2,"e":"Ans. is ''c'' i.e., Initiation of DNA replication [Ref Harper''s 29th le p. 366, 367] DNA synthesis cannot commence with deoxyribonucleotides because DNA polymerase cannot add a mononucleotide to another mononucleotide. Thus, DNA polymerase cannot initiate synthesis of complementary DNA synthesis strand of DNA on a totally single stranded template. For this, they require RNA primer, which is a short piece of RNA formed by enzyme primase° (RNA polymerase°) using DNA as a template. RNA primer is then extended by addition of deoxyribonucleotides. Later on, the ribonucleotides of the primer are replaced by deoxyribo nucleotides.","pyqMatches":[{"year":"2012","no":386,"q":"Primer function is in ?","o":["Transcription","Translation","Initiation of DNA replication","Termination of DNA replication"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1432, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 551, '{"id":1432,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":551,"q":"Which of the following is a ribozyme?","o":["Peptidyl transferase","Elongation factor 2","Primase","RNA polymerase"],"a":0,"e":"Ans. is ''a'' i.e., Peptidyl transferase [Ref Harper 29thIe p. 405] Some RNA molecules have intrinsic catalytic activity. The activity of these ribozymes often involves the cleavage of nucleic acid. Two important RNA enzymes or ribozymes are : ? The peptidyl transferase that catalyzes peptide bond formation on the ribosome and Ribozymes involved in the RNA splicing.","pyqMatches":[{"year":"2012","no":385,"q":"Which of the following is a ribozyme?","o":["Peptidyl transferase","Elongation factor 2","Primase","RNA polymerase"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1433, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 552, '{"id":1433,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":552,"q":"Which RNA is used in RNA splicing ?","o":["mRNA","Small nuclear RNA","Small cytosolic RNA","tRNA"],"a":1,"e":"Ans. is ''B'' i.e., Small nuclear RNA [Ref Harper 29th/e p. 378, 390] Splicesome Splicesome is an assembly made up of small nuclear RNA (snRNA), some proteins and hnRNA. snRNA combines with proteins to form small nuclear ribnonucleoprotein particles (snRNPs or snurps) that mediate splicing. It is snRNA component of snurps that catalyzes splicing°. Snurps are U,,U,,U3,U4, U5 and U6","pyqMatches":[{"year":"2012","no":384,"q":"Which RNA is used in RNA splicing ?","o":["mRNA","Small nuclear RNA","Small cytosolic RNA","tRNA"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1434, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 553, '{"id":1434,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":553,"q":"What is attatched to 3'' end of mRNA after transcription?","o":["Poly Atail","CCA","Intron","7-methylguanosine"],"a":0,"e":"Ans. is ''a'' i.e.,Poly Atail [Ref: Harper''s 29`h/e p. 392] Mammalian mRNA molecules contain a 7-methylguanosine cap structure at their 5'' terminal, and most have a poly (A) tail at the 3'' terminal. Prokaryotic mRNA is functional immediately upon synthesis, i.e. prokaryotic primary transcript of mRNA is functional. Thus it does not require post-transcriptional modification. In Eukaryotes the primary transcript of mRNA is the hn RNA (hetrogeneous nuclear RNA). After transcription hnRNA is extensively modified to form functional mRNA.","pyqMatches":[{"year":"2012","no":383,"q":"What is attatched to 3'' end of mRNA after transcription?","o":["Poly Atail","CCA","Intron","7-methylguanosine"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1435, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 554, '{"id":1435,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":554,"q":"Primase functions as ?","o":["Joining DNA fragments","Synthesining small RNA fragments during DNA synthesis","Synthesising small RNA fragments during translation","Unwinding of DNA"],"a":1,"e":"Ans. is ''b'' i.e., Synthesining small RNA fragments during DNA synthesis [Ref Harper''s 29th/e p. 366, 367]","pyqMatches":[{"year":"2012","no":382,"q":"Primase functions as ?","o":["Joining DNA fragments","Synthesining small RNA fragments during DNA synthesis","Synthesising small RNA fragments during translation","Unwinding of DNA"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1436, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 555, '{"id":1436,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":555,"q":"What is the function of DNA ligase ?","o":["Unwinding (denaturation) of dsDNA to provide an ssDNA template","Seals the single strand nick between the nascent chain and Okazaki fragments on lagging strand","Initiation of DNA synthesis and elongation","Initiates synthesis of RNA primers"],"a":1,"e":"Ans. is ''b'' i.e., Seals the single strand nick between the nascent chain and Okazaki fragments on lagging strand [Ref Harper 2501e p. 367]","pyqMatches":[{"year":"2012","no":381,"q":"What is the function of DNA ligase ?","o":["Unwinding (denaturation) of dsDNA to provide an ssDNA template","Seals the single strand nick between the nascent chain and Okazaki fragments on lagging strand","Initiation of DNA synthesis and elongation","Initiates synthesis of RNA primers"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1437, 'Biochemistry', 'Molecular Biology', 'Moderate', 'Biochemistry', 556, '{"id":1437,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Moderate","source":"Biochemistry","sourceNo":556,"q":"Central Dogma of molecular biology indudes all except ?","o":["Transcription","Translation","RNA replication","DNA replication"],"a":2,"e":"Ans. is ''c'' i.e., RNA replication DNA stores genetic information :- Information about amino acid sequence of all the proteins is present in the form of genes in DNA. The entire genetic material present in the DNA of an organism is known as genome. The important role of DNA in transfer of information in living cells is called central dogma of molecular biology. According to the central dogma, information flows from DNA to RNA to protein.","pyqMatches":[{"year":"2012","no":380,"q":"Central Dogma of molecular biology indudes all except ?","o":["Transcription","Translation","RNA replication","DNA replication"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1438, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 557, '{"id":1438,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":557,"q":"Nucleotide consists of all except ?","o":["Sugar","Phosphate","Fatty acid","Base"],"a":2,"e":"Ans. is ''c'' i.e., Fatty acid [Ref Harper''s 28\"/e p. 286] Nucleotides are monomeric units of nucleic acids. They are required for synthesis of nucleic acid. Each nucleotide is made up of : (i) A nitrogenous base, (ii) A sugar (pentose sugar) and (iii) A phosphate group (phosphoric acid). Nitrogenous base combines with a sugar to form nucleosides. The nucleoside combines with phosphoric acid to form a nucleotide.","pyqMatches":[{"year":"2012","no":379,"q":"Nucleotide consists of all except ?","o":["Sugar","Phosphate","Fatty acid","Base"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1439, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 558, '{"id":1439,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":558,"q":"Which of the following is required for fatty acid synthesis ?","o":["NADPH","NADH","FADH","None"],"a":0,"e":"Ans. is ''a'' i.e.,NADPH [Ref Harper 29th/e p. 216-217] Fatty acid synthesis takes place in cytosolQ. Acetyl-CoA is the immediate substrate for lipogenesis and synthesis always ends in formation of plamitic acie. In humans; liver and lactating mammary glands are the main organs for lipogenesisQ. Although kidney, brain, lungs and adipose tissue are also involved, to a lesser extent. Cofactor requirements for fatty acid synthesis are NADPH, ATP, Mr1.2, biotin and HCO3- (as a source of CO2). Because most fatty acids have multiples of two carbons, they are synthesized from successive addition of two carbon units, the donor of which is acetyl-CoA. So, the basic building block is acetyl-CoA° which is the source of all the carbon atoms of the fatty acid being synthesized.","pyqMatches":[{"year":"2012","no":289,"q":"Which of the following is required for fatty acid synthesis ?","o":["NADPH","NADH","FADH","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1440, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 559, '{"id":1440,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":559,"q":"Shine dalgarno sequence is related to ?","o":["Transcription","Translation","DNA replication","None"],"a":1,"e":"Ans. is ''b'' i.e., Translation Shine dalgarno sequence in prokaryotes and Kozak consensus sequences in eukaryotes helps in initiation of protein synthesis (Translation) In prokaryotes, a sequence of nucleotide bases on mRNA known as Shine-Dalgarno sequence (SD sequence) facilitates the binding of mRNA to the preinitiation complex. SD sequence is a purine-rich sequence of nucleotide bases, which is located -6 to -10 bp from AUG codon°. In Eukaryotes, ''Kozak consensus'' sequence surrounds AUG (initiation codon) and determines the initiating codon of mRNA.","pyqMatches":[{"year":"2012","no":378,"q":"Shine dalgarno sequence is related to ?","o":["Transcription","Translation","DNA replication","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1441, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 560, '{"id":1441,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":560,"q":"Citrate used in fatty acid synthesis uses which enzyme ?","o":["Citrate Synthase","ATP citrate lyase","Aconitase","Malic enzyme"],"a":1,"e":"Ans. is ''b'' i.e., ATP citrate lyase [Ref Harper''s 28th/e p. 193, 196] Glucose is the primary substrate for lipogenesis and acetyl-CoA (immediate substrate for fatty acid synthesis) is formed from glucose via oxidation of pyruvate within the mitochondria. However, acetyl-CoA can not penetrate inner mitochondrial membrane. Therefore it is transferred in the form of citrate. Citrate is formed in the mitochondrial matrix by the condensation of acetyl-CoA with oxaloacetate (first reaction in citric acid cycle). Then citrate is transported into cytosol via the tricorboxylate transporter in exchange with malate. In cytosol, citrate is cleaved by ATP-citrate lyase to oxaloacetate and acetyl-CoA.","pyqMatches":[{"year":"2012","no":290,"q":"Citrate used in fatty acid synthesis uses which enzyme ?","o":["Citrate Synthase","ATP citrate lyase","Aconitase","Malic enzyme"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1442, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 561, '{"id":1442,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":561,"q":"Which of the following is w-6 fatty acid -","o":["Cervonic acid","Linoleic acid","Alpha linolenic acid","Elaidic acid"],"a":1,"e":"Ans. is ''b'' i.e., Linoleic acid [Ref Harper 28th/e p. 123] Alpha linolenic acid → Linoleic acid → Oleic acid Clupandonic acid→ Gama linolenic acid → Nervonic acid Cervonic acid → Arachidonic acid → Elaidic acid","pyqMatches":[{"year":"2012","no":291,"q":"Which of the following is w-6 fatty acid","o":["Cervonic acid","Linoleic acid","Alpha linolenic acid","Elaidic acid"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1443, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 562, '{"id":1443,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":562,"q":"Linoleic acid is -","o":["w-3 fatty acid","w-6 fatty acid","w-9 fatty acid","Saturated fatty acid"],"a":1,"e":"Ans. is b'' i.e., w-6 fatty acid [Ref Harper 28thle p. 123]","pyqMatches":[{"year":"2012","no":292,"q":"Linoleic acid is","o":["w-3 fatty acid","w-6 fatty acid","w-9 fatty acid","Saturated fatty acid"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1444, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 563, '{"id":1444,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":563,"q":"Watson crick model is for which DNA ?","o":["B DNA","A DNA","C DNA","Z DNA"],"a":0,"e":"Ans. is ''a'' i.e., B DNA [Ref : Harper 250/e p. 344] DNA is the repository of genetic information. DNA is located in nucleus. DNA is also present in mitochondria","pyqMatches":[{"year":"2012","no":376,"q":"Watson crick model is for which DNA ?","o":["B DNA","A DNA","C DNA","Z DNA"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1445, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 564, '{"id":1445,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":564,"q":"Lipogenesis occurs in ?","o":["Liver","Skeletal muscles","Myocardium","Lungs"],"a":0,"e":":D Ans. is ''a > d'' i.e., Liver > Lungs Fatty acid synthesis takes place in cytosol°. Acetyl-CoA is the immediate substrate for lipogenesis and synthesis always ends in formation of palmitic acid.","pyqMatches":[{"year":"2012","no":293,"q":"Lipogenesis occurs in ?","o":["Liver","Skeletal muscles","Myocardium","Lungs"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1446, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 565, '{"id":1446,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":565,"q":"Which of the following is monoenoic acid ?","o":["Arachidonic acid","Linoleic acid","Oleic acid","Linolenic acid"],"a":2,"e":"Ans. C. Oleic acid In humans; liver and lactating mammary glands are the main organs for lipogenesisQ. Although kidney, brain, lungs and adipose tissue are also involved, to a lesser extent. Cofactor requirements for fatty acid synthesis are NADPH, ATP, Mn.2, biotin and HCO3- (as a source of CO). Because most fatty acids have multiples of two carbons, they are synthesized from successive","pyqMatches":[{"year":"2012","no":294,"q":"Which of the following is monoenoic acid ?","o":["Arachidonic acid","Linoleic acid","Oleic acid","Linolenic acid"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1447, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 566, '{"id":1447,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":566,"q":"Which of the following is not involved in synthesis of pyrimidines?","o":["Glutamine","CO","Aspartic acid","Glycine"],"a":3,"e":"Ans. is ''d'' i.e., Glycine [Ref Harper 29th/e p. 336-337] Amino acids involved in purine synthesis → Glycine, aspartate, glutamine. Amino acids involved in pyrimidine synthesis → Glutamine, aspartic acid (aspartate)","pyqMatches":[{"year":"2012","no":375,"q":"Which of the following is not involved in synthesis of pyrimidines?","o":["Glutamine","CO","Aspartic acid","Glycine"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1448, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 567, '{"id":1448,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":567,"q":"Which of the following fatty acid has maximum number of carbon atoms ?","o":["Oleic acid","Linolenic acid","Arachidonic acid","Cervonic acid"],"a":3,"e":"Ans. is ''d'' i.e., Cervonic acid Cervonic acid has 22 carbon atoms, more than oleic acid (18C), linolenic acid (18C) and arachidonic acid (20C). So, the basic building block is acetyl-CoAQ which is the source of all the carbon atoms of the fatty acid being synthesized.","pyqMatches":[{"year":"2012","no":295,"q":"Which of the following fatty acid has maximum number of carbon atoms ?","o":["Oleic acid","Linolenic acid","Arachidonic acid","Cervonic acid"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1449, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 568, '{"id":1449,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":568,"q":"Chylomicron remnants are associated with ?","o":["Apo-A","Apo-B100","Apo-E","Apo-C"],"a":2,"e":"Ans. is ''c'' i.e., Apo-E","pyqMatches":[{"year":"2012","no":296,"q":"Chylomicron remnants are associated with ?","o":["Apo-A","Apo-B100","Apo-E","Apo-C"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1450, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 569, '{"id":1450,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":569,"q":"Purine are formed by ?","o":["Aspartic acid, glycine, uric acid","Aspartate, glycine,","Aspartate, glutamate","Aspartate, glycine, glutamine"],"a":3,"e":"Ans. is ''d'' i.e., Aspartate, Glycine, Glutamine [Ref Harper 29thie p. 332] Amino acids involved in purine synthesis → Glycine, aspartate, glutamine. Amino acids involved in pyrimidine synthesis → Glutamine, aspartic acid (aspartate).","pyqMatches":[{"year":"2012","no":374,"q":"Purine are formed by ?","o":["Aspartic acid, glycine, uric acid","Aspartate, glycine,","Aspartate, glutamate","Aspartate, glycine, glutamine"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1451, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 570, '{"id":1451,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":570,"q":"Apoprotein - C ?","o":["Activates lipoprotein lipase","Inactivates lipoprotein lipase","Facilitates triglyceride transport","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above [Ref Harper 28th/e p. 213] Apo C-II is an activator of LPL, wheras apo A-II and apo C-III act as inhibitors of LPL. As apo-C is a component of chylomicrons and VLDL, it facilitates transport of TGs.","pyqMatches":[{"year":"2012","no":297,"q":"Apoprotein - C ?","o":["Activates lipoprotein lipase","Inactivates lipoprotein lipase","Facilitates triglyceride transport","All of the above"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1452, 'Biochemistry', 'Lipid Metabolism', 'Moderate', 'Biochemistry', 571, '{"id":1452,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":571,"q":"Which is not true of chylomicrons ?","o":["Lowest desnsity","Max. content is TGs","Max. content is cholesterol","Largest size"],"a":2,"e":"Ans. is ''c'' i.e., Max.content is cholesterol [Ref: Harper 29th/e p. 238, Chatterjea 8th le p. 445, 446]","pyqMatches":[{"year":"2012","no":298,"q":"Which is not true of chylomicrons ?","o":["Lowest desnsity","Max. content is TGs","Max. content is cholesterol","Largest size"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1453, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 572, '{"id":1453,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":572,"q":"Beta-alanine is derived from ?","o":["Adenosine","Guanosine","Thymine","Uracil"],"a":3,"e":"Ans. is ''d'' i.e., Uracil [Ref: Harper 29ille p. 339, 340]","pyqMatches":[{"year":"2012","no":373,"q":"Beta-alanine is derived from ?","o":["Adenosine","Guanosine","Thymine","Uracil"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1454, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 573, '{"id":1454,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":573,"q":"Oxidised LDL is more athreogenic because ?","o":["Binds to Apo E","Binds to scavenger R","Binds to ATP binding","Accumulates in macrophages"],"a":3,"e":"Ans. is ''d'' i.e., Accumulates in macrophages [Ref Robbin''s 8thle p. 837] Macrophages engulf LDL cholesterol and form foam cells formation of earliest lesion, i.e. fatty streak. Macrophages also form oxygen free radicals that cause oxidation of LDL to yield oxidized LDL (modified LDL).","pyqMatches":[{"year":"2012","no":299,"q":"Oxidised LDL is more athreogenic because ?","o":["Binds to Apo E","Binds to scavenger R","Binds to ATP binding","Accumulates in macrophages"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1455, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 574, '{"id":1455,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":574,"q":"Adenine phosphoribosyl transferase is involved ?","o":["De novo purine synthesis","Purine degradation","Salvage synthesis of purine nucleotides","None"],"a":2,"e":"Ans. is ''c'' i.e., Salvage synthesis of purine nucleotides [Ref Harper 29thie p. 334-335] Salvage pathway of purine nucleotide synthesis Free purine bases (adenine, guanine and hypoxanthine) and purine nucleosides are formed in cells during the metabolic degradation of nucleic acids and nucleotides. These free purine bases and purine nucleosides are reused in the formation of purine nucleotides. This is called salvage pathway (salvage means property saved from loss). Salvage synthesis requires far less energy than de novo synthesis.","pyqMatches":[{"year":"2012","no":371,"q":"Adenine phosphoribosyl transferase is involved ?","o":["De novo purine synthesis","Purine degradation","Salvage synthesis of purine nucleotides","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1456, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 575, '{"id":1456,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":575,"q":"Hormone sensitive lipase is inhibited by?","o":["Thyroid homone","Insulin","GH","ACTH"],"a":1,"e":"Ans. is `b'' i.e.,Insulin [Ref Harper 29\"Ve p. 246, 247]","pyqMatches":[{"year":"2012","no":301,"q":"Hormone sensitive lipase is inhibited by?","o":["Thyroid homone","Insulin","GH","ACTH"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1457, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 576, '{"id":1457,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":576,"q":"Lecithine hydrolysis yeilds ?","o":["Choline","Pyruvate","Glycine","None"],"a":0,"e":"Ans. is ''a'' i.e.,Choline [Ref Harper 29th/e p. 233]","pyqMatches":[{"year":"2012","no":302,"q":"Lecithine hydrolysis yeilds ?","o":["Choline","Pyruvate","Glycine","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1458, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 577, '{"id":1458,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":577,"q":"Which of the following requires vitamin BIZ ?","o":["Serine to lysine","Homocysteine to methionine","Serine to glycine","Glutamine to glutamate"],"a":1,"e":"Ans. is ''b'' i.e., Homocysteine to methionine [Ref: Harper 2967e p. 537-539] Conversion of homocystein to methionine In this reaction, active form is methylcobalamine. This is the only reaction which requires both vitamin B,2 (as methylcobalamine) and folic acid (as N5-methyl- Hdolate). The reaction is catalyzed by the enzyme cobalamin- dependent methionine synthase also called 5- methyltetrahydrofolate-homocysteine methyltransferase","pyqMatches":[{"year":"2012","no":369,"q":"Which of the following requires vitamin BIZ ?","o":["Serine to lysine","Homocysteine to methionine","Serine to glycine","Glutamine to glutamate"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1459, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 578, '{"id":1459,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":578,"q":"The pyruvate utilization in tissues is decreased in ?","o":["Pernicious anemia","Scurvy","Beriberi","Pellagra"],"a":2,"e":"Ans. is ''c'' i.e., Beriberi [Ref Harper 29th/e p. 534] Pyruvate utilization is decreased in thiamine deficiency. Beriberi is due to thiamine deficiency. In thiamine deficiency, pyruvate cannot be converted to acetyl-CoA as thiamine pyrophosphate is a coenzyme for pyruvate dehydrogenase which catalyzes the conversion of pyruvate to acetyl-CoA. Hence, excess of pyruvate is metabolized to lactate by lactate dehydrogenase","pyqMatches":[{"year":"2012","no":368,"q":"The pyruvate utilization in tissues is decreased in ?","o":["Pernicious anemia","Scurvy","Beriberi","Pellagra"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1460, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 579, '{"id":1460,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":579,"q":"Coenzyme form of pyridoxine is ?","o":["ADP","NAD","PLP","FAD"],"a":2,"e":"Ans. is ''c'' i.e.,PLP [Ref Guyton 12thie p. 854]","pyqMatches":[{"year":"2012","no":364,"q":"Coenzyme form of pyridoxine is ?","o":["ADP","NAD","PLP","FAD"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1461, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 580, '{"id":1461,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":580,"q":"Omega oxidation of fathy acids occur?","o":["ER","Mitochondria","Cytosol","None"],"a":0,"e":"Ans. is ''a'' i.e.,ER [Ref Harper''s 28th/e p. 185, 195] Beta (a) → Mitochondria Alpha (a) → Endoplasmic reticulum, Mitochandria Omega (w) → Microsomal system (smooth ER) a-oxidation of very long chain FA → Peroxisomes","pyqMatches":[{"year":"2012","no":303,"q":"Omega oxidation of fathy acids occur?","o":["ER","Mitochondria","Cytosol","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1462, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 581, '{"id":1462,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":581,"q":"Most potent anti oxidant ?","o":["Vit A","Vit K","Vit E","Vit C"],"a":2,"e":"Ans. is ''c'' i.e., Vit E [Ref : Harper 29thie p. 532, 541, 543] Amongst given options, vitamin A, E and C are anti-oxidants. However, Vitamin E (tocopherol) is the most important antioxidant in the body, acting in the lipid phase of membranes protecting against the effects of free radicals.","pyqMatches":[{"year":"2012","no":229,"q":"Most potent anti oxidant ?","o":["Vit A","Vit K","Vit E","Vit C"],"a":2,"source":"NEET_2012_Paper.pdf"},{"year":"2012","no":363,"q":"Most potent anti oxidant ?","o":["Vit A","Vit K","Vit E","Vit C"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1463, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 582, '{"id":1463,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":582,"q":"What is true regarding medium chain fatty acids ?","o":["Don''t require pancreatic lipase","Not deposited in adipose tissue","Diffuse directly into portal circulation","All of the above"],"a":3,"e":"Ans. is ''d'' i.e.,All of the above [Ref Vasudevan 6\" p. 160] Metabolism of short chain fatty acids (SCFAs) and medium chain fatty acids (MCFAs) is drastically different from long chain fatty acids (LCFAs). SCFAs and MCFAs do not require pancreatic lipase and bile salts for digestion, but required for LCFAs digestion. SCFAs and MCFAs are directly absorbed from intestine into portal circulation, whereas LCFAs are taken by lymphatics, after incorporation into chylomicrons. SCFAs and MCFAs are oxidized by peripheral cells and are not used for storage. LCFAs are esterified with glycerol to form triacylglycerol, storage form of lipid","pyqMatches":[{"year":"2012","no":304,"q":"What is true regarding medium chain fatty acids ?","o":["Don''t require pancreatic lipase","Not deposited in adipose tissue","Diffuse directly into portal circulation","All of the above"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1464, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 583, '{"id":1464,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":583,"q":"What will you give to stop chyluria in diet?","o":["Small chain FA","Medium chain FA","Long chain FA","Omega 3 unsaturated FA"],"a":1,"e":"Ans. is ''b'' i.e.,Medium Chain FA [Ref Harrison''s 18thie p. 294] Medium chain fatty acids directly enter the portal vein on absorption,bypassing the lymphatics.Hence,they are used in chyluria","pyqMatches":[{"year":"2012","no":305,"q":"What will you give to stop chyluria in diet?","o":["Small chain FA","Medium chain FA","Long chain FA","Omega 3 unsaturated FA"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1465, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 584, '{"id":1465,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":584,"q":"Pantothenic acid is needed for donating the following moiety ?","o":["Acetyl (or acyl) CoA","Carboxyl","Hydroxyl","Amino"],"a":0,"e":"Ans. is ''a'' i.e., Acetyl (or acyl) CoA [Ref Harper 29th/e p. 540] Pantothenic acid functions as coenzyme by providing building block of coenzyme A and ACP","pyqMatches":[{"year":"2012","no":362,"q":"Pantothenic acid is needed for donating the following moiety ?","o":["Acetyl (or acyl) CoA","Carboxyl","Hydroxyl","Amino"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1466, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 585, '{"id":1466,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":585,"q":"Ascorbic acid is required for synthesis of ?","o":["Phenylserine","Homoserine","Hydroxylysine","Selenocysteine"],"a":2,"e":"Ans. is ''c'' i.e., Hydroxylysine [Ref Harper''s 29th/e p. 540] Hydroxylation of proline and lysine residue takes place during post- translational modification in rough ER. The enzyme catalyzing the reactions are prolyl hydroxylase (for proline) and lysyl hydroxylase (for lysine). Both these enzymes are dioxygenases° using molecular oxygen (02) and cofactor for both these enzymes is vitamin C (ascorbic acid)°. a- Ketoglutatrate is a coreductant, which is oxidized to succinate.","pyqMatches":[{"year":"2012","no":359,"q":"Ascorbic acid is required for synthesis of ?","o":["Phenylserine","Homoserine","Hydroxylysine","Selenocysteine"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1467, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 586, '{"id":1467,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":586,"q":"In a person fasting overnight with carnitine deficiency, following chemicals increase in quantity in blood ?","o":["Glucose","Fatty acids","Amino acids","Ketone bodies"],"a":1,"e":"Ans. is ''b'' i.e., Fatty acids [Ref : Harper 29th/e p. 208-209, 214] In starvation, there is increased hydrolysis of TGs (of adipose tissues) into glycerol and fatty acids. Fatty acids are further oxidized by [3-oxidation in the mitochondria. Carnitine is required for transported of activated fatty acid into mitochondria for 3-oxidation. If carnitine is deficient, fatty acids cannot be transferred into the mitochondria, but they are continuously produced due to hydrolysis of TGs (in starvation there is decreased insulin to glucagon ratio, which stimulates hydrolysis of TGs). Thus free fatty acid level is increased as there is increased production but no utilization (p-oxidation).","pyqMatches":[{"year":"2012","no":306,"q":"In a person fasting overnight with carnitine deficiency, following chemicals increase in quantity in blood ?","o":["Glucose","Fatty acids","Amino acids","Ketone bodies"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1468, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 587, '{"id":1468,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":587,"q":"Which of the following is a Fat Soluble vitamin ?","o":["Thiamine","Niacine","Vitamin A","Ribaflavin"],"a":2,"e":"Ans. is ''c'' i.e., Vitamin A [Ref Harper''s 296/e p. 335]","pyqMatches":[{"year":"2012","no":358,"q":"Which of the following is a Fat Soluble vitamin ?","o":["Thiamine","Niacine","Vitamin A","Ribaflavin"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1469, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 588, '{"id":1469,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":588,"q":"Serum appeary milky white in ?","o":["Increased LDL","Increased HDL","Increased VLDL","Increased Chylomicrons"],"a":3,"e":"Ans. is ''d'' i.e., Increased Chylomicrons [Ref Harrison 18thle p. 3151] \"The fasting plasma is turbid, and if left at 4°C (39.2°F) for a few hours, the chylomicrons float to the top and form a creamy supernatant\". Chylomicrons are the largest lipoprotein molecule with maximum lipid contents. Therefore, they have least density and float on the top giving a creamy (milky) supernatant.","pyqMatches":[{"year":"2012","no":307,"q":"Serum appeary milky white in ?","o":["Increased LDL","Increased HDL","Increased VLDL","Increased Chylomicrons"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1470, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 589, '{"id":1470,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":589,"q":"Overnight fasting what occurs ?","o":["Glucose decreases","FFA increases","Increased gluconeogenesis","Increased beta-hydroxybutyrate"],"a":2,"e":"Ans. is ''c'' i.e., Increased gluconeogenesis [Ref Vasudevan &hie p. 85, 86, Harper 28th/e p. 240, 241] In overnight fasting glucose level is maintained due to glycogenolysis and gluconeogenesis. FFA and ketone bodies (p-hydroxybutyrate) starts rising after 2-3 days, i.e. in later part of initial stage of prolonged starving","pyqMatches":[{"year":"2012","no":357,"q":"Overnight fasting what occurs ?","o":["Glucose decreases","FFA increases","Increased gluconeogenesis","Increased beta-hydroxybutyrate"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1471, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 590, '{"id":1471,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":590,"q":"Adipose tissue fat metabolism is done by ?","o":["Lipoprotein lipase","Hormone sensitive lipase","Acid lipase","Acid maltase"],"a":1,"e":"Ans. is ''b i.e., Hormone sensitive lipase [Ref : Harper 29th/e chap. 16] Adipose tissue fat (TGs) metabolism → Hormone sensitive lipase Lipoproteins (VLDL & chylomicrons) TGs metabolism - Lipoprotein lipase","pyqMatches":[{"year":"2012","no":308,"q":"Adipose tissue fat metabolism is done by ?","o":["Lipoprotein lipase","Hormone sensitive lipase","Acid lipase","Acid maltase"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1472, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 591, '{"id":1472,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":591,"q":"RQ is least in ?","o":["Brain","RBC","Adipose","Heart"],"a":3,"e":"Ans. is ''d'' i.e., Heart [Ref Read below] Respiratory qnotient (RQ) of :","pyqMatches":[{"year":"2012","no":356,"q":"RQ is least in ?","o":["Brain","RBC","Adipose","Heart"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1473, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 592, '{"id":1473,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":592,"q":"Enzyme deficient in Type I Hyperlipidemia is ?","o":["HMG CoA reductase","Lipoprotein lipase","Cholesterol acyl transferase","Peroxidase"],"a":1,"e":"Ans. is ''b'' i.e.,Lipoprotein lipase [Ref : Harper 2e/e p. 232 table (26.1)]","pyqMatches":[{"year":"2012","no":309,"q":"Enzyme deficient in Type I Hyperlipidemia is ?","o":["HMG CoA reductase","Lipoprotein lipase","Cholesterol acyl transferase","Peroxidase"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1474, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 593, '{"id":1474,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":593,"q":"Apo-E dificiency is seen in","o":["Tpye I hypolipoproteinemia","Tpye II hypolipoproteinemia","Tpye III hypolipoproteinemia","Tpye IV hypolipoproteinemia"],"a":2,"e":"Ans. is ''c'' i.e., Tpye III hypolipoproteinemis [Ref Harison p. 3149, 3150, Chatterjea 8th/e p. 45]","pyqMatches":[{"year":"2012","no":310,"q":"Apo-E dificiency is seen in","o":["Tpye I hypolipoproteinemia","Tpye II hypolipoproteinemia","Tpye III hypolipoproteinemia","Tpye IV hypolipoproteinemia"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1475, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 594, '{"id":1475,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":594,"q":"Substance with highest thermogenic effect ?","o":["Fat","Proteins","Carbohydrate","All are the same"],"a":1,"e":"Ans. is `b'' i.e., Proteins [Ref Progress in obesity research-397] Thermogenic effect (thermic effect) of food refers to the increase in metabolic rate that occurs after ingestion of particular food. This results in an increase in the amount of heat generated by the body. Protein is at the top of the hierarely of macronutrients, as for as the thermogenic effect in concerned. About 25-30% of energy is consumed to digest the protein. Carbohydrates come in the middle and lipids (fats) are in third place.","pyqMatches":[{"year":"2012","no":354,"q":"Substance with highest thermogenic effect ?","o":["Fat","Proteins","Carbohydrate","All are the same"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1476, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 595, '{"id":1476,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":595,"q":"Anaplerotic reaction is catalyzed by ?","o":["Pyruvate carboxylse","Enolase","Pyruvate kinase","G6PD"],"a":0,"e":"Ans. is ''a'' i.e., Pyruvate carboxylse [Ref Dinesh Puri 3`die p. 177] Conversion of pyruvate to malate by the cytoplasmic malic-enzyme. Malate can then enter the mitochondrion as a substrate for the TCA cycle. Pyruvate may react with aspartate or glutamate in transaminase reactions, producing the TCA cycle intermediates oxalocetate and a- ketogluarate, respectively. Several glycogenic amino acids may serve as source of TCA intermediates","pyqMatches":[{"year":"2012","no":353,"q":"Anaplerotic reaction is catalyzed by ?","o":["Pyruvate carboxylse","Enolase","Pyruvate kinase","G6PD"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1477, 'Biochemistry', 'Lipid Metabolism', 'Moderate', 'Biochemistry', 596, '{"id":1477,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":596,"q":"Which of the following is not affected in Abetalipoproteinemia ?","o":["LDL","VLDL","HDL","IDL"],"a":2,"e":"Ans. is ''c'' i.e., HDL [Ref Chatterjea 8thle p. 462, 463 & Dinesh Puri 3rdle p. 248] Hypolipoproteinemia In this group of disorders concentration of one or more lipoproteins in plasma is decreased. The commonest of these disorders are abetalipoproteinemia, hypobetalipoproteinemia and hypoalphalipoproteinemia. Abetalipoproteinemia:- There is defective synthesis or secretion of apoprotein-B (apo-B) in intestine and liver. So, there is deficiency of apo-B containing lipoproteins i.e. chylomicrons°, VLDL°, IDL° and LDL°. As a result extremely low plasma levels of cholesterol and triacylglycerols° occurs. HDL levels are normal° as HDL does not contain apo-B. Hypobetalipoproteinemia:- There is decreased synthesis of apo-B due to apo-B gene mutations. So, apo-B containing lipoproteins are synthesized at lower rate. There is slight decrease in VLDL, IDL and LDL levels. HDL is normal. Plasma cholesterol and triglycerides are decreased. Hypoalphalipoproteinemia (Tangier disease):- There is marked deficiency of major lipoprotein HDL (apo-A-I and apo-A-II), probably because of accelerated catabolism.","pyqMatches":[{"year":"2012","no":311,"q":"Which of the following is not affected in Abetalipoproteinemia ?","o":["LDL","VLDL","HDL","IDL"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1478, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 597, '{"id":1478,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":597,"q":"In Zellweger syndrome,there is ?","o":["Accumulation of long fatty acids","Accumulation of short chain fatty acids","Accumulation of very long chain fatty acids","Accumulation of medium chain fatty acids"],"a":2,"e":"Ans. is ''c'' i.e., Accumulation of very long chain fatty acids [Ref Harper 29m/e p. 554; Chatterjea 6th le p. 412] Zellweger Syndrome is a rare inborn error of peroxisomal fatty acid oxidation° due to absence of functional peroxisomes in all tissues. As a result, the long chain fatty acids are not oxidized in peroxisomes and accumulate in tissues particularly in brain, liver, kidney and muscle and usually result in death by age six.","pyqMatches":[{"year":"2012","no":312,"q":"In Zellweger syndrome,there is ?","o":["Accumulation of long fatty acids","Accumulation of short chain fatty acids","Accumulation of very long chain fatty acids","Accumulation of medium chain fatty acids"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1479, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 598, '{"id":1479,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":598,"q":"Autooxidation is seen in ?","o":["Cholesterol","Arachidonic acid","Stearic acid","Palmitic acid"],"a":1,"e":"Ans. is ''b'' i.e., Arachidonic acid [Ref Essential of biochemistry p. 736] Polyunsaturated fatty acids (PUFAs) undergo peroxidation (auto- oxidation). Amongst the given options, only arachidonic acid is PUFA.","pyqMatches":[{"year":"2012","no":313,"q":"Autooxidation is seen in ?","o":["Cholesterol","Arachidonic acid","Stearic acid","Palmitic acid"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1480, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 599, '{"id":1480,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":599,"q":"Which of the following is a lipotropic factor : ?","o":["Sphingomyelin","Histidine","Methionine","Bilirubin"],"a":2,"e":"Ans. is ''c'' i.e., Methionine [Ref Essentials of biochemistry/p. 761] Lipotropic factors are substances which prevent accumulation of fat (TGs) in liver. Primary lipotropic factors choline, betaine, methionine, lecithine, inositol. Other factors with some lipotropic action :- Vitamin-13,2, folic acid, casein, glycine, essential fatty acids, selenium, vitamin E and serine.","pyqMatches":[{"year":"2012","no":314,"q":"Which of the following is a lipotropic factor : ?","o":["Sphingomyelin","Histidine","Methionine","Bilirubin"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1481, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 600, '{"id":1481,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":600,"q":"Lipogenesis is stimulated by ?","o":["Insulin","Glucagon","Epinephrine","Corticosteroids"],"a":0,"e":"Ans. is ''a'' i.e., Insulin [Ref Dinesh Puri 3rdie p. 318]","pyqMatches":[{"year":"2012","no":352,"q":"Lipogenesis is stimulated by ?","o":["Insulin","Glucagon","Epinephrine","Corticosteroids"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1482, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 601, '{"id":1482,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":601,"q":"Indole ring is present in ?","o":["Tryptophan","Tyrosine","Phenylalanine","Threonine"],"a":0,"e":"Ans. is ''a'' i.e.,Tryptophan [Ref: Lehninger 4thIe p. 80] Some amino acids contain a special functional group in their side chain which provide some specific functions to that amino acids. These are : - Hydroxyl group in serine and threonine Guanidinium in arginineQ Imidazole in histidine Amide group in aspargine and glutamine Benzene in phenylalanine Phenol in tyrosine Thioether in methionine Indole ring in tryptophanQ Pyrrolidine in proline Sulphydryl in cysteine 13-Carboxyl in glutamic acid E-amino in lysine y-carboxyl in glutamic acid","pyqMatches":[{"year":"2012","no":317,"q":"Indole ring is present in ?","o":["Tryptophan","Tyrosine","Phenylalanine","Threonine"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1483, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 602, '{"id":1483,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":602,"q":"Taurine is biosynthesized by ?","o":["Arginine","Leucine","Valine","Cysteine"],"a":3,"e":"Ans. is ''d'' i.e., Cysteine [Ref Harper 250/e p. 298-99] Taurine is synthesized from cysteine by 3 enzyme-catalyzed reactions :","pyqMatches":[{"year":"2012","no":319,"q":"Taurine is biosynthesized by ?","o":["Arginine","Leucine","Valine","Cysteine"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1484, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 603, '{"id":1484,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":603,"q":"Which of the following is true ?","o":["Glucokinase has high affinity for glucose","Hexokinase has low affinity for glucose","Glucokinase has low affinity for glucose","Hexokinase is induced by insulin"],"a":2,"e":"Ans. is ''c'' i.e., Glucokinase has low effinity for glucose [Ref Harper 28`\"/e p. 151-152] Glucokinase, is specific for glucose. It has high KinQ (i.e., low affinity for glucose), high Vmax and unlike hexokinase, it is not inhibited by glucose-6-phosphateQ. As it has low affinity for glucose (high km), it comes into play only when intracellular glucose concentration is high. It is induced by feeding and insulin. Glucagon inhibits glucokinase. Function of hexokinase is to provide glucose-6-phosphate at a constant rate, according the needs of cells, i.e., function of hexokinase is to provide constant glucose utilization by all tissues of body even when blood sugar is low. Function of glucokinase in the liver is to remove glucose from blood after a meal, providing glucose-6-phosphate in excess of requirement for glycolysis so that it can be used for glycogen synthesis and lipogenesis.","pyqMatches":[{"year":"2012","no":351,"q":"Which of the following is true ?","o":["Glucokinase has high affinity for glucose","Hexokinase has low affinity for glucose","Glucokinase has low affinity for glucose","Hexokinase is induced by insulin"],"a":2,"source":"NEET_2012_Paper.pdf"},{"year":"2015","no":556,"q":"Which of the following is true?","o":["Glucocorticoids upregulate MHC expression","Glucocorticoids activate T-helper cells","Glucocorticoids activate cytotoxic T cells","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"},{"year":"2016","no":801,"q":"Which of the following is true ?","o":["Two live vaccines should not be given together","Live and killed vaccine should not be given together","Immunoglobolin should not be given for at least 6 weeks when a live vaccine is administered","Live vaccine should not be given for 12 weeks if immunoglobin has been given"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2012","2015","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1485, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 604, '{"id":1485,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":604,"q":"Methylmalonyl aciduria is seen in deficiency of ?","o":["Vit B12","Vit B6","Vit C","Folic acid"],"a":0,"e":"Ans. is ''a'' i.e., Vit B12 [Ref Harper 29\"Ve p. 537] Isomerization of methylmalonyl CoA to succinyl CoA : In this reaction, active form of vitamin B I 2is deoxyadenosyl cobalamine. Propionyl-CoA is produced as catabolic end product of some alipathic amino acids and n-oxidation of odd chain fatty acids. Propionyl CoA is then converted to succinyl CoA through methylmalonyl-CoA. Thus methylmalonyl-CoA is accumulated and excreted in urine as methylmalonic acid (methylmalonate) in vitamin B12 deficiency0, i.e. methylmalonic acidurie","pyqMatches":[{"year":"2012","no":321,"q":"Methylmalonyl aciduria is seen in deficiency of ?","o":["Vit B12","Vit B6","Vit C","Folic acid"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1486, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 605, '{"id":1486,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":605,"q":"Carnitine is synthesised from -","o":["Lysine","Agrinine","Histidine","Choline"],"a":0,"e":"Trimethyllysine and γ-butyrobetaine hydroxylases are required for the synthesis of carnitine","pyqMatches":[{"year":"2012","no":322,"q":"Carnitine is synthesised from","o":["Lysine","Agrinine","Histidine","Choline"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1487, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 606, '{"id":1487,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":606,"q":"Chemiosmotic coupling of oxidation phosphorylation is related to ?","o":["Formation of ATP at substrate level","ATP generation of pumping of proton","ATP generation of pumping of neutron","ATP formation by transport of 0,"],"a":1,"e":"Ans. is ''b'' i.e., ATP generation of pumping of proton [Ref Harper 29''die p. 125-127] Chemoiosmotic theory It states that \"free energy of electron transport\" is conserved by pumping protons from mitochondrial matrix to the intermembrane space, so as to create an electrochemical proton gradient across the inner mitochondrial membrane, with outer side of membrane is positively charged as compared to inside. Electrochemical potential of this gradient is used to synthesize ATP by ATP synthase","pyqMatches":[{"year":"2012","no":350,"q":"Chemiosmotic coupling of oxidation phosphorylation is related to ?","o":["Formation of ATP at substrate level","ATP generation of pumping of proton","ATP generation of pumping of neutron","ATP formation by transport of 0,"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1488, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 607, '{"id":1488,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":607,"q":"Which one of the following statements concerning gluconeogenesis is correct ?","o":["It occurs in muscle","It is stimulated by fructose 2, 6-bisphosphate","It is inhibited by elevated levels of acetyl CoA","It is important in maintaining blood glucose during the normal overnight fast."],"a":3,"e":"Ans. is ''d'' i.e., It is important in maintaining blood glucose during the normal overnight fast [Ref Mark''s Basic medical biochemistry p. 566] During fasting, many of the reactions of glycolysis are reversed as the liver produces glucose to maintain blood glucose levels. This process of glucose production is called gluconeogenesis. During overnight fast, blood glucose levels are maintained by both gluconeogenesis and glycogenolysis. However, after approximately 30 hours of fasting, liver glycogen stores are mostly depleted. Subsequently, gluconeogenesis is the only source of blood glucose.","pyqMatches":[{"year":"2012","no":349,"q":"Which one of the following statements concerning gluconeogenesis is correct ?","o":["It occurs in muscle","It is stimulated by fructose 2, 6-bisphosphate","It is inhibited by elevated levels of acetyl CoA","It is important in maintaining blood glucose during the normal overnight fast."],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1489, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 608, '{"id":1489,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":608,"q":"Fatty acid metabolism gives ?","o":["Acetyl CoA","Malonyl CoA","Ketone bodies","Cholesterol"],"a":0,"e":"Ans. is ''a'' i.e., Acetyl CoA [Ref Harper 250/e p. 208-210] Acetyl-CoA has a special central role. Acetyl-CoA is the common degradation product of glucose (by glycolysisQ and PDH complex), fatty acids and ketogenic amino acids. Its acetyl group can be utilized in synthesis of fatty acidsQ, cholesterolQ and other steroidsQ, ketone bodiesQ; or can be oxidized via TCA (citric acid cycle). In fed state acetyl-CoA is oxidised via TCA cycle and used for synthesis of fatty acids and cholesterolQ, whereas in starvation it is used to synthesize ketone bodiesQ","pyqMatches":[{"year":"2012","no":348,"q":"Fatty acid metabolism gives ?","o":["Acetyl CoA","Malonyl CoA","Ketone bodies","Cholesterol"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1490, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Moderate', 'Biochemistry', 609, '{"id":1490,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":609,"q":"Tyrsoine is the precursor of all except ?","o":["Thyroxine","Melanin","Dopmine","Nicotinic acid"],"a":3,"e":"Ans. is ''d'' i.e., Nicotinic acid [Ref: Harper''s 28th /e p. 266, 268, 254] Tyrosine is a precursor of many important compounds such as catecholamines (epinephrineQ, norepinephrine Q),dopamine), thyroxineQ, triiodothryonine, melanin0.","pyqMatches":[{"year":"2012","no":323,"q":"Tyrsoine is the precursor of all except ?","o":["Thyroxine","Melanin","Dopmine","Nicotinic acid"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1491, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 610, '{"id":1491,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":610,"q":"Organ which can utilize glucose, FA and ketone bodies is -","o":["Liver","Brain","Skeletal muscle","RBC"],"a":2,"e":"Ans. is ''c'' i.e., Skeletal muscle [Ref Harper 28th/e p. 141] Skeletal muscles can utilize glucose, glycogen, fatty acids and ketone bodies. Liver cannot utilize ketone bodies. Brain and erythrocytes are exclusively dependent on glucose except in prolonged starvation where brain utilizes ketone bodies predominantly","pyqMatches":[{"year":"2012","no":346,"q":"Organ which can utilize glucose, FA and ketone bodies is","o":["Liver","Brain","Skeletal muscle","RBC"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1492, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Moderate', 'Biochemistry', 611, '{"id":1492,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":611,"q":"Which of the following enzyme is not used by liver in urea cycle ?","o":["CPS-I","CPS-II","Arginase","Arginosuccinate"],"a":1,"e":"Ans. is ''b'' i.e., CPS-II [Ref Harper 29th / e p. 277-278] Carbmoyl phosphate synthase II (CPS II) is involved in pyrimidine synthesis (not in urea cycle).","pyqMatches":[{"year":"2012","no":324,"q":"Which of the following enzyme is not used by liver in urea cycle ?","o":["CPS-I","CPS-II","Arginase","Arginosuccinate"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1493, 'Biochemistry', 'Lipid Metabolism', 'Easy', 'Biochemistry', 612, '{"id":1493,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":612,"q":"HMG-CoA in liver mitochondria is inhibited by ?","o":["Insulin","Glucagon","Glucocorticoid","Epinephrine"],"a":0,"e":"Ans. is ''a'' i.e., Insulin This question is a little tricky. Effect of insulin on ketogenesis Ketogenesis is usually associated with excessive fatty acid oxidation (lipolysis) which provides the substrate (acetyl-CoA) for ketogenesis. Thus, factors which inhibit lipolysis will inhibit ketogenesis (and also production of HMG-CoA). Insulin is an antilipolytic hormone. It inhibits lypolysis and therefore ketogenesis. Thus it decreases the synthesis of HMG​CoA in ketogenesis. So, insulin inhibits as well as stimulates production of HMG-CoA. Then why is insulin the answer of this question ? Here comes the tricky part of this question. Read the question carefully examiner has asked about HMG-CoA production in liver mitochondria. Ketogenesis occurs in mitochondria. Cholesterol synthesis occurs in cytosol and smooth ER. Thus insulin inhibits HMG-CoA production in mitochondria but stimulates it in cytosol.","pyqMatches":[{"year":"2012","no":345,"q":"HMG-CoA in liver mitochondria is inhibited by ?","o":["Insulin","Glucagon","Glucocorticoid","Epinephrine"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1494, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 613, '{"id":1494,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":613,"q":"Amino acid used by liver in urea cycle ?","o":["Glutamine","Glutamate","Aspartate","Fumarate"],"a":2,"e":"Ans. is ''c'' i.e., Aspartate [Ref Harper 29`\"/e p. 276-278] The source of two nitrogen atoms of urea -› one from ammonia° and one from amino group of aspartate°. Source of carbon is CO,Q. Thus out of all amino acids involved in urea cycle aspartate is consumed, while there is no net loss or gain of ornithine, citrulline, arginosuccinate or arginine. There is production of fumarate as by product°. 3 molecules of ATP are consumed (2 in first reaction and 1 in third reaction). However, 4 high energy phosphate bonds are utilized as 3rd ATP is converted to AMP+PPi.","pyqMatches":[{"year":"2012","no":325,"q":"Amino acid used by liver in urea cycle ?","o":["Glutamine","Glutamate","Aspartate","Fumarate"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1495, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 614, '{"id":1495,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":614,"q":"Hydrolysis occurs at which step of urea cycle ?","o":["Cleavage of arginine","Formation of Arginosuccinate","Formation of citrulline","Formation of ornithine"],"a":0,"e":"Ans.''A'', Cleavage of arginine Urea synthesis is a 5 step cyclic process, with 5 distinct enzymes. The first 2 enzymes are present in mitochondria while the rest are localized in the cytosol Step 1. Formation of Carbamoyl Phosphate- One molecule of ammonia condenses with CO2in the presence of two molecules of ATP to form carbamoyl phosphate. It is catalyzed by carbamoyl phosphate synthetase-I (CPS-I). Step 2. Formation of Citrulline- The carbamoyl group is transferred to the NH2 group of ornithine by ornithine transcarbamoylase. Step 3. Formation of Argininosuccinate- One molecule of aspartic acid adds to citrulline forming a carbon to nitrogen bond which provides the 2nd nitrogen atom of urea. Argininosuccinate synthetase catalyzes the reaction. Step 4. Formation of Arginine- Argininosuccinate is cleaved by argininosuccinate lyase (argininosuccinase) to arginine and fumarate. The enzyme is inhibited by fumarate. The fumarate formed may be funneled into the TCA cycle to be converted to malate and then to oxaloacetate to be transaminated to aspartate. Thus the urea cycle is linked to the TCA cycle through fumarate. Step 5. Formation of Urea- The final reaction of the cycle is the hydrolysis of arginine to urea and ornithine by arginase.","pyqMatches":[{"year":"2012","no":326,"q":"Hydrolysis occurs at which step of urea cycle ?","o":["Cleavage of arginine","Formation of Arginosuccinate","Formation of citrulline","Formation of ornithine"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1496, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 615, '{"id":1496,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":615,"q":"Why citric acid cycle called amphibolic pathway ?","o":["Both exergonic and endergonic reactions takes place","Metabolites are utilized in other pathways","It can proceed both in forward and backward direction","Same enzymes can be used in reverse directions"],"a":0,"e":"Ans. is ''a'' i.e., Both exergonic and endergonic reactions takes place [Ref : Harper 29th/e p. 151, 166] Citric acid cycle is called amphibolic pathway because it acts as a link between anabolic (endothermic) and catabolic (exothermic) pathways.","pyqMatches":[{"year":"2012","no":342,"q":"Why citric acid cycle called amphibolic pathway ?","o":["Both exergonic and endergonic reactions takes place","Metabolites are utilized in other pathways","It can proceed both in forward and backward direction","Same enzymes can be used in reverse directions"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1497, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 616, '{"id":1497,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":616,"q":"Urea & Kreb''s cycle are linked at ?","o":["Arginine","Ornithine","Oxaloacetate","Fumarate"],"a":3,"e":"Ans. is ''d'' i.e., Fumarate [Ref Harper 250/e p. 276-277] Fumarate is released during urea cycle, which is an intermediate of Kreb''s cycle, thus linking the two.","pyqMatches":[{"year":"2012","no":327,"q":"Urea & Kreb''s cycle are linked at ?","o":["Arginine","Ornithine","Oxaloacetate","Fumarate"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1498, 'Biochemistry', 'Carbohydrate Metabolism', 'Moderate', 'Biochemistry', 617, '{"id":1498,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":617,"q":"Which of the following metabolites is involved in glycogenolysis, glycolysis and gluconeogenesis ?","o":["Galactose-l-phosphate","Glucose-6-phosphate","Uridine diphosphoglucose","Fructose-6-phosphate"],"a":1,"e":"Ans. is ''b'' i.e., Glucose-6-phosphate [Ref Harper 28th le p. 166, 158] → Glucose-6-phosphate is the metabolite which :?","pyqMatches":[{"year":"2012","no":341,"q":"Which of the following metabolites is involved in glycogenolysis, glycolysis and gluconeogenesis ?","o":["Galactose-l-phosphate","Glucose-6-phosphate","Uridine diphosphoglucose","Fructose-6-phosphate"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1499, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 618, '{"id":1499,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":618,"q":"Which will activate carbomoyl phosphate synthase I?","o":["Alanine","N-acetyl glutamate","Ornithine","None"],"a":1,"e":"Ans. is ''b'' i.e., N-acetyl glutamate Carbamoyl phosphate synthase-I (CPS-I), a mitochondrial enzyme, catalyzes the formation of carbamoyl phosphate° by condensation of CO2 and ammonia. Two molecules of ATP are required for the reaction. CPS-I is the rate limiting enzyme of urea cycleQ. It is an allosteric enzyme and allosterically activated by N-acetyl glutamate","pyqMatches":[{"year":"2012","no":328,"q":"Which will activate carbomoyl phosphate synthase I?","o":["Alanine","N-acetyl glutamate","Ornithine","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1500, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 619, '{"id":1500,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":619,"q":"Enzyme deficient in Isovaleric acidemia","o":["Isovaleryl CoA dehydrogenase","Phenylalanine hydroxylase","Arginase","None"],"a":0,"e":"Ans. is ''a'' i.e.Isolvaleryl CoA dehydrogenase - Isovaleric acidemia is due to the defect in the metabolism of leucine. -The enzyme defective is isovaleryl Co-A dehydrogenase. -A characteristic odor of sweaty feet is present. -Vomiting, acidosis, and coma follow the ingestion of excess protein. Accumulated isovaleryl-CoA is hydrolyzed to isovalerate and excreted.","pyqMatches":[{"year":"2012","no":340,"q":"Enzyme deficient in Isovaleric acidemia","o":["Isovaleryl CoA dehydrogenase","Phenylalanine hydroxylase","Arginase","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1501, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 620, '{"id":1501,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":620,"q":"Transamination of Alanine results in formation of ?","o":["Oxaloacetate","Pyruvate","Aspartate","Arginine"],"a":1,"e":"Ans. is ''b'' i.e., Pyruvate","pyqMatches":[{"year":"2012","no":329,"q":"Transamination of Alanine results in formation of ?","o":["Oxaloacetate","Pyruvate","Aspartate","Arginine"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1502, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 621, '{"id":1502,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":621,"q":"True about alkaptonuria ?","o":["Deficiency of Tyrosinase","Urine is black","Banedict test is not useful","Fecl, test gives red colour"],"a":1,"e":"Ans. is ''b'' i.e., Urine is black [Ref Nelson 18thie p. 1812]","pyqMatches":[{"year":"2012","no":339,"q":"True about alkaptonuria ?","o":["Deficiency of Tyrosinase","Urine is black","Banedict test is not useful","Fecl, test gives red colour"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1503, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 622, '{"id":1503,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":622,"q":"Cofactors for glutamate dehydrogenase?","o":["NAD+","FAD","FMN","FADH2"],"a":0,"e":"Ans. ''A'' NAD+ Anaerobic Dehydrogenases are the enzymes that catalyze the removal of hydrogen from a substrate but oxygen cannot act as the hydrogen acceptor. They, therefore, require coenzymes as acceptors of the hydrogen atoms. When the substrate is oxidized, the coenzyme is reduced. NAD+ is derived from nicotinic acid, a member of the vitamin B complex. The NAD+ linked dehydrogenases are- Glyceraldehyde-3-phosphate dehydrogenase Isocitrate dehydrogenase Malate dehydrogenase Glutamate dehydrogenase Beta hydroxy acyl CoA dehydrogenase Pyruvate dehydrogenase Alpha-ketoglutarate dehydrogenase","pyqMatches":[{"year":"2012","no":330,"q":"Cofactors for glutamate dehydrogenase?","o":["NAD+","FAD","FMN","FADH2"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1504, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 623, '{"id":1504,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":623,"q":"Ochronosis is due to accumulation of ?","o":["Homogentisic acid","Phenylpyruvate","Xanthurenate","Glyoxylate"],"a":0,"e":"Ans. is ''a'' i.e., Homogentisic acid [Ref: Harper 29th/e p. 287-289] Alkaptonuria It is due to deficiency of homogentisate oxidase. As a result homogentisic acid (homogentisate) is excreted execessively in urine. There are three important characteristic features in alkaptonuria?","pyqMatches":[{"year":"2012","no":338,"q":"Ochronosis is due to accumulation of ?","o":["Homogentisic acid","Phenylpyruvate","Xanthurenate","Glyoxylate"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1505, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 624, '{"id":1505,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":624,"q":"Neonatal tyrosenemia is due to deficiency of ?","o":["Tyrosinase","Fumarylacetoacetate hyroxyase","Hydroxyphenyl pyruvate hydroxylase","Tyrosine transminase"],"a":2,"e":"Ans. is ''c'' i.e., Hydroxyphenyl pyruvate hydroxylase [Ref Harper''s 28th/e p. 266, 268] Tyrosinemia It is a defect in metabolism of tyrosine. It may be of following types.","pyqMatches":[{"year":"2012","no":332,"q":"Neonatal tyrosenemia is due to deficiency of ?","o":["Tyrosinase","Fumarylacetoacetate hyroxyase","Hydroxyphenyl pyruvate hydroxylase","Tyrosine transminase"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1506, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 625, '{"id":1506,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":625,"q":"Separation of proteins by their mass ?","o":["Electrophoresis","Salting out","SDS-PAGE","Ion exchange chromatography"],"a":2,"e":"Ans. is ''c'' i.e., SDS-PAGE [Ref Vasudevan 6\"die p. 600]","pyqMatches":[{"year":"2012","no":333,"q":"Separation of proteins by their mass ?","o":["Electrophoresis","Salting out","SDS-PAGE","Ion exchange chromatography"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1507, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 626, '{"id":1507,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":626,"q":"About Denaturation of protein,which is true ?","o":["Biological property persists","Primary structure lost","Always irreversible","Mostly renders protein insoluble"],"a":3,"e":"Ans. is ''d'' i.e., Mostly renders protein insoluble [Ref Lippincott''s 4thIe p. 57] The term denaturation refers to disruption of higher order (secondary, tertiary and quaternary) structure of protein. All non-covalent bonds that maintain higher order structure are disrupted, but peptide bond (covalent bond) remains intact. Thus, the primary structure is not altered during denaturation, i.e., amino acid sequence is not altered, but denaturation may completely disrupt secondary, tertiary and quaternary structure, e.g., denaturated oligomeric proteins dissociated into subunits, each with a randam coil formation. Denaturation is always accompanied by a loss of biological function, e.g., enzymes are inactivated and antibodies fail to act with antigens. Denaturation is generally irreversible, e.g., boiled egg does not regain its original form when kept in cold. Denatured proteins are less soluble and in many cases they precipitate.","pyqMatches":[{"year":"2012","no":337,"q":"About Denaturation of protein,which is true ?","o":["Biological property persists","Primary structure lost","Always irreversible","Mostly renders protein insoluble"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1508, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 627, '{"id":1508,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":627,"q":"Two same charged proteins can be separated by all except -","o":["Agarose","DEAE Cellulose","Sephadex","None of these"],"a":1,"e":"Ans. is ''b'' i.e., DEAE Cellulose [Ref Essentials of Biochemistry p. 670, 795] DEAE cellulose chromatography (anion exchange) separates molecules based on molecular charge. Therefore, it cannot separate two proteins with same charge. Agarose (sepharose) and dextran (sephadex) are used in gel filtration chromatography, which is based on molecular size. Thus, they can separate proteins of same charge.","pyqMatches":[{"year":"2012","no":334,"q":"Two same charged proteins can be separated by all except","o":["Agarose","DEAE Cellulose","Sephadex","None of these"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1509, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 629, '{"id":1509,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":629,"q":"250 nm light is absorbed by ?","o":["Arginine","Alanine","Tyrosine","Histidine"],"a":2,"e":"Ans. is ''c'' i.e.,Tyrosine Amino acids do not absorb visible light and thus are colourless. However, aromatic amino acidsQ (tryptophan, tyrosine, phenylalanine) absorb high-wavelength (250-290 nm) UV light. Trypytophan has the greatest absorption maxima in this region than other two aromatic amino acids. Thus, aromatic amino acids are responsible for UV absorption of most proteins0, maximum absorption being at 280 rim.","pyqMatches":[{"year":"2012","no":335,"q":"250 nm light is absorbed by ?","o":["Arginine","Alanine","Tyrosine","Histidine"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1510, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 630, '{"id":1510,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":630,"q":"Tyrosinosis is caused due to deficiency of which enzyme?","o":["Fumarylacetoacetate hydrolase.","p-hydroxy phenylpyruvate dehydrogenase.","Tyrosine transaminase.","Tyrosine ligase."],"a":0,"e":"Answer: A. Fumarylacetoacetate hydrolase Several metabolic disorders are associated with the tyrosine catabolic pathway. The probable metabolic defect in type I tyrosinemia (tyrosinosis) is at fumarylacetoacetate hydrolase. It is characterized by buildup of too much of the amino acid tyrosine in the blood and tissues due to an inability to metabolize it The therapy employs a diet low in tyrosine and phenylalanine. Untreated acute and chronic tyrosinosis leads to death from liver failure.","pyqMatches":[{"year":"2018","no":22,"q":"Tyrosinosis is caused due to deficiency of which enzyme?","o":["Fumarylacetoacetate hydrolase.","p-hydroxy phenylpyruvate dehydrogenase.","Tyrosine transaminase.","Tyrosine ligase."],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1511, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 631, '{"id":1511,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":631,"q":"Lesch–Nyhan syndrome is caused by deficiency of which enzyme?","o":["Orotate Phosphoribosyltransferase","Uracil phosphoribosyltransferase","Quinolinate Phosphoribosyltransferase","Hypoxanthine-guanine phosphoribosyltransferase (HGPRT)"],"a":3,"e":"Answer: D. Hypoxanthine-guanine phosphoribosyltransferase (HGPRT) The condition is called ksch-Nyhan slmdrome, in which there is complete deficiency of HGPRT. HGPRT deficiency causes decreased utilization of PRPP in salvage pathway. This results in increased production of purine nucleotide from PRPP via de-novo pathway. The disease is characterized by hyperuricemia, gouty arthritis, urinary stones, neurological symptoms.","pyqMatches":[{"year":"2018","no":23,"q":"Lesch–Nyhan syndrome is caused by deficiency of which enzyme?","o":["Orotate Phosphoribosyltransferase","Uracil phosphoribosyltransferase","Quinolinate Phosphoribosyltransferase","Hypoxanthine-guanine phosphoribosyltransferase (HGPRT)"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1512, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 632, '{"id":1512,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":632,"q":"Fish odor syndrome is caused by deficiency of which enzyme?","o":["Fumarylacetoacetate hydrolase","Methane monooxygenase","Monooxygenase 3 (FMO3)","D-amino acid oxidase"],"a":2,"e":"Answer: C. Monooxygenase 3 (FMO3) Trimethylaminuria, or fish odor syndrome (FOS), is a condition characterized by the presence of trimethylamine (TMA)—a tertiary amine whose odor is described as resembling that of rotting fish—in the urine, sweat, and expired air. The cause of the syndrome is rooted in the dysfunctional metabolism of TMA, which is normally oxidized by flavin monooxygenase 3 (FMO3) into non-odorous trimethylamine-N-oxide (TMAO). Most patients with FOS are eventually diagnosed with primary trimethylaminuria, which is caused by a deficiency in FMO3 that is inherited in an autosomal recessive fashion. The diagnosis is made on the basis of the clinical presentation and urinalysis. Urine can be analyzed for the concentration of both TMA and TMAO, and the results may be given as an oxidizing ratio based on the formula- TMAO/(TMAO+TMA) x 100%. Short courses of oral neomycin, metronidazole, and amoxicillin have been reported to be useful in some cases.","pyqMatches":[{"year":"2018","no":24,"q":"Fish odor syndrome is caused by deficiency of which enzyme?","o":["Fumarylacetoacetate hydrolase","Methane monooxygenase","Monooxygenase 3 (FMO3)","D-amino acid oxidase"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1513, 'Biochemistry', 'Genetics', 'Easy', 'Biochemistry', 633, '{"id":1513,"subject":"Biochemistry","chapter":"Genetics","difficulty":"Easy","source":"Biochemistry","sourceNo":633,"q":"Galactosemia is due to deficiency of which enzymes","o":["Galactose-1-phosphate uridyltransferase","HGPRT","Galactokinase","Epimerase"],"a":0,"e":"Answer: A. Galactose-1-phosphate uridyltransferase Galactosaemia (British galactosaemia) is a rare genetic metabolic disorder that affects an individual''s ability to metabolize the sugar galactose properly. Galactosemia follows an autosomal recessive mode of inheritance that confers a deficiency in an enzyme responsible for adequate galactose degradation.","pyqMatches":[{"year":"2017","no":31,"q":"Galactosemia is due to deficiency of which enzymes?","o":["Galactose-1-phosphate uridyltransferase","HGPRT","Galactokinase","Epimerase"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":25,"q":"Galactosemia is due to deficiency of which enzymes","o":["Galactose-1-phosphate uridyltransferase","HGPRT","Galactokinase","Epimerase"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1514, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 634, '{"id":1514,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":634,"q":"Which of the following is most abundant end product of fatty acid synthesis -","o":["Oleic acid","Palmitic acid","Arachidonic acid","Glucose"],"a":1,"e":"Answer: B. Palmitic acid Fatty acid are synthesized by extramitochondrial system. This system is present in many tissues including liver kidney brain lung mammary gland and adipose tissues. Acetyl CoA is immediate substrate. The end products of this synthesis are usually the saturated fatty acidspalmitate and stearate with the latter predominating.","pyqMatches":[{"year":"2017","no":32,"q":"Which of the following is most abundant end product of fatty acid synthesis","o":["Oleic acid","Palmitic acid","Arachidonic acid","Glucose"],"a":1,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":26,"q":"Which of the following is most abundant end product of fatty acid synthesis","o":["Oleic acid","Palmitic acid","Arachidonic acid","Glucose"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1515, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 635, '{"id":1515,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":635,"q":"About DNA polymerase I which one is correct?","o":["Not required in bacteria","Repair any damage with DNA","Involved in okazaki fragment","Participate in DNA replication"],"a":0,"e":"Answer: A. Not required in bacteria DNA polymerase I participates in the DNA replication of prokaryotes. Function of Pol I is mainly to repair any damage with DNA, but it also serves to connect okazaki fragments deleting RNA primers and replacing the strand with DNA.","pyqMatches":[{"year":"2017","no":33,"q":"About DNA polymerase I which one is correct?","o":["Not required in bacteria","Repair any damage with DNA","Involved in okazaki fragment","Participate in DNA replication"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":27,"q":"About DNA polymerase I which one is correct?","o":["Not required in bacteria","Repair any damage with DNA","Involved in okazaki fragment","Participate in DNA replication"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1516, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 636, '{"id":1516,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":636,"q":"What does chaperones assist in?","o":["Protein Cleavage","Protein Folding","Protein Degradation","Protein Modification"],"a":1,"e":"Answer: B. Protein Folding Folding of Proteins in Vivo Is Promoted by Chaperones","pyqMatches":[{"year":"2018","no":28,"q":"What does chaperones assist in?","o":["Protein Cleavage","Protein Folding","Protein Degradation","Protein Modification"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1517, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 637, '{"id":1517,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":637,"q":"Fishy odour occurs due to deficiency of this vitamin from diet -","o":["Biotin","Thiamine","Riboflavin","Vit. A"],"a":2,"e":"Answer: C. Riboflavin Vitamin B2 or riboflavin deficiency can bring about a fishy odor in the body. * Fish-odor syndrome, also called trimethylaminuria, is a rare metabolic disorder caused by the absence of enzyne n-oxidase ( A Flavin containing monooxygenase, 3(FMO3). Gene for trimethylamine o has been mapped on chromosome I(Iq23-q25). * Trimethylamine is normally produced in the intestine from the breakdown of dietary choline and trimethylamine oxide by bacteria. * Egg yolk and liver are the main sources of choline, and fish is the major source of trimethylamine oxide. * Trimethylamine is absorbed and oxidized in the liver by trimethylamine oxidase (flavin- containing monooxygenases) to trimethylamine oxide, which is odorless and excreted in the urine. Deficiency of the enzyme results in massive excretion of trimethylamine in urine. * Consequently, to these patients such foods may taste like rotten fish and import a fishy odor to their salvia, sweat and urine. Treatment * Restriction of fish, eggs, liver and other sources of choline (such as nuts and grains) in the diet significantly reduce the odor. - Treatment with short course of oral metronidamle, neomycin or lactulose causes temporary reduction in the body odor. * Riboflavin supplement can be given to enhance residual FMO3 activity.","pyqMatches":[{"year":"2018","no":29,"q":"Fishy odour occurs due to deficiency of this vitamin from diet","o":["Biotin","Thiamine","Riboflavin","Vit. A"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1518, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 638, '{"id":1518,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":638,"q":"VMA is excreted in urine in which condition -","o":["Alkaptonuria","Phenylketonuria","Pheochromocytoma","Diabetic ketoacidosis"],"a":2,"e":"Answer: C. Pheochromocytoma VMA is the end product of catabolism of catecholamines. In pheochromocytoma and neuroblastoma there is excessive synthesis of catecholamines which causes enhanced synthesis of VMA and its excretion in the urine. VMA is the urinary product of both epinephrine and norepinephrine. It is a good screening test for pheochromocytoma, and is also used to diagnose and follow up neuroblastoma and ganglioneuroma.","pyqMatches":[{"year":"2018","no":30,"q":"VMA is excreted in urine in which condition","o":["Alkaptonuria","Phenylketonuria","Pheochromocytoma","Diabetic ketoacidosis"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1519, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 639, '{"id":1519,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":639,"q":"In Cystinuria all of the following amino- acids reabsorption defect is present, except","o":["Lysine","Citrulline","Arginine","Ornithine"],"a":1,"e":"Ans. is ''B'' i.e., Citrulline Types of cystinuria * Type-I: It is homozygous with a fully recessive form. The patient excretes a large quantity of cystine, ornithine, lysine, and arginine. Gene involved is rBAT on chromosome-2. * Type-II & III: These are heterozygous variants of incompletely recessive forms. They excrete cystine, ornithine, lysine, and arginine more than normal but less than the homozygous state (Type-I). Gene involved is SLC7A9 on chromosome 79. Cystinuria * Biochemical Defect: An autosomal recessive disorder that results in the formation of a defective amino acid transporter in the renal tubule and intestinal epithelial cells. * Pathophysiology: The amino acid transporter is responsible for transporting cystine, ornithine, lysine, and arginine. Defective tubular reabsorption of these amino acids in the kidneys results in increased cystine in the urine, which can precipitate and cause kidney stones. * Clinical Manifestations: Cystine kidney stones presenting with severe, intermittent flank pain and hematuria. * Lab findings: Increased urinary excretion of cystine, ornithine, arginine, and lysine on urine amino acid chromatography; hematuria and cystine crystals (hexagonal) on the cooling of acidified urine sediment. * Imaging: Radiopaque kidney stones on CT scan. The most specific test is the cyanide–nitroprusside test * Treatment: Low-methionine diet; increased fluid intake; acetazolamide to alkalinize the urine. If this fails then patients are usually started on chelating therapy with penicillamine.","pyqMatches":[{"year":"2018","no":31,"q":"In Cystinuria all of the following amino- acids reabsorption defect is present, except","o":["Lysine","Citrulline","Arginine","Ornithine"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1520, 'Biochemistry', 'Biomolecules', 'Moderate', 'Biochemistry', 640, '{"id":1520,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Moderate","source":"Biochemistry","sourceNo":640,"q":"Fibrinopeptide A and fibrinopeptide B are acidic due to the presence of which amino acids in its structure -","o":["Serine and threonine","Glutamate and aspartate","Histidine and lysine","Glutamine and valine"],"a":1,"e":"Answer: B. Glutamate and aspartate The N-terminal A and B portions of the Aα and Bβ chains are termed fibrinopeptide A (FPA) and fibrinopeptide B (FPB), respectively. These domains are highly negatively charged as a result of an abundance of aspartate and glutamate residues. The negative charges contribute to the solubility of fibrinogen in plasma and importantly also serve to prevent aggregation by causing electrostatic repulsion between fibrinogen molecules.","pyqMatches":[{"year":"2018","no":32,"q":"Fibrinopeptide A and fibrinopeptide B are acidic due to the presence of which amino acids in its structure","o":["Serine and threonine","Glutamate and aspartate","Histidine and lysine","Glutamine and valine"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1521, 'Biochemistry', 'Miscellaneous', 'Easy', 'Biochemistry', 641, '{"id":1521,"subject":"Biochemistry","chapter":"Miscellaneous","difficulty":"Easy","source":"Biochemistry","sourceNo":641,"q":"HIAA in urine present in?","o":["Alkaptonuria","Albinism","Carcinoid","Phenylketonuria"],"a":2,"e":"Answer: C. Carcinoid Carcinoid syndrome develops in some people with carcinoid tumors and is characterized by cutaneous flushing, abdominal cramps, and diarrhea. Carcinoid tumour occur throughout the gastrointestinal tract, most commonly in the appendix, ileum and rectum in decreasing order of frequency. Right-sided valvular heart disease may develop after several years. The syndrome results from vasoactive substances (including serotonin, bradykinin, histamine, prostaglandins, polypeptide hormones) secreted by the tumor, which is typically a metastatic intestinal carcinoid. Diagnosis is clinical and by demonstrating increased urinary 5- hydroxyindoleacetic acid(HIAA). Tumor localization may require a radionuclide scan or laparotomy. Treatment of symptoms is with somatostatin or octreotide, but surgical removal is performed where possible; chemotherapy may be used for malignant tumors.","pyqMatches":[{"year":"2017","no":39,"q":"HIAA in urine present in?","o":["Alkaptonuria","Albinism","Carcinoid","Phenylketonuria"],"a":2,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":33,"q":"HIAA in urine present in?","o":["Alkaptonuria","Albinism","Carcinoid","Phenylketonuria"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1522, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 642, '{"id":1522,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":642,"q":"Nitric oxide acts by increasing ?","o":["BRCA 1","BRCA 2","Interleukin","cGMP"],"a":3,"e":"Answer: D> cGMP Nitric oxide diffuses to the surrounding smooth muscle cells, increasing cGMP . Cyclic guanosine monophosphate (cGMP) Cyclic nucleotide derived from guanosine triphosphate (GTP). Function: cGMP acts as a second messenger much like cyclic AMP. Mechanism of action: Activation of intracellular protein kinases in response to the binding of membrane-impermeable peptide hormones.","pyqMatches":[{"year":"2017","no":288,"q":"Nitric oxide acts by increasing ?","o":["BRCA 1","BRCA 2","Interleukin","cGMP"],"a":3,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":247,"q":"Nitric oxide acts by increasing ?","o":["BRCA 1","BRCA 2","Interleukin","cGMP"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1523, 'Biochemistry', 'Genetics', 'Easy', 'Biochemistry', 643, '{"id":1523,"subject":"Biochemistry","chapter":"Genetics","difficulty":"Easy","source":"Biochemistry","sourceNo":643,"q":"Phenylketonuria is due to deficiency of:","o":["Phenylalanine","Phenylalanine hydroxylase ( PAH)","Phenylene","All of these"],"a":1,"e":"Answer B. Phenylalanine hydroxylase ( PAH) A birth defect that causes an amino acid called phenylalanine to build up in the body. PKU is an autosomal recessive metabolic genetic disorder. PKU is characterized by homozygous or compound heterozygousmutations in the gene for the hepatic enzyme phenylalanine hydroxylase (PAH), rendering it nonfunctional. This enzyme is necessary to metabolize the amino acid phenylalanine (Phe) to the amino acid tyrosine (Tyr). When PAH activity is reduced, phenylalanine accumulates and is converted into phenylpyruvate (also known as phenylketone), which can be detected in the urine. The PAH gene is located on chromosome 12 in the bands 12q22- q24.1. More than 400 disease-causing mutations have been found in the PAH gene.","pyqMatches":[{"year":"2018","no":243,"q":"Phenylketonuria is due to deficiency of:","o":["Phenylalanine","Phenylalanine hydroxylase ( PAH)","Phenylene","All of these"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1524, 'Biochemistry', 'Molecular Biology', 'Easy', 'Biochemistry', 644, '{"id":1524,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Easy","source":"Biochemistry","sourceNo":644,"q":"By which method foreign DNA is introduced into a cell by a virus or viral vector?","o":["Transduction","Transcription","Lysogenic conversion","Transformation"],"a":0,"e":"Ans. A. Transduction Transduction is the process by which foreign DNA is introduced into a cell by a virus or viral vector. An example is the viral transfer of DNA from one bacterium to another.","pyqMatches":[{"year":"2018","no":264,"q":"By which method foreign DNA is introduced into a cell by a virus or viral vector?","o":["Transduction","Transcription","Lysogenic conversion","Transformation"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1525, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 645, '{"id":1525,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":645,"q":"Which one of the following shows allosteric inhibition?","o":["Malonic acid & succinate","2,3 BPG","Amino acid alanine & pyruvate kinase","Citrate"],"a":1,"e":"Answer: B. 2,3 BPG Negative allosteric modulation (also known as allosteric inhibition) occurs when the binding of one ligand decreases the affinity for substrate at other active sites. For example, when 2,3- BPG binds to an allosteric site on hemoglobin, the affinity for oxygen of all subunits decreases.","pyqMatches":[{"year":"2018","no":265,"q":"Which one of the following shows allosteric inhibition?","o":["Malonic acid & succinate","2,3 BPG","Amino acid alanine & pyruvate kinase","Citrate"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1526, 'Biochemistry', 'Biomolecules', 'Hard', 'Biochemistry', 646, '{"id":1526,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Hard","source":"Biochemistry","sourceNo":646,"q":"A 4-year-old boy of a first-degree consanguineous couple was noted by the parents to have darkening of the urine to an almost black color when it was left standing. He has a normal sibling, and there are no other medical problems. Growth and development to date are normal. Which of the following is most likely to be elevated in this patient?","o":["Methylmalonate","Homogentisate","Phenylpyruvate","α-Ketoisovalerate"],"a":1,"e":"Ans: B. Homogentisate. * Alkaptonuria is a rare metabolic disease involving a deficiency in homogentisic acid oxidase, and the subsequent accumulation of homogentisic acid in the urine, which turns dark upon standing. * The elevation of → methylmalonate (due to methylmalonyl CoA mutase deficiency), → Phenylpyruvate (due to phenylalanine hydroxylase deficiency), → α-ketoisovalerate (due to branched-chain α-keto acid dehydrogenase deficiency), → Homocysteine (due to cystathionine β-synthase deficiency) * All of these are inconsistent with a healthy child with a darkening of the urine. * Ref lippincott’s Illustrated reviews,5th edition, Amino Acid Degradation and Synthesis,Pg 276.","pyqMatches":[{"year":"2020","no":23,"q":"A 4-year-old boy of a first-degree consanguineous couple was noted by the parents to have darkening of the urine to an almost black color when it was left standing. He has a normal sibling, and there are no other medical problems. Growth and development to date are normal. Which of the following is most likely to be elevated in this patient?","o":["Methylmalonate","Homogentisate","Phenylpyruvate","α-Ketoisovalerate"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1527, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 647, '{"id":1527,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":647,"q":"Which of the following is true about different structures of protein?","o":["Secondary structure is the three-dimensional structure of protein","Secondary structure is stabilized by disulfide bonds","Primary, secondary and tertiary structures destroyed during denaturation","Secondary and tertiary structure depends on the sequence of amino acids"],"a":3,"e":"Ans: D. Secondary and tertiary structure depends on the sequence of amino acids Explanation Proteins are arranged in any of the following four structures viz: * Primary The sequence of amino acids in a protein is called the primary structure of the protein.chain * Secondary - The polypeptide backbone does not assume a random three- dimensional structure, but instead generally forms regular arrangements of amino acids that are located near to each other in the linear sequence. The α-helix, β-sheet, and β-bend (β-turn) are examples of secondary structures frequently encountered in proteins. * Tertiary - It refers to the three-dimensional arrangement of a polypeptide chain that has assumed its secondary structure. Disulfide bonds between cysteine residues may stabilize the tertiary structure. Protein denaturation results in the unfolding and disorganization of the protein’s secondary and tertiary structures, which are not accompanied by hydrolysis of peptide bonds * Quaternary - The quaternary structure requires more than one polypeptide chain. These chains associate through noncovalent interactions. Ref lippincott’s Illustrated reviews,5th edition, Structure of Protein,Pg 13","pyqMatches":[{"year":"2020","no":24,"q":"Which of the following is true about different structures of protein?","o":["Secondary structure is the three-dimensional structure of protein","Secondary structure is stabilized by disulfide bonds","Primary, secondary and tertiary structures destroyed during denaturation","Secondary and tertiary structure depends on the sequence of amino acids"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1528, 'Biochemistry', 'Carbohydrate Metabolism', 'Easy', 'Biochemistry', 648, '{"id":1528,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":648,"q":"The insulin glucagon ratio decreased. The enzyme is active at this time?","o":["Glucokinase","Hexokinase","Phosphofructokinase","Glucose 6 phosphatase"],"a":3,"e":"Ans. D.Glucose 6 phosphatase Explanation Low insulin:glucagon ratio (IGR) stimulates mobilization of stored nutrients, increases glycogenolysis and gluconeogenesis, and promotes the breakdown of adipose tissue into free fatty acids and glycerol. Decreases Insulin/glucagon ratio shows the fasting stage. Glucokinase, Hexokinase, and phosphofructokinase are glycolytic. Only gluconeogenic is glucose 6 phosphatase. Ref- https://www.ncbi.nlm.nih.gov/pmc/articles/PMC4801814","pyqMatches":[{"year":"2020","no":25,"q":"The insulin glucagon ratio decreased. The enzyme is active at this time?","o":["Glucokinase","Hexokinase","Phosphofructokinase","Glucose 6 phosphatase"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1529, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 649, '{"id":1529,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":649,"q":"Ochronosis is due to the accumulation of?","o":["Homogentisic acid","Homogentisic acid","Xanthurenate","Glyoxylate"],"a":0,"e":"Ans: A. Homogentisic acid Alkaptonuria is an autosomal recessive condition due to the deficiency of homogentisate 1,2 dioxidase. This results in the excretion of homogentisic acid in urine.is compatible with a fairly normal life. The only abnormality is the blackening of urine on standing. Homogentisic acid is oxidized by polyphenol oxidase to benzoquinone acetate. It is then polymerized to black colored alkapton bodies. By the 3rd or 4th decade of life, the patient may develop ochronosis (deposition of alkapton bodies in intervertebral discs, cartilages of nose, pinna of the ear). Black pigments are deposited over the connective tissues including joint cavities to produce arthritis. No specific treatment is required. But minimal protein intake with phenylalanine less than 500 mg/day is recommended. Ref- DM Vasudevan- Textbook of biochemistry for medical students, 6th edn, Aromatic Amino Acids, and Amino Acidurias, pg 208.","pyqMatches":[{"year":"2020","no":26,"q":"Ochronosis is due to the accumulation of?","o":["Homogentisic acid","Homogentisic acid","Xanthurenate","Glyoxylate"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1530, 'Biochemistry', 'Clinical Biochemistry', 'Easy', 'Biochemistry', 650, '{"id":1530,"subject":"Biochemistry","chapter":"Clinical Biochemistry","difficulty":"Easy","source":"Biochemistry","sourceNo":650,"q":"Bilirubin in serum can be measured by","o":["Van den Bergh reaction","Ehrlich’s Reaction","Schlesinger’s Reaction","Fouchet''s Reaction"],"a":0,"e":"Ans: A. Van den Bergh reaction Bilirubin is most commonly determined by the van den Bergh reaction, in which diazotized sulfanilic acid reacts with bilirubin to form red azodi pyrroles These are measured colorimetrically. In aqueous solution, the water- soluble, conjugated bilirubin reacts rapidly with the reagent (within one minute), and is said to be “direct-reacting.” The unconjugated bilirubin, which is much less soluble in aqueous solution, reacts more slowly. However, when the reaction is carried out in methanol, both conjugated and unconjugated bilirubin are soluble and react with the reagent, providing the total bilirubin value. The “indirect-reacting” bilirubin, which corresponds to the unconjugated bilirubin, is obtained by subtracting the direct-reacting bilirubin from the total bilirubin Note: In normal plasma, only about 4% of the total bilirubin is conjugated or direct-reacting, because most are secreted into bile. Ref- Lippincott’s Illustrated reviews,5th edition, Conversion of amino acids in specialized products,Pg 285.","pyqMatches":[{"year":"2020","no":27,"q":"Bilirubin in serum can be measured by","o":["Van den Bergh reaction","Ehrlich’s Reaction","Schlesinger’s Reaction","Fouchet''s Reaction"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1531, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 651, '{"id":1531,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":651,"q":"If a sample of DNA if adenine is 28% what will be the amount of Cytosine present","o":["23%","25%","46%","22%"],"a":3,"e":"Ans: D. 22% The bases of one strand of DNA are paired with the bases of the second strand so that adenine is always paired with thymine and cytosine is always paired with guanine. Therefore, one polynucleotide chain of the DNA double helix is always the complement of the other. Given the sequence of bases on one chain, the sequence of bases on the complementary chain can be determined. Note: The specific base pairing in DNA leads to the Chargaff Rule: In any sample of dsDNA, the amount of adenine equals the amount of thymine, the amount of guanine equals the amount of cytosine, and the total amount of purines equals the total amount of pyrimidines. The base pairs are held together by hydrogen bonds: two between A and T and three between G and C (Figure 29.5). These hydrogen bonds, plus the hydrophobic interactions between the stacked bases, stabilize the structure of the double helix. Ref- lippincott’s Illustrated reviews,5th edition, the structure of DNA, pg 397","pyqMatches":[{"year":"2020","no":28,"q":"If a sample of DNA if adenine is 28% what will be the amount of Cytosine present","o":["23%","25%","46%","22%"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1532, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 652, '{"id":1532,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":652,"q":"Which of the following vitamin at higher doses causes cystoid macular edema-","o":["Vit A","Vit D","Vit E","Niacin"],"a":3,"e":"Ans: D. Niacin Cystoid macular edema (CME) is a condition that involves the macula, causing painless vision loss. Niacin (nicotinic acid, vitamin B3, vitamin PP), one component of the dietary supplement taken by the patient, is a vitamin preparation usually used for the treatment of lipid disorders Fraunfelder et al. reported that 3 g or more per day of nicotinic acid could cause many ocular side effects such as blurred vision, eyelid edema, toxic amblyopia, proptosis, loss of eyelashes or eyebrow, superficial punctate keratitis, and cystoid macular edema, which represents the most serious ocular complications. All these adverse effects are reversible with discontinuation of niacin therapy Ref- Case Reports in Ophthalmological Medicine, Volume 2013, Article ID 713061, 5 page","pyqMatches":[{"year":"2020","no":29,"q":"Which of the following vitamin at higher doses causes cystoid macular edema","o":["Vit A","Vit D","Vit E","Niacin"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1533, 'Biochemistry', 'Genetics', 'Easy', 'Biochemistry', 653, '{"id":1533,"subject":"Biochemistry","chapter":"Genetics","difficulty":"Easy","source":"Biochemistry","sourceNo":653,"q":"True statement regarding Huntington’s chorea is","o":["There is a loss of function type of mutation","It is an autosomal recessive","It is a trinucleotide repeat expansion type of disorder","Increased number of CAA repeats"],"a":2,"e":"Ans: C. It is a trinucleotide repeat expansion type of disorder Huntington’s chorea is an autosomal dominant disorder with an increased number of CAG repeats. Clinically manifested as involuntary jerky movements, mood disturbances and finally severe dementia. Ref- Lange biochemistry and genetics flash cards, Huntington’s disease, pg 161","pyqMatches":[{"year":"2020","no":30,"q":"True statement regarding Huntington’s chorea is","o":["There is a loss of function type of mutation","It is an autosomal recessive","It is a trinucleotide repeat expansion type of disorder","Increased number of CAA repeats"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1534, 'Biochemistry', 'Amino Acid & Nitrogen Metabolism', 'Easy', 'Biochemistry', 654, '{"id":1534,"subject":"Biochemistry","chapter":"Amino Acid & Nitrogen Metabolism","difficulty":"Easy","source":"Biochemistry","sourceNo":654,"q":"Addition of which Amino Acid will increase UV absorption","o":["Tryptophan","Leucine","Proline","Arginine"],"a":0,"e":"Ans: A. Tryptophan Amino Acid Absorb UV Light Amino Acids that absorb 250-290 nm (Maximum at 280 nm) UV light are tryptophan, phenylalanine, tyrosine. The maximum absorption of UV light is by tryptophan. As it absorbs ultraviolet light about ten times more efficiently than phenylalanine or tyrosine, tryptophan makes the major contribution to the ability of most proteins to absorb light in the region of 280 nm. Tryptophan and tyrosine absorb UV at approximately 280 nrn. UV absorption spectroscopy is utilized to measure protein concentration. The absorption spectrum of a protein in the UV wavelength range is the result of absorption of light by the aromatic amino acids (250-320 nm), the disulfide bonds (250-300 nm) and the carbonyl group of the peptide bond (190-210). Remember Aromatic Amino Acids absorb UV Lights Amino acids are colourless because they do not absorb visible light. Ref-Rebecca james-self assessment and review of biochemistry, 3rd edn, Chemistry, and Metabolism of Amino Acids, Pg 7","pyqMatches":[{"year":"2020","no":31,"q":"Addition of which Amino Acid will increase UV absorption","o":["Tryptophan","Leucine","Proline","Arginine"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1535, 'Biochemistry', 'Vitamins & Minerals', 'Easy', 'Biochemistry', 655, '{"id":1535,"subject":"Biochemistry","chapter":"Vitamins & Minerals","difficulty":"Easy","source":"Biochemistry","sourceNo":655,"q":"V- Richest source of vitamin B12 ?","o":["Meat","Green leafy vegetables","Corn oil","Sunflower oil"],"a":0,"e":"Ans: A. Meat * Vitamin B12 is naturally found in animal products, including fish, meat, poultry, eggs, milk, and milk products. * Synonyms are cobalamin, extrinsic factor (EF) of Castle and anti pernicious anemia factor. Vitamin B12 is water-soluble, heat stable and red in color. It is satisfied by any of the following groups: cyanide, hydroxyl, adenosyl or methyl. * Cyanocobalamin- Oral preparations are in this form. * Hydroxy cobalamin- Injectable preparations are in this form. * Adenosylcobalamin- This is the major storage form, seen in the liver. * Methylcobalamin-This is the major form seen in blood circulation as well as in the cytoplasm of cells. * Vitamin B12 is generally not present in plant foods, but fortified breakfast cereals are a readily available source of vitamin B12 with high bioavailability for vegetarians. * Rich source of vitamin B12→ - Beef, liver, and chicken. - Fish and shellfish such as trout, salmon, tuna fish, and clams. - Fortified breakfast cereal. - Low-fat milk, yogurt, and cheese. - Eggs. Ref- DM Vasudevan- Textbook of biochemistry for medical students, 6th edn,Nutrition, pg 404.","pyqMatches":[{"year":"2020","no":32,"q":"V- Richest source of vitamin B12 ?","o":["Meat","Green leafy vegetables","Corn oil","Sunflower oil"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1536, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 656, '{"id":1536,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":656,"q":"Which amino acid is used to synthesize Nitric oxide?","o":["Glycine","Arginine","Tyrosine","Threonine"],"a":1,"e":"Ans: B. Arginine Nitric oxide is formed from arginine by the enzyme nitric oxide synthase (NOS). It contains heme, FAD, FMN, NADPH, and tetrahydrobiopterin. Nitric oxide has a very short half-life (3-4 seconds). NO combines with oxygen to form NO2. These nitrites are excreted through urine. Reacting with hemoglobin, NO is converted to NO3; and nitrates are also excreted in the urine. The very low quantity of NO is expelled through the lung. Arginine is a highly basic, semi-essential amino acid. It is glucogenic in nature.","pyqMatches":[{"year":"2020","no":33,"q":"Which amino acid is used to synthesize Nitric oxide?","o":["Glycine","Arginine","Tyrosine","Threonine"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1537, 'Biochemistry', 'Enzymes', 'Easy', 'Biochemistry', 657, '{"id":1537,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Easy","source":"Biochemistry","sourceNo":657,"q":"True About Noncompetitive antagonist -","o":["Km remains same, Vmax decreases","Km remains same, Vmax decreases","Km decreases, Vmax increases","Km increases, Vmax increases"],"a":0,"e":"Ans: A. Km remains same, Vmax decreases Noncompetitive inhibition occurs when the inhibitor and substrate bind at different sites on the enzyme. The noncompetitive inhibitor can bind either the free enzyme or the ES complex, thereby preventing the reaction from occurring. Effect on Vmax: Noncompetitive inhibition cannot be overcome by increasing the concentration of the substrate. Thus, noncompetitive inhibitors decrease the apparent Vmax of the reaction. Effect on Km: Noncompetitive inhibitors do not interfere with the binding of substrate to enzyme. Thus, the enzyme shows the same Km in the presence or absence of the non-competitive inhibitor. Effect on Lineweaver-Burk plot: Noncompetitive inhibition is readily differentiated from competitive inhibition by plotting 1/vo versus 1/[S] and noting that the apparent Vmax decreases in the presence of a non-competitive inhibitor, whereas Km is unchanged Ref- lippincott’s Illustrated reviews,5th edition,Inhibition of Enzyme Activity, pg 61.","pyqMatches":[{"year":"2020","no":34,"q":"True About Noncompetitive antagonist","o":["Km remains same, Vmax decreases","Km remains same, Vmax decreases","Km decreases, Vmax increases","Km increases, Vmax increases"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1538, 'Biochemistry', 'Molecular Biology', 'Moderate', 'Biochemistry', 658, '{"id":1538,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Moderate","source":"Biochemistry","sourceNo":658,"q":"Werner syndrome associated with premature aging is caused due to a defect in which of the following?","o":["Telomerase","Caspase","DNA topoisomerase","DNA helicase"],"a":3,"e":"Ans: D. DNA helicase Werner syndrome is a human autosomal recessive disorder that displays symptoms of premature aging, including early graying and thinning of hair, wrinkling and ulceration of skin, atherosclerosis, osteoporosis, and cataracts. In addition, Werner syndrome patients exhibit an increased incidence of diabetes mellitus type 2, hypertension, and are highly disposed to the emergence of benign and malignant neoplasms. Werner syndrome caused by mutation of the WRN gene, a member of the RecQ DNA helicase family. Ref- https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3237395/","pyqMatches":[{"year":"2020","no":35,"q":"Werner syndrome associated with premature aging is caused due to a defect in which of the following?","o":["Telomerase","Caspase","DNA topoisomerase","DNA helicase"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1539, 'Biochemistry', 'Biomolecules', 'Easy', 'Biochemistry', 659, '{"id":1539,"subject":"Biochemistry","chapter":"Biomolecules","difficulty":"Easy","source":"Biochemistry","sourceNo":659,"q":"Which of the following dietary fiber is insoluble in water?","o":["Pectin","Lignin","Hemicellulose","Cellulose"],"a":1,"e":"Ans: B. Lignin The unavailable or indigestible carbohydrates in the diet are called dietary fiber. Dietary fiber is necessary to maintain the normal motility of the gastrointestinal tract. They are chiefly- Cellulose- Retains water in feces, promotes peristalsis, increases bowel action Lignin- Antioxidant, increases bile acid excretion, hypocholesterolemic. Pectins- Partially Absorb water, slows esterified gastric emptying, binds bile acids, increases their excretion Hemi-cellulose- Retains water in feces, cellulose, increases bile acid and uronic acid excretion. Ref- DM Vasudevan- Textbook of biochemistry for medical students, 6th edn , Energy Metabolism and Nutrition. Pg 435.","pyqMatches":[{"year":"2020","no":36,"q":"Which of the following dietary fiber is insoluble in water?","o":["Pectin","Lignin","Hemicellulose","Cellulose"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1540, 'Biochemistry', 'Lipid Metabolism', 'Moderate', 'Biochemistry', 660, '{"id":1540,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Moderate","source":"Biochemistry","sourceNo":660,"q":"According to NCEP-ATP III, which among the following have not been included in metabolic syndrome?","o":["High LDL","Hypertriglyceridemia","Central Obesity","Hypertension"],"a":0,"e":"Answer- A. High LDL Metabolic syndrome refers to the co-occurrence of several known cardiovascular risk factors, including insulin resistance, obesity, atherogenic dyslipidemia, and hypertension. These conditions are interrelated and share underlying mediators, mechanisms, and pathways. Criteria for the Diagnosis of Metabolic Syndrome Elevated waist circumference: (For men >90 cm and for women, >80 cm). Elevated triglycerides: >150 mg/dL Reduced HDL (“good”) cholesterol: For men, <40 mg/dL; for women, < 50 mg/dL Elevated blood pressure: >130/85 mm Hg Elevated fasting glucose: >100 mg/dL Insulin resistance (hyperinsulinemia) Additional parameters include: coagulation abnormalities, hyperuricemia, microalbuminuria non-alcoholic steatohepatitis (NASH) and increased CRP. Diagnosis is made, if any 3 out of the 5 criteria given above. Ref- DM Vasudevan- Textbook of biochemistry for medical students, 6th edn, Clinical, and Applied Biochemistry, pg 286","pyqMatches":[{"year":"2020","no":37,"q":"According to NCEP-ATP III, which among the following have not been included in metabolic syndrome?","o":["High LDL","Hypertriglyceridemia","Central Obesity","Hypertension"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1541, 'Biochemistry', 'Molecular Biology', 'Moderate', 'Biochemistry', 661, '{"id":1541,"subject":"Biochemistry","chapter":"Molecular Biology","difficulty":"Moderate","source":"Biochemistry","sourceNo":661,"q":"Which of the following is the basis for the intestine-specific expression of apoprotein B-48?","o":["DNA rearrangement and loss","DNA rearrangement and loss","RNA alternative splicing","RNA editing"],"a":3,"e":"Ans: D. RNA editing. The production of apoB-48 in the intestine and apoB-100 in liver is the result of RNA editing in the intestine, where a sense codon is changed to a nonsense codon by post-transcriptional deamination of C to U.DNA rearrangement and transposition, as well as RNA interference and alternate splicing, do alter gene expression, but are not the basis of apoB-48 tissue-specific production. Reference- Lippincott’s Illustrated Reviews: Biochemistry, 5th edition, Regulation of Gene Expression, Pg 464.","pyqMatches":[{"year":"2020","no":38,"q":"Which of the following is the basis for the intestine-specific expression of apoprotein B-48?","o":["DNA rearrangement and loss","DNA rearrangement and loss","RNA alternative splicing","RNA editing"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1542, 'Dermatology', 'Acne & Disorders of Pilosebaceous Unit', 'Easy', 'Skin', 1, '{"id":1542,"subject":"Dermatology","chapter":"Acne & Disorders of Pilosebaceous Unit","difficulty":"Easy","source":"Skin","sourceNo":1,"q":"Fox Fordyce Disease effects:","o":["Sebaceous glands","Eccrine Glands","Apocrine glands","Any gland"],"a":2,"e":"Apocrine glands","pyqMatches":[{"year":"2014","no":1938,"q":"Fox Fordyce Disease effects:","o":["Sebaceous glands","Eccrine Glands","Apocrine glands","Any gland"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1543, 'Dermatology', 'Eczemas & Dermatitis', 'Easy', 'Skin', 2, '{"id":1543,"subject":"Dermatology","chapter":"Eczemas & Dermatitis","difficulty":"Easy","source":"Skin","sourceNo":2,"q":"A melanocytic naevus surrounded by a depigmented halo is called:","o":["Sutton''s nevus","Meyerson’s naevus","Cockade naevus","Nevus anaemicus"],"a":0,"e":"Sutton''s nevus/halo''s nevus : a halo of depigmentation appears around a preexisting melanocytic naevus. Meyerson’s naevus is used to describe a melanocytic naevus that has developed an associated inflammatory reaction, which looks like eczema. Ref: Rook''s textbook of dermatology, 8th edition Pg 54.20.","pyqMatches":[{"year":"2014","no":572,"q":"A melanocytic naevus surrounded by a depigmented halo is called:","o":["Sutton''s nevus","Meyerson’s naevus","Cockade naevus","Nevus anaemicus"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1544, 'Dermatology', 'Skin Tumors', 'Easy', 'Skin', 3, '{"id":1544,"subject":"Dermatology","chapter":"Skin Tumors","difficulty":"Easy","source":"Skin","sourceNo":3,"q":"Which of the following is the most common form of malignant melanoma?","o":["Nodular","Superficial spreading","Acral lentiginous","Mucosal"],"a":1,"e":"The commonest type of melanoma is the superficial spreading melanoma (SSM). The melanoma progress through 3 phases: in situ, radial growth, vertical growth. NB: A primary melanoma with no recognizable adjacent in situ or radial growth phase is nodular melanoma. Melanoma with similar prevalence in all ethnic groups- acral lentiginous Ref: Rook''s textbook of dermatology, Edition-8, Page-54.45.","pyqMatches":[{"year":"2014","no":1138,"q":"Which of the following is the most common form of malignant melanoma?","o":["Nodular","Superficial spreading","Acral lentiginous","Mucosal"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1545, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 4, '{"id":1545,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":4,"q":"Lines of Blaschko represent:","o":["Lines along lymphatics","Lines along blood vessels","Lines along nerves","Lines of development"],"a":3,"e":"The lines of Blaschko are defined by a pattern determined by nevoid representing non random lines on the human skin or mucosa. Blaschko lines or the lines of Blaschko are thought to represent pathways of epidermal cell migration and proliferation during the development of the fetus. Lines of Blaschko represent non-random developmental lines of the skin fundamentally differing from the system of dermatomes. They follow a''V'' shape over the back, ''S'' shaped whorls over the chest, stomach, and sides, and wary shapes on the head. The lines are belived to trace the migration of embryonic epidermal cells. The stripes are a type of genetic mosaicism. These lines characteristically do not follow the underlying nervous, Vascular, muscular or lymplatic structures in the skin. Lines of Blaschko are not ordinarily visibk, but are recognized in several cutaneous disorders that follow these arallel streaks. Ref: Syndromes: Rapid recognition and perioperative implications, by Bruno Bisonnette, Page 400; Neurocutaneous disorders: Phakomatosis and Hamartoneoplastic Syndromes, by Martino Ruggieri, Page 364.","pyqMatches":[{"year":"2015","no":1604,"q":"Lines of Blaschko represent:","o":["Lines along lymphatics","Lines along blood vessels","Lines along nerves","Lines of development"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1546, 'Dermatology', 'Eczemas & Dermatitis', 'Moderate', 'Skin', 5, '{"id":1546,"subject":"Dermatology","chapter":"Eczemas & Dermatitis","difficulty":"Moderate","source":"Skin","sourceNo":5,"q":"All are features of atopic dermatitis, except:","o":["Dennie -Morgan fold","Hertoghe’s sign","Darier’s Sign","Hyperlinearity of palms"],"a":2,"e":"It is seen in urticaria pigmentosa.","pyqMatches":[{"year":"2012","no":1372,"q":"All are features of atopic dermatitis, except:","o":["Dennie -Morgan fold","Hertoghe’s sign","Darier’s Sign","Hyperlinearity of palms"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1547, 'Dermatology', 'Dermatology Basics', 'Moderate', 'Skin', 6, '{"id":1547,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Moderate","source":"Skin","sourceNo":6,"q":"All of the following are true about incontinentia pigmenti, except:","o":["Ocular involvement is seen in almost 100% cases and is typically unilateral","Avascularity of peripheral retina","Primary skin abnormality","X-linked dominant"],"a":0,"e":"Ocular involvement is seen in about 20-35 percent of the cases of incontinentia pigmenti but not in 100 percent cases as mentioned in the option. Incontinentia pigmenti is a X-linked dominant primary skin disease that leads to avascularity of the retina. Ref: Rook''s Textbook of Dermatology 7th Edition, Pages 39.20-3.22; The Retinal Atlas By Lawrence A. Yannuzzi, Page 38","pyqMatches":[{"year":"2016","no":1188,"q":"All of the following are true about incontinentia pigmenti, except:","o":["Ocular involvement is seen in almost 100% cases and is typically unilateral","Avascularity of peripheral retina","Primary skin abnormality","X-linked dominant"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1548, 'Dermatology', 'Autoimmune Blistering Disorders', 'Moderate', 'Skin', 7, '{"id":1548,"subject":"Dermatology","chapter":"Autoimmune Blistering Disorders","difficulty":"Moderate","source":"Skin","sourceNo":7,"q":"Pemphigus vulgaris is characterized by all, except:","o":["Positive Nikolsky’s sign","Oral erosions","Subepidermal bulla","Tzanck smear showing acantholytic cells"],"a":2,"e":"Pemphigus vulgaris is an intraepidermal blistering disease.","pyqMatches":[{"year":"2012","no":1376,"q":"Pemphigus vulgaris is characterized by all, except:","o":["Positive Nikolsky’s sign","Oral erosions","Subepidermal bulla","Tzanck smear showing acantholytic cells"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1549, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 8, '{"id":1549,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":8,"q":"Which of the following is the agent of choice for cryosurgery?","o":["Nitrous oxide","CO2 snow","Liquid nitrogen spray","Freons"],"a":2,"e":"This has a temperature of -196 c(spray/probe) & the only cryogen advocated for malignant skin lesions. Ref: Textbook of dermatosurgery & cosmetology, satish S savant, E-2,P-117.","pyqMatches":[{"year":"2015","no":1304,"q":"Which of the following is the agent of choice for cryosurgery?","o":["Nitrous oxide","CO2 snow","Liquid nitrogen spray","Freons"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1550, 'Dermatology', 'Acne & Disorders of Pilosebaceous Unit', 'Easy', 'Skin', 9, '{"id":1550,"subject":"Dermatology","chapter":"Acne & Disorders of Pilosebaceous Unit","difficulty":"Easy","source":"Skin","sourceNo":9,"q":"Treatment of nodulocystic acne is","o":["Erythromycin","Tertacycline","Isoretinonine (Retinoic acid)","Steroids"],"a":2,"e":"C i.e. Isoretinonine","pyqMatches":[{"year":"2014","no":1923,"q":"Treatment of nodulocystic acne is","o":["Erythromycin","Tertacycline","Isoretinonine (Retinoic acid)","Steroids"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1551, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 10, '{"id":1551,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":10,"q":"Anagen phase of the hair indicates:","o":["The phase of activity and growth","The phase of transition","The phase of resting","The phase of degeneration"],"a":0,"e":"A i.e. The phase of activity & growth","pyqMatches":[{"year":"2015","no":1581,"q":"Anagen phase of the hair indicates:","o":["The phase of activity and growth","The phase of transition","The phase of resting","The phase of degeneration"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1552, 'Dermatology', 'Eczemas & Dermatitis', 'Hard', 'Skin', 11, '{"id":1552,"subject":"Dermatology","chapter":"Eczemas & Dermatitis","difficulty":"Hard","source":"Skin","sourceNo":11,"q":"After hepatitis B vaccination child with allergic family history and pruritis involving face & convexities developed numerous umblicated vesicles; which became pustular & haemorhagic & crusted. After 2 days child developed high fever and lymphadenopathy. The diagnosis is","o":["Secondary infected atopic dermatitis","Molluscum contagiosum","Eczema herpaticum","Eczema vaccinatum"],"a":2,"e":"C. i.e. Eczema herpaticurrtx * Eczema herpeticum or Kaposi''s varicelliform eruption results from wide spread (usually) primary HSV- 1 (herpes simplexl) infection in skin damaged by atopic dermatitis (eczema)Q. * Patients with atopic eczema may develop severe orofacial herpes simplex virus (HSV) infectionQ (eczema herpaticum), which may rapidly involve extensive areas of skin & occasionally disseminate to visceral organs. Systemic acyclovir or valaciclovir is treatment of choice. * In atopic dermatitis patients, small pox vaccination or even exposure to vaccinated individual, may cause severe wide spread erruption (k/a eczema vaccinatum) that resembles to eczema herpaticum. * Kaposis varicelliform eruptions manifest either as - eczema herpeticum or eczema vaccinatum. Disease Causative Virus Eczema HSV-1 (Herpes simplex herpeticum honimis virus)Q Eczema Vaccinia virus vaccinatumdue to inadvertent vaccination of small pox with live virus vaccine Milker''s node Paravaccinia / Pseudocowpox","pyqMatches":[{"year":"2015","no":1585,"q":"After hepatitis B vaccination child with allergic family history and pruritis involving face & convexities developed numerous umblicated vesicles; which became pustular & haemorhagic & crusted. After 2 days child developed high fever and lymphadenopathy. The diagnosis is","o":["Secondary infected atopic dermatitis","Molluscum contagiosum","Eczema herpaticum","Eczema vaccinatum"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1553, 'Dermatology', 'Autoimmune Blistering Disorders', 'Hard', 'Skin', 12, '{"id":1553,"subject":"Dermatology","chapter":"Autoimmune Blistering Disorders","difficulty":"Hard","source":"Skin","sourceNo":12,"q":"A 40 year old male reported with recurrent episodes of oral ulcers, large areas of denuded skin and flacid vesiculo-bullous eruptions. Which is the most important bed-side investigation helpful in establishing the diagnosis -","o":["Gram staining of the blister fluid","Culture and sensitivity","Skin biopsy and immunoflurescence","Tzanck smear from the floor of bulla"],"a":3,"e":"Ans. D. i.e. Tzanck smear from the floor of bulla","pyqMatches":[{"year":"2013","no":1648,"q":"A 40 year old male reported with recurrent episodes of oral ulcers, large areas of denuded skin and flacid vesiculo-bullous eruptions. Which is the most important bed-side investigation helpful in establishing the diagnosis","o":["Gram staining of the blister fluid","Culture and sensitivity","Skin biopsy and immunoflurescence","Tzanck smear from the floor of bulla"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1554, 'Dermatology', 'Autoimmune Blistering Disorders', 'Easy', 'Skin', 13, '{"id":1554,"subject":"Dermatology","chapter":"Autoimmune Blistering Disorders","difficulty":"Easy","source":"Skin","sourceNo":13,"q":"True about pemphigus vulgaris A/E:","o":["Subepidermal","Autoimmune disease","Tzanck smear shows acanthoyltic cells","Antibody are formed against desmogleins"],"a":0,"e":"A i.e. Subepidermal","pyqMatches":[{"year":"2015","no":1602,"q":"True about pemphigus vulgaris A/E:","o":["Subepidermal","Autoimmune disease","Tzanck smear shows acanthoyltic cells","Antibody are formed against desmogleins"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1555, 'Dermatology', 'Acne & Disorders of Pilosebaceous Unit', 'Hard', 'Skin', 14, '{"id":1555,"subject":"Dermatology","chapter":"Acne & Disorders of Pilosebaceous Unit","difficulty":"Hard","source":"Skin","sourceNo":14,"q":"A girl about to marry has comedonal acne. Drug to treat such a case is: March 2013","o":["Topical antibiotic","Benzoyl peroxide","Retinoids","Estrogen"],"a":2,"e":"Ans. C i.e. Retinoids Retinoids are mainly comedolytic Acne Comedones are characteristic of: Acne vulgaris Comedones are: * Small cysts, * formed in hair follicles, * due to blockage of the follicular orifice * by the retention of sebum and keratinous material Acen vulgaris is caused by: Obstruction of pilosebaceous duct Nodulocystic acne (NA) Treatment of NA: Isotretinonin (synthetic retinoic acid)","pyqMatches":[{"year":"2015","no":1582,"q":"A girl about to marry has comedonal acne. Drug to treat such a case is: March 2013","o":["Topical antibiotic","Benzoyl peroxide","Retinoids","Estrogen"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1556, 'Dermatology', 'Papulosquamous Disorders', 'Easy', 'Skin', 15, '{"id":1556,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Easy","source":"Skin","sourceNo":15,"q":"Koebner phenomenon seen in ?","o":["Psoriasis","Lichen planus","Warts","All the above"],"a":3,"e":"Ans. is ''d'' i.e., All the above","pyqMatches":[{"year":"2012","no":1374,"q":"Koebner phenomenon seen in ?","o":["Psoriasis","Lichen planus","Warts","All the above"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1557, 'Dermatology', 'Pigmentary Disorders', 'Easy', 'Skin', 16, '{"id":1557,"subject":"Dermatology","chapter":"Pigmentary Disorders","difficulty":"Easy","source":"Skin","sourceNo":16,"q":"Heliotopre sign is seen in ?","o":["Dermatomyositis","Scleroderma","Photodermatitis","Vitiligo"],"a":0,"e":"Ans. is ''a'' i.e., Dermatomyositis Cutaneous signs of dermatomyosits Gottron''s papules :- lilac or violaceous papules on knuckle, dorsa of hands. Gottron''s sign :- Violaceous erythema with edema over shoulder, arms, forearms. Heliotrope sign :- Violaceous erythema with edema over eyelids, periorbital region. Poikiloderma :- Atrophy of skin, hypopigmentaion, dilated blood vessels over trunk. Mechanic hand :- Symmetric hyperkeratosis along ulnar aspect of thumb and radial aspect of fingers. Shawl Sign :- Violaceous erythema extending from dorsolateral aspect of hands, forearms, and arms to shoulder & neck. Calcinosis cutis :- Calcium deposits in skin (in Juvenile variant). Miscellaneous signs :- Photosensitivity, vasculitis, panniculitis, Nail- fold telangiectasia. Extracutaneous involvement","pyqMatches":[{"year":"2014","no":1911,"q":"Heliotopre sign is seen in ?","o":["Dermatomyositis","Scleroderma","Photodermatitis","Vitiligo"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1558, 'Dermatology', 'Miscellaneous', 'Hard', 'Skin', 17, '{"id":1558,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Hard","source":"Skin","sourceNo":17,"q":"Patient presents with discharge per urethrum and microscopy shows presence of intracytoplasmic gram negative cocci; what is the most probable diagnosis ?","o":["Gonorrhea","Donovanosis","Bacterial vaginosis","Syphilis"],"a":0,"e":"Ans. is ''a'' i.e., Gonorrhea Presence of pus discharge per urethrum in males with presence of intracytoplasmic gram negative cocci are pointers to the presence of N. gonorrhea infection. GONOCOCCAL INFECTION N.Gonorrhoeae is an intracytoplasmic gram negative coccus. N. gonorrhoeae is exclusively a human pathogen although chimpanzees have been infected artificially. It is never found as a normal commensal although a proportion of those infected, particularly women, may remain asymptomatic. Acute urethritis is most common manifestation. Purulent discharge per urethra is the most common manifestation. The process may extend, along the urethra, to prostate, seminal vesicle, epididymis.","pyqMatches":[{"year":"2014","no":1913,"q":"Patient presents with discharge per urethrum and microscopy shows presence of intracytoplasmic gram negative cocci; what is the most probable diagnosis ?","o":["Gonorrhea","Donovanosis","Bacterial vaginosis","Syphilis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1559, 'Dermatology', 'Papulosquamous Disorders', 'Easy', 'Skin', 18, '{"id":1559,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Easy","source":"Skin","sourceNo":18,"q":"Christmas tree appearance in skin is seen in ?","o":["Pityriasis rosea","Pityriasisrubrapilaris","Psoriasis","Vitiligo"],"a":0,"e":"Ans. is ''a'' i.e., Pityriasis rosea Pityriasis rosacea P. rosea is a common scaly disorder, occuring usually in children and young adults (10-35 years). Characterized by round/oval pink brown patches with a superficial, centrifugal scale, distributed over trunk in a Christmas tree pattern. The disease is thought to be viral disease, is self limiting, and subsides in 6-12 weeks. The exact etiology is not known, but it is considered to be a viral disease; Human Herpes virus 6 (HHV 6) and Human Herpes virus 7 (HHV 7) may play a role. Clinical manifestations of P. rosea The disease starts with an upper respiratory prodrome or a mild flu. After 1-2 weeks, Annular erythmatous plaque appears on trunk that is referred to as mother patch or herald patch. Over the next 1-2 weeks, fresh patch appear all over the trunk, in a Christmas tree configuration or Fir tree Configration. The lesions are pinkish in white skin, hence the name rosea. However, on the dark Indian skin the lesions are skin coloured or brown. The most characteristic clue for the diagnosis is the presence of a fine scale at the edge of the lesion referrred to as centrifugal scale or collarette scales or cigarette paper scales. Lesions subside with hyperpigmentation. Trunk is involved predominantly, Sometimes (in 20% of patients) lesions occur predominantly on extremities and neck (inverse pattern).","pyqMatches":[{"year":"2014","no":1914,"q":"Christmas tree appearance in skin is seen in ?","o":["Pityriasis rosea","Pityriasisrubrapilaris","Psoriasis","Vitiligo"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1560, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 19, '{"id":1560,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":19,"q":"Pomphylox affects ?","o":["Palms & soles","Groin","Scalp","Trunk"],"a":0,"e":"Ans is ''a'' i.e., Palms & soles POMPHOLYX An attack of pompholyx is characterized by the sudden onset of crops of clear vesicles, which appear ''sago-like''. Itching may be severe, preceding the eruption of vesicles. The attack subsides spontaneously in 2-3 weeks . In mild cases, only the sides of the fingers may be affected, but in a typical case the vesicles develop symmetrically on the palms and/or soles","pyqMatches":[{"year":"2014","no":1915,"q":"Pomphylox affects ?","o":["Palms & soles","Groin","Scalp","Trunk"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1561, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 20, '{"id":1561,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":20,"q":"Erythrasma is caused by ?","o":["Comybacterium","Staphylococcus","Streptococcus","Herpes Virus"],"a":0,"e":"Ans. is ''a'' i.e., Cornybacterium Erythrasma is a skin disease that causes brown, scaly skin patches. It is caused by the Gram-positivebacterium Corynebacteriumminutissimum. It is prevalent among diabetics and the obese, and in warm climates; it is worsened by wearing occlusive clothing.","pyqMatches":[{"year":"2014","no":1917,"q":"Erythrasma is caused by ?","o":["Comybacterium","Staphylococcus","Streptococcus","Herpes Virus"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1562, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 21, '{"id":1562,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":21,"q":"HPV causes ?","o":["Condylomalata","Condyloma acuminata","Bubo","Chancre"],"a":1,"e":"Ans. is ''b'' i.e., Condyloma acuminata","pyqMatches":[{"year":"2014","no":1918,"q":"HPV causes ?","o":["Condylomalata","Condyloma acuminata","Bubo","Chancre"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1563, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 22, '{"id":1563,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":22,"q":"Drug of choice for genital warts is ?","o":["Acyclovir","Podophyllin","Minocyclin","Interferon alpha"],"a":1,"e":"Ans. is ''b'' i.e., Podophyllin","pyqMatches":[{"year":"2014","no":1919,"q":"Drug of choice for genital warts is ?","o":["Acyclovir","Podophyllin","Minocyclin","Interferon alpha"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1564, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 23, '{"id":1564,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":23,"q":"Depigmenting agent of choice in in treatment of dermatological disorders is","o":["Hydroquinone","Zinc","Kojic acid","Azelaic acid"],"a":0,"e":"Ans. is ''a'' i.e., Hydroquinone Skin depigmenting agents in clinical use are Hydroquinone - most effective and widely used Kojic acid Kojicdipalmitate Azelaic acid","pyqMatches":[{"year":"2014","no":1920,"q":"Depigmenting agent of choice in in treatment of dermatological disorders is","o":["Hydroquinone","Zinc","Kojic acid","Azelaic acid"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1565, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 24, '{"id":1565,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":24,"q":"Nail pitting is seen with ?","o":["Paronychia","Ectodermal dysplasia","Alopecia areate","All the above"],"a":3,"e":"Ans. is''d'' i.e., All the above","pyqMatches":[{"year":"2014","no":1921,"q":"Nail pitting is seen with ?","o":["Paronychia","Ectodermal dysplasia","Alopecia areate","All the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1566, 'Dermatology', 'Pigmentary Disorders', 'Moderate', 'Skin', 25, '{"id":1566,"subject":"Dermatology","chapter":"Pigmentary Disorders","difficulty":"Moderate","source":"Skin","sourceNo":25,"q":"Vitiligo is associated with the following except","o":["Addison''s disease","Men syndrome","Pernicious anemia","Crohns disease"],"a":3,"e":"Ans. is ''d'' i.e., Crohns disease Vitiligo is associated with the following autoimmune diseases :- Alopecia areata Diabetes mellitus Hyperthyroidism Hypothyroidism Pernicious anemia Addison disease Multiple endocrinopathy syndrome","pyqMatches":[{"year":"2014","no":1922,"q":"Vitiligo is associated with the following except","o":["Addison''s disease","Men syndrome","Pernicious anemia","Crohns disease"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1567, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 26, '{"id":1567,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":26,"q":"True about erythema toxicumneonatorum is ?","o":["It is present in 3 - 5 % of the newborns","It is mostly present at birth","It is called the flea bitten rash of newborn","Topical antibiotics is the treatment of choice"],"a":2,"e":"Ans. is ''c'' i.e., It is called the flea bitten rash of newborn Erythema ToxicumNeonatorum It is the harmless, erythematous, short lived eruptions of the newborn. It is present in 30 - 50% of the newborns It is considered a part of normal transition from the watery womb to the dry external environment. It appears most often in the first 2 days of life and is rarely present at birth It consists of widespread erythematous macules most present in the trunk and the proximal parts of the extremities. Hurwitz called it the flea bitten rash of new born. No active therapy is needed for the treatment.","pyqMatches":[{"year":"2014","no":1924,"q":"True about erythema toxicumneonatorum is ?","o":["It is present in 3 - 5 % of the newborns","It is mostly present at birth","It is called the flea bitten rash of newborn","Topical antibiotics is the treatment of choice"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1568, 'Dermatology', 'Miscellaneous', 'Hard', 'Skin', 27, '{"id":1568,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Hard","source":"Skin","sourceNo":27,"q":"What is the the most probable diagnosis of a child who presents with white umbilicated lesions on face?","o":["Molluscumcontagiosum","Herpes simplex infection","Erythema toxicumneonatorum","Human pappiloma virus infection"],"a":0,"e":"Ans. is ''a'' i.e., Molluscumcontagiosum Pearly white umblicated papule on face in children is most commonly seen in Molluscumcontagiosum. Molluscum contagiosum It is a common viral infection in children. It is caused by pox virus, i.e., Molluscum contagiosum virus. It is characterized by multiple pearly white, dome-shaped papules which are umbilicated centrally. On using a hand lens, many of the papules has a mosaic appearance. Epidermal cells contain eosinophilic intracytoplasmic inclusion bodies (Molluscum or Henderso-Paterson bodies). Autoinoculation can give rise to lesions arranged linearly along line of trauma ----> pseudoismorphic (pseudokoebner''s) phenomenon. M.C. may involve any part of the body In children face is involved most commonly. Anogenital molluscum contagiosum is a STD. Treatement Curretage, electrocautery, cryotherapy are simple and effective methods. Imiquimed, a recently introduced immunostimulant, is helpful in patients with multiple lesions and in small children.","pyqMatches":[{"year":"2014","no":1925,"q":"What is the the most probable diagnosis of a child who presents with white umbilicated lesions on face?","o":["Molluscumcontagiosum","Herpes simplex infection","Erythema toxicumneonatorum","Human pappiloma virus infection"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1569, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 28, '{"id":1569,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":28,"q":"Haascheiben cells in epidermis are responsible for?","o":["Touch","Temperature","Pressure","Proprioception"],"a":0,"e":"Ans. is ''a'' i.e., Touch","pyqMatches":[{"year":"2014","no":1926,"q":"Haascheiben cells in epidermis are responsible for?","o":["Touch","Temperature","Pressure","Proprioception"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1570, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 29, '{"id":1570,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":29,"q":"Apple jelly noddule is seen in ?","o":["Lupus vulgaris","Cutaneous anaphylaxus","Erythroderma","Erysepals"],"a":0,"e":"Ans. is ''a'' i.e., Lupus vulgaris Lupus vulgaris Lupus vulgaris is a chronic and progressive form of cutaneous tuberculosis that occurs in tuberculin sensitive patients. It is the most common type of cutaneous tuberculosis and has most variable presentation. Seen in children and young adults, though no age is exempted. Occurs on exposed area like face (nose, eyelid, pinna); and sometimes on buttock, trunk. Lesions are usually solitary and characterized by : -","pyqMatches":[{"year":"2014","no":1927,"q":"Apple jelly noddule is seen in ?","o":["Lupus vulgaris","Cutaneous anaphylaxus","Erythroderma","Erysepals"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1571, 'Dermatology', 'Autoimmune Blistering Disorders', 'Moderate', 'Skin', 30, '{"id":1571,"subject":"Dermatology","chapter":"Autoimmune Blistering Disorders","difficulty":"Moderate","source":"Skin","sourceNo":30,"q":"Flaccid bullae with mucosal involvement and intraepidermal acantholysis are characteristic of?","o":["Pemphygus vulgaris","Pemphigus foliaceous","Psoriasis","Vitiligo"],"a":0,"e":"Ans. is ''a'' i.e., Pemphygus vulgaris Among the given options, two are vesicullabullous disorders :-","pyqMatches":[{"year":"2014","no":1928,"q":"Flaccid bullae with mucosal involvement and intraepidermal acantholysis are characteristic of?","o":["Pemphygus vulgaris","Pemphigus foliaceous","Psoriasis","Vitiligo"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1572, 'Dermatology', 'Autoimmune Blistering Disorders', 'Easy', 'Skin', 31, '{"id":1572,"subject":"Dermatology","chapter":"Autoimmune Blistering Disorders","difficulty":"Easy","source":"Skin","sourceNo":31,"q":"Ig A deposition in dermoepidermal junction skin seen in ?","o":["Dermatitis herpetiformis","Bullous pemphigoid","Linear IgA disease","Epidermolysis bullosa"],"a":2,"e":"Ans. is ''c'' i.e., Linear IgA disease","pyqMatches":[{"year":"2014","no":1929,"q":"Ig A deposition in dermoepidermal junction skin seen in ?","o":["Dermatitis herpetiformis","Bullous pemphigoid","Linear IgA disease","Epidermolysis bullosa"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1573, 'Dermatology', 'Infections & Infestations', 'Moderate', 'Skin', 32, '{"id":1573,"subject":"Dermatology","chapter":"Infections & Infestations","difficulty":"Moderate","source":"Skin","sourceNo":32,"q":"Not a feature of scabies is ?","o":["Serpentine burrow","Severe itching","Web space affection","Genitalia are not affected"],"a":3,"e":"Ans. is ''d'' i.e., Genitalia are not affected","pyqMatches":[{"year":"2014","no":1930,"q":"Not a feature of scabies is ?","o":["Serpentine burrow","Severe itching","Web space affection","Genitalia are not affected"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1574, 'Dermatology', 'Papulosquamous Disorders', 'Easy', 'Skin', 33, '{"id":1574,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Easy","source":"Skin","sourceNo":33,"q":"True about the lesions of lichen planus ?","o":["Polygonal violaceous paple","Affect skin and mucous membranes","Are pruritic","All the above"],"a":3,"e":"Ans. is ''d'' i.e., All the above","pyqMatches":[{"year":"2014","no":1931,"q":"True about the lesions of lichen planus ?","o":["Polygonal violaceous paple","Affect skin and mucous membranes","Are pruritic","All the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1575, 'Dermatology', 'Autoimmune Blistering Disorders', 'Easy', 'Skin', 34, '{"id":1575,"subject":"Dermatology","chapter":"Autoimmune Blistering Disorders","difficulty":"Easy","source":"Skin","sourceNo":34,"q":"Antigen defect in Pemphigus Vulgaris -","o":["Desmoglein-1","Desmoglein-3","Desmocollin-3","Desmocollin-2"],"a":1,"e":"Ans. is ''b'' i.e., Desmoglein-3","pyqMatches":[{"year":"2014","no":1932,"q":"Antigen defect in Pemphigus Vulgaris","o":["Desmoglein-1","Desmoglein-3","Desmocollin-3","Desmocollin-2"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1576, 'Dermatology', 'Pigmentary Disorders', 'Easy', 'Skin', 35, '{"id":1576,"subject":"Dermatology","chapter":"Pigmentary Disorders","difficulty":"Easy","source":"Skin","sourceNo":35,"q":"Color of tuberous sclerosis lesions on wood lamp examination ?","o":["Bright green","Milky white","Golden yellow","Blue white"],"a":3,"e":"Ans. is ''d'' i.e., Blue white Wood lamp This is a source of ultraviolet light (320-400nm) from which virtually all visible rays have been excluded by a Wood''s (nickel oxide) filter. Primarily emits 360nm. UV light, when absorbed by certain substances, fluorescences in dark and color produced, is useful in diagnosis of the certain conditions Condition Fluorescence colour Tinea capitis Bright yellow green Erythrasma Coral red or pink Vitiligo Milky white Albinism Blue white Leprosy Blue white Tuberous sclerosis Blue white Pseudomonas infectionGreenish white Porphyria Pink/orange Tinea vesicolor Golden yellow","pyqMatches":[{"year":"2014","no":1933,"q":"Color of tuberous sclerosis lesions on wood lamp examination ?","o":["Bright green","Milky white","Golden yellow","Blue white"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1577, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 36, '{"id":1577,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":36,"q":"Alopecia areata is a/ an ?","o":["Autoimmune disorder","Allergic disorder","Anaphylactic disorder","Bacterial infection"],"a":0,"e":"Ans. is ''a'' i.e., Autoimmune disorder","pyqMatches":[{"year":"2014","no":1934,"q":"Alopecia areata is a/ an ?","o":["Autoimmune disorder","Allergic disorder","Anaphylactic disorder","Bacterial infection"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1578, 'Dermatology', 'Infections & Infestations', 'Easy', 'Skin', 37, '{"id":1578,"subject":"Dermatology","chapter":"Infections & Infestations","difficulty":"Easy","source":"Skin","sourceNo":37,"q":"Whitfield''s ointment consists of ?","o":["3% salicylic acid + 6% benzoic acid","3% benzoic acid + 6% salicylic acid","2% salicylic acid + 4% benzoic acid","2% benzoic acid + 4% salicylic acid"],"a":0,"e":"Ans. is ''a'' i.e., 3% salicylic acid + 6% benzoic acid Whitfield''s Ointment Whitfield''s ointment is salicylic acid and benzoic acid in a suitable base, such as lanolin or vaseline. The original ointment contains 3% salicylic acid and 6% benzoic acid, but other ratios are also used. It is used for the treatment of fungal infections, such as athlete''s foot. Its effectiveness is unclear. It can have a slight burning effect that goes away after a few minutes. It is named for Arthur Whitfield (1868-1947), a British dermatologist","pyqMatches":[{"year":"2014","no":1935,"q":"Whitfield''s ointment consists of ?","o":["3% salicylic acid + 6% benzoic acid","3% benzoic acid + 6% salicylic acid","2% salicylic acid + 4% benzoic acid","2% benzoic acid + 4% salicylic acid"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1579, 'Dermatology', 'Papulosquamous Disorders', 'Easy', 'Skin', 38, '{"id":1579,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Easy","source":"Skin","sourceNo":38,"q":"Sphagetti and meat ball appearance is seen in ?","o":["Pityriasis rosacae","Tinea capitis","Tinea carporis","Tinea versicolor"],"a":3,"e":"Ans. is ''d'' i.e., Tinea versicolo Pitvriasis versicolor (tinea versicolor) Tinea versicolor is a misnomer as it is not caused by a dermatophyte; it is caused by a nondermatophytic fungus called Pityrosporum ovale (malasezia furfur). Usually affects young adults. Clinical features There are multiple scaly hypopigmented (more common) or hyperpigmented macules. Scaling is fufuraciousor rice powder like. Macules start around the hair follicles and they merge with each other to form large areas. Affects trunk and shoulders (mainly chest and back). There may be loosening of scales with finger nails- coupled onle or stroke of nail. Lesions are recurrent in nature. Diagnosis","pyqMatches":[{"year":"2014","no":1936,"q":"Sphagetti and meat ball appearance is seen in ?","o":["Pityriasis rosacae","Tinea capitis","Tinea carporis","Tinea versicolor"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1580, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 39, '{"id":1580,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":39,"q":"Which of the following can cause both cicatricial as well as noncicatrical alopecia ?","o":["Alopecia areata","Telogen effluvium","SLE","Hypothyroidism"],"a":2,"e":"Ans. is ''c'' i.e., SLE","pyqMatches":[{"year":"2014","no":1937,"q":"Which of the following can cause both cicatricial as well as noncicatrical alopecia ?","o":["Alopecia areata","Telogen effluvium","SLE","Hypothyroidism"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1581, 'Dermatology', 'Acne & Disorders of Pilosebaceous Unit', 'Easy', 'Skin', 40, '{"id":1581,"subject":"Dermatology","chapter":"Acne & Disorders of Pilosebaceous Unit","difficulty":"Easy","source":"Skin","sourceNo":40,"q":"Miliaria arises from obstruction of ?","o":["Eccrine sweat glands","Apocrine sweat glands","Sebaceous glands","Ectopic sebaceous glands"],"a":0,"e":"Ans. is ''a'' i.e., Eccrine sweat glands Milliria Occur as a result of either obliteration or disruption of the eccrine sweat duct. Three forms :-","pyqMatches":[{"year":"2012","no":1368,"q":"Miliaria arises from obstruction of ?","o":["Eccrine sweat glands","Apocrine sweat glands","Sebaceous glands","Ectopic sebaceous glands"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":1939,"q":"Miliaria arises from obstruction of ?","o":["Eccrine sweat glands","Apocrine sweat glands","Sebaceous glands","Ectopic sebaceous glands"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1582, 'Dermatology', 'Dermatology Basics', 'Hard', 'Skin', 41, '{"id":1582,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Hard","source":"Skin","sourceNo":41,"q":"Patchy hair loss with velvety skin points to the diagnosis of","o":["Alopecia aereata","Trichotelomania","Hyperthyroidism","Adenoma sebacicum"],"a":2,"e":"Ans. is ''c'' i.e., Hyperthyroidism Hair loss in combination with velvety skin is seen in patients with excess of thyroid hormone production; thus the most probable answer is hyperthyroidism","pyqMatches":[{"year":"2014","no":1941,"q":"Patchy hair loss with velvety skin points to the diagnosis of","o":["Alopecia aereata","Trichotelomania","Hyperthyroidism","Adenoma sebacicum"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1583, 'Dermatology', 'Infections & Infestations', 'Easy', 'Skin', 42, '{"id":1583,"subject":"Dermatology","chapter":"Infections & Infestations","difficulty":"Easy","source":"Skin","sourceNo":42,"q":"Black piedra is caused by ?","o":["Piedraia hortae","Trichosporon asahi","Trichosporon ovoides","Trichosporon inkin"],"a":0,"e":"Ans. is ''a'' i.e., Piedraia hortae Piedra is an asymptomatic superficial fungal infection of the hair shaft also known as trichomycosis nodu- laris. Black piedra is caused by Piedraia hortae, whereas white piedra is caused by pathogenic species of the Trichosporon genus, namely Trichosporon asahii, Trichosporon ovoides, Trichosporon inkin, Trichosporon mucoides, Trichosporon asteroides, and Trichosporon cutaneum.","pyqMatches":[{"year":"2014","no":1942,"q":"Black piedra is caused by ?","o":["Piedraia hortae","Trichosporon asahi","Trichosporon ovoides","Trichosporon inkin"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1584, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 43, '{"id":1584,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":43,"q":"In scabies which skin layer is affected?","o":["Stratum corneum","Stratum basale","Stratum lucidum","Stratum germinatum"],"a":0,"e":"Ans. is ''a'' i.e., Stratum corneum After copulation, the male mite dies and the female mite burrows into the superficial skin layer (stratum cornuem) at the rate of 2 mm/day. Female mite lays eggs which hatch into larva, which moulds and mature into adult mites. The mite then burrows into stratum corneum. These burrow is visible clinically as an irregular gray-brown line. Burrow is a pathognomic sign for scabies.","pyqMatches":[{"year":"2014","no":1944,"q":"In scabies which skin layer is affected?","o":["Stratum corneum","Stratum basale","Stratum lucidum","Stratum germinatum"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1585, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 44, '{"id":1585,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":44,"q":"Groove sign of greenbalt is seen in ?","o":["LGV","Donovanosis","Chancroid","Genital Herpes"],"a":0,"e":"Ans. is ''a'' i.e., LGV Groove sign of Greenblatt'' is pathognomonic of LGV when inguinal lymph nodes are enlarged, they are separated by Poupart''s ligment, producing a groove.","pyqMatches":[{"year":"2014","no":1945,"q":"Groove sign of greenbalt is seen in ?","o":["LGV","Donovanosis","Chancroid","Genital Herpes"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1586, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 45, '{"id":1586,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":45,"q":"Mutation in which collagen is present in epidermolysis bullosa ?","o":["II","IV","V","VII"],"a":3,"e":"Ans. is ''d'' i.e., VII Molecular pathology of EB Normal basement membrane is between epidermal basal layer and dermis. This basement membrane (basal lamina) is attached to basal cells hemidesmosomes with the help of keratin containing intermediate filaments and is attached to dermis (dermal papillary layer) with the help of type VII collegen containing fibrils. Any defect in this anchoring complex leads to separation of skin; the site of separation depends on the type of defect","pyqMatches":[{"year":"2014","no":1946,"q":"Mutation in which collagen is present in epidermolysis bullosa ?","o":["II","IV","V","VII"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1587, 'Dermatology', 'Infections & Infestations', 'Easy', 'Skin', 46, '{"id":1587,"subject":"Dermatology","chapter":"Infections & Infestations","difficulty":"Easy","source":"Skin","sourceNo":46,"q":"Onychomycosis is most commonly caused by ?","o":["a) Trichophyton rubrum","Trichophyton mentagrophytes","Epidermatophyton floccosum","a) Candida"],"a":0,"e":"Ans. is ''a'' i.e., Trichophyton rubrum Tinea Unguium (Onychomycosis) Tinea unguium is dermatophytic infection of fingers and toe nails. Most common causative species is T-rubrum. Toe nails are more commonly involved. T. Unguium may be of two types : ?","pyqMatches":[{"year":"2014","no":1948,"q":"Onychomycosis is most commonly caused by ?","o":["a) Trichophyton rubrum","Trichophyton mentagrophytes","Epidermatophyton floccosum","a) Candida"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1588, 'Dermatology', 'Eczemas & Dermatitis', 'Hard', 'Skin', 47, '{"id":1588,"subject":"Dermatology","chapter":"Eczemas & Dermatitis","difficulty":"Hard","source":"Skin","sourceNo":47,"q":"RAST test is used in diagnosis of","o":["Allergic dermatitis","Seborrhoeicdematitis","Mycosis fungoides","Squamous cell carcinoma"],"a":0,"e":"Ans. is ''a'' i.e., Allergic dermatitis RAST : Radioallergosorbent assay It is the method used to measure total as well as specific IgE against a particular allergen or a complex. Diagnostic tests in allergic contact dermatitis Diagnostic Tests (if indicated) Patch testing Photopatch testing Tests for immediate hypersensitivity Radioallergosorbent assay test (RAST) Open and semiopen patch tests (read at 10 and 45 minutes) Prick test Scratch-chamber test Repeat open application \"use\" test Potassium hydroxide examination to fungi, glass fibers Fungal, bacterial, and viral smears and cultures Skin biopsies Dimethylglyoxime test for detecting nickel, other tests (detection of chromates and formaldehyde) Chemical analysis","pyqMatches":[{"year":"2014","no":408,"q":"RAST test is used in diagnosis of","o":["Allergic dermatitis","Seborrhoeicdematitis","Mycosis fungoides","Squamous cell carcinoma"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1589, 'Dermatology', 'Eczemas & Dermatitis', 'Easy', 'Skin', 48, '{"id":1589,"subject":"Dermatology","chapter":"Eczemas & Dermatitis","difficulty":"Easy","source":"Skin","sourceNo":48,"q":"Characteristic of chronic eczema ?","o":["Erythema","Induration","Lichenification","Edema"],"a":2,"e":"Ans. is ''c'' i.e., Lichenification Phase (stage) Clinical features Histology Acute Vesicles a Erythema Edema o Crusts Spongiosis (intracellular edema) Subacute Erythmatous, hyperpigmented plaque Scales & Crusts Parakeratosis Chronic Lichenification Thickening of stratum malpighi","pyqMatches":[{"year":"2013","no":1649,"q":"Characteristic of chronic eczema ?","o":["Erythema","Induration","Lichenification","Edema"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1590, 'Dermatology', 'Miscellaneous', 'Hard', 'Skin', 49, '{"id":1590,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Hard","source":"Skin","sourceNo":49,"q":"Sex worker with discharging ulcer, gram negative diplococci & growth on modified Thayer martin media. Diagnosis ?","o":["N. gonococci","Syphilis","LGV","Chaneroid"],"a":0,"e":"Ans. is ''a'' i.e., N. gonococci Information in this question are ?","pyqMatches":[{"year":"2013","no":1668,"q":"Sex worker with discharging ulcer, gram negative diplococci & growth on modified Thayer martin media. Diagnosis ?","o":["N. gonococci","Syphilis","LGV","Chaneroid"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1591, 'Dermatology', 'Acne & Disorders of Pilosebaceous Unit', 'Easy', 'Skin', 50, '{"id":1591,"subject":"Dermatology","chapter":"Acne & Disorders of Pilosebaceous Unit","difficulty":"Easy","source":"Skin","sourceNo":50,"q":"Difference in acne rosacea & acne vulgaris-","o":["Pustule","Erythema","Papule","Absence of comedone"],"a":3,"e":"Ans. is ''d'' i.e., Absence of comedone","pyqMatches":[{"year":"2013","no":1653,"q":"Difference in acne rosacea & acne vulgaris","o":["Pustule","Erythema","Papule","Absence of comedone"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1592, 'Dermatology', 'Pigmentary Disorders', 'Easy', 'Skin', 51, '{"id":1592,"subject":"Dermatology","chapter":"Pigmentary Disorders","difficulty":"Easy","source":"Skin","sourceNo":51,"q":"Frequency of woods lamp is ?","o":["365 nm","400 nm","320 nm","200 nm"],"a":0,"e":"Ans. is `a'' i.e., 360 nm Wood''s lamp Wood''s lamp has an ultraviolet light lamp (365 nm) with a filter containing nickle oxide and barium silicate. The UV light, when absorbed by certain substances, fluorescences in dark and the color of fluorescence is useful in diagnosis of the condition. Condition Fluorescent colours Tinea capitis Bright yellow green Erythrasma Coral red or pink Vitiligo Milky white Albinism Blue white Leprosy Blue white Tuberous sclerosis Blue white Pseudomonas infection Greenish white Porphyria Pinklorange Tinea versicolor Golden yellow","pyqMatches":[{"year":"2013","no":1689,"q":"Frequency of woods lamp is ?","o":["365 nm","400 nm","320 nm","200 nm"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1593, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 52, '{"id":1593,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":52,"q":"Lovibond profile sign is seen in ?","o":["Koilonychia","Platynochia","Clubbing","Onycholysis"],"a":2,"e":"Ans. is ''c'' i.e., Clubbing Clinical indicators of clubbing are Lovibond profile sign and curth''s modified profile sign\". Lovibond angle is the angle located at the junction between the nail plate and proximal nail fold. It is normally less than 160°. In clubbing, the angle exceeds 180° (Lovibond profile sign).","pyqMatches":[{"year":"2013","no":1696,"q":"Lovibond profile sign is seen in ?","o":["Koilonychia","Platynochia","Clubbing","Onycholysis"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1594, 'Dermatology', 'Acne & Disorders of Pilosebaceous Unit', 'Easy', 'Skin', 53, '{"id":1594,"subject":"Dermatology","chapter":"Acne & Disorders of Pilosebaceous Unit","difficulty":"Easy","source":"Skin","sourceNo":53,"q":"Which hormone is responsible for acne ?","o":["Estrogen","Thyroid","Testosterone","Gonadotropins"],"a":2,"e":"Ans. is ''c'' i.e., Testosterone Predisposing factors for Acne vulgaris Genetic factors Hormones -4 Androgens, glucocorticoids. Psychological stress and depression. Environmental factors High temperature & humidity. Cosmetics -3 Containing lenolin, petroleum, vegetable oils. Infection --> Propionibacterium, Pityrosporum, Staph. epidermidis. Menstural cycle -4 Premenstural aggravation. Hyperkeratosis of pilosebaceous ostia. Drugs Antepileptics (Carbamazepine, phenytoin, phenobarbitone), antitubercular (INH, rifampin, ethionamide), antidepressants, cyclosporine, Vitamin B12.Cough syrups containing halogens (Iodides, bromides).","pyqMatches":[{"year":"2013","no":1654,"q":"Which hormone is responsible for acne ?","o":["Estrogen","Thyroid","Testosterone","Gonadotropins"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1595, 'Dermatology', 'Eczemas & Dermatitis', 'Easy', 'Skin', 54, '{"id":1595,"subject":"Dermatology","chapter":"Eczemas & Dermatitis","difficulty":"Easy","source":"Skin","sourceNo":54,"q":"Hanifin & Rajke is the diagnostic criteria for","o":["Atopic dermatitis","Contact dermatitis","Urticaria","Erythroderma"],"a":0,"e":"Ans. is ''a'' i.e., Atopic dermatitis Hanifin and Rajka criteria is for diagnosis of atopic dermatitis. Diagnostic criteria (Hanifin and Rajka) Based mainly on clinical experience Major criteria","pyqMatches":[{"year":"2013","no":1659,"q":"Hanifin & Rajke is the diagnostic criteria for","o":["Atopic dermatitis","Contact dermatitis","Urticaria","Erythroderma"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1596, 'Dermatology', 'Infections & Infestations', 'Easy', 'Skin', 55, '{"id":1596,"subject":"Dermatology","chapter":"Infections & Infestations","difficulty":"Easy","source":"Skin","sourceNo":55,"q":"Treatment of choice of scabies in pregnancy ?","o":["Ivermectin","Garna-benzen hexachloride","Permethrin","Garna-benzen hexachloride"],"a":2,"e":"Ans. is ''c'' i.e., Permethrin ''Premethrin is the drug of choice for infants as well as pregnant and nursing women''. — Evidence based dermatology Alternatives are benzyl-benzoate and crotamitone. Gamma benzen hexachloride and ivermectin are not recommended.","pyqMatches":[{"year":"2013","no":1678,"q":"Treatment of choice of scabies in pregnancy ?","o":["Ivermectin","Garna-benzen hexachloride","Permethrin","Garna-benzen hexachloride"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1597, 'Dermatology', 'Eczemas & Dermatitis', 'Easy', 'Skin', 56, '{"id":1597,"subject":"Dermatology","chapter":"Eczemas & Dermatitis","difficulty":"Easy","source":"Skin","sourceNo":56,"q":"Most common metal in contact allergic dermatitis is?","o":["Gold","Silver","Aluminium","Nickel"],"a":3,"e":"Ans. is ''d'' i.e., Nickel Contact dermatitis Contact dermatitis is localized rash or irritation of skin caused by contact with a foreign substance. Contact dermatitis is a localized disease, i.e., lesion occurs at the site of contact. However, in sever cases, the lesions may extend outside the contact area or it may become generalized (referred to as id eruption). Contact dermatitis is mainly of two types : ? A. Irritant contact dermatitis Due to direct irritant action of the material e.g. Solvents, Alkalis, Detergents. Most common sites are hands & forearms. B. Allergic contact dermatis It is due to delayed hypersensitivity (type IV hypersensitivity) to a particular antigen in a sensitized individual. The most common allergens causing allergic contact dermatitis are pollen and metals : ?","pyqMatches":[{"year":"2013","no":1660,"q":"Most common metal in contact allergic dermatitis is?","o":["Gold","Silver","Aluminium","Nickel"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1598, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 57, '{"id":1598,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":57,"q":"Skin scrapping & KOH mounting is done for ?","o":["Leprosy","Varicella","Fungus","HSV"],"a":2,"e":"Ans. is ''c'' i.e., Fungus Laboratory diagnosis of fungal infection Laboratory diagnosis of fungal infection depends on : ?","pyqMatches":[{"year":"2013","no":1679,"q":"Skin scrapping & KOH mounting is done for ?","o":["Leprosy","Varicella","Fungus","HSV"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1599, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 58, '{"id":1599,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":58,"q":"Lines of Blaschko''s are related to ?","o":["Keratinocytes","Blood vessels","Nerves","Bones"],"a":0,"e":"Ans. is ''a'' i.e., Keratinocytes Blaschko''s lines correspond to the pathways followed by keratinocytes migrating from neural crest during embryogenesis. The lines follow a V-shape over spine, an S-shape on abdomen, inverted U-shape from breast area to upper arm and perpendicular down the front and back of the lower extrimities. A number of inflammatory conditions can follow Blaschko''s lines -","pyqMatches":[{"year":"2013","no":1652,"q":"Lines of Blaschko''s are related to ?","o":["Keratinocytes","Blood vessels","Nerves","Bones"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1600, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 59, '{"id":1600,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":59,"q":"Treatment of graunolma inguinale is ?","o":["Tetracycline","Azithromycin","Clarithromycin","Streptomycin"],"a":1,"e":"Ans. is ''b'' i.e., Azithromycin Granuloma inguinale or Granuloma venerum or Donovanosis Caused by Calymmatobecteriunt granulomatis, a gram negative intracellular bacteria. IP is 1- 4 weeks. Begins as one or more subcutaneous nodules that erode through skin to produce ulcer. Ulcer has following characterstics.","pyqMatches":[{"year":"2013","no":1685,"q":"Treatment of graunolma inguinale is ?","o":["Tetracycline","Azithromycin","Clarithromycin","Streptomycin"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1601, 'Dermatology', 'Papulosquamous Disorders', 'Easy', 'Skin', 60, '{"id":1601,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Easy","source":"Skin","sourceNo":60,"q":"The following drug is effective in treatment of ptyriasis versicolor ?","o":["Ketoconazole","Metronidazole","Griseofulvin","Chloroquine"],"a":0,"e":"Ans. is ''a'' i.e., Ketoconazole Pityriasis versicolor (Tinea versicolor) Tinea versicolor is a misnomer as it is not caused by dermatophyte; Pityriasis versicolor is more appropriate term. It is caused by a nondermatophyte fungus called Pityrosporum ovale (Malasezia furfur). It usually affects young adults. Clinical features There are multiple small scaly hypopigmented macules (macules may be hyperpigmented also). Scaling is furfuraceous or rice powder like. Macules start around the hair follicles and then merge with each other to form large areas. Affects trunk and shoulders (mainly chest and back). There may be loosening of scales with finger nails -4 Coupled onle or stroke of nail. Lesions are recurrent in nature (may reappear after treatment). Diagnosis of P.versicolor Examination of scales in 10% KOH shows short hyphae and round spores (Sphagetti and meat ball appearance). Wood''s lamp shows apple green fluorescence (blue-green fluorescence). Skin surface biopsy —) A cyanoacrylate adhesive (crazy glue) is used to remove the layer of stratum corneum on glass slide and then stained with PAS reagent. Treatment of P.versicolor","pyqMatches":[{"year":"2013","no":1681,"q":"The following drug is effective in treatment of ptyriasis versicolor ?","o":["Ketoconazole","Metronidazole","Griseofulvin","Chloroquine"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1602, 'Dermatology', 'Dermatology Basics', 'Hard', 'Skin', 61, '{"id":1602,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Hard","source":"Skin","sourceNo":61,"q":"Keivms skin test is used for diagnosis of","o":["Sarcoidosis","Wegeners granulomatosis","Graves disease","None"],"a":0,"e":"Ans. is ''a'' i.e., Sarcoidosis Kveim test (Nickerson-kveim or Kveim-Siltzbach test) was a skin test used to detect sarcoidosis. It is not used know.","pyqMatches":[{"year":"2013","no":1699,"q":"Keivms skin test is used for diagnosis of","o":["Sarcoidosis","Wegeners granulomatosis","Graves disease","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1603, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 62, '{"id":1603,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":62,"q":"Drug of choice for treating chylmydia with gonorrhea is ?","o":["Ciprofloxacin","Norfloxac in","Nalidixic acid","Doxycycline"],"a":3,"e":"Ans. is ''d'' i.e., Doxycycline","pyqMatches":[{"year":"2013","no":1669,"q":"Drug of choice for treating chylmydia with gonorrhea is ?","o":["Ciprofloxacin","Norfloxac in","Nalidixic acid","Doxycycline"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1604, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 63, '{"id":1604,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":63,"q":"Single dose treatment for gonorrhea ?","o":["Azithromycin","Tetracyline","Ceftriaxone","Erythromycin"],"a":2,"e":"Ans. is ''c'' i.e., Ceftriaxone For uncomplicated gonococcal infection, single dose of IM ceftriaxone is the drug of choice. It is given along with azithromycin (single dose) or doxycyline (BD for 7 days) to cover chlamydial infection","pyqMatches":[{"year":"2013","no":1670,"q":"Single dose treatment for gonorrhea ?","o":["Azithromycin","Tetracyline","Ceftriaxone","Erythromycin"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1605, 'Dermatology', 'Eczemas & Dermatitis', 'Easy', 'Skin', 64, '{"id":1605,"subject":"Dermatology","chapter":"Eczemas & Dermatitis","difficulty":"Easy","source":"Skin","sourceNo":64,"q":"Erythroderma % of skin involved is ?","o":[">90%","<30%","30-60%","60-70%"],"a":0,"e":"Ans. is ''a'' i.e., >90% Erythroderma (generalized exfoliative dermatitis) Erythroderma is the term used when the majority of the skin is erythmatous red color and usually associated with crusts, there may be associated erosions, pustules, shedding of nails or hair. \"Exfoliative dermatitis (erythroderma) refers to a scaling erythematous dermatitis involving 90% or more of the cutaneous surface\". Exfoliative dermatitis is characterized by : -","pyqMatches":[{"year":"2013","no":1684,"q":"Erythroderma % of skin involved is ?","o":[">90%","<30%","30-60%","60-70%"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1606, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 65, '{"id":1606,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":65,"q":"Drug causing fixed drug eruption ?","o":["Sulfonamide","Erythromycin","Aminoglycoside","None"],"a":0,"e":"Ans. is `a'' i.e., Sulfonamide Drugs causing fixed drug eruption Paracetamol (Phenacetin) Sulfonamides NSAIDs Aspirin Barbiturates Dapsone Tetracyclines Phenylbutazone","pyqMatches":[{"year":"2013","no":1690,"q":"Drug causing fixed drug eruption ?","o":["Sulfonamide","Erythromycin","Aminoglycoside","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1607, 'Dermatology', 'Eczemas & Dermatitis', 'Easy', 'Skin', 66, '{"id":1607,"subject":"Dermatology","chapter":"Eczemas & Dermatitis","difficulty":"Easy","source":"Skin","sourceNo":66,"q":"Pathergy test is used for ?","o":["Reither''s syndrome","Bechet''s syndrome","Lichen planus","Atopic dermatitis"],"a":1,"e":"Ans. is ''b'' i.e., Bechet''s syndrome Criteria for diagnosis of Bechet''s disease Recurrent oral ulcer for at least 3 times in 12 months. Plus any two of the followings :?","pyqMatches":[{"year":"2013","no":1683,"q":"Pathergy test is used for ?","o":["Reither''s syndrome","Bechet''s syndrome","Lichen planus","Atopic dermatitis"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1608, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 67, '{"id":1608,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":67,"q":"Tzank smear in varicella-zoster shows ?","o":["Acantholysis","Spongiosis","Multinucleated Giant cell","Necrotic cell"],"a":2,"e":"Ans. is ''c'' i.e., Multinucleated Giant cell","pyqMatches":[{"year":"2013","no":1664,"q":"Tzank smear in varicella-zoster shows ?","o":["Acantholysis","Spongiosis","Multinucleated Giant cell","Necrotic cell"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1609, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 68, '{"id":1609,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":68,"q":"Dead layer of epidermis ?","o":["Stratum basale","Straum spinosum","Stratum corneum","Stratum granulosum"],"a":2,"e":"Ans. is ''c'' i.e., Stratum corneum Stratum basale, stratum spinosum and stratum granulosum, together form the living layer and constitute the site of synthesis of keratin (Keratin is mostly synthesized in stratum spinosum). Stratum corneum is the dead layer. Layers of epidermis (From deep to superficial) In palm & sole (5 layers). Elsewhere (4 layers) Stratum basale Stratum basale Stratum spinosum Stratum spinosum Stratum granulosum iv)Stratum lucidum Stratum granulosum Stratum corneum Stratum corneum","pyqMatches":[{"year":"2013","no":1650,"q":"Dead layer of epidermis ?","o":["Stratum basale","Straum spinosum","Stratum corneum","Stratum granulosum"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1610, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 69, '{"id":1610,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":69,"q":"Which of the following cause non- cicatracial alopecia ?","o":["Tenia capitis","SLE","Alopecia areata","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above","pyqMatches":[{"year":"2013","no":1657,"q":"Which of the following cause non- cicatracial alopecia ?","o":["Tenia capitis","SLE","Alopecia areata","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1611, 'Dermatology', 'Papulosquamous Disorders', 'Moderate', 'Skin', 70, '{"id":1611,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Moderate","source":"Skin","sourceNo":70,"q":"Nail pitting is caused by all except ?","o":["Lichen planus","Hyperthyroidism","Fungal infection","Pityriasis Rosacea"],"a":3,"e":"Ans. is ''d'' i.e., Pityriasis Rosacea","pyqMatches":[{"year":"2013","no":1658,"q":"Nail pitting is caused by all except ?","o":["Lichen planus","Hyperthyroidism","Fungal infection","Pityriasis Rosacea"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1612, 'Dermatology', 'Infections & Infestations', 'Moderate', 'Skin', 71, '{"id":1612,"subject":"Dermatology","chapter":"Infections & Infestations","difficulty":"Moderate","source":"Skin","sourceNo":71,"q":"A pregnant lady comes with itchy hand lesions as shown. Her husband also gets it. The best treatment that can be given is ?","o":["Permathrin","Ivermectin","GBH","Benzyl benzoate"],"a":0,"e":"Ans. is ''a'' i.e., Permathrin Permethrin 5% cream is considered the drug of choice for treating scabies in patients, including pregnant women. Other scabicides considered safe for use during pregnancy are sulfur 5-10% in petrolatum and crotamiton 10%. Sulfur is effective and it has a good safety profile; however, sulfur preparations can stain clothing and they are odorous. Crotamiton 10% cream is not absorbed percutaneously and is considered safe in pregnancy although it is not effective as other therapies","pyqMatches":[{"year":"2015","no":1600,"q":"A pregnant lady comes with itchy hand lesions as shown. Her husband also gets it. The best treatment that can be given is ?","o":["Permathrin","Ivermectin","GBH","Benzyl benzoate"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1613, 'Dermatology', 'Papulosquamous Disorders', 'Easy', 'Skin', 72, '{"id":1613,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Easy","source":"Skin","sourceNo":72,"q":"Spongiosis involves ?","o":["Stratum basal","Stratum carneum","Stratum granulosum","Stratum spinosum"],"a":3,"e":"Ans. is ''d'' i.e., Stratum spinosum Separation of keratinocytes due to loss of intracellular bridges —> Acantholysis Intracellular edema of keratinocytes ---> Ballooning Stratum basale Acantholytic cells of pemphigus vulgaris are derived from stratum basal. Basal cell degeneration occurs in Lichen planus. Stratum spinosum Intercellular (in between the cells) edema —> Spongiosis Thickening --> Acanthosis Stratum granulosum Thickening→Hypergranulosis Stratum corneum Retention of nuclei within cells Thickening Stratum corneum is involved in —> Parakerat --> Hyperkera —> Micromun abscess, Dermatop Dermatop","pyqMatches":[{"year":"2013","no":1651,"q":"Spongiosis involves ?","o":["Stratum basal","Stratum carneum","Stratum granulosum","Stratum spinosum"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1614, 'Dermatology', 'Pigmentary Disorders', 'Easy', 'Skin', 73, '{"id":1614,"subject":"Dermatology","chapter":"Pigmentary Disorders","difficulty":"Easy","source":"Skin","sourceNo":73,"q":"Rain drop pigmentation is caused by ?","o":["Clofazimine","Dapsone","Minocycline","Arsenic"],"a":3,"e":"Ans. is ''d'' i.e., Arsenic","pyqMatches":[{"year":"2012","no":642,"q":"Rain drop pigmentation is caused by ?","o":["Clofazimine","Dapsone","Minocycline","Arsenic"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1615, 'Dermatology', 'Miscellaneous', 'Hard', 'Skin', 74, '{"id":1615,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Hard","source":"Skin","sourceNo":74,"q":"man with pain in defecation, no gastrointestinal symptoms, clustered ulcers extending into anal canal. Diagnosis-","o":["CM V","Gonorrhea","Herpes genitalis","HIV"],"a":2,"e":"Ans. is ''c'' i.e., Herpes genitalis Herpes genitalis is a sexually transmitted disease, characterized by appearance of multiple painful vesicles in clusteres in genital area which later on may ulcerate. These small ulcers may combine to form a large ulcer. First attack of this in infection may be associated with flu like symptoms but GIT symptoms are usually absent. Gonorrhea is characterized by acute anterior arthritis associated with thick yellow urethral discharge. Perianal ulceration is not a feature of gonorrhea. Although HIV can be considered in the differential diagnosis of Perianal ulcers, but is usually associated with GIT symptoms. Perianal ulceration is not a feature of CMV infection.","pyqMatches":[{"year":"2013","no":1672,"q":"man with pain in defecation, no gastrointestinal symptoms, clustered ulcers extending into anal canal. Diagnosis","o":["CM V","Gonorrhea","Herpes genitalis","HIV"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1616, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 75, '{"id":1616,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":75,"q":"Acanthosis nigricans is seen in ?","o":["Diabetes","GIT cancer","Hypothyroidism","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above Acanthosis nigricans Acanthosis nigricans is a brown to black, velvety hyperpigmentation of the skin. It is usually found in body folds, such as posterior & lateral folds of neck, axilla, groin, umblicus, forehead. It typically occurs in individuals younger than 40 years of age. Histopathologically papillomatosis is characteristically seen; however, there is no hypermelanosis and there is only mild acanthosis, if present. It is associated with","pyqMatches":[{"year":"2013","no":1697,"q":"Acanthosis nigricans is seen in ?","o":["Diabetes","GIT cancer","Hypothyroidism","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1617, 'Dermatology', 'Papulosquamous Disorders', 'Easy', 'Skin', 76, '{"id":1617,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Easy","source":"Skin","sourceNo":76,"q":"Circle of Hebra is involved in ?","o":["Pediculosis corpora","Pityriasis versicolar","Scabies","Leprosy"],"a":2,"e":"Ans. is ''c'' i.e., Scabies Scabies Scabies in is caused by mites of the family Sarcoptidae, which includes Sarcoptes scabiei, the scabies mite. Usually affects children but can occur at any age. More common in low socioeconomic strata as overcrowding and poor hygiene facilitate the spread. The most imp mean of spread is direct contact with the infected individual. Scabies is water shed disease which occurs die to inadequate use of water and improper hygiene. Clinical features :?","pyqMatches":[{"year":"2013","no":1676,"q":"Circle of Hebra is involved in ?","o":["Pediculosis corpora","Pityriasis versicolar","Scabies","Leprosy"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1618, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 77, '{"id":1618,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":77,"q":"Drug causing exanthema ?","o":["Atropine","Phenytoin","Sulfonamide","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above","pyqMatches":[{"year":"2013","no":1691,"q":"Drug causing exanthema ?","o":["Atropine","Phenytoin","Sulfonamide","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1619, 'Dermatology', 'Acne & Disorders of Pilosebaceous Unit', 'Hard', 'Skin', 78, '{"id":1619,"subject":"Dermatology","chapter":"Acne & Disorders of Pilosebaceous Unit","difficulty":"Hard","source":"Skin","sourceNo":78,"q":"A 15cm hyperpigmented macule on an adolosent male undergoes changes such as coarceness, growth of hair & acne. Diagnosis is ?","o":["Melanocytic nevus","Becker nevus","Sebaceous nevus","Sebaceous nevus"],"a":1,"e":"Ans. is ''b'' i.e., Becker nevus Becker Nevus Usually starts in adolescence as an irregular smooth hyperpigmented macule. Usually involves shoulder, anterior chest and scapular region, although any part of the may be involved. Slowly grows in size of a palm wile acquiring thick dark hair. Often lesion resembling acne vulgaris in different stages may appear on surface. No treatment is required.","pyqMatches":[{"year":"2013","no":1686,"q":"A 15cm hyperpigmented macule on an adolosent male undergoes changes such as coarceness, growth of hair & acne. Diagnosis is ?","o":["Melanocytic nevus","Becker nevus","Sebaceous nevus","Sebaceous nevus"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1620, 'Dermatology', 'Miscellaneous', 'Moderate', 'Skin', 79, '{"id":1620,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Skin","sourceNo":79,"q":"All are seen in Behchets syndrome except","o":["Genital ulcers","Genital ulcers","Oral ulcers","Pyoderma gangrenosum"],"a":3,"e":"Ans. is ''d'' i.e., Pyoderma gangrenosum","pyqMatches":[{"year":"2013","no":1682,"q":"All are seen in Behchets syndrome except","o":["Genital ulcers","Genital ulcers","Oral ulcers","Pyoderma gangrenosum"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1621, 'Dermatology', 'Pigmentary Disorders', 'Easy', 'Skin', 80, '{"id":1621,"subject":"Dermatology","chapter":"Pigmentary Disorders","difficulty":"Easy","source":"Skin","sourceNo":80,"q":"Ulceronecrotic nodule is seen in ?","o":["Lucio leprosy","Lucio leprosy","Indeterminate leprosy","Histoid leprosy"],"a":0,"e":"Ans. is ''a'' i.e., Lucio leprosy Lucio phenomenon It is found in lucio leprosy with type 2 lepra reaction. It is prevalent in mexico. Characterized by painful tender red patches particularly on extremities which later on become necrotic and finally develop into brown black eschar. Ulcers are more persistent on legs. Tuberculoid and indeterminate leprosy are characterized by hyperpigmented macule with impairment of sensations. In histoid leprosy, classical feature is erythematous shiny red subcutaneous or cutaneous nodules, esp over the extensor aspect of extremities, back, buttocks & face. Ulceration is unusual.","pyqMatches":[{"year":"2013","no":1673,"q":"Ulceronecrotic nodule is seen in ?","o":["Lucio leprosy","Lucio leprosy","Indeterminate leprosy","Histoid leprosy"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1622, 'Dermatology', 'Infections & Infestations', 'Easy', 'Skin', 81, '{"id":1622,"subject":"Dermatology","chapter":"Infections & Infestations","difficulty":"Easy","source":"Skin","sourceNo":81,"q":"Scalp and face are involved in ?","o":["Adult scabies","Nodular scabies","Infantile scabies","None"],"a":2,"e":"Ans. is ''c'' i.e., Infantile scabies Type Feature o Infantile scabies Scalp, face, palms and soles are involved o Norwegian scabies Crusted hyperkeratotic lesions on face , palms, soles, nails. Itching is not prominent. Mites are found in thousand, most severe form of scabies Crusted scabies Extensive crusts Nodular scabies Extensive crusts Genital scabies Extensive crusts Animal scabies History of contact with cat or dog. Atypical presentation","pyqMatches":[{"year":"2013","no":1677,"q":"Scalp and face are involved in ?","o":["Adult scabies","Nodular scabies","Infantile scabies","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1623, 'Dermatology', 'Miscellaneous', 'Moderate', 'Skin', 82, '{"id":1623,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Skin","sourceNo":82,"q":"Nerves are not involved in ?","o":["Tuberculoid leprosy","Lepromatous leprosy","Indeterminate leprosy","Borderline tuberculoid leprosy"],"a":2,"e":"Ans. is ''c'' i.e., Indeterminate leprosy","pyqMatches":[{"year":"2013","no":1674,"q":"Nerves are not involved in ?","o":["Tuberculoid leprosy","Lepromatous leprosy","Indeterminate leprosy","Borderline tuberculoid leprosy"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1624, 'Dermatology', 'Papulosquamous Disorders', 'Easy', 'Skin', 83, '{"id":1624,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Easy","source":"Skin","sourceNo":83,"q":"Grattage test is used for-","o":["Tinea capitis","Lichen planus","Pemphigus vulgaris","Psoriasis"],"a":3,"e":"Ans. is ''d'' i.e., Psoriasis Bedside tests for psoriasis Two bedside tests can be done to confirm the clinical diagnosis of psoriasis : - i. Grattage test Scraping the lesion with a glass slide causes accentuation of the silvery scales. ii. Auspitz''s Sign Scraping the lesion with glass slide causes accentuation os slivery scales (as in Grattage test). If scraping is continued further, a glistening white adherent membrane (Burlkey''s membrane) appears. On removing Burlkey''s membrane punctate (fine pin point) bleeding become visible, which is referred to as Auspitz''s sign.","pyqMatches":[{"year":"2013","no":1661,"q":"Grattage test is used for","o":["Tinea capitis","Lichen planus","Pemphigus vulgaris","Psoriasis"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1625, 'Dermatology', 'Papulosquamous Disorders', 'Easy', 'Skin', 84, '{"id":1625,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Easy","source":"Skin","sourceNo":84,"q":"Treatment of choice for lichen planus ?","o":["Topical corticosteroids","Systemic corticosteroids","Antihistaminics","Acitretin"],"a":0,"e":"Ans. is ''a'' i.e., Topical corticosteroids Treatment of Lichen planus The first line treatment of lichen planus are topical corticosteroids. Second choice would be systemic corticosteroids for symptom control and possibly more rapid resolution. Oral antihistaminics are given for pruritic. PUVA can be used for extensive lesions. Acitretin can be used for mucosal lesions.","pyqMatches":[{"year":"2013","no":1662,"q":"Treatment of choice for lichen planus ?","o":["Topical corticosteroids","Systemic corticosteroids","Antihistaminics","Acitretin"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1626, 'Dermatology', 'Papulosquamous Disorders', 'Easy', 'Skin', 85, '{"id":1626,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Easy","source":"Skin","sourceNo":85,"q":"Keratodermic sandles is a feature of ?","o":["Pityriasis rosacea","Lichen planus","Psoriasis","Pityriasis rubra pilaris"],"a":3,"e":"Ans. is `d'' i.e., Pityriasis rubra pilaris Pityriasis rubra pilaris It is a chronic papulosquamous disorder of unknown etiology characterized by : ?","pyqMatches":[{"year":"2014","no":1943,"q":"Keratodermic sandles is a feature of ?","o":["Pityriasis rosacea","Lichen planus","Psoriasis","Pityriasis rubra pilaris"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1627, 'Dermatology', 'Pigmentary Disorders', 'Easy', 'Skin', 86, '{"id":1627,"subject":"Dermatology","chapter":"Pigmentary Disorders","difficulty":"Easy","source":"Skin","sourceNo":86,"q":"Schamberg''s purpura are seen on ?","o":["Face","Feet","Chest","Arms"],"a":1,"e":"Ans. is ''b'' i.e., Feet Schamberg''s purpura Most common from of pigmented purpura dermatosis (PPD). Puncate purpura macules develop on lower extrimities, particularly around ankles & pretibial region. Mostly asymptomatic","pyqMatches":[{"year":"2013","no":1692,"q":"Schamberg''s purpura are seen on ?","o":["Face","Feet","Chest","Arms"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1628, 'Dermatology', 'Autoimmune Blistering Disorders', 'Easy', 'Skin', 87, '{"id":1628,"subject":"Dermatology","chapter":"Autoimmune Blistering Disorders","difficulty":"Easy","source":"Skin","sourceNo":87,"q":"Nikolsky''s sign is seen in ?","o":["Pemphigus","Herpes zoster","Bullous impetigo","All of the above"],"a":3,"e":"Ans. is `d'' i.e., All of the above Niko!sky''s sign is seen in ? Pemphigus Toxic epidermal necrolysis Bullous impetigo Steven jonson syndrome Staphylococcus scalded skin syndrome HSV & VZV infection Epidermolysis bullosa Malignancy (leukemia) Mycosis fungoides Bullous lichen planus","pyqMatches":[{"year":"2013","no":1663,"q":"Nikolsky''s sign is seen in ?","o":["Pemphigus","Herpes zoster","Bullous impetigo","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1629, 'Dermatology', 'Infections & Infestations', 'Easy', 'Skin', 88, '{"id":1629,"subject":"Dermatology","chapter":"Infections & Infestations","difficulty":"Easy","source":"Skin","sourceNo":88,"q":"Erythema multiforme is most commonly caused by?","o":["Herpes simplex","Idiopathic","TB","Drugs"],"a":1,"e":"Ans. is ''b'' i.e., Idiopathic Idiopathic erythema multiforme is the most common cause of EM. Herpes simplex is the most important infectious cause of EM. Causes of Erythema multiforme Idiopathic —) Most common cause Viral —> HSV (most important) HBV, Mumps, Adenovirus Bacteria → Streptococci, tuberculosis Fungal —> Coccidioidomycosis, Histoplasmosis. Drugs ---> Antibiotics (Sulphonamide), Phenytoin, NSAIDS. Autoimmune disease —> SLE, thyroiditis, RA Others —> Sarcoidosis, Pregnancy, Malignancy.","pyqMatches":[{"year":"2013","no":1666,"q":"Erythema multiforme is most commonly caused by?","o":["Herpes simplex","Idiopathic","TB","Drugs"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1630, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 89, '{"id":1630,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":89,"q":"Eyebrows don''t grow beyond certain length as they have a short ?","o":["Anagen phase","Telogen phase","Telogen phase","Exogen phase"],"a":0,"e":"Ans. is ''a'' i.e., Anagen phase Hair grows in cycles of various phases. Anagen is growth phase. Catagen is involuting or regression phase. Telogen is resting phase. Exogen is shedding phase. Normally 90% of the follicles are in anagen phase, 10-14% are in Telogen and 1-2 % are in catagen. The cycles duration is variable for the different parts of the body. For eyebrows, the cycle is finished in 3-4 months while for scalp it takes 3-4 years to finish. This is the reason why eyebrows have much shorter length limit as compared to scalp hair.","pyqMatches":[{"year":"2013","no":1655,"q":"Eyebrows don''t grow beyond certain length as they have a short ?","o":["Anagen phase","Telogen phase","Telogen phase","Exogen phase"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1631, 'Dermatology', 'Dermatology Basics', 'Moderate', 'Skin', 90, '{"id":1631,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Moderate","source":"Skin","sourceNo":90,"q":"Not a cutaneous porphyria ?","o":["Erythropoeitic porphyria","Hereditary coproporphyria","Congenital erythropoeitic porphyria","Sideroblastic anemia"],"a":1,"e":"Ans. is ''b'' i.e., Hereditary coproporphyria Porphyrias Porphyrias are heterogenous group of disorders characterized by defective metabolism of porphyrins. Porphyrins are important intermediates in biosynthesis of heme from glycine and succinyl CoA. Each step is controlled by specific enzyme. So, prophyrias are due to inherited or acquired deficiency of enzymes in heme bio- synthetic pathways (also called porphyrias pathway). They manifest with either neurological complications or skin problems (or rarely both). Based on the site of overproduction and accumulation of porphyrins, porphyrias are broadly classified as :? A. Acute (hepatic prophyria)","pyqMatches":[{"year":"2013","no":1693,"q":"Not a cutaneous porphyria ?","o":["Erythropoeitic porphyria","Hereditary coproporphyria","Congenital erythropoeitic porphyria","Sideroblastic anemia"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1632, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 91, '{"id":1632,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":91,"q":"Potato nose is seen in ?","o":["Acne vulgaris","Rhinosporoidosis","Acne rosacea","Lupus vulgaris"],"a":2,"e":"Ans. is ''c'' i.e., Acne rosacea Acne rosacea Acne rosacea, commonly called rosacea, is a chronic non-curable skin disease with periodic ups and down. It occurs in middle age (30-50 years). It is more common in females, but is more severe in males. Rosacea is a centrofacial disease, i.e., it involves the central face →Cheeks, Chin, Forehead, Nose, making typical cruciate pattern of involvement. Periorbital & perioral areas are spared. Clinical features are intermittant flushing followed by more permanent erythma and telangiectasia. On this back-ground, erythmatous papules, papulo pustules and rarely nodules develop. Lesions may be exacerbated by light (photosensitive) and spicy foods. Complications are : ?","pyqMatches":[{"year":"2013","no":1698,"q":"Potato nose is seen in ?","o":["Acne vulgaris","Rhinosporoidosis","Acne rosacea","Lupus vulgaris"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1633, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 92, '{"id":1633,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":92,"q":"Bullous impetigo is caused by ?","o":["Streptococcus","Staphylococcus","Staphylococcus","Y. Pestis"],"a":1,"e":"Ans. is ''b'' i.e., Staphylococcus Impetigo Impetigo is a highly contagious, Gram-positive bacterial infection of superficial layer of epidermis. Impetigo occurs in Two forms : ?","pyqMatches":[{"year":"2014","no":737,"q":"Bullous impetigo is caused by ?","o":["Streptococcus","Staphylococcus","Staphylococcus","Y. Pestis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1634, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 93, '{"id":1634,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":93,"q":"Match stick test is positive in ?","o":["Rhinophyma","Rhinosporiodosis","Lupus vulgaris","P. versicolor"],"a":2,"e":"Ans. is ''c'' i.e., Lupus vulgaris Lupus vulgaris Lupus vulgaris is a chronic and progressive form of cutaneous tuberculosis that occurs in tuberculin sensitive patients. It is the most common type of cutaneous tuberculosis and has most variable presentation. Seen in children and young adults, though no age is exempted. Occurs on exposed area like face (nose, eyelid, pinna); and sometimes on buttock, trunk. Lesions are usually solitary and characterized by : -","pyqMatches":[{"year":"2013","no":1675,"q":"Match stick test is positive in ?","o":["Rhinophyma","Rhinosporiodosis","Lupus vulgaris","P. versicolor"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1635, 'Dermatology', 'Papulosquamous Disorders', 'Hard', 'Skin', 94, '{"id":1635,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Hard","source":"Skin","sourceNo":94,"q":"On back, big black patch diagnosis is ?","o":["Seborrheic melanosis","Becker nevus","Lichen planus pigmentosus","Pityriasis versicolor"],"a":1,"e":"Ans. is `b'' i.e., Becker nevus Becker Nevus Usually starts in adolescence as an irregular smooth hyperpigmented macule. Usually involves shoulder, anterior chest and scapular region, although any part of the may be involved. owly grows in size of a palm wile acquiring thick dark hair. Often lesion resembling acne vulgaris in different stages may appear on surface. No treatment is required. Seborrheic melanosis Brownish black pigmentation typically distributrd over seborrhea areas (forehead & beard, retro auricular folds, neck, upper part of chest, interscapular areas) accompanied by erythema and itching. Lichen planus pigmentosus Hyperpigmented dark brown or slate grey macules distributed mainly over exposed areas and flexures. Pityriasis versicolor Dark brown to black overlapping confluent patches with satellite lesions, mainly over upper trunk and extending to upper arms, neck and abdomen.","pyqMatches":[{"year":"2013","no":1688,"q":"On back, big black patch diagnosis is ?","o":["Seborrheic melanosis","Becker nevus","Lichen planus pigmentosus","Pityriasis versicolor"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1636, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 95, '{"id":1636,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":95,"q":"Which of the following ultra-violet radiation cause most skin disorder ?","o":["UV-A","UV-B","UV-C","None"],"a":1,"e":"Ans. is `b'' i.e., UV-B Ultraviolet radiation (UVR) UVR is electromagnetic radiation with wavelength (200-400 nm) shorter than visible light, but longer than x rays. There are three segments of UVR.","pyqMatches":[{"year":"2013","no":1694,"q":"Which of the following ultra-violet radiation cause most skin disorder ?","o":["UV-A","UV-B","UV-C","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1637, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 96, '{"id":1637,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":96,"q":"Dermatophyes affect ?","o":["Keratin","Dermis of skin","Stratum basal","Stratum basal"],"a":0,"e":"Ans. is ''a'' i.e., Keratin Dermatophytes are keratinophillic fungi, living only on the superficial dead keratin. That is why they infect skin, hair and nail. In skin they infect most superficial layer of the epidermis i.e. stratum corneum. They do not penetrate living tissues. Dermatophytes cause a variety of clinical conditions, collectively known as dermatophytosis, tinea or ringworm. Dermatophytes have been classified into 3 genera :- trichophyton, microsporum, epidermophyton.","pyqMatches":[{"year":"2013","no":1680,"q":"Dermatophyes affect ?","o":["Keratin","Dermis of skin","Stratum basal","Stratum basal"],"a":0,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":1947,"q":"Dermatophyes affect ?","o":["Keratin","Dermis of skin","Stratum basal","Stratum basal"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1638, 'Dermatology', 'Eczemas & Dermatitis', 'Easy', 'Skin', 97, '{"id":1638,"subject":"Dermatology","chapter":"Eczemas & Dermatitis","difficulty":"Easy","source":"Skin","sourceNo":97,"q":"Treatment of dermatitis herpetiformis ?","o":["Gluten free diet","Dapsone","Sulfonamide","All of the above"],"a":0,"e":"Ans. is ''a'' i.e., Gluten free diet Tinea capitis shows greenish fluorescence. Erythrasma gives a coral pink hue. Pseudomonas infection gives a yellowish-green colour","pyqMatches":[{"year":"2013","no":1667,"q":"Treatment of dermatitis herpetiformis ?","o":["Gluten free diet","Dapsone","Sulfonamide","All of the above"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1639, 'Dermatology', 'Acne & Disorders of Pilosebaceous Unit', 'Easy', 'Skin', 98, '{"id":1639,"subject":"Dermatology","chapter":"Acne & Disorders of Pilosebaceous Unit","difficulty":"Easy","source":"Skin","sourceNo":98,"q":"Brown macular pigmentation in malar area in a pregnant female is due to ?","o":["Acne rosacea","Cholasma","Acanthosis nigricans","Urticaric pigmentosa"],"a":1,"e":"Ans. is `b'' i.e., Cholasma Chloasma (Melasma) Melasma (Chlosma) is the most common cause for facial pigmentation in Indian patients. There is Brown macular pigmentation on the molar area of face, forehead and sometimes chin. It usually affects young and middle aged women. When melasma results from pregnancy it is referred as chloasma. Two major etiological factors are : -","pyqMatches":[{"year":"2013","no":1656,"q":"Brown macular pigmentation in malar area in a pregnant female is due to ?","o":["Acne rosacea","Cholasma","Acanthosis nigricans","Urticaric pigmentosa"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1640, 'Dermatology', 'Acne & Disorders of Pilosebaceous Unit', 'Easy', 'Skin', 99, '{"id":1640,"subject":"Dermatology","chapter":"Acne & Disorders of Pilosebaceous Unit","difficulty":"Easy","source":"Skin","sourceNo":99,"q":"15 mm/cm hyperpigmented lesion on shoulder enlarging and hair over it ?","o":["Melanocytic nevus","Becker nevus","Sebaceous nevus","Comedo nevus"],"a":1,"e":"Ans. is ''b'' i.e., Becker nevus Becker Nevus Usually starts in adolescence as an irregular smooth hyperpigmented macule. Usually involves shoulder, anterior chest and scapular region, although any part of the may be involved. Slowly grows in size of a palm wile acquiring thick dark hair. Often lesion resembling acne vulgaris in different stages may appear on surface. No treatment is required.","pyqMatches":[{"year":"2013","no":1687,"q":"15 mm/cm hyperpigmented lesion on shoulder enlarging and hair over it ?","o":["Melanocytic nevus","Becker nevus","Sebaceous nevus","Comedo nevus"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1641, 'Dermatology', 'Dermatology Basics', 'Moderate', 'Skin', 100, '{"id":1641,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Moderate","source":"Skin","sourceNo":100,"q":"All are true about skin except:","o":["Both dermis & ectoderm are derived from ectoderm","Skin accounts for total of 15% of body weight","Most of the cells in skin are keratinocytes derived from ectoderm","Dermis is made up of type1 and type 3 collagen in 3:2 ratio"],"a":0,"e":"Ans:A. Both dermis & ectoderm are derived from ectoderm. True fact: Dermis derived from mesoderm and epidermis from ectoderm.","pyqMatches":[{"year":"2019","no":227,"q":"All are true about skin except:","o":["Both dermis & ectoderm are derived from ectoderm","Skin accounts for total of 15% of body weight","Most of the cells in skin are keratinocytes derived from ectoderm","Dermis is made up of type1 and type 3 collagen in 3:2 ratio"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1642, 'Dermatology', 'Pigmentary Disorders', 'Easy', 'Skin', 101, '{"id":1642,"subject":"Dermatology","chapter":"Pigmentary Disorders","difficulty":"Easy","source":"Skin","sourceNo":101,"q":"Identify the condition in the image?","o":["Leukoderma","Piebaldism","Vitiligo","DLE"],"a":0,"e":"Ans:A. Leukoderma Leukoderma is a skin disease that causes loss of skin pigmentation (melanin) that leads to skin whitening. The white patches on the skin are termed as leukoderma. When the condition gets severe, the spots cover almost all parts of the body including scalp, face and the genitals.","pyqMatches":[{"year":"2019","no":251,"q":"Identify the condition in the image?","o":["Leukoderma","Piebaldism","Vitiligo","DLE"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1643, 'Dermatology', 'Autoimmune Blistering Disorders', 'Moderate', 'Skin', 102, '{"id":1643,"subject":"Dermatology","chapter":"Autoimmune Blistering Disorders","difficulty":"Moderate","source":"Skin","sourceNo":102,"q":"Acantholysis is /are not seen in :","o":["Lichen planus","Bullous pemphigoid","Dermatitis herpetiformis","Hailey-Hailey disease e) Pemphigus vulgaris"],"a":0,"e":":B:C Ans. (A) Lichen planus (B) Bullous pemphigoid (C) Dermatitis herpetiformis Acantholysis: Separation of epidermal cells from each other. Acantholytic disorders includes Pemphigus family (including paraneoplastic pemphigus), eosinophilic spongiosis, Darier''s disease , Hailey-Hailey''s disease (Familial benign chronic pemphigus) and transient acantholytic dermatosis (Grouer''s disease), as well as specific histological patterns such as focal acantholytic dyskeratosis and epidermolytic hyperkeratosis.","pyqMatches":[{"year":"2013","no":1665,"q":"Acantholysis is /are not seen in :","o":["Lichen planus","Bullous pemphigoid","Dermatitis herpetiformis","Hailey-Hailey disease e) Pemphigus vulgaris"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1644, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 103, '{"id":1644,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":103,"q":"Which of the following epidermal layer is dead layer?","o":["Stratum basale","Stratum spinosum","Stratum corneum","Stratum granulosum"],"a":2,"e":"Ans. C. Stratum corneum Stratum corneum (Horny layer): This is the most superficial layer of epidermis and skin. Cells are fully keratinized and end up as anucleate dead cells. Therefore, stratum corneum is dead layer. Stratum corneum is last to develop 4 Therefore in premature newborn it is absent.","pyqMatches":[{"year":"2016","no":1658,"q":"Which of the following epidermal layer is dead layer?","o":["Stratum basale","Stratum spinosum","Stratum corneum","Stratum granulosum"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1645, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 104, '{"id":1645,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":104,"q":"Langerhans cell are seen in which layer of skin?","o":["Stratum basal","Stratum carneum","Stratum granulosum","Stratum spinosum"],"a":3,"e":"Ans. D. Stratum spinosum [Ref Venkataram 151/e p. 2] Langerhans cells These cells are found in stratum spinosum and function as epidermal macrophages (Antigen presenting cells). These cells contain characteristic tennis racquet shaped granules (Birbeck granules).","pyqMatches":[{"year":"2016","no":1659,"q":"Langerhans cell are seen in which layer of skin?","o":["Stratum basal","Stratum carneum","Stratum granulosum","Stratum spinosum"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1646, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 105, '{"id":1646,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":105,"q":"Increase in the thickness of the prickle cell layer of the epidermis is called?","o":["Spongiosis","Acanthosis","Hypergranulosis","Hyperkeratosis"],"a":1,"e":"Ans. B. Acanthosis [Ref Rook''s 7th/e p. 7.36] Important terminology related to epidermal layers Separation of keratinocytes due to loss of intracellular bridges - Acantholysis Intracellular edema of keratinocytes Ballooning","pyqMatches":[{"year":"2016","no":1660,"q":"Increase in the thickness of the prickle cell layer of the epidermis is called?","o":["Spongiosis","Acanthosis","Hypergranulosis","Hyperkeratosis"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1647, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 106, '{"id":1647,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":106,"q":"Substance common in skin and hair is?","o":["Keratin","Laminin","Nectin","Vimentin"],"a":0,"e":"Ans. A. Keratin [Ref: IADVL 3rd /e p. 12] Keratin is a family of fibrous structural proteins. Keratin is the protein that protects epithelial cells from damage or stress. Keratin is the key component of our skin, hair and nails. Its protein building blocks have amino acid chains, coiled, cross- linked and classified as either hard or soft.","pyqMatches":[{"year":"2016","no":1661,"q":"Substance common in skin and hair is?","o":["Keratin","Laminin","Nectin","Vimentin"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1648, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 107, '{"id":1648,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":107,"q":"Which of the following is a melanising agent?","o":["Methoxsalen","Dapsone","Minocycline","Kojic acid"],"a":0,"e":"Ans. A. Methoxsalen [Ref Internet & IADVL 3''/e p. 756] Melanizing agents are drugs that increase sensitivity to solar radiation and promote re-pigmentation of de-pigmented areas of skin. Melanizing agents sensitize the skin to sunlight. As a result, erythema, inflammation and pigmentation occurs.","pyqMatches":[{"year":"2016","no":1662,"q":"Which of the following is a melanising agent?","o":["Methoxsalen","Dapsone","Minocycline","Kojic acid"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1649, 'Dermatology', 'Acne & Disorders of Pilosebaceous Unit', 'Easy', 'Skin', 108, '{"id":1649,"subject":"Dermatology","chapter":"Acne & Disorders of Pilosebaceous Unit","difficulty":"Easy","source":"Skin","sourceNo":108,"q":"Fordyce spots involve?","o":["Penis","Tongue","Fingers","Nails"],"a":0,"e":"Ans. A. Penis [Ref IADVL 3\"1/e p. 1779] Fordyce spots (Fordyce granules or Fordyce disease): Fordyce''s spot represents ectopic sebaceous glands on lips (most common site) and oral mucosa. They may also appear on vulva and penis, where they are called Tyson''s gland, i.e., ectopic sebaceous gland at penis (prepuce) and vulva is called tyson''s gland. These glands have histopathology similar to normal sebaceous glands, despite their ectopic location.","pyqMatches":[{"year":"2016","no":1663,"q":"Fordyce spots involve?","o":["Penis","Tongue","Fingers","Nails"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1650, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 109, '{"id":1650,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":109,"q":"Most common etiology of erythema multiforme is?","o":["Idiopathic","Drugs","HSV","TB"],"a":0,"e":"Ans. A. Idiopathic [Ref: Neena Khanna Yale p. 61, 63] Erythema multiforme Most of the cases of erythema multiforme are idiopathic, but amongst the causative agents Herpes simplex virus is the most important cause. Erythema multiforme is an acute, often self limited erutption characterized by a distinctive clinical eruption, the hallmark of which is the Target lesion (Iris lesion or Bulle''s eye lesion).","pyqMatches":[{"year":"2016","no":1664,"q":"Most common etiology of erythema multiforme is?","o":["Idiopathic","Drugs","HSV","TB"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1651, 'Dermatology', 'Pigmentary Disorders', 'Easy', 'Skin', 110, '{"id":1651,"subject":"Dermatology","chapter":"Pigmentary Disorders","difficulty":"Easy","source":"Skin","sourceNo":110,"q":"Hypopigmented macules are found in?","o":["Addison''s disease","Porphyria","Cutaneous mastocytosis","Tuberous sclerosis"],"a":3,"e":"Ans. D. Tuberous sclerosis [Ref Rook''s 7th/e p. 17.37-17, 39.58-39.59; Behl 10thie p. 154] Causes of localized hypopigmentation (Macule/Patch): Primary Cutaneous disorders: Vitiligo Pityriasis versicolor Pityriasis alba Postinflammatory Nevus depigmentosus (achromicus) Nevus anemicus Piebaldism Chemical leukoderma Idiopathic guttate Hypomelanosis Systemic diseases: Scleroderma Tuberous sclerosis Sarcoidosis Cutaneous T-cell lymphoma Leprosy (tuberculoid & Indeterminate) Onchocerciasis Hypomelanosis of Ito Incontinetia pigmenti (Stage IV) Vogt - Koyangi - Harada disease","pyqMatches":[{"year":"2016","no":1665,"q":"Hypopigmented macules are found in?","o":["Addison''s disease","Porphyria","Cutaneous mastocytosis","Tuberous sclerosis"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1652, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 111, '{"id":1652,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":111,"q":"Which of the following disease is closely related to enetropathy?","o":["Linear Ig A disease","Pemphigus foliaceous","Dermatitis herpetiformis","Erythema multiforme"],"a":2,"e":"Ans. C. Dermatitis herpetiformis [Ref: Behl 10m/e p. 293] Dermatitis herpetiformis is a disease of the skin caused by the deposition of IgA in papillary dermis and along the epidermal basement membrane zone (Dermoepidermal junction). Almost all patients of dermatitis herpetiformis have an associated gluten sensitive enteropathy.","pyqMatches":[{"year":"2016","no":1666,"q":"Which of the following disease is closely related to enetropathy?","o":["Linear Ig A disease","Pemphigus foliaceous","Dermatitis herpetiformis","Erythema multiforme"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1653, 'Dermatology', 'Pigmentary Disorders', 'Easy', 'Skin', 112, '{"id":1653,"subject":"Dermatology","chapter":"Pigmentary Disorders","difficulty":"Easy","source":"Skin","sourceNo":112,"q":"Residual Hypopigmentation following a drug reaction, is best known as?","o":["Vitiligo","Chemical leukoderma","Post inflammatory hypomelanosis","Piebaldism"],"a":2,"e":"Ans. C. Post inflammatory hypomelanosis [Ref IADVL 3\"1/e p. 747-748] Among given options, postinflammatory hypomelanosis is the best answer. understand let us have a look at the definition few important terms. Vitiligo is also an acquired condition with loss of pigmentation but most cases are idiopathic. It is mainly considered to be an autoimmune condition. Precipitated by hormonal changes, acute emotional trauma or stress or any condition leading to immune imbalance. So, any hypomelanosis resulting after inflammation is known as post inflammatory hypomelanosis (including leucoderma). Sometimes both the terms are used synonymously. Whereas the term ''chemical leucoderma'' is used only when there repeated exposure (contact) to some specific chemical. Therefore among given options, postinflammatory hypomelanosis is the best answer as drug reaction is an inflammatory condition leading to residual hypopigmentation.","pyqMatches":[{"year":"2016","no":1667,"q":"Residual Hypopigmentation following a drug reaction, is best known as?","o":["Vitiligo","Chemical leukoderma","Post inflammatory hypomelanosis","Piebaldism"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1654, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 113, '{"id":1654,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":113,"q":"Most common pattern of onychomycosis is?","o":["Distal and lateral subungual","Proximal subungual","White superficial","Total dystrophic"],"a":0,"e":"Ans. A. Distal and lateral subungual [Ref IADVL 3fli/e p. 266] Distal and lateral subungual: DSO is the most common form (90%) of onychomycosis. Characterized by invasion of the nail bed and underside of the nail plate beginning at the hyponychium and migrates proximally through the underlying nail matrix DSO is usually caused by the dermatophyte T. rubrum. Infection of the toenails being much more common than infection of the fingernails","pyqMatches":[{"year":"2016","no":1668,"q":"Most common pattern of onychomycosis is?","o":["Distal and lateral subungual","Proximal subungual","White superficial","Total dystrophic"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1655, 'Dermatology', 'Miscellaneous', 'Moderate', 'Skin', 114, '{"id":1655,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Skin","sourceNo":114,"q":"Which of the following is not a feature of dermatomyositis?","o":["''V'' sign","Holster sign","Pokiloderma","Groove sign"],"a":3,"e":"Ans. D. Groove sign [Ref: Rooks 7th/e p. 127-38; IADVL 3''/e p. 1236] Groove sign (a depression along the course of a vein or between muscle groups) is seen in deep morphea. Cutaneous signs od dermatomyositis","pyqMatches":[{"year":"2016","no":1669,"q":"Which of the following is not a feature of dermatomyositis?","o":["''V'' sign","Holster sign","Pokiloderma","Groove sign"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1656, 'Dermatology', 'Dermatology Basics', 'Moderate', 'Skin', 115, '{"id":1656,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Moderate","source":"Skin","sourceNo":115,"q":"Not a feature of candidal intertrigo is?","o":["Obesity is a risk factor","C. albicans is the most common causative species","Central scaling","Satellite lesions"],"a":2,"e":"Ans. C. Central scaling [Ref Neena Khanna''s 4th/e p. 294] Candidal intertrigo Infection of skin folds is called candidal intertrigo. It is characterized by reddened (erythematous) plaques, with satellite pustules (peripheral pustules). There may be fine scales at periphery. Over the regions covered with thick stratum corneum, i.e., toe webs and Finger webs, the lesion appear as moist, white colored plaques. Virtually any body fold may be affected. Groins, axillae, submammary folds in females, toes & finger webs are common sites of affection. Lesions persisting for a long time lead to the development of superficial painful erosions that take a longer period to heal. This is called \"erythema of lacquer.","pyqMatches":[{"year":"2016","no":1670,"q":"Not a feature of candidal intertrigo is?","o":["Obesity is a risk factor","C. albicans is the most common causative species","Central scaling","Satellite lesions"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1657, 'Dermatology', 'Skin Tumors', 'Hard', 'Skin', 116, '{"id":1657,"subject":"Dermatology","chapter":"Skin Tumors","difficulty":"Hard","source":"Skin","sourceNo":116,"q":"Nevus simplex commonly presents at ?","o":["Face","Trunk","Legs","Hand"],"a":0,"e":"Ans. A. Face [Ref IADVL 3rdie p. 201] Nevus simplex (Nevus flammeus nuchae/stork bite/ Salmon patch) It is a congenital capillary malformation presents in 30 percent of newborn babies. A stork bite is due to dilation of blood vessels and may become darker when the child cries or strains. They are most common on the forehead, eyelids, upper lip, between the eyebrows, and the back of the neck, these marks fade as the infant grows.","pyqMatches":[{"year":"2016","no":1700,"q":"Nevus simplex commonly presents at ?","o":["Face","Trunk","Legs","Hand"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1658, 'Dermatology', 'Papulosquamous Disorders', 'Moderate', 'Skin', 117, '{"id":1658,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Moderate","source":"Skin","sourceNo":117,"q":"Scaling is not feature of which of the following?","o":["Tinea","Lichen planus","Herpes zoster","Reiter''s disease"],"a":2,"e":"Ans. C. Herpes zoster [Ref Beh110th/e p. 254-268; Neena Khanna 3\"Ye p. 37] In herpes there is crusting but no scaling. Papulo-squamous disorders have following two characteristics : - Papule (solid elevated skin lesion < 1 cms) or plaques (solid elevated lesion > 1 cm). ii) Scales (visible exfoliation of the skin which represnts visible shedding of skin). \"Papulosquamous disorders manifest papules surmounted by scales\".","pyqMatches":[{"year":"2016","no":1671,"q":"Scaling is not feature of which of the following?","o":["Tinea","Lichen planus","Herpes zoster","Reiter''s disease"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1659, 'Dermatology', 'Papulosquamous Disorders', 'Hard', 'Skin', 118, '{"id":1659,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Hard","source":"Skin","sourceNo":118,"q":"A 40 years old male patient presents with multiple erythematous annular lesions with peripheral scales arranged predominantly on trunk. Treatment of choice is?","o":["Topical steroids","Systemic steroids","Systemic Azathioprine","Topical antifungal"],"a":0,"e":"Ans. A. Topical steroids [Ref: Beh110`Ve p. 263] Pityriasis rubra pilaris Clinical presentation of the patient in question suggests the diagnosis of PRP for which treatment of choice is topical steroids and salicylic acid. Treatment Localized lesions - Topical corticosteroids + Keratolytics (Salicylic acid, urea) Erythroderma - Vitamin A, Acitretin (Retinoids), oral methotrexate.","pyqMatches":[{"year":"2016","no":1672,"q":"A 40 years old male patient presents with multiple erythematous annular lesions with peripheral scales arranged predominantly on trunk. Treatment of choice is?","o":["Topical steroids","Systemic steroids","Systemic Azathioprine","Topical antifungal"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1660, 'Dermatology', 'Papulosquamous Disorders', 'Easy', 'Skin', 119, '{"id":1660,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Easy","source":"Skin","sourceNo":119,"q":"Woronoff''s ring is a feature of?","o":["Psoriasis","Lichen planus","Pityriasis rosea","Pemphigus"],"a":0,"e":"Ans. A. Psoriasis [Ref Rooks 7\"Ve p. 35.1-35.63] Clinical features of Psoriasis (psoriasis vulgaris) Psoriasis occurs at all ages, most patients are young or middle aged adults. The typical lesion is nummular round plaque which has following characteristic features: Well defined Profuse, silvery white, powdery scales (Candle drop scales) - Losely adherent and easily drops. Bright red erythmatous base. Plaque is often surrounded by a hypopigmented halo Ring of Woronoff.","pyqMatches":[{"year":"2016","no":1673,"q":"Woronoff''s ring is a feature of?","o":["Psoriasis","Lichen planus","Pityriasis rosea","Pemphigus"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1661, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 120, '{"id":1661,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":120,"q":"True about erythema toxicum is?","o":["Common in pre-term baby","Lesions contain many lymphocytes","Can be life threatening condition","Occurs mainly in neonatal period"],"a":3,"e":"Ans. D. Occurs mainly in neonatal period [Ref IADVL .3rd le p. 163] * Erythema toxicum neonatorum (ETN/baby acne/toxic erythema of the newborn) - It is a benign, asymptomatic skin condition that is characterized by small, erythematous papules, vesicles, and, occasionally, pustules. - The lesions are usually surrounded by a distinctive diffuse, blotchy, erythematous halo - It is more common in babies born at full term (between 37 and 40 weeks of gestation) compared with premature babies. - Only occurs during the neonatal period, usually between day 2-5 after birth and typically resolves within first two weeks of life. - The fluid from erythema toxicum lesions will show many eosinophils","pyqMatches":[{"year":"2016","no":1699,"q":"True about erythema toxicum is?","o":["Common in pre-term baby","Lesions contain many lymphocytes","Can be life threatening condition","Occurs mainly in neonatal period"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1662, 'Dermatology', 'Infections & Infestations', 'Easy', 'Skin', 121, '{"id":1662,"subject":"Dermatology","chapter":"Infections & Infestations","difficulty":"Easy","source":"Skin","sourceNo":121,"q":"Most important factor in causation of Ingrown toe nail is?","o":["Fungal infection","Ill fitting shoes","Genetic predisposition","Nutritional deficiency"],"a":1,"e":"Ans. B. Ill fitting shoes Ill-fitting shoes: Ingrown toenail(unguis incarnates/ onychocryptosis) It is a common painful condition in which the nail grows so that it cuts into one or both sides of the paronychium or nail bed. While ingrown nails can occur in the nails of both the hands and the feet, they occur most commonly with the toenails. Presents with pain, tenderness, redness and swelling along one or both sides of the affected nail.","pyqMatches":[{"year":"2016","no":1674,"q":"Most important factor in causation of Ingrown toe nail is?","o":["Fungal infection","Ill fitting shoes","Genetic predisposition","Nutritional deficiency"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1663, 'Dermatology', 'Pigmentary Disorders', 'Easy', 'Skin', 122, '{"id":1663,"subject":"Dermatology","chapter":"Pigmentary Disorders","difficulty":"Easy","source":"Skin","sourceNo":122,"q":"Which of the following is true about xeroderma pigmentosa?","o":["Autosomal dominant","Good long term prognosis","Purine dimmers","DNA repair defect"],"a":3,"e":"Ans. D. DNA repair defect [Ref Rook''s 4thie p. 78.12] Xeroderma pigmentosa Molecular defect: Exposure to UV rays damages DNA due to production of convalent linkages between adjacent pyrimidines (pyrimidine dimmers). Normally the damaged DNA is repaired by excision and repair. In xeroderma pigmentosa the repair of UV damaged DNA is defective. It is an autosomal recessive disorder.","pyqMatches":[{"year":"2016","no":1698,"q":"Which of the following is true about xeroderma pigmentosa?","o":["Autosomal dominant","Good long term prognosis","Purine dimmers","DNA repair defect"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1664, 'Dermatology', 'Papulosquamous Disorders', 'Moderate', 'Skin', 123, '{"id":1664,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Moderate","source":"Skin","sourceNo":123,"q":"Which of the following is not a feature of lichen planus?","o":["Pterygium","Spontaneous healing","Scarring alopecia","Not premalignant"],"a":3,"e":"Ans. D. Not premalignant [Ref Behl/e p. 265; Rooks 7th /e p. 5.13] Very rarely chronic ulcerative lesions may develop malignant changes, i.e., squamous cell carcinoma. Clinical features of lichen planus.","pyqMatches":[{"year":"2016","no":1675,"q":"Which of the following is not a feature of lichen planus?","o":["Pterygium","Spontaneous healing","Scarring alopecia","Not premalignant"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1665, 'Dermatology', 'Eczemas & Dermatitis', 'Easy', 'Skin', 124, '{"id":1665,"subject":"Dermatology","chapter":"Eczemas & Dermatitis","difficulty":"Easy","source":"Skin","sourceNo":124,"q":"Most common metal responsible for contact dermatitis is ?","o":["Gold","Silver","Nickel","Mercury"],"a":2,"e":"Ans. C. Nickel [Ref Andrew''s diseases of skin E-book p 99 & IADVL 3rd/e p. 559] Contact dermatitis is mainly of two types : A. Irritant contact dermatitis Due to direct irritant action of the material e.g. Solvents, Alkalis, Detergents. Most common sites are hands & forearms. B. Allergic contact dermatitis It is due to delayed hypersensitivity (type IV hypersensitivity) to a particular antigen in a sensitized individual. The most common allergens causing allergic contact dermatitis are pollen and metals:","pyqMatches":[{"year":"2016","no":1697,"q":"Most common metal responsible for contact dermatitis is ?","o":["Gold","Silver","Nickel","Mercury"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1666, 'Dermatology', 'Infections & Infestations', 'Moderate', 'Skin', 125, '{"id":1666,"subject":"Dermatology","chapter":"Infections & Infestations","difficulty":"Moderate","source":"Skin","sourceNo":125,"q":"Which of the following is not true for scabies?","o":["Wrist is common site in children","Burrows are intradermal lesions","Papules and pustules are due to hypersensitivity to mite","Itching generalized"],"a":1,"e":"Ans. B. Burrows are intradermal lesions [Ref Behl 10th/e p. 179] Burrow is the serpentine (S-shaped), thread like gray-brown line which represent the intraepidermal tunnel created by the moving female mite in stratum corneum. Burrow is Pathognomic of scabies. Burrows are difficult to demonstrate in infant. Clinical features of scabies","pyqMatches":[{"year":"2016","no":1676,"q":"Which of the following is not true for scabies?","o":["Wrist is common site in children","Burrows are intradermal lesions","Papules and pustules are due to hypersensitivity to mite","Itching generalized"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1667, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 126, '{"id":1667,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":126,"q":"Treatment of choice for oral candidiasis is?","o":["Terbinafin","Nystatin","Griesofulvin","Selenium sulphide"],"a":1,"e":"Ans. B. Nystatin [Ref IADVL 3rdle p 283] Treatment of cutaneous candidiasis Topical (TOC for uncomplicated cases): - nystatin suspension, clotrimazole troches, gention violet, chlorhexidine, ketoocnazole, amphotericin gel. Systemic (reinfection, unresponsive & chronic cases): - oral fluconazole, itraconazole or ketoconazole are needed.","pyqMatches":[{"year":"2016","no":1696,"q":"Treatment of choice for oral candidiasis is?","o":["Terbinafin","Nystatin","Griesofulvin","Selenium sulphide"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1668, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 127, '{"id":1668,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":127,"q":"Scabies is caused by?","o":["Mite","Tic","Virus","Fungus"],"a":0,"e":"Ans. A. Mite [Ref Behl 10thie p. 179] Scabies is an intensly pruritic skin infestation caused by Sarcoptes scabiei, an acarus (mite). Scabies usually affects children but can occur at any age. More common in low socioeconomic strata as overcrowding and poor hygiene facilitate transmission. The most important means of transmission is via direct contact with an infected individual. Scabes is a water washed disease which occurs due to inadequate use of water or improper hygiene.","pyqMatches":[{"year":"2016","no":1677,"q":"Scabies is caused by?","o":["Mite","Tic","Virus","Fungus"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1669, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 128, '{"id":1669,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":128,"q":"Volcano sign is seen in?","o":["Leprosy","Leishmaniasis","Lupus vulgaris","DLE"],"a":1,"e":"Ans. B. Leishmaniasis [Ref Indian Dermatol Online J. 2012 Sep-Dec; 3(3): 159-165.doi: 10.4103/2229-5178.101810] Volcano sign: Descriptive term for the morphologic feature of Old World cutaneous leishmaniasis. The lesion starts as a small nontender papule, which enlarges in size and ulcerates in the centre. The border of the crusted ulcer often has an erythematous rim and is called as \"Volcano sign\".","pyqMatches":[{"year":"2016","no":1695,"q":"Volcano sign is seen in?","o":["Leprosy","Leishmaniasis","Lupus vulgaris","DLE"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1670, 'Dermatology', 'Infections & Infestations', 'Easy', 'Skin', 129, '{"id":1670,"subject":"Dermatology","chapter":"Infections & Infestations","difficulty":"Easy","source":"Skin","sourceNo":129,"q":"Selenium sulphide is used in the treatment of?","o":["Scabies","T. versicolor","T. cruris","Cutaneous leishmaniasis"],"a":1,"e":"Ans. B. T. versicolor [Ref Harrison 17th/e p. 318] Selenium sulphide (2.5%) in detergent base is applied all over body below neck (sparing the genitalia), left overnight and washed of next morning. Two to three applications applied once or twice a week usually clears the infection. Treatment of P. versicolor","pyqMatches":[{"year":"2016","no":1678,"q":"Selenium sulphide is used in the treatment of?","o":["Scabies","T. versicolor","T. cruris","Cutaneous leishmaniasis"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1671, 'Dermatology', 'Skin Tumors', 'Easy', 'Skin', 130, '{"id":1671,"subject":"Dermatology","chapter":"Skin Tumors","difficulty":"Easy","source":"Skin","sourceNo":130,"q":"First generation topical retinoid is?","o":["Retinoic acid","Adapalene","Tazarotene","Acitretin"],"a":0,"e":"Ans. A. Retinoic acid [Ref Comprehensive dermatological drug therapy p. 254 & internet] Retinoids The retinoids comprise a class of chemical compounds that are vitamers of vitamin A or are chemically related to it. Retinoids have found use in medicine where they regulate epithelial cell growth. Retinoids have many important functions throughout the body including roles in vision, regulation of cell proliferation and differentiation, growth of bone tissue, immune function, and activation of tumor suppressor genes.","pyqMatches":[{"year":"2016","no":1679,"q":"First generation topical retinoid is?","o":["Retinoic acid","Adapalene","Tazarotene","Acitretin"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1672, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 131, '{"id":1672,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":131,"q":"Most common type of cutaneous mastocytosis is?","o":["Solitary mastocytoma","Urticaria pigmentosa","Telangiectasia macularis eruptiva perstans","Diffuse erythrodermic"],"a":1,"e":"Ans. B. Urticaria pigmentosa [Ref IADVL text book of dermatology 3rde p. 146 Urticaria pigmentosa: (Generalized eruption of cutaneous mastocytosis (childhood type). It is the most common form of cutaneous mastocytosis. Urticaria pigmentosa is most common in children. It can also occur in adults. It is a familial cutaneous disorder characterised by generalised distribution of red brown macules. Each lesion represents a collection of mast cells in the dermis with hyperpigmentation of overlying epidermis. The most characteristic features is that these lesions urticate on scratching.","pyqMatches":[{"year":"2016","no":1694,"q":"Most common type of cutaneous mastocytosis is?","o":["Solitary mastocytoma","Urticaria pigmentosa","Telangiectasia macularis eruptiva perstans","Diffuse erythrodermic"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1673, 'Dermatology', 'Autoimmune Blistering Disorders', 'Moderate', 'Skin', 132, '{"id":1673,"subject":"Dermatology","chapter":"Autoimmune Blistering Disorders","difficulty":"Moderate","source":"Skin","sourceNo":132,"q":"Treatment for impetigo includes all except?","o":["Topical mupirocin","Systemic erythromycin","Topical gentamycin","Systemic cephalosporins"],"a":2,"e":"Ans. C. Topical gentamycin [Ref IADVL 3rd/e p. 235] * \"Topical use of gentamycin should be avoided as gentamycin resistance can develop and it can be transferred between different species and strains of staphylococcus.\" Treatment of impetigo * Impetigo contagiosum - Localized 4 Topical antibiotics like fusidic acid or mupirocin - Extensive - Systemic antibiotics (erythromycin group to cover staphylococcus and streptococcus). - If response is poor, oxacillin-Clavulanic acid or cephalexin can be tried. Bullous Impetigo * Localized→ Topical fusidic acid or mupirocin * Extensive 4 Systemic antistaphylococcal antibiotics (flucloxacillin, amoxicillin- clavulanic acid, methicillin or erythromycin)","pyqMatches":[{"year":"2016","no":1680,"q":"Treatment for impetigo includes all except?","o":["Topical mupirocin","Systemic erythromycin","Topical gentamycin","Systemic cephalosporins"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1674, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 133, '{"id":1674,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":133,"q":"False about Langer''s lines is?","o":["Remain constant throughout life time of a person","Correspond to the collagen fibers in dermis","Incision along these lines produces better scar","Skin along these lines is least flexible"],"a":0,"e":"Ans. A. Remain constant throughout life time of a person [Ref: IADVL text book of dermatology 3rd le p. 175 & Internet] Langer''s lines Also called cleavage lines, is a term used to define the direction within the human skin along which the skin has the least flexibility. These lines correspond to the alignment of collagen fibers within the dermis. Usually, a surgical cut is carried out in the direction of langer''s lines, and incisions made parallel to langer''s lines generally heal better and produce less scarring. Directional changes of Langer''s lines have been known to occur within the course of a person''s lifetime. Sometimes the exact direction of these lines are unknown, because in some regions of the body there are differences between different individuals.","pyqMatches":[{"year":"2016","no":1693,"q":"False about Langer''s lines is?","o":["Remain constant throughout life time of a person","Correspond to the collagen fibers in dermis","Incision along these lines produces better scar","Skin along these lines is least flexible"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1675, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 134, '{"id":1675,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":134,"q":"Jock itch is caused by?","o":["Epidermophyton floccosum","Candida albicans","Trichophyton tonsurans","Malassezia furfur"],"a":0,"e":"Ans. A. Epidermophyton floccosum [Ref Neena Khanna 3rd/e p. 242-244] Tinea cruris (Jock itch): It is also known as Dhobi''s itch. Tinea crusis is dermatophytic infection of the groin and adjacent skin. The classical appearance of tinea cruris is red (erythematous) scaly lesion with clear centre. Margins are well defined with raised borders. Itching is very prominent. The most common sites of involvement are genital area and medial aspect of upper thigh (Most common site of dermatophytosis in males). T cruris usually affect young adult male. In India trichophyton rubrum is the most common cause and in western countries epidermophyton floccosum is the most common cause.","pyqMatches":[{"year":"2016","no":1681,"q":"Jock itch is caused by?","o":["Epidermophyton floccosum","Candida albicans","Trichophyton tonsurans","Malassezia furfur"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1676, 'Dermatology', 'Papulosquamous Disorders', 'Easy', 'Skin', 135, '{"id":1676,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Easy","source":"Skin","sourceNo":135,"q":"Resorcinol is used in the treatment of?","o":["Lichen planus","Acne","Vitiligo","Scabies"],"a":1,"e":"Ans. B. Acne [Ref Contact and occupational dermatology p. 195] Resorcinol is included in many antiseptic and keratolytic topical medications. Uses include psoriasis, hidradenitis suppurativa, eczema, acne, seborrhea, corns, calluses, warts, and other skin disorders.","pyqMatches":[{"year":"2016","no":1682,"q":"Resorcinol is used in the treatment of?","o":["Lichen planus","Acne","Vitiligo","Scabies"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1677, 'Dermatology', 'Papulosquamous Disorders', 'Easy', 'Skin', 136, '{"id":1677,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Easy","source":"Skin","sourceNo":136,"q":"Multiple psoriatic lesions on hands. Treatment of choice is?","o":["NBUVB","Systemic methotrexate","Topical steroids and salicylic acid","Systemic steroids"],"a":2,"e":"Ans. C. Topical steroids and salicylic acid [Ref Neena Khanna 3rd le p. 46] Preferred treatment for localized psoriasis is topical coal tar or short contact, dithroanol. Alternative is topical steroids + Salicylic acid.","pyqMatches":[{"year":"2016","no":1692,"q":"Multiple psoriatic lesions on hands. Treatment of choice is?","o":["NBUVB","Systemic methotrexate","Topical steroids and salicylic acid","Systemic steroids"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1678, 'Dermatology', 'Papulosquamous Disorders', 'Easy', 'Skin', 137, '{"id":1678,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Easy","source":"Skin","sourceNo":137,"q":"Hertoghe''s sign is seen in?","o":["Atopic dermatitis","Cutaneous TB","Lichen planus","Psoriasis"],"a":0,"e":"Ans. A. Atopic dermatitis [Ref Indian Dermatol Online J. 2012 Sep-Dec; 3(3): 159-165.doi: 10.4103/2229-5178.101810] The Sign of Hertoghe or Queen Anne''s sign is a thinning or loss of the outer third of the eyebrows (superciliary madarosis). It is a classical sign of hypothyroidism or atopic dermatitis. It can also be seen in leprosy, myxedema, follicular mucinosis, trichotillomania, ectodermal dysplasia, discoid lupus erythematosus, alopecia areata, syphilis, ulerythema ophryogenes, systemic sclerosis and HIV infection.","pyqMatches":[{"year":"2016","no":1683,"q":"Hertoghe''s sign is seen in?","o":["Atopic dermatitis","Cutaneous TB","Lichen planus","Psoriasis"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1679, 'Dermatology', 'Papulosquamous Disorders', 'Easy', 'Skin', 138, '{"id":1679,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Easy","source":"Skin","sourceNo":138,"q":"Treatment of choice for erytherodermic psoriasis is?","o":["Prednisolone","Hydroxyurea","Acitretin","Ciclosporin"],"a":2,"e":"Ans. C. Acitretin [Ref: Neena Khanna 3rdle p. 46] Methotrexate is the DOC for Erythrodermic psoriasis. Acitretin is an alternative.","pyqMatches":[{"year":"2016","no":1691,"q":"Treatment of choice for erytherodermic psoriasis is?","o":["Prednisolone","Hydroxyurea","Acitretin","Ciclosporin"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1680, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 139, '{"id":1680,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":139,"q":"Preferred concentration of minoxidil for female androgenetic alopecia is?","o":["2%","5%","8%","10%"],"a":0,"e":"Ans. A. 2% [Ref IADVL 3''/e p. 891] In female androgenic alopecia results are similar with 2% and 5% minoxidil but side effects are more with 5% solution. Whereas in males 5% is more efficacious. Therefore in a female patient 2% minoxidil is preferred whereas in males 5% solution is the preferred choice.","pyqMatches":[{"year":"2016","no":1684,"q":"Preferred concentration of minoxidil for female androgenetic alopecia is?","o":["2%","5%","8%","10%"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1681, 'Dermatology', 'Infections & Infestations', 'Easy', 'Skin', 140, '{"id":1681,"subject":"Dermatology","chapter":"Infections & Infestations","difficulty":"Easy","source":"Skin","sourceNo":140,"q":"Normal epidermal turnover time is?","o":["1 week","2 weeks","3 weeks","4 weeks"],"a":2,"e":"Ans. C. 3 weeks [Ref: Neena Khanna 3rd le p. 297; Roxburgh''s 7th/e p. 62] Treatment of scabies in children Topical permethrin (5% cream) is a safe and effective scabicide in children. It is recommended as a first-line therapy for patients older than 2 months of age. Because there are theoretical concerns regarding percutaneous absorption of permethrin in infants younger than 2 months of age, guidelines recommend 7% sulfur preparation instead of permethrin.","pyqMatches":[{"year":"2016","no":1685,"q":"Normal epidermal turnover time is?","o":["1 week","2 weeks","3 weeks","4 weeks"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1682, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 141, '{"id":1682,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":141,"q":"Alopecia universalis is?","o":["Loss of all the scalp hair","Loss of all body hair","Loss hair at the scalp margin","Male pattern hair loss"],"a":1,"e":"Ans. B. Loss of all body hair [Ref Fitzpatrick] In alopecia aerata, when there is total loss of scalp hair it is called Alopecia totalis. When there is loss of total body hair it is referred as Alopecia universalis. Alopecia along the scalp margin is called ophiasis. An inverse ophiasis pattern (sisaphio) is when it spares occipital region and affects rest of the scalp.","pyqMatches":[{"year":"2016","no":1690,"q":"Alopecia universalis is?","o":["Loss of all the scalp hair","Loss of all body hair","Loss hair at the scalp margin","Male pattern hair loss"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1683, 'Dermatology', 'Infections & Infestations', 'Easy', 'Skin', 142, '{"id":1683,"subject":"Dermatology","chapter":"Infections & Infestations","difficulty":"Easy","source":"Skin","sourceNo":142,"q":"Treatment of choice for scabies in an infant < 6 months is?","o":["BHC","Ivermactin","Permathrin","Crotomiton"],"a":3,"e":"Ans. D. Crotomiton [Ref: Neena Khanna 3rdle p. 297] Ivermectin is the only oral drug, available for scabies treatment.","pyqMatches":[{"year":"2016","no":1686,"q":"Treatment of choice for scabies in an infant < 6 months is?","o":["BHC","Ivermactin","Permathrin","Crotomiton"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1684, 'Dermatology', 'Dermatology Basics', 'Hard', 'Skin', 143, '{"id":1684,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Hard","source":"Skin","sourceNo":143,"q":"A known case of diabetes develops annular orange skin lesions, which disappear after biopsy. This phenomenon is known as?","o":["Koebner''s phenomenon","Reverse Koebner''s phenomenon","Asboe Henson sign","Isotopic phenomenon"],"a":1,"e":"Ans. B. Reverse Koebner''s phenomenon [Ref https://www.researchgate.net/publication/268343496_Proposed_ classification_for_koebner_wolf isotopic_renbok_koebner_nonreaction_isotopic_nonreaction_other_rela Annular orange skin lesions in a diabetic indicate towards granuloma annulare. There have been few reports of disappearance of lesions after biopsy in granuloma annulare. This phenomenon is known as reverse Koebner''s phenomenon.","pyqMatches":[{"year":"2016","no":1689,"q":"A known case of diabetes develops annular orange skin lesions, which disappear after biopsy. This phenomenon is known as?","o":["Koebner''s phenomenon","Reverse Koebner''s phenomenon","Asboe Henson sign","Isotopic phenomenon"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1685, 'Dermatology', 'Papulosquamous Disorders', 'Easy', 'Skin', 144, '{"id":1685,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Easy","source":"Skin","sourceNo":144,"q":"Oral treatment of choice for scabies is?","o":["Albendazole","Itraconazole","Sulphur","Ivermactin"],"a":3,"e":"Ans. D. Ivermactin [Ref Behl 10th/e p. 406; Neena Khanna 3rd/e p. 50, 51] Pityriasis rosea: P. rosea is self limiting disease, subsides with 6-12 weeks. P. rosea is a common scaly disorder, occuring usually in children and young adults (10-35 years). Characterized by round/oval pink brown patches with a superficial, centrifugal scale, distributed over trunk in a Christmas tree pattern. The exact etiology is not known, but it is considered to be a viral disease; Human Herpes virus 6 (HHV 6) and Human Herpes virus 7 (HHV 7) may play a role.","pyqMatches":[{"year":"2016","no":1687,"q":"Oral treatment of choice for scabies is?","o":["Albendazole","Itraconazole","Sulphur","Ivermactin"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1686, 'Dermatology', 'Papulosquamous Disorders', 'Easy', 'Skin', 145, '{"id":1686,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Easy","source":"Skin","sourceNo":145,"q":"Pityriasis rosea clears with in?","o":["1-2 weeks","2-4 weeks","4-8 weeks","6-12 weeks"],"a":1,"e":"Ans. B. 2-4 weeks [Ref Behl 10th/e p. 406; Neena Khanna 3rd/e p. 50, 51] Pityriasis rosea: P. rosea is self limiting disease, subsides with 6-12 weeks. P. rosea is a common scaly disorder, occuring usually in children and young adults (10-35 years). Characterized by round/oval pink brown patches with a superficial, centrifugal scale, distributed over trunk in a Christmas tree pattern. The exact etiology is not known, but it is considered to be a viral disease; Human Herpes virus 6 (HHV 6) and Human Herpes virus 7 (HHV 7) may play a role. Clinical manifestations of P. rosea: The disease starts with an upper respiratory prodrome or a mild flu. After 1-2 weeks, annular erythematous plaque appears on trunk that is referred to as mother patch or herald patch. Over the next 1-2 weeks, fresh patch appear all over the trunk, in a Christmas tree configuration or Fir tree Configuration.","pyqMatches":[{"year":"2016","no":1688,"q":"Pityriasis rosea clears with in?","o":["1-2 weeks","2-4 weeks","4-8 weeks","6-12 weeks"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1687, 'Dermatology', 'Miscellaneous', 'Moderate', 'Skin', 146, '{"id":1687,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Skin","sourceNo":146,"q":"Periungual desquamation, which is a characteristic feature of Kawasaki syndrome, occurs at ?","o":["1st-2nd week","2nd-3rd week","3rd-4th week","4th_5th week"],"a":1,"e":"Ans. B. 2nd-3rd week Periungualdesequamation in kawasaki disease starts between 10-18 days.","pyqMatches":[{"year":"2015","no":1608,"q":"Periungual desquamation, which is a characteristic feature of Kawasaki syndrome, occurs at ?","o":["1st-2nd week","2nd-3rd week","3rd-4th week","4th_5th week"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1688, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 147, '{"id":1688,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":147,"q":"True about Keratinocyte is ?","o":["Ectoderm derived cell","Present only in basal layer","Mature in basal layer","Differentiate in basal layer"],"a":0,"e":"Ans. A. Ectoderm derived cell The principal cells of epidermis are keratinocytes. Keratin filament is the hallmark of keratinocytes. Keratinocytes has following features:","pyqMatches":[{"year":"2015","no":1579,"q":"True about Keratinocyte is ?","o":["Ectoderm derived cell","Present only in basal layer","Mature in basal layer","Differentiate in basal layer"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1689, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 148, '{"id":1689,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":148,"q":"Odland bodies are seen in which layer of epidermis?","o":["Basal cell layer","Prickle cell layer","Stratum granulosum","Stratum corneum"],"a":2,"e":"Ans. C. Stratum granulosum Odland bodies are membrane coated granules in stratum granulosum, which contain lipids which is responsible for barrier function of this layer. This layer also contains diamond shaped keratohyaline granules, which are the characteristic features of this layer. These keratohyaline granules contain filaggrin protein which is responsible for aggregation of keratin filaments.","pyqMatches":[{"year":"2015","no":1580,"q":"Odland bodies are seen in which layer of epidermis?","o":["Basal cell layer","Prickle cell layer","Stratum granulosum","Stratum corneum"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1690, 'Dermatology', 'Autoimmune Blistering Disorders', 'Easy', 'Skin', 149, '{"id":1690,"subject":"Dermatology","chapter":"Autoimmune Blistering Disorders","difficulty":"Easy","source":"Skin","sourceNo":149,"q":"Which of the following drug can lead to pemphigus?","o":["Penicillamine","Isoniazid","Carbamazepine","Furosemide"],"a":0,"e":"Ans. A. Penicillamine Drugs causing pemphigus- Penicillamine Penicillins and Cefalosporins Captopril, Iodine, Lithium Phenophthelin, Propanolol Rifampicine Phenytoin, Phenylbutazone, Salicylates, Piroxicam, Sulphonamides","pyqMatches":[{"year":"2015","no":1607,"q":"Which of the following drug can lead to pemphigus?","o":["Penicillamine","Isoniazid","Carbamazepine","Furosemide"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1691, 'Dermatology', 'Papulosquamous Disorders', 'Easy', 'Skin', 150, '{"id":1691,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Easy","source":"Skin","sourceNo":150,"q":"In which of the following phototherapy is useful in treatment ?","o":["Psoriasis","Tinea corporis","Pemphigus","PMLE"],"a":0,"e":"Ans. A. Psoriasis lndications for PUVA and UVB","pyqMatches":[{"year":"2015","no":1583,"q":"In which of the following phototherapy is useful in treatment ?","o":["Psoriasis","Tinea corporis","Pemphigus","PMLE"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1692, 'Dermatology', 'Papulosquamous Disorders', 'Moderate', 'Skin', 151, '{"id":1692,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Moderate","source":"Skin","sourceNo":151,"q":"All are true about actinic lichen planus except ?","o":["Associated with severe pruritus","Autoimmune etiology","Voilaceous brown papules","Usually affects exposed areas of body"],"a":0,"e":"Ans. A. Associated with severe pruritus Actinic Lichen Planus (lichen planussubtropicus/tropicus / lichen planusactinicus) Lichen planus is an autoimmune disease. Common in spring and summers in tropical countries. Usually affects children and young adults Sunlight is considered to be the predisposing factor therefore lesions are more common on sun exposed areas (face, dorsum ofhand, forearms and arms, nape of the neck). Papules are hyperpigmented with voilaceous-brown with well- definedhypopigmented border. Pruritrus and scaling are minimal.","pyqMatches":[{"year":"2015","no":1605,"q":"All are true about actinic lichen planus except ?","o":["Associated with severe pruritus","Autoimmune etiology","Voilaceous brown papules","Usually affects exposed areas of body"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1693, 'Dermatology', 'Dermatology Basics', 'Moderate', 'Skin', 152, '{"id":1693,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Moderate","source":"Skin","sourceNo":152,"q":"Acanthosis nigricans is characterized by all of the following except ?","o":["Common in obese people","Associated with thick skin with hyperpigmentaion","Histologically there is hypermelanosis","May be a sign of internal malignancy"],"a":2,"e":"Ans. C. Histologically there is hypermelanosis Acanthosis nigricans is brown to black discolouration which usually affects body folds like axilla, groin, umblicus, forehead. Acanthosis nigricans occurs in individuals younger than 40 years of age. It is associated with obesity (most common); endocrinopathy like insulin resistance DM, hypothyroidism, Bloom synd., PCOD, and internal malignancy e.g. gastric adenocarcinoma. Histopathologically, Papillomatosis is the characteristic feature whereas there is no hypermelanosis.n","pyqMatches":[{"year":"2015","no":1584,"q":"Acanthosis nigricans is characterized by all of the following except ?","o":["Common in obese people","Associated with thick skin with hyperpigmentaion","Histologically there is hypermelanosis","May be a sign of internal malignancy"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1694, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 153, '{"id":1694,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":153,"q":"Which of the following is characterized by a solitary painless ulcer on genitalia?","o":["Herpes","Soft chancre [chancroid]","Hard chancre","Traumatic ulcer"],"a":2,"e":"Ans. C. Hard Chancre Characteristics of various different types of genital ulcers - Primary syphilis (hard chancre) :- punched out, painless, non- bleeding(avascular) ulcer with 6rm induration. Donovanosis :- one or more, painless, bleeding (vascular) ulcers with induration. Chancroid (soft chancre):- multiple, painful, bleeding (vascular)ulcers with no or soft induration. LGV: - single, painless, non-bleeding ulcer. Herpes genitalis: - multiple painful/asymptomatic ulcers.","pyqMatches":[{"year":"2015","no":1603,"q":"Which of the following is characterized by a solitary painless ulcer on genitalia?","o":["Herpes","Soft chancre [chancroid]","Hard chancre","Traumatic ulcer"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1695, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 154, '{"id":1695,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":154,"q":"Epidermal nevus follows ?","o":["Blaschko''s lines","Langer''s lines","Vasculature","Lymphatics"],"a":0,"e":"Ans. A. Blaschko''s lines Blaschko''s lines correspond to the pathways followed by keratinocytes migrating from the neural crest during embryogenesis. Lines of Blaschko represent non-random lines of development of skin. Epidermal nevus follow the Blaschko''s line The skin lesions that follow the Blaschko''s lines are -","pyqMatches":[{"year":"2015","no":1586,"q":"Epidermal nevus follows ?","o":["Blaschko''s lines","Langer''s lines","Vasculature","Lymphatics"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1696, 'Dermatology', 'Eczemas & Dermatitis', 'Easy', 'Skin', 155, '{"id":1696,"subject":"Dermatology","chapter":"Eczemas & Dermatitis","difficulty":"Easy","source":"Skin","sourceNo":155,"q":"Which of the following organism has a role to play in Seborrhic dermatitis ?","o":["Pityrosporum ovale","Canida albicans","Propionibacterium","None of the above"],"a":0,"e":"Ans. A. Pityrosporum ovale Malasezia furfur or its yeast form Pityrosporum ovale plays an etilogicalrole in Seborrhic dermatitis.\"","pyqMatches":[{"year":"2015","no":1587,"q":"Which of the following organism has a role to play in Seborrhic dermatitis ?","o":["Pityrosporum ovale","Canida albicans","Propionibacterium","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1697, 'Dermatology', 'Autoimmune Blistering Disorders', 'Easy', 'Skin', 156, '{"id":1697,"subject":"Dermatology","chapter":"Autoimmune Blistering Disorders","difficulty":"Easy","source":"Skin","sourceNo":156,"q":"Pruritus is a feature of which of the following ?","o":["Pemphigus foliaceous","Pemphigus vulgaris","Bullous Pemphigoid","All of the above"],"a":2,"e":"Ans. C. Bullous Pemphigoid Diseases causing mild or no itching: Psonasis, Pityriasis rosea, SLE, parapsoriasis, Secondary syphilis, Pemphigus. Diseases causing moderate itching: Contact dermatitis, Dry skin, Bullous pemphigoid, Photosensitivity (sunburn). Diseases causing severe itching: Lichen planls, Lichen simplex chronicus, Herpes gestationis, Mastocytosis, Dermatitis herpetiformis, scabies, Prurigo nodularis.","pyqMatches":[{"year":"2015","no":1588,"q":"Pruritus is a feature of which of the following ?","o":["Pemphigus foliaceous","Pemphigus vulgaris","Bullous Pemphigoid","All of the above"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1698, 'Dermatology', 'Papulosquamous Disorders', 'Easy', 'Skin', 157, '{"id":1698,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Easy","source":"Skin","sourceNo":157,"q":"Goekarman regimen used in for treatment of psoriasis is?","o":["UVB plus coal tar","UVB plus anthralin","Coal tar plus anthralin","UVB plus methotrexate"],"a":0,"e":"Ans. A. UVB plus coal tar Goekerman regimen was invented for the treatment of mild to moderate psoriasis. In this therapy application of crude coal tar application for 2-10 hours is followed by exposure to UVB light. Treatment is now obsolete. Similarly UVB plus anthralin combination is known as Ingram regimen.","pyqMatches":[{"year":"2015","no":1589,"q":"Goekarman regimen used in for treatment of psoriasis is?","o":["UVB plus coal tar","UVB plus anthralin","Coal tar plus anthralin","UVB plus methotrexate"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1699, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 158, '{"id":1699,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":158,"q":"True regarding Bowen''s disease is ?","o":["In situ BCC","More common in dark skinned people","HSV infection plays a role","Chronic sun damage plays a role"],"a":3,"e":"Ans. D. Chronic sun damage plays a role Bowen''s Disease Bowen''s disease is SCC in situ. More common in fair skinned people. More common on sun exposed areas such as head & neck followed by limbs. When arises on glans penis, it is called \"erythroplasia of Queytat.\"","pyqMatches":[{"year":"2015","no":1601,"q":"True regarding Bowen''s disease is ?","o":["In situ BCC","More common in dark skinned people","HSV infection plays a role","Chronic sun damage plays a role"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1700, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 159, '{"id":1700,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":159,"q":"Among various types of psoriatic arthrirtis, which variety is most common ?","o":["Classic","Oligoarticular","Rheumatoid","Spondylitis"],"a":1,"e":"Ans. B. Oligoarticular Psoriatic arthritis (Affects 5-1Och of psoriatic patients) Classic or polyarticular type (16%):- affects DIP joints with “sausage shape apearance\"of fingers and toes. Nail involvement is common. Monoarticular or oligoarticular type (70%) most common type, affects large joints like knee. Rheumatoid type (15%) :- RA like presentation. Symmetrical. Affects PIP joints leading to \"swan neck deformity.\" Axial type or spondylitis :- associated with HLA - B27.","pyqMatches":[{"year":"2015","no":1590,"q":"Among various types of psoriatic arthrirtis, which variety is most common ?","o":["Classic","Oligoarticular","Rheumatoid","Spondylitis"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1701, 'Dermatology', 'Infections & Infestations', 'Moderate', 'Skin', 160, '{"id":1701,"subject":"Dermatology","chapter":"Infections & Infestations","difficulty":"Moderate","source":"Skin","sourceNo":160,"q":"All of the followings are part of the treatment of scabies except?","o":["Topical Permathrin","Oral ivermactin","Oral antihistamines","Long term oral steroids"],"a":3,"e":"Ans. D. Long term oral steroids Drugs used in scabies","pyqMatches":[{"year":"2015","no":1599,"q":"All of the followings are part of the treatment of scabies except?","o":["Topical Permathrin","Oral ivermactin","Oral antihistamines","Long term oral steroids"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1702, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 161, '{"id":1702,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":161,"q":"Drug of choice for bubos in a pregnant female is ?","o":["Tetracycline","Doxycycline","Ceftriaxone","Erythromycin"],"a":3,"e":"Ans. D. Erythromycin Buboes are most commonly caused by LGV. Doxycycline/tetracycline is the drug of choice for LGV in a non- pregnant female. In a pregnant female and children below 8 years, it should be treated with erythromycin.","pyqMatches":[{"year":"2015","no":1591,"q":"Drug of choice for bubos in a pregnant female is ?","o":["Tetracycline","Doxycycline","Ceftriaxone","Erythromycin"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1703, 'Dermatology', 'Papulosquamous Disorders', 'Moderate', 'Skin', 162, '{"id":1703,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Moderate","source":"Skin","sourceNo":162,"q":"Which ''P'' is not a feature of lichen planus ?","o":["Polygonal","Polyhedral","Pruritus","Plane"],"a":1,"e":"Ans. B. Polyhedral 5 characteristic ''P’ of lichen planus","pyqMatches":[{"year":"2015","no":1592,"q":"Which ''P'' is not a feature of lichen planus ?","o":["Polygonal","Polyhedral","Pruritus","Plane"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1704, 'Dermatology', 'Papulosquamous Disorders', 'Moderate', 'Skin', 163, '{"id":1704,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Moderate","source":"Skin","sourceNo":163,"q":"In lichen planus all the following sites are affected except ?","o":["Flexor aspect of upper extrimities","Oral mucosa","Nails","Extensor aspect of upper extrimities"],"a":3,"e":"Ans. D. Extensor aspect of upper extrimities Sites of involvement in lichen planus Flexors aspect of upper extremities and legs are the most common site involved. Oral mucosa involvement may lead to lacy pattern of lesions Nail involvement may cause pterygium (most characteristic), onychorrhexia, nail atrophy, anychia. Hair involvement cause scaring alopecia Inverse lichen planus affects axillae, groin, infraaxillary areas.","pyqMatches":[{"year":"2015","no":1593,"q":"In lichen planus all the following sites are affected except ?","o":["Flexor aspect of upper extrimities","Oral mucosa","Nails","Extensor aspect of upper extrimities"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1705, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 164, '{"id":1705,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":164,"q":"Bull''s eye lesions are found in ?","o":["Erythema nodosum","Erythema gangrenosum","Erythema multiforme","Erythroderma"],"a":2,"e":"Ans. C. Erythema Multiforme Clinical features of erythema multiforme Typical lesion of EM is a Target lesion (lris lesion or Bulle''s eye lesion) which consists of three concentric components : -","pyqMatches":[{"year":"2015","no":1598,"q":"Bull''s eye lesions are found in ?","o":["Erythema nodosum","Erythema gangrenosum","Erythema multiforme","Erythroderma"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1706, 'Dermatology', 'Dermatology Basics', 'Moderate', 'Skin', 165, '{"id":1706,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Moderate","source":"Skin","sourceNo":165,"q":"Not a hemorrhagic lesion ?","o":["Petechiae","Echymosis","Plaque","None of the above"],"a":2,"e":"Ans. C. Plaque Petechiae are small pin point purpuric macular lesions that occur due to extravasation of red blood cells from cutaneous vessels into the skin. Echryosis are larger bruise like hemorrhagic lesions. Cause is generally non inflammatory. Plaque is a solid plateau like elevation that occupies a large surface area in comparison to its height above the normal skin and has a diameter more than 0.5 cms. There is no hemorrhage involved as such","pyqMatches":[{"year":"2015","no":1594,"q":"Not a hemorrhagic lesion ?","o":["Petechiae","Echymosis","Plaque","None of the above"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1707, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 166, '{"id":1707,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":166,"q":"Maculae cerulea is seen in ?","o":["Pediculosis hominis corporis","Pediculosis capitis","Scabies","Lupus erythematosus"],"a":0,"e":"Ans. A. Pediculosis hominis corporis Maculae cerulea: This is a latin name for blue-grey macula. Pathognomic of lice infestation (Pediculosis corporis and Pediculosispthiris) They are hemosiderin-stained purpuric spots at the site of insect bite. Enzymes in insect salive breaks down human bilirubin to biliverdin, causing the color change in the skin.","pyqMatches":[{"year":"2015","no":1595,"q":"Maculae cerulea is seen in ?","o":["Pediculosis hominis corporis","Pediculosis capitis","Scabies","Lupus erythematosus"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1708, 'Dermatology', 'Eczemas & Dermatitis', 'Easy', 'Skin', 167, '{"id":1708,"subject":"Dermatology","chapter":"Eczemas & Dermatitis","difficulty":"Easy","source":"Skin","sourceNo":167,"q":"Most common site for atopic dermatitis -","o":["Scalp","Trunk","Popliteal fossa","Knees"],"a":2,"e":"Ans. C. Popliteal fossa Sites of itching patch in atopic dermatitis Infant; Face (especially cheek), extensors offorearm& legs. Childhood & adult > Flexures (antecubitalrbitalfoxa, Poplitealfossa).","pyqMatches":[{"year":"2015","no":1597,"q":"Most common site for atopic dermatitis","o":["Scalp","Trunk","Popliteal fossa","Knees"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1709, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 168, '{"id":1709,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":168,"q":"Incontinentia pigmenti involves all exept ?","o":["Skin","Bones","Teeth","Heart"],"a":3,"e":"Ans. D. Heart Incontinentia pigmenti (also k/a Bloch-Sulzberger syndrome) is a X-linked dominant genetic disorder. It involves Skin (100% of affected people) Teeth (80-90 % of affectedpeople) Bones (30-40% of affected people) CNS i.e. brain & spinal cord (30-40% of affected people) Eyes (25-35% of affected people)","pyqMatches":[{"year":"2015","no":1596,"q":"Incontinentia pigmenti involves all exept ?","o":["Skin","Bones","Teeth","Heart"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1710, 'Dermatology', 'Dermatology Basics', 'Moderate', 'Skin', 169, '{"id":1710,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Moderate","source":"Skin","sourceNo":169,"q":"Not true about Skin tag ?","o":["Associated with seborrhoeic keratosis","Pedunculated","Most common site is neck and axilla","Premalignant"],"a":3,"e":"Ans. D. Premalignant Skin tags (soft warts; achrochordon) A common benign lesion composed of loose fibrous tissue and occurring mainly on the neck and major flexures as a small soft Pedunculated Protrusion. Very common, particularly in women at the menopause or later. They are frequently found together with seborrhoeic keratoses. Treatment: Cautery and cryotherapy","pyqMatches":[{"year":"2012","no":1369,"q":"Not true about Skin tag ?","o":["Associated with seborrhoeic keratosis","Pedunculated","Most common site is neck and axilla","Premalignant"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1711, 'Dermatology', 'Skin Tumors', 'Easy', 'Skin', 170, '{"id":1711,"subject":"Dermatology","chapter":"Skin Tumors","difficulty":"Easy","source":"Skin","sourceNo":170,"q":"Spider telengectacia false is ?","o":["More common in males","Can be caused by trauma","Light therapy for treatment","May be associated with liver disease"],"a":0,"e":"Ans. A. More common in males Spider telangiectasia (arterial spider, spider nevus, nevus aranus) Seen in 2/3rd of pregnant females and usually disappears after delivery. Estrogen is said to be involved in pathogenesis. When multiple, liver disease should be ruled out. Central radiating body with radiating vessels gives a look of spider. Lesion usually over upper half of the body. Treatment by diathermy and excision.","pyqMatches":[{"year":"2012","no":1370,"q":"Spider telengectacia false is ?","o":["More common in males","Can be caused by trauma","Light therapy for treatment","May be associated with liver disease"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1712, 'Dermatology', 'Pigmentary Disorders', 'Easy', 'Skin', 171, '{"id":1712,"subject":"Dermatology","chapter":"Pigmentary Disorders","difficulty":"Easy","source":"Skin","sourceNo":171,"q":"Which of the following is untrue regarding piebaldism?","o":["autosomal dominant condition","amelanotic skin associated with a white forelock","Islands of normal or hypermelanotic skin","Usually improves with age"],"a":3,"e":"Ans. D. Usually improves with age Piebaldism Piebaldism is a rare autosomal dominant condition characterized by stable areas of vitiligo-like amelanotic skin associated with a white forelock. Present at birth and usually remain unchanged throughout life. Most common is a frontal median or paramedian patch, associated with a mesh of white hair (white Forelock). Often, white patches occur on the upper chest, abdomen and limbs, bilaterally but not necessarily symmetrically The hands and feet, as well as the back, remain normally pigmented Islands of normal or hypermelanotic skin occur in the white areas, or less often on normal skin.","pyqMatches":[{"year":"2012","no":1371,"q":"Which of the following is untrue regarding piebaldism?","o":["autosomal dominant condition","amelanotic skin associated with a white forelock","Islands of normal or hypermelanotic skin","Usually improves with age"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1713, 'Dermatology', 'Dermatology Basics', 'Moderate', 'Skin', 172, '{"id":1713,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Moderate","source":"Skin","sourceNo":172,"q":"Which of the following is not a NEVUS of melanocyte?","o":["Mongolian spot","Nevus of Ito","Nevus of ota","Becker nevus"],"a":3,"e":"Ans. D. Becker nevus Becker nevus is appendageal nevi where as other three are melanocyitc nevi. Melanocytic nevi are :- Dysplastic nevus BIue nevus Nevus of ito & nevus of ota Spitz nevus Giant pigmented nevus Mongolian spot Intramucosal neyus","pyqMatches":[{"year":"2012","no":1373,"q":"Which of the following is not a NEVUS of melanocyte?","o":["Mongolian spot","Nevus of Ito","Nevus of ota","Becker nevus"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1714, 'Dermatology', 'Papulosquamous Disorders', 'Easy', 'Skin', 173, '{"id":1714,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Easy","source":"Skin","sourceNo":173,"q":"Ichy purple papule followed by hayperpigmentation on resolution, is seen in?","o":["Addison''s disease","DM","Hypothyroidism","Lichen planus"],"a":3,"e":"Ans. D. Lichen planus LP is characterized by shiny, violaceous, flat-topped polygonal papules which retain the skin lines. White lines, known as Wickham''s striae, may traverse the surface of the papules. Linear lesions often appear along scratch marks or in scars (Koebner phenomenon). In most cases, the papules eventually flatten after a 6 months to 2 yrs, often to be replaced by an area of hyperpigmentation.","pyqMatches":[{"year":"2012","no":1375,"q":"Ichy purple papule followed by hayperpigmentation on resolution, is seen in?","o":["Addison''s disease","DM","Hypothyroidism","Lichen planus"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1715, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 174, '{"id":1715,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":174,"q":"Loss of Intercellular cohesion between keratinocytes is called as ?","o":["Acanthosis","Acantholysis","Keratinolysis","Spongiosis"],"a":1,"e":"Ans. B. Acantholysis Separation of epidermal keratinocytes due to loss of intercellular bridge is referred to as acantholysis. Acantholysis is seen in the epidermis (especially in basal layer).","pyqMatches":[{"year":"2012","no":1377,"q":"Loss of Intercellular cohesion between keratinocytes is called as ?","o":["Acanthosis","Acantholysis","Keratinolysis","Spongiosis"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1716, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 175, '{"id":1716,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":175,"q":"Tzank cell is ?","o":["Keratinocyte","Fibrobalst","Neutrophil","Lymphocyte"],"a":0,"e":"Ans.A. Keratinocyte Tzank cells are acanthoylytic cells i.e. large rounded keratinocytes with srelatively large nucleus with condensed or hazy cytoplasm.","pyqMatches":[{"year":"2012","no":1378,"q":"Tzank cell is ?","o":["Keratinocyte","Fibrobalst","Neutrophil","Lymphocyte"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1717, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 176, '{"id":1717,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":176,"q":"True about lepromatous leprosy ?","o":["Only 3 cutaneous lesions","Lepromin test highly positive","Thickened nerve roots","ENL in > 50% cases"],"a":2,"e":"Ans. C. Thickened nerve roots Nerve involvement in lepromatous leprosy causes thickening of nerve. Lepromin test is negative. There are more than 10 macules / patches/plaques.","pyqMatches":[{"year":"2012","no":1379,"q":"True about lepromatous leprosy ?","o":["Only 3 cutaneous lesions","Lepromin test highly positive","Thickened nerve roots","ENL in > 50% cases"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1718, 'Dermatology', 'Miscellaneous', 'Moderate', 'Skin', 177, '{"id":1718,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Skin","sourceNo":177,"q":"Dermatophytosis is not ?","o":["Scaly","Itchy","Superficial","Subdermal"],"a":3,"e":"Ans. D. Subdermal","pyqMatches":[{"year":"2012","no":1380,"q":"Dermatophytosis is not ?","o":["Scaly","Itchy","Superficial","Subdermal"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1719, 'Dermatology', 'Papulosquamous Disorders', 'Easy', 'Skin', 178, '{"id":1719,"subject":"Dermatology","chapter":"Papulosquamous Disorders","difficulty":"Easy","source":"Skin","sourceNo":178,"q":"Oculoorogenital ulcers are a feature of ?","o":["Behcet disease","lichen planus","SLE","Psoriasis"],"a":0,"e":"Ans. A. Behcet disease Behcet''s disease is a multisystem disease that is defined by the presence of oral aphthosis with at least two of the following: genital aphthae synovitis, posterior uveitis, cutaneous pustular vasculitis or meningoencephalitis, in the absence of IBD or autoimmune Diseases.","pyqMatches":[{"year":"2012","no":1381,"q":"Oculoorogenital ulcers are a feature of ?","o":["Behcet disease","lichen planus","SLE","Psoriasis"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1720, 'Dermatology', 'Acne & Disorders of Pilosebaceous Unit', 'Easy', 'Skin', 179, '{"id":1720,"subject":"Dermatology","chapter":"Acne & Disorders of Pilosebaceous Unit","difficulty":"Easy","source":"Skin","sourceNo":179,"q":"Maximum cumulative dose of isotretinoin shouldn''t exceed for acne treatment ?","o":["30-60 mg/kg","60-90 mg/kg","90-120 mg/kg","120-150 mg/kg"],"a":3,"e":"Ans., D. 120-150 mg/kg Isotretinoin is recommended for severe nodulocystic acne and also for the patients with milder disease who don''t respond to conventional treatment. Treatment regimens usually begin at 0.5-1.0mg/kg/day for the duration of between 16 and 20 weeks. Cumulative dose amount to a total of at least 12O mg/kg, but there is no added benefit when 150 mg/kg is exceeded.","pyqMatches":[{"year":"2012","no":1385,"q":"Maximum cumulative dose of isotretinoin shouldn''t exceed for acne treatment ?","o":["30-60 mg/kg","60-90 mg/kg","90-120 mg/kg","120-150 mg/kg"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1721, 'Dermatology', 'Miscellaneous', 'Easy', 'Skin', 180, '{"id":1721,"subject":"Dermatology","chapter":"Miscellaneous","difficulty":"Easy","source":"Skin","sourceNo":180,"q":"Exanthema subitum is caused by ?","o":["HHV","HPV","HIV","HCV"],"a":0,"e":"Ans. A. HHV HHV-6 virus causes roseola infantum (exanthem subitum), the most common exanthematic fever in children under the age of2 years, with a peak incidence between 6 and 9 months.","pyqMatches":[{"year":"2012","no":1386,"q":"Exanthema subitum is caused by ?","o":["HHV","HPV","HIV","HCV"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":803,"q":"Exanthema subitum is caused by ?","o":["HHV-6","HHV-8","Parvovirus","Coxsackievirus"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1722, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 181, '{"id":1722,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":181,"q":"Cutis marmorata occurs due to exposure to –","o":["Cold temperature","Dust","Hot temperature","Humidity"],"a":0,"e":"Ans. A.Cold temperature Cutis marmorata is a condition where in the skin has a pinkish blue mottled or marbled appearance when subjected to cold temperatures. It is seen throughout infancy and in 50 % of children. Rewarming restores the skin to normal. It is caused by superficial small blood vessels in the skin dilating and contracting at the same time .","pyqMatches":[{"year":"2018","no":191,"q":"Cutis marmorata occurs due to exposure to –","o":["Cold temperature","Dust","Hot temperature","Humidity"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1723, 'Dermatology', 'Dermatology Basics', 'Easy', 'Skin', 182, '{"id":1723,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Easy","source":"Skin","sourceNo":182,"q":"What constitutes malpighian layer?","o":["Corneum lucidum","Corneum spinosum","Spinosum and basale","Basale granulosum"],"a":2,"e":"Ans.C.Spinosum and basale The Malpighian layer of the skin is generally defined as both the stratum basale and stratum spinosum as a unit, although it is occasionally defined as the stratum basale specifically,or the stratum spinosum specifically. It is named after Marcello Malpighi.","pyqMatches":[{"year":"2018","no":252,"q":"What constitutes malpighian layer?","o":["Corneum lucidum","Corneum spinosum","Spinosum and basale","Basale granulosum"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1724, 'Dermatology', 'Dermatology Basics', 'Hard', 'Skin', 183, '{"id":1724,"subject":"Dermatology","chapter":"Dermatology Basics","difficulty":"Hard","source":"Skin","sourceNo":183,"q":"A Child is born, covered with a thick membranous coat, what could be the possible diagnosis?","o":["Lamellar ichthyosis","X-linked ichthyosis","Ichthyosis Vulgaris","Ichthyosis acquista"],"a":0,"e":"Answer- a. Lamellar ichthyosis Explanation- Ichthyosis is one of the most common genodermatoses. It is characterized by dry (xerotic) scaly skin all over the body. Scales are dull-brown-black. The basic defect is an impairment in the barrier function of skin and inability to maintain moisture. Collodion baby is the term used to denote the newborn baby with ichthyosis; the newborn baby is encased in a thick, shiny membrane coat called collodion and is seen in Lamellar ichthyosis Ref- Arvind Arora skin, 6th edition, page no 203","pyqMatches":[{"year":"2020","no":233,"q":"A Child is born, covered with a thick membranous coat, what could be the possible diagnosis?","o":["Lamellar ichthyosis","X-linked ichthyosis","Ichthyosis Vulgaris","Ichthyosis acquista"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1725, 'ENT', 'Ear', 'Easy', 'ENT', 1, '{"id":1725,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":1,"q":"Weber ferguson approach is used for?","o":["Mastoidectomy","Maxillectomy","Myringoplasty","Mandibulectomy"],"a":1,"e":"Ans. B. Maxillectomy WEBER FERGUSON APPROACH: This approach involves an extension of the lateral rhinotomy incision that includes the splitting of upperlip. Indications: Exenteration of maxilla for total or subtotal maxillectomy (splitting the upper lip releases the facial flap for adequate lateral retraction and adds transoral exposure of palate and teeth)","pyqMatches":[{"year":"2013","no":990,"q":"Weber ferguson approach is used for?","o":["Mastoidectomy","Maxillectomy","Myringoplasty","Mandibulectomy"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1726, 'ENT', 'Ear', 'Hard', 'ENT', 2, '{"id":1726,"subject":"ENT","chapter":"Ear","difficulty":"Hard","source":"ENT","sourceNo":2,"q":"A patient with ear complaints showed positive Hennebert sign. Which of the following condition shows positive Hennebert sign?","o":["Meniere''s disease","Acoustic neuroma","Neuronitis","Glossopharyngeal neuralgia"],"a":0,"e":"The presence of a fistula is suspected if nystagmus occurs or if the patient perceives movement of a visual target that is fixed after applying positive pressure to the outer ear canal. A positive test result (ie, Hennebert sign) suggests either a perilymph fistula or Meniere''s disease.","pyqMatches":[{"year":"2015","no":933,"q":"A patient with ear complaints showed positive Hennebert sign. Which of the following condition shows positive Hennebert sign?","o":["Meniere''s disease","Acoustic neuroma","Neuronitis","Glossopharyngeal neuralgia"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1727, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 3, '{"id":1727,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":3,"q":"The maxillary sinus opens into middle meatus at the level of:","o":["Hiatus semilunaris","Bulla ethmoidalis","Infundibulum","None of the above"],"a":0,"e":"The maxillary sinus is the largest of the paranasal sinuses and is located in the maxilla, lateral to the nasal cavity and inferior to the orbit. The maxillary sinus opens into the posterior aspect of the hiatus semilunaris in the middle meatus. The infraorbital nerve (CN V-2) primarily innervates the maxillary sinus.","pyqMatches":[{"year":"2016","no":894,"q":"The maxillary sinus opens into middle meatus at the level of:","o":["Hiatus semilunaris","Bulla ethmoidalis","Infundibulum","None of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1728, 'ENT', 'Ear', 'Moderate', 'ENT', 4, '{"id":1728,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":4,"q":"Gradenigo''s syndrome involves all of the following cranial nerves, EXCEPT:","o":["IV","V","VI","VII"],"a":0,"e":"Ans. A. IV Gradenigo’s syndrome is characterized by facial pain, particularly in the first division of the trigeminal nerve and diplopia due to sixth cranial nerve palsy. It is associated with disease at the apex of the petrous temporal bone where the abducens nerve is closely related to the trigeminal nerve. Facial nerve palsy and deafness (VIII nerve palsy) is also considered to be a part of this syndrome. Causes includes: Inflammation (petrositis, possibly spreading from a local infection such as otitis or mastoiditis) Tumors ( cholesteatoma, chordoma, meningioma, nasopharyngeal carcinoma, metastatic disease) Skull base fracture","pyqMatches":[{"year":"2016","no":911,"q":"Gradenigo''s syndrome involves all of the following cranial nerves, EXCEPT:","o":["IV","V","VI","VII"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1729, 'ENT', 'Ear', 'Easy', 'ENT', 5, '{"id":1729,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":5,"q":"Ceruminous glands present in the ear are:","o":["Modified eccrine glands","Modified apocrine glands","Mucous gland","Modified holocrine glands"],"a":1,"e":"Ans. is. B. Modified apocrine glands","pyqMatches":[{"year":"2015","no":932,"q":"Ceruminous glands present in the ear are:","o":["Modified eccrine glands","Modified apocrine glands","Mucous gland","Modified holocrine glands"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1730, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 6, '{"id":1730,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":6,"q":"Mac Ewan''s triangle is the landmark for:","o":["Maxillary sinus","Mastoid antrum","Frontal sinus","None"],"a":1,"e":"Ans. is. B. Mastoid antrum","pyqMatches":[{"year":"2016","no":901,"q":"Mac Ewan''s triangle is the landmark for:","o":["Maxillary sinus","Mastoid antrum","Frontal sinus","None"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1731, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 7, '{"id":1731,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":7,"q":"External auditory canal is formed by:","o":["1st branchial groove","1st visceral pouch","2nd branchial groove","2nd visceral pouch"],"a":0,"e":"Ans. is. A. 1st branchial groove","pyqMatches":[{"year":"2015","no":940,"q":"External auditory canal is formed by:","o":["1st branchial groove","1st visceral pouch","2nd branchial groove","2nd visceral pouch"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1732, 'ENT', 'Ear', 'Easy', 'ENT', 8, '{"id":1732,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":8,"q":"Hyperacusis is defined as:","o":["Hearing of only loud sound","Normal sounds heard as loud and painful","Completely deaf","Ability to hear in noisy surroundings"],"a":1,"e":"Sensation of discomfort or pain on exposure to normal sounds. Seen in injury to nerve to stapedius and in case of congenital syphilis (Hennebert sign)","pyqMatches":[{"year":"2013","no":1033,"q":"Hyperacusis is defined as:","o":["Hearing of only loud sound","Normal sounds heard as loud and painful","Completely deaf","Ability to hear in noisy surroundings"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1733, 'ENT', 'Ear', 'Easy', 'ENT', 9, '{"id":1733,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":9,"q":"In electrocochleography:","o":["It measures middle ear latency","Outer hair cells are mainly responsible for cochlear mi​‐ crophonics and summation potential","Summation potential is a compound of synchronus audi​tory nerve potential","Total AP represents endocochlear receptor potential to an external auditory stimulus"],"a":1,"e":"Ans. is. B. Outer hair cells are mainly responsible for cochlear mi​crophonics and summation potential","pyqMatches":[{"year":"2016","no":898,"q":"In electrocochleography:","o":["It measures middle ear latency","Outer hair cells are mainly responsible for cochlear mi​‐ crophonics and summation potential","Summation potential is a compound of synchronus audi​tory nerve potential","Total AP represents endocochlear receptor potential to an external auditory stimulus"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1734, 'ENT', 'Ear', 'Easy', 'ENT', 10, '{"id":1734,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":10,"q":"True statement about malignant otitis externa is:","o":["Not painful","Common in diabetics and old age","Caused by streptococcus","All of the above"],"a":1,"e":"Ans. is. B. Common in diabetics and old age","pyqMatches":[{"year":"2015","no":930,"q":"True statement about malignant otitis externa is:","o":["Not painful","Common in diabetics and old age","Caused by streptococcus","All of the above"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1735, 'ENT', 'Ear', 'Easy', 'ENT', 11, '{"id":1735,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":11,"q":"Ossicle M/C involved in CSOM:","o":["Stapes","Long process of incus","Head of malleus","Handle of malleus"],"a":1,"e":"Ans. is. B. Long process of incus","pyqMatches":[{"year":"2016","no":900,"q":"Ossicle M/C involved in CSOM:","o":["Stapes","Long process of incus","Head of malleus","Handle of malleus"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1736, 'ENT', 'Ear', 'Easy', 'ENT', 12, '{"id":1736,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":12,"q":"Most common nerve to be damaged in CSOM is","o":["III","VII","IV","VI"],"a":1,"e":"Facial nerve is the M/C nerve to be damaged in CSOM.","pyqMatches":[{"year":"2014","no":1104,"q":"Most common nerve to be damaged in CSOM is","o":["III","VII","IV","VI"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1737, 'ENT', 'Ear', 'Easy', 'ENT', 13, '{"id":1737,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":13,"q":"Simple mastoidectomy is done in:","o":["Acute mastoiditis","Cholesteatoma","Coalescent mastoiditis","Localized chronic otitis media"],"a":2,"e":"Ans. is. C. Coalescent mastoiditis","pyqMatches":[{"year":"2016","no":949,"q":"Simple mastoidectomy is done in:","o":["Acute mastoiditis","Cholesteatoma","Coalescent mastoiditis","Localized chronic otitis media"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1738, 'ENT', 'Ear', 'Easy', 'ENT', 14, '{"id":1738,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":14,"q":"Radical mastoidectomy is done for:","o":["ASOM","CSOM","Atticoantral cholesteotoma","Acute mastoiditis"],"a":2,"e":"Ans. is. C. Atticoantral cholesteotoma","pyqMatches":[{"year":"2016","no":950,"q":"Radical mastoidectomy is done for:","o":["ASOM","CSOM","Atticoantral cholesteotoma","Acute mastoiditis"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1739, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 15, '{"id":1739,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":15,"q":"Light house sign in seen in ASOM in which stage?","o":["Stage of suppuration","Stage of hyperaemia","Stage of resolution","Stage of pre-suppuration"],"a":0,"e":"In the stage of supperation of ASOM, pus formation occurs, hence in this stage pulsatile otorrhea or light house sign in seen.","pyqMatches":[{"year":"2015","no":934,"q":"Light house sign in seen in ASOM in which stage?","o":["Stage of suppuration","Stage of hyperaemia","Stage of resolution","Stage of pre-suppuration"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1740, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 16, '{"id":1740,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":16,"q":"In otosclerosis, the tympanogram is:","o":["Low compliance","High compliance","Normal compliance","None of the above"],"a":0,"e":"In otosclerosis - As type curve is seen which is a low compliance curve.","pyqMatches":[{"year":"2013","no":1038,"q":"In otosclerosis, the tympanogram is:","o":["Low compliance","High compliance","Normal compliance","None of the above"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1741, 'ENT', 'Ear', 'Easy', 'ENT', 17, '{"id":1741,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":17,"q":"Which fracture of the petrous bone will cause facial nerve palsy:","o":["Longitudinal fractures","Transverse fractures","Mastoid","Facial nerve injury is always complete"],"a":1,"e":"Ans. is. B. Transverse fractures","pyqMatches":[{"year":"2016","no":899,"q":"Which fracture of the petrous bone will cause facial nerve palsy:","o":["Longitudinal fractures","Transverse fractures","Mastoid","Facial nerve injury is always complete"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1742, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 18, '{"id":1742,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":18,"q":"FISCH classification is used for:","o":["Juvenile nasopharyngeal angiofibroma","Nasopharyngeal ca","Vestibular schwannoma","Glomus tumour"],"a":3,"e":"A classification system (A-D) describing glomus tumors based on anatomic location and size, with larger lettering representing more extensive tumors.","pyqMatches":[{"year":"2013","no":1041,"q":"FISCH classification is used for:","o":["Juvenile nasopharyngeal angiofibroma","Nasopharyngeal ca","Vestibular schwannoma","Glomus tumour"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1743, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 19, '{"id":1743,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":19,"q":"True about rhinophyma:","o":["Premalignant","Common in alcoholics","Acne rosacea","Fungal etiology"],"a":2,"e":"Rhinophyma is a slow-growing benign tumor which occurs due to hypertrophy of the sebaceous glands° of the tip of the nose. Seen in long standing cases of acne rosacea. Mostly affects men past middle age. Presents as a pink, lobulated mass over the nose. Treatment Paring down the bulk of the tumor with a sharp knife, or carbon dioxide laser or scalpel (dermabraions), and the area is allowed to re-epithelize. Sometimes tumor is completely excised and the raw area is covered with skin graft.","pyqMatches":[{"year":"2013","no":1059,"q":"True about rhinophyma:","o":["Premalignant","Common in alcoholics","Acne rosacea","Fungal etiology"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1744, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 20, '{"id":1744,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":20,"q":"What is a Rhinolith:","o":["Foreign body in nose","Stone in nose","Deposition of calcium around foreign body in nose","Misnomer"],"a":2,"e":"Rhinoliths are calcareous masses which result due to deposition of salts-like calcium and magnesium carbonates and phosphates around the nucleus of a foreign body.","pyqMatches":[{"year":"2016","no":933,"q":"What is a Rhinolith:","o":["Foreign body in nose","Stone in nose","Deposition of calcium around foreign body in nose","Misnomer"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1745, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 21, '{"id":1745,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":21,"q":"Posterior epistaxis occurs from:","o":["Woodruffs plexus","Kiesselbach''s plexus","Atherosclerosis","Littles area"],"a":0,"e":"No separate explanation was provided in the source.","pyqMatches":[{"year":"2013","no":1063,"q":"Posterior epistaxis occurs from:","o":["Woodruffs plexus","Kiesselbach''s plexus","Atherosclerosis","Littles area"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1746, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 22, '{"id":1746,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":22,"q":"Caldwell view is done for","o":["Sphenoid sinus","Maxillary sinus","Ethmoid sinus","Frontal sinus"],"a":3,"e":"Caldwell view is the occipito frontal view. The frontal sinuses are seen clearly in this view.","pyqMatches":[{"year":"2014","no":2028,"q":"Caldwell view is done for","o":["Sphenoid sinus","Maxillary sinus","Ethmoid sinus","Frontal sinus"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1747, 'ENT', 'Miscellaneous', 'Moderate', 'ENT', 23, '{"id":1747,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Moderate","source":"ENT","sourceNo":23,"q":"Regarding ranula all are true except:","o":["Retention cyst","Arises from submandibular gland","Translucent","Plunging may be a feature"],"a":1,"e":"No separate explanation was provided in the source.","pyqMatches":[{"year":"2013","no":1090,"q":"Regarding ranula all are true except:","o":["Retention cyst","Arises from submandibular gland","Translucent","Plunging may be a feature"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1748, 'ENT', 'Throat & Larynx', 'Easy', 'ENT', 24, '{"id":1748,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Easy","source":"ENT","sourceNo":24,"q":"Regarding adenoids true is/are:","o":["There is failure to thrive","Mouth breathing is seen","CT scan should be done to assess size","a and b"],"a":3,"e":"High arched palate and mouth breathing are features of hypertrophied adenoids which leads to adenoid facies In adenoids as a consequence of recurrent nasal obstruction and URTI, child develops failure to thrive Size of adenoids may well be assessed using lateral radiograph of nasopharynx, and CT scan is not necessary Adenoids, also known as nasopharyngeal tonsils, are subepithelial collection of lymphoid tissue at the junction of roof and posterior wall of nasopharynx.","pyqMatches":[{"year":"2016","no":937,"q":"Regarding adenoids true is/are:","o":["There is failure to thrive","Mouth breathing is seen","CT scan should be done to assess size","a and b"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1749, 'ENT', 'Throat & Larynx', 'Easy', 'ENT', 25, '{"id":1749,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Easy","source":"ENT","sourceNo":25,"q":"Trismus in parapharyngeal abscess is due to spasm of:","o":["Masseter muscle","Medial pterygoid","Lateral pterygoid","Temporalis"],"a":1,"e":"Styloid process divides the pharynx into anterior and posterior compartment. Trismus occurs in infection of anterior compartment whereas torticollis (due to spasm of paravertebral muscles) occurs in the infection of posterior compartment.","pyqMatches":[{"year":"2016","no":936,"q":"Trismus in parapharyngeal abscess is due to spasm of:","o":["Masseter muscle","Medial pterygoid","Lateral pterygoid","Temporalis"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1750, 'ENT', 'Throat & Larynx', 'Easy', 'ENT', 26, '{"id":1750,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Easy","source":"ENT","sourceNo":26,"q":"Inlet of larynx is formed by:","o":["Ventricular fold","Aryepiglottic fold","Glossoepiglottic fold","Vocal cord"],"a":1,"e":"The laryngeal inlet (laryngeal aditus, laryngeal aperture) is the opening that connects the pharynx and the larynx. Its borders are formed by: the free curved edge of the epiglottis, anteriorly. the arytenoid cartilages, the corniculate cartilages, and the interarytenoid fold, posteriorly.","pyqMatches":[{"year":"2013","no":1084,"q":"Inlet of larynx is formed by:","o":["Ventricular fold","Aryepiglottic fold","Glossoepiglottic fold","Vocal cord"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1751, 'ENT', 'Throat & Larynx', 'Moderate', 'ENT', 27, '{"id":1751,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Moderate","source":"ENT","sourceNo":27,"q":"All the following are true about Laryngeal carcinoma except:","o":["More common in females","Common in patients over 40 years of age","After laryngectomy, esophageal voice can be used","b and c"],"a":0,"e":"Cancer Larynx Most common histological type of laryngeal Ca - Squamous cell carcinoma (seen in 90% cases) It is more common in males. Male: Female ratio is 4: 1 Most common age = 60-70 years.","pyqMatches":[{"year":"2016","no":943,"q":"All the following are true about Laryngeal carcinoma except:","o":["More common in females","Common in patients over 40 years of age","After laryngectomy, esophageal voice can be used","b and c"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1752, 'ENT', 'Throat & Larynx', 'Easy', 'ENT', 28, '{"id":1752,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Easy","source":"ENT","sourceNo":28,"q":"Select correct statements about Ca larynx:","o":["Glottic Ca is the most common","Supraglottic ca has best prognosis","Lymphatic spread is the most common in subglottic Ca","All"],"a":0,"e":"Ans. is. A. Glottic Ca is the most common","pyqMatches":[{"year":"2016","no":939,"q":"Select correct statements about Ca larynx:","o":["Glottic Ca is the most common","Supraglottic ca has best prognosis","Lymphatic spread is the most common in subglottic Ca","All"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1753, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 29, '{"id":1753,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":29,"q":"The commonest site of aspiration of a foreign body in the supine position is into the:","o":["Right upper lobe apical","Right lower lobe apical","Left basal","Right medial"],"a":1,"e":"In supine position and with the patient on back superior segment of RLL is the most dependent segment.","pyqMatches":[{"year":"2012","no":1149,"q":"The commonest site of aspiration of a foreign body in the supine position is into the:","o":["Right upper lobe apical","Right lower lobe apical","Left basal","Right medial"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1754, 'ENT', 'Ear', 'Easy', 'ENT', 30, '{"id":1754,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":30,"q":"Cauliflower ear seen in:","o":["Hematoma of the auricle","Carcinoma of the auricle","Fungal infection of the auricle","Congenital deformity"],"a":0,"e":"Cauliflower ear (boxer''s ear, wrestler''s ear) is an acquired deformity of the outer ear. In this injury, the ear can shrivel up and fold in on itself and appear pale, giving it a cauliflower-like appearance, hence the term cauliflower ear. Wrestlers, boxers and martial artists in particular are susceptible to this type of injury. When the ear is struck and a blood clot develops under the skin, or the skin is sheared from the cartilage, the connection of the skin to the cartilage is disrupted.","pyqMatches":[{"year":"2016","no":897,"q":"Cauliflower ear seen in:","o":["Hematoma of the auricle","Carcinoma of the auricle","Fungal infection of the auricle","Congenital deformity"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1755, 'ENT', 'Nose & Paranasal Sinuses', 'Moderate', 'ENT', 31, '{"id":1755,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Moderate","source":"ENT","sourceNo":31,"q":"All of the following arteries contributes to Little''s area EXCEPT:","o":["Anterior Ethmoidal artery","Posterior Ethmoidal artery","Sphenopalatine artery","Greater palatine artery"],"a":1,"e":"Kiesselbach''s plexus It lies in Kiesselbach''s area/ Kiesselbach''s triangle/ Little''s area It is a region in the anteroinferior part of the nasal septum where four arteries anastomose to form a vascular plexus of that name. The arteries are: - Anterior Ethmoidal artery (from the Ophthalmic artery) - Sphenopalatine artery (terminal branch of the Maxillary artery) - Greater palatine artery (from the Maxillary artery) Septal branch of the superior labial artery (from the Facial artery) Although the Posterior Ethmoidal artery also supplies the septum of the nose, it does not contribute to the plexus.","pyqMatches":[{"year":"2013","no":1054,"q":"All of the following arteries contributes to Little''s area EXCEPT:","o":["Anterior Ethmoidal artery","Posterior Ethmoidal artery","Sphenopalatine artery","Greater palatine artery"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1756, 'ENT', 'Ear', 'Easy', 'ENT', 32, '{"id":1756,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":32,"q":"Multiple perforation of tympanic membrane characteristic of ?","o":["Tubercular Otitis Media","Syphilitic Otitis Media","Pseudomonas infection","Fungal Otitis Media"],"a":0,"e":"Ans. is ''a'' i.e., Tubercular otitis media Tubercular otitis media Tuberculosis of middle ear is a comparatively rare entity usually seen in association with or secondary to pulmonarytuberculosis, infection reaches the middle ear through eustachian tube. The rare modes of infection are through hematogenous spread from tubercular focus in lung, tonsils, cervical lymph nodes; or due to ingestion of infected cow''s milk. It usually affects children and young adults. Clinical features Generally, tuberculosis of middle ear is unilateral. It is characterized by painless otorrhoea which fails to respond to the usual antimicrobial treatment. There is painless watery otorrhea. Single or multiple perforation of tympanic membrane. There may be multiple perforations in the early stages, but they coalesce into a large tympanic membrane perforation accompanied by a pale granulation tissue. Periauricular fistulae, lymphadenopathy and facial palsy are infrequent findings. Late complications include facial paralysis, labyrinthitis, postauricular fistulae, subperiosteal abscess, petrous apicitis and intracranial extension of infection.","pyqMatches":[{"year":"2014","no":1110,"q":"Multiple perforation of tympanic membrane characteristic of ?","o":["Tubercular Otitis Media","Syphilitic Otitis Media","Pseudomonas infection","Fungal Otitis Media"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1757, 'ENT', 'Ear', 'Moderate', 'ENT', 33, '{"id":1757,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":33,"q":"Another name for oral thrush is ?","o":["Candidiasis","Herpangina","Vincent''s infection","Hand foot and mouth disease"],"a":0,"e":"Ans. is ''a'' i.e., Candidiasis Oral thrush Also called: oral candidiasis It is the fungal infection of the oral cavity. It is caused by candida albicans. It manifests as greyish white patches on the oral mucosa and tongue.\\When wiped off it leaves an erythematous mucosa. This is more common in infants and children. Adults suffering fro diabetes, malignancy, taking broad spectrum oral antibiotics, radiation, cytotoxic drugs or steroids can also be affected. It is treated by topical application of nystatin or clotrimazole. Chronic Hypertrophic Candidiasis (Candidial Leukoplakia) Appears as a white patch in the oral cavity which cannot be wiped off. It mostly affects the anterior buccal mucosa just behind the angle of mouth. It is treated by excision of the lesion.","pyqMatches":[{"year":"2014","no":1146,"q":"Another name for oral thrush is ?","o":["Candidiasis","Herpangina","Vincent''s infection","Hand foot and mouth disease"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1758, 'ENT', 'Nose & Paranasal Sinuses', 'Moderate', 'ENT', 34, '{"id":1758,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Moderate","source":"ENT","sourceNo":34,"q":"Which of the following is not true about inverted papilloma ?","o":["It is always unilateral","It is more common in males","10-15 % of the cases may be associated with squamous cell carcinoma","It is also called Ringertz tumor"],"a":3,"e":"Ans. is ''d'' i.e., It is also called Ringertz tumor Inverted Papilloma (Transitional cell papilloma / Schneiderion papilloma) Inverted papilloma is a benign neoplasm occurs mostly between 40- 70 years with male preponderance (5 : 1). o It arises from the lateral wall of nose and is always unilateral. Rarely, it may arise from nasal septum. o Features of inverted papilloma are :- It shows finger like epithelial invasions into the underlying stroma of the epithelium rather than on surface so called inverted papilloma. It is usually unilateral and is a locally aggressive tumour. Patients complain of nasal obstruction, rhinorrhea & unilateral epistaxis. In 10-15% cases there may be associated squamous cell carcinoma. Treatment is adequate local excision. If it arises in maxillary sinus, then a radical antrostomy is carried out.If it arises in the ethmoidal sinus, an external ethmoidectomy is done. If it arises from nose, treatment is wide surgical excision by lateral rhinotomy. Has a tendency to recur even after removal.","pyqMatches":[{"year":"2014","no":1126,"q":"Which of the following is not true about inverted papilloma ?","o":["It is always unilateral","It is more common in males","10-15 % of the cases may be associated with squamous cell carcinoma","It is also called Ringertz tumor"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1759, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 35, '{"id":1759,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":35,"q":"Positive head impulse test is suggestive of ?","o":["Injury to vestibular nuclei","Injury to peripheral vestibular nerve","Lesion in the brain stem","Injury to Occulomotor nerve"],"a":1,"e":"Ans. is `b'' i.e., Injury to peripheral vestibular nerve Head Impulse Test It is also called head thrust test. It is test for the diagnosis of injury to vestibular nerve which forms the peripheral vestibular pathway. Clinician asks the patient to fix his gaze on a target and then perform passive horizontal and vertical head impulses and observes the patient''s eyes. Observation of a refixation saccade after the head impulse indicates decreased decreasedvestibulo ocular reflex secondary to peripheral vestibular lesions (vestibular nerve involvement).","pyqMatches":[{"year":"2014","no":1078,"q":"Positive head impulse test is suggestive of ?","o":["Injury to vestibular nuclei","Injury to peripheral vestibular nerve","Lesion in the brain stem","Injury to Occulomotor nerve"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1760, 'ENT', 'Ear', 'Easy', 'ENT', 36, '{"id":1760,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":36,"q":"Conducting hearing loss with intact tympanic membrane ?","o":["Presbycausis","Meniere''s disease","Glue ear","Acoustic neuroma"],"a":2,"e":"Ans. is ''c'' i.e., Glue ear Among the given options, only glue ear (serous otitis media) is a cause of conductive deafness.","pyqMatches":[{"year":"2014","no":1112,"q":"Conducting hearing loss with intact tympanic membrane ?","o":["Presbycausis","Meniere''s disease","Glue ear","Acoustic neuroma"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1761, 'ENT', 'Ear', 'Moderate', 'ENT', 37, '{"id":1761,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":37,"q":"Not a cause of objective tinnitus ?","o":["Palatal myoclonus","Glomus tumor","Carotid artery aneurysm","Presbyacusis"],"a":3,"e":"Ans. is ''d'' i.e., Presbyacusis Tinnitus Tinnitus is ringing sound or noise in the ear. The characteristic feature is that the origin of this sound is within the patient.","pyqMatches":[{"year":"2014","no":1114,"q":"Not a cause of objective tinnitus ?","o":["Palatal myoclonus","Glomus tumor","Carotid artery aneurysm","Presbyacusis"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1762, 'ENT', 'Ear', 'Easy', 'ENT', 38, '{"id":1762,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":38,"q":"Length of external auditory meatus is ?","o":["12mm","16mm","20mm","24mm"],"a":3,"e":"Ans. is ''d'' i.e., 24 mm External auditory canal (External acoustic meatus) External auditory canal is a ''S'' shaped canal with length of 24- 25 mm and it is divided into two parts :? 1) Cartilagenous part It forms outer/lateral 1/3 (8mm) of the external auditory canal. It has two fissures / deficiencies in the anterior part called fissure of santorini through which parotid or superficial mastoid infection can appear in the canal and vice versa. Skin covering it is thick and has ceruminous glands (modified apocrine sweat glands), pilosebaceous glands and hair. Since hair is confined to cartilaginous part, furuncles are seen only in the outer third of the canal. 2) Bony part It forms inner/medial 2/3 (16 mm) of external auditory canal. Skin lining the bony part is thin and is devoid of hair and ceruminous glands. Isthmus is the narrowest portion of bony canal and is 5 mm lateral to tympanic membrane. Foreign bodies get lodged in isthmus are difficult to remove as it is the narrowest part. `Foramen of Huschke'' is a deficiency present in antero-inferior part of bony canal in children upto 4 years of age, permitting infection to and from parotid.","pyqMatches":[{"year":"2014","no":1113,"q":"Length of external auditory meatus is ?","o":["12mm","16mm","20mm","24mm"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1763, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 39, '{"id":1763,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":39,"q":"Which of the following is false regarding frontal sinusitis ?","o":["Pain shows periodicity","Most common sinus involved in infants and children","Pain is referred to as office headache","Tenderness is present just above the medial canthus of eye"],"a":1,"e":"Ans. is ''b'' i.e., Most common sinus involved in infants and children Most common sinus involved in infant and children is Ethmoid sinus. Clinical features of acute sinusitis Most common presenting patient''s compliant is persistent nasal discharge which can be of any quality (thin, thick, clear, or purulent). Nasal discharge from a sinus infection can be blood - tinged from excessive nose blowing and irritation. The clinical symptoms of acute sinusitis have been classified into major and minor.","pyqMatches":[{"year":"2014","no":1128,"q":"Which of the following is false regarding frontal sinusitis ?","o":["Pain shows periodicity","Most common sinus involved in infants and children","Pain is referred to as office headache","Tenderness is present just above the medial canthus of eye"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1764, 'ENT', 'Head & Neck', 'Easy', 'ENT', 40, '{"id":1764,"subject":"ENT","chapter":"Head & Neck","difficulty":"Easy","source":"ENT","sourceNo":40,"q":"Mini tracheostomy is performed through ?","o":["Cricothyroid membrane","2nd and 3rd tracheal rings","Any of the above","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Cricothyroid membrane Cricothyrotomy or Laryngtomy or Minitracheostomy It is the procedure to open the airway through the cricothyroid membrane. Patient''s head and neck are extended, lower border of throid cartilage and cricoid ring is identified. Skin in this area is incised vertically and then cricothyroid membrane is opened with a transverse incision. It is an emergency procedure to buy time for the patient to be shifted to the operation theatre.","pyqMatches":[{"year":"2014","no":1079,"q":"Mini tracheostomy is performed through ?","o":["Cricothyroid membrane","2nd and 3rd tracheal rings","Any of the above","None of the above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1765, 'ENT', 'Miscellaneous', 'Moderate', 'ENT', 41, '{"id":1765,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Moderate","source":"ENT","sourceNo":41,"q":"Which of the following is included in the Levenson criteria for congenital cholesteatoma ?","o":["White mass medial to normal tympanic membrane","Atticoantral perforation of the tympanic membrane","Definite history of otorrhoea","History of prior otologic procedures"],"a":0,"e":"Ans. is ''a'' i.e., White mass medial to normal tympanic membrane Levenson criteria for congenital cholesteatoma","pyqMatches":[{"year":"2014","no":1100,"q":"Which of the following is included in the Levenson criteria for congenital cholesteatoma ?","o":["White mass medial to normal tympanic membrane","Atticoantral perforation of the tympanic membrane","Definite history of otorrhoea","History of prior otologic procedures"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1766, 'ENT', 'Ear', 'Easy', 'ENT', 42, '{"id":1766,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":42,"q":"Which of the following is false regarding Frey''s syndrome?","o":["It is also called gustatory sweating","It is caused by injury to auriculotemporal nerve","It occurs immediately after the parotid surgery","It is caused by aberrant regeneration of post"],"a":2,"e":"Ans. is ''c'' i.e., It occurs immediately after the parotid surgery Frey''s syndrome (gustatory sweating) Gustatory sweating or Frey''s syndrome involves post-parotidectomy facial sweating and skin flushing while eating. The symptoms usually occur several months or even years after parotid surgery. The likely pathophysiology is aberrant regeneration of postganglionic secretomotor parasympathetic nerve fibres (originating from the otic ganglion) misdirected through several axonal sheaths of post- ganglionic sympathetic fibres feeding the sweat glands. These sympathetic fibres are to the sweat glands of the skin in the dissected field. The frey''s syndrome is likely due to injury to auriculotemporal nerve with faulty regeneration, therefore Frey''s syndrome is also known as Auriculotemporal syndrome. A variant of Frey''s syndrome in which there is gustatory facial flushing but not sweating, occurs following facial paralysis due to faulty regeneration following injury to the facial nerve. So, Frey''s syndrome is not limited to parotid surgery with injury to auriculotemporal nerve.","pyqMatches":[{"year":"2014","no":1115,"q":"Which of the following is false regarding Frey''s syndrome?","o":["It is also called gustatory sweating","It is caused by injury to auriculotemporal nerve","It occurs immediately after the parotid surgery","It is caused by aberrant regeneration of post"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1767, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 43, '{"id":1767,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":43,"q":"Most common cause of trigeminal neuralgia ?","o":["Infection","Trauma","Vascular compression","Iatrogenic"],"a":2,"e":"Ans. is ''c'' i.e., Vascular compression Trigeminal neuralgia (tic douloureux) is characterized by intermittent, shooting pain in the face. It is due to involvement of trigeminal nerve. 95% of causes of trigeminal neuralgia are due to pressure on trigeminal nerve close to where it enters the brain stem, past the Gasserian ganglion. In most cases, this pressure seems to be caused by an artery or vein compressing trigeminal nerve. Other causes are tumor, cysts, AV malformation and multiple sclerosis. Most commonly used drugs for treatment of trigeminal neuralgia are carbamazepine, gabapentin and valproate.","pyqMatches":[{"year":"2014","no":1081,"q":"Most common cause of trigeminal neuralgia ?","o":["Infection","Trauma","Vascular compression","Iatrogenic"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1768, 'ENT', 'Ear', 'Hard', 'ENT', 44, '{"id":1768,"subject":"ENT","chapter":"Ear","difficulty":"Hard","source":"ENT","sourceNo":44,"q":"Patient with thin painless otorrhoea, multiple perforations of the tympanic membrane and failure to respond to antimicrobial treatment. What is the most probable causative organism ?","o":["Mycobacterium tuberculosis","Staphylococcus aureus","Candida albicans","Aspegillusfumigatus"],"a":0,"e":"Ans. is ''a'' i.e., Mycobacterium tuberculosis Thin painless otorrhoea, multiple perforations of the tympanic membrane and failure to respond to antimicrobial treatment are the features of tubercular otitis media and it is caused by Mycobacterium tuberculosis.","pyqMatches":[{"year":"2014","no":1111,"q":"Patient with thin painless otorrhoea, multiple perforations of the tympanic membrane and failure to respond to antimicrobial treatment. What is the most probable causative organism ?","o":["Mycobacterium tuberculosis","Staphylococcus aureus","Candida albicans","Aspegillusfumigatus"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1769, 'ENT', 'Ear', 'Easy', 'ENT', 45, '{"id":1769,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":45,"q":"Synkinesis is a sequel of ?","o":["Facial nerve paralysis","Trigeminal nerve paralysis","Superficial temporal nerve paralysis","Greater Petrosal nerve paralysis"],"a":0,"e":"Ans. is ''a'' i.e., Facial nerve paralysis Clinical features of Bell''s palsy Acute onset, ipsilateral facial paralysis. Facial paralysis is usually preceded by pain behind the ear. Patient is unable to close his eyes. Bells phenomenon, i.e. on attempting to close the eye, eyeball turns up and out. Face becomes asymmetrical and saliva dribbles from angle of mouth. Ipsilateral loss of taste sensation, salivation and lacrimation. Intolerance to high pitched or loud sound (hyperacusis). Most patients (80%) recover within few weeks to months. Synkinesis and crocodile tear are sequelae of Bell''s palsy :- Synkinesis or facial synkinesis is a common sequelae to Bell''s palsy. This is due to cross innervation of nerve fibres during recovery. When the patient wishes to close the eye, corner of mouth also twiches and vice versa. Crocodile tear (gustatory lacrimation) is due to faulty regeneration of parasympathetic fibres which now supply lacrimal gland instead of the salivary glands.","pyqMatches":[{"year":"2014","no":1116,"q":"Synkinesis is a sequel of ?","o":["Facial nerve paralysis","Trigeminal nerve paralysis","Superficial temporal nerve paralysis","Greater Petrosal nerve paralysis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1770, 'ENT', 'Ear', 'Easy', 'ENT', 46, '{"id":1770,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":46,"q":"Sago grain appearance is seen in ?","o":["Healed myringitis bullosa","Otomycosis","Malignant otitis externa","Keratosis obturans"],"a":0,"e":"Ans. is ''a'' i.e., Healed myringitis bullosa Otitis externa haemorrhagica This condition is also known as Bullous myringitis or myringitis bullosa. This condition is extremely painful and has sudden onset. It is thought to be due to mycoplasma pneumoniae or viral infection, usually influenza''. There may be a mild conductive deafness and a mildly discharging car. The appearance of haemorrhagic bullae on the tympanic membrane and in the deep meatus is characteristic. The bullae are filled with serosanguinous fluid and blood. On healing, bullae look like Sago-grain. Therefore \"Sago-grain\" appearance of tympanic membrane is seen in healed myringitis bullosa.","pyqMatches":[{"year":"2014","no":1080,"q":"Sago grain appearance is seen in ?","o":["Healed myringitis bullosa","Otomycosis","Malignant otitis externa","Keratosis obturans"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1771, 'ENT', 'Ear', 'Easy', 'ENT', 47, '{"id":1771,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":47,"q":"Following is the preferred treatment of Serous Otitis Media -","o":["Grommet surgery","Oral Amoxicillin for 5 - 10 days","Modified radical mastoidectomy","Bed rest, antipyretics and adequate fluid intake"],"a":0,"e":"Ans. is ''a'' i.e., Grommet surgery Treatment of otitis media Following two treatments have been described : ? 1) Watchful waiting Watchful waiting is the active monitoring of the condition and hearing in anticipation of spontaneous resolution. Guidlines aimed at both primary care and specialist otolaryngologist broadly agree that a watch​ful waiting period for about three months is the initial management of children with serous otitis media. Therefore, unless there are also signs of an infection, most health care providers will not treat SOM at first Instead, they will recheck the problem in 2-3 months. This should be coupled with reassurance that doing nothing is as likely as doing something to result in resolution of the SOM and the associated symptoms. 2) Surgery Surgical intervention is recommended when watchful waiting and monitoring of hearing has confirmed failure of resolution of SOM. Following surgical intervention are used commonly : - i. Myringotomy and aspiration offluid : -An incision is made in tympanic membrane and fluid aspirated with suction. i. Grommet (ventilation tube) surgery : - If myringotomy and aspiration combined with medical measures has not helped and fluid recurs, a grommet is inserted to provide continued aeration of middle ear. This is the most common surgical intervention for SOM. Most prefered site of grommet insertion is antero-inferior through circumferential or radial incision. i. Surgical treatment of causative factor : - Adenoidectomy, tonsillectomy etc. Medical measures are controversial and involve : ?","pyqMatches":[{"year":"2014","no":1109,"q":"Following is the preferred treatment of Serous Otitis Media","o":["Grommet surgery","Oral Amoxicillin for 5 - 10 days","Modified radical mastoidectomy","Bed rest, antipyretics and adequate fluid intake"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1772, 'ENT', 'Throat & Larynx', 'Hard', 'ENT', 48, '{"id":1772,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Hard","source":"ENT","sourceNo":48,"q":"When a patient says Ah the right uvula presses the palate which of the following nerve is damaged ?","o":["Rght X CN","Right XII CN","Left X CN","Right XII CN"],"a":2,"e":"Ans. is ''c'' i.e., Left X CN Assessment of the movement of soft palate - Both IX and X CNs are tested: The glossopharyngeal nerve (IX CN) is a mixed nerve with motor, sensory and some parasympathetic activity. It carries sensory input from the palate and pharynx and the taste from the posterior third of the tongue. It provides afferent limb of the gag reflex. The vagus (X CN) is also a mixed nerve with motor, sensory and parasympathetic activity. It provides the motor supply to the pharynx, soft palate and larynx and provides the efferent limb to the gag reflex. Normally on oral examination thesoft palate is symmetrical with the uvula dangling in the centre and dividing the soft palate. When the patient is asked to say AAAh! The soft palate should elevate symmetrically and the uvula should remain centric. If there is unilateral weakness of the soft palate the uvula is pulled away from the weakened side. Now in the question given when the patient says aaah the right uvula presses the palate i. e. the right side soft palate pulls the uvula away from the weak left side. The weakness of the left soft palate away from the weak left side. The weakness of the left soft palate can be because of the weakness of the left IX or X cranial nerves.","pyqMatches":[{"year":"2014","no":1082,"q":"When a patient says Ah the right uvula presses the palate which of the following nerve is damaged ?","o":["Rght X CN","Right XII CN","Left X CN","Right XII CN"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1773, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 49, '{"id":1773,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":49,"q":"Lumpy feeling in throat relieved on taking food is attributed to ?","o":["Globus pharyngeus","Pharyngeal pouch","Diverticular disease","Esophageal atresia"],"a":0,"e":"Ans. is ''a'' i.e., Globus Pharyngeus Globus Pharyngeus Symptom where in a patient describes something stuck in throat or a sensation of lump or tightness in throat which is relieved by taking food or talking.","pyqMatches":[{"year":"2014","no":1083,"q":"Lumpy feeling in throat relieved on taking food is attributed to ?","o":["Globus pharyngeus","Pharyngeal pouch","Diverticular disease","Esophageal atresia"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1774, 'ENT', 'Ear', 'Easy', 'ENT', 50, '{"id":1774,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":50,"q":"Glomus jugulare commonly arises from ?","o":["Hypotympanum","Mesotympanum","Epitympanum","Prussaks space"],"a":0,"e":"Ans. is ''a'' i.e., Hypotympanum There are two types of glomus tumors:- i) Glomus jugulare These glomus tumors arise from the dome of the internal jugular vein in the hypotympanum and jugular foramen. In jugular foramen they can invade IX to XII cranial nerves. ii) Glomus tympanicum They arise from the promontory of the middle ear along the course of the tympanic branch of the IXth cranial nerve.","pyqMatches":[{"year":"2014","no":1117,"q":"Glomus jugulare commonly arises from ?","o":["Hypotympanum","Mesotympanum","Epitympanum","Prussaks space"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1775, 'ENT', 'Ear', 'Moderate', 'ENT', 51, '{"id":1775,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":51,"q":"Gradenigo syndrome is characterized by all except ?","o":["Diplopia","Retro-orbital pain","Persistent ear discharge","Vertigo"],"a":3,"e":"Ans. is d i.e., Vertigo Infection of mastoid and middle ear may be complicated by the spread of infection within the temporal bone into petrous apex. Petrositis is an extension of infection from middle ear and mastoid to the petrous part of the temporal bone. Gradenigo''s syndrome is the classical presentation and consists of a triad of : - External rectus palsy (VIth nerve/abducent nerve palsy) causing diplopia. Deep seated orbital or retroorbital pain (Vth nerve involvement). Persistent ear discharge due to ipsilateral acute or chronic otitis media. Associated symptoms of otitis media are also present e.g., conductive deafness. Other symptoms are fever, head​ache, vomiting, and sometimes neck rigidity. Some patient may get facial paralysis and recurrent vertigo due to involvement of facial and statoacoustic nerves.","pyqMatches":[{"year":"2013","no":1028,"q":"Gradenigo syndrome is characterized by all except ?","o":["Diplopia","Retro-orbital pain","Persistent ear discharge","Vertigo"],"a":3,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":1107,"q":"Gradenigo syndrome is characterized by all except ?","o":["Diplopia","Retro-orbital pain","Persistent ear discharge","Vertigo"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1776, 'ENT', 'Ear', 'Easy', 'ENT', 52, '{"id":1776,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":52,"q":"Attico antral disease is treated by ?","o":["Modified radical mastoidectomy","Antibiotics","Grommet insertion","Synringing"],"a":0,"e":"Ans. is ''a'' i.e., Modified radical mastoidectomy Treatment of atticoantral disease Since cholesteatoma is going to expand and destroy bone and mucous membrane, it has to be removed. Therefore, surgery is the mainstay of treatment. Primary aim is removal of disease by mastoidectomy to make ear safe followed by reconstruction of hearing at a later stage. Modified radical mastoidectomy is the surgery of choice. Two types of surgical procedures (mastoidectomy) are done to deal with cholesteatoma. 1) Canal wall down procedures These leave the mastoid cavity open into the external auditory canal so that the diseased area is fully exteriorized. The commonly used procedures for atticoantral disease are atticotomy, modified radical mastoidectomy and rarely radical mastoidectomy. Modified radical mastoidectomy is the procedure of choice. 2) Canal wall up procedures (cortical mastoidectomy) Here disease is removed by combined approach through the meatus and mastoid but retaining the posterior bony meatus wall, thereby avoiding an open mastoid cavity. For reconstruction of hearing mechanism myringoplasty or tympanoplasty can be done at the time of primary surgery or as a second stage procedure.","pyqMatches":[{"year":"2014","no":1105,"q":"Attico antral disease is treated by ?","o":["Modified radical mastoidectomy","Antibiotics","Grommet insertion","Synringing"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1777, 'ENT', 'Nose & Paranasal Sinuses', 'Hard', 'ENT', 53, '{"id":1777,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Hard","source":"ENT","sourceNo":53,"q":"Samters triad is seen in patients with ?","o":["Asthma","Chronic pancreatitis","Crohn''s disease","Liver cell carcinoma"],"a":0,"e":"Ans. is ''a'' i.e., Asthma Samter''s triad Samter''s triad is a medical condition consisting of asthma, aspirin sensitivity, and nasal/ethmoidal polyposis. It occurs in middle age (twenties and thirties are the most common onset times) and may not include any allergies. Most commonly, the first symptom is rhinitis. The disorder typically progeses to asthma, then polyposis, with aspirin sensitivity coming last. The aspirin reaction can be severe, including an asthma attack, anaphylaxis, and urticaria in some cases. Patients typically react to other NSAIDS such as ibuprofen, although paracetamol is generally considered safe. Anosmia (lack of smell) is also typical, as the inflammation reaches the olfactory receptors in the nose.","pyqMatches":[{"year":"2014","no":1129,"q":"Samters triad is seen in patients with ?","o":["Asthma","Chronic pancreatitis","Crohn''s disease","Liver cell carcinoma"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1778, 'ENT', 'Ear', 'Easy', 'ENT', 54, '{"id":1778,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":54,"q":"Strawberry tongue is seen in ?","o":["Streptococcal scarlet fever","Kawasaki disease","Both of the above","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., Both of the above Strawberry tongue It is also called raspberry tongue It basically refers to glossitis, which manifests with hyperplastic (enlarged) fungiform papillae, giving the appearance of a strawberry. White strawberry tongue is where there is a white coating on the tongue through which the hyperplastic fungiform papillae protrude. Red strawberry tongue is where the white coating is lost and a dark red, erythematous surface is revealed, interspaced with the hyperplastic fungiform papillae. White strawberry tongue is seen in early scarlet fever (a systemic infection of group A hemolytic streptococci). Red strawberry tongue occurs later, after 4-5 days. Other conditions in which strawberry tongue is seen are: Kawasaki disease, toxic shock syndrome, and vitamin B 12 deficiency.","pyqMatches":[{"year":"2014","no":1084,"q":"Strawberry tongue is seen in ?","o":["Streptococcal scarlet fever","Kawasaki disease","Both of the above","None of the above"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1779, 'ENT', 'Ear', 'Moderate', 'ENT', 55, '{"id":1779,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":55,"q":"All are true for gradenigo''s syndrome except ?","o":["Associated with intermittent ear discharge","Associated with conductive hearing loss","Causes diplopia","Leads to retro orbital pain"],"a":0,"e":"Ans. is ''a'' i.e., Associated with intermittent ear discharge Gradenigo''s syndrome, also called Gradenigo-Lannois syndrome, is a complication of otitis media and mastoiditis involving the apex of the petrous temporal bone. Symptoms Components of the syndrome include: retroorbital pain due to pain in the area supplied by the ophthalmic branch of the trigeminal nerve (fifth cranial nerve), abducens nerve palsy (sixth cranial nerve) otitis media Other symptoms can include photophobia, excessive lacrimation, fever, and reduced corneal sensitivity. The syndrome is classically caused by the spread of an infection into the petrous apex of the temporal bone.","pyqMatches":[{"year":"2014","no":1108,"q":"All are true for gradenigo''s syndrome except ?","o":["Associated with intermittent ear discharge","Associated with conductive hearing loss","Causes diplopia","Leads to retro orbital pain"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1780, 'ENT', 'Ear', 'Easy', 'ENT', 56, '{"id":1780,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":56,"q":"Treatment of middle ear papilloma is ?","o":["Myringotomy and simple excision","Myringectomy and simple excision","Tympanomastoidectomy","Local infiltration with podophyllin"],"a":2,"e":"Ans. is ''c'' i.e., Tympanomastoidectomy Middle ear pappilomas The middle ear papillomas are rare presentations and medical literature is mainly limited to case reports or case series. These include aggressive pappilary tumors, schneiderian type of pappilomas and inverted pappilomas. They are associated with hearing difficulty and vertigo and may be associated with Von Hippel Lindau syndrome. They tend to be slowly growing, locally aggressive non metastasizing neoplasms The approach for treatment of such pathology is usually radical and tympanomastoidectomy is considered the treatment of choice. This gives the best chance of cure.","pyqMatches":[{"year":"2014","no":1085,"q":"Treatment of middle ear papilloma is ?","o":["Myringotomy and simple excision","Myringectomy and simple excision","Tympanomastoidectomy","Local infiltration with podophyllin"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1781, 'ENT', 'Ear', 'Easy', 'ENT', 57, '{"id":1781,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":57,"q":"Best time for hearing assessment in an infant ?","o":["1st month of life","3-6 months","6-9 months","9-12 months"],"a":0,"e":"Ans. is ''a'' i.e., 1st month of life The American Academy of Pediatrics (AAP), Joint Committee on Infant hearing (2007), has recommended that all newborn infants be screened for hearing impairment either as neonate or before 1 month of age and that those infants who fail newborn screening have an audiologic examination to varify hearing loss before age of 3 months.","pyqMatches":[{"year":"2014","no":1086,"q":"Best time for hearing assessment in an infant ?","o":["1st month of life","3-6 months","6-9 months","9-12 months"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1782, 'ENT', 'Ear', 'Easy', 'ENT', 58, '{"id":1782,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":58,"q":"Darwin tubercle is seen in ?","o":["Tragus","Helix","Antihelix","Lobule"],"a":1,"e":"Ans. is ''b'' i.e., Helix Darwin''s tubercle (or auricular tubercle) is a congenital earcondition which often presents as a thickening on the helix at the junction of the upper and middle thirds. The feature is present in approximately 10.4% of the population.This acuminate nodule represents the point of the mammalian ear.","pyqMatches":[{"year":"2014","no":1088,"q":"Darwin tubercle is seen in ?","o":["Tragus","Helix","Antihelix","Lobule"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1783, 'ENT', 'Miscellaneous', 'Moderate', 'ENT', 59, '{"id":1783,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Moderate","source":"ENT","sourceNo":59,"q":"Trotter triad not included is ?","o":["Conductive deafness","Temporoparietal neuralgia","Palatal paralysis","Seizures"],"a":3,"e":"Ans. is ''d'' i.e., Seizures Trotter''s triad Trotter''s triad occurs in nasopharyngeal carcinoma It includes :- i) Conductive deafness (due to Eustachian tube blockage) ii) Temporo - parietal neuralgia (due to involvement of ipsilateral Vth cranial nerve) iii) Palatal paralysis (due to involvement of Xth cranial nerve)","pyqMatches":[{"year":"2014","no":1131,"q":"Trotter triad not included is ?","o":["Conductive deafness","Temporoparietal neuralgia","Palatal paralysis","Seizures"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1784, 'ENT', 'Ear', 'Moderate', 'ENT', 60, '{"id":1784,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":60,"q":"Following protein is not found in organ of corti ?","o":["Myosin","Microtubule associated protein 2","Microtubule associated protein 4","Fodrin"],"a":2,"e":"Ans. is ''c'' i.e., Microtubule associated protein 4 Proteins present in cochlea Actin-binding and microtubule-associated proteins regulate microfilament and microtubule number, length, organization and location in cells. In freeze-dried preparations of the guinea pig cochlea, both actin and tubulin are found in the sensory and supporting cells of the organ of Corti. Fodrin (brain spectrin) co-localized with actin in the cuticular plates of both inner and outer hair cells and along the lateral wall of the outer hair cells. Alpha-actinin co-localized with actin in the cuticular plates of the hair cells and in the head and foot plates of the supporting cells. It was also found in the junctional regions between hair cells and supporting cells. o Profilin co-localized with actin in the cuticular plates of the sensory hair cells. Myosin was detected only in the cuticular plates of the outer hair cells and in the supporting cells in the region facing endolymph. Gelsolin was found in the region of the nerve fibers. Tubulin is found in microtubules in all cells of the organ of Corti. In supporting cells, microtubules are bundled together with actin microfilaments and tropomyosin, as well as being present as individual microtubules arranged in networks. An intensely stained network of microtubules is found in both outer and inner sensory hair cells. The microtubules in the outer hair cells appear to course throughout the entire length of the cells, and based on their staining with antibodies to the tyrosinated form of tubulin they appear to be more dynamic structures than the microtubules in the supporting cells. The microtubule-associated protein MAP-2 is present only in outer hair cells within the organ of Corti and co-localizes with tubulin in these cells. No other MAPs (1,3,4,5) are present. Tau is found in the nerve fibers below both inner and outer hair cells and in the osseous spiral lamina.","pyqMatches":[{"year":"2014","no":1087,"q":"Following protein is not found in organ of corti ?","o":["Myosin","Microtubule associated protein 2","Microtubule associated protein 4","Fodrin"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1785, 'ENT', 'Throat & Larynx', 'Moderate', 'ENT', 61, '{"id":1785,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Moderate","source":"ENT","sourceNo":61,"q":"Following is true about laryngomalacia except ?","o":["Omega shaped epiglottis","Reassuarance of the patient is the treatment of choice","Condition is first noticed in the first few weeks of life","Expiratory stridor"],"a":3,"e":"Ans. is ''d'' i.e., Expiratory stridor Laryngomalacia It is the most common congenital abnormality of the larynx. Laryngomalacia is the most frequent cause of stridor or noisy breathing in infants. It occurs as a result of a floppy portion of the larynx (in supraglottic larynx) that has not yet developed the strength to provide rigid support to the airway. During inspiration negative pressure is created through larynx, which results in a collapse of these structures into the airway and a narrower breathing passage. Partial obstruction is the source of the noise with breathing (stridor), and sometimes cyanosis. The hallmark sign includes intermittent stridor mostly in inspiration. It is usually more prominent when the infant is lying on his/her back (supine position, crying, feeding, excited or has a cold. Stridor gets relieved on placing the patient in prone position. This is usually first noticed in the first few weeks of life. It may worsen over the first few months and become louder. This is because as the baby grows, inspiratory force is greater, which causes greater collapse of the laryngeal structures into the airway. This is usually worst at 3-6 months and then gradually improves as the rigidity of the cartilage improves. Most children are symptom free by 1 to 2 years. Sometimes, cyanosis may occur. Direct laryngoscopy shows :- Omega shaped epiglottis, i.e. elongated and curled on itself. Floopy, tall, foreshortened and thin aryepiglottic folds. Prominent arytenoids. In most patients laryngomalacia is a self limiting condition. Treatment of laryngomalacia is reassurance to the parents and early antibiotic therapy for upper respiratory tract infections.","pyqMatches":[{"year":"2014","no":1132,"q":"Following is true about laryngomalacia except ?","o":["Omega shaped epiglottis","Reassuarance of the patient is the treatment of choice","Condition is first noticed in the first few weeks of life","Expiratory stridor"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1786, 'ENT', 'Ear', 'Hard', 'ENT', 62, '{"id":1786,"subject":"ENT","chapter":"Ear","difficulty":"Hard","source":"ENT","sourceNo":62,"q":"Following are the laboratory tests for the diagnosis of vestibular dysfunction except ?","o":["Electronystagmography","Optokinetic test","Galvanic test","Gelle''s test"],"a":3,"e":"Ans. is ''d'' i.e., Gelle''s test Vestibular system The vestibular system contributes to balance and to the sense of spatial orientation. It is a sensory system that provides the leading contribution about movement and sense of balance. It includes the labyrinth (semicircular canals and otolith : utricle & sacules) of the inner ear and is situated in the vestibulum in the inner ear. The symptoms of vestibular dysfunction are vertigo, dizziness and Unbalance.","pyqMatches":[{"year":"2014","no":1118,"q":"Following are the laboratory tests for the diagnosis of vestibular dysfunction except ?","o":["Electronystagmography","Optokinetic test","Galvanic test","Gelle''s test"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1787, 'ENT', 'Ear', 'Hard', 'ENT', 63, '{"id":1787,"subject":"ENT","chapter":"Ear","difficulty":"Hard","source":"ENT","sourceNo":63,"q":"In a patient with CSOM, labrynthine fistula most commnonly involves ?","o":["Superior SCC","Lateral SCC","Posterior SCC","Utricle"],"a":1,"e":"Ans. is ''b'' i.e., Lateral SCC Labrynthine fistula is almost exclusively reported in association with chronic otitis media and cholesteatoma. The most commonly affected canal is lateral (horizontal) semicircular canal, but involvement of the posterior and superior canals as well as other regions of labyrinth have been reported. The incidence of labrynthine fistula in chronic otitis media is approximately 10%.","pyqMatches":[{"year":"2014","no":1106,"q":"In a patient with CSOM, labrynthine fistula most commnonly involves ?","o":["Superior SCC","Lateral SCC","Posterior SCC","Utricle"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1788, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 64, '{"id":1788,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":64,"q":"Horizontal acceleration with forward movement in the sagittal plane is detected by ?","o":["Macula of Utricle","Macula of Saccule","Lateral semicircular canal","Posterior semicircular canal"],"a":0,"e":"Ans. is ''a'' i.e., Macula of utricle","pyqMatches":[{"year":"2014","no":1120,"q":"Horizontal acceleration with forward movement in the sagittal plane is detected by ?","o":["Macula of Utricle","Macula of Saccule","Lateral semicircular canal","Posterior semicircular canal"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1789, 'ENT', 'Ear', 'Hard', 'ENT', 65, '{"id":1789,"subject":"ENT","chapter":"Ear","difficulty":"Hard","source":"ENT","sourceNo":65,"q":"Patient presents with mouth breathing, recurrent serous otitis media and adenoid facies. What is the best line of management ?","o":["Adenoidectomy","Tonsillectomy","Antibiotics","Supportive therapy"],"a":0,"e":"Ans. is ''a'' i.e., Adenoidectomy The triad of nasal and aural symptoms with adenoid facies points to the diagnosis of enlarged adenoids. For the treatment of enlarged adenoids when symptoms are not marked breathing excercise, decongenstant nasal drops and antihistaminics are used and when symptoms are marked, adenoidectomy is done. We have a patient with marked and recurrent symptoms thus adenoidectomy is the treatment of choice.","pyqMatches":[{"year":"2014","no":1133,"q":"Patient presents with mouth breathing, recurrent serous otitis media and adenoid facies. What is the best line of management ?","o":["Adenoidectomy","Tonsillectomy","Antibiotics","Supportive therapy"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1790, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 66, '{"id":1790,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":66,"q":"Which of the following organisms is known to cause Atrophic rhinitis ?","o":["Klebsiella ozaena","Klebsiella pneumonia","Streptococcus pneumonia","Streptococcus foetidis"],"a":0,"e":"Ans. is ''a'' i.e., Klebsiella ozaena Atrophic rhinitis (Ozaena) Atrophic rhinitis is a chronic inflammation of nose characterized by atrophy of nasal mucosa, including the glands, turbinate bones and the nerve elements. Atrophic rhinitis may be primary or secondary : ? 1) Primary atrophic rhinitis The primary pathology is inflammation and atrophy of the nose. Generally, atrophic rhinitis refers to primary atrophic rhinitis. Causes are : - i) Hereditary ii) Endocrinal pathology - Starts at puberty. Stops after menopause iii) Racial factors - Seen more in Whites and Yellow races iv) Nutritional deficiency - Deficiency of vitamin A, D, E and iron may be responsible for it. v) Infective - Klebsiella ozanae, Diphtheriods, P. vulgaris, E.coli, Staphylococci, Streptococci. vi) Autoimmune process - Causing destruction of nasal, neurovascular and glandular elements may be the cause. 2) Secondary atrophic rhinitis Specific infections, such as syphilis, lupus, leprosy, and rhinoscleroma, may cause destruction of the nasal structures leading to atrophic changes. Can also results from long standing purulent sinusitis , radiotherapy of nose, excessive surgical removal of the turbinate and as complication of DNS on the root side of nose.","pyqMatches":[{"year":"2014","no":1135,"q":"Which of the following organisms is known to cause Atrophic rhinitis ?","o":["Klebsiella ozaena","Klebsiella pneumonia","Streptococcus pneumonia","Streptococcus foetidis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1791, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 67, '{"id":1791,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":67,"q":"Potato tumor due to ?","o":["Hypotrophy of sebaceous glands of nose","Hypertrophy of sebaceous glands of nose","Hypotrophy of sweat glands of nose","Hpertrophy of sweat glands of nose"],"a":1,"e":"Ans. is ''b'' i.e., Hypertrophy of sebaceous glands of nose Rhinophyma (Potato tumor) Rhinophyma is large, bulb-shaped, red-colored (ruddy) nose. It is a slow growing benign tumor due to hypertrophy of the sebaceous glands. The cause of rhinophyma is unknown, though it is thought to be a severe form of acne roscea. Rhinophyma was once thought to be caused by heavy alcohol consumption, but this is not the case. Rhinophyma occurs equally in those who do not drink at all and those who drink large quantities of alcohol. It mostly affects men past middle age. Red/pink colour of the tumor is due to engorgment of superficial vessels. Treatment Surgery to reshape the nose is the best known treatment for rhinophyma. Surgery may be done with a laser (carbon dioxide laser), scalpel (sharp knife) or a rotating brush (dermabrasion) and the area is allowed to re-epithelialize. Sometimes, tumour is completely excised and the raw area is skin-grafted.","pyqMatches":[{"year":"2014","no":1091,"q":"Potato tumor due to ?","o":["Hypotrophy of sebaceous glands of nose","Hypertrophy of sebaceous glands of nose","Hypotrophy of sweat glands of nose","Hpertrophy of sweat glands of nose"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1792, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 68, '{"id":1792,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":68,"q":"Rhinitis most common bacterial cause ?","o":["Haemophilus influenza","Streptococcus haemolyticus","Pasturellamultocida","Cornybacterium diphtheria"],"a":0,"e":"Ans. is ''a'' i.e., Haemophilus influenza Acute bacterial rhinitis is most commonly seen among children, but adult may develop the condition after nasal trauma, viral upper respiratory tract infection, or surgery. The clinical presentation of acute bacterial rhinitis may be identical to that of common cold. Most common causative organisms include S. pneumoniae, H. influenzae and Moraxella Catarrhalis. Note: Overall, most common cause of infective rhinitis is viral infection (viral rhinitis).","pyqMatches":[{"year":"2014","no":1134,"q":"Rhinitis most common bacterial cause ?","o":["Haemophilus influenza","Streptococcus haemolyticus","Pasturellamultocida","Cornybacterium diphtheria"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1793, 'ENT', 'Ear', 'Easy', 'ENT', 69, '{"id":1793,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":69,"q":"Surgical markings for finding the facial nerve is are?","o":["Tympano - mastoid suture","Tragal pointer","Posterior belly of digastric","All the above"],"a":0,"e":"Ans. is ''a'' i.e., Tympano-mastoid suture Surgical landmarks to identify main trunk of the facial nerve are as follows: i. Tympanomastoid suture line - it is located between the mastoid and the tympanic bones. The main facial trunk lies 6 -8 mm distal to the end of the suture. i. Tragal pointer - the main nerve trunk lies 1.0 to 1.5 cm deep and slightly anterior and inferior to the tip of the external ear canal cartilage. i. Posterior belly of digastric -the main nerve trunk lies 1 cm deep to the medial attachment of the posterior belly of digastric muscle to the digastric groove (mastoid notch) of the mastoid bone. v. Mastoid bone - main nerve trunk is identified inside the mastoid bone by mastoidectomy.","pyqMatches":[{"year":"2014","no":1092,"q":"Surgical markings for finding the facial nerve is are?","o":["Tympano - mastoid suture","Tragal pointer","Posterior belly of digastric","All the above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1794, 'ENT', 'Ear', 'Easy', 'ENT', 70, '{"id":1794,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":70,"q":"Central part of cholesteatoma contains ?","o":["Keratin debris","Keratinized squamous epithelium","Coulmnar epithelium","Fibroblasts"],"a":0,"e":"Ans. is ''a'' i.e., Keratin debris Cholesteatoma Destructive or expanding growth in the middle ear or mastoid process The term cholesteatoma is a misnomer, because it neither contains cholesterol crystals nor is it a tumor to merit the suffix `oma''. Cholesteatoma has the property to destroy bone. It may cause destruction of ear ossicles, erosion of bony labyrinth, canal of facial nerve, sinus plate or tegmen tympani and thus cause several complications. Bone destruction by cholesteatoma has been attributed to various proteolytic enzymes liberated by osteoclasts and mononuclear inflammatory cells, seen in association with cholesteatoma. Cholesteatoma consists of two parts : ? i) Matrix : - Made up of keratinizing squamous epithelium. ii) Keratin debris (central white mass) : - Produced by the matrix. Therefore, cholesteatoma also referred to as epidermosisor keratoma.","pyqMatches":[{"year":"2014","no":1099,"q":"Central part of cholesteatoma contains ?","o":["Keratin debris","Keratinized squamous epithelium","Coulmnar epithelium","Fibroblasts"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1795, 'ENT', 'Miscellaneous', 'Moderate', 'ENT', 71, '{"id":1795,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Moderate","source":"ENT","sourceNo":71,"q":"Which of the following is not a cause of oropharyngeal carcinoma?","o":["Occupational exposue to hydrochloric acid","Smoking","Human Papilloma Virus infection","Occupational exposure to isopropyl oil"],"a":0,"e":"Ans. is ''a'' i.e., Occupational exposure to hydrochloric acid Etiology of oropharyngeal carcinoma i. Tobacco in any form - cigarette smoking or chewing i. Heavy alcohol abuse i. Beetle nut chewing v. Plummer vinson syndrome, cirrhosis v. Syphilis i. Trauma i. Dental irritation i. Poor oral hygiene x. Occupational exposure to isopropyl alcohol, sulphuric acid and nickel x. HPV infection","pyqMatches":[{"year":"2014","no":1093,"q":"Which of the following is not a cause of oropharyngeal carcinoma?","o":["Occupational exposue to hydrochloric acid","Smoking","Human Papilloma Virus infection","Occupational exposure to isopropyl oil"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1796, 'ENT', 'Throat & Larynx', 'Easy', 'ENT', 72, '{"id":1796,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Easy","source":"ENT","sourceNo":72,"q":"False regarding the foreign body of oropharynx is ?","o":["Impacted foreign bodies most often lodge in the soft tissue at the base of tongue","Food particles are the most common oropharyngeal foreign bodies in children","Clinical hypopharyngeal foreign bodies are amenable to clinical examination","Endoscopy and MDCT are used in the diagnosis"],"a":1,"e":"Ans. is ''b'' i.e., Food particles are the most common oropharyngeal foreign bodies in children Oropharyngeal foreign bodies Most ingested foreign bodies do not impact in the oropharynx Sharp foreign bodies like fish and chicken bones most commonly impact in the soft tissues at the base of the tongue. Hypopharyngeal foreign bodies can be detected by good physical examination. Endoscopy and MDCT are used in the diagnosis of foreign bodies of cervical esophagus. Coins are the most common impacted oropharyngeal foreign bodies encountered in children followed by food particles.","pyqMatches":[{"year":"2014","no":1094,"q":"False regarding the foreign body of oropharynx is ?","o":["Impacted foreign bodies most often lodge in the soft tissue at the base of tongue","Food particles are the most common oropharyngeal foreign bodies in children","Clinical hypopharyngeal foreign bodies are amenable to clinical examination","Endoscopy and MDCT are used in the diagnosis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1797, 'ENT', 'Miscellaneous', 'Moderate', 'ENT', 73, '{"id":1797,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Moderate","source":"ENT","sourceNo":73,"q":"Not a test for Eustachian tube patency ?","o":["Tympanometry","Toynbee","Valsalva","Frenzel maneuver"],"a":0,"e":"Ans. is ''a'' i.e., Tympanometry Tests for Eustachian tubepatency Valsalva test Methylene blue test Sonotubometry Politzer test Toynbee test Frenzel maneuver Catheterization Inflation - Deflation test","pyqMatches":[{"year":"2014","no":1119,"q":"Not a test for Eustachian tube patency ?","o":["Tympanometry","Toynbee","Valsalva","Frenzel maneuver"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1798, 'ENT', 'Ear', 'Easy', 'ENT', 74, '{"id":1798,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":74,"q":"Tympanoplasty deals with reconstruction of -","o":["Tympanic membrane","Ossicular chain","Both a and b","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., Both a and b Tympanoplasty is the surgical operation performed for reconstruction of tympanic membrane and/or middle ear ossicles. Myringoplasty is the reconstruction of tympanic membrane. Ossiculoplasty is the reconstruction of ossicular chain. Tympanoplasty = Myringoplasty ± ossiculoplasty","pyqMatches":[{"year":"2014","no":1141,"q":"Tympanoplasty deals with reconstruction of","o":["Tympanic membrane","Ossicular chain","Both a and b","None of the above"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1799, 'ENT', 'Ear', 'Easy', 'ENT', 75, '{"id":1799,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":75,"q":"Most common organism cultured in CSOM is ?","o":["Staphylococcus aureus","Staphylococcus epidermidis","Streptococcus pneumonia","Pseudomonas aeruginosa"],"a":3,"e":"Ans. is ''d'' i.e., Pseudomonas aeruginosa Microbiology of CSOM Pus culture in both types of aerobic and anaerobic CSOM may show multiple organisms. Most commonly isolated organisms are gram negative bacilli, i.e., Pseudomonas, proteus, E.coli. These organisms are not commonly found in the respiratory tract, while commonly found in the skin of external ear.","pyqMatches":[{"year":"2014","no":1103,"q":"Most common organism cultured in CSOM is ?","o":["Staphylococcus aureus","Staphylococcus epidermidis","Streptococcus pneumonia","Pseudomonas aeruginosa"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1800, 'ENT', 'Nose & Paranasal Sinuses', 'Moderate', 'ENT', 76, '{"id":1800,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Moderate","source":"ENT","sourceNo":76,"q":"Fowl smelling nasal discharge is seen in all except?","o":["Nasal Myiasis","Choanal atresia","Foreign body in nose","Rhinolith"],"a":1,"e":"Ans. is `b'' i.e., Choanal atresia Diseases with fowl smelling nasal discharge are: Nasal myiasis Foreign body in nose Rhinolith In choanal atresia there is presence of nasal discharge without air bubbles.","pyqMatches":[{"year":"2014","no":1096,"q":"Fowl smelling nasal discharge is seen in all except?","o":["Nasal Myiasis","Choanal atresia","Foreign body in nose","Rhinolith"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1801, 'ENT', 'Throat & Larynx', 'Easy', 'ENT', 77, '{"id":1801,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Easy","source":"ENT","sourceNo":77,"q":"Rhinoscleroma occurs due to ?","o":["Autoimmune cause","Inflammatory cause","Klebsiella rhinoscleromatis infection","Mycotic infection"],"a":2,"e":"Ans. is ''c'' i.e., Klebsiellarhinoscleromatis infection Rhinoscleroma The causative organism is Klebsiellarhinosclerontatisor Frisch bacillus, which can be cultured from the biopsy material. The disease is endemic in several parts of world. In India, it is seen more often in northern than in the southern parts. Biopsy shows infiltration of submucosa with plasma cells, lymphocytes, eosinophils, Mikulicz cells & Russell bodies. The latter two are diagnostic features of the disease. The disease starts in the nose & extends to nasopharynx, oropharynx, larynx, trachea & bronchi. Mode of infection is unknown. Both sexes of any age may be affected.","pyqMatches":[{"year":"2014","no":1139,"q":"Rhinoscleroma occurs due to ?","o":["Autoimmune cause","Inflammatory cause","Klebsiella rhinoscleromatis infection","Mycotic infection"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1802, 'ENT', 'Ear', 'Easy', 'ENT', 78, '{"id":1802,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":78,"q":"Cauliflower ear is due to ?","o":["Hematoma","Carcinoma","Fungal infection","Herpes"],"a":0,"e":"Ans. is ''a'' i.e., Hematoma Hematoma of the auricle It is the collection of blood between the auricular cartilage and its perichondrium. It usually occurs due to blunt trauma and often seen in boxers, wrestlers and rugby players, therefore it is also called Boxer''s ear. Extravasated blood may clot and then organise, resulting in typical deformity called, Cauliflower ear. If hae​matoma gets infected, severe perichondritis may set in.","pyqMatches":[{"year":"2014","no":1097,"q":"Cauliflower ear is due to ?","o":["Hematoma","Carcinoma","Fungal infection","Herpes"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1803, 'ENT', 'Ear', 'Moderate', 'ENT', 79, '{"id":1803,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":79,"q":"Fowl smelling ear discharge with presence of pale granulation tissue in ear in an adolescent boy is suggestive of ?","o":["Cholesteatoma","Exostosis","Otomycosis","Malignant otitis externa"],"a":0,"e":"Ans. is ''a'' i.e., Cholesteatoma Fowl smelling ear discharge with presence of granulation tissue in earin adolescent boy is suggestive chronic suppurativeotits media of the unsafe type (atticoantral disease). Such patients have underlying cholesteatoma along with evidence of bone destruction. Clinical features of cholesteatoma/atticoantral CSOM Otorrhoea :- Scanty, foul smelling discharge due to bone destruction. Hearing loss :- Initially conductive due to destruction of ossicles. Later sensorineural element may be added, which results in mixed hearing loss. Bleeding :- May occur from granulation or the polyp when cleaning the ear. Tympanic membrane show posterior marginal or attic perforation. Also granulation tissue and polyps may be present in ear.","pyqMatches":[{"year":"2014","no":1098,"q":"Fowl smelling ear discharge with presence of pale granulation tissue in ear in an adolescent boy is suggestive of ?","o":["Cholesteatoma","Exostosis","Otomycosis","Malignant otitis externa"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1804, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 80, '{"id":1804,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":80,"q":"Complication of trauma to danger area of face ?","o":["Cavernous sinus infection","Meningitis","Visual loss","Loss of memory"],"a":0,"e":"Ans. is ''a'' i,e., Cavernous sinus infection The area of upper lip and the lower part of nose is the danger area of face. It is due to that this area is the common site of infection. This area is drained by facial vein which communicates with the cavernous sinus through the superior ophthalmic vein and pterygoid venous plexus through the emissary vein. In case of any infection of this area it may spread to the cavernous sinus causing infection and/or thrombosis.","pyqMatches":[{"year":"2014","no":1140,"q":"Complication of trauma to danger area of face ?","o":["Cavernous sinus infection","Meningitis","Visual loss","Loss of memory"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1805, 'ENT', 'Ear', 'Easy', 'ENT', 81, '{"id":1805,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":81,"q":"Presence of delta sign on contrast enhanced CT SCAN suggests presence of ?","o":["Lateral Sinus thrombophlebitis","Cholesteatoma","Cerebellar abscess","Mastoiditis"],"a":0,"e":"Ans. is ''a'' i.e., Lateral Sinus thrombophlebitis LATERAL SINUS THROMBOPHLEBITIS (SIGMOID SINUS THROMBOSIS) Lateral or sigmoid sinus thrombophlebitis arises from inflammation in the adjacent mastoid. It may occur as a complication of : ? i. Acute coalescent mastoiditis i. CSOM and cholesteatoma Clinical features Hectic Picket-Fence type of fever with rigor. Headache, Progressive anemia and emaciation. Griesinger''s sign : - odema over the posterior part of mastoid due to thrombosis of mastoid emissary veins. Papilloedema Tobey-Ayer test :- Compression of vein on the thrombosed side produces no effect while compression of vein on healthy side produces rapid rise in CSF pressure which will be equal to bilateral compression of jugular veins. Crowe-Beck test :- Pressure on jugular vein of healthy side produces engorgement of retinal veins. Pressure on affected side does not produce such change. Tenderness along jugular vein Imaging studies Contrast-enhanced CT scan can show sinus thrombosis by typical delta-sign. It is a triangular area with rim enhancement, and central low density area is seen in posterior cranial fossa on axial cuts. Delta-sign may also be seen on contrast enhanced MRI.","pyqMatches":[{"year":"2014","no":1124,"q":"Presence of delta sign on contrast enhanced CT SCAN suggests presence of ?","o":["Lateral Sinus thrombophlebitis","Cholesteatoma","Cerebellar abscess","Mastoiditis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1806, 'ENT', 'Ear', 'Easy', 'ENT', 82, '{"id":1806,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":82,"q":"Ostmann fat pad is related to ?","o":["Ear lobule","Buccal mucosa","Eustachian tube","Tip of nose"],"a":2,"e":"Ans. is ''c'' i.e., Eustachian tube There are small fat bodies located infermedial to Eustachian tube. These are called Ostmann fat pads. They are important in normal closure of eustachian tube and preventing transmission of nasopharyngeal pressure to middle ear. These fat pads are absent in Patulous tube syndrome.","pyqMatches":[{"year":"2014","no":1095,"q":"Ostmann fat pad is related to ?","o":["Ear lobule","Buccal mucosa","Eustachian tube","Tip of nose"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1807, 'ENT', 'Ear', 'Moderate', 'ENT', 83, '{"id":1807,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":83,"q":"Which of the following structures is not at immediate risk of erosion by cholesteatoma ?","o":["Long process of incus","Fallopian canal containing facial nerve","Horizontal/ lateral semicircular canal","Base plate of stapes"],"a":3,"e":"Ans. is ''d'' i.e., Base plate of stapes Cholesteatoma has the property to destroy the bone by virtue of the enzymes released by it. Structures immediately at the risk of erosion are : - i. Long process of incus. i. Fallopian canal containing facial nerve. i. Horizontal / lateral semicircular canal","pyqMatches":[{"year":"2014","no":1101,"q":"Which of the following structures is not at immediate risk of erosion by cholesteatoma ?","o":["Long process of incus","Fallopian canal containing facial nerve","Horizontal/ lateral semicircular canal","Base plate of stapes"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1808, 'ENT', 'Ear', 'Hard', 'ENT', 84, '{"id":1808,"subject":"ENT","chapter":"Ear","difficulty":"Hard","source":"ENT","sourceNo":84,"q":"When the patient fails to understand normal speech, but can understand shouted or amplified speech the hearing loss, is termed ?","o":["Mild hearing loss","Moderate hearing loss","Severe hearing loss","Profound hearing loss"],"a":2,"e":"Ans. is ''c'' i.e., Severe hearing loss Severe hearing loss What is severe hearing loss? On average, the most quiet sounds heard by people with their better ear are between 70 and 95 dB. People who suffer from severe hearing loss will benefit from powerful hearing aids, but often they rely heavily on lip-reading even when they are using hearing aids. Some also use sign language.","pyqMatches":[{"year":"2014","no":1123,"q":"When the patient fails to understand normal speech, but can understand shouted or amplified speech the hearing loss, is termed ?","o":["Mild hearing loss","Moderate hearing loss","Severe hearing loss","Profound hearing loss"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1809, 'ENT', 'Throat & Larynx', 'Moderate', 'ENT', 85, '{"id":1809,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Moderate","source":"ENT","sourceNo":85,"q":"Most common site for carcinoma pharynx in females suffering from plummer vinson syndrome is","o":["Post cricoid region","Posterior wall","Lateral wall","Pyriformis fossa"],"a":0,"e":"Ans. is ''a'' i.e., Post cricoid Plummer-Vinson syndrome Plummer-Vinson syndrome, also known as Brown-Kelly-Paterson syndrome or sederopenic dysphagia, seen in middle aged edentulous women. The plummer Vinsion Paterson Brown Kelly Syndrome is characterized by : - Dysphagia Chronic iron deficiency anemia Atrophic oral mucosa and glossitis Brittle, spoon-shaped fingernails (Koilonychia) The cause of dysphagia is usually a cervical esophageal web, but abnormal pharyngeal and esophageal motility may play a role. The syndrome characterstically occurs in middle aged edentulous (without teeth) women. It is a premalignant lesion. Approximately 10% of patient develop squamous cell Ca of esophagus, oral cavity or the hypopharynx. As iron-deficiency anemia is a common finding, it is also known as sideropenic dysphagia. Carcinoma develops in post-cricoid region.","pyqMatches":[{"year":"2014","no":1144,"q":"Most common site for carcinoma pharynx in females suffering from plummer vinson syndrome is","o":["Post cricoid region","Posterior wall","Lateral wall","Pyriformis fossa"],"a":0,"source":"NEET_2014_Paper.pdf"},{"year":"2016","no":475,"q":"Most common site for carcinoma pharynx in females suffering from plummer vinson syndrome is","o":["Post cricoid region","Posterior wall","Lateral wall","Pyriformis fossa"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2014","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1810, 'ENT', 'Throat & Larynx', 'Easy', 'ENT', 86, '{"id":1810,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Easy","source":"ENT","sourceNo":86,"q":"Pyriform fossa is situated in ?","o":["Oropharynx","Hypopharynx","Nasopharynx","None of the above"],"a":1,"e":"Ans. is ''b'' i.e., Hypopharynx Pyriform fossa is a part of laryngopharynx (hypopharynx)","pyqMatches":[{"year":"2014","no":1143,"q":"Pyriform fossa is situated in ?","o":["Oropharynx","Hypopharynx","Nasopharynx","None of the above"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1811, 'ENT', 'Ear', 'Easy', 'ENT', 87, '{"id":1811,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":87,"q":"Incisura terminalis is between ?","o":["Tragus and crux of helix","Ear lobule and antihelix","Antihelix and external auditory meatus","Tragus and ear lobule"],"a":0,"e":"Ans. is ''a'' i.e., Tragus and crux of helix Incisura ternzinalis is the area between the tragus and crus of helix","pyqMatches":[{"year":"2014","no":1089,"q":"Incisura terminalis is between ?","o":["Tragus and crux of helix","Ear lobule and antihelix","Antihelix and external auditory meatus","Tragus and ear lobule"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1812, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 88, '{"id":1812,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":88,"q":"Graft for myringoplasty","o":["Temporalis fascia","Iliacus fascia","Coles fascia","I hotibial band"],"a":0,"e":"Ans. is ''a'' i.e., Temporalis fascia Graft material used for myringoplasty are : i. Temporalis fascia (most common) i. Tragal cartilage i. Perichondrium from the tragus v. Vein","pyqMatches":[{"year":"2014","no":1142,"q":"Graft for myringoplasty","o":["Temporalis fascia","Iliacus fascia","Coles fascia","I hotibial band"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1813, 'ENT', 'Ear', 'Moderate', 'ENT', 89, '{"id":1813,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":89,"q":"Which of the following is not a derivative of the middle ear cleft ?","o":["Semicircular canal","Mastoid air cell","Tympanic cavity","Eustachian tube"],"a":0,"e":"Ans. is ''a'' i.e., Semicircular canal The middle - ear cleft in the temporal bone includes :? i. Eustachian tube i. The middle ear (tympanic cavity) i. Aditus which leads posteriorly to the mastoid antrum and air cells.","pyqMatches":[{"year":"2014","no":1122,"q":"Which of the following is not a derivative of the middle ear cleft ?","o":["Semicircular canal","Mastoid air cell","Tympanic cavity","Eustachian tube"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1814, 'ENT', 'Ear', 'Moderate', 'ENT', 90, '{"id":1814,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":90,"q":"Exostosis due to repetitive exposure to cold water is common in which part of the temporal bone?","o":["Squamous part","Tympanic part","Ptreous part","Mastoid part"],"a":1,"e":"Ans. is ''b'' i.e., Tympanic part Surfer''s ear It is the common name for an exostosis or abnormal bone growth within the external auditory canal. Surfer''s ear is not the same as swimmer''s ear, although infection can result as a side effect. Irritation from cold wind and water exposure causes the bone surrounding the ear canal to develop lumps of new bony growth which constrict the ear canal. The condition is so named due to its prevalence among cold water surfers. Cold water surfers experience surfer''s ear at about six times the rate of warm water surfers. Common site for surfer''s ear is external auditory canal. Tympanic part of the temporal bone is a U shaped curved bony plate that forms most of the part of the external auditory canal. Thus exostosis is common in the tympanic part of the temporal bone. Note: Parts of temporal bone are: squamous, tympanic, styloid, petrous, and mastoid.","pyqMatches":[{"year":"2014","no":1121,"q":"Exostosis due to repetitive exposure to cold water is common in which part of the temporal bone?","o":["Squamous part","Tympanic part","Ptreous part","Mastoid part"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1815, 'ENT', 'Ear', 'Easy', 'ENT', 91, '{"id":1815,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":91,"q":"Ohgren''s line passes from ?","o":["Medial canthus to angle of mandible","Lateral canthus to angle of mandible","Medial canthus to mastoid process","Lateral canthus to mastoid process"],"a":0,"e":"Ans. is ''a'' i.e., Medial canthus to angle of mandible","pyqMatches":[{"year":"2014","no":1125,"q":"Ohgren''s line passes from ?","o":["Medial canthus to angle of mandible","Lateral canthus to angle of mandible","Medial canthus to mastoid process","Lateral canthus to mastoid process"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1816, 'ENT', 'Ear', 'Easy', 'ENT', 92, '{"id":1816,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":92,"q":"Passavant ridge ?","o":["Superior constrictor and palatopharyngeus","Inferior constrictor and palatopharyngeus","Superior constrictor and palatoglossus","Inferior constrictor and palatoglossus"],"a":0,"e":"Passavant ridge Near the superior margin of pharynx, a few fibres of superior constrictor blend with a band of muscle fibres belonging to the palatopharyngeus muscle. These fused fibres form a band or ring around the posterior wall and sidewalls of the nasopharyngeal isthumus. When the soft palate is elevated this muscle band appears as a ridge is known as passavant''s ridge.","pyqMatches":[{"year":"2012","no":111,"q":"Passavant ridge ?","o":["Superior constrictor and palatopharyngeus","Inferior constrictor and palatopharyngeus","Superior constrictor and palatoglossus","Inferior constrictor and palatoglossus"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1817, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 93, '{"id":1817,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":93,"q":"Rhinolith can cause","o":["Nasal obstruction","Epistaxis","Epiphora","All of the above"],"a":3,"e":"A rhinolith is a calculus present in the nasal cavity. The word is derived from the roots rhino- and -lith, literally meaning \"nose stone\". A rhinolith usually forms around the nucleus of a small exogenous foreign body, blood clot or secretion by slow deposition of calcium and magnesium salts. Over a period of time, they grow into large irregular masses that fill the nasal cavity. They may cause pressure necrosis of the nasal septum or lateral wall of nose leading to nasal obstruction, epistaxis, headache, sinusitis and epiphora.","pyqMatches":[{"year":"2016","no":932,"q":"Rhinolith can cause","o":["Nasal obstruction","Epistaxis","Epiphora","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1818, 'ENT', 'Ear', 'Moderate', 'ENT', 94, '{"id":1818,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":94,"q":"All of the following are true about malignant otitis externa except:","o":["ESR is used for follow up after treatment","Granulation tissues are seen on superior wall of the external auditory canal","Severe hearing loss is the chief presenting complaint","Pseudomonas is the most common cause"],"a":2,"e":"Ans. c. Severe hearing loss is the chief presenting complaint Severe hearing loss is not the chief presenting complaint malignant otitis externa. Malignant Otitis Externa: Characterized by granulation tissue in external auditory canal at the junction of bone and cartilage. MC organismz Pseudomonas aeruginosa ESR is raised, used for follow up of treatment","pyqMatches":[{"year":"2016","no":913,"q":"All of the following are true about malignant otitis externa except:","o":["ESR is used for follow up after treatment","Granulation tissues are seen on superior wall of the external auditory canal","Severe hearing loss is the chief presenting complaint","Pseudomonas is the most common cause"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1819, 'ENT', 'Nose & Paranasal Sinuses', 'Moderate', 'ENT', 95, '{"id":1819,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Moderate","source":"ENT","sourceNo":95,"q":"All are true about Rhinoscleroma, except ?","o":["Mikulicz cells","Caused by fungus","More common in Northern area","Woody nose"],"a":1,"e":"Ans. is ''b'' i.e., Caused by fungus Rhinoscleroma is caused by a bacterium. Rhinoscleroma The causative organism is Klebsiella rhinoscleromatis or Frisch bacillus, which can be cultured from the biopsy material. The disease is endemic in several parts of world. In India, it is seen more often in northern than in the southern parts. Biopsy shows infiltration of submucosa with plasma cells, lymphocytes, eosinophils, Mikulicz cells & Russell bodies. The latter two are diagnostic features of the disease. The disease starts in the nose & extends to nasopharynx, oropharynx, larynx, trachea & bronchi. Mode of infection is unknown. Both sexes of any age may be affected. Clinical features of rhinoscleroma The disease runs through the following stages :? a. Atrophic stage : It resembles atrophic rhinitis and is characterised by foul smelling purulent nasal discharge and crusting. b. Granulomatous stage : Granulomatous nodules form in nasal mucosa. There is also subdermal infiltration of lower part of external nose and upper lip giving a ''woody'' feel. Nodules are painless and non-ulcerative. c. Cicatricial stage : This causes stenosis of nares, distortion of upper lip, adhesions in the nose, nasopharynx and oropharynx. There may be subglottic stenosis with respiratory distress. Biopsy of rhinoscleroma shows infiltration of submucosa with plasma cells, lymphocytes, eosinophils, Mikulicz cells and Russell bodies. The latter two are the diagnostic features of the disease. Treatment Both streptomycin & tetracycline are given together for minimum of 4-6 wks. Steroid can be combined to reduce fibrosis. Surgical treatment may be required to establish the airway and correct nasal deformity","pyqMatches":[{"year":"2013","no":1056,"q":"All are true about Rhinoscleroma, except ?","o":["Mikulicz cells","Caused by fungus","More common in Northern area","Woody nose"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1820, 'ENT', 'Ear', 'Easy', 'ENT', 96, '{"id":1820,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":96,"q":"Associated with objective tinnitus?","o":["Meiners disease","Acoustic neuroma","Ear wax","Glomus tumor"],"a":3,"e":"Ans. is `d'' i.e., Glomus tumor Tinnitus Tinnitus is ringing sound or noise in the ear. The characteristic feature is that the origin of this sound is within the patient. Two types of tinnitus have been described : ? a. Subjective I. Otologic II . Non-otologic Impacted wax Disease of CNS Fluid in the middle ear Anaemia Acute and chronic otitis media Arteriosclerosis Abnormally patent eustachian tube Hypertension Meniere''s disease Hypotension Otosclerosis Hypoglycaemia","pyqMatches":[{"year":"2013","no":1045,"q":"Associated with objective tinnitus?","o":["Meiners disease","Acoustic neuroma","Ear wax","Glomus tumor"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1821, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 97, '{"id":1821,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":97,"q":"Which drug is to be given in a truck driver for rhinitis ?","o":["Cetrezine","Hydroxyzine","Promethazine","Buclizine"],"a":0,"e":"Ans. is ''a'' i.e., Cetrezine","pyqMatches":[{"year":"2013","no":535,"q":"Which drug is to be given in a truck driver for rhinitis ?","o":["Cetrezine","Hydroxyzine","Promethazine","Buclizine"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1822, 'ENT', 'Ear', 'Easy', 'ENT', 98, '{"id":1822,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":98,"q":"Schwartze sign seen in?","o":["Glomus Jugulare","Otosclerosis","Meniere''s diseases","Acoustic neuroma"],"a":1,"e":"Ans. is ''b'' i.e., Otosclerosis Symptoms of otosclerosis Hearing loss :- Bilateral conductive deafness which is painless and progressive with insidious onset. In cochlear otosclerosis sensorineural hearing loss also occur along with conductive deafness. Paracusis willissii :- An otosclerotic patient hears better in noisy than quiet surroundings. Tinnitus :- More common in cochlear otosclerosis. Speech :- Monotonous, well modulated soft speech. Vertigo :- is uncommon. Signs in otosclerosis Tympanic membrane is quite normal and mobile. In 10% of cases flamingo - pink blush is seen through the tympanic membrane called as Schwartze sign. Various tests show conductive hearing loss. Tuning fork tests in otosclerosis As otosclerotic patients have conductive deafness, the tuning fork tests results will be as follows :?","pyqMatches":[{"year":"2013","no":1034,"q":"Schwartze sign seen in?","o":["Glomus Jugulare","Otosclerosis","Meniere''s diseases","Acoustic neuroma"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1823, 'ENT', 'Ear', 'Easy', 'ENT', 99, '{"id":1823,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":99,"q":"Galle''s test is used for ?","o":["Otosclerosis","Juvenile angiofibroma","Nasal polyp","None"],"a":0,"e":"Ans. is ''a'' i.e., Otosclerosis Gelle''s test It is a bone conduction test and examines the effect of increased air pressure in ear canal on hearing. Increased air pressure in ear canal (by Siegle''s speculum) pushes the tympanic membrane and ossicles inwards which raises the intralabyrinthine pressure and causes immobility of basilar membrane and decreased hearing. However, if ear ossicles are already fixed or disconnected, the pressure cannot be transfered to inner ear No change in hearing in this situation. Base of vibrating tuning fork is placed on mastoid process and air pressure in ear canal increased (by Siegle''s speculum). Interpretation are : - Positive Gelle''s (decreased hearing on increased pressure)→ Normal or sensorineural hearing loss. h) Negative Gelle''s (No effect of pressure change in hearing) → Disconnected or fixed ossicular chain.","pyqMatches":[{"year":"2013","no":1035,"q":"Galle''s test is used for ?","o":["Otosclerosis","Juvenile angiofibroma","Nasal polyp","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1824, 'ENT', 'Ear', 'Easy', 'ENT', 100, '{"id":1824,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":100,"q":"Macula is stimulated by ?","o":["Gravity","Head position change","Linear acceleration","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above Vestibular apparatus (Peripheral part of vestibular system) The vestibular apparatus within the inner ear detects head motion and position and transduces this information to a neural signal. The vestibular apparatus has following parts :-","pyqMatches":[{"year":"2013","no":995,"q":"Macula is stimulated by ?","o":["Gravity","Head position change","Linear acceleration","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1825, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 101, '{"id":1825,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":101,"q":"Paranasal sinuses present at birth ?","o":["Frontal and maxillary","Ethmoid and maxillary","Frontal and ethmoid","Sphenoid and ethmoid"],"a":1,"e":"Ans. is ''b'' i.e., Ethmoid and maxillary Maxillary sinus → 4 Develop at birth; completely develop at 9 years Ethmoidal sinus → Develop at birth; completely develop at late puberty Frontal sinus → Develop at 2 year; completely develop at late adolescence Spenoid sinus → Develop at 3-5 years; completely develop at 12-15 years","pyqMatches":[{"year":"2013","no":1067,"q":"Paranasal sinuses present at birth ?","o":["Frontal and maxillary","Ethmoid and maxillary","Frontal and ethmoid","Sphenoid and ethmoid"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1826, 'ENT', 'Ear', 'Easy', 'ENT', 102, '{"id":1826,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":102,"q":"Most common bone affected by otosclerosis","o":["External auditory canal","Bony labyrinth","Mastoid process","None"],"a":1,"e":"Ans. is ''b'' i.e., Bony labyrinth Otosclerosis is a primary disease of the bony labyrinth. There is abnormal bone growth that causes hearing loss. There is altered bone remodeling. Normally, the typical human otic capsule remodeling rate is extremely low. In otosclerosis, normal inhibition of bone remodeling is lost resulting in foci of bone remodeling. When remodeled bone bridges the stapediovestibular joint, it fixates the joint and impedes sound transmission manifested as conductive hearing loss. The most common site of disease is promontory in the region of the anterior margin of oval window, and in advanced cases the stapes become ankylosed in position by a mass of new spongy bone. Other sites, which may be involved, are round window area, stapedial footplate, internal auditory canal, and semicircular canal.","pyqMatches":[{"year":"2013","no":1036,"q":"Most common bone affected by otosclerosis","o":["External auditory canal","Bony labyrinth","Mastoid process","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1827, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 103, '{"id":1827,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":103,"q":"Best view for nasal bone ?","o":["Lateral","Towne''s","Cald-well","Submentovertical"],"a":0,"e":"Ans. is ''a'' i.e., Lateral","pyqMatches":[{"year":"2013","no":1106,"q":"Best view for nasal bone ?","o":["Lateral","Towne''s","Cald-well","Submentovertical"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1828, 'ENT', 'Ear', 'Hard', 'ENT', 104, '{"id":1828,"subject":"ENT","chapter":"Ear","difficulty":"Hard","source":"ENT","sourceNo":104,"q":"Lomard''s test is used to diagnosis ?","o":["Conductive hearing loss","Sensorineural hearing loss","Mixed hearing loss","Non-organic hearing loss"],"a":3,"e":"Ans. is ''d'' i.e., Non-organic hearing loss","pyqMatches":[{"year":"2013","no":1004,"q":"Lomard''s test is used to diagnosis ?","o":["Conductive hearing loss","Sensorineural hearing loss","Mixed hearing loss","Non-organic hearing loss"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1829, 'ENT', 'Ear', 'Moderate', 'ENT', 105, '{"id":1829,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":105,"q":"True about serous otitis media are all except ?","o":["Also called glue ear","Affect school going children","Type C tympanogram","Fluid in middle ear"],"a":2,"e":"Ans. is `c'' i.e., Type C tympanogram Serous otitis media Serous otitis media (SOM) has many synonyms : Serous otitis media, otitis media with effusion, glue ear, non-suppurative otitis media, mucoid otitis media, silent otitis media. SOM is an insidious condition in which there is thick or sticky non-purulent fluid behind the eardrum in the middle ear, but there is no ear infection, i.e., effusion of middle ear without infection. Fluid in the middle ear is sterile. SOM occurs most commonly in school going children and SOM is the commonest cause of childhood hearing loss. Etiopathogenesis","pyqMatches":[{"year":"2016","no":917,"q":"True about serous otitis media are all except ?","o":["Also called glue ear","Affect school going children","Type C tympanogram","Fluid in middle ear"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1830, 'ENT', 'Ear', 'Easy', 'ENT', 106, '{"id":1830,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":106,"q":"Cause of myringosclerosis ?","o":["Genetic","Grommet insertion","Otosclerosis","None"],"a":1,"e":"Ans. is ''b'' i.e., Grommet insertion Tvmpanosclerosis Tympanosclerosis is a condition in which there is calcification of tissue in the eardrum (tympanic membrane) and middle ear. Tympanosclerosis may be classified as : -","pyqMatches":[{"year":"2013","no":1017,"q":"Cause of myringosclerosis ?","o":["Genetic","Grommet insertion","Otosclerosis","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1831, 'ENT', 'Ear', 'Easy', 'ENT', 107, '{"id":1831,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":107,"q":"Delta-sign is seen in ?","o":["Petrositis","Acute mastoiditis","Sigmoid sinus thrombosis","Glomus tumor"],"a":2,"e":"Ans. is ''c'' i.e., Sigmoid sinus thrombosis Contrast-enhanced CT scan can show sinus thrombosis by typical delta-sign. It is a triangular area with rim enhancement, and central low density area is seen in posterior cranial fossa on axial cuts. Delta-sign may also be seen on contrast enhanced M RI.","pyqMatches":[{"year":"2013","no":1025,"q":"Delta-sign is seen in ?","o":["Petrositis","Acute mastoiditis","Sigmoid sinus thrombosis","Glomus tumor"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1832, 'ENT', 'Ear', 'Easy', 'ENT', 108, '{"id":1832,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":108,"q":"Trismus is seen in commonly ?","o":["Ludwig angina","Quinsy","Retropharyngeal abscess","Parapharyngeal abscess"],"a":1,"e":"Ans. is ''b'' i.e., Quinsy Trismus is inability to open-mouth. Normal opening of mouth ranges between 25-50mm. Any value less than this is known as trismus (roughly the opening should permit a minimum of three fingers when inserted sideways). Causes of quinsy are :? A. Common causes Infection around impacted third molor Quinsy (peritonsillar abscess) Submucous fibrosis TM joint dysfunction B. Less common causes Ludwings angina Parotid gland infection and tumors Malignant otitis externa or furncle in external auditory canal. Parapharyngeal and retropharyngeal abscess Carcinoma mandible Tetanus Radiation therapy Carcinoma check Malignant hyperthermia Coming to the question Trismus can occur in all the given options. However, it is most common and most characteristic of quinsy (among the given options).","pyqMatches":[{"year":"2013","no":1103,"q":"Trismus is seen in commonly ?","o":["Ludwig angina","Quinsy","Retropharyngeal abscess","Parapharyngeal abscess"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1833, 'ENT', 'Audiology', 'Easy', 'ENT', 110, '{"id":1833,"subject":"ENT","chapter":"Audiology","difficulty":"Easy","source":"ENT","sourceNo":110,"q":"Red line in pure tone audiometry is for -","o":["Bone conduction","Air conduction","Right ear","Left ear"],"a":2,"e":"Ans. is ''c'' i.e., Right ear","pyqMatches":[{"year":"2013","no":1005,"q":"Red line in pure tone audiometry is for","o":["Bone conduction","Air conduction","Right ear","Left ear"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1834, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 111, '{"id":1834,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":111,"q":"Transverse fracture of maxilla is ?","o":["Le Fort-1","Le Fort-2","Le Fort-3","Cranifacial disruction"],"a":0,"e":"Ans. is ''a'' i.e., Le Fort-1 It is classified into 3 types : ?","pyqMatches":[{"year":"2013","no":1073,"q":"Transverse fracture of maxilla is ?","o":["Le Fort-1","Le Fort-2","Le Fort-3","Cranifacial disruction"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1835, 'ENT', 'Head & Neck', 'Easy', 'ENT', 112, '{"id":1835,"subject":"ENT","chapter":"Head & Neck","difficulty":"Easy","source":"ENT","sourceNo":112,"q":"Which of the following laryngeal cartilage is hyaline?","o":["Epiglottis","Comiculate","Cricoid","Cuneiform"],"a":2,"e":"Ans. is ''c'' i.e., Cricoid Hyaline cartilages Elastic cartilages (do not ossify) Thyroid cartilage Epioglottis Cricoid cartilage Corniculate Basal part of arytenoid cartilage Cuneiform Processes of arytenoid","pyqMatches":[{"year":"2012","no":112,"q":"Which of the following laryngeal cartilage is hyaline?","o":["Epiglottis","Comiculate","Cricoid","Cuneiform"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1836, 'ENT', 'Ear', 'Moderate', 'ENT', 113, '{"id":1836,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":113,"q":"All of the following cranial nerves are involved in Acoustic neuroma, except ?","o":["Vagus","Glossopharyngeal","Oculomotor","Facial"],"a":2,"e":"Ans. is ''c'' i.e., Oculomotor Clinical features of acoustic neuroma The clinical features depend on the extent of tumor and involved structure :? When tumor is still confined to the internal auditory canal Cochleovestibular symptoms are the earliest symptoms of acoustic neuroma when tumour is still confined to internal auditory canal. The commonest presenting symptoms are unilateral deafness or tinnitus, or a combination of both. Hearing loss is retrocochlear sensorineural type. There is marked difficulty in understanding speech, out of proportion to the pure tone hearing loss, a characteristic feature of acoustic neuroma. Vestibular symptoms are imbalance or unsteadiness. True vertigo is very rare. When tumor extends beyond IAC and involves other structures Vhcranial nerve :- It is the earliest nerve to be involved. There is reduced corneal sensitivity and loss of corneal reflex which is the earliest sign of acoustic neuroma. Numbness or paraesthesia of face may occur. Involvement of Vth nerve indicates that tumor is roughly 2.5 cm in diameter and occupies the CP angle. VIP nerve :- Sensory fibres of facial nerve are involved. There is hypoesthesia of posterior meatal wall (Hitzelberg''s sign), loss of taste, and loss of lacrimation on Schirmer''s test. Motor fibres are more resistant. IXth and A'' nerves :- Dysphagia and hoarseness due to palatal, pharyngeal and laryngeal paralysis. Brainstem :- Ataxia, weakness, numbness of arms & legs, exaggerated tendon reflexes. Cerebellum :- Ataxia, Dysdiadochokinesia, Nystagmus. Due to raised ICT :- Headache, neusea, vomiting, diplopia due to VI'' nerve involvement, and papilloedema.","pyqMatches":[{"year":"2013","no":1044,"q":"All of the following cranial nerves are involved in Acoustic neuroma, except ?","o":["Vagus","Glossopharyngeal","Oculomotor","Facial"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1837, 'ENT', 'Audiology', 'Easy', 'ENT', 114, '{"id":1837,"subject":"ENT","chapter":"Audiology","difficulty":"Easy","source":"ENT","sourceNo":114,"q":"Wave I in brain-stem response audiometry arises from?","o":["Cochlear nerve","Superior olivary complex","Lateral lemniscus","Inferior colliculus"],"a":0,"e":"Ans. is ''a'' i.e., Cochlear nerve Brain Stem Response Audiometry (BERA) It is a non-invasive procedure which objectively helps to find the integrity of central auditory pathway through the VIII nerve, pons and mid brain. It is accurate to within 10 or 15 dB of the psychoacoustic thereshold. It is the most reliable audiological method of differentiating between cochlear and Retrocochlear hearing losses. It is an objective test and can be done under sedation. It is used both as a screening test and as a definative hearing assessment test in children. Best test to detect deafness in infants (reliably recorded even from premature infants of 30 weeks gestational age) and mentally retarded or malingering subjects. It is also used for Identification of the site of lesion in Retrocochlear pathologies and to diagnose brainstem pathology e.g. multiple sclerosis or pontine tumor. Waves of BERA In a normal person, 7 waves are produced in first 10 miliseconds. The first, third and fifth waves are most stable and are used in measurements. Site of origin of waves are :- Wave I Distal part of Eighth nerve Wave II Proximal, part of Eighth cranial nerve Wave III Cochlear nucleus Wave IV Superior olivary complex Wave V Lateral leminiscus Wave VI & VII Inferior colliculus","pyqMatches":[{"year":"2013","no":1012,"q":"Wave I in brain-stem response audiometry arises from?","o":["Cochlear nerve","Superior olivary complex","Lateral lemniscus","Inferior colliculus"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1838, 'ENT', 'Ear', 'Easy', 'ENT', 115, '{"id":1838,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":115,"q":"Site of glomus jugulare?","o":["Epitympanum","Hypotympanum","Mesotympanum","Internal ear"],"a":1,"e":"Ans. is ''b'' i.e., Hypotympanum Glomus tumor Glomus tumor is the most common benign tumor of middle ear. It arises from the glomus bodies, therefore named Glomus tumor. It is well recognised that glomus tumors arise from paraganglions, which are normally occuring structures usually found in close association with sympathetic ganglions along the aorta and its main branches. The chief cells (paraganglionic cells) of the paraganglions are of neural crest origin and are components of the diffuse neuroendocrine system (DNES). These paraganglionic cells are derived from embryonic neuroepithelium (neural crest). Glomus tumors are also referred to as chemodectomas or nonchromaffin paragangliomas. There are two types of glomus tumors :- Glomus jugulare These glomus tumors arise from the dome of the internal jugular vein in the hypotympanum and jugular foramen. In jugular foramen they can invade IX to XII cranial nerves. Glomus tympanicum They arise from the promontory of the middle ear along the course of the tympanic branch of the IXth cranial nerve. Although rare, glomus tumors are the most common tumor of the middle ear and are second to acoustic neuroma (vestibular schwannoma) as the most common tumor of the temporal bone. It is more common in females with female to male ratio of 3-6 : 1. Glomus jugulare tumors have also been noted to be more common on the left side, especially in females. o Most tumors occur in patient 40-60 years. Multicentric tumors are found in 3-10% of sporadic cases and in 25- 50% of familial cases.","pyqMatches":[{"year":"2013","no":1042,"q":"Site of glomus jugulare?","o":["Epitympanum","Hypotympanum","Mesotympanum","Internal ear"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1839, 'ENT', 'Ear', 'Easy', 'ENT', 116, '{"id":1839,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":116,"q":"Frey''s syndrome is caused by ?","o":["Post traumatic nerve fibres of facial nerve with parasympathetic of auriculotemporal nerve","Greater auricular with auriculotemporal nerve","Facial nerve with greater auricular nerve","None"],"a":0,"e":"Ans. is ''a'' i.e., Post traumatic nerve fibres of facial nerve with parasympathetic of auriculotemporal nerve Frey''s syndrome (gustatory sweating) Gustatory sweating or Frey''s syndrome involves post-parotidectomy facial sweating and skin flushing while eating. The symptoms usually occur several months or even years after parotid surgery. The likely pathophysiology is aberrant regeneration of postganglionic secretomotor parasympathetic nerve fibres (originating from the otic ganglion) misdirected through several axonal sheaths of post- ganglionic sympathetic fibres feeding the sweat glands. These sympathetic fibres are to the sweat glands of the skin in the dissected field. The frey''s syndrome is likely due to injury to auriculotemporal nerve with faulty regeneration, therefore Frey''s syndrome is also known as Auriculotemporal syndrome. A variant of Frey''s syndrome in which there is gustatory facial flushing but not sweating, occurs following facial paralysis due to faulty regeneration following injury to the facial nerve. So, Frey''s syndrome is not limited to parotid surgery with injury to auriculotemporal nerve.","pyqMatches":[{"year":"2013","no":1030,"q":"Frey''s syndrome is caused by ?","o":["Post traumatic nerve fibres of facial nerve with parasympathetic of auriculotemporal nerve","Greater auricular with auriculotemporal nerve","Facial nerve with greater auricular nerve","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1840, 'ENT', 'Ear', 'Easy', 'ENT', 117, '{"id":1840,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":117,"q":"Killions incision is used for?","o":["Septoplasty","SMR","Proof puncture","Modified radical mastoidectomy"],"a":0,"e":"Ans. is ''a'' i.e., Septoplasty Technique of septoplasty","pyqMatches":[{"year":"2013","no":1100,"q":"Killions incision is used for?","o":["Septoplasty","SMR","Proof puncture","Modified radical mastoidectomy"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1841, 'ENT', 'Throat & Larynx', 'Easy', 'ENT', 118, '{"id":1841,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Easy","source":"ENT","sourceNo":118,"q":"Turban epiglottis is seen in ?","o":["TB","Leprosy","Laryngeal papilloma","Epiglottitis"],"a":0,"e":"Ans. is ''a'' i.e., TB Tubercular larvn_gitis Tubercular laryngitis is almost always secondary to pulmonary lesions, mostly affecting males in middle age (20-40 years). Disease affects the posterior third of larynx more commonly than anterior part.The parts affected in descending order of frequency are :- i) Interarytenoid fold, ii) Ventricular band, iii) Vocal cords, iv) Epiglottis Clinical features Weakness of voice with periods of aphonia earliest symptoms. o Hoarsness, cough, dysphagia (odynophagia) Referred otalgia Laryngeal examination in TB laryngitis Hyperaemia of the vocal cord in its whole extent or confined to posterior part with impairment of adduction is the first sign. Swelling in the interarytenoid region giving a mammilated appearance. Ulceration of vocal cord giving mouse-nibbled appearance. Superficial ragged ulceration on the arytenoids and interarytenoid region. Granulation tissue in interarytenoid region or vocal process of arytenoid. Pseudoedema of the epiglottis \"turban epiglottis\". Swelling of ventricular bands and aryepiglottic folds. Marked pallor of surrounding mucosa.","pyqMatches":[{"year":"2014","no":1145,"q":"Turban epiglottis is seen in ?","o":["TB","Leprosy","Laryngeal papilloma","Epiglottitis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1842, 'ENT', 'Throat & Larynx', 'Easy', 'ENT', 119, '{"id":1842,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Easy","source":"ENT","sourceNo":119,"q":"Most common part of larynx involved in TB ?","o":["Anterior","Posterior","Middle","Anywhere"],"a":1,"e":"Ans. is ''b'' i.e., Posterior Essential otolaryngology 2\"d/e p. 1139] Disease affects the posterior third of larynx more commonly than anterior part. The parts affected in descending order of frequency are :- i) Interarytenoid fold, ii) Ventricular band, iii) Vocal cords, iv) Epiglottis.","pyqMatches":[{"year":"2013","no":1085,"q":"Most common part of larynx involved in TB ?","o":["Anterior","Posterior","Middle","Anywhere"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1843, 'ENT', 'Ear', 'Easy', 'ENT', 120, '{"id":1843,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":120,"q":"Most common cause of ASOM is?","o":["Meningococci","Pneumococci","H influenzae","Moraxella"],"a":1,"e":"Ans. is ''b'' i.e., Pneumococci ASOM is an acute inflammation of middle ear cleft caused by pyogenic organism. It is worth noting that ASOM is the infection of middle ear cleft, i.e., middle ear (tympanic cavity), Eustachian tube, Attic, Aditus, antrum and mastoid air cells. ASOM is especially common in infants and children. Most of the time ASOM usually follows respiratory tract infections (i.e., acute tonsillitis, common cold or influenza) and the infection travel up by the eustachian tube to the middle ear. The most common causative organism is streptococcus pneumoniae. Other common organisms are H. influenzae and Moraxella catarrhalis. Less common causative organisms are streptococcus pyogenes, staphylococcus aureus and E.coli.","pyqMatches":[{"year":"2013","no":1020,"q":"Most common cause of ASOM is?","o":["Meningococci","Pneumococci","H influenzae","Moraxella"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1844, 'ENT', 'Ear', 'Easy', 'ENT', 121, '{"id":1844,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":121,"q":"Defective function of which of the following causes hyperacusis ?","o":["VIII nerve","7th nerve","Stapedius muscles","Any of the above"],"a":3,"e":"Ans. is ''d'' i.e., Any of the above Hyperacusis Hyperacusis is hearing normal voice as louder. The protective mechanisms a normal ear employs to minimize the harmful effects of loud noise are malfunctioning in hyperacusis. So, noise may seem too loud even with hearing protection. There is some speculation that the efferent portion of the auditory nerve is selectively damaged while the hair cells that allow us to hear pure tones in an audiometric evaluation remains intact. Some have said it involves direct malfunction of facial nerve; as a result, the stapedius muscle is unable to dampen sound.","pyqMatches":[{"year":"2013","no":1032,"q":"Defective function of which of the following causes hyperacusis ?","o":["VIII nerve","7th nerve","Stapedius muscles","Any of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1845, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 122, '{"id":1845,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":122,"q":"Paranasal polyp CT view?","o":["Corona!","Axial","Sagital","3D"],"a":0,"e":"Ans. is ''a'' i.e., Coronal Both coronal and axial view are used, but coronal views are best to study paranasal sinus polyps.","pyqMatches":[{"year":"2013","no":1071,"q":"Paranasal polyp CT view?","o":["Corona!","Axial","Sagital","3D"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1846, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 123, '{"id":1846,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":123,"q":"Vallecula sign is seen in ?","o":["TB laryngitis","Vocal nodule","Inverted papilloma","Acute epiglottitis"],"a":3,"e":"Ans. is ''d'' i.e., Acute epiglottitis There are two important radiological signs in acute epiglottitis :?","pyqMatches":[{"year":"2013","no":1086,"q":"Vallecula sign is seen in ?","o":["TB laryngitis","Vocal nodule","Inverted papilloma","Acute epiglottitis"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1847, 'ENT', 'Ear', 'Easy', 'ENT', 124, '{"id":1847,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":124,"q":"Most common cause of otomycosis ?","o":["Histoplasma","Rhinosporidium","Aspergillus","Actinomyces"],"a":2,"e":"Ans. is ''c'' i.e., Aspergillus Otomycosis Otomycosis, also called acute fungal otitis externa, describes a fungal or yeast infection of the external auditory meatus. Saprophytic fungi potentially residing in the ear canal include Aspergillus, Candida albicans, Phycomycetes, Rhizopus, Actinomyces, and Penicillium. Under certain conditions of increased heat, humidity, glucose concentration (diabetes), immunosuppression, or overuse of systemic or topical antibiotics and steroids, these saprophytic fungi can become pathogenic. Aspergillus niger accounts for 90% of otomycosis infections. Other common organisms are candida albicans (2\"a most common) and Aspergillus fumigatus. Less common organisms are Phycomycetes, Rhizopus, Actinomyces and Penicillium","pyqMatches":[{"year":"2013","no":1015,"q":"Most common cause of otomycosis ?","o":["Histoplasma","Rhinosporidium","Aspergillus","Actinomyces"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1848, 'ENT', 'Ear', 'Easy', 'ENT', 125, '{"id":1848,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":125,"q":"Facial nerve palsy can be caused by ?","o":["Cholesteatoma","Multiple sclerosis","Mastoidectomy","All of the above"],"a":3,"e":"Ans. is ''d'''' i.e., All of the above Causes of facial paralysis Central :- Brain abscess, pontine glioma, Polio, multiple sclerosis Intracranial part (cerebellopontine angle) :- Acoustic neuroma, meningioma, congenital cholesteatoma, metastatic carcinoma, meningitis Intratemporal part :- Idiopathic :- Bell''s palsy, Melkersson''s syndrome Infections :- ASOM, CSOM, Herpes zoster oticus, malignant otitis externa Trauma :- Surgical (mastoidectomy, stapedectomy), accidental (fractures of temporal bone) Neoplasms :- Malignancies of external and middle ear, glomus jugular, facial nerve neuroma, metastasis (from breast, lung etc). Extracranial part :- Malignancies or surgery or injury to parotid gland Systemic diseases :- Diabetes, hypothyroidism, uremia, PAN, Sarcoidosis (Heerfordt''s syndrome), leprosy, leukaemia, demyelinating disease","pyqMatches":[{"year":"2013","no":1031,"q":"Facial nerve palsy can be caused by ?","o":["Cholesteatoma","Multiple sclerosis","Mastoidectomy","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1849, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 126, '{"id":1849,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":126,"q":"Predisposing factor for Nasal myiasis ?","o":["Allergic rhinitis","Vasomotor rhinitis","Atrophic rhinitis","Rhinitis medicomentosa"],"a":2,"e":"Ans. is ''c'' i.e., Atrophic rhinitis Nasal myiasis (Maggots in nose) It results from the presence of ova of flies particularly chrysomia species in the nose which produce ulceration and destruction of nasal structure. Mostly seen in atrophic rhinitis when the mucosa becomes insensitive to flies laying eggs inside. Clinical features Initial symptoms (3-4 days maggots) :- Intense irritation, sneezing, headache, blood stained disharge, lacrimation. o Later :- Maggots may crawl out of nose and there is foul smell. Complications Destruction of nose, sinuses, soft tissues of face, palate and eyeball. Fistulae in nose and palate. Death occurs due to meningitis. Treatment Chloroform water or vapor must be instilled in order to anaesthetize or kill the maggots and so release their grip from the skin.","pyqMatches":[{"year":"2013","no":1064,"q":"Predisposing factor for Nasal myiasis ?","o":["Allergic rhinitis","Vasomotor rhinitis","Atrophic rhinitis","Rhinitis medicomentosa"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1850, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 127, '{"id":1850,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":127,"q":"Glomus tumor invading the vertical part of carotid canal. It is ?","o":["Type B","Type CI","Type C2","Type C3"],"a":2,"e":"Ans. is `c'' i.e., Type C2","pyqMatches":[{"year":"2013","no":1040,"q":"Glomus tumor invading the vertical part of carotid canal. It is ?","o":["Type B","Type CI","Type C2","Type C3"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1851, 'ENT', 'Ear', 'Easy', 'ENT', 128, '{"id":1851,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":128,"q":"Unilateral sensorineural hearing loss may occur in?","o":["Coronavirus","Mumps","Pertussis","Rotavirus"],"a":1,"e":"Ans. is ''b'' i.e., Mumps Infections of labyrinth Trauma to labyrinth or VIII nerve (Head injury, surgery etc) Noise induced hearing loss Ototoxic drugs Acquired causes of SNHL Presbycusis Meniere''s disease Acoustic neuroma Sudden hearing loss Systemic disorders (DM, Hypothyroidism, Renal disorders) Multiple sclerosis Smoking & Alcoholism","pyqMatches":[{"year":"2013","no":1013,"q":"Unilateral sensorineural hearing loss may occur in?","o":["Coronavirus","Mumps","Pertussis","Rotavirus"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1852, 'ENT', 'Ear', 'Moderate', 'ENT', 129, '{"id":1852,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":129,"q":"Fracture of which of the following bone causes leakage of cerebrospinal fluid through ear ?","o":["Mastoid process","Petrous temporal","Ethmoid plate","Cribriform plate"],"a":1,"e":"Ans. is `b'' i.e., Petrous temporal CSF otorrhea CSF otorrhea, i.e., leakage of cerebrospinal fluid through ear structure, is a rare but potentially life threatening situation that requires rapid intervention. The underlying etiology of spinal fluid leak through temporal bone is a violation of the bony and meningeal barriers that separate the subarachoid space from the middle ear and mastoid. This means that a defect must exist not only in the bone, but also in the dura matter. Causes of CSF otorrhea are : ?","pyqMatches":[{"year":"2013","no":1048,"q":"Fracture of which of the following bone causes leakage of cerebrospinal fluid through ear ?","o":["Mastoid process","Petrous temporal","Ethmoid plate","Cribriform plate"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1853, 'ENT', 'Ear', 'Easy', 'ENT', 130, '{"id":1853,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":130,"q":"Which of the following is a pneumatic bone ?","o":["Parietal bone","Occipital bone","Mastoid process","None"],"a":2,"e":"Ans. is ''c'' i.e., Mastoid process Pneumatic bones are one which contain large air spaces lined by epithelium. Examples: maxilla, sphenoid, ethmoid, etc. They make the skull light in weight, help in resonance of voice, and act as air conditioning chambers for the inspired air. A bone that is hollow or contains many air cells called as penumatic bone. Examples are mastoid process of temporal bone, maxilla, ethmoid, sphlenoid and frontal bone. Very simple to remember last 4 as all four paransal sinuses are pneumatic bones.","pyqMatches":[{"year":"2013","no":1107,"q":"Which of the following is a pneumatic bone ?","o":["Parietal bone","Occipital bone","Mastoid process","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1854, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 131, '{"id":1854,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":131,"q":"Mulberry nasal mucosa is seen in ?","o":["Lupus vulgaris","Vasomotor rhinitis","Atrophic rhinitis","None"],"a":1,"e":"Ans. is ''b'' i.e., Vasomotor rhinitis Vasomotor is a nonallergic condition that involves a constant runny nose, sneezing and nasal congestion, i.e., the nose is stuffy or runny for reasons other than allergies and infections. The exact etiology is unknown, but triggers include emotions, odors, poor air quality, spicy foods, and medication side effects. Pathogenesis include : - Parasympathetic overactivity Hyperactive nasal mucosa to several non-specific stimuli especially in women of 20-40 years. Symptoms of vasomotor rhinitis include excessive clear rhinorrhoea, nasal obstruction/congestion, irritation, paroxysmal sneezing and post-nasal drip. Nasal mucosa is hypertrophied & congested; and mucosa of turbinates may give mulberry like appearance and is pale to dusky red in colour. Complications of vasomotor rhinitis include hypertrophic rhinitis & sinusitis, and nasal polyp. Mulberry nasal mucosa is also seen in chronic hypertrophic rhinitis","pyqMatches":[{"year":"2013","no":1065,"q":"Mulberry nasal mucosa is seen in ?","o":["Lupus vulgaris","Vasomotor rhinitis","Atrophic rhinitis","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1855, 'ENT', 'Nose & Paranasal Sinuses', 'Moderate', 'ENT', 132, '{"id":1855,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Moderate","source":"ENT","sourceNo":132,"q":"All are seen in Samters triad except?","o":["Asthma","Nasal polyp","Bacterial infection","Aspirin sensitivity"],"a":2,"e":"Ans. is ''c'' i.e., Bacterial infection Samter''s triad Samter''s triad is a medical condition consisting of asthma, aspirin sensitivity, and nasaL''ethmoidal polyposis. It occurs in middle age (twenties and thirties are the most common onset times) and may not include any allergies. o Most commonly, the first symptom is rhinitis. The disorder typically progeses to asthma, then polyposis, with aspirin sensitivity coming last. The aspirin reaction can be severe, including an asthma attack, anaphylaxis, and urticaria in some cases. Patients typically react to other NSAIDS such as ibuprofen, although paracetamol is generally considered safe. Anosmia (lack of smell) is also typical, as the inflammation reaches the olfactory receptors in the nose.","pyqMatches":[{"year":"2013","no":1057,"q":"All are seen in Samters triad except?","o":["Asthma","Nasal polyp","Bacterial infection","Aspirin sensitivity"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1856, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 133, '{"id":1856,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":133,"q":"Objective test in adenoids","o":["Posterior rhinoscopy","Anterior rhinoscopy","Manual palpation","All of the above"],"a":0,"e":"Ans. is ''a'' i.e., Posterior rhinoscopy","pyqMatches":[{"year":"2013","no":1098,"q":"Objective test in adenoids","o":["Posterior rhinoscopy","Anterior rhinoscopy","Manual palpation","All of the above"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1857, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 134, '{"id":1857,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":134,"q":"Most common sinus to be involved in acute sinusitis?","o":["Ethmoid","Maxillary","Sphenoid","Frontal"],"a":1,"e":"Ans. is ''b'' i.e., Maxillary Most common sinus affected by sinusitis overall Maxillary Most common sinus affected in adult Maxillary Most common sinus affected in children Ethmoid Least common sinus affected Sphenoid Sinuses involved in order of frequency Maxillary > Frontal > Ethmoid > Sphenoid","pyqMatches":[{"year":"2013","no":1069,"q":"Most common sinus to be involved in acute sinusitis?","o":["Ethmoid","Maxillary","Sphenoid","Frontal"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1858, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 135, '{"id":1858,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":135,"q":"Queckensted test is done for ?","o":["Glomus tumor","CSF rhinorrhea","Otosclerosis","Acoustic neuroma"],"a":1,"e":"Ans. is ''b'' i.e., CSF rhinorrhea Detection of CSF Leak","pyqMatches":[{"year":"2013","no":1066,"q":"Queckensted test is done for ?","o":["Glomus tumor","CSF rhinorrhea","Otosclerosis","Acoustic neuroma"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1859, 'ENT', 'Head & Neck', 'Moderate', 'ENT', 136, '{"id":1859,"subject":"ENT","chapter":"Head & Neck","difficulty":"Moderate","source":"ENT","sourceNo":136,"q":"Bilateral recurrent laryngeal nerve palsy is seen in all except ?","o":["Thyroid carcinoma","Lymphadenopathy","Thyroid surgery","Aortic aneurysm"],"a":3,"e":"Ans. is ''d'' i.e., Aortic aneurysm","pyqMatches":[{"year":"2013","no":1087,"q":"Bilateral recurrent laryngeal nerve palsy is seen in all except ?","o":["Thyroid carcinoma","Lymphadenopathy","Thyroid surgery","Aortic aneurysm"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1860, 'ENT', 'Throat & Larynx', 'Easy', 'ENT', 137, '{"id":1860,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Easy","source":"ENT","sourceNo":137,"q":"Most common cause of singer''s nodule is ?","o":["Infection","Allergy","Vocal abuse","None"],"a":2,"e":"Ans. is ''c'' i.e., Vocal abuse Vocal nodule (singer''s or screamer''s nodule) Vocal nodule are benign noneoplastic growth on free edge of both the vocal cords at the junction of anterior 1/ 3 with posterior 2/3. This area is particularly vulnerable to trauma as this is the area of maximum vibration of the cord. The major cause is voice abuse, therefore it is most commonly seen in singers, actors, teachers, and howkers. Hoarseness is the most common symptom. Vocal fatigue and pain in neck on prolonged phonation are other symptoms. Treatment Early cases of vocal nodules can be treated conservatively by educating the patient in proper use of voice. Many nodules especially in children, disappear with this treatment. Surgery is required for large nodules or long standing nodules in adults. Microscopic (micorlaryngoscopic) excision is the treatment of choice.","pyqMatches":[{"year":"2016","no":953,"q":"Most common cause of singer''s nodule is ?","o":["Infection","Allergy","Vocal abuse","None"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1861, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 138, '{"id":1861,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":138,"q":"Mucoperichondrial flap in septoplasty is made on?","o":["Alar cartilage","Septal cartilage","Maxillary spine","Sphenoid spine"],"a":1,"e":"Ans. is ''b'' i.e., Septal cartilage Steps in septoplasty A unilateral incision is made in the mucoperichodrial flap at the lower border of septal cartilage on the left side in right handed persons. The mucoperichondrial flap is elevated on one side making an anterior tunnel. Another incision is made in the mucoperiosteum over the nasal spine on the same side, elevating the mucoperiosteum from nasal spine on both sides thus making two more tunnels called inferior tunnels. Two tunnels are joined by sharp dissection. Septal cartilage is then separated from vomero-ethmoid bones posteriorly and nasal spine inferiorly. Maxillary crest is removed to realign septal cartilage. Bony septal deformity is corrected by removing deformed part. Deformed septal cartilage is corrected. Trans-septal sutures are put to coapt mucoperichondrial flaps. Nasal pack is put. Thus (coming to question) Mucoperichondrial flap (and tunnel) are made on septal cartilage. Mucoperiosteal flap (and tunnels) are made on nasal spine.","pyqMatches":[{"year":"2013","no":1099,"q":"Mucoperichondrial flap in septoplasty is made on?","o":["Alar cartilage","Septal cartilage","Maxillary spine","Sphenoid spine"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1862, 'ENT', 'Nose & Paranasal Sinuses', 'Moderate', 'ENT', 139, '{"id":1862,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Moderate","source":"ENT","sourceNo":139,"q":"All are major symptoms of sinusitis except ?","o":["Nasal bluckage","Facial congertion","Nasal congestion","Halitosis"],"a":3,"e":"Ans. is ''d'' i.e., Halitosis The clinical symptoms of acute sinusitis have been classified into major and minor Major Facial pain or pressure Purulent nasal discharge Fever Nasal congestion Nasal obstruction Hyposmia or Anosmia Facial congestion or fullness Minor Headache Cough Fatigue Halitosis Dental pain Ear pain or pressure","pyqMatches":[{"year":"2013","no":1070,"q":"All are major symptoms of sinusitis except ?","o":["Nasal bluckage","Facial congertion","Nasal congestion","Halitosis"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1863, 'ENT', 'Throat & Larynx', 'Easy', 'ENT', 140, '{"id":1863,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Easy","source":"ENT","sourceNo":140,"q":"Laryngitis sicca is associated with ?","o":["Rhinosporidium","M. leprae","Klebsiella azaenae","Klebsiella rhinoscleromatosis"],"a":2,"e":"Ans. is ''c'' i.e., Klebsiella azaenae Laryngitis sicca (Atrophic laryngitis or laryngitis atrophica) It is a rare entity characterized by atrophic changes in the respiratory mucosa with loss of the mucus - producing glands. It is usually associated with atrophic rhinitis and pharyngitis caused by klebsiella ozaenae. The most common sites involved in larynx are the false cords (vestibular folds), the posterior region and the subglottic region. More common in women. Clinical features Irritable cough and hoarseness Excessive crusts formation which are sometimes bloodstained (hemorrhagic) with foul odour. Crusts are the most important diagnostic feature. Treatment Elimination of causative factors and humidification. Laryngeal sprays with glucose in glycerine or oil of pine helps in crust removal. Expectorants containing ammonium chloride or iodides also help to loosen the crust. Microlaryngoscopic removal of crust in laryngitis sicca is the new modality of treatment.","pyqMatches":[{"year":"2013","no":1088,"q":"Laryngitis sicca is associated with ?","o":["Rhinosporidium","M. leprae","Klebsiella azaenae","Klebsiella rhinoscleromatosis"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1864, 'ENT', 'Ear', 'Easy', 'ENT', 141, '{"id":1864,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":141,"q":"Ossicles of middle ear are responsible for which of the following ?","o":["Amplification of sound intensity","Reduction of sound intensity","Protecting the inner ear","Reduction of impedance to sound transmission"],"a":3,"e":"Ans. is ''d'' i.e., Reduction of impedance to sound transmission The ear canal (auditory canal) acts as a resonator, i.e. it resonates (amplifies frequencies) between 2000 and 5000 (average 3000) cycles per second and therefore most energy will be transmitted to the cochlea in these frequencies. However, if this sound energy hits the inner ear fluid directly most of the energy would be reflected, resulting in hearing loss (as all the sound wave is reflected and nothing is a transmitted as electrical impulse). Therefore, there is a need for a transformer mechanism, a need that is fullfilled by middle ear → middle ear converts sound of greater amplitude but lesser force to that of lesser amplitude but greater force. This function of the middle ear is called impedence matching mechanism or the transformer action.","pyqMatches":[{"year":"2013","no":996,"q":"Ossicles of middle ear are responsible for which of the following ?","o":["Amplification of sound intensity","Reduction of sound intensity","Protecting the inner ear","Reduction of impedance to sound transmission"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1865, 'ENT', 'Ear', 'Easy', 'ENT', 142, '{"id":1865,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":142,"q":"Which structure prevents spread of infection form middle ear to brain ?","o":["Tegmen tympani","Cribriform plate","Fundus tympani","Petrous apex"],"a":0,"e":"Ans. is ''a'' i.e., Tegmen tympani Tegmen tympani (forming the roof of middle ear cavity) separates the tympanic cavity from middle cranial fossa.","pyqMatches":[{"year":"2013","no":1108,"q":"Which structure prevents spread of infection form middle ear to brain ?","o":["Tegmen tympani","Cribriform plate","Fundus tympani","Petrous apex"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1866, 'ENT', 'Ear', 'Easy', 'ENT', 143, '{"id":1866,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":143,"q":"In otosclerosis, which is most affected?","o":["Oval window","Round window","Foot plate of stapes","Utricle"],"a":0,"e":"Ans. is ''a'' i.e., Oval window The most common site of disease is promontory in the region of the anterior margin of oval window, and in advanced cases the stapes become ankylosed in position by a mass of new spongy bone. Why is it so ? This area is involved most commonly because in this area is located the fissula ante fenestram, a vestigial structure which frequently contains cartilaginous remnants and which is particularly prone to otosclerotic changes. Most common type of otosclerosis → Stapedial otosclerosis Most common site of otosclerosis → Fissula ante fenestram (i.e, just in front of oval window) Most common site for Stapedial otosclerosis → Fissula ante fenestram (i.e, just in front of oval window) Most common site for cochlear otosclerosis → Round window","pyqMatches":[{"year":"2013","no":1037,"q":"In otosclerosis, which is most affected?","o":["Oval window","Round window","Foot plate of stapes","Utricle"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1867, 'ENT', 'Throat & Larynx', 'Easy', 'ENT', 144, '{"id":1867,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Easy","source":"ENT","sourceNo":144,"q":"True regarding laryngeal TB is?","o":["Commonly involves anterior 2/3 rd of vocal cord","Mouse-nibbled vocal cord","More common in males","None of the above"],"a":1,"e":"Ans. is ''b'' i.e., Mouse-nibbled vocal cord","pyqMatches":[{"year":"2013","no":1109,"q":"True regarding laryngeal TB is?","o":["Commonly involves anterior 2/3 rd of vocal cord","Mouse-nibbled vocal cord","More common in males","None of the above"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1868, 'ENT', 'Throat & Larynx', 'Easy', 'ENT', 145, '{"id":1868,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Easy","source":"ENT","sourceNo":145,"q":"Most common cause of acute tonsilitis ?","o":["Streptococcus pneumoniae","H. Influenza","13- hemolytic streptococci","Staphylococcus aureus"],"a":2,"e":"Ans. is ''c'' i.e., 13- hemolytic streptococci Tonsils frequently serve as the site of acute infection, which causes acute tonsillitis. Tonsillitis is particularly common in children, especially in school going age group. However, it can occur in adult also. Virus initiates an acute tonsillitis attack and predisposes to bacterial infection. 8-hemolytic streptococcus is the most common organism causing acute tonsillitis. Other bacteria causing acute tonsillitis are staphylococcus, hemophilus and pneumococcus.","pyqMatches":[{"year":"2013","no":1076,"q":"Most common cause of acute tonsilitis ?","o":["Streptococcus pneumoniae","H. Influenza","13- hemolytic streptococci","Staphylococcus aureus"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1869, 'ENT', 'Head & Neck', 'Easy', 'ENT', 146, '{"id":1869,"subject":"ENT","chapter":"Head & Neck","difficulty":"Easy","source":"ENT","sourceNo":146,"q":"Treatment of choice for nasopharyngeal carcinoma is ?","o":["Surgery","Radiotherapy","Surgery & radiotherapy","Chemotherapy"],"a":1,"e":"Ans. is ''b'' i.e., Radiotherapy Treatment of nasopharyngeal carcinoma Irradiation is treatment of choice (external radiotherapy). Radical neck dissection is required for persistent nodes when primary has been controlled and in post radiation cervical metastasis. Systemic chemotherapy is used as palliation for distant metastases or radiation failure. For advanced stages (stage III & IV), the cure rate can be doubled when chemotherapy is combined with radiotherapy.","pyqMatches":[{"year":"2013","no":1083,"q":"Treatment of choice for nasopharyngeal carcinoma is ?","o":["Surgery","Radiotherapy","Surgery & radiotherapy","Chemotherapy"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1870, 'ENT', 'Ear', 'Easy', 'ENT', 147, '{"id":1870,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":147,"q":"Cone of light focuses on which quadrant of tympanic membrane?","o":["Anteroinferior","Posteroinferior","Anterosuperior","Posterosuperior"],"a":0,"e":"Ans. is ''a'' i.e., Anteroinferior Cone of light Seen in anteroinferior quadrant of the tympanic membrane is actually the reflection of the light projected into the ear canal to examine it. This part reflects it because it is the only part of tympanic membrane that is approximately at right angles to the meatus. This difference in different part of the tympanic membrane is due to the handle of malleus which pulls the tympanic membrane and causes it to tent inside. Thus, the handle of malleus causes tenting and because of tenting the antero-inferior quardrant is at right angles to the meatus and thus reflects the light (leading to cone light).","pyqMatches":[{"year":"2013","no":994,"q":"Cone of light focuses on which quadrant of tympanic membrane?","o":["Anteroinferior","Posteroinferior","Anterosuperior","Posterosuperior"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1871, 'ENT', 'Ear', 'Easy', 'ENT', 148, '{"id":1871,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":148,"q":"Hearing loss of 65dB, what is the grade of deafness?","o":["Mild","Moderate","Severe","Moderately severe"],"a":3,"e":"Ans. is ''d'' i.e., Moderately severe","pyqMatches":[{"year":"2013","no":1009,"q":"Hearing loss of 65dB, what is the grade of deafness?","o":["Mild","Moderate","Severe","Moderately severe"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1872, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 149, '{"id":1872,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":149,"q":"Vestibular function is assessed by ?","o":["Fistula test","Hallpike manaeuver","Caloric test","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above","pyqMatches":[{"year":"2013","no":1014,"q":"Vestibular function is assessed by ?","o":["Fistula test","Hallpike manaeuver","Caloric test","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1873, 'ENT', 'Ear', 'Easy', 'ENT', 150, '{"id":1873,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":150,"q":"Blue ear drum is seen in ?","o":["Serous otitis media","CSOM","Perforation","None"],"a":0,"e":"Ans. is ''a'' i.e., Serous otitis media Any accumulation of fluid behind tympanic membrane causes structural changes in tympanic membrane causing it to appear blue, be it pus, blood or serous fluid. The most common cause of fluid accumulation in middle ear is serous otitis media or glue ear (most common cause) and haemotympanum. Other causes of blue tympanic membrane are glomus tumor, hemangioma of middle ear, and cholesterol granuloma.","pyqMatches":[{"year":"2013","no":1026,"q":"Blue ear drum is seen in ?","o":["Serous otitis media","CSOM","Perforation","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1874, 'ENT', 'Throat & Larynx', 'Easy', 'ENT', 151, '{"id":1874,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Easy","source":"ENT","sourceNo":151,"q":"Peritonsillar abscess is caused most commonly by ?","o":["Streptococcus pneumoniae","Staphylococcus aureus","Beta hemolytic streptococcus","H. influenzae"],"a":2,"e":"Ans. is ''c'' i.e., Beta hemolytic streptococcus Peritonsillar abscess (Ouinsy) Quinsy consists of suppuration outside the capsule in the area around the capsule. There is collection of pus between the capsule of tonsil and the superior constrictor muscle, i.e. in the peritonsillar area. Peritonsillar abscess is a complication of tonsillitis and is most commonly caused by group A beta - hemolytic streptococcus. Clinical features of Quinsy Clinical features are divided into :? General : They are due to septicaemia and resemble any acute infection.","pyqMatches":[{"year":"2013","no":1077,"q":"Peritonsillar abscess is caused most commonly by ?","o":["Streptococcus pneumoniae","Staphylococcus aureus","Beta hemolytic streptococcus","H. influenzae"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1875, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 152, '{"id":1875,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":152,"q":"Strawberry oppearance is seen in ?","o":["Lupus vulgarsis","Rhinoscleroma","Rhinosporidiosis","Angiofibroma"],"a":2,"e":"Ans. is ''c'' i.e., Rhinosporidiosis Rhinosporidiosis Rhinosporidiosis is a chronic granulomatous infection of the mucous membrane that usually manifests as vascular friable polyps that arise from the nasal mucosa. The etiological agent is Rhinosporidium seeberi. Rhinosporidium seeberi is an aquatic bacterum (not a fungus). Infection usually results from a local traumatic inoculation with the organism. It is seen in India, Pakistan and Sri Lanka. In India, most of the cases are seen in Southern states. Infection of the nose and nasopharynx is observed in 70% of persons with rhinosporidiosis; infection of palpebral conjunctiva or associated structures (including lacrimal apparatus) is observed in 15% of cases. Other structures of the mouth and upper airway may be sites of disease. Disease of the skin, ear, genitals and rectum has also been described. Rhinosporidiosis is an infection that typically limited to the mucosal epithelium. The disease progress with local replication of R seeberi and associated hyperplastic growth of host tissue and a localized immune response. Clinical features of Rhinosporidiosis Rhinosporidiosis presents as soft leafy polypoidal mass (soft polyp), which is pink to purple in colour studded with white dots, i.e. strawberry appearance. This appearance results from sporangia, which is visible as grey or yellow spots in the vascular polypoid masses. Because the polyps are vascular and friable, they bleed easily upon manipulation. Treatment The treatment of choice is surgical excision. Complete excision of mass is done with diathermy knife and cauterization of base. Dapsone is being tried for treating rhinosporidiosis but with limited success.","pyqMatches":[{"year":"2013","no":1058,"q":"Strawberry oppearance is seen in ?","o":["Lupus vulgarsis","Rhinoscleroma","Rhinosporidiosis","Angiofibroma"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1876, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 153, '{"id":1876,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":153,"q":"True about central nystagmus ?","o":["Changing direction","Not suppressed by optic fixation","Horizontal or vertical","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above Nystagmus Nystagmus is rhythmic oscillatory movement of eye. Nystagmus has following characteristics :?","pyqMatches":[{"year":"2013","no":999,"q":"True about central nystagmus ?","o":["Changing direction","Not suppressed by optic fixation","Horizontal or vertical","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1877, 'ENT', 'Ear', 'Easy', 'ENT', 154, '{"id":1877,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":154,"q":"Potato tumor is","o":["Rhinosporidiosis","Hypertrophied sebaceous gland","Nosopharyngeal angiofibroma","Tubercular infection"],"a":1,"e":"Ans. is ''b'' i.e., Hypertrophied sebaceous gland Rhinophyma (Potato tumor) Rhinophyma is a benign tumor of tip of nose due to hypertrophy of sebaceous gland. It is caused by granulomatous infiltration and occurs as a complication of long standing acne rosacea. Alcoholism is mistakenly attributed as a cause of this disease, but heavy alcohol consumption does aggravate the condition. The usual presentation is due to cosmetic appearance or obstruction. Treatment of choice is debulking of tumor by carban dioxide laser.","pyqMatches":[{"year":"2013","no":1060,"q":"Potato tumor is","o":["Rhinosporidiosis","Hypertrophied sebaceous gland","Nosopharyngeal angiofibroma","Tubercular infection"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1878, 'ENT', 'Ear', 'Moderate', 'ENT', 155, '{"id":1878,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":155,"q":"Early tonsillectomy is not done in?","o":["Thyroid storm","Suspected malignancy","Peritonsillar abscess","Rheumatic fever"],"a":0,"e":"Ans. is ''a'' i.e., Thyroid storm Uncotrolled systemic hypertension is a contraindication for tonsillectomy. In thyroid storm there is dangerously high BP. Contraindications of tonsillectomy","pyqMatches":[{"year":"2013","no":1095,"q":"Early tonsillectomy is not done in?","o":["Thyroid storm","Suspected malignancy","Peritonsillar abscess","Rheumatic fever"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1879, 'ENT', 'Head & Neck', 'Easy', 'ENT', 156, '{"id":1879,"subject":"ENT","chapter":"Head & Neck","difficulty":"Easy","source":"ENT","sourceNo":156,"q":"Most common cause of retropharyngeal abscess in adults?","o":["TB","Tooth extraction","Tonsillitis","Lymphadenitis"],"a":0,"e":"Ans. is ''a'' i.e., TB Abscess in infants (acute retropharyngeal abscess) Most commonly it results from retropharyngeal lymphadenitis due to an upper respiratory tract infection. Treatment is incision and drainage. Abscess in adults (chronic retropharyngeal abscess) If an adult or an older child has a retropharyngeal infection it is likely to be due to a tuberculous infection of the cervical spine (caries of cervical spine). Sometime it may be secondary to tuberculous infection of retropharyngeal lymph nodes. Treatment includes incision and drainage of abscess along with full course of antitubercular treatment.","pyqMatches":[{"year":"2013","no":1082,"q":"Most common cause of retropharyngeal abscess in adults?","o":["TB","Tooth extraction","Tonsillitis","Lymphadenitis"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1880, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 157, '{"id":1880,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":157,"q":"Otosclerosis affects which bone?","o":["Stapes","Incus","Malleus","None"],"a":0,"e":"Ans. is ''a'' i.e., Stapes Types of otosclerosis Following types of otosclerosis have been described :-","pyqMatches":[{"year":"2015","no":939,"q":"Otosclerosis affects which bone?","o":["Stapes","Incus","Malleus","None"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1881, 'ENT', 'Ear', 'Easy', 'ENT', 158, '{"id":1881,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":158,"q":"Endolymphatic sac decompression is done in?","o":["Menieres disease","Otosclerosis","Otitis media","Vestibular schwannoma"],"a":0,"e":"Ans. is ''a'' i.e., Menieres disease Treatment of Meniere''s disease Most treatments are for symptoms believed to be caused by excess endolymphatic fluid. Treatment of Meniere''s disease is of two types :? A) Medical management B) Surgical management Medical management: Treatment of Meniere''s disease begins first with medical management. Medical treatment controls the condition in over two third of patients. Medical management includes :?","pyqMatches":[{"year":"2013","no":1039,"q":"Endolymphatic sac decompression is done in?","o":["Menieres disease","Otosclerosis","Otitis media","Vestibular schwannoma"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1882, 'ENT', 'Throat & Larynx', 'Easy', 'ENT', 159, '{"id":1882,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Easy","source":"ENT","sourceNo":159,"q":"In type-4 thyroplasty, vocal cord is ?","o":["Medially displaced","Laterally displaced","Lengthened","Shortened"],"a":2,"e":"Ans. is ''c'' i.e., Lengthened Thyroplasty Isshiki divided thyroplasty procedures into 4 categories to produce functional alteration of vocal cords : -","pyqMatches":[{"year":"2013","no":1097,"q":"In type-4 thyroplasty, vocal cord is ?","o":["Medially displaced","Laterally displaced","Lengthened","Shortened"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1883, 'ENT', 'Ear', 'Easy', 'ENT', 160, '{"id":1883,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":160,"q":"Fenestration operation is which type of tympanoplasty?","o":["Type-2","Type-3","Type-4","Type-5"],"a":3,"e":"Ans. is ''d'' i.e., Type-5 Types of tympanoplasty Wullstein classified tympanoplasty into five types :? Type I: → Defect is perforation of tympanic membrane which is repaired with a graft. It is also called myringoplasty. Type II: → Defect is perforation of tympanic membrane with erosion of malleus. Graft is placed on the incus or remnant of malleus. Type III: → Malleus and incus are absent. Graft is placed directly on the stapes head. It is also called myringostapediopexy or columella tympanoplasty. Type IV: → Only the footplate of stapes is present. It is exposed to the external ear, and graft is placed between the oval and round windows. A narrow middle ear (cavum minor) is thus created, to have an air pocket around the round window. A mucosa-lined space extends from the eustachian tube to the round window. Sound waves in this case act directly on the footplate while the round window has been shielded. Type V: → Stapes footplate is fixed but round window is functioning. In such cases, another window is created on horizontal semicircular canal and covered with a graft. Also called fenestration operation.","pyqMatches":[{"year":"2013","no":1096,"q":"Fenestration operation is which type of tympanoplasty?","o":["Type-2","Type-3","Type-4","Type-5"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1884, 'ENT', 'Ear', 'Easy', 'ENT', 161, '{"id":1884,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":161,"q":"Bullous myringitis is caused by?","o":["Pseudomonas","Mycoplasma","Pneumococcus","Candida"],"a":1,"e":"Ans. is ''b'' i.e., Mycoplasma Otitis externa haemorrhagica This condition is also known as Bullous myringitis or myringitis bullosa. This condition is extremely painful and has sudden onset. It is thought to be due to mycoplasma pneumoniae or viral infection, usually influenza There may be a mild conductive deafness and a mildly discharging ear. The appearance of haemorrhagic bullae on the tympanic membrane and in the deep meatus is characteristic. The bullae are filled with serosanguinous fluid and blood. On healing, bullae look like Sago-grain. Therefore \"Sago-grain\" appearance of tympanic membrane is seen in healed myringitis bullosa.","pyqMatches":[{"year":"2013","no":1016,"q":"Bullous myringitis is caused by?","o":["Pseudomonas","Mycoplasma","Pneumococcus","Candida"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1885, 'ENT', 'Throat & Larynx', 'Moderate', 'ENT', 162, '{"id":1885,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Moderate","source":"ENT","sourceNo":162,"q":"All are absolute indications of tonsillectomy except","o":["Suspicious malignancy","Peritonsillar abscess","Chronic tonsillits","Tonsils causing obstructive sleep apnea"],"a":2,"e":"Ans. is ''c'' i.e., Chronic tonsillits Tonsillectomy Tonsillectomy, as the name suggests, is the surgical procedure to remove the tonsils. Often, tonsillectomy is done at the same time as adenoidectomy. Indications Indications are divided into :? A. Absolute","pyqMatches":[{"year":"2013","no":1094,"q":"All are absolute indications of tonsillectomy except","o":["Suspicious malignancy","Peritonsillar abscess","Chronic tonsillits","Tonsils causing obstructive sleep apnea"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1886, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 163, '{"id":1886,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":163,"q":"Retraction of tympanic membrane touching promontory. What is sade''s grade?","o":["1","2","3","4"],"a":2,"e":"Ans. is ''c'' i.e., 3 Atelectic grades of pars tensa Sade classification:: Grade 1 = slight retraction of TM over the annulus Grade 2 = the TM touches the long process of the incus Grade 3 = the TM touches the promontory Grade 4 = the TM is adherent to the promontory","pyqMatches":[{"year":"2013","no":1019,"q":"Retraction of tympanic membrane touching promontory. What is sade''s grade?","o":["1","2","3","4"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1887, 'ENT', 'Ear', 'Easy', 'ENT', 164, '{"id":1887,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":164,"q":"Posterosuperior retraction pocket if allowed to progress will lead to?","o":["SNHL","Secondary cholesteatoma","Tympanosclerosi","Primary cholesteatoma"],"a":3,"e":"Ans. is''d'' i.e., Primary cholesteatoma Retraction pockets are more common in the postero-superior portion of pars-tensa of ear-drum (tympanic membrane). Two reasons have been attributed to this features :-","pyqMatches":[{"year":"2013","no":1021,"q":"Posterosuperior retraction pocket if allowed to progress will lead to?","o":["SNHL","Secondary cholesteatoma","Tympanosclerosi","Primary cholesteatoma"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1888, 'ENT', 'Ear', 'Easy', 'ENT', 165, '{"id":1888,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":165,"q":"Treatment of choice for atticoantral type of CSOM?","o":["Antiboiotics","Tympanoplasty","Modified radical mastoidectomy","None"],"a":2,"e":"Ans. is''c'' i.e., Modified radical mastoidectomy Treatment of atticoantral disease Since cholesteatoma is going to expand and destroy bone and mucous membrane, it has to be removed. Therefore, surgery is the mainstay of treatment. Primary aim is removal of disease by mastoidectomy to make ear safe followed by reconstruction of hearing at a later stage. Modified radical mastoidectomy is the surgery of choice. Two types of surgical procedures (mastoidectomy) are done to deal with cholesteatoma:-","pyqMatches":[{"year":"2013","no":1022,"q":"Treatment of choice for atticoantral type of CSOM?","o":["Antiboiotics","Tympanoplasty","Modified radical mastoidectomy","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1889, 'ENT', 'Ear', 'Easy', 'ENT', 166, '{"id":1889,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":166,"q":"Retraction of tympanic membrane touching the promontory. It is called ?","o":["Mild retraction","Severe retraction","Atelectasis","Adhesive otitis"],"a":2,"e":"Ans. is ''c'' i.e., Atelectasis Tympanic membrane retraction The retracted segment of eardrum is often known as a retraction pocket. The terms \"atelectasis\" or sometimes \"adhesive otitis media\" can be used to describe retraction of a large area of the pars tensa.","pyqMatches":[{"year":"2013","no":1018,"q":"Retraction of tympanic membrane touching the promontory. It is called ?","o":["Mild retraction","Severe retraction","Atelectasis","Adhesive otitis"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1890, 'ENT', 'Ear', 'Moderate', 'ENT', 167, '{"id":1890,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":167,"q":"All are true about Rinne''s test except ?","o":["Positive in normal ear","Positive in sensorineural hearing loss","Minimum 15-20 dB air bone gap is required in conductive deafness","Bone conduction is better in sensorineural hearing loss"],"a":3,"e":"Ans. is''d'' i.e., Bone conduction is better in sensorineural hearing loss Rinne''s Test The Rinne test is a tuning fork test that compares hearing by air conduction and bone conduction. The Rinne test is based on the idea that hearing mechanism is normally more efficient by air conduction (AC) than it is by bone conduction (BC), i.e., AC > BC in normal persons. For this reason, a tuning fork will sound louder and longer by air conduction than by bone conduction. However, this air conduction advantage is lost when there is a conductive hearing loss in which case the tuning fork sounds louder by bone conduction than by air-conduction. Method Administering the Rinne test involves asking the patient to indicate whether a vibrating tuning fork sounds louder when its base is held against mastoid process (bone conduction) or when its prongs are held near the pinna, facing the opening of ear canal (air conduction). After striking the fork, the clinician alternates it between these two positions so that the patient can make a judgement about which one is louder. Interpretation of Rinne''s test The outcome of the Rinne test is traditionally called \"positive\" if the fork is louder by air conduction and this finding implies that the ear is normal or has sensorineural hearing loss. The results are called \"negative\" if the bone-conduction is louder than air-conduction, which is interpreted as revealing the presence of conductive deafness i.e., lesions of either external ear, tympanic membrane, middle ear or ear ossicles.. In conductive deafness Rinne''s test will be negative if the conductive hearing loss is greater than 15-20 dB (minimum air bone gap 15- 20 dB). That means, at least 15-20 dB of conductive hear loss is required to show bone conduction better than air conduction, i.e., Negative Rinne''s test. A negative Rinne test for 256, 512 and 1024 Hz indicates a minimum air-bone gap (ABG) of 15, 30, 45 dB respectively. Therefore, AB gap can be made if tuning forks of 256, 512 and 1024 Hz are used : -","pyqMatches":[{"year":"2013","no":1006,"q":"All are true about Rinne''s test except ?","o":["Positive in normal ear","Positive in sensorineural hearing loss","Minimum 15-20 dB air bone gap is required in conductive deafness","Bone conduction is better in sensorineural hearing loss"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1891, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 168, '{"id":1891,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":168,"q":"Stimulation of horizontal semicircular canal causes nystagmus in which directions ?","o":["Vertical","Horizontal","Rotary","Any of the three"],"a":1,"e":"Ans. is ''b'' i.e., Horizontal The cupulae of the semicircular canals are stimulated by movement of endolymphatic fluid and each canal causes the nystagmus in its own plane :-","pyqMatches":[{"year":"2013","no":1000,"q":"Stimulation of horizontal semicircular canal causes nystagmus in which directions ?","o":["Vertical","Horizontal","Rotary","Any of the three"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1892, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 169, '{"id":1892,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":169,"q":"Bilateral past-pointing is due to defect in ?","o":["Brainstem","Cerebellum","Vestibular system","Basal ganglia"],"a":2,"e":"Ans. is ''c'' i.e., Vestibular system Past-pointing is the deviation of the extremities caused by either cerebellar hemisphere or vestibular disease. Testing is usually done with arms. The traditional method is to have the patient extend the arm and place his extended finger on the examiner''s index finger; then with the eye closed raise the arm directly overhead; than bring it back down precisely onto the examiner''s finger. If vestibular or cerebellar lesion is there, past pointing (deviation of limb) will be present. The two types (cerebellar and vestibular) past pointing have different patterns :-","pyqMatches":[{"year":"2013","no":1001,"q":"Bilateral past-pointing is due to defect in ?","o":["Brainstem","Cerebellum","Vestibular system","Basal ganglia"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1893, 'ENT', 'Nose & Paranasal Sinuses', 'Moderate', 'ENT', 170, '{"id":1893,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Moderate","source":"ENT","sourceNo":170,"q":"Major contribution in the formation of nasal septum is by all except ?","o":["Septal cartilage","Vomer","Ethmoid","Nasal bone"],"a":3,"e":"Ans. is ''d'' i.e., Nasal bone The medial wall, or nasal septum, is formed (from anteiror to posterior) by : (1) the septal cartilage (destroyed in a dried skull) (2) the perpendicular plate of the ethmoid bone, and (3) the vomer . It is usually deviated to one side. The vomer contributes to the inferior portion of the nasal septum; the perpendicular plate of the ethmoid bone contributes to the superior portion.","pyqMatches":[{"year":"2013","no":1052,"q":"Major contribution in the formation of nasal septum is by all except ?","o":["Septal cartilage","Vomer","Ethmoid","Nasal bone"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1894, 'ENT', 'Audiology', 'Moderate', 'ENT', 171, '{"id":1894,"subject":"ENT","chapter":"Audiology","difficulty":"Moderate","source":"ENT","sourceNo":171,"q":"All are true about conductive deafness except ?","o":["Rinne''s test is negative","Absolute bone conduction is normal","Weber is lateralized to poorer ear","There is decay in threshold tone"],"a":3,"e":"Ans. is ''d'' i.e., There is decay in threshold tone","pyqMatches":[{"year":"2013","no":1011,"q":"All are true about conductive deafness except ?","o":["Rinne''s test is negative","Absolute bone conduction is normal","Weber is lateralized to poorer ear","There is decay in threshold tone"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1895, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 172, '{"id":1895,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":172,"q":"Ethmoidal polyp is ?","o":["Due to infection","Single","Recurrent","Occurs in children"],"a":2,"e":"Ans. is ''c'' i.e., Recurrent","pyqMatches":[{"year":"2013","no":1074,"q":"Ethmoidal polyp is ?","o":["Due to infection","Single","Recurrent","Occurs in children"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1896, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 173, '{"id":1896,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":173,"q":"Most common cause of oroantral fistula ?","o":["TB","Penetrating injury","Tooth extraction","latrogenic"],"a":2,"e":"Ans. is ''c'' i.e., Tooth extraction Oroantral fistula It is communication between the antrum and oral cavity. Etiology Dental extraction :- Most important cause and maxillary first molar accounts for 50% of oral-antral fistulas caused by extractions. Maxillary second and third molar extractions account for other 50%. Infection :- TB, syphilis, leprosy of maxillary bone. Malignant neoplasm :- Causes erosion of antrum. Fracture or penetrating injuries of maxilla. Midline granuloma (a form of lymphoma) Failure of sublabial incision to heal after Caldwell - Luc operation. Clinical features Regurgitation of food Discharge (often foul smelling) Inability to built positive or negative pressure in mouth.","pyqMatches":[{"year":"2013","no":1091,"q":"Most common cause of oroantral fistula ?","o":["TB","Penetrating injury","Tooth extraction","latrogenic"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1897, 'ENT', 'Ear', 'Easy', 'ENT', 174, '{"id":1897,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":174,"q":"Killian dehiscence is in ?","o":["Superior constrictor","Inferior constrictor","Middle constrictor","None"],"a":1,"e":"Ans. is ''b'' i.e., Inferior constrictor Inferior constrictor muscle has two parts :- (i) Thyropharyngeous with oblique fibres, and (ii) Cricopharyngeous with transverse fibres. Between these two parts of inferior constrictor exists a potential gap called Killan''s dehiscence. It is also called the gateway to tear as perforation can occur at this site during esophagoscopy. It is also the site for herniation of pharyngeal mucosa in case of pharyngeal pouch.","pyqMatches":[{"year":"2012","no":103,"q":"Killian dehiscence is in ?","o":["Superior constrictor","Inferior constrictor","Middle constrictor","None"],"a":1,"source":"NEET_2012_Paper.pdf"},{"year":"2013","no":1078,"q":"Killian dehiscence is in ?","o":["Superior constrictor","Inferior constrictor","Middle constrictor","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2012","2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1898, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 175, '{"id":1898,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":175,"q":"Saddle nose is ?","o":["Depressed nose","Crooked nose","Deviated nose","C-shaped"],"a":0,"e":"Ans. is ''a'' i.e., Depressed nose Saddle nose (Depressed nose) Nasal dorsum is depressed (sagging of the bridge of nose). Depressed nasal dorsum may involve either bony, cartilaginous or both bony and cartilaginous components. Most common etiology : Nasal trauma Causes are hematoma, excessive surgical removal, trauma, syphilis, abscess, Leprosy, and tuberculosis. Crooked or deviated nose Crooked nose is the external deviation of nose due to deviation of the dorsal border of septal cartilage, forming a `C'' or ''S'' shaped curve. In crooked nose, the midline dorsum is curved in ''C'' or ''S'' shaped manner from the frontonasal angle to the tip of nose. In a deviated nose, the midline is straight but deviated to one side, midline is not curved as in crooked nose.","pyqMatches":[{"year":"2013","no":1061,"q":"Saddle nose is ?","o":["Depressed nose","Crooked nose","Deviated nose","C-shaped"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1899, 'ENT', 'Throat & Larynx', 'Easy', 'ENT', 176, '{"id":1899,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Easy","source":"ENT","sourceNo":176,"q":"Tonsillar fossa is bounded anteriorly by ?","o":["Pharyngobasilar fascia","Palatopharyngeal fold","Buccopharyngeal fascia","Palatoglossal fold"],"a":3,"e":"Ans. is ''d'' i.e., Palatoglossal fold Palatine tonsils are masses of lymphoid tissue that can be seen on the left and right sides at the back of the throat. There are two palatine tonsils, and each palatine tonsil (right or left) lies in the tonsilar sinus (tonsilar fossa) on the lateral wall of oropharynx. Tonsillar fossa bounded by the palatoglossal fold in front and the palatopharyngeal fold behind. Tonsils are lined by non - keratinized stratified squamous epithelium. Medial surface of each tonsil has 15-20 crypts, the largest of which is called Intratonsillar cleft or crypta magna (which represents persistence of the ventral portion of the second pharyngeal pouch). Tonsillar bed is formed from within - outwards by :- Li Pharyngobasilar fascia Superior constrictor (above) and palatopharyngeus muscle Styloglossus (below) Buccopharyngeal fascia","pyqMatches":[{"year":"2013","no":1062,"q":"Tonsillar fossa is bounded anteriorly by ?","o":["Pharyngobasilar fascia","Palatopharyngeal fold","Buccopharyngeal fascia","Palatoglossal fold"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1900, 'ENT', 'Ear', 'Easy', 'ENT', 177, '{"id":1900,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":177,"q":"Passavants ridge is formed by ?","o":["Palatoglossus","Superior constrictor","Salpingopharyngeus","Palatopharyngeus"],"a":3,"e":"Ans. is ''d'' i.e., Palatopharyngeus Pharynx has two group of muscles :? * Intrinsic muscles :- Stylopharyngeous, salpingopharyngeous, palatopharyngeous. * Extrinsic muscles :- Superior constrictor, middle constrictor, inferior constrictor. - All muscles of pharynx are supplied by cranial accessory through branches of vagus via pharyngeal plexus except stylopharyngeus which is supplied by glossopharyngeal. - Inferior constrictor muscle has two parts :- (i) Thyropharyngeous with oblique fibres, and (ii) Cricophatyngeous with transverse fibres. - Between these two parts of inferior constrictor exists a potential gap called Killan''s dehiscence. It is also called the gateway to tear as perforation can occur at this site during esophagoscopy. It is also the site for herniation of pharyngeal mucosa in case of pharyngeal pouch. - Upper fibers of palatopharyngeus constitute the Passavant''s muscle which on contraction raises a ridge called Passavant''s ridge on posterior wall of nasopharynx.","pyqMatches":[{"year":"2012","no":101,"q":"Passavants ridge is formed by ?","o":["Palatoglossus","Superior constrictor","Salpingopharyngeus","Palatopharyngeus"],"a":3,"source":"NEET_2012_Paper.pdf"},{"year":"2013","no":1079,"q":"Passavants ridge is formed by ?","o":["Palatoglossus","Superior constrictor","Salpingopharyngeus","Palatopharyngeus"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2012","2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1901, 'ENT', 'Ear', 'Easy', 'ENT', 178, '{"id":1901,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":178,"q":"Hot potato voice is characteristic of ?","o":["Nasopharyngeal carcinoma","Glottic carcinoma","Subglottic carcinoma","Supraglottic carcinoma"],"a":3,"e":"Ans. is ''d'' i.e., Supraglottic carcinoma Clinical features of supraglottic carcinoma Pain on swallowing is the most frequent initial symptom -- Devita 7th/e p. 698 Mass in neck may be the first sign. Hoarsness is a late symptom. Pain may be referred to ear by vagus nerve and auricular nerve of arnold. Late symptoms include foul breath, dysphagia and aspiration. Large tumors can cause \"hot potato voice/muffled voice\". Hemoptysis, sore throat, shorteness of breath, stridor, otalgia and aspiration pneumonia may also occur.","pyqMatches":[{"year":"2013","no":1089,"q":"Hot potato voice is characteristic of ?","o":["Nasopharyngeal carcinoma","Glottic carcinoma","Subglottic carcinoma","Supraglottic carcinoma"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1902, 'ENT', 'Ear', 'Moderate', 'ENT', 179, '{"id":1902,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":179,"q":"All are early complications of tracheostomy except?","o":["Hemorrhage","Pneumothorax","Injury to esophagus","Tracheal stenosis"],"a":3,"e":"Ans. is ''d'' i.e., Tracheal stenosis Immediate (at the time of operation) Hemorrhage Apnea Pneumothorax Injury to RLN Aspiration of blood Injury to esophagus Complications of tracheostomy Intermediate (first few hours or days) Bleeding (reactionary or secondary) Displacement of tube Blocking of tube Subcutaneous emphysema Tracheitis and tracheobronchitis Atelectasis and lung abscess Local wound infection and granulations Late (with prolonged use of tube for weeks or months) Hemorrhage, due to erosion of major vessel Laryngeal stenosis Tracheal stenosis Tracheo-esophageal fistula Problem of decannulation Persistent tracheocutaneous fistula Problem of tracheostomy scar","pyqMatches":[{"year":"2013","no":1101,"q":"All are early complications of tracheostomy except?","o":["Hemorrhage","Pneumothorax","Injury to esophagus","Tracheal stenosis"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1903, 'ENT', 'Throat & Larynx', 'Easy', 'ENT', 180, '{"id":1903,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Easy","source":"ENT","sourceNo":180,"q":"Nasopharynx is lined by which epithelium ?","o":["Stratified squamous nonkerationized","Stratified squamous keratinized","Ciliated columnar","Cuboidal"],"a":2,"e":"Ans. is ''c'' i.e., Ciliated columnar The two main types of epithelia lining the nasopharynx are stratified squamous (comprising approximately 60% of nasopharyngeal epithelium) and pseudostratified columnar respiratory epithelium containing ciliated cells, goblet cells and basal cells.","pyqMatches":[{"year":"2015","no":113,"q":"Nasopharynx is lined by which epithelium ?","o":["Stratified squamous nonkerationized","Stratified squamous keratinized","Ciliated columnar","Cuboidal"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1904, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 181, '{"id":1904,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":181,"q":"Vidian neurectomy is done for ?","o":["Allergic rhinitis","Atrophic rhinitis","Vasomotor rhinitis","Chronic hypertrophic rhinitis"],"a":2,"e":"Ans. is ''c'' i.e., Vasomotor rhinitis Vasomotor rhinitis Vasomotor is a nonallergic condition that involves a constant runny nose, sneezing and nasal congestion, i.e., the nose is stuffy or runny for reasons other than allergies and infections. The exact etiology is unknown, but triggers include emotions, odors, poor air quality, spicy foods, and medication side effects. Pathogenesis include:- Parasympathetic overactivity Hyperactive nasal mucosa to several non-specific stimuli especially in women of 20-40 years. Symptoms of vasomotor rhinitis include excessive clear rhinorrhoea, nasal obstruction/congestion, irritation, paroxysmal sneezing and post-nasal drip. Nasal mucosa is hypertrophied & congested; and mucosa of turbinates may give mulberry like appearance and is pale to dusky red in colour. Complications of vasomotor rhinitis include hypertrophic rhinitis & sinusitis, and nasal polyp. Treatment Treatment of vasomotor rhinitis includes : -","pyqMatches":[{"year":"2014","no":1136,"q":"Vidian neurectomy is done for ?","o":["Allergic rhinitis","Atrophic rhinitis","Vasomotor rhinitis","Chronic hypertrophic rhinitis"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1905, 'ENT', 'Head & Neck', 'Easy', 'ENT', 182, '{"id":1905,"subject":"ENT","chapter":"Head & Neck","difficulty":"Easy","source":"ENT","sourceNo":182,"q":"Lymphatic drainage of orpharynx is mainly through?","o":["Superficial cervical lymph nodes","Submandibular nodes","Jugulodigastric node","Jugulo-omohyoid nodes"],"a":2,"e":"Ans. is ''c'' i.e., Jugulodigastric nodes Deep cervical lymph nodes are divided into two groups :- (i) jugulodigastric, and (ii) jugulo-omohyoid. Lymphatics from oropharynx drain into jugulodigastric nodes. Lymphatic drainage of pharynx Lymphatic drainage of pharynx may be :?","pyqMatches":[{"year":"2013","no":1080,"q":"Lymphatic drainage of orpharynx is mainly through?","o":["Superficial cervical lymph nodes","Submandibular nodes","Jugulodigastric node","Jugulo-omohyoid nodes"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1906, 'ENT', 'Ear', 'Moderate', 'ENT', 183, '{"id":1906,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":183,"q":"All are true about otitic barotrauma except ?","o":["Conductive deafness","Retracted tympanic membrane","Catheterization can be used","Occurs during sudden ascent in aircraft"],"a":3,"e":"Ans. is ''d'' i.e., Occurs during sudden ascent in aircraft Otitic Barotrauma This condition is seen when the ambient pressure is rising, e.g. in scuba diving (underwater diving), descending in an aircraft, or compression in pressure chamber. It occurs due to pressure differences between the inside and outside of the eardrum. Clinical features Ear discomfort or pain, hearing loss, and tinnitus are common Vertigo is uncommon Otoscopy findings are :- Congested and retracted tympanic membrane Blood may extravasate into middle ear producing haemotympanum On examination there is conductive deafness. Pathogenesis of otitic barotrauma The middle ear pressure is normally maintained at a level similar to that of the atmosphere by the function of Eustachian tube which allows passage of air from middle ear to pharynx. Sudden or dramatic changes of external pressure may defeat this mechanism and cause injury to middle ear. When atmospheric pressure is higher than that of middle ear by critical level of 90 mm Hg, eustachian tube gets locked as the soft tissues of pharyngeal end of the tube are forced into the lumen by high atmospheric pressure. This results in sudden negative pressure in the middle ear which causes retraction of tympanic membrane, hyperemia, transudation with hemorrhage and development of Aero-otitis media (barotrauma) At pressure difference >100 to 500 mm Hg, tympanic membrane can rupture → when the pressure difference is more than 100 mg Hg, tympanic membrane can rupture. Treatment of otitic Barotrauma Routine self treatment of pain associated with changing pressure in air craft includes chewing gum, attempting to yawn & swallow, blowing against closed nostrils, and using decongestant nasal sprays. The aim is to restore middle ear areation. Catheterization or politzerization can also be used. If the eustachian tube will not open with other treatments, surgery may be necessory. Myringotomy and aspiration of fluid is the surgical procedure used.","pyqMatches":[{"year":"2013","no":1002,"q":"All are true about otitic barotrauma except ?","o":["Conductive deafness","Retracted tympanic membrane","Catheterization can be used","Occurs during sudden ascent in aircraft"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1907, 'ENT', 'Ear', 'Easy', 'ENT', 184, '{"id":1907,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":184,"q":"Tear drop sign is seen in ?","o":["Fracture zygomatic arch","Fracture maxilla","Fracture mandible","Blow out fracture"],"a":3,"e":"Ans. is ''d'' i.e., Blow out fracture Fractures of the floor of the orbit Zygomatic fracture and Le fort II maxillary fractures are always accompanied by fractures of orbital floor. Isolated fractures of orbital floor, when a large blunt object strikes the globe, are called \"blow out fractures\". Clinical features Ecchymosis of lid, conjunctiva and sclera. Endophthalmos with inferior displacement of the eye-ball. This becomes apparent when oedema subsides. Diplopia, which may be due to displacement of the eyeball or entrapment of inferior rectus and inferior oblique muscles. Hypoaesthesi a or anaesthesia of cheek and upper lip, if infraorbital nerve is involved. Diagnosis J Water''s view show a convex opacity bulging into the antrum from above, i.e., Tear drop opacity. CT scan is diagnostic.","pyqMatches":[{"year":"2013","no":1075,"q":"Tear drop sign is seen in ?","o":["Fracture zygomatic arch","Fracture maxilla","Fracture mandible","Blow out fracture"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1908, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 185, '{"id":1908,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":185,"q":"Inverted papilloma of nose arise from ?","o":["Nasal septum","Roof of the nose","Tip of the nose","Lateral wall of the nose"],"a":3,"e":"Ans. is ''d'' i.e., Lateral wall of the nose Inverted Papilloma (Transitional cell papilloma/Schneiderion papilloma) Inverted papilloma is a benign neoplasm occurs mostly between 40- 70 years with male preponderance (5 : 1). It arises from the lateral wall of nose and is always unilateral. Rarely, it may arise from nasal septum. Features of inverted papilloma are : - It shows finger like epithelial invasions into the underlying stroma of the epithelium rather than on surface so called inverted papilloma. It is usually unilateral and is a locally aggressive tumour. Patients complain of nasal obstruction, rhinorrhea & unilateral epistaxis. In 10-15% cases there may be associated squamous cell carcinoma. Treatment is adequate local excision. If it arises in maxillary sinus, then a radical antrostomy is carried out. If it arises in the ethmoidal sinus, an external ethmoidectomy is done. If it arises from nose, treatment is wide surgical excision by lateral rhinotomy. Has a tendency to recur even after removal.","pyqMatches":[{"year":"2014","no":1127,"q":"Inverted papilloma of nose arise from ?","o":["Nasal septum","Roof of the nose","Tip of the nose","Lateral wall of the nose"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1909, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 186, '{"id":1909,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":186,"q":"True about external nose ?","o":["Upper 2/3 is bony","Lower 1/3 is cartilaginous","Single lateral cartilage","Two nasal bones"],"a":3,"e":"Ans. is''d'' i.e., Two nasal bones External nose has an osteocartilaginous framework of which upper one - third is bony and lower two-third is cartilaginous.","pyqMatches":[{"year":"2013","no":1053,"q":"True about external nose ?","o":["Upper 2/3 is bony","Lower 1/3 is cartilaginous","Single lateral cartilage","Two nasal bones"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1910, 'ENT', 'Ear', 'Easy', 'ENT', 187, '{"id":1910,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":187,"q":"Indication of BAHA (Bone-anclored hearing aid)","o":["Bilateral hearing loss","Sensorineural hearing loss","Congenital canal atresia","All of the above"],"a":2,"e":"Ans. is ''c'' i.e., Congenital canal atresia Indications for BAHA When air-conduction (AC) hearing aid connot be used; Canal atresia, congenital or acquired, not amenable to treatment. Chronic ear discharge, not amenable to treatment. Excessive feedback and discomfort from air-conduction hearing aid. Conductive or mixed hearing loss, e.g. otoscierosis and tympanosclerosis where surgery is contraindicated. Single-sided hearing loss.","pyqMatches":[{"year":"2013","no":1049,"q":"Indication of BAHA (Bone-anclored hearing aid)","o":["Bilateral hearing loss","Sensorineural hearing loss","Congenital canal atresia","All of the above"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1911, 'ENT', 'Ear', 'Easy', 'ENT', 188, '{"id":1911,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":188,"q":"Muller''s manoeuver is used ?","o":["To findout opening of mouth","To remove laryngeal foreign body","To find degree of obstruction in sleep disordered breathing","To remove foreign body from ear"],"a":2,"e":"Ans. is ''c'' i.e., To find degree of obstruction in sleep disordered breathing Muller''s manoeuvre Used to find the level and degree of obstruction in sleep- disordered breathing. It is performed while using flexible nasopharyngoscope. First the examiner sees the upper airways at rest and then during the time when patient makes maximal inspiratory effort with nose and mouth closed. Base of tongue, lateral pharyngeal wall and palate are examined for collapsibility and then rated form 0 (minimal collapse) to 4+ (complete collapse).","pyqMatches":[{"year":"2013","no":1050,"q":"Muller''s manoeuver is used ?","o":["To findout opening of mouth","To remove laryngeal foreign body","To find degree of obstruction in sleep disordered breathing","To remove foreign body from ear"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1912, 'ENT', 'Throat & Larynx', 'Easy', 'ENT', 189, '{"id":1912,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Easy","source":"ENT","sourceNo":189,"q":"Rosen''s incision is used for ?","o":["Septoplasty","SMR","Stapedectomy","Tonsillectomy"],"a":2,"e":"Ans. is ''c'' i.e., Stapedectomy Rosen''s incision is the most commonly used for stapedectomy through endomeatal or transcanal approach. Also know Lempert''s incision is used for endural approach. Wilde''s incision is used for postaural approach.","pyqMatches":[{"year":"2013","no":1102,"q":"Rosen''s incision is used for ?","o":["Septoplasty","SMR","Stapedectomy","Tonsillectomy"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1913, 'ENT', 'Head & Neck', 'Easy', 'ENT', 190, '{"id":1913,"subject":"ENT","chapter":"Head & Neck","difficulty":"Easy","source":"ENT","sourceNo":190,"q":"Submandibular nodes are classified as ?","o":["Level IA neck nodes","Level IB neck nodes","Level II neck nodes","Level III neck nodes"],"a":1,"e":"Ans. is ''b'' i.e., Level 1B neck nodes Division of neck nodes according to levels Level I Submental (IA) Submandibular (IB) Level II Upper jugular Level III Mid jugular Level IV Lower jugular Level V Posterior triangle group (Spinal accessory and transverse cervical chains) Level VI Prelaryngeal Pretracheal Paratracheal Level VII Nodes of upper mediastinum","pyqMatches":[{"year":"2013","no":992,"q":"Submandibular nodes are classified as ?","o":["Level IA neck nodes","Level IB neck nodes","Level II neck nodes","Level III neck nodes"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1914, 'ENT', 'Throat & Larynx', 'Moderate', 'ENT', 191, '{"id":1914,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Moderate","source":"ENT","sourceNo":191,"q":"Hyponasal voice is seen in all except ?","o":["Adenoids","Nasal polyp","Cleft palate","Habitual"],"a":2,"e":"Ans. is ''c'' i.e., Cleft palate Cause of hyponasality and hypernasality Hyponasality Hypernasality Common cold Velopharyngeal insufficiency Nasal allergy Congenitally short soft palate Nasal polyp Submucous palate Nasal growth Large nasopharynx Adenoids Cleft of soft palate Nasopharyngeal mass Paralysis of soft palate Familial speech pattern Post-adenoidectomy Habitual Oronasal fistula Familial speech pattern Habitual speech pattern","pyqMatches":[{"year":"2013","no":1051,"q":"Hyponasal voice is seen in all except ?","o":["Adenoids","Nasal polyp","Cleft palate","Habitual"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1915, 'ENT', 'Ear', 'Easy', 'ENT', 192, '{"id":1915,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":192,"q":"Schatzki''s Ring is present at ?","o":["Upper end of trachea","Lower end of trachea","Upper end of esophagus","Lower end of esophagus"],"a":3,"e":"Ans. is ''d'' i.e., Lower end of esophagus Schatzki''s ring It occurs at the junction of squamous and columnar epithelium at the lower end of oesophagus and has also been called lower oesophageal ring. Usually seen in patients above 50 years of age. Cause is unknown. Symptomatic patients complain of intermittent dysphagia and some may even present with bolus obstruction. It may be associated with hiatus hernia. Treatment is oesophageal dilatation.","pyqMatches":[{"year":"2013","no":1092,"q":"Schatzki''s Ring is present at ?","o":["Upper end of trachea","Lower end of trachea","Upper end of esophagus","Lower end of esophagus"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1916, 'ENT', 'Audiology', 'Easy', 'ENT', 193, '{"id":1916,"subject":"ENT","chapter":"Audiology","difficulty":"Easy","source":"ENT","sourceNo":193,"q":"\"Rising sun\" appearance is seen in -","o":["ASOM","CSOM","Glomus tumor","Acoustic neuroma"],"a":2,"e":"Ans. is ''c'' i.e., Glomus tumor Clinical features of glomus tumor The earliest symptoms of glomus tumour is pulsatile tinnitus (earliest) and hearing loss. Hearing loss is conductive and slowly progressive. These are followed by blood stained otorrhoea and earache. Before the tympanic membrane (eardrum) is perforated a red swelling is seen to arise from the floor of middle ear, i.e. \"Rising sun\" appearance. This results in a red reflex through the intact tympanic membrane. Sometimes, eardrum may be bluish and bulging. o Pulsation sign (Brown sign) is positive, i.e. when ear canal pressure is raised with Siegle''s speculum, tumor pulsates vigorously and then blanches; reverse happens with release of pressure. Aquino sign is positive, i.e. blanching of mass with manual compression of ipsilateral carotid artery. When the tumour perforates the eardrum a polypus will be seen in the meatus and this will bleed profusely if touched. Cranial nerve palsies is a late feature appearing several years after aural symptoms. IXth to XIV'' cranial nerves may be paralysed. This can cause dysphagia and hoarseness, and weakness of trapezius and sternocleidomastoid muscles, unilateral paralysis of soft palate, pharynx and vocal cord. Ausculation with stethoscope over the mastoid may reveal audible systolic bruit. Some glomus tumours secrete catecholamines and produce symptoms like tachycardia, arrhythmias, sweating, flushing and headache etc. Facial palsy may be caused by glomus tympanicum type of glomus tumor. Audiometry shows conductive deafness, However if inner ear is invaded, mixed conductive and sensorineural hearing loss is seen.","pyqMatches":[{"year":"2013","no":1043,"q":"\"Rising sun\" appearance is seen in","o":["ASOM","CSOM","Glomus tumor","Acoustic neuroma"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1917, 'ENT', 'Ear', 'Easy', 'ENT', 194, '{"id":1917,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":194,"q":"Cart-wheel appearance of tympanic membrane in ASOM is due to ?","o":["Perforation of tymparic membrane","Edema of tympanic membrane","Congested blood vessels along malleus","Granulation tissue on tympanic membrane"],"a":2,"e":"Ans. is ''c'' i.e., Congested blood vessels along malleus Stages of ASOM ASOM runs through the following stages and therefore presentation depends upon the stage :","pyqMatches":[{"year":"2013","no":1023,"q":"Cart-wheel appearance of tympanic membrane in ASOM is due to ?","o":["Perforation of tymparic membrane","Edema of tympanic membrane","Congested blood vessels along malleus","Granulation tissue on tympanic membrane"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1918, 'ENT', 'Ear', 'Moderate', 'ENT', 195, '{"id":1918,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":195,"q":"In noice induced hearing loss, audiogram shows a typical notch at","o":["1000 Hz","2000 Hz","3000 Hz","4000 Hz"],"a":3,"e":"Ans. is ''d'' i.e., 4000 Hz Noise induced hearing loss Exposure to loud noise can lead to permanent hearing threshold shifts. This may happen immediately with extreme exposure (nearby explosion or gunfire), but more commonly occurs slowly over time with repeated exposure to industrial or environmental noise. Patients will often have a typical 4-KHz (4000 Hz) notch (dip at 4000 Hz) in their audiogram called acoustic dip. Auditory effects of noice are :?","pyqMatches":[{"year":"2013","no":1008,"q":"In noice induced hearing loss, audiogram shows a typical notch at","o":["1000 Hz","2000 Hz","3000 Hz","4000 Hz"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1919, 'ENT', 'Ear', 'Easy', 'ENT', 196, '{"id":1919,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":196,"q":"In sensorineural hearing loss, weber''s test is lateralized to","o":["Normal ear","Defective ear","Not lateralized","May alternate"],"a":0,"e":"Ans. A. Weber test is lateralized to the unaffected or normal ear. PURPOSE: Determination of a conductive vs. a sensorineural hearing loss. Strike tuning fork and place base in the center of the forehead or the top of the head Ask if the tone is louder in the left ear, the right ear or equally loud in both ears due to the sound localization process, In a patient with a unilateral conductive hearing loss, the sound will be louder in the affected ear (airborne sounds mask bone conduction in the normal ear; conductive loss prevents masking in affected ear sound is perceived to be louder in affected ear) In a patient with unilateral sensorineural hearing loss, the sound is louder in the normal ear (no signal is transduced by the cochlea on the affected side, therefore the sound is louder on the normal side and is perceived to be coming from that side In a normal person or a person with symmetrical hearing loss, it is equally loud in both ears. In other words, a normal patient, the Weber tuning fork sound is heard equally loudly in both ears, with no one ear hearing the sound louder than the other (lateralization). In a patient with hearing loss, the Weber tuning fork sound is heard louder in one ear (lateralization) than the other.","pyqMatches":[{"year":"2013","no":1007,"q":"In sensorineural hearing loss, weber''s test is lateralized to","o":["Normal ear","Defective ear","Not lateralized","May alternate"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1920, 'ENT', 'Ear', 'Easy', 'ENT', 197, '{"id":1920,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":197,"q":"Which of the following is responsible for localization of sound ?","o":["Cochlear nerve","Cochlea","Superior olivary nucleus","Cochlear nuclei"],"a":2,"e":"Ans. is ''c'' i.e., Superior olivary nucleus Localization of sound in space A human can distinguish sounds originating from sources separated by as little as 1 degree. Binaural receptive fields (which is a feature of most auditory neurons above the level of cochlear nuclei) contribute to sound localization. In other words, relay nuclei in the brain stem (especially the superior olivary nuclei complex) mediate localization of sound. The auditory system uses following clues to judge the origin of sound :? Time lag between the entry of sound in two ears :- For example, if the sound originates from the right side of a person, it reaches the right ear earlier than the left ear. This time lag is more important for relatively low -frequency sounds (below 3000 Hz). Difference in intensities between the sound in the two ears :- It is important for sounds of higher frequencies (>3000 Hz). Sounds coming from directly in front of the individual and the back of the individual cannot be differentiated by the above two mechanisms. Here shape of pinna plays a role, it changes the quality of the sound depending on the direction from which sound comes.","pyqMatches":[{"year":"2013","no":998,"q":"Which of the following is responsible for localization of sound ?","o":["Cochlear nerve","Cochlea","Superior olivary nucleus","Cochlear nuclei"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1921, 'ENT', 'Ear', 'Easy', 'ENT', 198, '{"id":1921,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":198,"q":"Endolymph resembles ?","o":["CSF","ICF","ECF","Plasma"],"a":1,"e":"Ans. is ''b'' i.e., ICF Endolymph → Resembles intracellular fluid, rich in I+ ions. Perilymph (ectolymph) → Resembles ECF, rich in Na'' ions. Perilymph communicates with CSF through cochlear acqueduct therefore has characteristics similar to CSF. Fluid in the inner ear There are two main fluids in the inner ear : ?","pyqMatches":[{"year":"2013","no":997,"q":"Endolymph resembles ?","o":["CSF","ICF","ECF","Plasma"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1922, 'ENT', 'Ear', 'Moderate', 'ENT', 199, '{"id":1922,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":199,"q":"All are intracranial complications of otitis media except?","o":["Lateral sinus thrombophlebitis","Facial nerve palsy","Brain abscess","Hydrocephalus"],"a":1,"e":"Ans. is ''b'' i.e., Facial nerve palsy Intracranial Complications from Otitis Media Intracranial complications occur after the infectious (or inflammatory) process proceeds beyond the temporal bone \"requiring immediate and precise therapeutic intervention.\" Most common intracranial complications include meningitis, followed by brain abscess and lateral sinus thrombosis, subdural empyema, epidural abscess, and otic hydrocephalus.","pyqMatches":[{"year":"2013","no":1027,"q":"All are intracranial complications of otitis media except?","o":["Lateral sinus thrombophlebitis","Facial nerve palsy","Brain abscess","Hydrocephalus"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1923, 'ENT', 'Ear', 'Easy', 'ENT', 200, '{"id":1923,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":200,"q":"Most commonly used tuning fork in ear examination?","o":["128 Hz","256 Hz","512 Hz","1024 Hz"],"a":2,"e":"Ans. is ''c'' i.e., 512 Hz Commonly used tuning fork has a frequency of 512 Hz. Forks of other frequencies, e.g. 256 and 1024 Hz should also be available.","pyqMatches":[{"year":"2013","no":1003,"q":"Most commonly used tuning fork in ear examination?","o":["128 Hz","256 Hz","512 Hz","1024 Hz"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1924, 'ENT', 'Head & Neck', 'Easy', 'ENT', 201, '{"id":1924,"subject":"ENT","chapter":"Head & Neck","difficulty":"Easy","source":"ENT","sourceNo":201,"q":"Modified radical neck dissection includes which level of cervical lymph nodes?","o":["I-Ill","I-IV","I-V","I-Vil"],"a":2,"e":"Ans. is ''c'' i.e., I-V Radical neck dissection During radical neck dissection, following are removed. a. Lymph nodes of submental, submandibular, upper, middle and lower jugular, and lateral (posterior) triangle regions, i.e. Level I to V along with its fibrofatty tissue. b. Sternomastoid muscle. c. Internal jugular vein. d. Spinal accessory nerve. e. Submandibular salivary gland. f. Tail of the parotid. g. Omohyoid muscle. Following structures are saved - Carotid artery Brachial plexus, phrenic nerve, vagus nerve, cervical sympathetic chain, marginal mandibular branch of facial, lingual and hypoglosal nerve. Modified neck dissection It is similar to radical neck dissection but with preservation of one or more following structures -","pyqMatches":[{"year":"2013","no":993,"q":"Modified radical neck dissection includes which level of cervical lymph nodes?","o":["I-Ill","I-IV","I-V","I-Vil"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1925, 'ENT', 'Miscellaneous', 'Moderate', 'ENT', 202, '{"id":1925,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Moderate","source":"ENT","sourceNo":202,"q":"All are seen in treacher collin syndrome except","o":["Conductive deafness","Cleft palate","Mandibular hypoplasia","Choanal atresia"],"a":3,"e":"Ans. is ''d'' i.e., Choanal atresia Treacher collins syndrome It is rare condition that presents several craniofacial deformities of different levels. This is a congenital malformation involving the first and second branchial arches. The disorder is characterized by abnormalities of the auricular pinna, hypoplasia of facial bones, antimongoloid slanting palpebral fissures with coloboma of the lower eyelids and cleft palate. Important clinical findings are :-","pyqMatches":[{"year":"2013","no":1104,"q":"All are seen in treacher collin syndrome except","o":["Conductive deafness","Cleft palate","Mandibular hypoplasia","Choanal atresia"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1926, 'ENT', 'Ear', 'Easy', 'ENT', 203, '{"id":1926,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":203,"q":"True about penderd''s syndrome ?","o":["Blindness","Conductive deafness","Sensorineural deafness","All of the above"],"a":2,"e":"Ans. is ''c'' i.e., Sensorineural deafness Important features of Pendered syndrome: Congenital disorder Mutation in gene SLC 26 A4. Which codes for a protein called pendrin (helps in transport of ions across membrane). Impaired activity of Pendrin is seen in inner ear and thyroid gland. Bilateral sensorineural hearing loss. Goiter. Sometimes hypothyroidism. Occasionally vestibular dysfunction. No specific treatment.","pyqMatches":[{"year":"2013","no":1105,"q":"True about penderd''s syndrome ?","o":["Blindness","Conductive deafness","Sensorineural deafness","All of the above"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1927, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 204, '{"id":1927,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":204,"q":"Endoscopic sinus surgery prerequisite?","o":["MRI of paranasal sinus","CT of PNS","Mucocilliary clearing testing","Acoustic tests"],"a":1,"e":"Ans. is ''b'' i.e., CT of PNS Endoscopic surgery of inflammatory diseases of paranasal sinuses (sinusitis or polyp) requires a very detailed preoperative knowledge of the individual anatomical conditions and pathological changes. CT scan are used best to visualize sinus areas. CT scan provides excellent definition of paranasal sinuses and is a prerequisite for endoscopic surgery. \"CT scan limited study coronal cuts in bone window is prerequisite for endscopic sinus surgery\"----Mohan Bansal","pyqMatches":[{"year":"2013","no":1068,"q":"Endoscopic sinus surgery prerequisite?","o":["MRI of paranasal sinus","CT of PNS","Mucocilliary clearing testing","Acoustic tests"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1928, 'ENT', 'Ear', 'Easy', 'ENT', 205, '{"id":1928,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":205,"q":"X-ray findings in chronic otitis media ?","o":["Honeycombing of mastoid","Sclerosis with cavity in mastoid","Clear-cut distinct bony partition between cells","None of the above"],"a":1,"e":"Ans. is ''b'' i.e., Sclerosis with cavity in mastoid","pyqMatches":[{"year":"2013","no":1024,"q":"X-ray findings in chronic otitis media ?","o":["Honeycombing of mastoid","Sclerosis with cavity in mastoid","Clear-cut distinct bony partition between cells","None of the above"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1929, 'ENT', 'Nose & Paranasal Sinuses', 'Moderate', 'ENT', 206, '{"id":1929,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Moderate","source":"ENT","sourceNo":206,"q":"What is not true about use of intranasal steroids in nasal polyposis?","o":["Reduce recurrence","Reduce obstruction","Effective in eosinophilically predominant polyp only","May cause epistaxis"],"a":2,"e":"Ans. is ''c'' i.e., Effective in eosinophilically predominant polyp only Intranasal steroids have been used extensively as first-line management of nasal polyposis with few side effects Usually, patients with small polyps and limited involvement on CT scan are good candidates for topical therapy alone. Intranasal steroids reduce nasal obstruction, polyp size, drainage and polyp recurrence. The effect of steroids seems to be nonspecific, improving symptoms in both eosinophilically and non​eosinophilically dominated polyps. Nasal bleeding is the most common adverse event and can usually be minimized by directing the medication away from nasal septum.","pyqMatches":[{"year":"2013","no":1055,"q":"What is not true about use of intranasal steroids in nasal polyposis?","o":["Reduce recurrence","Reduce obstruction","Effective in eosinophilically predominant polyp only","May cause epistaxis"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1930, 'ENT', 'Ear', 'Moderate', 'ENT', 207, '{"id":1930,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":207,"q":"Referred ear pain may travel through all except?","o":["Trigeminal nerve","Glossopharyngeal nerve","Abducens nerve","Vagus nerve"],"a":2,"e":"Ans. is ''c'' i.e., Abducens nerve Referred otalgia As ear receives nerve supply from Vth (auriculotemporal branch), IXth (tympanic branch) and Xth (auricular branch) cranial nerves; and from C2 (lesser occipital) and C2 and C3 (greater auricular), pain may be referred from these remote areas:","pyqMatches":[{"year":"2013","no":1046,"q":"Referred ear pain may travel through all except?","o":["Trigeminal nerve","Glossopharyngeal nerve","Abducens nerve","Vagus nerve"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1931, 'ENT', 'Head & Neck', 'Moderate', 'ENT', 208, '{"id":1931,"subject":"ENT","chapter":"Head & Neck","difficulty":"Moderate","source":"ENT","sourceNo":208,"q":"Acute retropharyngeal abscess, not true ?","o":["Due to lymphadenitis","Common in adults","Swelling on one side of midline","Incision & drainage"],"a":1,"e":"Ans. is ''b'' i.e., Common in adults Retropharyngeal abscess Retropharyngeal space lies behind the pharynx, i.e. between buccopharyngeal fascia covering pharyngeal constrictor muscles (anteriorly) and prevertebral fascia covering the prevertebral muscles (posteriorly). So, retropharyngeal space lies behind the pharyngeal constrictor muscles and anterior to prevertebral fascia covering the prevertebral muscles. Abscess in this space may present differently depending upon the age :? Abscess in infants (acute Retropharyngeal abscess) It is commonly seen in infants and children below 3 years of age. Most commonly it results from retropharyngeal lymphadenitis due to an upper respiratory tract infection. The presention is acute, i.e. child has high temperature and sore throat. There is smooth swelling (bulge) in posterior pharyngeal wall on one side of the midline. There is dysphagia, difficulty in breathing, stridor, croupy cough and torticollis. Swelling can be palpable per orally on the posterior pharyngeal wall. Treatment is incision and drainage. Abscess in adults (chronic retropharyngeal abscess) If an adult or an older child has a retropharyngeal infection it is likely to be due to a tuberculous infection of the cervical spine (caries of cervical spine). Sometime it may be secondary to tuberculous infection of retropharyngeal lymph nodes. It is of slow onset and gives rise to pharyngeal discomfort, rather than pain. There is fluctuant swelling in posterior pharyngeal wall, centrally in the midline (if it is secondary to caries of cervical spine) or on one side of midline (if it is secondary to tuberculosis of retropharyngeal nodes). Treatment includes incision and drainage of abscess along with full course of antitubercular treatment.","pyqMatches":[{"year":"2013","no":1081,"q":"Acute retropharyngeal abscess, not true ?","o":["Due to lymphadenitis","Common in adults","Swelling on one side of midline","Incision & drainage"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1932, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 209, '{"id":1932,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":209,"q":"Proof puncture is done through ?","o":["Superior meatus","Middle meatus","Inferior meatus","Sphenoethmoidal recess"],"a":2,"e":"Ans. is ''c'' i.e., Inferior meatus Proof functure (Antral puncture) This procedure involves puncturing the medial wall of maxillary sinus in the region of inferior meatus and irrigating the sinus. Indications","pyqMatches":[{"year":"2013","no":1093,"q":"Proof puncture is done through ?","o":["Superior meatus","Middle meatus","Inferior meatus","Sphenoethmoidal recess"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1933, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 210, '{"id":1933,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":210,"q":"Inspiratory stridor is found in what kind of lesions:","o":["Supraglottic","Subglottic","Tracheal","Bronchus"],"a":0,"e":"Answer A. Supraglottic Generally, an inspiratory stridor suggests airway obstruction above the glottis. While an expiratory stridor is indicative of obstruction in the lower trachea. A biphasic stridor suggests a glottic or subglottic lesion.","pyqMatches":[{"year":"2019","no":148,"q":"Inspiratory stridor is found in what kind of lesions:","o":["Supraglottic","Subglottic","Tracheal","Bronchus"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1934, 'ENT', 'Ear', 'Easy', 'ENT', 211, '{"id":1934,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":211,"q":"The most common site of the branchial cyst is:","o":["Posterior border of sternocleidomastoid","Anterior border of sternocleidomastoid","Digastric muscle","Omohyoid muscle"],"a":1,"e":"Answer. B. Anterior border of sternocleidomastoid A branchial cleft cyst (BCC) commonly presents as a solitary, painless mass in the neck of a child or young adult. They are most commonly located along the anterior border and the upper third of the sternocleidomastoid muscle in the anterior triangle of the neck.","pyqMatches":[{"year":"2019","no":147,"q":"The most common site of the branchial cyst is:","o":["Posterior border of sternocleidomastoid","Anterior border of sternocleidomastoid","Digastric muscle","Omohyoid muscle"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1935, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 212, '{"id":1935,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":212,"q":"Lower limit of retropharyngeal space is at ?","o":["C 7","Bifurcation of trachea","4th esophageal constriction","None"],"a":1,"e":"Ans. is''b''i.e., Bifurcation of trachea Retropharyngeal space is divided into two lateral spaces (space of gillette) by a fibrous band. Retropharyngeal space is limited above by the base of skull and below where the alar fascia fuses with buccopharyngeal fascia at the level of T4 and carina (bifurcation of trachea).","pyqMatches":[{"year":"2012","no":102,"q":"Lower limit of retropharyngeal space is at ?","o":["C 7","Bifurcation of trachea","4th esophageal constriction","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1936, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 213, '{"id":1936,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":213,"q":"Retroauricular incision is also known as?","o":["Rosen''s incision","Lempert''s -I incision","Lempert''s-II incision","Wilde''s incision"],"a":3,"e":"Ans. is''d''i.e., Wilde''s incision [Ref: Dhingra Sth/e p. 410] Wilde''s incision is used for postaural (retroauricular) approach. Lempert''s incision is used for endaural approach. Rosen''s incision is used for stapedectomy through endomeatal or transcanal approach,","pyqMatches":[{"year":"2013","no":991,"q":"Retroauricular incision is also known as?","o":["Rosen''s incision","Lempert''s -I incision","Lempert''s-II incision","Wilde''s incision"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1937, 'ENT', 'Ear', 'Easy', 'ENT', 214, '{"id":1937,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":214,"q":"Electrode of cochlear implant is placed at ?","o":["Horizontal semicircular canal","Scala media","Scala tympani","Scala vestibuli"],"a":2,"e":"Ans. is ''c'' i.e., Scala tympani [Ref Essentials otolaryngology 2d/e p. 82] Cochlear implants Internal component : - lt contains receiver/stimulator which is implanted under the skin and electrode which is implanted in the scala tympani of the cochlea a cochleostomy opening in the basal turn of cochlea. It may also be placed at other locations like promontory or round window but these sites has poorer performance.","pyqMatches":[{"year":"2013","no":1047,"q":"Electrode of cochlear implant is placed at ?","o":["Horizontal semicircular canal","Scala media","Scala tympani","Scala vestibuli"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1938, 'ENT', 'Ear', 'Easy', 'ENT', 215, '{"id":1938,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":215,"q":"Threshold of hearing in a young normal adult is ?","o":["0 dB","10 dB","20 dB","30 dB"],"a":0,"e":"Ans. is''a''i.e.,0 dB [Rd Dhingra 4n/e p. 21] Audiometric zero Threshold of hearing, i.e. The faintest intensity which a normal healthy person can hear will vary from person to person. The International Standards Organisation (ISO) adopted a standard for this, which is represented as the zero level on the audiometer (0 dB). According to ISO, audiometric zero is the mean value of minimal audible intensity in a group of normally hearing healthy young adults.","pyqMatches":[{"year":"2016","no":910,"q":"Threshold of hearing in a young normal adult is ?","o":["0 dB","10 dB","20 dB","30 dB"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1939, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 216, '{"id":1939,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":216,"q":"Nasopharyngeal carcinoma seen in which occupation?","o":["Asbestos industry","Cement industry","Wood workers","Chimney workers"],"a":2,"e":"Ans. is ''c'' i.e., Wood workers Ref Dhingra 4h/e p. 235; Nasopharyngeal carcinoma By Andrew Van Hasselt, Alan G. Gibb 2d/e p. 4 Wood dusts exposure is a risk factor of nasopharyngeal carcinoma and Adenocarcinoma of PNS. Formaldehyde exposure is a risk factor of Nasopharyngeal carcinoma.","pyqMatches":[{"year":"2014","no":1130,"q":"Nasopharyngeal carcinoma seen in which occupation?","o":["Asbestos industry","Cement industry","Wood workers","Chimney workers"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1940, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 217, '{"id":1940,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":217,"q":"Investigation of choice for nasopharyngeal angiofibroma?","o":["X-ray","MRI","Plane-CT","CT- contrast"],"a":3,"e":"Ans. is''d''i.e., CT contrast Ref: Dhingra Sth/e p. 262 CT scan of head with contrast enhancement is the investigation of choice for JNA.","pyqMatches":[{"year":"2013","no":1072,"q":"Investigation of choice for nasopharyngeal angiofibroma?","o":["X-ray","MRI","Plane-CT","CT- contrast"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1941, 'ENT', 'Ear', 'Moderate', 'ENT', 218, '{"id":1941,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":218,"q":"True about tubercular otitis media are all except?","o":["Spreads through eustachian tube","Causes painless ear discharge","May cause multiple perforations","Usually affects both ears e) None"],"a":3,"e":"Answer- D. Usually affects both ears Tuberculosis of middle ear is a comparatively rare entity usually seen in association with or secondary to pulmonary tuberculosis, infection reaches the middle ear through eustachian tube. Clinical features Generally, tuberculosis of middle ear is unilateral. It is characterized by painless otorrhoea which fails to respond to the usual antimicrobial treatment. There is painless watery otorrhea. Single or multiple perforation of tympanic membrane.","pyqMatches":[{"year":"2013","no":1029,"q":"True about tubercular otitis media are all except?","o":["Spreads through eustachian tube","Causes painless ear discharge","May cause multiple perforations","Usually affects both ears e) None"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1942, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 219, '{"id":1942,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":219,"q":"Feature of Granulomatosis with polyangiitis:","o":["Nasal polyp","Perforated Nasal septum","Persistant sinus","Crusting of nasal mucosa e) Collapse of nasal bridge"],"a":1,"e":":C:D Answer- (B) Perforated Nasal septum (C) Persistant sinus (D) Crusting of nasal mucosa Granulomatosis with polyangiitis (Wegener) is a distinct clinicopathologic entity characterized by granulomatous vasculitis of the upper and lower respiratory tracts together with glomerulonephritis. Disseminated vasculitis involving both small arteries and veins may occur. Nasal findings include crusting granulations, septal perforation & a saddle nose Destruction of the septum with a characteristic implosion of the nasal bridge.","pyqMatches":[{"year":"2013","no":1671,"q":"Feature of Granulomatosis with polyangiitis:","o":["Nasal polyp","Perforated Nasal septum","Persistant sinus","Crusting of nasal mucosa e) Collapse of nasal bridge"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1943, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 220, '{"id":1943,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":220,"q":"Tensor tympani is attached at ?","o":["Malleus","Incus","Stapes","Tympanic membrane"],"a":0,"e":"Ans. is ''a'' i.e., Malleus [Ref Gray''s Anatomy 38th le p. 485] Tympanic cavity has two muscles :","pyqMatches":[{"year":"2016","no":893,"q":"Tensor tympani is attached at ?","o":["Malleus","Incus","Stapes","Tympanic membrane"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1944, 'ENT', 'Ear', 'Easy', 'ENT', 221, '{"id":1944,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":221,"q":"Vesicles on external ear are seen in","o":["Otitis externa","Malignant otitis externa","Herpes zoster","Clear cell carcinoma"],"a":2,"e":"Ans. is ''c'' i.e., Herpes zoster [Ref Head and Neck Surgical Pathology p. 53] Ramsay Hunt syndrome It is lower motor neuron type of facial palsy due to Varicella (herpes) zoster. Pain is often a prominent feature and vesicles are seen in the ipsilateral ear, on the hard palate and/or on anterior two third of tongue. It may involve other cranial nerves-V, VIII, IX and X and cervical branches (C2, C3 & C4) that have anastomotic communications with facial nerve. This results in features like : Anaesthesia of face Giddiness Hearing impairment along with VII nerve palsy.","pyqMatches":[{"year":"2016","no":895,"q":"Vesicles on external ear are seen in","o":["Otitis externa","Malignant otitis externa","Herpes zoster","Clear cell carcinoma"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1945, 'ENT', 'Ear', 'Easy', 'ENT', 222, '{"id":1945,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":222,"q":"First line treatment for mild retraction pocket in the ear is","o":["Observation","Antibiotics","Tympanostomy tube","Surgical excision"],"a":1,"e":"Ans. is ''b'' i.e., Antibiotics [Ref Conquering Otitis media by Charles Bluestone p. 95] Retraction pocket It must be treated by an otolaryngologist. 1) Antibiotics A mild retraction pocket that is present in a fluid - filled middle ear can first be treated with antibiotics. 2) Tympanostomy If antibiotics does not work, a tympanostomy tube is usually inserted, and in most cases, the eardrum will return to normal. If the retraction pocket is very deep, a tube should be inserted, bypassing the antibiotic treatment. 3) Surgical excision If the retraction pocket still does not go away, the deformed eardrum should be operated on to prevent a cholesteatoma from developing. Once a cholesteatoma develops, surgery is the only way to remove it.","pyqMatches":[{"year":"2016","no":896,"q":"First line treatment for mild retraction pocket in the ear is","o":["Observation","Antibiotics","Tympanostomy tube","Surgical excision"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1946, 'ENT', 'Ear', 'Easy', 'ENT', 223, '{"id":1946,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":223,"q":"Cristae are seen in?","o":["Utricle","Saccule","Semicircular canal","Otolith membrane"],"a":2,"e":"Ans. is ''c'' i.e., Semicircular canal [Ref Dhingra Sth/e p. 16] Vestibular apparatus The vestibular apparatus within the inner ear detects head motion and position and transduces this information to a neural signal.","pyqMatches":[{"year":"2016","no":902,"q":"Cristae are seen in?","o":["Utricle","Saccule","Semicircular canal","Otolith membrane"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1947, 'ENT', 'Ear', 'Easy', 'ENT', 224, '{"id":1947,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":224,"q":"Function of saccule is?","o":["Linear acceleration","Angular acceleration","Senses position of head","Rotational movement"],"a":0,"e":":C Ans. is ''a'' i.e.,Linear acceleration & ''c'' i.e.,Senses position of head","pyqMatches":[{"year":"2016","no":903,"q":"Function of saccule is?","o":["Linear acceleration","Angular acceleration","Senses position of head","Rotational movement"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1948, 'ENT', 'Ear', 'Easy', 'ENT', 225, '{"id":1948,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":225,"q":"Earliest age for doing BERA is?","o":["In utero - before birth","At birth","3 months","6 months"],"a":1,"e":"Ans. is ''b'' i.e., At birth [Ref Logan Turner 10thle p. 254; PL Dhingra 4th/e p. 28] \"Worldwide screening is largely performed in newborn nursery with the first screening test performed from birth until 10 days of age\"","pyqMatches":[{"year":"2016","no":904,"q":"Earliest age for doing BERA is?","o":["In utero - before birth","At birth","3 months","6 months"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1949, 'ENT', 'Ear', 'Easy', 'ENT', 226, '{"id":1949,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":226,"q":"Most common malignancy of middle ear is","o":["Glomus tumor","Squamous cell carcinoma","Adenocarcinoma","Sarcoma"],"a":1,"e":"Ans. is ''b'' i.e.,Squamous cell carcinoma [Ref Textbook of ENT by Rakesh Shrivastav 2\"/e p. 67] Squamous cell carcinoma is the most common malignant tumor of the middle ear. Other forms of malignancy like adenocarcinoma and sarcoma are rare.","pyqMatches":[{"year":"2016","no":905,"q":"Most common malignancy of middle ear is","o":["Glomus tumor","Squamous cell carcinoma","Adenocarcinoma","Sarcoma"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1950, 'ENT', 'Ear', 'Easy', 'ENT', 227, '{"id":1950,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":227,"q":"Most common benign tumor of ear canal is","o":["Osteomas","Sebaceous adenoma","Papilloma","Ceruminoma"],"a":0,"e":"Ans. is ''a'' i.e., Osteomas [Ref Dhingra 6thle p. 107; Bansal ENT p. 160; Encyclopedia of Imaging, Baert p. 1318] Osteomas/ exostoses → most common benign tumors of the external auditory canal. Squamous cell carcinomas → Most common malignant tumors of the external auditory canal.","pyqMatches":[{"year":"2016","no":906,"q":"Most common benign tumor of ear canal is","o":["Osteomas","Sebaceous adenoma","Papilloma","Ceruminoma"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1951, 'ENT', 'Ear', 'Easy', 'ENT', 228, '{"id":1951,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":228,"q":"Diplacusis is","o":["Hearing sound with diminished intensity","Hearing sounds of two different tones","Hearing extremely loud sound","Perceiving light on production of sound"],"a":1,"e":"Ans. is ''b'' i.e.,Hearing sounds of two different tones [Ref Tuli lst/e p. 114] Monaural diplacusis :- In monaural diplacusis, a listener hears two tones when a single tone is presented to a single ear, i.e. one ear hears two different tones when presented one. Binaural diplacusis :- In binaural diplacusis, a listener hears two different tones in right & left ear when a single tone is presented to both ears. Both monoaural and binaural diplacusis are caused by inhomogenities in the cochlea that also give rise to spontaneous otoacoustic emissions.","pyqMatches":[{"year":"2016","no":907,"q":"Diplacusis is","o":["Hearing sound with diminished intensity","Hearing sounds of two different tones","Hearing extremely loud sound","Perceiving light on production of sound"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1952, 'ENT', 'Ear', 'Easy', 'ENT', 229, '{"id":1952,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":229,"q":"Which semicircular canal is most commonly involved in BPPV?","o":["Horizontal","Posterior","Superior","All of the above"],"a":1,"e":"Ans. is ''b'' i.e., Posterior [Ref Dhingra Sth/e p. 51] BPPV is thought to be caused by displacement of otoconia (mineral crystals) from the vestibule of inner ear into the semicircular canals. The posterior semicircular canal is most commonly involved, though superior and horizontal canals canal can also be affected. Otoconia or ear rocks are small crystals of calcium carbonate derived structure in the utricle which migrate into semicircular canals and cause BPPV. While saccules also contains otoconia, they are not able to migrate into the semicircular canals.","pyqMatches":[{"year":"2016","no":908,"q":"Which semicircular canal is most commonly involved in BPPV?","o":["Horizontal","Posterior","Superior","All of the above"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1953, 'ENT', 'Ear', 'Easy', 'ENT', 230, '{"id":1953,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":230,"q":"Most common ossicle affected due to trauma -","o":["Malleus","Incus","Stapes","All affected similarly"],"a":1,"e":"Ans. is ''b'' i.e, Incus [Ref Hearing : Practical Guide by Tysome p. 96] \"Significant head injury or direct trauma to the middle ear can result in subluxation of one or more of the ossicles, the incus being the most commonly affected","pyqMatches":[{"year":"2016","no":909,"q":"Most common ossicle affected due to trauma","o":["Malleus","Incus","Stapes","All affected similarly"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1954, 'ENT', 'Ear', 'Easy', 'ENT', 231, '{"id":1954,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":231,"q":"Singapore ear is","o":["Hypertrophy of sweat glands","Hypertrophy of sebaceous glands","Otitis externa","Excoriation of external ear skin"],"a":2,"e":"Ans. is ''c'' i.e, Otitis externa [Ref Clinical ENT 5th/e p. 223] Excessive moisture is an important predisposing factor for otitis externa as excessive moisture elevates the pH and removes protective cerumen. Therefore, humidity and hot climate predispose to otitis externa. Hence otitis externa is also known as :-","pyqMatches":[{"year":"2016","no":912,"q":"Singapore ear is","o":["Hypertrophy of sweat glands","Hypertrophy of sebaceous glands","Otitis externa","Excoriation of external ear skin"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1955, 'ENT', 'Ear', 'Hard', 'ENT', 232, '{"id":1955,"subject":"ENT","chapter":"Ear","difficulty":"Hard","source":"ENT","sourceNo":232,"q":"A diabetic patient presents with foul smelling ear discharge, fever and severe pain in the ear. On examination there is thick yellow coloured discharge from the ear and granulation tissue in the canal. Which of the following is the appropriate management for this patient?","o":["Surgical debridement","Antibiotic therapy","Cryotherapy","Laser removal of granulation tissue"],"a":1,"e":"Ans. is ''b'' i.e., Antibiotic therapy [Ref Dhingra 6th/e p. 52] The patient described in the question most likely has malignant otitis externa. So the treatment of choice is anti - pseudomonal antibiotics. Extensive surgical debridement once an important part of the treatment is now rarely needed","pyqMatches":[{"year":"2016","no":914,"q":"A diabetic patient presents with foul smelling ear discharge, fever and severe pain in the ear. On examination there is thick yellow coloured discharge from the ear and granulation tissue in the canal. Which of the following is the appropriate management for this patient?","o":["Surgical debridement","Antibiotic therapy","Cryotherapy","Laser removal of granulation tissue"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1956, 'ENT', 'Ear', 'Hard', 'ENT', 233, '{"id":1956,"subject":"ENT","chapter":"Ear","difficulty":"Hard","source":"ENT","sourceNo":233,"q":"Topodiagnosis of facial nerve has all the tests except","o":["Schirmer test","Bing test","Taste test","Salivary flow test"],"a":1,"e":"Ans. is ''b'' i.e., Bing test [Ref Dhingra 6th/e p. 98] The following tests are useful in finding the site of lesion in paralysis of lower motor neuron.","pyqMatches":[{"year":"2016","no":915,"q":"Topodiagnosis of facial nerve has all the tests except","o":["Schirmer test","Bing test","Taste test","Salivary flow test"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1957, 'ENT', 'Ear', 'Easy', 'ENT', 234, '{"id":1957,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":234,"q":"Which of the following is the function of tensor tympani muscle?","o":["Dampen very loud sound","Tenses tympanic membrane","Tenses pharyngotympanic tube","Prevent noise trauma to the inner ear"],"a":1,"e":"Ans. is ''b'' i.e., Tenses tympanic membrane [Ref Dhingra 6\"/e p. 8] Normal opening of the eustachian tube equalizes atmospheric pressure in the middle ear; closing of the Eustachian tube protects the middle ear from unwanted pressure fluctuations and loud sounds. The muscles of the eustachian tube system help to open and close the tube, thus allowing it to perform its function. The muscles are :?","pyqMatches":[{"year":"2016","no":916,"q":"Which of the following is the function of tensor tympani muscle?","o":["Dampen very loud sound","Tenses tympanic membrane","Tenses pharyngotympanic tube","Prevent noise trauma to the inner ear"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1958, 'ENT', 'Ear', 'Easy', 'ENT', 235, '{"id":1958,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":235,"q":"Pink reflex through intact tympanic membrane in active otosclerosis is known as","o":["Schwabach''s sign","Schwartz sign","Lyre''s sign","Chvostek''s sign"],"a":1,"e":"Ans. is ''b'' i.e., Schwartz sign [Ref Dhingra 5th/e p. 98; Current otolaryngology 2nd/e p. 674] A reddish hue / Flammingo pink may be seen on the promontory and oval window niche owing to the prominent vascularity associated with an otospongiotic focus. This is k/a Schwartz sign. Schwartz sign is a pink reflex, seen through intact tympanic membrane, in the area of oval window. It indicates active otosclerosis usually during pregnancy. Lyre''s sign is splaying apart of internal and external carotid arteries on angiogram in cases of carotid body tumour of the neck. Chvostek''s sign seen in hypocalcaemia as after total thyroidectomy where parathyroids have also been removed. Tapping over the distribution of facial nerve produces a twitch.","pyqMatches":[{"year":"2016","no":918,"q":"Pink reflex through intact tympanic membrane in active otosclerosis is known as","o":["Schwabach''s sign","Schwartz sign","Lyre''s sign","Chvostek''s sign"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1959, 'ENT', 'Ear', 'Easy', 'ENT', 236, '{"id":1959,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":236,"q":"SADE classification classifies","o":["Retraction of tympanic membrane","Extension of Glomus tumor","Mortality after heart disease during pregnancy","Extent of CSF rhinorrhea"],"a":0,"e":"Ans. is ''a'' i.e., Retraction of tympanic membrane [Ref Basic Clinical Radiobiology 5th/e p. 942] Sade''s classification of retraction of the pars tensa of the tympanic membrane defined two types of retraction and classified each on an ordinal scale :?","pyqMatches":[{"year":"2016","no":919,"q":"SADE classification classifies","o":["Retraction of tympanic membrane","Extension of Glomus tumor","Mortality after heart disease during pregnancy","Extent of CSF rhinorrhea"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1960, 'ENT', 'Ear', 'Hard', 'ENT', 237, '{"id":1960,"subject":"ENT","chapter":"Ear","difficulty":"Hard","source":"ENT","sourceNo":237,"q":"A 10 year old child presents with non foul purulent smelling discharge, which is painless. Patient reports that he is able to hear better in the presence of discharge than when the ear is dry. The most probable diagnosis is","o":["CSOM","Serous otitis media","Cholesteatoma","Mastoiditis"],"a":0,"e":"Ans. is ''a'' i.e., CSOM [Ref Dhingra 6th /e p. 68] Clinical features of CSOM Profuse mucopurulant discharge which is not foul smelling, i.e., non foul smelling discharge . Hearing loss (conductive type). If sensorineural component also occurs (i.e., mixed type), it arouses the suspician of toxic deafness. Sometimes, patient reports a paradoxical effect, i.e., hears better in the presence of discharge than when the ear is dry. This is due to round window shielding effect produced by discharge which helps to maintain phase differential. There is no pain, if it occurs it is due to associated otitis externa not due to otitis media. Since the infected area is open at both ends, discharge does not accumulate in the middle ear cavity. Ossicular chain is mostly uninvolved, if involved only long process of incus is involved.","pyqMatches":[{"year":"2016","no":920,"q":"A 10 year old child presents with non foul purulent smelling discharge, which is painless. Patient reports that he is able to hear better in the presence of discharge than when the ear is dry. The most probable diagnosis is","o":["CSOM","Serous otitis media","Cholesteatoma","Mastoiditis"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1961, 'ENT', 'Ear', 'Moderate', 'ENT', 238, '{"id":1961,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":238,"q":"Treatment of central safe perforation of tympanic membrane includes all except","o":["Aural toilet","Ear drops","Avulsion of aural polyp","Myringoplasty"],"a":2,"e":"Ans. is ''c'' i.e., Avulsion of aural polyp [Ref Dhingra 6th le p. 72] An aural polyp should never be avulsed as it may be arising from the stapes, facial nerve or horizontal canal and thus lead to facial paralysis or labyrinthitis. Treatment The aim is to control infection and eliminate ear discharge and at a later stage to correct the hearing loss by surgical means.","pyqMatches":[{"year":"2016","no":921,"q":"Treatment of central safe perforation of tympanic membrane includes all except","o":["Aural toilet","Ear drops","Avulsion of aural polyp","Myringoplasty"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1962, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 239, '{"id":1962,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":239,"q":"Agger nasi is","o":["Mucosal flap covering the nasolacrimal duct","Opening of the sinuses","Depression in front of middle turbinate","Elevation anterior to middle turbinate"],"a":3,"e":"Ans. is ''d'' i.e., Elevation anterior to middle turbinate [Ref Dhingra 5thie p. 150; Tuli 1\"/e p. 135] Atrium is a shallow depression in front of the middle turbinate. Agger nasi is an elevation just anterior to the attachement of middle turbinate.","pyqMatches":[{"year":"2016","no":923,"q":"Agger nasi is","o":["Mucosal flap covering the nasolacrimal duct","Opening of the sinuses","Depression in front of middle turbinate","Elevation anterior to middle turbinate"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1963, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 240, '{"id":1963,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":240,"q":"Quadrungular septum is seen in which of the following?","o":["Larynx","Nose","Cranium","Palate"],"a":1,"e":"Ans. is ''b'' i.e., Nose [Ref Dhingra 5th/e p. 150] \"Cartilage of the septum, also known as the quandragular cartilage because it is roughly quadrilateral in shape - separates the nostrils\".","pyqMatches":[{"year":"2016","no":924,"q":"Quadrungular septum is seen in which of the following?","o":["Larynx","Nose","Cranium","Palate"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1964, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 241, '{"id":1964,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":241,"q":"Nasal vestibule is","o":["Lateral part of nasal cavity","Antero - inferior part of nasal cavity","Supero - medial part of nose","Posterior aperture of nose"],"a":1,"e":"Ans. is ''b'' i.e., Antero - inferior part of nasal cavity[Ref Otolaryngology Basic Science & Clinical Review by Van De Water p. 462] Internal nose has following parts : Nasal cavity proper:- Internal nose is divided into right and left nasal cavities by nasal septum. Each nasal cavity communicates with the exterior through naris or nostrils and with nasopharynx through posterior nasal aperture or posterior nares or choana. Vestibule of nose :- Anterior and inferior part of the nasal cavity is lined by skin and is called vestibule of nose. It contains sebaceous glands, hair follicles and the hair called vibrissae.","pyqMatches":[{"year":"2016","no":925,"q":"Nasal vestibule is","o":["Lateral part of nasal cavity","Antero - inferior part of nasal cavity","Supero - medial part of nose","Posterior aperture of nose"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1965, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 242, '{"id":1965,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":242,"q":"Which of the following terms is used to describe the most prominent point of nasal tip?","o":["Pronasale","Alare","Nasion","Columella apex"],"a":0,"e":"Ans. is ''a'' i.e., Pronasale [Ref Handbook of anthropometry: Physical measures of human form in health and diseases, by Victor R. Preedy, p. 922] Pronasale : Most prominent point on the nasal tip. Alare : The point where the nasal blade (Ala nasi) extends the farthest out. Columella apex : The most anterior or the highest point on the columella crest at the apex of the nostril. Nasion : The point in the midline of both the anatomic nose and the nasoanterioral suture","pyqMatches":[{"year":"2016","no":926,"q":"Which of the following terms is used to describe the most prominent point of nasal tip?","o":["Pronasale","Alare","Nasion","Columella apex"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1966, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 243, '{"id":1966,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":243,"q":"Epistaxis after ligating external carotid artery is due to which vessel?","o":["Anterior ethmoidal artery","Superior labial artery","Sphenopalatine artery","Greater palatine artery"],"a":0,"e":"Ans. is ''a'' i.e., Anterior ethmoidal artery [Ref Dhingra 5thie p. 190] Since external carotid artery is ligated, the bleeding comes from branches of the internal carotid artery. Anterior ethmoidal artery, a branch of ophthalmic artery, which is a branch of internal carotid artery, is a constituent of the blood supply of the Little''s area of the nasal septum. Blood supply of nasal septum i) Internal carotid system Anterior ethmoidal artery Branches of ophthalmic artery Posterior ethmoidal artery ii) External Carotid System Sphenopalatine artery (branch of maxillary artery) gives nasopalatine and posterior medial nasal branches. Septal branch of greater palatine artery (Br. of maxillary artery). Septal branch of superior labial artery (Br. of facial artery)","pyqMatches":[{"year":"2016","no":927,"q":"Epistaxis after ligating external carotid artery is due to which vessel?","o":["Anterior ethmoidal artery","Superior labial artery","Sphenopalatine artery","Greater palatine artery"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1967, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 244, '{"id":1967,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":244,"q":"Killian''s polyp is a/an","o":["Antrochoanal polyp","Ethmoidal polyp","Frontal polyp","Maxillary polyp"],"a":0,"e":"Ans. is ''a'' i.e., Antrochoanal polyp [Ref Dhingra 5th/e p. 186; Essential otolaryngology 2\"1/e p. 660] Nasal polyps are of two types :? Antrochoanal :- This is usually solitary and arises from maxillary sinus and grows backward in the nose towards the choana (in contrast to ethmoidal polyps which tend to grow forward). The Antrochoanal polyp was first described by Gustain killians, therefore the name given to it was killian''s polyp. Ethmoidal :- These are multiple, bilateral and arise from etmoidal sinuses and tend to protrude forwards.","pyqMatches":[{"year":"2016","no":928,"q":"Killian''s polyp is a/an","o":["Antrochoanal polyp","Ethmoidal polyp","Frontal polyp","Maxillary polyp"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1968, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 245, '{"id":1968,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":245,"q":"Which of the following is the predisposing factor for ethmoidal carcinoma","o":["Smoking","Alcohol","Chronic infection","All of the above"],"a":0,"e":"Ans. is ''a'' i.e., Smoking [Ref Diseases of ENT by Bansal p. 363] Risk factors for squamous cell carcinoma of the paranasal sinuses :- Smoking , Mustard gas, Nickel and chromium plating industry, Isopropyl oil Leather industry , Wood dust exposure (adenocarcinoma of ethmoid), Polycyclic volatile hydrocarbons","pyqMatches":[{"year":"2016","no":929,"q":"Which of the following is the predisposing factor for ethmoidal carcinoma","o":["Smoking","Alcohol","Chronic infection","All of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1969, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 246, '{"id":1969,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":246,"q":"Most common sinus predisposed to malignancy which of the following?","o":["Ethmoid","Maxillary","Frontal","Sphenoid"],"a":1,"e":"Ans. is ''b'' i.e., Maxillary [Ref Dhingra 5thie p. 219] The majority of paranasal sinus malignancies (50-80%) originate within the maxillary sinus antrum. Sinuses and various conditions in which sinuses are affected in descending order of frequency","pyqMatches":[{"year":"2016","no":930,"q":"Most common sinus predisposed to malignancy which of the following?","o":["Ethmoid","Maxillary","Frontal","Sphenoid"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1970, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 247, '{"id":1970,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":247,"q":"Most common benign tumor of paranasal sinuses?","o":["Papilloma","Osteoma","Warts","Fibroma"],"a":1,"e":"Ans. is ''b'' i.e., Osteoma [Ref Logan Turner 8`h/e p. 89] Osteoma of the frontal sinus - Most common benign tumour arising in the nasal sinuses. The osteoma arises from the floor of the frontal sinus near the midline.","pyqMatches":[{"year":"2016","no":931,"q":"Most common benign tumor of paranasal sinuses?","o":["Papilloma","Osteoma","Warts","Fibroma"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1971, 'ENT', 'Ear', 'Moderate', 'ENT', 248, '{"id":1971,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":248,"q":"Treatment of nasal bone fracture includes all except","o":["Hematoma drainage","Topical vasoconstrictor","Closed reduction","Immediate rhinoplasty"],"a":3,"e":"Ans. is ''d'' i.e., Immediate rhinoplasty [Ref Scott Brown 7th/e p. 1612] Treatment of nasal injuries After ensuring patency of airway, adequate ventilation and overall stability of patient, attention to the nasal injuries should be given. Standard therapy is to perform closed reduction or open reducation between 3 and 7 days, and upto 2 weeks. This is because : Most of the patients (-70-80%) do not require any active treatment, as many do not have a nasal fracture and those that do, the fracture is not displaced. Soft tissue swelling can produce the misleading appearance of a deformity which disapears as the swelling subsides. Such patients require only reassurance & topical vasoconstrictors to alleviate congestion and obstructive symptoms. A re-examination should be carried out after 5 days, if there is uncertainity about the need for reduction. A large number of patients will have a preexisting nasal deformity caused by a previous incident. Patients that fall in this category are advised to consider a formal rhinoplasty when everything has settled down some months later. Immediate surgical intervention in acute phase is indicated : ? Severe deformity:- Septal hematoma causing nasal obstruction","pyqMatches":[{"year":"2016","no":934,"q":"Treatment of nasal bone fracture includes all except","o":["Hematoma drainage","Topical vasoconstrictor","Closed reduction","Immediate rhinoplasty"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1972, 'ENT', 'Ear', 'Moderate', 'ENT', 249, '{"id":1972,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":249,"q":"All of the following are true about parapharyngeal abscess except?","o":["Mastoid process divides the space into anterior and posterior","Also known as pharyngomaxillary space infection","Tonsil is pushed medially","Occurs after tooth extraction"],"a":0,"e":"Ans. is ''a'' i.e., Mastoid process divides the space into anterior and posterior [Ref Dhingra V/e p. 281] Styloid process and the muscles attached to it divide the parapharyngeal space into anterior and posterior compartments, not mastoid process.","pyqMatches":[{"year":"2016","no":935,"q":"All of the following are true about parapharyngeal abscess except?","o":["Mastoid process divides the space into anterior and posterior","Also known as pharyngomaxillary space infection","Tonsil is pushed medially","Occurs after tooth extraction"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1973, 'ENT', 'Throat & Larynx', 'Easy', 'ENT', 250, '{"id":1973,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Easy","source":"ENT","sourceNo":250,"q":"Lining epithelium of vocal cord is","o":["Stratified squamous epithelium","Non stratified squamous epithelium","Ciliated columnar epithelium","Non ciliated columnar epithelium"],"a":0,"e":"Ans. is ''a'' i.e., Stratified squamous epithelium [Ref Dhingra Vie p. 300] Vocal cords along with the upper part of the vestibule is the only part of laryngeal mucous membrane which is lined by epithelium of stratified squamous type. Elsewhere in the larynx epithelium of the mucous membrane is ciliated columnar type.","pyqMatches":[{"year":"2016","no":938,"q":"Lining epithelium of vocal cord is","o":["Stratified squamous epithelium","Non stratified squamous epithelium","Ciliated columnar epithelium","Non ciliated columnar epithelium"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1974, 'ENT', 'Throat & Larynx', 'Easy', 'ENT', 251, '{"id":1974,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Easy","source":"ENT","sourceNo":251,"q":"Which of the following sites of Ca larynx has the best prognosis?","o":["Glottic","Supraglottis","Subgottis","All have poor prognosis"],"a":0,"e":"Ans. is ''a'' i.e.,Glottic [Ref Dhingra 5th/e p. 326] Laryngeal carcinoma:- Cancer Prognosis Glottis Good SupraglottisPoor Subglottis Worst","pyqMatches":[{"year":"2016","no":940,"q":"Which of the following sites of Ca larynx has the best prognosis?","o":["Glottic","Supraglottis","Subgottis","All have poor prognosis"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1975, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 252, '{"id":1975,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":252,"q":"Laser used in tracheal neoplasm is","o":["Argon","KTP - 532","CO2","Nd - YAG"],"a":2,"e":"Ans. is ''c'' i.e., CO2 [Ref Dhingra 5th/e p. 315] Four types of laser are generally used in ENT surgery : Argon KTP - 532 (Potassium titanyl phosphate); Nd : YAG (Neodyminum - yttrium aluminium garnet); CO2 The carbon dioxide (CO) laser is the most common laser used for tracheal neoplasm.","pyqMatches":[{"year":"2016","no":941,"q":"Laser used in tracheal neoplasm is","o":["Argon","KTP - 532","CO2","Nd - YAG"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1976, 'ENT', 'Head & Neck', 'Easy', 'ENT', 253, '{"id":1976,"subject":"ENT","chapter":"Head & Neck","difficulty":"Easy","source":"ENT","sourceNo":253,"q":"Most common site of distant metastasis from Ca larynx","o":["Lymph nodes","Lung","Brain","Bone"],"a":1,"e":"Ans. is ''b'' i.e., Lung [Ref Clinical Otorhinolaryngology yd /el). 931] Distant metastasis is seen much less frequently. The most commonly affected sites for distant metastases are lungs (66%); bone (22%), liver (10%), mediastinum and bone marrow.","pyqMatches":[{"year":"2016","no":942,"q":"Most common site of distant metastasis from Ca larynx","o":["Lymph nodes","Lung","Brain","Bone"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1977, 'ENT', 'Throat & Larynx', 'Hard', 'ENT', 254, '{"id":1977,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Hard","source":"ENT","sourceNo":254,"q":"A patient presents with Ca larynx involving left false cord, left arytenoid and left aryepiglottic fold with bilateral mobile true cords. The treatment of choice in this patient is which of the following?","o":["Vertical hemilarygectomy","Horizontal partial hemilaryngectomy","Total laryngectomy","Radiotherapy followed by chemotherapy"],"a":1,"e":"Ans. is ''b'' i.e., Horizontal partial hemilaryngectomy [Ref Dhingra 4th/e p. 284] Involvement of unilateral false cord, aryepiglottic folds and arytenoids with mobile cord suggests supraglottic cancer in T2 stage (more than one subsites of supraglottis are involved).","pyqMatches":[{"year":"2016","no":944,"q":"A patient presents with Ca larynx involving left false cord, left arytenoid and left aryepiglottic fold with bilateral mobile true cords. The treatment of choice in this patient is which of the following?","o":["Vertical hemilarygectomy","Horizontal partial hemilaryngectomy","Total laryngectomy","Radiotherapy followed by chemotherapy"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1978, 'ENT', 'Throat & Larynx', 'Easy', 'ENT', 255, '{"id":1978,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Easy","source":"ENT","sourceNo":255,"q":"In recurrent laryngeal nerve palsy which muscle keeps vocal cord in median position?","o":["Posterior cricoarytenoid","Cricothyroid","Vocalis","All of the above"],"a":1,"e":"Ans. is ''b'' i.e., Cricothyroid [Ref Dhingra 5th/e p. 300] Recurrent laryngeal nerve paralysis Recurrent laryngeal nerve supplies : ?","pyqMatches":[{"year":"2016","no":945,"q":"In recurrent laryngeal nerve palsy which muscle keeps vocal cord in median position?","o":["Posterior cricoarytenoid","Cricothyroid","Vocalis","All of the above"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1979, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 256, '{"id":1979,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":256,"q":"Food particles mostly get obstructed in which part of esophagus -","o":["Cricopharyngeal sphincter","Crossing of arch of aorta","Cardiac end","None of the above"],"a":0,"e":"Ans. is ''a'' i.e, Cricopharyngeal sphincter [Ref: Dhingra 6thie p. 349] By far the commonest site is at or just below the cricopharyngeal sphincter. Flat objects like coins are held up at the sphincter while others are held in the upper oesophagus just below the sphincter due to poor peristalsis.","pyqMatches":[{"year":"2016","no":947,"q":"Food particles mostly get obstructed in which part of esophagus","o":["Cricopharyngeal sphincter","Crossing of arch of aorta","Cardiac end","None of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1980, 'ENT', 'Head & Neck', 'Moderate', 'ENT', 257, '{"id":1980,"subject":"ENT","chapter":"Head & Neck","difficulty":"Moderate","source":"ENT","sourceNo":257,"q":"True regarding traction diverticuli of esophagus is all except","o":["Does not empty completely","Triangular appearance","Contains all layers","Maintains elastic recoil"],"a":0,"e":"Ans. is ''a'' i.e., Does not empty completely [Ref The Esophagus by Richter p. 143] Type Layers Location Associated Shape Emptying Traction Diverticula True diverticula Lined by all layers Mid esophagus Scarring from TB or histoplasmosis involving perihilar or subcarinal lymph nodes Triangular or tented Tends to empty contents Pulsion Diverticula False diverticula Ususally only mucosal outpouchings Distal esophagus Associated with dysmotility Rounded outpouchings Do not empty completely Epiphrenic diverticula, Zenker''s diverticula","pyqMatches":[{"year":"2016","no":948,"q":"True regarding traction diverticuli of esophagus is all except","o":["Does not empty completely","Triangular appearance","Contains all layers","Maintains elastic recoil"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1981, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 258, '{"id":1981,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":258,"q":"Sluder''s neuralgia is also called as","o":["Anterior ethmoidal syndrome","Posterior ethmoidal syndrome","Trotter syndrome","Lermoyez syndrome"],"a":0,"e":"Ans. is ''a'' i.e., Anterior ethmoidal syndrome [Ref Dhingra 6th/e p. 450] Sluder''s neuralgia It is also called anterior ethmoidal syndrome. It is said to originate from the middle turbinate pressing on the nasal septum. It is characterized by pain around the bridge of the nose radiating into forehead. Treatment Anatomical correction relieves the pain.","pyqMatches":[{"year":"2016","no":951,"q":"Sluder''s neuralgia is also called as","o":["Anterior ethmoidal syndrome","Posterior ethmoidal syndrome","Trotter syndrome","Lermoyez syndrome"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1982, 'ENT', 'Head & Neck', 'Easy', 'ENT', 259, '{"id":1982,"subject":"ENT","chapter":"Head & Neck","difficulty":"Easy","source":"ENT","sourceNo":259,"q":"Most common tumor of oropharynx is","o":["Squamous cell carcinoma","Adenocarcinoma","Melanoma","Salivary gland tumors"],"a":0,"e":"Ans. is ''a'' i.e., Squamous cell carcinoma [Ref Abeloff''s Clinical Oncology 6\" le p. 1059] 90 – 95% of tumors in the oropharynx are squamous cell carcinomas, whereas others are minor salivary gland tumors, melanomas. The most common manifesting symptoms are a nontender neck mass, dysphagia, otalgia, or a \"hot potato\" voice.","pyqMatches":[{"year":"2016","no":954,"q":"Most common tumor of oropharynx is","o":["Squamous cell carcinoma","Adenocarcinoma","Melanoma","Salivary gland tumors"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1983, 'ENT', 'Head & Neck', 'Easy', 'ENT', 260, '{"id":1983,"subject":"ENT","chapter":"Head & Neck","difficulty":"Easy","source":"ENT","sourceNo":260,"q":"Investigation of choice for diagnosing submandibular gland duct stones is","o":["Ultrasound","X-ray of floor of mouth","Sialography","Sialoendoscopy"],"a":0,"e":"Ans. is ''a'' i.e., Ultrasound [Ref Churchill''s pocket book of surgery p. 133] Investigations for salivary gland stones Ultrasound is the investigation of choice – as it permits assessment of the gland, duct system and calculus which usually has an acoustic shadow. ''Floor of mouth'' radiographic view for submandibular calculi in Wharton''s duct where ultrasound findings are equivocal or unavailable. If no stone is seen, consider sialography. Sialoendoscopy is increasingly used in the diagnosis and treatment of salivary gland outflow obstructive conditions.","pyqMatches":[{"year":"2016","no":955,"q":"Investigation of choice for diagnosing submandibular gland duct stones is","o":["Ultrasound","X-ray of floor of mouth","Sialography","Sialoendoscopy"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1984, 'ENT', 'Ear', 'Hard', 'ENT', 261, '{"id":1984,"subject":"ENT","chapter":"Ear","difficulty":"Hard","source":"ENT","sourceNo":261,"q":"Deafness in a case of Paget''s disease is due to","o":["Retraction pockets","Otitis","Eight nerve involvement","Endolymphatic hydrops"],"a":2,"e":"Ans. is ''c'' i.e., Eight nerve involvement [Refer Neurology consult 5\"/e p. 866] Cranial nerve compression is the usual cause of deafness. Complications of Paget''s disease Following complications can occur in Paget''s disease : -","pyqMatches":[{"year":"2016","no":956,"q":"Deafness in a case of Paget''s disease is due to","o":["Retraction pockets","Otitis","Eight nerve involvement","Endolymphatic hydrops"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1985, 'ENT', 'Throat & Larynx', 'Easy', 'ENT', 262, '{"id":1985,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Easy","source":"ENT","sourceNo":262,"q":"Membrane incised during hemilaryngectomy is","o":["Thyrohyoid","Cricothyroid","Aryepiglottic","Infralaryngeal"],"a":1,"e":"Ans. is ''b'' i.e., Cricothyroid [Ref Dhingra ele p. 310] Indications and containdications Ideal for bulky lesions of the membranous true vocal cord Normal or slightly impaired vocal cord mobility No involvement of the supraglottis","pyqMatches":[{"year":"2016","no":957,"q":"Membrane incised during hemilaryngectomy is","o":["Thyrohyoid","Cricothyroid","Aryepiglottic","Infralaryngeal"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1986, 'ENT', 'Ear', 'Easy', 'ENT', 263, '{"id":1986,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":263,"q":"Callaural fistula is an abnormality of ?","o":["1\" branchial arch","Pt branchial cleft","2nd branchial arch","2nd branchial cleft"],"a":1,"e":"Ans. is ''b'' i.e., Pt branchial cleft Collaural fistula is a 1\" branchial cleft anomaly which arises from failure of fusion of the ventral part of the Pt cleft. Its upper part opens into floor of external auditary canal. Its lower part opens in the neck between angle of mandible and sternocleidomastoid muscle.","pyqMatches":[{"year":"2014","no":1090,"q":"Callaural fistula is an abnormality of ?","o":["1\" branchial arch","Pt branchial cleft","2nd branchial arch","2nd branchial cleft"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1987, 'ENT', 'Ear', 'Easy', 'ENT', 264, '{"id":1987,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":264,"q":"Acute suppurative otits media in children is most commonly caused by ?","o":["St. pneumoniae","S. epidermidis","S. aureus","Pseudomonas"],"a":0,"e":"Ans. is ''a'' i.e., St. pneumonia [Ref Dhingra 5thle p. 54] ASOM is especially common in infants and children. Most of the time ASOM usually follows respiratory tract infections (i.e., acute tonsillitis, common cold or influenza) and the infection travel up by the eustachian tube to the middle ear. The most common causative organism is streptococcus pneumoniae","pyqMatches":[{"year":"2014","no":1102,"q":"Acute suppurative otits media in children is most commonly caused by ?","o":["St. pneumoniae","S. epidermidis","S. aureus","Pseudomonas"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1988, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 265, '{"id":1988,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":265,"q":"Young''s operation is done for","o":["Allergic rhinitis","Atropic rhinitis","Vasomotor rhinitis","Idiopathic rhinitis"],"a":1,"e":"Ans. is ''b'' i.e., Atrophic rhinitis [Ref Dhingra 5th/e p. 171; Essential otolaryngology 2\"d/e p. 523] Surgical treatment of Atrophic rhinitis","pyqMatches":[{"year":"2014","no":1137,"q":"Young''s operation is done for","o":["Allergic rhinitis","Atropic rhinitis","Vasomotor rhinitis","Idiopathic rhinitis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1989, 'ENT', 'Ear', 'Moderate', 'ENT', 266, '{"id":1989,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":266,"q":"All of the following are are a part of medial wall of the middle ear except?","o":["Promontory","Fenestra vestibule","Pyramid","Subiculum"],"a":2,"e":"Ans. is ''c'' i.e.,Pyramid [Ref Dhingra S ave p. 6] Medial or inner or labyrinthic wall (paries labyrinthica) of middle ear It is formed by labyrinth and separates the middle ear cavity from internal ear. It has following features :- A bulge called as promontory formed by basal turn of cochlea. Fenestra vestibuli (oval window) lies posterosuperior (behind and above) to the promontory and opens into scala vestibuli. It is occupied by foot plate of stapes fixed by annular ligament. Its, size on average is 3.25 mm long & 1.75 mm wide. Fenestra cochleae (round window) lies posteroinferior to the promontory and opens into scala tympani of cochlea. It is closed by secondary tympanic membrane. The round window is closest to ampulla of posterior semicircular canal. Round window is a triangular opening. Its diameter is between 1.8 to 2.3 mm.","pyqMatches":[{"year":"2015","no":929,"q":"All of the following are are a part of medial wall of the middle ear except?","o":["Promontory","Fenestra vestibule","Pyramid","Subiculum"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1990, 'ENT', 'Ear', 'Easy', 'ENT', 267, '{"id":1990,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":267,"q":"What is the intensity in decibel of normal conversation in humans?","o":["30dB","60dB","90dB","150dB"],"a":1,"e":"Ans. is ''b'' i.e., 60dB [Ref Dhingra 5thle p. 23] Intensity is the strength of sound which determines its loudness. It is usually measured in decibels (dB). Following are intensities when a person is at a distance of one meter from sound source. Whisper 30 dB Normal conversation60 dB Shout 90 dB Discomfort of ear 120 dB Pain in ear 130 dB","pyqMatches":[{"year":"2015","no":931,"q":"What is the intensity in decibel of normal conversation in humans?","o":["30dB","60dB","90dB","150dB"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1991, 'ENT', 'Ear', 'Easy', 'ENT', 268, '{"id":1991,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":268,"q":"What is the role of Sodium Fluoride in otosclerosis?","o":["It restores the electrolyte equilibrium","It hastens recovery of the Overstimulated Cochlea","It quickens the maturity of the active focus and reduces osteoclastic resorption","It repolarizes the cochlear cells"],"a":2,"e":"Ans. is ''c'' i.e., It quickens the maturity of the active focus and reduces osteoclastic resorption [Ref Current Diagnosis and treatment in Otolaryngology 2nd/e p. 678; Otosclerosis and Stapedectomy: Diagnosis, Management, and Complication by Glasscock (7hieme) 1st (2004) p. 61, 62] Mechanism of action of Sodium fluoride in otosclerosis","pyqMatches":[{"year":"2015","no":935,"q":"What is the role of Sodium Fluoride in otosclerosis?","o":["It restores the electrolyte equilibrium","It hastens recovery of the Overstimulated Cochlea","It quickens the maturity of the active focus and reduces osteoclastic resorption","It repolarizes the cochlear cells"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1992, 'ENT', 'Ear', 'Moderate', 'ENT', 269, '{"id":1992,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":269,"q":"Chemical labyrinthectomy by transtympanic route is done in Meniere''s disease using which drug?","o":["Amikacin","Gentamicin","Amoxycillin","Cyclosporine"],"a":1,"e":"Ans. is ''b'' i.e., Gentamicin [Ref Levine SC, Haberkamp TJ. Labyrinthectomy to correct vertigo Operative techniques in otolaryngology - Head & neck surgery.","pyqMatches":[{"year":"2015","no":936,"q":"Chemical labyrinthectomy by transtympanic route is done in Meniere''s disease using which drug?","o":["Amikacin","Gentamicin","Amoxycillin","Cyclosporine"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1993, 'ENT', 'Audiology', 'Moderate', 'ENT', 270, '{"id":1993,"subject":"ENT","chapter":"Audiology","difficulty":"Moderate","source":"ENT","sourceNo":270,"q":"Which of the following tests is not used to differentiate between cochlear and retrocochlear hearing loss?","o":["SISI TEST","Evoked response audiometry","Threshold tone decay test","Recruitment"],"a":2,"e":"Ans. is ''c'' i.e., Threshold tone decay test [Ref Dhingra 5th/e p. 31; zr/e p. 28]","pyqMatches":[{"year":"2015","no":937,"q":"Which of the following tests is not used to differentiate between cochlear and retrocochlear hearing loss?","o":["SISI TEST","Evoked response audiometry","Threshold tone decay test","Recruitment"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1994, 'ENT', 'Ear', 'Easy', 'ENT', 271, '{"id":1994,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":271,"q":"Where is the auditory cortex located inside the brain?","o":["Superior temporal gyrus","Inferior temporal gyrus","Area 3,1,2","Cingulate gyrus"],"a":0,"e":"Ans. is ''a'' i.e., Superior temporal gyrus [Ref Pickles, James 0. (2012). An Introduction to the Physiology of Hearing (4th ed.). Bingley, UK: Emerald Group Publishing Limited, pp. 215-217.] Primary Auditory Cortex is located bilaterally, roughly at the upper sides of the temporal lobes - in humans on the superior temporal plane, within the lateral fissure and comprising parts of Heschl''s gyrus and the superior temporal gyrus, including planum polare and planum temporale (roughly Brodmann areas 41, 42, and partially 22).","pyqMatches":[{"year":"2015","no":981,"q":"Where is the auditory cortex located inside the brain?","o":["Superior temporal gyrus","Inferior temporal gyrus","Area 3,1,2","Cingulate gyrus"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1995, 'ENT', 'Ear', 'Easy', 'ENT', 272, '{"id":1995,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":272,"q":"When does the rudimentary cochlea develop in the fetus?","o":["First week","4th to 8th week","8th to 12th week","16 to 20th week"],"a":1,"e":"Ans. is ''b'' i.e., 4th to 8th week [Ref Chap 172-Teview of medical embryology-Ben Pasky] Development of Inner ear After implantation, around the second to third week the developing embryo consists of three layers: endoderm, mesoderm andectoderm. The first part of the ear to develop is the inner ear,which begins to form from the ectoderm around the 22nd day of the embryo''s development. Specifically, the inner ear derives from two thickenings called otic placodes on either side of the head. Each otic placode recedes below the ectoderm, forms an otic pit and then an otic vesicle. This entire mass will eventually become surrounded by mesenchyme to form the bony labyrinth. Around the 33''d day of development, the vesicles begin to differentiate. Closer to the back of the embryo, they form what will become the utricle and semicircular canals. Closer to the front of the embryo, the vesicles differentiate into a rudimentary saccule, which will eventually become the saccule and cochlea. Part of the saccule will eventually give rise and connect to the cochlear duct. This duct appears approximately during the sixth week and connects to the saccule through the ductus reuniens.","pyqMatches":[{"year":"2015","no":938,"q":"When does the rudimentary cochlea develop in the fetus?","o":["First week","4th to 8th week","8th to 12th week","16 to 20th week"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1996, 'ENT', 'Ear', 'Easy', 'ENT', 273, '{"id":1996,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":273,"q":"The main muscle affected in congenital muscular torticollis is?","o":["Sternocleidomastoid","Trapezius","Scalenus Anticus","Omohyoid"],"a":0,"e":"Ans. is ''a'' i.e., Sternocleidomastoid [Ref: Cooperman, Daniel R. (1997). Karmel-Ross, Karen, ed. \"The Differential Diag​nosis of Torticollis in Children\". Physical & Occupational Therapy in Pediatrics. 17 (2): 1-11] The cause of congenital muscular torticollis is unclear. Birth trauma or intrauterine malposition is considered to be the cause of damage to the sternocleidomastoid muscle in the neck. Other alterations to the muscle tissue arise from repetitive microtrauma within the womb or a sudden change in the calcium concentration in the body which causes a prolonged period of muscle contraction.","pyqMatches":[{"year":"2015","no":980,"q":"The main muscle affected in congenital muscular torticollis is?","o":["Sternocleidomastoid","Trapezius","Scalenus Anticus","Omohyoid"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1997, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 274, '{"id":1997,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":274,"q":"Miracle fruit is used to change the taste from?","o":["Sour to Bitter","Sour to Sweet","Bitter to sweet","Salty to sweet"],"a":1,"e":"Ans. is ''b'' i.e., Sour to Sweet [Ref Peter Hanelt, ed. (2001).Mansfeld''s encyclopedia of agricultural and horticultural crops 2. Springer. p. 1660. ISBN 3-540-41017-1.] Miracle Fruit contains a glycoprotein called miraculin, which binds to the tongue''s taste buds when the fruit is consumed. Miraculin acts as a sweetness inducer when it comes in contact with acids, causing sour foods to taste sweet, temporarily.","pyqMatches":[{"year":"2015","no":979,"q":"Miracle fruit is used to change the taste from?","o":["Sour to Bitter","Sour to Sweet","Bitter to sweet","Salty to sweet"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1998, 'ENT', 'Nose & Paranasal Sinuses', 'Moderate', 'ENT', 275, '{"id":1998,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Moderate","source":"ENT","sourceNo":275,"q":"All of the following are complications of maxillary sinus lavage and insufflation except?","o":["Air embolism","Orbital injury","Epistaxis","Facial nerve injury"],"a":3,"e":"Ans. is ''d'' i.e., Facial nerve injury [Ref Schlemmer KD, Naidoo SK. Complicated sinusitis in a developing country, a retrospective review. Int J Pediatr Otorhinolaryngol. 2013 May 17] Complication of Maxillary sinus lavage and insufflation Complications of nonendoscopic drainage procedures can be minor or severe. The most common complication is failure to enter the sinus because of improper positioning of the trocar, incomplete penetration of the sinus mucosa, or the presence of a hypoplastic antrum. Epistaxis may occur because of laceration of the nasal mucosa or preexisting coagulopathies necessitating packing. Severe complications include orbital injury, air embolism, and death secondary to injection of air into the sinus.","pyqMatches":[{"year":"2015","no":978,"q":"All of the following are complications of maxillary sinus lavage and insufflation except?","o":["Air embolism","Orbital injury","Epistaxis","Facial nerve injury"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (1999, 'ENT', 'Throat & Larynx', 'Moderate', 'ENT', 276, '{"id":1999,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Moderate","source":"ENT","sourceNo":276,"q":"All of the following are removed in vertical hemilaryngectomy except?","o":["Half Glottis","Half Supraglottis","Half tongue","Half Subglottis"],"a":2,"e":"Ans. is ''c'' i.e., Half tongue [Ref Dhingra 4th/e p. 284; http://128.255.52.245/oto/Beta/database/contents] Vertical hemilaryngectomy means excision of one half of the larynx on one side, i.e., vertical half is removed which include vertical half of supraglottis, glottis and subglottis. Horizontal hemilaryngectomy is the excision of supraglottis only, also known as supraglottic laryngectomy.","pyqMatches":[{"year":"2015","no":977,"q":"All of the following are removed in vertical hemilaryngectomy except?","o":["Half Glottis","Half Supraglottis","Half tongue","Half Subglottis"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2000, 'ENT', 'Ear', 'Easy', 'ENT', 277, '{"id":2000,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":277,"q":"Submucosal resection is the treatment of choice of?","o":["DNS in adults","DNS in children","Sluder''s Neuralgia","Nasal polyp"],"a":0,"e":"Ans. is ''a'' i.e., DNS in adults [Ref Dhingra 5th /e p. 423] Submucous resection (SMR) is a surgical procedure to correct the deformity of nasal septum. The principle of this procedure is to remove deviated cartilage and bone from beneath the mucosal lining of nasal septum, leaving a corrected septum largely composed of scar tissue. Submucous resection is not advocated in children upto 17 years of age as it may interfere with development of the facial bones.","pyqMatches":[{"year":"2015","no":976,"q":"Submucosal resection is the treatment of choice of?","o":["DNS in adults","DNS in children","Sluder''s Neuralgia","Nasal polyp"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2001, 'ENT', 'Ear', 'Easy', 'ENT', 278, '{"id":2001,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":278,"q":"Which perforation of the tympanic membrane is most commonly seen with tubotympanic CSOM?","o":["Central","Anterosuperior","Posterosuperior","Posteroinferior"],"a":0,"e":"Ans. is ''a'' i.e., Central [Ref Dhingra 5thle p. 77; Pediatric otolaryngology 2\"/e p. 478] Tubotympanic CSOM It is also known as safe ear as it does not cause any serious complications Infection is is limited to antero-inferior part of middle ear cleft (eustachain tube & mesotympanum) and is associated with central perforation in pars tensa of tympanic membrane.","pyqMatches":[{"year":"2015","no":941,"q":"Which perforation of the tympanic membrane is most commonly seen with tubotympanic CSOM?","o":["Central","Anterosuperior","Posterosuperior","Posteroinferior"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2002, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 279, '{"id":2002,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":279,"q":"Caldwell Luc Surgery has its approach to the maxillary antrum through ?","o":["Gingivolabial sulcus","Inferior orbital rim","Nasal septum","Cribriform plate"],"a":0,"e":"Ans. is ''a'' i.e.,Gingivolabial sulcus [Ref Dhingra 5thIe p. 422]","pyqMatches":[{"year":"2015","no":975,"q":"Caldwell Luc Surgery has its approach to the maxillary antrum through ?","o":["Gingivolabial sulcus","Inferior orbital rim","Nasal septum","Cribriform plate"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2003, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 280, '{"id":2003,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":280,"q":"In Caldwell Luc operation, the approach is through the?","o":["Sublabial Approach leading to opening of mandibular antrum","Through the sphenopalatine recess","Opening of maxillary antrum through gingivolabial approach","Superior meatus"],"a":2,"e":"Ans. is ''c'' i.e., Opening of maxillary antrum through gingivolabial approach [Ref Dhingra Stile p. 422] Caldwell-Luc operation is a process of opening the maxillary antrum through canine fossa by sublabial approach and dealing with the pathology inside the antrum.In this surgery, antrum is reached through a incision in gingivolabial sulcus (from lateral incisor to 2\"d molar) and then opening of antrum in this area.","pyqMatches":[{"year":"2015","no":974,"q":"In Caldwell Luc operation, the approach is through the?","o":["Sublabial Approach leading to opening of mandibular antrum","Through the sphenopalatine recess","Opening of maxillary antrum through gingivolabial approach","Superior meatus"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2004, 'ENT', 'Head & Neck', 'Moderate', 'ENT', 281, '{"id":2004,"subject":"ENT","chapter":"Head & Neck","difficulty":"Moderate","source":"ENT","sourceNo":281,"q":"All of the following are indications for tracheostomy except ?","o":["Coma after head injury","Maxillofacial injury","Bilateral abductor palsy","Superior laryngeal nerve palsy"],"a":3,"e":"Ans. is ''d'' i.e., Superior laryngeal nerve palsy [Ref Ajay Yadav zithie p. 215; Dhingra 5thie p. 337] Tracheostomy A tracheostomy is a surgical procedure to create an opening through the neck into the anterior wall of trachea. A tube is usually placed through this opening to provide an airway and to remove secretions from the lungs. The tube is called tracheostomy tube.","pyqMatches":[{"year":"2015","no":973,"q":"All of the following are indications for tracheostomy except ?","o":["Coma after head injury","Maxillofacial injury","Bilateral abductor palsy","Superior laryngeal nerve palsy"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2005, 'ENT', 'Ear', 'Easy', 'ENT', 282, '{"id":2005,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":282,"q":"Most common cause of otitis externa is?","o":["Fungal infection","Bacterial infection","Seborrheic disease","Herpes Zoster"],"a":1,"e":"Ans. is ''b'' i.e., Bacterial infection [Ref Clinical ENT 5th/e p. 223] Most common cause of otitis externa is bacterial infection. Two most common causative bacteria are staphylococcus aureus and pseudomonas","pyqMatches":[{"year":"2015","no":942,"q":"Most common cause of otitis externa is?","o":["Fungal infection","Bacterial infection","Seborrheic disease","Herpes Zoster"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2006, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 283, '{"id":2006,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":283,"q":"Which is the narrowest portion of the esophagus?","o":["At the cricopharyngeal sphincter","At the crossing of the left main bronchus","At the level of the aortic arch","At the diagphragmatic aperture"],"a":0,"e":"Ans. is ''a'' i.e., At the cricopharyngeal sphincter [Gray H. Chapter 35: Mediastinum. Standring S, ed. Gray''s Anatomy: The Anatomical Basis of Clinical Practice. 40`Ve New York, NY: Churchill Livingstone Elsevier; 2008. 939-57.] Cricopharyngeal sphincter is the narrowest portion of esophagus","pyqMatches":[{"year":"2015","no":972,"q":"Which is the narrowest portion of the esophagus?","o":["At the cricopharyngeal sphincter","At the crossing of the left main bronchus","At the level of the aortic arch","At the diagphragmatic aperture"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2007, 'ENT', 'Miscellaneous', 'Moderate', 'ENT', 284, '{"id":2007,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Moderate","source":"ENT","sourceNo":284,"q":"Which of the following is not a premalignant condition oral cancer?","o":["Leukoplakia","Erythroplakia","Oral submucous fibrosis","Systemic Sclerosis"],"a":3,"e":"Ans. is ''d'' i.e., Systemic Sclerosis [ Ref Devita 7\"Ve p. 982; Bailey & love 25`Ve p. 735] Lesions with increased risk of malignancy in oral cancer Premalignant condition :- Leukoplakia, Erythroplakia, Speckled erythroplakia, chronic hyperplastic candidiasis. Conditions increasing risk :- Oral submucous fibrosis, syphilitic glossitis, sideropenic dysphagia (Peterson Kelly syndrome). Risk is doubtful : - Oral lichen planus, DLE, Dyskeratosis congenita.","pyqMatches":[{"year":"2015","no":971,"q":"Which of the following is not a premalignant condition oral cancer?","o":["Leukoplakia","Erythroplakia","Oral submucous fibrosis","Systemic Sclerosis"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2008, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 285, '{"id":2008,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":285,"q":"Which of the following is a cause of objective tinnitus?","o":["Impacted Wax","Carotid artery aneurysm","Meniere''s disease","Ototoxic drugs"],"a":1,"e":"Ans. is ''b'' i.e., Carotid artery aneurysm [Refi Dhingra Sth/e p. 145; Scott Brown''s 7th/e Vol-3 p. 4029-4030;Tuli p. 125-126]","pyqMatches":[{"year":"2015","no":943,"q":"Which of the following is a cause of objective tinnitus?","o":["Impacted Wax","Carotid artery aneurysm","Meniere''s disease","Ototoxic drugs"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2009, 'ENT', 'Throat & Larynx', 'Moderate', 'ENT', 286, '{"id":2009,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Moderate","source":"ENT","sourceNo":286,"q":"Which of the following cancers do not present with cervical lymphnode involvement?","o":["Glottic Cancer","Subglottic Cancer","Papillary thyroid cancer","Oral cancer"],"a":0,"e":"Ans. is ''a'' i.e., Glottic Cancer [Ref Dhingra 5th le p. 327; 41'' p. 283] True vocal cords are devoid of lymphatic, hence less chance of cervical nodal metastasis","pyqMatches":[{"year":"2015","no":970,"q":"Which of the following cancers do not present with cervical lymphnode involvement?","o":["Glottic Cancer","Subglottic Cancer","Papillary thyroid cancer","Oral cancer"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2010, 'ENT', 'Ear', 'Easy', 'ENT', 287, '{"id":2010,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":287,"q":"Pulsatile tinnitus is a feature of ?","o":["Glomus tumour","acoustic neuroma","malignant otits externa","meneire''s disease"],"a":0,"e":"Ans. is ''a'' i.e., Glomus tumour [Ref Logan Turner 10th/e p. 214] The earliest symptoms of glomus tumour is pulsatile tinnitus (earliest) and hearing loss. Hearing loss is conductive and slowly progressive. These are followed by blood stained otorrhoea and earache.","pyqMatches":[{"year":"2015","no":944,"q":"Pulsatile tinnitus is a feature of ?","o":["Glomus tumour","acoustic neuroma","malignant otits externa","meneire''s disease"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2011, 'ENT', 'Ear', 'Easy', 'ENT', 288, '{"id":2011,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":288,"q":"Histelberger''s sign is seen in?","o":["Acoustic neurom","Glomus Tumour","Nasal angiofibroma","Acute suppurative otitis media"],"a":0,"e":"Ans. is ''a'' i.e., Acoustic neurom [Ref Acta Otorhinolaryngol Belg. 1987;41(1):40-8.The Hitselberger sign as a perception phenomenon. Benz B, Baumgarten D.] Hitselberger''s sign In Acoustic neuroma - loss of sensation in the postero-superior part of external auditory meatus supplied by Arnold''s nerve (branch of Vagus nerve to ear).","pyqMatches":[{"year":"2015","no":945,"q":"Histelberger''s sign is seen in?","o":["Acoustic neurom","Glomus Tumour","Nasal angiofibroma","Acute suppurative otitis media"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2012, 'ENT', 'Throat & Larynx', 'Moderate', 'ENT', 289, '{"id":2012,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Moderate","source":"ENT","sourceNo":289,"q":"All of the following are true about Spasmoidic Dysphonia except ?","o":["It may be of adductor or abductor type","Abductor type is characterized by Whispering quality of voice","Adductor type is characterized by Breathlessness","It is focal Laryngeal dystonia"],"a":2,"e":"Ans. is ''c'' i.e., Adductor type is characterized by Breathlessness [RefiSulica L (December 2004). \"Contemporary man​agement of spasmodic dysphonia\". Current Opinion in Otolaryngology & Head and Neck Surgery. 12 (6)]","pyqMatches":[{"year":"2015","no":969,"q":"All of the following are true about Spasmoidic Dysphonia except ?","o":["It may be of adductor or abductor type","Abductor type is characterized by Whispering quality of voice","Adductor type is characterized by Breathlessness","It is focal Laryngeal dystonia"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2013, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 290, '{"id":2013,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":290,"q":"Ethmoidal infundibulum lies between ?","o":["Bulla ethmoidalis and uncinate process of ethmoid","Middle and inferior turbinate","Hiatus semilunaris and Inferior meatus","Wing of sphenoid and maxillary antrum"],"a":0,"e":"Ans. is ''a'' i.e., Bulla ethmoidalis and uncinate process of ethmoid The hiatus semilunaris is bounded inferiorly by the sharp concave margin of the uncinate process of the ethmoid bone, and leads into a curved channel, the infundibulum, bounded above by the bulla ethmoidalis and below by the lateral surface of the uncinate process of the ethmoid.","pyqMatches":[{"year":"2015","no":946,"q":"Ethmoidal infundibulum lies between ?","o":["Bulla ethmoidalis and uncinate process of ethmoid","Middle and inferior turbinate","Hiatus semilunaris and Inferior meatus","Wing of sphenoid and maxillary antrum"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2014, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 291, '{"id":2014,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":291,"q":"What lies between the middle and inferior turbinate?","o":["Middle meatus","Superior meatus","Hiatus semmilunaris","Inferior meatus"],"a":0,"e":"Ans. is ''a'' i.e., Middle meatus [Ref Scott Brown 7''Ve vol 2 p. 1329] Superior meatus → * Below superior turbinate (between superior and middle turbinates) Middle meatus → Below middle turbinate (between middle and inferior turbinates) Inferior meatus → Below inferior turbinate.","pyqMatches":[{"year":"2015","no":947,"q":"What lies between the middle and inferior turbinate?","o":["Middle meatus","Superior meatus","Hiatus semmilunaris","Inferior meatus"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2015, 'ENT', 'Miscellaneous', 'Moderate', 'ENT', 292, '{"id":2015,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Moderate","source":"ENT","sourceNo":292,"q":"All of the following are extrinsic laryngeal membranes except?","o":["Quadrangular membrane","Hyoepiglottic ligament","Cricotracheal membrane","Thyrohyoid membrane"],"a":0,"e":"Ans. is ''a'' i.e., Quadrangular membrane [Ref Merati AL, Bielamowicz SA. Textbook of Laryngology. San Diego: Plural Publishing Inc 2006.] Quadrangular membrane","pyqMatches":[{"year":"2015","no":968,"q":"All of the following are extrinsic laryngeal membranes except?","o":["Quadrangular membrane","Hyoepiglottic ligament","Cricotracheal membrane","Thyrohyoid membrane"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2016, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 293, '{"id":2016,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":293,"q":"The narrowest part of the nasal cavity is ?","o":["Internal nasal valve","Antrochoanal region","1st nasal turbinate","Region of inferior concha"],"a":0,"e":"Ans. is ''a'' i.e., Internal nasal valve [Ref Jafek BW. Anatomy and physiology of the nose. Jafek BW, Stark AK, eds. ENT Secrets. Philadelphia, Pa: Hanley & Belfus; 1996. 77-83.] The internal nasal valve involves the area bounded by upper lateral cartilage, septum, nasal floor, and anterior head of the inferior turbinate. This makes up the narrowest portion of the nasal airway","pyqMatches":[{"year":"2015","no":948,"q":"The narrowest part of the nasal cavity is ?","o":["Internal nasal valve","Antrochoanal region","1st nasal turbinate","Region of inferior concha"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2017, 'ENT', 'Throat & Larynx', 'Easy', 'ENT', 294, '{"id":2017,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Easy","source":"ENT","sourceNo":294,"q":"Anterior tonsillar pillar is formed by?","o":["Palatopharyngeal fold","Palatoglossal fold","Pterygopalatine arch","Valleculae"],"a":1,"e":"Ans. is ''b'' i.e., Palatoglossal fold Anterior tonsillar pillar- Palatoglossal fold Posterior tonsillar pillar- Palatopharyngeal fold","pyqMatches":[{"year":"2015","no":966,"q":"Anterior tonsillar pillar is formed by?","o":["Palatopharyngeal fold","Palatoglossal fold","Pterygopalatine arch","Valleculae"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2018, 'ENT', 'Head & Neck', 'Easy', 'ENT', 295, '{"id":2018,"subject":"ENT","chapter":"Head & Neck","difficulty":"Easy","source":"ENT","sourceNo":295,"q":"One of the following is true regarding Zenker diverticulum ?","o":["It is a pulsion diverticulum","It projects anteriorly","Commonly seen in young males","It is between superior and middle constrictor"],"a":0,"e":"Ans. is ''A'' i.e., It is a pulsion diverticulum Hypopharyngeal diverticulum or Zenker''s diverticulum or pharyngeal pouch It is a pulsion diverticulum where pharyngeal mucosa herniates through the Killian''s dehiscence, a weak area between two parts of the inferior constrictor. It is the most common esophageal diverticulum. The diverticula arise posteriorly in the midline of neck. The mouth of the diverticula is in the midline but projects laterally (usually left laterally ) Zenker''s diverticula are rarely seen below 30 yrs of age, most patients are over 50.","pyqMatches":[{"year":"2015","no":967,"q":"One of the following is true regarding Zenker diverticulum ?","o":["It is a pulsion diverticulum","It projects anteriorly","Commonly seen in young males","It is between superior and middle constrictor"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2019, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 296, '{"id":2019,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":296,"q":"Narrowest part of the nasal cavity is ?","o":["Vestibule","Choanae","Inferior turbinate","Middle turbinate"],"a":2,"e":"Ans. is ''c'' i.e., Inferior turbinate [Ref Heidari Z, Mahmoudzadeh- Sagheb H, Khammar T, Khammar M (May 2009). \"Anthropometric measurements of the external nose in 18-25- year-old Sistani and Baluch aborigine women in the southeast of Iran\". Folia Morphol. (Warsz) 68 (2): 88-92] The internal nasal valve comprises the area bounded by the upper lateral-cartilage, the septum, the nasal floor, and the anterior head of the inferior turbinate. In the narrow (leptorrhine) nose, this is the narrowest portion of the nasal airway.","pyqMatches":[{"year":"2015","no":949,"q":"Narrowest part of the nasal cavity is ?","o":["Vestibule","Choanae","Inferior turbinate","Middle turbinate"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2020, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 297, '{"id":2020,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":297,"q":"Saddle nose deformity is seen in?","o":["Primary Syphilis","Secondary syphilis","Tertiary syphilis","Lupus Vulgaris"],"a":2,"e":"Ans. is ''c'' i.e., Tertiary syphilis [Ref Dhingra 5th/e p. 184] Syphilis of nose occurs as :-","pyqMatches":[{"year":"2015","no":950,"q":"Saddle nose deformity is seen in?","o":["Primary Syphilis","Secondary syphilis","Tertiary syphilis","Lupus Vulgaris"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2021, 'ENT', 'Nose & Paranasal Sinuses', 'Moderate', 'ENT', 298, '{"id":2021,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Moderate","source":"ENT","sourceNo":298,"q":"All of the following are true about vasomotor rhinitis except ?","o":["It is allergic","It is due to parasympathetic overactivity","Resistant cases may need cryotherapy","It may lead to hypertrophic rhinitis"],"a":0,"e":"Ans. is ''a'' It is allergic [Ref Scott''s Brown 7thie p. 2122] Vasomotor rhinitis Vasomotor rhinitis is a nonallergic condition that involves a constant runny nose, sneezing and nasal congestion, i.e., the nose is stuffy or runny for reasons other than allergies and infections. The exact etiology is unknown, but triggers include emotions, odors, poor air quality, spicy foods, and medication side effects.","pyqMatches":[{"year":"2015","no":951,"q":"All of the following are true about vasomotor rhinitis except ?","o":["It is allergic","It is due to parasympathetic overactivity","Resistant cases may need cryotherapy","It may lead to hypertrophic rhinitis"],"a":0,"source":"NEET_2015_Paper.pdf"},{"year":"2015","no":952,"q":"All of the following are true about vasomotor rhinitis except?","o":["It is a nonallergic condition","it is due to parasympathetic overactivity","It may cause paroxysmal episodes of sneezing","It is an infective condition"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2022, 'ENT', 'Miscellaneous', 'Moderate', 'ENT', 299, '{"id":2022,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Moderate","source":"ENT","sourceNo":299,"q":"All of the following are true about vasomotor rhinitis except?","o":["It is a nonallergic condition","it is due to parasympathetic overactivity","It may cause paroxysmal episodes of sneezing","It is an infective condition"],"a":3,"e":"Ans. is ''d'' i.e., It is an infective condition [Ref Dhingra 5th/e p. 170]","pyqMatches":[{"year":"2015","no":951,"q":"All of the following are true about vasomotor rhinitis except ?","o":["It is allergic","It is due to parasympathetic overactivity","Resistant cases may need cryotherapy","It may lead to hypertrophic rhinitis"],"a":0,"source":"NEET_2015_Paper.pdf"},{"year":"2015","no":952,"q":"All of the following are true about vasomotor rhinitis except?","o":["It is a nonallergic condition","it is due to parasympathetic overactivity","It may cause paroxysmal episodes of sneezing","It is an infective condition"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2023, 'ENT', 'Nose & Paranasal Sinuses', 'Hard', 'ENT', 300, '{"id":2023,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Hard","source":"ENT","sourceNo":300,"q":"In evaluation of a case of immotile nasal cilia, which of the following investigations should prove useful?","o":["Rhinogram","Xray nasal and paranasal sinuses","Sweat sodium levels","Nitric oxide test"],"a":3,"e":"Ans. is ''d'' i.e., Nitric oxide test [Ref Leigh MW, Pittman JE, Carson JL, Ferkol TW, Dell SD, Davis SD. Clinical and genetic aspects of primary ciliary dyskinesia/Kartagener syndrome. Genet Med. 2009 Jul. 11(7):473-87] Screening tests for immotile cilia syndrome Nitric oxide : Measuring exhaled nasal nitric oxide, which is mostly reduced in primary ciliary dyskinesia, is a good screening test for immotile-cilia syndrome with a good negative predictive value. Studies have demonstrated a relationship between nasal nitric oxide levels, nasal oxide synthase mRNA expression, and ciliary beat frequency. There is also a significant inverse correlation between the degree of aplasia and/or hypoplasia of the paranasal sinus and nasal nitric oxide values in primary ciliary dyskinesia patients.","pyqMatches":[{"year":"2015","no":953,"q":"In evaluation of a case of immotile nasal cilia, which of the following investigations should prove useful?","o":["Rhinogram","Xray nasal and paranasal sinuses","Sweat sodium levels","Nitric oxide test"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2024, 'ENT', 'Miscellaneous', 'Moderate', 'ENT', 301, '{"id":2024,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Moderate","source":"ENT","sourceNo":301,"q":"All of the following are features of ethmoidal polyp except ?","o":["Common in adults","Commonly Singular","Commonly bilateral","Is usually allergic"],"a":1,"e":"Ans. is `b'' i.e., Commonly Singular [Ref Dhingra 5thle p. 187; Tuli 1\"/e p. 173] Antrochoanal polyp grows backward (posteriorly), therefore, it may not be visible on anterior rhinoscopy, while posterior rhinoscopy shows smooth, greyish white, spherical mass in choana. On the other hand, ethmoidal polyps grow anteriorly. Therefore, they are best seen on anterior rhinoscopy and may not be seen on posterior rhinoscopy.","pyqMatches":[{"year":"2015","no":954,"q":"All of the following are features of ethmoidal polyp except ?","o":["Common in adults","Commonly Singular","Commonly bilateral","Is usually allergic"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2025, 'ENT', 'Nose & Paranasal Sinuses', 'Moderate', 'ENT', 302, '{"id":2025,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Moderate","source":"ENT","sourceNo":302,"q":"All of the following are features of enlarged adenoids except?","o":["Otitis media","Nasal obstruction","Failure to thrive of child","Esophagitis"],"a":3,"e":"Ans. is ''d'' i.e., Esophagitis [Ref Dhingra Vie p. 254] Clinical features of enlarged adenoids Enlarged and infected adenoids may cause nasal, aural (ear), and general symptoms. 1) Nasal symptoms Nasal obstruction is the commonest symptom. This result in mouth breathing. As the respiration and feeding cannot take place simultaneously, child fails to thrive. Other symptoms are nasal discharge (wet bubbly nose), sinusitis, epistaxis and toneless voice with loss of nasal quality (Rhinololia clausa). 2) Aural symptoms Tubal obstruction Otitis media :- Recurrent acute otitis media, CSOM, serous otitis media 3) General symptoms Adenoidfacies: Elong at edface with dullex pression,open mouth,prominent & crow dedup per teeth, hit chedup perlip, pinched in appearance of nose and high arched palate. Pulmonary hypertension, aprosexia (lack of concentration).","pyqMatches":[{"year":"2015","no":965,"q":"All of the following are features of enlarged adenoids except?","o":["Otitis media","Nasal obstruction","Failure to thrive of child","Esophagitis"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2026, 'ENT', 'Nose & Paranasal Sinuses', 'Moderate', 'ENT', 303, '{"id":2026,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Moderate","source":"ENT","sourceNo":303,"q":"All of the following are treatments of multiple bilateral ethmoidal polyps except?","o":["Functional endoscopic sinus surgery","Intranasal ethmoidectomy","Extranasal ethmoidectomy","Caldwll Luc Surgery"],"a":3,"e":"Ans. is ''d'' i.e., Caldwil Luc Surgery [Ref Scott Brown, Vol-IL p.1701; Dhingra 5`\"/e p. 188, 430] Surgical treatment of ethmoidal polyps :","pyqMatches":[{"year":"2015","no":955,"q":"All of the following are treatments of multiple bilateral ethmoidal polyps except?","o":["Functional endoscopic sinus surgery","Intranasal ethmoidectomy","Extranasal ethmoidectomy","Caldwll Luc Surgery"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2027, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 304, '{"id":2027,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":304,"q":"What is the treatment of choice for ethmoidal polyps?","o":["Functional Endoscopic sinus surgery with polypectomy","Intranasal ethmoidectomy","Extranasl ethmoidectomy","Transantral ethmoidectomy"],"a":0,"e":"Ans. is ''a'' i.e.,Functional Endoscopic sinus surgery with polypectomy [Ref See above explanation]","pyqMatches":[{"year":"2015","no":956,"q":"What is the treatment of choice for ethmoidal polyps?","o":["Functional Endoscopic sinus surgery with polypectomy","Intranasal ethmoidectomy","Extranasl ethmoidectomy","Transantral ethmoidectomy"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2028, 'ENT', 'Head & Neck', 'Easy', 'ENT', 305, '{"id":2028,"subject":"ENT","chapter":"Head & Neck","difficulty":"Easy","source":"ENT","sourceNo":305,"q":"What is the type of epithelium of the adenoid?","o":["Pseudostratified ciliated columnar epithelium","Non keratinized squamous epithelium","Cuboidal epithelium","Columnar epithelium with goblet cells"],"a":0,"e":"Ans. is ''a'' i.e., Pseudostratified ciliated columnar epithelium [Ref Wiatrak BJ, Woolley AL. Pharyngitis and adenoton​sillar disease. Cummings CW, Fredrickson JM , Harker LA, Crause CJ, Schuller DE, Richardson MA. Otolaryngology Head and Neck Surgery. ..V/e. London: Mosby; 1998. 188-215.] The adenoid is covered by a pseudostratified ciliated columnar epithelium that is plicated to form numerous surface folds The nasopharyngeal epithelium lines a series of mucosal folds, around which the lymphoid parenchyma is organized into follicles and is subdivided into 4 lobes by connective tissue septa Seromucous glands lie within the connective tissue, and their ducts extend through the parenchyma and reach the nasopharyngeal surface.","pyqMatches":[{"year":"2015","no":964,"q":"What is the type of epithelium of the adenoid?","o":["Pseudostratified ciliated columnar epithelium","Non keratinized squamous epithelium","Cuboidal epithelium","Columnar epithelium with goblet cells"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2029, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 306, '{"id":2029,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":306,"q":"The artery which leads to bleeding in Woodruff''s area is?","o":["Anterior ethmoidal artery","Sphenopalatine artery","Greater palatine artery","Superior labial artery"],"a":1,"e":"Ans. is ''b'' i.e., Sphenopalatine artery [Ref Scott Brown 7h/e Vol- 2p. 1597; Dhingra 5th/e p. 190] Woodruff''s area : ? It is situated under the posterior end of inferior turbinate. Sphenopalatine artery anastomoses with posterior pharyngeal artery here. Posterior epistaxis occurs in this area.","pyqMatches":[{"year":"2015","no":957,"q":"The artery which leads to bleeding in Woodruff''s area is?","o":["Anterior ethmoidal artery","Sphenopalatine artery","Greater palatine artery","Superior labial artery"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2030, 'ENT', 'Nose & Paranasal Sinuses', 'Hard', 'ENT', 307, '{"id":2030,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Hard","source":"ENT","sourceNo":307,"q":"Intrathecal fluorescein with endoscopic visualization is useful in diagnosis of?","o":["Deviated nasal septum","Multiple ethmoidal polyps","Rhinitis Medicamentosa","CSF Rhinorrhoea"],"a":3,"e":"Ans. is ''d'' i.e., CSF Rhinorrhoea [ Ref: Logan Turner 10(h/e p. 28, Dhingra 5th/e p. 179] Detection of site of CSF leak in CSF Rhinorrhoea","pyqMatches":[{"year":"2015","no":958,"q":"Intrathecal fluorescein with endoscopic visualization is useful in diagnosis of?","o":["Deviated nasal septum","Multiple ethmoidal polyps","Rhinitis Medicamentosa","CSF Rhinorrhoea"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2031, 'ENT', 'Nose & Paranasal Sinuses', 'Moderate', 'ENT', 308, '{"id":2031,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Moderate","source":"ENT","sourceNo":308,"q":"All of the following are features of a nasal foreign body except?","o":["Foul smelling discharge","Epistaxis","Nasal obstruction","Septal perforation"],"a":3,"e":"Ans. is ''d'' i.e., Septal perforation [Ref Dhingra SaVe p. 176; Logan Turner 10''h/e p. 63] Foreign body in nose A nasal foreign body is anything that gets stuck inside the nose. Inanimate foreign body (object) is more common than animate foreign body. Common objects found in noses include food material (peas, beans, nuts), tissue paper, beads, toys and rocks. Animate foreign bodies are worms, larvae or maggots. Most cases of foreign bodies in the nose and nasal cavity are not serious and occur in toddlers and children from 1-8 years. Because children develop the ability to pick up objects at about the age of 9 months, this problem is much less common before 9 months of age.","pyqMatches":[{"year":"2015","no":959,"q":"All of the following are features of a nasal foreign body except?","o":["Foul smelling discharge","Epistaxis","Nasal obstruction","Septal perforation"],"a":3,"source":"NEET_2015_Paper.pdf"},{"year":"2015","no":960,"q":"All of the following are features of a nasal foreign body except?","o":["Vestibulitis","Epistaxis","Nasal obstruction","Deviated septum"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2032, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 309, '{"id":2032,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":309,"q":"ETHMOIDAL BULLAE are seen in?","o":["Posterior ethmoidal air cells","Middle ethmoid air cells","Superior ethmoidal air cells","Inferior ethmoidal air cells"],"a":1,"e":"Ans. is ''b'' i.e., Middle ethmoid air cells [Ref: Logan Turner 10th le p. 379; Dhingra 5th/e p. 153, 154]","pyqMatches":[{"year":"2015","no":963,"q":"ETHMOIDAL BULLAE are seen in?","o":["Posterior ethmoidal air cells","Middle ethmoid air cells","Superior ethmoidal air cells","Inferior ethmoidal air cells"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2033, 'ENT', 'Nose & Paranasal Sinuses', 'Moderate', 'ENT', 310, '{"id":2033,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Moderate","source":"ENT","sourceNo":310,"q":"All of the following are features of a nasal foreign body except?","o":["Vestibulitis","Epistaxis","Nasal obstruction","Deviated septum"],"a":3,"e":"Ans. is ''d'' i.e., Deviated septum [Ref Dhingra 5thie p. 176; Logan Turner 10`\"/e p. 63]","pyqMatches":[{"year":"2015","no":959,"q":"All of the following are features of a nasal foreign body except?","o":["Foul smelling discharge","Epistaxis","Nasal obstruction","Septal perforation"],"a":3,"source":"NEET_2015_Paper.pdf"},{"year":"2015","no":960,"q":"All of the following are features of a nasal foreign body except?","o":["Vestibulitis","Epistaxis","Nasal obstruction","Deviated septum"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2034, 'ENT', 'Nose & Paranasal Sinuses', 'Moderate', 'ENT', 311, '{"id":2034,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Moderate","source":"ENT","sourceNo":311,"q":"All of the following are causes of perforation of cartilaginous part of nasal septum except?","o":["Tuberculosis","Leprosy","Lupus","Syphilis"],"a":3,"e":"Ans. is ''d'' i.e., Syphilis [Ref Dhingra 5th/e p. 166; Scott-Brown''s Otolaryngology 7th/e Vol-2 chapter-124 p. 1583] A nasal septal perforation is a through-and-through defect in any portion of the cartilaginous or bony septum with no overlying mucoperichondrium or mucoperiosteum on either side. Perforation of bony part :- Syphilis Perforation of cartilaginous part :- TB, leprosy, lupus.","pyqMatches":[{"year":"2015","no":961,"q":"All of the following are causes of perforation of cartilaginous part of nasal septum except?","o":["Tuberculosis","Leprosy","Lupus","Syphilis"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2035, 'ENT', 'Nose & Paranasal Sinuses', 'Moderate', 'ENT', 312, '{"id":2035,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Moderate","source":"ENT","sourceNo":312,"q":"All of the following are true about nasal myiasis except?","o":["Common in vasomotor rhinitis","Intense nasal irritation present","Meningitis may occur in severe disease","Chloroform water is one of the modes of treatment"],"a":0,"e":"Ans. is ''a'' i.e., Common in vasomotor rhinitis [Ref Dhingra 5th/e p. 178]","pyqMatches":[{"year":"2015","no":962,"q":"All of the following are true about nasal myiasis except?","o":["Common in vasomotor rhinitis","Intense nasal irritation present","Meningitis may occur in severe disease","Chloroform water is one of the modes of treatment"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2036, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 313, '{"id":2036,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":313,"q":"Water’s view is used to obtain diagnostic information of:","o":["Maxillary sinus","Ethmoidal sinuses","Frontal sinus","Sphenoid sinus"],"a":0,"e":"ANSWER: A. Maxillary sinus Waters'' view (also known as the Occipitomental view) is a radiographic view, where an X-ray beam is angled at 45° to the orbitomeatal line. The rays pass from behind the head and are perpendicular to the radiographic plate. It is commonly used to get a better view of the maxillary sinuses.","pyqMatches":[{"year":"2017","no":150,"q":"Water’s view is used to obtain diagnostic information of:","o":["Maxillary sinus","Ethmoidal sinuses","Frontal sinus","Sphenoid sinus"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":120,"q":"Water’s view is used to obtain diagnostic information of:","o":["Maxillary sinus","Ethmoidal sinuses","Frontal sinus","Sphenoid sinus"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2037, 'ENT', 'Throat & Larynx', 'Easy', 'ENT', 314, '{"id":2037,"subject":"ENT","chapter":"Throat & Larynx","difficulty":"Easy","source":"ENT","sourceNo":314,"q":"Tracheostomy indication is:","o":["Vocal cord replacement","Pharynx replacement","Tracheomalacia","Foreign body obstructing airway"],"a":3,"e":"Answer- D. Foreign body obstructing airway Indications of tracheostomy: Upper respiratory tract obstruction; Laryngeal, supralaryngeal ,and tracheal causes.( Causes of stridor ) Lower respiratory tract obstruction: (Secretory obstruction, Wet lung syndrome).","pyqMatches":[{"year":"2017","no":151,"q":"Tracheostomy indication is:","o":["Vocal cord replacement","Pharynx replacement","Tracheomalacia","Foreign body obstructing airway"],"a":3,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":121,"q":"Tracheostomy indication is:","o":["Vocal cord replacement","Pharynx replacement","Tracheomalacia","Foreign body obstructing airway"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2038, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 315, '{"id":2038,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":315,"q":"Caldwell’s view is used for:","o":["Maxillary sinus","Frontal sinus","Ethmoidal sinus","All of the above"],"a":1,"e":"Answer- B. Frontal sinus Caldwell''s view (or Occipitofrontal view) is a radiographic view of skull, where X-ray plate is angled at 20° to orbitomeatal line. The rays pass from behind the head and are perpendicular to radiographic plate. It is commonly used to get better view of frontal sinuses.","pyqMatches":[{"year":"2017","no":153,"q":"Caldwell’s view is used for:","o":["Maxillary sinus","Frontal sinus","Ethmoidal sinus","All of the above"],"a":1,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":122,"q":"Caldwell’s view is used for:","o":["Maxillary sinus","Frontal sinus","Ethmoidal sinus","All of the above"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2039, 'ENT', 'Ear', 'Easy', 'ENT', 316, '{"id":2039,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":316,"q":"Where will be the placement location for Auditory Brainstem Implant?","o":["Scala tympani","Recess of 4th ventricle","IAC","back of ear"],"a":1,"e":"Answer: B - Recess of 4th ventricle. The implant is usually placed in the lateral recess of the fourth ventricle at the time of tumor resection to stimulate the cochlear nucleus Auditory Brainstem Implant (ABI): Tumor resection surgery in NF patients result in cochlear nerve damage or loss of function of nerve resulting in deafness. ABI are useful in restoring auditory perception to deaf patients with neurofibromatosis type 2 (NF2) Also used in treatment of congenitally deaf children with cochlear malformations or cochlear nerve deficiencies. Placement location: Lateral recess of 4th ventricle","pyqMatches":[{"year":"2018","no":288,"q":"Where will be the placement location for Auditory Brainstem Implant?","o":["Scala tympani","Recess of 4th ventricle","IAC","back of ear"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2040, 'ENT', 'Ear', 'Moderate', 'ENT', 317, '{"id":2040,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":317,"q":"All of the following are features of Tubotympanic CSOM except ?","o":["Profuse discharge","Hearing loss","Extreme pain","Sometimes paradoxical improvement in hearing is seen"],"a":2,"e":"Ans. is ''c'' i.e., Extreme pain [Ref Dhingra 5th/e p. 77; Pediatric otolaryngology 2\"/e p. 478] Clinical features of tubotympanic CSOM Profuse mucopurulent discharge which is not foul smelling, i.e., non- foul smelling discharge Hearing loss (conductive type). If sensorineural component also occurs (i.e., mixed type), it arouses the suspicion of toxic deafness. Sometimes, patient reports a paradoxical effect, i.e., hears better in the presence of discharge than when the ear isdry. This is due to round window shielding effect produced by discharge which helps to maintain phase differential. There is no pain, if it occurs it is due to associated otitis externa not due to otitis media. Since the infected area is open at both ends, discharge does not accumulate in the middle ear cavity Ossicular chain is mostly uninvolved, if involved only long process of incus is involved.","pyqMatches":[{"year":"2015","no":982,"q":"All of the following are features of Tubotympanic CSOM except ?","o":["Profuse discharge","Hearing loss","Extreme pain","Sometimes paradoxical improvement in hearing is seen"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2041, 'ENT', 'Ear', 'Moderate', 'ENT', 318, '{"id":2041,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":318,"q":"Features of Usher''s Syndrome include all except ?","o":["Night Blindness","Visual Impairment","Multiple Neurofibromas","Hearing deficit"],"a":2,"e":"Ans. is ''c'' i.e., Multiple Neurofibromas [Ref Mets MB, Young NM, Pass A, Lasky JB (2000). \"Early diagnosis of Usher syndrome in children\". Transactions of the American Ophthalmological Society. 98: 237-45.] Usher syndrome Usher syndrome is a relatively rare genetic disorder caused by a mutation in any one of at least 11 genes resulting in a combination of hearing loss and visual impairment, and is a leading cause of deafblindness. Usher syndrome is incurable at present. Other names for Usher syndrome include Hallgren syndrome, Usher-Hallgren syndrome, retinitis pigmentosa dysacusis syndrome, and dystrophia retinae dysacusis syndrome. This syndrome is characterized by hearing loss and a gradual visual impairment. The hearing loss is caused by a defective inner ear, whereas the vision loss results from retinitis pigmentosa (RP), a degeneration of the retinal cells.Usually, the rod cells of the retina are affected first, leading to early night blindness and the gradual loss of peripheral vision. In other cases, early degeneration of the cone cells in the macula occurs, leading to a loss of central acuity. In some cases, the foveal vision is spared, leading to \"doughnut vision\"; central and peripheral vision are intact, but an annulus exists around the central region in which vision is impaired.","pyqMatches":[{"year":"2015","no":983,"q":"Features of Usher''s Syndrome include all except ?","o":["Night Blindness","Visual Impairment","Multiple Neurofibromas","Hearing deficit"],"a":2,"source":"NEET_2015_Paper.pdf"},{"year":"2015","no":1069,"q":"Features of Usher''s Syndrome include all except ?","o":["Night Blindness","Visual Impairment","Multiple Neurofibromas","Hearing deficit"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2042, 'ENT', 'Audiology', 'Easy', 'ENT', 319, '{"id":2042,"subject":"ENT","chapter":"Audiology","difficulty":"Easy","source":"ENT","sourceNo":319,"q":"65 year old person with hearing loss with normal speech discrimination is suffering from?","o":["Noise induced hearing loss","Presbycusis","Ototoxic drug","NOHL"],"a":1,"e":"Ans. is ''B'' i.e., Presbycusis Information in this question are :- (i) Old age (65 years), (ii) Hearing loss, and (iii) Preserved speech discrimnation. Diagnosis is Presbycusis. Presbycusis Presbycusis refers to sensorineural hearing loss in elderly individuals Characteristically, presbycusis involves bilateral high frequency hearing loss associated with difficulty in speech discrimination and central auditory processing information. Four pathological types of presbycusis have been identified :- Sensory presbycusis There is epithelial atrophy with loss of sensory hair cells and supporting cells in the organ of corti. This process starts in the basal turn of cochlea and slowly progress towards the apex. Higher frequencies are affected but speech discrimination is preserved. Neural presbycusis :- There is atrophy of nerve cells in the cochlea and central neural pathways. Atrophy occurs throughout the cochlea, with the basilar region only slightly more predisposed than the remainder of the cochlea. Therefore, no precipitous drop in threshold on audiometry is observed. Speech discrimination is poor. Metabolic (strial) presbycusis ;;- There is atrophy of stria vascularis. Atrophy results in hearing loss represented by flat audiogram, but speech discrimination is preserved. Mechanical (cochlear conductive) presbycusis :- There is thickening and secondary stiffening of the basilar membrane of the cochlea. The thickening is more severe in the basal turn of cochlea where the basilar membrane is narrow. This correlates with a gradually sloping high frequency sensorineural hearing loss. Speech discrimination is average.","pyqMatches":[{"year":"2012","no":1007,"q":"65 year old person with hearing loss with normal speech discrimination is suffering from?","o":["Noise induced hearing loss","Presbycusis","Ototoxic drug","NOHL"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2043, 'ENT', 'Ear', 'Easy', 'ENT', 320, '{"id":2043,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":320,"q":"Stimulation of the external auditory canal leads to cough due to which nerve","o":["Auricular branch Vagus","Greater auricular nerve","Auriculotemporal nerve","Facial Nerve"],"a":0,"e":"Ans: A. Auricular branch Vagus nerve. >Auricular branch of Vagus (Arnold''s nerve) and Facial nerve continues inwards to supply the posterior wall and floor of the EAC. > The cough response caused while stimulating the ear canal is mediated by the vagus which also supplies the larynx. (Re/. Shambaugh, 6th ed., page 45)","pyqMatches":[{"year":"2020","no":123,"q":"Stimulation of the external auditory canal leads to cough due to which nerve","o":["Auricular branch Vagus","Greater auricular nerve","Auriculotemporal nerve","Facial Nerve"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2044, 'ENT', 'Ear', 'Easy', 'ENT', 321, '{"id":2044,"subject":"ENT","chapter":"Ear","difficulty":"Easy","source":"ENT","sourceNo":321,"q":"widening of the cartilaginous part of the extra auditory canal called.","o":["Otoplasty","Myringoplasty","Tympanoplasty","Meatoplasty"],"a":3,"e":"Ans. (d) Meatoplasty. Meatoplasty is an operative technique to widen the lateral cartilaginous part of the external auditory canal. Otoplasty- is a procedure to change the shape, position or size of the ears. Myringoplasty-closure of the perforation of pars tensa of the tympanic membrane Tympanoplasty- surgical technique to repair a defect in the tympanic membrane with the placement of a graft, either medial or lateral to the tympanic membrane annulus ref:https://vula.uct.ac.za/access/content/group/ba5fb1bd-be95- 48e5-81be-586fbaeba29d/Meatoplasty.pdf","pyqMatches":[{"year":"2020","no":124,"q":"widening of the cartilaginous part of the extra auditory canal called.","o":["Otoplasty","Myringoplasty","Tympanoplasty","Meatoplasty"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2045, 'ENT', 'Ear', 'Moderate', 'ENT', 322, '{"id":2045,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"ENT","sourceNo":322,"q":"Tubercular Otitis media is characterized by all except","o":["Painful otorrhea","Multiple perforations","Pale granulations","Foul-smelling ear discharge"],"a":0,"e":"Ans. A. Painful otorrhea. >Tuberculosis of middle ear is a comparatively rare entity usually seen in association with or secondary to pulmonary tuberculosis, the infection reaches the middle ear through the eustachian tube >It is characterized by painless otorrhoea which fails to respond to the usual antimicrobial treatment >patient with evidence of tubercle infection elsewhere followed by multiple tympanic membrane perforations, abundant granulation tissue, and bone necrosis, preauricular lymph node enlargement https://www.ncbi.nlm.nih.gov/pubmed/21522113","pyqMatches":[{"year":"2020","no":125,"q":"Tubercular Otitis media is characterized by all except","o":["Painful otorrhea","Multiple perforations","Pale granulations","Foul-smelling ear discharge"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2046, 'ENT', 'Nose & Paranasal Sinuses', 'Easy', 'ENT', 323, '{"id":2046,"subject":"ENT","chapter":"Nose & Paranasal Sinuses","difficulty":"Easy","source":"ENT","sourceNo":323,"q":"Partial and full closure done in","o":["Atrophic rhinitis","Allergic rhinitis","Vasomotor rhinitis","Occupational rhinitis"],"a":0,"e":"Ans. A. Atrophic rhinitis ATROPHIC RHINITIS >It is a form of chronic rhinitis associated with atrophy of nasal mucosa, mucous glands, nerves, and vessels. >It can be primary or secondary. >The surgical options aim to reduce the size of the roomy cavities to prevent the exposure to drying effects of air and crusts formation and thus help regeneration of nasal mucosa. Full closure - Young''s operation Partial closure - Modified young''s operation. (Ref. Cummings,6th ed., 695)","pyqMatches":[{"year":"2020","no":126,"q":"Partial and full closure done in","o":["Atrophic rhinitis","Allergic rhinitis","Vasomotor rhinitis","Occupational rhinitis"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2047, 'ENT', 'Miscellaneous', 'Easy', 'ENT', 324, '{"id":2047,"subject":"ENT","chapter":"Miscellaneous","difficulty":"Easy","source":"ENT","sourceNo":324,"q":"Occipitomental view of PNS X-ray called as","o":["Caldwell view","Water view","Town view","Pine view"],"a":1,"e":"Answer:b. Water view Occipitomental view of PNS X-ray called as Water view","pyqMatches":[{"year":"2020","no":127,"q":"Occipitomental view of PNS X-ray called as","o":["Caldwell view","Water view","Town view","Pine view"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2048, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 1, '{"id":2048,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":1,"q":"Grievous hurt comes under which section of IPC?","o":["Section 319","Section 320","Section 324","Section 326"],"a":1,"e":"Section 320 REF: Textbook of Forensic Medicine and Toxicology by Nagesh Kumar Rao Page 259 Section 320: Grievous hurt The following kinds of hurt only are designated as \"grievous\"","pyqMatches":[{"year":"2016","no":621,"q":"Grievous hurt comes under which section of IPC?","o":["Section 319","Section 320","Section 324","Section 326"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2049, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 2, '{"id":2049,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":2,"q":"Four carpal bones are present at what age?","o":["3 years","4 years","5 years","6 years"],"a":1,"e":"4 years REF: Parikh 6'' edition page 2.9 Between 2 to 6 years, the number of carpal bones present on X ray represents the approximate age in years, as for example, four carpal bones — 4 years.","pyqMatches":[{"year":"2016","no":29,"q":"Four carpal bones are present at what age?","o":["3 years","4 years","5 years","6 years"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2050, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 3, '{"id":2050,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":3,"q":"Grevious hurt comes under section:","o":["319","320","324","326"],"a":1,"e":"320","pyqMatches":[{"year":"2014","no":643,"q":"Grevious hurt comes under section:","o":["319","320","324","326"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2051, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 4, '{"id":2051,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":4,"q":"Magnan''s phenomenon occurs in addiction of:","o":["Alcohol","Cocaine","LSD","Opiates"],"a":1,"e":"Cocaine","pyqMatches":[{"year":"2014","no":541,"q":"Magnan''s phenomenon occurs in addiction of:","o":["Alcohol","Cocaine","LSD","Opiates"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2052, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 5, '{"id":2052,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":5,"q":"\"Last\" to putrefy in male is:","o":["Uterus","Prostate","Testes","Liver"],"a":1,"e":"Prostate","pyqMatches":[{"year":"2014","no":688,"q":"\"Last\" to putrefy in male is:","o":["Uterus","Prostate","Testes","Liver"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2053, 'Forensic Medicine', 'Sexual Offences', 'Moderate', 'Forensic_Medicine', 6, '{"id":2053,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":6,"q":"All the following are true regarding pseudocyesis, EXCEPT:","o":["The patients usually have an intense desire to have children","Change in the breast may be present","There may be considerable increase in the size of the abdomen","The labour pain invariably continue to persist even if she is told that she is not pregnant"],"a":3,"e":"Pseudocyesis or phantom pregnancy is usually seen in patients nearing menopause or in young women who intensely desire children. Most of them suffer from some forms of psychic or hormonal disorder. The abdomen may distend due to deposition of fat. The pregnancy may progress to full term and the labour pain may stop abruptly when informed that she is not pregnant. Ref: Textbook of Forensic Medicine and Toxicology by Narayan Reddy, Edition 21, Page - 333","pyqMatches":[{"year":"2014","no":2083,"q":"All the following are true regarding pseudocyesis, EXCEPT:","o":["The patients usually have an intense desire to have children","Change in the breast may be present","There may be considerable increase in the size of the abdomen","The labour pain invariably continue to persist even if she is told that she is not pregnant"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2054, 'Forensic Medicine', 'Medical Jurisprudence', 'Easy', 'Forensic_Medicine', 7, '{"id":2054,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":7,"q":"Minimum age for giving consent for organ donation in India is?","o":["16 years","18 years","21 years","No age limit"],"a":1,"e":"A legal age of 18 years has been set to consent for termination of pregnancy (MTP Act 1971), donation of blood and donation of organs (Transplantation of Human Organ Act 1994). As per Transplantation of Human Organs Act 1994 \"donor\" means any person, not less than eighteen years of age, who voluntarily authorizes the removal of any of his organs for therapeutic purposes under subsection (1) or sub-section (2) of section 3. Parents or Guardians consent will be required for any individual below 18 years wishing to donate an organ.","pyqMatches":[{"year":"2016","no":626,"q":"Minimum age for giving consent for organ donation in India is?","o":["16 years","18 years","21 years","No age limit"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2055, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 8, '{"id":2055,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":8,"q":"Choking is characteristic of the following weapon:","o":["Revolver","Pistol","Shotgun","Rifle"],"a":2,"e":"The choking lessens the rate of spread of shot after it leaves the muzzle, increases the explosive force and increases the velocity. Shotguns have variable choke adapters. Different degrees are known as full-choke, half-choke and quarter-choke or improved cylinder. Ref: The Essentials of Forensic Medicine and Toxicology by K S Reddy, 27th edition, Page 184.","pyqMatches":[{"year":"2015","no":646,"q":"Choking is characteristic of the following weapon:","o":["Revolver","Pistol","Shotgun","Rifle"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2056, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 9, '{"id":2056,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":9,"q":"Which of the following is meant by the term ‘Sin of Gomorrah’?","o":["Oral sex","Anal sex","Bestiality","Lesbianism"],"a":0,"e":"Oral sex is also called coitus per os or Sin of Gomorrah or buccal coitus. According to Bible the sin was common in a town called: Gomorrah, so the name. It is included in Unnatural sexual offences Act (S.377 IPC). Ref: The Essentials of Forensic Medicine and Toxicology by Dr. K. S. Narayan Reddy, 27th edition, Page 365.","pyqMatches":[{"year":"2016","no":660,"q":"Which of the following is meant by the term ‘Sin of Gomorrah’?","o":["Oral sex","Anal sex","Bestiality","Lesbianism"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2057, 'Forensic Medicine', 'Forensic Identification', 'Moderate', 'Forensic_Medicine', 10, '{"id":2057,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":10,"q":"Disputed maternity can be solved by using the following tests, EXCEPT:","o":["Blood grouping","HLA typing","Preciptin test","DNA fingerprinting"],"a":2,"e":"Precipitin test is an antigen-antibody reaction test, used to distinguish between species. It uses species specific antiserum. It will not be used for disputed maternity. Ref: Textbook of Medical Jurisprudence, Forensic Medicine and Toxicology By Parikh, 6th Edition, Pages 7-21 ; The Essentials of Forensic Medicine and Toxicology By K S Narayan Reddy, 27th Edition, Pages 402","pyqMatches":[{"year":"2012","no":630,"q":"Disputed maternity can be solved by using the following tests, EXCEPT:","o":["Blood grouping","HLA typing","Preciptin test","DNA fingerprinting"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2058, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 11, '{"id":2058,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":11,"q":"Post mortem staining gets fixed after :","o":["2-3 hrs.","3-4 hrs.","5-6 hrs..","7-8 hours"],"a":3,"e":"D i.e. 7-8 hours","pyqMatches":[{"year":"2016","no":639,"q":"Post mortem staining gets fixed after :","o":["2-3 hrs.","3-4 hrs.","5-6 hrs..","7-8 hours"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2059, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 12, '{"id":2059,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":12,"q":"True about cadaveric spasm :","o":["Develops immediately after death","May develop hours after death","Develops only in facial muscles","All"],"a":0,"e":"A i.e. Develops immediately after death","pyqMatches":[{"year":"2015","no":639,"q":"True about cadaveric spasm :","o":["Develops immediately after death","May develop hours after death","Develops only in facial muscles","All"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2060, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 13, '{"id":2060,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":13,"q":"Adipocere formation is seen in:","o":["Dead body exposed to air","Dead body buried in damp, clay soil","Burial in dry hot air","All"],"a":1,"e":"B i.e. Dead body buried in damp, clay soil Ideal condition for adipocere formation are warm (hot) temperature, moisture (humid) & diminution of airQ e.g. dead body immersed in water or damp soilQ","pyqMatches":[{"year":"2015","no":636,"q":"Adipocere formation is seen in:","o":["Dead body exposed to air","Dead body buried in damp, clay soil","Burial in dry hot air","All"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2061, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 14, '{"id":2061,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":14,"q":"Heat Rupture is characterized by:","o":["Regular margins","Irregular margins","Ruptured blood vessels","Ruptured Red Blood cells/clotted blood"],"a":1,"e":"B i.e. Irregular margins","pyqMatches":[{"year":"2016","no":657,"q":"Heat Rupture is characterized by:","o":["Regular margins","Irregular margins","Ruptured blood vessels","Ruptured Red Blood cells/clotted blood"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2062, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 15, '{"id":2062,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":15,"q":"Emphysema aquosum is seen in:","o":["Wet drowning","Dry drowning","Immersion syndrome","Secondary drowning"],"a":0,"e":"A i.e. Wet drowning - Emphysema aquosum is seen in wet (typical) drowningQ where drowning fluid causes alveolar wall disruption & enters tissue & blood vessels. If dead body is thrown into water, due to hydrostatic pressure water passes into lungs known as hydrostatic lung. Oedema aquosum (no columns of froth) is seen in drowning of unconscious. - ARDS & Fibrosing alveolitis is seen in near drowning or secondary drowning syndrome. - Dry Lung is seen in dry drowning in which death occurs due to laryngeal spasm. - If drowning is survived, the event is referred to as near drowning & complications as near (secondary) drowning syndrome.. - In Immersion syndrome death results from cardiac arrest due to vagal inhibition.Q","pyqMatches":[{"year":"2015","no":648,"q":"Emphysema aquosum is seen in:","o":["Wet drowning","Dry drowning","Immersion syndrome","Secondary drowning"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2063, 'Forensic Medicine', 'Miscellaneous', 'Hard', 'Forensic_Medicine', 16, '{"id":2063,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Forensic_Medicine","sourceNo":16,"q":"In a case of hanging neck ligature marks are example of","o":["Contussion","Printed abrasion","Laceration","Bruise"],"a":1,"e":"B i.e. Printed abrasion","pyqMatches":[{"year":"2012","no":615,"q":"In a case of hanging neck ligature marks are example of","o":["Contussion","Printed abrasion","Laceration","Bruise"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2064, 'Forensic Medicine', 'Thanatology', 'Hard', 'Forensic_Medicine', 17, '{"id":2064,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Hard","source":"Forensic_Medicine","sourceNo":17,"q":"In case of death in lock up, the inquest is held by","o":["A police officer","Magistrate","Panchayat officer","District Attorney"],"a":1,"e":"B i.e. Magistrate","pyqMatches":[{"year":"2014","no":647,"q":"In case of death in lock up, the inquest is held by","o":["A police officer","Magistrate","Panchayat officer","District Attorney"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2065, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 18, '{"id":2065,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":18,"q":"Which of following tests in used to detect semen?","o":["Phenolphthalein test","Reine''s test","Barberio''s test","Paraffin test"],"a":2,"e":"C i.e. Barberio''s test : Barberio''s test is used for identification of seminal stains Few drops of barberio''s reagent (containing pieric acid) are added to the seminal stain. Positive test is indicated by formation of Yellow and needle shaped crystals of spermine picrate. (Spermine in seminal stain reacts with picric acid to form these crystals) Phenolphthalein test (Kastle-Meyer test) is used for identification of haemoglobin in blood stains - Parikh 6th/7.16 Paraffin test (or Dermal nitrate test) is used to detect gun powder on skin i.e. to determine if suspect had discharged a firearm- Parikh 6\"/7.39 Reine''s test has not been mentioned in forensic literature Forensic tests to detect Seminal Stain Blood Stains - Barberio''s testO - Benzidine testQ - Fluorence testQ - Phenophthalein (Kastle? Q ( - Acid phosphatase Meyer) testQ testQ - Takayama''s - Creatine phosphatase Haemochromogen crystal test testQ - Elisa test - Teichmann''s Haemin crystal testQ - Spectroscopic test","pyqMatches":[{"year":"2014","no":709,"q":"Which of following tests in used to detect semen?","o":["Phenolphthalein test","Reine''s test","Barberio''s test","Paraffin test"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2066, 'Forensic Medicine', 'Sexual Offences', 'Easy', 'Forensic_Medicine', 19, '{"id":2066,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":19,"q":"Transvestism is :","o":["Wearing clothes of opposite sex","Touching ones own private parts to others","Desire for sexual intercourse with dead bodies","Orgasm from visualisation part of the body of a woman"],"a":0,"e":"A i.e. Wearing clothes of opposite sex","pyqMatches":[{"year":"2016","no":659,"q":"Transvestism is :","o":["Wearing clothes of opposite sex","Touching ones own private parts to others","Desire for sexual intercourse with dead bodies","Orgasm from visualisation part of the body of a woman"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2067, 'Forensic Medicine', 'Sexual Offences', 'Moderate', 'Forensic_Medicine', 20, '{"id":2067,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":20,"q":"Paraphilias are all except :","o":["Bisexuality","Homosexuality","Bestiality","Frottuerism"],"a":0,"e":"A i.e. Bisexuality - Abnormal & unorthodox sex play by using unusal objects or parts of body are known as paraphillia eg. Sadomasochism, Transvestism, Uranism, Beastality, Fortteurism, Urolangia, Homosexuality etc. - Bisexuality means hermaphrodite i.e. an individual with both ovary & testis & external genitals of both sexes.","pyqMatches":[{"year":"2014","no":2097,"q":"Paraphilias are all except :","o":["Bisexuality","Homosexuality","Bestiality","Frottuerism"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2068, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 21, '{"id":2068,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":21,"q":"Widmark''s formula helps in the measurements of blood level of:","o":["Barbiturates","Cocaine","Alcohol","Benzodiazepines"],"a":2,"e":"C i.e. Alcohol","pyqMatches":[{"year":"2012","no":653,"q":"Widmark''s formula helps in the measurements of blood level of:","o":["Barbiturates","Cocaine","Alcohol","Benzodiazepines"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2069, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 22, '{"id":2069,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":22,"q":"Postmortem wound best differs from the antemortem wound by :","o":["Gaps on incising","No clots","Absence of erythema and cellular changes","All"],"a":2,"e":"C i.e. Absence of erythema & cellular change","pyqMatches":[{"year":"2016","no":647,"q":"Postmortem wound best differs from the antemortem wound by :","o":["Gaps on incising","No clots","Absence of erythema and cellular changes","All"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2070, 'Forensic Medicine', 'Thanatology', 'Hard', 'Forensic_Medicine', 23, '{"id":2070,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Hard","source":"Forensic_Medicine","sourceNo":23,"q":"Arsenic poisoning presents with symptoms mimicking","o":["Cholera","Dhatura poisoning","Barbiturates poisoniong","Morphine poisoning"],"a":0,"e":"Ans:A.)Cholera. ARSENIC • Copper arsenite - sheele''s green • Copper acetoarsenite - paris green • Permissible limits of arsenic in ground water - 0.05mg/L • The gastroenteric type of poisoning resembles cholera • Greatest quantity is seen in - liver • Red velvety appearance of mucosa of stomach • Most affected part of the stomach – pylorus • Subendocardial petechial hemorrhages of the ventricle is typical of arsenic poisoning (also found in phosphorus, barium, mercury and in cases of heat stroke and acute infectious disease e.g. influenza) • Rigor mortis lasts longer than usual, Delays putrefaction Acute poisoning • Necrosis of intestinal mucosa with hemorrhagic gastroenteritis • Hypotension, delayed cardiomyopathy Chronic poisoning • Aldrich Mee''s line on finger nails • Rain drop pigmentation on skin(meastes like rash) • Chronic consumption of water containing high arsenic concentrations lead to vasospasm and peripheral vascular insufficiency - black foot disease • Diabetes, peripheral neuropathy, gangrene • Cancer of skin, lung, liver (angiosarcoma), bladder, kidney. • Arsenophagists - some people take arsenic daily as tonic or aphrodisiac and acquire tolerance • Chelating agent - Dimercaprol Arsenic was used as murder weapons in royal families, and called as \"the poison of kings and king of poisons\"","pyqMatches":[{"year":"2015","no":665,"q":"Arsenic poisoning presents with symptoms mimicking","o":["Cholera","Dhatura poisoning","Barbiturates poisoniong","Morphine poisoning"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2071, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 24, '{"id":2071,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":24,"q":"Amyl Nitrate is used as an antidote in...poisoning :","o":["CO2","CO","Cyanide","Nitric acid"],"a":2,"e":"C i.e. Cyanide","pyqMatches":[{"year":"2014","no":712,"q":"Amyl Nitrate is used as an antidote in...poisoning :","o":["CO2","CO","Cyanide","Nitric acid"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2072, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 25, '{"id":2072,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":25,"q":"Meaning of term vitriolage is:","o":["Using vitriol for suicide","Using vitriol for murder","Vitriol throwing","Perforation of stomach caused by H2SO4"],"a":2,"e":"C i.e. Vitriol throwing Vitriolage (Vitriol throwing) is throwing of any corrosive, not necessarily sulphuric acid (H2SO4) on another personQ. Eyes are the most affected organs.","pyqMatches":[{"year":"2012","no":647,"q":"Meaning of term vitriolage is:","o":["Using vitriol for suicide","Using vitriol for murder","Vitriol throwing","Perforation of stomach caused by H2SO4"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2073, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 26, '{"id":2073,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":26,"q":"Best method of treatment of Methyl alcohol poisoning is :","o":["Calcium gluconate","Ethyl alcohol","Amphetamines","1 % Ammonia"],"a":1,"e":"B i.e. Ethyl alcohol","pyqMatches":[{"year":"2015","no":676,"q":"Best method of treatment of Methyl alcohol poisoning is :","o":["Calcium gluconate","Ethyl alcohol","Amphetamines","1 % Ammonia"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2074, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 27, '{"id":2074,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":27,"q":"Charas is :","o":["Leaves of Cannabis Indica","Flowers of Cannabis Indica","Stem of Cannabis Indica","Resin exudate of Cannabis Indica"],"a":3,"e":"D i.e. Resin exudates of cannabis Indica","pyqMatches":[{"year":"2015","no":663,"q":"Charas is :","o":["Leaves of Cannabis Indica","Flowers of Cannabis Indica","Stem of Cannabis Indica","Resin exudate of Cannabis Indica"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2075, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 28, '{"id":2075,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":28,"q":"True about strychnine poisoning is :","o":["All muscles affected at the same time","Shoulder girdle affected first","Pelvic girdle affected first","None of the above"],"a":0,"e":"A i.e. All muscles affected at same time","pyqMatches":[{"year":"2016","no":667,"q":"True about strychnine poisoning is :","o":["All muscles affected at the same time","Shoulder girdle affected first","Pelvic girdle affected first","None of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2076, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 29, '{"id":2076,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":29,"q":"Nux vomica seeds contain 2 alkaloids, strychnine and :","o":["Hyoscine","Hyoscyamine","Brucine","Atropine"],"a":2,"e":"C i.e. Brucine","pyqMatches":[{"year":"2016","no":672,"q":"Nux vomica seeds contain 2 alkaloids, strychnine and :","o":["Hyoscine","Hyoscyamine","Brucine","Atropine"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2077, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 30, '{"id":2077,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":30,"q":"A sea snake is:","o":["Neurotoxic","Hemotoxic","Musculotoxic","All of the above"],"a":2,"e":"C i.e. Musculo toxic","pyqMatches":[{"year":"2016","no":673,"q":"A sea snake is:","o":["Neurotoxic","Hemotoxic","Musculotoxic","All of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2078, 'Forensic Medicine', 'Injuries & Wounds', 'Moderate', 'Forensic_Medicine', 31, '{"id":2078,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":31,"q":"Not a grievous injury: September 2005","o":["Multiple scars of face","Fracture of femur","Emasculation","Contusion of breast"],"a":3,"e":"Ans. D: Contusion of breast Sec 320 IPC: any of the following injures are grievous? Emasculation Permanent privation of sight or either eye Permanent privation of Hearing or either ear Permanent privation of any member or joint Permanent disfiguration of the head or face Destruction or permanent impairing of the power of any member or joint Fracture or dislocation of a bone or tooth Any hurts which endangers life, or which causes the victim to be in severe bodily pain or unable to follow his ordinary pursuits for a period of twenty days","pyqMatches":[{"year":"2012","no":661,"q":"Not a grievous injury: September 2005","o":["Multiple scars of face","Fracture of femur","Emasculation","Contusion of breast"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2079, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 33, '{"id":2079,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":33,"q":"Brain death is said to occur if there is: March 2008","o":["Absent spinal reflexes","Cortical death following widespread brain injury","Absence of brainstem reflexes","Core temperature of the body is below 35 degree C"],"a":2,"e":"Ans. C: Absence of brainstem reflexes Brainstem is responsible for the respiratory drive and mostly for the maintenance of BP. All motor outputs from the brain travel through the brainstem. Apart from smell and vision. All sensory traffic coming into the brain comes through the brainstem. The brainstem also mediates the cranial nerve reflexes. Hence a properly functioning brain stem is a precondition for full consciousness. Irreversible brain damage and loss of brain function, is evidenced by cessation of breathing and other vital reflexes (mediated by brain stem), unresponsiveness to stimuli, absence of muscle activity, and a flat electroencephalogram for a specific length of time.","pyqMatches":[{"year":"2014","no":1343,"q":"Brain death is said to occur if there is: March 2008","o":["Absent spinal reflexes","Cortical death following widespread brain injury","Absence of brainstem reflexes","Core temperature of the body is below 35 degree C"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2080, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 34, '{"id":2080,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":34,"q":"First permanent teeth to erupt is: September 2008","o":["First premolar","Second premolar","First molar","Second molar"],"a":2,"e":"Ans. C: First molar At the age of about 6-7 year, first permanent molar teeth erupts behind the second temporary molar. At the age of 9, there are 12 permanent teeths. At the age of 11, there are 20 permanent teeths At the age of 14, there are 28 permanent teeths","pyqMatches":[{"year":"2012","no":1182,"q":"First permanent teeth to erupt is: September 2008","o":["First premolar","Second premolar","First molar","Second molar"],"a":2,"source":"NEET_2012_Paper.pdf"},{"year":"2013","no":1428,"q":"First permanent teeth to erupt is: September 2008","o":["First premolar","Second premolar","First molar","Second molar"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2012","2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2081, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 35, '{"id":2081,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":35,"q":"Rigor mortis occurs due to: September 2008","o":["Muscle of the body began to relax","Capillo-venous distension in the most dependent body parts","Muscle of the body began to stiffen","Mummification of the body tissues"],"a":2,"e":"Ans. C: Muscle of the body began to stiffen A few hours after the death, the joints of the body stiffen and become locked in place. This stiffening is called rigor mortis. Depending on temperature and other conditions, rigor mortis lasts approximately 24- 48 hours in winter and 18-36 hours in summer. The phenomenon is caused by the skeletal muscles partially contracting. The muscles are unable to relax, so the joints become fixed in place Rigor mortis can be used to help estimate time of death. The onset of rigor mortis may range from 1-2 hours, depending on factors including temperature (rapid cooling of a body can inhibit rigor mortis, but it occurs upon thawing). Maximum stiffness is reached around 12-24 hours post mortem. It first starts in involuntary muscles (myocardium) Eyelids, neck and jaw muscles are affected first, with the rigor then spreading to other parts of the body. The joints are stiff but after some time general tissue decay and leaking of lysosomal intracellular digestive enzymes will cause the muscles to relax.","pyqMatches":[{"year":"2016","no":637,"q":"Rigor mortis occurs due to: September 2008","o":["Muscle of the body began to relax","Capillo-venous distension in the most dependent body parts","Muscle of the body began to stiffen","Mummification of the body tissues"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2082, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 36, '{"id":2082,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":36,"q":"Best method for methanol poisoning treatment: March 2007","o":["Ethanol","Calcium gluconate","Desferroxamine","BAL"],"a":0,"e":"Ans. A: Ethanol When metabolized by hepatic alcohol and aldehyde dehydrogenase, methanol forms formaldehyde and formic acid, both of which are toxic. Formic acid is the primary toxin that accounts for the majority of the anion gap, metabolic acidosis, and ocular toxicity. Formic acid inhibits cytochrome oxidase in the fundus of the eye. Swelling of axons in the optic disc and edema result in visual impairment. Degradation of formic acid is folate dependent. Thus, if a folate- deficient person ingests ethanol, toxicity may be more severe due to the increased accumulation of formic acid. Approximately 90-95% of methanol metabolism occurs in the liver, while 5-10% is excreted unchanged through the lungs and kidneys. Methanol is primarily metabolized by alcohol and aldehyde dehydrogenase. Formaldehyde has a short half-life, lasting only minutes. Formic acid is metabolized much more slowly, and it bioaccumulates with significant methanol ingestion. Physical Sign Ocular physical findings include sluggishly reactive or fixed and dilated pupils. Retinal edema or hyperemia Edema of the optic disc may be seen. Optic atrophy may appear in late stages (permanent blindness). CNS signs include lethargy and confusion. Respiratory signs include dyspnea (rare cases) or even Kussmaul respiration, despite acidosis. Cardiac signs (e.g., hypotension, bradycardia) are late signs associated with a poor prognosis. Lab studies Methanol concentration: This study confirms ingestion and helps guide treatment. Remember that low serum concentration do not rule out significant toxicity; late presenters may have low methanol concentrations but elevated formic acid levels and severe clinical toxicity (e.g., severe metabolic acidosis, blindness, coma). Treatment Supportive measures Attempted correction of acidosis using sodium bicarbonate is indicated if pH is less than 7.20. An alkalemic pH makes it more likely that formic acid will exist as its anion (formate), which cannot access the CNS and optic nerve as readily. Administer folic acid for several days to potentiate the folate- dependent metabolism of formic acid to carbon dioxide and water. Ethanol infusion is recommended: Ethanol is a competitive inhibitor of alcohol dehydrogenase and, thereby, impairs the metabolism of methanol and ethylene glycol. Ethanol has 10-20 times greater affinity for alcohol dehydrogenase than methanol does. Plasma formate concentration is of prognostic value","pyqMatches":[{"year":"2015","no":607,"q":"Best method for methanol poisoning treatment: March 2007","o":["Ethanol","Calcium gluconate","Desferroxamine","BAL"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2083, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 37, '{"id":2083,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":37,"q":"Gastric lavage is contraindicated in which of the following: September 2010","o":["Arsenic poisoning","Kerosene poisoning","Organophosphorus Poisoning","Dhatura poisoning"],"a":1,"e":"Ans. B: Kerosene Poisoning Lavage is contraindicated when patients have a compromised, unprotected airway and in patients at risk of gastrointestinal hemorrhage or perforation. Relative contraindications include when the poisoning is due to a corrosive substance, hydrocarbons, or for poisons that have an effective antidote.","pyqMatches":[{"year":"2012","no":631,"q":"Gastric lavage is contraindicated in which of the following: September 2010","o":["Arsenic poisoning","Kerosene poisoning","Organophosphorus Poisoning","Dhatura poisoning"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2084, 'Forensic Medicine', 'Forensic Toxicology', 'Hard', 'Forensic_Medicine', 38, '{"id":2084,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Hard","source":"Forensic_Medicine","sourceNo":38,"q":"Which of the following poisoning presents with abdominal pain, diarrhea, Mees line on nails and myelosuppression: September 2011","o":["Lead","Arsenic","Alcohol","Mercury"],"a":1,"e":"Ans. B: Arsenic In chronic arsenic poisoning, a classical state of ill health results are represented by 4 stages. First stage of nutritional and gastrointestinal disturbances (diarrhoea is common) Third stage (of skin rashes) shows white bands known as Mees line crossing the nail of fingers and toes In addition to this, there may be evidence of liver damage, kidney damage and bone marrow depression at some stage Arsenic poisoning Increased levels of the element arsenic in the body. Arsenic interferes with cellular longevity by allosteric inhibition of an essential metabolic enzyme. Symptoms of arsenic poisoning include headache, confusion, convulsion, diarrhea, vomiting, and in severe case coma and death Routes of exposure include contaminated water, air, and food. Occupational exposure to arsenic may occur with copper or lead smelting and wood treatment and among workers involved in the production or application of pesticides Symptoms of arsenic poisoning begin with headaches, confusion, severe diarrhea, and drowsiness. As the poisoning develops, convulsions and changes in fingernail pigmentation called leukonychia may occur. When the poisoning becomes acute, symptoms may include diarrhea, vomiting, blood in the urine, cramping muscles, hair loss, stomach pain, and more convulsions. The organs of the body that are usually affected by arsenic poisoning are the lungs, skin, kidneys, and liver. Chronic arsenic exposure can remain in the body systems for a longer period of time than a shorter term or more isolated exposure and can be detected in a longer time frame after the introduction of the arsenic, important in trying to determine the source of the exposure. Hair is a potential bioindicator for arsenic exposure due to its ability to store trace elements from blood. Incorporated elements maintain their position during growth of hair. Thus for a temporal estimation of exposure, an assay of hair composition needs to be carried out with a single hair which is not possible with older techniques requiring homogenization and dissolution of several strands of hair. This type of biomonitoring has been achieved with newer microanalytical techniques like Synchroton radiation based X ray fluorescence (SXRF) spectroscopy and Microparticle induced X ray emission (PIXE). Dimercaprol and dimercaptosuccinic acid are chelating agents which sequester the arsenic away from blood proteins and are used in treating acute arsenic poisoning. The most important side effect is hypertension. Dimercaprol is considerably more toxic than succimer","pyqMatches":[{"year":"2012","no":586,"q":"Which of the following poisoning presents with abdominal pain, diarrhea, Mees line on nails and myelosuppression: September 2011","o":["Lead","Arsenic","Alcohol","Mercury"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
