INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2096, 'Forensic Medicine', 'Forensic Identification', 'Moderate', 'Forensic_Medicine', 50, '{"id":2096,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":50,"q":"Elderly individual living alone in a temperate zone is found dead one morning. The electric heater is found to be damaged. The rigor mortis will set in: NEET 14","o":["Earlier than expected","Later than expected","Will not set in","Will set in as expected"],"a":0,"e":"Ans. Earlier than expected","pyqMatches":[{"year":"2013","no":668,"q":"Elderly individual living alone in a temperate zone is found dead one morning. The electric heater is found to be damaged. The rigor mortis will set in: NEET 14","o":["Earlier than expected","Later than expected","Will not set in","Will set in as expected"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
