INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2108, 'Forensic Medicine', 'Injuries & Wounds', 'Moderate', 'Forensic_Medicine', 62, '{"id":2108,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":62,"q":"Shotgun does not contain use: NEET 13","o":["Barrel","Choke bore","Bullets","Muzzle"],"a":2,"e":"Ans. Bullets","pyqMatches":[{"year":"2012","no":620,"q":"Shotgun does not contain use: NEET 13","o":["Barrel","Choke bore","Bullets","Muzzle"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2109, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 63, '{"id":2109,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":63,"q":"Dirt collar or grease collar is seen in: NEET 13","o":["Punctured wound by sharp weapon","Lacerated wound","Firearm entry wound","Stab wound e) None"],"a":2,"e":"Ans. Firearm entry wound Smudge ring/Lead ring/Grease collar/Dirt collar This is due to the wipe of the soft metal of the bullet, or dirt present on it, or grease carried from the barrel & is deposited round the entrance wound internal to the abraded collar The smudge ring may therefore be absent when the jacketed bullet has passed through clothing The smudging in case of lead shot or unjacketed bullets can be detected microchemically on the target (skin/cloth) The forensic value of bullet wipe is to establish a hole as a bullet hole, to determine the entry site, & on occasion the sequence of shots or bullet''s passage through multiple objects.","pyqMatches":[{"year":"2012","no":621,"q":"Dirt collar or grease collar is seen in: NEET 13","o":["Punctured wound by sharp weapon","Lacerated wound","Firearm entry wound","Stab wound e) None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
