INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2111, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 65, '{"id":2111,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":65,"q":"Gunshot residue on hands can be detected by: DNB 10; NEET 13","o":["Phenolphthalein test","Dermal nitrate test","Benzidine test","H2 activation test"],"a":1,"e":"Ans. Dermal nitrate test","pyqMatches":[{"year":"2012","no":619,"q":"Gunshot residue on hands can be detected by: DNB 10; NEET 13","o":["Phenolphthalein test","Dermal nitrate test","Benzidine test","H2 activation test"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
