INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2121, 'Forensic Medicine', 'Injuries & Wounds', 'Moderate', 'Forensic_Medicine', 75, '{"id":2121,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":75,"q":"All sections of IPC are related to grievous hurt, except","o":["Sec. 320","Sec. 331","Sec. 326","Sec. 319"],"a":3,"e":"Ans. d. Sec. 319","pyqMatches":[{"year":"2013","no":638,"q":"All sections of IPC are related to grievous hurt, except","o":["Sec. 320","Sec. 331","Sec. 326","Sec. 319"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2122, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 76, '{"id":2122,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":76,"q":"True about reactionary hemorrhage following surgery: UP 10","o":["Hemorrhage occurring within 48 h","Hemorrhage occurring within 36 h","Hemorrhage occurring within 24 h","Hemorrhage occurring during surgery"],"a":2,"e":"Ans. Hemorrhage occurring within 24 h Hemorrhage according to the Time of appearance can be classified as belows Primary hemorrhage Is one which occur at the time of injury or operation. Reactionary hemorrhage In majority of cases reactionary occur within 4 to 6 hours. Such bleeding may also occur due to: Restlessness Coughing Vomiting with raises the venous pressure Secondary hemorrhage This occurs usually after 7 to 14 days of injury or operation. This is usually due to infection and sloughing of a part of the arterial wall.","pyqMatches":[{"year":"2014","no":1597,"q":"True about reactionary hemorrhage following surgery: UP 10","o":["Hemorrhage occurring within 48 h","Hemorrhage occurring within 36 h","Hemorrhage occurring within 24 h","Hemorrhage occurring during surgery"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
