INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2125, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 79, '{"id":2125,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":79,"q":"Gestational sac can be seen using ultrasonography at the earliest by: Gujarat 07","o":["3rd week","4th week","5th week","8th week"],"a":2,"e":"Ans. 5th week The gestational sac can be visualized as early as 41/2 weeks by transvaginal USG and 5 weeks by transabdominal USG.","pyqMatches":[{"year":"2014","no":2033,"q":"Gestational sac can be seen using ultrasonography at the earliest by: Gujarat 07","o":["3rd week","4th week","5th week","8th week"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2126, 'Forensic Medicine', 'Sexual Offences', 'Moderate', 'Forensic_Medicine', 80, '{"id":2126,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":80,"q":"In sexual assault of a child, the hymen is usually not ruptured due to: NEET 13","o":["Deep seated","Underdeveloped","Too tough to rupture","Distensible"],"a":0,"e":"Ans. Deep seated","pyqMatches":[{"year":"2012","no":627,"q":"In sexual assault of a child, the hymen is usually not ruptured due to: NEET 13","o":["Deep seated","Underdeveloped","Too tough to rupture","Distensible"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2127, 'Forensic Medicine', 'Sexual Offences', 'Easy', 'Forensic_Medicine', 81, '{"id":2127,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":81,"q":"Irresistible sexual desire in a male is known as: AIIMS 08","o":["Nymphomania","Tribadism","Satyriasis","Sadism"],"a":2,"e":"Ans. Satyriasis Satyriasis is excessive sexual desire in male where he enjoys having multiple sexual partners or desires excessive sexual activity. The female-specific term for the same condition is Nymphomania. A fetish is an abnormal stimulus or object of sexual desire. Fetishism means the use of such objects of sexual gratification leading to orgasm. For exmaple underclothing, brassiere, petticoat, stocking, shoes, etc. Frotteurism : Sexual satisfaction is obtained by rubbing against persons in crowd. If they attempt intercourse, they have a premature ejaculation or they are impotent. It is an uncommon perversion and rarely occurs alone","pyqMatches":[{"year":"2015","no":655,"q":"Irresistible sexual desire in a male is known as: AIIMS 08","o":["Nymphomania","Tribadism","Satyriasis","Sadism"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
