INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2146, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 100, '{"id":2146,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":100,"q":"Treatment of acute alcohol withdrawal: Punjab 09","o":["Diazepam","Bupropion","Disulfiram","Acamprosate"],"a":0,"e":"Ans. Diazepam","pyqMatches":[{"year":"2014","no":2090,"q":"Treatment of acute alcohol withdrawal: Punjab 09","o":["Diazepam","Bupropion","Disulfiram","Acamprosate"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2147, 'Forensic Medicine', 'Miscellaneous', 'Moderate', 'Forensic_Medicine', 101, '{"id":2147,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":101,"q":"All are true of opioid withdrawal, except: NIMHANS 10; PGI 14","o":["Yawning","Hallucinations","Lacrimation","Piloerection"],"a":1,"e":"Ans. Hallucinations","pyqMatches":[{"year":"2016","no":675,"q":"All are true of opioid withdrawal, except: NIMHANS 10; PGI 14","o":["Yawning","Hallucinations","Lacrimation","Piloerection"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
