INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2149, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 103, '{"id":2149,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":103,"q":"Toxin responsible for epidemic dropsy: AIIMS 07; UP 09; PGI 11","o":["BOAA","Aflatoxin","Sanguinarine","Pyrrozolidine"],"a":2,"e":"Ans. Sanguinarine","pyqMatches":[{"year":"2012","no":862,"q":"Toxin responsible for epidemic dropsy: AIIMS 07; UP 09; PGI 11","o":["BOAA","Aflatoxin","Sanguinarine","Pyrrozolidine"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2150, 'Forensic Medicine', 'Sexual Offences', 'Easy', 'Forensic_Medicine', 104, '{"id":2150,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":104,"q":"Nullity of marriage is considered when ?","o":["Adultery in first 7 years","Infertility of husband","Assault in first 7yrs","Age > 55years"],"a":1,"e":"Ans. is ''b'' i.e., Infertility of husband Under section 12 of Hindu Marriage Act 1955 or section 24 of Special Marriage Act 1954, a wife may seek divorce on the ground that her husband was impotent at the time of marriage and continues to be impotent therefore he is incapable of fulfilling the rights of consummation of marriage by an act of sexual intercourse. Conditions for nullity of marriage Any marriage can be declared null and void under following conditions:? 1) Bigamy, i.e. one spouse has made one more marriage 2) Impotence 3) If either party is underage 4) If one spouse is having unsound mind at the time of marriage, virulent form of leprosy or veneral disease in a communicable form. 5) If one spouse has not been heard of as being alive for a period of 7 years or undergoing a sentence of imprisonment for 7 years. 6) If the consent has been obtained by coercion or fraud. 7) If the woman already pregnant with some one else''s child at the time of marriage.","pyqMatches":[{"year":"2014","no":637,"q":"Nullity of marriage is considered when ?","o":["Adultery in first 7 years","Infertility of husband","Assault in first 7yrs","Age > 55years"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2151, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 105, '{"id":2151,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":105,"q":"WHO definition of abdominal obesity is ?","o":["Waist - hip ratio > 0.80 in females","Waist - hip ratio > 0.85 in females","Waist - hip ratio > 0.90 in females","Waist - hip ratio > 0.95 in females"],"a":1,"e":"Ans. is ''b'' i.e., Waist - hip ratio > 0.85 in females Assessment of obesity Following parameters are used to assess obesity :? 1) Skin fold thickness (SFT) Since it is most accessible, SFT is the most common method used to assess obesity. Measurements are taken at 4 sites : mid triceps (best site), biceps, subscapular and suprailiac regions. The sum of measurements _ 50 mm in girls and 240 mm in boys indicate obesity. At single mid triceps level (best site to measure SFT), thickness 18 mm in boys and 32 mm in girls indicate obesity. The instrument used to estimate SFT is Harpenden skin callipers. 2) Waist circumference (WC) and Waist / Hip ratio (WHR) These are good predictors for metabolic complications and risk of cardiovascular disease. The cut-off for waist circumference is 102 cms in boys (for India 90 cms) and 88 cms in girls (for India . 80 cms). WHR > 1.0 in men and > 0.85 in women indicates obesity and abdominal fat accumulation. 3) Waist-Height ratio (WHtR) It is the best indicator of cardiovascular risk. It is independent of age and sex. Cut-off value is 0.5. 4) Indices based on weight and/or height These are :? i) Body mass index (Qetelet''s index) It is used internationally as reference standard for assessing the prevalence of obesity. It is dependent both on height and weight (has been explained earlier). ii) Ponderal index It is dependent both on height and weight. It is defined as height (cm) divided by cube root of weight (kg).","pyqMatches":[{"year":"2014","no":638,"q":"WHO definition of abdominal obesity is ?","o":["Waist - hip ratio > 0.80 in females","Waist - hip ratio > 0.85 in females","Waist - hip ratio > 0.90 in females","Waist - hip ratio > 0.95 in females"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2152, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 106, '{"id":2152,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":106,"q":"Commonly used long bone for identification ?","o":["Femur","Radius","Ulna","Humerus"],"a":0,"e":"Ans. is ''a'' i.e., Femur Stature can be calculated from the length of long bones and used for identification. Femur and tibia give more accurate values compared to humerus and radius Stature is determined in the dismembered body (skeletal remains) by :","pyqMatches":[{"year":"2014","no":656,"q":"Commonly used long bone for identification ?","o":["Femur","Radius","Ulna","Humerus"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2153, 'Forensic Medicine', 'Injuries & Wounds', 'Hard', 'Forensic_Medicine', 107, '{"id":2153,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Hard","source":"Forensic_Medicine","sourceNo":107,"q":"Soft friable extradural hematoma with honeycomb appearance seen in autopsy in cases of death due to?","o":["Coagulopathy","Thermal injury","Post mortem trauma","None of the above"],"a":1,"e":"Ans. is ''b'' i.e., Thermal injury When the head is exposed to intense heat, sufficient to cause charring of the skull, heat hematomas occur. They have the appearance like extradural hemorrhage, but signs of injury blunt force do not accompany it. It consists of soft friable clot of light chocklate colour and may be pink, if blood contains CO. The clot has honeycombed appearance due to bubbles of steam produced by heat. Thickness - 11/2 to 15 mm and volume 120 ml. Thus the findings described in the question have typical appearance secondary to excess heat as seen in thermal injuries due to burns.","pyqMatches":[{"year":"2014","no":665,"q":"Soft friable extradural hematoma with honeycomb appearance seen in autopsy in cases of death due to?","o":["Coagulopathy","Thermal injury","Post mortem trauma","None of the above"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2154, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 108, '{"id":2154,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":108,"q":"Which of the gustafson''s parameter is the most accurate ?","o":["Attrition","Periodontosis","Root resorption","Transperency of the tooth"],"a":3,"e":"Ans. is ''d'' i.e., Trnasperency of the tooth Age from teeth after 20 years Teeth eruption is useful for age estimation upto about 18 years, beyond which it is just a guess work. The methods used are :? A) Gustafson''s method : Useful only in persons older than 21 years of age, depending on the physiological changes in each of the dental tissues.","pyqMatches":[{"year":"2014","no":654,"q":"Which of the gustafson''s parameter is the most accurate ?","o":["Attrition","Periodontosis","Root resorption","Transperency of the tooth"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2155, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 109, '{"id":2155,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":109,"q":"Maximum soft tissue bruising in neck is seen in -","o":["Strangulation","Hanging","Burking","Smothering"],"a":0,"e":"Ans. is ''a'' i.e., Strangulation As manual strangulation (throttling) is among the most violent form of asphyxia, hyoid fracture and other injury to neck structures is more common.","pyqMatches":[{"year":"2014","no":675,"q":"Maximum soft tissue bruising in neck is seen in","o":["Strangulation","Hanging","Burking","Smothering"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2156, 'Forensic Medicine', 'Medical Jurisprudence', 'Easy', 'Forensic_Medicine', 110, '{"id":2156,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":110,"q":"Constitution by which we can force people on hunger strike to eat is ?","o":["Article 21","Article 35","Article 48","Article 52"],"a":0,"e":"Ans. is ''a'' i.e., Article 21 Indian constitution (Article 21) ensures right to life; there is no equivalent right to die. Since Indian constitution is supreme, force feeding in hunger strikers is lawful in India.","pyqMatches":[{"year":"2014","no":639,"q":"Constitution by which we can force people on hunger strike to eat is ?","o":["Article 21","Article 35","Article 48","Article 52"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2157, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 111, '{"id":2157,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":111,"q":"Following is false regarding the bullet entry wound in skull ?","o":["Punched in hole in outer table","Inner table shows bevelling surface","No pieces of bone are present in the bullet track","Wound is funnel shaped with the funnel opening in the direction in which the bullet is travelling"],"a":2,"e":"Ans. is ''c'' i.e., No pieces of bone are present in the bullet track Firearm/bullet wounds in the skull Wound of entrance shows a punched in (clean) hole in the outer table. Cone shaped bone is detached from the inner table forming a crater that is larger than the hole of the outer table and shows beveling (sloping surface). Fissured fractures are seen radiating from the defect. Irregular lacerations may be seen involving the leptomeninges. Pieces of bone from the wound of entry are often driven into the cranial cavity and may establish the bullet track. At the point of exit a punched out opening is produced in the inner table and beveled opening in the outer table. The wound is funnel shaped with the funnel opening in the direction in which the bullet is travelling both in entrance and exit wound. The exit wound is larger due to deformity and tumbling of the bullet after entering the skull.","pyqMatches":[{"year":"2014","no":671,"q":"Following is false regarding the bullet entry wound in skull ?","o":["Punched in hole in outer table","Inner table shows bevelling surface","No pieces of bone are present in the bullet track","Wound is funnel shaped with the funnel opening in the direction in which the bullet is travelling"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2158, 'Forensic Medicine', 'Sexual Offences', 'Easy', 'Forensic_Medicine', 112, '{"id":2158,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":112,"q":"Frigidity is ?","o":["Inability to initiate sexual arousal in males","Inability to initiate sexual arousal in females","Inability to initiate and maintain sexual arousal in males","Inability to initiate and maintain sexual arousal in females."],"a":3,"e":"Ans. is ''d'' i.e., Inability to initiate and maintain sexual arousal in females Frigidity : Inability to initiate and maintain sexual arousal in females.","pyqMatches":[{"year":"2014","no":687,"q":"Frigidity is ?","o":["Inability to initiate sexual arousal in males","Inability to initiate sexual arousal in females","Inability to initiate and maintain sexual arousal in males","Inability to initiate and maintain sexual arousal in females."],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2159, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 113, '{"id":2159,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":113,"q":"Which of the following teeth erupt earlier in the upper jaw ?","o":["Central incisor","Lateral incisor","Canine","First molar"],"a":1,"e":"Ans. is b'' i.e., Lateral incisor","pyqMatches":[{"year":"2014","no":655,"q":"Which of the following teeth erupt earlier in the upper jaw ?","o":["Central incisor","Lateral incisor","Canine","First molar"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2160, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 114, '{"id":2160,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":114,"q":"Fencing attiude of the dead bodies is caused by ?","o":["Ciagulation of proteins","Emulsification of fact","Exposure to excess cold","Electric shock"],"a":0,"e":"Ans. is ''a'' i.e., Coagulation of proteins Pugilistic attitude(boxing/fencing/defence attitude) It is heat stiffening caused by denaturation and coagulation of proteins. It is indicative of exposure to intense heat. There is flexion at all joints and ?clawing of fingers. This phenomenon occurs both in antemortem and postmortem burns.","pyqMatches":[{"year":"2014","no":666,"q":"Fencing attiude of the dead bodies is caused by ?","o":["Ciagulation of proteins","Emulsification of fact","Exposure to excess cold","Electric shock"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2161, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 115, '{"id":2161,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":115,"q":"Lucid interval may be seen in ?","o":["Intracerebral hemorrhage","Alcohol intake","Insanity","Subdural hemorrhage"],"a":2,"e":"Ans. is `e'' i.e., Insanity Lucid interval is seen in insanity and epidural haemorrhage. Lucid interval is a state of consciousness between two episodes of unconsciousness in subacute/chronic epidural haemorrhage. It is significant that during this period (lucid interval), the person can : (i) Make a valid will, (ii) Can give valid evidence, and (iii) Is legally responsible for act done (civil/criminal). Lucid interval is also seen in insanity, i.e. the period of sanity between two phases of insanity.","pyqMatches":[{"year":"2014","no":686,"q":"Lucid interval may be seen in ?","o":["Intracerebral hemorrhage","Alcohol intake","Insanity","Subdural hemorrhage"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2162, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 116, '{"id":2162,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":116,"q":"Alkaline diuresis is treatment of choice in poisoning with ?","o":["Benzodiazepine","Barbiturates","Dhatura","Morphine"],"a":1,"e":"Ans. is ''b'' i.e., Barbiturate poisoning Elimination of poison from circulation can be by following methods :? A) Forced diuresis with or without alteration of urinary pH Diuresis and ion trapping via alteration of urinary pH may prevent the renal reabsorption of poisons that under go excretion by glomerular filteration and active tubular secretion. Forced diuresis may be of following types :? 1) Alkaline diuresis : Poisons which are trapped and excreted in alkaline urine are barbiturates (phenobarbitone), chlorpropamide, diffunisol, sulfonamides and salicylates. 2) Acid diuresis : It is done for amphetamines, cocaine, strychnine, phencyclidine, quinidine, quinine, chloroquine, TCA and tocainide. 3) Saline diuresis : It is useful for alcohol, thallium, bromide, lithium, fluoride, chromium, potassium and isoniazide. B) Extracorporal removal therapies These are peritoneal dialysis, hemodialysis, hemoperfusion (resin or charcol), hemofiltration, plasmapheresis and exchange transfusion. Commonly used procedures are :? 1) Haemodialysis : It is useful in poisoning with alcohol (ethanol and methanol), aspirin (salicylates), acetone, atenolol, acetaminophen, barbiturates (phenobarbitone), bromide, boric acid, chloral hydrate, ethylene glycol, fluoride, lithium, trivalent arsenic, procainamide, theophylline, thiocyanate, sodium chlorate and sotalol. Hemodialysis is not useful in copper sulphate, benzodiazepines, organophosphates, kerosine and digitalis poisonings. In all poisonings, where hemodialysis is indicated peritoneal dialysis is also used with one more indication of mercury poisoning. 2) Hemoperfusion (chorcol or resin) : It is used in acetaminophen, barbiturates carbamazepine, chloral hydrate, caffeine, CC14, chloramphenical, phenytoin, procainamide, salicylates, theophylline, valproate, dapsone and methotrexate.","pyqMatches":[{"year":"2014","no":711,"q":"Alkaline diuresis is treatment of choice in poisoning with ?","o":["Benzodiazepine","Barbiturates","Dhatura","Morphine"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2163, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 117, '{"id":2163,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":117,"q":"Phossy jaw is caused by ?","o":["White phosphorus","Red Phosphorus","Arsenic","Antimony"],"a":0,"e":"Ans. is ''a'' i.e., White Phosphorus Phossy jaw is caused by phosphorus poisoning. All phosphorus poisoning are caused by white (yellow) phosphorus (Red phosphorus is nontoxic). Phosphorus poisoning Phosphorus is a protoplasmic poison affecting cellular oxidation and causing anoxic necorbiosis, classically affecting liver. It increases fat deposition and inhibits glycogen deposition in liver. It is used in fire works (Diwali poisoning) and as rat poison. Lethal dose is 60-120 mg. Phosphorus occurs in two forms :? 1) White/yellow phosphorus : It is white, and becomes yellow on exposure to air. It is translucent, waxy, luminous and crystalline cylinders. It has garlic like odor. It is insoluble in water and luminous in dark. Its fumes show phosphorescence. 2) Red phosphorus : It is reddish brown, inert, odourless and tasteless. It is nontoxic (thus poisoning occurs only due to white phosphorus). It is put on the sides (striking surface) of match box (along with powdered galss). Acute poisoning It has following stages : i) 1st Stage (GI irritation) : There is nausea, vomiting, diarrhea and garlic odor This stage lasts for 8 hours to 3 days garlic odor. This stage lasts for 8 hours to 3 days. ii) 2nd Stage (Asymptomatic) : This stage lasts for 3 days. iii) 3rd Stage : There is liver and kidney damage due to absorbed phosphorus. Initially liver is enlarged due to acute fatty infiltration. Later liver shruks due to necrosis, i.e. acute yellow atrophy. Chronic poisoning Toothache is the first symptom which is associated with loosening of teeth, necrosis of gums and osteomyelitis of jaw. Therefore chronic phosphorus poisoning is also know as phossy jaw (or glass jaw). Postmortem appearance There is garlic odor. Viscera and stool glow in dark (due to luminosity). To preserve luminosity, viscera are preserved in saturated saline solution. Rectified spirit is not used as it causes loss of luminosity.","pyqMatches":[{"year":"2012","no":638,"q":"Phossy jaw is caused by ?","o":["White phosphorus","Red Phosphorus","Arsenic","Antimony"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":713,"q":"Phossy jaw is caused by ?","o":["White phosphorus","Red Phosphorus","Arsenic","Antimony"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2164, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 118, '{"id":2164,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":118,"q":"Presence of spiral grooves in the barrel of weapon is referred to as ?","o":["Rifling","Incendiary","Cocking","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Rifling Type of firearm weapons Bore (caliber) is the inner diameter of barrel. Based on inside of barrel (i.e., bore), the firearm weapons are divided into:?","pyqMatches":[{"year":"2014","no":674,"q":"Presence of spiral grooves in the barrel of weapon is referred to as ?","o":["Rifling","Incendiary","Cocking","None of the above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2165, 'Forensic Medicine', 'Sexual Offences', 'Moderate', 'Forensic_Medicine', 119, '{"id":2165,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":119,"q":"Evidence not used in rape?","o":["Semen in vagina","Semen on clothes","Presence of smega bacilli in vagina","Presence of smegma under prepuce"],"a":3,"e":"Ans. is ''d'' i.e., Presence of smegma under prepuce Examination in a case of rape A. Examination of victim Victim cannot be examined without written informed consent. Informed written consent should be obtained if the age of victim is above 12 years. If she is less than 12 years of age or if she is mentally unsound, the written consent of parent/guardian should be taken (Sec. 90 IPC). Victim (female) should be examined by or under supervision of a female RMP (Sec. 53(2) CrPC). Finding which are suggestive of rape are :-","pyqMatches":[{"year":"2014","no":693,"q":"Evidence not used in rape?","o":["Semen in vagina","Semen on clothes","Presence of smega bacilli in vagina","Presence of smegma under prepuce"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2166, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 120, '{"id":2166,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":120,"q":"Which IPC includes vitriolage ?","o":["318","319","320","321"],"a":2,"e":"Ans. is ''c'' i.e., 320 Vitriolage is a potential cause of permanent disfigurement of face and thus is covered under grevious hurt and so comes under IPC","pyqMatches":[{"year":"2014","no":645,"q":"Which IPC includes vitriolage ?","o":["318","319","320","321"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2167, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 121, '{"id":2167,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":121,"q":"Which type of neuropathy is seen in arsenic poisoning ?","o":["Symmetric peripheral motor neuropathy","Asymmetrical peripheral motor neuropathy","Symmetrical peripheral sensory neuropathy","Asymmetrical peripheral sensory neuropathy"],"a":3,"e":"Ans. is ''d'' i.e., Asymmetrical peripheral sensory neuropathy Neurological manifestations of arsenic poisoning Headache, vertigo, hyperthermia, tremors, convulsions, coma, general paralysis. Peripheral neuropathy that is more sensory than motor occurs in asymmetric distal stocking glove distribution after one to two weeks of acute or chronic exposure.","pyqMatches":[{"year":"2014","no":714,"q":"Which type of neuropathy is seen in arsenic poisoning ?","o":["Symmetric peripheral motor neuropathy","Asymmetrical peripheral motor neuropathy","Symmetrical peripheral sensory neuropathy","Asymmetrical peripheral sensory neuropathy"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2168, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 122, '{"id":2168,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":122,"q":"Incised looking laceration is seen at ?","o":["Forehead","Hand","Thorax","Abdomen"],"a":0,"e":"Ans. is ''a'' i.e., Forehead LACERATIONS (Tear or Rupture) Lacerations are tears or splits of skin, mucous membrane and underlying tissue (e.g., muscle or internal organs). Lacerations are produced by application of blunt force to broad area of the body, which crush or stretch tissues beyond the limits of their elasticity. Localized portions of tissue are displaced by the impact of the blunt force, which sets up traction forces and causes tearing of tissues. Features of lacerations are :? i) Hair and hair bulb, nerves and blood vessels are crushed → There may be paralysis (nerve crushed) and hemorrhage is not pronounced (blood vessels crushed). ii) Site of injury is the site of impact. iii) Shape of injury is irregular, margins are irregular and contused/abraded and show tags of tissue. iv) Size of injury does not corresponds to impacting surface. There are following types of laceration : ? 1) Split laceration : Splitting occurs by crushing of skin between two hard objects. Blunt force on areas where the skin is close to rigid structures like bone with scanty subcutaneous tissue, may produce a wound that by linear splitting of tissue may look like incised wound, i.e., incised like or incised looking wound. Examples of such area are scalp, eye brows, cheek bones (zygomatic), lower jaw, iliac crest, perineum and skin. A wound produced by a fall on knee or elbow with limb flexed and by a sharp stone also simulates incised wound. 2) Strech lacerations : Overstretching of the skin, if it is fixed, will cause laceration, for example, by kicking, sudden deformity of bone occurs after fracture, making it compound. 3) Avulsion (shearing laceration) : An avulsion is a laceration produced by sufficient force (shearing force) delivered at an acute angle to detach (tear off) a portion of a traumatized surface or viscus from its attachment, the shearing and grinding force by a weight. Flaying is type of avulsion in which shearing and grinding force by weight (such as of lorry wheel passing over a limb) may produce avulsion (separation of skin from underlying tissue/degloving of a large area). 4) ears : Tears of the skin and tissues can occur from imact by a against irregular or semi-sharp objects, such as door handle of a car. This is another form of overstretching. 5) Cut laceration : Cut lacerations may be produced by a heavy sharp edged instrument.","pyqMatches":[{"year":"2012","no":611,"q":"Incised looking laceration is seen at ?","o":["Forehead","Hand","Thorax","Abdomen"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":683,"q":"Incised looking laceration is seen at ?","o":["Forehead","Hand","Thorax","Abdomen"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2169, 'Forensic Medicine', 'Medical Jurisprudence', 'Easy', 'Forensic_Medicine', 123, '{"id":2169,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":123,"q":"How much is punishment for sex determination ?","o":["3 years","5 years","7 years","9 years"],"a":0,"e":"Ans. is ''A'' i.e., 3 years Since the question is about punishment for sex determination not repeat offence of sex determination answer will be 3 years The families of a pregnant woman who ask for sex determination are also liable to be punished. Not adhering to the provisions of this act could warrant punishment in the form of up to 3 years imprisonment and up to Rs 10,000 fine, and on repeat offence up to 5 years imprisonment and up to Rs 50,000 fine. The name of the registered practitioner would be removed from the state council for 5 years if guilty and permanently if repeat offence is committed under section 23 of the act.","pyqMatches":[{"year":"2014","no":640,"q":"How much is punishment for sex determination ?","o":["3 years","5 years","7 years","9 years"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2170, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 124, '{"id":2170,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":124,"q":"Pre auricular sulcus is a part of ?","o":["Humerus","Femur","Pelvis","Skull"],"a":2,"e":"Ans. is `c'' i.e., Pelvis Preauricular sulcus is used for determination of sex. It is more frequent, broad and deep in female pelvis. There is attachment of anterior sacroiliac ligament.","pyqMatches":[{"year":"2014","no":664,"q":"Pre auricular sulcus is a part of ?","o":["Humerus","Femur","Pelvis","Skull"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2171, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 125, '{"id":2171,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":125,"q":"What is the upper permissible limit of alcohol allowed while driving in India -","o":["20 mg%","30 mg%","40 mg%","50 mg%"],"a":1,"e":"Ans. is ''b'' i.e., 30 mg% The statutory limit of alcohol level in blood in India while driving beyond which driving is considered as crime is 30 mg%. It is covered under S. 185 Motor Vehicle Act 1988. The punishment for first offence is fine upto Rs. 2000/- or 6 months of imprisonment or both and for second or subsequent offence fine upto Rs. 3000/- or imprisonment upto 2 years or both.","pyqMatches":[{"year":"2014","no":715,"q":"What is the upper permissible limit of alcohol allowed while driving in India","o":["20 mg%","30 mg%","40 mg%","50 mg%"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2172, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 126, '{"id":2172,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":126,"q":"What is the level of alcohol in blood beyond which person is condidered intoxicated ?","o":["40 mg%","80 mg%","120 mg%","140 mg%"],"a":3,"e":"Ans. is ''d'' i.e., 140 mg% All individuals with a blood alcohol level of 140 mg% are considered intoxicated to the point where they cannot deal with unusual, emergency or non - customary problems.","pyqMatches":[{"year":"2014","no":716,"q":"What is the level of alcohol in blood beyond which person is condidered intoxicated ?","o":["40 mg%","80 mg%","120 mg%","140 mg%"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2173, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 127, '{"id":2173,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":127,"q":"The pathways followed by corrosive acids in stomach is called ?","o":["Curling ulcer","Cushing ulcer","Magenstrasse","None"],"a":2,"e":"Ans. is ''c'' i.e., Magenstrasse Magenstrasse is the term applied to the pathway acidic agents follow in stomach. The pathway of acids and alkalis in food filled stomach starts along the lesser curvature of the stomach and leads to the pylorus, which explains the location of greatest damage in food filled stomach. Stomach without food have significant injury in the lower half of two thirds and may have sparing of fundus.","pyqMatches":[{"year":"2014","no":717,"q":"The pathways followed by corrosive acids in stomach is called ?","o":["Curling ulcer","Cushing ulcer","Magenstrasse","None"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2174, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 128, '{"id":2174,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":128,"q":"Chocolate Brown postmortem staining is seen in ?","o":["KCl poisoning","Opium poisoning","H2S poisoning","Cyanide poisoning"],"a":0,"e":"Ans. is ''a'' i.e., KCl Poisoning","pyqMatches":[{"year":"2014","no":718,"q":"Chocolate Brown postmortem staining is seen in ?","o":["KCl poisoning","Opium poisoning","H2S poisoning","Cyanide poisoning"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2175, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 129, '{"id":2175,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":129,"q":"Immersion syndrome occurs due to ?","o":["Vagal inhibition","Vagal Stimulation","Sympathetic stimulation","Sympathetic inhibition"],"a":0,"e":"Ans. is ''a'' i.e., Vagal inhibition Types of drowning Drowning is classified as (1) typical and (2) atypical.","pyqMatches":[{"year":"2014","no":694,"q":"Immersion syndrome occurs due to ?","o":["Vagal inhibition","Vagal Stimulation","Sympathetic stimulation","Sympathetic inhibition"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2176, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 130, '{"id":2176,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":130,"q":"What of the following is seen in fresh water drowning ?","o":["Hypovolemia","Hemoconcentration","Hyperkalemia","Hypernatremia"],"a":2,"e":"Ans. is ''c'' i.e. Hyperkalemia","pyqMatches":[{"year":"2014","no":695,"q":"What of the following is seen in fresh water drowning ?","o":["Hypovolemia","Hemoconcentration","Hyperkalemia","Hypernatremia"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2177, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 131, '{"id":2177,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":131,"q":"What is the proof of eyes being open for few hours after death ?","o":["Kevokian sign","Tache noir","Both of the above","None of the above"],"a":1,"e":"Ans. is ''b'' i.e., Tache noir If the eye lids are open for a few hours after death, a film of cell debris and mucous forms two yellow triangles on the sclera on either side of the iris , which become brown and then black called tache noir withing 3 - 4 hours.","pyqMatches":[{"year":"2014","no":698,"q":"What is the proof of eyes being open for few hours after death ?","o":["Kevokian sign","Tache noir","Both of the above","None of the above"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2178, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 132, '{"id":2178,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":132,"q":"Majority is obtained by a person under court guardianship by age of ?","o":["19 years","20 years","21 years","22 years"],"a":2,"e":"Ans. is ''c'' i.e., 21 years A person attains majority on completion of 18 years. However if a person is under the guardianship of court, he attains majority after 21 years (Indian Majority Act 1875).","pyqMatches":[{"year":"2014","no":649,"q":"Majority is obtained by a person under court guardianship by age of ?","o":["19 years","20 years","21 years","22 years"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2179, 'Forensic Medicine', 'Medical Jurisprudence', 'Moderate', 'Forensic_Medicine', 133, '{"id":2179,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":133,"q":"Which method is not used for autopsy ?","o":["Virchow","Rokitansky","Lettulle","Thomas"],"a":3,"e":"Ans. is ''d'' i.e., Thomas Methods of removal of organs Virchow''s technique - organs are removed one by one. Cranial cavity is exposed first, followed by thoracic, cervical & abdominal organs. Rokitansky''s technique - It involves in situ dissection in part, combined with en block removal. Lettulle''s technique - Cervical, thoracic, abdominal & pelvic organs are removed en masse & dissected as organ block.","pyqMatches":[{"year":"2014","no":699,"q":"Which method is not used for autopsy ?","o":["Virchow","Rokitansky","Lettulle","Thomas"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2180, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 134, '{"id":2180,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":134,"q":"Spalding sign is seen in ?","o":["Drowning","Mummification","Maceration","Starvation"],"a":2,"e":"Ans. is ''c'' i.e., Maceration Dead born : A deadborn child is one which has died in utero and shows one of the following signs after it is completely born :? 1) Rigor mortis : Rigor mortis may occur in dead fetus before birth or at birth. 2) Maceration : Maceration is a process of aseptic autolysis. It occurs when a dead fetus remains in the uterus for 3-4 days surrounded by liquor amnii but with exclusion of air. Skin slippage is the earliest sign (occurs within 12 hours). There is gas in the great vessels and chambers of heart (Robert''s sign). Except for lung and uterus, which remain unchanged for a long time, all other organs become soft, oedematous and loose there morphology. The one important radiological sign suggestive of maceration is ''Spaulding''s sign'' i.e. skull bones override each other. The smell is somewhat rancid. 3) Putrefaction (decomposition) : If the membranes are ruptured after death of fetus and air gains entry into liquor amnii, fetus undergoes putrefaction instead of maceration. Body is greenish, foul smelling and bloated. 4) Mummification : It results when there is deficient blood supply, scanty liquor and no air enters uterus. Body is thin, shrivelled dark brown and emitting smell like rotten cheese.","pyqMatches":[{"year":"2014","no":700,"q":"Spalding sign is seen in ?","o":["Drowning","Mummification","Maceration","Starvation"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2181, 'Forensic Medicine', 'Thanatology', 'Moderate', 'Forensic_Medicine', 136, '{"id":2181,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":136,"q":"Following is not true about adipocere formation ?","o":["It is a modification of putrefaction","It is developed in presence of air","It occurs in dead bodies lying in water","Body has an offensive sweet smell"],"a":1,"e":"Ans. is ''b'' i.e., It is developed in presence of air Adipocere formation (saponification). Adipocere is a modification of putrefaction, which occurs in the absence of air. That is when there is excessive moisture (humidity) and warnth (warm temperature), but absence of air i.e. warm humid climate, normal putrefaction does not occur, rather saponification occurs. Thus adipocese formation occurs in dead bodies which are lying in water (immered in water) or burned in damp lay soil. Saponification (adipocer formation) is the conversion of dead body into soft, fatty waxy substance due to conversion of unsaturated liquid fats to saturated solid fats under the influence of intrinsic lipase and lecithinase produced by Cl. perfringens. The process involves gradual hydrolysis and hydrogenation of body fats into higher fatty acids which combine with calcium and ammonium ions to form insoluble soaps. Ultimately, palmitic, oleic, stearic and hydroxystearic acids are formed, mixture of these is known as adipocere. Adipocere formation starts in subcutaneous fat and is marked in areas having excessive fat, eg. cheeks, female breast, buttocks and abdomen. Slowly the whole body including muscles and internal viscera change into adipocere. Adipocere has offensive or sweetish smell, however in early stages, smell is ammonical. Body is converted into soft, waxy and brittle substance, it floats on water, it can be cut easily, it dissolves in alcohol and ethers, and it melts on heating. Facial features and injuries on body are well preserved, thus identfication of body and determination cause of death (in case of injury) are possible. Normally adipocere formation requires 3 weeks to upto 3 to 6 months. However shortest recorded period in india is 3 days 22 hours. In india, it has been observed to begin within 4-5 days. Adipocere may persist for years or decades. Adipocere does not occur in foetus less than 7 month''s. Medicolegal importance : (i) Identification of body (facial features are preserved), (ii) cause of death (injury marks are preserved), (iii) time since death can be estimated.","pyqMatches":[{"year":"2014","no":702,"q":"Following is not true about adipocere formation ?","o":["It is a modification of putrefaction","It is developed in presence of air","It occurs in dead bodies lying in water","Body has an offensive sweet smell"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2182, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 137, '{"id":2182,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":137,"q":"Legal age by which fetus is capable of independent existence is ?","o":["240 days","230 days","220 days","210 days"],"a":3,"e":"Ans. is ''d'' i.e., 210 days Viability means the physical ability of a foetus to lead a separate existence after birth apart from its mother, by virtue of a certain degree of development. A child is viable after 210 days (7 months) of intrauterine life, and in some cases after 180 days (6 months) but in most of these cases fetus is immature. Full term mature infant show :- Length (crown-heel length) 48-52 cm, head circumference 30-35 cm. Ossification center at lower end of femur (appears at the end of 9 months or just before birth) and Ossification center of cuboid and upper tibia may also present (Note : some ossification centers are also present, but they appear before the attainment of viability so their presence does not have importance. These are (i) Clavicle, mandible, ribs vertebra → at the end of 2nd month, (ii) Calcaneum(os calcis) and manubrium sterni → at the end of 5th month and (iii) Sternum → at the end of 6 month). Other center which appears at attainment of viability is primary ossificaion center of talus which appears at the end of 7th month.","pyqMatches":[{"year":"2014","no":696,"q":"Legal age by which fetus is capable of independent existence is ?","o":["240 days","230 days","220 days","210 days"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2183, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 138, '{"id":2183,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":138,"q":"Trousseau sign positive in which poisoning ?","o":["Citric acid","Oxalic acid","Acetic acid","Carbolic acid"],"a":1,"e":"Ans. is ''b'' i.e., Oxalic acid Trousseou''s sign and chovstek''s sign are seen in hypocalcemia. Oxalic acid poisoning can cause hypoclacemia. Oxalic acid It is also known as salt of sorrel or acid of sugar. It is used to erase writing, as bleaching agent and in calico printing. It occurs in leaves of rhubarb. Local effects : Oxalic acid rarely damages the skin but readily corrode the mucus membrane of digestive tract. Systemic : (i) Shock : Large doses can cause death from shock; (ii) Hypocalcemia : Oxalic acid readily combines with calcium to cause hypocalcemia, which may present as tingling, numbness, twitching, tetany, and convulsions, (iii) Renal damage : It is due to oxaluria which may cause tubular necrosis. Antidote : Any calcium preparation (e.g. calcium gluconate/chloride, lime water, suspension of chalk) which converts poison into insoluble calcium oxalate is an antidote for oxalate poisoning.","pyqMatches":[{"year":"2014","no":720,"q":"Trousseau sign positive in which poisoning ?","o":["Citric acid","Oxalic acid","Acetic acid","Carbolic acid"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2184, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 139, '{"id":2184,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":139,"q":"Tactile hallucination seen in abuse with ?","o":["Heroine","Cocaine","Cannabis","Alcohol"],"a":1,"e":"Ans. is ''b'' i.e., Cocaine Magnan''s symptoms is tactile hallucination (formication) i.e. feeling of bugs crawling under the skin is seen with cocaine abuse/ poisoning. Cocaine Cocaine is an alkaloid derived from the Coca bush, Erythrexylum CoCa. It was the first local anaesthetic which was used clinically. Toxicity of cocaine may be : ? A) Acute toxicity : - Acute cocaine intoxication is characterized by : ? 1) Sympathetic hyperactivity : - Tachycardia, hypertension, mydriasis, sweating, nausea & vomiting. 2) Hypomanic state : - Increased psychomotor activity, grandiosity, elation, hypervigilance, Increased speech output. B) Chronic overuse : - Chronic overuse can cause : ? 1) Psychotic episodes (Cocaine psychosis) : - Persecutory delusions with tactile hallucinations (formination). Tactile hallucinations are manifested as bugs crawling under the skin → Cocaine bugs or magnan''s symptoms. 2) Other : - Anxiety reaction, compulsive behavior, delirium and delusional disorders. 3) Black pigmentation of tongue and teeth A combination of cocaine and heroin taken by injection is called speed ball speed ball.","pyqMatches":[{"year":"2014","no":721,"q":"Tactile hallucination seen in abuse with ?","o":["Heroine","Cocaine","Cannabis","Alcohol"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2185, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 140, '{"id":2185,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":140,"q":"Counter coup injury seen in when ?","o":["Moving head is suddenly decelerated","Stationery head is suddenly accelerated","Fall of heavy object on head","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Moving head is suddenly decelerated Countrecoup injury is caused when moving head is suddenly decelerated by hitting a firm surface. It can either be a subdural or subarachnoid hemorrhage. Brain injuries Coup injury is defined as the injury of skull and/or brain at the site of impact, e.g. a blow on forehead, resulting in fracture of frontal bone and injury or haemorrhage in frontal lobe. Contre coup injury is defined as an injury to the skull or brain, on opposite (contralateral) side of the area of impact. Cerebral concussion (stunning) occurs due to head trauma and is characterized by gross physiological disturbance of brain without any anatomical damage. There is sudden loss of consciousness with a tendency to spontaneous recovery. The condition is more severe when damage is caused to the moving head (decceleration injury) than when it results from blows to skull. Recovery from concussion is often followed by retrograde amnesia.","pyqMatches":[{"year":"2014","no":684,"q":"Counter coup injury seen in when ?","o":["Moving head is suddenly decelerated","Stationery head is suddenly accelerated","Fall of heavy object on head","None of the above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2186, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 141, '{"id":2186,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":141,"q":"Most common finger print type is ?","o":["Loops","Whorls","Composite","Arches"],"a":0,"e":"Ans. is ''a'' i.e., Loops Dactylography / DermatogIvphics / Calton system / Finger prints Finger prints are present from birth both on epidermis and dermis, remain constant through out life and can''t be altered without destroying true skin. Finger print pattern is absolutely individual i.e. no two hands are entirely alike, not even identical twins. That''s why, it is best (most sensitive and most specific) and most reliable method of identification (Quetelet''s rule of biological variation). DNA finger printing may be same in monozygotic twins. The pattern is neither inherited nor identical in any two persons. So the paternity cannot be proved through finger print patterns. However, paternity can be proved by DNA finger printing. Loops (67% most common) > whorls (25%) > arches (7%) > composite (2% least common) are four main types of pattern. It is accepted that chances of 2 finger prints matching 16 ridge characteristic are infinitely small (Parikh''s). In practice 8 - 16 (Reddy) / 16 - 20 (Seth, Simpson) points of fine comparision are accepted as proof of identity. Locard''s poroscopy method is study of microscopic pores, formed by mouths of ducts of subepidermal sweat gland present on ridges of fingers. These pores are permanent, remain un changed during life and are very useful when only fragments offingerprints are available. Each milimeter contains 9 - 18 pores. Criminals may attempt to multilate finger prints by applying CO2 snow, corrosive agents, burns or eroding against hard surface. But these manners do not destroy finger prints permanently unless true skin is completely de​stroyed.","pyqMatches":[{"year":"2014","no":658,"q":"Most common finger print type is ?","o":["Loops","Whorls","Composite","Arches"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2187, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 142, '{"id":2187,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":142,"q":"Back of 10 - 14 years old contributes how much percentage to total body surface area ?","o":["13%","15%","16%","19%"],"a":2,"e":"Ans. is ''c'' i.e., 16%","pyqMatches":[{"year":"2014","no":668,"q":"Back of 10 - 14 years old contributes how much percentage to total body surface area ?","o":["13%","15%","16%","19%"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2188, 'Forensic Medicine', 'Medical Jurisprudence', 'Moderate', 'Forensic_Medicine', 143, '{"id":2188,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":143,"q":"Exception to the rule of professional secrecy is allowed under following circumstances except ?","o":["Court of law","Cases of suspected crime","In negligent suits","In interest of relatives"],"a":3,"e":"Ans. is ''d'' i.e., In interest of relatives Professional secrecy is an implied ethical and legal obligation (or contract), that the doctor will not divulge any thing he comes to know concerning patient during the course of his professional work. Doctor is liable to damages for its breech. However, it is justified in certain circumstances, to disclose information to proper authority, and this is known as privileged communication. It is defined as a communication made by doctor to a proper authority that has corresponding legal, social, and moral duties to protect the public. Privileged communication is made in certain circumstances where the doctor is justified in disclosing information about his patient. Such communication is regarded as privileged and is an exception to the general rule of professional secrecy between doctor and patient. Example are :? 1) In court of law : When asked by judge. 2) As compulsor duty : Every doctor has to give details of birth, death and communicable disease. 3) As a social duty : If health of a patient can cause danger to society, e.g. :- i) Railway engine driver being colour blind. ii) Bus driver being epileptic, drug addict or hypertensive. iii) Pilot having refractive errors. iv) Hotel waitor suffering from TB or being typhoid carrier. v) Swimming pool user suffering from STD (e.g. syphilis) or infectious disease. vi) Person suffering from STD or HIV infection likely to marry. vii) Cases of food poisoining. viii) Water pollution. 4) In cases of suspected crime. 5) In self interest, both in civil and criminal suits by patient. 6) When a servant is sent by master. 7) In negligent suits when doctor is employed by opposite party to cross-examine patient who filed the suit. 8) In insurance reports, he can report any disease found. But he should not answer queries of insurance company or solicitor without the patient consent. 9) In the interest of patient : If patient is not taking proper care, details can be communicated to the relatives.","pyqMatches":[{"year":"2014","no":652,"q":"Exception to the rule of professional secrecy is allowed under following circumstances except ?","o":["Court of law","Cases of suspected crime","In negligent suits","In interest of relatives"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2189, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 144, '{"id":2189,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":144,"q":"Pupil dilatation is seen in poisoning with -","o":["Dhatura","Ethyl alcohol","Brium carbonate","All the above"],"a":3,"e":"Ans. is ''d'' i.e., All the above Poisoning of the following is associated with dilated pupils Atropine Tricyclic antidepressants Phenothiazines Dhatura Ethyl alcohol Barium carbonate","pyqMatches":[{"year":"2014","no":722,"q":"Pupil dilatation is seen in poisoning with","o":["Dhatura","Ethyl alcohol","Brium carbonate","All the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2190, 'Forensic Medicine', 'Miscellaneous', 'Moderate', 'Forensic_Medicine', 145, '{"id":2190,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":145,"q":"Tattooing in old decomposed body can be visualized by use of all except ?","o":["H2O2 3%","Gamma rays","Infrared photography","Examination with magnifying glass"],"a":1,"e":"Ans. is ''b'' i.e., Gamma rays Latent tattoo marks are faded marks and they can be visualized by Use of ultraviolet light Infrared photograpy Rubbing the part and examining under magnifying glass If tattoo marks are obscured by decomposition they can be visualized by treating with 3 % H2O2. Tatto marks can be developed by treating the skin by 0.5% caustic potash. Histopathology of local lymph nodes for pigment.","pyqMatches":[{"year":"2014","no":659,"q":"Tattooing in old decomposed body can be visualized by use of all except ?","o":["H2O2 3%","Gamma rays","Infrared photography","Examination with magnifying glass"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2191, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 146, '{"id":2191,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":146,"q":"Black gun powder composition ?","o":["Charcoal 60% + Potassium nitrate 20% + sulphur 20%","Charcoal 25% + Potassium nitrate 70% + sulphur 05%","Charcoal 15%+ Potassium nitrate 75% + sulphur 10%","Charcoal 65% + Potassium nitrate 20% + sulphur 15%"],"a":2,"e":"Ans. is ''c'' i.e., Charcoal 15% + Potassium nitrate 75% + sulphur 10% The classical gun powder is known as black powder, consists of charcol (15%), Sulphur (10%), and potassium nitrate (75%). Depending on fineness, the black gun powder is designated as FG, FFG, FFFG. etc. (F = fineness). Pyrodex is another gun powder with same components, but with different ratios. Black gun powder produces smoke, i.e. It is smoke producing powder. Smokeless powder, in addition to black powder, has nitrocellulose (single base), or nitrocellulose plus nitroglycerine (double base), or nitrocellulose plus nitroglycerine plus nitroguanidine (triple base). Semi smokeless powder has 80% black powder and 20% smokeless powder (nitrocellulose).","pyqMatches":[{"year":"2014","no":673,"q":"Black gun powder composition ?","o":["Charcoal 60% + Potassium nitrate 20% + sulphur 20%","Charcoal 25% + Potassium nitrate 70% + sulphur 05%","Charcoal 15%+ Potassium nitrate 75% + sulphur 10%","Charcoal 65% + Potassium nitrate 20% + sulphur 15%"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2192, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 147, '{"id":2192,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":147,"q":"Bone pearl appearance is seen in ?","o":["Electrical burns","Hydrocution","Strangulation","Throttling"],"a":0,"e":"Ans. is ''a'' i.e., Electrical burns Electric burns Electric burns are at times, also referred to as joule burns. Technically, joule burn is an endogenous burn, i.e. burns produced due to release of heat from the body, on application of electric current. Electric burns may be of following types :? 1) Contact burns : Due to contact with live wire. 2) Spark burns : Due to sparking of current, e.g. in loose electrical fitting. 3) Flash burns : Caused on being near the main power line, without actual contact. Burns result due to arcing of current from these lines. Characteristic features of electric burns are :? 1) There may be holes in clothes or shoes. 2) There is a wound of entry and wound of exit of electric current :- i. Entry wound : It is non-bleeding, thick, leathery, greyish white, depressed, hard and cauliflower like, known as crater formation. High voltage current may cause burns over large areas of skin, i.e. crocodile skin lesions. The skin may get coloured due to metallic pigment : green (in brass electrode), black (in iron electrode), blue (in copper electrode) and grey (in aluminium electrode). i. Exit wound : It is like a laceration and is bleeding. 3) Metals from electrode may melt and as small balls (current pearls) may be carried to tissue Calcium phosphate of bones may also melt may be carried to tissue. Calcium phosphate of bones may also melt and is radiologically seen as bone pearls (wax dripping). 4) Muscles show Zenker''s degeneration. Causes of death Commonest cause of death is ventricular fibrillation. Other causes include shock, cardiopulmonary arrest, cerebral anoxia, paralysis of respiratory muscles, and mechanical injuries due to fall.","pyqMatches":[{"year":"2014","no":669,"q":"Bone pearl appearance is seen in ?","o":["Electrical burns","Hydrocution","Strangulation","Throttling"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2193, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 148, '{"id":2193,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":148,"q":"Mummification is enhanced by ?","o":["Moist and hot air","Moist and cool air","Dry and hot air","Dry and cool air"],"a":2,"e":"Ans. is ''c'' i.e., Dry and hot air Mummification It is a modification of putrefaction, which occurs in the absence of moisture. That is when there is excess air and warmth but no moisture (humidity), i.e. hot dry and windy climate, mummification takes place in place of normal putrefaction. Thus mummification occurs in deserts, especially in summer and also in bodies buried in shallow grave in sandy soil. Mummification is characterized by dessication or drying of the dead body. There is drying, dehydration and shriveling of dead body. It proceeds from exterior to interior. Therefore first to be involved is skin, especially of exposed body parts like lips, nose tip, hands (fingers) and feet (toes). The skin is shrunken, contracted, dry, brittle, leathery, streched across bony prominences and rusty brown to black in color. Internal viscera also dry up, darken in color and blend with each other to form a single mass. Body emits smell like rotten cheese. Facial features and injuries are well preserved, thus identification of body and cause of death can be determined (like adipocere formation). Time required for mummification varies between 3 months - 2 years. If properly preserved, a mummified body can remain for years. Chronic arsenic or antimony poisoning favor mummification. Medicolegal importance : (i) Identification of body (facial features are preserved), (ii) cause of death (injury marks are preserved), (iii) time since death can be estimated.","pyqMatches":[{"year":"2014","no":703,"q":"Mummification is enhanced by ?","o":["Moist and hot air","Moist and cool air","Dry and hot air","Dry and cool air"],"a":2,"source":"NEET_2014_Paper.pdf"},{"year":"2016","no":646,"q":"Mummification is enhanced by ?","o":["Moist and hot air","Moist and cool air","Dry and hot air","Dry and cool air"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2014","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2194, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 149, '{"id":2194,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":149,"q":"Hyoid bone fracture most common occurs in ?","o":["Manual strangulation","Hanging","Smothering","Traumatic asphyxia"],"a":0,"e":"Ans. is ''a'' i.e., Manual strangulation As manual strangulation (throttling) is among the most violent form of asphyxia, hyoid fracture and other injury to neck structures is more common.","pyqMatches":[{"year":"2012","no":624,"q":"Hyoid bone fracture most common occurs in ?","o":["Manual strangulation","Hanging","Smothering","Traumatic asphyxia"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":676,"q":"Hyoid bone fracture most common occurs in ?","o":["Manual strangulation","Hanging","Smothering","Traumatic asphyxia"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2195, 'Forensic Medicine', 'Sexual Offences', 'Easy', 'Forensic_Medicine', 150, '{"id":2195,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":150,"q":"Taking off ones clothes and running naked in a public race is called ?","o":["Mooning","Exhibitionism","Voyeurism","Undinism"],"a":1,"e":"Ans. is ''b'' i.e., Exhibitionism Exhibitionism (Sec 294 IPC): It is a willful and intentional exposure of the genitalia in a public place while in the presence of others to obtain sexual pleasure. May or may not be associated with masturbation (punishment = 3 months + fine). Voyeurism = Scoptophilia = Peeping tom: Sexual gratification is obtained by looking at the sexual organs of other persons, watching the act of sexual intercourse, or witnessing undressing by a woman. Frotteurism: Sexual satisfaction is obtained by rubbing against persons in a crowd. If they attempt intercourse, they have premature ejaculation or they are impotent. It is an uncommon perversion and rarely occurs alone. Undinism: In this, sexual pleasure is often obtained by witnessing the act of urination by someone of the same or opposite sex.","pyqMatches":[{"year":"2014","no":692,"q":"Taking off ones clothes and running naked in a public race is called ?","o":["Mooning","Exhibitionism","Voyeurism","Undinism"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2196, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 151, '{"id":2196,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":151,"q":"According to federation dental lower left canine is designated as ?","o":["32","33","42","43"],"a":1,"e":"Ans. is ''b'' i.e., 33","pyqMatches":[{"year":"2014","no":657,"q":"According to federation dental lower left canine is designated as ?","o":["32","33","42","43"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2197, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 152, '{"id":2197,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":152,"q":"Judge can ask clarifying questions when ?","o":["After cross exam","Before cross exam","Before re cross exam","At any time he wishes"],"a":3,"e":"Ans. is ''d'' i.e., At any time he wishes The judge may ask any question, in any form, about any fact, relevant or irrelevant, at any stage of the examination to clear up doubts. Recording of evidence After oath administration, the evidence is recorded under following steps :- i. Examination in chief (direct examination) : It is the examination of the witness by lawyer of the party calling the witness. In government prosecutions, it is done by public prosecutor (PP)/district government pleader(DGP). The objective is to elicit all relevant, and convincing facts. No leading questions are permitted. Leading question means the question, which leads the witness to desired answer. However, if the witness is declared hostile, leading questions can be asked. i. Cross-examination : Examination of the witness is conducted by the lawyer ofthe opposite party. In government prosecutions it is done by defence lawyer. The objective is to elicit, remove or modify facts and to test the accuracy of statement or witness. Leading questions are allowed. i. Re-examination (Redirect examination) : It is conducted like examination in chief and so by the lawyer of same party. The objective is to clear out any discrepancies/doubt, that have arisen during cross-examination. Leading questions are not allowed. The witness should not tell any new thing at this stage, otherwise opposing lawyer is permitted for re-cross examination. v. Court questions : At any stage, during the recording of evidence, the judge may ask questions to clear his doubts.","pyqMatches":[{"year":"2014","no":653,"q":"Judge can ask clarifying questions when ?","o":["After cross exam","Before cross exam","Before re cross exam","At any time he wishes"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2198, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 153, '{"id":2198,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":153,"q":"Fatal dose of KCN is ?","o":["50 - 60 mg","120 -130 mg","180 -190 mg","280 - 300 mg"],"a":3,"e":"Ans. is ''d'' i.e., 280 - 300 mg Fatal dose of hydrocyanic acid in the pure form is 50 - 60 mg while as sodium or potassium cyanide is 200 - 300 mg.","pyqMatches":[{"year":"2014","no":723,"q":"Fatal dose of KCN is ?","o":["50 - 60 mg","120 -130 mg","180 -190 mg","280 - 300 mg"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2199, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 154, '{"id":2199,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":154,"q":"Rule of Haase is used to calculate ?","o":["Age of fetus","Length of femur","Diameter of skull","Percentage of burns"],"a":0,"e":"Ans. is ''a'' i.e., Age of fetus Rule of Haase Hess''s rule (Haase''s rule) : It is a rough method for calculating the age of fetus by measuring the length from crown to heel. Upto 5th month of gestation, length of foetus in cm is square of the month of gestation and beyound 5 months, length in cm is 5 times the month of gestation.","pyqMatches":[{"year":"2014","no":697,"q":"Rule of Haase is used to calculate ?","o":["Age of fetus","Length of femur","Diameter of skull","Percentage of burns"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2200, 'Forensic Medicine', 'Sexual Offences', 'Moderate', 'Forensic_Medicine', 155, '{"id":2200,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":155,"q":"Which of the following is not a sexual offence in India -","o":["Incest","Sodomy","Indecent assault","Bestiality"],"a":0,"e":"Ans. is ''a'' i.e., Incest Incest It means sexual intercourse by a man with a woman who is closely related to him by blood (prohibited degrees of relationship), e.g. a daughter, grand daughter, sister, step sister, aunt, or mother. These cases usually have psychological features. In India, incest as such is not an offence.","pyqMatches":[{"year":"2014","no":691,"q":"Which of the following is not a sexual offence in India","o":["Incest","Sodomy","Indecent assault","Bestiality"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2201, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 156, '{"id":2201,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":156,"q":"IPC 319 deals with ?","o":["Definition of hurt","Voluntarily causing hurt","Definition of grievous hurt","Voluntarily causing grievous hurt"],"a":0,"e":"Ans. is ''a'' i.e., Definition of hurt","pyqMatches":[{"year":"2014","no":644,"q":"IPC 319 deals with ?","o":["Definition of hurt","Voluntarily causing hurt","Definition of grievous hurt","Voluntarily causing grievous hurt"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2202, 'Forensic Medicine', 'Medical Jurisprudence', 'Easy', 'Forensic_Medicine', 157, '{"id":2202,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":157,"q":"Doctor who did surgery on wrong side of the pateient is punishable under section ?","o":["S. 304 A IPC","S. WC","S. 305 AIPC","S. 305 IPC"],"a":0,"e":"Ans. is ''a'' i.e., S. 304 A IPC Section 304 A IPC Causing death by negligence: Whosoever causes the death of any person, by doing any rash or negligent act not amounting to culpable homicide shall be punished with imprisonment for a term which may extend to 2 years or with fine, or with both. Doctor doing surgery on the wrong side of the patient is an example of gross inattention and recklessness shown by the doctor and is thus an example of criminal negligence. Criminal negligence is punishable under S. 304 A IPC.","pyqMatches":[{"year":"2014","no":646,"q":"Doctor who did surgery on wrong side of the pateient is punishable under section ?","o":["S. 304 A IPC","S. WC","S. 305 AIPC","S. 305 IPC"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2203, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 158, '{"id":2203,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":158,"q":"Postmortem blood is collected from which vessel ?","o":["Femoral artery","Femoral vein","Cephalic vein","Brachial artery"],"a":1,"e":"Ans. is ''b'' i.e., Femoral vein Before autopsy 10 - 20 ml of blood is collected from the femoral vein in groin. Jugular/ subclavian vein can also be used.","pyqMatches":[{"year":"2014","no":707,"q":"Postmortem blood is collected from which vessel ?","o":["Femoral artery","Femoral vein","Cephalic vein","Brachial artery"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2204, 'Forensic Medicine', 'Thanatology', 'Moderate', 'Forensic_Medicine', 159, '{"id":2204,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":159,"q":"When group of muscles of dead body were in state of strong contration immediately prior to death and remain so even after death, this is termed as ?","o":["Gas stiffening","Rigor mortis","Cadaveric spasm","Cold stiffening"],"a":2,"e":"Ans. is ''c'' i.e., Cadaveric spasm Cadaveric spasm (instantaneous rigor) is defined as the condition wherein a group of muscles, which were in contraction or spasm at the time of death, continue to be in spasm even after death, without the stage of primary relaxation. It is a condition in which the muscles of the body which were in a state of contraction immediately before death, continue to be so after death without passing through the stage of primary relaxation. Cadaveric spasm, being an antemortem phenomenon, reflects the last act of the subject performed before and at the time of his death. The cause and manner of death may be judged. It may be due to exhausted ATP in the affected muscles with the persistence of contraction even after death and the resulting failure of the chemical processes required for active muscular relaxation to occur during molecular death. Adrenocortical exhaustion, which impairs resynthesis of ATP may be the possible cause","pyqMatches":[{"year":"2014","no":705,"q":"When group of muscles of dead body were in state of strong contration immediately prior to death and remain so even after death, this is termed as ?","o":["Gas stiffening","Rigor mortis","Cadaveric spasm","Cold stiffening"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2205, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 160, '{"id":2205,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":160,"q":"Most common organ affected in underwater blast ?","o":["Intestine","Liver","Spleen","Heart"],"a":0,"e":"Ans. is ''a'' i.e., Intestine The most common organ affected in underwater blast injury is intestine. Explosion injury An explosion is a phenomenon resulting from sudden release of energy which is then dissipated by a blast wave, by translocation of objects, or by the generation of heat. Injuries in explosion occur due to four factors :? 1) Blast or shock wave When an explosion occurs, the explosive material produces a large volume of gas and releases a large amount of energy. It produces a ''shock wave'' which spread concentrically from the site of explosion. The injuries depend on the enviornment in which blast occurs :- i. Air blast (most common) : Explosion occurs in air. There is barotrauma to air filled hollow organs. Tympanic membrane (ear drum) is most sensitive and most commonly injured. Lung is the second organ to be injured and is the most commonly injured hollow organ and most common cause of life threatening injury. Other parts injured are middle ear, cochlea, eyes, bowels, mesentery, omentum and brain. Homogenous solid organs like liver and muscles are usually not affected. i. Under water blast (explosion under water): Gastrointestinal tract is injured most commonly. Lungs are also injured. i. Solid blast : Explosive is detonated near a rigid/solid structure and wave of energy spreads through it. If people are in contact with that rigid structure, injuries take place. The injuries are mostly skeletal; fracture of legs and vertebral column are more common. GIT damage is more common than lung. 2) Flame or hot gases Burns or burning of body may occur. 3) Flying missiles (debris) Flying pieces of explosive debris may be driven through air against the skin causing bruises, abrasions, lacerations, and ragged perforations. 4) Anoxia Various gases liberated during explosion may cause anoxia, e.g. carbon monoxide, nitrous oxide, nitric oxide, HCN and SO,.","pyqMatches":[{"year":"2014","no":679,"q":"Most common organ affected in underwater blast ?","o":["Intestine","Liver","Spleen","Heart"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2206, 'Forensic Medicine', 'Miscellaneous', 'Moderate', 'Forensic_Medicine', 161, '{"id":2206,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":161,"q":"Torture in which legs or thighs are tied with bamboo and the torturer presses on the two sides of the clamp to cause pain is called ?","o":["Falanga","Telefono","Mercelago","Chepuwa"],"a":3,"e":"Ans. is ''d'' i.e., Chepuwa Physical torture Torture is defined as deliberate, systemic or wanton infliction of physical or mental suffering by one or more persons acting alone or on the orders of any authority, to force a person to yield information, to make a confession or for any other reason. Torture may be physical or psychological. Important methods of physical torture are :?","pyqMatches":[{"year":"2014","no":678,"q":"Torture in which legs or thighs are tied with bamboo and the torturer presses on the two sides of the clamp to cause pain is called ?","o":["Falanga","Telefono","Mercelago","Chepuwa"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2207, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 162, '{"id":2207,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":162,"q":"Age under which child is considered incapable of committing an offence is ?","o":["3 years","7 years","14 years","18 years"],"a":1,"e":"Ans. is ''b'' i.e., 7 years","pyqMatches":[{"year":"2014","no":662,"q":"Age under which child is considered incapable of committing an offence is ?","o":["3 years","7 years","14 years","18 years"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2208, 'Forensic Medicine', 'Miscellaneous', 'Moderate', 'Forensic_Medicine', 163, '{"id":2208,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":163,"q":"Impotence is not a feature of -","o":["Double penis","Bilateral castration","Hypospadias","Penile amputation"],"a":2,"e":"Ans. is ''c'' i.e., Hypospadias \"Congenital problems such as hypospadias are not usually associated with erectile dysfunction\" — Michael C Foster","pyqMatches":[{"year":"2014","no":690,"q":"Impotence is not a feature of","o":["Double penis","Bilateral castration","Hypospadias","Penile amputation"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2209, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 164, '{"id":2209,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":164,"q":"How many cusps are present in chewing surface of premolars ?","o":["2","3","4","5"],"a":0,"e":"Ans. is ''a'' i.e., 2 Premolars or bicuspids They have two cusps on the chewing surface of teeth. The root is usually single but may be double.","pyqMatches":[{"year":"2014","no":661,"q":"How many cusps are present in chewing surface of premolars ?","o":["2","3","4","5"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2210, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 165, '{"id":2210,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":165,"q":"Hunger pangs are seen how long after starvation ?","o":["6 hours","12 hours","24 hours","48 hours"],"a":2,"e":"Ans. is ''c'' i.e., 24 hours When hunger contractions start to occur in the stomach, they are informally referred to as hunger pangs. Hunger pangs usually do not begin until 12 to 24 hours after the last ingestion of food.","pyqMatches":[{"year":"2014","no":726,"q":"Hunger pangs are seen how long after starvation ?","o":["6 hours","12 hours","24 hours","48 hours"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2211, 'Forensic Medicine', 'Thanatology', 'Moderate', 'Forensic_Medicine', 166, '{"id":2211,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":166,"q":"A person is declared dead if not seen by relatives for how many years ?","o":["3 years","7 years","10 years","12 years"],"a":1,"e":"Ans. is ''b'' i.e., 7 years A person is legally declared dead if not seen for 7 years from the date of declared missing. The Indian Evidence Act, under section 108 provides 7 years from the date whence a person is declared to be missing and his whereabouts are not known for presuming a person to be dead (Death in absentia).","pyqMatches":[{"year":"2014","no":641,"q":"A person is declared dead if not seen by relatives for how many years ?","o":["3 years","7 years","10 years","12 years"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2212, 'Forensic Medicine', 'Forensic Identification', 'Hard', 'Forensic_Medicine', 167, '{"id":2212,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Hard","source":"Forensic_Medicine","sourceNo":167,"q":"What is the situation of the knot of ligature in cases of typical hanging?","o":["In front of chin","Angle of mandible","Occiput","Mastoid"],"a":2,"e":"Ans. is ''c'' i.e., Occiput Typical hanging : The ligature runs from the midline above the thyroid cartilage, symmetrically upward on both side of neck to the occipital region, the point of suspension (knot of ligature) being on occiput (at nape of neck). Atypical hanging : Any variation from typical knot site (i.e. other than occiput/nape of neck) is called atypical hanging. Most common site of knot is near one side of mastoid process or angle of mandible.","pyqMatches":[{"year":"2014","no":677,"q":"What is the situation of the knot of ligature in cases of typical hanging?","o":["In front of chin","Angle of mandible","Occiput","Mastoid"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2213, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 168, '{"id":2213,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":168,"q":"Age of eruption of Permanent 1st molor ?","o":["6 years","8 years","10 years","12 years"],"a":0,"e":"Ans. is ''a'' i.e., 6 years","pyqMatches":[{"year":"2014","no":660,"q":"Age of eruption of Permanent 1st molor ?","o":["6 years","8 years","10 years","12 years"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2214, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 169, '{"id":2214,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":169,"q":"In India exhumation is ordered by ?","o":["Magistrate","Health Secretory","Health Minister","Any local MLA"],"a":0,"e":"Ans. is ''a'' i.e., Magistrate Exhumation Exhumation is lawful digging out of a burried body from the grave for the purpose of identification or determination of cause of death. Only a magistrate (executive magistrate) can order for exhumation. In india, there is no time limit for exhumation, i.e. can be done at any time after death. It is done under supervision of medical officer and Magistrate in presence of a police officer who provides witnesses to identify grave, coffin and dead body, whenever possible, Magistrate should inform the relatives and allow them not to remain present at the time of enquiry. The whole procedure should be conducted and completed in natural day light. Therefore, it is usually started early in morning.","pyqMatches":[{"year":"2014","no":663,"q":"In India exhumation is ordered by ?","o":["Magistrate","Health Secretory","Health Minister","Any local MLA"],"a":0,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":641,"q":"In India exhumation is ordered by ?","o":["Magistrate","Health Secretory","Health Minister","Any local MLA"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2215, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 170, '{"id":2215,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":170,"q":"Bullet which is left inside the body for long is referred to as ?","o":["Souvenir bullet","Tracer bullet","Tumbling bullet","Tandem bullet"],"a":0,"e":"Ans. is ''a'' i.e., Souvenir bullet Projectile is an object propelled by force of rapidly burning gases. In shotgun these are lead shots and pellets (recently steel is also used instead of lead) and in rifled weapons (pistal, rifle, revolver), these are bullets. Tip of the bullet is knwon as nose. Varieties of bullets are :- i. Incendiary (igniting) bullet : The tip of bullet contains self igniting material e.g. barium nitrate and powdered aluminium and magnesium (in the past, phosphorus was used), so that it catches fire on hitting the target. It is used to cause fire in usually inflammable targets like fuel tanks (of air crafts etc). i. Explosive bullet : The tip contains a detonator or lead azide, so that the bullet explodes on hitting the target. i. Dum-dum bullet (expanding bullet): It is a jacketed bullet with is nose tip chiseled or cut off. It is designed to increase in diameter and expand upon striking the target, thus producing larger diameter wounds of limited penetration. v. Tandem bullet (Piggey tail bullet) : It is called one-behind-other bullet because two bullets are ejected one after the other, when first bullet failed to leave the burrel and is ejected by subsequently fired bullet. Therefore, both enter body through same enterance wound (some times, they may enter through different entries), but the wounds of exit are always two. v. Tandem (Duplex) cartridge is one in which two bullets are present in same cartridge. It is used in military rifles. i. Tracer bullet: It leaves a trace in atmosphere along the path so that a person (gunner) can observe the strike. Burning of barium nitrate produces flame and powdered magnesium along with strontium nitrate are added to give red color to the flame. i. Tumbling bullet : One that rotates in end on end during its motion. i. Yawning bullet : One which travels in an irregular fashion and causes a key hole entery wound. Yaw means deviation between long axis of bullet and the axis of path of bullet. x. Souvenir bullet : A bullet left in body for long time and is surrounded by fibrous tissue. x. Frangile bullet : Designed to fragment upon impact. i. Mushrooming of bullet : A soft nose bullet, an hitting the target may get deformed to assume the shape of a mushroom.","pyqMatches":[{"year":"2014","no":680,"q":"Bullet which is left inside the body for long is referred to as ?","o":["Souvenir bullet","Tracer bullet","Tumbling bullet","Tandem bullet"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2216, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 171, '{"id":2216,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":171,"q":"Nysten''s rule pertains to ?","o":["Rigor mortis","Identification","Bullet injuries","Putrefaction"],"a":0,"e":"Ans. is ''a'' i.e., Rigor mortis Rigor mortis It is defined as contraction, stiffening, shortenig and opacity of muscles after death. It occurs after molecular (cellular) death. In tropical countries (e.g. india), it begins 1-2 hours after death, takes further 2 hours to develop, and lasts for 18-36 hours in summer and 24-48 hours in winter. In temperate countries, it begins in 3-6 hours, takes further 2-3 hours to develop and lasts for 2-3 days. All muscles of body are involved, i.e. voluntary or involuntary. However, it does not start in all muscles simultaneously (nysten''s rule). Involuntary muscles (heart) are involved first than voluntary muscles. Sequence of muscles involvement is as follows : Heart > upper eyelid > neck > jaw > face > chest > upper limb > abdomen > lower limb > finger and toes. It passes off in the same order in which it has appeared.","pyqMatches":[{"year":"2014","no":725,"q":"Nysten''s rule pertains to ?","o":["Rigor mortis","Identification","Bullet injuries","Putrefaction"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2217, 'Forensic Medicine', 'Forensic Toxicology', 'Moderate', 'Forensic_Medicine', 172, '{"id":2217,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":172,"q":"Pin point pupils are seen in all except ?","o":["Pontine hemorrhage","Organophosphorus poisoning","Opium poisoning","Barbiturate poisoning"],"a":3,"e":"Ans. is ''d'' i.e., Barbiturate poisoning Pin point pupil can be caused by : Opioids (morphine), organophosphates, phenothiazines, clonidine, mushroom poisoning, chloral hydrate, carbolic acid and pontine hemorrhage.","pyqMatches":[{"year":"2014","no":724,"q":"Pin point pupils are seen in all except ?","o":["Pontine hemorrhage","Organophosphorus poisoning","Opium poisoning","Barbiturate poisoning"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2218, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 173, '{"id":2218,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":173,"q":"Anal coitus with opposite sex is -","o":["Bestiality","Sodomy","Sin of Gomorrah","Fellatio"],"a":1,"e":"Ans. is ''b'' i.e., Sodomy Anal intercourse between two males or between a male and female is called sodomy. It is called sodomy as it used to be practiced in a town called sodomy.","pyqMatches":[{"year":"2014","no":689,"q":"Anal coitus with opposite sex is","o":["Bestiality","Sodomy","Sin of Gomorrah","Fellatio"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2219, 'Forensic Medicine', 'Medical Jurisprudence', 'Easy', 'Forensic_Medicine', 174, '{"id":2219,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":174,"q":"Punishment for perjury is covered under section -","o":["191 IPC","193 IPC","195 IPC","1971PC"],"a":1,"e":"Ans. is ''b'' i.e., 193 IPC","pyqMatches":[{"year":"2014","no":642,"q":"Punishment for perjury is covered under section","o":["191 IPC","193 IPC","195 IPC","1971PC"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2220, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 175, '{"id":2220,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":175,"q":"Extreme hunger in starvation lasts upto -","o":["6 - 12 hours","12 - 24 hours","24 - 36 hours","36 - 48 hours"],"a":3,"e":"Ans. is ''d'' i.e., 36 - 48 hours Starvation is the result of actual deprivation of food or administration of unsuitable food. Starvation may be :?","pyqMatches":[{"year":"2014","no":727,"q":"Extreme hunger in starvation lasts upto","o":["6 - 12 hours","12 - 24 hours","24 - 36 hours","36 - 48 hours"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2221, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 176, '{"id":2221,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":176,"q":"Rigor mortis in fetus at birth can be seen in ?","o":["Dead born","Still born","Superfoetation","Superfecundation"],"a":0,"e":"Ans. is ''a'' i.e., Dead born Signs of dead born (intrauterine death : IUD) are (i) Rigor mortis at birth, (ii) Maceration, (iii)Putrefaction, and (iv) Mummification.","pyqMatches":[{"year":"2014","no":701,"q":"Rigor mortis in fetus at birth can be seen in ?","o":["Dead born","Still born","Superfoetation","Superfecundation"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2222, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 177, '{"id":2222,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":177,"q":"Feature which differentiates true from artificial bruise is ?","o":["Round shape with irregular margins","Irregular shape with regular margins","Swelling of surrounding area","Erythema of surrounding area"],"a":0,"e":"Ans. is ''a'' i.e., Round shape with irregular margins Such \"injury\" is an artificial/false bruise that may be produced by applying the juices of various irritant vegetable poisons. Other agents that can produce artificial bruise may include madar juice or Plumbago root. The juice, like vitriol, has been thrown on the face with evil intention. Homicidal poisoning by internal administration of the juice is very rare.","pyqMatches":[{"year":"2014","no":681,"q":"Feature which differentiates true from artificial bruise is ?","o":["Round shape with irregular margins","Irregular shape with regular margins","Swelling of surrounding area","Erythema of surrounding area"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2223, 'Forensic Medicine', 'Injuries & Wounds', 'Moderate', 'Forensic_Medicine', 178, '{"id":2223,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":178,"q":"Bullet entry wound, for bullet entering at acute angle is identified by what shape of abrasion collar ?","o":["Circular","Rectangular","Oval","None of the above"],"a":2,"e":"Ans. is `c'' i.e., Oval If bullet enters at acute angle to the skin then the abrasion collar is oval and if the bullet enters at right angle to the skin the abrasion collar is circular.","pyqMatches":[{"year":"2014","no":672,"q":"Bullet entry wound, for bullet entering at acute angle is identified by what shape of abrasion collar ?","o":["Circular","Rectangular","Oval","None of the above"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2224, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 179, '{"id":2224,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":179,"q":"Atria mortis other name for?","o":["Gateways of death","Gateways of life","Gateways of air","Gateways of water"],"a":0,"e":"Ans. is ''a'' i.e., Gateways of death","pyqMatches":[{"year":"2014","no":706,"q":"Atria mortis other name for?","o":["Gateways of death","Gateways of life","Gateways of air","Gateways of water"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2225, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 180, '{"id":2225,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":180,"q":"Bitter almond odour is percieved in poisoning with?","o":["Cobalt","Arsenic","Cyanide","Lead"],"a":2,"e":"Ans. is ''c'' i.e., Cyanide","pyqMatches":[{"year":"2014","no":719,"q":"Bitter almond odour is percieved in poisoning with?","o":["Cobalt","Arsenic","Cyanide","Lead"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2226, 'Forensic Medicine', 'Injuries & Wounds', 'Moderate', 'Forensic_Medicine', 181, '{"id":2226,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":181,"q":"Incised wound which is not a feature ?","o":["Length is the greatest dimention","Width is more than the thickness of the blade","Margins are inverted","Hesitation cuts are seen in suicidal attempt"],"a":2,"e":"Ans. is ''c'' i.e., Margins are inverted Margins are everted, clear, and clean cut.","pyqMatches":[{"year":"2014","no":682,"q":"Incised wound which is not a feature ?","o":["Length is the greatest dimention","Width is more than the thickness of the blade","Margins are inverted","Hesitation cuts are seen in suicidal attempt"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2227, 'Forensic Medicine', 'Forensic Toxicology', 'Moderate', 'Forensic_Medicine', 182, '{"id":2227,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":182,"q":"Suspended animation is seen in following except?","o":["Sun stroke","Cerebral concussion","Cholera","Delerium tremens"],"a":3,"e":"Ans. is ''d'' i.e., Delirium tremens Suspended animation may be seen in electrocution, drowning, cholera, after anesthesia, shock, sunstroke, cerebral concussion, narcotic poisoning, new born infants and yogis/voluntary.","pyqMatches":[{"year":"2014","no":704,"q":"Suspended animation is seen in following except?","o":["Sun stroke","Cerebral concussion","Cholera","Delerium tremens"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2228, 'Forensic Medicine', 'Sexual Offences', 'Easy', 'Forensic_Medicine', 183, '{"id":2228,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":183,"q":"Puppe''s rule deals with?","o":["Chemical injuries","Multiple impact injuries","Sexual assault","Percentage of burns"],"a":1,"e":"Ans. is `b'' i.e., Multiple impact injuries","pyqMatches":[{"year":"2014","no":685,"q":"Puppe''s rule deals with?","o":["Chemical injuries","Multiple impact injuries","Sexual assault","Percentage of burns"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2229, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 184, '{"id":2229,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":184,"q":"Barberio''s test uses which of the following?","o":["Picric acid","Acetic acid","Hydrochloric acid","Sulfuric acid"],"a":0,"e":"Ans. is ''a'' i.e., Picric acid","pyqMatches":[{"year":"2014","no":708,"q":"Barberio''s test uses which of the following?","o":["Picric acid","Acetic acid","Hydrochloric acid","Sulfuric acid"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2230, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 185, '{"id":2230,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":185,"q":"Pugilistic attitude is characteristically seen in ?","o":["Burns","Drowning","Electrocution","Hanging"],"a":0,"e":"Ans. is ''a'' i.e., Burns","pyqMatches":[{"year":"2016","no":648,"q":"Pugilistic attitude is characteristically seen in ?","o":["Burns","Drowning","Electrocution","Hanging"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2231, 'Forensic Medicine', 'Forensic Toxicology', 'Hard', 'Forensic_Medicine', 186, '{"id":2231,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Hard","source":"Forensic_Medicine","sourceNo":186,"q":"Which of the following should not be done while dealing with a patient of snake bite ?","o":["Tight band applied","Reassuarance","Local incision","Clean with soap and water"],"a":2,"e":"Ans. is ''c'' i.e., Local incision Treatment of snake bite Reassurance should be given to patient. Application of pressure over bitten area which delays absorption of venom. Tie a broad firm bandage (tourniquet) proximal to the bitten area and around the limb which would occlude venous and lymphatic drainage but not arterial or deep venous flow. Limb immobilization. Local incision and suction should not be done as it can cause local injury and nerve damage. Clean the wound with soap and water or iodine and cover with sterile dressing. Polyvalent snake antivenom is given. However it is given only in following situations : i. Rapidly progressive and severe local findings. i. There are manifestations of systemic toxicity.","pyqMatches":[{"year":"2012","no":659,"q":"Which of the following should not be done while dealing with a patient of snake bite ?","o":["Tight band applied","Reassuarance","Local incision","Clean with soap and water"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2232, 'Forensic Medicine', 'Medical Jurisprudence', 'Moderate', 'Forensic_Medicine', 187, '{"id":2232,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":187,"q":"Punishment for criminal abortion for the women who gives consent and the performer are covered under IPC section ?","o":["312","313","314","315"],"a":0,"e":"Ans. is ''a'' i.e., 312 Punishment for performing criminal abortion with the consent of women; both for the women and performer is included in IPC Section 312.","pyqMatches":[{"year":"2016","no":618,"q":"Punishment for criminal abortion for the women who gives consent and the performer are covered under IPC section ?","o":["312","313","314","315"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2233, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 188, '{"id":2233,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":188,"q":"Professional death in medical profession is ?","o":["Death of doctor","Death sentence ordered by judge","Death during police firing","Removal of name of doctor from panel of RMP"],"a":3,"e":"Ans. is ''d'' i.e., Removal of name of doctor from panel of RMP MCI maintains medical register (Indian medical register) of medical practitioners. The registrar should keep the register up to date by :? A.Deleting names of (Erasure of name) : (i) Those dead, (ii) Those awarded penal erasure (professional death sentence) for professional misconduct, (iii) Enteries made in error or fraud. B.Adding names of : (1) Fresh graduates, (ii) Whose term of temporary erasure expires.","pyqMatches":[{"year":"2013","no":652,"q":"Professional death in medical profession is ?","o":["Death of doctor","Death sentence ordered by judge","Death during police firing","Removal of name of doctor from panel of RMP"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2234, 'Forensic Medicine', 'Sexual Offences', 'Easy', 'Forensic_Medicine', 189, '{"id":2234,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":189,"q":"Intercourse in closely related individual in relation?","o":["Incest","Adultery","Bestiality","Tribadism"],"a":0,"e":"Ans. is ''a'' i.e., Incest Incest It means sexual intercourse by a man with a woman who is closely related to him by blood (prohibited degrees of relationship).Example daughter, granddaughter, sister, stepsister, aunt, or mother. These cases usually have psychological features. In India, incest is not an offence. Adultery Adultery refers to volutary sexual intercourse between a married person and a person (married or not), other than his/her spouse. Bestiality It is the sexual intercourse by a human being with a lower animal. Tribadism (Lesbianism or female homosexuality) Sexual gratification of a women obtained by another woman by kissing, body contact, manipulation of breast and genitalia. Active partner is called dyke or butch and the passive agent is called femme. This is not an offence in India.","pyqMatches":[{"year":"2013","no":702,"q":"Intercourse in closely related individual in relation?","o":["Incest","Adultery","Bestiality","Tribadism"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2235, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 190, '{"id":2235,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":190,"q":"Cause of death in cafe coronary ?","o":["Chocking","Laryngeal edema","Cardiac arrest","Pulmonary edema"],"a":2,"e":"Ans. is ''c'' i.e., Cardiac arrest Both asphyxia and cardiac arrest are causes of death in café coronary. Most of the guides have given asphyxia as the answer. But according to me cardiac arrest is the better one. Read following statements : \"Death appears to be due to sudden heart attack.\" — Reddy \"The bolus offood obstruct the larynx, stimulating laryngeal nerve, so stimulating vagus nerve and thus resulting in sudden cardiopulmonary arrest and thereby sudden death.\" — S.K. Singhal \"Death is due to asphyxia or reflex cardiac arrest.\" — Parikh \"Death occurs due to cardiac arrest following parasympathetic stimulation through laryngeal nerve ending.\" —R.N. Karmaker","pyqMatches":[{"year":"2013","no":688,"q":"Cause of death in cafe coronary ?","o":["Chocking","Laryngeal edema","Cardiac arrest","Pulmonary edema"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2236, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 191, '{"id":2236,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":191,"q":"Penalty awarded according to dowry prohibition act?","o":["15000 Rs and 5 years","30000 Rs and 7 years","Life imprisonment","Imprisonment for 10 years"],"a":0,"e":"Ans. is ''a'' i.e., 15000 Rs and 5 years According to Dowry Prohibition act (1961), if any person gives or takes or abets the giving or taking dowry is punishable with imprisonment for a term which shall not be less than 5 years and with a fine which shall not be less then 15000 rupees or the amount of the value of such dowry, whichever is more. Note - According to section 304 B IPC punishment for dowry death is imprisonment for atleast 10 years, which may be extended to life imprisonment.","pyqMatches":[{"year":"2013","no":646,"q":"Penalty awarded according to dowry prohibition act?","o":["15000 Rs and 5 years","30000 Rs and 7 years","Life imprisonment","Imprisonment for 10 years"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2237, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 192, '{"id":2237,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":192,"q":"Hurt is defined under section ?","o":["320 IPC","321 IPC","319 IPC","323 IPC"],"a":2,"e":"Ans. is `c'' i.e., 319 IPC 319 IPC : Defines hurt. 320 IPC : Defines grievous hurt. 321 IPC : Voluntarily causing hurt. 322 IPC : Voluntarily causing grievous hurt. 323 IPC : Punishment for voluntarily causing hurt (no provocation, no dangerous weapon) (1 years imprisonment). 324 IPC : Punishment for voluntarily causing hurt by dangerous weapon (3 years imprisonment ± fine). 325 IPC : Punishment for voluntarily causing grievous hurt (no provocation, no dangerous weapon) (7 years imprisonment ± fine).","pyqMatches":[{"year":"2013","no":637,"q":"Hurt is defined under section ?","o":["320 IPC","321 IPC","319 IPC","323 IPC"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2238, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 193, '{"id":2238,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":193,"q":"Class I judicial magistrate has power to give punishment of-","o":["5yr, Rs. 3000","3yr, Rs.5000","5yr Rs.5000","3yr, Rs 3000"],"a":1,"e":"Ans. is ''b'' i.e., 3 yr, Rs. 5000 o Powers of Magistrate (sec 29 CrPC) Class ImprisonmentFine Chief judicial magistrate Upto 7 years Any amount Class 1 judicial magistrate Upto 3 years Rs 5000 Class 2 judicial magistrate Upto lyear Rs 1000","pyqMatches":[{"year":"2013","no":649,"q":"Class I judicial magistrate has power to give punishment of","o":["5yr, Rs. 3000","3yr, Rs.5000","5yr Rs.5000","3yr, Rs 3000"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2239, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 194, '{"id":2239,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":194,"q":"Shape of stab wound depends on-","o":["Edge of weapon","Shape of weapon","Width","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above A stab wound is an injury caused by a more or less sharp pointed weapon when it is driven in through the skin and its depth is the greatest dimension. The size and shape of the stab wound in the skin is dependent on the type of weapon, cutting surface, edge sharpness, width and shape of weapon, body region stabbed, the angle of withdrawal, the direction of thurst, the movement of blade in body, cleavage direction, movement of person stabbed and the condition of tension or relaxation of skin. With a double-edged weapon the shape of the wound will be elliptical or slit like and both angles will be sharp or pointed. With a single-edged weapon, the shape will be triangular or wedge shaped and one angle of the wound will be sharp, the other rounded, blunt, or squared-off. Blunt end on the skin may have small splits, so-called \"fish-tailing\" if the back edge of the blade is heavy. A spear or another round object causes a circular wound.","pyqMatches":[{"year":"2013","no":675,"q":"Shape of stab wound depends on","o":["Edge of weapon","Shape of weapon","Width","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2240, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 195, '{"id":2240,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":195,"q":"Finger print was first established in ?","o":["England","China","India","Singapore"],"a":2,"e":"Ans. is ''c'' i.e., India Finger prints were discovered by an ICS officer Sir William Herschelle (1958). But study was systemized by Sir Francis Gulton (1892) and was further improvized by Sir Edward Henery. Finger prints is the best system of identification till date and teeth (dental status) is considered the second best. The first ever finger print Bureau of the world was established at Calcutta (in Writer''s building) in India","pyqMatches":[{"year":"2013","no":658,"q":"Finger print was first established in ?","o":["England","China","India","Singapore"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2241, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 196, '{"id":2241,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":196,"q":"Cafe cornoray commonly occurs when a person is-","o":["Intoxicated","Eating fatty food","Eating meat","Eating fish"],"a":0,"e":"Ans. is ''a'' i.e., Intoxicated Cafe coronary : It refers to accidental chocking by bolus of food obstructing larynx. Death is mostly due to asphyxia, or due to reflex cardiac arrest caused by stimulation of laryngeal nerve endings. It is common when gag reflex is suppressed, e.g. intoxicated individuals and following large doese of tranquilizers.","pyqMatches":[{"year":"2013","no":689,"q":"Cafe cornoray commonly occurs when a person is","o":["Intoxicated","Eating fatty food","Eating meat","Eating fish"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2242, 'Forensic Medicine', 'Sexual Offences', 'Easy', 'Forensic_Medicine', 197, '{"id":2242,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":197,"q":"Incest is defined as sexual intercourse between ?","o":["Man and animals","Man and closely related women","Man and women other than wife","Man and man"],"a":1,"e":"Ans. is ''b'' i.e., Man and closely related women","pyqMatches":[{"year":"2013","no":703,"q":"Incest is defined as sexual intercourse between ?","o":["Man and animals","Man and closely related women","Man and women other than wife","Man and man"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2243, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 198, '{"id":2243,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":198,"q":"The ideal place to record body temperature in dead body is ?","o":["Rectum","Axilla","Mouth","Groin"],"a":0,"e":"Ans. is ''a'' i.e., Rectum Most common site for recording temperature is the rectum. Thermameter is inserted in rectum around 8-10 cm for 2 minutes. Other sites for recording temperature are nose, ear (external auditory meatus), vagina, and under liver.","pyqMatches":[{"year":"2013","no":667,"q":"The ideal place to record body temperature in dead body is ?","o":["Rectum","Axilla","Mouth","Groin"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2244, 'Forensic Medicine', 'Medical Jurisprudence', 'Moderate', 'Forensic_Medicine', 199, '{"id":2244,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":199,"q":"Under which section, police can arrest a person and ask medical officer to examine him without victims consent ?","o":["Sec 330 IPC","Sec 53 IPC","Sec 190 IPC","Sec 304-A IPC"],"a":1,"e":"Ans. is ''b'' i.e., Sec 53 IPC 53 1PC : An accused can be examined by a medical practitioner at request of police, even without his consent or by force. 304-A IPC: Causing death by negligence(criminal negligence) which also includes medical negligence (Punishable up 2 years or fine or both).","pyqMatches":[{"year":"2013","no":643,"q":"Under which section, police can arrest a person and ask medical officer to examine him without victims consent ?","o":["Sec 330 IPC","Sec 53 IPC","Sec 190 IPC","Sec 304-A IPC"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2245, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 200, '{"id":2245,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":200,"q":"First secondary ossification center appears in","o":["Lower end of femur","Upper end of humerus","Lower end of fibula","Upper end of tibia"],"a":0,"e":"Ans. is ''a'' i.e., Lower end of femur Site given in question Secondary ossification center appears at Lower end of femur 9th month intrauterine life Upper end of tibia At birth Upper end humerus 1/2 -1 year of age Lower end of fibula 1 year of age","pyqMatches":[{"year":"2013","no":663,"q":"First secondary ossification center appears in","o":["Lower end of femur","Upper end of humerus","Lower end of fibula","Upper end of tibia"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2246, 'Forensic Medicine', 'Miscellaneous', 'Moderate', 'Forensic_Medicine', 201, '{"id":2246,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":201,"q":"Rule of 9 in burns is used to denote ?","o":["Depth of bums","% of total body surfacearea","Severity of bums","Type of bums"],"a":1,"e":"Ans. is ''b'' i.e., % of total body surface area","pyqMatches":[{"year":"2013","no":707,"q":"Rule of 9 in burns is used to denote ?","o":["Depth of bums","% of total body surfacearea","Severity of bums","Type of bums"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":667,"q":"Rule of 9 in burns is used to denote ?","o":["Depth of bums","% of total body surfacearea","Severity of bums","Type of bums"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2247, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 202, '{"id":2247,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":202,"q":"Cheilography is the study of ?","o":["Finger prints","Lip prints","Breath analysis","Foot prints"],"a":1,"e":"Ans. is ''b'' i.e., Lip prints Cheiloscopy or queiloscopy is the study of lip prints. Podogram is the study of foot prints which are due to ridge on the sole and toes of the foot. Palato prints (rugoscopy) is the study of anterior part of palate. DactylographyDermatoglyphics/Galton system- is the study of Finger prints. Finger print pattern is absolutely individual i.e. no two hands are entirely alike, not even identical twins. That''s why, it is best (most sensitive and most specific) and most reliable method of identification (Quetelet''s rule of biological variation).","pyqMatches":[{"year":"2013","no":660,"q":"Cheilography is the study of ?","o":["Finger prints","Lip prints","Breath analysis","Foot prints"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2248, 'Forensic Medicine', 'Injuries & Wounds', 'Hard', 'Forensic_Medicine', 203, '{"id":2248,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Hard","source":"Forensic_Medicine","sourceNo":203,"q":"In a patient of unilateral loss of vision, the patient had injury to opposite eye leading to corneal opacification. The patient was operated by corneal grafting, he could see clearly again with one eye. The injury is said to be","o":["Simple","Grievous","Dangerous","Hazardous"],"a":0,"e":"Ans. is ''b'' i.e., Grievous This patient had permanent vision loss as it was corrected by surgery (corneal transplant). Permanent loss of sight of either eye is grievous hurt. Injuries can be classified as","pyqMatches":[{"year":"2015","no":642,"q":"In a patient of unilateral loss of vision, the patient had injury to opposite eye leading to corneal opacification. The patient was operated by corneal grafting, he could see clearly again with one eye. The injury is said to be","o":["Simple","Grievous","Dangerous","Hazardous"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2249, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 204, '{"id":2249,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":204,"q":"Telefono means ?","o":["Beating on soles","Beating on palms","Beating on ears","Pulling of hair"],"a":2,"e":"Ans. is ''c'' i.e., Beating on ears Telefono : Simultaneous beating of both ears with the palm of hands. This may lead to rupture of tympanic membrane, causing pain, bleeding and hearing loss. It is difficult to detect this. The external ear may also get torn during pulling of the ears. Falanga : beating of soles with blunt object. It is the most common type of torture. It can cause immediate & long term consequences, even disability","pyqMatches":[{"year":"2013","no":683,"q":"Telefono means ?","o":["Beating on soles","Beating on palms","Beating on ears","Pulling of hair"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2250, 'Forensic Medicine', 'Medical Jurisprudence', 'Easy', 'Forensic_Medicine', 205, '{"id":2250,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":205,"q":"Virchow method of organ removal is ?","o":["Organs removed en masse","Organs removed one by one","In situ dissection","None"],"a":1,"e":"Ans. is ''b'' i.e., Organs removed one by one Methods of removal of organs Virchow''s technique - organs are removed one by one. Cranial cavity is exposed first, followed by thoracic, cervical & abdominal organs. Rokitansky''s technique - It involves in situ dissection in part, combined with en block removal. Lettulle''s technique - Cervical, thoracic, abdominal & pelvic organs are removed en masse & dissected as organ block.","pyqMatches":[{"year":"2013","no":671,"q":"Virchow method of organ removal is ?","o":["Organs removed en masse","Organs removed one by one","In situ dissection","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2251, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 206, '{"id":2251,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":206,"q":"Primary injury is ?","o":["Due to flying debris b","Due to blast wind","Due to shock wave","Due to complication"],"a":2,"e":"Ans. is ''c'' i.e., Due to shock wave Types of blast injuries These are of following types :?","pyqMatches":[{"year":"2013","no":679,"q":"Primary injury is ?","o":["Due to flying debris b","Due to blast wind","Due to shock wave","Due to complication"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2252, 'Forensic Medicine', 'Thanatology', 'Moderate', 'Forensic_Medicine', 207, '{"id":2252,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":207,"q":"According to which section, a person can be punished for murder with imprisonment for 10 years","o":["Sec 301 IPC","Sec 300 IPC","Sec 302 IPC","Sec 304 IPC"],"a":2,"e":"Ans. is ''c'' i.e., Sec 302 302 IPC: Punishment for murder (death or life imprisonment). 301 IPC : Culpable homicide by causing death of person other than person whose death was intended. 300 IPC : Murder (defining murder). 303 IPC : Punishment of murder of life convict (death). 304 IPC : Punishment of culpable homicide, not amounting to murder (10 years imprisonment f fine). 305 IPC : Abetment of suicide of child or insane person. 306 IPC : Abetment of suicide. 307 IPC : Attempt to murder (10 years imprisonment f fine). 308 IPC : Attempt to commit culpable homicide (3-7 years imprisonment ± fine). 309 IPC : Attempt to commit suicide (1 years imprisonment ± fine).","pyqMatches":[{"year":"2013","no":644,"q":"According to which section, a person can be punished for murder with imprisonment for 10 years","o":["Sec 301 IPC","Sec 300 IPC","Sec 302 IPC","Sec 304 IPC"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2253, 'Forensic Medicine', 'Medical Jurisprudence', 'Easy', 'Forensic_Medicine', 208, '{"id":2253,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":208,"q":"Doctrine of res ipsa loquitur means ?","o":["Common knowledge","Medical maloccurance","Fact speaks for itself","Oral evidence"],"a":2,"e":"Ans. is ''c'' i.e., Fact speaks for itself Doctrine of res ipsa loquitur It means \"the thing or fact speaks for itself \". In a case of professional negligence of a physician, the patient need not prove negligence. It is applied when following conditions are fulfilled :","pyqMatches":[{"year":"2013","no":653,"q":"Doctrine of res ipsa loquitur means ?","o":["Common knowledge","Medical maloccurance","Fact speaks for itself","Oral evidence"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2254, 'Forensic Medicine', 'Forensic Identification', 'Moderate', 'Forensic_Medicine', 209, '{"id":2254,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":209,"q":"Number of teeth can be counted by all the following methods except -","o":["Gustafson method","Mile method","Boyde method","Frame method"],"a":3,"e":"Ans. is `d'' i.e., Frame method Age from teeth after 20 years Teeth eruption is useful for age estimation upto about 18 years, beyond which it is just a guess work. The methods used are :? A. Gustafson''s method : Useful only in persons older than 21 years of age, depending on the physiological changes in each of the dental tissues.","pyqMatches":[{"year":"2013","no":664,"q":"Number of teeth can be counted by all the following methods except","o":["Gustafson method","Mile method","Boyde method","Frame method"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2255, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 210, '{"id":2255,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":210,"q":"Term cafe coronary was coined by ?","o":["Roger Haugen","J. Morton","Neil Markson","M. Hoppefield"],"a":0,"e":"Ans. is ''a'' i.e., Roger Haugen A popular term ''cafe coronary'' was coined by Dr. Roger Haugen, Medical Examiner of Broward County, Florida for such impaction of food in the respiratory passage\". — Krishan Vij","pyqMatches":[{"year":"2013","no":687,"q":"Term cafe coronary was coined by ?","o":["Roger Haugen","J. Morton","Neil Markson","M. Hoppefield"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2256, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 211, '{"id":2256,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":211,"q":"Most common organ involved in air blast injury is ?","o":["Ear drum","Stomach","Eye","Lung"],"a":0,"e":"Ans. is ''a'' i.e., Ear drum Blast or shock wave When an explosion occurs, the explosive material produces a large volume of gas and releases a large amount of energy. It produces a ''shock wave'' which spread concentrically from the site of explosion. The injuries depend on the environment in which blast occurs :-","pyqMatches":[{"year":"2013","no":681,"q":"Most common organ involved in air blast injury is ?","o":["Ear drum","Stomach","Eye","Lung"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2257, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 212, '{"id":2257,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":212,"q":"The outer covering of diatom is made of ?","o":["Magnesium","Silica","Hydrocarbons","None"],"a":1,"e":"Ans. is ''b'' i.e., Silicon The extracellular coat of diatoms has silica. Diatoms are unicellular algae, suspended in water. They have silicaceous cell wall (i.e. cell wall contains silica) which resist acid digestion and putrefaction. Only live body with a circulation can transport diatoms form lung to brain, bone marrow, muscles etc. So, presence of diatoms in brain and bone marrow indicates death due to drowning. For detection of diatoms, bone marrow of long bones, e.g. femur, tibia, humerus or sternum is highly suitable and reliable. As diatoms resist acid digestion, to extract them acid digestion techinique is used. Diatoms test is negative in dead bodies thrown in water and in dry drowning. However, diatoms test is invalid, if deceased had drunk this water before submersion or species of diatoms do not match with specimen from the site of drowning","pyqMatches":[{"year":"2013","no":694,"q":"The outer covering of diatom is made of ?","o":["Magnesium","Silica","Hydrocarbons","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2258, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 213, '{"id":2258,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":213,"q":"Reliable method of identification of person is ?","o":["Gustafson''s method","Galton method","Scar","Anthropometry"],"a":1,"e":"Ans. is ''b'' i.e., Galton method Galton method or Finger prints or dactylography is the best system of identification till date. The fingerprints are capable of endless variation so that there is one chance in sixty four billions of two persons having identical prints. Dactylography / Dermatoglvphics / Galton system / Finger prints Finger prints are present from birth both on epidermis and dermis, remain constant through out life and can''t be altered without destroying true skin. Finger print pattern is absolutely individual i.e. no two hands are entirely alike, not even identical twins. That''s why, it is best (most sensitive and most specific) and most reliable method of identification (Quetelet''s rule of biological variation). DNA finger printing may be same in monozygotic twins. The pattern is neither inherited nor identical in any two persons. So the paternity cannot be proved through finger print patterns. However, paternity can be proved by DNA finger printing. Loops (67% most common) > whorls (25%) > arches (7%) > composite (2% least common) are four main types of pattern. It is accepted that chances of 2 finger prints matching 16 ridge characteristic are infinitely small (Parikh''s). Inpractice 8 - 16 (Reddy) / 16 - 20 (Seth, Simpson) points of fine comparision are accepted as proof of identity. Locard''s poroscopy method is study of microscopic pores, formed by mouths of ducts of subepidermal sweatgland present on ridges of fingers. These pores are permanent, remain un changed during life and are very usefulwhen only fragments of fingerprints are available. Each milimeter contains 9 - 18 pores. Criminals may attempt to multilate finger prints by applying CO2 snow, corrosive agents, burns or eroding against hard surface. But these manners do not destroy finger prints permanently unless true skin is completely destroyed.","pyqMatches":[{"year":"2013","no":661,"q":"Reliable method of identification of person is ?","o":["Gustafson''s method","Galton method","Scar","Anthropometry"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2259, 'Forensic Medicine', 'Medical Jurisprudence', 'Easy', 'Forensic_Medicine', 214, '{"id":2259,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":214,"q":"Quantum of punishment in dowry death is ?","o":["7years","5 years","Death","10 years"],"a":3,"e":"Ans. is ''d'' i.e., 10 years 304-B IPC: Dowry death : 10 years of imprisonment which can extend to life. 498-A IPC : Punishment for cruelty by husband or his relatives. Dowry death In some cases newly married girls are abused, harassed, cruelly treated and tortured by the husband, in-laws and their relatives for or in connection with any demand for dowry. In extreme cases, the woman is killed by burning or some other method. Law in relation to dowry death are : Low prescribing punishment and definition (section 304 B IPC) Husband or (his any) relative will be tried under section 304B, IPC and shall he deemed to have caused her death, if a woman dies due to bodily injury or burns or otherwise in suspicious circumstances with in 7 years of marriage and it is shown that soon before her death she was subjected to harassment or cruelty by them, in connection with, any demand for dowry. Such death shall be called dowry death. Punishment includes imprisonment of not less than 10 years, but which may extend to life imprisonment''. Low prescribing punishment for causing cruelty to a married women (Sec. 498A, IPC) Husband or (his any) relative will be tried under section 498A, IPC for causing cruelty to a married woman. Cruelty is defined as any willful conduct which drives the woman to commit suicide or grave physical or mental injury to her or harassment of the women with a view to coerce (intimidate) her for dowry. Punishment includes imprisonment which may extend upto 3 years and fine.","pyqMatches":[{"year":"2013","no":647,"q":"Quantum of punishment in dowry death is ?","o":["7years","5 years","Death","10 years"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2260, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 215, '{"id":2260,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":215,"q":"Cephalic index is used for","o":["Race","Age","Sex","Stature"],"a":0,"e":"Ans. is ''a'' i.e., Race Cephalic index, height index & nasal index are used for determination of race. Cephalic index = maximum breadth of skull/ maximum length of skull x 100 Type of skull Cephalic index Race Dolichocephalic (long headed) 70 - 75 Pure Aryan, Aborigines, Negroes Mesaticephalic (medium headed) 75 - 80 Europeans and Chinese Brachycephalic (short headed) 80- 85 Mongolian","pyqMatches":[{"year":"2013","no":665,"q":"Cephalic index is used for","o":["Race","Age","Sex","Stature"],"a":0,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":648,"q":"Cephalic index is used for","o":["Race","Age","Sex","Stature"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2261, 'Forensic Medicine', 'Medical Jurisprudence', 'Easy', 'Forensic_Medicine', 216, '{"id":2261,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":216,"q":"Active ingredient of marking nut is ?","o":["Semecarpol","Crotin","Abrin","None"],"a":0,"e":"Ans. is ''a'' i.e., Semecarpol Semicarpus anacardium or marking nut or bhilawan Its seed are heart shaped, conical and black with acrid oily juice which is brownish but turns black on exposure to air. Active principles are semecarpol and bhilawanol. Juice applied to skin produces irritation, painful blisters followed by itching and eczema. Therefore it is used to produce artificial bruises. It is also used by washerman to mark clothes.","pyqMatches":[{"year":"2016","no":679,"q":"Active ingredient of marking nut is ?","o":["Semecarpol","Crotin","Abrin","None"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2262, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 217, '{"id":2262,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":217,"q":"Mugging is compression of neck by ?","o":["Wooden sticks","Rope","Forearm","Hand"],"a":2,"e":"Ans. is ''c'' i.e., Forearm Mugging (choke hold) : It is compression of neck by forearm or in the bend of elbow. Bansdola : Compression of neck with one or two wooden sticks or bamboo. Garrotting : It is compression of neck by a rope thrown from behind. Spanish windlass is a type of garrotting, which used to be the official mode of execution in spain. In this, an iron collor around the neck was tightened by a screw for strangulation. Throttling (manual strangulation) : Neck is compressed by one or both hands.","pyqMatches":[{"year":"2013","no":690,"q":"Mugging is compression of neck by ?","o":["Wooden sticks","Rope","Forearm","Hand"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2263, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 218, '{"id":2263,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":218,"q":"Time limit of exhumation in India is -","o":["One month","One year","Ten years","No limit"],"a":3,"e":"Ans. is ''d'' i.e., No limit Exumation It is lawful digging out of a buried body from the grave for the purpose of identification or determination of cause of death. Only a magistrate (executive magistrate) can order for exhumation. In india, there is no time limit for exhumation, i.e. can be done at any time after death. It is done under supervision of medical officer and Magistrate in presence of a police officer who provides witnesses to identify grave, coffin and dead body, whenever possible, Magistrate should inform the relatives and allow them not to remain present at the time of enquiry. The whole procedure should be conducted and completed in natural day light. Therefore, it is usually started early in morning.","pyqMatches":[{"year":"2013","no":673,"q":"Time limit of exhumation in India is","o":["One month","One year","Ten years","No limit"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2264, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 219, '{"id":2264,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":219,"q":"Black foot disease is caused by","o":["Arsenic","Cadmium","Lead","Mercury"],"a":0,"e":"Ans. is ''a'' i.e., Arsenic Chronic arsenic exposure can cause ''black foot disease'' a severe form of peripheral vascular disease, causing gangrene of lower limbs. Arsenic poisoning may be acute or chronic. Acute arsenic poisoning It can present in any of the two ways :","pyqMatches":[{"year":"2015","no":667,"q":"Black foot disease is caused by","o":["Arsenic","Cadmium","Lead","Mercury"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2265, 'Forensic Medicine', 'Forensic Identification', 'Moderate', 'Forensic_Medicine', 220, '{"id":2265,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":220,"q":"All are signs of somatic death except ?","o":["Cessation of respiration","Cessation of heart","Non-responding muscles","No response to external stimuli"],"a":2,"e":"Ans. is ''c'' i.e., Non-responding muscles Death denotes death of human being (46 IPC). It is defined as cessation of life or cesation to exist. Death is of two types (1) somatic death (systemic death or clinical death) and (2) molecular death (cellular death). Somatic death (systemic death or clinical death) It is the complete and irreversible stoppage of the circulation, respiration and brain functions (bishop''s tripod of life). Somatic death is associated with immediate signs of death :?","pyqMatches":[{"year":"2013","no":666,"q":"All are signs of somatic death except ?","o":["Cessation of respiration","Cessation of heart","Non-responding muscles","No response to external stimuli"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2266, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 221, '{"id":2266,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":221,"q":"What does Gettlers test detects ?","o":["Diatoms in drowning","Chloride content of blood in drowning","Weight in drowning","None"],"a":1,"e":"Ans. is ''b'' i.e., Chloride content of blood in drowning Gettler test estimates chloride content of blood from both sides of heart. It is done for drowning. Normally the chloride content is equal in the right and left chambers of the heart (600 mg/100 m1). In fresh water drowning due to hemodilution the chloride content is decreased and in salt water drowning due to hemoconcentration the chloride content is increased in left side of heart. A 25% difference in chloride is significant but the test is of doubtful value.","pyqMatches":[{"year":"2013","no":695,"q":"What does Gettlers test detects ?","o":["Diatoms in drowning","Chloride content of blood in drowning","Weight in drowning","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2267, 'Forensic Medicine', 'Medical Jurisprudence', 'Easy', 'Forensic_Medicine', 222, '{"id":2267,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":222,"q":"Method of autopsy in which various systems organs are removed en masse ?","o":["Rokitansky","Virchow","Gasses","Lettulle"],"a":3,"e":"Ans. is ''d'' i.e., Lettulle Methods of removal of organs Virchow''s technique - organs are removed one by one. Cranial cavity is exposed first, followed by thoracic, cervical & abdominal organs. Rokitansky''s technique - It involves in situ dissection in part, combined with enblock removal. Lettulle''s technique - Cervical, thoracic, abdominal & pelvic organs are removed en masse & dissected as organ block.","pyqMatches":[{"year":"2013","no":672,"q":"Method of autopsy in which various systems organs are removed en masse ?","o":["Rokitansky","Virchow","Gasses","Lettulle"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2268, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 223, '{"id":2268,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":223,"q":"In blast injury, what is the organ to be damaged first-","o":["Tympanic membrane","Git","Liver","Lung"],"a":0,"e":"Ans. is ''a'' i.e. Tympanic membrane","pyqMatches":[{"year":"2013","no":682,"q":"In blast injury, what is the organ to be damaged first","o":["Tympanic membrane","Git","Liver","Lung"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2269, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 224, '{"id":2269,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":224,"q":"Immersion syndrome is also called as ?","o":["Hydrocution","Wet drowning","Dry drowning","Secondary drowning"],"a":0,"e":"Ans. is ''a'' i.e., Hydrocution Immersion syndrome - is also called as hydrocution or submersion inhibition or vagal inhibition. Atypical drowning It refers to drowning in which even after submersion of body in water, little or no water anters respiratory passages and lungs. Hence typical findings of wet drowning in the form of froth and oedema aquosun: of lungs are not found. Atypical drowning may be :","pyqMatches":[{"year":"2013","no":696,"q":"Immersion syndrome is also called as ?","o":["Hydrocution","Wet drowning","Dry drowning","Secondary drowning"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2270, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 225, '{"id":2270,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":225,"q":"Blanket consent is consent taken-","o":["When the patient comes to doctor for treatment","Oral consent","Written consent","Taken at the time of admission to do any surgery"],"a":3,"e":"Ans. is'' i.e., Taken at the time of admission to do any surgery Blanket consent: It refers to consent which is taken usually on a printed form, at the time of admission of the patient, authorizing the doctor to do any surgery under any anaesthesia. Legally, it is no consent, i.e. it is of no value in court. To be legally valid, the consent is to be obtained for each specific procedure and operation. Implied consent: In this, consent presumed to be there. The very fact that the patient has come to the doctor for treatment, it is presumed that his consent is there for routine physical examination. e.g. inspection, palpation, auscultation and percussion. Implied consent is a non-written but legally effective form of consent, which is not expressly asserted. Expressed consent: It is stated (oral or written) in clear and explicit language. Oral consent, given in presence of two or more witnesses is as valid as written consent, but there is no record. Written consent is better as there is a record of consent available, in cases of dispute. Written informed consent: It is a type of expressed consent in written form which is given by the patient after being informed of nature of illness or nature of procedure or operation to be done, its alternatives, its consequences and complications.","pyqMatches":[{"year":"2013","no":654,"q":"Blanket consent is consent taken","o":["When the patient comes to doctor for treatment","Oral consent","Written consent","Taken at the time of admission to do any surgery"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2271, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 226, '{"id":2271,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":226,"q":"Testamentary capacity is ?","o":["Ability to give willful statement","Ability to make will","Ability to judge","None"],"a":0,"e":"Ans. is ''b'' i.e., Ability to make will Testamentary capacity (testament = will) is the mental ability to make a valid will. Will denotes any testamentary document. The requirement for a valid will are as follows. A written and properly signed and witnessed document must exist. The testator must be a major and of sound disposing mind at the time of making the will. Force undue influence or dishonest representation of facts, should not have been applied by others.","pyqMatches":[{"year":"2013","no":656,"q":"Testamentary capacity is ?","o":["Ability to give willful statement","Ability to make will","Ability to judge","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2272, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 227, '{"id":2272,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":227,"q":"Ideal time to start exhumation ?","o":["Mid night","Late evening","Afternoon in proper light","Early morning"],"a":3,"e":"Ans. is ''d'' i.e., Early morning Exumation Exumation is lawful digging out of a burried body from the grave for the purpose of identification or determination of cause of death. Only a magistrate (executive magistrate) can order for exhumation. In india, there is no time limit for exhumation, i.e. can be done at any time after death. It is done under supervision of medical officer and Magistrate in presence of a police officer who provides witnesses to identify grave, coffin and dead body, whenever possible, Magistrate should inform the relatives and allow them not to remain present at the time of enquiry. The whole procedure should be conducted and completed in natural day light. Therefore, it is usually started early in morning.","pyqMatches":[{"year":"2013","no":674,"q":"Ideal time to start exhumation ?","o":["Mid night","Late evening","Afternoon in proper light","Early morning"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2273, 'Forensic Medicine', 'Miscellaneous', 'Moderate', 'Forensic_Medicine', 228, '{"id":2273,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":228,"q":"All are true about antemortem contusion except?","o":["Sequential color change","No inflammation","Raized enzyme levels","Blood cells in surrounding tissueAccidendal"],"a":1,"e":"Ans. is ''b'' i.e., No inflammation","pyqMatches":[{"year":"2013","no":676,"q":"All are true about antemortem contusion except?","o":["Sequential color change","No inflammation","Raized enzyme levels","Blood cells in surrounding tissueAccidendal"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2274, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 229, '{"id":2274,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":229,"q":"chocking of respiratory passage by bolus of food ?","o":["Gaging","Overlying","Cafe coronary","Burking"],"a":2,"e":"Ans. is ''c'' i.e., Cafe coronary","pyqMatches":[{"year":"2013","no":686,"q":"chocking of respiratory passage by bolus of food ?","o":["Gaging","Overlying","Cafe coronary","Burking"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2275, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 230, '{"id":2275,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":230,"q":"Latte''s crust of blood stain is used to detect ?","o":["Nature of stain","Detection species","Blood group","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., Blood group Blood and blood stains The examination of blood and blood stains is an important part of crime detection. The points that are usually required to be determined regarding stains are : (1) nature of stain (whether the stains is blood or not); (2) the species (human or animal) from which the blood has come from; and (3) blood group. Nature of stain (whether the stain is blood or not) To determine the nature of stain, following tests are used :","pyqMatches":[{"year":"2013","no":706,"q":"Latte''s crust of blood stain is used to detect ?","o":["Nature of stain","Detection species","Blood group","None of the above"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2276, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 231, '{"id":2276,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":231,"q":"Tattooing around the entry wound is seen in ?","o":["Close shot","Contact shot","Distant shot","All of the above"],"a":0,"e":"Ans. is ''a'' i.e., Close shot","pyqMatches":[{"year":"2013","no":684,"q":"Tattooing around the entry wound is seen in ?","o":["Close shot","Contact shot","Distant shot","All of the above"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2277, 'Forensic Medicine', 'Thanatology', 'Moderate', 'Forensic_Medicine', 232, '{"id":2277,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":232,"q":"All tests are used for infanticide except ?","o":["Ploucquet test","Fodere''s test","Gettler''s test","Raygat''s test"],"a":2,"e":"Ans. is ''c'' i.e., Gettler''s test Tests used in infanticide (for respiration) Ploucquet''s test : Weight of lung is measured in relation to body wieght. Before birth weight of lung is 1/70 of body weight and after respiration it becomes 1/35 of body weight due to increased blood flow in lung beds. Static test or Fodere''s test : The average weight ofboth lungs before respiration is 30-40 gm and after respiration is 60-70 cm. Hydrostatic test (Raygat''s test, I\" life test) : The specific gravity of a non-respired lung is 1040-1050 and of a respired lung is 940-950, so, after respiration lung floats on water (specific gravity of water is 1000). False positive hydrostatic test may occur (i.e.non-respired lung may float) in decomposition and in attempted artificial respiration. False negative hydrostatic test (i.e. respired lung may sink down) may occur in atelectasis, pulmonary oedema, bronchopneumonia, and congenital syphylis. Breslau''s second life test : It assumes that a live born child would respire and therefore, would also swallow some air into the stomach and bowel. Hence they float on water. This test is falsely positive in putrefaction (due to putrefied gases) or in cases of attempted artificial respiration. Werdin''s test : Before birth middle ear contains gelatinous embryonic tissue which is replaced by air after respiration","pyqMatches":[{"year":"2013","no":700,"q":"All tests are used for infanticide except ?","o":["Ploucquet test","Fodere''s test","Gettler''s test","Raygat''s test"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2278, 'Forensic Medicine', 'Miscellaneous', 'Hard', 'Forensic_Medicine', 233, '{"id":2278,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Forensic_Medicine","sourceNo":233,"q":"For diagnosis of insanity, maximum limit of observation?","o":["5 days","10 days","30 days","50 days"],"a":2,"e":"Ans. C. i.e., 30 days Insanity is characterized by certain abnormal mental and behavioral patterns. Simply insane means unsound mind, i.e. insane is the person which has unsound mind. Conversely sanity means sound mind (compos mentis). Lucid interval is the period of sanity (sound mind) in an insane person, i.e. period in course of mental illness when there is complete cessation of manifestations of insanity. During this period he is quite normal and can make valid will, sell/purchase property, give valid evidence and is legally responsible for his deeds. Before making a diagnosis of insanity, the patient may be kept under observation in mental hospital or general hospital/nursing home. Patient is kept under observation for 10 days, which can be extended upto maximum 30 days. Two doctors (at least one being a government doctor) should examine the patient separately without consulting each other for at least three examinations","pyqMatches":[{"year":"2013","no":657,"q":"For diagnosis of insanity, maximum limit of observation?","o":["5 days","10 days","30 days","50 days"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2279, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 234, '{"id":2279,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":234,"q":"Suicidal mark is horizontal in ?","o":["Hanging","Strangulation","Both of the above","None of the above"],"a":1,"e":"Ans. is ''b'' i.e., Strangulation","pyqMatches":[{"year":"2013","no":692,"q":"Suicidal mark is horizontal in ?","o":["Hanging","Strangulation","Both of the above","None of the above"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2280, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 235, '{"id":2280,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":235,"q":"Graze is a type of ?","o":["Bruise","Contusion","Laceration","Abrasion"],"a":3,"e":"Ans. is ''d'' i.e., Abrasion Abrasion It is a destruction of the skin, which involves the superficial layers of the epidermis only. They are of 4 types:","pyqMatches":[{"year":"2013","no":677,"q":"Graze is a type of ?","o":["Bruise","Contusion","Laceration","Abrasion"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2281, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 236, '{"id":2281,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":236,"q":"Platauf''s hemorrages, incorrect is ?","o":["Sign of drowning","Subpleural hemorrhage","Mostly seen in middle lobe","All are true"],"a":2,"e":"Ans. is ''c'' i.e., Mostaly seen in middle lobe Paltauf''s hemorrhages They are subpleural haemorrhages present in cases of drowning when alveolar walls rupture due to increased pressure during forced expiration and produce haemorrhages. They are shining pale pink or bluish red, and may be minute or 3- 5cm in diameter seen in lungs. They are usually present in about 50 % cases in lower lobes of lungs but may be seen on the anterior surfaces of lungs and the interlobar surfaces.","pyqMatches":[{"year":"2013","no":697,"q":"Platauf''s hemorrages, incorrect is ?","o":["Sign of drowning","Subpleural hemorrhage","Mostly seen in middle lobe","All are true"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2282, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 237, '{"id":2282,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":237,"q":"Most common hymen rupture in a virgin is ?","o":["Anterior","Anterolateral","Posterolateral","Posterior"],"a":2,"e":"Ans. is ''c'' i.e., Posterolateral Hymen rupture: Congenital : anterior Due to intercourse or foreign body: posterolateral ( 4/8 or 5/7 0'' clock) > posterior (6 0'' clock). In virgin rupture (tears) of hymen due to sudden tretching occurs in posterior half of membrane usually at the sides (i.e. posterolaterally) in 4 or 8''O clock or 5 or 7''O clock position, or in the midline of hymen (6''O clock position). With first intercourse tears usually occur in posterior midline because the hymen lies suspended across a potential space here, whereas anteriorly periurethral tissues buttress the hymen. More than 2 tears are unusual, Semilunar hymen often ruptures on both sides. Annular hymen which nearly closes up the vaginal orifice may suffer several hymenal lacerations indicate first sexual intercourse. One deep ''V shaped cleft/tear at 6'' 0 clock or a number of clefts usually in posterior haft hymen membrane indicate passage of any object through hyme orifice which is larger its original opening.'' In prepubertal children posterior tear may involve fourchette producing a deep U shaped defect. Fourchette is torn, fossa navicularis disappear and posterior commissure may be ruptured. The latter injury usually does not occur in consenting sexual intercourse unless there is much disproportion between the male and female parts.","pyqMatches":[{"year":"2012","no":628,"q":"Most common hymen rupture in a virgin is ?","o":["Anterior","Anterolateral","Posterolateral","Posterior"],"a":2,"source":"NEET_2012_Paper.pdf"},{"year":"2013","no":704,"q":"Most common hymen rupture in a virgin is ?","o":["Anterior","Anterolateral","Posterolateral","Posterior"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2012","2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2283, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 238, '{"id":2283,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":238,"q":"Most common drowning in India-","o":["Suicidal","Homicidal","Accidental","Infanticide"],"a":2,"e":"Ans. is ''c'' i.e., Accidental Most of the cases of drowning (2/3) in India are accidental. Rest 1/3 being suicidal. Homicidal drowning is less common in india. Suicidal drowning is indicated by absence of signs of struggle or assault (e.g. torn clothes, injury marks). A determined suicide may tie his hands and legs together or attach weights to his body or take poison or cut throat before immersion. In homicidal drowning, there are signs of struggle and violence (assault) (e.g. head injury, signs of strangulation, or throttling). Head and feet may be tied, heavy weight may be attached to body or body may be tied up inside a gunny bag. Homicidal drowning is very rare except in infants and children. Accidental drowning is quite common and usually seen in children, non-swimmers, during floods or due to fall in well etc.","pyqMatches":[{"year":"2013","no":698,"q":"Most common drowning in India","o":["Suicidal","Homicidal","Accidental","Infanticide"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2284, 'Forensic Medicine', 'Thanatology', 'Hard', 'Forensic_Medicine', 239, '{"id":2284,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Hard","source":"Forensic_Medicine","sourceNo":239,"q":"Magistrate inquest is done in case of ?","o":["Death by suicide","Death by accident","Death in psychiatry hospital","Death in suscpicious circumstances"],"a":2,"e":"Ans. is ''c'' i.e., Death in psychiatry hospital Magistrate''s inquest is done under sec 176 CrPC is case of :-","pyqMatches":[{"year":"2013","no":651,"q":"Magistrate inquest is done in case of ?","o":["Death by suicide","Death by accident","Death in psychiatry hospital","Death in suscpicious circumstances"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2285, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 240, '{"id":2285,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":240,"q":"Schedule-3 of MCI includes-","o":["MBBS degree of indian universities","DNB degree","Diploma of CPS","MBBS degree of foreign universities"],"a":2,"e":"Ans. is ''c'' i.e., Diploma of CPS Schedules of MCI Act MCI was established in 1934 and MCI act was revised in 1956, 1964, 1993, 1999, and 2002. The schedules of MCI includes list of medical degrees recognized by MCI :-","pyqMatches":[{"year":"2013","no":655,"q":"Schedule-3 of MCI includes","o":["MBBS degree of indian universities","DNB degree","Diploma of CPS","MBBS degree of foreign universities"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2286, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 241, '{"id":2286,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":241,"q":"Length of tibia is ?","o":["10% of height","20% of height","30% of height","40% of height"],"a":1,"e":"Ans. is ''b'' i.e., 20% of height Stature is determined in dismembered body (skeletal remains) by :","pyqMatches":[{"year":"2013","no":662,"q":"Length of tibia is ?","o":["10% of height","20% of height","30% of height","40% of height"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2287, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 242, '{"id":2287,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":242,"q":"Locord''s system is ?","o":["Podography","Dactylography","Poroscopy","Cheiloscopy"],"a":2,"e":"Ans. is ''c'' i.e., Poroscopy Dactylography (Galton''s system) —> Study of finger prints. Poroscopy (Locard''s system) -4 Study of number, sizes and distribution of pores of sweat glands on ridges (used when only a part of finger print is available). Podogram --> Study of foot print. Cheiloscopy (queiloscopy) —> Study of lip prints. Rugoscopy (Palatoprints) Study of anterior part of palate.","pyqMatches":[{"year":"2013","no":659,"q":"Locord''s system is ?","o":["Podography","Dactylography","Poroscopy","Cheiloscopy"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2288, 'Forensic Medicine', 'Forensic Toxicology', 'Moderate', 'Forensic_Medicine', 243, '{"id":2288,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":243,"q":"Putrefaction is delayed in all except ?","o":["Warm moist atmosphere","Carbolic acid poisoning","Anemia","Heavy metals poisoning"],"a":0,"e":"Ans. is ''a'' i.e., Warm moist atmosphere Factors causing delay of putrefaction Temperature <0°C or > 48° C (very high temperature). Dry weather and/or decreased air velocity. More than 2 meter deep grave. Tight clothing. Body in dry soil, and body packed in coffin. Infant not fed. Wasting diseases like anemia. Poisoning : Carbolic acid, ZnC12, strychnine (nux vomica), and heavy metals (arsenic, antimony). In water slower than in air (casper''s dictum). Factors facilitating putrefaction Putrefaction is facilitated by (i) free access of air (ii) moisture and (iii) optimum warnth (10°C - 45° C). Thus decomposition is fast in shallow damp, marshy shallow graves, in bodies without clothes and coffin.","pyqMatches":[{"year":"2013","no":669,"q":"Putrefaction is delayed in all except ?","o":["Warm moist atmosphere","Carbolic acid poisoning","Anemia","Heavy metals poisoning"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2289, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 244, '{"id":2289,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":244,"q":"Brown color of contusion is due to -","o":["Haematodin","Reduced hemoglobin","Haemosiderin","Bilirubin"],"a":2,"e":"Ans. is ''c'' i.e., Haemosiderin Color change and age of bruise (Contusion) After a bruise has appeared, it tends to get smaller from periphery to center and passes through a series of colour changes. These are due to disintegration of RBCs by hemolysis and breakdown of hemoglobin into the pigments haemosiderin, haematodin and bilirubin changes are : -","pyqMatches":[{"year":"2013","no":678,"q":"Brown color of contusion is due to","o":["Haematodin","Reduced hemoglobin","Haemosiderin","Bilirubin"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2290, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 245, '{"id":2290,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":245,"q":"Which is incorrect about exit wound of a bullet ?","o":["Bevelled","Everted","Abrasion collar","No COHb"],"a":2,"e":"Ans. is ''c'' i.e., Abrasion collar","pyqMatches":[{"year":"2013","no":685,"q":"Which is incorrect about exit wound of a bullet ?","o":["Bevelled","Everted","Abrasion collar","No COHb"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2291, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 246, '{"id":2291,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":246,"q":"Diagnostic of antemortum drowning ?","o":["Palatauf''s hemorrhage","Weeds and grass in clenched hands","Emphysema aquosum","Water in esophagus"],"a":1,"e":"Ans. is ''b'' i.e., Weeds and grass in clenched hands","pyqMatches":[{"year":"2013","no":699,"q":"Diagnostic of antemortum drowning ?","o":["Palatauf''s hemorrhage","Weeds and grass in clenched hands","Emphysema aquosum","Water in esophagus"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2292, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 247, '{"id":2292,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":247,"q":"Difference between contusion and post- mortem lividity is that post-mortem lividity ?","o":["Shows sequential color change","Easily washable","Shows diffuse irregular margins","Has raised enzyme levels"],"a":1,"e":"Ans. is ''b'' i.e., Easily washable","pyqMatches":[{"year":"2013","no":670,"q":"Difference between contusion and post- mortem lividity is that post-mortem lividity ?","o":["Shows sequential color change","Easily washable","Shows diffuse irregular margins","Has raised enzyme levels"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2293, 'Forensic Medicine', 'Injuries & Wounds', 'Hard', 'Forensic_Medicine', 248, '{"id":2293,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Hard","source":"Forensic_Medicine","sourceNo":248,"q":"All are immediate causes of death in a case of burn, except ?","o":["Suffocation","Embolism","Injury","Sepsis"],"a":3,"e":"Ans. is ''d'' i.e., Sepsis Causes of death in burns Causes of death in burns may be divided into :","pyqMatches":[{"year":"2013","no":708,"q":"All are immediate causes of death in a case of burn, except ?","o":["Suffocation","Embolism","Injury","Sepsis"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2294, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 249, '{"id":2294,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":249,"q":"Raygat''s test is used for ?","o":["Weight of lung","Specific gravity of lung","Consistency of lung","None"],"a":1,"e":"Ans. is ''b'' i.e., Specific gravity of lung Hydrostatic test (Raygat''s test, 1\" life test) : The specific gravity of a non-respired lung is 1040-1050 and of a respired lung is 940-950, so, after respiration lung floats on water (specific gravity of water is 1000). False positive hydrostatic test may occur (i.e.non-respired lung may float) in decomposition and in attempted artificial respiration. False negative hydrostatic test (i.e. respired lung may sink down) may occur in atelectasis, pulmonary oedema, bronchopneumonia, and congenital syphylis.","pyqMatches":[{"year":"2013","no":701,"q":"Raygat''s test is used for ?","o":["Weight of lung","Specific gravity of lung","Consistency of lung","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2295, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 250, '{"id":2295,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":250,"q":"Tache noire de salenortica is a postmortem finding is related to","o":["Eye","Muscle","Hair","Semen"],"a":0,"e":"Brownish discolouration of the sclera due to cellular debris and dust- Tache noire","pyqMatches":[{"year":"2015","no":632,"q":"Tache noire de salenortica is a postmortem finding is related to","o":["Eye","Muscle","Hair","Semen"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2296, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 251, '{"id":2296,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":251,"q":"1st affected in rigor mortis","o":["Eyelids","Myocardium","Jaw","Neck"],"a":1,"e":"Answer-B. Myocardium state of the muscles in a dead body when they become stiff or rigid with some degree of shortening. All muscles of body are involved i.e. voluntary or involuntary. However, it does not start in all muscles simultaneously (nysten’s rule). Involuntary muscles (heart) are involved first than voluntary muscles. Sequence of muscles involvement is as follows: Heart> upper eyelid> neck > jaw>face > chest > upper limb > abdomen > lower limb > finger and toes.","pyqMatches":[{"year":"2019","no":102,"q":"1st affected in rigor mortis","o":["Eyelids","Myocardium","Jaw","Neck"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2297, 'Forensic Medicine', 'Medical Jurisprudence', 'Easy', 'Forensic_Medicine', 252, '{"id":2297,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":252,"q":"Punishment for perjury is under which section IPC ?","o":["Sec 193","Sec 191","Sec 197","Sec 190"],"a":0,"e":"Answer A. Sec 193 Defines punishment for fabricating false evidence The witness is liable to be prosecuted for perjury, and the imprisonment may extend upto seven years. 193 IPC : punishment for false evidence, (punishment for perjury) : imprisonment upto 7 years + hne IgI IpC : (i) Giving false evidence (perjury) under oath. I92 IPC: Fabricating false evidence (perjury)","pyqMatches":[{"year":"2019","no":103,"q":"Punishment for perjury is under which section IPC ?","o":["Sec 193","Sec 191","Sec 197","Sec 190"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2298, 'Forensic Medicine', 'Forensic Toxicology', 'Moderate', 'Forensic_Medicine', 253, '{"id":2298,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":253,"q":"Gastric lavage is not contraindicated after ingestion of which acid.","o":["HCL","H2SO4","Carbolic acid","Nitric acid"],"a":2,"e":"Answer-C. Carbolic Acid The only obsolute contraindication is corrosive poisoning i.e alkalis, mineral acid, vegetable acid and organic acids (except carbolic acid). Carbolic acid is the only corrosive in which gastric lavage can be used. Gastric lavage must be done (except when contraindicated) irrespective of whether vomiting has occured or not, to prevent aspiration of content. Carbolic acid is the only corrosive in which gastric lavage is not contraindicated.","pyqMatches":[{"year":"2019","no":104,"q":"Gastric lavage is not contraindicated after ingestion of which acid.","o":["HCL","H2SO4","Carbolic acid","Nitric acid"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2299, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 254, '{"id":2299,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":254,"q":"Viscera in toxicology stored in","o":["Glycerine","Rectified spirit","Formalism","Saturated salt solution"],"a":3,"e":"Answer-D. Saturated salt solution Toxicological viscera is preserved in a saturated solution of common salt (sodium chloride). For toxicological analysis, viscera is never preserved in alcohol, formalin, or bile salt. In fact, formalin denatures proteins and chemicai toxins and would interfere with the detection of poisons during chemical analysis’","pyqMatches":[{"year":"2019","no":105,"q":"Viscera in toxicology stored in","o":["Glycerine","Rectified spirit","Formalism","Saturated salt solution"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2300, 'Forensic Medicine', 'Forensic Identification', 'Moderate', 'Forensic_Medicine', 255, '{"id":2300,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":255,"q":"Two identical twins will not have same","o":["Fingerprints","DNA copies","Iris color","Blood group"],"a":0,"e":"Answer: A. Fingerprints Identical twins have the same DNA, but their fingerprints (dactylography) are still diferent and they do not change. These can be easily used to differentiate between an identical set of twins. Identical twins have the same set of DNA, therefore DNA fingerprinting cannot differentiate them.","pyqMatches":[{"year":"2019","no":106,"q":"Two identical twins will not have same","o":["Fingerprints","DNA copies","Iris color","Blood group"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2301, 'Forensic Medicine', 'Injuries & Wounds', 'Moderate', 'Forensic_Medicine', 256, '{"id":2301,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":256,"q":"In Alleged history of gun shot injury.there is burning, blackening, tattooing around the wound Dirt collar, the injury is","o":["Close shot entry wound","Close shot exit wound","Distant shot entry wound","distant shot exit wound"],"a":0,"e":"Answer: A. Close shot entry wound Buring, blackening, tattooing around the wound are features of close shot entry. And may occur in contact shot when muzzle end is not pressed firmly. The muzzle end is not pressed firmly or is loosened by recoil, flame, gas and soot may escape sideways and soil the adjoining skin…… Parikh. Grease collar or dirt collar is seen at firearm entry wound. It is a black colored ring lining the entrance wound on the skin. It is produced by removal of substances from the bullet as it passes_through the skin,","pyqMatches":[{"year":"2019","no":107,"q":"In Alleged history of gun shot injury.there is burning, blackening, tattooing around the wound Dirt collar, the injury is","o":["Close shot entry wound","Close shot exit wound","Distant shot entry wound","distant shot exit wound"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2302, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 257, '{"id":2302,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":257,"q":"A child is having Battered baby syndrome how will you identify","o":["Stab wound","Gunshot wound","Bruise of different ages","None of these"],"a":2,"e":"Ans-C. Bruise of different ages A battered child is one who has received repetitive physical injuries as a result of non-accidental violence produced by a parent or a guardian. multiple bruise present over body, Laceration of the oral mucosa, Parents give vague history of accident to be the cause of the injuries. It is also called Caffey syndrome, Caffey-Kempe syndrome, maltreatment syndrome or Parent-infant traumatic stress syndrome The injuries may be caused by hand, foot, teeth, stick, belt, shoe, hot water, lighted cigarette, hot frying pan or any household article Accidental injuries typically involve bony prominences [head (forehead, occipital or parietal region), nose, chin, palm, elbows, knees and shin], match the history given by the parents and are keeping with the development of the child","pyqMatches":[{"year":"2019","no":108,"q":"A child is having Battered baby syndrome how will you identify","o":["Stab wound","Gunshot wound","Bruise of different ages","None of these"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2303, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 258, '{"id":2303,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":258,"q":"Degloving skin involves removal of?","o":["skin , subcutaneous fat, fascia, muscle","skin, subcutaneous fat, fascia","skin only","skin subcutaneous fat"],"a":3,"e":"Answer: D. skin subcutaneous fat The clinical entity of degloving injury means that the skin has been lost, but the musculoskeletal unit is intact, and hence, the movements of the part have been preserved. Degloving, also called avulsion, is a type of severe injury that happens when the top layers of your skin and tissue are ripped from the underlying muscle, connective tissue, or bone. It can affect any body part, but it’s more common in the legs Depending on the angle that the tire pullas across the extremity, the skin and subcutaneous tissue may be pulled or sheared off on leading edge of extremity.","pyqMatches":[{"year":"2019","no":100,"q":"Degloving skin involves removal of?","o":["skin , subcutaneous fat, fascia, muscle","skin, subcutaneous fat, fascia","skin only","skin subcutaneous fat"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2304, 'Forensic Medicine', 'Sexual Offences', 'Easy', 'Forensic_Medicine', 259, '{"id":2304,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":259,"q":"Sexual perversions(Exhibitionism) is under section","o":["Section 290","Section 294","Section 230","Section 291"],"a":1,"e":"Answer: B. Section 294 EXHIBITIONISM: sexual gratification by exposing one’s genitalia. Punishable under sec 294 I.P.C.with imprisonment upto 3 months or fine","pyqMatches":[{"year":"2019","no":101,"q":"Sexual perversions(Exhibitionism) is under section","o":["Section 290","Section 294","Section 230","Section 291"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2305, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 260, '{"id":2305,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":260,"q":"Xiphoid fuses with sternum by what age ?","o":["30 years","35 years","40 years","45 years"],"a":2,"e":"Ans. is ''c'' i.e., 40 years [Ref Parikh 6th le p. 2.30, 2.31] Sternum Pieces of body unite between 14-25 years. Xiphoid unites with body at 40 years. Manubrium unites with body at 60 years. Other bones Hyoid : greater cornu unites with body at 40-60 years. Laryngeal and costal cartilages ossify after 40 years. Vertebra : Osteophytes outgrowth, lipping of vertebra and disc atrophy occur.","pyqMatches":[{"year":"2014","no":41,"q":"Xiphoid fuses with sternum by what age ?","o":["30 years","35 years","40 years","45 years"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2306, 'Forensic Medicine', 'Medical Jurisprudence', 'Easy', 'Forensic_Medicine', 261, '{"id":2306,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":261,"q":"Sections 312 to 315 deal with ?","o":["Kidnapping & abduction","Attention & abetment to suicide","Causing grievous hurt","Criminal abortion"],"a":3,"e":"Ans. is D. i.e., Criminal abortion 312, 313, 314 and 315 IPC: For causing voluntary miscarriage (criminal abortion). 312 IPC: Causing miscarriage with consent (3 years of imprisonment ± fine). 313 IPC: Causing miscarriage without consent of lady (10 years of imprisonment which can extend up to life ± fine). 314 IPC: Death of patient caused by miscarriage (10 years of imprisonment ± fine). 315 IPC: Death of child during miscarriage (10 years imprisonment ± fine).","pyqMatches":[{"year":"2013","no":641,"q":"Sections 312 to 315 deal with ?","o":["Kidnapping & abduction","Attention & abetment to suicide","Causing grievous hurt","Criminal abortion"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2307, 'Forensic Medicine', 'Thanatology', 'Moderate', 'Forensic_Medicine', 262, '{"id":2307,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":262,"q":"Post mortem lividity is not seen in ?","o":["Drowning in well","Drowning in a fast flowing river","Postmortem submersion","Drowning in chlorinated swimming pool"],"a":1,"e":"Ans. is ''b'' i.e., Drowning in a fast flowing river [Ref Parikh 6th/e p.3.10]","pyqMatches":[{"year":"2016","no":638,"q":"Post mortem lividity is not seen in ?","o":["Drowning in well","Drowning in a fast flowing river","Postmortem submersion","Drowning in chlorinated swimming pool"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2308, 'Forensic Medicine', 'Sexual Offences', 'Moderate', 'Forensic_Medicine', 263, '{"id":2308,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":263,"q":"Sexual gratification of a women is obtained by another woman is called ?","o":["Tribadism","Bestiality","Fellatio","Cunnilingus"],"a":0,"e":"Ans. is ''a'' i.e.,Tribadism [Ref Parikh 6th/e p. 5.50, 5.52; Reddy 31\"/e p. 401; Rao 2\"''Ile p. 373-74; Rajes Bardale 1\"/e p. 325-26] Tribadism (Lesbianism or female homosexuality) : Sexual gratification of a women is obtained by another woman by kissing, body contact, manipulation of breast and genitalia. Active partner is called dyke or butch and the passive agent is called femme. This is not an offence in India.","pyqMatches":[{"year":"2015","no":651,"q":"Sexual gratification of a women is obtained by another woman is called ?","o":["Tribadism","Bestiality","Fellatio","Cunnilingus"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2309, 'Forensic Medicine', 'Sexual Offences', 'Easy', 'Forensic_Medicine', 264, '{"id":2309,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":264,"q":"Voyeurism is ?","o":["Sexual gratification by watching the act of sexual intercourse","Use of such objects for sexual gratification","Sexual gratification is by self pain","Sexual gratification by rubbing private part"],"a":0,"e":"Ans. is ''a'' i.e., Sexual gratification by watching the act of sexual intercourse [Ref Reddy 30th/e p. 395] Voyeurism ( Scoptophilia, Peeping tom) : Sexual gratification is obtained by looking at the sexual organs of other persons, watching the act of sexual intercourse, or witnessing undressing by a woman.","pyqMatches":[{"year":"2016","no":661,"q":"Voyeurism is ?","o":["Sexual gratification by watching the act of sexual intercourse","Use of such objects for sexual gratification","Sexual gratification is by self pain","Sexual gratification by rubbing private part"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2310, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 265, '{"id":2310,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":265,"q":"Wrong about dhatura seeds is ?","o":["Kidney shaped","Odourless","Yellow brown","Convex smooth surface"],"a":3,"e":"Ans. is ''d'' i.e.,Convex smooth surface [Ref Pilley 4th/e p. 207; Gautam Biswas 2\"d /e p. 496] Features of Dhatura sees are :-","pyqMatches":[{"year":"2016","no":668,"q":"Wrong about dhatura seeds is ?","o":["Kidney shaped","Odourless","Yellow brown","Convex smooth surface"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2311, 'Forensic Medicine', 'Medical Jurisprudence', 'Easy', 'Forensic_Medicine', 266, '{"id":2311,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":266,"q":"Adultery is described under which section of IPC?","o":["314","375","497","504"],"a":2,"e":"Ans. is c'' i.e., 497 [Ref Women and the Law p. 167] Section 497 of IPC says, \"Whoever has sexual intercourse with a person who is and whom he knows or has reason to believe to be the wife of another man, without the consent or connivance of that man, such sexual intercourse not amounting the offence of rape, is guilty of the offence of adultery and shall be punished.","pyqMatches":[{"year":"2016","no":619,"q":"Adultery is described under which section of IPC?","o":["314","375","497","504"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2312, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 267, '{"id":2312,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":267,"q":"Use of dangerous weapon is related to which section of IPC?","o":["304","319","322","324"],"a":3,"e":"Ans. is ''D'' i.e., 324 319 IPC : Defines hurt. 320 IPC : Defines grievous hurt. 321 IPC : Voluntarily causing hurt. 322 IPC : Voluntarily causing grievous hurt. 323 IPC : Punishment for voluntarily causing hurt (no provocation, no dangerous weapon) (1 years imprisonment). 324 IPC : Punishment for voluntarily causing hurt by dangerous weapon (3 years imprisonment ± fine). 325 IPC : Punishment for voluntarily causing grievous hurt (no provocation, no dangerous weapon) (7 years imprisonment ± fine).","pyqMatches":[{"year":"2016","no":620,"q":"Use of dangerous weapon is related to which section of IPC?","o":["304","319","322","324"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2313, 'Forensic Medicine', 'Sexual Offences', 'Easy', 'Forensic_Medicine', 268, '{"id":2313,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":268,"q":"Outraging modesty of women is which section of IPC?","o":["375","354","195","304"],"a":1,"e":"Ans. is ''b'' i.e., 354 [Ref Reddy 26th/e p. 365] Rape and other sexual offences and assault 228 IPC : Prohibits disclosure of identity of rape victim. 375 IPC : Defining rape. 376 IPC : Punishment for rape (7 years to life imprisonment ± fine). 376-A IPC : Punishment for marital rape (2 years imprisonment ± fine). 377 IPC: Unnatural sexual offences (10 years to life imprisonment ± fine). 354 IPC : Assault or criminal force to woman with intent to outrage her modesty. 366-A IPC : Procuration of minor girl for illicit intercourse. 351 IPC : Defines assault. 352-358 IPC : Punishment for causing assault. 509 IPC : Word, gesture or act intended to insult the modesty of a women","pyqMatches":[{"year":"2016","no":622,"q":"Outraging modesty of women is which section of IPC?","o":["375","354","195","304"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2314, 'Forensic Medicine', 'Medical Jurisprudence', 'Easy', 'Forensic_Medicine', 269, '{"id":2314,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":269,"q":"Section 89 IPC is for?","o":["Criminal responsibility of insane","Criminal responsibility of a child","Criminal responsibility of drunken person","Age for consent"],"a":1,"e":"Ans. is'' i.e., Criminal responsibility of a child 89 IPC: A child under 12 years of age can not be given valid consent to suffer any harm which can occur from an act done in good faith for the benefit of the child, e.g., consent for surgery. The only guardian can give such consent. An act is done in good faith for the benefit of a child or insane person, by or by consent of the guardian. Nothing which is done in good faith for the benefit of a person under twelve years of age, or of unsound mind, by or by consent, either express or implied, of the guardian or other person having lawful charge of that person, is an offence because of any harm which it may cause, or be intended by the doer to cause or be known by the doer to be likely to cause to that person","pyqMatches":[{"year":"2016","no":623,"q":"Section 89 IPC is for?","o":["Criminal responsibility of insane","Criminal responsibility of a child","Criminal responsibility of drunken person","Age for consent"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2315, 'Forensic Medicine', 'Medical Jurisprudence', 'Moderate', 'Forensic_Medicine', 270, '{"id":2315,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":270,"q":"A person is declared dead if he/she is not found for","o":["7 years","10 years","14 years","21 years"],"a":0,"e":"Ans. is ''a'' i.e.,7 years [Ref Civil Law, Section 108 MA] The Indian Evidence Act, under section 108 provides 7 years from the date whence a person is declared to be missing and his","pyqMatches":[{"year":"2016","no":624,"q":"A person is declared dead if he/she is not found for","o":["7 years","10 years","14 years","21 years"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2316, 'Forensic Medicine', 'Medical Jurisprudence', 'Easy', 'Forensic_Medicine', 271, '{"id":2316,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":271,"q":"Adulteration of drug is under which section of IPC","o":["271","272","273","274"],"a":3,"e":"Ans. is ''d'' i.e., 274 [Ref Safety Management of Hospitals p. 315; Principles of FMT, Bardale p. 18] Law related to Adulteration :- Indian Penal Code :? Section 272 → Adulteration of Food or Drink Intended for Sale Imprisonment for 6 months, Fine - Rs. 1000 Section 273 → Sale of Noxious Food or Drink Imprisonemnt for 6 months, fine - Rs. 1000 Section 274 → Adulteration of Drugs Section 275 → Sale of aduletrated drugs Section 276 → Sale of drugs as a different drug or preparation Section 277 → Fouling water of public spring or reservoir","pyqMatches":[{"year":"2016","no":625,"q":"Adulteration of drug is under which section of IPC","o":["271","272","273","274"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2317, 'Forensic Medicine', 'Sexual Offences', 'Easy', 'Forensic_Medicine', 272, '{"id":2317,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":272,"q":"First carpal bone to appear is?","o":["Trapezium","Capitate","Pisiform","Lunate"],"a":1,"e":"Ans. is ''B'' i.e., Capitate [Ref Reddy''s Essentials 26th/e p. 63] The ossification centres in carpal bones appear as follows : n Capitate 1 year n Hamate 2 years n Triquitrum 3 years n Lunate 4 years n Scaphoid and trapezoid 5 years n Trapezium6 years n Pisiform 11 years","pyqMatches":[{"year":"2013","no":1,"q":"First carpal bone to appear is?","o":["Trapezium","Capitate","Pisiform","Lunate"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2016","no":627,"q":"First carpal bone to appear is?","o":["Trapezium","Capitate","Pisiform","Lunate"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2013","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2318, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 273, '{"id":2318,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":273,"q":"Holograph will is defined as","o":["Doctor dictates and written by relatives","Testator is written in his own handwriting","Testator is dictated and written by relatives","Testator is dictated and written by doctor"],"a":1,"e":"Ans. is ''b'' i.e.,Testator is written in his own handwriting [Ref SK Singhal 4th/e p. 314] Holograph will is one which is written by the testator in his own handwritting. Testamentary capacity is defined as the capacity of a person to make a valid will.","pyqMatches":[{"year":"2016","no":630,"q":"Holograph will is defined as","o":["Doctor dictates and written by relatives","Testator is written in his own handwriting","Testator is dictated and written by relatives","Testator is dictated and written by doctor"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2319, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 274, '{"id":2319,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":274,"q":"Obtuse angle of mandible is seen in","o":["Infancy","Adulthood","Adult Male","Adult Female"],"a":0,"e":"Ans. is ''a'' i.e., Infancy [Ref Parikh 6th le p. 2.30] Feature Infancy Adult Old age Angle of mandible Obtuse angle Right angle Obtuse angle Mental foramen opening Near lower border Midway b/w upper Looks apparently nearer the of body & lower border upper border d/t loss of teeth","pyqMatches":[{"year":"2016","no":632,"q":"Obtuse angle of mandible is seen in","o":["Infancy","Adulthood","Adult Male","Adult Female"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2320, 'Forensic Medicine', 'Sexual Offences', 'Moderate', 'Forensic_Medicine', 275, '{"id":2320,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":275,"q":"Size of the fetus is 20 mm, then by the rule of Hasse’s, what is the gestational age of the fetus?","o":["2 weeks","4 weeks","6 weeks","8 weeks"],"a":2,"e":"Ans. is ''c'' i.e.,6 weeks Hess''s rule (Haase''s rule): It is a rough method for calculating the age of fetus by measuring the length from crown to heel. Up to 5th month of gestation, length of the foetus in cm is square of the month of gestation and beyond 5 months, length in cm is 5 times the month of gestation. Length in cm = (month of pregnancy) → upto 5 months Length in cm = month of pregnancy → after 5 months In this question : Length in cm = (month of pregnancy)2 2 = (month of pregnancy) → (Note : 20mm = 2cm) Month of pregnancy = 14 months or 6 weeks.","pyqMatches":[{"year":"2016","no":633,"q":"Size of the fetus is 20 mm, then by the rule of Hasse’s, what is the gestational age of the fetus?","o":["2 weeks","4 weeks","6 weeks","8 weeks"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2321, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 276, '{"id":2321,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":276,"q":"First incisor to erupt is","o":["Lower central","Upper central","Lower lateral","Upper lateral"],"a":0,"e":"Ans. is ''a'' i.e.,Lower central [Ref Reddy 30thie p. 60] First temporary tooth to upper (in primary dentition) is lower central incisors and last temporary tooth to erupt is2nd molar. The sequence of eruption is lower central incisor > upper central incisor > upper lateral incisor >lower lateral incisor > I\" molar > Canine > molar. Therefore eurption of temporary teeth is completed by eruption of 2\"° molar at 25 months (2 years). First permanent tooth to erupt (in secondary dentition) is 1\" molar and last to erupt is 3rd molar. The sequence of eruption is 1\" molar > central incisor > lateral incisor > 1\" premolar > 2\" premolar > canine > 2\" molar > 3rd molar. Eruption of permanent teeth is completed by eruption of 3rd molar between 17-25 years.","pyqMatches":[{"year":"2016","no":634,"q":"First incisor to erupt is","o":["Lower central","Upper central","Lower lateral","Upper lateral"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2322, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 277, '{"id":2322,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":277,"q":"X-ray of choice for age detection at around 16-17 years of age","o":["Elbow","Wrist","Shoulder","Pelvis"],"a":1,"e":"Ans. is ''b'' i.e., Wrist [Ref Parikh 6th/e p. 2.10] Site Age (in years) Female Male Elbow 13-14 15-16 Wrist 16-17 18-19 Shoulder 17-18 19-20 Crest of ilium18-19 20-21","pyqMatches":[{"year":"2016","no":636,"q":"X-ray of choice for age detection at around 16-17 years of age","o":["Elbow","Wrist","Shoulder","Pelvis"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2323, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 278, '{"id":2323,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":278,"q":"Suggilation is due to which of the following?","o":["Gravity leading to pooling of blood","Escape of blood from microvasculature","Molecular death leading to stiffening of muscles","Autolysis of enzymes"],"a":0,"e":"Ans. is ''a'' i.e., Gravity leading to pooling of blood [Ref Reddy 30th/e p. 141] Gravity leading to pooling of blood → Suggilation Molecular death leading to stiffening of muscles → Rigor Mortis Autolysis of enzymes → Putrefaction","pyqMatches":[{"year":"2016","no":640,"q":"Suggilation is due to which of the following?","o":["Gravity leading to pooling of blood","Escape of blood from microvasculature","Molecular death leading to stiffening of muscles","Autolysis of enzymes"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2324, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 279, '{"id":2324,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":279,"q":"Earliest sign of fetal death -","o":["Spalding sign","Robert''s sign","Ball sign","Adipocere formation"],"a":1,"e":"Ans. is ''b'' i.e., Robert''s sign [Ref Parikh 6th le p. 5.75, 5.76 & 4th/e p. 268] Robert sign (gas in great vessels) → 12h Spalding sign (overlapping of skull bones) → 1 week Blair-Hartley/Ball sign (hyperflexion/hyperextension → 3-4 weeks of spine with overcrowding of ribs","pyqMatches":[{"year":"2016","no":641,"q":"Earliest sign of fetal death","o":["Spalding sign","Robert''s sign","Ball sign","Adipocere formation"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2325, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 280, '{"id":2325,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":280,"q":"First sign of maceration is","o":["Robert''s sign","Skin slippage","Spalding sign","Greenish discoloration of body"],"a":1,"e":"Ans. is ''b'' i.e., Skin slippage [Ref Parikh 6\"Ve p. 5.75; SK Parikh 4th/e p. 268] Maceration is a process of aseptic autolysis. It occurs when a dead fetus remains in the uterus for 3-4 days surrounded by liquor amnii but with exclusion of air. Skin slippage is the earliest sign (occurs within 12 hours).","pyqMatches":[{"year":"2016","no":642,"q":"First sign of maceration is","o":["Robert''s sign","Skin slippage","Spalding sign","Greenish discoloration of body"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2326, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 281, '{"id":2326,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":281,"q":"Which is the best temperature for putrefaction?","o":["- 10 degrees C","0 degrees C","30 degrees C","50 degrees C"],"a":2,"e":"Ans. is ''c'' i.e., 30 degrees C [Ref Reddy 30th/e p. 150] Putrefaction is the last stage in resolution of body from the inorganic to organic state and is a certain sign of death. The putrefaction is due to : Autolysis : The enzymes of the body, break down the dead body causing proteolysis, lipolysis and glycolysis. Bacterial enzymes : Aerobic and anaerobic bacteria present in small intestine (e.g. C. welchii, staphylococcus, E.coli etc.) release enzymes (especilly lipase and lecithinase), which act on body to cause breakdown. Three conditions are necessory for putrefaction : (i) warmth (10-45°), (ii) moisture (humidity) and (iii) air. If air is absent, adipocere formation (saponification) occurs, and in the absence of moisture, mummification occurs.","pyqMatches":[{"year":"2016","no":643,"q":"Which is the best temperature for putrefaction?","o":["10 degrees C","0 degrees C","30 degrees C","50 degrees C"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2327, 'Forensic Medicine', 'Thanatology', 'Moderate', 'Forensic_Medicine', 282, '{"id":2327,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":282,"q":"According to Casper''s dictum, decomposition is the fastest when the body is in which of the following?","o":["Air","Water","Earth","Soil"],"a":0,"e":"Ans. is ''a'' i.e., Air [Ref Reddy 30thie p. 155] It is the effect of medium (in which body lies) on rate of putrefaction. Casper''s dictum states that a body decomposes in air twice as rapidly as in water and eight times as rapidly in earth.","pyqMatches":[{"year":"2016","no":644,"q":"According to Casper''s dictum, decomposition is the fastest when the body is in which of the following?","o":["Air","Water","Earth","Soil"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2328, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 283, '{"id":2328,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":283,"q":"Enzyme responsible for postmortem hemolysis is","o":["Hemolysin","Lecithinase","Lipoproteinase","Protease"],"a":1,"e":"Ans. is ''b'' i.e., Lecithinase [Ref Textbook of FMT by Vij 5th/e p. 89] Bacteria produce a large variety of enzymes that act on carbohydrates, proteins and fats and break down the various tissues. One of the most important enzymes is the lecithinase'' produced by the Clostridium welchii, which hydrolyses the lecithin present in all the cell membranes including blood cells and thus is responsible for producing hemolysis of blood postmortem. This enzyme also helps in postmortem hydrolysis and hydrogenation of body fat.","pyqMatches":[{"year":"2016","no":645,"q":"Enzyme responsible for postmortem hemolysis is","o":["Hemolysin","Lecithinase","Lipoproteinase","Protease"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2329, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 284, '{"id":2329,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":284,"q":"Gun powder on body and clothing can be visualized by?","o":["Harrison and Gilroy test","Neutron activation analysis","Dermal nitrate test","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above [Ref Parikh ele p. 4.39] Tests used in firearm discharge : Based on detection of nitrate : Dermal nitrite (Paraffin) test. Based on detection of heavy metal : Harrison and Gilroy test, neutron activation analysis, Atomic obsorption spectroscopy, and flameless atomic absorption spectroscopy.","pyqMatches":[{"year":"2016","no":650,"q":"Gun powder on body and clothing can be visualized by?","o":["Harrison and Gilroy test","Neutron activation analysis","Dermal nitrate test","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2330, 'Forensic Medicine', 'Injuries & Wounds', 'Moderate', 'Forensic_Medicine', 285, '{"id":2330,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":285,"q":"Bullet fixed from a gun is not released. It is ejected out with subsequent shot. Such a bullet is called as","o":["Tandem bullet","Dum - dum bullet","Inceridiary bullet","Tumbling bullet"],"a":0,"e":"Ans. is ''a'' i.e., Tandem bullet [Ref SK Singhal 4thle p. 188] Varieties of bullets are :- i) Incendiary (igniting) bullet : The tip of bullet contains self igniting material e.g. barium nitrate and powdered aluminium and magnesium (in the past, phosphorus was used), so that it catches fire on hitting the target. It is used to cause fire in usually inflammable targets like fuel tanks (of air crafts etc). ii) Explosive bullet : The tip contains a detonator or lead azide, so that the bullet explodes on hitting the target. iii) Dum-dum bullet (expanding bullet): It is a jacketed bullet with is nose tip chiseled or cut off It is designed to increase in diameter and expand upon striking the target, thus producing larger diameter wounds of limited penetration. iv) Tandem bullet (Piggey tail bullet) : It is called one-behind-other bullet because two bullets are ejected one after the other, when first bullet failed to leave the burrel and is ejected by subsequently fired bullet. Therefore, both enter body through same enterance wound (some times, they may enter through different entries), but the wounds of exit are always two.","pyqMatches":[{"year":"2016","no":651,"q":"Bullet fixed from a gun is not released. It is ejected out with subsequent shot. Such a bullet is called as","o":["Tandem bullet","Dum - dum bullet","Inceridiary bullet","Tumbling bullet"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2331, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 286, '{"id":2331,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":286,"q":"Which of the following causes maximum damage?","o":["Tandem","Dumdum","Souvenir","Piggy"],"a":1,"e":"Ans. is ''b'' i.e., Dumdum [Ref SK Singhal e/e p. 188] Expanding bullets, also known as hollow-point bullets or \"dum- dums\", are designed to \"mushroom\" upon entering a target in order to stop it from leaving the body. Compared to regular bullets, or full metal jack ammunition, expanding bullets are intended to cause maximum tissue damage.","pyqMatches":[{"year":"2016","no":652,"q":"Which of the following causes maximum damage?","o":["Tandem","Dumdum","Souvenir","Piggy"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2332, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 287, '{"id":2332,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":287,"q":"A bullet packed with jacket and opens at a base is called","o":["Dum dum bullet","Tandem bullet","Duplex bullet","Souvenir bullet"],"a":0,"e":"Ans. is ''a'' i.e., Dum dum bullet [Ref Parikhp. 4.33]","pyqMatches":[{"year":"2016","no":653,"q":"A bullet packed with jacket and opens at a base is called","o":["Dum dum bullet","Tandem bullet","Duplex bullet","Souvenir bullet"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2333, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 288, '{"id":2333,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":288,"q":"Ricochet bullet is","o":["Bullet producing a key hole entry wound","Bullet with nose tip chiseled off","Deviation in the direction or path of bullet","Bullet containing igniting material"],"a":2,"e":"Ans. is ''c'' i.e., Deviation in the direction or path of bullet [Ref Reddy 30th/e p. 211] Ricochetting of bullet is defined as deviation in the direction or path of bullet because of striking of bullet to an intermediary object.","pyqMatches":[{"year":"2016","no":654,"q":"Ricochet bullet is","o":["Bullet producing a key hole entry wound","Bullet with nose tip chiseled off","Deviation in the direction or path of bullet","Bullet containing igniting material"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2334, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 289, '{"id":2334,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":289,"q":"Compound used as primer in weapon is","o":["Potassium chlorate","Sulphur","Potassium nitrate","Nitrocellulose"],"a":0,"e":"Ans. is ''a'' i.e., Potassium chlorate [Ref Parikh 6th/e p. 4.29] Cartridge (round) Cartridge is the ammunition used in firearms. Cartridge consists of (i) Cartridge case, (ii) Propellant (gun powder), (iii) Projectile (missile) and (iv) Wads (only in shot guns.). 1) Cartridge case It is the outer shell or covering of the cartridge. In shotgun it is cylinderical. Base is of brass and rest of it is of cardboard or plastic. In rifled weapons, it is tapering and whole of it is made of brass or steel. Center of base has percussion cap (detonator cap) which has sensitive composition, i.e. primer, consisting of potassium chlorate, antimony sulphide, mercury fulminate, barium nitrite, lead peroxide or tetrazene. In all weapons, after firing, the cartridge case remains in the barrel and it is to be taken out manually (shotgun, revolvers, rifle) or it is ejected out automatically, e.g. in pistals. 2) Propellent (gun powder) It propels the projectile (missile) forward. It is composed of black powder or smokeless powder in the form of grains, pellets, thin cylindrical cords or flakes. Its ignition results in formation of expanding hot gases under pressure which (gas pressure) propels the projectile (missile) by providing it necessary muzzle velocity and striking energy. The classical gun powder is known as black powder, consists of charcol (15%), Sulphur (10%), and potassium nitrate (75%). Depending on fineness, the black gun powder is designated as FG, FFG, FFFG. etc. (F = fineness). Pyrodex is another gun powder with same components, but with different ratios. Black gun powder produces smoke, i.e. It is smoke producing powder. Smokeless powder, in addition to black powder, has nitrocellulose (single base), or nitrocellulose plus nitroglycerine (double base), or nitrocellulose plus nitroglycerine plus nitroguanidine (triple base). Semi smokeless powder has 80% black powder and 20% smokeless","pyqMatches":[{"year":"2016","no":655,"q":"Compound used as primer in weapon is","o":["Potassium chlorate","Sulphur","Potassium nitrate","Nitrocellulose"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2335, 'Forensic Medicine', 'Forensic Identification', 'Moderate', 'Forensic_Medicine', 290, '{"id":2335,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":290,"q":"Destructive power of bullet is determined by all except","o":["Velocity of bullet","Weight of bullet","Shape of bullet","Kinetic energy"],"a":2,"e":"Ans. is ''c'' i.e.,Shape of bullet [Ref Reddy 29th le p. 194] Tissue damage (or destructive power of bullet) is dependent on striking (kinetic) energy of bullet, which is proportional to its mass and square of velocity (KE = ''/2 mv2). So modern bullets are designed to have smaller mass allowing transportation of large amount of ammunition and high velocity, as velocity is more important determinant in destructive power of bullet.","pyqMatches":[{"year":"2016","no":656,"q":"Destructive power of bullet is determined by all except","o":["Velocity of bullet","Weight of bullet","Shape of bullet","Kinetic energy"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2336, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 291, '{"id":2336,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":291,"q":"Which of the following is the test done to confirm live born fetus after fetal death?","o":["Mirror test","Breslau''s test","Magnus test","Paraffin test"],"a":1,"e":"Ans. is ''b'' i.e., Breslau''s test [Ref SK Singhal 4th le p. 271] Tests used in infanticide Ploucquet''s test : Weight of lung is measured in relation to body wieght. Before birth weight of lung is 1/70 of body weight and after respiration it becomes 1/35 of body weight due to increased blood flow in lung beds. Static test or Fodere''s test : The average weight of both lungs before respiration is 30-40 gm and after respiration is 60-70 cm. Hydrostatic test (Raygat''s test, 1\" life test) : The gravity of a non-respired lung is 1040-1050 and of a respired lung is 940-950, so, after respiration lung floats on water (specific gravity of water is 1000). Breslau''s second life test : It assumes that a live born child would respire and therefore, would also swallow some air into the stomach and bowel. Hence they float on water. This test is falsely positive in putrefaction (due to putrefied gases) or in cases of attempted artificial respiration. Werdin''s test : Before birth middle ear contains gelatinous embryonic tissue which is replaced by air after respiration.","pyqMatches":[{"year":"2016","no":662,"q":"Which of the following is the test done to confirm live born fetus after fetal death?","o":["Mirror test","Breslau''s test","Magnus test","Paraffin test"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2337, 'Forensic Medicine', 'Forensic Toxicology', 'Moderate', 'Forensic_Medicine', 292, '{"id":2337,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":292,"q":"A couple was locked up in a room with fire around. All of the following are the probable immediate causes of death in such circumstance except:-","o":["Cyanide intoxication","Suffocation","Sepsis","Fat embolism"],"a":2,"e":"Ans. is ''c'' i.e., Sepsis [Ref Reddy 29''/e p. 287; Parikh 6th le p. 4.153] Causes of death in burns Causes of death in burns may be divided into : A) Causes of immediate death : These are (1) neurogenic shock (primary shock), (2) hypovolaemic shock (secondary shock), (3) suffocation, due to inhaled CO, CO2, (4) cyanide intoxication, (5) fat embolism, (6) cerebral or pulmonary edema, and (7) accidental injuries during burn. B) Causes of delayed death : These are : (1) renal failure (acute tubular necrosis), (2) infections (sepsis, gangrene, tetanus) and (3) centrilobular necrosis of liver.","pyqMatches":[{"year":"2016","no":665,"q":"A couple was locked up in a room with fire around. All of the following are the probable immediate causes of death in such circumstance except:","o":["Cyanide intoxication","Suffocation","Sepsis","Fat embolism"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2338, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 293, '{"id":2338,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":293,"q":"True about acid poisoning is","o":["Greatest damage is along the lesser curvature","Corrosives cause vaporization of tissues","Vitriolage means ingestion of acid in empty stomach","Highest chance of perforation is with nitric acid"],"a":0,"e":"Ans. is ''a'' i.e., Greatest damage is along the lesser curvature Magenstrasse is the term applied to the pathway acidic agents follow in stomach. The pathway of acids and alkalis in food filled stomach starts along the lesser curvature of the stomach and leads to the pylorus, which explains the location of greatest damage in food filled stomach. Stomach without food have significant injury in the lower half of two thirds and may have sparing of fundus. Mechanism of action :- Corrosives fix, destroy and erode the surface with which they come in contact. They mainly act locally by : Hygroscopic extraction of water from tissues Coagulation of proteins and Conversion of haemoglobin into hematin. Titriolage'' is throwing of any corrosive on another person. Eyes are affected most commonly. It comes under sector 320 IPS. There are highest chances of perforation of stomach with 11,SO4, among all mineral acids.","pyqMatches":[{"year":"2016","no":669,"q":"True about acid poisoning is","o":["Greatest damage is along the lesser curvature","Corrosives cause vaporization of tissues","Vitriolage means ingestion of acid in empty stomach","Highest chance of perforation is with nitric acid"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2339, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 294, '{"id":2339,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":294,"q":"Highest content of cannabis is found in which part of the plant?","o":["Root","Resin","Seed","Stem"],"a":1,"e":"Ans. is `b'' i.e.,Resin [Ref Reddy 26th /e p. 528] Cannabis, also known as marijuana, is obtained from the Indian Hemp plant or cannabis indica (Cannabis sativa). The active principles of Cannabis are contained in its resin. All parts of the plant, male or female, contain the active material, except stem, root and seeds. The principal constituent of the resin are cannabinol, which has no action. Cannabidiol is also inert, but on exposure to heat, it is partly converted to the very active isomeric tetrahydrocannabinols (THC).","pyqMatches":[{"year":"2016","no":670,"q":"Highest content of cannabis is found in which part of the plant?","o":["Root","Resin","Seed","Stem"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2340, 'Forensic Medicine', 'Forensic Toxicology', 'Moderate', 'Forensic_Medicine', 295, '{"id":2340,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":295,"q":"''Cold Turkey'' term is used to denote which of the following?","o":["Consumption of heroin","Abrupt cessation of heroin","Gradual withdrawal of heroin","Place to withdraw a drug in a group"],"a":1,"e":"Ans. is ''b'' i.e., Abrupt cessation of heroin [Ref Quitting Smoking for Life p. 18] ''Cold Turkey'' means abrupt and complete cessation of taking a drug to which one is addiced. Alcohol is not the only drug whereby quitting cold turkey poses a danger to the patient. People who are addicted to opiates (heroin, methadone, morphine, Suboxone, and even prescription benzodiazepines) are at immense risk if they try to stop their drug intake without a plan.","pyqMatches":[{"year":"2016","no":674,"q":"''Cold Turkey'' term is used to denote which of the following?","o":["Consumption of heroin","Abrupt cessation of heroin","Gradual withdrawal of heroin","Place to withdraw a drug in a group"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2341, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 296, '{"id":2341,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":296,"q":"Smoky stool is seen in which poisoning?","o":["Phosphorus","Arsenic","Lead","Zinc"],"a":0,"e":"Ans. is ''a'' i.e., Phosphorus [Ref Modern Medical Toxicology by Pillay p. 68] Acute poisoning of phosphorus :? Breath smells of garlic. Vomitus and stools may be luminous in the dark. Smoky stool syndrome :- Faint fumes may emanate from the stools. Manifestations of liver damage - tender hepatomegaly, jaundice which may progress to an olive green hue, flapping tremor of hands (asterixis), mousy odour to the breath (foetor hepaticus).","pyqMatches":[{"year":"2016","no":676,"q":"Smoky stool is seen in which poisoning?","o":["Phosphorus","Arsenic","Lead","Zinc"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2342, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 297, '{"id":2342,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":297,"q":"Gigantin is active principle of","o":["Plumbago Rosea","Calotropis","Ricinus Communis","P. Zeylanica"],"a":1,"e":"Ans. is ''b'' i.e., Calotropis [Ref Concise Textbook of FMT - Sharma p. 250] Calotropis gigantea -4 contains active principle named gigantin. When cut, stem and leaves of the plant exrude an acrid milky juice. When this juice is allowed to stand or heated, serum is exuded leaving behind white clot. The serum contains the active principle named gigantin which is very toxic.","pyqMatches":[{"year":"2016","no":677,"q":"Gigantin is active principle of","o":["Plumbago Rosea","Calotropis","Ricinus Communis","P. Zeylanica"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2343, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 298, '{"id":2343,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":298,"q":"Which of the following is true about cocaine metabolite test","o":["Measure benzoylecgonine levels","Used to diagnose cocaine use","Treatment of cocaine overdose","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above [Ref Code of Federal Regulations p. 174] Cocaine and cocaine metabolite test system : A cocaine and cocaine metabolite test system is a device intended to measure cocaine and a cocaine metabolite (benzoylecgoonine) in serum, plasma, and urine. Measurements obtained by this device are used in the diagnosis and treatment of cocaine use or overdose.","pyqMatches":[{"year":"2016","no":678,"q":"Which of the following is true about cocaine metabolite test","o":["Measure benzoylecgonine levels","Used to diagnose cocaine use","Treatment of cocaine overdose","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2344, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 299, '{"id":2344,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":299,"q":"Sodium flouride may be use for preservation of","o":["Cyanide","Arsenic","Alcohol","Urine"],"a":2,"e":"Ans. is ''c'' i.e., Alcohol [Ref Parikh 6th/e p. 2.62; Essentials of forensic medicine & toxicology 23rd/e p. 101] Sodium fluride should be added to urine or vitreous humor, if alcohol estimation is required; and also to samples for analysis for cocaine, cyanides and CO.","pyqMatches":[{"year":"2014","no":710,"q":"Sodium flouride may be use for preservation of","o":["Cyanide","Arsenic","Alcohol","Urine"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2345, 'Forensic Medicine', 'Medical Jurisprudence', 'Easy', 'Forensic_Medicine', 300, '{"id":2345,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":300,"q":"IPC 304B is related to -","o":["Punishment for cruelty by husband or his relatives","Dowry death","Death caused by negligence","Punishment of culpable homicide, not amounting to murder"],"a":1,"e":"Ans. is ''b'' i.e. Dowry death IPC 304 - Punishment of culpable homicide, not amounting to murder IPC 304 A - Death caused by negligence IPC 304 B - Dowry death : 10 years of imprisonment which can extend to life. IPC 498 - Punishment for cruelty by husband or his relatives.","pyqMatches":[{"year":"2015","no":616,"q":"IPC 304B is related to","o":["Punishment for cruelty by husband or his relatives","Dowry death","Death caused by negligence","Punishment of culpable homicide, not amounting to murder"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2346, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 301, '{"id":2346,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":301,"q":"IPC 201 is for -","o":["Punishment for embalming before autopsy","Perjury","Voluntary causing grievous hurt","Kidnapping"],"a":0,"e":"Ans. is ''a'' i.e. Punishment for embalming before autopsy [Ref: Reddy 30th/e p. 11] IPC 201 is for punishment for embalming before autopsy (and also for the disappearance of evidence).","pyqMatches":[{"year":"2015","no":617,"q":"IPC 201 is for","o":["Punishment for embalming before autopsy","Perjury","Voluntary causing grievous hurt","Kidnapping"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2347, 'Forensic Medicine', 'Medical Jurisprudence', 'Easy', 'Forensic_Medicine', 302, '{"id":2347,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":302,"q":"Sec 191 IPC is for -","o":["Medical negligence","Hostile witness","Criminal negligence","Assault punishment"],"a":1,"e":"Ans. is ''b'' i.e. Hostile witness [Ref Reddy 30th /e p. 11] Perjury, Hostile witness and false certificate 191 IPC : (i) Giving false evidence (perjury) under oath and (ii) hostile witness. 192 IPC: Fabricating false evidence (perjury). 193 IPC : Punishment for false evidence (punishment for perjury) : imprisonment upto 7 years + fine. 194 IPC : Giving or fabricating false evidence to procure conviction of capital offence. 195 IPC : Giving or fabricating false evidence to procure conviction of offence punishable with imprisonment for life. 197 IPC : Issuing or signing (attesting) false certificate by a doctor is a criminal offence. 201 IPC : Causing disappearance of evidence.","pyqMatches":[{"year":"2015","no":618,"q":"Sec 191 IPC is for","o":["Medical negligence","Hostile witness","Criminal negligence","Assault punishment"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2348, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 303, '{"id":2348,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":303,"q":"Corona mortis is ?","o":["Is a vascular anastomosis","Post mortem heart & coronary arteries examination","Another term used for rigor mortis","None of the above"],"a":0,"e":"Ans. is ''a'' i.e. Is a vascular anastomosis [Ref BRS Gross Anatomy p. 112] Corona mortis: This is also called as circle of death and refers to vascular ring form by the anastomosis of an aberrant artery with the normal obturator artery arising from a branch of the internal iliac artery. At the time of laparoscopic hernia this vessel is torn both end of vessel can bleed profusely, because both arise from a major artery. The surgeon should remember these anatomic landmarks and the point of mesh fixation should be selected superiorly, laterally and medially.","pyqMatches":[{"year":"2015","no":684,"q":"Corona mortis is ?","o":["Is a vascular anastomosis","Post mortem heart & coronary arteries examination","Another term used for rigor mortis","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2349, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 304, '{"id":2349,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":304,"q":"After death, blood is taken from ?","o":["Femoral vein","Antecubital vein","Jugular vein","Carotid artery"],"a":0,"e":"Ans. is ''a'' i.e. Femoral vein [Ref Forensic Neuropathology p.174] \"Ideally, the blood should be collected from femoral vein distal to clamp or ligature and without milking the calf or thigh\" - Forensic Neuropathology p.174 \"Femoral vein blood sample is preferred over a heart blood sample\" - Water-Related Death Investigation p. 269 Blood for the sample is taken from femoral vein. The jugular or subclavian veins can also be used. 10-20 ml of blood is taken and it is taken before autopsy. 30 ml of blood should be preserved (minimum is 10 ml).","pyqMatches":[{"year":"2015","no":683,"q":"After death, blood is taken from ?","o":["Femoral vein","Antecubital vein","Jugular vein","Carotid artery"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2350, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 305, '{"id":2350,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":305,"q":"True about finger printing is -","o":["Most common type is whorls","Most specific method of identification","Not present at birth","All of the above"],"a":1,"e":"Ans. is ''b'' i.e. Most specific method of identification [Ref Reddy 30thie p. 76] Finger prints are present from birth both on epidermis and dermis, remain constant throughout life and can''t be altered without destroying true skin. Fingers prints are due to papillary or epidermal ''ridges'' on the tips of fingers and thumb. Finger print pattern is absolutely individual i.e. no two hands are entirely alike, not even identical twins. That''s why, it is best (most sensitive and most specific) and most reliable method of identification (Quetelet''s rule of biological variation). Loops (67% most common) > Whorls (25%) > archer (7%) > composite (2% least common) are four main types of pattern. It is accepted that chances of 2 finger prints matching 16 ridge characteristic are infinitely small (Parikh''s). In practice 8-6 points of fine comparision are accepted as proof of identity.","pyqMatches":[{"year":"2015","no":624,"q":"True about finger printing is","o":["Most common type is whorls","Most specific method of identification","Not present at birth","All of the above"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2351, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 306, '{"id":2351,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":306,"q":"Ophitoxemia is ?","o":["Snake venom poisoning","Scorpion bite","Spider bite","Tick bite"],"a":0,"e":"Ans. is ''a'' i.e.,Snake venom poisoning [Ref Ramesh Gupta Zoology book] Ophitoxemia is poisoning by snake venom.","pyqMatches":[{"year":"2015","no":682,"q":"Ophitoxemia is ?","o":["Snake venom poisoning","Scorpion bite","Spider bite","Tick bite"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2352, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 307, '{"id":2352,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":307,"q":"Blisters are absent in ?","o":["Burns","Putrefaction","Arsenic Poisoning","Postmortem caloricity"],"a":3,"e":"Ans is ''d'' i.e., Postmortem caloricity [Ref Reddy03 tive p. 139,140; S.K. Singhal p. 92] There is no blistering in postmortem caloricity. All other conditions are associated with blister formation","pyqMatches":[{"year":"2015","no":680,"q":"Blisters are absent in ?","o":["Burns","Putrefaction","Arsenic Poisoning","Postmortem caloricity"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2353, 'Forensic Medicine', 'Sexual Offences', 'Easy', 'Forensic_Medicine', 308, '{"id":2353,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":308,"q":"Novus actus interveniens is -","o":["Facts speaking for itself","Breaking of chain","Contributory negligence","Therapeutic misadventure"],"a":1,"e":"Ans. is ''b'' i.e. Breaking of chain A person is responsible for his actions and their consequences. This principle applies to cases of assault or accidental injuries. However, sometimes such continuity of events is broken by an entirely new and unexpected happening, due to negligence of some other person, i.e. \"Novus actus interveniens\" (an unrelated action intervening). For example, If a person has been assaulted due to which he has sustained a large liver laceration, for which he is operated by a surgeon. If the patient dies intraoperatively or postoperatively due to complications related to surgery or injury, the person who has assaulted the patient will be held responsible. But, if the doctor has done some negligent act during surgery, e.g. left the swab or instrument in abdomen during surgery; and patient dies because of that act (sepsis due to swab), then the responsibility may pass from original incident to later negligent act of doctor by principle of `Novus actus intervention'' (an unrelated action intervening). Thus the doctor is responsible for negligent acts, i.e. criminal negligence, and the assailant will not be fully responsible for the ultimate harm.","pyqMatches":[{"year":"2015","no":620,"q":"Novus actus interveniens is","o":["Facts speaking for itself","Breaking of chain","Contributory negligence","Therapeutic misadventure"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2354, 'Forensic Medicine', 'Miscellaneous', 'Moderate', 'Forensic_Medicine', 309, '{"id":2354,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":309,"q":"Inquest, not followed in India is -","o":["Police inquest","Magistrate inquest","Coroner''s inquest","All of the above"],"a":2,"e":"Ans. is ''c'' i.e.,Coroner''s inquest Coroner''s court used to be held in India in Bombay (Mumbai). Now, it is held nowhere in the country. It was abolished even from Mumbai in 1999.","pyqMatches":[{"year":"2015","no":621,"q":"Inquest, not followed in India is","o":["Police inquest","Magistrate inquest","Coroner''s inquest","All of the above"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2355, 'Forensic Medicine', 'Sexual Offences', 'Easy', 'Forensic_Medicine', 310, '{"id":2355,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":310,"q":"Length of the fetus is 40cms. What would be the age of gestation ?","o":["4 months","6 months","7 months","8 months"],"a":3,"e":"Ans. is ''d'' i.e.,8 months [Ref Modi 23''die p. 1016, 1037; Dutta Obstetrics 6th/e p. 41] According to Rule of Hasse : Length = 5 x months of pregnancy. Thus, 40 = 5 x months of pregnancy or months of pregnancy = 8","pyqMatches":[{"year":"2015","no":622,"q":"Length of the fetus is 40cms. What would be the age of gestation ?","o":["4 months","6 months","7 months","8 months"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2356, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 311, '{"id":2356,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":311,"q":"Extra permanent tooth to erupt is -","o":["Upper incisor","Canine","Molar","Lower incisor"],"a":0,"e":"Ans. is ''a'' i.e., Upper incisor [Ref Textbook of Pediatric Decntistry p. 354] Most common supernumerary teeth are permanent, anterior incisor in the maxilla (maxillary incisors), called mesiodens. After maxillary incisors, maxillary and mandibular fourth molars called distodens or distomolars","pyqMatches":[{"year":"2015","no":623,"q":"Extra permanent tooth to erupt is","o":["Upper incisor","Canine","Molar","Lower incisor"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2357, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 312, '{"id":2357,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":312,"q":"Alcohol is taken with aerated soft drinks because -","o":["Absorption is faster","Effect is increased","To avoid hangover","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Absorption is faster [Ref Handbook of Alcoholic Beverages] The rate of alcohol absorption is dependent on its concentration, being the highest from beverages containing about 20% to 30% alcohol, and on the speed of its consumption. Alcohol consumed in acrated beveraes is more readily absorbed, as is alcohol taken on an empty stomach.","pyqMatches":[{"year":"2015","no":679,"q":"Alcohol is taken with aerated soft drinks because","o":["Absorption is faster","Effect is increased","To avoid hangover","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2358, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 313, '{"id":2358,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":313,"q":"UV rays examination is done for -","o":["Faded tattoo","Blood satins","Hair examination","None of the above"],"a":0,"e":"Ans. is ''a'' i.e. Faded tattoo [Ref Principles of Forensic Medicine and Toxicology by Rajesh Bardale] Tattoo mark is permanent when dye penetrates the dermis. Ultraviolet lamp makes old tattoos readily visible. A faded tattoo mark becomes visible by use of Infrared photography or rubbing the part and examining with magnifying lens.","pyqMatches":[{"year":"2015","no":625,"q":"UV rays examination is done for","o":["Faded tattoo","Blood satins","Hair examination","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2359, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 314, '{"id":2359,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":314,"q":"Just before the birth which epiphysis appears?","o":["Lower end of femur","Upper end of humerus","Lower end of fibula","Upper end of tibia"],"a":0,"e":"Ans. is ''a'' i.e., Lower end of femur [Ref Reddy 30/e p. 64, 65]","pyqMatches":[{"year":"2015","no":626,"q":"Just before the birth which epiphysis appears?","o":["Lower end of femur","Upper end of humerus","Lower end of fibula","Upper end of tibia"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2360, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 315, '{"id":2360,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":315,"q":"Base of sphenoid fuses with occipit at the age of -","o":["20 years","30 years","40 years","50 years"],"a":0,"e":"Ans. is ''a'' i.e., 20 years [Ref Dr. Anil Aggrarwal p.68] Spheno-occipit is the earliest to fuse (20 years). Saggital suture obliterates at 30-35 years. Coronoid (coronal suture) obliterates at 35-40 years. Lambdoid suture obliterates at 45-50 years. Squamous suture obliterates at 60 years. Spheno-parietal suture obliterates at 70 years.","pyqMatches":[{"year":"2015","no":627,"q":"Base of sphenoid fuses with occipit at the age of","o":["20 years","30 years","40 years","50 years"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2361, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 316, '{"id":2361,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":316,"q":"False about declaration of brain stem death in hospital -","o":["Presence of neurologist is not required","Drug overdose should be ruled out","Patient must be in coma","All of the above"],"a":0,"e":"Ans. is ''a'' i.e. Presence of neurologist is not required [Ref Principles of Forensic Medicine & Toxicology By Rajesh Bardale p. 134] Guidelines for declaration of brain stem death Brain death needs to be certified by a board of doctor''s consisting of: Registered Medical Practioner (RMP) in charge of hospital where brain death has occurred. An independent RMP -a specialist. A Neurologist / Neurosurgeon nominated by panel. RMP treating the patient. The patient must be examined by team of doctors at least trice with a reasonable gap of time in between (at least 6 hours). None of the doctor''s who participate in diagnosis of brain death should have any interest in transplantation or organ removal from cadaver. Brain death certificate has to be signed by all the members of board. Diagnosis of brain stem death depends upon following findings The patient must be in deep coma and cause of the coma must be irreversible structural brain stem damage (i.e. prolonged hypoxia, trauma, illness or toxic insult) must be established. Exclusion of other causes of coma : Hypothermia, Drug overdose eg: CNS depressants (benzodiazepines, barbiturates etc) Metabolic or endocrine disturbances Intoxication (alcohol) Demonstrating of absence of brain stem reflexes (Pupillary reflex, oculovestibular reflex(, corneal reflex, pharyngeal and tracheal reflexes.) No spontaneous respiration.","pyqMatches":[{"year":"2015","no":628,"q":"False about declaration of brain stem death in hospital","o":["Presence of neurologist is not required","Drug overdose should be ruled out","Patient must be in coma","All of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2362, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 317, '{"id":2362,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":317,"q":"Time interval between somatic and molecular death is -","o":["5-10 min","10-30 min","30 -1hr","1 - 2 hrs"],"a":3,"e":"Ans. is ''d'' i.e. 1-2 hrs [Ref e-book of Postmortem changes by DR D Rao] Death of the tissues and cells individually (molecular death) takes place usually 1-2 hours after stoppage of vital functions (somatic death). Molecular death of various organs occur at different intervals after somatic death :","pyqMatches":[{"year":"2015","no":629,"q":"Time interval between somatic and molecular death is","o":["5-10 min","10-30 min","30 -1hr","1 - 2 hrs"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2363, 'Forensic Medicine', 'Forensic Identification', 'Moderate', 'Forensic_Medicine', 318, '{"id":2363,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":318,"q":"Bishop''s tripod of life includes all except -","o":["Respiration","Circulation","Spinal cord reflexes","Brain functions"],"a":2,"e":"Ans. is ''c'' i.e., Spinal cord reflexes Somatic death It is the complete and irreversible stoppage of the circulation, respiration and brain functions (bishop''s tripod of life). Somatic death is associated with immediate signs of death :?","pyqMatches":[{"year":"2015","no":630,"q":"Bishop''s tripod of life includes all except","o":["Respiration","Circulation","Spinal cord reflexes","Brain functions"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2364, 'Forensic Medicine', 'Sexual Offences', 'Easy', 'Forensic_Medicine', 319, '{"id":2364,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":319,"q":"MTP can be done by a single doctor till ?","o":["8 weeks","12 weeks","20 weeks","24 weeks"],"a":1,"e":"Ans. is ''b'' i.e., 12 weeks [Ref Dutta 6th/e p. 174; Park 22\"/e p. 467] The Act provides safeguards to the mother by authorizing only a Registered Medical Practitioner having experience in gynecology and obstetrics to perform abortion where the length of pregnancy does not exceed 12 weeks.","pyqMatches":[{"year":"2015","no":678,"q":"MTP can be done by a single doctor till ?","o":["8 weeks","12 weeks","20 weeks","24 weeks"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2365, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 320, '{"id":2365,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":320,"q":"For autopsy, stomach is open through -","o":["Lesser sac","Greater sac","Greater curvature","Lesser curvature"],"a":2,"e":"Ans is ''c'' i.e. Greater curvature [Ref Atlas of Adult Autopsy p.66] Stomach is opened through greater curvature which allows to see lesser sac. Depending on type of case, any of the body cavity can be opened first. Spinal cord is routinely not opened. It is convenient to start the examination with the cavity chiefly affected. In cases of death due to asphyxia (especially hanging and strangulation), neck should be opened last. Spinal cord can be approached either from posterior (most preferred) or anterior approach. High cervical spine injuries are best seen by posterior and thoracic spine by anterior approach. Blood for the sample is taken from femoral vein. The jugular or subclavian veins can also be used. 10-20 ml of blood is taken and it is taken before autopsy. 30 ml of blood should be preserved (minimum is 10 ml).","pyqMatches":[{"year":"2015","no":631,"q":"For autopsy, stomach is open through","o":["Lesser sac","Greater sac","Greater curvature","Lesser curvature"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2366, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 321, '{"id":2366,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":321,"q":"Bacteria most commonly involved in bowel decomposition after death is -","o":["Streptococcus pyogenes","Clostridium welchii","Pseudomonas aeruginosa","None"],"a":1,"e":"Ans. is ''b'' i.e., Clostridium welchii [Ref Reddy 30th/e p. 149-152] Bowel decomposition is brought about by aerobic and anaerobic bacteria present in small intestine (e.g. C. welchii, staphylococcus, E.coli etc.) which release enzymes (especially lipase and lecithinase) which act on body to cause breakdown.","pyqMatches":[{"year":"2015","no":633,"q":"Bacteria most commonly involved in bowel decomposition after death is","o":["Streptococcus pyogenes","Clostridium welchii","Pseudomonas aeruginosa","None"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2367, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 322, '{"id":2367,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":322,"q":"How many days a person can live without food and water ?","o":["1 to 2 days","2 to 4 days","5 to 7 days","10 to 12 days"],"a":3,"e":"Ans. is. d, 10 to 12 days [Ref Parikh 6th/e p. 3.74; SK Singhal ele p. 146] Feeling of intense hunger lasts for→ 30-48 hours Emaciation & absorption of subcutaneous fat begins to occur→ After 4-5 days Newborn may survive with out food & water→ For 7-10 days Adult may survive without food & water → 10-12 days If food alone is withdrawn death occurs in → 6-8 weeks (50-60 days)","pyqMatches":[{"year":"2015","no":677,"q":"How many days a person can live without food and water ?","o":["1 to 2 days","2 to 4 days","5 to 7 days","10 to 12 days"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2368, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 323, '{"id":2368,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":323,"q":"Negative autopsy is defined as -","o":["No cause of death is found on gross as well as histopathological examination","Cause is apparent on gross examination but not on histopathological examination","Gross findings are minimal","Cause is apparent on gross examination but not found because of constraints on the part of doctor"],"a":0,"e":"Ans. is ''a'' i.e., No cause of death is found on gross as well as histopathological examination [Ref Dr. Anil Aggrawal p.124] Types of autopsy Normal autopsy - cause is apparent from gross examination Defective autopsy - cause was ascertainable, but was not ascertained due to constrains on the part of doctor, hospital, facilities etc Obscure autopsy - gross findings are minimal, indecisive or obscure, as in adrenal insufficiency, anesthetic overdose, myxedema, rare plant poisons, thyrotoxicosis etc. subsequent examination like histology, microbiology, toxicology or serology reveal the cause. Negative autopsy / inconclusive autopsy - Cause is not clear from gross as well as subsequent examinations.","pyqMatches":[{"year":"2015","no":634,"q":"Negative autopsy is defined as","o":["No cause of death is found on gross as well as histopathological examination","Cause is apparent on gross examination but not on histopathological examination","Gross findings are minimal","Cause is apparent on gross examination but not found because of constraints on the part of doctor"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2369, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 324, '{"id":2369,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":324,"q":"In Adipocere, color change seen is -","o":["Grayish white","Black","Brown","Red"],"a":0,"e":"Ans. is ''a'' i.e. Grayish white [Ref Reddy 30th/e p. 155-156] Adipocere is a crumbly, waxy, water-insoluble material consisting mostly of saturated fatty acids. Depending on whether it was formed from white or brown body fat, adipocere is either grayish white or tan in color.","pyqMatches":[{"year":"2015","no":637,"q":"In Adipocere, color change seen is","o":["Grayish white","Black","Brown","Red"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2370, 'Forensic Medicine', 'Thanatology', 'Moderate', 'Forensic_Medicine', 325, '{"id":2370,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":325,"q":"Not a feature of postmortem staining -","o":["Occur immediate after death","Common in dependent part","Disappear with putrefaction","Margins are sharp"],"a":0,"e":"Ans. is ''a'' i.e., Occur immediate after death [Ref Reddy 30th/e p.141,142] Postmortem staining is an early sign (not immediate sign) of death. It refers to discoloration of skin and internal organs after death due to accumulation of fluid blood in toneless capillaries and small veins of dependent part of the body. It does not appear elevated above the surface but has sharply defined (usually horizontal) margins. It is an early sign of death. It starts at about 1 hour, becomes a series of mottled patches within 1-3 hours and these pathces increase in size to coalesce in about 3-6 hours. After 6-12 hours, lividity is fully developed and fixed (unchangeable), i.e. primary lividity. It ends when putrification sets in. Fixation of lividity is due to stagnation of blood in distended capillaries and venules (not due to coagulation of blood).","pyqMatches":[{"year":"2015","no":638,"q":"Not a feature of postmortem staining","o":["Occur immediate after death","Common in dependent part","Disappear with putrefaction","Margins are sharp"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2371, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 326, '{"id":2371,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":326,"q":"Acid injury can be differentiated from alkali injury by ?","o":["Liquefactive necrosis","Acid burns are more dangerous","Perforation is more common","Affects more commonly esophagus"],"a":2,"e":"Ans. is ''c'' i.e. Perforation is more common","pyqMatches":[{"year":"2015","no":675,"q":"Acid injury can be differentiated from alkali injury by ?","o":["Liquefactive necrosis","Acid burns are more dangerous","Perforation is more common","Affects more commonly esophagus"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2372, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 327, '{"id":2372,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":327,"q":"Best temperature for putrefaction is -","o":["0-10 C","10-45 C","45-100 C","100-150 C"],"a":1,"e":"Ans. is ''b'' i.e., 10-45 C [Ref Reddy 30th/e p. 149-152] Optimum temperature for putrefaction 10°C - 45°C. Putrefaction is the last stage in resolution of body from the inorganic to organic state and is certain sign of death. Putrefaction rate in air is twice as compared to in water, and eight time as compared to in earth (Casper dictum). Putrefaction is delayed in death due to wasting disease anemia, debility, poisoning by carbolic acid, zinc chloride, strychine and chronic heavy metal poisoning.","pyqMatches":[{"year":"2015","no":640,"q":"Best temperature for putrefaction is","o":["0-10 C","10-45 C","45-100 C","100-150 C"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2373, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 328, '{"id":2373,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":328,"q":"Chicken fat appearance is seen in -","o":["Antemortem wound","Postmortem wound","Gunshot injury","None"],"a":1,"e":"Ans. is ''b'' i.e. Postmortem wound [Ref Reddy 29th/e p. 164, 168; Parikh 6th/e p. 4.76] Chicken fat clot is seen in postmortem wound. Gaping of the wound, presence of vital reaction and increased serotonin are features of antemortem wound.","pyqMatches":[{"year":"2015","no":643,"q":"Chicken fat appearance is seen in","o":["Antemortem wound","Postmortem wound","Gunshot injury","None"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2374, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 329, '{"id":2374,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":329,"q":"Thorn apple is ?","o":["Dhatura","Nax vomika","Opioid","Cannabis"],"a":0,"e":"Ans. is ''a'' i.e. Dhatura [Ref Parikh &hie p. 10.50-10.51; Essentials offorensic medicine-812] Dhatura (thorn apple) grows on waste land all over india and is of two types (i) Dhatura alba and (ii) dhatura niger. All parts of plant is poisonous, especially seeds and fruits. Active principles of dhatura are levohyoscyamine, hyoscine (scopolamine) and atropine.","pyqMatches":[{"year":"2015","no":674,"q":"Thorn apple is ?","o":["Dhatura","Nax vomika","Opioid","Cannabis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2375, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 330, '{"id":2375,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":330,"q":"Homicidal gunshot wound can be differentiated from suicidal gunshot wound by-","o":["Multiple gunshot wounds","Presence of gunpowder on hand","No sign of struggle","None"],"a":0,"e":"Ans is''a'' i.e. Multiple gunshot wounds Following are a few ways to Differentiate murder from suicide","pyqMatches":[{"year":"2015","no":645,"q":"Homicidal gunshot wound can be differentiated from suicidal gunshot wound by","o":["Multiple gunshot wounds","Presence of gunpowder on hand","No sign of struggle","None"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2376, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 331, '{"id":2376,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":331,"q":"Beveling of skull is seen in -","o":["Broad end of the entry point in bullet injury","Narrow end of the entry point in bullet injury","Exit point of bullet","Depressed fracture of the skull"],"a":2,"e":"Ans. is ''c'' i.e.,Exit point of bullet [Ref Parikh 6th/e p. 4.43] Wound of entrance shows a punched in (clean) hole in the outer table. Cone shaped bone is detached from the inner table forming a crater that is larger than the hole of the outer table and shows beveling (sloping surface). Thus, from looking outside, entrance wound is clean cut hole and exit wound is bevelled opening.","pyqMatches":[{"year":"2015","no":647,"q":"Beveling of skull is seen in","o":["Broad end of the entry point in bullet injury","Narrow end of the entry point in bullet injury","Exit point of bullet","Depressed fracture of the skull"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2377, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 332, '{"id":2377,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":332,"q":"Mickey Finn is ?","o":["Chloroform","Methyl alcohol","Chloral hydrate","Ethylene glycol"],"a":2,"e":"Ans. is ''c'' i.e., Chloral hydrate [Ref Reddy 30th/e p. 540] Mickey finn is a combination of alcohol and chloral hydrate.","pyqMatches":[{"year":"2015","no":673,"q":"Mickey Finn is ?","o":["Chloroform","Methyl alcohol","Chloral hydrate","Ethylene glycol"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2378, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 333, '{"id":2378,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":333,"q":"Most specific sign of Antemortem burns is -","o":["Soot in respiratory passage","Cyanosis of fingernails","Pugilistic attitude","Heat ruptures"],"a":0,"e":"Ans. is ''a'' i.e., Soot in respiratory passage [Ref: Parikh 6th le p. 4.152-4.156] One of the most important characteristic of antemortem burns is the finding of ''Soot and carbon particles'' in larynx, trachea and may be in lungs. A. Specific signs (which indicate antemortem burning) :","pyqMatches":[{"year":"2015","no":650,"q":"Most specific sign of Antemortem burns is","o":["Soot in respiratory passage","Cyanosis of fingernails","Pugilistic attitude","Heat ruptures"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2379, 'Forensic Medicine', 'Sexual Offences', 'Easy', 'Forensic_Medicine', 334, '{"id":2379,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":334,"q":"Sex with cadaver is called -","o":["Necrophilia","Exhibitionism","Voveyrism","Undinism"],"a":0,"e":"Ans. is ''a'' i.e., Necrophilia [Ref Narayan Reddy 30thie p. 394] Necrophilia : In this condition, there is a desire for sexual intercourse with dead bodies. It is said to have sadomasochistic foundation and that decomposition, foul smell and coldness act as stimulants.","pyqMatches":[{"year":"2015","no":652,"q":"Sex with cadaver is called","o":["Necrophilia","Exhibitionism","Voveyrism","Undinism"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2380, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 335, '{"id":2380,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":335,"q":"Smack is -","o":["Cocaine","Heroine","Dhatura","Cannabis"],"a":1,"e":"Ans is ''b'' i.e., Heroin Heroin (smack or brown sugar) is the most commonly abused opioid and 2\" most commonly abused substance, after alcohol.","pyqMatches":[{"year":"2015","no":672,"q":"Smack is","o":["Cocaine","Heroine","Dhatura","Cannabis"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2381, 'Forensic Medicine', 'Sexual Offences', 'Easy', 'Forensic_Medicine', 336, '{"id":2381,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":336,"q":"Sexual gratification by inflicting pain on partner -","o":["Sodomy","Sadism","Necrophilia","Bestiality"],"a":1,"e":"Ans. is ''b'' i.e., Sadism [Ref Reddy 30th/e p. 394] Sexual gratification is obtained or increased from acts of physical cruelty or infliction of pain on one''s partner. It is seen more commonly in men. To obtain sexual gratification, the sadist may bite, beat, whip, produce cuts on the victim, etc","pyqMatches":[{"year":"2015","no":653,"q":"Sexual gratification by inflicting pain on partner","o":["Sodomy","Sadism","Necrophilia","Bestiality"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2382, 'Forensic Medicine', 'Sexual Offences', 'Easy', 'Forensic_Medicine', 337, '{"id":2382,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":337,"q":"Sexual gratification obtained by enema is called -","o":["Exhibitionism","Fetichism","Klismaphillia","Frotteurism"],"a":2,"e":"Ans. is ''c'' i.e. Klismaphillia [Ref Internet] Klismaphilia (or klysmaphilia), is a paraphilia involving enjoyment of, and sexual arousal from, enemas.","pyqMatches":[{"year":"2015","no":656,"q":"Sexual gratification obtained by enema is called","o":["Exhibitionism","Fetichism","Klismaphillia","Frotteurism"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2383, 'Forensic Medicine', 'Sexual Offences', 'Easy', 'Forensic_Medicine', 338, '{"id":2383,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":338,"q":"To examine the vaginal cells in of the rape victim test used is -","o":["Lugol''s iodine test","Takayama test","Florence test","Precipitin test"],"a":0,"e":"Ans is ''a'' i.e. Lugol''s iodine test [Ref G Rao p. 301] Lugol''s iodine test It is done on the washing of glans penis (or from a moist blotting paper)of accused, which then exposed to iodine vapors or lugol''s iodine solution. Brown color means the test is positive (on 4th day). Brown color is due to glycogen present in vaginal epithelial cells of the victim.","pyqMatches":[{"year":"2015","no":657,"q":"To examine the vaginal cells in of the rape victim test used is","o":["Lugol''s iodine test","Takayama test","Florence test","Precipitin test"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2384, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 339, '{"id":2384,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":339,"q":"Acid used for forging signature is ?","o":["Sulphuric acid","Nitric acid","Carbolic acid","Oxalic acid"],"a":3,"e":"Ans. is ''d'' i.e., Oxalic acid [Ref Parikh 6th /e p. 8.32-8.34; Reddy''s Essentials of forensic medicine and toxicology 27th/e p. 468- 469] Oxalic acid is used to erase writing, as a bleaching agent and in calico printing","pyqMatches":[{"year":"2015","no":671,"q":"Acid used for forging signature is ?","o":["Sulphuric acid","Nitric acid","Carbolic acid","Oxalic acid"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2385, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 340, '{"id":2385,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":340,"q":"Absorption elution technique is used for -","o":["Blood group detection","Species detection","Seminal stain examination","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Blood group detection [Ref Parikh 6th/e p. 7.15- 7.18; SK Singhal 4''1''1e p. 158-162] For blood grouping, following tests are used : 1) Immunological (serological) :","pyqMatches":[{"year":"2015","no":658,"q":"Absorption elution technique is used for","o":["Blood group detection","Species detection","Seminal stain examination","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2386, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 341, '{"id":2386,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":341,"q":"Arrow poison is ?","o":["Opium","Curare","Cannabis","Cyanide"],"a":1,"e":"Ans. is ''b'' i.e. curare [Ref Dr. Anil Aggrawal p. 447] Arrow poisons ?","pyqMatches":[{"year":"2015","no":670,"q":"Arrow poison is ?","o":["Opium","Curare","Cannabis","Cyanide"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2387, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 342, '{"id":2387,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":342,"q":"Test to know the species from blood stain is -","o":["Takayama test","Benzidine test","Precipitin test","Teichmann''s test"],"a":2,"e":"Ans. is ''c'' i.e., Preciptin-test [Ref Parikh 6m/e p. 7.15-7.18; S.K. Singhal 4''/e p. 158-162] For detection of species, serological (immunological) tests are used. These tests are : Precipitin test Haemagglutination inhibition test Gel diffusion test. Double diffusion test. Precipitation electrophoresis. Latex agglutination test. Isoenzyme method (enzymological test)","pyqMatches":[{"year":"2015","no":659,"q":"Test to know the species from blood stain is","o":["Takayama test","Benzidine test","Precipitin test","Teichmann''s test"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2388, 'Forensic Medicine', 'Miscellaneous', 'Moderate', 'Forensic_Medicine', 343, '{"id":2388,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":343,"q":"All of the following are true for ingestion of acid except -","o":["They are hygroscopic","Coagulate proteins","Hemoglobin to hematin","Systemic symptoms are severe"],"a":3,"e":"Ans. is ''d'' i.e. Systemic symptoms are severe Acids fix, destroy and erode the surface with which they come in contact. They mainly act locally by","pyqMatches":[{"year":"2015","no":660,"q":"All of the following are true for ingestion of acid except","o":["They are hygroscopic","Coagulate proteins","Hemoglobin to hematin","Systemic symptoms are severe"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2389, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 344, '{"id":2389,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":344,"q":"Papaver semniferum milk exudes from ?","o":["Leaf","Root","Poppy seed","Unripe capsule"],"a":3,"e":"Ans. is ''d'' i.e., Unripe capsule [Ref Reddy 30th/e p. 533-534] Opioids (opiates) are derived from the poppy plant. Opium is the dried juice obtained by incision of the unripe capsule of the white poppy, papaver somniferum. Natural derivatives of opium are morphine, heroin and codeine.","pyqMatches":[{"year":"2015","no":669,"q":"Papaver semniferum milk exudes from ?","o":["Leaf","Root","Poppy seed","Unripe capsule"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2390, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 345, '{"id":2390,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":345,"q":"Max damage is done by which poison -","o":["Irritant poison","Corrosive poison","Alcohol","Opioid"],"a":1,"e":"Ans. is ''b'' i.e., Corrosive poison [Ref Rajesh Bardale p. 437] Corrosives fix, destroy and erode the surface with which they come in contact. Thus, they cause extensive tissue damage. Irritants produce less sever damage than corrosives and produce symptoms simulating gastroenteritis.","pyqMatches":[{"year":"2015","no":661,"q":"Max damage is done by which poison","o":["Irritant poison","Corrosive poison","Alcohol","Opioid"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2391, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 346, '{"id":2391,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":346,"q":"Least toxic form of lead is -","o":["Lead acetate","Lead oxide","Lead carbonate","Lead sulphide"],"a":3,"e":"Ans. is ''d'' i.e., Lead sulphide [Ref Parikh 6th le p. 9.17-9.20; Reddy 30thle p. 497-498] No heavy metal is poisonous in native form, except lead. Metallic lead and all its salts are poisonous. The principal salts which produce toxic effects are : (1) Lead acetate (sugar of lead), (2) lead carbonate (safeda or white lead), (3) lead chromate, (4) lead monoxide (lethrage), (5) lead tetraoxide (red lead, vermilion, sindur) and (6) lead sulphide (least toxic).","pyqMatches":[{"year":"2015","no":662,"q":"Least toxic form of lead is","o":["Lead acetate","Lead oxide","Lead carbonate","Lead sulphide"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2392, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 347, '{"id":2392,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":347,"q":"Marsch test is done for poisoning with ?","o":["Lead","Mercury","Arsenic","Nickel"],"a":2,"e":"Ans. is ''c'' i.e. Arsenic [Ref Parikh 6thle p. 9.9-9.11; Reddy 30th/e p. 493-494; Essentials offorensic medicine-812] Marsh''s test and Reinsh''s test were used arsenic poisoning, but are obsolete now.","pyqMatches":[{"year":"2015","no":668,"q":"Marsch test is done for poisoning with ?","o":["Lead","Mercury","Arsenic","Nickel"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2393, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 348, '{"id":2393,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":348,"q":"Which of the following is most specific for arsenic poisoning ?","o":["Red velvety stomach mucosa","Blue lining on gums","Tremors","Anemia"],"a":0,"e":"Ans. is ''a'' i.e. Red velvety stomach mucosa [Ref Parikh 6th/e p. 9.9-9.11; Reddy 30\" `/e p. 493-494; Essentials of forensic medicine-812] Red velvety mucosa is a typical postmortem finding in acute arsenic poisoning.","pyqMatches":[{"year":"2015","no":666,"q":"Which of the following is most specific for arsenic poisoning ?","o":["Red velvety stomach mucosa","Blue lining on gums","Tremors","Anemia"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2394, 'Forensic Medicine', 'Medical Jurisprudence', 'Easy', 'Forensic_Medicine', 349, '{"id":2394,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":349,"q":"Miscarriage due to negligence of doctor is seen under which IPC ?","o":["Sec 310 IPC","Sec 311 IPC","Sec 312 IPC","Sec 314 IPC"],"a":2,"e":"Ans. is ''c'' i.e., Sec 312 IPC Sec 312 IPC refers to \"causing miscarriage\" of a woman pregnant with a child, punishable up to 3 years, but if she is \"quick\" with her child the punishment may extend to 7 years.","pyqMatches":[{"year":"2013","no":642,"q":"Miscarriage due to negligence of doctor is seen under which IPC ?","o":["Sec 310 IPC","Sec 311 IPC","Sec 312 IPC","Sec 314 IPC"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2395, 'Forensic Medicine', 'Forensic Identification', 'Moderate', 'Forensic_Medicine', 350, '{"id":2395,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":350,"q":"According to section 82 IPC a child''s act is not considered as a crime if he is -","o":["< 4 years","< 7 years","< 12 years","< 18 years"],"a":1,"e":"Ans. is `b'' i.e., < 7 years 82 A child under the age of seven is incapable of committing an offence. This is so because action alobe doesnot amount to guilt unless if is accompanied by a guilty mind. And, a child of that tender age cannot have a guilty mind or criminal intention with which the act is done. This presumption, however, is only confined to offenses under the IPC but not to other Acts, e.g., the Railway Act.","pyqMatches":[{"year":"2013","no":645,"q":"According to section 82 IPC a child''s act is not considered as a crime if he is","o":["< 4 years","< 7 years","< 12 years","< 18 years"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2396, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 351, '{"id":2396,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":351,"q":"Dowry death is under which IPC ?","o":["IPC 304 A","IPC 304 B","IPC 305 A","IPC 305 B"],"a":1,"e":"Ans. is ''b'' i.e.,IPC 304 B 304-B IPC : Dowry death : 10 years of imprisonment which can extend to life.","pyqMatches":[{"year":"2013","no":648,"q":"Dowry death is under which IPC ?","o":["IPC 304 A","IPC 304 B","IPC 305 A","IPC 305 B"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2397, 'Forensic Medicine', 'Medical Jurisprudence', 'Easy', 'Forensic_Medicine', 352, '{"id":2397,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":352,"q":"Lendrum stain is done for ?","o":["Air embolism","Fat embolism","Amniotic fluid embolism","None"],"a":2,"e":"Ans. is ''c'' i.e., Amniotic fluid embolism [Ref Handbook of autopsy practise 3rdle p. 283] Amniotic fluid embolism diagnosis Sections of lungs and other organs are stained using Phloxine- Tartrazine (Lendrum staining) to detect squames, Alcian Blue to detect mucin. Sudan Black or Oil Red to detect vernix caseosa.","pyqMatches":[{"year":"2012","no":662,"q":"Lendrum stain is done for ?","o":["Air embolism","Fat embolism","Amniotic fluid embolism","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2398, 'Forensic Medicine', 'Medical Jurisprudence', 'Easy', 'Forensic_Medicine', 353, '{"id":2398,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":353,"q":"CrPC 26 ?","o":["Division of offence","Division of negligence","Division of malpractice","None"],"a":0,"e":"Ans. is ''a'' i.e.,Division of offence According to Sec 26 of CrPC, 1973, Offences under the Criminal Procedure Code (hereinafter the \"CrPC\") are divided into:","pyqMatches":[{"year":"2012","no":592,"q":"CrPC 26 ?","o":["Division of offence","Division of negligence","Division of malpractice","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2399, 'Forensic Medicine', 'Sexual Offences', 'Easy', 'Forensic_Medicine', 354, '{"id":2399,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":354,"q":"Which section belongs to marital rape ?","o":["375A","376A","376B","375B"],"a":1,"e":"Ans. is ''b'' i.e., 376A [Ref Reddy 30\"Ve p. 377] Marital rape It is forceful sexual intercourse with wife who is living separately from him under a decree of separation, or any custom or usage without her consent. It is punishable with imprisonment up to 2 years provided the age of wife is not below 12 years- Section 376 A, I.P.C.","pyqMatches":[{"year":"2012","no":593,"q":"Which section belongs to marital rape ?","o":["375A","376A","376B","375B"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2400, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 355, '{"id":2400,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":355,"q":"Plantiff is a person who ?","o":["Files case in civil court","Acts as defender","Gives judgement","None"],"a":0,"e":"Ans. is ''a'' i.e., Files case in civil court [Ref Internet] Plaintiff is a person who files a case in civil court. ·","pyqMatches":[{"year":"2012","no":595,"q":"Plantiff is a person who ?","o":["Files case in civil court","Acts as defender","Gives judgement","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2401, 'Forensic Medicine', 'Sexual Offences', 'Moderate', 'Forensic_Medicine', 356, '{"id":2401,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":356,"q":"DNA finger printing cannot be taken from ?","o":["Saliva","Tooth","Buccal mucosa","Blood"],"a":1,"e":"Ans. is ''b'' i.e., Tooth [Ref Parikh 6th le p. 7.2-7.15] DNA finger-printing/ DNA profiling Is a technique employed by forensic scientists to assist in the identification of individuals by their respective DNA profile it is a fool proof method to conclusively fix the paternity/ maternity. The most desirable method of collecting a reference sample is the use of a buccal swab. When this is not available (e.g. because a court order may be needed and not obtainable) other methods may need to be used to collect a sample of blood, saliva, semen, or other appropriate fluid or tissue from personal items (e.g. toothbrush, razor, etc.) or from stored samples (e.g. banked sperm or biopsy tissue)","pyqMatches":[{"year":"2012","no":660,"q":"DNA finger printing cannot be taken from ?","o":["Saliva","Tooth","Buccal mucosa","Blood"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2402, 'Forensic Medicine', 'Miscellaneous', 'Moderate', 'Forensic_Medicine', 357, '{"id":2402,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":357,"q":"Which of the following is not seen in finger prints ?","o":["Loop","Circles","Whorl","Arch"],"a":1,"e":"Ans. is ''b'' i.e., Circles [Ref Reddy 30`h/e p. 75-76] Classification of finger prints: Loops (60-70%)- radial, ulnar Whorls ( 25-35%)- concentric, spiral, double spiral, almond shaped Arches (6-7%)- plain, tented, exceptional Composite (1-2%)- central pocket loops, lateral pocket loops, twinned loops, accidentals Most common type - Loops. Least common type -› Composite.","pyqMatches":[{"year":"2012","no":602,"q":"Which of the following is not seen in finger prints ?","o":["Loop","Circles","Whorl","Arch"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2403, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 358, '{"id":2403,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":358,"q":"Which snake bite causes hematologic abnormalities ?","o":["Cobra","Crait","Viper","Sea snake"],"a":2,"e":"Ans. is ''c'' i.e., Viper [Ref Parikh &Ye p. 9.44] Hematotoxic Vipers Myotoxic Sea snakes Neurotoxic Elapids- cobra, Krait, coral","pyqMatches":[{"year":"2012","no":658,"q":"Which snake bite causes hematologic abnormalities ?","o":["Cobra","Crait","Viper","Sea snake"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2404, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 359, '{"id":2404,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":359,"q":"What is first external sign of decomposition of dead body -","o":["Decomposition of liver and intestine","Greenish discolouration over right iliac fossa","Greenish discolouration over dependent parts","Blood stained froth from mouth"],"a":1,"e":"Ans. is ''b'' i.e., Greenish discolouration over right iliac fossa [Ref Reddy 30th/e p. 150-152] First external sign of putrefaction - Green discoloration in right iliac fossa. First internal sign of putrefaction Green discoloration under liver. These are due to involvement of caecum which contains more gas and is full of bacteria.","pyqMatches":[{"year":"2012","no":604,"q":"What is first external sign of decomposition of dead body","o":["Decomposition of liver and intestine","Greenish discolouration over right iliac fossa","Greenish discolouration over dependent parts","Blood stained froth from mouth"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2405, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 360, '{"id":2405,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":360,"q":"Black papper adultrant is ?","o":["Khesari dal","Dried papaya seed","Fine sand","None"],"a":1,"e":"Ans. is `b'' i.e., Dried papaya seed","pyqMatches":[{"year":"2012","no":656,"q":"Black papper adultrant is ?","o":["Khesari dal","Dried papaya seed","Fine sand","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2406, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 361, '{"id":2406,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":361,"q":"In vitrous what is measured for time since death -","o":["Sodium","Potassium","Proteins","Chloride"],"a":1,"e":"Ans. is ''b'' i.e., Potassium [Ref: Reddy 30th/e p. 139] Post mortem changes in eye are : Loss of corneal reflex Opacity of cornea- cornea becomes opaque in 2 to 4 hours. Flaccidity of eye ball- within minutes after death due to decreased intraocular tension. Pupils are dilated within one minute of death, pupils react to atropine for about one hour. Retina- fragmentation of blood column in retinal vessels occur within minutes to one hour. Chemical change- a steady rise in the potassium values occur in the virtous humor after death upto 100 times.","pyqMatches":[{"year":"2012","no":605,"q":"In vitrous what is measured for time since death","o":["Sodium","Potassium","Proteins","Chloride"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2407, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 362, '{"id":2407,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":362,"q":"Most common drug abuse in India ?","o":["Cannabis","Amphetamine","Cocaine","Heroine"],"a":3,"e":"Ans. is ''d'' i.e., Heroin Amongst the given options, heroin is the most commonly abused substance : Alcohol → 43.9 % Opioids (including heroin) → 26% Cannabis → 11.6 %","pyqMatches":[{"year":"2012","no":655,"q":"Most common drug abuse in India ?","o":["Cannabis","Amphetamine","Cocaine","Heroine"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2408, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 363, '{"id":2408,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":363,"q":"In how many hours does a dead body float in India in summer ?","o":["6 hours","12 hours","24 hours","48 hours"],"a":2,"e":"Ans. is ''c'' i.e., 24 hours Time of floatation of dead body in drowining is ordinarily 24 hours after death in summer and 2 to 3 days in cold season.","pyqMatches":[{"year":"2012","no":608,"q":"In how many hours does a dead body float in India in summer ?","o":["6 hours","12 hours","24 hours","48 hours"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2409, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 364, '{"id":2409,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":364,"q":"Ethylene Glycol antidote is ?","o":["Barbiturates","Acetycysteine","Ferric chloride","Fomipizole"],"a":3,"e":"Ans. is ''d'' i.e., Fomipizole [Ref Reddy 30th/e p. 533] Antidote for ethylene glycol poisoning is fomipizole.","pyqMatches":[{"year":"2012","no":651,"q":"Ethylene Glycol antidote is ?","o":["Barbiturates","Acetycysteine","Ferric chloride","Fomipizole"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2410, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 365, '{"id":2410,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":365,"q":"In medicolegal autopsy, cavity to be opened first is ?","o":["Thoracic","Abdomen","Cervical","Any of the above"],"a":3,"e":"Ans. is ''d'' i.e., Any of the above [Ref Reddy 30thle p. 97] Depending on type of case, any of the body cavity can be opened first. Spinal cord is routinely not opened. It is convenient to start the examination with the cavity chiefly affected","pyqMatches":[{"year":"2012","no":610,"q":"In medicolegal autopsy, cavity to be opened first is ?","o":["Thoracic","Abdomen","Cervical","Any of the above"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2411, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 366, '{"id":2411,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":366,"q":"True about Stab Wounds ?","o":["Depth is greater than Breadth","Breadth is greater than depth","Length is greater than breadth","It has wound of entry and exit"],"a":0,"e":"Ans. is ''a'' i.e., Depth is greater than breadth [Ref Reddy 30th le p. 179] Stab/ puncture wound is an injury caused by pointed weapons such as dagger, knife, needle, arrow, scissor and its depth is the greatest dimension.","pyqMatches":[{"year":"2012","no":616,"q":"True about Stab Wounds ?","o":["Depth is greater than Breadth","Breadth is greater than depth","Length is greater than breadth","It has wound of entry and exit"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2412, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 367, '{"id":2412,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":367,"q":"Oochronosis is seen in which poisoning ?","o":["Hydrochloric acid","Carbolic acid","Oxalic acid","Formic acid"],"a":1,"e":"Ans. is ''b'' i.e., Carbolic acid [Ref Reddy 30th/e p. 489] Chronic carbolic acid poisoning/phenol marasmus The poisoning is characterised by anorexia, weight loss, headache, vertigo, dark urine and pigmentation of skin & sclera. Carbolic acid/ Phenol is converted into hydroquinone & pyrocatechol in the body before being excreted in the urine. Hydroquinone er pyrocatechol may cause pigmentation in the cornea and various cartilages- Oochronosis. Oochronosis is commonly associated with alkaptonuria, in which homegentisic acid gets deposited in cartilages, ligaments & fibrous tissues.","pyqMatches":[{"year":"2012","no":644,"q":"Oochronosis is seen in which poisoning ?","o":["Hydrochloric acid","Carbolic acid","Oxalic acid","Formic acid"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2413, 'Forensic Medicine', 'Injuries & Wounds', 'Easy', 'Forensic_Medicine', 368, '{"id":2413,"subject":"Forensic Medicine","chapter":"Injuries & Wounds","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":368,"q":"Marshalls triad is seen in ?","o":["Explosive injury","Gunshot injury","Drowning injury","None"],"a":0,"e":"Ans. is ''a'' i.e., Explosive injury [Ref epository.up.ac.za/bitstream/handle/2263/19400/Blumenthal_Does( Marshall''s triad includes punctate-bruises, abrasions and small punctate lacerations all of which are typically found in an explosive bomb blast.","pyqMatches":[{"year":"2012","no":617,"q":"Marshalls triad is seen in ?","o":["Explosive injury","Gunshot injury","Drowning injury","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2414, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 369, '{"id":2414,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":369,"q":"Brutonian lines on gums is seen in poisoning with ?","o":["Lead","Mercury","Mercury","Zinc"],"a":0,"e":":B Ans. is ''a > b'' i.e., Lead > Mercury [Ref Reddy 306/e p.497-498] Burtonian line is blue line, which is seen on upper gums in lead poisoning. Similar blue line (but not called burtonian line in these cases) is also seen in poisoning with Mercury (Hg), Copper (Cu), Silver (Ag), bismuth (Bi), and Iron (Fe).","pyqMatches":[{"year":"2012","no":643,"q":"Brutonian lines on gums is seen in poisoning with ?","o":["Lead","Mercury","Mercury","Zinc"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2415, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 370, '{"id":2415,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":370,"q":"Cyanide odour is of ?","o":["Rotten egg","Fish","Fruity","Bitter almond"],"a":3,"e":"Ans. is ''d'' i.e., Bitter almond [Ref Reddy 30th/e p. 578] Odors associated with poisoning Garlik like : Phosphorus, arsenic, zinc phosphide, aluminium phosphide (celphos), arsine gas, tellurium, parathion, malathion, arsenic. Rotten eggs : Hydrogen sulphide, mercaptans, disulphiram. Fishy or musty : Zinc phosphide. Bitter almonds : Cyanide, HCN. Acrid : Paraldehyde, chloral hydrate. Burnt rope : Cannabis. Kerosene like : Kerosene and organophosphates. Phenolic smell : Carbolic acid.","pyqMatches":[{"year":"2012","no":635,"q":"Cyanide odour is of ?","o":["Rotten egg","Fish","Fruity","Bitter almond"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2416, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 371, '{"id":2416,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":371,"q":"La facies symapthique is seen in ?","o":["Hanging","Strangulation","Myocardial insufficiency","Railway accident"],"a":0,"e":"Ans. is ''a'' i.e., Hanging [Ref Reddy 30th/e p. 526] La facies symapthique: eye on the side of the knot in hanging remains open, due to overstretching of cervical sympathetic chain of the neck on this side. It occurs in hanging due to pressure of ligature knot on the cervical sympathetic chain.","pyqMatches":[{"year":"2012","no":622,"q":"La facies symapthique is seen in ?","o":["Hanging","Strangulation","Myocardial insufficiency","Railway accident"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2417, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 372, '{"id":2417,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":372,"q":"Victim was choked with mouth & nose covered with elbow around neck. It is called as ?","o":["Mugging","Garrotting","Bansadola","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Mugging [Ref Reddy 30th/e p. 321] Mugging: Strangulation is caused by holding the neck of the victim in the bend of the elbow. Garrotting: The victim is attacked from behind. The throat may be grasped or a ligature is thrown over the neck & quickly tightened, by twisting it with a lever, which results in sudden loss in consciousness and collapse. Bansdola: one strong bamboo or stick is placed across the back of the neck & another across the front. Both the ends are tied with a rope due to which the victim is squeezed to death","pyqMatches":[{"year":"2012","no":625,"q":"Victim was choked with mouth & nose covered with elbow around neck. It is called as ?","o":["Mugging","Garrotting","Bansadola","None of the above"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2418, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 373, '{"id":2418,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":373,"q":"First aid should be given in acid contact ?","o":["Wash with normal water soap","Wash with mild alkali agent","Wash with strong alkali","Refer to higher centre"],"a":1,"e":"Ans. is ''b'' i.e., Wash with mild alkali agent [Ref Reddy 30Th le p. 485] The most critical aspect of acid burn care is the constant and prolonged washing of the area with water at a room temperature to get the acid out immediately. To try and minimize the damage, the effects of acid should be neutralized by applying a mild alkali solution to the affected area (solution of sodium bicarbonate and water.","pyqMatches":[{"year":"2012","no":633,"q":"First aid should be given in acid contact ?","o":["Wash with normal water soap","Wash with mild alkali agent","Wash with strong alkali","Refer to higher centre"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2419, 'Forensic Medicine', 'Sexual Offences', 'Easy', 'Forensic_Medicine', 374, '{"id":2419,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":374,"q":"Frotteruism is ?","o":["Sexual pleasure is obtained by witnessing the act of urination","Sexual gratification by rubbing private parts","Sexual practise involving three people","None"],"a":1,"e":"Ans. is ''b'' i.e., Sexual gratification by rubbing private parts [Ref Reddy 30thie p. 395] Frotteurism : is contact with another person in order to obtain sexual gratification. Sexual gratification by rubbing private parts against a female body in crowd. It is punishable under Section 290 I.P. C., with fine upto Rs 200.","pyqMatches":[{"year":"2012","no":629,"q":"Frotteruism is ?","o":["Sexual pleasure is obtained by witnessing the act of urination","Sexual gratification by rubbing private parts","Sexual practise involving three people","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2420, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 375, '{"id":2420,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":375,"q":"What acts as both poison & antidote ?","o":["CuSO4","HgC12","Ar203","Thallium arsenate"],"a":0,"e":"Ans. is ''a'' i.e., CuSO4 [Ref: Reddy 30th/e p. 500, 503] Copper sulphate acts as a poison & an antidote for phosphorus poisoning. Copper sulphate when ingested causes burning pain in stomach with colicky abdominal pain, vomiting. In severe cases, hemolysis, hemoglobinuria, methemoglobinemia, jaundice, pancreatitis & cramps & convulsions. Death can occur due to hepatic & renal failure. It is given in gastric lavage for phosphorous poisoning as it coats the particles of phosphorous with a film of copper sulphide which is harmless.","pyqMatches":[{"year":"2012","no":632,"q":"What acts as both poison & antidote ?","o":["CuSO4","HgC12","Ar203","Thallium arsenate"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2421, 'Forensic Medicine', 'Miscellaneous', 'Moderate', 'Forensic_Medicine', 376, '{"id":2421,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":376,"q":"Estimate volume of ringer lactate in first 8 hrs for 40% burns in 50 kg male with 2° burns?","o":["8 lt","4 lt","2 lt","6 lt"],"a":1,"e":"Answer: B. 4 lt Parkland formula most commonly used IV fluid - Lactated Ringer''s Solution Fluid calculation 4 x weight in kg x %TBSA burn Give 1/2 of that volume in the first 8 hours Give other 1/2 in next 16 hours Warning: Despite the formula suggesting cutting the fluid rate in half at 8 hours, the fluid rate should be gradually reduced throughout the resuscitation to maintain the targeted urine output, i.e., do not follow the second part of the formula that says to reduce the rate at 8 hours, adjust the rate based on the urine output. Example of fluid calculation 50-kg man with 40% TBSA burn Parkland formula: 4 x 50 x 40 = 8,000 ml Give 1/2 in first 8 hours = 4,000 ml in first 8 hours Adjust fluid rate to maintain urine output of 50 ml/hr","pyqMatches":[{"year":"2017","no":122,"q":"Estimate volume of ringer lactate in first 8 hrs for 40% burns in 50 kg male with 2° burns?","o":["8 lt","4 lt","2 lt","6 lt"],"a":1,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":76,"q":"Estimate volume of ringer lactate in first 8 hrs for 40% burns in 50 kg male with 2° burns?","o":["8 lt","4 lt","2 lt","6 lt"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2422, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 377, '{"id":2422,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":377,"q":"Posthumous child is:","o":["Child delivered after death of biological mother","Child delivered after death of biological father","Born after death of parents","has been abandoned by parents"],"a":1,"e":"Answer: B. Child delivered after death of biological father A child born after death of his/ her biological father","pyqMatches":[{"year":"2017","no":123,"q":"Posthumous child is:","o":["Child delivered after death of biological mother","Child delivered after death of biological father","Born after death of parents","has been abandoned by parents,"],"a":1,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":77,"q":"Posthumous child is:","o":["Child delivered after death of biological mother","Child delivered after death of biological father","Born after death of parents","has been abandoned by parents"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2423, 'Forensic Medicine', 'Medical Jurisprudence', 'Easy', 'Forensic_Medicine', 378, '{"id":2423,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":378,"q":"M''naghten rule comes under which section of IPC?","o":["Crpc 84","C pc 48","Ipc 84","IPC 48"],"a":2,"e":"Answer: C. Ipc 84 M''naghten rule (legal test or right or wrong test) : It states that an accused person is not legally responsible, if it is clearly proved that at the time of committing the crime, person was suffering from such a defect of reason from abnormality of mind that he didn''t know the nature and quality of act he was doing or that what he was doing was wrong i.e. a person is not responsible if he is not of sound mind. It is accepted in india as law of criminal responsibility and is embodied in section 84 1PC as - \"nothing is an offence which is done by a person, who at the time of doing it, by reason of unsoundness of mind is incapable of knowing the nature of act, or that he is doing what is either wrong or contrary to law\".","pyqMatches":[{"year":"2017","no":124,"q":"M''naghten rule comes under which section of IPC?","o":["Crpc 84","C pc 48","Ipc 84","IPC 48"],"a":2,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":78,"q":"M''naghten rule comes under which section of IPC?","o":["Crpc 84","C pc 48","Ipc 84","IPC 48"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2424, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 379, '{"id":2424,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":379,"q":"Bluish discoloration of gastric mucosa seen in which poisoning?","o":["Mercury","Cadmium","Amytal sodium","Arsenic"],"a":2,"e":"Answer: C. Amytal sodium S. No. Poison Color","pyqMatches":[{"year":"2017","no":125,"q":"Bluish discoloration of gastric mucosa seen in which poisoning?","o":["Mercury","Cadmium","Amytal sodium","Arsenic"],"a":2,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":79,"q":"Bluish discoloration of gastric mucosa seen in which poisoning?","o":["Mercury","Cadmium","Amytal sodium","Arsenic"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2425, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 380, '{"id":2425,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":380,"q":"Muscle pain, nephropathy caused by which metal poisoning","o":["Arsenic","Cadmium","Mercury","Lead"],"a":0,"e":"Answer: A. Arsenic Nephropathy is caused by most of heavy metals.Muscle pain is associated with arsenic.","pyqMatches":[{"year":"2017","no":126,"q":"Muscle pain, nephropathy caused by which metal poisoning","o":["Arsenic","Cadmium","Mercury","Lead"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":80,"q":"Muscle pain, nephropathy caused by which metal poisoning","o":["Arsenic","Cadmium","Mercury","Lead"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2426, 'Forensic Medicine', 'Thanatology', 'Easy', 'Forensic_Medicine', 381, '{"id":2426,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":381,"q":"Which is the first organ to putrefy :","o":["Brian","Heart","Prostate","Kidney"],"a":0,"e":"Answer: A. Brian The order of putrefaction is - earliest to last → larynx, trachea → Stomach, intestine → liver, spleen → Brain, Lungs →Heart, Kidney →Bladder, Uterus/Prostrate → Skin, muscles, tendon → lastly, bones.)","pyqMatches":[{"year":"2017","no":127,"q":"Which is the first organ to putrefy :","o":["Brian","Heart","Prostate","Kidney"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":81,"q":"Which is the first organ to putrefy :","o":["Brian","Heart","Prostate","Kidney"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2427, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 382, '{"id":2427,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":382,"q":"Locard is famous for:","o":["Theory of exchange","Fingerprint study","Formula for estimation of stature","System of personal identification using the body measurement"],"a":0,"e":"Answer: A. Theory of exchange Edmund locard is famous for theory of exchange.","pyqMatches":[{"year":"2017","no":128,"q":"Locard is famous for:","o":["Theory of exchange","Fingerprint study","Formula for estimation of stature","System of personal identification using the body measurement"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":82,"q":"Locard is famous for:","o":["Theory of exchange","Fingerprint study","Formula for estimation of stature","System of personal identification using the body measurement"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2428, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 383, '{"id":2428,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":383,"q":"When does basiocciput fuses with basisphenoid?","o":["18 to 22","22 to 25","14-16","12-14"],"a":0,"e":"Answer: A. 18 to 22 The basioccipital fuses with the basisphenoid at about 18 to 21 years.","pyqMatches":[{"year":"2017","no":129,"q":"When does basiocciput fuses with basisphenoid?","o":["18 to 22","22 to 25","14-16","12-14"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":83,"q":"When does basiocciput fuses with basisphenoid?","o":["18 to 22","22 to 25","14-16","12-14"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2429, 'Forensic Medicine', 'Miscellaneous', 'Easy', 'Forensic_Medicine', 384, '{"id":2429,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":384,"q":"What is the smell of mummified body?","o":["Odourless","Putrid","Pungent","Offensive"],"a":0,"e":"Answer: A. Odourless A mummy will smell odourless, this is because the internal organs are removed (which are the biggest factors in the decay process) and replaced with natron (which dries them out, preventing ''proper'' decay). The rest of the body is also dried using natron.","pyqMatches":[{"year":"2017","no":130,"q":"What is the smell of mummified body?","o":["Odourless","Putrid","Pungent","Offensive"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":84,"q":"What is the smell of mummified body?","o":["Odourless","Putrid","Pungent","Offensive"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2430, 'Forensic Medicine', 'Forensic Identification', 'Hard', 'Forensic_Medicine', 385, '{"id":2430,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Hard","source":"Forensic_Medicine","sourceNo":385,"q":"Patient presented with proximal tubule proteinuria. Which metal is likely to be associated with it?","o":["Cadmium","Mercury","Gold","Lead"],"a":0,"e":"Answer: A. Cadmium Early kidney damage and proteinuria seen in people, occupationally or environmentally exposed to cadmium.","pyqMatches":[{"year":"2017","no":131,"q":"Patient presented with proximal tubule proteinuria. Which metal is likely to be associated with it?","o":["Cadmium","Mercury","Gold","Lead"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":85,"q":"Patient presented with proximal tubule proteinuria. Which metal is likely to be associated with it?","o":["Cadmium","Mercury","Gold","Lead"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2431, 'Forensic Medicine', 'Medical Jurisprudence', 'Moderate', 'Forensic_Medicine', 386, '{"id":2431,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":386,"q":"Which of the following constitutional article is not related to children:","o":["23","21-A","42","24"],"a":2,"e":"Answer: C. 42 Constitutional Guarantees that are meant specifically for children include: Right to free and compulsory elementary education for all children in the 6-14 year age group (Article 21 A) Right to be protected from any hazardous employment till the age of 14 years (Article 24) Right to be protected from being abused and forced by economic necessity to enter occupations unsuited to their age or strength (Article 39(e)) Right to equal opportunities and facilities to develop in a healthy manner and in conditions of freedom and dignity and guaranteed protection of childhood and youth against exploitation and against moral and material abandonment (Article 39 (f)) Right to early childhood care and education to all children until they complete the age of six years (Article 45) Besides, Children also have rights as equal citizens of India, just as any other adult male or female: Right to equality (Article 14) Right against discrimination (Article 15) Right to personal liberty and due process of law (Article 21) Right to being protected from being trafficked and forced into bonded labour (Article 23) Right of minorities for protection of their interests (Article 29) Right of weaker sections of the people to be protected from social injustice and all forms of exploitation (Article 46) Right to nutrition and standard of living and improved public health (Article 47)","pyqMatches":[{"year":"2017","no":132,"q":"Which of the following constitutional article is not related to children:","o":["23","21-A","42","24"],"a":2,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":86,"q":"Which of the following constitutional article is not related to children:","o":["23","21-A","42","24"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2432, 'Forensic Medicine', 'Forensic Identification', 'Easy', 'Forensic_Medicine', 387, '{"id":2432,"subject":"Forensic Medicine","chapter":"Forensic Identification","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":387,"q":"Which of the statement regarding Factory act is correct","o":["Child age less than 14 carrying serious work earn more money","Less than 14 yr not done for factory act","More than 72 hour work per week","More than 82 hours a week"],"a":1,"e":"Answer: B- Less than 14 yr not done for factory act The Factory Act prohibits the employment of children below 14 years and declares 15 to 18 years as belonging to the adolescent group. Adolescents require fitness certificate prior to employment in a job. Act also prescribed a maximum 48 hours per week, not exceeding 9 Hours per day with at least half hour rest after 5 hour continuous work.","pyqMatches":[{"year":"2017","no":133,"q":"Which of the statement regarding Factory act is correct","o":["Child age less than 14 carrying serious work earn more money","Less than 14 yr not done for factory act","More than 72 hour work per week","More than 82 hours a week"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":87,"q":"Which of the statement regarding Factory act is correct","o":["Child age less than 14 carrying serious work earn more money","Less than 14 yr not done for factory act","More than 72 hour work per week","More than 82 hours a week"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2433, 'Forensic Medicine', 'Sexual Offences', 'Easy', 'Forensic_Medicine', 388, '{"id":2433,"subject":"Forensic Medicine","chapter":"Sexual Offences","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":388,"q":"Which of the following is the law on child sexual abuse in India?","o":["Child Sexual Abuse Prevention Act","Protection Of Children from Sexual Offences Act (POCSO)","Child Welfare Act","Sexual Offences Act"],"a":1,"e":"Ans: B. POSCO Act The Protection of Children from Sexual Offences (POSCO) Act, 2012,2019 It is applicable to the whole of India. It defines a child as any person below the age of 18 years and provides protection to all children Offences covered under the Act: Penetrative Sexual Assault Aggravated Penetrative Sexual Assault Sexual Assault Aggravated Sexual Assault Sexual Harassment of the Child Use of Child for Pornographic Purposes","pyqMatches":[{"year":"2020","no":71,"q":"Which of the following is the law on child sexual abuse in India?","o":["Child Sexual Abuse Prevention Act","Protection Of Children from Sexual Offences Act (POCSO)","Child Welfare Act","Sexual Offences Act"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2434, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 389, '{"id":2434,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":389,"q":"Punishment of perjury comes under IPC section?","o":["IPC 191","IPC 192","IPC 193","IPC 197"],"a":2,"e":"Ans: C. IPC 193 Defines punishment for fabricating false evidence The witness is liable to be prosecuted for perjury, and the imprisonment may extend up to seven years. 193 IPC: punishment for false evidence, (punishment for perjury): imprisonment up to 7 years and also liable for fine I91 IPC: Giving false evidence (perjury) under oath. I92 IPC: Fabricating false evidence (perjury) THE ESSENTIALS OF FORENSIC MEDICINE AND TOXICOLOGY -Dr. K.S. NARAYAN REDDY 33rd edition-pg-13","pyqMatches":[{"year":"2020","no":72,"q":"Punishment of perjury comes under IPC section?","o":["IPC 191","IPC 192","IPC 193","IPC 197"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2435, 'Forensic Medicine', 'Medical Jurisprudence', 'Easy', 'Forensic_Medicine', 390, '{"id":2435,"subject":"Forensic Medicine","chapter":"Medical Jurisprudence","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":390,"q":"When civil negligence is brought up against a doctor, the onus of proof lies upon -","o":["Judicial first-degree magistrate","Police not below the level of sub-inspector","Doctor","Patient"],"a":3,"e":"Ans: D. Patient \"Generally speaking, it is for the patient in an action for negligence to establish the guilt of the doctor, whose innocence is otherwise assumed.\"- Parikh However, in cases where the rule of res ipsa loquitur is applied, the patient need not prove negligence. Res ipso loquitur means that \"the thing or fact speaks for itself.\" The patient has to merely state what according to him was the act of negligence. Civil negligence When a patient (or his relative, in case of patient''s death) files suit in a civil court to get compensation from his doctor for the injury or death of the patient due to doctor''s negligence. A doctor files a civil suit to get fees from his patient, who refuses to pay alleging negligence. Note that? Even if a doctor is negligent, a patient is not entitled to any compensation if no damage has occurred. An error in diagnosis or treatment is not negligence provided proper care and skill has been exercised. Contributory negligence is not a defense in criminal negligence. (Contributory negligence is any negligence on the part of the patient or his attendant, which along with the doctor''s negligence, contributed to the injury) Criminal negligence cases are dealt with under I.P.C. section 304A.","pyqMatches":[{"year":"2020","no":73,"q":"When civil negligence is brought up against a doctor, the onus of proof lies upon","o":["Judicial first-degree magistrate","Police not below the level of sub-inspector","Doctor","Patient"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2436, 'Forensic Medicine', 'Thanatology', 'Hard', 'Forensic_Medicine', 391, '{"id":2436,"subject":"Forensic Medicine","chapter":"Thanatology","difficulty":"Hard","source":"Forensic_Medicine","sourceNo":391,"q":"Relatives of a patient told during postmortem examination that the person had a tattoo - which was now invisible. How to identify?","o":["Examine the Lymph node","Spectrophotometer","Ordinary light","X-ray"],"a":0,"e":"Answer- A-Examine the Lymph node Tattoo marks are permanent when dye penetrates the dermis. Infrared photography makes old tattoos readily visible. A faded tattoo mark becomes visible by the use of ultraviolet lamp 4 or rubbing the part and examining with a magnifying lens. Marks are recognized even in decomposed bodies(Aret) when the epidermis is removed. Lymph nodes near the tattoo mark show pigment deposition.","pyqMatches":[{"year":"2020","no":74,"q":"Relatives of a patient told during postmortem examination that the person had a tattoo - which was now invisible. How to identify?","o":["Examine the Lymph node","Spectrophotometer","Ordinary light","X-ray"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2437, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 392, '{"id":2437,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":392,"q":"True about hymen in Child rape is-","o":["Hymen easily tears because it is thin","Hymen easily tears because it is in the front","Hymen hardly tears because it is highly elastic","Hymen hardly tears because it is situated deep"],"a":3,"e":"Answer-D- Hymen hardly tears because it is situated deep The hymen may not rupture after rape if: Penetration was not full The hymen is tough, fleshy and elastic In a young child, full penetration may not occur Gautam Biswas Review of forensic medicine & Toxicology2/e; pg- 332 https://www.who.int/violence_injury_prevention/resources/publications/e","pyqMatches":[{"year":"2020","no":75,"q":"True about hymen in Child rape is","o":["Hymen easily tears because it is thin","Hymen easily tears because it is in the front","Hymen hardly tears because it is highly elastic","Hymen hardly tears because it is situated deep"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2438, 'Forensic Medicine', 'Forensic Toxicology', 'Easy', 'Forensic_Medicine', 393, '{"id":2438,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Easy","source":"Forensic_Medicine","sourceNo":393,"q":"Magnan’s symptoms are related to","o":["Cocaine poisoning","Cannabis","Cannabis","Alcohol"],"a":0,"e":"Answer:A. Cocaine poisoning Magnan''s sign or Symptom is a clinical sign in which people with cocaine addiction experience paraesthesia which feels like a constantly moving foreign bodies, (cocaine bugs) such as fine sand or powder, under the skin. It is the most tactile hallucination. Degeneration of the central nervous system occurs, and the patient may suffer from hallucinations, convulsions, delirium, and insanity. Magnan''s symptom or cocaine bugs is characteristic, in which there is a feeling as if grains of sand are lying under the skin or some small insects are creeping on the skin giving rise to itching sensation (formication, tactile hallucination) with resultant excoriation, leading to irregular scratches and ulcers. THE ESSENTIALS OF FORENSIC MEDICINE AND TOXICOLOGY By Dr. K.S. NARAYAN REDDY 33/e- pg-603","pyqMatches":[{"year":"2020","no":76,"q":"Magnan’s symptoms are related to","o":["Cocaine poisoning","Cannabis","Cannabis","Alcohol"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2439, 'Forensic Medicine', 'Forensic Toxicology', 'Hard', 'Forensic_Medicine', 394, '{"id":2439,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Hard","source":"Forensic_Medicine","sourceNo":394,"q":"Parents of the Child complains of assaulted by one of their relatives and anal pain in a child, On investigation test shows yellow iodine crystals with picric acid - what is the name of the test?","o":["Florence test","Barberio’s test","Acid phosphatase test","Creatine Phosphokinase"],"a":1,"e":"Answer: B. Barberio’s test It detects spermin (secreted by the prostate) and uses an aqueous or alcoholic solution of picric acid. A saturated aqueous or alcoholic solution of picric acid, when added to the spermatic fluid, produces yellow needle-shaped rhombic crystals of spermine picrate. The reaction probably depends on the presence of prostatic secretion. The Acid Phosphatase Test: The prostatic secretion element of seminal fluid contains 500 to 1000 times greater acid phosphatase than any other body fluid. Human red cells, semen of higher apes, and juice of cauliflower have acid phosphatase level similar to that of human semen THE ESSENTIALS OF FORENSIC MEDICINE AND TOXICOLOGY By Dr. K.S. NARAYAN REDDY 33/e- pg-434","pyqMatches":[{"year":"2020","no":77,"q":"Parents of the Child complains of assaulted by one of their relatives and anal pain in a child, On investigation test shows yellow iodine crystals with picric acid - what is the name of the test?","o":["Florence test","Barberio’s test","Acid phosphatase test","Creatine Phosphokinase"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2440, 'Forensic Medicine', 'Miscellaneous', 'Moderate', 'Forensic_Medicine', 395, '{"id":2440,"subject":"Forensic Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Forensic_Medicine","sourceNo":395,"q":"The Magistrate can detain the maximum number of days for a mentally ill person as per mental health care is","o":["30 days","90 days","50 days","100 days"],"a":0,"e":"Ans: A. 30 days * If the Magistrate is satisfied that it is necessary to detain the alleged mentally ill person in a psychiatric hospital, he passes a Reception Order (order for admission and detention), which is valid for 30 days. If he is not satisfied, he may refuse the application, giving his reasons in writing, a copy of which is supplied to the applicant. * Admission Under Special Circumstance - A mentally ill person may not be able to express his willingness for admission as a voluntary patient, Such person can be admitted in a psychiatric hospital (psychiatric nursing home) for a period of 90 days if an application is made by a relatives and friends","pyqMatches":[{"year":"2020","no":78,"q":"The Magistrate can detain the maximum number of days for a mentally ill person as per mental health care is","o":["30 days","90 days","50 days","100 days"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2441, 'Medicine', 'Neurology', 'Hard', 'Internal_Medicine', 1, '{"id":2441,"subject":"Medicine","chapter":"Neurology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":1,"q":"A 25 year old female presents with generalized restriction of eye movement in all direction, intermittent ptosis, proximal muscle weakness and fatigability.Which is the MOST useful test in making the diagnosis?","o":["CPK","Edrophonium test","EMG","Muscle biopsy"],"a":1,"e":"This patient is showing signs and symptoms of Myasthenia gravis. Edrophonium test is the most useful test in making a diagnosis of this condition because of the rapid onset and short duration of its effect. This test is considered to be positive if there is any improvement in the weakness of this patient after administration of edrophonium. Other diagnostic tests used for diagnosing myasthenia gravis are: Acetyl choline receptor antibodies: Presence of this antibodies is virtually diagnostic of MG, but a negative test does not exclude the disease. Rapid nerve stimulation test: In this test electric shocks are delivered at a rate of 2 or 3 per second to the appropriate nerves, and action potentials are recorded from the muscles. In these patients there is a rapid reduction of >10–15% in the amplitude of the evoked responses. Ref: Drachman D.B. (2012). Chapter 386. Myasthenia Gravis and Other Diseases of the Neuromuscular Junction. In D.L. Longo, A.S. Fauci, D.L. Kasper, S.L. Hauser, J.L. Jameson, J. Loscalzo (Eds), Harrison''s Principles of Internal Medicine, 18e.","pyqMatches":[{"year":"2013","no":1335,"q":"A 25 year old female presents with generalized restriction of eye movement in all direction, intermittent ptosis, proximal muscle weakness and fatigability.Which is the MOST useful test in making the diagnosis?","o":["CPK","Edrophonium test","EMG","Muscle biopsy"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2442, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 2, '{"id":2442,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":2,"q":"Kayser- Fleischer rings (KF rings) are seen in:","o":["Pterygium","Hematochromatosis","Wilson''s disease","Menke''s kinked hair syndrome"],"a":2,"e":"Wilson''s disease","pyqMatches":[{"year":"2015","no":1012,"q":"Kayser- Fleischer rings (KF rings) are seen in:","o":["Pterygium","Hematochromatosis","Wilson''s disease","Menke''s kinked hair syndrome"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2443, 'Medicine', 'Gastroenterology', 'Moderate', 'Internal_Medicine', 3, '{"id":2443,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":3,"q":"All are features of Abetalipoproteinemia, EXCEPT:","o":["Plasma levels of cholesterol and triglyceride are extremely low","Manifest in early childhood with diarrhea","Progressive pigmented retinopathy seen","Neurological manifestation as ataxia in first decade"],"a":3,"e":"Plasma levels of cholesterol and triglyceride are extremely low in this disorder, and chylomicrons. Abetalipoproteinemia usually presents in early childhood with diarrhea and failure to thrive. The neurological manifestations like decreased distal lower extremity vibratory and proprioceptive sense, dysmetria, ataxia, and the development of a spastic gait, often by the third or fourth decade. Patients also develop a progressive pigmented retinopathy presenting with decreased night and color vision. Ref: Harrisons Principles of Internal Medicine, 18th Edition, Page 3153","pyqMatches":[{"year":"2016","no":277,"q":"All are features of Abetalipoproteinemia, EXCEPT:","o":["Plasma levels of cholesterol and triglyceride are extremely low","Manifest in early childhood with diarrhea","Progressive pigmented retinopathy seen","Neurological manifestation as ataxia in first decade"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2444, 'Medicine', 'Hematology', 'Easy', 'Internal_Medicine', 4, '{"id":2444,"subject":"Medicine","chapter":"Hematology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":4,"q":"Which of the following findings is diagnostic of iron deficiency anemia?","o":["Increased TIBC, decreased serum ferritin","Decreased TIBC, decreased serum ferritin","Increased TIBC, increased serum ferritin","Decreased TIBC, increased serum ferritin"],"a":0,"e":"Iron deficiency anemia is associated with increased Total iron binding capacity (TIBC) and decreased serum ferritin ( storage form of iron) Ref: Harrison’s Principles of Internal Medicine, 17th Edition, Page 631, 663; Davidson’s principles and practice of Medicine, 20th Edition, Chapter 24, Page 1025-1027 &1030","pyqMatches":[{"year":"2015","no":453,"q":"Which of the following findings is diagnostic of iron deficiency anemia?","o":["Increased TIBC, decreased serum ferritin","Decreased TIBC, decreased serum ferritin","Increased TIBC, increased serum ferritin","Decreased TIBC, increased serum ferritin"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2445, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 5, '{"id":2445,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":5,"q":"Which of the following endocrine tumors is most commonly seen in MEN I?","o":["Insulinoma","Gastrinoma","Glucagonoma","Somatostatmoma"],"a":1,"e":"Amongst the options provided, gastrinomas are the most common enteropancreatic tumors associated with MEN I with insulinomas being the second most common. Ref: Harrison’s Principles of Internal Medicine, 17th Edition, Page 2358 & 2359; 16th/ 2232; Davidson’s principles and practice of Medicine, 20th Edition, Chapter 20, Page 803","pyqMatches":[{"year":"2014","no":1278,"q":"Which of the following endocrine tumors is most commonly seen in MEN I?","o":["Insulinoma","Gastrinoma","Glucagonoma","Somatostatmoma"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2446, 'Medicine', 'Hematology', 'Moderate', 'Internal_Medicine', 6, '{"id":2446,"subject":"Medicine","chapter":"Hematology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":6,"q":"All of the following statements regarding Sickle Cell Anemia is true, EXCEPT:","o":["Patients require frequent blood transfusions","Patients usually presents before the age of 6 months","There is a positive correlation between HBS and polymerization of HBS","Reccurent infections is the most common cause of death"],"a":1,"e":"Sickle cell anemia is an autosomal recessive disorder, caused by an amino acid substitution of valine for glutamine in the sixth position on the beta-globin chain. Onset of the disease starts during the first year of life especially after 6 months of age, when hemoglobin F levels falls, as a signal is sent to switch from production of gamma globin to beta globin. Hemoglobin S is unstable and polymerizes during hypoxemia and acidosis, leading to sickling of red blood cells. Patients develops jaundice, pigmented gallstones, spleenomegaly, and poorly healing ulcers over the lower tibia. Acute painful episodes can occur due to acute vaso-occlusion by clusters of sickled red cells during infection, dehydration, or hypoxia. Common sites of acute painful episodes include the bones and the chest. Ref: Current Medical Diagnosis and Treatment 2012, Chapter 13 ; Medical Assisting: Administrative and Clinical Competencies By Lucille Keir, 6th Edition, Page 471","pyqMatches":[{"year":"2012","no":1153,"q":"All of the following statements regarding Sickle Cell Anemia is true, EXCEPT:","o":["Patients require frequent blood transfusions","Patients usually presents before the age of 6 months","There is a positive correlation between HBS and polymerization of HBS","Reccurent infections is the most common cause of death"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2447, 'Medicine', 'Hematology', 'Moderate', 'Internal_Medicine', 7, '{"id":2447,"subject":"Medicine","chapter":"Hematology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":7,"q":"Leukoerythroblastic picture may be seen in all of the following conditions, except:","o":["Myelofibrosis","Metastatic carcinoma","Gaucher''s disease","Thalassemia"],"a":3,"e":"Leukoerythroblastosis refers to the presence of immature nucleated RBCs, immature white blood cells, and megakaryocyte fragments on the peripheral blood smear. It occur due to bone marrow infiltration. When marrow infiltration causes anemia or pancytopenia, it is referred to as myelophthisic anemia. The most common cause of myelophthisis includes metastatic carcinoma of the lung, breast, or prostate. Other causes include hematologic malignancies (leukemia, lymphoma), infections (tuberculosis, fungi), and metabolic diseases (Gaucher disease, Niemann-Pick disease). Thalassemia is not associated with leukoerythroblastosis. Ref: CURRENT Diagnosis & Treatment in Family Medicine, 3rd Edition, Chapter 31","pyqMatches":[{"year":"2014","no":1474,"q":"Leukoerythroblastic picture may be seen in all of the following conditions, except:","o":["Myelofibrosis","Metastatic carcinoma","Gaucher''s disease","Thalassemia"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2448, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 8, '{"id":2448,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":8,"q":"All of the following are major complications of massive transfusion, except:","o":["Hypokalemia","Hypothermia","Hypomagnesemia","Hypocalcemia"],"a":0,"e":"Ans:A.)Hypokalemia. Complications usually seen with massive blood transfusion are 1) hyperkalemia, 2) hypocalcemia, 3)hypomagnesemia 4) hyperammonemia, 5) hypothermia, 6) Acidosis 7)dilutional coagulopathies and DIC (most worrisome problem after massive transfusion and is the usual cause of death after massive blood transfusion) and 8) ARDS. The lethal triad of acidosis, hypothermia, and coagulopathy associated with MT is associated with a high mortality rate.","pyqMatches":[{"year":"2015","no":1129,"q":"All of the following are major complications of massive transfusion, except:","o":["Hypokalemia","Hypothermia","Hypomagnesemia","Hypocalcemia"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2449, 'Medicine', 'Hematology', 'Easy', 'Internal_Medicine', 9, '{"id":2449,"subject":"Medicine","chapter":"Hematology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":9,"q":"Richter’s syndrome refers to which of the following malignant transformation?","o":["CLL evolving into aggressive lymphoma","Hairy cell leukemia evolving to AML","Blast crisis in CML","Splenic infiltration in NHL"],"a":0,"e":"Ans. A. CLL evolving into aggressive lymphoma Richter''s transformation or Richter''s syndrome is a complication of B cell chronic lymphocytic leukemia (CLL) or hairy cell leukemia (HCL) in which the leukemia changes into a fast-growing diffuse large B cell lymphoma.","pyqMatches":[{"year":"2016","no":442,"q":"Richter’s syndrome refers to which of the following malignant transformation?","o":["CLL evolving into aggressive lymphoma","Hairy cell leukemia evolving to AML","Blast crisis in CML","Splenic infiltration in NHL"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2450, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 10, '{"id":2450,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":10,"q":"Sickle cell anemia leads to resistance towards?","o":["P. falciparum","P. ovale","P. malariae","P. vivax"],"a":0,"e":"Individuals with sickle cell trait (hemoglobin genotype AS) are resistant to the lethal effects of Plasmodium falciparum infection. This is because the sickle cell traits prevents the development of high parasitemia, probably partly as a result of parasitized red cells sickling in the circulation and being removed by the spleen before they can develop into schizonts. Absence of RBC Duffy antigen confers resistance to P. Vivax. Ref: Harrison''s 17th ed chapter 213 ; Essentials of clinical immunology by Helen Chapel, Man;e. Haeney, Siraj Misbah, 5th edition, Page 48 ; Lecture Notes: Tropical Medicine edited by G. V. Gill, Nick Beeching, 2011, Page 62.","pyqMatches":[{"year":"2014","no":1476,"q":"Sickle cell anemia leads to resistance towards?","o":["P. falciparum","P. ovale","P. malariae","P. vivax"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2451, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 11, '{"id":2451,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":11,"q":"Romiplostim acts on which of the following receptors:","o":["Thrombopoeitin","IL 6","IL 8","PGE 1"],"a":0,"e":"Romiplostim: Genetically engineered protein in which the Fc component of a human antibody is fused to two copies of a peptide that stimulates the thrombopoietin receptors; approved for treatment of idiopathic thrombocytopenic purpura Ref: Katzung 11th edition Chapter 33.","pyqMatches":[{"year":"2012","no":569,"q":"Romiplostim acts on which of the following receptors:","o":["Thrombopoeitin","IL 6","IL 8","PGE 1"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2452, 'Medicine', 'Hematology', 'Easy', 'Internal_Medicine', 12, '{"id":2452,"subject":"Medicine","chapter":"Hematology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":12,"q":"Oncogene associated with burkitt''s lymphoma is:","o":["BCL-1, IgH","BCL-2, IgH","C-MYC","ALK"],"a":2,"e":"Disease Cytogenetic Abnormality Oncogene Mantle cell lymphoma t(11;14)(q13;q32) BCL-1, IgH Follicular lymphoma t(14;18)(q32;q21) BCL-2, IgH Diffuse large cell lymphoma t(3;-)(q27;-) t(17;-)(p13;-) BCL-6 p53 Burkitt''s lymphoma, Burkitt''s leukemia t(8;-)(q24;-) C-MYC CD30+ Anaplastic large cell lymphoma t(2;5)(p23;q35) ALK Lymphoplasmacytoid lymphoma t(9;14)(p13;q32) PAX5, IgH Ref: Harrison, E-18,P-921","pyqMatches":[{"year":"2016","no":440,"q":"Oncogene associated with burkitt''s lymphoma is:","o":["BCL-1, IgH","BCL-2, IgH","C-MYC","ALK"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2453, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 13, '{"id":2453,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":13,"q":"FALSE statement regarding the ECG in acute pericarditis is:","o":["T wave inversion develop before ST elevations return to baseline","Global ST segment elevation is seen in early pericarditis","Sinus tachycardia is a common finding","PR segment depression is present in majority of patients"],"a":0,"e":"T wave inversion develop after ST elevations return to baseline. There are four stages of ECG changes in the evolution of acute pericarditis. In stage 1, there is widespread elevation of the ST segments, often with upward concavity, involving two or three standard limb leads and V2 to V6, with reciprocal depressions only in aVR and sometimes V1, as well as depression of the PR segment Usually there are no significant changes in QRS complexes. In stage 2, after several days, the ST segments return to normal, and only then, or even later, do the T waves become inverted (stage 3). Ultimately, weeks or months after the onset of acute pericarditis, the ECG returns to normal in stage 4. Ref: Harrisons principles of internal medicine, 18th edition, Page: 1971","pyqMatches":[{"year":"2016","no":1037,"q":"FALSE statement regarding the ECG in acute pericarditis is:","o":["T wave inversion develop before ST elevations return to baseline","Global ST segment elevation is seen in early pericarditis","Sinus tachycardia is a common finding","PR segment depression is present in majority of patients"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2454, 'Medicine', 'Rheumatology', 'Easy', 'Internal_Medicine', 14, '{"id":2454,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":14,"q":"Omalizumab is used in treatment of:","o":["Breast carcinoma","Asthma","Rheumatoid arthritis","None of the above"],"a":1,"e":"Omalizumab is a blocking antibody that neutralizes circulating IgE without binding to cell- bound IgE; it thus inhibits IgE-mediated reactions. This treatment has been shown to reduce the number of exacerbations in patients with severe asthma and may improve asthma control. However, the treatment is very expensive and only suitable for highly selected patients who are not controlled on maximal doses of inhaler therapy and have a circulating IgE within a specified range. Ref: Harrison’s principle of internal medicine 17th edition, chapter 248.","pyqMatches":[{"year":"2012","no":533,"q":"Omalizumab is used in treatment of:","o":["Breast carcinoma","Asthma","Rheumatoid arthritis","None of the above"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2455, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 15, '{"id":2455,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":15,"q":"The pathognomonic finding in miliary TB is which of the following?","o":["Bone marrow infiltrations","Choroid tubercles","Miliary mottling in chest X-Ray","Histological finding in liver biopsy"],"a":1,"e":"Eye examination may reveal choroidal tubercles, which are pathognomonic of miliary TB, seen in up to 30% of cases. Reference: Harrisons Principles of Internal Medicine, 18th Edition, Page 1349","pyqMatches":[{"year":"2014","no":1295,"q":"The pathognomonic finding in miliary TB is which of the following?","o":["Bone marrow infiltrations","Choroid tubercles","Miliary mottling in chest X-Ray","Histological finding in liver biopsy"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2456, 'Medicine', 'Respiratory Medicine', 'Hard', 'Internal_Medicine', 16, '{"id":2456,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Hard","source":"Internal_Medicine","sourceNo":16,"q":"All are important pathogens causing pneumonia in COPD patients, EXCEPT:","o":["Haemophilus influenzae","Pseudomonas aeruginosa","Legionella spp","Klebsiella pneumoniae"],"a":3,"e":"All are important pathogens causing pneumonia in COPD patients Haemophilus influenzae Pseudomonas aeruginosa Legionella spp S. pneumoniae Moraxella catarrhalis Chlamydia pneumoniae Klebsiella is an important pathogen causing pneumonia in chronic alcoholism. Ref: Harrison, E-18, P-2132","pyqMatches":[{"year":"2012","no":1020,"q":"All are important pathogens causing pneumonia in COPD patients, EXCEPT:","o":["Haemophilus influenzae","Pseudomonas aeruginosa","Legionella spp","Klebsiella pneumoniae"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2457, 'Medicine', 'Miscellaneous', 'Hard', 'Internal_Medicine', 17, '{"id":2457,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Internal_Medicine","sourceNo":17,"q":"PNH patients will be having deficient surface proteins that normally protect the red cells from activated compliments. What are the two deficient surface proteins?","o":["CD 45 and CD 59","CD 51 and CD 59","CD 55 and CD 59","CD58 and CD 59"],"a":2,"e":"The definitive diagnosis of PNH is based on the demonstration that a substantial proportion of the patient''s red cells have an increased susceptibility to complement (C), due to the deficiency on their surface of proteins (particularly CD59 and CD55). Reference: Harrisons Principles of Internal Medicine, 18th Edition, Page 884","pyqMatches":[{"year":"2012","no":481,"q":"PNH patients will be having deficient surface proteins that normally protect the red cells from activated compliments. What are the two deficient surface proteins?","o":["CD 45 and CD 59","CD 51 and CD 59","CD 55 and CD 59","CD58 and CD 59"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2458, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 18, '{"id":2458,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":18,"q":"Which of the following biochemical test is used to diagnose Dubin Johnson syndrome?","o":["Serum transaminases","Bromsulphalein test (BSP)","Hippurate test","Gamma glutamyl transferase level"],"a":1,"e":"Bromsulphalein test (BSP) is the diagnostic test for Dubin-Johnson Syndrome. Biliary excretion of numerous anionic compounds such as Bromsulphalein (BSP) is compromised in Dubin-Johnson Syndrome (DJS). In this test, BSP is administered as IV bolus and its clearance from plasma is determined. BSP levels show a characteristic rise in patients with DJS after 90 minutes of injection, due to reflux of conjugated BSP into the circulation from the hepatocyte. Ref: Davidson’s principles and practice of Medicine, 20th Edition, Chapter 23, Page 945; Harrison’s Principles of Internal Medicine, 16th Edition, Page 1821; Digestive Diseases and Sciences Vol/17 numbers 6.","pyqMatches":[{"year":"2016","no":1375,"q":"Which of the following biochemical test is used to diagnose Dubin Johnson syndrome?","o":["Serum transaminases","Bromsulphalein test (BSP)","Hippurate test","Gamma glutamyl transferase level"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2459, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 19, '{"id":2459,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":19,"q":"Cholecystokinin is produced from:","o":["Hepatocyte","Gastric mucosa","Duodenal mucosa","Epithelial cells of distal common bile duct"],"a":2,"e":"The major factor controlling the contraction of the gallbladder is the hormone cholecystokinin (CCK), which is released from the duodenal mucosa (I cells) in response to the ingestion of fats and amino acids. Reference: Harrisons Principles of Internal Medicine, 18th Edition, Page 2616","pyqMatches":[{"year":"2015","no":261,"q":"Cholecystokinin is produced from:","o":["Hepatocyte","Gastric mucosa","Duodenal mucosa","Epithelial cells of distal common bile duct"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2460, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 20, '{"id":2460,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":20,"q":"Esophageal manometry is useful all this conditions EXCEPT:","o":["Achalasia","Diffuse esophageal spasm","To assess the peristaltic integrity prior to the surgery for GERD","Malignancy"],"a":3,"e":"Esophageal manometry, or motility testing, entails positioning a pressure sensing catheter within the esophagus. Manometry is used to diagnose","pyqMatches":[{"year":"2012","no":1113,"q":"Esophageal manometry is useful all this conditions EXCEPT:","o":["Achalasia","Diffuse esophageal spasm","To assess the peristaltic integrity prior to the surgery for GERD","Malignancy"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2461, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 21, '{"id":2461,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":21,"q":"Which of the following drugs is useful in the prophylaxis of migraine?","o":["Propranolol","Sumatriptan","Domperidone","Ergotamine"],"a":0,"e":"Drugs such as topiramate, valproate, propanolol, timolol, candesartan, verapamil and amitryptilline are indicated in migraine prophylaxis. Migraine prophylaxis is indicated when migraine headaches occur more than two or three times a month or when it is associated with significant disability. After initiation of therapy,it should be continued for several months. Once the patient remains headache free, the dose is tapered and the drug is eventually withdrawn. Botulinum toxin type A was approved by the US Food and Drug Administration (FDA) for migraine prevention in late 2010. Ref: Current Medical Diagnosis and treatment 2012, Chapter 24","pyqMatches":[{"year":"2016","no":1368,"q":"Which of the following drugs is useful in the prophylaxis of migraine?","o":["Propranolol","Sumatriptan","Domperidone","Ergotamine"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2462, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 22, '{"id":2462,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":22,"q":"All of the following are true about treatment of migraine, EXCEPT:","o":["Naratriptan acts longer than sumatryptan","Sumatryptan is used in acute attack of migraine","Sumatryptan acts on 5HT 1B/1D receptors in great vessels","Sumatryptan is used for chronic migraine"],"a":3,"e":"Sumatriptan is an agonist at 5-HT serotonin receptors, in particular 5HT 1B/1Dreceptors. It is used in the treatment of acute migraine attacks but is not recommended for migraine prophylaxis. The drug provides rapid relief of migraine headache as well as relief of the associated manifestations of migraine including nausea, vomiting, photophobia and phonophobia. Short-acting, rapidly effective triptans include almotriptan, sumatriptan, rizatriptan, zolmitriptan, and eletriptan, whereas naratriptan and frovatriptan have the longest half-lives. 5HT 1B/1Dreceptor agonists are sumatriptan, naratriptan, rizatriptan, and zolmitriptan. Ref: Instant Pharmacology By Kourosh Saeb-Parsy, Ravi G. Assomull, Fakhar Z. Khan, Kasra Saeb-Parsy, Eamonn Kelly, 1999, Page 300 ; Harrison''s 17th ed chapter 15","pyqMatches":[{"year":"2014","no":1243,"q":"All of the following are true about treatment of migraine, EXCEPT:","o":["Naratriptan acts longer than sumatryptan","Sumatryptan is used in acute attack of migraine","Sumatryptan acts on 5HT 1B/1D receptors in great vessels","Sumatryptan is used for chronic migraine"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2463, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 23, '{"id":2463,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":23,"q":"Lateral medullary syndrome is due to the occlusion of which of the following vessels?","o":["Posterior superior cerebellar artery","Anterior inferior cerebellar artery","Basilar artery","Vertebral artery"],"a":3,"e":"Lateral medullary syndrome is otherwise known as Wallenberg’s syndrome or PICA syndrome or vertebral artery syndrome. Occlusive disease of the intracranial segment of the vertebral artery is a much more frequent cause of the lateral medullary syndrome. Signs and symptoms include: Ipsilateral side Horner’s syndrome Decrease in pain and temperature sensation on ipsilateral side of face Cerebellar signs (ataxia) Contralateral side: Decreased pain and temperature on contralateral body Dysphagia, dysarthria, hoarseness, paralysis of vocal cord Vertigo, nausea, vomiting, hiccups Nystagmus, diplopia No facial or extremity muscle weakness seen in this syndrome. Ref: Physical Medicine and Rehabilitation Board Review By Sara Cuccurullo, 2004, Page 11 ; Harrison''s Internal Medicine 17th ed Chapter 364. Cerebrovascular Diseases, Brainstem disorders by Peter P Urban, Louis R Caplan page 205-207.","pyqMatches":[{"year":"2015","no":1155,"q":"Lateral medullary syndrome is due to the occlusion of which of the following vessels?","o":["Posterior superior cerebellar artery","Anterior inferior cerebellar artery","Basilar artery","Vertebral artery"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2464, 'Medicine', 'Neurology', 'Moderate', 'Internal_Medicine', 24, '{"id":2464,"subject":"Medicine","chapter":"Neurology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":24,"q":"POEMS Syndrome includes all, EXCEPT:","o":["Polyneuropathy","Organomegaly","Endocrinopathy","Multiple sclerosis"],"a":3,"e":"The features of this syndrome are polyneuropathy, organomegaly, endocrinopathy, multiple myeloma, and skin changes (POEMS). Patients usually have a severe, progressive sensorimotor polyneuropathy associated with sclerotic bone lesions from myeloma. Polyneuropathy occurs in ~1.4% of myelomas, but the POEMS syndrome is only a rare subset of that group. Unlike typical myeloma, hepatomegaly and lymphadenopathy occur in about two-thirds of patients, and splenomegaly is seen in one-third. Ref: Harrison’s principle of internal medicine 17th edition, Chapter 106.","pyqMatches":[{"year":"2013","no":1323,"q":"POEMS Syndrome includes all, EXCEPT:","o":["Polyneuropathy","Organomegaly","Endocrinopathy","Multiple sclerosis"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2465, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 25, '{"id":2465,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":25,"q":"Barr body is found in the following phase of the cell cycle:","o":["Interphase","Metaphase","GI phase","Telophase"],"a":0,"e":"A i.e. Interphase The inactive X can be seen in the interphase nucleus as a darkly staining small mass in contact with the nuclear membrane known as the Barr body or X chromatin. Barr body is the inactivated X chromosome. In non dividing interphase cells it remains tightly coiled and can be seen as a dark staining body within the nucleus.","pyqMatches":[{"year":"2016","no":401,"q":"Barr body is found in the following phase of the cell cycle:","o":["Interphase","Metaphase","GI phase","Telophase"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2466, 'Medicine', 'Neurology', 'Moderate', 'Internal_Medicine', 26, '{"id":2466,"subject":"Medicine","chapter":"Neurology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":26,"q":"All of the following statements about Pulsus Bigeminus are true, except:","o":["Must be distinguished from Pulsus Alternans","Is a sign of digitalis toxicity","Compensatory pause is absent","Rhythm is Irregular"],"a":2,"e":"Answer is C (Compensatory pause is absent): Pulsus Bigeminus is associated with a compensatory Pause. Compensatory pause is absent in Pulsus Alternans Pulsus Bigeminus is a disorder of rhythm (Irregular rhythm) caused by a normal heat alternating with a premature contraction and a compensatory pause resulting in alternation of the strength of pulse. The stroke volume of the premature beat is diminished in relation to that of the normal beats, and the pulse varies in amplitude accordingly. Pulsus Bigeminus most closely mimics Pulsus Alternans from which it must be distinguished. In Pulsus Alternans the rhythm is regular and the compensatory pause is absent.","pyqMatches":[{"year":"2014","no":1430,"q":"All of the following statements about Pulsus Bigeminus are true, except:","o":["Must be distinguished from Pulsus Alternans","Is a sign of digitalis toxicity","Compensatory pause is absent","Rhythm is Irregular"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2467, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 27, '{"id":2467,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":27,"q":"Pulsus Bigeminus is seen in therapy with:","o":["Digitalis","Beta Blockers","ACE Inhibitors","Calcium Channel Blockers"],"a":0,"e":"Answer is A (Digitalis) Pulsus Bigeminus is recognized as a cause of digitalis toxicity. Pulsus Bigeminus is a disorder of rhythm (Irregular rhythm; arrhythmia) most commonly caused by Premature Ventricular Contractions that results in a pulse with irregular rhythm that alternates in amplitude (pressure) from beat to beat. The most common cause of Pulsus Bigeminus is Digitalis and Pulsus Bigeminus is recognized as a cause of digitalis toxicity.","pyqMatches":[{"year":"2014","no":1431,"q":"Pulsus Bigeminus is seen in therapy with:","o":["Digitalis","Beta Blockers","ACE Inhibitors","Calcium Channel Blockers"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2468, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 28, '{"id":2468,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":28,"q":"Wide pulse pressure is seen in all except:","o":["PDA","Aortic stenosis","Aortic Regurgitation","A.V. malformation"],"a":1,"e":"Answer is B (Aortic Stenosis) Aortic Stenosis is associated with a narrow pulse pressure. Patent Ductus Arteriosus (PDA), Aortic Regurgitation and AV Malformations (Arteriovenous shunting) are all associated with a wide pulse pressure.","pyqMatches":[{"year":"2015","no":1105,"q":"Wide pulse pressure is seen in all except:","o":["PDA","Aortic stenosis","Aortic Regurgitation","A.V. malformation"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2469, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 29, '{"id":2469,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":29,"q":"Erb''s Point in cardiology refers to:","o":["Right 2nd intercostal space","Left 2nd intercostal space","Right 3rd intercostal space","Left 2nd intercostal space"],"a":2,"e":"Answer is C (Right 3rd intercostal space) In cardiology, Erb''s point refers to the third intercostal space on the left sternal border where both components of S2 (A2 and P2) can be well appreciated. Both components of S2 (A2 and P2) are usually well transmitted to the Erb''s point. The physiological splitting of S2 into A2 and P2 is believed to be appreciated best at the Erb''s point or in the pulmonic area. A2 is best heard over the aortic area in the right second intercostal space P2 is best heard over the pulmonic area in the left second intercostal space Second heart sound (S2) is best heard over the pulmonic area (Since both A2 and P2 can be heard at the pulmonic area) and at the Erb''s Point. Note that even at the pulmonic area A2 is louder than P2","pyqMatches":[{"year":"2014","no":1263,"q":"Erb''s Point in cardiology refers to:","o":["Right 2nd intercostal space","Left 2nd intercostal space","Right 3rd intercostal space","Left 2nd intercostal space"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2470, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 30, '{"id":2470,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":30,"q":"S2 is best appreciated in:","o":["3rd left intercostal space","2nd right intercostal space","4th left intercostal space","5 left intercostal space"],"a":0,"e":"Answer is A (3rd left intercostal space) Best areas to auscultate for both components of the second heart sound (A2 and P2) are either the left sternal border at the level of second intercostal space (Pulmonic area) or the left sternal border at the level of third intercostal space (Erb''s point). The second heart sound has two components A2 (from Aortic closure) and P2 (from pulmonary closure). P2 is a soft sound that is poorly transmitted. It is best heard at the pulmonic area and is transmitted only as far as the Erb''s point. A2 is a loud sound best heard over the aortic area but since it is widely transmitted it may be heard across all areas of the chest even as far as the apex. Second heart sound (S2) is best heard over the pulmonic area (Since both A2 and P2 can be heard at the pulmonic area). Note that even at the pulmonic area A2 is louder than P2. The other area to auscultate for both components of the second heart sound is at the left sternal border of the third intercostal space (Erb ''s point)","pyqMatches":[{"year":"2014","no":1434,"q":"S2 is best appreciated in:","o":["3rd left intercostal space","2nd right intercostal space","4th left intercostal space","5 left intercostal space"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2471, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 31, '{"id":2471,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":31,"q":"Paradoxical splitting of second heart sound is seen in?","o":["RBBB","ASD","LBBB","VSD"],"a":2,"e":"Answer is C (LBBB) Left Bundle Branch Block (LBBB) is typically associated with Reversed or Paradoxical Splitting of S2 Paradoxical splitting of second heart sound is caused by delayed A2 or early P2. Left Bundle Branch Block (LBBB) is associated with delayed Aortic closure (delayed A2) due to delayed electrical activation of the left ventricle. ASD and RBBB are associated with a wide physiological (non- paradoxical) split of second heart sound due to delayed pulmonic closure (Delayed P2) while VSD is associated with a wide physiological (non-paradoxical) split second heart sound from early aortic closure (Early A2).","pyqMatches":[{"year":"2012","no":1014,"q":"Paradoxical splitting of second heart sound is seen in?","o":["RBBB","ASD","LBBB","VSD"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2472, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 32, '{"id":2472,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":32,"q":"All of the following statements about third Heart sound (S3) are true, except:","o":["Occurs due to rapid filling of the ventricles during atrial systole","Seen in in Constrictive Pericarditis","Seen in Atrial Septal Defect (ASD)","Seen in Ventricular Septal Defect (VSD)"],"a":0,"e":"Answer is A (Occurs due to rapid filling of the ventricles during atrial systole ) Third heart sound occurs at the end of early rapid filling phase of the ventricle but not at the time of atrial systole. The heart sound associated with ventricular filling during atrial systole is the fourth heart sound (S4) Fourth Heart sound occurs in association with an effective atrial contraction() (It is presumably caused by in-rush of blood into the ventricles when the atria contracts and hence it is also called the ''Atrial Heart Sound) Pathological Third Heart Sound (S3) may be associated with ASD and VSD `A pathological S3 is often present in large left to right shunts due to high flow across the mitral valve with VSD or patent ductus arteriosus and with high flow across the tricuspid valve with ASD. The presence of this sound in these conditions does not imply congestive heart failure, and such patients may maintain normal myocardial contractility for years after the S3 is detected''- ''Hurst: The Heart'' 11th/271 Congenital Heart Diseases associated with Loud S3 Ventricular septal Defect (VSD)() Patent Ductus Arteriosus (PDA)Q Atrial Septal Defect (ASD)Q Pathological Third Heart Sound (S3) may be associated with Constrictive Pericarditis Constrictive pericarditis is characterixstically associated with pericardial knock which is a distinct form of third heart sound (S3) `Pericardial knock is S3 that occurs earlier (0.1 to 0.12 after A2) and is higher pitched than normal. Its presence depends upon the restrictive effects of the adherent pericardium which halts diastolic filling abruptly''","pyqMatches":[{"year":"2012","no":145,"q":"All of the following statements about third Heart sound (S3) are true, except:","o":["Occurs due to rapid filling of the ventricles during atrial systole","Seen in in Constrictive Pericarditis","Seen in Atrial Septal Defect (ASD)","Seen in Ventricular Septal Defect (VSD)"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2473, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 33, '{"id":2473,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":33,"q":"Left Axis Deviation is seen as","o":["Positive in Lead I and Positive in Lead II","Positive in Lead I and Negative in Lead II","Negative in Lead I and Negative in Lead II","Negative in Lead I and positive in Lead II"],"a":1,"e":"Answer is B (Positive in Lead I and Negative in Lead II) Left axis deviation is seen as positive deflexion in Lead I and a Negative deflection in Lead II. Calculating the cardiac axis: Normal Axis Right axis deviation Left axis deviation Lead I Positive Negative Positive Lead II Positive Positive or negative Negative Lead III Positive or negative Positive Negative Note: Lead I : POSITIVE BETWEEN -90 TO +90 (CLOCKWISE) Lead II : POSITIVE BETWEEN -30 TO +150 (CLOCKWISE) Lead III : POSITIVE BETWEEN +30 TO -150 (CLOCKWISE)","pyqMatches":[{"year":"2014","no":1438,"q":"Left Axis Deviation is seen as","o":["Positive in Lead I and Positive in Lead II","Positive in Lead I and Negative in Lead II","Negative in Lead I and Negative in Lead II","Negative in Lead I and positive in Lead II"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2474, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 34, '{"id":2474,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":34,"q":"P wave is due to:","o":["Atrial depolarization","Atrial repolarization","Ventricular depolarization","Ventricular repolarization"],"a":0,"e":"Answer is A (Atrial Depolarization) P wave is produced due to atrial depolarization. Intervals Events in the Heart During Interval P wave Atrial depolarization PR interval Atrial depolarization and conduction through AV node QRS duration Ventricular depolarization and atrial repolarization QT interval Ventricular depolarization plus ventricular repolarization ST interval (QT minus QRS) Ventricular repolarization","pyqMatches":[{"year":"2013","no":134,"q":"P wave is due to:","o":["Atrial depolarization","Atrial repolarization","Ventricular depolarization","Ventricular repolarization"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2475, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 35, '{"id":2475,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":35,"q":"Absent P Wave is seen in:","o":["Atrial Fibrillation","Cor-pulmonale","Mitral Stenosis","COPD"],"a":0,"e":"Answer is A (Atrial Fibrillation) P wave is typically absent in Atrial Fibrillation. COPD and Cor- Pulmonale are associated with tall p waves from Right Atrial Enlargement (P-Pulmonale) while Mitral Stenosis is typically associated with a wide and notched p wave from Left Atrial Enlargement (P-Mitrale) Causes of Absent Wave: Atrial fibrillation (p'' wave is absent or replaced by fibrillary T wave) Atrial flutter (p'' wave is replaced by flutter wave, which shows saw- tooth appearance). SA block or sinus arrest Nodal rhythm (usually abnormal, small p wave). Ventricular ectopic and ventricular tachycardia. Supraventricular tachycardia (p'' wave is hidden within QRS, due to tachycardia). Hyperkalemia. Idioventricular rhythm Right Atrial Enlargement(RAE) is typically associated with tall P waves P Pulmonale (COPD and Cor-Pulmonale are associated with tall p waves from RAE) Left Atrial enlargement(LAE) is typically associated with wide P waves P Mitrale (Mitral Stenosis is typically associated with a wide and notched p wave from LAE","pyqMatches":[{"year":"2013","no":1256,"q":"Absent P Wave is seen in:","o":["Atrial Fibrillation","Cor-pulmonale","Mitral Stenosis","COPD"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2476, 'Medicine', 'Cardiology', 'Hard', 'Internal_Medicine', 36, '{"id":2476,"subject":"Medicine","chapter":"Cardiology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":36,"q":"A patient in regular rhythm presents with absent P waves on ECG. Leads II, III and AVF reveal a Saw-Tooth Pattern. Which of the following is the most likely diagnosis:","o":["Atrial Fibrillation","Atrial Flutter with Variable Block","Atrial Flutter with Fixed Block","Multifocal Atrial Tachcardia"],"a":2,"e":"Answer is C (Atrial Flutter with Fixed Block) The absence of any discernible P waves on ECG, together with the presence of Saw Tooth Flutter waves in inferior leads (Leads II, III and AVF) strongly suggests a diagnosis of Atrial Flutter. The presence of a regular rhyti,,o suggests a Fixed Block . Findings/Features Diagnosis Irregular Rhythm with no discernible P wave (Chaotic base line with fibrillary f waves) Atrial Fibrillation Irregular rhythm with no discernible P wave (Saw tooth ,Ilutter waves especially in inferior leads and VI) Atrial Flutter with variable block Regular rhythm with no discernible P waves (Saw tooth flutter waves especially in inferior leads and V1) Atrial Flutter with fixed block Irregular Rhythm with multiple P wave morphologies (P waves Discernible) and Varying PR intervals Multifocal Atrial Tachycardia","pyqMatches":[{"year":"2014","no":1440,"q":"A patient in regular rhythm presents with absent P waves on ECG. Leads II, III and AVF reveal a Saw-Tooth Pattern. Which of the following is the most likely diagnosis:","o":["Atrial Fibrillation","Atrial Flutter with Variable Block","Atrial Flutter with Fixed Block","Multifocal Atrial Tachcardia"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2477, 'Medicine', 'Respiratory Medicine', 'Moderate', 'Internal_Medicine', 37, '{"id":2477,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":37,"q":"A wide and notched P wave is typically seen in:","o":["Mitral Stenosis","Cor-Pulmonale","COPD","Pulmonary embolism"],"a":0,"e":"Answer is A (Mitral Stenosis) Mitral Stenosis is typically associated with a Wide and Notched P wave from Left Atrial Enlargement (LAE) Cor-Pulmonale, COPD and Pulmonary embolism are all associated with Right Atrial Enlargement resulting in a Tall P wave (not a wide p wave)","pyqMatches":[{"year":"2014","no":1441,"q":"A wide and notched P wave is typically seen in:","o":["Mitral Stenosis","Cor-Pulmonale","COPD","Pulmonary embolism"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2478, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 38, '{"id":2478,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":38,"q":"A QRS duration between 100 and 120 milliseconds suggests all of the following, Except:","o":["Normal","Left anterior Fascicular Block","Left posterior Fascicular Block","Left Bundle Branch Block"],"a":3,"e":"Answer is D (Left Bundle Branch Block) Left Bundle Branch block is typically associated with a QRS duration greater than 120 milli seconds. Partial Blocks (Fascicular or hemiblocks) in the left bundle system (left anterior or posterior fascicular blocks) generally do not prolong the QRS duration substantially and QRS duration typically remains less than 120 milliseconds.","pyqMatches":[{"year":"2014","no":1444,"q":"A QRS duration between 100 and 120 milliseconds suggests all of the following, Except:","o":["Normal","Left anterior Fascicular Block","Left posterior Fascicular Block","Left Bundle Branch Block"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2479, 'Medicine', 'Cardiology', 'Hard', 'Internal_Medicine', 39, '{"id":2479,"subject":"Medicine","chapter":"Cardiology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":39,"q":"Low QRS voltage on ECG with left ventricular hypertrophy on Echocardiography suggests a diagnosis of:","o":["Pericardial effusion","Cardiac Amyloidosis","Corpulmonale","Infective endocarditis"],"a":1,"e":"Answer is B (Cardiac Amyloidosis) Low QRS voltage on ECG with left ventricular hypertrophy on Echocardiography suggests a diagnosis of infiltrative cardiomyopathy like amyloidosis. The combination of low QRS voltage plus a thick left ventricle on echocardiogram strongly suggests the diagnosis of infiltrative cardiomyopathy like cardiac amyloidosis. The increased thickness is the amyloid. It is not muscle (not true hypertrophy), does not depolarize and therefore adds nothing to QRS voltage","pyqMatches":[{"year":"2014","no":1452,"q":"Low QRS voltage on ECG with left ventricular hypertrophy on Echocardiography suggests a diagnosis of:","o":["Pericardial effusion","Cardiac Amyloidosis","Corpulmonale","Infective endocarditis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2480, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 40, '{"id":2480,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":40,"q":"Tall T waves on ECG are seen in:","o":["Hyperkalemia","Hypokalemia","Hypercalcemia","Hypocalcemia"],"a":0,"e":"Answer is A (Hyperkalemia) Hyperkalemia is typically associated with Tall peaked narrow based frnted T wave.","pyqMatches":[{"year":"2012","no":1009,"q":"Tall T waves on ECG are seen in:","o":["Hyperkalemia","Hypokalemia","Hypercalcemia","Hypocalcemia"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2481, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 41, '{"id":2481,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":41,"q":"ST elevation is seen in all of the following conditions except :","o":["Myocardial infarction","Coronary artery spasm","Constrictive pericarditis","Ventricular aneurysm"],"a":2,"e":"Answer is C (Constrictive pericarditis) ST segment is measured from the end of QRS complex to the beginning of the T wave, and represents the time interval between ventricular depolarization and repolarization.","pyqMatches":[{"year":"2014","no":1447,"q":"ST elevation is seen in all of the following conditions except :","o":["Myocardial infarction","Coronary artery spasm","Constrictive pericarditis","Ventricular aneurysm"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2482, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 42, '{"id":2482,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":42,"q":"The most common reentrant tachycardia associated with WPW syndrome is","o":["Orthodromic AV reentry","Antidromic AV reentry","Rapidly conducting AF","None"],"a":0,"e":"Answer is A (Orthodromic AV reentry) 123.The most common macro-reentrant tachycardia associated WPW syndrome is orthodromic AV reentry. The most common macro-reentrant tachycardia associated with WPW syndrome is referred to as Orthodromic AV reentry''","pyqMatches":[{"year":"2016","no":1047,"q":"The most common reentrant tachycardia associated with WPW syndrome is","o":["Orthodromic AV reentry","Antidromic AV reentry","Rapidly conducting AF","None"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2483, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 43, '{"id":2483,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":43,"q":"Athletic syndrome is characterized by:","o":["Increased amplitude of QRS","Tachycardia","Decreased QT interval","U-waves"],"a":0,"e":"The answer is A (Increased amplitude of QRS complex): Athletic Heart Syndrome Athletic Heart Syndrome is a benign condition consisting of physiologic adaptations to the increased cardiac workload of exercise in trained athletes. It represents a constellation of clinical findings that are the result of normal physiologic adaptation to strenuous physical activity. In response to the increased physical demand, the left ventricles dilate and wall thickness increases. The mass to volume ratio, however, does not change. Physical examination Decreased body fat and increased muscle mass (generally very physically fit) Pulse slow and often irregular (sinus bradycardia or bradycardia with first-and second-degree blocks) Grade I or II mid-systolic murmurs (benign functional ejection murmur resolves with Valsalva maneuver) Third and fourth heart sounds very common (benign filling sounds) Blood pressure typically remains normal Electrocardiogram rhythm Rhythm - Sinus bradycardia of 40 to 55 beats /min while at rest - Sinus pauses of more than 2.0 seconds due to increased vagal tone - Wandering atrial pacemaker found only in dynamic athletes - First degree atrioventricular block present only at rest; P-R interval normalizes with exercise - Second degree atrioventricular block present only at rest: Mobitz I (wenckebach block) common in marathon runners; Mobitz II rare in athlete''s heart. Voltage: TORS voltage (Amplitude) - Left ventricular hypertrophy found in 85% of Olympic marathon runners - Right ventricular hypertrophy common in dynamic athletes but rarely seen in sedentary controls and static athletes sedentary control and static athletes Repolarization - S-T segment elevation with peaked T waves normalizes with exertion - S-T segment depression may be rarely found in athletes T-wave inversion in lateral leads associated with interventricular septal hypertrophy in static athletes (can be a normal finding in dynamic athletes) Chest radiography - The heart is globular in appearance, particularly in endurance athletes. - Cardiomegaly (cardiothoracic ratio >0.50)","pyqMatches":[{"year":"2012","no":1008,"q":"Athletic syndrome is characterized by:","o":["Increased amplitude of QRS","Tachycardia","Decreased QT interval","U-waves"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2484, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 44, '{"id":2484,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":44,"q":"Predisposing factors for coronary artery disease include, all Except:","o":["Homocysteinemia","↑ Lipoprotein B","↑ Fibrinogen","↑ plasminogen activator inhibitors 1"],"a":1,"e":"Answer is B (↑. Lipoprotein B) Predisposing factors for coronary artery disease include an increased lipoprotein ''a'' and not lipoprotein ''6''.","pyqMatches":[{"year":"2015","no":1099,"q":"Predisposing factors for coronary artery disease include, all Except:","o":["Homocysteinemia","↑ Lipoprotein B","↑ Fibrinogen","↑ plasminogen activator inhibitors 1"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2485, 'Medicine', 'Cardiology', 'Hard', 'Internal_Medicine', 45, '{"id":2485,"subject":"Medicine","chapter":"Cardiology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":45,"q":"40 year old male patient presents to the Emergency department with central chest pain for 2 hours. The ECG shows ST segment depression and cardiac troponins are elevated. Patient has a positive history of previous PCI 3 months back. He is administered Aspirin, Clopidogrel, Nitrates and LMWH, in the Emergency Department and shifted to the coronary are unit. The best recommended course of further action should include.","o":["Immediate Revascularization with Thrombolytics","Early Revascularization with PCI","Continue conservative management and monitoring of cardiac enzymes and ECG","Continue conservation management and plan for delayed Revascularization procedure after patient is discharged"],"a":1,"e":"Answer is B (Early Revascularization with PCI) The patient presenting as a case of NSTE M I to the emergency department. The presence of elevated cardiac troponins and history of previous PCI place the patient into a high ''risk category''. The Patient in question is th 10 a ''high risk'' patient with NSTEMI Such patients are candidates for early invasive management with PCl/CABG.","pyqMatches":[{"year":"2013","no":1236,"q":"40 year old male patient presents to the Emergency department with central chest pain for 2 hours. The ECG shows ST segment depression and cardiac troponins are elevated. Patient has a positive history of previous PCI 3 months back. He is administered Aspirin, Clopidogrel, Nitrates and LMWH, in the Emergency Department and shifted to the coronary are unit. The best recommended course of further action should include.","o":["Immediate Revascularization with Thrombolytics","Early Revascularization with PCI","Continue conservative management and monitoring of cardiac enzymes and ECG","Continue conservation management and plan for delayed Revascularization procedure after patient is discharged"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2486, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 46, '{"id":2486,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":46,"q":"The most common toxin causing Dilated Cardiomyopathy is:","o":["Alcohol","Chemotherapeutic agents","Heavy metal","Occupational exposure"],"a":0,"e":"Answer is A (Alcohol) Chronic Alcohol Consumption is the most common cause of Toxic Dilated Cardiomyopathy. Alcohol is the most common toxin implicated in chronic dilated cardiomyopathy'' Note : Dilated cardiomyopathy is the most common type of cardiomyopathy The most common cause of dilated cardiomyopathy is Idiopathic (Two-Thirds) Alcohol Consumption is the most common cause of Toxic Dilated Cardiomyopathy","pyqMatches":[{"year":"2016","no":1056,"q":"The most common toxin causing Dilated Cardiomyopathy is:","o":["Alcohol","Chemotherapeutic agents","Heavy metal","Occupational exposure"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2487, 'Medicine', 'Cardiology', 'Hard', 'Internal_Medicine', 47, '{"id":2487,"subject":"Medicine","chapter":"Cardiology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":47,"q":"The 9 month old child of a diabetic mother presents with tachypnea and hepatomegaly. Echocardiography of the heart showed normal cardiac morphology with asymmetric septal hypertrophy. Which of the following you will give to treat this child :","o":["Digoxin","Frusemide","Propranolol","Isoptin"],"a":2,"e":"Answer is C (Propranolol) The symptoms of the patient and echocardiographic finding of asymmetrical septal hypertrophy almost confirms the diagnosis of Hypertrophic cardiomyopathy. Beta Blockers should be the initial drug Q in symptomatic individuals Management of HOCM Avoidance of strenuous physical activity Beta Blockers should be the initial drug Q in symptomatic individuals. They reduce: - Heart rate - Blood pressure - Stiffness of left ventricle - Fatal arrythmias Calcium channel BlockersQ (verapamil and diltiazem) are alternative drugs. - They reduce-stiffness of ventricle - Elevated diastolic pressures Amiadarone may be used to reduce arrythmias. Surgical myomectomy","pyqMatches":[{"year":"2012","no":1013,"q":"The 9 month old child of a diabetic mother presents with tachypnea and hepatomegaly. Echocardiography of the heart showed normal cardiac morphology with asymmetric septal hypertrophy. Which of the following you will give to treat this child :","o":["Digoxin","Frusemide","Propranolol","Isoptin"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2488, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 48, '{"id":2488,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":48,"q":"Kussmaul''s sign is classically described in:","o":["Restrictive Cardiomyopathy","Pericardial Tamponade","Constrictive pericarditis","Right Ventricular Infarct"],"a":2,"e":"Answer is C (Constrictive pericarditis) Kussmaul''s sign is classically described in association with Constrictive Pericarditis. Kussmaul''s sign refers to paradoxical elevation of JVP/CVP during inspiration (In healthy persons venous pressure falls during inspiration because pressures in the right heart decrease as intrathoracic pressures fall) The Kussmaul''s sign is classically described in association with Constrictive pericarditis. Kussmaul''s sign is however also seen in association with Right Ventricular Infarction, Restrictive Cardiomyopathy, Pulmonary Embolism and Advanced Systolic Severe Heart Failure","pyqMatches":[{"year":"2012","no":1011,"q":"Kussmaul''s sign is classically described in:","o":["Restrictive Cardiomyopathy","Pericardial Tamponade","Constrictive pericarditis","Right Ventricular Infarct"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2489, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 49, '{"id":2489,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":49,"q":"Hypertension with Hypokalemia is seen in:","o":["Bartter Syndrome","Liddle''s Syndrome","Gitelman''s Syndrome","All of the above"],"a":1,"e":"Answer is B (Liddle''s Syndrome) Liddle''s Syndrome is typically associated with Hypokalemia and Hypertension. Rartter''s Syndrome and Gitelman''s Syndrome are also associated with hypokalemia but without hypertension. Liddle''s Syndrome : Review Pathophysiology: • Autosomal dominant disorder. • Genetic defect in the collecting tubule sodium channel, resulting in in of inhibition by higher levels of intracellular sodium Age of Presentation • Often diagnosed at young age, but can present in adulthood due to p Clinical presentation • Classic triad of hypertension, metabolic alkalosis, and hypokalemia. • Consider iffamily history of hypertension and/or hypokalemia. at youn Lab data • Metabolic alkalosis, hrpokalemia (although some are low normal), lo Treatment: • Lifelong. Potassium-sparing diuretic which closes the sodium channe Spironolactone does not work because aldosterone is not causing the s","pyqMatches":[{"year":"2015","no":1146,"q":"Hypertension with Hypokalemia is seen in:","o":["Bartter Syndrome","Liddle''s Syndrome","Gitelman''s Syndrome","All of the above"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2490, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 50, '{"id":2490,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":50,"q":"Which of the following statements about atrial myxomas is true","o":["Most common in Left Atrium","More common in Males","Distant metastasis are seen","Most myxomas are familial"],"a":0,"e":"Answer is A (Most common in Left Atrium) Cardiac Myxomas are usually located in the atria, most common in the left. Cardiac myxomas Are the most common type of primary cardiac tumorsQ Occur at all ages and show no sex preference (mixes equally with both sexes)Q Most cardiac myxomas are sporadic, while some may be familial Sporadic myxomas : Are solitary Q Located in Atria, most commonly in the left Q Unlikely to have post-op recurrence e Occur in younger individuals Q Familial myxomas : Are multiple ° More likely to have post op recurrence e Myxomas are benign tumors and therefore distant metastasis are not seen.?","pyqMatches":[{"year":"2015","no":1101,"q":"Which of the following statements about atrial myxomas is true","o":["Most common in Left Atrium","More common in Males","Distant metastasis are seen","Most myxomas are familial"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2491, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 51, '{"id":2491,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":51,"q":"Which condition is most commonly associated with coarctation of aorta?","o":["PDA","Bicuspid aortic valve","Aortic stenosis","VSD"],"a":1,"e":"Answer is B (Bicuspid Aortic Valve) The most common associated cardiac anomaly with coarctation of aorta is bicuspid aortic valve (Harrison''s 17th /1462) Coarctation of aorta is associated with a bicuspid aortic valve in more than 70% of cases - (Nelson 18th / 1900) Associated anomalies with coarctation of Aorta Q Shone complex • Bicuspid Aortic valve('' (commonest) Coarctation of Aorta • PDAQ • VSDQ Left sided obstructive lesions • Tubular hypoplasia of aortic arch('' (Mitral valve abnormalities • Aortic stenosisQ (valvular / subvalvular) and subaortic stenosis) Other Associated lesions that have been asked previously Mitral valve abnormalities (Subvalvular mitral ring /parachute mitral valve) Turner''s syndrome(''","pyqMatches":[{"year":"2013","no":1441,"q":"Which condition is most commonly associated with coarctation of aorta?","o":["PDA","Bicuspid aortic valve","Aortic stenosis","VSD"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2492, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 52, '{"id":2492,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":52,"q":"Acute Infective Endocarditis with abscess formation is most commonly associated with","o":["Listeria","Staphylococcus","Streptococcus","Enterococcus"],"a":1,"e":"Answer is B (Staphylococcus) Acute Infective Endocarditis with abscess formation is most commonly associated with staphylococcus. `The most common organism causing acute infective endocarditis overall is staphylococcus aureus. Staphylococcus aureus endocarditis is particularly virulent and associated with annular and myocardial abscess formation and a higher mortality''","pyqMatches":[{"year":"2012","no":1202,"q":"Acute Infective Endocarditis with abscess formation is most commonly associated with","o":["Listeria","Staphylococcus","Streptococcus","Enterococcus"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2493, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 53, '{"id":2493,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":53,"q":"In Marfan''s syndrome, Aortic aneurysm occurs most commonly in:","o":["Ascending aorta","Descending aorta","Abdominal aorta","Arch of aorta"],"a":0,"e":"The answer is A (Ascending Aorta) Aortic aneurysms in Marfan''s syndrome occur most frequently in the ascending aorta. Cardiovascular lesions in Marfan''s syndrome Cardiovascular lesions are the most life-threatening features of Marfan''s syndrome. Mitral valve prolapse(MVP) Loss of connective tissue support in mitral valves leaflets makes them soft and blowy creating the so-called ''floppy valve''. Mitral regurgitation frequently results. Dilatation of Ascending Aortae The media undergoes cystic necrosis (cystic medionecrosis). Loss of medial support results in progressive dilatation of aortic valve ring and root of the aorta Severe aortic incompetence Aortic dissections","pyqMatches":[{"year":"2012","no":1151,"q":"In Marfan''s syndrome, Aortic aneurysm occurs most commonly in:","o":["Ascending aorta","Descending aorta","Abdominal aorta","Arch of aorta"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2494, 'Medicine', 'Hematology', 'Hard', 'Internal_Medicine', 54, '{"id":2494,"subject":"Medicine","chapter":"Hematology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":54,"q":"Which of the following is not expected in a case of Microcytic Hypochromic Anemia:","o":["Reduced serum Iron","Reduced Total RBC distribution Width","Normal Ferritin levels","Increased TIBC"],"a":1,"e":"Answer is B (Reduced Total RBC distribution width Microcytic Hypochromic Anemias are typically associated with a Normal or High Red Cell Distribution Width Condition Test (normal values) Iron deficiency Thalassemia Sideroblastic anemia Anemia of chron disease Smear Microcytic (MCV<80) Microcytic hypochromic Microcytic hypochromic Microcytic hypochromic Normocytic normochromic > Micro/hypochrom (but Micro/Hypo may be present) Serum iron (50- 150n/d1) Low (<30) Normal Normal .1. (<50) TIBC (300-360 µg/dl) High (>360) Normal Normal (Chandrasoma Taylor) ,i, (<300) % Saturation < 10 (J'') N or Ted N or \"I'' 4, Saturation (30-50%) (30-80) (30-80) (10-20) Ferritin (R/1) (50-200 µg/L) < 15 (fed) T (50-300) T (50-300) Normal or T (30-200) Hemoglobin pattern Normal Abnormal Normal Normal Free Erythrocyte Protporphrin Ted Normal Ted Ted RDW Ted Normal Normal Normal","pyqMatches":[{"year":"2014","no":1461,"q":"Which of the following is not expected in a case of Microcytic Hypochromic Anemia:","o":["Reduced serum Iron","Reduced Total RBC distribution Width","Normal Ferritin levels","Increased TIBC"],"a":1,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":1125,"q":"Which of the following is not expected in a case of Microcytic Hypochromic anemia","o":["Reduced serum Iron","Reduced total RBC distribution width","Normal Ferritin levels","Increased TIBC"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2495, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 55, '{"id":2495,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":55,"q":"Megaloblastic anemia should be treated with both folic acid vitamin B12 because :","o":["Folic acid alone causes improvement of hematologic symptoms but worsening of neurological symptoms","It is a Co factor","It is enzyme","None of the above"],"a":0,"e":"Answer is A (Folic acid alone causes improvement in hematologic in symptoms but worsening of neurological symptoms) Megaloblastic anemia may be caused by a deficiency of vitamin B12 (cobalamine) or deficiency of folate. Unless it is clearly established, which of the two deficienceis / folate or cobalamine) is the cause anemia treatment should include administration of both .folk acid and. vitamin Bp. If only folic acid is administered in a patient with mezaloblastic anemia due to vitamin BI2 deficiency, worseninz of neurological symptoms (cobalamine neuropathy) is seen despite an improvement in the hematological .symptoms (anemia) ''Although prompt hematologic response heralded by reticulocytosis follows the administration of folic acid, it should he cautioned that the hematologic symptoms of a vitamin B,2 deficiency anemia also respond to folate therapy. However Mate does not prevent and may even exacerbate the progression of neurological deficits typical of vitamin B12 deficiency states'' Before large doses of folic acid are given, cobalamine deficiency must be excluded and if present corrected, otherwise cobalamine neuropathy may develop despite a response of the anemia of cobalamine deficiency to Palate therapy.","pyqMatches":[{"year":"2014","no":1463,"q":"Megaloblastic anemia should be treated with both folic acid vitamin B12 because :","o":["Folic acid alone causes improvement of hematologic symptoms but worsening of neurological symptoms","It is a Co factor","It is enzyme","None of the above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2496, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 56, '{"id":2496,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":56,"q":"Indirect Coomb''s test detects:","o":["Antibodies attached to RBC Surface","Antibodies in the serum","Antigens attached to RBC Surface","Antigens in the serum"],"a":1,"e":"Answer is B (Antibodies in the serum) Indirect Coomb''s test detects IgG antibodies in the serum (e.g. Anti- D Antibodies). Direct Coomb''s test detects IgG Antibodies (or complements) attached to the surface of RBCs. Direct Antihuman Globulin Test Detects RBCs sensitized with IgG or Complements(C3B or C3d) (DAT; Coomb''s; Direct Coomb''s) Detects IgG Antibodies (or complements) attached to the surface of RBCs. Indirect Antihuman Globulin Test Direct Coomb''s Test In the Direct Coomb''s test, red blood cells (RBCs) sensitized with IgG antibodies (or C3b, C3d) are agglutinated when Coomb''s reagent (Rabbit Anti-IgG antibody) is added to the test tube Detects Antibodies in the Serum Indirect Coomb''s Test In the Indirect Coomb''s test IgG antibodies (e.g. Anti-D) in the serum must first bind to blood group Type 0 Test RBCs added to the test tube. Addition of Coombs Reagent, then causes the sensitized Type 0 Test RBCs to agglutinate, indicating that IgG antibodies are present in the serum.","pyqMatches":[{"year":"2015","no":796,"q":"Indirect Coomb''s test detects:","o":["Antibodies attached to RBC Surface","Antibodies in the serum","Antigens attached to RBC Surface","Antigens in the serum"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2497, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 57, '{"id":2497,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":57,"q":"Direct Coomb''s test detects:","o":["Antibodies attached to RBC Surface","Antibodies in the serum","Antigens attached to RBC Surface","Antigens in the serum"],"a":0,"e":"Answer is A (Antibodies attached to RBC Surface) Direct Coomb''s test detects IgG Antibodies (or complements) attached to the surface of RBCs. Indirect Coomb''s test detects IgG antibodies in the serum (e.g. Anti-D Antibodies).","pyqMatches":[{"year":"2014","no":1467,"q":"Direct Coomb''s test detects:","o":["Antibodies attached to RBC Surface","Antibodies in the serum","Antigens attached to RBC Surface","Antigens in the serum"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2498, 'Medicine', 'Hematology', 'Easy', 'Internal_Medicine', 58, '{"id":2498,"subject":"Medicine","chapter":"Hematology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":58,"q":"Haemoglobin F is raised in:","o":["Juvenile chronic myeloid leukemia","Hereditary spherocytosis","Congenital red cell aplasia","Mysthania gravis"],"a":0,"e":"Answer is A (Juvenile CML) Fetal Haemoglobin levels (HbF) are increased in most cases of Juvenile CML – Causes of Raised HbF levels (Interpretation of Diagnostic Test 8th/411, 412) Haemoglobinopathies - β thalassemia major - β thalassemia minor - Sickle cell disease Hereditary Persistance of HbF Anemia: - Non Hereditary refractory normoblastic anemia - Pernicious anemia - Aplastic anemia Leukemia specially Juvenile Myeloid Leukemia Multiple myeloma Molar pregnancy Patients with Trisomy 13 or Trisomy 21 (Down''s syndrome) Some chronic viral infections (eg CMV, EBV)","pyqMatches":[{"year":"2012","no":1057,"q":"Haemoglobin F is raised in:","o":["Juvenile chronic myeloid leukemia","Hereditary spherocytosis","Congenital red cell aplasia","Mysthania gravis"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2499, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 59, '{"id":2499,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":59,"q":"HAM test is based upon :","o":["GPI Anchor Proteins","Complement","Spectrin protein","Mannose binding proteins"],"a":1,"e":"Answer is B (Complements) HAM test is based upon susceptibility of RBC''s to complement mediated lysis in patients with PNH. HAM test is usedfbr the diagnosis of PNH (Paroxysmal Nocturnal Haemoglobinuria). HAM test (Acidified serum lysis test) demonstrates lysis of RBC after activation of complement by acid. In acidified serum complement is activated by the alternate pathway. In patients with PNH, RBC are unusually susceptible to complement, and undergo lysis when incubated with acidified fresh serum.","pyqMatches":[{"year":"2015","no":1128,"q":"HAM test is based upon :","o":["GPI Anchor Proteins","Complement","Spectrin protein","Mannose binding proteins"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2500, 'Medicine', 'Hematology', 'Moderate', 'Internal_Medicine', 60, '{"id":2500,"subject":"Medicine","chapter":"Hematology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":60,"q":"Which is the most common cytogenetic abnormality in adult myelodysplastic syndrome (MDS) -","o":["Trisomy 8","20q?","5q?","Monosmy 7"],"a":2,"e":"Answer is C (5q-) `Monosomy 7 is by far the most common cytogenetic abnormality in children (pediatric MDS) whereas 5q- is observed most frequent!,'' in adults'' – Myelodysplastic Syndromes by John Bennett (2002)/300 Cytogenetic Abnormalities in MDS: Facts to Remember Monosomy 7 is the most frequent cytogenetic abnormality in children.Q Deletion 5q (5q) is the most frequent cytogenetic abnormality in adults Q. Trisomy 8 is the most frequent tri.somyQ. Differences between Myelodysplastic Syndromes in children and Adults (`Myelodysplastic Syndromes'' 2002/300; ''Childhood Leukemias'' 2''\"/549) Feature Children Adults • Frequency Less common More common • Presence of sideroblasts Uncommon (<2%) More common (,- -25%) • Cytogenetic Abervations -7/7q-Most common (r 30%) Less common ( 40%) q (r,30%) (,=-40%) -5/5q-Uncommon (--L- 1-2%) Most common (z20%)","pyqMatches":[{"year":"2014","no":1482,"q":"Which is the most common cytogenetic abnormality in adult myelodysplastic syndrome (MDS)","o":["Trisomy 8","20q?","5q?","Monosmy 7"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2501, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 61, '{"id":2501,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":61,"q":"Gaisbock syndrome is known as","o":["Primary Familial Polycythemia","High Altitude Erythrocytosis","Spurious Polycythemia","Polycythemia Vera"],"a":2,"e":"Answer is C (Spurious Polycythemia) Gaisbock syndrome refers to Spurious Polycythemia or Relative Erythrocytosis due to decreased plasma volume.","pyqMatches":[{"year":"2015","no":1186,"q":"Gaisbock syndrome is known as","o":["Primary Familial Polycythemia","High Altitude Erythrocytosis","Spurious Polycythemia","Polycythemia Vera"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2502, 'Medicine', 'Hematology', 'Moderate', 'Internal_Medicine', 62, '{"id":2502,"subject":"Medicine","chapter":"Hematology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":62,"q":"All of the following statements about Burkitt''s lymphoma are true, Except:","o":["B cell lymphoma","8, 14 translocation","Can present as an abdominal mass","Radiotherapy is the treatment of choice"],"a":3,"e":"Answer is D (Radiotherapy is the treatment of choice) The treatment of choice for Burkitt''s Lymphoma is chemotherapy and not Radiotherapy. ''Burkitt''s lymphoma responds well to short term high dose chemotherapy. Treatment of Burkitt''s lymphoma in both children and adults should begin within 48 hours of diagnosis and involves the use of intensive combination chemotherapy regimens'' – Harrisons Burkitt''s Lymphoma is a B cell lymphoma Burkitt''s Lymphoma are tumors of mature B cells – Robbins 7th/677 t (8;14) translocation is the most common translocation in Burkitt''s Lymphoma Burkitt''s lymphomas are associated with translocation of the c-MYC gene on chromosome 8. Translocation t (8; 14) t (8; 22) t (2; 8) Burkitt''s Lymphoma may present with an abdominal mass Most Burkitt''s Lymphoma presents at extranodal sites but may present with lymphadenopathy Extranodal sites of involvement include the mandible and abdominal viscera `Burkitt''s Lymphomas may present with peripheral lymphadenopathy or an intraabdominal mass'' – Harrison CNS involvement is frequent The disease is rapidly progressive and has a propensity to metastasize to CNS, prophylactic therapy to CNS is therefore mandatory. Burkitt''s Lymphoma is the most rapidly progressive human tumor","pyqMatches":[{"year":"2016","no":439,"q":"All of the following statements about Burkitt''s lymphoma are true, Except:","o":["B cell lymphoma","8, 14 translocation","Can present as an abdominal mass","Radiotherapy is the treatment of choice"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2503, 'Medicine', 'Hematology', 'Easy', 'Internal_Medicine', 63, '{"id":2503,"subject":"Medicine","chapter":"Hematology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":63,"q":"''Hairy cell leukemia'' is a Neoplastic proliferation of :","o":["T. cells","B. cells","Myeloid cells","Macrophages"],"a":1,"e":"Answer is B (B Cells) Wain'' Cell is a rare hut distinctive B-cell neoplasm. Hairy cell leukemia review : Presentation is with a triad of :","pyqMatches":[{"year":"2015","no":459,"q":"''Hairy cell leukemia'' is a Neoplastic proliferation of :","o":["T. cells","B. cells","Myeloid cells","Macrophages"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2504, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 64, '{"id":2504,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":64,"q":"Chemotherapeutic Agent of Choice for the treatment of CML is:","o":["Imatinib","Vincristine","Cyclophosphamide","Methotrexate"],"a":0,"e":"Answer is A (Imatinib): Tyrosine Kinase Inhibitors (Imatinib) are the chemotherapeutic agents for choice in the management of CML. Tyrosine Kinase inhibitors target the ''constitutively active tyrosine kinase'' implicated in the pathogenesis of CML. Although they do not cure the disease, these agents are able to achieve long term control of CML in the majority of patients. Most recent texts (Including Harrisons) recommend Tyrosine Kinase Inhibitors (Imatinib) as the initial treatment of choice for newly diagnosed CML reserving Allogeneic Stem Cell Transplantation (SCT) for those who develop Imatinib Resistance.","pyqMatches":[{"year":"2012","no":1059,"q":"Chemotherapeutic Agent of Choice for the treatment of CML is:","o":["Imatinib","Vincristine","Cyclophosphamide","Methotrexate"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2505, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 65, '{"id":2505,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":65,"q":"The immunoglobulin most commonly involved in Multiple Myeloma is :","o":["IgG","IgM","IgA","IgD"],"a":0,"e":"Answer is A(IgG) The M component in Multiple Myeloma can be made up of the immunoglobulins IgG, IgM, IgD, IgA, and IgE; light chains alone; or heavy chains alone. IgG Myeloma is the most common form of Multiple Myeloma while IgD (2%) and IgE (Rare) are the least common. Distribution of immunoglobulin types in patients with multiple myeloma Type of protein Percentage (%) IgG 52 IgA 22 IgM 12 IgD 2 IgE Rare","pyqMatches":[{"year":"2012","no":1062,"q":"The immunoglobulin most commonly involved in Multiple Myeloma is :","o":["IgG","IgM","IgA","IgD"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2506, 'Medicine', 'Miscellaneous', 'Hard', 'Internal_Medicine', 66, '{"id":2506,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Internal_Medicine","sourceNo":66,"q":"The most common translocation seen in patients with Multiple Myeloma is","o":["t(11;14)","t(4;14)","t(14;16)","t(14;20)"],"a":0,"e":"Answer is A (t(11;14)) The most common translocation seen in patients with Multiple Myeloma is 01;14). `The most common translocation seen in patients with Multiple Myeloma is t(11;14)(q13;q32) involving the BCL1 locus on chromosome 11g13 and the immunoglobulin heavy (IgH) chain locus on chromosome 14q13 which leads to overexpression of Cyclin D1 ''- The Washington Manual of Surgical Pathology `The two most common translocation seen in patients with Multiple Myeloma are t(11;14)and t(4; 14). Both these translocations occur with almost similar frequencies, however the incidence of translocation 1(11; 14) appears to be marginally higher. Patients with t(4; 14) fall within a poor prognosis subgroup, while those with 1(11; 14) have a standard risk'' - The Principles of Clinical Cytogenetics The two most common translocation seen in patients with Multiple Myeloma t(11;14)(q13;q32) : Associated with standard prognosis t(4;14) (p16;q32) : Associated with aggressive behaviour and poor prognosis The most common translocation in multiple myeloma associated with a poor prognosis is translocation t(4;14)","pyqMatches":[{"year":"2013","no":1237,"q":"The most common translocation seen in patients with Multiple Myeloma is","o":["t(11;14)","t(4;14)","t(14;16)","t(14;20)"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2507, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 67, '{"id":2507,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":67,"q":"All the following are true about multiple myeloma except:","o":["Osteolytic bone disease","t(8-14) translocation","Light chain proliferation","Bence-Jones proteins in urine"],"a":1,"e":"Answer is B (t (8-14) translocation) A variety of chromosomal alterations have been found in patients with Multiple myeloma. The most common translocation is t (11; 14) (q 13; q32). 13q14 deletions and 17p13 deletions and 11 q abnormalities predominate. Translocation 1(8-14) has not been mentioned. Complete Immunoglobulin chain comprises of both heavy chains and light chains. But in Multiple myeloma there is excess production of light chains e over heavy chains. These light chains are eliminated in urine as Bence Jones proteinQ Protein cast in urine are thus made up of light chains only Q (not complete immunoglobulin chains). Bone lesions in multiple myeloma are lytic in nature and are rarely associated with osteoblastic new bone formation.'' - Harrison. Bone lesions in MM are caused by the proliferation of tumor cells and activation of osteoclasts that destroy the bone. ''Bone pain is the most common symptom in MM affecting 70% of patients Q''-Harrison","pyqMatches":[{"year":"2012","no":1061,"q":"All the following are true about multiple myeloma except:","o":["Osteolytic bone disease","t(8-14) translocation","Light chain proliferation","Bence-Jones proteins in urine"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2508, 'Medicine', 'Hematology', 'Easy', 'Internal_Medicine', 68, '{"id":2508,"subject":"Medicine","chapter":"Hematology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":68,"q":"Converging point of both pathway in coagulation is at:","o":["Factor VIII","Stuart factor X","Factor IX","Factor VII"],"a":1,"e":"Answer is B (Stuart factor X) The extrinsic and Intrinsic pathways in coagulation converge at the Stuart factor X. Clotting factor deficiency InheritancePrevalence in General Population Laboratory Abnormality'' aPTI PT TT Minimum Hemostatic le N els Treatment Fibrinogen AR I in 1.000,000 + + + 100 mg/dL Cryoprecipi ProthrombinAR I in 2.000,000 + + 20-30% FFP/Pa''s Factor V AR 1 in 1.000,000 +/- +1- I 5-10\"/a HP Factor I II AR 1 in 500,000 - + - 15-20% FFP/PCCs Factor VIII X-linked I in 5.000 + - 30% FAINT concentrate Factor IX X-linked I in 30.000 + 30% FIX concen","pyqMatches":[{"year":"2015","no":274,"q":"Converging point of both pathway in coagulation is at:","o":["Factor VIII","Stuart factor X","Factor IX","Factor VII"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2509, 'Medicine', 'Hematology', 'Moderate', 'Internal_Medicine', 69, '{"id":2509,"subject":"Medicine","chapter":"Hematology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":69,"q":"Which of the following statements about coagulation factor VII is not true","o":["Deficiency is inherited as an Autosomal Recessive trait","Deficiency is associated with prolonged APTT","Deficiency can be managed by Fresh Frozen plasma","Has a shorter half life in comparison to Hageman factor (XII)"],"a":1,"e":"Answer is B (Deficiency is associated with prolonged APTT) Factor VII deficiency is associated with isolated prolongation of PT, APTT is normal in Factor VII deficiency Genetic and laboratory characteristic of inherited coagulation disorders + - - Factor X AR I in 1.000,000 +1- +/- - 15-20% FFP/PCICs Factor XI AR I in 1,000,000 15-20% FFP Factor XII AR ''SO + - h h HK AR ND + Ii h Prckallikrein AR ND _, 6 h Factor XIII AR I in 2,000,000 +/- 2-5% Cryptopreci Values within n srmal range (-) or prolonged (±) No risk for bleeding, treatment is not indicated HK, high-molecular weight kininogen; AR, autosomal recessive; aPTT, activated partial thromboplastin time; PT, prothrombin time; TT, thrombin time; ND, not determined; FFP. fresh frozen plasma; PCCs, prothrombin complex concentrates.","pyqMatches":[{"year":"2014","no":475,"q":"Which of the following statements about coagulation factor VII is not true","o":["Deficiency is inherited as an Autosomal Recessive trait","Deficiency is associated with prolonged APTT","Deficiency can be managed by Fresh Frozen plasma","Has a shorter half life in comparison to Hageman factor (XII)"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2510, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 70, '{"id":2510,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":70,"q":"Thrombotic thrombocytopenic purpura is a syndrome characterized by:","o":["Thrombocytosis, anemia, neurologic abnormalities, progressive renal failure and fever.","Thrombocytopenia, anemia, neurologic abnormalities, progressive hepatic failure and fever","Thrombocytosis, anemia neurologic abnormalities, progressive renal failure and fever","Thrombocytopenia, anemia, neurological abnormalities, progressive renal failure and fever"],"a":3,"e":"Answer is D (Thrombocytopenia, anemia, neurological abnormalities, progressive renal failure and fever) Thrombotic Thrombocytopenic Purpura (TTP) is characterized clinically by the Pentad of Microangiopathic Hemolytic Anemia, Thrombocytopenia. Decreased Renal Function. Disturbed Neurological function and Fever.","pyqMatches":[{"year":"2012","no":1060,"q":"Thrombotic thrombocytopenic purpura is a syndrome characterized by:","o":["Thrombocytosis, anemia, neurologic abnormalities, progressive renal failure and fever.","Thrombocytopenia, anemia, neurologic abnormalities, progressive hepatic failure and fever","Thrombocytosis, anemia neurologic abnormalities, progressive renal failure and fever","Thrombocytopenia, anemia, neurological abnormalities, progressive renal failure and fever"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2511, 'Medicine', 'Hematology', 'Easy', 'Internal_Medicine', 71, '{"id":2511,"subject":"Medicine","chapter":"Hematology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":71,"q":"Hypercoagulability due to defective factor V gene is called :","o":["Lisbon mutation","Leiden mutation","Antiphospholipid syndrome","Inducible thrombocytopenia syndrome"],"a":1,"e":"Answer is B (Leiden mutation) Hyper coagulability due to defective Factor V gene is called ''Leiden mutation'' and is named after the city in which it was described. Factor V Leiden Factor V Leiden is a variant (mutated) of normal clotting factor V and differs from normal clotting factor V by a single nucleotide. While Factor V Leiden is completely normal in terms of its ability to prevent bleeding, the one amino acid difference makes Factor V Leiden resistant to being degraded by activated protein C and protein S. Consequently factor V Leiden persists in the circulation longer and contributes to formation of blood clots. Factor V Leiden mutation is the most common underlying genetic cause of thrombophilia (venous thrombosis) Factor V Leiden mutation poses a life long risk of deep venous thrombosis.","pyqMatches":[{"year":"2016","no":428,"q":"Hypercoagulability due to defective factor V gene is called :","o":["Lisbon mutation","Leiden mutation","Antiphospholipid syndrome","Inducible thrombocytopenia syndrome"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2512, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 72, '{"id":2512,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":72,"q":"The preferred test for confirming H. pylori eradication is:","o":["Urease breath test","Culture","Serological test","Biopsy urease test"],"a":0,"e":"Answer is A (Urease Breath Test) The test of choice for documenting eradication is urease breath test. Assessment of success of Treatment with Eradication of H. Pylori should be done at least 4 weeks after completion of anti H. Pylori therapy. Non-invasive tests are typically preferred for assessment of Eradication. The test of choice for documenting eradication is urease breath test. Urease breath test detects H. pylori infection by ''bacterial urease activity'' and remains positive till the bacteria has not been eradicated with treatment. Thus urease breath test becomes negative only aftereradication of organism following treatment and not with chronic infection.","pyqMatches":[{"year":"2012","no":1031,"q":"The preferred test for confirming H. pylori eradication is:","o":["Urease breath test","Culture","Serological test","Biopsy urease test"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2513, 'Medicine', 'Infectious Diseases', 'Moderate', 'Internal_Medicine', 73, '{"id":2513,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":73,"q":"All of the following are used for treatment of H.Pylori, except:","o":["Gentamycin","Clarithromycin","Metronidazole","Amoxicillin"],"a":0,"e":"Answer is A (Gentamycin): Gentamycin is not used in any of the successful multi-drug regimens against H. Pylori Infection.","pyqMatches":[{"year":"2012","no":1032,"q":"All of the following are used for treatment of H.Pylori, except:","o":["Gentamycin","Clarithromycin","Metronidazole","Amoxicillin"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2514, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 74, '{"id":2514,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":74,"q":"Commonest site of peptic ulcer is :","o":["1st part of Duodenum","IInd part of duodenum","Distal 1/3 of stomach","Pylorus of the stomach"],"a":0,"e":"Answer is A (1st part of Duodenum) First part of duodenum is the most common site for peptic ulceration. Sites in order of decreasing frequency :","pyqMatches":[{"year":"2015","no":1303,"q":"Commonest site of peptic ulcer is :","o":["1st part of Duodenum","IInd part of duodenum","Distal 1/3 of stomach","Pylorus of the stomach"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2515, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 75, '{"id":2515,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":75,"q":"Dumping syndrome is due to:","o":["Diarrhoea","Presence of hypertonic content in small intestine","Vagotomy","Reduced gastric capacity"],"a":1,"e":"Answer is B (Presence of Hypertonic Contents in small intestine) DUMPING SYNDROME refers to a syndrome of abdominal and vasomator symptoms which results from dumping of food stuffs with a high osmotic load, front the stomach, into the small bowel. Loss of storage capacity of stomach and ablation, by pass or destruction of pylorus, results in rapid emptying of hyperostnolar chyme into duodenummm and small intestine. Extracellular fluid then shifts into the intestinal lumen to restore isotonicity resulting in decreased intravascular volume, which gives rise to the vasomotor symptoms. Note that while reduced gastric capacity contributes, option (b) is a more accurate answer. Dumping Syndrome is actually of two types: Early dumping syndrome (as described above) Late dumping syndrome: This is Reactive hypoglvcemiae. The carbohydrate load in thesmall intestine later causes a rise in plasma glucose, which in turn causes insulin levels to rise causing a secondary hypoglycemia.","pyqMatches":[{"year":"2014","no":1536,"q":"Dumping syndrome is due to:","o":["Diarrhoea","Presence of hypertonic content in small intestine","Vagotomy","Reduced gastric capacity"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2516, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 76, '{"id":2516,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":76,"q":"Schilling test is Abnormal in:","o":["Intrinsic factor deficiency","Amylase deficiency","Lipase deficiency","Pancreatic endocrine insufficiency"],"a":0,"e":"Answer is A (Intrinsic factor deficiency) Shilling''s test is typically done to determine the cause of cobalamine malabsorption (Vitamin B12 malabsorption) Vitamin B12 absorption (Schilling) test is typically used to diagnose conditions in which intrinsic factor (IF) may be absent, such as pernicious anemia or gastric atrophy. A diagnosis of Intrinsic factor deficiency can be established if radiolabelled cobalamine (Vitamin B12) appears in urine after administration of Intrinsic factor. Since cobalamine absorption requires multiple steps including gastric, pancreatic and ileal processes, the Schilling test can also be used to assess the integrity of these other organs. Dietary vitamin B 12 is bound in the stomach to an endogenous protein called R protein. Pancreatic enzymes degrade the R protein in the proximal small bowel and lower its affinity for vitamin B12 resulting in the rapid transfer of B 12 to IF; The IF-B12 Complex continues to the terminal ileum, where it binds to specific receptors on the surface of the epithelial cells. Thus lack of intrinsic factor, lack of sufficient pancreatic enzymes (pancreatic exocrine dysfunction) or presence of terminal heal mucosal disease may all result in abnormal vitamin B12 excretion.","pyqMatches":[{"year":"2012","no":1039,"q":"Schilling test is Abnormal in:","o":["Intrinsic factor deficiency","Amylase deficiency","Lipase deficiency","Pancreatic endocrine insufficiency"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2517, 'Medicine', 'Gastroenterology', 'Moderate', 'Internal_Medicine', 77, '{"id":2517,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":77,"q":"Which of the following statements regarding the schilling test for vitamin B12 malabsorption is most accurate?","o":["The schilling test results are abnormal in patients with dietary vitamin B12 deficiency.","In patients with pernicious anemia, the results of the schilling test normalize after oral administration of intrinsic factor,","In patients with ileal disease, the results of the schilling test normalize after oral administration of intrinsic factor","Pancreatic exocrine insufficiency does not cause schilling test results to be abnormal."],"a":1,"e":"Answer is B (In patients with pernicious anemia, the results of the Schilling test normalize after oral administration of intrinsic factor): An abnormal Schilling''s test that corrects or normalizes after administration of intrinsic factor suggests a diagnosis of Pernicious Anemia (Intrinsic Factor Deficiency). Shilling''s test is done to determine the cause of cyanocobalamine deficiency (Vitamin B12).Schilling test is abnormal in conditions that affect cobalamine absorption including Pernicious anemia, Chronic Pancreatitis, Bacterial overgrowth syndrome and Ileal dysfunction. An Abnormal Schilling''s test that corrects after administration of Intrinsic Factor indicates Pernicious Anemia An Abnormal Schilling''s test that corrects after administration of Pancreatic Enzymes suggests Exocrine Pancreatic Insufficiency (from Chronic Pancreatitis) An Abnormal Schilling''s test that corrects after administration of five days of antibiotics suggests Bacterial Overgrowth Syndrome An Abnormal Schilling''s test that does not correct after administration of intrinsic factor, pancreatic enzymes and/or antibiotics suggests Ileal mucosal dysfunction","pyqMatches":[{"year":"2014","no":1464,"q":"Which of the following statements regarding the schilling test for vitamin B12 malabsorption is most accurate?","o":["The schilling test results are abnormal in patients with dietary vitamin B12 deficiency.","In patients with pernicious anemia, the results of the schilling test normalize after oral administration of intrinsic factor,","In patients with ileal disease, the results of the schilling test normalize after oral administration of intrinsic factor","Pancreatic exocrine insufficiency does not cause schilling test results to be abnormal."],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2518, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 78, '{"id":2518,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":78,"q":"All of the following drugs may be used in the treatment of ulcerative colitis Except:","o":["Corticosteroids","Azathioprine","Sulfasalazine","Methotrexate"],"a":3,"e":"Answer is D (Methotrexate) Methotrexate has not been shown to be effective fbr treating active ulcerative colitis or for maintaining remission.","pyqMatches":[{"year":"2014","no":1355,"q":"All of the following drugs may be used in the treatment of ulcerative colitis Except","o":["Corticosteroids","Azathioprine","Sulfasalazine","Methotrexate"],"a":3,"source":"NEET_2014_Paper.pdf"},{"year":"2016","no":1099,"q":"All of the following drugs may be used in the treatment of ulcerative colitis Except:","o":["Corticosteroids","Azathioprine","Sulfasalazine","Methotrexate"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2014","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2519, 'Medicine', 'Rheumatology', 'Moderate', 'Internal_Medicine', 79, '{"id":2519,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":79,"q":"Extraintestinal manifestations of Inflammatory bowel disease include all of the following, Except:","o":["Uveitis","Sclerosing cholangitis","Osteoarthritis","Skin nodules"],"a":2,"e":"Answer is C (Osteoarthritis): Osteoarthritis is not an extraintestinal manifestation of inflammatory bowel disease Uveitis, Sclerosing Cholangitis, and skin nodules (Erythema nodosum) are all recognized extraintestinal manifestations of inflammatory bowel disease.","pyqMatches":[{"year":"2013","no":1295,"q":"Extraintestinal manifestations of Inflammatory bowel disease include all of the following, Except:","o":["Uveitis","Sclerosing cholangitis","Osteoarthritis","Skin nodules"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2520, 'Medicine', 'Gastroenterology', 'Moderate', 'Internal_Medicine', 80, '{"id":2520,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":80,"q":"Secretory diarrhea is not seen in:","o":["Phenolphthalein","Celiac disease","Cholera","Addison''s Disease"],"a":1,"e":"Answer is B (Celiac Disease) Celiac Disease is associated with Steatorrheal diarrhoea from mucosa! malabsorption. Secretory Diarrhea Certain Bacterial Infection Vibrio Cholera Enterotoxigenic E.Coli Non Osmotic Stimulant Laxatives Hormone Producing Endocrine Tumors Carcinoid, VlPomas, Gastrinomas, Medullary Carcinoma Thyroid (Calcitonin) Bile acids (endogenous laxatives) Bowel resection / disease or fistula Addison''s Disease Congenital Electrolyte Absorption defects Chronic Alcohol Ingestion Diabetic Diarrhea Steatorrheal Diarrhea Intraluminal maldigestion Pancreatic exocrine insufficiency, Bacterial overgrowth, Bariatric surgery, Liver disease Mucosal malabsorption Celiac sprue, Whipple''s disease, Infections, Abetalipoproteinemia, Ischemia Postmucosal obstruction (1° or 2° lymphatic obstruction)","pyqMatches":[{"year":"2012","no":1040,"q":"Secretory diarrhea is not seen in:","o":["Phenolphthalein","Celiac disease","Cholera","Addison''s Disease"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2521, 'Medicine', 'Gastroenterology', 'Moderate', 'Internal_Medicine', 81, '{"id":2521,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":81,"q":"Which of the following is not a prognostic factor for Acute Pancreatitis","o":["Serum Amylase","Serum Calcium","Serum Glucose","Serum AST"],"a":0,"e":"Answer is A (Serum Amylase) : Serum Amylase does not form any criteria for prognosis in Acute Pancreatitis. Although elevated serum amylase level is important for establishing diagnosis of acute pancreatitis, it plays no role in predicting prognosis or severity. \"There appears to be no definite correlation between severity of pancreatitis and the degree of serum amylase elevation. After 48 to 72 hours, even with continuing evidence of pancreatitis, total serum amylase levels tend to return to normal.\" - Harrison Hyperglycemia (Glucose), Hypocalcemia (Calcium) and elevated serum AST are all poor prognostic factors in accordance with Ranson''s criteria as elaborated in the previous question.","pyqMatches":[{"year":"2016","no":1247,"q":"Which of the following is not a prognostic factor for Acute Pancreatitis","o":["Serum Amylase","Serum Calcium","Serum Glucose","Serum AST"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2522, 'Medicine', 'Miscellaneous', 'Hard', 'Internal_Medicine', 82, '{"id":2522,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Internal_Medicine","sourceNo":82,"q":"Best provocative test for diagnosis of Gastrinoma is:","o":["Ca++ infusion test","Secretin injection test","ACTH stimulation test","Steroid assay"],"a":1,"e":"Answer is B (Secretin injection test) Gastrinomas (Zollinger Ellison Syndrome) are characterized by peptic ulceration due to hypersecretion of gastrin by a non-beta cell tumor. Secretin injection test is the most valuable provocative test in identifying patients with ZES.","pyqMatches":[{"year":"2012","no":1033,"q":"Best provocative test for diagnosis of Gastrinoma is:","o":["Ca++ infusion test","Secretin injection test","ACTH stimulation test","Steroid assay"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2523, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 83, '{"id":2523,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":83,"q":"The most classical symptom of VIPOMA is:","o":["Gall stones","Secretory diarrhea","Steatorrhea","Flushing"],"a":1,"e":"Answer is B (Secretory Diarrhoea) The principle feature of VIPOMA is large volume secretory Diarrhoea. Diarrhoea is secretory in nature, persists during fasting and is almost always greater than > I Litre per day (>3 Litres per day in 70 percent). A stool volume less than 700 ml per day is proposed to exclude the diagnosis. Most patients do not have accompanying Steatorrhea. VIPOMAS (Verner-Morrison Syndrome/ Pancreatic Cholera/WDHA Syndrome) VIPomas are tumours that secrete large amounts of Vasoactive Intestinal Peptide (VIP) VIP is an important neurotransmitter ubiquitously present in the CNS and GIT The most common location of VlPomas is the Pancreas Most common site within the pancreas is the pancreatic tail Usually Solitary Usually Malignant (37-68 % have hepatic metastasis at diagnosis VIP Stimulates Small Intestinal chloride secretion Stimulates smooth muscle contractility Inhibits acid secretion Has vasodilatory effects Typical Features (WDHA) Watery Diarrhoea (Large Volume Secretory Diarrhoea leading to dehydration) Hypokalemia (Diarrhoea severe enough to cause hypokalemia) Achlorhydria (Hypochlorhydria from increased small intestinal chloride secretion) The principle Symptoms are large volume diarrhoea (100 %) severe enough to cause hypokalemia (80- 100%), dehydration (83%), hypochlorhydria (54-76%) and flushing (20%) Most patients do not have accompanying Steatorrhea Other Features Increased stool Volume due to increased secretion of sodium and potassium which with the anion account for osmolality of the stool Hyperglycemia (25-50% Hypercalcemia (25-50%) The diagnosis requires demonstration of an elevated plasma VIP level and the presence of large volume secretory diarrhea.","pyqMatches":[{"year":"2012","no":1069,"q":"The most classical symptom of VIPOMA is:","o":["Gall stones","Secretory diarrhea","Steatorrhea","Flushing"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2524, 'Medicine', 'Gastroenterology', 'Moderate', 'Internal_Medicine', 84, '{"id":2524,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":84,"q":"All following are at-risk group adults meriting Hepatitis B vaccination in low endemic areas except:","o":["Patients on chronic hemodialysis","Diabetics on insulin","Medical/nursing personnel","Patients with chronic liver disease"],"a":1,"e":"Answer is B (Diabetics on Insulin): Behavioral: Sexually active persons who are not in a long-term, mutually monogamous relationship (e.g., persons with more than one sex partner during the previous 5 months): persons seeking evaluation or treatment for a sexually transmitted disease (STD): current or recent injection-drug users; and men who have sex with men. Occupational: Healthcare personnel and public-safety workers who are exposed to blood or other potentially infectious body fluids. Medical: Persons with end-stage renal disease, including patients receiving hemodialysis; person with HIV infection; and persons with chronic liver disease. Other: Household contacts and sex partners of persons with chronic HBV infection; clients and staff members of institutions for persons with developmental disabilities; and international travellers to countries with high or intermediate prevalence of chronic HBV infection. Hepatitis B vaccination is recommended for all adults in the following settings: STD treatment facilities; HIV testing and treatment facilities; facilities providing drug-abuse treatment and prevention services; healthcare settings targeting services to injection—drug users or men who have sex with men; correctional facilities; end-stage renal disease programs and facilities for chronic hemodialysis patients; and institutions and nonresidential day-care facilities for persons with developmental disabilities. Administer missing doses to complete a 3-dose series of hepatitis B vaccine to those persons not vaccinated or not completely vaccinated. These second dose should be administered 1 month after the first dose; the third dose should be given at least 2 months after the second dose (and at least 4 months after the first dose). If the combined hepatitis A and hepatitis B vaccine (Twinrix) is used, administer 3 doses at 0, 1, and 6 months; alternatively, a 4-dose Twinrix schedule, administered on days 0, 7, and 21 to 30, followed by a booster dose at month 12 may be used. Adult patients receiving hemodialysis or with other immunocompromising conditions should receive 1 dose of 40 pg/mL (Recombivax HB) administered on a 3-dose schedule or 2 doses of 20 Ug/mL (Engerix-B) administered simultaneously on a 4-dose schedule at 0, 1, 2, and 6 months.","pyqMatches":[{"year":"2012","no":1038,"q":"All following are at-risk group adults meriting Hepatitis B vaccination in low endemic areas except:","o":["Patients on chronic hemodialysis","Diabetics on insulin","Medical/nursing personnel","Patients with chronic liver disease"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2525, 'Medicine', 'Endocrinology', 'Moderate', 'Internal_Medicine', 85, '{"id":2525,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":85,"q":"Extrahepatic Manifestations of Hepatitis C include all of the following Except:","o":["Lichen Planus","Celiac Disease","Glomerulonephritis","Cryoglobulinemia"],"a":1,"e":"Answer is B (Celiac disease) Extrahepatic manifestations in viral hepatitis C: Wepatology'' by Kuntz Agranulocytosis Aplastic anaemia Corneal ulceration Ciyoglobillinaemia Diabetes mellitus (type I) Erythema exsudativum multiforme Glomerulonephritis Guillain-Barre syndrome Hyperlipasaemia Lichen planus Non-Hodgkin lymphoma Polyarteritis nodosa Polyarthritis Polyneuritis Porphyria cutanea tarda Sialadenitis Sjogren''s syndrome /Sicca syndrome Thrombocytopenia Thyroiditis","pyqMatches":[{"year":"2016","no":1160,"q":"Extrahepatic Manifestations of Hepatitis C include all of the following Except:","o":["Lichen Planus","Celiac Disease","Glomerulonephritis","Cryoglobulinemia"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2526, 'Medicine', 'Gastroenterology', 'Moderate', 'Internal_Medicine', 86, '{"id":2526,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":86,"q":"Which is not true about alcoholic hepatitis :","o":["Gamma glutamyl transferase is raised","SGPT is raised > SGOT","SGOT is raised > SGPT","Alkaline phosphatase is raised"],"a":1,"e":"Answer is B SGOT/SGPT ratio greater than 2 is highly suggestive of alcoholic hepatitis and cirrhosis. AST is synonymous with SGOT & ALT is synonymous with SGPT In general AST and ALT levels rise parallel to each other. In alcoholic liver disease the AST rises out of proportion to ALT such that the ratio of AST and ALT may become greater than 2: Stigmata of Alcoholic hepatitis / cirrhosis that aid in diagnosis :","pyqMatches":[{"year":"2015","no":1119,"q":"Which is not true about alcoholic hepatitis :","o":["Gamma glutamyl transferase is raised","SGPT is raised > SGOT","SGOT is raised > SGPT","Alkaline phosphatase is raised"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2527, 'Medicine', 'Hematology', 'Moderate', 'Internal_Medicine', 87, '{"id":2527,"subject":"Medicine","chapter":"Hematology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":87,"q":"Hepatic Encephalopathy is predisposed by all, Except:","o":["Hyperkalemia","Dehydration","Constipation","GI Bleeding"],"a":0,"e":"Answer is A (Hyperkalemia): Hepatic Encephalopathy is predisposed by Hypokalemia and not by Hyperkalemia","pyqMatches":[{"year":"2015","no":1118,"q":"Hepatic Encephalopathy is predisposed by all, Except:","o":["Hyperkalemia","Dehydration","Constipation","GI Bleeding"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2528, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 88, '{"id":2528,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":88,"q":"Features of Hepatorenal syndrome are","o":["Urine sodium < 10 meq/1","Normal renal histology","Renal function abnormal even after liver become normal","a and b"],"a":3,"e":"Answer is A & B (urine Na < 10 meq/l and Normal Renal Histology) Hepatorenal syndrome is associated with normal renal histology and supported by a urine sodium excretion l0meq/L Hepatorenal syndrome Hepatorenal syndrome is defined as a state of functional renal failure (Reduced GFR) in patients with severe liver disease Structurally /Histologically the kidneys are normal and recover function after successful liver transplantation. The pathogenetic hallmark of hepatorenal syndrome is intense renal vasoconstriction with coexistent systemic vasodilatation The diagnosis of hepatorenal syndrome is considered in accordance with the following diagnostic criteria. Diagnostic of Hepatorenal Syndrome Major criteria Low glomerular filtration rate. as indicated by serum creatinine > 1.5 mg/dL or 24-hr creatinine clearance < 40 mL/min Absence of shock, ongoing bacterial infection, fluid losses, and current treatment with nephrotoxic drugs No sustained improvement in renal function (decrease in serum creatinine to 1.5 nig/dL or increase in creatinine clearance to 40 mL/min) after diuretic withdrawal and expansion of plasma volume with 1.5L of a plasma expander Proteinuria mg/d1, and no uhrasonographic evidence of obstructive uropathy or parenchymal renal disease Additional criteria Urine volume < 500 mL/d Urine sodium < 10 meq/L Urine osmolality greater than plasma osmolality Urine red blood cells <50/high- power. field Serum sodium concentration < 130 niEqL Note: All major criteria must be present for the diagnosis of hepatorenal syndrome. Additional criteria are not necessary for the diagnosis but provide supportive evidence.","pyqMatches":[{"year":"2015","no":1110,"q":"Features of Hepatorenal syndrome are","o":["Urine sodium < 10 meq/1","Normal renal histology","Renal function abnormal even after liver become normal","a and b"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2529, 'Medicine', 'Gastroenterology', 'Moderate', 'Internal_Medicine', 89, '{"id":2529,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":89,"q":"All of the following statements about. Wilson''s disease are true, EXCEPT-","o":["It is an autosomal recessive disorder","Serum ceruloplasmin level is < 20 mg/dl","Urinary copper excretion is","Zinc acetate is effective as maintenance therapy"],"a":2,"e":"Answer is C (Urinary copper excretion is <100R/day) Urine copper is an important diagnostic too. Symptomatic patients invariably have urine copper levels > 100 p (>1.6 umol) per 24 hours. Wilson''s disease is an autosomal recessive disorder It is caused by a mutation of a gene on chromosome BQ which promotes Cu excretion (ATP 7B gene) Symptomatic patients with Wilson''s disease invariably have urinary copper excretion of >100 lig, per 24 hours (>1.6 innol /24 hr) Zinc is the treatment of choice for maintainance therapy in Wilson''s disease Zinc is the treatment of choice in Wilson''s disease for A. Initial therapy in patients with hepatitis without decompensation(2 A. Maintainance therapy B. Presymptomatic patient C. Pediatric patients D. Pregnant patients","pyqMatches":[{"year":"2012","no":1035,"q":"All of the following statements about. Wilson''s disease are true, EXCEPT","o":["It is an autosomal recessive disorder","Serum ceruloplasmin level is < 20 mg/dl","Urinary copper excretion is","Zinc acetate is effective as maintenance therapy"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2530, 'Medicine', 'Gastroenterology', 'Hard', 'Internal_Medicine', 90, '{"id":2530,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":90,"q":"A 14 year old boy presents wit recurrent episodes of hepatitis Opthalmoscopic evalution reveals KF rings and serum ceruloplasmin levels are < 20 mg/dl. The treatment of choice for initial therapy is","o":["Zinc","Penicillamine","Tetrathromolybdate","Hepatic transplantation"],"a":0,"e":"Answer is A (Zinc) Presence of KF rings and decreased ceruloplasmin levels suggest the diagnosis of Wilson ''s disease. The patient in question is presenting with intial hepatic disease without any evidence of hepatic decompensation. Zinc is the therapy of choice for patients with hepatitis or cirrhosis without evidence of hepatic decompensation or neuropsychiatric symptoms.","pyqMatches":[{"year":"2014","no":1408,"q":"A 14 year old boy presents wit recurrent episodes of hepatitis Opthalmoscopic evalution reveals KF rings and serum ceruloplasmin levels are < 20 mg/dl. The treatment of choice for initial therapy is","o":["Zinc","Penicillamine","Tetrathromolybdate","Hepatic transplantation"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2531, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 91, '{"id":2531,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":91,"q":"What is the uppermost intercostal space used for hepatic biopsy :","o":["5th","7th","9th","11th"],"a":1,"e":"Answer is B 7th The right surface of the liver is in contact with the diaphragm opposite the 7th to 11th ribs. In needle biopsy of the liver through the intercostal route, the needle may be inserted through the 6th 7th, 8th, 9th or 10th right intercostal space in the mid-axillary line. The 8th and 9th intercostal spaces are most commonly used. Insertion in the 6th or 7th intercostal space may also be used but is associated with risk of injury to the Lung. Needle is typically inserted at the end of expiration (Attempted Apnoea).","pyqMatches":[{"year":"2012","no":1030,"q":"What is the uppermost intercostal space used for hepatic biopsy :","o":["5th","7th","9th","11th"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2532, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 92, '{"id":2532,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":92,"q":"Significant weight loss is defined as:","o":["5% weight loss in 1-2 months","5% weight loss in 2-3 months","10% weight loss in 1-2 months","10% weight loss in 2-3 months"],"a":0,"e":"Answer is A (5% weight loss in 1-2 months): Significant weight loss is defined as 5% weight loss in I month. Percent weight change over a period of time is calculated using the person''s current body weight and person''s usual body weight. Usual weight — Current weight Percent weight change = Usual weight","pyqMatches":[{"year":"2015","no":1117,"q":"Significant weight loss is defined as:","o":["5% weight loss in 1-2 months","5% weight loss in 2-3 months","10% weight loss in 1-2 months","10% weight loss in 2-3 months"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2533, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 93, '{"id":2533,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":93,"q":"CRF with anemia best treatment:","o":["Oral Iron Therapy","Erythropoietin Stimulating Agents","Blood transfusion","Androgenic Steroids"],"a":1,"e":"Answer is B (Erythropoietin Stimulating Agents): Erythropoiesis-stimulating agents (ESAs) have emerged as the treatment of choice for anemia in chronic renal disease. Erythropoiesis-stimulating agents (ESAs) should be given to all patients with chronic kidney disease (CKD) with haemoglobin levels consistently below II g/dl. This applies equally to: Patients with CKD (stages 1-5) developing anaemia Patients with CKD stage 5 treated with haemodialysis (HD) or peritoneal dialysis (PD) Transplant patients with chronic renal insufficiency and anaemia. Strategies for treatment of Anemia in Chronic Renal Failure Erythropoiesis-stimulating agents (ESAs) Erythropoiesis-stimulating agents (ESAs) have emerged as the treatment of choice for anemia in chronic renal disease. They should be given to all patients with chronic kidney disease (CKD) with haemoglobin (Hb) levels consistently below 11 g/dl [haematocrit (Hct) <33%] All chronic kidney disease (CKD) patients with renal anaemia undergoing treatment with an erythropoiesis-stimulating agent (ESA) should be given supplementary iron to maintain adequate bone marrow iron stores Intravenous administration is the optimum route for the delivery of iron to patients with CKD, as oral iron is poorly absorbed in uremic individuals. Blood Transfusion Red blood cell transfusions should be avoided, if at all possible, in patients with chronic kidney disease (CKD), especially those awaiting kidney transplantation. Transfusions should not be given unless patients have one or more of the following: Symptomatic anaemia (fatigue, angina, dyspnoea) and/or associated risk factors (diabetes, heart failure, coronary artery disease, arteriopathy ) Acute worsening of anaemia due to blood loss (haemorrhage or surgery) or haemolysis Severe resistance to, or hyporesponsiveness to ESA therapy, e.g. due to the presence of a haematological disease or severe inflammatory systemic disease. Androgens Prior to the introduction of ESA therapy, androgens were widely used in the treatment of renal anaemia. There is evidence that androgens may potentiate the effect of exogenous erythropoietic protein and also stimulate erythropoiesis by enhancing erythrocyte stemcell differentiation The risk of liver disease and malignancy, virilisation and hirsutism in women, priapism in men and disfiguring acne in patients of both sexes may outweigh the benefits of androgen therapy in most anaemic patients. Androgens may be an effective alternative therapy in countries where ESAs are not available","pyqMatches":[{"year":"2012","no":1023,"q":"CRF with anemia best treatment:","o":["Oral Iron Therapy","Erythropoietin Stimulating Agents","Blood transfusion","Androgenic Steroids"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2534, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 94, '{"id":2534,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":94,"q":"The initial treatment of choice for secondary hyperparathyroidism in renal osteodystrophy is:","o":["Cinacalcet","Bisphosphonates","Calcium restriction","Phosphate binders"],"a":3,"e":"Answer is D (Phosphate Binders) The initial treatment of secondary hyperparathyroidism in renal osteodystrophy is management of high phosphate levels by dietary restriction and the use of Phosphate binders The objectives of management are to maintain blood levels of calcium and phosphorous to as close to normal as possible, to prevent or treat established hyperparathyroidism early and to prevent parathyroid hyperplasia. Phosphate retention begins early in the course of CKD, perhaps as early as in stage 2 and participates in the development of secondary hyperparathyroidism. Central to the management of high-turnover bone disease is controlling the serum phosphate levels. This may be achieved by dietary phosphate restriction or by the use of phosphate binders. Phosphate-binder therapy is recommended when serum phosphate concentrations are elevated despite patient compliance with dietary phosphate restriction. Calcium-based phosphate binders are often recommended as the initial binder therapy. High Bone Turnover Disease Bone turnover (the formation and removal of bone) is increased due to a process called secondary hyperparathyroidism (SHPT). Secondary hyperparathyroidism represents a common disorder in patients with CKD. It develops as a result of hyperphosphatemia, hypocalcemia and impaired renal vitamin D synthesis with reduction in serum calcitriol levels","pyqMatches":[{"year":"2012","no":1027,"q":"The initial treatment of choice for secondary hyperparathyroidism in renal osteodystrophy is:","o":["Cinacalcet","Bisphosphonates","Calcium restriction","Phosphate binders"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2535, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 95, '{"id":2535,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":95,"q":"The most common presentation for IgA nephropathy is:","o":["Nephritic syndrome","Nephritic syndrome","Microscopic hematuria","Repeated gross hematuria"],"a":3,"e":"Answer is D (Repeated Gross Hematuria): The most common presentation of IgA Nephropathy is with recurrent episodes of Gross (Macroscopic) Hematuria during or immediately following an upper respiratory tract infection ''Recurrent attacks of Painless Gross Hematuria represent the classic clinical presentation of IgA Nephropathy'' — Rudolph''s Paediatrics","pyqMatches":[{"year":"2012","no":1025,"q":"The most common presentation for IgA nephropathy is:","o":["Nephritic syndrome","Nephritic syndrome","Microscopic hematuria","Repeated gross hematuria"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2536, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 96, '{"id":2536,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":96,"q":"Disease, does not recur in the kidney after renal transplant is :","o":["Alport syndrome","Amyloidosis","Good Pasteur''s syndrome","Diabetic nephropathy"],"a":0,"e":"Answer is A (Alport''s syndrome): Alport is syndrome has not been mentioned to recur in kidney after a renal tansplant.","pyqMatches":[{"year":"2015","no":1115,"q":"Disease, does not recur in the kidney after renal transplant is :","o":["Alport syndrome","Amyloidosis","Good Pasteur''s syndrome","Diabetic nephropathy"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2537, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 97, '{"id":2537,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":97,"q":"True about light microscopy in minimal change disease is:","o":["Loss of foot process seen","Anti GBM Abs seen","IgA deposits seen","No change seen"],"a":3,"e":"Answer is D (No change seen) No abnormality is evident on light microscopy in a case of minimal change disease. Investigation Light microscopy Q Electron microscopy Q ImmunofluorescenceQ Observation No abnormality hence the term minimal change Fusion of foot processes Absence of immunoglobulin or complement","pyqMatches":[{"year":"2013","no":439,"q":"True about light microscopy in minimal change disease is:","o":["Loss of foot process seen","Anti GBM Abs seen","IgA deposits seen","No change seen"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2538, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 98, '{"id":2538,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":98,"q":"HIV renal specific nephropathy is:","o":["Focal Segmental Glomerulosclerosis","Membranoproliferative Glomerulonephritis","Mesangioproliferative Glomerulonephritis","Membranous Glomerulonephritis"],"a":0,"e":"Answer is A (Focal Segmental Glomerulosclerosis): The most characteristic glomerulopathy in HIV is Focal Segmental Glomerulosclerosis (FSGS) which typically reveals collapse of the glomerular capillary tuft called collapsing glomerulopathy. HIV associated Nephropathy is a severe rapidly progressive collapsing form of FSGS.","pyqMatches":[{"year":"2012","no":1026,"q":"HIV renal specific nephropathy is:","o":["Focal Segmental Glomerulosclerosis","Membranoproliferative Glomerulonephritis","Mesangioproliferative Glomerulonephritis","Membranous Glomerulonephritis"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2539, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 99, '{"id":2539,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":99,"q":"Distal renal tubular acidosis is associated with:","o":["Oxalate stones","Citrate","Calcium stones","Uric acid stones"],"a":2,"e":"Answer is C (Calcium Stones): Distal Renal Tubular Acidosis is associated with increased in cadence of Calcium Phosphate Stones Alkaline urine, Hypercalciuria and low levels of urinary citrate precipitate calcium phosphate stones in the kidney in patients with Distal Renal Tubular Acidosis (Typel). Proximal Renal Tubular Acidosis (Type-2) is not associated with increased incidence of Renal Stones despite Hypercalciuria because urinary citrate levels are normal or high.","pyqMatches":[{"year":"2012","no":1024,"q":"Distal renal tubular acidosis is associated with:","o":["Oxalate stones","Citrate","Calcium stones","Uric acid stones"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2540, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 100, '{"id":2540,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":100,"q":"Which of the following statement about Renal Cell Carcinoma (Hypemephroma) is false:","o":["Originate in the cortex","Histologically are usually Adenocarcinomas","May present with varicocele","Radiosensitive"],"a":3,"e":"Answer is D (Radiosensitive): Renal cell carcinoma is a relatively radioresistant tumor. Renal cell carcinoma originates in the Renal cortex `Renal cell carcinoma originates in the Renal cortex and tends to grow out into perinephric tissue causing the typical bulge or mass effect that aids in their detection by diagnostic imaging studies'' – Smith''s Urology Renal Cell carcinoma are adenocarcinomas Histologically Renal cell carcinoma is most often a mixed adenocarcinoma — Smith''s Urology Renal cell carcinomas may present with varicocele ''Renal cell carcinomas may present with Rapidly developing varicocele. Varicocele is usually observed on the left side. This occurs because left gonadal vein is obstructed where it joins the left renal vein. Renal cell carcinomas are Relatively Radioresistant tumors Renal cell carcinomas are generally considered radioresistant tumors Role of Radiotherapy in renal Cell carcinoma Preoperative Radiation has shown no impact on survival Postoperative Radiation has also shown no evidence of improved survival but may be used as it shows improvement in local control. Palliative Radiotherapy has been shown to be effective in metastatic disease to brain, bone and lungs.","pyqMatches":[{"year":"2014","no":1502,"q":"Which of the following statement about Renal Cell Carcinoma (Hypemephroma) is false:","o":["Originate in the cortex","Histologically are usually Adenocarcinomas","May present with varicocele","Radiosensitive"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2541, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 101, '{"id":2541,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":101,"q":"Classic triad inRenal cell carcinoma includes all of the following, Except:","o":["Hematuria","Hypertension","Flank mass","Abdominal Pain"],"a":1,"e":"Answer is B (Hypertension): Hypertension may be seen in patients with Renal cell carcinoma but it does not firm part of the classically described triad. Classic Triad of Renal cell carcinoma (seen in 10-20% of patients) Hematuria (Gross) Pain (Abdominal / Flank) Mass (Abdominal /Flank)","pyqMatches":[{"year":"2015","no":1220,"q":"Classic triad inRenal cell carcinoma includes all of the following, Except:","o":["Hematuria","Hypertension","Flank mass","Abdominal Pain"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2542, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 102, '{"id":2542,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":102,"q":"FEVI/FVC is decrease in:","o":["Asthma","Kyphosis","Scoliosis","Fibrosis"],"a":0,"e":"Answer is A (Asthma): Decreased FEV1/FVC suggests a diagnosis of Obstructive Lung Disease. Amongst the options provided Asthma is the only condition that leads to Obstructive Pattern of Lung Disease and hence is the answer of choice Kyphosis, Scoliosis and Fibrosis are Restrictive Lung Diseases that are characterized by Normal or Elevated FEVI/FVC ratios.","pyqMatches":[{"year":"2016","no":1068,"q":"FEVI/FVC is decrease in:","o":["Asthma","Kyphosis","Scoliosis","Fibrosis"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2543, 'Medicine', 'Dermatology & Allergy', 'Easy', 'Internal_Medicine', 103, '{"id":2543,"subject":"Medicine","chapter":"Dermatology & Allergy","difficulty":"Easy","source":"Internal_Medicine","sourceNo":103,"q":"Aspirin-sensitive asthma is associated with:","o":["Obesity","Urticaria","Nasal polyp","Extrinsic asthma"],"a":2,"e":"The answer is C (Nasal polyp): `Aspirin associated Asthma usually begins with perennial vasomotor rhinitis that is followed by hyperplastic rhinosinusitis with nasal polyps'' — Harrisons Aspirin associated Asthma: Primarily affects adults, although the condition may occur in childhood. Usually begins with perennial vasomotor rhinitis that is followed by hyperplastic rhinosinusitis with nasal polyps. Progressive asthma then appears. On exposure to even very small quantities of aspirin, affected individuals typically develop ocular and nasal congestion and acute, often severe episodes of airways obstruction. Death may follow ingestion of aspirin.","pyqMatches":[{"year":"2015","no":1076,"q":"Aspirin-sensitive asthma is associated with:","o":["Obesity","Urticaria","Nasal polyp","Extrinsic asthma"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2544, 'Medicine', 'Respiratory Medicine', 'Moderate', 'Internal_Medicine', 104, '{"id":2544,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":104,"q":"Feature of Acute severe Asthma include all of the following, Except:","o":["Tachycardia > 120/min","Pulsus paradoxus","Respiratory acidosis","Drowsy"],"a":0,"e":"Answer is A. Tachycardia > 120/min Diaphoresis Bradycardia Paradoxical throcobadominal movements PEER < 33% Hypotension Pulsus paradoxus Hypercapnea Silent chest","pyqMatches":[{"year":"2014","no":1252,"q":"Feature of Acute severe Asthma include all of the following, Except:","o":["Tachycardia > 120/min","Pulsus paradoxus","Respiratory acidosis","Drowsy"],"a":0,"source":"NEET_2014_Paper.pdf"},{"year":"2016","no":1079,"q":"Feature of Acute severe Asthma include all of the following, Except:","o":["Tachycardia > 120/min","Pulsus paradoxus","Respiratory acidosis","Drowsy"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2014","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2545, 'Medicine', 'Respiratory Medicine', 'Hard', 'Internal_Medicine', 105, '{"id":2545,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Hard","source":"Internal_Medicine","sourceNo":105,"q":"An Adult with asthma presents with asthma symptoms every day and wakes up in the night approximately 2 to 3 days in a week. He can be classified as having :","o":["Intermittent Asthma","Mild Persistent Asthma","Moderate Persistent Asthma","Severe Persistent Asthma"],"a":2,"e":"Answer is C (Moderate Persistent Asthma): ''Giudelines for the diagnosis and management of Asthma'' Summary Report 2007 (N1H Publication Number 08-5846); Koda-Kimble and Young''s Applied Therapeutics: The Clinical Use of Drugs 10TH/568,569,570 Moderate Persistent Asthma in an adult (>12 years) is defined as Day-Time Symptoms that occur daily and Night-Time Symptoms occurring more than 1 night per week but not every night.","pyqMatches":[{"year":"2014","no":1280,"q":"An Adult with asthma presents with asthma symptoms every day and wakes up in the night approximately 2 to 3 days in a week. He can be classified as having :","o":["Intermittent Asthma","Mild Persistent Asthma","Moderate Persistent Asthma","Severe Persistent Asthma"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2546, 'Medicine', 'Respiratory Medicine', 'Hard', 'Internal_Medicine', 106, '{"id":2546,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Hard","source":"Internal_Medicine","sourceNo":106,"q":"In a Patient with clinical signs of Asthma which of the following tests will confirm the diagnosis:","o":["Increase in FEV1/FVC","> 200 ml increase in FEVI after Methacholine","Diurnal variation in PEF > 20 Percent","Reduction of FEV I > 20 % after bronchodilators"],"a":2,"e":"Answer is C (Diurnal variation in PEF > 20 Percent): Demonstrate Outflow Obstruction Decreased FEV1 Decreased PEF Decreased FEV1 /FVC While respiratory symptoms suggest asthma, the sine qua non for the diagnosis of asthma is the presence of Reversible Airflow Obstruction and/or Airway Hyper-responsiveness or Increased Peak Expiratory Flow (PEF) Variability in subjects without airways obstruction. Reversible Airflow Obstruction Reversibility is demonstrated by repeating spirometry results 15 minutes after administering a short acting bronchodilator > 12% reversibility in FEV1 >200 ml increase in Baseline FEV1 Positive Reversibility Results Strongly (Considered Diagnostic) Increased Peak Expiratory Flow Rate (PEF) Variability Demonstration of Diurnal Variation in the Peak Expiratory Flow Rate A diurnal variation in PEF of more than 20 percent Strongly suggests a diagnosis of Asthma (Considered Diagnostic) Airway Hyper-responsiveness Measured by Methacholine orHistamine challenge. Increasing Concentrations of Methacholine are administered and if the FEV1 drops to >20 percent of baseline with any standard dose the test is consideredpositive. Positive test strongly suggests a diagnosis of Asthma","pyqMatches":[{"year":"2014","no":1281,"q":"In a Patient with clinical signs of Asthma which of the following tests will confirm the diagnosis:","o":["Increase in FEV1/FVC","> 200 ml increase in FEVI after Methacholine","Diurnal variation in PEF > 20 Percent","Reduction of FEV I > 20 % after bronchodilators"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2547, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 107, '{"id":2547,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":107,"q":"Antibody used in the treatment of Bronchial Asthma is:","o":["Omalizumab","Rituximab","Daclizumab","Transtusuzumab"],"a":0,"e":"Answer is A (Omalizumab): Omalizumab is a recombinant IgE Antibody approved for use in treatment of moderate and severe persistent asthma Omalizumab is a recombinant IgE blocking antibody that neutralizes circulating IgE. It prevents circulating IgE from binding to receptors on the surface of Basophils and Mast cells and thus inhibits IgE mediated reactions. Omalizumab is indicated for treatment of ''moderate to severe'' persistent asthma in patients who react to perennial allergens (Allergic Asthma). Treatment with Omalizumab has shown to reduce the number of exacerbations in patients with severe asthma and may improve asthma control. However this treatment is very expensive and is only suitable for highly selected patients who are not controlled on maximal doses of inhaler therapy and have a high circulating IgE (within a specified range). Omalizumab is usually given as a subcutaneous injection for 2 to 4 weeks and may be used in adults and adolescents more than 12 years of age.","pyqMatches":[{"year":"2012","no":1018,"q":"Antibody used in the treatment of Bronchial Asthma is:","o":["Omalizumab","Rituximab","Daclizumab","Transtusuzumab"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2548, 'Medicine', 'Respiratory Medicine', 'Moderate', 'Internal_Medicine', 108, '{"id":2548,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":108,"q":"Which of the following is the least common bacteria responsible for Acute Exacerbation of Chronic Bronchitis","o":["Streptococcus pneumoniae","Moraxella catarrhalis","Haemophilus influenza","Staphylocccus aureus"],"a":3,"e":"Answer is D (Staphylocccus aureus): The Global Initiative for Chronic Obstructive Lung Disease (GOLD); Report produced by the National Heart, Lung, and Blood Institute (NHLBI) and the World Health Organization (WHO) Staphylococcus Aureus is not a common bacterial pathogen responsible for Acute Exacerbation of Chronic Bronchitis. Common Bacterial Pathogens (30%-50%) Responsible for Acute Exacerbations of COPD Haemophilus influenza Streptococcus pneumonia Moraxella catarrhalis Pseudomonas aeruginosa and Enterobacteriaceae are also commonly isolated, particularly from patients with severe COPD. Acute Exacerbation of COPD: Bacterial Infections The GOLD, the NHLBI and the WHO, defines exacerbation of COPD as acute increase in symptoms beyond normal day-to-day variation. This generally includes one or more of the following cardinal symptoms. Cough increases in frequency and severity Sputum production increases in volume and/or changes character Dyspnea increases Constitutional symptoms, decrease in pulmonary function, and tachypnea are variably present during an exacerbation, but the CXR is usually unchanged. In the presence of severe underlying airflow obstruction, exacerbation can cause respiratory failure and death. It is estimated that 70 to 80% of exacerbations of COPD are due to respiratory infections. The remaining 20 to 30% are due to environmental pollution or have an unknown etiology. Viral and bacterial infections cause most exacerbations Bacterial infections appear to trigger 33% to 50% of COPD exacerbations. Non-typeable H. influenzae, M. catarrhalis, and S. pneumoniae are the bacteria most frequently isolated bronchoscopically from patients having an exacerbation of COPD Pseudomonas aeruginosa and other members of family Enterobacteriaceae are also commonly isolated, particularly from patients with severe COPD. Exacerbations of COPD are strongly associated with acquisition of new strain of H. influenzae, M. catarrhalis, S. pneumoniae, or P. aeruginosa. As a result, it has been proposed that acquisition of new bacterial strain plays central role in the pathogenesis of an exacerbation. The idea that exacerbations of COPD are due to acquisition of new strain of bacteria has largely replaced older hypothesis that increases in concentration of colonizing bacteria are the primary cause of exacerbations.","pyqMatches":[{"year":"2014","no":1303,"q":"Which of the following is the least common bacteria responsible for Acute Exacerbation of Chronic Bronchitis","o":["Streptococcus pneumoniae","Moraxella catarrhalis","Haemophilus influenza","Staphylocccus aureus"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2549, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 109, '{"id":2549,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":109,"q":"Occupational Lung Disease commonly seen in Textile Industry Workers is:","o":["Byssinosis","Bagassosis","Farmer''s Lung","Asbestosis"],"a":0,"e":"Answer is A (Byssinosis) Occupational Lung Disease in Textile Industry Workers (Cotton industry) Byssinosis is an asthma-like condition caused by inhalation of cotton fiber dust over prolonged period of time. Workers occupationally exposed to cotton dust (but also to flax, hemp or jute dust) in the production of yarns for textile and rope making are at risk of Byssinosis. Exposure occurs throughout the manufacturing process but is most pronounced in the portions of the factory involved with the treatment of cotton before spinning (blowing, mixing, carding or straightening) Byssinosis is more common during milling and processing of cotton than during spinning.","pyqMatches":[{"year":"2014","no":1344,"q":"Occupational Lung Disease commonly seen in Textile Industry Workers is:","o":["Byssinosis","Bagassosis","Farmer''s Lung","Asbestosis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2550, 'Medicine', 'Respiratory Medicine', 'Moderate', 'Internal_Medicine', 110, '{"id":2550,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":110,"q":"All the following are features of Tropical pulmonary Eosinophilia except-","o":["Eosinophilia > 3000/mm3","Microfilaria in blood","Paroxysmal cough and wheeze","Bilateral chest mottling and increased bronchovascular markings"],"a":1,"e":"Answer is B (Microfilaria in blood) : In TPE, Microfilaria are rapidly cleared from the blood stream by the lungs. Thus, microfilariae are sequestrated in the lungs and are not found in the blood. Tropical Pulmonary Eosinophilia Tropical Pulmonary Eosinophilia (TPE) is a distinct syndrome that develops in individuals infected with Lymphatic filarial species. Clinical symptoms result from allergic and inflammatory reaction elicited by the cleared parasites. Features of Tropical Pulmonary eosinophilia (TPE) : Male more commonly affected than females (4: 1) History of resistance in filarial endemic region Paroxysmal cough and wheezing that are usually nocturnal Weight loss, low grade fever, adenopathy Eosinophilia > 3000 eosinophilia / ,uLe Chest X-Ray : increased bronchovascular markings , diffuse miliary lesions , or mottled opacities. Restrictive changes on Pulmonary function test 2 Elevated levels of IgE e & Antifilarial antibody titers. In TPE, Microfilaria are rapidly cleared from the blood stream by the lungs. Thus, microfilariae are sequestrated in the lungs and are not found in the blood.","pyqMatches":[{"year":"2014","no":1363,"q":"All the following are features of Tropical pulmonary Eosinophilia except","o":["Eosinophilia > 3000/mm3","Microfilaria in blood","Paroxysmal cough and wheeze","Bilateral chest mottling and increased bronchovascular markings"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2551, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 111, '{"id":2551,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":111,"q":"Most common pattern of Pneumonia seen in Klebsiella infection is:","o":["Lobar Pneumonia","Bronchopneumonia","Interstitial Pneumonia","Miliary Pneumonia"],"a":0,"e":"Answer is A (Lobar Pneumonia): The most common pattern of Pneumonia seen in Klebsiella infection is Lobar Pneumonia Streptococcus Pneumoniae (Pneumococcus) and Klebsiella are two common organisms that produce a lobar pattern of Pneumonia. The radiographic pattern of pneumonia. Lobar Lobular (bronchopneumonia) Interstitial","pyqMatches":[{"year":"2014","no":1398,"q":"Most common pattern of Pneumonia seen in Klebsiella infection is:","o":["Lobar Pneumonia","Bronchopneumonia","Interstitial Pneumonia","Miliary Pneumonia"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2552, 'Medicine', 'Respiratory Medicine', 'Moderate', 'Internal_Medicine', 112, '{"id":2552,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":112,"q":"All of the following are more commonly seen in Klebsiella Pneumonia than in Pneumococcal Pneumonia, Except:","o":["Lower lobe involvement","Abscess Formation","Pleural Effusion","Cavitation"],"a":0,"e":"The answer is A (Lower Lobe Involvement): Pneumococcal pneumonia has a predilection to involve the right lower lobe, whereas Klebsiella usually affects one of the upper lobes. Features Pneumococcal Pneumonia Klebsiella Pneumonia Consolidation Pattern • Lobar Consolidation with positive air bronchogram sign • Lobar Consolidation with positive air bronchogram sign Lobe Predilection • The predilection to involve Lower Lobe (Any lobe may be involved) • Usually Unilobar (Usually do not expand involved lobe) • The predilection to involve Upper Lobe (Any lobe may be involved) • Often Multilobar (Tendency to expand involved lobe) Abscess • Abscess formation uncommon • Abscess Formation common Pleural • Pleural Effusion • Pleural Effusion Effusion uncommon common Cavitation • Cavitation is rare • Cavitation is common","pyqMatches":[{"year":"2014","no":1397,"q":"All of the following are more commonly seen in Klebsiella Pneumonia than in Pneumococcal Pneumonia, Except:","o":["Lower lobe involvement","Abscess Formation","Pleural Effusion","Cavitation"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2553, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 113, '{"id":2553,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":113,"q":"Friedlander Pneumonia refers to Pneumonia caused by:","o":["Klebsiella","Pneumococcus","H. lnfluenzae","Staphylococcus"],"a":0,"e":"Answer is A (Klebsiella): Klebsiella Pneumonia is also known as Friedlander Pneumonia. Klebsiella initially described in 1882 by Friedlander was also known as Friedlander''s bacillus. Community acquired Pneumonia caused by Friedlander''s bacillus (Klebsiella) was termed as Friedlander Pneumonia.","pyqMatches":[{"year":"2014","no":1399,"q":"Friedlander Pneumonia refers to Pneumonia caused by:","o":["Klebsiella","Pneumococcus","H. lnfluenzae","Staphylococcus"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2554, 'Medicine', 'Respiratory Medicine', 'Moderate', 'Internal_Medicine', 114, '{"id":2554,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":114,"q":"Atypical pneumonia can be caused by the following microbial agents except?","o":["Mycoplasma pneumoniae.","Legionella pemmophila","Human Corona virus","Klebsiella pneumoniae"],"a":3,"e":"Answer is D (Kleibsella pneumonia) : Causes of Atypical pneumonias .","pyqMatches":[{"year":"2016","no":787,"q":"Atypical pneumonia can be caused by the following microbial agents except?","o":["Mycoplasma pneumoniae.","Legionella pemmophila","Human Corona virus","Klebsiella pneumoniae"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2555, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 115, '{"id":2555,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":115,"q":"The most definitive method of diagnosing pulmonary embolism is :","o":["Pulmonary arteriography","Radioisotope perfusion pulmonary scintigraphy","EKG","Venography"],"a":0,"e":"Answer is A (Pulmonary arteriography): `Selective pulmonary angiography is the most specific examination available for establishing the definitive diagnosis of PE.''-Harriosn 16th/1563 Most definitive investigation :Pulmonary angiography is an invasive procedure, and it is the most definitive procedure. It is however certainly not the initial investigation of choice. The initial investigation of choice in a case of suspected pulmonary embolism is either a lung ventilation perfusion scan or a CT of the chest with intravenous contrast. `CT scanning of the chest with intravenous contrast is the principal imaging test for diagnosis of PE.'' - Harrison `Lung scanning (V/Q scan) is now a second line diagnostic test for PE'' Most definitive / specific test for PE Q Best initial imaging test for diagnosis of PE° Pulmonary angiographyQ CT scan with intravenous contrast Q (Preferred choice, against a lung V-Q scan)","pyqMatches":[{"year":"2013","no":1264,"q":"The most definitive method of diagnosing pulmonary embolism is :","o":["Pulmonary arteriography","Radioisotope perfusion pulmonary scintigraphy","EKG","Venography"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2556, 'Medicine', 'Rheumatology', 'Moderate', 'Internal_Medicine', 116, '{"id":2556,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":116,"q":"All of the following show low glucose in pleural fluid, EXCEPT-","o":["Empyema","Malignant pleural effusion","Rheumatoid arthritis","Dressler''s syndrome"],"a":3,"e":"Answer is D (Dressler''s Syndrome): Dressler syndrome is a secondary form of pericarditis that occurs in the setting of injury to the heart or the pericardium (the outer lining of the heart). It consists of fever, pleuritic pain, pericarditis and/or pericardial effusion. The disease consists of persistent low-grade fever, chest pain (usually pleuritic), pericarditis and/or pericardial effusion. The symptoms tend to occur 2–3 weeks after myocardial infarction but can also be delayed a few months. It tends to subside in a few days, and very rarely leads to pericardial tamponade. Elevated ESR is an objective but nonspecific laboratory finding. Dressler''s Syndrome is not associated with low glucose in pleural fluid. Rheumatoid Arthritis, Malignancy and Empyema (Bacterial infections) are all established causes of pleural effusion with low glucose. Pleural effusion with low glucose (< 60 mg/c11)","pyqMatches":[{"year":"2020","no":170,"q":"All of the following show low glucose in pleural fluid, EXCEPT","o":["Empyema","Malignant pleural effusion","Rheumatoid arthritis","Dressler''s syndrome"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2557, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 117, '{"id":2557,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":117,"q":"Which of the following statements about Branchial cysts is true:","o":["50-70% are seen in lungs","Most common site is mediastinum","They are premalignant lesions","Infection is uncommon in Pulmonary bronchogenic cysts"],"a":1,"e":"Answer is B (Most common site is mediastinum): Most common site of bronchial/bronchogenic cysts is mediastinum. Only about 15% of bronchogenic cysts occur in the lungs (pulmonary bronchial cysts). Pulmonary bronchogenic cysts often become infected. Bronchogenic cysts are benign lesion and do not have malignant potential (not premalignant). Bronchial Cyst/Bronchogenic cysts: Review Bronchial cysts represent islands of bronchial tissue left behind during the branching of the airways during early fetal development. They arise due to abnormal budding of the tracheobronchial tree and foregut and are lined by bronchial epithelium. The most common site of bronchial cysts is mediastinum. The other site of bronchial cyst is within the pulmonary parenchyma (lung) (Less common site - 15%) Mediastinal bronchial cyst Pulmonary parenchymal cyst (lungs) Most common site for bronchial cysts Most common site is middle mediastinum Commonly arise when Less common site (- 15%) Most common site is the lower lobes Commonly arise when bronchial tissue is separated from airways bronchial tissue is separated from airways early in gestation Communication with tracheobronchial tree is rare late in gestation Communication with tracheobronchial tree is more common than with mediastinal cysts. These cysts often become infected. Most bronchogenic cysts are asymptomatic and discovered as incidental radiographic findings in a young adult. When symptoms do occur they result most commonly from infection. Pulmonary parenchymal cysts often become infected – Rudolph Bronchogenic cysts are not considered premalignant lesions. However according to Rudolph''s textbook there is a small risk of malignant change and the best approach is removal and histological examination.","pyqMatches":[{"year":"2015","no":1308,"q":"Which of the following statements about Branchial cysts is true:","o":["50-70% are seen in lungs","Most common site is mediastinum","They are premalignant lesions","Infection is uncommon in Pulmonary bronchogenic cysts"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2558, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 118, '{"id":2558,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":118,"q":"Which of the following drugs, is used for Smoking Cessation?","o":["Naltrexone","Bupropion","Buprenorphine","Methadone"],"a":1,"e":"Answer is B (Bupropion): Bupropion (along with Varenicline and Nicotine replacement therapy) is a USFDA approved first line agent for pharmacotherapy in Smoking Cessation. USFDA Approved Agents for Smoking Cessation Nicotine Replacement Therapy (Transdermal Patch, gum, lozenges, oral inhaler, nasal spray) Bupropion (Atypical Antidepressant with dopaminergic and noradrenergic activity) Varenicline (Selective partial agonist at the Alpha4-Beta2 Nicotinic A-Choline receptor that is believed to mediate nicotine dependence) Clonidine and Nortriptyline are two other medications that have efficacy but are NOT USFDA approved for this indication. These are classified as second line agents.","pyqMatches":[{"year":"2013","no":494,"q":"Which of the following drugs, is used for Smoking Cessation?","o":["Naltrexone","Bupropion","Buprenorphine","Methadone"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2559, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 119, '{"id":2559,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":119,"q":"ANCA is NOT associated with which of the following diseases :","o":["Wegener''s granulomatosis","Henoch schonlein purpura","Microscopic PAN","Churg Strauss syndrome"],"a":1,"e":"Answer is B (H.S. Purpura) : H.S. purpura is not associated with any antinuclear cytoplasmic antibody (ANCA). It is an example of ANCA negative vasculitis. ANCA (Antineutrophilic cytoplasmic Antibodies) arc Antibodies directed against certain proteins in cytoplasmic granules of Neutrophil & monocytes. These are two major categories of ANCA based on different targets for the antibodies. ANCA (Antineutrophic cytoplasmic antibodies): ANCA is of 2 types C-ANCA (Cytoplasmic proteinase 3q is the target antigen) Wegeners Granulomatosisq (90-95%) P-ANCA (perinuclear myeloperoxidaseQ is the major target antigen) Microscopic PAN (microscopic polyangitis) Churg-Strauss syndrome Crescenteric glomerulonephritise Good pasteur''s syndrome","pyqMatches":[{"year":"2012","no":1081,"q":"ANCA is NOT associated with which of the following diseases :","o":["Wegener''s granulomatosis","Henoch schonlein purpura","Microscopic PAN","Churg Strauss syndrome"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2560, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 120, '{"id":2560,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":120,"q":"Feature of microscopic polyangitis is:","o":["IgG deposits in kidney","Bronchospasm","Renal involvement in 80% of cases","All of the above"],"a":2,"e":"Answer is C (Renal involvement in 80% of cases): Renal involvement is seen in at least 80% ofpatients with MPA. Renal involvement is seen in at least 80% of patients with MPA Renal involvement is seen in at least 80% of patients with MPA - CRDT Glomerulonephritis occurs in atleast 79% of patients – Harrison Microscopic polyangitis is not associated with IgG Deposits in kidney Microscopic Polyangitis is a pauci-immune glomerulonephritis. Immunofluorescence and electron microscopy show no immune deposits Microscopic Polyangitis is not associated with bronchospasm Asthma (bronchospasm) and Eosinophilia are features of Churg- Strauss Syndrome and are typically absent in microscopic polyangitis. Features H.S. purpura Microscopic Polyangitis Wegner''s Granulomatosis Churg- Strauss syndrome Deposits in kidney -- nt (IgA deposits) - Bronchospasm (Asthma) - - - + Eosinophilia - - - + Predominant ANCA - p-ANCA c-ANCA p-ANCA","pyqMatches":[{"year":"2015","no":495,"q":"Feature of microscopic polyangitis is:","o":["IgG deposits in kidney","Bronchospasm","Renal involvement in 80% of cases","All of the above"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2561, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 121, '{"id":2561,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":121,"q":"Jaw tightness is typically seen in:","o":["PAN","Coarctation of aorta","Giant cell arteritis","Wegner''s Granulomatosis"],"a":2,"e":"Answer is C (Giant Cell Arteritis): Jaw Claudication (law Tightness) is a typical manifestation of Temporal arteritis or Giant cell arteritis.","pyqMatches":[{"year":"2012","no":1012,"q":"Jaw tightness is typically seen in:","o":["PAN","Coarctation of aorta","Giant cell arteritis","Wegner''s Granulomatosis"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2562, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 122, '{"id":2562,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":122,"q":"Reversed Coarctation is seen in:","o":["Giant cell Arteritis","Polyarteritis Nodosa","Takayasu Arteritis","Kawasaki Disease"],"a":2,"e":"Answer is C (Takayasu Arteritis): Takayasu arteritis is also known as ''Reversed Coarctation''. Condition Coarctation of Aorta Takayasu Arteritis (Reversed Coarctation) Pathology (Site of Obstruction) Obstruction is most commonly found just distal to the origin of the left Subclavian artery thereby sparing the upper limb vessels Obstruction is most commonly seen in proximal aspect of branches of the aortic arch including the Subclavian and Common Carotid thereby affecting the upper limb vessels Pulses Absence or diminished pulse in the lower limbs Absence or diminished pulse in the upper limbs Blood Pressure Increased blood pressure in the upper limbs Decreased blood pressure in the upper limbs","pyqMatches":[{"year":"2014","no":1483,"q":"Reversed Coarctation is seen in:","o":["Giant cell Arteritis","Polyarteritis Nodosa","Takayasu Arteritis","Kawasaki Disease"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2563, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 123, '{"id":2563,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":123,"q":"Takayasu arteritis mainly affects?","o":["Pulmonary artery","Celiac artery","Subclavian artery","SMA"],"a":2,"e":"Answer is C (Subclavian Artery): Subclavian artery is the single most common artery involved in Takayasu arteritis. Takayasu arteritis : Most common sites affected Takayasu arteritis typically involves medium and large sized arteries It has a strong predilection for the aortic arch and its branches. The involvement of the major branches of the aorta is much more marked at their origin than distally The most commonly affected arteries as seen by arteriography in order of frequency Coronary (<10%) Vertebral (35%) Coeliac axis (18%) Pulmonary (10-40 %) Superior Mesenteric (18%) Iliac (17%) Subclavian (93%) Common Carotid (58%) Abdominal Aorta (47%) Renal (38%)","pyqMatches":[{"year":"2016","no":422,"q":"Takayasu arteritis mainly affects?","o":["Pulmonary artery","Celiac artery","Subclavian artery","SMA"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2564, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 124, '{"id":2564,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":124,"q":"Most common variant of Takayasu Disease in India is:","o":["Type-1","Type-2","Type-3","Type-4"],"a":2,"e":"Answer is C (Type -3): The most common type of Takayasu arteritis reported in India is Type III. Most studies from India have reported Type III as the most common form of Takayasu arteritis in India accounting for 53 to 76 percent of cases. Classification / Type Predominant Site Involved Type-I (Shimizu- Savo) Arch of aorta and its branches Type-II (Kimoto) Thoraco-abdominal aorta and its branches without involvement of the aortic arch Type-III (Inada) Combined features of both Type-I & Type-II Type-IV (Oata) Pulmonary involvement (in addition to features of Type-I, II or III) Involvement of coronary arteries (in addition to features of Type-1, II or III)","pyqMatches":[{"year":"2014","no":1484,"q":"Most common variant of Takayasu Disease in India is:","o":["Type-1","Type-2","Type-3","Type-4"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2565, 'Medicine', 'Dermatology & Allergy', 'Moderate', 'Internal_Medicine', 125, '{"id":2565,"subject":"Medicine","chapter":"Dermatology & Allergy","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":125,"q":"Kawasaki disease is associated with all of the following clinical features except","o":["Truncal rash","Posterior cervical lymphadenopathy","Thrombocytopenia","Pericarditis"],"a":2,"e":"Answer is C (Thrombocytopenia) : Kawasaki disease is associated with thrombocytosis and not thrombocytopenia. Characteristic laboratory findings Treatment of Choice Prognosis include Increased ESR High dose intravenous Prognosis for uneventful recovery is Thrombocytosise immunoglobulinse excellente","pyqMatches":[{"year":"2012","no":1086,"q":"Kawasaki disease is associated with all of the following clinical features except","o":["Truncal rash","Posterior cervical lymphadenopathy","Thrombocytopenia","Pericarditis"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2566, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 126, '{"id":2566,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":126,"q":"Treatment of choice for Kawasaki Disease is:","o":["IV Immunoglobulins","Steroids","Dapsone","Methotrexate"],"a":0,"e":"Answer is A (IV Immunoglobulins): The treatment of choice in Kawasaki disease is intravenous immunglobulins","pyqMatches":[{"year":"2015","no":1428,"q":"Treatment of choice for Kawasaki Disease is:","o":["IV Immunoglobulins","Steroids","Dapsone","Methotrexate"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2567, 'Medicine', 'Hematology', 'Moderate', 'Internal_Medicine', 127, '{"id":2567,"subject":"Medicine","chapter":"Hematology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":127,"q":"Features of SLE include all of the following except:","o":["Recurent abortion","Sterility","Coomb''s positive hemolytic anemia","Psychosis"],"a":1,"e":"Answer is B (Sterility): Systemic Lupus Erythematosus. Recurrent Abortions in SLE may be seen as a manifestation of Antiphospholipid Antibody syndrome. Small proportion of patients with SLE may have a Coomb''s Positive Haemolytic anemia. Psychosis is a known neurological manifestation of SLE.","pyqMatches":[{"year":"2012","no":1076,"q":"Features of SLE include all of the following except:","o":["Recurent abortion","Sterility","Coomb''s positive hemolytic anemia","Psychosis"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2568, 'Medicine', 'Rheumatology', 'Easy', 'Internal_Medicine', 128, '{"id":2568,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":128,"q":"Shrinking Lung Syndrome is seen in:","o":["SLE","Rheumatoid Arthritis","Scleroderma","Sarcoidosis"],"a":0,"e":"Answer is A (SLE): Shrinking lung syndrome refers to a condition typical of SLE that consists of a purely restrictive respiratory disease with normal lung parenchyma and markedly decreased lung volumes. Shrinking lung syndrome Shrinking lung syndrome refers to a condition typical of SLE that consis respiratory disease with normal lung parenchyma and markedly decrea Pathogentic Mechanism Diaphragmatic dysfunction has been advocated as the main pathogene shrinking lung syndrome Clinical Presentation Shrinking lung syndrome usually manifests as exertional dyspnea of va progress over a period of weeks or months. (Orthopnea attributed to dia may also occur). Pleuritic chest pain is reported frequently, and a previous history of pleu common. Physical examination is remarkably normal. Investigations Chest radiography typically shows elevated hemi-diaphragms, although finding and its absence does not exclude the diagnosis. Pleural effusion atelectasis may be also evident on plain films or CT scans. Pulmonary function tests show a marked restrictive pattern, with decrea u o a y u ct o tests s o a a ed est ct e patte , t dec ea (FVC). Carbon monoxide diffusion corrected by lung volumes is typically norma Anti-Ro antibodies may be present, although they do not offer an additio Prognosis The prognosis of this syndrome is usually good (Most patients show lon","pyqMatches":[{"year":"2015","no":412,"q":"Shrinking Lung Syndrome is seen in:","o":["SLE","Rheumatoid Arthritis","Scleroderma","Sarcoidosis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2569, 'Medicine', 'Rheumatology', 'Easy', 'Internal_Medicine', 129, '{"id":2569,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":129,"q":"Antibodies most commonly seen in drug induced lupus are:","o":["Anti ds DNA Antibodies","Anti Sm Antibodies","Anti-Ro Antibodies","Antihistone Antibodies"],"a":3,"e":"Answer is D (Antihistone Antibodies): The most commonly used marker for drug induced lupus is Antihistone Antibodies. Drug Induced Lupus is characterized serologically by the presence of Anti-Histone Antibodies and the absence of antibodies against double stranded DNA (dsDNA Antibody Negative; Anti-Histone Antibody Positive). Anti-dsDNA Serology in Drug Induced Lupus Erythematosus Almost all patients with Drug Induced Lupus will test positive for Antinuclear Antibodies (Positive ANA Test) The spectrum of Antinuclear antibodies in Drug Induced Lupus includes Positive Antihistone antibodies (most common; not specific; also seen in SLE) Positive autoantibodies against single stranded DNA (common ; not specific; also seen in SLE) Negative (absence of) autoantibodies against double stranded DNA(dsDNA) The presence of autoantibodies against dsDNA strongly suggests a diagnosis of SLE Drug Induced Lupus is typically associated with a Homogeneous ANA pattern due to the presence of Antihistone Antibodies Antibodies are seen in less than 5 percent of patients with Drug Induced Lupus The presence of Antihistone antibodies alone is not a specific test for diagnosis of Drug Induced Lupus as Antibodies to histones may also be seen in up to 50 to 80 percent of patients with idiopathic SLE. Note : Hypocomplementemia is uncommon in Drug Induced Lupus but not in SLE.","pyqMatches":[{"year":"2012","no":1077,"q":"Antibodies most commonly seen in drug induced lupus are:","o":["Anti ds DNA Antibodies","Anti Sm Antibodies","Anti-Ro Antibodies","Antihistone Antibodies"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2570, 'Medicine', 'Gastroenterology', 'Moderate', 'Internal_Medicine', 130, '{"id":2570,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":130,"q":"Bilateral parotid enlargement occurs in all, Except:","o":["Sjogren''s syndrome","SLE","HIV","Chronic pancreatitis"],"a":1,"e":"Answer is B (SLE): Bilateral parotid enlargement is not a feature of SLE. Causes of Bilateral parotid enlargement Viral infections Metabolic causes Endocrinal Miscellaneous • Mumps • Influenza • Epstein barr virus • Coxackie virus A • CMV • HIV • • • • Diabetes mellitus Hyper lipoproteinemia Chronic pancreatitise Cirrhosis • • Acromegaly Gonadal hypofunction • • • Sarcoidosis Amyloidosis Sjogren syndrome","pyqMatches":[{"year":"2015","no":1276,"q":"Bilateral parotid enlargement occurs in all, Except:","o":["Sjogren''s syndrome","SLE","HIV","Chronic pancreatitis"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2571, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 131, '{"id":2571,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":131,"q":"Lupus Pernio is seen in:","o":["Tuberculosis","SLE","PAN","Sarcoidosis"],"a":3,"e":"Answer is D (Sarcoidosis): Pernio is a typical cutaneous manifestation of Sarcoidosis. Lupus Pernio is the most typical and easily recognizable skin lesions of Sarcoidosis. It is characterized by the presence of violaceous, purple blue shiny swollen lesions over the bridge of nose, beneath the eyes and over the cheeks. This specific complex of involvement of the bridge of nose, the area beneath the eyes and the cheeks is considered diagnostic for a chronic form of Sarcoidosis.","pyqMatches":[{"year":"2012","no":1088,"q":"Lupus Pernio is seen in:","o":["Tuberculosis","SLE","PAN","Sarcoidosis"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2572, 'Medicine', 'Rheumatology', 'Easy', 'Internal_Medicine', 132, '{"id":2572,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":132,"q":"Keratoderma Blenorrhagica is typically seen in","o":["Rheumatoid Arthritis","Psoriatic Arthritis","Reactive Arthritis","Ankylosing spondylitis"],"a":2,"e":"Answer is C (Reactive Arthritis): Keratoderma Blenorrhagica is the charachteristic skin lesion seen in patients with Reactive Arthritis. ''The charachteristic skin lesions in Reactive Arthritis, Keratoderma Blenorrha2ica, consist of vesicles that become hyperkeratotic, ultimately forming a crust before disappearing. In patients with HIV infection, these lesions are often extremely severe and extensive sometimes dominating the clinical picture ''-","pyqMatches":[{"year":"2014","no":1388,"q":"Keratoderma Blenorrhagica is typically seen in","o":["Rheumatoid Arthritis","Psoriatic Arthritis","Reactive Arthritis","Ankylosing spondylitis"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2573, 'Medicine', 'Endocrinology', 'Moderate', 'Internal_Medicine', 133, '{"id":2573,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":133,"q":"Which of the following statements about Hematochromatosis is not true","o":["Hypogonadism may be seen","Arthropathy may occur","Diabetes Mellitus may develop","Desferrioxamine is treatment of choice"],"a":3,"e":"Answer is D (Desferrioromine is treatment of choice): The therapy of hematochromatosis involves removal of excess body iron. Iron removal is best achieved by periodic phlebotomies which is the treatment of choice for Hematochromosis. Chelating agents like desferoxamine are less effective and indicated when anemia or hypoproteinemia is severe enough to preclude phlebotomy. Chelating agents are not the treatment of choice for Hematochromatosis.","pyqMatches":[{"year":"2014","no":1421,"q":"Which of the following statements about Hematochromatosis is not true","o":["Hypogonadism may be seen","Arthropathy may occur","Diabetes Mellitus may develop","Desferrioxamine is treatment of choice"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2574, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 134, '{"id":2574,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":134,"q":"Renal artery stenosis may occur in all of the following, except :","o":["Atherosclerosis","Fibromuscular dysplasia","Takayasu''s arteritis","Polyarteritis nodosa"],"a":3,"e":"Answer is D (Polyarteritis nodosa) Amongst the options provided renal artery stenosis is least likely to be seen in association with Polyarteritis nodosa. Atherosclerosis and Fibromuscular disease - Renal artery stenosis is produced predominantly by atherosclerotic occlusive disease (80% to 90% of patients) or tibromuscular dysplasia (10-15% of patients).- CMDT''06 p 460 - he common cause of renal artery stenosis in the middle aged and elderly is an atheromatous plaque at origin of renal artery. Harrison - In younger women stenosis is due to intrinsic structural abnormalities of the arterial wall caused by a heterogenous group of lesions called ''fibromuscular dysplasia''. - Harrison 16`\" /1707 PAN or Takayasu arteritis ? CMDT do not mention PAN or Takayasu arteritis as a cause for renal artery stenosis. However, Takayasu arteritis is certainly a more common cause of renal artery stenosis than PAN. Takayasu arteritis (Aorto-arteritis) is beleiveds to be the most common of renovascular hypertension in India and China. – Diseases of Kidney and Urinary Tract 8th/1279 A number of research publications, however show Takayasu arteritis as a cause for renal artery stenosis. PAN Although renal involvement is seen in upto 60% of patients with PAN its pathology does not involve renal artery stenosis. The pathology involves arteritis without glomerulonephritis and is characterised by aneurysms of small and medium sized arteries. Stenosis of main renal artery is an unusual association''. Causes of Renal artery stenosis :","pyqMatches":[{"year":"2013","no":1282,"q":"Renal artery stenosis may occur in all of the following, except :","o":["Atherosclerosis","Fibromuscular dysplasia","Takayasu''s arteritis","Polyarteritis nodosa"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2575, 'Medicine', 'Endocrinology', 'Easy', 'Internal_Medicine', 135, '{"id":2575,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":135,"q":"The most common cause of Cushing''s syndrome is:","o":["Pituitary adenoma","Adrenal adenoma","Ectopic ACTH","Iatrogenic steroids"],"a":3,"e":"Answer is D (Iatrogenic steroids): \"The most common cause of Cushing''s syndrome is Iatrogenic administration of steroids for a variety of reasons.\"","pyqMatches":[{"year":"2015","no":1140,"q":"The most common cause of Cushing''s syndrome is:","o":["Pituitary adenoma","Adrenal adenoma","Ectopic ACTH","Iatrogenic steroids"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2576, 'Medicine', 'Endocrinology', 'Easy', 'Internal_Medicine', 136, '{"id":2576,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":136,"q":"Intake of exogenous steroid causes:","o":["Addison''s disease","Cushing''s syndrome","Pheochromocytoma","Conn''s syndrome"],"a":1,"e":"Answer is B (Cushing''s syndrome): The most common cause of Cushing''s syndrome is iatragenic administration of steroids for a variety of reasons. - Harrison","pyqMatches":[{"year":"2012","no":554,"q":"Intake of exogenous steroid causes:","o":["Addison''s disease","Cushing''s syndrome","Pheochromocytoma","Conn''s syndrome"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2577, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 137, '{"id":2577,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":137,"q":"Most common cause of Addison''s Disease in India is:","o":["Autoimmune","Postpartum","HIV","Tuberculosis"],"a":3,"e":"Answer is D (Tuberculosis): ''The commonest cause of adrenal insufficiency (Addison''s disease) in underdeveloped countries is Tuberculosis","pyqMatches":[{"year":"2015","no":1143,"q":"Most common cause of Addison''s Disease in India is:","o":["Autoimmune","Postpartum","HIV","Tuberculosis"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2578, 'Medicine', 'Nephrology', 'Hard', 'Internal_Medicine', 138, '{"id":2578,"subject":"Medicine","chapter":"Nephrology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":138,"q":"Initial Drug of choice for suspected case of acute adrenal insufficiency is:","o":["Norepinephrine","Hydrocortisone","Dexamethasone","Fludrocortisones"],"a":2,"e":"Answer is C (Dexamethasone): The treatment of choice for acute adrenal insufficiency is Glucocorticoid Replacement Therapy. In cases where the diagnosis of acute adrenal insufficiency is suspected (not confirmed) Dexamethasone is preferred as the initial steroid of choice because Dexamethasone does not compete with the cortisol assay. Cosyntropin stimulation testing may be performed while the patient is on treatment.","pyqMatches":[{"year":"2012","no":1063,"q":"Initial Drug of choice for suspected case of acute adrenal insufficiency is:","o":["Norepinephrine","Hydrocortisone","Dexamethasone","Fludrocortisones"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2579, 'Medicine', 'Endocrinology', 'Hard', 'Internal_Medicine', 139, '{"id":2579,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":139,"q":"Nelson''s syndrome is most likely seen after:","o":["Hypophysectomy","Adrenalectomy","Thyroidectomy","Orchidectomy"],"a":1,"e":"The answer is B (Adrenalectomy): Adrenalectomy predisposes to the development of Nelson''s syndrome. Nelson syndrome Nelson syndrome is a disorder characterized by the rapid enlargement of a preexisting ACTH pituitary adenoma after adrenalectomy. This syndrome occurs because the following adrenalectomy, the suppressive effect of cortisol on ACTH secretion and tumor growth is removed resulting in increased ACTH secretion and tumor growth. Patients with Nelson''s syndrome present with hyperpigmentation and with the manifestation of an expanding intrasellar mass lesion (visual field defects, headache, cavernous sinus invasion, etc.) These tumors represent one of the most aggressive and rapidly growing of all pituitary tumors. ACTH levels are markedly elevated. Preoperative Radiotherapy may be indicated to prevent the development of Nelson''s syndrome after adrenalectomy.","pyqMatches":[{"year":"2013","no":1232,"q":"Nelson''s syndrome is most likely seen after:","o":["Hypophysectomy","Adrenalectomy","Thyroidectomy","Orchidectomy"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2580, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 140, '{"id":2580,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":140,"q":"Primary Hyperaldosteronism can be diagnosed by all of the following criteria, except:","o":["Diastolic Hypertension without edema","Hyperaldosteronism which is not supressed by volume expansion","Low Plasma Renin Activity","Metabolic Acidosis"],"a":3,"e":"Answer is D (Metabolic Acidosis) Class,Triad of Biochemical Criteria for diagnosis of Primary Hyperaldoteronism Hypokalemia with inappropriate kaliuresis (Metabolic alkalosis) Suppressed plasma renin activity Elevated Aldosterone levels that do not fall appropriately in response to volume expansion or sodium load Taken from Manual of Endocrinology & Metabolism 41h/150","pyqMatches":[{"year":"2015","no":1142,"q":"Primary Hyperaldosteronism can be diagnosed by all of the following criteria, except:","o":["Diastolic Hypertension without edema","Hyperaldosteronism which is not supressed by volume expansion","Low Plasma Renin Activity","Metabolic Acidosis"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2581, 'Medicine', 'Endocrinology', 'Moderate', 'Internal_Medicine', 141, '{"id":2581,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":141,"q":"Primary hyperparathyroidism is suggested by all of the following, except:","o":["Increased serum calcium","Low urinary calcium","Increased PTH","Increased C-AMP"],"a":1,"e":"Answer is B (Low Urinary Calcium): Primary Hyperparathyroidism is associated with normal or increased urinary calcium levels. Increased PTH and Increased Serum calcium in association with high levels of urinary calcium suggest a diagnosis of Primary Hyperparathyroidism Increased PTH and Increased Serum calcium in association with low levels of urinary calcium suggest a diagnosis of Familial Hvpocalciuric Hvpercalcemia (FHH) Disorder S- Ca2± S- PHOSIntact PTH PTHrPUrine Calcium Urinary Ca2+ Creatinine Clearance ratio Primary HPTH1'' sl, (or N) 1'' (or N) ,I, U-Ca2'' > 100mg/24h >0.02 Familial benign hypercalcemia l'' .I(or N) 1'' (or N) ,I, U-Ca2+ <100mg/24h <0.01 This clearance ratio is calculated from simultaneous fasting serum and urine Ca and creatinine measurements The urine sample can and urine Ca and creatinine measurements. The urine sample can be from a spot or a 24 h collection. The clearance ratio is calculated as follows: Urine Ca (mg/24h)x plasma creatinine (mg/dl )/plasma Ca (mg/dL) x urine creatinine (mg/24h)","pyqMatches":[{"year":"2012","no":1068,"q":"Primary hyperparathyroidism is suggested by all of the following, except:","o":["Increased serum calcium","Low urinary calcium","Increased PTH","Increased C-AMP"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2582, 'Medicine', 'Endocrinology', 'Easy', 'Internal_Medicine', 142, '{"id":2582,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":142,"q":"Hypophosphatemia is seen in:","o":["Pseudohypoparathyroidism","Hyperparathyroidism","Hyperthyroidism","Hypoparathyroidism"],"a":1,"e":"Answer is B (Hyperparathyroidism): Hyperparathyroidism is typically associated with hypophosphatemia. Primary Hyperparathyroidism is associated with Hypophosphatemia and Hypercalcemia while Secondary Hyperparathyroidism is associated with Hypophosphatemia and Hypocalcemia. Hyperthyroidism is typical associated with normal phosphate levels Hypoparathyroidism and Pseudohypoparathyroidism are associated with Hyperphosphatemia","pyqMatches":[{"year":"2012","no":1072,"q":"Hypophosphatemia is seen in:","o":["Pseudohypoparathyroidism","Hyperparathyroidism","Hyperthyroidism","Hypoparathyroidism"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2583, 'Medicine', 'Respiratory Medicine', 'Moderate', 'Internal_Medicine', 143, '{"id":2583,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":143,"q":"Granulomatous condition causing hypercalcemia include all of the following, except:","o":["TB","Sarciodosis","Berylliosis","SLE"],"a":3,"e":"Answer is D (SLE): SLE is not classified as a granulomatous disease and is a rare cause of Hypercalcemia (Disseminated SLE). Sarcoidosis, Tuberculosis (TB) and Berylliosis are typical Granulomatous disorders causing hypercalcemia. Granulomatous causes of Hypercalcemia Infective Causes Tuberculosis Berylliosis Histoplasmosis Coccidoimycosis Pneumocystis Granulomatous Leprosy Cat-Scratch Disease Non-Infective Cause Sarcoidosis (Most common) Wegner''s Granulomatosis Inflammatory Bowel Disease Histiocytosis-X Foreign body Granulomas Almost every single disease associated with Granuloma formation has been reported to cause Hypercalcemia","pyqMatches":[{"year":"2012","no":1071,"q":"Granulomatous condition causing hypercalcemia include all of the following, except:","o":["TB","Sarciodosis","Berylliosis","SLE"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2584, 'Medicine', 'Endocrinology', 'Moderate', 'Internal_Medicine', 144, '{"id":2584,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":144,"q":"Osteoporosis is seen in all the following except","o":["Thyrotoxicosis","Rheumatoid arthritis","Hypoparathyroidism","Steroid therapy"],"a":2,"e":"Answer is C (Hypoparathyroidism) : Osteoporosis as associated with lzyperparathyroidism (not hypoparathyroidism). DISEASES ASSOCIATED WITH AN INCREASED RISK OF GENERALIZED OSTEOPOROSIS IN ADULTS : Hypogonadal States Nutritional and gastrointestinal disorders Turner Syndrome Malnutrition Klinefelter syndrome Parenteral nutrition Anorexia nervosa Malabsorption syndromes Hypothalmic amenorrhea Gastrectomy Other primary or secondary hypogonadal states Severe liver disease, especially biliary cirrhosis Pernicious anemia Endocrine disorders Hematologic disorders / Malignancy Cushing''s syndrome Multiple disorders/malignancy Hyperparathyroidism Lymphoma and leukemia Thyrotoxicosis Malignancy-associated parathyroid hormone - related (PTHrP) Insulin-dependent diabetes mellitus production Acromegaly Mastocytosis Adrenal insufficiency Hemophilia Thalassemia Selected inherited & Rheumatologic disorders Miscellaneous Osteogenesis imperfectaQ ImmobilizationQ Marfan syndromeQ Chronic obstructive pulmonary disease Hemochromatosis Pregnancy and lactation HypophosphatasiaQ Scoliosis Glycogen storage diseases Multiple sclerosis HomocystinuriaQ Sarcoidosis Ehlers-Danlos syndrome Amyloidosis Porphyria Alcoholism Menkes'' syndrome Epidermolysis bullosa Rheumatoid arthritis DRUGS ASSOCIATED WITH AN INCREASED RISK OF GENERALIZED OSTEOPOROSIS IN ADULTS : Glucocorticoids2 CyclosporineQ Cytotoxic drugs Anticonvulsants Excessive alcohol Excessive thyroxin Aluminium Gonadotropin-releasing hormone agonistsQ Heparin Lithium","pyqMatches":[{"year":"2016","no":1461,"q":"Osteoporosis is seen in all the following except","o":["Thyrotoxicosis","Rheumatoid arthritis","Hypoparathyroidism","Steroid therapy"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2585, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 145, '{"id":2585,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":145,"q":"Features of tumor lysis syndrome are:","o":["Hypocalcemia","Hypophosphatemia","Alkalosis","Hypokalemia"],"a":0,"e":"Answer is A (Hypocalcemia): Tumor Lysis syndrome is associated with Hypocalcemia. Tumor Lysis Syndrome is also associated with Hyperphosphatemia, Hyperkalemia and Acidosis.","pyqMatches":[{"year":"2013","no":1322,"q":"Features of tumor lysis syndrome are:","o":["Hypocalcemia","Hypophosphatemia","Alkalosis","Hypokalemia"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2586, 'Medicine', 'Endocrinology', 'Moderate', 'Internal_Medicine', 146, '{"id":2586,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":146,"q":"A pregnancy woman is diagnosed to suffering from Graves'' disease. The most appropriate therapy for her would be:","o":["Radioiodine therapy","Total thyroidectomy","Carbimazole parenteral","Propylthiouracil oral"],"a":3,"e":"Answer is D (Propylthiouracil): Propylthiouracil (PTU) is not associated with an increased risk of congenital malformations and is considered the drug of choice for treating hyperthyroidism is Pregnancy. Hyperthyroidism in Pregnancy Maternal Hyperthyroidism in Pregnancy is usually due to Grave''s Disease. TRAb crosses the placenta and if mother is thyrotoxic it must be assumed that the foetus is similarly affected The treatment of choice for thyrotoxicosis in Pregnancy is therapy with safe Antithyroid Drugs Thionamides (Carbimazole/Propylthiouracil) are equally effective in controlling Grave''s Hyperthyroidism in Pregnancy and are considered the drugs of choice. Amongst Carbimazole (Methimazole) and Propylthiouracil, Propylthiouracil is typically the preferred agent (Traditional drug of choice) Radioactive Iodine Therapy is contraindicated in pregnancy as it may destroy the fetal thyroid Thyroidectomy (Surgery) is rarely required during Pregnancy. When indicated preoperative treatment with antithyroid drugs and iodine is undertaken and surgery is performed during the second trimester Propylthiouracil Effective in controlling Grave''s Hyperthyroidism in Pregnancy Not associated with increased risk of congenital malformation (Aplasia Cutis Congenita has not reported with the use of Propylthiouracil)) Considered the drug of choice for treatment of Hyperthyroidism in pregnancy Considered the drug of choice for mothers during Breast feeding (Transferred to the milk one tenth as much as Carbimazole) Effective in controlling Grave''s Hyperthyroidism in Pregnancy Aplasia Cutis Congenita is a rare disorder reported in neonates of mothers who received Methimazole (Carbimazole) during pregnancy. (Consensus: Insufficient data to establish a direct causal relationship) Considered as an effective alternative where Propylthiouracil is not available or cannot be used for any reason May be used in mothers during breast feeding at a low dose (Transferred to milk more than Propylthiouracil but usually does not adversely affect the infant''s thyroid function)","pyqMatches":[{"year":"2012","no":1064,"q":"A pregnancy woman is diagnosed to suffering from Graves'' disease. The most appropriate therapy for her would be:","o":["Radioiodine therapy","Total thyroidectomy","Carbimazole parenteral","Propylthiouracil oral"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2587, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 147, '{"id":2587,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":147,"q":"Investigation of choice in pheochromocytoma is:","o":["CT scan","Urinary catecholamines","MIBG scan","MRI Scan"],"a":1,"e":"Answer is B (Urinary Catecholamines): Pheochromocytomas synthesize and store catecholamines which include norepinephrine, epinephrine and dopamine. The investigation of choice for diagnosis of Pheochromocytomas is determination of elevated levels of catecholamines and their methylated metabolites (metanephrines) in the plasma and urine. CT scan, MRI and MBIG Scintography are all useful diagnostic modalities for localization of pheochromocytoma once the diagnosis is established.","pyqMatches":[{"year":"2012","no":1066,"q":"Investigation of choice in pheochromocytoma is:","o":["CT scan","Urinary catecholamines","MIBG scan","MRI Scan"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2588, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 148, '{"id":2588,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":148,"q":"The predominant symptom/sign of pheochromocytoma is:","o":["Sweating","Weight loss","Orthostatic hypotension","Episodic hypertension"],"a":3,"e":"Answer is D (Episodic Hypertension): The predominant manifestation of Pheochromocytoma is Hypertension which classically presents as Episodic Hypertension (Sustained Hypertension and Orthostatic Hypotension may also be seen). ''The dominant sign is Hypertension. Classically patients have episodic hypertension, but sustained hypertension is also common'' - Harrison","pyqMatches":[{"year":"2012","no":1067,"q":"The predominant symptom/sign of pheochromocytoma is:","o":["Sweating","Weight loss","Orthostatic hypotension","Episodic hypertension"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2589, 'Medicine', 'Miscellaneous', 'Hard', 'Internal_Medicine', 149, '{"id":2589,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Internal_Medicine","sourceNo":149,"q":"The gold standard test for diagnosis of Insulinoma is:","o":["''72 hour'' fast test","Plasma Glucose levels < 3 mmol/l","Plasma Insulin levels > 6µU/ml","C- peptide levels < 50 p mol/e"],"a":0,"e":"The answer is A (''72 hour'' fast test): The Gold standard test for diagnosis of Insulinoma is a supervised ''72 hour fast'' test Diagnosis of insulinoma requires demonstration of inappropriately high levels of plasma Insulin ( and C- peptide) in the presence of documented hypoglycemia (Achieved by 72-hour fast test). Absolute values of Insulin or C- peptide are not reliable in establishing a diagnosis unless hypoglycemia is documented The ''72 hour fast test'' allows demonstration of hypoglycemia, together will elevated levels of Insulin and C-peptide and thus becomes the most reliable – gold standard test for establishing a diagnosis of Insulinoma Diagnosis of Insulinoma: ''72 hour fast'' test The diagnosis of Insulinoma requires the demonstration of an inappropriately elevated plasma insulin (and C-peptide) at the time of hypoglycemia. The ''72 hour fast'' test involves supervised fasting for up to 72 hours or until hypoglycemia can be documented. The test is considered positive if at any time when blood glucose levels drop to < 2.2mmo1/1 (40 mg/dl), the serum insulin levels are recorded to be greater than 6µU/ml. (and C- peptide levels > 100 pmo1/1) Studies indicate that 100% of patients with insulinoma will be detected after a supervised 72 hour fast and hence this test is considered the gold standard test. First 24 hours: 70-80% of patients with insulinoma can be detected Up to 48 hours: 98% of patients with insulinoma can be detected By 72 hours: 100% of patients with insulinoma can he detected","pyqMatches":[{"year":"2016","no":1149,"q":"The gold standard test for diagnosis of Insulinoma is:","o":["''72 hour'' fast test","Plasma Glucose levels < 3 mmol/l","Plasma Insulin levels > 6µU/ml","C- peptide levels < 50 p mol/e"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2590, 'Medicine', 'Miscellaneous', 'Hard', 'Internal_Medicine', 150, '{"id":2590,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Internal_Medicine","sourceNo":150,"q":"Diagnosis of carcinoid tumour is done Urinary estimation of:","o":["VMA","Metanephrines","Catecholamines","5HIAA"],"a":3,"e":"Answer is D (5HIAA): Carcinoid Tumors Carcinoid tumors are associated with elevated levels of metabolites of Tryptophan/ serotonin which include 5HIAA, 5HT and5HTP. Pheochromocytomas Pheochromocytomas are associated with elevated levels of catecholamines and their metabolites which include Vanillylmandelic acid (VMA)and metanephrines The diagnosis of Typical carcinoid syndrome is suggested by elevated levels of 5HIAA The diagnosis of Atypical Carcinoid Syndrome is suggested by elevated levels of 5HTP. established by elevated levels of 5HIAA.","pyqMatches":[{"year":"2012","no":1036,"q":"Diagnosis of carcinoid tumour is done Urinary estimation of:","o":["VMA","Metanephrines","Catecholamines","5HIAA"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2591, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 151, '{"id":2591,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":151,"q":"Carcinoid syndrome produces valvular disease primarily of the","o":["Venous valves","Tricuspid valve","Mitral valve","Aortic valve"],"a":1,"e":"Answer is B (Tricuspid valve); The most common site of involvement is the – Ventricular surface of Tricuspid valve. ''Cardiac manifestations in carcinoid syndrome are due to fibrosis involving the endocardium, primarily on the right side although left side lesions also occur. Dense fibrous deposits are most commonly on the ventricular aspect of the tricuspid valve and less commonly on the pulmonary valve cusps.'' They can result in either constriction of valves (stenosis) or fixation of valves in open (regurgitation) - Abnormality produced due to tricuspid valve involvement – Tricuspid regurgitation Q - Abnormality produced due to pulmonary valve involvement – Pulmonary stenosis Q","pyqMatches":[{"year":"2014","no":459,"q":"Carcinoid syndrome produces valvular disease primarily of the","o":["Venous valves","Tricuspid valve","Mitral valve","Aortic valve"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2592, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 152, '{"id":2592,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":152,"q":"Most common cause of chronic granulomatous disease in children is:","o":["Myeloperoxidase deficiency","Defective phagocytosis","Defective H2O2 production","Job''s disease"],"a":2,"e":"Answer is C (Defective H2O2 production) Chronic granulomatous disease is a ''disorder'' of microbial killing'' characterized by decreased ability of neutrophils to produce H4)-Q Chronic granulomatous disease is a ''disorder'' of microbial killing'' charac decreased ability of neutrophils to produce H,O2.Q Patients, here becom susceptible to disease caused by organisms that produce `catalase'', wh the small amount of H2O, present in these cells and leads to failure of b killing. The disease is called so, because granulomas, are formed in various tis second line defence against organisms, that normally would be remove acute inflammatory response. Manifestations: Recurrent infections with which catalase +ve Pyogenic bacteria e.g. sta Q - catalase negative bacteria e.g. streptococcus, Pneumococcus are ofte normally.Q Normal humoral immune response? but Defective killing process: Leucocytes are unable to kill bacteria after ph the major reason being decreased production of H-O2.Q Screening method: NBT test: Nitroblue retrazolium dye is not reduced by neutrophils in vitro","pyqMatches":[{"year":"2016","no":371,"q":"Most common cause of chronic granulomatous disease in children is:","o":["Myeloperoxidase deficiency","Defective phagocytosis","Defective H2O2 production","Job''s disease"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2593, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 153, '{"id":2593,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":153,"q":"In Turner''s syndrome which of the following is NOT seen :","o":["Short stature","Widely spaced nipple","Webbed neck","Mental retardation"],"a":3,"e":"Answer is D (Mental retardation): Mental retardation is seen in Down & Klinefelter''s syndrome but not in Turner''s syndrome. All other features mentioned as options may be seen in Turner''s syndrome.","pyqMatches":[{"year":"2016","no":1391,"q":"In Turner''s syndrome which of the following is NOT seen :","o":["Short stature","Widely spaced nipple","Webbed neck","Mental retardation"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2594, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 154, '{"id":2594,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":154,"q":"Broca''s aphasia is?","o":["Fluent aphasia","Non fluent aphasia","Sensory aphasia","Conduction aphasia"],"a":1,"e":"Answer is B (Non-fluent Aphasia): Broca''s Aphasia is a Non-Fluent Expressive (Motor) Aphasia with preserved comprehension and impaired repetition","pyqMatches":[{"year":"2014","no":1258,"q":"Broca''s aphasia is?","o":["Fluent aphasia","Non fluent aphasia","Sensory aphasia","Conduction aphasia"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2595, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 155, '{"id":2595,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":155,"q":"All of the following are Fluent Aphasia''s Except:","o":["Anomie Aphasia","Wernicke''s Aphasia","Conduction Aphasia","Broca''s Aphasia"],"a":3,"e":"Answer is D (Broca''s Aphasia): Neurologic Differential Diagnosis: A Case-Based Approach (Cambridge University Press, 2014)/ 36 Broca''s Aphasia is a Non-Fluent Expressive (Motor) Aphasia with preserved comprehension and impaired repetition. Non-Fluent Aphasias Global Broca''s Mixed Transcortical Transcortical Motor Fluent Aphasias Anomie Wernicke''s Conduction Transcortical Sensory","pyqMatches":[{"year":"2014","no":1259,"q":"All of the following are Fluent Aphasia''s Except:","o":["Anomie Aphasia","Wernicke''s Aphasia","Conduction Aphasia","Broca''s Aphasia"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2596, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 156, '{"id":2596,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":156,"q":"Fluent Aphasia with preserved comprehension and impaired repetition is:","o":["Broca''s","Wernicke''s","Anomie","Conduction"],"a":3,"e":"Answer is D (conduction): Conduction Aphasia is a ''Fluent'' Aphasia with preserved comprehension and impaired Repetition. Clinical Syndrome Non-Fluent Aphasias Fluent Aphas''as Features TranscorticalMotor Wernicke''sTranscor Sensory Fluent NoNo No NoYesYesYes Yes ComprehensionNoNo Yes YesYesYesNo No Repeat NoYes Yes NoYes NoNo Yes","pyqMatches":[{"year":"2014","no":1261,"q":"Fluent Aphasia with preserved comprehension and impaired repetition is:","o":["Broca''s","Wernicke''s","Anomie","Conduction"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2597, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 157, '{"id":2597,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":157,"q":"Involvement of pyramidal tract leads to all of the following except","o":["Spasticity","Fasciculation","Hyper-reflexia","Positive Babinski sign"],"a":1,"e":"Answer is B (Fasciculation): Fasciculations are a feature of Lower Motor Neuron Lesions. Involvement of Pyramidal tract indicates an Upper Motor Neuron Lesion. Hypertonia with Spasticity, Hyper-reflexia and a Positive Babinski Sign with an Extensor Planter response are all features of an upper motor neuron lesion (Pyramidal Tract Lesion).","pyqMatches":[{"year":"2014","no":1310,"q":"Involvement of pyramidal tract leads to all of the following except","o":["Spasticity","Fasciculation","Hyper-reflexia","Positive Babinski sign"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2598, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 158, '{"id":2598,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":158,"q":"The following are components of Brown Sequard syndrome except :","o":["Ipsilateral extensor plantar response","Ipsilateral pyramidal tract involvement","Contralateral spinothalamic tract involvement","Contralateral posterior column involvement"],"a":3,"e":"Answer is D (Contralateral posterior column involvement): Brown – Sequard syndrome or hemisection of the spinal cord leads to loss of joint position and vibratory sense (posterior coluntn movement) on the ipsilateral side and not on the contralateral side. – Harrison 16th / 2441, 144 Brown sequard syndrome: Hemisection of spinal cord Ipsilateral involvement of corticospinal tract : ipsilateral loss of motor power. Ipsilateral involvement of posterior column : ipsilateral loss of joint position and vibratory sense. Contralateral involvement of spinothalamic tract : contralateral loss of joint position and vibratory sense. Segmental signs such as radicular pain muscle atrophy or loss of deep tendon reflexes arc unilateral (Lower motor neuron signs at level of lesion).","pyqMatches":[{"year":"2015","no":1165,"q":"The following are components of Brown Sequard syndrome except :","o":["Ipsilateral extensor plantar response","Ipsilateral pyramidal tract involvement","Contralateral spinothalamic tract involvement","Contralateral posterior column involvement"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2599, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 159, '{"id":2599,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":159,"q":"Early loss of bladder control is seen in","o":["Conus Medullaris","Cauda Equina","Gullain Barre Syndrome","Amyotrophic Lateral Sclerosis"],"a":0,"e":"Answer is A (Conus Medullaris): Harrison''s 18th Loss of bladder control is an early and marked feature of conus medullaris. Feature Conus Medullaris Cauda Equina syndrome GBS AMLS Bladder Early and Marked Late and less marked Uncommon Absent /uncommon Involvement ''Bladder dysfunction is ''Bladder involvement is a ''If bladder dysfunction a ''Even in late stages of a prominent feature and late presentation in cauda- prominent feature and comes the illness bowel and comes early in the equina syndrome early in the course, diagnostic bladder functions are course of disease'' possibilities other than GBS should be preserved'' considered","pyqMatches":[{"year":"2014","no":1349,"q":"Early loss of bladder control is seen in","o":["Conus Medullaris","Cauda Equina","Gullain Barre Syndrome","Amyotrophic Lateral Sclerosis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2600, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 160, '{"id":2600,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":160,"q":"Most common cause of embolic stroke is?","o":["Intra-Cardiac Thrombi","Particulate Matter From IV Drug Injections","Protein C deficiency","Antiphospholipid syndrome"],"a":0,"e":"Answer is A (Intracardiac Thrombi): The most common cause of embolic strokes are Intro-cardiac Thrombi. The most common sources of systemic embolism and embolic stroke are Intra-cardiac thrombi formed as a result of atrial fibrillation, ST- elevation MI, left ventricular dysfunction or heart failure. Atrial Fibrillation is the single most important predisposing factor (Atrial Thrombus) followed by Myocardial Infarction (Left Ventricular Thrombus).","pyqMatches":[{"year":"2014","no":1382,"q":"Most common cause of embolic stroke is?","o":["Intra-Cardiac Thrombi","Particulate Matter From IV Drug Injections","Protein C deficiency","Antiphospholipid syndrome"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2601, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 161, '{"id":2601,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":161,"q":"The common cause of subarachnoid hemorrhage is:","o":["Arterio-venous malformation","Cavernous angioma","Aneurysm","Hypertension"],"a":2,"e":"Answer is C (Aneurysm): `The most common cause of subarachnoid haemorrhage is rupture of a saccular aneurysm (excluding head trauma)'' – Harrison. Previously asked frequently as follows: (Excluding hand trauma) Most common cause of subarachnoid haemorrhage is rupture of a saccular aneurysmQ Most common cause of subarachnoid haemorrhage is rupture of a Berry aneurysmQ Most common cause of subarachnoid haemorrhage is rupture of ''Circle of Willis'' aneurysmQ. (Saccular aneurysms are synonymous with Berry Aneurysms and most commonly occur in the anterior circulation on the Circle of Willis).","pyqMatches":[{"year":"2013","no":1288,"q":"The common cause of subarachnoid hemorrhage is:","o":["Arterio-venous malformation","Cavernous angioma","Aneurysm","Hypertension"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2602, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 162, '{"id":2602,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":162,"q":"Lateral medullary syndrome is caused by thrombosis of:","o":["Anterior inferior cerebral artery","Posterior inferior cerebellar artery","Vertebral artery","b and c"],"a":3,"e":"Answer is C > B (Vertebral artery > Posterior inferior cerebellar artery): `Most cases result from ipsilateral vertebral artery occlusion; in the reminder occlusion of posterior inferior cerebellar artery is responsible'' – Harrison Vessel occlusion that result in Lateral Medullary syndrome: - Vertebral (most common) - Posterior inferior cerebellar (2nd most common) - Superior, middle or Inferior lateral medullary arteries Vertebral artery The vertebral artery consists of four segments. The fourth segment courses upward to joint the other vertebral artery to form the basilar artery. Only this segment gives rise to branches that supply the brainstem and cerebellum. Embolic occlusion or thrombosis of the fourth segment is responsible for this syndrome Q Posterior inferior cerebellar artery Posterior inferior cerebellar artery in its proximal part supplies the lateral medulla and in its distal branches the inferior surface of cerebellum.","pyqMatches":[{"year":"2012","no":1044,"q":"Lateral medullary syndrome is caused by thrombosis of:","o":["Anterior inferior cerebral artery","Posterior inferior cerebellar artery","Vertebral artery","b and c"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2603, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 163, '{"id":2603,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":163,"q":"Which of the following statements about the pathology in Alzheimer''s disease is not true:","o":["Neuritic Plaques are formed of amyloid protein","Neurofibrillary tangles (NFT) are made of tau protein","NFTs appear extracellularly before intracellular appearance","Number of NFTs correlates with dementia"],"a":2,"e":"Answer is C (NFTs appear extracellularly before intracellular appearance): NFTs are typically seen intracellularly within the soma and proximal dendrites of neurons. Neurofibrillary Tangles (NFTs) are intracellular accumulations of hyperphosphorylated ''tau'' proteins. Neurofibrillary Tangles are Intracellular Accumulations Neurofibrillary Tangles are intracellular accumulations of hyperphosphorylated microtubule binding protein ''tau''. Paired helical filaments of tau protein (NFTs) form intracellularly within the soma and proximal dendrites of neurons. These cytoskeletal protein tangles (NFTs), initially impede cellular metabolism and axosplasmic transport leading to impaired synaptic function and eventually to neuronal death. These neurofibrillaty tangles may be seen as extracellular tangles after degeneration of the neuron as evidence of the neuronal cell''s demise Neurofibrillary Tangles are intracellular accumulations that may appear extracellularly alter degeneration of neuron (neuronal death) Histopathological Hallmarks of Alzheimer''s Disease Amyloid Plaques (Extracellular) Amyloid Neuritic Plaques are formed by extracellular accumulation of beta amyloid deposits within the neutropil ''Neuritic'' or ''Senile'' I3-amyloid plaques are an early histopathological sign of Alzheimer''s disease (that occur rarely in healthy subjects) The amyloid 13-protein accumulated in single neuritic plaques is toxic to surrounding structures and adjacent neurons. Clinicopathological studies have shown that amy/aid burden does not directly correlate with severity or duration of dementia. Neurofibrillary Tangles (Intracellular) Neurofibrillary tangles arc formed by intracellular accumulation of hyperphosphorylated microtubule binding protein ''tau''. NFT''s occur in many neurodegenerative diseases and /or a group of diseases called laupathies''. These include Frontotemporal dementia, Pick''s disease etc. The cooccurance of fi-amyloid plaques with NFT''s suggests a diagnosis of AD. The NFT''s are toxic to the neurons and neurons with NFT''s eventually die and degenerate leaving a residual `ghost tangle'', in the extracellular space reminding of the pyramidal cell body in which it was initially formed. Clinicopathological studies have shown that dementia correlates more strongly with NFT''s than with senile plaques (3-amyloid)","pyqMatches":[{"year":"2016","no":484,"q":"Which of the following statements about the pathology in Alzheimer''s disease is not true:","o":["Neuritic Plaques are formed of amyloid protein","Neurofibrillary tangles (NFT) are made of tau protein","NFTs appear extracellularly before intracellular appearance","Number of NFTs correlates with dementia"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2604, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 164, '{"id":2604,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":164,"q":"Which of the following metal ions is associated with secondary Parkinsonisms:","o":["Mangnese (Mn)","Magnesium (Mg)","Selenium (Se)","Molybednum (Me)"],"a":0,"e":"Answer is A (Mangnese (Mn)): Manganese ion exposure is implicated in the free radical damage of the basal ganglia causing Parkinsonism. Toxins Implicated in Parkinsonism (Harrison) Manganese (Mn) MPTP (1 Methyl - > Phenyl –1, 2, 3, 6 tetrahydropyridine) Carbonmonoxide Carbondisulphide Ctanide Hexane Methanol Toxins reported to induce Parkinonism: (Handbook of Atypical Parkinsonism) Betel nut (plus antiPsychotics) Carbon monoxide Contrast agent for cardiac catheterization Cyanide Ethanol intoxication, ethanol withdrawal Ethylene glycol Herbicides (paraquat, diquat, glyphosate) Heroin Hydrogen sulfide Kava-kava Manganese Maneb (Manganese Ethylene-Bis-Dithiocarbamate) Mercury Methanol Methcathinone (manganese ephedrone) MPTP (I-methyl-4-phenyl-1,2,3,6-tetrahydropyridine) Organic solvents (carbon disulfide, n-hexane, toluene, trichloroethylene) Organophosphate insecticide poisoning Petroleum products","pyqMatches":[{"year":"2015","no":1167,"q":"Which of the following metal ions is associated with secondary Parkinsonisms:","o":["Mangnese (Mn)","Magnesium (Mg)","Selenium (Se)","Molybednum (Me)"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2605, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 165, '{"id":2605,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":165,"q":"Which of the following sites is responsible for the amnestic defect in Wernicke''s Korsakoff syndrome:","o":["Mamillary body","Thalamus","Periventricular Grey matter","Hippocampus"],"a":1,"e":"Answer is B (Thalamus): The Amnestic effect in Wernicke''s Korsakoff Syndrome is related to lesions in the dorso-medial nuclei of the thalamus. `Lesions in the dorsomedial nucleus of the thalamus seem to be the best correlate of the memory disturbance and confabulation'' - Robbins","pyqMatches":[{"year":"2015","no":1160,"q":"Which of the following sites is responsible for the amnestic defect in Wernicke''s Korsakoff syndrome:","o":["Mamillary body","Thalamus","Periventricular Grey matter","Hippocampus"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2606, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 166, '{"id":2606,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":166,"q":"In children most common posterior fossa tumour is:","o":["Meningiomas","Astrocytoma","Medulloblastoma","Glioblastoma multiforme"],"a":1,"e":"Answer is B (Astrocytoma): Cerebellar Astrocytomas are the most common posterior .fossa tumors in children. Medulloblastoma are the second most common posterior fossa tumors in children and the most common malignant posterior fossa tumors in children. Although CPDT and Nelson''s textbook mention an equal incidence of cerebellar astrocytoma and medulloblastoma in the posterior fossa in children, most other standard textbooks mention cerebellar astrocytomas as the most common posterior fossa tumors in children.","pyqMatches":[{"year":"2013","no":1470,"q":"In children most common posterior fossa tumour is:","o":["Meningiomas","Astrocytoma","Medulloblastoma","Glioblastoma multiforme"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2607, 'Medicine', 'Endocrinology', 'Moderate', 'Internal_Medicine', 167, '{"id":2607,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":167,"q":"All the following are true of Craniopharyngioma except","o":["Derived from Rathke''s pouch","Contains epithelial cells","Present in sella or infra-sellar location","Causes visual disturbances"],"a":2,"e":"Answer is C (Present in sella or infrasellar location): Some of these lesions arise from the sella, but most are suprasellar Q (Not infra-sellar). They arise from near the pituitary stalk and commonly extend into the supra sellar cistern. Craniopharyngiomas arise from Rathke''s pouch and constitute 3-5% of all intracranial neoplasms. Some of these lesions arise from the sella, but most are suprasellar Q (Not infra-sellar). They arise from near the pituitary stalk and commonly extend into the supra sellar cistern. Consists of nests of cords of stratified squamous or columnar epithelium embedded in a spongy reticulum — Robbins 61h/1129 Visual complaints are the presenting feature in about 80% of adults and 60% of children.","pyqMatches":[{"year":"2013","no":1418,"q":"All the following are true of Craniopharyngioma except","o":["Derived from Rathke''s pouch","Contains epithelial cells","Present in sella or infra-sellar location","Causes visual disturbances"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2608, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 168, '{"id":2608,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":168,"q":"Predominantly sensory neuropathy is/are caused by:","o":["Cisplatin","Pyridoxine excess","Suramin","a and b"],"a":3,"e":"Answer is A and B (Cisplatin and Pyridoxine excess): Cisplatin and Pyridoxine are associated with predominantly sensory neuropathies.","pyqMatches":[{"year":"2012","no":1047,"q":"Predominantly sensory neuropathy is/are caused by:","o":["Cisplatin","Pyridoxine excess","Suramin","a and b"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2609, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 169, '{"id":2609,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":169,"q":"Which one of the following is correct regarding Eaton-Lambert syndrome-","o":["It commonly affects the ocular muscle","Neostigmine is the drug of choice for this syndrome","Repeated electrical stimulation enhances muscle power in it.","It is commonly associated with adenocarcinoma of lung"],"a":2,"e":"Answer is C (Repeated electrical stimulation enhances muscle power): ''Patients with Lambert – Eaten myaethenic syndrome show incremental rather than decremental response on repeated nerve stimulation'' – Harrison 17th/2674 ''Muscle response to stimulation of its motor nerve increases remarkably if nerve is stimulated repeatedly even in muscles that are clinically weak'' - CMDT Lambert Eaten Myasthenia Syndrome commonly involves proximal limb muscles and muscles of trunk Extraocular muscles are the most commonly involved in Myaesthenia Gravis and not in Lambert Eaten Myasthenia Syndrome Neostigmine is not considered the drug of choice Plasmapharesis and immunosuppression form mainstay of treatment 3, 4 Diaminopyridine is the drug of choice for enhancement of neuromuscular transmission. Pyridostigmine (or Neostigmine) may be sympatomatically helpful but their response is variable – Harrison & CMDT Lambert Eaten Myasthenia Syndrome is associated with small cell carcinoma of lung Lambert Eaten Myasthenia Syndrome is associated with small cell carcinoma of lung and not adenocarcinoma","pyqMatches":[{"year":"2015","no":1164,"q":"Which one of the following is correct regarding Eaton-Lambert syndrome","o":["It commonly affects the ocular muscle","Neostigmine is the drug of choice for this syndrome","Repeated electrical stimulation enhances muscle power in it.","It is commonly associated with adenocarcinoma of lung"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2610, 'Medicine', 'Dermatology & Allergy', 'Moderate', 'Internal_Medicine', 170, '{"id":2610,"subject":"Medicine","chapter":"Dermatology & Allergy","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":170,"q":"All of the following are feature of dermatomyositis, Except:","o":["Salmon Patch","Gottron''s patch","Mechanic finger","Periungual telengiectasias"],"a":0,"e":"Answer is A (Salmon Patch): Salmon patch is not a feature of dermatomyositis. Cutaneous features of dermatomvositis Cutaneous feature Description Heliotrope Rash° Periocular or facial erythema and edema with pink/purple /blue (heliotrope) hue (blue purple discoloration on upper eve lids with edema) Gottren''s PapulesQ (Gottren''s sign) Violaceous papules over the knuckles Erythema of the knuckles with a raised violaceous scaly eruption Ervthematous rash over other body surfaces such as anterior chest (often in a V form) `V'' sign Shawl sign Erythematous rash over other body surfaces including the upper trunk, neck, back & shoulders (shawl pattern) Periungual Telengiectasiase Dilated capillary loops at the base offingernails Mechanic''s Irregular, thickened, distorted cuticles, with rough handsQ and cracked areas over the lateral and palmar areas offingers with irregular dirty horizontal lines resembling mechanic ''s hand. Calcinosis Cutise Presence of hard calcium deposits in the skin","pyqMatches":[{"year":"2012","no":1382,"q":"All of the following are feature of dermatomyositis, Except:","o":["Salmon Patch","Gottron''s patch","Mechanic finger","Periungual telengiectasias"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2611, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 171, '{"id":2611,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":171,"q":"Best prognostic factor for head injury is :","o":["Glasgow coma scale","Age","Mode of injury","CT"],"a":0,"e":"Answer is A (Glasgow coma scale): Amongst the option provided GCS is the single best answer of choice. Determining the patient prognosis after TBI (Traumatic Brain Injury) is difficult and complex. Several independent variables have been identified that correlate with severity. Most studies have indicated Glasgow Coma Scale in the field and at arrival at the emergency department as a highly predictive indicator of prognosis. Harrison 17th / 2601 In severe head injury eye opening, the best motor response and verbal output have been found to be roughly predictive of outcome. There have been summarized using the Glasgow coma scale. Coma score = E + M + V Patient scoring 3 or 4 have an 85% chance of dying or remaining vegetative. Patients scoring 11 or above have only a 5 — 10% chance of dying or remaining vegetative. Intermediate scores correlate with proportional chances of recovery. Other Poor prognosis indicators : Harrison •Older age •CT evidence of compression of i / idli hif Older age cisterns / midline shift •Increase ICP •Delayed evacuation of large intracerebral hemorrhage •Hypoxia & Hypotension •Carrier status for apolipoprotein E-4 allele","pyqMatches":[{"year":"2013","no":1343,"q":"Best prognostic factor for head injury is :","o":["Glasgow coma scale","Age","Mode of injury","CT"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2612, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 172, '{"id":2612,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":172,"q":"Impotence is a feature of which of the following :","o":["Multiple sclerosis","Poliomyelitis","Amyotropic lateral sclerosis","Meningitis"],"a":0,"e":"Answer is A (Multiple sclerosis): Multiple sclerosis is associated with erectile dy.slitnction or impotence. Neurological disorders associated with Erectile dysfunction include: Spinal cord injury Multiple sclerosis Peripheral neuropathy","pyqMatches":[{"year":"2013","no":1292,"q":"Impotence is a feature of which of the following :","o":["Multiple sclerosis","Poliomyelitis","Amyotropic lateral sclerosis","Meningitis"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2613, 'Medicine', 'Neurology', 'Moderate', 'Internal_Medicine', 173, '{"id":2613,"subject":"Medicine","chapter":"Neurology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":173,"q":"Which of the following is the most common initial presenting feature of multiple sclerosis:","o":["Optic Neuritis","Cerebellar Ataxia","Internuclear ophthalmoplegia","Diplopia"],"a":0,"e":"Answer is A (Optic Neuritis): Optic Neuritis is the most frequent initial presenting feature of MS amongst the options provided. The most common earliest presenting features of multiple sclerosis are transient sensory defects followed by visual disturbances due to optic neuritis. Initial Symptoms of MS Symptom Percent of Cases Symptom Percent of Cases Sensory loss 37 Lhermitte''s 3 Optic neuritis 36 Pain 3 Weakness 35 Dementia 2 Paresthesias 24 Visual loss 2 Diplopia 15 Facial palsy 1 Ataxia 11 Impotence 1 Vertigo 6 Myokymia 1 Paroxysmal attacks 4 Epilepsy 1 4 1 Bladder 4 Falling 1","pyqMatches":[{"year":"2015","no":1162,"q":"Which of the following is the most common initial presenting feature of multiple sclerosis:","o":["Optic Neuritis","Cerebellar Ataxia","Internuclear ophthalmoplegia","Diplopia"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2614, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 174, '{"id":2614,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":174,"q":"\"Prosopagnosia\" is characterized by :","o":["Inability to read","Inability to identify faces","Inability to write","Inability to speak"],"a":1,"e":"Ans. B. Inability to identify faces Prosopagnosia is a recognition deficit in which the patient is unable to recognize familiar faces. Face and object recognition deficits are known as prosopagnosia and visual object agnosia respectively. The characteristic lesions in prosopagnosia and visual object agnosia consists of a bilateral infarction in the territory of the posterior cerebral arteries and involve lingual and fusiform gyri.","pyqMatches":[{"year":"2015","no":186,"q":"\"Prosopagnosia\" is characterized by :","o":["Inability to read","Inability to identify faces","Inability to write","Inability to speak"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2615, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 175, '{"id":2615,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":175,"q":"Criteria for Brainstem death includes:","o":["Positive Doll''s eye Reflex","Absent pupillary light reflex and delated pupils","Pinpoint pupils","Positive vestibulo-ocular reflex"],"a":1,"e":"Answer is B (Absent pupillary light reflex and delated pupils): Brainstem death is defined by the absence of all brainstem mediated cranial nerve reflexes. Pupillary Light Reflex is a brainstem mediated cranial nerve reflex that is absent in brainstem death. The pupils are usually midsized but may be dilated (should not however be small). Occulo-cephalic (Doll''s eye) reflex and Vestibulo-ocular (Caloric) reflex are both brainstem mediated cranial nerve reflexs that should be absent in Brainstem death. Criteria for Brain Death/Brainstem death The definition of Brain stem death requires simultaneous demonstration that the patient has irreversibly lost the capacity of consciousness (Coma) and the capacity to breathe (Apnoea) both of which are dependent on intact brainstem. Clinical assessment of the integrity of Brainstem has two components including assessment of the integrity of brainstem mediated cranial nerve reflexes and the Apnea test. Deep Unresponsive Coma Patients with brain death show the deepest coma possible with total unresponsiveness to all stimuli. No spontaneous movement No response to external stimuli (Verbal/ Deep pain) Absence of all Brainstem Cranial Reflexes All reflexes mediated by cranial nerve must be absent Absent Pupillary Light reflex (CN II, III) (Pupils are usually midsized but may be enlarged but they should not be small) Absent Corneal Reflex (CN V, VII) Absent Vestibulocochlear Reflex (CN III, IV, VI, VIII) (No eye movement in response to caloric irrigation of ears) Absent Oculocephalic Reflex (Absent Doll''s eye reflex) Eyes will move with the head (No occular movements on rapid turning of head). Absent Gag Reflex (CNIX, X) Absent Tracheal Cough Reflex (CNX) Absent Central Motor Response to Pain (CN V, VII) (No response to deep somatic stimulation). Complete Aponea in pressure of hypercarbia (Absence of Brainstem Respiratory Reflex) No respiratory effort in response to hypercarbia needs to be demonstrated to show that aponea is due to brainstem (medullary) damage Absent respiratory movement during disconnection from the ventilator with the PaCO2 > 60 mm Hg is required for the test to be valid Cranial nerve reflexes in Brain Stem Death testing: Reflex Cranial nerves Notes Pupillary light reflex HAI Use bright light source (not ophthalmoscope) in a dimmed environment. Look for both direct and consensual reaction. Important reflex that interrogates at level of midbrain Corneal reflex V, VII Stroke cornea with gauze, whilst gently holding eyes open; avoid trauma to cornea. The various nuclei of V are found throughout the whole length of the brainstem, whilst that of VII (facial nerve) is in the upper medulla. Central response to V, VII Apply deep pressure stimulation centrally (e.g. supra-orbital ridge) and peripherally deep somatic (e.g. nail bed). Look for central motor response in the distribution of the facial nerve. stimulation Peripheral stimulation may illicit peripheral spinal reflexes. Cold caloric III, IV, VI, VIII Check patency of external auditory canal with auroscope. Flex head to 30° (or apply vestibulo- ocular 30° head up tilt if cervical spine injury is suspected). Slowly irrigate canal with 5OrriL reflex ice-cold water over 60s. Observe for nystagmus for a further 30s. Contra- indicated in trauma-related otorrhea. The nuclei of III and IV lie withjin the midbrain, whilst those of VI and VIII are in the medulla. Oculocephalic reflex VIII, Ill, VI Rapid lateral movement of the head normally results in eye deviation to the (Doll''s eye reflex) contralateral side, testing brainstem gaze mechanism. In brainstem death eyes remain in a fixed position within the orbit. Gag reflex IX, X Stimulate uvula under direct vision with throat spatula, observing for contraction of soft palate. The nuclei of IX and X lie in the medulla. Tracheal cough reflex X Expose patient to umblicus. Stimulate trachea to level of carina by introduction of sterile suction catheter down endotracheal tube Observe for cough response tube. Observe for cough response","pyqMatches":[{"year":"2015","no":1161,"q":"Criteria for Brainstem death includes:","o":["Positive Doll''s eye Reflex","Absent pupillary light reflex and delated pupils","Pinpoint pupils","Positive vestibulo-ocular reflex"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2616, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 176, '{"id":2616,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":176,"q":"Renal papillary necrosis is almost always associated with one of the following conditions: March 2004","o":["Diabetes mellitus","Analgesic nephropathy","Chronic pyelonephritis","Post streptococcal glomerulonephritis"],"a":0,"e":"Ans. A i.e. Diabetes mellitus `Renal papillary necrosis, an accompaniment of acute pyelonephritis is most often seen in diabetics and is characterised by necrosis of renal papillae of one or both kidneys with sharped demarcation between necrotic and living tissue'' — Dorlands Thus while papillary necrosis is a feature of more than one conditions mentioned in the question, it is most commonly seen with diabetes mellitus.","pyqMatches":[{"year":"2012","no":461,"q":"Renal papillary necrosis is almost always associated with one of the following conditions: March 2004","o":["Diabetes mellitus","Analgesic nephropathy","Chronic pyelonephritis","Post streptococcal glomerulonephritis"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2617, 'Medicine', 'Hematology', 'Moderate', 'Internal_Medicine', 177, '{"id":2617,"subject":"Medicine","chapter":"Hematology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":177,"q":"Renal vein thrombosis is associated with all of the following except: September 2011","o":["Trauma","Sickle cell anemia","Nephrotic syndrome","Dehydration"],"a":1,"e":"Ans. B: Sickle cell anemia Conditions associated with RVT are: Trauma, extrinsic compression (lymoh nodes, aneurysm), invasion by renal cell carcinoma, dehydration (infants), nephritic syndrome and Pregnancy/ oral contraceptives RVT: Acute cases occurs in children and presents with sudden loss of renal function Gradual thrombosis occurs in elderly and only manifestation may be recurrent pulmonary emboli or development of hypertension Definitive diagnosis can be done through selective renal venography with visualization of the occluding thrombus Treatment options consists of anticoagulation and thrombectomy","pyqMatches":[{"year":"2012","no":75,"q":"Renal vein thrombosis is associated with all of the following except: September 2011","o":["Trauma","Sickle cell anemia","Nephrotic syndrome","Dehydration"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2618, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 178, '{"id":2618,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":178,"q":"Best marker to assess prognosis after Surgery for colon carcinoma: March 2005","o":["CA 19-9","CA-125","Alpha fetoprotein","CEA"],"a":3,"e":"Ans. D: CEA CEA is a family of related glycoproteins initially found in embryonic tissue and colon malignancies. The half-life of CEA is approximately 2 weeks. Plasma levels of CEA can be determined readily by radioimmunoassay. However, its usefulness in colon carcinogenesis screening is limited because of its high level in the plasma of a patient''s malignancies originating from other sites such as breast, pancreas, stomach and lung. Furthermore, CEA plasma levels may also be increased in smokers or patients with chronic diseases, such as inflammatory bowel disease, bronchitis and alcoholic liver disease. The clinical usefulness of CEA for screening purposes is further limited by the fact that its increase in level typically occurs only when the tumor penetrates through the serosa. Thus, early lesions may not be detected by serum CEA level changes. CEA is typically elevated with metastatic liver disease, but rarely with peritoneal involvement. Thus, while the specificity for CEA to identify occult CRCs is high, the sensitivity is low in most studies for screening. Accordingly, CEA is not a useful test for the screening of CRC. Regardless of the clinicopathologic stage, a preoperative elevation Regardless of the clinicopathologic stage, a preoperative elevation of the plasma CEA level predicts eventual tumour recurrence. High level of CA 19-9 is seen in the plasma of a patient''s malignancies originating from colon, breast and pancreas","pyqMatches":[{"year":"2015","no":1272,"q":"Best marker to assess prognosis after Surgery for colon carcinoma: March 2005","o":["CA 19-9","CA-125","Alpha fetoprotein","CEA"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2619, 'Medicine', 'Gastroenterology', 'Moderate', 'Internal_Medicine', 179, '{"id":2619,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":179,"q":"All of the following are features of Obstructive jaundice except: September 2007","o":["Normal alkaline phosphatase","Mildly elevated serum aminotransferases level","Clay colour stools","Pruritis"],"a":0,"e":"Ans. A: Normal alkaline phosphatase Obstruction to the flow of bile in common bile duct may result from choledocholithiasis, malignancy od head of pancreas, bile ducts or ampulla of Vater. Charcot''s triad of intermittent fever, pain and jaundice is characteristic of ascending cholangitis and indicates biliary obstruction. Hepatomegaly is present in most cases of obstructive jaundice and is due to congestion and stretching out of intrahepatic biliary spaces. A palpable gall bladder usually indicates obstruction of the distal CBD, due to other causes like underlying malignancy, than stone (Courvoisier''s law). Hepatic bile flow suppression leads to jaundice accompanied by dark urine (bilirubinuria) and light coloured (alcoholic) stools. Bile salts and pigments in urine and absent urobilinogen also favour the diagnosis of obstructive jaundice. Serum albumin and prothrombin time are good indicators of liver function derangement. Serum bilirubin levels indicate severity of jaundice and high direct bilirubin rules out hemolytic jaundice. Mild elevation of SGPT levels are also seen in obstructive jaundice Mild elevation of SGPT levels are also seen in obstructive jaundice consistent with liver dysfunction. An elevated alkaline phosphatase is, always present in obstructive jaundice.","pyqMatches":[{"year":"2013","no":1293,"q":"All of the following are features of Obstructive jaundice except: September 2007","o":["Normal alkaline phosphatase","Mildly elevated serum aminotransferases level","Clay colour stools","Pruritis"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2620, 'Medicine', 'Endocrinology', 'Easy', 'Internal_Medicine', 180, '{"id":2620,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":180,"q":"Chvostek sign is seen in: March 2013","o":["Hypercalcemia","Hypoparathyroidism","Insulinoma","Diabetes mellitus"],"a":1,"e":"Ans. B i.e. Hypoparathyroidism Hypocalcemia Idiopathic hypoparathyroidism is associated with: Genetic syndrome of hypoparathyroidism, - Addison''s disease and – Mucocutaneous candid iasis Pseudohypoparathyroidism: No deficiency of parathormone, but target organ (bone and kidney) are unresponsive to its action Chvostek''s sign: Contraction of facial muscles, elicited by light tapping of the facial nerve ECG changes: Prolongation of QT interval","pyqMatches":[{"year":"2015","no":1191,"q":"Chvostek sign is seen in: March 2013","o":["Hypercalcemia","Hypoparathyroidism","Insulinoma","Diabetes mellitus"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2621, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 181, '{"id":2621,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":181,"q":"ECG pattern seen in pulmonary embolism is: September 2009, March 2013","o":["S3Q3T1","S1Q1T3","S1Q3T3","S3Q3T3."],"a":2,"e":"Ans. C: S1Q3T3","pyqMatches":[{"year":"2016","no":1060,"q":"ECG pattern seen in pulmonary embolism is: September 2009, March 2013","o":["S3Q3T1","S1Q1T3","S1Q3T3","S3Q3T3."],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2622, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 182, '{"id":2622,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":182,"q":"Specific antibody associated with primary biliary cirrhosis is:","o":["Anti-myosin","Anti-nuclear","Anti-mitochondrial","Anti-endomysial"],"a":2,"e":"Ans. C: Anti-mitochondrial Primary biliary cirrhosis is strongly associated with the presence of anti-mitochondrial antibodies (AMA), which are diagnostic PBC: * Associated with CREST syndrome, sicca syndrome, auto-immune thyroiditis, type I DM and IgA deficiency * IgG AMA is detected in more than 90% of patients with PBC * 90% of women are between 35 - 60 years * Earliest symptom is pruritis * Eventually hepatocellular failure and portal hypertension develops * Lab findings: - Increased serum alkaline phosphatase - Increased serum 5-nucleotidase activity - Increased gamma-glutamyl transpeptidase - Serum bilirubin is usually normal - Aminotransferase levels minimally increased - Treatment: Ursodiol","pyqMatches":[{"year":"2016","no":1101,"q":"Specific antibody associated with primary biliary cirrhosis is:","o":["Anti-myosin","Anti-nuclear","Anti-mitochondrial","Anti-endomysial"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2623, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 183, '{"id":2623,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":183,"q":"''v'' Wave in JVP is due to ?","o":["Right atrial contraction","Left atrial contraction","Right atrial relaxation","Closure of tricuspid valve"],"a":0,"e":"Ans. is A The first elevation (a wave) corresponds to the slight rise in atrial pressure resulting from atrial contraction. The first descent (x descent) reflects a fall in atrial pressure that starts with atrial relaxation. The second elevation (v wave) corresponds to ventricular systole when blood is entering the right atrium from the vena cavae while the tricuspid valve is closed. Finally, the second descent (y descent) reflects falling right atrial pressure as the tricuspid valve opens and blood drains from the atrium into the ventricle.","pyqMatches":[{"year":"2014","no":144,"q":"''v'' Wave in JVP is due to ?","o":["Right atrial contraction","Left atrial contraction","Right atrial relaxation","Closure of tricuspid valve"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2624, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 184, '{"id":2624,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":184,"q":"Gene for Rh antigen is located on chromosome ?","o":["1","4","9","19"],"a":0,"e":"Ans. is ''a'' i.e., 1","pyqMatches":[{"year":"2014","no":232,"q":"Gene for Rh antigen is located on chromosome ?","o":["1","4","9","19"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2625, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 185, '{"id":2625,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":185,"q":"Mannitol infusion causes increase in","o":["Blood viscosity","Osmolarity","Intra-ocular tension","Intercranial tension"],"a":1,"e":"Ans. is ''b'' i.e., Omolarity","pyqMatches":[{"year":"2014","no":153,"q":"Mannitol infusion causes increase in","o":["Blood viscosity","Osmolarity","Intra-ocular tension","Intercranial tension"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2626, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 186, '{"id":2626,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":186,"q":"Normal QRS axis ?","o":["+30 to 110°","-30 to +110°","+110° to +150°","-110° to -150°"],"a":1,"e":"Ans. is ''b'' i.e., -30 to +110° In a normal heart, the average direction of the vector during spread of the depolarization wave through the ventricles, called the mean QRS vector, is about +59 degrees. This means that during most of the depolarization wave, the apex of the heart remains positive with respect to the base of the heart. The normal electrical axis of the heart (mean electrical axis or mean QRS vector) lies between -30° and + 100°. If the axis is more negative than -30° it is called left axis deviation, whereas if the axis is more positive than + 100°, it is called right axis deviation.","pyqMatches":[{"year":"2014","no":156,"q":"Normal QRS axis ?","o":["+30 to 110°","30 to +110°","+110° to +150°","110° to -150°"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2627, 'Medicine', 'Dermatology & Allergy', 'Easy', 'Internal_Medicine', 187, '{"id":2627,"subject":"Medicine","chapter":"Dermatology & Allergy","difficulty":"Easy","source":"Internal_Medicine","sourceNo":187,"q":"Acrodermatitis hemorrhagica is due to deficiency of","o":["Zinc","Manganese","Copper","Selenium"],"a":0,"e":"Ans. is ''a'' i.e., Zinc Symptoms of Zinc Deficiency Mild deficiency Severe dificiency Growth retardation Dwarfism Cardiomyopathy Hypogonadism Infertility Loss of taste Poor wound healing Deformed bones Diarrhoea Alopecia Night blindness Skin striae Nail changes Acrodermatitis enteropathica is an inherited autosomal recessive disorder with imapired intestinal disorder and transport of Zinc. Patient suffers with pustular and bullous dermatitis, alopecia, growth retardation diarrhoes, secondary infection, lethargy, irritability and depression. Oral Zinc supplementation leads to remission. Zinc 2nd most abundant trace element in the body. Most common catalytic metal ion in the cell cytoplasm. Component of more than 100 enzymes like DNA polymerase, RNA polymerase, transfer RNA synthetase. It plays role in all stages of insulin metabolism.","pyqMatches":[{"year":"2013","no":1420,"q":"Acrodermatitis hemorrhagica is due to deficiency of","o":["Zinc","Manganese","Copper","Selenium"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2628, 'Medicine', 'Gastroenterology', 'Moderate', 'Internal_Medicine', 188, '{"id":2628,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":188,"q":"Which of the following is not seen in Secondary Adrenal insufficiency","o":["Pigmentation","Postural hypotension","Hypoglycemia","Lassitude"],"a":0,"e":"Secondary adrenal insufficiency is adrenal hypofunction due to a lack of adrenocorticotropic hormone (ACTH). Secondary adrenal insufficiency may occur in Panhypopituitarism Isolated failure of adrenocorticotropic hormone (ACTH) production Patients receiving corticosteroids (by any route, including high doses of inhaled, intra-articular, or topical corticosteroids) Patients who have stopped taking corticosteroids Symptoms are the same as for Addison disease and include fatigue, weakness, weight loss, nausea, vomiting, and diarrhea, but there is usually less hypovolemia.","pyqMatches":[{"year":"2014","no":1460,"q":"Which of the following is not seen in Secondary Adrenal insufficiency","o":["Pigmentation","Postural hypotension","Hypoglycemia","Lassitude"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2629, 'Medicine', 'Infectious Diseases', 'Moderate', 'Internal_Medicine', 189, '{"id":2629,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":189,"q":"Typhoid is treated by all except","o":["Erythromycin","Ceftriaxone","Amikacin","Ciprofloxacin"],"a":0,"e":"Ans. is ''a'' i.e., Erythromycin The older agents used for the treatment of typhoid were : Chloramphenicol Ampicilin Trimethoprim Sulfamethoxazole Beta lactam Parenteral → Ceftriaxone Orall → Cefixime These drugs are not used nowdays because of widespread resistance. o Nowdays the drug of choice for Typhoid all over the world is a \"Fluroquinolone\" (Ciprofloxacin, ofloxacin). An important point to remember High level of fluoroquinolone resistance (ciprofloxacin) have been reported from India and other parts of South East Asia in S. paratyphi and S.typhi infection. Nalidixic acid resistant S.typhi (NARST) have decreased ciprofloxacin sensitivity and are less effectively treated with fluoroquinolones. The fluroquinolones should not be used as first line treatment for typhoid fevers in patients from India and other parts of South Asia with high rates of fluroquinolone resistance unless antibiotic susceptibility data demonstrates fluoroquinolone or nalidixic acid sensitivity.","pyqMatches":[{"year":"2014","no":1245,"q":"Typhoid is treated by all except","o":["Erythromycin","Ceftriaxone","Amikacin","Ciprofloxacin"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2630, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 190, '{"id":2630,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":190,"q":"Drug treatment is given for how many days in pneumococcal meningitis","o":["5 days","7 days","14 days","21 days"],"a":2,"e":"Ans. is ''c'' i.e., 14 days Recommendations for duration of treatment Pneumococcal meningitis —> 10-14 days Meningococcal meningitis 5-7 days Hib meningitis —> 7-14 days Listeria meningitis —> 21 days","pyqMatches":[{"year":"2014","no":1246,"q":"Drug treatment is given for how many days in pneumococcal meningitis","o":["5 days","7 days","14 days","21 days"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2631, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 191, '{"id":2631,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":191,"q":"Marker of acute kidney injury all except","o":["Clusterin","Osteopontin","Alanine aminopeptidase","Acid phosphatase"],"a":3,"e":"Ans. is ''d'' i.e., Acid phosphatase Alanine aminopeptidase (AAP) Kidney injury molecule-1 (KIM-1) Alkaline phosphatase (AP) Clusterin utathione-S-transferase (a-GST) Neutrophil gelatinase associated lipocalin (NGAL) yglutamyl transpeptidase (TGT) Interleukin-18 (IL- 18) N-acetyl-0-glucosaminidase (NAG) Cysteine-rich protein (CYR-61) 2-microglobulin Osteopontin (OPN) microglobulin o Retinol-binding protein (RBP) Fatty acid binding protein (FABP Cystatin C Sodium/hydrogen exchanger isoform (NHE3) o Microalbumin Exosomal fetuin-A","pyqMatches":[{"year":"2014","no":1486,"q":"Marker of acute kidney injury all except","o":["Clusterin","Osteopontin","Alanine aminopeptidase","Acid phosphatase"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2632, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 192, '{"id":2632,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":192,"q":"The treatment of choice in acute hyperkalemia of life threatening to cardiac myocytes is","o":["Infusion of calcium gluconate","Oral resins","Intravenous infusion of insulin","β blocker"],"a":0,"e":"Ans. is `a'' i.e. Infusion of calcium gluconate Emergent t/t of hyperkalemia is needed in conditions with severe hyperkalemia (IC >7 meq/L). In these cases cardiac toxicity or muscular paralysis is present. Calcium gluconate is the fastest acting agent among the agents used in the t/t of hyperkalemia°. It acts within minutes but an important point to note is that it does not cause transcellular movement of potassium, instead, it acts on cardiac cell membrane","pyqMatches":[{"year":"2014","no":1247,"q":"The treatment of choice in acute hyperkalemia of life threatening to cardiac myocytes is","o":["Infusion of calcium gluconate","Oral resins","Intravenous infusion of insulin","β blocker"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2633, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 193, '{"id":2633,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":193,"q":"Vitamin E causes","o":["Hemorrhagic stroke","Cardiac failure","Ataxia","Megalablastic anemia"],"a":2,"e":"Ans. is ''c'' i.e., Ataxia Vitamin E (tocopherol) is a fat-soluble vitamin with antioxidant properties; It protects cell membranes from oxidation and destruction. Vitamin E is found in a variety of food including oils, meat, eggs, and leafy vegatables. There are multiple forms and isomers of tocopherol and the related compounds, tocotrienols. The current evidence the primary bioactive form of Vitamin E is alfa- tocopherol. Serum vitamin E levels are strongly influenced by concentration of serum lipids, and do not accurately reflect tissue vitamin levels. Effective vitamin E levels are calculated as the ratio of serum alpha- tocopherol per gram total lipids. Absorption of dietary vitamin E requires effective pancreatic exocrine function and fat absorption, unless provided in a synthetic water- soluble form. Vitamin Vitamin E deficiency is uncommon in humans except in special circumstances. This is due to the abundance of tocopherols in the diet.","pyqMatches":[{"year":"2013","no":1326,"q":"Vitamin E causes","o":["Hemorrhagic stroke","Cardiac failure","Ataxia","Megalablastic anemia"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2634, 'Medicine', 'Miscellaneous', 'Hard', 'Internal_Medicine', 194, '{"id":2634,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Internal_Medicine","sourceNo":194,"q":"Which of the following circulating antibodies has the best sensitivity and sepcificity for the diagnosis of celiac disease ?","o":["Anti Saccharomyces antibody","Anti-tissue transglutaminase antibody","Anti-gliadin antibody","Anti-gliadin antibody antibody"],"a":0,"e":"Ans. is ''a'' i.e. Anti saccharomyces antibody Serologic evaluation in celiac disease Immunoglobulin A (IgA) anti-tissue transglutaminase (TTG) antibody is the single preferred test for detection of celiac disease in individuals over the age of two years. Serum antibody assays A variety of serologic studies have been described to aid in the diagnosis of celiac disease, including: IgA endomysial antibody (IgA EMA) IgA tissue transglutaminase antibody (IgA tTG) IgG tissue transglutaminase antibody (IgG tTG) IgA deamidated gliadin peptide (IgA DGP) IgG deamidated gliadin peptide (IgG DGP) Serum IgA endomysial and tissue transglutaminase antibody testing have the highest diagnostic accuracy. The IgA and IgG antigliadin antibody tests have lower diagnostic accuracy with frequent false positive results as compared with IgA tTG and IgA DGP assays and are therefore no longer recommended for initial diagnostic evaluation or screening However, the newer anti-deamidated gliadin peptide (DGP) assays described above show high diagnostic accuracy. IgA EMA, IgA tTG,IgA DGP and IgG DGP levels fall with treatment; as a result, these assays can be used as a noninvasive means of monitoring the response to a gluten-free diet. Assay sensitivity and specificity IgA endomysial antibodies- → Sensitivity 85 to 98 percent; specificity 97 to 100 percent IgA tissue transglutaminase antibodies → Sensitivity 90 to 98 percent; specificity 95 to 97 percent -- IgA deamidated gliadin peptide → Sen sitivity 94 percent; specificity 99 percent IgG deamidated gliadin peptide → Sensitivity 92 percent; specificity 100 percent","pyqMatches":[{"year":"2014","no":1249,"q":"Which of the following circulating antibodies has the best sensitivity and sepcificity for the diagnosis of celiac disease ?","o":["Anti Saccharomyces antibody","Anti-tissue transglutaminase antibody","Anti-gliadin antibody","Anti-gliadin antibody antibody"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2635, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 195, '{"id":2635,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":195,"q":"Aseptic meningitis caused by","o":["Indomethacin","Ibuprofen","Aspirin","Icatibant"],"a":1,"e":"Ans. is ''b'' i.e., Ibuprofen Medications known to cause aseptic meningitis Medications Medication Common Uncommon NSAIDs Ibuprofen Sulindac Naproxen Diclofenac Rofecoxib Antimicrobials Trimethoprim/sulfamethoxazoleSulfonamides Immunomodulating agents Monoclonalantibody OKT3Intravenous IgG Azathioprine Intrahecal agents Metrizamide Cytarabine Methylprednisolone acetate Other Carbamazepine Causes of acute aseptic meningitis Infectious cases Bacterial Lyne disease Leptospirosis Mycobacterium tuberculosis infection Subacute bacterial endocarditis Subacute bacterial endocarditis Parameningeal infection (epidural subdural abcess, sinus or ear infection) Partially treated bacterial meningitis Viral Echovirus infection Coxaackie virus infection Mumps St. Louis encephalitis Eastern equine encephalitis Western equine encephalitis Calcifornia encerphalitis Herpes simplex virus type 2 infection HIV infection Lymphocytic choriomeningitis Poliovirus infection","pyqMatches":[{"year":"2014","no":1250,"q":"Aseptic meningitis caused by","o":["Indomethacin","Ibuprofen","Aspirin","Icatibant"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2636, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 196, '{"id":2636,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":196,"q":"High Steppage Gait is seen in","o":["Foot drop","Frontal lobe stroke","Tabes dorsalis","Leprosy"],"a":2,"e":"Ans. is ''c'' i.e., Tabes dorsalis High stepping gait or steppage gait or foot drop gait is due to foot drop -+ leg is lifted more in order to get clearance and first to touch the ground is fore foot (not the heel as occur in normal gait). It may occur in all motor peripheral neuropathies involving common peroneal nerve —> Tabes dorsalis, leprosy etc. [Ref Harrison 18th/e chapter 377]","pyqMatches":[{"year":"2014","no":1251,"q":"High Steppage Gait is seen in","o":["Foot drop","Frontal lobe stroke","Tabes dorsalis","Leprosy"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2637, 'Medicine', 'Respiratory Medicine', 'Hard', 'Internal_Medicine', 197, '{"id":2637,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Hard","source":"Internal_Medicine","sourceNo":197,"q":"In a patient with bronchial asthma silent chest signifies","o":["Good Prognosis","Bad Prognosis","Grave Prognosis","Not a Prognostic sign"],"a":2,"e":"Ans. is ''c'' i.e., Grave Prognosis Silent chest (Little/no air movement without wheezes in Bronchial Asthma suggests a grave prognosis/impending respiratory failure (Life threatening Asthma). Signs of impending respiratory failure include : Drowsiness or confusion Diaphoresis Bradycardia Paradoxical thoraco abdominal Signs of impending respiratory failure in Asthma Drowsiness or confusion Diaphoresis Bradycardia Paradoxical thracoabdominal movements PEFR < 33% Hypotension Pulsus paradoxus Hypercapnea Silent chest","pyqMatches":[{"year":"2014","no":1253,"q":"In a patient with bronchial asthma silent chest signifies","o":["Good Prognosis","Bad Prognosis","Grave Prognosis","Not a Prognostic sign"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2638, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 198, '{"id":2638,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":198,"q":"Which is correct about pneumonia","o":["Bronchophonia","Decreased vocal fremitus","Shifting of trachea","Amphoric breathing"],"a":0,"e":"Ans. is ''a'' i.e., Bronchophonia Physical examination findings of Common pulmonary conditions Pleural effusion Pneumonia Endobronchial tumor Pneumothorax Tracheal position Shifted or midline Midline Shifted or midline Shifted or midli Chest wall Reduced or normal Reduced or normal Reduced or normal Reduced Fremitus Decreased Increased Normal or decreased None PercussionDull Dull Normal or DullHyperresonant Breath sounds Decreased Increased Normal or Decreased Decreased/abs Crackles None None None None Wheeze None None Possible None Egophony Band above effusion(skodiac)Present None None Tracheal position Deviated Away from Pneumo thorax Effusion Deviated towards Collapse Consolidation Tactile vocal fremitus Tactile vocal fremitus is vibration felt on the patients chest during low frequency vocalisation. Commonly the patient is asked to repeat a phrase while the examiner feels for vibtations by placing a hand over the patient chest or back. Tactile fremitus is normally more intense in the right second intercostal space as well as in the interscapular region as these : Tactile fremitus Increased → Consolidation Decreased or absent → Pleural effusion or Pneumothorax Reason for increased fremitus in a consolidated lung is the fact that the sound waves are transmitted with less decay in solid or fluid medium (consolidation) than in a gaseous medium (consolidation) than in a gaseous medium (aerated lung). Conversely the reason for decreased fremitus in a pleural effusion or pneumothorax (or any pathology separating the lung tissue itself from the body wall) is that this increased space diminishes or prevents entirely sound transmission Egophony is a change in timbre (E0 to A) but not pitch or volume. It is due to decrease in the amplitude and an increase in the frequency of the second formant produced by solid (including compressed lung) interposed between the resonator and the stethoscope head. The sound of a spoken \"E\" change to \"A\" over an area of consolidation. The spoken \"E\" is heared as \"A\" when listening over the consolidation because the frequencies of the vibrations are altered by the consolidation. Egophony or \"E\" to \"A\" changes may also occur in small band like area just above a pleural effusion because of compression of lung tissue that occurs just above the effusion.","pyqMatches":[{"year":"2014","no":1254,"q":"Which is correct about pneumonia","o":["Bronchophonia","Decreased vocal fremitus","Shifting of trachea","Amphoric breathing"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2639, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 199, '{"id":2639,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":199,"q":"Systemic Millary TB spreads via","o":["Artery","Vein","Bronchus","Lymphatic"],"a":0,"e":". Ans. is ''a'' i.e., Artery Systemic miliary ensues when infective foci in the lungs seed the pulmonary venous return to the heart; the organisms subsequently disseminate through the systemic arterial system.","pyqMatches":[{"year":"2014","no":1255,"q":"Systemic Millary TB spreads via","o":["Artery","Vein","Bronchus","Lymphatic"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2640, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 200, '{"id":2640,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":200,"q":"DOC for acute attack of Hereditary angioneurotic edema","o":["Danazol","Cl, inhibitor concentrate","Icatibant","Methylprednisolone"],"a":1,"e":"Ans. is ''b'' i.e., Cl inhibitor concentrate Medication C1 inhibitor concentrate (Plasma-derived) (Berinert, Berinert P, Cinryze. Recombinant C1 inhibitor Conestat alfa (Ruconest, Rhucin). Bradykinin Bzreceptor antagonist Icatibant (Firazyr). Kallikrein inhibitor Ecallantide (Kalbitor) Plasma","pyqMatches":[{"year":"2014","no":1256,"q":"DOC for acute attack of Hereditary angioneurotic edema","o":["Danazol","Cl, inhibitor concentrate","Icatibant","Methylprednisolone"],"a":1,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":1209,"q":"DOC for acute attack of Hereditary angioneurotic edema","o":["Danazol","Cl, inhibitor concentrate","Icatibant","Methylprednisolone"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2641, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 201, '{"id":2641,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":201,"q":"Type 5 Hypersensitivity mimics","o":["Type 1","Type 2","Type 3","Type 4"],"a":1,"e":"Ans. is ''b'' i.e., Type 2 Type V hypersensitivity reactions were additionally added to the scheme originally described by Coombs and Gell. Contrary to type IV and in agreement with types I, 11 and III respectively, they are mediated by antibodies too. The type V reactions are sometimes considered as a subtype of the type II hypersensitivity. As its mechanisms do not destroy target cells, they are responsible for induction of organ/tissue dysfunctions only most of authors prefer it to be and independent, the 5'' type of hypersensitivity reactions","pyqMatches":[{"year":"2014","no":1257,"q":"Type 5 Hypersensitivity mimics","o":["Type 1","Type 2","Type 3","Type 4"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2642, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 202, '{"id":2642,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":202,"q":"Which is best for plaque morphology","o":["CCTA","MRI","CMR","IVUS"],"a":0,"e":"Ans. is ''a'' i.e., CCTA Coronary lesions prone to rupture have a distinct morphology compared with stable plaques, and provide a unique opportunity for noninvasive imaging to identify vulnerable plques before they lead to clinical events. This can be achieved using a non-invasive cardiac imaging using coronary CT angiography. o Large plaque volume, low CT attenuation, napkin-ring sign, positive re-moedlling, and spotty calcification are all associated with a high risk of acute cardiovascular events in patients. Intravascular USG can give comparable results but is an invasive test","pyqMatches":[{"year":"2014","no":1432,"q":"Which is best for plaque morphology","o":["CCTA","MRI","CMR","IVUS"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2643, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 203, '{"id":2643,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":203,"q":"Most common cause of heart block in infants is","o":["SLE","Surgery for congentital heart disease","Viral myocarditis","Rheumatic fever"],"a":1,"e":"Ans. is ''b'' i.e., Surgery for congentital heart disease In children, the most common cause of permanent acquired complete AV block is surgery for congenital heart disease. Postsurgical completer atrioventricular block (A VB) is the most common cause for acquired AV block in children, resulting from trauma to the AV node at time of surgery (i.e., hemorrhage, ischemia, necrosis, inflammation, traumatic disruption). The second most common cause is congenital herat disease associated with complete AV block. Other etiologies of acquired AV block are often reversible and include : Digitalis and other drug intoxications. Viral myocarditis. Acute rheumatic fever, Lyme disease, and infectious mononucleosis.","pyqMatches":[{"year":"2014","no":1433,"q":"Most common cause of heart block in infants is","o":["SLE","Surgery for congentital heart disease","Viral myocarditis","Rheumatic fever"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2644, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 204, '{"id":2644,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":204,"q":"Aphasia which affects the arcuate fibres is called","o":["Global aphasia","Anomie aphasia","Conduction aphasia","Broca''s aphasia"],"a":2,"e":"Ans. is ''c'' i.e., Conduction aphasia Arcuate fibers are bundle of nerve fibres that connect Brocas area to the Wernicke ''s area. Damage to the arcuate fasciculus causes a disorder called conduction aphasia","pyqMatches":[{"year":"2014","no":1262,"q":"Aphasia which affects the arcuate fibres is called","o":["Global aphasia","Anomie aphasia","Conduction aphasia","Broca''s aphasia"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2645, 'Medicine', 'Cardiology', 'Hard', 'Internal_Medicine', 205, '{"id":2645,"subject":"Medicine","chapter":"Cardiology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":205,"q":"Drug for management of hypertension in Phaeochromocytoma","o":["Phenoxybenzamine","Phentolamine","Labetalol","Esmolol"],"a":0,"e":"Ans. is ''a'' i.e., Phenoxybenzamine Once a pheochromocytoma is diagnosed, all patients should undergo a resection of the pheochromocytoma following appropriate medical preparation. Resetting a pheochromocytoma is a high-risk surgical procedure and an experienced surgeon/anesthesiologist team is required. Some form of preoperative pharmacologic preparation is indicated for all patients with catecholamine-secreting neoplasms. Preoperative medical therapy is aimed at: Controlling hypertension (including preventing a hypertensive crisis during surgery) o Volume expansion In patients with undiagnosed pheochromocytomas who undergo surgery for other reasons (and who therefore have not undergone preoperative medical therapy), surgical mortality rates are high due to lethal hypertensive crises, malignant arrhythmias, and multiorgan failure. Combined alpha- and beta-adrenergic blockade Combined alpha- and beta-adrenergic blockade is the most common approach to control blood pressure and prevent intraoperative hypertensive crises. Alpha-adrenergic blockade An alpha-adrenergic blocker is given 10 to 14 days preoperatively to normalize blood pressure and expand the contracted blood volume. Phenoxybenzamine is the preferred drug for preoperative preparation to control blood pressure and arrhythmia in most centers in the United States. It is an irreversible, long-acting, nonspecific alpha-adrenergic blocking agent. The initial dose is 10 mg once or twice daily, and the dose is increased by 10 to 20 mg in divided doses every two to three days as needed to control blood pressure and spells. The final dose of phenoxybenzamine is typically between 20 and 100 mg daily. Beta-adrenergic blockade After adequate alpha-adrenergic blockade has been achieved, beta- adrenergic blockade is initiated, which typically occurs two to three days preoperatively. The beta-adrenergic blocker should never be started first because blockade of vasodilatory peripheral beta​adrenergic receptors with unopposed alpha-adrenergic receptor stimulation can lead to a further elevation in blood pressure. The alternatives to a and 13 adrenergic agents are calcium channel blockers and metyrosine. Calcium channel blockers Although perioperative alpha-adrenergic blockade is widely recommended, a second regimen that has been utilized involves the administration of a calcium channel blocker. Nicardipine is the most commonly used calcium channel blocker in this setting; the starting dose is 30 mg twice daily of the sustained release preparation. Metyrosine Another approach involves the administration of metyrosine (alpha- methyl Para-tyrosine), which inhibits catecholamine synthesis.","pyqMatches":[{"year":"2014","no":1264,"q":"Drug for management of hypertension in Phaeochromocytoma","o":["Phenoxybenzamine","Phentolamine","Labetalol","Esmolol"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2646, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 206, '{"id":2646,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":206,"q":"Causes of hyperparathyroidism are all except","o":["Solitary adenoma","Malignant","Thyroid malignancy","Parathyroid hyperplasia"],"a":2,"e":"Ans.:C.)Thyroid malignancy Hyperparathyroidism Pathology Increased levels of the PTH lead to increased osteoclastic activity. The resultant bone resorption produces cortical thinning (subperiosteal resorption) and osteopaenia. Subtypes primary hyperparathyroidism parathyroid adenoma (~80%) multiple parathyroid adenomas (4%) parathyroid hyperplasia (10-15%) parathyroid carcinoma (1-5%) secondary hyperparathyroidism caused by chronic hypocalcaemia with renal osteodystrophy being the most common cause (others include malnutrition, vitamin D deficiency) results in parathyroid hyperplasia tertiary hyperparathyroidism autonomous parathyroid adenoma caused by the chronic overstimulation of hyperplastic glands in renal insufficiency","pyqMatches":[{"year":"2014","no":1265,"q":"Causes of hyperparathyroidism are all except","o":["Solitary adenoma","Malignant","Thyroid malignancy","Parathyroid hyperplasia"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2647, 'Medicine', 'Hematology', 'Hard', 'Internal_Medicine', 207, '{"id":2647,"subject":"Medicine","chapter":"Hematology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":207,"q":"Mentzer index more than 13 suggests a diagnosis of","o":["Iron deficiency anemia","Thalassemia","Hereditary Spherocytosis","Autoimmune Hemolytic Anemia"],"a":0,"e":"Ans. is ''a'' i.e., Iron deficiency Anemia Mentzer index more than 13 suggests a diagnosis of Iron-deficiency anemia. Mentzer index The Mentzer index is used to help in differentiating iron deficiency anemia from beta thalassemia. The index is calculated as the quotient of the mean corpuscular volume (MCV, in fL) divided by the red blood cell count (RBC, in millions per microleter). If the Mentzer index is less than 13, thallassemia is said to be more likely. If the Mentzer Index is greater than 13, Then iron-deficiency anemia is said to be more likely. Principle In iron deficiency, the marrow cannot produce as many RBCs and they are small (imcrocytic), so the RBC count and the MCV will both be low, and as a result, the index will be greater than 13. Conversely, in thalassemia, which is a disorder of globin synthesis, the number of RBCs produced is normal, but the cells are smaller and more fragile. Therefore, the RBC count is normal, but the MCV is low, so the index will be less than 13. In practice, the Mentzer index is not a reliable indicator and should not, by itself be used to differentiate the two conditions. Index Formula Value for iron deficiency anemia Value for iron thalassemia Mentzer index MC V/RBC count > 13 < 13 Shine and Lal index MCV2 x MCH x 0.01 > 1530 < 1530 England and Fraser index MCV – RBC - (5 x Hb) 5.19 > 0 < 0 Srivastava index MCH/RBC > 3.8 < 3.8 Green and king index MCV2 x RDW x Hb/100 > 65 < 65 Red cell distribution width index MCV x RDW/RBC > 220 < 220","pyqMatches":[{"year":"2014","no":1465,"q":"Mentzer index more than 13 suggests a diagnosis of","o":["Iron deficiency anemia","Thalassemia","Hereditary Spherocytosis","Autoimmune Hemolytic Anemia"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2648, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 208, '{"id":2648,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":208,"q":"Which of the following statements about iron deficiency anemia is correct","o":["Decreased TIBC","Increased ferritin levels","Bone marrow iron is decreased after serum iron is decreased","Bone marrow iron is decreased earlier than serum iron"],"a":3,"e":"Ans. is ''D'' i.e., Bone marrow iron is decreased earlier than serum iron \"In iron deficiency anemia the first change is decrease in iron stores \" The decrease in iron stores is demonstrated by decreased serum ferritin level. Remember, Serum ferritin reflects the amount of storage iron in the body. As the total body iron level begins to fall a characteristic, sequence of events ensue : First Stage or Prelatent Stage of Iron Depletion When iron loss exceeds absorption, a negative iron balance exists. Stored iron begins to be, mobilized from stores. The iron present in the macrophages of liver, spleen and bone marrow are depleted Decrease in stored iron is reflected by decrease in serum ferritin. At this stage all other parameters of iron status are normal. Second Stage or Stage of Latent Iron Deficiency : Iron stores are exhausted but the blood hemoglobin level remains higher than the lower limit of normal. o After the exhaustion of iron stores : The plasma iron concentration fallsQ. Plasma iron binding capacity increases2. Percentage saturation falls below 15%Q. The percentage of sideroblast decreases in the bone marrowQ. Third Stage or Stage of Apparent Iron Deficiency Anemia Supply of iron to marrow becomes inadequate for normal hemoglobin production, So the blood hemoglobin concentration fallsQ below the lower limit of normal and iron deficiency anemia is apparent.","pyqMatches":[{"year":"2014","no":1466,"q":"Which of the following statements about iron deficiency anemia is correct","o":["Decreased TIBC","Increased ferritin levels","Bone marrow iron is decreased after serum iron is decreased","Bone marrow iron is decreased earlier than serum iron"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2649, 'Medicine', 'Hematology', 'Easy', 'Internal_Medicine', 209, '{"id":2649,"subject":"Medicine","chapter":"Hematology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":209,"q":"Persistent priapism is due to","o":["Sickle cell anaemia","Hairy cell leukaemia","Paraphimosis","Urethral stenosis"],"a":0,"e":"Ans. is ''a'' i.e., Sickle cell anemia Priapism is defined as erection lasting for > 4 hours. Low-flow priapism may be due to any of the following: An excessive release of neurotransmitters Blockage of draining venules (eg, mechanical interference in sickle cell crisis, leukemia, or excessive use of intravenous parenteral lipids) Paralysis of the intrinsic detumescence mechanism Prolonged relaxation of the intracavernous smooth muscles (most often caused by the use of exogenous smooth-muscle relaxants such as injectable intra-cavernosal prostaglandin E I) Prolonged low-flow priapism leads to a painful ischemic state, which can cause fibrosis of the corporeal smooth muscle and cavernosal artery thrombosis. The degree of ischemia is a function of the number of emissary veins involved and the duration of occlusion","pyqMatches":[{"year":"2014","no":1267,"q":"Persistent priapism is due to","o":["Sickle cell anaemia","Hairy cell leukaemia","Paraphimosis","Urethral stenosis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2650, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 210, '{"id":2650,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":210,"q":"The type of arteritis which may lead to myocardial infarction in children is","o":["Kawasaki disease","Takayasu arteritis","Polyarteritis nodosa","Microscopic polyangitis"],"a":0,"e":"Ans. is ''a'' i.e., Kawasaki disease o Kawasaki disease is an acute, self limited vasculitis of unknown etiology that occurs predominantly in infants and young children of all races. Coronary artery aneyrysms or ectasia develops in 15-25% of untreated children with the disease and may lead to ischemic heart disease, myocardial infarction, or even sudden death. In the USA, Kawasaki disease has surpassed acture rheumatic fever as teh leading cause of acquited heart disease in children","pyqMatches":[{"year":"2014","no":1268,"q":"The type of arteritis which may lead to myocardial infarction in children is","o":["Kawasaki disease","Takayasu arteritis","Polyarteritis nodosa","Microscopic polyangitis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2651, 'Medicine', 'Rheumatology', 'Easy', 'Internal_Medicine', 211, '{"id":2651,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":211,"q":"Onion skin spleen is seen in","o":["ITP","Thalassemia","SLE","Scleroderma"],"a":2,"e":"Ans. is ''c'' i.e., SLE The characterisitc histopathologic picture of the spleen in SLE is periaterial fibrosis or anion skin lesion. First described by Libman and Sacks, this lesion is defined as the presene of 3 to as many as 20 seperated layers of the normally densely packed periarterial collagen of the penicillary or follicular arteries producing the appearance of concentric rings (onion peel).","pyqMatches":[{"year":"2014","no":1269,"q":"Onion skin spleen is seen in","o":["ITP","Thalassemia","SLE","Scleroderma"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2652, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 212, '{"id":2652,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":212,"q":"Most common pulmonary manifestation in AIDS","o":["TB","Pneumonia","Bronchiectasis","Mycobacterial avium intracellular"],"a":1,"e":"Ans. is ''b'' i.e., Pneumonia Respiratory complications in AIDS Respiratory diseases in AIDS include A) Acute bronchitis and sinusitis They are caused by S. pneumoniae and H influenzae and are very common. B) Pulmonary diseases Pulmonary diseases are :-","pyqMatches":[{"year":"2014","no":1270,"q":"Most common pulmonary manifestation in AIDS","o":["TB","Pneumonia","Bronchiectasis","Mycobacterial avium intracellular"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2653, 'Medicine', 'Nephrology', 'Hard', 'Internal_Medicine', 213, '{"id":2653,"subject":"Medicine","chapter":"Nephrology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":213,"q":"Chronic hemodialysis in ESRD patient is done","o":["Once per week","Twice per week","Thrice per week","Daily"],"a":2,"e":"Ans. is ''c'' i.e., Thrice per week For the majority of patients with ESRD, between 9 and 12 h of dialysis are required each week, usually divided into three equal sessions. Current targets of hemodialvsis Urea reduction ratio (the fractional reduction in blood urea nitrogen per hemodialysis session) of > 65-70%. Body water-indexed clearance x time product (KT/V) above 1.2 or 1.05.","pyqMatches":[{"year":"2014","no":1272,"q":"Chronic hemodialysis in ESRD patient is done","o":["Once per week","Twice per week","Thrice per week","Daily"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2654, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 214, '{"id":2654,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":214,"q":"Interstitial nephritis is common with","o":["NSAID","Black water fever","Rhabdomyolysis","Tumor lysis syndrome"],"a":0,"e":"Ans. is ''a'' i.e., NSAID DRUGS CAUSING INTERSTITIAL NEPHRITIS Antibiotics Diuretics AnticonvulsantsMiscellaneous β Lactams Thiazide Phenytoin Captopril Sulfonamides Furosemide Phenobarbitone H2 receptor blockers Quinolones TriamtereneCarbamazepine Omeprazole Vancomycin NSAIDS Valproic acid Mesalazine Erythromycin Indinavir Minocycline Allopurinol Rifampicin Ethambutol Acyclovir","pyqMatches":[{"year":"2013","no":1281,"q":"Interstitial nephritis is common with","o":["NSAID","Black water fever","Rhabdomyolysis","Tumor lysis syndrome"],"a":0,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":1273,"q":"Interstitial nephritis is common with","o":["NSAID","Black water fever","Rhabdomyolysis","Tumor lysis syndrome"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2655, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 215, '{"id":2655,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":215,"q":"Best test for lung fibrosis","o":["Chest x-ray","MRI","HRCT","Biopsy"],"a":2,"e":"Ans. is ''c'' i.e., HRCT Lung fibrosis is a diffuse parenchymal lung disease. Idiopathic pulmonary fibrosis is the most common form of idiopathic interstitial pneumonia. We have already discussed that best investigation for interstitial lung disease is HRCT Estimated relative frequency of the interstitial lung disease Diagnosis Relative frequency, % Idiopathic interstitial pneumonias 40 Idiopathic pulmonary fibrosis 55 Nonspecific interstitial pneumonia 25 Respiratory bronchiolitis-ILD and 15 Cryptogenic organizing pneumonia 3 Acute interstitial pneumonia <1 Occupational and environmental 26 Sarcoidosis 10 Sarcoidosis 10 Connective tissue diseases 9 Drug and radiation 1 Pulmonary hemorrhage syndromes <1 Other 13","pyqMatches":[{"year":"2013","no":1270,"q":"Best test for lung fibrosis","o":["Chest x-ray","MRI","HRCT","Biopsy"],"a":2,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":1275,"q":"Best test for lung fibrosis","o":["Chest x-ray","MRI","HRCT","Biopsy"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2656, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 216, '{"id":2656,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":216,"q":"Which of the following is a Channelopathy","o":["Ataxia Telangiectasia","Frederich Ataxia","Spinocerebellar ataxia","Anderson Tawil Syndrome"],"a":3,"e":"Ans. is ''d'' i.e., Anderson Tawil Syndrome Anderson syndrome (Anderson-Tawi syndrome) is a potassium channel channelopathy.","pyqMatches":[{"year":"2013","no":379,"q":"Which of the following is a Channelopathy","o":["Ataxia Telangiectasia","Frederich Ataxia","Spinocerebellar ataxia","Anderson Tawil Syndrome"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2657, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 217, '{"id":2657,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":217,"q":"Good syndrome is","o":["Thymoma with immunodeficiency","Thymoma with M. Gravis","Thymoma with serum sickness","Thymoma with pure red cell aplasia"],"a":0,"e":"Ans. is ''a'' i.e., Thymoma with immunodeficiency Good''s syndrome (thymoma with immunodeficiency) is a rare cause of combined B and T cell immunodeficiency in adults. Clinical features of Good''s syndrome are :- Increased susceptibility to bacterial infections with encapsulated organisms and opportunistic viral and fungal infection. The most consistent immunological abnormalities are :- Hypogammaglobulinaemia and Reduced or absent B cells Treatment Resection of the thymoma and immunoglobulin replacement to maintain adequate through IgG values","pyqMatches":[{"year":"2014","no":1279,"q":"Good syndrome is","o":["Thymoma with immunodeficiency","Thymoma with M. Gravis","Thymoma with serum sickness","Thymoma with pure red cell aplasia"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2658, 'Medicine', 'Infectious Diseases', 'Hard', 'Internal_Medicine', 218, '{"id":2658,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Hard","source":"Internal_Medicine","sourceNo":218,"q":"Patient diagnosed with HIV and Tuberculosis. How to start ATT and c- A.R.T","o":["Start ATT first","Start cART first","Start both simultaneously","Start cART only"],"a":0,"e":"Ans. is ''a'' i.e., Start ATT first In a case when HIV and TB are diagnosed together ATT should be started first. ATT started first, because of IRIS (Immune Reconstitution Inflammatory syndrome). If ART started first, it may improve CD4 cells at first, but later a previously acquired infection (TB, Herpes), responds with an overshelming inflammatory response that paradoxically makes the symptom of infection worse. Therefore, starting of ATT-2 weeks before ART, have shown to decrease the incidence of IRIS.","pyqMatches":[{"year":"2014","no":1283,"q":"Patient diagnosed with HIV and Tuberculosis. How to start ATT and c- A.R.T","o":["Start ATT first","Start cART first","Start both simultaneously","Start cART only"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2659, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 219, '{"id":2659,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":219,"q":"Most common cause of lung abscess","o":["Staph aureus","Oral anaerobes","Klebsiella","Tuberculosis"],"a":1,"e":"Ans. is ''b'' i.e., Oral Anaerobes Most nonspecific lung abscesses are presumed to be due to anaerobic bacteria.","pyqMatches":[{"year":"2014","no":1284,"q":"Most common cause of lung abscess","o":["Staph aureus","Oral anaerobes","Klebsiella","Tuberculosis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2660, 'Medicine', 'Rheumatology', 'Easy', 'Internal_Medicine', 220, '{"id":2660,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":220,"q":"Normal CRP with elevated ESR seen in","o":["RA","SLE","Scleroderma","Polymyalgia rheumatica"],"a":1,"e":"Ans. is ''b'' i.e., SLE Both ESR and CRP are markers of inflammation Erythrocyte sedimentation rate or ESR is used to separate inflammation from non-inflammation. Another sign of inflammation is the rise in blood level of number of proteins called as acute phase proteins. One of the proteins is C-reactive protein (CRP). Like ESR and other acute phase proteins, CRP also goes up in inflammation. In systemic lupus however the level does not rise unless there is infection associated. The normal response to active inflammatory disease is an increase in plasma CRP concentration. o For reasons that remain unclear tht response is either significantly lower in magnitude or entirely absent in a few inflammatory conditions. This has proven diagnostically useful because there are very few inflammatory conditions in which ESR is significantly raised (reflecting an inflammatory process) but plasma CRP is only slightly raised or even normal. One ofthese conditions is systemic lupus erythematosus (SLE or lupus), a relatively common chronic autoimmune disease that predominantly affects women of child-bearing age. When this inflammation occurs in the lupus patient it is accompanied as expected by a marked increase in ESR. However in contrst to most other inflammatory condition, the plasma CRP remains resolutely normal. The combination of raised ESR and normal CRP is a useful diagnostic feature of SLE. Other disorders where CRP is not increased Osteoarthritis, leukemia, anemia Polycythemia, viral infection Ulcerative colitis, pregnancy, estrogen","pyqMatches":[{"year":"2014","no":1285,"q":"Normal CRP with elevated ESR seen in","o":["RA","SLE","Scleroderma","Polymyalgia rheumatica"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2661, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 221, '{"id":2661,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":221,"q":"Restrictive and constrictive pericarditis occurs together in","o":["Radiation","Adriamycin","Amyloidosis","Post cardiotomy syndrome"],"a":0,"e":"Ans. is ''a'' i.e., Radiation Progressive fibrosis can cause restrictive myocardial disease without dilation. Thoracic radiation, common for breast and lung cancer or mediastinal lymphoma, can produce early or late restrictive cardiomyopathy. Patients with radiation cardiomyopathy may present with a possible diagnosis of contrictive pericarditis, as the two conditions often coexist.","pyqMatches":[{"year":"2014","no":1287,"q":"Restrictive and constrictive pericarditis occurs together in","o":["Radiation","Adriamycin","Amyloidosis","Post cardiotomy syndrome"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2662, 'Medicine', 'Respiratory Medicine', 'Moderate', 'Internal_Medicine', 222, '{"id":2662,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":222,"q":"All form boundaries of triangle of auscultation except","o":["Trapezius","Latissmusdorsi","Scapula","Rhomboid major"],"a":3,"e":"Ans. is ''d'' i.e., Rhomboid major Triangle of auscultation has the following boundaries Superiorly and medially, by the inferior portion of the Trapezius. Inferiorly, by the Latissimus Dorsi. Laterally, by the medial border of the scapula. The superficial floor of the triangle is formed by the Serratus anterior and the lateral portion of the erector spinae muscles. Deep to these muscles are the osseous portions of the 6\" and 7th ribs and the internal and external intercostal muscles. Typically, the Triangle of Auscultation is covered by the Scapula. To better expose the triangle and listen to respiratory sounds with a stethoscope, patients are asked to fold their arms across their chest, medially rotating the scapulae, while bending forward at the trunk, somewhat resembling a fetal position.","pyqMatches":[{"year":"2012","no":51,"q":"All form boundaries of triangle of auscultation except","o":["Trapezius","Latissmusdorsi","Scapula","Rhomboid major"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2663, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 223, '{"id":2663,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":223,"q":"Rytand''s murmur is seen in","o":["A-V Block","Mitral stenosis","Aortic stenosis","Aortic regurgitation"],"a":0,"e":"Ans. is ''a'' i. e.,A-V Block Rytand Murmur Rytan ''s murmur is mid-diastolic (or late-diastolic) murmur that is heard in patients with complete artioventricular heart block. Rytand''s murmur is best heard at the apex and may be confused with mitral stenosis. The slow heart rate, variable duration of the murmur changing intensity of the S I and lack of opening snap are helpful Also know Carey Coombs murmur → Rheumatic fever Austin Flint murmur → Aortic regurgitation Graham-Steel murmur → Pulmonary regurgitation Rytands murmur → Complete heart block Docks murmur → Left Anterior Descending (LAD) artery stenosis Mill wheel murmur → Due to air emboli (air in PV cavity)","pyqMatches":[{"year":"2014","no":1435,"q":"Rytand''s murmur is seen in","o":["A-V Block","Mitral stenosis","Aortic stenosis","Aortic regurgitation"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2664, 'Medicine', 'Endocrinology', 'Moderate', 'Internal_Medicine', 224, '{"id":2664,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":224,"q":"Not associated with diabetes mellitus","o":["Cushing syndrome","Acromegaly","Hypothyroidism","Pheochromocytoma"],"a":2,"e":"Ans. is ''c'' i.e., Hypothyroidism","pyqMatches":[{"year":"2015","no":1135,"q":"Not associated with diabetes mellitus","o":["Cushing syndrome","Acromegaly","Hypothyroidism","Pheochromocytoma"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2665, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 225, '{"id":2665,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":225,"q":"Fever increase water losses by mUday per degree Celsius","o":["100","200","400","800"],"a":1,"e":"Ans. is `b'' i.e., 200 ml/day per degree Celsius","pyqMatches":[{"year":"2013","no":113,"q":"Fever increase water losses by mUday per degree Celsius","o":["100","200","400","800"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2666, 'Medicine', 'Endocrinology', 'Easy', 'Internal_Medicine', 226, '{"id":2666,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":226,"q":"Most common cause of hypernatremia","o":["Adipsic diabetes insipidus","Carcinoid syndrome","Renal losses","Sweating"],"a":2,"e":"Ans. is `c'' i.e., Renal losses Major causes of hypernatremia Unreplaced water loss (which requires an impairment in either thirst or access to water) Insensible and sweat losses Gastrointestinal losses Central or nephrogenic diabetes insipidus o Osmotic diuresis Glucose in uncontrolled diabetes mellitus Urea in high-protein tube feedings Mannitol Hypothalamic lesions impairing thirst or osmoreceptor function Primary hypodipsia Reset osmostat in mineralocorticoid excess Water loss into cells Severe exercise or seizures Sodioutn overload Intake or administration of hypertonic sodium solutions","pyqMatches":[{"year":"2014","no":1332,"q":"Most common cause of hypernatremia","o":["Adipsic diabetes insipidus","Carcinoid syndrome","Renal losses","Sweating"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2667, 'Medicine', 'Hematology', 'Easy', 'Internal_Medicine', 227, '{"id":2667,"subject":"Medicine","chapter":"Hematology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":227,"q":"Rarest type of Von Willebrand disease :","o":["vWD type 1","vWD type 2A","vWD type 2N","vWD type 3"],"a":3,"e":"Ans. is ''d'' i.e., vWD type 3 ConditionDefect vWD type 1 Mild to moderate quantitative deficiency of vWF (ie, about 20- 25% of normal levels). vWD type 2A The most common qualitative abnormality of vWF, is associated withselective loss of large and medium-sized multimers vWD type 2B Loss of only large multimers as mutant vWF spontaneously binds to Gplb in the absence of subendothelial contact vWD type 2N Characterized by a defect residing within the patient ''s plasma vWF that interferes with its ability to bind FVIII vWD type 2M Involves qualitative variants with decreased platelet-dependent function not resulting from absence of highmolecular weight multimers vWD type 3 A severe, quantitative deficiency associated with very little or no detectable plasma or platelet vWF, have a profound bleeding disorder","pyqMatches":[{"year":"2014","no":1291,"q":"Rarest type of Von Willebrand disease :","o":["vWD type 1","vWD type 2A","vWD type 2N","vWD type 3"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2668, 'Medicine', 'Hematology', 'Hard', 'Internal_Medicine', 228, '{"id":2668,"subject":"Medicine","chapter":"Hematology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":228,"q":"A patient has ecchymosis and petechiae all over the body with no hepato- splenomegaly. All are true except","o":["Increased megakaryocytes in bone narrow","Bleeding into the joints","Decreased platelet in blood","Disease resolves itself in 80% of Patients in 2-6"],"a":1,"e":"Ans. is ''b'' i.e., Bleeding into the joints Features of Acute and Chronic Idiopathic Thrombocytopenic Purpura Feature Acute ITP Chronic ITP Peak age of incidence Children 2-6 year Adults, 20-40 year Sex predilection None 3:1 female to male Antecedent infection Common 1-2 week Unusual Onset of bleeding Before Abrupt Insidious Hemorrhagic bullae in mouth Present in severe cases Usually absent Platelet count < 20000/4 3000-80000/8L Eosinophilia and yphocytosis Common Rare Spontaneous remission Occurs in 80% cases Months or years Uncommon","pyqMatches":[{"year":"2014","no":1292,"q":"A patient has ecchymosis and petechiae all over the body with no hepato-splenomegaly. All are true except","o":["Increased megakaryocytes in bone narrow","Bleeding into the joints","Decreased platelet in blood","Disease resolves itself in 80% of Patients in 2-6"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2669, 'Medicine', 'Rheumatology', 'Moderate', 'Internal_Medicine', 229, '{"id":2669,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":229,"q":"All of the following are true about Rheumatoid arthritis, except","o":["PIP and DIP joints involved equally","Pathology limited to articular cartilage","Women are affected 3 times more commonly than men","20% of patients have extra articular manifestations"],"a":3,"e":"Ans. is ''d'' i.e., 20% of patients have extra articular manifestations Association of Rheumatoid Arthritis with HLA DR-4 The class II major histocompatibility complex allele HLA-DR4 and related alleles are known to be a major genetic risk factor for Rheumatoid arthritis. Rheumatoid Arthritis is strongly associated with HLA DR4 The genetic risk for Rheumatoid arthritis is associated with allelic variation in the HLA-DRBI \"gene i.e. DRB1 0401, 04, 05\". Some of the HLA DRB1 alleles bestow a high risk of disease Clinical features: It occurs between the age of 20 to 50 years. Women are affected about 3 times more commonly than men. Following presentations are common: a) An acute, symmetrical polyarthritis: Pain and stiffness in multiple joints (at least four) Symptoms of articular inflammation. Common in- MP joints of hand PIP joints of fingers Wrists, knees, elbows, ankles","pyqMatches":[{"year":"2014","no":1294,"q":"All of the following are true about Rheumatoid arthritis, except","o":["PIP and DIP joints involved equally","Pathology limited to articular cartilage","Women are affected 3 times more commonly than men","20% of patients have extra articular manifestations"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2670, 'Medicine', 'Hematology', 'Moderate', 'Internal_Medicine', 230, '{"id":2670,"subject":"Medicine","chapter":"Hematology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":230,"q":"Development of Lymphoma in Sjogren''s syndrome is suggested by all of the following except","o":["Persistent parotid gland enlargement","Cyoglobilinemia","Leukopenia","High C4 compement levels"],"a":3,"e":"Ans. is ''d'' i.e., High C4 complement levels Lymphoa is a well-known complication of Sjogren''s syndrome Most lymphomas are extra-nodal, low grade marginal B cell lymphomas. Development of Lymphoma in Sjogren''s syndrome is suggested by low C4 complement levels. Lymphoma in Sjogren''s syndrome The development ofLymphomas in patients with Sjogren syndrome is suggested by : - Persistent parotid gland enlargement Purpura Leukopenia Cryoglobulinemia Low C4 complement levels","pyqMatches":[{"year":"2014","no":1293,"q":"Development of Lymphoma in Sjogren''s syndrome is suggested by all of the following except","o":["Persistent parotid gland enlargement","Cyoglobilinemia","Leukopenia","High C4 compement levels"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2671, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 231, '{"id":2671,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":231,"q":"Hemodialysis can be performed for long periods from the same site due to","o":["Arteriovenous fistula reduces bacterial contamination of site","Arteriovenous fistula results in arterialization of vein","Arteriovenous fistula reduces chances of graft failure","Aretiovenous fistula facilitates small bore needles for high flow rates"],"a":1,"e":"Ans. is ''b'' i.e., Arteriovenous fistula results in arterialization of vein The tstu/a graft, or catheter hemodialvsis is often referred to as a dialysis access. A native fistula created by the anastomosis of an artery to a vein (e.g. the Bresica-Cimino fistula, in which the cephalic vein is anastomosed end-to-side to the radial artery) results in arterialization of the vein. This facilitates its subsequent use in the placement of large needles (typically 15 Gauge) to access the circulation. Fistulas have the highest long-term patency rate of all dialysis access options. The most important complication of arteriovenous grafts is thrombosis of the graft and graft failure, due principally to intimal hyperplasia at the anastomosis between the graft and recipient vein. Many patients undergo placement of an arteriovenous graft (i.e., the interposition of prosthetic material, usually polytetrafluoroethylene, between an artery and a vein) or a tunneled dialysis catheter.","pyqMatches":[{"year":"2014","no":1297,"q":"Hemodialysis can be performed for long periods from the same site due to","o":["Arteriovenous fistula reduces bacterial contamination of site","Arteriovenous fistula results in arterialization of vein","Arteriovenous fistula reduces chances of graft failure","Aretiovenous fistula facilitates small bore needles for high flow rates"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2672, 'Medicine', 'Respiratory Medicine', 'Hard', 'Internal_Medicine', 232, '{"id":2672,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Hard","source":"Internal_Medicine","sourceNo":232,"q":"In AIDS patient presenting with fever, cough a diagnosis of pneumocystin pneumonia is best established by","o":["CT scan chest","Bronchoalveolar lavage","Staining of intra-nuclear inclusion with silver staining","Aspiration and culture"],"a":1,"e":"Ans. is ''b'' i.e., Bronchoalveolar lavage Diagnosis of PCP requires Demonstration of the organism in samples obtained from induced sputum. Bronchoalveolar lavage, transbronchial biopsy, or open-lung biopsy. If the histological examination fails :? u PCR is required to make the diagnosis","pyqMatches":[{"year":"2014","no":1296,"q":"In AIDS patient presenting with fever, cough a diagnosis of pneumocystin pneumonia is best established by","o":["CT scan chest","Bronchoalveolar lavage","Staining of intra-nuclear inclusion with silver staining","Aspiration and culture"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2673, 'Medicine', 'Neurology', 'Hard', 'Internal_Medicine', 233, '{"id":2673,"subject":"Medicine","chapter":"Neurology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":233,"q":"The most common neurological disorder seen in CRF patients","o":["Dementia","Peripheral neuropathy","Bakes intestinal dilator.","Restless leg syndrome"],"a":1,"e":"Ans. is ''b'' i.e., Peripheral neuropathy Peripheral neuropathy is the most common neurological problem in CRF, which may be? i) Uremic peripheral neuropathy (due to uremia). ii) More often a presenting feature of the cause of CRF Diabetic neuropathy (DM is the most common cause of CRF).","pyqMatches":[{"year":"2014","no":1298,"q":"The most common neurological disorder seen in CRF patients","o":["Dementia","Peripheral neuropathy","Bakes intestinal dilator.","Restless leg syndrome"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2674, 'Medicine', 'Nephrology', 'Hard', 'Internal_Medicine', 234, '{"id":2674,"subject":"Medicine","chapter":"Nephrology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":234,"q":"ECG image,U wave seen, patient is on furosemide & beta blocker. Diagnosis","o":["Hypocalcemia","Hypokalemia","Hyperkalemia","Hypercalcemia"],"a":1,"e":"Ans. is ''b'' i.e., Hypokalemia E.C.G. manifestations of electrolyte disorders Hvperkalemia A tall peaked and symmetrical T-waves is the first change seen on ECG in patients with hyperkalemia. o RR interval lengthens and QRS duration increases. Flattening or disappearance of P wave. ST elevation. Widening of the QRS complexes due to a severe conduction delay and may become ''sine wave''. The progresion and the severity of the E. C. G change do not correlate well with the serum potassiam concentration. Hvpokalemia Similar to hyperkalemia, hypokalemia produce changes on the E. C. G which are not necessary related to serum potassiam level. Depression of the ST segment Decrease in amplitude of T waves Increase in amplitude of U waves U and T wave merge in some cases to form a T-U wave which may be misdiagnosed as prolonged QT interval. P wave can become larger and wider and PR interval prolong slightly. QRS duration may increase when hypokalemia becomes more severe. Hvpocalcemia Prolongation of the QT interval Due to prolongation of the phase 2 of the ventricular action potential and lengthening of the ST segment while the T wave (which correlate with time for repolarisation remains unaltered). Hvpercalcemia Shortening of the QT interval (Primarily due to a decrease in phase 2 of the ventricular action potential and resultant decrease in ST segment duration). Iltpothermia Causes slow impulse conduction through all cardial tissues resulting in :? Prolongation of all the ECG intervals RR PR QRS'' QT There is also \"elevation of the J point\" (Only if the ST segment is unaltered producing characteristics T or osborne wave.)","pyqMatches":[{"year":"2013","no":1259,"q":"ECG image,U wave seen, patient is on furosemide & beta blocker. Diagnosis","o":["Hypocalcemia","Hypokalemia","Hyperkalemia","Hypercalcemia"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":1299,"q":"ECG image,U wave seen, patient is on furosemide & beta blocker. Diagnosis","o":["Hypocalcemia","Hypokalemia","Hyperkalemia","Hypercalcemia"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2675, 'Medicine', 'Endocrinology', 'Easy', 'Internal_Medicine', 235, '{"id":2675,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":235,"q":"In Zollinger Ellison syndrome what is raised?","o":["Insulin","VIP","Gastrin","Glucagon"],"a":2,"e":"Ans. is ''c'' i.e., Gastrin Zollinger Ellison syndrome ? Severe peptic ulcer disease secondary to gastric acid hypersecretion due to unregulated gastrin release from a non 13 cell endocrine tumour (gastrinoma), defines the components of Zollinger Ellison syndrome. Pathophysiology of Zollinger Ellison syndrome The driving force responsible for clinical manifestations of Zollinger Ellison syndrome is hypergastrinemia originating from Gastrinoma (autonomus neoplasm, non [3 cell neoplasm) Gastrinoma Hyper gastrinemia Hyper acidemia Peptic ulcer, erosive esophagitis and diarrhoea Other important characteristic of Gastrinoma o Over 80% of these tumours are seen in Gastrinoma triangle° (triangle formed between duodenum and pancreas) most of them are seen in the head of pancreas. o About 2/3''of these tumours are malignant°. o About one half of these tumours are multiple°. o About one fourth of the patients have multiple endocrine neoplasia (MEN I) syndrome with tumours of parathyroid, pituitary and pancreatic islets being present. Remember : Most common site of gastrinoma''s is → Duodenum (50-70%), (Pancreas 20-40%) Most common hormone to be secreted → ACTH besides gastrin is Most common site of peptic ulcers produced is → ls'' part of Duodenum. Most valuable provocative test in → The Secretin injection tests. identifying patients with ZES is Basal acid output is greater than 60% of out pu → BAO> MAO induced by maximal stimulation The term pancreatic endocrine tumour is misnomer because these tumours can occur either almost exclusively in the pancreas or at both pancreatic and extrapancreatic sites","pyqMatches":[{"year":"2012","no":1037,"q":"In Zollinger Ellison syndrome what is raised?","o":["Insulin","VIP","Gastrin","Glucagon"],"a":2,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":1300,"q":"In Zollinger Ellison syndrome what is raised?","o":["Insulin","VIP","Gastrin","Glucagon"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2676, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 236, '{"id":2676,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":236,"q":"Menke''s disease\" is a disease of","o":["Impaired zinc transport","Impaired copper transport","Impaired magnesium transport","Impaired molybdenum transport"],"a":1,"e":"Ans. is ''b'' i.e., Impaired copper transport Menke''s disease is caused due to defect in the copper transport. There is defect in the transport of copper present in the intestinal mucosa to the blood stream. The mucosal lining of intestine contains high level of copper bound to metallothionein protein. Rather than being transporated to bloodstream, the copper remained in the mucosa and was lost when intestinal cells were naturally soughed off. Menkes disease is caused due to defect in the \"MNK\" gene. The protein normally function by moving copper from the intestinal mucosal cells into the blood stream, where it is hound by proteins such as albumin and transported to organs and tissues. Serum copper is critical for the functioning of several enzymes Lysyl oxidase → It is important for the cross linking of collagen and elastin such that deficiencies lead to problems in connective tissues such as bones Cytochrome oxidase → Involved in temperature maintenance Tyrosinase → Necessary for pigmentation Clinical features of menkes disease Growth retardation Coarse hair, brittle and ivory white (result of depigmentations). The hair fibres are twiisted and broken helically (kinky hair). Seizures Cerebral and cerebellar degeneration (postmortem analysis) Hypothermia Thrombosis Poor bone development Increased tendency towards aneurysms","pyqMatches":[{"year":"2014","no":1301,"q":"Menke''s disease\" is a disease of","o":["Impaired zinc transport","Impaired copper transport","Impaired magnesium transport","Impaired molybdenum transport"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2677, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 237, '{"id":2677,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":237,"q":"Anosmia is early clinical feature of","o":["Alzheimer","Parkinson''s disease","Huntington''s chorea","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above Main causes of anosmia Main causes of anosmia Nasal. Smoking. Chronic rhinitis (allergic, atrophic, cocaine, infectious-Herpes, influenza). Overuse of nasal vasoconstrictors. Olfactory epithelium. Head injury with tearing of olfactory, filaments Cranial surgery. Subarachnoid hemorrhage, meningitis. Toxic (organic solvents, certain antibiotics-am inoglycosides, tetracyclines, corticosteroids, methotrexate, opiates, 1-dopa). Metabolic (thiamine deficiency, adrenal and thyroid deficiency, cirrhosis, renal failure, menses). Wegener granulomatosis. Compressive and infiltrative lesions (craniopharyngioma, meningioma, aneurysm, meningoencephalocele). Degenerative disease (Parkinson, Alzheimer, Huntington Temporal lobe epilepsy. Malingering and hysteria","pyqMatches":[{"year":"2014","no":1302,"q":"Anosmia is early clinical feature of","o":["Alzheimer","Parkinson''s disease","Huntington''s chorea","All of the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2678, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 238, '{"id":2678,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":238,"q":"DOC of GTCS in pregnancy","o":["Lamotrigine","CBZ","Levetiracetam","Valproate"],"a":0,"e":"Ans. is ''a'' i.e., Lamotrigine Lamotrigine is often better tolerated and is less teratogenic than valproate. Lamotrigine has been increasingly prescribed in pregnancy over older antiepileptic drugs such as carbamazepine and sodium valproate.","pyqMatches":[{"year":"2013","no":1240,"q":"DOC of GTCS in pregnancy","o":["Lamotrigine","CBZ","Levetiracetam","Valproate"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2679, 'Medicine', 'Respiratory Medicine', 'Hard', 'Internal_Medicine', 239, '{"id":2679,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Hard","source":"Internal_Medicine","sourceNo":239,"q":"A Patient with history of shortness of breath has Decreased FEV1/FVC Ratio, Normal DLCO. A 200 ml increase in baseline FEVI is observed 15 minutes after administration of bronchodilators. The likely diagnosis is","o":["Asthma","Chronic Bronchitis","Emphysema","Interstitial Lung Disease"],"a":0,"e":"Ans. is ''a'' i.e., Asthma Diagnosis of Asthma require Demonstration of Airways obstruction Decrease in the ratio of FEVI/FVC Demonstration of acute reversibility of airflow Administer 2-4 puffs of quick acting bronchodilator e.g., albuterol and repreat spirometry 10- 15 min An increase in FEV1 of 12% or more accompanied by an absolute increase in FEV lof at least 20 ml A bronchoprovocator (Methacholine) is administered hyperresponsiveness of the airway is demonstrated by reduction of FEV1 to 20%","pyqMatches":[{"year":"2014","no":1282,"q":"A Patient with history of shortness of breath has Decreased FEV1/FVC Ratio, Normal DLCO. A 200 ml increase in baseline FEVI is observed 15 minutes after administration of bronchodilators. The likely diagnosis is","o":["Asthma","Chronic Bronchitis","Emphysema","Interstitial Lung Disease"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2680, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 240, '{"id":2680,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":240,"q":"Pseudo-hemoptysis is seen mostly with","o":["Streptococcus","E. coli","Serratia marcescens","R.S.V"],"a":2,"e":"Ans. is ''C'' i.e., Serratia marcesens Pseudo-hemoptysis is expectoration of blood other than the respiratory tract i.e. GIT or blood draining from the larynx. Serratia marcescens is a cause of pseudohemoptysis.","pyqMatches":[{"year":"2014","no":1304,"q":"Pseudo-hemoptysis is seen mostly with","o":["Streptococcus","E. coli","Serratia marcescens","R.S.V"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2681, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 241, '{"id":2681,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":241,"q":"Finger is glove sign is seen in","o":["Pulmonary alveolar Proteinosis","Pneumocystis Carinii","Tuberculosis","Bronchocele"],"a":3,"e":"Ans. is ''d'' i.e., Bronchocele Rabbit ear appearance Mickey mouse appearance Toothpaste shaped opacities Y-shaped opacities V-shaped opacities Aetiology Obstructive In bronchial obstruction, the portion of the bronchus distal to the obstruction is dilated with the presence of mucous secretions (mucus plugging). Causes of bronchial obstruction include : Bronchial hamartoma Bronchial lipoma Bronchial carcinoid Bronchogenic carcinoma Congenital bronchial atresia (rarely) Non obstructive Causes include .- Asthma Allergic bronchopulmonary aspergillosis (ABPA) Cystic fibrosis","pyqMatches":[{"year":"2014","no":1305,"q":"Finger is glove sign is seen in","o":["Pulmonary alveolar Proteinosis","Pneumocystis Carinii","Tuberculosis","Bronchocele"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2682, 'Medicine', 'Hematology', 'Easy', 'Internal_Medicine', 242, '{"id":2682,"subject":"Medicine","chapter":"Hematology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":242,"q":"Which of the following disorders is least likely associated with progression to lymphoma","o":["Sjogren''s syndrome","Araxia telangiectasia","Severe combined immunodeficiency","Lynch II syndrome"],"a":2,"e":"Ans. is ''c'' i.e., Severe combined immunodeficiency Choice Cancers associated Sjogren syndrome NHL mainly MALT-oma involving salivary glands>stomach Ataxia telengectasia Elevated incidence of cancers, approximately 100-fold in comparison to the general population. In children, more than 85% of neoplasm cases are acute lymphocytic leukemia or lymphoma. In adults with ataxia- telangiectaisa, solid tumors are more frequent Gastrointestinal cancer associated with Lynch-II syndrome associated with endometrial/ovarian carcinoma. Early onset brain tumor and lymphoma also seen in children","pyqMatches":[{"year":"2014","no":1306,"q":"Which of the following disorders is least likely associated with progression to lymphoma","o":["Sjogren''s syndrome","Araxia telangiectasia","Severe combined immunodeficiency","Lynch II syndrome"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2683, 'Medicine', 'Rheumatology', 'Moderate', 'Internal_Medicine', 243, '{"id":2683,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":243,"q":"Woman of 30-years with Raynaud''s phenomenon, polyarthritis, dysphagia of 5-years and mild Sclerodactyl, blood showing Anti-centromere antibody positive, the likely cause is","o":["CREST","Mixed connective tissue disorder","SLE","Rheumatoid arthritis"],"a":0,"e":"Ans. is ''a'' i.e., CREST The disease is divided into two categories :? 1) Diffuse scleroderma . There is wide-spread involvement of skin at onset. There is rapid progression with early visceral involvement. It is associated with Anti-DNA topoisomerase (anti-Scl 70) antibodies. 2) Limited (localized) scleroderma (morphea) . Skin involvement is confined to finges, forearm and face. It is associated with slow progression and late visceral involvement. Some patients develop CREST syndrome (Cacinosis, Raynaud''s phenomenon, esophageal dysmotility, sclerodactyly, and telangiactasia). It is associated with anticentromere antibodies.","pyqMatches":[{"year":"2014","no":1307,"q":"Woman of 30-years with Raynaud''s phenomenon, polyarthritis, dysphagia of 5-years and mild Sclerodactyl, blood showing Anti-centromere antibody positive, the likely cause is","o":["CREST","Mixed connective tissue disorder","SLE","Rheumatoid arthritis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2684, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 244, '{"id":2684,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":244,"q":"Most common mechanism of arrhythmia","o":["Re-entry","Early after depolarization","Late after depolarization","Automaticity"],"a":0,"e":"Ans. is ''a'' i.e., Re-entry The most common arrhythmia mechanism is re-entry. Fundamentally, re-entry is defined as the circulation of an activation wave around an inexcitable obstacle. Re-entry appears to be the basis for most abnormal sustained Supra Ventricular Tachycardias (SVTs) and Ventricular tachycardia. Examples of re-entry are:- Polymorphic Ventricular tachycardia in patients with a genetically determined ion channel abnormality such as the Brugada syndrome, catecholaminergic polymorphic Ventricular tachycardia.","pyqMatches":[{"year":"2014","no":1436,"q":"Most common mechanism of arrhythmia ?","o":["Re-entry","Early after depolarization","Late after depolarization","Automaticity"],"a":0,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":1090,"q":"Most common mechanism of arrhythmia","o":["Re-entry","Early after depolarization","Late after depolarization","Automaticity"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2685, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 245, '{"id":2685,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":245,"q":"-30 to -90 degree axis deviation indicates","o":["Left Axis Deviation","Right Axis Deviation","Extrene Right Axis Deviation","Normal Cardiac Axis"],"a":0,"e":"Ans. is ''a'' i.e., Left Axis Deviation Cardiac axis The electrical signal recorded on the electrocardiogram (ECG) contains information relative to direction and magnitude of the various complexes. The average direction of any of the complexes can be determined. Normal Cardiac Axis The normal QRS electrical axis, as established in the frontal plane, is between -30 and 90° (directed downward or inferior and to the left) in adults. Left Axis Deviation An axis between -30° and -90° (directed superior and to the left) is termed left axis deviation. Right Axis Deviation If the axis is between 90° and 180° (directed inferior and to the right), then right axis deviation is present. Extreme Right Axis Deviation An axis between -90'' and -180° (directed superior and to the right) is referred to as extreme right or left axis. Indeterminate If the QRS is equiphasic in all leads with no dominant QRS deflection, it is indeterminate axis. Causes of axis deviation include Right axis Left axis deviation deviation Normal variation (vertical heart with an axis of 90°) Normal variation (physiologic, often with age) Mechanical shifts, such as inspiration and emphysema Mechanical shifts, such as expiration, high diaphragm (pregnancy, ascites, abdominal tumor) Right ventricular hypertrophy Left ventricular hypertrophy Left posterior fascicular block Left bundle branch block Dextrocardia Left anterior fascicular block Ventricular ectopic rhythms Congenital heart disease (prim um atrial septal Hefect, endocardial cushion defect) Ventricular ectopic rhythms Emphysema Pre-excitation syndrome (Wolff- Parkinson-White Hyperkalemia Lateral wall myocardial infarction Ventricular ectopic rhythms Secundum atrial septal defect Pre-excitation syndromes (Wolff-Parkinson-White Inferior wall myocardial infarction","pyqMatches":[{"year":"2014","no":1437,"q":"30 to -90 degree axis deviation indicates","o":["Left Axis Deviation","Right Axis Deviation","Extrene Right Axis Deviation","Normal Cardiac Axis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2686, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 246, '{"id":2686,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":246,"q":"Which of the following is not a sign of upper motor neuron paralysis","o":["Babinski sign","Spastic paralysis","Denervation potential in EMG","Exaggeration of tendon reflexes"],"a":2,"e":"Ans. is ''c'' i.e., Denervation potential in EMG Difference between upper and lower motor neuron paralysis Upper motor neuron paralysis Lower motor neuron paralysis Muscles affected in groups never individual muscles Individual muscles may be affected o Atrophy slight and due to disuse Atrophy pronounced up to 70% of the total bulk Spasticity with hyperactivity of the tendon reflexes and Flaccidity and hypotoniaQ of affected muscles with loss of tendon reflexes Extensor plantar reflex (Babinski sign) Plantar reflex if present is of normal flexor type (Babinski sign) Fascicular twitches absent Fasciculation may be present Normal nerve conduction studies; no denervation potentials in E.M.G. Abnormal nerve conduction studies; denervation potential (fibrillations, fasciculations positive sharp waves) in EMG","pyqMatches":[{"year":"2014","no":1309,"q":"Which of the following is not a sign of upper motor neuron paralysis","o":["Babinski sign","Spastic paralysis","Denervation potential in EMG","Exaggeration of tendon reflexes"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2687, 'Medicine', 'Endocrinology', 'Easy', 'Internal_Medicine', 247, '{"id":2687,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":247,"q":"Most common oral infection in diabetes mellitus","o":["Candida","Aspergillus","Streptococcus","Stphylococcus"],"a":0,"e":"Ans. is ''a'' i.e., Candida Individuals with DM have a greater frequency and severity of the infection. The reasons for this include incompletely defined abnormalities in cell-mediated immunity and phagocyte function associated with hyperglycemia, as well as diminished vascularization. Hyperglycemia aids the colonization and growth of a variety of organisms (candida and other fungal species).","pyqMatches":[{"year":"2014","no":1311,"q":"Most common oral infection in diabetes mellitus","o":["Candida","Aspergillus","Streptococcus","Stphylococcus"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2688, 'Medicine', 'Neurology', 'Moderate', 'Internal_Medicine', 248, '{"id":2688,"subject":"Medicine","chapter":"Neurology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":248,"q":"All are features of hypernatremia except","o":["Convulsions","Elevated intracranial tension","Periodic paralysis","Doughy skin"],"a":2,"e":"Ans. is ''c'' i.e., Periodic paralysis Periodic paralysis, is seen in hyponatermia Clinical features of Hypernatremia :? Most patients with hypernatremia are dehydrated and have the typical signs and symptoms of dehydration. Hypernatremia even without dehydration causes central nervous system symptoms that tend to parallel the degree of sodium elevation and the acuity of the increase. Patients are irritable, restless weak and lethargic Some have high pitched cry and hyperpnea. Alert patient are very thirsty. Hypernatremia causes fever although many patients have underlying process that contributes to the fever Except for dehydration, there is no clear direct effect of hypernatremia on other organs or tissues except the brain. Complication of hypernatremia :? Brain hemorrhage is the most devastating consequence of hypernatremia. As the extracellular osmolarity increases water moves out of brain cells, resulting in decrease in brain volume. This can result in tearing of intra cerebral veins and bridging vessels as the brain moves away from the skull and the meninges. Patient may have subarachnoid, subdural and parenchymal hemorrhage. Seizure and coma are possible sequale of the hemorrhage even though seizures are more common during t/t. Thrombotic complications are common in severe hypernatremic dehydration and include stroke, dural sinus thrombosis, peripheral thrombosis and renal vein thrombosis. The intracranial tension can be increased due to hemorrhage","pyqMatches":[{"year":"2014","no":1313,"q":"All are features of hypernatremia except","o":["Convulsions","Elevated intracranial tension","Periodic paralysis","Doughy skin"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2689, 'Medicine', 'Dermatology & Allergy', 'Easy', 'Internal_Medicine', 249, '{"id":2689,"subject":"Medicine","chapter":"Dermatology & Allergy","difficulty":"Easy","source":"Internal_Medicine","sourceNo":249,"q":"Doughy skin and woody induration of tongue is seen in","o":["Hypernatremia","Hyponatremia","Hypokalemia","Hyperkalemia"],"a":0,"e":"Ans. is ''a'' i.e., Hypernatremia Because of intracellular water loss (hypernatremic dehydration), the pinched abdominal skin of a hypernatremic dehydrated patient has a \"doughy\" feel and there is dry woody tongue.","pyqMatches":[{"year":"2014","no":1312,"q":"Doughy skin and woody induration of tongue is seen in","o":["Hypernatremia","Hyponatremia","Hypokalemia","Hyperkalemia"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2690, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 250, '{"id":2690,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":250,"q":"Which of the following is MOST commonly affected by Crohn''s Disease","o":["Cecum","Rectum","Sigmoid colon","Terminal Ileum"],"a":3,"e":"Ans. is ''d'' i.e., Terminal ileum Inflammatory Bowel disease site of involvement Crohn''s Ulcerative cocitis Any part of the Gout from mouth to anus Limited to the colon Most commonly affected is small intestine particularly ileum Involves the entire colon starting from the rectum (retrograde manner) Terminal ileitis or Rectum is most commonly affected Granulomatous colitis Ileum not involved may get involvedmay get involved in some cases cases (backwash ileitis). Rectum spared Full thickness of the intestine involved but in patchy manner skip lesions","pyqMatches":[{"year":"2014","no":1314,"q":"Which of the following is MOST commonly affected by Crohn''s Disease","o":["Cecum","Rectum","Sigmoid colon","Terminal Ileum"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2691, 'Medicine', 'Infectious Diseases', 'Moderate', 'Internal_Medicine', 251, '{"id":2691,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":251,"q":"All of following cause intravascular hemolysis, except","o":["Mismatched blood transfusion","Paroxysmal cold hemoglobinuria","Thermal burns","Hereditary spherocytosis"],"a":3,"e":"Ans. is ''d'' i.e., Hereditary spherocytosis Blood transfusion ABO mismatched transfusion Infected blood Thermal burns Snake bites Sepsis Bacterial/parasitic infections Clostridial sepsis Malaria Bartonellosis Mycoplasma pneumoniae Mechanical heart valves Paroxysmal hemoglobinuria PNH PCH","pyqMatches":[{"year":"2014","no":1468,"q":"All of following cause intravascular hemolysis, except","o":["Mismatched blood transfusion","Paroxysmal cold hemoglobinuria","Thermal burns","Hereditary spherocytosis"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2692, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 252, '{"id":2692,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":252,"q":"Blood transfusion should be completed within hours of initiation","o":["1- 4 hours","3- 6 hours","4- 8 hours","8- 12 hours"],"a":0,"e":"Ans. is ''a'' i.e., 1-4 hours From starting the infusion (puncturing the blood with the infusion set) to completion, infusion pack should take a maximum of 4 hours.","pyqMatches":[{"year":"2013","no":1241,"q":"Blood transfusion should be completed within hours of initiation","o":["1- 4 hours","3- 6 hours","4- 8 hours","8- 12 hours"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2693, 'Medicine', 'Hematology', 'Easy', 'Internal_Medicine', 253, '{"id":2693,"subject":"Medicine","chapter":"Hematology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":253,"q":"Vitamin B level in chronic myeloid leukemia is","o":["Elevated''","Decreased","Normal","Markedly"],"a":0,"e":"Ans. is ''a'' i.e., Elevated CML there will be rise in B1, level LDH level And decreased levels of ALP.","pyqMatches":[{"year":"2014","no":1315,"q":"Vitamin B level in chronic myeloid leukemia is","o":["Elevated''","Decreased","Normal","Markedly"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2694, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 254, '{"id":2694,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":254,"q":"Which is the most common organ involved in sarcoidosis","o":["Lung","Liver","CNS","Eye"],"a":0,"e":"Ans. is ''a'' i.e., Lung Following organs are commonly affected :? 1) Lung and lymph nodes (95%) 2) Skin (24%-43%) 3) Eye (12-29%","pyqMatches":[{"year":"2014","no":1316,"q":"Which is the most common organ involved in sarcoidosis","o":["Lung","Liver","CNS","Eye"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2695, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 255, '{"id":2695,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":255,"q":"Following statements about sarcoidosis is false","o":["Elevated level of angiotensin converting enzyme (ACE)","Bilateral parotid enlargement is the rule","Pleural effusion is common","Facial nerve palsy may be seen"],"a":2,"e":"Ans. is ''c'' i.e., Pleural effusion is common Diffuse Effusion is an uncommon atypical manifestation in Sarcoidosis reported in up to 5% of patients. Parotid enlargement is a classic feature of sarcoidosis and bilateral involvement is the rule Neurological disease is reported in 5-10% of patients with sarcoidosis Facial nerve palsy is the single most common neurological manifestation of sarcoidosis seen in up to 50% of patients with Neurosarcoidosis. Angiotensin converting enzyme (ACE) levels are raised in sarcoidosis Lung involvement in sarcoidosis Most common involved organ (90%). Characterized by B/L hilar adenopathy. Cavitations are rare Pleural effusion are rare (1-2%)","pyqMatches":[{"year":"2014","no":1317,"q":"Following statements about sarcoidosis is false","o":["Elevated level of angiotensin converting enzyme (ACE)","Bilateral parotid enlargement is the rule","Pleural effusion is common","Facial nerve palsy may be seen"],"a":2,"source":"NEET_2014_Paper.pdf"},{"year":"2014","no":1318,"q":"Following statements about sarcoidosis is false","o":["The first manifestation of the disease is an accumulation of mononuclear inflammatory cells, mostly CD8 + THI lymphocytes in affected organs","The Heerfordt-Waldenstrom syndrome describes individuals with fever, parotid enlargement, anterior uveitis, and facial nerve palsy","Elevated level of angiotensin converting enzyme (ACE) are a feature","Bilateral parotid involment is the rule"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2696, 'Medicine', 'Neurology', 'Hard', 'Internal_Medicine', 256, '{"id":2696,"subject":"Medicine","chapter":"Neurology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":256,"q":"The most common cause of seizures in a patient of AIDS is","o":["Toxoplasmosis","Cryptococcal meningitis","Progressive multifocal leucoencephalopathy","CNS lymphoma"],"a":0,"e":"Ans. is ''a'' i.e., Toxoplasmosis Neurological manifestations of H.I.V. AIDS dementia complex (HIV encephalopathy) is a result of direct effects of HIV on CNS (not an opportunistic disease). It is subcortical dementia. Most common cause of seizures —> Toxoplasma Most common cause of meningitis —> Cryptococcus M.C. cause of focal neurological deficit —> Toxoplasma Toxoplasmosis is the most common CNS infection in AIDS. CNS lymphoma and prograssive multifocal leukoencephalopathy may occur.","pyqMatches":[{"year":"2014","no":1319,"q":"The most common cause of seizures in a patient of AIDS is","o":["Toxoplasmosis","Cryptococcal meningitis","Progressive multifocal leucoencephalopathy","CNS lymphoma"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2697, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 257, '{"id":2697,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":257,"q":"Gene responsible for resistance to rifampicin","o":["Rpo B gene","Kat G gene","Rpm B gene","Emb B gene"],"a":0,"e":"Ans. is ''a'' i.e., Rpo B gene ATT Drug Gene responsible for drug resistance INH inhA and Kat G gene Ethambutol emb B gene Rifampicin rpoB gene PyrazinamidepncA gene","pyqMatches":[{"year":"2014","no":1320,"q":"Gene responsible for resistance to rifampicin","o":["Rpo B gene","Kat G gene","Rpm B gene","Emb B gene"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2698, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 258, '{"id":2698,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":258,"q":"Lepsroy causes ?","o":["Membranous GN","Focal glomerulosclerosis","Membranoproliferative GN","Mesangioproliferative GN"],"a":0,"e":"Ans. is ''a'' i.e., Membranous GN Infectious diseases causing membranous GN • Hepatitis B and C • Hydatid disease •Leprosy • Filariasis • Syphilis •Enterococcal • Malaria • Endocarditis •Schistosomiasis","pyqMatches":[{"year":"2014","no":1487,"q":"Lepsroy causes ?","o":["Membranous GN","Focal glomerulosclerosis","Membranoproliferative GN","Mesangioproliferative GN"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2699, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 259, '{"id":2699,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":259,"q":"Nephrotic syndrome is the hall mark of the following primary kidney diseases except","o":["Membranous Glomerulopathy","IgA nephropathy","Minimal change disease","Focal segmental Glomerulosclerosis"],"a":1,"e":"Ans. is ''b'' i.e., IgA nephropathy Most common presentation of IgA nephropathy is grass hematuria. It is the most common form of glomerulonephritis worldwide Causes of Nephrotic syndrome Minimal change disease Focal segmental glomerulosclerosis o Membranous glomerulonephritis o Diabetes nephropathy AL and AA amyloidosis Light chain deposition disease Fibrillary immunotactoid disease","pyqMatches":[{"year":"2014","no":1488,"q":"Nephrotic syndrome is the hall mark of the following primary kidney diseases except","o":["Membranous Glomerulopathy","IgA nephropathy","Minimal change disease","Focal segmental Glomerulosclerosis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2700, 'Medicine', 'Rheumatology', 'Easy', 'Internal_Medicine', 260, '{"id":2700,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":260,"q":"Bechterews disease also known as","o":["Rheumatoid arthritis","Ankylosing spondylitis","Osteoarthritis","Syphilitic arthritis"],"a":1,"e":"Ans. is ''b'' i.e., Ankylosing spondylitis ANKYLOSING SPONDYLITIS (MARIE - STRUMPELL DISEASE) Ankylosing spondylitis is a chronic progressive inflammatory disease of the sacroiliac joints and the axial skeleton. Prototype of seronegative (absence of rheumatoid factor) spondyloarthropathies. Inflammatory disorder of unknown cause. Usually begins in the second or third decade with a median age of 23, in 5% symptoms begin after 40. o Male to female ratio is 2-3 : 1 Strong correlation with HLA-B27 90-95% of cases are positive for HLA B27. Joints involved in ankvlosing spondylitis Ankylosing spondylitis primarily affects axial skeleton. The disease usually begins in the sacro-iliac joints and usually extends upwards to involve the lumbar, thoracic, and often cervical spine. In the worst cases the hips or shoulders are also affected. Hip joint is the most commonly affected peripheral joint. o Rarely knee (Ebenzar 4thie 593) and ankle (Apley''s 9th/e 67) are also involved. Clinical features Low back pain of insidious onset Duration usually less than 3 months Significant morning stiffness and improvement with exercise o Limited chest expansion Diffuse tenderness over the spine and sacroiliac joints Loss of lumbar lordosis, increased thoracic kyphosis Decreased spinal movements (especially extension) in all directions. Radiological features of ankvlosing spondvlitis Radiographic evidence of sacroiliac joint is the most consistent finding in ankylosing spondylitis and is crucial for diagnosis. The findings are :? Sclerosis of the articulating surfaces of SI joints Widening of the sacroiliac joint space Bony ankylosis of the sacroiliac joints Calcification of the sacroiliac ligament and sacro-tuberous ligaments Evidence of enthesopathy - calcification at the attachment of the muscles, tendons and ligaments, particularly around the pelvis and around the heel. o X-ray of lumbar spine may show :- Squaring of vertebrae : The normal anterior concavity of the vertebral body is lost because of calcification of the anterior longitudinal ligament. Loss of the lumbar lordosis Bridging `osteophytes'' (syndesmophytes) Bamboo spine appearance","pyqMatches":[{"year":"2014","no":1321,"q":"Bechterews disease also known as","o":["Rheumatoid arthritis","Ankylosing spondylitis","Osteoarthritis","Syphilitic arthritis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2701, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 261, '{"id":2701,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":261,"q":"Comprehension in intact with aphasia in","o":["Wernicke''s","Broca''s","Global aphasia","Transcortical sensory"],"a":1,"e":"Ans. is ''b'' i.e., Broca''s","pyqMatches":[{"year":"2014","no":1260,"q":"Comprehension in intact with aphasia in","o":["Wernicke''s","Broca''s","Global aphasia","Transcortical sensory"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2702, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 262, '{"id":2702,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":262,"q":"Following statements about sarcoidosis is false","o":["The first manifestation of the disease is an accumulation of mononuclear inflammatory cells, mostly CD8 + THI lymphocytes in affected organs","The Heerfordt-Waldenstrom syndrome describes individuals with fever, parotid enlargement, anterior uveitis, and facial nerve palsy","Elevated level of angiotensin converting enzyme (ACE) are a feature","Bilateral parotid involment is the rule"],"a":0,"e":"Ans. is ''a'' i.e., The first manifestation of the disease is an accumulation of mononuclear inflammatory cells, mostly CD8 + THI lymphocytes in affected organs","pyqMatches":[{"year":"2014","no":1317,"q":"Following statements about sarcoidosis is false","o":["Elevated level of angiotensin converting enzyme (ACE)","Bilateral parotid enlargement is the rule","Pleural effusion is common","Facial nerve palsy may be seen"],"a":2,"source":"NEET_2014_Paper.pdf"},{"year":"2014","no":1318,"q":"Following statements about sarcoidosis is false","o":["The first manifestation of the disease is an accumulation of mononuclear inflammatory cells, mostly CD8 + THI lymphocytes in affected organs","The Heerfordt-Waldenstrom syndrome describes individuals with fever, parotid enlargement, anterior uveitis, and facial nerve palsy","Elevated level of angiotensin converting enzyme (ACE) are a feature","Bilateral parotid involment is the rule"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2703, 'Medicine', 'Miscellaneous', 'Hard', 'Internal_Medicine', 263, '{"id":2703,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Internal_Medicine","sourceNo":263,"q":"The treatment options for patients with RRMS (relapsing-remitting multiple sclerosis) are all except","o":["IFN - 1 b","IFN - 1 a","Glatiramer acetate","TNF - a"],"a":3,"e":"Ans. is ''d'' i.e., TNF - a Treatment of RRMS is divided into:- i) In acute attack: Corticosteroids are given ii) Prophylaxis of acute attack (relapse) during remission: Disease modifying agents for MS are used to reduce the biological activity. Treatment is started by IFN-P la or IFN-[31b or Glatiramer or fingalimod. If there is poor response or intolerance to these drugs, Natalizumab is started.","pyqMatches":[{"year":"2014","no":1322,"q":"The treatment options for patients with RRMS (relapsing-remitting multiple sclerosis) are all except","o":["IFN - 1 b","IFN - 1 a","Glatiramer acetate","TNF - a"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2704, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 264, '{"id":2704,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":264,"q":"DOC for Tourette syndrome","o":["Haloperidol","Valproate","B complex","Clonidine"],"a":3,"e":"Ans. is ''d'' i.e., Clonidine Earlier Haloperidol was considered as DOC for Tourette syndrome. Clonidine is considered as DOC for Tourette syndrome Treatment There''s no cure for Tourette syndrome. Treatment is aimed at controlling tics that interfere with everyday activities and functioning. When tics aren''t severe, treatment might not be necessary. Medication Medications that block or lessen dopamine. Fluphenazine, haloperidol (Haldol), risperidone (Risperdal) and pimozide (Orap) can help control tics. Botulinum (Botox) injections Central adrenergic inhibitors. Medications such as clonidine (Catapres, Kapvay) and guanfacine (Intuniv) — typically prescribed for high blood pressure — might help control behavioral symptoms such as impulse control problems and rage attacks. Antidepressants. Fluoxetine (Prozac, Sarafem, others) Antiseizure medications. Therapy Behavior therapy. Cognitive Behavioral Interventions for Tics, including habit-reversal training, can help you monitor tics, identify premonitory urges and learn to voluntarily move in a way that''s incompatible with the tic. Psychotherapy. In addition to helping you cope with Tourette syndrome, psychotherapy can help with accompanying problems, such as ADHD, obsessions, depression or anxiety. Deep brain stimulation (DBS). For severe tics that don''t respond to other treatment, DBS might help. DBS involves implanting a battery- operated medical device in the brain to deliver electrical stimulation to targeted areas that control movement.","pyqMatches":[{"year":"2014","no":1323,"q":"DOC for Tourette syndrome","o":["Haloperidol","Valproate","B complex","Clonidine"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2705, 'Medicine', 'Neurology', 'Moderate', 'Internal_Medicine', 265, '{"id":2705,"subject":"Medicine","chapter":"Neurology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":265,"q":"SSPE is not diagnosed by","o":["EEG","Antibodies to measles in CSF","Antibodies to measles in blood","Antigen in brain biopsy"],"a":2,"e":"Ans. is ''c'' i.e., Antibodies to measles in blood [Ref. Nelson l8n/e chapter 2431] The diagnosis of SSPE can be establisheil througlt documentation of a compatible clinical course and at least I of the following supportingfindings. Measles antibody detected in CSF. Characteristic electroencephalographic findings. Typical histologic fndings and/or isolation of viurs or viral antigen in brain tissue obtained by biopsy or post-mortem examination. CSF analysis reveals normal cells but elevated IgG and IgM antibody titers in dilutions of >1.8. Electroencephaloraphic patterns are normal in stagel, but in the myclonic phase suppression-burst episodes are seen that are characteristic ofbut not pathognomic for,SSPE. Brain biopsy is no longer routinely indicated for diagnosis o/SSPE.","pyqMatches":[{"year":"2014","no":1324,"q":"SSPE is not diagnosed by","o":["EEG","Antibodies to measles in CSF","Antibodies to measles in blood","Antigen in brain biopsy"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2706, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 266, '{"id":2706,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":266,"q":"Bronchiectasis Sicca is seen with","o":["Tuberculosis","Pertussis","Cystic fibrosis","Kartagener syndrome"],"a":0,"e":"Ans. is ''a'' i.e., Tuberculosis Bronchiectasis Sicca or Dry Bronchiectasis is typically associated with Tuberculosis. Tuberculosis is associted with a type of dry bronchiectasis called Bronchiectasis Sicca, which is predominantly seen in upper lobes. Dry Bronchiectasis (Bronchiectasis Sicca) is typically characterized by absence of copious amount of sputum which is usually a hall mark of bronchiectasis. Dry cough associated with hemoptysis is the typical presentation Endobronchial tuberculosis commonly leads to bronchiectasis, either from bronchial stenosis or secondary traction from fibrosis. Traction bronchiectasis characteristically affects peripheral bronchi (which lack cartilage support) in areas of end-stage fibrosis","pyqMatches":[{"year":"2014","no":1325,"q":"Bronchiectasis Sicca is seen with","o":["Tuberculosis","Pertussis","Cystic fibrosis","Kartagener syndrome"],"a":0,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":1079,"q":"Bronchiectasis Sicca is seen with","o":["Tuberculosis","Pertussis","Cystic fibrosis","Kartagener syndrome"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2707, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 267, '{"id":2707,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":267,"q":"Brock''s Syndrome is","o":["Bronchiectasis Sicca","Middle Labe Bronchiectasis","Kartagener''s Syndrome","Sarcoidosis"],"a":1,"e":"Ans. is ''b'' i.e., Middle Lobe Bronchiectasis Brock''s Syndrome Right middle lobe bronchiectasis occurring as a late sequel ofprimaiy tuberculosis is known as Brock''s syndrome or middle lobe syndrome. Brock''s syndrome is believed to be caused by pressure of lymph nodes in primary tuberculosis on the middle lobe bronchus. It has been described as a typical outcome of hilar node involvement by tuberculosis in childhood. This term is also applied to recurrent atelectasis of the right middle lobe in the absence of endobronchial obstruction. Bronchiectasis develops after recurrent episodes of atelectasis and fibrosis","pyqMatches":[{"year":"2014","no":1326,"q":"Brock''s Syndrome is","o":["Bronchiectasis Sicca","Middle Labe Bronchiectasis","Kartagener''s Syndrome","Sarcoidosis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2708, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 268, '{"id":2708,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":268,"q":"Central bronchiectasis is seen with","o":["Cystic Adenomatoid Malformation","Cystic fibrosis","Broncho carcinoma","Tuberculosis"],"a":1,"e":"Ans. is''b'' i.e., Cystic fibrosis The distribution ()I. bronchiectasis mar be important diagnostically A central → Perihilar allergic bronchopulmonary aspergillosis. Predominant upper lobe o Middle and lower lobe → Cystic fibrosis or one of its variants. Distribution is consistent with PCD Lower lobe involvement is → Middle lobe and lingular segment of the LUL involvement is characteristic of non tuberculous mycobacteria (NTM). Idiopathic bronchiectasis","pyqMatches":[{"year":"2015","no":1078,"q":"Central bronchiectasis is seen with","o":["Cystic Adenomatoid Malformation","Cystic fibrosis","Broncho carcinoma","Tuberculosis"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2709, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 269, '{"id":2709,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":269,"q":"Type 3 respiratory failure occurs due to ?","o":["Post-operative atelectasis","Kyphoscoliosis","Flail chest","Pulmonary fibrosis"],"a":0,"e":"Ans. is ''a'' i.e., Post-operative atelectasis","pyqMatches":[{"year":"2013","no":114,"q":"Type 3 respiratory failure occurs due to ?","o":["Post-operative atelectasis","Kyphoscoliosis","Flail chest","Pulmonary fibrosis"],"a":0,"source":"NEET_2013_Paper.pdf"},{"year":"2016","no":1081,"q":"Type 3 respiratory failure occurs due to ?","o":["Post-operative atelectasis","Kyphoscoliosis","Flail chest","Pulmonary fibrosis"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2013","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2710, 'Medicine', 'Gastroenterology', 'Moderate', 'Internal_Medicine', 270, '{"id":2710,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":270,"q":"Bilateral Painless parotid enlargement is seen in all except","o":["Mumps","Alcoholics","Sarcoidosis","Diabetes mellitus"],"a":0,"e":"Ans. is ''a'' i.e., Mumps Bilateral parotid enlargement is seen in Viral infectionQMetabolic causes Endocrinal Sarcoidosis Mumps Diabetes mcuitus Gonadal Amyloidosis Influenza HyperlipoproteinemiahypofunctionSjogren''s syndrome Epstein barr virus Chronic pancreatitis Acromegaly Coxackie virus A Hepatic cirrhosis CMV HIV","pyqMatches":[{"year":"2014","no":1328,"q":"Bilateral Painless parotid enlargement is seen in all except","o":["Mumps","Alcoholics","Sarcoidosis","Diabetes mellitus"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2711, 'Medicine', 'Rheumatology', 'Moderate', 'Internal_Medicine', 271, '{"id":2711,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":271,"q":"All of the following are features of Scleroderma are following except","o":["Diffuse periosteal reaction","Esophageal dysmotility","Erosion of tip of phalanges","Lung Nodular infiltrates"],"a":0,"e":"Ans. is ''a'' i.e., Diffuse periosteal reaction Skin involvement in systemic sclerosis Skin involvement is a nearly universal feature of systemic sclerosis (SSc). It is characterized by variable extent and severity of skin. Thickening and hardening. The fingers, hands, and face are generally the earliest areas of the body involved. Edematous swelling and erythema may preceede skin induration. Other prominent skin manifestations include : Pruritus in the early stages Edema in the early stages Sclerodactyly Digital ulcers Pitting at the fingertips Telangiectasia Calcinosis cutis Radiographs of the hands may reveal Soft tissue calcifications (calcinosis cutis). Resorption of the distal phalangeal tufts (acro-osteolysis). Less common radiographic findings are : Articular erosions Joint space narrowing Demineralization The symptoms of the female and presence of antinuclear antibody points towards the diagnosis of systemic sclerosis. It is a case of systemic sclerosis or scleroderma. The clues to the diagnosis of scleroderma are : Sclerodactyly Raynaud''s phenomenon Dysphagia Presence of antinuclear antibody Though systemic sclerosis is a multisystem disease, the two most distinguishing features of systemic sclerosis are: o Striking cutaneous changes Notable skin thickening. This is the most easily recognized manifestation of scleroderma. Raynaud''s phenomenon This is the first manifestation of disease in almost every patients. Dysphagia Attributable to esophageal fibrosis and its resultant hypomotlity is present in more than 50% of patients. Remember, Whenever skin thickening is present along with Raynaud''s phenomenon, it is almost always a case of scleroderma\". These two features are not present in any other multisystem disease whose clinical features overlap with that of systemic sclerosis e.g. SLE, rheumatoid arthritis, inflammatory myopathy, Sjogren syndrome\". Although skin changes and Raynaud''s phenomenon are the major diagnostic clues, scleroderma is a multisystem disease that most commonly targets peripheral circulation, muscles, joints, gastrointestinal tract, lung, heart and kidney. So, the symptoms encountered in early presentation of scleroderma include musculoskeletal discomfort, fatigue, weight loss, and heart burn and dysphagia associated with gastroesophageal reflex disease (GERD). When these symptoms are accompanied by the skin thickness and Raynaud c phenomenon, diagnosis ofscleroderma should be considered. Role of autoantibodies in the diagnosis of scleroderma Autoantibodies are found in nearly every patient with scleroderma (sensitivity >95%), but they are not specific for scleroderma0. Scleroderma is associated with wide array of autoantibodies. Two ANA''S which are more or less unique to scleroderma are: Antitopoisomerase antibody (20-40%) Seen in patients with diffuse systemic sclerosis Patients with this autoantibody are more likely to havepulmonary .fibrosis and peripheral vascular disease Patients with these autoantibodies have poor prognosis Anticentromere antibody (20-40%) These autoantibodies are seen in patients with limited systemic sclerosis","pyqMatches":[{"year":"2014","no":1308,"q":"All of the following are features of Scleroderma are following except","o":["Diffuse periosteal reaction","Esophageal dysmotility","Erosion of tip of phalanges","Lung Nodular infiltrates"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2712, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 272, '{"id":2712,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":272,"q":"LBBB is seen with all except","o":["Acute MI","Ashmann syndrome","Hypokalemia","Hyperkalemia"],"a":2,"e":"Ans. is ''c'' i.e., Hypokalemia Causes of LBBB are :- Aortic stenosis Ischaemic heart disease Hypertension Dilated cardiomyopathy Anterior MI Primary degenerative disease (fibrosis) of the conducting system (Lenergre disease) Hyperkalaemia Digoxin toxicity Ashmann phenomenon (has both LBBB and RBBB) Atrial fibrillation has a narrow complex qRS but Ashmann phenomenon seen in atrialfibrillation is characterized by broad complex qRS with usually a RBBB morphology. Thus if an impulse lands on the bundle of HIS and finds the right bundle refractory then RBBB will occur. Also remember that the refractory period of right fascicle ix more than that of the left fascicle resulting in RBBB mostly in these patients. ECG findings of LBBB Normally the septum is activated from left to right, producing small Q waves in the lateral leads. In LBBB, the normal direction of septal depolarisation is reversed (becomes right to left), as the impulse spreads first to the RV via the right bundle branch and them to the LV via the septum. This sequence of activation extends the qRS duration to > 120 ms and eliminates the normal septal Q waves in the lateral leads. The overall direction of depolarisation (from right to left) produces tall R waves in the lateral leads (IaVLV5V6) deep S waves in the right precordial leads (V4 R) and usually leads to left axis deviation. As the ventricles are activated sequentially (right, then left) rather than simultaneously, this produces a broad or notched (`W-shaped) R wave in the lateral leads. Non-concordance in ST segment and T wave changes. The point is that the two fasciles of bundle of his have different refractory periods with the right fascicle having higher refractory period than the left. This means that if an impulse lands on the bundle of HIS and finds the right bundle refractory then RBBB will occur. In atrial fibrillation because of faster conduction, normally we see narrow complex qRS but sometimes we may see broad complex qRS also which is technically called Ashmann phenomenon. Mostly in Ashmann phenomenon RBBB is seen based on the physiological principle of refractory period of right fascicle more than the left one. However, rarely LBBB can also be seen if the impulse lands to find the left fascicle refractory. Irrespective of RBBB or LBBB, broad complex qRS will occur in case of atrial fibrillation and Ashmann phenomenon is occurrence of broad complex qRS in atrial fibrillation and not the occurrence of RBBB as is the popular perception. Hyperkalemia can cause defective repolarization and hence cause Bundle branch block that culminates in sine wave pattern. In acute MI, ischemia can damage the left bundle leading to LBBB.","pyqMatches":[{"year":"2014","no":1439,"q":"LBBB is seen with all except","o":["Acute MI","Ashmann syndrome","Hypokalemia","Hyperkalemia"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2713, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 273, '{"id":2713,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":273,"q":"Therapeutic hypothermia is of benefit in preventing neurological complications in","o":["Sepsis","Poly-trauma","Cardiac arrest","lschemic stroke"],"a":2,"e":"Ans. is ''c'' i.e., Cardiac arrest Inducing mild therapeutic hypothermia in selected patients surviving out-of-hospital sudden cardiac arrest can significantly improve rates of long-term neurologically intact survival and may prove to be one of the important clinical advancements in the science of resuscitation. The types of medical events that hypothermic therapies may effectively treat fall into four primary categories: Cardiac arrest Ischemic stroke Trumatic brain or spinal cord injury without fever. Neurogenic fever following brain trauma","pyqMatches":[{"year":"2014","no":1329,"q":"Therapeutic hypothermia is of benefit in preventing neurological complications in","o":["Sepsis","Poly-trauma","Cardiac arrest","lschemic stroke"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2714, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 274, '{"id":2714,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":274,"q":"Distribution of weakness in Pyrimidal tract lesions?","o":["Extensors more than flexors in lower limb","Flexors more than extensors in upper limb","Antigravity muscles are affected","Antigravity muscles are spared"],"a":3,"e":"Ans. is ''d'' i.e., Antigravity muscles are spared The following clinical features characterize a UMN lesion: Increased tone (spasticitv) Initially, UMN weakness may be flaccid, with absent or diminished deep tendon reflexes. There is little understanding of the reasons behind this initial flaccidity and it is often referred to as ''shock''. Increased tone of a UMN type is called spasticity. It may develop several hours, days or even weeks after the initial lesion has occurred. Spasticity is manifested by : Spastic catch'' : Mild spasticity may be detected as a resistance to passive movement or ''catch'' in the pronators on passive supination of the forearm and in the flexors of the hand/forearm on extension of the wrist/elbow. The ''clasp-knife'' phenomenon: In more severe lesions, following strong resistance to passive flexion of the knee or extension of the elbow, there is a sudden relaxation of the extensor muscles of the leg and flexor muscles in the arm. Clonus: Rhythmic involuntary muscular contractions follow an abruptly applied and sustained stretch stimulus, e.g. at the ankle following sudden passive dorsiflexion of the foot. `Pyramidal-pattern'' weakness The antigravity muscles are preferentially spared and stronger The flexors of the upper limbs and the extensors of the lower limbs. The patient can develop a characteristic posture of flexed and pronated arms with clenched fingers, and extended and adducted legs with plantar flexion of the feet. In upper extremiteis Relative sparing of the flexors More involvement of the extensor In lower extremities Predominant invovlement of the flexors with Relative sparing of the extensor or Absence of muscle wasting and fasciculations Focal muscle wasting andjasciculations are features of an LMN lesion. With chronic disuse, some loss of muscle bulk can occur after a UMN lesion, but this is rarely severe or focal. Brisk tendon reflexes and extensor plantar responses The tendon reflexes are brisk. The cremasteric and abdominal or ''cutaneous'' reflexes are depressed or absent. The plantar responses are extensor (upgoing toes'' or ''positive'' babinski sign). Anti-gravity muscles are typically spared in pyramidal tract lesions. Weakness, in pyramidal tract lesions is often termed as ''pyramidal'' in distribution affecting extensors more than flexors in the upper limb, and flexors more than extensors in the lower limb (Anti-gravity muscles are spared). Pyramidal weakness → Loss of power most marked in the extensors muscles in the arms and flexors in the legs Proximal weakness → Shoulders, hips, trunks, neck and sometimes face. Associated with myopathy. Distal weakness → Affects hands and feets. Associated with peripheral motor neuropathy. Global weakness → Generalized weakness in limbs which may result from severe pathologies.","pyqMatches":[{"year":"2014","no":1330,"q":"Distribution of weakness in Pyrimidal tract lesions?","o":["Extensors more than flexors in lower limb","Flexors more than extensors in upper limb","Antigravity muscles are affected","Antigravity muscles are spared"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2715, 'Medicine', 'Endocrinology', 'Easy', 'Internal_Medicine', 275, '{"id":2715,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":275,"q":"Aldose reductase inhibitor drugs are useful in","o":["Cataract","Diabetes mellitus","Hereditary fructose intolerance","Essential fructosuria"],"a":1,"e":"Ans. is ''b'' i.e., Diabetes mellitus Aldose reductase catalyzes the NADPH-dependent conversion of glucose to sorbitol, the first step in polyol pathway of glucose metabolism. Aldose reductase inhibitors are a class of drugs being studied as a way to prevent eye and nerve damage in people with diabetes mellitus. Examples of aldose reductase inhibitors include: Tolrestat (withdrawn from market) Apalrestat Ranirestat Fidarestat","pyqMatches":[{"year":"2014","no":1331,"q":"Aldose reductase inhibitor drugs are useful in","o":["Cataract","Diabetes mellitus","Hereditary fructose intolerance","Essential fructosuria"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2716, 'Medicine', 'Endocrinology', 'Moderate', 'Internal_Medicine', 276, '{"id":2716,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":276,"q":"Not a cause of hypernatremia","o":["Adipsic diabetes insipidus","Decreased insensible losses","Nephrogenic diabetes insipidus","Carcinoid syndrome"],"a":1,"e":"Ans. is ''b'' i.e., Decreased insensible losses Major causes of hypernatremia Unreplaced water loss (which requires an impairment in either thirst or access to water) Insensible and sweat losses Gastrointestinal losses Central or nephrogenic diabetes insipidus Osmotic diuresis Glucose in uncontrolled diabetes mellitus Urea in high-protein tube feedings Mannitol Hypothalamic lesions impairing thirst or osmoreceptor function Primary hypodipsia Reset osmostat in mineralocorticoid excess Water loss into cells Severe exercise or seizures Sodioum overload Intake or administration of hypertonic sodium solutions","pyqMatches":[{"year":"2014","no":1333,"q":"Not a cause of hypernatremia","o":["Adipsic diabetes insipidus","Decreased insensible losses","Nephrogenic diabetes insipidus","Carcinoid syndrome"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2717, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 277, '{"id":2717,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":277,"q":"Backwash ileitis is seen in","o":["Ulcerative colitis","Crohn''s disease","Colonic carcinoma","heal polyp"],"a":0,"e":"Ans. is ''a'' i.e., Ulcerative colitis Ulcerative colitis always involves the rectum and extends proximally in continuous fashion to involve part or all part of the colon. Involvement of terminal ileum in ulcerative colitis is called backwash ileitis","pyqMatches":[{"year":"2014","no":1335,"q":"Backwash ileitis is seen in","o":["Ulcerative colitis","Crohn''s disease","Colonic carcinoma","heal polyp"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2718, 'Medicine', 'Infectious Diseases', 'Moderate', 'Internal_Medicine', 278, '{"id":2718,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":278,"q":"Which of the following is not seen in Hereditary Spherocytosis","o":["Direct Coomb''s Positive","Increased Osmotic Fragility","Splenomegaly","Gall stones"],"a":0,"e":"Ans. is ''a'' i.e., Direct Coomb''s positive Hereditary Spherocytosis Membrane cytoskeleton that lies closely opposed to the internal surface of the plasma membrane, is responsible for elasticity and maintenance of RBC shape. Membrane skeleton consists :? Spectrin → The chief protein component responsible for biconcave shape. Ankyrin and band 4-2 → Binds spectrin to band 3 Band 3 → A transmembrane ion transport protein. Band 4.1 → Binds spectrin to glycophorin A, atransmembrane protein. Hereditary spherocytosis is an autosomal dominant disorder characterized by intrinsic defects in red cell membrane. This results in production of red cells that are sphere (spherocytes) rather than biconcave. The mutation most commonly involves the gene coding for ankyrin, followed by Band-3 (anionic transport channel), spectrin, and Band 4.2 (also called palladin). Also know Most common, defect in hereditary elliptocytosis is in spectrin Pathogensis of Hereditary spherocytosis Loss of membrane cytoskeleton proteins (ankyrin, spectrin, Band 3, 4.2) results in reduced membrane stability. Reduced membrane stability leads to spontaneous loss of membrane fragments during exposure to shear stresses in the circulation. The loss of membrane relative to cytoplasm forces the cells to assume the smallest possible diameter for a given volume cells become microspherocytes. Because of their spheroidal shape and reduced membrane plasticity, red cells become less deformable and are trapped in to spleen as they are unable to pass through the interendothelial fenestrations of the venous sinusoids. In the splenic sinusoides, red cells are phagocytosed by RE cells Extravascular hemolysis. Clinical features of Hereditory spherocytosis The clinical features are those of extravascular hemolysis : Anemia → Mild to moderate Jaundice (Mainly indirect bilirubin) → Splenomegaly Gall stones → Elevated excretion of bilirubin promotes formation of pigment stone. Leg ulcer → Rare clinical manifestation. Aplastic crisis → Triggered by parvo- virus infection. Laboratory findings Spherocytosis --> Peripheral smear shows microspherocytes which are small RBCs without central pallor (Normally central 1/3 pallor is present in red cells). MCV4 MCHC r Increased unconjugate bilirubin Urine urobilinogen 1'' Stool stercobilinogen Reticulocytosis -4 As seen with any type of hemolytic anemia. Hemoglobin 1 Serum Heptoglobin --> Nonnal to decreased. Increased osmotic fragility on pink test. Coomb''s test is used to distinguish hereditary spherocytosis from autoimmune hemolytic anemias. Autoimmune hemolytic anemias are coomb''s positive_ whereas hereditary spherocytosis is coomb''s negative.","pyqMatches":[{"year":"2012","no":1056,"q":"Which of the following is not seen in Hereditary Spherocytosis","o":["Direct Coomb''s Positive","Increased Osmotic Fragility","Splenomegaly","Gall stones"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":1469,"q":"Which of the following is not seen in Hereditary Spherocytosis","o":["Direct Coomb''s Positive","Increased Osmotic Fragility","Splenomegaly","Gall stones"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2719, 'Medicine', 'Hematology', 'Easy', 'Internal_Medicine', 279, '{"id":2719,"subject":"Medicine","chapter":"Hematology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":279,"q":"Usually associated with parvovirus B19 infection in those with hereditary spherocytosis","o":["Mild to moderate splenomegaly","Aplastic crisis","Gallstones","Hemolytic crisis"],"a":1,"e":"Ans. is ''b'' i.e., Aplastic crisis Parvovirus B19 selectively infects erythroid precursors and is the most common aetiological agent that induces aplastic crisis in patients with hereditary spherocytosis (and other Hemolytic disorders). Transient aplastic crisis Persons with decreased erythrocytes caused by conditions such as iron deficiency anemia, human immunodeficiency virus sickle cell disease, spherocytosis or thalassemia are at risk of transient aplastic crisis if infected with parvovirus B19. The virus causes a cessation of erythrocyte production. Parvovirus infection may be the first manifestation in HS. It begins with reticulocytosis and thrombocytosis","pyqMatches":[{"year":"2014","no":1470,"q":"Usually associated with parvovirus B19 infection in those with hereditary spherocytosis","o":["Mild to moderate splenomegaly","Aplastic crisis","Gallstones","Hemolytic crisis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2720, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 280, '{"id":2720,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":280,"q":"Which of the following is given to treat thrombocytopenia secondary to anti- cancer therapy and is known to stimulate progenitor megakaryocytes","o":["Filgrastim","Oprelvekin","Erythropoietin","Anagrelide"],"a":1,"e":"Ans. is ''b'' i.e., Oprelvekin Oprelvekin ( IL-11) is used to prevent and treat thrombocytopenia. [Ref Harrison''s 18th chapter 85 and Katzung 11th 580-581]","pyqMatches":[{"year":"2014","no":1337,"q":"Which of the following is given to treat thrombocytopenia secondary to anti- cancer therapy and is known to stimulate progenitor megakaryocytes","o":["Filgrastim","Oprelvekin","Erythropoietin","Anagrelide"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2721, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 281, '{"id":2721,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":281,"q":"Lambda - Panda sign is typically seen in","o":["Sarcoidosis","Tuberculosis","Histoplasmosis","Leishmaniasis"],"a":0,"e":"Ans. is ''a'' i.e., Sarcoidosis Lambda sign and Panda sign on Gallium scan are typically described for sarcoidosis. Active pulmonary and/or mediastinal sarcoidosis is gallium avid and a positive gallium scan can support the diagnosis of sarcoidosis. Typical patterns of uptake have been described as ''panda'' and ''lambda'' signs. Lambda sign → Formed from increased uptake in bilateral hilar and right paratracheal nodes Panda sign → Formed from increased uptake in the parotids and lacrimal glands A Lambda sign in combination with a so-called Panda sign (Lambda- Panda Sign) is a highly specific pattern for sarcoidosis. The degree of uptake typically depends on the activity of disease and gallium scan is positive only in the setting of active parenchymal disease and negative in remission","pyqMatches":[{"year":"2014","no":1338,"q":"Lambda - Panda sign is typically seen in","o":["Sarcoidosis","Tuberculosis","Histoplasmosis","Leishmaniasis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2722, 'Medicine', 'Gastroenterology', 'Moderate', 'Internal_Medicine', 282, '{"id":2722,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":282,"q":"All are indications for stopping effending ATT drug permanently except","o":["Gout","Autoimmune thrombocytopenia","Optic neuritis","Hepatitis"],"a":3,"e":"Ans. is ''d'' i.e., Hepatitis For patients with symptomatic hepatitis and those with marked (five to six fold) elevations in serum levels of aspartate aminotransferase, treatment should be immediately stopped and drugs reintroduced one at a time after liver function has returned to normal. Indications for stopping the A.T.T. permanently Hyperuricemia and arthralgia Optic neuritis Autoimmune thrombocytopenia","pyqMatches":[{"year":"2014","no":1339,"q":"All are indications for stopping effending ATT drug permanently except","o":["Gout","Autoimmune thrombocytopenia","Optic neuritis","Hepatitis"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2723, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 283, '{"id":2723,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":283,"q":"Interferon gamma release assay measures IFN release against which M. TB antigen","o":["ESAT-6","E SAT-7","CF-11","CF-12"],"a":0,"e":"Ans. is ''a'' i.e., ESAT-6 3 Interferon-gamma release assays (IGRAs) are diagnostic tools for latent tuberculosis infection (LTBI). They are surrogate markers of Mycobacterium tuberculosis infection and indicate a cellular immune response to M. tuberculosis. a IGRAs cannot distinguish between latent infection and active tuberculosis (TB) disease and should not be used for diagnosis of active TB, which is a microbiological diagnosis. A positive IGRA result may not necessarily indicate active TB, and a negative IGRA result may not rule out active TB . 3 Because IGRAs are not affected by Bacille Calmette-Guerin (BCG) vaccination status, IGRAs are useful for evaluation of LTBI in BCG-vaccinated individuals, particularly in settings where BCG vaccination is administered after infancy or multiple (booster) BCG vaccinations are given. Assay antigens M. tuberculosis-specific antigens include :- Early secreted antigenic target 6 (ESAT-6) and Culture filtrate protein 10 (CFP-10). These are encoded by genes located within the region of difference 1 (RD1) segment of the M. tuberculosis genome. They are more specific for M. tuberculosis than purified protein derivative (PPD) because they are not shared with any BCG vaccine strains or most species of NTM other than M marinum, M. kansasii, M szulgai, and M. flavescens. Types of assays Two IGRAs are available in many countries :- The QuantiFERON-TB Gold In-Tube (QFT-GIT) assay, which has replaced the second-generation Quantiferon​TB Gold (QFT-G) assay, and the T-SPOTTB assay. The QFT-GIT assay is an enzyme-linked immunosorbent assay (ELISA)-based, whole-blood test that uses peptides from three TB antigens i.e., CFP-10, and TB7.7) in an in-tube format The result is reported as quantification of interferon (IFN)-gamma in international units (IU) per mL. A newer assay, the QuantiFERON-TB Gold Plus (QFT-Plus), became available in 2015. This test is available in Europe but not in North America. The QFT- Plus assay has two TB antigen tubes, unlike the QFT assay (which has a single TB antigen tube). Sensitivity and specificity IGRAs have specificity >95 percent for diagnosis of latent TB infection. The sensitivity for T-SPOTTB appears to be higher than for QFT-GIT or TST (approximately 90, 80, and 80 percent, respectively) [2]. The higher sensitivity of T-SPOTTB may be useful for evaluating individuals with immunosuppressive conditions. TST specificity is high in populations not vaccinated with BCG (97 percent). Among populations where BCG is administered, it is much lower although variable (approximately 60 percent).","pyqMatches":[{"year":"2014","no":1340,"q":"Interferon gamma release assay measures IFN release against which M. TB antigen","o":["ESAT-6","E SAT-7","CF-11","CF-12"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2724, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 284, '{"id":2724,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":284,"q":"The term end-stage renal disease (ESRD) is considered appropriate when GFR falls to","o":["50% of normal","25% of normal","10-25% of normal","5-10% of normal"],"a":3,"e":"Ans. is ''d'' i.e., 5-10% of normal","pyqMatches":[{"year":"2014","no":1489,"q":"The term end-stage renal disease (ESRD) is considered appropriate when GFR falls to","o":["50% of normal","25% of normal","10-25% of normal","5-10% of normal"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2725, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 285, '{"id":2725,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":285,"q":"Muehrcke lines in nails are seen in","o":["Nephrotic syndrome","Barrter syndrome","Nail patella syndrome","Acute tubular necrosis"],"a":0,"e":"Ans. is ''a'' i.e., Nephrotic syndrome Muehrcke''s lines are characteristic of hypoalbuminemia. Nephrotic syndrome causes hypoalbunemia.","pyqMatches":[{"year":"2014","no":1341,"q":"Muehrcke lines in nails are seen in","o":["Nephrotic syndrome","Barrter syndrome","Nail patella syndrome","Acute tubular necrosis"],"a":0,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":1606,"q":"Muehrcke lines in nails are seen in","o":["Nephrotic syndrome","Barrter syndrome","Nail patella syndrome","Acute tubular necrosis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2726, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 286, '{"id":2726,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":286,"q":"Not true obstructive sleep appoea","o":["Nocturnal asphyxia","Alcoholism is a cofactor","Prone to hypertension","Overnight oximetry is diagnostic to replace polysomnography"],"a":3,"e":"Ans. is ''d'' i.e., Overnight oximetry is diagnostic to replace polysomnography Cardinal features in adults include: Obstructive apneas, hypopneas, or respiratory effort related arousals Daytime symptoms attributable to disrupted sleep, such as sleepiness, fatigue, or poor concentration Signs of disturbed sleep, such as snoring, restlessness, or resuscitative snorts Clinical presentation Most patients with OSA first come to the attention of a clinician because the patient complains of daytime sleepiness, or the bed partner reports loud snoring, gasping, snorting, or interruptions in breathing while sleeping. Daytime sleepiness, distinct from fatigue, is a common feature of OSA Sleepiness is the inability to remain fully awake or alert during the wakefulness portion of the sleep-wake cycle. Snoring is the other common feature of OSA. While snoring is associated with a sensitivity of 80 to 90 percent for the diagnosis of OSA, its specificity is below 50 percent. Clinical features of obstructive sleep apnea (OSA) Daytime sleepiness Obesity Daytime sleepiness Obesity Nonrestorative sleep Large neck circumference Loud snoring Systemic hypertension Witnessed apneas by bed partner Hypercapnia Awakening with choking Cardiovascular disease Nocturnal restlessness Cerebrovascular disease Insomnia with frequent awakenings Cardiac dysrhythmias Lack of concentration Narrow or \"crowded\" airway Cognitive deficits Pulmonary hypertension Changes in mood Cor pulmonale Morning headaches Polycythemia Vivid, strange, or threatening dreams Floppy eyelid syndrome Gastroesophageal reflux Nocturia Polysomnography Full-night, attended, in-laboratory polysomnography is considered the \"gold-standard diagnostic\" test for OSA. It involves monitoring the patient during a full night''s sleep. Unattended, out of centre sleep \"(OCST) may be used as an alternative to polysomnography for the diagnosis of OSA in patients with a high pre-test probability of moderate to severe OSA, provided there are no medical comorbidities such as heart failure that predispose to alternative or additional sleep related breathing disorders. The diagnosis of OSA is based upon the presence or absence of related symptoms, as well as the frequency of respiratory events during sleep (ie, apneas, hypopneas, and respiratory effort related arousals IRERAsJ as measured by polysomnography or out-of- center sleep testing (OCST). In adults, the diagnosis of OSA is confirmed if either of the two conditions exists: There are \"fil_y\" or more predominantly obstructive respiratory events (obstructive and mixed apneas, hypopneas, or RERAs) per hour of sleep (for polysomnography) or recording time (for OCST) in a patient with one or more of the following: Sleepiness, nonrestorative sleep, fatigue, or insomnia symptoms. Waking up with breath holding, gasping, or choking. Habitual snoring, breathing interruptions, or both noted by a bed partner or other observer Hypertension, mood disorder, cognitive dysfunction, coronary artery disease, stroke, congestive heart failure, atrial fibrillation, or type 2 diabetes mellitus There are 15 or more predominantly obstructive respiratory events (apneas, hypopneas, or RERAs) per hour of sleep (for polysomnography) or recording time (for OCST), regardless of the presence of associated symptoms or comorbidities","pyqMatches":[{"year":"2014","no":1347,"q":"Not true obstructive sleep appoea","o":["Nocturnal asphyxia","Alcoholism is a cofactor","Prone to hypertension","Overnight oximetry is diagnostic to replace polysomnography"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2727, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 287, '{"id":2727,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":287,"q":"Obstructive sleep apnoea may result in all of thefollowing except","o":["Systemic hypertension","Pulmonary hypertension","Cardiac arrhythmia","Impotence"],"a":2,"e":"Ans. is ''c'' i.e., Cardiac arrhythmia Daytime function and cognition OSA is associated with excessive daytime sleepiness, inattention, and fatigue, which may impair daily function, induce or exacerbate cognitive deficits, and increase the likelihood of errors and accidents. Cardiovascular morbidity Patients with OSA, are at increased risk for a broad range of cardiovascular morbidities, including systemic hypertension, pulmonary arterial hypertension, coronary artery disease, cardiac arrhythmias, heart failure, and stroke. Metabolic syndrome and type 2 diabetes Patients with OSA have an increased prevalence of insulin resistance and type 2 diabetes. Nonalcoholic fatty liver disease Intermittent nocturnal hypoxia due to OSA may contribute to the development and severity of nonalcoholic fatty liver disease (NAFLD), independent of shared risk factors such as obesity. Perioperative complications Patients with OSA may be at greater risk for perioperative complications such as postoperative oxygen desaturation, acute respiratory failure, postoperative cardiac events, and intensive care unit transfers. Mortality Patients with untreated severe OSA (ie, AHI 30 events per hour) have a two- to three fold increased risk of all-cause mortality compared with individuals without OSA, independent of other risk factors such as obesity and cardiovascular disease.","pyqMatches":[{"year":"2014","no":1346,"q":"Obstructive sleep apnoea may result in all of thefollowing except","o":["Systemic hypertension","Pulmonary hypertension","Cardiac arrhythmia","Impotence"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2728, 'Medicine', 'Rheumatology', 'Moderate', 'Internal_Medicine', 288, '{"id":2728,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":288,"q":"Tophi in gout found in all regions except","o":["Prepatellar bursae","Muscle","Helix of ear","Synovial membrane"],"a":1,"e":"Ans. is ''b'' i.e., Muscle Location of Tophi They are classically located along the helix of the ear. Can also be seen in :- Fingers Toes Prepattelar bursa Olecranon Although gout typically cuases joint inflammation, it can also cause inflammation in other synovial-based structures, such as bursae and tendons. Tophi are collections of urate crystals in the soft tissues. They tend to develop after about a decade in untreated patients who develop chronic gouty arthritis. Tophi may develop earlier in older women, particularly those receiving diuretics.","pyqMatches":[{"year":"2014","no":1348,"q":"Tophi in gout found in all regions except","o":["Prepatellar bursae","Muscle","Helix of ear","Synovial membrane"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2729, 'Medicine', 'Rheumatology', 'Moderate', 'Internal_Medicine', 289, '{"id":2729,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":289,"q":"All drugs used in treatment of acute gout except","o":["Allopurinol","Aspirin","Colchicine","Naproxen"],"a":0,"e":"Ans. is ''a'' i.e., Allopurinol Management of gout Treatment of acute gout To provide rapid and safe pain relief Drugs used are : i) NSAIDs: These are the most frequently used drugs to treat gout because they are so well tolerated. Indomethacin is the agent of choice but other NSAIDs may be just as effective. Aspirin is usually avoided because low doses of aspirin aggravate hyperuricemia. ii) Colchicinee: Colchicine is effective but less well tolerated than NSAIDs iii) GlucocorticoidsQ: Usually reserved for patients in whom colchicines or NSAIDs are contraindicated or ineffective. Treatment of chronic gout (maintain serum urate levels at 5.0 mg/dl or less) AllopurinolQ: Xanthine oxidase inhibitor Agent of choice for most patients with gouty'' Uricosuric agents Probenecid2 SulfinpyrazoneQ Treatment of gout according to the stage Asymptomatic hyperuricemia No treatment indicated, the causes should be determined and any associated problem should be addressed rigorously) Acute gouty arthritis NSAIDs or colchicines or glucocorticoid Intercritical period Prophylactic colchicines (to reduce further attacks) Acute tophoaecous gout Urate lowering drug (allopurinol or probenecid, sulfinpyrinazole)","pyqMatches":[{"year":"2014","no":1277,"q":"All drugs used in treatment of acute gout except","o":["Allopurinol","Aspirin","Colchicine","Naproxen"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2730, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 290, '{"id":2730,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":290,"q":"Wrong abour continuous murmur","o":["Seen with coarctation of aorta","Peaks at S2","Heard both in systole and diastole","Increase on squatting"],"a":3,"e":"Ans. is ''d'' i.e., Increase on squatting A continuous murmur is defined as one that begins in systole and extends through S2 into part or all of diastole. It need not occupy the entire cardiac cycle. Continuous murmurs are not affected by dynamic auscultation maneuvers like squatting etc. They can oftern be difficult to distinguish from individual systolic and diastolic murmurs in patients with mixed valvular heart disease. The classic example of a continuous murmur is that associated with a patent ductus arteriosus, which usually is heard in the second or third interspace at a slight distance from the sternal border.","pyqMatches":[{"year":"2014","no":1442,"q":"Wrong abour continuous murmur","o":["Seen with coarctation of aorta","Peaks at S2","Heard both in systole and diastole","Increase on squatting"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2731, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 291, '{"id":2731,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":291,"q":"Banana shaped left ventricle is seen in","o":["HOCM","DCM","RCM","Takotsubo cardiomyopathy"],"a":0,"e":"Ans. is ''a'' i.e., HOCM Spherical ventricle Dilated cardiomyopathy Apical ballooning Stress cardiomyopathy / Tako-Tsubo Spade- shaped ventricle Apical hypertrophic cardiomyopathy Distortion of ventricle Myocardial infarctions / aneurysms / remodeling Banana - shaped ventricle Hypertrophic cardiomyopathy","pyqMatches":[{"year":"2014","no":1443,"q":"Banana shaped left ventricle is seen in","o":["HOCM","DCM","RCM","Takotsubo cardiomyopathy"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2732, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 292, '{"id":2732,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":292,"q":"Wide QRS complex 0.12 seconds may be seen in all of the following, except","o":["Hyperkalemia","Wolf Parkinson White Syndrome","Ventricular Tachycaridia","Left Anterior Fascicular Block"],"a":3,"e":"Ans. is ''d'' i.e., Left Anterior Fascicular Block Left Anterior Fascicular Block is a partial block in the left bundle system and does not prolong the QRS duration significantly. Typically the QRS duration is slightly prolonged and remains between 0.10 to 0.12 seconds. Major causes of a wide ORS complex Intrinsic intraventricular conduction delay o Left bundle branch block and variants Right bundle branch block and variants o Other nonspecific IVCD patterns Extrinsic intraventricular conduction delay Hyperkalemia Drug-induced - type 1 antiarrhythmic drugs and related sodium channel blocking agents (eg, tricyclic antidepressants and phenothiazines) Ventricular beat o Premature o Escape Paced Ventricular preexcitation Wolff:Parkinson-White (WPW) pattern and variants Factitious ECG unintentionally recorded at fast paper speeds (50 or 100 mm/s) Wide QRS complex tachyarrhythmias Ventricular tachycardia Supraventricular tachycardia or atrial fibrillation or flutter with aberrant intraventricular conduc​tion due to: Bundle branch block Atrioventricular bypass tract (preexcitation syndromes with orthodromic conduction","pyqMatches":[{"year":"2014","no":1445,"q":"Wide QRS complex 0.12 seconds may be seen in all of the following, except","o":["Hyperkalemia","Wolf Parkinson White Syndrome","Ventricular Tachycaridia","Left Anterior Fascicular Block"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2733, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 293, '{"id":2733,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":293,"q":"Subacture combined degeneration of cord is caused due to deficiency of","o":["Vitamin B1","Vitamin B5","Vitamin B6","Vitamin B12"],"a":3,"e":"Ans. is ''d'' i.e., Vitamin B12 Subacate combined degeneration of the spinal cord is the term used for the degeneration of the spinal cord due to vitamin B12 deficiency. The spinal cord, brain, optic nerves, peripheral nerves may all be affected in vitamin B12 deficiency but the spinal cord is usually affected first and exclusively. The tracts mainly involved in the spinal cord are: o Posterior column Corticospinal tract Later on peripheral nerves are involved Clinical features of vitamin B deficiency or subacute combined degeneration of the cord : Patient first notices mild general weakenss and paresthesia consisting of tingling ''pins and needle''. As the illness progresses the gait becomes unsteady and stiffness and weakenss of the limbs and legs develop. If the disease remains untreated ataxic paraplegia evolve. Sometimes there may be loss of superficial sensations, such as tactile, pain and thermal sensations, but these signs are rare. Loss of \"vibration sense\" is the most consistent sign and is usually accompanied by loss of position sensee. Motor signs seen are:- Loss of strength in proximal limb muscles Spasticity, changes in tendon reflexes Clonus and extensor plantar responses Sometimes tendon reflexes may be absente (due to involvement of peripheral nerve) o Gait is ataxic Now, The Clinicopathological Correlation Clinical features Tracts involved Paresthesia, inpairment of deep sensation and ataxia Due to lesion in posterior column Weakness, spasticity and increased tendon reflexes Due to corticospinal tract involvement Occasional findings of loss of pain and temperature Due to spinothalamic tract involvement (rarely involved) Distal and symmetrical impairmeat of superficial Involvement of peripheral nerve (occassionally)","pyqMatches":[{"year":"2014","no":1350,"q":"Subacture combined degeneration of cord is caused due to deficiency of","o":["Vitamin B1","Vitamin B5","Vitamin B6","Vitamin B12"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2734, 'Medicine', 'Neurology', 'Moderate', 'Internal_Medicine', 294, '{"id":2734,"subject":"Medicine","chapter":"Neurology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":294,"q":"Foot ulcers in diabetes are due to all except","o":["Decreased immunity","Neuropathy","Microangiopathy","Macroangiopathy"],"a":0,"e":"Ans. is ''a'' i.e., Decreased immunity The reasons for the increased incidence of foot ulcers in DM involve the interaction of several pathogenic factors Neuropathy (Microvascular complication) Motor and sensory neuropathy lead to abnormal foot muscle mechanics and structural changes in the foot (hammertoe, claw toe deformity, prominent metatarsal heads, Charcot joint). Autonomic neuropathy Results in anhidrosis and altered superficial blood flow in the foot, which promote drying of the skin and fissure formation. PAD and poor wound healing impede the resolution of minor breaks in the skin, allowing them to enlarge and to become infected. Abnormal foot biomechanics. P.A.D. (Macrovascular complication) This leads to occlusive arterial disease that results in ischemia in the lower extremity and an increased risk of ulceration in diabetic patients. Poor wound healing. Grades of diabetic foot ulcers Grade 0 skin intact but bony deformities produce a \"foot at risk\". Grade 1 localized, superficial ulcer. Grade 2 deep ulcer to tendon, bone, ligament, or joint. Grade 3 deep abscess, osteomyelitis Grade 4 gangrene of toes or forefoot Grade 5 gangrene of the entire foot","pyqMatches":[{"year":"2014","no":1351,"q":"Foot ulcers in diabetes are due to all except","o":["Decreased immunity","Neuropathy","Microangiopathy","Macroangiopathy"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2735, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 295, '{"id":2735,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":295,"q":"Not a cause of Gynaecomastia","o":["Hypothyroidism","Kallman","obesity","Klinefelter syndrome"],"a":0,"e":". Ans. is ''a'' i.e., Hypothyroidism Causes of Gynaecomastia Puberty During puberty, the serum oestradiol rises to adult levels before testosterone, causing transient gynaecomastia. This normally resolves within six months to two years. Cirrhosis Gynaecomastia occurs due to altered sex hormone metabolism, and an increase in the oestradiol; free testosterone ratio. Hypogonadism Primary hypogonadism causes a compensatory rise in LH, in turn causing increased peripheral aromatization of testosterone to oestradiol. Secondary hypogonadism, due to pituitary or hypothalamic disease (e.g. prolactin excess, Kallman''s syndrome haemachromatosis), may also cause gynaecomastia despite LH deficiency, since the adrenal cortex continues to produce oestrogen precursors, which are converted to oestrogens in peripheral tissues. Tumours Testicular tumours: Germ cell tumours account for over 95% testicular tumours. Gynaecomatia occurs in 5% of patients, due to hCG secretion stimulating oestradol production by the testes. Leydig cell tumours cause gynaecomastia in 20 – 30% of cases. These tumours present with precocious puberty in boys, or poot libido and gynaecomastia in young males. Approximately 10% of these tumours are malignant. Sertoli cell turnours cause gynaecomastia through excess aromatization of androgents to oestrogens. These turnours may occur in Peutz- Jeger ''s syndrome. Adrenocortical turnours may cause gynaecomastia through overproduction of androgens such as androstenedione, which are converted to oestrogens in peripheral tissues. Ectopic hCG-secreting tumours include lung, gastric, renal, and hepatocellular carcinomas. Hypogonadism from chemotherapy or radiotherapy may also cause gynaecomastia in patients with testicular tumours. Graves disease Gynaecomastia may occur due to increased sex hormone-binding globulin (SHBG), and decreased free testosterone levels. Chronic renal failure: Half of patients receiving haemodialysis develop gynaecomastia due to decreased leydig cell function. Gynaecomastia may also occur following kidney transplantation due to ciclosporin use. Androgen insensitivity syndrome : Complete androgen insensitivity, .formerly termed ''testicular feminization syndrome'', causes a femalephynotype in patients who are genotype males. These patients are regarded as female, and therefore present with infertility and amenorrhoea rather gynaecomastia. Partial androgen receptor defects maycause gynaecomastia in phenotypic males. Drugs cause gvnaecomastia Anti-androgens Cyproterone acetate Finasteride/dutasteride Gastrointestinal drugs Cimetidine / ranitidine Cancer chemotherapy Alkylating agents/vinca alkaloids (due to testicular damage and hypogonadism) Imatinib (tyrosine kinase inhibitor used for chronic myeloid leukemia (CML) and gastrointestinal stromal tumour (GIST). Cardiovascular drugs Spironolactone (displaces oestrogen from SHBG, increasing free oestrogen: testosterone ratio) Digoxin Amiodarone Methyl-dopa Antimicrobial drugs Isoniazid Ketoconazole Metronodazole Anti-viral drugs Highly active anti-retroviral (HAART) therapy (especially protease inhibitors) Neurological drugs Phenothiazines Metoclopramide Tricyclic anti-depressants Opiates","pyqMatches":[{"year":"2014","no":1352,"q":"Not a cause of Gynaecomastia","o":["Hypothyroidism","Kallman","obesity","Klinefelter syndrome"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2736, 'Medicine', 'Endocrinology', 'Easy', 'Internal_Medicine', 296, '{"id":2736,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":296,"q":"Brain tumor causing hypernatremia in children","o":["Medulloblastoma","Cerebellar astrocytoma","Craniophyrangioma","Brain stem glioma"],"a":2,"e":"Ans. is ''c'' i.e., Craniophyrangioma Craniophyrangioma leads to central diabetes mellitus and resultant loss of water leads to hypernatremia.","pyqMatches":[{"year":"2014","no":1353,"q":"Brain tumor causing hypernatremia in children","o":["Medulloblastoma","Cerebellar astrocytoma","Craniophyrangioma","Brain stem glioma"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2737, 'Medicine', 'Endocrinology', 'Easy', 'Internal_Medicine', 297, '{"id":2737,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":297,"q":"Poorly controlled diabetes with blood sugar of 450 mg% is associated with:","o":["Hyponatremia","Hypernatremia","Hypokalemia","Hypomagnesemia"],"a":0,"e":"Ans. is ''a'' i.e., Hyponatremia Poorly controlled diabetes draws water out of cells resulting in hyponatremia. n Plasma concentration falls by 1.4 mmol/L for every 100mg/d1 rise in plasma glucose concentration of sodium.","pyqMatches":[{"year":"2014","no":1354,"q":"Poorly controlled diabetes with blood sugar of 450 mg% is associated with:","o":["Hyponatremia","Hypernatremia","Hypokalemia","Hypomagnesemia"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2738, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 299, '{"id":2738,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":299,"q":"With regards to hereditary spherocytosis, which of the following is false","o":["Usually has autosomal dominant inheritance","Caused by mutations in genes for proteins such as spectrin, ankrin or band 3","Red blood cells are destroyed in the spleen","Aplastic crises are common"],"a":3,"e":"Ans. is ''d'' i.e., Aplastic Crisis are common Aplastic crisis are a rare/uncommon complication of Hereditary Spherocytosis typically caused by virally induced bone marrow suppression. The most common aetiological agent that induces Aplastic Crisis in patients with Hereditary Spherocytosis is Parvovirus B19 Hereditary spherocvtosis usually has autosomal dominant inheritance caused by mutation in genes for proteins such as spectrin. ankrin or band 3. The genes responsible for HS include akyrin, b spectrin, band-3- protein, a-spectrin, and protein 4.2. In approximately two-thirds to three-quarter of HS patients, inheritance is autosomal dominant. In the remaining patients, inheritance is non-dominant due to autosomal recessive inheritance of a de novo mutation. In patients with hereditary spherocvtosis Red blood cells are destroyed in the spleen The spleen plays a critical role in the pathobiology of HS, as destruction of spherocytes in the spleen is the primary cause of hemolysis in HS patients. Aplastic Crisis is an Uncommon Complication Aplastic crisis following virally induced bone marrow suppression are uncommon, but may result in severe anaemia with serious complications including congestive heart failure or even death. The most common aetiological agent in these cases is parvovirus B19. Parvovirus selectively infects erythropoietic progenitor cells and inhibits their growth","pyqMatches":[{"year":"2014","no":1471,"q":"With regards to hereditary spherocytosis, which of the following is false","o":["Usually has autosomal dominant inheritance","Caused by mutations in genes for proteins such as spectrin, ankrin or band 3","Red blood cells are destroyed in the spleen","Aplastic crises are common"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2739, 'Medicine', 'Infectious Diseases', 'Hard', 'Internal_Medicine', 300, '{"id":2739,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Hard","source":"Internal_Medicine","sourceNo":300,"q":"All of the following are true regarding splenectomy in patients with hereditary spherocytosis, except ?","o":["Avoid in mild cases","Delay splenectomy until at least 4 years old age","Anti-pneumococcal vaccination must be given before splenectomy","Prolonged anti-pneumococcal antibiotic prophylaxis must be given after splenectomy"],"a":3,"e":"Ans. is ''d'' i.e., Prolonged Anti-pneumococcal Antibiotic Prophylaxis must be given after splenectomy Splencectomv in patients with Hereditary spherocytosis Avoid splenectomy in mild cases. Delay splenectomy until at least 4 years of age after the risk of severe sepsis has peaked. Anti-pneumococcal vaccination befoe splenectomy is imperative while anti-pneumococcal prophylaxis post-splenectomy is controversial.","pyqMatches":[{"year":"2014","no":1472,"q":"All of the following are true regarding splenectomy in patients with hereditary spherocytosis, except ?","o":["Avoid in mild cases","Delay splenectomy until at least 4 years old age","Anti-pneumococcal vaccination must be given before splenectomy","Prolonged anti-pneumococcal antibiotic prophylaxis must be given after splenectomy"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2740, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 301, '{"id":2740,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":301,"q":"Most common heavy chain disease is","o":["Franklin disease","Seligmann disease","Mu heavy chain disease","Waldenstrom cryoglobulinemia"],"a":1,"e":"Ans. is ''b'' i.e., Seligmann Disease (Alpha heavy chain disease) There are four forms: * Alpha chain disease (Seligmann''s disease)- most common type * Gamma chain disease (Franklin''s disease) * Mu chain disease * Delta chain disease","pyqMatches":[{"year":"2014","no":1473,"q":"Most common heavy chain disease is","o":["Franklin disease","Seligmann disease","Mu heavy chain disease","Waldenstrom cryoglobulinemia"],"a":1,"source":"NEET_2014_Paper.pdf"},{"year":"2016","no":436,"q":"Most common heavy chain disease is","o":["Franklin disease","Seligmann disease","Mu heavy chain disease","Waldenstrom cryoglobulinemia"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2014","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2741, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 302, '{"id":2741,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":302,"q":"Treatment of choice in acute sarcoidosis is","o":["Prednisolone","Cyclosporin","Infliximab","IV immunoglobulins"],"a":0,"e":"Ans. is ''a'' i.e., Prednisolone Prednisolone (corticosteroid) is the treatment of choice for both acute and chronic phase of sarcoidosis that requires treatment.","pyqMatches":[{"year":"2014","no":1356,"q":"Treatment of choice in acute sarcoidosis is","o":["Prednisolone","Cyclosporin","Infliximab","IV immunoglobulins"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2742, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 303, '{"id":2742,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":303,"q":"MDR TB must be treated for at least ?","o":["12 months","18 months","20 months","36 months"],"a":2,"e":"Ans. is ''c'' i.e., 20 months Resistance (or intolerance) to H Throughout (6) RZE Resistance (or intolerance) to R Throughout (12-18) HZEQ Resistance to H + R Throughout (at least 20 months) ZEQ + S (for another injectable agents) Resistance to all first- line drugs Throughout (at least 20 months 1 injectable agent + 3 of of these 4 ethionamide cycloserine, Q, PAS Intolerance to Z HRE","pyqMatches":[{"year":"2013","no":840,"q":"MDR TB must be treated for at least ?","o":["12 months","18 months","20 months","36 months"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2743, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 304, '{"id":2743,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":304,"q":"The following are the complication of haemodialysis except -","o":["Hypotension","Peritonitis","Hypertension","bleeding tendency"],"a":1,"e":"Ans. is ''b'' i.e., Peritonitis Patients with endstage renal disease (ESRD) on long term dialysis therapy have very high mortality due to predominantly cardiovascular causes. ''Sudden cardiac death is the single most common form of death in hemodialysis, accounting for 20% to 30 all deaths in this cohort.'' Dialysis patients have extraordinarity high mortailty rates with cardic disease accounting for 43 percent deaths in this population. Data indicates that approximately 27% of the mortailties are due to sudden cardic death. More on cardiovascular complications in dialysis Cardiovasucular disease is the major cause of death in ESRD patients and atheroscleroses is present in all long term dialysis patients. Premature cardiac death has reached epidemic levels in world dialysis population occurring five to ten times as commonly as in age matched general population and accounting for at least half of all patients death. o Hypertension is a major risk factor Other risk factor are :- Hyperphosphetemia and elevated calcium phosphorus with calcium deposition in coronary arteries. Anemia Hypertriglyceridemia Low HDL cholesterol Increased lipoprotein (a) Insulin deficiency or resistance Hyperhomocysteinem Also know Complications of dialysis Acute complications of hemodialysis Long term complications o Hypotension o Cardiovascular o Cramps o Anemia Nausea and vomiting Secondary hyperparathyrodism and Headache o Malnutrition Chest pain o o Hepatitis (A, B, C, D, E Back pain Depression Itching o Dialysis encephalopathy Fever and chills Malignant tumours Carpal tunnel syndrome Uremic neurophty","pyqMatches":[{"year":"2014","no":1357,"q":"The following are the complication of haemodialysis except","o":["Hypotension","Peritonitis","Hypertension","bleeding tendency"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2744, 'Medicine', 'Respiratory Medicine', 'Hard', 'Internal_Medicine', 305, '{"id":2744,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Hard","source":"Internal_Medicine","sourceNo":305,"q":"The most likely diagnosis in the case of a patient with multiple pulmonary cavities, hematuria and red cell casts is","o":["Anti-GBM disease","Churg-Strauss","Systemic lupus erythematousus","Wegner''s granulomatosis"],"a":3,"e":"Ans. is ''d'' i.e., Wegner''s granulomatosis Multi lung cavities and hematuria are characteristic of Wegner''s granulomatosis. Anti-GBM disease (Goodpasture''s syndrome) usually does not cause lung cavities. Churg-strauss syndrome usually does not cause hematuria. SLE is not a usual cause of lung cavities.","pyqMatches":[{"year":"2014","no":1359,"q":"The most likely diagnosis in the case of a patient with multiple pulmonary cavities, hematuria and red cell casts is","o":["Anti-GBM disease","Churg-Strauss","Systemic lupus erythematousus","Wegner''s granulomatosis"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2745, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 306, '{"id":2745,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":306,"q":"Hung-up reflexes are seen in","o":["Chorea","Atheotosis","Cerebral palsy","Cerebellar palsy"],"a":0,"e":"Ans. is ''a'' i.e., Chorea Hung up knee jerk When patellor tendon is tapped while the foot is hanging free, the leg may be held in extension for few seconds before relaxing owing to prolonged contraction of quadriceps. This is seen in \"chorea\". Other neurological signs associated with chorea Milkmaids grip Piano sign Handwriting Milkmaid''s grip Inability to maintain sustained voluntary contraction of muscle group at a constant level. Inability to apply steady pressure during handshake leading to a characteristic squeeze and release of grip. Patient''s have difficulty maintaining sustained eyelid closure and sustained tongue protrusion","pyqMatches":[{"year":"2014","no":1360,"q":"Hung-up reflexes are seen in","o":["Chorea","Atheotosis","Cerebral palsy","Cerebellar palsy"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2746, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 307, '{"id":2746,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":307,"q":"Arsenic poisoning causes","o":["Polyneuritis","Mononeuritis multiplex","Radiculopathy","Myelopathy"],"a":0,"e":"Ans. is ''a'' i.e., Polyneuritis There is sensory and motor (i.e. mixed) polyneuropathy, with painful paresthesia of hands and feet and muscle tenderness.","pyqMatches":[{"year":"2014","no":1361,"q":"Arsenic poisoning causes","o":["Polyneuritis","Mononeuritis multiplex","Radiculopathy","Myelopathy"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2747, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 308, '{"id":2747,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":308,"q":"Tropical pulmonary eosinophilia is caused because of","o":["Occult filariasis","Cerebral melaria","Penumonic plague","Asthmatic bronchitis"],"a":0,"e":"Ans. is ''a'' i.e., Occult filariasis Occult filariasis is a rare condition which is caused by hypersensitivity reaction to filarial antigen. Micro filatia are absent in the blood. Lymphatic filariasis is absent. Indirect evidence of filarial infection is obtained by demonstrating antifilarial antibodies","pyqMatches":[{"year":"2014","no":1362,"q":"Tropical pulmonary eosinophilia is caused because of","o":["Occult filariasis","Cerebral melaria","Penumonic plague","Asthmatic bronchitis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2748, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 309, '{"id":2748,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":309,"q":"Characteristic ECG finding of pulmonary embolism","o":["Sinus tachycardia","S Q3T3","T wave inversion","Epsilon waves"],"a":1,"e":"Ans. is `b'' i.e., SJQ3T3 E.C.G. changes of pulmonary embolism ? Sinus tachycardia is the most frequent and nonspecific finding on electrocardiography in acute pulmonary embolism. Features suggesting acute right heart strain on the ECG occur relatively infrequently, these include. Acute right axis deviation P pulmonale Right bundle branch block Inverted T waves ST segment changes in right sided leads. Earlier the following E.C.G. changes were considered highly predictive of acute pulmonary embolism, but these observations were found in less than 12% of patients with pulmonary emboli in recent studies. These E.C.G. features are - S wave in lead I Q wave in lead III Inverted Tin lead III (\"S1Q31.3\") S waves in lead I, II and III (\"Si,S2 S3\") Also know Areterial blood gas analysis in pulmonary embolism : Arterial blood gas analysis shows Mid to moderate hypoxemia Increased P (A - a) 0, Mildly reduced PaCO2 Almost all patients with pulmonary embolism have PaO, < 80 mm Hg but no absolute level of Pa02 can be used to exclude the diagnosis.","pyqMatches":[{"year":"2014","no":1490,"q":"Characteristic ECG finding of pulmonary embolism","o":["Sinus tachycardia","S Q3T3","T wave inversion","Epsilon waves"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2749, 'Medicine', 'Rheumatology', 'Moderate', 'Internal_Medicine', 310, '{"id":2749,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":310,"q":"Pleural effusion in rheumatoid arthritis is typically associated with the following features except","o":["Glucose > 60 mg/dl","Protein > 3 gm/di","Pleural fluid protien to serum protein ratio of >0 .5","Pleural fluid LDH to serum LDH ratio of >0.6"],"a":0,"e":"Ans. is ''a'' i.e., Glucose > 60 mg/dl Causes of low glucose pleural fluid Malignancy Rheumatoid arthritis Empyema Hemothorax Paragonimiasis Churg strauss syndrome Lupus pleuritis (occasionally)","pyqMatches":[{"year":"2014","no":1491,"q":"Pleural effusion in rheumatoid arthritis is typically associated with the following features except","o":["Glucose > 60 mg/dl","Protein > 3 gm/di","Pleural fluid protien to serum protein ratio of >0 .5","Pleural fluid LDH to serum LDH ratio of >0.6"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2750, 'Medicine', 'Rheumatology', 'Easy', 'Internal_Medicine', 311, '{"id":2750,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":311,"q":"In anklyosing spondylitis joint involvement is least in?","o":["Wrist and hand","Sacroiliac joint","Acromio-clavicular joint","Costochondral junction"],"a":0,"e":"Ans. is ''a'' i.e., Wrist and hand Ankylosing spondylitis (marie - strumpell disease) Ankylosing spondylitis is a chronic progressive inflammatory disease of the sacroiliac joints and the axial skeleton. Prototype of seronegative (absence of rheumatoid factor) spondyloarthropathies. Inflammatory disorder of unknown cause. Usually begins in the second or third decade with a median age of 23, in 5% symptoms begin after 40. Male to female ratio is 2-3 : 1 Strong correlation with HLA-B27 90-95% of cases are positive for HLA - B27. Joints involved in ankylosing spondylitis Primarily affects axial skeleton. The disease usually begins in the sacro-iliac joints and usually extends upwards to involve the lumbar, thoracic, and often cervical spine In the worst cases the hips or shoulders are also affected. o Hip joint is the most commonly affected peripheral joint. o Rarely knee and ankle are also involved. Pathology Enthesitis i.e. inflammation of the insertion points of tendons, ligaments or joint capsule on bone is one of the hallmarks of this entity of disease. Primarily affects axial (spinal) skeleton and sacroiliitis is often the earliest manifestation of A.S.. Involvement of costovertebral joints frequently occur, leading to diminished chest expansion (normal 5 cm) Peripheral joints e.g. shoulders, and hips are also involved in 1/3rd patients. Extraarticular manifestations like acute anterior uveitis (in 5%); rarely aortic valve disease, carditis and pulmonary fibrosis also occur. Pathological changes proceed in three stages? Inflammation with granulation tissue formation and erosion of adjacent bone. Fibrosis of granulation tissue Ossification of the fibrous tissue, leading to ankylosis of the joint. Inflammatory bowel disease (CD, UC) may also be seen. Clinicalfeatures (symptoms) Low back pain of insidious onset Duration usually less than 3 months Significant morning stiffness and improvement with exercise Limited chest expansion Diffuse tenderness over the spine and sacroiliac joints Loss of lumbar lordosis, increased thoracic kyphosis Decreased spinal movements (especially extension) in all directions. Radiological features of an kvlasing spondylitis Radiographic evidence of sacroiliac joint is the most consistent finding in ankylosing spondylitis and is crucial for diagnosis. The findings are :- D Sclerosis of the articulating surfaces of SI joints Widening of the sacroiliac joint space Bony ankylosis of the sacroiliac joints Calcification of the sacroiliac ligament and sacro-tuberous ligaments Evidence of enthesopathy - calcification at the attachment of the muscles, tendons and ligaments, particularly around the pelvis and around the heel. X-ray of lumbar spine may show :- Li Squaring of vertebrae : The normal anterior concavity of the vertebral body is lost because of calcification of the anterior longitudinal ligament. Loss of the lumbar lordosis. Bridging ''osteophytes'' (syndesmophytes) Bamboo spine appearance In the early disease process, plain x-rays may be read as normal. More accurate and early diagnosis can be done by using MR1 and/or CT scan. Dynamic MRI with fat saturation, either short tau inversion recovery (STIR) sequnece or TI weighted images with contrast enhancement is highly sensitive and specific for identifying early intra-articular inflammation, cartilage changes, and underlying bone marrow edema in sacroilitis. Magnetic resonance imaging allows for visualization of acute sacroilitis, spondylitis, and spondylodiscitis, and can also detect acute inflammation of the entheses, bone and synovium. The ability to detect early inflammatiion and acurately visualize cartilaginous and enthesal lesions makes magnetic resonance imaging a useful assessment tool in the spondyloarthropathies.","pyqMatches":[{"year":"2014","no":1364,"q":"In anklyosing spondylitis joint involvement is least in?","o":["Wrist and hand","Sacroiliac joint","Acromio-clavicular joint","Costochondral junction"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2751, 'Medicine', 'Rheumatology', 'Easy', 'Internal_Medicine', 312, '{"id":2751,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":312,"q":"Least common site involved in osteoarthritis is","o":["Hip joint","Knee joint","Carpometacarpal joint of thumb","Distal carpophalangeal joint"],"a":2,"e":"Ans. is ''C'' In the hand the joints specifically involved are ? Distal interphalangeal join& (of particular importance is the point that this joint is not involved in rheumatoid arthritis). Proximal interphalangeal join& First carpometacarpal jointsQ Remember these two important features of joint involvement in osteoarthritis It does not involve the metacarpophalangeal jointso It does not involve the wrist joINTEGER(2. It also does not involve the carpometacarpalQ joint (except at the base of thumb). Osteoarthritis involves the carpometacarpal joint at the base of thumb, infact it is the second most common area of involvement in osteoarthritis. Other joints which are commonly involved in osteoarthritis are Hips, Knees, Lower lumbar Cervical. Joints which are usually spared in osteoarthritis are WristsQ, carpometacarpale ElbowsQ Shoulder joint","pyqMatches":[{"year":"2014","no":1365,"q":"Least common site involved in osteoarthritis is","o":["Hip joint","Knee joint","Carpometacarpal joint of thumb","Distal carpophalangeal joint"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2752, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 313, '{"id":2752,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":313,"q":"Inverted T waves are seen in","o":["Hyperkalemia","Hyperthermia","Wellen syndrome","Coronary syndrome"],"a":2,"e":"Ans. is ''c'' i.e., Wellen syndrome Severe anterior wall Ischemia (with or without infarction) may cause prominent T-wave inversions in the precordial leads. This pattern (sometimes referred to as Wellens T-waves) is usually associated with a high-grade stenosis of the left anterior descending coronary artery. Hyperkalemia has tall Tented T-waves. Coronary syndrome Xis characterised by blockage of perforators while the epicardial coronary artery is normal. In these patients stenting of coronaries is not useful. Nitrates are mainstay of therapy.","pyqMatches":[{"year":"2014","no":1448,"q":"Inverted T waves are seen in","o":["Hyperkalemia","Hyperthermia","Wellen syndrome","Coronary syndrome"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2753, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 314, '{"id":2753,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":314,"q":"Wide QRS complex is typically seen in","o":["Bundle Branch block","Sick sinus syndrome","Mobitz type I block","Mobithz type II block"],"a":0,"e":"Ans. is ''a'' i.e., Bundle Branch block Repeat from previous session. Intrinsic intraventricular conduction delays such as left bundle block and right bundle branch block are associated with wide QRS complex.","pyqMatches":[{"year":"2014","no":1446,"q":"Wide QRS complex is typically seen in","o":["Bundle Branch block","Sick sinus syndrome","Mobitz type I block","Mobithz type II block"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2754, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 315, '{"id":2754,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":315,"q":"Low QRS voltage on ECG indicates ?","o":["Pulmonary embolism","Pericardial effusion","Cor pulmonale","Infective endocarditis"],"a":1,"e":"Ans. is ''b'' i.e., Pericardial effusion Causes of low voltage QRS complexes Adrenal insufficiency Anasarca Artifactual or spurious, eg, unrecognized standardization of ECG at one-half the usual gain (i.e., 5 mm/mv) Cardiac infiltration or replacement (e.g., amyloidosis, tumor) Cardiac transplantation, especially with acute or chronic rejection Cardiomyopathy, idiopathic or secondary Chronic obstructive pulmonary disease Constrictive pericarditis Hypothyroidism, usually with sinus bradycardia Left pneumothorax (mid-left chest leads) Myocardial infarction, extensive Myocarditis, acute or chronic Normal varian Obesity Pericardial effusion Pericardial tamponade, usually with sinus tachycardia Pleural effusions","pyqMatches":[{"year":"2014","no":1449,"q":"Low QRS voltage on ECG indicates ?","o":["Pulmonary embolism","Pericardial effusion","Cor pulmonale","Infective endocarditis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2755, 'Medicine', 'Hematology', 'Hard', 'Internal_Medicine', 316, '{"id":2755,"subject":"Medicine","chapter":"Hematology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":316,"q":"65-year-old man presents with anemia, posterior columan dysfunction, and planter extensor. Which of the following is the likely cause","o":["Tabes dorsalis","Frederich''s ataxia","Vitamin B1 deficiency","Vitamin B 12 deficiency"],"a":3,"e":"Ans. is ''d'' i.e., Vitamin B12 deficiency Anemia along with involvement of posterior column is characteristic of subacute combined degeneration of spinal cord caused by vitamin B12 deficiency.","pyqMatches":[{"year":"2014","no":1366,"q":"65-year-old man presents with anemia, posterior columan dysfunction, and planter extensor. Which of the following is the likely cause","o":["Tabes dorsalis","Frederich''s ataxia","Vitamin B1 deficiency","Vitamin B 12 deficiency"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2756, 'Medicine', 'Endocrinology', 'Moderate', 'Internal_Medicine', 317, '{"id":2756,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":317,"q":"Proptosis is not seen in","o":["Grave''s disease","Sarcoidosis","Pituitary adenoma","Myxoedema"],"a":3,"e":"Ans. is ''d'' i.e., Myxoedema Proptosis occurs in thyrotoxicosis not in hypothyroidism Choices Logic Grave''s Cytokines appear to play a major role in thyroid-associated ophthalmopathy There is infiltration of the extraocular muscles by activated T cells; the release of cytokines such as IFN-alpha and TNF results in fibroblast activation and increased synthesis of glycosaminoglycans that trap water, thereby leading to characteristic muscle swelling i l f Sarcoidosis Approximately 20%, of patients with ophthalmic findings of sarcoid have soft tissue involvement of the orbit or lacrimal gland and present as a mass lesion with proptosis, ptosis, or ophthalmoplegia. Pituitary adenoma Macro-adenoma associated with pituitary apoplexy can lead to proptosis.","pyqMatches":[{"year":"2013","no":1112,"q":"Proptosis is not seen in","o":["Grave''s disease","Sarcoidosis","Pituitary adenoma","Myxoedema"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2757, 'Medicine', 'Endocrinology', 'Easy', 'Internal_Medicine', 318, '{"id":2757,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":318,"q":"True about obesity","o":["Seen mostly in females","Prevalence decrease upto 40 years of age","No genetic predisposition","Smoking is a risk factor"],"a":3,"e":"Ans. is ''d'' i.e., Smoking is a risk factor Cessation of smoking Weight gain is very common when people stop smoking. This is thought to be mediated at least in part by nicotine withdrawal, which is associated with increased food intake and reduced energy expenditure. Weight gain of 1 to 2 kg in the first two weeks is often followed by an additional 2 to 3 kg weight gain over the next four to five months. The average weight gain is 4 to 5 kg but can be much greater. Obesity is common in both men and women (more common in women). Etiologic Classification of Obesity latrogenic causes Drugs that cause weight gain Hypothalamic surgery Dietary obesity Infant feeding practices Progressive hyperplastic obesity Frequency of eating High fat diets Overeating Neuroendocrine obesities Hypothalamic obesity Seasonal affective disorder Cushing''s syndrome Polycystic ovary syndrome Hypogonadism Growth hormone deficiency Pseudohypoparathyroidism Social and behavioral factors Socioeconomic status Ethnicity Psychological factors Restrained eaters Night eating syndrome Binge-eating Sedentary lifestyle Enforced inactivity (post-operative) Aging Genetic (dysmorphic) obesities Autosomal recessive traits Autosomal dominant traits X-linked traits Chromosomal abnormalities Other Low birth weight","pyqMatches":[{"year":"2013","no":115,"q":"True about obesity","o":["Seen mostly in females","Prevalence decrease upto 40 years of age","No genetic predisposition","Smoking is a risk factor"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2758, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 319, '{"id":2758,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":319,"q":"What is the of correction of sodium deficit","o":["0.5 mmol/hour","1 mmol/hour","1.5 mmol/hour","2.0 mmol/hour"],"a":0,"e":"Ans. is ''a'' i.e., 0.5 mmol/Hr For serious symptomatic hyponatremia, the first line of treatment is prompt intravenous infusion of hypertonic saline, with a target increase of 6 mmol/L over 24 hours (not exceeding 12 mmol/L) and an additional 8 mmol/L during every 24 hours thereafter until the patient''s serum sodium concentration reaches 130 mmol/L.","pyqMatches":[{"year":"2013","no":1242,"q":"What is the of correction of sodium deficit","o":["0.5 mmol/hour","1 mmol/hour","1.5 mmol/hour","2.0 mmol/hour"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2759, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 320, '{"id":2759,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":320,"q":"Maximum loss of sodium in a child occurs in","o":["Gastric juice","Ileal fluid","Non cholera Diarrhoea","Cholera"],"a":1,"e":"Ans. is ''b'' i.e., heal fluid Cations and anions in biological fluids in meq/dl Fluid SodiumPotassiumChloride Gastric juice 60 10 85 heal fluid 130 10 115 Diarrhea stool 10-90 10-80 10-110","pyqMatches":[{"year":"2014","no":1368,"q":"Maximum loss of sodium in a child occurs in","o":["Gastric juice","Ileal fluid","Non cholera Diarrhoea","Cholera"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2760, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 321, '{"id":2760,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":321,"q":"With regards to G6PD deficiency, which of the following in false","o":["Affects the pentose phosphate pathway","Associated with neonatal jaundice","Acute haemolysis can be precipitated by broad beans","X-linked recessive disorder that does not affect heterozygous famales"],"a":3,"e":"Ans. is ''d'' i.e., X-linked recessive disorder that does not affect heterozygous famales Glucose 6-phosphate dehydrogenase (G6PD) deficiency, an X- linked disorder, is the most common enzymatic disorder of red blood cells in humans, affecting 400 million people worldwide. Clinical spectrum The clinical expression of G6PD variants encompasses a spectrum of hemolytic syndromes The four forms of symptomatic G6PD deficiency : Acute hemolytic anemia Favism Congenital nonspherocytic hemolytic anemia Neonatal hyperbilirubinemia G6PD deficiency is expressed in males carrying a variant gene that results in sufficient enzyme deficiency to lead to symptoms. Acute hemolytic anemia Almost all individuals with the most prevalent G6PD variants, G6PD A- and G6PD Mediterranean, are asymptomatic in the steady state. They have neither anemia, evidence of increased red cell destruction, nor an alteration in blood morphology,. o However sudden destruction of enzyme deficient erythrocytes can be triggered by certain drugs or chemicals, by selected infections, and rarely by metabolic abnormalities (eg, diabetic ketoacidosis). Clinical course At two to four days after drug ingestion, there is the sudden onset of jaundice, pallor, and dark urine, with or without abdominal and back pain. This is associated with an abrupt fall in the hemoglobin concentration of 3 to 4 g/dL, during which time the peripheral blood smear reveals red cell fragments, microspherocytes, and eccentrocytes or \"bite\" cells. The anemia induces an appropriate stimulation of erythropoiesis, characterized by an increase in reticulocytes that is apparent within five days and is maximal at 7 to 10 days after the onset of hemolysis. Even with continued drug exposure, the acute hemolytic process ends after about one week, with ultimate reversal of the anemia. Inciting events Patients with class II or III variants develop intermittent hemolysis only after one or more of the following inciting events. Infection Oxidant drugs Chemical agents (eg, moth balls, aniline dyes, henna compounds) Diabetic ketoacidosis Ingestion of fava beans Drugs and chemicals Primaquine, dapsone, and a number of other drugs can precipitate hemolysis in G6PD deficient subjects. Foods: fava beans and bitter melon G6PD deficiency can also be precipitated by the the ingestion of fresh fava beans (favism). Manifestation offavism begins 5-24 hrs after fava bean ingestion and include headache, nausea, back pain. Congenital nonspherocytic hemolytic anemia Patients with class I G6PD variants have such severe G6PD deficiency that lifelong hemolysis occurs in the absence of infection or drug exposure. Such patients fall under the category of having congenital nonspherocytic hemolytic anemia. These G6PD variants have low in vitro activity and/or marked instability of the molecule, and most have DNA mutations at the glucose-6-phosphate or NADP binding sites. These sites are central to the function of G6PD, which oxidizes glucose-6-phosphate and reduces NADP to NADPH. It is presumed that the functional defect is so severe that the red cells cannot withstand even the normal oxidative stresses encountered in the circulation. Anemia and jaundice are often first noted in the newborn period, and the degree of hyperbilirubinemia is frequently of sufficient severity to require exchange transfusion. After infancy, hemolytic manifestations are subtle and inconstant. Most individuals have mild to moderate anemia (hemoglobin 8 to 10 g/dL) with a reticulocyte count of 10 to 15 percent. Pallor is uncommon, scleral icterus is intermittent, splenomegaly is rare, and splenectomy generally is of little benefit. Hemolysis can be exaggerated by exposure to drugs or chemicals with oxidant potential or exposure to fava beans. Some drugs with relatively mild oxidant potential that are safe in patients with class II or class III G6PD variants may increase hemolysis in patients with class I variants. Neonatal hyperbilirubineinia The clinical picture of neonatal jaundice due to G6PD deficiency differs from neonatal jaundice seen in hemolytic disease of the fetus and newborn (HDFN) associated with Rh(D) incompatibility in two main respects. G6PD deficiency-related neonatal jaundice is rarely present at birth; the peak incidence of clinical onset is between days two and three. a There is more jaundice than anemia, and the anemia is rarely severe. The severity ofjaundice varies widely, from being subclinical to imposing the threat of kernicterus if not treated","pyqMatches":[{"year":"2014","no":1370,"q":"With regards to G6PD deficiency, which of the following in false","o":["Affects the pentose phosphate pathway","Associated with neonatal jaundice","Acute haemolysis can be precipitated by broad beans","X-linked recessive disorder that does not affect heterozygous famales"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2761, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 322, '{"id":2761,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":322,"q":"All of the following statements about genetics of G6PD deficiency are true, except","o":["X-linked inheritance","More severe in Men","Contradicts Lyon Hypothesis","May affect Heterozygous females"],"a":2,"e":"Ans. is ''c'' i.e., Contradicts Lyon Hypothesis Genetics of G6PD The gene for G6PD is located on the X chromosome (band X q28) [8] and has been cloned and sequenced. o Even though females have two X chromosomes per cell, normal males and females have the same enzyme activity in their red cells because one of the X chromosomes in each cell of the female embryo is inactivated and remains inactive throughout subsequent cell divisions (Lyon hypothesis). G6PD deficiency is expressed in males carrying a variant gene, while heterozygous females are usually clinically normal. However, the mean red blood cell enzyme activity in heterozygous females may be normal, moderately reduced, or grossly deficient depending upon the degree of lyonization and the degree to which the abnormal G6PD variant is expressed. G6PD supports Lyon''s hypothesis :- According to lyon''s hypothesis one of the two chromosome in each cell of the female embryo is inactivated and remains inactive throughout subsequent cell division. G6PD is inherited as an X-linked (recessive) disorder, it is more common in males. Heterozygous Female may also be affected depend on the extent of lyonisation (inactivation of one X-chromosome) but the overall average degrees of hemolysis in heterozygous female is less. A heterozygous female with 50 percent normal G6PD activity has 50 percent normal red cells and 50 percent G6PD-deficient red cells. The deficient cells are as vulnerable to hemolysis as the enzyme- deficient red blood cells in males. Male Males, who have only one copy of the X chromosome, are either normal or hemizygous for the variant glucose 6-phosphate dehydrogenase (G6PD) gene. Thus, G6PD deficiency is expressed in males carrying a variant gene on their X chromosome that produces sufficient enzyme deficiency to lead to symptoms. All of the red cells in affected males are vulnerable to hemolysis. Female Females, who have two copies of the X chromosome, are either normal, heterozygous, or homozygous for the variant gene. Heterozygous females are usually clinically normal. However, their mean red blood cell enzyme activity may be normal, moderately reduced, or grossly deficient depending upon the degree of X chromosome inactivation (lyonization) and the degree to which the abnormal G6PD variant is expressed. A female with 50 percent normal G6PD activity, due to inactivation of one X chromosome in each cell via lyonization, has 50 percent normal red cells and 50 percent G6PD-deficient red cells. The deficient cells are as vulnerable to hemolysis as the enzyme- deficient red blood cells in males. Homozygous females are as severely affected clinically as hemizygous males. All of their red cells are vulner​able to hemolysis","pyqMatches":[{"year":"2014","no":1369,"q":"All of the following statements about genetics of G6PD deficiency are true, except","o":["X-linked inheritance","More severe in Men","Contradicts Lyon Hypothesis","May affect Heterozygous females"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2762, 'Medicine', 'Gastroenterology', 'Moderate', 'Internal_Medicine', 323, '{"id":2762,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":323,"q":"Platelets in stored blood do not live after","o":["24 hours","48 hours","72 hours","96 hours"],"a":2,"e":"Ans. is ''c'' i.e., 72 hours Platelets are provided as a pooled preparation from one or several donors, usually as a 6-unit bag, which is the usual amount given to an average-sized adult. Each unit contains approximately 8 x 101° platelets and should increase the platelet count by about 7000-10,000/ pL in a 75kg adult. Platelets stored at room temperature can be used for up to 5 days and have a life span of 8 days. Those stored at 4°C are useful for only 24 hours (only 50-70% of total platelet activity is present at 6 hours) and have a life span of only 2-3 days. ABO compatibility should be observed for platelets, but is not essential. For each donor used, there is a similar risk of transmitting hepatitis and HIV as for one unit of blood. Platelet should be administered through a 170pm filter.","pyqMatches":[{"year":"2014","no":1371,"q":"Platelets in stored blood do not live after","o":["24 hours","48 hours","72 hours","96 hours"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2763, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 324, '{"id":2763,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":324,"q":"Earliest and often the only presentation of TB kidney is","o":["Increased frequency","Colicky pain","Hematuria","Renal calculi"],"a":0,"e":"Ans. is ''a'' i.e., Increased frequency Urinary frequency, dysuria, nocturia, hematuria, and flank or abdominal pain is common presentations. However, patients may be asymptomatic and the disease is discovered only after severe destructive lesions of the kidneys have developed. Urinalysis gives abnormal results in 90% of cases, revealing pyuria and hematuria. The documentation of culture-negative pyuria in acidic urine raises the suspicion of TB. IV pyelography, abdominal CT, or MRI may show deformities and obstruction, and calcifications and ureteral strictures are suggestive findings. Culture of three morning urine specimens yields a definitive diagnosis in nearly 90% of cases.","pyqMatches":[{"year":"2014","no":1373,"q":"Earliest and often the only presentation of TB kidney is","o":["Increased frequency","Colicky pain","Hematuria","Renal calculi"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2764, 'Medicine', 'Gastroenterology', 'Hard', 'Internal_Medicine', 325, '{"id":2764,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":325,"q":"Most common cause of diarrhea in AIDS patients?","o":["Salmonella typhimurium","Cryptosporidium","Candida","isophora"],"a":1,"e":"Ans. is ''b'' i.e., Cryptosporidium Most common cause of diarrhea in HIV → Cryptosporidium. Diseases of Oropharvnx and GI system in H.I.V. These are :? Oral lesions : Thrush (oral candidiasis), oral Hairy leukoplakia (caused by EBV), and aphthous ulcer. Esophageal : Esophagitis by CMV, HSV or candida. Diarrhea : Diarrhea is caused by :- Bacteria : Salmonella, Shigella, Campylobacter, and mycobacteria avium intracellulare. Fungal : Histoplasma, Coccidioides, penicillium. Other : CMV, microsporidia, isospora helli, and cryptosporidia. AIDS enteropathy (HIV enteropathy)","pyqMatches":[{"year":"2014","no":1374,"q":"Most common cause of diarrhea in AIDS patients?","o":["Salmonella typhimurium","Cryptosporidium","Candida","isophora"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2765, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 326, '{"id":2765,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":326,"q":"Not seen with uremic lung","o":["alveolar injury","Pulmonary edema","Interstitial fibrosis","Fibrinous exudate in alveoli"],"a":2,"e":"Ans. is ''c'' i.e., Interstitial fibrosis Uremic lung is referred to abnormalities expressed chest x-ray abnormalities seen in patients with CKD. The pathogenesis was believed to be related to blood urea nitrogen and creatinine retention. There is : Its pathophysiology is based on uremia-induced increased permeability of pulmonary alveolo-capillary interfaces, leading to Interstitial and intra-alveolar edema Atelectasis Alveolar hemorrhage Pulmonary hyaline membrane formation. These changes are compounded by bleeding diathesis secondary to platelet dysfunction in advanced renal disease. The pulmonary symptoms and radiographic findings are reversible with hemodialysis.","pyqMatches":[{"year":"2014","no":1375,"q":"Not seen with uremic lung","o":["alveolar injury","Pulmonary edema","Interstitial fibrosis","Fibrinous exudate in alveoli"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2766, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 327, '{"id":2766,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":327,"q":"Oliguric phase of ARF is characterized by A/E","o":["Chest pain","Acidosis","Hypertension","Hypokalemia"],"a":3,"e":"Ans. is ''d'' i.e., Hypokalemia Maintenance phase (Oliguric phase) (Lasts for 1-2 weeks) Uremic complications and electrolyte abnormalities arise during this phase- • GFR reaches its lowest point, urine output is lowest (typically 5-10 ml/min) • Due to fluid overload and decreased electrolyte excretion, following electrolyte abnormalities are seen • Hyperkalemia - (d/t reduced excretion) . Hyponatremia -s (d/t volume overload) . Hyperphosphatemia 4 (d/t reduced excretion) . Hypermagnesemia - (d/t reduced excretion) . Hyperuricemia -> (d/t reduced excretion) . Hypocalcemia -> (d/t deposition of calcium phosphate) . Elevation of B. U.N. 4 (d/t reduced excretion) . Hyposmolality -> (d/t volume overload) . Anemia 4 (d/t Impaired erythropoiesis Hemolysis, bleeding Dilution)","pyqMatches":[{"year":"2014","no":1376,"q":"Oliguric phase of ARF is characterized by A/E","o":["Chest pain","Acidosis","Hypertension","Hypokalemia"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2767, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 328, '{"id":2767,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":328,"q":"In EEG type of wave seen in metabolic encephalophathy","o":["Alpha","Beta","Gamma","Delta"],"a":3,"e":"Ans. is ''cl'' i.e., Delta E.E.G. changes in metabolic encephalopathy In metabolic encephalopathy changes are typically nonfocal E.E.G. has been widely used to evaluate metabolic encephalopathy. The E.E.G .findings are abnormal in acute encephalopathic stages. It is difficult to establish a diagnosis of metabolic encephalopathy with certainity through E.E.G. There is generalized slowing of the E.E.G with an excess of the delta and theta waves with suppression of normal alpha and beta wave activity and occasionally bilateral spikes and waves complexes occurring in absence of seizure activity\". In metabolic encephalopathies, the E.E.G evolution correlates well with the severity of encephalopathy. o However EEG has little specificity in differentiating etiologies in metabolic encephalopathy. For example, though triphasic waves are most frequently mentioned in hepatic encephalopathy, they can also be seen in uremic encephalopathy or even in aged psychiatric patients treated with lithium. o Spikes and waves may appear in hypo or hyperglycemia uremic encephalopathy or vitamin deficiencies. Common principles of EEG changes in metabolic encephalopathy are : - Varied degrees of slowing Associated mixtures of epileptic discharge High incidence of triphasic waves Reversibility after treatment of underlying causes Metabolic encephalopathyEEG rythm Grade I (almost normal) Dominant activity is alpha rhythm with minimal teta activity Grade II (mildly abnormal) Dominant teta background with some alpha and delta activities. Grade II (moderately abnormal) Continuous delta activity predominates, little activity of faster frequencies Grade IV (severely abnormal) Low-amplitude delta activity or suppression-burst pattern Grade V (extremely abnormal) Nearly\"flat\" tracing or electrocerebral inactivity.","pyqMatches":[{"year":"2014","no":1377,"q":"In EEG type of wave seen in metabolic encephalophathy","o":["Alpha","Beta","Gamma","Delta"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2768, 'Medicine', 'Respiratory Medicine', 'Moderate', 'Internal_Medicine', 329, '{"id":2768,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":329,"q":"Asbestosis causes all except","o":["Shaggy heart borders","Honeycombing","Hilar lymphadenopathy","Basal peribronchial fibrosis"],"a":2,"e":"Ans. is ''c'' i.e., Hilar lymphadenopathy Asbestosis causes fibrosis in the lower lobes of the lung. Pleural plaque formed by asbestosis most commonly affects anterolateral and posterolateral aspects of parietal pleura and over the dome of diaphragm","pyqMatches":[{"year":"2014","no":1379,"q":"Asbestosis causes all except","o":["Shaggy heart borders","Honeycombing","Hilar lymphadenopathy","Basal peribronchial fibrosis"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2769, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 330, '{"id":2769,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":330,"q":"The most common cause of sudden death in sarcoidosis is","o":["Pneumonia","Cor pulmonale","Arrythmias","Liver failure"],"a":2,"e":"Ans. is ''c'' i.e., Arrhythmias Cardiac involvement occurs initially with inflammation and granuloma formation followed by scarring. The initial inflammation can lead to triggered ventricular arrhythmias with subsequent scarring resulting in the substrate for reentrant monomorphic ventricular tachycardia.","pyqMatches":[{"year":"2014","no":1380,"q":"The most common cause of sudden death in sarcoidosis is","o":["Pneumonia","Cor pulmonale","Arrythmias","Liver failure"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2770, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 331, '{"id":2770,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":331,"q":"Most common cause of unilateral Hilar lymphadenopathy","o":["Histoplasmosis","Sarcoidosis","Aspergillosis","Tuberculosis"],"a":3,"e":"Ans. is ''d'' i.e., Tuberculosis Primary TB most commonly presents with focal alveolar pneumonia and associated unilateral hilar or mediastinal adenopathy.","pyqMatches":[{"year":"2014","no":1381,"q":"Most common cause of unilateral Hilar lymphadenopathy","o":["Histoplasmosis","Sarcoidosis","Aspergillosis","Tuberculosis"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2771, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 332, '{"id":2771,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":332,"q":"Which of the following is cause of RBBB","o":["It can occur in a normal person","Pulmonary embolism","Corpulmonale","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above Causes of RBBB Normal physiological Pulmonary embolism/corpulmonale Pulmonary artery hypertension ASD Rheumatic heart disease","pyqMatches":[{"year":"2014","no":1450,"q":"Which of the following is cause of RBBB","o":["It can occur in a normal person","Pulmonary embolism","Corpulmonale","All of the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2772, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 333, '{"id":2772,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":333,"q":"Alternating RBBB with Left anterior hemiblock is seen in","o":["1'' degree heart block","Complete heart block","Mobitz type II block","Bi-fascicular block"],"a":3,"e":"Ans. is ''d'' i.e., Bi-fascicular block Bifascicular block → combination of RBBB with either left anterior hemiblock or left posterior hemiblock. Tri fascicular block → RBBB plus either LAHB/LPHB+ first degree AV block. Complete heart block destruction of → AV node leading to AV dissociation","pyqMatches":[{"year":"2014","no":1451,"q":"Alternating RBBB with Left anterior hemiblock is seen in","o":["1'' degree heart block","Complete heart block","Mobitz type II block","Bi-fascicular block"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2773, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 334, '{"id":2773,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":334,"q":"In LVH, SV1 +RV6 is more than mm","o":["25","30","35","45"],"a":2,"e":"Ans. is ''c'' i.e., 35 Arrhythmias by Kathryn Lewis p. 219] o In LVH, SV-1 plus RV-6 is more than 15 mm. To diagnose the left ventricular hypertrophy on ECG one of the following criteria should be met :? The sokolow-lyon criteria is most often used - R in V, or V6 + 5 in V > 35 mm in men The cornell-criteria has different values R in aVL and S in V3 > 28 mm in men R in aVL and S in V3 > 20 mm in women As the left ventricular wall becomes thicker QRS complexes are larger in leads V1-V6 S wave is deep in V, R wave is high in V4 ST depression in V„-V, (strain pattern)","pyqMatches":[{"year":"2014","no":1453,"q":"In LVH, SV1 +RV6 is more than mm","o":["25","30","35","45"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2774, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 335, '{"id":2774,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":335,"q":"Most common site for berry aneurysm rupture","o":["Anterior circulation of brai","Posterior circulation of brain","Ascending aorta","Descending aorta"],"a":0,"e":"Ans. is ''a'' i.e., Anterior circulation of brain The most common sites in descending order of frequency are - Li Proximal portion of anterior communicating artery (at the junction of anterior communicating artery with cerebral artery) At the origin of the posterior communicating artery from the stem of the internal carotid artery. At the first major bifurcation of middle cerebral artery. At the bifurcation of internal carotid into middle and anterior cerebral arteries. Vertibrobasilar bifurcation (3%)","pyqMatches":[{"year":"2014","no":1383,"q":"Most common site for berry aneurysm rupture","o":["Anterior circulation of brai","Posterior circulation of brain","Ascending aorta","Descending aorta"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2775, 'Medicine', 'Endocrinology', 'Moderate', 'Internal_Medicine', 336, '{"id":2775,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":336,"q":"Obesity is seen in all except","o":["Cushing syndrome","Pickwinian syndrome","Prader willi syndrome","Sipple syndrome"],"a":3,"e":"Ans. is `d'' i.e., Sipple syndrome Important syndromes associated with obesity Albright hereditary osteodystrophy (pseudohypoparathyroidism type la) Alstrom syndrome Bardet-Biedl syndrome Beckwith-Wiedemann syndrome Carpenter syndrome Cohen syndrome • Prader-willi syndrome","pyqMatches":[{"year":"2014","no":1384,"q":"Obesity is seen in all except","o":["Cushing syndrome","Pickwinian syndrome","Prader willi syndrome","Sipple syndrome"],"a":3,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":1214,"q":"Obesity is seen in all except","o":["Cushing syndrome","Pickwinian syndrome","Prader willi syndrome","Sipple syndrome"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2776, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 337, '{"id":2776,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":337,"q":"Cause of death in diabetic ketoacidosis in children","o":["Cerebral edema","Hypokalemia","Infection","Acidosis"],"a":0,"e":"Ans. is ''a'' i.e., Cerebral edema High blood sugar will cross the blood-brain barrier and simultaneously will draw water inside leading to cerebral edema. Cerebral edema accounts for 60-90% of all DKA related deaths in children. Infection is a precipitator for the development of DKA. Other precipitating factors can be tissue ischemia, inadequate insulin administration, drugs (cocaine) and pregnancy.","pyqMatches":[{"year":"2014","no":1385,"q":"Cause of death in diabetic ketoacidosis in children","o":["Cerebral edema","Hypokalemia","Infection","Acidosis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2777, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 338, '{"id":2777,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":338,"q":"Acute hyponatremia becomes symptomatic at","o":["< 135 mEq","< 125 mEq","< 120 mEq","< 110 mEq"],"a":1,"e":"Ans. is ''b'' i.e., < 125 mEq Serum level of sodium at which symptoms develop Acute < 125 meq/L Chronic < 120 meq/L Hyponatremia is commonly defined as a serum sodium < 135 mmol/L (< 135 mEq/L). Neurological symptoms occur at different levels of low sodium, depending not only on the absolute value but also on the rate of fall. In patients with hyponatremia that develops over hours, life- threatening seizures and cerebral edema may occur at values as high as 125 mmol/L. In contrast, some patients with more chronic hyponatremia that has slowly developed over months to years may be asymptomatic even with serum levels < 110 mmol. Acute or hvperacute hvponatremia The hyponatremia developed within the previous 24 hours, it is called \"acute.\" If the hyponatremia developed over just a few hours due to a marked increase in water intake (self-induced water intoxication, as may be seen in marathon runners, psychotic patients, and users of ecstasy), it is called \"hyperacute.\" Chronic hyponatremia If it is known that the hyponatremia has been presentfbr more than 48 hours, or if the duration is unknown (such as in patients who develop hyponatremia at home), it is called \"chronic.\" Mild to moderate hyponatremia Mild hyponatremia is usually defined as a serum sodium concentration between 130 and 135 meq/L. Moderate hyponatremia is often defined as a serum sodium concentration between 121 and 129 meq/L. Severe hvponatremia Severe hyponatremia can be defined as a serum sodium of 120 meq/L or less. Symptoms of hvponatremia Absent symptoms Patients with hyponatremia are frequently asymptomatic, particularly if the hyponatremia is chronic and of mild or moderate severity (ie, serum sodium >120 meq/L). However, such patients may have subclinical impairments in mentation and gait. Mild to moderate symptoms Mild to moderate symptoms of hyponatremia are relatively nonspecific and include headache, nausea, vomiting, fatigue, gait disturbances, and confusion. In patients with chronic hyponatremia (ie, >48 hours duration), these findings are not associated with impending herniation; however, in patients with more acute hyponatremia, such symptoms should be considered ominous and may evolve without warning to seizures, respiratory arrest, and herniation. Severe symptoms Severe symptoms of hyponatremia include u Seizures Obtundation Coma Respiratory arrest.","pyqMatches":[{"year":"2014","no":1386,"q":"Acute hyponatremia becomes symptomatic at","o":["< 135 mEq","< 125 mEq","< 120 mEq","< 110 mEq"],"a":1,"source":"NEET_2014_Paper.pdf"},{"year":"2016","no":1152,"q":"Acute hyponatremia becomes symptomatic at","o":["< 135 mEq","< 125 mEq","< 120 mEq","< 110 mEq"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2014","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2778, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 339, '{"id":2778,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":339,"q":"Hyponatremia is seen in","o":["Hyperthyroidism","Hypothyroidism","Diabetes insipidus","Increased insensible losses"],"a":1,"e":"Ans. is ''b'' i.e., Hypothyroidism [RefHarrison''s 18th Hypothyroidism is characterised by low cardiac output leading to increased AVP production and resultant hyponatremia. Addison disease must be ruled out in chronic cases of hyponatremia Major causes of hyponatremia Disorders in which ADH levels are elevated Effective circulating volume depletion True volume depletion Heart failure Cirrhosis Thiazide diuretics Syndrome of inappropriate ADH secretion, including reset osmostat pattern Hormonal changes Adrenal insufficiency Hypothyroidism Pregnancy Disorders in which ADH levels may be appropriately suppressed Advanced renal failure Primary polydipsia Beer drinker''s potomama Hyponatremia with normal or elevated plasma osmolality High plasma osmolality (effective osmols) Hyperglycemia Mannitol High plasma osmolality (ineffective osmols) Renal failure Alcohol intoxication with an elevated serum alcohlo concentration Normal plasma osmolality Psedohyponatremia (laboratory artifact) High triglycerides Chloestatic and obstructive jaundice (lipoprotein x) Multiple myeloma Absorption of irrigant solutions Glycine Sorbitol Mannitol","pyqMatches":[{"year":"2014","no":1334,"q":"Hyponatremia is seen in","o":["Hyperthyroidism","Hypothyroidism","Diabetes insipidus","Increased insensible losses"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2779, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 340, '{"id":2779,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":340,"q":"Chronic Non-Spherocytic hemolytic anemia is seen in which class of G6PD deficiency","o":["Class I","Class II","Class III","Class IV"],"a":0,"e":"Ans. is ''a'' i.e., Class I The four forms of symptomatic G6PD deficiency : Acute hemolytic anemia Favism Congenital nonspherocytic hemolytic anemia Neonatal hyperbilirubinemia Congenital nonspherocvtic hemolytic anemia Patients with class I G6PD variants have such severe G6PD deficiency that lifelong hemolysis occurs in the absence of infection or drug exposure. Such patients fall under the category of having congenital nonspherocvtic hemolytic anemia. These G6PD variants have low in vitro activity and/or marked instability of the molecule, and most have DNA mutations at the glucose-6-phosphate or NADP binding sites. These sites are central to the function of G6PD, which oxidizes glucose-6-phosphate and reduces NADP to NADPH. It is presumed that the functional defect is so severe that the red cells cannot withstand even the normal oxidative stresses encountered in the circulation. Anemia and jaundice are often first noted in the newborn period, and the degree of hyperbilirubinemia is frequently of sufficient severity to require exchange transfusion. After infancy, hemolytic manifestations are subtle and inconstant. Most individuals have mild to moderate anemia (hemoglobin 8 to 10 g/dL) with a reticulocyte count of 10 to 15 percent. Pallor is uncommon, scleral icterus is intermittent, splenomegaly is rare, and splenectomy generally is of little benefit. Hemolysis can be exaggerated by exposure to drugs or chemicals with oxidant potential or exposure to fava beans. Some drugs with relatively mild oxidant potential that are safe in patients with class II or class III G6PD variants may increase hemolysis in patients with class I variants. Disease variants of Glucose 6 phosphate dehvdrogenase deficiency The World Health Organization has classified the different G6PD variants according to the magnitude of the enzyme deficiency and the severity of hemolysis. Classes IV and V are of no clinical significance. TypesFeatures Class I Variants have severe enzyme deficiency (less than 10 percent of normal) and have chronic (nonspherocytic) hemolytic anemia. Class II Variants, such as G6PD Mediterranean, also have severe enzyme deficiency, but there are, usually only intermittent episodes of acute hemolysis associated with infection, drugs, or chemicals. Class Variants, such as G6PD A-, have moderate enzyme deficiency (10 to 60 percent of normal) with intermittent III episodes of acute hemolysis usually associated with infection, drugs, or chemicals Class IV Variants have no enzyme.deficiency or hemolysis. Class V Variants have increased enzyme activity","pyqMatches":[{"year":"2014","no":1475,"q":"Chronic Non-Spherocytic hemolytic anemia is seen in which class of G6PD deficiency","o":["Class I","Class II","Class III","Class IV"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2780, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 341, '{"id":2780,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":341,"q":"What is the Neutrophil count for moderate neutropenia","o":["< 500/mm''","500-1000/mm''","> 1000/mm3","100/mm3"],"a":1,"e":"Ans. is ''b'' i.e., 500-1000mm'' Mild neutropenia → Is present when the ANC is 1000- 15000 cells/µL Moderate neutropenia → Is present with an ANC of 500-1000/4 Severe neutropenia ANC lower than 500 cells/pL. The risk of bacterial infection is related to both the severity and duration of the neutropenia.","pyqMatches":[{"year":"2014","no":1387,"q":"What is the Neutrophil count for moderate neutropenia","o":["< 500/mm''","500-1000/mm''","> 1000/mm3","100/mm3"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2781, 'Medicine', 'Rheumatology', 'Easy', 'Internal_Medicine', 342, '{"id":2781,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":342,"q":"Gout can be precipitated by all of the following","o":["Thiazides","Furosemide","Cyclosporine","High dose salicylates"],"a":3,"e":"Ans. is ''d'' i.e., High dose salicylates High dose Salicylates are uricosuric and do not cause Hyperuricemia. Diuretics including Thiazides and Furosemide are known to cause Hyperuricemia. Cyclosporine and Tacrolimus are also associated with Hyperuricemia. High Doses of Salicylates > 3.0 g/day are uricosuric, while Low doses (0.3 to 3.0 g/day) are associated with uric acid retention and Hyperuricemia. Also know Causes of drug or diet induced hvperuricemia. Diuretics (thiazides and loop diuretics) Cyclosporine and tacrolimus. Low dose salicylates. Ethambutol. Pyrazinamide. Ethanol. Levodopa. Methoxyflurane. Laxative abuse (alkalosis). Salt restriction.","pyqMatches":[{"year":"2014","no":1390,"q":"Gout can be precipitated by all of the following","o":["Thiazides","Furosemide","Cyclosporine","High dose salicylates"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2782, 'Medicine', 'Infectious Diseases', 'Hard', 'Internal_Medicine', 343, '{"id":2782,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Hard","source":"Internal_Medicine","sourceNo":343,"q":"Relative risk of developing TB in patients already infected with TB bacilus is highest in","o":["Diabetes","Recent infection","Post transplantation","Malnutrition"],"a":2,"e":"Ans. is ''c'' i.e., Post transplantation Relative risk of developing T.B. Post transplantation 20- 70 HIV 30 Silicosis 30 Recent infection 12 Diabetes 3-4 Malnutrition 2-3","pyqMatches":[{"year":"2014","no":1391,"q":"Relative risk of developing TB in patients already infected with TB bacilus is highest in","o":["Diabetes","Recent infection","Post transplantation","Malnutrition"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2783, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 344, '{"id":2783,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":344,"q":"I.R.I.S. is","o":["Immune reconstitution idiopathic syndrome","Immune reconstitution immunological syndrome","Immune reconstitution inflammatory syndrome","Inflammatory reconstitution immune syndrome"],"a":2,"e":"Ans. is ''c'' i.e., Immune reconstitution inflammatory syndrome Causes of bone marrow suppression in patients with HIV infection HIV infection Medications Mycobacterial infections Zidovudine Fungal infections Dapsone B 19 parvovirus infection Trimethoprim/Sulfamethoxazole Lymphoma Pyrimethamine 5-Flucytosine Ganciclovir Interferon a Trimetrexate Foscarnet","pyqMatches":[{"year":"2014","no":1392,"q":"I.R.I.S. is","o":["Immune reconstitution idiopathic syndrome","Immune reconstitution immunological syndrome","Immune reconstitution inflammatory syndrome","Inflammatory reconstitution immune syndrome"],"a":2,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":1193,"q":"I.R.I.S. is","o":["Immune reconstitution idiopathic syndrome","Immune reconstitution immunological syndrome","Immune reconstitution inflammatory syndroma","Inflammatory reconstitution immune syndrome"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2784, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 345, '{"id":2784,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":345,"q":"In renal failure, metabolic acidosis is due to","o":["Increased fr production","Loss of HCO,","Decreased ammonia synthesis","Use of diuretics"],"a":2,"e":"Ans. is ''c'' i.e., Decreased ammonia synthesis The predominant reason for metabolic acidosis in C.R.E is decreased ammonia production. Metabolic acidosis is a common disturbance in advanced chronic kidney disease The majority of patients can still acidly the urine but they produce less ammonia and, therefore, cannot excrete the normal quantity of protons in combination with this urinary buffer.","pyqMatches":[{"year":"2014","no":1393,"q":"In renal failure, metabolic acidosis is due to","o":["Increased fr production","Loss of HCO,","Decreased ammonia synthesis","Use of diuretics"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2785, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 346, '{"id":2785,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":346,"q":"Diagnostic feature of CRF is","o":["Broad casts in urine","Elevated blood urea","Proteinuria","Bleeding diathesis"],"a":0,"e":"Ans. is ''a'' i.e., Broad casts in urine Casts ? Urinary casts are formed only in the distal convoluted tubulee (DCT) or the collecting dude (distal nephron). The proximal convoluted tubule and loop of henle are not the locations for cast formation. Casts are formed through the solidification of materials in the tubules of nephrons Later the material is flushed out of the kidney upon the production of more urine leaving a small solidified microscopic cylinder that can also contain what ever other materials that might be within the tubules of the kidneys at the time of cast formation. The microscopic detection of various types of casts can often be helpful diagnostic tool in the study of various types of renal diseases","pyqMatches":[{"year":"2014","no":1394,"q":"Diagnostic feature of CRF is","o":["Broad casts in urine","Elevated blood urea","Proteinuria","Bleeding diathesis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2786, 'Medicine', 'Hematology', 'Moderate', 'Internal_Medicine', 347, '{"id":2786,"subject":"Medicine","chapter":"Hematology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":347,"q":"Eosinophilic meningitis is seen with all except?","o":["Coccidiomycosis","Cryptococcal meningitis","Lepto meningeal metastasis","Helminthic infections"],"a":1,"e":"Ans. is ''b'' i.e., Cryptococcal meningitis Causes of eosinophilic meningitis Infectious, parasitic causes Roundworm (nematode) infections - commonly present as eosinophilic meningitis Angiotronglylus cantonensis - migrating larvae inherently neurotropic Gnathostoma spinigerum - migrating larvae in visceral and/or neural tissues Baylisascaris procyonis - migrating larvae inherently neurotropic Tapeworm (cestode) infections - may present as eosinophilic meningitis Cysticercosis -Cysts develop in CNS and/or visceral tissues Fluke (trematode) infections - occasionally cause eosinophilic meningitis Paragonimus westermani - ectopic spinal or cerebral localization. Schistosomiasis - ectopic spinal or cerebral localization. Fascioliasis - ectopic CNS localization. Other roundworm infections which occasionally cause eosinophilic meningitis Toxocariasis - migrating larvae Nonparasitic, infectious causes Coccidioidomycosis Cryptococcosis - CSF eosinophilia rare Myiasis - with CNS penetration Virus and bacteria - are of uncertain causality Noninfectious causes Idiopathic hypereosinophilic syndromes Ventriculoperitoneal shunts Leukemia or lymphoma with CNS involvement (Hodgkin''s) Nonsteroidal antiinflammatory drugs Antibiotics - ciprofloxacin, trimethoprim - sulfamethoxazole, intraventricular gentamicin or vancomycin Myelography contrast agents","pyqMatches":[{"year":"2014","no":1395,"q":"Eosinophilic meningitis is seen with all except?","o":["Coccidiomycosis","Cryptococcal meningitis","Lepto meningeal metastasis","Helminthic infections"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2787, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 348, '{"id":2787,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":348,"q":"Christmas tree appearance of urinary bladder is seen in","o":["Neurogenic bladder","Stress incontinence","Autonomous bladder","Enuresis"],"a":0,"e":"Ans. is ''a'' i.e., Neurogenic bladder Christmas tree appearance of the bladder is seen in neurogenic bladder caused by detrusor hyperreflexia. Detrusor hyperreflexia is caused by lesions of the spinal cord above the sacral segments but below the pons. Such patients have noperception of bladder filling or emptying and voluntary voiding is not possible. Voiding when it does occur is involuntary with simultaneous contractions of the detrusor and external sphincter muscles. Common neurological condition resulting in detrusor hyperreflexia include Multiple sclerosis Myelodysplasia, Spinal cord trauma Spinal cord tumours, A-V malformatio not the spinal cord Radiologically, patients with long terms untreated detrusor hyperreflaxia have characteristic changes of the urinary tact. Bladder is vertically oriented, with an irregular contours, consistent with trabeculation. There are frequently multipel diverticula, Such a bladder is referred to as a christmas tree. Automatic bladder Autonomous bladder Lesion site Above T5 or higher Cauda equina damage / lower motero neuron ManifestationSmall spastic bladder damage Large flaccid bladder Why this name urge comes again and again due to repeated contractions and hence empties repeatedly after some time Has no urge sensation and continuous DRIBBLING occurs, So it is like the bladder is working all the time but Brain has no control over it and hence called autonomous bladder Radiological data Christmas tree appearance No VUR but still bladder is large and holds lots of residual urine","pyqMatches":[{"year":"2014","no":1396,"q":"Christmas tree appearance of urinary bladder is seen in","o":["Neurogenic bladder","Stress incontinence","Autonomous bladder","Enuresis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2788, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 349, '{"id":2788,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":349,"q":"the diffusion capacity of lung (DL) is decreased in all of the following conditions except","o":["Inerstitial lung diseas","Goodpasture''s syndrome","Pneumocystis Jiroveci","Primary pulmonary hypertension"],"a":1,"e":"Ans. is ''b'' i.e., Goodpasture''s syndrome Gas diffusion tests : Gas diffusion tests measure the amount of oxygen and other gases that cross the alveoli into the blood. These tests evaluate how well gases are being absorbed into the blood from lungs. Gas diffusion tests include. Carbon monoxide diffusing capacity (transfer factor DLcy) Arterial blood gases Carbon monoxide diffusing capacity (DL): This measures how well the lung transfers a small amount of carbon monoxide into the blood0. Normally, in the lung, a gas has to cross the alveolar membrane, capillary membrane to reach the blood where it combines with hemoglobin. So quiet obviously the diffusion capacity of gas depends upon Driving pressure of the gas Surface area of alveolar capillary membrane Thickness of alveolar capillary membrane Diffusion coefficient of the gas Red blood cell volume. Reaction rate with hemoglobin and hemoglobin level of patient. Degree of V/Q mismatching.","pyqMatches":[{"year":"2014","no":1400,"q":"the diffusion capacity of lung (DL) is decreased in all of the following conditions except","o":["Inerstitial lung diseas","Goodpasture''s syndrome","Pneumocystis Jiroveci","Primary pulmonary hypertension"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2789, 'Medicine', 'Rheumatology', 'Easy', 'Internal_Medicine', 350, '{"id":2789,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":350,"q":"Keratoderma-Blenorrhagicum is pathogno-monic of","o":["Behcet''s disease","Reiter''s disease","Lyme''s disease","Glucagonoma"],"a":1,"e":"Ans. is ''b'' i.e., Reiter''s disease Keratoderma Blenorrhagica is the characteristic skin lesion seen in patients with Reactive Arthritis. \"The Characteristic skin lesions in Reactive Arthritis, Keratoderma Blenorrhagica, consist of vesicles that become hyperkeratotic, ultimately forming a crust before disappearing. These are seen in palms and soles.","pyqMatches":[{"year":"2014","no":1389,"q":"Keratoderma-Blenorrhagicum is pathogno-monic of","o":["Behcet''s disease","Reiter''s disease","Lyme''s disease","Glucagonoma"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2790, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 351, '{"id":2790,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":351,"q":"In Takayasu''s arteritis there is","o":["Intimal fibrosis","Renal hypertension","Coronary aneurysm","All of the above"],"a":1,"e":"Ans. is `b'' i.e., Renal hypertension Artery Potential clinical manifestation Subclavian Arm claudication, Raynaud''s phenomenon Commoncarotid Visual changes, syncope transient, ischaemic attacks stroke AbdominalAorta Abdominal pain, nausea vomiting Renal Hypertension, renal failure, aortic insufficiency, congestive heart failure Vertebral Visual changes, dizziness Coeliac axis Abdominal pain, nausea vomiting Iliac Leg claudication Pulmonary Atypical chest pain dyspnea Coronary Chest pain myocardial infarction","pyqMatches":[{"year":"2014","no":1485,"q":"In Takayasu''s arteritis there is","o":["Intimal fibrosis","Renal hypertension","Coronary aneurysm","All of the above"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2791, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 352, '{"id":2791,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":352,"q":"Which is not a high pitched heart sound","o":["Mid systolic click","Pericardial shudder","Opening snap","Tumor plop sound"],"a":3,"e":"Ans. is ''d'' i.e., Tumor plop sound Low pitch heart sounds are : S3 S4 Tumor plop sound Mid systolic clicks are Heard in mitral valve prolapse during systole and are high pitch sounds. The pericardial knock (PK) is Also high-pitched and occurs slightly later than the opening snap, corresponding in timing to the abrupt cessation of ventricular expansion after tricuspid valve opening and to an exaggerated y descent seen in the jugular venous waveform in patients with constrictive pericarditis. A tumor plop is A lower-pitched sound that can be heard in patients with atrial myxoma. It may be appreciated only in certain positions and arises from the diastolic prolapse of the tumor across the mitral valve","pyqMatches":[{"year":"2014","no":1454,"q":"Which is not a high pitched heart sound","o":["Mid systolic click","Pericardial shudder","Opening snap","Tumor plop sound"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2792, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 353, '{"id":2792,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":353,"q":"Broad complex tachycardia, due to ventricular tachycardia is suggested by all except","o":["Fusion beats","AV dissociation","Capture beats","Termination of tachycardia by carotid sinus massage"],"a":3,"e":"Ans. is `d'' i.e., Termination of tachycardia by carotid sinus massage","pyqMatches":[{"year":"2014","no":1455,"q":"Broad complex tachycardia, due to ventricular tachycardia is suggested by all except","o":["Fusion beats","AV dissociation","Capture beats","Termination of tachycardia by carotid sinus massage"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2793, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 354, '{"id":2793,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":354,"q":"Rupture of berry aneurysm most commonly results in","o":["Subarachnoid hemorrhage","Subdural hemorrhage","Extradural hemorrhage","Intra-parenchymal hemorrhage"],"a":0,"e":"Ans. is ''a'' i.e., Subarachnoid hemorrhage Most common cause of subarachnoid hemorrhage Trauma Most common cause of spontaneoussubarachnoid hemorrhage Rupture of Berry aneurysm (or Saccular aneurysm) Also know Mycotic aneurysm ? Mycotic aneurysm is caused by a septic embolus that weakens the wall of the vessel in which it lodges.","pyqMatches":[{"year":"2014","no":1401,"q":"Rupture of berry aneurysm most commonly results in","o":["Subarachnoid hemorrhage","Subdural hemorrhage","Extradural hemorrhage","Intra-parenchymal hemorrhage"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2794, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 355, '{"id":2794,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":355,"q":"Target BP before thrombolysis in ischemic stroke is below","o":["185/110 mmHg","165/100 mm Hg","145/100 Hg","120/80 mm Hg"],"a":0,"e":"Ans. is ''a'' i.e., 185/110 mm Hg Recommended target blood pressure before thrombolysis in patients with ischemic stroke is less than 185/110mm Hg.","pyqMatches":[{"year":"2014","no":1402,"q":"Target BP before thrombolysis in ischemic stroke is below","o":["185/110 mmHg","165/100 mm Hg","145/100 Hg","120/80 mm Hg"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2795, 'Medicine', 'Hematology', 'Easy', 'Internal_Medicine', 356, '{"id":2795,"subject":"Medicine","chapter":"Hematology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":356,"q":"The most common cause of malignant adrenal mass is","o":["Adrenocortical carcinoma","Malignant phaeochromocytoma","Lymphoma","Metastasis from another solid tissue tumor"],"a":3,"e":"Ans. is ''d'' i.e., Metastasis from another solid tissue tumor The most common cause of adrenal tumors is metastasis from another solid tumor like breast cancer and lung cancer. Malignant Percentage Adrenocortical carcinoma 2-5% Malignant pheochromocytoma <I% Adrenal neuroblastoma <0- 1% Lymphomas (incl. primary adrena lymphoma) <1% Metastases (most frequent : Breast, lung) 15%","pyqMatches":[{"year":"2014","no":1403,"q":"The most common cause of malignant adrenal mass is","o":["Adrenocortical carcinoma","Malignant phaeochromocytoma","Lymphoma","Metastasis from another solid tissue tumor"],"a":3,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":1141,"q":"The most common cause of malignant adrenal mass is","o":["Adrenocortical carcinoma","Malignant phaeochromocytoma","Lymphoma","Metastasis from another solid tissue tumor"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2796, 'Medicine', 'Endocrinology', 'Hard', 'Internal_Medicine', 357, '{"id":2796,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":357,"q":"The drug used in the management of medullary carcinoma thyroid is","o":["Cabozantinib","Rituximab","Tenofovir","Anakinra"],"a":0,"e":"Ans.is ''a'' i.e., Cabozantinib Medullary thyroid cancers (MTCs) are neuroendocrine tumors of thyroid paraf011icular cells that do not concentrate iodine. The primary treatment for MTC is extensive and meticulous surgical resection. There is a limited role for external-beam radiotherapy. For patients with asymptomatic metastatic tumors generally less than 1 to 2 cm in diameter, growing in diameter less than 20 percent per year Systemic therapy is not required Such patients should be monitored for disease progression. Known sites of metastatic disease should be imaged by CT or MRI every 6 to 12 months, and potential new sites of disease should be imaged every 12 to 24 months. For patients with metastatic tumors at least 1 to 2 cm in diameter, growing by at least 20 percent per year, or Or patients with symptoms related to multiple metastatic foci that cannot be alleviated with surgery or external beam radiotherapy Administer systemic treatment as part of a clinical trial. Forpatients with metastatic tumors at least I to 2 cm in diameter, growing by at least 20 percent per year, or for patients with .symptoms related to multiple metastatic foci who cannot participate in a clinical trial An oral tyrosine kinase inhibitor (TKI) is suggested, rather than traditional cytotoxic chemotherapy. For initial TKI therapy Cabozantinib or vandetanib rather than sorafenib or sunitinib. Cytotoxic chemotherapy, of which dacarbazine-based regimens such as cyclophosphamide-vincristine​dacarbazine are preferable, is an alternative option for patients who cannot tolerate or who fail multiple TKIs Drugs used in medullary carcinoma thyroid Tyrosine kinase inhibitors Cvtotoxic chemotherapy CabozanitibCyclophosphamide Vandetanib Vincristine Sorafenib Dacarbazine Sunitinib","pyqMatches":[{"year":"2014","no":1404,"q":"The drug used in the management of medullary carcinoma thyroid is","o":["Cabozantinib","Rituximab","Tenofovir","Anakinra"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2797, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 358, '{"id":2797,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":358,"q":"Incorrect about cerebral salt wasting syndrome","o":["Urine sodium > 20mEq/d1","Hyponatremia","Fludrocortisone is used","Expansion of plasma volume"],"a":3,"e":"Ans. is ''d'' i.e., Expansion of plasma volume Cerebral salt wasting syndrome (renal salt wasting) Cerebral salt wasting (CSW) is characterized by hyponatremia and extracellular fluid depletion due to inappropriate sodium wasting in the urine in the setting of acute disease in central nervous system (CNS), usually subarachnoid hemorrhage. CSW is a much less common cause of hyponatremia in patients with cerebral injury than the syndrome of inappropriate ADH secretion (SIADH). The pathophysiology of CSW is related to impaired sodium reabsorption, possibly due to the release of brain natriuretic peptide and/or diminished central sympathetic activity. Regardless of the mechanism, sodium wasting can lead sequentially to volume depletion, increased ADH release, hyponatremia due to the associated water retention, and possibly increased neurologic injury. Laboratory findings Hyponatremia with a low plasma osmolality An inappropriately elevated urine osmolality (above 100 mosmol/kgand usually above 300mosmol/kg) A urine sodium concentration above 40meq/L, and A low serum uric acid concentration due to urate wasting in the urine. CSW mimics all of the laboratory findings in the SIADH The only clue to the presence of CSW rather than SIADH is clinical evident of extracellular volume depletion, such as hypotension and decreased skin turgor, and/or increased hematocrit, in a patient with a urine sodium concentration above 40meq/L Unlike SIADH, volume repletion in CSW leads to a dilute urine, due to removal of the hypovolemic stimulus to ADH release, and subsequent correction of the hyponatremia. Treatment IV hypertonic saline solutions are employed to correct intravascular vloume depletion and hyponatremia and to replace ongoing urinary sodium loss Flurocortisone promotes sodium re-absorption","pyqMatches":[{"year":"2014","no":1405,"q":"Incorrect about cerebral salt wasting syndrome","o":["Urine sodium > 20mEq/d1","Hyponatremia","Fludrocortisone is used","Expansion of plasma volume"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2798, 'Medicine', 'Neurology', 'Hard', 'Internal_Medicine', 359, '{"id":2798,"subject":"Medicine","chapter":"Neurology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":359,"q":"A 70 kg adult male presents with serum sodium of 110 meq/dl. Calculate correction required in 24 hours","o":["100 mEq","200 mEq","300 mEq","400 mEq"],"a":3,"e":"Ans. is `d'' i.e., 400 mEq Goals of therapy in hyponatremia In patients who are treated to increase the serum sodium, the goal of initial therapy is to raise the serum sodium concentration by 4 to 6 meq/L in a 24-hour period. In patients who require emergency therapy, this goal should be achieved quickly, over six hours or less; thereafter, the serum sodium can be maintained at a constant level for the remainder of the 24-hour period to avoid overly rapid correction. Every effort should be made to keep the rise in serum sodium less than 9 meq/L in anv 24-hour period. In general, the same rate of rise can be continued on subsequent days until the sodium is normal or near normal. The rationale for these recommendations is as follows: Sodium deficit = Total body water x desired SNa - Actual SNa = .6 x 70 x 120 - 110 =420 mEq Treatment of hvponatrentia Aprviatitleaet_uIsupon risk stratification The following general approach for treating patients with hyponatremia is based upon the duration and severity of the hyponatremia and upon the presence and severity of symptoms: Disposition Patients with acute or hyperacute hyponatremia, most patients with severe hyponatremia, and many symptomatic patients with moderate hyponatremia should be treated in the hospital. In contrast, patients with mild hyponatremia and asymptomatic patients with moderate hyponatremia usually do not require hospitalization. Emergency therapy Aggressive therapy to raise the serum sodium as soon as possible (typically with hypertonic saline) is indicated in the following settings. Patients with severe symptoms due to hyponatremia, such as seizures or obtundation. Patients with acute hyponatremia who have symptoms due to hyponatremia, even if such symptoms are mild. Because of osmotically driven water flow across the blood-brain barrier, an acute onset of hyponatremia can result in life-threatening cerebral edema. Thus, even mild symptoms in acute hyponatremia present a medical emergency that requires prompt and aggressive treatment with hypertonic saline to prevent brain herniation. Patients with hyperacute hyponatremia due to self-induced water intoxication, even if there are no symptoms at the time of initial evaluation. Brain herniation has been reported in such patients, and the serum sodium may worsen spontaneously due to delayed absorption of ingested water Symptomatic patients who have either acute postoperative hyponatremia or hyponatremia associated with intracranial pathology. As with hyperacute hyponatremia, herniation may occur; and the serum sodium may decrease further because of absorption of ingested water or the excretion of high concentrations of sodium in the urine (desalination).","pyqMatches":[{"year":"2014","no":1406,"q":"A 70 kg adult male presents with serum sodium of 110 meq/dl. Calculate correction required in 24 hours","o":["100 mEq","200 mEq","300 mEq","400 mEq"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2799, 'Medicine', 'Hematology', 'Easy', 'Internal_Medicine', 360, '{"id":2799,"subject":"Medicine","chapter":"Hematology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":360,"q":"Which of the following is a quantitative defect in globin synthesis","o":["Thalassemia","Sickle cell hemoglobinopathy","G6PD deficiency","Diamond-Black fan syndrome"],"a":0,"e":"Ans. is ''a'' i.e., Thalassemia The thalassemia syndromes are a heterogeneous group of disorders caused by inherited mutations that decrease the synthesis of either the c-globin or p-globin chains that compose adult hemoglobin, HbA (c2p2), leading to anemia, tissue hypoxia, and red cell hemolysis related to the imbalance in globin chain synthesis.","pyqMatches":[{"year":"2014","no":1477,"q":"Which of the following is a quantitative defect in globin synthesis","o":["Thalassemia","Sickle cell hemoglobinopathy","G6PD deficiency","Diamond-Black fan syndrome"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2800, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 361, '{"id":2800,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":361,"q":"The most important diagnositic feature for beta thalassemia trait","o":["Raised HbF","Reduced MCH","Reduced MCV","Raised HbA2"],"a":3,"e":"Ans. is ''d'' i.e., Raised HbA2 An abnormal increase in the level of HbA2 is the most significant parameter in the diagnosis of beta-thalassemia carriers. HbA-2 is constanly elevated in heterozygous carriers of [3-thalassemia in all the ethnic groups studied. The values range from 3.5 to 7%. Investigations in thalassemia Hemoglobin electrophoresis should always be the first investigation to include/exclude the diagnosis of thalasemia. The level of normal adult hemoglobin HbA is markedly decreased with proportionate increase in HbA2 and HbF. X-ray skull shows :? i) Crew-cut appearance ii) Hair on end appearance","pyqMatches":[{"year":"2014","no":1478,"q":"The most important diagnositic feature for beta thalassemia trait","o":["Raised HbF","Reduced MCH","Reduced MCV","Raised HbA2"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2801, 'Medicine', 'Rheumatology', 'Hard', 'Internal_Medicine', 362, '{"id":2801,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":362,"q":"Uricase used in the treatment of chronic gout is","o":["Allopurinol","Benzbromarone","Pegloticase","Methotrexate"],"a":2,"e":"Ans. is ''c'' i.e., Pegloticase Pegloticase is a recombinant mammalian Uricase linked to polyethylene glycol (PEG) approved for the treatment of Hyperuricemia in patients with treatment refractory gout. Pegloticase facilitates the conversion of Uric acid into allantoin, which is far more soluble. Pegloticase is approved for intravenous administration and its use is associated with rapid and marked decline in serum uric acid levels. Agents inhibiting IL-1 action are used for the treatment of refractory Gout Anakinra Canakinumab","pyqMatches":[{"year":"2014","no":1407,"q":"Uricase used in the treatment of chronic gout is","o":["Allopurinol","Benzbromarone","Pegloticase","Methotrexate"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2802, 'Medicine', 'Neurology', 'Moderate', 'Internal_Medicine', 363, '{"id":2802,"subject":"Medicine","chapter":"Neurology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":363,"q":"All are seen in acute HiV syndrome except","o":["Diarrhoea","Pneumonia","Wight loss","Myelopathy"],"a":1,"e":"Ans. is ''b'' i.e., Pneumonia Clinical findings in the acute HIV syndrome General Fever Pharyngitis Lymphadenopathy Headache/retroorbital pain Arthralgias/myalgias Lethargy/malaise Anorexia/weight loss Nausea/vomiting/diarrhea Neurologic Meningitis Encephalitis Peripheral neuropathy Myelopathy Dermatology Erythematous maculo-papular Mucocutaneous rash ulceration [Ref Harrison 19th/e p. 1249]","pyqMatches":[{"year":"2014","no":1409,"q":"All are seen in acute HiV syndrome except","o":["Diarrhoea","Pneumonia","Wight loss","Myelopathy"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2803, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 364, '{"id":2803,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":364,"q":"Nephrocalcinosis is seen in all except","o":["Polycystic kidney","Hyperparathyroidism","Medullary sponge kidney","Renal tubular acidosis"],"a":0,"e":"Ans. is ''a'' i.e., Polycystic kidney Causes of Nephrocalcinosis Medullary sponge kidney Hyperparathyroidism Hypoparathyroidism Renal tubular acidosis (specifically distal RTA) Renal tuberculosis Renal papillary necrosis Hyperoxaluria Immobilization Milk-alkali syndrome Hypervitaminosis D Sarcoidosis","pyqMatches":[{"year":"2014","no":1410,"q":"Nephrocalcinosis is seen in all except","o":["Polycystic kidney","Hyperparathyroidism","Medullary sponge kidney","Renal tubular acidosis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2804, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 365, '{"id":2804,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":365,"q":"Most common acute complication of dialysis is","o":["Hypotension","Bleeding","Dementia","Muscle cramps"],"a":0,"e":"Ans. is ''a'' i.e., Hypotension Hypotension is the most common acute complication of hemodialysis particularly among patients with diabetes mellitus. Factors involved are :- Excessive ultrafiltration, with inadequate compensatory vascular filling, impaired vasoactive or autonomic response, osmolar shifts, overzealous use of antihypertensives","pyqMatches":[{"year":"2014","no":1358,"q":"Most common acute complication of dialysis is","o":["Hypotension","Bleeding","Dementia","Muscle cramps"],"a":0,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":1171,"q":"Most common acute complication of dialysis is","o":["Hypotension","Bleeding","Dementia","Muscle cramps"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2805, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 366, '{"id":2805,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":366,"q":"Characteristic features of a lesion in the lateral part of the medulla include all except","o":["Ipsilateral Homer''s syndrome","Contralateral loss of proprioception to the body and limbs","Nystagmus","Dysphagia"],"a":1,"e":"Ans. is ''b'' i.e., Contralateral loss of proprioception to the body and limbs Damage to lateral part of medulla (lateral medullary syndrome or wallenberg syndrome) causes :? 1) Ipsilateral : Facial sensory loss, facial pain, ataxia, nystagmus, homer syndrome. 2) Contralateral Other features are nausea & vomitng, vertigo dysphagia and horseness.","pyqMatches":[{"year":"2013","no":1243,"q":"Characteristic features of a lesion in the lateral part of the medulla include all except","o":["Ipsilateral Homer''s syndrome","Contralateral loss of proprioception to the body and limbs","Nystagmus","Dysphagia"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2806, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 367, '{"id":2806,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":367,"q":"Round pneumonia is seen with","o":["Streptococcal pneumonia","Kerosene oil aspiration","Lung cancer","Mendelson syndrome"],"a":0,"e":"Ans. is ''a'' i.e., Streptococcal pneumonia Streptococcus Pneumoniae (pneumococcus) is the most common organism responsible for round pneumonia. Round Pneumonia is spherical pneumonia that is usually seen in children due to the lack of collateral air drift. Streptococcus Pneumoniae (pneumococcus) is the most common organism responsible for round pneumonia. Round pneumonia is important as they may simulate a tumor mass from which they must be differentiated","pyqMatches":[{"year":"2014","no":1411,"q":"Round pneumonia is seen with","o":["Streptococcal pneumonia","Kerosene oil aspiration","Lung cancer","Mendelson syndrome"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2807, 'Medicine', 'Respiratory Medicine', 'Hard', 'Internal_Medicine', 368, '{"id":2807,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Hard","source":"Internal_Medicine","sourceNo":368,"q":"An elderly male admitted for Pneumonia presents with diarrhea and gripping abdominal pain five days after discharge from the hospital. Drug which is likely to benefit is","o":["Imodium","Metranidozole","Diphenoxylate","Levofloxacin"],"a":3,"e":"Ans. is ''d'' i.e., Levofloxacin Development of pneumonia and gastrointestinal symptoms (diarrhea & gripping abdominal pain) within 10 days after discharge from hospital hints to a possible diagnosis of Legionnaire''s disease. The drugs of choice for legionnairs''s disease include Azithromycin and Respiratory Fluoroquinolones such as levofloxacin, gatifloxacin, Gemifloxacin and Moxifloxacin It is a case of legionnaire''s disease. Legionnaires disease usually presents as atypical pneumoniae. The unique feature of legionnaires disease is that the clinical manifestation of this disease are usually more severe than those of most atypical pneumonias and the course and prognosis of legionella pneumonia more closely resemble those of bacteremic pneumococcal pneumonia than those ofpneumonia due to other organisms Think about the diagnosis as legionaire''s disease whenever the question talks about a pneumonia like picture along with any of the following - Gastrointestinal disturbances such as diarrhoea. Neurological abnormalities such as confusion and headache altered sensorium. High fever (> 40°C or > 104°F) Numerous neutrophils, but no organisms revealed by gram''s staining of respiratory secretions. Failure to respond to $ lactam drugs (penicillins and cephalosporins) and aminoglycoside antibiotics. Hyponatremia (S.Na- < 131 meq/1) Elevation in liver function tests. Occurrence of illness in an environment in which the potable water supply is known to be contaminated with legionella. Onset of symptoms within 10 days of discharge from hospital. Occurence of illness in immunocompromised individual","pyqMatches":[{"year":"2014","no":1412,"q":"An elderly male admitted for Pneumonia presents with diarrhea and gripping abdominal pain five days after discharge from the hospital. Drug which is likely to benefit is","o":["Imodium","Metranidozole","Diphenoxylate","Levofloxacin"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2808, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 369, '{"id":2808,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":369,"q":"Duration of apnea in obstructive sleep apnea is","o":["<10 sec","<20 sec","<30 sec","<60 sec"],"a":0,"e":"Ans. is ''a'' i.e., <10 sec Sleep apnea ? o Sleep apnea is defined as intermittent cessation of airflow at the nose and mouth during sleep. o By convention apneas of at least 10 seconds duration have been considered important but in most patients the apneas are 20s to 30 seconds in duration and may be as long as 2-3 minutes. o Sleep apnea is of two types - Sleep apnea Obstructive sleep apnea Central sleep apnea Occurs due to occlusion of upperairway at the level of oropharynx Occurs due to transient abolition ofthe central neural drive to the respiratory muscles Conditions associated are adenotonsillarhypertrophy, Primary and secondary central alveolarhypoventilation syndrome, hypoxia (high altitude) retrognathia, macroglossiaalcohol, obesity cardiovascular disease, pulmonary congestion, central nervous system disease, prolonged circulation time. Clinical features of sleep apnea - Excessive daytime sleepiness Cardiorespiratory disturbances which include Recurrent respiratory failure Pulmonary hypertension Heart failure Systemic hypertension 7 Chronic hypoventilation Polycythemia o Arterial blood gas analysis reveals hypoxemia and hypercapnia.","pyqMatches":[{"year":"2014","no":1345,"q":"Duration of apnea in obstructive sleep apnea is","o":["<10 sec","<20 sec","<30 sec","<60 sec"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2809, 'Medicine', 'Respiratory Medicine', 'Moderate', 'Internal_Medicine', 370, '{"id":2809,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":370,"q":"Causes of haemorrhagic pleural effusion are all except","o":["Pulmonary infarction","Mesothelioma","Bronchial adenoma","Tuberculosis"],"a":2,"e":"Ans. is ''c'' i.e., Bronchial adenoma Causes of hemorrhagic pleural effusion Trauma Malignancy Postpericardiotomy syndrome Asbestos related effusion Tuberculosis","pyqMatches":[{"year":"2014","no":1413,"q":"Causes of haemorrhagic pleural effusion are all except","o":["Pulmonary infarction","Mesothelioma","Bronchial adenoma","Tuberculosis"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2810, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 371, '{"id":2810,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":371,"q":"Following is characteristic neurologic finding in primary amyloidosis","o":["Peripheral motor and sensory neuropathy","Peripheral neuropathy associated with cerebral manifestation","Guillain - Barre type of syndrome","Spinal cord compression in thoracic region"],"a":0,"e":"Ans. is ''a'' i.e., Peripheral motor and sensory neuropathy ATTR usually presents as a syndrome of familial amyloidotic polyneuropathy or familial amyloidotic cardiomyopathy. Peripheral neuropathy usually begins as a lower-extremity sensor and motor neuropathy and progresses to the upper extremities. Autonomic neuropathy is manifest by gastrointestinal symptoms of diarrhea with weight loss and orthostatic hypotension.","pyqMatches":[{"year":"2014","no":1414,"q":"Following is characteristic neurologic finding in primary amyloidosis","o":["Peripheral motor and sensory neuropathy","Peripheral neuropathy associated with cerebral manifestation","Guillain - Barre type of syndrome","Spinal cord compression in thoracic region"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2811, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 372, '{"id":2811,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":372,"q":"Reactive arthritis is usually caused by","o":["Shigella flexneri","Shigella boydii","Shigela shiga","Shigela dysentriae"],"a":0,"e":"Ans. is ''a'' i.e., Shigella Flexneri Organisms that have been associated with ReiterArthritis include the following: C trachomatis (L2b serotype) Ureaplasma urealyticum Neisseria gonorrhoeae Shigella flexneri Salmonella enterica serovars Typhimurium Mycoplasma pneumoniae Mycobacterium tuberculosis Yersinia enterocolitica and pseudotuberculosis Campylobacter jejuni Clostridium difficile Beta-hemolytic (example, group A) and viridans streptococci","pyqMatches":[{"year":"2014","no":1415,"q":"Reactive arthritis is usually caused by","o":["Shigella flexneri","Shigella boydii","Shigela shiga","Shigela dysentriae"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2812, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 373, '{"id":2812,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":373,"q":"Which of the following arrhythmia is most commonly associated with alcohol binge in the alcoholics","o":["Ventricular fibrillations","Ventricular premature contractions","Atrial flutter","Atrial fibrilation"],"a":3,"e":"Ans. is ''d'' i.e., Atrial fibrilation When ever the pulse is irregularly irregular atrial fibrillation is almost always the diagnosis. Arrythmia occuring after a drinking binge is k/a Holiday heart syndrome. Arrythmias known to follow drinking Binge in order of frequency Atrial fibrillation (MC) Atrial flutter Ventricular premature Contractions Also know The most common cardiac effect of chronic drinking is Dilated Cardiomyopathy","pyqMatches":[{"year":"2014","no":1456,"q":"Which of the following arrhythmia is most commonly associated with alcohol binge in the alcoholics","o":["Ventricular fibrillations","Ventricular premature contractions","Atrial flutter","Atrial fibrilation"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2813, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 374, '{"id":2813,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":374,"q":"Treatment of asymptomatic bradycardia is","o":["No treatment is required","Give atropine","Isoprenaline","Cardiac pacing"],"a":0,"e":"Ans. is ''a'' i.e., No treatment is required The normal heart rate has been considered historically to range from 60 to 100 beats per minute, with sinus bradycardia being defined as a sinus rhythm with a rate below 60 beats per minute. Treatment is not indicated in asymptomatic patients with sinus bradycardia. n Pharmacologic therapy may be important in an acute myocardial infarction when the SA node is depressed by excessive parasympathomimetic activity or possibly ischemia. Treatment is indicated when Sinus bradycardia results in hemodynamic compromise.","pyqMatches":[{"year":"2014","no":1457,"q":"Treatment of asymptomatic bradycardia is","o":["No treatment is required","Give atropine","Isoprenaline","Cardiac pacing"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2814, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 375, '{"id":2814,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":375,"q":"WPW syndrome is caused by","o":["Bundle Branch Block","Right sided accessory pathway","Ectopic pacemaker in atrium","Left budle Branch block"],"a":1,"e":"Ans. is ''b'' i.e., Right sided accessory pathway Anatomy (Location ofAccessory pathway) in W.R W syndrome Electrophysiological studies and mapping have shown that accessory. Atrioventricular pathways may be located anywhere along the A-V rign or groove in the septum. The most frequent locations are : - Left lateral (50%), posteroseptal (30%) right anteroseptal (10%). Right lateral (10%). Preexcitation resulting from left sided accessory is called type A preexcitation. Preexcitation resulting from right sided accessory pathway is called type B preexcitation.","pyqMatches":[{"year":"2014","no":1458,"q":"WPW syndrome is caused by","o":["Bundle Branch Block","Right sided accessory pathway","Ectopic pacemaker in atrium","Left budle Branch block"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2815, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 376, '{"id":2815,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":376,"q":"Dose of rTPA in ischaemic stroke is","o":["60 mg","90 mg","100 mg","120 mg"],"a":1,"e":"Ans. is ''b'' i.e., 90 mg Recommended dose for thrombolysis with IV TPA is 0.9 mg/kg with the maximum dose being 90 mg. 10% should be given as a bolus over one minute, followed by remaining 90% as a continuous infusion over 60 minutes.","pyqMatches":[{"year":"2014","no":1416,"q":"Dose of rTPA in ischaemic stroke is","o":["60 mg","90 mg","100 mg","120 mg"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2816, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 377, '{"id":2816,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":377,"q":"Cerebral angiography was performed by","o":["Sir Walter Dandy","George Moore","Seldinger","Egas Moniz"],"a":3,"e":"Ans. is ''d'' i.e., Egas Moniz Egas Moniz first performed cerebral Angiography in 1927. n He received the Nobel Prize for developing for developing frontal leucotomy as a treatment for psychiatric diseases.","pyqMatches":[{"year":"2014","no":1417,"q":"Cerebral angiography was performed by","o":["Sir Walter Dandy","George Moore","Seldinger","Egas Moniz"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2817, 'Medicine', 'Endocrinology', 'Moderate', 'Internal_Medicine', 378, '{"id":2817,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":378,"q":"Mauriac''s syndrome is characterized by all except","o":["Diabetes","Obesity","Dwarfism","Cardiomegaly"],"a":3,"e":"Ans. is D i.e., Cardiomegaly Mauriac Syndrome Children with poorly controlled type I diabetes may develop Mauriac syndrome. It is characterized by : - Growth attenuation Delayed puberty Hepatomegaly Abnormal glycogen storage and steatosis Cushingoid features Rare in the modern era of insulin therapy but is occasionally reported.","pyqMatches":[{"year":"2014","no":1418,"q":"Mauriac''s syndrome is characterized by all except","o":["Diabetes","Obesity","Dwarfism","Cardiomegaly"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2818, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 379, '{"id":2818,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":379,"q":"Which of the following is associated with hyponatremia and low osmolality","o":["Hyperlipidemia","SIADH","CHF","CKD"],"a":2,"e":"Ans. is ''c'' i.e., CHF CHF is characterised by low perfusion of kidneys stimulating R.A.A.S and resultant absorption of salt and disproportionate amout of water would lead to hyponatremia with decreased osmolality. Isotonic hyponatremia is seen with hyperlipidemia and hvperproteinemia like in paraproteinemia. Intravenous immunoglobulin therapy also interferes with measurement of serum sodium. Major causes of hyponatremia Disorders in which ADH levels are elevated Effective circulating volume depletion True volume depletion Heart failure Cirrhosis Thiazide diuretics Syndrome of inappropriate ADH secretion, including reset osmostat pattern Hormonal changes Adrenal insufficiency Hypothyroidism Pregnancy Disorders in which ADH levels may be appropriately suppressed Advanced renal failure Primary polydipsia Beer drinker''s potomania Hyponatremia with normal or elevated plasma osmolality High plasma osmolality (effective osmols) Hyperglycemia Mannitol High plasma osmolality (ineffective osmols) Renal failure Alcohol intoxication with an elevated serum alcohlo concentration Normal plasma osmolality Psedohyponatremia (laboratory artifact) High triglycerides Chloestatic and obstructive jaundice (lipoprotein x) Multiple myeloma Absorption of irrigant solutions Glycine Sorbitol Mannitol","pyqMatches":[{"year":"2014","no":1419,"q":"Which of the following is associated with hyponatremia and low osmolality","o":["Hyperlipidemia","SIADH","CHF","CKD"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2819, 'Medicine', 'Hematology', 'Easy', 'Internal_Medicine', 380, '{"id":2819,"subject":"Medicine","chapter":"Hematology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":380,"q":"Deletion of one alpha globin gene on one chromosome is best defined as","o":["Hb Barts hydrops fetails","Alpha thalassemia major","Alpha thalassemia trait","Alpha thalassemia silent carrier"],"a":3,"e":"Ans. is ''d'' i.e., Alpha thalassemia silent carrier Condition Defect Genotype Clinical syndrome Silent Thalassemia Deletion of 1 alpha genes-a/aa Normal Thalessemia trait Deletion of 2 alpha genes -a/-a (homogygous) Microscopic hypochromic (heterogenous)Blood picture but No/Minimal Anemia HbH disease Deletion of 3 alpha genes--/-a Hemolytic anemia Hydrops fetalis (Hb Barts) Deletion of 4 alpha genes --/-- Fatal in utero or at birth","pyqMatches":[{"year":"2014","no":1479,"q":"Deletion of one alpha globin gene on one chromosome is best defined as","o":["Hb Barts hydrops fetails","Alpha thalassemia major","Alpha thalassemia trait","Alpha thalassemia silent carrier"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2820, 'Medicine', 'Hematology', 'Easy', 'Internal_Medicine', 381, '{"id":2820,"subject":"Medicine","chapter":"Hematology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":381,"q":"Which of the following is caused by deletion of all four alpha globin genes","o":["Beta thalassemia major","Hb Barts","HbH","a° thalassemia trait"],"a":1,"e":"Ans. is ''b'' i.e., Hb Barts Condition Defect Genotype Clinical syndrome Silent Thalassemia Deletion of 1 alpha genes-a/aa Normal Thalessemia trait Deletion of 2 alpha genes -a/-a (homogygous) Microscopic hypochromic (heterogenous)Blood picture but No/Minimal Anemia HbH disease Deletion of 3 alpha genes--/-a Hemolytic anemia Hydrops fetalis (Hb Barts) Deletion of 4 alpha genes --/-- Fatal in utero or at birth","pyqMatches":[{"year":"2014","no":1480,"q":"Which of the following is caused by deletion of all four alpha globin genes","o":["Beta thalassemia major","Hb Barts","HbH","a° thalassemia trait"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2821, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 382, '{"id":2821,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":382,"q":"In Beta thalassemia, the most common gene mutation is","o":["Intron 1 inversion","Intron 22","619 bp deletion","3.7 bp deletion"],"a":0,"e":"Ans. is ''a'' i.e., Intron 1 inversion Thalassemias are autosomal recessive disorder The most common mutation causing 13 thalassemias is intron/inversion Also know: Synthesis of alpha chain is controlled by 2 gene clusters on → Chromosome 16 Synthesis of beta chain is controlled by 2 gene clusters on → Chromosome 11 Thalassemia mutations in India Multations Frequency IVS1-5 (G —>C) 48% 619 bp defection 18% IVS-1 (G T) 9% FR41/42(TCTT) 9% FR8/9 (+G) 5% Codonl5 (G --> A) 6% Others 100%","pyqMatches":[{"year":"2014","no":1481,"q":"In Beta thalassemia, the most common gene mutation is","o":["Intron 1 inversion","Intron 22","619 bp deletion","3.7 bp deletion"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2822, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 383, '{"id":2822,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":383,"q":"Bence jones proteinuria is best detected by","o":["Dipstick method","Sulfosalicylic acid","Heat test","Electrophoresis"],"a":3,"e":"Ans. is `d'' i.e., Electrophoresis Bence Jones proteins are seen in multiple myeloma. Urinary protein electrophoresis will exhibit a discrete protein peak. In myeloma plasma cells produce immuno-globulin of a single heavy and light chain, a monoclonal protein commonly referred to as a paraprotein. Heat test is false negative in 50% of patients with light chain myeloma. Dipstick detects albumin and not paraproteins.","pyqMatches":[{"year":"2014","no":1420,"q":"Bence jones proteinuria is best detected by","o":["Dipstick method","Sulfosalicylic acid","Heat test","Electrophoresis"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2823, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 384, '{"id":2823,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":384,"q":"HIV RNA by PCR can detect as low as","o":["30 copies viral RNA/ml of blood","40 copies viral RNA/ml of blood","50 copies of viral RNA/ml of blood","60 copies of viral RNA/ml of blood"],"a":1,"e":"Ans. is ''b'' i.e., 40 copies viral RNA/ml of blood This assay generates data in the form of number of copies of HIV RNA per milli litre of serum or plasma and can reliably detect as few as 40 copies of HIV RNA per mili litre of plasma. Research based assay can detect down to one copy/ml.","pyqMatches":[{"year":"2014","no":1422,"q":"HIV RNA by PCR can detect as low as","o":["30 copies viral RNA/ml of blood","40 copies viral RNA/ml of blood","50 copies of viral RNA/ml of blood","60 copies of viral RNA/ml of blood"],"a":1,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":1197,"q":"HIV RNA by PCR can detect as low as","o":["30 copies viral RNA/ml of blood","40 copies viral RNA/ml of blood","50 copies of viral RNA/ml of blood","60 copies of viral RNA/ml of blood"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2824, 'Medicine', 'Hematology', 'Hard', 'Internal_Medicine', 385, '{"id":2824,"subject":"Medicine","chapter":"Hematology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":385,"q":"Most common cause of pleural effusion in AIDS patients","o":["Kaposi sarcoma","TB","Pneumocystis Jiroveci","Mycoplasma"],"a":0,"e":"Ans. is ''a'' i.e., Kaposi sarcoma Ophthalmological diseases The most common abnormal findings on fundoscopic examination are cotton wool spots. CMV retinitis is the most severe ocular complication and occurs when CD4 T-cells count is less than 50/ml. It typical presents as perivascular hemorrhage and exudae with Cottage-Cheese appearance. Acute retinal necrosis syndrome, also called progressive outer retinal necrosis (PORN) is caused by HSV and VZV Other manifestations are chorioretinitis by toxoplasma and P carinii, kaposi sarcoma of eyelid, and lymphoma.","pyqMatches":[{"year":"2013","no":1244,"q":"Most common cause of pleural effusion in AIDS patients","o":["Kaposi sarcoma","TB","Pneumocystis Jiroveci","Mycoplasma"],"a":0,"source":"NEET_2013_Paper.pdf"},{"year":"2015","no":1086,"q":"Most common cause of pleural effusion in AIDS patients","o":["Kaposi sarcoma","TB","Pneumocystis Jiroveci","Mycoplasma"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2013","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2825, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 386, '{"id":2825,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":386,"q":"Biomarker not involved in acute kidney injury is","o":["NGAL","KIM 1","Micro RNA 122","Cystatin C"],"a":2,"e":"Ans. is ''c'' i.e., Micro RNA 122 Biomarkers of acute kidney injury Alanine aminopeptidase (AAP) Alkaline phosphatase (AP) a-glutathione-S-transferase (a-GST) y-glutamyl transpeptidase (yGT) N-acetyl-13-glucosaminidase (NAG) pfmicroglobulin a imicroglobulin Retinol-binding protein (RBP) Cystatin C Microalbumin Kidney injury molecule-1 (KIM-1) Clusterin Neutrophil gelatinase associated lipocalin (NGAL) Interleukin-18 (IL-18) Cysteine-rich protein (CYR-61) Osteopontin (OPN) Fatty acid binding protein (FABP) Sodium/hydrogen exchanger isoform (NHE3) Exosomal fetuin-A","pyqMatches":[{"year":"2014","no":1423,"q":"Biomarker not involved in acute kidney injury is","o":["NGAL","KIM 1","Micro RNA 122","Cystatin C"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2826, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 387, '{"id":2826,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":387,"q":"Most common site of cerebral infarction is in the territory of","o":["Anterior cerebral artery","Middle cerebral artery","Posterior cerebral artery","Posterior inferior cerebellar artery"],"a":1,"e":"Ans. is ''b'' i.e., Middle cerebral artery Hemiplegia most commonly occurs due to lesion of middle cerebral artery","pyqMatches":[{"year":"2014","no":1424,"q":"Most common site of cerebral infarction is in the territory of","o":["Anterior cerebral artery","Middle cerebral artery","Posterior cerebral artery","Posterior inferior cerebellar artery"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2827, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 388, '{"id":2827,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":388,"q":"Hemiplegia is most often caused by thrombosis of ?","o":["Anteiror cerebral artery","Middle cerebral artery","Posterior cerebral artery","Basiliar artery"],"a":1,"e":"Ans. is ''b'' i.e., Middle cerebral artery Middle Cerebral Artery Deep branches of the middle cerebral artery on the lenticulostriate branches supply the internal capsule (posterior limb). Motor tracts are densely packed in this region and hence occlusion of deep branches or lenticulostrials branches leads to Densse Hemiplegia/Pure motor Hemiplegia. Anterior choroidal artery supplies the posterior limb of internal capsule (and not anterior limb of internal capsule). Anterior chorodial artery arises from the internal carotid artery and supplies the posterior limb of internal capsule. The complete syndrome of anterior choroidal artery occlusion consists of contralateral hemiplegia hemianesthesia (hypoesthesia) and homonymous hemianopia Posterior Cerebral Artery The posterior cerebral artery supplies the midbrain, thalamus lateral geniculate bodies, posterior of chroid plexus, occipital lobes, inferior and medial aspect of the temporal lobe and posterior inferior areas of the parietal lobe Occlusion of the Posterior Cerebral Artery usually results in two common clinical syndrome depending on the areas involved P1 Syndrome P2 Syndrome Occlusion of the proximal segment ofPCA from its origin to its union withthe posterior communicating artery Occlusion of the distalsegment of PCA distal to the junction of PCA with theposterior communicating artery P1 syndrome present primarily withthe following signs P2 syndrome presents primarily withthe following signs Midbrain signs Temporal lobe signs Thalamic signs Subthalamic signs Occipital lobe signs","pyqMatches":[{"year":"2014","no":1425,"q":"Hemiplegia is most often caused by thrombosis of ?","o":["Anteiror cerebral artery","Middle cerebral artery","Posterior cerebral artery","Basiliar artery"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2828, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 389, '{"id":2828,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":389,"q":"Indication for prophylaxis in pneumocystis carini pneumonia include","o":["CD4 count < 200","Tuberculosis","Viral load > 25,000 copies/ml","Oral candidiasis"],"a":0,"e":"Ans. is ''A'' i.e., CD4 count < 200 PROPHYLAXIS OF PNEUMOCYSTIC CARINI PNEUMONIA Primary prophylaxis is indicated for Patients with CD4- cell counts of< 200/4 History of oropharyngeal candidiasis Secondary prophylaxis is indicated for Both HIV infected and non-HIV infected patients. Who has recovered from pneumocystosis Primary and secondary prophylaxis may be discontinued in HIV infected persons once. CD4+ counts have risen to > 200/p1 and remained at that level for 3 months. Also know First choice agent for prophylaxis Trimethoprim, sulphamethoxazole. Other agents used in prophylaxis. Dapsone, pentamidine.","pyqMatches":[{"year":"2014","no":1427,"q":"Indication for prophylaxis in pneumocystis carini pneumonia include","o":["CD4 count < 200","Tuberculosis","Viral load > 25,000 copies/ml","Oral candidiasis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2829, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 390, '{"id":2829,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":390,"q":"Canon ''a'' wave is seen in","o":["Junctional rhythm","Atrial fibrillation","Atrial flutter","Ventricular fibrillation"],"a":0,"e":"Ans. is ''a'' i.e., Junctional rhythm Regularly –> During junctional rhythm • Irregularly A- V dissociation with ventricular tachycardia complete heart block.","pyqMatches":[{"year":"2014","no":1459,"q":"Canon ''a'' wave is seen in","o":["Junctional rhythm","Atrial fibrillation","Atrial flutter","Ventricular fibrillation"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2830, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 391, '{"id":2830,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":391,"q":"Most common cause of unilateral pedal edema","o":["Pregnancy","Lymphedema","Venous insufficiency","Milroy disease"],"a":2,"e":"Ans. is ''c'' i.e., Venous insufficiency The most likely cause of leg edema in patients over age 50 is venous insufficiency. Venous insufficiency affects up to 30% of the population, whereas heart failure affects only approximately 1%. The most important cause of unilateral pedal edema is venous insufficiency. Milroys disease : The defect in Milroy''s disease is present from birth and symptoms are usually first experienced in childhood. The most common problem is one-sided leg swelling, unilateral edema, which is progressive and can affect both legs. Impaired intestinal lymphatics can cause steatorrhea due to impaired transport of chylomicrons","pyqMatches":[{"year":"2014","no":1429,"q":"Most common cause of unilateral pedal edema","o":["Pregnancy","Lymphedema","Venous insufficiency","Milroy disease"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2831, 'Medicine', 'Infectious Diseases', 'Moderate', 'Internal_Medicine', 392, '{"id":2831,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":392,"q":"Grisel syndrome all are true except","o":["Post-adenoidectomy","Conservation treatment","Inflammation of cervical spine ligaments","No need for neurosurgeon"],"a":3,"e":"Ans. d. No need for neurosurgeon Grisel Syndrome: Non-traumatic atlanto-axial subluxation may occur secondary to any inflammatory process in the upper neck It is described following tonsillectomy and adenoidectomy Conservation treatment: Cervical immobilization, Analgesia and Antibiotics to reduce the risk of neurological deficit Grisel Syndrome Non-traumatic atlanto-axial subluxation may occur secondary to any inflammatory process in the upper neckQ Due infection in the peri-odontoid vascular plexusQ that drains the region, bringing about paraspinal ligament laxity Described following tonsillectomy and adenoidectomyQ It maybe associated with overuse of diathermy either for removal of adenoid or following curettageQ, when used for hemostasis. Children with Down syndrome° have atlanto-axial instability Treatment: Cervical immobilizationQ AnalgesiaQ AntibioticsQ to reduce the risk of neurological deficit","pyqMatches":[{"year":"2013","no":1488,"q":"Grisel syndrome all are true except","o":["Post-adenoidectomy","Conservation treatment","Inflammation of cervical spine ligaments","No need for neurosurgeon"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2832, 'Medicine', 'Dermatology & Allergy', 'Hard', 'Internal_Medicine', 393, '{"id":2832,"subject":"Medicine","chapter":"Dermatology & Allergy","difficulty":"Hard","source":"Internal_Medicine","sourceNo":393,"q":"A female patient of 26 years, presents with oral ulcers, photosensitivity and skin malar rash in face sparing the nasolabial folds of both side.","o":["Sturge weber syndrome","SLE","Dermatitis","Psoriasis"],"a":1,"e":"Answer- B (SLE) Common symptoms include painful and swollen joints, fever, chest pain, hair loss, mouth ulcers, swollen lymph nodes, feeling tired, and a red rash which is most commonly on the face.","pyqMatches":[{"year":"2019","no":167,"q":"A female patient of 26 years, presents with oral ulcers, photosensitivity and skin malar rash in face sparing the nasolabial folds of both side.","o":["Sturge weber syndrome","SLE","Dermatitis","Psoriasis"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2833, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 394, '{"id":2833,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":394,"q":"Most characteristic cardiovascular defect seen in Rubella-","o":["Pulmonary artery stenosis","Coarctation of aorta","Ankylosis spondylitis","Rheumatic fever"],"a":0,"e":"Answer. A. Pulmonary artery stenosis The classic triad for congenital rubella syndrome is: Sensorineural deafness (58% of patients) Eye abnormalities? especially retinopathy, cataract, and microphthalmia Congenital heart disease? especially pulmonary artery stenosis and patent ductus arteriosus.","pyqMatches":[{"year":"2019","no":168,"q":"Most characteristic cardiovascular defect seen in Rubella","o":["Pulmonary artery stenosis","Coarctation of aorta","Ankylosis spondylitis","Rheumatic fever"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2834, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 395, '{"id":2834,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":395,"q":"Osborn J waves is seen in-","o":["Hypothermia","Hyperkalemia","Hypocalemia","Hypokalemia"],"a":0,"e":"Answer. A. Hypothermia Cause people suffering from hypothermia with a temperature of less than 32°C (90°F).","pyqMatches":[{"year":"2019","no":169,"q":"Osborn J waves is seen in","o":["Hypothermia","Hyperkalemia","Hypocalemia","Hypokalemia"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2835, 'Medicine', 'Infectious Diseases', 'Moderate', 'Internal_Medicine', 396, '{"id":2835,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":396,"q":"Which is not related to HIV","o":["Primary CNS lymphoma","Tertiary syphilis","Oesophageal candidasis","None"],"a":1,"e":"Answer. B. Tertiary syphilis Tertiary Syphilis has no relation to HIV status and primarily based on the duration of the infection and complications of Syphilis.","pyqMatches":[{"year":"2019","no":171,"q":"Which is not related to HIV","o":["Primary CNS lymphoma","Tertiary syphilis","Oesophageal candidasis","None"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2836, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 397, '{"id":2836,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":397,"q":"Essential major blood culture criteria for infective endocarditis.","o":["Single positive culture of hacek","Single positive culture of coxiella","Single positive culture of cornybacterium","Both a & b"],"a":0,"e":"Answer. A. Single positive culture of HACEK","pyqMatches":[{"year":"2019","no":172,"q":"Essential major blood culture criteria for infective endocarditis.","o":["Single positive culture of hacek","Single positive culture of coxiella","Single positive culture of cornybacterium","Both a & b"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2837, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 398, '{"id":2837,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":398,"q":"Respiratory centres are stimulated by","o":["Oxygen","Lactic acid","Carbon dioxide","Calcium"],"a":2,"e":"Answer. C. Carbon dioxide The body’s respiratory center in the medulla is normally stimulated by an increased concentration of carbon dioxide, and to a lesser extent, by decreased levels of oxygen in arterial blood. Stimulation of the respiratory center causes an increase in the rate and depth of breathing, thus blowing off excess carbon dioxide and reducing blood acidity.","pyqMatches":[{"year":"2019","no":173,"q":"Respiratory centres are stimulated by","o":["Oxygen","Lactic acid","Carbon dioxide","Calcium"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2838, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 399, '{"id":2838,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":399,"q":"Alcoholic shows which type of cardiomyopathy-","o":["Hyper cardiomyopathy","Dilated cardiomyopathy","Pericarditis","Myocarditis"],"a":1,"e":"Answer. B. Dilated cardiomyopathy Alcoholic cardiomyopathy is a disease in which the chronic long- term abuse of alcohol (i.e., ethanol) leads to heart failure.Alcoholic cardiomyopathy is a type of dilated cardiomyopathy.","pyqMatches":[{"year":"2019","no":170,"q":"Alcoholic shows which type of cardiomyopathy","o":["Hyper cardiomyopathy","Dilated cardiomyopathy","Pericarditis","Myocarditis"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2839, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 400, '{"id":2839,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":400,"q":"Which murmur increases on standing?","o":["HOCM","MR","MS","VSD"],"a":0,"e":"Answer. A. HOCM Murmur will get softer with Valsalva or standing from squatting because less blood is being ejected through the aortic valve. Rapid squatting from a standing position forces increased venous return and would have the opposite effect of Valsalva or rapid standing.","pyqMatches":[{"year":"2019","no":174,"q":"Which murmur increases on standing?","o":["HOCM","MR","MS","VSD"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2840, 'Medicine', 'Cardiology', 'Hard', 'Internal_Medicine', 401, '{"id":2840,"subject":"Medicine","chapter":"Cardiology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":401,"q":"Which wall of heart enlargement can be seen on barium swallow in patient with mitral stenosis-","o":["Left atrium","Right atrium","Left ventricle","Right ventricle"],"a":3,"e":"Answer. D. Right ventricle Mitral stenosis is associated with right ventricular hypertrophy. Left ventricular diastolic pressure is normal in isolated MS. Mitral stenosis : Features left atrial pressure is increased pulmonary arterial pressure is increased Increased right ventricular afterload impedes the emptying of this chamber and Right ventricular end diastolic pressure and volume increase. Right ventricular hypertrophy occurs.","pyqMatches":[{"year":"2019","no":158,"q":"Which wall of heart enlargement can be seen on barium swallow in patient with mitral stenosis","o":["Left atrium","Right atrium","Left ventricle","Right ventricle"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2841, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 402, '{"id":2841,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":402,"q":"Which of the following statements is true about the bundle of kent?","o":["Abnormal pathway between two atria","It is muscular or nodal pathway between the atria and ventricle in WPW syndrome","It is slower than the AV nodal pathway","None"],"a":1,"e":"Answer. B. It is muscular or nodal pathway between the atria and ventricle in WPW syndrome The Wolff-Parkinson-White syndrome is defined by the combination of an atrioventricular pre-excitation (bundle of Kent) and paroxysmal supraventricular tachycardias. The diagnosis of atrioventricular pre- excitation in sinus rhythm is established on the association between a short PR interval, a wide QRS, a delta wave, a normal terminal QRS portion and frequent repolarization disorders.","pyqMatches":[{"year":"2019","no":159,"q":"Which of the following statements is true about the bundle of kent?","o":["Abnormal pathway between two atria","It is muscular or nodal pathway between the atria and ventricle in WPW syndrome","It is slower than the AV nodal pathway","None"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2842, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 403, '{"id":2842,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":403,"q":"Deep venous thrombosis which is incorrect –","o":["Clinical assessment highly reliable","Mostly bilateral","Most common clinically presents as pain and tenderness in calf","Some cases may directly present as pulmonary thromboembolism"],"a":1,"e":"Answer. B. Mostly bilateral Wells score or criteria: (possible score -2 to 9) Active cancer (treatment within last 6 months or palliative): +1 point Calf swelling = 3 cm compared to asymptomatic calf (measured 10 cm below tibial tuberosity): +1 point Swollen unilateral superficial veins (non-varicose, in symptomatic leg): +1 point Unilateral pitting edema (in symptomatic leg): +1 point Previous documented DVT: +1 point Swelling of entire leg: +1 point Localized tenderness along the deep venous system: +1 point Paralysis, paresis, or recent cast immobilization of lower extremities: +1 point Recently bedridden = 3 days, or major surgery requiring regional or general anesthetic in the past 12 weeks: +1 point Alternative diagnosis at least as likely: -2 points","pyqMatches":[{"year":"2019","no":160,"q":"Deep venous thrombosis which is incorrect –","o":["Clinical assessment highly reliable","Mostly bilateral","Most common clinically presents as pain and tenderness in calf","Some cases may directly present as pulmonary thromboembolism"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2843, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 404, '{"id":2843,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":404,"q":"Punched out ulcer in esophagus is seen in","o":["herpes","cmv","Oesophagitis","candida"],"a":2,"e":"Answer. C. Oesophagitis It is likely to present with a single, large shallow linear ulcer as opposed to the multiple vesicular/ “punched-out” ulcers seen in herpes esophagitis.","pyqMatches":[{"year":"2019","no":161,"q":"Punched out ulcer in esophagus is seen in","o":["herpes","cmv","Oesophagitis","candida"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2844, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 405, '{"id":2844,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":405,"q":"Type of sensation lost on same side of Brown Sequard syndrome-","o":["Pain","Touch","Proprioception","Temperature"],"a":2,"e":"Answer. C. Proprioception Damage to one half of the spinal cord, resulting in paralysis and loss of proprioception on the same (or ipsilateral) side as the injury or lesion, and loss of pain and temperature sensation on the opposite (or contralateral) side as the lesion.","pyqMatches":[{"year":"2019","no":162,"q":"Type of sensation lost on same side of Brown Sequard syndrome","o":["Pain","Touch","Proprioception","Temperature"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2845, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 406, '{"id":2845,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":406,"q":"Achondroplasia shows which type inheritance-","o":["XLR","XLD","Autosomal recessive","Autosomal dominant"],"a":3,"e":"Answer. D. Autosomal dominant Achondroplasia is inherited in an autosomal dominant pattern, which means one copy of the altered gene in each cell is sufficient to cause the disorder.","pyqMatches":[{"year":"2019","no":163,"q":"Achondroplasia shows which type inheritance","o":["XLR","XLD","Autosomal recessive","Autosomal dominant"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2846, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 407, '{"id":2846,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":407,"q":"MELD score includes","o":["Serum creatinine","Transaminase","Albumin","Alkaline phosphatase"],"a":0,"e":"Answer. A. Serum creatinine The Model for End-stage Liver Disease (MELD) is a prospectively developed and validated chronic liver disease severity scoring system that uses a patient’s laboratory values for – Li Serum bilirubin Serum creatinine The international normalized ratio (INR) for prothrombin time to predict three month survival. Patients with cirrhosis, and increasing MELD score is associated with increasing severity of hepatic dysfunction and increased three- month mortality risk. Given its accuracy in predicting short-term survival among patients with cirrhosis, MELD was adopted by the United network for organ sharing (UNOS) in 2002 for prioritization or patients awaiting liver transplantation in the United states.","pyqMatches":[{"year":"2014","no":1274,"q":"MELD score includes","o":["Serum creatinine","Transaminase","Albumin","Alkaline phosphatase"],"a":0,"source":"NEET_2014_Paper.pdf"},{"year":"2019","no":164,"q":"MELD score includes","o":["Serum creatinine","Transaminase","Albumin","Alkaline phosphatase"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2014","2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2847, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 408, '{"id":2847,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":408,"q":"Infarcts involving which portion of the myocardium cause aneurysm as a post- MI complication-","o":["Subendocardial","Anterior transmural","Posterior transmural","Inferior wall"],"a":3,"e":"Answer. D. Inferior wall Left ventricular aneurysm formation: Left ventricular apical aneurysm formation usually occurs following antero-apical myocardial infarction, after LAD occlusion. This weakening of the apical wall results in an outpouching or “dyskinesis” of the apex of the heart during systole.","pyqMatches":[{"year":"2016","no":419,"q":"Infarcts involving which portion of the myocardium cause aneurysm as a post- MI complication","o":["Subendocardial","Anterior transmural","Posterior transmural","Inferior wall"],"a":3,"source":"NEET_2016_Paper.pdf"},{"year":"2019","no":165,"q":"Infarcts involving which portion of the myocardium cause aneurysm as a post- MI complication","o":["Subendocardial","Anterior transmural","Posterior transmural","Inferior wall"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2016","2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2848, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 409, '{"id":2848,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":409,"q":"Risk factors for alzheimer’s disease include-","o":["Klinefelter syndrome","Low BP","Down’s syndrome","None"],"a":2,"e":"Answer. C. Down’s syndrome People with Down syndrome are born with an extra copy of chromosome 21, which carries the APP gene. This gene produces a specific protein called amyloid precursor protein (APP) with age these get accumulated in the brain cell and affects the functioning of the brain leading to alzheimer’s dementia.","pyqMatches":[{"year":"2019","no":166,"q":"Risk factors for alzheimer’s disease include","o":["Klinefelter syndrome","Low BP","Down’s syndrome","None"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2849, 'Medicine', 'Cardiology', 'Hard', 'Internal_Medicine', 410, '{"id":2849,"subject":"Medicine","chapter":"Cardiology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":410,"q":"A patient with native aortic valve disease came with right hemiparesis. What will you do to prevent further stroke?","o":["Antiplatelet only","Anticoagulant only","Both antiplatelet and anticoagulant","One dose of low molecular weight heparin sub-cutaneously followed by dual antiplatelet therapy"],"a":0,"e":"Answer- A. Antiplatelet only * Aspirin is the only antiplatelet agent that has been proven elfectivefor the acute treatment of ischemic stroke; use of aspirin within 48 hoars of stroke onset reduced both stroke recurrence risk and mortality minimally. * Asprin is the only antiplatelet agent that has been proven effecfive for the acute treatment of ischemic stroke; there are several antiplatelet agents proven for the secondary prevention of stroke. * Two layer trials, the International Stroke Trial (IST) and the Chinese Acute Stroke Trial (CAST),found that the use ofaspirin within 48 hours ofstroke onset reduced both stroke recurrence risk and mortality minimally.","pyqMatches":[{"year":"2012","no":50,"q":"A patient with native aortic valve disease came with right hemiparesis. What will you do to prevent further stroke?","o":["Antiplatelet only","Anticoagulant only","Both antiplatelet and anticoagulant","One dose of low molecular weight heparin sub-cutaneously followed by dual antiplatelet therapy"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2850, 'Medicine', 'Hematology', 'Easy', 'Internal_Medicine', 411, '{"id":2850,"subject":"Medicine","chapter":"Hematology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":411,"q":"The most common subtype of Non- Hodgkin''s lymphoma in India is:","o":["Diffuse small cell lymphocytic lymphoma","Diffuse large B cell lymphoma","Follicular lymphoma","Burkitt''s lymphoma"],"a":1,"e":"Answer- B. Diffuse large B cell lymphoma The most common subtype of Non-Hodgkin''s lymphomt in India is dilfuse large B cell lymphoma. Diffuse large B-cell lymphoma: MC subtype (34%) Follicular centre-cell lymphomas: 12.6% . B-celf small lymphocytic lymphoma:.5.7% Mantle-cell lymphoma: 3.4% Marginal zone B-cell lymphomas (including MALT lymphomas): 8.2%","pyqMatches":[{"year":"2013","no":709,"q":"The most common subtype of Non- Hodgkin''s lymphoma in India is:","o":["Diffuse small cell lymphocytic lymphoma","Diffuse large B cell lymphoma","Follicular lymphoma","Burkitt''s lymphoma"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2851, 'Medicine', 'Cardiology', 'Hard', 'Internal_Medicine', 412, '{"id":2851,"subject":"Medicine","chapter":"Cardiology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":412,"q":"Which of the following drug can be given in patients of primary pulmonary hypertension?","o":["Icatibant","Bosentan","Labetolol","Sodium nitroprusside"],"a":1,"e":"Answer- B. Bosentan Treatment for Primary pulmonary hypertension: CALCIUM CHANNEL BLOCKERS: Patients who respond to short-acting vasodilators at the time of cardiac catheterization should be treated with calcium channel blockers. The endothelin receptor antagonists bosentan and ambrisentan are approved treatments of PAH Bosentan is contraindicated in patients who are on cyclosporine or glyburide concurrently.","pyqMatches":[{"year":"2020","no":172,"q":"Which of the following drug can be given in patients of primary pulmonary hypertension?","o":["Icatibant","Bosentan","Labetolol","Sodium nitroprusside"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2852, 'Medicine', 'Cardiology', 'Hard', 'Internal_Medicine', 413, '{"id":2852,"subject":"Medicine","chapter":"Cardiology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":413,"q":"An 86 years old lady presented with severe constipation. She was a known hypertensive on medications for 10 years. In clinic, her BP was 157/98 mm Hg with a heart rate of 58/min. On taking here BP in the supine position it was found to be 90/60 mm Hg. She had the recent history of depression. She is taking atenolol, thiazide, imipramine, haloperidol and docusate. What will be the next best step in the management?","o":["Change atenolol and thiazide to calcium channel blocker and ACE inhibitor and add bisacodyl for constipation","Change imipramine and haloperidol to fluoxetine and risperidone and add bisacodyl for constipation","Only add bisacodyl for constipation and continue rest of the medications","Discontinue all her medications and start her on steroids"],"a":1,"e":"Ans: B. Change imipramine and haloperidol to fluoxetine and risperidone and add bisacodyl for constipation (Ref Harrison 19/e p1623-1624, 18/e p3531: Goodman Gilman 12/e p410. 1333) Effects of Imipramine: Postural hypotension - Due to alpha blockade by Imipramine & thiazides interaction. Anti-cholinergic side-effect. Hence, Imipramine (TCA) must be discontinued. Should be started on SSRI, fluoxetin & laxative (existing constipation). Effect of haloperidol: Anti-cholinergic side effects. Should start on atypical antipsychotic Risperidone.","pyqMatches":[{"year":"2012","no":564,"q":"An 86 years old lady presented with severe constipation. She was a known hypertensive on medications for 10 years. In clinic, her BP was 157/98 mm Hg with a heart rate of 58/min. On taking here BP in the supine position it was found to be 90/60 mm Hg. She had the recent history of depression. She is taking atenolol, thiazide, imipramine, haloperidol and docusate. What will be the next best step in the management?","o":["Change atenolol and thiazide to calcium channel blocker and ACE inhibitor and add bisacodyl for constipation","Change imipramine and haloperidol to fluoxetine and risperidone and add bisacodyl for constipation","Only add bisacodyl for constipation and continue rest of the medications","Discontinue all her medications and start her on steroids"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2853, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 414, '{"id":2853,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":414,"q":"pANCA positive vasculitis is","o":["Wegener''s granulomatosis","Churg - Strauss syndrome","Polyarteritis nodosa","All of the above"],"a":1,"e":"Answer- b. Churg - Strauss syndrome PANCA Typically found in: Microscopicpolyangiitis Churg-Strausssyndrome Idiopathiccrescenticglomerulonephritis Goodpasteur''ssyndrome. pANCA''s are also associated with certain non-vasculitic entities such as certain rheumatic and nonrheumatic autoimmune diseases, Inflammatory bowel diseases, certain drugs. Infections such as endocarditis and bacterial airway infection in patients with cystic fibrosis","pyqMatches":[{"year":"2014","no":452,"q":"pANCA positive vasculitis is","o":["Wegener''s granulomatosis","Churg - Strauss syndrome","Polyarteritis nodosa","All of the above"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2854, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 415, '{"id":2854,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":415,"q":"Levine sign is seen in","o":["Stable angina pectoris","Acute bronchial asthma","Hemolytic anemia","Gastroesophageal reflux disease"],"a":0,"e":"Answer- A. Stable angina pectoris Stable Angina Pectoris: This episodic clinical syndrome is due to transient myocardial ischemia When the patient is asked to localize the sensation, he or she typically places a hand over the sternum, sometimes with a clenched fist, to indicate a squeezing, central, substernal discomfort (Levine''s sign).","pyqMatches":[{"year":"2016","no":1054,"q":"Levine sign is seen in","o":["Stable angina pectoris","Acute bronchial asthma","Hemolytic anemia","Gastroesophageal reflux disease"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2855, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 416, '{"id":2855,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":416,"q":"Which of the following complications is not seen in mitral valve prolapse?","o":["Stroke","Infective endocarditis","Mitral stenosis","Ventricular arrhythmia"],"a":2,"e":"Answer- C. Mitral stenosis Surface marking of the mitral valve is Behind sternal end of left 4th costal cartilage. Infective endocarditis Mitral insuficiency (mitral regurgitation) Stroke or other systemic infarct resulting from embolism of leaflet thrombi Arrhythmias","pyqMatches":[{"year":"2012","no":52,"q":"Which of the following complications is not seen in mitral valve prolapse?","o":["Stroke","Infective endocarditis","Mitral stenosis","Ventricular arrhythmia"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2856, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 417, '{"id":2856,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":417,"q":"HbA1c control for how much time","o":["2 -3 weeks","3 - 6 weeks","6 - 8 weeks","14 - 18 weeks"],"a":2,"e":"Answer- C. 6 - 8 weeks The half-life of an erythrocyte is typically 60 days, the level of glycated hemoglobin (HbA1c) reflects the mean blood glucose concentration over the preceding 6-8 weeks.","pyqMatches":[{"year":"2016","no":1136,"q":"HbA1c control for how much time","o":["2 -3 weeks","3 - 6 weeks","6 - 8 weeks","14 - 18 weeks"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2857, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 418, '{"id":2857,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":418,"q":"All are seen in MEN IIA syndrome except","o":["Medullary carcinoma of thyroid is seen in 100% of the patients","40 - 30% patients have phaeochromocytoms","Caused by loss of function mutation in IIRT protooncogene","Primary hyperparathyroidism is the most variable feature of MEN II A syndrome"],"a":2,"e":"Answer- C. Caused by loss of function mutation in IIRT protooncogene MEN-2A or Sipple syndrome, is characterized by pheochromocytoma, medullary carcinoma of the thyroid, and parathyroid hyperplasia. Parathyroid hyperplasia and evidence of hypercalcemia or renal stones. MEN-2A is clinically and genetically distinct from MEN-I and is caused by germline gain-of-function mutations in the RET proto-oncogene on chromosome l0qll.2. 40% to 50% have pheochromocytomas. Primary hyperparathyroidism is the most variable feature of MEN 2A syndrome.","pyqMatches":[{"year":"2016","no":1138,"q":"All are seen in MEN IIA syndrome except","o":["Medullary carcinoma of thyroid is seen in 100% of the patients","40 - 30% patients have phaeochromocytoms","Caused by loss of function mutation in IIRT protooncogene","Primary hyperparathyroidism is the most variable feature of MEN II A syndrome"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2858, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 419, '{"id":2858,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":419,"q":"Hypoxic pulmonary vasoconstriction due to -","o":["Irreversible pulmonary vasocontriction hypoxia","Reversible pulmonary vasoconstriction due to hypoxia","Direct blood to poorly ventilated areas","Occurs hours after pulmonary vasoconstriction"],"a":1,"e":"Answer- b. Reversible pulmonary vasoconstriction due to hypoxia Hypoxic pulmonary vasoconstriction (HPV) is an adaptive vasomotor response to alveolar hypoxia which redistributes blood to optimally ventilatid lung segments by an active process of ''vasoconstriction, particularly involving the small muscular resistance pulmonary arteries (PA).","pyqMatches":[{"year":"2013","no":123,"q":"Hypoxic pulmonary vasoconstriction due to","o":["Irreversible pulmonary vasocontriction hypoxia","Reversible pulmonary vasoconstriction due to hypoxia","Direct blood to poorly ventilated areas","Occurs hours after pulmonary vasoconstriction"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2859, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 420, '{"id":2859,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":420,"q":"Polyuria with low fixed specific gravity urine is seen in ?","o":["Diabetes mellitus","Diabetes insipidus","Chronic glomerulonephritis","Potomania"],"a":2,"e":"Answer- C. Chronic glomerulonephritis Polyuria with fixed low specific gravity is a feature of chronic glomerulonephritis. Specific gravity measures the kidney''s ability to concentrate or dilute urine about plasma. Because urine is a solution of minerals, salts, and compounds dissolved in water, the specific gravity is greater than 1.000. The more concentrated the urine, the higher the urine specific gravity. An adult''s kidneys have a remarkable ability to concentrate or dilute urine. In infants, the range for specific gravity is less because immature kidneys are not able to concentrate urine as effectively as mature kidneys. A low specific gravity occurs in three situations. In diabetes insipidus, there is an absence or decrease of anti-diuretic hormone. Without anti-diuretic hormone, the kidneys produce an excessive amount of urine, often up to 15 to 20 liters per day with low specific gravity. Glomerulonephritis and pyelonephritis cause decreased urine volume and low specific gravity. In these diseases, damage to the kidney''s tubules affects the ability of the kidney to re-absorb water. As a result, the urine remains to dilute. The third reason for low specific gravity is renal failure, which results in a fixed specific gravity between 1.007 and 1.010. In renal failure, the remaining functional nephrons undergo compensatory structural and hypertrophic changes. These compensatory changes result in urine that is almost isotonic with plasma. Therefore, a patient experiencing renal failure will present with specimens measuring the same, or fixed, specific gravity regardless of water intake.","pyqMatches":[{"year":"2015","no":1113,"q":"Polyuria with low fixed specific gravity urine is seen in ?","o":["Diabetes mellitus","Diabetes insipidus","Chronic glomerulonephritis","Potomania"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2860, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 421, '{"id":2860,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":421,"q":"DOC for treatment of SSPE -","o":["Abacavir","Inosine pranobex","Glatiramer","Interferon"],"a":1,"e":"Answer- B. Inosine pranobex Inosine pranobex is used as an immune-modulator for the management of patients with- Immune-depression sufereing from viral infections as SSPE recurrent herpes simplex genital warts.","pyqMatches":[{"year":"2015","no":1170,"q":"DOC for treatment of SSPE","o":["Abacavir","Inosine pranobex","Glatiramer","Interferon"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2861, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 422, '{"id":2861,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":422,"q":"Rademecker complex in EEG is seen in -","o":["SSPE","vCJD","cCJD","Kuru"],"a":0,"e":"Answer- A. SSPE Characteristic periodic activity (Rademecker complex) is seen on EEG showing widespread cortical dysfunction in SSPE. It is characterised by high voltage spike occuning at higlr lrequency of 0.5- 1.5 seconds.","pyqMatches":[{"year":"2015","no":1158,"q":"Rademecker complex in EEG is seen in","o":["SSPE","vCJD","cCJD","Kuru"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2862, 'Medicine', 'Endocrinology', 'Easy', 'Internal_Medicine', 423, '{"id":2862,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":423,"q":"Charcot''s joint in diabetes affects commonly -","o":["Shoulder joint","Knee joint","Hip joint","Tarsal joint"],"a":3,"e":"Answer- D. Tarsal joint Tabes dorsalis → Knees, hip & ankles Loose body in joint A loose body is a free-floating piece of bone, cartilage or foreign object in a joint. The knee is the most common joint where one would find a loose body. Causes of loose bodies include :- i) Osteoarthritis iii) Osteochondral fracture(injury) v) Synovial chondromatosis ii) Osteochondritisdessicans iv) Charcot''s disease","pyqMatches":[{"year":"2014","no":1758,"q":"Charcot''s joint in diabetes affects commonly","o":["Shoulder joint","Knee joint","Hip joint","Tarsal joint"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2863, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 424, '{"id":2863,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":424,"q":"Shelf life of platelets to blood bank is","o":["5 days","7 days","10 days","21 days"],"a":0,"e":"Answer- A. 5 days Platelets are approved by FDA for stored upto 5days at 20-24 (RoomTemperature) because of risk of bacterial contamination.","pyqMatches":[{"year":"2015","no":455,"q":"Shelf life of platelets to blood bank is","o":["5 days","7 days","10 days","21 days"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2864, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 425, '{"id":2864,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":425,"q":"DOC for listeria meningitis -","o":["Ampicillin","Cefotaxime","Cefotriaxone","Ciprofloxacin"],"a":0,"e":"Answer- A. Ampicillin The antibiotic of choice for listeria infection is ampicillin or penicillin G.","pyqMatches":[{"year":"2012","no":1085,"q":"DOC for listeria meningitis","o":["Ampicillin","Cefotaxime","Cefotriaxone","Ciprofloxacin"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2016","no":699,"q":"DOC for listeria meningitis","o":["Ampicillin","Cefotaxime","Cefotriaxone","Ciprofloxacin"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2012","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2865, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 426, '{"id":2865,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":426,"q":"Dent''s disease is characterized by all except","o":["Chloride channel defect","Males are affected","Nephrolithiasis","Defect in limb of Loop of Henle"],"a":3,"e":"Answer- D. Defect in limb of Loop of Henle Dent''s disease refers to heterogenous group of X-linked disorders. It b characterized by manifestations of proximal tubule dysfunction (PT) dysfunction associated with hypercalciuria nephrolithiasis, nephrocalcinosis and progressive renalfailure These features are found in males only. mutation in gene encoding CLS-S, a Voltage gated Chloide channel.","pyqMatches":[{"year":"2013","no":1233,"q":"Dent''s disease is characterized by all except","o":["Chloride channel defect","Males are affected","Nephrolithiasis","Defect in limb of Loop of Henle"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2866, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 427, '{"id":2866,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":427,"q":"All are true for transplanted kidney except","o":["Humoral antibody responsible for rejection","CMI is responsible for rejection","Previous blood transfusion","HLA identity similarity seen in 1:100 people"],"a":3,"e":"Answer- D. HLA identity similarity seen in 1:100 people Within any particular family, sibling''s have a 7:4 chance of being HLA identical. In contrast among unrelated people, the probabilities of HLA identity in several thousand depending upon phenotype involved'' It is due to the fact that HLA complex is inherited intact as two haplotypes.","pyqMatches":[{"year":"2015","no":1106,"q":"All are true for transplanted kidney except","o":["Humoral antibody responsible for rejection","CMI is responsible for rejection","Previous blood transfusion","HLA identity similarity seen in 1:100 people"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2867, 'Medicine', 'Miscellaneous', 'Hard', 'Internal_Medicine', 428, '{"id":2867,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Internal_Medicine","sourceNo":428,"q":"Best management after human bite -","o":["Ampicillin plus sulbactam","Clindamycin plus TMP-SMX","Fibroquinolone","Doxycycline"],"a":0,"e":"Answer- A. Ampicillin plus sulbactam","pyqMatches":[{"year":"2015","no":1203,"q":"Best management after human bite","o":["Ampicillin plus sulbactam","Clindamycin plus TMP-SMX","Fibroquinolone","Doxycycline"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2868, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 429, '{"id":2868,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":429,"q":"Duroziez''s sign is seen in","o":["Aortic Regurgitation","Tricuspid RegurgitationMitral stenosis","Pericardial effusion","None"],"a":0,"e":"Answer- A. Aortic Regurgitation In severe aortic regurgitation, gradual pressure over the femoral artery leads to a systolic and diastolic bruit. Refers to systolic and distolic murmurs heard over the femoral artery while partially compresslng the vessel with the diaphragm of the stethoscope.","pyqMatches":[{"year":"2015","no":1102,"q":"Duroziez''s sign is seen in","o":["Aortic Regurgitation","Tricuspid RegurgitationMitral stenosis","Pericardial effusion","None"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2869, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 430, '{"id":2869,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":430,"q":"TTKG in hypokalemia is -","o":["< 3-4","> 6-7","> 9-10","> 10-15"],"a":0,"e":"Answer- A. < 3-4 A normal TTK in normal subjects on normal diet is 8-9 Without other disease, hypokalemia should produce a TTKG <3","pyqMatches":[{"year":"2013","no":1318,"q":"TTKG in hypokalemia is","o":["< 3-4","> 6-7","> 9-10","> 10-15"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2870, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 431, '{"id":2870,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":431,"q":"Most common cause of death in diphtheria is due to","o":["Airway compromise","Toxic cardiomyopathy","Sepsis","Descending polyneuropathy"],"a":1,"e":"Answer- B. Toxic cardiomyopathy Most common cause of death in diphtheria cardiomyopathy","pyqMatches":[{"year":"2013","no":876,"q":"Most common cause of death in diphtheria is due to","o":["Airway compromise","Toxic cardiomyopathy","Sepsis","Descending polyneuropathy"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2871, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 432, '{"id":2871,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":432,"q":"Upper lobe bronchiectasis is seen in which disease?","o":["Cystic fibrosis","Aspergilloma","HIV","Bronchogenic carcinoma"],"a":0,"e":"Answer- A. Cystic fibrosis Upper lobe bronchiectasis- Cystic fibrosis Tuberculosis Non tuberculous mycobacterial infections","pyqMatches":[{"year":"2014","no":1327,"q":"Upper lobe bronchiectasis is seen in which disease?","o":["Cystic fibrosis","Aspergilloma","HIV","Bronchogenic carcinoma"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2872, 'Medicine', 'Hematology', 'Hard', 'Internal_Medicine', 433, '{"id":2872,"subject":"Medicine","chapter":"Hematology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":433,"q":"On medical check up of a Punjabi student following findings were seen Hb of 9.9gm/d1, RBC count of 5.1 million, MCV of 62.5 fl and RDW of 13.51%. What is the most probable diagnosis ?","o":["HbD","Thalassemia trait","Iron deficiency anemia","Anemia of chronic disease"],"a":1,"e":"Answer- B. Thalassemia trait Normal RDW with low MCV is seen in--","pyqMatches":[{"year":"2014","no":1462,"q":"On medical check up of a Punjabi student following findings were seen Hb of 9.9gm/d1, RBC count of 5.1 million, MCV of 62.5 fl and RDW of 13.51%. What is the most probable diagnosis ?","o":["HbD","Thalassemia trait","Iron deficiency anemia","Anemia of chronic disease"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2873, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 434, '{"id":2873,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":434,"q":"Risk factors associated with health care associated pneumonia (HCAP)-","o":["Acute care hospitalization for at least 2 days in the preceding 90 days","Home infusion therapy","Immunosuppressive disease or immunosuppressive therapy","Antibiotic therapy in the preceding 90 days e) Hospitalization for > 48 h"],"a":0,"e":":B:C:D:E Answer- (A) Acute care hospitalization for at least 2 days in the preceding 90 days (B) Home infusion therapy (C) Immunosuppressive disease or immunosuppressive therapy (D) Antibiotic therapy in the preceding 90 days (E) Hospitalization for > 48 h Acute care hospitalization for at least 2 days in the preceding 90 days Residence in a nursing home or extended care facility Home infusion therapy, including chemotherapy, within the past 30 days Long-term dialysis within the past 30 days Home wound care Family member with an infection involving a multiple drug resistant pathogen Immunosuppressive disease or immunosuppressive therapy","pyqMatches":[{"year":"2014","no":1967,"q":"Risk factors associated with health care associated pneumonia (HCAP)","o":["Acute care hospitalization for at least 2 days in the preceding 90 days","Home infusion therapy","Immunosuppressive disease or immunosuppressive therapy","Antibiotic therapy in the preceding 90 days e) Hospitalization for > 48 h"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2874, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 435, '{"id":2874,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":435,"q":"Malignancy associated with hypercalcemia:","o":["Breast cancer","Small cell lung cancer","Non-small lung cancer","Prostate cancer e) Multiple myeloma"],"a":0,"e":":C:D:E Answer- A,Breast cancer C,Non-small lung cancer D,Prostate cancer E,Multiple myeloma Lung carcinoma, breast carcinoma, and multlple myeloma account for more than 50% of all cases of malignancy-associated hypercalcemia. Gastrointestinal tumars and prostate carcinoma are less common causes of hypercalcemia.","pyqMatches":[{"year":"2016","no":411,"q":"Malignancy associated with hypercalcemia:","o":["Breast cancer","Small cell lung cancer","Non-small lung cancer","Prostate cancer e) Multiple myeloma"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2875, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 436, '{"id":2875,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":436,"q":"Capnography helps to know the following","o":["Correct intubation","Pulmonary embolism","Adequate ventilation","Lung perfusion e) Significant metabolic change"],"a":0,"e":":B:C:D:E Answer- A,Correct intubation B,Pulmonary embolism C,Adequate ventilation D,Lung perfusion E,Significant metabolic change Conditions that affect ET CO2 Increased Hypoventilation Rebreathing Malignant hyperthermia, Neuroleptic malignant syndrome Increased skeletal muscle activity (shivering Hypermetabolism Hyperthyroidism & thyroid storm Decreased Hyperventilation Pulmonary embolism Hypoperfusion, hypotension, hypovalemia, shock Hypothermia","pyqMatches":[{"year":"2013","no":1705,"q":"Capnography helps to know the following","o":["Correct intubation","Pulmonary embolism","Adequate ventilation","Lung perfusion e) Significant metabolic change"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2876, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 437, '{"id":2876,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":437,"q":"The severity of mitral stenosis can be judged by-","o":["Intensity of murmur","Duration of murmur","Left ventricular S3","Loud S1"],"a":1,"e":"Answer- B. Duration of murmur Duration depends on severity of MS. In severe MS, the mid diastolic murmur is long and merges with the presystolic murmur to produce holodiastolic murmur..","pyqMatches":[{"year":"2015","no":1104,"q":"The severity of mitral stenosis can be judged by","o":["Intensity of murmur","Duration of murmur","Left ventricular S3","Loud S1"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2877, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 438, '{"id":2877,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":438,"q":"Pure motor palsy seen in poisoning of","o":["Lead poisoning","Arsenic poisoning","Cocaine poisoning","Cannabis poisoning"],"a":0,"e":"Ans. is ''A'' i.e., Lead poisoning The peripheral neuropathy of lead toxicity is a pure motor neuropathy affecting the upper limbs more than the lower limbs, presenting as symmetric or asymmetric wrist drop. The weakness may also involve other muscle groups of the distal upper extremities, the involvement of lower extremities, including isolated foot drop, also may occur.","pyqMatches":[{"year":"2016","no":666,"q":"Pure motor palsy seen in poisoning of","o":["Lead poisoning","Arsenic poisoning","Cocaine poisoning","Cannabis poisoning"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2878, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 439, '{"id":2878,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":439,"q":"Smokers are prone to which lung infection","o":["Mycobacterium tuberculosis","Pneumonia","Influenza","All the above"],"a":3,"e":"Answer- D. All the above","pyqMatches":[{"year":"2016","no":1030,"q":"Smokers are prone to which lung infection","o":["Mycobacterium tuberculosis","Pneumonia","Influenza","All the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2879, 'Medicine', 'Miscellaneous', 'Hard', 'Internal_Medicine', 440, '{"id":2879,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Internal_Medicine","sourceNo":440,"q":"Some patients with severe form of Idiopathic infantile hypercalcemia, presnt with phenotypic features similar to which of the following?","o":["Williams syndrome","Potters syndrome","Angelman syndrome","VHL syndrome"],"a":0,"e":"Answer- A. Williams syndrome In the severe form, Prenatal and postnatal growth failure are common and number of phenotypic features of Williams syndrome are observed in some of the patients include cardiovascular abnormalities (usually supravalvular aortic stenois and peripheral pulmonic stenosis), late psychomotor development, selective mental deficiency, a characteristic unusual facies and short stature. The serum calcium levels range between 12 - 19mg/ dL.","pyqMatches":[{"year":"2016","no":1031,"q":"Some patients with severe form of Idiopathic infantile hypercalcemia, presnt with phenotypic features similar to which of the following?","o":["Williams syndrome","Potters syndrome","Angelman syndrome","VHL syndrome"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2880, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 441, '{"id":2880,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":441,"q":"Which liver disease/s is/are associated with ductopenia?","o":["Chronic graft rejection","Hepatic sarcoidosis","Paraneoplastic syndrome related to hodgkins lymphoma","All the above"],"a":3,"e":"Answer- D. All the above Loss of bile ducts from the portal tracts is referred to as ductopenia. Ductopenia is most commonly seen related to chronic allograft rejection and includes drug related injury, primary binary cirrhosis, primary sclerosing cholangitis, chronic graft-vs-host disease, hepatic sarcoidosis, paraneoplastic syndrome related to Hodgkin disease, and syndromic paucity of bile ducts (Alagille syndrome).","pyqMatches":[{"year":"2016","no":1032,"q":"Which liver disease/s is/are associated with ductopenia?","o":["Chronic graft rejection","Hepatic sarcoidosis","Paraneoplastic syndrome related to hodgkins lymphoma","All the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2881, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 442, '{"id":2881,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":442,"q":"Which of the following is not true about metabolic syndrome?","o":["It is also called Syndrome X","Acanthosis and signs of hyperandrogenism may be seen","Type A has autoantibodies against the insulin receptor","Insulin resistance increases the risk of type 2 DM in patients with PCOS"],"a":2,"e":"Answer- C. Type A has autoantibodies against the insulin receptor It is an insulin resistance condition which comprises a spectrum of disorders, with hyperglycemia representing one of the most readily diagnosed features. The metabolic syndrome, the insulin resistance syndrome, or syndrome X are terms used to describe a constellation of metabolic derangements that includes insulin resistance, hypertension, dyslipidemia (decreased HDL and elevated triglycerides), central or visceral obesity, type 2 diabetes or IGT/IFG, and accelerated cardio- vascular disease. Acanthosis nigricans and signs of hyperandrogenism (hirsutism, acne, and oligomenorrhea in women) are also common physical features. Two distinct syndromes-","pyqMatches":[{"year":"2016","no":1034,"q":"Which of the following is not true about metabolic syndrome?","o":["It is also called Syndrome X","Acanthosis and signs of hyperandrogenism may be seen","Type A has autoantibodies against the insulin receptor","Insulin resistance increases the risk of type 2 DM in patients with PCOS"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2882, 'Medicine', 'Miscellaneous', 'Hard', 'Internal_Medicine', 443, '{"id":2882,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Internal_Medicine","sourceNo":443,"q":"Metabolic syndrome diagnosis in men based on NCEP ATP III criteria includes the following except","o":["Abdominal obesity > 40 inches","HDL < 50 mg / dL","BP >/= 130/85 mm Hg","Fasting glucoe > 110 mg/ dL"],"a":1,"e":"Answer- B. HDL < 50 mg / dL","pyqMatches":[{"year":"2016","no":1035,"q":"Metabolic syndrome diagnosis in men based on NCEP ATP III criteria includes the following except","o":["Abdominal obesity > 40 inches","HDL < 50 mg / dL","BP >/= 130/85 mm Hg","Fasting glucoe > 110 mg/ dL"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2883, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 444, '{"id":2883,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":444,"q":"Ejection click of pulmonary stenosis is better heard in","o":["Inspiration","Expiration","Patient bending forward","Patient lying in left lateral position"],"a":1,"e":"Answer- B. Expiration It emanates from a stenotic pulmonary valve or a dilated pulmonary artery. Its most characteristic feature is to disappear or become markedly softer with inspiration i.e. it is better heard in expiration. It is localized to 2nd and 3rd intercostal spaces. They may also be present in patients with pulmonary hypertention or the ones with dilated pulmonary artery.","pyqMatches":[{"year":"2016","no":1038,"q":"Ejection click of pulmonary stenosis is better heard in","o":["Inspiration","Expiration","Patient bending forward","Patient lying in left lateral position"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2884, 'Medicine', 'Cardiology', 'Hard', 'Internal_Medicine', 445, '{"id":2884,"subject":"Medicine","chapter":"Cardiology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":445,"q":"Reciprocal changes in ECG in patients with inferior wall myocardial infarction are seen in which leads","o":["I","II","III","aVF"],"a":0,"e":"Answer- A. I","pyqMatches":[{"year":"2016","no":1039,"q":"Reciprocal changes in ECG in patients with inferior wall myocardial infarction are seen in which leads","o":["I","II","III","aVF"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2885, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 446, '{"id":2885,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":446,"q":"All are features of aortic stenosis except","o":["Congestive heart failure due to systolic or diastolic dysfunction","Presence of ejection systolic murmur","Presence of pulsus tardus","Pressure in the aorta is the same as in left ventricle"],"a":3,"e":"Answer- D. Pressure in the aorta is the same as in left ventricle Clinical Findings- Systolic ejection murmur Carotid pulsus parvus et tardus Diminished aortic component of 2nd heart sound Sudden death in severe stenosis after exercise Classical triad- Angina Syncope Shortness of breath (heart failure)","pyqMatches":[{"year":"2016","no":1040,"q":"All are features of aortic stenosis except","o":["Congestive heart failure due to systolic or diastolic dysfunction","Presence of ejection systolic murmur","Presence of pulsus tardus","Pressure in the aorta is the same as in left ventricle"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2886, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 447, '{"id":2886,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":447,"q":"Which of the following is not true about bicuspid aortic valve?","o":["Usually undetected in early life","It is more common in females than in males","Post-stenotic dilatation of ascending aorta can be seen","Diagnosis is made by echocardiography"],"a":1,"e":"Answer- B. It is more common in females than in males The congenital bicuspid aortic valve, which may initially be functionally normal, is one of the most common congenital malformations of the heart and may go undetected in early life. More frequent in males (3:1) Diagnosis is made by echocardiography, which reveals the morphology of the aortic valve and aortic root and quantitates severity of stenosis or regurgitation. The ascending aorta is often dilated, misnamed \"poststenotic\" dilatation; this is due to histologic abnormalities of the aortic media similar to those in Marfan''s syndrome and may result in aortic dissection.","pyqMatches":[{"year":"2016","no":1041,"q":"Which of the following is not true about bicuspid aortic valve?","o":["Usually undetected in early life","It is more common in females than in males","Post-stenotic dilatation of ascending aorta can be seen","Diagnosis is made by echocardiography"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2887, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 448, '{"id":2887,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":448,"q":"Which of the following hemodynamic changes is not evident in cardiac tamponade during diastole?","o":["Right atrial and ventricular collapse","Absent y wave on JVP","Biphasic venous return","Elevated pericardial pressure"],"a":2,"e":"Answer- C. Biphasic venous return During the diastole the pericardial pressure remains elevated. It is greater than the intracavitary pressure thus there is no filling during the diastole The absence of venous return during the diastole leads to absence of \"y\" waves on the J.V.P. and the \"diastolic collapse\" of the right atria and ventricle.","pyqMatches":[{"year":"2016","no":1042,"q":"Which of the following hemodynamic changes is not evident in cardiac tamponade during diastole?","o":["Right atrial and ventricular collapse","Absent y wave on JVP","Biphasic venous return","Elevated pericardial pressure"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2888, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 449, '{"id":2888,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":449,"q":"Major criteria for infective endocarditis include which of the following","o":["Injection drug user","Fever","Oslers nodes","Typical organism of infective endocarditis isolated from two separate blood cultures"],"a":3,"e":"Answer- D. Typical organism of infective endocarditis isolated from two separate blood cultures","pyqMatches":[{"year":"2016","no":1043,"q":"Major criteria for infective endocarditis include which of the following","o":["Injection drug user","Fever","Oslers nodes","Typical organism of infective endocarditis isolated from two separate blood cultures"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2889, 'Medicine', 'Cardiology', 'Hard', 'Internal_Medicine', 450, '{"id":2889,"subject":"Medicine","chapter":"Cardiology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":450,"q":"Which of the following ECG features are not seen in patients with ventricular tachycardias?","o":["Bizzare QRS complexes","Presence of AV dissociation [fusion beats]","Prolonged duration of QRS complexes","P pulmonale"],"a":3,"e":"Answer- D. P pulmonale AV dissociation (atrial capture, fusion beats) QRS duration > 140 ms for RBBB type V1 morphology, VI > 160 ms for LBBB type VI morphology Frontal plane axis - 900 to 1800 Delayed activation during initial phase of the QRS complex LBBB pattern - R wave in V1, V, > 40 ms RBBB pattern - onset of R wave to nadir of S > 100 ms Bizarre QRS pattern that does not mimic typical RBBB or LBBB QRS complex. Concordance of QRS complex in all precordial leads RS or dominant S in V6 for RBBB VT Q wave in V6 with LBBB QRS pattern Monophasic R or biphasic qR of R/S in V, with RBBB pattern","pyqMatches":[{"year":"2016","no":1044,"q":"Which of the following ECG features are not seen in patients with ventricular tachycardias?","o":["Bizzare QRS complexes","Presence of AV dissociation [fusion beats]","Prolonged duration of QRS complexes","P pulmonale"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2890, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 451, '{"id":2890,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":451,"q":"Cerebro-occulo-genital syndrome has the following features except","o":["Microcephaly","Short stature","Agenesis of corpus callosum","Flaccid quadriplegia"],"a":3,"e":"Answer- D. Flaccid quadriplegia Cerebro-occulo-genital syndrome is associated with microcephaly, short stature, microophthalmia, agenesis of corpus callosum, hypospadias and spastic quadriplegia.","pyqMatches":[{"year":"2016","no":1045,"q":"Cerebro-occulo-genital syndrome has the following features except","o":["Microcephaly","Short stature","Agenesis of corpus callosum","Flaccid quadriplegia"],"a":3,"source":"NEET_2016_Paper.pdf"},{"year":"2016","no":1117,"q":"Cerebro-occulo-genital syndrome has the following features except","o":["Microcephaly","Short stature","Agenesis of corpus callosum","Flaccid quadriplegia"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2891, 'Medicine', 'Neurology', 'Moderate', 'Internal_Medicine', 452, '{"id":2891,"subject":"Medicine","chapter":"Neurology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":452,"q":"Pulsus biseferians, which of the following is not true","o":["It is seen in aortic regurgitation","It is better felt in peripheral arteries","It has one peak in systole and one in diastole","It has two peaks"],"a":2,"e":"Answer- C. It has one peak in systole and one in diastole It is characterized by two systolic peaks. It is seen in patients of aortic regurgitation. The pulse wave upstroke rises rapidly and forcefully producing the first systolic peak (percussion wave). A brief decline in pressure is followed by a smaller and somewhat slower rising positive pulse wave. In bisiferians pulse the second rise in systole is enhanced by reflection from peripheral arteries therefore it is more prominent in peripheral pulse.","pyqMatches":[{"year":"2016","no":1046,"q":"Pulsus biseferians, which of the following is not true","o":["It is seen in aortic regurgitation","It is better felt in peripheral arteries","It has one peak in systole and one in diastole","It has two peaks"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2892, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 453, '{"id":2892,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":453,"q":"Square wave seen in ECG recording denote","o":["Atrial depolarization","Ventricular depolarization","Ventricular repolarization","Standardization of ECG"],"a":3,"e":"Answer- D. Standardization of ECG Each ECG machine has a provision for Standardization (STD) of Calibration (CAL). The standardization lever releases a current of 1 mV to the stylus of ECG machine that records a shift of 10 mm on the ECG paper. The standardization current gives rise to a wave pattern called square wave pattern as depicted in the image below.","pyqMatches":[{"year":"2016","no":1048,"q":"Square wave seen in ECG recording denote","o":["Atrial depolarization","Ventricular depolarization","Ventricular repolarization","Standardization of ECG"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2893, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 454, '{"id":2893,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":454,"q":"Which of the following is not true about Torsades de pointes?","o":["Presence of prolonged QT interval on ECG","Presence of polymorphic QRS complexes","It is a type of supraventricular tachycardia","QRS complexes appear to rotate around the isoelectric baseline of ECG"],"a":2,"e":"Answer- C. It is a type of supraventricular tachycardia The significance of the long QT syndrome is its association with the development of a specific type of ventricular tachycardia called Torsades de points or polymorphic ventricular tachycardia A wide complex tachyarrythmia with QRS complexes of varying axis and morphology that appear to rotate around the iso electric baseline.","pyqMatches":[{"year":"2016","no":1049,"q":"Which of the following is not true about Torsades de pointes?","o":["Presence of prolonged QT interval on ECG","Presence of polymorphic QRS complexes","It is a type of supraventricular tachycardia","QRS complexes appear to rotate around the isoelectric baseline of ECG"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2894, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 455, '{"id":2894,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":455,"q":"Prolonged QT interval is seen in all of the following except","o":["Hypokalemia","Hypocalcemia","Use of macrolide antibiotitcs","Hypernatremia"],"a":3,"e":"Answer- D. Hypernatremia Metabolic Hypokalemia Hypocalcemia Hypomagnesemia","pyqMatches":[{"year":"2016","no":1050,"q":"Prolonged QT interval is seen in all of the following except","o":["Hypokalemia","Hypocalcemia","Use of macrolide antibiotitcs","Hypernatremia"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2895, 'Medicine', 'Cardiology', 'Hard', 'Internal_Medicine', 456, '{"id":2895,"subject":"Medicine","chapter":"Cardiology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":456,"q":"Following are the clinical signs of widened pulse pressure seen in patients of aortic regurgitation except","o":["Corrigans sign","De Mussets sign","Water Hammer pulse","Diastolic murmur"],"a":3,"e":"Answer- D. Diastolic murmur Corrigan’s pulse: A rapid and forceful distension of the arterial pulse with a quick collapse De Musset’s sign: Bobbing of the head with each heartbeat (like a bird walking) Muller’s sign: Visible pulsations of the uvula Quincke’s sign: Capillary pulsations seen on light compression of the nail bed Traube’s sign: Systolic and diastolic sounds heard over the femoral artery (“pistol shots”) Duroziez’s sign: Gradual pressure over the femoral artery leads to a systolic and diastolic bruit Hill’s sign: Popliteal systolic blood pressure exceeding brachial systolic blood pressure by ≥ 60 mmHg (most sensitive sign for aortic regurgitation) Water hammer pulse","pyqMatches":[{"year":"2016","no":1051,"q":"Following are the clinical signs of widened pulse pressure seen in patients of aortic regurgitation except","o":["Corrigans sign","De Mussets sign","Water Hammer pulse","Diastolic murmur"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2896, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 457, '{"id":2896,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":457,"q":"Episode of stable angina pectoris typically lasts for","o":["Less than 1 min","2 - 5 mins","5 - 10 mins","> 10 mins"],"a":1,"e":"Answer- B. 2 - 5 mins Angina is usually crescendo- decrescendo in nature, typically lasts 2 to 5 min, and can radiate to either shoulder and to both arms (especially the ulnar surfaces of the forearm and hand). It also can arise in or radiate to the back, interscapular region, root of the neck, jaw, teeth, and epigastrium. Angina is rarely localized below the umbilicus or above the mandible.","pyqMatches":[{"year":"2016","no":1053,"q":"Episode of stable angina pectoris typically lasts for","o":["Less than 1 min","2 - 5 mins","5 - 10 mins","> 10 mins"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2897, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 458, '{"id":2897,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":458,"q":"Not True about Prinzmetal''s angina:","o":["May present at rest","Occurs due atherosclerotic obstruction of coronary arteries","Smoking is a risk factor","Nitrates are used for treatment"],"a":1,"e":"Answer- B. Occurs due atherosclerotic obstruction of coronary arteries This syndrome is due to focal spasm of an epicardial coronAry artery, leading to severe myocardial ischemia leading to severe myocardial ischemia. The right coronary artery is the most frequent site, followed by the left anterior descending coronary artery. Acetylcholine released by the parasympathetic system at rest will simply cause contraction of the vascular smooth muscle. It usually occurs at rest and is associated with transient ST- segment elevation. Etiology cigarette smokers","pyqMatches":[{"year":"2016","no":1055,"q":"Not True about Prinzmetal''s angina:","o":["May present at rest","Occurs due atherosclerotic obstruction of coronary arteries","Smoking is a risk factor","Nitrates are used for treatment"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2898, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 459, '{"id":2898,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":459,"q":"Obstructive shock can be seen in","o":["Pulmonary embolism","Tension pneumothorax","Pericardial tamponade","All the above"],"a":3,"e":"Answer- D. All the above Causes in trauma patients include pulmonary embolism, pericardial tamponade, acute coronary syndromes, increased intrathoracic pressure as in tension pneumothorax, positive pressure ventilation and excessive PEEP.","pyqMatches":[{"year":"2016","no":1057,"q":"Obstructive shock can be seen in","o":["Pulmonary embolism","Tension pneumothorax","Pericardial tamponade","All the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2899, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 460, '{"id":2899,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":460,"q":"Pharmacological stress during stress myocardial radionucleotide perfusion imaging can be induced using","o":["Dipyridamole","Adenosine","Dobutamine","All the above"],"a":3,"e":"Answer- D. All the above Dipyridamole or adenosine can be given to create a coronary \"steal\" by temporarily increasing flow in nondiseased segments of the coronary vasculature at the expense of diseased segments. Alternatively, a graded incremental infusion of dobutamine may be administered to increase MVO2. The development of a transient perfusion defect with a tracer such as thallium-201 or 99m-technetium sestamibi is used to detect myocardial ischemia.","pyqMatches":[{"year":"2016","no":1058,"q":"Pharmacological stress during stress myocardial radionucleotide perfusion imaging can be induced using","o":["Dipyridamole","Adenosine","Dobutamine","All the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2900, 'Medicine', 'Cardiology', 'Hard', 'Internal_Medicine', 461, '{"id":2900,"subject":"Medicine","chapter":"Cardiology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":461,"q":"While treating patients with malignant hypertention the maximum allowed decrease in blood pressure in the first 2 - 6 hours should not exceed %","o":["15","20","25","30"],"a":2,"e":"Answer- C. 25 Hypertension with systolic BP 180 mmHg and diastolic BP 120 mm Hg is classified as \"severe hypertension\". Severe hypertension ( 180/120) does not necessarily mean hypertensive emergency or malignant hypertension. ? Patients with B.P. 180 / 120 may remain asymptomatic without causing any complications. The initial aim of treatment in malignant hypertension and hypertensive encephalopathy is to lower diastolic blood pressure to about 100 to 105 mm Hg within minutes to, two- six hours with the maximum fall in B.P. over this period of time not exceeding 25% of the original value.","pyqMatches":[{"year":"2016","no":1059,"q":"While treating patients with malignant hypertention the maximum allowed decrease in blood pressure in the first 2 - 6 hours should not exceed %","o":["15","20","25","30"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2901, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 462, '{"id":2901,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":462,"q":"Contraindication for percutaneous ballon mitral valvotomy include the following except","o":["Presence of pulmonary hypertension","Left atrial thrombus","Severe mitral regurgitation","Commissural calcification"],"a":0,"e":"Answer- A. Presence of pulmonary hypertension Patients with valvular calcification, thickened fibrotic leaflets with decreased mobility and subvalvular fusion, have incidence of acute complications and higher rate of restenosis on followup. Such patients are considered a contraindication for the procedure. Other contraind ications include more than moderate mitral regurgitation, presence of left atrial thrombi, and commissural calcification.","pyqMatches":[{"year":"2016","no":1061,"q":"Contraindication for percutaneous ballon mitral valvotomy include the following except","o":["Presence of pulmonary hypertension","Left atrial thrombus","Severe mitral regurgitation","Commissural calcification"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2902, 'Medicine', 'Cardiology', 'Hard', 'Internal_Medicine', 463, '{"id":2902,"subject":"Medicine","chapter":"Cardiology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":463,"q":"Mitral valve replacement is recommended in patients with","o":["Moderate MS in NYHA class II","Moderate MS in NYHA class III","Severe MS in NYHA class II","Severe MS in NYHA class III"],"a":3,"e":"Answer- D. Severe MS in NYHA class III Since there are also long-term complications of valve replacement, patients in whom preoperative evaluation suggests the possibility that MVR may be required should be operated on only if they have severe MS—i.e., an orifice area \"1 cm2—and are in NYHA Class III, i.e., symptomatic with ordinary activity despite optimal medical therapy\".","pyqMatches":[{"year":"2016","no":1062,"q":"Mitral valve replacement is recommended in patients with","o":["Moderate MS in NYHA class II","Moderate MS in NYHA class III","Severe MS in NYHA class II","Severe MS in NYHA class III"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2903, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 464, '{"id":2903,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":464,"q":"HOCM is common in which age group?","o":["10 - 30 years","20 - 40 years","30 - 50 years","40 - 60 years"],"a":1,"e":"Answer- B. 20 - 40 years Hypertrophic cardiomyopathy is characterized by marked left ventricular hypertrophy in the absence of other causes, such as hyper- tension or valve disease. Earlier termed hypertrophic obstructive cardiomyopathy (HOCM) Hypertrophic cardiomyopathy is characterized hemodynamically by diastolic dysfunction, originally attributed to the hyper¬trophy, fibrosis, and intraventricular gradient when present. Hypertrophic cardiomyopathy usually presents between the ages of 20 and 40 years. Dyspnea on exertion is the most common presenting symptom, reflecting elevated intracardiac filling pressures","pyqMatches":[{"year":"2016","no":1063,"q":"HOCM is common in which age group?","o":["10 - 30 years","20 - 40 years","30 - 50 years","40 - 60 years"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2904, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 465, '{"id":2904,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":465,"q":"Preferred vein for central venous catheter insertion is","o":["Right internal jugular vein","Left internal jugular vein","Right subclavian vein","Right antecubital vein"],"a":0,"e":"Answer- A. Right internal jugular vein Placement of the central venous catheter is indicated for the monitoring of the central venous pressure and for prolonged drug administration for parenteral nutrition. The preferred site for insertion of catheter into the superior venacava is from internal jugular vein of the neck. Other used sites are from the subclavian vein or from the peripheral vein in the antecubital fossa. Commonly used vein cannulation sites for central venous access include: Jugular vein External jugular vein Internal jugular vein (central, posterior, anterior approaches) Subclavian vein (supraclavicular, infraclavicular, axillary approaches) Femoral vein Basilic vein","pyqMatches":[{"year":"2016","no":1064,"q":"Preferred vein for central venous catheter insertion is","o":["Right internal jugular vein","Left internal jugular vein","Right subclavian vein","Right antecubital vein"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2905, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 466, '{"id":2905,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":466,"q":"Kerley B lines seen in mitral stenosis when the resting left atrial pressure exceeds","o":["10 mm Hg","20 mm Hg","30 mm Hg","40 mm Hg"],"a":1,"e":"Answer- B. 20 mm Hg Kerley B lines are fine, dense, opaque, horizontal lines that are most prominent in the lower and mid-lung fields and that result from distention of interlobular septae and lymphatics with edema when the resting mean LA pressure exceeds approximately 20 mmHg.","pyqMatches":[{"year":"2016","no":1065,"q":"Kerley B lines seen in mitral stenosis when the resting left atrial pressure exceeds","o":["10 mm Hg","20 mm Hg","30 mm Hg","40 mm Hg"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2906, 'Medicine', 'Nephrology', 'Hard', 'Internal_Medicine', 467, '{"id":2906,"subject":"Medicine","chapter":"Nephrology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":467,"q":"Which of the following is the most common anamoly in patients with fanconi''s anemia?","o":["Hyperpigmentation of the trunk, neck and intertriginous areas","Absent radii and thumb","Weak radial pulse","Presence of horse shoe kidneys"],"a":0,"e":"Answer- A. Hyperpigmentation of the trunk, neck and intertriginous areas Fanconi anemia (FA) is primarily inherited in an autosomal recessive manner (one uncommon form is X-linked recessive). The most common anomaly in FA is hyperpigmentation of the trunk, neck, and intertriginous areas, as well as café-au-lait spots and vitiligo, alone or in combination. Anomalies of the feet, congenital hip dislocation, and leg abnormalities are seen.","pyqMatches":[{"year":"2016","no":1066,"q":"Which of the following is the most common anamoly in patients with fanconi''s anemia?","o":["Hyperpigmentation of the trunk, neck and intertriginous areas","Absent radii and thumb","Weak radial pulse","Presence of horse shoe kidneys"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2907, 'Medicine', 'Gastroenterology', 'Hard', 'Internal_Medicine', 468, '{"id":2907,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":468,"q":"Patients with which of the following conditions are at greatest risk of pernio","o":["Raynaud''s phenomenon","Kawasaki disease","Henoch Schonlen purpura","Hepatitis C infection"],"a":0,"e":"Answer- A. Raynaud''s phenomenon The two most common nonfreezing peripheral cold injuries are chilblain (pernio) and immersion (trench) foot. Chilblain results from neuronal and endothelial damage induced by repetitive exposure to dry cold. Young females, particularly those with a history of Raynaud''s phenomenon, are at greatest risk of pernio (chilblain). Persistent vasospasticity and vasculitis can cause erythema, mild edema, and pruritus. Eventually plaques, blue nodules, and ulcerations develop","pyqMatches":[{"year":"2016","no":1067,"q":"Patients with which of the following conditions are at greatest risk of pernio","o":["Raynaud''s phenomenon","Kawasaki disease","Henoch Schonlen purpura","Hepatitis C infection"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2908, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 469, '{"id":2908,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":469,"q":"What is Tiffeneau - Pinelli index?","o":["FEV1/FVC ratio","Body mass index","Quetlet index","Ventilation/Perfusion ratio"],"a":0,"e":"Answer- A. FEV1/FVC ratio","pyqMatches":[{"year":"2016","no":1069,"q":"What is Tiffeneau - Pinelli index?","o":["FEV1/FVC ratio","Body mass index","Quetlet index","Ventilation/Perfusion ratio"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2909, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 470, '{"id":2909,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":470,"q":"Lights criteria is used for","o":["Pleural effusions","Pericardial effusions","Ascites","Increased intracranial tension"],"a":0,"e":"Answer- A. Pleural effusions Light''s critena for classification of unilateral pleural effusion The pleural fluid is an exudate if one or more of the following citeria are met. Pleural fluid protein divided by serum protein >0.5 Pleural fluid lacato dehyoctogenase LDH divided by serum LDH > 0.6","pyqMatches":[{"year":"2016","no":1070,"q":"Lights criteria is used for","o":["Pleural effusions","Pericardial effusions","Ascites","Increased intracranial tension"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2910, 'Medicine', 'Cardiology', 'Hard', 'Internal_Medicine', 471, '{"id":2910,"subject":"Medicine","chapter":"Cardiology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":471,"q":"Common cause of death in a patient with chronic bronchieactasis is","o":["Right sided heart fail","Infection","Hemoptysis","Carcinoma"],"a":0,"e":"Answer- A. Right sided heart fail In todays world, right sided heart failure in patients with diffuse long standing bronchieactasis is a common cause of death in patients with chronic bronchieactasis. Pneumonia and hemorrhage are less common causes of death.","pyqMatches":[{"year":"2016","no":1071,"q":"Common cause of death in a patient with chronic bronchieactasis is","o":["Right sided heart fail","Infection","Hemoptysis","Carcinoma"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2911, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 472, '{"id":2911,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":472,"q":"Leutriene inhibitors are used in asthma for","o":["Monotherapy for acute attack","Add-on therapy in patients not controlled by low dose inhaled glucocorticoids","Status asthmaticus","None of the above"],"a":1,"e":"Answer- B. Add-on therapy in patients not controlled by low dose inhaled glucocorticoids Cysteinyl-leukotrienes are potent bronchoconstrictors, cause microvascular leakage, and increase eosinophilic inflammation through the activation of cys-LT1-receptors. Lukotriene inhibitors such as montelukast and zafirlukast, block cys- LT 1-receptors and provide modest clinical benefit in asthma. They are less effective than inhaled corticosteroids in controlling asthma and have less effect on airway inflammation, but are useful as an add-on therapy in some patients not controlled with low doses of inhaled corticosteroids.","pyqMatches":[{"year":"2016","no":1072,"q":"Leutriene inhibitors are used in asthma for","o":["Monotherapy for acute attack","Add-on therapy in patients not controlled by low dose inhaled glucocorticoids","Status asthmaticus","None of the above"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2912, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 473, '{"id":2912,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":473,"q":"Apnea hypoapnea index indicating obstructive sleep apnea is -","o":["<1","2 - 5","5 - 8",">8"],"a":0,"e":"Answer- A. <1 Normal preschool and school-age children generally have a total AHI of less than 1.5 (obstructive AHI <1), and this is the most widely used cutoff value for Obstructive Sleep Apnea in children 12 yr and below; in older adolescents, the adult cutoff of an AHI 5 is generally used.","pyqMatches":[{"year":"2016","no":1073,"q":"Apnea hypoapnea index indicating obstructive sleep apnea is","o":["<1","2 - 5","5 - 8",">8"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2913, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 474, '{"id":2913,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":474,"q":"Multiple episodes of acute chest syndrome are associated with","o":["Asthma","Bronchieactasis","SLE","Sjogrens syndrome"],"a":0,"e":"Answer- A. Asthma Patient presents with recurrent episodes of acute chest syndrome. The characteristic symptoms during an episode of asthma are wheezing, dyspnea, and coughing, which are variable, both spontaneously and with therapy. Prodromal symptoms may precede an attack, with itching under the chin, discomfort between the scapulae, or inexplicable fear (impending doom).","pyqMatches":[{"year":"2016","no":1074,"q":"Multiple episodes of acute chest syndrome are associated with","o":["Asthma","Bronchieactasis","SLE","Sjogrens syndrome"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2914, 'Medicine', 'Rheumatology', 'Easy', 'Internal_Medicine', 475, '{"id":2914,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":475,"q":"Triad of skin lesions, mononeuritis multiplex, eosinophils seen in","o":["Alports syndrome","Churg - Strauss syndrome","Cryoglobulinemia","Wegeners granulomatosus"],"a":2,"e":"Answer- C. Cryoglobulinemia Churg & Strauss is characterized by asthma, eosinophilla, extravascular granuloma formation, vasculitis. Clinical Features-Fever, malaise, anorexia, weight loss. Mononeuritis multiplex is the second most common features. Allergic rhinitis and sinusitis. Asthma Peripheral and tissue eosinophillia, extravascular necrotizing granuloma.","pyqMatches":[{"year":"2016","no":1075,"q":"Triad of skin lesions, mononeuritis multiplex, eosinophils seen in","o":["Alports syndrome","Churg - Strauss syndrome","Cryoglobulinemia","Wegeners granulomatosus"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2915, 'Medicine', 'Miscellaneous', 'Hard', 'Internal_Medicine', 476, '{"id":2915,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Internal_Medicine","sourceNo":476,"q":"Chronic bronchitis is said to be present when patient has chronic cough","o":["3 consecutive months in at least two consecutive years","2 consecutive months for 3 consecutive years","3 consecutive months in one year","1 month in a year for 2 consecutive years"],"a":0,"e":"Answer-A. 3 consecutive months in at least 2 consecutive years. Cigarette smoking is the most important risk factor; air pollutants also contribute. The dominant pathologic features are mucus hypersecre- tion and persistent inflammation. Histologic examination demonstrates enlargement of mucous- secreting glands, goblet cell hyperplasia, chronic inflammation, and bronchiolar wall fibrosis.","pyqMatches":[{"year":"2016","no":1076,"q":"Chronic bronchitis is said to be present when patient has chronic cough","o":["3 consecutive months in at least two consecutive years","2 consecutive months for 3 consecutive years","3 consecutive months in one year","1 month in a year for 2 consecutive years"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2916, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 477, '{"id":2916,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":477,"q":"Brocks syndrome is due to which lobe of lung?","o":["Right middle lobe","Right lower lobe","Left upper lobe","Left lower lobe"],"a":0,"e":"Answer- A. Right middle lobe Brocks syndrome is due to collapse of right middle lobe of lung. It is seen as an acute complication of pulmonary tuberculosis. It occurs secondary to hilar node involvement.","pyqMatches":[{"year":"2016","no":1077,"q":"Brocks syndrome is due to which lobe of lung?","o":["Right middle lobe","Right lower lobe","Left upper lobe","Left lower lobe"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2917, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 478, '{"id":2917,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":478,"q":"Presence of Velcro crackles at the lung base on auscultation is a sign of","o":["Scleroderma","Systemic Lupus","Wegeners Granulomatosus","Polyarteritisnodosa"],"a":0,"e":"Answer- A. Scleroderma CLINICAL FEATURES- Skin- sclerodactyly, Ranaud’s phenomenon, calcinosis, telangiectasia, skin thickening. (inadvance stage fingers become claw like & face mask like) Musculoskeletal features- Arthralgia, flexor tenosynovitis GIT- oesophagitis, dysphagia, malabsorption Cardiorespiratory features- pulmonary fibrosis, pulmonary hypertension Renal features- hypertensive renal crisis Malignant hypertension Physical examination may reveal \"Velcro\" crackles at the lung bases.","pyqMatches":[{"year":"2016","no":1078,"q":"Presence of Velcro crackles at the lung base on auscultation is a sign of","o":["Scleroderma","Systemic Lupus","Wegeners Granulomatosus","Polyarteritisnodosa"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2918, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 479, '{"id":2918,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":479,"q":"Type IV respiratory failure occurs due to","o":["Alveolar flooding","Inability to eliminate CO2","Lung atelactasis","Hypoperfusion of respiratory muscles"],"a":3,"e":"Answer- d. Hypoperfusion of respiratory muscles Type IV Respiratory Failure: results from hypoperfusion of respiratory muscles in patients in shock. Commonly caused by cardiogenic shock, septic shock and hypovolemic shock.","pyqMatches":[{"year":"2016","no":1080,"q":"Type IV respiratory failure occurs due to","o":["Alveolar flooding","Inability to eliminate CO2","Lung atelactasis","Hypoperfusion of respiratory muscles"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2919, 'Medicine', 'Respiratory Medicine', 'Hard', 'Internal_Medicine', 480, '{"id":2919,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Hard","source":"Internal_Medicine","sourceNo":480,"q":"Tool/s which objectively asses the risk of adverse outcomes in a patient with pneumonia is/are","o":["Pneumonia severity index [PSI]","CURB - 65 criteria","Apachee Score","Glasgow scale"],"a":0,"e":":B Answer- (A) Pneumonia severity index [PSI] (B) CURB - 65 criteria Tools that objectively assess the risk of adverse outcomes are the Pneumonia Severity Index (PSI), a prognostic model used to identify patients at low risk of dying; and the CURB-65 criteria, a severity-of- illness score. The CURB-65 criteria include five variables: confusion (C); urea >7 mmol/L (U); respiratory rate 30/min (R); blood pressure, systolic \"90 mmHg or diastolic\" 60 mmHg (B); and age 65 years (65).","pyqMatches":[{"year":"2016","no":1082,"q":"Tool/s which objectively asses the risk of adverse outcomes in a patient with pneumonia is/are","o":["Pneumonia severity index [PSI]","CURB - 65 criteria","Apachee Score","Glasgow scale"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2920, 'Medicine', 'Respiratory Medicine', 'Hard', 'Internal_Medicine', 481, '{"id":2920,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Hard","source":"Internal_Medicine","sourceNo":481,"q":"In ICU setting patients suffering from which respiratory pathology are at risk of CO2 narcosis?","o":["Pneumonia","Asthma","Emphysema","Bronchieactasis"],"a":2,"e":"Answer- C. Emphysema Hypoventilation syndrome occurs most frequently in patients with a history of chronic CO, retention who are receiving oxygen therapy for emphysema or chronic pulmonary disease. The elevated Paco, leading to CO, narcosis may have a direct anesthetic effect, and cerebral vasodilation from increased Paco, can lead to increased ICP","pyqMatches":[{"year":"2016","no":1084,"q":"In ICU setting patients suffering from which respiratory pathology are at risk of CO2 narcosis?","o":["Pneumonia","Asthma","Emphysema","Bronchieactasis"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2921, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 482, '{"id":2921,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":482,"q":"Inspiratory squeaks are the physical examination finding of","o":["Bronchiolitis","Pulmonary hypertension","Pneumonia","Pulmonary edema"],"a":0,"e":"Answer- A. Bronchiolitis ILD associated with inflammation but are less likely to be heard in the granulomatous lung diseases. Crackles may be present in the absence of radiographic abnormalities on the chest radiograph. Scattered late inspiratory high-pitched rhonchi—so-called inspiratory squeaks—are heard in patients with bronchiolitis. Cyanosis and clubbing of the digits occur in some patients with advanced disease.","pyqMatches":[{"year":"2016","no":1085,"q":"Inspiratory squeaks are the physical examination finding of","o":["Bronchiolitis","Pulmonary hypertension","Pneumonia","Pulmonary edema"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2922, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 483, '{"id":2922,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":483,"q":"Which of the following are the clinical abnormalities of uremia?","o":["Hyperphosphatemia","Uremic frost","Peptic ulcer","All the above"],"a":3,"e":"Answer- D. All the above Volume expasion (I) Hyperkalemia (I) Hyponatremia (1) Hyperphosphatemia (I)","pyqMatches":[{"year":"2016","no":1086,"q":"Which of the following are the clinical abnormalities of uremia?","o":["Hyperphosphatemia","Uremic frost","Peptic ulcer","All the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2923, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 484, '{"id":2923,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":484,"q":"Which type of Bartter''s syndrome is associated with mutations in barttin?","o":["Type 1","Type 2","Type 3","Type 4"],"a":3,"e":"Answer- D. Type 4 Bartter''s syndrome may result from mutations affecting any of five ion transport proteins in the TAL. The proteins affected include the apical loop diuretic-sensitive sodium-potassium-chloride co-transporter NKCC2 (type 1), the apical potassium channel ROMK (type 2), and the basolateral chloride channel C1C-Kb (type 3). Bartter''s type 4 results from mutations in barttin, an essential subunit of CIC-Ka and C1C-Kb that enables transport of the chloride channels to the cell surface. Barttin is also expressed in the inner ear; this accounts for the deafness invariably associated with Bartter''s type 4.","pyqMatches":[{"year":"2016","no":1087,"q":"Which type of Bartter''s syndrome is associated with mutations in barttin?","o":["Type 1","Type 2","Type 3","Type 4"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2924, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 485, '{"id":2924,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":485,"q":"Test used for screening for urinary tract infection is","o":["Nitrite test","Na nitropruss ide test","Paul Bunnel test","Fentons test"],"a":0,"e":"Answer- A. Nitrite Test Effective and rapid method used for screening urine for the presence of bacterial infection. Test is based on the fact that most bacteria present in the urine, have the capacity to reduce urine nitrate to nitrite.","pyqMatches":[{"year":"2016","no":1088,"q":"Test used for screening for urinary tract infection is","o":["Nitrite test","Na nitropruss ide test","Paul Bunnel test","Fentons test"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2925, 'Medicine', 'Nephrology', 'Hard', 'Internal_Medicine', 486, '{"id":2925,"subject":"Medicine","chapter":"Nephrology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":486,"q":"Patient with nephrotic syndrome has decreased amount of which antibody","o":["IgG","IgE","IgM","IgA"],"a":0,"e":"Answer- A. IgG The immunological abnormalities noted are very peculiar IgG antibody is decrease IgE and IgM antibody increase Reduced responses to PHA and Con A (Concanavalin A) Increase of beta microglobulinlevels Reduced production of IL 2 Increased production of vascular permeability and immunosuppressor factors by CD4 T cells and CD 8 T cells respectively.","pyqMatches":[{"year":"2016","no":1089,"q":"Patient with nephrotic syndrome has decreased amount of which antibody","o":["IgG","IgE","IgM","IgA"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2926, 'Medicine', 'Gastroenterology', 'Hard', 'Internal_Medicine', 487, '{"id":2926,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":487,"q":"RIFLE criteria is used for diagnosis of","o":["Acute kidney injury","Acute splenic injury","Acute liver injury","Acute bowel injury"],"a":0,"e":"Answer- A. Acute kidney injury The RIFLE criteria, defines threes increasing levels of severity of acute kidney injury on the basis of the increase in serum creatinine concentration or decrease in urine output.","pyqMatches":[{"year":"2016","no":1090,"q":"RIFLE criteria is used for diagnosis of","o":["Acute kidney injury","Acute splenic injury","Acute liver injury","Acute bowel injury"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2927, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 488, '{"id":2927,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":488,"q":"Hemodynamically important lesions of renal artery stenosis are predicted by renal artery velocities more than on Doppler ultrasound.","o":["100 cm/s","125 cm/s","150 cm/s","200 cm/s"],"a":3,"e":"Answer- D. 200 cm/s Renal artery velocities by Doppler ultrasound above 200 cm/s generally predict hemodynamically important lesions (above 60% vessel lumen occlusion), although treatment trials require velocity above 300 cm/s to avoid false positives. Renal resistive index has predictive value regarding the viability of the kidney. It remains operator- and institution- dependent.","pyqMatches":[{"year":"2016","no":1092,"q":"Hemodynamically important lesions of renal artery stenosis are predicted by renal artery velocities more than on Doppler ultrasound.","o":["100 cm/s","125 cm/s","150 cm/s","200 cm/s"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2928, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 489, '{"id":2928,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":489,"q":"Gitelman''s syndrome resembles the effects of which of the following drugs?","o":["Thiazide","Furosemide","Spironolactone","Amiloride"],"a":0,"e":"Answer- A. Thiazide Gitelman''s syndrome is due to mutations in the thiazide-sensitive Na-Cl co-transporter, NCCT, in the distal convoluted tubule (DCT). Defects in NCCT in Gitelman''s syndrome impair sodium and chloride reabsorption in the DCT and thus resemble the effects of thiazide diuretics. It remains unclear how this defect leads to severe magnesium wasting.","pyqMatches":[{"year":"2016","no":1093,"q":"Gitelman''s syndrome resembles the effects of which of the following drugs?","o":["Thiazide","Furosemide","Spironolactone","Amiloride"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2929, 'Medicine', 'Infectious Diseases', 'Moderate', 'Internal_Medicine', 490, '{"id":2929,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":490,"q":"Definition of complicated urinary tract infection is, the infection which fail to resolve or recur within week/s of standard therapy.","o":["1 week","2 weeks","3 weeks","4 weeks"],"a":1,"e":"Answer- B. 2 weeks Complicated urinary tract infections refers to the infections that fail to resolve or recur within 2 weeks of standard therapy. These are associated with bacteremia or sepsis and are assocated with periurethral abscess, obstructions and pyelonephritis","pyqMatches":[{"year":"2016","no":1095,"q":"Definition of complicated urinary tract infection is, the infection which fail to resolve or recur within week/s of standard therapy.","o":["1 week","2 weeks","3 weeks","4 weeks"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2930, 'Medicine', 'Hematology', 'Hard', 'Internal_Medicine', 491, '{"id":2930,"subject":"Medicine","chapter":"Hematology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":491,"q":"A patient presents with blunt trauma to abdomen. On investigations patient is found to have hepatic injury which has a ruptured subcapsular hematoma with active bleeding. What is the grade of liver injury?","o":["Grade I","Grade II","Grade III","Grade IV"],"a":2,"e":"Answer- C. Grade III","pyqMatches":[{"year":"2016","no":1096,"q":"A patient presents with blunt trauma to abdomen. On investigations patient is found to have hepatic injury which has a ruptured subcapsular hematoma with active bleeding. What is the grade of liver injury?","o":["Grade I","Grade II","Grade III","Grade IV"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2931, 'Medicine', 'Gastroenterology', 'Hard', 'Internal_Medicine', 492, '{"id":2931,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":492,"q":"Excellent predictor of mortality and morbidity in patients after hepatectomy is","o":["Serum lactate levels","Serum magnesium level","Serum iron level","Serum copper level"],"a":0,"e":"Answer- A. Serum lactate levels Hyperlactemia and hypophosphatemia are common derangements in patients undergoing liver resection. Gluconeogenesis carried out by the liver normally consumes 40- 60% of lactate. When the liver is damaged, stressed or resected, it produces lactate rather than metabolizing it. Due to the additive effects of lactate-containing intravenous solution, non-lactate containing solutions are recommended for postoperative use after hepatectomy.","pyqMatches":[{"year":"2016","no":1097,"q":"Excellent predictor of mortality and morbidity in patients after hepatectomy is","o":["Serum lactate levels","Serum magnesium level","Serum iron level","Serum copper level"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2932, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 493, '{"id":2932,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":493,"q":"Ascitic fluid SAAG < 1.1 what is the disease associated with","o":["Hepatic failure","Idiopathic portal fibrosis","Constrictive pericarditis","Peritoneal carcinomatosis"],"a":3,"e":"Answer- D. Peritoneal carcinomatosis Low albumin gradient (SAAG <1.1 g/dL) Peritoneal carcinomatosis Peritoneal tuberculosis Pancreatitis Serositis Nephrotic syndrome","pyqMatches":[{"year":"2016","no":1100,"q":"Ascitic fluid SAAG < 1.1 what is the disease associated with","o":["Hepatic failure","Idiopathic portal fibrosis","Constrictive pericarditis","Peritoneal carcinomatosis"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2933, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 494, '{"id":2933,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":494,"q":"Gene associated with the development of Peutz-Jeghers syndrome is","o":["STK 11","PTEN","KRAS","BRCA 1"],"a":0,"e":"Answer- A. STK 11 Germline heterozygous loss-of-function mutations in the gene STKil are present in approximately half of individuals with familial Peutz- Jeghers syndrome as well as a subset of patients with sporadic Peutz-Jeghers syndrome.","pyqMatches":[{"year":"2016","no":1102,"q":"Gene associated with the development of Peutz-Jeghers syndrome is","o":["STK 11","PTEN","KRAS","BRCA 1"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2934, 'Medicine', 'Miscellaneous', 'Hard', 'Internal_Medicine', 495, '{"id":2934,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Internal_Medicine","sourceNo":495,"q":"Right hand dominant patient presents with normal comprehension but speaks with short utterances of a few words at a time, comprised mostly of nouns. What is the most probable location of the lesion","o":["Left inferior frontal gyrus","Right inferior frontal gyrus","Left superior temporal gyrus","Right superior temporal gyrus"],"a":0,"e":"Answer- A. Left inferior frontal gyrus Patient has normal comprehension but speaks with short utterances of a few words at a time, comprised mostly of nouns. These findings are suggestive of brocas aphsia. It is seen in patients having affection of the inferior frontal gyrus of the dominant hemisphere. The patient is right handed so the left hemisphere, will the dominant one. Thus most probable location of the lesion is left inferior frontal gyrus.","pyqMatches":[{"year":"2016","no":1104,"q":"Right hand dominant patient presents with normal comprehension but speaks with short utterances of a few words at a time, comprised mostly of nouns. What is the most probable location of the lesion","o":["Left inferior frontal gyrus","Right inferior frontal gyrus","Left superior temporal gyrus","Right superior temporal gyrus"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2935, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 496, '{"id":2935,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":496,"q":"Pure word deafness is associated with","o":["Middle cerebral artery stroke","Posterior cerebral artery stroke","Vertebral artery aneurysm","Basilar artery aneurysm"],"a":0,"e":"Answer- A. Middle cerebral artery stroke The most common causes are either bilateral or left-sided middle cerebral artery (MCA) strokes affecting the superior temporal gyrus. The net effect of the underlying lesion is to interrupt the flow of information from the auditory association cortex to Wernicke''s area.","pyqMatches":[{"year":"2016","no":1105,"q":"Pure word deafness is associated with","o":["Middle cerebral artery stroke","Posterior cerebral artery stroke","Vertebral artery aneurysm","Basilar artery aneurysm"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2936, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 497, '{"id":2936,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":497,"q":"Global aphasia is seen due to","o":["Strokes involving entire middle cerebral artery distribution in left hemisphere","Strokes involving entire middle cerebral artery distribution in right hemisphere","Strokes involving entire posterior cerebral artery distribution in left hemisphere","Strokes involving entire posterior cerebral artery distribution in right hemisphere"],"a":0,"e":"Answer- A. Strokes involving entire middle cerebral artery distribution in left hemisphere This syndrome represents the combined dysfunction of Broca''s and Wernicke''s areas and usually results from strokes that involve the entire middle cerebral artery distribution in the left hemisphere. Related signs include right hemiplegia, hemisensory loss, and homonymous hemianopia.","pyqMatches":[{"year":"2016","no":1106,"q":"Global aphasia is seen due to","o":["Strokes involving entire middle cerebral artery distribution in left hemisphere","Strokes involving entire middle cerebral artery distribution in right hemisphere","Strokes involving entire posterior cerebral artery distribution in left hemisphere","Strokes involving entire posterior cerebral artery distribution in right hemisphere"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2937, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 498, '{"id":2937,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":498,"q":"Lambert Eaton syndrome true is","o":["It is a paraneoplastic syndrome associated with squamous cell carcinoma of lung","IgM antibodies against ligand gated calcium channels","There is increase in release of presynaptic acetylcholine","With continuous stimulation there is marked increase in amplitude of action potentials."],"a":3,"e":"Answer- D. With continuous stimulation there is marked increase in amplitude of action potentials. It is a paraneoplastic syndrome associated with cancer particularly small cell Ca of lung. It is a disorder of neuromuscular junction transmission (Presynaptic) These IgG autoantibodies against the voltage sensitive calcium channels reduce the number of functioning channels. This causes decrease in release of presynaptic acetylcholine. Symptoms Muscles of the trunk shoulder girdle, pelvic girdle and muscles of lower extremities (muscles of the proximal leg are the most commonly involved muscles) Often the first symptoms are difficulty in arising from a chair, climbing stairs and walking, the shoulder muscles are affected later on.","pyqMatches":[{"year":"2016","no":1107,"q":"Lambert Eaton syndrome true is","o":["It is a paraneoplastic syndrome associated with squamous cell carcinoma of lung","IgM antibodies against ligand gated calcium channels","There is increase in release of presynaptic acetylcholine","With continuous stimulation there is marked increase in amplitude of action potentials."],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2938, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 499, '{"id":2938,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":499,"q":"Which is not seen in Alzheimers disease","o":["Gradual development of forgetfulness","Defective visuospatial orientation","Depression","Sequence of neurological abnormalities follows a described order"],"a":3,"e":"Answer- D. Sequence of neurological abnormalities follows a described order The sequence of neurological disabilities may not follow any described order and one or another deficit may take preceedence but usually the disease preceedes in the following four observed patterns. 1) Korsakoff amnestic state 2) Dysnomia 3) Visuospatial orientation becomes defective 4) Paranoia and other personality changes","pyqMatches":[{"year":"2016","no":1108,"q":"Which is not seen in Alzheimers disease","o":["Gradual development of forgetfulness","Defective visuospatial orientation","Depression","Sequence of neurological abnormalities follows a described order"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2939, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 500, '{"id":2939,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":500,"q":"Which lobe is affected in the early course of alzheimers disease","o":["Frontal lobe","Parietal lobe","Medial temporal lobe","Lateral temporal lobe"],"a":2,"e":"Answer- C. Medial temporal lobe Structures of the medial temporal lobe, including hippocampus, entorhinal cortex and amygdala, are involved early in the course and are usually severely atrophied in the later stages.","pyqMatches":[{"year":"2016","no":1109,"q":"Which lobe is affected in the early course of alzheimers disease","o":["Frontal lobe","Parietal lobe","Medial temporal lobe","Lateral temporal lobe"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2940, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 501, '{"id":2940,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":501,"q":"Which is/are the usual first deformity/ies to be seen in CMT disease?","o":["Pes cavus","Club hand","Mannus valgus","Flexion deformity of knee"],"a":0,"e":"Answer- A. Pes cavus Charcot-Marie-Tooth (CMT) disease is the most common type of hereditary neuropathy. There is progressive muscle weakness and atrophy that usually begins in the first two decades of life. The first signs of the disease are usually pes cavus, foot deformities and scoliosis. There is slowly progressive weakness and wasting, first of the feet and legs and then of the hands. The most common form of CMT is type 1, a demyelinating neuropathy with autosomal dominant inheritance, mapped most commonly to the short arm of chromosome 17.","pyqMatches":[{"year":"2016","no":1110,"q":"Which is/are the usual first deformity/ies to be seen in CMT disease?","o":["Pes cavus","Club hand","Mannus valgus","Flexion deformity of knee"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2941, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 502, '{"id":2941,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":502,"q":"Huntingtons disease is commonly seen in age group between","o":["15 - 35 years","25 - 45 years","35 - 55 years","45 - 65 years"],"a":1,"e":"Answer- B. 25 - 45 years HD is a progressive, fatal, highly penetrant autosomal dominant disorder characterized by motor, behavioral, and cognitive dysfunction. Onset is typically between the ages of 25 and 45 years (range, 3-70 years) with a prevalence of 2-8 cases per 100,000 and an average age at death of 60 years. Huntigton''s disease is characterized by triad of Autosomal dominant inheritence Choreoathetosis Dementia","pyqMatches":[{"year":"2016","no":1111,"q":"Huntingtons disease is commonly seen in age group between","o":["15 - 35 years","25 - 45 years","35 - 55 years","45 - 65 years"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2942, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 503, '{"id":2942,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":503,"q":"Which cranial nerve is involved in Weber syndrome?","o":["II","III","IV","V"],"a":1,"e":"Answer- B. III Weber''s syndrome- Midbrain- Oculomotor nerve- Ipsilateral third- nerve palsy","pyqMatches":[{"year":"2016","no":1112,"q":"Which cranial nerve is involved in Weber syndrome?","o":["II","III","IV","V"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2943, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 504, '{"id":2943,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":504,"q":"Violent abnormal flinging movements which are irregular and affecting one side are called as -","o":["Chorea","Athetosis","Dystonia","Hemiballismus"],"a":3,"e":"Answer- D. Hemiballismus It is defined as the dysfunction in the implementation of appropriate targeting and velocity of intended movements, dysfunction of posture and abnormal involuntary movement, or the performance of normal appearing movements at inappropriate or unintended times.","pyqMatches":[{"year":"2016","no":1113,"q":"Violent abnormal flinging movements which are irregular and affecting one side are called as","o":["Chorea","Athetosis","Dystonia","Hemiballismus"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2944, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 505, '{"id":2944,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":505,"q":"Wernickes encephalopathy develops secondary to accumulation of which substrate?","o":["Glutamate","Aspartate","Lactate","Acetate"],"a":0,"e":"Answer- A. Glutamate Glutamate accumulates owing to impairment of a ketoglutamate dehydrogenase activity and in combination with energy deficiency may result in excitotoxic cell damage.","pyqMatches":[{"year":"2016","no":1114,"q":"Wernickes encephalopathy develops secondary to accumulation of which substrate?","o":["Glutamate","Aspartate","Lactate","Acetate"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2945, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 506, '{"id":2945,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":506,"q":"Which of the following clinical test when positive suggests presence of sensory ataxia?","o":["Romberg test","Adson test","Stinchfield test","Crossed SLR test"],"a":0,"e":"Answer- A. Romberg test The Romberg test is a test of the body''s sense of positioning (proprioception), which requires healthy functioning of the dorsal columns of the spinal cord. The Romberg test is used to investigate the cause of loss of motor coordination (ataxia). A positive Romberg test suggests that the ataxia is sensory in nature, that is, depending on loss of proprioception.","pyqMatches":[{"year":"2016","no":1115,"q":"Which of the following clinical test when positive suggests presence of sensory ataxia?","o":["Romberg test","Adson test","Stinchfield test","Crossed SLR test"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2946, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 507, '{"id":2946,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":507,"q":"Todds paralysis is experience following episode of","o":["Focal seizure","Generalised seizure","After correction of hyponatremia","After correction of hypokalemia"],"a":0,"e":"Answer- A. Focal seizure Focal seizures arise from a neuronal network either discretely localized within one cerebral hemisphere. The routine interictal (i.e., between seizures) electroencephalogram (EEG) in patients with focal seizures is often normal or may show brief discharges termed epileptiform spikes, or sharp waves. Second, patients may experience a localized paresis (Todd''s paralysis) for minutes to many hours in the involved region following the seizure.","pyqMatches":[{"year":"2016","no":1116,"q":"Todds paralysis is experience following episode of","o":["Focal seizure","Generalised seizure","After correction of hyponatremia","After correction of hypokalemia"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2947, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 509, '{"id":2947,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":509,"q":"Frontal lobe syndrome consists","o":["Euphoria","Indifference","Irritability","All the above"],"a":3,"e":"Answer- D. All the above Euphoria, indifference, disinhibition, and irritability are consequences of frontal lobe lesions. These emotional and behavioural disturbances are usually referred to as frontal lobe syndrome. Other features are decreased social concern, jocularity, facetiousness, coarseness, hyperkinesia, disinhibition, loss of social graces, inappropriate sexual advances, sexual exhibitionism, impulsiveness, restlessness, and grandiose delusions.","pyqMatches":[{"year":"2016","no":1118,"q":"Frontal lobe syndrome consists","o":["Euphoria","Indifference","Irritability","All the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2948, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 510, '{"id":2948,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":510,"q":"Flapping tremors are not seen in","o":["CO2 toxicity","Hypomagnesemia","Subarachnoid hemorrhage","Carbolic acid poisoning"],"a":3,"e":"Answer- D. Carbolic acid poisoning It is an important clinical sign It is not pathognomonic of any condition but it gives clue to serious underlying disease process. Flapping tremor is a motor disturbance marked by intermettent lapses of an assumed posture as a result of intermittency of sustained contraction of group of muscles.","pyqMatches":[{"year":"2016","no":1119,"q":"Flapping tremors are not seen in","o":["CO2 toxicity","Hypomagnesemia","Subarachnoid hemorrhage","Carbolic acid poisoning"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2949, 'Medicine', 'Neurology', 'Moderate', 'Internal_Medicine', 511, '{"id":2949,"subject":"Medicine","chapter":"Neurology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":511,"q":"Features which differentiate seizures from syncope include the following except","o":["No immediate precipitating factors like stress, valsalva, orthostatic hypotension","Immediate transition to unconciousness","Presence of cyanosis and frothing of mouth","Presence of premonitory symptoms like diaphoresis and tunneling of vision"],"a":3,"e":"Ans. D. Presence of premonitory symptoms like diaphoresis and tunneling of vision","pyqMatches":[{"year":"2016","no":1120,"q":"Features which differentiate seizures from syncope include the following except","o":["No immediate precipitating factors like stress, valsalva, orthostatic hypotension","Immediate transition to unconciousness","Presence of cyanosis and frothing of mouth","Presence of premonitory symptoms like diaphoresis and tunneling of vision"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2950, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 512, '{"id":2950,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":512,"q":"Fine tremors are found in which disorder","o":["Mercury poisoning","Excess smoking","Hypoglycemia","All the above"],"a":3,"e":"Answer- D. All the above Fine tremors are noted when a limb is held in an antigravity posture They are noted in situations of catecholamine excess such as anxiety states, thyrotoxicosis, hypoglycemia and in alcoholism and excess smoking. They are also noted after ingestion of drugs like caffeine, salbutamol, theophylline, amphetamine, tricyclic antidepressants, Lithium, valproate, steroids, and in mercury poisoning.","pyqMatches":[{"year":"2016","no":1121,"q":"Fine tremors are found in which disorder","o":["Mercury poisoning","Excess smoking","Hypoglycemia","All the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2951, 'Medicine', 'Miscellaneous', 'Hard', 'Internal_Medicine', 513, '{"id":2951,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Internal_Medicine","sourceNo":513,"q":"True about electrophoresis in patients of multiple myeloma","o":["M component spike is for the alpha globulins","Monoclonal antibody must be present at a concentration of at least 10 g/L [1.0 g/dL] to be accurately quantitated by electrophoresis","M component is IgM in 53% of the patients","M component is IgA in 25% of the patients"],"a":3,"e":"Answer- D. M component is IgA in 25% of the patients The immunoglobulins move heterogeneously in an electric field and form a broad peak in the gamma region. The y globulin region of the electrophoretic pattern is usually increased in the sera of patients with plasma cell tumors. There is a sharp spike in this region called an M component (M for monoclonal). The serum M component in multiple myeloma will be IgG in 53% of patients, IgA in 25%, and IgD in 1%; 20% ofMietits will have only light chains in serum and urine.","pyqMatches":[{"year":"2016","no":1122,"q":"True about electrophoresis in patients of multiple myeloma","o":["M component spike is for the alpha globulins","Monoclonal antibody must be present at a concentration of at least 10 g/L [1.0 g/dL] to be accurately quantitated by electrophoresis","M component is IgM in 53% of the patients","M component is IgA in 25% of the patients"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2952, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 514, '{"id":2952,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":514,"q":"All but one is true for beta thalassemia major","o":["Growth and development is impaired","Red cell count <4 x 10''2/L","Levels of HbA2 < 3.5%","Bone marrow iron is depleted"],"a":3,"e":"Answer- D. Bone marrow iron is depleted Anaemia Hb gm/dl- < 7 (severe) Increased HbF, HbA2 and absence of HbA. Severity of disease ++++ Growth and development impaired Splenomegaly ++++ Skeletal changes +++ Thalassemia facies B.M. Iron- decreased","pyqMatches":[{"year":"2016","no":1123,"q":"All but one is true for beta thalassemia major","o":["Growth and development is impaired","Red cell count <4 x 10''2/L","Levels of HbA2 < 3.5%","Bone marrow iron is depleted"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2953, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 515, '{"id":2953,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":515,"q":"Immune thrombocytopenic puprpura associated with","o":["Hepatitis A infection","Hepatitis B infection","Hepatitis C infection","Hepatitis D infection"],"a":2,"e":"Answer- C. Hepatitis C infection Immune thrombocytopenic purpura (ITP; also termed idiopathic thrombocytopenic purpura) is an acquired disorder in which there is immune-mediated destruction of platelets and possibly inhibition of platelet release from the megakaryocyte. ITP is termed secondary if it is associated with an underlying disorder; autoimmune disorders, particularly systemic lupus erythematosus (SLE), and infections, such as HIV and hepatitis C, are common causes.","pyqMatches":[{"year":"2016","no":1124,"q":"Immune thrombocytopenic puprpura associated with","o":["Hepatitis A infection","Hepatitis B infection","Hepatitis C infection","Hepatitis D infection"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2954, 'Medicine', 'Rheumatology', 'Moderate', 'Internal_Medicine', 516, '{"id":2954,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":516,"q":"Which of the following is not a cause of secondary Idiopathic thrombocytopenic purpura?","o":["Systemic lupus erythmatosus","Hepatitis C infection","Rheumatoid arthritis","HIV infection"],"a":2,"e":"Answer- C. Rheumatoid arthritis ITP is termed secondary if it is associated with an underlying disorder; autoimmune disorders, particularly systemic lupus erythematosus (SLE), and infections, such as HIV and hepatitis C, are common causes.","pyqMatches":[{"year":"2016","no":1125,"q":"Which of the following is not a cause of secondary Idiopathic thrombocytopenic purpura?","o":["Systemic lupus erythmatosus","Hepatitis C infection","Rheumatoid arthritis","HIV infection"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2955, 'Medicine', 'Miscellaneous', 'Hard', 'Internal_Medicine', 517, '{"id":2955,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Internal_Medicine","sourceNo":517,"q":"Drug/s used in management relapsed multiple myeloma is","o":["Bortezomib","Lenalidomide","Doxorubicin","All the above"],"a":3,"e":"Answer- D. All the above The combination of bortezomib and liposomal doxorubicin is active in relapsed myeloma. Thalidomide, if not used as initial therapy, can achieve responses in refractory cases. High-dose melphalan and stem cell transplant, if not used earlier, also have activity in patients with refractory disease.","pyqMatches":[{"year":"2016","no":1126,"q":"Drug/s used in management relapsed multiple myeloma is","o":["Bortezomib","Lenalidomide","Doxorubicin","All the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2956, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 518, '{"id":2956,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":518,"q":"Treatment of chronic phase of CML in pregnant women is -","o":["Imatinib","Leukapheresis","Spleenectomy","Interferon therapy"],"a":1,"e":"Answer- B. Leukapheresis Intensive leukapheresis may control the blood counts in chronic- phase CML; however, it is expensive and cumbersome. It is useful in emergencies where leukostasis-related complications such as pulmonary failure or cerebrovascular accidents are likely. Splenectomy was used in CML in the past because of the suggestion that evolution to the acute phase might occur in the spleen. Splenic radiation is used rarely to reduce the size of the spleen.","pyqMatches":[{"year":"2016","no":1127,"q":"Treatment of chronic phase of CML in pregnant women is","o":["Imatinib","Leukapheresis","Spleenectomy","Interferon therapy"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2957, 'Medicine', 'Hematology', 'Hard', 'Internal_Medicine', 519, '{"id":2957,"subject":"Medicine","chapter":"Hematology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":519,"q":"Which of the following drug/s can be used for immediate parenteral anticoagulation in patients with venous thromboembolism?","o":["Unfractioned heparin","Low molecular weight heparin","Fondaparinux","All the above"],"a":3,"e":"Answer- D.�All the above Immediately effective anticoagulation is initiated with a parenteral drug: unfractionated heparin (UFH), low-molecular-weight heparin (LMWH), or fondaparinux. One should use a direct thrombin inhibitor�argatroban, lepirudin, or bivalirudin�in patients with proven or suspected heparin-induced thrombocytopenia. Warfarin requires 5-7 days to achieve a therapeutic effect.","pyqMatches":[{"year":"2016","no":1128,"q":"Which of the following drug/s can be used for immediate parenteral anticoagulation in patients with venous thromboembolism?","o":["Unfractioned heparin","Low molecular weight heparin","Fondaparinux","All the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2958, 'Medicine', 'Gastroenterology', 'Hard', 'Internal_Medicine', 520, '{"id":2958,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":520,"q":"A patient presents with icterus, but there is no evidence of bilirubin in urine. What is the most likely cause of jaundice in this patient?","o":["Hemolysis","Gall stones","Carcinoma head of pancreas","Biliary atresia"],"a":0,"e":"Answer- A. Hemolysis Hemolysis and hyperbilirubinemia Increased destruction of erythrocytes leads to increased bilirubin turnover and unconjugated hyperbilirubinemia; the hyperbilirubinemia is usually modest in the presence of normal liver function. Therefore, hemolysis alone cannot result in a sustained hyperbilirubinemia of more than -68 umol/L (4 mg/dL). When hemolysis is the only abnormality in an otherwise healthy individual, the result is a purely unconjugated hyperbilirubinemia.","pyqMatches":[{"year":"2016","no":1129,"q":"A patient presents with icterus, but there is no evidence of bilirubin in urine. What is the most likely cause of jaundice in this patient?","o":["Hemolysis","Gall stones","Carcinoma head of pancreas","Biliary atresia"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2959, 'Medicine', 'Hematology', 'Easy', 'Internal_Medicine', 521, '{"id":2959,"subject":"Medicine","chapter":"Hematology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":521,"q":"True about sideroblastic anemia","o":["Severity of the disease depends on the residual erythroid ALA synthase activity","Prussian blue staining sideroblasts are observed","Pyridoxine supplementation can be used for treatment","All the above"],"a":3,"e":"Answer- D. All the above XLSA results from the deficient activity of the erythroid form of ALA- synthase and is associated with ineffective erythropoiesis, weakness, and pallor. Typically, males with XLSA develop refractory hemolytic anemia, pallor, and weakness during infancy. Peripheral blood smears reveal a hypochromic, microcytic anemia with striking anisocytosis, poikilocytosis, and polychromasia; the leukocytes and platelets appear normal. A variety of Prussian blue-staining sideroblasts are observed. Levels of urinary porphyrin precursors and of both urinary and fecal porphyrins are normal.","pyqMatches":[{"year":"2016","no":1130,"q":"True about sideroblastic anemia","o":["Severity of the disease depends on the residual erythroid ALA synthase activity","Prussian blue staining sideroblasts are observed","Pyridoxine supplementation can be used for treatment","All the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2960, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 522, '{"id":2960,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":522,"q":"Massive transfusion is defined as transfusion of","o":["10/ 24 or more red cell products in hours.","5/12 or more red cell products in hours.","10/48 or more red cell products in hours.","5/24or more red cell products in hours."],"a":0,"e":"Answer: A 10/ 24 or more red cell products in hours. Various definitions of massive blood transfusion (MBT) have been published in the medical literature such as: Replacement of one entire blood volume within 24 h Transfusion of >10 units of packed red blood cells (PRBCs) in 24 h Transfusion of >4 units of PRBCs in 1 h when on-going need is foreseeable","pyqMatches":[{"year":"2016","no":1131,"q":"Massive transfusion is defined as transfusion of","o":["10/ 24 or more red cell products in hours.","5/12 or more red cell products in hours.","10/48 or more red cell products in hours.","5/24or more red cell products in hours."],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2961, 'Medicine', 'Hematology', 'Hard', 'Internal_Medicine', 523, '{"id":2961,"subject":"Medicine","chapter":"Hematology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":523,"q":"Which is the most common cause of thrombocytopenia in an ICU patient?","o":["Sepsis","Bone marrow failure","ITP","Drug induced"],"a":0,"e":"Answer- A. Sepsis Thrombocytopenia is a common laboratory abnormality that has been associated with adverse outcomes in ICU patients. Thrombocytopenia is defined as platelet count < 150 X 103 cells / mcL. Common causes of thrombocytopenia in ICU patients: Sepsis Disseminated intravascular coagulation Consumption (eg, major trauma, cardiopulmonary bypass) Dilution (with massive transfusion) Myelosuppressive chemotherapy Mechanical circulatory support devices (eg, intra-aortic balloon pump) Less common but important causes of thrombocytopenia that should not be missed: Heparin-induced thrombocytopenia Hemophagocytic syndrome Uncommon causes of thrombocytopenia that develop during ICU admission Drug-induced thrombocytopenia (other than heparin or cytotoxic chemotherapy) Leukemia, myelodysplasia, aplastic anemia, etc, unless abnormalities were already present before ICU admission","pyqMatches":[{"year":"2016","no":1132,"q":"Which is the most common cause of thrombocytopenia in an ICU patient?","o":["Sepsis","Bone marrow failure","ITP","Drug induced"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2962, 'Medicine', 'Miscellaneous', 'Hard', 'Internal_Medicine', 524, '{"id":2962,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Internal_Medicine","sourceNo":524,"q":"What percentage of Multiple myeloma patients have vertebral involvement?","o":["22%","44%","66%","88%"],"a":2,"e":"Answer- C. 66% Bone lesions are most common in the vertebral column. The following distribution was seen in a large series of cases: Vertebral column → 66% Ribs- 44% Skull → 4% Pelvis → 28% Femur → 28% Clavicle → 10%","pyqMatches":[{"year":"2016","no":1133,"q":"What percentage of Multiple myeloma patients have vertebral involvement?","o":["22%","44%","66%","88%"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2963, 'Medicine', 'Hematology', 'Hard', 'Internal_Medicine', 525, '{"id":2963,"subject":"Medicine","chapter":"Hematology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":525,"q":"Multiagent chemotherapy induces remission in of the patients of acute myelogenous leukemia","o":["65 - 70","75 - 80","85 - 90","95 - 100"],"a":2,"e":"Answer- C.�85 - 90 Aggressive multiagent chemotherapy is successful in inducing remission in approximately 85-90% of patients. Prognostic features [t(8;21); t(15;17); inv(16); APL] and improved outcome with chemotherapy, matched sibling stem cell transplantation is recommended only after a relapse Matched-sibling bone marrow or stem cell transplantation after remission achieves long-term disease-free survival in about two thirds of patients.","pyqMatches":[{"year":"2016","no":1134,"q":"Multiagent chemotherapy induces remission in of the patients of acute myelogenous leukemia","o":["65 - 70","75 - 80","85 - 90","95 - 100"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2964, 'Medicine', 'Endocrinology', 'Hard', 'Internal_Medicine', 526, '{"id":2964,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":526,"q":"HbA1C criteria for a patient to be diagnosed with diabetes mellitus is","o":[">4.5%",">5.5%",">6.5%",">7.5%"],"a":2,"e":"Answer- C. >6.5% Fasting plasma glucose > (126 mg/dl) Two hour plasma glucose > (200mg/d1) during an oral GTT A/C > 6.5%","pyqMatches":[{"year":"2016","no":1137,"q":"HbA1C criteria for a patient to be diagnosed with diabetes mellitus is","o":[">4.5%",">5.5%",">6.5%",">7.5%"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2965, 'Medicine', 'Endocrinology', 'Moderate', 'Internal_Medicine', 527, '{"id":2965,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":527,"q":"Which of the following is not true about the development of thyroid tumors in nodular goiter?","o":["Prevalence of thyroid carcinoma ranges between 5-15% in the patients with multinodular goiter","Papillary carcinoma is the most common carcinoma developed in patients with nodular goiter","Both benign and malignant neoplasms can be seen in patients with nodular goiter","The risk of development of carcinoma is not correlated with the level of TSH"],"a":3,"e":"Answer- D. The risk of development of carcinoma is not correlated with the level of TSH Thyroid tumors both benign and malignant can be seen in colloid goiter with both solitary and multiple nodules. The prevalence of thyroid carcinoma ranges from 5 – 15% in multinodular goiter and 8 – 17% in solitary colloid nodules. The prevalence in higher in men compared to women and usually occurs in older age group. The most common malignant tumor arising in mutinodular goiter is papillary carcinoma. Other like follicular carcinoma, hurthle cell carcinoma and medullary carcinoma are also encountered","pyqMatches":[{"year":"2016","no":1139,"q":"Which of the following is not true about the development of thyroid tumors in nodular goiter?","o":["Prevalence of thyroid carcinoma ranges between 5-15% in the patients with multinodular goiter","Papillary carcinoma is the most common carcinoma developed in patients with nodular goiter","Both benign and malignant neoplasms can be seen in patients with nodular goiter","The risk of development of carcinoma is not correlated with the level of TSH"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2966, 'Medicine', 'Endocrinology', 'Hard', 'Internal_Medicine', 528, '{"id":2966,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":528,"q":"Indication for giving liothyronine as therapeutic management is","o":["Resistant depression","Social phobia","Alzheimers disease","Cataplexy"],"a":0,"e":"Answer- A. Resistant depression It is the synthetic levorotatory isomer of triiodothyronine (T3). Liothyronine is the most broadly used thyroid hormone for treatment of depression. Liothyronine is used to accelerate the response to tricyclic antidepressants particularly in women. It is known to augment response to antidepressants in patients with mood disorders, in those who failed to respond to a tricyclic antidepressant trialie. In patients with resistant depression.","pyqMatches":[{"year":"2016","no":1141,"q":"Indication for giving liothyronine as therapeutic management is","o":["Resistant depression","Social phobia","Alzheimers disease","Cataplexy"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2967, 'Medicine', 'Endocrinology', 'Hard', 'Internal_Medicine', 529, '{"id":2967,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":529,"q":"Medical management of hyperparathyroidism includes which of the following?","o":["Bisphosphonates","Calcitonin","Plicamycin","All the above"],"a":3,"e":"Answer- D. All the above Expansion of intravascular volume, administration of loop diuretics, pharmacotherapy which reduces osteoclastic bone resorption (like Bisphosphonates, Calcitonin, and Plicamycin) are useful in the medical management of hyperparathyroidism.","pyqMatches":[{"year":"2016","no":1142,"q":"Medical management of hyperparathyroidism includes which of the following?","o":["Bisphosphonates","Calcitonin","Plicamycin","All the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2968, 'Medicine', 'Endocrinology', 'Moderate', 'Internal_Medicine', 530, '{"id":2968,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":530,"q":"Which of the following causes of hypercalcemia is not associated with high bone turnover?","o":["Hyperthyroidism","Vitamin A intoxication","Vitamin D intoxication","Thiazides"],"a":2,"e":"Answer- C. Vitamin D intoxication Vitamin D related Vitamin D intoxication Increased 1, 25 (OH)2D eg. Sarcoidosis Idiopathic hypercalcemia of infancy Associated high bone turnover Hyperthyroidism Immobilization Thiazides Vitamin A intoxication","pyqMatches":[{"year":"2016","no":1143,"q":"Which of the following causes of hypercalcemia is not associated with high bone turnover?","o":["Hyperthyroidism","Vitamin A intoxication","Vitamin D intoxication","Thiazides"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2969, 'Medicine', 'Gastroenterology', 'Moderate', 'Internal_Medicine', 531, '{"id":2969,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":531,"q":"Fasting hypoglycemia is caused by the following except","o":["Alcohol intake","Pentamidine therapy","Renal insufficiency","Chronic pancreatitis"],"a":3,"e":"Answer- D. Chronic pancreatitis Inappropriate (High) Insulin Level Insulin reaction in patients with diabetes - This is the most common cause of hypoglycemia, due to an imbalance between insulin supply and insulin requirements. Insulin secretagogue overdose in type 2 diabetes patients - Insulin secretagogues are oral hypoglycemic agents that work by stimulating insulin release from beta islet cells and, herefore, have the potential to cause hypoglycemia. Sulfonylureas (the most commonly prescribed type of these medications) are cleared by the kidney, so elderly patients with compromised renal function are at risk for developing hypoglycemia while on these agents. Factitious hypoglycemia (self induced or inadvertent) Autoimmune hypoglycemia Pentamidine - Pentamidine used for treatment/prophylaxis of PCP in patients with AIDS can cause hypoglycemia by direct injury to the beta islet cells causing hyperinsulinemia. Excess Insulin Secretion (Insulinoma)","pyqMatches":[{"year":"2016","no":1144,"q":"Fasting hypoglycemia is caused by the following except","o":["Alcohol intake","Pentamidine therapy","Renal insufficiency","Chronic pancreatitis"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2970, 'Medicine', 'Endocrinology', 'Easy', 'Internal_Medicine', 532, '{"id":2970,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":532,"q":"Diabetes insipidus is said to be present when","o":["> 30ml/hr urine output in 24 hrs and < 260 mosml/L osmolarity","> 40ml/hr urine output in 24 hrs and < 280 mosml/L osmolarity","> 50ml/hr urine output in 24 hrs and < 300 mosml/L osmolarity","> 60ml/hr urine output in 24 hrs and < 320 mosml/L osmolarity"],"a":2,"e":"Answer- C. > 50ml/hr urine output in 24 hrs and < 300 mosml/L osmolarity Decreased secretion or action of arginine vasopressin usually manifests as diabetes insipidus, a syndrome characterized by the production of abnormally large volumes of dilute urine. DI must be differentiated from other etiology of polyuria. The test should be started in the morning with careful supervision to avoid dehydration. Bodyweight, plasma osmolality, serum sodium, and urine volume and osmolality should be measured hourly. The test should be stopped when body weight decreases by 5% or plasma osmolality/sodium exceed the upper limit of normal. The 24-hour urine volume is >50 ml/kg body weight or urine osmolality Measurement of AVP levels before and after fluid deprivation may be helpful to distinguish central and nephrogenic DI. Occasionally, hypertonic saline infusion may be required if fluid deprivation does not achieve the requisite level of hypertonic dehydration, but this should be administered with caution.","pyqMatches":[{"year":"2016","no":1145,"q":"Diabetes insipidus is said to be present when","o":["> 30ml/hr urine output in 24 hrs and < 260 mosml/L osmolarity","> 40ml/hr urine output in 24 hrs and < 280 mosml/L osmolarity","> 50ml/hr urine output in 24 hrs and < 300 mosml/L osmolarity","> 60ml/hr urine output in 24 hrs and < 320 mosml/L osmolarity"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2971, 'Medicine', 'Respiratory Medicine', 'Moderate', 'Internal_Medicine', 533, '{"id":2971,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":533,"q":"Chronic adrenal insufficiency is caused by the following organisms except","o":["Mycobacterium tubercle","Histoplasma capsulatum","Coccidioides immitis","Mycobacterium bovis"],"a":3,"e":"Answer- D. Mycobacterium bovis Infections, particularly tuberculosis and those produced by fungi, cause primary chronic adrenocortical insufficiency. When present, tuberculous adrenalitis is usually associated with active infection in other sites, particularly in the lungs and genitourinary AIDS sufferers are at risk for developing adrenal insufficiency from several infectious (cytomegalovirus, Mycobacterium aviumintracellulare) and noninfectious (Kaposi sarcoma) complications.","pyqMatches":[{"year":"2016","no":1146,"q":"Chronic adrenal insufficiency is caused by the following organisms except","o":["Mycobacterium tubercle","Histoplasma capsulatum","Coccidioides immitis","Mycobacterium bovis"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2972, 'Medicine', 'Endocrinology', 'Moderate', 'Internal_Medicine', 534, '{"id":2972,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":534,"q":"Which of the following is not a feature of myxedema coma?","o":["Reduced level of consciousness and seizures with other features of hypothyroidism is seen","Hypoventilation leading to hypoxia and hypercapnia","Levothyroxine can be given via intravenous and nasogastric route","Levothyroxine should not be used in the management"],"a":3,"e":"Answer- D. Levothyroxine should not be used in the management Myxedema coma is defined as severe hypothyroidism leading to decreased mental status, hypothermia, and other symptoms of hypothyroidism. Reduced level of consciousness, sometimes associated with seizures may also be seen. Factors that predispose to myxedema coma include cold exposure, trauma, infection, and administration of narcotics. Therapy for myxedema coma should include levothyroxine (500 μg) as a single IV bolus followed by daily treatment with levothyroxine (50–100 μg/d), along with hydrocortisone (50 mg every 6 h) for impaired adrenal reserve, ventilatory support, space blankets, and treatment of precipitating factors.","pyqMatches":[{"year":"2016","no":1147,"q":"Which of the following is not a feature of myxedema coma?","o":["Reduced level of consciousness and seizures with other features of hypothyroidism is seen","Hypoventilation leading to hypoxia and hypercapnia","Levothyroxine can be given via intravenous and nasogastric route","Levothyroxine should not be used in the management"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2973, 'Medicine', 'Endocrinology', 'Easy', 'Internal_Medicine', 535, '{"id":2973,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":535,"q":"Acute adrenal insufficiency can present as","o":["Acute abdomen with abdominal tenderness, nausea,vomiting and fever","Neurologic disease with decreased responsiveness progressing to stupor and coma","Hypovolemic shock","All of the above"],"a":3,"e":"Answer- D. All of the above Postural hypotension may progress to hypovolemic shock. Adrenal insufficiency may mimic features of acute abdomen with abdominal tenderness, nausea, vomiting, and fever. In some cases, the primary presentation may resemble neurologic disease, with decreased responsiveness, progressing to stupor and coma. An adrenal crisis can be triggered by an intercurrent illness, surgical or other stress, or increased glucocorticoid inactivation (e.g., hyperthyroidism).","pyqMatches":[{"year":"2016","no":1148,"q":"Acute adrenal insufficiency can present as","o":["Acute abdomen with abdominal tenderness, nausea,vomiting and fever","Neurologic disease with decreased responsiveness progressing to stupor and coma","Hypovolemic shock","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2974, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 536, '{"id":2974,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":536,"q":"Hypotonic solution given to correct","o":["Dehydration secondary to diuretic therapy","Diabetic ketoacidosis","Hyperosmolar, hyperglycemic nonketotic syndrome","All the above"],"a":3,"e":"Answer- D. All the above Hypotonic solution has osmolarity lower than seum osmolarity. When a patient receives hypotonic solution, fluid shifts out of the blood vessels and into the cells and interstitial spaces, where osmolarity is higher. Hypotonic solution hydrates cells while reducing fluid in the circulatory system. Indications Dehydration secondary to diuretic therapy. Diabetic ketoacidosis Hyperosmolar, hyperglycemic nonketotic syndrome Examples of hypotonic solutions: half normal saline, 0.33% sodium chloride, dextrose 2.5% in water, dextrose 2.5%.","pyqMatches":[{"year":"2016","no":1150,"q":"Hypotonic solution given to correct","o":["Dehydration secondary to diuretic therapy","Diabetic ketoacidosis","Hyperosmolar, hyperglycemic nonketotic syndrome","All the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2975, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 537, '{"id":2975,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":537,"q":"All of the following are causes of acute hyponatremia except","o":["Glycine irrigation in TURP","Recent institution of thiazide therapy","MDMA ingestion","Liquorice ingestion"],"a":3,"e":"Answer- D. Liquorice ingestion causes of hyponatremia Iatrogenic Postoperative: premenopausal women Hypotonic fluids with causes of 1'' vasopressin Glycine irrigation: TURP, uterine surgery Colonoscopy preparation Recent institution of thiazides Polydipsia MDMA ingestion Exercise-induced Multifactorial, e.g., thiazide and polydipsia","pyqMatches":[{"year":"2016","no":1151,"q":"All of the following are causes of acute hyponatremia except","o":["Glycine irrigation in TURP","Recent institution of thiazide therapy","MDMA ingestion","Liquorice ingestion"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2976, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 538, '{"id":2976,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":538,"q":"Respiratory acidosis is recognized primarily by increase in","o":["Pa02","PaCO2","HCO3","None of the above"],"a":1,"e":"Answer- B. PaCO2 Respiratory acidosis occurs when there is accumulation of CO2 due to type II respiratory failure.it can also occur due to severe pulmonary disease, respiratory muscle fatigue, or abnormalities in ventilatory control and is recognized by an increase in Paco2 and decrease in pH This results in a rise in the PCO2, with a compensatory increase in plasma bicarbonate concentration, particularly when the disorder is of long duration and the kidney has fully developed its capacity for increased acid excretion","pyqMatches":[{"year":"2016","no":1153,"q":"Respiratory acidosis is recognized primarily by increase in","o":["Pa02","PaCO2","HCO3","None of the above"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2977, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 539, '{"id":2977,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":539,"q":"Which of the following drug administration is not associated with hypomagnesemia?","o":["Cisplatin","Valproate","Foscarnet","Cetuximab"],"a":1,"e":"Answer- B. Valproate Drugs causing hypomagnesemia Ethanol Diuretics (loop, thiazide, osmotic) Cisplatin Pentamidine, foscarnetCyclosporine Amino glycosides, amphotericin B Cetuximab","pyqMatches":[{"year":"2016","no":1154,"q":"Which of the following drug administration is not associated with hypomagnesemia?","o":["Cisplatin","Valproate","Foscarnet","Cetuximab"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2978, 'Medicine', 'Miscellaneous', 'Hard', 'Internal_Medicine', 540, '{"id":2978,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Internal_Medicine","sourceNo":540,"q":"Dose of benzathaine penicillin G to be given in patients of latent syphilis in patients without penicillin allergy and normal CSF findings is","o":["0.6mU IM / week for 3 weeks","1.2mU IM / week for 3 weeks","2.4mU IM / week for 3 weeks","4.8mU IM / week for 3 weeks"],"a":2,"e":"Answer- C. 2.4mU IM / week for 3 weeks Primary, secondary, or early latent- CSF normal or not examined: Penicillin G benzathine (single dose of 2.4 mU IM) CSF abnormal -Treat as neurosyphilis Late latent (or latent of uncertain duration), cardiovascular, or benign tertairy- CSF normal or not examined: Penicillin G benzathine (2.4 mU IM weekly for 3 weeks). CSF abnormal : Treat as neurosyphilis","pyqMatches":[{"year":"2016","no":1155,"q":"Dose of benzathaine penicillin G to be given in patients of latent syphilis in patients without penicillin allergy and normal CSF findings is","o":["0.6mU IM / week for 3 weeks","1.2mU IM / week for 3 weeks","2.4mU IM / week for 3 weeks","4.8mU IM / week for 3 weeks"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2979, 'Medicine', 'Infectious Diseases', 'Hard', 'Internal_Medicine', 541, '{"id":2979,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Hard","source":"Internal_Medicine","sourceNo":541,"q":"SARS infection case fatality rate of >50% is observed in patients of which age group?","o":["< 20 yrs","20 - 40 years","40 - 60 years","> 65 years"],"a":3,"e":"Answer- D. > 65 years The case fatality rate from SARS-CoV infection during the 2003 outbreak was 10-17%. No pediatric deaths were reported. The estimated case fatality rate according to age varied from <1% for those younger than 20 year of age to >50% for those older than 65 yr of age.","pyqMatches":[{"year":"2016","no":1156,"q":"SARS infection case fatality rate of >50% is observed in patients of which age group?","o":["< 20 yrs","20 - 40 years","40 - 60 years","> 65 years"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2980, 'Medicine', 'Infectious Diseases', 'Hard', 'Internal_Medicine', 542, '{"id":2980,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Hard","source":"Internal_Medicine","sourceNo":542,"q":"Which of the following corroborates to the presence of clostridium difficle infection in patients taking antibiotics for another cause?","o":["Diarrhoea unformed stools per 12 h for 2 days with no other recognized cause","Diarrhoea unformed stools per 24 h for 2 days with no other recognized cause","Diarrhoea unformed stools per 24 h for 3 days with no other recognized cause","Diarrhoea unformed stools per 24 h for 4 days with no other recognized cause"],"a":1,"e":"Answer- B. Diarrhoea unformed stools per 24 h for 2 days with no other recognized cause Diarrhoea unformed stools per 24 h for 2 days with no other recognized cause. Toxin A or B detected in the stool by PCR or culture. Pseudomembranes seen in colon by endoscopy.","pyqMatches":[{"year":"2016","no":1157,"q":"Which of the following corroborates to the presence of clostridium difficle infection in patients taking antibiotics for another cause?","o":["Diarrhoea unformed stools per 12 h for 2 days with no other recognized cause","Diarrhoea unformed stools per 24 h for 2 days with no other recognized cause","Diarrhoea unformed stools per 24 h for 3 days with no other recognized cause","Diarrhoea unformed stools per 24 h for 4 days with no other recognized cause"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2981, 'Medicine', 'Neurology', 'Moderate', 'Internal_Medicine', 543, '{"id":2981,"subject":"Medicine","chapter":"Neurology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":543,"q":"Following are the features of neuropathy associated with varicella-zoster infection except","o":["Persistent infection in neurons of sensory ganglia","With reactivation virus transported along nerves to skin","Shingles are distributed along motor dermatomes","Intranuclear inclusions are not found in peripheral nervous system"],"a":2,"e":"Answer- C. Shingles are distributed along motor dermatomes Varicella-zoster is one of the most common viral infections of the peripheral nervous system. Following chickenpox, a latent infection persists within neurons of sensory ganglia. If the virus is reactivated, sometimes many years later, it may be transported along the sensory nerves to the skin. Here it infects keratinocytes, leading to a painful, vesicular skin eruption (shingles) in a distribution that follows sensory dermatomes Most common is the involvement of thoracic or trigeminal nerve dermatomes.","pyqMatches":[{"year":"2016","no":1158,"q":"Following are the features of neuropathy associated with varicella- zoster infection except","o":["Persistent infection in neurons of sensory ganglia","With reactivation virus transported along nerves to skin","Shingles are distributed along motor dermatomes","Intranuclear inclusions are not found in peripheral nervous system"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2982, 'Medicine', 'Infectious Diseases', 'Moderate', 'Internal_Medicine', 544, '{"id":2982,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":544,"q":"Which of the following is not true about the epididymo¬orchitis of mumps?","o":["It is the most common manifestation of mumps infection","Testicular enlargement usually resolves in 1 week","Bilateral testicular involvement seen in 10 - 30% of cases","Sterility rarely develops in these patients"],"a":0,"e":"Answer- A. It is the most common manifestation of mumps infection Epididymo-orchitis is the second most common manifestation of mumps, developing in 15–30% of cases in postpubertal males. – Orchitis, characterized by a painful, tender, fever and enlarged testis, is bilateral in 10–30% of cases and resolves within 1 week. – Oophoritis (manifested by lower abdominal pain and vomiting) occurs in ~5% of women with mumps. – Sterility in mumps is rare.","pyqMatches":[{"year":"2016","no":1162,"q":"Which of the following is not true about the epididymo¬orchitis of mumps?","o":["It is the most common manifestation of mumps infection","Testicular enlargement usually resolves in 1 week","Bilateral testicular involvement seen in 10 - 30% of cases","Sterility rarely develops in these patients"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2983, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 545, '{"id":2983,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":545,"q":"Most common nerve affected in leprosy","o":["Posterior tibial","Ulnar","Median","Facial"],"a":0,"e":"Answer- A. Posterior tibial Leprosy affects peripheral mixed nerves and cutaneous nerves. The most common peripheral nerves affected in the order of frequency are the posterior tibial>ulnar> median> lateral popliteal> facial > radial","pyqMatches":[{"year":"2016","no":1163,"q":"Most common nerve affected in leprosy","o":["Posterior tibial","Ulnar","Median","Facial"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2984, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 546, '{"id":2984,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":546,"q":"Austrian syndrome is caused by which infection","o":["Staphylococcus aureus","Streptococcus pneumoniae","Staphylococcus epidermidis","Streptococcus viridans"],"a":1,"e":"Answer- B. Streptococcus pneumoniae Austrian syndrome is a medical condition first described by Robert Austrian in 1957. The classical triad consists of pneumonia, endocarditis, and meningitis, all caused by Streptococcus pneumoniae. It is associated with alcoholism, due to the presence of hyposplenia (reduced splenic functioning), and can be seen in males between 40 and 60 years old.","pyqMatches":[{"year":"2016","no":1166,"q":"Austrian syndrome is caused by which infection","o":["Staphylococcus aureus","Streptococcus pneumoniae","Staphylococcus epidermidis","Streptococcus viridans"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2985, 'Medicine', 'Respiratory Medicine', 'Moderate', 'Internal_Medicine', 547, '{"id":2985,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":547,"q":"Factors contributing to the development of complications in measles are the following except-","o":["Age group 5-20 years","Higher case fatality with overcrowding","Severe malnutrition","Lower serum retinol levels"],"a":0,"e":"Answer- A. Age group 5-20 years Complications of measles are largely attributable to the pathogenic effects of the virus on the respiratory tract and immune system. Morbidity and mortality from measles are greatest in patients younger than 5 yr of age (especially <1 yr of age) and older than 20 yr of age.","pyqMatches":[{"year":"2016","no":1167,"q":"Factors contributing to the development of complications in measles are the following except","o":["Age group 5-20 years","Higher case fatality with overcrowding","Severe malnutrition","Lower serum retinol levels"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2986, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 548, '{"id":2986,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":548,"q":"True about VHL syndrome is","o":["It is an autosomal recessive condition","Central nervous system is not involved","Regular screening for clear cell carcinoma of kidneys is essential","VHL is a growth promoter gene"],"a":2,"e":"Answer- C. Regular screening for clear cell carcinoma of kidneys is essential Von Hippel-Lindau disease (VHL) is a rare autosomal dominant disease characterized by abnormal angiogenesis with benign and malignant tumors that affect multiple tissues. The disease is inherited as a mutation in one allele of the VHL tumor-suppressor gene. Somatic mutation of the normal allele leads to retinal angiomas, central nervous system (CNS) hemangioblastomas, pheochromocytomas and multicentric clear cell cysts, hemangiomas, and adenomas of the kidney. The hi h risk of renal cell carcinoma mandates i eriodic surveillance usuall earl in adults b CT or MRI. Routine screening and awareness of the natural history of lesions has enabled renal-sparing approaches to disease management.","pyqMatches":[{"year":"2016","no":1168,"q":"True about VHL syndrome is","o":["It is an autosomal recessive condition","Central nervous system is not involved","Regular screening for clear cell carcinoma of kidneys is essential","VHL is a growth promoter gene"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2987, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 549, '{"id":2987,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":549,"q":"Tuberous sclerosis is caused by mutations in the following proteins","o":["Hamartin","Tuberin","Merlin","Ankyrin"],"a":0,"e":":B Answer- A. Hamartin & B. Tuberin It is caused by mutations in either the TSC1 gene, which maps to chromosome 9q34, and encodes a protein termed hamartin, or mutations in the TSC2 gene, which maps to chromosome 16p13.3 and encodes the tuberin protein. Hamartin forms a complex with tuberin, which inhibits cellular signaling through the mammalian target of rapamycin (mTOR), and acts as a negative regulator of the cell cycle. Patients with tuberous sclerosis have seizures, mental retardation, adenoma sebaceum (facial angiofibromas), shagreen patch, hypomelanotic macules, periungual fibromas, renal angiomyolipomas, and cardiac rhabdomyomas.","pyqMatches":[{"year":"2016","no":1169,"q":"Tuberous sclerosis is caused by mutations in the following proteins","o":["Hamartin","Tuberin","Merlin","Ankyrin"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2988, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 550, '{"id":2988,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":550,"q":"What characteristic finding of tuberous sclerosis is present at birth but not later in life?","o":["Cardiac rhabdomyosarcoma","Facial angiofibroma","Periungal fibroma","Renal angiomyolipoma"],"a":0,"e":"Answer- A. Cardiac rhabdomyosarcoma Patients with tuberous sclerosis have seizures, mental retardation, adenoma sebaceum (facial angiofibromas), shagreen patch, hypomelanotic macules, periungual fibromas, renal angiomyolipomas, and cardiac rhabdomyomas. Cardiac rhabdomyosarcomas can be present at birth in upto 80% of the infants with tuberous sclerosis. These involute in the first three years of life and completely disappear by adulthood","pyqMatches":[{"year":"2016","no":1170,"q":"What characteristic finding of tuberous sclerosis is present at birth but not later in life?","o":["Cardiac rhabdomyosarcoma","Facial angiofibroma","Periungal fibroma","Renal angiomyolipoma"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2989, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 551, '{"id":2989,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":551,"q":"Following is not true about epinephrine","o":["Has potent alpha and beta stimulating properties","It improves coronary perfusion pressure and myocardial blood flow","Increases cerebral blood flow during CPR","Routine use of high dose epinephrine during resuscitation is indicated"],"a":3,"e":"Answer- D. Routine use of high dose epinephrine during resuscitation is indicated Epinephrine (adrenaline) is an endogenous catecholamine with potent a- and 11-adrenergic stimulating properties. The adrenergic action (vasoconstriction) increases systemic and pulmonary vascular resistance. The resultant higher aortic diastolic blood pressure improves coronary perfusion pressure and myocardial blood flow even though it reduces global cardiac output during CPR. epinephrine also increases cerebral blood flow durin ood u uali CPR because peripheral vasoconstriction directs a greater proportion of flow to the cerebral circulation.However, epinephrine can decrease local cerebral microcirculatory blood flow at a time when global cerebral flow is increased.","pyqMatches":[{"year":"2016","no":1171,"q":"Following is not true about epinephrine","o":["Has potent alpha and beta stimulating properties","It improves coronary perfusion pressure and myocardial blood flow","Increases cerebral blood flow during CPR","Routine use of high dose epinephrine during resuscitation is indicated"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2990, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 552, '{"id":2990,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":552,"q":"Z track technique must be used for administration of","o":["Injection Iron Dextran deep IM","Injection Hydroxyzine hydrochloride deep IM","Injection Depomedroxyprogesterone iv","Injection erythromycin"],"a":0,"e":":B Answer- A. Injection Iron Dextran deep IM & B. Injection Hydroxyzine hydrochloride deep IM With intramuscular injections medications can leak upward into the subcutaneous tissues causing staining, bruising and significant pain for several weeks or longer with some medications. Nurses are encouraged to use the Z track technique (causing a needle track or pathway in the shape of Z) any time an intramuscular injection is given, to prevent leakage and associated pain. The Z track technique must be used whenever a deep intramuscular injection of iron dextran, and other irritating solutions such as hydroxyzine hydrochloride and several antipsychotic agents are given.","pyqMatches":[{"year":"2016","no":1172,"q":"Z track technique must be used for administration of","o":["Injection Iron Dextran deep IM","Injection Hydroxyzine hydrochloride deep IM","Injection Depomedroxyprogesterone iv","Injection erythromycin"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2991, 'Medicine', 'Gastroenterology', 'Moderate', 'Internal_Medicine', 553, '{"id":2991,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":553,"q":"In man what quantity of ethyl alcohol consumed daily for > 10 years increases the relative risk of development of alcoholic liver disease","o":["20g/d","40g/d","60g/d","80g/d"],"a":3,"e":"Answer- D. 80g/d 80g/day x 10+ yr.","pyqMatches":[{"year":"2016","no":1173,"q":"In man what quantity of ethyl alcohol consumed daily for > 10 years increases the relative risk of development of alcoholic liver disease","o":["20g/d","40g/d","60g/d","80g/d"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2992, 'Medicine', 'Hematology', 'Hard', 'Internal_Medicine', 554, '{"id":2992,"subject":"Medicine","chapter":"Hematology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":554,"q":"Which of the following antineoplastic agents is used in the management of Hodgkins lymphoma, non Hodgkins lymphoma and small cell carcinoma of lung?","o":["Cisplatin","Bleomycin","Paclitaxel","Doxorubicin"],"a":0,"e":"Answer- A. Cisplatin Cisplatin is used in the management of Hodgkins lymphoma, non Hodgkins lymphoma and small cell carcinoma of lung.","pyqMatches":[{"year":"2016","no":1175,"q":"Which of the following antineoplastic agents is used in the management of Hodgkins lymphoma, non Hodgkins lymphoma and small cell carcinoma of lung?","o":["Cisplatin","Bleomycin","Paclitaxel","Doxorubicin"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2993, 'Medicine', 'Respiratory Medicine', 'Moderate', 'Internal_Medicine', 555, '{"id":2993,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":555,"q":"Pierre robin syndrome following is true except","o":["Consists of micrognathia and cleft palate","Tongue is of normal size","Airway obstruction particularly during expiration","30 - 50% patients have Stickler syndrome"],"a":2,"e":"Answer C. Airway obstruction particularly during expiration Pierre Robin syndrome consists of micrognathia usually accompanied by a high arched or cleft palate. The tongue is usually of normal size, but the floor of the mouth is foreshortened. The air passages can become obstructed, particularly on inspiration, usually requiring treatment to prevent suffocation. The infant should be maintained in a prone or partially prone position so that the tongue falls forward to relieve respiratory obstruction. Some patients require tra- cheostomy. Mandibular distraction procedures in the neonate can improve mandibular size, enhance respiration, and facilitate oral feedings. Sufficient spontaneous mandibular growth can take place within a few months to relieve the potential airway obstruction. Often the growth of the mandible achieves a normal profile in 4-6 year.","pyqMatches":[{"year":"2016","no":1176,"q":"Pierre robin syndrome following is true except","o":["Consists of micrognathia and cleft palate","Tongue is of normal size","Airway obstruction particularly during expiration","30 - 50% patients have Stickler syndrome"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2994, 'Medicine', 'Hematology', 'Hard', 'Internal_Medicine', 556, '{"id":2994,"subject":"Medicine","chapter":"Hematology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":556,"q":"Mantle field radiation was used for management of -","o":["Hodgkins lymphoma","Mantle cell lymphoma","Multiple myeloma","Cervical carcinoma"],"a":0,"e":"Answer- A. Hodgkins lymphoma Mantle field radiation is a type of radiation treatment used for Hodgkin''s lymphoma The term ''mantle'' is derived from the name of a garment, much like a cloak, used many years back. The shape of the exposed area the radiation field has contours that resemble the shielding cloak. This type of large radiation field is not commonly used today.","pyqMatches":[{"year":"2016","no":1177,"q":"Mantle field radiation was used for management of","o":["Hodgkins lymphoma","Mantle cell lymphoma","Multiple myeloma","Cervical carcinoma"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2995, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 557, '{"id":2995,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":557,"q":"Alien limb syndrome seen in","o":["Post neurosurgical cases","Alzheimers disease","Creutzfeldt-Jakob disease","All the above"],"a":3,"e":"Answer- D. All the above Alien hand syndrome (AHS) is a condition in which a person experiences their limbs acting seemingly on their own, without control over the actions. The term is used for a variety of clinical conditions and most commonly affects the left hand. Alien hand syndrome is best documented in cases where a person has had the two hemispheres of their brain surgically separated, a procedure sometimes used to relieve the symptoms of extreme cases of epilepsy. It also occurs in some cases after brain surgery,stroke,infection, tumor, aneurysm and specific degenerative brain conditions such as Alzheimer''s disease and Creutzfeldt-Jakob disease.","pyqMatches":[{"year":"2016","no":1178,"q":"Alien limb syndrome seen in","o":["Post neurosurgical cases","Alzheimers disease","Creutzfeldt-Jakob disease","All the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2996, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 558, '{"id":2996,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":558,"q":"Osmolarity of Milk F-100 is","o":["399 mOsm/L","409 mOsm/L","419 mOsm/L","429 mOsm/L"],"a":2,"e":"Answer- C. 419 mOsm/L UNICEF and WHO prepared two formula diets by modification of the cows milk - Milk F-75 (starter 75 kcal/100 ml) and F-100 (followup 100 kcal/ 100 ml).","pyqMatches":[{"year":"2016","no":1179,"q":"Osmolarity of Milk F-100 is","o":["399 mOsm/L","409 mOsm/L","419 mOsm/L","429 mOsm/L"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2997, 'Medicine', 'Neurology', 'Moderate', 'Internal_Medicine', 559, '{"id":2997,"subject":"Medicine","chapter":"Neurology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":559,"q":"Which of the following drugs can cause seizures except?","o":["Lithium","Phencyclindine","INH","Ketorolac"],"a":3,"e":"Answer- D. Ketorolac Psychotropics Antidepressants Antipsychotics Lithium Drugs of abuse Amphetamine Cocaine Phencyclidine Methylphenidate Flumazenil","pyqMatches":[{"year":"2016","no":1180,"q":"Which of the following drugs can cause seizures except?","o":["Lithium","Phencyclindine","INH","Ketorolac"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2998, 'Medicine', 'Hematology', 'Easy', 'Internal_Medicine', 560, '{"id":2998,"subject":"Medicine","chapter":"Hematology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":560,"q":"Riboflavin deficiency causes","o":["Corneal vascularization","Anemia","Personality changes","All the above"],"a":3,"e":"Answer- D. All the above Riboflavin deficiency is manifested principally by lesions of the mucocutaneous surfaces of the mouth and skin. In addition to the mucocutaneous lesions, corneal vascularization, anemia, and personality changes have been described with riboflavin deficiency.","pyqMatches":[{"year":"2016","no":1181,"q":"Riboflavin deficiency causes","o":["Corneal vascularization","Anemia","Personality changes","All the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (2999, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 561, '{"id":2999,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":561,"q":"Soret band in which porphyrins absorb light lie at what wavelength of the spectrum of light?","o":["200nm","300nm","400nm","500nm"],"a":2,"e":"Answer- C. 400nm Due to this structure porphyrins avidly absorb light in a region near 400 nm of the light spectrum. This part of the light spectrum is called the Soret band.","pyqMatches":[{"year":"2016","no":1182,"q":"Soret band in which porphyrins absorb light lie at what wavelength of the spectrum of light?","o":["200nm","300nm","400nm","500nm"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3000, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 562, '{"id":3000,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":562,"q":"Which of the following is not seen after nerve transection?","o":["Morphologic pattern of wallerian degeneration","Myelin ovoids","Painful neuroma","Neuroma in continuity"],"a":3,"e":"Answer- D. Neuroma in continuity The morphologic hallmarks of axonal neuropathies produced by cutting a peripheral nerve, results in a prototypical pattern of injury described as Wallerian degeneration Within a day of injury, the distal axons begin to fragment and the associated myelin sheaths unravel and disintegrate into spherical structures (myelin ovoids). A failure of the outgrowing axons to find their distal target can produce a \"pseudotumor\" termed traumatic neuroma— a nonneoplastic haphazard whorled proliferation of axonal processes and associated Schwann cells that results in a painful nodule.","pyqMatches":[{"year":"2016","no":1183,"q":"Which of the following is not seen after nerve transection?","o":["Morphologic pattern of wallerian degeneration","Myelin ovoids","Painful neuroma","Neuroma in continuity"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3001, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 563, '{"id":3001,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":563,"q":"Reactive nitrogen species for killing of microbes are mainly derived from","o":["Elemental nitrogen [N3]","Nitric Oxide [NO]","Nitrogen Dioxide [NO2]","Nitrous Oxide [N20]"],"a":1,"e":"Answer- B. Nitric Oxide [NO] Killing of microbes is accomplished by reactive oxygen species (ROS, also called reactive oxygen intermediates) and reactive nitrogen species, mainly derived from nitric oxide (NO), and these as well as lysosomal enzymes destroy phagocytosed debris. This is the final step in the elimination of infectious agents and necrotic cells.","pyqMatches":[{"year":"2016","no":1184,"q":"Reactive nitrogen species for killing of microbes are mainly derived from","o":["Elemental nitrogen [N3]","Nitric Oxide [NO]","Nitrogen Dioxide [NO2]","Nitrous Oxide [N20]"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3002, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 564, '{"id":3002,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":564,"q":"During state of arousal in men relaxation of smooth muscle in corpus cavernosum is mainly caused by","o":["Acethycholine","Nitric oxide","Bicarbonate ions","Calcium"],"a":1,"e":"Answer- B. Nitric oxide Erectile dysfunction (ED) refers to the inability of men to attain and maintain an erect penis with sufficient rigidity to allow sexual intercourse. Nitric oxide (NO) released parasympathetic nonadrenergic noncholinergic (NANC) nerves andvascular endothelium is the major transmitter causing relaxation of smooth muscle in corpus cavernosum and blood vessels supplying it; ACh and PGs also play a role.","pyqMatches":[{"year":"2016","no":1185,"q":"During state of arousal in men relaxation of smooth muscle in corpus cavernosum is mainly caused by","o":["Acethycholine","Nitric oxide","Bicarbonate ions","Calcium"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3003, 'Medicine', 'Hematology', 'Moderate', 'Internal_Medicine', 565, '{"id":3003,"subject":"Medicine","chapter":"Hematology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":565,"q":"Which of the following genes if affected will sporadically cause Juvenile myeloid leukemia?","o":["NF1","PTEN","APC","SMAD2"],"a":0,"e":"Answer- A. NF1 NF1 - Neurobiastoma, juvenile myeloid leukemia","pyqMatches":[{"year":"2016","no":1186,"q":"Which of the following genes if affected will sporadically cause Juvenile myeloid leukemia?","o":["NF1","PTEN","APC","SMAD2"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3004, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 566, '{"id":3004,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":566,"q":"Chronic manifestations of Aspergillosis are not evident in which of the following organs?","o":["Skin","Brain","Lung","Eye"],"a":3,"e":"Answer- D. Eye Lung, sinus, brain, skin, heart,","pyqMatches":[{"year":"2016","no":1187,"q":"Chronic manifestations of Aspergillosis are not evident in which of the following organs?","o":["Skin","Brain","Lung","Eye"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3005, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 567, '{"id":3005,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":567,"q":"Oculogyric crisis is known to be produced by all of the following drugs except","o":["Trifluoperazine","Atropine","Perchlorperazine","Perphenazine"],"a":1,"e":"Answer- B. Atropine Oculogyric crisis is one of the manifestations seen in acute dystonic reaction (acute muscular dystonia). Other manifestations are facial grimacing, torticollis, locked jaw, abnormal contraction of spinal muscles (opisthotonus). It occurs within 1 to 5 days of antipsychotic therapy. Trifluperazine, perchlorperazine and perphenazine are antipsychotic","pyqMatches":[{"year":"2016","no":1189,"q":"Oculogyric crisis is known to be produced by all of the following drugs except","o":["Trifluoperazine","Atropine","Perchlorperazine","Perphenazine"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3006, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 568, '{"id":3006,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":568,"q":"Which metabolic derangement is seen in pregnancy?","o":["Metabolic acidosis","Metabolic alkalosis","Respiratory acidosis","Respiratory alkalosis"],"a":3,"e":"Answer- D. Respiratory alkalosis Hyperventilation in pregnancy will lead to respiratory alkalosis. The hyperventilation that occur during pregnancy is probably due in part to progesterone stimulating the centre. Lung volume changes and altered compliance may also contribute. The effect is a chronic respiratory alkalosis which is compensated by renal excretion of bicarbonate.","pyqMatches":[{"year":"2014","no":1241,"q":"Which metabolic derangement is seen in pregnancy?","o":["Metabolic acidosis","Metabolic alkalosis","Respiratory acidosis","Respiratory alkalosis"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3007, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 569, '{"id":3007,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":569,"q":"Which of the following is not used for investigation of fat malabsorption","o":["13C Trioctanoin","13C Triolein","13C Tripalmitin","13C Triclosan"],"a":3,"e":"Answer- D. 13C Triclosan Tests used for fat malabsorption","pyqMatches":[{"year":"2014","no":1244,"q":"Which of the following is not used for investigation of fat malabsorption","o":["13C Trioctanoin","13C Triolein","13C Tripalmitin","13C Triclosan"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3008, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 570, '{"id":3008,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":570,"q":"Vitamin E deficiency causes","o":["Hemorrhagic stroke","Cardiac failure","Ataxia","Megalablastic anemia"],"a":2,"e":"Answer- C. Ataxia Clinical Manifestations Axonal degeneration Hemolytic anaemia Peripheral neuropathy Spinocerebellar ataxia Dry skin Thrombocytosis Ataxia","pyqMatches":[{"year":"2014","no":1248,"q":"Vitamin E deficiency causes","o":["Hemorrhagic stroke","Cardiac failure","Ataxia","Megalablastic anemia"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3009, 'Medicine', 'Cardiology', 'Hard', 'Internal_Medicine', 571, '{"id":3009,"subject":"Medicine","chapter":"Cardiology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":571,"q":"1 year old male child is having a Heart Rate 40/min, BP 90/60. His serum Potassium = 6.5 what is the next best management?","o":["Ipratropium","Adrenaline","Sodium bicarbonate","Calcium chloride"],"a":2,"e":"Answer- C. Sodium bicarbonate For severe elevation 7 meq/L You need to shift potassium into the cells together with elimination of potassium from the body","pyqMatches":[{"year":"2014","no":1266,"q":"1 year old male child is having a Heart Rate 40/min, BP 90/60. His serum Potassium = 6.5 what is the next best management?","o":["Ipratropium","Adrenaline","Sodium bicarbonate","Calcium chloride"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3010, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 572, '{"id":3010,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":572,"q":"Most common presentation of extra- pulmonary TB","o":["Tubercular lymphadenitis","Peritoneal TB","Pericardial TB","Tubercular meningitis"],"a":0,"e":"Answer- A. Tubercular lymphadenitis The most common presentation of extra-pulmonary TB in both HIV sero-negative and HIV-infected patients to about 35% in general, lymph node disease is particularly frequent among HIV infected patients and in children.","pyqMatches":[{"year":"2014","no":1271,"q":"Most common presentation of extra- pulmonary TB","o":["Tubercular lymphadenitis","Peritoneal TB","Pericardial TB","Tubercular meningitis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3011, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 573, '{"id":3011,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":573,"q":"Incorrect about takayasu arteritis","o":["Spares pulmonary artery","Renovascular hypertension","Blood pressure difference between left and right limbs","Strongly positive mantoux"],"a":0,"e":"Answer- A. Spares pulmonary artery Takayasu arteritis is granulomatous vasculitis of large and medium arteries. It is characterized principally by ocular disturbance and marked weakening of pulses in the upper extremities -> Pulseless disease. It is also characterized by a strong predilection for aortic arch and its branches - Aortic arch syndrome. Subclavian artery is involved most commonly Other vessels involved are common carotid, abdominal aorta, coeliac, superior mesenteric, renal, vertebral, iliac, pulmonary and coronary arteries.","pyqMatches":[{"year":"2014","no":1286,"q":"Incorrect about takayasu arteritis","o":["Spares pulmonary artery","Renovascular hypertension","Blood pressure difference between left and right limbs","Strongly positive mantoux"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3012, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 574, '{"id":3012,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":574,"q":"Which of the following is associated with highest risk of Anaphylaxis","o":["Iron dextran","Iron sucrose","Ferumoxytol","Iron Gluconate"],"a":0,"e":"Answer- A. Iron dextran The risk of anaphylaxis is maximally associated with high molecular weight dextran (not so with low molecular weight dextran).","pyqMatches":[{"year":"2014","no":1290,"q":"Which of the following is associated with highest risk of Anaphylaxis","o":["Iron dextran","Iron sucrose","Ferumoxytol","Iron Gluconate"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3013, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 575, '{"id":3013,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":575,"q":"Herpes simplex infection can lead to?","o":["Frontal lobe infarction","Parietal lobe infarction","Temporal lobe infarction","Occipital neuralgia"],"a":2,"e":"Answer- C. Temporal lobe infarction Herpes simplex infection has a predilection for the involvement of Temporal lobe. The lesions in HSV encephalitis are intense hemorrhagic necrosis of the inferior and medial temporal lobe and the mediorbital part of frontal lobes.","pyqMatches":[{"year":"2014","no":1342,"q":"Herpes simplex infection can lead to?","o":["Frontal lobe infarction","Parietal lobe infarction","Temporal lobe infarction","Occipital neuralgia"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3014, 'Medicine', 'Rheumatology', 'Moderate', 'Internal_Medicine', 576, '{"id":3014,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":576,"q":"C V junction abnormalities are seen in all of the following except","o":["Rheumatoid arthritis","Ankylosing spondylitis","Odontoid dysgenesis","Basilar invagination"],"a":1,"e":"Answer- B. Ankylosing spondylitis Developmental and acquired abnormalities Atlanto axial instability","pyqMatches":[{"year":"2014","no":1428,"q":"C V junction abnormalities are seen in all of the following except","o":["Rheumatoid arthritis","Ankylosing spondylitis","Odontoid dysgenesis","Basilar invagination"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3015, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 578, '{"id":3015,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":578,"q":"Which of the following is the common cause of respiratory failure type 2 ?","o":["Chronic bronchitis exacerbation","Acute attack asthma","ARDS","Pneumonia"],"a":0,"e":"Answer- A. Chronic bronchitis exacerbation Type II respiratory failure occurs due to alveolar hypoventilation","pyqMatches":[{"year":"2015","no":1075,"q":"Which of the following is the common cause of respiratory failure type 2 ?","o":["Chronic bronchitis exacerbation","Acute attack asthma","ARDS","Pneumonia"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3016, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 579, '{"id":3016,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":579,"q":"Which of the following is seen in sarcoidosis","o":["Hypercalcemia","Hypocalcemia","Hyperphosphatemia","Hypophosphatemia"],"a":0,"e":"Answer- A. Hypercalcemia Granuloma of sarcoidosis can secret 1-25 (OH)2 vitamin D. Therefore, patients of sarcoidosis may develop hypercalcemia.","pyqMatches":[{"year":"2015","no":1077,"q":"Which of the following is seen in sarcoidosis","o":["Hypercalcemia","Hypocalcemia","Hyperphosphatemia","Hypophosphatemia"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3017, 'Medicine', 'Respiratory Medicine', 'Hard', 'Internal_Medicine', 580, '{"id":3017,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Hard","source":"Internal_Medicine","sourceNo":580,"q":"In a patient with COPD, best management option is","o":["Quit smoking","Bronchodilators","Low flow oxygen","Mucolytics"],"a":2,"e":"Answer- C. Low flow oxygen Therapy is started with short-acting bronchodilator (beta-agonist or anticholinergic). Long-term oxygen therapy is used in all patients with COPD who have chronic hypoxemia","pyqMatches":[{"year":"2015","no":1080,"q":"In a patient with COPD, best management option is","o":["Quit smoking","Bronchodilators","Low flow oxygen","Mucolytics"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3018, 'Medicine', 'Miscellaneous', 'Hard', 'Internal_Medicine', 581, '{"id":3018,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Internal_Medicine","sourceNo":581,"q":"In a patient there is dyspnea in upright position which is relieved in supine position, Diagnosis ?","o":["Tachypnea","Orthopnea","Paroxysmal nocturnal dyspnea","Platypnea"],"a":3,"e":"Answer- D. Platypnea Platyapnea (Orthodeoxia) Dyspnoea when a patient moves to sitting or standing position from a recumbent position.","pyqMatches":[{"year":"2015","no":1081,"q":"In a patient there is dyspnea in upright position which is relieved in supine position, Diagnosis ?","o":["Tachypnea","Orthopnea","Paroxysmal nocturnal dyspnea","Platypnea"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3019, 'Medicine', 'Cardiology', 'Hard', 'Internal_Medicine', 582, '{"id":3019,"subject":"Medicine","chapter":"Cardiology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":582,"q":"After Road traffic accident a patient presented to casualty with vitals showing BP of 90/60 mm Hg with heart of 56 bpm. Which kind of shock occurs ?","o":["Cardiogenic","Neurogenic","Distributive","Hypovolemia shock"],"a":1,"e":"Answer- B. Neurogenic Neurogenic shock is a distributive type of shock resulting in low blood pressure, occasionally with a slowed heart rate, that is attributed to the disruption of the autonomic pathways within the spinal cord. It can occur after damage to the central nervous system such as spinal cord injury.","pyqMatches":[{"year":"2015","no":1216,"q":"After Road traffic accident a patient presented to casualty with vitals showing BP of 90/60 mm Hg with heart of 56 bpm. Which kind of shock occurs ?","o":["Cardiogenic","Neurogenic","Distributive","Hypovolemia shock"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3020, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 583, '{"id":3020,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":583,"q":"Most common cause of idiopathic interstitial pneumonia is","o":["Sarcoidosis","Organizing pneumonia","Idiopathic pulmonary fibrosis","Lipoid pneumonia"],"a":2,"e":"Answer- C. Idiopathic pulmonary fibrosis Idiopatic pulmonary fibrosis Idiopathic nonspecific interstitial pneumonia","pyqMatches":[{"year":"2015","no":1082,"q":"Most common cause of idiopathic interstitial pneumonia is","o":["Sarcoidosis","Organizing pneumonia","Idiopathic pulmonary fibrosis","Lipoid pneumonia"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3021, 'Medicine', 'Neurology', 'Moderate', 'Internal_Medicine', 584, '{"id":3021,"subject":"Medicine","chapter":"Neurology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":584,"q":"Man working in hot environment & drinking lots of water without intake of salts is liable to develop -","o":["Heat hyperpyrexia","Heat cramps","Heat stroke","Heat encephalopathy"],"a":1,"e":"Answer- B. Heat cramps Heat cramps/Miner''s cramps/Stoker''s cramp/Firemen''s cramp These are painful spasm of voluntary muscles which follow sternous work in a hot atmosphere. These are caused by loss of water and salt in profuse prespiration (sweating).","pyqMatches":[{"year":"2015","no":1215,"q":"Man working in hot environment & drinking lots of water without intake of salts is liable to develop","o":["Heat hyperpyrexia","Heat cramps","Heat stroke","Heat encephalopathy"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3022, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 585, '{"id":3022,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":585,"q":"Clicking noise in Pneumomediastinum is known as","o":["Hamman sign","Trail sign","Kussmaul sign","None"],"a":0,"e":"Answer- A. Hamman sign Crunching or clicking noise heard synchronously with the heart beat on auscultation and best heard in the left lateral decubitus position. It is associated with \"Pneumomediastinum\".","pyqMatches":[{"year":"2015","no":1083,"q":"Clicking noise in Pneumomediastinum is known as","o":["Hamman sign","Trail sign","Kussmaul sign","None"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3023, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 586, '{"id":3023,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":586,"q":"True abour drug induced SLE is except ?","o":["Female: Male ratio=9:1","Anti-histone Antibodies","CNS involvement not common","Renal involvement not common"],"a":0,"e":"Answer- A. Female: Male ratio=9:1 It is predominant in caucasians It has less female preddiction than SLE It rarely involves kidneys or brain It is rarely associated with anti Ds DNA It is commonly associated with antibodies to histones It usually resolves over several weeks after discontinuation of the offending medication.","pyqMatches":[{"year":"2015","no":1213,"q":"True abour drug induced SLE is except ?","o":["Female: Male ratio=9:1","Anti-histone Antibodies","CNS involvement not common","Renal involvement not common"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3024, 'Medicine', 'Respiratory Medicine', 'Hard', 'Internal_Medicine', 587, '{"id":3024,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Hard","source":"Internal_Medicine","sourceNo":587,"q":"Emphysema presents with all except","o":["Cyanosis","Barrel shaped chest","Associated with smoking","Type I respiratory failure"],"a":0,"e":"Answer- A. Cyanosis Dyspnoea Cough or wheezing (some patient) Weight loss Barrel-Chest FEVC and FEV1 are reduced. TLC, RC, and FRC are increased due to hyperinflation. Cyanosis is rare (in contrast to chronic bronchitis) Emphysema (COPD) causes type-1 respiratory failure","pyqMatches":[{"year":"2015","no":1084,"q":"Emphysema presents with all except","o":["Cyanosis","Barrel shaped chest","Associated with smoking","Type I respiratory failure"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3025, 'Medicine', 'Respiratory Medicine', 'Moderate', 'Internal_Medicine', 588, '{"id":3025,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":588,"q":"All are seen in emphysema except","o":["Decreased vital capacity","Hyperinflation","Rhonchi","Reduced Dlco"],"a":2,"e":"Answer- C. Rhonchi Cough or wheezing (some patient) Weight loss Barrel-Chest FEVC and FEV1 are reduced. TLC, RC and FRC are increased due to hyperinfcation. Cyanosis is rare (in contrast to chronic bronchitis) Emphysema (COPD) causes type-1 respiratory failure","pyqMatches":[{"year":"2015","no":1085,"q":"All are seen in emphysema except","o":["Decreased vital capacity","Hyperinflation","Rhonchi","Reduced Dlco"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3026, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 589, '{"id":3026,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":589,"q":"Flushing with niacin in reduced by -","o":["Laropiprant","Premedication with aspirin","Tachyphylaxis","All of the above"],"a":3,"e":"Answer- D. All of the above Laropiprant (selective prostaglandin D2 receptor antagonid) Premedication with aspirin Flushing as subject to tachyphylaxis and often improves with time.","pyqMatches":[{"year":"2015","no":1212,"q":"Flushing with niacin in reduced by","o":["Laropiprant","Premedication with aspirin","Tachyphylaxis","All of the above"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3027, 'Medicine', 'Respiratory Medicine', 'Hard', 'Internal_Medicine', 590, '{"id":3027,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Hard","source":"Internal_Medicine","sourceNo":590,"q":"Most common cause of lung abscess is comatose patient","o":["Staph aureus","Oral anaerobes","Klebsiella","Tuberculosis"],"a":1,"e":"Answer- B. Oral anaerobes Most lung abscesses in moribund intubated patients are due to anaerobic bacteria, like peptostreptococcus, Bacteroides etc. Lung abscess The term pulmonary abscess describes a local suppurative process within the lung, characterized by necrosis of lung tissues Etiology As aspiration of oropharyngeal secretions is the most common cause, organisms most commonly causing lung abscess are those normally found in oral cavity, i.e., Anaerobic bacteria (Bacteroides, Fusobacterium, peptococcus species). Other organisms are S. aureus, Klebsiella, Nocardia and gram negative bacteria.","pyqMatches":[{"year":"2015","no":1087,"q":"Most common cause of lung abscess is comatose patient","o":["Staph aureus","Oral anaerobes","Klebsiella","Tuberculosis"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3028, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 591, '{"id":3028,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":591,"q":"Which can be give in hemorrhagic stroke ?","o":["Normal saline","Colloids","Blood transfusion","Hypertonic fluids"],"a":0,"e":"Answer- A. Normal saline Normal saline initially should be used for maintenance and replacement fluids : Hypotonic fluids are contraindicated as they may exacerbate cerebral edema and intracranial pressure. Hypervolemia should be avoided as it may worsen cerebral edema.","pyqMatches":[{"year":"2015","no":1211,"q":"Which can be give in hemorrhagic stroke ?","o":["Normal saline","Colloids","Blood transfusion","Hypertonic fluids"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3029, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 592, '{"id":3029,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":592,"q":"If a person is having ventriular tachycardia, extra systoles appears to","o":["P wave","QRS complex","T wave","R wave"],"a":1,"e":"Answer- B. QRS complex Extra systole in ventricular tachycardia appears in QRS complex when an irritable focus in any part of the ventricular myocardium activates the ventricles before the arrival of the next normal wave of depolarisation from the atria a ventricular extrasystole is produced.","pyqMatches":[{"year":"2015","no":1088,"q":"If a person is having ventriular tachycardia, extra systoles appears to","o":["P wave","QRS complex","T wave","R wave"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3030, 'Medicine', 'Cardiology', 'Hard', 'Internal_Medicine', 593, '{"id":3030,"subject":"Medicine","chapter":"Cardiology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":593,"q":"Most common arrhythmia in ICU patients -","o":["Atrial flutter","Atrial fibrillation","PSVT","NPAT"],"a":1,"e":"Answer- B. Atrial fibrillation Most common arrhythmia in I.C.U. patient → Atrial fibrillation Most common arrhythmia in a patient with Cardiac arrest → Ventricular fibrillation","pyqMatches":[{"year":"2015","no":1089,"q":"Most common arrhythmia in ICU patients","o":["Atrial flutter","Atrial fibrillation","PSVT","NPAT"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3031, 'Medicine', 'Miscellaneous', 'Hard', 'Internal_Medicine', 594, '{"id":3031,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Internal_Medicine","sourceNo":594,"q":"In a patient who was brought to casualty after RTA with pulse rate 108, SBP 80. Which fluid is to be given ideally?","o":["Plasma","Normal Saline","Blood","5% dextrose"],"a":1,"e":"Answer- B. Normal Saline Initial resuscitation requires rapid reexpansion of the circulating intravascular blood volume along with interventions to control ongoing losses. Volume resuscitation is initiated with the rapid infusion of either isotonic saline or a balanced salt solution such as Ringer''s lactate","pyqMatches":[{"year":"2015","no":1210,"q":"In a patient who was brought to casualty after RTA with pulse rate 108, SBP 80. Which fluid is to be given ideally?","o":["Plasma","Normal Saline","Blood","5% dextrose"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3032, 'Medicine', 'Cardiology', 'Hard', 'Internal_Medicine', 595, '{"id":3032,"subject":"Medicine","chapter":"Cardiology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":595,"q":"Patient of 1st degree heart block complains of dizziness. Best treatment for this patient is","o":["Atropine","Isoprenaline","Adrenaline","Pacemaker"],"a":3,"e":"Answer- D. Pacemaker The most definitive or reliable treatment for patient with symptomatic A. V. conduction system is temporary or permanent pacing.","pyqMatches":[{"year":"2015","no":1091,"q":"Patient of 1st degree heart block complains of dizziness. Best treatment for this patient is","o":["Atropine","Isoprenaline","Adrenaline","Pacemaker"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3033, 'Medicine', 'Respiratory Medicine', 'Moderate', 'Internal_Medicine', 596, '{"id":3033,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":596,"q":"Which of the following condition does not cause multiple painful ulcers on tongue?","o":["TB","Sacroidosis","Herpes","Behcet disease"],"a":1,"e":"Answer- B. Sacroidosis Painful ulcers in mouth Apthous ulcers Behcet disease Denture stomatitis Thermal burns Tuberculosis Herpes Carcinoma tongue Arsenic poisoning","pyqMatches":[{"year":"2015","no":1208,"q":"Which of the following condition does not cause multiple painful ulcers on tongue?","o":["TB","Sacroidosis","Herpes","Behcet disease"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3034, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 597, '{"id":3034,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":597,"q":"All are used for secondary prevention of MI except","o":["Aspirin","Statins","Beta blockers","Warfarin"],"a":3,"e":"Answer- D. Warfarin Medicines used in the secondary prevention of M.I. Long term dual antiplatelet therapy with aspirin and P2Y12 receptor blocker. Statins (high intensity). Angiotensin converting enzyme inhibitors in patient with diabetes heart failure, left ventricular ejection fraction. f3 blockers.","pyqMatches":[{"year":"2015","no":1092,"q":"All are used for secondary prevention of MI except","o":["Aspirin","Statins","Beta blockers","Warfarin"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3035, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 598, '{"id":3035,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":598,"q":"Which of the following substances is primarily found in tendons?","o":["Collagen","Fibrin","Fibrillin","Protedglycans"],"a":0,"e":"Answer- A. Collagen Tendon is primarily made up of collagen.","pyqMatches":[{"year":"2015","no":1207,"q":"Which of the following substances is primarily found in tendons?","o":["Collagen","Fibrin","Fibrillin","Protedglycans"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3036, 'Medicine', 'Miscellaneous', 'Hard', 'Internal_Medicine', 599, '{"id":3036,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Internal_Medicine","sourceNo":599,"q":"Not recommended in coronary artery disease patients","o":["Daily exercise","Potassium","Vitamin-E","Statins"],"a":2,"e":"Answer- C. Vitamin-E Intervention studies using vitamin E to prevent cardiovascular disease or cancer have not shown efficacy","pyqMatches":[{"year":"2015","no":1093,"q":"Not recommended in coronary artery disease patients","o":["Daily exercise","Potassium","Vitamin-E","Statins"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3037, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 600, '{"id":3037,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":600,"q":"Number of barr bodies in klinfellter''s syndrome is -","o":["0","1","2","3"],"a":1,"e":"Answer- B. 1 Found in female But - Kleinefelter syndrome is male with one Barr body. Turner syndrome is female without Barr body.","pyqMatches":[{"year":"2015","no":1205,"q":"Number of barr bodies in klinfellter''s syndrome is","o":["0","1","2","3"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3038, 'Medicine', 'Miscellaneous', 'Hard', 'Internal_Medicine', 601, '{"id":3038,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Internal_Medicine","sourceNo":601,"q":"Digitalis is used in mitral stenosis when patient develops","o":["Atrial fibrillation","Right ventricular failure","Acute pulmonary edema","Myocarditis"],"a":0,"e":"Answer- A. Atrial fibrillation Drugs useful in slowing the ventricular rate of patients with AF Beta blockers, Nondihydropyridine calcium channel blockers (e.g., verapamil or diltiazem), and Digitalis glycosides","pyqMatches":[{"year":"2015","no":1094,"q":"Digitalis is used in mitral stenosis when patient develops","o":["Atrial fibrillation","Right ventricular failure","Acute pulmonary edema","Myocarditis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3039, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 602, '{"id":3039,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":602,"q":"Incorrect about LAMB syndrome -","o":["Lentigines","Atrial Myxoma","Myaesthenic syndrome","Blue Nevi"],"a":2,"e":"Answer- C. Myaesthenic syndrome LAMB syndrome is characterized by presence of :- Lentigines Atrial Myxoma Blue nevi.","pyqMatches":[{"year":"2015","no":1202,"q":"Incorrect about LAMB syndrome","o":["Lentigines","Atrial Myxoma","Myaesthenic syndrome","Blue Nevi"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3040, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 603, '{"id":3040,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":603,"q":"Which one of the following is not an early complication of acute myocardial infarction ?","o":["Papillary muscle dysfunction","Ventricular septal defect","Paricarditis","Dressler''s syndrome"],"a":3,"e":"Answer- D. Dressler''s syndrome Dressler''s syndrome is a late complication of myocardial infarction. It usually occurs 1-8 weeks after myocardial infarctions","pyqMatches":[{"year":"2015","no":1095,"q":"Which one of the following is not an early complication of acute myocardial infarction ?","o":["Papillary muscle dysfunction","Ventricular septal defect","Paricarditis","Dressler''s syndrome"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3041, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 604, '{"id":3041,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":604,"q":"Most common malignant tumor of heart in adults","o":["Sarcoma","Rhabdomyoma","Lipoma","Paraganglioma"],"a":0,"e":"Answer- A. Sarcoma Almost all primary cardiac malignancies are sarcomas.","pyqMatches":[{"year":"2015","no":1096,"q":"Most common malignant tumor of heart in adults","o":["Sarcoma","Rhabdomyoma","Lipoma","Paraganglioma"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3042, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 605, '{"id":3042,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":605,"q":"In which of causes of oral ulcer, Auto- antibodies are not seen?","o":["Behcet disease","SLE","Pemphigus","Celiac disease"],"a":0,"e":"Answer- A. Behcet disease Behcet''s disease is classified among the vasculitides laboratory diagnostic does not include regularly autoantibodies associated with vascular manifestations of systemic autoimmune disease.","pyqMatches":[{"year":"2015","no":1201,"q":"In which of causes of oral ulcer, Auto- antibodies are not seen?","o":["Behcet disease","SLE","Pemphigus","Celiac disease"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3043, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 606, '{"id":3043,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":606,"q":"Which is the best way to differentiate between stable angina and NSTEMI?","o":["ECG","Cardiac-biomarker","Trans thoracic Echocardiography","Multi uptake gated Acquisition scan"],"a":1,"e":"Answer- B. Cardiac-biomarker The differentiating feature between Angina and MI is the elevation of cardiac markers°.(no elevation is seen in Angina)","pyqMatches":[{"year":"2015","no":1097,"q":"Which is the best way to differentiate between stable angina and NSTEMI?","o":["ECG","Cardiac-biomarker","Trans thoracic Echocardiography","Multi uptake gated Acquisition scan"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3044, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 607, '{"id":3044,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":607,"q":"Aetiology of Dressler Syndrome is","o":["Viral","Autoimmune","Idiopathic","Toxin mediated"],"a":1,"e":"Answer- B. Autoimmune Immunological factors are thoughts to be of primary importance. The immune complexes hat are generated are deposited into the pericardium, pleura and lungs.","pyqMatches":[{"year":"2015","no":1098,"q":"Aetiology of Dressler Syndrome is","o":["Viral","Autoimmune","Idiopathic","Toxin mediated"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3045, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 608, '{"id":3045,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":608,"q":"Murmur heard in aortic stenosis","o":["Right 2nd intercistal, low pitch murmur","Apex, low pitch murmur","Left Sternal area, low pitch murmur","Pen-systolic murmur, high pitch murmur"],"a":0,"e":"Answer- A. Right 2nd intercistal, low pitch murmur Typically heard at the base of the heart in Aortic area (second intercostal space). Harsh quality. Generally begins after Si and end S before S2.","pyqMatches":[{"year":"2015","no":1100,"q":"Murmur heard in aortic stenosis","o":["Right 2nd intercistal, low pitch murmur","Apex, low pitch murmur","Left Sternal area, low pitch murmur","Pen-systolic murmur, high pitch murmur"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3046, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 609, '{"id":3046,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":609,"q":"All are true about cross-matching of blood except -","o":["Mandatory in all cases except emergency","Recipient serum is tested against donor packed cells","Donor serum is tested against recipient packed cells","Involves visible agglutination"],"a":2,"e":"Answer- C. Donor serum is tested against recipient packed cells Cross matching involves testing the patients serum with donor cells to determine whether the patient has an antibody which may cause a hemolytic transfusion reaction","pyqMatches":[{"year":"2015","no":1199,"q":"All are true about cross-matching of blood except","o":["Mandatory in all cases except emergency","Recipient serum is tested against donor packed cells","Donor serum is tested against recipient packed cells","Involves visible agglutination"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3047, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 610, '{"id":3047,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":610,"q":"Becks triad is seen in","o":["Constrictive pericarditis","Restrictive cardiomyopathy","Cardiac tamponade","None of the above"],"a":2,"e":"Answer- C. Cardiac tamponade Beck''s triad is characteristic of cardiac Tamponade, it includes : Increased venous pressure Decreased arterial pressure Muffled heart sounds, silent heart (due to presence of fluid in pericardium).","pyqMatches":[{"year":"2015","no":1103,"q":"Becks triad is seen in","o":["Constrictive pericarditis","Restrictive cardiomyopathy","Cardiac tamponade","None of the above"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3048, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 611, '{"id":3048,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":611,"q":"All are seen in Nephrotic syndrome except","o":["Atherosclerosis","Thrombo-embolism","Increased protein C levels","Lipiduria"],"a":2,"e":"Answer- C. Increased protein C levels Nephrotic syndrome is a clinical complex characterized by a number of renal and extrarenal features, most prominent of which are Proteinuria (in practice > 3.0 to 3.5gm/24hrs), Hypoalbuminemia, Edema Hypertension Hyperlipidemia, Lipiduria Hypercoagulabilty(result of Loss of Antithrombin III)","pyqMatches":[{"year":"2015","no":1107,"q":"All are seen in Nephrotic syndrome except","o":["Atherosclerosis","Thrombo-embolism","Increased protein C levels","Lipiduria"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3049, 'Medicine', 'Gastroenterology', 'Moderate', 'Internal_Medicine', 612, '{"id":3049,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":612,"q":"All are seen in carney''s triad except -","o":["Atrial myxoma","GIST","Chondroma","Paraganglioma"],"a":0,"e":"Answer- A. Atrial myxoma Extra-adrenal paraganglioma (e.g. extra adrenal phaeo- chromocytoma) Gastrontestinal stromal tumors previously known as gastric epithelioid leiomyosarcoma Pulmonary chondroma hamartoma only 2 of the 3 tumors are present at the time of diagnosis typically affects young people.","pyqMatches":[{"year":"2015","no":1198,"q":"All are seen in carney''s triad except","o":["Atrial myxoma","GIST","Chondroma","Paraganglioma"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3050, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 613, '{"id":3050,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":613,"q":"Basket weave appearance of glomerular basement membrane on electron microscopy is seen in","o":["Alport syndrome","Acute post stretptococcal GN","Polyarteritis nodosa","Giant cell arteritis"],"a":0,"e":"Answer- A. Alport syndrome Basketweave appearance of glomerular basement membrane on Electron Microscopy is seen in Alport''s syndrome. In Alport''s Syndrome, the glomerular basement membrane shows irregular thinning and thickening with a lamellated basket-weave appearance in the thickened area due to extensive remodeling and injury of the basement membrane.","pyqMatches":[{"year":"2015","no":1108,"q":"Basket weave appearance of glomerular basement membrane on electron microscopy is seen in","o":["Alport syndrome","Acute post stretptococcal GN","Polyarteritis nodosa","Giant cell arteritis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3051, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 614, '{"id":3051,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":614,"q":"All of the following causes acute renal failure except","o":["Pyelonephritis","Snakebite","Rhabdomyolysis","Analgesic nephropathy"],"a":3,"e":"Answer- D. Analgesic nephropathy Analgesic nephropathy causes chronic interstitial nephritis and presents with chronic kidney disease. AKI is a serious complication of snakebites by the viperidae family","pyqMatches":[{"year":"2015","no":1109,"q":"All of the following causes acute renal failure except","o":["Pyelonephritis","Snakebite","Rhabdomyolysis","Analgesic nephropathy"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3052, 'Medicine', 'Rheumatology', 'Easy', 'Internal_Medicine', 615, '{"id":3052,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":615,"q":"Martel sign is seen in -","o":["Gout","Ankylosing spondylitis","Osteoarthritis","Rheumatoid arthritis"],"a":0,"e":"Answer- A. Gout Martel''s sign is not present in all cases of gouty arthritis. Martel''s sign, which is a radiological sign (straight arrow) to describe the overhanging margin of the new bone alone the edge of erosion.","pyqMatches":[{"year":"2015","no":1196,"q":"Martel sign is seen in","o":["Gout","Ankylosing spondylitis","Osteoarthritis","Rheumatoid arthritis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3053, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 616, '{"id":3053,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":616,"q":"All are true about GFR except","o":["30-40% decrease after 70 years of age","Best estimated by creatinine clearance","C.K.D is defied as GFR < 30 ml/min/1.732 for 4 weeks","GFR is dependent on height in children"],"a":2,"e":"Answer- C. C.K.D is defied as GFR < 30 ml/min/1.732 for 4 weeks","pyqMatches":[{"year":"2015","no":1111,"q":"All are true about GFR except","o":["30-40% decrease after 70 years of age","Best estimated by creatinine clearance","C.K.D is defied as GFR < 30 ml/min/1.732 for 4 weeks","GFR is dependent on height in children"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3054, 'Medicine', 'Hematology', 'Moderate', 'Internal_Medicine', 617, '{"id":3054,"subject":"Medicine","chapter":"Hematology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":617,"q":"Manifestations of vitamin E.deficiency are all except -","o":["Hemolytic anemia","Posterior column abnormalities","Cerebellar ataxia","Autonomic dysfunction"],"a":3,"e":"Answer- D. Autonomic dysfunction The clinical manifestations are edema, hemolytic anemia (due to fragile red cell''s membrane as a result of lipid peroxidation) and thrombocytosis. Nerve and muscle membrane damage may occur. Vitamin E deficiency causes axonal degeneration of the large myelinated axons and results in posterior column and spinocerebellar symptoms.","pyqMatches":[{"year":"2015","no":1195,"q":"Manifestations of vitamin E.deficiency are all except","o":["Hemolytic anemia","Posterior column abnormalities","Cerebellar ataxia","Autonomic dysfunction"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3055, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 618, '{"id":3055,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":618,"q":"Dialysis indications","o":["Hypertension","Hypokalemia","Pericarditis","Metabolic alkalosis"],"a":2,"e":"Answer- C. Pericarditis Indications of dialysis in chronic renal failure Pericarditis or pleuritis (urgent indication). Progressive uremic encephalopathy or neuropathy, with signs such as confusion, asterixis, myoclonus, wrist or foot drop, or,in severe cases, seizures (urgent indication). A clinically significant bleeding diathesis attributable to uremia (urgent indication). Persistent metabolic disturbances that are refractory to medical therapy;these include hyperkalemia, metabolic acidosis, hypercalcemia, hypocalcemia, and hyperphosphatemia. Fluid overload refractory to diuretics. Hypertension poorly responsive to antihypertensive medications. Persistent nausea and vomiting. Evidence of malnutrition.","pyqMatches":[{"year":"2015","no":1112,"q":"Dialysis indications","o":["Hypertension","Hypokalemia","Pericarditis","Metabolic alkalosis"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3056, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 619, '{"id":3056,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":619,"q":"Which of the following microorganism is incriminated in infection after hemodialysis","o":["Chlamydia","Gram positive organisms","Gram negative","Anaerobes"],"a":1,"e":"Answer- B. Gram positive organisms Hemo-dialysis catheter-related bloodstream infections (CRBSIs) are a major complication of long-term catheter us in HD. Gram positive organism are seen followed by gram negative organisms.","pyqMatches":[{"year":"2015","no":1114,"q":"Which of the following microorganism is incriminated in infection after hemodialysis","o":["Chlamydia","Gram positive organisms","Gram negative","Anaerobes"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3057, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 620, '{"id":3057,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":620,"q":"Dietary deficiency of which vitamin usually does not exist -","o":["Vitamin-B6","Thiamine","Vitamin-E","Vitamin-D"],"a":2,"e":"Answer- C. Vitamin-E Dietary deficiency of vitamin E does not exist.","pyqMatches":[{"year":"2015","no":1194,"q":"Dietary deficiency of which vitamin usually does not exist","o":["Vitamin-B6","Thiamine","Vitamin-E","Vitamin-D"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3058, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 621, '{"id":3058,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":621,"q":"Low serum copper due to ATP 7A gene is due to?","o":["Dubin-johnson''s syndrome","Wilson disease","Menke disease","Gilbert''s disease"],"a":2,"e":"Answer- C. Menke disease Menke''s disease, also known as kinky hair disease, is an X-linked neurodegenerative disease of impaired copper transport, due to ATP 7A gene located on Xp12-13.","pyqMatches":[{"year":"2015","no":1116,"q":"Low serum copper due to ATP 7A gene is due to?","o":["Dubin-johnson''s syndrome","Wilson disease","Menke disease","Gilbert''s disease"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3059, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 622, '{"id":3059,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":622,"q":"I.R.I.S. is -","o":["Immune reconstitution idiopathic syndrome","Immune reconstitution immunological syndrome","Immune reconstitution inflammatory syndroma","Inflammatory reconstitution immune syndrome"],"a":2,"e":"Answer- C. Immune reconstitution inflammatory syndroma The term \"immune reconstitution inflammatory syndrome\" (IRIS) describes a collection of inflammatory disorders associated with paradoxical worsening of preexisting infectious processes following the initiation of highly active antiretroviral therapy.","pyqMatches":[{"year":"2014","no":1392,"q":"I.R.I.S. is","o":["Immune reconstitution idiopathic syndrome","Immune reconstitution immunological syndrome","Immune reconstitution inflammatory syndrome","Inflammatory reconstitution immune syndrome"],"a":2,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":1193,"q":"I.R.I.S. is","o":["Immune reconstitution idiopathic syndrome","Immune reconstitution immunological syndrome","Immune reconstitution inflammatory syndroma","Inflammatory reconstitution immune syndrome"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3060, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 623, '{"id":3060,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":623,"q":"Blood transfusion associated acute lung injury occurs due to -","o":["Nosocomial infections","HLA mediated","Auto-immune disorder","Genetic susceptibility"],"a":1,"e":"Answer- B. HLA mediated TRALI usually results from the transfusion of donor plasma that contains high titre anti HLA class II antibodies that bind recipient leucocytes. The leucocytes aggregate in the pulmonary vasculature and release mediators that increase capillary permeability. Testing the donor''s plasma for Anti HLA antibodies can support this diagnosis.","pyqMatches":[{"year":"2015","no":1192,"q":"Blood transfusion associated acute lung injury occurs due to","o":["Nosocomial infections","HLA mediated","Auto-immune disorder","Genetic susceptibility"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3061, 'Medicine', 'Hematology', 'Hard', 'Internal_Medicine', 624, '{"id":3061,"subject":"Medicine","chapter":"Hematology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":624,"q":"Rockall score is used for prognosis of patients of","o":["Upper GI bleeding","Lower GI bleeding","Hepatic encephalopathy","IBD"],"a":0,"e":"Answer- A. Upper GI bleeding","pyqMatches":[{"year":"2015","no":1120,"q":"Rockall score is used for prognosis of patients of","o":["Upper GI bleeding","Lower GI bleeding","Hepatic encephalopathy","IBD"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3062, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 625, '{"id":3062,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":625,"q":"Which of the following is given to decrease Serum Triglycerides?","o":["Fibrates","Statine","Ezetimibe","Niacin"],"a":0,"e":"Answer- A. Fibrates Fibrates are drugs of choice for hypertriglyceridemia (type IV) and chylomicronemia (type I).","pyqMatches":[{"year":"2015","no":1190,"q":"Which of the following is given to decrease Serum Triglycerides?","o":["Fibrates","Statine","Ezetimibe","Niacin"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3063, 'Medicine', 'Hematology', 'Easy', 'Internal_Medicine', 626, '{"id":3063,"subject":"Medicine","chapter":"Hematology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":626,"q":"Streptococcus bovis infection is associated with -","o":["CLL","Hairy cell leukemia","Colorectal cancer","Multiple myeloma"],"a":2,"e":"Answer- C. Colorectal cancer Colon and rectal tumors Streptococcus bovis (bacteremia)","pyqMatches":[{"year":"2015","no":1189,"q":"Streptococcus bovis infection is associated with","o":["CLL","Hairy cell leukemia","Colorectal cancer","Multiple myeloma"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3064, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 627, '{"id":3064,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":627,"q":"Which is a hormone dependent liver tumor ?","o":["Adenoma","Hemangioma","Hepatocellular carcinoma","Hemangiopericytoma"],"a":0,"e":"Answer- A. Adenoma Adenomas are associated with contraceptive hormone use.","pyqMatches":[{"year":"2015","no":1121,"q":"Which is a hormone dependent liver tumor ?","o":["Adenoma","Hemangioma","Hepatocellular carcinoma","Hemangiopericytoma"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3065, 'Medicine', 'Rheumatology', 'Easy', 'Internal_Medicine', 628, '{"id":3065,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":628,"q":"Polyarticular onset JRA involves more than how many joints -","o":["3","4","5","6"],"a":2,"e":"Answer- C. 5 Polyarticular JRA It is characterized by involvement of 5 or more joints. There are two subtypes :- i) Polyarticular RA positive It is characterized bysymmetrical joint involvement along with Uveitis, and rheumatoid nodules. RA factor and ANA are positive. ii) Polyarticular RA negative RA factor and rheumatoid nodules are not seen.","pyqMatches":[{"year":"2015","no":1188,"q":"Polyarticular onset JRA involves more than how many joints","o":["3","4","5","6"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3066, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 629, '{"id":3066,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":629,"q":"Poikilocytosis and anisocytosis is seen in","o":["Megaloblastic anaemia","Iron deficiency anaemia","Nutritional deficiency anaemia","Thalassemia"],"a":1,"e":"Answer- B. Iron deficiency anaemia Anisocytosis means that RBC''s are unequal in size indicating that some of the RBC''s are either too big or too small. Poikilocytosis means that some of the RBC''s are abnormally shaped.","pyqMatches":[{"year":"2015","no":1123,"q":"Poikilocytosis and anisocytosis is seen in","o":["Megaloblastic anaemia","Iron deficiency anaemia","Nutritional deficiency anaemia","Thalassemia"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3067, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 630, '{"id":3067,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":630,"q":"Alzehiemer type II astrocyte are seen in -","o":["Hepatic encephalopathy","Alzehiemer''s","Parkinsonism","Biswanger disease"],"a":0,"e":"Answer- A. Hepatic encephalopathy Swollen astrocytes in hepatic encephalopathy are called Alzheimer type II astrocytes. Their nuclei are large and appear clear in H & E stains. They are also seen in Wilson disease.","pyqMatches":[{"year":"2015","no":1187,"q":"Alzehiemer type II astrocyte are seen in","o":["Hepatic encephalopathy","Alzehiemer''s","Parkinsonism","Biswanger disease"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3068, 'Medicine', 'Rheumatology', 'Easy', 'Internal_Medicine', 631, '{"id":3068,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":631,"q":"Which of the following antibodies is highly specific for systemic lupus erythematosus -","o":["Anti-Sm","Anti-RO-1","Anti-UIRNP","Anti-Centromere"],"a":0,"e":"Answer- A. Anti-Sm Sensitive test for SLE → Antinuclear antibodies (ANA) Specific test for SLE → Anti dsDNA, Anti Sm","pyqMatches":[{"year":"2015","no":1185,"q":"Which of the following antibodies is highly specific for systemic lupus erythematosus","o":["Anti-Sm","Anti-RO-1","Anti-UIRNP","Anti-Centromere"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3069, 'Medicine', 'Hematology', 'Moderate', 'Internal_Medicine', 632, '{"id":3069,"subject":"Medicine","chapter":"Hematology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":632,"q":"All of the following are characteristic features of treatment of iron deficiency anemia with oral iron supplements, except","o":["Bioavailability is enhanced with vitamin C","The proportion of iron absorbed reduces as hemoglobin improves","The reticulocyte count should begin to increase in two weeks and peak in 4 weeks this suggests good response to treatment","The treatment should be discontinued immediately once hemoglobin normalizes to prevent side effects of iron"],"a":3,"e":"Answer- D. The treatment should be discontinued immediately once hemoglobin normalizes to prevent side effects of iron The reticulocyte count begin to increase within 4-7 days after initiation of therapy and peak at 1.5 weeks. Typically for iron replacement therapy, up to 200mg of elemental iron per day is given, usually as three or four iron tablets (each containing 50-65mg elemental iron) given over the course of the day. A dose of 200 mg of elemental iron per day should result in absorption of iron upto 50 mg/day. This supports a red cell production level of 2-3 times normal in an individual with a normally functioning marrow and appropriate erythropoietin stimulus. As the hemoglobin level rise, erythropoietin stimulation decreases, and the amount of iron absorbed is reduced. The goal of therapy in individuals with iron-deficiency anemia is not l t i th i b t l t id t f t l t 0 5 1 only to repair the anemia, but also to provide stores of at least 0-5-1 g of iron. This sustained treatment for a period of 6-12 months after correction of the anemia will be necessary.","pyqMatches":[{"year":"2015","no":1124,"q":"All of the following are characteristic features of treatment of iron deficiency anemia with oral iron supplements, except","o":["Bioavailability is enhanced with vitamin C","The proportion of iron absorbed reduces as hemoglobin improves","The reticulocyte count should begin to increase in two weeks and peak in 4 weeks this suggests good response to treatment","The treatment should be discontinued immediately once hemoglobin normalizes to prevent side effects of iron"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3070, 'Medicine', 'Respiratory Medicine', 'Hard', 'Internal_Medicine', 634, '{"id":3070,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Hard","source":"Internal_Medicine","sourceNo":634,"q":"A 23-year old woman has experienced episodes of myalgias, pleural effusion, pericarditis and arthralgias without joint deformity over course of several years. The best laboratory screening test to diagnose her disease would be -","o":["CD, lymphocyte count","Erythrocyte sedimentation rate","Antinuclear antibody","Assay for thyroid hormones"],"a":2,"e":"Answer- C. Antinuclear antibody Sensitive test for SLE → Antinuclear antibodies (ANA) Specific test for SLE → Anti dsDNA, Anti Sm","pyqMatches":[{"year":"2015","no":1184,"q":"A 23-year old woman has experienced episodes of myalgias, pleural effusion, pericarditis and arthralgias without joint deformity over course of several years. The best laboratory screening test to diagnose her disease would be","o":["CD, lymphocyte count","Erythrocyte sedimentation rate","Antinuclear antibody","Assay for thyroid hormones"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3071, 'Medicine', 'Gastroenterology', 'Moderate', 'Internal_Medicine', 635, '{"id":3071,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":635,"q":"Zieve syndrome is characterized by all except","o":["Alcohol abuse","Hemolysis","Hypertriglyceridemia","Pancreatic lipase deficiency"],"a":3,"e":"Answer- D. Pancreatic lipase deficiency Zieve''s syndrome is an acute metabolic condition that can occur during withdrawal from prolonged alcohol abuse Zieve syndrome is a rare condition characterized by hemolytic anemia in conjunction with secondary hyperlipidemia in patients suffering from alcohol-related toxic liver damage.","pyqMatches":[{"year":"2015","no":1126,"q":"Zieve syndrome is characterized by all except","o":["Alcohol abuse","Hemolysis","Hypertriglyceridemia","Pancreatic lipase deficiency"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3072, 'Medicine', 'Hematology', 'Easy', 'Internal_Medicine', 636, '{"id":3072,"subject":"Medicine","chapter":"Hematology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":636,"q":"Which is the most common tumor leading to death in adults?","o":["Lung cancer","Prostate cancer","Colorectal cancer","Leukemia"],"a":0,"e":"Answer- A. Lung cancer Lung cancer constitutes upto29% of all cancer related deaths in males and 26% of all cancer related death in woman.","pyqMatches":[{"year":"2015","no":1183,"q":"Which is the most common tumor leading to death in adults?","o":["Lung cancer","Prostate cancer","Colorectal cancer","Leukemia"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3073, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 637, '{"id":3073,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":637,"q":"Hemoglobin with zeta 2 and gamma 2 chains are seen in which of the following","o":["Gower I","Gower II","Portland","Fetal Gb"],"a":2,"e":"Answer- C. Portland Hb Gower I → Zeta 2 / epsilon 2 Hb Portland → Zeta 2 /gamma 2 Hb Gower H Alpha 2 / epsilon 2","pyqMatches":[{"year":"2015","no":1127,"q":"Hemoglobin with zeta 2 and gamma 2 chains are seen in which of the following","o":["Gower I","Gower II","Portland","Fetal Gb"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3074, 'Medicine', 'Rheumatology', 'Easy', 'Internal_Medicine', 638, '{"id":3074,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":638,"q":"In long standing rheumatoid arthritis which will be seen -","o":["Milk alkali syndrome","Nephrolithiasis","Paradoxical aciduria","Secondary amylodosis"],"a":3,"e":"Answer- D. Secondary amylodosis Reactive amyloid A (AA) amyloidosis, one of the most severe complications of RA, is serious, potentially life threatening disorder caused by deposition of AA amyloid fibrils in multiple organs","pyqMatches":[{"year":"2015","no":1182,"q":"In long standing rheumatoid arthritis which will be seen","o":["Milk alkali syndrome","Nephrolithiasis","Paradoxical aciduria","Secondary amylodosis"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3075, 'Medicine', 'Hematology', 'Moderate', 'Internal_Medicine', 639, '{"id":3075,"subject":"Medicine","chapter":"Hematology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":639,"q":"All are true about CNS leukemia except","o":["CNS irradiation is given","Intrathecal methotrexate is given","Seen with acute myeloid leukemia","Single blast in CSF is sufficient for diagnosis"],"a":2,"e":"Answer- C. Seen with acute myeloid leukemia Most children with leukemia have subclinical CNS involvement at the time of diagnosis. Few children show central nervous system involvement at the time of diagnosis, most are asymptomatic but some have features of raised intracranial tension. CNS involvement is mostly due to ALL. CNS involvement is more common in ALL than AML.","pyqMatches":[{"year":"2015","no":1130,"q":"All are true about CNS leukemia except","o":["CNS irradiation is given","Intrathecal methotrexate is given","Seen with acute myeloid leukemia","Single blast in CSF is sufficient for diagnosis"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3076, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 640, '{"id":3076,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":640,"q":"Thrombocythemia is characterized by","o":["Platelets elevation","Low platelets","Neutrophilia","Monocytosis"],"a":0,"e":"Answer- A. Platelets elevation Thrombocythemia or thrombocytosis is the elevation of platelets.","pyqMatches":[{"year":"2015","no":1132,"q":"Thrombocythemia is characterized by","o":["Platelets elevation","Low platelets","Neutrophilia","Monocytosis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3077, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 641, '{"id":3077,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":641,"q":"Hyperuricemia can be caused by all except -","o":["Ethanol","Thiazide","Furosemide","None"],"a":3,"e":"Ans. is. D. None Causes of drug or diet induced hyperuricemia Diuretics (thiazides and loop diuretics) Cyclosporine and tacrolimus Low dose salicylates. Ethambutol Pyrazinamide Ethanol Levodopa Methoxyflurane Laxative abuse (alkalosis) Salt restriction","pyqMatches":[{"year":"2015","no":1179,"q":"Hyperuricemia can be caused by all except","o":["Ethanol","Thiazide","Furosemide","None"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3078, 'Medicine', 'Endocrinology', 'Easy', 'Internal_Medicine', 642, '{"id":3078,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":642,"q":"Glucose fever is related with -","o":["Glucagon","Parathyroid","GH","Aldosterone"],"a":3,"e":"Answer- D. Aldosterone Hypoglycemia in Addison disease is managed with hydrocortisone/dexamethasone. Administration of I.V. glucose in Addison leads to development of fever and is called as \"glucose fever\". In patients with adrenal insufficiency, who have not received glucocorticoids glucose infusion may cause high fever (glucose fever) followed by collapse and death.","pyqMatches":[{"year":"2015","no":1134,"q":"Glucose fever is related with","o":["Glucagon","Parathyroid","GH","Aldosterone"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3079, 'Medicine', 'Nephrology', 'Hard', 'Internal_Medicine', 643, '{"id":3079,"subject":"Medicine","chapter":"Nephrology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":643,"q":"Patient on insulin in CKD stage 4. What is the dose adjustment of insulin required ?","o":["Increased insulin","Decreased insulin","Normal insulin","Add DPP-4 inhibitors"],"a":1,"e":"Answer- B. Decreased insulin Insulin requirements show a biphasic course in diabetic patients with renal disease. It is not uncommon for glucose control to deteriorate as renal function deteriorates, as increasing insulin resistance can affect both type I and type 2 diabetics.","pyqMatches":[{"year":"2015","no":1136,"q":"Patient on insulin in CKD stage 4. What is the dose adjustment of insulin required ?","o":["Increased insulin","Decreased insulin","Normal insulin","Add DPP-4 inhibitors"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3080, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 644, '{"id":3080,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":644,"q":"Most common cause of death in cancer is -","o":["Bleeding","Infection","Respiratory failure","Renal failure"],"a":1,"e":"Answer- B. Infection The most common causes of death in patients with cancer are infection (leading to circulatory failure), respiratory failure, hepatic, and renal failure. Intestinal blockage may lead to inanition and starvation.","pyqMatches":[{"year":"2015","no":1178,"q":"Most common cause of death in cancer is","o":["Bleeding","Infection","Respiratory failure","Renal failure"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3081, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 645, '{"id":3081,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":645,"q":"Which is the best indicator for short term control (2-3 weeks] of blood glucose ?","o":["Serum fructosamine","HbA lc","Blood sugar","Urine sugar"],"a":0,"e":"Answer- A. Serum fructosamine Serum fructosamine → Tells sugar fluctuations in 2-3 weeks Glycosylated hemoglobin → Tells sugar fluctuations in previous 6-8 weeks.","pyqMatches":[{"year":"2015","no":1137,"q":"Which is the best indicator for short term control (2-3 weeks] of blood glucose ?","o":["Serum fructosamine","HbA lc","Blood sugar","Urine sugar"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3082, 'Medicine', 'Endocrinology', 'Easy', 'Internal_Medicine', 646, '{"id":3082,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":646,"q":"Post Prandial capillary glucose should be mg/dl for adequate diabetes control","o":["< 100mg / dl","< 140 mg / dl","< 180 mg/dl","< 200 mg/dl"],"a":2,"e":"Answer- C. < 180 mg/dl HbA IC- two Preprandial capillary plasma glucose- 70-130 mg/d1 < Peak post prandial capillary plasma glucose -180 mg/d1 < Blood pressure- 130/80","pyqMatches":[{"year":"2015","no":1138,"q":"Post Prandial capillary glucose should be mg/dl for adequate diabetes control","o":["< 100mg / dl","< 140 mg / dl","< 180 mg/dl","< 200 mg/dl"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3083, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 647, '{"id":3083,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":647,"q":"Mosaic pattern of coment line is characteristically seen in -","o":["Hyperthyroidism","Paget''s disease of bone","Renal osteodystrophy","Osteomalacia"],"a":1,"e":"Answer- B. Paget''s disease of bone Mosaic pattern of cement line is characteristically associated with paget''s disease of the bone","pyqMatches":[{"year":"2015","no":1176,"q":"Mosaic pattern of coment line is characteristically seen in","o":["Hyperthyroidism","Paget''s disease of bone","Renal osteodystrophy","Osteomalacia"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3084, 'Medicine', 'Endocrinology', 'Easy', 'Internal_Medicine', 648, '{"id":3084,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":648,"q":"Hyperpigmentation is seen with which hormone?","o":["FSH","LH","TSH","ACTH"],"a":3,"e":"Answer- D. ACTH Hyperpigmentation of the skin and mucous membranes often precedes all other symptoms by months to years. It is caused by the stimulant effect of excess adrenocorticotrophic hormone (ACTH) on the melanocytes to produce melanin. The hyperpigmentation is caused by high levels of circulating ACTH that bind to the melanocortin 1 receptor on the surface of dermal melanocytes. Other melanocyte-stimulating hormones produced by the pituitary and other tissues include alpha-MSH (contained within the ACTH molecule), beta-MSH, and gamma-MSH. When stimulated, the melanocyte changes the color of the pigment to a dark brown or black. The increased MSH in Addison''s causes melanocytes to disperse melanin in the epidermis thus increasing pigmentation.","pyqMatches":[{"year":"2015","no":1139,"q":"Hyperpigmentation is seen with which hormone?","o":["FSH","LH","TSH","ACTH"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3085, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 649, '{"id":3085,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":649,"q":"Female with blood sugar of 600 mg% and sodium of 110 mEq. Insulin was given, what will happen to serum sodium levels ?","o":["Sodium increase","Sodium decrease","Sodium unaffected","Relative sodium deficiency"],"a":0,"e":"Answer- A. Sodium increase As the glucose level decreases, there is decrease in the osmolarity of extracellular fluid. This causes movement of intracellular fluid back into the cellular compartment producing increase in serum sodium.","pyqMatches":[{"year":"2015","no":1144,"q":"Female with blood sugar of 600 mg% and sodium of 110 mEq. Insulin was given, what will happen to serum sodium levels ?","o":["Sodium increase","Sodium decrease","Sodium unaffected","Relative sodium deficiency"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3086, 'Medicine', 'Gastroenterology', 'Hard', 'Internal_Medicine', 650, '{"id":3086,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":650,"q":"Which of the following presents with hypokalemia and metabolic acidosis ?","o":["Diarrhea","Vomiting","Nasogastic suction","Nasogastic suction"],"a":0,"e":"Ans- A. Diarrhea Diarrhea causes hypokalemia with metabolic acidosis. Vomiting nosogastric suction and conn''s syndrome cause metabolic alkalosis.","pyqMatches":[{"year":"2015","no":1145,"q":"Which of the following presents with hypokalemia and metabolic acidosis ?","o":["Diarrhea","Vomiting","Nasogastic suction","Nasogastic suction"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3087, 'Medicine', 'Neurology', 'Hard', 'Internal_Medicine', 651, '{"id":3087,"subject":"Medicine","chapter":"Neurology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":651,"q":"Lafora''s disease presents with -","o":["G.T.C.S","Myoclonic epilepsy","Petit mal epilepsy","Partial seizures"],"a":1,"e":"Answer- B. Myoclonic epilepsy Lofora disease is an autosomal recessive poliencephalopathy of late childhood or early adult life. It is characterized by progressive dementia, dysarthria, visual loss, pyramidal & cerebellar signs, and myoclonic & other seizures. The diagnostic pathological finding is lofora bodies.","pyqMatches":[{"year":"2015","no":1175,"q":"Lafora''s disease presents with","o":["G.T.C.S","Myoclonic epilepsy","Petit mal epilepsy","Partial seizures"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3088, 'Medicine', 'Hematology', 'Moderate', 'Internal_Medicine', 652, '{"id":3088,"subject":"Medicine","chapter":"Hematology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":652,"q":"In cobalamin deficiency which is not seen","o":["Microcytic anemia","Long tract signs","Loss of proprioception","Rhomberg sign"],"a":0,"e":"Answer- A. Microcytic anemia Cobalmine deficiency causes megaloblastic (macrocytic) anemia (not microcytic). Cobalamine deficiency also causes subacute combined degeneration of spinal cord due to involvement of posterior column, affecting vibration, fine touch, and imbolance (Romberg sign).","pyqMatches":[{"year":"2015","no":1147,"q":"In cobalamin deficiency which is not seen","o":["Microcytic anemia","Long tract signs","Loss of proprioception","Rhomberg sign"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3089, 'Medicine', 'Neurology', 'Moderate', 'Internal_Medicine', 653, '{"id":3089,"subject":"Medicine","chapter":"Neurology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":653,"q":"Hypernatremia causes all EXCEPT","o":["Seizure","Thrombus","Brain hemorrhage","Central pontine myelinosis"],"a":3,"e":"Answer- D. Central pontine myelinosis Complication of hypernatremia are brain hemorrhage, seizures, coma, thrombotic complications and raised ICT. Central pontine myelinosis is classically associated with overlay rapid correction of hyponatremia. Clinical features- Patients are irritable, restless weak and lethargic Some have high pitched cry and hyperpnea. Alert patient are very thirsty. Hypernatremia causes fever although many patients have underlying process that contributes to the fever.","pyqMatches":[{"year":"2015","no":1148,"q":"Hypernatremia causes all EXCEPT","o":["Seizure","Thrombus","Brain hemorrhage","Central pontine myelinosis"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3090, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 654, '{"id":3090,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":654,"q":"All of the following are associated with hyponatremia except","o":["anorexia","Convulsions","Drowsiness","Myalgia"],"a":3,"e":"Answer- D. Myalgia Anorexia, nausea & vomiting Coma Convulsions Drowsiness Headache Circulatory failure and hypotension Hyponatremia can also cause muscle cramps and weakness.","pyqMatches":[{"year":"2015","no":1149,"q":"All of the following are associated with hyponatremia except","o":["anorexia","Convulsions","Drowsiness","Myalgia"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3091, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 655, '{"id":3091,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":655,"q":"Most common type of multiple sclerosis?","o":["Relapsing remitting type","Secondry progressive multiple sclerosis","Progresive relapsing multiple scelrosis","Primary progresive multiple sclerosis"],"a":0,"e":"Answer- A. Relapsing remitting type Repapsing-remitting multiple sclerosis (RRMS) This is the most common form of multiple sclerosis. About 85% of people with M.S. are initially diagnosed with relapsing- remitting multiple sclerosis.","pyqMatches":[{"year":"2015","no":1150,"q":"Most common type of multiple sclerosis?","o":["Relapsing remitting type","Secondry progressive multiple sclerosis","Progresive relapsing multiple scelrosis","Primary progresive multiple sclerosis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3092, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 656, '{"id":3092,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":656,"q":"Aspirin decreases the risk of development of which of the following -","o":["Colorectal cancer","Stomach cancer","Carcinoid","MALToma"],"a":0,"e":"Ans. A. Colorectal cancer Regular aspirin use reduces the risk of colon adenomas and carcinomas as well as death from large-bowel cancer","pyqMatches":[{"year":"2015","no":1174,"q":"Aspirin decreases the risk of development of which of the following","o":["Colorectal cancer","Stomach cancer","Carcinoid","MALToma"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3093, 'Medicine', 'Dermatology & Allergy', 'Moderate', 'Internal_Medicine', 657, '{"id":3093,"subject":"Medicine","chapter":"Dermatology & Allergy","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":657,"q":"Dermatitis may be a clinical manifestation of deficiency states of all of following nutrients except -","o":["Biotin","Niacin","Pyridoxine","Thiamine"],"a":3,"e":"Answer- D. Thiamine Vitamin B3 (Niacin) deficiency causes dermatitis. Biotin and Vitamin B6 (pyridoxin) deficiency causes seborrheic dermatitis.","pyqMatches":[{"year":"2015","no":1173,"q":"Dermatitis may be a clinical manifestation of deficiency states of all of following nutrients except","o":["Biotin","Niacin","Pyridoxine","Thiamine"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3094, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 658, '{"id":3094,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":658,"q":"In EEG which type of waves are seen in metabolic encephalopathy","o":["Alpha","Beta","Gamma","Delta"],"a":3,"e":"Answer- D. Delta E.E.G. has been widely used to evaluate metabolic encephalopathy. The E.E.G. findings are abnormal in acute encephalopathy stages Metabolic encephalopathy ''vthm Grade I (almost normal) Dominant activity is rhythm with minima, theta activity Grade II (mildly abnormal) Dominant theta background with some alpha and delta activities Grade II (morderately abnormal) Continuous delta activety predominates, little activity of faster frequencies Grade IV (severely abnormal) Low-amplitude delta activity or suppression- burst pattern Grade V (extremely abnormal) Nearly \"flat\" tracing or electrocerebral inactivity","pyqMatches":[{"year":"2015","no":1151,"q":"In EEG which type of waves are seen in metabolic encephalopathy","o":["Alpha","Beta","Gamma","Delta"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3095, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 659, '{"id":3095,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":659,"q":"Which vitamin toxicity is associated with excessive sweating -","o":["Choline","Biotin","Folic cid","Vitamin B"],"a":0,"e":"Answer- A. Choline Toxicity from choline results in - Hypotension Cholinergic sweating Diarrhea Salivation Fishy body odor","pyqMatches":[{"year":"2015","no":1172,"q":"Which vitamin toxicity is associated with excessive sweating","o":["Choline","Biotin","Folic cid","Vitamin B"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3096, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 660, '{"id":3096,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":660,"q":"Isaac syndroma is characterised by -","o":["Peripheral nerve excitability","Opsoclonus","Encephalomyelitis","Limbic encephalitis"],"a":0,"e":"Answer- A. Peripheral nerve excitability Isacc syndrome (neuromyotonia) Peripheral nerve hyperexcitability Spontaneous and continuous muscle fiber activity of peripheral nerve origin. Clinical features include cramps, muscle twitching (fasciculations or myokymia) Stiffness Delayed Muscle relaxation (pseudomyotonia) Spontaneous or evoked carpal or pedal spasms.","pyqMatches":[{"year":"2015","no":1168,"q":"Isaac syndroma is characterised by","o":["Peripheral nerve excitability","Opsoclonus","Encephalomyelitis","Limbic encephalitis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3097, 'Medicine', 'Miscellaneous', 'Hard', 'Internal_Medicine', 661, '{"id":3097,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Internal_Medicine","sourceNo":661,"q":"Glasgow coma scale motor 4 represents?","o":["Withdrawal or flexion","Decorticate posturing","Decorticate posturing","Localise pain"],"a":0,"e":"Answer- A. Withdrawal or flexion","pyqMatches":[{"year":"2015","no":1152,"q":"Glasgow coma scale motor 4 represents?","o":["Withdrawal or flexion","Decorticate posturing","Decorticate posturing","Localise pain"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3098, 'Medicine', 'Miscellaneous', 'Hard', 'Internal_Medicine', 662, '{"id":3098,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Internal_Medicine","sourceNo":662,"q":"A patient after an accident was unconscious. On physical examination there was unilateral pupillary dilatation Possible reason for the same is","o":["Uncal herniation","Tonsillar herniation","Cingulate herniation","Transcalvarial herniation"],"a":0,"e":"Answer- A. Uncal herniation Transtentorial herniation is the displacement of medial temporal lobe into the tentorial opening it is usually seen after extradural hemorrhage.","pyqMatches":[{"year":"2015","no":1153,"q":"A patient after an accident was unconscious. On physical examination there was unilateral pupillary dilatation Possible reason for the same is","o":["Uncal herniation","Tonsillar herniation","Cingulate herniation","Transcalvarial herniation"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3099, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 663, '{"id":3099,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":663,"q":"First Symptoms of parkinsons disease is -","o":["Postural instability","Rigidity","Tremors","Bradykinesia"],"a":2,"e":"Answer- C. Tremors Parkinsonism is a progressive degenerative, extrapyramidal disorder of muscle movement, due to dysfunction in basal ganglia, comprising four cardinal features Bradykinesia or hypokinesia Muscle rigidity Resting tremor","pyqMatches":[{"year":"2015","no":1166,"q":"First Symptoms of parkinsons disease is","o":["Postural instability","Rigidity","Tremors","Bradykinesia"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3100, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 664, '{"id":3100,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":664,"q":"Increased ICT is shown by","o":["Miosis","Systemic hypotension","Tachycardia","Reduction in GCS"],"a":3,"e":"Answer- D. Reduction in GCS Increased ICT leads to bradycardia with Hypertension. Uncal herniation of brain leads to ipsilateral pupillary dilatation. Reduction in GCS due to damage to reticular activating system leads to development of coma.","pyqMatches":[{"year":"2015","no":1154,"q":"Increased ICT is shown by","o":["Miosis","Systemic hypotension","Tachycardia","Reduction in GCS"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3101, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 665, '{"id":3101,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":665,"q":"Plaques jaunes are seen in","o":["Syphilis","Head injury","Endocarditis","Atherosclerosis"],"a":1,"e":"Answer- B. Head injury Plaque Jaunes is a term used to describe the characteristic gross appearance of old traumatic contusions on the surface of brain from previous head injuries.","pyqMatches":[{"year":"2015","no":1157,"q":"Plaques jaunes are seen in","o":["Syphilis","Head injury","Endocarditis","Atherosclerosis"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3102, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 666, '{"id":3102,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":666,"q":"Commonest cause of cerebro vascular accident","o":["Infarction","Infarction","Embolism","Aortic dissection"],"a":0,"e":"Answer- A. Infarction","pyqMatches":[{"year":"2015","no":1159,"q":"Commonest cause of cerebro vascular accident","o":["Infarction","Infarction","Embolism","Aortic dissection"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3103, 'Medicine', 'Cardiology', 'Hard', 'Internal_Medicine', 667, '{"id":3103,"subject":"Medicine","chapter":"Cardiology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":667,"q":"This patient came to the casualty with palpitations. His ECG has been shown below. What is your diagnosis?","o":["Ventricular tachycardia","A-V dissociation","Supraventricular tachycardia","Sinus tachycardia"],"a":2,"e":"Answer- C. Supraventricular tachycardia The overall rhythm is rapid and rgular. The R-R interval is almost exactly 1.5 large boxes in duration - establishing the rate at 180-190 beats per min this is an ECG showing narrow complex tachycardia most probably due to AVNRT (Av Nodal Reentrant Tachycardia) aka supraventricular tachycardia. [Ref Harrison''s 18th/e p.1888]","pyqMatches":[{"year":"2013","no":1229,"q":"This patient came to the casualty with palpitations. His ECG has been shown below. What is your diagnosis?","o":["Ventricular tachycardia","A-V dissociation","Supraventricular tachycardia","Sinus tachycardia"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3104, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 668, '{"id":3104,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":668,"q":"What is Reifenstein syndrome?","o":["Associated with gonadal dysgenesis","Partial androgen insensitivity syndrome due to receptor mutation","Associated with mental retardation","5-alpha reductase deficiendy associated with perineo¬scrotal hypospadias"],"a":1,"e":"Answer- B. Partial androgen insensitivity syndrome due to receptor mutation It is partial androgen insensitivity syndrome because of less severe androgen receptor mutation. Patients often present in infancy with :","pyqMatches":[{"year":"2013","no":1231,"q":"What is Reifenstein syndrome?","o":["Associated with gonadal dysgenesis","Partial androgen insensitivity syndrome due to receptor mutation","Associated with mental retardation","5-alpha reductase deficiendy associated with perineo¬scrotal hypospadias"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3105, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 669, '{"id":3105,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":669,"q":"Following are absolute indication for hemo-dialysis except","o":["GI bleeding","Convulsions","Pericarditis","Hyperkalemia of 6.5 mEq/L"],"a":3,"e":"Answer- D. Hyperkalemia of 6.5 mEq/L Important indications for hemodialysis are:","pyqMatches":[{"year":"2013","no":1234,"q":"Following are absolute indication for hemo-dialysis except","o":["GI bleeding","Convulsions","Pericarditis","Hyperkalemia of 6.5 mEq/L"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3106, 'Medicine', 'Rheumatology', 'Moderate', 'Internal_Medicine', 670, '{"id":3106,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":670,"q":"In scleroderma features are all except:","o":["Decrease in tone of LES","Restrictive cardiomyopathy","Syndactyly","Halitosis"],"a":2,"e":"Answer- C. Syndactyly Syndactyly is not associated with scleroderma. Lower esophageal sphincter tone is decreased in scleroderma. Scleroderma can cause restrictive cardiomyopathy. Halitosis (bad smell in breath) can occur in scleroderma.","pyqMatches":[{"year":"2013","no":1235,"q":"In scleroderma features are all except:","o":["Decrease in tone of LES","Restrictive cardiomyopathy","Syndactyly","Halitosis"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3107, 'Medicine', 'Respiratory Medicine', 'Hard', 'Internal_Medicine', 671, '{"id":3107,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Hard","source":"Internal_Medicine","sourceNo":671,"q":"Best for management of respiratory alkalosis?","o":["Rebreathing in paper bag","IPPV","Normal saline","Acetazolamide"],"a":0,"e":"Answer- A. Rebreathing in paper bag Changing ventilator setting may be used to prevent or treat respiratory alkalosis in persons who are being mechanically ventilated. Persons with hyperventilation syndrome may benefit from reassurance, rebreathing from a paper bag during symptomatic attacks, and attention to the psychological stress.","pyqMatches":[{"year":"2013","no":1238,"q":"Best for management of respiratory alkalosis?","o":["Rebreathing in paper bag","IPPV","Normal saline","Acetazolamide"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3108, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 672, '{"id":3108,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":672,"q":"Adrenal reserve is best tested by means of infusion with","o":["Glucocorticoids","ACTH","GnRH","Metyrapone"],"a":1,"e":"Answer- B. ACTH Glucocorticosteroid reserve can be evaluated by the ACTH stimulation test A more sensitive test of adrenal reserve is the standardised 24-hour ACTH infusion test. Under maximal ACTH stimulation the cortisol secretion increases tenfold. If gtucocorucoid coverage is required during the ACTH stimulation test, dexamethasone can be used because it does not interfere with the laboratory values of endogenous glucocorucoids.","pyqMatches":[{"year":"2013","no":1239,"q":"Adrenal reserve is best tested by means of infusion with","o":["Glucocorticoids","ACTH","GnRH","Metyrapone"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3109, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 673, '{"id":3109,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":673,"q":"Graham steel murmur is seen in","o":["PS","PR","TR","TS"],"a":1,"e":"Answer- B. PR Graham steel''s murmur A diastolic murmur audible along the left sternal border due to pulmonaryregurgitation in patients with pulmonary hypertension. Graham steel murmur is a high pitched decressendo murmur loudest during inspiration Grahm steel''s- Early DM- PR","pyqMatches":[{"year":"2013","no":1245,"q":"Graham steel murmur is seen in","o":["PS","PR","TR","TS"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3110, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 674, '{"id":3110,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":674,"q":"CVP is monitored in A/E","o":["Anterior jugular vein","Internal jugular vein","External jugular vein","Inferior venacava"],"a":3,"e":"Answer- D. Inferior venacava Commonly used vein cannulation sites for central venous access include: Jugular vein External jugular vein Internal jugular vein (central, posterior, anterior approaches) Subclavian vein (supraclavicular, infraclavicular, axillary approaches) Femoral vein Basilic vein","pyqMatches":[{"year":"2013","no":1247,"q":"CVP is monitored in A/E","o":["Anterior jugular vein","Internal jugular vein","External jugular vein","Inferior venacava"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3111, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 675, '{"id":3111,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":675,"q":"Central venous monitoring is done for all except","o":["Regulating the speed and amount of fluid infusion","Administering thrombolytics","Deciding the need for plasma infusion","Deciding the requirement for blood transfusion"],"a":1,"e":"Answer- B. Administering thrombolytics 1) Administration of noxious medications 2) Hemodynamic monitoring- Blood transfusion or plasma transfusion 3) Plasmapheresis, apheresis, hemodialysis, or continuous renal replacement therapy 4) Poor peripheral venous access","pyqMatches":[{"year":"2013","no":1248,"q":"Central venous monitoring is done for all except","o":["Regulating the speed and amount of fluid infusion","Administering thrombolytics","Deciding the need for plasma infusion","Deciding the requirement for blood transfusion"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3112, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 676, '{"id":3112,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":676,"q":"Thrombosis is most commonly associated with what site in CVP","o":["Internal jugular vein","Subclavian vein","Femoral vein","External jugular vein"],"a":2,"e":"Answer- C. Femoral vein Advantages- Rapid access with high success rate Does not interfere with CPR Does not interfere with intubation No risk of pneumothorax Trendelenburg position not necessary during insertion Disadvantages- Delayed circulation of drugs during CPR Prevents patient mobilization Difficult to keep site sterile Difficult for PA catheter insertion Increased risk of iliofemoral thrombosis","pyqMatches":[{"year":"2013","no":1249,"q":"Thrombosis is most commonly associated with what site in CVP","o":["Internal jugular vein","Subclavian vein","Femoral vein","External jugular vein"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3113, 'Medicine', 'Cardiology', 'Hard', 'Internal_Medicine', 677, '{"id":3113,"subject":"Medicine","chapter":"Cardiology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":677,"q":"Serum ascitic fluid gradient of 1.5 (SAAG) with ascitic fluid protein of 2.8gm/d1. the most likely cause is","o":["Nephritic syndrome","Cardiac failure","TB","Portal hypertension"],"a":1,"e":"Answer- B. Cardiac failure Serum to ascites albumin gradient >1.5 suggests either cirrhosis or cardiac failure. The total protein concentration >2.5 suggests ascites due to cardiac cause The total protein concentration helps to differentiate uncomplicated ascites from cirrhosis from cardiac ascites both of which have a SAAG 1.1 g/dL.","pyqMatches":[{"year":"2013","no":1250,"q":"Serum ascitic fluid gradient of 1.5 (SAAG) with ascitic fluid protein of 2.8gm/d1. the most likely cause is","o":["Nephritic syndrome","Cardiac failure","TB","Portal hypertension"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3114, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 678, '{"id":3114,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":678,"q":"Coronary steal phenomenon caused due to","o":["Arterial dilation","Coronary microvessel dilation","Epicardial vessel dilation","Capacitance vessel dilation"],"a":1,"e":"Answer- B. Coronary microvessel dilation Coronary steal is the term given to blood being stolen from one region of the coronary tree by another. It is also called coronary steal syndrome. It is commonly seen with powerful coronary dilator drugs like dipyridamole or hydralazine. These drugs are potent arteriolar dilators and dilates resistance vessels too. The obstructed branch has significant arteriolar dilation even when oxygen demand is low because of the accumulation of metabolites in the ischemic tissue.","pyqMatches":[{"year":"2013","no":1251,"q":"Coronary steal phenomenon caused due to","o":["Arterial dilation","Coronary microvessel dilation","Epicardial vessel dilation","Capacitance vessel dilation"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3115, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 679, '{"id":3115,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":679,"q":"Decreased CVP is seen in","o":["Pneumothorax","PEEP","Bacterial sepsis","Heart failure"],"a":2,"e":"Answer- C. Bacterial sepsis Decreased Hypovolemia Septic shock Deep inhalation (transient) Increased venous compliance","pyqMatches":[{"year":"2013","no":1252,"q":"Decreased CVP is seen in","o":["Pneumothorax","PEEP","Bacterial sepsis","Heart failure"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3116, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 680, '{"id":3116,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":680,"q":"Lemierre''s syndrome is","o":["Carotid sinus aneurysm","Thromobophlebitis of IJV","Traumatic occlusion of IJV","Any of the above"],"a":1,"e":"Answer- B. Thromobophlebitis of IJV Rare thrombophlebitis of the jugular veins with distant metastatic sepsis in the setting of initial oropharyngeal infections (pharyngitis, t/-peritonsillar abscess).","pyqMatches":[{"year":"2013","no":1254,"q":"Lemierre''s syndrome is","o":["Carotid sinus aneurysm","Thromobophlebitis of IJV","Traumatic occlusion of IJV","Any of the above"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3117, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 681, '{"id":3117,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":681,"q":"Wide QRS duration is -","o":["> 0.8sec","> 0.9 sec","> .12 sec","None"],"a":2,"e":"Answer- C. > .12 sec QRS duration → 0.08 - 0.12 sec. QT interval 0.40 sec. PR interval 0.12 - 20 sec. QRS Axis range → + 90 to -30°","pyqMatches":[{"year":"2013","no":1255,"q":"Wide QRS duration is","o":["> 0.8sec","> 0.9 sec","> .12 sec","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3118, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 682, '{"id":3118,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":682,"q":"Torsades de pointes is seen in all except","o":["Hyponatremia","Hypocalcemia","Hypomagnesemia","Hypokalemia"],"a":0,"e":"Answer- A. Hyponatremia HypokalemiaQ HypocalcemiaQ Hypomagnesemia","pyqMatches":[{"year":"2013","no":1257,"q":"Torsades de pointes is seen in all except","o":["Hyponatremia","Hypocalcemia","Hypomagnesemia","Hypokalemia"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3119, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 683, '{"id":3119,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":683,"q":"Sinus bradycardia with MI treatment","o":["Atropine","Digoxin","Calcium channel blocker","Propranolol"],"a":0,"e":"Answer- A. Atropine The SA node rate generally increases after the administration of a vagolytic drug, such as \"atropine\".","pyqMatches":[{"year":"2013","no":1258,"q":"Sinus bradycardia with MI treatment","o":["Atropine","Digoxin","Calcium channel blocker","Propranolol"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3120, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 684, '{"id":3120,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":684,"q":"In COPD which is true","o":["FEV 1 /FVC < 0.7","FEV1/FVC","RV4","TLV1"],"a":0,"e":"Answer- A. FEV 1 /FVC < 0.7 Spirometry findings in COPD includes reduced FEV1 and a reduced FEV1 / FVC ratio. Diffusion capacity for carbon monoxide reflects the ability of lung to transfer gas across alveolar/capillary interface. Diffusion capacity is low in patients with emphysema and infiltrative lung diseases. It is increased in patients with pulmonary hemorrhage, congestive heart failure and asthma.","pyqMatches":[{"year":"2013","no":1260,"q":"In COPD which is true","o":["FEV 1 /FVC < 0.7","FEV1/FVC","RV4","TLV1"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3121, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 685, '{"id":3121,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":685,"q":"Which of the following is markedly decreased in restrictive lung disease","o":["FVC","FEV I","FEV I /FVC","RV"],"a":0,"e":"Answer- A. FVC Forced vital capacity (FVC)- Decreased (more than obstruction) Forced expiratory volume in 1 second (FEV,)- Decreased in proportion to FVC FEVi/FVC- Near normal or increased Forced mid expiratory flow rate- Reduced Total lung capacity- Decreased Residual volume- Generally decreased Functional residual capacity- Decreased","pyqMatches":[{"year":"2013","no":1261,"q":"Which of the following is markedly decreased in restrictive lung disease","o":["FVC","FEV I","FEV I /FVC","RV"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3122, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 686, '{"id":3122,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":686,"q":"Cepacia syndrome fulminant illness seen in","o":["Sarcoidosis","Cystic fibrosis","Tuberculosis","Immotile cilia sydrome"],"a":1,"e":"Answer- B. Cystic fibrosis Capacea syndrome is a rapid clinical deterioration in patients with cystic fibrosis due to new acquisition of or chronic colonization with Burkholderia cepacia complex and carries a very high mortality. In chronically colonized patients the deterioration is often triggered by an intercurrent illness.","pyqMatches":[{"year":"2013","no":1262,"q":"Cepacia syndrome fulminant illness seen in","o":["Sarcoidosis","Cystic fibrosis","Tuberculosis","Immotile cilia sydrome"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3123, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 687, '{"id":3123,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":687,"q":"Empyema thoracis is most commonly caused by which organism","o":["Streptococcus pneumoniae","Pseudomonas","Mycoplasma","Stapylococcus aureus"],"a":0,"e":"Answer- A. Streptococcus pneumoniae Empyema thoracic is commonly caused by those bacterias that cause pneumonias such as streptococcus pneumoniae and staphlococcus aureus. E.coli, FLinfluenzas, Klebsiella pneumoniae.","pyqMatches":[{"year":"2013","no":1265,"q":"Empyema thoracis is most commonly caused by which organism","o":["Streptococcus pneumoniae","Pseudomonas","Mycoplasma","Stapylococcus aureus"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3124, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 688, '{"id":3124,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":688,"q":"Most common cause of lobar consolidation","o":["Mycoplasma","Chlamydia","Streptococcus","Legionela"],"a":2,"e":"Answer- C. Streptococcus Lobar pneumonias typically occurs with primary pneumonias caused by virulent agents, most commonly pneumococci.","pyqMatches":[{"year":"2013","no":1266,"q":"Most common cause of lobar consolidation","o":["Mycoplasma","Chlamydia","Streptococcus","Legionela"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3125, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 689, '{"id":3125,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":689,"q":"Clinical feature of Bronchiestasis are all except","o":["Hemoptysis","Night sweats","Chest pain","Productive cough"],"a":1,"e":"Answer- B. Night sweats The classic clinical manifestations of bronchiectasis are cough and the daily production of mucopurulent and tenacious sputum lasting months to years. complaints include dyspnea, wheezing hemoptysis, and pleuritic chest pain.","pyqMatches":[{"year":"2013","no":1267,"q":"Clinical feature of Bronchiestasis are all except","o":["Hemoptysis","Night sweats","Chest pain","Productive cough"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3126, 'Medicine', 'Respiratory Medicine', 'Moderate', 'Internal_Medicine', 690, '{"id":3126,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":690,"q":"All of the following are features of interstitial lung disease except","o":["Exertional dyspnea","Early productive cough","Digital clubbing","Coarse crepitation during clubbing"],"a":1,"e":"Answer- B. Early productive cough Cough is usually nonproductive, a productive cough is unusual Hemoptysis Wheezing Chest pain Clubbing can occur with interstitial lung disease.","pyqMatches":[{"year":"2013","no":1268,"q":"All of the following are features of interstitial lung disease except","o":["Exertional dyspnea","Early productive cough","Digital clubbing","Coarse crepitation during clubbing"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3127, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 691, '{"id":3127,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":691,"q":"Chest X-ray shows B/L lung infiltrates next investigation is","o":["Sputum examination","CT","Bronchoscopy","Antibiotics"],"a":1,"e":"Answer- B. CT Presence of B/L lung infiltrates suggests interstitial lung disease. High resolution computed tomography (HRCT) is obtained in almost all patients with diffuse pulmonary parenchymal disease.","pyqMatches":[{"year":"2013","no":1269,"q":"Chest X-ray shows B/L lung infiltrates next investigation is","o":["Sputum examination","CT","Bronchoscopy","Antibiotics"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3128, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 692, '{"id":3128,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":692,"q":"Drug of choice in interstitial lung disease is","o":["Antibiotics","Steroid","Bronchodilators","Aspirin"],"a":1,"e":"Answer- B. Steroid The usual initial treatment is \"oral prednisolone\". For severe disease, - \"Pulse methylprednisolone\" is used.","pyqMatches":[{"year":"2013","no":1271,"q":"Drug of choice in interstitial lung disease is","o":["Antibiotics","Steroid","Bronchodilators","Aspirin"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3129, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 693, '{"id":3129,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":693,"q":"Last stage of acute asthma is","o":["Hypocapnia","Hypercapnia","Hyperoxia","Alkalosis"],"a":1,"e":"Answer- B. Hypercapnia Late stages of Asthma are characterized by \"hypercapnia\". In asthma patients with impending respiratory failure the CO, level exceeds 45 mmHg.","pyqMatches":[{"year":"2013","no":1272,"q":"Last stage of acute asthma is","o":["Hypocapnia","Hypercapnia","Hyperoxia","Alkalosis"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3130, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 694, '{"id":3130,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":694,"q":"AGN (acute glomerulonephritis) is diagnosed by","o":["Hyaline cast","WBC cast","RBC cast","Granular cast"],"a":2,"e":"Answer- C. RBC cast Presence of RBC casts in urine is characteristic of nephritic syndrome due to glomerulonephritis.","pyqMatches":[{"year":"2013","no":1273,"q":"AGN (acute glomerulonephritis) is diagnosed by","o":["Hyaline cast","WBC cast","RBC cast","Granular cast"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3131, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 695, '{"id":3131,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":695,"q":"Cystatin C levels are used in urology for","o":["Detecting UTI","Estimating GFR","Estimating difference betwen CRF and ARF","Screening of Rena Ca"],"a":1,"e":"Answer- B. Estimating GFR GFR estimations determined by creatinine based equations are not precise, so other substances such as \"cystatin C\" are being explored to estimate GFR.","pyqMatches":[{"year":"2013","no":1274,"q":"Cystatin C levels are used in urology for","o":["Detecting UTI","Estimating GFR","Estimating difference betwen CRF and ARF","Screening of Rena Ca"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3132, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 696, '{"id":3132,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":696,"q":"Which is not seen in distal RTA","o":["Urine pH < 5.5","Hypokalemia","Hypercalciuria","Nephrolithiasis"],"a":0,"e":"Answer- A. Urine pH < 5.5 Normal anion gap metabolic acidosis/acidemia Hypokalemia Urinary stone formation (related to alkaline urine, hypercalciuria, and low urinary citrate). Nephrocalcinosis (deposition of calcium in the substance of the kidney) Bone demineralisation (causing rickets in children and osteomalacia in adults)","pyqMatches":[{"year":"2013","no":1275,"q":"Which is not seen in distal RTA","o":["Urine pH < 5.5","Hypokalemia","Hypercalciuria","Nephrolithiasis"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3133, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 697, '{"id":3133,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":697,"q":"Which of the following is not a feature of distal renal tubular acidosis","o":["Normal anion gap","Renal hypercalciuria","Alkaline urine","Hyperkalemia"],"a":0,"e":"Answer- A. Normal anion gap Normal anion gap metabolic acidosis/acidemia Hypokalemia Urinary stone formation (related to alkaline urine, hypercalciuria, and low urinary citrate). Nephrocalcinosis (deposition of calcium in the substance of the kidney) Bone demineralisation (causing rickets in children and osteomalacia in adults)","pyqMatches":[{"year":"2013","no":1276,"q":"Which of the following is not a feature of distal renal tubular acidosis","o":["Normal anion gap","Renal hypercalciuria","Alkaline urine","Hyperkalemia"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3134, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 698, '{"id":3134,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":698,"q":"Hyperkalemia aciduria is seen in","o":["Type I RTA","Type II RTA","Type IV RTA","Sigmoidocolostomy"],"a":2,"e":"Answer- C. Type IV RTA Type 4 RTA is due either to a deficiency of Aldosterone or to a resistance to its effects. It was included in the classification of renal tubular acidoses as it is associated with a mild (normal anion gap) metabolic acidosis (hyperchloremic acidosis) due to a physiological reduction in proximal tubular ammonium excretion (impaired ammoniagenesis), which is secondary to hypoaldosteronism, and results in a decrease in urine buffering capacity.","pyqMatches":[{"year":"2013","no":1277,"q":"Hyperkalemia aciduria is seen in","o":["Type I RTA","Type II RTA","Type IV RTA","Sigmoidocolostomy"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3135, 'Medicine', 'Endocrinology', 'Hard', 'Internal_Medicine', 699, '{"id":3135,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":699,"q":"A patient with diabetes, hyperkalemia, urinary pH < 5.5 Cause is","o":["Uremia","Pseudohyperaldosteronism","Type I Renal tubular acidosis","Type IV RTA"],"a":3,"e":"Answer- D. Type IV RTA Hyperkalemia with urinary pH < 5.5 along with diabetes suggests type IV renal tubular acidosis.","pyqMatches":[{"year":"2013","no":1278,"q":"A patient with diabetes, hyperkalemia, urinary pH < 5.5 Cause is","o":["Uremia","Pseudohyperaldosteronism","Type I Renal tubular acidosis","Type IV RTA"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3136, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 700, '{"id":3136,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":700,"q":"Calciphylaxis is a severe life threatening condition which occurs is","o":["Parathyroidectomy","Medullary carcinoma thyroid","Hyperthyroidism","End stage Renal disease"],"a":3,"e":"Answer- D. End stage Renal disease Calciphylaxis is a rare and serious disorder characterized by systemic medial calcification of the arterioles that leads to ischemia and subcutaneous necrosis. Calciphylaxis is one of several types of extra-osseous calcification (which also includes intimal, medial, and valvular calcification) that may occur in patients with end-stage renal disease (ESRD). Calciphylaxis most common occurs in patients with ESRD who are on hemodialysis.","pyqMatches":[{"year":"2013","no":1279,"q":"Calciphylaxis is a severe life threatening condition which occurs is","o":["Parathyroidectomy","Medullary carcinoma thyroid","Hyperthyroidism","End stage Renal disease"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3137, 'Medicine', 'Rheumatology', 'Easy', 'Internal_Medicine', 701, '{"id":3137,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":701,"q":"The hallmark of henoch schonlein purpura is","o":["Palpable purpura","Abdominal pain","Arthritis","Renal dysfunction"],"a":0,"e":"Answer- A. Palpable purpura Palpable purpura is essential for diagnosis. Diagnosis is confirmed by presence of palpable purpura with normal platelet count along with one or more of the following : abdominal pain, arthralgia/arthritisand mesangial deposition of IgA.","pyqMatches":[{"year":"2013","no":1280,"q":"The hallmark of henoch schonlein purpura is","o":["Palpable purpura","Abdominal pain","Arthritis","Renal dysfunction"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3138, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 702, '{"id":3138,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":702,"q":"A:G maintained in","o":["Nephritic syndrome","Cirrhosis","Protein losing enteropathy","Multiple myeloma"],"a":0,"e":"Answer- A. Nephritic syndrome Decreased albumin/Globulin ratio is seen : Multiple myeloma or metastatics disease AIDS Renal disease Liver disease (cirrhosis) Intestinal disease (Protein losing enteropathy) Cachexic patient CHF A/G ratio is decreased in nephrotic syndrome.","pyqMatches":[{"year":"2013","no":1283,"q":"A:G maintained in","o":["Nephritic syndrome","Cirrhosis","Protein losing enteropathy","Multiple myeloma"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3139, 'Medicine', 'Neurology', 'Moderate', 'Internal_Medicine', 703, '{"id":3139,"subject":"Medicine","chapter":"Neurology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":703,"q":"Which is not a stroke","o":["TIA","Hemiplegia","SAH","Intracerebral hemorrhage"],"a":0,"e":"Answer- A. TIA Stroke occurs when poor blood flow to brain results in death of brain cells. Stroke is of two types :-","pyqMatches":[{"year":"2013","no":1284,"q":"Which is not a stroke","o":["TIA","Hemiplegia","SAH","Intracerebral hemorrhage"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3140, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 704, '{"id":3140,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":704,"q":"The features of Cushing triad are all except","o":["Bradycardia","Hypotension","Irregular breathing","Hypertension"],"a":3,"e":"Answer- D. Hypertension Cushing''s triad is a sign of increased intracranial pressure. It is the triad of : - Hypertension, Bradycardia and Irregular breathing","pyqMatches":[{"year":"2013","no":1286,"q":"The features of Cushing triad are all except","o":["Bradycardia","Hypotension","Irregular breathing","Hypertension"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3141, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 705, '{"id":3141,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":705,"q":"Alice in wonderland syndrome occurs in","o":["SSPE","Epilepsy","Cerebral hemorrhage","Multiple sclerosis"],"a":1,"e":":C Answer- (B) Epilepsy & (C) Cerebral hemorrhage Infectious : CMV, EBV (IMN), Influenza A encephalitis, coxsackie B1 encephalitis, scarlet fever, typhoid encephalopathy, VZV encephalitis. CNS lesions :- Acute disseminated encephalomyelitis, cavernous angioma, cerebral arteriosclerosis, brain tumor, cerebral hemorrhage. Paroxysmal neurological disorders : Epilepsy (temporal lobe epilepsy), migraine1","pyqMatches":[{"year":"2013","no":1287,"q":"Alice in wonderland syndrome occurs in","o":["SSPE","Epilepsy","Cerebral hemorrhage","Multiple sclerosis"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3142, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 706, '{"id":3142,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":706,"q":"Water shed infarct in brain","o":["Occurs in the proximal portion of main arteries","Occurs in the central portion of main arteries","Occurs in the terminal portion of main arteries","Any of the above"],"a":2,"e":"Answer- C. Occurs in the terminal portion of main arteries Border zone or watershed infarcts are ischemic lesion that occurs in characteristic location at the junction between two main arterial territories. Watershed strokes are named that way because they affect the watershed areas of the brain. These areas are thin strips of brain which are sandwiched in between the farthest end branches of two adjacent vascular territories.","pyqMatches":[{"year":"2013","no":1290,"q":"Water shed infarct in brain","o":["Occurs in the proximal portion of main arteries","Occurs in the central portion of main arteries","Occurs in the terminal portion of main arteries","Any of the above"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3143, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 707, '{"id":3143,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":707,"q":"In Wilsons disease copper deposition occurs in","o":["Pons","Medulla","Cerebellum","Basal ganglia"],"a":3,"e":"Answer- D. Basal ganglia In brain, the toxic injury primarily affects the basal ganglia particularly the putamen which demonstrates atrophy and cavitation.","pyqMatches":[{"year":"2013","no":1291,"q":"In Wilsons disease copper deposition occurs in","o":["Pons","Medulla","Cerebellum","Basal ganglia"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3144, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 708, '{"id":3144,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":708,"q":"Abdominojugular reflex appears after compressing abdomen for","o":["5 sec","10 sec","15 sec","30 sec"],"a":2,"e":"Answer- C. 15 sec This is done by applying firm pressure with the palm of the hand to the right upper quadrant of the abdomen for 10-15 seconds with the patients breathing quietly while the jugular vein is observed. A positive abdominojugular reflux sign is defined by an increase in the jugular venous pressure of greater than 3 cm, sustained for greater than 15 seconds.","pyqMatches":[{"year":"2013","no":1294,"q":"Abdominojugular reflex appears after compressing abdomen for","o":["5 sec","10 sec","15 sec","30 sec"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3145, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 709, '{"id":3145,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":709,"q":"Genitourinary complication of ulcerative colitis","o":["Cystitis","Pyelonephritis","Urinary calculi","Urethritis"],"a":2,"e":"Answer- C. Urinary calculi Urinary calculi (oxalate stones in ileal disease), local extension of Crohn disease involving ureter or bladder, amyloidosis, drug-related nephrotoxicity.","pyqMatches":[{"year":"2013","no":1296,"q":"Genitourinary complication of ulcerative colitis","o":["Cystitis","Pyelonephritis","Urinary calculi","Urethritis"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3146, 'Medicine', 'Gastroenterology', 'Moderate', 'Internal_Medicine', 710, '{"id":3146,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":710,"q":"Liver biopsy indication is all except","o":["Amoebic hepatitis","Wilson''s disease","Chronic hepatitis B and C","Autoimmune hepatitis"],"a":0,"e":"Answer- A. Amoebic hepatitis Grading and staging of chronic hepatitis B and C Diagnosis of : Hemochromatosis (quantitative estimation of hepatic iron) Wilson''s disease (quantitative hepatic copper) Focal liver lesions Evaluation of : Cholestatic liver disease : Primary biliary cirrhosis, primary sclerosing cholangitis Abnormal liver biochemical tests in a patient with a negative or inconclusive serologic work-up Treatment efficacy Side effects of treatment regimens (such as methotrexate for rheumatoid arthritis) Post liver transplant by protocol or for evaluation of abnormal liver biochemical tests Donor liver Fever of unknown origin","pyqMatches":[{"year":"2013","no":1297,"q":"Liver biopsy indication is all except","o":["Amoebic hepatitis","Wilson''s disease","Chronic hepatitis B and C","Autoimmune hepatitis"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3147, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 711, '{"id":3147,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":711,"q":"Use of spironolactone in liver cirrhosis is","o":["Decrease edema","Improves liver function","Decrease afterload","Decrease intravascular volume"],"a":0,"e":"Answer- A. Decrease edema Treatment of ascites in patient with cirrhosis is aimed at the underlying cause of the hepatic disease and at the sodium water retention Diuretic therapy typically consists of treatment with spironolactone and furosemide in a ratio of 100: 40 mg/day with doses titrated upward as needed (upto 400 mg spironolactone and furosemide in a ratio of 100 : 40 mg/day).","pyqMatches":[{"year":"2013","no":1298,"q":"Use of spironolactone in liver cirrhosis is","o":["Decrease edema","Improves liver function","Decrease afterload","Decrease intravascular volume"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3148, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 712, '{"id":3148,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":712,"q":"Pea soup diarrhea is seen in -","o":["Cholera","Typhoid","Yersinosis","Hepatitis"],"a":1,"e":"Answer- B. Typhoid Pea Soup diarrhoea is characteristic of salmonella infection. About 2 weeks after infection with salmonella typhi most people suffering from typhoid develop a yellow green foul liquid stool that resembles pea soup in appearance i.e., pea soup stool.","pyqMatches":[{"year":"2013","no":1299,"q":"Pea soup diarrhea is seen in","o":["Cholera","Typhoid","Yersinosis","Hepatitis"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3149, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 713, '{"id":3149,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":713,"q":"Most significant risk factor for development for gastric carcinoma is","o":["Paneth cell metplasia","Pyloric metaplasia","Intestinal metaplasia","Ciliated metaplasia"],"a":2,"e":"Answer- C. Intestinal metaplasia A) Environmental factors B) Host factors : Chronic gastritis (causing hypochlorhydria or intestinal metaplasia), partial gastrectomy, gastric adenoma, Barrett''s esophagus, and Menetrier disease. Intestinal metaplasia is the most significant precursor lesion for Gastric cancer C) Genetic factors","pyqMatches":[{"year":"2013","no":1301,"q":"Most significant risk factor for development for gastric carcinoma is","o":["Paneth cell metplasia","Pyloric metaplasia","Intestinal metaplasia","Ciliated metaplasia"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3150, 'Medicine', 'Respiratory Medicine', 'Hard', 'Internal_Medicine', 714, '{"id":3150,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Hard","source":"Internal_Medicine","sourceNo":714,"q":"Adult male with chronic atrophic gastritis, growth on skirrows medium & rapid urease test positive. Diagnosis is","o":["H pylori","H. influnzae","K pneumonia","V. Cholarae"],"a":0,"e":"Answer- A. H pylori All favor the diagnosis of H pylori infection.","pyqMatches":[{"year":"2013","no":1302,"q":"Adult male with chronic atrophic gastritis, growth on skirrows medium & rapid urease test positive. Diagnosis is","o":["H pylori","H. influnzae","K pneumonia","V. Cholarae"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3151, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 715, '{"id":3151,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":715,"q":"Seen in SIADH","o":["Generalized edema","Ascites","Normal BP","Dry mucous membrane"],"a":2,"e":"Answer- C. Normal BP Hyponatremia (dilutional hyponatremia with Net'' < 135 mmol/L) Decreased plasma osmolality (<280 m osm/kg) with inappropriately increased urine osmolality > 150 m osm). High urine sodium (over 20 meq/1) Low blood urea nitrogen <10 mg/L Hypouricemia (<4 mg/dL) Clinical euvolemia","pyqMatches":[{"year":"2013","no":1303,"q":"Seen in SIADH","o":["Generalized edema","Ascites","Normal BP","Dry mucous membrane"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3152, 'Medicine', 'Rheumatology', 'Hard', 'Internal_Medicine', 716, '{"id":3152,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":716,"q":"A diabetic patient having sensory involvement, tingling, numbness, ankle swelling, no pain. Diagnosis is","o":["Charcots joint","Gout","Rheumatoid arthritis","Ankylosing spondylitis"],"a":0,"e":"Answer- A. Charcots joint It is a progressive destructive arthritis associated with loss of pain sensation°, proprioception° or both, in addition normal muscular reflexes that modulate joint movements are decreased. It is most commonly caused by diabetes mellitus. [Ref Harrison 18`5/e p. 2855, 2856; 17th/e p. 2180-2181]","pyqMatches":[{"year":"2013","no":1304,"q":"A diabetic patient having sensory involvement, tingling, numbness, ankle swelling, no pain. Diagnosis is","o":["Charcots joint","Gout","Rheumatoid arthritis","Ankylosing spondylitis"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3153, 'Medicine', 'Endocrinology', 'Hard', 'Internal_Medicine', 717, '{"id":3153,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":717,"q":"Patient having Cushing syndrome due to adrenal tumor. Drug to be given","o":["Cortisol","Betamethasone","Ketoconazole","Fludrocortisones"],"a":2,"e":"Answer- C. Ketoconazole TREATMENT- Treatment of choice- removal of pituritary corticotrope tumour (transphenoidal approach) Pituitary irradiation Metyrapone and ketoconazole Adrenocortical carcinoma- mitotane","pyqMatches":[{"year":"2013","no":1305,"q":"Patient having Cushing syndrome due to adrenal tumor. Drug to be given","o":["Cortisol","Betamethasone","Ketoconazole","Fludrocortisones"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3154, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 718, '{"id":3154,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":718,"q":"Metabolic change in severe vomiting is","o":["Metabolic alkalosis","Respiratory alkalosis","Metabolic acidosis","Hyperkalemia"],"a":0,"e":"Answer- A. Metabolic alkalosis Persistent gastric vomiting leads to Hyponatremia Hypokalemia Hypochloremia Alkalosis","pyqMatches":[{"year":"2013","no":1306,"q":"Metabolic change in severe vomiting is","o":["Metabolic alkalosis","Respiratory alkalosis","Metabolic acidosis","Hyperkalemia"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3155, 'Medicine', 'Nephrology', 'Moderate', 'Internal_Medicine', 719, '{"id":3155,"subject":"Medicine","chapter":"Nephrology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":719,"q":"Treatment of hypercalcemia includes all except","o":["Steroids","Bisphosphonates","Phosphate","Strontium"],"a":3,"e":"Answer- D. Strontium Treatment of acute hypercalcemia Hydration with saline Forced diuresis: Saline plus loop diuretics (furosemide) Bisphosphonates (pamidronate, zoledronate) Calcitonin Special therapies: Phosphate (oral), glucocorticoids, dialysis","pyqMatches":[{"year":"2013","no":1307,"q":"Treatment of hypercalcemia includes all except","o":["Steroids","Bisphosphonates","Phosphate","Strontium"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3156, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 720, '{"id":3156,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":720,"q":"Myelodysplastic syndrome is common in which age group","o":["2-10yrs","15-20yrs","25-40 yrs","> 50yrs"],"a":3,"e":"Answer- D. > 50yrs Myelodysplastic syndrome occurs most commonly in older adults with median age at diagnosis in most cases of 65 years and a male preponderance. Onset of the disease earlier than age 50 is unusual.","pyqMatches":[{"year":"2013","no":1308,"q":"Myelodysplastic syndrome is common in which age group","o":["2-10yrs","15-20yrs","25-40 yrs","> 50yrs"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3157, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 721, '{"id":3157,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":721,"q":"The best drug to lower prolactin level in a female with infertility is","o":["Bromocriptine","GnRH","Testosterone","Corticosteroid"],"a":0,"e":"Answer- A. Bromocriptine The treatment of choice for prolactinoma is \"bromocriptine\". Bromocriptine is a dopamine agonist which inhibits the secretion and synthesis of prolactin.","pyqMatches":[{"year":"2013","no":1309,"q":"The best drug to lower prolactin level in a female with infertility is","o":["Bromocriptine","GnRH","Testosterone","Corticosteroid"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3158, 'Medicine', 'Hematology', 'Moderate', 'Internal_Medicine', 722, '{"id":3158,"subject":"Medicine","chapter":"Hematology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":722,"q":"Which of the following is not commonly seen in Polycythemia Vera","o":["Thrombosis","Hyperuricemia","Prone for acute leukemia","Spontaneous severe infection"],"a":3,"e":"Answer- D. Spontaneous severe infection Clinical features- Hyperviscosity, hypovolaemia, hypermetabolism, erythocytosis, thrombosis. Headache, vertigo, tinnitus, syncope or even coma, transient visual loss Splenomegaly, haemtemesis and melena, bleeding. Pruritis & peptic ulceration (basophilia with histamine release) Hyperuricaemia- urate stones and gout","pyqMatches":[{"year":"2013","no":1310,"q":"Which of the following is not commonly seen in Polycythemia Vera","o":["Thrombosis","Hyperuricemia","Prone for acute leukemia","Spontaneous severe infection"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3159, 'Medicine', 'Hematology', 'Easy', 'Internal_Medicine', 723, '{"id":3159,"subject":"Medicine","chapter":"Hematology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":723,"q":"Evans syndrome is","o":["Anemia and thrombocytopenia","Pancytopenia","Lymphopenia and anemia","Thrombocytosis and lymphocytosis"],"a":0,"e":"Answer- A. Anemia and thrombocytopenia Evans syndrome (ES) refers to the combination of Coombs-positive warm autoimmune hemolytic anemia (AIHA) and immune thrombocytopenia (ITP), although, less commonly, some patients will also have autoimmune neutropenia (15 percent in one series).","pyqMatches":[{"year":"2013","no":1311,"q":"Evans syndrome is","o":["Anemia and thrombocytopenia","Pancytopenia","Lymphopenia and anemia","Thrombocytosis and lymphocytosis"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3160, 'Medicine', 'Respiratory Medicine', 'Moderate', 'Internal_Medicine', 724, '{"id":3160,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":724,"q":"All are major complications of massive transfusion except","o":["Hypokalemia","Hypothermia","Hypomagnesemia","Hypocalcemia"],"a":0,"e":"Answer- A. Hypokalemia Complications of Massive transfusion : - Coagulopathy Citrate toxicity Hypothermia Metabolic alkaptosis Hyperkalemia Acute respiratory distress syndrome Coagulation factor depletion","pyqMatches":[{"year":"2013","no":1312,"q":"All are major complications of massive transfusion except","o":["Hypokalemia","Hypothermia","Hypomagnesemia","Hypocalcemia"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3161, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 725, '{"id":3161,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":725,"q":"Regarding MSUD which is not true","o":["Deficiency of branched chain amino acid enzymes","Hyperaminoaciduria","Asymptomatic","FeC13 turns navyblue"],"a":2,"e":"Answer- C. Asymptomatic It is an inherited (autosomal recessive) disorder of branched chain amino acid i.e. - Valine, Leucine and Isoleucine. Maple syrup urine disease (MSUD) is d/t defect in enzyme - a-keto acid dehydrogenase. Diagnosis The keto acids may be detected by adding a few drops 2-4 din itrophenylhydrazine (DNPH) reagent which produces a yellow precipitate in positive test. Ferric chloride gives navy blue colour with the patients urine.","pyqMatches":[{"year":"2013","no":1314,"q":"Regarding MSUD which is not true","o":["Deficiency of branched chain amino acid enzymes","Hyperaminoaciduria","Asymptomatic","FeC13 turns navyblue"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3162, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 726, '{"id":3162,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":726,"q":"Result of liquorice ingestion","o":["Hyperkalemic alkalosis","Hypokalemic alkalosis","Hypokalemic acidosis","Hypermalemic acidosis"],"a":1,"e":"Answer- B. Hypokalemic alkalosis Liquorice (Licorice) ingestion causes apparent mineralocorticoid excess (pseudohyperaldosteronism) due to inhibition of enzyme 11- 13-HSD. This causes metabolic alkalosis, hypokalemia and volume overload.","pyqMatches":[{"year":"2013","no":1315,"q":"Result of liquorice ingestion","o":["Hyperkalemic alkalosis","Hypokalemic alkalosis","Hypokalemic acidosis","Hypermalemic acidosis"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3163, 'Medicine', 'Hematology', 'Easy', 'Internal_Medicine', 727, '{"id":3163,"subject":"Medicine","chapter":"Hematology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":727,"q":"Most common carcinoma associated with RA","o":["Diffuse large B cell lymphoma","Large granular lymphocytic leukemia","Chronic lymphocytic leukemia","None of the above"],"a":1,"e":"Answer- B. Large granular lymphocytic leukemia Lymphogranular proliferation may be present in patients with Rheumatoid arthritis and in minority it will proceed to \"large granular lymphocytic leukemia\" in Rheumatoid arthritis","pyqMatches":[{"year":"2013","no":1316,"q":"Most common carcinoma associated with RA","o":["Diffuse large B cell lymphoma","Large granular lymphocytic leukemia","Chronic lymphocytic leukemia","None of the above"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3164, 'Medicine', 'Dermatology & Allergy', 'Moderate', 'Internal_Medicine', 728, '{"id":3164,"subject":"Medicine","chapter":"Dermatology & Allergy","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":728,"q":"Systemic sclerosis shows all except","o":["Acroosteolysis","Tufting","Calcinosis cutis","Digital ulcers"],"a":1,"e":"Answer- B. Tufting Skin involvement in systemic sclerosis Pruritus in the early stages Edema in the early stages Sclerodactyly Digital ulcers Pitting at the fingertips Telangiectasia Calcinosis cutis","pyqMatches":[{"year":"2013","no":1319,"q":"Systemic sclerosis shows all except","o":["Acroosteolysis","Tufting","Calcinosis cutis","Digital ulcers"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3165, 'Medicine', 'Endocrinology', 'Easy', 'Internal_Medicine', 729, '{"id":3165,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":729,"q":"Tetany is seen in","o":["Hypocalcemia","Hypercalcemia","Hypoparathyroidism","Hyperparathyroidism"],"a":0,"e":"Answe- A. Hypocalcemia Acute hypocalcemia directly increases peripheral neuromuscular irritability. Tetany consists of repetitive high frequency discharges after a single stimulus. Hyperexcitability ofperipheralneurons is probably the most important pathophysiologic effect of hypocalcemia.","pyqMatches":[{"year":"2012","no":1074,"q":"Tetany is seen in","o":["Respiratory alkalosis","Respiratory acidosis","Metabolic acidosis","Hyperkalemia"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2013","no":1320,"q":"Tetany is seen in","o":["Hypocalcemia","Hypercalcemia","Hypoparathyroidism","Hyperparathyroidism"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2012","2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3166, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 730, '{"id":3166,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":730,"q":"In inflammatory myopathy, which group of muscles is not affected","o":["Ocular","Facial","Proximal muscles of limb","Distal muscles of limb"],"a":2,"e":"Answer- C. Proximal muscles of limb Inflammatory myopathies represent the largest group of acquired and potentially treatable cause of skeletal muscle weakness. They are classified into three major groups :","pyqMatches":[{"year":"2013","no":1321,"q":"In inflammatory myopathy, which group of muscles is not affected","o":["Ocular","Facial","Proximal muscles of limb","Distal muscles of limb"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3167, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 731, '{"id":3167,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":731,"q":"Signs of Bartter''s syndrome -","o":["Hypokalemia","Hypernatremia","Hyperkalemia","Acidosis"],"a":0,"e":"Answer- A. Hypokalemia Inherited forms of hypochloremic metabolic alkalosis and hypokalemia without hypertension are due to genetic mutations of various ion transporters and channels of the thick ascending limb of Henle''s loop (TAL) and distal convoluted tubule (DCT). [Ref: Harrisons Principles of Internal Medicine, 18th Edition, Pages 2360, 61]","pyqMatches":[{"year":"2013","no":1325,"q":"Signs of Bartter''s syndrome","o":["Hypokalemia","Hypernatremia","Hyperkalemia","Acidosis"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3168, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 732, '{"id":3168,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":732,"q":"Description of Waterhouse Friedrich syndrome","o":["Adrenal hemorrhage post malignancy","Congenital adrenals deficiency","Adrenal hemorrhage after meningococcal infection","Adrenal hemorrhage after corticosteroid withdrawal"],"a":2,"e":"Answer- C. Adrenal hemorrhage after meningococcal infection Waterhouse Friderichsen syndrome or massive adrenal hemorrhage is an uncommon usually fatal consequence of overwhelling sepsis. It is most frequently seen as a result of \"meningococcal infection\".","pyqMatches":[{"year":"2013","no":1327,"q":"Description of Waterhouse Friedrich syndrome","o":["Adrenal hemorrhage post malignancy","Congenital adrenals deficiency","Adrenal hemorrhage after meningococcal infection","Adrenal hemorrhage after corticosteroid withdrawal"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3169, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 733, '{"id":3169,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":733,"q":"In total parenteral nutrition, no need to measure daily","o":["Electrolyte","Fluid intake and output","LFT albumin","Magnesium"],"a":2,"e":"Answer- C. LFT albumin Monitoring of parenteral nutrition daily :- Measurement of fluid intake and output Serum electrolyte Glucose Calcium Magnesium Phosphate Monitor the following parameters weekly :- Aminotransferase Bilirubin Triglycerides","pyqMatches":[{"year":"2013","no":1329,"q":"In total parenteral nutrition, no need to measure daily","o":["Electrolyte","Fluid intake and output","LFT albumin","Magnesium"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3170, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 734, '{"id":3170,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":734,"q":"Drug of choice for kala-azar is","o":["Antimonials","Amphotericin B","Quinine","Parmomycin"],"a":0,"e":"Answer- A. Antimonials First line : Pentavalent antimony (Sodium stibogluconateis the drug of choice), and amphotericin-B. Alternatives : Paromomycin, pentamidine, miltefosine, sitamoquine","pyqMatches":[{"year":"2013","no":1331,"q":"Drug of choice for kala-azar is","o":["Antimonials","Amphotericin B","Quinine","Parmomycin"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3171, 'Medicine', 'Neurology', 'Moderate', 'Internal_Medicine', 735, '{"id":3171,"subject":"Medicine","chapter":"Neurology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":735,"q":"DMD not seen is","o":["Muscle pseudo hypertrophy","Weakness","Tenderness","Cardiomyopathy"],"a":2,"e":"Answer- C. Tenderness DMD, also called peudohypertrophic mucular dystrophy, is the most common hereditary neuromuscular dystrophy. It is an X-linked recessivedisorder. It is caused by a mutation in gene responsible for producing dystrophin (a sarcolemmal protein). There is progressive muscle weakness affecting proximal muscles of limbs. Child walks clumsily, has difficulty in climbing stairs and the gait is waddling (Trendelenburg). Scoliosis, epilepsy and mild mental retardation","pyqMatches":[{"year":"2013","no":1333,"q":"DMD not seen is","o":["Muscle pseudo hypertrophy","Weakness","Tenderness","Cardiomyopathy"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3172, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 736, '{"id":3172,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":736,"q":"Most sensitive test for myaesthenia gravis","o":["Edrophonium test","Single fibre EMG","Multiple fibre EMG","Repetitive nerve stimulation"],"a":1,"e":"Answer- B. Single fibre EMG Diagnosis- Anti- AchR radioimmunoassay Electrophysiological testing Single- fibre electromyography (most sensitive)","pyqMatches":[{"year":"2013","no":1334,"q":"Most sensitive test for myaesthenia gravis","o":["Edrophonium test","Single fibre EMG","Multiple fibre EMG","Repetitive nerve stimulation"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3173, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 737, '{"id":3173,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":737,"q":"Dyslipidemia associated with alcohol consumption","o":["Decreased HDL","Increased HDL","Decreased triglycerase","Decreased lipoprotein"],"a":1,"e":"Answer- B. Increased HDL Serem HDL cholesterol increases by 4.0 mg/dl (.1mmol/L) Serum apolipoprotein A.1 increase by 8.8 mg/dl Serum Triglyceride increases by 5-4 mg mg/dl","pyqMatches":[{"year":"2013","no":1336,"q":"Dyslipidemia associated with alcohol consumption","o":["Decreased HDL","Increased HDL","Decreased triglycerase","Decreased lipoprotein"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3174, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 738, '{"id":3174,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":738,"q":"Migraine is due to","o":["Dilatation of cranial arteries","Constriction of cranial arteries","Cortical spreading depression","Meningial inflammation"],"a":2,"e":"Answer- C. Cortical spreading depression Cortical spreading depression is a self propagating wave of neuronal and glial depolarization that spreads across the cerebral cortex. The activation of trigeminal afferents by cortical spreading depression in turn causes inflammatory changes in the pain- sensitive meninges that generate the headache of migraine through central and peripheral reflex mechanisms.","pyqMatches":[{"year":"2012","no":1089,"q":"Migraine is due to","o":["Dilatation of cranial arteries","Constriction of cranial arteries","Cortical spreading depression","Meningial inflammation"],"a":2,"source":"NEET_2012_Paper.pdf"},{"year":"2013","no":1337,"q":"Migraine is due to","o":["Dilatation of cranial arteries","Constriction of cranial arteries","Cortical spreading depression","Meningial inflammation"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2012","2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3175, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 739, '{"id":3175,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":739,"q":"-30° to -60° left axis deviation is seen in","o":["Left ventricular hypertrophy","Right ventricular hypertrophy","Aortic stenosis","Left atrial enlargement"],"a":0,"e":"Answer- A. Left ventricular hypertrophy Normally, QRS axis ranges from -30° to 90°C An axis more negative than -30° is referred to as left axis deviation and an axis more positive than +100° is called right axis deviation Left axis deviation Axis more negative than -30° Associated with Left ventricular hypertrophy Left anterior fascicular block Inferior M.I.","pyqMatches":[{"year":"2012","no":1010,"q":"30° to -60° left axis deviation is seen in","o":["Left ventricular hypertrophy","Right ventricular hypertrophy","Aortic stenosis","Left atrial enlargement"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3176, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 740, '{"id":3176,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":740,"q":"Which is increased in plasma of chronic heart disease pts","o":["BNP","Endothelin 1","Cortisol","None"],"a":0,"e":"Answer- A. BNP The plasma concentrations of both hormones are increased in patients with asymptomatic and symptomatic left ventricular dysfunction, permitting their use in diagnosis. BNP levels are simple and objective measures of cardiac function. These measures can be used to diagnoose heart failure including diastolic function.","pyqMatches":[{"year":"2012","no":1015,"q":"Which is increased in plasma of chronic heart disease pts","o":["BNP","Endothelin 1","Cortisol","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3177, 'Medicine', 'Respiratory Medicine', 'Hard', 'Internal_Medicine', 741, '{"id":3177,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Hard","source":"Internal_Medicine","sourceNo":741,"q":"In asthma diagnosis is by","o":["FEVi","Measurement of tidal volume","End expiratory flow rate","Total lung capacity"],"a":0,"e":"Answer- A. FEVi Asthma is classified according to the frequency of symptoms, forced expiratory volume in one second (FEV1), and peak expiratory flow rate. Spirometry is recommended to aid in diagnosis and management. It is the single best test for asthma. If the FEV1 measured by this technique improves more than 12% and increases by at least 200 milliliters following administration of a bronchodilator such as salbutamol, this is supportive of the diagnosis.","pyqMatches":[{"year":"2012","no":1016,"q":"In asthma diagnosis is by","o":["FEVi","Measurement of tidal volume","End expiratory flow rate","Total lung capacity"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3178, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 742, '{"id":3178,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":742,"q":"A person has asthma attacks more than once during day and once during night","o":["Mild intermittent asthma","Mild persistent asthma","Moderate asthma","Severe asthma"],"a":3,"e":"Answer- D. Severe asthma Severe asthma Symptoms- Throughout day Night awakenings- Daily Short-acting B2-agonist use for symptom control-Several times per day Interference with normal activity- Extreme limitation FEV1- < 60% FEV1 /FVC= > 5% reduced","pyqMatches":[{"year":"2012","no":1017,"q":"A person has asthma attacks more than once during day and once during night","o":["Mild intermittent asthma","Mild persistent asthma","Moderate asthma","Severe asthma"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3179, 'Medicine', 'Infectious Diseases', 'Hard', 'Internal_Medicine', 743, '{"id":3179,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Hard","source":"Internal_Medicine","sourceNo":743,"q":"A child presents with recurrent pulmonary infections for hemoptysis due to associated bronchiectasia and on imaging characterized by unilateral loss of lung volume with hyperlucency on chest radiograph, reduction in vascularity on CT scan of the chest. The abdominal organs are normally place (d) most lilkely cause is","o":["Kartagener''s syndrome","Swyer-James-MacLeod syndrome","Mendelson''s syndrome","Immotile cilia syndrome"],"a":1,"e":"Answer- B. Swyer-James-MacLeod syndrome Swyer-James-MacLeod syndrome or unilateral h erlucent lun ndrome is a rare entity associated with postinfectious bronchiolitis obliterans occurring in childhood. It is characterized by hypoplasia and/or agenesis of the pulmonary arteries resulting in pulmonary parenchyma hypoperfusion, showing a characteristic radiological pattern, such as translucent or hyperlucent unilateral lung.","pyqMatches":[{"year":"2012","no":1019,"q":"A child presents with recurrent pulmonary infections for hemoptysis due to associated bronchiectasia and on imaging characterized by unilateral loss of lung volume with hyperlucency on chest radiograph, reduction in vascularity on CT scan of the chest. The abdominal organs are normally place (d) most lilkely cause is","o":["Kartagener''s syndrome","Swyer-James-MacLeod syndrome","Mendelson''s syndrome","Immotile cilia syndrome"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3180, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 744, '{"id":3180,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":744,"q":"Fibrosis of upper lobe is due to","o":["Pneumonia","ABPA","Bronchiectasis in COPD","Rheumatoid arthritis"],"a":1,"e":"Answer- B. ABPA Silicosis (Progressive massive fibrosis Sarcoidosis Coal worker pneumoconiosis Ankylosing spondylitis Radiation Allergic bronchopulmonary aspergillosis Tuberculosis Extrinsic allergic alveolitis","pyqMatches":[{"year":"2012","no":1021,"q":"Fibrosis of upper lobe is due to","o":["Pneumonia","ABPA","Bronchiectasis in COPD","Rheumatoid arthritis"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3181, 'Medicine', 'Hematology', 'Moderate', 'Internal_Medicine', 745, '{"id":3181,"subject":"Medicine","chapter":"Hematology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":745,"q":"What is not seen in CRF","o":["Hypercalcemia","Hyperkalemia","Hyperphosphatemia","Hypocalcemia"],"a":0,"e":"Answer- A. Hypercalcemia Abnormalities seen in CRF Acidosis Hyperkalemia Anemia Hypernatremia Hyperphosphatemia Hyperlipidemia Hyponatremia Hypocalcemia Uremia","pyqMatches":[{"year":"2012","no":1022,"q":"What is not seen in CRF","o":["Hypercalcemia","Hyperkalemia","Hyperphosphatemia","Hypocalcemia"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3182, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 746, '{"id":3182,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":746,"q":"Maximum urinary catheter induced infection","o":["E.coli","Pseudomonas","Staphylococcus epidermidis","Proteus"],"a":0,"e":"Answer- A. E.coli Catheter associated urinary tract infections represent the most common type of nosocomial infection. Most common organism causing catheter associated urinary tract infections are E.coli.","pyqMatches":[{"year":"2012","no":1028,"q":"Maximum urinary catheter induced infection","o":["E.coli","Pseudomonas","Staphylococcus epidermidis","Proteus"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3183, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 747, '{"id":3183,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":747,"q":"Most common symptom of genitourinary TB","o":["Renal colic","Increased frequency","Hematuria","Painful micturition"],"a":1,"e":"Answer- B. Increased frequency The clinical manifestations are variable. The onset of clinically evident genitourinary tuberculosis is usually insidious. The most common symptoms are :- Dysuria, increased frequency of urination and gross hematuria","pyqMatches":[{"year":"2012","no":1029,"q":"Most common symptom of genitourinary TB","o":["Renal colic","Increased frequency","Hematuria","Painful micturition"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3184, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 748, '{"id":3184,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":748,"q":"Anominal aphasia is due to defect in","o":["Left inferior frontal","Parietal","Temporal occipital","Cerebellum"],"a":2,"e":"Answer- C. Temporal occipital Anomia can be genetic or caused by damage to various parts of the parietal lobe or the temporal lobe of the brain by an accident or stroke, or a brain tumor.","pyqMatches":[{"year":"2012","no":1041,"q":"Anominal aphasia is due to defect in","o":["Left inferior frontal","Parietal","Temporal occipital","Cerebellum"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3185, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 749, '{"id":3185,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":749,"q":"Unable to consolidate long term memory. Which lobe of the brain is involved","o":["Frontal","Parietal","Temporal","Occipital"],"a":2,"e":"Answer- C. Parietal Medial temporal lobe is the area of brain responsible for consolidation, i.e. processing of short term memory into long term memory.","pyqMatches":[{"year":"2012","no":1042,"q":"Unable to consolidate long term memory. Which lobe of the brain is involved","o":["Frontal","Parietal","Temporal","Occipital"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3186, 'Medicine', 'Miscellaneous', 'Moderate', 'Internal_Medicine', 750, '{"id":3186,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":750,"q":"Gerstmanns syndrome all except","o":["Acalculia","Agraphia","Aphasia","Agnosia"],"a":2,"e":"Answer- C. Aphasia Gerstmann syndrome consists of :","pyqMatches":[{"year":"2012","no":1043,"q":"Gerstmanns syndrome all except","o":["Acalculia","Agraphia","Aphasia","Agnosia"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3187, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 751, '{"id":3187,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":751,"q":"Pontine hemorrhage most common cause is","o":["Hypertension","Diabetes","Trauma","Aneurysmal rupture"],"a":0,"e":"Answer- A. Hypertension Most common cause of pontine hemorrhage is hypertension.","pyqMatches":[{"year":"2012","no":1045,"q":"Pontine hemorrhage most common cause is","o":["Hypertension","Diabetes","Trauma","Aneurysmal rupture"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3188, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 752, '{"id":3188,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":752,"q":"Daily temperature variation in remmitent fever is","o":["< 0.5 C","> 1°C","< 1.0 C","> 2 C"],"a":1,"e":"Answer- B. > 1°C Continuous fever Temperature remains above normal throughout the day and does not fluctuate more than 1°C in 24 hours. Intermittent fever The temperature elevation is present only for a certain period, later back to normal e.g. malaria, kala azar septicaemia.","pyqMatches":[{"year":"2012","no":1048,"q":"Daily temperature variation in remmitent fever is","o":["< 0.5 C","> 1°C","< 1.0 C","> 2 C"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3189, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 753, '{"id":3189,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":753,"q":"Hyperthermia","o":["Temperature > 41.5","> 40 with autonomic dysfunctuion","No change in hypothalamic thermostat","Failure of thermoregulation"],"a":3,"e":"ANswer- D. Failure of thermoregulation Hyperthermia is defined as elevation of core body temperature above the normal diurnal range of 36 to 37.5°C due to failure of thermoregulation at the level of hypothalamus. Hyperthermia is not synonymous with the more common sign offever, which is induced by cytokine activation during inflammation, and regulated at the level of the hypothalamus.","pyqMatches":[{"year":"2012","no":1049,"q":"Hyperthermia","o":["Temperature > 41.5","> 40 with autonomic dysfunctuion","No change in hypothalamic thermostat","Failure of thermoregulation"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3190, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 754, '{"id":3190,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":754,"q":"Myasthenia gravis is associated with","o":["Antibodies against Ach receptors","Decreased myosin","Absent troponin C","Increased myoneural junction transmission"],"a":0,"e":"Answer- A. Antibodies against Ach receptors The characteristic pathological feature of myasthenia gravis is presence of antibodies against acetyl choline receptors. These autoantibodies against the acetylcholine receptors lead to loss of functional acetylcholine receptors at the neuro muscular junction.","pyqMatches":[{"year":"2012","no":1050,"q":"Myasthenia gravis is associated with","o":["Antibodies against Ach receptors","Decreased myosin","Absent troponin C","Increased myoneural junction transmission"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3191, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 755, '{"id":3191,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":755,"q":"Eaton Lambert syndrome is seen with -","o":["Ca breast","Ca liver","Ca lung","CNS tumors"],"a":2,"e":"Answer- C. Ca lung Paraneoplastic syndrome Associated with Small cell carcinoma lung Certain autoimmune diseases","pyqMatches":[{"year":"2012","no":1051,"q":"Eaton Lambert syndrome is seen with","o":["Ca breast","Ca liver","Ca lung","CNS tumors"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3192, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 756, '{"id":3192,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":756,"q":"Lesion of globus pallidus causes","o":["Chorea","Athetosis","Hemibalismus","Flexion dystonia"],"a":1,"e":"Answer- B. Athetosis Athetosis- Globus pallidus (mainly) and Subthalamic nucleus. Lesion at the globus pallidus and striatum cause athetosis, which is characterized by continuous, slow writhing movements. Chorea: rapid, involuntary dancing movements → Most commonly, the lesion is in the striatum. Ballism: involuntary flailing, intense and violent movements. The movements are of large amplitude and predominantly involves proximal muscles. The lesion in the subthalamic nucleus. Athetosis: continuous, slow writhing movements → Lesion at globus pallidus and striatum.","pyqMatches":[{"year":"2012","no":1052,"q":"Lesion of globus pallidus causes","o":["Chorea","Athetosis","Hemibalismus","Flexion dystonia"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3193, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 757, '{"id":3193,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":757,"q":"Most common tumor associated with NF 1","o":["Optic glioma","2nd nerve schwannoma","Astrocytoma","Bilateral acoustic neuroma"],"a":0,"e":"Answer- A. Optic glioma \"Optic pathway gliomas\" are the predominant type of neoplasm associated with neurofibromatosis type I but other central nervous system and non CNS tumours can occur.","pyqMatches":[{"year":"2012","no":1053,"q":"Most common tumor associated with NF 1","o":["Optic glioma","2nd nerve schwannoma","Astrocytoma","Bilateral acoustic neuroma"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3194, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 758, '{"id":3194,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":758,"q":"CSF picture in viral meningitis","o":["Lymphocytic pleocytosis","WBC count > 1500/mL","Sugar is reduced","Protein is decreased"],"a":0,"e":"Answer- A. Lymphocytic pleocytosis Normal Bacterial Viral Opening Pressure 7-18 >30 Normal or Mildly Incre AppearanceClear, ColorlessTurbid Clear Protein (mg/dl) 23-38 Increased Normal to Decreased Glucose (mmol/L) 2/3rds Serum Glucose Decreased Normal Gram Stain Negative Positive 160-90% of Cases) Negative Glucose CSF: Serum Ratio 0.6 <0.4 >0.6 White Cell Count cells Predominately NeutrophilsPredominately Lymph","pyqMatches":[{"year":"2012","no":1054,"q":"CSF picture in viral meningitis","o":["Lymphocytic pleocytosis","WBC count > 1500/mL","Sugar is reduced","Protein is decreased"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3195, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 759, '{"id":3195,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":759,"q":"In herpes encephalitis A/E","o":["Focal symptoms common","Temporal lobe involved","MRI is diagnostic","EEG not diagnostic"],"a":3,"e":"Answer- D. EEG not diagnostic Diagnosis Most sensitive and specific investigation for HSV-1 encephalitic is MRI In contrast, cranial CT scans have only 50% sensitivity and that too early in the disease. EEG findings in HSV-1 encephalitis","pyqMatches":[{"year":"2012","no":1055,"q":"In herpes encephalitis A/E","o":["Focal symptoms common","Temporal lobe involved","MRI is diagnostic","EEG not diagnostic"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3196, 'Medicine', 'Hematology', 'Moderate', 'Internal_Medicine', 760, '{"id":3196,"subject":"Medicine","chapter":"Hematology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":760,"q":"Which of the following provide protection against malaria all except","o":["Duffy blood group","Sickle cell anemia","Thalassemia","PNH"],"a":3,"e":"Answer- D. PNH Red cell surface antigen that offer protection against malaria Duffy blood group system ABO (H) blood group system Glycophorins Gerbich antigen Complement receptor type I Knops blood group Abnormalities of the red cell cytoskeleton which may offer protection include South-east asia ovalocytosis Hereditary elliptocytosis Hereditary spherocytosis Sickle cell HbA/S","pyqMatches":[{"year":"2012","no":1058,"q":"Which of the following provide protection against malaria all except","o":["Duffy blood group","Sickle cell anemia","Thalassemia","PNH"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3197, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 761, '{"id":3197,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":761,"q":"Richner-Hanhart syndrome is","o":["Autosomal dominant","Occular and cutaneous features","Associated with abnormality in lipid metabolism","Normal mental function"],"a":1,"e":"Answer- B. Occular and cutaneous features Rare autosomal recessive disorder of tyrosine metabolism due to deficiency of the cytosolic fraction of hepatic tyrosine amino transferase. Occurs due to deficiency of \"Tyrosine amino transferase\". Mental retardation. The patient has high urinary tyrosine levels along with high plasma tyrosine levels. These patients responds dramatically to dietary restriction of the amino acids phenylalanine and tyrosine","pyqMatches":[{"year":"2012","no":1065,"q":"Richner-Hanhart syndrome is","o":["Autosomal dominant","Occular and cutaneous features","Associated with abnormality in lipid metabolism","Normal mental function"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3198, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 762, '{"id":3198,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":762,"q":"Fabry''s disease affects","o":["ER","Lysosome","Mitochondria","Cell membrane"],"a":1,"e":"Answer- B. Lysosome Fabry disease, also called Anderson-Fabry disease, is the second most prevalent lysosomal storage disorder after Gaucher disease. It is an X-linked inborn error of the glycosphingolipid metabolic pathway. This results in accumulation of globotriaosylceramide (Gb3) within lysosomes in a wide variety of cells, thereby leading to the protean manifestations of the disease.","pyqMatches":[{"year":"2012","no":1070,"q":"Fabry''s disease affects","o":["ER","Lysosome","Mitochondria","Cell membrane"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3199, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 763, '{"id":3199,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":763,"q":"Calcium homeostasis disturbance is seen in","o":["Malignant hyperthermia","DMD","Tibial muscular dystrophy","Limb girdle muscle dystrophy"],"a":0,"e":"Answer- A. Malignant hyperthermia Malignant hyperthermia is a pharmacogenetic condition caused due to mutation of the \"Ryanodine receptor gene\". Ryanodine receptor gene controls the level of \"cytosolic calcium\" and therefore skeletal muscle contraction.","pyqMatches":[{"year":"2012","no":1073,"q":"Calcium homeostasis disturbance is seen in","o":["Malignant hyperthermia","DMD","Tibial muscular dystrophy","Limb girdle muscle dystrophy"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3200, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 764, '{"id":3200,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":764,"q":"Tetany is seen in","o":["Respiratory alkalosis","Respiratory acidosis","Metabolic acidosis","Hyperkalemia"],"a":0,"e":"Answer- A. Respiratory alkalosis In alkalosis tetany occurs because of the decreased concentration of free ionized calcium. It is the free ionized calcium that is physiologically more important. [Ref Harrison 18th/e p. 362, 360; Guyton 10thie p. 342]","pyqMatches":[{"year":"2012","no":1074,"q":"Tetany is seen in","o":["Respiratory alkalosis","Respiratory acidosis","Metabolic acidosis","Hyperkalemia"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2013","no":1320,"q":"Tetany is seen in","o":["Hypocalcemia","Hypercalcemia","Hypoparathyroidism","Hyperparathyroidism"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2012","2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3201, 'Medicine', 'Gastroenterology', 'Moderate', 'Internal_Medicine', 765, '{"id":3201,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":765,"q":"Hypomagnesemia is not seen in","o":["Barters syndrome","Diabetes mellitus","Diarrhea","Gitelman syndrome"],"a":0,"e":"Answer- A. Barters syndrome Hypomagnesemia may occur in Barter''s syndrome but usually the serum magnesium level is normal in Barters syndrome.","pyqMatches":[{"year":"2012","no":1075,"q":"Hypomagnesemia is not seen in","o":["Barters syndrome","Diabetes mellitus","Diarrhea","Gitelman syndrome"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3202, 'Medicine', 'Rheumatology', 'Easy', 'Internal_Medicine', 766, '{"id":3202,"subject":"Medicine","chapter":"Rheumatology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":766,"q":"Primary Sjogrens syndrome true is","o":["Can be seen in children","Increased complement C4 leads to thymoma","Associated with rheumatoid arthritis","Salivary gland enlargement"],"a":3,"e":"Answer- D. Salivary gland enlargement Sjogren syndrome is a chronic disease characterized by dry eyes (keratoconjuctivitis sicca) and dry mouth (xerostomia) resulting from immunological mediated destruction of the lacrimal and salivary glands. It occurs in two forms","pyqMatches":[{"year":"2012","no":1078,"q":"Primary Sjogrens syndrome true is","o":["Can be seen in children","Increased complement C4 leads to thymoma","Associated with rheumatoid arthritis","Salivary gland enlargement"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3203, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 767, '{"id":3203,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":767,"q":"Prophylaxis for HIV is optimally effective if started upto ..... hrs of exposure","o":["1","2","4","12"],"a":0,"e":"Answer- A. 1 goal is to start within one to two hours or earlier after exposure often using a starter pack with appropriate drugs as immediately available. The median time to initiation of postexposure prophylaxis is 1.8 hrs. The centre for disease control and prevention (CDC) recommendations are to offer prophylaxis upto 24-36 hrs after exposure, for longer time lapses, the recommendations is to seek advice from an expert","pyqMatches":[{"year":"2012","no":1079,"q":"Prophylaxis for HIV is optimally effective if started upto ..... hrs of exposure","o":["1","2","4","12"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3204, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 768, '{"id":3204,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":768,"q":"Odd pair","o":["Erythema marginatum-rheumatic fever","Erythema gyrens ripens-malignancy","Necrotic acral erythema-HCV","Erythema chronicum migrans malignancy"],"a":3,"e":"Answer- D. Erythema chronicum migrans malignancy \"Erythema gyratum repens\" is a rare and characteristic rash strongly associated with malignancy . Erythema chromicum nigrans Ergthema marginatum It is a characteristic cutaneous manifestation of rheumatic fever.","pyqMatches":[{"year":"2012","no":1080,"q":"Odd pair","o":["Erythema marginatum-rheumatic fever","Erythema gyrens ripens-malignancy","Necrotic acral erythema-HCV","Erythema chronicum migrans malignancy"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3205, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 769, '{"id":3205,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":769,"q":"Yellow-nail syndrome consists of","o":["Knee joint effusion and lymphedema, associated with discolored nails","Pericardial and lymphedema, associated with discolored nails","Peritoneal effusion and lymphedema, associated with discolored nails","Pleural effusion and lymphedema, associated with discolored nails"],"a":3,"e":"Answer- D. Pleural effusion and lymphedema, associated with discolored nails Yellow nail syndrome is a rare disorder of the nail, which is usually accompanied by Lymphoedema It may also be associated with : Recurrent pleural effusions Bronchiectasis","pyqMatches":[{"year":"2012","no":1082,"q":"Yellow-nail syndrome consists of","o":["Knee joint effusion and lymphedema, associated with discolored nails","Pericardial and lymphedema, associated with discolored nails","Peritoneal effusion and lymphedema, associated with discolored nails","Pleural effusion and lymphedema, associated with discolored nails"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3206, 'Medicine', 'Infectious Diseases', 'Moderate', 'Internal_Medicine', 770, '{"id":3206,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":770,"q":"Not to be given in malignant malaria is -","o":["Quinolone","Quinine","Doxycycline","Artesunate"],"a":0,"e":"Answer- A. Quinolone Artemisinin derivative : Artesunate Quinine or Quinidine Plus one of the following : Doxycycline, Tetracycline and Clindamycin","pyqMatches":[{"year":"2012","no":1083,"q":"Not to be given in malignant malaria is","o":["Quinolone","Quinine","Doxycycline","Artesunate"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3207, 'Medicine', 'Dermatology & Allergy', 'Easy', 'Internal_Medicine', 771, '{"id":3207,"subject":"Medicine","chapter":"Dermatology & Allergy","difficulty":"Easy","source":"Internal_Medicine","sourceNo":771,"q":"Muir–Torre syndrome shows","o":["Sebaceous keratomas","Lisch nodules","Intestinal polyp","Hyperelastic joints"],"a":0,"e":"Answer- A. Sebaceous keratomas Muir - Torre syndrome is an autosomal skin condition of genetic origin characterized by tumors of the sebaceous gland or keratoacanthoma that are associated with visceral malignant disease Cutaneous characteristic Adenoma Epithelioma Carcinoma Multiple keratoacanthomas","pyqMatches":[{"year":"2012","no":1084,"q":"Muir–Torre syndrome shows","o":["Sebaceous keratomas","Lisch nodules","Intestinal polyp","Hyperelastic joints"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3208, 'Medicine', 'Dermatology & Allergy', 'Easy', 'Internal_Medicine', 772, '{"id":3208,"subject":"Medicine","chapter":"Dermatology & Allergy","difficulty":"Easy","source":"Internal_Medicine","sourceNo":772,"q":"First symptom of leprosy","o":["Decreased vibration & position sense","Decreased pain","Decreased temperature","Decreased light touch"],"a":1,"e":"Answer- B. Decreased pain In 90% of patients the first sign of the disease is a feeling of numbers which may preceedes skin lesions by a number of years . Temperature is the first sensation lost followed by light tourch pain and then deep pressure. [Ref Harrison 18thie p. 1363-1364]","pyqMatches":[{"year":"2012","no":1087,"q":"First symptom of leprosy","o":["Decreased vibration & position sense","Decreased pain","Decreased temperature","Decreased light touch"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3209, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 774, '{"id":3209,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":774,"q":"Which of the following is endogenous pyrogen","o":["PG E2","PG D2","PGF2 alpha","PG I2"],"a":0,"e":"Answer: -A. PG E2 Pyrogen Pyrogens are substances that cause fever. Pyrogens may be exogenous or endogenous Exogenous → Bacterial toxins Endogenous → IL-1, TNF-a, IL-6, Interferons, Ciliary neurotrophic factor These pyrogens increase the level of PGE, in the hypothalamus that elevates the thermoregulatory set point and causes fever.","pyqMatches":[{"year":"2018","no":130,"q":"Which of the following is endogenous pyrogen","o":["PG E2","PG D2","PGF2 alpha","PG I2"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3210, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 775, '{"id":3210,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":775,"q":"In Bartter syndrome defect is seen in:","o":["Defect in PCT","Defect in DCT","Defect in thick ascending limb of loop of henle","None"],"a":2,"e":"Answer: C - Defect in thick ascending limb of loop of henle Autosomal recessive disorder. Genetic defect in the thick ascending limb of the loop of henle Defects in Na-K-2C/ coLtransporter, K or Cl channels result in lack of concentrating ability","pyqMatches":[{"year":"2018","no":131,"q":"In Bartter syndrome defect is seen in:","o":["Defect in PCT","Defect in DCT","Defect in thick ascending limb of loop of henle","None"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3211, 'Medicine', 'Respiratory Medicine', 'Moderate', 'Internal_Medicine', 776, '{"id":3211,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":776,"q":"Not seen in allergic pulmonary aspergillosis is","o":["High IgE level","Recurrent pneumonia","Occurrence in patients with old cavitary lesions","Pleural effusion"],"a":1,"e":"Answer: B-Recurrent pneumonia Allergic bronchopulmonary aspergillosis is a pulmonary hypersensitivity disorder caused by allergy to fungal antigens that colonize the tracheobronchial tree. It most commonly occurs in atopic asthmatic individuals in response to antigen of aspergillus species. Main diagnostic criteria Clinical history of Asthma Q Pulmonary infiltrates (transient /fleeting or fixed)Q Peripheral eosinophilia (> 1000 /,uL)Q Immediate skin reactivity to Aspergillus antigen (wheal and flare response) Serum precipitins to A. fumigatus Elevated serum IgE levels(>100Ong/ml) Central /proximal bronchiectasis Secondary diagnostic criteria History of brownish plugs in sputum Identification / culture of A., fumigatus from sputum Late skin reactivity to aspergillus antigen - CMDT Elevated IgE (and IgG) class antibodies specific for A. fumigatus - Harrisons Note Elevated IgE (and IgG) class antibodies specific for A. fumigatus has been mentioned as a secondary diagnostic criteria in Harrison''s textbook while Fishman''s textbook includes this as a main/major diagnostic criteria.","pyqMatches":[{"year":"2018","no":132,"q":"Not seen in allergic pulmonary aspergillosis is","o":["High IgE level","Recurrent pneumonia","Occurrence in patients with old cavitary lesions","Pleural effusion"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3212, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 777, '{"id":3212,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":777,"q":"Pseudo P Pulmonale","o":["Hypokalemia","Hyponatremia","Hypocalcemia","Hypercalcemia"],"a":0,"e":"Answer: A. Hypokalemia In some cases there can be a notched (or bifid) p-wave known as “p mitrale”, indicative of left atrial hypertrophy which may be caused by mitral stenosis. There may be tall peaked p-waves. This is called “p- pulmonale” and is indicative of right atrial hypertrophy often secondary to tricuspid stenosis or pulmonary hypertension. A similar picture can be seen in hypokalemia (known as “pseudo p- pulmonale”).","pyqMatches":[{"year":"2018","no":133,"q":"Pseudo P Pulmonale","o":["Hypokalemia","Hyponatremia","Hypocalcemia","Hypercalcemia"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3213, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 778, '{"id":3213,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":778,"q":"Automatic Implantable Cardioverter Defibrillator, (AICD) implantation is done for which of following conditions:","o":["Brugada syndrome","Ventricular fibrillation","Acute coronary syndrome with low EF","All of the above"],"a":3,"e":"Answer: D. All of the above An Automatic Implantable Cardioverter Defibrillator, (AICD), is a small electronic device that is implanted into your chest to monitor and correct an abnormal heart rhythm, or arrhythmia. These devices are used to treat serious and life-threatening arrhythmias and are the most effective way of doing so. Brugadasyndrome is a condition that causes a disruption of the heart''s normal rhythm. Ventricular fibrillation is a heart rhythm problem that occurs when the heart beats with rapid, erratic electrical impulse. Acute coronary syndrome is a term used to describe a range of conditions associated with sudden, reduced blood flow to the heart.","pyqMatches":[{"year":"2018","no":134,"q":"Automatic Implantable Cardioverter Defibrillator, (AICD) implantation is done for which of following conditions:","o":["Brugada syndrome","Ventricular fibrillation","Acute coronary syndrome with low EF","All of the above"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3214, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 779, '{"id":3214,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":779,"q":"What is the line of treatment for intractable Sydenham chorea?","o":["Haloperidol","Valproate","Warfarin","Risperidone"],"a":1,"e":"Answer: B. Valproate Sydenham''s chorea (SC) / Chorea minor / Rheumatic chorea (RC) / St. Vitus’ s Dance Major diagnostic criteria for rheumatic disease Most common acquired chorea during childhood Characterized by rapid, uncoordinated jerking movements primarily affecting the face, hands and feet Benzodiazepines facilitate the action of GABA and valproate enhances the action on GABA, hence these agents are used to treat chorea","pyqMatches":[{"year":"2018","no":135,"q":"What is the line of treatment for intractable Sydenham chorea?","o":["Haloperidol","Valproate","Warfarin","Risperidone"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3215, 'Medicine', 'Neurology', 'Moderate', 'Internal_Medicine', 780, '{"id":3215,"subject":"Medicine","chapter":"Neurology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":780,"q":"Neurofibromatosis 1 criteria except","o":["Brain tumor","Acoustic neuromas","Pseudoarthrosis","Cafe-au-lait spots"],"a":1,"e":"Answer: B - Acoustic neuromas Clinical diagnosis requires presence of at least 2 of 7 criteria to confirm presence of neurofibromatosis, type 1. Despite suspicion, most signs do not appear until late childhood / adolescent The 7 clinical criteria used to diagnose NF1 are as follows: Six or more café-au-lait spots / hyperpigmented macules greater than or equal to 5 mm in diameter in prepubertal children & 15 mm postpubertal Axillary or inguinal freckles (>2) Two or more typical neurofibromas or one plexiform neurofibroma Optic nerve glioma Two or more iris hamartomas (Lisch nodules) (often identified only through slit-lamp examination) Sphenoid dysplasia or typical long-bone abnormalities such as pseudarthrosis Strong family history (1st degree relative with NF1)","pyqMatches":[{"year":"2018","no":136,"q":"Neurofibromatosis 1 criteria except","o":["Brain tumor","Acoustic neuromas","Pseudoarthrosis","Cafe-au-lait spots"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3216, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 781, '{"id":3216,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":781,"q":"Most common site of chronic gastric ulcer","o":["Pyloric antrum","Upper part of lesser curvature","Lower part of lesser curvature","Segment of large intestine"],"a":0,"e":"Answer: A - Pyloric antrum A major causative factor (60% of gastric& up to 50–75% of duodenal ulcers) is chronic inflammation due to Helicobacter pylori that colonizes the antral mucosa.","pyqMatches":[{"year":"2018","no":137,"q":"Most common site of chronic gastric ulcer","o":["Pyloric antrum","Upper part of lesser curvature","Lower part of lesser curvature","Segment of large intestine"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3217, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 782, '{"id":3217,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":782,"q":"Approximate time interval between HIV infection & manifestation of AIDS is?","o":["7.5 yr","10 yr","12 yr","11 yr"],"a":1,"e":"Answer: B - 10 years The approximate time frame required for incubation is usually 10 years. median time from infection to the development of AIDS in adults is about 9 years. A small proportion of untreated HIV-infected people are long-term non-progressors, with CD4 counts in the reference range for 10 years or more. Some long-term non-progressors have undetectable viral loads and are known as ‘elite controllers’.","pyqMatches":[{"year":"2018","no":138,"q":"Approximate time interval between HIV infection & manifestation of AIDS is?","o":["7.5 yr","10 yr","12 yr","11 yr"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3218, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 783, '{"id":3218,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":783,"q":"Heller''s myotomy is done for","o":["Zenker''s diverticulum","Achalasia cardia","Bunions","Knee arthroscopy"],"a":1,"e":"Answer: B - Achalasia cardia Achalasia, a disorder of esophagus characterized by progressive inability to swallow solids & liquids. Causes include weakened esophageal muscles & issues with lower esophageal sphincter relaxation Heller Myotomy, surgical procedure offers long term symptomatic relief to these patients. It involves weakening of muscles at gastroesophageal junction, allowing the valve between oesophagus & stomach to remain open.","pyqMatches":[{"year":"2018","no":139,"q":"Heller''s myotomy is done for","o":["Zenker''s diverticulum","Achalasia cardia","Bunions","Knee arthroscopy"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3219, 'Medicine', 'Cardiology', 'Hard', 'Internal_Medicine', 784, '{"id":3219,"subject":"Medicine","chapter":"Cardiology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":784,"q":"Myocardial stunning pattern not matching the ECG. What is the diagnosis.","o":["Takotsubo cardiomyopathy","Restrictive cardiomyopathy","Brigade''s cardiomyopathy","Pericardial something"],"a":0,"e":"Answer: A -Takotsubo cardiomyopathy “Myocardial Stunning” is a state where certain segments of myocardium (corresponding to area of major coronary occlusion) shows forms of contractile abnormality. A segmental dysfunction persisting for a variable period of time, about two weeks, even after ischemia has been relieved (by for instance angioplasty or coronary artery bypass surgery). Takotsubo cardiomyopathy / Takotsubo syndrome, a temporary condition where your heart muscle becomes suddenly weakened or ''stunned''.","pyqMatches":[{"year":"2018","no":140,"q":"Myocardial stunning pattern not matching the ECG. What is the diagnosis.","o":["Takotsubo cardiomyopathy","Restrictive cardiomyopathy","Brigade''s cardiomyopathy","Pericardial something"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3220, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 785, '{"id":3220,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":785,"q":"Alternative drug for cardiac arrest in place of epinephrine is?","o":["Amiodarone infusion","Atropine","High dose vasopressin","Adenosine"],"a":2,"e":"Answer: C - High dose vasopressin Vasopressin is an alternative vasopressor at high doses, causes vasoconstriction by directly stimulating smooth muscle V1 receptors. American Heart Association (AHA) guidelines states “Vasopressin is a reasonable first-line vasopressor in patients with ventricular fibrillation or pulseless ventricular tachycardia. Additionally, the guidelines comment that one dose of vasopressin 40 U may replace the first or second dose of epinephrine in all pulseless sudden cardiac arrest scenarios, including asystole and pulseless electrical activity.","pyqMatches":[{"year":"2018","no":141,"q":"Alternative drug for cardiac arrest in place of epinephrine is?","o":["Amiodarone infusion","Atropine","High dose vasopressin","Adenosine"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3221, 'Medicine', 'Neurology', 'Hard', 'Internal_Medicine', 786, '{"id":3221,"subject":"Medicine","chapter":"Neurology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":786,"q":"Patient presenting with cutaneous vasculitis, glomerulonephritis, peripheral neuropathy, Which investigation is to be performed next that will help you diagnose the condition?","o":["ANCA","RA factor","Hbsag","MIF"],"a":0,"e":"Answer: A - ANCA Anti-neutrophil cytoplasmic antibodies (ANCAs): Group of autoantibodies IgG type mainly, Produced against antigens in cytoplasm of neutrophil granulocytes & monocytes. Particularly associated with systemic vasculitis, so called “ANCA- associated vasculitis”.","pyqMatches":[{"year":"2018","no":142,"q":"Patient presenting with cutaneous vasculitis, glomerulonephritis, peripheral neuropathy, Which investigation is to be performed next that will help you diagnose the condition?","o":["ANCA","RA factor","Hbsag","MIF"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3222, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 787, '{"id":3222,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":787,"q":"Cryoglobulinemia","o":["Hepatitis c","Ovarian cancer","Diabetes","Leukemia"],"a":0,"e":"Answer: A. Hepatitis C Cryoglobulinemia / Cryoglobulinemic disease with large amounts of cryoglobulins in blood Cryoglobulins are proteins (mostly immunoglobulins themselves) Become insoluble at reduced temperatures. Mixtures of monoclonal or polyclonal IgM, IgG, and/or IgA & blood complement proteins like C4 are associated with cases of infectious diseases, particularly Hepatitis C infection,","pyqMatches":[{"year":"2018","no":143,"q":"Cryoglobulinemia","o":["Hepatitis c","Ovarian cancer","Diabetes","Leukemia"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3223, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 788, '{"id":3223,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":788,"q":"Causes of hypokalemic metabolic alkalosis with hypertension","o":["Liddle syndrome","Bartter syndrome","Gitelman syndrome","Renal tubular acidosis"],"a":0,"e":"Answer: A. Liddle syndrome Liddle syndrome - Rare hereditary disorder Increased activity of the epithelial sodium channel (E-Na Ch) Activating kidneys to excrete potassium retaining excessive sodium & water, leading to hypertension.","pyqMatches":[{"year":"2018","no":144,"q":"Causes of hypokalemic metabolic alkalosis with hypertension","o":["Liddle syndrome","Bartter syndrome","Gitelman syndrome","Renal tubular acidosis"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3224, 'Medicine', 'Respiratory Medicine', 'Easy', 'Internal_Medicine', 789, '{"id":3224,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Easy","source":"Internal_Medicine","sourceNo":789,"q":"Gold criteria for very severe COPD","o":["Fev1/Fvc <70 and Fev1 < 30","Fev1/Fvc <70 and Fev1 < 70","Fev1/Fvc <70 and Fev1 < 50","Both A and C"],"a":0,"e":"Answer: A. Fev1/Fvc <70 and Fev1 < 30 COPD should be considered in any patient who has dyspnea, chronic cough or sputum production, and/or a history of exposure to risk factors for the disease. Spirometry is required to make the diagnosis. Presence of post-bronchodilator FEV1/FVC < 0.70 confirms the presence of persistent airflow limitation. Stage IV / Very Severe COPD Severe airflow limitation (FEV1/FVC < 70%; FEV1 <. 30% predicted) or FEV1 < 50% predicted plus chronic respiratory failure. Patients may have Very Severe (Stage IV)COPD even if FEV1 is > 30% predicted.","pyqMatches":[{"year":"2018","no":145,"q":"Gold criteria for very severe COPD","o":["Fev1/Fvc <70 and Fev1 < 30","Fev1/Fvc <70 and Fev1 < 70","Fev1/Fvc <70 and Fev1 < 50","Both A and C"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3225, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 790, '{"id":3225,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":790,"q":"ABPI increases artificially in","o":["Arteriosclerosis calcified arteries","Ischemic ulcers","Intermittent claudication","DVT"],"a":0,"e":"Answer: A. Arteriosclerosis calcified arteries The ankle-brachial pressure index (ABPI) / Ankle-Brachial index (ABI): Ratio of blood pressure at ankle to blood pressure in upper arm (brachium). Compared to arm, lower blood pressure in leg suggests blocked arteries due to peripheral artery disease (PAD). Ankle brachial pressure index (ABPI) is a method for the quantification of peripheral vascular disease that results from advanced atherosclerosis.","pyqMatches":[{"year":"2018","no":146,"q":"ABPI increases artificially in","o":["Arteriosclerosis calcified arteries","Ischemic ulcers","Intermittent claudication","DVT"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3226, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 791, '{"id":3226,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":791,"q":"Minimal dysfunction syndrome seen in","o":["Dyslexia","ADHD","Mental subnormality","Down’s syndrome"],"a":0,"e":"Answer: A. Dyslexia Clinical feature of Minimal dysfunction syndrome includes dyslexia. Minimal brain dysfunction: Neurodevelopmental disorder. Characterized by evidences of immaturity involving control of activity, emotions, & behavior Specific learning disabilities involving the communicating skills needed in reading, writing, and mathematics. Inability to maintain attention & concentration Inability to skillfully blend the auditory & visual functions essential in language performance","pyqMatches":[{"year":"2018","no":147,"q":"Minimal dysfunction syndrome seen in","o":["Dyslexia","ADHD","Mental subnormality","Down’s syndrome"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3227, 'Medicine', 'Endocrinology', 'Hard', 'Internal_Medicine', 792, '{"id":3227,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":792,"q":"The earliest feature of 3rd cranial nerve involvement in diabetes mellitus patient is -","o":["Normal light reflex","Abnormal light reflex","Normal light and accommodation reflex","Abnormal light and accommodation reflex"],"a":0,"e":"Answer: A. Normal light reflex The oculomotor nerve is the third cranial nerve. It enters the orbit via the superior orbital fissure and innervates muscles that enable most movements of the eye and that raise the eyelid. The nerve also contains fibers that innervate the muscles that enable pupillary constriction and accommodation (ability to focus on near objects as in reading). The oculomotor nerve is derived from the basal plate of the embryonic midbrain.In people with diabetes and older than 50 years of age, an oculomotor nerve palsy occurs.","pyqMatches":[{"year":"2018","no":283,"q":"The earliest feature of 3rd cranial nerve involvement in diabetes mellitus patient is","o":["Normal light reflex","Abnormal light reflex","Normal light and accommodation reflex","Abnormal light and accommodation reflex"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3228, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 793, '{"id":3228,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":793,"q":"Mobitz type 2 second degree AV block is seen in all except:","o":["Hypothyroidism","Coronary Artery Disease","Sarcoidosis","Cushing syndrome"],"a":3,"e":"Ans: D. Cushing syndrome Delay or lack of conduction through the atrioventricular (AV) node and below has multiple causes. Degenerative changes (eg, fibrosis, calcification, or infiltration) are the most common cause of non- ischeamic AV block. Idiopathic fibrosis or calcification of the AV conduction system, commonly seen in the elderly, can cause complete AV block. Causes of Mobitz type 2 second degree AV block are - Damage of the conduction system from coronary artery disease, valve surgery, myocardial infarction, myocarditis, infiltrative cardiomyopathies (sarcoidosis, hemochromatosis), myxedema, Lyme disease, neuromuscular disease, and AV junction ablation [6]","pyqMatches":[{"year":"2018","no":256,"q":"Mobitz type 2 second degree AV block is seen in all except:","o":["Hypothyroidism","Coronary Artery Disease","Sarcoidosis","Cushing syndrome"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3229, 'Medicine', 'Infectious Diseases', 'Easy', 'Internal_Medicine', 794, '{"id":3229,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Easy","source":"Internal_Medicine","sourceNo":794,"q":"Which drug regimen is given in a pregnant woman with HIV infection?","o":["Tenofovir disoproxil fumarate with emtricitabine","Tenofovir disoproxil fumarate with lamivudine","Abacavir with lamivudine","All"],"a":3,"e":"Ans. D. All Preferred Regimens for HIV Antiretroviral Therapy (ART) in Pregnancy Two-NRTI backbone Regimens include the following: Tenofovir disoproxil fumarate with emtricitabine (TDF/FTC co- formulated) or tenofovir disoproxil fumarate with lamivudine (3TC) once daily (use with caution in renal insufficiency) or Abacavir with lamivudine (ABC/3TC) once daily (only if HLA-B5701– negative); avoid combination with ritonavir-boosted atazanavir if the pretreatment HIV viral load exceeds 100,000 copies/mL. For women who have never taken HIV medicines, the preferred HIV regimen should include two nucleoside reverse transcriptase inhibitors (NRTIs) plus an integrase strand transfer inhibitor (INSTI), a non-nucleoside reverse transcriptase inhibitor (NNRTI), or a protease inhibitor (PI) with low-dose ritonavir (brand name: Norvir). The regimen generally should include at least one of the following NRTIs that pass easily across the placenta: abacavir (brand name: Ziagen) emtricitabine (brand name: Emtriva) lamivudine (brand name: Epivir) tenofovir disoproxil fumarate(brand name: Viread) zidovudine (brand name: Retrovir)","pyqMatches":[{"year":"2018","no":279,"q":"Which drug regimen is given in a pregnant woman with HIV infection?","o":["Tenofovir disoproxil fumarate with emtricitabine","Tenofovir disoproxil fumarate with lamivudine","Abacavir with lamivudine","All"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3230, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 795, '{"id":3230,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":795,"q":"Nutcracker esophagus, the correct statement is","o":["There is extremely forceful peristaltic activity leading to episodes of chest pain and dysphagia","There is no medical t/t available","Type of oesophageal Malignancy","None"],"a":0,"e":"Ans: A. There is extremely forceful peristaltic activity leading to episodes of chest pain and dysphagia NutCracker Oesophagus is a hypermotility disorder with high amplitude peristalsis. It is a condition in which extremely forceful peristaltic activity leads to episodic chest pain and dysphagia. Treatment is with nitrates or nifedipine. Ref. davidsons principles and practice 23rd edition page no.795","pyqMatches":[{"year":"2020","no":142,"q":"Nutcracker esophagus, the correct statement is","o":["There is extremely forceful peristaltic activity leading to episodes of chest pain and dysphagia","There is no medical t/t available","Type of oesophageal Malignancy","None"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3231, 'Medicine', 'Gastroenterology', 'Moderate', 'Internal_Medicine', 796, '{"id":3231,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":796,"q":"Which of the following criteria is used to assess the prognosis of the liver condition as represented in the picture below?","o":["Child pugh score","Milan score","Meld score","Alvarado score"],"a":0,"e":"Ans: A. Child pugh score the liver condition as represented in the picture above demonstrates liver cirrhosis. Child-Pugh score (or the Child–Turcotte–Pugh score or Child Criteria) is used to assess the prognosis of chronic liver disease, mainly cirrhosis. It is now used to determine the prognosis, as well as the required strength of treatment and the necessity of liver transplantation. Factor 1 point 2 points 3 points Total bilirubin (μmol/L) <34 34-50 >50 Serum albumin (g/L) >35 28-35 <28 PT INR <1.7 1.71-2.30 >2.30 Ascites None Mild Moderate to Severe H ti N G d I II ( d G d III IV ( Hepatic encephalopathy None Grade I-II (or suppressed with medication) Grade III-IV (or refractory) Interpretation: Points Class One year survival Two-year survival 5–6 A 100% 85% 7–9 B 81% 57% 10–15 C 45% 35%","pyqMatches":[{"year":"2020","no":143,"q":"Which of the following criteria is used to assess the prognosis of the liver condition as represented in the picture below?","o":["Child pugh score","Milan score","Meld score","Alvarado score"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3232, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 797, '{"id":3232,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":797,"q":"Sudden onset headache with neck rigidity?","o":["Intraparenchymal hemorrhage","Sah","Meningitis","None of the above"],"a":1,"e":"Ans: b. Sah sudden onset of a severe headache (often described as \"the worst headache of my life\") nausea and vomiting stiff neck sensitivity to light (photophobia) blurred or double vision loss of consciousness seizures","pyqMatches":[{"year":"2020","no":144,"q":"Sudden onset headache with neck rigidity?","o":["Intraparenchymal hemorrhage","Sah","Meningitis","None of the above"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3233, 'Medicine', 'Cardiology', 'Easy', 'Internal_Medicine', 798, '{"id":3233,"subject":"Medicine","chapter":"Cardiology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":798,"q":"Vegetation in mitral valve seen in which condition","o":["Libman sacks","Infective endocarditis","NBTE","Rheumatic fever"],"a":1,"e":"Ans: B. Infective endocarditis Infective endocarditis is characterized by lesions, known as vegetations, which is a mass of platelets, fibrin, microcolonies of microorganisms, and scant inflammatory cells. In the subacute form of infective endocarditis, the vegetation may also include a center of granulomatous tissue, which may be fibrosed or calcified.","pyqMatches":[{"year":"2020","no":145,"q":"Vegetation in mitral valve seen in which condition","o":["Libman sacks","Infective endocarditis","NBTE","Rheumatic fever"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3234, 'Medicine', 'Neurology', 'Easy', 'Internal_Medicine', 799, '{"id":3234,"subject":"Medicine","chapter":"Neurology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":799,"q":"Water hammer pulse is seen in","o":["Aortic regurgitation","Mitral stenosis","Aortic stenosis","Left ventricular failure"],"a":0,"e":"Ans: A. Aortic regurgitation Water hammer pulse It is a large bounding pulse, associated with an increased stroke volume of the left ventricle and a decrease in the peripheral resistance, leading to wide pulse pressure. The pulse strikes the palpating finger with a rapid, forced jerk and quickly disappears. It is best felt in the radial artery with the patient''s arm elevated. It is seen in aortic regurgitation.","pyqMatches":[{"year":"2020","no":146,"q":"Water hammer pulse is seen in","o":["Aortic regurgitation","Mitral stenosis","Aortic stenosis","Left ventricular failure"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3235, 'Medicine', 'Infectious Diseases', 'Moderate', 'Internal_Medicine', 800, '{"id":3235,"subject":"Medicine","chapter":"Infectious Diseases","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":800,"q":"What will you do when 3 yrs old child parents come to phc with fever, cough since 5 days with chest indrawing present under mnci classification","o":["Give antipyretics only","Give antibiotics and follow up","Refer urgently to tertiary care","Give antibiotics and refer to tertiary care"],"a":3,"e":"Ans: D. Give antibiotics and refer to tertiary care","pyqMatches":[{"year":"2020","no":147,"q":"What will you do when 3 yrs old child parents come to phc with fever, cough since 5 days with chest indrawing present under mnci classification","o":["Give antipyretics only","Give antibiotics and follow up","Refer urgently to tertiary care","Give antibiotics and refer to tertiary care"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3236, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 801, '{"id":3236,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":801,"q":"What poison will you detect in skeleton even after emaciation","o":["Lead","Arsenic","Mercury","Cadmium"],"a":1,"e":"Ans: B. Arsenic Arsenic can be detected even in conflagrated human bones. Hence, it is possible to detect poisoning by arsenic even when the body has been burnt for a long time. FMT 2nd edition Page no. 184","pyqMatches":[{"year":"2020","no":148,"q":"What poison will you detect in skeleton even after emaciation","o":["Lead","Arsenic","Mercury","Cadmium"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3237, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 802, '{"id":3237,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":802,"q":"Ph7.2, HCO3 - (10 or 12), pco2-35 , metabolic acidosis due to","o":["K+ excretion by the kidney","Co2 expiration by lungs","H+excretion by the kidney","Hco3 loss by kidney"],"a":3,"e":"Ans: D. Hco3 loss by kidney In the question, pH is decreased (acidosis) & pCO2 is decreased (Normal= 40-45 mm Hg). A decreased pCO2 will try to increase pH, hence it must be a secondary compensating mechanism. So, the primary mechanism causing the acid-base imbalance must be a decrease in serum bicarbonate concentration i.e. metabolic acidosis.","pyqMatches":[{"year":"2020","no":149,"q":"Ph7.2, HCO3 - (10 or 12), pco2-35 , metabolic acidosis due to","o":["K+ excretion by the kidney","Co2 expiration by lungs","H+excretion by the kidney","Hco3 loss by kidney"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3238, 'Medicine', 'Endocrinology', 'Easy', 'Internal_Medicine', 803, '{"id":3238,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":803,"q":"Impaired function of Aquaporin results in","o":["Liddel syndrome","Nephrogenic DI","Cystic fibrosis","Barter syndrome"],"a":1,"e":"Ans: B. Nephrogenic DI Aquaporins, also called water channels, are integral membrane proteins from a larger family of major intrinsic proteins that form pores in the membrane of biological cells, mainly facilitating the transport of water between cells. Genetic defects involving aquaporin genes have been associated with several human diseases including nephrogenic diabetes insipidus and neuromyelitis optica.","pyqMatches":[{"year":"2020","no":150,"q":"Impaired function of Aquaporin results in","o":["Liddel syndrome","Nephrogenic DI","Cystic fibrosis","Barter syndrome"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3239, 'Medicine', 'Nephrology', 'Easy', 'Internal_Medicine', 804, '{"id":3239,"subject":"Medicine","chapter":"Nephrology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":804,"q":"The most common cause of death in SLE in children","o":["Lupus nephritis","Lupus cerebritis","Libman sacks endocarditis","Anemia and infections"],"a":0,"e":"Ans: A. Lupus nephritis Major causes of death in pediatric SLE include :","pyqMatches":[{"year":"2020","no":152,"q":"The most common cause of death in SLE in children","o":["Lupus nephritis","Lupus cerebritis","Libman sacks endocarditis","Anemia and infections"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3240, 'Medicine', 'Miscellaneous', 'Hard', 'Internal_Medicine', 805, '{"id":3240,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Internal_Medicine","sourceNo":805,"q":"A patient having multiple Gall stones and shows 8 mm dilation and 4 stones in CBD, best treatment modalities are –","o":["Cholecystectomy with choledocholithotomy at the same setting","ESWL","Cholecystectomy and wait for ERCP","All"],"a":0,"e":"Ans: A. Cholecystectomy with choledocholithotomy done at the same sitting Management of suspected or proven CBD stones associated with gall bladder stones For gallstones - laparoscopic cholecystectomy is the procedure of choice. For CBD stones two things can be done: 1) If the surgeon is experienced in laparoscopic techniques of CBD stone removal then both cholecystectomy and choledocholithotomy are done in the same sitting. CBD stones are first confirmed by an intraoperative cholangiogram then the stones are removed laparoscopically via the cystic duct or by choledochotomy. 2) If the surgeon is not experienced with laparoscopic methods of CBD stone removal, preoperative endoscopic sphincterotomy with stone removal and later laparoscopic cholecystectomy is done. Laparoscopic cholecystectomy with choledocholithotomy in the same sitting is the preferred technique (provided the surgeon is experienced) But one must keep in mind here that \"for elderly, poor-risk patients with gallstones and CBD stones, some have recommended ERCP and sphincterotomy as the sole treatment, leaving gallbladder and stones in situ\". - Maingot''s 10/e Usually the gallstones in these patients remain asymptomatic and if the need arises can be managed by cholecystectomy","pyqMatches":[{"year":"2020","no":153,"q":"A patient having multiple Gall stones and shows 8 mm dilation and 4 stones in CBD, best treatment modalities are –","o":["Cholecystectomy with choledocholithotomy at the same setting","ESWL","Cholecystectomy and wait for ERCP","All"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3241, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 806, '{"id":3241,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":806,"q":"Pulmonary plethora is seen with all except:","o":["TGS","Ebstein anomalies","Hypoplastic left heart syndrome","Double outlet right ventricle"],"a":1,"e":"Ans: B. Ebstein anomalies Pulmonary plethora is seen in TOF TA Ebstein''s anomaly Pulmonary atresia","pyqMatches":[{"year":"2014","no":1612,"q":"Pulmonary plethora is seen with - all except","o":["TGA","Hypoplastic left heart syndrome","Ebstein anomalis","Double outlet right ventricle"],"a":2,"source":"NEET_2014_Paper.pdf"},{"year":"2020","no":154,"q":"Pulmonary plethora is seen with all except:","o":["TGS","Ebstein anomalies","Hypoplastic left heart syndrome","Double outlet right ventricle"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2014","2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3242, 'Medicine', 'Miscellaneous', 'Hard', 'Internal_Medicine', 807, '{"id":3242,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Hard","source":"Internal_Medicine","sourceNo":807,"q":"Hemodynamically unstable patient with SVT","o":["IV IBUTILIDE","IV DILTIAZEM","CARDIOVERSION","Iv beta-blockers"],"a":2,"e":"Ans: C. CARDIOVERSION","pyqMatches":[{"year":"2020","no":156,"q":"Hemodynamically unstable patient with SVT","o":["IV IBUTILIDE","IV DILTIAZEM","CARDIOVERSION","Iv beta-blockers"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3243, 'Medicine', 'Nephrology', 'Hard', 'Internal_Medicine', 808, '{"id":3243,"subject":"Medicine","chapter":"Nephrology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":808,"q":"A Female patient was on lithium for bipolar disorder for 6 months.she fasted for some days due to religious condition and later presented with seizures,tremors, confusion and weakness. What investigations have to be done to diagnose her condition","o":["serum electrolytes","serum lithium","ECG","MRI"],"a":1,"e":"Ans: B. serum lithium Because of its effects on multiple body systems, including but not limited to renal, hematologic, and thyroid systems, appropriate baseline studies must precede the start of lithium therapy. The minimal tests to be done include serum creatinine, electrolytes, thyroid function tests, and a complete blood count with differential. Additionally, because of its cardiac effect, an ECG is indicated. Any woman thought to be pregnant should have a pregnancy test. Ref: Nurcombe B. (2008). Chapter 12. Diagnostic Formulation, Treatment Planning, and Modes of Treatment in Children and Adolescents. In M.H. Ebert, P.T. Loosen, B. Nurcombe, J.F. Leckman (Eds), CURRENT Diagnosis & Treatment: Psychiatry, 2e.","pyqMatches":[{"year":"2020","no":157,"q":"A Female patient was on lithium for bipolar disorder for 6 months.she fasted for some days due to religious condition and later presented with seizures,tremors, confusion and weakness. What investigations have to be done to diagnose her condition","o":["serum electrolytes","serum lithium","ECG","MRI"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3244, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 809, '{"id":3244,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":809,"q":"Lithium causes:","o":["Hypokalemia","Hyperkalemia","Hypocalcemia","Hypercalcemia"],"a":0,"e":"Ans: A. Hypokalemia Side effects of lithium","pyqMatches":[{"year":"2020","no":158,"q":"Lithium causes:","o":["Hypokalemia","Hyperkalemia","Hypocalcemia","Hypercalcemia"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3245, 'Medicine', 'Hematology', 'Hard', 'Internal_Medicine', 810, '{"id":3245,"subject":"Medicine","chapter":"Hematology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":810,"q":"A 50-year-old man presents with paresthesia. HB-6.8g/dl. Peripheral smear shows macrocytosis and neutrophils with hypersegmented nuclei.endoscopy reveals atrophic gastritis. a most probable diagnosis is","o":["Folate deficiency","Vitamin B12 deficiency","Riboflavin deficiency","Iron deficiency"],"a":1,"e":"Ans: B. Vitamin B12 deficiency Macrocytosis and hyper segmented neutrophils on peripheral smear, poor absorption(Atrophic gastritis) suggest the diagnosis of B12 deficiency. The presence of anemia (Hb= 6gm%) Macrocytosis (MCV=104) and decreased vitamin B12 levels (B12=60 pg/ml) suggests a diagnosis of megaloblastic anemia due to vitamin B12 deficiency. The patient in question thus has macrocytic anemia due to vitamin B12 deficiency.","pyqMatches":[{"year":"2020","no":159,"q":"A 50-year-old man presents with paresthesia. HB-6.8g/dl. Peripheral smear shows macrocytosis and neutrophils with hypersegmented nuclei.endoscopy reveals atrophic gastritis. a most probable diagnosis is","o":["Folate deficiency","Vitamin B12 deficiency","Riboflavin deficiency","Iron deficiency"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3246, 'Medicine', 'Hematology', 'Easy', 'Internal_Medicine', 811, '{"id":3246,"subject":"Medicine","chapter":"Hematology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":811,"q":"All trans retinoic acid is used in the treatment of tumour associated with","o":["BCR-ABL","PML-RARA","CMYC","CEBPA"],"a":1,"e":"Ans: B. PML-RARA All-trans retinoic acid (ATRA) is an active metabolite of vitamin A under the family retinoid. Retinoids, through their cognate nuclear receptors, exert potent effects on cell growth, differentiation and apoptosis, and have significant promise for cancer therapy and chemoprevention. Differentiation therapy with ATRA has marked a major advance and become the first choice drug in the treatment of acute promyelocytic leukemia (APL). All-trans retinoic Acid is used in the treatment for Acute Promyelocytic Leukemia (PML)","pyqMatches":[{"year":"2020","no":160,"q":"All trans retinoic acid is used in the treatment of tumour associated with","o":["BCR-ABL","PML-RARA","CMYC","CEBPA"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3247, 'Medicine', 'Respiratory Medicine', 'Moderate', 'Internal_Medicine', 812, '{"id":3247,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":812,"q":"Renal tubular acidosis with ABG value pH = 7.24 P02=80; PaCO2= 36 Na = 131; HCO3 = 14 Cl= 90; BE = -13 Glucose = 135 above ABG picture suggest –","o":["Respiratory acidosis","Respiratory alkalosis","Metabolic acidosis","Metabolic alkalosis"],"a":2,"e":"Ans: C. Metabolic acidosis The given values have low pH, and low HCo3 Indicate metabolic acidosis PCO2 in lower normal range (normal value 35-45 mm/hg)","pyqMatches":[{"year":"2020","no":161,"q":"Renal tubular acidosis with ABG value pH = 7.24 P02=80; PaCO2= 36 Na = 131; HCO3 = 14 Cl= 90; BE = -13 Glucose = 135 above ABG picture suggest –","o":["Respiratory acidosis","Respiratory alkalosis","Metabolic acidosis","Metabolic alkalosis"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3248, 'Medicine', 'Respiratory Medicine', 'Hard', 'Internal_Medicine', 813, '{"id":3248,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Hard","source":"Internal_Medicine","sourceNo":813,"q":"Patient with pulmonary fibrosis. Which antiarrhythmic drug should not be given","o":["Amiodarone","Flecainide","Iv ibutilide","lidocaine"],"a":0,"e":"Ans: A. Amiodarone Amiodarone and its metabolites can produce lung damage directly by a cytotoxic effect and indirectly by an immunological reaction. The latter is supported by the finding of cytotoxic T cells in bronchoalveolar lavage (BAL) fluid from patients with diagnosed APT. Amiodarone may induce the production of toxic O2 radicals, which can directly damage cells","pyqMatches":[{"year":"2020","no":162,"q":"Patient with pulmonary fibrosis. Which antiarrhythmic drug should not be given","o":["Amiodarone","Flecainide","Iv ibutilide","lidocaine"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3249, 'Medicine', 'Gastroenterology', 'Hard', 'Internal_Medicine', 814, '{"id":3249,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":814,"q":"A 42-year-old patient with obstructive jaundice. Alp, Ggt, haptoglobin all increased. The most likely cause is:","o":["Alcohol","Lead","Chronic rf","None of the above"],"a":0,"e":"Ans: A. Alcohol An indicator that should make the clinician highly suspicious of alcohol-related liver injury is AST: ALT ratio of 2:1 or more. Gamma-glutamyl transferase (GGT) is another sensitive but non- specific marker for the hepatic injury which cannot be used solely to diagnose alcohol-related hepatic insult. Levels of GGT greater than twice the normal values in addition to AST:ALT ratio >2 strongly indicate alcohol-induced liver injury as well.","pyqMatches":[{"year":"2020","no":163,"q":"A 42-year-old patient with obstructive jaundice. Alp, Ggt, haptoglobin all increased. The most likely cause is:","o":["Alcohol","Lead","Chronic rf","None of the above"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3250, 'Medicine', 'Gastroenterology', 'Easy', 'Internal_Medicine', 815, '{"id":3250,"subject":"Medicine","chapter":"Gastroenterology","difficulty":"Easy","source":"Internal_Medicine","sourceNo":815,"q":"The differentiating feature between IBS and organic GI disease is:","o":["Diarrhea","Stool calprotectin","Pain abdomen","Mucus in stools"],"a":1,"e":"Ans: B. Stool calprotectin Both organic IBD and non-organic functional disorders like IBS exhibit very similar symptoms researchers have identified several stool-based biomarkers to differentiate between IBD and IBS. These become especially crucial when taking the next step towards deciding how to manage the disease (e.g. therapeutic intervention, etc.). Those biomarkers include the following: Calprotectin Alpha-1 Antitrypsin Lysozyme Secretory IgA Albumin","pyqMatches":[{"year":"2020","no":164,"q":"The differentiating feature between IBS and organic GI disease is:","o":["Diarrhea","Stool calprotectin","Pain abdomen","Mucus in stools"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3251, 'Medicine', 'Endocrinology', 'Moderate', 'Internal_Medicine', 816, '{"id":3251,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":816,"q":"Atient has fatigue. But not gaining weight. Body was warm. Investigation will show:","o":["Low TSH with more t3 or t4","High TSH with normal t3 or t4","High TSH with euthyroid","Increased uptake of t3, but decrease t4"],"a":0,"e":"Ans: A. Low TSH with more t3 or t4","pyqMatches":[{"year":"2020","no":165,"q":"Atient has fatigue. But not gaining weight. Body was warm. Investigation will show:","o":["Low TSH with more t3 or t4","High TSH with normal t3 or t4","High TSH with euthyroid","Increased uptake of t3, but decrease t4"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3252, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 817, '{"id":3252,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":817,"q":"Warming in Frost frostbite should be done at what temperature:","o":["37 degree","42 degree","44 degree","46 degree"],"a":0,"e":"Ans: A. 37 degree At temperature below freezing (dry-cold condition) frostbite occurs the tissue freeze & ice crystals form in between the cells Affected part should be warmed using water at 44 °is under Criticism, Warming should last about 20 minutes at a time, Intake of hot fluids promotes general rewarming","pyqMatches":[{"year":"2020","no":166,"q":"Warming in Frost frostbite should be done at what temperature:","o":["37 degree","42 degree","44 degree","46 degree"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3253, 'Medicine', 'Cardiology', 'Moderate', 'Internal_Medicine', 818, '{"id":3253,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":818,"q":"Which of the following is not seen in Pituitary apoplexy","o":["Headache","Hypertension","Hypotension","Vomiting"],"a":2,"e":"Ans: C. Hypotension Following are seen in Pituitary apoplexy Severe hypoglycemia Severe headache (usually retro-orbital) Impaired consciousness Fever Visual disturbances (visual field defect, visual acuity) Ophthalmoplegia (ocular paresis) → Causing diplopia Hypotension & shock Nausea/vomiting Meningeal sign","pyqMatches":[{"year":"2020","no":167,"q":"Which of the following is not seen in Pituitary apoplexy","o":["Headache","Hypertension","Hypotension","Vomiting"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3254, 'Medicine', 'Miscellaneous', 'Easy', 'Internal_Medicine', 819, '{"id":3254,"subject":"Medicine","chapter":"Miscellaneous","difficulty":"Easy","source":"Internal_Medicine","sourceNo":819,"q":"Loss of pain/temperature sensation on ipsilateral face & C/L body due to thrombosis in","o":["PICA","Posterior cerebellar artery","Superior cerebellar artery","None of the above"],"a":0,"e":"Ans: A. PICA .Most cases result from ipsilateral vertebral artery occlusion; occlusion of the posterior inferior cerebellar artery is responsible for it. Vessel occlusion that results in Lateral Medullary syndrome: Vertebral (most common) Posterior inferior cerebellar (2nd most common) Superior, middle or Inferior lateral medullary arteries Lateral medullary syndrome (Wallenberg syndrome): Vertigo Numbness of ipsilateral face and contralateral limbs Diplopia Dysphagia Dysarthria Ataxia Hoarseness","pyqMatches":[{"year":"2020","no":168,"q":"Loss of pain/temperature sensation on ipsilateral face & C/L body due to thrombosis in","o":["PICA","Posterior cerebellar artery","Superior cerebellar artery","None of the above"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3255, 'Medicine', 'Respiratory Medicine', 'Moderate', 'Internal_Medicine', 820, '{"id":3255,"subject":"Medicine","chapter":"Respiratory Medicine","difficulty":"Moderate","source":"Internal_Medicine","sourceNo":820,"q":"All found in LVF except","o":["Lung oligemia","Kerley b lines","Rales","Pedal edema"],"a":0,"e":"Ans: A. Lung oligemia Chest X-ray Features of Left ventricular failure: Cardiomegaly Kerley lines Prominent upper lobe veins Bat’s wings shadow Pleural effusion Kerley B line is due to interstitial edema. Prominent right descending pulmonary artery is seen in acute pulmonary embolism.","pyqMatches":[{"year":"2020","no":169,"q":"All found in LVF except","o":["Lung oligemia","Kerley b lines","Rales","Pedal edema"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3256, 'Medicine', 'Neurology', 'Hard', 'Internal_Medicine', 821, '{"id":3256,"subject":"Medicine","chapter":"Neurology","difficulty":"Hard","source":"Internal_Medicine","sourceNo":821,"q":"A 25 years old lady with a history of fever for 1 month presents with headache and ataxia.Brain imaging shows dilated ventricles and significant basal exudates. Which of the following will be the most likely CSF finding:","o":["Lymphocytosis, Low Glucose, High protein","Lymphocytosis, Normal Glucose, High protein","Lymphocytosis, Low Glucose, Normal protein","Neutrophilia, Low glucose, Low Protein"],"a":0,"e":"Ans: A. (Lymphocytosis, Low Glucose, High protein) Presence of significant basal exudates, together with dilated ventricles (hydrocephalus) in a young female with a prolonged history of fever and headache suggests a diagnosis of Tubercular Meningitis. Tubercular Meningitis is characterized by Lymphocytic Pleocytosis, Low Glucose and High Protein within the CSF. The pathological hallmark of Tubercular Meningitis is the predominant involvement of basal cisterns that are observed by the presence of basal inflammatory tissue exudate.","pyqMatches":[{"year":"2020","no":171,"q":"A 25 years old lady with a history of fever for 1 month presents with headache and ataxia.Brain imaging shows dilated ventricles and significant basal exudates. Which of the following will be the most likely CSF finding:","o":["Lymphocytosis, Low Glucose, High protein","Lymphocytosis, Normal Glucose, High protein","Lymphocytosis, Low Glucose, Normal protein","Neutrophilia, Low glucose, Low Protein"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3257, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 1, '{"id":3257,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":1,"q":"Most common species of pseudomonas causingintravascular catheter related infections is ?","o":["P. cepacia","P. aeruginosa","P. maltiphila","P. mallei"],"a":1,"e":"P. aeruginosa [Ref- Harrison 17 th/e p. 838, 839; The Internet journal of Anaesthesiology] Most common species of pseudomonas associated with intravascular catheter is Pseudomonas Aeruginosa. Intravascular catheter related infections Indwelling vascular catheters are a leading source of bloodstream infections. Amongst indwelling vascular catheters, central venous catheters are the most common culprits. Pathogenesis There are four potential sources for catheter related infections ? 1) The skin insertion site 2) The catheter hub 3) Hematogenous seeding from a distant infection 4) Contaminated infusate The skin insertion site and the catheter hub are by for the two most important sources. Approximately 65% of catheter related infections originate from the skin flora, 30% from the contaminated hub and 5% from other pathways. For short term catheters, skin contamination is the most likely mechanism of pathogenesis. On the other hand, for long term catheters, hub contamination is more .frequent because such catheters often have to be intercepted and manipulated. Skin organisms migrate from the skin insertion site along the external surface of catheter, colonizing the distal intravascular tip of the catheter, and ultimately causing blood-stream infection. On the other hand, in hub related infections, organisms are usually introduced into the hub from the hands of medical personnel and the organisms migrate along the internal surface of the catheter, where they can cause a bloodstream infection. Microbiology Most of the micro-organisms implicated in CRIs arise from the skin flora. Staphylococci are the most frequently isolated pathogens, paricularly coagulase-negative staphylococci. Etiology of catheter related infection Microorganism Percentage • Coagulase negative staphylococci 30 - 40 • Staph aureus 5 - 10 • Enterococci 4 - 6 • Candida spp. 3 - 6 • Pseudomonas aeruginosa 2 - 5 • Enterobacter spp 1 - 4 • Acinetobacter spp. 1 - 2 • Serratia spp. <1 • Others < 1 - 5","pyqMatches":[{"year":"2014","no":789,"q":"Most common species of pseudomonas causingintravascular catheter related infections is ?","o":["P. cepacia","P. aeruginosa","P. maltiphila","P. mallei"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3258, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 2, '{"id":3258,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":2,"q":"Draughtsman colonies are seen with:","o":["Anthrax","Pnuemococci","Pertussis","Yersenia"],"a":1,"e":"Pnuemococci Due to alpha hemolysk, colonies of pneumococci rcsemble colonies of Str. virtdans. But on further incubation the colonies ofpneumococci become flat with raised edges and central umbonation, so that concentric rings are seen on the surface when viewed from above - draughtsman or Carrom coin appearance.","pyqMatches":[{"year":"2015","no":704,"q":"Draughtsman colonies are seen with:","o":["Anthrax","Pnuemococci","Pertussis","Yersenia"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3259, 'Microbiology', 'Clinical Microbiology', 'Hard', 'Microbiology', 3, '{"id":3259,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Hard","source":"Microbiology","sourceNo":3,"q":"A 20 year old man presented with abdominal pain, vomiting and bloody diarrhea, his stool sample grew Escherichia coli in pure culture. Which of the following serotype of E.coli is the causative agent of hemorrhagic colitis?","o":["O 157:H7","O 159:H7","O 107:H7","O 55:H7"],"a":0,"e":"Enterohemorrhagic E.coli O157:H7 is the serotype of E.coli causing hemorrhagic colitis. It is associated with the ingestion of undercooked hamburger, sprouts, unpasteurized milk or juice. EHEC produces a shiga toxin and can cause colitis after an incubation period of 3 -5 days. It typically produces watery diarrhea that progress to bloody diarrhea after a few hours to few days. Fatigue, abdominal pain, nausea and vomiting are associated complaints. Mechanism of enterohemorrhagic colitis appears to be vascular endothelial damage that leads to platelet aggregation and initiation of the coagulation cascade. This in turn, leads to ischemia of the colon and results in hemorrhagic colitis. Ref: Mayo Clinic Gastroenterology and Hepatology Board Review By Stephen Hauser, 4th Edition, Page 197","pyqMatches":[{"year":"2016","no":718,"q":"A 20 year old man presented with abdominal pain, vomiting and bloody diarrhea, his stool sample grew Escherichia coli in pure culture. Which of the following serotype of E.coli is the causative agent of hemorrhagic colitis?","o":["O 157:H7","O 159:H7","O 107:H7","O 55:H7"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3260, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 4, '{"id":3260,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":4,"q":"Granulomatosis infantiseptica is caused by:","o":["Pseudomonas","Chlamydia trachomatis","Group D streptococci","Listeria"],"a":3,"e":"Granulomatosis infantiseptica is an intra-uterine infection of the newborn caused by listeria. The predominant feature of this condition is extensive focal necrosis affecting especially the liver and, less often, the lungs. The mortality rate is very high. Occasionally meningitis may be associated with it. The organisms can be isolated from the affected areas in the child and frequently from the genital tract of the mother, who may or may not manifest the disease. Ref: Harrisons principles of internal medicine, 18th edition, Page:","pyqMatches":[{"year":"2015","no":695,"q":"Granulomatosis infantiseptica is caused by:","o":["Pseudomonas","Chlamydia trachomatis","Group D streptococci","Listeria"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3261, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 5, '{"id":3261,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":5,"q":"Stalactite growth in ghee broth is due to the following organism?","o":["Y.pestis","T.palladium","H.influenzae","C.diphtheriae"],"a":0,"e":"Cultural characteristics of Yersinia pestis:","pyqMatches":[{"year":"2016","no":729,"q":"Stalactite growth in ghee broth is due to the following organism?","o":["Y.pestis","T.palladium","H.influenzae","C.diphtheriae"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3262, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 6, '{"id":3262,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":6,"q":"Milk ring test is done to detect which organism present in milk?","o":["Bordetella","Brucellosis","Bartonella","Salmonella"],"a":1,"e":"correct answer- B--> Brucellosis For the detection of Brucella in infected animals, pooled milk samples may be tested for bacilli by culture and for antibodies by several techniques. In the milk ring test, a sample of whole milk is mixed well with a drop of stained brucella antigen and incubated in a water bath at 70 degrees for 40-50 min. If antibodies are present in the milk, the bacilli are agglutinated and rise with the cream to form a blue ring at the top, leaving the milk unstained. If antibodies are absent, no colour ring is formed and the milk remains uniformly blue. Also Know: Bordetella is detected using the cough plate method, post nasal swab, and the pernasal swab method. Bartonella bacilliformis causes Oroya fever. Bartonella quintana causes trench fever. Bartonella henselae causes cat scratch disease. Salmonella is detected using a widal reaction.","pyqMatches":[{"year":"2013","no":753,"q":"Milk ring test is done to detect which organism present in milk?","o":["Bordetella","Brucellosis","Bartonella","Salmonella"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":770,"q":"Milk ring test is done to detect which organism present in milk?","o":["Bordetella","Brucellosis","Bartonella","Salmonella"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3263, 'Microbiology', 'General Microbiology', 'Moderate', 'Microbiology', 7, '{"id":3263,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Moderate","source":"Microbiology","sourceNo":7,"q":"TRUE about corynebacterium diphtheriae are all, EXCEPT:","o":["Has metachromatic granules","Does not invade deeper tissues","Toxigenicity demonstrated by elek''s test","Toxin mediated by chromosomal gene"],"a":3,"e":"Corynebacteria are 0.5–1 m in diameter and several micrometers long. Characteristically, they possess irregular swellings at one end that give them the \"club-shaped\" appearance. Irregularly distributed within the rod (often near the poles) are granules staining deeply with aniline dyes (metachromatic granules) that give the rod a beaded appearance. Diphtheria toxin is absorbed into the mucous membranes and causes destruction of epithelium and a superficial inflammatory response. If disulfide bonds are broken, the molecule can be split into two fragments. Fragment B (MW=38,000), which has no independent activity, is functionally divided into a receptor domain and a translocation domain. Acidification of the translocation domain within a developing endosome leads to creation of a protein channel that facilitates movement of Fragment A into the host cell cytoplasm. Toxin fragment A inactivates EF-2 by catalyzing a reaction that yields free nicotinamide plus an inactive adenosine diphosphate- ribose-EF-2 complex (ADP-ribosylation). It is assumed that the abrupt arrest of protein synthesis is responsible for the necrotizing and neurotoxic effects of diphtheria toxin. The toxigenicity of the corynebacterium diphtheriae is demonstrated by Elek test. Ref: Brooks G.F., Carroll K.C., Butel J.S., Morse S.A., Mietzneron T.A. (2010). Chapter 12. Aerobic Nonspore-Forming Gram-Positive Bacilli: Corynebacterium, Listeria, Erysipelothrix, Actinomycetes, & Related Pathogens. In G.F. Brooks, K.C. Carroll, J.S. Butel, S.A. Morse, T.A. Mietzneron (Eds), Jawetz, Melnick, & Adelberg''s Medical Microbiology, 25e.","pyqMatches":[{"year":"2013","no":748,"q":"TRUE about corynebacterium diphtheriae are all, EXCEPT:","o":["Has metachromatic granules","Does not invade deeper tissues","Toxigenicity demonstrated by elek''s test","Toxin mediated by chromosomal gene"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3264, 'Microbiology', 'Clinical Microbiology', 'Moderate', 'Microbiology', 8, '{"id":3264,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Moderate","source":"Microbiology","sourceNo":8,"q":"Respiratory Syncytial Virus (RSV) causes all, EXCEPT:","o":["Coryza in kids","ARDS","Bronchitis","Common cold"],"a":1,"e":"RSV infection leads to a wide spectrum of respiratory illnesses. In infants it can cause pneumonia, bronchiolitis, and tracheobronchitis. In this age group, illness begins most frequently with rhinorrhea, low-grade fever, often accompanied by cough and wheezing. In adults, the most common symptoms are common cold, with rhinorrhea, sore throat, and cough. It cause severe pneumonia in elderly. Sinusitis, otitis media, and worsening of chronic obstructive and reactive airway disease are also associated with RSV infection. Ref: Harrison’s Principles of Internal Medicine, 18th Edition, Chapter 186","pyqMatches":[{"year":"2016","no":750,"q":"Respiratory Syncytial Virus (RSV) causes all, EXCEPT:","o":["Coryza in kids","ARDS","Bronchitis","Common cold"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3265, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 9, '{"id":3265,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":9,"q":"Who is the father of modern Microbiology?","o":["Metchnikoff","Lord Lister","Louis Pasteur","Robert Koch"],"a":2,"e":"Father of Modern Microbiology : Louis Pasteur. Father of Medical Microbiology : Robert Koch. Father of Pathology : Rudolph Virchow.","pyqMatches":[{"year":"2016","no":680,"q":"Who is the father of modern Microbiology?","o":["Metchnikoff","Lord Lister","Louis Pasteur","Robert Koch"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3266, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 10, '{"id":3266,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":10,"q":"Microorganism which causes pyogenic osteomyelitis is ?","o":["Streptococcus","Staph aureus","Corynebacterium","Neisseria gonorrhoeae"],"a":1,"e":"Staphylococcus aureus causes 80–90% of cases of acute pyogenic osteomyelitis. S aureus has a receptor for collagen, which contributes to its pathogenicity. Other organisms that cause osteomyelitis include: Escherichia coli and Pseudomonas in intravenous drug users and patients with urinary tract infections. Haemophilus influenzae and Group B Streptococcus in neonates. Salmonella in patients with sickle cell disease. Ref: Wyatt C., Kemp W.L., Moos P.J., Burns D.K., Brown T.G. (2008). Chapter 19. Pathology of the Bones and Joints. In C. Wyatt, W.L. Kemp, P.J. Moos, D.K. Burns, T.G. Brown (Eds), Pathology: The Big Picture.","pyqMatches":[{"year":"2015","no":1482,"q":"Microorganism which causes pyogenic osteomyelitis is ?","o":["Streptococcus","Staph aureus","Corynebacterium","Neisseria gonorrhoeae"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3267, 'Microbiology', 'Clinical Microbiology', 'Easy', 'Microbiology', 11, '{"id":3267,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":11,"q":"True statement about Pneumocystic Jiroveci is:","o":["Often associated with CMV infection","Usually diagnosed by sputum examination","Infection occurs only in immunocompromised patients","Always associated with Pneumatocele"],"a":1,"e":"Pneumocystis Jiroveci is usually diagnosed by sputum examination. Ref: Medical Microbiology By Jawetz, 24th Edition, Pages 648-49; Washington Manual of Pulmonary Medicine, 2006, Page 104; Pneumocystis Pneumonia By Walzer, Cushion, 3rd Edition, Page 418; Harrison’s Principles of Internal Medicine, 16th Edition, Pages 1194-95","pyqMatches":[{"year":"2014","no":1426,"q":"True statement about Pneumocystic Jiroveci is:","o":["Often associated with CMV infection","Usually diagnosed by sputum examination","Infection occurs only in immunocompromised patients","Always associated with Pneumatocele"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3268, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 12, '{"id":3268,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":12,"q":"Mycobacterium tuberculosis was discoverd by ?","o":["Louis pasteur","Robert koch","Lister","Jener"],"a":1,"e":"Ans. is ''b'' i.e., Robert koch Scientist Associated with Fracastorius Proposed a contagium vivuin (cause of infectious disease) Von Plenciz Suggested that each disease is caused by a separate agent Augustino Bassi Earliest discovery of pathogenic microorganism Davaine and Pollender Observed anthrax bacilli in blood of animal Louis Pasteur Father of microbiology (Also see above explanation) Robert Koch Father of medical microbiology Discovered M. tuberculosis and V cholerae Introduced staining techniques methods of obtaining bacteria in pure culture on solid media Suggested Koch''s postulate Joseph Lister Father of Aseptic surgery Proved that sepsis could be prevented by Proved that sepsis could be prevented by Hand hygiene Antony Van Leeuwen hoek Invented microscope (Father of compound microscope) Father of Bacteriology Edward Jenner Father of Immunology Peyton Rous Isolated virus causing sarcoma in fowl Von Behring & Kitasato Described antibody","pyqMatches":[{"year":"2013","no":717,"q":"Mycobacterium tuberculosis was discoverd by ?","o":["Louis pasteur","Robert koch","Lister","Jener"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3269, 'Microbiology', 'Immunology', 'Moderate', 'Microbiology', 13, '{"id":3269,"subject":"Microbiology","chapter":"Immunology","difficulty":"Moderate","source":"Microbiology","sourceNo":13,"q":"Flagella not true -","o":["Locomotion","Attachment","Protein in nature","Antigenic"],"a":1,"e":"Ans. is ''b'' i.e., Attachment","pyqMatches":[{"year":"2012","no":668,"q":"Flagella not true","o":["Locomotion","Attachment","Protein in nature","Antigenic"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3270, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 14, '{"id":3270,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":14,"q":"Percentage of glutaraldehyde used ?","o":["1%","2%","3%","4%"],"a":1,"e":"Ans. is ''b'' i.e., 2% 2% Glutaradehyde (cidex) is an aldehyde disinfectant with a broad spectrum of action against bacteria, fungi, viruses, as well as spores (slow action).","pyqMatches":[{"year":"2013","no":726,"q":"Percentage of glutaraldehyde used ?","o":["1%","2%","3%","4%"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3271, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 15, '{"id":3271,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":15,"q":"In nutrient agar concentration of agar is -","o":["1%","1.5 %","3%","4%"],"a":1,"e":"Ans. is ''b'' i.e., 1.5% Nutrient Agar is a general-purpose, nutrient medium used for the cultivation of microbes supporting the growth of a wide range of non- fastidious organisms. Nutrient agar is popular because it can grow a variety of types of bacteria and fungi, and contains many nutrients needed for the bacterial growth. Nutrient agar is made by adding 1.5% agar to the nutrient broth. 0.5% Peptone 0.3% beef extract/yeast extract. 0.5% NaCl Distilled water pH is adjusted to neutral (7.4) at 25 °C.","pyqMatches":[{"year":"2012","no":669,"q":"In nutrient agar concentration of agar is","o":["1%","1.5 %","3%","4%"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3272, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 16, '{"id":3272,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":16,"q":"Natural method of horizontal gene transfer among bacteria includes -","o":["Electroporation","Transduction","Transformation","b and c"],"a":3,"e":"Ans. is ''b'' i.e., Transduction; ''c'' i.e., Transformation Gene transfer Gene transfer refers to the process of genetic material (e.g. DNA) being sent and received among two organisms ---> Donor sends and recipient receives the genetic material. There are two processes of gene transfer :? 1) Horizontal gene transfer (HGT) or lateral gene transfer Horizontal gene transfer is the process by which genetic material is passed between two different organism, i.e. organism of different species. The recipient is not the offspring of donor. The most important example is gene transfer between the bacteria. The processes of horizontal gene transfer in bacteria are :-","pyqMatches":[{"year":"2016","no":683,"q":"Natural method of horizontal gene transfer among bacteria includes","o":["Electroporation","Transduction","Transformation","b and c"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3273, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 17, '{"id":3273,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":17,"q":"Which cells cause rosette formation with sheep RBCs-","o":["T cells","NK cells","Monocytes","All"],"a":0,"e":"Ans. is ''a. T cells","pyqMatches":[{"year":"2012","no":746,"q":"Which cells cause rosette formation with sheep RBCs","o":["T cells","NK cells","Monocytes","All"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3274, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 18, '{"id":3274,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":18,"q":"Gene components of HLA class I includes -","o":["A, B, C","DR","DQ","DP"],"a":0,"e":"Ans. is ''a'' i.e., A, B, C . Class I HLA comprises A, B and C loci.","pyqMatches":[{"year":"2012","no":759,"q":"Gene components of HLA class I includes","o":["A, B, C","DR","DQ","DP"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3275, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 19, '{"id":3275,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":19,"q":"Complement attaches to immunoglobulin at ?","o":["Aminoterminal","Fab region","Variable region","Fc fragment"],"a":3,"e":"Ans. is ''d'' i.e., Fc fragment . Fc fragment is composed of the carboxyterminal. It determines the biological activity such as complement fixation, placental transfer, skin fixation and catabolic rate. CH-2 of Ig G and CH, of IgM bind to C1q portion of CI.","pyqMatches":[{"year":"2013","no":816,"q":"Complement attaches to immunoglobulin at ?","o":["Aminoterminal","Fab region","Variable region","Fc fragment"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3276, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 20, '{"id":3276,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":20,"q":"Antigen idiotype is related to -","o":["Fc fragment","Hinge region","C-terminal","N-terminal"],"a":3,"e":"Ans. is ''d'' i.e., N-terminal The idiotype is the specific region of the fab portion (not Fc fragment) of Ig molecule to which antigen binds. Idiotype (antigen binding site) is on variable region, which is at amino terminal (N-terminal). The aminoacid sequences of the variable regions are not uniformly variable along their length, but consist of relatively invariable and some highly variable zones. The higltly variable Zones are involved wlth the formation of antigen binding sites. The sites on the hyervariable regions that make actual contact with the epitopes are called\"complementarity determining Regions.","pyqMatches":[{"year":"2012","no":755,"q":"Antigen idiotype is related to","o":["Fc fragment","Hinge region","C-terminal","N-terminal"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3277, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 21, '{"id":3277,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":21,"q":"Idiotypic class of antibody is determined by -","o":["Fc region","Hinge region","Carboxy end","Amino end"],"a":3,"e":"Ans. is ''d'' i.e., Amino end The idiotype is defined as the specific region of the Fab portion of the Ig molecule to which antigen binds. It is on aminoterminal where antigen binding site is present.","pyqMatches":[{"year":"2012","no":742,"q":"Idiotypic class of antibody is determined by","o":["Fc region","Hinge region","Carboxy end","Amino end"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3278, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 22, '{"id":3278,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":22,"q":"Antibody diversity is due to -","o":["Gene rearrangement","Gene translocation","Antigenic variation","a and c"],"a":3,"e":"Ans. is ''a'' i.e., Gene rearrangement; ''c'' i.e., Antigenic variation","pyqMatches":[{"year":"2016","no":774,"q":"Antibody diversity is due to","o":["Gene rearrangement","Gene translocation","Antigenic variation","a and c"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
