INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3280, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 24, '{"id":3280,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":24,"q":"Pentavalent immunoglobin is","o":["IgA","IgG","IgM","IgE"],"a":2,"e":"Ans. is ''c'' i.e., IgM","pyqMatches":[{"year":"2012","no":748,"q":"Pentavalent immunoglobin is","o":["IgA","IgG","IgM","IgE"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
