INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3282, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 26, '{"id":3282,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":26,"q":"Which of the following immunoglobulin is responsible for opsonisation -","o":["IgA","Ig G","Ig M","none"],"a":2,"e":"Ans. is ''c'' i.e., IgM > ''b'' i.e., IgG","pyqMatches":[{"year":"2012","no":753,"q":"Which of the following immunoglobulin is responsible for opsonisation","o":["IgA","Ig G","Ig M","none"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3283, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 27, '{"id":3283,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":27,"q":"Activation of classical complement pathway ?","o":["IgA","IgG","IgM","IgD"],"a":2,"e":"Ans. is ''c'' i.e., IgM","pyqMatches":[{"year":"2012","no":756,"q":"Activation of classical complement pathway ?","o":["IgA","IgG","IgM","IgD"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3284, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 28, '{"id":3284,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":28,"q":"The Fc piece of which immunoglobulin fixes C1","o":["IgA","IgG","IgM","c and b"],"a":3,"e":"Ans. is ''c'' > ''b'' i.e., IgM > IgG Make it very clear in your mind that both IgM and IgG fix C 1. \" C2 of IgG and C114 of IgM bind to CIq portion of C1\"-------- Ananthanarayan \"CIq portion of CI is an aggregate of 18 polypeptides that binds to the Fc portion of IgM and igG.\"---LANGE microbiology However, if you will have to choose one option, IgM is the best because IgM is more effective than IgG for complement fixation.","pyqMatches":[{"year":"2013","no":817,"q":"The Fc piece of which immunoglobulin fixes C1","o":["IgA","IgG","IgM","c and b"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3285, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 29, '{"id":3285,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":29,"q":"Antibody elevated in parasitic infection ?","o":["IgA","IgE","IgG","IgM"],"a":1,"e":"Ans. is ''b'' i.e., IgE","pyqMatches":[{"year":"2012","no":760,"q":"Antibody elevated in parasitic infection ?","o":["IgA","IgE","IgG","IgM"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3286, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 30, '{"id":3286,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":30,"q":"Papain acts an gamma globulin to form ?","o":["2 Fc fragments","2 Fab fragments","1 Fab fragments","None"],"a":1,"e":"Ans. is ''b'' i.e., 2 Fab fragments . Papain acts at hinge region to produce :? 1) One Fe fragments 2) Two Fab fragments","pyqMatches":[{"year":"2013","no":809,"q":"Papain acts an gamma globulin to form ?","o":["2 Fc fragments","2 Fab fragments","1 Fab fragments","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3287, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 31, '{"id":3287,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":31,"q":"Which of the following T cell independent Antigen acts through -","o":["T-cell","B-cell","Macrophages","CD8+ T cells"],"a":1,"e":"Ans. is ''b'' i.e., B-cells T-cell independent antigens directly stimulates B-cells without processing by antigen presenting cells.","pyqMatches":[{"year":"2012","no":751,"q":"Which of the following T cell independent Antigen acts through","o":["T-cell","B-cell","Macrophages","CD8+ T cells"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3288, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 32, '{"id":3288,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":32,"q":"Which part of bacteria is most antigenic ?","o":["Protein coat","Lipopolysaccharide","Nucleic acid","Lipids"],"a":0,"e":"Ans. is d i.e., Lipids Proteins are most immunogenic, while lipids & nucleic acids are least immunogenic. Polysaccharides (carbohydrates) are less immunogenic than protein antigens, but are more antigenic than lipids & nucleic acids.","pyqMatches":[{"year":"2012","no":666,"q":"Which part of bacteria is most antigenic ?","o":["Protein coat","Lipopolysaccharide","Nucleic acid","Lipids"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3289, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 33, '{"id":3289,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":33,"q":"Superantigen causes -","o":["Polyclonal activation of T-cells","Stimulation of B cells","Enhancement of phagocytosis","Activation of complement"],"a":0,"e":"Ans. is ''a'' i.e., Polyclonal activation of T-cells Superantigens are capable of activating up to 20% of the peripheral T-cell pool, where as conventional antigens activate < 1 in 10, 000.","pyqMatches":[{"year":"2012","no":757,"q":"Superantigen causes","o":["Polyclonal activation of T-cells","Stimulation of B cells","Enhancement of phagocytosis","Activation of complement"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3290, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 34, '{"id":3290,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":34,"q":"Prozone phenomenon is seen with?","o":["Same concentration of antibody and antigen","In antigen excess to antibody","Antibody excess to antigen","Hyperimmune reaction"],"a":2,"e":". Ans. is ''c'' i.e., Antibody excess to antigen","pyqMatches":[{"year":"2012","no":743,"q":"Prozone phenomenon is seen with?","o":["Same concentration of antibody and antigen","In antigen excess to antibody","Antibody excess to antigen","Hyperimmune reaction"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3291, 'Microbiology', 'Clinical Microbiology', 'Easy', 'Microbiology', 35, '{"id":3291,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":35,"q":"Paul bunnel reaction is a type of","o":["Agglutination","CF","Precipitation","Flocculation test"],"a":0,"e":"Ans. is ''a'' i.e., Agglutination test Paul Bunnell test is tube agglutination test.","pyqMatches":[{"year":"2012","no":745,"q":"Paul bunnel reaction is a type of","o":["Agglutination","CF","Precipitation","Flocculation test"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3292, 'Microbiology', 'Immunology', 'Moderate', 'Microbiology', 36, '{"id":3292,"subject":"Microbiology","chapter":"Immunology","difficulty":"Moderate","source":"Microbiology","sourceNo":36,"q":"All are ture about innate immunity except ?","o":["Non-specific","First line of defence","Not affected by genetic affected","Includes complement"],"a":2,"e":"Ans. is ''c'' i.e., Not affected by genetic affected","pyqMatches":[{"year":"2012","no":747,"q":"All are ture about innate immunity except ?","o":["Non-specific","First line of defence","Not affected by genetic affected","Includes complement"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3293, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 37, '{"id":3293,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":37,"q":"When transfer factor is given as treatment results in -","o":["Natural active immunity","Artificial active immunity","Artificial passive immunity","Adoptive immunity"],"a":3,"e":"Ans. is ''d'' i.e., Adoptive immunity","pyqMatches":[{"year":"2015","no":795,"q":"When transfer factor is given as treatment results in","o":["Natural active immunity","Artificial active immunity","Artificial passive immunity","Adoptive immunity"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3294, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 38, '{"id":3294,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":38,"q":"Which is found in DiGeorge''s syndrome -","o":["Tetany","Eczema","Total absence of T cells","Absent B and T cells"],"a":0,"e":"Ans. is ''a'' i.e., Tetany Digeorge syndrome Digeorge syndrome is an example of a T cell deficiency that results from failure of development of the third and fourth pharyngeal pouches. * Clinical features? * Enhanced susceptibility to viral, fungal (mucocutaneous candidiasis) and bacterial infections. * Facial abnormalities : Hypertelorism, abnormal ears, short philtrum and micrognathia. Hypocalcemic tetany due to failure of parathyroid development. Congenital heart diseases eg fallot''s tetralogy. * Absence of a normal thymus. * Serum immunoglobulin concentration are frequently normal, but antibody responses, particularly of IgG and IgA isotypes, are usually impaired. * T cell levels are reduced (not total absence). * B cell levels are normal.","pyqMatches":[{"year":"2015","no":1425,"q":"Which is found in DiGeorge''s syndrome","o":["Tetany","Eczema","Total absence of T cells","Absent B and T cells"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3295, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 39, '{"id":3295,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":39,"q":"Complement formed in liver -","o":["C2, C4","C3, C6, C9","C5, C8","C1"],"a":1,"e":"Ans. is b'' i.e., C3, C6, C9 Biosynthesis of complement components . Complement components are synthesized in various sites of body :- i) Intestine —> Cl ii) Macrophages —> C2, C4 iii) Spleen —> C5, C8 iv) Liver --> C3, C6, C9","pyqMatches":[{"year":"2012","no":758,"q":"Complement formed in liver","o":["C2, C4","C3, C6, C9","C5, C8","C1"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
