INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3297, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 41, '{"id":3297,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":41,"q":"Hereditary angioneurotic edema is due to ?","o":["Deficiency of C1 inhibitor","Deficiency of NADPH oxidase","Deficiency of MPO","Deficiency of properdin"],"a":0,"e":"Ans. is ''a'' i.e., Deficiency of C1 inhibitor Hereditary angioneurotic edema is due to C1inhibitor (Ci esterase inhibitor) deficiency.","pyqMatches":[{"year":"2012","no":1383,"q":"Hereditary angioneurotic edema is due to ?","o":["Deficiency of C1 inhibitor","Deficiency of NADPH oxidase","Deficiency of MPO","Deficiency of properdin"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3298, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 42, '{"id":3298,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":42,"q":"Opsonization takes place through -","o":["C3a","C3b","C5a","C5b"],"a":1,"e":"Ans. is ''b'' i.e., C3b","pyqMatches":[{"year":"2012","no":754,"q":"Opsonization takes place through","o":["C3a","C3b","C5a","C5b"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3299, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 43, '{"id":3299,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":43,"q":"Rosette formation with sheep RBC''s indicate functioning of -","o":["T-cells","B-cells","Neutrophils","Monocytes"],"a":0,"e":"Ans. is ''a'' i.e., T-cells T cells bind to sheep erythrocytes forming rosettes (SRBC or E rosette) by CD2 antigen.","pyqMatches":[{"year":"2013","no":815,"q":"Rosette formation with sheep RBC''s indicate functioning of","o":["T-cells","B-cells","Neutrophils","Monocytes"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3300, 'Microbiology', 'Miscellaneous', 'Moderate', 'Microbiology', 44, '{"id":3300,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Microbiology","sourceNo":44,"q":"Digeorge syndrome is characterized by all except ?","o":["Congenital thymic hypoplasia","Abnormal development of third and fourth pouches","Hypothyroidism","Hypocalcemic tetany"],"a":2,"e":"Ans. is ''c'' i.e., Hypothyroidism","pyqMatches":[{"year":"2016","no":7,"q":"Digeorge syndrome is characterized by all except ?","o":["Congenital thymic hypoplasia","Abnormal development of third and fourth pouches","Hypothyroidism","Hypocalcemic tetany"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3301, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 45, '{"id":3301,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":45,"q":"Staph aureus causes -","o":["Erythrasma","Chancroid","Acne vulgaris","Bullous impetigo"],"a":3,"e":"Ans. is ''d'' i.e., Bullous impetigo Impetigo is divided into two types :? i) Non-bullous impetigo (Impetigo contagiosum) :- Caused by staphylococcus aureus and streptococcus pyogenes. ii) Bullous impetigo :- Caused by staphylococcus aureus.","pyqMatches":[{"year":"2012","no":674,"q":"Staph aureus causes","o":["Erythrasma","Chancroid","Acne vulgaris","Bullous impetigo"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3302, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 46, '{"id":3302,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":46,"q":"Glomerulonephritis in streptococcal infection is diagnosed by -","o":["Blood culture","Throat culture","ASO Titre","PCR"],"a":2,"e":"Ans. is ''c'' i.e., ASO Titre In rheumatic fever and glomerulonephritis, retrospective diagnosis of streptococcal infection may be established by demonstrating high levels of antibodies to streptococcal toxins. The usual test done is antistreptolysin O titration. ASO titres higher than 200 units are considered significant and suggests either recent or recurrent infection with streptococci. ASO titres > 200 units do not mean rheumatic fever, it only indicates recent or recurrent infection.","pyqMatches":[{"year":"2013","no":752,"q":"Glomerulonephritis in streptococcal infection is diagnosed by","o":["Blood culture","Throat culture","ASO Titre","PCR"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3303, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 47, '{"id":3303,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":47,"q":"Which group of streptococcus grow at > 60°C","o":["A","B","C","D"],"a":3,"e":"Ans. is ''d'' i.e., D Among streptococci, enterococcus (group D streptococcus) is heat resistant.","pyqMatches":[{"year":"2012","no":679,"q":"Which group of streptococcus grow at > 60°C","o":["A","B","C","D"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3304, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 48, '{"id":3304,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":48,"q":"Pneumococcal vaccine is prepared from ?","o":["Cell surface antigen","Capsular polysaccharide","From exotoxin","From M protein"],"a":1,"e":"Ans. is ''b'' i.e., Capsular polysaccharide There are two types of pneumococcal vaccines available : -","pyqMatches":[{"year":"2013","no":746,"q":"Pneumococcal vaccine is prepared from ?","o":["Cell surface antigen","Capsular polysaccharide","From exotoxin","From M protein"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3305, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 49, '{"id":3305,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":49,"q":"Meningococci differ from gonococci in that they?","o":["Are intra-cellular","Possess a capsule","Cause fermentation of glucose","Are oxidase positive"],"a":1,"e":"Ans. is ''b'' i.e., Possess a capsule","pyqMatches":[{"year":"2012","no":683,"q":"Meningococci differ from gonococci in that they?","o":["Are intra-cellular","Possess a capsule","Cause fermentation of glucose","Are oxidase positive"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3306, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 50, '{"id":3306,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":50,"q":"Virulence of gonococci is due to -","o":["Pili","Endotoxin","Exotoxin","None"],"a":0,"e":"Ans. is ''a'' i.e., Pili . Major virulence factor for gonococci is pill (fimbriae).","pyqMatches":[{"year":"2012","no":686,"q":"Virulence of gonococci is due to","o":["Pili","Endotoxin","Exotoxin","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3307, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 51, '{"id":3307,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":51,"q":"Meningitis with rash is seen in -","o":["Neisseria meningitidis","H. influenzae","Strepto. agalactae","Pneumococcus"],"a":0,"e":"Ans. is ''a'' i.e., Neisseria meningitidis","pyqMatches":[{"year":"2012","no":688,"q":"Meningitis with rash is seen in","o":["Neisseria meningitidis","H. influenzae","Strepto. agalactae","Pneumococcus"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3308, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 52, '{"id":3308,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":52,"q":"The vaccine against N-meningitidis contains ?","o":["Whole bacteria","Capsular polysaccharide","Somatic ''0'' antigen","None of these"],"a":1,"e":"Ans. is ''b'' i.e., Capsular polysaccharide Meningococcal vaccine Meningococcal vaccine refers to any of the vaccines used to prevent infection by Neisseria meningitidis. Different versions are effective against some or all of the following types of meningococcus: A, B, C, W-135, and Y Effective vaccines prepared from purified Group A, Group C, Group Y, and or Group W - 135 meningococcal capsular polysaccharides. The immunity is group-specific. Meningococcal vaccines containing unconjugated purified capsular polysaccharides (A, C, Y and W) have been available since the 1970s and are still used to immunise travellers and at-risk individuals. Vaccines can be formulated as bivalent (groups A and C) or tetravalent (groups A, C, Y, and W135). The vaccines induce good immunity after a single dose in older children and adults but are of a little valve in children below 3 years. It takes 10-14 days for immunity to develop. There is no Group B vaccine available at present.","pyqMatches":[{"year":"2013","no":743,"q":"The vaccine against N-meningitidis contains ?","o":["Whole bacteria","Capsular polysaccharide","Somatic ''0'' antigen","None of these"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3309, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 53, '{"id":3309,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":53,"q":"Daisy head colonies are seen with -","o":["Staph. Aureus","Corynebacterium diphtheriae","Staph. Pyogenes","Anthrax"],"a":1,"e":"Ans. is ''b'' i.e., Corynebacterium Diphtheriae Four subspecies are recognized: C. d. mitis, C. d. intermedius, C. d. gravis, and C. d. belfanti. C.d.Gravis Colony on Tellurite Blood Agar is having ≥ 2mm, dull greyish black, opaque colonies, daisy head, brittle, like cold margarine. Special stains like Albert’s stain and Ponder''s stain are used to demonstrate the metachromatic granules formed in the polar regions. The granules are called polar granules, Babes Ernst granules, volutin etc daisy-head colony. a round grey or black colony with a narrow translucent scalloped border, typically produced by Corynebacterium diphtheriae on tellurite blood agar.","pyqMatches":[{"year":"2013","no":749,"q":"Daisy head colonies are seen with","o":["Staph. Aureus","Corynebacterium diphtheriae","Staph. Pyogenes","Anthrax"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3310, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 54, '{"id":3310,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":54,"q":"The \"String of pearl\" colonies on Nutrient agar is produced by -","o":["Klebsiella","Proteus","Bacillus","Salmonella"],"a":2,"e":"Ans. is ''c'' i.e.,Bacillus String of pearl reaction String of pearl reaction is used to differentiate B. anthracis from B. cereus and other aerobic spore-forming bacteria. When B. anthracis is grown on a solid medium containing penicillin, the cells become larger, spherical and occur in chains on the surface of the agar, resembling a string of pearls.","pyqMatches":[{"year":"2013","no":757,"q":"The \"String of pearl\" colonies on Nutrient agar is produced by","o":["Klebsiella","Proteus","Bacillus","Salmonella"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3311, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 55, '{"id":3311,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":55,"q":"Saccharolytic species of clostridia ?","o":["C. tetani","Cl. cochlearum","Cl. septicum","None"],"a":2,"e":"Ans. is ''c'' i.e., Cl. septicum Clostridia may break down carbohydrate for energy (saccharolytic) or break down protein for energy Proteolytic) or both. Different clostridia have a different pattern:- A) Both proteolytic and saccharolytic Pre-dominating proteolytic- Cl. sporogenes, Cl botulinum A.B.F., Cl. bifermentans, Cl. histolyticum. Pre-Dominating Saccharolytic - Cl. perfringens, Cl. noyyi, Cl. septicum, Cl. difficile. B) Only proteolytic (not saccharolytic) - Cl. tetani C) Only Saccharolytic (not proteolytic) - Cl. botulinum C.D.E. D) Neither proteolytic nor saccharolytic - Cl. cochlear","pyqMatches":[{"year":"2013","no":758,"q":"Saccharolytic species of clostridia ?","o":["C. tetani","Cl. cochlearum","Cl. septicum","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3312, 'Microbiology', 'Immunology', 'Moderate', 'Microbiology', 56, '{"id":3312,"subject":"Microbiology","chapter":"Immunology","difficulty":"Moderate","source":"Microbiology","sourceNo":56,"q":"The following statements are true regarding botulism except -","o":["Infant botulism is caused by ingestion of preformed toxin","Clostridium botulinum A, B, C and F cause human disease","The gene for botulinum toxin is encoded by a bacteriophage","Clostridium baratti may cause botulism"],"a":0,"e":"Ans. is ''a'' i.e., Infant botulism is caused by ingestion of preformed toxin Infant botulism is caused by ingestion of spores. Spores are ingested in food, get established in the gut and there produce the toxin. \"Seven main types of C. botulinum, designated A - G, produce antigenically distinct toxins with pharmacologically identical action. All types can cause human disease, but type A, B and E are most common\". (In Harrison & Ananthanarayan, eight types of C. botulinum A, B, CI, C2, D, E, F, G have been mentioned). Toxin production in clostridium botulinum appears to be determined by presence of bacteriophage (at least in type C & D). \"Clostridium butyricum and clostridium baratti have also been found to produce toxin\". - Harrison 16th/e 843 - Any strain producing toxin will obviously cause botulism.","pyqMatches":[{"year":"2016","no":1165,"q":"The following statements are true regarding botulism except","o":["Infant botulism is caused by ingestion of preformed toxin","Clostridium botulinum A, B, C and F cause human disease","The gene for botulinum toxin is encoded by a bacteriophage","Clostridium baratti may cause botulism"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3313, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 57, '{"id":3313,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":57,"q":"Botulism is most commonly due to -","o":["Egg","Milk","Meat","Pulses"],"a":2,"e":"Ans. is ''c'' i.e., Meat Following new types of botulism have been added in 18th/e of Harrison . Adult intestinal toxemia botulism :- results from absorption of toxin produced in situ after rarely occuring intestinal colonization with toxigenic clostridia. . Iatrogenic botulism :- results from injection of botulism toxin.","pyqMatches":[{"year":"2012","no":677,"q":"Botulism is most commonly due to","o":["Egg","Milk","Meat","Pulses"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3314, 'Microbiology', 'Miscellaneous', 'Moderate', 'Microbiology', 58, '{"id":3314,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Microbiology","sourceNo":58,"q":"Pseudomembranous colitis, all are true except -","o":["Toxin A is responsible for clinical manifestation","Toxin B is responsible for clinical manifestation","Blood in stools is a common feature","Summit lesions is early histopathological finding"],"a":2,"e":"Ans. is ''c'' i.e., Blood in stools is a common feature","pyqMatches":[{"year":"2013","no":714,"q":"Pseudomembranous colitis, all are true except","o":["Toxin A is responsible for clinical manifestation","Toxin B is responsible for clinical manifestation","Blood in stools is a common feature","Summit lesions is early histopathological finding"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3315, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 59, '{"id":3315,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":59,"q":"Shigella are be divided into subgroup on the basis of ability to ferment -","o":["Lactose","Maltose","Fructose","Mannitol"],"a":3,"e":"Ans. is ''d'' i.e., Mannitol Fermentation of mannitol is of importance in classification Shigella Mannitol fermenting Mannitol nonfermenting Sh. flexneri (sub group B) Sh. dysenteriae (sub group A) Sh boydii (sub group C) Sh. Sonnei (sub group D)","pyqMatches":[{"year":"2014","no":740,"q":"Shigella are be divided into subgroup on the basis of ability to ferment","o":["Lactose","Maltose","Fructose","Mannitol"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3316, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 60, '{"id":3316,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":60,"q":"Which of the following stimulate adenylate cyclase with G-protein coupled action ?","o":["Shiga toxin","Cholera toxin","Diphtheria toxin","Pseduomonas toxin"],"a":1,"e":"Ans. is ''b'' i.e., Cholera toxin","pyqMatches":[{"year":"2013","no":739,"q":"Which of the following stimulate adenylate cyclase with G-protein coupled action ?","o":["Shiga toxin","Cholera toxin","Diphtheria toxin","Pseduomonas toxin"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3317, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 61, '{"id":3317,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":61,"q":"Cholera toxin is due to -","o":["Chromosome","Plasmid","Phage","Transposons"],"a":2,"e":"Ans. is ''c'' i.e., Phage . Cholera toxin production is determined by a filamentous phage integrated with bacterial chromosome.","pyqMatches":[{"year":"2012","no":684,"q":"Cholera toxin is due to","o":["Chromosome","Plasmid","Phage","Transposons"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3318, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 62, '{"id":3318,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":62,"q":"Psedomonas is which type of bacteria ?","o":["Anaerobic","Microaerophilic","Microaerophilic","Obligate anaerobe"],"a":2,"e":"Ans. is ''c'' i.e., Microaerophilic","pyqMatches":[{"year":"2013","no":720,"q":"Psedomonas is which type of bacteria ?","o":["Anaerobic","Microaerophilic","Microaerophilic","Obligate anaerobe"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3319, 'Microbiology', 'Clinical Microbiology', 'Moderate', 'Microbiology', 63, '{"id":3319,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Moderate","source":"Microbiology","sourceNo":63,"q":"What is NOT true about yersiniosis -","o":["Gram-negative bacillus","Caused by Y pestis","By yersinia enterocolitica","By yersinia pseudotuberculosis"],"a":1,"e":"Ans. is ''b'' i.e., Caused by yersinia pestis Yersiniosis is an infectious disease caused by a bacterium of the genus Yersinia. Yersinia enterocolitica is a Gram-negative bacillus- shaped bacterium, belonging to the family Yersiniaceae. It is motile at temperatures of 22–29° C (72-84°F), but becomes nonmotile at normal human body temperature.[1][2] Y. enterocolitica infection causes the disease yersiniosis, which is an animal-borne disease occurring in humans, as well as in a wide array of animals such as cattle, deer, pigs, and birds. Infection caused by yersinia genus are divided into :- i) Plague :- It is a deadly infectious disease caused by yersinia pestis. ii) Yersinosis :- It is characterized by infectious diarrhea, enteritis, ileitis and occasionally septicemia. It is caused by yersinia enterocolitica (most common) and yersinia pseudotuberculosis.","pyqMatches":[{"year":"2012","no":692,"q":"What is NOT true about yersiniosis","o":["Gram-negative bacillus","Caused by Y pestis","By yersinia enterocolitica","By yersinia pseudotuberculosis"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3320, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 64, '{"id":3320,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":64,"q":"True about H influenza -","o":["Grown on sheep blood agar & CO2","it is not capsulated","Invasive strain is most common","Gram positive"],"a":2,"e":"Ans. is ''c'' i.e., Invasive strain is most common Invasive disease is more common than non-invasive disease. H. influenzae does not grow on blood agar. It is gram negative and capsulated.","pyqMatches":[{"year":"2012","no":682,"q":"True about H influenza","o":["Grown on sheep blood agar & CO2","it is not capsulated","Invasive strain is most common","Gram positive"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3321, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 65, '{"id":3321,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":65,"q":"Thumb print appearance in culture film smear is seen -","o":["Bacillus anthracis","Brucella, species","Bordetella pertussis","Clostridium Welchii"],"a":2,"e":"Ans. is ''c'' i.e., Bordetella pertussis In culture smears, the bacilli are arranged in loose clumps with clear spaces in between giving a thumbprint appearance. Culture Characteristics of Bordetella Incorporation of diamine fluoride and penicillin (Lacey''s DFP medium) makes it more selective. It produces bisected pearl or mercury drops colonies. Confluent growth is present with “aluminium paint” appearance. In culture smears the bacilli are arranged in loose clumps with clear spaces in between giving a thumbprint appearance. Transport media used are modified by Stuart''s medium and Mischulo’s charcoal agar.","pyqMatches":[{"year":"2013","no":760,"q":"Thumb print appearance in culture film smear is seen","o":["Bacillus anthracis","Brucella, species","Bordetella pertussis","Clostridium Welchii"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3322, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 66, '{"id":3322,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":66,"q":"Tuberculin test is positive if induration is ?","o":[">2min",">5mm",">7mm",">10mrn"],"a":3,"e":"Ans. is ''d'' i.e., > 10mm The tuberculosis skin test is another name for the tuberculin test or PPD test. The PPD test determines if someone has developed an immune response to the bacterium that causes tuberculosis (TB) A tuberculin reaction is classified as positive based on the diameter of the induration in conjunction with certain patient- specific risk factors. In a healthy person whose immune system is normal, induration greater than or equal to 15 mm is considered a positive skin test. Procedure The standard recommended tuberculin test is the Mantoux test, which is administered by injecting a 0.1 mL of liquid containing 5 TU (tuberculin units) PPD (purified protein derivative) into the top layers of skin of the forearm. Doctors should read skin tests 48-72 hours after the injection. The basis of the reading of the skin test is the presence or absence and the amount of induration (localized swelling). A negative test does not always mean that a person is free of tuberculosis. A person who received a BCG vaccine (administered in some countries but not the U.S.) against tuberculosis may also have a positive skin reaction to the TB test.","pyqMatches":[{"year":"2013","no":751,"q":"Tuberculin test is positive if induration is ?","o":[">2min",">5mm",">7mm",">10mrn"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3323, 'Microbiology', 'Clinical Microbiology', 'Easy', 'Microbiology', 67, '{"id":3323,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":67,"q":"Pigment producing atypical mycobacteria ?","o":["M. fortution and M. chelonae","M. xenopi and MAC","M. gordonae and M. szulgai","M. ulcerans"],"a":2,"e":"Ans. is ''c'' i.e., M. gordonae and M. szulgai Non-tubercular mycobacteria (also called atypical mycobacteria) have been classified into four groups by Runyon based on pigment production and rate of growth. 1) Group I (photochromogens) :- These produce pigmented colonies (yellow-orange) only when exposed to light, but not in dark. Examples of photochromogens are M. asiaticum, M. kansasii, M. marinum, and M. simiae. 2) Group II (scotochromogens) :- These always produce pigmented colonies (yellow-orange-red), i.e. in dark as well as in light. Scotochromogens are M. flovescens, M. gordonae, M. scrofulaceum and M. szulgi. 3) Group HI (Nonchromogens) :- These do not produce pigment. Nonchromogens are M. avium complex (MAC), M. haemophilum, M. gastri, M. ulcerans, M. xenopi and M. nonchromogenicum. 4) Group IV (rapid growers) :- This is heterogeneous group of mycobacteria capable of rapid growth, colonies appearing within 7 days of incubation. Within the group, photochromogenic, scotochromogenic and nonchromogenic species occur. Chromogenic (pigment producing) rapid growers are mostly saprophytic, e.g. M. phlei and M. smegmetis. M. fortuitum and M. chelonei do not produce any pigment. Other rapid growers are M. abscessus, M. vaccae, M. genevense, M. confluentis, and M. intermedium.","pyqMatches":[{"year":"2012","no":680,"q":"Pigment producing atypical mycobacteria ?","o":["M. fortution and M. chelonae","M. xenopi and MAC","M. gordonae and M. szulgai","M. ulcerans"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3324, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 68, '{"id":3324,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":68,"q":"Fish tank granuloma is seen in -","o":["M fortuitum","M kansasi","M marinum","M leprosy"],"a":2,"e":"Ans. is ''c'' i.e., M. Marinum '' Fish tank granuloma'', also called swimming pool granuloma'' , is caused by M. marinum.","pyqMatches":[{"year":"2012","no":696,"q":"Fish tank granuloma is seen in","o":["M fortuitum","M kansasi","M marinum","M leprosy"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3325, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 69, '{"id":3325,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":69,"q":"Tabes dorsalis is seen in -","o":["Primary syphilis","Secondary syphilis","Tertiary syphilis","Latent syphilis"],"a":2,"e":"Ans. is ''c'' i.e., Tertiary syphilis","pyqMatches":[{"year":"2012","no":687,"q":"Tabes dorsalis is seen in","o":["Primary syphilis","Secondary syphilis","Tertiary syphilis","Latent syphilis"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3326, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 70, '{"id":3326,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":70,"q":"True about VDRL test -","o":["Non - specific","Slide flocculation test","Best followed for drug therapy","All"],"a":3,"e":"Ans is ''d'' i.e., All","pyqMatches":[{"year":"2015","no":775,"q":"True about VDRL test","o":["Non - specific","Slide flocculation test","Best followed for drug therapy","All"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3327, 'Microbiology', 'Clinical Microbiology', 'Easy', 'Microbiology', 71, '{"id":3327,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":71,"q":"TRUE about mycoplasma is -","o":["Causes lung infection","Penicillin is drug of choice","Thick cell wall","Thallium acetate inhibits the growth"],"a":0,"e":"Ans. is ''a'' i.e., Causes lung infection Mycoplasma infections . Mycoplasma pneumoniae causes infection of upper and lower respiratory tract. . Highest attack rates in 5 - 20 years old. . Children < 5 yrs Upper respiratory symptoms . Children > 5 yrs —0. Bronchitis and pneumonia . disease. About other options . Penicillin is not active against mycoplasmas. . Mycoplasmas lack cell wall. Mycoplasmas are resistant to thallium acetate in a concentration of 1:10000","pyqMatches":[{"year":"2012","no":675,"q":"TRUE about mycoplasma is","o":["Causes lung infection","Penicillin is drug of choice","Thick cell wall","Thallium acetate inhibits the growth"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3328, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 72, '{"id":3328,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":72,"q":"Seven sheathed flagella is seen in -","o":["V cholera","H pylori","Ps aeroginosa","Spirochetes"],"a":1,"e":"Ans. is ''b'' i.e., H. pyroli H. pylori has five to seven sheathed polar flagella. Vibrio cholerae and Pseudomonas aeruginosa have single polar flagellum. Occasional strains of pseudomonas may contain 2 or 3 flagella. Spirochetes (Treponema) is motile by endoflagella.","pyqMatches":[{"year":"2012","no":681,"q":"Seven sheathed flagella is seen in","o":["V cholera","H pylori","Ps aeroginosa","Spirochetes"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3329, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 73, '{"id":3329,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":73,"q":"Legionnaire disease is caused by?","o":["Motile gram positive","Motile gram negative","Non-motile gram positive","Non-motile gram negative"],"a":1,"e":"Ans. is ''b'' i.e., Motile gram-negative Legionella is a gram-negative, non-capsulated coccobacillus which is motile by polar or subpolar Flagella. Legionella causes the following infections : A) Pulmonary infections There are two types of pulmonary infections:-","pyqMatches":[{"year":"2016","no":708,"q":"Legionnaire disease is caused by?","o":["Motile gram positive","Motile gram negative","Non-motile gram positive","Non-motile gram negative"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3330, 'Microbiology', 'Immunology', 'Hard', 'Microbiology', 74, '{"id":3330,"subject":"Microbiology","chapter":"Immunology","difficulty":"Hard","source":"Microbiology","sourceNo":74,"q":"Patient came from Nagaland and shows positive test with OXK antigen. Diagnosis is?","o":["Trench fever","Scrub typhus","Endemic typhus","Epidemic typhus"],"a":1,"e":"Ans. is ''b'' i.e., Scrub typhus Weil Felix reaction (Detect OXK antibodies) . This reaction is an agglutination test in which sera are tested for agglutinins to 0 antigens of certain non-motile proteus strains OX - 19, OX - 2 and OX - K. The basis of the test is the sharing of an alkali - stable carbohydrate antigen by some rickettsiae and by certain strains of proteus, P. vulgaris OX - 19 and OX - 2 and P. mirabilis OX - K. The test is usually done as a tube agglutination, though rapid slide agglutination methods have been employed for screening. Weil Felix Reaction Disease OX- 19 OX-2OX- K Rocky Mountain spotted fever Rickettsial pox Epidemic typhus + - + + - - ? ? _ Brill - Zinsser disease +/- - ? Scrub typhus - - + Endemic typhus + - ? Trench fever - ? Q fever -","pyqMatches":[{"year":"2013","no":738,"q":"Patient came from Nagaland and shows positive test with OXK antigen. Diagnosis is?","o":["Trench fever","Scrub typhus","Endemic typhus","Epidemic typhus"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3331, 'Microbiology', 'General Microbiology', 'Moderate', 'Microbiology', 75, '{"id":3331,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Moderate","source":"Microbiology","sourceNo":75,"q":"All are true about B. Quintana except -","o":["Causes trench fever","Not detected by weil felix reaction","Recurrence is common","Tick is the vector"],"a":3,"e":"Ans. is ''d'' i.e., Tick is the vector Trench fever Trench fever, also called 5-day fever or quintan fever, is caused by Bartonella quintana (Rochalimaea quintana). The human body louce (Pediculus humans corporis) is the vector and humans is the only known reservoir. Clinical manifestations The incubation period is 15-25 days (range, 3-38 days). ''Classical'' trench fever presents as febrile illness. Fever is exceedingly variable, but commonly lasts for about 5 days. The fever is followed by a remission and a recurrence after 5 days. These recurrences may be single or multiple and upto 12 recurrences every 5-6 days are not uncommon. Other symptoms and signs include headache, back and limb pain, profuse sweating, shivering, myalgia, arthralgia, splenomegaly, a maculopapular rash in occasional cases, and nuchal rigidity in some cases. Diagnosis Definitive diagnosis requires isolation of B. quintana by blood culture. Weil-Felix test used for diagnosis of ricketssial infection is negative in trench fever. Treatment It is treated with gentamycin along with doxycycline.","pyqMatches":[{"year":"2012","no":693,"q":"All are true about B. Quintana except","o":["Causes trench fever","Not detected by weil felix reaction","Recurrence is common","Tick is the vector"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3332, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 76, '{"id":3332,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":76,"q":"Boutonneuse fever is caused by -","o":["Rickettsia japonica","Rickettsia conorii","Rickettsia sibirica","Rickettsia australis"],"a":1,"e":"Ans. is ''b'' i.e., Rickettsia conorii Tick borne fevers caused by Rickettsie Organism Fever caused R. conorii Mediterranean spotted fever (boutonneuse fever) Kenya tick typhus Indian tick typhus South African tick typhus Israeli spotted fever Astrakhan spotted fever R. rickettsii Rocky mountain spotted fever R. Afircae African tick-bite fever (A similar disease is caused by R. parker in US and A.trisite in South America) R. japonica Japanese spotted fever (oriental spotted fever) (similar diseae in North Asia is caused by R. sibirica and R. heilongjiangesis) R. honei Flinders Island spotted fever R. australis Queensland tick typhus","pyqMatches":[{"year":"2013","no":756,"q":"Boutonneuse fever is caused by","o":["Rickettsia japonica","Rickettsia conorii","Rickettsia sibirica","Rickettsia australis"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3333, 'Microbiology', 'Clinical Microbiology', 'Easy', 'Microbiology', 77, '{"id":3333,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":77,"q":"Which of the following has only 1 serotype -","o":["C psittaci","C pneumoniae","C trachomatis","None"],"a":1,"e":"Ans. is ''b'' i.e., C pneumoniae There are many serovars of chlamydiae : C. trachomatis TRIC —p. 12 serotypes } Total 15 C. trachomatis LGV 3 serotypes C. psittaci — Many serotyes C. pneumoniae —10. Only one serotype","pyqMatches":[{"year":"2013","no":754,"q":"Which of the following has only 1 serotype","o":["C psittaci","C pneumoniae","C trachomatis","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3334, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 78, '{"id":3334,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":78,"q":"Which of the following is called as Preisz- Nocard bacillus -","o":["C. diphtheriae","C. pseudotuberculosis","M. tuberculosis","Mycoplasma"],"a":1,"e":"Ans. is ''b'' i.e., C. pseudotuberculosis Bacteria and their alternate names Bordetella Clostridium tetani Corynebacterium diphtheriae Corynebacterium pseudotuberculosis Haemophilus aegyptius Haemophilus influenzae Klebsiella pneumoniae Klebsiella ozaenae Klebsiella Rhinoscleromatis Mycobacterium tuberculosis Mycobacterium intracellulare Mycobacterium paratuberculosis Mycoplasma Pseudomonas pseudomallei Bordet Gengou bacillus Nicolaire''s bacillus Klebs-Loeffler ''s bacillus Preisz-Nocard bacillus Koch-Weeks bacillus Pfeiffer ''s bacillus Friedlander''s bacillus Abel''s bacillus Frisch ''s bacillus Koch''s bacillus Battey''s bacillus Johne''s bacillus Eaton agent Whitmore''s bacillus","pyqMatches":[{"year":"2013","no":736,"q":"Which of the following is called as Preisz-Nocard bacillus","o":["C. diphtheriae","C. pseudotuberculosis","M. tuberculosis","Mycoplasma"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3335, 'Microbiology', 'Bacteriology', 'Moderate', 'Microbiology', 79, '{"id":3335,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Moderate","source":"Microbiology","sourceNo":79,"q":"All cause fournier gangrene except-","o":["Staphylococcus","Streptococcus","Clostridium","Bacteroides"],"a":2,"e":"Ans. is ''c'' i.e., Clostridium Fournier''s gangrene is a necrotising fascitis of genitalia, usually affecting the scrotum and penis. There have been many types of bacteriological culture encountered in Fournier''s gangrene, both single strain and polymicrobial culture. Majority of cases are due to mixed infection caused by both aerobic and anaerobic bacteria. Following are common causative organisms : Staphylococcus aureus, streptococcus pyogenes ((3-hemolytic streptococci), enterobacteriaceae (E. coli, klebsiella, proteus), enterococci, pseudomonas, and anaerobes like bacteroides and peptostreptococcus.","pyqMatches":[{"year":"2012","no":698,"q":"All cause fournier gangrene except","o":["Staphylococcus","Streptococcus","Clostridium","Bacteroides"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3336, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 80, '{"id":3336,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":80,"q":"Necrotizing fascitis is caused by -","o":["Staphylococcus aureus","Beta hemolytic streptococci","Clostridium perfringens","Pneumococcus"],"a":1,"e":"Ans. is ''b'' i.e., Beta hemolytic streptococci The spectrum of infections of the deep soft tissues ranges from localized bacterial, viral and parasitic lesions to rapidly spreading, tissue destructive infections such as necrotizing fascitis and myonecrosis. A) Pyomyositis :- It is common in tropics, therefore also called tropical pyomyositis. It is a localized infection of skeletal muscles. It is caused most commonly by staphylococcus aureus. B) Necrotizing fascitis Necrotizing fascitis is an infection of the deeper layers of skin and subcutaneous tissues, easily spreading across the fascial plane within the subcutaneous tissues. There are two types of necrotizing fascitis :? i) Type 1:- It is a polymicrobial infection, i.e. mixed aerobic and anaerobic infection. It occurs most commonly after surgical procedures in diabetic patients or in those who have peripheral vascular disease. ii) Type 2 :- It is caused most commonly by streptococcus pyogenes (Group A beta hemolytic streptococci). C) Clostridial myonecrosis (Gas gangrene) :- It is characterized by rapid and extensive necrosis of muscle accompanied by gas formation and systemic toxicity. It is caused by C. perfringens (most common), C. novyi, C. septicum and C. histolyticum. It is also called type III necrotizing fascitis.","pyqMatches":[{"year":"2012","no":673,"q":"Necrotizing fascitis is caused by","o":["Staphylococcus aureus","Beta hemolytic streptococci","Clostridium perfringens","Pneumococcus"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3337, 'Microbiology', 'Bacteriology', 'Moderate', 'Microbiology', 81, '{"id":3337,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Moderate","source":"Microbiology","sourceNo":81,"q":"Which of the following organisms does not enters through abrasions in the skin -","o":["E rhusiopathiae","E corrodens","C hominis","C violaceum"],"a":2,"e":"Ans. is ''c'' i.e., C. hominis Bacteria circulate and multiply in blood ---> Septicemia . Bacteria circulate in blood --> Bacteremia . Toxins circulate in blood --> Toxemia . Pus in blood —> Pyemia Eikenella corrodens (E. corrodens), chromobacterium violaceum (C. violaceum) and Eikenella corrodens (E. corrodens) enters the body through skin abrasions. A wide variety of microorganisms that reside on the skin and mucous membranes of the body, as well as those found in the environment, can cause skin and soft tissue infections. These organisms enter the body through breaks in the skin or mucous membranes, through wounds made by trauma or bites or as a complication of surgery or foreign-body implantation. These organisms have been mentioned in following table : Aerobic and facultative microorganisms Anaerobic bacteria Aerobic microorganisms from unusual, Vspecialized and zoonotic infections Yeast • Coagulase • Actinobacillus • Cand negative Peptostreptococcus• albicans staphylococcispp. actinomycetemcomitans• Cand krusei • Staphylococcus aureus • Clostridium spp. •Aeromonas spp. • Cand parapsil • Enterococcus spp. • Eubacterium limosum •Bacillus anthracis • Streptococcus viridans • Bacteroides fragilis • Bergeyella zoohelcum • Corynebacterium spp. • Prevotella spp. • Chromobacterium violaceum • Bacillus cereus • Porphyromonas •Eikenella corrodens • E. coli • Fusobacterium •Erysipalothrix • Serratia • Veillonella spp. rhusiopathiae • Enterobactor •Francisella tularensis • Proteus •Haemophillus spp. • Morganella •Kingella kingae • Pseudomonas •Pasteurella multocida • Acinetobactor •Streptobacillus moniliformis •Vibrio vulnificus","pyqMatches":[{"year":"2012","no":764,"q":"Which of the following organisms does not enters through abrasions in the skin","o":["E rhusiopathiae","E corrodens","C hominis","C violaceum"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3338, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 82, '{"id":3338,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":82,"q":"Darting motility which occur in V.cholerae, also found in -","o":["Shigella","Campylobacter jejuni","Pneumococcus","Bacillus anthrax"],"a":1,"e":"Ans. is ''b'' i.e., Campylobacter jejuni Darting (shooting star) motility is seen in V. Cholerae Gardnerella vaginalis Campylobactor","pyqMatches":[{"year":"2013","no":737,"q":"Darting motility which occur in V.cholerae, also found in","o":["Shigella","Campylobacter jejuni","Pneumococcus","Bacillus anthrax"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":876,"q":"Darting motility which occur in V.cholerae, also found in","o":["Shigella","Campylobacter jejuni","Pneumococcus","Bacillus anthrax"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3339, 'Microbiology', 'Miscellaneous', 'Moderate', 'Microbiology', 83, '{"id":3339,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Microbiology","sourceNo":83,"q":"All are true about cutaneous anthrax except ?","o":["Extremely painful","The whole area is congested and edematous","Central crustation with black eschar","Satellite nodule around inguinal region"],"a":0,"e":"Ans. is ''a'' i.e., Extremely painful Cutaneous anthrax is painless.","pyqMatches":[{"year":"2016","no":702,"q":"All are true about cutaneous anthrax except ?","o":["Extremely painful","The whole area is congested and edematous","Central crustation with black eschar","Satellite nodule around inguinal region"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3340, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 84, '{"id":3340,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":84,"q":"True about vibrio cholerae is -","o":["Disease more common in woman","Classical vibrio protect against development of 0-139 Tor is milder than classical","El - Tor is milder than classical","All"],"a":2,"e":"El - Tor is milder than classical","pyqMatches":[{"year":"2016","no":727,"q":"True about vibrio cholerae is","o":["Disease more common in woman","Classical vibrio protect against development of 0-139 Tor is milder than classical","El - Tor is milder than classical","All"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3341, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 85, '{"id":3341,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":85,"q":"Appearance of cowdry type A inclusion bodies?","o":["Granular","Circumscribed","In polio","None"],"a":0,"e":"Ans. is ''a'' i.e., Granular Intranuclear inclusion bodies were classified into two types by cowdry : a) Cowdry type A :- These are of variable size and granular in appearance, e.g. in herpesvirus and yellow fever virus. b) Cowdry type B :- These are more circumscribed and often multiple, as with adenovirus and poliovirus.","pyqMatches":[{"year":"2012","no":733,"q":"Appearance of cowdry type A inclusion bodies?","o":["Granular","Circumscribed","In polio","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3342, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 86, '{"id":3342,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":86,"q":"Which is enveloped virus -","o":["Dengue virus","Norwalk virus","Hep A virus","Adenovirus"],"a":0,"e":"Ans. is ''a'' i.e., Dengue virus Dengue virus (a member of flavivirodae) is an enveloped virus. Adenovirus, norwalk virus (calciviridae) and hepatitis A virus (Picornaviridae) are non-enveloped viruses.","pyqMatches":[{"year":"2012","no":723,"q":"Which is enveloped virus","o":["Dengue virus","Norwalk virus","Hep A virus","Adenovirus"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3343, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 87, '{"id":3343,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":87,"q":"Smallest DNA virus is?","o":["Herpes virus","Adenovirus","Parvovirus","Poxvirus"],"a":2,"e":"Ans. is ''c'' i.e. Parvovirus Smallest virus (also smallest DNA virus) → Parvovirus. Largest virus (also largest DNA virus) → Pox virus. Smallest RNA virus → Picornavirus Largest RNA virus → Paramyxoviridae.","pyqMatches":[{"year":"2016","no":741,"q":"Smallest DNA virus is?","o":["Herpes virus","Adenovirus","Parvovirus","Poxvirus"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3344, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 88, '{"id":3344,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":88,"q":"Which of the following is primary cell line ?","o":["Chick embryo fibroblast","Hela cells","Vero cells","WI-38"],"a":0,"e":"Ans. is ''a'' i.e., Chick embryo fibroblast Chick embryo fibroblast is primary cell culture.","pyqMatches":[{"year":"2012","no":721,"q":"Which of the following is primary cell line ?","o":["Chick embryo fibroblast","Hela cells","Vero cells","WI-38"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3345, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 89, '{"id":3345,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":89,"q":"Influenza virus culture is done on ?","o":["Chorioallantoic membrane","Allantoic cavity","Yolk sac","All"],"a":1,"e":"Ans. is b i.e., Allantoic cavity In embryonated egg cultivation for influenza virus site of inoculation are :- Allontoic cavity or amniotic cavity Inoculation sites in embryonated eggs Chorioallantoic membrane -4 HSV, Poxvirus, Rous-sarcoma virus Amniotic cavity -4 Influenza virus, mumps virus Allantoic cavity - Influenza virus, mumps virus, avian adenovirus, newcastle disease virus Yolk sac --> HSV, chlamydia, rickettisia","pyqMatches":[{"year":"2012","no":740,"q":"Influenza virus culture is done on ?","o":["Chorioallantoic membrane","Allantoic cavity","Yolk sac","All"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3346, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 90, '{"id":3346,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":90,"q":"Virus quantification is done by-","o":["Egg inoculation","Hemadsorption","Plaque assay","Electron microscopy"],"a":2,"e":"Ans. is ''c'' i.e., Plaque assay Plaque assay and Pock assay are quantitative infective assays.","pyqMatches":[{"year":"2012","no":722,"q":"Virus quantification is done by","o":["Egg inoculation","Hemadsorption","Plaque assay","Electron microscopy"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3347, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 91, '{"id":3347,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":91,"q":"Von Magnus phenomenon -","o":["Is a normal replicative cycle","Virus yield has low hemagglutination","Virus has high infectivity","Virus yields has high hemagglutination titre but low infectivity"],"a":3,"e":"Ans. is ''d'' i.e. virus yields has high hemagglutination titre but low infectivity Abnormal replicative cycles of viruses . Von magnus phenomenon when cells are infected with a high dose of influenza virus, there is defective assembly during replication and the produced virus has high hemagglutinin titre but low infectivity. . Abortive infection Due to defective maturation or assembly, either no release of virons occur or the progeny of virus is noninfectious. . Defective viruses Some viruses are genetically defective and require help of simultaneously infected helper virus for replication. eg. HDV, Rous sarcoma virus.","pyqMatches":[{"year":"2015","no":766,"q":"Von Magnus phenomenon","o":["Is a normal replicative cycle","Virus yield has low hemagglutination","Virus has high infectivity","Virus yields has high hemagglutination titre but low infectivity"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3348, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 92, '{"id":3348,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":92,"q":"Lysis of bacterial colony in culture is seen by which virus -","o":["Pox","HSV","Bacteriophage","CMV"],"a":2,"e":"Ans. is ''c'' i.e., Bacteriophage Lysis of bacteria occurs due to replication of bacteriophage in the bacteria, in lytic cycle. The process of lytic cycle occurs in following steps :? 1) Adsorption (attachment) of a phage to the surface of a susceptible bacterium by its tail. 2) Penetration of phage nucleic acid into the bacterial cells. 3) Synthesis of phage components. 4) Assembly of phage components into mature infective phage particles, i.e. maturation. 5) Release of mature progeny phage.","pyqMatches":[{"year":"2013","no":805,"q":"Lysis of bacterial colony in culture is seen by which virus","o":["Pox","HSV","Bacteriophage","CMV"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3349, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 93, '{"id":3349,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":93,"q":"Phage typing can be done for -","o":["Salmonella","Streptococcus","Shigella","Pseudomonas"],"a":0,"e":"Ans. is ''a'' i.e., Salmonella Phage typing is a method used for detecting single strains of bacteria. It is used to trace the source of outbreaks of infections. The viruses that infect bacteria are called bacteriophages (\"phages\" for short) and some of these can only infect a single strain of bacteria. Phage typing provides a rapid, accurate, and cheap method of investigating Salmonella strains for epidemiological use. Salmonella strains within a particular serovar may be differentiated into a number of phage types by their pattern of susceptibility to lysis by a set of phages with different specificity. Phase typing is done for","pyqMatches":[{"year":"2013","no":734,"q":"Phage typing can be done for","o":["Salmonella","Streptococcus","Shigella","Pseudomonas"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3350, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 94, '{"id":3350,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":94,"q":"Small pox belongs to which class of poxviruses ?","o":["Parapoxvirus","Capripoxvirus","Leporipox virus","Orthopoxvirus"],"a":3,"e":"Ans. is ''d'' i.e., Orthopoxvirus i) Entomopoxvirinae : Poxviruses of insects which do not infect vertebrates. Chordopoxvirinae are classified into six genera or subgroups - i) Orthopoxvirus : These are mammalian poxviruses that tend to cause generalized infection with rash. Exmples are variola (smallpox virus), vaccinia, cowpox, monnkeypox, rabbitpox, buffalopox, camelpox, mousepox. ii) Parapoxvirus : Viruses of ungulates that may occasionally infact human, eg. Orf (contagious pustular dermatitis) and paravaccinia (milker''s node, bovine pupular stomatitis). iii) Copripoxvirus : Viruses of goat and sheeps, eg. sheep-pox, goatpox, lumpy skin disease. iv) Leporipox virus : Viruses of of leporids (rabbits, hares, squirrels), e.g. myxoma and fibromas. v) Avipoxvirus : Virus of birds, eg. fowlpox, turkeypox, pigeonpox, canarypox. vi) Suipoxvirus : Virus of swine, eg. swinepox.","pyqMatches":[{"year":"2012","no":734,"q":"Small pox belongs to which class of poxviruses ?","o":["Parapoxvirus","Capripoxvirus","Leporipox virus","Orthopoxvirus"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3351, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 95, '{"id":3351,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":95,"q":"Following virus is of pox virus -","o":["Variola","Coxsachie","ECHO","HSV"],"a":0,"e":"Ans. is ''a'' i.e., Variola","pyqMatches":[{"year":"2012","no":729,"q":"Following virus is of pox virus","o":["Variola","Coxsachie","ECHO","HSV"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3352, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 96, '{"id":3352,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":96,"q":"Brick-shaped virus -","o":["Chicken pox","Small pox","CMV","EBV"],"a":1,"e":"Ans. is ''b'' i.e., Small pox Variola virus Belongs to Poxviruses enveloped DNA (ds DNA) virus. Brick shaped In stained preparation elementary bodies are seen —) Paschen bodies. The variola virus is the causative agent of small pox. On 8th may 1980 who anounced global eradication of small pox. Vaccinia virus It is similar to variola virus in properties. It is an artificial virus and does not occur in nature as such. Vaccinia virus is being employed as a vector for the development of recombinant vaccines. Vaccinia genome can accomodate about 25000 foreign base pairs, sufficient for introducing several genes. Many genes have been inserted eg - HB V, HIV, rabies and for pharmacologically important products such as neuropeptides. However it is not suitable as a vector for human use due to its pathogenic effects.","pyqMatches":[{"year":"2012","no":735,"q":"Brick-shaped virus","o":["Chicken pox","Small pox","CMV","EBV"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3353, 'Microbiology', 'Virology', 'Hard', 'Microbiology', 97, '{"id":3353,"subject":"Microbiology","chapter":"Virology","difficulty":"Hard","source":"Microbiology","sourceNo":97,"q":"A patient with sore throat has a positive Paul Bunnell test. The causative organism is-","o":["EBV","Adenovirus","CMV","Herpesvirus"],"a":0,"e":"Ans. is ''a'' i.e., EBV . EBV associated malignancies - Burkitt''s lymphoma0 - Nasopharynageal carcinoma - Hodgkin''s disease (mixed cellularity type) - Tonsillar Carcinoma - T Cell lymphoma - Thymoma - Gastric carcinoma - CNS lymphoma in AIDS and - Angiocentric nasal NK/T cell immunoproliferative lesions transplant recipient - Angioimmuno- blastic lymphadenopathy - Leiomyosarcoma Other associated nonmalignant conditions -Oral hairy leukoplakia in AIDS patients - Chronic fatigue syndrome - X-linked lymphoproli ferative syndrome (Duncan''s disease) Laboratory diagnosis","pyqMatches":[{"year":"2012","no":744,"q":"A patient with sore throat has a positive Paul Bunnell test. The causative organism is","o":["EBV","Adenovirus","CMV","Herpesvirus"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3354, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 98, '{"id":3354,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":98,"q":"Coxsackie virus is -","o":["Harpes virus","Pox virus","Enterovirus","Myxovirus"],"a":2,"e":"Ans. is ''c'' i.e., Enterovirus","pyqMatches":[{"year":"2012","no":724,"q":"Coxsackie virus is","o":["Harpes virus","Pox virus","Enterovirus","Myxovirus"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3355, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 99, '{"id":3355,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":99,"q":"Influenza virus has -","o":["5 segments of SS RNA","8 Segments of ds DNA","8 segments of ssDNA","8 segments of ssRNA"],"a":3,"e":"Ans. is ''d'' i.e., 8 segments of ssRNA INFLUENZA VIRUS Belong to orthomyxoviridae —. Envelope, RNA virus Contain single stranded RNA which is segmented —4. 8 pieces There are three viral subtypes","pyqMatches":[{"year":"2013","no":804,"q":"Influenza virus has","o":["5 segments of SS RNA","8 Segments of ds DNA","8 segments of ssDNA","8 segments of ssRNA"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3356, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 100, '{"id":3356,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":100,"q":"Hemorrhagic fever is caused by -","o":["West-Mile fever","Sandfly fever","Ebola virus","All of the above"],"a":2,"e":"Ans. is ''c'' i.e., Ebola virus Ebola virus belongs to hemorrhagic fever (see above explanation).","pyqMatches":[{"year":"2012","no":739,"q":"Hemorrhagic fever is caused by","o":["West-Mile fever","Sandfly fever","Ebola virus","All of the above"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3357, 'Microbiology', 'Virology', 'Moderate', 'Microbiology', 101, '{"id":3357,"subject":"Microbiology","chapter":"Virology","difficulty":"Moderate","source":"Microbiology","sourceNo":101,"q":"Which of the following is not common in India ?","o":["Japanese B encephalitis","Lassa fever","KFD","Dengue"],"a":1,"e":"Ans. is ''b'' i.e., Lassa fever SomeArboviruses known to be prevalent in India","pyqMatches":[{"year":"2013","no":769,"q":"Which of the following is not common in India ?","o":["Japanese B encephalitis","Lassa fever","KFD","Dengue"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3358, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 102, '{"id":3358,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":102,"q":"Amplifier host is -","o":["Pig in JE","Dog in rabies","Man in JE","Cattle in JE"],"a":0,"e":"Ans. is ''a'' i.e., Pig JE","pyqMatches":[{"year":"2012","no":730,"q":"Amplifier host is","o":["Pig in JE","Dog in rabies","Man in JE","Cattle in JE"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3359, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 103, '{"id":3359,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":103,"q":"True about hepatitis A viurs ?","o":["Causes cirrhosis","Helps HDV replication","Common cause of hepatitis in children","Causes chronic hepatitis"],"a":2,"e":"Ans. is ''c'' i.e., Common cause of hepatitis in children HAV is the most common cause of hepatitis in children. HAV does not cause chronic hepatitis or cirrhosis. HBV (no HAV) helps in HDV replication.","pyqMatches":[{"year":"2013","no":802,"q":"True about hepatitis A viurs ?","o":["Causes cirrhosis","Helps HDV replication","Common cause of hepatitis in children","Causes chronic hepatitis"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3360, 'Microbiology', 'Virology', 'Hard', 'Microbiology', 104, '{"id":3360,"subject":"Microbiology","chapter":"Virology","difficulty":"Hard","source":"Microbiology","sourceNo":104,"q":"Serological testing of patient shows HBsAg, IgM anti-HBc and HBeAg postive. The patient hase -","o":["Chronic hepatitis B with low infectivity","Acute hepatitis B with high infectivity","Chronic hepatitis with high infectivity","Acute on chronic hepatitis"],"a":1,"e":"Ans. is `b'' i.e., Acute hepatitis B with high infectivity","pyqMatches":[{"year":"2012","no":725,"q":"Serological testing of patient shows HBsAg, IgM anti-HBc and HBeAg postive. The patient hase","o":["Chronic hepatitis B with low infectivity","Acute hepatitis B with high infectivity","Chronic hepatitis with high infectivity","Acute on chronic hepatitis"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3361, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 105, '{"id":3361,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":105,"q":"Nef gene in HIV is for use -","o":["Enhancing the expression of genes","Enhancing viral replication","Decreasing viral replication","Maturation"],"a":2,"e":"Ans. is ''c'' i.e., Decreasing viral replication Nonstructural HIV genes o These are ? 1) Tat (Trans-activating gene) : Enhancing the expression of all viral genes. 2) Nef (Negative factor gene) : Down-regulating viral replication. 3) Rev (Regulator of viral gene) : Enhancing expression of structural proteins. 4) Vif (Viral infectivity factor gene) : Influencing infectivity of viral particles. 5) Vpu (In HIV-1) and vpx (In HIV-2) : Enhance maturation and release of progeny of virus from cells. 6) Vpr : Stimulates promotor region. 7) LTR (Long terminal repeat) sequence : Contains sequences which give promotor, enhancer and integration signals.","pyqMatches":[{"year":"2012","no":737,"q":"Nef gene in HIV is for use","o":["Enhancing the expression of genes","Enhancing viral replication","Decreasing viral replication","Maturation"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3362, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 106, '{"id":3362,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":106,"q":"The chance that a health worker gets HIV from an accidental needle prick is -","o":["1%","10%","95%","100%"],"a":0,"e":"Ans. is ''a'' i.e., 1% Common modes of transmission of HIV and their relative risk Types of exposure Approximate chance of infection per exposure Sexual intercourse : 0.1-1.0% anal, vaginal, oral II Blood and blood products, Factor VII > 90% etc. Blood transfusion III Tissue and organ 50-90% donation, semen, cornea, bone marrow, kidney etc. IV Injections and 0.5-1.0% injuries; shared needles by drug addicts Injections with unsterile Needle-stick and other injuries in health staff? Surgical wounds g V Mother to baby : 30% Transplacental At birth After birth Breast milk","pyqMatches":[{"year":"2014","no":824,"q":"The chance that a health worker gets HIV from an accidental needle prick is","o":["1%","10%","95%","100%"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3363, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 107, '{"id":3363,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":107,"q":"False about p24 is","o":["Seen after 3 weeks of infection","Cant be seen in first week","Cant be detected after seroconversion","a and c"],"a":3,"e":"Ans. is ''a > c'' i.e., Seen after 3 weeks of infection > Cant be detected after seroconversion Antigen detection in HIV Following a single massive infection, as by blood transfusion, the virus antigens may be detectable in blood after about two weeks. The major core antigen, p24 is the earliest virus marker to appear in the blood and is the one tested for. IgM antibodies appear in about 4-6 weeks, to be following by IgG antibodies. If the infecting dose is small, as following a needle-stick injury, the process may be considerably delayed. The appearance of p24 antigenemia and viremia, followed by IgM antibody response, coincides with acute or seroconversion illness. Afterwards, free p24 antigen disappears from circulation and remains absent during the long asymptomatic phase, to reappear only when severe clinical disease sets in. However antibody-bound p24 antigen continues to be demonstrable, after dissociation. The p24 antigen capture assay (ELISA) which uses anti-p24 antibody as the solid phase can be used for this. The test is positive in about 30% of HIV infected persons. With prior dissociation of antigen-antibody complex, the positivity rate increases to about 50%. The test is most useful in persons recently exposed to risk of infection, in whom the antibody test is negative. Now coming to the question Option b & d are straight-forward. p24 antigen is detected by ELISA (enzyme immuno-assay or enzyme linked immuno-assay) and is not detectable in first week after the infection. Option ''a'' incorrect because though the p24 antigen can be detected after 2 weeks of infection :​\"The p24 antigen test can detect the p24 antigen on average 10-14 days after infection with HIV\". \"Following a single massive infection, the virus antigens may be detectable in blood after about two weeks\". Option ''c'' is partly correct and partly incorrect because :- i) Free p24 antigen is not detectable after seroconversion. However, in 30-50% of infected persons, antibody-bound p24 antigen can be detected after its dissociation from antibody.","pyqMatches":[{"year":"2012","no":731,"q":"False about p24 is","o":["Seen after 3 weeks of infection","Cant be seen in first week","Cant be detected after seroconversion","a and c"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3364, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 108, '{"id":3364,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":108,"q":"Which of the following is a protista-","o":["Algae","Fungi","Protozoa","Bacteria"],"a":2,"e":"Ans. is ''c'' i.e., Protozoa","pyqMatches":[{"year":"2012","no":664,"q":"Which of the following is a protista","o":["Algae","Fungi","Protozoa","Bacteria"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3365, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 109, '{"id":3365,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":109,"q":"True about trematodes","o":["Two host required","Segmented","Anus present","Body cavity present"],"a":0,"e":"Ans. is ''a'' i.e., Two host required Medically important member of the class trematoda belong to subclass Digenea, as they are digenetic, i.e. require two hosts. The definitive host in which they pass the sexual or adult stage are mammals, humans or animals, and the intermediate hosts in which they pass their asexual or larval stages are freshwater molluscs or snails. Trematodes are unsegmented, and have no anus and body cavity.","pyqMatches":[{"year":"2012","no":701,"q":"True about trematodes","o":["Two host required","Segmented","Anus present","Body cavity present"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3366, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 110, '{"id":3366,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":110,"q":"Operculated eggs are seen in -","o":["Nematodes","Cestodes","Trematodes","Protozoa"],"a":2,"e":"Ans. is ''c'' i.e., Trematodes Operculated eggs has a little cap like structure (operculum) at the end. The operculum pops open when the next stage is ready to emerge. The nematodes (flukes) lay operculated eggs. An exception is schistosome egg, which are not operculated.","pyqMatches":[{"year":"2013","no":776,"q":"Operculated eggs are seen in","o":["Nematodes","Cestodes","Trematodes","Protozoa"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3367, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 111, '{"id":3367,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":111,"q":"Amoebic liver abscess can be diagnosed by demonstrating-","o":["Cysts in the sterile pus","Trophozoites in the pus","Cysts in the intestine","Trophozoites in the feces"],"a":1,"e":"Ans. is ''b'' i.e., Trophozoites in the pus","pyqMatches":[{"year":"2013","no":713,"q":"Amoebic liver abscess can be diagnosed by demonstrating","o":["Cysts in the sterile pus","Trophozoites in the pus","Cysts in the intestine","Trophozoites in the feces"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3368, 'Microbiology', 'Parasitology', 'Easy', 'Microbiology', 112, '{"id":3368,"subject":"Microbiology","chapter":"Parasitology","difficulty":"Easy","source":"Microbiology","sourceNo":112,"q":"How many pairs of flagella does Giardia lamblia possess -","o":["One","Two","Three","Four"],"a":3,"e":"Ans. is ''d'' i.e., Four","pyqMatches":[{"year":"2013","no":779,"q":"How many pairs of flagella does Giardia lamblia possess","o":["One","Two","Three","Four"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3369, 'Microbiology', 'Clinical Microbiology', 'Hard', 'Microbiology', 113, '{"id":3369,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Hard","source":"Microbiology","sourceNo":113,"q":"A case of giardiasis presents with -","o":["Nausea and vomiting","Abdominal pain","Steatorrhea and flatulence","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above Giardiasis * Disease manifestations of giardiasis range from asymptomatic carriage to fulminant diarrhea and malabsorption. * Most infected persons are asymptomatic * The mechanisms by which Giardia causes alteration in small bowel function are largely unknown. Although trophozoites adhere to the epithelium, they do not cause invasive or locally destructive alterations. * In most cases the morphology of the bowel is unaltered but in few cases; in chronically infected symptomatic patients; the histopathologic finding (flattened villi) and the clinical manifestations resemble those of tropical sprue and gluten sensitive enteropathy. Incubation period - I to 3 weeks * Clinical manifestations * Diarrhea * Nausea * Abdominal pain * Vomiting * Bloating * Flatus * Extraintestinal - urticaria, anterior uveitis, arthritis. * Fever, the presence of blood or mucus in the stools suggest a different diagnosis as all these are absent in giardiasis.","pyqMatches":[{"year":"2013","no":780,"q":"A case of giardiasis presents with","o":["Nausea and vomiting","Abdominal pain","Steatorrhea and flatulence","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3370, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 114, '{"id":3370,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":114,"q":"Malarial parasite was discovered by-","o":["Ronald ross","Paul muller","Laveran","Pampania"],"a":2,"e":"Ans. is ''c'' i.e., Laveran . The specific causative agent of malaria was discovered in the red blood cells of a patient in 1880 by Alophonse Laveran, a French army surgeon in Algeria. Remember . Romanowsky developed a method of staining malaria parasites in blood films.","pyqMatches":[{"year":"2012","no":663,"q":"Malarial parasite was discovered by","o":["Ronald ross","Paul muller","Laveran","Pampania"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3371, 'Microbiology', 'Parasitology', 'Easy', 'Microbiology', 115, '{"id":3371,"subject":"Microbiology","chapter":"Parasitology","difficulty":"Easy","source":"Microbiology","sourceNo":115,"q":"In malaria, sexual cycle is -","o":["Sporozoite to gametocytes","Gametocytes to Sporozoite","Occurs in human","Responsible for relapse"],"a":1,"e":"Ans. is ''b'' i.e., Gametocytes to sporozoite LIFE CYCLE OF PLASMODIUM Plasmodium passes its life cycle in two different hosts ?","pyqMatches":[{"year":"2012","no":706,"q":"In malaria, sexual cycle is","o":["Sporozoite to gametocytes","Gametocytes to Sporozoite","Occurs in human","Responsible for relapse"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3372, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 116, '{"id":3372,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":116,"q":"In malaria, pre-erythrocytic schizogony occurs in -","o":["Lung","Liver","Spleen","Kidney"],"a":1,"e":"Ans. is ''b'' i.e., Liver","pyqMatches":[{"year":"2013","no":778,"q":"In malaria, pre-erythrocytic schizogony occurs in","o":["Lung","Liver","Spleen","Kidney"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3373, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 117, '{"id":3373,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":117,"q":"Which form of the malarial parasite is present in saliva of an infective mosquito -","o":["Ring form","Schizont","Gametocyte","Sporozoite"],"a":3,"e":"Ans. is ''d'' i.e., Sporozoite . Sporozoites are infective to man. Human infection begins when a female anopheline mosquito inoculates plasmodial sporozoites from its salivary gland during a blood meal.","pyqMatches":[{"year":"2013","no":777,"q":"Which form of the malarial parasite is present in saliva of an infective mosquito","o":["Ring form","Schizont","Gametocyte","Sporozoite"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3374, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 118, '{"id":3374,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":118,"q":"Which type of malaria is associated with renal failure -","o":["Falciparum","Vivax","Malariae","Ovale"],"a":0,"e":"Ans. is ''a'' i.e., Falciparum Nephrotic syndrome —> quarta malaria (P. malariae) Acute tubular necrosis (renal failure) malignant tertian malaria or pernicious malaria (caused by P falciparum).","pyqMatches":[{"year":"2012","no":707,"q":"Which type of malaria is associated with renal failure","o":["Falciparum","Vivax","Malariae","Ovale"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3375, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 119, '{"id":3375,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":119,"q":"Malaria causing nephrotic syndrome -","o":["P. vivax","P. falciparum","P. malariae","P. ovale"],"a":2,"e":"Ans. is ''c'' i.e., P-malariae Nephrotic syndrome is seen in Quartan malarial nephropathy, caused by repeated or chronic infection with P. malariae.","pyqMatches":[{"year":"2012","no":708,"q":"Malaria causing nephrotic syndrome","o":["P. vivax","P. falciparum","P. malariae","P. ovale"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3376, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 120, '{"id":3376,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":120,"q":"JSB stain is used for which parasite ?","o":["Malaria","Filaria","Kala azar","Sleeping sickness"],"a":0,"e":"Ans. is ''a'' i.e., Malaria JSB (Jaswant-Singh-Bhattacherji) stain is a fairly rapid staining method for the detection of malarial parasites. This stain is superior to the field''s stain because the parasites stain clearer and both thick and thin smears can be stained. However, preparations fade quite rapidly and this stain is, therefore, not recommended when permanent slides are desired. Stains used for staining malarial smears A number of Romanowsky stains are used for example Field''s, Giemsa''s, Wright''s and Leishman''s. For thick smear, the stains used are : (i) Field''s or (ii) Giemsa''s. For thin smear, the stains used are (i) Giemsa''s or (ii) Leishman''s. JSB stain is used for both thick and thin smears, and is the standard method used by laboratories under the National Malaria Eradication Programme in India.","pyqMatches":[{"year":"2013","no":763,"q":"JSB stain is used for which parasite ?","o":["Malaria","Filaria","Kala azar","Sleeping sickness"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3377, 'Microbiology', 'Parasitology', 'Easy', 'Microbiology', 121, '{"id":3377,"subject":"Microbiology","chapter":"Parasitology","difficulty":"Easy","source":"Microbiology","sourceNo":121,"q":"Cylindrical helminths are -","o":["Tapeworms","Flukes","Roundworms","Cestodes"],"a":2,"e":"Ans. is ''c'' i.e., Roundworms Helminths (metazoa) are divided into ?","pyqMatches":[{"year":"2013","no":770,"q":"Cylindrical helminths are","o":["Tapeworms","Flukes","Roundworms","Cestodes"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3378, 'Microbiology', 'Parasitology', 'Moderate', 'Microbiology', 122, '{"id":3378,"subject":"Microbiology","chapter":"Parasitology","difficulty":"Moderate","source":"Microbiology","sourceNo":122,"q":"Consumption of uncooked pork is likely to cause which of the following helminthic disease -","o":["Taenia saginata","Taenia solium","Trichuris trichiura","None of these"],"a":1,"e":"Ans. is ''b'' i.e., Taenia solium Humans acquire intestinal tapeworm infection by ingesting undercooked pork containing cysticerci. Mode of infection of tapeworms","pyqMatches":[{"year":"2013","no":771,"q":"Consumption of uncooked pork is likely to cause which of the following helminthic disease","o":["Taenia saginata","Taenia solium","Trichuris trichiura","None of these"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3379, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 123, '{"id":3379,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":123,"q":"Katayama fever is caused by -","o":["F. hepatica","C. sinensis","S. haematobium","A. lumbricoides"],"a":2,"e":"Ans. is ''c'' i.e., S. haematobium Katayama fever (Acute Schistosomiasis) occurs in about a month after infecion with S. japonicum and S. mansoni and rarely with S. haematobium.","pyqMatches":[{"year":"2012","no":665,"q":"Katayama fever is caused by","o":["F. hepatica","C. sinensis","S. haematobium","A. lumbricoides"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3380, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 124, '{"id":3380,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":124,"q":"Child having perianal pruritus with following eggs is due to -","o":["E. vermicularis","Ascaris","Ancylostoma duodenale","S stercoralis"],"a":0,"e":"Ans. is ''a'' i.e., E. vermicularis Clinical features of thread worm Infections * Most pinworm infections are asymptomatic. * Perianal pruritis is the cardinal symptom. The itching, is worse at night and disturbes sleep. * Heavy infections can cause abdominal pain and weight loss. * Nocturnal enuresis * Vulvovaginitis * Pelvic and peritoneal granulomas rare * Appendicitis * Salpingitis","pyqMatches":[{"year":"2013","no":774,"q":"Child having perianal pruritus with following eggs is due to","o":["E. vermicularis","Ascaris","Ancylostoma duodenale","S stercoralis"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3381, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 125, '{"id":3381,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":125,"q":"Wucheria bancrofti, true is -","o":["Unsheathed","Tail tip free from nuclei","Non-periodic","All"],"a":1,"e":"Ans. is ''b'' i.e., Tail tip free from nuclei W. bancrofti is sheathed and periodic with tail tip free from nuclei.","pyqMatches":[{"year":"2012","no":711,"q":"Wucheria bancrofti, true is","o":["Unsheathed","Tail tip free from nuclei","Non-periodic","All"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3382, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 126, '{"id":3382,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":126,"q":"Calabar swelling is produced by?","o":["Onchocerca volvulus","Loa loa","Burgia malayi","Wuchereria bancrofti"],"a":1,"e":"Ans. is ''b'' i.e., Loa - Loa Loiasis Loiasis is caused by L. Loa (the African eye worm) Habitat of adult worms is subcutaneous connective tissue of man; often in the sub-conjuctival tissue of the eye. The worm passes its life cycle in two hosts : 1) Man & 2) Chrysops (Mango or deer flies) C/Fs → Asymptomatic microfilaremia, Calabar (fugitive) swelling - subcutaneous swelling, Nephropathy, Encephalopathy (rare), Cardiomyopathy Calabar swelling is due to hypersensitivity reaction to the adult worm.","pyqMatches":[{"year":"2016","no":734,"q":"Calabar swelling is produced by?","o":["Onchocerca volvulus","Loa loa","Burgia malayi","Wuchereria bancrofti"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3383, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 127, '{"id":3383,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":127,"q":"River blindness is caused by -","o":["Onchocerca","Loa loa","Ascaris","B. malayi"],"a":0,"e":"Ans. is ''a'' i.e., Onchocerca Onchocerciasis is also known as River blindness and Robles disease.","pyqMatches":[{"year":"2015","no":771,"q":"River blindness is caused by","o":["Onchocerca","Loa loa","Ascaris","B. malayi"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3384, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 128, '{"id":3384,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":128,"q":"Cutaneous larva migrans is due to ?","o":["Ankylostoma braziliensis","W.bancrofti","B. Malayi","D. medinensis"],"a":0,"e":"Ans. is ''a'' i.e., Ankylostoma braziliense Larva migrans . Certain nematode larvae on entering into unnatural host (e.g. man) may not be able to complete their journey through the host''s tissues for localization in their normal abode. . Two different types of conditions are produced.","pyqMatches":[{"year":"2013","no":784,"q":"Cutaneous larva migrans is due to ?","o":["Ankylostoma braziliensis","W.bancrofti","B. Malayi","D. medinensis"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3385, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 129, '{"id":3385,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":129,"q":"Schistosomiasis is transmitted by ?","o":["Cyclops","Fish","Snaile","Cattle"],"a":2,"e":"Ans. is ''c'' i.e., Snails Intermediate host for schistosoma sp. is snail.","pyqMatches":[{"year":"2012","no":700,"q":"Schistosomiasis is transmitted by ?","o":["Cyclops","Fish","Snaile","Cattle"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3386, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 130, '{"id":3386,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":130,"q":"Cercariae are infective form of-","o":["S. hematobium","P. westermanii","F. hepatica","T. solium"],"a":0,"e":"Ans. is ''a'' i.e., S. hematobium Cercaria of Schistosoma hematobium is the infective form.","pyqMatches":[{"year":"2012","no":704,"q":"Cercariae are infective form of","o":["S. hematobium","P. westermanii","F. hepatica","T. solium"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3387, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 131, '{"id":3387,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":131,"q":"Which of the following is toxic to parasite -","o":["Peroxidase","Interferon","IL-2","IL-6"],"a":0,"e":"Ans. is ''a'' i.e., Peroxidase Neutrophils and monocytes contain a peroxidase (myeloperoxidase), that has been implicated in antiparasitic activity. However, monocytes lose this enzyme when they mature into macrophages. Eosinophils also contain peroxidase that differs from myeloperoxidase of neutrophils. However, like myeloperoxidase, eosinophil peroxidase combines with H20, and a halide to form an antiparasite system. Parasite Egg size 1) Fasciola gigantica 190 X 100 m 2) Echinostoma iliocanum 100 X 70 m 3) Gastrodiscoides hominis 150 X 70-100 m 4) Opisthorcis viverni <30 X 15 m","pyqMatches":[{"year":"2012","no":713,"q":"Which of the following is toxic to parasite","o":["Peroxidase","Interferon","IL-2","IL-6"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3388, 'Microbiology', 'Parasitology', 'Easy', 'Microbiology', 132, '{"id":3388,"subject":"Microbiology","chapter":"Parasitology","difficulty":"Easy","source":"Microbiology","sourceNo":132,"q":"Hanging drop method is used for-","o":["T. trichomonas","Plasmodium","Toxoplasma","Cryptosporidium"],"a":0,"e":"Ans. is ''a'' i.e., T. trichomonas Hanging drop method is used for examining motility of micro- organisms. Motility of trichomonas vaginalis may also be observed by this method.","pyqMatches":[{"year":"2012","no":709,"q":"Hanging drop method is used for","o":["T. trichomonas","Plasmodium","Toxoplasma","Cryptosporidium"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3389, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 133, '{"id":3389,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":133,"q":"Which of the following is true about malaria ?","o":["Gametocyte harbourers are carrier","All stage in erythrocytic schizogony seen in falciparum infection in peripheral blood","Schizonts of vivax do not completely fill the RBC","All the correct"],"a":0,"e":"Ans. is ''a'' i.e., Gametocyte harbourers are carrier * The individual who harbours the gametocytes is known as a carrier. * Only ring form (young trophozoites) and gametocytes are seen in peripheral blood. * Schizont of P. vivax almost completely fills an enlarged R.B.C.","pyqMatches":[{"year":"2013","no":712,"q":"Which of the following is true about malaria ?","o":["Gametocyte harbourers are carrier","All stage in erythrocytic schizogony seen in falciparum infection in peripheral blood","Schizonts of vivax do not completely fill the RBC","All the correct"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3390, 'Microbiology', 'Mycology', 'Easy', 'Microbiology', 134, '{"id":3390,"subject":"Microbiology","chapter":"Mycology","difficulty":"Easy","source":"Microbiology","sourceNo":134,"q":"Which of the following is only yeast ?","o":["Candida","Mucor","Rhizopus","Cryptococcus"],"a":3,"e":"Ans. is d i.e., Cryptococcus","pyqMatches":[{"year":"2012","no":715,"q":"Which of the following is only yeast ?","o":["Candida","Mucor","Rhizopus","Cryptococcus"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3391, 'Microbiology', 'Mycology', 'Easy', 'Microbiology', 135, '{"id":3391,"subject":"Microbiology","chapter":"Mycology","difficulty":"Easy","source":"Microbiology","sourceNo":135,"q":"The fungus with septate hyphae and dichotomous branching is -","o":["Aspergillus","Penicillium","Mucor","Rhizopus"],"a":0,"e":"Ans. is ''a'' i.e., Aspergillus Septate hyphae with dichotomous branching into two equal divisons at a regular angle of 45° are typical ofAspergillus. Mucor and rhizopus are non-septate (aseptate) and penicillium has no hyphae (It is yeast like fungus).","pyqMatches":[{"year":"2013","no":786,"q":"The fungus with septate hyphae and dichotomous branching is","o":["Aspergillus","Penicillium","Mucor","Rhizopus"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3392, 'Microbiology', 'Mycology', 'Easy', 'Microbiology', 136, '{"id":3392,"subject":"Microbiology","chapter":"Mycology","difficulty":"Easy","source":"Microbiology","sourceNo":136,"q":"Acute angled septate hyphae are seen in ?","o":["Aspergillus","Mucor","Penicillium","Candida"],"a":0,"e":"Ans. is ''a'' i.e., Aspergillus Septate hyphae with acute branching is characteristic of aspergillus.","pyqMatches":[{"year":"2013","no":787,"q":"Acute angled septate hyphae are seen in ?","o":["Aspergillus","Mucor","Penicillium","Candida"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3393, 'Microbiology', 'Mycology', 'Moderate', 'Microbiology', 137, '{"id":3393,"subject":"Microbiology","chapter":"Mycology","difficulty":"Moderate","source":"Microbiology","sourceNo":137,"q":"Aseptate hyphae is not seen in -","o":["Rhizopus","Mucor","Aspergillus","None"],"a":2,"e":"Ans. is ''c'' i.e., Aspergillus Non-septate (aseptate) hyphae --> Rhizopus, mucor. Septate hyphae —> Aspergillus.","pyqMatches":[{"year":"2012","no":720,"q":"Aseptate hyphae is not seen in","o":["Rhizopus","Mucor","Aspergillus","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3394, 'Microbiology', 'Mycology', 'Easy', 'Microbiology', 138, '{"id":3394,"subject":"Microbiology","chapter":"Mycology","difficulty":"Easy","source":"Microbiology","sourceNo":138,"q":"Which of the following is false regarding dimorphic fungi -","o":["Occurs in two growth forms","Can cause systemic infection","Cryptococcus is an example","Coccidioides is an example"],"a":2,"e":"Ans. is ''c'' i.e., Cryptococcus is an example Dimorphic fungi Fungi that have two growth forms, such as mold (filaments) and a yeast, which develop under different growth conditions. . In host tissues or cultures at 37°C they occur as yeasts, while in the soil and in cultures at 22\"C they appear as moulds. . Most fungi causing systemic infections are dimorphic fungi. Note - Candida albicans is a dimorphic fungus, while other species of candida are not dimorphic.","pyqMatches":[{"year":"2013","no":794,"q":"Which of the following is false regarding dimorphic fungi","o":["Occurs in two growth forms","Can cause systemic infection","Cryptococcus is an example","Coccidioides is an example"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3395, 'Microbiology', 'Mycology', 'Easy', 'Microbiology', 139, '{"id":3395,"subject":"Microbiology","chapter":"Mycology","difficulty":"Easy","source":"Microbiology","sourceNo":139,"q":"Trichophyton species which is zoophilic ?","o":["T. tonsurans","T. violaceum","T. schoenleinii","T. mentagrophytes"],"a":3,"e":"Ans. is ''d'' i.e. T. mentagrophytes Zoophilic dermatophytes are the species which primarily infect animals and occasionally transmitted to humans. Zoophilic species of trichophyton are T. montegrophytes and T verrucosum. Other zoophilic species of dermatophytes is M. canis.","pyqMatches":[{"year":"2012","no":719,"q":"Trichophyton species which is zoophilic ?","o":["T. tonsurans","T. violaceum","T. schoenleinii","T. mentagrophytes"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3396, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 140, '{"id":3396,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":140,"q":"Tinea cruris is caused by -","o":["Epidermophyton","Trichophyton","Microsporum","a and b"],"a":3,"e":"Ans. is ''a'' i.e., Epidermophyton; ''b'' i.e., Trichophyton","pyqMatches":[{"year":"2013","no":792,"q":"Tinea cruris is caused by","o":["Epidermophyton","Trichophyton","Microsporum","a and b"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3397, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 141, '{"id":3397,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":141,"q":"Hair perforation test is positive in infection with ?","o":["Trichophyton","Microsporum","Epidermophyton","All of the above"],"a":0,"e":"Ans. is ''a'' i.e., Trichophyton Hair perforation test . The hair perforation test consists of inoculating colonies of an organism into a dish containing a small amount of water, a few drops of yeast extract solution and some human hair. The dish is incubated at 300C and after 7 days, some of the hair are taken and are kept on a slide with a coverslip and are observed under a microscope. The test is considered positive if the hair has deep, narrow wedge shaped perforation in it. . Hair perforation test is done to distinguish between isolates of dermatophytes, particularly trichophyton mentagrophytes and its variants.","pyqMatches":[{"year":"2016","no":763,"q":"Hair perforation test is positive in infection with ?","o":["Trichophyton","Microsporum","Epidermophyton","All of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3398, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 142, '{"id":3398,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":142,"q":"Color of granules in mycetoma caused by Actinomadura pelletierrii -","o":["Black","Yellow","Red","Brown"],"a":2,"e":"Ans. is ''c'' i.e., Red Colout of Grains in Mycetomas of Various Etiology White to Yellow Brown to Black Red 1) Nocardia asteroides 1) Madurella mycetomi 1) Actinomadura pelletierrii 2) Nocardia brasilliensis 2) Madurella grisea 3) Actinomadura madurae 3) Phialophora jeanselmei 4) Streptomyces somaliensis 5) Allescheria boydii","pyqMatches":[{"year":"2013","no":789,"q":"Color of granules in mycetoma caused by Actinomadura pelletierrii","o":["Black","Yellow","Red","Brown"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3399, 'Microbiology', 'Mycology', 'Moderate', 'Microbiology', 143, '{"id":3399,"subject":"Microbiology","chapter":"Mycology","difficulty":"Moderate","source":"Microbiology","sourceNo":143,"q":"Aspergillus causes all except ?","o":["Bronchopulmonary allergy","Otomycosis","Dermatophytosis","Allergic sinusitis"],"a":2,"e":"Ans. is ''c'' i.e., Dermatophytosis","pyqMatches":[{"year":"2013","no":790,"q":"Aspergillus causes all except ?","o":["Bronchopulmonary allergy","Otomycosis","Dermatophytosis","Allergic sinusitis"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3400, 'Microbiology', 'Mycology', 'Easy', 'Microbiology', 144, '{"id":3400,"subject":"Microbiology","chapter":"Mycology","difficulty":"Easy","source":"Microbiology","sourceNo":144,"q":"Valley fever or desert rheumatism is caused by ?","o":["Sporothrix","Cladosporium","Phialophora","None"],"a":3,"e":"Ans. is ''None'' Ans. is ''None'' Coccidioidomycosis , commonly known as cocci, Valley fever, as well as California fever,desert rheumatism, and San Joaquin Valley fever, is a mammalian fungal disease caused by Coccidioides immitis or Coccidioides posadasii. The scientific name for Valley fever is “coccidioidomycosis,” and it''s also sometimes called “San Joaquin Valley fever” or “desert rheumatism.” The term “Valley fever” usually refers to Coccidioides infection in the lungs, but the infection can spread to other parts of the body in severe cases.","pyqMatches":[{"year":"2013","no":791,"q":"Valley fever or desert rheumatism is caused by ?","o":["Sporothrix","Cladosporium","Phialophora","None"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3401, 'Microbiology', 'Clinical Microbiology', 'Moderate', 'Microbiology', 145, '{"id":3401,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Moderate","source":"Microbiology","sourceNo":145,"q":"A plant prick can produce sporotrichosis. All are true statements about sporotrichosis except -","o":["Is a chronic mycotic disease that typically involves skin, subcutaneous tissue and regional lymphatics","Most cases are acquired via cutaneous inoculation","Enlarged lymph nodes extending centripetally as a beaded chain are a characteristic finding","It is an occupational disease of butchers, doctors"],"a":3,"e":"Ans. is ''d'' i.e., It is an occupational disease of butchers, doctors * Sporotrichosis is caused by the thermally dimorphic fungus sporothrix schenckii. * Because S.schenckii naturally found in soil, hay, sphagnum moss, and plants, it usually affects farmers, gardeners, and agricultural workers. * This fungal disease usually affects the skin although rare forms can affect the lungs, joints, bones and CNS. * Fungus enters through small cuts and abrasions in the skin to cause the infection. * Because roses can spread the disease, it is one of a few diseases referred to as rose-thorn or rose gardener''s disease. Forms and symptoms of sporotrichosis: 1) Cutaneous (skin) sporotrichosis * This is the most common form of this disease. * Symptoms of this form includes nodular lesions or bumps in the skin, at the point of entry and also along lymph nodes and vessels. * The lesion starts off as small and painless, nodule and ranges in The lesion starts off as small and painless, nodule and ranges in colour from pink to purple. * Left untreated, the lesion becomes larger and looks similar to a boil and more lesions will appear, until a chronic ulcer develops. * Usually cutaneous sporotrichosis lesions occurs in the finger, hand and arm. 2) Pulmonary sporotrichosis * This rare form of the disease occur when S.schenckii spores are inhaled. * Symptoms include productive cough, nodules, cavitations and fibrosis of lungs; and hilar lymph node enlargement. * Patients with this form of sporotrichosis are susceptible to developing tuberculosis and pneumonia. 3) Disseminated sporotrichosis * When the infection spreads from the primary site to secondary sites in the body, the disease develops into a rare and critical form called disseminated sporotrichosis. * The infection can spread to joints and bones (called osteoarticular sporotrichosis) as well as the CNS and brain (sporotrichosis meningitis).","pyqMatches":[{"year":"2013","no":795,"q":"A plant prick can produce sporotrichosis. All are true statements about sporotrichosis except","o":["Is a chronic mycotic disease that typically involves skin, subcutaneous tissue and regional lymphatics","Most cases are acquired via cutaneous inoculation","Enlarged lymph nodes extending centripetally as a beaded chain are a characteristic finding","It is an occupational disease of butchers, doctors"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3402, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 146, '{"id":3402,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":146,"q":"Which is false about penicillium marefi -","o":["Black colonies","Dimorphic fungi","Amphotericin B used for treatment","Causes fulminant infections in immuno​compromised patients"],"a":0,"e":"Ans. is ''a'' i.e., Black colonies Penicillium marneffei Penicillium morneffei cause serious disseminated disease with characteristic papular skin lesion in AIDS Patients in South-East Asia. The fungus is dimorphic, forming yeast-like cells that are often intracellular, resembling histoplasmosis, in infected tissues. The yeast phase (37°C) displays colonies that are white to tan, soft and dry. The most distinguishing characteristic of mould phase (at 25° C) is the early presence of red pigment that diffuses into agar. The colonies start as pinkish-yellow and evolve into a bluish-green color in the center with a white periphery. It is associated with bamboo rat (Rhizomys sinensis) and has been isolated from their burrows and internal organs. Treatment is amphotericin B, followed by intracoazole to prevent relapse.","pyqMatches":[{"year":"2013","no":788,"q":"Which is false about penicillium marefi","o":["Black colonies","Dimorphic fungi","Amphotericin B used for treatment","Causes fulminant infections in immuno​compromised patients"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3403, 'Microbiology', 'Mycology', 'Easy', 'Microbiology', 147, '{"id":3403,"subject":"Microbiology","chapter":"Mycology","difficulty":"Easy","source":"Microbiology","sourceNo":147,"q":"Neurotropic fungus is/are -","o":["Cryptococcus neoformans","Histoplasmosis","Trichophyton","a and b"],"a":3,"e":"Ans. is ''a'' i.e., Cryptococcus neoformans; ''b'' i.e., Histoplasmosis Fungi infecting the brain are Cryptococcus neoformans Blastomyces dermatitidis Coccidioides immitis Aspergillus sp. Candida sp. Sporothrix schenckii Histoplasma capsulatum","pyqMatches":[{"year":"2016","no":762,"q":"Neurotropic fungus is/are","o":["Cryptococcus neoformans","Histoplasmosis","Trichophyton","a and b"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3404, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 148, '{"id":3404,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":148,"q":"Pneumocystis carinii is diagnosed by -","o":["Sputum examination for trophozoites and cyst under microscope","Culture","Positive serology","Growth on artificial media"],"a":0,"e":"Ans. is ''a'' i.e., Sputum examination for trophozoites and cyst under microscope","pyqMatches":[{"year":"2016","no":769,"q":"Pneumocystis carinii is diagnosed by","o":["Sputum examination for trophozoites and cyst under microscope","Culture","Positive serology","Growth on artificial media"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3405, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 149, '{"id":3405,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":149,"q":"Bacteria showing antigenic variation ?","o":["Yersinia","Bordetella","Brucella","Borrelia"],"a":3,"e":"Ans. is ''d'' i.e., Borrelia Bacteria showing antigenic variation are :? i) Neisseria (Meningococci, Gonococci) ii) Streptococcus spp iii) Mycoplasma iv) Borrelia burgdorferi","pyqMatches":[{"year":"2013","no":835,"q":"Bacteria showing antigenic variation ?","o":["Yersinia","Bordetella","Brucella","Borrelia"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3406, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 150, '{"id":3406,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":150,"q":"Bioterroism group A agent","o":["Q fever","Typhus fever","Brucella","Antrax"],"a":3,"e":"Ans. is ''d'' i.e., Antrax","pyqMatches":[{"year":"2013","no":827,"q":"Bioterroism group A agent","o":["Q fever","Typhus fever","Brucella","Antrax"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3407, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 151, '{"id":3407,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":151,"q":"Which of the following belongs to category-B of bioterrorism -","o":["Cholera","Anthrox","Plague","Botulism"],"a":0,"e":"Ans. is ''a'' i.e., Cholera","pyqMatches":[{"year":"2013","no":828,"q":"Which of the following belongs to category-B of bioterrorism","o":["Cholera","Anthrox","Plague","Botulism"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3408, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 152, '{"id":3408,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":152,"q":"Most common mode of transmission of nosocomial infection is -","o":["Hand contact","Droplet infection","Blood and blood products","Contaminated water"],"a":0,"e":"Ans. is ''a'' i.e., Hand contact Modes of transmission of nosocomial infections There are following types of modes of transmission of hospital- acquired infections. 1) Contact transmission * It is the most common and most preventable means of transmission. It is divided into two types - .0 Direct contact : It involves contact of body surface to body surface with a physical transfer of microorganisms. Hand contact is most common mode of transmission. ii) Indirect contact : It involves body surface contact with a contaminated intermediate object. 2) Droplet transmission * It occurs when droplet containing microorganisms from an infected person are propelled through the air (e.g. coughing, sneezing) and land on the mouth, eyes or nose of another person. 3) Airborne transmission * It results when a droplet containing microorganisms evaporates and remains suspended in air for a long time (this should not be confused with droplet infection, in which transmission is immediate and droplets do not remains suspended in the air). * Airborne transmission also occurs by dust particles containing microorganism. 4) Vehicle transmission * It refers to transmission of infection by contaminated items such as food, water, medications, devices and equipment.","pyqMatches":[{"year":"2013","no":837,"q":"Most common mode of transmission of nosocomial infection is","o":["Hand contact","Droplet infection","Blood and blood products","Contaminated water"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3409, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 153, '{"id":3409,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":153,"q":"Most common organism involved in nosocomial infection -","o":["Staph aureus","E. coli","Legionella","Strep pneumonia"],"a":0,"e":"Ans. is ''a'' i.e., Staph aureus . UTI is the most common type of nosocomial infection. . Most common cause of UTI ---> E coli . Most common cause of UTI in ICU ----> Candida . Overall staph aureus is a leading cause of nosocomial infection. . Staph aureus is the most common cause of surgical wound infection - . Most common cause of primary bacteremia --> Coagulase negative staphylococcus.","pyqMatches":[{"year":"2015","no":703,"q":"Most common organism involved in nosocomial infection","o":["Staph aureus","E. coli","Legionella","Strep pneumonia"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3410, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 154, '{"id":3410,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":154,"q":"Most common organism causing ventilator associated pneumonia -","o":["Legionella","Pneumococcus","Pseudomonas","Coagulase negative staphylococcus"],"a":2,"e":"Ans. is ''c'' i.e., Pseudomonas Staphylococcus aureus and Pseudomonas aeruginosa cause most of the cases of ventilator associated pneumonia (VAP). Other common organisms causing VAP are enterococcus faecium, Acinetobacter baumonnii, enterobacter species and klebsiella pneumoniae. Mnemonic : ESKAPE (Enterococcus, staphylococcus, klebsiella, Acinetobacter, Pseudomonas, enterobacter). As single most common organism, pseudomonas is the causative agent ? - Pseudomonas aeruginosa —>21% - Staphylococcus aureus —>20% - Enterobacter species —>9% - Klebsiella pneumoniae —>8% - Acinetobacter —>6%","pyqMatches":[{"year":"2013","no":836,"q":"Most common organism causing ventilator associated pneumonia","o":["Legionella","Pneumococcus","Pseudomonas","Coagulase negative staphylococcus"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3411, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 155, '{"id":3411,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":155,"q":"In donovanosis-","o":["Pseudolymphadenopathy","Penicillin is used for treatment","Painful ulcer","Suppurative lymphadenopathy"],"a":0,"e":"Ans. is `a'' i.e., Pseudolymphadenopathy Donovanosis Caused by Calymmatobacterium granulomatis. C. granulomatis is ? Gram negative Encapsulated Nonmotile Intracellular It shares many morphologic and serologic characteristic (antigenic) and > 99% homology at the nucleotide level with Klebsiella. Clinical manifestations IP → 1-4 weeks Begins as one or more subcutaneous nodules that erode through skin to produce clean, granulomatous, sharply defined, usually painless lesions. The genitalia are involved in 90% of cases. Genital swelling, particularly of labia, is common. In donovanosis, heaped-up granulomatous tissue may follow and via subcutaneous extension to inguinal area may form \"pseudo- buboes\"; however, the absence of true lymphadenopathy is the hallmark of this infection. Complications Pseudoelephantiasis, phimosis and paraphimosis. Diagnosis: The preferred diagnostic method involves demonstration of typical intracellular Donovan bodies within large mononuclear cells visualized in smears prepared from lesions or biopsy specimens. Stain used is wright - Giemsa Treatment: Azithromycin (DOC) Doxycycline (2''d choice) Chloramphenicol","pyqMatches":[{"year":"2012","no":672,"q":"In donovanosis","o":["Pseudolymphadenopathy","Penicillin is used for treatment","Painful ulcer","Suppurative lymphadenopathy"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3412, 'Microbiology', 'Bacteriology', 'Hard', 'Microbiology', 156, '{"id":3412,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Hard","source":"Microbiology","sourceNo":156,"q":"An adolescent male developed vomiting and diarrhea 1 hour after having food from a restaurant. The most likely pathogen is?","o":["Clostridium perfringens","Vibrio parahaemolyticus","Staphylococcus aureus","Salmonella"],"a":2,"e":"Ans. is ''c'' i.e., Staphylococcus aureus . Among the given options, only staphylococcus can cause gasteroenteritis within 6 hours.","pyqMatches":[{"year":"2013","no":829,"q":"An adolescent male developed vomiting and diarrhea 1 hour after having food from a restaurant. The most likely pathogen is?","o":["Clostridium perfringens","Vibrio parahaemolyticus","Staphylococcus aureus","Salmonella"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3413, 'Microbiology', 'Bacteriology', 'Hard', 'Microbiology', 157, '{"id":3413,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Hard","source":"Microbiology","sourceNo":157,"q":"18 years old girl presents with watery diarrhea. Most likely causative agent -","o":["Rota virus","V. cholerae","Salmonella","Shigella"],"a":1,"e":"Ans. is ''b'' i.e., V. cholerae Amongst the given options Rotavirus and V. cholerae cause watery diarrhea. Acute watery diarrha in children is usually bacterial in origin, most commonly due to enterotoxigenic E. coli (ETEC). V cholerae is also a common cause. Rota virus is the most common cause of diarrhea in infant and children (the patient in question is adult).","pyqMatches":[{"year":"2012","no":765,"q":"18 years old girl presents with watery diarrhea. Most likely causative agent","o":["Rota virus","V. cholerae","Salmonella","Shigella"],"a":1,"source":"NEET_2012_Paper.pdf"},{"year":"2016","no":779,"q":"18 years old girl presents with watery diarrhea. Most likely causative agent","o":["Rota virus","V. cholerae","Salmonella","Shigella"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2012","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3414, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 158, '{"id":3414,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":158,"q":"The predominant colonic bacteria are -","o":["Largely aerobic","Largely anaerobic","Bacteroides","Staphylococci"],"a":1,"e":"Ans. is ''b'' i.e., Largely anaerobic * In the adult normal colon, the resident bacterial flora are mostly (96 - 99 per cent) anaerobes : * Anaerobic streptococci (Peptostreptococci) - Clostridia * Anaerobic lactobacilli (bifidobacteria) - Bacteroides * 1-4 per cent are aerobes : * Enterococci * Pseudomonas * Coliforms * Lactobacilli * Proteus Remember * In duodenum and upper ileum, predominant organisms are —> Lactobacilli and enterococci. * In lower ileum and cecum —› Flora resemble the fecal flora.","pyqMatches":[{"year":"2013","no":833,"q":"The predominant colonic bacteria are","o":["Largely aerobic","Largely anaerobic","Bacteroides","Staphylococci"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3415, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 159, '{"id":3415,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":159,"q":"Memory cells are: September 2004","o":["Basophils","Eosinophils","Lymphocytes","Neutrophils"],"a":2,"e":"Ans. C i.e. Lymphocytes","pyqMatches":[{"year":"2016","no":385,"q":"Memory cells are: September 2004","o":["Basophils","Eosinophils","Lymphocytes","Neutrophils"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3416, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 160, '{"id":3416,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":160,"q":"Complement Fixation test is: September 2005","o":["VIDAL","Coombs test","Wassermann reaction","VDRL"],"a":2,"e":"Ans. C: Wassermann reaction The complement fixation test (CFT) was extensively used in syphilis serology after being introduced by Wasserman in 1906. However, there is now a trend to replace the CFT with the simple flocculation tests. Although CFT is considered to be a relatively simple test, it is a very exacting procedure because 5 variables are involved. In essence the test consists of two antigen-antibody reactions, one of which is the indicator system. The first reaction, between a known virus antigen and a specific antibody takes place in the presence of a predetermined amount of complement. The complement is removed or \"fixed\" by the antigen- antibody complex. The second antigen-antibody reaction consists of reacting sheep RBC with haemolysin. When this indicator system is added to the reactants, the sensitized RBCs will only lyse in the presence of free complement. The antigens used for CFT tend to be group antigens rather than type-specific antigens. In order for the CFT to be set up correctly, the optimal concentration of haemolytic serum, complement, and antigen should be determined by titration. The Wassermann test is no longer in use.","pyqMatches":[{"year":"2015","no":778,"q":"Complement Fixation test is: September 2005","o":["VIDAL","Coombs test","Wassermann reaction","VDRL"],"a":2,"source":"NEET_2015_Paper.pdf"},{"year":"2016","no":777,"q":"Complement Fixation test is: September 2005","o":["VIDAL","Coombs test","Wassermann reaction","VDRL"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2015","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3417, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 161, '{"id":3417,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":161,"q":"Confirmatory test for Syphilis is: September 2010 March 2013","o":["VDRL","Rapid plasma reagin test","FT-ABS","All of the above"],"a":2,"e":"Ans. C: FT-ABS T. pallidum cannot be grown in vitro Diagnostic tests for syphilis: Tests include serologic tests for syphilis (STS), which consist of screening (reaginic) and confirmatory (treponemal) tests, and dark field microscopy. Reaginic tests use lipid antigens (cardiolipin from bovine hearts) to detect reagin (human antibodies that bind to lipids). The Venereal Disease Research Laboratory (VDRL) and rapid plasma reagin (RPR) tests are sensitive, simple, and inexpensive reaginic tests that are used for screening but are not specific for syphilis. Results may be presented qualitatively (e.g., reactive, weakly reactive, borderline, or nonreactive) and quantitatively as titers (e.g., positive at 1:16 dilution). Many disorders other than treponemal infections (e.g., SLE, antiphospholipid antibody syndromes) can produce a positive (biologically false-positive) reagin test result. CSF reaginic tests are reasonably sensitive for early disease but less so for late neurosyphilis. CSF reagin tests can be used to diagnose neurosyphilis or to monitor response to treatment by measuring antibody titers. Treponemal tests detect antitreponemal antibodies qualitatively and are very specific for syphilis. They include the following: Fluorescent treponemal antibody absorption (FTA-ABS) test Microhemagglutination assay for antibodies to T. pallidum (MHA-TP) T. pallidum hemagglutination assay (TPHA)","pyqMatches":[{"year":"2016","no":705,"q":"Confirmatory test for Syphilis is: September 2010 March 2013","o":["VDRL","Rapid plasma reagin test","FT-ABS","All of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3418, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 162, '{"id":3418,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":162,"q":"Nosocomial infection is most commonly caused by: March 2004","o":["Gram negative bacilli","Gram positive bacilli","Gram negative cocci","Mycoplasma"],"a":0,"e":"Ans. A i.e. Gram negative bacilli","pyqMatches":[{"year":"2015","no":803,"q":"Nosocomial infection is most commonly caused by: March 2004","o":["Gram negative bacilli","Gram positive bacilli","Gram negative cocci","Mycoplasma"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3419, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 163, '{"id":3419,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":163,"q":"Enteric fever is caused by: September 2005","o":["Salmonella typhi","Salmonella paratyphi A","Salmonella paratyphi B","All of the above"],"a":3,"e":"Ans. D: All of the above Typhoid fever is caused by Salmonella typhi. Paratyphoid fever is caused by Salmonella paratyphi A, B and C. The term enteric fever encompasses both typhoid and paratyphoid fevers.","pyqMatches":[{"year":"2014","no":744,"q":"Enteric fever is caused by: September 2005","o":["Salmonella typhi","Salmonella paratyphi A","Salmonella paratyphi B","All of the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3420, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 164, '{"id":3420,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":164,"q":"Ghon''s focus reflects: September 2005","o":["Miliary tuberculosis","Primary complex","Tuberculous lymphadenitis","Post primary tuberculosis"],"a":1,"e":"Ans. B: Primary complex Only a very small percent of Mycobacterium tuberculosis (MTB) infections result in disease, and even a smaller percentage of MTB infections progress to an advanced stage. The bacilli is engulfed by alveolar macrophages multiply and give rise to a subpleural focus of tuberculous pneumonia, commonly located in the lower lobe or the lower part of the upper lobe.This is known as Ghon focus. The Ghon focus together with the enlarged hilar lymph node constitutes the primary complex. Small metastatic foci containing low numbers of MTB may also calcify. However, in many cases these foci will contain viable organisms. These foci are referred to Simon foci. The Simon foci are also visible upon chest X-ray and are often the site of disease reactivation.","pyqMatches":[{"year":"2015","no":485,"q":"Ghon''s focus reflects: September 2005","o":["Miliary tuberculosis","Primary complex","Tuberculous lymphadenitis","Post primary tuberculosis"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3421, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 165, '{"id":3421,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":165,"q":"Diphtheria toxin''s mechanism of action is: September 2009","o":["Inhibiting glucose synthesis","Inhibiting protein synthesis","Promoting acetylcholine release","Altering cyclic GMP levels"],"a":1,"e":"Ans. B: Inhibiting protein synthesis The diphtheria toxin causes the death eucaryotic cells and tissues by inhibition of protein synthesis in the cells. Although the toxin is responsible for the lethal symptoms of the disease, the virulence of C. diphtheriae cannot be attributed to toxigenicity alone, since a distinct invasive phase apparently precedes toxigenesis.","pyqMatches":[{"year":"2016","no":728,"q":"Diphtheria toxin''s mechanism of action is: September 2009","o":["Inhibiting glucose synthesis","Inhibiting protein synthesis","Promoting acetylcholine release","Altering cyclic GMP levels"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3422, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 166, '{"id":3422,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":166,"q":"Most serious complication of measles is: September 2008","o":["Croup","Meningo-encephalitis","Otitis media","Pneumonia"],"a":1,"e":"Ans. B: Meningo-encephalitis Measles is a highly communicable acute disease. It is also known as rubeola and is marked by prodromal fever, cough, coryza, conjunctivitis, and pathognomonic enanthem (i.e., Koplik spots), followed by an erythematous maculopapular rash on the third to seventh day. Infection confers life-long immunity. A generalized immunosuppression that follows acute measles frequently predisposes patients to bacterial otitis media and bronchopneumonia. In approximately 0.1% of cases, measles causes acute meningo- encephalitis,which is the most serious complication. Subacute sclerosing panencephalitis (SSPE) is a rare chronic degenerative disease that occurs several years after measles infection.","pyqMatches":[{"year":"2020","no":151,"q":"Most serious complication of measles is: September 2008","o":["Croup","Meningo-encephalitis","Otitis media","Pneumonia"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3423, 'Microbiology', 'Parasitology', 'Easy', 'Microbiology', 167, '{"id":3423,"subject":"Microbiology","chapter":"Parasitology","difficulty":"Easy","source":"Microbiology","sourceNo":167,"q":"Promastigote form of Leishmania is found in which part of sandfly: March 2005","o":["Lymph node","GIT","Spleen","Bone marrow"],"a":1,"e":"Ans. B: GIT","pyqMatches":[{"year":"2016","no":735,"q":"Promastigote form of Leishmania is found in which part of sandfly: March 2005","o":["Lymph node","GIT","Spleen","Bone marrow"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3424, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 168, '{"id":3424,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":168,"q":"For phage typing, how many phages of staphylococcus aureus are used ?","o":["12","15","20","23"],"a":3,"e":"Ans. is'' D i.e., 23 Bacteriophage typing of staphylococcus is based on the susceptibility of cocci to bacteriophages. This is carried out by pattern method where a set of 23 standard typing phages of S. aureus is used to type staphylococcal isolates and distinguish them from one another by their patterns of susceptibility to lysis. The phage-type of a strain is known by the designation of the phages that lyse it. For example, if a strain is lysed by phages 83A, 84 and 85, it is called type 83A/84/85.","pyqMatches":[{"year":"2014","no":728,"q":"For phage typing, how many phages of staphylococcus aureus are used ?","o":["12","15","20","23"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3425, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 169, '{"id":3425,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":169,"q":"Most common biotype of S. aureus causing human infection ?","o":["A","B","C","D"],"a":0,"e":"Ans. is ''a'' i.e., A Staphylococcus aureus has been classified into six biotypes : A, B, C, D, E and F. Most human pathogenic strains belong to biotype A.","pyqMatches":[{"year":"2014","no":729,"q":"Most common biotype of S. aureus causing human infection ?","o":["A","B","C","D"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3426, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 170, '{"id":3426,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":170,"q":"Most common pox virus infection in human is ?","o":["Smallpox","Monkeypox","Cowpox","Mulluscum contagiosum"],"a":3,"e":"Ans. is ''d'' i.e., Mulluscum contagiosum Among the given options, smallpox (variola) virus and molluscum contagiosum affect human as their primary host. Small pox has been eradicated. Molluscum contagiosum is a common skin infection.","pyqMatches":[{"year":"2014","no":797,"q":"Most common pox virus infection in human is ?","o":["Smallpox","Monkeypox","Cowpox","Mulluscum contagiosum"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3427, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 171, '{"id":3427,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":171,"q":"HHV-6 causes ?","o":["Erythema infectiosum","Kaposi sarcoma","Roseola infantum","Herpangina"],"a":2,"e":"Ans. is ''c'' i.e., Roseola infantum","pyqMatches":[{"year":"2014","no":804,"q":"HHV-6 causes ?","o":["Erythema infectiosum","Kaposi sarcoma","Roseola infantum","Herpangina"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3428, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 172, '{"id":3428,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":172,"q":"Phenylalanine deaminase test is positive in ?","o":["Salmonella","Proteus","Vibrio cholerae","Helicobacter"],"a":1,"e":"Ans. is ''b'' i.e., Proteus The distinctive character of proteus genus is deamination of phenyl alanine to phenyl pyruvic acid (PPA + ye)","pyqMatches":[{"year":"2014","no":743,"q":"Phenylalanine deaminase test is positive in ?","o":["Salmonella","Proteus","Vibrio cholerae","Helicobacter"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3429, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 173, '{"id":3429,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":173,"q":"Gram positive, catalase negative cocci ?","o":["Staph aureus","Staph epidermidis","Staph saprophyticus","Pneumococcus"],"a":3,"e":"Ans. is ''d'' i.e., Pneumococcus","pyqMatches":[{"year":"2014","no":736,"q":"Gram positive, catalase negative cocci ?","o":["Staph aureus","Staph epidermidis","Staph saprophyticus","Pneumococcus"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3430, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 174, '{"id":3430,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":174,"q":"R-factor in bacteria is transfered by ?","o":["Transduction","Transformation","Conjugation","Vertical transmission"],"a":2,"e":"Ans. is ''c'' i.e., Conjugation Conjugation Bacterial conjugation is the transfer of genetic material between bacteria through direct cell to cell contact or through a bridge- like connection between two cells. Conjugation is process where by a donor (male) bacterium makes physical contact with a recipient (female) bacterium. Donor status is determined by the presence of plasmid. This plasmid codes for specialized fimbria (sex pilus) and for self transfer. Sex pilus (conjugation tube) helps in transfer of genetic material from male bacterium to female bacterium. The plasmid is known as transfer factor (sex factor or fertility factor). Plasmid may be R factor, which codes for transferrable multiple drug resistance. The DNA of the plasmid replicates during transfer so that each bacterium receives a copy Recipient becomes donor and the donor retains its donor status.","pyqMatches":[{"year":"2014","no":851,"q":"R-factor in bacteria is transfered by ?","o":["Transduction","Transformation","Conjugation","Vertical transmission"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3431, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 175, '{"id":3431,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":175,"q":"Feces are disinfected best by ?","o":["1% formaldehyde","5% cresol","5% phenol","Isopropyl alcohol"],"a":1,"e":"Ans. is ''b'' i.e., 5% cresol \"The most effective disinfectant for general use is a coal-tar disinfectant with a Rideal-Walker (RW) coefficient of 10 or more such as cresol\".","pyqMatches":[{"year":"2014","no":853,"q":"Feces are disinfected best by ?","o":["1% formaldehyde","5% cresol","5% phenol","Isopropyl alcohol"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3432, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 176, '{"id":3432,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":176,"q":"Stool specimen is transported in ?","o":["Cary blair medium","Blood agar","Selenite F broth","Compy BAP medium"],"a":0,"e":"Ans. is ''a'' i.e., Cary blair medium Transport media for stool specimen are :? a. Cary-Blair medium b. Buffered glycerol saline c. Stuart medium Inoculate media for routine stool culture are :- a. Blood agar b. MacConkey agar c. Hektoen enteric HE ( agar) d. Selective media for campylobactor : Campy BAP, skirrow e. Selenite F broth or GN Broth f. Xylose-lysine deoxycholate agar (XLD agar) For specific situations, selective media are used :- i. Vibrio : TCBS agar or Alkaline peptone broth. i. Yersinia : Cefsulodin-Irgasan-Novobiosin (CIN) agar or Phosphate Buffered Saline (PBS) broth. i. E.coli 0157:H7: Sarbitol-MacConkey agar.","pyqMatches":[{"year":"2014","no":863,"q":"Stool specimen is transported in ?","o":["Cary blair medium","Blood agar","Selenite F broth","Compy BAP medium"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3433, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 177, '{"id":3433,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":177,"q":"HEPA filter is used to disinfect ?","o":["Water","Air","Culture","Blood"],"a":1,"e":"Ans. is ''b'' i.e., Air HEPA (High-efficiency particulate air) filter is used to remove microorganisms from air. HEPA filter traps airborne particles and microbes. It can remove > 95% of all particles including microorganisms with a diameter > 0.3 p.m.","pyqMatches":[{"year":"2014","no":852,"q":"HEPA filter is used to disinfect ?","o":["Water","Air","Culture","Blood"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3434, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 178, '{"id":3434,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":178,"q":"Virus most sensitive to inactivation by biocides ?","o":["Adenovirus","Herpes virus","Parvovirus","Poliovirus"],"a":1,"e":"Ans. is ''b'' i.e., Herpes virus Enveloped viruses are most sensitive to inactivation by biocides. Among the given options only Herpesvirus is enveloped virus. Adenovirus, parvovirus and poliovirus (picornavirus) are non- enveloped viruses.","pyqMatches":[{"year":"2014","no":802,"q":"Virus most sensitive to inactivation by biocides ?","o":["Adenovirus","Herpes virus","Parvovirus","Poliovirus"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3435, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 179, '{"id":3435,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":179,"q":"Complement components are ?","o":["Lipoproteins","Glycoproteins","Polysaccharides","Lipid"],"a":1,"e":"Ans. is ''b'' i.e., Glycoproteins The proteins and glycoprotiens that constitute the complement system are synthesized by hepatocytes\" — Internet \"Most of the complement glycoproteins are synthesized predominantly by the liver, but macrophages and many other cell types are also sources of various complement components\" - Medical immunology \"Complement components are glycoproteins\" — Textbook of Human Blood Plasma Protiens","pyqMatches":[{"year":"2014","no":880,"q":"Complement components are:","o":["Lipids","Proteins","Lipoproteins","Polysaccharide"],"a":1,"source":"NEET_2014_Paper.pdf"},{"year":"2014","no":881,"q":"Complement components are ?","o":["Lipoproteins","Glycoproteins","Polysaccharides","Lipid"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3436, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 180, '{"id":3436,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":180,"q":"True about Campylobacter jejuni ?","o":["Obligate aerobe","Oxidase negative","Grows at 42°C","Non-motile"],"a":2,"e":"Ans. is ''C'' i.e., Grows at 42°C Campylobacter jejuni Morphology Gram negative Comma shaped Motile with a single polar flagellum → Darting or tumbling motility Non capsulated Non Sporing Culture Growth occurs under microaerophilic conditions (5% O2, 10% CO2 and 85% N2). Thermophilic, growing at 42°C (Can grow at 37°C, but incubation at higher temperatures suppresses normal fecal flora.) Biochemical reactions Do not ferment carbohydrate Catalase and oxidase-positive Nitrate reduction positive","pyqMatches":[{"year":"2014","no":754,"q":"True about Campylobacter jejuni ?","o":["Obligate aerobe","Oxidase negative","Grows at 42°C","Non-motile"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3437, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 181, '{"id":3437,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":181,"q":"Best indicator for sterilization by autoclaving ?","o":["Bacillus subtilis","Geobacillus","Bacillus pumilis","Clostridium"],"a":1,"e":"Ans. is ''b'' i.e., Geobacillus Biological indicators Biological indicators are standardised preparations of microorganisms used to assess the effectiveness of a sterilization process. They usually consist of a population of bacterial spores placed on an inert carrier, for example a strip of filter paper, a glass slide or a plastic tube. Most commonly, spores of Bacillus stereothermophilus (Geobacillus stearothermophilus) are used. Spores of Bacillus subtilis and Bacillus pumilis are alse used.","pyqMatches":[{"year":"2014","no":861,"q":"Best indicator for sterilization by autoclaving ?","o":["Bacillus subtilis","Geobacillus","Bacillus pumilis","Clostridium"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3438, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 182, '{"id":3438,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":182,"q":"Satellitism is seen in cultures of?","o":["Hemophilus","Streptococcus","Klebsiella","Proteus"],"a":0,"e":"Ans. is ''a'' i.e., Haemophilus Satellitism The growth of Haemophilus influenzae is scanty on blood agar, as the factor V is not freely available, being imprisoned inside the red blood cells. Growth is, therefore, better if the source of the V factor is also provided. When Staph aureus is streaked across a plate of blood agar on which a specimen containing H. influenzae has been inoculated, after overnight incubation, the colonies of H. influenzae will be large and well developed alongside the streak of staphylococcus, and smaller further away. This phenomenon is called satellitism. Satellitism is due to a high concentration of factor ''V'' in staph aureus which is released into medium and is used by H. influenzae.","pyqMatches":[{"year":"2014","no":758,"q":"Satellitism is seen in cultures of?","o":["Hemophilus","Streptococcus","Klebsiella","Proteus"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3439, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 183, '{"id":3439,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":183,"q":"Varicella zoster virus belongs to which family of DNA viruses ?","o":["Poxviridae","Herpesviridae","Adenoviridae","Papovaviridae"],"a":1,"e":"Ans. is `b'' i.e., Herpesviridae DNA viruses Poxviridae :- Variola, vaccinia, cowpox, monkeypox, tanapox, molluscum contagiosum Herpesviridae :- HSV-1, HSV-2, varicella- zoster, EBV, CMV, HTLV- 1, RK-virus Adenoviride Adenovirus Parvoviridae Parvovirus, Adenosatellovirus, Densovirus Papovaviridae Papilloma virus (HPV), Polyomavirus Hepadnaviridae Hepatitis-B virus","pyqMatches":[{"year":"2014","no":791,"q":"Varicella zoster virus belongs to which family of DNA viruses ?","o":["Poxviridae","Herpesviridae","Adenoviridae","Papovaviridae"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3440, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 184, '{"id":3440,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":184,"q":"C1 esterase inhibitor deficiency causes ?","o":["Neisseria infection","Hereditary angioneurotic edema","Hemolytic disease","Hemolytic uremic syndrome"],"a":1,"e":"Ans. is ''b'' i.e., Hereditary angioneurotic edema Hereditary angioneurotic edema is due to C1 inhibitor (CI esterase inhibitor) deficiency.","pyqMatches":[{"year":"2014","no":882,"q":"C1 esterase inhibitor deficiency causes ?","o":["Neisseria infection","Hereditary angioneurotic edema","Hemolytic disease","Hemolytic uremic syndrome"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3441, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 185, '{"id":3441,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":185,"q":"Runt disease is ?","o":["Graft rejection","Graft vs host disease","Host vs graft disease","Type III hypersensitivity"],"a":1,"e":"Ans. is ''b'' i.e., Graft vs host disease","pyqMatches":[{"year":"2014","no":884,"q":"Runt disease is ?","o":["Graft rejection","Graft vs host disease","Host vs graft disease","Type III hypersensitivity"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3442, 'Microbiology', 'Miscellaneous', 'Moderate', 'Microbiology', 186, '{"id":3442,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Microbiology","sourceNo":186,"q":"True about hydatid cyst are all, except ?","o":["Most common site is liver","Calcification is common in lung","May involve kidney","Liver cysts are more common in right lobe"],"a":1,"e":"Ans. is ''b'' i.e., Calcification is common in lung Hydatid disease Liver cysts The majority of hydatid cysts occur in the liver, causing symptoms : Chronic abdominal discomfort Palpable abdominal mass Allergic reactions due to cyst rupture - skin rash, anaphylactic shock, or death. Abscess formation due to secondry bacterial infection Liver cysts occur more frequently in the right lobe. Lung cyst Second most common organ (after liver) Usually asymptomatic Occasionally may cause symptoms. Least common site of calcified hydatid cyst. Radiographic signs","pyqMatches":[{"year":"2014","no":832,"q":"True about hydatid cyst are all, except ?","o":["Most common site is liver","Calcification is common in lung","May involve kidney","Liver cysts are more common in right lobe"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3443, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 187, '{"id":3443,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":187,"q":"Virulence factor for clostridium tetani ?","o":["Endotoxin","Tetanolysin","Tetanospasmin","Bacteremia"],"a":2,"e":"Ans. is ''c'' i.e., Tetanospasmin Pathogenicity of CI tetani Cl. tetani has little invasive property and is confined to the primary site of lodgment. Tetanus results from the action of the potent exotoxin it produces. Toxins of CI tetani 1) Tetanolysin (Hemolysin) Not relevant in the pathogenesis of tetanus. 2) Tetanospasmin (neurotoxin) Responsible for tetanus It is plasmid coded In the brainstem and spinal cord it blocks release of the inhibitory neurotransmitter glycine and ''y​aminobutyric acid (GABA). It resembles strychnine in its effects, but it acts presynaptically, while strychnine acts postsynaptically. o Tetanus toxin and botulinum toxin resemble each other in their aminoacid sequences. 3) Nonspasmogenic, peripherally active neurotoxin Its role is not known","pyqMatches":[{"year":"2014","no":734,"q":"Virulence factor for clostridium tetani ?","o":["Endotoxin","Tetanolysin","Tetanospasmin","Bacteremia"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3444, 'Microbiology', 'Virology', 'Moderate', 'Microbiology', 188, '{"id":3444,"subject":"Microbiology","chapter":"Virology","difficulty":"Moderate","source":"Microbiology","sourceNo":188,"q":"Which myxovirus does not have hemagglutinin and neuraminidase but have membrane fusion protein -","o":["Measles","Parainfluenza","RSV","Influenza"],"a":2,"e":"Ans. is ''c'' i.e., RSV RSV does not posses hemagglutinin or neuraminidase. The viral envelope has two glycoproteins? i) G protein → By which virus attaches to cell surface ii) F- protein ( Fusion protein ) → which bring about fusion between viral and host cell membranes. It is also responsible for cell to cell fusion, which leads to characteristic syncytial formation.","pyqMatches":[{"year":"2014","no":801,"q":"Which myxovirus does not have hemagglutinin and neuraminidase but have membrane fusion protein","o":["Measles","Parainfluenza","RSV","Influenza"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3445, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 189, '{"id":3445,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":189,"q":"Which prion disease affect human ?","o":["Scrapie","Madcow disease","Kuru","Bovine spongiform encephalopathy"],"a":2,"e":"Kuru prion Infection through ritualistic cannibalism","pyqMatches":[{"year":"2014","no":830,"q":"Which prion disease affect human ?","o":["Scrapie","Madcow disease","Kuru","Bovine spongiform encephalopathy"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3446, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 190, '{"id":3446,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":190,"q":"Peritrichous flagellae are seen in ?","o":["Vibrio cholerae","Proteus","Campylobacter","Legionella"],"a":1,"e":"Ans. is ''b'' i.e., Proteus","pyqMatches":[{"year":"2014","no":877,"q":"Peritrichous flagellae are seen in ?","o":["Vibrio cholerae","Proteus","Campylobacter","Legionella"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3447, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 191, '{"id":3447,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":191,"q":"Molluscum contagiosum virus belongs to ?","o":["Poxviruses","Herpesviruses","Picornaviruses","Adenovirus"],"a":0,"e":"Ans. is ''a'' i.e., Poxviruses","pyqMatches":[{"year":"2014","no":792,"q":"Molluscum contagiosum virus belongs to ?","o":["Poxviruses","Herpesviruses","Picornaviruses","Adenovirus"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3448, 'Microbiology', 'Clinical Microbiology', 'Easy', 'Microbiology', 192, '{"id":3448,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":192,"q":"True about vibrio vulnificus ?","o":["Causes diarrhea commonly","Halophilic","Drug of choice is penicillin","Produces shiga toxin"],"a":1,"e":"Ans. is ''b i.e., Halophilic V. Vulnificus V. vulnificus is a halophilic vibrio. It has been linked to two distinct syndrome.","pyqMatches":[{"year":"2014","no":753,"q":"True about vibrio vulnificus ?","o":["Causes diarrhea commonly","Halophilic","Drug of choice is penicillin","Produces shiga toxin"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3449, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 193, '{"id":3449,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":193,"q":"True about diphtheria toxin ?","o":["Heat stable","Acts through cGMP","Consists of three fragments","Special affinity for brain"],"a":0,"e":"Ans. is ''a'' i.e., Heat stable \"Diphtheria toxin is a heat-stable polypeptide, composed of two fragments\" - Medical microbiology Diphtheria toxin The diphtheria toxin acts by inhibiting protein synthesis. It inhibits polypeptide chain elongation in the presence of nicotinamide adinine dinucleotide (NAD) by inactivating elongation factor, EF - 2. The diphtheria toxin is a protein which consists of two fragments, A and B. Both fragments are necessary for the toxic effect :","pyqMatches":[{"year":"2014","no":763,"q":"True about diphtheria toxin ?","o":["Heat stable","Acts through cGMP","Consists of three fragments","Special affinity for brain"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3450, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 194, '{"id":3450,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":194,"q":"How does chlamydia differ from other usual bacteria?","o":["Lack cell wall","Cannot grow in cell free culture media","Contains inclusion body","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., Contains inclusion body Chlamydia produces basophilic (intracytoplasmic) inclusion bodies in infected cells in contrast to eosinophilic inclusion bodies produced by most viruses and hence they are sometimes referred to as Basophilic viruses. Unique properties of chlamydiae are Chlamydia is an obligate intracellular parasite. This means they can survive only by establishig residence inside animal cells They need their host''s ATP as an energy source for their own cellular activity. They are energy parasites using a cell membrane transport system that uses ATP from the host system and gives out ADP. This obligate intracellular existence makes it impossible to culture these organisms on nonliving artificial media. Due to their small size and failure to grow in cell - free media they were considered to be viruses. Chlamydiae grows in cultures of a variety of eukaryotic cell lines Mc Coy or HeLa cells. It may be necessary to treat cells with polyanionic compounds such as DEAD-dextran to reduce the electrostatic barrier to infection. Antimetabolite such as cycloheximide is added to favour competition for host cell amino acid pools. All types of chlamydiae proliferate in embryonated eggs particulary in the yolk sac. The special features in structure and chemical composition of chlamydiae are:","pyqMatches":[{"year":"2014","no":764,"q":"How does chlamydia differ from other usual bacteria?","o":["Lack cell wall","Cannot grow in cell free culture media","Contains inclusion body","None of the above"],"a":2,"source":"NEET_2014_Paper.pdf"},{"year":"2016","no":713,"q":"How does chlamydia differ from other usual bacteria?","o":["Lack cell wall","Cannot grow in cell free culture media","Contains inclusion body","None of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2014","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3451, 'Microbiology', 'Bacteriology', 'Hard', 'Microbiology', 195, '{"id":3451,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Hard","source":"Microbiology","sourceNo":195,"q":"A patient is suffering from pneumonia. Laboratory study shows acid-fast filamentous bacterium. The causative organism is ?","o":["M. tuberculosis","Actinomyces","Nocardia","Mycobacterium Avium intracellulare"],"a":2,"e":"Ans. is ''c'' i.e., Nocardia Symptoms of pneumonia by a filamentous acid fast bacterium suggest the diagnosis of Nocardia.","pyqMatches":[{"year":"2014","no":765,"q":"A patient is suffering from pneumonia. Laboratory study shows acid-fast filamentous bacterium. The causative organism is ?","o":["M. tuberculosis","Actinomyces","Nocardia","Mycobacterium Avium intracellulare"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3452, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 196, '{"id":3452,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":196,"q":"Mycobacterium tuberculosis grows in LJ media in?","o":["1 0- 14 days","2-3 weeks","4-8 weeks","> 10 weeks"],"a":2,"e":"Ans. is ''c'' i.e., 4-8 weeks M tuberculosis produces visible colonies on solid media (L.J. media) in 4-8 weeks Use of liquid media with radiomimetic growth detection (BACTEC- 460) and the identification of isolates by nucleic acid probes give result in 2-3 weeks.","pyqMatches":[{"year":"2014","no":759,"q":"Mycobacterium tuberculosis grows in LJ media in?","o":["1 0- 14 days","2-3 weeks","4-8 weeks","> 10 weeks"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3453, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 197, '{"id":3453,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":197,"q":"Which of the following is an example of heterophile antibody test ?","o":["Widal test","Weil-Felix reaction","Rose-waler test","Blood grouping & cross matching"],"a":1,"e":"Ans. is ''b'' i.e., Weil-Felix reaction Heterophilic agglutination reaction Some organisms of different class or species share closely related antigens. When serum containing agglutinin (antibody) of one organism gives agglutination reaction with antigen of other organism, it is called heterophilic agglutination test. Examples are Streptococcus M.G. agglutination test for primary atypical pneumonia. Weil - Felix reaction for typhus fever. Paul Bunnell test for IM1V.","pyqMatches":[{"year":"2014","no":879,"q":"Which of the following is an example of heterophile antibody test ?","o":["Widal test","Weil-Felix reaction","Rose-waler test","Blood grouping & cross matching"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3454, 'Microbiology', 'Virology', 'Moderate', 'Microbiology', 198, '{"id":3454,"subject":"Microbiology","chapter":"Virology","difficulty":"Moderate","source":"Microbiology","sourceNo":198,"q":"All cause viral hepatitis except -","o":["Measles","EBV","Rhinovirus","Reovirus"],"a":2,"e":"Ans. is ''c'' i.e., Rhinovirus Important viruses causing hepatitis:? 1) Hepatotropic viruses : HAV, HBV, HCV, HD V, HEV. 2) Herpes viruses : CMV, EBV, HSV-1, VZV. 3) Flaviviruses : Yellow fever, dengue fever. 4) Filoviruses : Marburg virus, Ebola virus. 5) Occasinal causes Measles virus, adenovirus, Echoviruses, Coxsackieviruses, influenza virus, parvoviruses, reoviruses, mumps virus.","pyqMatches":[{"year":"2014","no":805,"q":"All cause viral hepatitis except","o":["Measles","EBV","Rhinovirus","Reovirus"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3455, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 199, '{"id":3455,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":199,"q":"Shiga toxin acts by ?","o":["Activating adenylyl cyclase to increase cAMP","Activating guanylyl cyclase to increase cGMP","Inhibiting protein synthesis","Inhibiting DNA replication"],"a":2,"e":"Ans. is ''c'' i.e., Inhibiting protein synthesis","pyqMatches":[{"year":"2014","no":741,"q":"Shiga toxin acts by ?","o":["Activating adenylyl cyclase to increase cAMP","Activating guanylyl cyclase to increase cGMP","Inhibiting protein synthesis","Inhibiting DNA replication"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3456, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 200, '{"id":3456,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":200,"q":"Enrichment media for cholera ?","o":["VR medium","TCBS medium","Cary-Blair medium","Alkaline peptone water"],"a":3,"e":"Ans. is ''d'' i.e., Alkaline peptone water","pyqMatches":[{"year":"2012","no":670,"q":"Enrichment media for cholera ?","o":["VR medium","TCBS medium","Cary-Blair medium","Alkaline peptone water"],"a":3,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":747,"q":"Enrichment media for cholera ?","o":["VR medium","TCBS medium","Cary-Blair medium","Alkaline peptone water"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3457, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 201, '{"id":3457,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":201,"q":"True about vibrio parahemolyticus ?","o":["Polar flagella","Non halophilic vibrio","Non-capsulated","Requires NaCI"],"a":3,"e":"Ans. is ''d'' i.e., Requires NaCI It is halophilic vibrio. * Inhabits the coastal sea, where it isfound inftshes arthopods such as shrimps and ctabs and molluscs such as oyster. * It resembles the cholera vibrio except that: --> It is capsulated. --> Shows bipolar staining * Produces peritrichous flagella when grown on solid mediun (V. cholerae has polar flagella), in liquid medium polar flagella are formed. * It grows, only in media containing NaCl, optimum conc.is 2-4 %, lts enteropathogenic is closely linked to its ability to cause hemolysis on Wagatsuma agar t the Kanagawa phenomenon.","pyqMatches":[{"year":"2014","no":751,"q":"True about vibrio parahemolyticus ?","o":["Polar flagella","Non halophilic vibrio","Non-capsulated","Requires NaCI"],"a":3,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":700,"q":"True about vibrio parahemolyticus ?","o":["Polar flagella","Non halophilic vibrio","Non-capsulated","Requires NaCI"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3458, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 202, '{"id":3458,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":202,"q":"Selective medium for shigella ?","o":["Chocolate agar","BYCE medium","Hektoen agar","EMJH medium"],"a":2,"e":"Ans. is ''c'' i.e., Hektoen agar","pyqMatches":[{"year":"2014","no":742,"q":"Selective medium for shigella ?","o":["Chocolate agar","BYCE medium","Hektoen agar","EMJH medium"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3459, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 203, '{"id":3459,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":203,"q":"Sterilization is defined as ?","o":["Disinfection of skin","Complete destruction of all microorganisms","Destruction of pathogenic organisms","Decrease bacterial count from objects"],"a":1,"e":"Ans. is ''b'' i.e., Complete destruction of all microorganisms Sterilization The process by which an article surface or medium is freed of all living microorganisms either in the vegetative or spore state Complete absence of microorganism. Disinfection Destruction or removal of all pathogenic organisms capable of giving rise to infection reduction in the microorganisms to such a level which is deemed no longer harmful to health. Unlike sterilization, disinfection is not sporicidal (does not kill spores). Decontamination The process of rendering of an article or area free of danger from contaminants, including microbial, chemical, radioactive and other hazards. Antisepsis It is defined as\" Prevention of infection, usually by inhibiting the growth of bacteria in wound or tissues\". Antiseptics Chemical disinfectants which can be safely applied to skin or mucous membrane are called antiseptics or skin disinfactant. Best and most commonly used antiseptic is povidone iodine (betadine). Commonly used skin disinfactants for hand washing are povidone iodine (betadine), chlorhexidine and isopropyl alcohol. Disinfectants Antimicrobials applied only to inanimate object. They are not used for surface disinfection(A\"9) (skin or mucous membrane). Germicides These include both antiseptics and disinfectant.","pyqMatches":[{"year":"2014","no":862,"q":"Sterilization is defined as ?","o":["Disinfection of skin","Complete destruction of all microorganisms","Destruction of pathogenic organisms","Decrease bacterial count from objects"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3460, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 204, '{"id":3460,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":204,"q":"True about endotoxin ?","o":["Protein","Highly antigenic","No enzymatic activity","Produced by gram positive bacteria"],"a":2,"e":"Ans. is ''c'' i.e., No enzymatic activity","pyqMatches":[{"year":"2014","no":878,"q":"True about endotoxin ?","o":["Protein","Highly antigenic","No enzymatic activity","Produced by gram positive bacteria"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3461, 'Microbiology', 'Clinical Microbiology', 'Hard', 'Microbiology', 205, '{"id":3461,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Hard","source":"Microbiology","sourceNo":205,"q":"A 17 years old female presents with sore throat, lymphadenopathy and positive heterophile antibodies test. Diagnosis is ?","o":["Tuberculosis","Streptococcal pharyngitis","Infectious mononucleosis","Cytomegalic inclusion disease"],"a":2,"e":"Ans. is ''c'' i.e., Infectious mononucleosis Laboratory diagnosis In IMN, there is predominantly lymphocytosis with presence of 20% or more atypical lymphocytes. These atypical lymphocytes are activated T-lymphocytes which have round or irregularly shaped nuclei, with abundant flowing cytoplasm that characteristically has a dark-staining peripheri.","pyqMatches":[{"year":"2014","no":816,"q":"A 17 years old female presents with sore throat, lymphadenopathy and positive heterophile antibodies test. Diagnosis is ?","o":["Tuberculosis","Streptococcal pharyngitis","Infectious mononucleosis","Cytomegalic inclusion disease"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3462, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 206, '{"id":3462,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":206,"q":"Lethal effect of dry heat is due to ?","o":["Denaturation of proteins","Oxidative damage","Toxicity due to metabolites","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above HEAT STERILIZATION Heat is the most reliable method of sterilisation and should be the method of choice unless contraindicated. o Sterilization by heat is of two types. Dry heat Killing effect is due to protein denaturation, oxidative damage and the toxic effect of elevated metabolites.","pyqMatches":[{"year":"2014","no":858,"q":"Lethal effect of dry heat is due to ?","o":["Denaturation of proteins","Oxidative damage","Toxicity due to metabolites","All of the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3463, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 207, '{"id":3463,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":207,"q":"PLET medium is used in ?","o":["Plague","Anthrax","Typhoid","Cholera"],"a":1,"e":"Ans. is `b'' i.e., Anthrax Selective media for B. antracis is PLET medium, consisting of polymyxin, lysozyme, ethylene diamine tetraacetic acid (EDTA) and thallous acetate added to heart infusion agar.","pyqMatches":[{"year":"2014","no":773,"q":"PLET medium is used in ?","o":["Plague","Anthrax","Typhoid","Cholera"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3464, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 208, '{"id":3464,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":208,"q":"Tunica reaction is positive in ?","o":["R prowazekii","R typhi","R tsutsugamushi","R akari"],"a":1,"e":"Ans. is ''b'' i.e., R typhi Neill - Mooser (Tunica) reaction When male guinea pigs are inoculated intraperitoneally with blood from a case of endemic typhus or with a culture of R. typhi (R. mooseri) they develop fever and a characteristic scrotal inflammation. This reaction is used to differentiate R. typhi and R. prowazekii.","pyqMatches":[{"year":"2014","no":788,"q":"Tunica reaction is positive in ?","o":["R prowazekii","R typhi","R tsutsugamushi","R akari"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3465, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 209, '{"id":3465,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":209,"q":"Laproscope is sterilized by ?","o":["2% formalin","2% glutaraldehyde","Autoclaving","Boiling"],"a":1,"e":"Ans. is ''b'' i.e., 2% glutaraldehyde All endoscopes (e.g. laproscope) are sterilized by 2% glutaraldehyde (cidex).","pyqMatches":[{"year":"2014","no":855,"q":"Laproscope is sterilized by ?","o":["2% formalin","2% glutaraldehyde","Autoclaving","Boiling"],"a":1,"source":"NEET_2014_Paper.pdf"},{"year":"2016","no":690,"q":"Laproscope is sterilized by ?","o":["2% formalin","2% glutaraldehyde","Autoclaving","Boiling"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2014","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3466, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 210, '{"id":3466,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":210,"q":"Suckling mice is used for isolation of ?","o":["Coxsachie virus","Pox","Herpes","Adenovirus"],"a":0,"e":"Ans. is ''a'' i.e., Coxsackie virus It is necessary to employ suckling mice for the isolation of coxsackie viruses. Inoculation is usually made by intracerebral, subcutaneous and intraperitoneal route. Adult mice are not susceptible.","pyqMatches":[{"year":"2014","no":817,"q":"Suckling mice is used for isolation of ?","o":["Coxsachie virus","Pox","Herpes","Adenovirus"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3467, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 211, '{"id":3467,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":211,"q":"Safety pin appearance is seen in ?","o":["Vibrio vulnificus","Vibrio parahemolyticus","Pseudomonas aeuroginosa","H. influenzae"],"a":1,"e":"Ans. is `b'' i.e., Vibrio parahemolyticus Bipolar staining (safety pin appearance) Some bacteria display a safety pin appearance due to the accumulation of dye at the poles of the cells. This characteristic is called bipolar staining. Bacteria showing bipolar staining are?","pyqMatches":[{"year":"2014","no":767,"q":"Safety pin appearance is seen in ?","o":["Vibrio vulnificus","Vibrio parahemolyticus","Pseudomonas aeuroginosa","H. influenzae"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3468, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 212, '{"id":3468,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":212,"q":"Which anticoagulant is used when blood is sent for blood culture ?","o":["Sodium citrate","EDTA","Oxalate","SPS"],"a":3,"e":"Ans. is ''d'' i.e., SPS Many different types of bacteria and fungi have been identified as causative agents of septicemia. For this reason, many diverse culture media formulations are available in prepared blood culture bottles. Majority of these media contain 0.03% SPS (Sodium polyanethal sulfonate), a polyanionic anticoagulant, which additionally inhibits complement and lysozyme activity, interferes with phagocytosis and inactivates aminoglycosides. Following important blood culture bottles are there :- i) Brain heart infusion (BHI) with PABA (para-aminobenzoic acid) ii) Brucella broth with 6% sorbitol iii) Brucella broth with 10% sucrose iv) Columbia broth v) Thioglycolate medium vi) Tryptic soy broth","pyqMatches":[{"year":"2013","no":731,"q":"Which anticoagulant is used when blood is sent for blood culture ?","o":["Sodium citrate","EDTA","Oxalate","SPS"],"a":3,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":864,"q":"Which anticoagulant is used when blood is sent for blood culture ?","o":["Sodium citrate","EDTA","Oxalate","SPS"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3469, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 213, '{"id":3469,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":213,"q":"Kanagawa''s phenomenon is seen in ?","o":["Pseudomonea aeuroginosa","Vibrio parahemolyticus","Shigella sonie","Proteus mirabilis"],"a":1,"e":"Ans. is ''b'' i.e., Vibrio parahemolyticus Strains of vibrio parahemolyticus isolated from patients are always hymolytic on Wagatsuma agar, while strains from environmental sources are always non-hemolytic. This linkage of enteropathogenicity to ability of hemolysis on Wagatsuma agar is called Kanagawa''s phenomenon.","pyqMatches":[{"year":"2014","no":752,"q":"Kanagawa''s phenomenon is seen in ?","o":["Pseudomonea aeuroginosa","Vibrio parahemolyticus","Shigella sonie","Proteus mirabilis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3470, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 214, '{"id":3470,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":214,"q":"Which flavivirus causes hepatitis in human ?","o":["Hepatitis A","Hepatitis B","Hepatitis C","Hepatitis D"],"a":2,"e":"Ans. is ''c'' i.e., Hepatitis C","pyqMatches":[{"year":"2014","no":806,"q":"Which flavivirus causes hepatitis in human ?","o":["Hepatitis A","Hepatitis B","Hepatitis C","Hepatitis D"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3471, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 215, '{"id":3471,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":215,"q":"Syncytium formation is a property of ?","o":["Herpes virus","Adenovirus","Measles virus","Rabies virus"],"a":2,"e":"Ans. is ''c'' i.e., Measles virus","pyqMatches":[{"year":"2014","no":818,"q":"Syncytium formation is a property of ?","o":["Herpes virus","Adenovirus","Measles virus","Rabies virus"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3472, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 216, '{"id":3472,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":216,"q":"Babesiosis is transmitted by ?","o":["Tick","Mites","Flea","Mosquito"],"a":0,"e":"Ans. is ''a'' i.e., Tick Babesia Babesiosis is a protozoan disease caused by two species of Babesia : Babesia microti and Babesia divergens. It is transmitted by Ioxdid tick. Babesia infects the RBCs and resides inside the RBCs ( intraerythrocytic). Intraerythrocytic infection of Babe​siosis is characterised by maltese cross. Maltese cross is a characteristic arrangement of parasites within the erythrocytes → Parasites within erythrocytes are arranged such that pointed ends of four parasites come in contact thereby giving a tetrad configuration resembling a maltese cross. Tetrad forms or ''Maltese cross'' appearance is considered pathognomic of Babesiosis. Clinically Babesiosis presents with chills, fever, mild hepatosplenomegaly, and mild hemolytic anemia. o Treatment includes Atovaquone plus azithromycin or quinine plus clindamycin. Babesiosis can easily be confused with P. falciparum malaria. Following two features distinguish Babesiosis from malaria :?","pyqMatches":[{"year":"2014","no":837,"q":"Babesiosis is transmitted by ?","o":["Tick","Mites","Flea","Mosquito"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3473, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 217, '{"id":3473,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":217,"q":"Pseudomonas exotoxin inhibits protein synthesis by inhibiting ?","o":["RNA polymerase","EF-2","Transpeptidase","Reverse transcriptase"],"a":1,"e":"Ans. is ''b'' i.e., EF-2 Exotoxin ''A'' of P. aeruginosa inhibits protein synthesis through interference with adenosine diphosphate ribosylation of elongation factor - 2. Remember Bacterial toxins inhibiting protein synthesis : Exotoxin A of P aeruginosa Shiga toxin (Shigella) Diphtheria toxin Shiga like toxin or verocytotoxin of EHEC.","pyqMatches":[{"year":"2014","no":768,"q":"Pseudomonas exotoxin inhibits protein synthesis by inhibiting ?","o":["RNA polymerase","EF-2","Transpeptidase","Reverse transcriptase"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3474, 'Microbiology', 'Bacteriology', 'Moderate', 'Microbiology', 218, '{"id":3474,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Moderate","source":"Microbiology","sourceNo":218,"q":"Triple iron sugar medium contains all, except ?","o":["Lactose","Sucrose","Glucose","Maltose"],"a":3,"e":"Ans. is d i.e., Maltose Triple sugar iron agar is used for the differentiation of microorganisms on the basis of :? i. Fermentation of dextrose (glucose), lactose and sucrose. i. Production of H2S. It is recommended for differentiation of enteric gram negative bacilli from clinical specimens, dairy samples and food products. Contents of the medium are :? i. Enzymatic digest of casein and animal tissue. i. Yeast enriched peptone. i. Three sugars : Dextrose (glucose), lactose and sucrose. v. Ferric ammonium citrate. v. Sodium chloride. i. Sodium thiosulfate. i. Phenol red. i. Agar. When carbohydrates are fermented, acid production is detected by the phenol red indicator, which is yellow in acid and red in alkaline conditions. Sodium thiosulfate is reduced to hydrogen sulfide (H2S) and H2S reacts with an iron salt yielding typical black iron sulfide. Ferric ammonium citrate is hydrogen sulfide indicator. Results Two areas of tube are examined : (i) Butt of the tube, and (ii) Slant of the tube. An alkaline slant (red)- acid butt (yellow) indicates fermentation of dextrose (glucose) only → red /yellow. Examples are Proteus mirabilis, salmonella thyphimurium and shigella flexneri. An acid slant (yellow) - acid butt (yellow) indicates fermentations of dextrose (glucose), lactose and/or sucrose → yellow/yellow. Example is E coli. An alkaline slant (red) - alkaline butt (red) indicates no fermentation (non-fermenter) → red/red. Example is Pseudomonas aeruginosa. An alkaline precipitate in butt indicates H2S production. It is produced by Proteus mirabilis and Salmonella typhimurium.","pyqMatches":[{"year":"2014","no":865,"q":"Triple iron sugar medium contains all, except ?","o":["Lactose","Sucrose","Glucose","Maltose"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3475, 'Microbiology', 'Bacteriology', 'Hard', 'Microbiology', 219, '{"id":3475,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Hard","source":"Microbiology","sourceNo":219,"q":"Fastest method for diagnosis of TB -","o":["Gene expert","LJ medium","TB MGIT","BAC, IEC"],"a":0,"e":"Ans. is ''a'' i.e., Gene expert GeneXpert MTB/RIF The Xpert MTB/RIF detects DNA sequences specific for Mycobacterium tuberculosis and rifampicin resistance by polymerase chain reaction. It is based on the Cepheid GeneXpert system, a platform for rapid and simple-to-use nucleic acid amplification tests (NAAT). The Xpert MTB/RIF purifies and concentrates Mycobacterium tuberculosis bacilli from sputum samples, isolates genomic material form the captured bacteria by sonication and subsequently amplifies the genomic DNA by PCR. The process identifies all the clinically relevant rifampicin resistance inducing mutations in the RNA polymerase beta (rpoB) gene in the mycobacterium tuberculosis genome in a real time format using fluorescent probes called molecular beacons. Results are obtained from unprocessed sputum samples in 90 minutes, with minimal biohazard and very little technical training required to operate.","pyqMatches":[{"year":"2014","no":761,"q":"Fastest method for diagnosis of TB","o":["Gene expert","LJ medium","TB MGIT","BAC, IEC"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3476, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 220, '{"id":3476,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":220,"q":"New York agar is used for ?","o":["Salmonella","Clostridia","Neisseria","Bacillus Anthracis"],"a":2,"e":"Ans. is ''c'' i.e., Neisseria New York City (NYC) medium is primarily designed for isolation of pathogenic Neisseria. It also supports the growth of genital mycoplasma (Mycoplasma hominis and Ureoplasma Urealyticum). It is useful in the diagnosis of gonorrhea and mycoplasma infection. It consists of primarily a peptone-corn starch agar-base buffered with phosphates and supplemented with horse plasma, horse hemoglobin, dextrose, yeast autolysate and antibiotics.","pyqMatches":[{"year":"2014","no":769,"q":"New York agar is used for ?","o":["Salmonella","Clostridia","Neisseria","Bacillus Anthracis"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3477, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 221, '{"id":3477,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":221,"q":"Acquire IgA deficiency may occur in ?","o":["Severe Congenital toxoplasmosis","Severe Measles infection","Severe Brucellosis","Severe Leptospirosis"],"a":0,"e":"Severe Congenital toxoplasmosis Block in B cell differentiation due to defective interaction between T and B cells. Naive B cells are not able to differentiate into IgA - producing cells.","pyqMatches":[{"year":"2014","no":885,"q":"Acquire IgA deficiency may occur in ?","o":["Severe Congenital toxoplasmosis","Severe Measles infection","Severe Brucellosis","Severe Leptospirosis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3478, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 222, '{"id":3478,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":222,"q":"Which of the following is a sexual spore ?","o":["Chlamydospore","Sporangiospore","Ascospore","Phialoconidia"],"a":2,"e":"Ans. is ''c'' i.e., Ascospore","pyqMatches":[{"year":"2014","no":844,"q":"Which of the following is a sexual spore ?","o":["Chlamydospore","Sporangiospore","Ascospore","Phialoconidia"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3479, 'Microbiology', 'Virology', 'Moderate', 'Microbiology', 223, '{"id":3479,"subject":"Microbiology","chapter":"Virology","difficulty":"Moderate","source":"Microbiology","sourceNo":223,"q":"True about Nipah virus are all except ?","o":["Is a paramyxovirus","Causes hemorrhagic fever","Emerging infection","Present in India"],"a":1,"e":"Ans. is ''b'' i.e., Causes hemorrhagic fever Nipah virus is an emerging infectious agent belongs to paramyxoviridae. It was first isolated in Malaysia in 1998, causing encephalitis in domestic pigs, with direct transmission from pigs to human. There have been Nipah virus infection outbreaks in pigs in Malaysia and Singapore and human disease in Malaysia, Singapore, India and Bangladesh. Typically the human infection presents as an encephalitis syndrome marked by fever headache, drowsiness, disorientation, mental confusion, coma and death.","pyqMatches":[{"year":"2014","no":819,"q":"True about Nipah virus are all except ?","o":["Is a paramyxovirus","Causes hemorrhagic fever","Emerging infection","Present in India"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3480, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 224, '{"id":3480,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":224,"q":"Defective hepatitis virus is ?","o":["HAV","HBV","HCV","HDV"],"a":3,"e":"Ans. is ''d'' i.e., HDV Hepatitis D (HDV) or Delta virus It is defective RNA virus dependent on the helper function of HBV for its replication and expression. It contains single stranded RNA (ssRNA) - Defective RNA. It has no independent existence and can survive and replicate only as long as HBV infection persists in the host. It resembles some plant viruses, such as viroids or satellite viruses. It has been classified in genus Deltavirus. Delta core of HDV is encapsidated by an outer envelope of HBs Ag, so it require cooperative function of HBV. Intracellular replication of HDV RNA can occur without HBV but liver injury requires the presence of HBV. HDV can cause two types of infection.","pyqMatches":[{"year":"2014","no":809,"q":"Defective hepatitis virus is ?","o":["HAV","HBV","HCV","HDV"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3481, 'Microbiology', 'Parasitology', 'Moderate', 'Microbiology', 225, '{"id":3481,"subject":"Microbiology","chapter":"Parasitology","difficulty":"Moderate","source":"Microbiology","sourceNo":225,"q":"The cystic form of all are seen in man except ?","o":["E.histolytica","Giardia","Trichomonas","Toxoplasma"],"a":2,"e":"Ans. is ''c'' i.e., Trichomonas Protozoal parasites have two phases. Cystic phase Trophozoite Cystic phase is not seen in : Trichomonas Entamoeba gingivalis Dientamoeba fragilis","pyqMatches":[{"year":"2014","no":843,"q":"The cystic form of all are seen in man except ?","o":["E.histolytica","Giardia","Trichomonas","Toxoplasma"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3482, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 226, '{"id":3482,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":226,"q":"Maternal mortality is more in ?","o":["HAV","HBV","HCV","HEV"],"a":3,"e":"Ans. is ''d'' i.e., HEV Hepatitis E virus Also known as enterically transmitted non-A non - B (NANB) virus or epidemic NANB. It is classified in the genus Herpesvirus under the family caliciviridae. It is a RNA virus with single - stranded positive sense RNA It is transmitted by fecal-oral route. In India, HEV is responsible for the majority of epidemic and sporadic hepatitis in adults. An epidemiological feature that distinguishes HEV from other enteric agents is the rarity of secondary person to person transmission (Secondary attack rate is very low 2-3% as against 10-20 % in HAV infection) A unique feature is the clinical severity and high case fatality rate of 20-40 % in pregnant women, especially in the last trimester of pregnancy. It is characteristically associated with cholestasis","pyqMatches":[{"year":"2014","no":810,"q":"Maternal mortality is more in ?","o":["HAV","HBV","HCV","HEV"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3483, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 227, '{"id":3483,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":227,"q":"Culture media used for 0157 : H7 Entero​‐ hemorrhagic E coli ?","o":["Sorbitol containing agar","Mannitol containing agar","Sucrose containing agar","Dextrose containing agar"],"a":0,"e":"Ans. is ''a'' i.e., Sorbitol containing agar Culture of 0157: H7 E.coli E.coli 0157:H7 is not identified on routine stool cultures. E.coli 0157:H7 can be specifically detected by the use of modified Mac Conkey media which containssorbitol in place of lactose (SMAC). Sorbitol Mac Conkey media is specifically useful for the detection of E.coli 0157:H7 as unlike most strains of E. coli, the 0157: H7 strain does not ferment sorbitol. Non fermenting colonies on a Sorbitol Mac Conkey plate (SMAC) therefore suggest the diagnosis of E.coli 0157:H7. Sorbitol Mac Conkey media is the screening method of choice for E.coli 0157:H7.","pyqMatches":[{"year":"2014","no":756,"q":"Culture media used for 0157 : H7 Entero​‐ hemorrhagic E coli ?","o":["Sorbitol containing agar","Mannitol containing agar","Sucrose containing agar","Dextrose containing agar"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3484, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 228, '{"id":3484,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":228,"q":"Liquid medium for tuberculosis ?","o":["LJ medium","Dorset medium","Loeffler''s medium","MGIT"],"a":3,"e":"Ans. is ''d'' i.e., MGIT Mycobacterial growth indicator tube (MGIT) is an automated liquid culture method. It contains 7 ml of modified Middle brook 7 H9 Broth base.","pyqMatches":[{"year":"2014","no":760,"q":"Liquid medium for tuberculosis ?","o":["LJ medium","Dorset medium","Loeffler''s medium","MGIT"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3485, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 229, '{"id":3485,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":229,"q":"Indicator used in MaConkey Agar ?","o":["Methylene blue","Methyl red","Neutral red","Bromothymol blue"],"a":2,"e":"Ans. is ''c'' i.e., Neutral red MacConkey agar is a selective medium for enteric gram negative bacilli. It is used to differentiate lactose fermenting enteric bacilli from lactose non-fermenters. Composition of MacConkey agar ? 1) Enzymatic digest of gelatin, casein and animal tissue : To provide nutrition. 2) Lactose : Fermentable carbohydrate. 3) Bile salts : Selective agent and inhibits gram positive organisms. 4) Crystal violet : Inhibits gram positive bacteria. 5) Sodium chloride : Supplies essential electrolytes and osmotic balance. 6) Neutral red : pH indicator (when lactose is fermented, the pH of medium decreases, changing color of neutral red to pink). 7) Agar : Solidifying agent.","pyqMatches":[{"year":"2014","no":866,"q":"Indicator used in MaConkey Agar ?","o":["Methylene blue","Methyl red","Neutral red","Bromothymol blue"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3486, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 230, '{"id":3486,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":230,"q":"Subterminal spores are seen in ?","o":["Cl perfringens","Cl tetani","Cl tertium","None"],"a":0,"e":"Ans. is ''a'' i.e., Cl perfringens","pyqMatches":[{"year":"2014","no":732,"q":"Subterminal spores are seen in ?","o":["Cl perfringens","Cl tetani","Cl tertium","None"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3487, 'Microbiology', 'Clinical Microbiology', 'Easy', 'Microbiology', 231, '{"id":3487,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":231,"q":"LGV (lymphogranuloma venerum) is caused by ?","o":["Treponema pallidum","Chlamydia trachomatis","Calymmatobacter granulomatosis","H Ducreyi"],"a":1,"e":"Ans. is ''b'' i.e., Chlamydia trachomatis Lymphogranuloma venereum (LGV) is a long-term (chronic) infection of the lymphatic system. It is caused by any of 3 different types (serovars) of the bacteria Chlamydia trachomatis. The bacteria are spread by sexual contact. The infection is not caused by the same bacteria that cause genital chlamydia. Chlamydia trachomatis causes eye (conjunctivitis, trachoma), respiratory (pneumonia), and genital tract (urethritis, lymphogranuloma venereum) infections. Diagnosis made with nucleic acid test for C trachomatis, LGV serovars diagnosed serologically.","pyqMatches":[{"year":"2014","no":772,"q":"LGV (lymphogranuloma venerum) is caused by ?","o":["Treponema pallidum","Chlamydia trachomatis","Calymmatobacter granulomatosis","H Ducreyi"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3488, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 232, '{"id":3488,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":232,"q":"Exanthema subitum is caused by ?","o":["HHV-6","HHV-8","Parvovirus","Coxsackievirus"],"a":0,"e":"Ans. is ''a'' i.e., HHV-6 HHV-6 causes roseola infantum (also called exanthema subitum or sixth disease).","pyqMatches":[{"year":"2012","no":1386,"q":"Exanthema subitum is caused by ?","o":["HHV","HPV","HIV","HCV"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":803,"q":"Exanthema subitum is caused by ?","o":["HHV-6","HHV-8","Parvovirus","Coxsackievirus"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3489, 'Microbiology', 'Miscellaneous', 'Moderate', 'Microbiology', 233, '{"id":3489,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Microbiology","sourceNo":233,"q":"Which is not parenterally transmitted","o":["HAV","HBV","HCV","HDV"],"a":0,"e":"Ans. is ''a'' i.e., HAV","pyqMatches":[{"year":"2014","no":808,"q":"Which is not parenterally transmitted","o":["HAV","HBV","HCV","HDV"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3490, 'Microbiology', 'Mycology', 'Moderate', 'Microbiology', 234, '{"id":3490,"subject":"Microbiology","chapter":"Mycology","difficulty":"Moderate","source":"Microbiology","sourceNo":234,"q":"True about cryptococcus are all except","o":["Primarily infects lung","Urease negative","India-ink is used","All are true"],"a":1,"e":"Ans. is `b i.e., Urease negative CRYPTOCOCCUS NEOFORMANS The only pathogenic yeast Four capsular serotypes - A, B, C and D It has polysaccharide capsule Most infections in immunocompromized patients are caused by serotype A. Pigeon droppings commonly contains serotype A and D. Eucalyptus tree contain serotype B. It is urease positive. Mode of transmission By inhalation of the fungus into the lung (most common) Through skin or mucosa (some times).","pyqMatches":[{"year":"2014","no":845,"q":"True about cryptococcus are all except","o":["Primarily infects lung","Urease negative","India-ink is used","All are true"],"a":1,"source":"NEET_2014_Paper.pdf"},{"year":"2016","no":767,"q":"True about cryptococcus are all except","o":["Primarily infects lung","Urease negative","India-ink is used","All are true"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2014","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3491, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 235, '{"id":3491,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":235,"q":"Which vaccine can cause adverse effects in persons with allergy to egg ?","o":["Measles","Rubella","Rabies","Mumps"],"a":2,"e":"Ans. is ''c'' i.e., Rabies Duck embryo Vaccine has less neuroparalytic complications, but can cause allergic reactions. Persons allergic to eggs, should not be given this vaccine. Rabies Vaccine Rabies vaccines are fluid or dried prepration of fixed virus grown in the neural tissues of rabbits, sheep, goats, mice or rats or in embryonated ducks egg or in cell cultures. Inactivation of virus is commonly done by treatment with formalin or","pyqMatches":[{"year":"2014","no":890,"q":"Which vaccine can cause adverse effects in persons with allergy to egg ?","o":["Measles","Rubella","Rabies","Mumps"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3492, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 236, '{"id":3492,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":236,"q":"Salmonellae other than S typhi and S paratyphi cause ?","o":["Typhoid fever","Enteric fever","Gastroenteritis","All of the above"],"a":2,"e":"Ans. is ''c'' i.e., Gastroenteritis SALMONELLOSIS Salmonellosis is referred to the infection caused by bacteria of genus salmonella. Salmonellosis is of two types?","pyqMatches":[{"year":"2014","no":745,"q":"Salmonellae other than S typhi and S paratyphi cause ?","o":["Typhoid fever","Enteric fever","Gastroenteritis","All of the above"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3493, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 237, '{"id":3493,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":237,"q":"Optimal percentage of NaCI for V cholerae ?","o":["1%","2%","3%","4%"],"a":0,"e":"Ans. is ''a'' i.e., 1%","pyqMatches":[{"year":"2014","no":748,"q":"Optimal percentage of NaCI for V cholerae ?","o":["1%","2%","3%","4%"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3494, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 238, '{"id":3494,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":238,"q":"Waterhouse-Friderichsen syndrome is seen in ?","o":["Pneumococci","N. meningitidis","Pseudomonas","Yersinia"],"a":1,"e":"Ans. is ''b'' i.e., N. meningitidis Waterhouse–Friderichsen syndrome (WFS) is defined as adrenal gland failure due to bleeding into the adrenal glands, commonly caused by a severe bacterial infection. Typically, it is caused by Neisseria meningitides. The bacterial infection leads to massive bleeding into one or (usually) both adrenal glands. Fulminant meningococcemia (purpura fulminans or Waterhouse - Friderichsen syndrome) is the most rapidly lethal form of septic shock experienced by humans. It differs from most other forms of septic shock by the prominence of hemorrhagic skin lesions (petechiae, purpura) and the consistent development of DIC.","pyqMatches":[{"year":"2013","no":750,"q":"Waterhouse-Friderichsen syndrome is seen in ?","o":["Pneumococci","N. meningitidis","Pseudomonas","Yersinia"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":774,"q":"Waterhouse-Friderichsen syndrome is seen in ?","o":["Pneumococci","N. meningitidis","Pseudomonas","Yersinia"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3495, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 239, '{"id":3495,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":239,"q":"Causative organism of SARS","o":["HiN,","Corona virus","Rotavirus","RSV"],"a":1,"e":"Ans. is ''b'' i.e., Corona virus Severe acute respiratory syndrome In November 2002, China experienced an outbreak of an unusual respiratory infection with many deaths Severe acute respiratory syndrome (SARS). o It is caused by Corona virus type – 4. SARS spreads by inhalation of the virus present in droplets or aerosols of respiratory secretions of patients. Fecal aerosols may also be infectious. o Incubation period is less than 10 days.","pyqMatches":[{"year":"2014","no":820,"q":"Causative organism of SARS","o":["HiN,","Corona virus","Rotavirus","RSV"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3496, 'Microbiology', 'Bacteriology', 'Moderate', 'Microbiology', 240, '{"id":3496,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Moderate","source":"Microbiology","sourceNo":240,"q":"Weil felix reaction is heterophile antibodies reaction due sharing of Rickettsial antigen with","o":["Shigella","Proteus","Chlamydia","Mycoplasma"],"a":1,"e":"Ans. is ''b'' i.e., Proteus Weil felix reaction This reaction is an agglutination test in which sera are tested for agglutinins to 0 antigens of certain nonmotile proteus strains OX -19, OX - 2 and OX - K. The basis of the test is the sharing of an alkali - stable carbohydrate antigen by some rickettsiae and by certain strains of proteus, P. vulgaris OX - 19 and OX - 2 and P. mirabilis OX - K. The test is usually done as a tube agglutination, though rapid slide agglutination methods have been employed for screening","pyqMatches":[{"year":"2014","no":775,"q":"Weil felix reaction is heterophile antibodies reaction due sharing of Rickettsial antigen with","o":["Shigella","Proteus","Chlamydia","Mycoplasma"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3497, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 241, '{"id":3497,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":241,"q":"Neutrilization test is","o":["Widal test","Weil-Felix test","Paul Bunnel test","Nagler reaction"],"a":3,"e":"Ans. is `d'' i.e., Nagler reaction Neutralization reaction When antibody reacts with a toxin or other biologically active antigen, it may neutralize the effect of toxin or antigen. This ability to used in neutralization test. Neutralization tests are of two types","pyqMatches":[{"year":"2014","no":886,"q":"Neutrilization test is","o":["Widal test","Weil-Felix test","Paul Bunnel test","Nagler reaction"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3498, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 242, '{"id":3498,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":242,"q":"Mode of transmission of Listeria","o":["Ingestion","Inhalation","Skin inoculation","None"],"a":0,"e":"Ans. is ''a'' i.e., Ingestion LISTERIOSIS Mode of transmission; Foodborne → Most common (most cases are due to serotype 4b) Nosocomial → In late-onset neonatal infection. L monocytogenes enters the body through the gastrointestinal tract after ingestion of contaminated foods such as cheese, fruit, or vegetables. The organism has several adhesion proteins (Ami (an autolysin amidase), Fbp A (fibronectin binding protein), and flagellin proteins) that facilitate bacterial binding to the host cells and that contribute to virulence. Iron is an important virulence factor. Listeria produces siderophores and is able to obtain iron from transferrin.","pyqMatches":[{"year":"2014","no":776,"q":"Mode of transmission of Listeria","o":["Ingestion","Inhalation","Skin inoculation","None"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3499, 'Microbiology', 'Clinical Microbiology', 'Easy', 'Microbiology', 243, '{"id":3499,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":243,"q":"Frisch bacillus affects most commonly","o":["Mouth","Nose","Eye","Ear"],"a":1,"e":"Ans. is ''b'' i.e., Nose Frisch bacillus is Klebsiella rhinoscleromatis, which causes rhinoscleroma, a granulomatous disease of the nose. K pneumoniae subspecies rhinoscleromatis form rhinoscleroma, a destructive granuloma of the nose and pharynx. Klebsiella granulomatis (formerly Calymmatobacterium granulomatis) causes a chronic genital ulcerative disease, granuloma inguinale, an uncommon sexually transmitted disease","pyqMatches":[{"year":"2014","no":777,"q":"Frisch bacillus affects most commonly","o":["Mouth","Nose","Eye","Ear"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3500, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 244, '{"id":3500,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":244,"q":"Scarlet fever is caused by","o":["Streptococcus agalactie","Streptococcus pyogenes","Streptococcus pneumoniae","Streptococcus equisimilus"],"a":1,"e":"Ans. is ''b'' i.e., Streptococcus pyogenes Infections caused by streptococcus pyogenes Scarlet fever consists of streptococcal pharyngitis, accompanied by a characteristic rash which has a tiny red pinpoint appearance with sand-paper like texture. It occurs due to production of erythrogenic toxin Respiratory infections Sore throat is the most common of streptococcal disease. It may be localised as tonsillitis as in older children and adults or it may involve the pharynx more diffusely (pharyngitis) as in younger children. Otitis media.","pyqMatches":[{"year":"2014","no":738,"q":"Scarlet fever is caused by","o":["Streptococcus agalactie","Streptococcus pyogenes","Streptococcus pneumoniae","Streptococcus equisimilus"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3501, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 245, '{"id":3501,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":245,"q":"E antigen (HBeAg) of hepatitis B virus is a product of which gene","o":["S","C","p","x"],"a":1,"e":"Ans. is ''b'' i.e., C Genes & gene products The genome of HBV is made of circular DNA, but it is unusual because the DNA is not fully double stranded --> one of the strands is incomplete and other is complete → partially double stranded DNA. There are four known genes encoded by genome —› ''C'' , X'', `P'' ,''S''.","pyqMatches":[{"year":"2014","no":811,"q":"E antigen (HBeAg) of hepatitis B virus is a product of which gene","o":["S","C","p","x"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3502, 'Microbiology', 'Miscellaneous', 'Hard', 'Microbiology', 246, '{"id":3502,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Hard","source":"Microbiology","sourceNo":246,"q":"Which type of pulmonary TB is most likely to give sputum positive ?","o":["Fibronodular","Pleural effusion","Cavitary","None"],"a":2,"e":"Ans. is ''c'' i.e., Cavitary Sputum smears are usually positive in patients with laryngeal TB, endobronchial TB and cavitary pulmonary TB\" — Kelley ''s \"Patients with cavitary pulmonary TB have high bacterial load in their sputum\" — Internet","pyqMatches":[{"year":"2014","no":762,"q":"Which type of pulmonary TB is most likely to give sputum positive ?","o":["Fibronodular","Pleural effusion","Cavitary","None"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3503, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 247, '{"id":3503,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":247,"q":"Most halophilic vibrio ?","o":["V cholerae","V vulnificus","V alginolyticus","V parahemolyticus"],"a":2,"e":"Ans. is ''c'' i.e., V alginolyticus V alginolyticus is most salt tolerant (most halophilic) species of vibrio.","pyqMatches":[{"year":"2014","no":750,"q":"Most halophilic vibrio ?","o":["V cholerae","V vulnificus","V alginolyticus","V parahemolyticus"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3504, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 248, '{"id":3504,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":248,"q":"Bile esculin agar is used for ?","o":["Group A streptococcus","Group B streptococcus","Group C streptococcus","Enterococcus"],"a":3,"e":"Ans. is ''d'' i.e., Enterococcus Enterococcus Majority of the infections are caused by E. faecalis and E. faecium. Less frequently isolated species are E. gallinarum, E. durans, E. hirae and E. avium. Enterococci are normal inhabitants of the large bowel of human adults, although they usually make up < 1% of the culturable intestinal microflora. They are catalase negative (as all streptococci). Their characteristic feature is that they can grow in presence of :?","pyqMatches":[{"year":"2014","no":778,"q":"Bile esculin agar is used for ?","o":["Group A streptococcus","Group B streptococcus","Group C streptococcus","Enterococcus"],"a":3,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":751,"q":"Bile esculin agar is used for ?","o":["Group A streptococcus","Group B streptococcus","Group C streptococcus","Enterococcus"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3505, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 249, '{"id":3505,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":249,"q":"Tachyzoites are seen in ?","o":["Toxoplasma","Toxocara","Pulmonary eosinophilia","Ascaris"],"a":0,"e":"Ans. is ''a'' i.e., Toxoplasma Toxoplasmosis is the disease caused by infection with the obligate intracellular parasite Toxoplasma gondii. There are two distinct stages in the life cycle of T gondii :? Nonfeline stage In this stage tissue cysts (containg bradyzoites) or sporulated oocysts are ingested by intermediate hosts (Human, mouse, sheep or pig). The cyst is rapidly digested by the acidic-pH gastric secretion releasing bradyzoites or sporozoites. These bradyzoites or sporozoites enter the small - intestinal epithelium and tranform into rapidly dividing tachyzoites (endozoites). The tachyzoites can infect and replicate in all mammalian cells except red blood cells. Tissue cysts containing many bradyzoite develop 7-10 days after systemic tachyzoite infection. These tissue cysts occur in a variety of host organs but persist principally within the CNS and muscle. Feline stage (sexual stage) This stage takes place in the definitive host (cat) This cycle is associated with formation of oocysts, which are excreted in cat feces. Mature oocysts contain 2 sporocysts, each with 4 sporozoites. The formation of tissue cysts in cats constitutes the other part of feline cycle.","pyqMatches":[{"year":"2014","no":841,"q":"Tachyzoites are seen in ?","o":["Toxoplasma","Toxocara","Pulmonary eosinophilia","Ascaris"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3506, 'Microbiology', 'Parasitology', 'Hard', 'Microbiology', 250, '{"id":3506,"subject":"Microbiology","chapter":"Parasitology","difficulty":"Hard","source":"Microbiology","sourceNo":250,"q":"A patient presents with headache, high fever and meningismus. Within 3 days he becomes unconscious. Most probable causative agent ?","o":["Naegleria fowleri","Acanthamoeba castellani","Entamoeba histolytica","Trypanosoma cruzi"],"a":0,"e":"Ans. is ''a'' i.e., Naegleria fowleri Amongst the given options Naeglaria and Acanthamoeba cause amoebic encephalitis. \"The prognosis of Naeglaria encephalitis is uniformaly poor, most patients die within a week\". \"Acanthamoeba encephalitis follows a more indolent course\".","pyqMatches":[{"year":"2014","no":840,"q":"A patient presents with headache, high fever and meningismus. Within 3 days he becomes unconscious. Most probable causative agent ?","o":["Naegleria fowleri","Acanthamoeba castellani","Entamoeba histolytica","Trypanosoma cruzi"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3507, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 251, '{"id":3507,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":251,"q":"DNA polymerase of HBV is encoded by which of the following ?","o":["S gene","C gene","P gene","X gene"],"a":2,"e":"Ans. is `c'' i.e., P gene DNA polymerase of HBV is encoded by P gene","pyqMatches":[{"year":"2014","no":812,"q":"DNA polymerase of HBV is encoded by which of the following ?","o":["S gene","C gene","P gene","X gene"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3508, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 252, '{"id":3508,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":252,"q":"Heat labile liquids are sterilized by ?","o":["Hot air oven","Autoclaving","Membrane filter","Moist heat"],"a":2,"e":"Ans. is ''c'' i.e., Membrane filter Filters are used to sterilize heat-labile solutions. Membrane filters are used to sterilize pharmaceutical substances, ophthalmic solutions, liquid culture media, oils, antibiotics and other heat sensitive solutions.","pyqMatches":[{"year":"2014","no":856,"q":"Heat labile liquids are sterilized by ?","o":["Hot air oven","Autoclaving","Membrane filter","Moist heat"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3509, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 253, '{"id":3509,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":253,"q":"Rideal-Walker coefficient is related with ?","o":["Disinfecting power","Parasitic clearance","Dietary requirement","Statistical correlation"],"a":0,"e":"Ans. is ''a'' i.e., Disinfecting power Traditional testing of disinfectants Two traditional tests for determining the efficiency of disinfectants are :? 1) Rideal-Walker test : Phenol is taken as the standard with unit as phenol coefficient (pheno1=1) 2) Chick-Martin test : The disinfectant acts in the presence of organic matter (dried yeast or feces).","pyqMatches":[{"year":"2014","no":860,"q":"Rideal-Walker coefficient is related with ?","o":["Disinfecting power","Parasitic clearance","Dietary requirement","Statistical correlation"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3510, 'Microbiology', 'Miscellaneous', 'Hard', 'Microbiology', 254, '{"id":3510,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Hard","source":"Microbiology","sourceNo":254,"q":"A patient presents with fever. Peripheral smears shows band across the erythrocytes. Diagnosis is ?","o":["P Falciparum","P vivax","P ovate","P malariae"],"a":3,"e":"Ans. is ''d'' i.e., P malariae Band across erythrocytes (band-form trophozoites) is characteristic of P malariae.","pyqMatches":[{"year":"2014","no":834,"q":"A patient presents with fever. Peripheral smears shows band across the erythrocytes. Diagnosis is ?","o":["P Falciparum","P vivax","P ovate","P malariae"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3511, 'Microbiology', 'Bacteriology', 'Moderate', 'Microbiology', 255, '{"id":3511,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Moderate","source":"Microbiology","sourceNo":255,"q":"Rash is not caused by ?","o":["Salmonella","Shigella","Meningococci","Staphylococcus"],"a":1,"e":"Ans. is ''b'' i.e., Shigella Salmonella (typhoid) and meningococci cause morbiliform rash. Staphylococcus causes scarlentiform rash in TS S and SSSS. Infections causing Exanthems (acute generalized rash) Morbilliform Viral : Measles (rubeola), rubella, erythema infectiosum, EBV, CMV, adenovirus, echovirus, early HIV, coxasackie virus. Bacterial : Typhoid, Early secondary syphiis, Early rickettsia, Early meningoccemia. Scarlentiform Scarlet fever (streptococcus). Toxic shock syndrome. Staphylococcal scalded skin syndrome.","pyqMatches":[{"year":"2014","no":779,"q":"Rash is not caused by ?","o":["Salmonella","Shigella","Meningococci","Staphylococcus"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3512, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 256, '{"id":3512,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":256,"q":"Owl eye intranuclear inclusion body is seen in ?","o":["Herpes zoster","Herpes simplex","CMV","EBV"],"a":2,"e":"Ans. is ''c'' i.e., CMV CYTOMEGALOVIRUS (CMV) Also known as salivary gland virus CMV is the largest virus amongst herpes viruses They are characterized by enlargment of infected cells (cytomegalic cells) and intranuclear inclusions. Intranuclear inclusion is eccentrically placed and is surrounded by a halo - owl''s eye appearance Once infected an individual carries CMV for life CMV is the most common organism causing intrauterine infection. CMV is the most common pathogen complicating organ transplantation.","pyqMatches":[{"year":"2014","no":831,"q":"Owl eye intranuclear inclusion body is seen in ?","o":["Herpes zoster","Herpes simplex","CMV","EBV"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3513, 'Microbiology', 'Parasitology', 'Easy', 'Microbiology', 257, '{"id":3513,"subject":"Microbiology","chapter":"Parasitology","difficulty":"Easy","source":"Microbiology","sourceNo":257,"q":"Parasites for which modified ZN stain is used ?","o":["Isospora","Microsporidia","Plasmodium","Echinococcus"],"a":0,"e":"Ans. is ''a'' i.e., Isospora","pyqMatches":[{"year":"2014","no":833,"q":"Parasites for which modified ZN stain is used ?","o":["Isospora","Microsporidia","Plasmodium","Echinococcus"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3514, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 258, '{"id":3514,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":258,"q":"Most common complication of chicken- pox -","o":["Bacterial infection","Meningitis","Pneumonia","Nephritis"],"a":0,"e":"Ans. is ''a'' i.e., Bacterial infection Complications of chicken pox The most common infectious complication of varicella is secondary bacterial superinfection of the skin, which is usually caused by streptococcus pyogenes or Staphylococcus aureus. The most common extracutaneous site of involvement in children is CNS. Varicella pneumonia is the most serious complication following chickenpox in adults.","pyqMatches":[{"year":"2014","no":800,"q":"Most common complication of chicken- pox","o":["Bacterial infection","Meningitis","Pneumonia","Nephritis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3515, 'Microbiology', 'Bacteriology', 'Moderate', 'Microbiology', 259, '{"id":3515,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Moderate","source":"Microbiology","sourceNo":259,"q":"Man had uncooked meat at dinner 3 days back, Now presenting with diarrhea. Stool examination shows coma shaped organism with RBC and WBC. Causative organism is ?","o":["Vibrio cholerae","Shigella","Campylobacter jejuni","Yersinia enterocolitia"],"a":2,"e":"Ans. is ''c'' i.e., Campylobacter jejuni This is a case of dysentery (RBC in stools along with WBC). Among the given options, ''b'', ''c'' and ''d'' can cause dysentery. But, coma shaped organism is campylobactor jejuni. Based on the depth of intestinal invasion, there are different clinical manifestations of infection with organisms causing diarrhea:- No cell invesion (noninflammatory) The bacteria bind to intestinal epithelial cells but do not enter the cell. Diarrhea is caused by the release of enterotoxins. Watery diarrhea with no fecal leukocytes and no systemic symptoms (e.g. fever) occurs. Organisms are :","pyqMatches":[{"year":"2014","no":781,"q":"Man had uncooked meat at dinner 3 days back, Now presenting with diarrhea. Stool examination shows coma shaped organism with RBC and WBC. Causative organism is ?","o":["Vibrio cholerae","Shigella","Campylobacter jejuni","Yersinia enterocolitia"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3516, 'Microbiology', 'Clinical Microbiology', 'Easy', 'Microbiology', 260, '{"id":3516,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":260,"q":"E coli causing hemolytic uremic syndrome ?","o":["Enteropathogenic","Enterotoxigenic","Enteroinvasive","Enterohemorrhagic"],"a":3,"e":"Ans. is ''d'' i.e., Enterohemorrhagic SCHERICHIA COLI At least six distinct \"pathotypes\" of intestinal pathogenic E. coli exist : Enteropathogenic E. coli lEnteroadherent E. colil It causes diarrhoea in infants and children usually occuring as institutional out breaks. It does not produce enterotoxin, nor are they invasive. They adhere to the mucosa of small intestine and cause disruption of the brush border microvilli. These strains can be identified by their adhesion to HEP - 2 cells. Enterotoxigenic E. coli It causes traveller''s diarrhoea [ETEC is the most common cause of traveller''s diarrhea!. It produces enterotoxins. They can produce heat labile toxin (LT) or heat stable toxin or both. Toxin production alone may not lead to illness. The strain should first be able to adhere to intestinal mucosa. This adhesiveness is medicated by fimbrial or colonisation factor antigen (CFA). Enteroinvasive E. coli They themselves resemble shigella and their infection resembles shigellosis (remember : shiga like toxin is elaborated by enterohemorrhagic E. coli). They produce mild diarrhoea to frank dysentry and occur in adult as well as in children. They have been termed enteroinvasive because they have the capacity to invade intestinal epithelial cells in vivo and penetrate HeLa or HEP - 2 cells in tissue culture. This ability of penetration is plasmid determined which codes for outer membrane antigens called the ''virulence marker antigen'' (VMA). The detection of plasmid can be diagnostic. For laboratory diagnosis of EIEC, the sereny test used to be employed. These strains are non motile, do not ferment lactose or ferment it late with acid without producing any gas. Enterohemorrhagic E. coli or verotoxigenic E. coli These strains produce verocytotoxin (VT) or shiga like toxin (SLT) They can cause mild diarrhoea to fatal hemorrhagic colitis. Shiga like toxin belongs to class ribosome inactivating proteins (RIPs). It inhibits protein synthesis by inhibiting ribosomal function. This toxin also acts on vascular endothelium to promote the synthesis of coagulation factor VIII, vWF -* Platelet aggregation. They can cause hemolytic uremic syndrome particularly in young children and the elderly. 0 157 : H 7 is the most prominent serotype of EHEC, associated with HUS, but 06, 026, 055, 091, 0103, 0111, 0113 and OX3 have also been associated with this syndrome. The primary target for VT is vascular endothelium. The typical EHEC is serotype 0157: H7 which does not ferement sorbital unlike majority of E. coli (but Harrison writes that few species of this serotype can ferment sorbital). Some other serotype like 026 : H1 also belongs to this group. Laboratory diagnosis of VIEC diarrhea is established by demonstration of the bacilli or VT in feces directly or in culture.","pyqMatches":[{"year":"2014","no":757,"q":"E coli causing hemolytic uremic syndrome ?","o":["Enteropathogenic","Enterotoxigenic","Enteroinvasive","Enterohemorrhagic"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3517, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 261, '{"id":3517,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":261,"q":"KOH wet mount is prepared for ?","o":["Herpes Zoster","Candida","Gonorrhea","Trichomonas vaginalis"],"a":1,"e":"Ans. is ''b'' i.e., Candida","pyqMatches":[{"year":"2014","no":847,"q":"KOH wet mount is prepared for ?","o":["Herpes Zoster","Candida","Gonorrhea","Trichomonas vaginalis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3518, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 262, '{"id":3518,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":262,"q":"Oncogenic DNA virus is ?","o":["Retrovirus","HBV","HIV","HTLV"],"a":1,"e":"Ans. is ''b'' i.e., HBV","pyqMatches":[{"year":"2014","no":822,"q":"Oncogenic DNA virus is ?","o":["Retrovirus","HBV","HIV","HTLV"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3519, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 263, '{"id":3519,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":263,"q":"Band form of P malariae is ?","o":["Schizoint stage","Trophozoite stage","Merozoite stage","Gametocyte stage"],"a":1,"e":"Ans. is ''b'' i.e., Trophozoite stage","pyqMatches":[{"year":"2014","no":835,"q":"Band form of P malariae is ?","o":["Schizoint stage","Trophozoite stage","Merozoite stage","Gametocyte stage"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3520, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 264, '{"id":3520,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":264,"q":"Bifringence polarization microscopy is used for ?","o":["Flagella","Intracellular structures","Capsule","Spores"],"a":1,"e":"Ans. is `b'' i.e., Intracellular structures Polarization microscope enables the study of intracellular structure using differences in bifringence.","pyqMatches":[{"year":"2014","no":873,"q":"Bifringence polarization microscopy is used for ?","o":["Flagella","Intracellular structures","Capsule","Spores"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3521, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 265, '{"id":3521,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":265,"q":"Most common cause of infection due to catheter in urinary tract ?","o":["E coli","Coagulase negative staphylococci","Staph aureus","Pseudomonas"],"a":0,"e":"Ans. is ''a'' i.e., E coli \"E coli cause 80% of acute UTI in patients without catheterization\". \"E. coil is the most common cause of catheter associated UTI too\".","pyqMatches":[{"year":"2014","no":780,"q":"Most common cause of infection due to catheter in urinary tract ?","o":["E coli","Coagulase negative staphylococci","Staph aureus","Pseudomonas"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3522, 'Microbiology', 'Mycology', 'Easy', 'Microbiology', 266, '{"id":3522,"subject":"Microbiology","chapter":"Mycology","difficulty":"Easy","source":"Microbiology","sourceNo":266,"q":"Which of the following fungi is/are difficult to isolate culture ?","o":["Candida","Dermatophytes","Cryptococcus","Malassezia furfur"],"a":3,"e":"Ans. is ''D'' i.e., Malassezia furfur Malassezia furfur does not grow on regular sabouraud''s medium. It requires complex media to grow M. furfur is a lipid dependent fungus and 1% emulsified olive oil is added to sabouraud medium for its cultivation Two media are now widely employed for all malassezia species.","pyqMatches":[{"year":"2014","no":846,"q":"Which of the following fungi is/are difficult to isolate culture ?","o":["Candida","Dermatophytes","Cryptococcus","Malassezia furfur"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3523, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 267, '{"id":3523,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":267,"q":"Window period in HIV infection ?","o":["1-2 weeks","4-8 weeks","8-12 weeks","> 12 weeks"],"a":1,"e":"Ans. is ''b '' i.e., 4-8 weeks Window period It takes 2-8 weeks to months for antibodies to appear after infection. This period, from infection to appearance of antibodies, is called as window period. During this period patients is seronegative i.e. serological tests (ELISA and Western blot) are negative. o The individual may be highly infectious during this period.","pyqMatches":[{"year":"2014","no":823,"q":"Window period in HIV infection ?","o":["1-2 weeks","4-8 weeks","8-12 weeks","> 12 weeks"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3524, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 268, '{"id":3524,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":268,"q":"Thermophile bacteria grow at ?","o":["20°C","20-40° C","40-60°C","60-80°C"],"a":3,"e":"Ans. is ''d'' i.e., 60-80° C Temperature requirement of bacteria Bacteria vary in their requirements of temprature for growth.","pyqMatches":[{"year":"2014","no":874,"q":"Thermophile bacteria grow at ?","o":["20°C","20-40° C","40-60°C","60-80°C"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3525, 'Microbiology', 'Virology', 'Moderate', 'Microbiology', 269, '{"id":3525,"subject":"Microbiology","chapter":"Virology","difficulty":"Moderate","source":"Microbiology","sourceNo":269,"q":"Which of the following is not a pox virus?","o":["Cow pox","Molluscum contagiosum","Small pox","Chicken pox"],"a":3,"e":"Ans. is ''d'' i.e., Chicken pox Poxviruses causing disease in humans Variola (small pox) Buffalopox Cowpox Molluscum contagiosum Vaccinia Monkeypox Orf Tanapox Chicken pox is caused by varicella - zoster virus, which is a herpes virus.","pyqMatches":[{"year":"2014","no":793,"q":"Which of the following is not a pox virus?","o":["Cow pox","Molluscum contagiosum","Small pox","Chicken pox"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3526, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 270, '{"id":3526,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":270,"q":"Metachromatic granules are seen in ?","o":["Gardenella vaginali","Corynebacteria","Argobacterim","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above Polvpmetahosphate / volutin granules Some bacteria contain granules composed of polymetaphosphate. They were first described in spirillum volutans, so they were called as Volutin granules. These granules are also known as Babes Ernst granules or polar bodies or metachromatic granules. These granules stain reddish violet with methylene blue or toluidine blue. These granules are strongly basophilic. In the granules, there is stored phosphate in the form of linear chains of inorganic phosphate. These granules represent intracellular phosphate reserve when nucleic acid syntheis does not occur. The phosphate is incorporated into nucleic acid during the synthesis of the latter. When nucleic acid synthesis is prevented by starvation , the granules accumulate in the cytoplasm. So, volutin metachromatic granules are most frequent in cells grown under conditions of nutritional deficiency (starvation) and tend to disappear when the deficient nutrients are supplied. Volutin metachromatic granules are common in - i. Corynebacteria diptheriae i. Gardenella vaginalis i. Agrobacterim tumefaciens v. Mycobacteria v. Spirillum voluants","pyqMatches":[{"year":"2014","no":872,"q":"Metachromatic granules are seen in ?","o":["Gardenella vaginali","Corynebacteria","Argobacterim","All of the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3527, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 271, '{"id":3527,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":271,"q":"Which of the following is incubated at temperature 40-44 degrees ?","o":["Vibrio cholerae","Pseudomonas aeruginosa","Vibrio parahemolyticus","E coli"],"a":1,"e":"Ans. is ''b'' i.e., Pseudomonas aeruginosa \"The optimum temperature for growth of pseudomonas aeruginosa is 37 degree and is able to grow at temperature as high as 42° C\" - Essentials of Microbiology Pseudomonas aeruginosa Morphology Gram negative bacilli Motile by polar flagellum Non capsulated but many strains have mucoid slim layer especially the organisms which are isolated from cystic fibrosis patient. Culture Obligate aerobe Colonies emit a distinctive, musty, mawkish, earthy or sweet grape- like odour or corn tocolike odour. Cetrimide agar is a selective media. Pseudomonas aeruginosa produces a numbers of pigments. The production of these pigments accounts for the colour of colonies. Pyocyanin is produced only by P.aeruginosa and it inhibits the growth of many other bacteria. Pyoverdin may be produced by many other species.","pyqMatches":[{"year":"2014","no":790,"q":"Which of the following is incubated at temperature 40-44 degrees ?","o":["Vibrio cholerae","Pseudomonas aeruginosa","Vibrio parahemolyticus","E coli"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3528, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 272, '{"id":3528,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":272,"q":"Transmission of cholera is through ?","o":["Fecally contaminated food","Fecally contaminated water","Contaminated food by vomits of a case","All of the above"],"a":3,"e":"Man is the only reservoir. The immediate source of infection are the stools and vomits of cases and carrier. Infection is acquired through fecally contaminated water or food. Chlorination of water is effective against V cholerae. There are following tyes of carrier in cholera. i) Incubatory : Shed vibrios only in the brief incubation period of 1-5 days. ii) Convalescent : Shed vibrios for 2-3 weeks. iii) Healthy or contact carrier : Has had subclinical infection and shed vibrios for less than 10 days. iv) Chronic carriers : Can shed vibrios for months or years and may have persistent infection in gall bladder.","pyqMatches":[{"year":"2014","no":749,"q":"Transmission of cholera is through ?","o":["Fecally contaminated food","Fecally contaminated water","Contaminated food by vomits of a case","All of the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3529, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 273, '{"id":3529,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":273,"q":"Reservoir of plague is ?","o":["Domestic rat","Wild rat","Rat flea","Man"],"a":1,"e":"Ans. is ''b'' i.e., Wild rat","pyqMatches":[{"year":"2014","no":782,"q":"Reservoir of plague is ?","o":["Domestic rat","Wild rat","Rat flea","Man"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3530, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 274, '{"id":3530,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":274,"q":"IgE binds to which cell ?","o":["T cells","B cells","Mast cells","NK cells"],"a":2,"e":"IgE binds to Mast cells and basophils, and mediate Type I hypersensitivity.","pyqMatches":[{"year":"2014","no":887,"q":"IgE binds to which cell ?","o":["T cells","B cells","Mast cells","NK cells"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3531, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 275, '{"id":3531,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":275,"q":"Wrong statement about chicken pox/ herpes zoster?","o":["Caused by VZV","Chicken-pox primary infection","Herpes-zoster recurrent infection","Latent infection in trigeminal ganglion"],"a":2,"e":"Ans. is ''c'' i.e., Herpes-Zoster recurrent infection Herpes-Zoster is due to reactivation of latent infection (not due to recurrent infection). Other options are correct.","pyqMatches":[{"year":"2014","no":799,"q":"Wrong statement about chicken pox/ herpes zoster?","o":["Caused by VZV","Chicken-pox primary infection","Herpes-zoster recurrent infection","Latent infection in trigeminal ganglion"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3532, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 276, '{"id":3532,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":276,"q":"Sterols are found in ?","o":["Cell wall of Ricketssia","Cell membrane of Ricketssia","Cell wall of Mycoplasma","Cell membrane of Mycoplasma"],"a":3,"e":"Ans. is ''d'' i.e., Cell membrane of Mycoplasma Mycoplasma lack cell wall. They are bounded by triple layered unit membrane that contains sterol. o Thus they require cholesterole and related sterols.","pyqMatches":[{"year":"2014","no":783,"q":"Sterols are found in ?","o":["Cell wall of Ricketssia","Cell membrane of Ricketssia","Cell wall of Mycoplasma","Cell membrane of Mycoplasma"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3533, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 277, '{"id":3533,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":277,"q":"Double zone of hemolysis is seen in ?","o":["Staphylococcus areus","Streptococcus pyogenes","Clostridium perfringens","Corynebacterium diphtheriae"],"a":2,"e":"Ans. is ''c'' i.e., Clostridium perfringens Two important characteristic feature of Cl. perfringens are :?","pyqMatches":[{"year":"2014","no":733,"q":"Double zone of hemolysis is seen in ?","o":["Staphylococcus areus","Streptococcus pyogenes","Clostridium perfringens","Corynebacterium diphtheriae"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3534, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 278, '{"id":3534,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":278,"q":"Mechanism action of botulinum toxin ?","o":["Increased cAMP","Increased cGMP","Inhibition of acetylcholine release","Inhibition of noradrenaline release"],"a":2,"e":"Ans. is ''c'' i.e., Inhibition of acetylcholine release Botulinum Toxin Cl. botulinum produces a powerful exotoxin that is responsible for its pathogenicity. The toxin differs from other exotoxins in that it is not released during the life of organism. It is produced intracellularly and appears in the medium only on the death and autolysis of the cell. It is the most toxic substance known. Toxin is heat labile, but spores are highly heat resistant. It acts by blocking the release of acetylcholine at synapses and neuromuscular junction. It acts presynaptically. Toxin of all types (A, B, C, D, E, F, G) are neurotoxin except C2 which is a cytotoxin (enterotoxin).","pyqMatches":[{"year":"2014","no":784,"q":"Mechanism action of botulinum toxin ?","o":["Increased cAMP","Increased cGMP","Inhibition of acetylcholine release","Inhibition of noradrenaline release"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3535, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 279, '{"id":3535,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":279,"q":"Serum marker after Hepatitis B vaccination ?","o":["Anti-HBsAg","Anti-HBeAg","Anti-HBcAg","HBsAg"],"a":0,"e":"Ans. is ''a'' i.e., Anti-HBsAg","pyqMatches":[{"year":"2014","no":814,"q":"Serum marker after Hepatitis B vaccination ?","o":["Anti-HBsAg","Anti-HBeAg","Anti-HBcAg","HBsAg"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3536, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 280, '{"id":3536,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":280,"q":"Double stranded RNA virus with segmented genome?","o":["Influenza","Rotavirus","Arenavirus","Bunyavirus"],"a":1,"e":"Ans. is ''b'' i.e., Rotavirus","pyqMatches":[{"year":"2014","no":794,"q":"Double stranded RNA virus with segmented genome?","o":["Influenza","Rotavirus","Arenavirus","Bunyavirus"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3537, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 281, '{"id":3537,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":281,"q":"Culture medium for campylobactor jejuni ?","o":["BYCE medium","Skirrow''s medium","Thayer-Martin medium","TCBS medium"],"a":1,"e":"Ans. is ''b'' i.e., Skirrow''s medium","pyqMatches":[{"year":"2014","no":755,"q":"Culture medium for campylobactor jejuni ?","o":["BYCE medium","Skirrow''s medium","Thayer-Martin medium","TCBS medium"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3538, 'Microbiology', 'Mycology', 'Moderate', 'Microbiology', 282, '{"id":3538,"subject":"Microbiology","chapter":"Mycology","difficulty":"Moderate","source":"Microbiology","sourceNo":282,"q":"All are true about candida except ?","o":["Pseudohyphae seen","Produce chlamydospore","It is a mould","It is a dimorphic fungus"],"a":2,"e":"Ans. is ''c'' i.e., It is a mould Candida Candida is a yeast like fungus (not mould). Candida albicans is the most common cause of mucosal candidiasis. All candida species pathogenic for humans are also encountered as commensals of humans, particularly in the mouth, stool and vagina. They grow rapidly on simple media as oval budding cells at 25° to 37°C. In tissue, both yeasts and pseudohyphae are present. Candida albicans is differentiated by other candida : It forms true hyphae (mycelia) or germ tubes when grown in serum. It forms thick walled large spores called chlamydospores when grown in corn meal agar. It is dimorphic. Remember → Candida albicans can produce yeast, true hyphae and pseudohyphae. A rapid method of identifying C. albicans is based on its ability to form germ tubes within two hours when incubated in human serum at 37°C Reynolds - Braude phenomenon ( Also known as germ tube test)","pyqMatches":[{"year":"2014","no":848,"q":"All are true about candida except ?","o":["Pseudohyphae seen","Produce chlamydospore","It is a mould","It is a dimorphic fungus"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3539, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 283, '{"id":3539,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":283,"q":"Intermediate host for guinea worm ?","o":["Fish","Man","Cyclops","Crab"],"a":2,"e":"Ans. is ''c'' i.e., Cyclops","pyqMatches":[{"year":"2014","no":850,"q":"Intermediate host for guinea worm ?","o":["Fish","Man","Cyclops","Crab"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3540, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 284, '{"id":3540,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":284,"q":"Which of the following hepatitis viruses is a DNA virus ?","o":["Hepatitis C virus","Hepatitis B virus","Delta agent","Hepatitis E virus"],"a":1,"e":"Ans. is ''b'' i.e., Hepatitis B virus Hepatitis B virus (HBV) Hepatitis B virus is the most widespread virus and the most important cause of viral hepatitis. o HBV belongs to Hepadna viridae HBV is hepadnavirus type -1 Hepatitis B is the only hepatitis virus which has DNA. All others are RNA viruses. HBV contains two linear strands of DNA. One of the strands (the plus strand) is incomplete and other is complete (the minus strand) → Partially double stranded DNA. HBV contains both DNA-dependent DNA polymerase and RNA dependent reverse transcriptase. Instead of DNA replication directly from a DNA template, HBV relys on reverse transcription of minus strand DNA from a pregenomic RNA intermediate (like retrovirus).","pyqMatches":[{"year":"2014","no":807,"q":"Which of the following hepatitis viruses is a DNA virus ?","o":["Hepatitis C virus","Hepatitis B virus","Delta agent","Hepatitis E virus"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3541, 'Microbiology', 'Clinical Microbiology', 'Easy', 'Microbiology', 285, '{"id":3541,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":285,"q":"Most common Nosocomial infection ?","o":["Pneumonia","UTI","Surgical wound infection","Nephritis"],"a":1,"e":"Ans. is ''b'' i.e., UTI Most common nosocomial infection → Urinary tract infection. Most of the nosocomial UTIs occur after urinary catheterization. Second most common nosocomial infection → Pneumonia. Most of the nosocomial pneumonias are acquire through respiratory intubation, mechanical ventilation and suction of the material from mouth.","pyqMatches":[{"year":"2014","no":891,"q":"Most common Nosocomial infection ?","o":["Pneumonia","UTI","Surgical wound infection","Nephritis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3542, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 286, '{"id":3542,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":286,"q":"Method used for acid fast staining ?","o":["Robertson''s method","Ziehl Neelsen","Silver imprignation method","Dark ground illumination"],"a":1,"e":"Ans. is ''b'' i.e., Ziehl Neelsen Acid fast staining After staining with aniline dye, acid fast organisms resist decolourisation with acids. Method most commonly used is modified Ziehl Neelsen.","pyqMatches":[{"year":"2014","no":871,"q":"Method used for acid fast staining ?","o":["Robertson''s method","Ziehl Neelsen","Silver imprignation method","Dark ground illumination"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3543, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 287, '{"id":3543,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":287,"q":"Paralysis in polio is characterized by ?","o":["Spasticity","Symmetrical","LMN type","Progressive"],"a":2,"e":"Ans. is ''c'' i.e., LMN type Clinical manifestations of polio Incubation period ranges from 3-35 days (usually 7-14 days). The clinical spectrum includes :-","pyqMatches":[{"year":"2014","no":825,"q":"Paralysis in polio is characterized by ?","o":["Spasticity","Symmetrical","LMN type","Progressive"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3544, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 288, '{"id":3544,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":288,"q":"Drug resistance in Tuberculosis is due to ?","o":["Transformation","Transduction","Conjugation","Mutation"],"a":3,"e":"Ans. is ''d'' i.e., Mutation","pyqMatches":[{"year":"2014","no":870,"q":"Drug resistance in Tuberculosis is due to ?","o":["Transformation","Transduction","Conjugation","Mutation"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3545, 'Microbiology', 'Bacteriology', 'Moderate', 'Microbiology', 289, '{"id":3545,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Moderate","source":"Microbiology","sourceNo":289,"q":"All selective media are correctly matched except ?","o":["V cholerae - TCBS medium","Pseudomonas - Cetrimide agar","M tuberculosis - LJ medium","Campylobacter - BCYE medium"],"a":3,"e":"Ans. is ''d'' i.e., Campylobacter - BCYE medium","pyqMatches":[{"year":"2014","no":785,"q":"All selective media are correctly matched except ?","o":["V cholerae - TCBS medium","Pseudomonas - Cetrimide agar","M tuberculosis - LJ medium","Campylobacter - BCYE medium"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3546, 'Microbiology', 'Mycology', 'Moderate', 'Microbiology', 290, '{"id":3546,"subject":"Microbiology","chapter":"Mycology","difficulty":"Moderate","source":"Microbiology","sourceNo":290,"q":"Not true about Histoplasma capsulatum ?","o":["Dimorphic fungus","May mimic TB","Capsulated","Mostly asymptomic"],"a":2,"e":"Ans. is ''c'' i.e., Capsulated Histoplasma capsulatum A dimorphic fungus Non encapsulated → The only medically important capsulated fungus is cryptococcus. Infection is acquired by inhalation of microconidia (small spores) in dust contaminated with bird or bat dropping. It causes intracellular infection of reticuloendothelial system. Clinical manifestations → Majority of patients are asymptomatic","pyqMatches":[{"year":"2014","no":849,"q":"Not true about Histoplasma capsulatum ?","o":["Dimorphic fungus","May mimic TB","Capsulated","Mostly asymptomic"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3547, 'Microbiology', 'Miscellaneous', 'Moderate', 'Microbiology', 291, '{"id":3547,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Microbiology","sourceNo":291,"q":"Schizoint are not seen in peripheral blood of which malarial parasites ?","o":["P vivax","P falciparum","P ovale","P malariae"],"a":1,"e":"Ans. is ''b'' i.e., P falciparum In peripheral smear offalciparum malaria following forms are seen Early ring form Gametocytes Mature trophozoites and schizoint are not found in peripheral blood because schizogony occurs inside the capillary of internal organs (spleen, liver and bone marrow).","pyqMatches":[{"year":"2014","no":836,"q":"Schizoint are not seen in peripheral blood of which malarial parasites ?","o":["P vivax","P falciparum","P ovale","P malariae"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3548, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 292, '{"id":3548,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":292,"q":"Super carrier of HBV shows following serum markers ?","o":["HBsAg","HbsAg + HBV DNA","HbsAg + HBeAg + HBV DNA","Anti-HBsAg + HBV DNA"],"a":2,"e":"Ans. is ''c'' i.e., HbsAg + HBeAg + HBV DNA In HBV infection, there are two types of carriers : Super Carriers High titre of HBs Ag, HBe Ag, DNA polymerase and HBV in the circulation Highly infective Simple carriers Low titre of HBsAg with negative HBe Ag, DNA polymerase and HBV Have low infectivity","pyqMatches":[{"year":"2014","no":815,"q":"Super carrier of HBV shows following serum markers ?","o":["HBsAg","HbsAg + HBV DNA","HbsAg + HBeAg + HBV DNA","Anti-HBsAg + HBV DNA"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3549, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 293, '{"id":3549,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":293,"q":"Cold sterilization is ?","o":["Sterilization by negative temperature","Sterilization by ionizing radiation","Sterilization by liquid CO2","Sterilization by non-ionizing radiation"],"a":1,"e":"Ans. is ''b'' i.e., Sterilization by ionizing radiation","pyqMatches":[{"year":"2014","no":857,"q":"Cold sterilization is ?","o":["Sterilization by negative temperature","Sterilization by ionizing radiation","Sterilization by liquid CO2","Sterilization by non-ionizing radiation"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3550, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 294, '{"id":3550,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":294,"q":"Best specimen for anaerobic culture ?","o":["Exudates from wound","Pus aspirated in vial","Swab from wound","Mid-stream urine"],"a":1,"e":"Ans. is ''b'' i.e., PUS aspirated in vial Ideal specimens for anaerobic cultures are samples of needle aspirates and proper tissue specimens. Anaerobic swabs are usually discouraged. Important specimens are :- i. Local abscess : Needle aspirates. i. Pulmonary : Transtracheal aspirates, lung aspirates, pleural fluid, protected bronchial wash. i. Abdominal : Abdominal abscess aspirate. v. Urinary tract : Suprapubic bladder aspirate. v. Genital tract : Culdocentesis specimen, endometrial swabs. i. CNS : CSF, Aspirate of abscess. Aspirated material then injected into one of the following :? a. Anaerobic swab b. Thioglycollate enrichment broth c. Oxygen free vials Exudates, swabs from burns, wound and skin abscesses are generally unacceptable for anaerobic culture. Cysts and abscess are contaminated with normal anaerobic flora. Voided and catheterized urine are contaminated with distal urethral anaerobes and are therefore unacceptable for anaerobic culture.","pyqMatches":[{"year":"2014","no":868,"q":"Best specimen for anaerobic culture ?","o":["Exudates from wound","Pus aspirated in vial","Swab from wound","Mid-stream urine"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3551, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 295, '{"id":3551,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":295,"q":"Aerobic blood culture should be incubated for how many days, before discarding ?","o":["2 days","5 days","10 days","14 days"],"a":3,"e":"Ans. is ''d'' i.e., 14 days Blood specimens of 5 or 10 ml generally are added to bottles containing, 50 or 100 ml of reagent (medium) to achieve a 1:10 blood medium ratio. All bottles should be transported to the laboratory as soon as possible and immediately incubeted at 35 ± 2°C in an upright position (Note - Lower incubation temperature may be preferred for isolation of some specific bacteria, e.g. Listeria grows well at 20- 25°C). A total incubation period of 7 days is generally sufficient for routine isolation procedure, which can be extended up to 14 days before discarding those that do not show evidence of growth.","pyqMatches":[{"year":"2014","no":869,"q":"Aerobic blood culture should be incubated for how many days, before discarding ?","o":["2 days","5 days","10 days","14 days"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3552, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 296, '{"id":3552,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":296,"q":"Infective endocarditis after tooth extraction is probably due to ?","o":["Streptococcus viridans","Streptococcus pneumoniae","Streptococcus pyogenes","Staphylococcus aureus"],"a":0,"e":"Ans. is ''a'' i.e., Streptococcus viridans Viridans streptococci are normally resident in the mouth and upper respiratory tract. They cause transient bacteremia following tooth extraction or other dental procedures; and get implanted on damaged or prosthetic valves or in a congenitally diseased heart, and grow to form vegetations. They are ordinarily nonpathogenic but can on occasion cause disease. In persons with preexisting cardiac lesions, they may cause bacterial endocarditis, Str. sanguis being most often responsible. Str. mutans is important in causation of dental caries. The transient viridans streptococcal bacteremia induced by eating, tooth-brushing, flossing and other source of minor trauma, together with adherence to biological surfaces, is thought to account for the predilection of these organisms to cause endocarditis. Viridans streptococci are also isolated, often as a part of a mixed flora, from sites of sinusitis, brain abscess and liver abscess. Viridans streptococcal bacteremia occurs relatively frequently in neutropenic patients, particularly after bone marrow transplantation or high dose chemotherapy for cancer. Treatment of varidans streptococcal infections include :-","pyqMatches":[{"year":"2014","no":739,"q":"Infective endocarditis after tooth extraction is probably due to ?","o":["Streptococcus viridans","Streptococcus pneumoniae","Streptococcus pyogenes","Staphylococcus aureus"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3553, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 297, '{"id":3553,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":297,"q":"Chronic carrier of typhoid shed bacilli for ?","o":["1-3 weeks after cure","3 weeks to 3 months after cure","3 months - 1 year after cure","More than 1 year after cure"],"a":3,"e":"Ans. is ''d'' i.e., More than 1 year after cure Carriers Bacilli presist in the gall bladder or kidney and are eliminated in the feces (fecal carriers) or urine (urinary carrier), respectively. The development of the carrier state is more common in women and in older age groups ( over 40 yrs) Carriers are the more frequent source of infection than cases. Urinary carriage is less frequent but more dangerous than intestinal carrier - Park PSM Urinary carrier is generally associated with some urinary lesions such as calculi or schistosomiasis. Presence of Vi antibody indicates the carrier state.","pyqMatches":[{"year":"2014","no":746,"q":"Chronic carrier of typhoid shed bacilli for ?","o":["1-3 weeks after cure","3 weeks to 3 months after cure","3 months - 1 year after cure","More than 1 year after cure"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3554, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 298, '{"id":3554,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":298,"q":"Ovoviviparous parasite which is associated with autoinfection ?","o":["Ancylostoma duodenale","Strongyloides stercoralis","Enterobius vermicularis","Ascaris"],"a":1,"e":"Ans. is ''b'' i.e., Strongyloides stercoralis Among the given options, strongyloides and enterobius can cause autoinfection. Strongyloides is ovoviviparous, whereas enterobius is oviparous.","pyqMatches":[{"year":"2014","no":839,"q":"Ovoviviparous parasite which is associated with autoinfection ?","o":["Ancylostoma duodenale","Strongyloides stercoralis","Enterobius vermicularis","Ascaris"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3555, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 299, '{"id":3555,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":299,"q":"Double stranded RNA virus ?","o":["Rotavirus","Measles virus","Mumps virus","Influenza virus"],"a":0,"e":"Ans. is ''a'' i.e., Rotavirus","pyqMatches":[{"year":"2014","no":795,"q":"Double stranded RNA virus ?","o":["Rotavirus","Measles virus","Mumps virus","Influenza virus"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3556, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 300, '{"id":3556,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":300,"q":"Earliest growth of diphtheria is detect on which media ?","o":["Potassium tellurite media with iron","McConkey''s agar","Dorset egg medium","Loeffler''s serum slope"],"a":3,"e":"Ans. is ''d'' i.e., Loeffler''s serum slope Diphtheria bacilli grow on Loeffler''s serum slope very rapidly and colonies can be seen in 6-8 hours, long before other bacteria grow.","pyqMatches":[{"year":"2014","no":787,"q":"Earliest growth of diphtheria is detect on which media ?","o":["Potassium tellurite media with iron","McConkey''s agar","Dorset egg medium","Loeffler''s serum slope"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3557, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 301, '{"id":3557,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":301,"q":"Blood agar is an example of ?","o":["Enriched media","Indicator media","Enrichment media","Selective media"],"a":0,"e":"Ans. is ''a'' i.e., Enriched media","pyqMatches":[{"year":"2012","no":671,"q":"Blood agar is an example of ?","o":["Enriched media","Indicator media","Enrichment media","Selective media"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":867,"q":"Blood agar is an example of ?","o":["Enriched media","Indicator media","Enrichment media","Selective media"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3558, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 302, '{"id":3558,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":302,"q":"Virus causing oropharyngeal carcinoma ?","o":["EBV","HPV","HHV-8","HTLV"],"a":1,"e":"Ans. is ''b'' i.e., HPV","pyqMatches":[{"year":"2014","no":826,"q":"Virus causing oropharyngeal carcinoma ?","o":["EBV","HPV","HHV-8","HTLV"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3559, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 303, '{"id":3559,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":303,"q":"Temperature required for holding period of 20 minutes in Hot air oven -","o":["160° C","170° C","120° C","130° C"],"a":1,"e":"Ans. is ''b'' i.e., 170° C","pyqMatches":[{"year":"2014","no":859,"q":"Temperature required for holding period of 20 minutes in Hot air oven","o":["160° C","170° C","120° C","130° C"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3560, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 304, '{"id":3560,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":304,"q":"Break bone fever is caused by ?","o":["Yellow fever","Japanese encephlitis","Dengue fever","KFD"],"a":2,"e":"Ans. is ''c'' i.e., Dengue fever Break bone fever (Saddle back fever) is caused by dengue virus. Dengue fever Dengue fever is caused by arboviruses (at least 4 serotypes have been recognized) It is transmitted by Aedes (Aedes aegypti is the main vector). The reservoir of infection is both man and mosquito. The transmission cycle is Man-mosquito-man Dengue fever occurs both epidemically and endemically. Epidemics starts in rainy season and are usually explosive. Aedes mosquito becomes infective by feeding on a patient from the day before onset to the 5th day of illness. Various manifestations of Dengue infection A) Classical dengue fever – i. Also known as break bone fever i. Incubation period 2-7 days (3-10 days -4 Park) i. Onset is sudden with chills and fever. Fever is usually between 39°c and 40°c temperature returns to normal after 5-6 days or subside on about the 3rd day and rise again after 5-8 days after onset (saddle back fever). v. Rashes appear in 80% of cases during remission or during second febrile phase. The rash lasts for 2 hours to several days and may be followed by desquamation. B) Dengue Hemorrhagic fever (DHF)- It is a severe form of dengue fever caused by infection with more than one dengue virus. The severe illness is thought to be due to double infection with more than one dengue virus. Dengue hemorrhagic fever is believed to result from reinfection with a virus of different serotype ( due to enhancing antibodies) DHF usally occurs after sequential infection with any two of the four serotypes of dengue virus. Sequence of infection may be important; serotype 1 followed by serotype2 is more dangerous than serotype 4 followed by serotype","pyqMatches":[{"year":"2014","no":827,"q":"Break bone fever is caused by ?","o":["Yellow fever","Japanese encephlitis","Dengue fever","KFD"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3561, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 305, '{"id":3561,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":305,"q":"In pontaic fever, which antigen is seen in urine?","o":["Lipopolysaccharide-1","Lipopolysaccharide-2","Lipopolysaccharide-4","Lipopolysaccharide-6"],"a":0,"e":"Ans. is ''a'' i.e., Lipopolysaccharide-1 Legionella are classified into serogroup on the basis ofgroup specific lipopolysaccharide (somatic antigen or ''O'' antigen). Legionella pneumophila sero-group-1 (LP-1) is the most common infecting organism. Urine test detect LP-1.","pyqMatches":[{"year":"2014","no":730,"q":"In pontaic fever, which antigen is seen in urine?","o":["Lipopolysaccharide-1","Lipopolysaccharide-2","Lipopolysaccharide-4","Lipopolysaccharide-6"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3562, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 306, '{"id":3562,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":306,"q":"Spores of clostridium perfringens are located ?","o":["In the middle of cells","At the poles of cells","Between middle and pole of cells","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., Between middle and pole of cells Clostridium perfringens (C. perfringens) is a spore-forming gram- positive bacterium that is found in many environmental sources as well as in the intestines of humans and animals. C. perfringens is commonly found on raw meat and poultry Spores of clostridium may be:?","pyqMatches":[{"year":"2014","no":731,"q":"Spores of clostridium perfringens are located ?","o":["In the middle of cells","At the poles of cells","Between middle and pole of cells","None of the above"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3563, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 307, '{"id":3563,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":307,"q":"Agar media used for Haemophilus influenza ?","o":["Blood agar","Chocolate agar","Tryptose agar","BYCE agar"],"a":1,"e":"Ans. is ''b'' i.e., Chocolate agar","pyqMatches":[{"year":"2014","no":786,"q":"Agar media used for Haemophilus influenza ?","o":["Blood agar","Chocolate agar","Tryptose agar","BYCE agar"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3564, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 308, '{"id":3564,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":308,"q":"Mechanism of action in pathogenesis of Pseudomembranous colitis by CI difficle ?","o":["Due to invasiveness","Due to endotoxin","Due to exotoxin","Due to NM blockade"],"a":2,"e":"Ans. is ''c'' i.e., Due to exotoxin Pathogenesis of pseudomembranous colitis is due to production of two large toxins by C. difficile : i) Toxin A (an enterotoxin) Is a potent neutrophil chemoattractant Causes disruption of cell cytoskeleton by glycosylation of GTP - binding proteins that regulate the actin cell cytoskeleton. ii) Toxin B (a cytotoxin) Causes disruption of cell cytoskeleton by similar mechanism.","pyqMatches":[{"year":"2014","no":735,"q":"Mechanism of action in pathogenesis of Pseudomembranous colitis by CI difficle ?","o":["Due to invasiveness","Due to endotoxin","Due to exotoxin","Due to NM blockade"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3565, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 309, '{"id":3565,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":309,"q":"Virus causing Latent infection (or Latent period is shown by which virus) -","o":["Rubella","HBV","Pertussis","Rota virus"],"a":1,"e":"Ans. is ''b'' i.e., HBV","pyqMatches":[],"pyqYears":[]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3566, 'Microbiology', 'Virology', 'Moderate', 'Microbiology', 310, '{"id":3566,"subject":"Microbiology","chapter":"Virology","difficulty":"Moderate","source":"Microbiology","sourceNo":310,"q":"True regarding arbovirus is all except ?","o":["KFD is transmitted by Tick","Dengue virus has one Serotype","Yellow fever is not seen in India","Dengue fever is transmitted by Aedes"],"a":1,"e":"Ans. is ''b'' i.e., Dengue virus has one Serotype KFD is mainly transmitted by Hard tick, but soft tick can also transmit the disease. Dengue virus has four serotypes. Yellow fever is not endemic in India, it is distributed in Africa and South America. Dengue fever is transmitted by Aedes mosquito.","pyqMatches":[{"year":"2014","no":829,"q":"True regarding arbovirus is all except ?","o":["KFD is transmitted by Tick","Dengue virus has one Serotype","Yellow fever is not seen in India","Dengue fever is transmitted by Aedes"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3567, 'Microbiology', 'Clinical Microbiology', 'Moderate', 'Microbiology', 311, '{"id":3567,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Moderate","source":"Microbiology","sourceNo":311,"q":"Bacteria not affected by streptogramins is ?","o":["E. coli","Staphylococcuaureus","Legionella","M. pneumoniae"],"a":0,"e":"Ans. is ''a'' i.e., E. coli Streptogramins are active against gram-positive cocci and organisms responsible for atypical pneumonia (e.g., M. pneumoniae, Legionella spp., and Chlamydia pneumoniae), but largely inactive against gram-negative organisms. They are bactericidal against streptococci and many strains of staphylococci, but bacteriostatic against E. faecium.","pyqMatches":[{"year":"2014","no":565,"q":"Bacteria not affected by streptogramins is ?","o":["E. coli","Staphylococcuaureus","Legionella","M. pneumoniae"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3568, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 312, '{"id":3568,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":312,"q":"Smallest Virus is ?","o":["Herpes virus","Adenovirus","Parvovirus","Poxvirus"],"a":2,"e":"Ans. is `c'' i.e. Parvovirus","pyqMatches":[{"year":"2014","no":796,"q":"Smallest Virus is ?","o":["Herpes virus","Adenovirus","Parvovirus","Poxvirus"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3569, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 313, '{"id":3569,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":313,"q":"Infectivity of HBV is indicated by ?","o":["HBeAg","HbsAg","HBV DNA","Anti HBs Ag"],"a":0,"e":"Ans. is ''a'' i.e., H BeAg","pyqMatches":[{"year":"2014","no":813,"q":"Infectivity of HBV is indicated by ?","o":["HBeAg","HbsAg","HBV DNA","Anti HBs Ag"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3570, 'Microbiology', 'Virology', 'Moderate', 'Microbiology', 314, '{"id":3570,"subject":"Microbiology","chapter":"Virology","difficulty":"Moderate","source":"Microbiology","sourceNo":314,"q":"True about CMV are all except ?","o":["Most common cause of post-transpinatation infection","Most common cause of transplacental infection","A non-enveloped DNA virus","Produces intranuclear inclusions"],"a":2,"e":"Ans. is ''c'' i.e., A non-enveloped DNA virus CMV is an enveloped DNA virus, belongs to Herpesviridae.","pyqMatches":[{"year":"2016","no":749,"q":"True about CMV are all except ?","o":["Most common cause of post-transpinatation infection","Most common cause of transplacental infection","A non-enveloped DNA virus","Produces intranuclear inclusions"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3571, 'Microbiology', 'Miscellaneous', 'Moderate', 'Microbiology', 315, '{"id":3571,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Microbiology","sourceNo":315,"q":"Not ture about El Tor biotype of vibrio cholerae?","o":["Lower mortality","Less SAR","Less chances of survival in environment","VP (+)"],"a":2,"e":"Ans. is ''c'' i.e., Less chances of survival in environment","pyqMatches":[{"year":"2015","no":699,"q":"Not ture about El Tor biotype of vibrio cholerae?","o":["Lower mortality","Less SAR","Less chances of survival in environment","VP (+)"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3572, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 316, '{"id":3572,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":316,"q":"HSV-2 (Herpes simplex) causes ?","o":["Oral ulcers","Genital ulcers","U.T.I.","Pharyngitis"],"a":1,"e":"Ans. is ''b'' i.e., Genital ulcer","pyqMatches":[{"year":"2016","no":745,"q":"HSV-2 (Herpes simplex) causes ?","o":["Oral ulcers","Genital ulcers","U.T.I.","Pharyngitis"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3573, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 317, '{"id":3573,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":317,"q":"Which of the following is the mechanism of action of tetanospasmin ?","o":["Inhibition of release of GABA and glycine","Inhibition of Ach release from synapse","Inhibition of protein synthesis","Activation of adenylyl cyclase"],"a":0,"e":"Ans. is ''a'' i.e., Inhibition of release of GABA and glycine Pathogenicity CL tetani has little invasive property and is confined to the primary site of lodgment. Tetanus results from the action of the potent exotoxin it produces.","pyqMatches":[{"year":"2012","no":685,"q":"Which of the following is the mechanism of action of tetanospasmin ?","o":["Inhibition of release of GABA and glycine","Inhibition of Ach release from synapse","Inhibition of protein synthesis","Activation of adenylyl cyclase"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3574, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 318, '{"id":3574,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":318,"q":"Ebola virus belongs to?","o":["Picornaviridae","Togaviridae","Flaviviridae","Filoviridae"],"a":3,"e":"Ans. is ''d'' i.e., Filoviridae","pyqMatches":[{"year":"2016","no":754,"q":"Ebola virus belongs to?","o":["Picornaviridae","Togaviridae","Flaviviridae","Filoviridae"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3575, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 319, '{"id":3575,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":319,"q":"Bollinger bodies are seen in ?","o":["Chickenpox","Cowpox","Fowlpox","Smallpox"],"a":2,"e":"Ans. is ''c'' i.e., Fowl pox","pyqMatches":[{"year":"2012","no":728,"q":"Bollinger bodies are seen in ?","o":["Chickenpox","Cowpox","Fowlpox","Smallpox"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3576, 'Microbiology', 'Virology', 'Moderate', 'Microbiology', 320, '{"id":3576,"subject":"Microbiology","chapter":"Virology","difficulty":"Moderate","source":"Microbiology","sourceNo":320,"q":"All are true regarding Japanese encephalitis except ?","o":["Caused by flavivirus","Humans are dead-end hosts","Transmitted by culex","Cattles are amplifier hosts"],"a":3,"e":"Ans. is ''d'' i.e., Cattles are amplifier hosts Japanese encephalitis Caused by a group B arbovirus (flavivirus) It is a Zoonotic disease ie infecting mainly animals and incidentally man. In south, epidemics have occured in Karnataka, Andhra predesh, TamilNadu, and Kerala. Human, cattle, and horses are dead-end hosts as the disease manifests as fatal encephalitis. Pigs act as an amplifying host and have a very important role in the epidemiology of the disease. Infection in swine is asymptomatic, except in pregnant sows, when abortion and fetal abnormalities are common sequelae. The most important vector is Culex tritaeniorhynchus, which feeds on cattle in preference to humans. The natural hosts of the Japanese encephalitis virus are birds, not humans. In November 2011, the Japanese encephalitis virus was reported in Culex bitaeniorhynchus in South Korea","pyqMatches":[{"year":"2014","no":994,"q":"All are true regarding Japanese encephalitis except ?","o":["Caused by flavivirus","Humans are dead-end hosts","Transmitted by culex","Cattles are amplifier hosts"],"a":3,"source":"NEET_2014_Paper.pdf"},{"year":"2020","no":80,"q":"All are true regarding Japanese encephalitis except ?","o":["Caused by flavivirus","Humans are dead-end hosts","Transmitted by culex","Cattles are amplifier hosts"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2014","2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3577, 'Microbiology', 'Clinical Microbiology', 'Moderate', 'Microbiology', 321, '{"id":3577,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Moderate","source":"Microbiology","sourceNo":321,"q":"All are seen with Pneumocystis carini in AIDS except","o":["Pneumonia","Otic polypoid mass","Ophthalmic choroid lesion","Meningitis"],"a":3,"e":"Ans. is'' i.e., Meningitis P. jiroveci (formerly known as P. carinii) causes interstitial pneumonia in AIDS patients. Pneumocystis otomastoiditis present with unilateral otalgia, otorrhea, hearing loss and a polypoid mass on otoscopy. Ocular pneumocystis is typically restricted to choroidal layer producing multiple focal circumscribed creamy to yellow-white lesions","pyqMatches":[{"year":"2013","no":715,"q":"All are seen with Pneumocystis carini in AIDS except","o":["Pneumonia","Otic polypoid mass","Ophthalmic choroid lesion","Meningitis"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3578, 'Microbiology', 'General Microbiology', 'Moderate', 'Microbiology', 322, '{"id":3578,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Moderate","source":"Microbiology","sourceNo":322,"q":"Antibiotic sensitivity testing can be done using all except","o":["E test","Kirby-Bauer method","Culture agar method","Broth dilution method"],"a":2,"e":"Ans. is ''c'' i.e., Culture agar method Tests used for antimicrobial sensitivity are :","pyqMatches":[{"year":"2013","no":604,"q":"Antibiotic sensitivity testing can be done using all except","o":["E test","Kirby-Bauer method","Culture agar method","Broth dilution method"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3579, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 323, '{"id":3579,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":323,"q":"Type E adverse reaction is","o":["Toxicity","Augmented effect","Teratogenesis","Withdrawal reaction"],"a":3,"e":"Ans. is ''d'' i.e., Withdrawal reaction Type A (Augmented) reaction Excess of normal, predictable, dose related pharmacodynamic effect. May occur in everyone eg - Postural hypotension, hypoglycemia Type B (Bizzare) reaction Due to unusual attributes of the patient interaction with the drug. Not dose related Not a part of normal pharmacological effect of a drug. Occurs only in some people. eg - Idiosyncracy and drug allergy. Type C (chronic) reaction Due to long term exposure eg; Analgesic nephropathy, dyskinesia by levodopa, immunosuppression by corticosteroids. Type D (Delayed) effects eg; Carcinogenesis or teratogenesis. Type E (Ending of use) reaction 3 eg; withdrawl reactions with clonidine.","pyqMatches":[{"year":"2013","no":508,"q":"Type E adverse reaction is","o":["Toxicity","Augmented effect","Teratogenesis","Withdrawal reaction"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3580, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 324, '{"id":3580,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":324,"q":"Treponema pallidum was discovered by ?","o":["Robert Koch","Twort","Schaudinn and Hoffman","Ellerman"],"a":2,"e":"Ans. is ''c'' i.e., Schaudinn and Hoffman Bacteria Discovered by Lepra bacillus (M. Leprae) Hansen (1874) Gonococcus Neisser (1879) Staphylococcus Ogston (1881) Diphtheria bacillus (C. Diphtheria) Loeffler (1884) Tetanus bacillus (C. Tetani) Nicolaier (1884) Pneumococcus Fraenkel (1886) Causative organism for Malta fever (Brucella) Bruce (1887) Spirochete of syphilis (T pallidum) Schaudinn and Hoffmann (1905)","pyqMatches":[{"year":"2013","no":716,"q":"Treponema pallidum was discovered by ?","o":["Robert Koch","Twort","Schaudinn and Hoffman","Ellerman"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3581, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 325, '{"id":3581,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":325,"q":"Lactose fermentation is seen in ?","o":["Blood agar","Chocolate agar","MacConkey agar","LJ medium"],"a":2,"e":"Ans. is ''c'' i.e., MacConkey agar Culture on differential media that contain special dyes and carbohydrates distinguishes lactose-fermenting (colored) from non- lactose-fermenting (non-pigmented) colonies and may allow rapid presumptive identification of enteric bacteria. Such media, used to see lactose fermentation, are :?","pyqMatches":[{"year":"2013","no":729,"q":"Lactose fermentation is seen in ?","o":["Blood agar","Chocolate agar","MacConkey agar","LJ medium"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3582, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 326, '{"id":3582,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":326,"q":"Major immunoglobulin secreted by intestine ?","o":["IgG","IgM","IgA","IgD"],"a":2,"e":"Ans. is ''c'' i.e., IgA It is the second most abundant antibody (after IgG)'' It is major immunoglobulin in clostrum, saliva, tears, respiratory and gastrointestinal secretions.","pyqMatches":[{"year":"2013","no":811,"q":"Major immunoglobulin secreted by intestine ?","o":["IgG","IgM","IgA","IgD"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3583, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 327, '{"id":3583,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":327,"q":"False about viruses is ?","o":["Ribosomes absent","Mitochondria absent","Motility absent","Nucleic acid absent"],"a":3,"e":"Ans. is ''d'' i.e., Nucleic acid absent Viruses contain nucleic acid, either RNA or DNA. Properties of viruses Viruses are obligate intracellular parasites. They lack enzymes necessary for protein and nucleic acid synthesis and are dependent for replication on the synthetic machinery of host cells so, they cannot grow in cell free culture media. They do not have cellular organization. They are unaffected by antibacterial antibiotics. They contain only one type of nucleic acid, either RNA or DNA, never both. They multiply by a complex process and not by binary fission. The extracellular infections virus particle is called the virion. o With few exceptions, viruses are very heat labile.","pyqMatches":[{"year":"2013","no":796,"q":"False about viruses is ?","o":["Ribosomes absent","Mitochondria absent","Motility absent","Nucleic acid absent"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3584, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 328, '{"id":3584,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":328,"q":"Arrangement of lens from eye to source of light, in light microscope ?","o":["Ocular lens : Subjective lens : Condensor lens","Subjective lens : Ocular lens : Condensor len","Condensor lens : Sujective lens : Ocular lens","Subjecive lens : Condensor lens : Ocular lens"],"a":0,"e":"Ans. is ''a'' i.e., Ocular lens : Subjective lens : Condensor lens","pyqMatches":[{"year":"2013","no":733,"q":"Arrangement of lens from eye to source of light, in light microscope ?","o":["Ocular lens : Subjective lens : Condensor lens","Subjective lens : Ocular lens : Condensor len","Condensor lens : Sujective lens : Ocular lens","Subjecive lens : Condensor lens : Ocular lens"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3585, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 329, '{"id":3585,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":329,"q":"Numbers of variable regions on each light and heavy chain of an antibody ?","o":["1","2","3","4"],"a":0,"e":"Ans. is ''a'' i.e., 1","pyqMatches":[{"year":"2013","no":807,"q":"Numbers of variable regions on each light and heavy chain of an antibody ?","o":["1","2","3","4"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3586, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 330, '{"id":3586,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":330,"q":"Hybridoma technique is used to obtain ?","o":["Specific antigen","Complement","Specific antibody","Interleukins"],"a":2,"e":"Ans. is ''c'' i.e., Specific antibody Hybridomas are cells that have been engineered to produce a specific antibody in huge numbers. Hybridomas Hybridomas are cells that have been engineered to produce a specific antibody in huge numbers To achieve this, qualities of two types of cells have to be combined together i.e. Cells which can produce large amount of pure antibody and Cells which have the ability to grow continually. These two types of cells are then fused together to form hybridoma. Procedure The pure antibody secreting cells are produced by injecting specific antigen in a mouse and obtaining the antigen specific plasma cells (antibody producing cell) from the mouse''s spleen. Cell which can grow indefinitely in culture are myeloma cells (cancerous cells). These two cell lines are fused together. The hybrid cell which is thus produced can be cloned to produce large number of identical daughter clones. These daughter clone cells then produce antibodies. Since these antibodies come from only one type of cell (hybridoma cell) they are called monoclonal antibodies. HAT (hypoxanthine, Aminopterin and thymidine) medium is used for preparation of monoclonal antibodies because it allows only fused hybridoma cells to grow. It does not allow the unfused myeloma and unfused antibody cells to grow. So HAT medium is a selective medium which allows (which allow selective growth of fused hybridoma) How does this happen ? Before we move on with the discussion, remember these few points about purine synthesis. Purine synthesis is essential for the survival of cells. Purine can be synthesized in two way i.e. De novo synthesis (dihydrofolate reductase enzyme is required for this pathway). Salvage pathway (an enzyme hypoxanthine - guanine phosphoribosyl transferase is required for salvage pathways) Myeloma cells lack HGPRTase enzyme therefore they cannot synthesize purine by salvage pathways. o Antibody cells have HGPRTase enzyme so they can use the salvage pathways. Aminopterin inhibits dihydrofolate reductase an enzyme used in denovo synthesis of purine When two cell lines i.e. antibody producing cell and myeloma cells are grown in HAT medium only the fused hybridoma cells survive. Myeloma cells die because they lack the enzyme HGPRTase so they cannot use the salvage pathways for purine synthesis. They also cannot use de-novo pathway, because Aminopterin present in the HAT medium inhibits dihydrofolate reductase (an enzyme essential for denovo synthesis ofpurine). The unfused antibody producing cells die as they cannot grow indefinitely because of their limited life span. Only fused hybridoma cells grow indefinitely because the antibody cell partner supplies HGPRTase and the myeloma partner gives it immortality. (as it is a cancer cell)","pyqMatches":[{"year":"2013","no":821,"q":"Hybridoma technique is used to obtain ?","o":["Specific antigen","Complement","Specific antibody","Interleukins"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3587, 'Microbiology', 'Virology', 'Moderate', 'Microbiology', 331, '{"id":3587,"subject":"Microbiology","chapter":"Virology","difficulty":"Moderate","source":"Microbiology","sourceNo":331,"q":"Which is not a DNA virus ?","o":["Parvovirus","Papovavirus","Poxvirus","Rhabdovirus"],"a":3,"e":"Ans. is ''d'' i.e., Rhabdovirus","pyqMatches":[{"year":"2013","no":797,"q":"Which is not a DNA virus ?","o":["Parvovirus","Papovavirus","Poxvirus","Rhabdovirus"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3588, 'Microbiology', 'General Microbiology', 'Moderate', 'Microbiology', 332, '{"id":3588,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Moderate","source":"Microbiology","sourceNo":332,"q":"All are sporicidal agents except ?","o":["Formaldehyde","Glutaraldehyde","Ethylene oxide","Isopropyl alcohol"],"a":3,"e":"Ans. is ''d'' i.e., Isopropyl alcohol Sporicidal agents Bacterial spores constitute some of the most resistant forms of life. By nature bacterial spores are resistant to extreme physical, chemical and thermal conditions and are second only to prions in their resistance to disinfection. They are resistant to most of the disinfectants. Only a few agents are effective against them. Sporicidal agents are - Glutaraldehyde Formaldehyde Halogens","pyqMatches":[{"year":"2013","no":723,"q":"All are sporicidal agents except ?","o":["Formaldehyde","Glutaraldehyde","Ethylene oxide","Isopropyl alcohol"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3589, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 333, '{"id":3589,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":333,"q":"In blood culture the ratio of blood to reagent is ?","o":["1:5","1:20","1:10","1:100"],"a":2,"e":"Ans. is ''c'' i.e., 1:10","pyqMatches":[{"year":"2013","no":730,"q":"In blood culture the ratio of blood to reagent is ?","o":["1:5","1:20","1:10","1:100"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3590, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 334, '{"id":3590,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":334,"q":"Sabin feldman Dye test is used to demonstrate infection with ?","o":["Filaria","Toxoplasma","Histoplasma","Ascaris"],"a":1,"e":"Ans. is •b'' i.e., Toxoplasma The polyclonal IgG antibodies evoked by infection are parasiticidal in vitro in the presence of serum complement and are the basis for the Sabin - Feldman dye test. Laboratory diagnosis of toxoplasmosis Laboratory diagnosis can be made by","pyqMatches":[{"year":"2014","no":838,"q":"Sabin feldman Dye test is used to demonstrate infection with ?","o":["Filaria","Toxoplasma","Histoplasma","Ascaris"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3591, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 335, '{"id":3591,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":335,"q":"Culture medium used for entamoeba histolytica?","o":["Blood agar","Philip''s medium","CLED medium","Trypticase serum"],"a":1,"e":"Ans. is ''b'' i.e., Philip''s medium Cultures media used for cultivation of E.histolytica are :-","pyqMatches":[{"year":"2013","no":765,"q":"Culture medium used for entamoeba histolytica?","o":["Blood agar","Philip''s medium","CLED medium","Trypticase serum"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3592, 'Microbiology', 'Mycology', 'Easy', 'Microbiology', 336, '{"id":3592,"subject":"Microbiology","chapter":"Mycology","difficulty":"Easy","source":"Microbiology","sourceNo":336,"q":"Ascospore is ?","o":["Asexual spore","Sexual spore","Conidia","None of the above"],"a":1,"e":"Ans. is ''b'' i.e., Sexual spore Fungal spores Most fungi reproduce through the generation of spores Fungi produce spores by two methods? Sexual reproduction → Sexual spores Asexual reproduction → Asexual spores","pyqMatches":[{"year":"2013","no":785,"q":"Ascospore is ?","o":["Asexual spore","Sexual spore","Conidia","None of the above"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3593, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 337, '{"id":3593,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":337,"q":"Most common staphylococcal phage strain causing hospital infection ?","o":["80/81","79/80","3A/3C","69/70"],"a":0,"e":"Ans. is ''a'' i.e., 80/81 Hospital strains of staphylococcus aureus Certain strains of staphylococcus are the common cause of post- operative wound infections and other infections in the hospital environment. These strains are known as hospital strains. The hospital strains show the following characteristics:","pyqMatches":[{"year":"2013","no":740,"q":"Most common staphylococcal phage strain causing hospital infection ?","o":["80/81","79/80","3A/3C","69/70"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3594, 'Microbiology', 'General Microbiology', 'Moderate', 'Microbiology', 338, '{"id":3594,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Moderate","source":"Microbiology","sourceNo":338,"q":"All of the sterilization methods are properly matched except ?","o":["Catgut suture - Radiation","Culture media - Autoclaving","Bronchoscope - Autoclaving","Glassware & syringes - Hot air ove"],"a":2,"e":"Ans. is ''c'' i.e., Bronchoscope - Autoclaving","pyqMatches":[{"year":"2013","no":725,"q":"All of the sterilization methods are properly matched except ?","o":["Catgut suture - Radiation","Culture media - Autoclaving","Bronchoscope - Autoclaving","Glassware & syringes - Hot air ove"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3595, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 339, '{"id":3595,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":339,"q":"Endoscope tube is sterilized by?","o":["Glutaraldehyde","Formalin","Autoclaving","Boiling"],"a":0,"e":"Ans. is ''a'' i.e., Glutaraldehyde 2% Glutaraldehyde (cidex) is most often used for equipment such as endoscope that cannot be sterilized or disinfected by heat.","pyqMatches":[{"year":"2014","no":854,"q":"Endoscope tube is sterilized by?","o":["Glutaraldehyde","Formalin","Autoclaving","Boiling"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3596, 'Microbiology', 'Bacteriology', 'Moderate', 'Microbiology', 340, '{"id":3596,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Moderate","source":"Microbiology","sourceNo":340,"q":"All are true regarding resistance of penicillin in staphylococcus aureus, except ?","o":["Penicillinase production is transmitted by transduction","Methicillin resistance is due to change in PBP","Hospital strains mostly produce type D penicillinase","Penicillinase production is plasmid mediated"],"a":2,"e":"Ans. is ''c'' i.e., Hospital strains mostly produce type D penicillinase Resistance to antibiotics a Penicillin resistance is of three types?","pyqMatches":[{"year":"2013","no":732,"q":"All are true regarding resistance of penicillin in staphylococcus aureus, except ?","o":["Penicillinase production is transmitted by transduction","Methicillin resistance is due to change in PBP","Hospital strains mostly produce type D penicillinase","Penicillinase production is plasmid mediated"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3597, 'Microbiology', 'Virology', 'Moderate', 'Microbiology', 341, '{"id":3597,"subject":"Microbiology","chapter":"Virology","difficulty":"Moderate","source":"Microbiology","sourceNo":341,"q":"Which of the following is not capsulated ?","o":["Pneumococcus","Cryptococcus","Meningococcus","Proteus"],"a":3,"e":"Ans. is ''d'' i.e., Proteus Capsule Many bacteria secrete a viscid material around the cell surface. When this is organized into a sharply defined structure, it is known as capsule. Capsules are protective and protect the bacteria from phagocytosis and from lytic enzymes. Some bacteria loose their capsules on repeated subcultures. Capsulated organisms Pneumococcus Yersinia Bacillus anthrax V. parahemolyticus Bordetella H. influenzae Meningococci Fresh strains of staphylococci, streptococci and ''E coli. Cl. perfringens and Cl. butyric= Bacteroides Klebsiella Cryptococcus.","pyqMatches":[{"year":"2013","no":719,"q":"Which of the following is not capsulated ?","o":["Pneumococcus","Cryptococcus","Meningococcus","Proteus"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3598, 'Microbiology', 'Immunology', 'Moderate', 'Microbiology', 342, '{"id":3598,"subject":"Microbiology","chapter":"Immunology","difficulty":"Moderate","source":"Microbiology","sourceNo":342,"q":"All are true regarding interleukin-1 except ?","o":["Primary source is monocyte-macrophage system","Endogenous pyrogens","Inhibit IL-2 production by T-cells","All are true"],"a":2,"e":"Ans. is ''c'' i.e., Inhibit IL-2 production by T-cells Interleukin -1 Also known as leucocyte activating factor (LAF) or B cell activating factor (BAF). Principally secreted by macrophages and monocytes; and epithelial cells. Other sources are B lymphocytes, fibroblasts and endothelial cells. Immunological effects- Activation of T cells for the production of IL - 2. B cell proliferation and antibody synthesis Neutrophil chemotaxis and increased PMN release from bone marrow. Increases body temperature (important endogenous pyrogen). Bone marrow cell proliferation Induction of acute phase protein.","pyqMatches":[{"year":"2013","no":819,"q":"All are true regarding interleukin-1 except ?","o":["Primary source is monocyte-macrophage system","Endogenous pyrogens","Inhibit IL-2 production by T-cells","All are true"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3599, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 343, '{"id":3599,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":343,"q":"Which of the following is a superantigen ?","o":["Cholera toxin","Diphtheria toxin","TSST","Vero-cytoxin"],"a":2,"e":"Ans. is ''c'' i.e., TSST Superantigens Certain species of infectious microorganisms produce powerful, immunostimulatory and disease causing toxins called superantigen, so called because of their ability to polyclonally active large fraction ( up to 20% ) of T cell population. Superantigens are potent activators of T-lymphocytes. Superantigens stimulate very large numbers of T cells, without relation to their epitope specificity. This leads to an excessive and dysregulated immune response with release of cytokines IL - 1, IL - 2, TNF - a and IF - y. Conventional antigens bind to MHC class I or II molecules in the groove of the cc 13 dimer (T cell receptor). In contrast, superantigen bind directly to the lateral portion of TCR 13 chain and MHC class II 13 chain, and stimulate T cells solely on 7 13 gene segment utilized independent of the D, J and y a - sequences present → Tf3 restricted T cell mitogens. Superantigens are capable of activating up to 20% of the peripheral T-cell pool, where as conventional antigens activate < I in 10, 000. Examples of superantigen Staphylococcal toxic shock syndrome Certain nonhuman Staphylococcal toxic shock syndrome toxin Staphylococcal enterotoxins Staphylococcal exfoliative (erythrogenic) toxin Streptococcal toxic shock syndrome toxin retroviral proteins. Yersinia pseudotuberculosis Mycoplasma arthritis. Mouse mammary tumor virus.","pyqMatches":[{"year":"2013","no":820,"q":"Which of the following is a superantigen ?","o":["Cholera toxin","Diphtheria toxin","TSST","Vero-cytoxin"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3600, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 344, '{"id":3600,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":344,"q":"Thomsen friedensreich phenomenon is ?","o":["Red cells infection by CMV","Red cell agglutination by all blood group sera","Hemolysis of transfused blood","Due to B antigen"],"a":1,"e":"Ans. is ''b'' i.e., Red cell agglutination by all blood group sera Thomsen-Freidenreich Phenomenon Red cell suspensions contaminated with certain bacteria, e.g. pseudomonas aeruginosa, become agglutinable by all blood group sera and even by normal human sera. This is known as Thomsen Friedenreich phenomenon and is due to unmasking of a hidden antigen normally present on all human erythryocytes, i.e. T-antigen. Anti-T agglutinins are normally present in human sera. Such panagglutinability of red cells has occasionally been observed in persons suffering from systemic bacterial infections.","pyqMatches":[{"year":"2013","no":826,"q":"Thomsen friedensreich phenomenon is ?","o":["Red cells infection by CMV","Red cell agglutination by all blood group sera","Hemolysis of transfused blood","Due to B antigen"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3601, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 345, '{"id":3601,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":345,"q":"Most common organism causing URTI in adult?","o":["H influenza","Stap aureus","Strepto pneumonia","Streptococcus pyogenes"],"a":3,"e":"Ans. is ''d'' i.e., Streptococcus pyogenes Most common cause of upper respiratory tract infection is viral infection. Rhinovirus is the most common cause. Among the bacteria, group A beta-hemolytic streptococci (streptococcus pyogenes) is the most common cause. And most common type of infection is pharyngitis.","pyqMatches":[{"year":"2013","no":741,"q":"Most common organism causing URTI in adult?","o":["H influenza","Stap aureus","Strepto pneumonia","Streptococcus pyogenes"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3602, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 346, '{"id":3602,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":346,"q":"Street rabies virus cause ?","o":["Natural rabies","Loboratory passage in rabbit","Fatal encephalitis in 6 days","Negri bodies not seen"],"a":0,"e":"Ans. is ''a'' i.e., Natural rabies","pyqMatches":[{"year":"2013","no":800,"q":"Street rabies virus cause ?","o":["Natural rabies","Loboratory passage in rabbit","Fatal encephalitis in 6 days","Negri bodies not seen"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3603, 'Microbiology', 'Parasitology', 'Moderate', 'Microbiology', 347, '{"id":3603,"subject":"Microbiology","chapter":"Parasitology","difficulty":"Moderate","source":"Microbiology","sourceNo":347,"q":"All are true about Helminths, except?","o":["Alimentary canal is complete in Nematodes","Body cavity is present in trematodes","Nematodes have separate sexes","Alimentary canal is Present but incomplete"],"a":1,"e":"Ans. is'' i.e., B- Body cavity is present in trematodes","pyqMatches":[{"year":"2013","no":766,"q":"All are true about Helminths, except?","o":["Alimentary canal is complete in Nematodes","Body cavity is present in trematodes","Nematodes have separate sexes","Alimentary canal is Present but incomplete"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3604, 'Microbiology', 'Parasitology', 'Moderate', 'Microbiology', 348, '{"id":3604,"subject":"Microbiology","chapter":"Parasitology","difficulty":"Moderate","source":"Microbiology","sourceNo":348,"q":"Which of the following amoebae does not have neuropathogenic effect ?","o":["Naegleria","Acanthamoeba","Dientamoeba","Bala muthia"],"a":2,"e":"Ans. is ''c'' i.e., Dientamoeba Neuropathogenic amoebae are Naegleria Fowleri Causes primary amebic meningoencephalitis. Acanthamoeba causes granulomatous amebic encephalitis Balamuthia mandrillaris causes amebic meningoencephalitis.","pyqMatches":[{"year":"2013","no":764,"q":"Which of the following amoebae does not have neuropathogenic effect ?","o":["Naegleria","Acanthamoeba","Dientamoeba","Bala muthia"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3605, 'Microbiology', 'Miscellaneous', 'Moderate', 'Microbiology', 349, '{"id":3605,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Microbiology","sourceNo":349,"q":"All of the following are important mechanisms of gene transfer in bacteria, except ?","o":["Lateral gene transfer","Conjugation","Vertical gene transfer","Horizontal gene transfer"],"a":2,"e":"Ans. is ''c'' i.e., Vertical gene transfer Gene transfer Gene transfer refers to the process of genetic material (e.g. DNA) being sent and received among two organisms-* Donor sends and recipient receives the genetic material. There are two processes of gene transfer :?","pyqMatches":[{"year":"2016","no":682,"q":"All of the following are important mechanisms of gene transfer in bacteria, except ?","o":["Lateral gene transfer","Conjugation","Vertical gene transfer","Horizontal gene transfer"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3606, 'Microbiology', 'Miscellaneous', 'Moderate', 'Microbiology', 350, '{"id":3606,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Microbiology","sourceNo":350,"q":"All are true regarding development of T- cells, except?","o":["T-cells are formed in bone marrow","Maturation of T-cells take place in thymus","T-cell are located in mantle layer of spleen","In lymph nodes, T-cells are found in paracortical area"],"a":2,"e":"Ans. is ''c'' i.e., T-cell are located in mantle layer of spleen T cells origin and maturation T cells originate in the bone marrow, fetal liver and yolk sac and mature in thymus. T cell precursors from the yolk sac, fetal liver and bone marrow migrate to the thymus during embryonic and postnatal life. Maturity of T-cells takes place in the thymus. After maturity T-lymphocytes are selectively seeded into certain sites of the peripheral lymphatic tissues, known as \"thymus - dependent regions\". Thymus dependent regions are - Paracortical area of lymph node. White pulp of the spleen, around the central arteriole. After neonatal thymectomy, the source of mature T cells (thymus) will be absent. As a result the thymus dependent regions of peripheral lymphoid organs will be depleted of T cells. B-cell origin and maturation In contrast to T cells ( which originate in bone marrow and mature in thymus), origin as well as maturation of B- cells takes place in the bone marrow. After maturation, B- cells migrate to peripheral T- cell independent lymphoid regions. T- cell independent regions are ?","pyqMatches":[{"year":"2013","no":812,"q":"All are true regarding development of T- cells, except?","o":["T-cells are formed in bone marrow","Maturation of T-cells take place in thymus","T-cell are located in mantle layer of spleen","In lymph nodes, T-cells are found in paracortical area"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3607, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 351, '{"id":3607,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":351,"q":"The only ovoviviporous parasite ?","o":["Ascaris","Strongyloides","Enterobius","Ancylostome"],"a":1,"e":"Ans. is ''b'' i.e., Strongyloides Strongyloides stercoralis is a human pathogenic parasitic roundworm causing the disease strongyloidiasis. Ovo-viviparous (lay eggs which hatch immediately) Strongyloides stercoralis, a ovo-viviparous intestinal nematode causes strongyloidiasis, which is manifested by skin rashes, eosinophilia, and abdominal abdominal pain. Infection usually usually results in asymptomatic chronic disease of the gut, which can remain undetected for decades.","pyqMatches":[{"year":"2013","no":767,"q":"The only ovoviviporous parasite ?","o":["Ascaris","Strongyloides","Enterobius","Ancylostome"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3608, 'Microbiology', 'Bacteriology', 'Moderate', 'Microbiology', 352, '{"id":3608,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Moderate","source":"Microbiology","sourceNo":352,"q":"All organisms shows bipolar staining except ?","o":["Calymmatobacter granulomati","Y. pestis","Pseudomonas mallei","H. influenzae"],"a":3,"e":"Ans. is ''d'' i.e., H. influenzae Safety pin appearance (Bipolar staining)","pyqMatches":[{"year":"2013","no":718,"q":"All organisms shows bipolar staining except ?","o":["Calymmatobacter granulomati","Y. pestis","Pseudomonas mallei","H. influenzae"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3609, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 353, '{"id":3609,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":353,"q":"Draughtsman (Concentric Rings) on culture are produced by ?","o":["Yersina pestis","H. ducreyi","B. pertusi","Pneumococi"],"a":3,"e":"Ans. is ''d'' i.e., Pneumococci Due to alpha hemolysis, colonies of pneumococci resemble colonies of Str. viridans. But on further incubation, the colonies of pneumococci become flat with raised edges and central umbonation, so that concentric rings are seen on the surface when viewed from above --> draughtsman or Carrom coin appearance.","pyqMatches":[{"year":"2013","no":742,"q":"Draughtsman (Concentric Rings) on culture are produced by ?","o":["Yersina pestis","H. ducreyi","B. pertusi","Pneumococi"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3610, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 354, '{"id":3610,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":354,"q":"Causative agent for melioidosis is ?","o":["Pseudomonas pseudomallei","Pseudomonas aeruginosa","Pseudomonas cepacia","Pseudomonas mallei"],"a":0,"e":"Ans. is ''a'' i.e., Pseudomonas pseudomallei Burkholderia pseudomallei is a recognized biothreat agent and the causative agent of melioidosis. This Gram-negative bacterium exists as a soil saprophyte in melioidosis-endemic areas of the world and accounts for 20% of community-acquired septicaemia in northeastern Thailand where half of those affected die. Melioidosis can be contracted via cutaneous inoculation, inhalation, or ingestion, and can present with extremely varied symptoms, these vague symptoms and diverse clinical presentations, along with culture-based diagnostic anomalies, make it difficult to properly diagnose in clinical settings. No vaccines against B. pseudomallei are currently available, making rapid detection and specific antibiotic treatment crucial for favorable outcomes in infected humans","pyqMatches":[{"year":"2013","no":762,"q":"Causative agent for melioidosis is ?","o":["Pseudomonas pseudomallei","Pseudomonas aeruginosa","Pseudomonas cepacia","Pseudomonas mallei"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3611, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 355, '{"id":3611,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":355,"q":"Specific reason to disallow the sample for culture?","o":["Sample brought within 2 hr of collection","Sample brought in sterile plastic container","Sample brought in formalin","Sample obtained after cleaning the collection site"],"a":2,"e":"Ans. is ''c'' i.e., Sample brought in formalin Guidelines for proper specimen collection Collect specimen before administering antibiotics or antivirals when possible. Collect specimen with as little skin contamination as possible to ensure that the sample collected represents the infected site. Utilize appropriate collection devices. Use sterile equipment and aseptic technique to collect specimens to prevent introduction of microorganisms during invasive procedures. Clearly label the specimen container with patient''s name, hospital number or other identifying number (i.e. birth date, requisition number), date and time of collection. Collect an adequate amount of specimen. Inadequate amounts of specimen may yield false-negative results. If a specimen is collected through intact skin, cleanse the skin first. For example, use 70% alcohol followed by iodine solution (1 to 2% tincture of iodine or 10% solution of povidone iodine). Collect fluid specimens in sturdy, sterile, screw cap, leak proof containers with lids that do not create an aerosol when opened. Specimens obtained by a physician using needle aspiration should be transferred to a sterile tube or anaerobic transport vial prior to transport of the specimen to the laboratory. If there is little material in the syringe, the physician should draw a small amount of sterile nonbacteriostatic 0.85% NaC1 through the syringe and then transfer the specimen to a sterile tube. Alternatively, and ONLY if the specimen will be compromised by transferring it from the syringe, a small amount of sterile 0.85% NaC1 may be drawn into the syringe prior to removal of the needle. DO NOT TRANSPORT SYRINGES WITH NEEDLES ATTACHED AND/OR RECAPPED. Attach syringe cap ONLY if necessary. The physician should use a protective device while removing the needle to avoid injury and should cap the syringe with a sterile cap prior to transporting it to the laboratory. Any Micorbiology and Virology specimens collected in formalin are UNACCEPTABLE for culture.","pyqMatches":[{"year":"2013","no":721,"q":"Specific reason to disallow the sample for culture?","o":["Sample brought within 2 hr of collection","Sample brought in sterile plastic container","Sample brought in formalin","Sample obtained after cleaning the collection site"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3612, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 356, '{"id":3612,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":356,"q":"Glass vessels and syringes are best sterilised by -","o":["Hot air oven","Autoclaving","Irradiation","Ethylene dioxide"],"a":0,"e":"Ans. is `a'' i.e., Hot air oven Hot air oven Hot air oven are electrical devices used in sterilization. The oven uses dry heat to sterilize articles. Hot air oven is used for Glass ware Swabs Liquid paraffin Fat and grease All glass syringe Forceps, scissors, scalpels Dusting powder","pyqMatches":[{"year":"2013","no":727,"q":"Glass vessels and syringes are best sterilised by","o":["Hot air oven","Autoclaving","Irradiation","Ethylene dioxide"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3613, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 357, '{"id":3613,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":357,"q":"Spores of bacteria are destroyed by","o":["Alcohol","Lysol","Halogen","Ionizing radiation"],"a":2,"e":"Ans. is ''c'' i.e., Halogen Amongst the given options, only halogens have sporicidal property","pyqMatches":[{"year":"2013","no":724,"q":"Spores of bacteria are destroyed by","o":["Alcohol","Lysol","Halogen","Ionizing radiation"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3614, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 358, '{"id":3614,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":358,"q":"Cell wall deficient organisms are","o":["Chlamydia","Mycoplasma","Streptococcus","Anaerobes"],"a":1,"e":"Ans. is ''b'' i.e., Mycoplasma Mycoplasma Smallest free living organism, are prokaryotes Lack cell wall, are bounded by a triple layered unit membrane that contains sterol (therefore mycoplasmas require sterol for growth). Their lack of cell wall is associated with cellular pleomorphism and resistance to cell wall - active antimicrobial agents, such as penicillins and cephalosporins (13 - lactam drugs). Multiplication is by binary fission. Unique among prokaryotes is the requirment of most mycoplasmas for cholesterol and related sterols.","pyqMatches":[{"year":"2014","no":875,"q":"Cell wall deficient organisms are","o":["Chlamydia","Mycoplasma","Streptococcus","Anaerobes"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3615, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 359, '{"id":3615,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":359,"q":"Vaccine is available against which type of meningococcus ?","o":["Type A","Type B","Type A and C","Type B and D"],"a":2,"e":"Ans. is ''c'' i.e., Type A and C Vaccine is a available against type A, type C, type Y and type W - 135 meningococci.","pyqMatches":[{"year":"2013","no":744,"q":"Vaccine is available against which type of meningococcus ?","o":["Type A","Type B","Type A and C","Type B and D"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3616, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 360, '{"id":3616,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":360,"q":"\"Citron bodies\" boat or leaf shaped pleomorphic organism in an exudate is","o":["Cl. welchii","Cl. edematiens","Cl. septicum","Cl. tetani"],"a":2,"e":"Ans. is ''c'' i.e., Clostridium septicum Citron bodies and boat or leaf shaped pleomorphic bacilli with irregular staining suggest CL septicum\". Clostridium Clostridial species are : Gram positive Anaerobic (obligate anaerobe) Spore forming Bacilli Motile by peritrichate flagella except C perfringens and C. tetani type IV which are non motile. Non capsulated except C. perfringens and C. butyricum which are capsulated Pathogenesis is due to exotoxin not endotoxin. Clostridium botulinum causes botulism not gas gangrene. Gas gangrene is caused by : C. perfringens (80%) → C novyi C. septicum → C. histolyticum","pyqMatches":[{"year":"2015","no":484,"q":"\"Citron bodies\" boat or leaf shaped pleomorphic organism in an exudate is","o":["Cl. welchii","Cl. edematiens","Cl. septicum","Cl. tetani"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3617, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 361, '{"id":3617,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":361,"q":"Swarming growth on culture is characteristic of which Gram positive organism ?","o":["Clostridium welchi","Clostridium tetani","Bacillus cereus","Proteus mirabilis"],"a":1,"e":"Ans. is ''b'' i.e., Clostridium tetani Swarming growth Swarming growth is due to the motility of bacteria. In young culture, discrete colonies are seen but thereafter actively motile cells spread on the surface of the plate in successive waves to form a thin filmy layer in concentric circles. Gram-positive organism showing swarming growth → C. tetani and Bacillus cereus Gram-negative organism showing swarming growth → Proteus mirabilis and Proteus vulgaris","pyqMatches":[{"year":"2013","no":735,"q":"Swarming growth on culture is characteristic of which Gram positive organism ?","o":["Clostridium welchi","Clostridium tetani","Bacillus cereus","Proteus mirabilis"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3618, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 362, '{"id":3618,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":362,"q":"Most common genetic play in Neisseria infection is","o":["Male gender","HLA b27","Complement deficiency","IgA deficiency"],"a":2,"e":"Ans. is ''c'' i.e., Complement deficiency It is an essential component of the innate immune defence against infection by Neisseria (N. meningitides and N. gonorrhoea). People who lack or have a deficiency in complement-mediated bactericidal activity are most susceptible to Neisseria diseases. Terminal complement component (C5 through C9) deficiencies and deficiencies of the alternative pathway (Properdin, C3, Factor D) have a strong effect on susceptibility to, as well as the severity of, neisserial infections.","pyqMatches":[{"year":"2013","no":745,"q":"Most common genetic play in Neisseria infection is","o":["Male gender","HLA b27","Complement deficiency","IgA deficiency"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3619, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 363, '{"id":3619,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":363,"q":"Heat labile immunoglobulin","o":["IgA","IgG","IgE","IgM"],"a":2,"e":"Ans. is ''c'' i.e., IgE Only heat labile Ig Inactivated at 56 degrees C in one hour.","pyqMatches":[{"year":"2013","no":810,"q":"Heat labile immunoglobulin","o":["IgA","IgG","IgE","IgM"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3620, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 364, '{"id":3620,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":364,"q":"Which is the longest DNA of hepatitis B virus ?","o":["P gene","X gene","S gene","C gene"],"a":0,"e":"Ans. is ''a'' i.e., P gene","pyqMatches":[{"year":"2013","no":801,"q":"Which is the longest DNA of hepatitis B virus ?","o":["P gene","X gene","S gene","C gene"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3621, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 365, '{"id":3621,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":365,"q":"Bacterial count in doudenum","o":["105 per gram","10'' per gram","1010 per gram","10''2 per gram"],"a":0,"e":"Ans. is ''a'' i.e., 105 per gram In GIT of an adult : Duodenum → -4 103 - 106 bacteria per gram. Jejunum and proximal ileum → 10'' - 108 bacteria per gram Lower ileum and cecum → 108 - 1010 bacteria per gram Colon and rectum → 10\" - 1012 bacteria per gram Colon and rectum have maximum number of bacteria and most of them (96-99%) are anaerobes : Anaerobic streptococci Clostridia Anaerobic lactobacilli Bacteroides","pyqMatches":[{"year":"2013","no":834,"q":"Bacterial count in doudenum","o":["105 per gram","10'' per gram","1010 per gram","10''2 per gram"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3622, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 366, '{"id":3622,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":366,"q":"Capacity of producing IgG starts at what age","o":["6 months","1 year","2 years","3 years"],"a":0,"e":"Ans. is ''a'' i.e., 6 months Immediately after birth, the newborn has high level of IgG antibodies in blood stream. But these antibodies are passively transferred to the baby from mother (i.e., maternal antibodies). During next few months, the maternal IgG antibodies steadily decrease. When healthy baby is about 2-3 months old, the immune system starts producing its own IgG antibodies. Once healthy babies reach six months of age, their IgG productin reaches at normal level. Note IgM antibodies production starts before birth only (3-6 months before), but at very lowlevel.","pyqMatches":[{"year":"2013","no":814,"q":"Capacity of producing IgG starts at what age","o":["6 months","1 year","2 years","3 years"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3623, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 367, '{"id":3623,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":367,"q":"Job''s syndrome is the following type of immuno​nodeficiency disease","o":["Humoral immunodeficiency","Cellular immunodeficiency","Disorder of complement","Disorder of phagocytosis"],"a":3,"e":"Ans. is ''d'' i.e., Disorder of phagocytosis Jobs syndrome is defect in phagocytic function. It is characterized by cold staphylococcal abscess, atopic eczema, otitis media; serum immunoglobulins are normal except IgE that is elevated","pyqMatches":[{"year":"2013","no":822,"q":"Job''s syndrome is the following type of immuno​nodeficiency disease","o":["Humoral immunodeficiency","Cellular immunodeficiency","Disorder of complement","Disorder of phagocytosis"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3624, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 368, '{"id":3624,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":368,"q":"Prions are best killed by","o":["Autoclaving at 134°C","5% formaline","Sodium hypochloride","None of these"],"a":0,"e":"Ans. is ''A'' i.e., Autoclaving at 134°C Incineration is the only way of disinfecting prion-contaminated materials or tissues. Boiling or irradiation does not affect and even routine autoclaving (at 121°C) is not reliable. Therefore, where there is a risk of exposure, surgeons use disposable instruments. To sterilize reusable instruments, WHO currently recommends combined use of a strong solution of sodium hydroxide and extended autoclaving at 134°C. \"Autoclaving at 134°C for 5 hrs or treatment with 2N NaOH for several hours is recommended for sterilization of prions\". since Sodium hydroxide option not available, correct answer is A","pyqMatches":[{"year":"2013","no":806,"q":"Prions are best killed by","o":["Autoclaving at 134°C","5% formaline","Sodium hypochloride","None of these"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3625, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 369, '{"id":3625,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":369,"q":"Most common cause of HUS in children is","o":["E coli 0157/H7","S typhi","Shigella","None"],"a":0,"e":"Ans. is ''a'' i.e., E Coli 0157/H7 The majority of HUS in children (90%) is related to prototypic diarrhoea associated form, predominately in previously healthy children 6 months to 4 years of age with a peak between 1 and 2 years. Shiga toxin-producing E .coli (STEC) is the major cause of diarrhoea associated with HUS. Specifically, E coli with serotype 0157:H7 is the bacteria most commonly associated with HUS (90%) and is the most virulent. Other common bacteria implicated in the causation of HUS are : Shigella dysenteriae Salmonella typhi Campylobacter jejuni Yersinia species Pseudomonas species Clostridium difficile","pyqMatches":[{"year":"2013","no":747,"q":"Most common cause of HUS in children is","o":["E coli 0157/H7","S typhi","Shigella","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3626, 'Microbiology', 'Miscellaneous', 'Moderate', 'Microbiology', 370, '{"id":3626,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Microbiology","sourceNo":370,"q":"Koch''s postulate is fullfilled by all except","o":["M.tuburculosis","E.coli","T. pallidum","None"],"a":2,"e":"Ans. is ''c'' i.e., T. pallidum Koch postulates Robert Koch proposed a series of postulates that have been applied broadly to link many specific bacterial species with particular disease. Koch''s postulates are :","pyqMatches":[{"year":"2013","no":722,"q":"Koch''s postulate is fullfilled by all except","o":["M.tuburculosis","E.coli","T. pallidum","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3627, 'Microbiology', 'Clinical Microbiology', 'Easy', 'Microbiology', 371, '{"id":3627,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":371,"q":"Inclusion body containing glycogen is seen in ?","o":["Chlamydia trachomatis","Chlamydia pneumoniae","Chlamydia psittaci","All of the above"],"a":0,"e":"Ans. is ''a'' i.e., Chlamydia trachomatis Characteristics of the chlamydia C trachomatis C pneumoniae C psittaci Inclusion morphology Round, vacuolar Round, dense Large, variable shape, dense Glycogen in inclusions Yes No No Elementary body morphology Round Pear-shaped, round Round Susceptible to sulfonamides Yes No No DNA homology to C pneumoniae < 10% 100% < 10% Plasmid Yes No Yes Serovars 15 1 > 4 Natural host Humans Humans Birds Mode of transmission Person to person, mother Airborne person to Airborne bird excreta to to infant person humans Major diseases Trachoma, STDs, infant pneumonia, lymphogran- uloma venereum Pneumonia, bronchitis, pharyngitis, sinusitis Psittacosis, pneumonia, fever of unexplained origin","pyqMatches":[{"year":"2013","no":755,"q":"Inclusion body containing glycogen is seen in ?","o":["Chlamydia trachomatis","Chlamydia pneumoniae","Chlamydia psittaci","All of the above"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3628, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 372, '{"id":3628,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":372,"q":"Cytolytic activity of membrane attack complex is modulated by ?","o":["Factor I","Factor B","Factor S","Factor H"],"a":2,"e":"Ans. is ''c'' i.e., Factor S","pyqMatches":[{"year":"2013","no":818,"q":"Cytolytic activity of membrane attack complex is modulated by ?","o":["Factor I","Factor B","Factor S","Factor H"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3629, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 373, '{"id":3629,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":373,"q":"Most common type of HPV associated with cervical cancer ?","o":["6, 11","5, 8","16, 18","6, 8"],"a":2,"e":"Ans. is `c'' i.e., 16, 18 HPV DNA of oncogenic types (High risk) in HPV-16, 18, 31, 33 and 45 → associated with cervical cancer HPV-6 and 11 (Low risk HPV) → associated with precursor lesions of cervical cancer (CIN) and Condyloma Acuminatum. In patients with epidermodysplasia verruciformis, Squamous cell cancer develop frequently at sites infected with specific HPV types, including 5 and 8. E6 and E7genes of HPV are responsible for carcinogenicity.","pyqMatches":[{"year":"2013","no":793,"q":"Most common type of HPV associated with cervical cancer ?","o":["6, 11","5, 8","16, 18","6, 8"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3630, 'Microbiology', 'Immunology', 'Hard', 'Microbiology', 374, '{"id":3630,"subject":"Microbiology","chapter":"Immunology","difficulty":"Hard","source":"Microbiology","sourceNo":374,"q":"Frie''s test is useful for diagnosis of ?","o":["Mycoplasma","Rickettsia","Sarcoidosis","Chlamydia"],"a":3,"e":"Ans. is ''d'' i.e., Chlamydia Fries test (skin hypersensitivity test) was used for LGV (caused by chlamydia trachomatis). But it is not used now because of high false positive results.","pyqMatches":[{"year":"2014","no":766,"q":"Frie''s test is useful for diagnosis of ?","o":["Mycoplasma","Rickettsia","Sarcoidosis","Chlamydia"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3631, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 375, '{"id":3631,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":375,"q":"Which of the following is an intermediate level disinfectant ?","o":["2% glutarldyhyde","Ethylene oxide","Hypochlorite","None"],"a":2,"e":"Ans. is ''c'' i.e., Hypochlorite","pyqMatches":[{"year":"2013","no":728,"q":"Which of the following is an intermediate level disinfectant ?","o":["2% glutarldyhyde","Ethylene oxide","Hypochlorite","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3632, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 376, '{"id":3632,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":376,"q":"Infective form of T. brucei ?","o":["Amastigote","Trypomastigote","Egg","None"],"a":1,"e":"Ans. is ''b'' i.e., Trypomastigote https://image.slidesharecdn.com/trypanosomaseminar1- 170312074241/95/trypanosoma-1-4-638.jpg?cb=1489304612","pyqMatches":[{"year":"2013","no":775,"q":"Infective form of T. brucei ?","o":["Amastigote","Trypomastigote","Egg","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3633, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 377, '{"id":3633,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":377,"q":"Staining method used for mycoplasma ?","o":["Fontona method","Laviditti method","Dienes method","None"],"a":2,"e":"Ans. is ''c'' i.e., Dienes method Colonies of mycoplasma may be seen with a hand lens but are best studied after staining by Dienes method. For this, a block of agar containing the colony is cut and placed on a slide. It is covered with a cover slip on which an alcoholic solution of methylene blue and azure has been dried","pyqMatches":[{"year":"2013","no":759,"q":"Staining method used for mycoplasma ?","o":["Fontona method","Laviditti method","Dienes method","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3634, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 378, '{"id":3634,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":378,"q":"Innate immunity involves ?","o":["T-cells","B-cells","Macrophages","Antibodies"],"a":2,"e":"Ans. is ''c'' i.e., Macrophages Macrophages and neutrophils are phagocytic cells that engulf a microbial pathogen after it has been identified by the innate immune system","pyqMatches":[{"year":"2013","no":824,"q":"Innate immunity involves ?","o":["T-cells","B-cells","Macrophages","Antibodies"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3635, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 379, '{"id":3635,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":379,"q":"Golden yellow jelly fungus is ?","o":["T tursurans","T montegrophytes","Trenella mesenterica","E floccosum"],"a":2,"e":"Ans. is ''c'' i.e., Trenella mesenterica The term jelly fungus is sometimes applied to any fungus with a jelly like fruiting body, but it is especially appropriate for the members of a group of texa traditionally assigned to the order Tremellales. Largest genus is Tremella, which consists of about 80 species. Tremella mesenterica (witches butter) is a commonly encountered species which has orange to golden yellow fruiting bodies. Therefore it is also called as golden yellow jelly fungus or yellow brain or yellow trembler.","pyqMatches":[{"year":"2013","no":838,"q":"Golden yellow jelly fungus is ?","o":["T tursurans","T montegrophytes","Trenella mesenterica","E floccosum"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3636, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 380, '{"id":3636,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":380,"q":"Macrophage tropic strains of HIV use ?","o":["CCR5","CXCR4","CCR4","None"],"a":0,"e":"Ans. is ''a'' i.e., CCR5 Receptors for HIV The receptor for the virus is CD4 antigen, and therefore the virus may infect any cell bearing the CD4 antigen on the surface this is primarily the CD4 + (Helper) T Lymphocyte Specific binding of virus to CD4 receptor is by the envelope glycoprotein gp-I 20. However, for infection to take place, cell fusion is essential, which is brought about by the transmembrane gp41. Entry of virus into the cells also requires coreceptor molecule :- T cell CXCR4 MacrophageCCR5","pyqMatches":[{"year":"2013","no":803,"q":"Macrophage tropic strains of HIV use ?","o":["CCR5","CXCR4","CCR4","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3637, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 381, '{"id":3637,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":381,"q":"ABO isoantibodies are of which class","o":["IgG","IgM","IgD","IgA"],"a":1,"e":"Ans. is ''b'' i.e., IgM The ABO antigens represent carbohydrate moeties present on erythrocytes. Invidual naturally develop antibodies (called isoantibodies), usually of IgM isotype, specific for ABO antigens that do not express. If the individual receives a transfusion of blood that contains incompatible ABO antigens, isoantibodies will cause agglutination of donor cells. This process is called as isohemagglutination, the antigens are called isohemagglutinins. Aslo remember Anti-Rh antibodies are of IgG class","pyqMatches":[{"year":"2013","no":825,"q":"ABO isoantibodies are of which class","o":["IgG","IgM","IgD","IgA"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3638, 'Microbiology', 'Clinical Microbiology', 'Hard', 'Microbiology', 382, '{"id":3638,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Hard","source":"Microbiology","sourceNo":382,"q":"A 4 year old child presents with acute watery diarrhea and abdominal cramps. Stool microscopy reveals trophozoites with falling leaf motility. The etiological agent is ?","o":["Entamoeba hisiolutics","Giardia lamblia","Trichomonas tenax","Balantidium coli"],"a":1,"e":"Ans. is ''b'' i.e., Giardia lamblia In acute giardiasis trophozoites show the typical \"falling-leaf\" motility in wet mount examination of faeces. Diagnosis of giardiasis? The gold-standard for diagnosis of giardiasis is microscopic demonstration of trophozoite or cyst or both in faeces. In acute giardiasis trophozoites show the typical \"falling-leaf\" motility in wet mount examination of faeces. The characteristic shape and two nuclei are seen after staining a thin faecal smear with Field''s stain. Trophozoites are also present in duodenal fluid. Duodenal fluid can be either aspirated or obtained by \"String test\" (Enterotest) for examination. Cysts of G. lamblia are often shed in the faeces in \"Showers\", meaning that many cytes may be passed on a day and none on the other. Hence, to detect cyst-passers multiple-sample are to be examined, preferably following concentration techniques like zinc sulphate floatation or formal detergent concentration technique.","pyqMatches":[{"year":"2013","no":781,"q":"A 4 year old child presents with acute watery diarrhea and abdominal cramps. Stool microscopy reveals trophozoites with falling leaf motility. The etiological agent is ?","o":["Entamoeba hisiolutics","Giardia lamblia","Trichomonas tenax","Balantidium coli"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3639, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 383, '{"id":3639,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":383,"q":"The hookworm thrives on ?","o":["Whole blood","Plasma","Serum","RBC"],"a":1,"e":"Ans. is ''b'' i.e., Plasma Hook worms Ancylostoma duodenale → Old world hookworm Nector americanus → New world hook worm Habitat → Small intestine (Jejunum > duodenum > Ileum) Infective form → Filariform larva Mode of infection → Penetration of skin Plasma forms the main source of nourishment for hookworm, the red blood cells pass out from the worm practically unchanged into the lumen of host''s intestine.","pyqMatches":[{"year":"2013","no":782,"q":"The hookworm thrives on ?","o":["Whole blood","Plasma","Serum","RBC"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3640, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 384, '{"id":3640,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":384,"q":"Infective form of Hookworms ?","o":["Egg","Rhabditiform larva","Filariform larva","None"],"a":2,"e":"Filariform larva Eggs are passed in the stool, and under favorable conditions (moisture, warmth, shade), larvae hatch in 1 to 2 days. The released rhabditiform larvae grow in the feces and/or the soil, and after 5 to 10 days (and two molts) they become filariform (third-stage) larvae that are infective .","pyqMatches":[{"year":"2013","no":783,"q":"Infective form of Hookworms ?","o":["Egg","Rhabditiform larva","Filariform larva","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3641, 'Microbiology', 'Miscellaneous', 'Moderate', 'Microbiology', 385, '{"id":3641,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Microbiology","sourceNo":385,"q":"All are non-sporing anaerobes of medical importance except","o":["Actinomyces","Bacteroides","Clostridia","Fusobacterium"],"a":2,"e":"Ans. is ''c'' i.e., Clostridia","pyqMatches":[{"year":"2013","no":761,"q":"All are non-sporing anaerobes of medical importance except","o":["Actinomyces","Bacteroides","Clostridia","Fusobacterium"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3642, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 386, '{"id":3642,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":386,"q":"The number of bacteria on skin are","o":["10''- 102","102- 105","105- 010",">1010"],"a":3,"e":"Ans. is ''d'' i.e., >1010 It has been calculated that a human adult has about 1012 bacteria on the skin.","pyqMatches":[{"year":"2013","no":831,"q":"The number of bacteria on skin are","o":["10''- 102","102- 105","105- 010",">1010"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3643, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 387, '{"id":3643,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":387,"q":"The number of bacteria per cm of skin are ?","o":["10''- 102","102- 103","105- 1010",">10''"],"a":1,"e":"Ans. is `b'' i.e., 102- 103 Density of bacterial population at most sites is between 100-1000 per square cm.","pyqMatches":[{"year":"2013","no":832,"q":"The number of bacteria per cm of skin are ?","o":["10''- 102","102- 103","105- 1010",">10''"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3644, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 388, '{"id":3644,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":388,"q":"Which Passive immunity is also provided through colostrum and breast milk?","o":["IgG","IgA","IgE","IgM"],"a":1,"e":"Ans. B. IgA Passive immunity is also provided through colostrum and breast milk, which contain IgA antibodies that are transferred to the gut of the infant, providing local protection against disease- causing bacteria and viruses until the newborn can synthesize its own antibodies. Protection mediated by IgA is dependent on the length of time that an infant is breastfed, which is one of the reasons the World Health Organization recommends breastfeeding for at least the first two years of life.","pyqMatches":[{"year":"2016","no":818,"q":"Which Passive immunity is also provided through colostrum and breast milk?","o":["IgG","IgA","IgE","IgM"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3645, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 389, '{"id":3645,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":389,"q":"Which of the following cell types are the most potent activator of T-cell ?","o":["Bell","Follicular Dendritic Cells","Mature dendritic cells","Macrophages"],"a":2,"e":"Ans. (c) Mature Dendritic cells Ref. Robins 8/e, p 192, Harrison 18/e, p 2657 \"Mature dendritic cells are the most potent activator of naive T-cell\" Dendritic Cells: Bone marrow derived cells There are two types of cells with dendritic morphology: - Interdigitating dendritic cells - Follicular dendritic cells Interdigitating dendritic cells or just dendritic cells are the most important antigen presenting cells for initiating pri​mary immune response against protein antigens. This is due to following reasons: - These cells are located at the right place to capture antigens , i.e. under epithelia, in the interstitial of all tissue. - They express variety of receptors (including TLR, mannose) for capturing microbes. - In response to microbes dendritic cells express the same chemokine receptors as to naive T-cells. - They express high levels of MHC class II molecules as well as co-stimulatory molecules B.7-1 and B.7-2. Or in other words they possess all the machinery needed for presenting antigens to and activating CD4 + T cells. On the other hand follicular dendritic cells (does not arise from bone marrow) are present in the germinal centres of lymphoid follicles where they trap antigens bound to antibodies or complement. Follicular dendritic cells plays a role in ongoing immune response by presenting antigens to B-cells and selecting the B-cells that have the highest affinity for the antigen.","pyqMatches":[{"year":"2015","no":772,"q":"Which of the following cell types are the most potent activator of T-cell ?","o":["Bell","Follicular Dendritic Cells","Mature dendritic cells","Macrophages"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3646, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 390, '{"id":3646,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":390,"q":"Prozone phenomenon is due to","o":["Antigen excess","Antibody excess","False +ve reaction","False -ve reaction"],"a":1,"e":":D Ans. (b) and (d) Antibody excess and False-negative Ref. Ananthanarayan 8/e, p 104, 9/ 105 Zone phenomenon (seen in agglutination and precipitation) consists of 3 parts:","pyqMatches":[{"year":"2015","no":793,"q":"Prozone phenomenon is due to","o":["Antigen excess","Antibody excess","False +ve reaction","False -ve reaction"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3647, 'Microbiology', 'Miscellaneous', 'Moderate', 'Microbiology', 391, '{"id":3647,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Microbiology","sourceNo":391,"q":"Which of the following Staphylococcal infection is not toxin mediated:","o":["Toxic shock syndrome","Scalded skin syndrome","Food poisoning","Septic shock"],"a":3,"e":"Ans. is (d) Septic shock Toxin mediated illness of S. Disease Toxin involved - Toxic shock syndrome Toxic shock syndrome toxin - Food poisoning Enterotoxin - Staphylococcal scalded skin syndrome Exfoliative/epidermolytic toxin Note: Septic shock is due to bacteremia.","pyqMatches":[{"year":"2014","no":888,"q":"Which of the following Staphylococcal infection is not toxin mediated:","o":["Toxic shock syndrome","Scalded skin syndrome","Food poisoning","Septic shock"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3648, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 392, '{"id":3648,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":392,"q":"True about interferon is:","o":["It is a synthetic antiviral agent","Inhibits viral replication in cells","Is specific for particular virus","None"],"a":1,"e":"Ans. (b) Inhibits viral replication in cells Rt,11 itlii ilallarayl111 CO, p p Iiii i tC,i :;r, p Interferon (host coded protein) has no direct action on viruses but inhibit viral replication by selectively inhibiting translation of viral m- RNA without affecting cellular m-RNA. IFN are not virus specific but species specific. It is of 3 types: Type Cell source. Cell target Biological ctivity IFN a (protein) or leukocyte IFN All cells All cellsAntiviral activity; stimulates T L.ell, macrophages and NK cell activity IFN 13 (glycoprotein) or Fibroblast IFN All cells All cellsDirect antitumor effects Upregulates MHC class I antigen expression. Used therepeutically in viral and autoimmune disease • IFNy (glycoprotein) or immune IFN T cells All cellsRegulates macrophage and NK cells activation NK Stimulates Ig secretion by B cells g y cells Induction of class II histocompatibility antigens TH1 T cell differentiation","pyqMatches":[{"year":"2012","no":762,"q":"True about interferon is:","o":["It is a synthetic antiviral agent","Inhibits viral replication in cells","Is specific for particular virus","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3649, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 393, '{"id":3649,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":393,"q":"Protein A of staphylococcus binds to","o":["IgA","IgG","IgD","IgE"],"a":1,"e":"Ans. is. b. IgG","pyqMatches":[{"year":"2015","no":722,"q":"Protein A of staphylococcus binds to","o":["IgA","IgG","IgD","IgE"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
