INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3671, 'Microbiology', 'Miscellaneous', 'Hard', 'Microbiology', 415, '{"id":3671,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Hard","source":"Microbiology","sourceNo":415,"q":"A child is presenting with vomiting and abdominal pain after 5 hours of eating some food. The most likely causa​tive orgonism:","o":["Bacillus cereus","Cl. perfringens","Cl. botalinum","V. cholerae"],"a":0,"e":"Ans. is. ''a'' i. e. Bacillus cereus","pyqMatches":[{"year":"2015","no":800,"q":"A child is presenting with vomiting and abdominal pain after 5 hours of eating some food. The most likely causa​tive orgonism:","o":["Bacillus cereus","Cl. perfringens","Cl. botalinum","V. cholerae"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3672, 'Microbiology', 'General Microbiology', 'Moderate', 'Microbiology', 416, '{"id":3672,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Moderate","source":"Microbiology","sourceNo":416,"q":"All are true about listeria except:","o":["Gram positive","PALCAM agar is used for isolation","Characteristic tumbling motility at 37°C","Umbrella shaped growth"],"a":2,"e":"Ans. is. ''c'' i. e., Characteristic tumbling motility at 37°C L. monocytogenes is a gram-positive'' coccobacillus''(coccoid rod) with a tendency to occur in chains. Peritrichous flagella are produced by the bacillus optimally at 20- 30°C but only scantily or not at all at 37°C Culture media used for isolation are blood agar, chocolate agar, and PALCAM agar. It grows on ordinary media within a temperature range of 1° to 45°C. Most cases of human disease are caused by serotypes 1/2a, 1/2b and 4b. The organism can be found as a part of the gastrointestinal flora in healthy individuals. Human disease due to L. monocytogenes generally occurs in the setting of pregnancy or immunosuppression.","pyqMatches":[{"year":"2015","no":714,"q":"All are true about listeria except:","o":["Gram positive","PALCAM agar is used for isolation","Characteristic tumbling motility at 37°C","Umbrella shaped growth"],"a":2,"source":"NEET_2015_Paper.pdf"},{"year":"2016","no":698,"q":"All are true about listeria except:","o":["Gram positive","PALCAM agar is used for isolation","Characteristic tumbling motility at 37°C","Umbrella shaped growth"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2015","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3673, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 417, '{"id":3673,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":417,"q":"Listeria resists phagocytosis in phagosomes (phagolysosomes) due to:","o":["β-hemolysin","Caspases","Cell membrane adhesion molecules","Opacity associated protein (OAP)"],"a":0,"e":"Ans. is. ''a'' i. e., β-hemolysin Most important step in pathogenesis of listeriosis is the survival and multiplication of L monocytogenes in phagocytes (macrophages), host epithelial cells and hepatocytes. * The most importaflt deterrminant of pathogenesis k listeriolysin O (LLO), A beta- hemolysin . LLO causes lysis of membrane of phagosomes within phagocytes and helps in intracellular survival of L monocytogenes. * Iron is an important virulence factor. Listeria produce siderophores and are able to obtain iron from transferrin. Immunity to listeria is primary cell mediated. Immunity can be transferred by sensitized lymphocytes but not by antibodies.","pyqMatches":[{"year":"2015","no":715,"q":"Listeria resists phagocytosis in phagosomes (phagolysosomes) due to:","o":["β-hemolysin","Caspases","Cell membrane adhesion molecules","Opacity associated protein (OAP)"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
