INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3676, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 420, '{"id":3676,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":420,"q":"XDR-TB is defined as Resistance to:","o":["INH plus rifampicin","Fluoroquinolones plus INH plus amikacin","Fluoroquinolones plus rifampicin plus kanamycin","Fluoroquinolones plus INH plus rifampicin plus amikacin"],"a":3,"e":"Ans. is. ''d'' i. e., Fluoroquinolones plus INH plus rifampicin plus amikacin Extensive drug resistance TB ( XDR - TB) is referred to resistance to rifampicin and isoniazid as well as to quinolone and at least one of the following second line drug kanamycin, capreomycin or amikacin. XDR - TB = resistance to INH, rifampcin, Quinolone, and capreomycin/kanamycin/ amikacin","pyqMatches":[{"year":"2013","no":1328,"q":"XDR-TB is defined as Resistance to:","o":["INH plus rifampicin","Fluoroquinolones plus INH plus amikacin","Fluoroquinolones plus rifampicin plus kanamycin","Fluoroquinolones plus INH plus rifampicin plus amikacin"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
