INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3701, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 445, '{"id":3701,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":445,"q":"Flame cells are seen in:","o":["Protozoa","Cestode","Nematodes","None"],"a":1,"e":"Ans. b. Cestode Flame cell (also called solenocyte) is the excretory cell in cestodes and trematodes, the number and arrangement of which is used as a basis for identification. The cell has a tuft of cilia, whose beating resembles the flickering of a flame. The flame cells open into a collecting tubule.","pyqMatches":[{"year":"2012","no":712,"q":"Flame cells are seen in:","o":["Protozoa","Cestode","Nematodes","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
