INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3706, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 450, '{"id":3706,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":450,"q":"Pontiac fever is caused by:","o":["Legionella","Listeria","Scrub typhus","Leptospira e) Rickettsia"],"a":0,"e":"Ans. (a) Legionella Pontiac fever is a mild nonfatal influenza like illness caused by Legionella pneumophila. Pontiac fex c, An acute self limiting flue like illness with IP of 24-48 hours Malaise, fatigue and myalgia are the most frequent presenting symptoms Pneumonia doesn''t develop. Complete recovery takes place, without antibiotic therapy. Diagnosis is established by antibody detection.","pyqMatches":[{"year":"2016","no":709,"q":"Pontiac fever is caused by:","o":["Legionella","Listeria","Scrub typhus","Leptospira e) Rickettsia"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
