INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3710, 'Microbiology', 'Immunology', 'Hard', 'Microbiology', 454, '{"id":3710,"subject":"Microbiology","chapter":"Immunology","difficulty":"Hard","source":"Microbiology","sourceNo":454,"q":"Diagnosis of rotavirus is by:","o":["Stool antigen","Stool antibody","Stool culture","Blood antibody"],"a":0,"e":"Ans. is ''a'' i.e., Stool antigen [Ref: Hanison 18n/e p. 1591, 1592; Greenwood 1&/e p. 5251 In Rotavirus diarrhoea, large no. of viruses are shed in faeces (at the peak of the disease, as many as l0rr virus particles can bedetected per ml of feces). These viruses can be easily detected by the following methods: i) Enzyme immunoassay (ELISA) It offers approximately 90% specificity & sensitivity for detection of virus in stools. ii) Latex agglutination iii) Immune electron microscopy --> Viral shedding detectable by these methods usually subsides within a week --> Virus in stools can be detected for longer periods by using techniques for detecting viral RNAs, such as PCR, Gel electrophoresis, probe hybridization.","pyqMatches":[{"year":"2012","no":727,"q":"Diagnosis of rotavirus is by:","o":["Stool antigen","Stool antibody","Stool culture","Blood antibody"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
