INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3722, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 466, '{"id":3722,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":466,"q":"Vincent''s angina is caused by Borrelia vincentii along with:","o":["Lactobacillus","Lactobacillus","Fusobacterium","Bacteroides"],"a":2,"e":"Ans. (c) Fusobacterium","pyqMatches":[{"year":"2015","no":719,"q":"Vincent''s angina is caused by Borrelia vincentii along with:","o":["Lactobacillus","Lactobacillus","Fusobacterium","Bacteroides"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3723, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 467, '{"id":3723,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":467,"q":"Most common form of leptospirosis:","o":["Weil''s disease","Icteric form","Hepatorenal form","Anicteric form"],"a":3,"e":"Ans. (d) Anicteric form It is most common (90%) and mild form. Most commonfindingkfner with conjunctival suftrcion","pyqMatches":[{"year":"2015","no":716,"q":"Most common form of leptospirosis:","o":["Weil''s disease","Icteric form","Hepatorenal form","Anicteric form"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3724, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 468, '{"id":3724,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":468,"q":"Colorado Tic fever is caused by:","o":["Filoviridae","Reoviridae","Coronaviridae","Calciviridae"],"a":1,"e":"Ans. b. Reoviridae","pyqMatches":[{"year":"2012","no":741,"q":"Colorado Tic fever is caused by:","o":["Filoviridae","Reoviridae","Coronaviridae","Calciviridae"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3725, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 469, '{"id":3725,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":469,"q":"Medium used for antibiotic sensitivity:","o":["CLED agar","Hektoen agar","Mueller-Hinton agar","Salt milk agar"],"a":2,"e":"Ans. is. ''c'' i. e., Mueller-Hinton agar Antibiotic sensitivity testing Antibiotic sensitivity testing is carried out to determine appropriate antibiotic to be used for a particular strain isolated from clinical specimens. Antibiotic testing can be carried out by two broad methods : a) Disc diffusion tests b) Dilution tests A) Disc diffusion tests There are most commonly used methods to determine antibiotic susceptibility. Discs impregnated with known concentration of antibiotics and are placed on the culture medium that has been inoculated with a culture of bacterium to be tested. Antibiotic sensitivity is determined by zone of inhibition of bacterial growth around the disc. Selection of media Medium that supports both test and control strains is selected for carrying out antibiotic susceptibility testing. For example: Muller-Hinton agar is used for gram-negative bacilli and staphylococcus spp. Blood agar is used for streptococcus spp and enterococcus spp. Chocolate agar is used for Haemophilus influenzae Wellcotest medium uses antibiotics sulfonamide and cotrimoxazole Mueller -Hinton agar is most commonly used medium for antibiotic sensitivity testing Type of disc diffusion test. Disc diffusion tests are following types :? i) Kirby-Bauer disc diffusion method - most commonly used. ii) Stoke disc diffusion method iii) Primary disc diffusion test","pyqMatches":[{"year":"2015","no":688,"q":"Medium used for antibiotic sensitivity:","o":["CLED agar","Hektoen agar","Mueller-Hinton agar","Salt milk agar"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3726, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 470, '{"id":3726,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":470,"q":"Sterilization of culture media containing serum is by:","o":["Autoclaving","Micropore filter","Gamma radiation","Gamma radiation"],"a":0,"e":"Ans. (a) Autoclaving","pyqMatches":[{"year":"2016","no":691,"q":"Sterilization of culture media containing serum is by:","o":["Autoclaving","Micropore filter","Gamma radiation","Gamma radiation"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3727, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 471, '{"id":3727,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":471,"q":"Incubation period of measles is:","o":["18-72 hours","10-14 days","3-4 days","20-25 days"],"a":1,"e":"Ans. b. 10-14 days","pyqMatches":[{"year":"2014","no":963,"q":"Incubation period of measles is:","o":["18-72 hours","10-14 days","3-4 days","20-25 days"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3728, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 472, '{"id":3728,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":472,"q":"Viral DNA is integrated into Bacterial DNA in:","o":["Transduction","Lysogenic conversion","Transformation","Conjugation"],"a":1,"e":"Ans. (b) Lysogenic conversion","pyqMatches":[{"year":"2015","no":691,"q":"Viral DNA is integrated into Bacterial DNA in:","o":["Transduction","Lysogenic conversion","Transformation","Conjugation"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3729, 'Microbiology', 'Virology', 'Moderate', 'Microbiology', 473, '{"id":3729,"subject":"Microbiology","chapter":"Virology","difficulty":"Moderate","source":"Microbiology","sourceNo":473,"q":"Which influenzae strain, not of human origin and can cause pandemic:","o":["Hi Ni","H2 N2","H5 Ni","H9 Ni"],"a":2,"e":"Ans. c. H5 N1","pyqMatches":[{"year":"2015","no":758,"q":"Which influenzae strain, not of human origin and can cause pandemic:","o":["Hi Ni","H2 N2","H5 Ni","H9 Ni"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3730, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 474, '{"id":3730,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":474,"q":"True about influenza vaccine:","o":["Live vaccine is used most commonly","Live vaccine is given by nasal drops","Killed vaccine is given intramuscular in deltoid","All are correct"],"a":1,"e":"Ans-B Live attenuated vaccines--> These are used as nasal drops Killed vaccine --> It is used mosf commonly. It is given subcutaneously in 2 doses, 3-4 weeks apart. Protective efficacy is 70-90% and duration of protection is 3-6 months.","pyqMatches":[{"year":"2015","no":759,"q":"True about influenza vaccine:","o":["Live vaccine is used most commonly","Live vaccine is given by nasal drops","Killed vaccine is given intramuscular in deltoid","All are correct"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3731, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 475, '{"id":3731,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":475,"q":"True about rotavirus vaccine:","o":["Killed vaccine","Given subcutaneous","Pentavalent vaccine","Should be given before 5 years"],"a":2,"e":"Ans. c. Pentavalent vaccine","pyqMatches":[{"year":"2015","no":765,"q":"True about rotavirus vaccine:","o":["Killed vaccine","Given subcutaneous","Pentavalent vaccine","Should be given before 5 years"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3732, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 476, '{"id":3732,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":476,"q":"Binding of gp 120 causes:","o":["Infection of target cell","Facilitation of co-receptor","Fusing of virus and target cell","None"],"a":1,"e":"Ans. b. Facilitation of co-receptor","pyqMatches":[{"year":"2012","no":736,"q":"Binding of gp 120 causes:","o":["Infection of target cell","Facilitation of co-receptor","Fusing of virus and target cell","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3733, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 477, '{"id":3733,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":477,"q":"HIV envelop is formed by:","o":["Host cell","Virus","Both","None"],"a":2,"e":"Ans. c. Both","pyqMatches":[{"year":"2015","no":754,"q":"HIV envelop is formed by:","o":["Host cell","Virus","Both","None"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3734, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 478, '{"id":3734,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":478,"q":"Which HIV-virus is more dangerous:","o":["HIV-1","HIV-2","Both are same","It depends on host factors"],"a":0,"e":"Ans. a. HIV-1","pyqMatches":[{"year":"2015","no":755,"q":"Which HIV-virus is more dangerous:","o":["HIV-1","HIV-2","Both are same","It depends on host factors"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3735, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 479, '{"id":3735,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":479,"q":"Most common mode of transmission of HIV sexual transmission:","o":["Blood & blood products","Occupational","Perinatal","Breast feeding"],"a":0,"e":"Ans. a. Blood & blood products","pyqMatches":[{"year":"2015","no":756,"q":"Most common mode of transmission of HIV sexual transmission:","o":["Blood & blood products","Occupational","Perinatal","Breast feeding"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3736, 'Microbiology', 'Parasitology', 'Easy', 'Microbiology', 480, '{"id":3736,"subject":"Microbiology","chapter":"Parasitology","difficulty":"Easy","source":"Microbiology","sourceNo":480,"q":"Flask shaped ulcers in intestine caused by","o":["Giardia lamblia","Entamoeba histolytica","Helicobacter pylori (H. pylori)","E. vermicularis"],"a":1,"e":"Answer B. Entamoeba histolytica Disease occurs when amoeba comes in contact with the cells lining the intestine. It then secretes the same substances it uses to digest bacteria, which include enzymes that destroy cell membranes and proteins. This process can lead to penetration and digestion of human tissues, resulting first in flask-shaped ulcerations in the intestine. Entamoeba histolytica ingests the destroyed cells by phagocytosis and is often seen with red blood cells (a process known as erythrophagocytosis) inside when viewed in stool samples","pyqMatches":[{"year":"2019","no":121,"q":"Flask shaped ulcers in intestine caused by","o":["Giardia lamblia","Entamoeba histolytica","Helicobacter pylori (H. pylori)","E. vermicularis"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3737, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 481, '{"id":3737,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":481,"q":"What type of culture media is used for Ligionella?","o":["(BCYE) agar media","MacConkey agar","Baird–Parker agar","Sabouraud’s agar"],"a":0,"e":"Answer: A. (BCYE) agar media BCYE is selective for certain Gram-negative bacteria, especially Legionella pneumophila. The organisms are nutritionally fastidious, non-spore forming, aerobic, gram-negative, slender rods. Media containing cysteine, yeast extract, a-ketoglutarate, and iron (BCYE) are required for isolation of Legionella. Selective BCYE (medium containing antibiotics), is recommended for specimens likely to be contaminated with other bacteria.","pyqMatches":[{"year":"2019","no":122,"q":"What type of culture media is used for Ligionella?","o":["(BCYE) agar media","MacConkey agar","Baird–Parker agar","Sabouraud’s agar"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3738, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 482, '{"id":3738,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":482,"q":"Special Stain for cryptococcus :","o":["ZN stain","Gram stain","Mucicarmine stain","Malachite green"],"a":2,"e":"Ans: C. Mucicarmine stain Mucicarmine stain provides specific staining of polysaccharide cell wall in C. neoformans. This is limited to microorganisms with a cell wall that is composed, at least in part, of a polysaccharide component.","pyqMatches":[{"year":"2019","no":123,"q":"Special Stain for cryptococcus :","o":["ZN stain","Gram stain","Mucicarmine stain","Malachite green"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3739, 'Microbiology', 'Clinical Microbiology', 'Hard', 'Microbiology', 483, '{"id":3739,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Hard","source":"Microbiology","sourceNo":483,"q":"A 36 yrs old male patient c/,o cough cold fever/rusty sputum / sputum neg for tb ,h/o of travel in china & eaten crab, Name the infection","o":["Paragonimus westermani","Faciola hepatica","Fasciolopsis buski","Entamoeba histolytica"],"a":0,"e":"Ans: A. Paragonimus westermani (lung fluke ). During invasion and migration of the flukes, diarrhea, abdominal pain, fever, cough, urticaria, hepatosplenomegaly, pulmonary abnormalities, and eosinophilia may develop. Un embryonated eggs are passed in the sputum of a human. During the chronic phase, the lungs are damaged most, but other organs may be involved. The clinical picture resembles and is often confused with TB. Praziquantel is the treatment of choice.","pyqMatches":[{"year":"2019","no":124,"q":"A 36 yrs old male patient c/,o cough cold fever/rusty sputum / sputum neg for tb ,h/o of travel in china & eaten crab, Name the infection","o":["Paragonimus westermani","Faciola hepatica","Fasciolopsis buski","Entamoeba histolytica"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3740, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 484, '{"id":3740,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":484,"q":"Microbiological test for diagnosing leptospira infection?","o":["Cold agglutination","Standard agglutination","Microscopic agglutination test (MAT)","None of these"],"a":2,"e":"Answer: C. Microscopic agglutination test (MAT) Dark-field microscopy or by immunofluorescence or light microscopy after appropriate staining used Microscoplc agglutination test [MAT](Gold Standard) also Macroscopic agglutlnation test Differential diagnosis list for leptospirosis is very large due to diverse symptoms.","pyqMatches":[{"year":"2019","no":125,"q":"Microbiological test for diagnosing leptospira infection?","o":["Cold agglutination","Standard agglutination","Microscopic agglutination test (MAT)","None of these"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3741, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 485, '{"id":3741,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":485,"q":"Disc diffusion method is also known as","o":["Kirby Bauer","VDRL","Dark field microscopy","None of these"],"a":0,"e":"Answer: A. Kirby Bauer The disk diffusion test, or agar diffusion test, or Kirby–Bauer test (disc-diffusion antibiotic susceptibility test, disc-diffusion antibiotic sensitivity test, KB test), is a test of the antibiotic sensitivity of bacteria. It uses antibiotic discs to test the extent to which bacteria are affected by those antibiotics. In this test, wafers containing antibiotics are placed on an agar plate where bacteria have been placed, and the plate is left to incubate. If an antibiotic stops the bacteria from growing or kills the bacteria, there will be an area around the wafer where the bacteria have not grown enough to be visible. This is called a zone of inhibition","pyqMatches":[{"year":"2019","no":117,"q":"Disc diffusion method is also known as","o":["Kirby Bauer","VDRL","Dark field microscopy","None of these"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3742, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 486, '{"id":3742,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":486,"q":"Rubella virus belongs to which family ?","o":["Rheovirus","Togavirus","Picornavirus","Orthomyxo"],"a":1,"e":"And. B. Togavirus Rubella virus (RuV) is the pathogenic agent of the disease rubella, and is the cause of congenital rubella syndrome when infection occurs during the first weeks of pregnancy. Rubella virus is the only member of the genus Rubivirus and belongs to the family of Togaviridae, whose members commonly have a genome of single-stranded RNA of positive polarity which is enclosed by an icosahedral capsid.","pyqMatches":[{"year":"2019","no":118,"q":"Rubella virus belongs to which family ?","o":["Rheovirus","Togavirus","Picornavirus","Orthomyxo"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3743, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 487, '{"id":3743,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":487,"q":"Which of the following infection resembles erythroblastosis?","o":["EBV","CMV","HSV","STAPHYLOCOCCUS"],"a":1,"e":"ANSWER: B. CMV Cytomegalovirus infection is a common herpesvirus infection with a wide range of symptoms: from no symptoms to fever and fatigue (resembling infectious mononucleosis) Infection with CMV, like that with Epstein-Barr virus (EBV, a type 4 herpesvirus), can cause a type of infectious mononucleosis in adolescents and young adults. Both CMV and EBV mononucleosis cause fever and fatigue. But EBV also causes a severe sore throat. CMV does not.","pyqMatches":[{"year":"2019","no":119,"q":"Which of the following infection resembles erythroblastosis?","o":["EBV","CMV","HSV","STAPHYLOCOCCUS"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3744, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 488, '{"id":3744,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":488,"q":"Diagnostic test for neurosyphilis","o":["VDRL","RPR","TPI","FTA-ABS"],"a":0,"e":"Answer:A. VDRL Examination of CSF for pleocytosis, increase protein concentration, VDRL reactivity. A positive CSF VDRL makes the diagnosis of neurosyphilis. If both test i.e. VDRL and FTA- ABS IgM (specific) test are positive in the infant then congenital syphilis should be strongly suspected and the child should be treated. A positive test confirms neurosyphilis but a negative result does not rule out neurosyphilis. Due to the low sensitivity of the CSF VDRL, fluorescent treponemal antibody absorption test (FTA-ABS) can be used to supplement VDRL.","pyqMatches":[{"year":"2019","no":120,"q":"Diagnostic test for neurosyphilis","o":["VDRL","RPR","TPI","FTA-ABS"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3745, 'Microbiology', 'Clinical Microbiology', 'Hard', 'Microbiology', 489, '{"id":3745,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Hard","source":"Microbiology","sourceNo":489,"q":"A patient is having gastrointestinal problems including abdominal pain and distension, bloody or mucus-filled diarrhea, and tenesmus,with rectal prolapse, A stool, ova and parasites exam reveals the presence of typical Barrel-shaped eggs, possible causative agent is?","o":["Campylobacter","Clostridium difficile","Giardia lamblia","Trichuris"],"a":3,"e":"Answer: D. Trichuris whipworm can cause gastrointestinal problems, such as abdominal pain, diarrhea, mucous or bloody stools weight loss, painful urination, and weakness. Rectal prolapse is a hallmark, albeit rare, symptom of a heavy T. trichiura infection that occurs in children more frequently than adults. When rectal prolapse occurs, worms can often be identified on the edematous rectum. In a whipworm infection, the rectum loses its internal support because the worms bury their thin heads into the intestinal lining, loosening the elastic epithelium and weakening the surrounding muscles.","pyqMatches":[{"year":"2019","no":109,"q":"A patient is having gastrointestinal problems including abdominal pain and distension, bloody or mucus-filled diarrhea, and tenesmus,with rectal prolapse, A stool, ova and parasites exam reveals the presence of typical Barrel-shaped eggs, possible causative agent is?","o":["Campylobacter","Clostridium difficile","Giardia lamblia","Trichuris"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3746, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 490, '{"id":3746,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":490,"q":"Contact isolation is done for","o":["MRSA","Mumps","Diphtheria","Asthama"],"a":2,"e":"Answer: C. Diphtheria A type of bacteria called Corynebacterium diphtheriae causes diphtheria. The condition is typically spread through person-to-person contact or through contact with objects that have the bacteria on them, such as a cup or used tissue. Even if an infected person doesn’t show any signs or symptoms of diphtheria, they’re still able to transmit the bacterial infection for up to six weeks after the initial infection The bacteria most commonly infect your nose and throat. Once you’re infected, the bacteria release dangerous substances called toxins. The toxins spread through your bloodstream and often cause a thick, gray coating in nose, throat,lungs.","pyqMatches":[{"year":"2019","no":110,"q":"Contact isolation is done for","o":["MRSA","Mumps","Diphtheria","Asthama"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3747, 'Microbiology', 'Bacteriology', 'Moderate', 'Microbiology', 491, '{"id":3747,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Moderate","source":"Microbiology","sourceNo":491,"q":"A child is suffering from recurrent chronic infections with encapsulated bacteria is due to deficiency of subclass .","o":["IgG1","IgG2","IgG3","IgG4"],"a":1,"e":"Answer: B. IgG2 IgG2 antibodies are predominantly against the polysaccharide (complex sugar) coating (capsule) of certain disease-producing bacteria (such as, Streptococcus pneumoniaeand Haemophilus influenzae). In young children, the ability to make IgG2 antibodies to the polysaccharide coatings of bacteria develops more slowly than the ability to make antibodies to proteins.","pyqMatches":[{"year":"2019","no":111,"q":"A child is suffering from recurrent chronic infections with encapsulated bacteria is due to deficiency of subclass .","o":["IgG1","IgG2","IgG3","IgG4"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3748, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 492, '{"id":3748,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":492,"q":"D.O.C for isospora","o":["Penicillin G","Benzathine penicillin","Co-trimoxazole","Albendazole"],"a":2,"e":"Answer: C. Co-trimoxazole The most common antibiotic that is prescribed is co-trimoxazole (trimethoprimsulfamethoxazole), more commonly known as Bactrim, Septra, or Cotrim. For Immunocompetent hosts Prefered regimen: Trimethoprim- sulfamethoxazole 160 mg/800 mg PO bid for 7-10 days..","pyqMatches":[{"year":"2019","no":112,"q":"D.O.C for isospora","o":["Penicillin G","Benzathine penicillin","Co-trimoxazole","Albendazole"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3749, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 493, '{"id":3749,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":493,"q":"Coxsackievirus A16 causes","o":["Yellow fever","Hand-foot-mouth disease","Rocky mountain spotted fever","Encephalomyocarditis"],"a":1,"e":"Answer: B. Hand-foot-mouth disease Hand, Foot and Mouth Disease (HFMD) is caused by coxsackie A- 16 The viruses that cause HFMD are spread through close personal contact, through the air from coughing and the feces of an infected person. Coxsackievirus A16 is the most common cause, and enterovirus 71 is the second-most common cause. Other strains of coxsackievirus and enterovirus can also be responsible. It typically begins with a fever and feeling generally unwell. This is followed a day or two later by flat discolored spots or bumps that may blister, on the hands, feet and mouth and occasionally buttocks and groin.","pyqMatches":[{"year":"2019","no":113,"q":"Coxsackievirus A16 causes","o":["Yellow fever","Hand-foot-mouth disease","Rocky mountain spotted fever","Encephalomyocarditis"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3750, 'Microbiology', 'Clinical Microbiology', 'Easy', 'Microbiology', 494, '{"id":3750,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":494,"q":"Pneumocystis jerovici is:","o":["Associated with CMV","Diagnosis is by sputum microscopy","Seen only in immunocompromised patients","Always associated with pneumatocele"],"a":1,"e":"Answer: B. Diagnosis is by sputum microscopy Human isolate of. Pneumocystis which is associated with severe pneumonia in immunocompromised state particularly AIDS. P. jerovici is an extracellular pathogen. Growth in the lung is limited to surfactant layer above alveolar epithelium. Serologic evidence suggest that most individuals are infected in early childhood (thus option “c” is wrong) but the pneumonia is seen only in immunocompromised state. Diagnosis is made by detection of organism in proper specimen Sputum: Quick and non invasive. Broncho-alaeolar laoage (BAL) fluid: Mainstay of pneumocystis diagnosis. Transbronchial biopsy: If diagnosis cannot be made by BAL.","pyqMatches":[{"year":"2016","no":768,"q":"Pneumocystis jerovici is:","o":["Associated with CMV","Diagnosis is by sputum microscopy","Seen only in immunocompromised patients","Always associated with pneumatocele"],"a":1,"source":"NEET_2016_Paper.pdf"},{"year":"2019","no":114,"q":"Pneumocystis jerovici is:","o":["Associated with CMV","Diagnosis is by sputum microscopy","Seen only in immunocompromised patients","Always associated with pneumatocele"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2016","2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3751, 'Microbiology', 'Miscellaneous', 'Moderate', 'Microbiology', 495, '{"id":3751,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Microbiology","sourceNo":495,"q":"All are true about congenital Toxoplasmosis EXCEPT","o":["Chorioretinitis","Conjunctivitis","Hydrocephalus","Cerebral calcification"],"a":1,"e":"Answer B. Conjunctivitis Occurs only when mother gets primary toxoplasmosis infection whether clinical or asymptomatic during pregnancy or <6 months before conception (i.e. no risk if acquired > 6 months before conception). As gestational age is increased, risk of transmission to fetus increased, i.e. max. in 3rd trimester while severity of fetal damage is decreased, i.e. infant is usually asymptomatic if infection transmit in 3rd trimester. Chorioretinitis is usually treated with a combination of corticosteroids and antibiotics. It causes: hydrocephalous, diffuse cerebral calcification,hepatosplenomegaly,mental retardation myocarditis,lymphadenitis,microencephaly, myocarditis, chorioretinitis, multiorgan failure, Pneumonitis","pyqMatches":[{"year":"2019","no":115,"q":"All are true about congenital Toxoplasmosis EXCEPT","o":["Chorioretinitis","Conjunctivitis","Hydrocephalus","Cerebral calcification"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3752, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 496, '{"id":3752,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":496,"q":"true about TRIAD congenital rubella syndrome","o":["PDA, cataract and deafness is seen","Hepatosplenomegaly, mental retardation, deafness","Chorioretinitis, multiorgan failure, pneumonitis","None of these"],"a":0,"e":"Answer: A. PDA, cataract and deafness is seen Congenital rubella syndrome (CRS) can occur in a developing fetus of a pregnant woman who has contracted rubella, usually in the first trimester. If infection occurs 0–28 days before conception, the infant has a 43% risk of being affected. Infection in 2nd trimester – may be deafness only. >6 wks – no major abnormalities Diagnosis: Isolation of virus in cell cultures of throat samples, urine or other secretions. Detection of IgM in single serum sample shortly after birth. Persistance of Rubella IgG antibodies serum beyond 1 year or rising antibody titer anytime during infancy in an unvaccinated child","pyqMatches":[{"year":"2019","no":116,"q":"true about TRIAD congenital rubella syndrome","o":["PDA, cataract and deafness is seen","Hepatosplenomegaly, mental retardation, deafness","Chorioretinitis, multiorgan failure, pneumonitis","None of these"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3753, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 497, '{"id":3753,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":497,"q":"Weil felix reaction in scrub typhus is/are positive for:","o":["OX -19","OX-2","Both OX -19 & OX-2","OX -K e) OX -19, OX-2 & OX -K"],"a":3,"e":"Ans: d. OX -K [Ref Ananthanarayan 9th/410; Medical Microbiology by Greenwood 16th/373] This reaction is an agglutination test in which sera are tested for agglutinins to the 0 antigens of certain non-motile Proteus strains OX-19, OX-2 & OX-X The basis of test is the sharing of an alkali-stable carbohydrate antigen by some rickettsiae & by certain strains of proteus, P. vulgaris OX 19 & OX 2 & P.mirabilis OX K. disease OX-19 OX-2 OX-K Epidemic typhus +++ + _ Brill- Zinsser disease Usually(– ve)or weakly (+ve) - Endemic typhus +++ +/- - Tickborne spotted f ++ ++ - fever Scrub typhus - - +++","pyqMatches":[{"year":"2015","no":777,"q":"Weil felix reaction in scrub typhus is/are positive for:","o":["OX -19","OX-2","Both OX -19 & OX-2","OX -K e) OX -19, OX-2 & OX -K"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3754, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 498, '{"id":3754,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":498,"q":"The correct order of gram staining is","o":["Gentian violet → Iodine → Carbol fuchsin","Iodine → Gentian violet → Carbol fuchsin","Carbol fuchsin → Iodine → Gentian violet","Carbol fuchsin → Gentian violet → Iodine"],"a":0,"e":"Answer-A- Gentian violet → Iodine → Carbol fuchsin","pyqMatches":[{"year":"2012","no":667,"q":"The correct order of gram staining is","o":["Gentian violet → Iodine → Carbol fuchsin","Iodine → Gentian violet → Carbol fuchsin","Carbol fuchsin → Iodine → Gentian violet","Carbol fuchsin → Gentian violet → Iodine"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3755, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 499, '{"id":3755,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":499,"q":"Non-parasitic eosinophilia is caused by infection with -","o":["Staphylococcus","Ehrlischia","Coccidioidomycosis","Candidiasis"],"a":2,"e":"Ans. is ''c'' i.e.,Coccidioidomycosis [Ref Diagnostic hematology p. 332] \"One of the very few non-parasitic infections that regularly cause eosinophilia is Coccidioidomycosis, a fungal infection. atypical pneumonia","pyqMatches":[{"year":"2016","no":786,"q":"Non-parasitic eosinophilia is caused by infection with","o":["Staphylococcus","Ehrlischia","Coccidioidomycosis","Candidiasis"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3756, 'Microbiology', 'Mycology', 'Easy', 'Microbiology', 500, '{"id":3756,"subject":"Microbiology","chapter":"Mycology","difficulty":"Easy","source":"Microbiology","sourceNo":500,"q":"Candidias of penis is ?","o":["Thrush","Leukoplakia","Balanitis","None"],"a":2,"e":"Ans. is ''c'' i.e.,Balanitis [Ref Essentials of medical microbiology p. 712] Candidal infections are identified by their location on the body as follows : Axillae, under pendulous breasts, groin, intergluteal folds : intertrigo. Glans penis : balanitis Follicular pustules : candidal folliculitis Nail folds : candidal paronychia Mouth and tongue : oral cnadidiasis (thrush) Area included under diaper -diaper dermatitis","pyqMatches":[{"year":"2016","no":785,"q":"Candidias of penis is ?","o":["Thrush","Leukoplakia","Balanitis","None"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3757, 'Microbiology', 'General Microbiology', 'Moderate', 'Microbiology', 501, '{"id":3757,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Moderate","source":"Microbiology","sourceNo":501,"q":"All culture media are used for antibiotic susceptibility except -","o":["Tetrathionate-F","Blood agar","Chocolate agar","Muller-Hinton agar"],"a":0,"e":"Ans. is ''a'' i.e., Tetrathionate-F * The Kirby-Bauer disk diffusion method is one of the most widely practiced antimicrobial susceptibility tests (AST). * It is affected by many factors among which are the media used. * Mueller-Hinton agar (MHA) is the standard medium recommended in guidelines. * Mueller-Hinton has a few properties that make it excellent for antibiotic use. ... - Starch is known to absorb toxins released from bacteria, so that they cannot interfere with the antibiotics. - Second, it is a loose agar. This allows for better diffusion of the antibiotics than most other plates.","pyqMatches":[{"year":"2016","no":684,"q":"All culture media are used for antibiotic susceptibility except","o":["Tetrathionate-F","Blood agar","Chocolate agar","Muller-Hinton agar"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3758, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 502, '{"id":3758,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":502,"q":"Cellulitis surrounding diabetic ulcer is mostly caused by ?","o":["Streptococcus pyogenes","Staphylococcus","Mixed organisms","Pseudomonas"],"a":2,"e":"Ans. is ''c'' i.e., Mixed organisms [Ref Essentials of medical microbilogy p. 712] \"A mixture of gram-positive cocci and gram-negative acrobes and anaerobes is often implicated in cellulitis surrounding diabetic and decubitus ulcers\".","pyqMatches":[{"year":"2016","no":784,"q":"Cellulitis surrounding diabetic ulcer is mostly caused by ?","o":["Streptococcus pyogenes","Staphylococcus","Mixed organisms","Pseudomonas"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3759, 'Microbiology', 'Bacteriology', 'Moderate', 'Microbiology', 503, '{"id":3759,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Moderate","source":"Microbiology","sourceNo":503,"q":"A paitent operated for transurethral resection of prostate [TURP] develops UTI. The organism most commonly grown on culture will be -","o":["Proteus","E. coli","Pseudomonas","Listeria"],"a":1,"e":"Ans. is ''b'' i.e., E. coli [Ref www.jcam.com] Most common organism causing UTI after transurethral prostectomy is E coli.","pyqMatches":[{"year":"2016","no":783,"q":"A paitent operated for transurethral resection of prostate [TURP] develops UTI. The organism most commonly grown on culture will be","o":["Proteus","E. coli","Pseudomonas","Listeria"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3760, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 504, '{"id":3760,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":504,"q":"Loeffer''s serum is an example of","o":["Basal medium","Simple medium","Complex medium","Enrichment medium"],"a":2,"e":"Ans. is ''c'' i.e., Complex medium [Ref Ananthanarayan 8th/e.p. 140] Loeffler''s medium is an enriched medium → A type of special (complex) medium.","pyqMatches":[{"year":"2016","no":685,"q":"Loeffer''s serum is an example of","o":["Basal medium","Simple medium","Complex medium","Enrichment medium"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3761, 'Microbiology', 'Bacteriology', 'Moderate', 'Microbiology', 505, '{"id":3761,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Moderate","source":"Microbiology","sourceNo":505,"q":"Most common organism grown in urine culture of pregnant woman with asymptomatic bacteriuria?","o":["Proteus","E. coli","Staph aureus","Pseudomonas"],"a":1,"e":"Ans. is ''b'' i.e., E. coli Asymptomatic bacteriuria is the presence of bacteria in a voided urine sample and is caused by bacterial colonization of the urinary tract. It affects about 5 to 10 percent of both sexually active and pregnant women. Asymptomatic bacteriuria is less prevalent in men. As the name indicates, asymptomatic bacteriuria does not cause symptoms. The condition simply refers to the detection of bacteria in a urine sample. Nonetheless, there is good reason to be concerned about this infection, particularly if you are pregnant, because it can lead to a symptomatic upper urinary tract infection (namely, pyelonephritis), which can complicate pregnancy. Bacteria are typically introduced into the urinary tract during intercourse or when wiping after a bowel movement. The bacterium E. coli is responsible for at least 75 to 80 percent of asymptomatic bacteriuria. Klebsiella pneumoniea, Proteus species, staphylococcal species, enterococci, and group B streptococci can also establish colonization.","pyqMatches":[{"year":"2016","no":782,"q":"Most common organism grown in urine culture of pregnant woman with asymptomatic bacteriuria?","o":["Proteus","E. coli","Staph aureus","Pseudomonas"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3762, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 506, '{"id":3762,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":506,"q":"To create anaerobiosis which organism is used","o":["Micrococcus","Clostridium","B. anthracis","Corynebacterium"],"a":0,"e":"Ans. is ''a'' i.e., Micrococcus Obligate aerobic micrococcus is used to create anaerobic condition (anaerobiosis). The micrococcus and the anaerobic organism to be cultivated are both inoculated into the same liquid medium. During incubation the Micrococcus gradually utilizes the free oxygen creating conditions favorable for the growth of anaerobe. After anaerobiosis is achieved, the micrococcus dies (due to lack of oxygen) leaving the anaerobe in pure culture.","pyqMatches":[{"year":"2016","no":686,"q":"To create anaerobiosis which organism is used","o":["Micrococcus","Clostridium","B. anthracis","Corynebacterium"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3763, 'Microbiology', 'Bacteriology', 'Moderate', 'Microbiology', 507, '{"id":3763,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Moderate","source":"Microbiology","sourceNo":507,"q":"A 30 years old male is having prpductive cough with dysnea. Blood gas analysis shows low pa02. Chest x-ray is showing reticulonodular pattern. The causative agent is?","o":["Staph aureus","Pneumococcus","P. jerovecii","Pseudomonas"],"a":2,"e":"Ans. is ''c'' i.e., P. jerovecii [Ref Read below] Reticulo-nodular shadow is seen in interstitial pneumonia. Among the given options P jerovecii is a cause of interstitial pneumonia. Other three options are causes of airspace pneumonia. \"Pneumocystis Carinii pneumonia produces a diffuse, symmetric, fine-to-medium reticulonodular pattern\".","pyqMatches":[{"year":"2016","no":781,"q":"A 30 years old male is having prpductive cough with dysnea. Blood gas analysis shows low pa02. Chest x-ray is showing reticulonodular pattern. The causative agent is?","o":["Staph aureus","Pneumococcus","P. jerovecii","Pseudomonas"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3764, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 508, '{"id":3764,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":508,"q":"Which of the following is a method of Pasteurization","o":["Vat method","Pasteur method","Billing method","Flash method"],"a":0,"e":":D Ans. is ''a & d'' i.e., Vat method & Flash method [Ref Park 23ra/e p. 655] Pasteurization is done to destroy the pathogens in milk. It kills nearly 90% of bacteria in milk, including more heat resistant tubercular bacilli and Q-fever organism. However, thermoduric bacteria and spores are not killed. There are following methods of pasteurization :? A) Holder method (Vat method) Milk is kept at 63-66° C for 30 minutes and then rapidly cooled to 5°C. B) High temperature short time (HTST) method It is also called Flash method. Milk is heated to 72°C for 15 seconds and then rapidly cooled to 4°C. It is now the most widely used method. C) Ultra-high temperature (UHT) method Milk is rapidly heated in two stages to 125° C for few seconds, 2\"d stage being under pressure. It is then rapidly cooled. Method Remarks Holder/Vat Method For small and rural communities HTST (flash) Most widely used for large HTST (flash) Method Most widely used, for large quantities UHT Method Heating in 2 stages 2''d stage under pressure","pyqMatches":[{"year":"2016","no":688,"q":"Which of the following is a method of Pasteurization","o":["Vat method","Pasteur method","Billing method","Flash method"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3765, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 509, '{"id":3765,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":509,"q":"Temperature used in Tyndallizaton","o":["40°C","60°C","80°C","100°C"],"a":3,"e":"Ans. is ''d'' i.e., 100°C [Ref Ananthanarayan 9thie p. 31 & trie p. 33] Tyndallization (intermittent sterilization) Media containing sugar or gelatin are sterilized by heating at 100°C for 20 minutes on three successive days. First exposure kills all vegetative bacteria. Spores germinate and are killed on subsequent exposures","pyqMatches":[{"year":"2016","no":689,"q":"Temperature used in Tyndallizaton","o":["40°C","60°C","80°C","100°C"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3766, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 510, '{"id":3766,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":510,"q":"Nutrient agar heated at 80°C used for","o":["Spore germination","To grow mesophilic bacteria","To grow thermophilic bacteria","For clostridium isolation"],"a":0,"e":":D Ans. is ''a'' > ''d'' i.e., Spore germination > For clostridium isolation Heating for 20 minutes at 80 degrees centigrade destroys vegetative cells and activates the spores for germination. This method can be used to cultivate anaerobic spore-forming organisms (e.g. clostridium) About options a & c Microorganisms can be grouped into broad (but not very precise) categories, according to their temperature ranges for growth. Psychrophiles (cold-loving) can grow at 0°C, and some even as low as -10°C; their upper limit is often about 25°C. Mesophlles grow in the moderate temperature range, from about 20°C (or lower) to 45°C. Thermophiles are heat-loving, with an optimum growth temperature of 50° or more, a maximum of up to 70°C or more, and a minimum of about 20°C. Hyperthermophiles have an optimum above 75°C and thus can grow at the highest temperatures tolerated by any organism. An extreme example is the genus Pyrodictium, found on geothermally heated areas of the sea bed. It has a temperature minimum of 82°, an optimum of 105° and a growth maximum of 110°C.","pyqMatches":[{"year":"2016","no":692,"q":"Nutrient agar heated at 80°C used for","o":["Spore germination","To grow mesophilic bacteria","To grow thermophilic bacteria","For clostridium isolation"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3767, 'Microbiology', 'Clinical Microbiology', 'Easy', 'Microbiology', 511, '{"id":3767,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":511,"q":"Involutional form are seen in which phase of bacterial growth","o":["Lag phase","Log phase","Stationary phase","Death phase"],"a":3,"e":"Ans. is ''d'' i.e., Death phase [Ref Ananthanarayan 94Ve p. 22] Bacterial growth is the division of one bacterium into two daughter cells in a process called binary fission. Providing no mutational event occurs, the resulting daughter cells are genetically identical to the original cell. Hence \"Local doubling\" of the bacterial population occurs. Bacteria have a distinct pattern of growth when a bacterium is seeded into a suitable liquid medium and incubated, its growth follows a definite course.","pyqMatches":[{"year":"2016","no":693,"q":"Involutional form are seen in which phase of bacterial growth","o":["Lag phase","Log phase","Stationary phase","Death phase"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3768, 'Microbiology', 'Clinical Microbiology', 'Hard', 'Microbiology', 512, '{"id":3768,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Hard","source":"Microbiology","sourceNo":512,"q":"A patient is presenting with recurrent staphylococcal infection, kyphoscoliosis and typical faces. The patient is suffering from ?","o":["Ig A deficiency","Hyper IgE syndrome","Common variable immunodeficiency","Burton''s Agammaglobulinemia"],"a":1,"e":"Ans. is ''b'' i.e., Hyper IgE syndrome Job''s syndrome (Hyper-IgE syndrome) Job''s syndrome, also called Hyper-IgE syndrome or Hyperimmunoglobulin E syndrome, is an autosomal dominant disorder due to mutations in Signal Transducer and Activator of Transcription-3 (STAT-3). There is defect in phagocytosis. IgE levels are elevated. Other immunoglobulins are normal. Clinical manifestations include staphylococcal cold abscess, otitis media, recurrent sinopulmonary and skin infections, and cavitary pneumonia with pneumatoceles. Beside infections, other findings are characteristic facies with brood nose, osteoporosis, kyphoscoliosis, cerebral.","pyqMatches":[{"year":"2016","no":778,"q":"A patient is presenting with recurrent staphylococcal infection, kyphoscoliosis and typical faces. The patient is suffering from ?","o":["Ig A deficiency","Hyper IgE syndrome","Common variable immunodeficiency","Burton''s Agammaglobulinemia"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3769, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 513, '{"id":3769,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":513,"q":"Partial acid fast organism is","o":["M. tuberculosis","M. Bovis","Nocardia","None"],"a":2,"e":"Ans. is ''c'' i.e., Nocardia [Ref Concise Review of microbiology p. 13] Portial acid fast means, organism which is shows less affinity for primary stain, thus less concentrated H2So4 (instead of 20% H2So4) is used for decolorization of primary stain (Carbol fuschin). Partial acid fast bacteria are M leprae (5% H,SO4), and Nocardia (0.5% H2SO4)","pyqMatches":[{"year":"2016","no":694,"q":"Partial acid fast organism is","o":["M. tuberculosis","M. Bovis","Nocardia","None"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3770, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 514, '{"id":3770,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":514,"q":"Resolving power of electron microscope","o":["1-5 mm","1-5 um","1-5 nm","1-5 A°"],"a":3,"e":"Ans. is ''d'' i.e.,1-5 Ae [Ref Essentials of medical microbiology]","pyqMatches":[{"year":"2016","no":695,"q":"Resolving power of electron microscope","o":["1-5 mm","1-5 um","1-5 nm","1-5 A°"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3771, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 515, '{"id":3771,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":515,"q":"Most effective antibody for precipitation ?","o":["IgM","IgG","IgA","IgD"],"a":1,"e":"Ans. is ''b'' i.e., IgG [Ref Harrison 19th/e p. 372 & 18th/e p. 2674; Ananthanarayan 9thie p. 98 & 8th/e p. 98] IgM is more effective than IgG for:","pyqMatches":[{"year":"2016","no":776,"q":"Most effective antibody for precipitation ?","o":["IgM","IgG","IgA","IgD"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3772, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 516, '{"id":3772,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":516,"q":"Specificity of antibody is dependent on ?","o":["Fc portion","Fab region","Carboxy terminal","All of the above"],"a":1,"e":"Ans. is ''b'' i.e., Fab region [Ref: Harrison 19th/e p. 372; Ananthanarayan 9thie p. 100] The infinite range of the antibody specificity of immunoglobulins depends on the variability of the aminoacid sequences at the variable units of H and L chains. Variable region is present on Fab region.","pyqMatches":[{"year":"2016","no":775,"q":"Specificity of antibody is dependent on ?","o":["Fc portion","Fab region","Carboxy terminal","All of the above"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3773, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 517, '{"id":3773,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":517,"q":"Classification of staphylococcus is based on -","o":["Catalase test","Coagulase test","Mannitol fermentation","Optochin sensitivity"],"a":1,"e":"Ans. is ''b'' i.e., Coagulase test Medically important staphylococci that cause human disease are divided into two groups:? Coagulase positive: Staphylococcus aureus. Coagulase-negative: Staphylococcus epidermidis, Staphylococcus haemolyticus, Staphylococcus saprophyticus.","pyqMatches":[{"year":"2016","no":696,"q":"Classification of staphylococcus is based on","o":["Catalase test","Coagulase test","Mannitol fermentation","Optochin sensitivity"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3774, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 518, '{"id":3774,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":518,"q":"Antibody specificity is due to ?","o":["Amino acid sequence at H chain","Amino acid sequence at L chain","Amino acid at carboxy terminal","Amino acid sequence at the amino terminal"],"a":0,"e":":B:D Ans. is ''d > a & b'' i.e., Amino acid sequence at amino terminal > Amino acid sequence at H chain & Amino acid sequence at L chain [Ref Read below] Antibody specificity is due to variability of the aminoacid sequences at the variable unit (at aminoterminal) of both H and L chains (not only H or L chains).","pyqMatches":[{"year":"2016","no":773,"q":"Antibody specificity is due to ?","o":["Amino acid sequence at H chain","Amino acid sequence at L chain","Amino acid at carboxy terminal","Amino acid sequence at the amino terminal"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3775, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 519, '{"id":3775,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":519,"q":"Iron helps in virulence of which organism","o":["Streptococcus pyogenes","Pneumococcus","Staphylococcus aureus","Pseudomonas"],"a":2,"e":"Ans. is ''c'' i.e., Staphylococcus aureus Staphylococcus aureus causes a significant amount of human morbidity and mortality. The ability of S.aureus to cause disease is dependent upon its acquisition of iron from the host. S. aureus can obtain iron from various sources during infection, including haem and transferrin. The most abundant iron source in humans is haem iron bound by haemoglobin contained within erythrocytes. S. aureus is known to lyre erythrocytes through secretion of pore- forming toxins, providing access to host haemoglobin. Proteins of the iron-regulated surface determinant (Isd) system bind host hemoproteins, remove the haem cofactor, and shuttle haem into the cytoplasm for use as a nutrient iron source. Deletion of Isd system components decreases staphylococcal virulence, underscoring the importance of haem iron acquisition during infection. In addition to haem, S. aureus can utilize transferrin iron through the secretion of siderophores. Several staphylococcal siderophores have been described, some of which have defined roles during the pathogenesis of staphylococcal infections.","pyqMatches":[{"year":"2016","no":697,"q":"Iron helps in virulence of which organism","o":["Streptococcus pyogenes","Pneumococcus","Staphylococcus aureus","Pseudomonas"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3776, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 520, '{"id":3776,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":520,"q":"Wool-Sorter disease is caused by","o":["Pseudomonas","Bacillus anthracis","Vibrio parahemolyticus","Spirillus minor"],"a":1,"e":"Ans. is ''b'' i.e., Bacillus anthracis [Ref Harrison 19(h/e p. 261; Ananthnarayan /e p. 246] Bacillus Anthracis is the causative organism of anthrax. In human, anthrax occurs in following forms ? Cutaneous anthrax (Hide porter''s disease) It is the most common form of anthrax. It is a painless lesion and is called charbon or malignant pustule. It generally resolves spontaneously, but 10-20% of untreated patients may develop fatal septicemia. Pulmonary anthrax (Wool sorter''s disease) It follows inhalation of dust from infected wool. It presents as hemorrhagic pneumonia. Intestinal anthrax is rarest form.","pyqMatches":[{"year":"2016","no":701,"q":"Wool-Sorter disease is caused by","o":["Pseudomonas","Bacillus anthracis","Vibrio parahemolyticus","Spirillus minor"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3777, 'Microbiology', 'Mycology', 'Moderate', 'Microbiology', 521, '{"id":3777,"subject":"Microbiology","chapter":"Mycology","difficulty":"Moderate","source":"Microbiology","sourceNo":521,"q":"Not true about sporothrix Schenckii ?","o":["Dimorphic fungus","Asteroid bodies","Copper penny bodies","Common in gardners"],"a":2,"e":"Ans. is ''c'' i.e.,Copper penny bodies [Ref Harrison 19th/e p. 1353] Copper penny bodies are seen in chromoblastomycosis. Sporothrix Schenckii Sporothrix Schenckii is a dimorphic fungus. The organism (sporothrix schenckii) are usually described as tiny, cigar-shaped bodies, 3-5 microns in length, which bear from one to three small oval buds at either or both pales. Occasionally a larger asteroid body may be seen. Because S. schenckii naturally found in soil, hay, sphagnum moss, and plants, it usually affects farmers, gardeners, and agricultural workers. This fungal disease usually affects the skin although rare forms can affect the lungs, joints, bones and CNS. Fungus enters through small cuts and abrasions in the skin to cause the infection. Because roses can spread the disease, it is one of a few diseases referred to as rose-thorn or rose gardener''s disease.","pyqMatches":[{"year":"2016","no":772,"q":"Not true about sporothrix Schenckii ?","o":["Dimorphic fungus","Asteroid bodies","Copper penny bodies","Common in gardners"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3778, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 522, '{"id":3778,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":522,"q":"Fishy odour is found on growth of which organism","o":["Proteus","Pseudomonas","Yersinia pseudotuberculosis","Yersinia pestis"],"a":0,"e":"Ans. is ''a'' i.e., Proteus Proteus is part of the normal flora of the human gastrointestinal tract. It can also be found free-living in water and soil. When this organism, however, enters the urinary tract, wounds, or the lungs it can become pathogenic Culture of proteus bacilli has a characteristic putrefactive odor described as ''fishy or seminal\". Rotten cooked fishy odor: Proteus mirabilis produces a very distinct fishy odor. On Salmonella-Shigella (SS) agar, Proteus usually smells like “rotten cooked fish”.","pyqMatches":[{"year":"2016","no":704,"q":"Fishy odour is found on growth of which organism","o":["Proteus","Pseudomonas","Yersinia pseudotuberculosis","Yersinia pestis"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3779, 'Microbiology', 'Mycology', 'Easy', 'Microbiology', 523, '{"id":3779,"subject":"Microbiology","chapter":"Mycology","difficulty":"Easy","source":"Microbiology","sourceNo":523,"q":"Lipophilic fungus is ?","o":["Malassezia furfur","Candida","Cryptococcus","Histoplasma"],"a":0,"e":"Ans. is ''a'' i.e., Malassezia furfur [Ref Principles of medical microbiology p. 781] Malassezia furfur (Pityrosporum ovale) is a lipopphilic fungus that is found in areas of the body that are rich in sebaceous glands. This fungus causes tinea versicolor (pityriasis versicolor).","pyqMatches":[{"year":"2016","no":771,"q":"Lipophilic fungus is ?","o":["Malassezia furfur","Candida","Cryptococcus","Histoplasma"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3780, 'Microbiology', 'Mycology', 'Hard', 'Microbiology', 524, '{"id":3780,"subject":"Microbiology","chapter":"Mycology","difficulty":"Hard","source":"Microbiology","sourceNo":524,"q":"A 60 years old farmer has developed swelling on the sole of foot with discharging yellow granules. The diagnosis is -","o":["Fungal mycetoma","Eumycetoma","Actinomycosis","Candidiasis"],"a":2,"e":"Ans. is ''c'' i.e., Actinomycosis Mycetoma Is a localized chronic granulomatous involvement of the subcutaneous and deeper tissues, commonly affecting the foot and less often the hand and other parts. Presenting as a subcutaneous swelling with multiple discharging sinuses. Sinuses discharge seropurulent fluid containing granules. These granules are microcolonies of the etiological agents. Mycetoma can be caused by both fungus and bacteria","pyqMatches":[{"year":"2016","no":770,"q":"A 60 years old farmer has developed swelling on the sole of foot with discharging yellow granules. The diagnosis is","o":["Fungal mycetoma","Eumycetoma","Actinomycosis","Candidiasis"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3781, 'Microbiology', 'Clinical Microbiology', 'Easy', 'Microbiology', 525, '{"id":3781,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":525,"q":"Rapid detection of meningococal meningitis is","o":["Blood culture","CSF culture","PCR","None"],"a":2,"e":"Ans. is ''c'' i.e., PCR [Ref Basic in microbiology p. 719] \"PCR assay can be performed rapidly with a turnaround time of 2 hour from intiation of DNA extraction to the issuing of reports\". Laboratory diagnosis of meningococci Specimens used are CSF (for cases), nasopharyngeal swab (for carrier), blood (in meningococcemia & early meningitis), and petechial lesions (in meningococcemia). Best specimen for case 4 CSF (by lumbar puncture). Best specimen for carrier 4 Naspharyngeal swab.","pyqMatches":[{"year":"2016","no":706,"q":"Rapid detection of meningococal meningitis is","o":["Blood culture","CSF culture","PCR","None"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3782, 'Microbiology', 'Clinical Microbiology', 'Hard', 'Microbiology', 526, '{"id":3782,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Hard","source":"Microbiology","sourceNo":526,"q":"Presumptive diagnosis of meningococcal meningitis is made earliest by -","o":["CSF culture","PCR","Latex agglutination","CFT"],"a":2,"e":"Ans. is ''c'' i.e., Latex agglutination [Ref Essentials of medical microbiologyr3 d/e p. 412] In combination with a clinical picture CSF examination consistent with bacterial meningitis, a presumptive diagnosis of bacterial meningitis caused by N. meningitidis, S. pneumoniae, or H. influenzae can by made after performing a Gram stain of the CSF sediment or by detection of specific antigens in the CSF by a latex agglutination test or using RDTs. Positive results for any of these tests can rapidly provide evidence of infection even if cultures fail to grow. PCR and CSF culture are used for definitive diagnosis (not presumptive diagnosis)","pyqMatches":[{"year":"2016","no":707,"q":"Presumptive diagnosis of meningococcal meningitis is made earliest by","o":["CSF culture","PCR","Latex agglutination","CFT"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3783, 'Microbiology', 'Mycology', 'Easy', 'Microbiology', 527, '{"id":3783,"subject":"Microbiology","chapter":"Mycology","difficulty":"Easy","source":"Microbiology","sourceNo":527,"q":"Chlamydospore is formed by ?","o":["Candida albicans","Candida pscitasi","Histoplasma","Cryptococcus"],"a":0,"e":"Ans. is ''a'' i.e.,Candida albicans [Ref Ananthanarayan 8thle p. 607- 608] All candida species pathogenic for humans are also encountered as commensals of humans, particularly in the mouth, stool and vagina. They grow rapidly on simple media as oval budding cells at 25° to 37°C. In tissue, both yeasts and pseudohyphae are present. Candida albicans is differentiated by other candida : It forms true hyphae (mycelia) or germ tubes when grown in serum. It forms thick walled large spores called chlamydospores when grown in corn meal agar. It is dimorphic.","pyqMatches":[{"year":"2016","no":766,"q":"Chlamydospore is formed by ?","o":["Candida albicans","Candida pscitasi","Histoplasma","Cryptococcus"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3784, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 528, '{"id":3784,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":528,"q":"Sewer swabs are taken to detect","o":["Typhoid cases in community","Cholera cases in community","Typhoid carriers in community","Cholera carriers in community"],"a":2,"e":"Ans. is ''c'' i.e., Typhoid carriers in community [Ref Textbook of practical Microbiology p. 721] Typhoid carriers are detected by Sewer-swab method''. The use of sewer swabs enables premises to be screened for the possibility of the existence of a salmonella problem more quickly and more easily than by the examination of many end-of-line samples. In the event of salmonellae being found, a return visit can be paid and detailed samples taken to attempt to defect the source of contamination.","pyqMatches":[{"year":"2016","no":710,"q":"Sewer swabs are taken to detect","o":["Typhoid cases in community","Cholera cases in community","Typhoid carriers in community","Cholera carriers in community"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3785, 'Microbiology', 'Mycology', 'Easy', 'Microbiology', 529, '{"id":3785,"subject":"Microbiology","chapter":"Mycology","difficulty":"Easy","source":"Microbiology","sourceNo":529,"q":"Aspergillus fumigatus is differentiated by other fungi by ?","o":["Showing septate hyphae","Grow at 45°C","Cause respiratory tract infection","Most common endemic mycosis"],"a":1,"e":"Ans. is ''b'' i.e., Grow at 45°C [Ref Harrison 19thie p. 1346; Ananthanarayan 8th/e p. 613] Aspergillus is a mould with septate branching hyphae. Ability of A. fumigatus to grow at 45° C helps to distinguish it from other species. Mode of transmission - Inhalation of Aspergillus spores (Conidia) into lungs. The commonest human disease caused by aspergillus is otomycosis. Aspergillus infection in neutropenic patient is characterized by hyphal invasion of blood vessels, thrombosis, necrosis and hemorrhagic infarction","pyqMatches":[{"year":"2016","no":765,"q":"Aspergillus fumigatus is differentiated by other fungi by ?","o":["Showing septate hyphae","Grow at 45°C","Cause respiratory tract infection","Most common endemic mycosis"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3786, 'Microbiology', 'Clinical Microbiology', 'Easy', 'Microbiology', 530, '{"id":3786,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":530,"q":"Species of shigella causing arthritis","o":["Sh dysenteriae-1","Sh sonnei","Sh flexneri","Sh boydii"],"a":2,"e":"Ans. is ''c'' i.e., Sh flexneri [Ref Harrison 18th/e p. 945] Shigella is highly communicable. The infective dose for shigella is less. It can be as low as 10-100 bacilli because they survive gastric acidity better than other enterobacteriae. Shigellae produce follwing clinical features. 1) Intestinal : These are :- Dysentery : Most common cause is Sh dyenteriae typel. Diarrhea : Usually by Sh Sonnei. 2) Extraintestinal : These are hemolytic uremic syndrome (caused by Sh dysenteriae-I), arthritis (Sh flexneri), seizures (Sh flexneri), pneumonia and Reiter syndrome (in HLA B27 association).","pyqMatches":[{"year":"2016","no":711,"q":"Species of shigella causing arthritis","o":["Sh dysenteriae-1","Sh sonnei","Sh flexneri","Sh boydii"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3787, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 531, '{"id":3787,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":531,"q":"Ectothrix is caused by ?","o":["T tansurans","T violaceum","Microsporum canis","All of the above"],"a":2,"e":"Ans. is ''c'' i.e., Microsporum canis [Ref: Greenwood 16thie p. 574] Tinea capitis is dermatophytic infection of scalp and scalp hair. Occurs commonly in children. It is uncommon in adults (in contrast, T.crusis, T.manuum and T.unguium are common in adults). Caused by genera trichophyton or microsporum. As epidermophyton does not affect the hair, Epidermophyton does not cause T.capitis. Two most common species causing T-Capitis are M.canis & T. tonsurans. Tinea capitis may be two types.","pyqMatches":[{"year":"2016","no":764,"q":"Ectothrix is caused by ?","o":["T tansurans","T violaceum","Microsporum canis","All of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3788, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 532, '{"id":3788,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":532,"q":"Griffth classification is base on","o":["''C''-carbohydrate","M, T, R antigens","Type of hemolysis","0, requirment"],"a":1,"e":"Ans. is ''b'' i.e., M, T, R antigens [Ref Ananthanarayan 9th/e p. 209, 210] Group ''A'' strep. are further subdivided into types based on the protein (M, T and R) antigens present on the cell surface (Griffith typing). About 80 types of str. pyogenes have been recognized.","pyqMatches":[{"year":"2016","no":712,"q":"Griffth classification is base on","o":["''C''-carbohydrate","M, T, R antigens","Type of hemolysis","0, requirment"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3789, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 533, '{"id":3789,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":533,"q":"Sabouraud''s dextrose [glucose] agar is used for isolation of -","o":["Pseudomonas","B. Antracis","Fungi","Ancylostome"],"a":2,"e":"Ans. is ''c'' i.e.,Fungi [Ref Greenwood 10/e p. 570; Ananthanarayan 8th/e p. 601] Culture media used in mycology are :","pyqMatches":[{"year":"2016","no":761,"q":"Sabouraud''s dextrose [glucose] agar is used for isolation of","o":["Pseudomonas","B. Antracis","Fungi","Ancylostome"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3790, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 534, '{"id":3790,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":534,"q":"Similarity between chlamydia and virus is","o":["Filterable through filter","Ability to grow in cell free media","Contains both DNA and RNA","All of the above"],"a":0,"e":"Ans. is ''a'' i.e.,Filterable through filter [Ref Textbook of microbiology by Parija p. 418] Chlamydiae were thought to be viruses because (like viruses) they : Pass through 0.45 ym filters. Are obligate intracellular parasite - cannot be grown in cell free media.","pyqMatches":[{"year":"2016","no":714,"q":"Similarity between chlamydia and virus is","o":["Filterable through filter","Ability to grow in cell free media","Contains both DNA and RNA","All of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3791, 'Microbiology', 'Bacteriology', 'Hard', 'Microbiology', 535, '{"id":3791,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Hard","source":"Microbiology","sourceNo":535,"q":"Bloody diarrhea in HIV infected patient is mostly due to ?","o":["Cryptosporidium","Isospora","CMV","Salmonella"],"a":2,"e":"Ans. is ''c'' i.e.,CMV [Ref www.medscape.com] The most common of the opportunistic infections that cause diarrhea in patients with AIDS are CMV infection, cryptosporidiosis, microsporidiosis, and MAC infection. CMV infection is the most common opportunistic viral infection in the GI tract of HIV-infected patients and can cause problems from the mouth to the anus. It most frequently causes a colitis associated with fever, crampy abdominal pain, and frequent (often bloody) stools.","pyqMatches":[{"year":"2016","no":760,"q":"Bloody diarrhea in HIV infected patient is mostly due to ?","o":["Cryptosporidium","Isospora","CMV","Salmonella"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3792, 'Microbiology', 'Immunology', 'Moderate', 'Microbiology', 536, '{"id":3792,"subject":"Microbiology","chapter":"Immunology","difficulty":"Moderate","source":"Microbiology","sourceNo":536,"q":"Which test cannot differentiate endemic and epidemic typhus","o":["Weil-Felix reaction","Complement fixation test","Immunofluorescence","Radio precipitation"],"a":0,"e":"Ans. is ''a'' i.e., Weil-Felix reaction Both epidemic typhus and endemic typhus are positive for OX-19 antigen → Thus Weil Felix reaction cannot differentiate between the two. Weil-Felix reaction This reaction is an agglutination test in which sera are tested for agglutinins to 0 antigens of certain nonmotile proteus strains OX- 19, OX - 2 and OX - K. The basis of the test is the sharing of an alkali - stable carbohydrate antigen by some rickettsiae and by certain strains of proteus, P. vulgaris OX - 19 and OX - 2 and P. mirabilis OX - K. The test is usually done as a tube agglutination, though rapid slide agglutination methods have been employed for screening.","pyqMatches":[{"year":"2016","no":716,"q":"Which test cannot differentiate endemic and epidemic typhus","o":["Weil-Felix reaction","Complement fixation test","Immunofluorescence","Radio precipitation"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3793, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 537, '{"id":3793,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":537,"q":"CCR5 mutation is related to which condition ?","o":["Resistance to HIV infection","Susceptibility to HIV infection","Resistance to HBV infection","Susceptibility to HBV infection"],"a":0,"e":"Ans. is ''a'' i.e., Resistance to HIV infection [Ref www.lumenlearning.com] In recent years, scientific interest has been piqued by the discovery of a few individuals from northern Europe who are resistant to HIV infection in 1998, American geneticist Stephen J. O''Brien at the National Institutes of Health (NIH) and colleagues published the result of their genetic analysis of more than 4,000 individuals. These indicated that many individuals of Eurasian descent (up to 14% in some ethnic groups) have a deletion mutation, called CCR5 delta 32, in the gene encoding CCR5 is a coreceptor found on the surface of T cells that is necessary for many strains of the virus to enter the host cell. The mutation leads to the production of a receptor to which HIV cannot effectively bind and thus blocks viral people homozygous for this mutation have greatly reduced susceptibility to HIV infection, and those who are heterozygous have some protection from infection as well.","pyqMatches":[{"year":"2016","no":758,"q":"CCR5 mutation is related to which condition ?","o":["Resistance to HIV infection","Susceptibility to HIV infection","Resistance to HBV infection","Susceptibility to HBV infection"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3794, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 538, '{"id":3794,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":538,"q":"E. coli subtypes are divided on the basis of","o":["Lactose fermentation","Virulence properties","Somatic 0 antigen","Maltose fermentation"],"a":1,"e":"Ans. is ''b'' i.e., Virulence properties [Ref en wikipedia.org] Enteric E.coli (EC) are classified on the basis of serological characteristics and virulence properties :? Enteropathogenic E. coli (Enteroadherent E coli) Enterohemorrhagic E.coli or verotoxigenic E.coli Enterotoxigenic E. coli Enteroaggregative E. coli Enteroinvasive E. coli","pyqMatches":[{"year":"2016","no":717,"q":"E. coli subtypes are divided on the basis of","o":["Lactose fermentation","Virulence properties","Somatic 0 antigen","Maltose fermentation"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3795, 'Microbiology', 'Virology', 'Moderate', 'Microbiology', 539, '{"id":3795,"subject":"Microbiology","chapter":"Virology","difficulty":"Moderate","source":"Microbiology","sourceNo":539,"q":"True about rhabdoviridae are all except ?","o":["Includes vesculostomatitis virus","Rabies virus is inactivated by formalin","Rabies virus is negative sense double stranded RNA virus","All of the above correct"],"a":2,"e":"Ans. is ''c'' i.e., Rabies virus is negative sense double stranded RNA virus Rhabdoviridae contains two genera :?","pyqMatches":[{"year":"2016","no":756,"q":"True about rhabdoviridae are all except ?","o":["Includes vesculostomatitis virus","Rabies virus is inactivated by formalin","Rabies virus is negative sense double stranded RNA virus","All of the above correct"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3796, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 540, '{"id":3796,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":540,"q":"ELISA test for virulence antigen is used for which type of E coli","o":["ETEC","EIEC","EHEC","EAEC"],"a":1,"e":"Ans. is ''b'' i.e., EIEC [Ref Ananthnarayan 9th/e p. 279] For laboratory diagnosis of EIEC, the Sereny test used to be employed (that is, instillation of suspension of freshly isolated EIEC or shigella into the eyes of guinea pigs leads to mucopurulent conjunctivities and severe keratitis). Mice may be used instead of guinea pigs. Cell penetration of HeLa or HEP-2 cells in culture is a more humane diagnostic test. This ability to penetrate cells is determined by a large plasmid, detection of which can also be a diagnostic test. The plasmid codes for outer membrane antigens called the ''virulence marker antigens'' (VMA) which can be detected by the ELISA (VMA ELISA) test.","pyqMatches":[{"year":"2016","no":719,"q":"ELISA test for virulence antigen is used for which type of E coli","o":["ETEC","EIEC","EHEC","EAEC"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3797, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 541, '{"id":3797,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":541,"q":"E. coli infection occur in which enzyme defect","o":["Lactase","Pyruvate kinase","Pepsin","Trypsin"],"a":1,"e":"Ans. is ''b'' i.e., Pyruvate kinase [Ref Hardcore microbiology & immunology by Benjamin W Sears p. 133] Opportunistic infections is immunodeficiency due to defect in myeloid cells are :- Staph aureus Klebsiella Pneumococcus E. coli Neisseria Candida Conditions causing defect in myeloid cells are :? Chronic granulomatous disease Chediak-Higashi syndrome G6PD and pyruvate kinase deficiency Myeloperoxidase deficiency","pyqMatches":[{"year":"2016","no":720,"q":"E. coli infection occur in which enzyme defect","o":["Lactase","Pyruvate kinase","Pepsin","Trypsin"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3798, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 542, '{"id":3798,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":542,"q":"Culture media containing potassium tellurite","o":["TCBS medium","Monsur medium","BYCE medium","Muller Hinton agar"],"a":1,"e":"Ans. is ''b'' i.e., Monsur medium [Ref Fundamental principles of bacteriology p. 129] Monsur''s GTTA medium is Monsur''s gelatin tourocholate trypticase tellurite agar. Selective media for vibrio cholarae TCBS medium (pH 8.6) : This medium contains thiosulfate, citrate, bile salts, sucrose, and bromothymol blue (indicator). V. cholerae produces large, yellow convex colonies on this medium. This is due to fermentation of sucrose by the bacteria, leading to production of acid. Accumulation of acid reduces pH of the medium, and so the color of the bromothymol blue indicator becomes yellow, thus making V. cholerae colonies yellow. Non sucrose-fermenting V. parahaemolyricus produces blue green colonies. Monsur''s GTTA medium (pH 8.5): High pH of the medium and presence of potassium tellurite in this medium inhibits most of Gram positive bacteria and enteric bacteria with exception of proteus species. Hence, the GTTA medium is used for isolation of V. cholerae and other vibrios from feces. V. cholerae produces small translucent colonies with grayish black cencer and a turbid halo after 24 hours of incubation. The colonies become larger (3-4 mm in size) after a prolonged incubation of 48 hours. Alkaline BSA (pH 8.2) : This is another selective medium used for V. cholerae. The colonies on BSA are similar to those on nutrient agar.","pyqMatches":[{"year":"2016","no":721,"q":"Culture media containing potassium tellurite","o":["TCBS medium","Monsur medium","BYCE medium","Muller Hinton agar"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3799, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 543, '{"id":3799,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":543,"q":"Borrelia causes which of the following","o":["Weil''s disease","Bejels","Vincent angina","Yaws"],"a":2,"e":"Ans. is ''c'' i.e., Vincent angina Three important diseases caused by Borreliae are :? Lyme disease : Caused by B. burgdorferi Relapsing fever : Caused by B. recurrentis, B duttoni, B. hermsii, B. Parkeri, B. turicatae, B. persica, B. hispanica. Vincent''s angina : Caused by B. vincenti.","pyqMatches":[{"year":"2016","no":722,"q":"Borrelia causes which of the following","o":["Weil''s disease","Bejels","Vincent angina","Yaws"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3800, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 544, '{"id":3800,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":544,"q":"Zika virus causes ?","o":["Hepatitis","Myocarditis","Conjunctivitis","None of these"],"a":2,"e":"Ans. is ''c'' i.e., Conjunctivitis Zika virus (ZIKV) is a flavivirus related to yellow fever virus. It is transmitted by Aedes mosquito. Zika virus disease (Zika) is a disease caused by the Zika virus, which is spread to people primarily through the bite of an infected","pyqMatches":[{"year":"2016","no":753,"q":"Zika virus causes ?","o":["Hepatitis","Myocarditis","Conjunctivitis","None of these"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3801, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 545, '{"id":3801,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":545,"q":"What is similar between rotavirus and Norwalk virus ?","o":["Both belong to same family","Both have segmented genome","Both have single stranded RNA","Both are causes of viral gastroenteritis"],"a":3,"e":"Ans. is ''d'' i.e., Both are causes of viral gastroenteritis [Ref Essentials of Microbiology p. 497] Rota virus belongs to reoviridae → double stranded segmented RNA. Norwalk virus belongs to calciviridae → Single stranded non segmented RNA. Both Rota virus and Norwalk virus are causes of viral gastroenteritis","pyqMatches":[{"year":"2016","no":752,"q":"What is similar between rotavirus and Norwalk virus ?","o":["Both belong to same family","Both have segmented genome","Both have single stranded RNA","Both are causes of viral gastroenteritis"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3802, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 546, '{"id":3802,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":546,"q":"Rota-teq oral vaccine for rotavirus contains ?","o":["2 reassorted rotaviruses","3 reassorted rotaviruses","4 reassorted rotaviruses","5 reassorted rotaviruses"],"a":3,"e":"Ans. is ''d'' i.e., 5 reassorted rotaviruses [Ref Essential of medical microbiology p. 932] Rota-virus vaccine The Rotavirus vaccines are live -attenuated vaccines given orally. Two new vaccines are now in use -","pyqMatches":[{"year":"2016","no":751,"q":"Rota-teq oral vaccine for rotavirus contains ?","o":["2 reassorted rotaviruses","3 reassorted rotaviruses","4 reassorted rotaviruses","5 reassorted rotaviruses"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3803, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 547, '{"id":3803,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":547,"q":"Core antigen [HBO in HBV is encloded by which gene ?","o":["S","C","P","X"],"a":1,"e":"Ans. is `b'' i.e., C [Ref Ananthanarayan 9th/e p. 544] The genome of HBV is made of circular DNA, but it is unusual because the DNA is not fully double stranded -> one of the strands is incomplete and other is complete 4 partially double stranded DNA. There are four known genes encoded by genome - ''C'' , X'', ''P'' ,''S''. P gene is the largest gene.. X-gene codes for HBx Ag, which can transactivate the transcription of cellular and viral genes and may contribute to carcinogenesis. HBx Ag and its antibody are present in patients with severe chronic hepatitis and hepatocellular carcinoma.","pyqMatches":[{"year":"2016","no":748,"q":"Core antigen [HBO in HBV is encloded by which gene ?","o":["S","C","P","X"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3804, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 548, '{"id":3804,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":548,"q":"Which of the following is Hepadnavirus ?","o":["HAV��","HBV","HCV","HDV"],"a":1,"e":"Ans. is ''b'' i.e., HBV�[Ref Ananthnarayan 9th/e p. 549 & 8thle p. 545]","pyqMatches":[{"year":"2016","no":747,"q":"Which of the following is Hepadnavirus ?","o":["HAV��","HBV","HCV","HDV"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3805, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 549, '{"id":3805,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":549,"q":"HSV-2 causes latent infection in which nerve plexus/ ganglia ?","o":["Trigeminal ganglion","Otic ganglion","Sacral ganglion","Ciliary ganglion"],"a":2,"e":"Ans. is ''c'' i.e., Sacral ganglion [Ref Essentials of medical microbiology 3''/e p. 1215] Site of latency HSV-1→ Trigeminal ganglion. HSV-2 → Sacral ganglion.","pyqMatches":[{"year":"2016","no":746,"q":"HSV-2 causes latent infection in which nerve plexus/ ganglia ?","o":["Trigeminal ganglion","Otic ganglion","Sacral ganglion","Ciliary ganglion"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3806, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 550, '{"id":3806,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":550,"q":"Hand foot mouth disease is caused by ?","o":["Enterovirus -70","Coxsackie - A virus","Coxsackie - B virus","Enterovirus"],"a":1,"e":"Ans. is ''b'' i.e., Coxsackie -A virus [Ref Greenwood le/e p. 459; Ananthanarayan 9th/e p. 491] There are two types of Coxsackie viruses :","pyqMatches":[{"year":"2016","no":743,"q":"Hand foot mouth disease is caused by ?","o":["Enterovirus -70","Coxsackie - A virus","Coxsackie - B virus","Enterovirus"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3807, 'Microbiology', 'Virology', 'Moderate', 'Microbiology', 551, '{"id":3807,"subject":"Microbiology","chapter":"Virology","difficulty":"Moderate","source":"Microbiology","sourceNo":551,"q":"All viruses are associated with specific inclusion body, except ?","o":["CMV","Malluscum contagiosum","EBV","Yellow fever"],"a":2,"e":"Ans. is ''c'' i.e., EBV [Ref Essentials of medical microbiology p. 791]","pyqMatches":[{"year":"2016","no":742,"q":"All viruses are associated with specific inclusion body, except ?","o":["CMV","Malluscum contagiosum","EBV","Yellow fever"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3808, 'Microbiology', 'Miscellaneous', 'Moderate', 'Microbiology', 552, '{"id":3808,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Microbiology","sourceNo":552,"q":"Intermediate host is not required for which parasite -","o":["Toxoplasma","Schistosoma","Ancylostoma","Fish tapeworm"],"a":2,"e":"Ans. is ''c'' i.e., Ancylostoma [Ref Rajesh Karykarte p. 7] The sequential stages in growth, development and multiplication constitute its life cycle","pyqMatches":[{"year":"2016","no":739,"q":"Intermediate host is not required for which parasite","o":["Toxoplasma","Schistosoma","Ancylostoma","Fish tapeworm"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3809, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 553, '{"id":3809,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":553,"q":"Generation time for M tuberculosis","o":["10-15 min","10-15 hours","10-15 days","5-10 days"],"a":1,"e":"Ans. is ''b'' i.e., 10-15 hours [Ref Ananthanarayan 8th/e p. 365] Generation time of lepra bacillus → 4 12-13 days Generation time of tubercle bacillus → 14 hours Generation time of coliform bacilli → 20 minutes","pyqMatches":[{"year":"2016","no":724,"q":"Generation time for M tuberculosis","o":["10-15 min","10-15 hours","10-15 days","5-10 days"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3810, 'Microbiology', 'Parasitology', 'Easy', 'Microbiology', 554, '{"id":3810,"subject":"Microbiology","chapter":"Parasitology","difficulty":"Easy","source":"Microbiology","sourceNo":554,"q":"Maurer''s dots are seen in which species of plasmodium?","o":["P ovale","P vivax","P falciparum","P malariae"],"a":2,"e":"Ans. is ''c'' i.e., P. falciparum [Ref Chatterjee 12th/e p. 79-80] P. vivax → Schuffner''s dot P. malariae → Ziemann''s stippling, P. falciparum → Maurer''s dot P.ovale → Schuffner''s dot","pyqMatches":[{"year":"2016","no":737,"q":"Maurer''s dots are seen in which species of plasmodium?","o":["P ovale","P vivax","P falciparum","P malariae"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3811, 'Microbiology', 'Parasitology', 'Hard', 'Microbiology', 555, '{"id":3811,"subject":"Microbiology","chapter":"Parasitology","difficulty":"Hard","source":"Microbiology","sourceNo":555,"q":"Which stage of Leishmania is found in spleen aspirate of patient ?","o":["Amastigote�","Promastigote","Epimastigote� �","Trypomastigote"],"a":0,"e":"Ans. is ''a'' i.e., Amastigote�[Ref Essentials of parasitology�p.�122] Amastigote forms, also known as Leishmania donovani bodies, are found intracellularly in tissues like liver, spleen and bone marrow. A positive bone marrow or spleen aspiration for L.donovani bodies provides confirmation of diagnosis.","pyqMatches":[{"year":"2016","no":736,"q":"Which stage of Leishmania is found in spleen aspirate of patient ?","o":["Amastigote�","Promastigote","Epimastigote� �","Trypomastigote"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3812, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 556, '{"id":3812,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":556,"q":"Adherence of E. histolytica to colonic mucosa is mediated by ?","o":["Fibronectin","Lectin","Collagen","Fucose"],"a":1,"e":"Ans. is ''b'' i.e., Lectin [Ref www.pathologyoutlines.com] Pathophysiology of E. histolytica infection Cyst are ingested from fecally contaminated food or water, sexual transmission also occurs. Excystation to 8 motile trophozoites occurs in the small intestine The cysts are resistant to gastric acid (and chlorine in water supplies). Trophozoites are potentially invasive and multiply by binary fission. In an estimated 20% of infections invasion into the wall of the colon with tissue destruction occurs. Adherence to colonic mucosa is mediated by a lectin on E. histolytics''s surface. The parasite then induces apoptosis of epithelial cells through a channel forming pore protein E. histolytica ingests remnant cells. Some trophozoites undergo encystation through signalling pathways completing the cycle.","pyqMatches":[{"year":"2016","no":733,"q":"Adherence of E. histolytica to colonic mucosa is mediated by ?","o":["Fibronectin","Lectin","Collagen","Fucose"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3813, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 557, '{"id":3813,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":557,"q":"Pulmonary eosinophilia is found in infection with ?","o":["Babesia","Malaria","Strongyloides","Trypanosoma"],"a":2,"e":"Ans. is ''c'' i.e., Strongyloides [Ref Harrison 18th/e p. 2120 & 17th/e p. 1610] Ascaris Strongyloides stercoralis Ancylostoma (hook worm) Wuchereria bancrofti or W. malayi Toxocara","pyqMatches":[{"year":"2016","no":732,"q":"Pulmonary eosinophilia is found in infection with ?","o":["Babesia","Malaria","Strongyloides","Trypanosoma"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3814, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 558, '{"id":3814,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":558,"q":"Cyst with scolex and hooks is seen in","o":["T. saginatu","Fish tapeworm","Echinococcus","H. diminuta"],"a":2,"e":"Ans. is ''c'' i.e., Echinococcus [Ref: Clinical parasitology 3rd/e p. 315] First one must understand the meaning of scolex. Scolex is pear- shaped or knoblike head of cystodes (tapeworms). Scolex is covered with suckers and hooks :-","pyqMatches":[{"year":"2016","no":730,"q":"Cyst with scolex and hooks is seen in","o":["T. saginatu","Fish tapeworm","Echinococcus","H. diminuta"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3815, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 559, '{"id":3815,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":559,"q":"E. coli is differentiated by E histolytica by presence of","o":["Very active movement","Thin nuclear membrane","Cyst with 1-4 nuclei","Blunt pseudopodia"],"a":3,"e":"Ans. is ''d'' i.e., Blunt pseudopodia [Ref: Essentials of medical parasitology p. 37]","pyqMatches":[{"year":"2016","no":731,"q":"E. coli is differentiated by E histolytica by presence of","o":["Very active movement","Thin nuclear membrane","Cyst with 1-4 nuclei","Blunt pseudopodia"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3816, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 560, '{"id":3816,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":560,"q":"Example of transfer of drug resistance by conjugation -","o":["Staphylococci to rifampicin","Pneumococcus to penicillin G","M tuberculosis to antitubercular drugs","E coli to streptomycin"],"a":3,"e":"Ans. is ''d'' i.e., E coli to streptomycin [Ref Basics in laboratory microbiology p. 781] Drug resistance It refers to unresponsiveness of a microorganism to an antimicrobial. Drug resistance may be acquired by :","pyqMatches":[{"year":"2015","no":686,"q":"Example of transfer of drug resistance by conjugation","o":["Staphylococci to rifampicin","Pneumococcus to penicillin G","M tuberculosis to antitubercular drugs","E coli to streptomycin"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3817, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 561, '{"id":3817,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":561,"q":"Shadow casting is used in -","o":["Light microscopy","Electron microscopy","Optical microscopy","Fluoroscence microspopy"],"a":1,"e":"Ans. is ''b'' i.e., Electron microscopy [Ref Cell and molecular biology p.726] Two standard methods of staining in electron microscopy are :","pyqMatches":[{"year":"2015","no":689,"q":"Shadow casting is used in","o":["Light microscopy","Electron microscopy","Optical microscopy","Fluoroscence microspopy"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3818, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 562, '{"id":3818,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":562,"q":"Frozen phenomenon is used for -","o":["Sterilization of heat sensitive material","Killing thermophilic bacteria","Preservation of microorganisms","Stimulating metabolism of microorganism"],"a":2,"e":"Ans. is ''c'' i.e., Preservation of microorganisms [Ref Microbiology Application Based Approach p. 189] Some psychrophilic bacteria can grow at 0°C, but subzero temperatures will inhibit the metabolism of microorganism in general. Freezing is commonly used to preserve foods, drugs and laboratory specimens because it effectively stops microbial growth. However, subzero temperature may not kill microorganism (especially psychrophilic) and may in fact preserve them along with the material being frozen. This phenomenon has been used by microbiologists to store and preserve microorganisms.","pyqMatches":[{"year":"2015","no":692,"q":"Frozen phenomenon is used for","o":["Sterilization of heat sensitive material","Killing thermophilic bacteria","Preservation of microorganisms","Stimulating metabolism of microorganism"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3819, 'Microbiology', 'Virology', 'Moderate', 'Microbiology', 563, '{"id":3819,"subject":"Microbiology","chapter":"Virology","difficulty":"Moderate","source":"Microbiology","sourceNo":563,"q":"True about universal precautions are all except -","o":["To prevent transmission of blood borne pathogens","Includes use of hand washing","Consider that all body fluids are contaminated with blood","Includes use of gloves and masks"],"a":1,"e":"Ans. is ''b'' i.e., Includes use of hand washing [Ref Microbiology for surgical techniques p. 796] Hand washing is a part of standard precautions not universal precautions Universal precautions Universal precautions is an approach to infection control to treat all human blood and certain human body fluids as if they were known to be infectious with HIV, HBV and other blood borne pathogens. Blood borne pathogen standard requires. Employees to observe ''universal precautions''to prevent contact with blood or other potentially infectious material (OPIM) Treat all blood and OPIM with proper precautions like use of gloves, masks and gown. Other potentially infectious material includes :","pyqMatches":[{"year":"2015","no":693,"q":"True about universal precautions are all except","o":["To prevent transmission of blood borne pathogens","Includes use of hand washing","Consider that all body fluids are contaminated with blood","Includes use of gloves and masks"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3820, 'Microbiology', 'Virology', 'Moderate', 'Microbiology', 564, '{"id":3820,"subject":"Microbiology","chapter":"Virology","difficulty":"Moderate","source":"Microbiology","sourceNo":564,"q":"Nucleic acid is not found in -","o":["Virus","bacteria","Fungus","Prions"],"a":3,"e":"Ans. is ''d'' i.e., Prions [Ref Harrison 19'' /e p. 451 & 17th/e p.2647] Prions are infectious particle which contains protein only. They do not have nucleic acid.","pyqMatches":[{"year":"2015","no":694,"q":"Nucleic acid is not found in","o":["Virus","bacteria","Fungus","Prions"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3821, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 565, '{"id":3821,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":565,"q":"Oil paint appearance on nutrient agar is seen in -","o":["Streptococcus pyogenes","Staphylococcus aureus","Bordtella pertussis","H. influenzae"],"a":1,"e":"Ans. is ''b'' i.e., Staphylococcus aureus Staphylococcus is facultative anaerobe. Optimum pH for growth is 7.4 - 7.6 and optimum temperature is 37°C. Staph aureus produces golden yellow pigment, which is maximum at 22°C. Most of the staphylococcus species grow in the presence of 10% NaCl","pyqMatches":[{"year":"2015","no":706,"q":"Oil paint appearance on nutrient agar is seen in","o":["Streptococcus pyogenes","Staphylococcus aureus","Bordtella pertussis","H. influenzae"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3822, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 566, '{"id":3822,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":566,"q":"Streptococcal pneumoniae pneumonia present at -","o":["< 5 years","5 - 15 years","20 - 25 years","30 - 40 years"],"a":0,"e":"Ans. is ''a'' i.e., < 5 years [Ref: Textbook of Microbiology by Parija p.197] Streptococcus pneumoniae is the leading cause of pneumonia, both lobar and bronchopneumonia. Pneumonia is common at the extereme of ages : Children (especially < 5 years of age) Elderly (> 60-65 years) Serotypes 6, 14, 18, 19 and 23 are responsible for most cases of pneumonia in children, while serotypes 1, 3, 4, 7, 8 and 12 cause pneumonia in adults.","pyqMatches":[{"year":"2015","no":707,"q":"Streptococcal pneumoniae pneumonia present at","o":["< 5 years","5 - 15 years","20 - 25 years","30 - 40 years"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3823, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 567, '{"id":3823,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":567,"q":"Most common age group affected by streptococcus pyogenes -","o":["< 5 years","5 - 15 years","20 - 25 years","30 - 40 years"],"a":1,"e":"Ans. is ''b'' i.e., 5 - 15 years [Ref Parija p. 191] Sore throat (tonsillitis) is the most common manifestation of streptococcal infection and affects 5-15 years age group.","pyqMatches":[{"year":"2015","no":708,"q":"Most common age group affected by streptococcus pyogenes","o":["< 5 years","5 - 15 years","20 - 25 years","30 - 40 years"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3824, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 568, '{"id":3824,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":568,"q":"Oropharyngeal commensal which predisposes to candidiasis -","o":["Hemophilus influenzae","Streptococcus","Staphylococcus","Lactobacillus"],"a":1,"e":"Ans. is ''b'' i.e., Streptococcus [Ref Textbook of polymicrobial disease - Chapter 18] An example of the complexity of coaggregation may be the range of intergeneric coaggregations occuring between the oral fungal pathogen candida albicans and other oral species that may play an important role in the colonization of the oral cavity by candida albicans. Although streptococcal species, namely, streptococcus gordonii, streptococcus oralis and streptococcus sanguins, exhibit the highest affinities for C albicans, C albicans (as well as Candida dubliniensis) have been shown to coaggregate with Fusobacterium species in suspension. Actinomyces has also been shown to coaggreate with candida albicans.","pyqMatches":[{"year":"2015","no":710,"q":"Oropharyngeal commensal which predisposes to candidiasis","o":["Hemophilus influenzae","Streptococcus","Staphylococcus","Lactobacillus"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3825, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 569, '{"id":3825,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":569,"q":"Hemophilus parainfluenzae requres -","o":["Factor V","Factor X","Factor V & X","Factor VII"],"a":0,"e":"Ans. is ''a'' i.e., Factor V [Ref: Ananthanaran 9\" /e p. 327 & 8thie p. 330] H. influenzae, H. aegyptius, H. haemolyticus → Factor X & V. H. Parainfluenzae, H. Parahemolyticus, H. Paraphrophilus → Factor V. H. ducreyi, H. aphrophilus → Factor X.","pyqMatches":[{"year":"2015","no":712,"q":"Hemophilus parainfluenzae requres","o":["Factor V","Factor X","Factor V & X","Factor VII"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3826, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 570, '{"id":3826,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":570,"q":"Most sensitive test in syphilis -","o":["VDRL","TP-PA","RPR","FTA-ABS"],"a":1,"e":"Ans. is ''b'' i.e., TP-PA [Ref Harrison Mole p. 1137, 1138 e.7 18th/e p. 1385, Ananthanarayan 9th/e p. 374, 375 & p. 374-78] TPPA is the most sensitive serological test overall (considering all stages of syphilis). All the serological tests have 100% sensitivity in secondary stage of syphilis Test Primary Secondary Latent Tertiary VDRL / RPR 78 (74- 87) 100 95 (88- 100) 71 (37- 94) FTA - ABS 84 (70- 100) 100 100 96 TP – PA 89 100 100 NA","pyqMatches":[{"year":"2015","no":727,"q":"Most sensitive test in syphilis","o":["VDRL","TP-PA","RPR","FTA-ABS"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3827, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 571, '{"id":3827,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":571,"q":"Fresh water swimming leads to infection by -","o":["Bordetella pertussis","Corynebacterium diphtheriae","M tuberculosis","Pseudomonas"],"a":3,"e":"Ans. is `d'' i.e., Pseudomonas [Ref Alcamo''s fundamentals of microbiology p. 669] \"Extended swimming in fresh water pools can irritate and break down skin in the ear canal allowing bacteria such as pseudomonas, staphylococcus or streptococcus to penetrate and cause otitis externa\" Pseudomonas is the most common cause of swimmer''s ear infection. Pseudomonas also causes \"hot tub rash\" syndrome or hot-tub folliculitis, associated with use of hot tub, less commonly associated with whirlpools or swimming pools.","pyqMatches":[{"year":"2015","no":731,"q":"Fresh water swimming leads to infection by","o":["Bordetella pertussis","Corynebacterium diphtheriae","M tuberculosis","Pseudomonas"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3828, 'Microbiology', 'Clinical Microbiology', 'Easy', 'Microbiology', 572, '{"id":3828,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":572,"q":"Most common complication of diphtheria is -","o":["Myocarditis","Pneumonia","Meningitis","Endocarditis"],"a":0,"e":"Ans. is ''a'' i.e., Myocorditis [Ref With text] \"Myocarditis is the most common complication of diphtheria and the leading cause of death in diphtheric cases, whose incidence is 10- 25%\" Essentials in Microbiology \"Complications of diphtheria include myocarditis (the most common complication), thrombocytopenia, vocal card paralysis and neuritis\" → Clinical microbiology. \"Most common complications of diphtheria are myocarditis and toxic neuritis\" → NMS Two most common complications of diphtheria are :","pyqMatches":[{"year":"2015","no":733,"q":"Most common complication of diphtheria is","o":["Myocarditis","Pneumonia","Meningitis","Endocarditis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3829, 'Microbiology', 'General Microbiology', 'Moderate', 'Microbiology', 573, '{"id":3829,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Moderate","source":"Microbiology","sourceNo":573,"q":"All are true about anaerobic infection except -","o":["Most infections are endogenous","Exudates and swabs are best for culture","Specimen for UTI is suprapubic aspiration","They are found normally on skin and GIT"],"a":1,"e":"Ans. is ''b'' i.e., Exudates and swabs are best for culture [Ref Essentials of microbiology p.224] Most anaerobic bacteria that cause infection are members of our normal indigenous flora and anaerobic infections are usually endogenous, caused by tissue invosion by bacteria normally resisdent or respective body surfaces. Anaerobic bacteria are normally present on skin, mouth, nasopharynx, upper respiratory tract, gut and vagina. Ideal specimens for anaerobic cultures are samples of needle aspirates and proper tissue specimens. Anaerobic swabs are usually discouraged. Important specimens are :-","pyqMatches":[{"year":"2015","no":734,"q":"All are true about anaerobic infection except","o":["Most infections are endogenous","Exudates and swabs are best for culture","Specimen for UTI is suprapubic aspiration","They are found normally on skin and GIT"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3830, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 574, '{"id":3830,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":574,"q":"Most common route of infection in pasteurella cellulitis -","o":["Animal bites or scratches","Aerosols or dust","Contaminated tissue","Human to human"],"a":0,"e":"Ans. is ''a'' i.e., Animal bites or scratches [Ref Ananthanarayan 9th le p. 325; 7h/e p. 326; Harrison 19thle p. 830 & le/e p. 1235] Transmission to humans may occur by two routes? 1) Direct inoculation through skin The most common mode of transmission of P.microcida is direct inoculation by a bite or scratch. Most of the infections are caused by cats. Infection may also occur via deposition of organism on injured skin or mucosal surfaces during licking. 2) Through the respiratory tract This is the second most common mode of transmission. Infection via the respiratory tract occurs from contact with contaminated dust or infectious droplets (aerosol dust).","pyqMatches":[{"year":"2015","no":735,"q":"Most common route of infection in pasteurella cellulitis","o":["Animal bites or scratches","Aerosols or dust","Contaminated tissue","Human to human"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3831, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 575, '{"id":3831,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":575,"q":"Non-motile bacterium is -","o":["Vibrio","Clostridium septicum","Clostridium perfringens","Legionella"],"a":2,"e":"Ans. is ''c'' i.e., Clostridium perfringens [Ref Ananthanarayan 9th/e p.262, 263, 252-257] All clostridia are motile by peritrichous flagella except C/ tetani VI and Cl perfringens which are non-motile.","pyqMatches":[{"year":"2015","no":743,"q":"Non-motile bacterium is","o":["Vibrio","Clostridium septicum","Clostridium perfringens","Legionella"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3832, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 576, '{"id":3832,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":576,"q":"Ehrlichia phagocytophila mainly affects -","o":["RBC","Platelets","Neutrophils","Macrophages"],"a":2,"e":"Ans. is ''c'' i.e., Neutrophils [Ref Essentials of clinical microbiology p. 712] Anaplasma phagocytophilum (formerly known as Ehrlichia phagocytophila) is a causative agent of tick-borne fever in sheep and pasture fever in cattle. It is an obligate intracellular bacterium whose main target is neutrophils but it can also infect monocytes.","pyqMatches":[{"year":"2015","no":747,"q":"Ehrlichia phagocytophila mainly affects","o":["RBC","Platelets","Neutrophils","Macrophages"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3833, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 577, '{"id":3833,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":577,"q":"Which viral gene acts as carcinogen in causing carcinoma cervix -","o":["P 24 - gene","E - gene","L - gene","H - gene"],"a":1,"e":"Ans. is ''b'' i.e., E-gene [Ref Harrison 150/e p. 1199-1200] HPV is the most important cause of cervical cancer. Products of E-genes (E6, E7) are related to immortalization or malignant transformation of keratinocytes by interfering with p53 and Rb genes, respectively","pyqMatches":[{"year":"2015","no":757,"q":"Which viral gene acts as carcinogen in causing carcinoma cervix","o":["P 24 - gene","E - gene","L - gene","H - gene"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3834, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 578, '{"id":3834,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":578,"q":"Which of the following can infect ovary -","o":["Mumps virus","EBV","CMV","Measles virus"],"a":0,"e":"Ans. is ''a'' i.e., Mumps virus [Ref Clinical microbiology p. 273] Mumps begins as a primary infection in the respiratory tract and spreads by viremia to glandular tissues including the salivary glands, pancreas, testes and ovaries.","pyqMatches":[{"year":"2015","no":760,"q":"Which of the following can infect ovary","o":["Mumps virus","EBV","CMV","Measles virus"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3835, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 579, '{"id":3835,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":579,"q":"Integration of viral genome into host cell chromosome can leads to -","o":["Malignancy","Latency","Altered growth","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above [Ref Clinical microbiology p. 312] Integration of viral genomes into host cell chromosome can cause alteration in :","pyqMatches":[{"year":"2015","no":762,"q":"Integration of viral genome into host cell chromosome can leads to","o":["Malignancy","Latency","Altered growth","All of the above"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3836, 'Microbiology', 'Virology', 'Moderate', 'Microbiology', 580, '{"id":3836,"subject":"Microbiology","chapter":"Virology","difficulty":"Moderate","source":"Microbiology","sourceNo":580,"q":"Not true about paramyxoviruses -","o":["Belong to family myxovirus","Are DNA viruses","Have linear nucleic acid","Antigenically stable"],"a":1,"e":"Ans. is ''b'' i.e., Are DNA viruses [Ref Ananthanarayan 9`h/e p. 497-498] Myxoviruses are enveloped RNA viruses. They are characterized by ability to adsorb on to mucoprotein (affinity for mucin) on erythrocytes causing agglutination of erythocytes. Major route of infection of all these virus is respiratory route by droplet infection. Myxovirus are divided into two important families ?","pyqMatches":[{"year":"2015","no":763,"q":"Not true about paramyxoviruses","o":["Belong to family myxovirus","Are DNA viruses","Have linear nucleic acid","Antigenically stable"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3837, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 581, '{"id":3837,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":581,"q":"HTLV-1 can be transmitted by -","o":["Blood transfusion","Droplet inhalation","Contaminated water","Animal bite"],"a":0,"e":"Ans. is ''a'' i.e., Blood transfusion [Ref Manual of clinical microbiology Vol.1 p.1131] HTLV-1 and HTLV-2 infections are transmitted by?","pyqMatches":[{"year":"2015","no":764,"q":"HTLV-1 can be transmitted by","o":["Blood transfusion","Droplet inhalation","Contaminated water","Animal bite"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3838, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 582, '{"id":3838,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":582,"q":"Thymus dependent area in spleen -","o":["Mantel layer","Perifollicular region","Malphigian corpuscle","All of the above"],"a":2,"e":"Ans. is ''c'' i.e., Malphigian corpuscle Thymus dependent (T- cells collect)","pyqMatches":[{"year":"2015","no":773,"q":"Thymus dependent area in spleen","o":["Mantel layer","Perifollicular region","Malphigian corpuscle","All of the above"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3839, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 583, '{"id":3839,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":583,"q":"Precipitation in comparison to agglutination requires -","o":["Less pH","High temperature","Specific enzyme","Soluble antigen"],"a":3,"e":"Ans. is ''d'' i.e.,Soluble antigen [Ref Ananthanarayan 9tVe p. 105]merav","pyqMatches":[{"year":"2015","no":774,"q":"Precipitation in comparison to agglutination requires","o":["Less pH","High temperature","Specific enzyme","Soluble antigen"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3840, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 584, '{"id":3840,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":584,"q":"Common variable deficiency is due to -","o":["Absent B cells","Reduced number of B cells","Defective B cell differentiation","All of the above"],"a":2,"e":"Ans. is ''c'' i.e., Defective B cell differentiation [Ref: Robbin''s 9m/e p. 241 & 8th/e p. 233] Most patients with common variable immunodeficiency have normal or near-normal numbers of B cells in the blood and lymphoid tissues. These B cells, however, are not able to differentiate into plasma cells. The clinical manifestations are caused by antibody deficiency. The feature common to all patients is hypogammaglobulinemia, generally affecting all the antibody classes but sometimes only IgG.","pyqMatches":[{"year":"2015","no":807,"q":"Common variable deficiency is due to","o":["Absent B cells","Reduced number of B cells","Defective B cell differentiation","All of the above"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3841, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 585, '{"id":3841,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":585,"q":"CD3 is a marker for?","o":["B - cells","T - cells","NK - cells","Monocytes"],"a":1,"e":"Ans. is ''b'' i.e., T - cells [Ref : Robbin''s 9th/e p. 590 & 8`5/e p. 600 table (13.5)] CD-3 is known as Pan T-cell marker.","pyqMatches":[{"year":"2015","no":806,"q":"CD3 is a marker for?","o":["B - cells","T - cells","NK - cells","Monocytes"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3842, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 586, '{"id":3842,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":586,"q":"In Rideal walker method, plates are incubated for ?","o":["< 2 days","2-3 days","6-8 days","> 10 days"],"a":1,"e":"Ans. is ''b'' i.e., 2-3 days [Ref Textbook of sterilization e.7 disinfection p.233] In Rideal walker method, for checking efficiency of disinfectant, bactericidal activity is determined against salmonella typhi suspension. Subcultures are performed from both the test and phenol at intervals of 2.5, 5, 7.5 and 10 minutes. The plates are incubated for 48-72 hours at 37°C.","pyqMatches":[{"year":"2015","no":805,"q":"In Rideal walker method, plates are incubated for ?","o":["< 2 days","2-3 days","6-8 days","> 10 days"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3843, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 587, '{"id":3843,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":587,"q":"ABO non- secretors are more prone to ?","o":["Infection","Autoimmunity","Heart disease","Carcinoma"],"a":0,"e":":B:C Ans. is ''a'' i.e., Infection, ''b'' i.e., Autoimmunity & ''c'' i.e.,Heart disease [Ref www.dadamo.com] There are two types of people (independent of blood group) Secretor: These persons secrete their blood group antigen into other body fluids like saliva etc. Nonseretor: They do not secrete their blood group antigen into body fluids. Non-secretors appear to have an increase in prevalence of a variety of autoimmune disease like ankylosing spondylitis, reactive arthritis, Graves disease and Sjogren''s syndrome. Non - secretors are at a greater risk of developing diabetes, MI and heart disease. Non-secretors are at a greater risk for recurrent urinary tract infections and candida infection. Non-secretors have more oral diseases and more digestive problems.","pyqMatches":[{"year":"2015","no":804,"q":"ABO non- secretors are more prone to ?","o":["Infection","Autoimmunity","Heart disease","Carcinoma"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3844, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 588, '{"id":3844,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":588,"q":"Rose waaler test is -","o":["Complement fixation test","Pricipitation in gel","Ring precipitation","Passive hemagglutination test"],"a":3,"e":"Ans. is ''d'' i.e., Passive hemogglutination test [Ref Ananthanarayan 8th /e p. 107, 108, Harrison 18th/e p. 1469, 1470]","pyqMatches":[{"year":"2015","no":776,"q":"Rose waaler test is","o":["Complement fixation test","Pricipitation in gel","Ring precipitation","Passive hemagglutination test"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3845, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 589, '{"id":3845,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":589,"q":"Prevention of catheter induced urinary tract infection is by ?","o":["Prophylactic antibiotics","Use of face mask","Closed drainage technique","All of the above"],"a":2,"e":"Ans. is ''c'' i.e., Closed drainage technique [Ref Microbiology in clinical practice p.450] Prevention of catheter-associated infection depends on:","pyqMatches":[{"year":"2015","no":801,"q":"Prevention of catheter induced urinary tract infection is by ?","o":["Prophylactic antibiotics","Use of face mask","Closed drainage technique","All of the above"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3846, 'Microbiology', 'Clinical Microbiology', 'Easy', 'Microbiology', 590, '{"id":3846,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":590,"q":"Example of precipitation test is","o":["Rose waaler test","Widal test","Latex agglutination","Kahn test"],"a":3,"e":"Ans. is ''d'' i.e., Kahn test It is a Heterophile tube agglutination test, used to diagnose Rickettsiae.","pyqMatches":[{"year":"2015","no":779,"q":"Example of precipitation test is","o":["Rose waaler test","Widal test","Latex agglutination","Kahn test"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3847, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 591, '{"id":3847,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":591,"q":"Morula form is seen in which infection ?","o":["Chlamydiae","Bartonella quintana","Mycoplasma hominis","Ehrlichia"],"a":3,"e":"Ans. is ''d'' i.e.,Ehrlichia [Ref Ananthanarayan h le p. 409; Vasanthakumari p.310] Ehrlichiae graw within phagosomes of phagocytes as mulberry-like clusters called morula.","pyqMatches":[{"year":"2015","no":799,"q":"Morula form is seen in which infection ?","o":["Chlamydiae","Bartonella quintana","Mycoplasma hominis","Ehrlichia"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3848, 'Microbiology', 'Miscellaneous', 'Moderate', 'Microbiology', 592, '{"id":3848,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Microbiology","sourceNo":592,"q":"Which of the following is not an in vivo test ?","o":["Elek''s gel precipitation test","Schick test","Lepromin test","Tuberculin test"],"a":0,"e":"Ans. is ''a'' i.e., Elek''s gel precipitation test [Ref Read below] Elek''s gel precipitation is an in vitro test for toxigenicity of C diphtheriae. Other three options are skin tests (i.e. in vivo tests).","pyqMatches":[{"year":"2015","no":797,"q":"Which of the following is not an in vivo test ?","o":["Elek''s gel precipitation test","Schick test","Lepromin test","Tuberculin test"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3849, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 593, '{"id":3849,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":593,"q":"Primory T-cell deficiency is -","o":["Ecto- 5'' nucleotidase deficiency","Common variable immunodeficiency","DiGeorge syndrome","Wiskott-Aldrich syndrome"],"a":2,"e":"Ans. is ''c'' i.e.,Di George syndrome [Ref: Atlas of immunology p. 537] I. Cellular immunodeficiencies (T cell defects)","pyqMatches":[{"year":"2015","no":781,"q":"Primory T-cell deficiency is","o":["Ecto- 5'' nucleotidase deficiency","Common variable immunodeficiency","DiGeorge syndrome","Wiskott-Aldrich syndrome"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3850, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 594, '{"id":3850,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":594,"q":"Monoclonal antibody binds to ?","o":["Epitope","Paratope","Both epitope and paratope","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Epitope [Ref : Ananthanarayan 9th/e p. 88 & 71* p. 81; Harrison 18thie p. 2673 & 17th/e p. 2036] Epitope Also known as \"antigenic determinant\". It is antibody binding site of antigen.","pyqMatches":[{"year":"2015","no":794,"q":"Monoclonal antibody binds to ?","o":["Epitope","Paratope","Both epitope and paratope","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3851, 'Microbiology', 'Clinical Microbiology', 'Easy', 'Microbiology', 595, '{"id":3851,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":595,"q":"Oakley - fulthorpe procedure is -","o":["Agglutination test","Precipitation test","Single diffusion in one dimension","Double diffusion in one dimension"],"a":1,"e":":D Ans. is ''d > b'' i.e., Double diffusion in one dimension > Precipitation test [Ref: Ananthanarayan 9th/e p. 105] Immunodiffusion tests are precipitation reaction in gels. Important examples of immunodiffusion test are :-","pyqMatches":[{"year":"2015","no":782,"q":"Oakley - fulthorpe procedure is","o":["Agglutination test","Precipitation test","Single diffusion in one dimension","Double diffusion in one dimension"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3852, 'Microbiology', 'Bacteriology', 'Moderate', 'Microbiology', 596, '{"id":3852,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Moderate","source":"Microbiology","sourceNo":596,"q":"Complement deficiency has not been implicated in causing ?","o":["SLE","PNH","Hereditary angiodema","Membranous nephritis"],"a":3,"e":"Ans. is ''d'' i.e., Membranous nephritis [Ref Pariza 3''/e p. 121] Complement deficiency and disease Deficiency of early components (C1, C2, C4) causes immune - complex diseases (e.g. SLE), and pyogenic infections. Deficiency of C3 and C3b causes recurrent pyogenic infections. Terminal complement component (C5 through Co) deficiencies and deficiencies of the alternative pathway (Properdin, C3, Factor D) have a strong effect on susceptibility to, as well as severity of, neisserial infections. Inherited deficiency of C, esterase inhibitor cases Hereditary angioneurotic edema. Acquired deficiency of Decay accelarating factor (DAF) causes Paroxysmal nocturnal hemoglobinuria (PNH). DAF is a regulator in complement system which increases dissolution of C3 convertase (C4b2a)","pyqMatches":[{"year":"2015","no":791,"q":"Complement deficiency has not been implicated in causing ?","o":["SLE","PNH","Hereditary angiodema","Membranous nephritis"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3853, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 597, '{"id":3853,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":597,"q":"Molecular mass of IgG [in K Da]","o":["150","400","1000","1500"],"a":0,"e":"Ans. is ''a'' i.e.,150 AntibodyMolecular mass (KDa) IgG 150 IgA 160,400 IgM 950,1150 IgD 175 IgE 190","pyqMatches":[{"year":"2015","no":783,"q":"Molecular mass of IgG [in K Da]","o":["150","400","1000","1500"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3854, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 598, '{"id":3854,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":598,"q":"Lattice phenomenon is seen in -","o":["Neutrilization reaction","Complement fixation test","Precipitation test","All of the above"],"a":2,"e":"Ans. is ''c'' i.e., Precipitation test [Ref Textbook of clinical microbiology p.785] The lattice hypothesis was proposed by marrack (1934) to explain the mechanism of precipitation. According to this concept, multivalent antigens combine with bivalent antibodies in varying proportion depending on the antigen-antibody ratio in the reacting mixture. Precipitation results when large lattice is formed consisting of alternating antigen and antibody molecules. This is possible only in the zone of equivalence. In the zone of antigen or antibody excess, the lattice does not enlarge, as the valencies of the antibody and the antigen, repectively are fully satisfied. In either cases extensive lattice cannot be formed and precipition is inhibited. The lattice hypothesis holds good for agglutination also.","pyqMatches":[{"year":"2015","no":790,"q":"Lattice phenomenon is seen in","o":["Neutrilization reaction","Complement fixation test","Precipitation test","All of the above"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3855, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 599, '{"id":3855,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":599,"q":"Haptens are immunogenic when they covalently bind to -","o":["Lipid carrier","Polysaccharide carrier","Protein carrier","Any of the above carrier"],"a":2,"e":"Ans. is ''c'' i.e.,Protein carrier [Ref Essentials of microbiology p. 91] Hapten Hapten is a substance, which itself is unable to induce antibody synthesis, i.e non-immunogenic but may be able to react specifically with antibody. Thus, hapten can function as antigen but not as immunogen. Haptens are incomplete antigens , which become complete antigens when they covalently combine with carrier molecule or schleper. After combination with carrier molecule, it becomes complete antigen and can induce an immune response.","pyqMatches":[{"year":"2015","no":784,"q":"Haptens are immunogenic when they covalently bind to","o":["Lipid carrier","Polysaccharide carrier","Protein carrier","Any of the above carrier"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3856, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 600, '{"id":3856,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":600,"q":"IgM appears in fetus at what gestational age -","o":["10 weeks","20 weeks","30 weeks","at birth"],"a":1,"e":"Ans. is ''b'' i.e., 20 weeks IgM is the earliest immunoglobulin class to be synthesized by the fetus, beginning at 20 weeks of age.","pyqMatches":[{"year":"2015","no":785,"q":"IgM appears in fetus at what gestational age","o":["10 weeks","20 weeks","30 weeks","at birth"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3857, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 601, '{"id":3857,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":601,"q":"The serum concentration of which of the following human IgG subclass is maximum ?","o":["IgG 1","IgG 2","IgG 3","IgG 4"],"a":0,"e":"Ans. is ''a'' i.e., Ig G1 [Ref Ananthanarayan 9th/ep. 97 & 8`\"/e p. 98; Harrison 19m/e p. 372 & 18tVe p. 2674]","pyqMatches":[{"year":"2015","no":786,"q":"The serum concentration of which of the following human IgG subclass is maximum ?","o":["IgG 1","IgG 2","IgG 3","IgG 4"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3858, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 602, '{"id":3858,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":602,"q":"Which is specific for acquired immunity ?","o":["Immunological memory","Affected by genetic makeup","No antigen exposure","All of the above"],"a":0,"e":"Ans. is ''a'' i.e., Immunological memory [Ref Harrison 19th/e p. 372] Acquired (adaptive) immunity is found only in vertebrates It is based on the generation of antigen receptors on T and B lymphocytes by germ line gene rearrangements. It is specific. It is developed as a result of an antigenic stimulus (Immunological priming)or by passive transfer of antibodies. It provides immunological memory; subsequent antigen exposure leads to more rapid and vigorous immune responses. The adaptive immune system consist of dual limbs of cellular and humoral immunity.","pyqMatches":[{"year":"2015","no":789,"q":"Which is specific for acquired immunity ?","o":["Immunological memory","Affected by genetic makeup","No antigen exposure","All of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3859, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 603, '{"id":3859,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":603,"q":"Example of neutrilization reaction -","o":["VDRL","Widal test","Kahn test","Nagler reaction"],"a":3,"e":"Ans. is ''d'' i.e., Nagler reaction [Ref Ananthanarayan 9th/e p.112] Important neutralization tests are Nagler reaction, dick test and schick test.","pyqMatches":[{"year":"2015","no":787,"q":"Example of neutrilization reaction","o":["VDRL","Widal test","Kahn test","Nagler reaction"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3860, 'Microbiology', 'Immunology', 'Moderate', 'Microbiology', 604, '{"id":3860,"subject":"Microbiology","chapter":"Immunology","difficulty":"Moderate","source":"Microbiology","sourceNo":604,"q":"Which does not stimulate active immunity -","o":["Subclinical infection","Clinical infection","Vaccination","Transplacental antibody in newborn"],"a":3,"e":"Ans. is ''d'' i.e., Transplacental antibody in newborn [Ref Ananthanarayan 9th/e p. 81-83] Adaptive (acquired) immunity is of following types :? 1) Active immunity It is so called because host''s immune system actively produce immunity. Antigenic stimulus induces the immune system to produce antibodies or cellular immune response. Active immunity may be :-","pyqMatches":[{"year":"2015","no":788,"q":"Which does not stimulate active immunity","o":["Subclinical infection","Clinical infection","Vaccination","Transplacental antibody in newborn"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3861, 'Microbiology', 'Bacteriology', 'Moderate', 'Microbiology', 605, '{"id":3861,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Moderate","source":"Microbiology","sourceNo":605,"q":"Which of the following is not true regarding amoebic liver abscess","o":["Multiple abscesses is more common","May rupture into the pleural cavity","For asymptomatic luminal carriers diloxanide furoate is the drug of choice","Mostly involving the right lobe of liver"],"a":0,"e":"Ans. is ''a'' i.e., Multiple abscesses are more common Amoebic liver abscess is the most common extra- intestinal manifestation of amoebiasis. It is the involvement of liver tissue by trophozoites of the organism Entamoeba histolytica and of its abscess due to necrosis. Most common in the posterosuperior surface of the right lobe. Usually, there is one large solitary abscess.- The necrotic contents of liver abscess are classically described as anchovy-sauce pus. Pleuropulmonary involvement of the most frequent complication of amoebic liver abscess. ALA is usually solitary and pyogenic liver abscess is usually multiple. Multiple ALA, although rare, are frequently confused with pyogenic liver abscess. However, Tayal et al., from India showed that the existence of multiple ALA is not uncommon as previously thought and superinfection or co-infection with pyogenic organisms is common in such cases. Treatment Treatment depends on the type of infection: 1) Asymptomatic carrier --> Luminal agents (Iodoquinol, Paromomycine) --> Diloxanide furoate is the DOC. 2) Acute colitis(dysentery) --> Metronidazole or Tinidazole + Luminal agent. 3) Liver abscess --> Metronidazole or Tinidazole or Ornidazole + Luminal agent.","pyqMatches":[{"year":"2015","no":1122,"q":"Which of the following is not true regarding amoebic liver abscess","o":["Multiple abscesses is more common","May rupture into the pleural cavity","For asymptomatic luminal carriers diloxanide furoate is the drug of choice","Mostly involving the right lobe of liver"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3862, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 606, '{"id":3862,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":606,"q":"Gene responsible for mutation of HBV is ?","o":["X gene","S gene","P gene","C gene"],"a":3,"e":"Ans. is- D- i.e., C gene Two categories of naturally occurring HBV variants have attracted the most attention. One of these was identified initially in Mediterranean countries among patients with an unusual serologic clinical profile. They have severe chronic HBV infection and detectable HBV DNA but with anti- HBe instead of HBeAg. These patients were found to be infected with an HBA mutant that contained an alteration in the pre-core region rendering the virus incapable of encoding HBeAg. Another mutation, in the core-promoter region, prevents transcription of the coding region for HBeAg and yields an HBeAg​‐ negative phenotype. Patients with such mutations in the pre-core region and who are unable to secrete HBeAg tend to have severe liver disease that progresses more rapidly to cirrhosis, or they are identified clinically later in the course of the natural history of chronic hepatitis B when the disease is more advanced. Both \"wild-type\" HBV and pre-core-mutant HBV can coexist in the same patient, or mutant HBV may arise late during wild-type HBV infection","pyqMatches":[{"year":"2013","no":710,"q":"Gene responsible for mutation of HBV is ?","o":["X gene","S gene","P gene","C gene"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3863, 'Microbiology', 'Miscellaneous', 'Moderate', 'Microbiology', 607, '{"id":3863,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Microbiology","sourceNo":607,"q":"The statements regarding falciparum malaria are all except","o":["Haemoglobinuria and renal failure","Hypoglycemia","Cerebral malaria","Adequately prevented with chloroquine therapy"],"a":3,"e":"Ans. is ''d'' i.e., Adequately prevented with chloroquine therapy [Ref CMDT-14 Chapter 35 p.1491] Most species of P. falciparum are resistant to chloroquine (so, it does not effectively prevent P. falciparum malaria). P falciparum malaria can cause :-","pyqMatches":[{"year":"2013","no":711,"q":"The statements regarding falciparum malaria are all except","o":["Haemoglobinuria and renal failure","Hypoglycemia","Cerebral malaria","Adequately prevented with chloroquine therapy"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3864, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 608, '{"id":3864,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":608,"q":"Eggs discharged in urine","o":["S. mansoni","S. japonicum","S. haematobium","All"],"a":2,"e":"Ans. is ''c'' i.e. S. haematobium 20 mm in length and 0.25 mm in breadth female. Elongated 110 -170 um long and 40-70 um wide eggs, Has a thin, smooth shell, a rounded anterior end and a characteristic terminal spine from the tapered posterior end Egg discharged in Urine, Infective form is Fork - tailed cercariae that penetrate skin of humans wading in freshwater canals.","pyqMatches":[{"year":"2013","no":772,"q":"Eggs discharged in urine","o":["S. mansoni","S. japonicum","S. haematobium","All"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3865, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 609, '{"id":3865,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":609,"q":"Most common site for hydatid cyst","o":["Lung","Liver","Brain","Kidney"],"a":1,"e":"Ans. is ''b'' i.e., Liver [Ref Harrison 18th le p. 1762] The majority of hydatid cysts occur in the liver, Liver cysts occur more frequently in the right lobe.","pyqMatches":[{"year":"2013","no":773,"q":"Most common site for hydatid cyst","o":["Lung","Liver","Brain","Kidney"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3866, 'Microbiology', 'General Microbiology', 'Hard', 'Microbiology', 610, '{"id":3866,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Hard","source":"Microbiology","sourceNo":610,"q":"A child come with fever, cold, cough, membrane over tonsils; nasal swab is taken, culture should be done on which medium for earliest diagnosis ?","o":["Loffelers serum slop","L. J. media","MC Conkey''s Agar","Citrate media"],"a":0,"e":"Ans. is ''a'' i.e., Loffelers serum slop [Ref: Ananthanarayan ele p. 233] Fever, cold, cough with membrane on tonsils suggest the diagnosis of diphthesia. For rapid growth the specimen is inoculated on Loeffer''s serum slop. Diphtheria bacilli grow on Loeffler''s serum slope very rapidly and colonies can be seen in 6-8 hours, long before other bacteria grow","pyqMatches":[{"year":"2012","no":676,"q":"A child come with fever, cold, cough, membrane over tonsils; nasal swab is taken, culture should be done on which medium for earliest diagnosis ?","o":["Loffelers serum slop","L. J. media","MC Conkey''s Agar","Citrate media"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3867, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 611, '{"id":3867,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":611,"q":"What is p24 ?","o":["Envelop antigen in HIV","Core antigen in HIV","Genome of HIV","Shell antigen"],"a":1,"e":"Ans. is ''b'' i.e.,Core antigen in HIV [Ref Ananthanarayan 8thie p. 571] A. Envelop antigens Spike antigen - gp 120 (Principal envelope antigen) Transmembrane pedicle protein - gp 41 B. Shell antigen Nucleocapsid protein - p 18 C. Core antigens Principal core antigen - p 24 Other core antigens - p 15, p 55 Polymerase antigens - p 31, p 51, p 66","pyqMatches":[{"year":"2012","no":738,"q":"What is p24 ?","o":["Envelop antigen in HIV","Core antigen in HIV","Genome of HIV","Shell antigen"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3868, 'Microbiology', 'Bacteriology', 'Moderate', 'Microbiology', 612, '{"id":3868,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Moderate","source":"Microbiology","sourceNo":612,"q":"Invasive infection s caused by all except ?","o":["Shigella","Salmonella","V. cholerae","Yersinia"],"a":2,"e":"Ans. is ''c'' i.e., V. cholerae [Ref Harrison tele p. 1084]","pyqMatches":[{"year":"2012","no":690,"q":"Invasive infection s caused by all except ?","o":["Shigella","Salmonella","V. cholerae","Yersinia"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3869, 'Microbiology', 'Clinical Microbiology', 'Easy', 'Microbiology', 613, '{"id":3869,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":613,"q":"A child with fever with ABCs & pus in stools, causative organism is ?","o":["ETEC","EHEC","EPEC","EAEC"],"a":1,"e":"Ans. is ''b'' i.e., EHEC [Ref Harrison 18thle p. 1084] Fever with RBC and pus in stools suggest inflammatory diarrhea. Amongst the given options EHEC causes invasion.","pyqMatches":[{"year":"2012","no":691,"q":"A child with fever with ABCs & pus in stools, causative organism is ?","o":["ETEC","EHEC","EPEC","EAEC"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3870, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 614, '{"id":3870,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":614,"q":"Painless genital ulcer in male with everted margin is seen in ?","o":["Syphilis","Chancroid","Herpes","LGV"],"a":0,"e":"Ans. is ''a'' i.e.,Syphilis [Ref Harrison 18th/e p. 1382, Jawetz 22\"/e p. 642] Painless indurated ulcer with everted margins, h/o of sexual exposure and lack of systemic symptoms favours the diagnosis of syphilis.","pyqMatches":[{"year":"2012","no":694,"q":"Painless genital ulcer in male with everted margin is seen in ?","o":["Syphilis","Chancroid","Herpes","LGV"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3871, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 615, '{"id":3871,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":615,"q":"Which organism can be isolated from stool & sputum -","o":["Paragnomus","Fasciola","Chlornchis","P. carini"],"a":0,"e":"Ans. is ''a'' i.e., Paragnomus [Ref Rajesh karyakarte p. 212] Two organism can be isolated from both sputum and stool :-","pyqMatches":[{"year":"2012","no":702,"q":"Which organism can be isolated from stool & sputum","o":["Paragnomus","Fasciola","Chlornchis","P. carini"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3872, 'Microbiology', 'Parasitology', 'Easy', 'Microbiology', 616, '{"id":3872,"subject":"Microbiology","chapter":"Parasitology","difficulty":"Easy","source":"Microbiology","sourceNo":616,"q":"Largest intestinal protozoa is ?","o":["E. coli","Balantidium coli","Giardia","T. gondii"],"a":1,"e":"Ans. is ''b'' i.e., Balantidium coli [Ref Paniker p. 111] Largest protozoa Balantidum coli Smallest intestinal amoeba Dientamoeba fragilis Smallest tapeworm found in human intestine H. nana Largest helminth (largest worm) T. saginata (beef tapeworm) Largest liver fluke F. hepatica Largest trematode infecting man→Fasciolopsis buski Largest Nematode Ascaris Smallest Nematode - Trichinella Only protozoan parasite found in small intestine of man Giardia lamblia Only ciliate protozoan parasite of man - Balantidum coli Parthenogenic worm (female is able to produce fertile eggs or larvae without fertilization) Strongyloides stercoralis.","pyqMatches":[{"year":"2012","no":718,"q":"Largest intestinal protozoa is ?","o":["E. coli","Balantidium coli","Giardia","T. gondii"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3873, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 617, '{"id":3873,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":617,"q":"Rhaditiform larvae is seen in ?","o":["Tenia solium","Strongyloides","D. latum","Trichenella"],"a":1,"e":"Ans. is `b'' i.e., Strongyloides [Ref Panikar 6th/e p. 171] Rhabditiform larva is the first stage feeding larva found in some nematodes. It is non-infective. Filiform larva is the non feeding infective larva in some nematodes. Rhabditiform larva and filiform larva are found in following important nematodes","pyqMatches":[{"year":"2012","no":710,"q":"Rhaditiform larvae is seen in ?","o":["Tenia solium","Strongyloides","D. latum","Trichenella"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3874, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 618, '{"id":3874,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":618,"q":"Burkholderia cepacia is resistant to which of the following drugs:","o":["Ceftazidime","Trimethoprim-sulfamethoxazole","Temocillin","Cefotetan"],"a":3,"e":"Answer: D. Cefotetan B. cepacia complex strains are intrinsically resistant to a wide range of antimicrobial agents, including aminoglycosides, polymyxin, first and second generation cephalosporins, and carboxypenicillins Antimicrobial agents that are effective against B. cepacia complex include meropenem, ceftazidime, piperacillin, temocillin, and trimethoprim-sulfamethoxazole.","pyqMatches":[{"year":"2017","no":63,"q":"Burkholderia cepacia is resistant to which of the following drugs:","o":["Ceftazidime","Trimethoprim-sulfamethoxazole","Temocillin","Cefotetan"],"a":3,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":88,"q":"Burkholderia cepacia is resistant to which of the following drugs:","o":["Ceftazidime","Trimethoprim-sulfamethoxazole","Temocillin","Cefotetan"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3875, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 619, '{"id":3875,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":619,"q":"Shingles Is caused by which of the following ?","o":["Varicella-zoster","Herpes simplex","CMV","None"],"a":0,"e":"Ans. A. Varicella-zoster Shingles, also called herpes zoster, is a painful skin rash. Shingles is caused by reactivation of the varicella zoster virus, the same virus that causes chickenpox.","pyqMatches":[{"year":"2018","no":89,"q":"Shingles Is caused by which of the following ?","o":["Varicella-zoster","Herpes simplex","CMV","None"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3876, 'Microbiology', 'Miscellaneous', 'Hard', 'Microbiology', 620, '{"id":3876,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Hard","source":"Microbiology","sourceNo":620,"q":"Urea breath test is used for diagnosis of:","o":["H.pylori","Campylobacter jejuni","E. coli","Lactobacillus"],"a":0,"e":"Answer: A. H.pylori The urea breath test is a rapid diagnostic procedure used to identify infections by Helicobacter pylori, a spiral bacterium implicated in gastritis, gastric ulcer, and peptic ulcer disease. It is based upon the ability of H. pylori to convert urea to ammonia and carbon dioxide","pyqMatches":[{"year":"2017","no":65,"q":"Urea breath test is used for diagnosis of:","o":["H.pylori","Campylobacter jejuni","E. coli","Lactobacillus"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":90,"q":"Urea breath test is used for diagnosis of:","o":["H.pylori","Campylobacter jejuni","E. coli","Lactobacillus"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3877, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 621, '{"id":3877,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":621,"q":"Hyperacute graft rejection occurs after how much time?","o":["24 hours","2 weeks right","In minutes","Years"],"a":2,"e":"Answer: C. In minutes Hyperacute Transplant Rejection occurs almost immediately and is often evident while you are still in surgery. It is caused by accidental ABO Blood type mismatching of the donor and recipient which almost never happens anymore..Acute onset is in few weeks to month. Chronic onset is from months to years.","pyqMatches":[{"year":"2017","no":66,"q":"Hyperacute graft rejection occurs after how much time?","o":["24 hours","2 weeks right","In minutes","Years"],"a":2,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":91,"q":"Hyperacute graft rejection occurs after how much time?","o":["24 hours","2 weeks right","In minutes","Years"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3878, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 622, '{"id":3878,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":622,"q":"Australian antigen for hepatitis b is?","o":["Hb S ag","Hb E ag","Hb D ag","HbV Dna"],"a":0,"e":"Answer: A. Hb S ag HBsAg (also known as the Australia antigen) is the surface antigen of the hepatitis B virus (HBV). It indicates current hepatitis B infection.","pyqMatches":[{"year":"2017","no":67,"q":"Australian antigen for hepatitis b is?","o":["Hb S ag","Hb E ag","Hb D ag","HbV Dna"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":92,"q":"Australian antigen for hepatitis b is?","o":["Hb S ag","Hb E ag","Hb D ag","HbV Dna"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3879, 'Microbiology', 'Mycology', 'Hard', 'Microbiology', 623, '{"id":3879,"subject":"Microbiology","chapter":"Mycology","difficulty":"Hard","source":"Microbiology","sourceNo":623,"q":"Which fungus is most commonly associated with orbital cellulitis in patients with diabetic ketoacidosis.","o":["Candida","Mucor","Aspergillus","Rhizopus"],"a":2,"e":"Answer: C. Aspergillus Orbital cellulitis term is reserved for infections behind the orbital septum which may or may not spill over to lids. Bacterial OC is more common in children and fulminant infection (& ischemic infarction) with Mucor or Aspergillus typically affectspatients with diabetes (esp ketoacidosis) and immunosuppression. Presentation is Extensive swelling of lids with chemosis often obscure proptosis (i.e. most commonly lateral & downwards). Proptosis with impaired mobility resulting in diplopia Pain is severe, increased by movement of eye or pressure Unilateral, tender, warm & red periorbital edema,painful ophthalmoplegia.","pyqMatches":[{"year":"2017","no":68,"q":"Which fungus is most commonly associated with orbital cellulitis in patients with diabetic ketoacidosis.","o":["Candida","Mucor","Aspergillus","Rhizopus"],"a":2,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":93,"q":"Which fungus is most commonly associated with orbital cellulitis in patients with diabetic ketoacidosis.","o":["Candida","Mucor","Aspergillus","Rhizopus"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3880, 'Microbiology', 'Miscellaneous', 'Hard', 'Microbiology', 624, '{"id":3880,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Hard","source":"Microbiology","sourceNo":624,"q":"Sabin Feldman dye test is used for diagnosis of which of the following condition:","o":["Botulism","Toxoplasmosis","Sarcoidosis","Yellow fever"],"a":1,"e":"Answer: B. Toxoplasmosis A Sabin–Feldman dye test is a serologic test to diagnose for toxoplasmosis","pyqMatches":[{"year":"2017","no":69,"q":"Sabin Feldman dye test is used for diagnosis of which of the following condition:","o":["Botulism","Toxoplasmosis","Sarcoidosis","Yellow fever"],"a":1,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":94,"q":"Sabin Feldman dye test is used for diagnosis of which of the following condition:","o":["Botulism","Toxoplasmosis","Sarcoidosis","Yellow fever"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3881, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 625, '{"id":3881,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":625,"q":"Acute Hemorrhagic Conjunctivitis is caused by which of enterovirus type ?","o":["69","68","70","71"],"a":2,"e":"Answer: C. 70 Acute hemorrhagic conjunctivitis (AHC) is characterized by conjunctival congestion, vascular dilatation, and onset of edema .Serologic studies have been useful in showing the presence of neutralizing antibodies to Coxsackie group A24 (CA24) and enterovirus E70 (EV70) strains as the causative agent.","pyqMatches":[{"year":"2017","no":70,"q":"Acute Hemorrhagic Conjunctivitis is caused by which of enterovirus type ?","o":["69","68","70","71"],"a":2,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":95,"q":"Acute Hemorrhagic Conjunctivitis is caused by which of enterovirus type ?","o":["69","68","70","71"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3882, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 626, '{"id":3882,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":626,"q":"Echinococcus granulosus are commonly seen in which of the given animals:","o":["Dog","Cat","Fox","Pig"],"a":0,"e":"Answer: A. Dog Echinococcus granulosus, also called the hydatid worm, hyper tape-worm or dog tapeworm. Domestic dogs (Canis familiaris) have been recognised as the definitive host of the parasite.","pyqMatches":[{"year":"2017","no":71,"q":"Echinococcus granulosus are commonly seen in which of the given animals:","o":["Dog","Cat","Fox","Pig"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":96,"q":"Echinococcus granulosus are commonly seen in which of the given animals:","o":["Dog","Cat","Fox","Pig"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3883, 'Microbiology', 'Bacteriology', 'Moderate', 'Microbiology', 627, '{"id":3883,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Moderate","source":"Microbiology","sourceNo":627,"q":"An anaerobe causing multiple abscess with discharging sinuses, demonstrating sulphur granules in pus is?","o":["Actinomycetes","Nocardia","Salmonella","Tularemia"],"a":0,"e":"Answer: A. Actinomycetes Actinomycosis is a rare subacute to chronic infection caused by the gram-positive filamentous non-acid fast anaerobic to microaerophilic bacteria, Actinomyces. The chronic form has multiple abscesses that form sinus tracts and are associated with sulfur granules. About 70% of infections are due to either Actinomyces israelii or Actinomyces gerencseriae. The characteristic of the disease is the sulfur granules which are yellow. They are formed primarily by mycelial fragments with some proteinaceous polysaccharide complexes, which act as a resistance mechanism to avoid and inhibit phagocytosis. Multiple abscess with discharging sinuses, demonstrating sulphur granules in pus are characteristics of actinomycetes","pyqMatches":[{"year":"2017","no":72,"q":"An anaerobe causing multiple abscess with discharging sinuses, demonstrating sulphur granules in pus is?","o":["Actinomycetes","Nocardia","Salmonella","Tularemia"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":97,"q":"An anaerobe causing multiple abscess with discharging sinuses, demonstrating sulphur granules in pus is?","o":["Actinomycetes","Nocardia","Salmonella","Tularemia"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3884, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 628, '{"id":3884,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":628,"q":"Whole blood is used as a sample for which test?","o":["Bacteria","IGRA","Genexpert","Virus"],"a":1,"e":"Answer: B. IGRA Interferon-Gamma Release Assays (IGRAs) are whole-blood tests that can aid in diagnosing Mycobacterium tuberculosis infection","pyqMatches":[{"year":"2017","no":73,"q":"Whole blood is used as a sample for which test?","o":["Bacteria","IGRA","Genexpert","Virus"],"a":1,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":98,"q":"Whole blood is used as a sample for which test?","o":["Bacteria","IGRA","Genexpert","Virus"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3885, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 629, '{"id":3885,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":629,"q":"Which organism causing acute bacterial prostatitis ?","o":["Enterococcus","Streptococcus viridans","Peptostreptococcus","E.coli"],"a":3,"e":"Answer: D. E.coli Aerobic gram-negative bacilli are the predominant pathogens in bacterial prostatitis. E. coli cause 50%–80% of cases; other pathogens include Enterobacteriaceae (eg, Klebsiella and Proteus, which account for 10%–30% of cases), Enterococcus species (5%– 10%)","pyqMatches":[{"year":"2017","no":74,"q":"Which organism causing acute bacterial prostatitis ?","o":["Enterococcus","Streptococcus viridans","Peptostreptococcus","E.coli"],"a":3,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":99,"q":"Which organism causing acute bacterial prostatitis ?","o":["Enterococcus","Streptococcus viridans","Peptostreptococcus","E.coli"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3886, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 630, '{"id":3886,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":630,"q":"Which of the following organism releases histamine and cause scombroid fish poisoning -","o":["Salmonella","Staphylococcus","P. aeruginosa","Weissella"],"a":2,"e":"Answer: C. P. aeruginosa Scombroid poisoning is one of the most common causes of morbidity associated with fish intake which have not been refrigerated properly from the time they were caught until the time they were served. Bacteria act on compounds in the fish, releasing histamine. Process is induced by enzymes produced by primarily enteric gram-negative bacteria (e.g., Morganella morganii, Escherichia coli, Klebsiella species and Pseudomonas aeruginosa) found in the fish''s cutis and intestines.,.","pyqMatches":[{"year":"2017","no":75,"q":"Which of the following organism releases histamine and cause scombroid fish poisoning","o":["Salmonella","Staphylococcus","P. aeruginosa","Weissella"],"a":2,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":100,"q":"Which of the following organism releases histamine and cause scombroid fish poisoning","o":["Salmonella","Staphylococcus","P. aeruginosa","Weissella"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3887, 'Microbiology', 'General Microbiology', 'Easy', 'Microbiology', 631, '{"id":3887,"subject":"Microbiology","chapter":"General Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":631,"q":"Who is the father of microbiology?","o":["A.V.L.hook","Robert brown","J.C Bose","Pasteur"],"a":0,"e":"Answer: A. A.V.L.hook “Antoni van Leeuwenhoek” is commonly known as \"the Father of Microbiology. Antonie Philips van Leeuwenhoek (24th Oct, 1632 – 26th Aug, 1723) is known as ''The Father of Microbiology''. He was known so because of his contributions towards the establishment of microbiology. He was scientist from Delft, Netherlands and is considered to be ''The First Microbiologist in the World''. leeuwenhoek is called as father of microbiology. He was the first person to see bacteria through his self made single lensed microscope. And he named them “animalcules\". Louis Pasteur is know as “father of morden microbiology”.","pyqMatches":[{"year":"2017","no":76,"q":"Who is the father of microbiology?","o":["A.V.L.hook","Robert brown","J.C Bose","Pasteur"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":101,"q":"Who is the father of microbiology?","o":["A.V.L.hook","Robert brown","J.C Bose","Pasteur"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3888, 'Microbiology', 'Miscellaneous', 'Easy', 'Microbiology', 632, '{"id":3888,"subject":"Microbiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Microbiology","sourceNo":632,"q":"Cutaneous larva migrans caused by which organism?","o":["Strongyloides","Toxocara canis","Ancylostoma braziliense","Necator americanus"],"a":2,"e":"Answer: C. Ancylostoma braziliense Cutaneous larva migrans(CLM) /It is a skin disease in humans, caused by the larvae of various nematode parasites of the hookworm family (Ancylostomatidae). The most common species causing this disease in the Americas is Ancylostoma braziliense. These parasites live in the intestines of dogs, cats and wild animals and should not be confused with other members of the hookworm family for which humans are definitive hosts, namely Ancylostoma duodenale and Necator americanus. Colloquially called creeping eruption due to its presentation, the disease is also somewhat ambiguously known as \"ground itch\" or (in some parts of the Southern USA) \"sandworms\", as the larvae like to live in sandy soil. Another vernacular name is plumber''s itch. The medical term CLM literally means \"wandering larvae in the skin\"","pyqMatches":[{"year":"2017","no":77,"q":"Cutaneous larva migrans caused by which organism?","o":["Strongyloides","Toxocara canis","Ancylostoma braziliense","Necator americanus"],"a":2,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":102,"q":"Cutaneous larva migrans caused by which organism?","o":["Strongyloides","Toxocara canis","Ancylostoma braziliense","Necator americanus"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3889, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 633, '{"id":3889,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":633,"q":"After kidney transplantation which organisms infection is more likely to happens -","o":["CMV","Klebsiella","Streptococcus","Staphylococcus"],"a":0,"e":"Answer: A. CMV CMV is the most common viral infection after Kidney Transplantation. Most common CMV syndrome in kidney transplant patient is fever (most common), leukopenia, hepatosplenomegaly, myalgia and arthralgia.","pyqMatches":[{"year":"2017","no":78,"q":"After kidney transplantation which organisms infection is more likely to happens","o":["CMV","Klebsiella","Streptococcus","Staphylococcus"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":103,"q":"After kidney transplantation which organisms infection is more likely to happens","o":["CMV","Klebsiella","Streptococcus","Staphylococcus"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3890, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 634, '{"id":3890,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":634,"q":"Vector for zika virus is -","o":["Aedes","Culex","Anopheles","None of these"],"a":0,"e":"Ans: A. Aedes Zika virus disease is caused by the Zika virus, which is spread to people primarily through the bite of an infected mosquito (Aedes aegypti and Aedes albopictus). The virus can also be transmitted through sex. These are the same mosquitoes that spread dengue and chikungunya viruses. A mosquito gets infected with a virus when it bites an infected person during the period of time when the virus can be found in the person’s blood, typically only through the first week of infection. Medical Microbiology and Immunology 14/e-pg;395","pyqMatches":[{"year":"2020","no":79,"q":"Vector for zika virus is","o":["Aedes","Culex","Anopheles","None of these"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3891, 'Microbiology', 'Virology', 'Moderate', 'Microbiology', 635, '{"id":3891,"subject":"Microbiology","chapter":"Virology","difficulty":"Moderate","source":"Microbiology","sourceNo":635,"q":"All of the following is/are having superantigen Property Except","o":["Vibrio cholera","Streptococcal pyrogenic","Staphylococcal enterotoxins","None of these"],"a":0,"e":"Answer-A- Vibrio Cholera SAgs are produced by some pathogenic viruses and bacteria most likely as a defense mechanism against the immune system. Toxic shock syndrome toxin (TSST-1), epidermolytic toxin and other staphylococcal enterotoxin are superantigens. These superantigens can bind MHC molecules outside the peptide- binding cleft. Consequently, superantigen can activate up to 10% of T-cells in a nonspecific manner which in turn leads to the release of large quantities of cytokines. Jawetz 27/e-pg-135","pyqMatches":[{"year":"2020","no":81,"q":"All of the following is/are having superantigen Property Except","o":["Vibrio cholera","Streptococcal pyrogenic","Staphylococcal enterotoxins","None of these"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3892, 'Microbiology', 'Virology', 'Easy', 'Microbiology', 636, '{"id":3892,"subject":"Microbiology","chapter":"Virology","difficulty":"Easy","source":"Microbiology","sourceNo":636,"q":"Type A bioterrorism Agent-","o":["Chikungunya","Anthrax","Hendra","Influenza"],"a":1,"e":"Answer- B- Anthrax Category A agents - consists of the agents that are considered the highest risk Included among Category B agents is one that could conceivably threaten water and food safety. Category C includes pathogens that are considered emerging infectious disease threats and which could be engineered for mass dissemination. Category A Category B Category C Anthrax Caliciviruses Antimicrobial Resistance Botulism Chikungunya Hendra Dengue Cholera Influenza (highly pathogenic strains) Ebola E. coli O157: H7 MERS Hantavirus Hepatitis A Nipah Lassa Ricin toxin Prions Marburg Salmonella Rabies Plague Typhus fever SARS Smallpox Yellow fever Tick-Borne encephalitis Tularemia Zika Tuberculosis Jawetz 27/e-pg-417","pyqMatches":[{"year":"2020","no":82,"q":"Type A bioterrorism Agent","o":["Chikungunya","Anthrax","Hendra","Influenza"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3893, 'Microbiology', 'Clinical Microbiology', 'Easy', 'Microbiology', 637, '{"id":3893,"subject":"Microbiology","chapter":"Clinical Microbiology","difficulty":"Easy","source":"Microbiology","sourceNo":637,"q":"Culture media used for E.coli 0157:H7 is","o":["SMAC","Wilson and Blair medium","Potassium tellurite in Mcleod''s medium","Deoxycholate citrate agar (DCA)"],"a":0,"e":"Answer- A- SMAC An enterohemorrhagic bacterial strain, E. coli O157: H7 infects the alimentary tract and induces abdominal cramps with hemorrhagic diarrhea. Transmission of E. coli O157: H7 occurs via the fecal-oral route after consumption of contaminated, undercooked liquids and foods. Mac Conkey-Sorbitol ChromoSelect Agar (SMAC) is recommended for selective isolation of Escherichia coli 0157:H7 from food and animal feeding stuffs. MacConkey Sorbitol Agar is based on the formulation described by Rappaport and Henigh. The medium contains sorbitol instead of lactose and it is recommended for the detection of enteropathogenic strains of E. coli 0157:H7 which ferments lactose but does not ferment sorbitol and hence produce colorless colonies. Sorbitol fermenting strains of E. coli produce pink-red colonies. The red color is due to the production of acid from sorbitol, absorption of neutral red and a subsequent colour change of the dye when the pH of the medium falls below 6.8. https://www.sigmaaldrich.com/analytical- chromatography/microbiology/microbiology-products.html? TablePage=18297647","pyqMatches":[{"year":"2020","no":83,"q":"Culture media used for E.coli 0157:H7 is","o":["SMAC","Wilson and Blair medium","Potassium tellurite in Mcleod''s medium","Deoxycholate citrate agar (DCA)"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3894, 'Microbiology', 'Parasitology', 'Easy', 'Microbiology', 638, '{"id":3894,"subject":"Microbiology","chapter":"Parasitology","difficulty":"Easy","source":"Microbiology","sourceNo":638,"q":"Donovanosis is Caused By-","o":["H. ducreyi","Leishmania donovani","K. granulomatis","Treponema pallidum"],"a":2,"e":"Answer- C- K. Granulomatis Donovanosis is a sexually transmitted genital ulcer disease. The bacterium that causes donovanosis (Klebsiella granulomatis) infects the skin around the genitals, groin or anal area and causes ulcers and destruction of the skin.","pyqMatches":[{"year":"2020","no":84,"q":"Donovanosis is Caused By","o":["H. ducreyi","Leishmania donovani","K. granulomatis","Treponema pallidum"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3895, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 639, '{"id":3895,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":639,"q":"Fungal Infection which is acquired by traumatic inoculation is?","o":["Sporothrix","Blastomycosis","Coccidioides","Paracoccidioides"],"a":0,"e":"Answer-A- Sporothrix Sporothrix schenckii is a thermally dimorphic fungus that lives on vegetation. It is associated with a variety of plants, grasses, trees, sphagnum moss, rose bushes, and other horticultural plants. The conidia or hyphal fragments of S.schenckii are introduced into the skin by trauma. Following a traumatic introduction into the skin, S.schenckii causes sporotrichosis, a chronic granulomatous infection. This manifestation mimics chronic cavitary tuberculosis and tends to occur in patients with impaired cell-mediated immunity. Jawetz 27/e-pg-670","pyqMatches":[{"year":"2020","no":85,"q":"Fungal Infection which is acquired by traumatic inoculation is?","o":["Sporothrix","Blastomycosis","Coccidioides","Paracoccidioides"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3896, 'Microbiology', 'Virology', 'Moderate', 'Microbiology', 640, '{"id":3896,"subject":"Microbiology","chapter":"Virology","difficulty":"Moderate","source":"Microbiology","sourceNo":640,"q":"Which of the following is not involved in urethritis","o":["Trichomonas","H.ducreyi","Chlamydia","Gonococcus"],"a":1,"e":"Answer-B- H.ducreyi Bacteria that commonly cause urethritis to include: E. coli and other bacteria present in the stool Gonococcus, which is sexually transmitted and causes gonorrhea. Chlamydia trachomatis, which is sexually transmitted and causes chlamydia. The herpes simplex virus (HSV-1 and HSV-2) can also cause urethritis. Trichomonas is another cause of urethritis -https://www.webmd.com/a-to-z-guides/urethritis-symptoms- causes-treatments#1 ; Jawetz 27/e-pg-746","pyqMatches":[{"year":"2020","no":86,"q":"Which of the following is not involved in urethritis","o":["Trichomonas","H.ducreyi","Chlamydia","Gonococcus"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3897, 'Microbiology', 'Bacteriology', 'Hard', 'Microbiology', 641, '{"id":3897,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Hard","source":"Microbiology","sourceNo":641,"q":"A patient complains about nausea, vomiting and stomach cramps after attending a social gathering party, which causative organism is likely responsible for Food Poisoning within 3 hours.","o":["Staphylococcus aureus","Salmonella","Clostridium botulinum","Clostridium perfringens"],"a":0,"e":"Answer- A- Staphylococcus aureus Staph food poisoning is characterized by a sudden start of nausea, vomiting, and stomach cramps. Most people also have diarrhea. Symptoms usually develop within 30 minutes to 6 hours after eating or drinking an item containing Staph toxin and last no longer than 1 day. Severe illness is rare. The illness cannot be passed from one person to another. https://www.cdc.gov/foodsafety/diseases/staphylococcal.html","pyqMatches":[{"year":"2020","no":87,"q":"A patient complains about nausea, vomiting and stomach cramps after attending a social gathering party, which causative organism is likely responsible for Food Poisoning within 3 hours.","o":["Staphylococcus aureus","Salmonella","Clostridium botulinum","Clostridium perfringens"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3898, 'Microbiology', 'Bacteriology', 'Hard', 'Microbiology', 642, '{"id":3898,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Hard","source":"Microbiology","sourceNo":642,"q":"A 46-year-old woman with HIV complains severe persistent diarrhea, Histological Investigation was performed, Identify the organism causing diarrhea in HIV Patient.","o":["Cryptosporidium","Staphylococcus aureus","Salmonella","Clostridium botulinum"],"a":0,"e":"Answer-A- Cryptosporidium * The origin of infectious diarrhea in patients with AIDS can be divided into 2 general categories: that caused by common pathogens and that caused by opportunistic pathogens. * The most common infectious organisms causing AIDS-related diarrhea include - Cytomegalovirus (CMV) - The parasites Cryptosporidium, - Microsporidia - Giardia lamblia * And the bacterium Mycobacterium avium-intracellulare (MAC). * Other bacteria and parasites that cause diarrheal symptoms in otherwise healthy people may cause more severe, prolonged or recurrent diarrhea in people with HIV or AIDS https://aidsinfo.nih.gov/news/175/aids-related-diarrhea","pyqMatches":[{"year":"2020","no":88,"q":"A 46-year-old woman with HIV complains severe persistent diarrhea, Histological Investigation was performed, Identify the organism causing diarrhea in HIV Patient.","o":["Cryptosporidium","Staphylococcus aureus","Salmonella","Clostridium botulinum"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3899, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 643, '{"id":3899,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":643,"q":"Organism Causing LGV","o":["Chlamydia trachomatis","Neisseria gonorrhoeae","Treponema pallidum","Haemophilus ducreyi"],"a":0,"e":"Answer- A- Chlamydia trachomatis Lymphogranuloma venereum (LGV) is a long-term (chronic) infection of the lymphatic system. It is caused by any of the 3 different types (serovars) of the bacteria Chlamydia trachomatis. The bacteria are spread by sexual contact. The infection is not caused by the same bacteria that cause genital chlamydia. Chlamydia trachomatis causes eye (conjunctivitis, trachoma), respiratory (pneumonia), and genital tract (urethritis, lymphogranuloma venereum) infections. Diagnosis made with the nucleic acid test for C.trachomatis, LGV serovars diagnosed serologically. Lange Review of Medical Microbiology & Immunology 14/e 208","pyqMatches":[{"year":"2020","no":89,"q":"Organism Causing LGV","o":["Chlamydia trachomatis","Neisseria gonorrhoeae","Treponema pallidum","Haemophilus ducreyi"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3900, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 644, '{"id":3900,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":644,"q":"Which interleukin responsible for producing IgE from B cells","o":["IL 1","IL 3","IL 4","Both B & C"],"a":2,"e":"Answer- C, IL 4 IgE is produced by plasma cells located in lymph nodes draining the site of antigen entry or locally, at the sites of allergic reactions, by plasma cells derived from germinal centers developing within the inflamed tissue. IgEantibody production requires TH2 cells that produce interleukin-4 (IL-4) and IL-13 and it can be inhibited by TH1 cells that produce interferon-γ (IFN-γ). https://www.ncbi.nlm.nih.gov/books/NBK27117/","pyqMatches":[{"year":"2020","no":90,"q":"Which interleukin responsible for producing IgE from B cells","o":["IL 1","IL 3","IL 4","Both B & C"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3901, 'Microbiology', 'Immunology', 'Easy', 'Microbiology', 645, '{"id":3901,"subject":"Microbiology","chapter":"Immunology","difficulty":"Easy","source":"Microbiology","sourceNo":645,"q":"HbsAg is based on which principle","o":["Immunochromatography assays","Chemiluminescence","ELISA","Immunofluorescence"],"a":0,"e":"Answer- A- Immunochromatography assays HBV chronic carriers are those in whom HBsAg persists for more than 6 months in the presence of HBeAg or anti-HBe. HBsAg may persist for years after the loss of HBeAg. The most useful detection methods are enzyme-linked Immunosorbent assay for HBV antigens and antibodies and PCR for viral DNA -Jawetz 27/e pg- 504 Serological assays detect the host immune response (antibodies to HCV) or a viral antigen (HBsAg, HCVcAg). They are based on the immunoassay principle and are available in the form of rapid diagnostic tests (RDTs) or laboratory-based enzyme immunoassays (EIAs), chemiluminescence immunoassays (CLIAs) and electrochemiluminescence immunoassays (ECLs).- https://www.ncbi.nlm.nih.gov/books/NBK442281/","pyqMatches":[{"year":"2020","no":91,"q":"HbsAg is based on which principle","o":["Immunochromatography assays","Chemiluminescence","ELISA","Immunofluorescence"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3902, 'Microbiology', 'Bacteriology', 'Easy', 'Microbiology', 646, '{"id":3902,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Easy","source":"Microbiology","sourceNo":646,"q":"Nosocomial Infection occurs within?","o":["A- 48","B. 72","C. 24","D. 50"],"a":0,"e":"Answer- A- 48 hours A hospital-acquired infection (HAI), also known as a nosocomial infection, is an infection that is acquired in a hospital or other health care facility. Nosocomial infections can be defined as those occurring within 48 hours of hospital admission or within 3 days of discharge or 30 days of operation. Some well known nosocomial infections include: ventilator-associated pneumonia, Methicillin-resistant Staphylococcus aureus, Candida albicans, Acinetobacter baumannii, Clostridium difficile, Tuberculosis, Urinary tract infection, Vancomycin-resistant Enterococcus, and Legionnaires'' disease. https://www.ncbi.nlm.nih.gov/books/NBK441857/","pyqMatches":[{"year":"2020","no":92,"q":"Nosocomial Infection occurs within?","o":["A- 48","B. 72","C. 24","D. 50"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3903, 'Microbiology', 'Bacteriology', 'Moderate', 'Microbiology', 647, '{"id":3903,"subject":"Microbiology","chapter":"Bacteriology","difficulty":"Moderate","source":"Microbiology","sourceNo":647,"q":"Which of the following cell components produced by Neisseria gonorrhoeae is responsible for attachment to host cells?","o":["Lipooligosaccharide","Pili (fimbriae)","IgA1 protease","Outer membrane porin protein"],"a":1,"e":"Answer- B- Pili (fimbriae) Pili are hair-like appendages that extend up to several micrometers from the gonococcal surface. They enhance attachment to host cells and resistance to phagocytosis. They are made up of stacked pilin proteins. The amino terminal of the pilin molecule, which contains a high percentage of hydrophobic amino acids, is conserved. The amino acid sequence near the midportion of the molecule also is conserved; this portion of the molecule serves in an attachment to host cells and is less prominent in the immune response. The amino acid sequence near the carboxyl-terminal is highly variable; this portion of the molecule is most prominent in the immune response. The pilins of almost all strains of N. gonorrhea are antigenically different, and a single strain can make many antigenically distinct forms of pilin Jawetz 27/e-pg-282","pyqMatches":[{"year":"2020","no":93,"q":"Which of the following cell components produced by Neisseria gonorrhoeae is responsible for attachment to host cells?","o":["Lipooligosaccharide","Pili (fimbriae)","IgA1 protease","Outer membrane porin protein"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3904, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 1, '{"id":3904,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":1,"q":"Main support of uterus is from - ligament :","o":["Cardinal","Broad","Round","Pubocervical"],"a":0,"e":"Cardinal","pyqMatches":[{"year":"2012","no":66,"q":"Main support of uterus is from - ligament :","o":["Cardinal","Broad","Round","Pubocervical"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3905, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 2, '{"id":3905,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":2,"q":"Best gas used for creating pneumoperitonium at laparoscopy is :","o":["N2","02","CO2","N20 Goniometer is used"],"a":2,"e":"CO2 CO, is the gas used to create pneumoperitoneum during laparoscopy. Other option is - N20 : But it is expensive, less soluble in blood and supports combustion. Also know : Instrument used for creating pneumoperitoneum is veress needle. Flow Rate of CO, for creating pneumoperitoneum 200 - 2000 ml/min & pressure between 15 - 25 mm of Hg.","pyqMatches":[{"year":"2012","no":1104,"q":"Best gas used for creating pneumoperitonium at laparoscopy is :","o":["N2","02","CO2","N20 Goniometer is used"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3906, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 3, '{"id":3906,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":3,"q":"Gonococci has affinity for :","o":["Columnar epithelium","Glandular epithelium","Stratified sqamous epithelium","Squamous epithelium"],"a":0,"e":"Columnar epithelium","pyqMatches":[{"year":"2016","no":725,"q":"Gonococci has affinity for :","o":["Columnar epithelium","Glandular epithelium","Stratified sqamous epithelium","Squamous epithelium"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3907, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Gynecology', 4, '{"id":3907,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Gynecology","sourceNo":4,"q":"In a case of Dysgerminoma of ovary one of the following tumor markers is likely to be raised :","o":["Serum HCG","Serum alphafetoprotein","Serum lactic dehydrogenase","Serum inhibin"],"a":2,"e":"Ans. is c i.e. Serum lactic dehydrogenase however placental alkaline phosphate and lactate dehydrogenase are commonly produced by dysgerminomas and may be useful in monitoring the disease.\"","pyqMatches":[{"year":"2016","no":497,"q":"In a case of Dysgerminoma of ovary one of the following tumor markers is likely to be raised :","o":["Serum HCG","Serum alphafetoprotein","Serum lactic dehydrogenase","Serum inhibin"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3908, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 5, '{"id":3908,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":5,"q":"Which of the following ovarian tumor is most prone to undergo torsion during pregnancy :","o":["Serous cystadenoma","Mucinous cystadenoma","Dermoid cyst","Theca lutein cyst"],"a":2,"e":"Ans. is c i.e. Dermoid cyst \"A benign cystic teratoma is the most common neoplasm to undergo torsion, and it to the M/C benign tumor diagnosed during pregnancy.\" A benign cystic teratoma is synonymous to dermoid cyst. Remember : Most common ovarian tumour in pregnancy is serous cystadenoma but mostly remains undiagnosed. Incidence of dermoid cyst is increased two fold during pregnancy and it is the most common neoplasm diagnosed during pregnancy. Hingorani sign seen : - In ovarian tumor during pregnancy. Trendelenburg''s position can elicit the groove between two separate swelling. Used to distinguish between ovarian tumour and fibroid.","pyqMatches":[{"year":"2015","no":1515,"q":"Which of the following ovarian tumor is most prone to undergo torsion during pregnancy :","o":["Serous cystadenoma","Mucinous cystadenoma","Dermoid cyst","Theca lutein cyst"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3909, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 6, '{"id":3909,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":6,"q":"Which of the following has LEAST pregnancy failure rate :","o":["OCP","IUCD","Diaphragm","Condom"],"a":0,"e":"OCP","pyqMatches":[{"year":"2012","no":846,"q":"Which of the following has LEAST pregnancy failure rate :","o":["OCP","IUCD","Diaphragm","Condom"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3910, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Gynecology', 7, '{"id":3910,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Gynecology","sourceNo":7,"q":"Which of the following is true regarding precocious puberty :","o":["Sexual maturity is attained early","Mental function is increased","No reproductive function","Body proportions are enlarged"],"a":0,"e":"Ans. is a i.e. Sexual maturity is attained early Precocious puberty is the appearance of appropriate secondary sexual characters before the age of 8 years and occurrence of menstruation before 10 years of chronological age. Also know : Delayed puberty : is considered delayed when the secondary sexual characters do not appear by the age of 14, and menarche is not established by 16 years of age.","pyqMatches":[{"year":"2015","no":1519,"q":"Which of the following is true regarding precocious puberty :","o":["Sexual maturity is attained early","Mental function is increased","No reproductive function","Body proportions are enlarged"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3911, 'OBG', 'Benign Gynecology', 'Easy', 'Gynecology', 8, '{"id":3911,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Easy","source":"Gynecology","sourceNo":8,"q":"Cause of unilateral dysmenorrhea :","o":["One horn of malformed uterus","Endometriosis with unilateral distribution","Small fibroid at the utero tubal junction","All of the above"],"a":3,"e":"All of the above Causes of unilateral dysmenorrhea : One horn of malformed uterus Endometriosis with unilateral distribution Small fibroid at the utero - tubal junction. Ovarian dysmenorrhea Right ovarian vein syndrome Colonic or caecal spasm.","pyqMatches":[{"year":"2015","no":1541,"q":"Cause of unilateral dysmenorrhea :","o":["One horn of malformed uterus","Endometriosis with unilateral distribution","Small fibroid at the utero tubal junction","All of the above"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3912, 'OBG', 'Contraception & Family Planning', 'Easy', 'Gynecology', 9, '{"id":3912,"subject":"OBG","chapter":"Contraception & Family Planning","difficulty":"Easy","source":"Gynecology","sourceNo":9,"q":"Progesterone of choice in emergency contraception is?","o":["Norethisterone","Medroxyprogesterone","Oxytocin","Levonorgestrel"],"a":3,"e":"Unprotected intercourse without regard to the time of the month carries an 8% incidence of pregnancy, an incidence that can be reduced to 2% by the use of emergency contraceptives within 72 hours of unprotected intercourse. 0.75 mg levonorgestrel are now approved for postcoital contraception and are available over the counter for women aged >17 years. Levonorgestrel is more effective and is associated with fewer side effects than the combination estrogen-progestin regimens. Basically the methods used interfere with the physiological events before implantation, for e.g. inhibition or delaying of ovulation or interference with postovulatory events necessary for implantation & longevity of the blastocyst. Ref: Hall J.E. (2012). Chapter 347. The Female Reproductive System, Infertility, and Contraception. In D.L. Longo, A.S. Fauci, D.L. Kasper, S.L. Hauser, J.L. Jameson, J. Loscalzo (Eds), Harrison''s Principles of Internal Medicine, 18e.","pyqMatches":[{"year":"2015","no":1493,"q":"Progesterone of choice in emergency contraception is?","o":["Norethisterone","Medroxyprogesterone","Oxytocin","Levonorgestrel"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3913, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Gynecology', 10, '{"id":3913,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Gynecology","sourceNo":10,"q":"Which among the following is an absolute contraindication of Hormone replacement therapy ?","o":["Endometriosis","Osteoarthritis","Heart disease","Breast carcinoma"],"a":3,"e":"Absolute contraindications of hormone replacement therapy (HRT): Undiagnosed vaginal bleeding Estrogen dependent cancer in the body Severe liver disease Pregnancy Venous thrombosis Well- differentiated and early endometrial cancer (once treatment for the malignancy is complete, is no longer an absolute contraindication.)","pyqMatches":[{"year":"2013","no":587,"q":"Which among the following is an absolute contraindication of Hormone replacement therapy ?","o":["Endometriosis","Osteoarthritis","Heart disease","Breast carcinoma"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3914, 'OBG', 'Miscellaneous', 'Hard', 'Gynecology', 11, '{"id":3914,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Hard","source":"Gynecology","sourceNo":11,"q":"A 40 year old woman presents with abnormal cervical cytology on PAP smear suggestive of CIN III (HSIL). The next best step in management is:","o":["Hysterectomy","Colposcopy and LEEP","Colposcopy and Cryotherapy","Conization"],"a":1,"e":"According to FIGO classification, cervical intraepithelial neoplasia 3 (CIN 3) belong to stage 0. Loop electrocautery excision procedure done under colposcopic visualization is the mode of treatment for CIN II and CIN III lesions. Ref: Novak''s, 14th Edition, Page 582, 583; William''s Gynoecology, 1st Edition, Page 635; COGDT, 10th Edition, Pages 841, 837; Dewhurst''s, 6th Edition, Pages 575, 574.","pyqMatches":[{"year":"2015","no":1553,"q":"A 40 year old woman presents with abnormal cervical cytology on PAP smear suggestive of CIN III (HSIL). The next best step in management is:","o":["Hysterectomy","Colposcopy and LEEP","Colposcopy and Cryotherapy","Conization"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3915, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Gynecology', 12, '{"id":3915,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Gynecology","sourceNo":12,"q":"Chlamydia trachomatis infection commonly causes: March 2004","o":["Infertility","Post coital bleeding","Amenorrhoea","Malignancy"],"a":0,"e":"Ans. A i.e. Infertility","pyqMatches":[{"year":"2016","no":715,"q":"Chlamydia trachomatis infection commonly causes: March 2004","o":["Infertility","Post coital bleeding","Amenorrhoea","Malignancy"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3916, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 13, '{"id":3916,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":13,"q":"Main difference between anorexia nervosa and bulimia nervosa lies in: March 2013","o":["Symptomatology","Weight","Gender","Age"],"a":1,"e":"Ans. B i.e. Weight Anorexia nervosa and bulimia Both anorexia nervosa and bulimia are characterized by an overvalued drive for thinness and a disturbance in eating behavior. The main difference between diagnoses is that anorexia nervosa is a syndrome of self-starvation involving significant weight loss of 15 percent or more of ideal body weight, whereas patients with bulimia nervosa are, by definition, at normal weight or above. Bulimia is characterized by a cycle of dieting, binge-eating and compensatory purging behavior to prevent weight gain. Purging behavior includes vomiting, diuretic or laxative abuse. Excessive exercise aimed at weight loss or at preventing weight gain is common in both anorexia nervosa and in bulimia.","pyqMatches":[{"year":"2014","no":2103,"q":"Main difference between anorexia nervosa and bulimia nervosa lies in: March 2013","o":["Symptomatology","Weight","Gender","Age"],"a":1,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":1704,"q":"Main difference between anorexia nervosa and bulimia nervosa lies in: March 2013","o":["Symptomatology","Weight","Gender","Age"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3917, 'OBG', 'Miscellaneous', 'Moderate', 'Gynecology', 14, '{"id":3917,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Gynecology","sourceNo":14,"q":"Not seen in anorexia nervosa: September 2009","o":["Osteoporosis","Refusal to feeds","Weight loss","Menorrhagia"],"a":3,"e":"Ans. D: Menorrhagia Physical Signs of anorexia nervosa * Excessive weight loss * Scanty or absent menstrual periods * Thinning hair - Dry skin * Cold ors wollen hands and feet Bloated or upset stomach * Downy hair covering the body Low blood pressure * Fatigue * Abnormal heart rhythms *Osteoporosis Psychological and Behavioral Signs in anorexia nervosa * Distorted perception of self (insisting they are overweight when they are thin) * Being preoccupied with food Refusing to eat * Inability to remember things * Refusing to acknowledge the seriousness of the illness Obsessive-compulsive behavior * Depression","pyqMatches":[{"year":"2015","no":1703,"q":"Not seen in anorexia nervosa: September 2009","o":["Osteoporosis","Refusal to feeds","Weight loss","Menorrhagia"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3918, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Gynecology', 15, '{"id":3918,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Gynecology","sourceNo":15,"q":"First polar body is formed after ?","o":["Mitosis","First meiosis","Second meiosis","Fertilization"],"a":1,"e":"Ans. is ''b'' i.e., First meiosis Oogenesis Oogenesis refers to the process of formation of ova from the primitive germ cells. Unlike fetal testis (in which spermatogenesis beings at puberty), the fetal ovary begins oogenesis by 10 weeks of gestation. o The sequence of events in oogenesis are : i) The primitive germ cells undergo mitotic divisions to form oogonia (diploid Oogonium is unique in that it is the only female cell in which both ''X'' chromosomes are active. ii) The oogonia proliferate by mitosis to form primary oocytes (diploid cells). iii) Primary oocytes formed from the oogonia enter a prolonged prophase (diplotene stage) of the first meiotic division and remain in this stage until ovulation occurs after puberty. iv) Primary oocytes completes the first meiotic division at puberty just before ovulation to form secondary oocyte (haploid cell) and 1st polor body. v) Secondary oocyte immediately begins second meiotic division but this division stops at metaphase and is completed only if the mature ovum (ootid) is fertilized with sperm. At that time second polor body (polocyte) is extruded and the fertilized ovum proceeds to form a new individual. Fertilization normally occurs in the ampulla of fallopian tube.","pyqMatches":[{"year":"2014","no":190,"q":"First polar body is formed after ?","o":["Mitosis","First meiosis","Second meiosis","Fertilization"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3919, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 16, '{"id":3919,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":16,"q":"Conceptus enters uterine cavity in which cell stage ?","o":["4 cells","8 cells","16 cells","32 cells"],"a":2,"e":"Ans. is ''c'' i.e., 16 cells Fertilization and implantation Fertilization refers to fusion of male and female gametes (i.e. spermatozoon and ovum). It takes place in the middle segment (ampulla) of fallopian tube. Before fertilization, the ovum and sperms reach the ampulla for fertilization. Fusion of spermatocyte and ovum leads to formation of zygote. First week of development begins immediately after fertilization and includes :? i) Cleavage of zygote : Zygote (fertilized ovum) starts dividing immediately and large zygote is subdivided into smaller daughter cells called blastomeres. Blastomeres are still surrounded by zona pellucida. Cleavage occurs in fallopian tube (uterine tube). ii) Formation of morula : At about 16 cells stage the blastomeres tightly align by the process of compaction to form a compact ball of cells called morula (mulberry). This process of compaction leads to segregation of cells into two groups (i) inner cells (inner cell mass), and (ii) outer cells (outer cell mass). Morula enters uterine cavity 4 days after fertilization. iii) Formation of blastocyst : As the morula enters the uterine cavity, uterine fluid diffuses through zona pellucida and fills small intercellular gaps between blastomeres, and morula is converted to blastocyst. Blastocyst consists of :? a) Zona pellucida : Outer covering. b) Embryoblast : A group of centerally located cells of inner cell mass and later give rise to tissues of embryo proper. c) Trophoblast : A thin outer layer of cells formed from outer cells mass and later give rise extraembryonic tissues. d) Blastocele : Cavity of blastocyst : The region of blastocyst containing embryoblast is known as embryonic pole and the opposite pole, the abembryonic pole. The trophoblasts overlying the embryoblast at embryonic pole is called polar trophoblast and that occupying the rest of wall called mural trophoblast. Between 5-6 days after fertilization, blastocyst hatches from zona pellucida, and this naked blastocyst is ready for implantation","pyqMatches":[{"year":"2014","no":202,"q":"Conceptus enters uterine cavity in which cell stage ?","o":["4 cells","8 cells","16 cells","32 cells"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3920, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Gynecology', 17, '{"id":3920,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Gynecology","sourceNo":17,"q":"Implantation occurs on which menstrual cycle day ?","o":["5-7 days","20-22 days","14-18 days","26-28 days"],"a":1,"e":"Ans. is ''b'' i.e., 20-22 days Implantation occurs at 6-7 days after fertilization. Ovulation occurs at 14th day of menstrual cycle and fertilization occur within 24 hours after ovulation. Thus, implantation will correspond to 20-22 days of menstrual cycle.","pyqMatches":[{"year":"2014","no":193,"q":"Implantation occurs on which menstrual cycle day ?","o":["5-7 days","20-22 days","14-18 days","26-28 days"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3921, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 18, '{"id":3921,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":18,"q":"Blastocyte comes out on which day after fertilization ?","o":["4-7 days","10-12 days","12-15 days","15-20 days"],"a":0,"e":"Ans. is ''a'' i.e., 4-7 days Free floating unimplanted blastocyst is seen on 4-5 days.","pyqMatches":[{"year":"2014","no":194,"q":"Blastocyte comes out on which day after fertilization ?","o":["4-7 days","10-12 days","12-15 days","15-20 days"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3922, 'OBG', 'Contraception & Family Planning', 'Easy', 'Gynecology', 19, '{"id":3922,"subject":"OBG","chapter":"Contraception & Family Planning","difficulty":"Easy","source":"Gynecology","sourceNo":19,"q":"DMPA is given once in -","o":["3 months","6 months","9 months","45 days"],"a":0,"e":"Ans. is ''a'' i.e., 3 months HORMONAL CONTRACEPTIVES These are hormonal preparations used for reversible suppression of fertility. Types of methods A. Oral Combined pill (monophasic pills) It contains an estrogen and a progestin. This is the most effective and popular method. Efficacy is 98-99% Preparation are - Ethinyl estradiol 30 pg (•03 mg) + Norgestrel 0.3 mg Ethinyl estradiol 50 .tg (•05 mg) + Levonorgestrel 0.25 mg Ethinyl estradiol 30 pig (•03 mg) + Desogestreol 0.15 mg One tablet (containing estrogen and progesterone) is taken daily for 21 days starting on 51\"day of mensturation. Phased regimens The estrogen dose is kept constant (or varied slightly between 30-40 mg), while the amount of pregestin is low in first phase and progressiely higher in the second and third phases. Preparations are Biphasic pills Day 1-10 → Ethinyl estradiol 35 mg + Norethindrone 0.5 mg Day 11-21 → Ethinyl estradiol 35 mg + Norethindrone 1 mg. Triphasic pills Day 1-7 → Ethinyl estradiol 35 mg + Norethindrone 0.5 mg Day 8-14 →Ethinyl estradiol 35 mg + Norethindrone 0.75 mg Day 15-21 → Ehinyl estradiol 35 mg + Norethindrone 1 mg Minipill (progestin only pill) A low dose progestin pill is taken daily without any gap. Preparations → Norethindrone (0.35 mg) or Norgestrel 75 mg. Postcoital (emergency) pills. a) Levonorgestrel 0.5 mg + ethinyl estradiol 0.1 mg —> within 72 hours of unprotected intercourse and repeated after 12 hours - Yuzpe method. b) Levonorgestrel alone 0.75 mg taken twice with 12 hour gap within 72 hours of unprotected intercourse → method of choice for emergency contraception. c) Mifepristone 600 mg single dose within 72 hours of unprotected intercourse. B. Injectable They are given i.m. as oily solution 1.Long acting progestin alone a) Depot medroxy progesterone acetate (DMPA) 150 mg at 3 month intervals. or b) Norethindrone (norethisterone) enanthate (NEE) 200 mg at 2 months intervals. c) The most important undesirable property is complete disruption of menstural bleeding pattern and total amenorrhoea (more common with DMPA). 2.Long acting progestin + long acting estrogen - once a month.","pyqMatches":[{"year":"2014","no":610,"q":"DMPA is given once in","o":["3 months","6 months","9 months","45 days"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3923, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Gynecology', 20, '{"id":3923,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Gynecology","sourceNo":20,"q":"Patient of juvenile myoclonic epilepsy on valproate comes to you at 5 months of pregnancy with level H scan normal what will you advise?","o":["Change the drug","Continue the drug in same dose","Decrease the dose of drug","Increase the dose of drug"],"a":1,"e":"Ans. is ''b'' i.e., Continue the drug in same dose Valproic acid has the risk of fetal malformations during the first trimester of pregnancy. This patient has normal level II scan at 5 months of pregnancy so the risk period of valproate is already over and valproate is the drug of choice in juvenile myoclonic epilepsy. Thus the drug shoud be continued in the same doses.","pyqMatches":[{"year":"2014","no":536,"q":"Patient of juvenile myoclonic epilepsy on valproate comes to you at 5 months of pregnancy with level H scan normal what will you advise?","o":["Change the drug","Continue the drug in same dose","Decrease the dose of drug","Increase the dose of drug"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3924, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Gynecology', 21, '{"id":3924,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Gynecology","sourceNo":21,"q":"Gestational Trophoblastic neoplasm does not include-","o":["Choriocarcinoma","Placental site trophoblastic tumour","Invasive mole","Partial mole"],"a":3,"e":"Ans. D. Partial Mole The main types of gestational trophoblastic diseases are: Hydatidiform mole (complete or partial) Invasive mole Choriocarcinoma Placental-site trophoblastic tumor Epithelioid trophoblastic tumor Note: In the given best option best answer can be partial as partial hydatidiform mole is not completely mentioned in it.","pyqMatches":[{"year":"2019","no":219,"q":"Gestational Trophoblastic neoplasm does not include","o":["Choriocarcinoma","Placental site trophoblastic tumour","Invasive mole","Partial mole"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3925, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 22, '{"id":3925,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":22,"q":"Which vaccine is contraindicated in pregnancy:","o":["Chicken pox","Rabies","Tet toxoid","Hepatitis B"],"a":0,"e":"Ans. A. Chicken pox As a rule of thumb the vaccination with live viral or bacterial vaccine is contraindicated in pregnancy. The important ones are : – Measles Mumps Poliomyelitis Rubella Yellow fever Varicella BCG","pyqMatches":[{"year":"2019","no":220,"q":"Which vaccine is contraindicated in pregnancy:","o":["Chicken pox","Rabies","Tet toxoid","Hepatitis B"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3926, 'OBG', 'Contraception & Family Planning', 'Moderate', 'Gynecology', 23, '{"id":3926,"subject":"OBG","chapter":"Contraception & Family Planning","difficulty":"Moderate","source":"Gynecology","sourceNo":23,"q":"45 years female with 3 months menorrhagia. USG showing 2 cm submucosal fibroid.Treatment options.","o":["Ocp for 3 months","Progesterone for 3 months","Endometrial sampling","Hysterectomy"],"a":3,"e":"Ans. D. Hysterectomy YOUNG WOMEN OLDER WOMEN Contraception not desirable Contraception desired Combined OCPs Progestogens and other hormones Mirena Rule out cancer &uterine pathology Progestogens Ethamsylate, NSAIDs Estrogen Tranexamic for 3–4 months GnRH 3–4 months Effective Fails Normal uterus (DUB) Uterine pathology Continue for 6–9 months Minimal invasive surgery Hysterectomy with conservation of ovaries Progestogens and others ?No response Hysterectomy with removal of ovaries after 50 years Surgery Removal of an intrauterine contraceptive device if medical therapy fails. Myomectomy/hysterectomy for uterine fibroids. Wedge resection/hysterectomy for adenomyosis of the uterus. Dilatation and curettage with blood transfusion is the primary treatment of puberty menorrhagia with low Hb% Multipara, hypertensive woman with menorrhagia should be treated with MIRENA Hysterectomy with or without removal of the adnexa according to the age and the individual needs of the patient.","pyqMatches":[{"year":"2019","no":221,"q":"45 years female with 3 months menorrhagia. USG showing 2 cm submucosal fibroid.Treatment options.","o":["Ocp for 3 months","Progesterone for 3 months","Endometrial sampling","Hysterectomy"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3927, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 24, '{"id":3927,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":24,"q":"In low ovarian reserve,anti mullerian hormone level will be:","o":["<1","1-4",">7",">10"],"a":0,"e":"Ans. A. <1 AMH and ovarian reserve AMH of 1.0 has very poor ovarian reserve The central concept for the measurement of blood levels of AMH to determine ovarian reserve is this: women with lower AMH levels have a lower ovarian reserve than women with high AMH levels. AMH is currently being used by fertility specialists to help predict women who may respond poorly to fertility medications and in general, couples who are less likely to be successful with fertility treatment.","pyqMatches":[{"year":"2019","no":222,"q":"In low ovarian reserve,anti mullerian hormone level will be:","o":["<1","1-4",">7",">10"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3928, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 25, '{"id":3928,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":25,"q":"Presenting diameter of full flexed head:","o":["Suboccipito-bregmatic diameter","Suboccipito-frontal diameter","Occipito-frontal diameter","Occipito-posterior position"],"a":0,"e":"Ans. A. Suboccipito-bregmatic diameter Suboccipito-bregmatic diameter : The diameter is from suboccipital region to centre of the bregma. Diameter = 9.5 cm Fetal head circumference is smallest (32 cm ) Head well flexed Flexed vertex presentation Suboccipito-frontal diameter : Diameter calculated from prominence at mid frontal bone to the under-surface of the occipital bone where it joins neck The diameter is 10.5 cm Vertex is partially deflexed. Results in occipito-posterior position. Occipito-frontal diameter : Diameter extends from the prominent point of mid-frontal bone to the most prominent point of occipital bone The diameter = 11.5 cm Fetal head circumference ~ 34.5 cm Vertex is deflexed Associated with Direct occipito- posterior position. Occipito-posterior position : It is a vertex presentation in which the occiput is placed posteriorly .","pyqMatches":[{"year":"2019","no":223,"q":"Presenting diameter of full flexed head:","o":["Suboccipito-bregmatic diameter","Suboccipito-frontal diameter","Occipito-frontal diameter","Occipito-posterior position"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3929, 'OBG', 'Contraception & Family Planning', 'Easy', 'Gynecology', 26, '{"id":3929,"subject":"OBG","chapter":"Contraception & Family Planning","difficulty":"Easy","source":"Gynecology","sourceNo":26,"q":"What is the dose of ulipristal acetate?","o":["300mg","30mg","300µg","30µg"],"a":1,"e":"Ans. B. 30 mg Ulipristal (Ella) is a progesterone agonist/antagonist marketed for emergency contraception. It is available by prescription only. Its mechanism of action varies based on time of administration. When taken before ovulation, ulipristal delays or inhibits ovulation. Administration in the early luteal phase may decrease endometrial thickness and affect implantation of a fertilized egg. Ulipristal is labeled for use as an emergency contraceptive following unprotected sexual intercourse or contraceptive failure. One tablet(30-mg tablet) taken as soon as possible, within 120 hours (five days) of unprotected sexual intercourse or contraceptive failure.","pyqMatches":[{"year":"2019","no":224,"q":"What is the dose of ulipristal acetate?","o":["300mg","30mg","300µg","30µg"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3930, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 27, '{"id":3930,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":27,"q":"Premature ejaculation is a part of which phase of sexual disorders?","o":["Excitement phase","Plateau phase","Orgasm phase","Refractory phase"],"a":2,"e":"Ans. C. Orgasm phase The male sexual response is described as a sequence of phases including 4 stages: sexual desire, arousal, orgasm (ejaculation) and resolution. The male sexual dysfunction usually occurs in one or more of the three first stages of the sexual response cycle, including: Dysfunctions of sexual desire (e.g. hypoactive sexual desire) Arousal (e.g. erectile dysfunction) Orgasm/ejaculation (e.g. premature ejaculation, retarded ejaculation or inability to ejaculate). Premature ejaculation occurs due to the rapid evolution of the two first stages of the sexual response cycle and is not necessarily related to strong sexual arousal or changes in erection. Premature Ejaculation seems to be a neurobiological problem that is related to low serotonin levels in those regions of the central nervous system that regulate ejaculation (brain and spinal cord).","pyqMatches":[{"year":"2019","no":215,"q":"Premature ejaculation is a part of which phase of sexual disorders?","o":["Excitement phase","Plateau phase","Orgasm phase","Refractory phase"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3931, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Gynecology', 28, '{"id":3931,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Gynecology","sourceNo":28,"q":"60 year woman comes with 3rd degree uterine prolapse. What will be the management?","o":["Vaginal hysterectomy with pelvic floor repair","Pelvic floor repair","Sacrospinous fixation","Pessary"],"a":0,"e":"Ans. A. Vaginal hysterectomy with pelvic floor repair Uterine prolapse surgery is performed to remove the uterus and repair the weak tissue. Uterine prolapse frequently occurs in postmenopausal women who’ve had one or more vaginal deliveries. Sagging of the pelvic muscles which leads to uterine prolapse can occur: If supportive tissues are damaged during pregnancy and delivery Due to estrogen loss As a result of straining repeatedly over the years (chronic cough, constipation etc.) Due to gravitational effects Depending on factors like age of the woman, desire for becoming pregnant and the overall state of a woman’s health, the treatment plan is decided. Here the woman is of old age (non gestational) and have 3rd degree of prolapse. So best management of choice will be Vaginal hysterectomy with pelvic floor repair.","pyqMatches":[{"year":"2019","no":211,"q":"60 year woman comes with 3rd degree uterine prolapse. What will be the management?","o":["Vaginal hysterectomy with pelvic floor repair","Pelvic floor repair","Sacrospinous fixation","Pessary"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3932, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Gynecology', 29, '{"id":3932,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Gynecology","sourceNo":29,"q":"Day 20 of menstrual cycle falls under which phase?","o":["Menstrual phase","Follicular phase","Ovulation phase","Luteal phase"],"a":3,"e":"Ans. D. Luteal phase The entire duration of a Menstrual cycle can be divided into four main phases:","pyqMatches":[{"year":"2019","no":212,"q":"Day 20 of menstrual cycle falls under which phase?","o":["Menstrual phase","Follicular phase","Ovulation phase","Luteal phase"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3933, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 30, '{"id":3933,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":30,"q":"Chromosome number of partial hydatidiform mole is-","o":["46 XX","45 XO","46 XXY","69 XXX"],"a":3,"e":"Ans. D. 69XX A partial hydatidiform mole is a triploid pregnancy with 69 instead of 46 chromosomes and another strange complication of the reproductive process. Partial hydatidiform mole can be identified by ultrasound showing placenta tissue, some hygromatous cysts, some fetal oddities, but no clear fetus structure. Ultrasound is strictly an indicator. After spontaneous abortion or dilation and curettage, tissue needs to be examined by pathology and cytogenetics needs to be determined. If a triploid karyotype is determined as 69, XXX, 69XXY, or 69 XYY [6], then a partial mole can be confirmed.","pyqMatches":[{"year":"2019","no":213,"q":"Chromosome number of partial hydatidiform mole is","o":["46 XX","45 XO","46 XXY","69 XXX"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3934, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 31, '{"id":3934,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":31,"q":"Vulvar atrophy and itching are treated by-","o":["Estrogen ointment","Antihistamines","Tamoxifen","None"],"a":0,"e":"Ans. A. Estrogens ointment Atrophic vaginitis, the medical term for this condition, occurs as a result of deterioration of the vaginal tissue. It’s a common condition in postmenopausal women because as estrogen levels drop, the tissue that lines the vagina becomes thinner and more easily damaged. Women with atrophic vaginitis may also experience vaginal itching, burning, frequent urination, or vaginal discharge. Women can treat this condition topically with estrogen creams, tablets (Vagifem), or an estrogen-releasing ring placed in the vagina (Estring). Oral estrogen, available with a doctor’s prescription, will also restore vaginal tissue. Vaginal lubricants offer an alternative for women wary of using estrogen. Moisturizers such as Replens, Astroglide, and Lubrin can reduce symptoms and make sexual intercourse more comfortable.","pyqMatches":[{"year":"2019","no":214,"q":"Vulvar atrophy and itching are treated by","o":["Estrogen ointment","Antihistamines","Tamoxifen","None"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3935, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 32, '{"id":3935,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":32,"q":"PGF2 alpha maximum dose in PPH is-","o":["2000 µg","200 µg","2 mg","20 mg"],"a":2,"e":"Ans. C. 2mg Drug doses for management of PPH: 15-Methyl prostaglandin F2a: Dose and route:IM: 0.25 mg Continuing dose:0.25 mg every 15 minutes Maximum dose:8 doses (Total 2 mg) Precautions/ contraindications:Asthma","pyqMatches":[{"year":"2019","no":226,"q":"PGF2 alpha maximum dose in PPH is","o":["2000 µg","200 µg","2 mg","20 mg"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3936, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 33, '{"id":3936,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":33,"q":"Which of the following is false as physiological change in pregnancy?","o":["Increase cardiac output","Increase total protein","Increase residual volume","Increase GFR"],"a":2,"e":"Ans. C. Increase residual volume The respiratory rate is essentially unchanged, but tidal volume and resting minute ventilation increase significantly as pregnancy advances. The functional residual capacity and the residual volume are decreased as a consequence of the elevated diaphragm.","pyqMatches":[{"year":"2019","no":203,"q":"Which of the following is false as physiological change in pregnancy?","o":["Increase cardiac output","Increase total protein","Increase residual volume","Increase GFR"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3937, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 34, '{"id":3937,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":34,"q":"Overt gestational diabetes is defined as blood glucose more than_?","o":[">200 mg/dl",">126 mg/dl",">100 mg/dl",">180 mg/dl"],"a":1,"e":"Ans. B. >126 mg/dl If fasting is 92-125 mg/dl it is diagnosed as GDM and if it is = 126 mg/dl it is designated as overt Diabetes","pyqMatches":[{"year":"2019","no":204,"q":"Overt gestational diabetes is defined as blood glucose more than_?","o":[">200 mg/dl",">126 mg/dl",">100 mg/dl",">180 mg/dl"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3938, 'OBG', 'Antenatal Care & Complications', 'Easy', 'Gynecology', 35, '{"id":3938,"subject":"OBG","chapter":"Antenatal Care & Complications","difficulty":"Easy","source":"Gynecology","sourceNo":35,"q":"MgSO4 have no role in prevention of-","o":["Seizures in severe pre-eclampsia","Recurrent seizures in eclampsia","RDS in premature baby","Bradycardia"],"a":2,"e":"Ans. C. RDS in premature baby Indicated to prevent seizures associated with pre-eclampsia, and for control of seizures with eclampsia. Magnesium sulfate (MgSO4) is commonly used as an anticonvulsant for toxemia and as a tocolytic agent for premature labor during the last half of pregnancy. Toxicity of I/V magnesium sulfate includes cardiac arrhythmias, muscular paralysis, respiratory depression and CNS depression in mother as well as the neonate.","pyqMatches":[{"year":"2019","no":205,"q":"MgSO4 have no role in prevention of","o":["Seizures in severe pre-eclampsia","Recurrent seizures in eclampsia","RDS in premature baby","Bradycardia"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3939, 'OBG', 'Labour & Delivery', 'Easy', 'Gynecology', 36, '{"id":3939,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Gynecology","sourceNo":36,"q":"Green frothy vaginal discharge is produced by –","o":["Herpes simplex","Candida albicans","Trichomonas vaginalis","Normal vaginal flora"],"a":2,"e":"Ans. C. Trichomonas vaginalis Trichomoniasis – It is a sexually transmitted disease It is almost entirely a disease of child-bearing age The vaginal discharge is frothy, slightly green in colour and profuse. There are multiple punctate strawberry spots on the vaginal vault and portio vaginalis of cervix. Diagnosis : Culture is 98% reliable","pyqMatches":[{"year":"2019","no":206,"q":"Green frothy vaginal discharge is produced by –","o":["Herpes simplex","Candida albicans","Trichomonas vaginalis","Normal vaginal flora"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3940, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Gynecology', 37, '{"id":3940,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Gynecology","sourceNo":37,"q":"Which of the following is an absolute CONTRAINDI​CATION to OCP use:","o":["Chronic renal disease","DVT","Diabetes mellitus","History of amenorrhea"],"a":1,"e":"Ans. B. DVT Contraindications to combined oral contraceptives They are generally accepted to be contraindicated in women with pre-existing cardiovascular disease, in women who have a familial tendency to form blood clots/ thrombosis (such as familial factor V Leiden), women with severe obesity and/or hypercholesterolemia (high cholesterol level), and in smokers over age 40. COCP are also contraindicated for women with liver tumors, hepatic adenoma or severe cirrhosis of the liver, and for those with known or suspected breast cancer.","pyqMatches":[{"year":"2019","no":207,"q":"Which of the following is an absolute CONTRAINDI​CATION to OCP use:","o":["Chronic renal disease","DVT","Diabetes mellitus","History of amenorrhea"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3941, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 38, '{"id":3941,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":38,"q":"Which of the following statement is correct about acute fatty liver of pregnancy?","o":["Occurs in 1 in 1000 pregnancy","Mostly seen in last trimester","Common if female fetus is present","May be associated with decreased uric acid"],"a":1,"e":"Ans. B. Mostly seen in last trimester Acute fatty liver of pregnancy is usually seen in obese woman. It is more commonly seen in woman carrying a male foetus. The neonate is at risk of fatty infiltration of liver. It More commonly occurs in 3rd trimester. It May be associated with ?uric acid.","pyqMatches":[{"year":"2019","no":208,"q":"Which of the following statement is correct about acute fatty liver of pregnancy?","o":["Occurs in 1 in 1000 pregnancy","Mostly seen in last trimester","Common if female fetus is present","May be associated with decreased uric acid"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3942, 'OBG', 'Labour & Delivery', 'Moderate', 'Gynecology', 39, '{"id":3942,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Moderate","source":"Gynecology","sourceNo":39,"q":"Female with 41 wk gestation confirmed by radiological investigation, very sure of her LMP, no uterine contractions, no effacement and no dilatation. What should not be done?","o":["Intracervical foley’s","PGE1 tab","PGE2 gel","PGF2alpha"],"a":3,"e":"Ans. D. PGF2alpha PgF2 alpha is a uterine relaxant so it can’t be used in induction of labour.","pyqMatches":[{"year":"2019","no":209,"q":"Female with 41 wk gestation confirmed by radiological investigation, very sure of her LMP, no uterine contractions, no effacement and no dilatation. What should not be done?","o":["Intracervical foley’s","PGE1 tab","PGE2 gel","PGF2alpha"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3943, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 40, '{"id":3943,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":40,"q":"Double decidua sign is seen during-","o":["1St trimester","2nd early trimester","2nd late trimester","3rd trimester"],"a":0,"e":"Ans. A. 1st trimester The double decidual sac sign (DDSS) is a useful feature on early pregnancy ultrasound to confirm an early intrauterine pregnancy (IUP) when the yolk sac or embryo is still not visualized. The “Double Decidual Sign”, first described by Nyberg and co- workers consists of two echogenic rings surrounding the hypoechoic gestational sac. The inner ring represents the chorion, embryonic disc and decidua capsularis. The outer ring represents the decidua parietalis.","pyqMatches":[{"year":"2019","no":210,"q":"Double decidua sign is seen during","o":["1St trimester","2nd early trimester","2nd late trimester","3rd trimester"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3944, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Gynecology', 41, '{"id":3944,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Gynecology","sourceNo":41,"q":"In Medical termination of pregnancy, according to FDA, Misoprostol is given after how many hours of Mifepristone?","o":["24 hours","48 hours","72 hours","96 hours"],"a":1,"e":"Ans. is ''b'' i.e., 48 hours FDA approved protocol - (Original protocol) 600 mg of mifepristone (i.e., 3 tablets) given orally on day 1 followed 2 days (48 hours) later by oral misoprostol 400 tig (2 tablets) on day","pyqMatches":[{"year":"2015","no":1501,"q":"In Medical termination of pregnancy, according to FDA, Misoprostol is given after how many hours of Mifepristone?","o":["24 hours","48 hours","72 hours","96 hours"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3945, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 42, '{"id":3945,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":42,"q":"First symptom invulval cancer is-","o":["Pain","Pruritis","Ulcer","Blood discharge"],"a":1,"e":"Ans. B.Pruritis Women with WN and yulvar cancer commonly present with pruritus and a visible lesion. However, pain, bleeding, and ulceration may also be initial complaints''","pyqMatches":[{"year":"2015","no":1559,"q":"First symptom invulval cancer is","o":["Pain","Pruritis","Ulcer","Blood discharge"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3946, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 43, '{"id":3946,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":43,"q":"Which is increased in premature ovarian failure :","o":["Sr. Inhibin","Sr. FSH","Sr. Estradiol","Both A and B"],"a":1,"e":"Answer- B. Sr. FSH In premature ovarian failure :-","pyqMatches":[{"year":"2015","no":1534,"q":"Which is increased in premature ovarian failure :","o":["Sr. Inhibin","Sr. FSH","Sr. Estradiol","Both A and B"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3947, 'OBG', 'Miscellaneous', 'Moderate', 'Gynecology', 44, '{"id":3947,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Gynecology","sourceNo":44,"q":"All of the following are markers of ovarian reserve except -","o":["Inhibin A","Estradiol concentration","Inhibin B","Ovarian volume"],"a":0,"e":"Answer- A. Inhibin A Basal FSH and Estradiol concentration Clomiphene Citrate Challenge Test Inhibin B Antimullerian hormone Antral follicle count Ovarian volume","pyqMatches":[{"year":"2015","no":1535,"q":"All of the following are markers of ovarian reserve except","o":["Inhibin A","Estradiol concentration","Inhibin B","Ovarian volume"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3948, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 45, '{"id":3948,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":45,"q":"Most common site involved in genital TB -","o":["Fallopian tubes","Endometrium","Ovaries","Vulvo - vaginal part"],"a":0,"e":"Answer- A. Fallopian tubes Fallopian Tubes → 90 - 100","pyqMatches":[{"year":"2015","no":1536,"q":"Most common site involved in genital TB","o":["Fallopian tubes","Endometrium","Ovaries","Vulvo - vaginal part"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3949, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Gynecology', 46, '{"id":3949,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Gynecology","sourceNo":46,"q":"Which is not a side effect of POP [Progestin only pill]","o":["Ovarian cysts","Venous thromboembolism","Increased risk of diabetes mellitus","Ectopic pregnancy"],"a":1,"e":"Answer- B. Venous thromboembolism Adverse effects of progestin only pill (minipill) Menstural irregularities Headache, nausea, dizziners Bloating or weight gain Increased risk of INDDM Ovarian cysts Breast tenderness Acne Ectopic pregnancy","pyqMatches":[{"year":"2015","no":1537,"q":"Which is not a side effect of POP [Progestin only pill]","o":["Ovarian cysts","Venous thromboembolism","Increased risk of diabetes mellitus","Ectopic pregnancy"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3950, 'OBG', 'Labour & Delivery', 'Moderate', 'Gynecology', 47, '{"id":3950,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Moderate","source":"Gynecology","sourceNo":47,"q":"Maternal age is not associated with -","o":["Preterm labour","Post maturity","Aneuploidy","Hydatidiform mole"],"a":0,"e":"Answer- A. Preterm labour Recent evidence however suggests lowest incidence of preterm labor between 18 and 35 years of age and higher risk in lower and higher age groups.","pyqMatches":[{"year":"2015","no":1538,"q":"Maternal age is not associated with","o":["Preterm labour","Post maturity","Aneuploidy","Hydatidiform mole"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3951, 'OBG', 'Contraception & Family Planning', 'Easy', 'Gynecology', 48, '{"id":3951,"subject":"OBG","chapter":"Contraception & Family Planning","difficulty":"Easy","source":"Gynecology","sourceNo":48,"q":"What is to be done if 2 OCP is missed on day 17 - 18 of the cycle -","o":["Take 2 pills on the next 2 days","Use back up contraceptive","Both a and b","Continue taking single pill per day"],"a":1,"e":"Answer- B. Use back up contraceptive Missing pills while on OCP - Management : Missing one pill (late upto 24 hours) -take the missed pill at once and continue the same regimen. Missing two pills in the first week (days 1 - 7) - take two pills on each of the next two days and then continue the schedule. Extra - precaution (back up) - alternative contraception Missing two pills in the third week (days 15 - 21) or if more than two pills are missed at any time - another form of contraception. Start the next pack without a break. Missing any of the 7 inactive pills - throw away the missed pills. Start the new pack as usual.","pyqMatches":[{"year":"2015","no":1539,"q":"What is to be done if 2 OCP is missed on day 17 - 18 of the cycle","o":["Take 2 pills on the next 2 days","Use back up contraceptive","Both a and b","Continue taking single pill per day"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3952, 'OBG', 'Gynecologic Oncology', 'Easy', 'Gynecology', 49, '{"id":3952,"subject":"OBG","chapter":"Gynecologic Oncology","difficulty":"Easy","source":"Gynecology","sourceNo":49,"q":"Most common complication of dermoid cyst is -","o":["Cyst Rupture","Torsion","Malignant degeneration","None of the above"],"a":1,"e":"Answer- B. Torsion Torsion is the most common complication occurring in Dermoid cyst. Because of the fat content of the cyst, it is lighter than other ovarian tumors and therefore easily torsioned. Almost 15% of dermoid cysts undergo torsion.","pyqMatches":[{"year":"2015","no":1540,"q":"Most common complication of dermoid cyst is","o":["Cyst Rupture","Torsion","Malignant degeneration","None of the above"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3953, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Gynecology', 50, '{"id":3953,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Gynecology","sourceNo":50,"q":"Management of tubal ectopic pregnancy of 2.5 x 3 cm is -","o":["Medical management","Salpingectomy","According to presence of fetal cardiac activity","Observation"],"a":2,"e":"Answer- C. According to presence of fetal cardiac activity Conservative management Medical management :","pyqMatches":[{"year":"2015","no":1542,"q":"Management of tubal ectopic pregnancy of 2.5 x 3 cm is","o":["Medical management","Salpingectomy","According to presence of fetal cardiac activity","Observation"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3954, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 51, '{"id":3954,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":51,"q":"Dose of dexamethasone for fetal lung maturity is -","o":["6 mg","12 mg","18 mg","24 mg"],"a":0,"e":"Answer- A. 6 mg Betamethasone - 12 mg i.m. 24 hours apart for 2 doses Dexamethasone - 6 mg i.m. 12 hours apart for 4 doses. Betamethasone - Steroid of choice.","pyqMatches":[{"year":"2015","no":1543,"q":"Dose of dexamethasone for fetal lung maturity is","o":["6 mg","12 mg","18 mg","24 mg"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3955, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Gynecology', 52, '{"id":3955,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Gynecology","sourceNo":52,"q":"Management of a patient with complete placenta previa at 38 weeks gestation without any vaginal bleeding is -","o":["Expectant management","Macafee and Johnson regimen","Elective caesarean section","Emergency caesarean section"],"a":2,"e":"Answer- C. Elective caesarean section As this patient is more than 37 weeks gestation, active interference is mandatory. But as this patient is not actively bleeding therefore elective caesarean section can be planned.","pyqMatches":[{"year":"2015","no":1545,"q":"Management of a patient with complete placenta previa at 38 weeks gestation without any vaginal bleeding is","o":["Expectant management","Macafee and Johnson regimen","Elective caesarean section","Emergency caesarean section"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3956, 'OBG', 'Labour & Delivery', 'Moderate', 'Gynecology', 53, '{"id":3956,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Moderate","source":"Gynecology","sourceNo":53,"q":"True about nabothian cyst is all except -�","o":["Squamous epithelium occludes the mouth of the glands","It is seen in chronic irritation and inflammation","It is a pathology of the cervix","It is pre - malignant"],"a":3,"e":"Answer- D.�It is pre - malignant Seen in chronic inflammation of cervix. It is the result of blockage of mouth of the glands of the cervix. During the process of healing, the squamous epithelium replaces the columnar epithelium. The blocked glands become distended with secretion and form small cysts which can be seen with the naked eye, the so-called nabothian follicles. The condition is neither malignant nor pre-malignant.","pyqMatches":[{"year":"2015","no":1546,"q":"True about nabothian cyst is all except - �","o":["Squamous epithelium occludes the mouth of the glands","It is seen in chronic irritation and inflammation","It is a pathology of the cervix","It is pre - malignant"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3957, 'OBG', 'Postpartum & Puerperium', 'Easy', 'Gynecology', 54, '{"id":3957,"subject":"OBG","chapter":"Postpartum & Puerperium","difficulty":"Easy","source":"Gynecology","sourceNo":54,"q":"Most common cause of pelvic inflammatory disease is -","o":["Sexually transmitted disease","IUCD","Pelvic peritonitis","Puerperal sepsis"],"a":0,"e":"Answer- A. Sexually transmitted disease Sexually transmitted disease is the most common cause. Gonococcal and chlamydial infections are the most common cause. Postabortal or puerperal sepsis. IUCD Tuberculosis Pelvic peritonitis, due to appendicitis and diverticulitis.","pyqMatches":[{"year":"2015","no":1547,"q":"Most common cause of pelvic inflammatory disease is","o":["Sexually transmitted disease","IUCD","Pelvic peritonitis","Puerperal sepsis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3958, 'OBG', 'Miscellaneous', 'Moderate', 'Gynecology', 55, '{"id":3958,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Gynecology","sourceNo":55,"q":"There is overlapping of skull sutures which can be reduced with gental pressure. What is the grade of moulding ?","o":["Grade 1","Grade 2","Grade 3","Grade 4"],"a":1,"e":"Answer- B. Grade 2 There are three gradings of moulding : Grade 1 - the bones touching but not overlapping Grade 2 -overlapping but easily separated Grade 3 - fixed overlapping.","pyqMatches":[{"year":"2015","no":1548,"q":"There is overlapping of skull sutures which can be reduced with gental pressure. What is the grade of moulding ?","o":["Grade 1","Grade 2","Grade 3","Grade 4"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3959, 'OBG', 'Labour & Delivery', 'Easy', 'Gynecology', 56, '{"id":3959,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Gynecology","sourceNo":56,"q":"Risk factor for cervical carcinoma is -","o":["Smoking","Human papilloma virus","Low socioeconomic status","All of the above"],"a":3,"e":"Answer- D. All of the above HPV infection. Coitus before 18 years. Multiple sexual partners. Delivery of the first baby before the age of 20 years. Multiparity with poor birth spacing between pregnancies. Poor personal hygiene. Poor socioeconomic status. Smoking. Immunosupressive disease.","pyqMatches":[{"year":"2015","no":1549,"q":"Risk factor for cervical carcinoma is","o":["Smoking","Human papilloma virus","Low socioeconomic status","All of the above"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3960, 'OBG', 'Miscellaneous', 'Moderate', 'Gynecology', 57, '{"id":3960,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Gynecology","sourceNo":57,"q":"45 yrs female with G5P4A0L4 with LMP 25.8.15, gestational age will be how many weeks on date 11.5.15?","o":["32 weeks","35 weeks","36 weeks","40 weeks"],"a":2,"e":"Answer- C. 36 weeks if the patient''s LMP is 25.8.15 then EDD would be 3.6.16. On 11.5.15, patient would be 23 days left would for EDD, that is 3 weeks and 2 days. Subtracting this from 40 weeks, the patients gestational age would be 36 weeks and 5 days.","pyqMatches":[{"year":"2015","no":1512,"q":"45 yrs female with G5P4A0L4 with LMP 25.8.15, gestational age will be how many weeks on date 11.5.15?","o":["32 weeks","35 weeks","36 weeks","40 weeks"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3961, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 58, '{"id":3961,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":58,"q":"Which of the following about abdominal pregnancy is true?","o":["Primary abdominal pregnancy is more common","If placenta is densely adhered, it should be separated alongwith the organ it overlies","Around 50% of the fetus reach full term and survive","If placenta is left behind, infection can occur"],"a":3,"e":"Answer- D. If placenta is left behind, infection can occur Abdominal Pregnancy A) Primary Abdominal Pregnancy Criteria to diagnose primary abdominal pregnancy by Studiford :","pyqMatches":[{"year":"2015","no":1511,"q":"Which of the following about abdominal pregnancy is true?","o":["Primary abdominal pregnancy is more common","If placenta is densely adhered, it should be separated alongwith the organ it overlies","Around 50% of the fetus reach full term and survive","If placenta is left behind, infection can occur"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3962, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 59, '{"id":3962,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":59,"q":"Oxygen consumption increases in pregnancy by","o":["10%","20%","30%","40%"],"a":1,"e":"Answer- B. 20% Oxygen consumption increases approximately 20% during pregnancy, and it is approximately 10% higher in multifetal gestation. During labour, oxygen consumption increases 40 - 60%.","pyqMatches":[{"year":"2015","no":1510,"q":"Oxygen consumption increases in pregnancy by","o":["10%","20%","30%","40%"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3963, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 60, '{"id":3963,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":60,"q":"Stroke volume increases in pregnancy by","o":["20%","25%","40%","45%"],"a":1,"e":"Answer- B. 25% Hemodynamic changes during pregnancy Non - pregnant Pregnancy near term Change Cardiac output (lit/m1) 4.5 6.26 +40% Stroke volume (ml) 65 75 +27% Heart rate (per minute) 70 85 + 17% Blood pressure Unaffected or mid pregnancy drop of diastolic pressure by 5 - 10 mmHg Venous pressure 8 - 10 cm (femoral) 20 cm +100% Colloid oncotic pressure (mmHg) 20 18 - 14% Systemic vascular resistance - 21% Pulmonary vascular rests - 34%","pyqMatches":[{"year":"2015","no":1509,"q":"Stroke volume increases in pregnancy by","o":["20%","25%","40%","45%"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3964, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 61, '{"id":3964,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":61,"q":"Cardiac output in pregnancy increases from which week of gestation","o":["5 weeks","15 weeks","25 weeks","35 weeks"],"a":0,"e":"Answer- A. 5 weeks Cardiac output starts to increase from the 5th week of gestation, reaches its peak 40 - 50% at 30 - 34 weeks.","pyqMatches":[{"year":"2015","no":1508,"q":"Cardiac output in pregnancy increases from which week of gestation","o":["5 weeks","15 weeks","25 weeks","35 weeks"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3965, 'OBG', 'Gynecologic Oncology', 'Easy', 'Gynecology', 62, '{"id":3965,"subject":"OBG","chapter":"Gynecologic Oncology","difficulty":"Easy","source":"Gynecology","sourceNo":62,"q":"What is the stage of carcinoma cervix involving body of uterus -","o":["Stage I","Stage II","Stage III","Stage IV"],"a":0,"e":"Answer- A. Stage I Cervical Cancer - FIGO Staging Stage 0 Carcinoma in situ Stage I Intraepithelial carcinoma confined to the cervix Stage IA Diagnosed only by microscopy Stage IA1 Microinvasiva carcinoma with stromal invasion < 3 mm in depth & < 7 mm in wide. Stage IA2 Microinvasiva carcinoma not exceeding 5 mm in depth /7 mm in width. Stage IB Clinically visible or microscopic lesion > IA2. Stage IB1 Clinical lesion not exceeding 4cm in diameter. Stage IB2 Clinical lesion more then 4 cm in diameter. Stage II Extension beyond the cervix but not to the pelvic wall. Stage Involvement of vagina but not the lower third IIA Involvement of vagina but not the lower third. Stage IIA1 Clinically visible lesion more then 4 cm. Stage IIA2 Clinically visible lesion more then 4 cm. Stage IIB Parametrial involvement not reaching the pelcvic side wall.","pyqMatches":[{"year":"2015","no":1550,"q":"What is the stage of carcinoma cervix involving body of uterus","o":["Stage I","Stage II","Stage III","Stage IV"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3966, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 63, '{"id":3966,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":63,"q":"Therapeutic use of folic acid is","o":["Previous pregnancy with child having neural tube defect","Megaloblastic anaemia","Hemoglobinopathies","All of the above"],"a":1,"e":"Answer- B. Megaloblastic anaemia Folic acid is given in all the given conditions. But answer hear is option b. This questions is tricky :- Examiner is asking about therapeutic uses of folic acid (not preventive) In megaloblastic anemia, folic is given for treatment —> therapeutic uses In pregnancy it is given for prevention of neural tube defect —> prophylactic use (preventive use)","pyqMatches":[{"year":"2015","no":1506,"q":"Therapeutic use of folic acid is","o":["Previous pregnancy with child having neural tube defect","Megaloblastic anaemia","Hemoglobinopathies","All of the above"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3967, 'OBG', 'Gynecologic Oncology', 'Easy', 'Gynecology', 64, '{"id":3967,"subject":"OBG","chapter":"Gynecologic Oncology","difficulty":"Easy","source":"Gynecology","sourceNo":64,"q":"Most common cause of death in cervical cancer is -","o":["Renal failure","Infection","Haemorrhage","Metastasis to vital organs"],"a":0,"e":"Answer- A. Renal failure Renal failure is the most common cause of death in cervical cancer. Renal failure in cervical cancer occurs due to involvement of ureters in Stage 1IIB. It can also occur due to direct involvement of kidney as in stage IV B.","pyqMatches":[{"year":"2015","no":1551,"q":"Most common cause of death in cervical cancer is","o":["Renal failure","Infection","Haemorrhage","Metastasis to vital organs"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3968, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Gynecology', 65, '{"id":3968,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Gynecology","sourceNo":65,"q":"During pregnancy increased size of pituitary is caused by increased size of cells which secrete ?","o":["Growth hormone","Prolactin","ACTH","TSH"],"a":1,"e":"Answer- B. Prolactin Prolactin levels rise gradually throughout pregnancy, preparing the breast for lactation. This lactotroph hyperplasia has important implications for the patient with a prolactinoma who desires pregnancy.","pyqMatches":[{"year":"2015","no":1505,"q":"During pregnancy increased size of pituitary is caused by increased size of cells which secrete ?","o":["Growth hormone","Prolactin","ACTH","TSH"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3969, 'OBG', 'Miscellaneous', 'Moderate', 'Gynecology', 66, '{"id":3969,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Gynecology","sourceNo":66,"q":"Treatment options for CIN III include all of the following except -","o":["LLETZ","Conization","Hysterectomy","Wertheim''s hysterectomy"],"a":3,"e":"Answer- D. Wertheim''s hysterectomy Treatment options of (IN III","pyqMatches":[{"year":"2015","no":1552,"q":"Treatment options for CIN III include all of the following except","o":["LLETZ","Conization","Hysterectomy","Wertheim''s hysterectomy"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3970, 'OBG', 'Miscellaneous', 'Moderate', 'Gynecology', 67, '{"id":3970,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Gynecology","sourceNo":67,"q":"What size of the hegar''s dilator if passed through the internal os can be labeled as cervical incompetence?","o":["4","6","8","10"],"a":2,"e":"Answer- C. 8 Passage without resistance and pain of No. 8 Hegar''s dilator is a screening test for cervical incompetence.","pyqMatches":[{"year":"2015","no":1554,"q":"What size of the hegar''s dilator if passed through the internal os can be labeled as cervical incompetence?","o":["4","6","8","10"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3971, 'OBG', 'Labour & Delivery', 'Easy', 'Gynecology', 68, '{"id":3971,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Gynecology","sourceNo":68,"q":"Propulsive stage in labour in multipara","o":["10 minutes","20 minutes","40 minutes","1 hour"],"a":1,"e":"Answer- B. 20 minutes Second stage of labour has two phases :","pyqMatches":[{"year":"2015","no":1504,"q":"Propulsive stage in labour in multipara","o":["10 minutes","20 minutes","40 minutes","1 hour"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3972, 'OBG', 'Labour & Delivery', 'Easy', 'Gynecology', 69, '{"id":3972,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Gynecology","sourceNo":69,"q":"Funneling in cervicogram is seen in -","o":["In labour","Cervical incompetence","Cervical ectopic","During TVS"],"a":1,"e":"Answer- B. Cervical incompetence Cervicogram is done for diagnosis of cervical incompetence. In other conditions, cervicogram is not done.","pyqMatches":[{"year":"2015","no":1555,"q":"Funneling in cervicogram is seen in","o":["In labour","Cervical incompetence","Cervical ectopic","During TVS"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3973, 'OBG', 'Labour & Delivery', 'Easy', 'Gynecology', 70, '{"id":3973,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Gynecology","sourceNo":70,"q":"In cervical incompetence diameter of internal os of cervix is -","o":["1 cm","1.5 cm","2 cm","2.5 cm"],"a":0,"e":"Answer- A. 1 cm Cervical sonography : Funelling of the cervix with changes in the form of Y, V, U. Cervical length < 2.5 cm. Funnelling of the internal os > 1 cm Speculum examination : Detection of dilatation of internal os with herniation of the membranes. Cervical index = (Funnel length + 1) / (endocervical length). The \"+1\" allows an index to be calculated when funelling is absent. Predictors of preterm birth : Cervical index > 0.52. Cervical length < 18 mm Funnel length > 9 mm. Funnel width > 6 mm.","pyqMatches":[{"year":"2015","no":1556,"q":"In cervical incompetence diameter of internal os of cervix is","o":["1 cm","1.5 cm","2 cm","2.5 cm"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3974, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 71, '{"id":3974,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":71,"q":"Occipitoanterior position","o":["Anterior fontanalle is posterior","Sagittal suture is along the Transverse plane of the maternal pelvis","Coronal suture is along the antero - posterior plane of the maternal pelvis","All of the above"],"a":0,"e":"Answer- A. Anterior fontanalle is posterior In direct occipito anterior position, the sagittal suture of the fetus will be along the antero - posterior plane of the maternal pelvis and the coronal suture along the transverse diameter.","pyqMatches":[{"year":"2015","no":1500,"q":"Occipitoanterior position","o":["Anterior fontanalle is posterior","Sagittal suture is along the Transverse plane of the maternal pelvis","Coronal suture is along the antero - posterior plane of the maternal pelvis","All of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3975, 'OBG', 'Labour & Delivery', 'Moderate', 'Gynecology', 72, '{"id":3975,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Moderate","source":"Gynecology","sourceNo":72,"q":"Method not used for shoulder dystocia","o":["McRobert''s maneuver","Hegar''s maneuver","Zanavelli maneuver","Wood''s maneuver"],"a":1,"e":"Answer- B. Hegar''s maneuver McRobert''s, Zanavelli and Wood''s maneuvers'' are maneuvers in the management of shoulder dystocia.","pyqMatches":[{"year":"2015","no":1499,"q":"Method not used for shoulder dystocia","o":["McRobert''s maneuver","Hegar''s maneuver","Zanavelli maneuver","Wood''s maneuver"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3976, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 73, '{"id":3976,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":73,"q":"Vasa previa is associated with -","o":["Marginal placenta","Velamentous placenta","Battledore","Placenta previa"],"a":1,"e":"Answer- B. Velamentous placenta If a leash of blood vessels happen to traverse through the membranes overlying the internal is, in front of the presenting part, the condition is called as vasa praevia. It is associated with velamentous placenta. The unsupported umbilical vessels in velamentous placenta, lie below the presenting part and run across the cervical os. Rupture of membranes involving the overlying vessels leads to vaginal bleeding. As it is entirely fetal blood, this may result in fetal exsanguination and even death. [Ref Dutta''s Obstetrics 8th/e p. 301]","pyqMatches":[{"year":"2015","no":1558,"q":"Vasa previa is associated with","o":["Marginal placenta","Velamentous placenta","Battledore","Placenta previa"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3977, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Gynecology', 74, '{"id":3977,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Gynecology","sourceNo":74,"q":"Which is not a risk factor for gestational hypertension","o":["Obesity","Smoking","Primigravida","Factor V Leiden mutation"],"a":1,"e":"Answer- B. Smoking Primigravida : Young or elderly (first time exposure to villi) Family history (hypertension, pre - eclampsia) Placental ischemia Obesity Thrombophilia (antiphospholipid syndrome), protein C and S deficiency, factor V Leiden mutation) Molar pregnancy (early onset pre - eclampsia)","pyqMatches":[{"year":"2015","no":1498,"q":"Which is not a risk factor for gestational hypertension","o":["Obesity","Smoking","Primigravida","Factor V Leiden mutation"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3978, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 75, '{"id":3978,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":75,"q":"Most common breech position is","o":["Complete breech","Frank breech","Footling breech","Knee presentation"],"a":1,"e":"Answer- B. Frank breech Frank breech (Breech with extended legs) is the most common breech presentation. Breech with extended legs (Frank breech) : Thighs are flexed at hip and legs are extended at knee. It is commonly seen in primigravidae (70%). It is the most common type of breech.","pyqMatches":[{"year":"2015","no":1497,"q":"Most common breech position is","o":["Complete breech","Frank breech","Footling breech","Knee presentation"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3979, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Gynecology', 76, '{"id":3979,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Gynecology","sourceNo":76,"q":"When fetus is at station +2 & fetal skull reaches pelvic floor, which of the following is true","o":["Forceps can be applied","Best time to give episiotomy","Called as crowning","May lead to deep transverse arrest"],"a":0,"e":"Answer- A. Forceps can be applied When the fetal skull has reached the level of pelvic floor and station of head is at + 2 or more, outlet forceps can be applied. However, crowning is defined as stretching of the vulva'' outlet by the maximum diameter of the fetal head (biparietal diameter) without any recession. Thus the station is + 5. Best time to give episiotomy is at the time of crowning of head. [Ref Dutta''s Obstetrics 81h/e p. 651]","pyqMatches":[{"year":"2015","no":1496,"q":"When fetus is at station +2 & fetal skull reaches pelvic floor, which of the following is true","o":["Forceps can be applied","Best time to give episiotomy","Called as crowning","May lead to deep transverse arrest"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3980, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 77, '{"id":3980,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":77,"q":"Contracted pelvis is defined as shortening of one or more planes by -","o":["0.5 cm","1 cm","1.25 cm","1.5 cm"],"a":0,"e":"Answer- A. 0.5 cm Anatomically, contracted pelvis is defined as shortening of one or more planes by 0.5 cm.","pyqMatches":[{"year":"2015","no":1557,"q":"Contracted pelvis is defined as shortening of one or more planes by","o":["0.5 cm","1 cm","1.25 cm","1.5 cm"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3981, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Gynecology', 78, '{"id":3981,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Gynecology","sourceNo":78,"q":"Common misdiagnosis of partial mole is","o":["Threatened abortion","Choriocarcinoma","Complete mole","Ectopic pregnancy"],"a":0,"e":"Answer- A. Threatened abortion The clinical picture of partial mole is confused with threatened abortion or missed abortion due to pain and bleeding alongwith a fetus (usually dead) in utero.","pyqMatches":[{"year":"2015","no":1495,"q":"Common misdiagnosis of partial mole is","o":["Threatened abortion","Choriocarcinoma","Complete mole","Ectopic pregnancy"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3982, 'OBG', 'Labour & Delivery', 'Easy', 'Gynecology', 79, '{"id":3982,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Gynecology","sourceNo":79,"q":"Prolonged second stage of labour may occur due to","o":["Uterine inertia","Epidural analgesia","Cephalopelvic disproportion","All of the above"],"a":3,"e":"Answer- D. All of the above Prolongation of second stage of labour can occur due to any of the following reasons : 1) Fault in the power Uterine inertia Inability to bear down Epidural analgesia Constriction ring 2) Fault in the passage Cephalopelvic disproportion, android pelvis, contracted pelvis Undue resistance of the pelvic floor or perineum due to spasm or old scarring Soft tissue pelvic tumor. 3) Fault in the passenger Malposition (occipito - posterior) Malpresentation Big baby Congenital malformation of the baby","pyqMatches":[{"year":"2015","no":1492,"q":"Prolonged second stage of labour may occur due to","o":["Uterine inertia","Epidural analgesia","Cephalopelvic disproportion","All of the above"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3983, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 80, '{"id":3983,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":80,"q":"Most common type of conjoint twin is -","o":["Thoracopagus","Omphalopagus","Craniopagus","Rachipagus"],"a":0,"e":"Answer- A. Thoracopagus Four types of fusion may occur : Thorapagus - Most common Pyopagus (posterior fusion) Craniopagus (cephalic) Ischiopagus (caudal)","pyqMatches":[{"year":"2015","no":1560,"q":"Most common type of conjoint twin is","o":["Thoracopagus","Omphalopagus","Craniopagus","Rachipagus"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3984, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 81, '{"id":3984,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":81,"q":"Crowning is","o":["Biparietal diameter at the inlet of pelvis","Biparietal diameter at the ischial spine","Biparietal diameter at the vulval outlet","Biparietal diameter just outside the vulval outlet Answer-"],"a":2,"e":"Answer- C. Biparietal diameter at the vulval outlet Crowning : After internal rotation of the head, further descent occurs until the subocciput lies underneath the pubic arch. At this stage, the maximum diameter of the head (biparietal diameter) stretches the vulval outlet without any recession of the head even after the contraction is over - called \"crowning of the head\".","pyqMatches":[{"year":"2015","no":1491,"q":"Crowning is","o":["Biparietal diameter at the inlet of pelvis","Biparietal diameter at the ischial spine","Biparietal diameter at the vulval outlet","Biparietal diameter just outside the vulval outlet Answer"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3985, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Gynecology', 82, '{"id":3985,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Gynecology","sourceNo":82,"q":"Uterine height is greater than gestational age of the patient in a case of all except -","o":["Fibroid uterus","IUGR","Wrong dates","Polyhydramnios"],"a":1,"e":"Answer- B. IUGR Uterine height greater than gestational age in case of : Wrong dates Polyhydramnios Pregnancy with fibroid uterus Multiple pregnancy","pyqMatches":[{"year":"2015","no":1561,"q":"Uterine height is greater than gestational age of the patient in a case of all except","o":["Fibroid uterus","IUGR","Wrong dates","Polyhydramnios"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3986, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 83, '{"id":3986,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":83,"q":"True about placental site trophoblastic disease is","o":["Highly Malignant behavior","Hysterectomy followed by chemoradiation is the treatment of choice","Secretes human placental lactogen","Contains syncytiotrophoblasts mainly"],"a":2,"e":"Answer- C. Secretes human placental lactogen Placental Site Trophoblastic Tumour Arises from the placental bed trophoblasts and invades the myometrium. Follows a full - term normal delivery. Tumor contains mainly cytotrophoblasts with few or no syncytiotrophoblasts. Most of these tumors run a benign course, malignancy is rare. [Ref Shaw''s Gynae le/e p. 313; Dutta''s Obs 8thie p. 231]","pyqMatches":[{"year":"2015","no":1490,"q":"True about placental site trophoblastic disease is","o":["Highly Malignant behavior","Hysterectomy followed by chemoradiation is the treatment of choice","Secretes human placental lactogen","Contains syncytiotrophoblasts mainly"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3987, 'OBG', 'Labour & Delivery', 'Easy', 'Gynecology', 84, '{"id":3987,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Gynecology","sourceNo":84,"q":"Quickening in multiparae is felt at what weeks of gestation?","o":["14 weeks","16 weeks","18 weeks","20 weeks"],"a":1,"e":"Answer- B. 16 weeks Quickening is feeling of life. It denotes perception of active fetal movements by the women. It is usually felt about the 18th week, about 2 weeks earlier in multiparae. Its appearance is an useful guide to calculate the expected date of delivery with reasonable accuracy.","pyqMatches":[{"year":"2015","no":1489,"q":"Quickening in multiparae is felt at what weeks of gestation?","o":["14 weeks","16 weeks","18 weeks","20 weeks"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3988, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 85, '{"id":3988,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":85,"q":"Pregnancy is contraindicated in which cardiac disease -","o":["Mitral stenosis","Primary pulmonary hypertension","VSD","Mitral regurgitation"],"a":1,"e":"Answer- B. Primary pulmonary hypertension Place of therapeutic termination in case of following heart diseases. Considering high maternal deaths, absolute indications are : Primary pulmonary hypertension Eisenmenger''s syndrome Pulmonary veno - occlusive disease.","pyqMatches":[{"year":"2015","no":1562,"q":"Pregnancy is contraindicated in which cardiac disease","o":["Mitral stenosis","Primary pulmonary hypertension","VSD","Mitral regurgitation"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3989, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 86, '{"id":3989,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":86,"q":"Malodorous vaginal discharge is due to","o":["Bacterial vaginosis","Chlamydia trachomatis","Trichomonas vaginalis","Neisseria gonorrhea"],"a":0,"e":"Answer- A. Bacterial vaginosis Bacterial vaginosis is an alteration of the normal vaginal flora with consequent overgrowth of pathogenic bacteria. There is fall in the absolute number of hydrogen peroxide - producing lactobacilli, leading to a rise in pH and increase in the absolute number of G. vaginalis, anaerobic gram - negative rods, Mobiluncus spp. and Mycoplasma hominis.","pyqMatches":[{"year":"2015","no":1488,"q":"Malodorous vaginal discharge is due to","o":["Bacterial vaginosis","Chlamydia trachomatis","Trichomonas vaginalis","Neisseria gonorrhea"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3990, 'OBG', 'Labour & Delivery', 'Moderate', 'Gynecology', 87, '{"id":3990,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Moderate","source":"Gynecology","sourceNo":87,"q":"Following delivery, tear involves perineum, external anal spincter with intact mucosa, grade of tear is -","o":["First degree","Second degree","Third degree","Fourth degree"],"a":2,"e":"Answer- C. Third degree Third degree : Injury to perineum, involving the anal sphincter complex (both the external and internal). 3a : if half thickness external anal sphincter involved. 3b : if full thickness external anal sphincter involved. 3c : if internal anal sphincter involoved.","pyqMatches":[{"year":"2015","no":1563,"q":"Following delivery, tear involves perineum, external anal spincter with intact mucosa, grade of tear is","o":["First degree","Second degree","Third degree","Fourth degree"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3991, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 88, '{"id":3991,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":88,"q":"Amsel criteria is for","o":["Bacterial vaginosis","Antiphospholipid antibody syndrome","Ovarian ectopic pregnancy","HELLP Syndrome"],"a":0,"e":"Answer- A. Bacterial vaginosis Amsel criteria : Three out of four of the following should be present A white / gray homogenous discharge A vaginal discharge pH of > 4.5 A positive amine test (drop of 10% potassium hydroxide added to drop of discharge on a slide produces fishy odour), also known as Whiff test. Microscopy demonstrates clue cells.","pyqMatches":[{"year":"2015","no":1578,"q":"Amsel criteria is for","o":["Bacterial vaginosis","Antiphospholipid antibody syndrome","Ovarian ectopic pregnancy","HELLP Syndrome"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3992, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 89, '{"id":3992,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":89,"q":"Plane of cleavage during placental separation runs through","o":["Between compact and spongy layer of decidua basalis","Between decidua basalis and chorion frondosum","Through deep spongy layer of decidua basalis","Between layers of chorion frondosum"],"a":2,"e":"Answer- C. Through deep spongy layer of decidua basalis Marked retraction reduces effectively the surface area at the placental site to about its half. But as the placenta is inelastic, it cannot keep pace with such an extent of diminution resulting in its buckling. A shearing force is instituted between the placenta and the placental site which brings about its ultimate separation.","pyqMatches":[{"year":"2015","no":1577,"q":"Plane of cleavage during placental separation runs through","o":["Between compact and spongy layer of decidua basalis","Between decidua basalis and chorion frondosum","Through deep spongy layer of decidua basalis","Between layers of chorion frondosum"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3993, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Gynecology', 90, '{"id":3993,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Gynecology","sourceNo":90,"q":"Not a cause of oligohydramnios -","o":["IUGR","Renal agenesis","Amnion nodosum","Chorioangioma"],"a":3,"e":"Answer- D. Chorioangioma Fetal, Chromosomal or structural anamolies Renal agenesis Obstructive uropathy Spontaneous rupture of membrane Intrauterine infection Drugs: PG inhibitors, ACE inhibitors Postmaturity IUGR Amnion nodosum Maternal Hypertensive disorders Uteorplacental insufficiency Dehydration Idiopathic","pyqMatches":[{"year":"2015","no":1564,"q":"Not a cause of oligohydramnios","o":["IUGR","Renal agenesis","Amnion nodosum","Chorioangioma"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3994, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 91, '{"id":3994,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":91,"q":"Which of the following is true about ovarian ectopic pregnancy?","o":["Studdiford criteria is used for diagnosis","There should be no rent on the ovary or tube","Absence of evidence of pregnancy at any other site than ovarian","Conservative surgery can be done if diagnosed early"],"a":3,"e":"Answer- D. Conservative surgery can be done if diagnosed early Ovarian ectopic is a rare entity that is difficult to diagnose clinically. It usually does not proceed past the first four weeks of pregnancy. Spiegelberg''s criteria is used for diagnosis of ovarian pregnancy. It includes :","pyqMatches":[{"year":"2015","no":1576,"q":"Which of the following is true about ovarian ectopic pregnancy?","o":["Studdiford criteria is used for diagnosis","There should be no rent on the ovary or tube","Absence of evidence of pregnancy at any other site than ovarian","Conservative surgery can be done if diagnosed early"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3995, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 92, '{"id":3995,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":92,"q":"False about chorionic vinous sampling -","o":["Is used for prental genetic diagnosis","Is performed only in second trimester of pregnancy","Villi collected from chorion frondosum","Can cause limb deformities"],"a":1,"e":"Answer- B. Is performed only in second trimester of pregnancy Is used for prenatal genetic diagnosis. Performed transcervically through 10-12 weeks (first trimester) and transabdominally from 10 weeks to term. (Advantage over amniocentesis which is performed in second trimester of pregnancy) Villi are collected from chorion frondosum. Can cause oromandibular limb deformities or limb reduction defects if performed before 10 weeks of gestation.","pyqMatches":[{"year":"2015","no":1565,"q":"False about chorionic vinous sampling","o":["Is used for prental genetic diagnosis","Is performed only in second trimester of pregnancy","Villi collected from chorion frondosum","Can cause limb deformities"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3996, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 93, '{"id":3996,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":93,"q":"Bacteria responsible for ectopic pregnancy is","o":["Staphylococcus","Chlamydia","Peptostreptococcus","Trichomonas vaginalis"],"a":1,"e":"Answer- B. Chlamydia Salpingitis and PID (Pelvic Inflammatory Disease) is the most important risk factor for ectopic pregnancy. Chlamydia trachomatis infection is the most common risk factor for PID and salpingitis. [Ref Dutta''s Obstetrics 8th/e p.. 207]","pyqMatches":[{"year":"2015","no":1573,"q":"Bacteria responsible for ectopic pregnancy is","o":["Staphylococcus","Chlamydia","Peptostreptococcus","Trichomonas vaginalis"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3997, 'OBG', 'Miscellaneous', 'Hard', 'Gynecology', 94, '{"id":3997,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Hard","source":"Gynecology","sourceNo":94,"q":"A 28 year old primigravida with 32 weeks of gestation comes with complain of thin, frothy, profuse discharge through the vagina since yesterday. She was advised USG which showed Single live intrauterine gestational sac with FL and AC corresponding to the weeks of gestation and AFI as adequate.What is the diagnosis?","o":["PPROM","Trichomoniasis","Normal finding","Candidiasis"],"a":1,"e":"Answer- B. Trichomoniasis Patients infected with Trichomonas vaginalis complain of a typical discharge, which is thin, profuse, frothy, irritating, creamy or slight green in colour. Slight green colour of the discharge is often not complained by the patient but spotted by the physician.","pyqMatches":[{"year":"2015","no":1566,"q":"A 28 year old primigravida with 32 weeks of gestation comes with complain of thin, frothy, profuse discharge through the vagina since yesterday. She was advised USG which showed Single live intrauterine gestational sac with FL and AC corresponding to the weeks of gestation and AFI as adequate.What is the diagnosis?","o":["PPROM","Trichomoniasis","Normal finding","Candidiasis"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3998, 'OBG', 'Benign Gynecology', 'Easy', 'Gynecology', 95, '{"id":3998,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Easy","source":"Gynecology","sourceNo":95,"q":"Le Fort repair is done for","o":["Uterovaginal descent","Vault prolapse","VVF","RVF"],"a":0,"e":"Answer- A. Uterovaginal descent Le Forte''s repair Very elderly menopausal women Advanced prolapse Unfit for any major surgical procedure [Ref Shaw''s Gynaecology 16th/e p. 360]","pyqMatches":[{"year":"2015","no":1572,"q":"Le Fort repair is done for","o":["Uterovaginal descent","Vault prolapse","VVF","RVF"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (3999, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 96, '{"id":3999,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":96,"q":"Leydig cells of fetus testis secretes","o":["hCG","LH","Testosterone","Mullerian inhibiting substance"],"a":2,"e":"Answer- C. Testosterone Leydig cells in fetal testis are the cellular site of testosterone synthesis. Fetal testis also secretes mullerian inhibiting substance produced by sertoli cells which acts locally as a paracrine factor to cause mullerian duct regression. Mullerian duct regression completes by 9 to 10 weeks'' gestation, which is much before testosterone secretion has commenced.","pyqMatches":[{"year":"2015","no":1571,"q":"Leydig cells of fetus testis secretes","o":["hCG","LH","Testosterone","Mullerian inhibiting substance"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4000, 'OBG', 'Miscellaneous', 'Moderate', 'Gynecology', 97, '{"id":4000,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Gynecology","sourceNo":97,"q":"Risk factors for molar gestation are all of the following except -","o":["Oriental countries","Disturbed maternal immune mechanism","Higher ratio of maternal/paternal chromosomes","Faulty nutrition"],"a":2,"e":"Answer- C. Higher ratio of maternal/paternal chromosomes Risk factors for H. mole :","pyqMatches":[{"year":"2015","no":1567,"q":"Risk factors for molar gestation are all of the following except","o":["Oriental countries","Disturbed maternal immune mechanism","Higher ratio of maternal/paternal chromosomes","Faulty nutrition"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4001, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 98, '{"id":4001,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":98,"q":"Embryo gets implanted at what stage of development?","o":["Two cell stage","Four cell stage","Morula","Blastocyst"],"a":3,"e":"Answer- D. Blastocyst After the zygote formation, typical mitotic division of the nucleus occurs producing two blastomeres. Two cell stage is reached approximately 30 hours after fertilization. The blastomeres continue to divide by binary division through 4, 8, 16 cell stage until a cluster of cells is formed and is called morula, resembling a mulberry. Morula after spending about 3 days in the uterine tube enters the uterine cavity through the narrow uterine ostium (1mm) on the 4th day in the 16 - 64 cell stage. Implantation occurs on the 6th day which corresponds to the 20th day of regular menstrual cycle. Implantation occurs through 4 stages : apposition, adhesion, penetration and invasion.","pyqMatches":[{"year":"2015","no":1570,"q":"Embryo gets implanted at what stage of development?","o":["Two cell stage","Four cell stage","Morula","Blastocyst"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4002, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 99, '{"id":4002,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":99,"q":"Poor prognostic factor for hydatidiform mole is -","o":["Prior molar pregnancy","Metastasis to lung","No prior chemotherapy","WHO score > 8"],"a":3,"e":"Answer- D. WHO score > 8 High Risk (Poor Prognosis) : Long duration of disease (> 4 months) Initial serum hCG level > 40,000 mIU/ml Brain or liver metastasis Failure of prior chemotherapy Following term pregnancy WHO score > 8","pyqMatches":[{"year":"2015","no":1568,"q":"Poor prognostic factor for hydatidiform mole is","o":["Prior molar pregnancy","Metastasis to lung","No prior chemotherapy","WHO score > 8"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4003, 'OBG', 'Benign Gynecology', 'Easy', 'Gynecology', 100, '{"id":4003,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Easy","source":"Gynecology","sourceNo":100,"q":"Drugs used in endometriosis is","o":["Combined oral contraceptives","Letrozole","Mifepristone","All of the above"],"a":3,"e":"Answer- D. All of the above Combined oral contraceptives - Administered intermittently or continuously, oral contraceptives may alleviate the disease. Oral progestogens - Exert anti - estrogenic effect and their continuous administration causes decidualization and endometrial atrophy. Danazol - inhibits pituitary gonadotropins GnRH analogues - Downregulate and suppress pituitary gonadotropins. Aromatase inhibitors (letrozole) : Anti - estrogenic action Anti - progestin (mifepristone)","pyqMatches":[{"year":"2015","no":1569,"q":"Drugs used in endometriosis is","o":["Combined oral contraceptives","Letrozole","Mifepristone","All of the above"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4004, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 101, '{"id":4004,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":101,"q":"Risk of scar rupture in lower segment of previous scar present is ?","o":["05 - 1.5 %","15 - 25 %","2.5 - 3.5 %","3.5 - 4.5 %"],"a":0,"e":"Ans. A. 05 - 1.5 %","pyqMatches":[{"year":"2014","no":1910,"q":"Risk of scar rupture in lower segment of previous scar present is ?","o":["05 - 1.5 %","15 - 25 %","2.5 - 3.5 %","3.5 - 4.5 %"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4005, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Gynecology', 102, '{"id":4005,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Gynecology","sourceNo":102,"q":"Not true in complete hydatidiform mole ?","o":["Triploid","Absence of fetal parts","Diffuse trophoblastic hyperplasia","Beta HCG > 50,000"],"a":0,"e":"Ans, A. Triploid Triploidy and diploidy are seen in partial mole. Complete mole has 46 XX karyotype.","pyqMatches":[{"year":"2014","no":1909,"q":"Not true in complete hydatidiform mole ?","o":["Triploid","Absence of fetal parts","Diffuse trophoblastic hyperplasia","Beta HCG > 50,000"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4006, 'OBG', 'Miscellaneous', 'Moderate', 'Gynecology', 103, '{"id":4006,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Gynecology","sourceNo":103,"q":"Components of Mala D are all except ?","o":["0.03 mg Ethinyl estradiol","0.15mg desogestrel","0.15 mg levenogestrel","Iron tablets"],"a":1,"e":"Ans, B. 0.15mg desogestrel","pyqMatches":[{"year":"2014","no":1908,"q":"Components of Mala D are all except ?","o":["0.03 mg Ethinyl estradiol","0.15mg desogestrel","0.15 mg levenogestrel","Iron tablets"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4007, 'OBG', 'Infertility & Reproductive Endocrinology', 'Moderate', 'Gynecology', 104, '{"id":4007,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Moderate","source":"Gynecology","sourceNo":104,"q":"Mechanism of action of IUCD is all except ?","o":["Inhibit ovulation","Induce biochemical changes in endometrium","Increase tubal motility","Inflammatory respone in endometrium"],"a":0,"e":"Ans, A. Inhibit ovulation Act predominantly in the uterine cavity and do not inhibit ovulation.","pyqMatches":[{"year":"2014","no":1907,"q":"Mechanism of action of IUCD is all except ?","o":["Inhibit ovulation","Induce biochemical changes in endometrium","Increase tubal motility","Inflammatory respone in endometrium"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4008, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 105, '{"id":4008,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":105,"q":"Most common infection in long term IUCD use -","o":["Actinomyosis","Mucormycosis","Aspergillosis","Candidiasis"],"a":0,"e":"Ans. A. Actinomyosis Actinomycosis is an infection common in patients sing inert IUCDs.","pyqMatches":[{"year":"2014","no":1906,"q":"Most common infection in long term IUCD use","o":["Actinomyosis","Mucormycosis","Aspergillosis","Candidiasis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4009, 'OBG', 'Gynecologic Oncology', 'Moderate', 'Gynecology', 106, '{"id":4009,"subject":"OBG","chapter":"Gynecologic Oncology","difficulty":"Moderate","source":"Gynecology","sourceNo":106,"q":"Absolute contraindication of OC pills are all except?","o":["Suspicious vaginal bleeding","Cervical cancer","Uterine anamoly","Old STD"],"a":3,"e":"Ans. D. Old STD Current STD is an absolute contraindication (not past STDs).","pyqMatches":[{"year":"2014","no":1905,"q":"Absolute contraindication of OC pills are all except?","o":["Suspicious vaginal bleeding","Cervical cancer","Uterine anamoly","Old STD"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4010, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 107, '{"id":4010,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":107,"q":"Copper IUCD as a contraceptive measure can be used maximum till what time after contact ?","o":["2 days","3 days","4 days","5 days"],"a":3,"e":"Ans. D. 5 days IntroductionofCopperlUDwithinamaximumperiodof5dayscan preventconceptionfollowingaccidentalunprotectedexposure.","pyqMatches":[{"year":"2014","no":1904,"q":"Copper IUCD as a contraceptive measure can be used maximum till what time after contact ?","o":["2 days","3 days","4 days","5 days"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4011, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Gynecology', 108, '{"id":4011,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Gynecology","sourceNo":108,"q":"Clomiphene citrate is used for ?","o":["Anovulation","Endometriosis","Puberty menorrhagia","Hormone replacement therapy"],"a":0,"e":"Ans A. Anovulation","pyqMatches":[{"year":"2014","no":1903,"q":"Clomiphene citrate is used for ?","o":["Anovulation","Endometriosis","Puberty menorrhagia","Hormone replacement therapy"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4012, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Gynecology', 109, '{"id":4012,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Gynecology","sourceNo":109,"q":"First line treatment of infertility in PCOS is ?","o":["Clomiphene","FSH","GnRH","Assisted reproductive techniques"],"a":0,"e":"Ans. A. Clomiphene Clomiphene citrate is the first line of treatment of infertility in a PCOS woman.","pyqMatches":[{"year":"2014","no":1902,"q":"First line treatment of infertility in PCOS is ?","o":["Clomiphene","FSH","GnRH","Assisted reproductive techniques"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
