INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4014, 'OBG', 'Benign Gynecology', 'Easy', 'Gynecology', 111, '{"id":4014,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Easy","source":"Gynecology","sourceNo":111,"q":"Investigation of choice in endometriosis ?","o":["Laproscopy","Hysteoscopy","CT scan","MRI"],"a":0,"e":"Ans. A. Laproscopy Laproscopy is considered as gold standard investigation for diagnosis of endometriosis. It is diagnostic as well as therapeutic,","pyqMatches":[{"year":"2014","no":1900,"q":"Investigation of choice in endometriosis ?","o":["Laproscopy","Hysteoscopy","CT scan","MRI"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
