INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4016, 'OBG', 'Gynecologic Oncology', 'Easy', 'Gynecology', 113, '{"id":4016,"subject":"OBG","chapter":"Gynecologic Oncology","difficulty":"Easy","source":"Gynecology","sourceNo":113,"q":"Meigs syndrome is associated with which tumor ?","o":["Fibroma","Cystadenoma","Dysgerminoma","Teratoma"],"a":0,"e":"Ans. A. Fibroma Meigs syndrome combination offibroma with ascites andhydrothorax, usuaily rightsided. Seen in 1- 5% patients.","pyqMatches":[{"year":"2014","no":1898,"q":"Meigs syndrome is associated with which tumor ?","o":["Fibroma","Cystadenoma","Dysgerminoma","Teratoma"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4017, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 114, '{"id":4017,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":114,"q":"Sentinel lymph node biopsy is used to map the lymph node status of which cancers?","o":["Breast","Melanoma","Vulva","All the above"],"a":3,"e":"Ans, D. All the above Lymphatic mapping and sentinel lymph node biopsy Technique use to know the local lymph node status in cancers of breast, vulva and melanoma","pyqMatches":[{"year":"2014","no":1897,"q":"Sentinel lymph node biopsy is used to map the lymph node status of which cancers?","o":["Breast","Melanoma","Vulva","All the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
