INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4019, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 116, '{"id":4019,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":116,"q":"Most common cancer in pregnancy ?","o":["Melanoma","Breast carcinoma","Gastric carcinoma","Thyroid carcinoma"],"a":1,"e":"Ans. B. Breast carcinoma Breast carcinoma is the most common cancer in pregnancy constituting 46% (1:3000 to 10,000) of the cases followed by hematological malignancies constituting 18 - 25%o of the cases,","pyqMatches":[{"year":"2014","no":1895,"q":"Most common cancer in pregnancy ?","o":["Melanoma","Breast carcinoma","Gastric carcinoma","Thyroid carcinoma"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4020, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 117, '{"id":4020,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":117,"q":"Most common cause of vulval carcinoma is ?","o":["HPV infection","EBV infection","Herpes genitalis infection","Syphilis infection"],"a":0,"e":"Ans. A. HPV infection HPV infection is a common risk factor for the development of invasive vulval carcinoma.","pyqMatches":[{"year":"2014","no":1894,"q":"Most common cause of vulval carcinoma is ?","o":["HPV infection","EBV infection","Herpes genitalis infection","Syphilis infection"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4021, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Gynecology', 118, '{"id":4021,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Gynecology","sourceNo":118,"q":"Following the criteria for conservative surgery in patients with ovarian carcinoma except ?","o":["FIGO stage II disease","Young patient with no or few children","Well differentiated serous tumor","No infiltration of capsule, lymphatics or mesoovarium"],"a":0,"e":"Ans. A. FIGO stage II disease Requirements for conservative surgery in patients with ovarianCancer are: FIGO stage IA disease Well differentiated serous, mucinous, endometroid or clear cell tumor Young patient with no or few children No other pelvic pathology precluding pregnancy","pyqMatches":[{"year":"2014","no":1893,"q":"Following the criteria for conservative surgery in patients with ovarian carcinoma except ?","o":["FIGO stage II disease","Young patient with no or few children","Well differentiated serous tumor","No infiltration of capsule, lymphatics or mesoovarium"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4022, 'OBG', 'Gynecologic Oncology', 'Easy', 'Gynecology', 119, '{"id":4022,"subject":"OBG","chapter":"Gynecologic Oncology","difficulty":"Easy","source":"Gynecology","sourceNo":119,"q":"Most common ovarian cyst to undergo torsion is ?","o":["Dysgerminoma","Benign cystic teratoma","Ovarian fibroma","Brenner''s tumor"],"a":1,"e":"Ans, B. Benign cystic teratoma Benign cystic teratoma is the most common ovarian neoplasm to undergo torsion.","pyqMatches":[{"year":"2014","no":1892,"q":"Most common ovarian cyst to undergo torsion is ?","o":["Dysgerminoma","Benign cystic teratoma","Ovarian fibroma","Brenner''s tumor"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
