INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4030, 'OBG', 'Miscellaneous', 'Moderate', 'Gynecology', 127, '{"id":4030,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Gynecology","sourceNo":127,"q":"What is the next step in investigating a 45 yrs old female with post coital bleeding and visible cervical mass on speculum examination ?","o":["Dilatation and curettage","Conisation","Colposcopy","Hysteroscopy"],"a":2,"e":"Ans. C. Colposcopy","pyqMatches":[{"year":"2014","no":1884,"q":"What is the next step in investigating a 45 yrs old female with post coital bleeding and visible cervical mass on speculum examination ?","o":["Dilatation and curettage","Conisation","Colposcopy","Hysteroscopy"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4031, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 128, '{"id":4031,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":128,"q":"Most common mode of spread for genital tuberculosis is?","o":["Hematogenous","Lymphatic","Direct","Ascending"],"a":0,"e":"Ans. A. Hematogenous From any of the primary sites, the pelvic organs involved by hematogenous spread in about 90% of the cases.","pyqMatches":[{"year":"2014","no":1883,"q":"Most common mode of spread for genital tuberculosis is?","o":["Hematogenous","Lymphatic","Direct","Ascending"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4032, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 129, '{"id":4032,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":129,"q":"Estimation of fetal hemoglobin is done by ?","o":["Gerhard test","Kleihauser-Betke Acid Elution Test","Grinders test","Simpsons test"],"a":1,"e":"Ans. B. Kleihauser-Betke Acid Elution Test Modified Keihauser-Betke Acid Elution test: it k used to note the number fetal red cells per 0 low power fields. If there are 80 fetal erythrocyte in 50 low power fields in maternal peripheralblood films, it presents the transplacental hemorrhage of 4 ml of fetal blood.","pyqMatches":[{"year":"2014","no":1882,"q":"Estimation of fetal hemoglobin is done by ?","o":["Gerhard test","Kleihauser-Betke Acid Elution Test","Grinders test","Simpsons test"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4033, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 130, '{"id":4033,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":130,"q":"Most common breech presentation in primigravida is ?","o":["Flexed breech","Frank breech","Footling presentation","Incomplete"],"a":1,"e":"Ans, B. Frank breech Breech with extended legs/Frank breech","pyqMatches":[{"year":"2014","no":1881,"q":"Most common breech presentation in primigravida is ?","o":["Flexed breech","Frank breech","Footling presentation","Incomplete"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4034, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Gynecology', 131, '{"id":4034,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Gynecology","sourceNo":131,"q":"Transverse lie is caused by all except ?","o":["Multiparity","Prematurity","Anencephaly","Placenta previa"],"a":2,"e":"Ans, C. Anencephaly Etiology transverse lie: Multiparity Twins Contracted pelvis Pelvic tumors Intrauterine death Prematurity Hydramnios Placentaprevia Congenital malformation of uterus - arcuate, subseptate","pyqMatches":[{"year":"2014","no":1880,"q":"Transverse lie is caused by all except ?","o":["Multiparity","Prematurity","Anencephaly","Placenta previa"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4035, 'OBG', 'Miscellaneous', 'Hard', 'Gynecology', 132, '{"id":4035,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Hard","source":"Gynecology","sourceNo":132,"q":"20 year old female with primary amenorrhoea with normal presentation of everything except no axillary or pubic hair. What is the diagnosis?","o":["Testicular feminization syndrome","Kallman syndrome","Turners syndrome","Klienfelters syndrome"],"a":0,"e":"Ans, A. Testicular feminization syndrome Phenotypically normal females with absence of axillary and pubic hair with primary amenorrhoea have two differential diagnosis: Testicular feminizing syndrome and Mullerian agenesis.","pyqMatches":[{"year":"2014","no":1879,"q":"20 year old female with primary amenorrhoea with normal presentation of everything except no axillary or pubic hair. What is the diagnosis?","o":["Testicular feminization syndrome","Kallman syndrome","Turners syndrome","Klienfelters syndrome"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4036, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 133, '{"id":4036,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":133,"q":"In PID due to neiserriea gonorrhea, tubal damage is?","o":["Peritubal","Endotubal","Extratubal","Juxtatubal"],"a":1,"e":"Ans. B. Endotubal Gonococcal infection involves the mucosa and mainly remains an endoluminal pathology while the other bacterial PID tend to involve deeper tissues and can also involve extratubal tissues. So the most probable answer is endotubal.","pyqMatches":[{"year":"2014","no":1878,"q":"In PID due to neiserriea gonorrhea, tubal damage is?","o":["Peritubal","Endotubal","Extratubal","Juxtatubal"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4037, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Gynecology', 134, '{"id":4037,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Gynecology","sourceNo":134,"q":"Condition where there is ingrowth of the endometrium, both glandular and stromal component in myometrium is ?","o":["Adenomyosis","Courvelaire uterus","Placenta accreta","Uterine fibroid"],"a":0,"e":"Ans, A. Adenomyosis Adenomyosis is a condition where there is ingrowth of the endometrium, both the glandular and stromal components, directly into the myometrium.","pyqMatches":[{"year":"2014","no":1877,"q":"Condition where there is ingrowth of the endometrium, both glandular and stromal component in myometrium is ?","o":["Adenomyosis","Courvelaire uterus","Placenta accreta","Uterine fibroid"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4038, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 135, '{"id":4038,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":135,"q":"Couvelaire uterus is seen in ?","o":["Placenta previa","Abruptio placentae","Plencenta accrete","Velamentous placenta"],"a":1,"e":"Ans. B. Abruptio placentae Couvelaire uterus Also called uteroplacental apoplexy. It is seen in association with severe forms of \"concealed abruptio placen \"","pyqMatches":[{"year":"2014","no":1876,"q":"Couvelaire uterus is seen in ?","o":["Placenta previa","Abruptio placentae","Plencenta accrete","Velamentous placenta"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4039, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 136, '{"id":4039,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":136,"q":"Swiss cheese pattern is seen in ?","o":["Metropathica hemorrhagica","Serous cystadenoma","Mucinous cystadenoma","Dermoid"],"a":0,"e":"Ans. A. Metropathica hemorrhagica Microscopicappearance of endometrium shows: Glandular hyperplasiawith cystic dilation of few glands of variable sizes givingit a swiss cheese appearance.","pyqMatches":[{"year":"2014","no":1875,"q":"Swiss cheese pattern is seen in ?","o":["Metropathica hemorrhagica","Serous cystadenoma","Mucinous cystadenoma","Dermoid"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4040, 'OBG', 'Miscellaneous', 'Hard', 'Gynecology', 137, '{"id":4040,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Hard","source":"Gynecology","sourceNo":137,"q":"Upper age limit to diagnose a patient as having primary amenorrhoea is ?","o":["13 years","14 years","15 years","16 years"],"a":3,"e":"Ans. D. 16 years A young girl who has not yet menstruated by her 16 years of age has pimary amenonhoea rather than delayed metarche. Delayed puberty is defined as failure of development of signs of sexual development by the age of 14 years in boy. In girls delayed puberty is defined as failure of breast budding by I 3 years or absence of menarche by I 5 year or lack of secondary sexual characters by l7 years.","pyqMatches":[{"year":"2014","no":1874,"q":"Upper age limit to diagnose a patient as having primary amenorrhoea is ?","o":["13 years","14 years","15 years","16 years"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4041, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Gynecology', 138, '{"id":4041,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Gynecology","sourceNo":138,"q":"Lileys zone 3 at 35 weeks gestation management is?","o":["Follow up","Intrauterine infusion","Preterm termination of pregnancy","Cordocentesis"],"a":2,"e":"Ans, C. Preterm termination of pregnancy A chart that uses the spectrographic measurement of amniotic fluid bilirubin levels plotted against gestational age to estimate the severity of fetal hemolysis resultingfrom Rh isoimmunizntion.","pyqMatches":[{"year":"2014","no":1873,"q":"Lileys zone 3 at 35 weeks gestation management is?","o":["Follow up","Intrauterine infusion","Preterm termination of pregnancy","Cordocentesis"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4042, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 139, '{"id":4042,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":139,"q":"How much time after reduced movement fetal heart stops?","o":["1 hr","2 hrs","6 hrs","12 hrs"],"a":3,"e":"Ans, D, 12 hrs On an averagefetalheart stops after 12 - 48 hours of diseased fetal movements in intrauterinefetal death.","pyqMatches":[{"year":"2014","no":1872,"q":"How much time after reduced movement fetal heart stops?","o":["1 hr","2 hrs","6 hrs","12 hrs"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4043, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 140, '{"id":4043,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":140,"q":"Red cell volume is increased by what percentage in pregnancy?","o":["10 - 20%","20 - 30%","30 - 40%","40 - 50%"],"a":1,"e":"Ans. B. 20 - 30%","pyqMatches":[{"year":"2014","no":1871,"q":"Red cell volume is increased by what percentage in pregnancy?","o":["10 - 20%","20 - 30%","30 - 40%","40 - 50%"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
