INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4045, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Gynecology', 142, '{"id":4045,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Gynecology","sourceNo":142,"q":"Not a risk for ectopic pregnancy ?","o":["Use of condom","OCP","PID","Previous ectopic pregnancy"],"a":0,"e":"Ans. A. Use of condom","pyqMatches":[{"year":"2014","no":1869,"q":"Not a risk for ectopic pregnancy ?","o":["Use of condom","OCP","PID","Previous ectopic pregnancy"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4046, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 143, '{"id":4046,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":143,"q":"Risk factors for the ectopic pregnancy are ?","o":["IUCD","History of infertility","Tubal endometriosis","All the above"],"a":3,"e":"Ans, D, All the above","pyqMatches":[{"year":"2014","no":1868,"q":"Risk factors for the ectopic pregnancy are ?","o":["IUCD","History of infertility","Tubal endometriosis","All the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4047, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Gynecology', 144, '{"id":4047,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Gynecology","sourceNo":144,"q":"34 weeks pregnancy with low lying placenta previa, floating head, Hb - 11 gm%. What should be the further line of management?","o":["Expectant management","Induction of labour","Caesarian section","Blood transfusion"],"a":0,"e":"Ans. A. Expectant management","pyqMatches":[{"year":"2014","no":1867,"q":"34 weeks pregnancy with low lying placenta previa, floating head, Hb - 11 gm%. What should be the further line of management?","o":["Expectant management","Induction of labour","Caesarian section","Blood transfusion"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4048, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 145, '{"id":4048,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":145,"q":"Which of the following is an absolute indication for caesarian section?","o":["Central placenta previa","Breech presentation","Bad obstetric history","Previous caesarian delivery"],"a":0,"e":"Ans, A. Central placenta previa Absolute indications for caesarian section- Central placenta previa Contracted pelvis or cephalopelvic disproportion (absolute) Pelvic mass causing obstruction (cervical or broad ligament fibroid)","pyqMatches":[{"year":"2014","no":1866,"q":"Which of the following is an absolute indication for caesarian section?","o":["Central placenta previa","Breech presentation","Bad obstetric history","Previous caesarian delivery"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4049, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 146, '{"id":4049,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":146,"q":"What is used to aid identification of areas of dysplasia in colposcopy?","o":["3 - 5% acetic acid","Acetocarmine red","1 % formic acid","1 % alcohol"],"a":0,"e":"Ans. A. 3 - 5% acetic acid Colposcopy is the mainstay in the diagnosis of cervical dysplasia and precancerous lesions.","pyqMatches":[{"year":"2014","no":1865,"q":"What is used to aid identification of areas of dysplasia in colposcopy?","o":["3 - 5% acetic acid","Acetocarmine red","1 % formic acid","1 % alcohol"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4050, 'OBG', 'Miscellaneous', 'Hard', 'Gynecology', 147, '{"id":4050,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Hard","source":"Gynecology","sourceNo":147,"q":"Following are the ultrasound doppler parameters used in the diagnosis of intrauterine growth restriction except?","o":["Abdominal circumference","Doppler velocimetry","Increased diastolic velocity in middle cerebral artery","Ponderal index"],"a":0,"e":"Ans, A. Abdominal circumference","pyqMatches":[{"year":"2014","no":1864,"q":"Following are the ultrasound doppler parameters used in the diagnosis of intrauterine growth restriction except?","o":["Abdominal circumference","Doppler velocimetry","Increased diastolic velocity in middle cerebral artery","Ponderal index"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4051, 'OBG', 'Abortion & Ectopic Pregnancy', 'Easy', 'Gynecology', 148, '{"id":4051,"subject":"OBG","chapter":"Abortion & Ectopic Pregnancy","difficulty":"Easy","source":"Gynecology","sourceNo":148,"q":"Most common cause of early abortion -","o":["Genetic","Maternal","Immunologic","Anatomic abnormalities"],"a":0,"e":"Ans. A. Genetic","pyqMatches":[{"year":"2014","no":1863,"q":"Most common cause of early abortion","o":["Genetic","Maternal","Immunologic","Anatomic abnormalities"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4052, 'OBG', 'Infertility & Reproductive Endocrinology', 'Moderate', 'Gynecology', 149, '{"id":4052,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Moderate","source":"Gynecology","sourceNo":149,"q":"Following are the indicatons of hysterosalpingography except","o":["Fallopian tube patency in infertility","Study uterine anamoly","Detect uterine synechiae","Detect endometriosis"],"a":3,"e":"Ans, D. Detect endometriosis Indications of HysterosaIpingography To study the patency offallopian tubes in infertility and postoperative tuboplasty To assess the feasibility of tuboplasty by studying the extent of tubal pathologist. To study the uterine anomaly such as septate and cornuate uterus To detect uterine synechiae To detect uterine polyp To study the incompetence of internal OS","pyqMatches":[{"year":"2014","no":1862,"q":"Following are the indicatons of hysterosalpingography except","o":["Fallopian tube patency in infertility","Study uterine anamoly","Detect uterine synechiae","Detect endometriosis"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4053, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Gynecology', 150, '{"id":4053,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Gynecology","sourceNo":150,"q":"Sarcoma botryoides all are true except ?","o":["Also called embryonalrhabdomyosarcoma","Commonly arises from vagina","It presents with blood stained watery vaginal discharge","It can be treated with VAC regime"],"a":1,"e":"Ans B. Commonly arises from vagina Sarcoma botyroides ( Embrvonalrhabdomyosarcoma) Special type of mixed mesodermal tumour commonly arising from cervix, rarely from vagina &uterus.","pyqMatches":[{"year":"2014","no":1861,"q":"Sarcoma botryoides all are true except ?","o":["Also called embryonalrhabdomyosarcoma","Commonly arises from vagina","It presents with blood stained watery vaginal discharge","It can be treated with VAC regime"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4054, 'OBG', 'Labour & Delivery', 'Moderate', 'Gynecology', 151, '{"id":4054,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Moderate","source":"Gynecology","sourceNo":151,"q":"Monzygotic twin with one healthy baby born at term and one dead mummified fetusis suggestive of ?","o":["Fetus acardiacus","Fetus papyraceous","Hydatidiform mole","Vanishing twin"],"a":1,"e":"Ans. B. Fetus papyraceous Fetus Paoyraceous or compressus- Is a state which occurs in case of twins when one of the fetuses dies early. The dead fetus is flattened mummifed and compressed between the membranes of livingfetus and uterine waII. It may occur in both varieties of twins but is more common in monozygotic twins and is discovered at delivery or earlier by sonography.","pyqMatches":[{"year":"2014","no":1860,"q":"Monzygotic twin with one healthy baby born at term and one dead mummified fetusis suggestive of ?","o":["Fetus acardiacus","Fetus papyraceous","Hydatidiform mole","Vanishing twin"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4055, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 152, '{"id":4055,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":152,"q":"Mediolateral episiotomy is preferred because ?","o":["Reduces damage to anal sphincter and anal canal","Less blood loss","Easy to suture","Easy technique"],"a":0,"e":"Ans, A. Reduces damage to anal sphincter and anal canal Mediolateral episiotomy reduces the risk of damage to anal sphincter and anal canal thought it may slightly increase the bleeding.","pyqMatches":[{"year":"2014","no":1859,"q":"Mediolateral episiotomy is preferred because ?","o":["Reduces damage to anal sphincter and anal canal","Less blood loss","Easy to suture","Easy technique"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4056, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Gynecology', 153, '{"id":4056,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Gynecology","sourceNo":153,"q":"Which is not a part of basic essential obstetric care?","o":["Blood transfusion","Parenteral antibiotics","Parenteral oxytocic drugs","Parenteral sedatives for eclampsia"],"a":0,"e":"Ans. A. Blood transfusion Basic essential obstetric care services at the health center level should include at least the following: Parenteral antibiotics Parenteral oxytocic drugs Parenteral sedativesfor eclampsia Manual removal of placenta Manual removal of retained products","pyqMatches":[{"year":"2014","no":1858,"q":"Which is not a part of basic essential obstetric care?","o":["Blood transfusion","Parenteral antibiotics","Parenteral oxytocic drugs","Parenteral sedatives for eclampsia"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4057, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 154, '{"id":4057,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":154,"q":"Vasa previa is seen in which type of placenta ?","o":["Central","Vilamentous","Peripheral","None of the above"],"a":1,"e":"Ans. B. Vilamentous Vasa previa If a leash of blood vessels happen to traverse through the membranes overlying the internal os, in front of presenting part, the condition is called vasa previa. These are the unsupported umbilical vessels in vilamentous placenta.","pyqMatches":[{"year":"2014","no":1857,"q":"Vasa previa is seen in which type of placenta ?","o":["Central","Vilamentous","Peripheral","None of the above"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4058, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 155, '{"id":4058,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":155,"q":"Duration of second stage of labor depends upon -","o":["Size of fetus","Mother''s build","Parity","Lie of fetus"],"a":2,"e":"Ans, C, Parity The duration of the normal second stage is usually very much shorter than the normalfirst stage of labour. As with the first stage the duration of the second stage willmainlydepends on whether it is the first labour or the woman haspreviously given birth to a viable infant i. e. it depends on the parity status ofthe mother,","pyqMatches":[{"year":"2014","no":1856,"q":"Duration of second stage of labor depends upon","o":["Size of fetus","Mother''s build","Parity","Lie of fetus"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4059, 'OBG', 'Gynecologic Oncology', 'Moderate', 'Gynecology', 156, '{"id":4059,"subject":"OBG","chapter":"Gynecologic Oncology","difficulty":"Moderate","source":"Gynecology","sourceNo":156,"q":"Simultaneous administration of estrogen and progesterone in hormone replacement therapy increases risk of ?","o":["Ovarian cancer","Breast cancer","Cervical cancer","Both a and b"],"a":3,"e":"Ans D. Both a and b Risk due to both estrogen and progesterone in HRT:- Breast cancer Ovarian cancer Risk due to only estrogen in HRT:- Endometrial carcinoma","pyqMatches":[{"year":"2014","no":1855,"q":"Simultaneous administration of estrogen and progesterone in hormone replacement therapy increases risk of ?","o":["Ovarian cancer","Breast cancer","Cervical cancer","Both a and b"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4060, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 157, '{"id":4060,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":157,"q":"LEEP stands for ?","o":["Loop electrosurgical excision procedure","Loop electromagnetic excision procedure","Loop electrodiagnostic excision procedure","Loop electrochemical excision procedure"],"a":0,"e":"Ans, A, Loop electrosurgical excision procedure LEEP Stands for Loop Electrosurgical diagnostic procedure. It is also known as large loop excision of the transformation zone (LLETZ).","pyqMatches":[{"year":"2014","no":1854,"q":"LEEP stands for ?","o":["Loop electrosurgical excision procedure","Loop electromagnetic excision procedure","Loop electrodiagnostic excision procedure","Loop electrochemical excision procedure"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4061, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Gynecology', 158, '{"id":4061,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Gynecology","sourceNo":158,"q":"Definitive treatment for a case of severe pre eclampsia is -","o":["MgS0,","Delivery of baby","Antihypertensive drugs","Rest"],"a":1,"e":"Ans, B. Delivery of baby For all types of PIH, irrespective of severity, definitive management is termination of pregnancy\"","pyqMatches":[{"year":"2014","no":1853,"q":"Definitive treatment for a case of severe pre eclampsia is","o":["MgS0,","Delivery of baby","Antihypertensive drugs","Rest"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4062, 'OBG', 'Benign Gynecology', 'Moderate', 'Gynecology', 159, '{"id":4062,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Moderate","source":"Gynecology","sourceNo":159,"q":"Another name for mancehster operation for uterine prolapse is ?","o":["Fothergill","Mercy","McDonald","Purandare"],"a":0,"e":"Ans, A, Fothergill Manchester operation also called Fothergill''s operation.","pyqMatches":[{"year":"2014","no":1852,"q":"Another name for mancehster operation for uterine prolapse is ?","o":["Fothergill","Mercy","McDonald","Purandare"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4063, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 160, '{"id":4063,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":160,"q":"What is the risk of recurrence of anencephaly in subsequent pregnancy?","o":["1%","2%","3%","4%"],"a":1,"e":"Ans, B. 2% The risk of recurrence of anencephaly in subsequent pregnancy is 2%.","pyqMatches":[{"year":"2014","no":1851,"q":"What is the risk of recurrence of anencephaly in subsequent pregnancy?","o":["1%","2%","3%","4%"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4064, 'OBG', 'Labour & Delivery', 'Moderate', 'Gynecology', 161, '{"id":4064,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Moderate","source":"Gynecology","sourceNo":161,"q":"Following is true about tamoxifene except ?","o":["It is a selective estrogen receptor modulator","It is a competitive inhibitor of estrogen at receptor site","It decreases risk of venous thromboembolism","It can be used for induction of ovulation"],"a":2,"e":"Ans, C, It decreases risk of venous thromboembolism","pyqMatches":[{"year":"2014","no":1850,"q":"Following is true about tamoxifene except ?","o":["It is a selective estrogen receptor modulator","It is a competitive inhibitor of estrogen at receptor site","It decreases risk of venous thromboembolism","It can be used for induction of ovulation"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4065, 'OBG', 'Labour & Delivery', 'Hard', 'Gynecology', 162, '{"id":4065,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Hard","source":"Gynecology","sourceNo":162,"q":"Following is true regarding the management of intrauterine fetal death except ?","o":["In 50% of cases spontaneous expulsion occurs in 2 weeks","Fibrinogen levels should be checked weekly","Delivery by medical induction is preferred if spontaneous expulsion does not occur","Caesarian section has limited place in management of intrauterine fetal death"],"a":0,"e":"Ans, A, In 50% of cases spontaneous expulsion occurs in 2 weeks","pyqMatches":[{"year":"2014","no":1849,"q":"Following is true regarding the management of intrauterine fetal death except ?","o":["In 50% of cases spontaneous expulsion occurs in 2 weeks","Fibrinogen levels should be checked weekly","Delivery by medical induction is preferred if spontaneous expulsion does not occur","Caesarian section has limited place in management of intrauterine fetal death"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4066, 'OBG', 'Labour & Delivery', 'Easy', 'Gynecology', 163, '{"id":4066,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Gynecology","sourceNo":163,"q":"Sequence of lochia ?","o":["Rubra - Serosa - Alba","Serosa - Alba - Rubra","Alba - Rubra - Serosa","Alba - Serosa - Rubra"],"a":0,"e":"Ans, A, Rubra - Serosa - Alba Lochia It is the vaginal discharge for the first fortnight during peurperium. The discharge originates from the uterine body, cervix and vagina.","pyqMatches":[{"year":"2014","no":1848,"q":"Sequence of lochia ?","o":["Rubra - Serosa - Alba","Serosa - Alba - Rubra","Alba - Rubra - Serosa","Alba - Serosa - Rubra"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4067, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Gynecology', 164, '{"id":4067,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Gynecology","sourceNo":164,"q":"Amenorrhoea following hyperprolactinoma is caused by ?","o":["Inhibition of GnRH pulse secretion","Inhibition of adrenal steoridogenesis","It causes hypergonadotropic hypogonadism","It leads to formation of ovarian cysts"],"a":0,"e":"Ans, A. Inhibition of GnRH pulse secretion Prolactin inhibits GnRH pulse secretion and suppresses ganadotropin levels. Hyperprolactinemiacauses amenorrhea, anovulation and Hypogonadism.","pyqMatches":[{"year":"2014","no":1847,"q":"Amenorrhoea following hyperprolactinoma is caused by ?","o":["Inhibition of GnRH pulse secretion","Inhibition of adrenal steoridogenesis","It causes hypergonadotropic hypogonadism","It leads to formation of ovarian cysts"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4068, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 165, '{"id":4068,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":165,"q":"Old complete perineal tear is repaired at ?","o":["Immediately","3 - 6 months","6 - 9 months","9 - 12 months"],"a":1,"e":"Ans, B. 3 - 6 months The definitive surgery for complete perineal tear k repair of the anal sphincter complex (sphinaeroptasty) with restoration of the perineal body (perineoraphy). For the fresh injuries the best time of repair is within 24 hours afire injury, For old perineal tears this should preferable be done 3 - 6 months following injury.","pyqMatches":[{"year":"2014","no":1846,"q":"Old complete perineal tear is repaired at ?","o":["Immediately","3 - 6 months","6 - 9 months","9 - 12 months"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4069, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 166, '{"id":4069,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":166,"q":"Which of the following has maximum diabetogenic potency in pregnancy ?","o":["Estrogen","Progesterone","Cortisol","Prolactin"],"a":2,"e":"Ans, C, Cortisol","pyqMatches":[{"year":"2014","no":1845,"q":"Which of the following has maximum diabetogenic potency in pregnancy ?","o":["Estrogen","Progesterone","Cortisol","Prolactin"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4070, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 167, '{"id":4070,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":167,"q":"Role of ergometrine to stop post partum hemorrhage is due to ?","o":["Increased uterine muscle tone","Vasoconstriction","Increased platelet aggregation","Increased coagulation"],"a":0,"e":"Ans. A. Increased uterine muscle tone Ergometrine acts directly on myometrium and excites uterine contractions, which closes blood vessels in between thus helps in controlling PPH. Vasoconstrictive action of ergometrine does not control bleeding but may cause rise in B.P. gangrene of toe, PreciPitate bronchospasm. Option (c) & (d), are not the action of ergometrine.","pyqMatches":[{"year":"2013","no":1596,"q":"Role of ergometrine to stop post partum hemorrhage is due to ?","o":["Increased uterine muscle tone","Vasoconstriction","Increased platelet aggregation","Increased coagulation"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4071, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 168, '{"id":4071,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":168,"q":"Continence & incontinence of urine is seen in ?","o":["VVF","Vesicoperitoneal","Ureterovaginal","Uretrovaginal"],"a":2,"e":"Ans. C. Ureterovaginal Continence and incontinence of urine is seen in ureterovaginal fistula.","pyqMatches":[{"year":"2013","no":1597,"q":"Continence & incontinence of urine is seen in ?","o":["VVF","Vesicoperitoneal","Ureterovaginal","Uretrovaginal"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4072, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 169, '{"id":4072,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":169,"q":"Type of suture used in complete perineal tear is -","o":["Catgut","Silk","Vicryl","Vicryl and catgut"],"a":3,"e":"Ans. D. Vicryl and catgut Rectum is dissected to clear of scar tissue & freshening of cut edges. Cut edges ofrectum and anus are sutured with vicryl. Deep muscle of perenial body and levatorani are identified and sutured with No l-catgut. Superficial muscle is sutured with vicrylcatgut sutures.","pyqMatches":[{"year":"2013","no":1598,"q":"Type of suture used in complete perineal tear is","o":["Catgut","Silk","Vicryl","Vicryl and catgut"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4073, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 170, '{"id":4073,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":170,"q":"Uterine rupture is most common in -","o":["Ant lower segment","Classical C.S","Placenta previa","Normal labour"],"a":1,"e":"Ans. B. Classical C.S","pyqMatches":[{"year":"2013","no":1599,"q":"Uterine rupture is most common in","o":["Ant lower segment","Classical C.S","Placenta previa","Normal labour"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
