INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4075, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Gynecology', 172, '{"id":4075,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Gynecology","sourceNo":172,"q":"Age of metropathic hemorrhagica is ?","o":["20-25","50-55","60-65","40-45"],"a":3,"e":"Ans, D. 40-45 Metropathiahemorrhagica Specializedform of DUB. Mostly seen in premenopausal women. Maximum age incidence: Between ages 40-45 years. Patient complains of prolonged amenorrhea (of 6-8 weeks) followed by excessive painless bleeding (anovular bleeding).","pyqMatches":[{"year":"2013","no":1601,"q":"Age of metropathic hemorrhagica is ?","o":["20-25","50-55","60-65","40-45"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
