INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4078, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 175, '{"id":4078,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":175,"q":"Battle door insertion of placenta ?","o":["Cord attached to the margin of placenta","Placenta attached to the margin","Cord attached to the membranes","Placenta attached to the centre"],"a":2,"e":"Ans. C. Cord attached to the membranes Change in fetal heart rate (tachycardia/loss of beat to beat variability/decelerations) is earliest sign of impending scar dehiscence, followed by maternal tachycardia.","pyqMatches":[{"year":"2013","no":1604,"q":"Battle door insertion of placenta ?","o":["Cord attached to the margin of placenta","Placenta attached to the margin","Cord attached to the membranes","Placenta attached to the centre"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
