INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4088, 'OBG', 'Gynecologic Oncology', 'Easy', 'Gynecology', 185, '{"id":4088,"subject":"OBG","chapter":"Gynecologic Oncology","difficulty":"Easy","source":"Gynecology","sourceNo":185,"q":"Most common presentation of cervical cancer is -","o":["Deep pelvic pain","Rectal pain","Bleeding per vaginum","Weight loss"],"a":2,"e":"Ans, C. Bleeding per vaginum","pyqMatches":[{"year":"2013","no":1611,"q":"Most common presentation of cervical cancer is","o":["Deep pelvic pain","Rectal pain","Bleeding per vaginum","Weight loss"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4089, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 186, '{"id":4089,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":186,"q":"Treatment of simple hyperplasia of endometrium is ?","o":["Progesterone","Estrogen","Hysterectomy","Cryosurgery"],"a":0,"e":"Ans, A. Progesterone","pyqMatches":[{"year":"2013","no":1612,"q":"Treatment of simple hyperplasia of endometrium is ?","o":["Progesterone","Estrogen","Hysterectomy","Cryosurgery"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4090, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 187, '{"id":4090,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":187,"q":"Most common presenting feature of complete mole is ?","o":["Vomiting","Amenorrhoea","Amenorrhoea","Bleeding per vaginum"],"a":3,"e":"Ans, D. Bleeding per vaginum Clinical features of complete mole Vaginal bleeding is the most common symptom causing patient to seek treatment for complete mole pregnancy. Abnormal uterine bleeding usually during the first trimester is the most common presenting symptom occurring in more than 90% of patients with molar pregnancies.","pyqMatches":[{"year":"2013","no":1613,"q":"Most common presenting feature of complete mole is ?","o":["Vomiting","Amenorrhoea","Amenorrhoea","Bleeding per vaginum"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4091, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 188, '{"id":4091,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":188,"q":"Androgenic XX chromosome is ?","o":["Partial mole","Complete mole","Turner''s syndrome","Stein leventhal syndrome"],"a":1,"e":"Ans, B. Complete mole Characteristics of complete Mole Complete H. mole shows no evidence of fetal tissue at all. Complete hydatiform moles exhibit characteristic swelling and trophoblastic hyperplasia. Most common karyotype is 46XX. The molar chromosomes are entirely of paternal origin, although mitochondrial DNA is of maternal origin. The complete mole arises from an ovum that has been fertilized by a haploid sperm, which then duplicates its own chromosomes called Anilrogenesis. The ovum nucleus may be either absent or inactivated.","pyqMatches":[{"year":"2013","no":1614,"q":"Androgenic XX chromosome is ?","o":["Partial mole","Complete mole","Turner''s syndrome","Stein leventhal syndrome"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4092, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 189, '{"id":4092,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":189,"q":"High chance of rupture in tubal pregnancy are seen in which ?","o":["Ampulla","Isthmus","Interstitial","Fimbrial"],"a":1,"e":"Ans. B. Isthmus M.C.siteoftubal rupture = Isthmus","pyqMatches":[{"year":"2013","no":1615,"q":"High chance of rupture in tubal pregnancy are seen in which ?","o":["Ampulla","Isthmus","Interstitial","Fimbrial"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4093, 'OBG', 'Abortion & Ectopic Pregnancy', 'Easy', 'Gynecology', 190, '{"id":4093,"subject":"OBG","chapter":"Abortion & Ectopic Pregnancy","difficulty":"Easy","source":"Gynecology","sourceNo":190,"q":"Most common site of ectopic pregnancy is -","o":["Tubal","Abdominal","Ovarian","Uterine"],"a":0,"e":"Ans, A. Tubal Most common site of ectopic pregnancy is fallopian tube. In tubal pregnancy M.C. site is ampula followed by Isthmus.","pyqMatches":[{"year":"2013","no":1616,"q":"Most common site of ectopic pregnancy is","o":["Tubal","Abdominal","Ovarian","Uterine"],"a":0,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":1835,"q":"Most common site of ectopic pregnancy is ?","o":["Ovary","Fallopian tube","Peritoneum","Cervix"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4094, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 191, '{"id":4094,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":191,"q":"% of ectopic pregnancy seen in fallopian tube is?","o":["75%","90%","80%","67%"],"a":1,"e":"Ans, B. 90% M.C. site of ectopic pregnancy = Fallopian tube (97%).","pyqMatches":[{"year":"2013","no":1617,"q":"% of ectopic pregnancy seen in fallopian tube is?","o":["75%","90%","80%","67%"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4095, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 192, '{"id":4095,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":192,"q":"Drugs used in ectopic pregnancy ?","o":["PGE2","PGI","PGF2","None"],"a":2,"e":"Ans. C. PGF2","pyqMatches":[{"year":"2013","no":1618,"q":"Drugs used in ectopic pregnancy ?","o":["PGE2","PGI","PGF2","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4096, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 193, '{"id":4096,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":193,"q":"Most common congenital uterine anomaly is ?","o":["Bicornuate uterus","Septate uterus","Unicornuate uterus","Arcuate uterus"],"a":1,"e":"Ans. B. Septate uterus","pyqMatches":[{"year":"2013","no":1619,"q":"Most common congenital uterine anomaly is ?","o":["Bicornuate uterus","Septate uterus","Unicornuate uterus","Arcuate uterus"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4097, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 194, '{"id":4097,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":194,"q":"When is copper T inserted ?","o":["3 days after periods are over","Within 10 days of start of menstrual cycle","PID just before menstruation","Just after menstruation"],"a":1,"e":"Ans, B. Within 10 days of start of menstrual cycle ldeal time for insertion of Cu-T is within 10 days of the start of the menstrual cycle It has the advantage that cervical canal is dilated, uterus is relaxed and chances ofpregnancy are remore. Post Partum insertion within 48 hours of delivery or 6 weeks after delivery. Post-MTP insertion immediately following D & E (in early pregnancy)","pyqMatches":[{"year":"2013","no":1620,"q":"When is copper T inserted ?","o":["3 days after periods are over","Within 10 days of start of menstrual cycle","PID just before menstruation","Just after menstruation"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4098, 'OBG', 'Labour & Delivery', 'Easy', 'Gynecology', 195, '{"id":4098,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Gynecology","sourceNo":195,"q":"Most common cause of annular cervix is ?","o":["Obstructive labor","Prepitate labor","Primary cervical dystocia","Iatrogenic"],"a":2,"e":"Ans, C. Primary cervical dystocia Annular cervix is detachment of the cervix following prolonged labour in primary cervical dystocia.","pyqMatches":[{"year":"2013","no":1621,"q":"Most common cause of annular cervix is ?","o":["Obstructive labor","Prepitate labor","Primary cervical dystocia","Iatrogenic"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4099, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 196, '{"id":4099,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":196,"q":"Intrauterine adhesions best seen by?","o":["USG","CT","Hysteroscopy","MRI"],"a":2,"e":"Ans. C. Hysteroscopy Hysteroscopy is the endoscopic technique of visualizing the interior of uterus directly, It is both diagnostic and therapeutic.","pyqMatches":[{"year":"2013","no":1622,"q":"Intrauterine adhesions best seen by?","o":["USG","CT","Hysteroscopy","MRI"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4100, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 197, '{"id":4100,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":197,"q":"Insulin resistance in pregnancy is due to ?","o":["Estrogen","Progesterone","HPL","GH"],"a":0,"e":":C Ans. C>A. HPL>Estrogen During Pregnancy insulin levels are increased because of increased insulin secretion as well as increase in insulin resistance due to a number of contra insulin factors but the most important hormone causing insulin resistance is Human placental lactogen.","pyqMatches":[{"year":"2013","no":1623,"q":"Insulin resistance in pregnancy is due to ?","o":["Estrogen","Progesterone","HPL","GH"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4101, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 198, '{"id":4101,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":198,"q":"Gestational diabetes mellitus ?","o":["Is first recognized during pregnancy","Previous history of IUGR","There is no recurrance of GDM in future pregnancy","No risk of overt diabetes"],"a":0,"e":"Ans. A. Is first recognized during pregnancy Gestational diabetes mellitus is defined as carbohydrate intolerance of variable severity with onset or first recognition during Pregnancy. Pregnancy is a form of stress that can cause latent diabetes to manifest just as do surgical operations or acute infections. In most of the cases the carbohydrate intolerance reverts by the end of puerperium but this manifestation may be the first indication of diabetes yet to come. More than half the women with gestational diabetes will develop frank diabetes within the next 20 years. However in some of these carbohydrate intolerance may persist beyond the puerperium and these are in reality cases of pre- gestational diabetes which have become overt during pregnancy.","pyqMatches":[{"year":"2013","no":1624,"q":"Gestational diabetes mellitus ?","o":["Is first recognized during pregnancy","Previous history of IUGR","There is no recurrance of GDM in future pregnancy","No risk of overt diabetes"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4102, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 199, '{"id":4102,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":199,"q":"True about gestational diabetes is ?","o":["These are increased chances of congenital malformation","Only 2% of women present with overt diabetes","There is chance of macrosomia","Usually diagnosed in early pregnancy"],"a":2,"e":"Ans. C. There is chance of macrosomia","pyqMatches":[{"year":"2013","no":1625,"q":"True about gestational diabetes is ?","o":["These are increased chances of congenital malformation","Only 2% of women present with overt diabetes","There is chance of macrosomia","Usually diagnosed in early pregnancy"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4103, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Gynecology', 200, '{"id":4103,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Gynecology","sourceNo":200,"q":"Most common presenting symptom of TB endometritis is -","o":["Abdominal pain","Infertility","Amenorrhoea","Vaginal discharge"],"a":1,"e":"Ans, B. Infertility Most common symptom of Genital TB is:- Infertility (35-60%) is either due to blockage offallopian tube or due to loss oftubal function even iftubes are patent.","pyqMatches":[{"year":"2013","no":1626,"q":"Most common presenting symptom of TB endometritis is","o":["Abdominal pain","Infertility","Amenorrhoea","Vaginal discharge"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4104, 'OBG', 'Contraception & Family Planning', 'Easy', 'Gynecology', 201, '{"id":4104,"subject":"OBG","chapter":"Contraception & Family Planning","difficulty":"Easy","source":"Gynecology","sourceNo":201,"q":"PID after insertion of IUD is seen in how many weeks?","o":["3","5","7","14"],"a":0,"e":"Ans, A. 3 The risk of developing PID is 2-10 times greater among the IIJD users. The risk is more in the first 3 weeks. Infection with chlamydia and actinomycosis most common.","pyqMatches":[{"year":"2013","no":1627,"q":"PID after insertion of IUD is seen in how many weeks?","o":["3","5","7","14"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4105, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 202, '{"id":4105,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":202,"q":"Acute PID, most common route of spread ?","o":["Descending","Ascending infection","Lymphatics","Hematogenous"],"a":1,"e":"Ans, B, Ascending infection M/c route of spread of PID is:- Ascending infection along with sperms. All PIDs are sexually transmitted except TB.","pyqMatches":[{"year":"2013","no":1628,"q":"Acute PID, most common route of spread ?","o":["Descending","Ascending infection","Lymphatics","Hematogenous"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4106, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 203, '{"id":4106,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":203,"q":"Best way to look at endometrial activity is by -","o":["HSG","Biopsy","USG","Colposcopy"],"a":1,"e":"Ans, B. Biopsy Endometrial sampling or curettage or biopsy is the best method to assess endometrial activity.","pyqMatches":[{"year":"2013","no":1629,"q":"Best way to look at endometrial activity is by","o":["HSG","Biopsy","USG","Colposcopy"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4107, 'OBG', 'Labour & Delivery', 'Easy', 'Gynecology', 204, '{"id":4107,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Gynecology","sourceNo":204,"q":"Block given in forceps delivery ?","o":["Pudendal","Ilio inguinal","Genitofemoral","Posterior femoral"],"a":0,"e":"Ans, A. Pudendal For forceps oPerationpudendal block is given supplemented by perineal and labial infiltration.","pyqMatches":[{"year":"2013","no":1630,"q":"Block given in forceps delivery ?","o":["Pudendal","Ilio inguinal","Genitofemoral","Posterior femoral"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4108, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 205, '{"id":4108,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":205,"q":"Cause of big baby ?","o":["Hyperglycemia","Hyperinsulinemia","Multiparity","Post maturity"],"a":0,"e":":B:C:D Ans, All of the above A, B, C, D","pyqMatches":[{"year":"2013","no":1631,"q":"Cause of big baby ?","o":["Hyperglycemia","Hyperinsulinemia","Multiparity","Post maturity"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4109, 'OBG', 'Benign Gynecology', 'Easy', 'Gynecology', 206, '{"id":4109,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Easy","source":"Gynecology","sourceNo":206,"q":"Decubitus ulcer is ?","o":["Due to trauma","Due to venous congestion","Due to friction created by thighs","Due to"],"a":1,"e":"Ans, B. Due to venous congestion Decubitus ulcer is a trophic ulcer always found at the dependent part of the prolapsed mass (in prolapsed uterus). It is due to decreased circulation due to narrowing of uterine vessels by stretching efect with additionalkeratinizations, cracks.","pyqMatches":[{"year":"2013","no":1632,"q":"Decubitus ulcer is ?","o":["Due to trauma","Due to venous congestion","Due to friction created by thighs","Due to"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":1586,"q":"Decubitus ulcer is","o":["Venous ulcer","Wet gangrene","Trophic ulcer","Post thrombotic ulcer"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4110, 'OBG', 'Benign Gynecology', 'Hard', 'Gynecology', 207, '{"id":4110,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Hard","source":"Gynecology","sourceNo":207,"q":"Patient with history of vaginal prolapse with ulcer on it. Diagnosis ?","o":["Carcinoma","Pressure erosion","Syphilis","Decubitus ulcer"],"a":3,"e":"Ans, D. Decubitus ulcer","pyqMatches":[{"year":"2013","no":1633,"q":"Patient with history of vaginal prolapse with ulcer on it. Diagnosis ?","o":["Carcinoma","Pressure erosion","Syphilis","Decubitus ulcer"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4111, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 208, '{"id":4111,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":208,"q":"SERMs are ?","o":["Agonist on estrogen receptor","Antagonist on estrogen receptor","Some are agonist some antagonist on estrogen receptor","Used due to reduced chances of hot flushes, thromboembolism"],"a":2,"e":"Ans, C, Some are agonist some antagonist on estrogen receptor SERM’s are selective estrogen receptor modulators called SERMs blocks the effects of estrogen in the breast tissue. They block the effect of estrogen by acting on estrogen recePtors.","pyqMatches":[{"year":"2013","no":1634,"q":"SERMs are ?","o":["Agonist on estrogen receptor","Antagonist on estrogen receptor","Some are agonist some antagonist on estrogen receptor","Used due to reduced chances of hot flushes, thromboembolism"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4112, 'OBG', 'Infertility & Reproductive Endocrinology', 'Hard', 'Gynecology', 209, '{"id":4112,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Hard","source":"Gynecology","sourceNo":209,"q":"Female with hirsutism with ammenorrhoea and obesity. Diagnosis ?","o":["PCOD","Ovarian tumor","Androgen insensitivity syndrome","Turner syndrome"],"a":0,"e":"Ans, A. PCOD The clinical and laboratory features of the patient described in the question match with those of PCOS as depicted in the table. So the most appropriate answer is PCOD.","pyqMatches":[{"year":"2013","no":1635,"q":"Female with hirsutism with ammenorrhoea and obesity. Diagnosis ?","o":["PCOD","Ovarian tumor","Androgen insensitivity syndrome","Turner syndrome"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4113, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 210, '{"id":4113,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":210,"q":"HAIRAN syndrome is seen in ?","o":["PCOD","Endometeriosis","CA ovary","Adrenal tumours"],"a":0,"e":"Ans, A. PCOD PCOD is also known as HAIRAN SyNDROME","pyqMatches":[{"year":"2013","no":1636,"q":"HAIRAN syndrome is seen in ?","o":["PCOD","Endometeriosis","CA ovary","Adrenal tumours"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4114, 'OBG', 'Miscellaneous', 'Moderate', 'Gynecology', 211, '{"id":4114,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Gynecology","sourceNo":211,"q":"Regarding PCOD all are true except ?","o":["High FSH/LH","High DHEA","Raised LH","T Estrogen"],"a":0,"e":"Ans, A. High FSH/LH PCOD is also known as HAIRAN SyNDROME","pyqMatches":[{"year":"2013","no":1637,"q":"Regarding PCOD all are true except ?","o":["High FSH/LH","High DHEA","Raised LH","T Estrogen"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4115, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 212, '{"id":4115,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":212,"q":"Which hormone increases in PCOD ?","o":["LH","FSH","Estrogen","TSH"],"a":0,"e":"Ans, A, LH Stein leventhal syndrome is also called ‘Polycystic Ovarian Syndrome''","pyqMatches":[{"year":"2013","no":1638,"q":"Which hormone increases in PCOD ?","o":["LH","FSH","Estrogen","TSH"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4116, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 213, '{"id":4116,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":213,"q":"Stein Levinthal syndrome what hormone is raised?","o":["LH","FSH","GnRH","Progesterone"],"a":0,"e":"Ans, A. LH","pyqMatches":[{"year":"2013","no":1639,"q":"Stein Levinthal syndrome what hormone is raised?","o":["LH","FSH","GnRH","Progesterone"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4117, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Gynecology', 214, '{"id":4117,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Gynecology","sourceNo":214,"q":"What should not be done during delivery of Rh negative?","o":["IV Fluids","External version","Manual removal of placenta should be done gently","Ergometire to be withheld at delivery of ant. shoulder"],"a":0,"e":"Ans, A. IV Fluids","pyqMatches":[{"year":"2013","no":1640,"q":"What should not be done during delivery of Rh negative?","o":["IV Fluids","External version","Manual removal of placenta should be done gently","Ergometire to be withheld at delivery of ant. shoulder"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4118, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 215, '{"id":4118,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":215,"q":"History of yellow green watery discharge and pruritus?","o":["Trichomonas vaginalis","Candida","Bacterial vaginosis","Clamydia tracomatis"],"a":1,"e":"Ans. B. Candida During Rh PregnancfstePs should be taken to prevent feto maternal bleeding; - Precautions during caesariansection to prevent blood spilling into peritoneal cavity Prophylactic ergometine with delivery of ant shoulder to be withheld. Amniocentesis should be done after sonographic. Localization of placenta to prevent placental injury. Forcible attempt for external version should not be done. Manual removal of placenta should be done gently. To refrainfrom abdominal palpation in abruption placenta.","pyqMatches":[{"year":"2013","no":1641,"q":"History of yellow green watery discharge and pruritus?","o":["Trichomonas vaginalis","Candida","Bacterial vaginosis","Clamydia tracomatis"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4119, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 216, '{"id":4119,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":216,"q":"Most common genital infection in pregnancy is ?","o":["Candida","Gonorrhea","Trachoma","Cytomegalo virus"],"a":0,"e":"Ans, A. Candida Seventy per cent show typical discharge, which is profuse, thin, creamy or slightly green in colour,irritating and frothy. The vaginal walls are tender, angry looking and the discharge causes pruritus and inflammation of the vulva.","pyqMatches":[{"year":"2013","no":1642,"q":"Most common genital infection in pregnancy is ?","o":["Candida","Gonorrhea","Trachoma","Cytomegalo virus"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4120, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 217, '{"id":4120,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":217,"q":"Decreased fetal heart sound is due to which drug -","o":["Oxytocin","Sodium bicarbonate","IV fluids","Iron"],"a":0,"e":"Ans, A, Oxytocin Vaginitis due to candida is more common than trichomonas and is more prevalent in Diabetic pregnancy. Treatment is miconazole vaginal cream for 7 days.","pyqMatches":[{"year":"2013","no":1643,"q":"Decreased fetal heart sound is due to which drug","o":["Oxytocin","Sodium bicarbonate","IV fluids","Iron"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4121, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 218, '{"id":4121,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":218,"q":"Dose of mifepristone in MTP is ?","o":["10mg","20 mg","100mg","200mg"],"a":0,"e":"Ans, A. 10mg Decreased fetal heart rate or fetal distress is due to fetal hypoxia.","pyqMatches":[{"year":"2013","no":1644,"q":"Dose of mifepristone in MTP is ?","o":["10mg","20 mg","100mg","200mg"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4122, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 219, '{"id":4122,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":219,"q":"A young sexually active female has intensive pruritus and watery discharge, smear shows ?","o":["Trichomonas vaginalis","Candida vaginitis","Gardenlla vaginalis","HIV"],"a":3,"e":"Ans, D. HIV","pyqMatches":[{"year":"2013","no":1645,"q":"A young sexually active female has intensive pruritus and watery discharge, smear shows ?","o":["Trichomonas vaginalis","Candida vaginitis","Gardenlla vaginalis","HIV"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4123, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 220, '{"id":4123,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":220,"q":"Treatment for trichomonas vaginalis is ?","o":["Metronidazole","Azithromycin","Ciprofloxacin","None"],"a":0,"e":"Ans. A. Metronidazole The drug of choice for Trichomonasvaginits is Metronidazole.","pyqMatches":[{"year":"2013","no":1646,"q":"Treatment for trichomonas vaginalis is ?","o":["Metronidazole","Azithromycin","Ciprofloxacin","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4124, 'OBG', 'Postpartum & Puerperium', 'Easy', 'Gynecology', 221, '{"id":4124,"subject":"OBG","chapter":"Postpartum & Puerperium","difficulty":"Easy","source":"Gynecology","sourceNo":221,"q":"Which organism causes puerperal sepsis ?","o":["CMV","Toxoplasma gondii","Group A beta hemolytic streptococci","Group B beta hemolytic streptococci"],"a":2,"e":"Ans, C. Group A beta hemolytic streptococci Most common cause of puerperal sepsis is Group A streptococcus. Other organisms that are implicated are: Striptococcus group B, C and G, staphylococcus aureus, E. coli, Enterobacterspeciesand chlamydia trachomatis.","pyqMatches":[{"year":"2013","no":1647,"q":"Which organism causes puerperal sepsis ?","o":["CMV","Toxoplasma gondii","Group A beta hemolytic streptococci","Group B beta hemolytic streptococci"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4125, 'OBG', 'Labour & Delivery', 'Easy', 'Gynecology', 222, '{"id":4125,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Gynecology","sourceNo":222,"q":"The prostaglandin most commonly used at term for induction of labor is ?","o":["PGI2","PGE1","PGE2","PGF2a"],"a":2,"e":"Ans. C. PGE2 PGE2 is most commonly used at term for induction of labor.","pyqMatches":[{"year":"2016","no":1575,"q":"The prostaglandin most commonly used at term for induction of labor is ?","o":["PGI2","PGE1","PGE2","PGF2a"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4126, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Gynecology', 223, '{"id":4126,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Gynecology","sourceNo":223,"q":"HCG levels at which Expectant management of Ectopic pregnancy can be done :","o":["10000 IU/L","1000 IU/L","2500 IU/L","5000 IU/L"],"a":1,"e":"Ans. B. 1000 IU/L Initial HCG levels < 1000 IU/l & subsequent levels are falling.","pyqMatches":[{"year":"2016","no":1576,"q":"HCG levels at which Expectant management of Ectopic pregnancy can be done :","o":["10000 IU/L","1000 IU/L","2500 IU/L","5000 IU/L"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4127, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Gynecology', 224, '{"id":4127,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Gynecology","sourceNo":224,"q":"MC cause of Primary Amenorrhea is ?","o":["Constitutional/idiopathic","RMKH syndrome","Ovarian dysgenesis","None of the above"],"a":2,"e":"Ans, C. Ovarian dysgenesis MC cause of primary amenorrhea is ovarian dysgenesis/Turner syndrome.","pyqMatches":[{"year":"2016","no":1492,"q":"MC cause of Primary Amenorrhea is ?","o":["Constitutional/idiopathic","RMKH syndrome","Ovarian dysgenesis","None of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4128, 'OBG', 'Miscellaneous', 'Moderate', 'Gynecology', 225, '{"id":4128,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Gynecology","sourceNo":225,"q":"An infertile woman has bilateral tubal block at cornua diagnosed on hysterosalpingography. Next treatment of choice is ?","o":["IVF","Laparoscopy and hysteroscopy","Tuboplasty","Hydrotubation"],"a":1,"e":"Ans. B. Laparoscopy and hysteroscopy Laparoscopy (with chromopertubation with methylene blue dye): Best investigation for tubal patency, as tubal patency can be confirmed under vision, and besides, any pathology can simultaneously be corrected with operative laparoscoPy.","pyqMatches":[{"year":"2016","no":1493,"q":"An infertile woman has bilateral tubal block at cornua diagnosed on hysterosalpingography. Next treatment of choice is ?","o":["IVF","Laparoscopy and hysteroscopy","Tuboplasty","Hydrotubation"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4129, 'OBG', 'Miscellaneous', 'Moderate', 'Gynecology', 226, '{"id":4129,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Gynecology","sourceNo":226,"q":"Fetal karyotyping can be done by all, EXCEPT?","o":["Cordocentesis","Amniocentesis","CVS","Fetal skin biopsy"],"a":3,"e":"Ans. D. Fetal skin biopsy Percutaneous umbilical blood sampling (PUBS) is also known as cordocentesisis performed after 16 weeks'' gestation'' under USG guidance a needle is inserted into umbilical vein. This technique apart from karyotyping is also useful for evaluating fetal metabolism and hematologic abnormalities.","pyqMatches":[{"year":"2016","no":1494,"q":"Fetal karyotyping can be done by all, EXCEPT?","o":["Cordocentesis","Amniocentesis","CVS","Fetal skin biopsy"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4130, 'OBG', 'Benign Gynecology', 'Hard', 'Gynecology', 227, '{"id":4130,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Hard","source":"Gynecology","sourceNo":227,"q":"55 year old lady complaints of mass in the vagina, which is reducible & increases on defecation. The diagnosis is?","o":["Rectal prolapse","Uterine prolapse","Cervical fibroid","Vaginal cancer"],"a":1,"e":"Ans. B. Uterine prolapse Prolapse is defined as the displacement of an organ from its normal anatomical position. Genital prolapse occurs due to weakness of the suPPorts.","pyqMatches":[{"year":"2016","no":1495,"q":"55 year old lady complaints of mass in the vagina, which is reducible & increases on defecation. The diagnosis is?","o":["Rectal prolapse","Uterine prolapse","Cervical fibroid","Vaginal cancer"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4131, 'OBG', 'Benign Gynecology', 'Easy', 'Gynecology', 228, '{"id":4131,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Easy","source":"Gynecology","sourceNo":228,"q":"Moschowit''s surgery is done for -","o":["Cervical cancer","Fundal fibroids","Uterine prolapse","Enterocele prevention"],"a":3,"e":"Ans. D. Enterocele prevention Enteroceleformatiol can be prevented by Moschowit''s or Halban''s surgeries, in both the POD is obliterated.","pyqMatches":[{"year":"2016","no":1496,"q":"Moschowit''s surgery is done for","o":["Cervical cancer","Fundal fibroids","Uterine prolapse","Enterocele prevention"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4132, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 229, '{"id":4132,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":229,"q":"Which of the following is used in quantifying hirsutism?","o":["Bishop score","Rotterdam criteria","Ferriman-Gallwey score","All of the above"],"a":2,"e":"Ans. C. Ferriman-Gallwey score The Ferriman-Gallwey score is a method of evaluating and quantifying hirsutism in women. The method was originally published in l96l by D. Ferriman and J.D. Gallwey in the Journal of Clinical Endocrinology.","pyqMatches":[{"year":"2016","no":1497,"q":"Which of the following is used in quantifying hirsutism?","o":["Bishop score","Rotterdam criteria","Ferriman-Gallwey score","All of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4133, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 230, '{"id":4133,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":230,"q":"MC heart disease in pregnancy is ?","o":["MS","AS","MR","WPW syndrome"],"a":0,"e":"Ans. A. MS Mitral stenosis is the MC valvular heart disease in pregnancy.","pyqMatches":[{"year":"2016","no":1498,"q":"MC heart disease in pregnancy is ?","o":["MS","AS","MR","WPW syndrome"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4134, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 231, '{"id":4134,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":231,"q":"Rate of cervical dilatation in primigravida is ?","o":["0.8 cm/hour","1.2 cm/hour","1.5 cm/hour","2 cm/hour"],"a":0,"e":"Ans. A. 0.8 cm/hour The normal rate of cervical dilatation in active phase is 1.2 cm/hour in primigravidae and 1.5 cm/hour in multiparae.","pyqMatches":[{"year":"2016","no":1499,"q":"Rate of cervical dilatation in primigravida is ?","o":["0.8 cm/hour","1.2 cm/hour","1.5 cm/hour","2 cm/hour"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4135, 'OBG', 'Antenatal Care & Complications', 'Moderate', 'Gynecology', 232, '{"id":4135,"subject":"OBG","chapter":"Antenatal Care & Complications","difficulty":"Moderate","source":"Gynecology","sourceNo":232,"q":"Complications of pre eclampsia are all except ?","o":["Post datism","DIC","Blindness","None of the above"],"a":0,"e":"Ans. A. Post datism","pyqMatches":[{"year":"2016","no":1500,"q":"Complications of pre eclampsia are all except ?","o":["Post datism","DIC","Blindness","None of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4136, 'OBG', 'Miscellaneous', 'Hard', 'Gynecology', 233, '{"id":4136,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Hard","source":"Gynecology","sourceNo":233,"q":"What is monitored in a patient of pre eclamsia ?","o":["Uric acid","Platelet count","LFT","All of the above"],"a":3,"e":"Ans. D. All of the above","pyqMatches":[{"year":"2016","no":1501,"q":"What is monitored in a patient of pre eclamsia ?","o":["Uric acid","Platelet count","LFT","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4137, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Gynecology', 234, '{"id":4137,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Gynecology","sourceNo":234,"q":"Not an absolute contraindication for methylergometrine use is ?","o":["Eclampsia","Heart disease","Rh incompatibility","After delivery of first baby in twin pregnancy"],"a":2,"e":"Ans. C. Rh incompatibility Methylergometrine (Methergin) can be used in the prevention and treatment of PPH. Absolute contraindications to the use of Methergin are:","pyqMatches":[{"year":"2016","no":1502,"q":"Not an absolute contraindication for methylergometrine use is ?","o":["Eclampsia","Heart disease","Rh incompatibility","After delivery of first baby in twin pregnancy"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4138, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Gynecology', 235, '{"id":4138,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Gynecology","sourceNo":235,"q":"A lady with 35 weeks of pregnancy is admitted in view of first episode of painless bout of bleeding yesterday. On examination Hb 10g%, BP 120/70 mmHg, uterus relaxed, and cephalic floating. FHS regular. Next line of management is ?","o":["Cesarean section","Induction of labor","Wait and watch","Blood transfusion"],"a":2,"e":"Ans. C. Wait and watch This is a case of placenta previa (painless bleeding, relaxed uterus, and floating head all point to placenta previa). In this case, all the criteria for conservative management are fulfilled and therefore the answer is wait and watch for fetal lung maturity.","pyqMatches":[{"year":"2016","no":1503,"q":"A lady with 35 weeks of pregnancy is admitted in view of first episode of painless bout of bleeding yesterday. On examination Hb 10g%, BP 120/70 mmHg, uterus relaxed, and cephalic floating. FHS regular. Next line of management is ?","o":["Cesarean section","Induction of labor","Wait and watch","Blood transfusion"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4139, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Gynecology', 236, '{"id":4139,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Gynecology","sourceNo":236,"q":"G3P2L2 with previous 2 LSCS with anterior placenta previa has got a very high risk of which complication?","o":["Placenta acreta","Vasa previa","Abruption","None of the above"],"a":0,"e":"Ans. A. Placenta acreta The term placenta accreta is used to describe any placental implantation in which there is abnormally firm adherence to the uterine wall. The incidence of placenta accreta, increta, and percreta has increased, most likely because of the increasedcesarean delivery rate.","pyqMatches":[{"year":"2016","no":1504,"q":"G3P2L2 with previous 2 LSCS with anterior placenta previa has got a very high risk of which complication?","o":["Placenta acreta","Vasa previa","Abruption","None of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4140, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 237, '{"id":4140,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":237,"q":"B-Lynch suture is applied on ?","o":["Cervix","Uterus","Fallopian tubes","Ovaries"],"a":1,"e":"Ans. B. Uterus Described first by Christopher, B-Lynch is a compression suture placed on uterus in the management of atonic PPH when the medical methods fail.","pyqMatches":[{"year":"2016","no":1505,"q":"B-Lynch suture is applied on ?","o":["Cervix","Uterus","Fallopian tubes","Ovaries"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4141, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Gynecology', 238, '{"id":4141,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Gynecology","sourceNo":238,"q":"A 28-year-old primigravida with 33 weeks of pregnancy suddenly complains of headache, oliguria, and blurred vision. Her BP is 180/110 and urine albumin is +3. The line of further management is ?","o":["Wait and watch","LSCS","Induction of labor","Anticonvulsant + antihypertensive therapy"],"a":3,"e":"Ans. D. Anticonvulsant + antihypertensive therapy The patie nt is a case of severe preeclampsia, with impending eclampsia. Magnesium sulfate is the drug of choice for eclampsia and also for impendingeclampsia.","pyqMatches":[{"year":"2016","no":1506,"q":"A 28-year-old primigravida with 33 weeks of pregnancy suddenly complains of headache, oliguria, and blurred vision. Her BP is 180/110 and urine albumin is +3. The line of further management is ?","o":["Wait and watch","LSCS","Induction of labor","Anticonvulsant + antihypertensive therapy"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4142, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 239, '{"id":4142,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":239,"q":"Which of the following statements concerning abdominal pregnancy is correct?","o":["Gastrointestinal symptoms are quite often very severe","Fetal survival is approximately 80%","Aggressive attempts should be made to remove the placenta at the time of initial surgery","Placenta can be left in situ at the time of surgery"],"a":3,"e":"Ans. D. Placenta can be left in situ at the time of surgery Although leaving the placenta in the abdomen following surgical delivery predisposes to riskesof postoperative infections, the risk is much less severe than the hemorrhage associated with attempts of removal of placenta at the time of primary surgery.","pyqMatches":[{"year":"2016","no":1507,"q":"Which of the following statements concerning abdominal pregnancy is correct?","o":["Gastrointestinal symptoms are quite often very severe","Fetal survival is approximately 80%","Aggressive attempts should be made to remove the placenta at the time of initial surgery","Placenta can be left in situ at the time of surgery"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4143, 'OBG', 'Miscellaneous', 'Hard', 'Gynecology', 240, '{"id":4143,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Hard","source":"Gynecology","sourceNo":240,"q":"Complete vesicular mole is associated Theca leutin csyts in what percentage of cases ?","o":["<5","5-15","20-40","60-70"],"a":2,"e":"Ans. C. 20-40 Theca-lutein cysts: In many cases of hydatidiform mole, the ovaries contain multiple theca-lutein cysts.","pyqMatches":[{"year":"2016","no":1508,"q":"Complete vesicular mole is associated Theca leutin csyts in what percentage of cases ?","o":["<5","5-15","20-40","60-70"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4144, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Gynecology', 241, '{"id":4144,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Gynecology","sourceNo":241,"q":"Patient with 3 months amenorrhoea, c/o hyperemesis and vaginal bleeding since one month. O/E=uterus 16 weeks with absent fetal heart sound. The diagnosis is ?","o":["Vesicular mole","Ectopic pregnancy","IUFD","Abruptio placentae"],"a":0,"e":"Ans. A. Vesicular mole Vesicular mole is an abnormal condition of placenta where there is hydropic degeneration and proliferative changes in the young chorionic villi. It is a benign condition with malignant potential. Uterine bleeding is almost universal and may vary from spotting to profuse hemorrhage. It is the MC presenting feature. The discharge has'' white currant in red currant juice'' appearance.","pyqMatches":[{"year":"2016","no":1509,"q":"Patient with 3 months amenorrhoea, c/o hyperemesis and vaginal bleeding since one month. O/E=uterus 16 weeks with absent fetal heart sound. The diagnosis is ?","o":["Vesicular mole","Ectopic pregnancy","IUFD","Abruptio placentae"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4145, 'OBG', 'Miscellaneous', 'Hard', 'Gynecology', 242, '{"id":4145,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Hard","source":"Gynecology","sourceNo":242,"q":"Patient with choriocarcinoma & jaundice, treatment of choice is ?","o":["Methotreaxate","Actinomycin D","Suction evacuation","Combination of all"],"a":1,"e":"Ans. B. Actinomycin D","pyqMatches":[{"year":"2016","no":1510,"q":"Patient with choriocarcinoma & jaundice, treatment of choice is ?","o":["Methotreaxate","Actinomycin D","Suction evacuation","Combination of all"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4146, 'OBG', 'Labour & Delivery', 'Easy', 'Gynecology', 243, '{"id":4146,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Gynecology","sourceNo":243,"q":"EMACO regime is for ?","o":["Ca cervix","Ca endometrium","Ca ovary","Chorio carcinoma"],"a":3,"e":"Ans. D. Chorio carcinoma","pyqMatches":[{"year":"2016","no":1511,"q":"EMACO regime is for ?","o":["Ca cervix","Ca endometrium","Ca ovary","Chorio carcinoma"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4147, 'OBG', 'Gynecologic Oncology', 'Hard', 'Gynecology', 244, '{"id":4147,"subject":"OBG","chapter":"Gynecologic Oncology","difficulty":"Hard","source":"Gynecology","sourceNo":244,"q":"Stage lb cervical cancer is diagnosed in a young woman. Assuming that the cancer is confirmed to the cervix and that intraoperative biopsies are negative, which of the following structure would not be removed during the radical hysterectomy?","o":["Uterosacral and uterovesical ligaments","Pelvic nodes","The entire parametrium on both sides of the cervix","Both ovaries"],"a":3,"e":"Ans. D. Both ovaries Preservation of the ovaries is generally acceptable, particularly in younger women.","pyqMatches":[{"year":"2016","no":1512,"q":"Stage lb cervical cancer is diagnosed in a young woman. Assuming that the cancer is confirmed to the cervix and that intraoperative biopsies are negative, which of the following structure would not be removed during the radical hysterectomy?","o":["Uterosacral and uterovesical ligaments","Pelvic nodes","The entire parametrium on both sides of the cervix","Both ovaries"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4148, 'OBG', 'Benign Gynecology', 'Easy', 'Gynecology', 245, '{"id":4148,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Easy","source":"Gynecology","sourceNo":245,"q":"In vaginal hysterectomy, the first clamp includes:","o":["Uterine artery","Fallopian tube & round ligament","Uterosacral ligament","None of the above"],"a":2,"e":"Ans. C. Uterosacral ligament Vaginal hysterectomy with pelvic floor repair is done for vaginouterine prolapse in peri/post menopausal women. First clamp includes uteroscaral&Macenrodt''s ligament. Second clamp includes uterine artery. Third clamp includes cornual structures.","pyqMatches":[{"year":"2016","no":1513,"q":"In vaginal hysterectomy, the first clamp includes:","o":["Uterine artery","Fallopian tube & round ligament","Uterosacral ligament","None of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4149, 'OBG', 'Labour & Delivery', 'Easy', 'Gynecology', 246, '{"id":4149,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Gynecology","sourceNo":246,"q":"Therapeutic conization is indicated in?","o":["Microinvasive carcinoma cervix stage lal","CIN III","Unsatisfactory colposcopy with cervical dysplasia","Cervical metaplasia"],"a":0,"e":"Ans. A. Microinvasive carcinoma cervix stage lal In stage 1A1, there is no lymph node involvement. Therapeutic conization is the surgery of choice for stage 1A1 in young patients who are desirous of future childbearing","pyqMatches":[{"year":"2016","no":1514,"q":"Therapeutic conization is indicated in?","o":["Microinvasive carcinoma cervix stage lal","CIN III","Unsatisfactory colposcopy with cervical dysplasia","Cervical metaplasia"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4150, 'OBG', 'Gynecologic Oncology', 'Easy', 'Gynecology', 247, '{"id":4150,"subject":"OBG","chapter":"Gynecologic Oncology","difficulty":"Easy","source":"Gynecology","sourceNo":247,"q":"Cervical cancer III B treatment is ?","o":["Wertheim''s operation","Radiotherapy","Chemotherapy","Chemoradiation"],"a":3,"e":"Ans. D. Chemoradiation Cisplatin is given before RT as a radiosensltizer, hence the preferred terminology is CTRT (concurrent chemo and radiotherapy also known as chemoradiation).","pyqMatches":[{"year":"2016","no":1515,"q":"Cervical cancer III B treatment is ?","o":["Wertheim''s operation","Radiotherapy","Chemotherapy","Chemoradiation"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4151, 'OBG', 'Gynecologic Oncology', 'Easy', 'Gynecology', 248, '{"id":4151,"subject":"OBG","chapter":"Gynecologic Oncology","difficulty":"Easy","source":"Gynecology","sourceNo":248,"q":"Wertheim''s hysterectomy is done for ?","o":["1A1 cervical cancer","IB cervical cancer","Germ cell ovarian cancer","All of the above"],"a":1,"e":"Ans. B. IB cervical cancer Stages of Ca cervix that are operable (radical/Wertheim''s hysterectomy) are 1A2, IB, and IIA.","pyqMatches":[{"year":"2016","no":1516,"q":"Wertheim''s hysterectomy is done for ?","o":["1A1 cervical cancer","IB cervical cancer","Germ cell ovarian cancer","All of the above"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4152, 'OBG', 'Labour & Delivery', 'Easy', 'Gynecology', 249, '{"id":4152,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Gynecology","sourceNo":249,"q":"Radio isotope used in Ca cervix Brachytherapy ?","o":["Cobalt","Iridium","Cesium","All of the above"],"a":3,"e":"Ans. D. All of the above","pyqMatches":[{"year":"2016","no":1517,"q":"Radio isotope used in Ca cervix Brachytherapy ?","o":["Cobalt","Iridium","Cesium","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4153, 'OBG', 'Miscellaneous', 'Moderate', 'Gynecology', 250, '{"id":4153,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Gynecology","sourceNo":250,"q":"Ca vulva spreads to all except ?","o":["Urethra","Deep inguinal nodes","Superficial inguinal nodes","Paraaortic nodes"],"a":3,"e":"Ans. D. Paraaortic nodes Modes of spread of ca. vulva","pyqMatches":[{"year":"2016","no":1518,"q":"Ca vulva spreads to all except ?","o":["Urethra","Deep inguinal nodes","Superficial inguinal nodes","Paraaortic nodes"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4154, 'OBG', 'Gynecologic Oncology', 'Easy', 'Gynecology', 251, '{"id":4154,"subject":"OBG","chapter":"Gynecologic Oncology","difficulty":"Easy","source":"Gynecology","sourceNo":251,"q":"Which ovarian tumour can present with menorrhagia ?","o":["Demoid cyst","Epithelial ovarian cancer","Granulosa cell tumour","Yolk sac tumour"],"a":2,"e":"Ans. C. Granulosa cell tumour Granulosa cell tumours (or granulosa-theca cell tumours) are tumours that arise fromgranulosa cells. These tumoursare part of the sex cordgonadal stromal tumour or non-epithelial group of tumours.","pyqMatches":[{"year":"2016","no":1519,"q":"Which ovarian tumour can present with menorrhagia ?","o":["Demoid cyst","Epithelial ovarian cancer","Granulosa cell tumour","Yolk sac tumour"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4155, 'OBG', 'Abortion & Ectopic Pregnancy', 'Moderate', 'Gynecology', 252, '{"id":4155,"subject":"OBG","chapter":"Abortion & Ectopic Pregnancy","difficulty":"Moderate","source":"Gynecology","sourceNo":252,"q":"All are risk factors for ectopic pregnancy except ?","o":["Past history","Tubal ligation failure","IVF","LNG IUCD"],"a":3,"e":"Ans. D. LNG IUCD IUCD: The modern copper IIJD does not increase the rkk of ectopic pregnancy. However, there is a relative increase in tubal pregnancy (7 times more) should pregnancy occur with IUCD in situ. Studies have demonstrated that up to l% of pregnancies achieved through IVF or GIFT can result in a heterotopic gestation.","pyqMatches":[{"year":"2016","no":1520,"q":"All are risk factors for ectopic pregnancy except ?","o":["Past history","Tubal ligation failure","IVF","LNG IUCD"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4156, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Gynecology', 253, '{"id":4156,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Gynecology","sourceNo":253,"q":"A 21-year-old female presents to emergency ward with 2 months of amenorrhea with pain in abdomen and shock. BP 90/60 mmHg and Hb 6 gm%. Urine pregnancy test is found positive. Next immediate line of treatment is ?","o":["Laparotomy","IV fluids & cross match","Medical management","Laparoscopy"],"a":1,"e":"Ans. B. IV fluids & cross match This is a case of ruptured ectopic pregnancy. Positive Urine Pregnancy Test indicates that the amenorrhea is due to pregnancy. Pain and shock in early pregnancy are mostly always due to ruptured ectopic.","pyqMatches":[{"year":"2016","no":1521,"q":"A 21-year-old female presents to emergency ward with 2 months of amenorrhea with pain in abdomen and shock. BP 90/60 mmHg and Hb 6 gm%. Urine pregnancy test is found positive. Next immediate line of treatment is ?","o":["Laparotomy","IV fluids & cross match","Medical management","Laparoscopy"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4157, 'OBG', 'Abortion & Ectopic Pregnancy', 'Hard', 'Gynecology', 254, '{"id":4157,"subject":"OBG","chapter":"Abortion & Ectopic Pregnancy","difficulty":"Hard","source":"Gynecology","sourceNo":254,"q":"DOC for medical management of ectopic pegnancy ?","o":["Actinomycin D","Intramuscular Methotrexate","Intramuscular Methotrexate","PGf2 alpha"],"a":1,"e":"Ans. B. Intramuscular Methotrexate","pyqMatches":[{"year":"2016","no":1522,"q":"DOC for medical management of ectopic pegnancy ?","o":["Actinomycin D","Intramuscular Methotrexate","Intramuscular Methotrexate","PGf2 alpha"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4158, 'OBG', 'Infertility & Reproductive Endocrinology', 'Moderate', 'Gynecology', 255, '{"id":4158,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Moderate","source":"Gynecology","sourceNo":255,"q":"What is not used in PCOS ?","o":["OC pills","Cyclical progesterones","Myoinositol","Danazol"],"a":3,"e":"Ans. D. Danazol Insulin sensitizers are also used to tackle insulin resisitance. Danazol has no role in PCOS.","pyqMatches":[{"year":"2016","no":1523,"q":"What is not used in PCOS ?","o":["OC pills","Cyclical progesterones","Myoinositol","Danazol"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4159, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 256, '{"id":4159,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":256,"q":"Pearl necklace appearance is characteristic of ?","o":["Ectopic pregnancy","PCOS","Endometriosis","PID"],"a":1,"e":"Ans. B. PCOS USG features of polycystic ovarian syndrome (PCOS) Greater than 12 follicles measuring between 2 mm and 9 mm in diameter located peripherally, resulting in a pearl necklace appearance. Increased echogenicity of ovarianstroma and /or ovarian volume greater than 10 ml.","pyqMatches":[{"year":"2016","no":1524,"q":"Pearl necklace appearance is characteristic of ?","o":["Ectopic pregnancy","PCOS","Endometriosis","PID"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4160, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 257, '{"id":4160,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":257,"q":"Violin string adhesion [violent string sign] is seen in ?","o":["PCOS","Endometriosis","Fitz - high -curtis syndrome","Ruptured ectopic pregnancy"],"a":2,"e":"Ans. C. Fitz - high -curtis syndrome Laparoscopy is performed, the liver capsule will appear inflamed, with classic violin string adhesions in the perietal peritoneum beneath the diaphragm. Five percent to 10% of women with acute PID develop symptoms of perihepatic inflammation, the Fitz-High-Curtis syndrome.","pyqMatches":[{"year":"2016","no":1525,"q":"Violin string adhesion [violent string sign] is seen in ?","o":["PCOS","Endometriosis","Fitz - high -curtis syndrome","Ruptured ectopic pregnancy"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4161, 'OBG', 'Gynecologic Oncology', 'Easy', 'Gynecology', 258, '{"id":4161,"subject":"OBG","chapter":"Gynecologic Oncology","difficulty":"Easy","source":"Gynecology","sourceNo":258,"q":"Dysgerminoma spreads mainly via ?","o":["Hematogenous route","Lymphatic route","Direct spread","Does not spread"],"a":1,"e":"Ans. B. Lymphatic route Dysgerminomas are the most common malignant germ cell tumors, accounting for about 30% to 40% of all ovarian cancers of germ cell origin. In the 25% of patients who present with metastatic disease, the tumor most commonly spreads via the lymphatics.","pyqMatches":[{"year":"2016","no":1526,"q":"Dysgerminoma spreads mainly via ?","o":["Hematogenous route","Lymphatic route","Direct spread","Does not spread"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4162, 'OBG', 'Benign Gynecology', 'Moderate', 'Gynecology', 259, '{"id":4162,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Moderate","source":"Gynecology","sourceNo":259,"q":"Triad of symptoms of endometriosis are all except ?","o":["Infertility","Dysmenorrhea","Dyspareunia","Cyclical hematuria"],"a":3,"e":"Ans. D. Cyclical hematuria Endometriosis is defined as the presence of normal functional endometrial mucosa (glands and stroma) abnormally implanted in locations other than the uterine cavity. It was first described by Von Rokitansky About one third of women with endometriosis remain asymptomatic.","pyqMatches":[{"year":"2016","no":1527,"q":"Triad of symptoms of endometriosis are all except ?","o":["Infertility","Dysmenorrhea","Dyspareunia","Cyclical hematuria"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4163, 'OBG', 'Benign Gynecology', 'Easy', 'Gynecology', 260, '{"id":4163,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Easy","source":"Gynecology","sourceNo":260,"q":"Complication of Benign Ovarian Cysts is ?","o":["Torsion","Intracystic hemorrhage","Pseudomyxoma perotonei","All of the above"],"a":3,"e":"Ans. D. All of the above","pyqMatches":[{"year":"2016","no":1528,"q":"Complication of Benign Ovarian Cysts is ?","o":["Torsion","Intracystic hemorrhage","Pseudomyxoma perotonei","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4164, 'OBG', 'Benign Gynecology', 'Easy', 'Gynecology', 261, '{"id":4164,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Easy","source":"Gynecology","sourceNo":261,"q":"Level 1 support of uterus & vagina is ?","o":["levator ani","Perineal body","Uterosacral ligaments","All of the above"],"a":2,"e":"Ans. C. Uterosacral ligaments Delancey’s three levels of pelvic (uterus, vagina) support= Level 1: The uterosacral-cardinal ligament complex provides attachment of the uterus and vaginal vault to the sacrum. Uterine prolapse occurs when this ligament complex breaks or is attenuated.","pyqMatches":[{"year":"2016","no":1529,"q":"Level 1 support of uterus & vagina is ?","o":["levator ani","Perineal body","Uterosacral ligaments","All of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4165, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Gynecology', 262, '{"id":4165,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Gynecology","sourceNo":262,"q":"MC presenting symptom of fibroid is ?","o":["Menorrhagia","Infertility","Lump","Compression"],"a":0,"e":"Ans. A. Menorrhagia","pyqMatches":[{"year":"2016","no":1530,"q":"MC presenting symptom of fibroid is ?","o":["Menorrhagia","Infertility","Lump","Compression"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4166, 'OBG', 'Benign Gynecology', 'Hard', 'Gynecology', 263, '{"id":4166,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Hard","source":"Gynecology","sourceNo":263,"q":"Medical management of fibroids is with all except -","o":["Progesterone","Mifepristone","Ulipristal acetate","Misoprostol"],"a":3,"e":"Ans. D. Misoprostol","pyqMatches":[{"year":"2016","no":1531,"q":"Medical management of fibroids is with all except","o":["Progesterone","Mifepristone","Ulipristal acetate","Misoprostol"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4167, 'OBG', 'Benign Gynecology', 'Easy', 'Gynecology', 264, '{"id":4167,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Easy","source":"Gynecology","sourceNo":264,"q":"Endometriosis is ?","o":["Endometrium within the myometrium","Functional endometrium outside the uterus","Myometrium within the endometrium","Rare squamous variety of CA endometrium"],"a":1,"e":"Ans. B. Functional endometrium outside the uterus Endometriosis Definition: Presence of functional endometrium at places other than uterus (ectopic endometrial tissue)","pyqMatches":[{"year":"2016","no":1532,"q":"Endometriosis is ?","o":["Endometrium within the myometrium","Functional endometrium outside the uterus","Myometrium within the endometrium","Rare squamous variety of CA endometrium"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4168, 'OBG', 'Benign Gynecology', 'Easy', 'Gynecology', 265, '{"id":4168,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Easy","source":"Gynecology","sourceNo":265,"q":"Samson''s theory for Development of Endometriosis is ?","o":["Celomic metaplasia","Hematogenous spread","Lymphatic spread","Retrograde menstruation"],"a":3,"e":"Ans. D. Retrograde menstruation Theories for Development of Endometriosis","pyqMatches":[{"year":"2016","no":1533,"q":"Samson''s theory for Development of Endometriosis is ?","o":["Celomic metaplasia","Hematogenous spread","Lymphatic spread","Retrograde menstruation"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4169, 'OBG', 'Benign Gynecology', 'Hard', 'Gynecology', 266, '{"id":4169,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Hard","source":"Gynecology","sourceNo":266,"q":"Examination of a 26 years old obese infertile female reveals. Fixed retroverted uterus & Nodularity of the uterosacral ligaments. The most likely diagnosis is ?","o":["PCOS","Endometriosis","Adenomyosis","TB"],"a":1,"e":"Ans. B. Endometriosis Pelvic examination of endometriosis: May be normal or may reveal the following: Fixed retroverted uterus Pelvic tenderness Nodules in the POD Nodularity of the uterosaoal ligaments Unilateral or bilateral adnexal mass Speculum examination may reveal bluish nodules in posterior fornix.","pyqMatches":[{"year":"2016","no":1534,"q":"Examination of a 26 years old obese infertile female reveals. Fixed retroverted uterus & Nodularity of the uterosacral ligaments. The most likely diagnosis is ?","o":["PCOS","Endometriosis","Adenomyosis","TB"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4170, 'OBG', 'Benign Gynecology', 'Easy', 'Gynecology', 267, '{"id":4170,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Easy","source":"Gynecology","sourceNo":267,"q":"Investigation of choice for endometriosis ?","o":["USG","CA 125","MRI","Laparoscopy"],"a":3,"e":"Ans. D. Laparoscopy Laparoscopy is the Investigation ofChoice.","pyqMatches":[{"year":"2016","no":1535,"q":"Investigation of choice for endometriosis ?","o":["USG","CA 125","MRI","Laparoscopy"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4171, 'OBG', 'Benign Gynecology', 'Easy', 'Gynecology', 268, '{"id":4171,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Easy","source":"Gynecology","sourceNo":268,"q":"Powder burnt lesion seen in ?","o":["PID","PCOS","Endometriosis","All of the above"],"a":2,"e":"Ans. C. Endometriosis Laparoscopy findings in endometriosis are: Chocolate cysts Blueberrylesion Red/flame lesion Powder burn sPots Red/purple raspberry lesion Subovarian adhesions Matchstick burnt sPots White lesion.","pyqMatches":[{"year":"2016","no":1536,"q":"Powder burnt lesion seen in ?","o":["PID","PCOS","Endometriosis","All of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4172, 'OBG', 'Infertility & Reproductive Endocrinology', 'Hard', 'Gynecology', 269, '{"id":4172,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Hard","source":"Gynecology","sourceNo":269,"q":"Treatment of choice in patient with infertility & endometriosis ?","o":["IUI","Surgery","Danozol","Ovulation induction"],"a":1,"e":"Ans. B. Surgery Surgical Management","pyqMatches":[{"year":"2016","no":1537,"q":"Treatment of choice in patient with infertility & endometriosis ?","o":["IUI","Surgery","Danozol","Ovulation induction"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4173, 'OBG', 'Benign Gynecology', 'Easy', 'Gynecology', 270, '{"id":4173,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Easy","source":"Gynecology","sourceNo":270,"q":"Surgery of choice in 42 year old P3L3 with diffuse endometriosis is ?","o":["Ovarian cystectomy & adhesiolysis","Hysterectomy","Hysterectomy with BSO with resection of endometrial implants","Ovarian cystectomy & adhesiolysis & resection of implants"],"a":2,"e":"Ans. C. Hysterectomy with BSO with resection of endometrial implants If the family k complete and the patient has severe pain or menstrual complaints: Hystetectomy with bilateralsalpingo- oophorectomy with resection of all endometriotic implants.","pyqMatches":[{"year":"2016","no":1538,"q":"Surgery of choice in 42 year old P3L3 with diffuse endometriosis is ?","o":["Ovarian cystectomy & adhesiolysis","Hysterectomy","Hysterectomy with BSO with resection of endometrial implants","Ovarian cystectomy & adhesiolysis & resection of implants"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4174, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 271, '{"id":4174,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":271,"q":"The most common Mullerian anomaly is?","o":["Mullerian agenesis (RMKH)","Unicornuate uterus","Bicornuate uterus","Septate uterus"],"a":3,"e":"Ans. D. Septate uterus Septate uterus is the MC Mullerian anomaly.","pyqMatches":[{"year":"2016","no":1539,"q":"The most common Mullerian anomaly is?","o":["Mullerian agenesis (RMKH)","Unicornuate uterus","Bicornuate uterus","Septate uterus"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4175, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 272, '{"id":4175,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":272,"q":"SEAM used in DUB is ?","o":["Clomiphene","Raloxifene","Ormiloxifene","Mifepristone"],"a":2,"e":"Ans., C. Ormiloxifene Ormeloxifene is a third generation benzopyran SERM which blocks the cytosol receptors by its competitive binding and selectively acts on estrogen recePtors as agonist and antagonist in different reproductive tissues.","pyqMatches":[{"year":"2016","no":1540,"q":"SEAM used in DUB is ?","o":["Clomiphene","Raloxifene","Ormiloxifene","Mifepristone"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4176, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 273, '{"id":4176,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":273,"q":"Choice of adjuvant treatment for endometrial carcinoma stage IA, grade I is?","o":["Radiotherapy","Chemotherapy","Chemotherapy plus radiotherapy","No treatment"],"a":3,"e":"Ans. D. No treatment Management of Ca endometrium A) Stage l=1: Surgery (total abdominal hysterectomy with bilateral salpingo- oophorectomy with lymph node sampling), followed by radiotherapy. Only patients with stage 1A, grades 1 and 2 do not require postoperative radiotherapy. B) Stage 2: Modified radical hysterectomy, bilateral salpingo-oophorectomy with lymph node dissection, followed by radiotherapy. C) Stages 3 and 4: Debulking surgery followed by radiotherapy.","pyqMatches":[{"year":"2016","no":1541,"q":"Choice of adjuvant treatment for endometrial carcinoma stage IA, grade I is?","o":["Radiotherapy","Chemotherapy","Chemotherapy plus radiotherapy","No treatment"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4177, 'OBG', 'Miscellaneous', 'Hard', 'Gynecology', 274, '{"id":4177,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Hard","source":"Gynecology","sourceNo":274,"q":"A 46-year-old P3L3 complains of menorrhagia since 3 months. Next line of management is ?","o":["D & C","Progesterone x 6 months","OC pills x 6 months","Hysterectomy"],"a":0,"e":"Ans. A. D & C In Patients with menorrhagia in perimenopausal age group (40+), always make the diagnosis first before proceeding with any treatment. It is necessary to rule out endometrial hyperplasia and cancer in this age group. Hence, histopathological examination of endometrium is required, and therefore D 6C should be done first.","pyqMatches":[{"year":"2016","no":1542,"q":"A 46-year-old P3L3 complains of menorrhagia since 3 months. Next line of management is ?","o":["D & C","Progesterone x 6 months","OC pills x 6 months","Hysterectomy"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4178, 'OBG', 'Miscellaneous', 'Hard', 'Gynecology', 275, '{"id":4178,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Hard","source":"Gynecology","sourceNo":275,"q":"Simple hyperplasia with atypia will progress to ca endometrium in % of cases ?","o":["1-2","3-4","8-9","20"],"a":2,"e":"Ans. C. 8-9","pyqMatches":[{"year":"2016","no":1543,"q":"Simple hyperplasia with atypia will progress to ca endometrium in % of cases ?","o":["1-2","3-4","8-9","20"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4179, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 276, '{"id":4179,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":276,"q":"Grade 1 Ca endometrium, there is presence of % non sqoumaous growth ?","o":["<5","6-25","25-50",">50"],"a":0,"e":"Ans. A. <5 FIGO Grading of Endometrial Carcinoma Histopathologic degree of differentiation: Gl: < 5% nonsquamous or nonmorular growth pattern.","pyqMatches":[{"year":"2016","no":1544,"q":"Grade 1 Ca endometrium, there is presence of % non sqoumaous growth ?","o":["<5","6-25","25-50",">50"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4180, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 277, '{"id":4180,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":277,"q":"Definitive treatment of adenomyosis is ?","o":["OC pills","NSAIDS","Endometrial ablation","Hysterectomy"],"a":3,"e":"Ans, D. Hysterectomy Hysterectomy The only way to completely cure this condition is to have a hysterectomy.","pyqMatches":[{"year":"2016","no":1545,"q":"Definitive treatment of adenomyosis is ?","o":["OC pills","NSAIDS","Endometrial ablation","Hysterectomy"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4181, 'OBG', 'Benign Gynecology', 'Easy', 'Gynecology', 278, '{"id":4181,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Easy","source":"Gynecology","sourceNo":278,"q":"MC cause for hysterectomy is ?","o":["Prolapse","Fibroids","Ca endometrium","Acute PID"],"a":1,"e":"Ans. B. Fibroids A hysterectomy is an operation to remove the uterus. A woman may have a hysterectomy for different reasons, including: Uterine fibroids that cause pain, bleeding, or other problems.","pyqMatches":[{"year":"2016","no":1546,"q":"MC cause for hysterectomy is ?","o":["Prolapse","Fibroids","Ca endometrium","Acute PID"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4182, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 279, '{"id":4182,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":279,"q":"Prolonged surgery time of vaginal hysterectomy would lead to damage to which nerve ?","o":["Obturator","Pudendal","Peroneal","Sural"],"a":2,"e":"Ans. C. Peroneal Most commonly injured lower extremity nerve in patients undergoing surgery in lithotomy position is the common paroneal nerve(LA-S2).","pyqMatches":[{"year":"2016","no":1547,"q":"Prolonged surgery time of vaginal hysterectomy would lead to damage to which nerve ?","o":["Obturator","Pudendal","Peroneal","Sural"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4183, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Gynecology', 280, '{"id":4183,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Gynecology","sourceNo":280,"q":"Which of the following is not a part of PID -","o":["Endometritis","Cervicitis","Tuboovarian abcess","Peritonitis"],"a":1,"e":"Ans. B. Cervicitis PID is a spectrum of infection & inflammation of upper genital tract organs involving uterus, fallopian tubes, ovaries, pelvic peritoneum&parametrium. Cervicitis is not included.","pyqMatches":[{"year":"2016","no":1548,"q":"Which of the following is not a part of PID","o":["Endometritis","Cervicitis","Tuboovarian abcess","Peritonitis"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4184, 'OBG', 'Miscellaneous', 'Hard', 'Gynecology', 281, '{"id":4184,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Hard","source":"Gynecology","sourceNo":281,"q":"Triad for clinical diagnosis PID includes all except ?","o":["Fever","Lower abdominal pain","Cervical motion tenderness","Bilateral adnexal tenderness"],"a":0,"e":"Ans. A. Fever Diagrosis ofPID is often difficult. The \"gold standard\" for diagnosis relies on the laparoscopic appearance ofFallopian tube inflammation but cost and limited availability of the technique often preclude its use. In theabsence of laparoscopy, the triad of lower abdominal pain, cervical motion tenderness, and bilateral adnexal tenderness has been advocated as the minimal criterion for clinical diagnosis of PID.","pyqMatches":[{"year":"2016","no":1549,"q":"Triad for clinical diagnosis PID includes all except ?","o":["Fever","Lower abdominal pain","Cervical motion tenderness","Bilateral adnexal tenderness"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4185, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 282, '{"id":4185,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":282,"q":"Acute salpingitis is most commonly caused by ?","o":["N. gonorrhoeae","Chlamydia trachomatis","Mycoplasma","Staphylococcus"],"a":1,"e":"Ans, B. Chlamydia trachomatis Option B is now a days slightly more commoner than option a) & hence the best option to mark If polymicrobial/mixed infection, is in the option, then that is the answer.","pyqMatches":[{"year":"2016","no":1550,"q":"Acute salpingitis is most commonly caused by ?","o":["N. gonorrhoeae","Chlamydia trachomatis","Mycoplasma","Staphylococcus"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4186, 'OBG', 'Gynecologic Oncology', 'Moderate', 'Gynecology', 283, '{"id":4186,"subject":"OBG","chapter":"Gynecologic Oncology","difficulty":"Moderate","source":"Gynecology","sourceNo":283,"q":"Tumor marker for germ cell malignancy are all except?","o":["LDH","Alkaline phosphatase","AFP","CA-125"],"a":3,"e":"Ans. D. CA-125","pyqMatches":[{"year":"2016","no":1551,"q":"Tumor marker for germ cell malignancy are all except?","o":["LDH","Alkaline phosphatase","AFP","CA-125"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4187, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 284, '{"id":4187,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":284,"q":"Acute pelvic pain could be due to ?","o":["Ectopic pregnancy","PID","Corpus luteum hematoma","All of the above"],"a":3,"e":"Ans. D. All of the above","pyqMatches":[{"year":"2016","no":1552,"q":"Acute pelvic pain could be due to ?","o":["Ectopic pregnancy","PID","Corpus luteum hematoma","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4188, 'OBG', 'Miscellaneous', 'Moderate', 'Gynecology', 285, '{"id":4188,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Gynecology","sourceNo":285,"q":"Nugent score includes all except -","o":["Lactobacillus","Gardnerella","Mobiluncus","Gonococcus"],"a":3,"e":"Ans. D. Gonococcus Nugent''s criteria for diagnosis ofbacterial vaginosis Many use Nugent''s criteria to quantify or grade bacteria via Gram stain of vaginal samples. In brief, Nugent''s criteria evaluated 3 types of bacteria via Gram stain: Lactobacillus, Bacteroides/ Gardnerella, and Mobiluncus.","pyqMatches":[{"year":"2016","no":1553,"q":"Nugent score includes all except","o":["Lactobacillus","Gardnerella","Mobiluncus","Gonococcus"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4189, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 286, '{"id":4189,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":286,"q":"Clue cells are seen in?","o":["Bacterial vaginosis","Candidiasis","Chlamydiasis","Trichomoniasis"],"a":0,"e":"Ans. A. Bacterial vaginosis Bacterial vaginosis/vaginitis (BV) is a common vaginal infection. Clue cells (vaginal epithelial cells covered with coccobacilli and the cells appear as stippled or granular). CIue cells are diagnostic ofBV.","pyqMatches":[{"year":"2016","no":1554,"q":"Clue cells are seen in?","o":["Bacterial vaginosis","Candidiasis","Chlamydiasis","Trichomoniasis"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4190, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 287, '{"id":4190,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":287,"q":"HSG findings suggestive of genital koch ?","o":["Beaded tubes","Honeycomb uterus","Golf club tube","All of the above"],"a":3,"e":"Ans. D. All of the above In active tuberculosis, HSG is contraindicated.","pyqMatches":[{"year":"2016","no":1555,"q":"HSG findings suggestive of genital koch ?","o":["Beaded tubes","Honeycomb uterus","Golf club tube","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4191, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Gynecology', 288, '{"id":4191,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Gynecology","sourceNo":288,"q":"A pregnant lady presents with genital warts. The best management for her is ?","o":["Imiquimod","Trichloroacetic acid","Podophyllin","Cryotherapy"],"a":3,"e":"Ans,. D. Cryotherapy For reasons unknown genital warts increase in size and number during pregnancy. Treatment options during pregnancy include cryotherapy and trichloroacetic acid (TCA). Out of the two, cryosurgery is more effective than TCA and hence is prefnred.","pyqMatches":[{"year":"2016","no":1556,"q":"A pregnant lady presents with genital warts. The best management for her is ?","o":["Imiquimod","Trichloroacetic acid","Podophyllin","Cryotherapy"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4192, 'OBG', 'Miscellaneous', 'Hard', 'Gynecology', 289, '{"id":4192,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Hard","source":"Gynecology","sourceNo":289,"q":"28 year old female complaints of foul smelling yellowish urethral discharge since 4 days. History of burning micturation. History of sexual contact with multiple partners 2 days before the onset of symptoms. Most likely diagnosis is ?","o":["Syphilis","Chancroid","Gonococcal urethritis","Non-infective urethritis"],"a":2,"e":"Ans. C. Gonococcal urethritis History of foul smelling mucopurulent discharge , & short incubation period with high risk exposure clinches the diagnosis","pyqMatches":[{"year":"2016","no":1557,"q":"28 year old female complaints of foul smelling yellowish urethral discharge since 4 days. History of burning micturation. History of sexual contact with multiple partners 2 days before the onset of symptoms. Most likely diagnosis is ?","o":["Syphilis","Chancroid","Gonococcal urethritis","Non-infective urethritis"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4193, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 290, '{"id":4193,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":290,"q":"Twin-peak sign is seen in ?","o":["All Monozygotic twins","Monochorionic twins","Dichorionic twins","Siamese twins"],"a":2,"e":"Ans. C. Dichorionic twins","pyqMatches":[{"year":"2016","no":1558,"q":"Twin-peak sign is seen in ?","o":["All Monozygotic twins","Monochorionic twins","Dichorionic twins","Siamese twins"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4194, 'OBG', 'Labour & Delivery', 'Easy', 'Gynecology', 291, '{"id":4194,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Gynecology","sourceNo":291,"q":"In ca Cervix treatment, point A receives ?","o":["3000 cGy","5000 cGy","7000 cGy","10,000 cGy"],"a":2,"e":"Ans. C. 7000 cGy Point A and Point B are in relation to radiotherapy for Ca Cervix.","pyqMatches":[{"year":"2016","no":1559,"q":"In ca Cervix treatment, point A receives ?","o":["3000 cGy","5000 cGy","7000 cGy","10,000 cGy"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4195, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Gynecology', 292, '{"id":4195,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Gynecology","sourceNo":292,"q":"Ashermans syndrome is characterized by ?","o":["Amenorrhea","Menorrhagia","Polymenorrhea","All of the above"],"a":0,"e":"Ans. A. Amenorrhea Intra-uterine adhesions Asherman syndrome was identified in 1948 as uterine synechiae. These intra-uterine adhesions (IUA) are often associated with amenorrhea or infertility.","pyqMatches":[{"year":"2016","no":1560,"q":"Ashermans syndrome is characterized by ?","o":["Amenorrhea","Menorrhagia","Polymenorrhea","All of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4196, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 293, '{"id":4196,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":293,"q":"GARDASIL vaccine is for -","o":["HPV 16,18","HSV","HPV 6,11,16,18","Hepatitis B"],"a":2,"e":"Ans. C. HPV 6,11,16,18","pyqMatches":[{"year":"2016","no":1561,"q":"GARDASIL vaccine is for","o":["HPV 16,18","HSV","HPV 6,11,16,18","Hepatitis B"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4197, 'OBG', 'Contraception & Family Planning', 'Easy', 'Gynecology', 294, '{"id":4197,"subject":"OBG","chapter":"Contraception & Family Planning","difficulty":"Easy","source":"Gynecology","sourceNo":294,"q":"LNG content of Mirena is -","o":["20 gms","20 mg","52 gms","52 mgs"],"a":3,"e":"Ans. D. 52 mgs Mirena/LNG IUD/LNG 2O/levonova/LNG IUS Mirenacontainsatotalof52mglevonorgestrel(LNG).LNGisreleasedintothe at a rate of approximtely20pg/day.","pyqMatches":[{"year":"2016","no":1562,"q":"LNG content of Mirena is","o":["20 gms","20 mg","52 gms","52 mgs"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4198, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 295, '{"id":4198,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":295,"q":"Which of the following decreases the risk of Pelvic Inflammatory Disease ?","o":["Cu T","Spermicidal agents","O.C. pills","Today vaginal sponge"],"a":2,"e":"Ans. C. O.C. pills Several studies have shown that regular O.C. pill users are protected from PIDs to the extent of 50%.","pyqMatches":[{"year":"2016","no":1563,"q":"Which of the following decreases the risk of Pelvic Inflammatory Disease ?","o":["Cu T","Spermicidal agents","O.C. pills","Today vaginal sponge"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4199, 'OBG', 'Miscellaneous', 'Hard', 'Gynecology', 296, '{"id":4199,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Hard","source":"Gynecology","sourceNo":296,"q":"Patient with 45 XO , what HRT to be given ?","o":["Growth hormone + E+P","Estrogene","No HRT Needed","HRT only after 45 years"],"a":0,"e":"Ans. A. Growth hormone + E+P Growth hormone (GH) therapy has become the standard of care for girls with turner syndrome and should be considered as soon as decreased linear growth velocity is apparent. Initial hormone replacement involves low dose estrogenmonotherapy. Progestagenreplacement is generally added 1-2 yearsafter starting estrogen or upon breakthrough bleeding.","pyqMatches":[{"year":"2016","no":1564,"q":"Patient with 45 XO , what HRT to be given ?","o":["Growth hormone + E+P","Estrogene","No HRT Needed","HRT only after 45 years"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4200, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 297, '{"id":4200,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":297,"q":"Tamoxifen decreases the risk of which cancer?","o":["Breast","Endometrium","Ovary","All of the above"],"a":0,"e":"Ans. A. Breast Tamoxifen has been used for more than 30 years to treat patients with breast cancer. Tamoxifenworks against breast cancer, in part, by interfering with the activity of estrogen, a female hormone that promotes the growth of breast cancer cells. In October 1998, the U.S. Food and Drug Administration (FDA) approved the use of tamoxifen to reduce the incidence of breast cancer in women at increased risk of the disease.","pyqMatches":[{"year":"2016","no":1565,"q":"Tamoxifen decreases the risk of which cancer?","o":["Breast","Endometrium","Ovary","All of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4201, 'OBG', 'Labour & Delivery', 'Easy', 'Gynecology', 298, '{"id":4201,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Gynecology","sourceNo":298,"q":"Raloxifene decreases the risk of which cancer?","o":["Breast","Cervix","Ovary","All of the above"],"a":0,"e":"Ans. A. Breast After an average of 81 months, raloxifene reduces risk of invasive breast cancer by about 38 percent compared to tamoxifenreducing breast cancer by about 50 percent.","pyqMatches":[{"year":"2016","no":1566,"q":"Raloxifene decreases the risk of which cancer?","o":["Breast","Cervix","Ovary","All of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4202, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 299, '{"id":4202,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":299,"q":"Least failure rate ?","o":["CuT","MIRENA","DMPA","O.C. PILLS"],"a":1,"e":"Ans. B. MIRENA","pyqMatches":[{"year":"2016","no":1567,"q":"Least failure rate ?","o":["CuT","MIRENA","DMPA","O.C. PILLS"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4203, 'OBG', 'Labour & Delivery', 'Easy', 'Gynecology', 300, '{"id":4203,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Gynecology","sourceNo":300,"q":"Nuva ring contains ?","o":["EE+ etonogestrel","LNG + EE","LNG","EE+ drosperinone"],"a":0,"e":"Ans. A. EE+ etonogestrel Contraceptive rings Nuva Ring: It is a soft vaginal ring that releases 15 microgram EE and 120 microgram ENG, etonogestrel,the active metabolite of desogestrel, per day as a controlled delivery system.","pyqMatches":[{"year":"2016","no":1568,"q":"Nuva ring contains ?","o":["EE+ etonogestrel","LNG + EE","LNG","EE+ drosperinone"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4204, 'OBG', 'Benign Gynecology', 'Moderate', 'Gynecology', 301, '{"id":4204,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Moderate","source":"Gynecology","sourceNo":301,"q":"Which drug used for endometriosis can cause increase in hepatic enzyme & adverse lipid profile -","o":["0. C. pills","GnRh analogues","Both of the above","None of the above"],"a":0,"e":"Ans. A. 0. C. pills O. C. pills (progesterone component) are a/w increase in LDL & decrease in HDL cholesterol but estrogens have opposite effect. Cholestasis &cholestatic jaundice are occasional side effects of O. C. pills.","pyqMatches":[{"year":"2016","no":1569,"q":"Which drug used for endometriosis can cause increase in hepatic enzyme & adverse lipid profile","o":["0. C. pills","GnRh analogues","Both of the above","None of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4205, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 302, '{"id":4205,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":302,"q":"Norgestimate in OC pills has the following advantage ?","o":["Reduces venous thrombosis","Is cheaper than standard OC pills","Reduces acne and hirsutism","Useful in heart disease"],"a":2,"e":"Ans. C. Reduces acne and hirsutism Three newer progestogens, namely desogestrel, gestodene, and norgestimatecan decrease the ameanilhirsutism as compared to olderprogesterones, which actually can cause oily skin and acne.","pyqMatches":[{"year":"2016","no":1570,"q":"Norgestimate in OC pills has the following advantage ?","o":["Reduces venous thrombosis","Is cheaper than standard OC pills","Reduces acne and hirsutism","Useful in heart disease"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4206, 'OBG', 'Miscellaneous', 'Moderate', 'Gynecology', 303, '{"id":4206,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Gynecology","sourceNo":303,"q":"Which of the following is not an ideal candidate for IUCD insertion ?","o":["Previous LSCS","Lactating mother","Acute PID","All of the above"],"a":2,"e":"Ans. C. Acute PID","pyqMatches":[{"year":"2016","no":1571,"q":"Which of the following is not an ideal candidate for IUCD insertion ?","o":["Previous LSCS","Lactating mother","Acute PID","All of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4207, 'OBG', 'Miscellaneous', 'Hard', 'Gynecology', 304, '{"id":4207,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Hard","source":"Gynecology","sourceNo":304,"q":"Betamethasone given to preterm patient for all except ?","o":["Fetal lung maturity","Decrease intraventricular hemorrhage","Prevents periventricular leukomalacia","Prevent PPH"],"a":3,"e":"Ans. D. Prevent PPH Steroids (dexamethasone or betamethasone) are given to enhance fetal lung maturity and they also decrease the incidence intraventricular hemorrhage.","pyqMatches":[{"year":"2016","no":1572,"q":"Betamethasone given to preterm patient for all except ?","o":["Fetal lung maturity","Decrease intraventricular hemorrhage","Prevents periventricular leukomalacia","Prevent PPH"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4208, 'OBG', 'Antenatal Care & Complications', 'Hard', 'Gynecology', 305, '{"id":4208,"subject":"OBG","chapter":"Antenatal Care & Complications","difficulty":"Hard","source":"Gynecology","sourceNo":305,"q":"A 32-year-old female with mild hypertension. Two days after normal delivery, she develop seizures, headache. No proteinuria was there. On imaging she was found to have parasagittal infarction and hematoma 3x2cm.The most probable cause is?","o":["Eclampsia","Superior sagittal sinus thrombosis","Pituitary apoplexy","Subarachnoid hemorrhage"],"a":1,"e":"Ans. B. Superior sagittal sinus thrombosis The various etiologies for dural sinus thrombosis are:","pyqMatches":[{"year":"2016","no":1573,"q":"A 32-year-old female with mild hypertension. Two days after normal delivery, she develop seizures, headache. No proteinuria was there. On imaging she was found to have parasagittal infarction and hematoma 3x2cm.The most probable cause is?","o":["Eclampsia","Superior sagittal sinus thrombosis","Pituitary apoplexy","Subarachnoid hemorrhage"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4209, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 306, '{"id":4209,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":306,"q":"Penicillamine use in pregnancy is associated with this fetal complication ?","o":["Conradi syndrome","Renal anomalies","Thymus hypolplasia","Cutis laxa"],"a":3,"e":"Ans. D. Cutis laxa Pencillamine interferes with synthesis of collagen & elastin & can cause :elastosisperforansserpiginosa and localized cutis laxa.","pyqMatches":[{"year":"2016","no":1574,"q":"Penicillamine use in pregnancy is associated with this fetal complication ?","o":["Conradi syndrome","Renal anomalies","Thymus hypolplasia","Cutis laxa"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4210, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 307, '{"id":4210,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":307,"q":"DOC for malaria in pregnancy ?","o":["Chloroquin","Quinine","Primaquin","Artesunate"],"a":0,"e":"Ans, A. Chloroquin Drugs for treatment of malaria in pregnancy- Malaria can be life threatening during pregnancy. Chloroquin is 1st choice of drug. If resistant to chloroquin, quinine should be given under supervision. Primaquin (for radical cure) should be withheld until the pregnancy is over. Artesunate is the 1st choice in case of complicated malaria.","pyqMatches":[{"year":"2012","no":1324,"q":"DOC for malaria in pregnancy ?","o":["Chloroquin","Quinine","Primaquin","Artesunate"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4211, 'OBG', 'Labour & Delivery', 'Easy', 'Gynecology', 308, '{"id":4211,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Gynecology","sourceNo":308,"q":"Prophylactic methergin given for ?","o":["Induction of labour","Induction of abortion","To stop excess bleeding from uterus","All of the above"],"a":2,"e":"Ans, C. To stop excess bleeding from uterus Methergin (methyl-ergo-novine) is a semisynthetic ergot derivative derived from lysergic acid. Indications Prophylactic:- Active management of 3rd stage of labour to prevent excess bleeding following delivery. Therapeutic:- To stop atonic uterine bleeding.","pyqMatches":[{"year":"2012","no":1323,"q":"Prophylactic methergin given for ?","o":["Induction of labour","Induction of abortion","To stop excess bleeding from uterus","All of the above"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4212, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Gynecology', 309, '{"id":4212,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Gynecology","sourceNo":309,"q":"6 year old son of pregnant women is suffering from chicken pox. Which of the following is given to pregnant women ?","o":["Acyclovir","Acyclovir + immunoglobulin","Only immunoglobulin","Vaccination"],"a":1,"e":"Ans. B. Acyclovir + immunoglobulin Varicella during pregnancy The risk of congenital malformations is nearly absent when maternal infection occurs after 20 weeks. VariceIa vaccine is not recommended in pregnancy. Varicella zoster immunoglobulin (VZIG) should be given to exposed non-immune as it reduces the mortality. Oral acyclovir is safe in pregnancy & reduces the duration of illness when given with in 24 hrs of rash but it cannot prevent congenital infection.","pyqMatches":[{"year":"2012","no":1322,"q":"6 year old son of pregnant women is suffering from chicken pox. Which of the following is given to pregnant women ?","o":["Acyclovir","Acyclovir + immunoglobulin","Only immunoglobulin","Vaccination"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4213, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 310, '{"id":4213,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":310,"q":"Maximum chance of transmission during delivery?","o":["HSV","CMV","VZV","Rubella"],"a":0,"e":"Ans. A. HSV \"Transplacental infection by HSV is not usual. The fetus becomes affected by virus shed from the cervix or lower genital tractduring vaginal delivery.\"","pyqMatches":[{"year":"2012","no":1321,"q":"Maximum chance of transmission during delivery?","o":["HSV","CMV","VZV","Rubella"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4214, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 311, '{"id":4214,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":311,"q":"Drug of choice for pneumocystis carinii in pregnancy?","o":["SMZ/TMP","Primaquine","Dapsone","Pentamidine"],"a":0,"e":"Ans, A. SMZ/TMP","pyqMatches":[{"year":"2012","no":1320,"q":"Drug of choice for pneumocystis carinii in pregnancy?","o":["SMZ/TMP","Primaquine","Dapsone","Pentamidine"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4215, 'OBG', 'Miscellaneous', 'Moderate', 'Gynecology', 312, '{"id":4215,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Gynecology","sourceNo":312,"q":"A pregnant woman in first trimester has four fold rise in IgG against toxoplasmosis. it indicates ?","o":["Protective antibodies","Acute infection","Chronic infection","None of the above"],"a":1,"e":"Ans, B. Acute infection Acute infection is detected by detecting IgM specific antibody high titre of IgG antibody & detection of sero-conversion for IgG from negative to positive","pyqMatches":[{"year":"2012","no":1319,"q":"A pregnant woman in first trimester has four fold rise in IgG against toxoplasmosis. it indicates ?","o":["Protective antibodies","Acute infection","Chronic infection","None of the above"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4216, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 313, '{"id":4216,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":313,"q":"HRT is given in ?","o":["Symptomatic postmenopausal women","Following hysterectomy","Gonadal dysgenesis","All of the above"],"a":3,"e":"Ans, D. All of the above Indications of HRT","pyqMatches":[{"year":"2012","no":1318,"q":"HRT is given in ?","o":["Symptomatic postmenopausal women","Following hysterectomy","Gonadal dysgenesis","All of the above"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4217, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 314, '{"id":4217,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":314,"q":"Methergin is given for prophylaxis of ?","o":["Anaemia","Cardiac disease","Renal disease","Lung disease"],"a":0,"e":"Ans, A. Anaemia Methergin (methyl-ergo-novine) is a semisynthetic ergot derivative derived from lysergic acid. Indications","pyqMatches":[{"year":"2012","no":1317,"q":"Methergin is given for prophylaxis of ?","o":["Anaemia","Cardiac disease","Renal disease","Lung disease"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4218, 'OBG', 'Miscellaneous', 'Moderate', 'Gynecology', 315, '{"id":4218,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Gynecology","sourceNo":315,"q":"All of the following occurs because of prostaglandin use except?","o":["Excess water retention","Flushes","Increased motility of bowel","Nausea"],"a":0,"e":"Ans, A. Excess water retention Disadvantages & side effects of prostaglandins","pyqMatches":[{"year":"2012","no":1316,"q":"All of the following occurs because of prostaglandin use except?","o":["Excess water retention","Flushes","Increased motility of bowel","Nausea"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4219, 'OBG', 'Abortion & Ectopic Pregnancy', 'Moderate', 'Gynecology', 316, '{"id":4219,"subject":"OBG","chapter":"Abortion & Ectopic Pregnancy","difficulty":"Moderate","source":"Gynecology","sourceNo":316,"q":"Definite use for PGE2 is all except ?","o":["Contraception","Induces labour","Therapeutic abortion","Keeps patency of PDA"],"a":0,"e":"Ans. A. Contraception","pyqMatches":[{"year":"2012","no":1315,"q":"Definite use for PGE2 is all except ?","o":["Contraception","Induces labour","Therapeutic abortion","Keeps patency of PDA"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4220, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 317, '{"id":4220,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":317,"q":"Which of following most commonly clinically used?","o":["Diagonal conjugate","Ant post diameter of inlet","Transverse diameter of outlet","Oblique diameter of pelvis"],"a":0,"e":"Ans, A. Diagonal conjugate Most commonly used clinical conjugate is Diagonal conjugate.","pyqMatches":[{"year":"2012","no":1314,"q":"Which of following most commonly clinically used?","o":["Diagonal conjugate","Ant post diameter of inlet","Transverse diameter of outlet","Oblique diameter of pelvis"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4221, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 318, '{"id":4221,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":318,"q":"Least diameter of inlet of gynecoid pelvis is?","o":["Transverse","Oblique","Diagonal conjugate","Obstetric conjugate"],"a":3,"e":"Ans, D. Obstetric conjugate","pyqMatches":[{"year":"2012","no":1313,"q":"Least diameter of inlet of gynecoid pelvis is?","o":["Transverse","Oblique","Diagonal conjugate","Obstetric conjugate"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4222, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 319, '{"id":4222,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":319,"q":"Tdap vaccine is give in between which weeks of pregnancy?","o":["10-16 weeks","17-22 weeks","22-26 weeks","27-36 weeks"],"a":3,"e":"Ans, D. 27-36 weeks Women should get adult tetanus, diphtheria and acellular pertussis vaccine (Tdap) during each pregnancy. Ideally, the vaccineshould be given between 27 and 36 weekes ofpregnancy\".","pyqMatches":[{"year":"2012","no":1312,"q":"Tdap vaccine is give in between which weeks of pregnancy?","o":["10-16 weeks","17-22 weeks","22-26 weeks","27-36 weeks"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
