INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4228, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 325, '{"id":4228,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":325,"q":"I-pill is used when ?","o":["Accidental sexual exposure","OCP forgotten","Of choice in young","All of the above"],"a":0,"e":"Ans. A. Accidental sexual exposure I-pill l-pill is an emergency contraceptive Pill containing levonorgestrel. Asingledoseof I pillprovidesasafeandeasywaytopreventanunintended pregnancy,afterunprotected sex orcontraceptivefailure. It should be take i-pill as soon as possible, preferably within 12 hours and no later than 72 hours ofunprotected intercourse. Single dose tablet to be taken orally after a meal.","pyqMatches":[{"year":"2012","no":1306,"q":"I-pill is used when ?","o":["Accidental sexual exposure","OCP forgotten","Of choice in young","All of the above"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
