INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4253, 'OBG', 'Benign Gynecology', 'Easy', 'Gynecology', 350, '{"id":4253,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Easy","source":"Gynecology","sourceNo":350,"q":"HT indicated in menopausal women","o":["Hot flash","Ca breast","Endometriosis","Uterine bleeding"],"a":0,"e":"Ans. A. Hot flash Hormone Therapy (HT) is one of the government-approved treatments for relief of menopausal symptoms. These symptoms, caused by lower levels of estrogen at menopause, include : Hot flashes, Sleep disturbances, and Vaginal dryness. HT is also approved for the prevention of osteoporosis.","pyqMatches":[{"year":"2018","no":178,"q":"HT indicated in menopausal women","o":["Hot flash","Ca breast","Endometriosis","Uterine bleeding"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4254, 'OBG', 'Benign Gynecology', 'Easy', 'Gynecology', 351, '{"id":4254,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Easy","source":"Gynecology","sourceNo":351,"q":"In Uterine prolapse how to know if ring is in place?","o":["If not expelled after increased abdominal pressure","If Bleeding does not occur","If patient feels discomfort","None"],"a":0,"e":"Ans. A.If not expelled after increased abdominal pressure A vaginal pessary is a removable device placed into the vagina. It is designed to support areas of pelvic organ prolapse. A variety of pessaries are available, including the ring pessaries If not expelled after increased abdominal pressure ring pessary is supposed to be placed in place","pyqMatches":[{"year":"2018","no":177,"q":"In Uterine prolapse how to know if ring is in place?","o":["If not expelled after increased abdominal pressure","If Bleeding does not occur","If patient feels discomfort","None"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4255, 'OBG', 'Antenatal Care & Complications', 'Easy', 'Gynecology', 352, '{"id":4255,"subject":"OBG","chapter":"Antenatal Care & Complications","difficulty":"Easy","source":"Gynecology","sourceNo":352,"q":"Drug that is used for fetal lung maturity is:","o":["Dexamethasone","Folic acid","Beclomethasone","None"],"a":0,"e":"Ans. A. Dexamethasone Betamethasone and dexamethasone are corticosteroids, also called glucocorticoids, that are given before birth (antenatally) to speed up a preterm fetuses lung development. Either is used when a mother is in preterm labor and birth may occur in 24 to 48 hours.","pyqMatches":[{"year":"2018","no":176,"q":"Drug that is used for fetal lung maturity is:","o":["Dexamethasone","Folic acid","Beclomethasone","None"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4256, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 353, '{"id":4256,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":353,"q":"Best time to do quadruple test","o":["8-12 weeks","11-15 weeks","15-20 weeks","18-22 weeks"],"a":2,"e":"Ans. C.15-20 weeks The quad screen is done in the second trimester, usually between 15 and 20 weeks of pregnancy. Ideally, the test should be performed in conjunction with first- trimester screening tests.","pyqMatches":[{"year":"2018","no":175,"q":"Best time to do quadruple test","o":["8-12 weeks","11-15 weeks","15-20 weeks","18-22 weeks"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4257, 'OBG', 'Postpartum & Puerperium', 'Moderate', 'Gynecology', 354, '{"id":4257,"subject":"OBG","chapter":"Postpartum & Puerperium","difficulty":"Moderate","source":"Gynecology","sourceNo":354,"q":"Which One of the following is not a cause of secondary Postpartum Haemorrhage?","o":["Placenta previa","Retained bits of placenta","Endometritis","Polyp"],"a":0,"e":"Ans. A.Placenta previa Causes of secondary Postpartum Haemorrhage are: Retained bits of placenta Postpartum infection Infection of Cervical and Vaginal Tears Puerperal Inversion of Uterus Uterine Polyp or Fibroid: Undiagnosed carcinoma of cervix Chorion-epithelioma","pyqMatches":[{"year":"2018","no":174,"q":"Which One of the following is not a cause of secondary Postpartum Haemorrhage?","o":["Placenta previa","Retained bits of placenta","Endometritis","Polyp"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4258, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 355, '{"id":4258,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":355,"q":"RDA of iodine in lactation in microgram-","o":["150","220","100","250"],"a":3,"e":"Ans. D. 250 To accommodate increased iodine needs during pregnancy and lactation, the iodine RDA is 220 mcg/day for pregnant women and 250 mcg/day for lactating women","pyqMatches":[{"year":"2018","no":173,"q":"RDA of iodine in lactation in microgram","o":["150","220","100","250"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4259, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 356, '{"id":4259,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":356,"q":"Paget''s is associated with which other cancer:","o":["Vulva","Vagina","Cervix","Uterus"],"a":0,"e":"Ans. A. Vulva Extramammary Paget''s disease (EMPD), also extramammary Paget disease, is a rare, slow-growing, usually noninvasive intraepithelial (in the skin) adenocarcinoma outside the mammary gland and includes Paget''s disease of the vulva and the extremely rare Paget''s disease of the penis.","pyqMatches":[{"year":"2018","no":185,"q":"Paget''s is associated with which other cancer:","o":["Vulva","Vagina","Cervix","Uterus"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4260, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 357, '{"id":4260,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":357,"q":"Fimbriectomy procedure is known as-","o":["Uchida method","Irving method","Madlener technique","Kroener method"],"a":3,"e":"Ans. D. Kroener method Uchida technique—A saline solution is injected subserosal in the mid portion of the tube to create a bleb. Irving method — The tube is ligated on either side and mid portion of the tube (between the ties) is excised. Madlener technique -It is the easiest method. The loop of the tube is crushed with an artery forceps. Kroener method of fimbriectomy is not a common procedure","pyqMatches":[{"year":"2018","no":172,"q":"Fimbriectomy procedure is known as","o":["Uchida method","Irving method","Madlener technique","Kroener method"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4261, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 358, '{"id":4261,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":358,"q":"Establishment of fetoplacental circulation seen at-","o":["11 to 13 days","20 to 22 days","7 days","25 to 26 days"],"a":1,"e":"Ans. B.20 to 22 days Important Events Following Fertilization 0’ hour Fertilization (day-15 from LMP) 30 hours 2 cell stage (blastomeres) 40–50 hours 4 cell stage 72 hours 12 cell stage 96 hours 16 cell stage. Morula enters the uterine cavity 5th day Blastocyst 4–5th day Zona pellucida disappears 5–6th day Blastocyst attachment to endometrial surface 6–7th day Differentiation of cyto and syncytiotrophoblast layers 10th day Synthesis of hCG by syncytiotrophoblast 9–10th day Lacunar network forms 10–11th day Trophoblasts invade endometrial sinusoids establishing uteroplacental circulation Interstitial implantation completed with entire decidual coverage 13th day Primary villi 16th day Secondary villi 16th day Secondary villi 21st day Tertiary villi 21st–22nd day Fetal heart. Fetoplacental circulation","pyqMatches":[{"year":"2018","no":171,"q":"Establishment of fetoplacental circulation seen at","o":["11 to 13 days","20 to 22 days","7 days","25 to 26 days"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4262, 'OBG', 'Abortion & Ectopic Pregnancy', 'Easy', 'Gynecology', 359, '{"id":4262,"subject":"OBG","chapter":"Abortion & Ectopic Pregnancy","difficulty":"Easy","source":"Gynecology","sourceNo":359,"q":"Dilatation & curettage (D&C) is contraindicated in-","o":["Pelvic inflammatory disease (PID)","Endometriosis","Ectopic pregnancy","None"],"a":0,"e":"Ans. A. Pelvic inflammatory disease (PID) Predisposing risk factors for PID are: Sexual contact History of STI Procedures involving the upper female genital tract including: Dilatation & curettage (D&C) Recent intrauterine device (IUD) insertion Therapeutic abortion (T/A)","pyqMatches":[{"year":"2018","no":179,"q":"Dilatation & curettage (D&C) is contraindicated in","o":["Pelvic inflammatory disease (PID)","Endometriosis","Ectopic pregnancy","None"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4263, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 360, '{"id":4263,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":360,"q":"Anteversion of uterus is maintained by?","o":["Cardinal ligament","Uterosacral ligament","Pubocervical ligament","Round ligament"],"a":3,"e":"Ans. D. Round ligament In most women, the uterus is anteverted and anteflexed. The function of the round ligament is maintenance of the anteversion of the uterus(a position where the fundus of the uterus is turned forward at the junction of cervix and vagina) during pregnancy. Normally, the cardinal ligament is what supports the uterine angle (angle of anteversion).","pyqMatches":[{"year":"2018","no":294,"q":"Anteversion of uterus is maintained by?","o":["Cardinal ligament","Uterosacral ligament","Pubocervical ligament","Round ligament"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4264, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Gynecology', 361, '{"id":4264,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Gynecology","sourceNo":361,"q":"What is the effect of Progesterone only pills?","o":["Completely suppresses ovulation","Thin lining of uterus","Thick cervical mucus","All of the above"],"a":3,"e":"Answer: D. All of the above Progestogen-only pills / Progestin-only Pills (POP) / Morning after pills - Contraceptive pills Contain only synthetic progestins & doesn''t contain estrogen. Mechanism: Mucus thickening in the neck of the womb: Penetration of sperm to reach egg and womb becomes difficult. Prevents ovulation: The lining of the uterus becomes thin Fertilized egg implantation is prevented Advantages: Doesn’t interfere with breastfeeding Also helps in premenstrual symptoms and painful periods","pyqMatches":[{"year":"2018","no":240,"q":"What is the effect of Progesterone only pills?","o":["Completely suppresses ovulation","Thin lining of uterus","Thick cervical mucus","All of the above"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4265, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 362, '{"id":4265,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":362,"q":"Long-standing pelvic inflammation may lead to which of the following conditions?","o":["Pyometra","Uterine polyposis","Pseudopregnancy","Cystic endometrial hyperplasia"],"a":0,"e":"Ans. A.Pyometra Pyometra is collection of pus due to obstruction of flow in the uterine cavity. It may be due to Long-standing PID or secondary to cervical stenosis.","pyqMatches":[{"year":"2018","no":295,"q":"Long-standing pelvic inflammation may lead to which of the following conditions?","o":["Pyometra","Uterine polyposis","Pseudopregnancy","Cystic endometrial hyperplasia"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4266, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 363, '{"id":4266,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":363,"q":"Meiosis occurs in","o":["Adult ovary","Prepubertal testis","At birth in ovary","All"],"a":0,"e":"Ans. is. A. Adult ovary Meiosis 1 is completed at puberty hence answer is adult ovary Total number of oocytes at 20 weeks of intrauterine life is about 6–7 million. At birth, the total number of primordial follicles is estimated to be about 2 million. The primary oocytes do not finish the first meiotic division until puberty is reached. Spermatogenesis occurs at puberty so it cannot happen in prepubertal testis .","pyqMatches":[{"year":"2020","no":219,"q":"Meiosis occurs in","o":["Adult ovary","Prepubertal testis","At birth in ovary","All"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4267, 'OBG', 'Labour & Delivery', 'Easy', 'Gynecology', 364, '{"id":4267,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Gynecology","sourceNo":364,"q":"Prolactin secreted maximum at-","o":["24 hrs after delivery","REM","2 hrs running","24 hour after Ovulation"],"a":0,"e":"Ans. A.24 hrs after delivery Prolactin is maximum 24 hrs after delivery. Prolactin secretion also increases during strenuous exercise and sleep(NREM). 24 hrs after ovulation estrogen has a negative feedback effect on prolactin which decreases the level of prolactin.","pyqMatches":[{"year":"2020","no":213,"q":"Prolactin secreted maximum at","o":["24 hrs after delivery","REM","2 hrs running","24 hour after Ovulation"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4268, 'OBG', 'Labour & Delivery', 'Hard', 'Gynecology', 365, '{"id":4268,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Hard","source":"Gynecology","sourceNo":365,"q":"A sexually active female with the profuse frothy foul-smelling discharge with intense itching. Strawberry cervix revealed on examination. What will be the diagnosis?","o":["Trichomonas vaginalis","Bacterial vaginosis","Candidiasis","None"],"a":0,"e":"Answer: a. Trichomonas vaginalis Trichomonas vaginitis: Clinical Features: There is sudden profuse and offensive vaginal discharge often dating from the last menstruation. Irritation and itching of varying degrees within and around the introitus are common. There is the presence of urinary symptoms such as dysuria and frequency of micturition. There may be history of previous similar attacks On Examination: There is thin, greenish-yellow and frothy offensive discharge per vaginum. The vulva is inflamed with evidences of pruritus. Vaginal examination may be painful. The vaginal walls become red and inflamed with multiple punctate hemorrhagic spots. Similar spots are also found over the mucosa of the portio vaginalis part of the cervix on speculum examination giving the appearance of ‘strawberry’ Ref: Dutta Gynaecology 6th edition Page no.163-164","pyqMatches":[{"year":"2020","no":210,"q":"A sexually active female with the profuse frothy foul-smelling discharge with intense itching. Strawberry cervix revealed on examination. What will be the diagnosis?","o":["Trichomonas vaginalis","Bacterial vaginosis","Candidiasis","None"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4269, 'OBG', 'Infertility & Reproductive Endocrinology', 'Hard', 'Gynecology', 366, '{"id":4269,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Hard","source":"Gynecology","sourceNo":366,"q":"18-year-old girl presents with 6 months of amenorrhea with h/o low-grade fever, weight loss, pain abdomen, generalized weaknesses. On PR examination, palpable left-sided pelvic mass felt... Diagnosis is","o":["Fibroid with degeneration","TB pelvis with Tubo ovarian mass","Ectopic pregnancy","Granulosa cell tumour"],"a":1,"e":"Ans.B.TB pelvis with Tubo ovarian mass The tubercles burst to pour the caseous material inside the lumen producing tubercular pyosalpinx, which may adhere to the ovaries and the surrounding structures. Often the infection spreads outwards producing peri salpingitis with exudation, causing dense adhesions with the surrounding structures tubercular tubo-ovarian mass. Clinical diagnostic features: Weakness, low-grade fever, anorexia, anemia or night sweats may be present. Infertility: It may be primary or secondary Chronic pelvic pain Vaginal discharge— postcoital bleeding or a blood-stained discharge. Constitutional symptoms such as loss of weight, malaise, anorexia, pyrexia, and anemia are present in the acute phase of the disease. Menstrual abnormality: In about 50 percent, the menstrual function is normal. Presence of pelvic mass with nodules in the pouch of Douglas palpable Ref. Gynaecology Dutta ed. 6th Page no. 139-142","pyqMatches":[{"year":"2020","no":232,"q":"18-year-old girl presents with 6 months of amenorrhea with h/o low-grade fever, weight loss, pain abdomen, generalized weaknesses. On PR examination, palpable left-sided pelvic mass felt... Diagnosis is","o":["Fibroid with degeneration","TB pelvis with Tubo ovarian mass","Ectopic pregnancy","Granulosa cell tumour"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4270, 'OBG', 'Miscellaneous', 'Moderate', 'Gynecology', 367, '{"id":4270,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Gynecology","sourceNo":367,"q":"A pregnant female had Meconium stained liquor and underwent emergency LSCS. A few days later her condition deteriorated. USG showed edematous bowels. What''s the cause?","o":["Meconium peritonitis","Paralytic ileus","Adhesive intestinal obstruction","Intra-abdominal abscess"],"a":1,"e":"Ans.B. Paralytic ileus POSTOPERATIVE COMPLICATIONS OF LSCS: Intestinal obstruction: The obstruction may be mechanical due to adhesions or bands, or paralytic ileus following peritonitis. Paralytic ileus is an adynamic obstruction in which there is a failure of transmission of peristaltic waves Clinical features : The resultant stasis leads to the following: Accumulation of fluid and gas in the bowel With associated distension: marked and tympanitic Vomiting (effortless) Absence of bowel sounds Absolute constipation Dutta obstetrics ed. 8th Page no. 678 Bailey & Love''s Short Practice of Surgery - 27th Edition (Page no 1297)","pyqMatches":[{"year":"2020","no":231,"q":"A pregnant female had Meconium stained liquor and underwent emergency LSCS. A few days later her condition deteriorated. USG showed edematous bowels. What''s the cause?","o":["Meconium peritonitis","Paralytic ileus","Adhesive intestinal obstruction","Intra-abdominal abscess"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4271, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Gynecology', 368, '{"id":4271,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Gynecology","sourceNo":368,"q":"Best treatment option for septate uterus-","o":["Tompkins Metroplasty","Jones metroplasty","Strassmann metroplasty","Transcervical hysteroscopic resection of the septum"],"a":3,"e":"Ans. D. Transcervical hysteroscopic resection of the septum Hysteroscopic metroplasty is more commonly done. Resection of the septum can be done either by a resectoscope or by laser. Advantages are:","pyqMatches":[{"year":"2020","no":230,"q":"Best treatment option for septate uterus","o":["Tompkins Metroplasty","Jones metroplasty","Strassmann metroplasty","Transcervical hysteroscopic resection of the septum"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4272, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 369, '{"id":4272,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":369,"q":"Distension media used for hysteroscopy with bipolar cautery?","o":["Glycine","NS","Co2","Dextran 70"],"a":1,"e":"Ans. B. NS The distending media commonly used in hysteroscopy is normal saline —The uterine cavity is distended with a media to separate the uterine walls and to have a panoramic view. The media used could be either a gas or a liquid. Carbon dioxide (CO 2 )—is commonly used for diagnostic purposes. It is soluble in blood and is safe. Hysteroflator provides a gas flow rate of a maximum of 100 mL per minute and a maximum pressure of 100 mm Hg. Liquid media is used for operative procedures. Normal saline can be used is suitable for bipolar cautery but not suitable for monopolar electrosurgery. Constant flow is to be maintained to flush the operative area. Ref. Dutta Gynaecology ed. 6th page no. 620, 624","pyqMatches":[{"year":"2020","no":229,"q":"Distension media used for hysteroscopy with bipolar cautery?","o":["Glycine","NS","Co2","Dextran 70"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4273, 'OBG', 'Miscellaneous', 'Easy', 'Gynecology', 370, '{"id":4273,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Gynecology","sourceNo":370,"q":"Most common site for Fertilization is-","o":["Ampulla","Isthmus","Intramural","Fimbriae"],"a":0,"e":"Ans. A. Ampulla Fertilization is the process of fusion of the spermatozoon with the mature ovum. It begins with sperm egg collision and ends with the production of a mononucleated single cell called the zygote. Its objectives are: To initiate the embryonic development of the egg and To restore the chromosome number of the species. Almost always, fertilization occurs in the ampullary part of the uterine tube. Reference: Dutta Obstetrics ed. 8th Page no 23","pyqMatches":[{"year":"2020","no":228,"q":"Most common site for Fertilization is","o":["Ampulla","Isthmus","Intramural","Fimbriae"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4274, 'OBG', 'Miscellaneous', 'Hard', 'Gynecology', 371, '{"id":4274,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Hard","source":"Gynecology","sourceNo":371,"q":"A 22-year-old primigravida visits ANC OPD with 20 weeks POG. On examination uterine height reveals a 16-week size.USG shows reduced liquor. What will be the diagnosis?","o":["Renal agenesis","Fetal anemia","Barter’s syndrome","Liddle syndrome"],"a":0,"e":"Ans. A. Renal agenesis The question states reduced liquor that means oligohydramnios is seen. Oligohydramnios is defined as an amniotic fluid index of 5 cm or less. It is almost always present when there is either obstruction of the fetal urinary tract or renal agenesis. Williams Obstetrics ed 24th page 237","pyqMatches":[{"year":"2020","no":227,"q":"A 22-year-old primigravida visits ANC OPD with 20 weeks POG. On examination uterine height reveals a 16-week size.USG shows reduced liquor. What will be the diagnosis?","o":["Renal agenesis","Fetal anemia","Barter’s syndrome","Liddle syndrome"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4275, 'OBG', 'Miscellaneous', 'Moderate', 'Gynecology', 372, '{"id":4275,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Gynecology","sourceNo":372,"q":"Which of the following is not an estrogen-dependent pubertal change?","o":["Hair growth","Menstruation","Vaginal Cornification","Cervical mucus"],"a":1,"e":"Ans. B. Menstruation Pubarche or development of axillary and pubic hair is due to testosterone (in both the sexes). Puberty in females : Involves the beginning of menstrual cycles (menarche), breast development (thelarche), and an increase in adrenal androgen secretion (adrenarche). Estradiol induces the development of secondary sex characteristics, including the breasts and reproductive tract, and increased fat in the hips. Estrogens also regulate the growth spurt at puberty, vaginal cornification, and cervical mucus production, induce closure of the epiphyses, have a positive effect in maintaining bone formation, and can antagonize the degrading actions of parathyroid hormone on bone. Reference: Rhoades and Tanner''s Medical Physiology, 2nd edition (Page no: 680)","pyqMatches":[{"year":"2020","no":226,"q":"Which of the following is not an estrogen-dependent pubertal change?","o":["Hair growth","Menstruation","Vaginal Cornification","Cervical mucus"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4276, 'OBG', 'Infertility & Reproductive Endocrinology', 'Hard', 'Gynecology', 373, '{"id":4276,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Hard","source":"Gynecology","sourceNo":373,"q":"A mother brought her 16-year-old daughter to Gynaecology OPD with a complaint of not attending menarche. She gives H/O cyclic abdominal pain. On further examination midline, abdominal swelling seen. Per rectal examination reveals a bulging mass in the vagina. Which of the following can be most commonly seen?","o":["Imperforate hymen","Transvaginal septum","Vaginal agenesis","MRKH"],"a":0,"e":"Ans. A. Imperforate hymen According to the clinical case, patients suffer from primary amenorrhea and cryptomenorrhea(cyclic abdominal pain). The girl is aged about 14–16 years. The chief complaints are periodic lower abdominal pain, which may be continuous, primary amenorrhea and urinary symptoms, such as frequency, dysuria or even retention of urine. In fact, in significant cases, the presenting feature may be the retention of urine. The cause of retention is due to the elongation of the urethra. An abdominal examination reveals a suprapubic swelling, which may be uterine or full bladder. Prior catheterization reveals the true state. Vulval inspection reveals a tense bulging membrane of bluish coloration Ref. Dutta Gynaecology ed. 6th page no. 42","pyqMatches":[{"year":"2020","no":225,"q":"A mother brought her 16-year-old daughter to Gynaecology OPD with a complaint of not attending menarche. She gives H/O cyclic abdominal pain. On further examination midline, abdominal swelling seen. Per rectal examination reveals a bulging mass in the vagina. Which of the following can be most commonly seen?","o":["Imperforate hymen","Transvaginal septum","Vaginal agenesis","MRKH"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4277, 'OBG', 'Infertility & Reproductive Endocrinology', 'Hard', 'Gynecology', 374, '{"id":4277,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Hard","source":"Gynecology","sourceNo":374,"q":"13 yr old child visit gynaecology OPD with a complaint of not attaining menarche with karyotype 46XX. On examination, clitoromegaly is seen. Which enzyme is most likely to be deficient in the above condition?","o":["21 alpha-hydroxylase","11 beta-hydroxylase","17 alpha-hydroxylase","3 beta-hydroxysteroid dehydrogenase"],"a":0,"e":"Ans. A. 21 alpha-hydroxylase The condition described above represents the Congenital adrenal hyperplasia. \"More than 90% of CAH cases are caused by 21-hydroxylase deficiency\" Congenital adrenal hyperplasia: It is due to an inborn error of adrenal steroid metabolism, commonly due to 21-hydroxylase (95%) and rarely due to 11-hydroxylase or 3β hydroxysteroid dehydrogenase deficiency. Clinical presentation An ambiguity of sex at birth Hirsutism and amenorrhea may be the presenting features around puberty in a milder form. The karyotype is 46, XX. Ref. Dutta Gynaecology ed. 6th page no. 440","pyqMatches":[{"year":"2020","no":224,"q":"13 yr old child visit gynaecology OPD with a complaint of not attaining menarche with karyotype 46XX. On examination, clitoromegaly is seen. Which enzyme is most likely to be deficient in the above condition?","o":["21 alpha-hydroxylase","11 beta-hydroxylase","17 alpha-hydroxylase","3 beta-hydroxysteroid dehydrogenase"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4278, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Gynecology', 375, '{"id":4278,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Gynecology","sourceNo":375,"q":"In early pregnancy clinical signs of feeling the cer​vix and the body of bulky uterus separated be​cause of softened isthmus at 6 - 8 weeks of gestation :","o":["Goodell''s sign","Chadwick''s sign","Piskacek''s sign","Hegar''s sign"],"a":3,"e":"Correct Ans: D. Hegar''s sign At 6 to 8 weeks menstrual age, the firm cervix contrasts with the now softer fundus and the compressible interposed softened isthmus —Hegar sign","pyqMatches":[{"year":"2020","no":223,"q":"In early pregnancy clinical signs of feeling the cer​vix and the body of bulky uterus separated be​cause of softened isthmus at 6 - 8 weeks of gestation :","o":["Goodell''s sign","Chadwick''s sign","Piskacek''s sign","Hegar''s sign"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4279, 'OBG', 'Labour & Delivery', 'Moderate', 'Gynecology', 376, '{"id":4279,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Moderate","source":"Gynecology","sourceNo":376,"q":"Misoprostol used in the induction of labour is an analogue of which of the following type of prostaglandin?","o":["PG E1","PG E2","PG I2","PG F2alpha"],"a":0,"e":"Correct Ans: A. PG E1 Misoprostol is a methyl ester of PGE1. Indications of Misoprostol: It is used for cervical ripening. Transvaginally it is used for induction of labour. Uses of Prostaglandins in Obstetrics: Induction of abortion Termination of molar pregnancy Induction of labour Cervical ripening prior to induction of labour Acceleration of labour Management of atonic postpartum hemorrhage Medical management of tubal ectopic pregnancy","pyqMatches":[{"year":"2020","no":222,"q":"Misoprostol used in the induction of labour is an analogue of which of the following type of prostaglandin?","o":["PG E1","PG E2","PG I2","PG F2alpha"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4280, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 1, '{"id":4280,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":1,"q":"The thickness of endometrium at the time of implantation is :","o":["3 – 4 mm","20 – 30 mm","15 –20 mm","30 – 40 mm"],"a":0,"e":"Ans. is None/ a i.e. 3-4 mm \"7he Endometrium is in the secretory phase corresponding to 20 - 21 days of cycle\" at the time of implantation. \"After ovulation, the endometrium now demonstrates a combined reaction to estrogen and progesterone activity. Most impressive is that total endometrial height is fixed at roughly its preovulatory extent (5 -6 mm) despite continued availability of estrogen.\" Reading the above text it is clear that endometrium is - 5 - 6 mm thick at the time of implantation, which is not given in the option. Still if you have to mark one answer option ''a'' i.e. 3 - 4 mm being closest could be right. Extra Edge Implantation occurs 7 - 9 days after ovulation°. In human, the blastocyst burrows in the uterine cavity till whole of it lies within the thickness of endometrium. This is called as interstitial implantation. After implantation of the embryo the uterine endometrium is called the decidua\". Decidua basalis - The part of decidua where the placenta is to be formed. Decidua Capsularis - The part of the decidua that separates the embryo from the uterine lumen. Decidua Parietalis - The part of the decidua lining rest of the uterine cavity. At the end of pregnancy, the decidua is shed off along with placenta and membranes.","pyqMatches":[{"year":"2012","no":235,"q":"The thickness of endometrium at the time of implantation is :","o":["3 – 4 mm","20 – 30 mm","15 –20 mm","30 – 40 mm"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4281, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 2, '{"id":4281,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":2,"q":"Zygote with zona pellucida reaches uterine cavity by :","o":["2 days","4 days","5 days","6 days"],"a":1,"e":"4 days","pyqMatches":[{"year":"2016","no":1,"q":"Zygote with zona pellucida reaches uterine cavity by :","o":["2 days","4 days","5 days","6 days"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4282, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 3, '{"id":4282,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":3,"q":"Ligamentum terea is formed after '':","o":["Obliteration of the umbilical vein","Obliteration of the ductus venous","Obliteration of the ductus arteriosus","Obliteration of the hypogastric artery"],"a":0,"e":"Obliteration of the umbilical vein","pyqMatches":[{"year":"2013","no":830,"q":"Ligamentum terea is formed after '':","o":["Obliteration of the umbilical vein","Obliteration of the ductus venous","Obliteration of the ductus arteriosus","Obliteration of the hypogastric artery"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4283, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 4, '{"id":4283,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":4,"q":"The role of human placental lactogen is :","o":["Stimulate milk production","Fetal breast development","Growth of fetus","Endocrine regulation"],"a":2,"e":"Growth of fetus Functions : a) Provide fetal nutrition by antagonizing the action of insulin in maternal circulation, breakdown of fats and proteins and transport of fatty acids and amino acids from maternal to feta circulation. b) Potent angiogenic, helps develop fetal vasculature. c) Promotes growth of breast for lactation.","pyqMatches":[{"year":"2015","no":1522,"q":"The role of human placental lactogen is :","o":["Stimulate milk production","Fetal breast development","Growth of fetus","Endocrine regulation"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4284, 'OBG', 'Postpartum & Puerperium', 'Easy', 'Obstetrics', 5, '{"id":4284,"subject":"OBG","chapter":"Postpartum & Puerperium","difficulty":"Easy","source":"Obstetrics","sourceNo":5,"q":"Commonest cause for puerperal sepsis is :","o":["Streptococci","Anaerobes","Gonococci","Staphylococci"],"a":0,"e":"Streptococci","pyqMatches":[{"year":"2015","no":732,"q":"Commonest cause for puerperal sepsis is :","o":["Streptococci","Anaerobes","Gonococci","Staphylococci"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4285, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 6, '{"id":4285,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":6,"q":"The best method for inducing mid trimester abortion is :","o":["Injection of Hypertonic Saline","Ethacrydine","Prostaglandins","D and C"],"a":2,"e":"Prostaglandins Mid trimester termination of pregnancy A) Medical methods i) Prostaglandins : misoprostol (PGE 1) with or without Mife pristone, gemeprost (PGE1), dinoprostone (PGE2), carboprost (PGE2) ii) Oxytocin","pyqMatches":[{"year":"2015","no":1502,"q":"The best method for inducing mid trimester abortion is :","o":["Injection of Hypertonic Saline","Ethacrydine","Prostaglandins","D and C"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4286, 'OBG', 'Abortion & Ectopic Pregnancy', 'Easy', 'Obstetrics', 7, '{"id":4286,"subject":"OBG","chapter":"Abortion & Ectopic Pregnancy","difficulty":"Easy","source":"Obstetrics","sourceNo":7,"q":"Most common site of Implantation of tubal pregnancy is :","o":["Interstitial portion of fallopian tube","Isthmus","Ampulla","Infundibulum"],"a":2,"e":"Ampulla Maximum propensity to rupture —> Isthmic ectopic pregnancy. Minimum propensity to rupture -3 Ampullary ectopic pregnancy.","pyqMatches":[{"year":"2015","no":1574,"q":"Most common site of Implantation of tubal pregnancy is :","o":["Interstitial portion of fallopian tube","Isthmus","Ampulla","Infundibulum"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4287, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 8, '{"id":4287,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":8,"q":"During which gestational age is peak serum HCG levels attained ?","o":["7-9 weeks","11-13 weeks","20 weeks","25 weeks"],"a":0,"e":"HCG rises progressively from conception. Levels double on the average, every 30.9 hours until values reach 6500 mIU/ml (6,500 IU/L) at approximately the eighth week after the last menstrual period (LMP). After that the rate of rise becomes individualized, peaking between the 60th and 70th day (9 to 10 weeks) LMP. HCG decreases slightly between the 12th and 16th week post LMP, and then remains constant until birth.","pyqMatches":[{"year":"2015","no":1520,"q":"During which gestational age is peak serum HCG levels attained ?","o":["7-9 weeks","11-13 weeks","20 weeks","25 weeks"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4288, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 9, '{"id":4288,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":9,"q":"The uterine artery is a branch of which of the following?","o":["Left common iliac artery","Internal iliac artery","Internal pudendal artery","Ovarian artery"],"a":1,"e":"Uterine arteries arise from internal iliac artery or hypogastric artery. It runs downwards and forwards along the lateral pelvic wall until the base of the broad ligament. Note: During pregnancy the uterine arteries hypertrophy and their course is straightened. Ref: Comp Textbook of Obstetrics and Gynecology, Sadhana Gupta, 2011, Page 18","pyqMatches":[{"year":"2015","no":70,"q":"The uterine artery is a branch of which of the following?","o":["Left common iliac artery","Internal iliac artery","Internal pudendal artery","Ovarian artery"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4289, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 10, '{"id":4289,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":10,"q":"In which part of fallopian tube ectopic pregnancy will have longest survival?","o":["Isthmus","Ampulla","Cornua","Interstitium"],"a":3,"e":"Ans. D. Interstitium If the implantation occurs in the antimesenteric border in the ampulla, the pregnancy may continue a little longer time. Earliest interruption occurs in the isthmial implantation and pregnancy may continue upto 3-4 months in interstitial implantation. Also know: Isthmic rupture usually occurs at 6-8 weeks, the ampullary one at 8- 12 weeks and the interstitial one at about 4 months. Ref: Textbook of Obstetrics by DC Dutta, 6th edition, Page 181.","pyqMatches":[{"year":"2015","no":1575,"q":"In which part of fallopian tube ectopic pregnancy will have longest survival?","o":["Isthmus","Ampulla","Cornua","Interstitium"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4290, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 11, '{"id":4290,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":11,"q":"What would be the type of presentation when the engaging diameter is mentovertical?","o":["Face","Brow","Vertex","Breech"],"a":1,"e":"In brow presentation, the engaging diameter is mentovertical (14cm). Brow is the rarest variety of cephalic presentation where the presenting part is the brow and the attitude of the of the head is short of that degree of extension necessary to produce face presentation. In face presentation, the presenting part is face, attitude of the fetus shows complete flexion of the limbs with extension of the spine. The commonest position is left mento anterior. The engaging diameter of the head is submento bregmatic 9.5cm in fully extended head or submento vertical 11.5cm in partially extended head. Ref: Textbook of Obstetrics By D.C Dutta, 6th edn, page 392-3","pyqMatches":[{"year":"2015","no":1507,"q":"What would be the type of presentation when the engaging diameter is mentovertical?","o":["Face","Brow","Vertex","Breech"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4291, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 12, '{"id":4291,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":12,"q":"Which of the following statements regarding fetal circulation is correct?","o":["The liver and heart of the fetus receive blood with very high oxygen saturation","PO2 of fetal blood leaving the placenta is slightly greater than maternal mixed venous PO2","The presence of fetal hemoglobin shifts the oxyhemoglobin dissociation to the right","The foramen ovale closes during the third trimester unless the fetus has an atrial septal defect"],"a":0,"e":"Since the liver is supplied by umbilical venous blood from the placenta, and the heart and head receive blood before it has mixed with significant amounts of desaturated blood, these important organs receive blood that is relatively high in saturated oxyhemoglobin. The high rate of blood flow at the placenta and the significant resistance of the placenta to diffusion of oxygen result in blood in the umbilical vein that has a lower PO2 (30 mm Hg) than the maternal mixed venous blood. However, the left shift in fetal oxyhemoglobin concentration and the Bohr effect both act to increase the transport of oxygen to fetal tissues. A number of significant differences in circulating patterns are present in the fetus. The foramen ovale remains open until after birth and a significant portion of inferior vena cava flow is shunted through it to the left. 1/3 of blood enters directly from right atrium to left atrium (bypassing right ventricle) through foramen oval The major portion of right ventricular output is shunted through the ductus arteriosus to the aorta, not the lungs. The net effect of these shunts in the presence of high fetal pulmonary vascular resistance is very low fetal pulmonary blood flow. At birth, these patterns normally are quickly changed to ex-utero patterns with high pulmonary perfusion. Ref: Barrett K.E., Barman S.M., Boitano S., Brooks H.L. (2012). Chapter 33. Circulation through Special Regions. In K.E. Barrett, S.M. Barman, S. Boitano, H.L. Brooks (Eds), Ganong''s Review of Medical Physiology, 24e.","pyqMatches":[{"year":"2012","no":1203,"q":"Which of the following statements regarding fetal circulation is correct?","o":["The liver and heart of the fetus receive blood with very high oxygen saturation","PO2 of fetal blood leaving the placenta is slightly greater than maternal mixed venous PO2","The presence of fetal hemoglobin shifts the oxyhemoglobin dissociation to the right","The foramen ovale closes during the third trimester unless the fetus has an atrial septal defect"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4292, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 13, '{"id":4292,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":13,"q":"Most common cause of secondary PPH is :","o":["Uterine inertia","Retained placenta","Episiotomy","Cervical tear"],"a":1,"e":"Retained placenta Secondary PPH Bleeding usually occurs between 8th to 14th day of delivery. Causes of late PPH : Retained bits of cotyledon or membranes (M.C.) Infection and separation of slough over a deep cervico - vaginal laceration. Endometritis and subinvolution of the placental site.","pyqMatches":[{"year":"2015","no":1544,"q":"Most common cause of secondary PPH is :","o":["Uterine inertia","Retained placenta","Episiotomy","Cervical tear"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4293, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 14, '{"id":4293,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":14,"q":"The major contribution of the amniotic fluid after 20 weeks of gestation :","o":["Ultrafiltrate and maternal plasma","Fetal urine","Fetal lung fluid","Fetal skin"],"a":1,"e":"Ans. B. Fetal urine There are two primary sources of amniotic fluid: fetal urine and the lung liquid. After about 20 weeks, fetal urine makes up most of the fluid.","pyqMatches":[{"year":"2019","no":225,"q":"The major contribution of the amniotic fluid after 20 weeks of gestation :","o":["Ultrafiltrate and maternal plasma","Fetal urine","Fetal lung fluid","Fetal skin"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4294, 'OBG', 'Miscellaneous', 'Hard', 'Obstetrics', 15, '{"id":4294,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Hard","source":"Obstetrics","sourceNo":15,"q":"Incidence of scar rupture in a subsequent preg​nancy in case of Lower Segment Cesarean Section (LSCS) is:","o":["2%","4%","5%","8%"],"a":0,"e":"2% The risk of lower segment scar - rupture is low (0.2-1.5%) and even if it does occur, maternal death is much less and the perinatal mortality is about 1 in 8.","pyqMatches":[{"year":"2015","no":1513,"q":"Incidence of scar rupture in a subsequent preg​nancy in case of Lower Segment Cesarean Section (LSCS) is:","o":["2%","4%","5%","8%"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4295, 'OBG', 'Miscellaneous', 'Moderate', 'Obstetrics', 16, '{"id":4295,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Obstetrics","sourceNo":16,"q":"The characteristics of caput succedaneum include all of the following except :","o":["Crosses midline","Crosses the suture line","It does not disappear within 2-3 days","It is a diffuse edematous swelling of the soft tis​sues of the scalp"],"a":2,"e":"It does not disappear within 2-3 days Location- subcutaneous plane Clinical features- Soften gradually and disappear within 2-3 days Diffuse crosses suture line ill defined margin. Not associated with prolonged jaundice","pyqMatches":[{"year":"2013","no":1436,"q":"The characteristics of caput succedaneum include all of the following except :","o":["Crosses midline","Crosses the suture line","It does not disappear within 2-3 days","It is a diffuse edematous swelling of the soft tis​sues of the scalp"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4296, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 17, '{"id":4296,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":17,"q":"Hydrocephalus is best detected antenately by :","o":["X-ray abdomen","Amniocentesis","Clinical examination","Ultrasonography"],"a":3,"e":"Ans. is d i.e. Ultrasonography Hydrocephalus is a condition in which there is an abnormal increase in cerebrospinal fluid within the ventricular and subarachnoid spaces of brain. \"The prenatal diagnosis of hydrocephalus is usually made by demonstration of a dilated ventricular system in an ultrasound examination.\" Earliest and most accurate sonographic sign of hydrocephalus – Enlarged lateral ventricles.° The lateral ventricle is measured at the level of atrium. Normal transverse diameter of atrium is 7 mm ± 1 mm. (It remains constant during the second and third trimester) When diameter of atrium is >10 mm it is called as Ventriculomegaly / Hydrocephalus. Other signs of hydrocephalus on USG : Dangling choroid plexuses. Thinning out of cerebral cortex. Extra Edge : Friends, the terms ventriculomegaly and hydrocephalus are often used interchangeably but have slightly different meanings. * Ventriculomegaly : The condition in which lateral ventricles of the brain are filled with excessive fluid and enlarge. * Hydrocephalus : There is ventriculomegaly along with an increase in the head circumference. Normal fetal head circumference at term ranges between 32 and 38 cms. With hydrocephalus, the circumference exceeds 50 cms. Ventriculomegaly can also be caused by° : * Spina bifida° * Chromosomal abnormalities° * Congenital infections like cytomegalovirus. toxoplasmosis, syphilis and influenza.° Dandy walker syndrome includes Hydrocephalus + Posterior fossa cyst°+ Defect in cerebellar vermis.","pyqMatches":[{"year":"2015","no":1399,"q":"Hydrocephalus is best detected antenately by :","o":["X-ray abdomen","Amniocentesis","Clinical examination","Ultrasonography"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4297, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 18, '{"id":4297,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":18,"q":"Subpubic angle is :","o":["<65°","65-75°","85°","110-120°"],"a":2,"e":"85°","pyqMatches":[{"year":"2016","no":631,"q":"Subpubic angle is :","o":["<65°","65-75°","85°","110-120°"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4298, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 19, '{"id":4298,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":19,"q":"Rule of Hasse is used to determine :","o":["The age of fetus","Height of an adult","Race of a person","Identification"],"a":0,"e":"Ans. is a i.e. The age of fetus Hasse''s rule is employed in calculating the age of fetus by its length During the first five months of pregnancy, the length in cms is square of the age in months i.e. Length in cms = (Age in months)? Age in months = Qlength in cms During second five months of pregnancy, length in cms divided by 5 is the age in months. Length in ems Age in months 5","pyqMatches":[{"year":"2012","no":600,"q":"Rule of Hasse is used to determine :","o":["The age of fetus","Height of an adult","Race of a person","Identification"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4299, 'OBG', 'Contraception & Family Planning', 'Easy', 'Obstetrics', 20, '{"id":4299,"subject":"OBG","chapter":"Contraception & Family Planning","difficulty":"Easy","source":"Obstetrics","sourceNo":20,"q":"Banana and lemon sign seen in which fetal nomalies :","o":["Neural tube defect","Hydrops fetalis","Twins","IUD"],"a":0,"e":"Ans. is a i.e. Neural tube defect Signs of Spina bifida on Ultrasound Small biparietal diameter. Ventriculomegaly. Frontal bone scalloping or the so called lemon sign. Elongation and downward displacement of the cerebellum-the so called banana sign. Effacement or obliteration of the cisterna megna.","pyqMatches":[{"year":"2016","no":1734,"q":"Banana and lemon sign seen in which fetal nomalies :","o":["Neural tube defect","Hydrops fetalis","Twins","IUD"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4300, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 21, '{"id":4300,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":21,"q":"Indication of Acyclovir in pregnancy :","o":["Disseminated herpes","Chicken-pox in first trimester","Prophylaxis in recurrent herpes","All of the above"],"a":3,"e":"All of the above","pyqMatches":[{"year":"2012","no":575,"q":"Indication of Acyclovir in pregnancy :","o":["Disseminated herpes","Chicken-pox in first trimester","Prophylaxis in recurrent herpes","All of the above"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4301, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 22, '{"id":4301,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":22,"q":"Lovset manoeuvre is used in delivery of :","o":["Head","Breech","Foot","Arms"],"a":3,"e":"Arms Lovset''s maneuver Principle : Because of the curved birth canal, when the anterior shoulder remains above the symphysis pubis, the posterior shoulder will be below the sacral promontory. If the fetal trunk is rotated keeping the back anterior and maintaining a downward traction, the posterior shoulder will appear below the symphysis pubis.","pyqMatches":[{"year":"2015","no":1494,"q":"Lovset manoeuvre is used in delivery of :","o":["Head","Breech","Foot","Arms"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4302, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 23, '{"id":4302,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":23,"q":"Macrosomia is/are associated with:","o":["Gestational diabetes mellitus","Maternal obesity","Hypothyroidism","A & B"],"a":3,"e":"Ans. is a and b i.e. Gestational diabetes and Maternal obesity Macrosomia is the term used to describe a large fetus. The recommended definition is fetal (neonatal) weight exceeding two standard deviations or above 90th centile for the appropriate normal population. According to ACOG : birth weight of > 4500gm is called as macrosomia. In Indian context Birth weight of > 4000 gm is called as macrosomia.","pyqMatches":[{"year":"2012","no":1198,"q":"Macrosomia is/are associated with:","o":["Gestational diabetes mellitus","Maternal obesity","Hypothyroidism","A & B"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4303, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 24, '{"id":4303,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":24,"q":"Drug which is contraindicated before 2nd stage of labor is: March 2009","o":["Mifepristone","Oxytocin","Misoprostol","Ergometrine"],"a":3,"e":"Ans. D: Ergometrine Drugs used for medical method of induction of labour are: Mifepristone Oxytocin Misoprostol (Prostaglandins El) Ergometrine is contraindicated in pregnancy, 1st stage of labour, 2nd stage of labour before crowning of the head and in breech delivery prior to crowning.","pyqMatches":[{"year":"2015","no":560,"q":"Drug which is contraindicated before 2nd stage of labor is: March 2009","o":["Mifepristone","Oxytocin","Misoprostol","Ergometrine"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4304, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 25, '{"id":4304,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":25,"q":"Nuchal translucency in USG can be detected at_____weeks of gestation.","o":["11-13 weeks","18-20 weeks","8-10 weeks","20-22 weeks"],"a":0,"e":"Ans. A. 11-13 weeks Nuchal translucency is the normal fluid-filled subcutaneous space identified at the back of the fetal neck during the late first trimester and early second trimester (11.3-13.6 weeks).","pyqMatches":[{"year":"2019","no":216,"q":"Nuchal translucency in USG can be detected at_____weeks of gestation.","o":["11-13 weeks","18-20 weeks","8-10 weeks","20-22 weeks"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4305, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 26, '{"id":4305,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":26,"q":"First line of treatment of mastitis in a lactating mother is-","o":["Dicloxacillin","Cefazolin","Ceftriaxone","Ampicillin"],"a":0,"e":"Ans. A. Dicloxacillin The beta lactamase-resistant penicillins have been recommended in the treatment of mastitis. These include cloxacillin, dicloxacillin, or flucloxacillin. Because penicillins are acidic, they are poorly concentrated in human milk, which is also acid. Therefore, cloxacillin and its congeners tend to treat cellulitis well, but they are less effective in eradicating adenitis, the most likely precursor of breast abscess. When patients are allergic to penicillins, cephalexin or clindamycin may be the alternative to erythromycin. Combination like co-amoxiclav should be avoided because of fear of inducing MRSA","pyqMatches":[{"year":"2019","no":217,"q":"First line of treatment of mastitis in a lactating mother is","o":["Dicloxacillin","Cefazolin","Ceftriaxone","Ampicillin"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4306, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Obstetrics', 27, '{"id":4306,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Obstetrics","sourceNo":27,"q":"Patient with recurrent abortion diagnosed to have antiphospholipid syndrome. What will be the treatment?","o":["Aspirin only","Aspirin + Low molecular weight Heparin","Aspirin + Low molecular weight Heparin + Prednisolone","No Treatment"],"a":1,"e":"Ans. B. Aspirin + Low molecular weight Heparin The recommended treatment for women with recurrent pregnancy loss associated with antiphospholipid syndrome includes combined Aspirin and Heparin therapy. In pregnant SLE patients with Antiphospholipid antibodies and prior fetal loss, treatment with heparin (standard or low –molecular- weight) plus low dose aspirin has been shown in prospective controlled trials to increase significantly the proportion of live births. Combined aspirin and heparin therapy has proven effectiveness and is the preferred treatment for women with recurrent pregnancy loss associated with antiphospholipid syndrome.","pyqMatches":[{"year":"2019","no":218,"q":"Patient with recurrent abortion diagnosed to have antiphospholipid syndrome. What will be the treatment?","o":["Aspirin only","Aspirin + Low molecular weight Heparin","Aspirin + Low molecular weight Heparin + Prednisolone","No Treatment"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4307, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 28, '{"id":4307,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":28,"q":"Human placenta is ?","o":["Discoid","Hemochorial","Deciduate","All the above"],"a":3,"e":"Ans. is ''d'' i.e., All the above The human placenta is : Discoid, because of its shape. Hemochorial, because of direct contact of the chorion with the maternal blood andDeciduate, because some maternal tissue is shed at parturition.","pyqMatches":[{"year":"2015","no":1532,"q":"Human placenta is ?","o":["Discoid","Hemochorial","Deciduate","All the above"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4308, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 29, '{"id":4308,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":29,"q":"Twin pregnancy of the same age and sex rules out ?","o":["Superfetation","Maternal twins","Superfecundation","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Superfetation Superfetation It is the simultaneous occurrence of more than one stage of developing offspring in the same animal. In mammals, it manifests as the formation of an embryo from a different estrous cycle while another embryo or fetus is already present in the uterus.","pyqMatches":[{"year":"2015","no":1503,"q":"Twin pregnancy of the same age and sex rules out ?","o":["Superfetation","Maternal twins","Superfecundation","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4309, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Obstetrics', 30, '{"id":4309,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Obstetrics","sourceNo":30,"q":"All are true about uteroplacental circulation except","o":["Blood in the intervillous space is completely replaced 3 - 4 times per minute","The villi depend on the maternal blood for their nutrition","A mature placenta has 150 ml of blood in the villi system and 350 ml of blood in the intervillous space","Intervillous blood flow at term is 500 - 600 ml per minute"],"a":2,"e":"Answer- C. A mature placenta has 150 ml of blood in the villi system and 350 ml of blood in the intervillous space A mature placenta has a volume of about 500 ml of blood; 350 ml being occupied in the villi system and 150 ml lying in the intervillous space. Intervillous blood flow at term is around 500 - 600 ml per minute. The blood in the intervilllous space is completely replaced about 3 - 4 times per minute. The villi depend on maternal circulation for nutrition, thus it is possible for the chorionic villi to survive for a varying period even after the fetus is dead.","pyqMatches":[{"year":"2015","no":1533,"q":"All are true about uteroplacental circulation except","o":["Blood in the intervillous space is completely replaced 3 - 4 times per minute","The villi depend on the maternal blood for their nutrition","A mature placenta has 150 ml of blood in the villi system and 350 ml of blood in the intervillous space","Intervillous blood flow at term is 500 - 600 ml per minute"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4310, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 31, '{"id":4310,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":31,"q":"Uterus is receptive for implantation for how many days after fertilization -","o":["6 days","12 days","6 weeks","12 weeks"],"a":3,"e":"Answer- D. 12 weeks Superfetation is the fertilization of two ova released in two different menstrual cycles. The nidation and development of one fetus over another fetus is theoretically possible until the decidual space is obliterated by 12 weeks of pregnancy.","pyqMatches":[{"year":"2015","no":1531,"q":"Uterus is receptive for implantation for how many days after fertilization","o":["6 days","12 days","6 weeks","12 weeks"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4311, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 32, '{"id":4311,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":32,"q":"Number of stem villi at term in human placenta is","o":["60","120","240","480"],"a":0,"e":"Answer- A. 60 Functional subunit is called a lobule which is derived from a tertiary stem villi. About 60 stem villi persist in human placenta. Thus each cotyledon (total 15 - 29) contains 3 - 4 major stem villi. The villi are the functional unit of the placenta. The total villi surface, for exchange, approximately varies between 10 to 14 square metres. The fetal capillary system within the villi is almost 50 km long.","pyqMatches":[{"year":"2015","no":1530,"q":"Number of stem villi at term in human placenta is","o":["60","120","240","480"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4312, 'OBG', 'Miscellaneous', 'Moderate', 'Obstetrics', 33, '{"id":4312,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Obstetrics","sourceNo":33,"q":"All are of value in modified Bishop score except","o":["Dilatation","Effacement","Cervical length","Consistency"],"a":1,"e":"Answer- B. Effacement","pyqMatches":[{"year":"2015","no":1528,"q":"All are of value in modified Bishop score except","o":["Dilatation","Effacement","Cervical length","Consistency"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4313, 'OBG', 'Labour & Delivery', 'Hard', 'Obstetrics', 34, '{"id":4313,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Hard","source":"Obstetrics","sourceNo":34,"q":"G2P1L1 female with 1 : 4 anti D titres at 28 weeks gestation, management is","o":["MCA Doppler","Caesarean section","Induction of labour","Amniocentesis"],"a":0,"e":"Answer- A. MCA Doppler If Indirect Coomb''s test is positive in an antenatal patient with Rh negative blood group, and antibody titres >1 : 16 or Ab level > 10 IU/ml","pyqMatches":[{"year":"2015","no":1527,"q":"G2P1L1 female with 1 : 4 anti D titres at 28 weeks gestation, management is","o":["MCA Doppler","Caesarean section","Induction of labour","Amniocentesis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4314, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Obstetrics', 35, '{"id":4314,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Obstetrics","sourceNo":35,"q":"Patient with NTD, dose of folic acid in next pregnancy","o":["0.5 mg","1 mg","2 mg","4 mg"],"a":3,"e":"Answer- D. 4 mg Folic acid supplementation 4 mg daily 1 month before conception to about 12 weeks of pregnancy.","pyqMatches":[{"year":"2015","no":1525,"q":"Patient with NTD, dose of folic acid in next pregnancy","o":["0.5 mg","1 mg","2 mg","4 mg"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4315, 'OBG', 'Infertility & Reproductive Endocrinology', 'Moderate', 'Obstetrics', 36, '{"id":4315,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Moderate","source":"Obstetrics","sourceNo":36,"q":"Kallmans syndrome is associated with all of the following except","o":["Amenorrhea","Excess stimulation of the HPO axis","Genetic mutation","Anosmia"],"a":1,"e":"Answer- B. Excess stimulation of the HPO axis When congenital GnRH deficiency is associated with anosmia or hyposmia (an absent or grossly impaired sense of smell), the disorder is known as Kallmann''s syndrome. Two genetic mutations associated with Kallman''s Syndrome :","pyqMatches":[{"year":"2015","no":1524,"q":"Kallmans syndrome is associated with all of the following except","o":["Amenorrhea","Excess stimulation of the HPO axis","Genetic mutation","Anosmia"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4316, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 37, '{"id":4316,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":37,"q":"Hot flushes are experienced as a result of","o":["Increased noradrenaline","Decreased estrogen","Increased noradrenaline and decreased estrogen","Increased noradrenaline and estrogen"],"a":2,"e":"Answer- C. Increased noradrenaline and decreased estrogen Hot flushes are caused by noradrenaline, which disturbs the thermoregulatory system. Oestrogen deficiency reduces hypothalamic endorphins, which release more norepinephrine and serotonin. This leads to inappropriate heat loss mechanism. Other causes that can be associated with the symptom of hot flushes include: thyroid disease, epilepsy, pheochromocytoma, carcinoid syndromes, autoimmune disorders, mast cell disorders, insulinoma, pancreatic tumours and even leukemias.","pyqMatches":[{"year":"2015","no":1523,"q":"Hot flushes are experienced as a result of","o":["Increased noradrenaline","Decreased estrogen","Increased noradrenaline and decreased estrogen","Increased noradrenaline and estrogen"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4317, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 38, '{"id":4317,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":38,"q":"Cephalic index is","o":["BPD/OFD","BPD/HC","OFD/BPD","HC/FL"],"a":0,"e":"Answer- A. BPD/OFD Cephalic index = BPD / OFD (Biparietal diameter divided by the occipito - frontal diameter)","pyqMatches":[{"year":"2015","no":1521,"q":"Cephalic index is","o":["BPD/OFD","BPD/HC","OFD/BPD","HC/FL"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4318, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Obstetrics', 39, '{"id":4318,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Obstetrics","sourceNo":39,"q":"If the symphysiofundal height is 40 cm and the station of the head is at -1, weight of the fetus is approximately","o":["3 kg","3.3 kg","4 kg","4.3 kg"],"a":3,"e":"Answer- D. 4.3 kg Johnson''s Formula for estimation of fetal weight : Height of the uterus above the symphysis pubis in centimeters minus 12, if the vertex is at or above the level of ischial spines or minus 11, if the vertex is below the level of ischial spines - multiplied by 155 gives the weight in grams. Solution : (40 - 12) x 155 = 4340 gms","pyqMatches":[{"year":"2015","no":1518,"q":"If the symphysiofundal height is 40 cm and the station of the head is at -1, weight of the fetus is approximately","o":["3 kg","3.3 kg","4 kg","4.3 kg"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4319, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 40, '{"id":4319,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":40,"q":"In MRKH syndrome, which among the following is absent?","o":["Vagina","Breast development","Pubic hair development","Testes"],"a":3,"e":"Answer- D. Testes MRKH syndrome is also known as MURCS syndrome (Mullerian agenesis, Renal aplasia and cervicothoracic somite dysplasia). MRKH (Mayer Rokitansky Kuster Hauser) syndrome has a karyotype of 46, XX. So the gonads present are ovaries in contrast to Androgen Insensitivity Syndrome where testes are present. The MRKH syndrome is characterized by congenital aplasia of the uterus and the upper part (2/3) of the vagina in women showing normal development of secondary sexual characteristics and a normal 46, XX karyotype.","pyqMatches":[{"year":"2015","no":1517,"q":"In MRKH syndrome, which among the following is absent?","o":["Vagina","Breast development","Pubic hair development","Testes"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4320, 'OBG', 'Benign Gynecology', 'Easy', 'Obstetrics', 41, '{"id":4320,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Easy","source":"Obstetrics","sourceNo":41,"q":"What is the preferred treatment of complete prolapse in a female with completed family?","o":["Sling surgery","Vaginal hysterectomy","Le Forte''s repair","Pessary"],"a":1,"e":"Answer- B. Vaginal hysterectomy Vaginal hysterectomy is commonly performed for major degree uterine prolapse in a female with completed family.","pyqMatches":[{"year":"2015","no":1516,"q":"What is the preferred treatment of complete prolapse in a female with completed family?","o":["Sling surgery","Vaginal hysterectomy","Le Forte''s repair","Pessary"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4321, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Obstetrics', 42, '{"id":4321,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Obstetrics","sourceNo":42,"q":"Which of the following is not a probable sign of pregnancy","o":["Jacquemier''s sign","Dalrymple sign","Hegar''s sign","Palmer''s sign"],"a":1,"e":"Answer- B. Dalrymple sign Probable signs of pregnancy : Jacquemier''s sign/Chadwick''s sign Osiander''s sign Goodell''s sign Piskacek''s sign Hegar''s sign Palmer''s sign Braxtor-hicks contraction External ballotment Abdominal enlargement Outlining the fetus","pyqMatches":[{"year":"2015","no":1514,"q":"Which of the following is not a probable sign of pregnancy","o":["Jacquemier''s sign","Dalrymple sign","Hegar''s sign","Palmer''s sign"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4322, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 43, '{"id":4322,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":43,"q":"Polyspermy is inhibited by which ion ?","o":["Ca","Na","K","Cl"],"a":0,"e":"Ans, A. Ca The calcium wave amplifies the local signal at the site of sperm- oocyte interaction and distributes it throughout the oocyte cytoplasm. The increase in calcium concentration is the signal that causes the oocyte to resume cell division, initiating the completion of meiosis II and setting of the developmental programme that leads to embryogenesis.","pyqMatches":[{"year":"2014","no":1783,"q":"Polyspermy is inhibited by which ion ?","o":["Ca","Na","K","Cl"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4323, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 44, '{"id":4323,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":44,"q":"Which of the following is present in normal vagina?","o":["Trichomonas buccalis","Trichomonas hominis","Trichomonas vaginalis","Trichomonas bovis"],"a":2,"e":"Ans. C. Trichomonas vaginalis","pyqMatches":[{"year":"2014","no":1784,"q":"Which of the following is present in normal vagina?","o":["Trichomonas buccalis","Trichomonas hominis","Trichomonas vaginalis","Trichomonas bovis"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4324, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 45, '{"id":4324,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":45,"q":"Maximum amniotic fluid at ?","o":["32 weeks","34 weeks","36 weeks","40 weeks"],"a":2,"e":"Ans, C. 36 weeks","pyqMatches":[{"year":"2014","no":1785,"q":"Maximum amniotic fluid at ?","o":["32 weeks","34 weeks","36 weeks","40 weeks"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4325, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 46, '{"id":4325,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":46,"q":"At 20 weeks of gestation amniotic fluid volume is ?","o":["200 ml","400 ml","600 ml","800 ml"],"a":1,"e":"Ans, B. 400 ml","pyqMatches":[{"year":"2014","no":1786,"q":"At 20 weeks of gestation amniotic fluid volume is ?","o":["200 ml","400 ml","600 ml","800 ml"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4326, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 47, '{"id":4326,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":47,"q":"Fertilized ovum reaches the uterus at what day of menstrual cycle?","o":["6th","14th","20th","25th"],"a":2,"e":"Ans, C. 20th Implantation of the fertilized ovum occurs in the endometrium of the anterior or posterior wall of the body near the fundus on the & ilay of fertilization which corresponds to the 20th day of the regular menstrual cycle.","pyqMatches":[{"year":"2014","no":1787,"q":"Fertilized ovum reaches the uterus at what day of menstrual cycle?","o":["6th","14th","20th","25th"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4327, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 48, '{"id":4327,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":48,"q":"Fertilization usually occurs in which part of fallopian tube?","o":["Fimbrial end","Ampulla","Interstitium","Isthmus"],"a":1,"e":"Ans. B. Ampulla Fertilization is the process of fusion of the spermatozoon with the mature ovum. It begins with sperm egg collision and ends with production of a mononucleated single cell called the zygote. Its objectives are:","pyqMatches":[{"year":"2014","no":1788,"q":"Fertilization usually occurs in which part of fallopian tube?","o":["Fimbrial end","Ampulla","Interstitium","Isthmus"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4328, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 49, '{"id":4328,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":49,"q":"Physiologic change in leukocyte numbers in pregnancy is","o":["Neutrophilic leukocytosis","Lymphocytic leukocytosis","Neutropenia","Basophilic leukocytosis"],"a":0,"e":"Ans. A. Neutrophilic leukocytosis Physiological change observed in leukocyte numbers in pregnancy is neutrophilic leukocytosis. It occurs to the tune of 8000/mm3 and may upto 20,000/ mm3 in labour. The increase maybe due to the rise in levels of estrogen and cortisol.","pyqMatches":[{"year":"2014","no":1789,"q":"Physiologic change in leukocyte numbers in pregnancy is","o":["Neutrophilic leukocytosis","Lymphocytic leukocytosis","Neutropenia","Basophilic leukocytosis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4329, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 50, '{"id":4329,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":50,"q":"Weight of uterus at term is ?","o":["400-500 gm","600-700gm","800-900 gm","900-1000 gm"],"a":3,"e":"Ans. D. 900-1000 gm The uterus in the non-pregnant state weight is about 60 gm, with a cavity of 5 - 70 ml and measures about 7.5 cm in length. At term it weighs about 900 - 1000 gm and measures 35 cm in length.","pyqMatches":[{"year":"2014","no":1790,"q":"Weight of uterus at term is ?","o":["400-500 gm","600-700gm","800-900 gm","900-1000 gm"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4330, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 51, '{"id":4330,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":51,"q":"During pregnancy estrogen causes which of the following?","o":["Growth of ducts of breasts","Growth of alveoli of breasts","Both a and b","None of the above"],"a":2,"e":"Ans. C. Both a and b The increased size of the breasts is evident in the early weeks of pregnancy. The increase in size is due to hypertrophy and proliferation of the ducts and the alveoli. Estrogen is responsible for the hypertrophy and proliferation of the ducts and alveoli while progesterone is only responsible for the hypertrophy and proliferation of the alveoli.","pyqMatches":[{"year":"2014","no":1791,"q":"During pregnancy estrogen causes which of the following?","o":["Growth of ducts of breasts","Growth of alveoli of breasts","Both a and b","None of the above"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4331, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 52, '{"id":4331,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":52,"q":"Maternal side layer of the placenta is called ?","o":["Decidua basalis layer","Decidua capsularis layer","Decidua parietalis","Decidua spongiosa"],"a":0,"e":"Ans., A. Decidua basalis layer Decidua basalis (Decidual plate) is the part of endometrium related to embryonic pole of conceptus and forms the maternal p art of placenta.","pyqMatches":[{"year":"2014","no":1792,"q":"Maternal side layer of the placenta is called ?","o":["Decidua basalis layer","Decidua capsularis layer","Decidua parietalis","Decidua spongiosa"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4332, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Obstetrics', 53, '{"id":4332,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Obstetrics","sourceNo":53,"q":"Which of the following is not a physiological change of pregnancy in urinary bladder?","o":["Edematous mucosa","Increased frequency at 14 weeks","Stress incontinence","Pressure on bladder in late pregnancy"],"a":1,"e":"Ans.B. Increased frequency at 14 weeks Physiological changes in bladder in pregnancy Marked congestion and hypertrophy of the muscles and elastic tissues of the bladder wall. Edematous bhdder mucosa in late pregnancy especially in primigravida. Increased frequency of micturition at 6 - 8 weeks which subsides by 12 weeks and reappears in late pregnancy due to pressure of the gravid uterus on bladder. Stress urinary incontinence in late pregnancy.","pyqMatches":[{"year":"2014","no":1793,"q":"Which of the following is not a physiological change of pregnancy in urinary bladder?","o":["Edematous mucosa","Increased frequency at 14 weeks","Stress incontinence","Pressure on bladder in late pregnancy"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4333, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 54, '{"id":4333,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":54,"q":"Urinary retention earliest in pregnancy is seen at ?","o":["10 weeks","18 weeks","22 weeks","34 weeks"],"a":0,"e":"Ans, A. 10 weeks Urinary retention in pregnancy is rare It is classically described in some women with retroverted uterus, which becomes impacted in the pelvis, usually seen earliest between 8 - 12 weeks of pregnancy and causes outflow obstruction.","pyqMatches":[{"year":"2014","no":1794,"q":"Urinary retention earliest in pregnancy is seen at ?","o":["10 weeks","18 weeks","22 weeks","34 weeks"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4334, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 55, '{"id":4334,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":55,"q":"Beta HCG is detected earliest by which day of conception?","o":["8 days","15 days","21 days","30 days"],"a":0,"e":"Ans, A. 8 days hCG is a glycoprotein produced by the syncytiotrophoblast. hCG-c is identical to the c subunit of LH, FSH, and TSH. Its presence in the urine in early pregnancy is the basis of the various laboratory tests for pregnancy, and it can sometimes be detected in the urine as early as 14 d after conception and in serum as early as 8-9 days,","pyqMatches":[{"year":"2014","no":1795,"q":"Beta HCG is detected earliest by which day of conception?","o":["8 days","15 days","21 days","30 days"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4335, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 56, '{"id":4335,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":56,"q":"Doubling time of beta HCG in early pregnancy is ?","o":["24 hrs","48 hrs","72 hrs","96 hrs"],"a":1,"e":"Ans, B. 48 hrs Beta hCG usually double about every 2 days (48 hours) during first four weak of pregnancy. As pregnancy progresses, doubling time becomes longer. By 6-7 weeks beta hCG levels may take as long as 3.5 days to double.","pyqMatches":[{"year":"2014","no":1796,"q":"Doubling time of beta HCG in early pregnancy is ?","o":["24 hrs","48 hrs","72 hrs","96 hrs"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4336, 'OBG', 'Benign Gynecology', 'Easy', 'Obstetrics', 57, '{"id":4336,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Easy","source":"Obstetrics","sourceNo":57,"q":"Tubal patency test in which phase of the menstrual cycle?","o":["Menstrual","Preovulatory","Leuteal","Premenstrual"],"a":1,"e":"Ans, B. Preovulatory The testing of tubal patency and detecting tubal pathology are done in pre-ovulatory phase of the menstrual cycle. If performed in the post-ovulatory period, insufflation might disturb an implanted or fertilized ovum and may also cause pelvic endometriosis.","pyqMatches":[{"year":"2014","no":1797,"q":"Tubal patency test in which phase of the menstrual cycle?","o":["Menstrual","Preovulatory","Leuteal","Premenstrual"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4337, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Obstetrics', 58, '{"id":4337,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Obstetrics","sourceNo":58,"q":"Following physiological changes are seen in vagina in pregnancy except ?","o":["Jacquimiers sign","Increased length of anterior vaginal wall","pH acidic","Decreased number of navicular cells"],"a":3,"e":"Ans, D. Decreased number of navicular cells The vaginal walls become hypertrophied, edematous and more vascular. Increased blood supply to venous plexus surrounding the walls gives bluish coloration of the mucosa (Jacquemier''s sign). The length of the anterior vaginal wall is increased. The secretion of vagina becomes copious, thin and curdy white, due to marked exfoliated cells and bacteria. The pH becomes acidic (3.5 - 6) due to more conversion of glycogen into lactic acid by lactobacillus acidophilus consequent on high estrogen level. The acidic pH prevents multiplication of pathogenic organisms. There is predominance of navicular cells in cluster and plenty of lactobacilli.","pyqMatches":[{"year":"2014","no":1798,"q":"Following physiological changes are seen in vagina in pregnancy except ?","o":["Jacquimiers sign","Increased length of anterior vaginal wall","pH acidic","Decreased number of navicular cells"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4338, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 59, '{"id":4338,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":59,"q":"FHS can be usually heard by stethoscope at ?","o":["14 weeks","18 weeks","22 weeks","26 weeks"],"a":1,"e":"Ans, B. 18 weeks Fetal heart sound (FHS) is most conclusive clinical sign of pregnancy. With an ordinary stethoscope it can be detected between 18 - 20 weeks of PregnancY.","pyqMatches":[{"year":"2014","no":1799,"q":"FHS can be usually heard by stethoscope at ?","o":["14 weeks","18 weeks","22 weeks","26 weeks"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4339, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 60, '{"id":4339,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":60,"q":"What is the fetoplacental relationship at 24 weeks of gestation?","o":["3","4","5","6"],"a":0,"e":"Ans, A. 3 The relationship between the fetal and placental weights can be studied by the so called fetoplacental relationship (fetal weight/ placental weight ratio). The fetoplacental relationship increases as the pregnancy advances.","pyqMatches":[{"year":"2014","no":1800,"q":"What is the fetoplacental relationship at 24 weeks of gestation?","o":["3","4","5","6"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4340, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 61, '{"id":4340,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":61,"q":"Down syndrome is earliest diagnosed at ?","o":["8 - 10 weeks","10 - 12 weeks","12 - 14 weeks","14 - 16 weeks"],"a":1,"e":"Ans. B. 10 - 12 weeks Earliest diagnosis of genetic defects can be done by use of chorionic villous sampling. Chorionic villous sampling is carried out transcervically at 10 - 12 weeks and transabdominally from 10 weeks to term.","pyqMatches":[{"year":"2014","no":1801,"q":"Down syndrome is earliest diagnosed at ?","o":["8 - 10 weeks","10 - 12 weeks","12 - 14 weeks","14 - 16 weeks"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4341, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 62, '{"id":4341,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":62,"q":"Chorionic villus biopsy is done earliest in which week of gestation ?","o":["9 weeks","11 weeks","13 weeks","15 weeks"],"a":1,"e":"Ans, B. 11 weeks It is carried out transcervically between 7O - 12 weeks and transabdominally from 10 weeks to term.","pyqMatches":[{"year":"2014","no":1802,"q":"Chorionic villus biopsy is done earliest in which week of gestation ?","o":["9 weeks","11 weeks","13 weeks","15 weeks"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4342, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 63, '{"id":4342,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":63,"q":"When is folic acid started in pregnancy ?","o":["4 weeks prior to conception","8 weeks prior toconception","4 weeks after conception","8 weeks after conception"],"a":0,"e":"Ans. A. 4 weeks prior to conception Folic acid supplementation (4mg/day) is stated 4 weeks prior to conception and continued upto 12 weeks of pregnancy. This can reduce the incidence of neural tube defects.","pyqMatches":[{"year":"2014","no":1803,"q":"When is folic acid started in pregnancy ?","o":["4 weeks prior to conception","8 weeks prior toconception","4 weeks after conception","8 weeks after conception"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4343, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 64, '{"id":4343,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":64,"q":"Term placenta weight to Baby weight ratio is ?","o":["1 : 3","1 : 4","1 : 5","1 : 6"],"a":3,"e":"Ans, D. 1 : 6 The term Placenta Placenta at term is a circular disc with a diameter of 15 - 20 cm. It has thickness of 3 cm at center and thins of towards the edges. It feels spongy and weighs about 500 gm. The ratio of placemat weight at term and the baby weight is 1:6. It occupies about 30% of the uterine wall.","pyqMatches":[{"year":"2014","no":1804,"q":"Term placenta weight to Baby weight ratio is ?","o":["1 : 3","1 : 4","1 : 5","1 : 6"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4344, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Obstetrics', 65, '{"id":4344,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Obstetrics","sourceNo":65,"q":"First trimester diagnosis for anencephaly is by increased?","o":["Alpha feto protein in maternal serum","Alpha feto protein in amniotic fluid","Beta HCG in maternal serum","Beta HCG in amniotic fluid"],"a":1,"e":"Ans, B. Alpha feto protein in amniotic fluid In the first half of the pregnancy the diagnosis of anencephaly is made by elevated alpha feto protein in amniotic fluid and confirmed by sonography.","pyqMatches":[{"year":"2014","no":1805,"q":"First trimester diagnosis for anencephaly is by increased?","o":["Alpha feto protein in maternal serum","Alpha feto protein in amniotic fluid","Beta HCG in maternal serum","Beta HCG in amniotic fluid"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4345, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 66, '{"id":4345,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":66,"q":"Which of the following is true about EDD ?","o":["Less than 10% of deliveries occur on EDD","Less than 20% of deliveries occur on EDD","80% of the deliveries occur on EDD","90% of the deliveries occur on EDD"],"a":0,"e":"Ans, A. Less than 10% of deliveries occur on EDD Fewer than 5% of all the pregnancies end on the expected date of delitery (EDD). 13% of the births occur preterm. 5 - 7% of the pregnancies are delivered post term. Majority of the deliveries occur within 7 days of EDD.","pyqMatches":[{"year":"2014","no":1806,"q":"Which of the following is true about EDD ?","o":["Less than 10% of deliveries occur on EDD","Less than 20% of deliveries occur on EDD","80% of the deliveries occur on EDD","90% of the deliveries occur on EDD"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4346, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 67, '{"id":4346,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":67,"q":"","o":["Most common position of engagement in vertex presentation?","LOA","ROA","LOP"],"a":0,"e":"Ans, A. LOA Vertex occupying the left anterior quadrant of the pelvis is the commonest and is called left occipito -anterior position.","pyqMatches":[],"pyqYears":[]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4347, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 68, '{"id":4347,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":68,"q":"Which is the engaging diameter in occipitoposterior nresentation?","o":["Suboccipito frontal","Mento vertical","Submentovertical","Bitrochanteric"],"a":0,"e":"Ans, A. Suboccipito frontal","pyqMatches":[{"year":"2014","no":1808,"q":"Which is the engaging diameter in occipitoposterior nresentation?","o":["Suboccipito frontal","Mento vertical","Submentovertical","Bitrochanteric"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4348, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 69, '{"id":4348,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":69,"q":"Which is the most common presentation in twin pregnancy?","o":["Vertex - vertex","Vertex - breech","Breech - Breech","Vertex - Footling"],"a":0,"e":"Ans. A. Vertex - vertex","pyqMatches":[{"year":"2014","no":1809,"q":"Which is the most common presentation in twin pregnancy?","o":["Vertex - vertex","Vertex - breech","Breech - Breech","Vertex - Footling"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4349, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 70, '{"id":4349,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":70,"q":"Direct Occipitoposterior position is a favourable position in which type of pelvis ?","o":["Anthropoid","Android pelvis","Gynaecoid","Mongoloid"],"a":0,"e":"Ans, A. Anthropoid Direct Occipitoposterior position is a favourable position in anthropoid type of pelvis.","pyqMatches":[{"year":"2014","no":1810,"q":"Direct Occipitoposterior position is a favourable position in which type of pelvis ?","o":["Anthropoid","Android pelvis","Gynaecoid","Mongoloid"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4350, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 71, '{"id":4350,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":71,"q":"Persistent OP position is most common in which pelvis?","o":["Android","Gynaecoid","Anthrpoid","Mixed"],"a":0,"e":"Ans, A. Android With android type of pelvis the occipitoPosterior position is common due to funnel shape of the pelvis.","pyqMatches":[{"year":"2014","no":1811,"q":"Persistent OP position is most common in which pelvis?","o":["Android","Gynaecoid","Anthrpoid","Mixed"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4351, 'OBG', 'Labour & Delivery', 'Moderate', 'Obstetrics', 72, '{"id":4351,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Moderate","source":"Obstetrics","sourceNo":72,"q":"Contraindication for induction of labour is all except?","o":["Hypertensive disease of pregnancy","Heart disease of pregnancy","Pelvic tumor","Vasa previa"],"a":0,"e":"Ans. A. Hypertensive disease of pregnancy Hypertensive disease of pregnancy is an indication for induction of labour. Other three are contraindications.","pyqMatches":[{"year":"2014","no":1812,"q":"Contraindication for induction of labour is all except?","o":["Hypertensive disease of pregnancy","Heart disease of pregnancy","Pelvic tumor","Vasa previa"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4352, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Obstetrics', 73, '{"id":4352,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Obstetrics","sourceNo":73,"q":"Medical management of ectopic pregnancy has decreased success if ?","o":["Gestational sac < 3cm","Duration of gestation < 5 weeks","Cardiac activity present","Beta HCG < 8000 IU/L"],"a":2,"e":"Ans. C. Cardiac activity present Medical management of an ectoPic Pregnancy is done when : Patient is hemodynamically stable No evidence of acute intra abdominal bleeding Ready to comply with follow up care Serum beta HCG < 10,000 IU/L Absent embryonic heart activity Diameter of ectopic gestational mass less than 4 cm.","pyqMatches":[{"year":"2014","no":1813,"q":"Medical management of ectopic pregnancy has decreased success if ?","o":["Gestational sac < 3cm","Duration of gestation < 5 weeks","Cardiac activity present","Beta HCG < 8000 IU/L"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4353, 'OBG', 'Miscellaneous', 'Moderate', 'Obstetrics', 74, '{"id":4353,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Obstetrics","sourceNo":74,"q":"All are the prognostic factors of Boer- meisel system except -","o":["Extent of adhesions","Thickness of tubal wall","Size of hydrosalpinx","Infecting organism"],"a":3,"e":"Ans, D. Infecting organism Boer-meisel system of prognostic classification for chronic pelvic inflammatory disease includes: Extent of adhesions Nature of adhesions flimsy or dense Size of hydrosalpinx Macroscopic condition of hydrosalpinx Thickness of tubal wall","pyqMatches":[{"year":"2014","no":1814,"q":"All are the prognostic factors of Boer- meisel system except","o":["Extent of adhesions","Thickness of tubal wall","Size of hydrosalpinx","Infecting organism"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4354, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 75, '{"id":4354,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":75,"q":"Pregnant uterus will compress ureters at ?","o":["Pelvic brim","Uterovesical junction","Trigone","Ureterovesical junction"],"a":0,"e":"Ans, A. Pelvic brim Ureters become atonic due to high progesterone level in pregnancy, Dilatation of the ureter above the pelvic brim with stasis is marked on the right side especially in the primigravidae. It is due to deoxtrorotation of the uterus pressing the right ureter against the pelvic brim and abo due to pressure by right ovarian vein, which crosses the right ureter at right angle.","pyqMatches":[{"year":"2014","no":1815,"q":"Pregnant uterus will compress ureters at ?","o":["Pelvic brim","Uterovesical junction","Trigone","Ureterovesical junction"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4355, 'OBG', 'Labour & Delivery', 'Hard', 'Obstetrics', 76, '{"id":4355,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Hard","source":"Obstetrics","sourceNo":76,"q":"Following is given to a patient with pre term labour exept -","o":["Glucocorticoids","Tocolytic drugs","Antibiotics","Beta blocker"],"a":3,"e":"Ans. D. Beta blocker Tocolytic drugs [Note: betamimetic and not beta blocker is a tocolytic]","pyqMatches":[{"year":"2014","no":1816,"q":"Following is given to a patient with pre term labour exept","o":["Glucocorticoids","Tocolytic drugs","Antibiotics","Beta blocker"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4356, 'OBG', 'Postpartum & Puerperium', 'Easy', 'Obstetrics', 77, '{"id":4356,"subject":"OBG","chapter":"Postpartum & Puerperium","difficulty":"Easy","source":"Obstetrics","sourceNo":77,"q":"Most common cause of tenth day post partum bleeding?","o":["Retained bits of membrane","Infection","Endometritis","Blood coagulopathy"],"a":0,"e":"Ans. A. Retained bits of membrane Postpartum hemorrhage (PPH) is defined as blood loss of more than 500 ml following birth of baby.","pyqMatches":[{"year":"2014","no":1817,"q":"Most common cause of tenth day post partum bleeding?","o":["Retained bits of membrane","Infection","Endometritis","Blood coagulopathy"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4357, 'OBG', 'Labour & Delivery', 'Hard', 'Obstetrics', 78, '{"id":4357,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Hard","source":"Obstetrics","sourceNo":78,"q":"A multgravida 4 kg fetus is in labour since 15 hours and has 5cm dilation of cervix for last 8 hours. What is the further management of this patient ?","o":["Wait and watch","Amniotomy","Injection Oxytocin","Caesarian section"],"a":3,"e":"Ans. D. Caesarian section","pyqMatches":[{"year":"2014","no":1818,"q":"A multgravida 4 kg fetus is in labour since 15 hours and has 5cm dilation of cervix for last 8 hours. What is the further management of this patient ?","o":["Wait and watch","Amniotomy","Injection Oxytocin","Caesarian section"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4358, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 79, '{"id":4358,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":79,"q":"The treatment of choice for bartholin cyst is ?","o":["Marsupilisation","Aspiration","Observe","Curettage and closure"],"a":0,"e":"Ans. A. Marsupilisation Bartholin''s cyst Bartholin''s cyst is formed when duct of bartholins gland is blocked either by inflammation or by inspissated secretion. It appears as a swelling on the inner side of the junction of the anterior two-thirds with the posterior one-third of the labium majus. A small cyst remains asymptomatic, but a larger one bulges across the vaginal introitus and causes dyspareunia, discomfort and may get infected when it needs excision or marsupialization","pyqMatches":[{"year":"2014","no":1819,"q":"The treatment of choice for bartholin cyst is ?","o":["Marsupilisation","Aspiration","Observe","Curettage and closure"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4359, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 80, '{"id":4359,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":80,"q":"Gartner''s cyst are seen at ?","o":["Antero lateral vaginal wall","Antero - lateral cervix","Posterolateral vaginal wall","Posterolateral cervix"],"a":0,"e":"Ans, A,’. Antero lateral vaginal wall Gartners duct cyst arises from the remnants of the mesotephric duct and lies in the anterolateral aspect of vaginal wall.","pyqMatches":[{"year":"2014","no":1820,"q":"Gartner''s cyst are seen at ?","o":["Antero lateral vaginal wall","Antero - lateral cervix","Posterolateral vaginal wall","Posterolateral cervix"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4360, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 81, '{"id":4360,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":81,"q":"Most common cause of death of baby in vasa previa is?","o":["Infection","Maternal exanguination","Fetal exanguination","Both b and c"],"a":2,"e":"Ans, C. Fetal exanguination Vasa previa In it a leash of blood vessels happen to traverse through the membranes overlying the internal os, in front of presenting part. Rupture of membranes involving the overlying vessels leads to vaginal bleeding. As it is entirely fetal blood, this may result in fetal exanguination and even death.","pyqMatches":[{"year":"2014","no":1821,"q":"Most common cause of death of baby in vasa previa is?","o":["Infection","Maternal exanguination","Fetal exanguination","Both b and c"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4361, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 82, '{"id":4361,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":82,"q":"Sheehan syndrome is ?","o":["Pitutary adenoma","Pitutary necrosis","Adrenal necrosis","Adrenal adenoma"],"a":1,"e":"Ans., B. Pitutary necrosis Sheehan''s syndrome is anterior pituitory necrosis following severe PPH, shock or severe infection.","pyqMatches":[{"year":"2014","no":1822,"q":"Sheehan syndrome is ?","o":["Pitutary adenoma","Pitutary necrosis","Adrenal necrosis","Adrenal adenoma"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4362, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Obstetrics', 83, '{"id":4362,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Obstetrics","sourceNo":83,"q":"Most common cause of menorrhagia in adolescents?","o":["Thyroid disorder","Coagulation disorders","Leiomyomas","Polyps"],"a":1,"e":"Ans, B. Coagulation disorders In adolescent age group, abnormal uterine bleeding results from anovulation and coagulation defects at disproportionately higher rates compared with older reproductive-aged women Coagulation disorders account for 20% of cases of menorrhagia in adolescents.","pyqMatches":[{"year":"2014","no":1823,"q":"Most common cause of menorrhagia in adolescents?","o":["Thyroid disorder","Coagulation disorders","Leiomyomas","Polyps"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4363, 'OBG', 'Gynecologic Oncology', 'Moderate', 'Obstetrics', 84, '{"id":4363,"subject":"OBG","chapter":"Gynecologic Oncology","difficulty":"Moderate","source":"Obstetrics","sourceNo":84,"q":"Not associated with endometrial hyperplasia ?","o":["PCOD","Glucose intolerance","HRT","Unopposed exposure to progesterone"],"a":3,"e":"Ans. D. Unopposed exposure to progesterone Following are the causes of endometrial hyperplasia Follicular cysts of ovary PCOD Granulosa and theca cell tumors of ovary HRT Glucose in tolerance Unopposed exposure to estrogen (endogenous or exogenous)","pyqMatches":[{"year":"2014","no":1824,"q":"Not associated with endometrial hyperplasia ?","o":["PCOD","Glucose intolerance","HRT","Unopposed exposure to progesterone"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4364, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Obstetrics', 85, '{"id":4364,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Obstetrics","sourceNo":85,"q":"Following are the causes of maternal deaths in patients with hypertensive disorder of pregnanacy except ?","o":["Cardiac failure","ARDS","Chronic renal failure","Cerebral hemorrhage"],"a":2,"e":"Ans. C. Chronic renal failure Causes of maternal deaths in cases of hypertensive disorders of pregnancy are Cardiac failure Cerebral hemorrhage ARDS Puerperal sepsis Pulmonary edema Acute renal failure Pulmonary embolism Aspiration and/or septic pneumonia Cardio-pulmonary arrest Post-partum shock","pyqMatches":[{"year":"2014","no":1825,"q":"Following are the causes of maternal deaths in patients with hypertensive disorder of pregnanacy except ?","o":["Cardiac failure","ARDS","Chronic renal failure","Cerebral hemorrhage"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4365, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Obstetrics', 86, '{"id":4365,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Obstetrics","sourceNo":86,"q":"Classical name of mid cycle abdominal pain with vaginal bleeding is called ?","o":["Endometriosis","Mittelschmez","Meteropathiahemorrhagica","Menometrorrhagia"],"a":1,"e":"Ans. B. Mittelschmez Mittelschmerz is a mid-cycle pain, not lasting more than 12-24 hours, around ovulation. Pain is located in one of the iliac fossa and may be accompanied with vaginal bleeding.","pyqMatches":[{"year":"2014","no":1826,"q":"Classical name of mid cycle abdominal pain with vaginal bleeding is called ?","o":["Endometriosis","Mittelschmez","Meteropathiahemorrhagica","Menometrorrhagia"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4366, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 87, '{"id":4366,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":87,"q":"Following is true about leuteoma of pregnancy ?","o":["Usually bilateral","It is a benign self limiting condition","It consists of leutenized cells","All the above"],"a":3,"e":"Ans. D. All the above Leuteoma of Pregnancy It usually appears as bilateral, multinodular, solid masses in ovaries. It is characterized by replacement of normal ovarian parenchyma by solid proliferation of leutenized stromal cells under influence of human chorionic gonadotroPin. It is benign self-limiting condition and requires no treatment.","pyqMatches":[{"year":"2014","no":1827,"q":"Following is true about leuteoma of pregnancy ?","o":["Usually bilateral","It is a benign self limiting condition","It consists of leutenized cells","All the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4367, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 88, '{"id":4367,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":88,"q":"Clinical alarming sign of MgSO4 toxicity is ?","o":["Loss of knee jerk","Loss of superficial abdominal reflexes","Loss of pin prick sensation","Loss of proprioception"],"a":0,"e":"Ans. A. Loss of knee jerk","pyqMatches":[{"year":"2014","no":1828,"q":"Clinical alarming sign of MgSO4 toxicity is ?","o":["Loss of knee jerk","Loss of superficial abdominal reflexes","Loss of pin prick sensation","Loss of proprioception"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4368, 'OBG', 'Antenatal Care & Complications', 'Easy', 'Obstetrics', 89, '{"id":4368,"subject":"OBG","chapter":"Antenatal Care & Complications","difficulty":"Easy","source":"Obstetrics","sourceNo":89,"q":"False about MgSo4 is ?","o":["Not used as antihypertensive","Its dose is different for eclampsia and preeclampsia","Deep tendon reflexes is monitored for toxicity","It acts as a membrane stabilizer and neuroprotector"],"a":1,"e":"Ans. B. Its dose is different for eclampsia and preeclampsia Dose of magnesium sulphate for management of pre-eclampsia and eclampsia is the same.","pyqMatches":[{"year":"2014","no":1829,"q":"False about MgSo4 is ?","o":["Not used as antihypertensive","Its dose is different for eclampsia and preeclampsia","Deep tendon reflexes is monitored for toxicity","It acts as a membrane stabilizer and neuroprotector"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4369, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Obstetrics', 90, '{"id":4369,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Obstetrics","sourceNo":90,"q":"18 weeks pregnancy of a lady, last two times history of midtrimester abortion, which was painless. What is the diagnosis ?","o":["Incompetent os","Chromosomal abnormality","Bivalve uterus","Progesterone deficiency"],"a":0,"e":"Ans. A. Incompetent os Most common cause of second trimester pregnancy loss is cervical incompetence, in which patient presents with recurrent painless abortion.","pyqMatches":[{"year":"2014","no":1830,"q":"18 weeks pregnancy of a lady, last two times history of midtrimester abortion, which was painless. What is the diagnosis ?","o":["Incompetent os","Chromosomal abnormality","Bivalve uterus","Progesterone deficiency"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4370, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 91, '{"id":4370,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":91,"q":"Following are the features of true labour pain ?","o":["Uterine contractions at regular intervals","Progressive effacement and dilation of cervix","Formation of bag of membranes","All the above"],"a":3,"e":"Ans. D. All the above Features of true labour Pains Uterine contractions at regular intervals Frequency of contractions increase gradually Intensity and duration of contractions increase progressively Associated with show Progressive effacement and dilation of cervix Descent of the presenting part Formation of bag of forewaters Not relieved by enema and sedatives","pyqMatches":[{"year":"2014","no":1831,"q":"Following are the features of true labour pain ?","o":["Uterine contractions at regular intervals","Progressive effacement and dilation of cervix","Formation of bag of membranes","All the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4371, 'OBG', 'Gynecologic Oncology', 'Easy', 'Obstetrics', 92, '{"id":4371,"subject":"OBG","chapter":"Gynecologic Oncology","difficulty":"Easy","source":"Obstetrics","sourceNo":92,"q":"HRT improves ?","o":["Bone density","Demetia","Coronary artery disease","Endometrial cancer"],"a":0,"e":"Ans, A. Bone density Hormone replacement therapy improves bone density,","pyqMatches":[{"year":"2014","no":1832,"q":"HRT improves ?","o":["Bone density","Demetia","Coronary artery disease","Endometrial cancer"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4372, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 93, '{"id":4372,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":93,"q":"Most common risk factor for rupture of scarred uterus is","o":["Use of oxytocin in labour","Grand multiparity","Forceps application","Obstructed labour"],"a":0,"e":"Ans, A. Use of oxytocin in labour The most common cause of rupture of scarred uterus k use of high doses of oxytocin for the augmuntation of labour.","pyqMatches":[{"year":"2014","no":1833,"q":"Most common risk factor for rupture of scarred uterus is","o":["Use of oxytocin in labour","Grand multiparity","Forceps application","Obstructed labour"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4373, 'OBG', 'Miscellaneous', 'Hard', 'Obstetrics', 94, '{"id":4373,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Hard","source":"Obstetrics","sourceNo":94,"q":"Invalueable tool in the diagnosis of chronic pelvic pain is ?","o":["Endometrial biopsy","Ultrasound","Laparoscopy","Colposcopy"],"a":2,"e":"Ans, C. Laparoscopy Laproscopy is an invalueable diagnostic tool in the investigation of chronic pelvic pain.","pyqMatches":[{"year":"2014","no":1834,"q":"Invalueable tool in the diagnosis of chronic pelvic pain is ?","o":["Endometrial biopsy","Ultrasound","Laparoscopy","Colposcopy"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4374, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 95, '{"id":4374,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":95,"q":"Most common site of ectopic pregnancy is ?","o":["Ovary","Fallopian tube","Peritoneum","Cervix"],"a":1,"e":"Ans. B. Fallopian tube","pyqMatches":[{"year":"2013","no":1616,"q":"Most common site of ectopic pregnancy is","o":["Tubal","Abdominal","Ovarian","Uterine"],"a":0,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":1835,"q":"Most common site of ectopic pregnancy is ?","o":["Ovary","Fallopian tube","Peritoneum","Cervix"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4375, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 96, '{"id":4375,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":96,"q":"Least common site of ectopic pregnancy in fallopian tubes is ?","o":["Interstitium","Ampulla","Infundibulum","Isthumus"],"a":0,"e":"Ans, A. Interstitium Most common site for ectopic pregnancy fallopian tubes,","pyqMatches":[{"year":"2014","no":1836,"q":"Least common site of ectopic pregnancy in fallopian tubes is ?","o":["Interstitium","Ampulla","Infundibulum","Isthumus"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4376, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 97, '{"id":4376,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":97,"q":"Criteria for Puerperal pyrexia is temperature ?","o":["100.4 degrees F on two separate occasions","101 degrees F on two separate occasions","100.4 degrees F on three separate occasions","101 degrees F on three separate occasions"],"a":0,"e":"Ans, A. 100.4 degrees F on two separate occasions Puerperal pyrexia A rise of temperature reaching 100.4 degrees F (38 degrees C) or more (measured orally) on two separate occasions at 24 hours apart (excluding first 24 hours) within first 10 days following delivery is called puerperal pyrexia.","pyqMatches":[{"year":"2014","no":1837,"q":"Criteria for Puerperal pyrexia is temperature ?","o":["100.4 degrees F on two separate occasions","101 degrees F on two separate occasions","100.4 degrees F on three separate occasions","101 degrees F on three separate occasions"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4377, 'OBG', 'Miscellaneous', 'Hard', 'Obstetrics', 98, '{"id":4377,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Hard","source":"Obstetrics","sourceNo":98,"q":"Investigation of choice for diagnosis of PID is ?","o":["Laparoscopy","Colposcopy","Hysteroscopy","Ultrasonography"],"a":0,"e":"Ans, A. Laparoscopy Laparoscopy is considered the investigation of choice for the diagnosis of pelvic inflammatory disease.","pyqMatches":[{"year":"2014","no":1838,"q":"Investigation of choice for diagnosis of PID is ?","o":["Laparoscopy","Colposcopy","Hysteroscopy","Ultrasonography"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4378, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Obstetrics', 99, '{"id":4378,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Obstetrics","sourceNo":99,"q":"Which drug is preferred for the treatement of 21 hydroxylase deficient female fetus to prevent genital virilization?","o":["Materal cortisol","Maternal dexamethasone","Maternal hydrocortisone","Maternal methylprednisolone"],"a":1,"e":"Ans, b. Maternal dexamethasone Fetus is at risk of CAH maternal dexamethasone therapy can suppress the fetal HPA axis and prevent genital virilization in affected female fetus.","pyqMatches":[{"year":"2014","no":1839,"q":"Which drug is preferred for the treatement of 21 hydroxylase deficient female fetus to prevent genital virilization?","o":["Materal cortisol","Maternal dexamethasone","Maternal hydrocortisone","Maternal methylprednisolone"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4379, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 100, '{"id":4379,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":100,"q":"Speilberg criteria is used for ?","o":["Ovarian pregnancy","Ovarian malignancy","Cervical pregnancy","Cervical malignancy"],"a":0,"e":"Ans, A. Ovarian pregnancy","pyqMatches":[{"year":"2014","no":1840,"q":"Speilberg criteria is used for ?","o":["Ovarian pregnancy","Ovarian malignancy","Cervical pregnancy","Cervical malignancy"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4380, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 101, '{"id":4380,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":101,"q":"Main factor responsible for increased perinatal mortality in twin pregnancy is ?","o":["Prematurity","IUGR","Polyhydramnios","Uterine rupture"],"a":0,"e":"Ans, A. Prematurity","pyqMatches":[{"year":"2014","no":1841,"q":"Main factor responsible for increased perinatal mortality in twin pregnancy is ?","o":["Prematurity","IUGR","Polyhydramnios","Uterine rupture"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4381, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 102, '{"id":4381,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":102,"q":"Cryptomenorrhoea is a feature of ?","o":["Vaginal atresia","Turner syndrome","Empty sella syndrome","Gonadal agenesis"],"a":0,"e":"Ans, A. Vaginal atresia","pyqMatches":[{"year":"2014","no":1842,"q":"Cryptomenorrhoea is a feature of ?","o":["Vaginal atresia","Turner syndrome","Empty sella syndrome","Gonadal agenesis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4382, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Obstetrics', 103, '{"id":4382,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Obstetrics","sourceNo":103,"q":". Which of the following antiepileptic drug is associated with causing congenital heart disease in fetus?","o":["Barbiturates","Valproate","Carbamazepine","Phenytoin"],"a":0,"e":"Ans. A. Barbiturates","pyqMatches":[{"year":"2014","no":1843,"q":". Which of the following antiepileptic drug is associated with causing congenital heart disease in fetus?","o":["Barbiturates","Valproate","Carbamazepine","Phenytoin"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4383, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 104, '{"id":4383,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":104,"q":"Engagement of head in labour means ?","o":["Smallest horizontal plane of the presenting part has crossed the pelvic brim","Greatest horizontal plane of the presenting part has crossed the pelvic brim","Smallest horizontal plane of the presenting part has crossed the pelvic outlet","Greatest horizontal plane of the presenting part has crossed the pelvic outlet"],"a":1,"e":"Ans. B. Greatest horizontal plane of the presenting part has crossed the pelvic brim When the greatest horizontal plane of the presenting part has passed the plane of pelvic brim the presenting part is said to be engaged.","pyqMatches":[{"year":"2014","no":1844,"q":"Engagement of head in labour means ?","o":["Smallest horizontal plane of the presenting part has crossed the pelvic brim","Greatest horizontal plane of the presenting part has crossed the pelvic brim","Smallest horizontal plane of the presenting part has crossed the pelvic outlet","Greatest horizontal plane of the presenting part has crossed the pelvic outlet"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4384, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 105, '{"id":4384,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":105,"q":"USG of 28 weeks gestation showing oligohydramnios is likely to be due to ?","o":["Gastroinstestinal obstruction","Renal pathway obstruction","Anencephyaly","Neuromuscular disorder"],"a":1,"e":"Ans, B. Renal pathway obstruction Urinarytract obstruction is an important cause of oligohydramnios.","pyqMatches":[{"year":"2013","no":1565,"q":"USG of 28 weeks gestation showing oligohydramnios is likely to be due to ?","o":["Gastroinstestinal obstruction","Renal pathway obstruction","Anencephyaly","Neuromuscular disorder"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4385, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Obstetrics', 106, '{"id":4385,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Obstetrics","sourceNo":106,"q":"Anovulatory DUB is due to ?","o":["Absence of progesterone","Excess of estrogen","Hypothalmic pitutary defect","High progesterone"],"a":0,"e":"Ans. A. Absence of progesterone No progesterone is produced when ovulation does not occur, and thus proliferative endometrium persists. At the tissue level, persistent proliferative endometrium is often associated with stromal breakdown, decreased spiral arteriole density, and increased dilated and unstable venous capillaries. At the cellular level, the availability of arachidonic acid is reduced, and prostaglandin production is impaired. For these reasons, bleeding associated with anovulation is thought to result from changes in endometrial vascular structure and in prostaglandin concentration, and from an increased endometrial responsiveness to vasodilating prostaglandins.","pyqMatches":[{"year":"2013","no":1566,"q":"Anovulatory DUB is due to ?","o":["Absence of progesterone","Excess of estrogen","Hypothalmic pitutary defect","High progesterone"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4386, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 107, '{"id":4386,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":107,"q":"In carcinoma cervix surgery to retain conception is done in which stage ?","o":["1B1","1B2","2A","2B"],"a":0,"e":"Ans. A. 1B1 Concepts is retained upto term only in stage I A1. In other stages, hysterectomy is done with fetus left in situ (if it is not viable); or delivery of fetus by classic cesarean hysterectomy followed by radiation (if fetus is viable).","pyqMatches":[{"year":"2013","no":1567,"q":"In carcinoma cervix surgery to retain conception is done in which stage ?","o":["1B1","1B2","2A","2B"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4387, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 108, '{"id":4387,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":108,"q":"Bishop scoring is done for ?","o":["Exchange transfusion in newborn","Induction of labour","Ventilation of Newborn","Gestation of Newborn"],"a":1,"e":"Ans. B. Induction of labour Bishop score, also Bishop''s score, also known as cervix score is a pre-labor scoring system to assist in predicting whether induction of labor will be required.","pyqMatches":[{"year":"2013","no":1568,"q":"Bishop scoring is done for ?","o":["Exchange transfusion in newborn","Induction of labour","Ventilation of Newborn","Gestation of Newborn"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4388, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 109, '{"id":4388,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":109,"q":"Teratozoospermia refers to?","o":["Absence of semen","Absence of sperm","All dead sperms in ejaculate","Morphologically defective sperms"],"a":3,"e":"Ans. D. Morphologically defective sperms","pyqMatches":[{"year":"2013","no":1569,"q":"Teratozoospermia refers to?","o":["Absence of semen","Absence of sperm","All dead sperms in ejaculate","Morphologically defective sperms"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4389, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 110, '{"id":4389,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":110,"q":"Bispinous diameter in anatomic outlet ?","o":["10.5 cm","11 cm","11.5 cm","12 cm"],"a":1,"e":"Ans. B. 11 cm Anatomical outlet Antero-posterior (13 cm) Distance between lower border of symphysis pubis to the tip of coccyx. Transverse diameter (bispinous- 11 cm) Distance between the inner borders of ischialtuberosities Posterior sagittal diameter (8.5 cm) Distance between sacroccygeal joint and anterior margin of anus.","pyqMatches":[{"year":"2013","no":1571,"q":"Bispinous diameter in anatomic outlet ?","o":["10.5 cm","11 cm","11.5 cm","12 cm"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4390, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 111, '{"id":4390,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":111,"q":"Most suitable type of pelvis in female ?","o":["Gynaecoid","Android","Anthropoid","Platypelloid"],"a":0,"e":"Ans. A. Gynaecoid Gynaecoid pelvis round in shape & is most spacious.","pyqMatches":[{"year":"2013","no":1572,"q":"Most suitable type of pelvis in female ?","o":["Gynaecoid","Android","Anthropoid","Platypelloid"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4391, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 112, '{"id":4391,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":112,"q":"Which pelvis is associated with DTA ?","o":["Android","Antrhropoid","Platypelloid","Gynaecoid"],"a":0,"e":"Ans. A. Android","pyqMatches":[{"year":"2013","no":1573,"q":"Which pelvis is associated with DTA ?","o":["Android","Antrhropoid","Platypelloid","Gynaecoid"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4392, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 113, '{"id":4392,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":113,"q":"In obstructive labor most important parameter is?","o":["Diameter of pelvic inlet","Diameter of pelvic outlet","Biparietal diameter","Bitemporal diameter"],"a":1,"e":"Ans. B. Diameter of pelvic outlet The narrowest diameter for the fetus to pass through is pelvic outlet.","pyqMatches":[{"year":"2013","no":1574,"q":"In obstructive labor most important parameter is?","o":["Diameter of pelvic inlet","Diameter of pelvic outlet","Biparietal diameter","Bitemporal diameter"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4393, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 114, '{"id":4393,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":114,"q":"Maximum diameter that passed through maternal pelvis ?","o":["Suboccipital bregmatic","Biparietal","Suboccipital frontal","Occipito frontal"],"a":1,"e":"Ans, B. Biparietal Occipitofrontal is large diameter and deflexed head may complicate as deep transverse arrest and obstructed labour. In case of spacious gynaecoid and anthropoid pelvis it ends up in face to pubis delivery. Mento-vertical is the largest diameter but it cannot pass through the maternal pelvis.","pyqMatches":[{"year":"2013","no":1575,"q":"Maximum diameter that passed through maternal pelvis ?","o":["Suboccipital bregmatic","Biparietal","Suboccipital frontal","Occipito frontal"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4394, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 115, '{"id":4394,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":115,"q":"Semen examination can be done ?","o":["Immediately in semi solid form","After liquefaction","Within 15-30 minutes of liquefaction","11/2 - 2 hr irrespective of liquefaction"],"a":3,"e":"Ans. D. 11/2 - 2 hr irrespective of liquefaction Semen analysis Best specimen obtained by masturbation 3-5 days of abstinence is best, not more than that Specimen should be examined within 1 1/2 - 2hr Liquefaction usually completes within 15-20 min and if delayed it indicates prostatic dysfunction. Thus during semen analysis timing of liquefaction is important but timing of analysis is not set according to liquefaction.","pyqMatches":[{"year":"2013","no":1576,"q":"Semen examination can be done ?","o":["Immediately in semi solid form","After liquefaction","Within 15-30 minutes of liquefaction","11/2 - 2 hr irrespective of liquefaction"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4395, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 116, '{"id":4395,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":116,"q":"Lithotomy position increases vaginal opening by how many cm -","o":["1cm","2cm","3cm","4cm"],"a":1,"e":"Ans. B. 2cm In dorsal lithotomy position, the antero-posterior diameter of the outlet may be increased to 1.5-2 cm. Furthermore, the coccyx is pushed back while the head ilescends down to the perineum.","pyqMatches":[{"year":"2013","no":1577,"q":"Lithotomy position increases vaginal opening by how many cm","o":["1cm","2cm","3cm","4cm"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4396, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Obstetrics', 117, '{"id":4396,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Obstetrics","sourceNo":117,"q":"Endometrial biopsy is usually done at ?","o":["Just before menstruation","10-12 days after menstruation","Just after menstruation","At the time of ovulation"],"a":0,"e":"Ans. A. Just before menstruation","pyqMatches":[{"year":"2013","no":1578,"q":"Endometrial biopsy is usually done at ?","o":["Just before menstruation","10-12 days after menstruation","Just after menstruation","At the time of ovulation"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4397, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 118, '{"id":4397,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":118,"q":"Oligomenorrhoea means ?","o":["Cycle < 20 days","Cycle more than 45 days","Cycle more than 28 days","Cycle more than 35 days"],"a":3,"e":"Ans. D. Cycle more than 35 daysnee","pyqMatches":[{"year":"2013","no":1579,"q":"Oligomenorrhoea means ?","o":["Cycle < 20 days","Cycle more than 45 days","Cycle more than 28 days","Cycle more than 35 days"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4398, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 119, '{"id":4398,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":119,"q":"Magnification obtained by colposcopy is ?","o":["1-2 times","5-6 times","15-25 times","10-20 times"],"a":3,"e":"Ans. D. 10-20 times Colposcope provides a magnification of 10-20 times. Colpomicroscopeprovides a magnification 100-300 times.","pyqMatches":[{"year":"2013","no":1580,"q":"Magnification obtained by colposcopy is ?","o":["1-2 times","5-6 times","15-25 times","10-20 times"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4399, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Obstetrics', 120, '{"id":4399,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Obstetrics","sourceNo":120,"q":"On which day LH & FSH should be measured ?","o":["1-3rd day","7th day","14th day","10th day"],"a":0,"e":"Ans. A. 1-3rd day Level of the hormone FSH, LH and estradiol arc measured on day 3 in infertility workup. An elevated FSH level on day 3 is an indication of poor ovarian reserve. Hormonal assessment FSH/LH developingfollicle producesestrogen which signals the hypothalamus to increase or reduce the amount of FSH produced by the pituitary gland. When good follicles are not developingestrogen levels are lower and more FSH is produced. This leak to higher level of FSH on day 3. Day 3 FSH fertility test b not the only parameter used to assess ovarian reserve.","pyqMatches":[{"year":"2013","no":1581,"q":"On which day LH & FSH should be measured ?","o":["1-3rd day","7th day","14th day","10th day"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4400, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 121, '{"id":4400,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":121,"q":"Best parameter for estimation of fetal age by ultrasound in 3rd trimester is ?","o":["Femur length","BPD","Abdominal circuference","Intraoccular distanc"],"a":0,"e":"Ans. A. Femur length Best parameters for estimation of fetal age by ultrasound 1st trimester – Crown Rump length (CRL) 2nd trimester - Corrected biparietal diameter (cBPD) or head circumference (HC) 3d trimester - Head circumference and femur length Overall - Crown rump length","pyqMatches":[{"year":"2013","no":1582,"q":"Best parameter for estimation of fetal age by ultrasound in 3rd trimester is ?","o":["Femur length","BPD","Abdominal circuference","Intraoccular distanc"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4401, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 122, '{"id":4401,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":122,"q":"Commonest variety of compound presentation is ?","o":["Head with hand","Head with foot","Head with both foot","Head, hand & foot"],"a":0,"e":"Ans. A. Head with hand When a cePhalic presentation is complicated by the presence of a hand or a foot or both alongside the head or presence of one orboth hands by the side of the breech it is called compound presentation. Commonest variety of compound presentation - Head with hand Rarest variety of compound presentation - Head with hand and foot both.","pyqMatches":[{"year":"2013","no":1583,"q":"Commonest variety of compound presentation is ?","o":["Head with hand","Head with foot","Head with both foot","Head, hand & foot"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4402, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 123, '{"id":4402,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":123,"q":"Hegar sign?","o":["Uterine contraction","Quickening","Bluish discoloration of vagina","Softening of isthmus"],"a":3,"e":"Ans. D. Softening of isthmus Hegars sign Present in 2/3 of cases. Demonstrated in 6-10 week Signs is based on the fad that:","pyqMatches":[{"year":"2013","no":1584,"q":"Hegar sign?","o":["Uterine contraction","Quickening","Bluish discoloration of vagina","Softening of isthmus"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4403, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 124, '{"id":4403,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":124,"q":"Pregnant women going for long journey & prolonged sitting is associated with danger of ?","o":["Thromboembolism","Seat belt compression","Preterm labor","Bleeding"],"a":0,"e":"Ans. A. Thromboembolism Prolonged sitting in car or aeroplane is avoided due to venous stasis or thromboembolism.","pyqMatches":[{"year":"2013","no":1585,"q":"Pregnant women going for long journey & prolonged sitting is associated with danger of ?","o":["Thromboembolism","Seat belt compression","Preterm labor","Bleeding"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4404, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 125, '{"id":4404,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":125,"q":"Head of baby is removed in breech delivery by which maneuver ?","o":["Lovsets maneover","Pinards maneover","Prague","Burn Marshall method"],"a":3,"e":"Ans. D. Burn Marshall method","pyqMatches":[{"year":"2013","no":1586,"q":"Head of baby is removed in breech delivery by which maneuver ?","o":["Lovsets maneover","Pinards maneover","Prague","Burn Marshall method"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4405, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 126, '{"id":4405,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":126,"q":"Prague manuever is used for ?","o":["After coming head in breech","Deep transverse assest","Extraction of extended arms","External cephalic version"],"a":0,"e":"Ans. A. After coming head in breech Sometimes the head rotatesposteriorly so, that the face is behind the pubis. Delivery in this position is difficult and ''Prague maneuver'' may be tried.","pyqMatches":[{"year":"2013","no":1587,"q":"Prague manuever is used for ?","o":["After coming head in breech","Deep transverse assest","Extraction of extended arms","External cephalic version"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4406, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Obstetrics', 127, '{"id":4406,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Obstetrics","sourceNo":127,"q":"Trial of labour in previous casearian section can be done in ?","o":["Placenta previa type III","Previous two classical casearian section","Suspected CPD","Previous caesarian section with adequate pelvis"],"a":3,"e":"Ans. D. Previous caesarian section with adequate pelvis Adequate pelvis is an indication oftrial oflabour. Other three options are contraindications.","pyqMatches":[{"year":"2013","no":1588,"q":"Trial of labour in previous casearian section can be done in ?","o":["Placenta previa type III","Previous two classical casearian section","Suspected CPD","Previous caesarian section with adequate pelvis"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4407, 'OBG', 'Labour & Delivery', 'Moderate', 'Obstetrics', 128, '{"id":4407,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Moderate","source":"Obstetrics","sourceNo":128,"q":"Hematoma during labour is not due to ?","o":["Improper haemostasis","Extension of cervical laceration","Rupture of paravaginal venous plexus","Obliteration of dead space while suturing vaginal wall"],"a":3,"e":"Ans. D. Obliteration of dead space while suturing vaginal wall Failure of obliteration of dead space causes hematoma (not obliteration of dead space).","pyqMatches":[{"year":"2013","no":1589,"q":"Hematoma during labour is not due to ?","o":["Improper haemostasis","Extension of cervical laceration","Rupture of paravaginal venous plexus","Obliteration of dead space while suturing vaginal wall"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4408, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 129, '{"id":4408,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":129,"q":"Treatment of jaundice in third trimester ?","o":["Termination of pregnancy","Termination at 42 weeks","Termination at 38 weeks","Wait for spontaeous labour"],"a":2,"e":"Ans, C. Termination at 38 weeks In patients of intrahepatic cholestasis of pregnancy there is increased perinatal mortality. Hence fetal surveillance is done with biweekly NST. Conventional antepartum testing does not predict fetal mortality as there is sudden death in cholestasis due to acute hypoxia. Hence delivery is recommended at 37-38 weeks. In those patients with jaundice with S bilirubin > 1.8 mg%, termination ofpregnancy should be done at 36 weeks.","pyqMatches":[{"year":"2013","no":1590,"q":"Treatment of jaundice in third trimester ?","o":["Termination of pregnancy","Termination at 42 weeks","Termination at 38 weeks","Wait for spontaeous labour"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4409, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 130, '{"id":4409,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":130,"q":"Rate of turnover of amniotic fluid is ?","o":["500 cc/h","1L/hr","1500 cc/h","2L/h"],"a":0,"e":"Ans. A. 500 cc/h Specific gravity of Amniotic fluid: 1.008 to 1.010 Osmolality: 250 mosm/L Completely replaced in 3 hours. Rate of amniotic fluid turn over is 500cc/hr.","pyqMatches":[{"year":"2013","no":1591,"q":"Rate of turnover of amniotic fluid is ?","o":["500 cc/h","1L/hr","1500 cc/h","2L/h"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4410, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 131, '{"id":4410,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":131,"q":"Maximum amount of amiotic fluid is seen at how many weeks ?","o":["16","30","12","38-40"],"a":3,"e":"Ans. D. 38-40","pyqMatches":[{"year":"2013","no":1592,"q":"Maximum amount of amiotic fluid is seen at how many weeks ?","o":["16","30","12","38-40"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4411, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 132, '{"id":4411,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":132,"q":"Uterus post pregnancy becomes a pelvic organ in?","o":["4 weeks","6 weeks","12 weeks","2 week"],"a":3,"e":"Ans, D. 2 week By the end of 2 weeks - uterus is a pelvic organ. By the md of 6 week - uterus returns almost to its normal size (pre pregnant size).","pyqMatches":[{"year":"2013","no":1593,"q":"Uterus post pregnancy becomes a pelvic organ in?","o":["4 weeks","6 weeks","12 weeks","2 week"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4412, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 133, '{"id":4412,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":133,"q":"Assisted head delivery is done in ?","o":["Brow presentation","Face presentation","Persistent occipito posterior position","Twin presentation 1522. % of"],"a":2,"e":"Ans. C. Persistent occipito posterior position Occipito posterior positions \"In practice about 5-1O% of women admitted in labourwith cephalic presentations present with occipito-posterior presentations. Given time and patience, many of these will rotate and get corrected to occipito-anterior position and deliver normally.","pyqMatches":[{"year":"2013","no":1594,"q":"Assisted head delivery is done in ?","o":["Brow presentation","Face presentation","Persistent occipito posterior position","Twin presentation 1522. % of"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4413, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 134, '{"id":4413,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":134,"q":"% of women delivering on their EDD is ?","o":["25%","50%","4%","15%"],"a":2,"e":"Ans. C. 4% Based on the Noegelesfomulalabour starts approximately on: - Expected date – 4%","pyqMatches":[{"year":"2013","no":1595,"q":"% of women delivering on their EDD is ?","o":["25%","50%","4%","15%"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4414, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 135, '{"id":4414,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":135,"q":"Inner cell mass differentiates into ?","o":["Chorion","Trophoectoderm","Embryo","All of the above"],"a":2,"e":"ANs. C. Embryo Blastocyst enlarges & the zonapellucida undergoes lysis , this is called zona hatching. The cells on the outer side become trohoectoderm which differentiates into chorion. The cells on the inner side form inner cell mass which differentiates into embrvo.","pyqMatches":[{"year":"2016","no":1581,"q":"Inner cell mass differentiates into ?","o":["Chorion","Trophoectoderm","Embryo","All of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4415, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 136, '{"id":4415,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":136,"q":"Embryo is called \"fetus\" after how many weeks post fertilization/conception ?","o":["6","8","10","12"],"a":1,"e":"Ans. B. 8 Embryonic period begins at 3rd week following ovulation/fertilization & extends upto 8 weeks post conception (10 weeks from LMP). Fetal period begins after 8 weeks post conception (10 weeks from LMP) & ends in delivery.","pyqMatches":[{"year":"2016","no":1582,"q":"Embryo is called \"fetus\" after how many weeks post fertilization/conception ?","o":["6","8","10","12"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4416, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 137, '{"id":4416,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":137,"q":"Utero-placental circulation is established days after fertilization ?","o":["5","10","15","20"],"a":1,"e":"Ans. B. 10 The uteroPlacental circulation is established 9-10 days after fertilization. Fetoplacental circulation is established 2l days post fertilization.","pyqMatches":[{"year":"2016","no":1583,"q":"Utero-placental circulation is established days after fertilization ?","o":["5","10","15","20"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
