INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4419, 'OBG', 'Miscellaneous', 'Moderate', 'Obstetrics', 140, '{"id":4419,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Obstetrics","sourceNo":140,"q":"Ovarian cycle can be correlated with all except ?","o":["Endometrial sampling","Vaginal cytology","Blood hormonal levels","Estrous cycle"],"a":3,"e":"Ans. D. Estrous cycle Estrous cycle does not occur in human beings.","pyqMatches":[{"year":"2016","no":1586,"q":"Ovarian cycle can be correlated with all except ?","o":["Endometrial sampling","Vaginal cytology","Blood hormonal levels","Estrous cycle"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4420, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Obstetrics', 141, '{"id":4420,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Obstetrics","sourceNo":141,"q":"Endometrial biopsy to detect ovulation is done on which day of the menstual cycle ?","o":["Day 8-9","Day 13-15","Day 21-23","Day 3-5"],"a":2,"e":"Ans. C. Day 21-23 Endometrial Biopsy : Rarely done now a days for the purpose of iletecting ovulation.","pyqMatches":[{"year":"2016","no":1587,"q":"Endometrial biopsy to detect ovulation is done on which day of the menstual cycle ?","o":["Day 8-9","Day 13-15","Day 21-23","Day 3-5"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4421, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 142, '{"id":4421,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":142,"q":"The uterine blood flow at term is -","o":["50 mL/min","100-150 mL/min","350-375 mL/min","500-750 mL/min"],"a":3,"e":"Ans. D. 500-750 mL/min Uteroplacental blood flow increases progressively during pregnancy and ranges from 5N)-800 mL/minat term.","pyqMatches":[{"year":"2016","no":1588,"q":"The uterine blood flow at term is","o":["50 mL/min","100-150 mL/min","350-375 mL/min","500-750 mL/min"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4422, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 143, '{"id":4422,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":143,"q":"Godell''s sign is ?","o":["Dusky hue of the vestibule","Softening of the cervix","Increased pulsations felt through the lateral fornices","Regular and rhythmic contractions during bimanual examination"],"a":1,"e":"Ans. B. Softening of the cervix","pyqMatches":[{"year":"2016","no":1589,"q":"Godell''s sign is ?","o":["Dusky hue of the vestibule","Softening of the cervix","Increased pulsations felt through the lateral fornices","Regular and rhythmic contractions during bimanual examination"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4423, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 144, '{"id":4423,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":144,"q":"In fetus, insulin production begin at weeks of gestation -","o":["4-6","8-12","14-18","24-28"],"a":1,"e":"Ans. B. 8-12 Reaching 8 to 10 weeks into development, the pancreas starts producing insulin, glucagon, somatostatin, and pancreatic polypeptide.","pyqMatches":[{"year":"2016","no":1590,"q":"In fetus, insulin production begin at weeks of gestation","o":["4-6","8-12","14-18","24-28"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4424, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 145, '{"id":4424,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":145,"q":"Limb bud appear at what weeks of gestation?","o":["3","4","6","9"],"a":1,"e":"Ans. B. 4 The upper extremity is first discretely visible as a bulge or limb bud that develops on the ventrolateral wall of the embryo on day 26 (4- mm crown-to-rump length).","pyqMatches":[{"year":"2016","no":1591,"q":"Limb bud appear at what weeks of gestation?","o":["3","4","6","9"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4425, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 146, '{"id":4425,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":146,"q":"Features of non severe/mild pre ecampsia are all ecxept​ -","o":["Diastolic BP <100 mm Hg","Systolic BP< 160 mm Hg","Mild IUGR","No premonitory symptoms"],"a":2,"e":"Ans., C. Mild IUGR","pyqMatches":[{"year":"2016","no":1592,"q":"Features of non severe/mild pre ecampsia are all ecxept​","o":["Diastolic BP <100 mm Hg","Systolic BP< 160 mm Hg","Mild IUGR","No premonitory symptoms"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4426, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 147, '{"id":4426,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":147,"q":"FERNING is due to ?","o":["Estogen & sodium chloride","Progesterone & sodium chloride","HCG","All of the above"],"a":0,"e":"Ans, A, Estogen & sodium chloride Cervical mucus is relatively rich in sodium chloride when estrogen (but not progesterone) is being produced.","pyqMatches":[{"year":"2016","no":1593,"q":"FERNING is due to ?","o":["Estogen & sodium chloride","Progesterone & sodium chloride","HCG","All of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4427, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 148, '{"id":4427,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":148,"q":"Second wave of trophoblastic invasion occurs at weeks of gestation?","o":["8-11","10-12","12-15","16-20"],"a":2,"e":"Ans, C. 12-15 The timing of the development of the uteroplacental vessels has been described in waves, or stages, over the course of gestation. The first wave occurs before 12 weeks post-fertilization and consists ofinvasion and modification of the spiral arteries of the decidua. Between 12 and 16 weeks pos-fertilization, the second wore occurs. This involves invasion of the intramyometrial parts of the spiral arteries, converting narrow lumen, muscular spiral arteries into dilated, low-resistance uteroplacental vessels.","pyqMatches":[{"year":"2016","no":1594,"q":"Second wave of trophoblastic invasion occurs at weeks of gestation?","o":["8-11","10-12","12-15","16-20"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4428, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 149, '{"id":4428,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":149,"q":"Abstinence period before semen analysis is ?","o":["1-2 days","3-5 days","5-7 days","7-9 days"],"a":1,"e":"Ans. B. 3-5 days The ideal specimen for examination is after 3-5 days of abstinence.","pyqMatches":[{"year":"2016","no":1595,"q":"Abstinence period before semen analysis is ?","o":["1-2 days","3-5 days","5-7 days","7-9 days"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4429, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 150, '{"id":4429,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":150,"q":"Engaging diameter in face presentation is -","o":["Suboccipitobregmatic","Mentovertical","Submentobregmatic","Occipitofrontal"],"a":2,"e":"ANs, C. Submentobregmatic","pyqMatches":[{"year":"2016","no":1596,"q":"Engaging diameter in face presentation is","o":["Suboccipitobregmatic","Mentovertical","Submentobregmatic","Occipitofrontal"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4430, 'OBG', 'Benign Gynecology', 'Easy', 'Obstetrics', 151, '{"id":4430,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Easy","source":"Obstetrics","sourceNo":151,"q":"Least likely to cause dysmenorrhea -","o":["Endometriosis","Adenomyosis","Uterine polyp","Cervical polyp"],"a":3,"e":"Ans, D. Cervical polyp","pyqMatches":[{"year":"2016","no":1597,"q":"Least likely to cause dysmenorrhea","o":["Endometriosis","Adenomyosis","Uterine polyp","Cervical polyp"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4431, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Obstetrics', 152, '{"id":4431,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Obstetrics","sourceNo":152,"q":"LH surge is due to ?","o":["Progesterone","Estrogen","AMH","All of the above"],"a":1,"e":"Ans, B. Estrogen 3-4 days before the ovulation, estrogen level crosses a certain limit (threshold level).","pyqMatches":[{"year":"2016","no":1598,"q":"LH surge is due to ?","o":["Progesterone","Estrogen","AMH","All of the above"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4432, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 153, '{"id":4432,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":153,"q":"Menopause is defined as ?","o":["Presence of hot flushes","Cessation of menses for 1 year","Cessation of menses for 6 months","Cessation of menses for 2 years"],"a":1,"e":"Ans, B. Cessation of menses for 1 year Menopause is defined as the permanent cessation of menses for 7 year and is physiologically correlated with the decline in estrogen secretion resulting from the loss offollicular/ovarian function.","pyqMatches":[{"year":"2016","no":1599,"q":"Menopause is defined as ?","o":["Presence of hot flushes","Cessation of menses for 1 year","Cessation of menses for 6 months","Cessation of menses for 2 years"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4433, 'OBG', 'Miscellaneous', 'Moderate', 'Obstetrics', 154, '{"id":4433,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Obstetrics","sourceNo":154,"q":"Symptoms of menopause are all except ?","o":["Hot flushes","Night sweats","Decrease libido","Intermittent hypotension"],"a":3,"e":"Ans, D. Intermittent hypotension Hot flushes The classic symPtom associated with estrogen deficiency is the hot flash, also known as hot flush This symptom is described as ''recurrent, transient periods of flushing, sweating and a sensation ofheat, often accompanied by palpations, feeling of anxiety and sometimes followed by chills\".","pyqMatches":[{"year":"2016","no":1600,"q":"Symptoms of menopause are all except ?","o":["Hot flushes","Night sweats","Decrease libido","Intermittent hypotension"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4434, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 155, '{"id":4434,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":155,"q":"MENOPAUSE is diagnosed by ?","o":["Estradiol <20 pg/ml","Progesterone <40 ng/dl","FSH>40 IU/L","LH > 20 IU/L"],"a":2,"e":"Ans, C. FSH>40 IU/L As per the American Association of clinical Endocrinologists, the diagnosis of menopause is confirmed by FSH levels >40 IU/L.","pyqMatches":[{"year":"2016","no":1601,"q":"MENOPAUSE is diagnosed by ?","o":["Estradiol <20 pg/ml","Progesterone <40 ng/dl","FSH>40 IU/L","LH > 20 IU/L"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4435, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 156, '{"id":4435,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":156,"q":"The velocity of sperm is ?","o":["1-2 cm/hr","2-4 cm/min","1-4 mm/min","1-4 mm/hr"],"a":2,"e":"Ans. C. 1-4 mm/min The velocity of a sperm in fluid medium is usually 1-4 mm/min. This allows the sperm to move towards an ovum in order to fertilize it.","pyqMatches":[{"year":"2016","no":1602,"q":"The velocity of sperm is ?","o":["1-2 cm/hr","2-4 cm/min","1-4 mm/min","1-4 mm/hr"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4436, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 157, '{"id":4436,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":157,"q":"After ejaculation semen liquefies in ?","o":["10 minutes","30 minutes","75 minutes","120 minutes"],"a":1,"e":"Ans. B. 30 minutes Following ejaculation, the semen forms a gel which provides protection for the sperm from the acidic environment of the vagina. The gelisliquefied within 20-30 minute by enzymes from the prostate gland.","pyqMatches":[{"year":"2016","no":1603,"q":"After ejaculation semen liquefies in ?","o":["10 minutes","30 minutes","75 minutes","120 minutes"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4437, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 158, '{"id":4437,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":158,"q":"During pregnancy, true statement about CVS is ?","o":["Cardiac output decreases","Right axis deviation","Increase in left ventricular end diastolic diameter","All of the above"],"a":2,"e":"Ans, C. Increase in left ventricular end diastolic diameter 2D echo: Increase in left ventricular end diastolic diameter. Increase in left and right atrial diameters.","pyqMatches":[{"year":"2016","no":1604,"q":"During pregnancy, true statement about CVS is ?","o":["Cardiac output decreases","Right axis deviation","Increase in left ventricular end diastolic diameter","All of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4438, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 159, '{"id":4438,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":159,"q":"MC site of implantation is ?","o":["Fallopian tube amullary part","Fallopian tube isthmus","Fundus of uterus","Cornu of uterus"],"a":2,"e":"Ans, C. Fundus of uterus Implantation occurs in the endometrium on the anterior or posterior wall of the body near the fundus on the sixth day following fertilization (corresponding to the 20th day of the menstrual cycle).","pyqMatches":[{"year":"2016","no":1605,"q":"MC site of implantation is ?","o":["Fallopian tube amullary part","Fallopian tube isthmus","Fundus of uterus","Cornu of uterus"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4439, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 160, '{"id":4439,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":160,"q":"Alpha subunit of hCG is similar to ?","o":["FSH","LH","TSH","All of the above"],"a":3,"e":"Ans, D. All of the above Human chorionic Gonadotropin (hcG) isstructurallyrelated to three other glycoproteinhormones LH, FSH, and TSH.","pyqMatches":[{"year":"2016","no":1606,"q":"Alpha subunit of hCG is similar to ?","o":["FSH","LH","TSH","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4440, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 161, '{"id":4440,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":161,"q":"Placental hormone with highest carbohydrate content is -","o":["HCG","Human pregnancy specific beta glycoprotein","HPL","Relaxin"],"a":0,"e":"Ans, A. HCG HCGhas the highest carbohydrate content of any human hormone- 30%.","pyqMatches":[{"year":"2016","no":1607,"q":"Placental hormone with highest carbohydrate content is","o":["HCG","Human pregnancy specific beta glycoprotein","HPL","Relaxin"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4441, 'OBG', 'Miscellaneous', 'Moderate', 'Obstetrics', 162, '{"id":4441,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Obstetrics","sourceNo":162,"q":"The pelvic inlet usually is considered to be contracted if its shortest anteroposterior diameter is less than -","o":["12 cm","10 cm","8 cm","14 cm"],"a":1,"e":"Ans. B. 10 cm The pelvic inlet usually is considered to be contracted if its shortest anteroposteriordiameter is less than10 cmor if the greatest transverse diameter isless than12 cm","pyqMatches":[{"year":"2016","no":1608,"q":"The pelvic inlet usually is considered to be contracted if its shortest anteroposterior diameter is less than","o":["12 cm","10 cm","8 cm","14 cm"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4442, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 163, '{"id":4442,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":163,"q":"Azoospermia with normal FSH would indicate ?","o":["Hypothalamic failure","Testicular failure","Obstruction of vas defrens","All of the above"],"a":2,"e":"Ans, C, Obstruction of vas defrens","pyqMatches":[{"year":"2016","no":1609,"q":"Azoospermia with normal FSH would indicate ?","o":["Hypothalamic failure","Testicular failure","Obstruction of vas defrens","All of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4443, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Obstetrics', 164, '{"id":4443,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Obstetrics","sourceNo":164,"q":"Causes of male infertility ?","o":["Idiopathic","Varicocele","Yq 11 micro deletion","All of the above"],"a":3,"e":"Ans, D. All of the above","pyqMatches":[{"year":"2016","no":1610,"q":"Causes of male infertility ?","o":["Idiopathic","Varicocele","Yq 11 micro deletion","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4444, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 165, '{"id":4444,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":165,"q":"Fetal thyroid gland is able to synthesize hormones by weeks of gestation ?","o":["6-7","7-8","10-12","12-14"],"a":2,"e":"Ans, C. 10-12 Fetal thyroidglandisabletosynthesizehormonesby 10-12 weeksofgestation.","pyqMatches":[{"year":"2016","no":1611,"q":"Fetal thyroid gland is able to synthesize hormones by weeks of gestation ?","o":["6-7","7-8","10-12","12-14"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4445, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 166, '{"id":4445,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":166,"q":"Poor prognosis in first trimester USG is ?","o":["No fetal pole at 5 weeks","No cardiac activity at 5 weeks","No gestational sac at 4 weeks","No cardiac activity at 8 weeks of gestation"],"a":3,"e":"Ans, D. No cardiac activity at 8 weeks of gestation Absence of embryo with heartbeat 22 weeks after a scan that showed a gestational sac without a yolk sac","pyqMatches":[{"year":"2016","no":1612,"q":"Poor prognosis in first trimester USG is ?","o":["No fetal pole at 5 weeks","No cardiac activity at 5 weeks","No gestational sac at 4 weeks","No cardiac activity at 8 weeks of gestation"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4446, 'OBG', 'Miscellaneous', 'Moderate', 'Obstetrics', 167, '{"id":4446,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Obstetrics","sourceNo":167,"q":"All are true about post partum depression except -","o":["Symptoms resolve in 10-12 days","Affects both sexes","SSRIs are effective","None of the above"],"a":0,"e":"Ans, A. Symptoms resolve in 10-12 days","pyqMatches":[{"year":"2016","no":1613,"q":"All are true about post partum depression except","o":["Symptoms resolve in 10-12 days","Affects both sexes","SSRIs are effective","None of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4447, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 168, '{"id":4447,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":168,"q":"Nerve injured in McRoberts maneuver is ?","o":["Lumbosacral trunk","Obturator nerve","Femoral nerve","Pudendal nerve"],"a":2,"e":"Ans, C. Femoral nerve McRoberts maneuver is to be done in cases of shoulder dystocia. When the maternal thighs are markedly flexed and abducted, pressure from the overlying inguinal iigament may lead to femoral nerve injury.","pyqMatches":[{"year":"2016","no":1614,"q":"Nerve injured in McRoberts maneuver is ?","o":["Lumbosacral trunk","Obturator nerve","Femoral nerve","Pudendal nerve"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4448, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 169, '{"id":4448,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":169,"q":"Most conclusive clinical sign of pregnancy is ?","o":["Uterine enlargement","Cervical softening","Amenorrhea","Fetal heat sound auscultation"],"a":3,"e":"Ans. D. Fetal heat sound auscultation FHS auscultation is the most conclusive clinical sign of pregnancy.","pyqMatches":[{"year":"2016","no":1615,"q":"Most conclusive clinical sign of pregnancy is ?","o":["Uterine enlargement","Cervical softening","Amenorrhea","Fetal heat sound auscultation"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4449, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 170, '{"id":4449,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":170,"q":"CRL when cardiac activity can be detected earliest by TVS -","o":["1-4mm","1 cm","6-7mm","2-4 cm"],"a":0,"e":"Ans, A. 1-4mm Fetal heart beat can be detected as early as just under 6 weeks gestation on good quality, high frequency transvaginalultrasound, as a crown rump length (CRL) of as little as 1-2 mm.","pyqMatches":[{"year":"2016","no":1616,"q":"CRL when cardiac activity can be detected earliest by TVS","o":["1-4mm","1 cm","6-7mm","2-4 cm"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4450, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Obstetrics', 171, '{"id":4450,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Obstetrics","sourceNo":171,"q":"Kamla, 30 years old, P2L2 with 3.2 x 4.1 cm fibroid uterus, complains of menorrhagia and is on symptomatic treatment since 6 months. The patient refuses surgery. Next line of management is ?","o":["GnRH analogs","Danazol","Myomectomy","Uterine artery embolization"],"a":3,"e":"Ans, D. Uterine artery embolization UAE can be used as a therapy for symptomatic patients who refuse or want to avoid surgery. After embolization, there is 60-65% decrease in size of fibroids over a period of 6-9 months, and so the patient''s symPtoms may decrease or disaPPear. If the patient is still symptomatic after 1 year, then surgery should be considered.","pyqMatches":[{"year":"2016","no":1617,"q":"Kamla, 30 years old, P2L2 with 3.2 x 4.1 cm fibroid uterus, complains of menorrhagia and is on symptomatic treatment since 6 months. The patient refuses surgery. Next line of management is ?","o":["GnRH analogs","Danazol","Myomectomy","Uterine artery embolization"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4451, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 172, '{"id":4451,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":172,"q":"Living ligature of the uterus is ?","o":["Endometrium","Middle layer of myometrium","Inner layer of myometrium","Parametrium"],"a":1,"e":"Ans, B. Middle layer of myometrium Middle crisscross fibres act as living ligature during involution of the uterus and prevent blood loss.","pyqMatches":[{"year":"2016","no":1618,"q":"Living ligature of the uterus is ?","o":["Endometrium","Middle layer of myometrium","Inner layer of myometrium","Parametrium"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4452, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 173, '{"id":4452,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":173,"q":"In partograms recommended by ''WHO'' the distance between the alert and action lines is ?","o":["1 hour","2 hours","4 hours","5 hours"],"a":2,"e":"Ans. C. 4 hours The concept of alert line'' and ‘action line’ was introduced by Philpott and Castle in 1972. The action line can be placed at 2 – 4 hours interval to the right and parallel to alert line. In partograms recommended by''WH0''the distancebetween the alert and action lines is 4 hours.","pyqMatches":[{"year":"2016","no":1619,"q":"In partograms recommended by ''WHO'' the distance between the alert and action lines is ?","o":["1 hour","2 hours","4 hours","5 hours"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4453, 'OBG', 'Abortion & Ectopic Pregnancy', 'Easy', 'Obstetrics', 174, '{"id":4453,"subject":"OBG","chapter":"Abortion & Ectopic Pregnancy","difficulty":"Easy","source":"Obstetrics","sourceNo":174,"q":"Surgical excision of corpus luteum before weeks of gestation, results in miscarriage","o":["6-7","9-11","11-12","12-14"],"a":0,"e":"Ans, A, 6-7 Surgical excision of corpus luteum (luteoctomy) before 7 weeks of gestation, uniformly precipitated an abrupt decrease in serum progesterone concentration followed by miscarriage","pyqMatches":[{"year":"2016","no":1620,"q":"Surgical excision of corpus luteum before weeks of gestation, results in miscarriage","o":["6-7","9-11","11-12","12-14"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4454, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 175, '{"id":4454,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":175,"q":"Factors responsible for development of OHSS include ?","o":["Histamine","Cytokines","Vascular Endothelial Growth Factor","All of the above"],"a":3,"e":"Ans, D. All of the above VEGF is considered to be the most important.","pyqMatches":[{"year":"2016","no":1621,"q":"Factors responsible for development of OHSS include ?","o":["Histamine","Cytokines","Vascular Endothelial Growth Factor","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4455, 'OBG', 'Abortion & Ectopic Pregnancy', 'Easy', 'Obstetrics', 176, '{"id":4455,"subject":"OBG","chapter":"Abortion & Ectopic Pregnancy","difficulty":"Easy","source":"Obstetrics","sourceNo":176,"q":"MVA syringe is used for ?","o":["First trimester MTP","2nd trimester MTP","Vacuum delivery","All of the above"],"a":0,"e":"Ans, A, First trimester MTP Manual vacuum aspiration (MvA) is a safe and effective method of abortion that involves evacuation of the uterine contents by the use of a hand-held plastic aspirator. It is appropriate for treatment of incomplete abortion for uterine sizes up to 12 weeks from the last menstrual period (including miscarriage, spontaneous abortion and removal of retained products from an induced abortion), first-trimester MTP and endometrial biopsy.","pyqMatches":[{"year":"2016","no":1622,"q":"MVA syringe is used for ?","o":["First trimester MTP","2nd trimester MTP","Vacuum delivery","All of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4456, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 177, '{"id":4456,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":177,"q":"Diihrssen incision is taken on -","o":["Fallopian tube","Ovary","Incompletely dilated cervix","Fully dilated cervix"],"a":2,"e":"Ans, C, Incompletely dilated cervix Occasionalln especially with small preterm fetuses, the incompletely dilated cervix will not allow vaginal delivery of the after-coming head ofthe breech. In such cases, Duhrssen incisions are usually necessary (cut the cervix at l0 and 2 o''clock positions).","pyqMatches":[{"year":"2016","no":1623,"q":"Diihrssen incision is taken on","o":["Fallopian tube","Ovary","Incompletely dilated cervix","Fully dilated cervix"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4457, 'OBG', 'Postpartum & Puerperium', 'Hard', 'Obstetrics', 178, '{"id":4457,"subject":"OBG","chapter":"Postpartum & Puerperium","difficulty":"Hard","source":"Obstetrics","sourceNo":178,"q":"A 27-year-old female with placenta previa had severe bleeding. What is the most likely outcome post delivery?","o":["Galactorrhea","Diabetes","Absence of menstrual cycle","Cushing syndrome"],"a":2,"e":"Ans. c. Absence of menstrual cycle Sheehan syndrome, also known as postpartum hypopituitarism or postpartum pituitary necrosis, is hypopituitarism caused by necrosis due to blood loss and hypovolemic shock during and after childbirth. Most common initial symptoms of Sheehan syndrome are agalactorrhea (absence of lactation) under difficulties with lactation. Many women also report amenorrhea or oligomenorrhea after delivery.","pyqMatches":[{"year":"2016","no":1624,"q":"A 27-year-old female with placenta previa had severe bleeding. What is the most likely outcome post delivery?","o":["Galactorrhea","Diabetes","Absence of menstrual cycle","Cushing syndrome"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4458, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 179, '{"id":4458,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":179,"q":"Woman has 100 ml blood loss every 30 days. This is called as ?","o":["Menorrhagia","Polymenorrhea","Hypomenorrhea","Normal menses"],"a":0,"e":"Ans. A. Menorrhagia Normal blood loss during menses is around 35 ml (20-80 ml) Blood loss more than 80 ml is menorrhagia","pyqMatches":[{"year":"2016","no":1625,"q":"Woman has 100 ml blood loss every 30 days. This is called as ?","o":["Menorrhagia","Polymenorrhea","Hypomenorrhea","Normal menses"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4459, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 180, '{"id":4459,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":180,"q":"Menometrorrhagia is ?","o":["Heavy periods","Intermenstrual bleeding","Heavy & irregular bleeding","Uterine bleeding occurring at regular intervals of less than 21 days"],"a":2,"e":"Ans. C. Heavy & irregular bleeding","pyqMatches":[{"year":"2016","no":1626,"q":"Menometrorrhagia is ?","o":["Heavy periods","Intermenstrual bleeding","Heavy & irregular bleeding","Uterine bleeding occurring at regular intervals of less than 21 days"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4460, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 181, '{"id":4460,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":181,"q":"Prevalence of breech presentation at full term is ?","o":["10%","6-7%","3-4%","1-2%"],"a":2,"e":"Ans. C. 3-4%","pyqMatches":[{"year":"2016","no":1627,"q":"Prevalence of breech presentation at full term is ?","o":["10%","6-7%","3-4%","1-2%"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4461, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 182, '{"id":4461,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":182,"q":"The shortest conjugate is ?","o":["True conjugate","Obstetric conjugate","Diagonal conjugate","Anatomical conjugate"],"a":1,"e":"Ans. B. Obstetric conjugate Obstetric conjugate (10 cm) Distance between midpoint of sacral Promontory to the prominent bony projection in the midline on inner surface of symphysis pubis.","pyqMatches":[{"year":"2016","no":1628,"q":"The shortest conjugate is ?","o":["True conjugate","Obstetric conjugate","Diagonal conjugate","Anatomical conjugate"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4462, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 183, '{"id":4462,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":183,"q":"Shortest transverse diameter is ?","o":["BPD","Bitemporal diameter","Bimastoid diameter","All are equal in length"],"a":2,"e":"Ans. C. Bimastoid diameter Bimastoid diameter = 7.5 cm Occipitofrontal diameter → 11.5 cm","pyqMatches":[{"year":"2016","no":1629,"q":"Shortest transverse diameter is ?","o":["BPD","Bitemporal diameter","Bimastoid diameter","All are equal in length"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4463, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 184, '{"id":4463,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":184,"q":"With reference to fetal heart rate, a nonstress test is considered reactive when?","o":["Two fetal heart rate accelerations are noted in 20 minutes","One fetal heart rate acceleration is noted in 20 minutes","Two fetal heart rate accelerations are noted in 10 minutes","Three fetal heart rate accelerations are noted in 30 minutes"],"a":0,"e":"Ans. A. Two fetal heart rate accelerations are noted in 20 minutes Reactive (Reassuring) NST Two or more accelerations of > 15 beats/minute above the baseline, lasting for > 75 seconds arc present in 20-4O minutes observation period.","pyqMatches":[{"year":"2016","no":1630,"q":"With reference to fetal heart rate, a nonstress test is considered reactive when?","o":["Two fetal heart rate accelerations are noted in 20 minutes","One fetal heart rate acceleration is noted in 20 minutes","Two fetal heart rate accelerations are noted in 10 minutes","Three fetal heart rate accelerations are noted in 30 minutes"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4464, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 185, '{"id":4464,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":185,"q":"Variable deceleration is seen in ?","o":["Head compression","Uteroplacental insufficiency","Cord compression","None of the above"],"a":2,"e":"Ans, C. Cord compression Variable decelerations are due to cord compression (oligohydramnios in labor)","pyqMatches":[{"year":"2016","no":1631,"q":"Variable deceleration is seen in ?","o":["Head compression","Uteroplacental insufficiency","Cord compression","None of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4465, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 186, '{"id":4465,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":186,"q":"Modified BIOPHYSICAL PROFILE is ?","o":["NST + FETAL TONE","FETAL TONE + AFI","NST + AFI","NST+ FETAL TONE + AFI"],"a":2,"e":"Ans, C. NST + AFI Modified BPP = NST &AFI BPP has 5 components","pyqMatches":[{"year":"2016","no":1632,"q":"Modified BIOPHYSICAL PROFILE is ?","o":["NST + FETAL TONE","FETAL TONE + AFI","NST + AFI","NST+ FETAL TONE + AFI"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4466, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 187, '{"id":4466,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":187,"q":"If fetus is having hypoxia, which of the BPP parameter will be affected last ?","o":["Fetal tone","Fetal breathing movement","Fetal movements","NST"],"a":0,"e":"Ans. A. Fetal tone First activity to appear, Fetal Tone at about 7.5-8.5 weeks, is also presumably the last activity to disappear with progressively worsening hypoxia.","pyqMatches":[{"year":"2016","no":1633,"q":"If fetus is having hypoxia, which of the BPP parameter will be affected last ?","o":["Fetal tone","Fetal breathing movement","Fetal movements","NST"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4467, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Obstetrics', 188, '{"id":4467,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Obstetrics","sourceNo":188,"q":"Test used to detect genetic abnormality in embryo,before transferring it to the uterus in IVF is ?","o":["Embryo cell biopsy","CVS","ICSI","All of the above"],"a":0,"e":"Ans, A. Embryo cell biopsy PGD, involves removing a cell from an IVF embryo to test it for a specific genetic condition (cystic fibrosis'' for example) before transferring the embryo to the uterus.","pyqMatches":[{"year":"2016","no":1634,"q":"Test used to detect genetic abnormality in embryo,before transferring it to the uterus in IVF is ?","o":["Embryo cell biopsy","CVS","ICSI","All of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4468, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 189, '{"id":4468,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":189,"q":"In IVF, embryos are transferred back to uterine cavity at cells stage ?","o":["2","2-4","4-8","8-16"],"a":2,"e":"Ans, C. 4-8 Typically embryos ate transferred at the cleavage stage (Day 2 or 3 after oocyte retrieval). Day three embryos ate called cleavage stage embryos and have approximately 4 - 8 cells.","pyqMatches":[{"year":"2016","no":1635,"q":"In IVF, embryos are transferred back to uterine cavity at cells stage ?","o":["2","2-4","4-8","8-16"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4469, 'OBG', 'Miscellaneous', 'Hard', 'Obstetrics', 190, '{"id":4469,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Hard","source":"Obstetrics","sourceNo":190,"q":"Azoospermic patient can be a father of a child, by which of the following?","o":["IUI","ZIFT","ICSI","Not possible & counsel regarding adoption"],"a":2,"e":"Ans. C. ICSI PESA= percutaneous epididymalsperm aspiration MESA= microscopic epididymal sperm aspiration TESA= testicular sperm asPiration TESE= testicular sperm extraction (testicular biopsy)","pyqMatches":[{"year":"2016","no":1636,"q":"Azoospermic patient can be a father of a child, by which of the following?","o":["IUI","ZIFT","ICSI","Not possible & counsel regarding adoption"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4470, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Obstetrics', 191, '{"id":4470,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Obstetrics","sourceNo":191,"q":"A primigravida with 36 weeks of pregnancy is in labor with 3 cm dilatation and minimal uterine contraction. On rupture of membranes, fresh bleeding is noted with late fetal deceleration up to 50 beats/min. The patient was taken for LSCS but fetus could no be saved. No abruptio or placenta previa was seen. The likely diagnosis is ?","o":["Placenta previa","Revealed abruptio","Circumvallate placenta","Vasa previa"],"a":3,"e":"Ans. D. Vasa previa Vasa previa ( l:2500) is a rare condition in which fetal blood vessels are in front of the presenting part and cross the cervix. The condition has a high fetal mortality rate (50-95%). This is attributed to rapid fetal exsanguination, resulting from the vessels tearing when the cervix dilates, membrane ruPture.","pyqMatches":[{"year":"2016","no":1637,"q":"A primigravida with 36 weeks of pregnancy is in labor with 3 cm dilatation and minimal uterine contraction. On rupture of membranes, fresh bleeding is noted with late fetal deceleration up to 50 beats/min. The patient was taken for LSCS but fetus could no be saved. No abruptio or placenta previa was seen. The likely diagnosis is ?","o":["Placenta previa","Revealed abruptio","Circumvallate placenta","Vasa previa"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4471, 'OBG', 'Labour & Delivery', 'Hard', 'Obstetrics', 192, '{"id":4471,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Hard","source":"Obstetrics","sourceNo":192,"q":"All are components of Active Management of the Third Stage of Labor except ?","o":["Uterotonic agent within 1 minute of birth","Massage of uterus before control cord traction","Control cord traction","None of the above"],"a":1,"e":"Ans. B. Massage of uterus before control cord traction Administer anuterotonic drug at the delivery of the anterior shoulder or afterwards, within one minute of the baby''s birth. Before performing AMTSL, gently palpate the woman''s abdomen to rule out the presence of another baby. At this point, do not massage the uterus. Perform controlled cord traction Massage the uterus immediately","pyqMatches":[{"year":"2016","no":1638,"q":"All are components of Active Management of the Third Stage of Labor except ?","o":["Uterotonic agent within 1 minute of birth","Massage of uterus before control cord traction","Control cord traction","None of the above"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4472, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 193, '{"id":4472,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":193,"q":"With which of the following events, the feto maternal haemorrhage risk is the least ?","o":["Amniocentesis","Cordocentrsis","Chorionic villus sampling","Abruption"],"a":3,"e":"Ans. D. Abruption","pyqMatches":[{"year":"2016","no":1639,"q":"With which of the following events, the feto maternal haemorrhage risk is the least ?","o":["Amniocentesis","Cordocentrsis","Chorionic villus sampling","Abruption"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4473, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Obstetrics', 194, '{"id":4473,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Obstetrics","sourceNo":194,"q":"Infertility is defined as ?","o":["Inability to conceive after 1 year of regular unprotected intercourse","Inability to conceive after 1 year of marriage","Inability to conceive after 2 years of marriage","Inability to conceive in spite of 2 years of regular unprotected intercourse"],"a":0,"e":"ANS. A. Inability to conceive after 1 year of regular unprotected intercourse Infertility is defined as an inability to conceive in spite of 1 year of regular unprotected intercourse","pyqMatches":[{"year":"2016","no":1640,"q":"Infertility is defined as ?","o":["Inability to conceive after 1 year of regular unprotected intercourse","Inability to conceive after 1 year of marriage","Inability to conceive after 2 years of marriage","Inability to conceive in spite of 2 years of regular unprotected intercourse"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4474, 'OBG', 'Benign Gynecology', 'Easy', 'Obstetrics', 195, '{"id":4474,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Easy","source":"Obstetrics","sourceNo":195,"q":"Cord prolapse is least likely with -","o":["Transverse lie","Footling breech","Oligohydroamnios","Floating head"],"a":2,"e":"Ans. C. Oligohydroamnios Cord prolapse has been defined as the descent of the umbilical cord through the cervix alongside (occult) or past the presenting part (overt) in the vagina or outside the vulva in the presence of ruptured membranes","pyqMatches":[{"year":"2016","no":1641,"q":"Cord prolapse is least likely with","o":["Transverse lie","Footling breech","Oligohydroamnios","Floating head"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4475, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 196, '{"id":4475,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":196,"q":"Ideal time to do Glucose challenge test in pregnancy is ?","o":["12-16 weeks","20-24 weeks","24-28 weeks","30-34 weeks"],"a":2,"e":"Ans. C. 24-28 weeks O''sullivan Blood Sugar Screening Test (Glucose Challenge Test) The ideal time to do this test is24-28 weeks of gestation (as insulin resistance in pregnancy is maximum at 28 weeks of gestation)","pyqMatches":[{"year":"2016","no":1642,"q":"Ideal time to do Glucose challenge test in pregnancy is ?","o":["12-16 weeks","20-24 weeks","24-28 weeks","30-34 weeks"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4476, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 197, '{"id":4476,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":197,"q":"After IUFD, when does the mother develop DIC -","o":["48 hours","1-2 weeks","3-4 weeks","6 weeks"],"a":2,"e":"Ans. C. 3-4 weeks Thromboplastin from the dead fetus can enter the maternal system and cause DIC. This only happens when the dead fetus is retained inside for 3-4 weeks.","pyqMatches":[{"year":"2016","no":1643,"q":"After IUFD, when does the mother develop DIC","o":["48 hours","1-2 weeks","3-4 weeks","6 weeks"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4477, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 198, '{"id":4477,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":198,"q":"Folic acid required in first trimester of normal pregnancy -","o":["100 microgram","400-500 microgram","4 mg","5 mg"],"a":1,"e":"Ans, B, 400-500 microgram Some NTDs are associated with a specific mutation in the methylene tetrahydrofolatereductase gene, the adverse effects of whichcan be largely overcome by periconceptional folic acid supplementation. More than half of NTDs could be prevented with daily intake of 400 microgram of folic acid throughout the periconceptional period. A woman with a prior pregnancy complicated by a neural tube defect can reduce the 23% recurrence risk by more than 70% if she takes 4 mg of folic acid for the month before conception and for the first trimester of pregnancy.","pyqMatches":[{"year":"2016","no":1644,"q":"Folic acid required in first trimester of normal pregnancy","o":["100 microgram","400-500 microgram","4 mg","5 mg"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4478, 'OBG', 'Abortion & Ectopic Pregnancy', 'Hard', 'Obstetrics', 199, '{"id":4478,"subject":"OBG","chapter":"Abortion & Ectopic Pregnancy","difficulty":"Hard","source":"Obstetrics","sourceNo":199,"q":"A 30-year-old is 14 weeks pregnant. She had two painless deliveries at 16 weeks earlier. Next line of management is ?","o":["Cervical encerclage","Evaluation for diabetes mellitus and thyroid disorders","Cervical length assessment","Tocolytics"],"a":2,"e":"Ans, C. Cervical length assessment The patient had two painless abortions at 16 weeks in the past, so mostly it is a case of incompetent os. Next line of management in these patients is frequent cervical length assessment: clinically or by USG. The patient is evaluated more frequently and if the cervix is short (less than 2.5cm) than cervical encerclage has to be done. Cervical encerclage is the surgery ofchoice for incompetent os, but the surgery itselfcan lead to complications such as uterine contractions, abortions, and PROM. So the surgery is only to be done if it is indicated.","pyqMatches":[{"year":"2016","no":1645,"q":"A 30-year-old is 14 weeks pregnant. She had two painless deliveries at 16 weeks earlier. Next line of management is ?","o":["Cervical encerclage","Evaluation for diabetes mellitus and thyroid disorders","Cervical length assessment","Tocolytics"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4479, 'OBG', 'Benign Gynecology', 'Easy', 'Obstetrics', 200, '{"id":4479,"subject":"OBG","chapter":"Benign Gynecology","difficulty":"Easy","source":"Obstetrics","sourceNo":200,"q":"Upper two -third anterior vaginal wall prolapse is ?","o":["Cystocele","Urethrocele","Rectocele","Enterocele"],"a":0,"e":"Ans. A. Cystocele","pyqMatches":[{"year":"2016","no":1646,"q":"Upper two -third anterior vaginal wall prolapse is ?","o":["Cystocele","Urethrocele","Rectocele","Enterocele"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4480, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 201, '{"id":4480,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":201,"q":"Earliest sign after IUFD is ?","o":["Overlapping of skull bones","Hyperflexion of spine","Gas in great vessel","Over crowding of ribs"],"a":2,"e":"Ans. C. Gas in great vessel Robert sign (gas in great vessels) - 12hrs after death.","pyqMatches":[{"year":"2016","no":1647,"q":"Earliest sign after IUFD is ?","o":["Overlapping of skull bones","Hyperflexion of spine","Gas in great vessel","Over crowding of ribs"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4481, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 202, '{"id":4481,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":202,"q":"True about Gartners cyst is ?","o":["Retention cyst in remnants of Wolffian duct","Arises from mullerian duct","Commonly arises from cervix","Impulse on coughing"],"a":0,"e":"Ans, A. Retention cyst in remnants of Wolffian duct","pyqMatches":[{"year":"2016","no":1648,"q":"True about Gartners cyst is ?","o":["Retention cyst in remnants of Wolffian duct","Arises from mullerian duct","Commonly arises from cervix","Impulse on coughing"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4482, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 203, '{"id":4482,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":203,"q":"If the anal spincter is injured, it is which degree of Perineal Tear ?","o":["First","Second","Third","Fourth"],"a":2,"e":"Ans, C. Third Perineal Tears are classified into four categories First-degree tear: laceration is limited to the fourchette and superficial perineal skin or vaginal mucosa. Second-degree tear: laceration extends beyond fourchette, perinealskin and vaginal mucosa to perineal muscles and fascia, but not the anal sphincter. Third-degree tear: fourchette, perineal skin, vaginal mucosa, muscles, and anal sphincter are torn","pyqMatches":[{"year":"2016","no":1649,"q":"If the anal spincter is injured, it is which degree of Perineal Tear ?","o":["First","Second","Third","Fourth"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4483, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 204, '{"id":4483,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":204,"q":"If the rectal mucosa is injured, it is which degree of Perineal Tear ?","o":["First","Second","Third","Fourth"],"a":3,"e":"Ans, D. Fourth Rectal mucosal tear is fourth degree tear.","pyqMatches":[{"year":"2016","no":1650,"q":"If the rectal mucosa is injured, it is which degree of Perineal Tear ?","o":["First","Second","Third","Fourth"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4484, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 205, '{"id":4484,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":205,"q":"Cryptomenorrhea occurs in ?","o":["Fibroids","PCOS","Imperforate hymen","All of the above"],"a":2,"e":"Ans, C. Imperforate hymen Congenital Imperforate hymen: It is due to failure of disintegration of the central cells of Mullerian eminence that project into urogenital sinus TransversevaginalsePtum Atresia ofvagina, cervix.","pyqMatches":[{"year":"2016","no":1651,"q":"Cryptomenorrhea occurs in ?","o":["Fibroids","PCOS","Imperforate hymen","All of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4485, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 206, '{"id":4485,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":206,"q":"Best indicator for ovarian reserve is ?","o":["AMH","LH/FSH ratio","FSH","Estradiol"],"a":0,"e":"Ans. A. AMH AMH blood levels are thought to reflect the size of the remaining egg supply or “ovarian reserve\"","pyqMatches":[{"year":"2016","no":1652,"q":"Best indicator for ovarian reserve is ?","o":["AMH","LH/FSH ratio","FSH","Estradiol"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4486, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 207, '{"id":4486,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":207,"q":"HPL has activity similar to which hormone ?","o":["Oxytocin","Growth hormone","Insulin","All of the above"],"a":1,"e":"Ans. B. Growth hormone Human placenta lactogen (hPL) was named so, because of its potent lactogenic & growth hormone like bioactivity as well as immunochemical resemblance to human growth hormone''","pyqMatches":[{"year":"2016","no":1653,"q":"HPL has activity similar to which hormone ?","o":["Oxytocin","Growth hormone","Insulin","All of the above"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4487, 'OBG', 'Miscellaneous', 'Moderate', 'Obstetrics', 208, '{"id":4487,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Obstetrics","sourceNo":208,"q":"Which of the following is not a soft tissue marker of Down syndrome on USG ?","o":["Increase NT","Absent nasal bone","Exomphalos","Polydactyly"],"a":3,"e":"Ans. D. Polydactyly","pyqMatches":[{"year":"2016","no":1654,"q":"Which of the following is not a soft tissue marker of Down syndrome on USG ?","o":["Increase NT","Absent nasal bone","Exomphalos","Polydactyly"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4488, 'OBG', 'Abortion & Ectopic Pregnancy', 'Hard', 'Obstetrics', 209, '{"id":4488,"subject":"OBG","chapter":"Abortion & Ectopic Pregnancy","difficulty":"Hard","source":"Obstetrics","sourceNo":209,"q":"In a case of recurrent spontaneous abortion the following investigation is unwanted ?","o":["Hysteroscopy","Testing for antiphospholipid antibodies","Testing for TORCH infections","Thyroid function tests"],"a":2,"e":"Ans. C. Testing for TORCH infections Testingfor TORCH infections is now thought to be unwarranted.","pyqMatches":[{"year":"2016","no":1655,"q":"In a case of recurrent spontaneous abortion the following investigation is unwanted ?","o":["Hysteroscopy","Testing for antiphospholipid antibodies","Testing for TORCH infections","Thyroid function tests"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4489, 'OBG', 'Abortion & Ectopic Pregnancy', 'Easy', 'Obstetrics', 210, '{"id":4489,"subject":"OBG","chapter":"Abortion & Ectopic Pregnancy","difficulty":"Easy","source":"Obstetrics","sourceNo":210,"q":"Dilatation & evacuation is done for all ecxept ?","o":["Inevitable abortion","Incomplete abortion","Threatened abortion","None of the above"],"a":2,"e":"Ans. C. Threatened abortion Inevitable abortion means the process ofexpulsion ofproducts ofconception has become irreversible. The expulsion of products of conception has not occurred but it is bound to happen and nothing can be done to stop this process. When the entire products are not expelled, part of it is left inside the uterine cavity, it is called incomplete abortion.","pyqMatches":[{"year":"2016","no":1656,"q":"Dilatation & evacuation is done for all ecxept ?","o":["Inevitable abortion","Incomplete abortion","Threatened abortion","None of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4490, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 211, '{"id":4490,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":211,"q":"WHO normal Hb value for a non pregnant adult female is ?","o":["10 gm/di","11 gm /dl","12 gm/dl","13 gm/dl"],"a":2,"e":"Ans. C. 12 gm/dl","pyqMatches":[{"year":"2016","no":1657,"q":"WHO normal Hb value for a non pregnant adult female is ?","o":["10 gm/di","11 gm /dl","12 gm/dl","13 gm/dl"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4491, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 212, '{"id":4491,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":212,"q":"Outcomes of occipito posterior position?","o":["Deep transverse arrest","Occipito sacral arrest","Face to pubis delivery","All of the above"],"a":3,"e":"Ans, D. All of the above","pyqMatches":[{"year":"2016","no":1577,"q":"Outcomes of occipito posterior position?","o":["Deep transverse arrest","Occipito sacral arrest","Face to pubis delivery","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4492, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 213, '{"id":4492,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":213,"q":"RMP can perform MTP in first trimester if he has assisted in MTPs -","o":["5","15","25","50"],"a":2,"e":"Ans, C. 25 A registered medical practitioner shall have one or more of the following experience or training in gynecology and obstetrics namely = If he has assisted a registered medical practitioner in the performance of twenty-five cases of medical termination ofpregnancy of which at least five have been performed independently,","pyqMatches":[{"year":"2016","no":1578,"q":"RMP can perform MTP in first trimester if he has assisted in MTPs","o":["5","15","25","50"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4493, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 214, '{"id":4493,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":214,"q":"Crying of fetus in utero is called as ?","o":["Vagitus uterinus","First cry","Utero vaginalis","Vagitus vagina"],"a":0,"e":"Ans, A. Vagitus uterinus","pyqMatches":[{"year":"2016","no":1579,"q":"Crying of fetus in utero is called as ?","o":["Vagitus uterinus","First cry","Utero vaginalis","Vagitus vagina"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4494, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 215, '{"id":4494,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":215,"q":"True about cephalhematoma is :","o":["Crosses the suture lines","Always present at birth","Ventouse delivery is a risk factor","All of the above"],"a":2,"e":"Ans. C. Ventouse delivery is a risk factor The usual causes of a cephalohematoma are a prolonged second stage of labor or instrumental delivery,particularly ventouse.","pyqMatches":[{"year":"2015","no":1404,"q":"True about cephalhematoma is","o":["It is hemorrhage between the skull and periosteum","It is hemorrhage within the subcutaneous tissue around the skull","It is type of subdural hemorrhage","It is extraperiosteal bleeding in the skull"],"a":0,"source":"NEET_2015_Paper.pdf"},{"year":"2016","no":1580,"q":"True about cephalhematoma is :","o":["Crosses the suture lines","Always present at birth","Ventouse delivery is a risk factor","All of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2015","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4495, 'OBG', 'Infertility & Reproductive Endocrinology', 'Moderate', 'Obstetrics', 216, '{"id":4495,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Moderate","source":"Obstetrics","sourceNo":216,"q":"All are causes of anovulatory amenorrhoea except?","o":["PCOD","Hyperprolactemia","Gonadal dysgenesis","Drugs"],"a":2,"e":"Ans. C. Gonadal dysgenesis Causes of anovulatory amenorrhea PCOD Hyperprolactinaemia Weight loss, stress, exercise Drugs Chest wall stimulation","pyqMatches":[{"year":"2012","no":1340,"q":"All are causes of anovulatory amenorrhoea except?","o":["PCOD","Hyperprolactemia","Gonadal dysgenesis","Drugs"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4496, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 217, '{"id":4496,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":217,"q":"What is false about post menopausal state ?","o":["Low LH","Low estrogen","High FSH","High androgen"],"a":0,"e":"Ans. A. Low LH Hormonal changes in post-menoPausal state FSH level is increased Oestrogen level is decreased & most of it is synthesised peripherally by conversion of androgen to oestrogen Androgen level is slightly increased","pyqMatches":[{"year":"2012","no":1341,"q":"What is false about post menopausal state ?","o":["Low LH","Low estrogen","High FSH","High androgen"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4497, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 218, '{"id":4497,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":218,"q":"In a postmenopausal female, which hormone increases?","o":["FSH","Estrogen","GH","None of the above"],"a":0,"e":"Ans, A. FSH","pyqMatches":[{"year":"2012","no":1342,"q":"In a postmenopausal female, which hormone increases?","o":["FSH","Estrogen","GH","None of the above"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4498, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 219, '{"id":4498,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":219,"q":"Role of lactobacilli in vaginal secretions","o":["To maintain alkaline pH","To maintain acidic pH","Nutrition","None"],"a":1,"e":"Ans., B. To maintain acidic pH The importance of Doderlein''s bacillus is that its presence is associated with production of lactic acid contained in the vaigna and this acidity inhibits the growth of other organisms.\" Doderlein''s bacillus is the only organism which will grow at the pH of 4-4.5 (normal pH of vagina).","pyqMatches":[{"year":"2012","no":1343,"q":"Role of lactobacilli in vaginal secretions","o":["To maintain alkaline pH","To maintain acidic pH","Nutrition","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4499, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Obstetrics', 220, '{"id":4499,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Obstetrics","sourceNo":220,"q":"Hegar sign all are true except ?","o":["Bimanual palpation method","Difficult in obese","Can be done at 14 weeks","Present in 2/3rd of cases"],"a":2,"e":"Ans. C. Can be done at 14 weeks Hegar''s sign: Present in2/3rd of cases. Demonstrated between 6-10 weeks, a little earlier in multipara. This sign is based on the 2 facts (1) upper part of the body of uterus is enlarged by growing uterus and lower part is empty and soft and cervix is comparatively film. Therefore on bimannual examination (2 fingers in the anterior fornix and abdominal fingers behind the uterus), abdominal and vaginal fingers seem to appose below the body ofthe uterus.","pyqMatches":[{"year":"2012","no":1344,"q":"Hegar sign all are true except ?","o":["Bimanual palpation method","Difficult in obese","Can be done at 14 weeks","Present in 2/3rd of cases"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4500, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 221, '{"id":4500,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":221,"q":"Hegar sign is seen in how many weeks ?","o":["6-10 weeks","10-14 weeks","14-18 weeks","18-22 weeks"],"a":0,"e":"Ans. A. 6-10 weeks","pyqMatches":[{"year":"2012","no":1345,"q":"Hegar sign is seen in how many weeks ?","o":["6-10 weeks","10-14 weeks","14-18 weeks","18-22 weeks"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4501, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 222, '{"id":4501,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":222,"q":"Palmer sign is related to ?","o":["Contraction of uterus","Dusky hue of ant vaginal wall","Bluish discolouration of ant vaginal wall","Increased pulsations felt through lateral fornix"],"a":0,"e":"Ans, A, Contraction of uterus Palmer sign:-regular and rhythmic contractions can be elicited during bimanual examination as early as 4-8 weeks.","pyqMatches":[{"year":"2012","no":1346,"q":"Palmer sign is related to ?","o":["Contraction of uterus","Dusky hue of ant vaginal wall","Bluish discolouration of ant vaginal wall","Increased pulsations felt through lateral fornix"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4502, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 223, '{"id":4502,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":223,"q":"New born can be given breast milk after how much time following normal delivery?","o":["Half hour","1 hours","2 hours","3 hours"],"a":0,"e":"Ans A. Half hour A healthy baby is put to the breast immediately or at most % to 1 hr following normal delivery. Following caesarean sections a period of 4-6 hours may be sufficient for the mother to feed her baby.","pyqMatches":[{"year":"2012","no":1347,"q":"New born can be given breast milk after how much time following normal delivery?","o":["Half hour","1 hours","2 hours","3 hours"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4503, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Obstetrics', 224, '{"id":4503,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Obstetrics","sourceNo":224,"q":"4 month amenorrhoea with increased FSH, LH & decreased estrogen in a 35 yrs old?","o":["Premature menopause","Menopause","Late menopause","Perimenopause"],"a":0,"e":"Ans, A. Premature menopause Premature menopause is defined as ovarian failure occurring 2 SD in years before the mean menopausal age in a population. It is clinically defined as secondary amenorrhea for at least 3 months with raised FSH level, raised FSH:LH ratio & low E2 level in a women under 40 yrs of age.\"","pyqMatches":[{"year":"2012","no":1348,"q":"4 month amenorrhoea with increased FSH, LH & decreased estrogen in a 35 yrs old?","o":["Premature menopause","Menopause","Late menopause","Perimenopause"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4504, 'OBG', 'Infertility & Reproductive Endocrinology', 'Hard', 'Obstetrics', 225, '{"id":4504,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Hard","source":"Obstetrics","sourceNo":225,"q":"35 yr old with 4 months amenorrhea with increased FSH, decreased estrogen. What is the diagnosis?","o":["Premature ovarian failure","PCOD","Pituitary failure","Hypothalamic failure"],"a":0,"e":"Ans. A. Premature ovarian failure It is a case of premature menoPause (premature ovarian failure)''","pyqMatches":[{"year":"2012","no":1349,"q":"35 yr old with 4 months amenorrhea with increased FSH, decreased estrogen. What is the diagnosis?","o":["Premature ovarian failure","PCOD","Pituitary failure","Hypothalamic failure"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4505, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 226, '{"id":4505,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":226,"q":"Contraction stress test false is ?","o":["Oxytocin not used","Invasive method","Detects fetal well being","Negative test is associated with good fetal outcome"],"a":0,"e":"Ans, A. Oxytocin not used Contraction stress test (CST) (syn : Oxytocin challenge test): It is an invasive test to asses fetal respiratory well being during pregnancy. It detects alteration in FHR in response to uterine contraction induced by oxytocin indicating hypoxia. Interpretations Negative test indicated good outcome","pyqMatches":[{"year":"2012","no":1350,"q":"Contraction stress test false is ?","o":["Oxytocin not used","Invasive method","Detects fetal well being","Negative test is associated with good fetal outcome"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4506, 'OBG', 'Miscellaneous', 'Moderate', 'Obstetrics', 227, '{"id":4506,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Obstetrics","sourceNo":227,"q":"NST, what is seen except?","o":["Variability","Acceleration","Time period","Oxytocin"],"a":3,"e":"Ans, D. Oxytocin The non-stress test (NST) measures fetal heart rate, which is monitored with an external transducer for at least 20 minutes. During fetal movement, tracing is observed for heart rate acceleration. Test is positive if two or more fetal heart rate accelerations occurs in 20 minute period.","pyqMatches":[{"year":"2012","no":1351,"q":"NST, what is seen except?","o":["Variability","Acceleration","Time period","Oxytocin"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4507, 'OBG', 'Abortion & Ectopic Pregnancy', 'Easy', 'Obstetrics', 228, '{"id":4507,"subject":"OBG","chapter":"Abortion & Ectopic Pregnancy","difficulty":"Easy","source":"Obstetrics","sourceNo":228,"q":"Menstrual regulation effective upto ?","o":["14 days","21 days","4weeks","6 weeks"],"a":0,"e":"Ans, A. 14 days Menstrual regulation (lnduction/Aspiration) Aspiration of endometrial cavity within l4 days of missed period in a woman with previous normal cycle. Done as an OPD procedure. Helps to detect failed abortion, molar pregnancy or ectopic Pregnancy. Contraindicated in advanced pregnancy & in presence of local pelvic inflammation.","pyqMatches":[{"year":"2012","no":1352,"q":"Menstrual regulation effective upto ?","o":["14 days","21 days","4weeks","6 weeks"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4508, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 229, '{"id":4508,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":229,"q":"pH of vagina in pregnant woman is usually ?","o":["4.0","4.5","5",">5"],"a":0,"e":"Ans. A. 4.0 The vaginal acidity is due to lactic acid. The normal pH in the healthy women of the child bearing age group is 4.5","pyqMatches":[{"year":"2012","no":1353,"q":"pH of vagina in pregnant woman is usually ?","o":["4.0","4.5","5",">5"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4509, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 230, '{"id":4509,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":230,"q":"Vaginal pH before puberty is?","o":["7","6","4.5","5"],"a":0,"e":"Ans. A. 7","pyqMatches":[{"year":"2012","no":1354,"q":"Vaginal pH before puberty is?","o":["7","6","4.5","5"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4510, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 231, '{"id":4510,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":231,"q":"Decidual reaction is due to which hormone ?","o":["Progesterone","Estrogen","LH","FSH"],"a":0,"e":"Ans. A. Progesterone Increased structural & secretory activity of the endometrium that brought about in response to progesterone following implantation is known as Decidual reaction\".","pyqMatches":[{"year":"2012","no":1355,"q":"Decidual reaction is due to which hormone ?","o":["Progesterone","Estrogen","LH","FSH"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4511, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 232, '{"id":4511,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":232,"q":"Inhibin levels are checked on which day of menstrual cycle ?","o":["Day 3","Day 4","Day 5","Day 6"],"a":0,"e":"Ans. A. Day 3 Ovarian reserve test is designed to assess both the number of immature eggs in the ovaries and their quality, which gives an indication of woman''s potential fertility. It works by detecting the levels of three female hormones, using a blood sample taken on day three of menstrual cycle:","pyqMatches":[{"year":"2012","no":1356,"q":"Inhibin levels are checked on which day of menstrual cycle ?","o":["Day 3","Day 4","Day 5","Day 6"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4512, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Obstetrics', 233, '{"id":4512,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Obstetrics","sourceNo":233,"q":"Best test for ovulation ?","o":["Serum estrogen","Serum progesterone","Both","None"],"a":1,"e":"Ans. B. Serum progesterone Plasma concentration of progesterone rises after ovulation & reaches peak of 15 ng/ml at mid luteal phase & then declines as the corpus luteum degenerates\".","pyqMatches":[{"year":"2012","no":1357,"q":"Best test for ovulation ?","o":["Serum estrogen","Serum progesterone","Both","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4513, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 234, '{"id":4513,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":234,"q":"Cardiac output increases maximum at which week?","o":["26-28wks","30-32 wks","32-34 wks","34-36 wks"],"a":2,"e":"Ans. C. 32-34 wks Cardiac output: Starts to increase from 5th week of pregnancy, reaches its peak 40- 50% at about 30-34 weeks.","pyqMatches":[{"year":"2012","no":1358,"q":"Cardiac output increases maximum at which week?","o":["26-28wks","30-32 wks","32-34 wks","34-36 wks"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4514, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 235, '{"id":4514,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":235,"q":"In pregnancy plasma volume increased maximum at what gestational age?","o":["10 wks","20 wks","25 wks","30 wks"],"a":3,"e":"Ans, D. 30 wks Plasma volume is increased. Starting to increase at 6 weeks & reaching max upto 50% at 30 weeks. Total plasma volume increases to the extent of 1.25 litres.","pyqMatches":[{"year":"2012","no":1359,"q":"In pregnancy plasma volume increased maximum at what gestational age?","o":["10 wks","20 wks","25 wks","30 wks"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4515, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 236, '{"id":4515,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":236,"q":"5 month pregnant female, which of the following is true?","o":["50% have soft systolic murmur","Cardiac output is reduced","Systemic vascular resistance is increased","Increase in CVP"],"a":0,"e":"Ans. A. 50% have soft systolic murmur Anatomical changes during pregnancy Heart is pushed upwards & outward. Apex beat is shifted in 4th intercostals space. A systolic murmur can be heard in apical or pulmonary area. Mammary murmur is a continuous hissing murmur audible over tricuspid area in left 2nd & 3rd iintercostals space. ECG shows left axis deviation. 53 and rarely 54 can be heard.","pyqMatches":[{"year":"2012","no":1360,"q":"5 month pregnant female, which of the following is true?","o":["50% have soft systolic murmur","Cardiac output is reduced","Systemic vascular resistance is increased","Increase in CVP"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4516, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 237, '{"id":4516,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":237,"q":"Spinnbarkeit is maximum shown at which phase?","o":["Menstrual phase","Ovulatory","Post ovulatory","Pre follicular"],"a":1,"e":"Ans. B. Ovulatory Spinnbarkeit test (Thread test or Fern test) A sPecimen of cervical mucus when seen under low power microscope, shows a characteristic fern formation. Done to see the estrogenic activity in ovulatory phase of menstrual cycle.","pyqMatches":[{"year":"2012","no":1361,"q":"Spinnbarkeit is maximum shown at which phase?","o":["Menstrual phase","Ovulatory","Post ovulatory","Pre follicular"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4517, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 238, '{"id":4517,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":238,"q":"Rarest presentation is?","o":["Cephalic","Breech","Shoulder","Vertex"],"a":2,"e":"Ans. C. Shoulder","pyqMatches":[{"year":"2012","no":1362,"q":"Rarest presentation is?","o":["Cephalic","Breech","Shoulder","Vertex"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4518, 'OBG', 'Infertility & Reproductive Endocrinology', 'Easy', 'Obstetrics', 239, '{"id":4518,"subject":"OBG","chapter":"Infertility & Reproductive Endocrinology","difficulty":"Easy","source":"Obstetrics","sourceNo":239,"q":"Fertile period of female is measured by ?","o":["LH","FSH","Estrogen","Oxytocin"],"a":0,"e":"Ans, A. LH \"LH surge from the anterior pituitary gland occurs 24 hours prior to ovulation. Radioimmunoassays of the morning sample of urine & blood gives results in 3 hours. Not only does the LH surge help in predicting ovulation, but the approximate time of ovulation can be gauged & coitus around this time can improve the chances of conception.\"","pyqMatches":[{"year":"2012","no":1363,"q":"Fertile period of female is measured by ?","o":["LH","FSH","Estrogen","Oxytocin"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4519, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 240, '{"id":4519,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":240,"q":"External version is done after?","o":["34 weeks","36 weeks","38 weeks","40 weeks"],"a":1,"e":"Ans. B. 36 weeks The maneuver is carried out after 36 weeks in labour-delivery complex.\"","pyqMatches":[{"year":"2012","no":1364,"q":"External version is done after?","o":["34 weeks","36 weeks","38 weeks","40 weeks"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4520, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 241, '{"id":4520,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":241,"q":"Least common presentation of twins ?","o":["Both vertex","Both breech","Both transverse","First vertex and 2nd transverse"],"a":2,"e":"Ans. C.Both transverse Lie - Presentation in twin pregnancy: The most common lie in the fetuses is longitudinal (90%). The combination of presentation of fetuses are: Both vertex (50%) First breech second vertex (10%) First vertex and second transverse (rare) First yertex and second breech (30o/o) Both breech (10%) Both transverse (rarest).","pyqMatches":[{"year":"2012","no":1365,"q":"Least common presentation of twins ?","o":["Both vertex","Both breech","Both transverse","First vertex and 2nd transverse"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4521, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 242, '{"id":4521,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":242,"q":"Presenting part in transverse lie ?","o":["Shoulder","Face","Vertex","Brow"],"a":0,"e":"Ans. A. Shoulder ''When the long axis of the fetus lies perpendicular o the maternal spine or centralised uterine axis, it is called transverse lie. But more commonly, fetal axis lies oblique to the maternal spine & is then called oblique lie. In either of the conditions shoulder usually presents over the cervical opening during labour & both are collectively called shoulder presentations.\"","pyqMatches":[{"year":"2012","no":1366,"q":"Presenting part in transverse lie ?","o":["Shoulder","Face","Vertex","Brow"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4522, 'OBG', 'Miscellaneous', 'Hard', 'Obstetrics', 243, '{"id":4522,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Hard","source":"Obstetrics","sourceNo":243,"q":"Severely anaemic pregnant patient in cardiac failure. Choice of transfusion?","o":["Platelets","Packed cells","Whole blood","Exchange transfusion"],"a":1,"e":"Ans. B. Packed cells","pyqMatches":[{"year":"2012","no":1283,"q":"Severely anaemic pregnant patient in cardiac failure. Choice of transfusion?","o":["Platelets","Packed cells","Whole blood","Exchange transfusion"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4523, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 244, '{"id":4523,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":244,"q":"Hydrops fetalis is due to ?","o":["Rh mismatch","Hyperproteinemia","Placental hypoplasia","All of the above"],"a":0,"e":"Ans. A. Rh mismatch","pyqMatches":[{"year":"2012","no":1284,"q":"Hydrops fetalis is due to ?","o":["Rh mismatch","Hyperproteinemia","Placental hypoplasia","All of the above"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4524, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 245, '{"id":4524,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":245,"q":"Caput succedaneum indicates that fetus was alive till ?","o":["Immediately after birth","Till 2-3 days after birth","2-3 weeks after birth","2-3 months after birth"],"a":0,"e":"Ans. A. Immediately after birth CaPut succedaneum Formation of swelling due to stagnation of fluid in the layers of scalp beneath the girdle of contact. Boggy diffuse swelling, not limited to midline. Disappears spontaneously within 24 hours. Usually occurs after rupture of membranes.","pyqMatches":[{"year":"2012","no":1285,"q":"Caput succedaneum indicates that fetus was alive till ?","o":["Immediately after birth","Till 2-3 days after birth","2-3 weeks after birth","2-3 months after birth"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4525, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 246, '{"id":4525,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":246,"q":"Caput succedeum is said to occur in baby?","o":["Within 24 hrs","2-3 days","2-3 weeks","2-3 months"],"a":0,"e":"Ans. A. Within 24 hrs","pyqMatches":[{"year":"2012","no":1286,"q":"Caput succedeum is said to occur in baby?","o":["Within 24 hrs","2-3 days","2-3 weeks","2-3 months"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4526, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 247, '{"id":4526,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":247,"q":"For uterine prolapse in pregnancy, Ring pessary can be inserted upto ?","o":["12 weeks","14 weeks","16weeks","18 weeks"],"a":3,"e":"Ans. D. 18 weeks Pessary treatment for ProlaPse It does not cure the prolapse, only gives symptomatic relief by stretching the hiatus genitalis, thus preventing the uterine & vaginal descent. Indications of PessarY EarlY Pregnancy - uPto 18 weeks PuerPerium Patients absolutely unfit for surgery Patients unwilling for operation While waiting for surgery Additional benefits like improvement of urinary symptoms","pyqMatches":[{"year":"2012","no":1325,"q":"For uterine prolapse in pregnancy, Ring pessary can be inserted upto ?","o":["12 weeks","14 weeks","16weeks","18 weeks"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4527, 'OBG', 'Labour & Delivery', 'Moderate', 'Obstetrics', 248, '{"id":4527,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Moderate","source":"Obstetrics","sourceNo":248,"q":"Not a method for delivery of after-coming head of breech ?","o":["Forceps method","Burns and Marshall method","Malar flexion and shoulder traction","Half hand method"],"a":3,"e":"Ans. D. Half hand method Methods of delivery of aftercoming head are Burns - Marshall method ForcePs delivery Malar flexion and shoulder traction (modified Mauriceau-Smellie-Veit technique)","pyqMatches":[{"year":"2012","no":1326,"q":"Not a method for delivery of after- coming head of breech ?","o":["Forceps method","Burns and Marshall method","Malar flexion and shoulder traction","Half hand method"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4528, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 249, '{"id":4528,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":249,"q":"Investigation of choice in post menopausal bleeding?","o":["PAP smear","Laproscopy","Fractional curettage","Ultrasound"],"a":2,"e":"Ans., C. Fractional curettage","pyqMatches":[{"year":"2012","no":1327,"q":"Investigation of choice in post menopausal bleeding?","o":["PAP smear","Laproscopy","Fractional curettage","Ultrasound"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4529, 'OBG', 'Contraception & Family Planning', 'Easy', 'Obstetrics', 250, '{"id":4529,"subject":"OBG","chapter":"Contraception & Family Planning","difficulty":"Easy","source":"Obstetrics","sourceNo":250,"q":"Preferred IUD for menorrhagea ?","o":["NOVA T","Cu IUD","Mirena","Gyne fix"],"a":2,"e":"Ans. C. Mirena","pyqMatches":[{"year":"2012","no":1328,"q":"Preferred IUD for menorrhagea ?","o":["NOVA T","Cu IUD","Mirena","Gyne fix"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4530, 'OBG', 'Contraception & Family Planning', 'Easy', 'Obstetrics', 251, '{"id":4530,"subject":"OBG","chapter":"Contraception & Family Planning","difficulty":"Easy","source":"Obstetrics","sourceNo":251,"q":"Preferred treatment for menorrhagea in reproductive age group?","o":["NOVA T","Cu IUD","OCPs","Hysterectomy"],"a":2,"e":"Ans. C. OCPs","pyqMatches":[{"year":"2012","no":1329,"q":"Preferred treatment for menorrhagea in reproductive age group?","o":["NOVA T","Cu IUD","OCPs","Hysterectomy"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4531, 'OBG', 'Miscellaneous', 'Moderate', 'Obstetrics', 252, '{"id":4531,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Obstetrics","sourceNo":252,"q":"Drug not used commonly for menorrhagea ?","o":["Methergin","Clomiphene","GnRH","NSAIDS"],"a":0,"e":"Ans. A. Methergin","pyqMatches":[{"year":"2012","no":1330,"q":"Drug not used commonly for menorrhagea ?","o":["Methergin","Clomiphene","GnRH","NSAIDS"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4532, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 253, '{"id":4532,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":253,"q":"Drug causing abruption placenta ?","o":["Methadone","Cocaine","Amphetamine","Fluoxetine"],"a":1,"e":"Ans. B. Cocaine","pyqMatches":[{"year":"2012","no":1331,"q":"Drug causing abruption placenta ?","o":["Methadone","Cocaine","Amphetamine","Fluoxetine"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4533, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 254, '{"id":4533,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":254,"q":"Classical C section indicated in ?","o":["CA Cervix","Central placenta praevia","Failed induction","Fetal distress"],"a":0,"e":"Ans. A. CA Cervix","pyqMatches":[{"year":"2012","no":1332,"q":"Classical C section indicated in ?","o":["CA Cervix","Central placenta praevia","Failed induction","Fetal distress"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4534, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 255, '{"id":4534,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":255,"q":"Definitive indication of LSCS ?","o":["Mento ant","Contracted pelvis","Occipito posterior","Vertex"],"a":1,"e":"Ans, B. Contracted pelvis","pyqMatches":[{"year":"2012","no":1333,"q":"Definitive indication of LSCS ?","o":["Mento ant","Contracted pelvis","Occipito posterior","Vertex"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4535, 'OBG', 'Labour & Delivery', 'Easy', 'Obstetrics', 256, '{"id":4535,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Easy","source":"Obstetrics","sourceNo":256,"q":"After delivery upto which week is known as puerperium?","o":["2 weeks","4 weeks","6 weeks","8 weeks"],"a":2,"e":"Ans. C. 6 weeks Immediate puerperium: 24 h Early puerperium: upto 1 week Remote puerperium: upto 6 weeks","pyqMatches":[{"year":"2012","no":1334,"q":"After delivery upto which week is known as puerperium?","o":["2 weeks","4 weeks","6 weeks","8 weeks"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4536, 'OBG', 'Labour & Delivery', 'Hard', 'Obstetrics', 257, '{"id":4536,"subject":"OBG","chapter":"Labour & Delivery","difficulty":"Hard","source":"Obstetrics","sourceNo":257,"q":"Which of these steps is followed first for the management of shoulder dystocia after McRoberts maneuver?","o":["Sharp flexion of hip joints towards abdomen","Supra pubic pressure","90 degree rotation of posterior shoulder","Emergency c-section"],"a":1,"e":"Ans. B.Supra pubic pressure Applying a gentle suprapubic pressure is the first step in management of shoulder dystocia after McRoberts maneuver. Mnemonic “HELPERR” as a guide for treating shoulder dystocia: “H” stands for help “E” stands for evaluate for episiotomy. “L” stands for legs(pull your legs toward your stomach McRoberts maneuver) “P” stands for suprapubic pressure “E” stands for enter maneuvers(internal rotation of baby’s shoulders) “R” stands for remove the posterior arm from the birth canal. “R” stands for roll the patient.","pyqMatches":[{"year":"2018","no":180,"q":"Which of these steps is followed first for the management of shoulder dystocia after McRoberts maneuver?","o":["Sharp flexion of hip joints towards abdomen","Supra pubic pressure","90 degree rotation of posterior shoulder","Emergency c-section"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4537, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 258, '{"id":4537,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":258,"q":"Peripartum cardiomyopathy occurs at-","o":["Within 7 days","Within 6 weeks","Within 24 months","Within 5 months"],"a":3,"e":"Ans. D. Within 5 months PPCM is a structural heart muscle disease that occurs in women either at the end of pregnancy or up to five months after giving birth. Pearson’s diagnostic criteria for peripartum cardiomyopathy: Development of cardiac failure in the last month of pregnancy or within 5 months after delivery Absence of an identifiable cause for the cardiac failure Absence of recognizable heart disease prior to the last month of pregnancy, and Left ventricular systolic dysfunction demonstrated by classic echocardiographic criteria, such as depressed ejection fraction or fractional shortening along with a dilated left ventricle.","pyqMatches":[{"year":"2018","no":182,"q":"Peripartum cardiomyopathy occurs at","o":["Within 7 days","Within 6 weeks","Within 24 months","Within 5 months"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4538, 'OBG', 'Postpartum & Puerperium', 'Easy', 'Obstetrics', 259, '{"id":4538,"subject":"OBG","chapter":"Postpartum & Puerperium","difficulty":"Easy","source":"Obstetrics","sourceNo":259,"q":"Nerve mostly compressed in pregnancy puerperium:","o":["Radial nerve","Median nerve","Femoral nerve","Facial nerve"],"a":2,"e":"Ans C. Femoral nerve The most common postpartum nerve injury is foot drop due to injury to the peroneal nerve and injury to the lateral femoral cutaneous nerve. Obstetricians may consider frequent position changes in labor, avoidance of prolonged hip flexion, and shortening the pushing time by allowing for passive descent of the fetus before pushing begins as means of avoiding lateral femoral cutaneous nerve injury.","pyqMatches":[{"year":"2018","no":183,"q":"Nerve mostly compressed in pregnancy puerperium:","o":["Radial nerve","Median nerve","Femoral nerve","Facial nerve"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4539, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 260, '{"id":4539,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":260,"q":"In pregnancy which of the following level is altered mostly:","o":["Total T3","Free T3","Free T4","TSH"],"a":0,"e":"Ans A. Total T3 Total T3 levels are altered throughout pregnancy. Hormones during pregnancy: Increased Decreased Unchanged Growth Hormone Luteinizing hormone ADH Follicle-stimulating hormone Free T3,Free T4 Prolactin Di-Hydro EpiAndroSterone Total T3, Total T4 Aldosterone Testosterone,Androstenodione and cortisol Insulin(due to insulin resistance) Estrogen Progesterone Total T3 and total T4 increase due to stimulation of thyroid tissue by hCG during the early period of gestation. But there is no change in free T3 and T4 due to increase in TBG. This leads to transient fall in TSH during an early weeks of gestation. The level of TSH reaches normal level during second and third trimester.","pyqMatches":[{"year":"2018","no":184,"q":"In pregnancy which of the following level is altered mostly:","o":["Total T3","Free T3","Free T4","TSH"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4540, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 261, '{"id":4540,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":261,"q":"What is meant by Superfecundation?","o":["Fertilization of two or more ova in one intercourse","Fertilization of two or more ova in different intercourses in same menstrual cycle","Fertilization of ova and then it''s division","Fertilization of second ovum first being implanted"],"a":1,"e":"Ans. B. Fertilization of two or more ova in different intercourses in same menstrual cycle Superfecundation is the fertilization of two or more ova from the same cycle by sperm from separate acts of sexual intercourse, which can lead to twin babies from two separate biological fathers. The term superfecundation is derived from fecund, meaning the ability to produce offspring.","pyqMatches":[{"year":"2018","no":186,"q":"What is meant by Superfecundation?","o":["Fertilization of two or more ova in one intercourse","Fertilization of two or more ova in different intercourses in same menstrual cycle","Fertilization of ova and then it''s division","Fertilization of second ovum first being implanted"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4541, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 262, '{"id":4541,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":262,"q":"Acute fatty liver commonly seen in pregnancy at-","o":["3rd trimester","1st trimester","Immediate postpartum","Intrapartum"],"a":0,"e":"Ans. A. 3rd trimester Acute fatty liver of pregnancy (AFLP) is a rare, potentially fatal complication that occurs in the third trimester or early postpartum period. Acute fatty liver of pregnancy is more commonly associated with: Male fetus First pregnancy Maternal obesity It is due to defect in the long-chain-3-hydroxyacyl-CoA- dehydrogenase pathway. It is uncommon in subsequent pregnancies.","pyqMatches":[{"year":"2018","no":170,"q":"Acute fatty liver commonly seen in pregnancy at","o":["3rd trimester","1st trimester","Immediate postpartum","Intrapartum"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4542, 'OBG', 'Miscellaneous', 'Easy', 'Obstetrics', 263, '{"id":4542,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Easy","source":"Obstetrics","sourceNo":263,"q":"Fetal heart starts contracting at-","o":["10-12 days","10-12 weeks","3-5 weeks","3- 5 month"],"a":2,"e":"Ans. C 3-5 weeks The fetal heart starts contracting at approximately 23 days of gestation.","pyqMatches":[{"year":"2018","no":187,"q":"Fetal heart starts contracting at","o":["10-12 days","10-12 weeks","3-5 weeks","3- 5 month"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4543, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 264, '{"id":4543,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":264,"q":"Which of the following is correct regarding placenta?","o":["Placental artery provides nutrients through umbilical cord to baby","Placenta has Wharton''s jelly","Placenta has 2 veins and 1 artery","Estrogen is secreted by placenta"],"a":1,"e":"Ans. B. Placenta has Wharton''s jelly The umbilical cord is a structure that provides vascular flow between the fetus and the placenta. It contains two arteries and one vein, which are surrounded and supported by gelatinous tissue known as Wharton''s jelly.","pyqMatches":[{"year":"2018","no":169,"q":"Which of the following is correct regarding placenta?","o":["Placental artery provides nutrients through umbilical cord to baby","Placenta has Wharton''s jelly","Placenta has 2 veins and 1 artery","Estrogen is secreted by placenta"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4544, 'OBG', 'Antenatal Care & Complications', 'Easy', 'Obstetrics', 265, '{"id":4544,"subject":"OBG","chapter":"Antenatal Care & Complications","difficulty":"Easy","source":"Obstetrics","sourceNo":265,"q":"Anesthesia of choice for cesarean section in severe pre-eclampsia :","o":["Spinal","GA","Epidural","Spinal+epidural"],"a":2,"e":"Ans. C. Epidural Continuous Epidural Anesthesia is the first choice for patients with preeclampsia during labour, Vaginal delivery and cesarean section. Preeclampsia patients have a risk of severe airway edema , which makes intubation difficult Continuous Epidural Anesthesia can improve uteroplacental perfusion and also decrease catecholamine secretions.","pyqMatches":[{"year":"2018","no":188,"q":"Anesthesia of choice for cesarean section in severe pre-eclampsia :","o":["Spinal","GA","Epidural","Spinal+epidural"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4545, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Obstetrics', 266, '{"id":4545,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Obstetrics","sourceNo":266,"q":"Which of the following is not a high-risk pregnancy?","o":["Previous history of manual removal of placenta","Anemia","Diabetes","Obesity"],"a":0,"e":"Ans. A. Previous history of manual removal of placenta High Risk Pregnancy is seen in : Cardiovascular and renal factors: Moderate to severe preeclampsia Chronic hypertension Severe heart failure (class II-IV, NYHA classification) Moderate to severe renal disorders Metabolic disorders: Obesity Insulin-dependent diabetes Previous endocrine ablation Obstetric history: Fetal exchange transfusion because of Rh incompatibility Stillbirth Late abortion (16–20 wk) Post-term pregnancy (> 42 wk) Preterm newborn (< 37 wk and < 2500 g) Intrauterine growth restriction (weight < 10th percentile for estimated gestational age) Polyhydramnios Multifetal pregnancy Previous brachial plexus injury Abnormal fetal position Other disorders: Abnormal cervical cytologic findings Sickle cell disease Severe anemia Thrombophilia Autoimmune disorders Anatomic abnormalities: Uterine malformation Insufficient (incompetent) cervix Exposure to teratogens: Group B streptococcal infections Smoking > 10 cigarettes/day (associated with premature rupture of membranes) Current pregnancy complications: Preterm labor at < 37 Wks Preterm premature rupture of membranes Moderate to severe preeclampsia Polyhydramnios (hydramnios) or oligohydramnios Post-term (> 42 wk) Uterine rupture Placenta previa Abruptio placentae Chorioamnionitis Prolapsed cord Fetal bradycardia for >30 min Fetal tachycardia for >30 min Fetal weight < 2.5 kg Fetal weight > 4 kg Fetal acidosis pH ≤7","pyqMatches":[{"year":"2018","no":189,"q":"Which of the following is not a high-risk pregnancy?","o":["Previous history of manual removal of placenta","Anemia","Diabetes","Obesity"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4546, 'OBG', 'Antenatal Care & Complications', 'Moderate', 'Obstetrics', 267, '{"id":4546,"subject":"OBG","chapter":"Antenatal Care & Complications","difficulty":"Moderate","source":"Obstetrics","sourceNo":267,"q":"Which of the following is not used in preeclampsia?","o":["Methyldopa","Atenolol","Labetalol","Hydralazine"],"a":1,"e":"Ans. B. Atenolol Choice of anti-hypertensives in pregnancy PIH / pre-eclampsia / severe pre-eclampsia : Labetalol Acute Hypertension/Hypertension crisis : IV labetalol > Nifedipine > Hydralazine Chronic Hypertension in pregnancy : Labetalol > Methyl dopa.","pyqMatches":[{"year":"2018","no":190,"q":"Which of the following is not used in preeclampsia?","o":["Methyldopa","Atenolol","Labetalol","Hydralazine"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4547, 'OBG', 'Contraception & Family Planning', 'Easy', 'Obstetrics', 268, '{"id":4547,"subject":"OBG","chapter":"Contraception & Family Planning","difficulty":"Easy","source":"Obstetrics","sourceNo":268,"q":"Postmenopausal women 1st line of drug for osteoporosis is-","o":["OCP","Bisphosphonates","Raloxifene","Strontium"],"a":1,"e":"Ans. is. B. Bisphosphonates First line of management of osteoporosis – Bisphosphonates females. Alendronate, etidronate, pamidronate, and Ibandronate are bisphosphonates which inhibit bone resorption, and are very effective for both osteoporosis prevention and treatment. Uses: First line drugs for treating postmenopausal osteoporosis Paget’s disease Osteolytic bone metastasis. Raloxifene: It is a selective estrogen receptor modulator which is also useful in management of osteoporosis but it is a hormonal preparation.","pyqMatches":[{"year":"2020","no":212,"q":"Postmenopausal women 1st line of drug for osteoporosis is","o":["OCP","Bisphosphonates","Raloxifene","Strontium"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4548, 'OBG', 'Obstetric Anatomy & Physiology', 'Easy', 'Obstetrics', 269, '{"id":4548,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Easy","source":"Obstetrics","sourceNo":269,"q":"A 36-week old pregnant lady with previous twin delivery. What is the Ovarian score?","o":["G2P1","G2P2","G3P2","G3P3"],"a":0,"e":"ANS. A.G2P1 Gravida includes all confirmed pregnancies. Each pregnancy is only counted one time, even if the pregnancy was multiple gestations, such as twins or triplets Parity reflects the total number of births after 20 weeks, not the total number of infants born. Ref.OBS Dutta 8th ed Page no. 107","pyqMatches":[{"year":"2020","no":221,"q":"A 36-week old pregnant lady with previous twin delivery. What is the Ovarian score?","o":["G2P1","G2P2","G3P2","G3P3"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4549, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Obstetrics', 270, '{"id":4549,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Obstetrics","sourceNo":270,"q":"DCDA twins, 38wks, first twin breech mother has BP 140/96, 1+ proteinuria what''s the management","o":["Immediate LSCS","Induction at 40 weeks","Immediate induction and delivery","Induction if signs of preeclampsia"],"a":0,"e":"ANS. A. Immediate LSCS CASE DISCUSSION: The patient has mild preeclampsia with BP 140 / 96, so TOP is 37 weeks. This patient is 38 weeks so immediate termination of pregnancy is required. The first twin is breech so the mode of delivery is LSCS hence the answer is A. INDICATIONS OF CESAREAN SECTION: The indications are broadly divided into: Obstetric Placenta previa Preeclampsia Previous cesarean section Cord prolapse of the first baby Abnormal uterine contractions Contracted pelvis. For twins: Both the fetuses or even the first fetus with noncephalic (breech or transverse) presentation Twins with complications: IUGR, conjoined twins Monoamniotic twins Monochorionic twins with TTTS The collision of both the heads at brim preventing engagement of either head. Ref.OBS Dutta 8th ed Page no. 244","pyqMatches":[{"year":"2020","no":220,"q":"DCDA twins, 38wks, first twin breech mother has BP 140/96, 1+ proteinuria what''s the management","o":["Immediate LSCS","Induction at 40 weeks","Immediate induction and delivery","Induction if signs of preeclampsia"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4550, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Obstetrics', 271, '{"id":4550,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Obstetrics","sourceNo":271,"q":"A 32-year-old woman complains of amenorrhea since the delivery of a baby 15 months previously, despite the fact that she did not breastfeed her baby. The delivery was complicated by excessive hemorrhage that required a transfusion of 2.5 liters of blood. She has also been fatigued and has gained an additional 4.5Kg since the baby was born. Laboratory data show the following: Serum LH < 1 IU/L (normal, 4-24 IU/L) Serum estradiol 5 pg/mL (normal, 20 - 100 pg/mL) Serum TSH 0.1 mU/L (normal, 0.5 - 5 mU/L) Serum GH 3 ng/mL (normal, < 5 ng/mL) Serum ACTH 28 pg/mL (normal, 10 - 50 pg/mL) Serum prolactin 2 ng/mL (normal, Injection of 500 μg of TRH failed to produce the expected rise in both serum TSH and prolactin. Which of the following diagnoses most likely explains the findings in this patient?","o":["Hashimoto''s thyroiditis","Isolated gonadotropin deficiency","Isolated gonadotropin deficiency","Primary amenorrhea"],"a":3,"e":"Ans. D. Sheehan''s syndrome Sheehan''s syndrome It is hypopituitarism due to ischemic damage to the pituitary resulting from excessive hemorrhage during parturition. The pituitary is enlarged during pregnancy; it is more metabolically active, and more susceptible to hypoxemia. Furthermore, the blood vessels in the pituitary may be more susceptible to vasospasm because of the high estrogen. In about 30% of women who hemorrhage excessively during parturition, some degree of hypopituitarism eventually becomes manifest. The symptoms depend on how much of the pituitary is damaged and what cell types are destroyed. The patient described above exhibited persistent amenorrhea after the delivery of her infant. This is due to the destruction of pituitary gonadotrophs and diminished secretion of gonadotropins (LH). There also appears to have been significant destruction of lactotrophs since TRH injection failed to induce an increase in prolactin. Had the women attempted to breastfeed her infant, a failure to lactate mostly likely would have occurred. This case is also characterized by secondary hypothyroidism. The low TSH and failure to respond to TRH injection are confirmatory. Corticotrophs appear to have been spared since plasma ACTH is normal. It is not clear whether somatotrophs were damaged. Further testing would be needed to see if GH reserve is diminished. Ref. William Obs. ed. 24th page no.798, 1163 Dutta Gynaecology 6th ed. Page no. 465","pyqMatches":[],"pyqYears":[]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4551, 'OBG', 'Obstetric Anatomy & Physiology', 'Moderate', 'Obstetrics', 272, '{"id":4551,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Moderate","source":"Obstetrics","sourceNo":272,"q":"A 7 weeks pregnant lady has 1 accidental exposure to x-ray. Which of the following should be done?","o":["Continue pregnancy","Terminate pregnancy","Chromosome analysis","Pre invasive diagnostic testing"],"a":0,"e":"Ans. A. Continue pregnancy Exposure to X-ray has a very low range of rad so in given case scenario Pregnancy will be continued. Exposure >15 rad during the second and third trimester or >5 rad in the first trimester needs patient counseling. Elective termination of pregnancy may be considered. Ref. OBS Dutta 8th edition Page no. 740 William’s Obs 24th edition Page no. 931 Table no 46-5","pyqMatches":[{"year":"2020","no":217,"q":"A 7 weeks pregnant lady has 1 accidental exposure to x-ray. Which of the following should be done?","o":["Continue pregnancy","Terminate pregnancy","Chromosome analysis","Pre invasive diagnostic testing"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4552, 'OBG', 'Miscellaneous', 'Moderate', 'Obstetrics', 273, '{"id":4552,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Moderate","source":"Obstetrics","sourceNo":273,"q":"In Modern obstetrics, for sensitized Rh- negative mother what should be done to evaluate the condition of the mother?","o":["MCA doppler peak systolic volume","Fetal blood","Amniocentesis","Biophysical profile"],"a":0,"e":"Ans. A. MCA doppler peak systolic volume Doppler ultrasound: Serial Doppler study of the middle cerebral artery (MCA)-peak systolic velocity (PSV) is the mainstay to assess fetal anemia. A value >1.5 multiples of the median (MOMs) for the corresponding gestational age, predicts moderate to severe fetal anemia. This value (between 24 weeks and 35 weeks of gestation), is an indication for cordocentesis and fetal transfusion Most centers have replaced serial amniocentesis with serial MCA Doppler studies. Ref. OBstetrics Dutta ed. 8th pg. 391","pyqMatches":[{"year":"2020","no":216,"q":"In Modern obstetrics, for sensitized Rh- negative mother what should be done to evaluate the condition of the mother?","o":["MCA doppler peak systolic volume","Fetal blood","Amniocentesis","Biophysical profile"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4553, 'OBG', 'Obstetric Anatomy & Physiology', 'Hard', 'Obstetrics', 274, '{"id":4553,"subject":"OBG","chapter":"Obstetric Anatomy & Physiology","difficulty":"Hard","source":"Obstetrics","sourceNo":274,"q":"A patient delivered at home with a complete perineal tear came to the hospital after 2 weeks. What management will you prefer?","o":["Immediate repair","Repair 3 weeks post-delivery","Repair 6 weeks post-delivery","Repair 3 months post-delivery"],"a":3,"e":"Ans. D. Repair 3 months post-delivery The recent tears should be repaired immediately following the delivery of the placenta. This reduces the chance of infection and minimizes blood loss. In cases of delay beyond 24 hours, the repair is to be withheld. Antibiotics should be started to prevent infection. The complete tear should be repaired after 3 months if delayed beyond 24 hours. In case of any doubt to the grade 3rd-degree tear, it is advisable to classify to a higher degree rather than a lower degree. Ref.Obs Dutta 24th edition Page no. 490","pyqMatches":[{"year":"2020","no":215,"q":"A patient delivered at home with a complete perineal tear came to the hospital after 2 weeks. What management will you prefer?","o":["Immediate repair","Repair 3 weeks post-delivery","Repair 6 weeks post-delivery","Repair 3 months post-delivery"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4554, 'OBG', 'Contraception & Family Planning', 'Moderate', 'Obstetrics', 275, '{"id":4554,"subject":"OBG","chapter":"Contraception & Family Planning","difficulty":"Moderate","source":"Obstetrics","sourceNo":275,"q":"All are used for postcoital contraception except-","o":["CuT","Ru 486","High dose estrogen","Danazol"],"a":3,"e":"Ans. D. Danazol EMERGENCY CONTRACEPTIVES: Drug Dose PREGNANCY RATE Levonorgestrel 0.75 mg stat and after 12 hours 0–1 Ethinyl estradiol 50 µg + norgestrel 0.25 mg 2 tab stat and 2 after 12 hours 0–2 Ethinyl estradiol 2.5 mg Bd × 5 days 0–0.6 Mifepristone 100 mg single dose 0–0.6 Copper Iuds (Gold standard) Insertion within 5 days 0–0.1 (RU 486Mifepristone) (ulipristal acetate) 30 mg PO 0–1 Ref:DUTTA GYNAECOLOGY ED. 6TH PAGE NO. 492","pyqMatches":[{"year":"2020","no":214,"q":"All are used for postcoital contraception except","o":["CuT","Ru 486","High dose estrogen","Danazol"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4555, 'OBG', 'Miscellaneous', 'Hard', 'Obstetrics', 276, '{"id":4555,"subject":"OBG","chapter":"Miscellaneous","difficulty":"Hard","source":"Obstetrics","sourceNo":276,"q":"33 yr old female with heavy menstrual bleeding for 6 months comes to the gynaecology OPD. On examination, no abnormality was seen. USG also appeared normal. The patient was tried to be managed on non-hormonal treatment but it failed. What will be the next management step?","o":["Hormonal therapy","Endometrial sampling","Hysterectomy","Hysterectomy"],"a":1,"e":"Ans. B.Endometrial sampling Before starting Hormonal therapy endometrial sampling is done as if hormonal therapy precedes sampling the sampling results will be altered. As already mentioned in question the USG and clinical examination show no abnormality hence the diagnosis can’t be made on that so for diagnosis we need to do endometrial sampling and see the hormonal pattern. Then we can proceed with hormonal therapy. Ref. Dutta Gynaecology ed. 6th page no. 120","pyqMatches":[{"year":"2020","no":211,"q":"33 yr old female with heavy menstrual bleeding for 6 months comes to the gynaecology OPD. On examination, no abnormality was seen. USG also appeared normal. The patient was tried to be managed on non-hormonal treatment but it failed. What will be the next management step?","o":["Hormonal therapy","Endometrial sampling","Hysterectomy","Hysterectomy"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4556, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 1, '{"id":4556,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":1,"q":"Transducin is a protein found in:","o":["Glomerulus","Retina","Skeletal muscle","Adrenal medulla"],"a":1,"e":"Retina REF: Ganong 22nd edition, chapter 8, http://en.wikipedia.org/wiki/Transducin Transducin (also called Gt) is a heterotrimeric G protein that is naturally expressed in vertebrate retina rods and cones. Mechanism of action: Heterotrimeric Transducin (alpha-beta-gamma subunits) is activated by a conformational change in rhodopsin due to the absorption of a photon by rhodopsin''s active group retinal. Activation causes the GDP bound to the alpha subunit to be exchanged with GTP from solution and results in activated alpha dissociating from beta-gamma. Active Transducin-alpha then causes cyclic GMP Phosphodiesterase to increase its activity, thereby lowering the concentration of cGMP, an intracellular second-messenger molecule. Decrease in cGMP concentration leads to the closure of cGMP-regulated Na+ and Ca2+ ion channels and a hyperpolarized membrane potential. This chain of signaling events is also called \"the vertebrate photo transduction cascade\"","pyqMatches":[{"year":"2012","no":167,"q":"Transducin is a protein found in:","o":["Glomerulus","Retina","Skeletal muscle","Adrenal medulla"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4557, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 2, '{"id":4557,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":2,"q":"Treatment of mooren''s ulcer is?","o":["Corneal graft","Immunosuppressives","Topical steroids","All of the above"],"a":3,"e":"All of the above REF: Khurana 4th ed p. 110 MOOREN''S ULCER: Severe inflammatory peripheral ulcerative keratitis , chronic serpigenous or rodent ulcer Treatment:","pyqMatches":[{"year":"2016","no":970,"q":"Treatment of mooren''s ulcer is?","o":["Corneal graft","Immunosuppressives","Topical steroids","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4558, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 3, '{"id":4558,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":3,"q":"The percentage of atropine present in atropine drops as cycloplegic is:","o":["0.5%","1%","4%","2%"],"a":1,"e":"1%","pyqMatches":[{"year":"2016","no":979,"q":"The percentage of atropine present in atropine drops as cycloplegic is:","o":["0.5%","1%","4%","2%"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4559, 'Ophthalmology', 'Cornea & External Eye', 'Moderate', 'Ophthalmology', 4, '{"id":4559,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Moderate","source":"Ophthalmology","sourceNo":4,"q":"All of the following are true about Keratoconus, except:","o":["Increased curvature of corneaAstigmatism","Astigmatism","K.F ring cornea","Thick cornea"],"a":3,"e":"The main pathological changes in Keratoconus are thinning and ectasia of the lens which occur as a result of defective synthesis of mucopolysaccharide and collagen tissue.","pyqMatches":[{"year":"2015","no":1018,"q":"All of the following are true about Keratoconus, except:","o":["Increased curvature of corneaAstigmatism","Astigmatism","K.F ring cornea","Thick cornea"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4560, 'Ophthalmology', 'Refraction & Optics', 'Moderate', 'Ophthalmology', 5, '{"id":4560,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Moderate","source":"Ophthalmology","sourceNo":5,"q":"Which of the following condition is associated with the development of posterior staphyloma?","o":["Pathological myopia","Retinoblastoma","Acid injury","Sympathetic ophthalmia"],"a":0,"e":"Posterior staphyloma, the posterior outpouching of the wall of the eye, is an important component of the diagnosis of pathologic myopia; indeed, it is one of the hallmarks of pathologic myopia. With the exception of inferior staphyloma related to tilted disc syndrome, it does not occur in pathologies other than pathologic myopia. Thus, the presence of staphyloma is specific to pathologic myopia and critically important in differentiating simple school myopia with good best corrected visual acuity (BCVA) and pathologic myopia that could cause the loss of BCVA.","pyqMatches":[{"year":"2014","no":1172,"q":"Which of the following condition is associated with the development of posterior staphyloma?","o":["Pathological myopia","Retinoblastoma","Acid injury","Sympathetic ophthalmia"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4561, 'Ophthalmology', 'Uvea', 'Hard', 'Ophthalmology', 6, '{"id":4561,"subject":"Ophthalmology","chapter":"Uvea","difficulty":"Hard","source":"Ophthalmology","sourceNo":6,"q":"A 30 year old man presents to the clinic with pain in the eye, watering, redness and photophobia. Examination of his eyes shows circumcorneal congestion and keratic precipitates. Assertion: KPs are proteinaceous deposits occurring in a triangular fashion in the inferior part of cornea. Reason: Mutton fat KPs are seen in granulomatous iridocyclitis and is composed of epitheloid cells and macrophages.","o":["Both Assertion and Reason are true, and Reason is the correct explanation for Assertion","Both Assertion and Reason are true, and Reason is not the correct explanation for Assertion","Assertion is true, but Reason is false","Assertion is false but reason is true"],"a":1,"e":"Keratic precipitates are proteinaceous deposits occurring in a triangular fashion in the inferior part of cornea due to convection currents in the aqueous humor. Mutton fat KPs are seen in granulomatous iridocyclitis and is composed of epithelioid cells and macrophages. They are usually 10-15 in number. Ref: Comprehensive Ophthalmology by AK Khurana, 4th Edition, Page 142","pyqMatches":[{"year":"2015","no":1014,"q":"A 30 year old man presents to the clinic with pain in the eye, watering, redness and photophobia. Examination of his eyes shows circumcorneal congestion and keratic precipitates. Assertion: KPs are proteinaceous deposits occurring in a triangular fashion in the inferior part of cornea. Reason: Mutton fat KPs are seen in granulomatous iridocyclitis and is composed of epitheloid cells and macrophages.","o":["Both Assertion and Reason are true, and Reason is the correct explanation for Assertion","Both Assertion and Reason are true, and Reason is not the correct explanation for Assertion","Assertion is true, but Reason is false","Assertion is false but reason is true"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4562, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 7, '{"id":4562,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":7,"q":"Transport of Ascorbic acid to lens is done by which of the following?","o":["Myoinositol","Choline","Taurine","Na-K ATPase"],"a":3,"e":"The lens epithelium is the principal site of energy production of the lens that is used for transport of inorganic ions and amino acids by an active process involving Na and K activated ATPase. Ref: Histopathology of Preclinical Toxicity Studies: Interpretation and Relevance ... By Peter Greaves, Peter Greaves (M.B., Ch.B.), 2007, Page 896; Transport of vitamin C in the lens, Curr Eye Res. 1987 Jul;6(7):885-96; Adler''s Physiology of the eye 10th Edition, Page 131; Ascorbic acid and the Eye, Am J Clin Nutr 1991;54:1198S-1202S.","pyqMatches":[{"year":"2016","no":984,"q":"Transport of Ascorbic acid to lens is done by which of the following?","o":["Myoinositol","Choline","Taurine","Na-K ATPase"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4563, 'Ophthalmology', 'Retina & Vitreous', 'Hard', 'Ophthalmology', 8, '{"id":4563,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Hard","source":"Ophthalmology","sourceNo":8,"q":"Fundus fluorescein angiography done in a patient following cataract surgery shows a flower petal pattern. What is he MOST likely suffering from?","o":["Macular hole","Cystoid macular edema","Central serous retinopathy","None of the above"],"a":1,"e":"He is showing features of cystoid macular edema. Cystoid macular edema refers to a condition in which there is fluid accumulation in honeycomb like spaces of the outer plexiform and inner nuclear layers. Fluorescein angiography done shows leakage of fluorescein dye from the perifoveal retinal capillaries and peripapillary region, and accumulating in a flower-petal pattern around the fovea. It most frequent occur following cataract surgery, especially if the surgery was complicated or prolonged. It usually manifests at 4–12 weeks postoperatively. Ref: Fletcher E.C., Chong N., Augsburger J.J., Corrêa Z.M. (2011). Chapter 10. Retina. In P. Riordan-Eva, E.T. Cunningham, Jr. (Eds), Vaughan & Asbury''s General Ophthalmology, 18e","pyqMatches":[{"year":"2013","no":1126,"q":"Fundus fluorescein angiography done in a patient following cataract surgery shows a flower petal pattern. What is he MOST likely suffering from?","o":["Macular hole","Cystoid macular edema","Central serous retinopathy","None of the above"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4564, 'Ophthalmology', 'Uvea', 'Easy', 'Ophthalmology', 9, '{"id":4564,"subject":"Ophthalmology","chapter":"Uvea","difficulty":"Easy","source":"Ophthalmology","sourceNo":9,"q":"Painful eye movement is a feature of :","o":["Iridocyclitis","Papilledema","Corneal ulcer","Vernal catarrh"],"a":0,"e":"Anterior uveitis , also known as iridocyclitis and iritis, is the inflammation of the iris and anterior chamber. Anywhere from two-thirds to 90% of uveitis cases are anterior in location. Injection, photophobia, pain, and blurred vision usually accompany iritis (anterior uveitis or iridocyclitis). Ref : Braverman R.S. (2012). Chapter 16. Eye. In W.W. Hay, Jr., M.J. Levin, R.R. Deterding, J.J. Ross, J.M. Sondheimer (Eds), CURRENT Diagnosis & Treatment: Pediatrics, 21e.","pyqMatches":[{"year":"2016","no":1014,"q":"Painful eye movement is a feature of :","o":["Iridocyclitis","Papilledema","Corneal ulcer","Vernal catarrh"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4565, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 10, '{"id":4565,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":10,"q":"Kayser Fleischer ring is found in which layer of cornea?","o":["Bowman''s Capsule","Substantia propria","Descemet’s membrane","Endothelium"],"a":2,"e":"Kayser-Fleischer rings take the form of a crescentic rusty-brown discoloration of the deepest layer of the cornea (Descemet membrane). In the purely hepatic stage of the disease, the rings may not be evident (in 25 percent of cases), but they are virtually always present (if properly sought) once the neurologic signs manifests. A slit-lamp examination may be necessary for their early detection, particularly in brown-eyed patients, but in the majority of patients with neurologic signs the rings can be visualized with the naked eye or with the aid of an indirect ophthalmoscope focused on the limbus. Also Know: Kayser-Fleischer rings are a sign of Wilson''s disease, which involves abnormal copper handling by the liver resulting in copper accumulation in the body and is characterised by abnormalities of the basal ganglia of the brain, liver cirrhosis, splenomegaly, involuntary movements, muscle rigidity, psychiatric disturbances, dystonia and dysphagia. The combination of neurological symptoms, a low blood ceruloplasmin level and KF rings is diagnostic of Wilson''s disease. Ref: Ropper A.H., Samuels M.A. (2009). Chapter 37. Inherited Metabolic Diseases of the Nervous System. In A.H. Ropper, M.A. Samuels (Eds),Adams and Victor''s Principles of Neurology, 9e.","pyqMatches":[{"year":"2015","no":1011,"q":"Kayser Fleischer ring is found in which layer of cornea?","o":["Bowman''s Capsule","Substantia propria","Descemet’s membrane","Endothelium"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4566, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 11, '{"id":4566,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":11,"q":"Placido disc is used for diagnosing which of the following condition?","o":["Uveitis","Keratoconus","Retinoblastoma","Retinal detachment"],"a":1,"e":"Placido disc examination is used to diagnose keratoconus. In a case of keratoconus, placido disc examination shows irregularities of the circles. Placido’s keratoscopic disc: It is a disc painted with alternating black and white circles. It may be used to assess the smoothness and curvature of corneal surface. Normally, on looking through the hole in the center of disc a uniform sharp image of the circle is seen on the cornea. Distortion of the circles occur when irregularities are present on the corneal surface. Ref: Comprehensive Ophthalmology By AK Khurana, 4th edn, page 119","pyqMatches":[{"year":"2016","no":960,"q":"Placido disc is used for diagnosing which of the following condition?","o":["Uveitis","Keratoconus","Retinoblastoma","Retinal detachment"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4567, 'Ophthalmology', 'Optic Nerve & Neuro-ophthalmology', 'Easy', 'Ophthalmology', 12, '{"id":4567,"subject":"Ophthalmology","chapter":"Optic Nerve & Neuro-ophthalmology","difficulty":"Easy","source":"Ophthalmology","sourceNo":12,"q":"Macular sparing is associated with lesions in:","o":["Optic nerve","Lateral geniculate body","Occipital cortex","Optic chiasma"],"a":2,"e":"Macular sparing, that is, loss of peripheral vision with intact macular vision, is also common with occipital lesions Ref: Ganong''s Review of Medical Physiology 23rd edition, Chapter 12.","pyqMatches":[{"year":"2015","no":1059,"q":"Macular sparing is associated with lesions in:","o":["Optic nerve","Lateral geniculate body","Occipital cortex","Optic chiasma"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4568, 'Ophthalmology', 'Cornea & External Eye', 'Moderate', 'Ophthalmology', 13, '{"id":4568,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Moderate","source":"Ophthalmology","sourceNo":13,"q":"All statements are true about trachoma except","o":["Trachoma is caused by bedsonian organism of psittacosis - lymphogranuloma - trachoma (PLT) group.","Strains mainly responsible are A, B, Ba and C","Marked papillary hyperplasia with limbal follicles are seen in stage III","Corneal ulcerstion is a complication"],"a":2,"e":"C. i.e. Marked papillary hyperplasia with limbal follicles are seen in stage III >Trachoma is caused by a Bedsonian organism, the Chlamydia trachomatis belonging to the Psittacosis-lymphogranulomatrachoma (PLT) group. >Serotypes A, B, Ba and C are associated with hyperendemic (blinding) trachoma, while serotypes D-K are associated with paratrachoma (oculogenital chlamydial disease). >Congestion of upper tarsal and forniceal conjunctiva. 2. Conjunctival follicles. Follicles look like boiled sagograins and are commonly seen on upper tarsal conjunctiva and fornix; but may also be present in the lower fornix, plica semilunaris and caruncle. Sometimes, (follicles may be seen on the bulbar conjunctiva (pathognomic of trachoma). >Pannus i.e., infiltration of the cornea associated with vascularization is seen in upper part >Grading of trachoma McCallan''s classification McCallan in 1908, divided the clinical course of the trachoma into following four stages: Stage I (Incipient trachoma or stage of infiltration). It is characterized by hyperaemia of palpebral conjunctiva and immature follicles. Stage II (Established trachoma or stage of florid infiltration). It is characterized by appearance of mature follicles, papillae and progressive corneal pannus. Fig. 4.14. Trachomatous Herbert''s pits. A B 66 Comprehensive OPHTHALMOLOGY Stage III (Cicatrising trachoma or stage of scarring). It includes obvious scarring of palpebral conjunctiva. Stage IV (Healed trachoma or stage of sequelae). The disease is quite and cured but sequelae due to cicatrisation give rise to symptoms. - The clinical diagnosis of trachoma is made from its typical signs; at least two sets of signs should be present out of the following: 1. Conjunctival follicles and papillae 2.Pannus progressive or regressive 3. Epithelial keratitis near superior limbus 4. Signs of cicatrisation or its sequelae.","pyqMatches":[{"year":"2013","no":1138,"q":"All statements are true about trachoma except","o":["Trachoma is caused by bedsonian organism of psittacosis - lymphogranuloma - trachoma (PLT) group.","Strains mainly responsible are A, B, Ba and C","Marked papillary hyperplasia with limbal follicles are seen in stage III","Corneal ulcerstion is a complication"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4569, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 14, '{"id":4569,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":14,"q":"Satellite nodules are seen in","o":["Fungal corneal ulcer","Tuberculosis","Sarcoidosis","Viral ulcer"],"a":0,"e":"A i.e. Fungal corneal ulcer","pyqMatches":[{"year":"2012","no":937,"q":"Satellite nodules are seen in","o":["Fungal corneal ulcer","Tuberculosis","Sarcoidosis","Viral ulcer"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4570, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 15, '{"id":4570,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":15,"q":"Herpetic keratitis is treated by","o":["Analgesics","Atropine","Steroids","Idoxuridine"],"a":3,"e":"Ans: D i.e. Idoxuridine Drug of choice for herpetic keratitis is Acyclovir Q (topical) Other antiviral drugs used are Idoxuridine Trifluorothyrnidine Vidarabine","pyqMatches":[{"year":"2012","no":935,"q":"Herpetic keratitis is treated by","o":["Analgesics","Atropine","Steroids","Idoxuridine"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4571, 'Ophthalmology', 'Cornea & External Eye', 'Moderate', 'Ophthalmology', 16, '{"id":4571,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Moderate","source":"Ophthalmology","sourceNo":16,"q":"Interstitial keratitis is seen in all except:","o":["Syphilis","Acanthamoeba","HSV ChlamydiaTrachomatis","HZV"],"a":1,"e":"B i.e. Achanthamoeba > acquired syphilis)Q - Herpetic keratitis (including chicken pox; HSV is now the most common cause) Other viral infections (HSV, Herpes zoster, Epstein Barr, mumps, measels etc) - Tuberculosis, leprosy - Sarcoidosis - Trypanosomiasis, - Malaria - Cogan''s syndrome (d/t chlamydinQ etc) \" v:shapes=\"_x0000_s1027\">Interstitial keratitis (IK) Interstitial keratitis (IK) is nonsuppurative inflammation of corneal stroma without primary involvement of epithelium or endothelium. In most cases the inflammation is an immune mediated process triggered by an appropriate antigen. Immune stromal keratitis manifests as focal, multifocal or diffuse stromal opacities or an immune ring. It is often accompanied by stromal edema and mild anterior chamber reaction, while sparing epithelium and endothelium. It is called IK if accompanied by vascularization. HSVQ is now the most common cause of IK (esp.unilateral). Unlike syphilitic (luetic) IK, HSV neovascularization is usually sectoral & leads upto stromal scar. - Syphilis related (congenital >> acquired) IK is usually bilateral, although usually not simultaneous. It presents with characteristic salmon patch appearance, granulomatnus anterior ureitis, and ghost vessels and feathery deep stromal scarring in healed stage. - Cogan''s syndrome is chronic bilateral deep nonsyphilitic IK with vestibuloauditory chysfunction (i.e. neuro sensory deafness, vertigo & tinnitus) because of systemic autoimmune vasculitis (life thereatening in 10%). Serum antibodies to various • infectious agents (Lyme disease, Chalamydia, type 1 poliovirus) have been associated with Cogan''s syndrome.","pyqMatches":[{"year":"2013","no":1152,"q":"Interstitial keratitis is seen in all except:","o":["Syphilis","Acanthamoeba","HSV ChlamydiaTrachomatis","HZV"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4572, 'Ophthalmology', 'Retina & Vitreous', 'Hard', 'Ophthalmology', 17, '{"id":4572,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Hard","source":"Ophthalmology","sourceNo":17,"q":"An elderly male with heart disease presents with sudden loss of vision in one eye; examination reveals cherry red spot; diagnosis is:","o":["Central retinal vein occlusion","Central retinal artery occlusion","Amaurosis fugax","Acute ischemic optic neuritis"],"a":1,"e":"B i.e. Central Retinal Artery Occlusion Central retinal artery occlusion characteristically presents with sudden painless loss of vision, cherry red spot & cattle-truck appearanceQ (of retinal veins usually). Source of emboli from carotid artery & heart disease, and thrombus from arteriosclerosis along with hypertension & arteritis are predisposing factors.","pyqMatches":[{"year":"2016","no":1004,"q":"An elderly male with heart disease presents with sudden loss of vision in one eye; examination reveals cherry red spot; diagnosis is:","o":["Central retinal vein occlusion","Central retinal artery occlusion","Amaurosis fugax","Acute ischemic optic neuritis"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4573, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 18, '{"id":4573,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":18,"q":"Primary aim of retinal detachment surgery","o":["Removal of vitreous","Drainage of subretinal fluid","Vitrectomy","Encirclage"],"a":3,"e":"D i.e. Encirclage The main objective of the treatment of retinal detachment is to seal and support the retinal breakQ.","pyqMatches":[{"year":"2013","no":1179,"q":"Primary aim of retinal detachment surgery","o":["Removal of vitreous","Drainage of subretinal fluid","Vitrectomy","Encirclage"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4574, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 19, '{"id":4574,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":19,"q":"Which of the following antiglaucoma medications can cause drowsiness?","o":["Latanoprost","Timolol","Brimonidine","Dorzolamide"],"a":2,"e":"C i.e. Brimonidine","pyqMatches":[{"year":"2013","no":1176,"q":"Which of the following antiglaucoma medications can cause drowsiness?","o":["Latanoprost","Timolol","Brimonidine","Dorzolamide"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4575, 'Ophthalmology', 'Optic Nerve & Neuro-ophthalmology', 'Moderate', 'Ophthalmology', 20, '{"id":4575,"subject":"Ophthalmology","chapter":"Optic Nerve & Neuro-ophthalmology","difficulty":"Moderate","source":"Ophthalmology","sourceNo":20,"q":"All are true regarding optic neuritis except:","o":["Decreased visual acuity","Decreased pupillary reflex","Abnormal electroretinogram","Abnormal visual evoked response retinogram"],"a":2,"e":"C i.e. Abnormal electroretinogram Electroretinogram indicates the activity of retinal (esp. rods & cones) function and has no role in assessing the functional integrity of the optic nerve Q. So it can''t be abnormal in optic neuritis.","pyqMatches":[{"year":"2015","no":1055,"q":"All are true regarding optic neuritis except:","o":["Decreased visual acuity","Decreased pupillary reflex","Abnormal electroretinogram","Abnormal visual evoked response retinogram"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
