INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4577, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 22, '{"id":4577,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":22,"q":"In which of the following conditions Berlin''s edema is","o":["Open angle glaucoma","After cataract surgery","After concussional trauma","Diabetic retinopathy"],"a":2,"e":"C i.e. After concussion trauma Blunt trauma to eye may produce Berlin''s edema or commotio retinae Q which is a cloudy swelling characterized by a grey appaerance, most frequently in the temporal region. It may also manifest as cherry red spot in the foveal region.","pyqMatches":[{"year":"2015","no":1065,"q":"In which of the following conditions Berlin''s edema is","o":["Open angle glaucoma","After cataract surgery","After concussional trauma","Diabetic retinopathy"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
