INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4583, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 28, '{"id":4583,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":28,"q":"Sturm''s conoid refers to configuration of the rays refracted through:","o":["Concave spherical surface","Convex spherical surface","Toric surface","Irregular surface"],"a":2,"e":"Ans. Toric surface SturmS Conoid It is an optical condition in which the refractive power of lens or cornea is not the same in all meridians, hence two focal points separated by a focal interval are formed which is called the Sturm''s Conoid.","pyqMatches":[{"year":"2015","no":988,"q":"Sturm''s conoid refers to configuration of the rays refracted through:","o":["Concave spherical surface","Convex spherical surface","Toric surface","Irregular surface"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
