INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4588, 'Ophthalmology', 'Community Ophthalmology', 'Easy', 'Ophthalmology', 33, '{"id":4588,"subject":"Ophthalmology","chapter":"Community Ophthalmology","difficulty":"Easy","source":"Ophthalmology","sourceNo":33,"q":"Swimming pool conjunctivitis is caused by","o":["Chlamydia trachomatis","Adenovirus type 8","Adenovirus type 8","Gonococcus"],"a":0,"e":"Ans., Chlamydia trachomatis","pyqMatches":[{"year":"2016","no":780,"q":"Swimming pool conjunctivitis is caused by","o":["Chlamydia trachomatis","Adenovirus type 8","Adenovirus type 8","Gonococcus"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4589, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 34, '{"id":4589,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":34,"q":"Goldenhar syndrome is associated with which prominent ocular manifestation:","o":["Microcornea","Megalocornea","Sclerocornea","Epibulbar dermoids"],"a":3,"e":"Ans. Epibulbar dermoids Goldenhar syndrome (oculoauriculovertebral dysplasia with hemifacial microsomia) is a rare congenital developmental anomaly involving the first and second branchial arches. The classic features of this syndrome include ocular changes such as microphthalmia, epibulbar dermoids, lipodermoids and coloboma; aural features such as preauricular tragi, hearing loss and microtia; and vertebral anomalies such as scoliosis, hemivertebrae and cervical fusion. Other ocular anomalies are rare but include microphthalmos, microcornea, anophthalmos, eyelid colobomas, iris and choroid colobomas, motility disorders, strabismus, blepharoptosis, palpebral fissure, iris atrophy, polar cataract, anomalous lacrimal drainage system, and retinal and optic nerve anomalies","pyqMatches":[{"year":"2014","no":1694,"q":"Goldenhar syndrome is associated with which prominent ocular manifestation:","o":["Microcornea","Megalocornea","Sclerocornea","Epibulbar dermoids"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
