INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4598, 'Ophthalmology', 'Lens & Cataract', 'Moderate', 'Ophthalmology', 43, '{"id":4598,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Moderate","source":"Ophthalmology","sourceNo":43,"q":"A child has got a congenital cataract involving the visual axis which was detected by the parents right at birth. This child should be operated:","o":["Immediately","At 2 months of age","At 1 year of age when the globe becomes normal sized","After 4 years when entire ocular and orbital growth becomes normal"],"a":0,"e":"Ans. A [Immediately] Congenital cataract - Timing of surgery","pyqMatches":[{"year":"2013","no":1110,"q":"A child has got a congenital cataract involving the visual axis which was detected by the parents right at birth. This child should be operated:","o":["Immediately","At 2 months of age","At 1 year of age when the globe becomes normal sized","After 4 years when entire ocular and orbital growth becomes normal"],"a":0,"source":"NEET_2013_Paper.pdf"},{"year":"2016","no":994,"q":"A child has got a congenital cataract involving the visual axis which was detected by the parents right at birth. This child should be operated:","o":["Immediately","At 2 months of age","At 1 year of age when the globe becomes normal sized","After 4 years when entire ocular and orbital growth becomes normal"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2013","2016"]}');
