INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4603, 'Ophthalmology', 'Retina & Vitreous', 'Moderate', 'Ophthalmology', 48, '{"id":4603,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Moderate","source":"Ophthalmology","sourceNo":48,"q":"All of the following are true for retinopathy of prematurity except:","o":["Occurs in premature infants due to late crying","Due to hypoxia there occurs neovascularization followed by fibroproliferation","End result is bilateral blindness","Blindness can be prevented by early diagnosis and ablation of vascular premature retina with cryotherapy or photocoagulation"],"a":0,"e":"Ans. Occurs in premature infants due to late crying","pyqMatches":[{"year":"2015","no":1045,"q":"All of the following are true for retinopathy of prematurity except:","o":["Occurs in premature infants due to late crying","Due to hypoxia there occurs neovascularization followed by fibroproliferation","End result is bilateral blindness","Blindness can be prevented by early diagnosis and ablation of vascular premature retina with cryotherapy or photocoagulation"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4604, 'Ophthalmology', 'Retina & Vitreous', 'Moderate', 'Ophthalmology', 49, '{"id":4604,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Moderate","source":"Ophthalmology","sourceNo":49,"q":"All of the following are the causes of exudative retinal detachment except:","o":["Retinopathy of toxaemia of pregnancy","Retinopathy of prematurity","Exudative retinopathy of Coats","Sympathetic ophthalmia"],"a":1,"e":"Ans. Retinopathy of prematurity","pyqMatches":[{"year":"2016","no":1000,"q":"All of the following are the causes of exudative retinal detachment except:","o":["Retinopathy of toxaemia of pregnancy","Retinopathy of prematurity","Exudative retinopathy of Coats","Sympathetic ophthalmia"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4605, 'Ophthalmology', 'Retina & Vitreous', 'Moderate', 'Ophthalmology', 50, '{"id":4605,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Moderate","source":"Ophthalmology","sourceNo":50,"q":"The earliest change noticed in hypertensive retinopathy is:","o":["Soft exudate","Arteriolar spasm","Venospasm","Hard exudate"],"a":1,"e":"Ans. Arteriolar spasm","pyqMatches":[{"year":"2013","no":1206,"q":"The earliest change noticed in hypertensive retinopathy is:","o":["Soft exudate","Arteriolar spasm","Venospasm","Hard exudate"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4606, 'Ophthalmology', 'Ocular Motility & Strabismus', 'Hard', 'Ophthalmology', 51, '{"id":4606,"subject":"Ophthalmology","chapter":"Ocular Motility & Strabismus","difficulty":"Hard","source":"Ophthalmology","sourceNo":51,"q":"Strabismic amblyopia is more common in patients with:","o":["Intermittent squint","Alternate squint","Constant squint","Latent squint"],"a":2,"e":"Ans. Constant squint","pyqMatches":[{"year":"2015","no":993,"q":"Strabismic amblyopia is more common in patients with:","o":["Intermittent squint","Alternate squint","Constant squint","Latent squint"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4607, 'Ophthalmology', 'Ocular Motility & Strabismus', 'Easy', 'Ophthalmology', 52, '{"id":4607,"subject":"Ophthalmology","chapter":"Ocular Motility & Strabismus","difficulty":"Easy","source":"Ophthalmology","sourceNo":52,"q":"Onset of stereopsis occurs at the age of:","o":["3 to 5 months","1 to 2 years","5 years","7 years"],"a":0,"e":"Ans. 3 to 5 months","pyqMatches":[{"year":"2016","no":1008,"q":"Onset of stereopsis occurs at the age of:","o":["3 to 5 months","1 to 2 years","5 years","7 years"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4608, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 53, '{"id":4608,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":53,"q":"Elevators of eye:","o":["SR and 10","I0 and SO","IR and S","SO SR"],"a":0,"e":"Ans. SR and 10","pyqMatches":[{"year":"2013","no":1196,"q":"Elevators of eye:","o":["SR and 10","I0 and SO","IR and S","SO SR"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4609, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Easy', 'Ophthalmology', 54, '{"id":4609,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Easy","source":"Ophthalmology","sourceNo":54,"q":"Dalrymple''s sign of ocular Graves'' disease refers to:","o":["Retraction of the upper lid","Lid lag","Proptosis","All of the above combinedly"],"a":0,"e":"Ans. Retraction of the upper lid","pyqMatches":[{"year":"2015","no":1058,"q":"Dalrymple''s sign of ocular Graves'' disease refers to:","o":["Retraction of the upper lid","Lid lag","Proptosis","All of the above combinedly"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4610, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 55, '{"id":4610,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":55,"q":"Best method of detection of retained glass intraocular foreign body is:","o":["CT scan","Radiography","Ultrasonography","Tonography"],"a":0,"e":"Ans. CT scan","pyqMatches":[{"year":"2015","no":1063,"q":"Best method of detection of retained glass intraocular foreign body is:","o":["CT scan","Radiography","Ultrasonography","Tonography"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4611, 'Ophthalmology', 'Glaucoma', 'Moderate', 'Ophthalmology', 56, '{"id":4611,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Moderate","source":"Ophthalmology","sourceNo":56,"q":"In primary open-angle glaucoma pilocarpine eye drops lowers the intraocular pressure by its direct action on the:","o":["Trabecular meshwork","Ciliary epithelium","Longitudinal fibres of the ciliary muscle","All of the above"],"a":3,"e":"Ans. D� Pilocarpine as eye drops it is�used�to manage�angle closure glaucoma�until surgery can be performed, ocular hypertension, primary�open angle glaucoma, and to bring about constriction of the pupil following its dilation. Mechanism of�Action: Pilocarpine�is�used�as a miotic and in the treatment of glaucoma Pilocarpine�contracts the ciliary muscle, causing increased tension on the scleral spur and opening of the trabecular meshwork spaces to facilitate outflow of aqueous humor. Outflow resistance is�reduced,�lowering intraocular pressure�(IOP).","pyqMatches":[{"year":"2015","no":985,"q":"In primary open-angle glaucoma pilocarpine eye drops lowers the intraocular pressure by its direct action on the:","o":["Trabecular meshwork","Ciliary epithelium","Longitudinal fibres of the ciliary muscle","All of the above"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4612, 'Ophthalmology', 'Optic Nerve & Neuro-ophthalmology', 'Easy', 'Ophthalmology', 57, '{"id":4612,"subject":"Ophthalmology","chapter":"Optic Nerve & Neuro-ophthalmology","difficulty":"Easy","source":"Ophthalmology","sourceNo":57,"q":"Isolated painful third nerve palsy is a feature of aneurysms of:","o":["Posterior communicating artery","Anterior communicating artery","Vertebrobasillary artery","Ophthalmic artery"],"a":0,"e":"Ans. Posterior communicating artery The most common of all intracranial aneurysms, posterior communicating artery aneurysms present with ipsilateral third nerve palsy (thus dilating the pupil) Isolated cranial nerve palsy frequently involves the third cranial nerve due to its anatomic surroundings when leaving the brainstem. (PCOM) is the most common type of aneurysm to form in the basal cistern. The majority of symptomatic aneurysms of the PCOM present as an oculomotor nerve palsy (ONP), which can develop directly via mass effect of the growing aneurysm or indirectly via rupture of the aneurysm","pyqMatches":[{"year":"2013","no":1289,"q":"Isolated painful third nerve palsy is a feature of aneurysms of:","o":["Posterior communicating artery","Anterior communicating artery","Vertebrobasillary artery","Ophthalmic artery"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4613, 'Ophthalmology', 'Community Ophthalmology', 'Easy', 'Ophthalmology', 58, '{"id":4613,"subject":"Ophthalmology","chapter":"Community Ophthalmology","difficulty":"Easy","source":"Ophthalmology","sourceNo":58,"q":"All of the following are given global prominence in the VISION 2020 goal, expect:","o":["Refractive errors","Cataract","Trachoma","Glaucoma"],"a":3,"e":"Ans. Glaucoma","pyqMatches":[{"year":"2012","no":836,"q":"All of the following are given global prominence in the VISION 2020 goal, expect:","o":["Refractive errors","Cataract","Trachoma","Glaucoma"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4614, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 59, '{"id":4614,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":59,"q":"Axial length of eye ball is: March 2005","o":["16 mm","20 mm","24 mm","28 mm"],"a":2,"e":"Ans. C: 24 mm The eye of the newborn is hypermetropic and the average axial length is about 18mm.At the age of 3 years it is 23 mm and from age 3-14 years it increases by 1 mm. In the emmetropic eye, the axial length (from the posterior corneal surface to the retina) varies from 22 to 26 millimeters. In the emmetropic eye (which has no refractive error), the range of corneal refracting power is between 39 and 48 diopters, while the range of lenticular refracting power is between 15 and 24 diopters.","pyqMatches":[{"year":"2015","no":986,"q":"Axial length of eye ball is: March 2005","o":["16 mm","20 mm","24 mm","28 mm"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4615, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 60, '{"id":4615,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":60,"q":"Eye structure with maximum refractive power: March 2007","o":["Anterior surface of lens","Posterior surface of lens","Anterior surface of cornea","Posterior surface of cornea"],"a":2,"e":"Ans. C: Anterior surface of cornea Together with the lens, the cornea refracts light, accounting for approximately two-thirds of the eye''s total optical power. In humans, the refractive power of the cornea is approximately 43 dioptres. While the cornea contributes most of the eye''s focusing power, its focus is fixed. The curvature of the lens, on the other hand, can be adjusted to \"tune\" the focus depending upon the object''s distance.","pyqMatches":[{"year":"2012","no":922,"q":"Eye structure with maximum refractive power: March 2007","o":["Anterior surface of lens","Posterior surface of lens","Anterior surface of cornea","Posterior surface of cornea"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4616, 'Ophthalmology', 'Glaucoma', 'Moderate', 'Ophthalmology', 61, '{"id":4616,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Moderate","source":"Ophthalmology","sourceNo":61,"q":"Pilocarpine is used in all of the following except: September 2006","o":["Primary, Open Angle Glaucoma","Malignant Glaucoma","Acute Angle Closure Glaucoma","Chronic Synechial Angle Closure Glaucoma"],"a":1,"e":"Ans. B: Malignant Glaucoma Management of angle-closure secondary to ciliochoroidal effusion is directed at two processes: The first is uveal inflammation, which is treated with oral steroids to reduce the effusion and allow the chamber to deepen spontaneously as the inflammation subsides. The second is anterior rotation of the lens-iris diaphragm, which is reversed with cycloplegics. The pressure is treated in the acute setting with aqueous suppressants and oral carbonic anhydrase inhibitors. Pilocarpine is contraindicated because it will cause anterior rotation of the lens-iris diaphragm.","pyqMatches":[{"year":"2015","no":1070,"q":"Pilocarpine is used in all of the following except: September 2006","o":["Primary, Open Angle Glaucoma","Malignant Glaucoma","Acute Angle Closure Glaucoma","Chronic Synechial Angle Closure Glaucoma"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4617, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 62, '{"id":4617,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":62,"q":"Most common etiolopathogenetic cause of glaucoma is: March 2012","o":["Raised pressure in episcleritic veins","Decreased outflow","Increased formation of aqueous humour","Increased scleral outflow"],"a":1,"e":"Ans: B i.e. Decreased outflow A sustained increase in intraocular pressure may be due to increased formation of the aqueous humour, difficulty in its exit, or a raised pressure in the episcleral veins of these, the first & last rarely occur, and it follows that raised intraocular pressure is essentially due to an increased resistance to the circulation of the aqueous at the pupil and/ or its drainage through the angle of the anterior chamber.","pyqMatches":[{"year":"2015","no":1033,"q":"Most common etiolopathogenetic cause of glaucoma is: March 2012","o":["Raised pressure in episcleritic veins","Decreased outflow","Increased formation of aqueous humour","Increased scleral outflow"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4618, 'Ophthalmology', 'Refraction & Optics', 'Easy', 'Ophthalmology', 63, '{"id":4618,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Easy","source":"Ophthalmology","sourceNo":63,"q":"Posterior staphyloma is seen in: September 2005","o":["Myopia","Hypermetropia","Astigmatism","Presbyopia"],"a":0,"e":"Ans. A: Myopia Staphyloma is the term given to an eye whose sclero-uveal coats are stretched (also known as ectasia). This most commonly occurs posteriorly, athough anterior staphyloma also is recognised. Posterior staphyloma Progressive myopia (or mega myope) most common cause. Glaucoma Scleritis Necrotizing infection Surgery/trauma Radiotherapy Posterior staphyloma affects the posterior pole of the eye and is lined by the choroid. The ectatic portion is not visible externally but can be detected by fundoscopy and B-scan USG. Anterior staphyloma The most common cause for anterior staphyloma is sloughing corneal ulcer winch perforates and heals with the formation of a pseudocornea by the organization of exudates and laying down of fibrous tissue. Differential diagnoses Buphthalmos (congenital glaucoma) Axial myopia Macrophthalmos: seen in neurofibromatosis typel (NF1) Coloboma","pyqMatches":[{"year":"2015","no":1013,"q":"Posterior staphyloma is seen in: September 2005","o":["Myopia","Hypermetropia","Astigmatism","Presbyopia"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4619, 'Ophthalmology', 'Miscellaneous', 'Moderate', 'Ophthalmology', 64, '{"id":4619,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Ophthalmology","sourceNo":64,"q":"All of the following are true for sympathetic ophthalmitis except:","o":["Affects the injured eye","Mostly results from a penetrating wound","Autoimmune etiology","Dalen Fuch''s nodules may be seen"],"a":0,"e":"Ans. A: Affects the injured eye Sympathetic ophthalmitis is a condition in which serious inflammation attacks the sound eye after injury to the other eye.","pyqMatches":[{"year":"2015","no":1019,"q":"All of the following are true for sympathetic ophthalmitis except:","o":["Affects the injured eye","Mostly results from a penetrating wound","Autoimmune etiology","Dalen Fuch''s nodules may be seen"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4620, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 65, '{"id":4620,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":65,"q":"Snowflake cataract is associated with: September 2008","o":["Hypertension","Adult diabetes","Trauma","Juvenile diabetes"],"a":3,"e":"Ans. D: Juvenile diabetes Snowflake Cataracts: This type of cataract represents dots of various sizes (and sometimes various colours) distributed throughout the cortex surrounding the nucleus for 360°. This is the most common cataract seen in Down Syndrome (extra copy of chromosome 21 also called trisomy 21) and juvenile diabetes mellitus. These usually have very little effect on vision. Adult diabetic cataract shows cortical and/or nuclear and/or subcapsular (same as age related)","pyqMatches":[{"year":"2015","no":1029,"q":"Snowflake cataract is associated with: September 2008","o":["Hypertension","Adult diabetes","Trauma","Juvenile diabetes"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4621, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 66, '{"id":4621,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":66,"q":"Diabetic cataract is due to accumulation of: March 2009","o":["Fructose","Galactose","Glucose","Sorbitol"],"a":3,"e":"Ans. D) Sorbitol The enzyme aldose reductase (AR) catalyzes the reduction of glucose to sorbitol through the polyol pathway, a process linked to the development of diabetic cataract.","pyqMatches":[{"year":"2014","no":1200,"q":"Diabetic cataract is due to accumulation of: March 2009","o":["Fructose","Galactose","Glucose","Sorbitol"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4622, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 67, '{"id":4622,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":67,"q":"Scleritis is most commonly associated with: March 2005","o":["Diabetes","Osteoarthritis","Rheumatoid arthritis","Hypertension"],"a":2,"e":"Ans. C: Rheumatoid arthritis Scleritis is a severe, destructive, chronic, painful, and potentially blinding inflammatory disease of the Conjunctiva, Sclera and Episclera tissues. Symptoms includes redness and severe eye pain, which may radiate to adjacent areas, the forehead, cheek, or behind the eye. This is usually associated with light sensitivity, teary, and in some cases, reduced or poor vision. The affected eye often has a bluish hue or becomes an intense purple. There are several different sub-types of Scleritis Nodular Scleritis is characterized by a focal area of inflammation, immovable, and tender, inflamed nodules on the eye. Diffuse Scleritis Diffuse Anterior Scleritis is the most common type, and is characterized by widespread inflammation of the Anterior portion of the Sclera, the white of the eye. The Diffuse type of Scleritis is, fortunately, the most benign form of Scleritis and the most responsive to therapy. Necrotizing Scleritis is likely the worst form of the disease, sometimes leading to loss of the eye from multiple complications, severe pain, or occasionally perforation of the globe. It is often associated with severe systemic disease and involvement of multiple organs. An associated type of vascular inflammation, called Vasculitis, may threaten the lives of those patients afflicted. Pain with this condition is usually extreme, and damage to the Sclera is often marked. Necrotizing scleritis also known as Scleromalacia perforans is characterized by severe thinning of the Sclera of the Eye, allowing for local outpouchings of the underlying dark Uveal tissue. There are large abnormal blood vessels crossing areas of Scleral loss. The condition occurs in an otherwise white and \"quiet\" Eye, without pain. This type of Scleritis is associated with severe Rheumatoid Arthritis, occasionally seen in Wegener''s Granulomatosis and Relapsing Polychondritis. Posterior Scleritis is quite rare, but usually presents with poor or double vision, severe pain, proptosis (forward displacement of the eye), Uveitis (inflammation inside the Uvea Tract), and limitation of eye movement. An exudative Retinal detachment (fluid under the Retina) may cause severe visual loss, Angle-Closure Glaucoma from Choroidal effusion. About 50% of Scleritis patients are associated with systemic autoimmune disorders including rheumatoid arthritis, gout, wegener granulomatosis, Relapsing Polychondritis, Systemic Lupus Erythematosus, Polyarteritis Nodosa, Ankylosing Spondylitis, with infections, or chemical or physical injuries. It occurs most often in people between the ages of 30 and 60 (it is rare in children). Scleritis may be the initial or only presenting clinical manifestation of these potentially lethal disorders.","pyqMatches":[{"year":"2015","no":1015,"q":"Scleritis is most commonly associated with: March 2005","o":["Diabetes","Osteoarthritis","Rheumatoid arthritis","Hypertension"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4623, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 68, '{"id":4623,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":68,"q":"Laser used to manage after cataract: March 2005, September 2009","o":["Excimer laser","Argon green laser","Diode laser","Nd:YAG laser"],"a":3,"e":"Ans. D: Nd:YAG laser The Nd:YAG laser is a solid state laser that uses a neodymium- doped yttrium-aluminum-garnet crystal as the lasing medium. It is optically pumped with a lamp or diode and most commonly emits infrared light at 1064nm. It can be used in either a pulsed or continuous mode. Pulsed YAG lasers are typically Q-switched to achieve high-intensity pulses, which can be frequency doubled to emit light at 532nm. There are numerous ophthalmic applications for Nd:YAG lasers. They are most commonly used to treat posterior capsular opacification after cataract surgery To create a peripheral iridotomy in patients with narrow angles or angle-closure glaucoma. YAG lasers can also be used to cut the anterior capsule for capsular block syndrome and capsular phimosis To cut vitreous strands in the anterior chamber. In malignant glaucoma, disruption of the anterior hyaloid face is performed with the YAG laser In refractory glaucomas, these lasers can be used for cyclophotoablation of the ciliary body. They have also been helpful for draining premacular subhyaloid hemorrhages in patients with Valsalva retinopathy. Panretinal photocoagulation can be performed with frequency- doubled Nd:YAG lasers. Other applications include the treatment of recurrent corneal erosions and vitreous floaters. Excimer (Argon fluoride) laser is used in photorefractive keratectomy (PRK), phototherapeutic keratectomy (PTK), LASIK, LASEK Argon green laser is used in trabeculoplasty, iridoplasty, pupillomydriasis and retinal photocoagulation Diode laser is used in retinal photocoagulation","pyqMatches":[{"year":"2014","no":1196,"q":"Laser used to manage after cataract: March 2005, September 2009","o":["Excimer laser","Argon green laser","Diode laser","Nd:YAG laser"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4624, 'Ophthalmology', 'Refraction & Optics', 'Moderate', 'Ophthalmology', 69, '{"id":4624,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Moderate","source":"Ophthalmology","sourceNo":69,"q":"Which of the following is not a cause of hypermetropia: September 2009","o":["Short axial length of the eyeball","Flat cornea","Increased refractive index of the cortex of lens","Anterior dislocation of the lens"],"a":3,"e":"Ans. D: Anterior dislocation of the lens Factors responsible for hypermetropia: Short axial length of the eyeball Curvature hypermetropia commonly occurs as a factor in astigmatism (corneal plana) Index hypermetropia accounts for the hypermetropia of old age due to increased refractive index of the cortex of the lens relative to the nucleus so that overall refractive power of the lens decreases. It may be associated with diabetes, tumors, microphthalmia (a growth dysfunction during fetus development) and fovea hypoplasia, a condition that affects the blood vessels in the retina. While these conditions may result in hypermetropia, one of the most commonly cited causes of farsightedness is considered to be aging.","pyqMatches":[{"year":"2013","no":1123,"q":"Which of the following is not a cause of hypermetropia: September 2009","o":["Short axial length of the eyeball","Flat cornea","Increased refractive index of the cortex of lens","Anterior dislocation of the lens"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4625, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 70, '{"id":4625,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":70,"q":"Type of collagen present in cornea ?","o":["Type I","Type II","Type III","Type IV"],"a":0,"e":"Ans. is ''a'' i.e., Type I","pyqMatches":[{"year":"2014","no":245,"q":"Type of collagen present in cornea ?","o":["Type I","Type II","Type III","Type IV"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4626, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 71, '{"id":4626,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":71,"q":"Which of the following is present in cornea ?","o":["Hyaluronic acid","Chondroitin sulfate","Dermatan sulfate","Heparan sulfate"],"a":1,"e":"Ans. is ''b'' i.e., Chondroitin sulfate","pyqMatches":[{"year":"2014","no":246,"q":"Which of the following is present in cornea ?","o":["Hyaluronic acid","Chondroitin sulfate","Dermatan sulfate","Heparan sulfate"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4627, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 72, '{"id":4627,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":72,"q":"A person with defective blue color appreciation is called ?","o":["Deuteranomalous","Deuteranopia","Tritanopia","Tritanomalous"],"a":3,"e":"Ans. is `d'' i.e., Tritanomalous","pyqMatches":[{"year":"2014","no":1214,"q":"A person with defective blue color appreciation is called ?","o":["Deuteranomalous","Deuteranopia","Tritanopia","Tritanomalous"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4628, 'Ophthalmology', 'Retina & Vitreous', 'Hard', 'Ophthalmology', 73, '{"id":4628,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Hard","source":"Ophthalmology","sourceNo":73,"q":"What is the immediate management of vitreous hemorrhage in eye ?","o":["No treatment","Steroids","Antibiotics","Vitrectomy"],"a":0,"e":"Ans. is ''a'' i.e., No treatment Treatment of vitreous haemorrhage :","pyqMatches":[{"year":"2014","no":1182,"q":"What is the immediate management of vitreous hemorrhage in eye ?","o":["No treatment","Steroids","Antibiotics","Vitrectomy"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4629, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 74, '{"id":4629,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":74,"q":"Keratitis is caused by ?","o":["Bacteria","Atopy","Protozoa","All"],"a":3,"e":"Ans. is ''d'' i.e., All Causes of keratitis","pyqMatches":[{"year":"2014","no":1165,"q":"Keratitis is caused by ?","o":["Bacteria","Atopy","Protozoa","All"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4630, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 75, '{"id":4630,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":75,"q":"Subconjunctival cyst is seen in?","o":["Toxoplasmosis","Cysticercosis","Leishmaniasis","Chaga''s disease"],"a":1,"e":"Ans. is b i.e., Cysticercosis Parasitic cysts occurs in subconjunctival cysticercus, hydatid cyst and filarial cyst.","pyqMatches":[{"year":"2012","no":933,"q":"Subconjunctival cyst is seen in?","o":["Toxoplasmosis","Cysticercosis","Leishmaniasis","Chaga''s disease"],"a":1,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":1160,"q":"Subconjunctival cyst is seen in?","o":["Toxoplasmosis","Cysticercosis","Leishmaniasis","Chaga''s disease"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4631, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 76, '{"id":4631,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":76,"q":"Pars planitis is ?","o":["Anterior uveitis","Intermediate uveitis","Posterior uveitis","Pan uveitis"],"a":1,"e":"Ans. is b i.e., intermediate uveitis Uveitis Uveitis refers to the inflammation of uveal tissue. However, practically there is always some associated inflammation of the adjacent structures such as retina, vitreous, sclera and cornea. Due to close relationship between the anatomically distinct part of the uveal tract, the inflammatory process usually involve the uvea as a whole and are generally not limited to a single part. However, the uveitis is classified according to the part of uvea which is clinically more affected. For example, the term iritis is used when iris appears to be more affected. Anatomical classification of uveitis","pyqMatches":[{"year":"2014","no":1169,"q":"Pars planitis is ?","o":["Anterior uveitis","Intermediate uveitis","Posterior uveitis","Pan uveitis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4632, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 77, '{"id":4632,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":77,"q":"Brushfield spot in iris is seen in -","o":["Neurofibromatosis","Down syndrome","Tuberous sclerosis","Toxoplasmosis"],"a":1,"e":"Ans. is ''b'' i.e., Down syndrome Brushfield spots are white spots in the iris in patients with Down syndrome.","pyqMatches":[{"year":"2014","no":1215,"q":"Brushfield spot in iris is seen in","o":["Neurofibromatosis","Down syndrome","Tuberous sclerosis","Toxoplasmosis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4633, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Easy', 'Ophthalmology', 78, '{"id":4633,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Easy","source":"Ophthalmology","sourceNo":78,"q":"Most common orbital cyst in children-","o":["Neuroenteric cyst","Dermoid cyst","Lymphoma","Clobomatous cyst"],"a":1,"e":"Ans. is ''b'' i.e., Dermoid cyst Epidermal dermoid cyst (dermoid) is by for the most common orbital cystic lesion in children, accounting for over 40% of all orbital lesions of childhood and for 89% of all orbital cystic lesions of childhood that come to biopsy or surgical removal. Most important secondary cyst is a mucocele that can occur in children with cystic fibrosis.","pyqMatches":[{"year":"2014","no":1216,"q":"Most common orbital cyst in children","o":["Neuroenteric cyst","Dermoid cyst","Lymphoma","Clobomatous cyst"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4634, 'Ophthalmology', 'Ocular Motility & Strabismus', 'Easy', 'Ophthalmology', 79, '{"id":4634,"subject":"Ophthalmology","chapter":"Ocular Motility & Strabismus","difficulty":"Easy","source":"Ophthalmology","sourceNo":79,"q":"Disscociated vertical deviation seen in ?","o":["AV dissociation","Infantile esotropia","Congenital esotropia","Superior oblique palsy"],"a":2,"e":"Ans. is ''c'' i.e., Congenital esotropia The usual age of presentation of congenital (infantile) esotropia is between 2-4 months of age. Presentation at birth is very rare. Infantile esotropia has been classically described as large angle constant esotropia (not variable). The classicle triad of associated motor abnormalies in congenital esotropia is inferior oblique overaction, dissociated vertical deviation (DVD) and latent nystagmus. \"It seems, from a review of literature, that infants with esotropia have, on average, refractive errors similar to the normal age matched population\". — Handbook","pyqMatches":[{"year":"2014","no":1206,"q":"Disscociated vertical deviation seen in ?","o":["AV dissociation","Infantile esotropia","Congenital esotropia","Superior oblique palsy"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4635, 'Ophthalmology', 'Uvea', 'Easy', 'Ophthalmology', 80, '{"id":4635,"subject":"Ophthalmology","chapter":"Uvea","difficulty":"Easy","source":"Ophthalmology","sourceNo":80,"q":"Koeppe''s nodules are type of ?","o":["Granulomatous uveitis","Non granulomatous uveitis","Coroiditis","Pars planitis"],"a":0,"e":"Ans. is ''a'' i.e., Granulomatous uveitis Nodules on the iris surface. These are observed in granulomatous uveitis (Koeppe’s and Busacca’s nodules), melanoma, tuberculoma and gumma of the iris Iris nodules There are many types of nodules that develop on iris in granulomatous uveitis :- i. Keoppe nodule :- Seen at pupillary margin. i. Busacca''s nodule :- Seen on the peripheral part of anterior surface of iris. i. Tubercular nodules :- Scattered throughout the iris and ciliary body, mostly in stroma. They are more common at pupillary margin. v. Syphilitic nodules :- At pupillary margin. v. Sarcoid nodules :- At pupillary margin or in the stroma of the iris.","pyqMatches":[{"year":"2014","no":1168,"q":"Koeppe''s nodules are type of ?","o":["Granulomatous uveitis","Non granulomatous uveitis","Coroiditis","Pars planitis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4636, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 81, '{"id":4636,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":81,"q":"Cause of blindness in pterygium ?","o":["Astigmatism","Loss of visual axis","Cataract","Limitation of ocular movements"],"a":0,"e":"Ans. is ''a'' i.e., Astigmatism Ptervgium Pterygium is a non-cancerous (non-neoplastic) growth of conjunctiva, characterized by a wing-shaped fold of conjunctiva encroaching upon the cornea from either side within the interpalpebral fissure. Pterygium is always situated in the palpebral aperture. Pathologically Pterygium is a degenerative and hyperplastic condition of conjunctiva. The subconjunctival tissue undergoes elastotic degeneration and proliferates as vascularized granulation tissue under the epithelium, which ultimately encroaches the cornea. The corneal epithelium, Bowman''s layer and stroma are destroyed. Etiology & Clinical features Pterygium is more common in people with excess outdoor exposure to sunlight (UV rays), dry heat, high wind and abundance of dust. Therefore it is more common in those who work outdoors. Clinically it presents as a triangular fold of conjunctiva encroaching the cornea in the area of palpebral aperture, usually on the nasal side. Other findings are stocker''s line (deposition of iron) Ptergyium is an asymptomatic condition in the early stages, except for cosmetic intolerance. Visual disturbance or corneal astigmatism may occur. Visual disturbances are due to encroachment of pterygium on pupillary area or corneal astigmatism. Occasionally diplopia may occur due to limitation of ocular movements. Treatment Asymptomatic pterygium which is not progressive is best left alone. Surgical excision is the only satisfactory treatment and is indicated for : - (1) Cosmetic reasons, (2) Continued progression threatening to encroach onto the pupillary area (once the pterygium has encroached pupillary area, wait till it crosses on the other side), (3) Diplopia due to interference in ocular movement.","pyqMatches":[{"year":"2014","no":1161,"q":"Cause of blindness in pterygium ?","o":["Astigmatism","Loss of visual axis","Cataract","Limitation of ocular movements"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4637, 'Ophthalmology', 'Community Ophthalmology', 'Easy', 'Ophthalmology', 82, '{"id":4637,"subject":"Ophthalmology","chapter":"Community Ophthalmology","difficulty":"Easy","source":"Ophthalmology","sourceNo":82,"q":"Cause of blindness in trachoma ?","o":["Scarring","Pannus","Chronic dacrocystitis","Entropion"],"a":0,"e":"Ans. is ''a'' i.e., Scarring The later structural changes of trachoma are referred to as \"cicatricial trachoma\". These include scarring in the eyelid (tarsal conjunctiva) that leads to distortion of the eyelid with buckling of the lid (tarsus) so that eye lashes rub on the eye (trichiasis). Rubbing of eye lashes of scarred eye lids against the cornea leads to corneal opacities and scarring and then to blindness. Thus actual cause of blindness is corneal opacity and scarring, which may be secondary to eyelid scarring.","pyqMatches":[{"year":"2014","no":1163,"q":"Cause of blindness in trachoma ?","o":["Scarring","Pannus","Chronic dacrocystitis","Entropion"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4638, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 83, '{"id":4638,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":83,"q":"Fundus in retinitis Pigmentosa is ?","o":["White spots with red disc","Jet- black spots with pale-waxy disc","No pigmentation","Dilatation of arterioles"],"a":1,"e":"Ans. is ''b'' i.e., Jet- black spots with pale-waxy disc Examination findings in retinitis pigmentosa Ophthalmoscopic findings are characteristic and include :- i. Retinal pigmentary changes (Bone spicule intraneural retinal pigmentation) : - Retina studded with small, jet-black spots resembling bone corpuscles with a spidery outline. These pigmentary changes are typically perivascular and retinal veins (never arteries) have a sheath of pigment for part of their course. These changes affect equatorial region initially sparing the posterior pole and periphery. Later in the course of disease whole retina is involved. i. Attenuated and thread like retinal arterioles and veins. i. Pale and waxy optic disc (consecutive optic atrophy). v. Thinning and atrophy of retinal pigment epithelium (RPE) in mid and far peripheral retina with relative sparing of RPE at macula. Electroretinogram (ERG) and particularly the electro-oculogram (EOG) are markedly subnormal.","pyqMatches":[{"year":"2014","no":1180,"q":"Fundus in retinitis Pigmentosa is ?","o":["White spots with red disc","Jet- black spots with pale-waxy disc","No pigmentation","Dilatation of arterioles"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4639, 'Ophthalmology', 'Miscellaneous', 'Hard', 'Ophthalmology', 84, '{"id":4639,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Hard","source":"Ophthalmology","sourceNo":84,"q":"Retinoblastoma can occur bilaterally in how many percentage of the cases?","o":["10 - 15%","15 - 20%","20 - 25%","25 - 30%"],"a":3,"e":"Ans. is ''d'' i.e., 25- 30% RETINOBLASTOMA Retinoblastoma is the most common intraocular tumor in children. The tumor is confined to infancy and very young children (1-2 years). There is no sex predisposition. Retinoblastoma is unilateral in 70-75% of cases and bilateral in 25-30% of cases. Etiology Retinoblastoma gene (RB gene) is located on 14 band on the long arm of chromosome 13 (13q14). RB gene is a tumor supressor gene. Retinoblastoma develops when both the normal alleles of the RB genes are inactived or altered.lt is typical example of Knudson''s two hit hypothesis. In Hereditary retinoblastoma first genetic change (first hit) in RB gene is inherited from an affected parent, where as second mutation (second hit) occurs in postnatal life and both alleles are lost. In non- hereditary retinoblastoma, both mutations (first and second hits) occur postnataly.","pyqMatches":[{"year":"2014","no":1219,"q":"Retinoblastoma can occur bilaterally in how many percentage of the cases?","o":["10 - 15%","15 - 20%","20 - 25%","25 - 30%"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4640, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 85, '{"id":4640,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":85,"q":"Kayser flescher ring is seen in ?","o":["Siderosis","Chalcosis","Open angle glaucoma","Chemical injuries"],"a":1,"e":"Ans. is ''b'' i.e., Chalcosis Chalcosis It refers to the specific changes produced by the alloy of copper in the eye. Mechanism. Copper ions from the alloy are dissociated electrolytically and deposited under the membranous structures of the eye. Unlike iron ions these do not enter into a chemical combination with the proteins of the cells and thus produce no degenerative changes. Clinical manifestations i. Kayser-Fleischer ring : It is a golden brown ring which occurs due to deposition of copper under peripheral parts of the Descemet''s membrane of the cornea. i. Sunflower cataract : It is produced by deposition of copper under the posterior capsule of the lens. It is brilliant golden green in colour and arranged like the petals of a sun flower. i. Retina : It may show deposition of golden plaques at the posterior pole which reflect the light with a metallic sheen.","pyqMatches":[{"year":"2014","no":1228,"q":"Kayser flescher ring is seen in ?","o":["Siderosis","Chalcosis","Open angle glaucoma","Chemical injuries"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4641, 'Ophthalmology', 'Ocular Motility & Strabismus', 'Easy', 'Ophthalmology', 86, '{"id":4641,"subject":"Ophthalmology","chapter":"Ocular Motility & Strabismus","difficulty":"Easy","source":"Ophthalmology","sourceNo":86,"q":"Gaze fixation takes place at which age ?","o":["3 months","6 months","1 year","2 years"],"a":1,"e":"Ans. is ''b'' i.e., 6 months Gaze Fixation starts developing in the first month and is completed in 6 months. Macula is fully developed by 4 - 6 months. Fusional reflexes, stereopsis and accommodation is well developed by 4 - 6 months. Cornea attains normal adult diameter by 2 years of age. Lens grows throughout life.","pyqMatches":[{"year":"2014","no":1159,"q":"Gaze fixation takes place at which age ?","o":["3 months","6 months","1 year","2 years"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4642, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 87, '{"id":4642,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":87,"q":"Phacoemulsification incision is at ?","o":["Sclero-corneal junction","Cornea","Sclera","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Sclero-corneal junction In phacoemulsification very small 3 cmm incision is taken at the sclerocorneal junction. Phacoemulsification It is nothing else but an advancement in the method of doing ECCE. Here the nucleus is converted into pulp or emulsified using high frequency sound waves, and then sucked out of the eye through a small (3.2 mm) incision. A special foldable IOL is then inserted into the posterior chamber through the same incision. ECCE by phacoemulsification with foldable posterior chamber IOL is the procedure of choice for cataract. The steps in phacoemulsification include :(i) Corneoscleral incision, (ii) Continuous curvilinear capsulorrhexis, (iii) Hydrodissection and hydrodelineation (iv) Emulsification and aspiration of nucleus and then cortex, and (v) Foldable IOL implantation in posterior chamber. Recovery with phacoemulsification is fastest as incision is very small and no sutures are taken.","pyqMatches":[{"year":"2014","no":1197,"q":"Phacoemulsification incision is at ?","o":["Sclero-corneal junction","Cornea","Sclera","None of the above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4643, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Easy', 'Ophthalmology', 88, '{"id":4643,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Easy","source":"Ophthalmology","sourceNo":88,"q":"Gland of Moll opens in/on the ?","o":["Skin","Hair follicle","Tarsal plate","Ducts of Meibomian glands"],"a":1,"e":"Ans. is ''b'' i.e., Hair follicle GLANDS OF EYELIDS : i. Meibomian glands : These are also known as tarsal glands and are present in the stroma of tarsal plate arranged vertically. They are modified sebaceous glands. Their ducts open at the lid margin. Their secretion constitutes the oily layer of the tear film. i. Glands of Zeis : These are also sebaceous glands, which open into the follicles of eyelashes. i. Glands of Moll : These are modified sweat glands situated near the hair follicle. They open into the hair follicles or into the ducts of Zeis glands. They do not open directly onto the skin surface or elsewhere. v. Accessory lacrimal glands of Wolfring : These are present near the upper border of the tarsal plate.","pyqMatches":[{"year":"2014","no":1177,"q":"Gland of Moll opens in/on the ?","o":["Skin","Hair follicle","Tarsal plate","Ducts of Meibomian glands"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4644, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 89, '{"id":4644,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":89,"q":"Cherry red spot is seen in ?","o":["Niemann - Pick''s disease","Tay Sach''s disease","Central retinal artery occlusion","All of the above"],"a":3,"e":"Ans. is ''d i.e., All of the above Causes of cherry red spot GM2 gangliosidoses (Tay sachs & sandhoff) Hurler''s syndrome GM1 gangliosidoses Cryoglobulinemia Niemann - Pick''s disease Laber''s congenital amaurosis Gaucher''s disease Sialidosis (galactosialidosis) Metachromatic leukodystrophy Mucopolysacharidosis VII Central retinal artery occlusion (CRAO) Multiple sulfatase deficiency Trauma (Berlin''s edema / commotio retinae) Poisoning :- Carbon mono-oxide, methanol Quinine and Dapsone Shprintzen-Goldberg syndrome Farber''s disease Hallervorden Spatz disease Goldberg''s disease Rarely in krabbe''s disease","pyqMatches":[{"year":"2014","no":1183,"q":"Cherry red spot is seen in ?","o":["Niemann - Pick''s disease","Tay Sach''s disease","Central retinal artery occlusion","All of the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4645, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 90, '{"id":4645,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":90,"q":"Most common malignant intraorbital tumor in adult is ?","o":["Lymphoma","Rhabdomyosarcoma","Dermoid cyst","Sarcoma"],"a":0,"e":"Ans. is ''a'' i.e., Lymphoma An orbital tumor is any tumor that occurs within the orbit of the eye. The orbit is a bony housing in the skull that provides protection to the entire eyeball except the frontal surface. It is lined by the orbital bones and contains the eyeball, its muscles, blood vessels, nerves and fat. An intraocular tumor is the tumor which occurs within the eyeball. Most common intraocular tumor in adults is metastasis. Metastasis is particularly common from carcinoma of breast and lung. Most common primary intraocular tumor in adults is uveal melanoma. Most of the uveal malignant melanoma arise in choroid. Most common primary intraocular tumor is children is retinoblastoma. Most common orbital tumors in adults are benign vascular tumors → Cavernous hamangioma. Most common malignant orbital tumor in adult → lymphoma Most common orbital tumors in children are benign tumors → Dermoid cyst > capillary hemangioma Most common malignant orbital tumor in children → rhabdomyosarcoma. Overall most common primary malignant tumor of eye is malignant melanoma followed by retinoblastoma Most common malignant eyelid tumor → Basal cell carcinoma. Most common epithelial tumor of lacrimal gland Pleomorphic adenoma (benign mixed tumor) Overall most common tumor of lacrimal gland → Lymphoid tumour and inflammatory pseudo - tumors Most common malignant tumor of conjunctiva & cornea → Squamous cell carcinoma.","pyqMatches":[{"year":"2014","no":1217,"q":"Most common malignant intraorbital tumor in adult is ?","o":["Lymphoma","Rhabdomyosarcoma","Dermoid cyst","Sarcoma"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4646, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 91, '{"id":4646,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":91,"q":"Which antiglaucoma drug decreases aqueous formation ?","o":["Prostaglandins","Beta - blockers","Mannitol","Pilocarpine"],"a":1,"e":"Ans. is ''b'' i.e., Beta - blockers","pyqMatches":[{"year":"2014","no":1190,"q":"Which antiglaucoma drug decreases aqueous formation ?","o":["Prostaglandins","Beta - blockers","Mannitol","Pilocarpine"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4647, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 92, '{"id":4647,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":92,"q":"Selective alpha 2 agoinst used in glaucoma ?","o":["Tirriolol","Epinephrine","Dipivefrine","Brimonidine"],"a":3,"e":"Ans. is ''d'' i.e., Brimonidine","pyqMatches":[{"year":"2014","no":1191,"q":"Selective alpha 2 agoinst used in glaucoma ?","o":["Tirriolol","Epinephrine","Dipivefrine","Brimonidine"],"a":3,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":1038,"q":"Selective alpha 2 agoinst used in glaucoma ?","o":["Tirriolol","Epinephrine","Dipivefrine","Brimonidine"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4648, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 93, '{"id":4648,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":93,"q":"Bilateral inferior dislocation of lens is seen in ?","o":["Marfans syndrome","Homocystinuria","Weil Marchesani syndrome","Trauma"],"a":1,"e":"Ans. is `b'' i.e., Homocystinuria Ectopia lentis Ectopia lentis is defined as displacement or malposition of the crystalline lens of the eye. The lens is considered dislocated (luxated) when it lies completely outside the lens patellar fossa. The lens is described as subluxated when it is partially displaced but contained within the lens space.","pyqMatches":[{"year":"2014","no":1198,"q":"Bilateral inferior dislocation of lens is seen in ?","o":["Marfans syndrome","Homocystinuria","Weil Marchesani syndrome","Trauma"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4649, 'Ophthalmology', 'Glaucoma', 'Moderate', 'Ophthalmology', 94, '{"id":4649,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Moderate","source":"Ophthalmology","sourceNo":94,"q":"All are true about Bullous keratopathy except ?","o":["Seen in Macular dystrophy","Treatment is lamellar kertoplasty","Lenses can be prescribed for such patients","Seen in Fuch''s dystrophy"],"a":0,"e":"Ans. is ''a'' i.e., Seen in Macular dystrophy Fuch''s epithelial - endothelial dystrophy Fuch''s dystrophy-slowly progressive bilateral condition affecting females more than males. Primary open angle glaucoma is associated with this condition. Stages and clinical features i) Stage of cornea guttata Hassal - Henle type of excrescences in the central part of cornea. A gradual increase of central guttae with peripheral spread and confluence gives rise to the so called ''beaten - metal'' appearance. This stage is asyptomatic. ii) Oedematous stage or Stage of endothelial decompensation Early stromal edema and epithelial dystrophy Patients complain of blurring of vision. iii) Stage of Bullous keratopathy Follows long standing stromal edema Marked epithelial edema with formation of bullae, which when rupture cause pain, discomfort and irritation with associated decreased visual acuity. iv) Stage of scarring Cornea becomes opaque and vascularized. May be complicated by secondary infection or glaucoma. Treatment i. Edematous stage : 5% Sodium chloride (Hypertonic saline) i. Bullous keratopathy: Bandage soft contact lenses. i. Penetrating kertaoplasty : treatment of choice.","pyqMatches":[{"year":"2014","no":1178,"q":"All are true about Bullous keratopathy except ?","o":["Seen in Macular dystrophy","Treatment is lamellar kertoplasty","Lenses can be prescribed for such patients","Seen in Fuch''s dystrophy"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4650, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 95, '{"id":4650,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":95,"q":"Most common primary intraocular neoplasm in a child is ?","o":["Metastasis","Retinoblastoma","Basal cell carcinoma","Squamous cell carcinoma"],"a":1,"e":"Ans. is ''b'' i.e., Retinoblastoma","pyqMatches":[{"year":"2014","no":1218,"q":"Most common primary intraocular neoplasm in a child is ?","o":["Metastasis","Retinoblastoma","Basal cell carcinoma","Squamous cell carcinoma"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4651, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Moderate', 'Ophthalmology', 96, '{"id":4651,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Moderate","source":"Ophthalmology","sourceNo":96,"q":"Following are the side effects of apraclonidine except ?","o":["Lid dermatitis","Follicular conjunctivitis","Eye lid retraction","Watering of mouth"],"a":3,"e":"Ans. is ''d'' i.e., Watering of mouth Apraclonidine Topical application lowers the intra ocular pressure by 25 %. It decreases aqueous production by primary alphal and subsidiary alpha 2 action in ciliary body. Itching, lid dermatitis, follicular conjunctivitis, mydriasis, eyelid retraction, dryness of mouth and nose are common side effects. Its use is restricted to short term control of spikes of intraocular tension after laser trabeculolasty or iridotomy.","pyqMatches":[{"year":"2014","no":1193,"q":"Following are the side effects of apraclonidine except ?","o":["Lid dermatitis","Follicular conjunctivitis","Eye lid retraction","Watering of mouth"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4652, 'Ophthalmology', 'Refraction & Optics', 'Easy', 'Ophthalmology', 97, '{"id":4652,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Easy","source":"Ophthalmology","sourceNo":97,"q":"Treatment of presbyopia is by use of which lens?","o":["Convex","Concave","Biconcave","Concavoconvex"],"a":0,"e":"Ans. is ''a'' i.e., Convex Presbvopia Presbyopia is a vision condition in which the crystalline lens of eye loses its flexibility, which make it difficult to focus on the objects closer to the eye. Presbyopia is not an error of refraction but a condition of physiological insufficiency of accommodation leading to a progressive fall in near vision. Presbyopia is an age related problem, therefore also called eye sight of old age. Symptoms are usually seen after 40 years of age. Presbyopia is not a disease, rather a natural part of the aging process of the eye. The treatment of presbyopia is the prescription of appropriate convex glasses for near work.","pyqMatches":[{"year":"2014","no":1176,"q":"Treatment of presbyopia is by use of which lens?","o":["Convex","Concave","Biconcave","Concavoconvex"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4653, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 98, '{"id":4653,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":98,"q":"Steroid is contraindicated in ?","o":["Herpetic keratitis","Atopic dermatitis","Fungal corneal ulcer","Exposure keratitis"],"a":2,"e":"Ans. is ''c'' i.e., Fungal corneal ulcer Topical corticosteroids enhance fungal replication and corneal invasion and therefore, contraindicated in a fungal corneal ulcer. Now, option ''a'' requires specific mention here :- Topical corticosteroids are contraindicated in herpetic keratitis. But not in all forms of herpetic keratitis :- i. Epithelial herpetic keratitis (Dendritic ulcer, geographic ulcer) Topicla corticosteroids are contraindicated. i. Stromal keratitis (Disciform & Diffuse necrotic) Topical corticosteroids along with topical antiviral drugs are used as the first line of treatment. So, my opinion for this type of question is that :- i. If herpetic keratitis has given as the option, then look at other options. If any of the other options is a clear cut contraindication for corticosteroid (e.g. fungal corneal ulcer in this question), consider that option as your answer. If no ther option is a contraindication for topical corticosteroid, considere herpetic keratitis as the answer. i. If examiner has specifically mentioned dendritic ulcer as an option, consider it as the answer.","pyqMatches":[{"year":"2014","no":1231,"q":"Steroid is contraindicated in ?","o":["Herpetic keratitis","Atopic dermatitis","Fungal corneal ulcer","Exposure keratitis"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4654, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 99, '{"id":4654,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":99,"q":"Vitreous hemorrhage produces ?","o":["Sudden painless loss of vision","Sudden painful loss of vision","Gradual painless loss of vision","Gradual painful loss of vision"],"a":0,"e":"Ans. is ''a'' i.e., Sudden painless loss of vision","pyqMatches":[{"year":"2014","no":1181,"q":"Vitreous hemorrhage produces ?","o":["Sudden painless loss of vision","Sudden painful loss of vision","Gradual painless loss of vision","Gradual painful loss of vision"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4655, 'Ophthalmology', 'Refraction & Optics', 'Easy', 'Ophthalmology', 100, '{"id":4655,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Easy","source":"Ophthalmology","sourceNo":100,"q":"Tubular vision seen in -","o":["Myopia","Hypermetropia","Presbyopia","Optic neuritis"],"a":0,"e":"Ans. is ''a'' i.e., Myopia Causes of Tubular vision Retinitis pigmentosa High Myopia Primary open angle glaucoma CRAO with sparing of cilioretinal artery","pyqMatches":[{"year":"2014","no":1232,"q":"Tubular vision seen in","o":["Myopia","Hypermetropia","Presbyopia","Optic neuritis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4656, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 101, '{"id":4656,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":101,"q":"Treatment of dacryocystitis in three months old child ?","o":["Daily probing","Weekly probing","Massaging","Syringing"],"a":2,"e":"Ans. is ''c'' i.e., Massaging Spontaneous recanalization of obstructed nosolacrimal duct occurs during first 6-8 weeks and sometimes after 6-12 months in 90% of infants. Therefore upto 9-12 months only massage and antibiotic drops are indicated. After the age of 12 months high pressure syringing is indicated.","pyqMatches":[{"year":"2014","no":1224,"q":"Treatment of dacryocystitis in three months old child ?","o":["Daily probing","Weekly probing","Massaging","Syringing"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4657, 'Ophthalmology', 'Community Ophthalmology', 'Easy', 'Ophthalmology', 102, '{"id":4657,"subject":"Ophthalmology","chapter":"Community Ophthalmology","difficulty":"Easy","source":"Ophthalmology","sourceNo":102,"q":"Methanol attacks ?","o":["Cones","Rods","Ganglion cells of retina","Germinal cell layer"],"a":2,"e":"Ans. is ''c'' i.e., Ganglion cells of retina Methyl alcohol is metabolised very slowly and thus stays for a longer period in the body. It is oxidised into formic acid and formaldehyde in the tissues. These toxic agents cause oedema followed by degeneration of the ganglion cells of the retina, resulting in complete blindness due to optic atrophy.","pyqMatches":[{"year":"2014","no":1186,"q":"Methanol attacks ?","o":["Cones","Rods","Ganglion cells of retina","Germinal cell layer"],"a":2,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":664,"q":"Methanol attacks ?","o":["Cones","Rods","Ganglion cells of retina","Germinal cell layer"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4658, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 103, '{"id":4658,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":103,"q":"Retinal tears seen most commonly seen in ?","o":["Primary retinal detachment","Secondary retinal detachment","Tractional retinal detachment","Exudative retinal detachment"],"a":0,"e":"Ans. is ''a'' i.e., Primary retinal detachment Retinal detachment is a disorder of eye in which retina peels away from its underlying layer of support tissue. Usually there is separation between the neuroepithelium (neurosensory epithelium) and the pigmented layer. The retinal separation is divided into:","pyqMatches":[{"year":"2014","no":1185,"q":"Retinal tears seen most commonly seen in ?","o":["Primary retinal detachment","Secondary retinal detachment","Tractional retinal detachment","Exudative retinal detachment"],"a":0,"source":"NEET_2014_Paper.pdf"},{"year":"2016","no":1003,"q":"Retinal tears seen most commonly seen in ?","o":["Primary retinal detachment","Secondary retinal detachment","Tractional retinal detachment","Exudative retinal detachment"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2014","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4659, 'Ophthalmology', 'Retina & Vitreous', 'Moderate', 'Ophthalmology', 104, '{"id":4659,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Moderate","source":"Ophthalmology","sourceNo":104,"q":"Following are the clinical features of Leber optic neuropathy except","o":["Seen in the 2nd or 3rd decade of life","It is a example of gradual painless visual loss","Males can transmit the disease","No leak of dye is observed in fluorescein angiography"],"a":2,"e":"Ans. is ''c'' i.e., Males can transmit the disease Leber''s Hereditary optic neuropathv Leber''s hereditary optic neuropathy is characterized by sequential subacute optic neuropathy in males aged 11-30 years. The underlying genetic abnormality is a point mutation in mitochondria! DNA. Since mitochondrial DNA is exclusively derived from mother, males do not transmit the disease and the disease is transmitted by carrier females. It is characterizeed by bilateral, painless, subacute visual failure that develops during young adult life. Males are four to five times more likely than females to be affected. Affected individuals are usually entirely asymptomatic until they develop blurring affecting the central visual field of one eye; Similar symptoms appear in the other eye an average of two to three months late. In about 25% of cases, visual loss is bilateral at onset. On examination, patients generally have bilateral impairments of visual acuity. There is centrocecal scotoma that begins nasal to the blind spot and extends to involve fixation of both sides of the vertical meridian. Pupillary reactions are often normal. Ophthalmoscopic examination shows fundus abnormalities in acute phase like swelling of the disc, peripapillary retinal telangiectasia, but characteristically there is no leak from the optic disc during fluorescein angiography. Later in atrophic phase, disc becomes atrophic and pale.","pyqMatches":[{"year":"2014","no":1209,"q":"Following are the clinical features of Leber optic neuropathy except","o":["Seen in the 2nd or 3rd decade of life","It is a example of gradual painless visual loss","Males can transmit the disease","No leak of dye is observed in fluorescein angiography"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4660, 'Ophthalmology', 'Uvea', 'Easy', 'Ophthalmology', 105, '{"id":4660,"subject":"Ophthalmology","chapter":"Uvea","difficulty":"Easy","source":"Ophthalmology","sourceNo":105,"q":"Following is feature of Fusch''s hetero chromic iridocyclitis ?","o":["Heterochromia of iris","Keratic precipitates","Posterior subcapsular cataract","All the above"],"a":3,"e":"Ans. is ''d'' i.e., All the above Fuch''s heterochromic iridocyclitis (Fuch''s uveitis syndrome) It is a form of anterior and intermediate uveitis. The condition is usually unilateral and chronic in nature and is characterized by a chronic non-granulomatous uveitis and eventually results in iris heterochromia (a change in the colour of iris). The disease has following characteristic features : i) Heterochromia of iris ii) Diffuse stromal iris atrophy iii) Fine KPs at back of cornea iv) Faint aqueous flare v) Absence of posterior synechiae vi) A fairly common rubeosis iridis, sometimes associated with neovascularisation of the angle of anterior chamber. vii) Comparatively early development of complicated cataract and secondary glaucoma (usually open angle type). Glaucoma has been reported in 10-59% of cases. Treatment Fuch''s heterchromic uveitis responds variable to steroids and cycloplegics. The complications of long term use of these drugs may at times outweigh their potential benefits. Therefore, treatment with topical steroids is given to iritis which is sufficiently active to require the treatment, otherwise the patient is routinely followed without giving any treatment. Cataract responds well to most forms of intraocular surgeries, including the standard IOL implantation. Hyphemia may occur because of rubeosis iridis (neovascularization of iris). Glaucoma control may be somewhat more problematic, with surgical options indicated for later forms of disease","pyqMatches":[{"year":"2014","no":1173,"q":"Following is feature of Fusch''s hetero chromic iridocyclitis ?","o":["Heterochromia of iris","Keratic precipitates","Posterior subcapsular cataract","All the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4661, 'Ophthalmology', 'Ocular Motility & Strabismus', 'Easy', 'Ophthalmology', 106, '{"id":4661,"subject":"Ophthalmology","chapter":"Ocular Motility & Strabismus","difficulty":"Easy","source":"Ophthalmology","sourceNo":106,"q":"BSGT stands for ?","o":["Bagolini striated glasses test","Bagolini smooth glasses test","Bagolini shiny glasses test","Bagolini second glue test"],"a":0,"e":"Ans. is ''a'' i.e., Bagolini striated glasses test Bagolini striated glasses test, or BSGT, is a subjective clinical test to detect the presence or extent of binocular functions and is generally performed by an orthoptist. It is mainly used in strabismus clinics.","pyqMatches":[{"year":"2014","no":1147,"q":"BSGT stands for ?","o":["Bagolini striated glasses test","Bagolini smooth glasses test","Bagolini shiny glasses test","Bagolini second glue test"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4662, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 107, '{"id":4662,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":107,"q":"Melanocytes in conjunctiva are derived from ?","o":["Neural ectoderm","Surface ectoderm","Mesoderm","Neural crest"],"a":3,"e":"Ans. is ''d'' i.e., Neural crest","pyqMatches":[{"year":"2014","no":1148,"q":"Melanocytes in conjunctiva are derived from ?","o":["Neural ectoderm","Surface ectoderm","Mesoderm","Neural crest"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4663, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 108, '{"id":4663,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":108,"q":"Bitemporal hemianopia is characteristic of ?","o":["Glaucoma","Optic neuritis","Pituitary tumor","Retinal detachment"],"a":2,"e":"Ans. is ''c'' i.e., Pituitary tumor Characteristic visual field defect of central chiasmatic lesion is bitemporal hemianopia. Pituitary tumor causes central chiasmatic lesion. Bitemporal hemianopia results due to central (sagittal) lesion of the optic chiasma, common causes of which are tumors of the pituitary gland (most common), craniopharyngioma, suprasellar meningioma, glioma of third ventricle, chiasmal arachnoiditis, and third ventricular dilatation.","pyqMatches":[{"year":"2014","no":1211,"q":"Bitemporal hemianopia is characteristic of ?","o":["Glaucoma","Optic neuritis","Pituitary tumor","Retinal detachment"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4664, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 109, '{"id":4664,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":109,"q":"For congenital obstruction of nasolacrimal duct, probing is done at what age ?","o":["2 months","6 months","10 months","14 months"],"a":1,"e":"Ans. is ''b'' i.e., 6 months Probing of congenital nasolacrimal duct blockade with Bowman''s probe It should be performed, in case the condition is not cured by the age of 3-4 months. Some surgeons prefer to wait till the age of 6 months. It is usually performed under general anaesthesia. While performing probing, care must be taken not to injure the canaliculus.","pyqMatches":[{"year":"2014","no":1226,"q":"For congenital obstruction of nasolacrimal duct, probing is done at what age ?","o":["2 months","6 months","10 months","14 months"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4665, 'Ophthalmology', 'Ocular Motility & Strabismus', 'Easy', 'Ophthalmology', 110, '{"id":4665,"subject":"Ophthalmology","chapter":"Ocular Motility & Strabismus","difficulty":"Easy","source":"Ophthalmology","sourceNo":110,"q":"Right esotropia is evident with ?","o":["Left lateral rectus paralysis","Right lateral rectus paralysis","Left medial rectus paralysis","Right medial rectus paralysis"],"a":0,"e":"Ans. is ''a'' i.e., Left lateral rectus paralysis","pyqMatches":[{"year":"2014","no":1205,"q":"Right esotropia is evident with ?","o":["Left lateral rectus paralysis","Right lateral rectus paralysis","Left medial rectus paralysis","Right medial rectus paralysis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4666, 'Ophthalmology', 'Retina & Vitreous', 'Moderate', 'Ophthalmology', 111, '{"id":4666,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Moderate","source":"Ophthalmology","sourceNo":111,"q":"Diabetic ischemic maculopathy is characterized by all except ?","o":["It occurs due to microvascular blockage","Mild visual loss","Areas of non perfusion are evident on fluorescein angiography","Microaneurysms and hemorrhages are seen"],"a":1,"e":"Ans. is `b'' i.e., Mild visual loss Ischaemic diabetic maculopathy It occurs due to microvascular blockage. Clinically it is characterised by marked visual loss with microaneurysms, haemorrhages, mild or no macular oedema and a few hard exudates. Fluorescein angiography shows areas of non-perfusion which in early cases are in the form of enlargement of foveal avascular zone (FAZ), later on areas of capillary dropouts are seen and in advanced cases precapillary arterioles are blocked.","pyqMatches":[{"year":"2014","no":1187,"q":"Diabetic ischemic maculopathy is characterized by all except ?","o":["It occurs due to microvascular blockage","Mild visual loss","Areas of non perfusion are evident on fluorescein angiography","Microaneurysms and hemorrhages are seen"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4667, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 112, '{"id":4667,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":112,"q":"Treatment for mild ptosis is ?","o":["Fasanella servat operation","Levator resection","Frontalis sling operation","Everbusch''s operation"],"a":0,"e":"Ans. is ''a'' i.e., Fasanella servat operation Fasanella-Servat operation. It is performed in cases having mild ptosis (1-5-2mm) and good levator function. In it, upper lid is everted and the upper tarsal border along with its attached Muller''s muscle and conjunctiva are resected.","pyqMatches":[{"year":"2014","no":1227,"q":"Treatment for mild ptosis is ?","o":["Fasanella servat operation","Levator resection","Frontalis sling operation","Everbusch''s operation"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4668, 'Ophthalmology', 'Lens & Cataract', 'Hard', 'Ophthalmology', 113, '{"id":4668,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Hard","source":"Ophthalmology","sourceNo":113,"q":"Cataract is cases of diabetes mellitus is due to accumulation of ?","o":["Glycated crytallins","Calcified crystallins","Glycated fibrillins","Calcified fibrillins"],"a":0,"e":"Ans. is ''a'' i.e., Glycated crytallins Diabetic cataract Senile cataract tends to develop at an earlier age and more rapidly than usual in diabetic subjects. The lenses of an adult diabetic are said to be in the same condition as a non-diabetic who is 15 years older. In diabetic adults, coin- pared to non-diabetics, cataracts are more prevalent, are dependent on the duration of diabetes and progress more rapidly. The mechanisms are believed to be glycation, carbamylation of crystallins and increased oxidative damage. True diabetic cataract is a rare condition occurring typi- cally in young people in whom the diabetes is so acute as to disturb grossly the water balance of the body. A large number of fluid vacuoles appear under the anterior -td posterior parts of the capsule, initially manifesting as myopia and then producing a diffuse opacity which at this stage is reversible. The lens then rapidly becomes cataractous, with dense, white subcapsular opacities in the anterior and posterior cortex resembling a snowstorm- ''snowflake'' cataract. Fine, needle-shaped polychromatic cortical opacities may also form. With appropriate treatment to control hyperglycaemia, the rapid progression to mature cataract may be arrested at this stage.","pyqMatches":[{"year":"2014","no":1201,"q":"Cataract is cases of diabetes mellitus is due to accumulation of ?","o":["Glycated crytallins","Calcified crystallins","Glycated fibrillins","Calcified fibrillins"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4669, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 114, '{"id":4669,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":114,"q":"Density of cells in adult corneal endothelium ?","o":["2000 cells/mm2","3000 cells/mm2","4000 cells/mm2","5000 cells/mm2"],"a":1,"e":"Ans. is ''b'' i.e., 3000 cells/mm2 The cell density of corneal endothelium is around 3000 cells/mm2 in young adults, which decreases with the advancing age.","pyqMatches":[{"year":"2014","no":1149,"q":"Density of cells in adult corneal endothelium ?","o":["2000 cells/mm2","3000 cells/mm2","4000 cells/mm2","5000 cells/mm2"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4670, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Easy', 'Ophthalmology', 115, '{"id":4670,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Easy","source":"Ophthalmology","sourceNo":115,"q":"Axial proptosis is produced by tumors lying in ?","o":["Retrobulbar space","Subperiosteal space","Tenon space","Peripheral space"],"a":0,"e":"Ans. is ''a'' i.e., Retrobulbar space SURGICAL SPACES IN THE ORBIT These are of importance as most orbital pathologies tend to remain in the space in which they are formed. Therefore, their knowledge helps the surgeon in choosing the most direct surgical approach. Each orbit is divisible into four surgical spaces.","pyqMatches":[{"year":"2014","no":1220,"q":"Axial proptosis is produced by tumors lying in ?","o":["Retrobulbar space","Subperiosteal space","Tenon space","Peripheral space"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4671, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 116, '{"id":4671,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":116,"q":"In xerophthalmia classification X 2 stage is ?","o":["Bitots spots","Corneal xerosis","Corneal ulceration","Corneal scar"],"a":1,"e":"Ans. is b i.e., Corneal xerosis WHO classification (1982) The new xerophthalmia classification (modification of original 1976 classification) is as follows :","pyqMatches":[{"year":"2014","no":1233,"q":"In xerophthalmia classification X 2 stage is ?","o":["Bitots spots","Corneal xerosis","Corneal ulceration","Corneal scar"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4672, 'Ophthalmology', 'Uvea', 'Moderate', 'Ophthalmology', 117, '{"id":4672,"subject":"Ophthalmology","chapter":"Uvea","difficulty":"Moderate","source":"Ophthalmology","sourceNo":117,"q":"All of the following has HLAB27 associated with uveitis except ?","o":["Ankylosing spondylitis","Reiters syndrome","Behcets syndrome","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., Behcets syndrome A few examples of HLA-associated diseases with uveitis are as follows : i) HLA-B27 : Acute anterior uveitis associated with ankylosing spondylitis and also in Reiter''s syndrome. ii) HLA-B5 : Uveitis in Behcet''s disease. iii) HLA-DR4 and DW15 : Vogt Koyanagi Harada''s disease.","pyqMatches":[{"year":"2014","no":1179,"q":"All of the following has HLAB27 associated with uveitis except ?","o":["Ankylosing spondylitis","Reiters syndrome","Behcets syndrome","None of the above"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4673, 'Ophthalmology', 'Optic Nerve & Neuro-ophthalmology', 'Easy', 'Ophthalmology', 118, '{"id":4673,"subject":"Ophthalmology","chapter":"Optic Nerve & Neuro-ophthalmology","difficulty":"Easy","source":"Ophthalmology","sourceNo":118,"q":"Marcus gunn jaw winking phenomenon due to relation between which cranial nerves","o":["VII + VIII","III + V","V + VII","III + VI"],"a":1,"e":"Ans. is ''b'' i.e., III + V Marcus Gunn phenomenon (a.k.a. Marcus Gunn Jaw-Winkingor Trigemino-oculomotor Synkineses) IT is an autosomal-dominant condition with incomplete penetrance, in which nursing infants will have rhythmic upward jerking of their upper eyelid. This condition is characterized as a synkinesis: when two or more muscles that are independently innervated have either simultaneous or coordinated movements.","pyqMatches":[{"year":"2014","no":1213,"q":"Marcus gunn jaw winking phenomenon due to relation between which cranial nerves","o":["VII + VIII","III + V","V + VII","III + VI"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4674, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 119, '{"id":4674,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":119,"q":"Increased intraocular tension can be diagnosed by ?","o":["Tonometer","Pachymeter","Placido''s disc","Keratometer"],"a":0,"e":"Ans. is ''a'' i.e., Tonometer The exact measurement of intraocular pressure is done by an instrument called tonometer. Indentation (Schiotz tonometer) and applanation (e.g., Goldmann''s tonometer) tonometers are frequently used.","pyqMatches":[{"year":"2014","no":1235,"q":"Increased intraocular tension can be diagnosed by ?","o":["Tonometer","Pachymeter","Placido''s disc","Keratometer"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4675, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 120, '{"id":4675,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":120,"q":"Wernicke''s hemianopic pupillary reponse is seen in lesions at ?","o":["Optic tract","Optic chiasma","Optic radiation","Lateral geniculate body"],"a":0,"e":"Ans. is ''a'' i.e., Optic tract","pyqMatches":[{"year":"2014","no":1212,"q":"Wernicke''s hemianopic pupillary reponse is seen in lesions at ?","o":["Optic tract","Optic chiasma","Optic radiation","Lateral geniculate body"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4676, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 121, '{"id":4676,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":121,"q":"`Ischemic necrosis'' in alkali burn is ?","o":["Stage I","Stage II","Stage III","Stage IV"],"a":0,"e":"Ans. is ''a'' i.e., Stage I Alkali burns are among the most severe chemical injuries to eye. Common alkalies responsible for burns are liquid ammonia (most harmful), lime, caustic potash or caustic soda. o Clinical features are divided into three stages. 1) Acute ischemic necrosis (Stage I) :- In this stage there are signs in conjunctiva (edema, congestion, necrosis, copious discharge), cornea (sloughing, edema and opacity) and iris (iridocyclitis). 2) Reparation (Stage II) :- Conjunctival and corneal epithelium regenerate, and there is corneal neovascularization. 3) Complications (Stage III) :- Symblepharon, recurrent corneal ulceration, complicated cataract, secondary glaucoma.","pyqMatches":[{"year":"2014","no":1229,"q":"`Ischemic necrosis'' in alkali burn is ?","o":["Stage I","Stage II","Stage III","Stage IV"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4677, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 122, '{"id":4677,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":122,"q":"Ganglionic cells are, neurons ?","o":["First order","Second order","Third order","None"],"a":1,"e":"Ans. is ''b'' i.e., Second order","pyqMatches":[{"year":"2014","no":1203,"q":"Ganglionic cells are, neurons ?","o":["First order","Second order","Third order","None"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4678, 'Ophthalmology', 'Refraction & Optics', 'Easy', 'Ophthalmology', 123, '{"id":4678,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Easy","source":"Ophthalmology","sourceNo":123,"q":"No movement of Red reflex in retinoscopy -","o":["No refractive error","Myopia of 3D","Myopia of ID","Hypermetropia"],"a":2,"e":"Ans. is ''c'' i.e., Myopia of ID Retinoscopy Retinoscopy, also called skiascopy or shadow test, is an objective method of finding out the error of refraction by the method of neutralization. Retinoscopy is based on the fact that when a light is reflected from a mirror into the eye, the direction in which the light will travel across the pupil will depend upon the refractive state of the eye. With the help of a retinoscope, light is thrown onto the patient''s eye and through a hole in the retinoscope''s mirror the examiner observes of red reflex in the pupillary area of the patient. Then the retinoscope is moved in horizontal the vertical meridia keeping a watch on red reflex, which also moves when the retinoscope is moved.","pyqMatches":[{"year":"2014","no":1150,"q":"No movement of Red reflex in retinoscopy","o":["No refractive error","Myopia of 3D","Myopia of ID","Hypermetropia"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4679, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 124, '{"id":4679,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":124,"q":"Maximum refractive index ?","o":["Cornea","Air","Lens","Vitreous"],"a":2,"e":"Ans. is ''c'' i.e., Lens","pyqMatches":[{"year":"2014","no":1151,"q":"Maximum refractive index ?","o":["Cornea","Air","Lens","Vitreous"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4680, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 125, '{"id":4680,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":125,"q":"Primary action of inferior oblique ?","o":["Abduction","Adduction","Extorsion","Elevation"],"a":2,"e":"Ans. is ''c'' i.e., Extorsion","pyqMatches":[{"year":"2014","no":1204,"q":"Primary action of inferior oblique ?","o":["Abduction","Adduction","Extorsion","Elevation"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4681, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 126, '{"id":4681,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":126,"q":"What is the most common problem following surgical treatment of pterygium?","o":["Recurrence","Corneal ulceration","Astigmatism","Scleral scarring"],"a":0,"e":"Ans. is ''a'' i.e., Recurrence Surgical excision of pterygium is its only satisfactory treatment and is indicated for ?","pyqMatches":[{"year":"2014","no":1162,"q":"What is the most common problem following surgical treatment of pterygium?","o":["Recurrence","Corneal ulceration","Astigmatism","Scleral scarring"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4682, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 127, '{"id":4682,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":127,"q":"Refsum''s syndrome is associated with ?","o":["Retinitis pigmentosa","Xerophthalmia","Chalcosis","Diabetes retinopathy"],"a":0,"e":"Ans. is ''a'' i.e., Retinitis pigmentosa Associations of retinitis pigmentosa Ocular associations : These include myopia, primary open angle glaucoma, microphthalmos, conical cornea and posterior subcapsular cataract. Systemic associations : These are in the form of following syndromes :- i) Laurence-Moon-Biedl syndrome : It is characterised by retinitis pigmentosa, obesity, hypogenitalism, polydactyly and mental deficiency. ii) Cockayne''s syndrome : It comprises retinitis pigmentosa, progressive infantile deafness, dwarfism, mental retardation, nystagmus and ataxia. iii) Refsum''s syndrome : It is characterized by retinitis pigmentosa, peripheral neuropathy and cerebellar ataxia. iv) Usher''s syndrome : It includes retinitis pigmentosa and labyrinthine deafness. v) Hallgren''s syndrome : It comprises retinitis pigmentosa, vestibulo- cerebellar ataxia, congenital deafness and mental deficiency.","pyqMatches":[{"year":"2014","no":1188,"q":"Refsum''s syndrome is associated with ?","o":["Retinitis pigmentosa","Xerophthalmia","Chalcosis","Diabetes retinopathy"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4683, 'Ophthalmology', 'Ocular Motility & Strabismus', 'Easy', 'Ophthalmology', 128, '{"id":4683,"subject":"Ophthalmology","chapter":"Ocular Motility & Strabismus","difficulty":"Easy","source":"Ophthalmology","sourceNo":128,"q":"Following is a feature of concomitant squint ?","o":["Constant amount of deviation in all directions of gaze","Associated limitation of ocular movements","Different amount of deviation in different directions of gaze","Develops in the patients at 15 - 20 years of age."],"a":0,"e":"Ans. is ''a'' i.e., Constant amount of deviation in all directions of gaze MANFEST SQUINT (HETEROTROPIA) In manifest squint the deviation of eye is present as such and cannot be compensated by fusion. Two main types of manifest squint are concomitant squint and paralytic squint. A) Concomitant squint In concomitant squint the eyes are not in alignment and the degree of malalignment remains constant in all the directions of gaze and there is no limitation of ocular movements. Concomitant squint may be of following types: 1) Esotropia (Convergent squint) :- It denotes inward deviation of eye. It can be unilateral or uniocular (the same eye always deviates inwards) or alternating (either of the eyes deviates inwards and the other eye takes up fixation, alternately). Concomitant esotropia is the most common type of squint in children. Following types of esotropia are there :- i) Congenital esotropia (infantile esotropia) True congenital (infantile) esotropia usually appears between the age of 2 and 4 months. However, rarely it may be present from birth. The inward turn of the eye is constant of large amount, i.e., deviation is > 35 prism diopters (17-5''). Binocular vision (both eyes fixing simultaneously) does not develop. There is alternate fixation in primary gaze, i.e, when the infant looks straight, he fixes the gaze with one eye at a time alternately. On lateral gaze there is cross fixation, i.e, use right eye to fix across the nose to view the objects to the left and vice versa. Amblyopia develops in 25- 40% of cases. Latent horizontal nystagmus (common) and many rotatory nystagmus may occur. Inferior oblique overaction may be present initially or develop later and dissociated vertical deviation develop in 80% by age of 3 years. It is more difficult to help this type of strabismus with nonsurgical methods, thus, surgery is the treatment of choice. Surgical procedure to make both medial recti weak by recession. Surgery should be done as early as possible to avoid development of amblyopia and for the development of proper binocular vision. The usually recommended time is between 6 month - 2 years of age (and preferably before 1 year of age).It is important to treat the amblyopia before performing surgery by patching of normal eye. ii) Accommodative esotropia Accommodative esotropia occurs due to overaction of convergence associated with accommodation reflex. Accommodative esotropia is the most common type of squint in children (Previously it was believed that congenital esotropia is the most common type squint in children. However now it is very much clear that accommodative esotropia is the most common one). It esotropia is noted around 2-3 years of age, it is most likely accommodative esotropia. On the bases of AC/A (accommodative convergence/accomodation) ratio, accommodative esotropia is divided into two types : (a) Refractive (Normal AC/A ratio); (b) Non - refractive (abnormal AC/A ratio). AC/A ratio gives the relationship between the amount of convergence that is goverened by a given amount of accommodation. a. Normal AC/A ratio accommodative esotropia :- This occurs in children with hypermetropia. Esotropia is a physiological response to excessive hypermetropia. Patients with high hypermetropia generate large amount of accommodation to see clearly at near fixation. This excessive accommodation may cause esotropia as accommodation is associated with convergence. AC/A ratio is normal. b. Large AC/A ratio accommodative esotropia :- Children have large amounts of focusing power and sometimes the increase of accommodation is accompanied by a disproportionately large increase of convergence. This occurs in patient with hypermetropia but may occur in myopia and without any refractive error. AC/A ratio is high. Usually, there are no symptoms except for cosmetic embarrassment to the patient. There is no diplopia as the image in the squinting eye is automatically suppressed, i.e., amblyopia develops in squinting eye. The main feature is the failure of binocular vision. 2) Exotropia (divergent squint) :- It is characterized by outward deviation of eye. This is very less common than esotropia. 3) Hypertropia (Vertical squint) :- It is characterized by vertical deviation of eye. It is also rare. B) Incomitant squint Incomitant squint is a squint in which the angle of deviation differs depending upon the direction of gaze i.e, amount of deviation varies in different directions of gaze. There are many type of incomitant squints (paralytic, restrictive, ''A'' & ''V'' pattern), however the most common type is Paralytic squint and the word incomitant squint is usually used for paralytic squint. Therefore, I will explain paralytic squint here Paralytic squint is the most common type of squint in adults. Paralytic squint is the strabismus resulting from complete or incomplete paralysis of one or more extraocular muscles. There are many causes like neurogenic (e.g. meningitis, cranial nerve palsy etc.), myogenic (myopathies), or neuromuscular junction lesions. o Symptoms of paralytic squint are :- i) Diplopia : It is the main symptom. It is most marked in the direction of action of paralysed muscle. For example in left rectus palsy, the maximum diplopia occurs when patient tries to see horizontally on left side and in left superior oblique palsy (causes Dextrodepression) diplopia is maximum when patient tries to look downward and right. It is worth noting here that in diplopia, if the images are separated horizontally it is probable that either a lateral or a medial recuts is affected; when the images are separated vertically or the image is tilted (torsion) it is likely that one or more of the vertical recti or the tilted (torsion) it is likely that one or more of the vertical recti or the obliques are affected. ii) Other symptoms : Confusion, nausea & vertigo, ocular deviation, loss of stereopsis. Signs of paralytic squint are :- i) Secondary deviation is more than primary deviation:- Primary deviation is the deviation in the affected eye and is away from the action of paralysed muscle. Secondary deviation is the deviation of normal eye seen under cover, when the patient is made to fix with the squinting eye. ii) Restriction of ocular movements iii) Compensatory head posture :- Patients with a paralytic squint move their head such that the eyes occupy a position in the orbit where the angle of squint is minimal and this can avoid confusion and diplopia. Head is turned towards the action of paralysed muscle. When the horizontal recti (medial or lateral) are affected, the characteristic posture is a turn of the face to right or left, e.g. in left lateral rectus palsy the head is turned to the left and in left medial recuts palsy the head is turned to the right. When a vertical rectus (superior or inferior) or an oblique muscle is affected, a tilt of the head to the right or left with depression or elevation of the chin is adopted to reduce both the vertical deviation and rotation, e.g in superior oblique palsy (dextrodepression of left eye is affected) the head is tilted to left so that the left eye can see down and medially. iv) There is false projection or orientation v) There is no amblyopia and visual acuity is normal as paralytic squint develops in adults when visual acuity has already developed.","pyqMatches":[{"year":"2014","no":1207,"q":"Following is a feature of concomitant squint ?","o":["Constant amount of deviation in all directions of gaze","Associated limitation of ocular movements","Different amount of deviation in different directions of gaze","Develops in the patients at 15 - 20 years of age."],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4684, 'Ophthalmology', 'Ocular Motility & Strabismus', 'Easy', 'Ophthalmology', 129, '{"id":4684,"subject":"Ophthalmology","chapter":"Ocular Motility & Strabismus","difficulty":"Easy","source":"Ophthalmology","sourceNo":129,"q":"Diplopia is usually seen in ?","o":["Paralytic squint","Non-paralytic squint","Both of the above","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Paralytic squint","pyqMatches":[{"year":"2014","no":1208,"q":"Diplopia is usually seen in ?","o":["Paralytic squint","Non-paralytic squint","Both of the above","None of the above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4685, 'Ophthalmology', 'Uvea', 'Moderate', 'Ophthalmology', 130, '{"id":4685,"subject":"Ophthalmology","chapter":"Uvea","difficulty":"Moderate","source":"Ophthalmology","sourceNo":130,"q":"Following is true about behcet''s disease except ?","o":["It shows presence of aphthous ulceration, genital ulceration and uveitis","Uveitis is bilateral, acute recurrent iridocyclitis with hypopyon","It has good visual prognosis","Chlorambucil can be used to control the disease"],"a":2,"e":"Ans. is ''c'' i.e., It has good visual prognosis BEHCET''S DISEASE It is an idiopathic multisystem disease characterised by recurrent, non-granulomatous uveitis, aphthous ulceration, genital ulcerations and erythema multiforme. Etiology It is still unknown; the basic lesion is an obliterative vasculitis probably caused by circulating immune complexes. The disease typically affects the young men who are positive for HLA-B5 1. Clinical features Uveitis seen in Behcet''s disease is typically bilateral, acute recurrent iridocyclitis associated with hypopyon. It may also be associated with posterior uveitis, vitritis, periphlebitis retinae and retinitis in the form of white necrotic infiltrates. Treatment No satisfactory treatment is available, and thus the disease has got comparatively poor visual prognosis. Corticosteroids may by helpful initially but ultimate response is poor. In some cases the disease may be controlled by chlorambucil.","pyqMatches":[{"year":"2014","no":1236,"q":"Following is true about behcet''s disease except ?","o":["It shows presence of aphthous ulceration, genital ulceration and uveitis","Uveitis is bilateral, acute recurrent iridocyclitis with hypopyon","It has good visual prognosis","Chlorambucil can be used to control the disease"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4686, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 131, '{"id":4686,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":131,"q":"Imbert-Fick law is associate with ?","o":["Schiotz tonometry","Applanation tonometry","Pachymetry","Keratometry"],"a":1,"e":"Ans. is ''b'' i.e., Applanation tonometry Applanation tonometry The concept of applanation tonometry was introduced by Goldmann is 1954. It is based on Imbert- Fick lawwhich states that the pressure inside a sphere (P) is equal to the force (W) required to flatten its surface divided by the area of flattening (A); i.e., P = W/A.","pyqMatches":[{"year":"2014","no":1152,"q":"Imbert-Fick law is associate with ?","o":["Schiotz tonometry","Applanation tonometry","Pachymetry","Keratometry"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4687, 'Ophthalmology', 'Optic Nerve & Neuro-ophthalmology', 'Easy', 'Ophthalmology', 132, '{"id":4687,"subject":"Ophthalmology","chapter":"Optic Nerve & Neuro-ophthalmology","difficulty":"Easy","source":"Ophthalmology","sourceNo":132,"q":"Recurrent non-granulomatous uveitis is seen in?","o":["Vogt koyanagi-Harada syndrome","Posner-Schlossman syndrome","Tuberculosis","Sarcoidosis"],"a":1,"e":"Ans. is `b'' i.e., Posner-Schlossman syndrome Glaumatocyclic crisis Glamatocyclitic crisis (Posner - Schlossman syndrome) is a unilateral recurrent non- granulomatous iritis that is associated with an elevated ocular pressure during the attacks. This self- limiting condition tends to occur in persons during the third to sixth decade and the visual fields, the optic nerve head, and anterior chamber angle are normal. A mild inflammatory reaction is very rarely present as evidenced by a few keratic precipitates on the posterior surface of the cornea. The cause of the glaucoma remains unknown, but a trabeculitis is suspected. Many patients (55%) subsequently develop open angle glaucoma.","pyqMatches":[{"year":"2014","no":1174,"q":"Recurrent non-granulomatous uveitis is seen in?","o":["Vogt koyanagi-Harada syndrome","Posner-Schlossman syndrome","Tuberculosis","Sarcoidosis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4688, 'Ophthalmology', 'Ocular Motility & Strabismus', 'Easy', 'Ophthalmology', 133, '{"id":4688,"subject":"Ophthalmology","chapter":"Ocular Motility & Strabismus","difficulty":"Easy","source":"Ophthalmology","sourceNo":133,"q":"Bett''s classification deals with ?","o":["Ocular trauma","Ocular foreign body","Squint","Maculopathy"],"a":0,"e":"Ans. is ''a'' i.e., Ocular trauma BETTS (Birmingham Eye Trauma Classification System) Ocular trauma classification group has organized eye injuries using standard technology to describe various forms of ocular injury. This is called BETTS - Birmingham Eye Trauma Classification System.","pyqMatches":[{"year":"2014","no":1230,"q":"Bett''s classification deals with ?","o":["Ocular trauma","Ocular foreign body","Squint","Maculopathy"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4689, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 134, '{"id":4689,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":134,"q":"How many incisions are used in the divided system approach of pars planavitrectomy?","o":["1","2","3","4"],"a":2,"e":"Ans. is ''c'' i.e., 3 Techniques of performing vitrectomy A) Open-sky vitrectomy This technique is employed to perform only anterior vitrectomy. Open sky vitrectomy is performed through the primary wound to manage the disturbed vitreous during cataract surgery or aphakickeratoplasty. B) Closed vitrectomy (Pars planavitrectomy) Pars plana approach is employed to perform core vitrectomy, subtotal and total vitrectomy.Pars planavitrectomy is a highly sophisticated microsurgery which can be performed by using two type of systems:","pyqMatches":[{"year":"2014","no":1237,"q":"How many incisions are used in the divided system approach of pars planavitrectomy?","o":["1","2","3","4"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4690, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 135, '{"id":4690,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":135,"q":"Munson''s sign is a feature of ?","o":["Keratoconus","Corneal ulcer","Pterygium","Posterior staphyloma"],"a":0,"e":"Ans. is ''a'' i.e., Keratoconus Kerotoconus Keratoconus is a progressive, noninflammatory, bilateral ectatic corneal disease, characterizedparaxia/stromal thinning and weakening that leads to corneal surface distortion. Essential pathological changes are thinning and ectasia which occur as a result of defective synthesis of mucopolysaccharide and collagen tissue. It usually starts at puberty and progresses slowly. Symptoms usually begins as blurred vision with shadowing around images. Vision becomes progressively more blurred and distorted with associated glare, halos around lights, light sensitivity and ocular irritation. Visual loss occurs primarily from irregular astigmatism and myopia, and secondarily from corneal scarring. o The hallmark of keratoconus is central or paracentral stromal thinning, apical protrusion of anterior corneaand irregular astigmatism. The cornea thins near the centre and progressively bulges forwards, with the apex of cone always being slightly below the centre of the cornea. Important findings an examination are - i) Distarted window reflex (Corneal reflex)e. ii) Fleisher''s rine. iii) Yawning reflex (Scissor reflex). iv) Oil drop reflex. v) Munson''s signs Treatment includes :? 1) Spectacles for regular or mild irregular astigmatism. 2) Rigid gas permeable contact lens for higher astigmatism. 3) Epikeratoplasty in patients intolerant to lens and without significant corneal scarring. 4) Keratoplasty penetrating or deep lamellar if there is significant corneal scarring.","pyqMatches":[{"year":"2014","no":1166,"q":"Munson''s sign is a feature of ?","o":["Keratoconus","Corneal ulcer","Pterygium","Posterior staphyloma"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4691, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 136, '{"id":4691,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":136,"q":"Newborn eye is ?","o":["Myopic","Hypermetropic","Presbyopic","None of the above"],"a":1,"e":"Ans. is ''b'' i.e., Hypermetropic Eye at birth Anteroposterior diameter of eye ball is about 16.5 mm (70% of adult size). Adult size is attained by 7-8 years. Corneal diameter is about 10 mm. Adult size (11.7 mm) is attained by 2 years of age. Anterior chamber is shallow and angle is narrow. Lens is spherical at birth. Retina :- Apart from macular area, the retina is fully differentiated. Macula differentiates 4-6 months after birth. Myelination of optic nerve fibres has reached the lamina cribrosa. New born is usually hypermetropic by +2 to +3D. Orbit is more divergent (50°) as compared to adult (45°). Lacrimal gland is still underdeveloped and tears are not secreted.","pyqMatches":[{"year":"2014","no":1158,"q":"Newborn eye is ?","o":["Myopic","Hypermetropic","Presbyopic","None of the above"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4692, 'Ophthalmology', 'Optic Nerve & Neuro-ophthalmology', 'Moderate', 'Ophthalmology', 137, '{"id":4692,"subject":"Ophthalmology","chapter":"Optic Nerve & Neuro-ophthalmology","difficulty":"Moderate","source":"Ophthalmology","sourceNo":137,"q":"Homonymous hemianopia type of visual field defect is seen in all except ?","o":["Lateral geniculate body","Total optic radiation","Optic tract","Optic chaisma"],"a":3,"e":"Ans. is ''d'' i.e., Optic chaisma","pyqMatches":[{"year":"2014","no":1210,"q":"Homonymous hemianopia type of visual field defect is seen in all except ?","o":["Lateral geniculate body","Total optic radiation","Optic tract","Optic chaisma"],"a":3,"source":"NEET_2014_Paper.pdf"},{"year":"2016","no":1009,"q":"Homonymous hemianopia type of visual field defect is seen in all except ?","o":["Lateral geniculate body","Total optic radiation","Optic tract","Optic chaisma"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2014","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4693, 'Ophthalmology', 'Optic Nerve & Neuro-ophthalmology', 'Moderate', 'Ophthalmology', 138, '{"id":4693,"subject":"Ophthalmology","chapter":"Optic Nerve & Neuro-ophthalmology","difficulty":"Moderate","source":"Ophthalmology","sourceNo":138,"q":"Following is true about oculocardiac reflex except ?","o":["It is also called aschner phenomenon","It is mediated by occulomotor and vagus nerve","It is characterized by bradycardia following traction on extra- ocular muscles","Reflex is more sensitive in neonates"],"a":1,"e":"Ans. is ''b'' i.e., It is mediated by occulomotor and vagus nerve Oculocardiac reflex Oculocardiac reflex, is also known as Aschner phenomenon, Aschner reflex, or Aschner-Dagnini reflex, o It is characterized by decrease in pulse rate (bradycardia) associated with traction applied to extraocular muscles and/or compression of the eyeball. The reflex is mediated by nerve connections between the ophthalmic branch of the trigeminal cranial nerve via the ciliary ganglion, and the vagus nerve of the parasympathetic nervous system. This reflex is especially sensitive in neonates and children, particularly during strabismus correction surgery. However, this reflex may also occur with adults. Bradycardia, junctional rhythm and asystole, all of which may be life- threatening,can be induced through this reflex.","pyqMatches":[{"year":"2014","no":1238,"q":"Following is true about oculocardiac reflex except ?","o":["It is also called aschner phenomenon","It is mediated by occulomotor and vagus nerve","It is characterized by bradycardia following traction on extra- ocular muscles","Reflex is more sensitive in neonates"],"a":1,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":287,"q":"Following is true about oculocardiac reflex except ?","o":["It is also called aschner phenomenon","It is mediated by occulomotor and vagus nerve","It is characterized by bradycardia following traction on extra- ocular muscles","Reflex is more sensitive in neonates"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4694, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 139, '{"id":4694,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":139,"q":"Corneal endothelial cell count is measured by ?","o":["Specular microscope","Ophthalmoscope","Synoptophore","Amsler''s grid"],"a":0,"e":"Ans. is ''a'' i.e., Specular microscope Corneal endothelium is examined with specular microscope, which allows a clear morphological study of endothelial cells including photographic documentation. The cell density of endothelium is around 3000 cells/mm2 in young adults, which decreases with advancing age.","pyqMatches":[{"year":"2012","no":928,"q":"Corneal endothelial cell count is measured by ?","o":["Specular microscope","Ophthalmoscope","Synoptophore","Amsler''s grid"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":1153,"q":"Corneal endothelial cell count is measured by ?","o":["Specular microscope","Ophthalmoscope","Synoptophore","Amsler''s grid"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4695, 'Ophthalmology', 'Glaucoma', 'Hard', 'Ophthalmology', 140, '{"id":4695,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Hard","source":"Ophthalmology","sourceNo":140,"q":"Drug kept as a last resort in the management of primary open angle glaucoma is ?","o":["Latanoprost","Topical beta blocker","Brimonidine","Oral acetazolamide"],"a":3,"e":"Ans. is ''d'' i.e., Oral acetazolamide Treatment of POAG (Primary open angle glaucoma) Following treatment options are available for POAG : Medical therapy :- Total medical therapy is the treatment of choice for POAG. Topical 13-blockers (Timolol, Betoxalol, Levobunolol, carteolol) are the drugs of choice. Topical prostaglandin analogues (Latanoprost, bimatoprost, travoprost) are the second choice drugs. Other topical drugs for POAG are:- LI Alpha agonists (non - selective : epinephrine, dipivefrine; and Selective - a2: apraclonidine, brimonidine) Carbonic anhydrase inhibitors (Dorzalamide, brinzolamide) Cholinomimetic drugs (Pilocarpine, physostigmine, echothiophate, carbachol) Pilocarpire has several drawbacks, therefore, is being considered as an adjunctive therapy only as a last resort. Approach to treatment of POAG Start monotherapy with topical P-blocker or latanoprost. If target IOT is not attained either change over to the alternative drug or use both the above concurrently. Brimonidine/dorazolamide/dipivefrine are used only when there are contraindications to PG analogues or 13-blockers. Topical miotics and oral acetazolamide are added only as the last resort. Systemic therapy is considered only as a last resort. Drugs used for systemic therapy are :- (i) Carbonic anhydrase inhibitors (Acetazolamide, Dichlorphenamide, methazolamide), (ii) Hyperosmotic agents (mannitol, glycerol).","pyqMatches":[{"year":"2014","no":1194,"q":"Drug kept as a last resort in the management of primary open angle glaucoma is ?","o":["Latanoprost","Topical beta blocker","Brimonidine","Oral acetazolamide"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4696, 'Ophthalmology', 'Uvea', 'Easy', 'Ophthalmology', 141, '{"id":4696,"subject":"Ophthalmology","chapter":"Uvea","difficulty":"Easy","source":"Ophthalmology","sourceNo":141,"q":"Amsler''s grid is used to evaluate ?","o":["Central 10 degress of vision","Central 20 degrees of vision","Peripheral vision","Lens opacity"],"a":0,"e":"Ans. is ''a'' i.e., Central 10 degress of vision Metamorphopsia is a phenomenon wherein the patient perceives objects to have an altered, irregular contour or shape. For example, graph paper lines may be bent or obscured in areas. This can be reviewed for any changes over time using an Amsler grid, which tests the central 10° of vision. It is associated with diseases affecting the macula such as central serous choroidopathy, age- related macular degeneration, diabetic macular oedema and macular hole.","pyqMatches":[{"year":"2014","no":1155,"q":"Amsler''s grid is used to evaluate ?","o":["Central 10 degress of vision","Central 20 degrees of vision","Peripheral vision","Lens opacity"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4697, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 142, '{"id":4697,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":142,"q":"Stye is suppurative inflammation of glands of ?","o":["Zeis","Meibonian","Wolfring","All the above"],"a":0,"e":"Ans. is ''a'' i.e., Zeis","pyqMatches":[{"year":"2014","no":1222,"q":"Stye is suppurative inflammation of glands of ?","o":["Zeis","Meibonian","Wolfring","All the above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4698, 'Ophthalmology', 'Refraction & Optics', 'Moderate', 'Ophthalmology', 143, '{"id":4698,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Moderate","source":"Ophthalmology","sourceNo":143,"q":"Objective methods for checking the refractive error are all except","o":["Ophthalmoscopy","Retinoscopy","Refractometry","Keratometry"],"a":0,"e":"Ans. is ''a'' i.e., Ophthalmoscopy The procedure of determining and correcting refractive errors is termed as refraction. The refraction comprises two complementary methods : ? A) Objective methods : Objective methods of refraction include :- (i) Retinoscopy, (ii) Refractometry, (iii) Keratometry. B) Subjective methods : These are :- (i) Subjective verification of refraction, (ii) Subjective refining of refraction, (iii) Subjective binocular balancing.","pyqMatches":[{"year":"2014","no":1156,"q":"Objective methods for checking the refractive error are all except","o":["Ophthalmoscopy","Retinoscopy","Refractometry","Keratometry"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4699, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 144, '{"id":4699,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":144,"q":"Lens dislocation in marfans syndrome is -","o":["Superotemporal","Inferonasal","Forward","Backward"],"a":0,"e":"Ans. is ''a'' i.e., Superotemporal","pyqMatches":[{"year":"2014","no":1199,"q":"Lens dislocation in marfans syndrome is","o":["Superotemporal","Inferonasal","Forward","Backward"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4700, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 145, '{"id":4700,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":145,"q":"Safe size of corneal graft with less chances of failure is ?","o":["7.5 mm","6.5 mm","5.5 mm","4.5 mm"],"a":0,"e":"Ans. is ''a'' i.e., 7.5 mm Correlation of corneal graft diameter and chances of graft failure Increased corneal graft size has been reported in some studies to be a significant risk factore for graft rejection. Other studies refute this and point to smaller graft size as more likely to be rejected. There is increased risk of rejection and endothelial failure in small grafts with recipient size < 7mm and also increased risk of rejection in large grafts with graft size > 8.5 mm. Thus the corneal graft with graft diameter between 7 and 8.5 mm has more chances of survival.","pyqMatches":[{"year":"2014","no":1167,"q":"Safe size of corneal graft with less chances of failure is ?","o":["7.5 mm","6.5 mm","5.5 mm","4.5 mm"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4701, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 146, '{"id":4701,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":146,"q":"Angular conjunctivitis is caused mainly by","o":["Moraxella axenfeld","Staphylococcus aureus","Streptococcus pneumonae","Pseudomonas aeruginosa"],"a":0,"e":"Ans. is ''a'' i.e., Moraxella axenfeld Angular conjunctivitis (diplobacillary conjunctivitis) It is a type of chronic conjunctivitis characterized by mild grade inflammation confined to conjunctiva and lid margins near the angles associated with maceration of the surrounding skin. Moraxella axenfeld (Moraxella lacunata), a diplobacillus, is the commonest causative organism. Less commonly, staphylococcus aureus can also cause angular conjunctivitis. Source of infection: Nasal tract of healthy people and the nasal discharge of patients with angular conjunctivitis. It spreads from the nasal cavity to the eye by contaminated hands and handkerchief. Angular conjunctivitis responds to tetracycline ointment, Oxytetracycline for 10 to 14 days. Eye drops containing zinc inhibit the proteolytic ferment and are of great value although less rapidly effective, and may be used in addition to tetracycline.","pyqMatches":[{"year":"2014","no":1164,"q":"Angular conjunctivitis is caused mainly by","o":["Moraxella axenfeld","Staphylococcus aureus","Streptococcus pneumonae","Pseudomonas aeruginosa"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4702, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 147, '{"id":4702,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":147,"q":"Anterior uveitis earliest lesion ?","o":["Aqueous flare","Keratic precipitates","Circumcorneal congestion","Blurring of vision"],"a":0,"e":"Ans. is ''a'' i.e., Aqueous flare Aqueous flare is the earliest sign of acute anterior uveitis. Keratic precipitates is the pathognomic sign of acute anterior uveitis Clinical features of acute anterior uveitis Acute anterior uveitis is the most common form of uveits, accounting for 60-70% of cases. It is characterized by sudden onset and duration less than 3 months. Presentation is typical with sudden onset of unilateral pain, photophobia, redness, lacrimation and blepherospasm. Vision may be normal initially. However, later there may be distrubance in vision due to ciliary spasm (induced myopia), corneal haze (due to edema & 1(13s) and aqueous turbidity. External examination shows following signs :- i. Circumcorneal (ciliary) congestion Which has a violaceous hue. i. Corneal edema, posterior corneal opacities. i. Keratic precipitates (KPs):- are proteinaceous cellular deposits at the back of cornea on endothelium. v. Anterior chamber signs :- Aqueous cells, Aqueous flare, hypopyon, hyphaemia (in hemorrhagic uveitis), deep anterior chamber (If posterior synachiae occurs). v. Iris signs :- Blurred & indistinct iris, i.e. muddy iris, instead of being clear and sharply defined. i. Papillary signs :- Narrow (miotic) pupil, irregular pupil due to segmental posterior synechiae which gives festooned appearance (festooned pupil) when dilated with atropine, sluggish pupillary reaction, ectropion pupillae (evertion of pupillary margins), occlusio pupillae (due to complete occlusion of pupil by organised exudate).","pyqMatches":[{"year":"2014","no":1170,"q":"Anterior uveitis earliest lesion ?","o":["Aqueous flare","Keratic precipitates","Circumcorneal congestion","Blurring of vision"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4703, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 148, '{"id":4703,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":148,"q":"Main MOA brimonidine in glaucoma ?","o":["Decreased aqueous secretion","Increased trabecular outflow","Increased uveoscleral outflow","Reduce vitreous volume"],"a":0,"e":"Ans. is ''a'' i.e., Decreased aqueous secretion","pyqMatches":[{"year":"2014","no":1192,"q":"Main MOA brimonidine in glaucoma ?","o":["Decreased aqueous secretion","Increased trabecular outflow","Increased uveoscleral outflow","Reduce vitreous volume"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4704, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 149, '{"id":4704,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":149,"q":"Meibomian glands secrete which component of sweat?","o":["Water (aqueous)","Mucin","Protein","Lipid"],"a":3,"e":"Ans. is ''d'' i.e., Lipid The major function of lacrimal apparatus is to secrete and drain the tear. Tear film consists of 3 layers :- i. Mucous or mucin layer (innermost):- Secreted by conjunctival goblet cells, crypts of Henle, glands of Manz. i. Aqueous layer (intermediate) :- This forms the bulk of the tear. It is secreted by main lacrimal and accessory lacrimal glands. i. Lipid layer (outermost) :- Secreted by the Meibomion Zeis, and Moll glands.","pyqMatches":[{"year":"2014","no":1223,"q":"Meibomian glands secrete which component of sweat?","o":["Water (aqueous)","Mucin","Protein","Lipid"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4705, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 150, '{"id":4705,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":150,"q":"Quantification of corneal sensation is done by ?","o":["Pachymeter","Keratometer","Aesthesiometer","Tonometer"],"a":2,"e":"Ans. is ''c'' i.e., Aesthesiometer Measurement of Corneal Sensitivity Corneal sensitivity may be tested by touching it in various places with a wisp of cotton-wool twisted to a fine point and comparing the effect with that on the other, normal cornea. There is in general a brisk reflex closure of the lids. Corneal sensations are often diminished after any gross disorder, but the change is of diagnostic significance in certain cases, particularly herpes keratitis where minimal corneal changes are accompanied by a gross diminution of sensation. Quantification of the corneal sensation is possible to some degree by the use of a corneal aesthesiometer in which a single horse hair of varying length is used instead of a wisp of cotton-wool. The longest length which induces blinking is a measure of the threshold of corneal sensitivity.","pyqMatches":[{"year":"2014","no":1154,"q":"Quantification of corneal sensation is done by ?","o":["Pachymeter","Keratometer","Aesthesiometer","Tonometer"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4706, 'Ophthalmology', 'Cornea & External Eye', 'Hard', 'Ophthalmology', 151, '{"id":4706,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Hard","source":"Ophthalmology","sourceNo":151,"q":"Subconjunctival hemorrhages are evident in the following cases except ?","o":["Whooping cough","Scurvy","Purpura","Pellagra"],"a":3,"e":"Ans. is ''d'' i.e., Pellagra Subconjunctival haemorrhage Occurs due to the rupture of small vessels. The condition, though unsightly, is trivial. This can occur spontaneously in elderly people with fragile vessels or those with systolic hypertension or after local ocular trauma or eye surgery. Very minute ecchymoses, or possibly thromboses, are seen in severe conjunctivitis; large extravasations accompany severe straining, especially in old people, as on lifting heavy weights or vomiting. They are not infrequently seen in children with whooping cough and may occur in scurvy, blood diseases such as purpura, or in malaria. Recurrent subconjunctival haemorrhages warrant investigations for a bleeding diatheses or leukaemia. The differential diagnosis includes Kaposi sarcoma. More serious are the large sub-conjunctival ecchymoses which seep forwards from the fonix following head injuries. They are due to an extravasation of blood along the floor of the orbit, secondary to a fracture of the base of the skull. In fractures of the sphenoid the blood appears later on the temporal side than elsewhere. Haemorrhages also result from severe or prolonged pressure on the thorax and abdomen, as in persons squeezed in a crowd or by machinery. The blood gradually changes colour and gets absorbed in 1 to 3 weeks without treatment. The use of aspirin and non-steroidal anti-inflammatory drugs (NSAIDs) should be avoided and if mild ocular irritation is present, artificial tears can be prescribed four to six times a day.","pyqMatches":[{"year":"2015","no":1010,"q":"Subconjunctival hemorrhages are evident in the following cases except ?","o":["Whooping cough","Scurvy","Purpura","Pellagra"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4707, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Easy', 'Ophthalmology', 152, '{"id":4707,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Easy","source":"Ophthalmology","sourceNo":152,"q":"Pleomorphic adenoma of the lacrimal gland moves the eyeball ?","o":["Downwards and outwards","Downwards and inwards","Upwards and outwards","Upwards and inwards"],"a":0,"e":"Ans. is ''a'' i.e., Downwards and outwards Benign mixed tumour of lacrimal gland IPleomorphic adenoma'' It is also known as pleomorphic adenoma and occurs predominantly in young adult males. Clinically it presents as a slowly progressive painless swelling in the upper-outer quadrant of the orbit displacing the eyeball downwards and outwards. It is locally invasive and may infiltrate its own pseudocapsule to involve the adjacent periosteum. Histologically, it is characterised by presence of pleomorphic myxomatous tissue, just like benign mixed tumour of salivary gland. Treatment consists of complete surgical removal with the capsule. Recurrences are very common following incomplete removal.","pyqMatches":[{"year":"2014","no":1239,"q":"Pleomorphic adenoma of the lacrimal gland moves the eyeball ?","o":["Downwards and outwards","Downwards and inwards","Upwards and outwards","Upwards and inwards"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4708, 'Ophthalmology', 'Optic Nerve & Neuro-ophthalmology', 'Easy', 'Ophthalmology', 153, '{"id":4708,"subject":"Ophthalmology","chapter":"Optic Nerve & Neuro-ophthalmology","difficulty":"Easy","source":"Ophthalmology","sourceNo":153,"q":"Optic canal is a part of ?","o":["Lesser wing of sphenoid","Greater wing of sphenoid","Ethmoid","Pterygoid"],"a":0,"e":"Ans. is ''a'' i.e., Lesser wing of sphenoid The optic nerve leaves the orbit is the optic canal to enter the cranial vault. The optic canal is the most posterior landmark of the orbit. It measures 10 mm in length. The thin piece of bone separating the optic canal from the superior orbital fissure is the optic strut. The optic strut and optic canal are a part of the lesser wing of sphenoid bone.","pyqMatches":[{"year":"2014","no":1175,"q":"Optic canal is a part of ?","o":["Lesser wing of sphenoid","Greater wing of sphenoid","Ethmoid","Pterygoid"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4709, 'Ophthalmology', 'Retina & Vitreous', 'Moderate', 'Ophthalmology', 154, '{"id":4709,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Moderate","source":"Ophthalmology","sourceNo":154,"q":"Floaters are seen in following except ?","o":["Vitreous hemorrhage","Retinal detachment","Uveitis","Acute congestive glaucoma"],"a":3,"e":"Ans. is `d'' i.e., Acute congestive glaucoma Floaters A floater is something in the fluids of the eye that casts a shadow on the retina and looks like a dark spot or spots floating around in the field of vision. Floaters are usually described by patients, as small, semitranslucent particles of varying shapes moving across the visual field with the movement of the eye. Floater can only be seen with the eyes open and in a lighted environment. Floaters are usually grey or black, since they are actually shadow on the retina. Causes of floaters are :- i. Posterior vitreous detachment (PVD) i. Bleeding (vitreous hemorrhage) i. Retinal detachment v. Inflammation of eye (uveitis) v. High myopia","pyqMatches":[{"year":"2014","no":1157,"q":"Floaters are seen in following except ?","o":["Vitreous hemorrhage","Retinal detachment","Uveitis","Acute congestive glaucoma"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4710, 'Ophthalmology', 'Refraction & Optics', 'Easy', 'Ophthalmology', 155, '{"id":4710,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Easy","source":"Ophthalmology","sourceNo":155,"q":"Illuminated frenzel glasses are used in detecting?","o":["Nystagmus","Heterophoria","Esotropia","Astigmatism"],"a":0,"e":"Ans. is ''a'' i.e., Nystagmus Illuminated frenzel galsses (+20 lenses) are useful for abolishing fixation and thus revealing peripheral vestibular nystagmus.","pyqMatches":[{"year":"2014","no":1240,"q":"Illuminated frenzel glasses are used in detecting?","o":["Nystagmus","Heterophoria","Esotropia","Astigmatism"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4711, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 156, '{"id":4711,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":156,"q":"Following is a cause of secondary angle closure glaucoma ?","o":["Pseudophakia","Corticosteroid induced","Angle recession glaucoma","Congenital glaucoma"],"a":0,"e":"Ans. is ''a'' i.e., Pseudophakia Causes of secondary angle closure glaucoma Pupillary block: uveitis, psudophakia Angle fibrosis: neovascular glaucoma","pyqMatches":[{"year":"2014","no":1195,"q":"Following is a cause of secondary angle closure glaucoma ?","o":["Pseudophakia","Corticosteroid induced","Angle recession glaucoma","Congenital glaucoma"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4712, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 157, '{"id":4712,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":157,"q":"Which gas is most commonly used with pneumatic retinopathy ?","o":["SF6","C3F8","CO2","N3"],"a":0,"e":"Ans. is ''a'' i.e., SF6 Sulfur hexafluoride gas (SF6) is most commonly used with pneumatic retinopexy.","pyqMatches":[{"year":"2014","no":1189,"q":"Which gas is most commonly used with pneumatic retinopathy ?","o":["SF6","C3F8","CO2","N3"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4713, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 158, '{"id":4713,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":158,"q":"Latanoprost used topically in glaucoma primarily acts by?","o":["Decreasing aqueous humor formation","Increasing uveoscleral outflow","Releasing pupillary block","Increasing trabecular outflow"],"a":1,"e":"Ans. is ''b'' i.e., Increasing uveoscleral outflow Ans. is ''b'' i.e., Increasing uveoscleral outflow Latanoprost is an analog of prostaglandin F2a that increases uveoscleral outflow and induces miosis. Antiglaucoma Drugs: Mechanism of Lowering Intraocular Pressure (IOP): Drugs that increase trabecular outflow ? Miotics (e.g., pilocarpine) ? Epinephrine, dipivefrine ? Bimatoprost Drugs that increase uveoscleral outflow ? Prostaglandins (latanoprost) ? Epinephrine, dipivefrine ? Brimonidine ? Apraclonidine Drugs that decrease aqueous production ? Carbonic anhydrase inhibitors (e.g., acetazolamide, dorzolamide) ? Alpha receptor stimulators in ciliary process (e.g., epinephrine, dipivefrine, clonidine, brimonidine, apraclonidine) ? Beta-blockers Hyperosmotic agents - (e.g., glycerol, mannitol, urea).","pyqMatches":[{"year":"2015","no":1039,"q":"Latanoprost used topically in glaucoma primarily acts by?","o":["Decreasing aqueous humor formation","Increasing uveoscleral outflow","Releasing pupillary block","Increasing trabecular outflow"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4714, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 159, '{"id":4714,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":159,"q":"2nd Purkinje image is ?","o":["Erect and moves in same direction","Inverted and moves in same direction","Erect and moves in opposite direction","Inverted and moves in opposite direction"],"a":0,"e":"Ans. is ''a'' i.e., Erect and moves in same direction 1st from anterior surfac: of cornea --> Erett anil moves in same direction. 2nd from posterior surface of cornea --> Erect and moves in same direction. 3rd from anterior surface of lens --> Erect and move in same direction. 4th from posterior surface of lens --> Inverted and moves in opposite direction","pyqMatches":[{"year":"2012","no":927,"q":"2nd Purkinje image is ?","o":["Erect and moves in same direction","Inverted and moves in same direction","Erect and moves in opposite direction","Inverted and moves in opposite direction"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4715, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Easy', 'Ophthalmology', 160, '{"id":4715,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Easy","source":"Ophthalmology","sourceNo":160,"q":"Axial length of eye ball is measured by ?","o":["A mode Ultrasonography","B mode Ultrasonography","M mode Ultrasonography","Both a and b"],"a":0,"e":"Ans. is ''a'' i.e., A mode Ultrasonography Ultrasonographv in Ophthalmology A Mode Transducer is coupled directly to the eye through the use of methyl cellulose. Recording are done in a graphic mode. Height of the recorded spike on vertical axis is a measure of the amplitude of the echo, the position of the spike along the horizontal axis indicates the arrival of the echo on the tranducer. Diagnosis is based on the basis of amplitude, position, extent and movement of the abnormal echoes alonwith the sound attenuating properties of the abnormality. It has a special role in biometry i.e. axial length which is very essential for surgical planning. B mode The transducer is coupled to the eye by either the gel applied to the closed lid or by a saline bath Is is a display of two - dimensional cross sectional images. The echoes in B scan are displayed as spots and the brightness of echoes indicates its amplitude.","pyqMatches":[{"year":"2015","no":1028,"q":"Axial length of eye ball is measured by ?","o":["A mode Ultrasonography","B mode Ultrasonography","M mode Ultrasonography","Both a and b"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4716, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Easy', 'Ophthalmology', 161, '{"id":4716,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Easy","source":"Ophthalmology","sourceNo":161,"q":"Enophthalmos is seen in ?","o":["Blow out fracture of orbit wall","Hyperthyroidism","Radiation Injuries","Diabetes mellitus"],"a":0,"e":"Ans. is ''a'' i.e., Blow out fracture of orbit wall Enophthalmos is seen in blow out fracture of orbit wall.","pyqMatches":[{"year":"2016","no":1025,"q":"Enophthalmos is seen in ?","o":["Blow out fracture of orbit wall","Hyperthyroidism","Radiation Injuries","Diabetes mellitus"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4717, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 162, '{"id":4717,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":162,"q":"Acute angle closure glaucoma first line treatment?","o":["Iv mannitol","Acetazolamide","Pilocarpine","Beta blocker eyedrops"],"a":0,"e":"Ans. is ''a'' i.e., I.V. Mannitol Treatment of angle closure glaucoma Definitive treatment (treatment of choice) is surgery. However, intially drugs are used to decrease KW during an acute attack. Approach of treatment is as follows:- Start i.v. mannitol or i.v. acetazolamide When IOT starts falling, start topical pilocarpine or β-blocker (timolol). Apraclonidine/latanoprost may be added. Once IOT is reduced, surgery is done. Topical pilocarpine 2% is the preferred antiglaucomatous drug. After control of IOP, Laser (Nd : YAG) peripheral irodotomy is the definitive management of choice. If laser is not available surgical peripheral iridectomy is the procedure of choice. Other surgical procedures used are filteration surgeries (like trabeculectomy, deep sclerotomy, Viscoanulostomy). Symptomatic treatment during an attack also includes analgesics, antiemetic and topical corticosteroids to reduce inflammation. Mydriatics (e.g. atropine) are contraindicated as they precipitate glaucoma. PACG is a bilateral disease, the fellow eye is at risk of developing an acute attack in 50% cases in future. Therefore a prophylactic peripheral laser iridotomy should be performed in the fellow eye.","pyqMatches":[{"year":"2013","no":1175,"q":"Acute angle closure glaucoma first line treatment?","o":["Iv mannitol","Acetazolamide","Pilocarpine","Beta blocker eyedrops"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4718, 'Ophthalmology', 'Miscellaneous', 'Moderate', 'Ophthalmology', 163, '{"id":4718,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Ophthalmology","sourceNo":163,"q":"Occulomotor nerve supplies all extraocular muscles except ?","o":["Superior rectus","Inferior rectus","Lateral rectus","Medial rectus"],"a":2,"e":"Ans. is ''c'' i.e., Lateral rectus","pyqMatches":[{"year":"2015","no":101,"q":"Occulomotor nerve supplies all extraocular muscles except ?","o":["Superior rectus","Inferior rectus","Lateral rectus","Medial rectus"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4719, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 164, '{"id":4719,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":164,"q":"Which bacteria penetrates intact cornea ?","o":["Corynebacterium","Pneumococcus","Morexella","E. coli"],"a":0,"e":"Ans. is ''a'' i.e., Corynebacterium Bacterial corneal ulcer Bacterial corneal ulcer, also called suppurative keratitis, is due to organisms that produce toxin which cause tissue necrosis and pus formation in the corneal tissue. Purulent keratitis is nearly always exogenous, due to pyogenic organism. As long as the cornea is healthy, the majority of bacteria are unable to cross or adhere to the corneal epithelium. Therefore the two main predisposing factors for bacterial corneal ulcer are : -","pyqMatches":[{"year":"2012","no":934,"q":"Which bacteria penetrates intact cornea ?","o":["Corynebacterium","Pneumococcus","Morexella","E. coli"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4720, 'Ophthalmology', 'Cornea & External Eye', 'Moderate', 'Ophthalmology', 165, '{"id":4720,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Moderate","source":"Ophthalmology","sourceNo":165,"q":"Which of the following is not a feature of fungal corneal ulcer?","o":["Fixed hypopyon","Ulcer with sloughing margins","Symptoms are more pronounced than signs","Fungal hyphae are seen on KOH mount"],"a":2,"e":"Ans. c. Symptoms are more pronounced than signs","pyqMatches":[{"year":"2016","no":974,"q":"Which of the following is not a feature of fungal corneal ulcer?","o":["Fixed hypopyon","Ulcer with sloughing margins","Symptoms are more pronounced than signs","Fungal hyphae are seen on KOH mount"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4721, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 166, '{"id":4721,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":166,"q":"Congenital dacrocystitis, the block is at?","o":["Lacrimal calnaliculi","Nasolacrimal duct","Punctum","None"],"a":1,"e":"Ans. is ''b'' i.e., Nasolacrimal duct Congenital dacryocystitis (Dacryocvstitis neonatorum) It is the inflammation of lacrimal sac in the newborn. It is due to congenital blockage of nasolacrimal duct. Congenital dacryocystitis usually presents as a mild grade chronic inflammation. It is characterized by :?","pyqMatches":[{"year":"2013","no":1212,"q":"Congenital dacrocystitis, the block is at?","o":["Lacrimal calnaliculi","Nasolacrimal duct","Punctum","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4722, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 167, '{"id":4722,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":167,"q":"Dacrocytorhinostomy involves?","o":["Opening up the terminal blocked end of nasolacrimal duct","Connecting the lacrimal sac to nose by breaking the medial wall","Complete excision of lacrimal","Insertion of drainage tube in the lacrimal sac"],"a":1,"e":"Ans. is ''b'' i.e., Connecting the lacrimal sac to nose by breaking the medial wall Dacryocystorhinostomy is the surgical procedure which involves removal of bone adjacent to lacrimal sac (medialwall) and incorporating the lacrimal sac with lateral nasal mucosa (at middle meatus) in order to bypass the obstruction in nasolacrimal duct. Advantage of dacryocystorhinostomy over dacryocystectomy is that there is no epiphora or watering of eyes posteoperatively. Indications of dacryocystorhinostomy are :-","pyqMatches":[{"year":"2013","no":1213,"q":"Dacrocytorhinostomy involves?","o":["Opening up the terminal blocked end of nasolacrimal duct","Connecting the lacrimal sac to nose by breaking the medial wall","Complete excision of lacrimal","Insertion of drainage tube in the lacrimal sac"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4723, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 168, '{"id":4723,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":168,"q":"Copper deposition in cornea leads to?","o":["Keratoconus","Keratoglobus","KF ring","Siderosis"],"a":2,"e":"Ans. is ''c'' i.e., KF ring Retention of Foreign bodies The retention of a foreign body adds considerably to the danger of a penetrating injury. The foreign bodies most likely to penetrate and be retained in the eye are minute chips of iron or steel (accounting for 90% of the foreign bodies in industry), stone, and particles of glass, lead pellets, copper percussion caps and less frequently, spicules of wood. In chipping stone with an iron chisel, it is commonly a chip of the chisel and not of the stone which enters the eye. Chalcosis is perforating injury to eye with metal containing copper (Cu). Copper deposition can lead to :?","pyqMatches":[{"year":"2013","no":1216,"q":"Copper deposition in cornea leads to?","o":["Keratoconus","Keratoglobus","KF ring","Siderosis"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4724, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 169, '{"id":4724,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":169,"q":"Habbs striae are seen in ?","o":["Buphthalmos","Keratoglobus","Trachoma","Keratoconus"],"a":0,"e":"Ans. is ''a'' i.e., Buphthalmos Examination findings of primary congenital glaucoma (buphthalmos) First sign is corneal edema with watering of eye with marked photophobia Haab striae (Discrete corneal opacities appear as lines with double contour due to rupture in Descemets membrane) Cornea is hazy with frosted glass appearance. Corneal enlargement Thin & blue sclera Deep anterior chamber Lens is antero- posteriorly flat and may be subluxated backward Iridodonesis (tremulous iris) and atrophic patch on iris Large eye (Buphthalmos or hydrophthalmos) Variable cupping and atrophy of disc Raised IOP (neither acute nor marked) Axial myopia due to increased axial length which may give rise to anisometropic amblyopia","pyqMatches":[{"year":"2013","no":1173,"q":"Habbs striae are seen in ?","o":["Buphthalmos","Keratoglobus","Trachoma","Keratoconus"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4725, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 170, '{"id":4725,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":170,"q":"Krukenberg spindles -","o":["Involves anterior surface of cornea","Involves anterior lens surface","Involves posterior surface of cornea","Involves posterior surface of lens"],"a":2,"e":"Ans. is ''c'' i.e., Involves posterior surface off cornea Pigmentot-v glaucoma It is a type of secondary open angle glaucoma where in clogging up of trabecular meshwork occurs by the pigment particles. The condition typically occurs in young myopic males. The characteristic feature is the deposition of pigment granules in the anterior segment structures such as iris, posterior surface of the cornea (Krukenberg''s spindle), trabecular meshwork, ciliary zonul es and the crystalline lens.o Gonioscopy shows pigment accumulation along the schwalbe''s line especially inferiorly (Sampalesi''s line). Iris transillumination shows radial slit-like transillumination defects in the mid periphery (pathognomonic feature). Treatment is as for primary open angle glaucoma","pyqMatches":[{"year":"2013","no":1171,"q":"Krukenberg spindles","o":["Involves anterior surface of cornea","Involves anterior lens surface","Involves posterior surface of cornea","Involves posterior surface of lens"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4726, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 171, '{"id":4726,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":171,"q":"Eye of a newborn is ?","o":["Emmetropic","Hypermetropic","Myopic","Astigmatism"],"a":1,"e":"Ans. is ''b'' i.e., Hypermetropic Eye at birth Anteroposterior diameter of eye ball is about 16.5 mm (70% of adult size). Adult size is attained by 7-8 years. Corneal diameter is about 10 mm. Adult size (11.7 mm) is attained by 2 years of age. Anterior chamber is shallow and angle is narrow. Lens is spherical at birth. Retina : - Apart from macular area, the retina is fully differentiated. Macula differentiates 4-6 months after birth. Myelination of optic nerve fibres has reached the lamina cribrosa. New born is usually hypermetropic by +2 to +3D. Orbit is more divergent (50°) as compared to adult (450). Lacrimal gland is still underdeveloped and tears are not secreted.","pyqMatches":[{"year":"2013","no":1113,"q":"Eye of a newborn is ?","o":["Emmetropic","Hypermetropic","Myopic","Astigmatism"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4727, 'Ophthalmology', 'Retina & Vitreous', 'Moderate', 'Ophthalmology', 172, '{"id":4727,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Moderate","source":"Ophthalmology","sourceNo":172,"q":"Causes of exudative retinal detachment are all except-","o":["Toxemia of pregnancy","Scleritis","High myopia","Central serous retinopathy"],"a":2,"e":"Ans. is ''c'' i.e., High myopia Cause: retinal detachment","pyqMatches":[{"year":"2013","no":1178,"q":"Causes of exudative retinal detachment are all except","o":["Toxemia of pregnancy","Scleritis","High myopia","Central serous retinopathy"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4728, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 173, '{"id":4728,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":173,"q":"Commotio retinae affects which part of retina -","o":["Posterior pole","Peripheral retina","Inferior-nasal part","Superior-nasal part"],"a":0,"e":"Ans. is ''a'' i.e., Posterior pole Berlin''s oedema, also called commotio retinae, occurs in blunt trauma to eye. It manifests as milky white cloudiness involving a considerable area of the posterior pole with a ''cherry-red'' spot in the foveal region. It may disappear after some days or may be followed by pigmentary changes.","pyqMatches":[{"year":"2013","no":1217,"q":"Commotio retinae affects which part of retina","o":["Posterior pole","Peripheral retina","Inferior-nasal part","Superior-nasal part"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4729, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 174, '{"id":4729,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":174,"q":"Standard in perimetry ?","o":["Goldman type I","Goldman type II","Goldman type III","Goldman type IV"],"a":2,"e":"Ans. is ''c'' i.e., Goldman type III Projected stimuli in perimetry are usually white and of variable size and intensity. There are five different sizes on Goldmann scale designated by Roman numeral Ito V. The standard used in both manual and automated perimetry is Goldman III (0.05\" and area of 4mm2). o Failure to recognize target size III necessitates testing with stimulus V Goldman scaleStimulus size (mm2) I ''/4 II 1 III 4 IV 16 v 64","pyqMatches":[{"year":"2013","no":1124,"q":"Standard in perimetry ?","o":["Goldman type I","Goldman type II","Goldman type III","Goldman type IV"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4730, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 175, '{"id":4730,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":175,"q":"Treatment of congenital ptosis with poor elevation is","o":["Levator resection","Frontalis sling","FS operation","None of the"],"a":1,"e":"Ans. is ''b'' i.e., Frontalis sling Surgeries for ptosis Depending upon the LPS action, three main types of techniques are available.","pyqMatches":[{"year":"2013","no":1220,"q":"Treatment of congenital ptosis with poor elevation is","o":["Levator resection","Frontalis sling","FS operation","None of the"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4731, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 176, '{"id":4731,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":176,"q":"Dacrocystorhinostomy, where the duct is opened?","o":["Superior meatus","Inferior meatus","Middle meatus","Sphenoethmoidal recess"],"a":2,"e":"Ans. is ''None > c'' i.e., Middle meatus CMV retinitis is the most common ophthalmic manifestation of CMV, occuring as a congenital infection in infants or an opportunistic infection in the immunocompromised host. Adults commonly affected include those individuals with acquired immunodeficiency syndrome (AIDS), oncology patients, and patients on immunosuppresive therapy. There is characteristic hemorrhagic, full thickness retinitis. In early stage there are yellow-white exudates (areas of retinal necrosis) associated with areas of vasculitis and retinal hemorrhage. There may be exudative retinal detachment and ultimately, there occurs total retinal atrophy. There are three distinct variants of CMV retinitis :?","pyqMatches":[{"year":"2013","no":1214,"q":"Dacrocystorhinostomy, where the duct is opened?","o":["Superior meatus","Inferior meatus","Middle meatus","Sphenoethmoidal recess"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4732, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Easy', 'Ophthalmology', 177, '{"id":4732,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Easy","source":"Ophthalmology","sourceNo":177,"q":"Blow out fracture of orbit leads to fracture in","o":["Floor","Posterior Medial wall","Lateral wall","Roof of the orbit"],"a":1,"e":"Ans:B","pyqMatches":[{"year":"2016","no":1018,"q":"Blow out fracture of orbit leads to fracture in","o":["Floor","Posterior Medial wall","Lateral wall","Roof of the orbit"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4733, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 178, '{"id":4733,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":178,"q":"Most common symptom in buphthalmos is?","o":["Lacrimation","Pain","Photophobia","Itching"],"a":0,"e":"Ans. is ''a'' i.e., Lacrimation The commonest symptom is watering\" In Buphthalmos Most common symptom → Watering (lacrimation) 2nd most common symptom → Photophobia Most troublesome symptom → Photophobia (Child avoids light) o First sign→ Corneal edema with watering Frosted glass appearance of the cornea (hazy cornea) Haab striae Large cornea Deep anterior chamber Lens anteroposteriorly flat","pyqMatches":[{"year":"2013","no":1172,"q":"Most common symptom in buphthalmos is?","o":["Lacrimation","Pain","Photophobia","Itching"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4734, 'Ophthalmology', 'Optic Nerve & Neuro-ophthalmology', 'Easy', 'Ophthalmology', 179, '{"id":4734,"subject":"Ophthalmology","chapter":"Optic Nerve & Neuro-ophthalmology","difficulty":"Easy","source":"Ophthalmology","sourceNo":179,"q":"Normal vision with absence of direct & consensual light reflex, which nerve is involved ?","o":["Optic","Oculomotor","Trigeminal","Abducens"],"a":1,"e":"Ans. is ''b'' i.e., Oculomotor This question can be solved by simple basic knowledge :- Among the given options only oitic nerve and occulomotor newes are related to light reflex'' a In optic nerve injury vision is also impaired (vision is normal in the question)'' n Thus answer is oculomotor nerve When light is shone to one (e.g. left) eye. left optic nerve canies afferent impulse to brain and from brain efferent impulse to ipsiplateral (left) eye comes through ipsilateral (left) occulomotor nerye (for direct light reflex) and efferent for contralatcral (right) eye comes through contralateral (right) occulmotor nerve for consensual light reflex'' When light is shone to other (right) eyc, right optic nerve carries afferent impulse to brain and from brain, efferent impulse to right eye (for direct light reflex) comes through right occulmotor nerve and effcrent fbr left eye (for consensual light reflex) comes through left occulomotor nerve'' So :- Optic newe is responsibtefor direct light reJlex in ipsilateral eye and consensual light reflexfor contralateral eye. (lnabove example, afferent for right sided direct and left sided consensual light reflex is through right optic nerve; and atl-erent for left sided direct and right sided consensual light reflex is through left optic nerve)'' Occulomotor nerve is responsible for direct and consensual light reflex in the same eye'' (ln above example'' efferent for right sided direct as rvell as consensual light reflex is through right occulmotor nerve and ef''ferent for left sided direct as well as consensual light reflex is through left occulomotor nerve)'' In complete optic nerve lesion of one side (Amaurosis light reflex or total afferent pupillary fect) The ipsilateral direct reflex is lost The ipsilateral conscnsual reflex is intact The contralateral direct reflex is intact The contralateral consensual reflex is lost In occulomotor nerve lesion ofone side (efferent pupillarydefect The ipsilateral direct reflex is lost The ipsilateral consensual reflex is lost The contralateral direct reflex is intact The contralateral consensual reflex is intact","pyqMatches":[{"year":"2013","no":1192,"q":"Normal vision with absence of direct & consensual light reflex, which nerve is involved ?","o":["Optic","Oculomotor","Trigeminal","Abducens"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2016","no":1010,"q":"Normal vision with absence of direct & consensual light reflex, which nerve is involved ?","o":["Optic","Oculomotor","Trigeminal","Abducens"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2013","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4735, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 180, '{"id":4735,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":180,"q":"The most common cause of vitreous hemorrhage in adults is","o":["Retinal hole","Trauma","Hypertension","Diabetes"],"a":3,"e":"Ans. is ''d'' i.e., Diabetes Diabetic retinopathy is the commonest cause of spontaneous vitreous hemorrhage in adults\". __ Parson''s \"Most common cause of vitreous hemorrhage is diabetic retinopathy in adults\". — Atlas of ophthalmology Causes of vitreous hemorrhage Posterior vitreous detachment Eale''s disease & Coat''s disease Retineal tear (break) due to trauma Vascular disorders :- Hypertensive retinopathy, or vitreous traction. CRVO Proliferative diabetic retinopathy Acute chorioretinitis, periphlebitis or uveitis Branched retinal vein occlusion Bleeding disorders (Polycythemia, anemia, SCA) Age- related macular degeneration Neoplasm Retinal macroaneurysm Treson syndrome","pyqMatches":[{"year":"2013","no":1187,"q":"The most common cause of vitreous hemorrhage in adults is","o":["Retinal hole","Trauma","Hypertension","Diabetes"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4736, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 181, '{"id":4736,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":181,"q":"Slit lamp examination helps in examination of?","o":["Anterior 2/3rd of choroid","Anterior 1/3rd of choroid","Posterior 1/3rd of choroid","Posterior capsule"],"a":3,"e":"Ans. is ''d'' i.e., Posterior capsule Slit-lamp bimicroscopy is very useful in the diagnosis of eye diseases. o It should routinely be performed in almost all diseases of the eye. o Following structures are examined ?","pyqMatches":[{"year":"2013","no":1125,"q":"Slit lamp examination helps in examination of?","o":["Anterior 2/3rd of choroid","Anterior 1/3rd of choroid","Posterior 1/3rd of choroid","Posterior capsule"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4737, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 182, '{"id":4737,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":182,"q":"Retinal detachment occurs between","o":["Layers of neurosensory retina","Neurosensory retina and pigment epithelium","Pigment epithelium and choroid","None of the above"],"a":1,"e":"Ans. is ''b'' i.e., Neurosensory retina and pigment epithelium Retina has total ten layers from with out inward :- (i) Pigmented epithelium, (ii) Layers ofRods & cones, (iii) External limiting membrane, (iv) Outer nuclear layer, (v) Outer plexiform layers, (vi) Inner nuclear layer, (vii) Inner plexiform layer, (viii) Ganglionic cell layer, (ix) Nerve fibre layer, (x) Internal limiting membrane Broadly these layers are subdivided into two layers based on the function :? Neurosensory layer or sensory layer (containing layers ii to x of above 10 layers) :- for vision. Pigmented epithelium (layer i) :- Provide metabolic support to neurosensory layer and acts as an antireflective layer. So, inner layers are included in neurosensory layer and outer most layer is retinal pigmented epithelium(RPE). Retinal detachment is a disorder of eye in which retina peels away from its underlying layer of support tissue. Usually there is separation between the neuroepithelium (neurosensory epithelium or sensory epithelium) and the pigmented layer, because there is a potential space between these two layers where fluid can accumulates and can cause separation.","pyqMatches":[{"year":"2013","no":1181,"q":"Retinal detachment occurs between","o":["Layers of neurosensory retina","Neurosensory retina and pigment epithelium","Pigment epithelium and choroid","None of the above"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":1184,"q":"Retinal detachment occurs between","o":["Layers of neurosensory retina","Neurosensory retina and pigment epithelium","Pigment epithelium and choroid","None of the above"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4738, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 183, '{"id":4738,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":183,"q":"Ocular bobbing?","o":["Midbrain","Pons","Medulla","Cortex"],"a":1,"e":"Ans. is ''b'' i.e., Pons Square-wave erks Not localizing Macro square-wave erks Cerebellum Macrosaccadic oscillation Cerebellum Voluntary nystagmus Volitional Saccadic pulses Cerebellum, lower brainstem Ocular flutter Cerebellum, lower brainstem Opsoclonus Cerebellum, lower brainstem Ocular bobbing Pons","pyqMatches":[{"year":"2013","no":1195,"q":"Ocular bobbing?","o":["Midbrain","Pons","Medulla","Cortex"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4739, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 184, '{"id":4739,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":184,"q":"Bilateral inferior lens subluxation is seen in?","o":["Marfan syndrome","Homocysteinuria","Ocular trauma","None of the above"],"a":1,"e":"Ans. is `b'' i.e., Homocysteinuria","pyqMatches":[{"year":"2013","no":1168,"q":"Bilateral inferior lens subluxation is seen in?","o":["Marfan syndrome","Homocysteinuria","Ocular trauma","None of the above"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4740, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 185, '{"id":4740,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":185,"q":"Retinitis pigmentosa is characterized by ?","o":["Central scotoma","Centrocaecal scotoma","Tubular vision","Isopteric contraction"],"a":2,"e":"Ans. is ''c'' i.e., Tubular vision Important facts Earliest visual field defect in primary open angle glaucoma→ Isopeteric contraction. Earliest clinically significant visual .field defect in primary open angle glaucoma —> Paracentral scotoma, Visual field deject in rheugmatogenous retinal detachment→ Loss of peripheral field. Visual field defect in retinitis pigmentosa→ Tubular vision. Most common visual ,field defect in optic neuritis → Central or centrocaecal. Visual field defect in papilloedema→ Enlargement of blind spot and progressive contraction of visual _field. Visual field defect in Leber''s optic neuropathy→ Centmcaecal. Characteristic visual .field defect in anterior ischemic optic neuropathy→ Altitudinal visual field defects.","pyqMatches":[{"year":"2013","no":1130,"q":"Retinitis pigmentosa is characterized by ?","o":["Central scotoma","Centrocaecal scotoma","Tubular vision","Isopteric contraction"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4741, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 186, '{"id":4741,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":186,"q":"Scissor reflex is seen in ?","o":["Open angle glaucoma","Phlyctenular conjunctivitis","Keratoconus","Interstitial keratitis"],"a":2,"e":"Ans. is ''c'' i.e., Keratoconus Keratoconus is a progressive, noninflammatory, bilateral ectatic corneal disease, characterizedparaxiastromal thinning and weakening that leads to corneal surface distortion. Essential pathological changes are thinning and ectasia which occur as a result of defective synthesis of mucopolysaccharide and collagen tissue. It usually starts at puberty and progresses slowly. Symptoms usually begins as blurred vision with shadowing around images. Vision becomes progressively more blurred and distorted with associated glare, halos around lights, light sensitivity and ocular irritation. Visual loss occurs primarily from irregular astigmatism and myopia. and secondarily from corneal scarring The hallmark of keratoconus is central or paracentral stromal thinning, apical protrusion of anterior corneaand irregular astigmatism. The cornea thins near the centre and progressively bulges forwards, with the apex of cone always being slightly below the centre of the cornea. Important findings an examination are -","pyqMatches":[{"year":"2013","no":1142,"q":"Scissor reflex is seen in ?","o":["Open angle glaucoma","Phlyctenular conjunctivitis","Keratoconus","Interstitial keratitis"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4742, 'Ophthalmology', 'Optic Nerve & Neuro-ophthalmology', 'Easy', 'Ophthalmology', 187, '{"id":4742,"subject":"Ophthalmology","chapter":"Optic Nerve & Neuro-ophthalmology","difficulty":"Easy","source":"Ophthalmology","sourceNo":187,"q":"Which are first order neuron in optic pathway?","o":["Bipolar cells","Ganglionic cells","Cells of lateral geniculate body","Astrocytes"],"a":0,"e":"Ans. is ''a'' i.e., Bipolar cells In visualpathway Sensory organs →Photoreceptors (Rods & cones) Neurons of first rder -3 Axon of bipolar cells (in Retina) Neurons of second rder → Axons of ganglionic cell (Retina i.e., Optic disc,Optic nerve, Optic chiasma, optic tracts) Neurons of third order → Axons from nerve cells in lateral geniculate body (optic adiation)","pyqMatches":[{"year":"2013","no":1119,"q":"Which are first order neuron in optic pathway?","o":["Bipolar cells","Ganglionic cells","Cells of lateral geniculate body","Astrocytes"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4743, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 188, '{"id":4743,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":188,"q":"True about electroretinogram ?","o":["a'' wave is positive wave","''a'' wave arises from pigmented epithelium","b'' wave arises from rods and cones","''c'' wave is positive wave"],"a":3,"e":"Ans. is ''d'' i.e., ''c'' wave is positive wave Electroretinogram The changes induced by the stimulation of light in the resting potential of the eye are measured by electroretinography. It is extinguished or absent in complete failure of function of rods and cones, e.g. pigmentary retinal dystrophy, complete occlution of retinal artery, complete retinal detachment, advanced siderosis etc.","pyqMatches":[{"year":"2013","no":1131,"q":"True about electroretinogram ?","o":["a'' wave is positive wave","''a'' wave arises from pigmented epithelium","b'' wave arises from rods and cones","''c'' wave is positive wave"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4744, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 189, '{"id":4744,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":189,"q":"Specific for albinism","o":["Red reflex","Decreased visual activity","Photophobia","Nystagmus"],"a":0,"e":"Ans. is ''a'' i.e., Red reflex All the given options are seen in albinism. But, red reflex is specific. Ocular features in albinism - a Red reflex Pink or blue iris Dazzling glare Photophobia Decreased vision Nystagmus Clear retinal and choroidal vessels, separated by glistening white space Strabismus (mild to moderate)","pyqMatches":[{"year":"2013","no":1224,"q":"Specific for albinism","o":["Red reflex","Decreased visual activity","Photophobia","Nystagmus"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4745, 'Ophthalmology', 'Retina & Vitreous', 'Moderate', 'Ophthalmology', 190, '{"id":4745,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Moderate","source":"Ophthalmology","sourceNo":190,"q":"All are parts of anterior segment of eye except?","o":["Lens","Cornea","Vitreous","None"],"a":2,"e":"Ans. is ''c'' i.e., Vitreous The eyeball is divided into two segments : ? Anterior segment","pyqMatches":[{"year":"2013","no":1115,"q":"All are parts of anterior segment of eye except?","o":["Lens","Cornea","Vitreous","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4746, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 191, '{"id":4746,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":191,"q":"Attachement of Vitreous is Srongest at","o":["Foveal region","Back of lens","Across ora serrata","Margin of optic disc"],"a":2,"e":"Ans. is ''c'' i.e., Across ora serrata Attachement of vitreous Vitreous is attached anteriorly to the lens (Hyloid capsular ligament of Wieger) and ciliary epithelium in front of the ora serrata. The part of vitreous about 4 mm across the ora serrata is known as the \"base of vitreous\" where the attachement is strongest Posteriorly vitreous is attached to the edge of the optic disc and macula lutea (foveal region) forming ring-shaped structure around them","pyqMatches":[{"year":"2013","no":1116,"q":"Attachement of Vitreous is Srongest at","o":["Foveal region","Back of lens","Across ora serrata","Margin of optic disc"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4747, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 192, '{"id":4747,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":192,"q":"Umbrella configration on fluorescein angiogrphyis seen in ?","o":["Retinitis pigmentosa","Rheugmatous retinal detachment","Central serous retinopathy","Eale''s disease"],"a":2,"e":"Ans. is ''c'' i.e., Central serous retinopathy Central serous retinopathy Central serous retinopathy is caused by an accumulation of transparent fluid at the posterior pole especially at macula causing a circumscribed area retinal detachment in the macular region. There is detachment of neurosensory retina (layers of rods and cones) with or without retinal pigment epithelium detachment. The condition affects males between 20-40 years of age. Patient presents with a sudden onset of painless loss of vision associated with relative positive scotoma, micropsia and metamorphosia. Ophthalmoscopic findings include mild elevation of macular area demarcated by a circular ring reflex and foveal reflex is distorted or absent. The diagnosis is confirmed by fluorescein angiography. It shows focal leakage of fluorescein in following two patterns : ? Ink-blot pattern or enlarging dot sign :- A small hyperfluorescent spot which gradually increases in size. Smoke-stack pattern :- Small hyperfluorescent spot which ascends vertically like a smoke stack and gradually spreads laterally to take a mushroom or umbrella configration","pyqMatches":[{"year":"2013","no":1184,"q":"Umbrella configration on fluorescein angiogrphyis seen in ?","o":["Retinitis pigmentosa","Rheugmatous retinal detachment","Central serous retinopathy","Eale''s disease"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4748, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 193, '{"id":4748,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":193,"q":"Epithelial xerosis of conjunetiva is caused by ?","o":["Trachoma","Diphtheria","Xerophthalmia","Pemphigus"],"a":2,"e":"Ans. is ''c'' i.e., Xerophthalmia Xerosis of conjunctiva refers to a condition where the conjunctiva becomes dry and lusterless. Depending upon the etiology, conjunctival xerosis can be divided into two groups : ? Parenchymatous xerosis : - It occurs following cicatricial disorganization of conjunctiva due to local causes which can be : ?","pyqMatches":[{"year":"2013","no":1225,"q":"Epithelial xerosis of conjunetiva is caused by ?","o":["Trachoma","Diphtheria","Xerophthalmia","Pemphigus"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4749, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 194, '{"id":4749,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":194,"q":"Cicatrising trachoma is seen in ?","o":["Stage-1","Stage-2","Stage-3","Stage-4"],"a":2,"e":"Ans. is ''c'' i.e., Stage-3 McCal Ian''s classification-McCallan in 1908 divided the clinical course of trachoma into 4 stages Stage 1 (Incipient trachoma) Hyperaemia of palpebral Stage 2 (Established tracoma) Stage 3 (Cicatrising trachoma) Stage 4 (Healed trachoma) Immature follicle Appearance of mature follicle & conjunctiva papillae Scarring of palpebralconjunctiva Disease is cured or is not markable Mild superfecial punctate keratopathy Progressive corneal pannus Scars are easily visibleas white bands Necrosis Sequelae to cicatrisationcause symptoms Stage 2 is further subdivided into :- 2a (Ha) :- Presence of mature follicles b (Hb) :- Marked papillary hyperplasia","pyqMatches":[{"year":"2013","no":1137,"q":"Cicatrising trachoma is seen in ?","o":["Stage-1","Stage-2","Stage-3","Stage-4"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4750, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 195, '{"id":4750,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":195,"q":"Non-sterile hypopyon is seen in ?","o":["Pneumococcus infection","Pseudomonas infection","Fungal infection","Gonococcal infection"],"a":2,"e":"Ans. is ''c'' i.e., Fungal infection Hypopyon refers to accumulation ofpolymorphonuclear leucocytes in the lower angle of anterior chamber. Many pyogenic organisms (Staphylococcus, streptococci, gonococci, Moraxella) and fungi may produce hypopyon but by far the most dangerous are pseudomonas pyogenea and pneumococcus. Thus, any corneal ulcer may be associated with hypopyon, however, it is customary to reserve the term ''hypopyon corneal ulcer'' for the characteristic ulcer caused by pneumococcus and the term ''corneal ulcer with hypopyon'' for the ulcers associated with hypopyon due to other causes. The characteristic hypopyon corneal ulcer caused by pneumococcus is called \"ulcus serpens\" . It is worth noting that the hypopyon in bacterial causes is sterile since the outpouring of polymorphonuclear cells is due to toxin and not due to actual invasion by bacteria. On the other hand, hypopyon in fungal (mycotic) corneal ulcer is non-sterile as there is direct invasion by fungi.","pyqMatches":[{"year":"2013","no":1143,"q":"Non-sterile hypopyon is seen in ?","o":["Pneumococcus infection","Pseudomonas infection","Fungal infection","Gonococcal infection"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4751, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 196, '{"id":4751,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":196,"q":"Normal level of visual acuity is attained at which age","o":["6 months","1 year","3 years","6 years"],"a":2,"e":"Ans. is ''c'' i.e., 3 years [Ref Khurana 4th Eye in postnatal period Fixation starts developing by 4-6 weeks. Critical period for development of fixation reflex is 2-4 months. Development of fixation is completed by 6 months. So there are three points to remember : ? Fixation starts developing 4-6 weeks (1-11/2 months). Critical period for development→ 2-4 months.","pyqMatches":[{"year":"2013","no":1114,"q":"Normal level of visual acuity is attained at which age","o":["6 months","1 year","3 years","6 years"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4752, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 197, '{"id":4752,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":197,"q":"Duanne syndrome involves?","o":["Superior oblique","Inferior oblique","Lateral rectus","Superior rectus"],"a":2,"e":"Ans. is ''c'' i.e., Lateral rectus retraction syndrome represents the most frequent and most prominent congenital cranial dysinnervation disorder (CCDD). It is due to fibrosis of the lateral rectus or an innervational anomaly withCo-contraction of the lateral and medial recti. There is deficiency of abduction, associated with impaired adduction, contraction of palpebral fissure and oblique movements of the eye.","pyqMatches":[{"year":"2013","no":1200,"q":"Duanne syndrome involves?","o":["Superior oblique","Inferior oblique","Lateral rectus","Superior rectus"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4753, 'Ophthalmology', 'Retina & Vitreous', 'Moderate', 'Ophthalmology', 198, '{"id":4753,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Moderate","source":"Ophthalmology","sourceNo":198,"q":"Birdshot retinopathy is characterized by all except?","o":["Common in females","Unilateral","HLA-A29 positive","Creamy yellow spots"],"a":1,"e":"Ans. is ''b'' i.e., Unilateral Bird-shot retinochoroidopathy It is a rare, idiopathic, bilaterally symmetrical chronic multifocal chorioretinitis characterised by numerous flat creamy-yellow spots due to focal chorioretinal hypopigmentation, resembling the pattern of \"bird-short scatter from a shotgun\". The disease, more common in females than males, typically affects middle-aged healthy persons who are positive for HLA-A29. It runs a long chronic course of several years. Treatment with corticosteroids is usually not effective","pyqMatches":[{"year":"2013","no":1186,"q":"Birdshot retinopathy is characterized by all except?","o":["Common in females","Unilateral","HLA-A29 positive","Creamy yellow spots"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4754, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 199, '{"id":4754,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":199,"q":"Treatment of choice for anisoeikonia ?","o":["Orthoptic exercise","Spectacles","Surgery","Contact lens"],"a":3,"e":"Ans. is ''d'' i.e., Contact lens Anisoeikonia Anisoeikonia is defined as a condition wherein the images projected on the visual cortex from the two retinae are abnormally unequal in size or shape. Causes may be Optical aniseikonia : - When the difference between refractive error of two eyes is of high degree, the image of an object may be of different size or shape in two eyes. So the defect is at refractive structures level. Retinal aniseikonia : - Defect is at retinal level and occurs due to displacement of retinal elements towards the nodal point in one eye due to stretching or edema of the retina. Cortical aniseikonia : - Defect is at higher central level. There is asymmetrical simultaneous perception inspite of equal size of images formed on the two retinae. Up to 5 percent aniseikonia is well tolerated. For high degree of aniseikonia, treatment of choice is contact lenses.","pyqMatches":[{"year":"2013","no":1120,"q":"Treatment of choice for anisoeikonia ?","o":["Orthoptic exercise","Spectacles","Surgery","Contact lens"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4755, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 200, '{"id":4755,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":200,"q":"Maximum correction of myopia can be done by ?","o":["Radial keratotomy","LASIK","Photorefractive keratotomy","Orthokeratology"],"a":1,"e":"Ans. is ''b'' i.e., LASIK Amongst the given options, maximum correction can be achieved by LASIK. Surgical ocedure Myopia orrection Radial keratomy -2 to -6 D Photorefractive keratotomy -2 to -6 D LASIK Upto -12D Extraction of lens -16 to -18 D Phakic IOL > -12 D Interconaeal ring (ICR 1-6 D Orthokeratology upto - 5D","pyqMatches":[{"year":"2013","no":1122,"q":"Maximum correction of myopia can be done by ?","o":["Radial keratotomy","LASIK","Photorefractive keratotomy","Orthokeratology"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4756, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 201, '{"id":4756,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":201,"q":"Marcus Gunn pupil is due to ?","o":["Total afferent pupillary defect","Relative afferent pupillary defect","Efferent pathway defect","Cerebral lesion"],"a":1,"e":"Ans. is ''b'' i.e., Relative afferent papillary defect Marcus Gunn pupil Marcus Gunn pupil is seen in relative afferent pathway defect (RAPD) An incomplete optic nerve lesion or retinal disease cause it (in contrast to amaurotic light reflex, where there is total afferent pathway defect). It is best tested by swinging flash light test. To perform this test, a bright flash light is shone to one pupil and constriction of that pupil is noted. Then the flashlight is quickly moved to the contralateral pupil and the response in that pupil is noted. This swinging to and fro of the flashlight is repeated several times while the pupillary response is observed. Normally, both pupils constrict equally and the pupil to whom light is transferred remains tightly constricted. In the presence of relative afferent pupillary defect in one eye, both the pupil will dilate when the flash light is moved from the normal to the abnormal eye. This is a paradoxical resposne. This is called Marcus Gunn pupil and is the earliest indicator of optic nerve disease even in the presence of a normal visual acuity. Relative afferent papillary defect (RAPD) or Marcus Gunn pupil is a reliable and objectve sign of unilateral or assymmetric disease or any lesion in afferent papillary pathway, i.e., retina, optic nerve, optic chiasma, optic tract or midbrain (pretectal nucleus). However, RAPD is most characteristic of lesions in the optic nerve.","pyqMatches":[{"year":"2013","no":1191,"q":"Marcus Gunn pupil is due to ?","o":["Total afferent pupillary defect","Relative afferent pupillary defect","Efferent pathway defect","Cerebral lesion"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4757, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 202, '{"id":4757,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":202,"q":"Distance of medial rectus from limbus -","o":["4.5 mm","5.5 mm","7.0 mm","10 mm"],"a":1,"e":"Ans. is ''b'' i.e., 5.5 mm Muscle Distance of insertion from limbus Medial rectus 5.5 mm Inferior ectus 6.5 mm Lateral rectus 6.9 mm Superior ectus7.7 mm","pyqMatches":[{"year":"2013","no":1199,"q":"Distance of medial rectus from limbus","o":["4.5 mm","5.5 mm","7.0 mm","10 mm"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4758, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Moderate', 'Ophthalmology', 203, '{"id":4758,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Moderate","source":"Ophthalmology","sourceNo":203,"q":"All nerve are involved in superior orbital fissuresyndrome except ?","o":["1t","3rd","4''h","6th"],"a":0,"e":"Ans. is''a'' i.e., 1\" Superior orbital fissure syndrome The superior orbital fissure is a cleft between the lesser and greater wing of sphenoid. The structures passed through superior orbital fissure are 3rd,4th,6rn nerve, ophthalmic division of Sth nerve, superior & inferior division of ophthalmic vein and sympathetic fibres. Therefore symptoms of superior orbital fissure syndrome are same as in cavernous sinus thrombosis, i.e., painful ophthalmoplegia :- Pain (retro-orbital pain) and sensory disturbances in the V1(ophthalmic division of 5th nerve)distribution Ipsilateral ophthalmoplegia Ord 4th and 6th nerve involvement).","pyqMatches":[{"year":"2013","no":1226,"q":"All nerve are involved in superior orbital fissuresyndrome except ?","o":["1t","3rd","4''h","6th"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4759, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 204, '{"id":4759,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":204,"q":"Posterior lenticonus is seen in ?","o":["Alport''s syndrome","Lowe''s syndrome","Marfan syndrome","Homocystinuria"],"a":1,"e":"Ans. is ''b'' i.e., Lowe''s syndrome Lenticonus refers to cone-shaped elevation of the anterior pole (anterior lenticonus) or posterior pole (posterior lenticonus) of the lens. Anterior lenticonus is seen in Alport''s syndrome. Posterior lenticonus is seen in Lowe''s syndrome. On distant direct ophthalmoscopy, lenticonus present as an oil globule lying in the center of red reflex. Slit-lamp examination confirms the diagnosis.","pyqMatches":[{"year":"2013","no":1166,"q":"Posterior lenticonus is seen in ?","o":["Alport''s syndrome","Lowe''s syndrome","Marfan syndrome","Homocystinuria"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4760, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 205, '{"id":4760,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":205,"q":"Thickest portion of sclera is ?","o":["Anterior to rectus muscle insertion","Posterior to rectus muscle insertion","Posterior pole","Limbus"],"a":2,"e":"Ans. is ''c'' i.e., Posterior pole o The thickness of the sclera varies according to location : ? At the limbus, the sclera is 0.8 mm thick. Anterior to the rectus muscle insertions, it is 0.6 mm thick. Posterior to the rectus muscle insertions, it is 0.3 mm thick (Thinnest portion). At the equator, it is 0.5 to 0.8 mm thick. At the posterior pole, it is greatest than 1 mm thick.","pyqMatches":[{"year":"2013","no":1153,"q":"Thickest portion of sclera is ?","o":["Anterior to rectus muscle insertion","Posterior to rectus muscle insertion","Posterior pole","Limbus"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4761, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 206, '{"id":4761,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":206,"q":"Reis-Buckler dystrophy affects which layer of cornea","o":["Epithelium","Stroma","Bowman''s membrane","Endothelium"],"a":2,"e":"Ans. is ''c'' i.e., Bowman''s membrane","pyqMatches":[{"year":"2013","no":1148,"q":"Reis-Buckler dystrophy affects which layer of cornea","o":["Epithelium","Stroma","Bowman''s membrane","Endothelium"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4762, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 207, '{"id":4762,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":207,"q":"Down-beat nystagmus is seen in lesion of ?","o":["Brainstem","Cerebellum","Basal ganglia","Hippocampus"],"a":1,"e":"Ans. is ''b'' i.e., Cerebellum Central vestibular nystagmus may be of following types ? Up-beat nystagmus In primary position of gaze, the fast component is upward. It is seen in lesions of central tegmentum of brain-stem. Down-beat nystagmus In primary position of gaze, the fast component is downward. It is usually associated with posterior fossa disease and is typical of compression at the level of foramen magnum. It is a common feature of cerebellar lesions and Arnold-chiary syndrome. Periodic alternative nystagms It is a jerk nystagmus which shows fluctuations in amplitude and direction. It may occur due to vascular or demyelinating vascular or brainstem-cerebellar lesions.","pyqMatches":[{"year":"2013","no":1201,"q":"Down-beat nystagmus is seen in lesion of ?","o":["Brainstem","Cerebellum","Basal ganglia","Hippocampus"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4763, 'Ophthalmology', 'Miscellaneous', 'Moderate', 'Ophthalmology', 208, '{"id":4763,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Ophthalmology","sourceNo":208,"q":"Von Herick angle grade ''3'' of anterior chamber denotes","o":["Wide open angle","Moderately open angle","Moderately narrow angle","Closed angle"],"a":1,"e":"Ans. is ''b'' i.e., Moderately open angle","pyqMatches":[{"year":"2013","no":1170,"q":"Von Herick angle grade ''3'' of anterior chamber denotes","o":["Wide open angle","Moderately open angle","Moderately narrow angle","Closed angle"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4764, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 209, '{"id":4764,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":209,"q":"Foldable lens is made up of?","o":["PMMA","Silicon","Hydrogel","None"],"a":1,"e":"Ans. is ''b'' i.e., Silicon Depending on the material of manufacturing, following types of IOLs are there :- Rigid IOLs :- Made entirely from polymethyl methacrylate (PMMA). Foldable 10Ls :- Are used after phacoemulsification and are made of silicon, acrylic, hydrogel and collamer. Rollable 10Ls :- Ultra thin IOLs and are sued after phokonit technique (micro- incision : lmm). These are made of hydrogel.","pyqMatches":[{"year":"2013","no":1169,"q":"Foldable lens is made up of?","o":["PMMA","Silicon","Hydrogel","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4765, 'Ophthalmology', 'Optic Nerve & Neuro-ophthalmology', 'Easy', 'Ophthalmology', 210, '{"id":4765,"subject":"Ophthalmology","chapter":"Optic Nerve & Neuro-ophthalmology","difficulty":"Easy","source":"Ophthalmology","sourceNo":210,"q":"Arcuate field defect akin to glaucoma is seen in?","o":["Pituitary tumor","Occipital lobe infarct","Optic nerve lesion","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., Optic nerve lesion An arcuate visual field defect usually results from damage to retinal nerve fibers or ganglion cells in the superior or inferior arcuate nerve fiber bundles. In such cases there is a central field defect that is not circular but instead is limited above or below by the horizontal meridian. This visual field defect may occur in patients with occlusion of blood supply of the superior or inferior portion of macula or in patients with glaucoma. In both settings, the scotoma is associated with normal visual acuity, since it does not completely affect the macula. Virtually any lesion, whether ischemic, infiltrative or compressive, can cause arcute field defect, and may be located in either the retina or optic nerve. Important causes of arcuate scotoma are :-","pyqMatches":[{"year":"2013","no":1132,"q":"Arcuate field defect akin to glaucoma is seen in?","o":["Pituitary tumor","Occipital lobe infarct","Optic nerve lesion","None of the above"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4766, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 211, '{"id":4766,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":211,"q":"Thinnest portion of sclera ?","o":["Anterior to rectus muscle insertion","Posterior to rectus muscle insertion","Posterior pole","Limbus"],"a":1,"e":"Ans. is.b, Posterior to rectus muscle insertion Thinnest portion of sclera→ Posterior to insertions of rectus muscle. Thickest portion of sclera→ Posterior pole.","pyqMatches":[{"year":"2013","no":1154,"q":"Thinnest portion of sclera ?","o":["Anterior to rectus muscle insertion","Posterior to rectus muscle insertion","Posterior pole","Limbus"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4767, 'Ophthalmology', 'Refraction & Optics', 'Easy', 'Ophthalmology', 212, '{"id":4767,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Easy","source":"Ophthalmology","sourceNo":212,"q":"During retinoscopy of a 30 years old male, which cycloplegic is used routinely","o":["Atropine 1% ointment","Cyclopentolate 1% drop","Homatropine 2% drop","None of the above"],"a":3,"e":"Ans. is ''d'' i.e., None of the above There is no need for cycloplegia as a routine in adults (20-40 years). Cvcloplegic in retinoscopy Cycloplegics are drugs which cause paralysis of ciliary muscles (accommodation) and dilatation of pupil. Theuse of cycloplegics is useful in refraction and there are certain situations where they are indicated. Because of their strong accommodative reserve, very young people (< 16 years) should always be refracted after the use of cyclopleagics : -","pyqMatches":[{"year":"2013","no":1128,"q":"During retinoscopy of a 30 years old male, which cycloplegic is used routinely","o":["Atropine 1% ointment","Cyclopentolate 1% drop","Homatropine 2% drop","None of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4768, 'Ophthalmology', 'Refraction & Optics', 'Easy', 'Ophthalmology', 213, '{"id":4768,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Easy","source":"Ophthalmology","sourceNo":213,"q":"In senile nuclear cataract what type of myopia is seen?","o":["Curvature myopia","Index myopia","Axial myopia","Positional myopia"],"a":1,"e":"Ans. is ''b'' i.e., Index myopia Nuclear changes of aging induce a modification of refractive index of lens and produce an index myopia. \"Nuclear cataracts cause a general decrease in the transperancy of the lens nucleus.They are associated withindexmyopia\" Ophthalmic study guide Causes of errors of refraction Possible causes of ametropia are : ? 1) Axial It is the commonest form of ametropia (both myopia and hypermetropia). In hypermetropia, there is an axial shortening of eyeball. So, image is formed behind the retina. In myopia, there is an axial lengthening of eyeball. So, image is formed in front of the retina. 1 mm change in axial length leads to ametropia of 3D. For example 1 mm shortening in axial length causes hypermetropia of 3D. 2) Curvature Change in the curvature of cornea or lens will cause ametropia. In hypermetropia, the curvature of cornea or lens is lesser than normal. In myopia, there is increase in curvature of cornea or lens./ mm change in corneal curvature leads to 6-7 D ametropia. 3) Index If refractive index of optical system is low, it will result in hypermetropia and high refractive index will result in myopia. 4) Positional (Due to relative position of the lens), A forward shift of lens causes myopia, backward shift result in hypermetropia. Absence of lens (aphakia) causes hypermetropia. 5) Excessive accommodation Excessive accommodation due to spasm of accommodation causes myopia.","pyqMatches":[{"year":"2013","no":1162,"q":"In senile nuclear cataract what type of myopia is seen?","o":["Curvature myopia","Index myopia","Axial myopia","Positional myopia"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4769, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 214, '{"id":4769,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":214,"q":"Panophthalmitis involves ?","o":["Inner coat of eyeball","Inner and outer coat but sparing tenon''s capsule","All structure of eyeball including tenon''s capsule","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., All structure of eyeball including tenon''s capsule Endophthahnitis Endophthalmitis is defined as inflammation within the anterior segment (aqueous) or post​erior segment (vitreous) or both together with partial thickness involvement of the adjacent occular wall (one or more inner coats of the eye) Inflammation characteristically involves the the inner structures of the eye ball Le., uveal tissue (iris/ciliary body/ choroid) and Retina (Sclera is spared). Panophthalmitis Panopthalmitis is defined as inflammation within the anterior (aqueous) segment and'' or posterior (vitreous) segment together with inflammation of all three coats of the eye. Panophthalmitis often starts as an endophthalmitis that then involves the sclera, tenon''s capsule and may also involve the orbital tissue.","pyqMatches":[{"year":"2013","no":1160,"q":"Panophthalmitis involves ?","o":["Inner coat of eyeball","Inner and outer coat but sparing tenon''s capsule","All structure of eyeball including tenon''s capsule","None of the above"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4770, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 215, '{"id":4770,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":215,"q":"Cataract is caused by ?","o":["Hypoparathyroidism","Cigrate smoking","Non-ionizing radiation","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above","pyqMatches":[{"year":"2013","no":1163,"q":"Cataract is caused by ?","o":["Hypoparathyroidism","Cigrate smoking","Non-ionizing radiation","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"},{"year":"2015","no":1023,"q":"Cataract is caused by ?","o":["Hypoparathyroidism","Cigrate smoking","Non-ionizing radiation","All of the above"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2013","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4771, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 216, '{"id":4771,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":216,"q":"Ameboid ulcer is a feature of","o":["Parasitic corneal ulcer","Mycotic corneal ulcer","Herpetic corneal ulcer","Bacterial corneal ulcer"],"a":2,"e":"Ans. is c i.e., Herpetic corneal ulcer Herpetic Keratitis Most of the ocular infection are caused by HSV-1 except in neonates where eye infection can be caused by HSV​2 through infected genitalia of mother. Ocular involvement by HSV may occur in two forms : - Primary herpes : - Typically is a unilateral blepharoconjunctivitis which is characterized by vesicles on the skin of lids, follicular conjunctivitis, preauriculars adenopathy and sometimes punctate keratitis. Recurrent ocular herpes : - After primary infection, recurrent disease may involve any or all layers of the cornea. Recurrent herpatic keratitis is divided into : ? 1) Epithelial keratitis : - Manifestations of epithelial keratitis include : -","pyqMatches":[{"year":"2013","no":1144,"q":"Ameboid ulcer is a feature of","o":["Parasitic corneal ulcer","Mycotic corneal ulcer","Herpetic corneal ulcer","Bacterial corneal ulcer"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4772, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 217, '{"id":4772,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":217,"q":"Most common site of distant metastasis inintraorbital malignant melanoma is?","o":["Brain","Lung","Liver","Lymph nodes"],"a":2,"e":"Ans. is `c i.e., Liver Malignant melanoma mostly arise in uvea and uveal malignant melanoma is the most common primary intraocular tumor. The most common site for distant metastasis of uveal melanoma is liver. The liver is the most common site of metastasis of uveal melanoma\" — Clinical oncology The liver is the most common site of metastatis from primary ocular melanoma\" — Smith & Nesi''s Uveal melanoma Uveal melanoma is the most common primary intraocular tumor in adults. Most of the (85%) uveal melanomas arise in the choroid. So, choroidal melanoma is the most common primary intraocular tumor in adults. Tumor arises from dendritic melanocytes (neural crest, neuroectodermal origin). Histologically choroidal melanoma can be divided into: - Spindle cell melanomas : - These melanomas contain predominantly spindle cells. These melanomas are further subdivided into Spindle A or Spindle B depending upon the type of cells. Epitheloid cell melanomas : - Contain epitheloid like cells. Mixed cell melanomas : - Contain both spindle cells and epitheloid cells. Choroidal melanoma presents as a sessile or dome shaped mass located deep to the sensory retina. A secondary non-rheugmatogenous retinal detachment frequently occurs. Involvement of vortex vein by tumor results in glaucoma. With continued growth, a choroidal melanoma can rupture Bruch''s membane and assume a mushroom shape. When that occurs, tumor has a tendency to bleed, and vitreal or subretinal hemorrhage may occur.","pyqMatches":[{"year":"2013","no":1205,"q":"Most common site of distant metastasis inintraorbital malignant melanoma is?","o":["Brain","Lung","Liver","Lymph nodes"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4773, 'Ophthalmology', 'Refraction & Optics', 'Easy', 'Ophthalmology', 218, '{"id":4773,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Easy","source":"Ophthalmology","sourceNo":218,"q":"Shortening of 2 mm of axial length of eye ball causes ?","o":["3D myopia","6D myopia","3D hypermetropia","6D hypermetropia"],"a":3,"e":"Ans. is. d., 6D hypermetropia Change in axial length can cause refractive error. It is the commonest form of ametropia (both myopia and hypermetropia). In hypermetropia, there is an axial shortening of eyeball. So, image is formed behind the retina. In myopia, there is an axial lengthening of eyeball. So, image is formed in front of the retina. 1 mm change in axial length leads to ametropia of 3D. For example 1 mm shortening in axial length causes hypermetropia of 3D.","pyqMatches":[{"year":"2013","no":1121,"q":"Shortening of 2 mm of axial length of eye ball causes ?","o":["3D myopia","6D myopia","3D hypermetropia","6D hypermetropia"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4774, 'Ophthalmology', 'Uvea', 'Easy', 'Ophthalmology', 219, '{"id":4774,"subject":"Ophthalmology","chapter":"Uvea","difficulty":"Easy","source":"Ophthalmology","sourceNo":219,"q":"Drug of choice for intermediate uveitis ?","o":["Atropine","Antibiotics","Topical steroids","Systemic steroid"],"a":3,"e":"Ans. is ''d'' i.e., Systemic steroids Drugs used in acute anterior uveitis (iridocyclitis) Topical steroids (Drugs of choice) Mydriatic - cycloplegics: Atropine (Drug of 2\" choice), Homatropine, cyclopentolate, tropicamide, rnydricain (mixture of atropine, adrenaline & procaine) Systemic steroids NSAIDs Systemic immunosuppressives cyclosporine, methotrexate, cyclophosphamide Intermediate uveitis Systemic steroids are the drug of choice Posterior uveitis (choroiditis) Systemic steroids are the drug of choice","pyqMatches":[{"year":"2013","no":1156,"q":"Drug of choice for intermediate uveitis ?","o":["Atropine","Antibiotics","Topical steroids","Systemic steroid"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4775, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 220, '{"id":4775,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":220,"q":"Inverted image in Purkinje test is formed from ?","o":["Anterior surface of cornea","Posterior surface of c","Anterior surface of lens","Posterior surface of lens"],"a":3,"e":"Ans. is ''d'' i.e., Posterior surface of lens Purkinje images test Normally, when a strong beam of light is shown to the eye, four images (Purkinje images) are formed from the four different reflecting surfaces :- 1\" from anterior surface of cornea → Erect and moves in same direction. 2nd from posterior surface of cornea → Erect and moves in same direction. 3''d from anterior surface of lens → Erect and move in same direction. 4th from posterior surface of lens → Inverted and moves in opposite direction First three reflecting surfaces are convex and produce erect images, while 4th surface is concave, therefore produces inverted image. Presence of all four images indicates presence of a clear lens. In aphakia 3rd & 4th images are absent and only first two images are present. In cataract 4th image is absent and first 3 images are present.","pyqMatches":[{"year":"2013","no":1134,"q":"Inverted image in Purkinje test is formed from ?","o":["Anterior surface of cornea","Posterior surface of c","Anterior surface of lens","Posterior surface of lens"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4776, 'Ophthalmology', 'Ocular Motility & Strabismus', 'Easy', 'Ophthalmology', 221, '{"id":4776,"subject":"Ophthalmology","chapter":"Ocular Motility & Strabismus","difficulty":"Easy","source":"Ophthalmology","sourceNo":221,"q":"Forced duction test is to find out?","o":["Ocular muscle palsy","Ocular muscle spasm","Angle of deviation","Refractive error"],"a":0,"e":"Ans. is ''a'' i.e., Ocular muscle palsy Forced duction test It is performed to differentiate between the incomitant squint due to paralysis of extraocular muscle and that due to mechanical restriction of the ocular movements. FDT is positive (resistance encountered during passive rotation) in cases of incomitant squint due to mechanical restriction and negative in cases of extraocular muscle palsy.","pyqMatches":[{"year":"2013","no":1203,"q":"Forced duction test is to find out?","o":["Ocular muscle palsy","Ocular muscle spasm","Angle of deviation","Refractive error"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4777, 'Ophthalmology', 'Uvea', 'Easy', 'Ophthalmology', 222, '{"id":4777,"subject":"Ophthalmology","chapter":"Uvea","difficulty":"Easy","source":"Ophthalmology","sourceNo":222,"q":"Red keratic precipitates are seen in ?","o":["Granulomatous uveits","Hemorrhagic uveitis","Old healed uveitis","Acute anterior uveitis"],"a":1,"e":"Ans. is .b i.e., Hemorrhagic uveitis Keratic precipitates (KPs) KPs are proteinaceous cellular deposits occurring at the back of cornea (corneal endothelial deposits). Keratic precipitates are formed by the aggregation of polymorphonuclear cells, lymphocytes, and epitheloid cells. In the setting of uveitis, the bimicrosopic appearance of KP may yeild important diagnostic clues for the identification of the underlying inflammatory disorder :? Mutton fat KP :- Large, yellowish KPs, are characteristic ofgranulomatous uveitis. These are composed of epitheloid cells and macrophages. They are large, thick fluffy, lardaceous KPs, having a greasy or waxy appearance. Small or medium KPs (granular KPs):- These are composed of lymphocytes and are characteristic of non- granulomatous uveitis. These are small, round and whitish precipitates Red KPs :- Composed of RBCs and inflammatory cells. These are seen in hemorrhagic uveitis. Old KPs :- In healed uveitis. The above described KPs shrink, fade, become pigmented and irregular in shape with crenated margins.","pyqMatches":[{"year":"2013","no":1157,"q":"Red keratic precipitates are seen in ?","o":["Granulomatous uveits","Hemorrhagic uveitis","Old healed uveitis","Acute anterior uveitis"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2015","no":1020,"q":"Red keratic precipitates are seen in ?","o":["Granulomatous uveits","Hemorrhagic uveitis","Old healed uveitis","Acute anterior uveitis"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2013","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4778, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Easy', 'Ophthalmology', 223, '{"id":4778,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Easy","source":"Ophthalmology","sourceNo":223,"q":"Hardoleum internum is ?","o":["Acute infection of Zeis gland","Acute infection of Moll gland","Acute infection Meibomian gland","Chronic infection of Zeis gland"],"a":2,"e":". Ans. is ''c'' i.e., Acute infection Meibomian gland Acute infection of Zeis (Moll) gland → Stye (Hardoleum externum). Acute infection of tarsal gland (Meibomian gland) → Hardoleum internum o Chronic infection of tarsal gland (Meihonium gland) → Chalazion Differences between stye (Hordeolum externum), chalazion and Hordeolum internum Stye (Hordeolum externum) Chalazion Hordeolum internum Onset Acute Chronic Acute Gland Zeis''s gland Meibomian gland Meibomian gland Types of inflammation Suppurative LipogranulomatousSuppurative Symptoms Acute pain and swelling Painless disfigurement Severe pain Signs Localized, hard and tender Hard nontender swelling Yellow point seen on swelling near the lid margin away from lid margin everting the lid Treatment Hot fomentation, Antibiotics Drainage by incision Incision and drainage t b ot cs c s o d a age and removal of eye lash and curettage Intralesional steroid Diathermy, antibiotic Antibiotics and analgesic","pyqMatches":[{"year":"2013","no":1211,"q":"Hardoleum internum is ?","o":["Acute infection of Zeis gland","Acute infection of Moll gland","Acute infection Meibomian gland","Chronic infection of Zeis gland"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4779, 'Ophthalmology', 'Uvea', 'Easy', 'Ophthalmology', 224, '{"id":4779,"subject":"Ophthalmology","chapter":"Uvea","difficulty":"Easy","source":"Ophthalmology","sourceNo":224,"q":"Snow banking is seen in?","o":["White coats disease","Eales disease","Diabetic nephropathy","Intermediate uveitis"],"a":3,"e":"Ans. is d i.e., Intermediate uveitis Pars planitis (Intermediate uveitis) denotes the inflammation of pars plana part of ciliary body and most peripheral part of the retina. Most common symptom is floaters; defective vision may also occur. Fundus examination in pars planitis reveals whitish exudates present near the ora serrata in the inferior quadrant. These typical exudates are referred as snow ball opacities. These may coalesce to form a grey white pique called snow banking.","pyqMatches":[{"year":"2013","no":1158,"q":"Snow banking is seen in?","o":["White coats disease","Eales disease","Diabetic nephropathy","Intermediate uveitis"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4780, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 225, '{"id":4780,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":225,"q":"Retrobulbar injection is given in","o":["Inside muscle cone","Outside muscle cone","Subtenon space","Subperiosteum"],"a":0,"e":"Ans. is ''a'' i.e., Inside muscle cone Retrobulbar injection :- Injection in retrobulbar space inside the muscle cone. Peribulbar injection :- Injection in peribulbar/retrobulbar space outside the muscle cone. Sub-Tenon injection :- Injection beneath the tenon capule, i.e. in subtenon space. It is also called parabulbar block.","pyqMatches":[{"year":"2013","no":1218,"q":"Retrobulbar injection is given in","o":["Inside muscle cone","Outside muscle cone","Subtenon space","Subperiosteum"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4781, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Easy', 'Ophthalmology', 226, '{"id":4781,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Easy","source":"Ophthalmology","sourceNo":226,"q":"Basal cell carcinoma is seen in most commonlyin which eyelid?","o":["Upper medial","Upper lateral","Lower medial","Lower lateral"],"a":2,"e":"Ans. is ''c'' i.e., Lower medial Basal cell carcinoma is the commonest malignant tumor of the lids (90%) usually seen in elderly people. It is locally malignant and involves most commonly lower lid (50%) followed by medial canthus (25%), upper lid (10-15%) and outer canthus. \"Basal cell carcinoma is seen in the lower lid near the inner canthus usually\" Renu Jogi","pyqMatches":[{"year":"2013","no":1207,"q":"Basal cell carcinoma is seen in most commonlyin which eyelid?","o":["Upper medial","Upper lateral","Lower medial","Lower lateral"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4782, 'Ophthalmology', 'Glaucoma', 'Moderate', 'Ophthalmology', 227, '{"id":4782,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Moderate","source":"Ophthalmology","sourceNo":227,"q":"All are ophthalmological emergencies except ?","o":["CRAO","CRVO","Acute congestive glaucoma","Endophthalmitis"],"a":1,"e":"Ans. is ''b'' i.e., CRVO Ocular emergencies include those conditions that result in acute, severe pain in association with sudden vision loss, or that may lead to vision loss if left untreated; and traumatic conditions that affect globe or adnexa. Comon ophthalmic emergencies are :-","pyqMatches":[{"year":"2013","no":1219,"q":"All are ophthalmological emergencies except ?","o":["CRAO","CRVO","Acute congestive glaucoma","Endophthalmitis"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4783, 'Ophthalmology', 'Retina & Vitreous', 'Hard', 'Ophthalmology', 228, '{"id":4783,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Hard","source":"Ophthalmology","sourceNo":228,"q":"Diagnosis of all is made by fluorescein angiographyexcept?","o":["Diabetes retinopathy","Hypertensive retinopathy","Central serous retinopathy","Choroidal neovascularization"],"a":1,"e":"Ans. is ''b'' i.e., Hypertensive retinopathy","pyqMatches":[{"year":"2013","no":1127,"q":"Diagnosis of all is made by fluorescein angiographyexcept?","o":["Diabetes retinopathy","Hypertensive retinopathy","Central serous retinopathy","Choroidal neovascularization"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4784, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Easy', 'Ophthalmology', 229, '{"id":4784,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Easy","source":"Ophthalmology","sourceNo":229,"q":"Lacrimal punctum of upper and lower eyelids are?","o":["They are opposed","No relation","Upper punctum is medial","Upper punctum is lateral"],"a":0,"e":"Ans. is ''a'' i.e., They are opposed","pyqMatches":[{"year":"2013","no":98,"q":"Lacrimal punctum of upper and lower eyelids are?","o":["They are opposed","No relation","Upper punctum is medial","Upper punctum is lateral"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4785, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 230, '{"id":4785,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":230,"q":"Down beat nystagmus is seen in?","o":["Arnold chiari malformation","Brain stem damage","Pontine hemorrhage","Labyrinthine damage"],"a":0,"e":"Ans. is ''a'' i.e., Arnold chiari malformation Down-beat nystagmus are seen in cerebellar lesion and Arnold- chiary malformation","pyqMatches":[{"year":"2013","no":1202,"q":"Down beat nystagmus is seen in?","o":["Arnold chiari malformation","Brain stem damage","Pontine hemorrhage","Labyrinthine damage"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4786, 'Ophthalmology', 'Glaucoma', 'Moderate', 'Ophthalmology', 231, '{"id":4786,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Moderate","source":"Ophthalmology","sourceNo":231,"q":"Not true about Fuch''s corneal dystrophy ?","o":["Posterior dystrophy","Endothelial dystrophy","Unilateral condition","Occurs in old age"],"a":2,"e":"Ans. is ''c'' i.e., Unilateral condition Corneal dystrophies are bilateral. Fuch''s epithelial endothelial dystrophy Fuchs dystrophy is frequently seen as a slowly progressive bilateral condition affecting females more than males, usually between fifth and seventh decade of life. Primary open angle glaucoma is its common association. Clinical features can be divided into following four stages :?","pyqMatches":[{"year":"2013","no":1149,"q":"Not true about Fuch''s corneal dystrophy ?","o":["Posterior dystrophy","Endothelial dystrophy","Unilateral condition","Occurs in old age"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4787, 'Ophthalmology', 'Ocular Motility & Strabismus', 'Easy', 'Ophthalmology', 232, '{"id":4787,"subject":"Ophthalmology","chapter":"Ocular Motility & Strabismus","difficulty":"Easy","source":"Ophthalmology","sourceNo":232,"q":"Positive forced duction test is seen in ?","o":["Extraocular muscle palsy","Mechanical restriction of ocular movement","Concomitant squint","None"],"a":1,"e":"Ans. is ''b'' i.e., Mechanical restriction of ocular movement forced duction test : Resistance encountered during passive rotation and is seen in incomitant squint due to mechanical restriction. Negative forced duction test :No resistance during passive rotation and is seen in extraocular muscle palsy","pyqMatches":[{"year":"2013","no":1204,"q":"Positive forced duction test is seen in ?","o":["Extraocular muscle palsy","Mechanical restriction of ocular movement","Concomitant squint","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4788, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 233, '{"id":4788,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":233,"q":"Immune ring is a feature of ?","o":["Interstitial keratitis","Fungal corneal ulcer","Bacterial corneal ulcer","Herpes simplex keratitis"],"a":1,"e":"Ans. is ''b'' i.e., Fungal corneal ulcer Clinical features of fungal (mycotic) corneal ulcer Symptoms are similar to bacterial corneal ulcers but in general they are less marked than the equal sized bacterial ulcer. On the other hand signs are very prominent, i.e. signs are more prominent than symptoms. Following signs can be seen : -","pyqMatches":[{"year":"2013","no":1147,"q":"Immune ring is a feature of ?","o":["Interstitial keratitis","Fungal corneal ulcer","Bacterial corneal ulcer","Herpes simplex keratitis"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4789, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 234, '{"id":4789,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":234,"q":"In specular microscopy endothelial density is measured by?","o":["Optical doubling","Fixed frame analysis","Optical focusing","None"],"a":1,"e":"Ans. is ''b'' i.e., Fixed frame analysis Endothelial cell density in specular microscopy is counted by fixed frame analysis and variable frame analysis. Cell density (ceIlsimrn2 ) = Cell count in frame","pyqMatches":[{"year":"2013","no":1129,"q":"In specular microscopy endothelial density is measured by?","o":["Optical doubling","Fixed frame analysis","Optical focusing","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4790, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 235, '{"id":4790,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":235,"q":"Most common type of scleritis ?","o":["Non-necrotizing","Necrotizing","Posterior","None"],"a":0,"e":"Ans. is ''a'' i.e., Non-necrotizing SCLERITIS Scleritis refers to a chronic inflammation of the sclera proper. It is a comparatively serious disease which may cause visual impairment and even loss of the eye if treated inadequately. It usually occurs in elderly patients (40-70 years) involving females more than the males. Classification: I. Anterior scleritis (98%)","pyqMatches":[{"year":"2013","no":1155,"q":"Most common type of scleritis ?","o":["Non-necrotizing","Necrotizing","Posterior","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4791, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 236, '{"id":4791,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":236,"q":"Which of the following indicates activity of anterior uveitis?","o":["Cells in anterior chamber","Circumcorneal congestion","Keratic precipitate","Corneal edema"],"a":0,"e":"Ans. is ''a'' i.e., Cells in anterior chamber Activity of acute anterior uveitis is indicated by presence of cells (aquous cells) and flare in anterior chamber→Grading is done on these two. Grade Aquous cells Grade Aquous flare 0 cells 0no flare +_ 1-5 cells +1Just detectable +1 6-10 cells +2Moderate flare +2 11-20 cells +3Marked flare +3 21-50 cells +4Intense flare +4 > 50 cells","pyqMatches":[{"year":"2013","no":1159,"q":"Which of the following indicates activity of anterior uveitis?","o":["Cells in anterior chamber","Circumcorneal congestion","Keratic precipitate","Corneal edema"],"a":0,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":1171,"q":"Which of the following indicates activity of anterior uveitis?","o":["Cells in anterior chamber","Circumcorneal congestion","Keratic precipitate","Corneal edema"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4792, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 237, '{"id":4792,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":237,"q":"Normal aqueous production rate -","o":["2 ml/min","5 ml/min","2 1/min","5 1/min"],"a":2,"e":"Ans. is ''c'' i.e., 2 l/min The ciliary processes are the site of aqueous production. The aqueous humor is primarily derived from the plasma within the capillary network of the ciliary process. Three mechanisms play a part in aqueous formation at different levels :- (i) Active secretion (70%), (ii) ultrafiltration (20%), (iii) Diffusion / osmosis (10%). Active secretion occurs by the help ofNa+ IC AT Pase system and bicarbonate system mediated by carbonic anhydrase (convert CO2 & H20 into carbonic acid). The normal aqueous production is 2.3 micro lit/min.Total volume of aqueous is about 0.31 ml (0.25m1 in anterior chamber and about 0.06 ml in the posterior chamber). As it is derived from plasma it has similar constituents as plasma, but at different concentrations :- i) Constituents having concentration less than plasma :- Protein Nat, IC+, Ca'', Mg'', Urea,glucose. ii) Constituents having concentration more than plasma :- Cl-, HCO3-, Lactate, Pyruvate, Ascorbate. Aqueous humor is important in providing following functions :-","pyqMatches":[{"year":"2013","no":1118,"q":"Normal aqueous production rate","o":["2 ml/min","5 ml/min","2 1/min","5 1/min"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4793, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 238, '{"id":4793,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":238,"q":"Drug of choice for open angle glaucoma -","o":["Acetazolamide","Latanoprost","Timolol","Brimonidine"],"a":2,"e":"Ans. is ''c'' i.e., Timolol Important acts Angle closure glaucoma Treatment of choice for acute congestive glaucoma Laser iridotomy (1\" choice), Peripheral iridectency (2\" choice) Drug of choice for acute congestive glaucoma Pilocarpine Initially IOP is controlled (first drug used)→ Systemic mannitol or acetazolamide Open angle glaucoma Treatment of choice Topical antiglaucoma drugs Drug of choice /3 - blocker (Timolol, betaxolol, levobunalol) Surgery of choice Argon or diode laser trabeculoplasty","pyqMatches":[{"year":"2013","no":1174,"q":"Drug of choice for open angle glaucoma","o":["Acetazolamide","Latanoprost","Timolol","Brimonidine"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4794, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 239, '{"id":4794,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":239,"q":"Superficial corneal vascularization is caused by?","o":["Contact lens","Graft rejection","Chemical burn","Interstitial keratitis"],"a":0,"e":"Ans. is ''a'' i.e., Contact lens & ''to'' i.e., Graft rejection Superficial Deep Superficial corneal ulcer Contact lens user Trachoma Rosacea keratitis Phlyctenular keratoconjunctivitis o Cornea graft rejection Interstitial keratitis Disciforrn keratitis Deep corneal ulcer Chemical burns Sclerosing keratitis Viral infection can cause superficial corneal ulcer as well as disciform keratitis.","pyqMatches":[{"year":"2013","no":1150,"q":"Superficial corneal vascularization is caused by?","o":["Contact lens","Graft rejection","Chemical burn","Interstitial keratitis"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4795, 'Ophthalmology', 'Refraction & Optics', 'Easy', 'Ophthalmology', 240, '{"id":4795,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Easy","source":"Ophthalmology","sourceNo":240,"q":"Choroidal vascularization is seen in ?","o":["Myopia","Hypermetropia","Presbyopia","Astigmatism"],"a":0,"e":"Ans. is ''a'' i.e., Myopia","pyqMatches":[{"year":"2013","no":1188,"q":"Choroidal vascularization is seen in ?","o":["Myopia","Hypermetropia","Presbyopia","Astigmatism"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4796, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 241, '{"id":4796,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":241,"q":"Contraindication of LASIK ?","o":[">20 years","Keratoconus","Normal cornea","Myopia of - 8D"],"a":1,"e":"Ans. is ''b'' i.e., Keratoconus Patient selection criteria for LASIK Patients above 20 years of age Stable refraction for at least 12 months Motivated patients Myopia upto -12D Absence of corneal pathology Corneal thickness > 500 Contraindications of LASIK Monocular patient Infections eg conjunctivitis, Glaucoma Autoimmune disease Thin cornea (< 450 micron Keratoconus Poor endothelial cell count in cornea (< 1500) Dry eye Diabetic retinopathy Movement Dextroelevation Levoelevation Dextrodepression Yoke Muscles Right superior rectus Left inferior oblique Left superior rectus Right inferior oblique Right inferior rectus Left superior oblique Left inferior rectus Right superior oblique Levodepression Dextroversion Levoversion Right lateral rectus left medial rectus Left lateral rectus Right medial rectus Yoke Muscles Right superior rectus Left inferior oblique Left superior rectus Right inferior oblique Right inferior rectus Left superior oblique Left inferior rectus Right superior oblique Right lateral rectus left medial rectus Left lateral rectus Right medial rectus","pyqMatches":[{"year":"2013","no":1227,"q":"Contraindication of LASIK ?","o":[">20 years","Keratoconus","Normal cornea","Myopia of - 8D"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4797, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 242, '{"id":4797,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":242,"q":"Binocular single vision is tested by ?","o":["Amsler grid","Synoptophore","Maddox rod","Cardboard test"],"a":1,"e":"Ans. is ''b'' i.e., Synoptophore Grades of binocular single vision There are three grades of binocular single vision, which are best tested with the help of a synoptophore.","pyqMatches":[{"year":"2013","no":1133,"q":"Binocular single vision is tested by ?","o":["Amsler grid","Synoptophore","Maddox rod","Cardboard test"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4798, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 243, '{"id":4798,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":243,"q":"In aphakia purkinje images absent are ?","o":["1 & 3''","2nd & 4m","2nd & 3rd","3rd & 4th"],"a":2,"e":"Ans. is ''c'' i.e., 2nd & 3rd","pyqMatches":[{"year":"2013","no":1135,"q":"In aphakia purkinje images absent are ?","o":["1 & 3''","2nd & 4m","2nd & 3rd","3rd & 4th"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4799, 'Ophthalmology', 'Lens & Cataract', 'Moderate', 'Ophthalmology', 244, '{"id":4799,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Moderate","source":"Ophthalmology","sourceNo":244,"q":"Keratitis in contact lens wearer is caused by all except ?","o":["Pseudomonas","Pneumococcus","Aspergillu","Chlamydia"],"a":1,"e":"Ans. is ''d'' i.e., Chlamydia Ectopia lentis o Ectopia lentis is defined as displacement or malposition of the crystalline lens of the eye. The lens is considered dislocated (luxated) when it lies completely outside the lens patellar fossa. The lens is described as subluxated when it is partially displaced but contained within the lens space. Causes are i) Homocystinuria ii) Marfan syndrome iii) Weil - Marchesani sydrome iv) Ehler Dan los syndrome v) Hyperlysinemia vi) Sulphite oxidase deficiency vii) Stickler syndrome viii) Trauma ix) Consecutive / spontaneous (Hypermature cataract, buphthalmos, high myopia)","pyqMatches":[{"year":"2013","no":1145,"q":"Keratitis in contact lens wearer is caused by all except ?","o":["Pseudomonas","Pneumococcus","Aspergillu","Chlamydia"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4800, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 245, '{"id":4800,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":245,"q":"Phlyctenular conjunctivitis is caused by -","o":["Chlaymydia","Staphylococcus","Pneumococcus","Aspergillus"],"a":1,"e":"Ans. is ''b'' i.e., Staphylococcus Phlyctenular keratoconjunctivitis Phlyctenular conjunctivitis is an allergic response of the conjunctival and corneal epithelium to some endogenous allergens and characterized by formation of the phlyctens. Phlyctens are grey, yellow or pinkish white nodules slightly raised above the surface, are seen on the bulbar conjunctiva, generally near the limbus. Peak age group is 3-15 years with slight female preponderance.","pyqMatches":[{"year":"2013","no":1140,"q":"Phlyctenular conjunctivitis is caused by","o":["Chlaymydia","Staphylococcus","Pneumococcus","Aspergillus"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4801, 'Ophthalmology', 'Retina & Vitreous', 'Moderate', 'Ophthalmology', 246, '{"id":4801,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Moderate","source":"Ophthalmology","sourceNo":246,"q":"All are seen in non-proliferative diabetic retinopathy except ?","o":["Microaneurysm","Neovascularization","Hard exudates","Macular edema"],"a":1,"e":"Ans. is ''b'' i.e., Neovascularization Classification of Diabetic retinopathy Nonproliferative Proliferative Background retinopathy","pyqMatches":[{"year":"2013","no":1182,"q":"All are seen in non-proliferative diabetic retinopathy except ?","o":["Microaneurysm","Neovascularization","Hard exudates","Macular edema"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2016","no":999,"q":"All are seen in non-proliferative diabetic retinopathy except ?","o":["Microaneurysm","Neovascularization","Hard exudates","Macular edema"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2013","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4802, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 247, '{"id":4802,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":247,"q":"Surgery of choice for chronic acquired dacryocystitis","o":["Dacryocystorhinostomy","Dacryocystectomy","Conjunctivo-cystorhinostomy","None"],"a":0,"e":"Ans. is ''a'' i.e., Dacryocystorhinostomy Treatment of chronic dacryocystitis Congenital Adult (acquired) Massage over lacrimal sac with antibiotic eye drops Conservative :- Massage, antibiotic drops, probing, Syringing (irrigation) with normal saline & syringing antibiotic solution Dacryocystorhinostomy (DCR) :- Surgery of hoice Probing of nasolacrimal duct Dactyocystectomy (DCT) Intubation with silicone tube Conjunctivocystorhinostom Dacryocystorhinostomy (DCR)","pyqMatches":[{"year":"2013","no":1215,"q":"Surgery of choice for chronic acquired dacryocystitis","o":["Dacryocystorhinostomy","Dacryocystectomy","Conjunctivo-cystorhinostomy","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4803, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 248, '{"id":4803,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":248,"q":"Posner-schlossman syndrome is ?","o":["Ipsilateral optic atrophy with contralateral papilloedema","Unilateral glaucomatous changes with mild anterior uveitis","Granulomatous uveitis with iris heterochromia","None of the above"],"a":1,"e":". Ans. is ''b'' i.e., Unilateral glaucomatous changes with mild anterior uveitis","pyqMatches":[{"year":"2013","no":1177,"q":"Posner-schlossman syndrome is ?","o":["Ipsilateral optic atrophy with contralateral papilloedema","Unilateral glaucomatous changes with mild anterior uveitis","Granulomatous uveitis with iris heterochromia","None of the above"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4804, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 249, '{"id":4804,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":249,"q":"Antigaucomatous drug causing spasm of accommodation","o":["Timolol","Pilocarpine","Dorazolamide","Latanoprost"],"a":1,"e":"Ans. is ''b'' i.e., Pilocarpine Ocular side effects of topical agents for POAG 13-blocker: Allergic blepheroconjunctivitis, corneal hyposthesia, blurred vision, dry eye, superficial punctate keratitis. Cholinomietics (pilocarpine): Blurred vision, miosis, accommodative spasm, browache. Sympathomimetics Non-selective (Dipivefrine): Follicular conjunctivities, rebound congestion, macular edema in aphakic Apraclonidine: Allergies, lid retraction, follicular conjunctivitis, fluctuation in visual acuity Brimonidine: Ocular allergy, conjuntival blanching. Carbonic anhydrase inhibitors (Dorzolamide, brinaolamide): Punctate keratitis, ocular allergies. Prostaglandin analogues (Latanoprost): Punctate keratitis, iris pigmentation.","pyqMatches":[{"year":"2013","no":516,"q":"Antigaucomatous drug causing spasm of accommodation","o":["Timolol","Pilocarpine","Dorazolamide","Latanoprost"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4805, 'Ophthalmology', 'Glaucoma', 'Moderate', 'Ophthalmology', 250, '{"id":4805,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Moderate","source":"Ophthalmology","sourceNo":250,"q":"Besides its properties of decreasing intraocular pressure, timolol is preferred in the treatment of glaucoma because it","o":["Produces no miosis","Possess membrane stabilizing activity","Increases outflow of aqueous humor","Is a selective beta-adrenoceptor blocker"],"a":0,"e":"Ans. is ''a'' i.e., Produces no miosis Advantages of topical n-blockers (timolol) over miotics (pilocarpinel No change in pupil size (no miosis) → No fluctuation in I.O.T. No induced myopia → Convenient once/twice daily applications No ciliary spasm (no spasm of accomodation) → Few systemic side effects.","pyqMatches":[{"year":"2013","no":517,"q":"Besides its properties of decreasing intraocular pressure, timolol is preferred in the treatment of glaucoma because it","o":["Produces no miosis","Possess membrane stabilizing activity","Increases outflow of aqueous humor","Is a selective beta-adrenoceptor blocker"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4806, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 251, '{"id":4806,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":251,"q":"Rigid gas permeable lens are made of-","o":["Plymethymethacrylate","Hydroxymethylmethacrylate","Co polymer of PMMA, Silicon containing monomer & cellulose acetyl butyrate","Cellulose acetae Butyrate"],"a":2,"e":"No separate explanation was provided in the source.","pyqMatches":[{"year":"2015","no":1027,"q":"Rigid gas permeable lens are made of","o":["Plymethymethacrylate","Hydroxymethylmethacrylate","Co polymer of PMMA, Silicon containing monomer & cellulose acetyl butyrate","Cellulose acetae Butyrate"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4807, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 252, '{"id":4807,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":252,"q":"What is regular astigmatism?","o":["Astigmatism in which the principal meridians are parallel","Astigmatism in which the principal meridians are perpendicular","Asymptomatic astigmatism","Astigmatism as a result of cataract surgery"],"a":1,"e":"Regular stigmatism → Principal meridians are pendicular Irregular astigmatism → Principal meridians are not perpendicular.","pyqMatches":[{"year":"2015","no":995,"q":"What is regular astigmatism?","o":["Astigmatism in which the principal meridians are parallel","Astigmatism in which the principal meridians are perpendicular","Asymptomatic astigmatism","Astigmatism as a result of cataract surgery"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4808, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 253, '{"id":4808,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":253,"q":"Chemotherapy agents for retinoblastoma:","o":["vincristine ,carboplatin and etoposide","vinblastine, etoposide and bleomycin","vinblastine , vincristine and etoposide","vinblastine , vincristine and cisplatin"],"a":0,"e":"Answer. A. Vincristine, carboplatin and etoposide Chemotherapy for Retinoblastoma Chemotherapy (chemo) is the use of anti-cancer drugs to treat cancer. Chemo can be given in different ways to treat retinoblastoma. Some of the chemo drugs used to treat retinoblastoma include:","pyqMatches":[{"year":"2019","no":154,"q":"Chemotherapy agents for retinoblastoma:","o":["vincristine ,carboplatin and etoposide","vinblastine, etoposide and bleomycin","vinblastine , vincristine and etoposide","vinblastine , vincristine and cisplatin"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4809, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 254, '{"id":4809,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":254,"q":"Drug used in acute congestive glaucoma are:","o":["Atropine","Pilocarpine","Acetazolamide","Both B & C"],"a":3,"e":"Answer. D. Both Pilocarpine & Acetazolamide Management of angle closure glaucoma Acute congestive glaucoma also is known as acute angle closure glaucoma. Immediate medical therapy in acute AC consists of commencing IOP-lowering eye medications such as topical ß-blocker, a2-agonist and even prostaglandin analogues as soon as possible. Once the IOP is sufficiently reduced to allow iris reperfusion, pilocarpine is instilled to induce miosis in an attempt to widen the anterior chamber angles and reestablish aqueous outflow. Mydriatic drugs such as atropine, cyclopentolate, tropicamide and phenylephrine are precipitating factor for angle closure glaucoma, so not used (contraindicated) in its treatment.","pyqMatches":[{"year":"2019","no":155,"q":"Drug used in acute congestive glaucoma are:","o":["Atropine","Pilocarpine","Acetazolamide","Both B & C"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4810, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Easy', 'Ophthalmology', 255, '{"id":4810,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Easy","source":"Ophthalmology","sourceNo":255,"q":"Which is the Most common ocular finding in myasthenia gravis?","o":["Ptosis","Lagophthalmos","Proptosis","Enophthalmos"],"a":0,"e":"Answer .A. Ptosis In more than half the people who develop myasthenia gravis, their first signs and symptoms involve eye problems, such as:","pyqMatches":[{"year":"2019","no":156,"q":"Which is the Most common ocular finding in myasthenia gravis?","o":["Ptosis","Lagophthalmos","Proptosis","Enophthalmos"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4811, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 256, '{"id":4811,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":256,"q":"In Retinitis pigmentosa decreased level of?","o":["Arachidonic","Trielonic","Thromboxane","Docosa hexanoic acid"],"a":3,"e":"Answer. D. Docosa hexanoic acid","pyqMatches":[{"year":"2019","no":149,"q":"In Retinitis pigmentosa decreased level of?","o":["Arachidonic","Trielonic","Thromboxane","Docosa hexanoic acid"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4812, 'Ophthalmology', 'Refraction & Optics', 'Easy', 'Ophthalmology', 257, '{"id":4812,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Easy","source":"Ophthalmology","sourceNo":257,"q":"What is against the rule correction in astigmatism:","o":["-1.25 cyl 90","-2 spherical 180","-3 cyl 180","+2 cyl 180"],"a":0,"e":":D Types of regular astigmatism Depending upon the axis and the angle between the two principal meridia, regular astigmatism can be classified into the following types :","pyqMatches":[{"year":"2019","no":150,"q":"What is against the rule correction in astigmatism:","o":["1.25 cyl 90","2 spherical 180","3 cyl 180","+2 cyl 180"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4813, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 258, '{"id":4813,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":258,"q":"Morbid fear of darkness known as:","o":["Claustrophobia","Xenophobia","Mysophobia","Nyctophobia"],"a":3,"e":"Answer. D. Nyctophobia Nyctophobia is an extreme fear of night or darkness that can cause intense symptoms of anxiety and depression. A fear becomes a phobia when it’s excessive, irrational, or impacts your day-to-day life. Claustrophobia is a form of anxiety disorder, in which an irrational fear of having no escape or being closed-in can lead to a panic attack. xenophobia. : fear and hatred of strangers or foreigners or of anything that is strange or foreign. Mysophobia, also known as verminophobia, germophobia, germaphobia, bacillophobia and bacteriophobia, is a pathological fear of contamination and germs.","pyqMatches":[{"year":"2019","no":151,"q":"Morbid fear of darkness known as:","o":["Claustrophobia","Xenophobia","Mysophobia","Nyctophobia"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4814, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 259, '{"id":4814,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":259,"q":"Which drug causes ocular hypotension with apnea in an infant?","o":["Latanoprost","Timolol","Brimonidine","Dorzolamide"],"a":2,"e":"Answer. C. Brimonidine Brimonidine is a relatively selective alpha-agonist, which reduces intraocular pressure (IOP) by decreasing aqueous production and increasing uveoscleral outflow. Brimonidine passes through the blood-brain barrier, potentially causing central nervous system (CNS) toxicity. There have been reports of bradycardia, hypotension, hypothermia, hypotonia, and apnea in infants after topical brimonidine.","pyqMatches":[{"year":"2019","no":153,"q":"Which drug causes ocular hypotension with apnea in an infant?","o":["Latanoprost","Timolol","Brimonidine","Dorzolamide"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4815, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 260, '{"id":4815,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":260,"q":"A child has ptosis and poor levator function. What surgery will you do?","o":["Levator muscle resection","Mullerectomy","Fasanella Servat surgery","Frontalis suspension surgery"],"a":3,"e":"Answer D. Frontalis suspension surgery Muller muscle resections are typically used for repair of minimal ptosis (2 mm) and are generally considered superior to the Fasanella-Servat procedure (tarsoconjunctival mullerectomy) in maintaining eyelid contour and preserving the tarsus. When levator function is poor, the surgeon should consider utilizing the accessory elevators of the eyelid in ptosis repair. This type of surgery is most commonly required in congenital ptosis with poor levator function or in various forms of neurogenic ptosis with poor levator function. Frontalis suspension surgeryperformed when levator function is poor or absent, the eyelid is suspended directly from the frontalis muscle so that movement of the brow is efficiently transmitted to the eyelid. Thus, the patient is able to elevate the eyelid by using the frontalis muscle to lift the brow. Frontalis suspension can be performed transcutaneously or transconjunctivally.This surgery connects the eyelid to the brow with a sling material and utilizes the power of the frontalis muscle to elevate the poorly functioning eyelid.","pyqMatches":[{"year":"2019","no":152,"q":"A child has ptosis and poor levator function. What surgery will you do?","o":["Levator muscle resection","Mullerectomy","Fasanella Servat surgery","Frontalis suspension surgery"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4816, 'Ophthalmology', 'Refraction & Optics', 'Easy', 'Ophthalmology', 261, '{"id":4816,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Easy","source":"Ophthalmology","sourceNo":261,"q":"Esotropiais usually associated with:","o":["Myopia","Hypermetropia","Astigmatism","Presbyopia"],"a":1,"e":"Ans.B.Hypermetropia Accommodative esotropia is one of the most common types of strabismus in childhood. The incidence is estimated at 2% of the population. It is usually found in patients with moderate amounts of hyperopia. As the patient accommodates or focuses the eyes, the eyes converge.","pyqMatches":[{"year":"2019","no":157,"q":"Esotropiais usually associated with:","o":["Myopia","Hypermetropia","Astigmatism","Presbyopia"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4817, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 262, '{"id":4817,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":262,"q":"Corneal ulcer resembling fungal ulcer is seen in infec​tion with which of the agents?","o":["Nocardia asteroides","Mycobacterium","Klebsiella pneumoniae","Chlamydia trachomatis"],"a":0,"e":"Ans: A. Nocardia asteroides (Ref: Yanoff & Duker 4Ie p219; Smolin and Thoft''s''The Cornea 4Ie p248) Keratitis caused by Nocardia asteroides, which is a filamentous bacteria, closely resembles the morphology of corneal ulcers caused by fungi. Corneal infections with Nocardia, Actinomyces, and Streptomyces typically follow an indolent clinical course, which may simulate mycotic keratitis with hyphal edges, satellite lesions, and elevated epithelial lesions. The ulcer is characteristically superficial, with a wreath-shaped gray- white infiltrate and an undermined necrotic edge. The base might assume a cracked windshield appearance. Nocardia keratitis often resembles fungal infection, with a filamentous appearing border and satellite lesions. Infection appears to be indolent; the anterior chamber reaction is often minimal. However, rarely, more severe anterior chamber reaction and hypopyon seen.","pyqMatches":[{"year":"2013","no":1228,"q":"Corneal ulcer resembling fungal ulcer is seen in infec​tion with which of the agents?","o":["Nocardia asteroides","Mycobacterium","Klebsiella pneumoniae","Chlamydia trachomatis"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4818, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 263, '{"id":4818,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":263,"q":"Anisocoria in Horner''s syndrome is due to","o":["Oculo sympathetic palsy","Oculo parasympathetic palsy","Oculomotor nerve palsy","Abducens nerve palsy"],"a":0,"e":"Answer- A. Oculo sympathetic palsy Anisocoria is a condition characterized by an unequal size of the eyes'' pupils. It can be an entirely harmless condition or a symptom of more serious medical problems. Anisocoria has various causes: Physiological anisocoria: About 20% of normal people have a slight difference in pupil size which is known as physiological anisocoria. In this condition, the difference between pupils is usually less than 1 mm.[3] Horner''s syndrome Horner''s syndrome is oculo sympathetic palsy. Horner''s syndrome consists of classical triad of ipsilateral:-","pyqMatches":[{"year":"2015","no":1056,"q":"Anisocoria in Horner''s syndrome is due to","o":["Oculo sympathetic palsy","Oculo parasympathetic palsy","Oculomotor nerve palsy","Abducens nerve palsy"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4819, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 264, '{"id":4819,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":264,"q":"Diopteric power is related -","o":["Directly to square of focal length","Inversely to focal length","Directly to focal length","Inversely to square of focal length"],"a":1,"e":"Answer- B. Inversely to focal length Optical power (also referred to as dioptric power, refractive power, focusing Power,or convergence Power) is the degree to mirror, or other optical system converges or diverges light.","pyqMatches":[{"year":"2012","no":920,"q":"Diopteric power is related","o":["Directly to square of focal length","Inversely to focal length","Directly to focal length","Inversely to square of focal length"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4820, 'Ophthalmology', 'Retina & Vitreous', 'Moderate', 'Ophthalmology', 265, '{"id":4820,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Moderate","source":"Ophthalmology","sourceNo":265,"q":"All are seen in CMV retinitis except","o":["Immunosuppresion","Brush-fire appearance Pattern","Crack mud appearance","Perivasculitis"],"a":2,"e":"Answer- C. Crack mud appearance CMV retinitis is the most common ophthalmic manifestation of CMV. There is characteristic hemorrhagic, full thickness retinitis. Occuring as a congenital infection in infants or an opportunistic infection in the immunocompromised host. CMV retinitis is a white granular geographic lesion that clears centrally as it enlarges, leaving a quiet central area of retinal atrophy and mottled pigment epithelium. This has also been described as \"brush-fire pattern. Perivascular retinitis- Frosted branch angitis with retinal perivasculitis.","pyqMatches":[{"year":"2013","no":1183,"q":"All are seen in CMV retinitis except","o":["Immunosuppresion","Brush-fire appearance Pattern","Crack mud appearance","Perivasculitis"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4821, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 266, '{"id":4821,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":266,"q":"Optic vesicle is derived from -","o":["Endoderm","Mesoderm","Neuroectoderm","Surface Ectoderm"],"a":2,"e":"Answer- C. Neuroectoderm An outgrowth from prosencephalon forms optic vesicle (neuroectodermal structure). Proximal part of optic vesicle becomes constricted and elongated to form optic stalk Growing optic vesicle comes in contact with surface ectoderm which is thickened to form lens placode.","pyqMatches":[{"year":"2016","no":6,"q":"Optic vesicle is derived from","o":["Endoderm","Mesoderm","Neuroectoderm","Surface Ectoderm"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4822, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 267, '{"id":4822,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":267,"q":"Goblet cells are seen in -","o":["Cornea","Conjunctiva","Retina","Vitreous"],"a":1,"e":"Answer B. Conjunctiva Goblet cells within the conjunctival epithelium are specialized cells that secrete mucins onto the surface of the eye. Histology of conjunctiva The epithelium is non-keratinizing and around five cell-layers deep. Mucin-secreting goblet cells are located within the epithelium, and they are most dense inferonasally (nasal > inferior) and in the fornices. The stroma (substantia propria) consists of richly vascularized, loose connective tissue. The accessory lacrimal glands of Krause and Wolfring are located deep within the stroma. Conjunctiva-associated lymphoid tissue (CALT) is critical in the initiation and regulation of ocular surface immune responses.","pyqMatches":[{"year":"2016","no":966,"q":"Goblet cells are seen in","o":["Cornea","Conjunctiva","Retina","Vitreous"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4823, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 268, '{"id":4823,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":268,"q":"Neovascularization in uveal tissue [Rubeosis Iridis] is most commonly caused by","o":["Diabetic Retinopathy","CRVO","CRAO","Choroidal melanoma"],"a":0,"e":"Answer- A. Diabetic Retinopathy It is a secondary angle closure glaucoma which results due to formation of neovascular membrane over the iris i.e., neovascularization of iris (rubeosis iridis). Causes of rubeosis iridis are:- Common :- Diabetic retinopathy (most common cause), central retinal vein occlusion), Eale''s disease, sickle-cell retinopathy.","pyqMatches":[{"year":"2013","no":1180,"q":"Neovascularization in uveal tissue [Rubeosis Iridis] is most commonly caused by","o":["Diabetic Retinopathy","CRVO","CRAO","Choroidal melanoma"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4824, 'Ophthalmology', 'Lens & Cataract', 'Moderate', 'Ophthalmology', 269, '{"id":4824,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Moderate","source":"Ophthalmology","sourceNo":269,"q":"All of the following are causes of posterior subcapsular cataract except -","o":["Myotonic dystrophy","Wilson''s Disease","Ionizing radiation","Congenital cataract"],"a":3,"e":"Answer- D. Congenital cataract Myotoic dystrophy Wilson''s disease Atopic dermatitis Corticosteroids Trauma Galactosemia Infrared/heat cataract (glass-blower''s or glass worker)","pyqMatches":[{"year":"2015","no":1024,"q":"All of the following are causes of posterior subcapsular cataract except","o":["Myotonic dystrophy","Wilson''s Disease","Ionizing radiation","Congenital cataract"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4825, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 270, '{"id":4825,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":270,"q":"Ectopia lentis is/are associated with:","o":["Homocystinuria","Alport syndrome","Lowe syndrome","Marfan syndrome e) Sulphite oxidase deficiency"],"a":0,"e":":D:E Answer- (A) Homocystinuria (D) Marfan syndrome (E) Sulphite oxidase deficiency Marfan syndrome Homocystinuria Weil-Marchesani syndrome Sulfite oxidase deficiency Hyperlysinemia","pyqMatches":[{"year":"2013","no":1167,"q":"Ectopia lentis is/are associated with:","o":["Homocystinuria","Alport syndrome","Lowe syndrome","Marfan syndrome e) Sulphite oxidase deficiency"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4826, 'Ophthalmology', 'Refraction & Optics', 'Moderate', 'Ophthalmology', 271, '{"id":4826,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Moderate","source":"Ophthalmology","sourceNo":271,"q":"All are true regarding cornea except:","o":["Endothelium help in maintaining dehydrated state","Oxygen is mostly derived by epithelium directly from the air through tear film","Glucose supply for corneal metabolism is mainly derived from the aqueous","Corneal thickness is more at center than periphery e) Richly vascular"],"a":3,"e":":E Answer- (D) Corneal thickness is more at center than periphery (E) Richly vascular Outer & fibrous coat of EYEBALL. Transparent, anterior 1/6th segment of eyeball. Non-vascular Most of the refraction in eye occur at anterior surface of cornea (air- tear interface) ,i.e., Anterior surface of cornea is the most important refractive structure of eye. The most actively metabolising layers of the cornea are epithelium & endothelium.","pyqMatches":[{"year":"2015","no":1007,"q":"All are true regarding cornea except:","o":["Endothelium help in maintaining dehydrated state","Oxygen is mostly derived by epithelium directly from the air through tear film","Glucose supply for corneal metabolism is mainly derived from the aqueous","Corneal thickness is more at center than periphery e) Richly vascular"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4827, 'Ophthalmology', 'Glaucoma', 'Moderate', 'Ophthalmology', 272, '{"id":4827,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Moderate","source":"Ophthalmology","sourceNo":272,"q":"Feature (s) of Infantile glaucoma is/are except:","o":["Aniridia may be associated","Treatment includes trabeculotomy","Buphthalmos can occur","Cornea is thin & clear e) May be associated with Sturge-weber syndrome"],"a":3,"e":"Answer- D. Cornea is thin & clear Answer- D. Cornea is thin & clear Primary infantile glaucoma is a rare developmental defect in the iridocorneal filtration angle of the anterior chamber that prevents aqueous fluid from properly draining from the eye. This obstruction increases the intraocular pressure, which, if untreated, damages the optic nerve. Infantile glaucoma can cause complete blindness if left untreated. Glaucoma can also occur in infants after trauma or intraocular surgery (eg, cataract extraction). Glaucoma associated with another ocular disorder, such as aniridia, Lowe syndrome, or Sturge-Weber syndrome, is called secondary glaucoma. Buphthalmos (blue and thin sclera, streched limbus) is seen. Treatment: Trabeculotomy, Goniotomy, combined trabeculotomy and trabeculotomy +/- MMC(Mitomycin)","pyqMatches":[{"year":"2015","no":1034,"q":"Feature (s) of Infantile glaucoma is/are except:","o":["Aniridia may be associated","Treatment includes trabeculotomy","Buphthalmos can occur","Cornea is thin & clear e) May be associated with Sturge-weber syndrome"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4828, 'Ophthalmology', 'Refraction & Optics', 'Moderate', 'Ophthalmology', 273, '{"id":4828,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Moderate","source":"Ophthalmology","sourceNo":273,"q":"In Snellen''s chart, eye subtends an angle of how many minutes with letters on Snellen''s chart?","o":["1 min of arc","5 min of arc","10 min of arc","15 min of arc"],"a":1,"e":"Ans. is ''b'' i.e., 5 min of arc Indications: To provide a baseline recording of visual acuity (VA) To aid examination and diagnosis of eye disease or refractive error For medico-legal reasons Equipment: Multi-letter Snellen chart E or C Snellen chart or a chart with illustrations for patients who cannot read or speak Plain occluder (not essential) Pinhole occluder Torch or flashlight Patient''s documentation Procedure: At the given distance, each letter subtends an angle of 5 min at the nodal point of the eye Snellen chart is used for distant vision. The patient should read the chart at a distance of 6 m. Principle: lt consists of letters arranged in lines, with progressively diminishing size. Each letter subtends an angle of 5 minutes at the nodal point of an eye when viewed from its respective distance Each letter is so constructed that the width (of each stroke) subtends an angle of 1 minute = MAR. Interpretation: Normal visual acuity for far is 6/5 Best visual acuity for far is 6/3 Minimum recordable VA on Snellen''s chart is 1/60. Snellen''s chart:","pyqMatches":[{"year":"2016","no":959,"q":"In Snellen''s chart, eye subtends an angle of how many minutes with letters on Snellen''s chart?","o":["1 min of arc","5 min of arc","10 min of arc","15 min of arc"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4829, 'Ophthalmology', 'Optic Nerve & Neuro-ophthalmology', 'Easy', 'Ophthalmology', 274, '{"id":4829,"subject":"Ophthalmology","chapter":"Optic Nerve & Neuro-ophthalmology","difficulty":"Easy","source":"Ophthalmology","sourceNo":274,"q":"Listers perimeter is used for","o":["Kinetic Visual field testing","Static Visual field testing","Both kinetic and static visual testing","None of these"],"a":0,"e":"Ans. is ''a'' i.e., Kinetic Visual field testing [Ref Kanski''s 8th/e chapter 10, p. 325] Static perimetry: A method of assessing fields, usually automated, in which the location of a stimulus remains fixed, with intensity increased until it is seen by the subject (threshold is reached) or decreased until it is no longer detected. Kinetic (dynamic) perimetry is now much less commonly performed than static perimetry. A stimulus of constant intensity is moved from a non-seeing area to a seeing area at a standardized speed until it is perceived, and the point of perception is recorded on a chart; points from different meridia are joined to plot an isopter for that stimulus intensity. Stimuli of different intensities are used to produce a contour map of the visual field. Kinetic perimetry can be performed by means of a manual (Goldmann) or an automated perimeter if the latter is equipped with an appropriate software program.","pyqMatches":[{"year":"2016","no":961,"q":"Listers perimeter is used for","o":["Kinetic Visual field testing","Static Visual field testing","Both kinetic and static visual testing","None of these"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4830, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 275, '{"id":4830,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":275,"q":"What is the type of Goldman tonometry?","o":["Applanation Tonometry","Dynamic countour tonometry","Rebound tonometry","Impression tonometry"],"a":0,"e":"Ans. is ''a'' i.e., Applanation Tonometry [Ref Anatomy & physiology of eye 2\"1/e p. 79] Measurement of intraocular pressure (10P) Measurement of IOP is done by :? A) Manometry :- It is the only direct measure of IOP. B) Tonometry :- It is an indirect method of measurement of IOP. Following types of tonometers are there :-","pyqMatches":[{"year":"2016","no":962,"q":"What is the type of Goldman tonometry?","o":["Applanation Tonometry","Dynamic countour tonometry","Rebound tonometry","Impression tonometry"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4831, 'Ophthalmology', 'Refraction & Optics', 'Easy', 'Ophthalmology', 276, '{"id":4831,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Easy","source":"Ophthalmology","sourceNo":276,"q":"Spasm of accommodation mimics","o":["Myopia","Hypermetropia","Amblyopia","Presbiopia"],"a":0,"e":"Ans. is ''a'' i.e.,Myopia [Ref Khurana ilth/e p. 42] Pseudomyopia Spasm of accommodation occurs due to excessive contraction of the ciliary muscles. This makes the zonules loose and hence the lens becomes more convex. This leads to the image be formed in front of the retina therebt mimicking myopia. This is called pseudomyopia.","pyqMatches":[{"year":"2016","no":963,"q":"Spasm of accommodation mimics","o":["Myopia","Hypermetropia","Amblyopia","Presbiopia"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4832, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 277, '{"id":4832,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":277,"q":"Subretinal haemorrhage at the macula in myopia is known as?","o":["Lacquer cracks","Foster Fuchs spot","Staphyloma","Macular retinoschisis"],"a":1,"e":"Ans. is ''b'' i.e., Foster fuchs spot Degenerative myopia: Refractive error may increase upto 20-25D with degenerative changes in eye. Temporal myopic crescent is a feature of pathological/degenerative myopia. It is a white crescent at the temporal border of the disc. Some of the most typical features of degenerative myopia are: Vitreous liquefaction and posterior vitreous detachment Peripapillary atrophy appearing as temporal choroidal or scleral crescents or rings around the optic disc Lattice degeneration in the peripheral retina Tilting or malinsertion of the optic disc, usually associated with myopic conus Thinning of the retinal pigment epithelium with resulting atrophic appearance of the fundus Ectasia of the sclera posteriorly (posterior staphyloma) Breaks in Bruch’s membrane and choriocapillaris, resulting in lines across the fundus called “lacquer cracks” Foster Fuch’s spot in the macular area.","pyqMatches":[{"year":"2016","no":964,"q":"Subretinal haemorrhage at the macula in myopia is known as?","o":["Lacquer cracks","Foster Fuchs spot","Staphyloma","Macular retinoschisis"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4833, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 278, '{"id":4833,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":278,"q":"Dispersive prism functions for","o":["Splitting light into different wavelengths","Reflecting light","Polarizing light","None"],"a":0,"e":"Ans. is ''a'' i.e., Splitting light into different wavelengths [Ref \"The Discovery of the Spectrum of Light\".] \"Prisms may be used for polarising and reflecting light but dispersive prisms like the commonly used triangular prism split the light into different colours based on wavelengths\" In optics, a prism is a transparent optical element with flat, polished surfaces that refract light. At least two of the flat surfaces must have an angle between them. The exact angles between the surfaces depend on the application. The traditional geometrical shape is that of a triangular prism with a triangular base and rectangular sides. Light changes speed as it moves from one medium to another (for example, from air into the glass of the prism). This speed change causes the light to be refracted and to enter the new medium at a different angle (Huygens principle). The degree of bending of the light''s path depends on the angle that the incident beam of light makes with the surface, and on the ratio between the refractive indices of the two media (Snell''s law). The refractive index of many materials (such as glass) varies with the wavelength or color of the light used, a phenomenon known as dispersion. This causes light of different colors to be refracted differently and to leave the prism at different angles, creating an effect similar to a rainbow.","pyqMatches":[{"year":"2016","no":965,"q":"Dispersive prism functions for","o":["Splitting light into different wavelengths","Reflecting light","Polarizing light","None"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4834, 'Ophthalmology', 'Cornea & External Eye', 'Moderate', 'Ophthalmology', 279, '{"id":4834,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Moderate","source":"Ophthalmology","sourceNo":279,"q":"Corneal epithelial repair includes all of the following phases except","o":["Cell proliferation","Cell migration","Cell adhesion","Cell fusion"],"a":3,"e":"Ans. is ''d'' i.e., Cell fusion [Ref Corneal Epithelial wound healing: BJO 1994, 78; 401-408] Corneal epithelial repair The processes involved in the healing of corneal epithelial wounds can be divided into three distinct components: cell migration, cell proliferation, and cell adhesion. All three components are part of a continuous process but the contribution of each can vary depending on the size and depth of the wound and nature of injury.","pyqMatches":[{"year":"2016","no":968,"q":"Corneal epithelial repair includes all of the following phases except","o":["Cell proliferation","Cell migration","Cell adhesion","Cell fusion"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4835, 'Ophthalmology', 'Cornea & External Eye', 'Moderate', 'Ophthalmology', 280, '{"id":4835,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Moderate","source":"Ophthalmology","sourceNo":280,"q":"Conjunctival staining is done by all except","o":["Fluoroscein","India ink","Rose Bengal","Lissamine"],"a":1,"e":"Ans. is ''b'' i.e., India ink [Ref Can J Ophthalmol. 2015 Aug;50(4):273-7. doi: 10.1016/j.jcjo.2015.05.007.] Common dyes used for conjunctival staining : Rose Bengal, Fluoroscein and Lissamine.","pyqMatches":[{"year":"2016","no":969,"q":"Conjunctival staining is done by all except","o":["Fluoroscein","India ink","Rose Bengal","Lissamine"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4836, 'Ophthalmology', 'Community Ophthalmology', 'Easy', 'Ophthalmology', 281, '{"id":4836,"subject":"Ophthalmology","chapter":"Community Ophthalmology","difficulty":"Easy","source":"Ophthalmology","sourceNo":281,"q":"Pseudogerontoxon is seen in","o":["Vernal keratopathy","Choroidal melanoma","Trachoma","Retinoblastoma"],"a":0,"e":"Ans. is ''a'' i.e., Vernal keratopathy [Ref Kanski 8''1* Chap. 5, p. 138]","pyqMatches":[{"year":"2016","no":971,"q":"Pseudogerontoxon is seen in","o":["Vernal keratopathy","Choroidal melanoma","Trachoma","Retinoblastoma"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4837, 'Ophthalmology', 'Cornea & External Eye', 'Hard', 'Ophthalmology', 282, '{"id":4837,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Hard","source":"Ophthalmology","sourceNo":282,"q":"A 50 year old male presents with cicatricial entopion of upper and lower eyelid. On eversion of upper eyelid, linear conjunctival scars - Arlt line are seen. What is the diagnosis?","o":["Trachoma","Spring catarrah","Ligneous conjunctivitis","Parinaud oculoglandular syndrome"],"a":0,"e":"Ans. is ''a'' i.e.,Trachoma [Ref Kanski 8th /e Chap. 5, p. 138] Arlt line is a feature of trachoma. Signs of Trachoma Conjunctival signs :- Congestion, conjunctival follicles (boiled sagograin like), Papillary hyperplasia, conjunctival scarring (Arles line), concretion. Corneal signs :- Superficial keratitis, Herbert follicles, Pannus, Corneal ulcer, Herbert pits, Corneal opacity.","pyqMatches":[{"year":"2016","no":972,"q":"A 50 year old male presents with cicatricial entopion of upper and lower eyelid. On eversion of upper eyelid, linear conjunctival scars - Arlt line are seen. What is the diagnosis?","o":["Trachoma","Spring catarrah","Ligneous conjunctivitis","Parinaud oculoglandular syndrome"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4838, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 283, '{"id":4838,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":283,"q":"Pain is out of proportion to signs in which corneal ulcer?","o":["Herpes simplex keratits","Acanthamoeba keratitis","Fungal keratitis","Pneumococcal keratitis"],"a":1,"e":"Ans. is ''b'' i.e.,Acanthamoeba keratitis [Ref Kanski 8th le Chap. 6, p. 197] In human, acanthamoeba causes :- (i) Keratitis; (ii) Granulomatous encephalitis, (iii) Fulminant meningoencephalitis Patient presents with very severe pain (which is out of proportion to the degree of clinical signs), watering, photophobia, blurred vision and blepherospasm. On examination, following characteristic features are seen : ?","pyqMatches":[{"year":"2016","no":973,"q":"Pain is out of proportion to signs in which corneal ulcer?","o":["Herpes simplex keratits","Acanthamoeba keratitis","Fungal keratitis","Pneumococcal keratitis"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4839, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 284, '{"id":4839,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":284,"q":"Oblate ellipsoid appearance of cornea is seen in which of the following conditions?","o":["Post myopic LASIK surgery","With the rule astigmatism","Bi-oblique astigmatism","Oblique astigmatism"],"a":0,"e":"Ans. is ''a'' i.e., Post myopic LASIK surgery [Ref Quality of vision: Essential Optics for the cataract and refractive surgeon, chap. 3, p. 30] The cornea is a three dimensional prolate ellipsoid, like a bullet or a tulip. It is steeper in the centre and flatter in the periphery. After refractive surgeries like myopic LASIK, cornea is converted to oblate ellipsoid, which is steeper in the periphery and flatter in the centre.","pyqMatches":[{"year":"2016","no":975,"q":"Oblate ellipsoid appearance of cornea is seen in which of the following conditions?","o":["Post myopic LASIK surgery","With the rule astigmatism","Bi-oblique astigmatism","Oblique astigmatism"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4840, 'Ophthalmology', 'Cornea & External Eye', 'Moderate', 'Ophthalmology', 285, '{"id":4840,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Moderate","source":"Ophthalmology","sourceNo":285,"q":"Which of the following Glycosaminoglycans are not present in cornea","o":["Keratin sulfate","Chondroitin sulfate","Chondroitin","Heparin sulfate"],"a":3,"e":"Ans. is ''d'' i.e., Heparin sulfate [Ref Khurana Anatomy and Physiology of Eyes, ?die, chapter 2, p. 26) GAGs ( Glycosaminoglycans) or so called acid- mucopolysaccharides represent 4-4.5% of the dry weight of the cornea. Cornea contains three major GAG fractions namely: Keratan sulfate (50%), chondroitin sulfate (25%) and chondroitin (25%)-present exclusively in cornea. The GAG are present in the interfibrillar space of the corneal stroma and account for the `stromal swelling pressure''(normal-60 mmHg) ie. Its tendency to imbibe water and thus plays an important role in the maintenance of corneal hydration level and transparency. An abnormal accumulation of GAG occurs in the corneal stroma of the patients affected by the inborn errors of GAG metabolism known as mucopolysaccharidosis.","pyqMatches":[{"year":"2016","no":976,"q":"Which of the following Glycosaminoglycans are not present in cornea","o":["Keratin sulfate","Chondroitin sulfate","Chondroitin","Heparin sulfate"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4841, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 286, '{"id":4841,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":286,"q":"Iron deposition line at edge of pterygium on corneal epithelium is known as?","o":["Stocker''s line","KF Ring","Fleischer ring","Ferrys line"],"a":0,"e":"Ans. is ''a'' i.e., Stocker''s line [Ref: Khurana 4''5/e p. 80; Parson 21\"/e p. 181; Yanoff & Ducker Ophthalmology yd le p","pyqMatches":[{"year":"2016","no":977,"q":"Iron deposition line at edge of pterygium on corneal epithelium is known as?","o":["Stocker''s line","KF Ring","Fleischer ring","Ferrys line"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4842, 'Ophthalmology', 'Optic Nerve & Neuro-ophthalmology', 'Easy', 'Ophthalmology', 287, '{"id":4842,"subject":"Ophthalmology","chapter":"Optic Nerve & Neuro-ophthalmology","difficulty":"Easy","source":"Ophthalmology","sourceNo":287,"q":"Which order neuron is optic nerve in the visual pathway?","o":["First order","Second order","Third order","None of these"],"a":1,"e":"Ans. is ''b'' i.e., Second order [Ref Khurana 4th/e p. 286-289; Concise textbook of physiology 2\"/e p. 336] Sensory organs → Photoreceptors (Rods & cones) Neurons of first order → Axon of bipolar cells (in Retina) Neurons of second order → Axons of ganglionic cell (Retina i.e., Optic disc, Optic nerve, Optic chiasma, optic tracts) Neurons of third order → Axons from nerve cells in lateral geniculate body (optic radiation)","pyqMatches":[{"year":"2016","no":980,"q":"Which order neuron is optic nerve in the visual pathway?","o":["First order","Second order","Third order","None of these"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4843, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 288, '{"id":4843,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":288,"q":"Purkinje image test is used in","o":["Keratomoter","Retinoscopy","Optical coherence tomography","Pachymeter"],"a":3,"e":"Ans. is ''d'' i.e.,Pachymeter [Ref Elkington''s clinical optics 3rd/e chapter 14, p. 207] Pachymetry is the measurement of corneal thickness. Pachymeters employ either optical or ultrasound principles. Optical pachymeters use the Purkinje-Sanson images formed by the anterior and posterior surfaces of the cornea (images I and II) to measure corneal thickness, and the Purkinje-Sanson images formed by the posterior surface of the cornea and the anterior surface of the lens (images II and III) to measure the depth of the anterior chamber.","pyqMatches":[{"year":"2016","no":981,"q":"Purkinje image test is used in","o":["Keratomoter","Retinoscopy","Optical coherence tomography","Pachymeter"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4844, 'Ophthalmology', 'Cornea & External Eye', 'Moderate', 'Ophthalmology', 289, '{"id":4844,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Moderate","source":"Ophthalmology","sourceNo":289,"q":"Which of the following is not a part of uveal","o":["Iris","Ciliary body","Choroid","Retina"],"a":3,"e":"Ans. is ''d'' i.e.,Retina [Ref Khurana''s 2\"/e Chap. 3, p. 44] Uveal tissue constitutes the middle vascular coat of the eyeball (Inner coat is retina and outer coat is cornea & sclera). From anterior to posterior it can be divided into three parts :- Iris, ciliary body and choroid. Iris and anterior part (2 mm) of ciliary body(pars plicata) are considered as anterior uveal tissues. Posterior part (4mm) of ciliary body (pars plana) and adjacent choroid are considered as intermediate uveal tissue. Choroid is considered as posterior uveal tissue. The entire uveal tract is developmentally, structurally and functionally one individual structure.","pyqMatches":[{"year":"2016","no":982,"q":"Which of the following is not a part of uveal","o":["Iris","Ciliary body","Choroid","Retina"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4845, 'Ophthalmology', 'Miscellaneous', 'Moderate', 'Ophthalmology', 290, '{"id":4845,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Ophthalmology","sourceNo":290,"q":"All except one are true for Scleromalacia perforans","o":["It is non inflammatory scleritis","It affects only males","Perforation of the globe is extremely rare","Vision is unaffected"],"a":1,"e":"Ans. is ''b'' i.e., It affects only males [Ref Kanski''s Clinical Ophthalmology 8\"Ve chapter 8, p. 259] Scleromalacia perforans Scleromalacia perforans (5% of scleritis) is a specific type of progressive scleral thinning without inflammation that typically affects elderly women with longstanding rheumatoid arthritis, but has also been described in association with other systemic disorders. Despite the nomenclature, perforation of the globe is extremely rare as integrity is maintained by a thin layer of fibrous tissue. Differential diagnosis is from the innocuous scleral hyaline plaque and senile scleromalacia.","pyqMatches":[{"year":"2016","no":983,"q":"All except one are true for Scleromalacia perforans","o":["It is non inflammatory scleritis","It affects only males","Perforation of the globe is extremely rare","Vision is unaffected"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4846, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 291, '{"id":4846,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":291,"q":"Blue dot cataract is caused by","o":["Diabetes","Wilson''s disease","Atopic dermatitis","Chalcosis"],"a":2,"e":"Ans. is ''c'' i.e.,Atopic dermatitis [Ref Parson''s 21\"/e p. 259] Blue dot cortical cataract is caused by myotonic dystrophy and atopic dermatitis.","pyqMatches":[{"year":"2016","no":985,"q":"Blue dot cataract is caused by","o":["Diabetes","Wilson''s disease","Atopic dermatitis","Chalcosis"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4847, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 292, '{"id":4847,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":292,"q":"Which of the following is complication of prolonged use of corticosteroid eye drops?","o":["Posterior Subcapsular cataract","Nuclear cataract","Capsular cataract","Cortical cataract"],"a":0,"e":"Ans. is ''a'' i.e., Posterior Subcapsular cataract Causes of posterior subcapsular cataract : Myotoic dystrophy Down''s syndromeIonizing radiation Wilson''s disease Corticosteroids Galactosemia DM Busulfan Senile cataract Infrared/heat cataract Chloroquine Trauma (glass-blower''s or glass worker)Atopic dermatitis","pyqMatches":[{"year":"2016","no":986,"q":"Which of the following is complication of prolonged use of corticosteroid eye drops?","o":["Posterior Subcapsular cataract","Nuclear cataract","Capsular cataract","Cortical cataract"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4848, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 293, '{"id":4848,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":293,"q":"False about treatment of cataract in children is","o":["ECCE is the treatment of choice","In case of bilateral cataract imparing vision surgery must be done by 4-6 weeks of age","Lensectomy is not one of the methods of extracapsular extraction","Intraocular lens implantation must be done only after 2 years of age"],"a":2,"e":"Ans. is ''c'' i.e., Lensectomy is not one of the methods of extracapsular extraction [Ref Textbook of pediatric cataract surgery p. 194] The critical period for developing the fixation reflex in both unilateral and bilateral visual deprivation disorders is between 2-4 months of age. Any cataract dense enough to impair vision must be dealt with before this age and the earliest possible time is preferred.","pyqMatches":[{"year":"2016","no":987,"q":"False about treatment of cataract in children is","o":["ECCE is the treatment of choice","In case of bilateral cataract imparing vision surgery must be done by 4-6 weeks of age","Lensectomy is not one of the methods of extracapsular extraction","Intraocular lens implantation must be done only after 2 years of age"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4849, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 294, '{"id":4849,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":294,"q":"What is the new advance in cataract surgery?","o":["Femtosecond Laser","Neodymium Laser","Nanosecond Laser","Picosecond Laser"],"a":0,"e":"Ans. is ''a'' i.e., Femtosecond laser [Ref Femtosecond laser- assisted cataract surgery: Kendall E. Donaldson, Rosa Braga-Mele,Florence Cabot, for the ASCRS Refractive Cataract Surgery Subcommittee] Femtosecond laser-assisted cataract surgery provides surgeons an exciting new option to potentially improve patient outcomes and safety. In this surgery a femtosecond laser is used for various steps like lens fragmentation and capsulotomy. Although the results have been good the technology is currently very expensive.","pyqMatches":[{"year":"2016","no":988,"q":"What is the new advance in cataract surgery?","o":["Femtosecond Laser","Neodymium Laser","Nanosecond Laser","Picosecond Laser"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4850, 'Ophthalmology', 'Lens & Cataract', 'Moderate', 'Ophthalmology', 295, '{"id":4850,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Moderate","source":"Ophthalmology","sourceNo":295,"q":"Which of the following step is not done during phacoemulsification surgery for cataract?","o":["Irrigation and drainage of cortex","Continuous curvilinear capsulorrhexis","Foldable IOL implantation","Sclerocorneal tunnel"],"a":3,"e":"Ans. is ''d'' i.e., Sclerocorneal tunnel [Ref Phacoemulsification by vajpayee] The steps in phacoemulsification include : (i) Corneoscleral incision, (ii) Continuous curvilinear capsulorrhexis, (iii) Hydrodissection and hydrodelineation, (iv) Emulsification and aspiration of nucleus and then cortex, (v) Foldable IOL implantation in posterior chamber.","pyqMatches":[{"year":"2016","no":989,"q":"Which of the following step is not done during phacoemulsification surgery for cataract?","o":["Irrigation and drainage of cortex","Continuous curvilinear capsulorrhexis","Foldable IOL implantation","Sclerocorneal tunnel"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4851, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 296, '{"id":4851,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":296,"q":"Phacoemulsification uses","o":["High frequency sound waves","Infrared waves","Ultraviolet rays","None of these"],"a":0,"e":"Ans. is ''a'' i.e., High frequency sound waves [Ref Kanski''s 8th/e chapter 9, p. 281] In Phacoemulsification, lens nucleus is emulsified using high frequency sound waves.","pyqMatches":[{"year":"2016","no":990,"q":"Phacoemulsification uses","o":["High frequency sound waves","Infrared waves","Ultraviolet rays","None of these"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4852, 'Ophthalmology', 'Retina & Vitreous', 'Moderate', 'Ophthalmology', 297, '{"id":4852,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Moderate","source":"Ophthalmology","sourceNo":297,"q":"Post operative complications of cataract are all except?","o":["After cataract","Endophthalmitis","Glaucoma","Scleritis"],"a":3,"e":"Ans. is ''d'' i.e., Scleritis [Ref Ophthalmology by Duker 2\"d/e p. 484] There are so many complications of cataract surgery, Here are only important ones:? After cataract (opacification of capsule) Retinal detachment Vitreous prolapse & loss Neovascular glaucoma Cystoid macular edema Anterior uveitis (iridocyclitis) Endophthalmitis Iris prolapse Aphakic glaucoma Stria keratopathy & Pseudophakic bullous keratopathy Fibrous & endothelial growth Corneal endothelial damage","pyqMatches":[{"year":"2016","no":991,"q":"Post operative complications of cataract are all except?","o":["After cataract","Endophthalmitis","Glaucoma","Scleritis"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4853, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 298, '{"id":4853,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":298,"q":"Hemeralopia is seen in","o":["Retinal detachment","Retinitis pigmentosa","Optic neuritis","Subcapsular cataract"],"a":3,"e":"Ans. is ''d'' i.e., Subcapsular cataract [Ref Kanski 8th/e Chap. 9, p. 270] Hemeralopia is the inability to see clearly in bright light ( also known as day blindness) and is the exact opposite of nyctalopia (night blindness). Subcapsular cataract Anterior subcapsular cataract lies directly under the lens capsule and is associated with fibrous metaplasia of the lens epithelium. Posterior subcapsular opacity lies just in front of the posterior capsule and has a granular or plaque-like appearance on oblique slit lamp biomicroscopy, but typically appears black and vacuolated on retroillumination; the vacuoles are swollen migratory lens epithelial cells (bladder or Wedl), similar to those commonly seen postoperatively in posterior capsular opacification. Due to its location at the nodal point of the eye, a posterior subcapsular opacity often has a particularly profound effect on vision. Patients are characteristically troubled by glare, for instance from the headlights of oncoming cars, and symptoms are increased by miosis, such as occurs during near visual activity and in bright sunlight (day blindness).","pyqMatches":[{"year":"2016","no":993,"q":"Hemeralopia is seen in","o":["Retinal detachment","Retinitis pigmentosa","Optic neuritis","Subcapsular cataract"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4854, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 299, '{"id":4854,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":299,"q":"Which of the following is a good dye is used for lens in cataract surgery?","o":["Trypan Blue","Fluoroscein","India ink","None"],"a":0,"e":"Ans. is ''A Trypan blue dye for anterior segment surgeries Trypan blue has been used as an adjunct for improving visualization of the anterior capsule during phacoemulsification of mature white cataracts for the past few years. Surgeons have long used dyes like indocyanine green, fluorescein, and trypan blue to stain the anterior capsule in order to facilitate the surgical procedure. studies comparing these 3 dyes have concluded that trypan blue provides significantly more intensive staining of the anterior lens capsule than the others Trypan blue is easier to use than indocyanine green, because it comes in a premixed solution, and it is available at a more economical price.","pyqMatches":[{"year":"2016","no":995,"q":"Which of the following is a good dye is used for lens in cataract surgery?","o":["Trypan Blue","Fluoroscein","India ink","None"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4855, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 300, '{"id":4855,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":300,"q":"Which of the following is a layer between choroid and retina?","o":["Bruch''s membrane","Descemet''s membrane","Photoreceptors","Ganglion cell layer"],"a":0,"e":"Ans. is ''a'' i.e.,Bruch''s membrane [Ref Parson''s 21\"/e p. 321] Bruch''s membrane is the innermost layer of the choroid. It is also called the vitreous lamina, because of its glassy microscopic appearance. It is 2-4 thick. It lies between choroid and the retina.","pyqMatches":[{"year":"2016","no":996,"q":"Which of the following is a layer between choroid and retina?","o":["Bruch''s membrane","Descemet''s membrane","Photoreceptors","Ganglion cell layer"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4856, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 301, '{"id":4856,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":301,"q":"100 day glaucoma is caused by","o":["CRVO","CRAO","Buphthalmos","Age related macular degeneration"],"a":0,"e":"Ans. is ''a'' i.e., CRVO 100-day glaucoma is typically seen in Ischemic CRVO. Following central retinal vein occlusion, flame-shaped haemorrhages develop in the nerve fiber layer of the retina, especially around the optic disc, as a result of the high intravascular pressure that dilates the veins and collateral vessels. Edema of the optic disc and retina occur because of impaired absorption of interstitial fluid. Vision is generally poor but may recover surprisingly well, considering the severity of the funduscopic changes. Intractable closed-angle glaucoma, with severe pain and repeated haemorrhages, commonly occurs 2 to 3 months after central retinal vein occlusion (100-day glaucoma''; ''thrombotic glaucoma''), owing to neovascularization of the iris and adhesions between the iris and the anterior chamber angle (peripheral anterior synechiae).","pyqMatches":[{"year":"2016","no":997,"q":"100 day glaucoma is caused by","o":["CRVO","CRAO","Buphthalmos","Age related macular degeneration"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4857, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 302, '{"id":4857,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":302,"q":"Keeth Wagner classification is for","o":["Hypertensive retinopathy","Diabetic maculpathy","CRVO","CRAO"],"a":0,"e":"Ans. is ''a'' i.e.,Hypertensive retinopathy [Ref Robart W. Schrier 8\"/e p. 1377]","pyqMatches":[{"year":"2016","no":998,"q":"Keeth Wagner classification is for","o":["Hypertensive retinopathy","Diabetic maculpathy","CRVO","CRAO"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4858, 'Ophthalmology', 'Uvea', 'Easy', 'Ophthalmology', 303, '{"id":4858,"subject":"Ophthalmology","chapter":"Uvea","difficulty":"Easy","source":"Ophthalmology","sourceNo":303,"q":"In which of the following, intraocular pressure is very high and inflammation is minimum?","o":["Glaucomatocyclic crisis","Acute iridocyclitis","Hypetensive uveitis","Angle closure glaucoma"],"a":0,"e":"Ans. is ''a'' i.e.,Glaucomatocyclic crisis [Ref Khurana 4th/e p. 160] Glaumatocyclic crisis Glamatocyclitic crisis (Posner - Schlossman syndrome) is a unilateral recurrent non- granulomatous iritis that is associated with an elevated ocular pressure during the attacks. This self- limiting condition tends to occur in persons during the third to sixth decade and the visual fields, the optic nerve head, and anterior chamber angle are normal. A mild inflammatory reaction is very rarely present as evidenced by a few keratic precipitates on the posterior surface of the cornea. The cause of the glaucoma remains unknown, but a trabeculitis is suspected. Many patients (55%) subsequently develop open angle glaucoma","pyqMatches":[{"year":"2016","no":1001,"q":"In which of the following, intraocular pressure is very high and inflammation is minimum?","o":["Glaucomatocyclic crisis","Acute iridocyclitis","Hypetensive uveitis","Angle closure glaucoma"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4859, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 304, '{"id":4859,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":304,"q":"Cell bodies of Muller''s Cells are present in which layer of retina?","o":["Inner limiting membrane","Outer nuclear layer","Retinal pigment epithelium","Ganglion cell layer"],"a":0,"e":"Ans. is ''a'' i.e., Inner limiting membrane [Ref Histology of the Eye, edited by William Krause, Dept. Pathology and Anatomical science, University of Missouri School of Medicine] Inner limiting membrane - basement membrane elaborated by Muller cells. Nerve fibre layer - axons of the ganglion cell nuclei (note that a thin layer of Muller cell footplates exists between this layer and the inner limiting membrane). Ganglion cell layer - contains nuclei of ganglion cells, the axons of which become the optic nerve fibres for messages and some displaced amacrine cells. Inner plexiform layer - contains the synapse between the bipolar cell axons and the dendrites of the ganglion and amacrine cells. Inner nuclear layer - contains the nuclei and surrounding cell bodies (perikarya) of the amacrine cells, bipolar cells and horizontal cells. Outer plexiform layer - projections of rods and cones ending in the rod spherule and cone pedicle, respectively. These make synapses with dendrites of bipolar cells. In the macular region, this is known as the Fiber layer of Henle. Outer nuclear layer - cell bodies of rods and cones. External limiting membrane - layer that separates the inner segment portions of the photoreceptors from their cell nucleus. Layer of rods and cones - layer of rod cells and cone cells. Retinal pigment epithelium - single layer of cuboidal cells. This is closest to the choroid.","pyqMatches":[{"year":"2016","no":1002,"q":"Cell bodies of Muller''s Cells are present in which layer of retina?","o":["Inner limiting membrane","Outer nuclear layer","Retinal pigment epithelium","Ganglion cell layer"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4860, 'Ophthalmology', 'Cornea & External Eye', 'Moderate', 'Ophthalmology', 305, '{"id":4860,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Moderate","source":"Ophthalmology","sourceNo":305,"q":"Which of the following is true about signs of angle in closure glaucoma except","o":["Vertical semi dialted puil","Edematous cornea","Multiple iris nodules","Edematous and hyperemic optic disc"],"a":2,"e":"Ans. is ''c'' i.e., Multiple iris nodules [Ref Parson''s 21\"/e p. 290] Clinical features of angle closure glaucoma Conjunctiva is chemosed and congested (both conjunctival & ciliary vessels are congested). Cornea is oedematous and insensitive Anterior chamber is very shallow & with aqueous flare Angle of anterior chamber is closed (on gonioscopy) Iris is discoloured Pupil is semidilated, vertically oval and fixed. It is non reactive to both light and accommodation. IOP is markedly raised (40- 70 mm Hg) Optic disc is oedematous & hyperemic Fellow eye shows shallow anterior chamber and a narrow angle.","pyqMatches":[{"year":"2016","no":1005,"q":"Which of the following is true about signs of angle in closure glaucoma except","o":["Vertical semi dialted puil","Edematous cornea","Multiple iris nodules","Edematous and hyperemic optic disc"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4861, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 306, '{"id":4861,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":306,"q":"Which of the following is false statement about vitreous?","o":["Anatomically, vitreous is present in anterior segment","Vitreous largely contain water and hyaluronic acid","Strongest attachment of vitreous base is at ora serrata","Vitreous is attached anteriorly to the lens"],"a":0,"e":"Ans. is ''a'' i.e., Anatomically, vitreous is present in anterior segment [Ref Kanski 8thie Chap. 17, p. 722] Vitreous is present in posterior segment of eye. Vitreous humor is a jelly like fluid liquid that fills most (80%) of the eye (from the lens back, i.e., in the posterior segment). The vitreous consists largely of water (99%), a network of collagen fibrils, large molecules of hyaluronic acid, peripheral cells (hyalocytes), and mucopolysaccharides, forming a gel - like material. There is a potential space between vitreous and retina, called subhyaloid space. As we age, vitreous changes from a gel to a liquid and gradually shrinks separating from the retina. This is when people start seeing floaters (black spots in front of the eye).","pyqMatches":[{"year":"2016","no":1006,"q":"Which of the following is false statement about vitreous?","o":["Anatomically, vitreous is present in anterior segment","Vitreous largely contain water and hyaluronic acid","Strongest attachment of vitreous base is at ora serrata","Vitreous is attached anteriorly to the lens"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4862, 'Ophthalmology', 'Lens & Cataract', 'Moderate', 'Ophthalmology', 307, '{"id":4862,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Moderate","source":"Ophthalmology","sourceNo":307,"q":"Phacodonesis is seen in all except","o":["Traumatic injury to the eye","Hypermature cataract","Pseudoexfoliation","Diabetes mellitus"],"a":3,"e":"Ans. is ''d'' i.e., Diabetes mellitus [Ref Kanski 8thie p. 300] Phacodonesis is the tremulousness or vibration of the lens with eye movement. It is seen in:","pyqMatches":[{"year":"2016","no":1007,"q":"Phacodonesis is seen in all except","o":["Traumatic injury to the eye","Hypermature cataract","Pseudoexfoliation","Diabetes mellitus"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4863, 'Ophthalmology', 'Ocular Motility & Strabismus', 'Easy', 'Ophthalmology', 308, '{"id":4863,"subject":"Ophthalmology","chapter":"Ocular Motility & Strabismus","difficulty":"Easy","source":"Ophthalmology","sourceNo":308,"q":"Which of the following is true about divergent squint","o":["It is also called exotropia","It is more common than convergent squint","It is a feature of 6th nerve palsy","All of the following"],"a":0,"e":"Ans. is ''a'' i.e., It is also called exotropia [Ref Pediatric strabismus 4th/e p. 218-224] Divergent squint is also called as exotropia. It less common than convergent squint (esotropia). 6th nerve palsy causes convergent squint.","pyqMatches":[{"year":"2016","no":1011,"q":"Which of the following is true about divergent squint","o":["It is also called exotropia","It is more common than convergent squint","It is a feature of 6th nerve palsy","All of the following"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4864, 'Ophthalmology', 'Optic Nerve & Neuro-ophthalmology', 'Easy', 'Ophthalmology', 309, '{"id":4864,"subject":"Ophthalmology","chapter":"Optic Nerve & Neuro-ophthalmology","difficulty":"Easy","source":"Ophthalmology","sourceNo":309,"q":"Crossed eye fixation is positive in -","o":["Esotropia","Exotropia","Hypertropia","Hypotropia"],"a":0,"e":"Ans. is ''a'' i.e.,Esotropia [Ref Internet] Cross fixation is the use of the right eye to view the left visual field and the use of the left eye to view the right visual field. This behavior is very common in children with infantile esotropia. Cross fixation often causes the appearance of not looking directly at a target and parents often wonder if vision is reduced.","pyqMatches":[{"year":"2016","no":1012,"q":"Crossed eye fixation is positive in","o":["Esotropia","Exotropia","Hypertropia","Hypotropia"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4865, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Easy', 'Ophthalmology', 310, '{"id":4865,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Easy","source":"Ophthalmology","sourceNo":310,"q":"Partial ptosis is oculomotor nerve injury is due to intact -","o":["Supply from opposite oculomotor nerve","Sympathetic innervation","Parasympathetic innervation","Action of orbicularis oculi"],"a":1,"e":"Ans. is ''b'' i.e., Sympathetic innervation [Ref Textbook of ophthalmic reconstructive surgeries p. 786] Motor nerve supply of lid is through three sources :?","pyqMatches":[{"year":"2016","no":1013,"q":"Partial ptosis is oculomotor nerve injury is due to intact","o":["Supply from opposite oculomotor nerve","Sympathetic innervation","Parasympathetic innervation","Action of orbicularis oculi"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4866, 'Ophthalmology', 'Lens & Cataract', 'Moderate', 'Ophthalmology', 311, '{"id":4866,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Moderate","source":"Ophthalmology","sourceNo":311,"q":"Retinoblastomas show all of the following except","o":["Small round cells","Necrosis","Pseudorosettes and Fleurettes","None"],"a":3,"e":"Ans. ''d'' is None (All are seen) [Ref Khurana 4thie p. 281] Histology of retinoblastomas The tumor arises from small round cells with large nuclei, i.e., it is a tumor of a group called small round blue cell tumors. Microscopic features of a well differentiated tumor include Flexnerwintersteiner rosettes (specific for retinoblastoma), Homer Wright rosettes, pseudorosettes and fleurettes formation.","pyqMatches":[{"year":"2016","no":1015,"q":"Retinoblastomas show all of the following except","o":["Small round cells","Necrosis","Pseudorosettes and Fleurettes","None"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4867, 'Ophthalmology', 'Optic Nerve & Neuro-ophthalmology', 'Easy', 'Ophthalmology', 312, '{"id":4867,"subject":"Ophthalmology","chapter":"Optic Nerve & Neuro-ophthalmology","difficulty":"Easy","source":"Ophthalmology","sourceNo":312,"q":"Which of the following is most common visual defect in papilloedema","o":["Amourosis fugax","Homonymous hemianopia","Homonymous quadrantopia","Glare"],"a":0,"e":"Ans. is ''a'' i.e., Amourosis fugax [Ref Clinical opthalmology 2\"d% p. 349, 350] Initially the symptoms of papilloedema are due to increased ICT, e.g. headache, nausea, projectile vomiting and papilloedema. Vision is normal initially. In 25% of patients visual symptoms occur only in advanced severe papilloedema, when optic atrophy sets in. Typically, there is recurring brief episodes (transient) of visual obscurations (Amaurosis fugax) lasting less then 30 seconds, in which vision turns grey or blacks, sometimes decribed as if a veil has fallen over the eyes. The symptoms usually affect both eyes at once as papilloedema is bilateral. Central vision is affected late in the disease. Initially there is enlargement of blind spot and progressive contraction of the visual field (visual field becomes smaller). Complete blindness sets in eventually. Thus, characteristically there is gradually progressive painless loss of vision","pyqMatches":[{"year":"2016","no":1016,"q":"Which of the following is most common visual defect in papilloedema","o":["Amourosis fugax","Homonymous hemianopia","Homonymous quadrantopia","Glare"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4868, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Easy', 'Ophthalmology', 313, '{"id":4868,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Easy","source":"Ophthalmology","sourceNo":313,"q":"What is the treatment of meibomianitis ?","o":["Cleansing the lid edges","Application of moist heat","Local antibiotics","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above [Ref Foster CS. The eye in skin and mucous membrane disorders. In: Tasman W, Jaeger EA, eds. Duane''s Ophthalmology . 15th ed. Philadelphia, Pa: Lippincott Williams & Wilkins; 2009:chap 27] Meibomianitis Meibomianitis is inflammation of the meibomian glands, a group of oil-releasing (sebaceous) glands in the eyelids. Causes Any condition that increases the oily secretions of the meibomian glands will allow excess oils to build up on the edges of the eyelids. This allows for the excess growth of bacteria that are normally present on the skin. These problems can be caused by allergies, hormone changes during adolescence, or skin conditions such as rosacea and acne. Meibomianitis is often associated with blepharitis, which can cause a buildup of a dandruff-like substance at the base of the eyelashes. In some people with meibomianitis, the glands will be plugged so that there is less oil being made for the normal tear film. These people often have symptoms of dry eye.","pyqMatches":[{"year":"2016","no":1017,"q":"What is the treatment of meibomianitis ?","o":["Cleansing the lid edges","Application of moist heat","Local antibiotics","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4869, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 314, '{"id":4869,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":314,"q":"Most common site of basal cell carcinoma of the eye is","o":["Eyelid","Conjunctiva","Cornea","Lacrimal apparatus"],"a":0,"e":"Ans. is ''a'' i.e., Eyelid [Ref Renu Jogi 4th/e p. 420; Khurana 4th/e p. 360] Basal cell carcinoma is the commonest malignant tumor of the lids (90%) usually seen in elderly people. It is locally malignant and involves most commonly lower lid (50%) followed by media! canthus (25%), upper lid (10-15%) and outer canthus. \"Basal cell carcinoma is seen in the lower lid near the inner canthus usually","pyqMatches":[{"year":"2016","no":1019,"q":"Most common site of basal cell carcinoma of the eye is","o":["Eyelid","Conjunctiva","Cornea","Lacrimal apparatus"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4870, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Easy', 'Ophthalmology', 315, '{"id":4870,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Easy","source":"Ophthalmology","sourceNo":315,"q":"Ankyloblepheron is defined as","o":["Adhesion of the lid to the eyeballs","Adhesion of the lid margins to each other","Inturned eyelash","Inflammation of the lid margin"],"a":1,"e":"Ans is ''b'' i.e., Adhesion of the lid margins to each other [Ref: Kanski 8th le p. 52] Disorders of the eyelids Blepharitis :- Chronic inflammation of lid margin. Blephritis acarica : Inflammation of lid margin caused by Demodex folliculorum. Madarosis :- Loss of eye lashes. Trichiasis :- Misdirected eyelashes which rub against the eyeball in normal position of lid margin. Distichiasis :- an abnormal extra row of cilia taking place of meibomian glands. Entropion :- Inward rolling or inturning of lid margin. Ectropion :- Out rolling or outward turning of lid margin. Symblepharon :- Adhesion of the lids to eyeball. Ankyloblepharon :- Adhesion of margins of two eyelids. Blepharophimosis Palpebral fissure appears to be contracted at the outer canthus. Lagophthalmos :- Incomplete closure of the palpebral aperture when eyes are shut. Tylosis :- Thickening of lid margin. Basal cell carcinoma :- Most common malignant tumor of eyelid Cloboma of lid :- Triangular gap in nasal side of upper lid","pyqMatches":[{"year":"2016","no":1021,"q":"Ankyloblepheron is defined as","o":["Adhesion of the lid to the eyeballs","Adhesion of the lid margins to each other","Inturned eyelash","Inflammation of the lid margin"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4871, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Easy', 'Ophthalmology', 316, '{"id":4871,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Easy","source":"Ophthalmology","sourceNo":316,"q":"The globe is displaced to which side in lacrimal gland tumour?","o":["Inferotemporal","Inferonasal","Superotemoral","Nasal"],"a":1,"e":"Ans. is ''b'' i.e., Inferonasal [Ref Bernardini FP, Devoto MH, Croxatto JO. Epithelial tumors of the lacrimal gland: an update. Curr Opin Ophthalmol 2008;19:409-13] All lacrimal gland tumors typically share the following symptoms: facial asymmetry due to displacement of the globe, diplopia, ptosis, limited ocular motility, and enlargement of the lacrimal gland. Epithelial lesions tend to develop mostly in the orbital lobe of the lacrimal gland and are principally unilateral. The initial sign is usually inferior and nasal displacement of the globe and proptosis, due to the superotemporal location of the lacrimal gland in the anterior aspect of the orbit.","pyqMatches":[{"year":"2016","no":1022,"q":"The globe is displaced to which side in lacrimal gland tumour?","o":["Inferotemporal","Inferonasal","Superotemoral","Nasal"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4872, 'Ophthalmology', 'Uvea', 'Easy', 'Ophthalmology', 317, '{"id":4872,"subject":"Ophthalmology","chapter":"Uvea","difficulty":"Easy","source":"Ophthalmology","sourceNo":317,"q":"''D'' shaped pupil is seen in","o":["Glaucoma","Dislocation of lens","Iridodialysis","Iridocyclitis"],"a":2,"e":"Ans. is ''c'' i.e., Iridodialysis [Ref Khurana 4thie p. 404] Iridodialysis is detachment of iris from its root at the ciliary body. It results in D shaped pupil and a lack biconvex area seen at the periphery.","pyqMatches":[{"year":"2015","no":1062,"q":"D Shaped pupil is seen in ?","o":["Iridodialysis","Iridodonesis","Anterior Uveitis","Anterior synechiae"],"a":0,"source":"NEET_2015_Paper.pdf"},{"year":"2016","no":1023,"q":"''D'' shaped pupil is seen in","o":["Glaucoma","Dislocation of lens","Iridodialysis","Iridocyclitis"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2015","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4873, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 318, '{"id":4873,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":318,"q":"Investigation of choice for optic neuritis is ?","o":["MRI Brain and orbit","Ct scan Brain and orbit","Vitreous biopsy","Electooculogram"],"a":0,"e":"Ans. is ''a'' i.e., MRI Brain and orbit [Ref Kanski 8th/e Chap. 19, p. 784] Magnetic Resonance Imaging (MRI) is far more superior for the study of soft tissue and thus, for most neuro-ophthalmic conditions, MRI is the investigation of choice.","pyqMatches":[{"year":"2015","no":1671,"q":"Investigation of choice for optic neuritis is ?","o":["MRI Brain and orbit","Ct scan Brain and orbit","Vitreous biopsy","Electooculogram"],"a":0,"source":"NEET_2015_Paper.pdf"},{"year":"2016","no":1024,"q":"Investigation of choice for optic neuritis is ?","o":["MRI Brain and orbit","Ct scan Brain and orbit","Vitreous biopsy","Electooculogram"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2015","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4874, 'Ophthalmology', 'Lens & Cataract', 'Moderate', 'Ophthalmology', 319, '{"id":4874,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Moderate","source":"Ophthalmology","sourceNo":319,"q":"Ocular findings in diabetes are all except -","o":["Retinopathy","Early senile cataract","Neovascular glaucoma","Blepharophimosis"],"a":3,"e":"Ans. is ''d'' i.e., Blepharophimosis [Ref Kanski''s 8`Ve chapter 13, p. 520]","pyqMatches":[{"year":"2016","no":1026,"q":"Ocular findings in diabetes are all except","o":["Retinopathy","Early senile cataract","Neovascular glaucoma","Blepharophimosis"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4875, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 320, '{"id":4875,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":320,"q":"Which of the following is a long term side effect of phakic 10Ls","o":["Chronic glaucoma","Retinal detachment","Optic neuritis","None"],"a":0,"e":"Ans. is ''a'' i.e., Chronic glaucoma [Ref Chen LI, et al. Metaanalysis of cataract development after phakic intraocular lens surgery. J Cataract Refract Surg 2008;34:1181-200.] Phakic intraocular lenses (pIOLs) are artificial lenses that are inserted either on top of the iris or in between the iris and the natural lens. They are used to treat refractive error without removing cornea tissue or the lens. Long term risks of phakic IOLS Chronic intraocular pressure elevation can produce indolent vision damage from angle closure glaucoma. The surgical procedure itself also induces some endothelial cell damage and if the prosthetic is in close proximity to the cornea, chronic loss could be induced. Finally, chronic inflammation or prosthetic-lens touch can induce cataract formation","pyqMatches":[{"year":"2016","no":1028,"q":"Which of the following is a long term side effect of phakic 10Ls","o":["Chronic glaucoma","Retinal detachment","Optic neuritis","None"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4876, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 321, '{"id":4876,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":321,"q":"Most common protozoan causing keratitis is","o":["Plasmodium","Acanthamoeba","Toxoplasma","W. bancrofti"],"a":1,"e":"Ans. is `b'' i.e., Acanthamoeba [Ref Kanski 8th/e p. 197] \"Acanthamoeba keratitis is the most common keratitis caused by a protozoan especially in contact lens users\".","pyqMatches":[{"year":"2012","no":938,"q":"Most common protozoan causing keratitis is","o":["Plasmodium","Acanthamoeba","Toxoplasma","W. bancrofti"],"a":1,"source":"NEET_2012_Paper.pdf"},{"year":"2016","no":1029,"q":"Most common protozoan causing keratitis is","o":["Plasmodium","Acanthamoeba","Toxoplasma","W. bancrofti"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2012","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4877, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 323, '{"id":4877,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":323,"q":"Treatment of acute dacrocystitis in stage of cellulitis is ?","o":["Antibiotics","Abscess drainage","DCT","DCR"],"a":0,"e":"Ans. A. Antibiotics Treatment of acute dacyrocystitis During cellulitis stage It consists of systemic and topical antibiotics to control infection; and systemic anti-inflammatory analgesic drugs and hot fomentation to relieve pain and swelling.","pyqMatches":[{"year":"2014","no":1225,"q":"Treatment of acute dacrocystitis in stage of cellulitis is ?","o":["Antibiotics","Abscess drainage","DCT","DCR"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4878, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 324, '{"id":4878,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":324,"q":"What is the correct sequence of xerophthalmia","o":["Nightblindness 4 Conjunctival xerosis → corneal xerosis - corneal ulcer","Conjunctival xerosis → corneal xerosis → corneal ulcer → Nightblindness","Corneal xerosis → corneal ulcer 4 Nightblindness → Conjunctival xerosis","Corneal ulcer → Nightblindness → Conjunctival xerosis -3 corneal xerosis"],"a":0,"e":"Ans. A. Nightblindness 4 Conjunctival xerosis → corneal xerosis - corneal ulcer","pyqMatches":[{"year":"2014","no":1234,"q":"What is the correct sequence of xerophthalmia","o":["Nightblindness 4 Conjunctival xerosis → corneal xerosis - corneal ulcer","Conjunctival xerosis → corneal xerosis → corneal ulcer → Nightblindness","Corneal xerosis → corneal ulcer 4 Nightblindness → Conjunctival xerosis","Corneal ulcer → Nightblindness → Conjunctival xerosis -3 corneal xerosis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4879, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 325, '{"id":4879,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":325,"q":"Which eye muscle has radial, longitudinal and circular fibres?","o":["Sphinctor Pupillae","Dilator Pupillae","Levator palpebrae Superioris","Ciliary muscle"],"a":3,"e":"Ans. D. Ciliary muscle The ciliary muscle is a ring of smooth muscle in the eye''s middle layer (vascular layer) that controls accommodation for viewing objects at varying distances and regulates the flow of aqueous humour into Schlemm''s canal. It changes the shape of the lens within the eye. The ciliary fibers have circular, longitudinal (meridional) and radial orientations.","pyqMatches":[{"year":"2015","no":984,"q":"Which eye muscle has radial, longitudinal and circular fibres?","o":["Sphinctor Pupillae","Dilator Pupillae","Levator palpebrae Superioris","Ciliary muscle"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4880, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 326, '{"id":4880,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":326,"q":"Required for IOL power calculation ?","o":["Corneal topography","Gonioscopy","Indirect Ophthalmoscopy","Keratometry"],"a":3,"e":"Ans, D. Keratometry IOL power calculation requires keratometry and biometry (axial length of eyeball).","pyqMatches":[{"year":"2015","no":987,"q":"Required for IOL power calculation ?","o":["Corneal topography","Gonioscopy","Indirect Ophthalmoscopy","Keratometry"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4881, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 327, '{"id":4881,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":327,"q":"Immediate treatment of acute dacryocystitis is?","o":["Antibiotics and drainage of abscesss if present","Dacryocystorhinostomy","Dacryocystectomy","Nasal decongestants"],"a":0,"e":"Ans. A. Antibiotics and drainage of abscesss if present","pyqMatches":[{"year":"2015","no":1074,"q":"Immediate treatment of acute dacryocystitis is?","o":["Antibiotics and drainage of abscesss if present","Dacryocystorhinostomy","Dacryocystectomy","Nasal decongestants"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4882, 'Ophthalmology', 'Refraction & Optics', 'Easy', 'Ophthalmology', 328, '{"id":4882,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Easy","source":"Ophthalmology","sourceNo":328,"q":"True about imaging spectrometry is ?","o":["Allows simultaneous measurements of reflectance spectra along a line","Is useful in diagnosing against the rule astigmatism","Spectrometry is an essential investigation before trabeculectomy","It is based on the principle of Sturm''s Conoid"],"a":0,"e":"Ans. A. Allows simultaneous measurements of reflectance spectra along a line ''Imaging sPectrometry is a new technique that permits simultaneous measurements of reflectance spectra at different locations along a line. Results are three-dimensional images, whose coordinates are location, wavelength, and reflectance. A conventional fundus camera is adapted to a spectrograph and an intensified charge coupled device (CCD) matrix detector system. Considering the radiation transPort in single fundus layers, the local distribution of the concentration-thickness product of xanthophyll, melanin, and choroidal blood can be calculated''","pyqMatches":[{"year":"2015","no":989,"q":"True about imaging spectrometry is ?","o":["Allows simultaneous measurements of reflectance spectra along a line","Is useful in diagnosing against the rule astigmatism","Spectrometry is an essential investigation before trabeculectomy","It is based on the principle of Sturm''s Conoid"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4883, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 329, '{"id":4883,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":329,"q":"The principle of total internal reflection is used by?","o":["Gonioscope","Pachymeter","Ophthalmoscope","Lensometer"],"a":0,"e":"Ans. A Gonioscopy is an essential diagnostic tool and examination technique used to visualize the structures of the anterior chamber angle. Mastering the various techniques of gonioscopy is crucial in the evaluation of glaucoma patients. Gonioscopy is required to visualize the chamber angle because under normal conditions light reflected from the angle structures undergoes total internal reflection at the tear–air interface. At the tear–air interface, the critical angle (approximately 46°) is reached and light is totally reflected back into the corneal stroma. This prevents direct visualization of the angle structures. All gonioscopy lenses eliminate the tear–air interface by placing a plastic or glass surface adjacent to the front surface of the eye. The small space between the lens and cornea is filled by the patient’s tears, saline solution, or a clear viscous substance. Depending on the type of lens","pyqMatches":[{"year":"2015","no":1073,"q":"The principle of total internal reflection is used by?","o":["Gonioscope","Pachymeter","Ophthalmoscope","Lensometer"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4884, 'Ophthalmology', 'Refraction & Optics', 'Moderate', 'Ophthalmology', 330, '{"id":4884,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Moderate","source":"Ophthalmology","sourceNo":330,"q":"Refractory error measured by all except ?","o":["Keratometry","Retinoscopy","Refractometry","Spectrometry"],"a":3,"e":"Ans. D. Spectrometry The procedure of determining and correcting refractive errors is termed as reftaction. The refraction comprises two complementary methods : -","pyqMatches":[{"year":"2015","no":990,"q":"Refractory error measured by all except ?","o":["Keratometry","Retinoscopy","Refractometry","Spectrometry"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4885, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 331, '{"id":4885,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":331,"q":"Ansiokonia is ?","o":["Projection of different coloured images into visual cortex","Projection of different shaped images into visual cortex of two retinae","Change in the velocity of perceived objects","Partial intermittent visual loss"],"a":1,"e":"Ans. B. Projection of different shaped images into visual cortex of two retinae Anisoeikonia is defined as a condition wherein the images projected on the visual cortex from the two retinae are abnormally unequal in size or shape-","pyqMatches":[{"year":"2015","no":991,"q":"Ansiokonia is ?","o":["Projection of different coloured images into visual cortex","Projection of different shaped images into visual cortex of two retinae","Change in the velocity of perceived objects","Partial intermittent visual loss"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4886, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 332, '{"id":4886,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":332,"q":"Parasitosis of extraocular eye muscles is seen in?","o":["Trichinosis","Cysticercosis","Amoebiasis","Ascariasis"],"a":0,"e":"Ans, A. Trichinosis ''Although many parasites can theoretically involve the extraocular muscle the most frequent form of parasitic infestation of extraocular muscles is trichinosis''","pyqMatches":[{"year":"2015","no":1072,"q":"Parasitosis of extraocular eye muscles is seen in?","o":["Trichinosis","Cysticercosis","Amoebiasis","Ascariasis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4887, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 333, '{"id":4887,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":333,"q":"Most powerful refractory surface of eye is -","o":["Conjunctiva","Cornea","Vitreous","Lens"],"a":1,"e":"Ans. B. Cornea The cornea, with the anterior chamber and lens, refracts light, with the cornea accounting for approximately two-thirds of the eye''s total optical power. In humans, the refractive power of the cornea is approximately 43 dioptres. The diopteric power of reduced eye is + 5OD, of which + 44D is contributed by cornea and + 16D by the crystalline lens. Total diaopteric power of schematic eye is + 58D, of which cornea contributes +43D and the lens +15D.","pyqMatches":[{"year":"2015","no":992,"q":"Most powerful refractory surface of eye is","o":["Conjunctiva","Cornea","Vitreous","Lens"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4888, 'Ophthalmology', 'Refraction & Optics', 'Easy', 'Ophthalmology', 334, '{"id":4888,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Easy","source":"Ophthalmology","sourceNo":334,"q":"Astigmatism is defined as ?","o":["Refractory error wherein refraction varies along different meridians","Refractory error due to long AP length of eye ball","Varying refractory error in both eyes","Varying Shape perception by both eyes"],"a":0,"e":"Ans. A. Refractory error wherein refraction varies along different meridians Astigmatism is a type of refractive error wherein the refraction varies in the different meridia. Consequently, the rays of light entering in the eye cannot converge to a point focus but form focal lines. The refractive error of the astigmatic eye stems from a difference in degree of curvature refraction of the two different meridians (i.e., the eye has different focal point in different planes). For example, the image may be clearly focused on retina in the horizontal plane, but not in the vertical plane. The most common cause of astigmatism is abnormality of corneal curvature. Other less common cause are lenticular (curvature abnormality of lens,oblique position of lens) and retinal (oblique placement of macula).","pyqMatches":[{"year":"2015","no":994,"q":"Astigmatism is defined as ?","o":["Refractory error wherein refraction varies along different meridians","Refractory error due to long AP length of eye ball","Varying refractory error in both eyes","Varying Shape perception by both eyes"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4889, 'Ophthalmology', 'Miscellaneous', 'Moderate', 'Ophthalmology', 335, '{"id":4889,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Ophthalmology","sourceNo":335,"q":"CHARGE syndrome includes all except ?","o":["Eye Coloboma","Congenital heart disease","Urinary tract defects","Esophageal Atresia"],"a":3,"e":"Ans, D. Esophageal Atresia CHARGE SYNDROME C - Coloboma of the eye, central nervous system anomalies. H-Heartdefects. A - Atresia ofthechoanae. R - Retardation of growth and/or development. G - Genital and/or urinary defects (Hypogonadism, undescended testicles, besides hypospadias). E - Ear anomalies and/or deafrress and abnormally bowl-shaped and concave ears, known as ''lop ears\".","pyqMatches":[{"year":"2015","no":1071,"q":"CHARGE syndrome includes all except ?","o":["Eye Coloboma","Congenital heart disease","Urinary tract defects","Esophageal Atresia"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4890, 'Ophthalmology', 'Refraction & Optics', 'Easy', 'Ophthalmology', 336, '{"id":4890,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Easy","source":"Ophthalmology","sourceNo":336,"q":"Anteroposterior change in length of eye is called ?","o":["Anisokonia","Curvatural anisotropia","Axial Ametropia","Emmetropia"],"a":2,"e":"Ans. C. Axial Ametropia Ametropia (a condition of refractive error) is defined as a state of refraction, wherein the parallel rays of light coming from infinity are not focused on retina, rather focused either in front (in myopia) or behind (in hypermetropia) the sensitive layer of retina. Axial Ametropia: It is the commonest form of ametropia (both myopia and hypermetropia). In hypermetropia, there is an axial shortening of eyeball. So, image is formed behind the retina. In myopia, there is an axial lengthening of eyeball. So, image is formed in front of the retina. 1 mm change in axial length leads to ametropia of 3D. For example 1 mm shortening in axial length causes hypermetropia of 3D.","pyqMatches":[{"year":"2015","no":996,"q":"Anteroposterior change in length of eye is called ?","o":["Anisokonia","Curvatural anisotropia","Axial Ametropia","Emmetropia"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4891, 'Ophthalmology', 'Retina & Vitreous', 'Moderate', 'Ophthalmology', 337, '{"id":4891,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Moderate","source":"Ophthalmology","sourceNo":337,"q":"Features of Usher''s Syndrome include all except ?","o":["Night Blindness","Visual Impairment","Multiple Neurofibromas","Hearing deficit"],"a":2,"e":"Ans. C. Multiple Neurofibromas Usher syndrome Usher syndrome is a relatively rare genetic disorder caused by a mutation in any one of at least I I genes resulting in a combination of hearing loss and visual impairment, and is a leading cause of deafblindness. Usher syndrome is incurable at present. Other names for Usher syndrome include Hallgren syndrome, Usher-Hallgren syndrome, retinitis pigmentosadysacusissyndrome, and dystrophia retinae dysacusis syndrome. This syndrome is characterized by hearing loss and a gradual visual impairment. The hearing loss is caused by a defective inner ear, whereas the vision loss results from retinitis pigmentosa (RP), a degeneration of the retinal cells. Usually, the rod cells of the retina are affected first, leading to early night blindness and the gradual loss of peripheral vision. In other cases, early degeneration of the cone cells in the macula occurs, leading to a loss of central acuity. In some cases, the foveal vision is spared, leading to ''doughnut vision\"; central and peripheral vision are intact, but an annulus exists around the central region in which vision is impaired.","pyqMatches":[{"year":"2015","no":983,"q":"Features of Usher''s Syndrome include all except ?","o":["Night Blindness","Visual Impairment","Multiple Neurofibromas","Hearing deficit"],"a":2,"source":"NEET_2015_Paper.pdf"},{"year":"2015","no":1069,"q":"Features of Usher''s Syndrome include all except ?","o":["Night Blindness","Visual Impairment","Multiple Neurofibromas","Hearing deficit"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4892, 'Ophthalmology', 'Cornea & External Eye', 'Hard', 'Ophthalmology', 338, '{"id":4892,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Hard","source":"Ophthalmology","sourceNo":338,"q":"In a case of myopia, LASIK will provide correction upto ?","o":["20D","12D","6D","4D"],"a":1,"e":"Ans. B. 12D Surgical Procedure Myopia correction Radial Keratomy -2to - 6D Photorefractive keraotomy2to 6D LASIK Upto - 12D Extraction of lens -16to -18D Phakic IOL >-12D Intercorneal ring (ICR) 1-6D","pyqMatches":[{"year":"2015","no":997,"q":"In a case of myopia, LASIK will provide correction upto ?","o":["20D","12D","6D","4D"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4893, 'Ophthalmology', 'Uvea', 'Easy', 'Ophthalmology', 339, '{"id":4893,"subject":"Ophthalmology","chapter":"Uvea","difficulty":"Easy","source":"Ophthalmology","sourceNo":339,"q":"What is the most common eye lesion in HIV?","o":["Kaposi Sarcoma of Lid","CMV Retinitis","Cotton wool spots","Choroiditis"],"a":2,"e":"Ans. C. Cotton wool spots The most common abnorrnal finding on fundoscopic examination is cofton-wool spots.","pyqMatches":[{"year":"2015","no":1068,"q":"What is the most common eye lesion in HIV?","o":["Kaposi Sarcoma of Lid","CMV Retinitis","Cotton wool spots","Choroiditis"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4894, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 340, '{"id":4894,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":340,"q":"What is reverse hypopyon?","o":["Collection of pus in the vireous","Collection of emulsified silicon oil in anterior chamber","Abscess in the orbit","Seen in corneal ulcer close to being ruptured"],"a":1,"e":"Ans, B. Collection of emulsified silicon oil in anterior chamber Reverse hypopyon Collection of silicon oil in the anterior chamber may lead to the appearance of a reverse hypopyon. This is due to the emulsified oil being less denser than the aqueous layer","pyqMatches":[{"year":"2015","no":998,"q":"What is reverse hypopyon?","o":["Collection of pus in the vireous","Collection of emulsified silicon oil in anterior chamber","Abscess in the orbit","Seen in corneal ulcer close to being ruptured"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4895, 'Ophthalmology', 'Refraction & Optics', 'Easy', 'Ophthalmology', 341, '{"id":4895,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Easy","source":"Ophthalmology","sourceNo":341,"q":"Silk retina is seen in ?","o":["Hypermetropia","Myopia","Astigmatism","Presbyopia"],"a":0,"e":"Ans. A. Hypermetropia Clinical findings of hypermetropia","pyqMatches":[{"year":"2015","no":1000,"q":"Silk retina is seen in ?","o":["Hypermetropia","Myopia","Astigmatism","Presbyopia"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4896, 'Ophthalmology', 'Ocular Motility & Strabismus', 'Moderate', 'Ophthalmology', 342, '{"id":4896,"subject":"Ophthalmology","chapter":"Ocular Motility & Strabismus","difficulty":"Moderate","source":"Ophthalmology","sourceNo":342,"q":"All of the following drugs increase the risk of postoperative nausea and vomiting after squint surgery in children except ?","o":["Halothane","Opiods","Propofol","Nitrous Oxide"],"a":2,"e":"Ans, C. Propofol Strabismus surgery on children is an independent risk factor for postoperative nausea and vomiting. Propofol Is Used In Predisposed Individuals As It Has VeryLessEmetogenecity","pyqMatches":[{"year":"2015","no":1067,"q":"All of the following drugs increase the risk of postoperative nausea and vomiting after squint surgery in children except ?","o":["Halothane","Opiods","Propofol","Nitrous Oxide"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4897, 'Ophthalmology', 'Cornea & External Eye', 'Moderate', 'Ophthalmology', 343, '{"id":4897,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Moderate","source":"Ophthalmology","sourceNo":343,"q":"All of the following are complications of traumatic hyphema except?","o":["Rebleeding","Pupillary Block","Corneal Ulcer","Posterior synechiae"],"a":2,"e":"Ans. C. Corneal Ulcer Complications of traumatic hyphema","pyqMatches":[{"year":"2015","no":1066,"q":"All of the following are complications of traumatic hyphema except?","o":["Rebleeding","Pupillary Block","Corneal Ulcer","Posterior synechiae"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4898, 'Ophthalmology', 'Refraction & Optics', 'Easy', 'Ophthalmology', 344, '{"id":4898,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Easy","source":"Ophthalmology","sourceNo":344,"q":"Pseudopapilitis with silk shot appearance is seen in?","o":["Hypermetropia","Myopia","Astigmatism","Presbyopia"],"a":0,"e":"Ans.A. Hypermetropia Clinical findings of hypermetropia","pyqMatches":[{"year":"2015","no":1001,"q":"Pseudopapilitis with silk shot appearance is seen in?","o":["Hypermetropia","Myopia","Astigmatism","Presbyopia"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4899, 'Ophthalmology', 'Refraction & Optics', 'Easy', 'Ophthalmology', 345, '{"id":4899,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Easy","source":"Ophthalmology","sourceNo":345,"q":"1mm change axial length of the eyeball would change the refracting power of the eye by ?","o":["1D","2D","3D","4D"],"a":2,"e":"Ans. C. 3D 1 mm change in axial length leads to ametropia of 3D. For example I mm shortening in axial length causes hypermetropia of 3D.","pyqMatches":[{"year":"2015","no":1002,"q":"1mm change axial length of the eyeball would change the refracting power of the eye by ?","o":["1D","2D","3D","4D"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4900, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 346, '{"id":4900,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":346,"q":"D Shaped pupil is seen in ?","o":["Iridodialysis","Iridodonesis","Anterior Uveitis","Anterior synechiae"],"a":0,"e":"Ans., A. Iridodialysis Iridodtalysis is detachment of lris from its root at the ciliary body. It results in D shaped pupil and a black biconvex area seen at the periphery.","pyqMatches":[{"year":"2015","no":1062,"q":"D Shaped pupil is seen in ?","o":["Iridodialysis","Iridodonesis","Anterior Uveitis","Anterior synechiae"],"a":0,"source":"NEET_2015_Paper.pdf"},{"year":"2016","no":1023,"q":"''D'' shaped pupil is seen in","o":["Glaucoma","Dislocation of lens","Iridodialysis","Iridocyclitis"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2015","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4901, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 347, '{"id":4901,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":347,"q":"Lensometer detects ?","o":["Correct power of a pair of glasses","Corneal topography","Biochemical constitution of lens","Power of IOL"],"a":0,"e":"Ans. A. Correct power of a pair of glasses Lensometer A lensmeter or lensometer, also known as a focimeter or vertometer, is an ophthalmic instrument. It is mainly used by optometrists and opticians to verify the correct prescription in a pair of eyeglasses, to properly orient and mark uncut lenses, and to confirm the correct mounting of lenses in spectacle frames. Lensmeters can also verifr the power of contact lenses, if a special lens support is used.","pyqMatches":[{"year":"2015","no":1003,"q":"Lensometer detects ?","o":["Correct power of a pair of glasses","Corneal topography","Biochemical constitution of lens","Power of IOL"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4902, 'Ophthalmology', 'Optic Nerve & Neuro-ophthalmology', 'Easy', 'Ophthalmology', 348, '{"id":4902,"subject":"Ophthalmology","chapter":"Optic Nerve & Neuro-ophthalmology","difficulty":"Easy","source":"Ophthalmology","sourceNo":348,"q":"Sixth cranial nerve palsy causes of left eye causes?","o":["Accomodation paresis in left gaze","Ptosis of left eye","Adduction weakness of left eye","Diplopia in left gaze"],"a":3,"e":"Ans. D. Diplopia in left gaze Sixth nerve supplies lateral rectus, therefore its palsy results in abduction weakness (not adduction weakness). In left gaze, there is abduction ofleft eye and adduction ofright eye. Ifthere is paralysis oflateral rectus of left eye (66 nerve paralysis), abduction ofleft eye will not be possible in left gaze, while adduction of right eye is normal. Therefore, there will be diplopia in left gaze.","pyqMatches":[{"year":"2015","no":1061,"q":"Sixth cranial nerve palsy causes of left eye causes?","o":["Accomodation paresis in left gaze","Ptosis of left eye","Adduction weakness of left eye","Diplopia in left gaze"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4903, 'Ophthalmology', 'Cornea & External Eye', 'Moderate', 'Ophthalmology', 349, '{"id":4903,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Moderate","source":"Ophthalmology","sourceNo":349,"q":"All of the following are treatments of myopia except?","o":["LASIK","Phakic intraocular lens","Radial Keratotomy","Holmium laser thermoplasty"],"a":3,"e":"Ans. D. Holmium laser thermoplasty Refractive surgeries for myopia Radial keratotomy Laser insitu keratomileusis (LASIK) Phakic intraocular lens (IOL) Orthokeratology Photorefractive keratotomy (PRK) Extraction oflens (Fucala''s operation) Intercorneal ring implantation","pyqMatches":[{"year":"2015","no":1004,"q":"All of the following are treatments of myopia except?","o":["LASIK","Phakic intraocular lens","Radial Keratotomy","Holmium laser thermoplasty"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4904, 'Ophthalmology', 'Retina & Vitreous', 'Moderate', 'Ophthalmology', 350, '{"id":4904,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Moderate","source":"Ophthalmology","sourceNo":350,"q":"Pupillary reflex pathway- All of the following are a part except ?","o":["Edinger Westphal nucleus","Pretectal nudes","Medial geniculate body","Retinal ganglion cell"],"a":2,"e":"Ans. C. Medial geniculate body Sensory efferent) component of light rfiex = Optic (1st) nerve Motor (efferent) component of light reflex = Occulomotor (3rd) nerve","pyqMatches":[{"year":"2015","no":1060,"q":"Pupillary reflex pathway- All of the following are a part except ?","o":["Edinger Westphal nucleus","Pretectal nudes","Medial geniculate body","Retinal ganglion cell"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4905, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 351, '{"id":4905,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":351,"q":"Index myopia is seen in ?","o":["Nuclear cataracts","Chorioretinitis","Choroidal melanoma","Posterior uveitis"],"a":0,"e":"Ans. A. Nuclear cataracts Nuclear changes of aging induce a modification of refractive index of lens and produce an index myopia. ''Nuclear cataracts cause a general decrease in the transperancy of the lens nucleus. They are associated with index myopia\"","pyqMatches":[{"year":"2015","no":1005,"q":"Index myopia is seen in ?","o":["Nuclear cataracts","Chorioretinitis","Choroidal melanoma","Posterior uveitis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4906, 'Ophthalmology', 'Glaucoma', 'Moderate', 'Ophthalmology', 352, '{"id":4906,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Moderate","source":"Ophthalmology","sourceNo":352,"q":"Sudden painless loss of vision- All are causes except?","o":["CRAO","CSR","Acute congestive glaucoma","Vitereous Hemorrhage"],"a":2,"e":"Ans. C. Acute congestive glaucoma","pyqMatches":[{"year":"2015","no":1006,"q":"Sudden painless loss of vision- All are causes except?","o":["CRAO","CSR","Acute congestive glaucoma","Vitereous Hemorrhage"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4907, 'Ophthalmology', 'Ocular Motility & Strabismus', 'Easy', 'Ophthalmology', 353, '{"id":4907,"subject":"Ophthalmology","chapter":"Ocular Motility & Strabismus","difficulty":"Easy","source":"Ophthalmology","sourceNo":353,"q":"The most common type of strabismus seen in myopes is?","o":["Intermittent Exotropia","Intermittent Esotropia","Esotropia hypotropia complex","Exoptropia Hypotropia complex"],"a":0,"e":"Ans. A. Intermittent Exotropia Myopia and Intermittent exoptropia Traditionally, it is believed that the presence of myopia may be associated with a decreased demand for accommodation and hence lower convergence. This may predispose to an increased risk ofdeveloping exotropia Alternately, it is hypothesized that intermittent exotropia may lead to development of rnyopia due to increased accommodative demand and increased convergence may be necessary to control the exodeviation that can contribute to increased acommodation and myopia in intermittent distance exotropia.","pyqMatches":[{"year":"2015","no":1057,"q":"The most common type of strabismus seen in myopes is?","o":["Intermittent Exotropia","Intermittent Esotropia","Esotropia hypotropia complex","Exoptropia Hypotropia complex"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4908, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 354, '{"id":4908,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":354,"q":"Muscae volitantes is seen in ?","o":["Vitreous detachment","Vitreous Hemorrhage","Remains of primitive hyaloid vasculatur","Eale''s disease"],"a":2,"e":"Ans, C. Remains of primitive hyaloid vasculatur Muscaevolitantes are physiological vitreous opacities and represent the residues ofprimitivehyaloid vasculature.","pyqMatches":[{"year":"2015","no":1054,"q":"Muscae volitantes is seen in ?","o":["Vitreous detachment","Vitreous Hemorrhage","Remains of primitive hyaloid vasculatur","Eale''s disease"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4909, 'Ophthalmology', 'Retina & Vitreous', 'Moderate', 'Ophthalmology', 355, '{"id":4909,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Moderate","source":"Ophthalmology","sourceNo":355,"q":"All of the following are causes Crystal keratopathy except?","o":["Cystinosis","Schnyder''s Dystrophy","Bietti''s Dystrophy","Diabetes"],"a":3,"e":"Ans. D. Diabetes Causes of Crystalline Keratopathy :- Infections, Schnyder corneal dystrophy, Bietti corneoretinal dystrophy, Cystinosis, Lymphoproliferative disorders, Medication-induced.","pyqMatches":[{"year":"2015","no":1008,"q":"All of the following are causes Crystal keratopathy except?","o":["Cystinosis","Schnyder''s Dystrophy","Bietti''s Dystrophy","Diabetes"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4910, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 356, '{"id":4910,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":356,"q":"Most common age related change in vitreous ?","o":["Anterior vitreous detachment","Posterior vitreous detachment","Vitreous hemorrhage","Vitritis"],"a":1,"e":"Ans. B. Posterior vitreous detachment Yanoff Writes (Most common age related event in vitreous is posterior vitreous detachment''","pyqMatches":[{"year":"2015","no":1053,"q":"Most common age related change in vitreous ?","o":["Anterior vitreous detachment","Posterior vitreous detachment","Vitreous hemorrhage","Vitritis"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4911, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 357, '{"id":4911,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":357,"q":"What is true about retinal hemorrhage in new born?","o":["More common in instrumented deliveries","Resolve in 6 - 8 months","Commonly unilateral","Associated with intrauterine infection"],"a":0,"e":"Ans. A. More common in instrumented deliveries Birth-rdated RH in infants occurs in one-quarter of normal deliveries and are far more common after instrumental deliveries. Commonly bilateral, they were predominantly intraretinal, posterior, resolved rapidly, and very rarely persisted beyond 6 weeks.","pyqMatches":[{"year":"2015","no":1052,"q":"What is true about retinal hemorrhage in new born?","o":["More common in instrumented deliveries","Resolve in 6 - 8 months","Commonly unilateral","Associated with intrauterine infection"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4912, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 358, '{"id":4912,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":358,"q":"Subhyaloid hemorrhage is ?","o":["Boat shaped","Crescent shaped","Round","Flame shaped"],"a":0,"e":"Ans,. A. Boat shaped Retrohyaloid (subhyaloid) hemorrhage (''Boat- shaped or scaphoid) :- Located anterior (internal) to the retina, within the retrohyoid space. (note - the term hyaloid refers to hyaloid body, another name for vitreous humor).","pyqMatches":[{"year":"2015","no":1051,"q":"Subhyaloid hemorrhage is ?","o":["Boat shaped","Crescent shaped","Round","Flame shaped"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4913, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 359, '{"id":4913,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":359,"q":"Prutchners retinopathy in associated with -","o":["Diabetes Mellitus","Wilson''s disease","Head trauma","Rheumatoid arthritis"],"a":2,"e":"Ans. C. Head trauma Purtscher’s retinopathy Near-confluent cotton-wool spots clustered around an otherwise normal optic nerve head in an eye of a patient who had sustained a severe blunt injury to the head and chest. Later, it was discovered to be associated with several non-traumatic systemic diseases. Conditions associated: Severe head, chest & long bone diseases. Fat embolism syndrome. Amniotic fluid embolism Actuepancreatitits. SLE","pyqMatches":[{"year":"2015","no":1050,"q":"Prutchners retinopathy in associated with","o":["Diabetes Mellitus","Wilson''s disease","Head trauma","Rheumatoid arthritis"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4914, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 360, '{"id":4914,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":360,"q":"Snowball appearance is seen in ?","o":["Posterior uveitis","Sarcoidosis","Anterior uveitis","Vitreous Hemorrhage"],"a":1,"e":"Ans. B. Sarcoidosis Causes of intermediate uveitis, thus Snowball Opacities of Vitreous – Candidiasis TB, syphilis Sarcoidosis Multiple sclerosis Lyme disease.","pyqMatches":[{"year":"2015","no":1049,"q":"Snowball appearance is seen in ?","o":["Posterior uveitis","Sarcoidosis","Anterior uveitis","Vitreous Hemorrhage"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4915, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 361, '{"id":4915,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":361,"q":"Unilateral frontal blisters with upper lid edema with conjunctivitis is seen in ?","o":["Acanthamoeba Keratits","Herpes Simplex","Herpes Zoster Ophthalmicus","Neuroparalytic Keratitis"],"a":2,"e":"Ans. C. Herpes Zoster Ophthalmicus Ocular lesions : Combination of 2 or more of the following with subsidence of skin eruptions : - i) Conjunctivitis (Most common ocularlesion) ii) Zoster keratitis : Punctate keratitis, Microdendritic corneal ulcer (Pseudodendritic Keratitis.), nummular anterior stromal keratitis, Disciform keratitis, neuroparalytic ulceration, exposure keratitis, mucous plaque keratitis, Keratouveitis with endothelitis , Sclerokeratitis (least common). The endothelium is a favoured site of attack and acute endothelial cell loss occurs during herpes zoster keratouveitis. iii) Episcleritis/Scleritis, Iridocyclitis (Uveitis). iv) Acute retinal necrosis, anterior segment necrosis, phthisis bulbi. v) Secondary glaucoma.","pyqMatches":[{"year":"2015","no":1016,"q":"Unilateral frontal blisters with upper lid edema with conjunctivitis is seen in ?","o":["Acanthamoeba Keratits","Herpes Simplex","Herpes Zoster Ophthalmicus","Neuroparalytic Keratitis"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4916, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 362, '{"id":4916,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":362,"q":"What is false about Eale''s disease amongst the followwing?","o":["Retinal detachment may occur","AKT is given","Optic neuritis","Vitreous Hemorrhage"],"a":2,"e":"Ans. C. Optic neuritis","pyqMatches":[{"year":"2015","no":1048,"q":"What is false about Eale''s disease amongst the followwing?","o":["Retinal detachment may occur","AKT is given","Optic neuritis","Vitreous Hemorrhage"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4917, 'Ophthalmology', 'Retina & Vitreous', 'Hard', 'Ophthalmology', 363, '{"id":4917,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Hard","source":"Ophthalmology","sourceNo":363,"q":"A 44 year old woman presents Sudden painless loss of vision with history of previous similar episode fundoscopy shows no glow. What could be the possible diagnosis?","o":["Vitreous Hemorrhage","Rhegmatogenous Retinal Detachment","Acute congestive glaucoma","Fungal Keratitis"],"a":0,"e":"Ans., A. Vitreous Hemorrhage Vitreous hemorrhage refers to bleeding into the vitreous chamber or a space created by vitreous detachment. Patients present with sudden onset of floaters (black spots in front of the eye)where the hemorrhage is small, and there may be sudden painless loss ofvisionif the hemorrhage is large.","pyqMatches":[{"year":"2015","no":1044,"q":"A 44 year old woman presents Sudden painless loss of vision with history of previous similar episode fundoscopy shows no glow. What could be the possible diagnosis?","o":["Vitreous Hemorrhage","Rhegmatogenous Retinal Detachment","Acute congestive glaucoma","Fungal Keratitis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4918, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 364, '{"id":4918,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":364,"q":"Glaucoma drainage devices ?","o":["Drain aqueous humour to the posterior segment","Drain aqueous humour to an external device","Open the trabeculae mechanically","Reduce the aqueous secretion by compressing the ciliary epithelium"],"a":1,"e":"Ans. B. Drain aqueous humour to an external device Glaucoma drainage devices are designed to divert aqueous humor from the anterior chamber to an external reservoir, where a fibrous capsule forms about 4-6 weeks after surgery and regulates flow. These devices have shown success in controlling intraocular pressure (IOP) in eyes with previously failed trabeculectomy and in eyes with insufficient conjunctiva because of scarring from prior surgical procedures or injuries. They also have shown success in complicated glaucomas, such as uveiticglaucoma, neovascular glaucoma, and pediatric and developmental glaucomas, among others.","pyqMatches":[{"year":"2015","no":1043,"q":"Glaucoma drainage devices ?","o":["Drain aqueous humour to the posterior segment","Drain aqueous humour to an external device","Open the trabeculae mechanically","Reduce the aqueous secretion by compressing the ciliary epithelium"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4919, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 365, '{"id":4919,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":365,"q":"What is the cause of glaucoma in retinoblastoma?","o":["Blockge of trabecular network","Neovascularisation","Mass effect of the tumour","Lysis of the lens"],"a":1,"e":"Ans. B. Neovascularisation Retinoblastoma is a cause of neovascular glaucoma,","pyqMatches":[{"year":"2015","no":1042,"q":"What is the cause of glaucoma in retinoblastoma?","o":["Blockge of trabecular network","Neovascularisation","Mass effect of the tumour","Lysis of the lens"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4920, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 366, '{"id":4920,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":366,"q":"Mioitcs are treatment of choice for ?","o":["Angle closure glaucoma","Open angle glaucoma","Buphthalmos","Sympathetic Ophthalmia"],"a":0,"e":"Ans. A. Angle closure glaucoma","pyqMatches":[{"year":"2015","no":1040,"q":"Mioitcs are treatment of choice for ?","o":["Angle closure glaucoma","Open angle glaucoma","Buphthalmos","Sympathetic Ophthalmia"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4921, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 367, '{"id":4921,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":367,"q":"Which organism can peneterate corneal endothelium?","o":["Aspergillus fumigatus","Staphylococcus Aureus","Neisseriae Gonorrhae","Hemophilus influenza"],"a":0,"e":"Ans. A. Aspergillus fumigatus Fungi - Can penetrate intact corneal endothelium Neisseria sp, C. Diptheriae, H,Aegyptus, Listeria- Can penetrate intact corneal epithelium","pyqMatches":[{"year":"2015","no":1017,"q":"Which organism can peneterate corneal endothelium?","o":["Aspergillus fumigatus","Staphylococcus Aureus","Neisseriae Gonorrhae","Hemophilus influenza"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4922, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 368, '{"id":4922,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":368,"q":"Earliest sign of primary congenital glaucoma ?","o":["Corneal edema with watering","Haab''s Striae","Blue sclera","Myopia"],"a":0,"e":"Ans., A. Corneal edema with watering Mostcommon symptom - Watering (lacrimation) 2d most common symptom - Photophobia Most troublesome symptom - Photophobia (Child avoids light) First sign - Corneal edema with watering","pyqMatches":[{"year":"2015","no":1037,"q":"Earliest sign of primary congenital glaucoma ?","o":["Corneal edema with watering","Haab''s Striae","Blue sclera","Myopia"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4923, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 369, '{"id":4923,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":369,"q":"The zonules suspending the lens are attached to the?","o":["Root of iris","Ciliary body","Anterior vitreous","Limbus"],"a":1,"e":"Ans. B. Ciliary body The ciliary zonules (Zonules of zinn or suspensory ligaments of lens) hold the lens in position and enable the ciliary muscle to act on it. These consist essentially of a series of fibres which run from the ciliary body and fuse into the outer layer of the lens capsule around the equatorial zone.","pyqMatches":[{"year":"2015","no":1021,"q":"The zonules suspending the lens are attached to the?","o":["Root of iris","Ciliary body","Anterior vitreous","Limbus"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4924, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 370, '{"id":4924,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":370,"q":"Descemet membrane breach is seen in ?","o":["Angle closure glaucoma","Buphthalmos","Acute Iridocyclitis","Subconjunctival hemorrhage"],"a":1,"e":"Ans. B. Buphthalmos Haab striae are discrete corneal opacities appear as lines with double contour due to rupture in Descemet''s membrane.","pyqMatches":[{"year":"2015","no":1036,"q":"Descemet membrane breach is seen in ?","o":["Angle closure glaucoma","Buphthalmos","Acute Iridocyclitis","Subconjunctival hemorrhage"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4925, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 371, '{"id":4925,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":371,"q":"Lens attached to ciliary body via ?","o":["Limbus","Zonules","Vitreous Humour","Root of iris"],"a":1,"e":"Ans. B. Zonules","pyqMatches":[{"year":"2015","no":1022,"q":"Lens attached to ciliary body via ?","o":["Limbus","Zonules","Vitreous Humour","Root of iris"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4926, 'Ophthalmology', 'Glaucoma', 'Moderate', 'Ophthalmology', 372, '{"id":4926,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Moderate","source":"Ophthalmology","sourceNo":372,"q":"What is not true about congenital glaucoma of eye?","o":["Photophobia is most common symptom","Haab''s Striae maybe seen","Thin and blue sclera seen","Anterior chamber is shallow"],"a":0,"e":"Ans. A. Photophobia is most common symptom","pyqMatches":[{"year":"2015","no":1035,"q":"What is not true about congenital glaucoma of eye?","o":["Photophobia is most common symptom","Haab''s Striae maybe seen","Thin and blue sclera seen","Anterior chamber is shallow"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4927, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 373, '{"id":4927,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":373,"q":"The intraocular lens in cataract surgery is placed in ?","o":["Surface of iris","Capsular bag","Over the face of viterous","Around the limbus"],"a":1,"e":"Ans. B. Capsular bag A saclike structure remaining within the eye following extracapsular cataract extraction or Phacoemulsification. The implanted intraocular lens is placed within this structure to recreate the usual phakic state.","pyqMatches":[{"year":"2015","no":1025,"q":"The intraocular lens in cataract surgery is placed in ?","o":["Surface of iris","Capsular bag","Over the face of viterous","Around the limbus"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4928, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 374, '{"id":4928,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":374,"q":"Non foldable lens is made of -","o":["Silicon","Acrylic","PMMA","Hydrogel"],"a":2,"e":"Ans. C. PMMA Types of IOL Depending on the material of manufacturing, following types of IOLs are there","pyqMatches":[{"year":"2015","no":1026,"q":"Non foldable lens is made of","o":["Silicon","Acrylic","PMMA","Hydrogel"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4929, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 375, '{"id":4929,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":375,"q":"What is the type of Galactosemia cataract?","o":["Snowflake","Oil drop","Blue dot","Polychromatic lustre"],"a":1,"e":"Ans, B. Oil drop","pyqMatches":[{"year":"2015","no":1030,"q":"What is the type of Galactosemia cataract?","o":["Snowflake","Oil drop","Blue dot","Polychromatic lustre"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4930, 'Ophthalmology', 'Optic Nerve & Neuro-ophthalmology', 'Easy', 'Ophthalmology', 376, '{"id":4930,"subject":"Ophthalmology","chapter":"Optic Nerve & Neuro-ophthalmology","difficulty":"Easy","source":"Ophthalmology","sourceNo":376,"q":"In head injury unilateral dilatation of pupil is seen due to ?","o":["Occulomotor nerve compression","Ophthalmic N. compression","Trizeminal N. compression","None"],"a":0,"e":"Ans. A. Occulomotor nerve compression Pupil dilation is thought to be the result of uncal herniation causing mechanical compression of IIIrd cranial nerve and subsequent brain stem compromise,","pyqMatches":[{"year":"2013","no":1111,"q":"In head injury unilateral dilatation of pupil is seen due to ?","o":["Occulomotor nerve compression","Ophthalmic N. compression","Trizeminal N. compression","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4931, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 377, '{"id":4931,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":377,"q":"The junction between Retina & Ciliary body is ??","o":["Equator","Pars plicata","Pars plana","Ora serrata"],"a":3,"e":"Ans.D. Ora serrata Ora serrata is the serrated peripheral margin where the retina ends'' Here retina is firmly attached both to vitreous and choroid. Pars plana (of ciliarybody) extends anteriorly from ora serrata.","pyqMatches":[{"year":"2013","no":1117,"q":"The junction between Retina & Ciliary body is ??","o":["Equator","Pars plicata","Pars plana","Ora serrata"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4932, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 378, '{"id":4932,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":378,"q":"\"Bread-crumb\" appearance is seen in ?","o":["Diabetic cataract","Toxoplasmosis","CMV retinitis","Complicated cataract"],"a":3,"e":"Ans. D. Complicated cataract","pyqMatches":[{"year":"2013","no":1164,"q":"\"Bread-crumb\" appearance is seen in ?","o":["Diabetic cataract","Toxoplasmosis","CMV retinitis","Complicated cataract"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4933, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 379, '{"id":4933,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":379,"q":"Yoke muscle for left superior rectus is ?","o":["Right superior rectus","Left inferior rectus","Right inferior oblique","Right superior oblique"],"a":2,"e":"Ans. C. Right inferior oblique Yoke muscles (contralateral synergists). It refers to the pair of muscles (one from each eye) which contract simultaneously during version movements. For example, right lateral rectus and left medial rectus act as yoke muscles for dextroversion movements. Other pair of yoke muscles are right MR and left LR, right LR and left MR, right SR and left IO, right SO and left IR and right IO and left SR.","pyqMatches":[{"year":"2013","no":1197,"q":"Yoke muscle for left superior rectus is ?","o":["Right superior rectus","Left inferior rectus","Right inferior oblique","Right superior oblique"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4934, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 380, '{"id":4934,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":380,"q":"Downward and outward moment of eye is effected in injury of?","o":["3rd nerve","4th nerve","5th nerve","6th nerve"],"a":1,"e":"Ans. B. 4th nerve Downward and outward movement is caused by superior oblique, supplied by uochlear (4s nerve).","pyqMatches":[{"year":"2013","no":1198,"q":"Downward and outward moment of eye is effected in injury of?","o":["3rd nerve","4th nerve","5th nerve","6th nerve"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4935, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 381, '{"id":4935,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":381,"q":"Irregular pupil is seen in ?","o":["Glaucoma","Trauma","Occulomotor pulsy","Retinal detachment"],"a":1,"e":"Ans, B. Trauma Irregular:- It is jagged looking and occurs most often after orbital trauma.","pyqMatches":[{"year":"2012","no":919,"q":"Irregular pupil is seen in ?","o":["Glaucoma","Trauma","Occulomotor pulsy","Retinal detachment"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4936, 'Ophthalmology', 'Refraction & Optics', 'Easy', 'Ophthalmology', 382, '{"id":4936,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Easy","source":"Ophthalmology","sourceNo":382,"q":"Low astigmatism in dim light is due ?","o":["Pupil constriction","Pupil dilatation","Increased curvature of lens","Decreased curvature of lens"],"a":1,"e":"Ans. B. Pupil dilatation","pyqMatches":[{"year":"2012","no":925,"q":"Low astigmatism in dim light is due ?","o":["Pupil constriction","Pupil dilatation","Increased curvature of lens","Decreased curvature of lens"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4937, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 383, '{"id":4937,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":383,"q":"Disciform keratitis is seen ?","o":["HSV","HIV","HBV","Rubella"],"a":0,"e":"Ans. A. HSV","pyqMatches":[{"year":"2012","no":936,"q":"Disciform keratitis is seen ?","o":["HSV","HIV","HBV","Rubella"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4938, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 384, '{"id":4938,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":384,"q":"Corneal dystrophy, true is -","o":["Inflammatory","Neovascularization","Bilateral","All"],"a":2,"e":"Ans. C. Bilateral Corneal dystroPhy is a group of disorders, characterized by a non- inflammatory, inherited, bilateral opacity of the cornea. There is no vascularization of cornea. Dystrophies are classified according to the anatomical involvement.","pyqMatches":[{"year":"2012","no":939,"q":"Corneal dystrophy, true is","o":["Inflammatory","Neovascularization","Bilateral","All"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4939, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 385, '{"id":4939,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":385,"q":"Following corneal transplantation, most common infection occur ?","o":["Staph epidermidis","Streptococcus","Klebsiella","Pseudomonas"],"a":0,"e":"Ans. A. Staph epidermidis Pneumococcus and staphylococcus aureus have been found to be the commonest microorganisms in the developed world, whereas staph epidermidis is the commonest in developing countries, for causing infectious keratitis after corneal transplantations.","pyqMatches":[{"year":"2012","no":940,"q":"Following corneal transplantation, most common infection occur ?","o":["Staph epidermidis","Streptococcus","Klebsiella","Pseudomonas"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4940, 'Ophthalmology', 'Uvea', 'Easy', 'Ophthalmology', 386, '{"id":4940,"subject":"Ophthalmology","chapter":"Uvea","difficulty":"Easy","source":"Ophthalmology","sourceNo":386,"q":"1st sign of anterior uveitis ?","o":["Keratic precipitate","Aqueous flare","Hypopyon","Miosis"],"a":1,"e":"Ans. B. Aqueous flare","pyqMatches":[{"year":"2012","no":941,"q":"1st sign of anterior uveitis ?","o":["Keratic precipitate","Aqueous flare","Hypopyon","Miosis"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4941, 'Ophthalmology', 'Uvea', 'Easy', 'Ophthalmology', 387, '{"id":4941,"subject":"Ophthalmology","chapter":"Uvea","difficulty":"Easy","source":"Ophthalmology","sourceNo":387,"q":"1st sign of iridocyclitis ?","o":["Retrolental flare","KP","Congestion","Trichiasis"],"a":0,"e":"Ans. A. Retrolental flare","pyqMatches":[{"year":"2012","no":942,"q":"1st sign of iridocyclitis ?","o":["Retrolental flare","KP","Congestion","Trichiasis"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4942, 'Ophthalmology', 'Uvea', 'Easy', 'Ophthalmology', 388, '{"id":4942,"subject":"Ophthalmology","chapter":"Uvea","difficulty":"Easy","source":"Ophthalmology","sourceNo":388,"q":"Most common cause of anterior uveitis ?","o":["CMV","Ankylosing spondylitis","Toxoplasma","None"],"a":0,"e":"Ans, A. CMV","pyqMatches":[{"year":"2012","no":943,"q":"Most common cause of anterior uveitis ?","o":["CMV","Ankylosing spondylitis","Toxoplasma","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4943, 'Ophthalmology', 'Uvea', 'Hard', 'Ophthalmology', 389, '{"id":4943,"subject":"Ophthalmology","chapter":"Uvea","difficulty":"Hard","source":"Ophthalmology","sourceNo":389,"q":"Iritis in young patient with joint pain -","o":["Gout","RA","AS","Toxoplasma"],"a":2,"e":"Ans, C. AS","pyqMatches":[{"year":"2012","no":944,"q":"Iritis in young patient with joint pain","o":["Gout","RA","AS","Toxoplasma"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4944, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 390, '{"id":4944,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":390,"q":"Commonest complication of pars planitis ?","o":["Glaucoma","Cataract","Retinal detachment","Vitreous hemorrhage"],"a":1,"e":"Ans. B. Cataract The most common complication of intermediate uveitis (pers ptanitis) is cystoid macular edema, which may decrease the visual acuity. 2nd most common complication is complicated cataract'' Other complication includes retinal detachment.","pyqMatches":[{"year":"2012","no":945,"q":"Commonest complication of pars planitis ?","o":["Glaucoma","Cataract","Retinal detachment","Vitreous hemorrhage"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4945, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 391, '{"id":4945,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":391,"q":"Metamorphopsia is seen in ?","o":["Anterior uveitis","Posterior uveitis","Cataract","Glaucoma"],"a":1,"e":"Ans. B. Posterior uveitis Matamorphopsia is a condition in which patients perceive distorted images of the object. It occurs in Posterior uveitis due to alteration in retinal contour''","pyqMatches":[{"year":"2012","no":946,"q":"Metamorphopsia is seen in ?","o":["Anterior uveitis","Posterior uveitis","Cataract","Glaucoma"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4946, 'Ophthalmology', 'Uvea', 'Easy', 'Ophthalmology', 392, '{"id":4946,"subject":"Ophthalmology","chapter":"Uvea","difficulty":"Easy","source":"Ophthalmology","sourceNo":392,"q":"Recurrent anterior uveitis with increased intraocular tension is seen in ?","o":["Posner schlossman syndrome","Foster kennedy syndrome","Vogt-koyanagi-harada syndrome","None"],"a":0,"e":"Ans. A. Posner schlossman syndrome Glamatocyclitic crisis (posner - Schlossman syndrome) is a unilateral recurrent non- granulomatous iritis that is associated with an elevated ocular pressure during the attacks''","pyqMatches":[{"year":"2012","no":947,"q":"Recurrent anterior uveitis with increased intraocular tension is seen in ?","o":["Posner schlossman syndrome","Foster kennedy syndrome","Vogt-koyanagi-harada syndrome","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4947, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 393, '{"id":4947,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":393,"q":"Congenital cataract commonly associated with visual defect?","o":["Punctate Cataract","Blue dot cataract","Zonular cataract","Fusiform cataract"],"a":2,"e":"Ans. C. Zonular cataract Lamellar (Zonular) cataract is the most common type of congenital cataract presenting with visual impairment. It is usually bilateral and frequently causes servere visual defects''","pyqMatches":[{"year":"2012","no":948,"q":"Congenital cataract commonly associated with visual defect?","o":["Punctate Cataract","Blue dot cataract","Zonular cataract","Fusiform cataract"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4948, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 394, '{"id":4948,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":394,"q":"Decreased reading ability is seen in ?","o":["Fusiform cataract","Zonular cataract","Blue dot cataract","Punctate cataract"],"a":1,"e":"Ans, B. Zonular cataract","pyqMatches":[{"year":"2012","no":949,"q":"Decreased reading ability is seen in ?","o":["Fusiform cataract","Zonular cataract","Blue dot cataract","Punctate cataract"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4949, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 395, '{"id":4949,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":395,"q":"Lens subluxates in homocystinuria ?","o":["Inferotemporal","Inferonasal","Superonasal","Superotemporal"],"a":1,"e":"Ans. B. Inferonasal","pyqMatches":[{"year":"2012","no":950,"q":"Lens subluxates in homocystinuria ?","o":["Inferotemporal","Inferonasal","Superonasal","Superotemporal"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4950, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 396, '{"id":4950,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":396,"q":"Second sight is seen in ?","o":["Nuclear cataract","Cortical cataract","Zonular cataract","Punctate cataract"],"a":0,"e":"Ans. A. Nuclear cataract When a nuclear cataract develops, it can bring about a temporary improvement in near vision, called ''second sight''.","pyqMatches":[{"year":"2012","no":951,"q":"Second sight is seen in ?","o":["Nuclear cataract","Cortical cataract","Zonular cataract","Punctate cataract"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4951, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 397, '{"id":4951,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":397,"q":"Congenital cataract with visual disturbances surgery should be done ?","o":["Immediately","After 2 months","After 4 months","After 1 year"],"a":0,"e":"Ans. A. Immediately","pyqMatches":[{"year":"2012","no":952,"q":"Congenital cataract with visual disturbances surgery should be done ?","o":["Immediately","After 2 months","After 4 months","After 1 year"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4952, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 398, '{"id":4952,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":398,"q":"Most common type of congenital cataract is ?","o":["Capsular","Zonular","Coralliform","Blue dot"],"a":3,"e":"Ans D. Blue dot Most common type of congenital cataract = punctate (blue dot) cataract. Most common type of cataract which is clinically (visually) significant + zonular or lamellar cataract.","pyqMatches":[{"year":"2012","no":953,"q":"Most common type of congenital cataract is ?","o":["Capsular","Zonular","Coralliform","Blue dot"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4953, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 399, '{"id":4953,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":399,"q":"Treatment of traumatic cataract in children ?","o":["ECCE + IOL","Lensectomy","Contact lens","Glasses"],"a":0,"e":"Ans. A. ECCE + IOL Traumatic cataract in children is a common cause of unilateral loss of vision. Penetrating injuries are usually more common than blunt injuries. At the time of presentation after trauma to eye, primary repair of the corneal or scleral wound is usually preferred, Cataract surgery GCCE) with IOL implantations is performed later following complete evaluation of damage to the intraocular structures by ancillary methods such as B-scan ultrasonography.","pyqMatches":[{"year":"2012","no":954,"q":"Treatment of traumatic cataract in children ?","o":["ECCE + IOL","Lensectomy","Contact lens","Glasses"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4954, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 400, '{"id":4954,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":400,"q":"Jack in box scotoma is seen after correction of Aphakia by?","o":["IOL","Spectacles","Contact lens","None"],"a":1,"e":"Jack-in-the-box phenomenon is seen in the correction of aphakia by spectacles due to the prismatic effects at the edge of the lens. Other difficulties in the correction of aphakia by spectacles include the following: Image magnification by 25–30%. Pin Cushion distortion - a spherical aberration due to thick spectacles. Restricted field with Jack in the Box phenomenona/Roving Ring scotoma - a prismatic aberration. Cosmetically, the eyes look enlarged (Frog eyes) behind the thick spectacles. Physical inconvenience. Treatment of choice: correction is obtained by intraocular lens (IOL).","pyqMatches":[{"year":"2012","no":955,"q":"Jack in box scotoma is seen after correction of Aphakia by?","o":["IOL","Spectacles","Contact lens","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4955, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 401, '{"id":4955,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":401,"q":"False about phacolytic glaucoma ?","o":["Due to contact of iris to lens","Open angle glaucoma","Seen in hypermature stage of cataract","Lens induced glaucoma"],"a":0,"e":"Ans. A. Due to contact of iris to lens Phacolytic glaucoma is an open angle glaucoma in hypermature stage of cataract due to blockage of trabecular meshwork by swollen macrophages. Glaucoma due to contact of iris to lens (pupillary block glaucoma) is seen in phacomorphic glaucoma.","pyqMatches":[{"year":"2012","no":956,"q":"False about phacolytic glaucoma ?","o":["Due to contact of iris to lens","Open angle glaucoma","Seen in hypermature stage of cataract","Lens induced glaucoma"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4956, 'Ophthalmology', 'Glaucoma', 'Moderate', 'Ophthalmology', 402, '{"id":4956,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Moderate","source":"Ophthalmology","sourceNo":402,"q":"Neovascular glaucoma is seen in all except?","o":["Diabetes","CRVO","Eale''s disease","Open angle glaucoma"],"a":3,"e":"Ans. D. Open angle glaucoma It is a secondary angle closure glaucoma which results due to formation of neovascular membrane over the iris i.e., neovascularization of iris (rubeosis iridis).","pyqMatches":[{"year":"2012","no":957,"q":"Neovascular glaucoma is seen in all except?","o":["Diabetes","CRVO","Eale''s disease","Open angle glaucoma"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4957, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 403, '{"id":4957,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":403,"q":"Laser iridotomy is done in ?","o":["Angle closure glaucoma","Open angle glaucoma","Pigmentory glaucoma","None"],"a":0,"e":"Ans. A. Angle closure glaucoma Treatment of choice for PACG is peripheral laser iridotomy.","pyqMatches":[{"year":"2012","no":958,"q":"Laser iridotomy is done in ?","o":["Angle closure glaucoma","Open angle glaucoma","Pigmentory glaucoma","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4958, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 404, '{"id":4958,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":404,"q":"In acute angle closure glaucoma, primary mechanism of pathogenesis is ?","o":["Increased secretion","Increased absorption but increased secretion","Outflow obstruction","None"],"a":2,"e":"Ans, C. Outflow obstruction In acute angle closure glaucoma, rise in IOP occurs due to blockage of aqueous outflow by closure of a narrower angle of anterior chamber.","pyqMatches":[{"year":"2012","no":959,"q":"In acute angle closure glaucoma, primary mechanism of pathogenesis is ?","o":["Increased secretion","Increased absorption but increased secretion","Outflow obstruction","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4959, 'Ophthalmology', 'Lens & Cataract', 'Moderate', 'Ophthalmology', 405, '{"id":4959,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Moderate","source":"Ophthalmology","sourceNo":405,"q":"Not a risk factor for angle closure glaucoma ?","o":["Small eye","Hypermetropia","Small cornea","Small lens"],"a":3,"e":"Ans. D. Small lens Predisposing factors for PACG :- i) Shallow anterior chamber,ii) Short eye (short axiallensth),i1i) Smaller corneal diameter, iv) Anterior location of iris-lens diaphragm, v) Hlpermetropic eye, vi) Large lens (older cataractous).","pyqMatches":[{"year":"2012","no":960,"q":"Not a risk factor for angle closure glaucoma ?","o":["Small eye","Hypermetropia","Small cornea","Small lens"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4960, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 406, '{"id":4960,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":406,"q":"Staphlyoma involvement ?","o":["Iris with conjunctiva","Conjunctiva with cornea","Choroid with retina","Iris with cornea"],"a":3,"e":"Ans. D. Iris with cornea Staphyloma is an abnormal protrusion of uveal tissue (iris or ciliary body or choroid) through a week and thin portion of cornea or sclera. So, staphyloma is lined internally by uveal tissue (iris or ciliary body or choroid) and externally by weak cornea or sclera.","pyqMatches":[{"year":"2012","no":1006,"q":"Staphlyoma involvement ?","o":["Iris with conjunctiva","Conjunctiva with cornea","Choroid with retina","Iris with cornea"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4961, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 407, '{"id":4961,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":407,"q":"Best drug for open angle glaucoma ?","o":["Latanoprost","Pilocarpine","Physostigmine","Apraclonidine"],"a":0,"e":"Ans. A. Latanoprost Medical therapy :- Total medical therapy is the treatment of choice for POAG. Topical p-blockers (Timolol, Betoxalol, Levobunolol, carteolol) are the drugs of choice. Topical prostaglandin analogues (Iatanoprost, bimatoprost, travoprost) are the second choice drugs.","pyqMatches":[{"year":"2012","no":961,"q":"Best drug for open angle glaucoma ?","o":["Latanoprost","Pilocarpine","Physostigmine","Apraclonidine"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4962, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 408, '{"id":4962,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":408,"q":"Corneal tattooing is done by ?","o":["Gold chloride","Silver chloride","Titanium chloride","Aluminium chloride"],"a":0,"e":"Ans. A. Gold chloride For tattooing Indian black ink gold chloride or platinum may be used.","pyqMatches":[{"year":"2012","no":1005,"q":"Corneal tattooing is done by ?","o":["Gold chloride","Silver chloride","Titanium chloride","Aluminium chloride"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4963, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 409, '{"id":4963,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":409,"q":"Broadest neuroretinal rim is seen in -","o":["Sup pole","Inf pole","Nasal pole","Temporal lobe"],"a":1,"e":"Ans., B. Inf pole The neurorentinal rim is the area of optic disc which contains neural elements and is located between the edge of the optic disc and the physiological cup. The neuroretinal rin is broadest Inferiorly, followed by Superior, Nasal and Temporal regions in decreasing order ofthickness (the ISNT) rule.","pyqMatches":[{"year":"2012","no":962,"q":"Broadest neuroretinal rim is seen in","o":["Sup pole","Inf pole","Nasal pole","Temporal lobe"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4964, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 410, '{"id":4964,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":410,"q":"Enucleation is indicated in ?","o":["Acute congestive glaucoma","Panophthalmitis","Retinoblastoma","None"],"a":2,"e":"Ans, C. Retinoblastoma Indications of Enucleation Absolute = Retinoblastoma, malignant melanoma. Relative = Painful blind eye, mutilating ocular injury, anterior staphyloma, phthisis DalEi, endophthalmitis, congenital anophthalmia or severe microphthalmia.","pyqMatches":[{"year":"2012","no":1004,"q":"Enucleation is indicated in ?","o":["Acute congestive glaucoma","Panophthalmitis","Retinoblastoma","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4965, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 411, '{"id":4965,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":411,"q":"Retinitis pigmentosa is due to defect in which gene-","o":["Scotopsin","Rhodopsin","Pigmented epithelium","None"],"a":1,"e":"Ans. B. Rhodopsin Several different rhodopsin gene mutations have been identified in the pedigrees with autosomal dominant retinitis pigmentosa.","pyqMatches":[{"year":"2012","no":963,"q":"Retinitis pigmentosa is due to defect in which gene","o":["Scotopsin","Rhodopsin","Pigmented epithelium","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4966, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 412, '{"id":4966,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":412,"q":"Iris cloboma is most common in ?","o":["Inferotemporal","Soperotemporal","Inferonasal","Soperonasal"],"a":2,"e":"Ans. C. Inferonasal All clobomas (including iris) are mostly inferonasal.","pyqMatches":[{"year":"2012","no":1003,"q":"Iris cloboma is most common in ?","o":["Inferotemporal","Soperotemporal","Inferonasal","Soperonasal"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4967, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 414, '{"id":4967,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":414,"q":"Shaffer''s sign is seen in ?","o":["Retinitis pigmentosa","Retinal detachment","CRVO","CRAO"],"a":1,"e":"Ans. B. Retinal detachment Vitreous show pigment in the anterior vitreous (tobacco dusting or shaffer sign), with posterior vitreous detachement.","pyqMatches":[{"year":"2012","no":965,"q":"Shaffer''s sign is seen in ?","o":["Retinitis pigmentosa","Retinal detachment","CRVO","CRAO"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4968, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 415, '{"id":4968,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":415,"q":"Deposit in retinal macular degeneration ?","o":["Iron","Drusen","Lipochrome","Hemosiderine"],"a":1,"e":"Ans. B. Drusen Dry form of ARMD begins with characteristic yellow deposits in the macula called drusen between the retinal pigment epithelium and tie underlying choroid","pyqMatches":[{"year":"2012","no":966,"q":"Deposit in retinal macular degeneration ?","o":["Iron","Drusen","Lipochrome","Hemosiderine"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4969, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 416, '{"id":4969,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":416,"q":"Vitreous hemorrhage in diabetic retinopathy ?","o":["Non-proliferative diabetic retinopathy","Proliferative diabetic retinopathy","Both","None"],"a":1,"e":"Ans. B. Proliferative diabetic retinopathy","pyqMatches":[{"year":"2012","no":967,"q":"Vitreous hemorrhage in diabetic retinopathy ?","o":["Non-proliferative diabetic retinopathy","Proliferative diabetic retinopathy","Both","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4970, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 417, '{"id":4970,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":417,"q":"Head light in fog appearance is seen in ?","o":["Syphilis","Toxoplasmoss","Toxocara","Herpes"],"a":1,"e":"Ans. B. Toxoplasmoss On fundoscopic examination, there is diffuse \"headtightinthe fogappearance, in congenital toxoplasmosis. This is due to combination of active retinal lesion in the center with depigmentation (the headlight) and severe vitreous inflammation (the fog).","pyqMatches":[{"year":"2012","no":968,"q":"Head light in fog appearance is seen in ?","o":["Syphilis","Toxoplasmoss","Toxocara","Herpes"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4971, 'Ophthalmology', 'Uvea', 'Easy', 'Ophthalmology', 418, '{"id":4971,"subject":"Ophthalmology","chapter":"Uvea","difficulty":"Easy","source":"Ophthalmology","sourceNo":418,"q":"Coloboma, most common site ?","o":["Superotemporal","Inferonasal","Inferotemporal","Superonasal"],"a":1,"e":"Ans. B. Inferonasal A coloboma is a hole in one of the structures of eye, such as iris, retina, choroid or optic disc. The eye develops in the embryo, from the optic cup and optic fissure. The optic fissure fuses at 5-7 weeks development. Failure of this fusion leads to a gap in ocular tissue know as coloboma, typically located in the inferonasal quadrant.","pyqMatches":[{"year":"2012","no":1002,"q":"Coloboma, most common site ?","o":["Superotemporal","Inferonasal","Inferotemporal","Superonasal"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4972, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 419, '{"id":4972,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":419,"q":"Salt & pepper fundus ?","o":["Cong toxoplasmosis","Cong histoplasmosis","Congenital syphilis","None"],"a":2,"e":"Ans. C. Congenital syphilis","pyqMatches":[{"year":"2012","no":969,"q":"Salt & pepper fundus ?","o":["Cong toxoplasmosis","Cong histoplasmosis","Congenital syphilis","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4973, 'Ophthalmology', 'Lens & Cataract', 'Easy', 'Ophthalmology', 420, '{"id":4973,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Easy","source":"Ophthalmology","sourceNo":420,"q":"Expulsive hemorrhage in cataract surgery is from?","o":["Vortex vein","Ciliary artery","Choroidal vein","None"],"a":1,"e":"Ans, B. Ciliary artery Expulsive hemorrhage after cataract extraction or glaucoma surgery = Rupture of ciliary artery. Expulsive hemorrhage in Retinal/Vitrous operation = Direct trauma to choroidal or vortex vein.","pyqMatches":[{"year":"2012","no":1001,"q":"Expulsive hemorrhage in cataract surgery is from?","o":["Vortex vein","Ciliary artery","Choroidal vein","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4974, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 421, '{"id":4974,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":421,"q":"Cattle track appearence ?","o":["CRVO","CRAO","Diabetic retinopathy","Syphilitic retinopathy"],"a":1,"e":"Ans. B. CRAO","pyqMatches":[{"year":"2012","no":970,"q":"Cattle track appearence ?","o":["CRVO","CRAO","Diabetic retinopathy","Syphilitic retinopathy"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4975, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 422, '{"id":4975,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":422,"q":"Eale''s disease is ?","o":["Retinal hemorrhage","Vitreous hemorrhage","Conjunctival hemorrhage","Choroidal hemorrhage"],"a":1,"e":"Ans. B. Vitreous hemorrhage Eale''s disese is an idiopathic inflammatory venous occlusion that primarily affects the peripheral retina of young adult (20-30 yrs) male. It is characterized by recurrent bilateral vitreous hemorrhage; therefore, also referred to as primary vitreous hemorrhage.","pyqMatches":[{"year":"2012","no":971,"q":"Eale''s disease is ?","o":["Retinal hemorrhage","Vitreous hemorrhage","Conjunctival hemorrhage","Choroidal hemorrhage"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4976, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 423, '{"id":4976,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":423,"q":"Extra retinal fibrovascular proliferation at ridge is?","o":["Normal","Stage I ROM","Stage II ROM","Stage III ROM"],"a":3,"e":"Ans. D. Stage III ROM Disease Severity (Stage) Prior to the development of ROP in the premature infant, vascularization of the retina is incomplete or \"immature\" (Stage 0). Stage 1: Demarcation Line: This line is thin and flat (in the retina plane) and separates the avascular retina anteriorly from the vascularized retina posteriorly. Stage 2: Ridge: The ridge arises from the demarcation line and has height and width, which extends above the plane of the retina. The ridge may change from white to pink and vessels may leave the plane of the retina posterior to the ridge to enter it. Small isolated tufts of neovascular tissue lying on the surface of the retina, commonly called \"popcorn\" may be seen posterior to this ridge structure and do not constitute the degree of fibrovascular growth that is a necessary condition for stage 3. Stage 3: Extraretinal Fibrovascular Proliferation: Neovascularization extends from the ridge into the vitreous. This extraretinal proliferating tissue is continuous with the posterior aspect of the ridge, causing a ragged appearance as the proliferation becomes more extensive. Stage 4: Partial Retinal Detachment: Stage 4, in the initial classification was the final stage and initially known as the cicatricial phase. It was later divided into extrafoveal (stage 4A) and foveal (stage 4B) partial retinal detachments. Stage 4 retinal detachments are generally concave and most are circumferentially oriented. Retinal detachments usually begin at the point of fibrovascular attachment to the vascularized retina and the extent of detachment depends on the amount of neovascularization present. Stage 5: Total Retinal Detachment: Retinal detachments are generally tractional and usually funnel shaped. The configuration of the funnel itself is used for subdivision of this stage depending if the anterior and posterior portions are open or narrowed","pyqMatches":[{"year":"2012","no":972,"q":"Extra retinal fibrovascular proliferation at ridge is?","o":["Normal","Stage I ROM","Stage II ROM","Stage III ROM"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4977, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 424, '{"id":4977,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":424,"q":"All are seen in 3'' nerve palsy ?","o":["Mydriasis","Loss of light reflex","Loss of abduction","Ptosis"],"a":2,"e":"Ans. C. Loss of abduction","pyqMatches":[{"year":"2012","no":973,"q":"All are seen in 3'' nerve palsy ?","o":["Mydriasis","Loss of light reflex","Loss of abduction","Ptosis"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4978, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 425, '{"id":4978,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":425,"q":"Swinging light test is positive in ?","o":["Conjunctivitis","Glaucoma","Retrobulbar neuritis","Keratoconus"],"a":2,"e":"Ans. C. Retrobulbar neuritis Swinging flash light is used for relative efferent pathway defect (RAPD) which is most characteristic of Iesions in the optic nerve. Thus it is positive in retrobulbar neuritis.","pyqMatches":[{"year":"2012","no":974,"q":"Swinging light test is positive in ?","o":["Conjunctivitis","Glaucoma","Retrobulbar neuritis","Keratoconus"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4979, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 426, '{"id":4979,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":426,"q":"Optic tract lesion causes ?","o":["Wernicke''s hemianopic pupil","Amauratic pupil","Amauratic pupil","None"],"a":0,"e":"Ans, A. Wernicke''s hemianopic pupil Wernicke''s hemianopic pupil is seen in complete lesion of optic tract.","pyqMatches":[{"year":"2012","no":975,"q":"Optic tract lesion causes ?","o":["Wernicke''s hemianopic pupil","Amauratic pupil","Amauratic pupil","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4980, 'Ophthalmology', 'Optic Nerve & Neuro-ophthalmology', 'Easy', 'Ophthalmology', 427, '{"id":4980,"subject":"Ophthalmology","chapter":"Optic Nerve & Neuro-ophthalmology","difficulty":"Easy","source":"Ophthalmology","sourceNo":427,"q":"Amblyopia is caused by ?","o":["Methyl alcohol","Penicillin","Propranolol","None"],"a":0,"e":"Ans. A. Methyl alcohol Toxic amblyopia is chronic retrobulbar neuritiswhich results from the damage to optic nerve by the exogenous poisons. The toxic agents involve may be: Tobacco, ethyl atcohol, ethylene glycol, Iead, arsenic, cannabis indica, carbon disulphide various drugs","pyqMatches":[{"year":"2012","no":976,"q":"Amblyopia is caused by ?","o":["Methyl alcohol","Penicillin","Propranolol","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4981, 'Ophthalmology', 'Optic Nerve & Neuro-ophthalmology', 'Easy', 'Ophthalmology', 428, '{"id":4981,"subject":"Ophthalmology","chapter":"Optic Nerve & Neuro-ophthalmology","difficulty":"Easy","source":"Ophthalmology","sourceNo":428,"q":"Vitamin B12 deficiency causes ?","o":["Centrocaecal scotoma","Binasal hemianopia","Constriction of peripheral field","Bitemporal hemianopia"],"a":0,"e":"Ans., A. Centrocaecal scotoma Vitamin B12 deficiency causes optic neuritis. Most common visual field defect in optic neuritis is central or centrocaecal scotoma.","pyqMatches":[{"year":"2012","no":977,"q":"Vitamin B12 deficiency causes ?","o":["Centrocaecal scotoma","Binasal hemianopia","Constriction of peripheral field","Bitemporal hemianopia"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4982, 'Ophthalmology', 'Optic Nerve & Neuro-ophthalmology', 'Easy', 'Ophthalmology', 429, '{"id":4982,"subject":"Ophthalmology","chapter":"Optic Nerve & Neuro-ophthalmology","difficulty":"Easy","source":"Ophthalmology","sourceNo":429,"q":"Cause of bilateral optic atrophy ?","o":["Trauma to optic nerve","Intracranial neoplasma","CRAO","Optic neuritis"],"a":1,"e":"Ans. B. Intracranial neoplasma","pyqMatches":[{"year":"2012","no":978,"q":"Cause of bilateral optic atrophy ?","o":["Trauma to optic nerve","Intracranial neoplasma","CRAO","Optic neuritis"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4983, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 430, '{"id":4983,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":430,"q":"Earliest muscle to involve in thyroid ophthalmopathy?","o":["MR","LR","IR","SR"],"a":2,"e":"Ans. C. IR","pyqMatches":[{"year":"2012","no":979,"q":"Earliest muscle to involve in thyroid ophthalmopathy?","o":["MR","LR","IR","SR"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4984, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 431, '{"id":4984,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":431,"q":"Which of the following is longest extraocular muscle?","o":["SR","MR","SO","IO"],"a":2,"e":"Ans. C. SO The superior oblique is the longest, thinnest extraocular muscle.","pyqMatches":[{"year":"2012","no":980,"q":"Which of the following is longest extraocular muscle?","o":["SR","MR","SO","IO"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4985, 'Ophthalmology', 'Ocular Motility & Strabismus', 'Easy', 'Ophthalmology', 432, '{"id":4985,"subject":"Ophthalmology","chapter":"Ocular Motility & Strabismus","difficulty":"Easy","source":"Ophthalmology","sourceNo":432,"q":"Treatment of choice for amblyopia is ?","o":["Convergent exercises","Spectacles","Surgery","Conventional occlusion"],"a":3,"e":"Ans. D. Conventional occlusion The treatment of amblyopia should begin as early as possible. The amblyopic eye fails to develop vision and visual impairment remains Permanent unless it is treated before the age of 7 years. Amblyopic therapy works best when intitiated in young children under 3 years ofage.","pyqMatches":[{"year":"2012","no":981,"q":"Treatment of choice for amblyopia is ?","o":["Convergent exercises","Spectacles","Surgery","Conventional occlusion"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4986, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 433, '{"id":4986,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":433,"q":"Alkali causes ?","o":["Symblepharon","Papilloedema","Optic neuritis","Retinal detachment"],"a":0,"e":"Ans, A. Symblepharon","pyqMatches":[{"year":"2012","no":1000,"q":"Alkali causes ?","o":["Symblepharon","Papilloedema","Optic neuritis","Retinal detachment"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4987, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Easy', 'Ophthalmology', 434, '{"id":4987,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Easy","source":"Ophthalmology","sourceNo":434,"q":"Unilateral lacrimal gland destruction may be caused by?","o":["Inferior orbital fissure fracture","Fracture of roof of orbit","Fracture of lateral wall","Fracture of sphenoid"],"a":1,"e":"Ans. B. Fracture of roof of orbit Damage to the superior orbital structures, in fracture of roof of orbit, can cause diplopia, ptosis, optic neuropathy, ptosis, neuroPathy and lacrimal gland injury.","pyqMatches":[{"year":"2012","no":999,"q":"Unilateral lacrimal gland destruction may be caused by?","o":["Inferior orbital fissure fracture","Fracture of roof of orbit","Fracture of lateral wall","Fracture of sphenoid"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4988, 'Ophthalmology', 'Miscellaneous', 'Moderate', 'Ophthalmology', 435, '{"id":4988,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Ophthalmology","sourceNo":435,"q":"After trauma, A person cannot move eye outword beyond mid point. The nerve injured is ?","o":["2nd","3rd","4th","6th"],"a":3,"e":"Ans, D. 6th All the extraocular muscles are supplied by 3rd cranial (occulomotor) nerve except for superior oblique and lateral rectus. superior oblique muscle is supplied by 4thcranial (trochlear) nerve, and lateral rectus muscle is supplied by 6th cranial (abducent) nene. Beside these extraocular muscles, occulomotor (3rd) nerve also supplies levator palpebrae superioris, sphinctor pupillae (causes pupillary constriction), and ciliary muscle (causes accommodation).","pyqMatches":[{"year":"2012","no":982,"q":"After trauma, A person cannot move eye outword beyond mid point. The nerve injured is ?","o":["2nd","3rd","4th","6th"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4989, 'Ophthalmology', 'Miscellaneous', 'Moderate', 'Ophthalmology', 436, '{"id":4989,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Ophthalmology","sourceNo":436,"q":"Bilateral ptosis is seen in all except ?","o":["Hyperthyroidism","Congenital","Trauma","Myotonic dystrophy"],"a":2,"e":"Ans, C. Trauma","pyqMatches":[{"year":"2012","no":998,"q":"Bilateral ptosis is seen in all except ?","o":["Hyperthyroidism","Congenital","Trauma","Myotonic dystrophy"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4990, 'Ophthalmology', 'Ocular Motility & Strabismus', 'Easy', 'Ophthalmology', 437, '{"id":4990,"subject":"Ophthalmology","chapter":"Ocular Motility & Strabismus","difficulty":"Easy","source":"Ophthalmology","sourceNo":437,"q":"Angle of squint is measured by ?","o":["Gonioscopy","Prism","Retinoscopy","Keratometry"],"a":1,"e":"Ans. B. Prism","pyqMatches":[{"year":"2012","no":983,"q":"Angle of squint is measured by ?","o":["Gonioscopy","Prism","Retinoscopy","Keratometry"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4991, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Easy', 'Ophthalmology', 438, '{"id":4991,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Easy","source":"Ophthalmology","sourceNo":438,"q":"Most common cause of intermittent proptosis ?","o":["Orbital varix","Thyroid ophthalmopathy","Neuroblastoma","Retinoblastoma"],"a":0,"e":"Ans. A. Orbital varix Intetmittent proptosis:- Proptosis developing intermittently and rapidly in one eye when venous stasis is induced by forward bending or lowering the head, turning the head forcibly, hyperextension of the neck, coughing, forced expiration with or without compression of the nostrils, or pressure on jugular veins. The most important casue is orbital varix (varicocele).","pyqMatches":[{"year":"2012","no":997,"q":"Most common cause of intermittent proptosis ?","o":["Orbital varix","Thyroid ophthalmopathy","Neuroblastoma","Retinoblastoma"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4992, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 439, '{"id":4992,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":439,"q":"Most common cause of ophthalmoplegia ?","o":["Aneurysm","Infection","Mysthenia gravis","None"],"a":0,"e":"Ans. A. Aneurysm The most common indentifiable etiologies are ischemia, aneurysm, tumor and ttauma;some 20% remain unexplained.","pyqMatches":[{"year":"2012","no":984,"q":"Most common cause of ophthalmoplegia ?","o":["Aneurysm","Infection","Mysthenia gravis","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4993, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 440, '{"id":4993,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":440,"q":"Massaging of nasolacrimal duct is done in ?","o":["Acute dacryocystitis","Congenital dacryocystitis","Conjunctivitis","None"],"a":1,"e":"Ans. B. Congenital dacryocystitis Massage over lacrimal sac is the mainstay of treatment in congenital dacryocystitis.","pyqMatches":[{"year":"2012","no":996,"q":"Massaging of nasolacrimal duct is done in ?","o":["Acute dacryocystitis","Congenital dacryocystitis","Conjunctivitis","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4994, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 441, '{"id":4994,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":441,"q":"Ataxia, nystagmus and ophthalmoplegia is seen in -","o":["Mysthenia gravis","Chronic progressive external ophthalmoplegia","3rd nerve palsy","None"],"a":1,"e":"Ans. B. Chronic progressive external ophthalmoplegia The most commonidentifiableetiologies are ischemia, aneurysm, tumor and trauma, some 20% remain unexplained.","pyqMatches":[{"year":"2012","no":985,"q":"Ataxia, nystagmus and ophthalmoplegia is seen in","o":["Mysthenia gravis","Chronic progressive external ophthalmoplegia","3rd nerve palsy","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4995, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 442, '{"id":4995,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":442,"q":"Abnormally eccentric placed pupil is called ?","o":["Polycoria","Corectopia","Corectopia","Ectopia lentis"],"a":1,"e":"Ans. B. Corectopia","pyqMatches":[{"year":"2012","no":995,"q":"Abnormally eccentric placed pupil is called ?","o":["Polycoria","Corectopia","Corectopia","Ectopia lentis"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4996, 'Ophthalmology', 'Ocular Motility & Strabismus', 'Hard', 'Ophthalmology', 443, '{"id":4996,"subject":"Ophthalmology","chapter":"Ocular Motility & Strabismus","difficulty":"Hard","source":"Ophthalmology","sourceNo":443,"q":"Child with mild squint. Intrauterine, birth history, developmental history till date all normal. Corneal reflex normal. All other eye parameters normal except exaggerated epicanthal fold. Diagnosis ?","o":["Pseudostrabismus","Accommodative squint","Exophoria","Esophoria"],"a":0,"e":"Ans, A. Pseudostrabismus Pseudoesotropia (apparent convergent squint - Due to prominent epicanthal fold. Pseudoexotropia (apparent divergent squint - Due to hypertelorism.","pyqMatches":[{"year":"2012","no":986,"q":"Child with mild squint. Intrauterine, birth history, developmental history till date all normal. Corneal reflex normal. All other eye parameters normal except exaggerated epicanthal fold. Diagnosis ?","o":["Pseudostrabismus","Accommodative squint","Exophoria","Esophoria"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4997, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 444, '{"id":4997,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":444,"q":"Madarosis is seen in ?","o":["Addison''s disease","Hypothyroidism","Acromegaly","None"],"a":1,"e":"Ans. B. Hypothyroidism Madarosis maY be seen in - Rubella Congenital Syphilis Congenital leber amaurosis Mayous Batten disease Thioridazine toxicity","pyqMatches":[{"year":"2012","no":994,"q":"Madarosis is seen in ?","o":["Addison''s disease","Hypothyroidism","Acromegaly","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4998, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Easy', 'Ophthalmology', 445, '{"id":4998,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Easy","source":"Ophthalmology","sourceNo":445,"q":"MC orbital tumor ?","o":["Nerve sheath tumor","Hemangioma","Lymphoma","Meningioma"],"a":1,"e":"Ans. B. Hemangioma Mostcommonorbital tumor -Cavernous hemangioma. Most common malignant orbital tumor –Lymphoma.","pyqMatches":[{"year":"2012","no":987,"q":"MC orbital tumor ?","o":["Nerve sheath tumor","Hemangioma","Lymphoma","Meningioma"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (4999, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 446, '{"id":4999,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":446,"q":"Loss of eyelashes is ?","o":["Tylosis","Madarosis","Trichiasis","Ectropion"],"a":1,"e":"Ans. B. Madarosis Madarosis refer to loss of eyelashes and sometimes also eyebrows","pyqMatches":[{"year":"2012","no":993,"q":"Loss of eyelashes is ?","o":["Tylosis","Madarosis","Trichiasis","Ectropion"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5000, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 447, '{"id":5000,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":447,"q":"Fusion of palpebral and bulbar conjunctiva is -","o":["Symblepharon","Trichiasis","Ectropion","Tylosis"],"a":0,"e":"Ans. A. Symblepharon Adhesion of the lids to eyeball is called symblepharon. It occurs due to fusion of palpebral conjunctiva (covering inner surface of lid) to bulbur conjunctiva (covering outer surface of eyeball).","pyqMatches":[{"year":"2012","no":992,"q":"Fusion of palpebral and bulbar conjunctiva is","o":["Symblepharon","Trichiasis","Ectropion","Tylosis"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5001, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Easy', 'Ophthalmology', 448, '{"id":5001,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Easy","source":"Ophthalmology","sourceNo":448,"q":"Most common orbital tumor has its origin from?","o":["Blood vessels","Nerves","Muscle","Lymph node"],"a":0,"e":"Ans, A. Blood vessels Most common orbital tumors are benign vascular tumors - Cavernous hemangioma.","pyqMatches":[{"year":"2012","no":988,"q":"Most common orbital tumor has its origin from?","o":["Blood vessels","Nerves","Muscle","Lymph node"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5002, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 449, '{"id":5002,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":449,"q":"Retinal astrocytoma is seen in ?","o":["Tuberous sclerosis","Sturge weber syndrome","Von Hippel-Lindau syndrome","None"],"a":0,"e":"Ans. A. Tuberous sclerosis","pyqMatches":[{"year":"2012","no":991,"q":"Retinal astrocytoma is seen in ?","o":["Tuberous sclerosis","Sturge weber syndrome","Von Hippel-Lindau syndrome","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5003, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Easy', 'Ophthalmology', 450, '{"id":5003,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Easy","source":"Ophthalmology","sourceNo":450,"q":"Most common malignant tumour of eyelid is ?","o":["Sebaceous gland carcinoma","Basal cell carcinoma","Squamous cell carcinoma","Malignant melanoma"],"a":1,"e":"Ans, b. Basal cell carcinoma Basal cell carcinoma is the most common malignant tumour of the eyelids and constitutes 85-90% of all malignant epithelialeyelid tumours.","pyqMatches":[{"year":"2012","no":989,"q":"Most common malignant tumour of eyelid is ?","o":["Sebaceous gland carcinoma","Basal cell carcinoma","Squamous cell carcinoma","Malignant melanoma"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5004, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 451, '{"id":5004,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":451,"q":"Most common carcinoma of conjunctiva ?","o":["Squamous cell Ca","Basal cell ca","Melanoma","Lymphoma"],"a":0,"e":"Ans. A. Squamous cell Ca Squamous cell carcinoma is the most common malignant lesion of the conjunctiva\"","pyqMatches":[{"year":"2012","no":990,"q":"Most common carcinoma of conjunctiva ?","o":["Squamous cell Ca","Basal cell ca","Melanoma","Lymphoma"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5005, 'Ophthalmology', 'Refraction & Optics', 'Easy', 'Ophthalmology', 452, '{"id":5005,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Easy","source":"Ophthalmology","sourceNo":452,"q":"Astigmatism in emmetropic eye of elderly person contribute to:","o":["+1d","+2D","+3d","+4d"],"a":2,"e":"Answer C. +3d Laser vision enhancements When planning presbyopia-correcting IOL(Intra ocular lens) surgery in a patient with a high level of pre-existing astigmatism (ie, more than 3 D), a bioptics approach (ie, IOL followed by laser vision enhancement) may be needed. LRIs alone are unlikely to correct the astigmatism completely.Limbal Relaxing Incisions (LRI) are a refractive surgical procedure to correct minor astigmatism in the eye. There are several different strategies for these planned laser vision enhancements. The first is to perform the presbyopia-correcting IOL surgery followed by LASIK or PRK.","pyqMatches":[{"year":"2018","no":123,"q":"Astigmatism in emmetropic eye of elderly person contribute to:","o":["+1d","+2D","+3d","+4d"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5006, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 453, '{"id":5006,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":453,"q":"100 day Glaucoma seen in which of the following condition:","o":["Central retinal vein occlusion (CRVO)","Neovascular glaucoma","Central retinal artery occlusion (CRAO)","Steroid induced Glaucoma"],"a":0,"e":"Answer- A, Central retinal vein occlusion (CRVO) 100 days glaucoma is a neovascular glaucoma occurring in CRVO. Central Retinal vein occlusion (CRVO)","pyqMatches":[{"year":"2017","no":155,"q":"100 day Glaucoma seen in which of the following condition:","o":["Central retinal vein occlusion (CRVO)","Neovascular glaucoma","Central retinal artery occlusion (CRAO)","Steroid induced Glaucoma"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":124,"q":"100 day Glaucoma seen in which of the following condition:","o":["Central retinal vein occlusion (CRVO)","Neovascular glaucoma","Central retinal artery occlusion (CRAO)","Steroid induced Glaucoma"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5007, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 454, '{"id":5007,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":454,"q":"Q Roth spots is seen in:","o":["Uveal melanoma","Acute leukaemia","Both a & b","None of the above"],"a":1,"e":"Answer- B. Acute leukaemia Roth''s spots are retinal hemorrhages with white or pale centers. Composed of coagulated fibrin including platelets, focal ischemia, inflammatory infiltrate, infectious organisms, or neoplastic cells. Roth''s spots may be observed in leukemia, diabetes, subacute bacterial endocarditis, pernicious anemia, ischemic events, hypertensive retinopathy and rarely in HIV retinopathy. Roth''s spots are named after Moritz Roth.","pyqMatches":[{"year":"2017","no":156,"q":"Q Roth spots is seen in:","o":["Uveal melanoma","Acute leukaemia","Both a & b","None of the above"],"a":1,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":125,"q":"Q Roth spots is seen in:","o":["Uveal melanoma","Acute leukaemia","Both a & b","None of the above"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5008, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 455, '{"id":5008,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":455,"q":"Yoke muscle of right lateral rectus:","o":["Lt medial rectus","Lt superior rectus","Lt lateral rectus","Lt inferior oblique"],"a":0,"e":"Answer - A. Lt medial rectus Contralaterally paired extraocular muscles that work synergistically to direct the gaze in a given direction. For example, in directing the gaze to the right, the right lateral rectus and left medial rectus operate together as yoke muscles. Yoke Muscles: 2 Muscles (1 in each eye) that are the prime movers of their respective eyes in a given possitiono of gaze For - Example - when the eyes move into right gaze (dextroversin), the right lateral rectus & the left medial rectus muscle are yoke muscles.","pyqMatches":[{"year":"2017","no":157,"q":"Yoke muscle of right lateral rectus:","o":["Lt medial rectus","Lt superior rectus","Lt lateral rectus","Lt inferior oblique"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":126,"q":"Yoke muscle of right lateral rectus:","o":["Lt medial rectus","Lt superior rectus","Lt lateral rectus","Lt inferior oblique"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5009, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 456, '{"id":5009,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":456,"q":"Severe Conjunctivitis caused by:","o":["Neisseria","Staphylococcus","Streptococcus","Haemophilus"],"a":0,"e":"ANSWER- A. Neisseria The most common causes of acute bacterial conjunctivitis are Staphylococcus aureus, Streptococcus pneumoniae, and Haemophilus influenzae. Hyperacute cases are usually caused by Neisseria gonorrhoeae or N. meningitidis. Chronic cases of bacterial conjunctivitis are those lasting longer than 3 weeks, and are typically caused by Staphylococcus aureus, Moraxella lacunata, or gram-negative enteric flora. Neisseria gonorrhoeae causes gonococcal conjunctivitis, which usually results from sexual contact with a person who has a genital infection. The incidence rates of gonococcal conjunctivitis increase during spring and summer. This is a potentially devastating ocular infection, because N. gonorrhoeae can cause severe ulcerative keratitis, which may rapidly progress to corneal perforation.","pyqMatches":[{"year":"2017","no":158,"q":"Severe Conjunctivitis caused by:","o":["Neisseria","Staphylococcus","Streptococcus","Haemophilus"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":127,"q":"Severe Conjunctivitis caused by:","o":["Neisseria","Staphylococcus","Streptococcus","Haemophilus"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5010, 'Ophthalmology', 'Refraction & Optics', 'Easy', 'Ophthalmology', 457, '{"id":5010,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Easy","source":"Ophthalmology","sourceNo":457,"q":"Which is example of the Simple Myopic Astigmatism among the prescriptions given below:","o":["Rx (+) sphere","Rx will be plano (-)","Rx will be (-) sphere","(-)(+) (+)(-) on both 90 and 180 degree axis"],"a":1,"e":"Answer- B. Rx will be plano (-) When eyewear prescriptions are written, they can be classified into different areas depending on the power or refractive error. There are seven categories to which prescriptions can fall:","pyqMatches":[{"year":"2017","no":159,"q":"Which is example of the Simple Myopic Astigmatism among the prescriptions given below:","o":["Rx (+) sphere","Rx will be plano (-)","Rx will be (-) sphere","(-)(+) (+)(-) on both 90 and 180 degree axis"],"a":1,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":128,"q":"Which is example of the Simple Myopic Astigmatism among the prescriptions given below:","o":["Rx (+) sphere","Rx will be plano (-)","Rx will be (-) sphere","(-)(+) (+)(-) on both 90 and 180 degree axis"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5011, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Easy', 'Ophthalmology', 458, '{"id":5011,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Easy","source":"Ophthalmology","sourceNo":458,"q":"Blow out fracture of orbit involves:","o":["Floor","Medial wall","Lateral wall","Roof"],"a":0,"e":"Answer-A. Floor Orbital floor fracture, also known as “blowout” fracture of the orbit. Blow out fracture of orbit involves:","pyqMatches":[{"year":"2017","no":160,"q":"Blow out fracture of orbit involves:","o":["Floor","Medial wall","Lateral wall","Roof"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":129,"q":"Blow out fracture of orbit involves:","o":["Floor","Medial wall","Lateral wall","Roof"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5012, 'Ophthalmology', 'Lens & Cataract', 'Hard', 'Ophthalmology', 459, '{"id":5012,"subject":"Ophthalmology","chapter":"Lens & Cataract","difficulty":"Hard","source":"Ophthalmology","sourceNo":459,"q":"A diabetic patient 2 days after post cataract surgery develops develops hypopyon. What will be the management?","o":["Intravitreal antibiotics","Eye drops","Surgery","No treatment required"],"a":0,"e":"Ans. A. Intravitreal antibiotics","pyqMatches":[{"year":"2018","no":291,"q":"A diabetic patient 2 days after post cataract surgery develops develops hypopyon. What will be the management?","o":["Intravitreal antibiotics","Eye drops","Surgery","No treatment required"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5013, 'Ophthalmology', 'Glaucoma', 'Easy', 'Ophthalmology', 460, '{"id":5013,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Easy","source":"Ophthalmology","sourceNo":460,"q":"What is the Thinnest part of neuro-retinal rim according to ISNT rule?","o":["Inferior","Superficial","Temporal","Medial"],"a":2,"e":"Ans. C. Temporal The ISNT rule is an easy way to remember how the optic nerve is supposed to look in a normal eye. Normally the neuro-retinal rim is thickest Inferiorly and thinnest Temporally. With glaucoma, however, you begin to see vertical thinning, with atrophy along the inferior and superior rims.","pyqMatches":[{"year":"2018","no":292,"q":"What is the Thinnest part of neuro-retinal rim according to ISNT rule?","o":["Inferior","Superficial","Temporal","Medial"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5014, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 461, '{"id":5014,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":461,"q":"What causes shifting fluid?","o":["Exudative Retinal detachment","Tractional Retinal Detachment","Rhegmatogenous retinal detachment","Retinodialysis"],"a":0,"e":"Ans.a.Exudative Retinal detachment. >In exudative retinal detachment, the subretinal fluid may be confined to a localized area, usually the posterior pole, or may extend to the periphery, even forming bullous retinal detachment. >The characteristic feature of a significant exudative retinal detachment is the presence of shifting subretinal fluid. >The fluid shifts to the most dependent location when patients change body position. https://clinicalgate.com/nonrhegmatogenous-retinal-detachment/","pyqMatches":[{"year":"2020","no":128,"q":"What causes shifting fluid?","o":["Exudative Retinal detachment","Tractional Retinal Detachment","Rhegmatogenous retinal detachment","Retinodialysis"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5015, 'Ophthalmology', 'Cornea & External Eye', 'Moderate', 'Ophthalmology', 462, '{"id":5015,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Moderate","source":"Ophthalmology","sourceNo":462,"q":"Conjunctival injection, pharyngeal injection, polymorphic rash, cervical lymphadenopathy can be seen in","o":["Kawasaki syndrome","Measles","Thrombocytopenia","Mumps"],"a":0,"e":"Ans: a.Kawasaki syndrome. >Kawasaki disease is a generalized vasculitis that affects medium- sized arteries. > It is characterized by systemic inflammation that manifests as persistent fever, erythema of the mucous membranes, bilateral nonexudative conjunctivitis, rash, swelling and redness of the hands and feet, and cervical lymphadenopathy Ref:https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3034467/","pyqMatches":[{"year":"2020","no":129,"q":"Conjunctival injection, pharyngeal injection, polymorphic rash, cervical lymphadenopathy can be seen in","o":["Kawasaki syndrome","Measles","Thrombocytopenia","Mumps"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5016, 'Ophthalmology', 'Miscellaneous', 'Moderate', 'Ophthalmology', 463, '{"id":5016,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Ophthalmology","sourceNo":463,"q":"Incongruous Homonymous hemianopia with Wernicke''s hemianopia pupil is seen with the lesion of","o":["Optic radiation","Lateral geniculate body","Optic tract","Anterior occipital cortex"],"a":2,"e":"Ans:c. Optic tract >Anterior optic tract lesion produces Incongruous Homonymous hemianopia, decreased visual acuity, afferent pupil defect(Wernicke''s hemianopia pupil) and atrophy of optic discs with characteristic Bow-tie atrophy are contralateral. >A complete Homonymous hemianopia results from posterior optic tract lesions. Ref:https://books.google.co.in/books? id=bDpI9n4q3e0C&pg=PA376&lpg=PA376&dq=Incongruous+Homo fCi_bmAhUoxzgGHf56An8Q6AEwFXoECAoQAQ#v=onepage&q=In","pyqMatches":[{"year":"2020","no":130,"q":"Incongruous Homonymous hemianopia with Wernicke''s hemianopia pupil is seen with the lesion of","o":["Optic radiation","Lateral geniculate body","Optic tract","Anterior occipital cortex"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5017, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Hard', 'Ophthalmology', 464, '{"id":5017,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Hard","source":"Ophthalmology","sourceNo":464,"q":"The patient came with proptosis, restriction of eye movements, and was Euthyroid. What could this be from?","o":["Orbital Cellulitis","Orbital Lymphoma","Orbital pseudotumor","Thyroid ophthalmopathy"],"a":2,"e":"Ans: C.Orbital pseudotumor >Proptosis and restricted eye movement is most commonly associated with thyroid ophthalmopathy >But in question asked is Euthyroid. >So, the best option to select is Orbital pseudotumor(Idiopathic orbital inflammatory syndrome) Ref. Comprehensive Ophthalmology by AK Khurana - 6th Edition Page no 335","pyqMatches":[{"year":"2020","no":131,"q":"The patient came with proptosis, restriction of eye movements, and was Euthyroid. What could this be from?","o":["Orbital Cellulitis","Orbital Lymphoma","Orbital pseudotumor","Thyroid ophthalmopathy"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5018, 'Ophthalmology', 'Uvea', 'Easy', 'Ophthalmology', 465, '{"id":5018,"subject":"Ophthalmology","chapter":"Uvea","difficulty":"Easy","source":"Ophthalmology","sourceNo":465,"q":"Prerequisite for sympathetic ophthalmitis","o":["Penetrating injury to the eye","Blunt ocular tumor","Chemical injury","Urinary tract infection"],"a":0,"e":"Ans: a. Penetrating injury to the eye. >Sympathetic ophthalmia is a rare type of uveitis that causes small abnormal clumps of cells (granulomas) to form. >This disorder occurs in the uninjured eye after a penetrating injury (such as when a pencil, pen, or stick punctures the eye) or surgery to the other (injured) eye. Ref:https://www.msdmanuals.com/en-in/home/eye-disorders/uveitis- and-related-disorders/sympathetic-ophthalmia.","pyqMatches":[{"year":"2020","no":132,"q":"Prerequisite for sympathetic ophthalmitis","o":["Penetrating injury to the eye","Blunt ocular tumor","Chemical injury","Urinary tract infection"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5019, 'Ophthalmology', 'Retina & Vitreous', 'Easy', 'Ophthalmology', 466, '{"id":5019,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Easy","source":"Ophthalmology","sourceNo":466,"q":"Photostress test to differentiate","o":["Lens and cornea","The macula and Optic nerve diseases","Cataract and glaucoma","Retinal and vitreous diseases"],"a":1,"e":"Ans:b.The macula and Optic nerve diseases. >To distinguish optic nerve conduction defects from the macular disease in patients with otherwise unexplained loss of central vision we first determined the best visual acuity with correction at distance in unilateral defects. > The normal eye was tested first and photo stressed for ten seconds by looking at an ordinary penlight held 2 to 3 cm from the eye. >The time required to read three letters on three Snellen test lines just larger than the best acuity was used as the endpoint. >Recovery time will be prolonged with maculopathy. >Prolonged recovery time will not be observed in patients who have optic nerve disease. https://www.ncbi.nlm.nih.gov/pubmed/836667","pyqMatches":[{"year":"2020","no":133,"q":"Photostress test to differentiate","o":["Lens and cornea","The macula and Optic nerve diseases","Cataract and glaucoma","Retinal and vitreous diseases"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5020, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 467, '{"id":5020,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":467,"q":"Which layer of cornea helps in the hydration of stroma of cornea","o":["Endothelium","Epithelium","Descemet membrane","Stroma"],"a":0,"e":"Ans: a.Endothelium >The corneal endothelium is responsible for maintaining the hydration of the cornea. > This is through a \"Pump-Leak\" mechanism where the active transport properties of the endothelium represent the \"Pump\" and the stromal swelling pressure represents the \"Leak\" Ref:https://www.researchgate.net/publication/51238307_Molecular_Me","pyqMatches":[{"year":"2020","no":134,"q":"Which layer of cornea helps in the hydration of stroma of cornea","o":["Endothelium","Epithelium","Descemet membrane","Stroma"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5021, 'Ophthalmology', 'Ocular Motility & Strabismus', 'Hard', 'Ophthalmology', 468, '{"id":5021,"subject":"Ophthalmology","chapter":"Ocular Motility & Strabismus","difficulty":"Hard","source":"Ophthalmology","sourceNo":468,"q":"A 65 old male with a history of hypertension and diabetes, presents to the OPD with complaints of diplopia and squint. On examination, the secondary deviation is more than the primary deviation. Which of the following is most likely diagnosis","o":["concomitant squint","paralytic squint","Restrictive squint","Pseudo squint"],"a":1,"e":"Ans:b.paralytic squint. >Paralytic or incomitant squint occurs when there is an acquired defect of the movement of an eye. > The squint (and double vision) is maximally demonstrated by looking in the direction of action of the weakened muscle. >Paralytic squints occur due to disease of the III, IV and VI cranial nerves. Ref:https://www.gponline.com/basics- strabismus/ophthalmology/article/1055827","pyqMatches":[{"year":"2020","no":135,"q":"A 65 old male with a history of hypertension and diabetes, presents to the OPD with complaints of diplopia and squint. On examination, the secondary deviation is more than the primary deviation. Which of the following is most likely diagnosis","o":["concomitant squint","paralytic squint","Restrictive squint","Pseudo squint"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5022, 'Ophthalmology', 'Refraction & Optics', 'Easy', 'Ophthalmology', 469, '{"id":5022,"subject":"Ophthalmology","chapter":"Refraction & Optics","difficulty":"Easy","source":"Ophthalmology","sourceNo":469,"q":"Esotropia is common in","o":["Myopia","Hypermetropia","Emmetropia","Astigmatism"],"a":1,"e":"And: B. Hypermetropia >Patients with refractive esotropia are typically farsighted (hyperopic). > This means that the eyes must work harder to see clearly, particularly when the object of regard is up close. https://aapos.org/glossary/accommodative-esotropia","pyqMatches":[{"year":"2020","no":136,"q":"Esotropia is common in","o":["Myopia","Hypermetropia","Emmetropia","Astigmatism"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5023, 'Ophthalmology', 'Miscellaneous', 'Easy', 'Ophthalmology', 470, '{"id":5023,"subject":"Ophthalmology","chapter":"Miscellaneous","difficulty":"Easy","source":"Ophthalmology","sourceNo":470,"q":"An extra row of cilia posterior to the grey line","o":["Distichiasis","Tylosis","Madarosis","Trichiasis"],"a":0,"e":"And: a. Distichiasis >Distichiasis is a rare disorder defined as the abnormal growth of lashes from the orifices of the meibomian glands on the posterior lamella of the tarsal plate. Ref:https://emedicine.medscape.com/article/1212908-overview","pyqMatches":[{"year":"2020","no":137,"q":"An extra row of cilia posterior to the grey line","o":["Distichiasis","Tylosis","Madarosis","Trichiasis"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5024, 'Ophthalmology', 'Orbit & Ocular Adnexa', 'Hard', 'Ophthalmology', 471, '{"id":5024,"subject":"Ophthalmology","chapter":"Orbit & Ocular Adnexa","difficulty":"Hard","source":"Ophthalmology","sourceNo":471,"q":"The patient came with unilateral Proptosis and bilateral Abducent nerve palsy. This could be from","o":["Cavernous sinus","Orbital cellulitis","Orbital pseudotumor","Orbital lymphoma"],"a":0,"e":"Ans: a.Cavernous sinus >Proptosis is initially seen unilaterally ultimately becomes bilateral. >6th cranial nerve(Abducent) passes through the cavernous sinus.so in cavernous sinus thrombosis bilateral abducens palsy is seen. Parson''s Diseases of the Eye -Ed. 22 Pg 497","pyqMatches":[{"year":"2020","no":138,"q":"The patient came with unilateral Proptosis and bilateral Abducent nerve palsy. This could be from","o":["Cavernous sinus","Orbital cellulitis","Orbital pseudotumor","Orbital lymphoma"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5025, 'Ophthalmology', 'Cornea & External Eye', 'Easy', 'Ophthalmology', 472, '{"id":5025,"subject":"Ophthalmology","chapter":"Cornea & External Eye","difficulty":"Easy","source":"Ophthalmology","sourceNo":472,"q":"The characteristic finding of fungal ulcers?","o":["Satellite lesions","Dendritic ulcer","Ring abscess","White hypopyon"],"a":0,"e":"And.a.Satellite lesions >Fungal keratitis or keratomycosis refers to an infective process of the cornea caused by any of the multiple pathologic fungi capable of invading the ocular surface. >when the epithelial integrity is broken either due to trauma or ocular surface disease and the organism gains access into the tissue and proliferates. >Multifocal stromal infiltrates or \"satellite lesions\" have been considered a characteristic feature of fungal keratitis. Ref: https://eyewiki.aao.org/Fungal_Keratitis","pyqMatches":[{"year":"2020","no":139,"q":"The characteristic finding of fungal ulcers?","o":["Satellite lesions","Dendritic ulcer","Ring abscess","White hypopyon"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5026, 'Ophthalmology', 'Glaucoma', 'Hard', 'Ophthalmology', 473, '{"id":5026,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Hard","source":"Ophthalmology","sourceNo":473,"q":"A drug used in a patient with increased IOP and optic disc changes, ciliary congestion for decrease IOP acts by increasing uveoscleral outflow is","o":["Latanoprost","Pilocarpine","Dorzolamide","Timolol"],"a":0,"e":"Ans: a. Latanoprost >Latanoprost selectively stimulates the prostaglandin F2 alpha receptor and this results in a decreased intraocular pressure (IOP) via the increased outflow of aqueous humor, which is often implicated in cases of elevated intraocular pressure. Ref:https://www.google.com/url? sa=t&source=web&rct=j&url=https://www.drugbank.ca/drugs/DB00654& Nz08_cOFzeYemAzeWf&cshid=1578651404060","pyqMatches":[{"year":"2020","no":140,"q":"A drug used in a patient with increased IOP and optic disc changes, ciliary congestion for decrease IOP acts by increasing uveoscleral outflow is","o":["Latanoprost","Pilocarpine","Dorzolamide","Timolol"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5027, 'Ophthalmology', 'Retina & Vitreous', 'Hard', 'Ophthalmology', 474, '{"id":5027,"subject":"Ophthalmology","chapter":"Retina & Vitreous","difficulty":"Hard","source":"Ophthalmology","sourceNo":474,"q":"A patient diagnosed with Rheumatoid arthritis was on medications. After 2 years, he developed a blurring vision and was found to have corneal opacity. Which drug is most likely to cause this?","o":["Sulfasalazine","Chloroquine","Methotrexate","Leflunomide"],"a":1,"e":"Ans: B. Chloroquine In long-term chloroquine therapy Ocular complications were observed >This therapy is usually used in patients with rheumatoid arthritis, lupus erythematosus, sarcoidosis, discoid lupus, and other chronic \"collagen disease\". >Retinal changes, corneal opacifications, blurring of vision are some complications seen in long term use of Chloroquine. Ref:https://www.ncbi.nlm.nih.gov/pubmed/1427503","pyqMatches":[{"year":"2020","no":141,"q":"A patient diagnosed with Rheumatoid arthritis was on medications. After 2 years, he developed a blurring vision and was found to have corneal opacity. Which drug is most likely to cause this?","o":["Sulfasalazine","Chloroquine","Methotrexate","Leflunomide"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5028, 'Orthopedics', 'Pediatric Orthopedics', 'Easy', 'Orthopedics', 1, '{"id":5028,"subject":"Orthopedics","chapter":"Pediatric Orthopedics","difficulty":"Easy","source":"Orthopedics","sourceNo":1,"q":"Which of the following is caused by congenital 17 hydroxylase deficiency:","o":["Hyperkalemia","Hermaphroditism","Hypertension","Virilism"],"a":2,"e":"Hypertension 17 -hydroxylase (17 -OH) deficiency syndrome is a rare genetic disorder of steroid biosynthesis causing decreased production of glucocorticoids and sex steroids and increased synthesis of mineralocorticoid precursors. Reduced or absent levels of both gonadal and adrenal sex hormones result in sexual infantilism in 46, XX females and ambiguous genitalia in 46, XV males. Excessive mineralocorticoid activity produces varying degrees of hypertension Q and hypokalemia Q. Patients usually are diagnosed with this condition during an evaluation of delayed puberty. absent secondary sexual characteristics or primary amenorrhea.Q","pyqMatches":[{"year":"2013","no":1475,"q":"Which of the following is caused by congenital 17 hydroxylase deficiency:","o":["Hyperkalemia","Hermaphroditism","Hypertension","Virilism"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5029, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 2, '{"id":5029,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":2,"q":"True about lumbricals is","o":["Flex IP joints and extends MCP joint","1st and 2nd supplied by radial nerve","3 and 4 supplied by superficial branch of ulnar","Origin from tendons of flexor digitorum profundus"],"a":3,"e":"Answer. D Origin from tendons of flexor digitorum profundus* The four lumbrical muscles arise from the tendons of flexor digitorum profundus. They have different origins: Each passes distally to the radial side of its nearest metacarpophalangeal joint of the fingers to be inserted into the dorsal extensor expansionof digits two to five. Their actions on these digits are to: * Extend the interphalangeal joints * Flex the metacarpophalangeal joints The innervation of the lumbricals is dual: * The radial first and second lumbricals are supplied by the median nerve (C8, T1) * The ulnar third and fourth lumbricals are supplied by the deep branch of the ulnar nerve (C8, T1) * Occasionally, the third lumbrical can receive its innervation from the median nerve.","pyqMatches":[{"year":"2015","no":11,"q":"True about lumbricals is","o":["Flex IP joints and extends MCP joint","1st and 2nd supplied by radial nerve","3 and 4 supplied by superficial branch of ulnar","Origin from tendons of flexor digitorum profundus"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5030, 'Orthopedics', 'Miscellaneous', 'Hard', 'Orthopedics', 3, '{"id":5030,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Hard","source":"Orthopedics","sourceNo":3,"q":"In patients with hypertrophic cardiomyopathy maximum mutations are found in which gene:","o":[". β - myosin heavy chain","Elastin",". α - tropomyosin","Troponin T"],"a":0,"e":"β - Myosin heavy chain Mutations in gene for β - Mysoin heavy chain are associated with 40% of the families with hypertrophic cardiomyopathy. Troponin T mutations - 15% of the families α - tropomyosin mutations ~5% of the families","pyqMatches":[{"year":"2016","no":420,"q":"In patients with hypertrophic cardiomyopathy maximum mutations are found in which gene:","o":[". β - myosin heavy chain","Elastin",". α - tropomyosin","Troponin T"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5031, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 4, '{"id":5031,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":4,"q":"What is the venous hematocrit level at which you will diagnose polycythemia in a newborn?","o":["55%","60%","65%","70%"],"a":2,"e":"Definition of polycythemia: a. Venous haematocrit of over 65%. b. Venous haematocrit of over 64% at 2 hours age. c. An umbilical venous or arterial haematocrit over 63% or more. The mean venous haematocrit of term infants is 53 in cord blood, 60 at 2 hours of age, 57 at 6 hours of age and 52 at 12-18 hours of age. As the haematocrit increases, there is increased viscosity and decreased blood flow. When haematocrit increases to more than 60% there is a fall in O2 transport. Definition of hyperviscosity: Viscosity greater than 14.6 centipose at a shear rate of 11.55 as measured by a viscometer. (normal is 1.4- 1.8 centipoise).","pyqMatches":[{"year":"2012","no":487,"q":"What is the venous hematocrit level at which you will diagnose polycythemia in a newborn?","o":["55%","60%","65%","70%"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5032, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 4, '{"id":5032,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":4,"q":"Limb shortening","o":["1,2 true & 3,4 false","2,3 True & 1,4 false","1,2,3 true & 4 false","All are true"],"a":3,"e":"It is also known as the pars plana and Pseudo Coxalgia. It is an osteochondritis of the femoral head. The femoral head becomes partly or wholly avascular and deformed. Etiology is not definetly known. It is supposed to be due to reccurent episoedes of ischemia of the femoral head in the suceptible age group, probably perecipitaed by episodes of synovitis. Pathology: the disease progresses in three ill defined stages: Stage of synovitis Stage of trabecular necrosis Stage of healing Clinical features: Commonly seen in the age group of 5 to 10 years. Child present with pain in the hip which often radiates to the knee or may also present with limp or hip stiffness. On examination, the finding are minimal. sometimes the only finding being limitation of abduction and internal rotation and shortening. X- ray shows collapse and sclerosis of the epiphysis of the femoral head. hip joint space is increased. Bone scan may show a decreased uptake by the head of the femur. Treatment: The primary aim is to prevent the head from ill shaping while the bone is in the softening phase. The head is required to be kept inside the acetabulum while the revascularization takes place (i.e. containment). This may be achieved by corrective methods (plaster, splint etc.) or by operation (containment osteotomy). Ref: Maheshwari 3/e, Page 269-70.","pyqMatches":[{"year":"2015","no":4,"q":"Limb shortening","o":["1,2 true & 3,4 false","2,3 True & 1,4 false","1,2,3 true & 4 false","All are true"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5033, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 5, '{"id":5033,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":5,"q":"The significance of difference between proportions can also be tested by-","o":[".‘t’ test","Chi square test","ANOVA","Correlation and regression"],"a":1,"e":"Ans. B. Chi square test Chi-Square test offers a method of testing the significance of difference between the proportions. Its advantage lies in the fact that it can also be used when more than two groups are to be compared. By using this test, we can find out if the difference between two proportions or ratios has occurred by chance. The steps involved are-","pyqMatches":[{"year":"2019","no":139,"q":"The significance of difference between proportions can also be tested by","o":[".‘t’ test","Chi square test","ANOVA","Correlation and regression"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5034, 'Orthopedics', 'Miscellaneous', 'Moderate', 'Orthopedics', 6, '{"id":5034,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Orthopedics","sourceNo":6,"q":"Peripheral and central chemoreceptors may both contribute to the increased ventilation that occurs as a result of which of the following?","o":["A decrease in arterial oxygen content","A decrease in arterial blood pressure","An increase in arterial carbon dioxide tension","A decrease in arterial oxygen tension"],"a":2,"e":"The central chemoreceptors located on or near the ventral surface of the medulla cause an increase in ventilation in response to an increase in PacO2 and to a lesser extent to a decrease in arterial pH because the blood brain barrier is relatively impermeable to hydrogen ions. The peripheral chemoreceptors in the carotid bodies cause an increase in ventilation in response to an increase in PacO2 a decrease in arterial pH, and a decrease in PaO2. Neither the central chemoreceptors nor the carotid bodies are stimulated by a decrease in arterial blood pressure or O2 content.","pyqMatches":[{"year":"2012","no":132,"q":"Peripheral and central chemoreceptors may both contribute to the increased ventilation that occurs as a result of which of the following?","o":["A decrease in arterial oxygen content","A decrease in arterial blood pressure","An increase in arterial carbon dioxide tension","A decrease in arterial oxygen tension"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5035, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 7, '{"id":5035,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":7,"q":"Wireless capsule endoscopy is done to visualize which of the following condition?","o":["Esophageal varices","Gastric carcinoma","Crohn''s disease","Ulcerative colitis"],"a":2,"e":"Crohn''s disease Wireless capsule endoscopy (WCE) allows direct visualization of the entire small-bowel mucosa. The diagnostic yield of detecting lesions suggestive of active CD is higher with WCE than CT enterography or small-bowel series. WCE cannot be used in the setting of a small-bowel stricture. Capsule retention occurs in <1 % of patients with suspected CD, but retention rates of 4- -6% are seen in patients with established CD.","pyqMatches":[{"year":"2013","no":1776,"q":"Wireless capsule endoscopy is done to visualize which of the following condition?","o":["Esophageal varices","Gastric carcinoma","Crohn''s disease","Ulcerative colitis"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5036, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 8, '{"id":5036,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":8,"q":"Thomas test is used for testing?","o":["Hip flexion","Knee flexion","Hip abduction","Hip rotation"],"a":0,"e":"A Hip flexion REF: Lange Instant Access: Orthopedics and Sports Medicine, by Anil Patel, page 106 Thomas Test: With the patient lying supine, maximally flex both hips. Allow the femur on the ipsilateral side to fall into as much extension as possible, while holding the other hip up. The angle between the femur and examining table is the residual flexion and represents the flexion contracture.","pyqMatches":[{"year":"2015","no":1438,"q":"Thomas test is used for testing?","o":["Hip flexion","Knee flexion","Hip abduction","Hip rotation"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5037, 'Orthopedics', 'Upper Limb', 'Moderate', 'Orthopedics', 9, '{"id":5037,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Moderate","source":"Orthopedics","sourceNo":9,"q":"Indication for surgical compartment release in compartment Syndrome in any compartment is absolute pressure greater than?","o":["15 mm Hg","20 mm Hg","30 mm Hg","Varies from compartment to compartment"],"a":2,"e":"30 mm Hg REF: With text \"Setting the threshold for fasciotomy at a perfusion pressure of 30 mmHg can be considered safe, but still may lead to overtreatment if used routinely\" REF: Evidence-based Orthopedics - Mohit Bhandari Page 634 Different authors consider surgical intervention if: (REF: Tiwari A, Haq A I, Myint F, Hamilton G. Acute compartment syndromes. Br J Surg 2002; 89: 397-412.)","pyqMatches":[{"year":"2016","no":1328,"q":"Indication for surgical compartment release in compartment Syndrome in any compartment is absolute pressure greater than?","o":["15 mm Hg","20 mm Hg","30 mm Hg","Varies from compartment to compartment"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5038, 'Orthopedics', 'Miscellaneous', 'Moderate', 'Orthopedics', 10, '{"id":5038,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Orthopedics","sourceNo":10,"q":"Which is not true of Tabes dorsalis?","o":["Seen in neuro syphilis","Paresthesia is seen","Deep tendon reflexes are retained","Abdominal pain and visceral symptoms occur"],"a":2,"e":"Deep tendon reflexes are retained REF: Harrison''s Principles of Internal Medicine 17th ed chapter 372 TABES DORSALIS: The classic syndromes of tabes dorsalis and meningovascular syphilis of the spinal cord are now less frequent than in the past but must be considered in the differential diagnosis of spinal cord disorders. The characteristic symptoms of tabes are fleeting and repetitive lancinating pains, primarily in the legs or less often in the back, thorax, abdomen, arms, and face. Ataxia of the legs and gait due to loss of position sense occurs in half of patients. Paresthesias, bladder disturbances, and acute abdominal pain with vomiting (visceral crisis) occur in 15-30% of patients. The cardinal signs of tabes are loss of reflexes in the legs; impaired position and vibratory sense; Romberg''s sign; and, in almost all cases, bilateral Argyll Robertson pupils, which fail to constrict to light but accommodate. Diabetic polyradiculopathy may simulate tabes.","pyqMatches":[{"year":"2014","no":1367,"q":"Which is not true of Tabes dorsalis?","o":["Seen in neuro syphilis","Paresthesia is seen","Deep tendon reflexes are retained","Abdominal pain and visceral symptoms occur"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5039, 'Orthopedics', 'Miscellaneous', 'Moderate', 'Orthopedics', 11, '{"id":5039,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Orthopedics","sourceNo":11,"q":"Vitamin not deficient in celiac disease is?","o":["Vitamin D","Vitamin B 12","Folic acid","Vitamin A"],"a":2,"e":"Folk acid REF: Sheila Crowe - 2010 page 384, Harrison 17th ed chapter 288 Vitamins deficient in celiac disease are:","pyqMatches":[{"year":"2014","no":1288,"q":"Vitamin not deficient in celiac disease is?","o":["Vitamin D","Vitamin B 12","Folic acid","Vitamin A"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5040, 'Orthopedics', 'Arthritis & Joint Disease', 'Hard', 'Orthopedics', 12, '{"id":5040,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Hard","source":"Orthopedics","sourceNo":12,"q":"A Bone marrow transplant recipient patientdeveloped chest infection. On HRCT ''Tree in bud appearance'' is seen. Most likely causative agent is:","o":["Klebsiella","Pneumocystis","TB","RSV"],"a":1,"e":"Pneumocystis [Ref: Harrison I7/e p843; Article ''Tree in bud sign'' in Journal ''Radiology'' and ''Radiographics7 Tree-in-bud is a sign seen in HRCT, most commonly seen with endobronchial spread of Tuberculosis, but can be seen with a wide variety of conditions, most commonly infections. (Described ahead in detail). Theoretically all the options can cause ''Tree-in-bud'' sign (although Klebsiella has not been mentioned in the list). So the next clue is Bone marrow transplant. Bone marrow transplant causes a transient state of immunological deficiency leading to a wide variety of opportunistic infections. Among the given options, according to the table and text of Harrison (17/e chapter ''Infections in Transplant Recipients'') Pneumocystis and RSV can cause pneumonia after transplant: but​Pneumocystis is a much more common than RSV. Common Sources of Infections after Hematopoietic Stein Cell Transplantation Period after Transplantation Infection Site Early (<1 Month) Middle (1-4 months) Late (>6 Months) Disseminated Aerobic gram- negative, grain-positive bacteria Nocardia Candida, Aspergillus Encapsulated bacteria (Streptococcus pneumoniae, Haemophilus influenzae, Neisseria meningitidis) Skin and mucous membranes HSV- HHV-6 VZV Lungs Candida, Aspergillus HSV CMV, seasonal respiratory viruses Pneumocystis Toxoplasma Pneumocystis Gastrointestinal tract CMV Kidney BK virus, adenovirus BK virus Brain HHV-6 Toxoplasma Toxoplasma JC virus Bone marrow HHV-6 Tree-in-bud sign The tree-in-bud sign is a finding seen on thin-section computed tomographic images of the lung (HRCT). (Not seen on X-rays) Peripheral, small, centrilobular nodules are connected to linear, branching opacities that have more than one contiguous branching site, thus resembling a budding or, fruiting tree: this is known as tree-in-bud-pattern. It represents dilated and impacted (mucus or pus-filled) centrilobular bronchioles. The presence of tree-in-bud is indicative of small airway disease. It is most commonly associated with endobronchial spread of Mycobacterium tuberculosis. But it can also be seen in a large number of conditions. Pulmonary infectious disorders involving the small airways are the most common causes of the tree-in-bud sign. Any infectious organism, including bacterial, mycobacterial, viral, parasitic, and fungal agents, can involve the small airways and cause a tree-in-bud pattern. Causes of Tree-in-bud appearance Peripheral airway disease Infection Bacterial Mycobacterium tuberculosis M avium-intracellulare complex Staphylococcus aureus Haemophilus influenzae Fungal Aspergillus Pneumocystis carinii, (renamed Pneumocystis jiroveci) Viral Cytomegalovirus Respiratory syncytial virus Congenital disorders Cystic fibrosis Kartagener syndrome Idiopathic disorders Obliterative bronchiolitis Diffuse panbronchiolitis A spiration Inhalation Toxic fumes and gases Immunologic disorders Allergic bronchopulmonary aspergillosis Connective tissue disorders Rheumatoid arthritis Sjo-gren syndrome Peripheral pulmonary vascular disease Neoplasms Primary pulmonary lymphoma Neoplastic pulmonary emboli Gastric cancer Breast cancer Ewing sarcoma Renal cancer","pyqMatches":[{"year":"2016","no":1750,"q":"A Bone marrow transplant recipient patientdeveloped chest infection. On HRCT ''Tree in bud appearance'' is seen. Most likely causative agent is:","o":["Klebsiella","Pneumocystis","TB","RSV"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5041, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 13, '{"id":5041,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":13,"q":"Cause of vasodilatation in spider nevi -","o":["Estrogen","Testosterone","Hepatot oxins","FSH"],"a":0,"e":"Estrogen [Ref: Harrison 171h/e p. 1920; Robbin''s 7th/e p. 882] Spider nevi refer to dilated, visible small blood vessels in the skin. - It is called spider nevi because it consists of central \"feeding\" blood vessel with numerous fine radiating legs emanating .from the central body. Spider nevi are caused due to vasodilatation of vessels and are usually associated with cirrhosis. Cirrhosis is associated with vasodilatation and hyperdynamic circulation. \"The cause of vasodilatation in chrrhosis is uncertain but it is believed to be related to the increased level of estrogen in the both. Estrogen is a female sex hormone which is metabolized by liver. Thus in liver diseases its level tends to increase which is believe to cause vasodilatation, resulting in spider naevi.","pyqMatches":[{"year":"2013","no":1300,"q":"Cause of vasodilatation in spider nevi","o":["Estrogen","Testosterone","Hepatot oxins","FSH"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5042, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 14, '{"id":5042,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":14,"q":"Strawberry gingivitis seen in","o":["Myelocytic infiltration","Phenytoin toxicity","Wegner granulomatosis","Klipel renaunay syndrome"],"a":2,"e":"Wegener''s granulomatosis [Ref: IADVL Textbook of Dermatology 3r9e p. 695] Wegener''s granulomatosis is known to cause oral mucosal lesions. \"Strawberry gingivitis is characteristic oral lesion associated with wegener''s granulomatosis\". Straberry gingivitis clinically presents with: ? ''Swollen erythematous gums clinically resembling overripe strawberries\" Histologically strawberry gingivitis is characterized by","pyqMatches":[{"year":"2016","no":424,"q":"Strawberry gingivitis seen in","o":["Myelocytic infiltration","Phenytoin toxicity","Wegner granulomatosis","Klipel renaunay syndrome"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5043, 'Orthopedics', 'Miscellaneous', 'Moderate', 'Orthopedics', 15, '{"id":5043,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Orthopedics","sourceNo":15,"q":"Which of the following is true of Wilson''s disease all except -","o":["Autosomal recessive","Serum ceruloplasmin level < 20 mg/d1","Urinary coppor excretion < 100 microgram/c11","Zinc acetate is used as maintence therapy"],"a":2,"e":"Urinary copper excretion <100 microgram/di [Ref: Harrison 17\"''/e p. 2450, 2449] Symptomatic pts. of Wilson disease invariably have urine copper levels > 100 pg per day. Wilson disease is an autosomal recessive disorder caused by mutation in the ATP 7B gene (a copper transporting ATPase) Diagnosis - The gold standard for diagnosis is Liver biopsy with quantitative copper assayQ. Other diagnostic tests used are ? - Serum ceruloplasmin levelQ - KF rings(2 - Urine copper excretiono - DNA Helpful-ye analysisQ Serum copper values have no diagnostic value, since they may be low, normal or elevated depending upon the stage of evolution of disease. Table : Useful Diagnostic Tests for Wilson Disease Test Normal Value Wilson Disease 180-350 Serum mg/L ceruloplasmin (18-35 mg/d1) • Low in 85% • Present in 99% KF ringsAbsent - If neurologic or psychiatric symptoms present. • Present in 30-50% - in hepatic presentation and presymptomatic state • Urinary copper excretion is increased 24-h urine Cu 0.3-0.8 mmol - >1.6intn ol(>100mg) in symptomatic patients • 0.9 to > mmol (60 to > 100 mg) - in presymptomatic patients Liver Cu 0.3 — 0.8 mmol/g • Liver copper is increased (20-50 mg) tissue • > 3.1 mmol (200 mg) Haplotype analysis 0 Matches 2 Matches Treatment Zinc is the treatment of choice for Wilson diseaseQ. It produces a negative copper balance - By blocking intestinal absorption of copper - By inducing hepatic metallothionein synthesis which sequesters additional toxic copper. Table : Recommended Anticopper Treatments for Wilson Disease Disease Status First Choice Second Choice Initial hepatic manifestations Zinc Trientine and zinc Trientine and zinc Hepatic transplantation Trientine Penicillainine and zinc Hepatic transplantation Trientine and zinc • Hepatitis or cirrhosis without decompensation • Hepatitis or Cirrhosis with decompensation - Mild - Moderate - Severe Initial neurologic/psychiatric Tetraioinolybdate and zinc Trientine and zinc Maintenance therapy Zinc Trientine Presymptomatic therapy Zinc Trientine Pediatric Zinc Trientine Pregnant Zinc Trientine","pyqMatches":[{"year":"2013","no":1464,"q":"Which of the following is true of Wilson''s disease all except","o":["Autosomal recessive","Serum ceruloplasmin level < 20 mg/d1","Urinary coppor excretion < 100 microgram/c11","Zinc acetate is used as maintence therapy"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5044, 'Orthopedics', 'Miscellaneous', 'Moderate', 'Orthopedics', 16, '{"id":5044,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Orthopedics","sourceNo":16,"q":"All are true about thrombotic thrombocytopenic purpura except?","o":["Micro angiopathic hemolytic anemia","Thrombocytopenia","Normal complement level","Grossly abnormal coagulation tests"],"a":3,"e":"Ans: D. Grossly abnormal coagulation test [Ref: Robbin''s 7m/e p. 1010] * Thrombotic thrombocytopenic purpura (TTP) is characterized by the presence of widespread thrombosisthroughout the microcirculation. * The unique characteristic of these thrombi is that they are primarily composed of plateletso with very little. fibrin in it. * The consumption of platelet leads to thrombocytopenia and the presence of intravascular thrombi causes microangiopathic hemolytic anemiaQ and widespread organ dysfunction. * You must have noticed that TTP and DIC share so many similar features such as 4icrovascular occulsion and microangiopathic hemolytic anemia, But they are pathologically distinct. In TTP * Activation of coagulation cascade is not of primary importance. The thrombi present are essentially platelet thrombi, hence results of laboratory tests of coagulation such as PT and PTT are usually normal. In D.I.C. * The main defect is activation of coagulation system there fore PT and PTT are abnormal. * Patients with TTP are deficient in an enzyme called ADAMTSB. This enzyme is also known as vWf in etalloprotease. * This enzyme normally degrades very high molecular weight multimers of von-Willebrand .factor. In the absence of this enzyme, these multimers of vWF accumulate in plasma and under some circumstances promote platelet macroaggregate.formation throughout the microcirculation leading to symptoms of TTP. * Thrombotic thrombocytopenic purpura is a thrombotic microangiopathy. * The other disorders which is included in this group include H. U.S. * The diseases are characterized by widespread thrombosis in microcirculation. * The vessels which are involved are terminal arteriolesQ and capillaries. * These vessels have thrombi. * The characteristic of this thrombus is that it is primarily a platelet thrombusQ i.e. the thrombi is composed mainly of platelets and von Wilebrand factor with very little fibrin in it. Pathogenesis * Patients with TTP are deficient in an enzyme called ADAMTSBQ. (This enzyme is also known as vWf nielalloproteaSe.) * This enzyme normally degrades very high molecular weight multimers of von-Willebrand .factor. In the absence of this enzyme, these multimers of vWF accumulate in plasma and under some circumstances promote platelet macroaggregate formation throughout the microcirculation leading to symptoms of TTP. * Platelet associated immunoglobulin (IgG) and complement levels are normal in T.T.P.","pyqMatches":[{"year":"2016","no":434,"q":"All are true about thrombotic thrombocytopenic purpura except?","o":["Micro angiopathic hemolytic anemia","Thrombocytopenia","Normal complement level","Grossly abnormal coagulation tests"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5045, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 17, '{"id":5045,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":17,"q":"Most common organism associated with reactive arthritis is:","o":["Staphylococcus","Shigella","Chlamydia","Yersinia"],"a":2,"e":"Chlamydia [Ref: Harrison 17/e p2113; http://www.emedicine.com/derm/TOPIC207.HTM; http://www.entedicine.com/med/TOPIC1998.11TM] Reactive arthritis is a systemic disorder of unknown etiology that is defined by the development of conjunctivitis, urethritis, arthritis, and mucocutaneous lesions following an episode of infection elsewhere in the body. In 1916, Hans Reiter described the triad of nongonococcal urethritis, conjunctivitis, and arthritis in a young German officer with bloody dysentery.The classic triad of the disease, namely urethritis, arthritis, and conjunctivitis, is present in only one third of the patients. Reactive arthritis is frequently associated with the human leukocyte antigen B27 (1-ILA-B27) haplotype. The etiology of reactive arthritis remains uncertain. The most accepted theory about the pathophysiology of reactive arthritis involves initial activation by a microbial antigen, followed by an autoimmune reaction that involves the skin, eyes, and joints. Two forms are recognized: a sexually transmitted form and a dysenteric form. Gastrointestinal infections with Shigella, Salmonella, and Campylobacter species and other microorganisms, and genitourinary infections especially with Chlamydia trachomatis have been found to trigger reactive arthritis. Young children tend to have the post dysenteric form, whereas adolescents and young men are most likely to acquire reactive arthritis after they have urethritis. It''s not clear which organism is most commonly associated with reactive arthritis. Both Shigella and Chlamydia appear to he most common. After going through many articles from journals on the net, Chlamydia appears to he the most common. We would prefer to go with Chlamydia. (However if any one finds a reliable reference documenting the most common organism, please mail us at our email id. The article on Reactive Arthritis in the journal \"Best Practice & Research Clinical Rheumatology\" Vol. 20, No. 6, pp. 1119e1137, 2006 writes- \"The prevalence is estimated to be 30-40 cases per 100,000 adults; the annual incidence is estimated to be 4.6/100,000 .for Chlamydia-induced arthritis and 5/100,000 .for enterobacteria- induced reactive arthritis.4,5 However, real numbers may be significantly higher? The following article \"Frequency of triggering bacteria in patients with reactive arthritis and undifferentiated oligoarthritis and the relative importance of the tests used for diagnosis\" in Ann Rheum Dis. 2001 April; 60(4): 337​343 at the following website- http://www.pubmedcentralmih.gov/articlerenderfcgi?artid=1753604 writes its conclusion as: \"CONCLUSIONS—Chlamydia trachomatis, yersinia, and salmonella can be identified as the causative pathogen in about 50% of patients with probable or possible ReA if the appropriate tests are used.\"","pyqMatches":[{"year":"2015","no":1181,"q":"Most common organism associated with reactive arthritis is:","o":["Staphylococcus","Shigella","Chlamydia","Yersinia"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5046, 'Orthopedics', 'Pediatric Orthopedics', 'Easy', 'Orthopedics', 18, '{"id":5046,"subject":"Orthopedics","chapter":"Pediatric Orthopedics","difficulty":"Easy","source":"Orthopedics","sourceNo":18,"q":"Absence of Corpus callosum leads to","o":["Hemiparesis","Hemisensory loss","Astereognosis","No neurological manifestations"],"a":3,"e":"No neurological manifestations [Ref: Internet reference] Agenesis of corpus callosum is a rare birth defect (congenital disorder) in which there is complete or partial absence of corpus callosum. Corpus callosum is a band of tissue connecting the two hemispheres of the brain. Fibres of corpus callosum arise from the superficial layers of the cerebral cortex and they project to the homotypic regions of the contralateral cortex by passing through the corpus collosum while crossing the midline. Clinical features of Agenesis of corpus callosum Signs and symptoms of agenesis of corpus callosum vary greatly among individuals. Patients usually do not have any neurological manifestations. However, some features common in agenesis of corpus callosum are:​- Vision impairment * Low muscle tone (hypotonia) Poor motor coordination * Delay in motor milestones such as sitting and walking. Low perception of pain * Delayed toilet training * Chewing and swallowing difficulties * Early speech and language delays Social difficulties Other characteristics sometimes associated with callosal disorders are:​- Seizures * Spasticity * Early, feeding difficulties and or gastric reflux-. * Hearing impairments * Abnormal head and facial features * Mental retardation Investigation CT and MRI reveal \"Bat wing\" deformity of the ventricles. Treatment There are currently no specific medical treatments for callosal disorders. An important point The neurological abnormalities associated with corpus callosum are not caused by absence of corpus callosum per se. * These conditions are believed to be caused due to associated cerebral anomalies rather than in corpus callosum per sc. * The most common associated brain anomalies with absent corpus callosum are * Dandy walker malformation * lnterhenfispheric cyst with hydrocephalus * Migrational disorder * Absence of the inferior vertnis * The children who had the best prognosis without any significant neurological sequale were those with isolated agenesis of corpus collosum. * The children with the worst prognosis and neurological sequale were those with agenesis of corpus callosum and migrational disorder with or without Dandy — walker malformation. * Hence prognosis is determined primarily by the underlying or associated malformation.","pyqMatches":[{"year":"2015","no":1163,"q":"Absence of Corpus callosum leads to","o":["Hemiparesis","Hemisensory loss","Astereognosis","No neurological manifestations"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5047, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 19, '{"id":5047,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":19,"q":"Water hammer pulse seen in","o":[">Aortic stenosis",">Aortic regurgitation",">Aortic stenosis and Aortic regurgitation",">Mitral regurgitation"],"a":1,"e":"Aortic regurgitation [Ref. Harrison 17h/e p 1476 & 166/e p 1400 Kundu, bedside clinics in medicine] Water hammer pulse It is a large bounding pulse, associated with increased stroke volume of the left ventricle and decrease in the peripheral resistance, leading to a wide pulse pressure. The pulse strikes the palpating finger with a rapid, forcefid jerk and quickly disappears. It is best felt in the radial artery with the patients arm elevated. It is seen in Aortic regurgitation. Pathophysiology of water hammer pulse In Aortic regurgitation the stroke volume is high, so the systolic pressure is high and this is responsible for sharp rise in the pulse. The stroke volume is high because the left ventricle gets blood from two sources during the diastole i.e. blood leaking from the Aorta and the blood it receives from left atria. The collapse occurs because Diastolic leak of blood into the left ventricle from the Aorta Rapid run off to the periphery as a result of low systemic vascular resistance (the increased cardiac output stimulates the baroreceptors in the aortic arch and the result is reflex vasodilatation of the peripheral vessels into which the blood flows rapidly). Wiry are arms elevated in the examination ? When the arm is raised there is fall of blood column resulting in vasodilation and thus helps to reduce the diastolic pressure more, so the pulse pressure widens. It may be so that the artery palpated becomes more in the line of Aorta after elevation of the arm and thus allows the direct systolic ejection and diastolic backward flow.","pyqMatches":[{"year":"2016","no":1036,"q":"Water hammer pulse seen in","o":[">Aortic stenosis",">Aortic regurgitation",">Aortic stenosis and Aortic regurgitation",">Mitral regurgitation"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5048, 'Orthopedics', 'Miscellaneous', 'Moderate', 'Orthopedics', 20, '{"id":5048,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Orthopedics","sourceNo":20,"q":"Interstitial nephritis is seen with all except","o":["Beta lactam inhibitors","INH","Diuretics","Allopurinol"],"a":1,"e":"INH [Ref. Harrison 17th/e p 1806, 1807 & 16th/e p 1702, 1703] DRUGS CAUSING INTERSTITIAL NEPHRITIS Antibiotics DiureticsAnticonvulsantsMiscellaneous . filactamso • ThiazideQ • Phenytoinu . Captopril0 . SulfonamidesQ • FurosemideQ • PhenobarbitoneQ • H2 receptor blockerse • QuinolonesQ . Triamterene • Carbamazepine . Omeprazole . Vancomycin . NSAIDS° • Valproic acid . Mesalazine • Erythromycin . Indinavir . Minocycline . Allopurinol . Rifampicin • Ethambutol . Acyclovir","pyqMatches":[{"year":"2015","no":609,"q":"Interstitial nephritis is seen with all except","o":["Beta lactam inhibitors","INH","Diuretics","Allopurinol"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5049, 'Orthopedics', 'Upper Limb', 'Moderate', 'Orthopedics', 21, '{"id":5049,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Moderate","source":"Orthopedics","sourceNo":21,"q":"A person is not able to extend his metacarpophalangeal joint. Injury to which of the following nerve result in this?","o":["Ulnar nerve","Radial nerve injury","Median nerve injury","Post. Interosseous nerve injury"],"a":3,"e":"Damage to posterior interosseous nerve result in inability to extend the fingers at the metacarpophalangeal joints and radial deviation of the wrist on wrist extension caused by weakness of extensor carpi ulnaris muscle. Posterior interosseous nerve or deep ulnar nerve is a pure motor branch of radial nerve in the forearm. It supplies the extensor muscles of forearm including the extensor carpi ulnaris. Ulnar nerve palsy result in loss of fine intrinsic motions of hand. It result in an abduction deformity of the little finger from paralysis of the interossei, interosseous muscle wasting, and partial claw hand from interphalangeal flexion deformities of the ring and little fingers. Radial nerve injury result in wrist drop. Axillary or proximal injury result in triceps weakness in addition to wrist drop. Injury in the axilla causes damage to triceps brachii, anconeus, brachioradialis and extensor carpi radialis longus. Ref: Neurology in Clinical Practice: The neurological disorders, Volume 2 edited by Walter George Bradley page 2315. LeBlond R.F., DeGowin R.L., Brown D.D. (2009). Chapter 14. The Neurologic Examination. In R.F. LeBlond, R.L. DeGowin, D.D. Brown (Eds), DeGowin''s Diagnostic Examination, 9e.","pyqMatches":[{"year":"2013","no":1519,"q":"A person is not able to extend his metacarpophalangeal joint. Injury to which of the following nerve result in this?","o":["Ulnar nerve","Radial nerve injury","Median nerve injury","Post. Interosseous nerve injury"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5050, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 22, '{"id":5050,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":22,"q":"Tension band wiring is indicated in fracture of which of the following ?","o":["Fracture humerus","Olecranon","Fracture tibia","Fracture spine"],"a":1,"e":"Tension band wiring is indicated in the treatment of two types of olecranon fracture. First type is a clean break with separation of the fragments, and second type is comminuted fracture of the olecranon with displced fragments. A crack in the olecranon without displacement is treated by immobilising the elbow in an above elbow plaster slab in 30 degrees of flexion.","pyqMatches":[{"year":"2012","no":1274,"q":"Tension band wiring is indicated in fracture of which of the following ?","o":["Fracture humerus","Olecranon","Fracture tibia","Fracture spine"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5051, 'Orthopedics', 'Trauma & Fractures', 'Hard', 'Orthopedics', 23, '{"id":5051,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Hard","source":"Orthopedics","sourceNo":23,"q":"Which of the following attitude will be seen in a patient with posterior dislocation of hip?","o":["Flexion, Abduction, Internal rotation","Flexion, Adduction, Internal rotation","Flexion, Abduction, External rotation","Flexion, Adduction, External rotation"],"a":1,"e":"Dislocations are usually posterior, and occasionally anterior, or central through the acetabulum. Posterior dislocation: Hip is flexed, adducted, and internally rotated, and leg is shortened. Anterior dislocation: Hip is flexed, abducted, and externally rotated, and leg is shortened. Central dislocation: Trochanter is displaced medially. One may be able to feel the head of femur rectally. There is no shortening.","pyqMatches":[{"year":"2019","no":199,"q":"Which of the following attitude will be seen in a patient with posterior dislocation of hip?","o":["Flexion, Abduction, Internal rotation","Flexion, Adduction, Internal rotation","Flexion, Abduction, External rotation","Flexion, Adduction, External rotation"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5052, 'Orthopedics', 'Lower Limb', 'Moderate', 'Orthopedics', 25, '{"id":5052,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Moderate","source":"Orthopedics","sourceNo":25,"q":"Blount''s disease is associated with all of the following, EXCEPT:","o":["Genu varum","Genu Recurvatum","Internal Tibial Torsion","External Tibial Torsion"],"a":3,"e":"Blount’s disease is characterized by varus and internal tibial torsion and genu recurvatum, with varus of the proximal tibia being the primary deformity. It is not associated with external tibial torsion. Ref: Operative techniques in pediatric orthopedics, by John M.Flynn, Sam W.Wiesel, Page 205, 206.","pyqMatches":[{"year":"2015","no":1477,"q":"Blount''s disease is associated with all of the following, EXCEPT:","o":["Genu varum","Genu Recurvatum","Internal Tibial Torsion","External Tibial Torsion"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5053, 'Orthopedics', 'Bone Tumors', 'Easy', 'Orthopedics', 26, '{"id":5053,"subject":"Orthopedics","chapter":"Bone Tumors","difficulty":"Easy","source":"Orthopedics","sourceNo":26,"q":"Brown tumors are seen in:","o":["Hypeparathyroidism","Pigmented villonodular synovitis","Osteomalacia","Neurofibromatosis"],"a":0,"e":"Brown tumors are highly vascular lytic lesions of the skeleton seen in both primary and secondary hyperparathyroidism. They result from the accumulation of abundant fibrovascular tissue and osteoclast like giant cells. Ref: Robbin’s Basic Pathology, 7th Edition, Pages 1186, 1286; Orthopaedic Pathology By Vincent J. Vigorita, Bernard Ghelman, Douglas Mintz, 2007, Page 187.","pyqMatches":[{"year":"2013","no":1330,"q":"Brown tumors are seen in:","o":["Hypeparathyroidism","Pigmented villonodular synovitis","Osteomalacia","Neurofibromatosis"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5054, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 27, '{"id":5054,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":27,"q":"Lift off test is done to assess the function of:","o":["Supraspinatus","Infraspinatus","Teres Minor","Subscapularis"],"a":3,"e":"D i.e. Subscapularis - Failure to perform maximum internal rotation (as tested in belly press and lift off test) or inability to maintain position of maximal internal rotation (internal rotation lag sign) indicate tear of subscapularis tendon. Lift off test is done to assess the strength of subscapularis muscle and detect an isolated rupture of subscapularis tendon in a rotator cuff tear.","pyqMatches":[{"year":"2015","no":1453,"q":"Lift off test is done to assess the function of:","o":["Supraspinatus","Infraspinatus","Teres Minor","Subscapularis"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5055, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 28, '{"id":5055,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":28,"q":"The most common bone fractured during birth","o":["Clavicle","Scapula","Radius","Humerus"],"a":0,"e":"A i.e. Clavicle Clavicle is the most common bone to be fractured in children and during birth.","pyqMatches":[{"year":"2014","no":1718,"q":"The most common bone fractured during birth","o":["Clavicle","Scapula","Radius","Humerus"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5056, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 29, '{"id":5056,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":29,"q":"The malunion of supracondylar fracture of the humerus most commonly leads to:","o":["Flexion deformity","Cubitus varus","Cubitus valgus","Extension deformity"],"a":1,"e":"B i.e. Cabitus Varus Malunion : - It is the commonest complication of supracondylar fracture and results in cubitus varus (Gun stock deformity). Cubitus valgus is rare and may occur occasionally in posterolateral displacement.","pyqMatches":[{"year":"2012","no":1224,"q":"The malunion of supracondylar fracture of the humerus most commonly leads to:","o":["Flexion deformity","Cubitus varus","Cubitus valgus","Extension deformity"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5057, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 30, '{"id":5057,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":30,"q":"Treatment of choice in Acute myositis ossificans is:","o":["Immobilization of elbow","Short wave diathermy","Passive movements of arm","Active exercises"],"a":0,"e":"A i.e. Immobilization of elbow * Rest of the affected part during the period while the process is active is the basic principle of treatment(TN 91) . * No massage should be given. * If any physical therapy is going on, it should be discontinued immediately. * All passive movements and vigorous exercise must be stopped. Very gentle exercise must be started. * Indomethacin and radiotherapy prevent calcification. However, radiotherapy should be avoided in children. - Surgical excision is indicated if myositis ossificans interferes with function. It is worth noting that surgical excision is contraindicated during active phase when calcification matures. * Surgical excision, if required, should be done only after complete maturation of ossification.","pyqMatches":[{"year":"2016","no":1488,"q":"Treatment of choice in Acute myositis ossificans is:","o":["Immobilization of elbow","Short wave diathermy","Passive movements of arm","Active exercises"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5058, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 31, '{"id":5058,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":31,"q":"Pulled Elbow is:","o":["Disarticulation of elbow","Disarticulation of elbow","Subluxation of proximal radio ulnar joint","None of the above"],"a":2,"e":"C i.e. subluxation of proximal radio ulnar joint If a young child is lifted by the wrist, the head of the radius may be pulled partly out of the annular ligament, i.e., subluxation of the head of the radius. It occurs when forearm is pronated, elbow is extended and longitudinal traction is applied to the hand or wrist, e.g., lifting, spinning or swinging a child with wrist or hand. Pulled elbow most commonly occurs between the age of 2-5 years","pyqMatches":[{"year":"2012","no":1229,"q":"Pulled Elbow is:","o":["Disarticulation of elbow","Disarticulation of elbow","Subluxation of proximal radio ulnar joint","None of the above"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5059, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 32, '{"id":5059,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":32,"q":"In Monteggia fracture, which is true about ulnar fracture and head of radius","o":["Both ulnar fracture and head of radius is displaced posteriorly","Both ulnar fracture and head of radius is displaced anteriorly","Ulnar fractures is posteriorly and head of radius is displaced anteriorly","Ulnar fracture is anteriorly and head of radius is displaced posteriorly"],"a":1,"e":"Ans: B i.e. Both ulnar fracture and head of radius is displaced anteriorly * This is a fracture of the upper-third of the ulna with dislocation of the head of the radius. It is caused by a fall on an out​stretched hand. It may also result from a direct blow on the back of the upper forearm. - These fall into two main categories depending upon the angulation of the ulna fracture - extension and flexion type. The extension type, is the commoner of the two, where the ulna fracture angulates anteriorly (extends) and the radial head dislocates anteriorly. The flexion type is where the ulna fracture angulates posteriorly (flexes) and the radial head dislocates posteriorly.","pyqMatches":[{"year":"2016","no":1430,"q":"In Monteggia fracture, which is true about ulnar fracture and head of radius","o":["Both ulnar fracture and head of radius is displaced posteriorly","Both ulnar fracture and head of radius is displaced anteriorly","Ulnar fractures is posteriorly and head of radius is displaced anteriorly","Ulnar fracture is anteriorly and head of radius is displaced posteriorly"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5060, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 33, '{"id":5060,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":33,"q":"The most common complication of intracapsular fracture neck of femur is","o":["Mal union","Osteoarthritis","Non-Union","Shortening"],"a":2,"e":"C i.e. Nonunion Both intracapsular neck fracture and extracapsular fracture (basicervical and IT fracture) have same deformities, i.e. external rotation and shortening. These displacements are more marked in extracapsular fractures, because in an intracapsular fracture, the capsule of the hip joint is attached to the distal fragment and prevents extreme rotation and displacement of the distal fragment (and with it, the limb). In extracapsular fracture, distal fragment being outside the capsule is displaced more markedly.","pyqMatches":[{"year":"2016","no":1439,"q":"The most common complication of intracapsular fracture neck of femur is","o":["Mal union","Osteoarthritis","Non-Union","Shortening"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5061, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 34, '{"id":5061,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":34,"q":"AVN is seen in which type of # of femur:","o":["Intertrochantric #","Subcapital #","Trans cervical #","B AND C"],"a":3,"e":"B. i.e. Subcapital > C. i.e. Transcervical Fracture of the neck of femur Fracture of the Scaphoid ( Proximal pole> Waist) Fracture neck of talus Posterior dislocation of the hip","pyqMatches":[{"year":"2015","no":1466,"q":"AVN is seen in which type of # of femur:","o":["Intertrochantric #","Subcapital #","Trans cervical #","B AND C"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5062, 'Orthopedics', 'Trauma & Fractures', 'Moderate', 'Orthopedics', 35, '{"id":5062,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Moderate","source":"Orthopedics","sourceNo":35,"q":"Vascular sign of Narath is noticed in","o":["Fracture neck of femur","Perthes disease","Posterior dislocation of hip","All of the above"],"a":2,"e":"C i.e. Posterior dislocation of hip Vascular sign of narath is positive in posterior dislocation of hip joint. Due to posterior dislocation, the hip joint falls on the femoral artery, and this causes feeble or absent femoral pulse.","pyqMatches":[{"year":"2016","no":1434,"q":"Vascular sign of Narath is noticed in","o":["Fracture neck of femur","Perthes disease","Posterior dislocation of hip","All of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5063, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 36, '{"id":5063,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":36,"q":"Seat belt injury is","o":["Tear drop fracture","Wedge fracture","Chance fracture","Whiplash injury"],"a":2,"e":"C i.e. Chance fracture A horizontal fracture of the vertebra extending from body to the posterior element, caused by a strong distraction force","pyqMatches":[{"year":"2016","no":1437,"q":"Seat belt injury is","o":["Tear drop fracture","Wedge fracture","Chance fracture","Whiplash injury"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5064, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 37, '{"id":5064,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":37,"q":"Which part of the spine is most commonly affected in Rheumatoid arthritis:","o":["Cervical","Lumbar","Thoracic","Sacral"],"a":0,"e":"Answer is A (Cervical): Rheumatoid arthritis commonly involves the joints of hands, wrist, elbow, knees, ankle, and feet in a symmetrical manner. Axial skeleton involvement is usually limited to Upper Cervical Spine.","pyqMatches":[{"year":"2015","no":1485,"q":"Which part of the spine is most commonly affected in Rheumatoid arthritis:","o":["Cervical","Lumbar","Thoracic","Sacral"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5065, 'Orthopedics', 'Trauma & Fractures', 'Moderate', 'Orthopedics', 38, '{"id":5065,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Moderate","source":"Orthopedics","sourceNo":38,"q":"Complications of elbow dislocation are all EXCEPT: March 2004","o":["Vascular injury","Median nerve injury","Myositis ossificans","Radial nerve injury"],"a":3,"e":"Ans. d i.e. Radial nerve injury 1) Early complications Vascular injury :- Brachial artery may injured. It may result in compartment syndrome and Volkmann''s ischemic contracture. Nerve injury :- Median and ulnar nerve injury","pyqMatches":[{"year":"2013","no":1503,"q":"Complications of elbow dislocation are all EXCEPT: March 2004","o":["Vascular injury","Median nerve injury","Myositis ossificans","Radial nerve injury"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5066, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 39, '{"id":5066,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":39,"q":"True regarding Monteggia fracture is: March 2007, March 2013 (a, b, d, f)","o":["Upper ulnar fracture & dislocated radial head","Upper radial fracture & dislocated ulna","Lower radial fracture & dislocated ulna","Lower ulnar fracture & dislocated radius"],"a":0,"e":"Ans. A: Upper ulnar fracture & dislocated radial head Monteggia fracture-dislocations are classified by the Bado system Bado type I injuries are characterized by a proximal ulnar fracture with anterior dislocation of the radial head. This is due to a forceful pronation injury of the forearm and is the most common type. Bado type II injuries are \"reversed\" Monteggia fracture-dislocation injuries. Here, there is posterior angulation of the ulnar fracture site and posterior dislocation of the radial head. Bado type III and IV are rare injuries.","pyqMatches":[{"year":"2015","no":1458,"q":"True regarding Monteggia fracture is: March 2007, March 2013 (a, b, d, f)","o":["Upper ulnar fracture & dislocated radial head","Upper radial fracture & dislocated ulna","Lower radial fracture & dislocated ulna","Lower ulnar fracture & dislocated radius"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5067, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 40, '{"id":5067,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":40,"q":"March fracture is fracture of: September 2007","o":["Calcaneus","2nd metatarsal","Distal fibula","Proximal tibia"],"a":1,"e":"Ans. B: 2nd metatarsal A stress fracture of the 2nd or 3rd metatarsal bone is sometimes called a ''march fracture'' because soldiers running in boots often get it. The fracture heals spontaneously, so treatment is purely symptomatic.","pyqMatches":[{"year":"2014","no":1728,"q":"March fracture is fracture of: September 2007","o":["Calcaneus","2nd metatarsal","Distal fibula","Proximal tibia"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5068, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 41, '{"id":5068,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":41,"q":"Most common type of shoulder dislocation is: March 2011","o":["Posterior","Anterior","Inferior","Superior"],"a":1,"e":"Ans. B: Anterior Shoulder joint is the commonest joint in the body to dislocate Anterior shoulder dislocation is much more common than posterior dislocation Shoulder dislocation: MC joint to dislocate in body: Shoulder MC type of shoulder dislocation: Subcoracoid/ inferior Rarest type of shoulder dislocation: Posterior Posterior type of shoulder dislocation is associated with: Epileptic fits Bankart''s lesion is related with avulsion of glenoidal labrum Hill Sach''s lesion is found on humeral head Test for dislocation of shoulder joint: - Duga''s test, - Hamilton ruler test, - Callaways test Kocher''s manouevre is done to reduce a dislocated shoulder","pyqMatches":[{"year":"2012","no":1221,"q":"Most common type of shoulder dislocation is: March 2011","o":["Posterior","Anterior","Inferior","Superior"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5069, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 42, '{"id":5069,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":42,"q":"Felon/ Whitlow is: September 2012","o":["Midpalamr space infection","Terminal pulp space infection","Infection of the ulnar bursa","Infection of the radial bursa"],"a":1,"e":"Ans. B i.e. Terminal pulp space infection a painful abscess of the deep tissues of the palmar surface of the fingertip that is typically caused by bacterial infection (as with a staphylococcus) and is marked by swelling and pain","pyqMatches":[{"year":"2012","no":1273,"q":"Felon/ Whitlow is: September 2012","o":["Midpalamr space infection","Terminal pulp space infection","Infection of the ulnar bursa","Infection of the radial bursa"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5070, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 43, '{"id":5070,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":43,"q":"Swan neck deformity is seen in: March 2013 (a, c, e)","o":["Ankylosing spondylitis","Rheumatoid arthritis","Osteoarthritis","Reiter''s syndrome"],"a":1,"e":"Ans. B i.e. Rheumatoid arthritis Rheumatoid arthritis RA is a disease of: Synovium/ synovial membrane RA starts in: Synovium Body tissue mostly affected in RA: Synovium Characteristic feature: - Persistent inflammatory synovitis, - Peripheral joint, - Symmetrical distribution Causes: - Immunological, - Familial, – Infective (implicated) Mostly affects: Females (three times) Earliest lesion in rheumatoid synovitis: – Microvascular injury, – Increase in number of synovial lining cells Joints characteristically involved in RA: – MCP, – PIP (symmetric arthritis) Boutonniere deformity: – Flexion contracture of the PIP – Extension of DIP Criteria for diagnosis: Any 4 criteria must be present Pathognomic feature: Rheumatoid nodule Extra-articular manifestations are seen in: Individuals with high titres of RF (autoantibodies to the Fc component of IgG)","pyqMatches":[{"year":"2014","no":1752,"q":"Swan neck deformity is seen in: March 2013 (a, c, e)","o":["Ankylosing spondylitis","Rheumatoid arthritis","Osteoarthritis","Reiter''s syndrome"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5071, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 44, '{"id":5071,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":44,"q":"Perthe''s disease is Osteochondritis of the epiphysis of the: March 2013 (g)","o":["Capitulum","Lunate","Femoral head","Calacaneal tuberosity"],"a":2,"e":"Ans. C i.e. Femoral head Osteochondritis Perthes disease: - Osteochondritis of femoral head - Adduction is unaffected - IOC for Perthes disease: MRI Osteochondritis of lunate: Kienbock''s disease Osteochondritis of tibial tubercle: OschGood''s Schlatter''s disease Osteochondritis of calcaneum: Sever''s disease","pyqMatches":[{"year":"2012","no":1250,"q":"Perthe''s disease is Osteochondritis of the epiphysis of the: March 2013 (g)","o":["Capitulum","Lunate","Femoral head","Calacaneal tuberosity"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5072, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 45, '{"id":5072,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":45,"q":"Best diagnostic modality to diagnose avascular necrosis is: March 2007","o":["MRI scan","CT scan","X-ray","USG"],"a":0,"e":"Ans. A: MRI Scan Avascular necrosis/ osteonecrosis/ aseptic (bone) necrosis/ ischemic bone necrosis is a disease resulting from the temporary or permanent loss of the blood supply to the bones. Without blood, the bone tissue dies and causes the bone to collapse. There are many causes of avascular necrosis such as: Alcoholism Excessive steroid use Post trauma Caisson disease (decompression sickness) Vascular compression Vasculitis Thrombosis Damage from radiation Bisphosphonates (particularly the mandible) Sickle cell anaemia Gaucher''s Disease Idiopathic (no cause is found). Rheumatoid arthritis and lupus are also common causes of AVN. Avascular necrosis most commonly affects the head of femur. Other Avascular necrosis most commonly affects the head of femur. Other common sites include the talus, scaphoid and the jaw. Avascular necrosis usually affects people between 30 and 50 years of age. When it occurs in children at the femoral head, it is known as Legg- Calve-Perthes syndrome. It is most oftenly diagnose clinically. Because early X-rays are usually normal in the early stage of the disease, bone scintigraphy and MRI are the diagnostic modality of choice since both can detect minimal changes at early stages of the disease. Late radiographic signs include a radiolucency area following the collapse of subchondral bone (crescent sign) and ringed regions of radiodensity","pyqMatches":[{"year":"2012","no":1252,"q":"Best diagnostic modality to diagnose avascular necrosis is: March 2007","o":["MRI scan","CT scan","X-ray","USG"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5073, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 46, '{"id":5073,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":46,"q":"Cubital tunnel syndrome involves: March 2013 (c, f)","o":["Radial nerve","Ulnar nerve","Median nerve","Axillary nerve"],"a":1,"e":"Ans. B i.e. Ulnar nerve When the ulnar nerve compression occurs at the elbow, it is called \"cubital tunnel syndrome.\"","pyqMatches":[{"year":"2012","no":1244,"q":"Cubital tunnel syndrome involves: March 2013 (c, f)","o":["Radial nerve","Ulnar nerve","Median nerve","Axillary nerve"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5074, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 47, '{"id":5074,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":47,"q":"Foot drop occurs due to the involvement of: September 2006, March 2013 (b, f g, h)","o":["Sciatic nerve","Direct injury to the dorsiflexors","Common peroneal nerve palsy","All of the above"],"a":3,"e":"Ans. D: All of the above Foot drop may follow direct injury to the dorsiflexors. A few cases of rupture of the tibialis anterior tendon leading to foot drop and suspicion of peroneal nerve palsy have occurred. This subcutaneous tendon rupture usually occurs after a minor trauma with the foot in plantar flexion. Compartment syndromes also may lead to foot drop. March gangrene, a form of anterior compartment syndrome, is thought to be due to edema and small hemorrhages in the muscles of the anterior compartment occurring after strenuous activity in individuals not accustomed to it. Deep posterior compartment syndrome also may result in foot drop as a late sequela due to resultant contracture formation. Neurologic causes of foot drop include mononeuropathies of the deep peroneal, common peroneal, or sciatic nerves. Lumbosacral plexopathy, lumbar radiculopathy, motor neuron disease, or parasagittal cortical or subcortical cerebral lesions also can manifest as foot drop. These lesions can be differentiated through clinical and electrodiagnostic examinations. A common behavioral cause of foot drop is habitual crossing of the legs. These cases typically resolve with discontinuation of the habit. Foot drop also may be seen as a combination of neurologic, muscular, and anatomic dysfunction. Charcot foot is one example.","pyqMatches":[{"year":"2015","no":1463,"q":"Foot drop occurs due to the involvement of: September 2006, March 2013 (b, f g, h)","o":["Sciatic nerve","Direct injury to the dorsiflexors","Common peroneal nerve palsy","All of the above"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5075, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 48, '{"id":5075,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":48,"q":"Most common nerve injured in fracture of medial epicondyle of humerus is: March 2007","o":["Radial nerve","Ulnar nerve","Median nerve","Musculocutaneous nerve"],"a":1,"e":"Ans. B: Ulnar Nerve Certain lesions are commonly associated with fractures to specific areas of the humerus. At the upper end, the surgical neck of the humerus and anatomical neck of humerus can both be involved, though fractures of the surgical neck are more common. The axillary nerve can be damaged in fractures of this type. Mid-shaft fractures may damage the radial nerve, which traverses the lateral aspect of the humerus closely associated with the radial groove. The median nerve is vulnerable to damage in the supracondylar area. The ulnar nerve is vulnerable to damage near the medial epicondyle, around which it curves to enter the forearm.","pyqMatches":[{"year":"2013","no":1520,"q":"Most common nerve injured in fracture of medial epicondyle of humerus is: March 2007","o":["Radial nerve","Ulnar nerve","Median nerve","Musculocutaneous nerve"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5076, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 49, '{"id":5076,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":49,"q":"Waddling gait due to: March 2009","o":["Bilateral congenital dysplasia of hip","Coxa valga","CTEV","Bilateral coxa valgum"],"a":0,"e":"Ans. A: Bilateral congenital dysplasia of hip A waddling gait is the style of walking that is seen in a patient with proximal myopathy. It is characterised by: A broad-based gait with a duck-like waddle to the swing phase The pelvis drops to the side of the leg being raised Forward curvature of the lumbar spine Marked body swing This gait may be seen in patients with bilateral congenital hip dislocation and pregnancy.","pyqMatches":[{"year":"2015","no":1476,"q":"Waddling gait due to: March 2009","o":["Bilateral congenital dysplasia of hip","Coxa valga","CTEV","Bilateral coxa valgum"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5077, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 50, '{"id":5077,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":50,"q":"Knuckle bender splint is used for: September 2009","o":["Ulnar nerve palsy","Radial nerve palsy","Median nerve palsy","Axillary nerve palsy"],"a":0,"e":"Ans. A: Ulnar Nerve Palsy Cock-up splint • Radial nerve palsy Knuckle-bender splint • Ulnar nerve palsy","pyqMatches":[{"year":"2012","no":1276,"q":"Knuckle bender splint is used for: September 2009","o":["Ulnar nerve palsy","Radial nerve palsy","Median nerve palsy","Axillary nerve palsy"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5078, 'Orthopedics', 'Spine', 'Easy', 'Orthopedics', 51, '{"id":5078,"subject":"Orthopedics","chapter":"Spine","difficulty":"Easy","source":"Orthopedics","sourceNo":51,"q":"Maximum weight that can be given with skeletal traction is: September 2009","o":["5 kg","10 kg","15 kg","20 kg"],"a":3,"e":"Ans. D: 20 kg Traction is usually applied to the spine, pelvis, neck, arms, or legs. The force is generated by weight or force against the weight of the body. The two main types of traction are skin traction and skeletal traction. Of these two types, many specialized forms have been developed to treat conditions in specific parts of the body. With skin traction, weights are attached to the skin, which applies the pulling force to the bone. It is used when light (3 to 4 kg) or short-term traction is needed. With skeletal traction, pins are attached to the bone so that the pulling force is applied directly to the bone. Skeletal traction is used when skin traction is not possible and when greater weight (upto 20 kg) is needed.","pyqMatches":[{"year":"2013","no":1550,"q":"Maximum weight that can be given with skeletal traction is: September 2009","o":["5 kg","10 kg","15 kg","20 kg"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5079, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 52, '{"id":5079,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":52,"q":"Cock up splint is used in treatment of ?","o":["Radial nerve palsy","Ulnar nerve palsy","Median nerve palsy","Posterior interosseous nerve palsy"],"a":0,"e":"Ans. is ''a'' i.e., Radial nerve palsy Splints Any material which is used to support a fracture is called splint. Splints are used for immobilizing fractures; either temporarily during transportation or for definitive treatment. The most commonly employed splints is plaster of paris (POP) splint. Various POP splints are.","pyqMatches":[{"year":"2014","no":1712,"q":"Cock up splint is used in treatment of ?","o":["Radial nerve palsy","Ulnar nerve palsy","Median nerve palsy","Posterior interosseous nerve palsy"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5080, 'Orthopedics', 'Arthritis & Joint Disease', 'Hard', 'Orthopedics', 53, '{"id":5080,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Hard","source":"Orthopedics","sourceNo":53,"q":"Froment''s sign is positive in cases of weakness of ?","o":["Thumb adduction","Thumb abduction","Thumb flexion","Thumb extension"],"a":0,"e":"Ans. is ''a'' i.e., Thumb adduction Normally when a person is asked to grasp a book between the thumb and index finger, he will grasp the book firmly with thumb extended, taking full advantage of the adductor pollicis and the first dorsal interosseous muscles. If the ulnar nerve is injured the adductor pollicis will be paralysed and the patient will hold the book by using the flexor pollicislongus (supplied by median nerve) producing flexion at the interphalangeal joint. This becomes more pronounced if the examiner tries to pull the book out while the patient tries to hold it. This sign is known as `Froment''s sign'' or the ''book test''.","pyqMatches":[{"year":"2014","no":1742,"q":"Froment''s sign is positive in cases of weakness of ?","o":["Thumb adduction","Thumb abduction","Thumb flexion","Thumb extension"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5081, 'Orthopedics', 'Pediatric Orthopedics', 'Easy', 'Orthopedics', 54, '{"id":5081,"subject":"Orthopedics","chapter":"Pediatric Orthopedics","difficulty":"Easy","source":"Orthopedics","sourceNo":54,"q":"Most common cause of amputation in India is ?","o":["Diabetic gangrene","Gas gangrene","Road traffic accident","Tumors"],"a":2,"e":"Ans. is ''c'' i.e., Road traffic accident Amputation Amputation is a procedure where a part of the limb is removed through one or more bones. Disarticulation is a procedure where the limb is removed through a joint. Indications of amputation Indications of amputations may be absolute or relative :? A) Absolute indications Gas gangrene Diabetic gangrene Irreparable loss of blood supply due to trauma or disease Peripheral vascular disease (Burger''s gangrene) B) Relative indications Trauma Tumors Severe loss of function of limb Nerve injuries Congenital anomalies Overall most common cause of amputation is trauma (injury) to a limb. Most common cause of trauma is road traffic accident.","pyqMatches":[{"year":"2014","no":1710,"q":"Most common cause of amputation in India is ?","o":["Diabetic gangrene","Gas gangrene","Road traffic accident","Tumors"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5082, 'Orthopedics', 'Trauma & Fractures', 'Moderate', 'Orthopedics', 55, '{"id":5082,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Moderate","source":"Orthopedics","sourceNo":55,"q":"All are true about colles fracture except ?","o":["In old age","Dorsal shift","At cortico-cancellous junction","Garden spade deformity"],"a":3,"e":"Ans. is ''d'' i.e., Garden spade deformity COLLES FRACTURE Colle''s fracture is an extra-articular fracture at the distal end of radius, at its cortico-cancellous junction. It is the most common fracture in person over 40 years of age and especially in women after menopause (Postmenopausal females). The association of the fracture with osteoporosis is now well established and it is one of the fragility fracture, seen in osteoporosis. The fracture nearly always caused by fall on outstretched hand. Displacement in colle''s fracture The fracture line runs transversely at the cortico-cancellous junction. In the majority of the cases, one or more displacements of the distal fragment occur :- i. Dorsal displacement (Dorsal shift) i. Lateral tilt (lateral angulation) i. Dorsal tilt (Dorsal angulation) v. Supination (external rotation) v. Lateral displacement (lateral shift) i. Impaction (proximal migration) i. Clinical features of colles fracture Pain and swelling at the wrist. Typical deformity : There is a dorsal hollow or depression just proximal to the fracture and immediately distal to this there is a marked prominence caused by lower fragment being displaced backwards, carrying with it the whole of the carpus and hand. This gives appearance of a fork, So named dinner fork/ silver fork / spoon shaped deformity.","pyqMatches":[{"year":"2014","no":1719,"q":"All are true about colles fracture except ?","o":["In old age","Dorsal shift","At cortico-cancellous junction","Garden spade deformity"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5083, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 56, '{"id":5083,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":56,"q":"Most common type of supra condylar fracture in children ?","o":["Posteromedial extension","Posterolateral extension","Anteromedial flexion","Anterolateral flexion"],"a":0,"e":"Ans. is ''a'' i.e., Posteromedial extension Supracondylar fracture of humerus Supracondylar humeral fractures are the most common elbow fractures in children. Most common age group affected is 5-8 years. Boys are affected more than girls. Left side is more common than right. Mechanism of injury Mostly it occurs due to hyperextension injury. Fracture is caused by a fall onto the outstretched hand with hyperextension at elbow. Types of supracondylar fracture Supracondylar fracture is broadly classified into extension type and flexion type. 1) Extension type It is the most common type (97 - 99%). Distal fragment is extended (tilted backward/posteriorly) in relation to proximal fragment. Occurs due to hyperextension injury after fall on outstretched hands. Generally, displacement of distal fragment may be : - i) Posteromedial (70-80%) ii) Posterolateral (20-30%) 2) Flexion type It is less common type (1-3 %) Distal fragment is flexed (tilted forward/anteriorly) in relation to proximal fragments. The mechanism of injury generally is believed to be a fall directly onto the elbow rather than a fall on outstretched hand. As the extension type fracture is more common (97 - 99%), the most common elbow injury in children is extension type of supracondylar fracture. Clinical features of supracondylar fracture Following a fall, the child is in pain and elbow is swollen. In extension type of injury, `S'' shaped deformity of the elbow is obvious. There is loss of both active and passive movements of elbow. Symptoms relating to vascular and nerve injury may be seen. Unusual posterior prominence of the point of elbow (tip of olecrenon) because of backward tilt of the distal fragment. Three point bony relationship is maintained as the fracture is above the level of condyles. Dimple sign due to one of the spikes of proximal fragment penetrating the muscle and tethring the skin.","pyqMatches":[{"year":"2014","no":1720,"q":"Most common type of supra condylar fracture in children ?","o":["Posteromedial extension","Posterolateral extension","Anteromedial flexion","Anterolateral flexion"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5084, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 57, '{"id":5084,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":57,"q":"Most common joint involved in gout is ?","o":["Knee","Hip","MP joint of great toe","MP joint of thumb"],"a":2,"e":"Ans. is ''c'' i.e., MP joint of great toe Gout is the common end point of a group of disorders that produce hyperuricemia. It is marked by transient attacks of acute arthritis intitiated by crystallization of monosodium urate into the joints, leading eventually to chronic gouty arthritis and deposition of masses of urates in joints and other sites, creating tophi. Most common joint involved in gout is big toe, i.e. metatarsophalangeal joint of great toe. Tophi are pathognomic of gout. They are formed by large aggregations of urate crystals. The urate crystals are surrounded by -","pyqMatches":[{"year":"2014","no":1754,"q":"Most common joint involved in gout is ?","o":["Knee","Hip","MP joint of great toe","MP joint of thumb"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5085, 'Orthopedics', 'Lower Limb', 'Moderate', 'Orthopedics', 58, '{"id":5085,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Moderate","source":"Orthopedics","sourceNo":58,"q":"Which of the following structure are not normally visualized during the arthroscopy of the knee?","o":["Meniscus","Cruciate ligaments","Collateral ligaments","Patella articular surface"],"a":2,"e":"Ans. is ''c'' i.e., Collateral ligaments The following structures are visualized during the knee arthroscopy :- i) Medial and lateral meniscus ii) Anterior and posterior cruciate ligaments iii) Knee articular cartilage iv) Patello - femoral joint v) Loose bodies in joint","pyqMatches":[{"year":"2014","no":1711,"q":"Which of the following structure are not normally visualized during the arthroscopy of the knee?","o":["Meniscus","Cruciate ligaments","Collateral ligaments","Patella articular surface"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5086, 'Orthopedics', 'Arthritis & Joint Disease', 'Moderate', 'Orthopedics', 59, '{"id":5086,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Moderate","source":"Orthopedics","sourceNo":59,"q":"Not a complication of fracture neck of femur ?","o":["Non-union","Malunion","AVN","Osteoarthritis"],"a":1,"e":"Ans. is ''b'' i.e., Malunion Complications of femoral neck fracture Fractures of the neck of the femur are more prone to serious complications than in any other fracture. All the complications affect fractures with displacement rather than impacted abducted (valgus impacted) fractures. The important complications are : 1) Avascular necrosis of femoral head AVN is the most common complication of femoral neck fracture. It occurs in 15-35% of cases of displaced fractures and 2) Non-union Non-union is the second most common complication of femoral neck fracture. It occurs in 10-30% of cases of displaced fractures and 3) Secondary osteoarthritis It occurs a few years following fracture neck femur. Avascular necrosis or collapse of femoral head leads to secondary osteoarthritis of the hip joint.","pyqMatches":[{"year":"2014","no":1721,"q":"Not a complication of fracture neck of femur ?","o":["Non-union","Malunion","AVN","Osteoarthritis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5087, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 60, '{"id":5087,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":60,"q":"Most common site of metastasis in skeleton ?","o":["Femur","Tibia","Vertebrae","Skull"],"a":2,"e":"Ans. is ''c'' i.e., Vertebrae Metastasis Metastatic bone disease is the commonest malignancy of bones and is much more common than primary bone tumors. The commonest sites for bone metastases are vertebrae (most common), pelvis, the proximal half of the femur and the humerus. Extremities distal to elbow and knee are least commonly involved sites. Spread is usually via the blood stream; occasionally, visceral tumors spread directly into adjacent bones e.g., the pelvis and ribs. Certain tumors are known to be common sources of bone metastasis. The following primary tumors are the most common to metastasize in the bone; breast, prostate, lung, thyroid, kidney, and gastrointestinal tract. The commonest source of metastatic bone disease is carcinoma of the breast. In males most common source is prostate carcinoma. Bladder and uterine carcinomas are less common sources. In children, skeletal metastases originate from neuroblastoma, Ewing''s sarcoma, and osteosarcoma.","pyqMatches":[{"year":"2014","no":1759,"q":"Most common site of metastasis in skeleton ?","o":["Femur","Tibia","Vertebrae","Skull"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5088, 'Orthopedics', 'Lower Limb', 'Hard', 'Orthopedics', 61, '{"id":5088,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Hard","source":"Orthopedics","sourceNo":61,"q":"Perkin''s line on X-ray is used for diagnosis of -","o":["Perthe''s disease","CDH","CTEV","AVN Hip"],"a":1,"e":"Ans. is ''b'' i.e., CDH Radiological features of DDH/CDH In Von Rosen''s view following parameters should be noted Perkin''s line : Vertical line drawn at the outer border of acetabulum Hilgenreiner''s line : Horizontal line drawn at the level of tri-radiate cartilage Shenton''s line : Smooth curve formed by inferior border of neck of femur with superior margin of obturator foramen. Acetabular index : Normally is S 30° CE angle of Wiberg : Normal value is 15-30\" Normally the head lies in the lower and inner quadrant formed by two lines (Perkin''s & Hilgenreiner''s). In DDH the head lies in outer & upper quadrant Shenton \"s line is broken Delayed appearance & retarded development of ossification of head of femur Sloping acetabulum Superior & lateral displacement of femoral head Von-Rosen''s line This is a line, which helps in the diagnosis of DDH in infants less than 6 months. For this AP view of pelvis is taken with both lower limb in 450 abduction and full internal rotation. Upward prolongation of long axis of shaft of the femur points towards the lateral margin of the acetabulum and crosses the pelvis in the region of sacroiliac joint. In CDH, upward prolongation of this line points towards anterior superior iliac spine and crosses the midline in the lower lumber region → Positive Von-Rosen''s sign.","pyqMatches":[{"year":"2014","no":1767,"q":"Perkin''s line on X-ray is used for diagnosis of","o":["Perthe''s disease","CDH","CTEV","AVN Hip"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5089, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 62, '{"id":5089,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":62,"q":"Which joint is most commonly affected in pseudogout -","o":["Knee","Hip","MP joint great toe","MP joint thumb"],"a":0,"e":"Ans. is ''a'' i.e., Knee Pseudogout It is one of the forms of \"Calcium pyrophosphate dihydrate\" (CPPD) arthropathy. Pseudogout commonly involves the larger joints. Knee joint is most commonly involved; other sites are wrist, elbow, shoulder, ankle. Involvement of small joints is uncommon. Age group is > 60 yrs. In CPPD arthropathy, CPPD deposition occurs in articular tissues. It can present in any of the following three forms :? 1) Asympatomatic chondrocalcinosis 2) Acute synovitis - Pseudogout 3) Chronic pyrophosphate arthropathy The radiologic hallmark of CPPD is \"chondrocalcinosis. Chondrocalcinosis is seen as punctate and/or linear radiodense deposits in fibrocartilaginous joint menisci or articular hyaline cartilage. Definitive diagnosis is made by synovial fluid polarised light microscopy which shows weakly positive, birefringent, rhomboid crystals of CPPD. [In gout polarized light shows - strongly negative birefringent, needle shaped crystals of monosodium urate]","pyqMatches":[{"year":"2014","no":1755,"q":"Which joint is most commonly affected in pseudogout","o":["Knee","Hip","MP joint great toe","MP joint thumb"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5090, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 63, '{"id":5090,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":63,"q":"Loose body in joint most common site is -","o":["Knee","Hip","Elbow","Ankle"],"a":0,"e":"Ans. is ''a'' i.e., Knee Loose body in joint A loose body is a free-floating piece of bone, cartilage or foreign object in a joint. The knee is the most common joint where one would find a loose body. Causes of loose bodies include :- i) Osteoarthritis ii) Osteochondritisdessicans iii) Osteochondral fracture(injury) iv) Charcot''s disease v) Synovial chondromatosis","pyqMatches":[{"year":"2014","no":1757,"q":"Loose body in joint most common site is","o":["Knee","Hip","Elbow","Ankle"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5091, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 64, '{"id":5091,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":64,"q":"Investigation of choice for entrapment neuropathy is ?","o":["CT SCAN","Clinical examination","Ulrasonography","EMG NCV"],"a":3,"e":"Ans. is ''d'' i.e., EMG NCV The diagnosis of mononeuropathy in entrapment neuropathy is based on electrodiagnostic studies (EMG/ NCV) and Magnetic resonance imaging (MRI). Entrapment neuropathy is a medical condition caused by entrapment and compression of a peripheral nerve wherever it traverses fibro-osseous tunnels. Sites of entrapment neuropathy are : - i. Carpal tunnel :- Median nerve (carpal tunnel syndrome) i. Cubital tunnel :- Ulnar nerve (cubital tunnel syndrome) i. Guyan''s canal :- Ulnar nerve (Guyan''s canal syndrome) v. Tarsal tunnel :- Posterior tibial nerve (Tarsal tunnel syndrome) v. Inguinal ligament :- Lateral cutaneous nerve of thigh (meralgia paraesthetica). i. Suprascapular notch :- Suprascapular nerve i. Neck of fibula :- Common peroneal nerve i. Fascial tunnel of superficial peroneal nerve :- Superficial peroneal nerve x. Arcase of Frohse :- Posterior interosseous syndrome x. Thoracic outlet :- Lower trunk of brachial plexus i. Compression in the foot :- Digital nerve (Morten''s metatarsalgia)","pyqMatches":[{"year":"2014","no":1741,"q":"Investigation of choice for entrapment neuropathy is ?","o":["CT SCAN","Clinical examination","Ulrasonography","EMG NCV"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5092, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 65, '{"id":5092,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":65,"q":"Posterior gliding of tibia on femur is prevented by ?","o":["Anterior cruciate ligament","Posterior cruciate ligament","Medial collateral ligament","Lateral collateral ligament"],"a":1,"e":"Ans. is ''b'' i.e., Posterior cruciate ligament Posterior cruciate ligament PCL begins from posterior part of intercondylar area of tibia and runs upwards, forwards and medially to attach the anterior part of the lateral surface of medial condyle of femur. PCL is extrasynovial but intracapsular, i.e., lies between synovium and capsule of the knee joint. It provides antero-posterior stability and prevents posterior gliding of tibia on femur. It is taut in flexion. Blood supply of cruciate (anterior & posterior) ligaments is from : -","pyqMatches":[{"year":"2014","no":1736,"q":"Posterior gliding of tibia on femur is prevented by ?","o":["Anterior cruciate ligament","Posterior cruciate ligament","Medial collateral ligament","Lateral collateral ligament"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5093, 'Orthopedics', 'Upper Limb', 'Hard', 'Orthopedics', 66, '{"id":5093,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Hard","source":"Orthopedics","sourceNo":66,"q":"Cozen''s test is used for the diagnosis of ?","o":["Tennis elbow","Golfer''s elbow","Base baller''s pitcher elbow","Carpal tunnel syndrome"],"a":0,"e":"Ans. is ''a'' i.e., Tennis elbow Signs and Tests Adson''s test : for thoracic outlet syndrome Allen''s test : for testing patency of radial and ulnar arteries Alli''s test : for CDH Anvil test : for testing tenderness of the spine Ape thumb : for median nerve injury Apley''s grinding test :for meniscus injury Apprehension test : for recurrent dislocation of the shoulder Barlow''s test : for CDH Blue sclera : Osteogenesis imperfecta Bryant''s test : for anterior dislocation of the shoulder Callways'' test : for anterior dislocation of the shoulder Chovstek''s sign : for tetany Claw hand : for ulnar nerve injury Coin test : for dorso lumbar tuberculosis of spine Cozen''s test : for tennis elbow Drawer test : for ACL and PCL injutries Anterior : for ACL injury Posterior : for ACL injury Finkelstein''s test : for de Quervain''s tenovaginitis Foot drop : for common peroneal nerve injury Froment''s sign : for ulnar nerve injury Gaenslen''s test: for SI joint involvement Galleazzi sign : for CDH Gower''s sign : for musular dystrophy Hamilton ruler test : for anterior dislocation of the shoulder Kanavel''s sign : for infection in ulnar bursa Lasegue''s test: for disc prolapse Lachmann test : for ACL injury Ludloffs sign: for avulsion of lesser trochanter McMurray''s test : for meniscus injury Nagffziger test : for disc prolapse Ober''s test : for tight ilio- tibial band (e.g., in polio) O'' Donoghue triad: traid of MCL, ACL & medial meniscus injuries occurring together Ortolani''s test : for CDH Pivot shift test : for ACL injury Policeman tip : for Erb''s palsy Runner''s knee : Patellar tendinitis Sulcus sign: for inferior dislocation of the shoulder Thomas'' test : for hip flexion deformity Trendelenburg''s test: for unstable hip due to any reaseon (e.g., CDH) Tinel''s sign: for detecting improving nerve injury Volkmann''s sign : for ischaemic contracture of forearm muscles Wrist drop : for radial nerve injury","pyqMatches":[{"year":"2014","no":1770,"q":"Cozen''s test is used for the diagnosis of ?","o":["Tennis elbow","Golfer''s elbow","Base baller''s pitcher elbow","Carpal tunnel syndrome"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5094, 'Orthopedics', 'Spine', 'Easy', 'Orthopedics', 67, '{"id":5094,"subject":"Orthopedics","chapter":"Spine","difficulty":"Easy","source":"Orthopedics","sourceNo":67,"q":"Most common site for the osteoporotic vertebral fracture is ?","o":["Dorsolumbar spine","Cervical spine","Lumbosacral spine","Dorsal spine"],"a":0,"e":"Ans. is ''a'' i.e., Dorsolumbar spine Osteoporosis is an asymptomatic disorder unless complications (predominantly fractures) occur. Most common symptom of osteoporosis is back pain secondary to vertebral compression fracture. Dorso-lumbar spine is the most frequent site. Other common sites of fracture are lower end radius (Colle''s fracture) and fracture neck femur. Osteoporotic fracture (fragile fractures) are : (i) Fracture vertebrae (most common), (ii) Colle''s fracture, (iii) Fracture neck femur. Serum calcium, phosphate and alkaline phosphatase are normal in osteoporosis.","pyqMatches":[{"year":"2014","no":1731,"q":"Most common site for the osteoporotic vertebral fracture is ?","o":["Dorsolumbar spine","Cervical spine","Lumbosacral spine","Dorsal spine"],"a":0,"source":"NEET_2014_Paper.pdf"},{"year":"2016","no":1480,"q":"Most common site for the osteoporotic vertebral fracture is ?","o":["Dorsolumbar spine","Cervical spine","Lumbosacral spine","Dorsal spine"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2014","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5095, 'Orthopedics', 'Bone Tumors', 'Easy', 'Orthopedics', 68, '{"id":5095,"subject":"Orthopedics","chapter":"Bone Tumors","difficulty":"Easy","source":"Orthopedics","sourceNo":68,"q":"Sunray appearance on X - ray is seen in ?","o":["Osteosarcoma","Osteochondroma","Osteoclastoma","Chondroblastoma"],"a":0,"e":"Ans. is ''a'' i.e., Osteosarcoma Codman''s triangle and sunray appearance are typical of osteosarcoma. However, you should keep in your mind following very important facts : - Sunray (sunburst) appearance and codman''s triangle indicates periosteal reaction (periosteal new bone formation). Both these are typical of osteosarcoma but may also occur in other rapidly growing bone tumors (Ewing''s sarcoma), and infection (osteomyelitis). Similarly, onion peel appearance indicates periosteal new bone- formation and is typical for Ewing''s sarcoma. But this can also occur in oseosarcoma and osteomyelitis. The crux is that, aggresively growing tumors and infection stimulate the periosteum which then react by forming new bone, (therefore it is called periosteal reaction) which may take any of the above form.","pyqMatches":[{"year":"2014","no":1761,"q":"Sunray appearance on X - ray is seen in ?","o":["Osteosarcoma","Osteochondroma","Osteoclastoma","Chondroblastoma"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5096, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 69, '{"id":5096,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":69,"q":"Puttiplat operation is done for ?","o":["Elbow instability","Shoulder instability","Rotator cuff tear","Biceps Tendinitis"],"a":1,"e":"Ans. is ''b'' i.e., Shoulder instability Important surgeries for recurrent anterior dislocation of shoulder are: i) Barkart''s operation iii) Bristow''s operation v) Eden Hybinette operation ii) Putti-Platt''s operation iv) McLaughin''s operation vi) Magnum & Stack operation","pyqMatches":[{"year":"2014","no":1740,"q":"Puttiplat operation is done for ?","o":["Elbow instability","Shoulder instability","Rotator cuff tear","Biceps Tendinitis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5097, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 70, '{"id":5097,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":70,"q":"Lachmann''s test is used for ?","o":["ACL injury","PCL injury","MCL injury","LCL injury"],"a":0,"e":"Ans. is ''a'' i.e., ACL injury ACL injury ACL is the most commonly injured ligament of knee. Most common mechanism of injury is twisting (medial rotation) with valgus injury on semiflexed knee. Often with this mechanism MCL and medial meniscus are also injured. This triple injury of ACL , MCL and medial meniscus is called O''Donghue triad. Isolated ACL can also be injured by hyperextension injury. Tests for ACL injury Following tests are used for ACL injury : ? i. Lachman''s test i. Pivot shift test i. Flexion-rotation drawer test v. Anterior drawer test v. Jerk test i. Loose''s test Lachman''s test is the most sensitive test for anterior cruciate ligament tears. It is done with the knee flexed at 20 degrees. So it can be done in acute as well as chronic injuries. (because in acute cases with hemarthrosis more flexion is usually not possible so performing anterior drawer test is difficult).","pyqMatches":[{"year":"2014","no":1737,"q":"Lachmann''s test is used for ?","o":["ACL injury","PCL injury","MCL injury","LCL injury"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5098, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 71, '{"id":5098,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":71,"q":"Infection of ulnar bursa is diagnosed by -","o":["Kanavel''s sign","Chowstek''s sign","Gower''s sign","Ludloff''s sign"],"a":0,"e":"Ans. is ''a'' i.e., Kanavel''s sign Kanavel''s sign is for infection of ulnar bursa.","pyqMatches":[{"year":"2014","no":1771,"q":"Infection of ulnar bursa is diagnosed by","o":["Kanavel''s sign","Chowstek''s sign","Gower''s sign","Ludloff''s sign"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5099, 'Orthopedics', 'Pediatric Orthopedics', 'Easy', 'Orthopedics', 72, '{"id":5099,"subject":"Orthopedics","chapter":"Pediatric Orthopedics","difficulty":"Easy","source":"Orthopedics","sourceNo":72,"q":"Ring shaped epiphyses is seen in ?","o":["Osteogenesis imperfecta","Morquios syndrome","Zellweger syndrome","Multiple epiphyseal dysplasia"],"a":0,"e":"Ans. is ''a'' i.e., Osteogenesis imperfecta Ring shaped epiphysis i) Hypothyroidism (healing phase) iv) Osteoporosis ii) Osteogenesis imperfecta v) Rickets (healing phase) iii) Osteopetrosis vi) Scurvy","pyqMatches":[{"year":"2014","no":1776,"q":"Ring shaped epiphyses is seen in ?","o":["Osteogenesis imperfecta","Morquios syndrome","Zellweger syndrome","Multiple epiphyseal dysplasia"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5100, 'Orthopedics', 'Bone Tumors', 'Easy', 'Orthopedics', 73, '{"id":5100,"subject":"Orthopedics","chapter":"Bone Tumors","difficulty":"Easy","source":"Orthopedics","sourceNo":73,"q":"Development of Chondrosarcomas is related with?","o":["Maffucci syndrome","Felty syndrome","a and b both","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Maffucci syndrome Chondrosarcomasdeveloping in patients with ollier''s and maffucci syndrome is called secondary chondrosarcoma. Secondary chondrosarcoma It is the chondrosarcoma arising in benign precursor either osteochondroma and enchondroma. There are no reliable figures about the risk of developing secondary chondrosarcoma in benign precursors. The risk of chondrosarcoma in solitary osteochondroma is 2% and that for osteochondromatosis is 5 - 25%. Patients with ollier''s disease and maffucci syndrome have a 25 - 30% risk of developing chondrosarcoma.","pyqMatches":[{"year":"2014","no":1763,"q":"Development of Chondrosarcomas is related with?","o":["Maffucci syndrome","Felty syndrome","a and b both","None of the above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5101, 'Orthopedics', 'Arthritis & Joint Disease', 'Hard', 'Orthopedics', 74, '{"id":5101,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Hard","source":"Orthopedics","sourceNo":74,"q":"CASPAR criteria is used in diagnosis of ?","o":["Psoriatic arthritis","Rheumatoid arthritis","Ankyosing spondylitis","Reactive synnovitis"],"a":0,"e":"Ans. is ''a'' i.e., Psoriatic arthritis Classification criteria for psoriatic arthritis (CASPAR) is used for the diagnosis of psoriatic arthropathy. The CASPAR (classification Criteria for Psoriatic Arthritis) Criteria To meet the CASPAR criteria a patient must have inflammatory articular disease (joint, spine, or entheseal) with 3 points from any of the following five categories :","pyqMatches":[{"year":"2014","no":1753,"q":"CASPAR criteria is used in diagnosis of ?","o":["Psoriatic arthritis","Rheumatoid arthritis","Ankyosing spondylitis","Reactive synnovitis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5102, 'Orthopedics', 'Miscellaneous', 'Hard', 'Orthopedics', 75, '{"id":5102,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Hard","source":"Orthopedics","sourceNo":75,"q":"Drug of choice for the treatment of acute gout in patients in whom NSAIDs are contraindicated is?","o":["Colchicine","Allopurinol","Xyloric acid","Paracetamol"],"a":0,"e":"Ans. is ''a'' i.e., Colchicine Treatment of Gout 1) Acute gout NSAIDs are the drugs of choice Colchicine is the fastest acting drug. However it is reserved for the patients in which NSAIDs are contraindicated, because colchicine can cause gastrointestinal disturbances. If neither NSAIDs nor colchicin are tolerated, oral prednisolone is used. Allopurinol and uricosuric drugs (sulfinpyrazone, probenacid) are not effective in acute gout because they will not relieve symptoms as they don''t have anti-inflammatory property. 2) Chronic gout Allopurinal is the drug of choice. Other drugs are sulfinpyrazone and probenacid.","pyqMatches":[{"year":"2014","no":1276,"q":"Drug of choice for the treatment of acute gout in patients in whom NSAIDs are contraindicated is?","o":["Colchicine","Allopurinol","Xyloric acid","Paracetamol"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5103, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 76, '{"id":5103,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":76,"q":"Causes of painful arc syndrome is/ are ?","o":["Supraspinatus tendinitis","Subacromial bursitis","Fracture of greater tuberosity","All the above"],"a":3,"e":"Ans. is ''d'' i.e., All the above Painful Arc syndrome This is a clinical syndrome in which there is pain in the shoulder and upper arm during the mid range of glenohumeral abduction. Following are the common causes : i. Minor tears of the supraspinatus tendon i. Supraspinatus tendinitis i. Calcification of supraspinatus tendon v. Subacromial bursitis v. Fracture of the greater tuberosity In all these conditions, the space between the upper - end of the humerus and the acrominon gets compromised, so that during mid - abduction the tendon of the rotator - cuff gets nipped between the greater tuberosity and acrominon. X- ray of the shoulder may show calcific deposit, or a fracture of the greater tuberosity or acromion. o Treatment consists of ultrasonics to the tender point and anti- inflammatory drugs. Some cases need an injection of hydrocortisone in the subacromial space or excision of the anterior, often prominent part of the acromion.","pyqMatches":[{"year":"2014","no":1775,"q":"Causes of painful arc syndrome is/ are ?","o":["Supraspinatus tendinitis","Subacromial bursitis","Fracture of greater tuberosity","All the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5104, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 77, '{"id":5104,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":77,"q":"Fat embolism syndrome is most commonly seen after ?","o":["Femur fracture","Acetabular fracture","Pelvis fracture","Calcaneal fracture"],"a":0,"e":"Ans. is ''a'' i.e., Femur fracture Fat embolism means circulation of fat globule away from its site of origin. When fat embolism causes symptoms it is called fat embolism syndrome. Causes of fat embolism","pyqMatches":[{"year":"2014","no":1777,"q":"Fat embolism syndrome is most commonly seen after ?","o":["Femur fracture","Acetabular fracture","Pelvis fracture","Calcaneal fracture"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5105, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 78, '{"id":5105,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":78,"q":"What about durham pin is true ?","o":["It is used to give skeletal traction","It has threads in the center of pin","It is used to give skeletal traction through calcaneum","All the above"],"a":3,"e":"Ans. is ''d'' i.e., All the above Denham pin It is a type of pin used to give skeletal traction. Threaded portion of the pin engages the bony cortices and reduces the chances of pin sliding. This type of pin is used commonly to give skeletal traction through the cancellous bone i.e. calcaneum. It can also be used to give traction through osteoporotic bones.","pyqMatches":[{"year":"2014","no":1716,"q":"What about durham pin is true ?","o":["It is used to give skeletal traction","It has threads in the center of pin","It is used to give skeletal traction through calcaneum","All the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5106, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 79, '{"id":5106,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":79,"q":"Z score measures the bone mineral density compred to ?","o":["Age, Race and sex matched individuals","Race and sex matched individuals","Sex matched individuals","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Age, Race and sex matched individuals T Score and Z score are the measures of bone mineral density. Z score : Measures the bone mineral density in terms standard deviation from the mean bone mineral density of age, race and sex matched individuals. T score : Measures the bone mineral density in terms standard deviation from the mean bone mineral density of race and sex matched individuals of normal younger age group.","pyqMatches":[{"year":"2014","no":1779,"q":"Z score measures the bone mineral density compred to ?","o":["Age, Race and sex matched individuals","Race and sex matched individuals","Sex matched individuals","None of the above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5107, 'Orthopedics', 'Spine', 'Easy', 'Orthopedics', 80, '{"id":5107,"subject":"Orthopedics","chapter":"Spine","difficulty":"Easy","source":"Orthopedics","sourceNo":80,"q":"Osteoid osteoma consists of -","o":["Osteoblasts","Osteoclasts","Both of above","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., Both of above Osteoid Osteoma Osteoid osteoma is the most common true benign tumor of the bone. This is a benign circumscribed lesion that may arise in the cortex of long bones or occasionally in the cancellous bone of spine. The characteristic feature is the formation of a small nidus of osteoid tissue, surrounded by a reactive zone of dense sclerosis (Sclerotic new bone formation). Microscopically, the tumor is composed of thin, irregular, trabeculae within a cellular granulation tissue containing osteoblasts and osteoclasts.Trabeculae are more mature in the center, which is often partially calcified. Reactive, sclerotic bone surrounds the nidus. Clinical features of osteoid osteoma The tumor occurs between 10-30 years of age and is more common in males. The diaphysis of long bones is involved, most common bone involved is the tibia followed by femur. Posterior elements of the vertebrae may also be involved. The presenting complaint is a nagging pain, worst at night, and is relieved by salicylates or other NSAIDs, a diagnostic feature. On X-ray, there is a small radiolucent area (nidus) surrounded by dens sclerosis. X-ray, in some cases, show local sclerotic thickening of the shaft that may obscure the small central nidus within the area of rarefaction. Bone scan shows increased uptake in the nidus. The only treatment is wide en block excision along with internal fixation with or without bone grafting.","pyqMatches":[{"year":"2014","no":1764,"q":"Osteoid osteoma consists of","o":["Osteoblasts","Osteoclasts","Both of above","None of the above"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5108, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 81, '{"id":5108,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":81,"q":"Most common cause of acute compartment syndrome in children is ?","o":["Fracture supracondylar humerus","Transphysealhumerus fracture","Fracture radius /ulna","Fracture shaft humerus"],"a":0,"e":"Ans. is ''a'' i.e., Fracture supracondylar humerus Compartment syndrome is most commonly caused by extremity fractures :- i. Supracondylar fracture of humerus is the most common cause is children. i. Crush injuries to forearm are the most common cause in adults. i. Other injuries are fracture both bones forearm, elbow dislocation.","pyqMatches":[{"year":"2014","no":1778,"q":"Most common cause of acute compartment syndrome in children is ?","o":["Fracture supracondylar humerus","Transphysealhumerus fracture","Fracture radius /ulna","Fracture shaft humerus"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5109, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 82, '{"id":5109,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":82,"q":"Thomas splint is used for immobilizing fractures of ?","o":["Femur","Tibia","Radius","Ulna"],"a":0,"e":"Ans. is ''a'' i.e., Femur Splints Any material which is used to support a fracture is called splint. Splints are used for immobilizing fractures; either temporarily during transportation or for definitive treatment. The most commonly employed splints is plaster of paris (POP) splint. Various POP splints are:- 1) Casts : - Here the POP roll completely encircles the limb. 2) Slab : - It is not completely encircles the limb, but only one half or one third circumference. 3) Spica : - This encircles a part of the body; e.g., hip spica for fractures around hip.","pyqMatches":[{"year":"2014","no":1713,"q":"Thomas splint is used for immobilizing fractures of ?","o":["Femur","Tibia","Radius","Ulna"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5110, 'Orthopedics', 'Lower Limb', 'Moderate', 'Orthopedics', 83, '{"id":5110,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Moderate","source":"Orthopedics","sourceNo":83,"q":"Which of the following is not the extra - articular manifestations of ankylosing spondylitis?","o":["Acute anterior uveitis","Aortic valve disease","Pulmonary fibrosis","Dilated cardiomyopathy"],"a":3,"e":"Ans. is ''d'' i.e., Dilated cardiomyopathy Extra articular manifestations of ankylosing spondylitis are acute anterior uveitis (in 5%); rarely aortic valve disease, carditis and pulmonary fibrosis also occur. Ankylosing spondylitis (marie-strumpell disease) Ankylosing spondylitis is a chronic progressive inflammatory disease of the sacroiliac joints and the axial skeleton. Prototype of seronegative (absence of rheumatoid factor) spondyloarthropathies. Inflammatory disorder of unknown cause. Usually begins in the second or third decade with a median age of 23, in 5% symptoms begin after 40. Male to female ratio is 2-3 : 1 Strong correlation with HLA-B27 90-95% of cases are positive for HLA - B27. Joints involved in ankylosing spondylitis Ankylosing spondylitis primarily affects axial skeleton. The disease usually begins in the sacro-iliac joints and usually extends upwards to involve the lumbar, thoracic, and often cervical spine. In the worst cases the hips or shoulders are also affected. Hip joint is the most commonly affected peripheral joint. Rarely knee (Ebenzar 4th/e 593) and ankle (Apley''s 9th/e 67) are also involved. Pathology Enthesitis i.e. inflammation of the insertion points of tendons, ligaments or joint capsule on bone is one of the hallmarks of this entity of disease. Primarily affects axial (spinal) skeleton and sacroiliitis is often the earliest manifestation of A.S.. Involvement of costovertebral joints frequently occur, leading to diminished chest expansion (normal 5 cm) o Peripheral joints e.g. shoulders, and hips are also involved in 1/3rd patients. Extraarticular manifestations like acute anterior uveitis (in 5%); rarely aortic valve disease, carditis and pulmonary fibrosis also occur. Pathological changes proceed in three stages?","pyqMatches":[{"year":"2014","no":1749,"q":"Which of the following is not the extra - articular manifestations of ankylosing spondylitis?","o":["Acute anterior uveitis","Aortic valve disease","Pulmonary fibrosis","Dilated cardiomyopathy"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5111, 'Orthopedics', 'Upper Limb', 'Hard', 'Orthopedics', 84, '{"id":5111,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Hard","source":"Orthopedics","sourceNo":84,"q":"Which of the following deformity is evident in case of erbs palsy?","o":["Policeman tip deformity","Winging of scapula","Claw hand","Wrist drop"],"a":0,"e":"Ans. is ''a'' i.e., Policeman tip deformity Deformity (position of the limb) in Erb''s palsy i) Arm : Hanges by the side; it is adducted and medially rotated ii) Forearm : Extended and pronated n The deformity is known as ''policeman''s tip hand'' or ''porter''s tip hand''.","pyqMatches":[{"year":"2014","no":1744,"q":"Which of the following deformity is evident in case of erbs palsy?","o":["Policeman tip deformity","Winging of scapula","Claw hand","Wrist drop"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5112, 'Orthopedics', 'Trauma & Fractures', 'Moderate', 'Orthopedics', 85, '{"id":5112,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Moderate","source":"Orthopedics","sourceNo":85,"q":"Functional cast bracing not used in fracture of ?","o":["Humerus","Tibia","Ulna","Thoracolumbar spine"],"a":3,"e":"Ans. is ''d'' i.e., Thoracolumbar spine Functional cast bracing is used for the fracture of :- i. Humerus i. Femur i. Ulna v. Tibia","pyqMatches":[{"year":"2014","no":1714,"q":"Functional cast bracing not used in fracture of ?","o":["Humerus","Tibia","Ulna","Thoracolumbar spine"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5113, 'Orthopedics', 'Upper Limb', 'Moderate', 'Orthopedics', 86, '{"id":5113,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Moderate","source":"Orthopedics","sourceNo":86,"q":"What is not true about pulled elbow?","o":["Occurs due to sudden axial pull on extended elbow","Forearm is held in pronation and extention","Most commonly occurs between 2-5 years of age","Treatment is quick pronation and flexion of elbow"],"a":3,"e":"Ans. is ''d'' i.e., Treatment is quick pronation and flexion of elbow Pulled elbow If a young child is lifted by the wrist, the head of the radius may be pulled partly out of the annular ligament, i.e., subluxation of the head of the radius. It occurs when forearm is pronated, elbow is extended and longitudinal traction is applied to the hand or wrist, e.g., lifting, spinning or swinging a child with wrist or hand. Pulled elbow most commonly occurs between the age of 2-5 years. Clinical features of pulled elbow History of sudden axial pull on extended elbow. Immediately child starts crying and is unable to move the affected elbow. The forearm is held in pronation and extension and any attempt to supinate is resisted. Child does not allow to touch the affected limb. X-ray seems to be normal. Treatment of pulled elbow Treatment is simple. The child''s attention is diverted, the elbow is quickly supinated and then slightly flexed. This reduces the subluxation or dislocation and the radial head is relocated with a snap.","pyqMatches":[{"year":"2014","no":1729,"q":"What is not true about pulled elbow?","o":["Occurs due to sudden axial pull on extended elbow","Forearm is held in pronation and extention","Most commonly occurs between 2-5 years of age","Treatment is quick pronation and flexion of elbow"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5114, 'Orthopedics', 'Arthritis & Joint Disease', 'Moderate', 'Orthopedics', 87, '{"id":5114,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Moderate","source":"Orthopedics","sourceNo":87,"q":"Heberden node denotes involvement of ?","o":["Distal inetrphalangeal joint","Proximal interphalangel joint","Metacarpophalangeal joint","Metatarsophalangeal joint"],"a":0,"e":"Ans. is ''a'' i.e., Distal inetrphalangeal joint In osteoarthritis of hand : i) Distal interphalangeal joint :- Heberden''s node ii) Proximal interphalangeal joint :- Bouchard''s node","pyqMatches":[{"year":"2014","no":1748,"q":"Heberden node denotes involvement of ?","o":["Distal inetrphalangeal joint","Proximal interphalangel joint","Metacarpophalangeal joint","Metatarsophalangeal joint"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5115, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 88, '{"id":5115,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":88,"q":"De - quervian''s tenovaginitis involves ?","o":["Abductor pollicislongus","Extensor pollicisbrevis","Both of the above","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., Both of the above De-Quervian''s tenovaginitis is characterized by pain over the styloid process of the radius and palpable thickening in the course of the abductor pollicis longus and extensor pollicis brevis tendons. The fibrous sheaths of the abductor pollicis longus and extensor pollicis brevis tendons are thickened where they cross the tip of the radial syloid process. The tendons themselves appear normal as does the synovial lining of sheath. Exact cause is unknow. Excessive friction from overuse may be a factor, because the condition seems prone to follow repetitive actions such as wringing clothes, or in more recent times excessive typing or manipulations. The condition is five times commoner in women than men, predominantly in middle age. The main symptom is pain on using the hand, especially when movement tenses the abductor pollicis longus and extensors pollicis brevis tendons (as in lifting a saucepan or a teapot). On examination, there is local tenderness at the point where the tendons cross the radial styloid process. The thickened fibrous sheath are usually palpable as firm nodule. Passive adduction of the wrist or thumb causes the patient to wince with pain. Finkelstein''s test is used to diagnose De-Quervain''s tenovaginitis. To perform the test, the patients ask to flex their thumb and clench their fist over the thumb followed by ulnar deviation. This produces sharp pain along the distal radius.","pyqMatches":[{"year":"2014","no":1772,"q":"De - quervian''s tenovaginitis involves ?","o":["Abductor pollicislongus","Extensor pollicisbrevis","Both of the above","None of the above"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5116, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 89, '{"id":5116,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":89,"q":"The typical deformity in CTEV is ?","o":["Ankle equinus","Subtalar inversion","Forefoot adduction","All the above"],"a":3,"e":"Ans. is ''d'' i.e., All the above CTEV is the commonest and most important congenital deformity of the foot. CTEV is more common males in than in females (males to female ratio 2.5 : 1). In half of the cases CTEV is bilateral. Right and left foot are affected equally. The deformity consists of following elements :? i) Equinus, i.e. Plantar flexion at ankle joint (tibiotalar joint). ii) Inversion of foot at subtalar joint (talocalcaneal joint). iii) Forefoot adduction, at mid-tarsal joints, especially at talo- navicular joint. iv) Sometimes forefoot cavus, i.e. excessive arching of the foot at mid-tarsal joints.","pyqMatches":[{"year":"2014","no":1769,"q":"The typical deformity in CTEV is ?","o":["Ankle equinus","Subtalar inversion","Forefoot adduction","All the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5117, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 90, '{"id":5117,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":90,"q":"Ortolani test is positive when the examiner hears the ?","o":["Clunk of entry on abduction and flexion of hip","Clunk of entry on extension and adduction of hip","Click of exit on abduction and flexion of hip","Click of exit on extension and adduction of hip"],"a":0,"e":"Ans. is ''a'' i.e., Clunk of entry on abduction and flexion of hip Clinical tests for CDH/DDH In infancy two tests are used. Barlow''s test This test is done within 2-3 days of birth. The test has two parts :?","pyqMatches":[{"year":"2014","no":1768,"q":"Ortolani test is positive when the examiner hears the ?","o":["Clunk of entry on abduction and flexion of hip","Clunk of entry on extension and adduction of hip","Click of exit on abduction and flexion of hip","Click of exit on extension and adduction of hip"],"a":0,"source":"NEET_2014_Paper.pdf"},{"year":"2016","no":1455,"q":"Ortolani test is positive when the examiner hears the ?","o":["Clunk of entry on abduction and flexion of hip","Clunk of entry on extension and adduction of hip","Click of exit on abduction and flexion of hip","Click of exit on extension and adduction of hip"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2014","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5118, 'Orthopedics', 'Spine', 'Easy', 'Orthopedics', 91, '{"id":5118,"subject":"Orthopedics","chapter":"Spine","difficulty":"Easy","source":"Orthopedics","sourceNo":91,"q":"When do you operate for prolapsed disc ?","o":["Busy executive needs quick surgery","Only with weakness no pain","Severe pain interfering with activity and not relieved by rest and treatment of 8 weeks","Patient of PID with difficulty in ambulation"],"a":2,"e":"Ans. is ''c'' i.e., Severe pain interfering with activity and not relieved by rest and treatment of 8 weeks Indications for surgery in cases of Prolapsed intervertebral disc are :- i) Failure of conservative treatment (even after 8 weeks of treatment). ii) Progressive neurological deficit. iii) Cauda - equina syndrome. iv) Severe sciatic tilt.","pyqMatches":[{"year":"2014","no":1732,"q":"When do you operate for prolapsed disc ?","o":["Busy executive needs quick surgery","Only with weakness no pain","Severe pain interfering with activity and not relieved by rest and treatment of 8 weeks","Patient of PID with difficulty in ambulation"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5119, 'Orthopedics', 'Spine', 'Easy', 'Orthopedics', 92, '{"id":5119,"subject":"Orthopedics","chapter":"Spine","difficulty":"Easy","source":"Orthopedics","sourceNo":92,"q":"Vertebral rotation in scoliosis is checked in","o":["Forward bending","Backward bending","Sideways","Without bending"],"a":0,"e":"Ans. is ''a'' i.e., Forward bending The forward bending test is very sensitive in demonstrating the vertebral rotation that takes place in a structural scoliotic curve. Quantification of the rotation is done by measuring the rib hump by use of inclinometer or scoliometer. Severity of the curve in scoliosis is measured by cobb''s angle, i.e. an angle between line passing through the margins of vertebra at ends of curve. To use the cobb method, one must first decide which vertebrae are the end-vertebrae of the curve. These end vertebrae are the vertebrae at the upper and lower limits of curve which tilt most severely toward the conavity of the curve. Other method used to measure scoliosis angle is Ferguson''s method.","pyqMatches":[{"year":"2014","no":1733,"q":"Vertebral rotation in scoliosis is checked in","o":["Forward bending","Backward bending","Sideways","Without bending"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5120, 'Orthopedics', 'Trauma & Fractures', 'Hard', 'Orthopedics', 93, '{"id":5120,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Hard","source":"Orthopedics","sourceNo":93,"q":"Patient comes with crush injury to upper limb, doctor is concerned about gangrene and sepsis what can help decide between amputation and limb salvage?","o":["MESS","Guliton score","Gustilo Anderson classification","ASIA guidelines"],"a":0,"e":"Ans. is ''a'' i.e., MESS MESS (Mangled Extremity Severity Score) : Estimates viability of an extremity after trauma, to determine need for salvage vs empiric amputation. Following parameters are looked for :- i) Limb ischemia ii) Patient age range iii) Shock iv) Injury mechanism","pyqMatches":[{"year":"2014","no":1717,"q":"Patient comes with crush injury to upper limb, doctor is concerned about gangrene and sepsis what can help decide between amputation and limb salvage?","o":["MESS","Guliton score","Gustilo Anderson classification","ASIA guidelines"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5121, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 94, '{"id":5121,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":94,"q":"Inability to pronate forearm is due to injury to which nerve ?","o":["Ulnar","Radial","Median nerve","Musculocutaneous"],"a":2,"e":"Ans. is ''c'' i.e., Median nerve Pronation of the forearm is by two muscles pronator teres and pronator quadratus. These two muscles are supplied by median nerve. Thus injury to median nerve produces inability to pronate forearm. The median nerve is also called labourer''s nerve. The median nerve arises by two roots, one from the lateral cord (C5,6,7) and the other from the medial cord (C8, T1). The various muscles supplied by median nerve are : ? 1) In the forearm All the flexor muscles of the forearm, except the flexor carpi ulnaris and the medial half of flexor digitorum profundus to the ulnar two fingers. These muscles are : - i. Pronater teres i. Flexor digitorum superficialis i. Flexor pollicis longus v. Flexor carpi radialis v. Flexor digitorum profundus (lateral half) i. Pronator quadratus i. Pulmaris longus 2) In hand Median nerve supplies : - i. Thenar muscles (except adductor pollicis) - Flexor pollicis brevis, opponens pollicis and abductor pollicis brevis. Adductor pollicis is supplied by ulnar nerve. i. First two lumbricals","pyqMatches":[{"year":"2014","no":1743,"q":"Inability to pronate forearm is due to injury to which nerve ?","o":["Ulnar","Radial","Median nerve","Musculocutaneous"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5122, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 95, '{"id":5122,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":95,"q":"High stepping gait is seen in ?","o":["CTEV","Common peroneal nerve palsy","Polio","Cerebral palsy"],"a":1,"e":"Ans. is ''b'' i.e., Common peroneal nerve palsy First to touch the ground is the forefoot, and not the heel.","pyqMatches":[{"year":"2014","no":1745,"q":"High stepping gait is seen in ?","o":["CTEV","Common peroneal nerve palsy","Polio","Cerebral palsy"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5123, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 96, '{"id":5123,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":96,"q":"Sectoral sign is positive in ?","o":["Avascular necrosis of femur head","Osteoarthritis of hip","Protrusio acetabuli","Slipped capital femoral epiphyses"],"a":0,"e":"Ans. is ''a'' i.e., Avascular necrosis of femur head Clinical features of AVN In the earlier stages of AVN, the patient is asymptomatic, and by the time patient presents, the lesion is well advanced. Common histories patient gives (Any of the following) : - i) Dislocation of Hip ii) Alcoholism iii) Steroid intake for any disorder iv) Nephrotic syndrome Pain is a common complaint. Pain is felt in the grain and may radiate to knee. Decreased range of motion especially internal rotation followed by abduction. Sectoral sign or Differential rotation : - Internal rotation is possible in extended position of hip, but as seen as the hip is flexed to 90° no internal rotation is possible. This is the characteristic sign of AVN. o Limp with antalgic gait. Trendelenberg''s test positive.","pyqMatches":[{"year":"2014","no":1780,"q":"Sectoral sign is positive in ?","o":["Avascular necrosis of femur head","Osteoarthritis of hip","Protrusio acetabuli","Slipped capital femoral epiphyses"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5124, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 97, '{"id":5124,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":97,"q":"Garden''s classification used for which fracture?","o":["Surgical neck humerus","Shaft humerus","Neck of femur","Shaft femur"],"a":2,"e":"Ans. is ''c'' i.e., Neck of femur Garden''s classification Garden''s classification is the most useful and most accepted classification of the neck of femur. This is based on the degree of displacement of the fracture. Following 4 stages of fracture are there :? 1) Stage 1 : The fracture is incomplete, with head tilted in postero- lateral direction, i.e. into valgus, therefore is known as valgus (abduction) impacted fracture. 2) Stage 2 : Complete fracture but undisplaced. 3) Stage 3 : Complete fracture with partial displacement. 4) Stage 4 : Complete fracture with total displacement. The degree of displacement, in Garden''s classification, is judged from change in the direction of medial trabecular stream of the neck, in relation to the bony trabeculae in the weight bearing part of the head and in the corre​sponding part of the acetabulum. i) Stage 1 :- There is an obtuse angle laterally at the trabecular stream. ii) Stage 2 :- Trebeculae between head and neck are broken but they are in alignment with each other and with trabeculae in the acetabulum. iii) Stage 3 :- All three trabeulae are out of alignment. iv) Stage 4 :- Acetabular and head trabeculae are in alignment but head and neck trabeculae are not aligned.","pyqMatches":[{"year":"2014","no":1722,"q":"Garden''s classification used for which fracture?","o":["Surgical neck humerus","Shaft humerus","Neck of femur","Shaft femur"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5125, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 98, '{"id":5125,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":98,"q":"One of the common fractures that occur during boxing by hitting with a closed fist is ?","o":["Monteggia fracture dislocation","Galeazzi fracture dislocation","Bennett''s fracture dislocation","Smith''s fracture"],"a":2,"e":"Ans. is ''c'' i.e., Bennett''s fracture dislocation The common mechanism of injury for Benett''s fracture is an axial blow directed against the partially flexed metacarpal, in most cases during ''fist fights''. Benett''s fracture Benett''s fracture is an intra-articular fracture dislocation of the palmar base of first metacarpal bone of the thumb with either subluxation or dislocation of first carpometacarpal joint, i.e. trapezometacarpal joint. The common mechanism of injury is an axial blow directed against the partially flexed metacarpal, in most cases during \"Fist fights \". Patient complains of pain, swelling and tenderness over the base of the thumb. Movements of thumb are restricted. Displacing force in Bennett''s fractures Following are the deforming forces in Bennett''s fracture :- i) At the distal fragment, it is the adductor pollicis. ii) At the proximal fragment, it is the abductor pollicis longus. Base of the thumb metacarpal is pulled dorsally and medially by the abductor pollicis longus, while the distal attachment of adductor pollicis further levers the base into abduction.","pyqMatches":[{"year":"2012","no":1230,"q":"One of the common fractures that occur during boxing by hitting with a closed fist is ?","o":["Monteggia fracture dislocation","Galeazzi fracture dislocation","Bennett''s fracture dislocation","Smith''s fracture"],"a":2,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":1725,"q":"One of the common fractures that occur during boxing by hitting with a closed fist is ?","o":["Monteggia fracture dislocation","Galeazzi fracture dislocation","Bennett''s fracture dislocation","Smith''s fracture"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5126, 'Orthopedics', 'Trauma & Fractures', 'Moderate', 'Orthopedics', 99, '{"id":5126,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Moderate","source":"Orthopedics","sourceNo":99,"q":"Causes of Carpal tunnel syndrome are all except?","o":["DM","RA","Leprosy","Gout"],"a":2,"e":"Ans. is ''c'' i.e., Leprosy Carpal tunnel syndrome Carpal tunnel syndrome is the most common and widely known entrapment neuropathy in which the body''s peripheral nerve is compressed or traumatized. Carpal tunnel syndrome occurs when the median nerve is compressed in the carpal tunnel below flexor retinaculum. The carpal tunnel is a narrow rigid passage way of ligament and bones at the base of hand, in front of distal part of wrist. Carpal tunnel houses the median nerve and 9 tendons (4 FDS, 4 FDP & FPL). Causes of carpal tunnel syndrome There are many causes of carpal tunnel syndrome : 1) Idiopathic : - This is the most common cause. 2) Pregnancy and menopause 3) Metabolic : - Gout, Diabetes mellitus 4) Endocrine : - Hypothyroidism, Myxedema, Acromegaly, Hyperparathyroidism. 5) Deposition disorder Amyloidosis, Sarcoidosis, Rheumatid arthritis, Leukemia, CRF, Mucopoly saccharoidosis. 6) Alcoholism 7) Local causes : - Malunited colle''s fracture, osteo-arthritis of the carpal bones, synovitits of flexor tendon sheath, hematoma. Clinical features of carpal tunnel syndrome Carpal tunnel syndrome is more common in women and occurs between 35-50 years. Symptoms usually start gradually, with frequent burning, tingling, paresthesia and numbness in the distribution of median nerve, i.e., lateral three & half of fingers and lateral 2/3rd of palm. The symptoms often first appear during night, since many people sleep with flexed wrists. (Flexion decreases the space in carpal tunnel which results in increased pressure over median nerve). Sensory symptoms can often be reproduced by percussing over median nerve (Tinel''s sign) or by holding the wrist fully flexed for a minute (Phalen''s test). As the disease progresses, clumsiness of hand and impairment of digital function develop. Later in the disease, there is sensory loss in median nerve distribution and obvious wasting of thenar eminence. Clinical Tests for Carpal tunnel syndrome There are some provocative tests which act as important screening methods : ? 1) Wrist flexion (Phalen''s test) : - The patient is asked to actively place the wrist in complete flexion. If tingling and numbness develop in the distribution of median nerve, the test is positive. This is the most sensitive provocative test. 2) Tourniquet test : - A pneumatic BP cuff is applied proximal to the elbow and inflated higher than the patient''s systolic BP. The test is positive if there is paresthesia or numbness in the region of median nerve distribution in hand. 3) Median nerve percussion test (Tinel''s sign) : - The median nerve is gently tapped at the wrist. The test is positive if there is tingling sensation. 4) Median nerve compression test : - Direct pressure is exerted equally over both wrists by the examiner. If symptoms of carpal tunnel syndrome appear, the test is positive.","pyqMatches":[{"year":"2014","no":1773,"q":"Causes of Carpal tunnel syndrome are all except?","o":["DM","RA","Leprosy","Gout"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5127, 'Orthopedics', 'Trauma & Fractures', 'Moderate', 'Orthopedics', 100, '{"id":5127,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Moderate","source":"Orthopedics","sourceNo":100,"q":"Radiological factors indicating an unstable pelvis are all except ?","o":["Posterior sacroiliac complex displacement by > 1 cm","Avulsion fracture of sacral or ischial end of the sacrospinous ligament","Avulsion fractures of the L5 transverse process","Isolated disruption of pubic symphysis with pubic diastasis of 2 cm."],"a":3,"e":"Ans. is ''d'' i.e., Isolated disruption of pubic symphysis with pubic diastasis of 2 cm Radiographic factors indicating unstable pelvis are :- Posterior sacroiliac complex displacement by > lcm Avulsion fracture of sacral or ischial end of the sacrospinous ligament Avulsion fractures of the L5 transverse process Disruption of pubic symphysis with pubic diastasis of 2 cm with posterior pelvic injury or injury to anterior/ posterior sacroiliac ligament or sacrospinous ligaments. Presence of gap rather than impaction in the posterior pelvic ring.","pyqMatches":[{"year":"2014","no":1723,"q":"Radiological factors indicating an unstable pelvis are all except ?","o":["Posterior sacroiliac complex displacement by > 1 cm","Avulsion fracture of sacral or ischial end of the sacrospinous ligament","Avulsion fractures of the L5 transverse process","Isolated disruption of pubic symphysis with pubic diastasis of 2 cm."],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5128, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 101, '{"id":5128,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":101,"q":"Most common complication of mid shaft humerus fracture is ?","o":["Radial nerve palsy","Median nerve palsy","Nonunion","Malunion"],"a":0,"e":"Ans. is ''a'' i.e., Radial nerve palsy Complications of humerus shaft fracture","pyqMatches":[{"year":"2014","no":1726,"q":"Most common complication of mid shaft humerus fracture is ?","o":["Radial nerve palsy","Median nerve palsy","Nonunion","Malunion"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5129, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 102, '{"id":5129,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":102,"q":"Deformity of hip in stage of tubercular synovitis stage is ?","o":["Flexion, abduction external rotation","Flexion, adduction internal rotation","Flexion adduction external rotation","Flexion abduction internal rotation"],"a":0,"e":"Ans. is ''a'' i.e., Flexion, abduction external rotation Synovitis- Flexion abduction external rotation apparent lengthening","pyqMatches":[{"year":"2014","no":1766,"q":"Deformity of hip in stage of tubercular synovitis stage is ?","o":["Flexion, abduction external rotation","Flexion, adduction internal rotation","Flexion adduction external rotation","Flexion abduction internal rotation"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5130, 'Orthopedics', 'Miscellaneous', 'Moderate', 'Orthopedics', 103, '{"id":5130,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Orthopedics","sourceNo":103,"q":"Needle shaped crystals negatively birefringent on polarized microscopy is characteristic of which crystal associated arthropathy?","o":["Gout","CPPD","Neuropathic arthropathy","Hemophilic arthropathy"],"a":0,"e":"Ans. is ''a'' i.e., Gout Crystal of Pseudogout Made up of calcium pyrophosphate Weakly positive birefringent, rhomboid Crystal of gout :- Made up of uric acid (monosodium urate) Strongly negative birefringent, needle shaped","pyqMatches":[{"year":"2014","no":1756,"q":"Needle shaped crystals negatively birefringent on polarized microscopy is characteristic of which crystal associated arthropathy?","o":["Gout","CPPD","Neuropathic arthropathy","Hemophilic arthropathy"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5131, 'Orthopedics', 'Arthritis & Joint Disease', 'Moderate', 'Orthopedics', 104, '{"id":5131,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Moderate","source":"Orthopedics","sourceNo":104,"q":"Which of the following is not a feature of rheumatoid arthritis?","o":["Heberden nodes","Swan neck deformity","Ulnar deviation of fingers at metacarpopalyngeal joint","Symmetric reduction of joint space"],"a":0,"e":"Ans. is ''a'' i.e., Heberden nodes Heberden nodes is a feature of osteoarthritis and not rheumatoid arthritis. Important hand deformities of hand in RA Boutonniere deformity : Flexion contracture of PIP joint and extension of DIP joint. Swan neck deformity : Hyperextension of PIP joint and flexion at DIP joint. Z-deformity : Radial deviation of wrist with ulnar deviation of fingers. Hyperextension of 1st interphalangeal joint and flexion of MP joint.","pyqMatches":[{"year":"2014","no":1751,"q":"Which of the following is not a feature of rheumatoid arthritis?","o":["Heberden nodes","Swan neck deformity","Ulnar deviation of fingers at metacarpopalyngeal joint","Symmetric reduction of joint space"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5132, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 105, '{"id":5132,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":105,"q":"Keinbock''s disease is osteochondritis of ?","o":["Scaphoid","Lunate","Calcaneum","Tibial tuberosity"],"a":1,"e":"Ans. is ''b'' i.e., Lunate Perthes''s disease- Femoral head Panner''s disease- Capitulum Kienbock''s disease- Lunate bone Osgood Shlatter''s disease- Tibial tubercle Sever''s disease- Calcaneal tuberosity Kohler''s disease- Navicular bone","pyqMatches":[{"year":"2014","no":1781,"q":"Keinbock''s disease is osteochondritis of ?","o":["Scaphoid","Lunate","Calcaneum","Tibial tuberosity"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5133, 'Orthopedics', 'Trauma & Fractures', 'Moderate', 'Orthopedics', 106, '{"id":5133,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Moderate","source":"Orthopedics","sourceNo":106,"q":"Metaphyseal fracture touching physis but not crossing it, comes under which type of Salter Harris physeal injury?","o":["I","II","III","IV"],"a":1,"e":"Ans. is ''b'' i.e., II Salter and Harris have classified epiphyseal injuries into five types - Type I : Complete separation of epiphysis from the metaphysis without fracture. Common in rickets, scurvy and osteomyelitis. Type II : The fracture involves the physis and a triangle of metaphyseal bone (Thurston Holland sign) i.e. metaphyseal fracture touching the physis but not crossing it. This is the commonest type of epiphyseal injury accounting for 73 percent of cases over 10 years of age. Type III :The fracture is intra- articular and extends along the physis and then along the growth plate. This injury is relatively uncommon. Type IV : The fracture is intra- articular and extends through the epiphysis, physis and metaphysis. Perfect reduction is necessary and open reduction is more often necessary to prevent growth arrest. Type V : Crushing of epiphysis. Growth arrest usually follows. Type VI (Rang''s type) : There is a peripheral physis (perichondrial ring) injury.","pyqMatches":[{"year":"2014","no":1707,"q":"Metaphyseal fracture touching physis but not crossing it, comes under which type of Salter Harris physeal injury?","o":["I","II","III","IV"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5134, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 107, '{"id":5134,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":107,"q":"Motorcyclist''s fracture is ?","o":["Stellate fracture across base of skull","Transverse fracture across base of skull","Lamina fracture of CI vertebra","Spinous process fracture of C7 vertebra"],"a":1,"e":"Ans. is `b'' i.e., Transverse fracture across base of skull Motorcyclist''s fracture Because of the inherent instability of two wheeled vehicles, the rider and passanger inevitably fall to the ground in a crash. Injuries can occur to any part of the body, but the limbs and head are particularly susceptible to serious injury. Impact with the road surface or another vehicle at speed often causes skull fracture, even in the presence of a helmet. A transverse fracture across the floor of the skull, usually called a \"hinge fracture\", is sometimes referred to as motorcyclist fracture. At autopsy, the base of the skull may be appriciated to have divided into two halves, each moving independently of each other like a hinge, the so-called motorcyclist fracture.","pyqMatches":[{"year":"2014","no":1727,"q":"Motorcyclist''s fracture is ?","o":["Stellate fracture across base of skull","Transverse fracture across base of skull","Lamina fracture of CI vertebra","Spinous process fracture of C7 vertebra"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5135, 'Orthopedics', 'Lower Limb', 'Moderate', 'Orthopedics', 108, '{"id":5135,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Moderate","source":"Orthopedics","sourceNo":108,"q":"Which among the following is not a feature of Unhappy triad of 0'' Donoghue?","o":["ACL injury","Medial meniscus injury","Medial collateral ligament injury","Fibular collateral ligament injury"],"a":3,"e":"Ans. is ''d'' i.e., Fibular collateral ligament injury The most common mechanism of ligament disruption of knee is adduction (valgus), flexion and internal rotation offemur on tibia which usually occur in sports in which the foot is planted solidly on the ground and leg is twisted by rotating body (i.e., foot ball, soccer, basket ball, skiing). The medial structures medial (tibial) collateral ligament (MCL) and medial capsular ligament are first to fail, followed by ACL tears, if the force is of sufficient magnitude. The medial meniscus may be trapped between condyles and have a peripheral tear, thus producing unhappy triad of 0'' Donoghue.","pyqMatches":[{"year":"2014","no":1738,"q":"Which among the following is not a feature of Unhappy triad of 0'' Donoghue?","o":["ACL injury","Medial meniscus injury","Medial collateral ligament injury","Fibular collateral ligament injury"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5136, 'Orthopedics', 'Spine', 'Easy', 'Orthopedics', 109, '{"id":5136,"subject":"Orthopedics","chapter":"Spine","difficulty":"Easy","source":"Orthopedics","sourceNo":109,"q":"Which is the commonest true benign bone tumor?","o":["Osteoid osteoma","Hemangioma","Osteochondroma","Enchondroma"],"a":0,"e":"Ans. is ''a'' i.e., Osteoid osteoma Osteoid osteoma is the most common true benign tumor of the bone. This is a benign circumscribed lesion that may arise in the cortex of long bones or occasionally in the cancellous bone of spine. The characteristic feature is the formation of a small nidus of osteoid tissue, surrounded by a reactive zone of dense sclerosis (Sclerotic new bone formation).","pyqMatches":[{"year":"2014","no":1765,"q":"Which is the commonest true benign bone tumor?","o":["Osteoid osteoma","Hemangioma","Osteochondroma","Enchondroma"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5137, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 110, '{"id":5137,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":110,"q":"Which of the following is true about hallux valgus?","o":["Great toe points laterally","Great toe points medially","Lateral angulation of the 1 stmetatarsophalyngeal joint","Dorsal angulation of the lstmetatarsophalyngeal joint"],"a":0,"e":"Ans. is ''a'' i.e., Great toe points laterally Hallux valgus Hallux valgus is lateral (outward) deviation of great toe at the metatarsophalangeal joint. It is the commonest foot deformity. It is common in women past middle age, and is not infrequent even in young women. Common causes are : Rheumatoid arthritis Wearing pointed shoes with high heels Hereditary factors Idiopathic Pathology Outward deviation of the great toe. After several years two secondary changes occur :- i) Formation of a thick walled bursa (bunion) over the medial prominence of 1\" metatarsal head. ii) Osteoarthritis of metatarsophalangeal joint. It is worth noting that medial prominence over metatarsal head looks like an exostosis, but there is no true exostosis. Lateral deviation of great toe causes overcrowding of lateral toes and sometimes overriding of adjacent toes.","pyqMatches":[{"year":"2014","no":1708,"q":"Which of the following is true about hallux valgus?","o":["Great toe points laterally","Great toe points medially","Lateral angulation of the 1 stmetatarsophalyngeal joint","Dorsal angulation of the lstmetatarsophalyngeal joint"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5138, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 111, '{"id":5138,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":111,"q":"Jaipur foot was invented by ?","o":["P. K. Sethi","S. K. Verma","B. L. Sehgal","H. R. Gupta"],"a":0,"e":"Ans. is ''a'' i.e., P. K. Sethi P. K. Sethi. Pramod Karan Sethi (28 November 1927 - 6 January 2008) was an Indian orthopaedic surgeon. With Ram Chandra Sharma, he co-invented the \"Jaipur foot\", an inexpensive and flexible artificial limb, in 1969.","pyqMatches":[{"year":"2014","no":1706,"q":"Jaipur foot was invented by ?","o":["P. K. Sethi","S. K. Verma","B. L. Sehgal","H. R. Gupta"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5139, 'Orthopedics', 'Spine', 'Easy', 'Orthopedics', 112, '{"id":5139,"subject":"Orthopedics","chapter":"Spine","difficulty":"Easy","source":"Orthopedics","sourceNo":112,"q":"Test used for prolapsed lumbar intervertebral disc is -","o":["Active straight leg raising test","Lasegue test","Thomas test","Apley''s grinding test"],"a":1,"e":"Ans. is ''b'' i.e., Lasegue test Clinical examination in PID Forward stooping (bending), twisting or coughing aggravate the pain. The trunk is tilted to one side (sciatic scoliosis or sciatic tilt). Movements of lumbar spine are restricted especially flexion. Straight leg raising (SLR) test is positive, i.e. straight leg raising is possible 40° or less (AIIMSO4). Lasegue test (a modification of SLR test) is positive.","pyqMatches":[{"year":"2014","no":1734,"q":"Test used for prolapsed lumbar intervertebral disc is","o":["Active straight leg raising test","Lasegue test","Thomas test","Apley''s grinding test"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5140, 'Orthopedics', 'Spine', 'Hard', 'Orthopedics', 113, '{"id":5140,"subject":"Orthopedics","chapter":"Spine","difficulty":"Hard","source":"Orthopedics","sourceNo":113,"q":"Lumbar canal stenosis presents as ?","o":["Claudication","Scoliotic deformity","Kyphotic deformity","Radiculopathy"],"a":0,"e":"Ans. is ''a'' i.e., Claudication The patient of lumbar canal stenosis is usually a man aged over 50, complains of aching, heaviness, numbness and paraesthesia in the thighs and legs; it comes on after standing upright or walking for 5- 10 minutes, and is consistently relieved by sitting, squatting or leaning against a wall to flex the spine (hence the term ''spinal claudication'').","pyqMatches":[{"year":"2014","no":1735,"q":"Lumbar canal stenosis presents as ?","o":["Claudication","Scoliotic deformity","Kyphotic deformity","Radiculopathy"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5141, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 114, '{"id":5141,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":114,"q":"Callus formation is seen between what duration of fracture healing ?","o":["0 - 2 weeks","2 - 4 weeks","4 - 12 weeks","12 - 16 weeks"],"a":2,"e":"Ans. is ''c'' i.e., 4 - 12 weeks Healing of a fracture The process of fracture healing varies according to the type of bone involved and the amount of movement at the fracture site. Following healing processes are there :? Indirect fracture healing (healing by callus) This is the ''natural'' form of healing in tubular bones and in the absence of rigid fixation when there is micromovement at fracture site. There is formation of internal and external callus. This stage is divided in three phases which are further subdivided into five stages :","pyqMatches":[{"year":"2014","no":1709,"q":"Callus formation is seen between what duration of fracture healing ?","o":["0 - 2 weeks","2 - 4 weeks","4 - 12 weeks","12 - 16 weeks"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5142, 'Orthopedics', 'Bone Tumors', 'Easy', 'Orthopedics', 115, '{"id":5142,"subject":"Orthopedics","chapter":"Bone Tumors","difficulty":"Easy","source":"Orthopedics","sourceNo":115,"q":"In osteogenic sarcoma predominant histological finding is ?","o":["Giant cells","Osteoid forming tumor cells","Fibroblastic proliferation","Chondroblasts"],"a":1,"e":"Ans. is ''b'' i.e., Osteoid forming tumor cells Histologic appearance of osteosarcoma It appears pale and extending through the cortex on gross cut section examination. On histological sections it consists of malignant stromal tissue showing osteoid formation. Osteoid bone formation by tumor cells is diagnostic of OGS.","pyqMatches":[{"year":"2014","no":1762,"q":"In osteogenic sarcoma predominant histological finding is ?","o":["Giant cells","Osteoid forming tumor cells","Fibroblastic proliferation","Chondroblasts"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5143, 'Orthopedics', 'Trauma & Fractures', 'Moderate', 'Orthopedics', 116, '{"id":5143,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Moderate","source":"Orthopedics","sourceNo":116,"q":"Osteoporosis is characterized by all the following except ?","o":["Decreased bone mineral density","Decreased Serum Calcium, phosphorus and alkaline phosphatase is seen","Glucocorticoids can cause osteoposis","Dorsolumbar spine is the most coomon site of osteoporotic fracture"],"a":1,"e":"Ans. is ''b'' i.e., Decreased Serum Calcium, phosphorus and alkaline phosphatase is seen Osteoporosis is a state of decreased mass per unit volume of a normally mineralized bone. Osteoporosis is the commonest metabolic bone disease. Osteoporosis is characterized by an abnormally low bone mass (low bone density) and defects in bone structure, a combination of which renders the bone unusually fragile and at greater than normal risk of fracture. Bone depletion may be brought about by predominant bone resorption, decreased bone formation or a combination of the two.","pyqMatches":[{"year":"2014","no":1782,"q":"Osteoporosis is characterized by all the following except ?","o":["Decreased bone mineral density","Decreased Serum Calcium, phosphorus and alkaline phosphatase is seen","Glucocorticoids can cause osteoposis","Dorsolumbar spine is the most coomon site of osteoporotic fracture"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5144, 'Orthopedics', 'Arthritis & Joint Disease', 'Moderate', 'Orthopedics', 117, '{"id":5144,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Moderate","source":"Orthopedics","sourceNo":117,"q":"Arthritis involving DIP, PIP, 1st carpometacarpal with sparing of MCP and wrist joints is typical of ?","o":["Osteoarthritis","Rheumatoid arthritis","Ankylosing spondylitis","Psoriatic arthritis"],"a":0,"e":"Ans. is ''a'' i.e., Osteoarthritis 1st Carpometacarpal joint Wrist- Osteoarthritis","pyqMatches":[{"year":"2014","no":1747,"q":"Arthritis involving DIP, PIP, 1st carpometacarpal with sparing of MCP and wrist joints is typical of ?","o":["Osteoarthritis","Rheumatoid arthritis","Ankylosing spondylitis","Psoriatic arthritis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5145, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 118, '{"id":5145,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":118,"q":"Sunderland classification is used for ?","o":["Nerve injury","Muscle injury","Tendon injury","Ligament injury"],"a":0,"e":"Ans. is ''a'' i.e., Nerve injury Sunderland is an extension of the seddon classification and includes 5 types of nerve injuries.","pyqMatches":[{"year":"2014","no":1746,"q":"Sunderland classification is used for ?","o":["Nerve injury","Muscle injury","Tendon injury","Ligament injury"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5146, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 119, '{"id":5146,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":119,"q":"Index finger infection spreads to ?","o":["Thenar space","Mid palmar space","Hypothenar space","Flexion space"],"a":0,"e":"Ans. is ''a'' i.e., Thenar space Thenar space communicates with the index finger while the mid palmar space communicates with the middle, ring and little fingers. Thus infection of index finger leads to thenar space infection while the infection of middle, ring or little finger leads to mid palmar space infection.","pyqMatches":[{"year":"2014","no":1774,"q":"Index finger infection spreads to ?","o":["Thenar space","Mid palmar space","Hypothenar space","Flexion space"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5147, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 120, '{"id":5147,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":120,"q":"Pipkin''s classification system is used for ?","o":["Fracture femur head","Fracture femur shaft","Fracture proximal tibia","Fracture calcaneum"],"a":0,"e":"Ans. is ''a'' i.e., Fracture femur head Pipikin''s classification of femoral head fracture Type I : Femoral head fracture inferior (caudal) to fovea. Type II : Femoral head fracture superior (cephalad) to fovea. Type III : Femoral head fracture with associated femoral neck fracture. Type IV : Type I, II or III with associated acetabular fracture.","pyqMatches":[{"year":"2014","no":1724,"q":"Pipkin''s classification system is used for ?","o":["Fracture femur head","Fracture femur shaft","Fracture proximal tibia","Fracture calcaneum"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5148, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 121, '{"id":5148,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":121,"q":"Tinel sign is seen in ?","o":["Nerve degeneration","Nerve regeneration","Muscle degeneration","Muscle regeneration"],"a":1,"e":"Ans. is ''b'' i.e., Nerve regeneration Pathological changes after nerve injury After nerve injury, nerve first degenerates and then tries to regenerate. Nerve degeneration The part of the neurone distal to the point of injury undergoes secondary or Wallerian degeneration; the proximal part undergoes primary or retrograde degeneration upto a single node. Nerve regeneration As regeneration begins, the axonal stump from the proximal segment begins to grow distally. If the endoneural tube with its contained Schwann cells is intact, the axonal sprout may readily pass along its primary course and reinnervate the end-organ. The rate of recovery of axon is 1 mm per day. The muscles nearest to the site of injury recovers first, followed by others as the nerve reinnervates muscles from proximal to distal, the so-called motor march. When the skin over the nerve is percussed gently from distal to proximal, the patient gets a tingling sensation if the nerve is recovering. This is called Tinel''s sign and is a sign of recovery.","pyqMatches":[{"year":"2016","no":1466,"q":"Tinel sign is seen in ?","o":["Nerve degeneration","Nerve regeneration","Muscle degeneration","Muscle regeneration"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5149, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 122, '{"id":5149,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":122,"q":"Dinner fork deformity is seen in?","o":["Colle''s fracture","March fracture","Lateral condyle fracture","Supracondylar fracture"],"a":0,"e":"Ans. is ''a'' i.e., Colle''s fracture Complications of colle''s fracture Complications in colle''s fracture are high (50-60%). Following complications may occur 1) Stiffness of fingers and joints Stiffness of finger, wrist and shoulder is the most common avoidable complication of colle''s fracture. This occurs due to lack of exercise. Therefore, patient should be encouraged for active exercise of finger and shoulder. 2) Malunion It is the second most common complication It results in dinner fork deformity 3) Sudek''s osteodystrophy (reflex sympathetic dystrophy) 4) Carpal tunnel syndrome: Median nerve may get compressed in carpal tunnel 5) Carpal instability 6) Rupture of the extensor pollicis longus tendon 7) Frozen shoulder syndrome This is a troublesome complication which develops due to unnecessory voluntary shoulder immobilization by the patient on the affected side for fear of fracture displacement. 8)TFCC injury 9) Non-union is very rare","pyqMatches":[{"year":"2015","no":1459,"q":"Dinner fork deformity is seen in?","o":["Colle''s fracture","March fracture","Lateral condyle fracture","Supracondylar fracture"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5150, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 123, '{"id":5150,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":123,"q":"Tennis elbow is characterized by ?","o":["Tenderness over the medial epicondyle","Tendinits of common extensor origin","Tendinitis of common flexor origin","Painful flexion and extension"],"a":1,"e":"Ans. is ''b'' i.e., Tendinits of common extensor origin Tennis elbow is extraarticular affection characterized by pain and acute tenderness at the origin of the extensor muscles of the forearm from the lateral epicondyle. It is believed to be caused by strain of the forearm extensor muscles, particularly the extensor carpi radialisbrevis, at the point of their origin from lateral epicondyle.","pyqMatches":[{"year":"2015","no":1434,"q":"Tennis elbow is characterized by ?","o":["Tenderness over the medial epicondyle","Tendinits of common extensor origin","Tendinitis of common flexor origin","Painful flexion and extension"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5151, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 124, '{"id":5151,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":124,"q":"False about osteoarthritis is ?","o":["Involves synovial joints","Progressive softening of the articular cartilage","It is an inflammatory arthritis","Marginal osteophytes are produced"],"a":2,"e":"Ans. is ''c'' i.e., It is an inflammatory arthritis Osteoarthritis (OA) is a chronic disorder of synovial joints in which there is progressive softening and disintegration of articular cartilage accompanied by new growth of cartilage and bone at the joint margins (osteophytes), cyst formation and sclerosis in the subchondral bone, mild synovitis and capsular fibrosis. The term osteoarthritis is a misnomer as it is a non-inflammatory condition. The right term is osteoarthrosis or degenerative joint disorder because it is a degenerative wear - and - tear process occuring in joints.","pyqMatches":[{"year":"2016","no":1483,"q":"False about osteoarthritis is ?","o":["Involves synovial joints","Progressive softening of the articular cartilage","It is an inflammatory arthritis","Marginal osteophytes are produced"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5152, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 125, '{"id":5152,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":125,"q":"Tardy ulnar nerve palsy is seen in","o":["Medial condyle # humerus","Lateral condyle # humerus","Humerus shaft fracture","Fracture shaft radius"],"a":1,"e":"Ans. is ''b'' i.e., Lateral condyle # humerus Causes of tardy ulnar nerve palsy are : -","pyqMatches":[{"year":"2012","no":1243,"q":"Tardy ulnar nerve palsy is seen in","o":["Medial condyle # humerus","Lateral condyle # humerus","Humerus shaft fracture","Fracture shaft radius"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5153, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 126, '{"id":5153,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":126,"q":"Ankle sprain due to forced inversion of a plantar flexed foot is due to injury to","o":["Anterior talofibular ligament","Posterior talofibular ligament","Calcaneofibular ligament","Posterior fibres of deltoid"],"a":0,"e":"Ans. a. Anterior talofibular ligament * Structures damaged due to inversion injury. - Peroneal tendon injury. - Avulsion fracture of tip of lateral malleolus . - Avulsion fracture of anterolateral surface of talus & calcaneum (sustentaculum tali). - Fracture of base of 5th metatarsal. - Lateral collateral ligament injury (anterior talo fibular > calcaneofibular > posterior- talofibular ligament). - Medial malleolus fracture.","pyqMatches":[{"year":"2016","no":1442,"q":"Ankle sprain due to forced inversion of a plantar flexed foot is due to injury to","o":["Anterior talofibular ligament","Posterior talofibular ligament","Calcaneofibular ligament","Posterior fibres of deltoid"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5154, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 127, '{"id":5154,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":127,"q":"Gallows traction is used for fracture:","o":["Shaft femur","Neck femur","Shaft tibia","Tibial tuberosity"],"a":0,"e":"Ans. a. Shaft femur Gallow''s traction is used for treatment of fracture shaft of femur, in infants and children Gallow''s Traction Gallow''s traction is used for treatment of fracture shaft of femur, in infants and children Weight must not be >12 kgs Both the fractured and the normal femur are placed in skin traction and infant is suspended by these from a special frame. The buttocks should be lifted just off the bed so that the weight of the body provides counter traction and the fracture is reduced Uses of Tractions Name Use Bryant''s TractionQ Fracture shaft of femur in children Gallow''s TractionQ Fracture shaft of femur in children Russel''s TractionQ Fracture shaft of femur in older children Perkin''s TractionQ Fracture shaft of femur in adults F h f f f i 90°-90° TractionQ Fracture shaft of femur in children Agnes-Hunt TractionQ Correction of Hip deformit Well-Leg TractionQ Correction of adduction or abduction deformity of hip Dunlop TractionQ Supracondylar fracture of humerus Smith''s TractionQ Supracondylar fracture of humerus Uses of Tractions Name Use Calcaneal Traction Open fractures of ankle or leg Metacarpal Traction Open forearm fractures Head-Halter Traction Cervical spine injuries Crutchfield TractionQ Cervical spine injuries Halo-Pelvic Traction Scoliosis","pyqMatches":[{"year":"2014","no":1715,"q":"Gallows traction is used for fracture:","o":["Shaft femur","Neck femur","Shaft tibia","Tibial tuberosity"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5155, 'Orthopedics', 'Lower Limb', 'Moderate', 'Orthopedics', 128, '{"id":5155,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Moderate","source":"Orthopedics","sourceNo":128,"q":"True about ankylosing spondylitis are all except ?","o":["Affects males","3 0-40yrs","90% HLA-B5","Bamboo spine"],"a":2,"e":"Ans. is ''c'' i.e., 90% HLA-B5 Ankylosing spondylitis (marie-strumpell disease) Ankylosing spondylitis is a chronic progressive inflammatory disease of the sacroiliac joints and the axial skeleton. rototype of seronegative (absence of rheumatoid factor) spondyloarthropathies. Inflammatory disorder of unknown cause. Usually begins in the second or third decade with a median age of 23, in 5% symptoms begin after 40. Male to female ratio is 2-3 : 1 Strong correlation with HLA-B270-95% of case 9s are positive for HLA - B27. Joints involved in ankylosing spondylitis Ankylosing spondylitis primarily affects axial skeleton. The disease usually begins in the sacro-iliac joints and usually extends upwards to involve the lumbar, thoracic, and often cervical spine. In the worst cases the hips or shoulders are also affected. Hip joint is the most commonly affected peripheral joint. Rarely knee (Ebenzar 4th/e 593) and ankle (Apley''s 9thle 67) are also involved. Pathology Enthesitis i.e. inflammation of the insertion points of tendons, ligaments or joint capsule on bone is one of the hallmarks of this entity of disease. Primarily affects axial (spinal) skeleton and sacroiliitis is often the earliest manifestation of A.S.. Involvement of costovertebral joints frequently occur, leading to diminished chest expansion (normal _ 5 cm) Peripheral joints e.g. shoulders, and hips are also involved in 1/3rd patients. Extraarticular manifestations like acute anterior uveitis (in 5%); rarely aortic valve disease, carditis and pulmonary fibrosis also occur. Pathological changes proceed in three stages? Inflammation with granulation tissue formation and erosion of adjacent bone. Fibrosis of granulation tissue Ossification of the fibrous tissue, leading to ankylosis of the joint. Radiological features of ankylosing spondylitis Radiographic evidence of sacroiliac joint is the most consistent finding in ankylosing spondylitis and is crucial for diagnosis. The findings are :- Sclerosis of the articulating surfaces of SI joints Widening of the sacroiliac joint space Bony ankylosis of the sacroiliac joints Calcification of the sacroiliac ligament and sacro-tuberous ligaments Evidence of enthesopathy - calcification at the attachment of the muscles, tendons and ligaments, particularly around the pelvis and around the heel. X-ray of lumbar spine may show :- Squaring of vertebrae : The normal anterior concavity of the vertebral body is lost because of calcification of the anterior longitudinal ligament. ft Loss of the lumbar lordosis. Bridging `osteophytes'' (syndesmophytes) Bamboo spine appearance","pyqMatches":[{"year":"2014","no":1750,"q":"True about ankylosing spondylitis are all except ?","o":["Affects males","3 0-40yrs","90% HLA-B5","Bamboo spine"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5156, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 129, '{"id":5156,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":129,"q":"In extension type of supracondylar fracture, the usual displacement","o":["Anterolateral","Anterolateral","Posteromedial","Posterolateral"],"a":3,"e":"Ans. is ''d'' i.e., Posterolateral Types of supracondylar fracture Supracondylar fracture is broadly classified into extension type and flexion type. 1. Extension type It is the most common type (97 - 99%). Distal fragment is extended (tilted backward/posteriorly) in relation to proximal fragment. Occurs due to hyperextension injury after fall on outstretched hands. Generally, displacement of distal fragment may be : ? Posteromedial (70-80%) Posterolateral (20-30%)","pyqMatches":[{"year":"2013","no":1500,"q":"In extension type of supracondylar fracture, the usual displacement","o":["Anterolateral","Anterolateral","Posteromedial","Posterolateral"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5157, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 130, '{"id":5157,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":130,"q":"In Articular cartilage, most active chondrocytes are seen in ?","o":["Zone 1","Zone 2","Zone 3","Zone 4"],"a":2,"e":"Ans. is ''c'' i.e., Zone 3 o There are four zones (layers) of articular cartilage from the articular surface to subchondral bone.","pyqMatches":[{"year":"2013","no":1491,"q":"In Articular cartilage, most active chondrocytes are seen in ?","o":["Zone 1","Zone 2","Zone 3","Zone 4"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5158, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 131, '{"id":5158,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":131,"q":"Most common cause of neuropathic joint ?","o":["Leprosy",") Tabes dorsalis","Diabetes","Nerve injury"],"a":2,"e":"Ans. is `c'' i.e., Diabetes Neuropathic joint (Charcot''s joint) o It is a progressive destructive arthritis associated with loss of pain sensationx, proprioception or both, in addition normal muscular reflexes that modulate joint movements are decreased. Without these protective mechanisms, joints are subjected to repeated trauma, resulting in progressive cartilage and bone damage. o It is most commonly caused by diabetes mellitus. Causes of Neuropathic joint disease (Charcoat''s joint) Causes of Neuropathic joint disease (Charcoat''s joint) Diabetes mellitus (most common) Amyloidosis Tabes Dorsalis Leprosy Meningomyelocele Congenital indifference to pain Syringomyelia Peroneal muscular atrophy","pyqMatches":[{"year":"2013","no":1556,"q":"Most common cause of neuropathic joint ?","o":["Leprosy",") Tabes dorsalis","Diabetes","Nerve injury"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5159, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 132, '{"id":5159,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":132,"q":"Most common nerve used for nerve conduction study in H reflex ?","o":["Median nerve","Ulnar nerve","Tibial nerve","Peroneal nerve"],"a":2,"e":"Ans.is ''c'' i.e., Tibial nerve It is recorded over the soleus or gastrocnemius muscles. It is used mos The H reflex is basically an electrophysiologically recorded Achilles tendon stretch reflex. o It is performed by stimulating the tibial nerve in popliteal fossa. t commonly to evaluate Si radiculopathy or to distinguish it from an L5 radiculopathy.","pyqMatches":[{"year":"2013","no":1518,"q":"Most common nerve used for nerve conduction study in H reflex ?","o":["Median nerve","Ulnar nerve","Tibial nerve","Peroneal nerve"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5160, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 133, '{"id":5160,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":133,"q":"Moth eaten bone is ?","o":["Osteoid osteoma","Multiple myeloma","Eosinophilic granuloma","Chondromyxoid fibroma"],"a":1,"e":"Ans. is ''b'' i.e., Multiple myeloma Patterns of bone destruction present in a lytic lesion ?","pyqMatches":[{"year":"2013","no":1538,"q":"Moth eaten bone is ?","o":["Osteoid osteoma","Multiple myeloma","Eosinophilic granuloma","Chondromyxoid fibroma"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5161, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 134, '{"id":5161,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":134,"q":"Commonest ligament injured in ankle injury ?","o":["Anterior talofibular ligament","Calcaneofibular ligament","Posterior talofibular ligament","Spring ligament"],"a":0,"e":"Ans. is ''a'' i.e., Anterior talofibular ligament The ankle is one of the most common sites for acute musculoskeletal injuries. Sprains constitute 85% of all ankle injuries, and 85% of those involve a lateral inversion mechanism. Inversion Sprain - Inversion ankle sprains occur when the foot turns in or out to an abnormal degree relative to the ankle. The most common mechanism of an ankle sprain is a combination of plantarflexion and inversion where the foot is pointing downward and inward. The lateral ligaments are involved in an inversion ankle sprain and hence most commonly damaged. These ligaments are on the outside of the ankle, which includes the anterior talofibular (ATFL), calcaneofibular (CFL) and posterior talofibular ligaments (PTFL). Injury to the ATFL is the most common. When both the ATFL and CFL are injured together, ankle instability will be more noticeable. The PTFL is the strongest of the three ligaments and is rarely injured in an inversion sprain.","pyqMatches":[{"year":"2012","no":1236,"q":"Commonest ligament injured in ankle injury ?","o":["Anterior talofibular ligament","Calcaneofibular ligament","Posterior talofibular ligament","Spring ligament"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":1739,"q":"Commonest ligament injured in ankle injury ?","o":["Anterior talofibular ligament","Calcaneofibular ligament","Posterior talofibular ligament","Spring ligament"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5162, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 135, '{"id":5162,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":135,"q":"Flexor tendon graft repair graft is taken from ?","o":["Plantaris","Palmaris longus","Extensor digitorum","Extensor indicis"],"a":3,"e":"Ans. is ''d'' i.e., Extensor indicis Beside covering the bone and sharing some of its blood supply with the bone, periosteum (particularly cambium layer) also produces bone when it is stimulated. Practically anything that breaks, tears, stretches, inflames or even touches the periosteum, stimulates the reactive bone formation by periosteum. This is called periosteal reaction. Differential Diagnosis of Periosteal Reaction Arthritis Psoriatic arthritis Reactive arthritis Metabolic Hypertrophic pulmonary osteoarthropathy Thyroid acropathy Congenital Pachydermoperiostosis Periosteal reaction of newborn Trauma Stress fracture Fracture Drugs Fluorosis Hypervitaminosis A Prostaglandins Tumors Osetosarcoma Ewing''s sarcoma Chondroblastoma Eosinophilic granuloma Osteoid osteoma Leukemia and lymphoma Infection Genetic Caffey disease Vascular Venous stasis Neuropathic arthropathy is also associated with periosteal reaction.","pyqMatches":[{"year":"2013","no":1492,"q":"Flexor tendon graft repair graft is taken from ?","o":["Plantaris","Palmaris longus","Extensor digitorum","Extensor indicis"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5163, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 136, '{"id":5163,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":136,"q":"Insal-Salvati index is used for ?","o":["Olecranon","Patella","Talus","Scaphoid"],"a":1,"e":"Ans. is ''b'' i.e., Patella Two radiological indices are commonly used for determining the position of patella - Insall-Salvati index","pyqMatches":[{"year":"2013","no":1557,"q":"Insal-Salvati index is used for ?","o":["Olecranon","Patella","Talus","Scaphoid"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5164, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 137, '{"id":5164,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":137,"q":"Intramembranous ossification is seen in whichbones?","o":["Pelvis","Long bones","Maxilla","None"],"a":2,"e":"Ans. is ''c'' i.e., Maxilla Bone formation Bone formation (ossification) occurs by two methods : 1) Endochondral ossification, 2) Intramembranous ossification. In both, mesenchymal connective tissue is replaced by bone but by different mechanics. Endochondral ossification","pyqMatches":[{"year":"2013","no":1493,"q":"Intramembranous ossification is seen in whichbones?","o":["Pelvis","Long bones","Maxilla","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5165, 'Orthopedics', 'Arthritis & Joint Disease', 'Hard', 'Orthopedics', 138, '{"id":5165,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Hard","source":"Orthopedics","sourceNo":138,"q":"Radiological sign in case of Perthe''s disease ?","o":["Epiphyseal calcification","Organized calcification","Lateral subluxation femur head","Restriction of abduction"],"a":1,"e":"Ans. is ''b'' i.e., Organized calcification Seronegative spondvloarthropathies The seronegative spondyloarthropathies are a group of disorders that share certain clinical features and genetic associations. The word seronegative referes to the absence of rheumatoid factor in this group of disorders. The seronegative spondyloarthropathies include ?","pyqMatches":[{"year":"2013","no":1523,"q":"Radiological sign in case of Perthe''s disease ?","o":["Epiphyseal calcification","Organized calcification","Lateral subluxation femur head","Restriction of abduction"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5166, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 139, '{"id":5166,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":139,"q":"True about proximal fragment in supratrochantric fracture is ?","o":["Flexion","Abduction","External rotation","All the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above Deformity in cases of fracture subtrochanteric femur The proximal femur is surrounded by very large and powerful muscles. In the case of a fracture, their spatial arrangement, combined with their origin and insertion, results in a very characteristic deformity. The proximal fragment, as a result of contraction of the abductors, the external rotators, and the iliopsoas muscle, is flexed, abducted, and externally rotated. The adductors cause the shaft to be adducted, and the force of gravity causes the distal fragment to fall into some external rotation. All the muscles that span the fracture combine to cause shortening. Thus, the resultant deformity is one of an anterior and lateral bowing of the proximal shaft, combined with con​siderable shortening and variable degrees of external rotation.","pyqMatches":[{"year":"2013","no":1511,"q":"True about proximal fragment in supratrochantric fracture is ?","o":["Flexion","Abduction","External rotation","All the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5167, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 140, '{"id":5167,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":140,"q":"Anterolateral arthroscopy of knee is for ?","o":["To see patella femoral articulation","To see the posterior cruciate ligament","To see the anterior portion of lateral meniscus","To see the periphery of the posterior horn of medial"],"a":0,"e":"Ans. is ''a'' i.e., To see patella femoral articulation Standard Portals In Knee Arthroscopy : Anterolateral portal ?","pyqMatches":[{"year":"2013","no":1558,"q":"Anterolateral arthroscopy of knee is for ?","o":["To see patella femoral articulation","To see the posterior cruciate ligament","To see the anterior portion of lateral meniscus","To see the periphery of the posterior horn of medial"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5168, 'Orthopedics', 'Spine', 'Easy', 'Orthopedics', 141, '{"id":5168,"subject":"Orthopedics","chapter":"Spine","difficulty":"Easy","source":"Orthopedics","sourceNo":141,"q":"Dripping Candle Wax lesion on spine ?","o":["Metastasis","TB spine","Osteopterosis","Melorheostosis"],"a":3,"e":"Ans. is ''d'' i.e., Melorheostosis Melorheostosis Melorheostosis is a medical developmental disorder and mesenchymal dysplasia in which the bony cortex widens and becomes hyperdense in a sclerotomal distribution. Caused by a mutation of the LEMD3gene. Can be detected by radiograph due to thickening of bony cortex resembling \"dripping candle wax\". Disorder tends to be unilateral and monoostotic, with only one limb typically involved. Cases with involvement of multiple limbs, ribs, and bones in the spine have also been reported. There are no reported cases of involvement of skull or facial bones. Melorheostosis can be associated with pain, physical deformity, skin and circulation problems, contractures, and functional limitation. It is also associated with a benign inner ear dysplasia known as osteosclerosis.","pyqMatches":[{"year":"2013","no":1544,"q":"Dripping Candle Wax lesion on spine ?","o":["Metastasis","TB spine","Osteopterosis","Melorheostosis"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5169, 'Orthopedics', 'Pediatric Orthopedics', 'Easy', 'Orthopedics', 142, '{"id":5169,"subject":"Orthopedics","chapter":"Pediatric Orthopedics","difficulty":"Easy","source":"Orthopedics","sourceNo":142,"q":"Cause of Coxa vera ?","o":["Congenital","Perthe''s disease","SCFE","All of the above"],"a":0,"e":"Ans. is ''d'' i.e., All of the above Coxa vera Coxa vera refers to reduced angle between the neck and shaft of the femur. Coxa vera may be congenital or acquired.","pyqMatches":[{"year":"2013","no":1524,"q":"Cause of Coxa vera ?","o":["Congenital","Perthe''s disease","SCFE","All of the above"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5170, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 143, '{"id":5170,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":143,"q":"Bunion is commonly seen at ?","o":["Great toe MTP joint","Medial malleolus","Lateral Malleolus","Shin of tibia"],"a":0,"e":"Ans. is ''a'' i.e., Great toe MTP joint Bunion A hallux abducto valgus deformity, commonly called a bunion, is a deformity characterized by lateral deviation of the great toe, often erroneously described as an enlargement of bone or tissue around the joint at the head of the big toe. The bump itself is partly due to the swollen bursal sac or an osseous (bony) anomaly on the metatarsophalangeal joint. The larger part of the bump is a normal part of the head of the first metatarsal bone that has tilted sideways to stick out at its top.","pyqMatches":[{"year":"2013","no":1545,"q":"Bunion is commonly seen at ?","o":["Great toe MTP joint","Medial malleolus","Lateral Malleolus","Shin of tibia"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5171, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 144, '{"id":5171,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":144,"q":"Most common type of shoulder dislocation is ?","o":["Preglenoid","Subcoracoid","Subclavicular","Posterior"],"a":0,"e":"Ans. is ''a'' i.e., Preglenoid Anterior dislocation of the shoulder is the most common type of shoulder dislocation. Head of the humerus comes out of the glenoid cavity and lies anteriorly. Anterior dislocation of shoulder could be :?","pyqMatches":[{"year":"2013","no":1498,"q":"Most common type of shoulder dislocation is ?","o":["Preglenoid","Subcoracoid","Subclavicular","Posterior"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5172, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 145, '{"id":5172,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":145,"q":"Pencil in cup deformity is seen in ?","o":["Rheumatoid arthritis","Ankylosing spondylitis","AVN","Psoriatic arthritis"],"a":3,"e":"Ans. is `D i.e., Psoriatic arthritis Gull''s wing appearance- Psoriatic arthritis Opera glass deformity- Psoriatic arthritis Cup and pencil deformity- Psoriatic arthritis","pyqMatches":[{"year":"2013","no":1552,"q":"Pencil in cup deformity is seen in ?","o":["Rheumatoid arthritis","Ankylosing spondylitis","AVN","Psoriatic arthritis"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5173, 'Orthopedics', 'Spine', 'Moderate', 'Orthopedics', 146, '{"id":5173,"subject":"Orthopedics","chapter":"Spine","difficulty":"Moderate","source":"Orthopedics","sourceNo":146,"q":"All are true about aneurismal bone cyst except ?","o":["Eccentric","Expansile & lytic","Treated by simple curettage","Metaphysis of long bones"],"a":2,"e":"Ans. is ''c'' i.e., Treated by simple curettage Aneurysmal bone cyst Aneurysmal bone cyst occur in children and young adults (5-20 years). The term aneurysmal is used because it causes expansion of overlying cortex like vascular expansion of an aneurysm. The metaphysis of long bones is involved most commonly. Most common in femur and tibia; however any long bone can be involved. Other common sites are posterior elements of vertebrae and pelvis. athology Cystic spaces of variable sizes & number which are filled with blood but not lined with vascular endothelium. The wall of vascular space is lined with fibroblast cells with collagen, giant cells, hemosiderin & osteoid (secondary to microfractures). Clinical features With expanding lesions, pain may be a presenting feature. Large cyst can also cause swelling Pathological fracture may occur (but less frequent than simple bone cyst). Radiological features of aneurysmal bone cyst Eccentric, expansile osteolytic lesion The characteristic feature is ''blown-out'' distension of one surface of the bone. Overlying cortex may be intact or disrupted. Extensive sclerosis at the interface between normal and expanded cortex (buttersing) may be present. Delicate thin trabeculae is characteristic and an expansile ballooning lesion may produce a ''soap-bubble appearance''. Lesion occurs at metaphysis of long bones. Other common locations include the posterior elements of the spine(pedicle, lamina, transverse process, spinous process) and pelvis. Treatment Surgery is the treatment of choice. Curettage and bone grafting is the procedure commonly followed.","pyqMatches":[{"year":"2013","no":1539,"q":"All are true about aneurismal bone cyst except ?","o":["Eccentric","Expansile & lytic","Treated by simple curettage","Metaphysis of long bones"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5174, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 147, '{"id":5174,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":147,"q":"Painful arc syndrome is caused by impingement of ?","o":["Sub acromial bursa","Sub deltoid bursa","Rotator cuff tendon","Biceps tendon"],"a":2,"e":"Ans. is ''c'' i.e., Rotator cuff tendon Painful arc syndrome Pain in the shoulder and upper arm during mid range of glenohumeral abduction. Causes - supraspinatus tendon tear or tendinitis, subacromial bursitis, fracture of greater tuberosity. The space between the upper end of humerus and the acromion gets compromised so that during mid abduction the tendon of rotator cuff gets nipped between the greater tuberosity and acromion.","pyqMatches":[{"year":"2013","no":1499,"q":"Painful arc syndrome is caused by impingement of ?","o":["Sub acromial bursa","Sub deltoid bursa","Rotator cuff tendon","Biceps tendon"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5175, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 148, '{"id":5175,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":148,"q":"The father of joint replacement surgery is ?","o":["Manning","Girdlestone","Charnley","Ponseti"],"a":2,"e":"Ans. is ''c'' i.e., Charnley Father of the modern hip replacement: Professor Sir John Charnley (1911-82). Professor Sir John Charnley was a British orthopaedic surgeon, inventor and skilled craftsman. He is best known for his development of the first truly successful operation for total arthroplasty of the hip, the low-friction arthroplasty. As well as publishing significant works on closed fracture management and compression arthrodesis, he can also be accredited with pioneering work in the development of clean-air operating conditions and body-exhaust suits.","pyqMatches":[{"year":"2013","no":1497,"q":"The father of joint replacement surgery is ?","o":["Manning","Girdlestone","Charnley","Ponseti"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5176, 'Orthopedics', 'Spine', 'Easy', 'Orthopedics', 149, '{"id":5176,"subject":"Orthopedics","chapter":"Spine","difficulty":"Easy","source":"Orthopedics","sourceNo":149,"q":"Halopelvic traction is used for correcting which deformity","o":["Spine","Pectus Carinatum","Spondyloptosis","Coxa Vara"],"a":0,"e":"Ans. is ''a'' i.e., Spine Head-pelvic skeletal traction was first attempted in 1958. With the description of the \"halo\" skull traction apparatus by Perry and Nickel (1959), a method was provided for immobilising the unstable cervical spine. From this developed \"halo-femoral\" traction, now used by some surgeons for the correction of spinal deformities before and after operation.","pyqMatches":[{"year":"2013","no":1559,"q":"Halopelvic traction is used for correcting which deformity","o":["Spine","Pectus Carinatum","Spondyloptosis","Coxa Vara"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5177, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 150, '{"id":5177,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":150,"q":"Game keepers thumb is ?","o":["Thumb metacarpophalangeal joint ulnar collateral ligament rupture","Thumb metacarpophalangeal joint radial collateral ligament rupture","Thumb interphalangeal joint ulnar collateral ligament rupture","Thumb interphalangeal joint radial collateral ligament rupture"],"a":0,"e":"Ans. is ''a'' i.e., Thumb metacarpophalangeal joint ulnar collateral ligament rupture Injury to the thumb metacarpophalangeal joint ulnar collateral ligament is commonly referred to as gamekeeper thumb or skier''s thumb, although the original \"gamekeeper\" description (Campbell, 1955) referred to an attritional ulnar collat- eral ligament injury. Snow skiing accidents and falls on an outstretched hand with forceful radial and palmar abduction of the thumb are the usual causes.","pyqMatches":[{"year":"2013","no":1508,"q":"Game keepers thumb is ?","o":["Thumb metacarpophalangeal joint ulnar collateral ligament rupture","Thumb metacarpophalangeal joint radial collateral ligament rupture","Thumb interphalangeal joint ulnar collateral ligament rupture","Thumb interphalangeal joint radial collateral ligament rupture"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5178, 'Orthopedics', 'Pediatric Orthopedics', 'Easy', 'Orthopedics', 151, '{"id":5178,"subject":"Orthopedics","chapter":"Pediatric Orthopedics","difficulty":"Easy","source":"Orthopedics","sourceNo":151,"q":"Von-Rosen''s sign is positive in ?","o":["Perthe''s disease","SCFE","DDH","CTEV"],"a":2,"e":"Ans. is ''c'' i.e., DDH Radiological features of DDH/CDH In Von Rosen''s view following parameters should be noted .","pyqMatches":[{"year":"2013","no":1525,"q":"Von-Rosen''s sign is positive in ?","o":["Perthe''s disease","SCFE","DDH","CTEV"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5179, 'Orthopedics', 'Upper Limb', 'Moderate', 'Orthopedics', 152, '{"id":5179,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Moderate","source":"Orthopedics","sourceNo":152,"q":"Which of the following is not a diarthrosis ?","o":["Elbow joint","Interphalangeal joint","Skull sutures","Hip joint"],"a":2,"e":"Ans. is ''c'' i.e., Skull sutures Functional classification of joints (movement) Joints can also be classified functionally according to the type and degree of movement they allow:","pyqMatches":[{"year":"2013","no":1496,"q":"Which of the following is not a diarthrosis ?","o":["Elbow joint","Interphalangeal joint","Skull sutures","Hip joint"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5180, 'Orthopedics', 'Spine', 'Easy', 'Orthopedics', 153, '{"id":5180,"subject":"Orthopedics","chapter":"Spine","difficulty":"Easy","source":"Orthopedics","sourceNo":153,"q":"Block vertebrae are seen in ?","o":["Pagets disease","Leukemia","TB","Klippel - Feil syndrome"],"a":3,"e":"Ans. is i.e., Klippel - Feil syndrome A block vertebra is a type of vertebral anomaly where there is a failure of separation of two or more adjacent vertebral bodies Associations","pyqMatches":[{"year":"2013","no":1513,"q":"Block vertebrae are seen in ?","o":["Pagets disease","Leukemia","TB","Klippel - Feil syndrome"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5181, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 154, '{"id":5181,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":154,"q":"Bulge sign in knee joint is seen after how much fluid accumulation ?","o":["100m1","400m1","200m1","<30 ml"],"a":3,"e":"Ans. is i.e., < 30 ml The bulge test is used to determine the presence of fluid in the knee joint. It is useful when only a little fluid is present in the joint. The suprapatellar bursa is first emptied of fluid by squeezing distally from about 15 cm above the patella. The medial compartment of the knee join is emptied by pressing on the side of the joint with the free hand. The hand is then lifted away and then the lateral side is sharply compressed. If the test is positive, a ripple is seen on the flattened, medial surface. The test is negative if the effusion is tense - up to 120 ml. The bulge test is used to determine minimal fluid in the knee joint. It can detect as little as 4 - 6 ml of fluid in the knee joint.","pyqMatches":[{"year":"2013","no":1512,"q":"Bulge sign in knee joint is seen after how much fluid accumulation ?","o":["100m1","400m1","200m1","<30 ml"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5182, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 155, '{"id":5182,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":155,"q":"Splint used in CTEV after correction ?","o":["Bohler-Brown splint","Thomas splint","Dennis Brown splint","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., Dennis Brown splint Treatment of CTEV at birth Ideally treatment should be begun immediately after birth, certainly not more than 1 week later The principles of treatment are :-","pyqMatches":[{"year":"2013","no":1526,"q":"Splint used in CTEV after correction ?","o":["Bohler-Brown splint","Thomas splint","Dennis Brown splint","None of the above"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5183, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 156, '{"id":5183,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":156,"q":"Which of the following is least likely associated with vascular injury ?","o":["Fracture supracondylar femur","Fracture supracondylar humerus","Fracture shaft of femur","Fracture shiaft humerus"],"a":3,"e":"Ans. is ''d'' i.e., Fracture shaft humerus Vascular injury may be seen in -","pyqMatches":[{"year":"2013","no":1542,"q":"Which of the following is least likely associated with vascular injury ?","o":["Fracture supracondylar femur","Fracture supracondylar humerus","Fracture shaft of femur","Fracture shiaft humerus"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5184, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 157, '{"id":5184,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":157,"q":"Turn-buckle cast is used for ?","o":["Fracture shaft humerus","Fracture shaft femur","Scoliosis","Cervical spine injury"],"a":2,"e":"Ans. is ''c'' i.e., Scoliosis. Name of the case Use Minerva cast Cervical spine disease Risser''s cast Scoliosis Turn-buckle cast Scoliosis Shoulder spica Shoulder immobilisation U-slab Fracture of the humerus Hanging cast Fracture of the humerus Colle''s cast Colles'' fracture Hip spica Fracture of the femur Cylinder cast Fracture of the patella PTB cast Fracture of the tibia","pyqMatches":[{"year":"2013","no":1548,"q":"Turn-buckle cast is used for ?","o":["Fracture shaft humerus","Fracture shaft femur","Scoliosis","Cervical spine injury"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5185, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 158, '{"id":5185,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":158,"q":"Frozen pelvis is seen in ?","o":["Osteoarthritis","Potts disease","Actinomycosis","Reiters disease"],"a":1,"e":"Ans. is ''b'' i.e., Potts disease A term for significant involvement of the pelvic floor by malignancy, usually carcinoma, or ttuberculosis; in which there is massive extension of pathology to the urinary bladder, female genital tract, and sigmoid colon. Adequate resection of a frozen pelvis is virtually impossible; chemotherapy and radiation therapy are palliative at best.","pyqMatches":[{"year":"2013","no":1561,"q":"Frozen pelvis is seen in ?","o":["Osteoarthritis","Potts disease","Actinomycosis","Reiters disease"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5186, 'Orthopedics', 'Spine', 'Moderate', 'Orthopedics', 159, '{"id":5186,"subject":"Orthopedics","chapter":"Spine","difficulty":"Moderate","source":"Orthopedics","sourceNo":159,"q":"All are true about chronic osteomyelitis except ?","o":["Reactive new bone formation","Cloaca is an opening in involucrum","Involucrum is dead bone","Sequestrum is hard and porus"],"a":2,"e":"Ans. is ''c'' i.e., Involucrum is dead bone Pathology in chronic osteomyelitis Chronic osteomyelitis occurs most commonly in long bones. Bone is destroyed or devitalized in the affected part. Cavities containing pus and pieces of dead bone (sequestra) are surrounded by vascular tissue, and beyond that by areas of sclerosis due to reaction new bone formation, which may take the form of a distinct bony sheath (involucrum) Often sinus track leads to the skin surface; the sinus tends to heal and present down recurrently, but if a sequestrum is present it never heals permanently. This is because sequestra act as substrate for bacterial adhesion in much the same way as foreign implants, ensuring the persistence of infection until they are removed or discharged through perforations in the involucrum and sinuses that drain to the skin. Sequestrum Sequestrum is apiece of dead bone, surrounded by infected granulation tissue trying to eat the sequestrum away. The sequestrum is hard, rough, porus, light in weight and lighter in colour than normal. Normal pattern of bone is lost.(Note : Sequestrum in syphilis and TB is heavier than normal bone because sclerosis usually precedes the death of the bone). On x-ray, sequestra show up as unnatural dense fragments, in contrast to the surrounding osteopenic bone. Involucrum Involucrum is reactive new bone overlying a sequestrum. There may be some holes in the involucrum for pus to drain out. These holes are called cloaca.","pyqMatches":[{"year":"2013","no":1534,"q":"All are true about chronic osteomyelitis except ?","o":["Reactive new bone formation","Cloaca is an opening in involucrum","Involucrum is dead bone","Sequestrum is hard and porus"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5187, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 160, '{"id":5187,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":160,"q":"Ischial bursitis is also known as ?","o":["Clergyman''s knee","Housemaid''s knee","Weaver''s bottom","Students elbow"],"a":0,"e":"Ans. is ''c'' i.e., Weaver''s bottom Prepatellar bursitis Hr°,1semaid''s knee Infrapatellar bursitis Clergyman''s knee Olecranon bursitis Student''s elbow Ischia] bursitis Weaver''s bottom On lateral malleolus Tailor''s ankle On great toe Bunion","pyqMatches":[{"year":"2013","no":1546,"q":"Ischial bursitis is also known as ?","o":["Clergyman''s knee","Housemaid''s knee","Weaver''s bottom","Students elbow"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5188, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 161, '{"id":5188,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":161,"q":"Articular cartilage, true is ?","o":["Very vascular structure","Surrounded by thick perichondrium","Has no nerve supply","Fibrocartilage"],"a":2,"e":"Ans. is ''c'' i.e., Has no nerve supply Articular cartilage The articulating surfaces of a synovial joint are covered by articular cartilage. The articular cartilage has following features :-","pyqMatches":[{"year":"2013","no":1490,"q":"Articular cartilage, true is ?","o":["Very vascular structure","Surrounded by thick perichondrium","Has no nerve supply","Fibrocartilage"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5189, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 162, '{"id":5189,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":162,"q":"Essex lopresti lesion in upper limb-","o":["Injury to interosseous membrane","Radial head and DER fracture","Radial shaft","Radial shaft and radio-ulnar joint fracture"],"a":0,"e":"Ans. is ''a'' i.e., Injury to interosseous membrane The Esscx-Iopresti fracture is a fracture of the radial head with concomitant dislocation of the distal radio-ulnar joint with disruption of the interosseous membrane","pyqMatches":[{"year":"2013","no":1505,"q":"Essex lopresti lesion in upper limb","o":["Injury to interosseous membrane","Radial head and DER fracture","Radial shaft","Radial shaft and radio-ulnar joint fracture"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5190, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 163, '{"id":5190,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":163,"q":"Brodie''s abscess is ?","o":["Acute osteomyelitis","Subacute osteomyelitis","Chronic osteomyelitis","Septic arthritis"],"a":2,"e":"Brodie''s abscess is a sub-acute form of osteomyelitis, presenting as a collection of pus in bone, often with an insidious onset. Classically, this may present after progression to a draining abscess extending from the tibia out through the skin. Occasionally acute osteomyelitis may be contained to a localized area and walled off by fibrous and granulation tissue. This is termed Brodie''s abscess. Most frequent causative organism is Staphylococcus aureus. Usually occurs at the metaphysis of long bones. Distal tibia, proximal tibia, distal femur, proximal or distal fibula, and distal radius. Brodie''s abscess is best visualized using computed tomography (CT) scan. Associated atrophy of soft tissue near the site of infection and shortening of the affected bone. Osteoblastoma may be a classic sign for Brodie''s abscess. In the majority of cases, surgery has to be performed. If the cavity is small then surgical evacuation and curettage are performed under antibiotic cover. If the cavity is large then the abscess space may need packing with cancellous bone chips after evacuation.","pyqMatches":[{"year":"2013","no":1535,"q":"Brodie''s abscess is ?","o":["Acute osteomyelitis","Subacute osteomyelitis","Chronic osteomyelitis","Septic arthritis"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5191, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 164, '{"id":5191,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":164,"q":"Fracture of proximal forearm cast position is ?","o":["Pronated flexion","Neutral position","Supinated position","Position does not matter"],"a":2,"e":"Ans. is ''c'' i.e., Supinated position Fracture proximal third - supination of forearm Fracture middle third - mid pronation offorearm Fracture distal third - pronation offorearm","pyqMatches":[{"year":"2013","no":1504,"q":"Fracture of proximal forearm cast position is ?","o":["Pronated flexion","Neutral position","Supinated position","Position does not matter"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5192, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 165, '{"id":5192,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":165,"q":"Which of the following movements is restricted in Perthe''s disease -","o":["Adduction & external rotation","Abduction & external rotation","Adduction & internal rotation","Abduction & internal rotation"],"a":3,"e":"Ans. is.''d'' i.e., Abduction & internal rotation Clinical features of Perthes disease Perthes disease is common in male of age group 5-10 years. Pain in the hip, often radiating to knee. Limp (antalgic limp) Limitation of movement :- Abduction, internal rotation and extension are limited, therefore there is adduction, external rotation, and flexion deformity. Shortening of limb. Positive trendelenburg test. During the disease process, bone age is 1-3 years lower than the normal. After healing, bone age returns to normal.","pyqMatches":[{"year":"2013","no":1522,"q":"Which of the following movements is restricted in Perthe''s disease","o":["Adduction & external rotation","Abduction & external rotation","Adduction & internal rotation","Abduction & internal rotation"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5193, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 166, '{"id":5193,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":166,"q":"Windswept deformity in foot is seen in ?","o":["Rickets","RA","Hyperparathyroidism","Scurvy"],"a":1,"e":"Ans. is ''b'' i.e., RA Windswept deformity","pyqMatches":[{"year":"2013","no":1553,"q":"Windswept deformity in foot is seen in ?","o":["Rickets","RA","Hyperparathyroidism","Scurvy"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5194, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 167, '{"id":5194,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":167,"q":"True Supracondylar fracture of femur?","o":["Type A","Type B","Type C","Type D"],"a":0,"e":"Ans. is ''a'' i.e., Type A A useful classification is from the AO group: type A fractures have no articular splits and are truly ''supra- condylar''; type B fractures are simply shear fractures of one of the condyles; and type C fractures have supra- condylar and intercondylar fissures","pyqMatches":[{"year":"2013","no":1501,"q":"True Supracondylar fracture of femur?","o":["Type A","Type B","Type C","Type D"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5195, 'Orthopedics', 'Lower Limb', 'Moderate', 'Orthopedics', 168, '{"id":5195,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Moderate","source":"Orthopedics","sourceNo":168,"q":"All are true about menisci of knee joint except","o":["Lateral meniscus covers more articular surface of tibia-","Lateral meniscus is more mobile","Lateral meniscus is more prone to injury","Lateral meniscus is semicircular"],"a":2,"e":"Ans. is ''c'' i.e., Lateral meniscus is more prone to injury","pyqMatches":[{"year":"2015","no":1454,"q":"All are true about menisci of knee joint except","o":["Lateral meniscus covers more articular surface of tibia","Lateral meniscus is more mobile","Lateral meniscus is more prone to injury","Lateral meniscus is semicircular"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5196, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 169, '{"id":5196,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":169,"q":"Garden spade deformity is seen in ?","o":["Barton''s fracture","Colle''s fracture","Smith''s fracture","Bennet''s fracture"],"a":2,"e":"Ans. is ''c'' i.e., Smith''s fracture Smith fracture (Reverse colle''s fracture) It is a fracture of distal third of radius with palmar displacement. Hence, it is called as reverse colles fracture (In colles fracture there is dorsal displacement). It is less common than colles fracture and is caused by fall on the back of hand. The deformity is opposite to that of colle''s fracture and is called the ''garden spade deformity''. Treatment is closed reduction and immobilization in cast with forearm in supination and wrist in extension. o Percutaneous pinning may be done in unstable fractures.","pyqMatches":[{"year":"2013","no":1509,"q":"Garden spade deformity is seen in ?","o":["Barton''s fracture","Colle''s fracture","Smith''s fracture","Bennet''s fracture"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5197, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 170, '{"id":5197,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":170,"q":"Dignostic sign of a fracture-","o":["Abnormal mobility at fracture site","Pain at the fracture site","Tenderness","Swelling"],"a":0,"e":"Ans. is ''a'' i.e., Abnormal mobility at fracture site","pyqMatches":[{"year":"2013","no":1495,"q":"Dignostic sign of a fracture","o":["Abnormal mobility at fracture site","Pain at the fracture site","Tenderness","Swelling"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5198, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 171, '{"id":5198,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":171,"q":"Fracture neck femur cause of non- union?","o":["Injury to blood supply with shearing stress","Poor nutrition of the patient","Smoking","Old age and osteoporosis"],"a":0,"e":"Ans. is ''a'' i.e., Injury to blood supply with shearing stress Causes of non-union in fracture neck of femur are :?","pyqMatches":[{"year":"2013","no":1510,"q":"Fracture neck femur cause of non- union?","o":["Injury to blood supply with shearing stress","Poor nutrition of the patient","Smoking","Old age and osteoporosis"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5199, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 172, '{"id":5199,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":172,"q":"Exsanguinating blood loss in?","o":["Closed humerus fracture","Closed tibia fracture","Open femur fracture","Open humerus fracture"],"a":2,"e":"Ans. is ''c'' i.e., Open femur fracture Exsanguination is the process of blood loss, to a degree sufficient to cause death. Shaft femur fracture out of the above is associated with maximum blood loss and more blood loss is expected in cases of open fracture. Thus, the most probable answer is open fracture shaft femur. Two important fractures which can cause significant blood loss are -","pyqMatches":[{"year":"2013","no":1543,"q":"Exsanguinating blood loss in?","o":["Closed humerus fracture","Closed tibia fracture","Open femur fracture","Open humerus fracture"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5200, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 173, '{"id":5200,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":173,"q":"Which of the following is an orthopedic emergency?","o":["Intraarticular fracture","Septic arthritis","Fracture lateral condyle humerus","Fracture neck femur"],"a":1,"e":"Ans. is ''b'' i.e., Septic arthritis Timing of surgery Fracture surgery can be divided into emergency, urgency or elective. Emergency Emergency surgery is immediate for life and limb threatening problems. Examples are : -","pyqMatches":[{"year":"2013","no":1549,"q":"Which of the following is an orthopedic emergency?","o":["Intraarticular fracture","Septic arthritis","Fracture lateral condyle humerus","Fracture neck femur"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5201, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 174, '{"id":5201,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":174,"q":"Aeroplane splint is used in ?","o":["Radial nerve injury","Ulnar nerve injury","Brachial plexus injury","Scoliosis"],"a":2,"e":"Ans. is ''c'' i.e., Brachial plexus injury Name Use Cramer-wire splint Thomas splint Bohler-Braun splint Aluminium splint Dennis Brown splint Cock-up splint Knuckle-bender splint Toe-raising splint Volkmann''s splint Four-post collar Aeroplane splint SOMI brace ASHE (Anterior spinal hyperextension) Taylor''s brace Milwaukee brace Boston bracet Lumbar corset Emergency immobilisation Fracture femur-anywhere Fracture femur-anywhere Immobilization of fingers CIEV Radial nerve palsy Ulnar nerve palsy Foot drop Volkmann''s ischaemic contracture (VIC) Neck immbilisation Brachial plexus injury Cervical spine injury Dorso-lumbar spinal injury brace Dorso-lumbar immobilisation Scoliosis Scoliosis Backache","pyqMatches":[{"year":"2015","no":1443,"q":"Aeroplane splint is used in ?","o":["Radial nerve injury","Ulnar nerve injury","Brachial plexus injury","Scoliosis"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5202, 'Orthopedics', 'Bone Tumors', 'Easy', 'Orthopedics', 175, '{"id":5202,"subject":"Orthopedics","chapter":"Bone Tumors","difficulty":"Easy","source":"Orthopedics","sourceNo":175,"q":"Commonest malignant tumor of skeletal system ?","o":["Multiple myeloma","Metastasis","Osteosarcoma","Chondrosarcoma"],"a":1,"e":"Ans. is `b'' i.e., Metastasis Commonest bone malignancies →Secondaries Commonest primary malignant tumor → A- Multiple myeloma Commonest primary malignant tumor → Osteosarcoma of long bones Commonest benign tumor of bone - → Osteochondroma (Osteochondroma is not true neoplasm since its growth stops with cessation of growth at the epiphyseal plate) Commonest true benign tumor of bone → Osteoid osteoma Commonest benign tumor of hand → Enchondroma","pyqMatches":[{"year":"2013","no":1540,"q":"Commonest malignant tumor of skeletal system ?","o":["Multiple myeloma","Metastasis","Osteosarcoma","Chondrosarcoma"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5203, 'Orthopedics', 'Spine', 'Easy', 'Orthopedics', 176, '{"id":5203,"subject":"Orthopedics","chapter":"Spine","difficulty":"Easy","source":"Orthopedics","sourceNo":176,"q":"Poor prognostic indicator of Pott''s paraplegia","o":["Early onset","Active disease","Healed disease","Wet lesion"],"a":2,"e":"Ans. is ''c'' i.e., Healed disease Prognosis of Pott''s paraplegia Good Poor Degree Partial (only sensory or motor) Complete paraplegia (grade IV) Duration Shorter Longer (> 12 months) Type Early (acute) onset Late (chronic) onset Speed of onset Slow (insidious) Rapid (sudden) Age Younger Old General condition Good Poor Vertebral disease Active Healed Kyphotic deformity < 600 > 60° Cord on MRI Normal Myelomalacia or syringomyelia Preoperative Wet lesion Dry lesion","pyqMatches":[{"year":"2013","no":1536,"q":"Poor prognostic indicator of Pott''s paraplegia","o":["Early onset","Active disease","Healed disease","Wet lesion"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5204, 'Orthopedics', 'Spine', 'Easy', 'Orthopedics', 177, '{"id":5204,"subject":"Orthopedics","chapter":"Spine","difficulty":"Easy","source":"Orthopedics","sourceNo":177,"q":"Picture frame vertebra is seen in ?","o":["Paget''s disease","Osteopetrosis","Osteoporosis","Ankylosing spondylitis"],"a":0,"e":"Ans. is ''a'' i.e., Paget''s disease Radiological features of Paget''s disease Radiographic features depend on the stage of the disorder : ? A. In the early osteolytic phase Active bone resorption is evident as a radiolucent wedged area in long bones termed as ''candle flame'' or `blade of grass''. In the flat bones such as the calvarium or the iliac bone, purely osteolytic lesion is noted, known as osteoporosis circumscripta. B. Later phases of new bone formation Bone remodelling appears radiographically as thickening of the cortex, coarse trabeculation and enlargement or expansion of an entire bone or area of a long bone. Vertebral cortical thickening of the superior and inferior end plates creates a ''picture frame vertebra''. Diffuse radiodense enlargement of a vertebra is referred to as ''ivory vertebra''. Skull x-ray shows focal patchy densities-cotton ball appearance, which is quite characteristic of Paget disease. Pelvic radiograph demonstrate disruption of fusion of the saro-iliac joints and softening with protrusio acetabuli. Long bones reveal bowing deformities and typical pagetic changes of cortical thickening and expansion and areas of lucency and sclerosis.","pyqMatches":[{"year":"2013","no":1532,"q":"Picture frame vertebra is seen in ?","o":["Paget''s disease","Osteopetrosis","Osteoporosis","Ankylosing spondylitis"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5205, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 178, '{"id":5205,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":178,"q":"Barton''s fracture is ?","o":["Fracture distal end humerus","Extra-articular fracture distal end radius","Intra-articular fracture distal end radius","Intra-articular fracture distal end radius with carpal bone subluxation"],"a":0,"e":"Ans. is ''d'' i.e., Intra-articular fracture distal end radius with carpal bone subluxation Barton''s fracture Barton''s fracture is an intra-articular fracture of distal radius with subluxation of carpals. When carpals subluxation occurs anteriorly (volar), it is called volar Barton''s fracture. It is the commonest type. When carpals subluxate posteriorly (Dorsal), it is called Dorsal Barton''s fracture. The Barton''s fracture is difficult to manage by conservative methods : reduction is often imperfect and tends to be unstable, so that redisplacement often occurs. Therefore, often internal fixation by small buttress plating is recommended.","pyqMatches":[{"year":"2013","no":1506,"q":"Barton''s fracture is ?","o":["Fracture distal end humerus","Extra-articular fracture distal end radius","Intra-articular fracture distal end radius","Intra-articular fracture distal end radius with carpal bone subluxation"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5206, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 179, '{"id":5206,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":179,"q":"Short 4th metacarpal is a feature of","o":["Hyperparathyroidism","Hyperparathyroidism","Pseudohypoparathyroidism","Scleroderma"],"a":2,"e":"Ans. is `c'' i.e., Pseudohypoparathyroidism Short 41kmetacarpal/metatassal (metacarpal sign) Post - traumatic Post infection (from sickle cell anemia) Turner''s syndrome Pseudohypoparathyroidism Pseudopseudohypoparathyroidism Hereditary multiple exostosis Chondroectodermal dysplasia (Ellis-vanCreveld syndrome)","pyqMatches":[{"year":"2013","no":1560,"q":"Short 4th metacarpal is a feature of","o":["Hyperparathyroidism","Hyperparathyroidism","Pseudohypoparathyroidism","Scleroderma"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5207, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 180, '{"id":5207,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":180,"q":"Most common site of osteochondritis dessicans ?","o":["Lateral part of the medial femoral condyle","Medial part of the medial femoral condyle","Lateral part of the lateral femoral condyle","Medial part of the lateral femoral condyle"],"a":0,"e":"Ans. is ''a'' i.e., Lateral part of the medial femoral condyle Joint Site of osteochondritis dessicans Knee Lateral surface of the medial femoral condyle Elbow Capitulum of humerus Hip Femoral head Ankle Talus","pyqMatches":[{"year":"2013","no":1554,"q":"Most common site of osteochondritis dessicans ?","o":["Lateral part of the medial femoral condyle","Medial part of the medial femoral condyle","Lateral part of the lateral femoral condyle","Medial part of the lateral femoral condyle"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5208, 'Orthopedics', 'Bone Tumors', 'Moderate', 'Orthopedics', 181, '{"id":5208,"subject":"Orthopedics","chapter":"Bone Tumors","difficulty":"Moderate","source":"Orthopedics","sourceNo":181,"q":"All are common sites of primary for bone metastasis except","o":["Breast","Breast","Brain","Brain"],"a":2,"e":"Ans. is `c'' i.e., Brain Metastatic bone disease is the commonest malignancy of bones and is much more common than primary bone tumors. The commonest sites for bone metastases are vertebrae (most common), pelvis, the proximal half of the femur and the humerus. Extremities distal to elbow and knee are least commonly involved sites. Spread is usually via the blood stream; occasionally, visceral tumors spread directly into adjacent bones e.g., the pelvis and ribs. Certain tumors are known to be common sources of bone metastasis. The following primary tumors are the most common to metastasize in the bone; breast, prostate, lung, thyroid, kidney, and gastrointestinal tract. The commonest source of metastatic bone disease is carcinoma of the breast In males most common source is prostate carcinoma. Bladder and uterine carcinomas are less common sources. In children, skeletal metastases originate from neuroblastoma, Ewing''s sarcoma, and osteosarcoma.","pyqMatches":[{"year":"2013","no":1541,"q":"All are common sites of primary for bone metastasis except","o":["Breast","Breast","Brain","Brain"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5209, 'Orthopedics', 'Pediatric Orthopedics', 'Easy', 'Orthopedics', 182, '{"id":5209,"subject":"Orthopedics","chapter":"Pediatric Orthopedics","difficulty":"Easy","source":"Orthopedics","sourceNo":182,"q":"Madelung''s deformity involves -","o":["Humerus","Proximal ulna","Distal radius","Carpals"],"a":2,"e":"Ans. is ''c'' i.e., Distal radius Madelung''s deformity Madelung''s deformity is a congenital disorder that affects growth of distal radius. The primary defect is failure of normal growth of medial and palmar halves of the distal radial physis, leading to curvature in an medial (ulnar) and palmar direction. The ulna is relatively long and becomes prominent dorsally. The carpus (carpal bones) sinks, along with the medial (ulnar) half of the distal radial articular surface, into the gaps between the two forearm bones.","pyqMatches":[{"year":"2013","no":1507,"q":"Madelung''s deformity involves","o":["Humerus","Proximal ulna","Distal radius","Carpals"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5210, 'Orthopedics', 'Spine', 'Easy', 'Orthopedics', 183, '{"id":5210,"subject":"Orthopedics","chapter":"Spine","difficulty":"Easy","source":"Orthopedics","sourceNo":183,"q":"Common causes of vertebra plana","o":["TB","Eosinophilic granuloma","Metastasis","All of the above"],"a":0,"e":"Ans. is ''d'' i.e., All of the above Vertebra plana This term is used to describe uniform collapse of a vertebral body into a thin, flat disc. The most common cause is eosinophilic granuloma, with the thoracic vertebrae most frequently affected. Causes are :?","pyqMatches":[{"year":"2013","no":1514,"q":"Common causes of vertebra plana","o":["TB","Eosinophilic granuloma","Metastasis","All of the above"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5211, 'Orthopedics', 'Spine', 'Moderate', 'Orthopedics', 184, '{"id":5211,"subject":"Orthopedics","chapter":"Spine","difficulty":"Moderate","source":"Orthopedics","sourceNo":184,"q":"DISC prolapse is common at all site except ?","o":["L4 - L5","L5 - S1","C6 - C7","T3 - T4"],"a":3,"e":"Ans. is ''d'' i.e., T3 - T4 Herniation of intervertebral disc is a common cause of combined back pain and sciatica (Pain in back with radiation to lower limb). Prolapsed intervertebral disc is often precipitated by injury, but it may also occur in the absence of any remembered injury. The disc between Lc and Sp and between L4 and L5 are those most often affected (80%). Lower cervical region (C''s - C6 and C6_7) is affected in 19-20%.","pyqMatches":[{"year":"2013","no":1515,"q":"DISC prolapse is common at all site except ?","o":["L4 - L5","L5 - S1","C6 - C7","T3 - T4"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5212, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 185, '{"id":5212,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":185,"q":"Aspirated synovial fluid in septic arthritis will have?","o":["Clear color","High viscosity","Markedly increased polymorphonuclear leukocytes","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., Markedly increased polymorphonuclear leukocytes Appearance- Purulent Clarity- Opaque Viscocity- Decreased Cell count- > 80000 (> 80% PMNs) Example- Bacterial arthritis","pyqMatches":[{"year":"2013","no":1537,"q":"Aspirated synovial fluid in septic arthritis will have?","o":["Clear color","High viscosity","Markedly increased polymorphonuclear leukocytes","None of the above"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5213, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 186, '{"id":5213,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":186,"q":"Which can cause loose body in the joint -","o":["RA","Ankylosing spondylitis","OA","SLE"],"a":2,"e":"Ans. is ''c'' i.e., OA Causes of loose bodies include :-","pyqMatches":[{"year":"2013","no":1555,"q":"Which can cause loose body in the joint","o":["RA","Ankylosing spondylitis","OA","SLE"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5214, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 187, '{"id":5214,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":187,"q":"Salter''s pelvic osteotomy is done for treatment of ?","o":["CTEV","SCFE","DDH","None"],"a":2,"e":"Ans. is ''c'' i.e., DDH Treatment of CDH/DDH The aim of treatment in DDH is to achieve and maintain an early concentric reduction and maintain it until the hip becomes clinically stable and a round acetabulum cover it. Treatment plan is according to the age :?","pyqMatches":[{"year":"2013","no":1527,"q":"Salter''s pelvic osteotomy is done for treatment of ?","o":["CTEV","SCFE","DDH","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5215, 'Orthopedics', 'Spine', 'Moderate', 'Orthopedics', 188, '{"id":5215,"subject":"Orthopedics","chapter":"Spine","difficulty":"Moderate","source":"Orthopedics","sourceNo":188,"q":"All are features of Paget''s disease except ?","o":["Defect in osteoclasts","Common in female","Can cause deafness","Can cause osteosarcoma"],"a":1,"e":"Ans. is ''b'' i.e., Common in female Paget disease Paget''s disease is characterized by increased bone turnover and enlargement and thickening of the bone, but the internal architecture is abnormal and the bone is usually brittle. Primary defect is in osteoclasts with increased osteoclastic activity. This results secondarily increase in osteoblastic activity (normal osteoclasts and osteoblasts act in a co-ordinated manner). So, characteristic cellular change is a marked increase in osteoclastic and osteoblastic activity. Bone turnover is acclerated, plasma alkaline phosphatase is raised (a sign of osteoblastic activity) and there is increased excretion of hydroxyproline in urine (due to osteoclastic activity). Clinical features of Paget''s disease Paget''s disease is slightly more common in males and is seen after 40 years of age. The pelvis and tibia being the commonest sites, and femur, skull, spine (vertebrae) and clavicle the next commonest o Most of the patient with Paget''s disease are asymptomatic, the disorder being diagnosed when an x-ray is taken for some unrelated condition or after the incidental discovery of raised serum alkaline phosphatase. When patients does present, they present because any of the three : -","pyqMatches":[{"year":"2013","no":1533,"q":"All are features of Paget''s disease except ?","o":["Defect in osteoclasts","Common in female","Can cause deafness","Can cause osteosarcoma"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5216, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 189, '{"id":5216,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":189,"q":"Deformity in transient synovitis of Hip ?","o":["Abduction","Flexion","External rotation","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above Transient synovitis of Hip Transient synovitis of hip is also known as observation hip, toxic synovitis or irritable hip. Its a self-limiting, inflammatory condition of the synovium, that lasts only a short time (therefore known as transient) It is the most common cause of hip pain and limp in children under 10 yrs of age. Cause is not known but association has been seen with a recent history of an upper respiratory tract infection. Presentation is with hip pain or limp. The limb is in attitude of slight flexion, abduction and external rotation. The child may have low grade fever. The ESR, C-Reactive protein & WBCs count are normal (This differentiates Transient synovitis from Septic arthiritis a serious condition, in which patient has high grade fever and elevated ESR, C-Reactive protein and WBC count). Radiograph or ultrasound may show widening of the joint space However, most of the time x-ray is normal. Usually the treatment of a clinically suspected case of transient synovitis of hip is Bed rest, NSAIDS and observation. USG guided aspiration is indicated for :-","pyqMatches":[{"year":"2013","no":1529,"q":"Deformity in transient synovitis of Hip ?","o":["Abduction","Flexion","External rotation","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5217, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 190, '{"id":5217,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":190,"q":"Rocker bottom foot is due to ?","o":["Overtreatment of CTEV","Malunited fracture calcaneum","Horizontal talus","Neural tube defect"],"a":0,"e":"Ans. is ''a'' i.e., Overtreatment of CTEV Rocker bottom foot Rocker bottom foot is a foot with a convex plantar surface with an apex of convexity at the talar head (normal plantar surface is concave). Causes of Rocker Bottom foot are :-","pyqMatches":[{"year":"2013","no":1528,"q":"Rocker bottom foot is due to ?","o":["Overtreatment of CTEV","Malunited fracture calcaneum","Horizontal talus","Neural tube defect"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5218, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 191, '{"id":5218,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":191,"q":"Hangman''s fracture is ?","o":["Subluxation of C5 over C6","Fracture dislocation of C2","Fracture dislocation of ankle joint","Fracture of odontoid"],"a":1,"e":"Ans. is ''b'' i.e., Fracture dislocation of C2 Hangman''s fracture Hangman''s fracture is bilateral fracture of the pars interarticularis of axis (C2) with traumatic spondylolisthesis of axis (C2) over C3 vertebrae. Thus Hangman''s fracture is not simply a fracture, but fracture dislocation of axis (C2). The mechanism of injury is extension with distraction (in true, judicial hangman''s fracture) and hyper-extension, axial compression &. flexion (in civilian injuries, which are now more common). It is second most common type of Axis (C2) fracture, second only to odontoid fractures. Fatalaties are common, However, neurological deficit is unusual as the fracture of posterior arch decompress the spinal cord. Most of the fatalities occur at the scene of injury, acute post admission mortality is low. Successful healing of C2 traumatic spondylolishesis is reported to approach 95%. This is most commonly achieved with non-operative measures, even in the presence of displacement of pars inter- articularis. Undisplaced fractures are treated in a semi-rigid orthosis, and displaced fracture are closed reduced & treated with halo-vest. Occasionally, the hangman''s fracture is associated with a C2/3 facet dislocation. This is a severely unstable injury; open reduction and stabilization is required.","pyqMatches":[{"year":"2013","no":1516,"q":"Hangman''s fracture is ?","o":["Subluxation of C5 over C6","Fracture dislocation of C2","Fracture dislocation of ankle joint","Fracture of odontoid"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5219, 'Orthopedics', 'Spine', 'Easy', 'Orthopedics', 192, '{"id":5219,"subject":"Orthopedics","chapter":"Spine","difficulty":"Easy","source":"Orthopedics","sourceNo":192,"q":"Most common cause of kyphotic deformity ?","o":["Trauma","Osteoporosis","Ankylosing spondylitis","Rickets"],"a":1,"e":"Ans. is ''b'' i.e., Osteoporosis Kvphosis Kyphotic deformities are characterized by on increased dorsal curvature in the sagittal plane of spinal alignment. Postural kyphosis (Postural round back) and scheuermann''s disease are the most common causes of kyphosis, particularly in adolescents. Most common cause in older persons is osteoporosis. Other common causes are tuberculosis of the vertebral bodies, ankylosing spondylitis, rickets, cancers and spina bifida. There are three types of kyphotic deformities :","pyqMatches":[{"year":"2013","no":1517,"q":"Most common cause of kyphotic deformity ?","o":["Trauma","Osteoporosis","Ankylosing spondylitis","Rickets"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5220, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 193, '{"id":5220,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":193,"q":"Saturday night palsy is which type of nerve injury?","o":["Neuropraxia","Axonotemesis","Neurotemesis","Complete section"],"a":0,"e":"Ans. is ''a'' i.e., Neuropraxia Seddon''s classification of nerve injuries Seddon identified three types of injuries","pyqMatches":[{"year":"2013","no":1521,"q":"Saturday night palsy is which type of nerve injury?","o":["Neuropraxia","Axonotemesis","Neurotemesis","Complete section"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5221, 'Orthopedics', 'Trauma & Fractures', 'Moderate', 'Orthopedics', 194, '{"id":5221,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Moderate","source":"Orthopedics","sourceNo":194,"q":"Common fractures in children are all except ?","o":["Lacteral condyle humerus","Supracondylar humerus","Fracture of hand","Radius-ulna fracture"],"a":2,"e":"Ans. is ''c'' i.e., Fracture of hand Common fractures in children","pyqMatches":[{"year":"2013","no":1530,"q":"Common fractures in children are all except ?","o":["Lacteral condyle humerus","Supracondylar humerus","Fracture of hand","Radius-ulna fracture"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5222, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 195, '{"id":5222,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":195,"q":"Most common site of myositis ossificans ?","o":["Knee","Elbow","Shoulder","Wrist"],"a":1,"e":"Ans. is ''b'' i.e., Elbow Myositis ossificans is the extraskeletal hetrotropic ossification that occurs in muscles and other soft tissues. Trauma is the most important cause of myositis ossificans. Usually there is history of severe single injury. It is more common in children. Most commonly involved joint is elbow followed by hip. There is history of trauma around the elbow, i.e. fracture supracondylar humerus, dislocation of elbow or surgery with extensive periosteal stripping. Massage to the elbow and vigorous passive stretching to restore movements are aggravating factor. It occurs in muscles which are vulnerable to tear under heavy loads, such as quadriceps, adductors, brachicilis, biceps, and deltoid. X-ray finding is characteristic and shows distinct peripheral margin of mature ossification and a radiolucent center of immature osteoid & primitive mesenchymal tissue","pyqMatches":[{"year":"2013","no":1547,"q":"Most common site of myositis ossificans ?","o":["Knee","Elbow","Shoulder","Wrist"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5223, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 196, '{"id":5223,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":196,"q":"Thurston Holland sign is seen in ?","o":["Type I","Type II","Type III","Type IV"],"a":1,"e":"Ans. is ''b'' i.e., Type II Epiphyseal (Physeall Injuries o The junction between the metaphysis and epiphysis, i.e. physeal plate/growth plate, is the weakest point of a long bone in children and is, therefore, most vulnerable to shearing forces. o Salter and Harris have classified epiphyseal injuries into five types ? Type I : Complete separation of epiphysis from the metaphysis without fracture. Common in rickets, scurvy and osteomyelitis. Type II: The fracture involves the physis and a triangle of metaphyseal bone (Thurston Holland sign).This is the commonest type of epiphyseal injury accounting for 73 percent of cases over 10 years of age. Type III: The fracture is intra- articular and extends along the physis and then along the growth plate. This injury is relatively uncommon. Type IV: The fracture is intra- articular and extends through the epiphysis, physis and metaphysis. Perfect reduction is necessary and open reduction is more often necessary to prevent growth arrest. Type V : Crushing of epiphysis. Growth arrest usually follows. Type VI (Rang''s type) : There is a peripheral physis (perichondrial ring) injury.","pyqMatches":[{"year":"2013","no":1531,"q":"Thurston Holland sign is seen in ?","o":["Type I","Type II","Type III","Type IV"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5224, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 197, '{"id":5224,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":197,"q":"Which part of scaphoid fracture is most susceptible to avascular necrosis?","o":["Distal 1/3rd","Middle 1/3rd","Proximal 1/3rd","Scaphoid Tubercle"],"a":2,"e":"Answer. C. Proximal 1/3rd Scaphoid fractures (i.e. fractures through the scaphoid bone) are common, in some instances can be difficult to diagnose, and can result in significant functional impairment. Epidemiology Scaphoid fractures account for 70-80% of all carpal bone fractures. Although they occur essentially at any age, adolescents and young adults are most commonly affected. Older patients falling in a similar manner are more likely to sustain a distal radial fracture (usually a Colles fracture). Clinical Presentation Classically there can be pain in anatomical snuffbox which is thought to have a sensitivity of ~90% and a specificity ~40% Fractures can occur essentially anywhere along the scaphoid, but distribution is not even:","pyqMatches":[{"year":"2019","no":194,"q":"Which part of scaphoid fracture is most susceptible to avascular necrosis?","o":["Distal 1/3rd","Middle 1/3rd","Proximal 1/3rd","Scaphoid Tubercle"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5225, 'Orthopedics', 'Bone Tumors', 'Easy', 'Orthopedics', 198, '{"id":5225,"subject":"Orthopedics","chapter":"Bone Tumors","difficulty":"Easy","source":"Orthopedics","sourceNo":198,"q":"Pott’s puffy tumor:","o":["Subperiosteal abscess of frontal bone","Subperiosteal abscess of ethmoid bone","Mucocele of frontal bone","Mucocele of ethmoid bone"],"a":0,"e":"Answer. A. Subperiosteal abscess of frontal bone Pott’s puffy tumor, first described by Sir Percivall Pott in 1760, is a rare clinical entity characterized by subperiosteal abscess associated with osteomyelitis. It is characterized by an osteomyelitis of the frontal bone, either direct or through haematogenous spread. This results in a swelling on the forehead, hence the name. The infection can also spread inwards, leading to an intracranial abscess. Pott’s puffy tumor can be associated with cortical vein thrombosis, epidural abscess, subdural empyema, and brain abscess.","pyqMatches":[{"year":"2019","no":195,"q":"Pott’s puffy tumor:","o":["Subperiosteal abscess of frontal bone","Subperiosteal abscess of ethmoid bone","Mucocele of frontal bone","Mucocele of ethmoid bone"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5226, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 199, '{"id":5226,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":199,"q":"Scissor gait is seen in which of the following condition:","o":["Polio","Cerebral palsy","Hyperbilirubinemia","Hyponatremia"],"a":1,"e":"Answer. B. Cerebral palsy Scissor gait is a form of gait abnormality primarily associated with spastic cerebral palsy. That condition and others like it are associated with an upper motor neuron lesion.","pyqMatches":[{"year":"2019","no":196,"q":"Scissor gait is seen in which of the following condition:","o":["Polio","Cerebral palsy","Hyperbilirubinemia","Hyponatremia"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5227, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 200, '{"id":5227,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":200,"q":"Most common joint involved in septic arthritis:","o":["Knee","Hip","Shoulder","Elbow"],"a":0,"e":"Answer. A. Knee Septic arthritis (Acute suppurative arthritis) Septic arthritis refers to pyogenic infection of a joint, i.e., infection of a joint by pyogenic organism (bacteria). The joint can become infected by : –","pyqMatches":[{"year":"2019","no":201,"q":"Most common joint involved in septic arthritis:","o":["Knee","Hip","Shoulder","Elbow"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5228, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 201, '{"id":5228,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":201,"q":"Painful arc syndrome pain is felt during ?","o":["Mid abduction","Initial abduction","Full range of abduction","Overhead abduction"],"a":0,"e":"Answer. A. Mid abduction PAINFUL ARC SYNDROME Other Names Impingement syndrome Supraspinatus syndrome Swimmer’s syndrome Thrower’s shoulder Clinical syndrome characterized by pain in the shoulder during an arc of movement between 60° and 120° of abduction. Etiology:","pyqMatches":[{"year":"2019","no":202,"q":"Painful arc syndrome pain is felt during ?","o":["Mid abduction","Initial abduction","Full range of abduction","Overhead abduction"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5229, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 202, '{"id":5229,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":202,"q":"True about Tenosynovitis of finger ?","o":["Fingers held in mild extension / Extension deformity at the involved fingers.","Tenosynovitis of little finger will spread to thumb rather than ring finger.","With involvement of little finger the infection can spread to the index finger.","Treatment is conservative."],"a":1,"e":"Ans. B. Tenosynovitis of little finger will spread to thumb rather than ring finger Infection of the synovial sheath that surrounds the flexor tendon Infection from the flexor tendon sheath of the thumb can also extend along the radial bursa to the space of Parona and then into the ulnar bursa and the flexor tendon sheath of the little finger—and vice versa—leading to a “horseshoe” abscess. Horseshoe abscess: May develop from spread pyogenic flexor tenosynovitis, of many individuals have a connection between the sheaths of the thumb and little fingers at the level of the wrist","pyqMatches":[{"year":"2019","no":200,"q":"True about Tenosynovitis of finger ?","o":["Fingers held in mild extension / Extension deformity at the involved fingers.","Tenosynovitis of little finger will spread to thumb rather than ring finger.","With involvement of little finger the infection can spread to the index finger.","Treatment is conservative."],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5230, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 203, '{"id":5230,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":203,"q":"The last deformity to be corrected by Ponseti''s method for CTEV is -","o":["Heel Varus","Equinus","Foot Adduction","Cavus"],"a":1,"e":"Answer- B. Equinus Ponseti''s technique This involves first correcting the cavus deformiry then the adductionand heel varus andfinally the equinus deformity. This technique is now mostly accepted technique for CTEV correction as it is based on better understanding ofthe pathoanatomy ofthe deformed foot. The success ofreduction is 90-98 Percent.","pyqMatches":[{"year":"2016","no":1458,"q":"The last deformity to be corrected by Ponseti''s method for CTEV is","o":["Heel Varus","Equinus","Foot Adduction","Cavus"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5231, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 204, '{"id":5231,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":204,"q":"Ossification centre of scaphoid appears at","o":["1-6 months","1 to 2 years","2 to 4 years","4 to 6 years"],"a":3,"e":"Answer- D. 4 to 6 years","pyqMatches":[{"year":"2016","no":629,"q":"Ossification centre of scaphoid appears at","o":["1-6 months","1 to 2 years","2 to 4 years","4 to 6 years"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5232, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 205, '{"id":5232,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":205,"q":"Which of the following is the most metabolically active part of long bone?","o":["Epiphysis","Metaphysis","Diaphysis","Physis"],"a":3,"e":"Answer- D. Physis The growth plate (physis) and the adjacent terminal diaphysis represent the most metabolically active segment of the long bone. This part changes dramatically during development and hence it is called the metaphysis","pyqMatches":[{"year":"2016","no":1426,"q":"Which of the following is the most metabolically active part of long bone?","o":["Epiphysis","Metaphysis","Diaphysis","Physis"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5233, 'Orthopedics', 'Lower Limb', 'Hard', 'Orthopedics', 206, '{"id":5233,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Hard","source":"Orthopedics","sourceNo":206,"q":"Iliotibial band contracture in patients of poliomyelitis will lead to","o":["Flexion at hip and knee","Flexion at hip, extention at knee","Extention at hip flexion at knee","Extention at hip and knee"],"a":0,"e":"Answer- A. Flexion at hip and knee Deformities: Iliotibial band contracture can lead to : Flexion, abduction and external rotation deformity at hip (most common). Flexon and valgus at lcnee or sometimes triple deformity at knee (flexion, posterior subluxation and external routation of tibia on femur). Equinovarus at ankle and foot. Lumbar scoliosis and pelvic obliquity at spine and pelvis respectively.","pyqMatches":[{"year":"2016","no":1427,"q":"Iliotibial band contracture in patients of poliomyelitis will lead to","o":["Flexion at hip and knee","Flexion at hip, extention at knee","Extention at hip flexion at knee","Extention at hip and knee"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5234, 'Orthopedics', 'Trauma & Fractures', 'Hard', 'Orthopedics', 207, '{"id":5234,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Hard","source":"Orthopedics","sourceNo":207,"q":"Management of displaced non comminuted intercondylar humerus fracture is -","o":["Open reduction internal fixation","Above elbow plaster slab application","Olecranon pin traction","External fixation"],"a":0,"e":"Answer- A. Open reduction internal fixation It depends upon the displacement. An undisplaced fracture needs support in an above-elbow plaster slab for 3-4 weeks, followed by exercises. A displaced fracture is treated generally by open reduction and internal fixation. In cases with severe comminution, olecranon pin traction is given to reduce the fracture and maintain the reduction.","pyqMatches":[{"year":"2016","no":1491,"q":"Management of displaced non comminuted intercondylar humerus fracture is","o":["Open reduction internal fixation","Above elbow plaster slab application","Olecranon pin traction","External fixation"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5235, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 208, '{"id":5235,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":208,"q":"Jumpers knee","o":["Apophysitis of patellar tendon as it inserts in patella","Apophysitis of patellar tendon as it inserts in tibia","Apophysitis of quadriceps tendon as it inserts in patella","Apophysitis of hamstring tendon as it inserts in tibia"],"a":0,"e":"Answer- A. Apophysitis of patellar tendon as it inserts in patella It is also called Patellar tendinitis This is an apophysitis (inflammation) of the patellar tendon as it inserts into the patella. It is associated with pain, swelling and crepitus.","pyqMatches":[{"year":"2016","no":1428,"q":"Jumpers knee","o":["Apophysitis of patellar tendon as it inserts in patella","Apophysitis of patellar tendon as it inserts in tibia","Apophysitis of quadriceps tendon as it inserts in patella","Apophysitis of hamstring tendon as it inserts in tibia"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5236, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 209, '{"id":5236,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":209,"q":"Proximal tibial epiphysis fuses at -","o":["12 - 14 years","14 - 16 years","16 - 18 years","18 - 20 years"],"a":2,"e":"Answer- C. 16 - 18 years The tibia ossifies from three centres, one in the shaft and one in each epiphysis. Ossification begins in midshaft at about the seventh intrauterine week. The proximal epiphysial centre is usually present at birth: at approximately 10 years a thin anterior process from the centre descends to form the smooth part of the tibial tuberosity.","pyqMatches":[{"year":"2016","no":1490,"q":"Proximal tibial epiphysis fuses at","o":["12 - 14 years","14 - 16 years","16 - 18 years","18 - 20 years"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5237, 'Orthopedics', 'Trauma & Fractures', 'Hard', 'Orthopedics', 210, '{"id":5237,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Hard","source":"Orthopedics","sourceNo":210,"q":"What is the treatment for patient with hypertrophic nonunion with deformity at fracture site?","o":["No treatment required","Fixation only","Bone grafting only","Fixation with bone grafting"],"a":1,"e":"Answer- B. Fixation only Patients with hypertrophic nonunion have sufficient vascularity to heal but stability is lacking or normal axial alignment has not been restored. Thus in a case of hypertrophic nonunion without deformity, fixation alone will provide stability and will lead to healing.","pyqMatches":[{"year":"2016","no":1489,"q":"What is the treatment for patient with hypertrophic nonunion with deformity at fracture site?","o":["No treatment required","Fixation only","Bone grafting only","Fixation with bone grafting"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5238, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 211, '{"id":5238,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":211,"q":"Chauffeur fracture is -","o":["Extra - articular fracture of styloid process","Intra - articular fracture of styloid process","Intra - articular fracture of base of 1st metacarpal","Extra - articular fracture of base of 1st metacarpal"],"a":1,"e":"Answer- B. Intra - articular fracture of styloid process An intra-articular oblique fracture of the styloid process of the radius.","pyqMatches":[{"year":"2016","no":1487,"q":"Chauffeur fracture is","o":["Extra - articular fracture of styloid process","Intra - articular fracture of styloid process","Intra - articular fracture of base of 1st metacarpal","Extra - articular fracture of base of 1st metacarpal"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5239, 'Orthopedics', 'Trauma & Fractures', 'Moderate', 'Orthopedics', 212, '{"id":5239,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Moderate","source":"Orthopedics","sourceNo":212,"q":"Which of the following is not true about Galeazzi fracture dislocation?","o":["Fracture of distal third of radius and dislocation of distal radio- ulnar joint","Results from fall on outstretched hand","The distal end of ulna dislocates volarly after disruption of distal radio - ulnar joint","Radius is angulated medially and anteriorly"],"a":2,"e":"Answer- C. The distal end of ulna dislocates volarly after disruption of distal radio - ulnar joint Fracture of the distal third of the radius with dislocation of the distal radioulnar joint This injury is the counterpart of the Monteggia fracture-dislocation. It commonly results from a fall on an out stretched hand. The radius fracture is angulated medially and anteriorly. The distal radioulnar joint is disrupted, resulting in dorsal dislocation of the distal end of the ulna Malunion occurs because of displacement of the fragment. It results in deformity and limitation of supination and pronation.","pyqMatches":[{"year":"2016","no":1429,"q":"Which of the following is not true about Galeazzi fracture dislocation?","o":["Fracture of distal third of radius and dislocation of distal radio- ulnar joint","Results from fall on outstretched hand","The distal end of ulna dislocates volarly after disruption of distal radio - ulnar joint","Radius is angulated medially and anteriorly"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5240, 'Orthopedics', 'Spine', 'Moderate', 'Orthopedics', 213, '{"id":5240,"subject":"Orthopedics","chapter":"Spine","difficulty":"Moderate","source":"Orthopedics","sourceNo":213,"q":"Which of the following is not true about Jeffersons fracture?","o":["It is a burst fracture of the ring of atlas vertebra","It is the most common type of atlas fracture","Fracture definintion is particularly clear on CT Scan image","It is associated with injury elsewhere in spine in 25% of the cases"],"a":3,"e":"Answer- D. It is associated with injury elsewhere in spine in 25% of the cases Sudden severe load on the top of the head may cause a ''bursting'' force which fractures the ring of the atlas (Jefferson''s fracture). Thus it is a type of axial compression force. It is the most common type of fracture of the Atlas. There is no encroachment on the neural canal and usually no neurological damage. With the exception of pain or loss of sensation in the greater occipital nerve distribution, neurological sequelae are uncommon and more likely to be related to associated injuries. Fracture of atlas are associated with injury elsewhere in cervical spine in upto 50% of cases; odontoid fractures and hangman''s fracture in particular should be excluded","pyqMatches":[{"year":"2016","no":1431,"q":"Which of the following is not true about Jeffersons fracture?","o":["It is a burst fracture of the ring of atlas vertebra","It is the most common type of atlas fracture","Fracture definintion is particularly clear on CT Scan image","It is associated with injury elsewhere in spine in 25% of the cases"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5241, 'Orthopedics', 'Upper Limb', 'Hard', 'Orthopedics', 214, '{"id":5241,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Hard","source":"Orthopedics","sourceNo":214,"q":"Which of the following shoulder movements is/ are weak in patients of supraspinatus tear?","o":["Abduction","Adduction","External rotation","Internal rotation"],"a":0,"e":"Answer- A. Abduction Patients may tear the supraspinatus tendon acutely by falling on an outstretched arm or lifting a heavy object. Symptoms are pain along with weakness of abduction and external rotation of the shoulder. Atrophy of the supraspinatus muscles develops.","pyqMatches":[{"year":"2016","no":1432,"q":"Which of the following shoulder movements is/ are weak in patients of supraspinatus tear?","o":["Abduction","Adduction","External rotation","Internal rotation"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5242, 'Orthopedics', 'Spine', 'Easy', 'Orthopedics', 215, '{"id":5242,"subject":"Orthopedics","chapter":"Spine","difficulty":"Easy","source":"Orthopedics","sourceNo":215,"q":"Most mobile segment of vertebral column is -","o":["Cervical","Thoracic","Lumbar","Sacral"],"a":0,"e":"Answer- A. Cervical The spinal column can be divided into three mobile (cervical, thoracic, and lumbar regions) and two fused (sacrum and coccyx). Cervical region: It is the most mobile region of the spinal column with range of motion of approximately 80 - 90 degrees of flexion, 70 degrees of extention, 20 - 45 degrees of lateral flexion, and upto 90 degrees of rotation to both sides","pyqMatches":[{"year":"2016","no":1486,"q":"Most mobile segment of vertebral column is","o":["Cervical","Thoracic","Lumbar","Sacral"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5243, 'Orthopedics', 'Upper Limb', 'Moderate', 'Orthopedics', 216, '{"id":5243,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Moderate","source":"Orthopedics","sourceNo":216,"q":"Which of the following is not true about impingement syndrome?","o":["It is the tendinitis caused by inflammation of the rotator cuff tendons","Supraspinatus tendon is most often involved","Shoulder abduction in the arc of 60 - 120 degrees is particularly painful","Surgical decompression of the subacromial space is frequently indicated"],"a":3,"e":"Answer- D. Surgical decompression of the subacromial space is frequently indicated Impingement syndrome (painful are syndrome) is most commonly due tendinits of supraspinatus component of rotator cuff and is characterized by pain in 60°- 120\" of abduction. Treatment is initialy conservative. Surgical decompression is required in failed cases.","pyqMatches":[{"year":"2016","no":1433,"q":"Which of the following is not true about impingement syndrome?","o":["It is the tendinitis caused by inflammation of the rotator cuff tendons","Supraspinatus tendon is most often involved","Shoulder abduction in the arc of 60 - 120 degrees is particularly painful","Surgical decompression of the subacromial space is frequently indicated"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5244, 'Orthopedics', 'Trauma & Fractures', 'Hard', 'Orthopedics', 217, '{"id":5244,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Hard","source":"Orthopedics","sourceNo":217,"q":"Most dangerous type of odontoid fracture as per Anderson and D'' Alonzo classification and its respective management is","o":["Type I - immobilization in rigid collar","Type II - screw fixation","Type III - halo vest immmobilization","Type IV - ope reduction internal fixation"],"a":1,"e":"Answer- B. Type II - screw fixation Odontoid fractures have been classified by Anderson and D''Alonzo (1974) as follows:","pyqMatches":[{"year":"2016","no":1435,"q":"Most dangerous type of odontoid fracture as per Anderson and D'' Alonzo classification and its respective management is","o":["Type I - immobilization in rigid collar","Type II - screw fixation","Type III - halo vest immmobilization","Type IV - ope reduction internal fixation"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5245, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 218, '{"id":5245,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":218,"q":"Increased Q angle predisposes to","o":["Medial patellar subluxation","Lateral patellar subluxation","Superior patellar subluxation","Inferior patellar subluxation"],"a":1,"e":"Answer- B. Lateral patellar subluxation Patellar alignment can be assessed by measuring the Q-angle (quadriceps angle). This is the angle subtended by a line drawn from the anterior superior iliac spine to the centre of the patella and another from the centre of the patella to the tibial tubercle. It normally averages about 14 degrees in men and 17 degrees in women. Patellofemoral stability is maintained by a combination of the articular surface geometry and soft tissue restraints.","pyqMatches":[{"year":"2016","no":1436,"q":"Increased Q angle predisposes to","o":["Medial patellar subluxation","Lateral patellar subluxation","Superior patellar subluxation","Inferior patellar subluxation"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5246, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 219, '{"id":5246,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":219,"q":"False about osteogenesis imperfecta is -","o":["Defective collagen formation","Associated with cataract formation","Autosomal dominant","Known as Brittle bone disease"],"a":1,"e":"Answer- B. Associated with cataract formation Osteogenesis imperfecta, also known as brittle bone disease or Lobstein syndrome, is a hereditary condition characterized by fragility of bones, deafness, blue sclera, laxity of joints and tendency to improve with age. It is a disease of defective collagen formation. Therefore, collagen - containing tissues are affected, e.g. bone, teeth, skin, tendons and ligaments. Primary defect in bone is defective osteoid formation. It is usually transmitted as an autosomal dominant, but in a severe variant of the disease the parents are normal and a fresh gene mutation or autosomal recessive inheritance is postulated. Radiology shows wormian bones in the skull.","pyqMatches":[{"year":"2016","no":1485,"q":"False about osteogenesis imperfecta is","o":["Defective collagen formation","Associated with cataract formation","Autosomal dominant","Known as Brittle bone disease"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5247, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 220, '{"id":5247,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":220,"q":"Shentons line is seen in X ray of -","o":["Antero-posterior pelvis with both hips","Antero-posterior shoulder","Lateral cervical spine","Lateral lumbosacral spine"],"a":0,"e":"Answer- A. Antero-posterior pelvis with both hips With a normal hip Shenton''s line, which continues from the inferior border of the femoral neck to the inferior border of the pubic ramus, looks continuous; any interruption in the line suggests an abnormal position of the femoral head. Narrowing of the joint ''space'' is a sign of articular cartilage loss, a feature of both inflammatory and non-inflammatory arthritis.","pyqMatches":[{"year":"2016","no":1484,"q":"Shentons line is seen in X ray of","o":["Antero-posterior pelvis with both hips","Antero-posterior shoulder","Lateral cervical spine","Lateral lumbosacral spine"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5248, 'Orthopedics', 'Trauma & Fractures', 'Hard', 'Orthopedics', 221, '{"id":5248,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Hard","source":"Orthopedics","sourceNo":221,"q":"A patient presents with wrist trauma. On investigations patient is diagnosed to have a sprained wrist, without any evidence of fracture. There is tenderness in anatomical snuffbox. Which ligament is commonly involved -","o":["Scapholunate ligament","Radial collateral ligament","Lunotriquetral ligament","Ulnar collateral ligament"],"a":0,"e":"Answer- A. Scapholunate ligament Lunate and scapholunate ligmante- Tender in lunate fracture and scapholunate dissociation","pyqMatches":[{"year":"2016","no":1481,"q":"A patient presents with wrist trauma. On investigations patient is diagnosed to have a sprained wrist, without any evidence of fracture. There is tenderness in anatomical snuffbox. Which ligament is commonly involved","o":["Scapholunate ligament","Radial collateral ligament","Lunotriquetral ligament","Ulnar collateral ligament"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5249, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 222, '{"id":5249,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":222,"q":"Palpable femur head on per rectal exam is a feature of which of the following conditions?","o":["Posterior hip dislocation","Anterior hip dislocation","Central hip dislocation","Inferior hip dislocation"],"a":2,"e":"Answer- C. Central hip dislocation In central fracture-dislocation of the hip the femoral head is driven through the floor (medial wall) of the acetabulum towards the pelvic cavity. It occurs due to fall on the side, or a blow over the greater trochater.","pyqMatches":[{"year":"2016","no":1438,"q":"Palpable femur head on per rectal exam is a feature of which of the following conditions?","o":["Posterior hip dislocation","Anterior hip dislocation","Central hip dislocation","Inferior hip dislocation"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5250, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 223, '{"id":5250,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":223,"q":"Popliteal artery injury is commonly seen in which type of traumatic knee dislocation?","o":["Anterior","Posterior","Medial","Lateral"],"a":1,"e":"Answer- B. Posterior Popliteal artery injury is common with both anterior and posterior dislocations. Posterior dislocations more likely to result in direct injury and even rupture of popliteal artery (isolated transection). Anterior dislocations cause stretching of popliteal artery which may lead to intimal disruption and thrombosis (damage is over a longer segment of artery).","pyqMatches":[{"year":"2016","no":1440,"q":"Popliteal artery injury is commonly seen in which type of traumatic knee dislocation?","o":["Anterior","Posterior","Medial","Lateral"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5251, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 224, '{"id":5251,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":224,"q":"Kocher manoeuver is used for","o":["Shoulder reduction","Elbow reduction","Ankle dislocation","Knee dislocation"],"a":0,"e":"Answer- A. Shoulder reduction Kocher''s manoeuvre : This is the most commonly used method. The steps are as follows:","pyqMatches":[{"year":"2016","no":1441,"q":"Kocher manoeuver is used for","o":["Shoulder reduction","Elbow reduction","Ankle dislocation","Knee dislocation"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5252, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 225, '{"id":5252,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":225,"q":"Treatment of scaphoid fracture","o":["Conservative","Compression Screws","Compression Plating","Traction"],"a":0,"e":"Answer- A. Conservative The treatment of a scaphoid is essentially conservative. The hand is immobilized in a scaphoid cast with wrist in little dorsiflexion and radial deviation (glass holding position).","pyqMatches":[{"year":"2016","no":1443,"q":"Treatment of scaphoid fracture","o":["Conservative","Compression Screws","Compression Plating","Traction"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5253, 'Orthopedics', 'Trauma & Fractures', 'Moderate', 'Orthopedics', 226, '{"id":5253,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Moderate","source":"Orthopedics","sourceNo":226,"q":"All of the following are true regarding fracture of lateral condyle of humerus except","o":["Usually seen at 6 - 10 years of age","Results in Gun stock deformity","Cubitus valgus occurs","Tardy ulnar nerve palsy is seen"],"a":1,"e":"Answer- B. Results in Gun stock deformity Fracture Lateral Condyle Humerus/Jupiter fracture It is a common fracture in children. The lateral condylar (or capitular) epiphysis begins to ossify during the first year of life and fuses with shaft at 12-16 years. Between these ages it may be sheared off or avulsed by forceful traction. The maximum chances of injury is between 6-10 years.","pyqMatches":[{"year":"2016","no":1444,"q":"All of the following are true regarding fracture of lateral condyle of humerus except","o":["Usually seen at 6 - 10 years of age","Results in Gun stock deformity","Cubitus valgus occurs","Tardy ulnar nerve palsy is seen"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5254, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 227, '{"id":5254,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":227,"q":"Most common complication of fracture of tibia","o":["Infection","Compartment syndrome","Delayed union","Vascular injury"],"a":2,"e":"Answer- C. Delayed union The tibia has some characteristic features which are responsible for delayed union or non-union of tibia fractures. The distal third of tibia is particularly prone for delayed union and nonunion because of its precarious blood supply.","pyqMatches":[{"year":"2016","no":1445,"q":"Most common complication of fracture of tibia","o":["Infection","Compartment syndrome","Delayed union","Vascular injury"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5255, 'Orthopedics', 'Lower Limb', 'Moderate', 'Orthopedics', 228, '{"id":5255,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Moderate","source":"Orthopedics","sourceNo":228,"q":"Which of the following is not true about ACL injury?","o":["It is a component of the 0'' Donoghue triad","ACL is intrasynovial","ACL is important for proprioceptive function","Anterior drawer test is the most sensitive test"],"a":3,"e":"Answer- D. Anterior drawer test is the most sensitive test Lachman''s test is the most sensitive test for anterior cruciate ligament tears. It is done with the knee flexed at 20 degrees. So it can be done in acute as well as chronic injuries. (because in acute cases with hemarthrosis more flexion is usually not possible so performing anterior drawer test is difficult). ACL is intrasynovial & has proprioceptive function.","pyqMatches":[{"year":"2016","no":1446,"q":"Which of the following is not true about ACL injury?","o":["It is a component of the 0'' Donoghue triad","ACL is intrasynovial","ACL is important for proprioceptive function","Anterior drawer test is the most sensitive test"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5256, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 229, '{"id":5256,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":229,"q":"Cubitus valgus develops as complication of -","o":["Jupitor fracture","Smiths fracture","Malgaigne fracture","Staddle fracture"],"a":0,"e":"Answer- A. Jupitor fracture Fracture of lateral condyle of humerus (Jupitor fracture)","pyqMatches":[{"year":"2016","no":1479,"q":"Cubitus valgus develops as complication of","o":["Jupitor fracture","Smiths fracture","Malgaigne fracture","Staddle fracture"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5257, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 230, '{"id":5257,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":230,"q":"X-ray appearance of sequestrum is -","o":["Unnatural radiodense fragments","Osteopenic fragment","Fragment with honeycomb loculated appearance","Radiolucent area with speckled calcification"],"a":0,"e":"Answer- A. Unnatural radiodense fragments Sequestrum is a piece of dead bone, surrounded by infected granulation tissue trying to eat the sequestrum away. On x-ray, sequestra show up as unnatural dense fragments, in contrast to the surrounding osteopenic bone","pyqMatches":[{"year":"2016","no":1478,"q":"X-ray appearance of sequestrum is","o":["Unnatural radiodense fragments","Osteopenic fragment","Fragment with honeycomb loculated appearance","Radiolucent area with speckled calcification"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5258, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 231, '{"id":5258,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":231,"q":"Continuous fixed traction is provided by -","o":["Thomas splint","BB splint","Hamilton Russel","Gallows"],"a":0,"e":"Answer- A. Thomas splint Combined traction - If a Thomas'' splint is used, the tapes are tied to the end of the splint and the entire splint is then suspended, as in balanced traction","pyqMatches":[{"year":"2016","no":1447,"q":"Continuous fixed traction is provided by","o":["Thomas splint","BB splint","Hamilton Russel","Gallows"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5259, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 232, '{"id":5259,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":232,"q":"Cobra head plate is used for","o":["Hip arthrodesis","Knee arthrodesis","Elbow arthrodesis","Ankle arthrodesis"],"a":0,"e":"Answer- A. Hip arthrodesis Special implants SP nail-plants Dynamic hip screw (DHS)- Intertrochanteric fracture Condylar blade-plate- Interochanteric fracture T-plate- Condylar fracture of femur Spoon plate tibia- Condyar fracture of tibia Cobra plate- Fracture of lower aend of Hip arthrodesis","pyqMatches":[{"year":"2016","no":1448,"q":"Cobra head plate is used for","o":["Hip arthrodesis","Knee arthrodesis","Elbow arthrodesis","Ankle arthrodesis"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5260, 'Orthopedics', 'Lower Limb', 'Hard', 'Orthopedics', 233, '{"id":5260,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Hard","source":"Orthopedics","sourceNo":233,"q":"A 20 year old male presents with history of gradual onset pain and swelling in left knee since 6 months. Now since last 1 month patient has started limping while walking and also has flexion deformity of knee. Ultrasonography shows presence of synovial thickening. What is the most probable diagnosis?","o":["Tuberculosis of knee","Pigmented villonodular synovitis","Synovial sarcoma","Hemarthrosis"],"a":0,"e":"Answer- A. Tuberculosis of knee Unilateral monoarticular knee involvement with gradual onset pain swelling and flexion deformity, with synovial thickening is most probably suggestive of tuberculosis of knee. Presenting complaints : The patient, usually in the age group of 10-25 years, presents with complaints of pain and swelling in the knee On Examination:","pyqMatches":[{"year":"2016","no":1477,"q":"A 20 year old male presents with history of gradual onset pain and swelling in left knee since 6 months. Now since last 1 month patient has started limping while walking and also has flexion deformity of knee. Ultrasonography shows presence of synovial thickening. What is the most probable diagnosis?","o":["Tuberculosis of knee","Pigmented villonodular synovitis","Synovial sarcoma","Hemarthrosis"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5261, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 234, '{"id":5261,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":234,"q":"Locking compression plating for is commonly indicated in the following fracture types","o":["Periarticular fractures","Transverse or oblique fractures of long bones","Intertrochanteric fractures","Fracture of long bones"],"a":0,"e":"Answer- A. Periarticular fractures Locking compression plates are commonly used in periarticular fractures","pyqMatches":[{"year":"2016","no":1449,"q":"Locking compression plating for is commonly indicated in the following fracture types","o":["Periarticular fractures","Transverse or oblique fractures of long bones","Intertrochanteric fractures","Fracture of long bones"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5262, 'Orthopedics', 'Spine', 'Easy', 'Orthopedics', 235, '{"id":5262,"subject":"Orthopedics","chapter":"Spine","difficulty":"Easy","source":"Orthopedics","sourceNo":235,"q":"Tuberculosis of spine most commonly affects which vertebral segment?","o":["Upper dorsal","Lower dorsal","Lumbar","Cervical"],"a":1,"e":"Answer- B. Lower dorsal The spine is the commonest site of bone and joint tuberculosis. The most common site is Dorsolumbar region. Lower dorsal (thoracic) region is the most common segment involved followed by lumbar segment. The tuberculosis of spine is also called pott''s disease or tubercular spondylytis.","pyqMatches":[{"year":"2016","no":1476,"q":"Tuberculosis of spine most commonly affects which vertebral segment?","o":["Upper dorsal","Lower dorsal","Lumbar","Cervical"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5263, 'Orthopedics', 'Trauma & Fractures', 'Hard', 'Orthopedics', 236, '{"id":5263,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Hard","source":"Orthopedics","sourceNo":236,"q":"Dunlop traction is a type of traction used in management of","o":["Fracture humerus","Fracture radius","Fracture femur","Fracture Tibia"],"a":0,"e":"Answer- A. Fracture humerus It is used in management of fracture humerus. It is a skin traction applied to the arm with the child supine. Traction straps are applied to the forearm with the arm supinated. A counterweight is hung from the upper part of the arm to help pull the proximal fragment of the humerus posteriorly, to approximate the distal fragment. Longitudinal traction is then applied to the supinated forearm with the elbow flexed to about 45 degrees","pyqMatches":[{"year":"2016","no":1450,"q":"Dunlop traction is a type of traction used in management of","o":["Fracture humerus","Fracture radius","Fracture femur","Fracture Tibia"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5264, 'Orthopedics', 'Spine', 'Hard', 'Orthopedics', 237, '{"id":5264,"subject":"Orthopedics","chapter":"Spine","difficulty":"Hard","source":"Orthopedics","sourceNo":237,"q":"Which of the following is not true about the management of potts paraplegia?","o":["Chemotherapy is the mainstay of conservative management","Paraplegia not improving with conservative treatment even after 3 - 6 months is an indication for operative intervention","Decompression via anterolateral approach is most preferred","Posterior fusion and instrumentation can be used to correct the deformity"],"a":2,"e":"Answer- C. Decompression via anterolateral approach is most preferred The following measures are adopted in the treatment of Pott''s paraplegia : 1) Conservative treatment Chemotherapy (ATTs) is the mainstay of conservative treatment. Immobilization by traction (in cervical spine) or brace (in dorsal region). Physiotherapy of paralysed limb. 2) Surgical treatment","pyqMatches":[{"year":"2016","no":1475,"q":"Which of the following is not true about the management of potts paraplegia?","o":["Chemotherapy is the mainstay of conservative management","Paraplegia not improving with conservative treatment even after 3 - 6 months is an indication for operative intervention","Decompression via anterolateral approach is most preferred","Posterior fusion and instrumentation can be used to correct the deformity"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5265, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 238, '{"id":5265,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":238,"q":"First radiological sign for active tubercular arthritis is -","o":["Localized osteoporosis","Sclerosis","Joint space reduction","Osteophytes"],"a":0,"e":"Answer- A. Localized osteoporosis In tubercular arthritis, localized osteoporosis is the first radiological sign of active disease.","pyqMatches":[{"year":"2016","no":1474,"q":"First radiological sign for active tubercular arthritis is","o":["Localized osteoporosis","Sclerosis","Joint space reduction","Osteophytes"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5266, 'Orthopedics', 'Bone Tumors', 'Hard', 'Orthopedics', 239, '{"id":5266,"subject":"Orthopedics","chapter":"Bone Tumors","difficulty":"Hard","source":"Orthopedics","sourceNo":239,"q":"33 yr old female presents with a slow growing bony mass along the distal femur cortex in the metaphyseal region with an appreciable gap between the cortex and tumor without any cortical invasion. What is the usual treatment for the same?","o":["Local resection","Amputaion","Chemotherapy","Radiotherapy"],"a":0,"e":"Answer- A. Local resection Slow growing bony mass along the distal femur cortex in the metaphyseal region with an appreciable gap between the cortex and tumor without any cortical invasion in an individual in the 3rd or LIth decade of life is suggestive of - parosteal osteosarcoma. Local resection of the lesion is the usual treatment for parosteal osteosarcoma.","pyqMatches":[{"year":"2016","no":1473,"q":"33 yr old female presents with a slow growing bony mass along the distal femur cortex in the metaphyseal region with an appreciable gap between the cortex and tumor without any cortical invasion. What is the usual treatment for the same?","o":["Local resection","Amputaion","Chemotherapy","Radiotherapy"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5267, 'Orthopedics', 'Bone Tumors', 'Easy', 'Orthopedics', 240, '{"id":5267,"subject":"Orthopedics","chapter":"Bone Tumors","difficulty":"Easy","source":"Orthopedics","sourceNo":240,"q":"Which is intramendullary tumor among carcinoma of bone -","o":["Classical Osteosarcoma","Parosteal osteosarcoma","Periosteal osteosarcoma","None of the above"],"a":0,"e":"Answer- A. Classical Osteosarcoma In its classic (intramedullary) form, osteosarcoma is a highly malignant tumor arising within the bone and spreading rapidly outwards to the periosteum and surrounding soft tissue. The tumor most commonly begins in the metaphysis. Osteosarcoma arises from primitive bone - forming cells. Tumor destroys the bone structure and eventually bursts into the surrounding soft tissues.","pyqMatches":[{"year":"2016","no":1472,"q":"Which is intramendullary tumor among carcinoma of bone","o":["Classical Osteosarcoma","Parosteal osteosarcoma","Periosteal osteosarcoma","None of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5268, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 241, '{"id":5268,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":241,"q":"Age group affected by osteosarcoma -","o":["Upto 10 years","10 - 20 years","30 - 40 years","Older than 45 years"],"a":1,"e":"Answer- B. 10 - 20 years Osteogenic sarcoma is the most common primary malignant tumor of bone in children. This is predominantly a tumor of childhood or adolescence, occuring most commonly in the 10-25 years. The most common site of involvement is metaphysis of long bone around knee : - Lower end of femur (45%) Upper end of Tibia (25%)","pyqMatches":[{"year":"2016","no":1471,"q":"Age group affected by osteosarcoma","o":["Upto 10 years","10 - 20 years","30 - 40 years","Older than 45 years"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5269, 'Orthopedics', 'Spine', 'Easy', 'Orthopedics', 242, '{"id":5269,"subject":"Orthopedics","chapter":"Spine","difficulty":"Easy","source":"Orthopedics","sourceNo":242,"q":"Ankle reflex is affected in prolapsed intervertebral disc at what level?","o":["L3 - L4","L4 - L5","L5 - S1","S1 - S2"],"a":2,"e":"Answer- C. L5-S1 S1 root- Weakness of plantar flexors of root- Over lateral side of foot","pyqMatches":[{"year":"2016","no":1451,"q":"Ankle reflex is affected in prolapsed intervertebral disc at what level?","o":["L3 - L4","L4 - L5","L5 - S1","S1 - S2"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5270, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 243, '{"id":5270,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":243,"q":"CTEV shoe true is","o":["It is the same as normal shoe","It has straight medial border","It has medical shoe raise","It has heel with extra length"],"a":1,"e":"Answer- B. It has straight medial border It has straight inner (medial) border which helps prevent forefoot adduction. It has outer shoe raise which helps prevent forefoot inversion. There is no heel which helps prevent equinus.","pyqMatches":[{"year":"2016","no":1452,"q":"CTEV shoe true is","o":["It is the same as normal shoe","It has straight medial border","It has medical shoe raise","It has heel with extra length"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5271, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 244, '{"id":5271,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":244,"q":"Most commonly lesion associated with pathological fracture in hand is -","o":["Enchondroma","Metastases","Osteoid osteoma","Osteochondroma"],"a":0,"e":"Answer- A. Enchondroma In hand pathological fractures are most commonly associated with benign bone tumors. About 23 % of the bone tumors in hand present with pathological fractures. The average age of presentation is 37 years. The most common bone affected is the proximal phalynx, the fifth ray was involved in 44% of the patients. Majority (approximately 88%) of the pathological fractures are caused by enchondromas.","pyqMatches":[{"year":"2016","no":1468,"q":"Most commonly lesion associated with pathological fracture in hand is","o":["Enchondroma","Metastases","Osteoid osteoma","Osteochondroma"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5272, 'Orthopedics', 'Arthritis & Joint Disease', 'Moderate', 'Orthopedics', 245, '{"id":5272,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Moderate","source":"Orthopedics","sourceNo":245,"q":"All are features of inflammatory arthritis except?","o":["Morning stiffness","X-ray showing sclerosis","Elevated ESR","Weight gain"],"a":1,"e":"Answer- B. X-ray showing sclerosis X-ray feature of inflammatory arthritis shows rarefaction while x-ray features in non-inflammatory arthritis reveals sclerosis.","pyqMatches":[{"year":"2016","no":1453,"q":"All are features of inflammatory arthritis except?","o":["Morning stiffness","X-ray showing sclerosis","Elevated ESR","Weight gain"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5273, 'Orthopedics', 'Upper Limb', 'Moderate', 'Orthopedics', 246, '{"id":5273,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Moderate","source":"Orthopedics","sourceNo":246,"q":"All are true about Marie - strumpell disease except :","o":["Most commonly involves the sacro - iliac joints","Enhesitis is common","More common in males","Roentgenogram is the most sensitive investigation"],"a":3,"e":"Answer- D. Roentgenogram is the most sensitive investigation Marie — Strumpell disease is also known as Ankylosing Spondylitis In the early disease process, plain x-rays (Roentgenogram) may be read as normal —> not very sensitive. Ankylosing spondylitis primarily affects axial skeleton. The disease usually begins in the sacro-iliac joints and usually extends upwards to involve the lumbar, thoracic, and often cervical spine. In the worst cases the hips or shoulders are also affected. Hip joint is the most commonly affected peripheral joint. It is more common in males (male to female ratio 2-3 : 1)","pyqMatches":[{"year":"2016","no":1467,"q":"All are true about Marie - strumpell disease except :","o":["Most commonly involves the sacro - iliac joints","Enhesitis is common","More common in males","Roentgenogram is the most sensitive investigation"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5274, 'Orthopedics', 'Trauma & Fractures', 'Moderate', 'Orthopedics', 247, '{"id":5274,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Moderate","source":"Orthopedics","sourceNo":247,"q":"Which of the following is not true about the tests for hip instability in neonates?","o":["Ortolanis test has two parts","They are performed at 2 - 3 days of birth","In ortolanis test examiners fingers rest on the greater trochanter","In barlows test examiners thumb is placed in the groin"],"a":0,"e":"Answer- A. Ortolanis test has two parts In Ortolani''s test, the baby''s thighs are held with the thumbs medially and the fingers resting on the greater trochanters; the hips are flexed to 90 degrees and gently abducted. Normally there is smooth abduction to almost 90 degrees. In congenital dislocation the movement is usually impeded, but if pressure is applied to the greater trochanter there is a soft ''clunk'' as the dislocation reduces, and then the hip abducts fully (the ''jerk of entry''). If abduction stops halfway and there is no jerk of entry, there may be an irreducible dislocation.","pyqMatches":[{"year":"2016","no":1454,"q":"Which of the following is not true about the tests for hip instability in neonates?","o":["Ortolanis test has two parts","They are performed at 2 - 3 days of birth","In ortolanis test examiners fingers rest on the greater trochanter","In barlows test examiners thumb is placed in the groin"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5275, 'Orthopedics', 'Bone Tumors', 'Easy', 'Orthopedics', 248, '{"id":5275,"subject":"Orthopedics","chapter":"Bone Tumors","difficulty":"Easy","source":"Orthopedics","sourceNo":248,"q":"Oncogenic osteomalacia is mediated by","o":["Phosphatonin","Calcitonin","Interleukin 2","Interleukin 6"],"a":0,"e":"Answer- A. Phosphatonin Oncogenic osteomalacia is mediated by phosphatonin in certain tumors, particularly vascular tumours like hemangiopericytomas and also fibrohistocytic lesions","pyqMatches":[{"year":"2016","no":1456,"q":"Oncogenic osteomalacia is mediated by","o":["Phosphatonin","Calcitonin","Interleukin 2","Interleukin 6"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5276, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 249, '{"id":5276,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":249,"q":"Which of the following is/are feature/s of sprengels deformity?","o":["Elevated shoulder on affected side","Smaller than usual scapula","Short neck","All the above"],"a":3,"e":"Answer- D. All the above Sprengel''s deformity : Deformity is the only symptom and it may be noticed at birth. The shoulder on the affected side is elevated; the scapula looks and feels abnormally high, smaller than usual and somewhat prominent; occasionally both scapulae are affected.","pyqMatches":[{"year":"2016","no":1465,"q":"Which of the following is/are feature/s of sprengels deformity?","o":["Elevated shoulder on affected side","Smaller than usual scapula","Short neck","All the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5277, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 250, '{"id":5277,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":250,"q":"Which of the following is true about CTEV","o":["It is more common in females","Right foot is usually more affected than the left","Talus is displaced medial and plantarwards","Tibia usually shows lateral torsion"],"a":2,"e":"Answer- C. Talus is displaced medial and plantarwards CTEV is the commonest and most important congenital deformity of the foot. CTEV is more common males in than in females (males to female ratio 2.5 : 1). In half of the cases CTEV is bilateral. Right and left foot are affected equally.","pyqMatches":[{"year":"2016","no":1457,"q":"Which of the following is true about CTEV","o":["It is more common in females","Right foot is usually more affected than the left","Talus is displaced medial and plantarwards","Tibia usually shows lateral torsion"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5278, 'Orthopedics', 'Trauma & Fractures', 'Moderate', 'Orthopedics', 251, '{"id":5278,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Moderate","source":"Orthopedics","sourceNo":251,"q":"Which of the following is not true about the manipulation methods to correct CTEV?","o":["Involves serial casting and below knee plaster casting","In kites method deformities are corrected sequentially adduction → inversion → equinus","Ponseti''s technique has success rate of 90 - 98%","Ponseti''s method of correction involves cavus —> adduction --> heel varus —> equinus"],"a":0,"e":"Answer- A. Involves serial casting and below knee plaster casting Serial manipulation and above knee plaster casting is done weekly for the first 6 weeks. Other options are correct.","pyqMatches":[{"year":"2016","no":1459,"q":"Which of the following is not true about the manipulation methods to correct CTEV?","o":["Involves serial casting and below knee plaster casting","In kites method deformities are corrected sequentially adduction → inversion → equinus","Ponseti''s technique has success rate of 90 - 98%","Ponseti''s method of correction involves cavus —> adduction --> heel varus —> equinus"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5279, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 252, '{"id":5279,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":252,"q":"Psoriatic arthritis most commonly involves which joint -","o":["Distal interphalangeal joint","Proximal interphalangeal joint","Wrist joint","Metacarpophalangeal joint"],"a":0,"e":"Answer- A. Distal interphalangeal joint These include :","pyqMatches":[{"year":"2016","no":1464,"q":"Psoriatic arthritis most commonly involves which joint","o":["Distal interphalangeal joint","Proximal interphalangeal joint","Wrist joint","Metacarpophalangeal joint"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5280, 'Orthopedics', 'Trauma & Fractures', 'Hard', 'Orthopedics', 253, '{"id":5280,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Hard","source":"Orthopedics","sourceNo":253,"q":"Which of the following is the management for neglected case of CTEV in a patient > 10 years of age?","o":["Triple arthrodesis","Ankle arthrodesis","Jess fixation","Ponseti casting"],"a":0,"e":"Answer- A. Triple arthrodesis * All these require surgical correction and the surgery depends upon the age of the patient. - < 4 years of age :- Postero-medial soft tissue release - > 4 years :- Postero-medial soft tissue release with a bony procedure :- * 4 - 8 years :- Dilwyn - Evans procedure (PMR + Calcaneo-cuboid fusion) * 8 - 10 years :- PMR + Wedge tarsectomy * > 10 years :- Triple arthrodesis (subtalar, calcaneo-cuboid, and talonavicular joints)","pyqMatches":[{"year":"2016","no":1460,"q":"Which of the following is the management for neglected case of CTEV in a patient > 10 years of age?","o":["Triple arthrodesis","Ankle arthrodesis","Jess fixation","Ponseti casting"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5281, 'Orthopedics', 'Lower Limb', 'Moderate', 'Orthopedics', 254, '{"id":5281,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Moderate","source":"Orthopedics","sourceNo":254,"q":"Which of the following is not true about SCFE?","o":["Males are affected more frequently","Extension is restricted","Commonly occurs during adolescence","Varus, adduction and external rotation deformities are present"],"a":1,"e":"Answer- B. Extension is restricted SCFE is the separation of proximal femoral capital epiphysis (head) at growth plate. SCFE occurs due to weakness of growth plate and occurs during adolescent period (11-15 years) when the growth plate is weak due to accelerated growth. Males are affected more frequently than females. Movements are restricted particularly abduction and internal rotation. Flexion is also restricted and extension is increased. And this clinical feature differentiates SCFE with all other hip pathologies because most of the hip pathologies have opposite deformity, i.e. flexion deformity with restricted extension. Varus, adduction and external rotation deformities are present. External rotation is increased along with extension. When hip is flexed it goes into external rotation, i.e. obligatory external rotation. It is a very important sign of SCFE. Waddling gait is present. Trendelenburg''s test is positive.","pyqMatches":[{"year":"2016","no":1462,"q":"Which of the following is not true about SCFE?","o":["Males are affected more frequently","Extension is restricted","Commonly occurs during adolescence","Varus, adduction and external rotation deformities are present"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5282, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 255, '{"id":5282,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":255,"q":"Genu recurvatum is seen in -","o":["Rheumatoid arthritis","Poliomyelitis","Rickets","All the above"],"a":3,"e":"Answer- D. All the above a) Congenital recurvatum This may be due to abnormal intra-uterine posture; it usually recovers spontaneously. Rarely, gross hyperextension is the precursor of true congenital dislocation of the knee. b) Lax ligaments Normal people with generalized joint laxity tend to stand with their knees backset. Prolonged traction, especially on a frame, or holding the knee hyperextended in plaster, may overstretch ligaments, leading to permanent hyperextension deformity. Ligaments may also become overstretched following chronic or recurrent synovitis (especially in rheumatoid arthritis), the hypotonia of rickets, the flailness of poliomyelitis or the insensitivity of Charcot''s disease.","pyqMatches":[{"year":"2016","no":1463,"q":"Genu recurvatum is seen in","o":["Rheumatoid arthritis","Poliomyelitis","Rickets","All the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5283, 'Orthopedics', 'Bone Tumors', 'Easy', 'Orthopedics', 256, '{"id":5283,"subject":"Orthopedics","chapter":"Bone Tumors","difficulty":"Easy","source":"Orthopedics","sourceNo":256,"q":"Calcification in osteosarcoma is due to presence of","o":["Osteoid matrix","Osteoblasts","High calcium levels in serum","High calcitonin"],"a":0,"e":"Answer- A. Osteoid matrix The pattern of mineralization (calcification) on radiograph may be helpful in identifying tumor matrix. Dense, homogenous mineralization (calcification) is typical of osteoid matrix, formed by benign and malignant bone-forming lesions Calcified rings and arcs, dense punctate calcification, and flocculent calcification (small, loosely aggregated masses) are pattern of mineralization of chondroid matrix, formed by benign and malignant cartilage forming tumors.","pyqMatches":[{"year":"2014","no":1760,"q":"Calcification in osteosarcoma is due to presence of","o":["Osteoid matrix","Osteoblasts","High calcium levels in serum","High calcitonin"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5284, 'Orthopedics', 'Miscellaneous', 'Moderate', 'Orthopedics', 257, '{"id":5284,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Orthopedics","sourceNo":257,"q":"Osteoclasts have all of the following except -","o":["Bone resorption","Receptor for parathormone","Ruffledborder","RANK ligand"],"a":1,"e":"Answer- B. Receptor for parathormone Osteoclasts are found in sites in which bone is being remodeled These cells are the principal mediator of bone resorption The characteristic feature is the area of infolded plasma membrane known as ruffled border which is surrounded by an organelle free clear zone through which osteoclast attaches to bone & which is the site of bone resorption. RANK binds to RANK Ligand which stimulates bone resorption. Parathormone are present on osteoblasts (not on osteoclasts).","pyqMatches":[{"year":"2015","no":1430,"q":"Osteoclasts have all of the following except","o":["Bone resorption","Receptor for parathormone","Ruffledborder","RANK ligand"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5285, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 258, '{"id":5285,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":258,"q":"PTH acts directly on which cells ?","o":["Osteoclasts","Osteocytes","Osteoblasts","Macrophages"],"a":2,"e":"Answer- C. Osteoblasts Parathormone activates osteoblasts which then secrete mediators of osteoclastogenesis that stimulate osteoclasts for bone resorption.","pyqMatches":[{"year":"2015","no":1431,"q":"PTH acts directly on which cells ?","o":["Osteoclasts","Osteocytes","Osteoblasts","Macrophages"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5286, 'Orthopedics', 'Pediatric Orthopedics', 'Easy', 'Orthopedics', 259, '{"id":5286,"subject":"Orthopedics","chapter":"Pediatric Orthopedics","difficulty":"Easy","source":"Orthopedics","sourceNo":259,"q":"Most vascular zone of the bone is -","o":["Metaphysis","Diaphysis","Epiphysis","Medullary Cavity"],"a":0,"e":"Answer- A. Metaphysis Metaphysis is the most vascular zone of the bone especially in children as it has long hairpin loop arranged arterioles and venules running through it.","pyqMatches":[{"year":"2015","no":1432,"q":"Most vascular zone of the bone is","o":["Metaphysis","Diaphysis","Epiphysis","Medullary Cavity"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5287, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 260, '{"id":5287,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":260,"q":"Snapping knee syndrome is due to involvement of -","o":["Pes Anserinus","Quadrieps Tendon","Gastrocnemius origin","lateral collateral ligament"],"a":0,"e":"Answer- A. Pes Anserinus Snapping knee syndrome is characterized by painful clicks/ catching sensations experienced during every movement of flexion and extension. It is experienced usually at the posteromedial corner of the knee and ususally is due to involvement of semitendinosus and gracilis tendons.","pyqMatches":[{"year":"2015","no":1433,"q":"Snapping knee syndrome is due to involvement of","o":["Pes Anserinus","Quadrieps Tendon","Gastrocnemius origin","lateral collateral ligament"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5288, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 261, '{"id":5288,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":261,"q":"Flexor Digitorum Profundus tendon avulsion injury leads to -","o":["Jersey Finger","Mallet Finger","Gamekeepers Thumb","Boutonierre Deformity"],"a":0,"e":"Answer- A. Jersey Finger Jersey Finger - Flexor digitorum profundus Injury Mallet Finger -Avulsion injury of extensor digitorum tendon Gamekeepers Thumb - chronic injury to ulnar collateral ligament of thumb Bennets Fracture- Intra articular fracture at the base of 1st metacarpal","pyqMatches":[{"year":"2015","no":1435,"q":"Flexor Digitorum Profundus tendon avulsion injury leads to","o":["Jersey Finger","Mallet Finger","Gamekeepers Thumb","Boutonierre Deformity"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5289, 'Orthopedics', 'Trauma & Fractures', 'Moderate', 'Orthopedics', 262, '{"id":5289,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Moderate","source":"Orthopedics","sourceNo":262,"q":"K nail can be used for all of the following fractures excePt -","o":["Isthmic femur shaft fractures","Intertrochanteric fractures","Low subtrochanteric fractures","Distal femur shaft fractures"],"a":1,"e":"Answer- B. Intertrochanteric fractures K nail is a clover leaf shaped nail that relies on the principle of three point fixation K nail can never be used for intertrochanteric fractures as it cannot provide stability in this fracture.","pyqMatches":[{"year":"2015","no":1436,"q":"K nail can be used for all of the following fractures excePt","o":["Isthmic femur shaft fractures","Intertrochanteric fractures","Low subtrochanteric fractures","Distal femur shaft fractures"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5290, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 263, '{"id":5290,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":263,"q":"Extensor Carpi Radialis Longus is -","o":["Extensor and ulnar deviator ofthe wrist","Extensor and radial Deviator of the wrist","Injured in Posterior interosseus nerve injury","Weak extensor of the wrist"],"a":1,"e":"Answer- B. Extensor and radial Deviator of the wrist Extensor carpi Radialis Longus is a primary extensor and radial deviator of the wrist. Loss of function causes wrist drop.","pyqMatches":[{"year":"2015","no":1437,"q":"Extensor Carpi Radialis Longus is","o":["Extensor and ulnar deviator ofthe wrist","Extensor and radial Deviator of the wrist","Injured in Posterior interosseus nerve injury","Weak extensor of the wrist"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5291, 'Orthopedics', 'Lower Limb', 'Hard', 'Orthopedics', 264, '{"id":5291,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Hard","source":"Orthopedics","sourceNo":264,"q":"A child presented to an orthopaedic clinic with a limp. The surgeon suspected him to have a fixed fledon deformity of the hip. Which test should the surgeon perform to confirm his finding?","o":["Thomas test","Trendelenburgs test","Nelatons test","Telescoping test"],"a":0,"e":"Answer- A. Thomas test Thomas test is done for flexion deformity of hip.","pyqMatches":[{"year":"2015","no":1439,"q":"A child presented to an orthopaedic clinic with a limp. The surgeon suspected him to have a fixed fledon deformity of the hip. Which test should the surgeon perform to confirm his finding?","o":["Thomas test","Trendelenburgs test","Nelatons test","Telescoping test"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5292, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 265, '{"id":5292,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":265,"q":"Trigger Finger Involves Which joint ?","o":["Proximal Interphalngeal joint","Distal Interphalngeal foint","Metacarpophalangeal joint","Carpometacarpal joint"],"a":2,"e":"Answer- C. Metacarpophalangeal joint The mouth of the fibrous digital sheath is at the level of metacarpo- phalangeal joint.","pyqMatches":[{"year":"2015","no":1440,"q":"Trigger Finger Involves Which joint ?","o":["Proximal Interphalngeal joint","Distal Interphalngeal foint","Metacarpophalangeal joint","Carpometacarpal joint"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5293, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 266, '{"id":5293,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":266,"q":"Effect of hypoparathyroidisrn on bones include -","o":["Brown tumours","Subperiosteal Resorption of Bone","Multiple Cysts in Bone","NoneoftheAbove"],"a":3,"e":"Answer- D. NoneoftheAbove Features of Hypoparathyroidism Premature closure of epiphyses Generalized increase in bone density (Osteosclerosis) Calvarial thickening Sacroiliac sclerosis Bandlike density in metaphysic Thickened lamina dura + widened diploe Deformed hip (thickening & Sclerosis of femoral head & acetabulum) Intracranial calcification Calcification of spinal & Other ligaments Subcutaneous calcification Ectopic bone formation Ossification of muscle insertions","pyqMatches":[{"year":"2015","no":1441,"q":"Effect of hypoparathyroidisrn on bones include","o":["Brown tumours","Subperiosteal Resorption of Bone","Multiple Cysts in Bone","NoneoftheAbove"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5294, 'Orthopedics', 'Trauma & Fractures', 'Hard', 'Orthopedics', 267, '{"id":5294,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Hard","source":"Orthopedics","sourceNo":267,"q":"Bone transport can be used in the management of -","o":["Gap non union","Deformity Correction","Communited shaft femur fracture","Avscular Necrosis of Femoral Head"],"a":0,"e":"Answer- A. Gap non union Bone transport technique is primarily used in the management of gap non unions. An osteotomy is made in the normal bone and a segamnt of bone is transported to the non union site","pyqMatches":[{"year":"2015","no":1442,"q":"Bone transport can be used in the management of","o":["Gap non union","Deformity Correction","Communited shaft femur fracture","Avscular Necrosis of Femoral Head"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5295, 'Orthopedics', 'Trauma & Fractures', 'Moderate', 'Orthopedics', 268, '{"id":5295,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Moderate","source":"Orthopedics","sourceNo":268,"q":"AII of the following are true regarding application of POP Cast except -","o":["Putting the Plaster roll in warm water hastens setting time","It is anhydrous Calcium phosphate","It can applied in presence of extreme swelling","Gangrene is known complication of a tight plaster cast"],"a":1,"e":"Answer B. It is anhydrous Calcium phosphate POP is chemically hemihydrous calcium sulphate. Warm water hastens while cold water slows the setting time. Plaster cast should be avoided when there is extreme swelling. Common complications of plaster casts include compartment syndrome, gangrene and plaster sores.","pyqMatches":[{"year":"2015","no":1444,"q":"AII of the following are true regarding application of POP Cast except","o":["Putting the Plaster roll in warm water hastens setting time","It is anhydrous Calcium phosphate","It can applied in presence of extreme swelling","Gangrene is known complication of a tight plaster cast"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5296, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 269, '{"id":5296,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":269,"q":"In uncemented arthroplasty of the hip , the stem remains attached to the bone by -","o":["Bone Ingrowth/ ongrowth over the surface of the stem","Mechanical bonding between the stem and bone","Press fitting of the stem in the tight canal","Adhesion between the stem and bone due to ashesive properties ofthe stem"],"a":0,"e":"Answer- A. Bone Ingrowth/ ongrowth over the surface of the stem Bone in growth- Over porous surface. Optimal pore size should be 100 to 400 microns. Fiber mesh or beads are present over the stem surface. Stem created by sintering or diffusion bonding processes.","pyqMatches":[{"year":"2015","no":1445,"q":"In uncemented arthroplasty of the hip , the stem remains attached to the bone by","o":["Bone Ingrowth/ ongrowth over the surface of the stem","Mechanical bonding between the stem and bone","Press fitting of the stem in the tight canal","Adhesion between the stem and bone due to ashesive properties ofthe stem"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5297, 'Orthopedics', 'Arthritis & Joint Disease', 'Moderate', 'Orthopedics', 270, '{"id":5297,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Moderate","source":"Orthopedics","sourceNo":270,"q":"During perfoming a total hip replacement, the surgeon found destruction of the articular cartilage and rnultiple wedge shaped subchondral depressions. What is this called ?","o":["Osteolysis","Osteomyelitis","Osteonecrosis","Osteogenesis"],"a":2,"e":"Answer- C. Osteonecrosis Presence of dense wedge shaped opacities in the anterolateral quadrant of the femoral head this is called sectoral involvement. Presence of multiple cystic and sclerotic areas Acetabular involvement leads to development of severe arthritis","pyqMatches":[{"year":"2015","no":1446,"q":"During perfoming a total hip replacement, the surgeon found destruction of the articular cartilage and rnultiple wedge shaped subchondral depressions. What is this called ?","o":["Osteolysis","Osteomyelitis","Osteonecrosis","Osteogenesis"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5298, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 271, '{"id":5298,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":271,"q":"Sudden dorsiflexion of foot may lead to which of the following injuries -","o":["Anterior talofibular ligament injury","Tendo Achilles avulsion injury","Rupture of deltoid ligament","Tarsal tunnel syndrome"],"a":1,"e":"Answer- B. Tendo Achilles avulsion injury A rupture of the Achilles tendon occurs when the tendon is stretched outside beyond its capacity. The most common site of rupture is the \"watershed\" less vascular area of tendon, which is 4 cm proximal to its insertion on calcaneum.","pyqMatches":[{"year":"2015","no":1447,"q":"Sudden dorsiflexion of foot may lead to which of the following injuries","o":["Anterior talofibular ligament injury","Tendo Achilles avulsion injury","Rupture of deltoid ligament","Tarsal tunnel syndrome"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5299, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 272, '{"id":5299,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":272,"q":"Salter Harris classification is used for -","o":["Supracondylar humerus fractures in children","Estimation of growth of the physes","Physeal injuries","Severity of degloving injuries to the limb"],"a":2,"e":"Answer- C. Physeal injuries","pyqMatches":[{"year":"2015","no":1448,"q":"Salter Harris classification is used for","o":["Supracondylar humerus fractures in children","Estimation of growth of the physes","Physeal injuries","Severity of degloving injuries to the limb"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5300, 'Orthopedics', 'Spine', 'Easy', 'Orthopedics', 273, '{"id":5300,"subject":"Orthopedics","chapter":"Spine","difficulty":"Easy","source":"Orthopedics","sourceNo":273,"q":"Milwaukee Brace is used in -","o":["Congenital Kyphosis","Scheurmanns Disease","Adolescentldiopathic Scoliosis","Spondylolisthesis"],"a":0,"e":"Answer- A. Congenital Kyphosis The Milwaukee brace is a plastic body jacket used in the treatment of adolescents with idiopathic scoliosis and Scheuermann''s disease. The Milwaukee brace, also refferred to as a Cervico-Thoraco- Lumbo-Sacral-Orthosis brace, is similar to braces for the lower back, but also includes a neck ring held in place by vertical bars attached to the body of the brace.","pyqMatches":[{"year":"2015","no":1449,"q":"Milwaukee Brace is used in","o":["Congenital Kyphosis","Scheurmanns Disease","Adolescentldiopathic Scoliosis","Spondylolisthesis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5301, 'Orthopedics', 'Spine', 'Moderate', 'Orthopedics', 274, '{"id":5301,"subject":"Orthopedics","chapter":"Spine","difficulty":"Moderate","source":"Orthopedics","sourceNo":274,"q":"Vertebra Plana is seen in all except -","o":["Histioctosis X","Leukemia","Excessive use of systemic steroids","Scheurmanns Disease"],"a":3,"e":"Answer- D. Scheurmanns Disease Causes of Vertebra Plana","pyqMatches":[{"year":"2015","no":1450,"q":"Vertebra Plana is seen in all except","o":["Histioctosis X","Leukemia","Excessive use of systemic steroids","Scheurmanns Disease"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5302, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 275, '{"id":5302,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":275,"q":"What is luxatio erecta ?","o":["Anterior Dislocation of the shoulder joint","Inferior Dislocation of the shoulder joint","Anterior Dislocation of the HIP joint","Posterior Dislocation of Hip joint"],"a":1,"e":"Answer- B. Inferior Dislocation of the shoulder joint The head of the humerus is below the glenoid cavity and the humeral shaft is pointing overhead. It is due to hyperabduction injury. It is rare and also called luxatio erecta because the humeral head is subluxated (dislocated inferiorly) and humerus shaft points upwards (erected).","pyqMatches":[{"year":"2015","no":1451,"q":"What is luxatio erecta ?","o":["Anterior Dislocation of the shoulder joint","Inferior Dislocation of the shoulder joint","Anterior Dislocation of the HIP joint","Posterior Dislocation of Hip joint"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5303, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 276, '{"id":5303,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":276,"q":"Which of the following casts/splints is used for fracture shaft humerus ?","o":["Hanging casts","Knuckle bender splint","Aeroplane Splint","Above elbow cast"],"a":0,"e":"Answer- A. Hanging casts Hanging cast- Fracture of the humerus Turn-buckle cast- Scoliosis","pyqMatches":[{"year":"2015","no":1452,"q":"Which of the following casts/splints is used for fracture shaft humerus ?","o":["Hanging casts","Knuckle bender splint","Aeroplane Splint","Above elbow cast"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5304, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 277, '{"id":5304,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":277,"q":"Three point bony relationship of the elbow is disturbed in -","o":["Supracondylar Fracture of the humerus","Fracture lateral condyle of the humerus","Monteggia Fracture dislocation","Fracture of Proximal Radius"],"a":1,"e":"Answer- B. Fracture lateral condyle of the humerus Three prominent bony points around elbow are medial epicondyle, lateral epicondyle and tip of the olecranon. In elbow injuries, following is seen in three bony relationship :","pyqMatches":[{"year":"2015","no":1455,"q":"Three point bony relationship of the elbow is disturbed in","o":["Supracondylar Fracture of the humerus","Fracture lateral condyle of the humerus","Monteggia Fracture dislocation","Fracture of Proximal Radius"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5305, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 278, '{"id":5305,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":278,"q":"Hamilton Ruler test sign is positive in which of the above mentioned conditions ?","o":["Anterior dislocation of shoulder","Acrornioclavivular joint dislocation","Posterior dislocation of shoulder","luxatio erecta"],"a":0,"e":"Answer- A. Anterior dislocation of shoulder Hamilton ruler test : Because of flattening of shoulder, it is possible to place a ruler on the lateral side of arm and it touches acromian & lateral condyle of humerus simultaneously (in normal it would not due to shoulder contour).","pyqMatches":[{"year":"2015","no":1456,"q":"Hamilton Ruler test sign is positive in which of the above mentioned conditions ?","o":["Anterior dislocation of shoulder","Acrornioclavivular joint dislocation","Posterior dislocation of shoulder","luxatio erecta"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5306, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 279, '{"id":5306,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":279,"q":"Cubitus Valgus Deformity is commonly seen in which of the following conditions -","o":["Malunited Lateral Condylar fracture of Humerus","Malunited Supracondylar Fracture of Humerus","Posterior dislocation ofelbow","Fracture medial condyle of humerus"],"a":0,"e":"Answer- A. Malunited Lateral Condylar fracture of Humerus Fractures commonly showing cubitus valgus deformity due to malunion : Fracture lateral condyle humerus Monteggia Fracture Dislocation","pyqMatches":[{"year":"2015","no":1457,"q":"Cubitus Valgus Deformity is commonly seen in which of the following conditions","o":["Malunited Lateral Condylar fracture of Humerus","Malunited Supracondylar Fracture of Humerus","Posterior dislocation ofelbow","Fracture medial condyle of humerus"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5307, 'Orthopedics', 'Trauma & Fractures', 'Moderate', 'Orthopedics', 280, '{"id":5307,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Moderate","source":"Orthopedics","sourceNo":280,"q":"AVN following transcervical neck femur fractures occurs due to damage to which of the following blood vessels ?","o":["Lateral retinacular branch of lateral circumflex femoral artery","Lateral retinacular branch of medial circumflex femoral artery","Medial retinacular branch of lateral circumflex femoral artery","Obdurator artery"],"a":0,"e":"Answer- A. Lateral retinacular branch of lateral circumflex femoral artery Lateral circumflex femoral artery It supplies through anterior retinacular artery.","pyqMatches":[{"year":"2015","no":1460,"q":"AVN following transcervical neck femur fractures occurs due to damage to which of the following blood vessels ?","o":["Lateral retinacular branch of lateral circumflex femoral artery","Lateral retinacular branch of medial circumflex femoral artery","Medial retinacular branch of lateral circumflex femoral artery","Obdurator artery"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5308, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 281, '{"id":5308,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":281,"q":"Lockingoftheknee involves -","o":["External rotation of femur with the foot offthe ground","Internal rotation of the tibia with the foot on the ground","Contraction of popliteus","Internal rotation of femur with foot on the ground"],"a":3,"e":"Answer- D. Internal rotation of femur with foot on the ground Physiological locking occurs in extension when the femur is internally (medially) rotated on a fixed tibia. Locking is a mechanism that allows the knee to remain in the position of full extension as in standing without much muscular efforts and is caused by quadriceps femoris.","pyqMatches":[{"year":"2015","no":1462,"q":"Lockingoftheknee involves","o":["External rotation of femur with the foot offthe ground","Internal rotation of the tibia with the foot on the ground","Contraction of popliteus","Internal rotation of femur with foot on the ground"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5309, 'Orthopedics', 'Trauma & Fractures', 'Moderate', 'Orthopedics', 282, '{"id":5309,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Moderate","source":"Orthopedics","sourceNo":282,"q":"Fracture neck of femur in 80 year old male sustained 1 weekback The treatment of choice is -","o":["Hemiarthroplasty","ExcisionarthroPlastY","Closed reduction and fixation with three cancellous screws","Longitudinal skin traction for 6 weeks"],"a":0,"e":"Answer- A. Hemiarthroplasty Closed reduction & screw fixation If 2 attempts of closed reduction fail, hemiarthroplasty is done","pyqMatches":[{"year":"2015","no":1464,"q":"Fracture neck of femur in 80 year old male sustained 1 weekback The treatment of choice is","o":["Hemiarthroplasty","ExcisionarthroPlastY","Closed reduction and fixation with three cancellous screws","Longitudinal skin traction for 6 weeks"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5310, 'Orthopedics', 'Trauma & Fractures', 'Moderate', 'Orthopedics', 283, '{"id":5310,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Moderate","source":"Orthopedics","sourceNo":283,"q":"Which of the following fractures of the neck of femur are associated with maximal compromise in blood supply ?","o":["Intertrochantericfractures","Basicervical fracture","Trans cervical fracture","Sub Capital fractures"],"a":3,"e":"Answer- D. Sub Capital fractures The non-union and AVN will be most common in subcapital fracture and least in basicervical fracture.","pyqMatches":[{"year":"2015","no":1465,"q":"Which of the following fractures of the neck of femur are associated with maximal compromise in blood supply ?","o":["Intertrochantericfractures","Basicervical fracture","Trans cervical fracture","Sub Capital fractures"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5311, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 284, '{"id":5311,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":284,"q":"Tinels sign is seen in -","o":["Avascular necrosisof scaPhoid","Kienbock s Disease","lst carpometacarpal joint arthritis","Carpal tunnel syndrome"],"a":3,"e":"Answer- D. Carpal tunnel syndrome Median nerve percussion test (Tinel''s sign) : - The median nerve is gently tapped at the wrist. The test is positive if there is tingling sensation","pyqMatches":[{"year":"2015","no":1467,"q":"Tinels sign is seen in","o":["Avascular necrosisof scaPhoid","Kienbock s Disease","lst carpometacarpal joint arthritis","Carpal tunnel syndrome"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5312, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 285, '{"id":5312,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":285,"q":"Which of the following is used as a substitute for wrist extensors in radial nerve PalsY?","o":["Pronator Teres","Palmaris Longus","Flexor Digitorum SuPerficialis","Flexor Digitorum Profundus"],"a":0,"e":"Answer- A. Pronator Teres Pronator teres is a common muscle used as a substitute for wrist extensors in case of wrist drop occurring as a result of radial nerve palsy. Pronator teres is a pronator of the forearm supplied by Median nerve.","pyqMatches":[{"year":"2015","no":1468,"q":"Which of the following is used as a substitute for wrist extensors in radial nerve PalsY?","o":["Pronator Teres","Palmaris Longus","Flexor Digitorum SuPerficialis","Flexor Digitorum Profundus"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5313, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 286, '{"id":5313,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":286,"q":"Most common cause of ca4ral tunnel syndrome is ?","o":["Pregnancy","Idiopathic","Alcoholism","Occupational-Excessive use of vibratory instruments"],"a":1,"e":"Answer- B. Idiopathic Most common type of carpal tunnel syndrome is idiopathic → no known cause.","pyqMatches":[{"year":"2015","no":1469,"q":"Most common cause of ca4ral tunnel syndrome is ?","o":["Pregnancy","Idiopathic","Alcoholism","Occupational-Excessive use of vibratory instruments"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5314, 'Orthopedics', 'Trauma & Fractures', 'Hard', 'Orthopedics', 287, '{"id":5314,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Hard","source":"Orthopedics","sourceNo":287,"q":"A 45 year old carpenter with a blunt trauma to his arm sustained a fracture followingwhich he developedwrist drop, loss of extension at fingers and loss of sensations on the lateral aspect of the wrist joint. Which of the following is true ?","o":["Patient has an injury to the median nerve","He should have also lost extention of the forearm","Patient has injured the radial nerve in the spird groove","There is combined involvement of the radial nerve and median nerve"],"a":2,"e":"Answer- C. Patient has injured the radial nerve in the spird groove Radial nerve injury may be high or low. 1) High radial nerve palsy Injury is before the spiral groove All muscles supplied by radial nerve are paralysed 2) If lesion is high Wrist drop, thumb drop and finger drop. Inability to extend elbow, wrist, thumb & fingers (MP joint) Patient can extend interphalangeal joints due to action of lumbricals and interossei. Sensory loss over posterior surface of arm & forearm and lower lateral half of forearm.","pyqMatches":[{"year":"2015","no":1470,"q":"A 45 year old carpenter with a blunt trauma to his arm sustained a fracture followingwhich he developedwrist drop, loss of extension at fingers and loss of sensations on the lateral aspect of the wrist joint. Which of the following is true ?","o":["Patient has an injury to the median nerve","He should have also lost extention of the forearm","Patient has injured the radial nerve in the spird groove","There is combined involvement of the radial nerve and median nerve"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5315, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 288, '{"id":5315,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":288,"q":"In which of the following deformities is the distal interphalangeal joint extended ?","o":["Boutonniere deformity","Swan neck deformity","Z deforrnity","Claw Hand"],"a":0,"e":"Answer- A. Boutonniere deformity Boutonniere deformity : Flexion contracture of PIP joint and extension of DIP joint.","pyqMatches":[{"year":"2015","no":1472,"q":"In which of the following deformities is the distal interphalangeal joint extended ?","o":["Boutonniere deformity","Swan neck deformity","Z deforrnity","Claw Hand"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5316, 'Orthopedics', 'Pediatric Orthopedics', 'Easy', 'Orthopedics', 289, '{"id":5316,"subject":"Orthopedics","chapter":"Pediatric Orthopedics","difficulty":"Easy","source":"Orthopedics","sourceNo":289,"q":"Club foot clinically present as what deformity ?","o":["Calcaneovalgus","Equinovarus","Equino Cavovarus","Calcaneovarus"],"a":2,"e":"Answer- C. Equino Cavovarus CTEV is the commonest and most important congenital deformity of the foot. The deformity consists of following elements :","pyqMatches":[{"year":"2015","no":1473,"q":"Club foot clinically present as what deformity ?","o":["Calcaneovalgus","Equinovarus","Equino Cavovarus","Calcaneovarus"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5317, 'Orthopedics', 'Trauma & Fractures', 'Hard', 'Orthopedics', 290, '{"id":5317,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Hard","source":"Orthopedics","sourceNo":290,"q":"4 year old child presented to the clinic with a history of fall on outstretched hand. Radiographs revealed a broken anterior cortex with an intact posterior cortex Of the radius with an exaggerated bowing of the radius. The fracture sustained is known as -","o":["Torus Fracture","Greenstick fracture","Galleazi Fracture","Monteggia Frtacture Dislocation"],"a":1,"e":"Answer- B. Greenstick fracture Greenstick Fracture: Incomplete fracture of the bone with plastic deformation on the concave side of the bone. The fracture needs to be completed to obtain reduction.","pyqMatches":[{"year":"2015","no":1474,"q":"4 year old child presented to the clinic with a history of fall on outstretched hand. Radiographs revealed a broken anterior cortex with an intact posterior cortex Of the radius with an exaggerated bowing of the radius. The fracture sustained is known as","o":["Torus Fracture","Greenstick fracture","Galleazi Fracture","Monteggia Frtacture Dislocation"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5318, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 291, '{"id":5318,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":291,"q":"Greenstick/ Nightstick fractures are seen in -","o":["Children","Elderly","Youngadults","Common in all age groups"],"a":0,"e":"Answer- A. Children","pyqMatches":[{"year":"2015","no":1475,"q":"Greenstick/ Nightstick fractures are seen in","o":["Children","Elderly","Youngadults","Common in all age groups"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5319, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 292, '{"id":5319,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":292,"q":"Who devised correction of CTEV by serial castinga -","o":["Ignasio Ponseti","Gerhardt Kuntscher","Gavril Ilizarov","Hugh Owen Thomas"],"a":0,"e":"Answer- A. Ignasio Ponseti Ignasio Ponseti propounded the technique of serial weekly casts.","pyqMatches":[{"year":"2015","no":1478,"q":"Who devised correction of CTEV by serial castinga","o":["Ignasio Ponseti","Gerhardt Kuntscher","Gavril Ilizarov","Hugh Owen Thomas"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5320, 'Orthopedics', 'Pediatric Orthopedics', 'Easy', 'Orthopedics', 293, '{"id":5320,"subject":"Orthopedics","chapter":"Pediatric Orthopedics","difficulty":"Easy","source":"Orthopedics","sourceNo":293,"q":"Osteosclerosis is a feature of which of the followinga -","o":["Rickets","Hyperparathyroidism","Pagets Disease","Osteogenesis Imperfecta"],"a":2,"e":"Answer- C. Pagets Disease Paget''s disease is characterized by increased bone turnover and enlargement and thickening of the bone, but the internal architecture is abnormal and the bone is usually brittle. Primary defect is in osteoclasts with increased osteoclastic activity. This results secondarily increase in osteoblastic activity (normal osteoclasts and osteoblasts act in a co-ordinated manner).","pyqMatches":[{"year":"2015","no":1479,"q":"Osteosclerosis is a feature of which of the followinga","o":["Rickets","Hyperparathyroidism","Pagets Disease","Osteogenesis Imperfecta"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5321, 'Orthopedics', 'Bone Tumors', 'Moderate', 'Orthopedics', 294, '{"id":5321,"subject":"Orthopedics","chapter":"Bone Tumors","difficulty":"Moderate","source":"Orthopedics","sourceNo":294,"q":"All of the following are true regarding Pagets Disease except -","o":["Pelvis is the most common site","Cranial nerve involvement may be seen","High output cardiac failure is one of the complications","It may progress to a secondary chondrosarcoma"],"a":3,"e":"Answer- D. It may progress to a secondary chondrosarcoma Pagets disease may progress to a secondary osteosarcoma not chondrosarcoma","pyqMatches":[{"year":"2015","no":1480,"q":"All of the following are true regarding Pagets Disease except","o":["Pelvis is the most common site","Cranial nerve involvement may be seen","High output cardiac failure is one of the complications","It may progress to a secondary chondrosarcoma"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5322, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 295, '{"id":5322,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":295,"q":"Commonest site of occurrence of chondrosarcoma is -","o":["Pelvis","Ribs","Femur","Proximal tibia"],"a":0,"e":"Answer- A. Pelvis A chondrosarcoma is a malignant tumor derived from cartilage cells and it tends to maintain its cartilaginous character throughout its evolution Most commonly involved bones are pelvis (most common), femur (2nd most common), humerus, ribs and shoulder girdles. It may be at metaphysis or diaphysis.","pyqMatches":[{"year":"2015","no":1483,"q":"Commonest site of occurrence of chondrosarcoma is","o":["Pelvis","Ribs","Femur","Proximal tibia"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5323, 'Orthopedics', 'Bone Tumors', 'Easy', 'Orthopedics', 296, '{"id":5323,"subject":"Orthopedics","chapter":"Bone Tumors","difficulty":"Easy","source":"Orthopedics","sourceNo":296,"q":"Onion peel appearanace on Xray is seen in which of the following conditions ?","o":["Ewings Sarcoma","Osteosarcoma","Giant cell tumour","Eosinophilic granuloma"],"a":0,"e":"Answer- A. Ewings Sarcoma Onion Peel Appearance Ewings Sarcoma Codmans Triangle Osteosarcoma Sun Burst Appearance Osteosarcoma Soap Bubble appearanceGCT","pyqMatches":[{"year":"2015","no":1484,"q":"Onion peel appearanace on Xray is seen in which of the following conditions ?","o":["Ewings Sarcoma","Osteosarcoma","Giant cell tumour","Eosinophilic granuloma"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5324, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 297, '{"id":5324,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":297,"q":"Hammer toe deformity is seen in -","o":["Rheumatoid arthritis","Fracture distal phalanx ofgreat toe","Bunion","Osteochondritis"],"a":0,"e":"Answer- A. Rheumatoid arthritis Foot Hallux valgus, Hammer toe, etc.","pyqMatches":[{"year":"2015","no":1486,"q":"Hammer toe deformity is seen in","o":["Rheumatoid arthritis","Fracture distal phalanx ofgreat toe","Bunion","Osteochondritis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5325, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 298, '{"id":5325,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":298,"q":"Pion fracture is","o":["Bimalleolar","Trimalleolar","Distal femur Intraarticular","Distal tibia Intraarticular"],"a":3,"e":"Answer- D. Distal tibia Intraarticular Pilon fracture- Comminuted intra-articular fracture of distal tibial end","pyqMatches":[{"year":"2013","no":1494,"q":"Pion fracture is","o":["Bimalleolar","Trimalleolar","Distal femur Intraarticular","Distal tibia Intraarticular"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5326, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 299, '{"id":5326,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":299,"q":"Late complication of elbow dislocation","o":["Median nerve injury","Brachial artery injury","Myositis ossificans","All of the above"],"a":2,"e":"Answer- C. Myositis ossificans Late complications Stiffness Myositis ossificans Unreduced dislocation Recurrent dislocation","pyqMatches":[{"year":"2013","no":1502,"q":"Late complication of elbow dislocation","o":["Median nerve injury","Brachial artery injury","Myositis ossificans","All of the above"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5327, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 300, '{"id":5327,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":300,"q":"Which arthritis causes no periosteal reaction","o":["Psoriatic athritis","Reactive arthritis","Neropathic arthritis","Rheumatoid arthritis"],"a":3,"e":"Answer- D. Rheumatoid arthritis Arthritis with Periosteal Reaction are Psoriatic arthritis, Reactive Arthritis And Neuropathic Arthropathy.","pyqMatches":[{"year":"2013","no":1551,"q":"Which arthritis causes no periosteal reaction","o":["Psoriatic athritis","Reactive arthritis","Neropathic arthritis","Rheumatoid arthritis"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5328, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 301, '{"id":5328,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":301,"q":"Proximal humerus fracture which has maximum chances of avascular necrosis","o":["One part","Two part","Three part","Four part"],"a":3,"e":"Answer- D. Four part Neer''s classified proximal humerus fracture into 4 types, based on these four segments :","pyqMatches":[{"year":"2012","no":1220,"q":"Proximal humerus fracture which has maximum chances of avascular necrosis","o":["One part","Two part","Three part","Four part"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5329, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 302, '{"id":5329,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":302,"q":"Most common muscle damaged in rotator cuff","o":["Supraspinatus","Infraspinatus","Subscapularis","Teres minor"],"a":0,"e":"Answer- A. Supraspinatus During injury to rotator cuff, tendons are affected, not the muscle. Supraspinatus tendon is affected most frequently.","pyqMatches":[{"year":"2012","no":1222,"q":"Most common muscle damaged in rotator cuff","o":["Supraspinatus","Infraspinatus","Subscapularis","Teres minor"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5330, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 303, '{"id":5330,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":303,"q":"True about supracondylar fracture of humerus","o":["Common in adults","Extension type most common","Flexion type is most common","None"],"a":1,"e":"Answer- B. Extension type most common Supracondylar humeral fractures are the most common elbow fractures in children. Most common age group affected is 5-8 years. Boys are affected more than girls. Left side is more common than right. Extension type is most common","pyqMatches":[{"year":"2012","no":1223,"q":"True about supracondylar fracture of humerus","o":["Common in adults","Extension type most common","Flexion type is most common","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5331, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 304, '{"id":5331,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":304,"q":"What is seen on x-ray with posterior elbow dislocation","o":["Coronoid process posterior to humerus","Coronoid process anterior to humerus","Coronoid process below humerus","None"],"a":0,"e":"Answer- A. Coronoid process posterior to humerus AP view : Greater superimposition of distal humerus with proximal ulna and olecranon (normally, only terminal part of humerus is superimposed).","pyqMatches":[{"year":"2012","no":1226,"q":"What is seen on x-ray with posterior elbow dislocation","o":["Coronoid process posterior to humerus","Coronoid process anterior to humerus","Coronoid process below humerus","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5332, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 305, '{"id":5332,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":305,"q":"In posterior dislocation of elbow, most prominent part","o":["Coronoid","Radial head","Olecranon","None"],"a":2,"e":"Answer- C. Olecranon There is exaggrated prominence of the Olecranon","pyqMatches":[{"year":"2012","no":1227,"q":"In posterior dislocation of elbow, most prominent part","o":["Coronoid","Radial head","Olecranon","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5333, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 306, '{"id":5333,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":306,"q":"Most common complication of lateral condyle humerus fracture","o":["Malunion","Nonunion","VIC","Median nerve injury"],"a":1,"e":"Answer- B. Nonunion Lateral spur (Lateral condylar spur or lateral condylar overgrowth) is one of the most common complication. Delayed union or non-union can occur if fracture is undetected or left untreated. Cubitus valgus is a common complication Tardy ulnar nerve palsy seen after several years. Rarely avascular necrosis and myositis ossificans.","pyqMatches":[{"year":"2012","no":1228,"q":"Most common complication of lateral condyle humerus fracture","o":["Malunion","Nonunion","VIC","Median nerve injury"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5334, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 307, '{"id":5334,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":307,"q":"Most common complication of Cones #","o":["Malunion","Avascular necrosis","Finger stiffness","Rupture of EPL tendon"],"a":2,"e":"Answer- C. Finger stiffness The complication rate is 55%, with the most common complication being some degree of residual finger and wrist stiffness (39%). Most common complication of colle''s fracture- Finger stiffness","pyqMatches":[{"year":"2012","no":1231,"q":"Most common complication of Cones #","o":["Malunion","Avascular necrosis","Finger stiffness","Rupture of EPL tendon"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5335, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 308, '{"id":5335,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":308,"q":"Most common complication of fracture neck of femur","o":["Malunion","AVN","Nonunion","Arthritis"],"a":1,"e":"Answer- B. AVN AVN is the most common complication of femoral neck fracture. Non-union is the second most common complication of femoral neck fracture.","pyqMatches":[{"year":"2012","no":1232,"q":"Most common complication of fracture neck of femur","o":["Malunion","AVN","Nonunion","Arthritis"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5336, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 309, '{"id":5336,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":309,"q":"Which of the following describes grade 2 fracture neck femur?","o":["Incomplete fracture, medial trabeculae intact","Complete fracture with undisplaced neck","Complete fracture with ischemic head","Moderate displacement of neck, vascularity damaged"],"a":1,"e":"Answer- B. Complete fracture with undisplaced neck Garden stage I: undisplaced incomplete, including valgus impacted fractures medial group of femoral neck trabeculae may demonstrate a greenstick fracture Garden stage II: undisplaced complete no disturbance of the medial trabeculae","pyqMatches":[{"year":"2012","no":1233,"q":"Which of the following describes grade 2 fracture neck femur?","o":["Incomplete fracture, medial trabeculae intact","Complete fracture with undisplaced neck","Complete fracture with ischemic head","Moderate displacement of neck, vascularity damaged"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5337, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 310, '{"id":5337,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":310,"q":"Treatment of choice for fracture neck femur in a 40 years old female","o":["Multiple screw fixation","Bipolar hemiarthroplasty","THR","None"],"a":0,"e":"Answer- A. Multiple screw fixation Placement of multiple screws across the fractured femoral neck is the treatment of choice for femoral neck fractures, and may be performed following either closed or open reduction using a standard lateral approach or a more limited percutaneous technique.","pyqMatches":[{"year":"2012","no":1234,"q":"Treatment of choice for fracture neck femur in a 40 years old female","o":["Multiple screw fixation","Bipolar hemiarthroplasty","THR","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5338, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 311, '{"id":5338,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":311,"q":"Talus is supplied by","o":["Anterior tibial artery","Posterior tibial artery","Dorsal pedis artery","All"],"a":3,"e":"Answer- D. All Extraosseous blood supply","pyqMatches":[{"year":"2012","no":1235,"q":"Talus is supplied by","o":["Anterior tibial artery","Posterior tibial artery","Dorsal pedis artery","All"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5339, 'Orthopedics', 'Spine', 'Moderate', 'Orthopedics', 312, '{"id":5339,"subject":"Orthopedics","chapter":"Spine","difficulty":"Moderate","source":"Orthopedics","sourceNo":312,"q":"Posterior scalloping of vertebrae is not seen","o":["Neurofibromatosis","Astrocytoma","Aortic aneurysm","Ependymoma"],"a":2,"e":"Answer- C. Aortic aneurysm Posterior scalloping is the concavity to the posterior aspect of the vertebral body. Anterior Scalloping is the concavity to the anterior aspect of the vertebral body.","pyqMatches":[{"year":"2012","no":1237,"q":"Posterior scalloping of vertebrae is not seen","o":["Neurofibromatosis","Astrocytoma","Aortic aneurysm","Ependymoma"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5340, 'Orthopedics', 'Spine', 'Easy', 'Orthopedics', 313, '{"id":5340,"subject":"Orthopedics","chapter":"Spine","difficulty":"Easy","source":"Orthopedics","sourceNo":313,"q":"In cervical spine injury, first to be done","o":["Trun head","Maintain airway","Immobilization of spine","None"],"a":1,"e":"Answer- B. Maintain airway \"Initial care at the accident scene may be critical to survival. The first steps are to establish an airway, maintain oxygenation and immobilize the cervical spine\".","pyqMatches":[{"year":"2012","no":1238,"q":"In cervical spine injury, first to be done","o":["Trun head","Maintain airway","Immobilization of spine","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5341, 'Orthopedics', 'Spine', 'Easy', 'Orthopedics', 314, '{"id":5341,"subject":"Orthopedics","chapter":"Spine","difficulty":"Easy","source":"Orthopedics","sourceNo":314,"q":"In scoliosis degree of deformity is calculated by","o":["Cobbs method","Hamburger method","Haldane method","Milwaukee method"],"a":0,"e":"Answer- A. Cobbs method Cobb angle is a measurement of the degree of side-to-side spinal curvature, which is a deformity you may know as scoliosis.","pyqMatches":[{"year":"2012","no":1239,"q":"In scoliosis degree of deformity is calculated by","o":["Cobbs method","Hamburger method","Haldane method","Milwaukee method"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5342, 'Orthopedics', 'Spine', 'Moderate', 'Orthopedics', 315, '{"id":5342,"subject":"Orthopedics","chapter":"Spine","difficulty":"Moderate","source":"Orthopedics","sourceNo":315,"q":"Partial anterior dislocation of one segment of the spine over another is","o":["Spondylosis","Spondylolisthesis","Kyphosis","Scoliosis"],"a":1,"e":"Answer- B. Spondylolisthesis Displacement (partial) of one vertebrae over other is called Spondylolisthesis. Spondylolisthesis is a defect in the pars interarticularis.","pyqMatches":[{"year":"2012","no":1240,"q":"Partial anterior dislocation of one segment of the spine over another is","o":["Spondylosis","Spondylolisthesis","Kyphosis","Scoliosis"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5343, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 316, '{"id":5343,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":316,"q":"In EMG/NCV study, H. reflex correlates with","o":["L3 radiculopathy","L4 radiculopathy","L5 radiculopathy","SI radiculopathy"],"a":3,"e":"Answer- D. SI radiculopathy H-Reflex has its utility in investigating patients with S1 radiculopathy.","pyqMatches":[{"year":"2012","no":1241,"q":"In EMG/NCV study, H. reflex correlates with","o":["L3 radiculopathy","L4 radiculopathy","L5 radiculopathy","SI radiculopathy"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5344, 'Orthopedics', 'Upper Limb', 'Moderate', 'Orthopedics', 317, '{"id":5344,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Moderate","source":"Orthopedics","sourceNo":317,"q":"In axillary nerve paralysis, all the following are true except","o":["Deltoid muscle is wasted","Extension of shoulder with arm abducted to 90 degrees is impossible","Small area of numbness is present over the shoulder region","Patient cannot initiate abduction"],"a":3,"e":"Answer- D. Patient cannot initiate abduction Initial 15° of abduction is caused by supraspinatus which is supplied by suprascapular nerve (not axillary nerve). \"At the initiation of abduction from neutral position, the supraspinatus is more important than deltoid, whereas deltoid (middle portion) is of greater importance for elevation of arm at the higher angle of abduction, such as 60°\".","pyqMatches":[{"year":"2012","no":1242,"q":"In axillary nerve paralysis, all the following are true except","o":["Deltoid muscle is wasted","Extension of shoulder with arm abducted to 90 degrees is impossible","Small area of numbness is present over the shoulder region","Patient cannot initiate abduction"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5345, 'Orthopedics', 'Upper Limb', 'Moderate', 'Orthopedics', 318, '{"id":5345,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Moderate","source":"Orthopedics","sourceNo":318,"q":"Carpal tunnel syndrome all are present except","o":["Ulnar nerve dysfunction","Tinel sign","Phalens sign","Pain & paraesthesia of wrist"],"a":0,"e":"Answer- A. Ulnar nerve dysfunction The symptoms often first appear during night, since many people sleep with flexed wrists. (Flexion decreases the space in carpal tunnel which results in increased pressure over median nerve). Sensory symptoms can often be reproduced by percussing over median nerve (Tina''s sign) or by holding the wrist fully flexed for a minute (Phalen''s test). As the disease progresses, clumsiness of hand and impairment of digital function develop.","pyqMatches":[{"year":"2012","no":1245,"q":"Carpal tunnel syndrome all are present except","o":["Ulnar nerve dysfunction","Tinel sign","Phalens sign","Pain & paraesthesia of wrist"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5346, 'Orthopedics', 'Pediatric Orthopedics', 'Easy', 'Orthopedics', 319, '{"id":5346,"subject":"Orthopedics","chapter":"Pediatric Orthopedics","difficulty":"Easy","source":"Orthopedics","sourceNo":319,"q":"Fairbank triangle is seen in","o":["CDH","Congenital coxa vara","Perthe''s disease","SCFE"],"a":1,"e":"Answer- B. Congenital coxa vara The epiphyseal plate may be too vertical. There may be a separate triangle of bone in the inferior portion of the metaphysis, called Fairbank''s triangle [Ref Ebnezar 4th/e p. 410]","pyqMatches":[{"year":"2012","no":1246,"q":"Fairbank triangle is seen in","o":["CDH","Congenital coxa vara","Perthe''s disease","SCFE"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5347, 'Orthopedics', 'Pediatric Orthopedics', 'Easy', 'Orthopedics', 320, '{"id":5347,"subject":"Orthopedics","chapter":"Pediatric Orthopedics","difficulty":"Easy","source":"Orthopedics","sourceNo":320,"q":"Dysplastic hip in a child, investigation of choice","o":["X-ray","MRI","USG","CT Scan"],"a":2,"e":"Answer- C. USG Ultrasonography is the investigation of choice for DDH. It visualizes the cartilage and allows dynamic testing of the hip joint.","pyqMatches":[{"year":"2012","no":1247,"q":"Dysplastic hip in a child, investigation of choice","o":["X-ray","MRI","USG","CT Scan"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5348, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 321, '{"id":5348,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":321,"q":"Primary pathology in CDH","o":["Large head of femur","Shallow acetabulum","Excessive retroversion","Everted limbus"],"a":1,"e":"Answer- B. Shallow acetabulum Following changes are seen in dislocated hip :","pyqMatches":[{"year":"2012","no":1248,"q":"Primary pathology in CDH","o":["Large head of femur","Shallow acetabulum","Excessive retroversion","Everted limbus"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5349, 'Orthopedics', 'Lower Limb', 'Hard', 'Orthopedics', 322, '{"id":5349,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Hard","source":"Orthopedics","sourceNo":322,"q":"In neglected cases of CTEV, joint fused are","o":["Calcaneocuboid, talonavicular and talocalcaneal","Tibiotalar, calcaneocuboid and talonavicular","Ankle joint, calcaneocuboid and talonavicular","None of the above"],"a":0,"e":"Answer- A. Calcaneocuboid, talonavicular and talocalcaneal Joints fused in triple arthrodesis for CTEVare i) Subtalar (tolocalcaneal) joint, ii) Calcaneocuboid joint, iii) Tolonavicular joint.","pyqMatches":[{"year":"2012","no":1249,"q":"In neglected cases of CTEV, joint fused are","o":["Calcaneocuboid, talonavicular and talocalcaneal","Tibiotalar, calcaneocuboid and talonavicular","Ankle joint, calcaneocuboid and talonavicular","None of the above"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5350, 'Orthopedics', 'Trauma & Fractures', 'Moderate', 'Orthopedics', 323, '{"id":5350,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Moderate","source":"Orthopedics","sourceNo":323,"q":"Osteonerosis is seen in all except","o":["Fracture neck femur","Sickle cell anemia","Perthe''s disease","Paget''s disease"],"a":3,"e":"Answer- D. Paget''s disease Storage disorders : - Gaucher''s disease Caisson disease : - Dysbaric osteonecrosis Hemoglobinopathy & Coagulation disorder: - Sickel cell disease, Familial thrombophilia, Hypofibrinolysis, Hypolipoproteinemia. Congenital disorders : - Perthe''s disease, Slipped capital femoral epiphysis. Hematological malignancies : - Leukemia, lymphoma, Polycythemia. Hyperlipedemia : - Nephrotic syndrome","pyqMatches":[{"year":"2012","no":1251,"q":"Osteonerosis is seen in all except","o":["Fracture neck femur","Sickle cell anemia","Perthe''s disease","Paget''s disease"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5351, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 324, '{"id":5351,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":324,"q":"After chronic use of steroids severe pain in right hip with immobility is due to","o":["Avascular necrosis","Perthes disease","Hip dislocation","Osteoarthritis"],"a":0,"e":"Answer- A. Avascular necrosis Pain in hip and limitatation of movement (immobility) ofter chronic use of steroids suggest the diagnosis of AVN of femoral head.","pyqMatches":[{"year":"2012","no":1253,"q":"After chronic use of steroids severe pain in right hip with immobility is due to","o":["Avascular necrosis","Perthes disease","Hip dislocation","Osteoarthritis"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5352, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 325, '{"id":5352,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":325,"q":"In elbow, osteochondritis usually involves","o":["Olecranon","Trochlea","Radial head","Capitulum"],"a":3,"e":"Answer- D. Capitulum Knee- Lateral surface of the medial femoral condyle Elbow- Capitulum of humerus Hip- Femoral head Ankle- Talus","pyqMatches":[{"year":"2012","no":1254,"q":"In elbow, osteochondritis usually involves","o":["Olecranon","Trochlea","Radial head","Capitulum"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5353, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 326, '{"id":5353,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":326,"q":"Most common organism causing infection after open fracture","o":["Pseudomonas","Staphylococcus aureus","Klebsiella","Gonococcus"],"a":0,"e":"Answer- A. Pseudomonas staphylococcus aureus was the most common organism causing infection in open fractures. More recent studies have shown that gram negative organisms such as pseudomonas aeruginosa and E.coli are becoming more common","pyqMatches":[{"year":"2012","no":1255,"q":"Most common organism causing infection after open fracture","o":["Pseudomonas","Staphylococcus aureus","Klebsiella","Gonococcus"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5354, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 327, '{"id":5354,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":327,"q":"Septic arthritis is diagnosed by","o":["X-ray","Joint aspiration","USG","MRI"],"a":1,"e":"Answer- B. Joint aspiration Quickest and best method of diagnosis of septic arthritis is aspiration of joint.","pyqMatches":[{"year":"2012","no":1256,"q":"Septic arthritis is diagnosed by","o":["X-ray","Joint aspiration","USG","MRI"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5355, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 328, '{"id":5355,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":328,"q":"Sequestrum is best defined as","o":["A piece of dead bone","A piece of dead bone surrounded by infected tissue","A piece of bone with poor vascularity","None"],"a":1,"e":"Answer- B. A piece of dead bone surrounded by infected tissue Sequestrum is a piece of dead bone, surrounded by infected granulation tissue.","pyqMatches":[{"year":"2012","no":1257,"q":"Sequestrum is best defined as","o":["A piece of dead bone","A piece of dead bone surrounded by infected tissue","A piece of bone with poor vascularity","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5356, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 329, '{"id":5356,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":329,"q":"Cloacae are present in","o":["Sequestrum","Involucrum","Normal bone","Myositis"],"a":1,"e":"Answer- B. Involucrum Involucrum is reactive new bone overlying a sequestrum. There may be some holes in the involucrum for pus to drain out. These holes are called cloaca.","pyqMatches":[{"year":"2012","no":1258,"q":"Cloacae are present in","o":["Sequestrum","Involucrum","Normal bone","Myositis"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5357, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 330, '{"id":5357,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":330,"q":"Complication of joint TB","o":["Fibrous ankylosis","Bony ankylosis","Normal healing","None"],"a":0,"e":"Answer- A. Fibrous ankylosis The outcome of tubercular arthritis is fibrous ankylosis, except in spine. Spine is the only site where tuberculosis heals with bony ankylosis.","pyqMatches":[{"year":"2012","no":1259,"q":"Complication of joint TB","o":["Fibrous ankylosis","Bony ankylosis","Normal healing","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5358, 'Orthopedics', 'Spine', 'Easy', 'Orthopedics', 331, '{"id":5358,"subject":"Orthopedics","chapter":"Spine","difficulty":"Easy","source":"Orthopedics","sourceNo":331,"q":"False about Pott''s spine","o":["Commonest at dorsolumbar junction","Always heals by chemotherapy","Back pain is an early symptom","There is disc space narrowing on x-ray"],"a":1,"e":"Answer- B. Always heals by chemotherapy Chemotherapy is the mainstay of treatment. But it is not effective always, surgery is often required in some cases. Commonest site of pott''s spine is dorsolumbar junction. Back pain is the earliest symptom and narrowing of disc space is the earliest radiological sign.","pyqMatches":[{"year":"2012","no":1260,"q":"False about Pott''s spine","o":["Commonest at dorsolumbar junction","Always heals by chemotherapy","Back pain is an early symptom","There is disc space narrowing on x-ray"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5359, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 332, '{"id":5359,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":332,"q":"Apparent lengthening is seen in which stage of TB Hip","o":["Stage I","Stage II","Stage III","None"],"a":0,"e":"Answer- A. Stage I Stage of synovitis (Stage 1) : - Three is effusion in the hip joint which demands the hip to be in a position of maximum capacity. This position is acquired by flexion, abduction and external rotation. Because of abduction deformity, there is apparent lengthening.","pyqMatches":[{"year":"2012","no":1261,"q":"Apparent lengthening is seen in which stage of TB Hip","o":["Stage I","Stage II","Stage III","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5360, 'Orthopedics', 'Spine', 'Easy', 'Orthopedics', 333, '{"id":5360,"subject":"Orthopedics","chapter":"Spine","difficulty":"Easy","source":"Orthopedics","sourceNo":333,"q":"Tuberculosis spine; most common site is","o":["Sacral","Cevical","Dorsolumbar","Lumbosacral"],"a":2,"e":"Answer- C. Dorsolumbar The most common site is Dorsolumbar region. Lower dorsal (thoracic) region is the most common segment involved followed by lumbar segment. The tuberculosis of spine is also called pott''s disease or tubercular spondylytis.","pyqMatches":[{"year":"2012","no":1262,"q":"Tuberculosis spine; most common site is","o":["Sacral","Cevical","Dorsolumbar","Lumbosacral"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5361, 'Orthopedics', 'Upper Limb', 'Easy', 'Orthopedics', 334, '{"id":5361,"subject":"Orthopedics","chapter":"Upper Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":334,"q":"Anterolateral decompression is done for","o":["Spinal tuberculosis","Chest TB","Hand TB","Foot TB"],"a":0,"e":"Answer- A. Spinal tuberculosis Anterior decompression can be caused by : -","pyqMatches":[{"year":"2012","no":1263,"q":"Anterolateral decompression is done for","o":["Spinal tuberculosis","Chest TB","Hand TB","Foot TB"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5362, 'Orthopedics', 'Bone Tumors', 'Easy', 'Orthopedics', 335, '{"id":5362,"subject":"Orthopedics","chapter":"Bone Tumors","difficulty":"Easy","source":"Orthopedics","sourceNo":335,"q":"Tumor with maximum bone matrix","o":["Osteoid osteoma","Chondrosarcoma","Enchondroma","None"],"a":0,"e":"Answer- A. Osteoid osteoma Dense, homogenous mineralization (calcification) is typical of osteoid matrix, formed by benign and malignant bone forming lesions.","pyqMatches":[{"year":"2012","no":1264,"q":"Tumor with maximum bone matrix","o":["Osteoid osteoma","Chondrosarcoma","Enchondroma","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5363, 'Orthopedics', 'Bone Tumors', 'Easy', 'Orthopedics', 336, '{"id":5363,"subject":"Orthopedics","chapter":"Bone Tumors","difficulty":"Easy","source":"Orthopedics","sourceNo":336,"q":"Which of the following is true about Giant cell tumor","o":["Usually presents as a lytic lesion with sclerotic rim","Always beingn","Epiphyseal origin","Seen in age less than 15 years"],"a":2,"e":"Answer- C. Epiphyseal origin GCT is an osteolytic tumor arising from the epiphysis and is common between the age of 20-40 years. The commonest sites are lower end of femur and upper end of tibia. Other common sites are lower end radius and upper end of humerus. It may also occur in the spine and sacrum. The radiological features are : -","pyqMatches":[{"year":"2012","no":1265,"q":"Which of the following is true about Giant cell tumor","o":["Usually presents as a lytic lesion with sclerotic rim","Always beingn","Epiphyseal origin","Seen in age less than 15 years"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5364, 'Orthopedics', 'Spine', 'Easy', 'Orthopedics', 337, '{"id":5364,"subject":"Orthopedics","chapter":"Spine","difficulty":"Easy","source":"Orthopedics","sourceNo":337,"q":"Striated vertebra is seen in","o":["TB spine","Haemangioma","Chordoma","Metastasis"],"a":1,"e":"Answer- B. Haemangioma Haemangioma of the vertebra has a typical radiographic picture in the form of loss of horizontal striations and prominence of vertebral striations. There is Polka dot appearance on CT. In the skull, hemangioma generally affects the calverium and is seen as an expansile lytic lesion which has a sunburst appearance with striation radiating from the centre. A hemangioma may be identified due to associated phlebolith and it may cause local gigantism of the invovled area.","pyqMatches":[{"year":"2012","no":1266,"q":"Striated vertebra is seen in","o":["TB spine","Haemangioma","Chordoma","Metastasis"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5365, 'Orthopedics', 'Spine', 'Moderate', 'Orthopedics', 338, '{"id":5365,"subject":"Orthopedics","chapter":"Spine","difficulty":"Moderate","source":"Orthopedics","sourceNo":338,"q":"Metastasis not found in","o":["Femur","Humerus","Fibula","Spine"],"a":2,"e":"Answer- C. Fibula Metastatic bone disease is the commonest malignancy of bones and is much more common than primary bone tumors. The commonest sites for bone metastases are vertebrae (most common), pelvis, the proximal half of the femur and the humerus. Extremities distal to elbow and knee are least commonly involved sites. Spread is usually via the blood stream; occasionally, visceral tumors spread directly into adjacent bones e.g., the pelvis and ribs.","pyqMatches":[{"year":"2012","no":1267,"q":"Metastasis not found in","o":["Femur","Humerus","Fibula","Spine"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5366, 'Orthopedics', 'Bone Tumors', 'Easy', 'Orthopedics', 339, '{"id":5366,"subject":"Orthopedics","chapter":"Bone Tumors","difficulty":"Easy","source":"Orthopedics","sourceNo":339,"q":"Periosteal reactions is seen in","o":["Osteomyelitis","Syphilis","Tumor","All"],"a":3,"e":"Answer- D. All Infection :- Osteomyelitis, Brodie''s abscess, syphilis Neoplasms Benign : Osteoid osteoma Malignant : Ewing''s sarcoma, osteosarcoma Eosinophilic granuloma Healed stress fracture Hypertrophic pulmonary osteoarthropathy","pyqMatches":[{"year":"2012","no":1268,"q":"Periosteal reactions is seen in","o":["Osteomyelitis","Syphilis","Tumor","All"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5367, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 340, '{"id":5367,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":340,"q":"Volkmanns contracture, which artery is involved","o":["Radial","Brachial","Ulnar","Interosseus"],"a":1,"e":"Answer- B. Brachial Injury to brachial artery may cause nerve and muscle ischemia (Volkmann''s ischemia of flexor compartment) or may result in postischemic swelling due to edema or hemorrhage, thereby causing compartment syndrome, which can cause, if not treated immediatealy, Volkmann''s ischaemic contracture later on.","pyqMatches":[{"year":"2012","no":1269,"q":"Volkmanns contracture, which artery is involved","o":["Radial","Brachial","Ulnar","Interosseus"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5368, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 341, '{"id":5368,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":341,"q":"Cast syndrome is due to","o":["Above elbow cast","Below elbow cast","Hip Spica","Above knee cast"],"a":2,"e":"Answer- C. Hip Spica Cast syndrome (Superior mesentric artery syndrome) is gastric dilatation with partial or complete obstruction of the duodenum. It is most frequently seen in orthopaedics patients who have had spinal surgery or who are in hip spica or body casts.","pyqMatches":[{"year":"2012","no":1270,"q":"Cast syndrome is due to","o":["Above elbow cast","Below elbow cast","Hip Spica","Above knee cast"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5369, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 342, '{"id":5369,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":342,"q":"Heterotopic ossification occurs in","o":["Bone","Joint","Soft tissue","None"],"a":2,"e":"Answer- C. Soft tissue Heterotopic ossification is the process by which bone tissue is formed in soft tissue outside the skeleton.","pyqMatches":[{"year":"2012","no":1271,"q":"Heterotopic ossification occurs in","o":["Bone","Joint","Soft tissue","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5370, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 343, '{"id":5370,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":343,"q":"Felon most common complication","o":["Osteomyelitis","Subungual hematoma","Infective arthritis","None"],"a":0,"e":"Answer- A. Osteomyelitis Felon is the infection of distal pulp space. Next to acute paranychia, this is the most common hand infection. It usually follows a pinprick, with index finger and thumb being the common unfortunate victim. The patient initially complains of dull pain and swelling. Complications are osteomyelitis (most common), skin necrosis, osteonecrosis of digits and rarely tenosynovitis or infective arthritis of DIP joint.","pyqMatches":[{"year":"2012","no":1272,"q":"Felon most common complication","o":["Osteomyelitis","Subungual hematoma","Infective arthritis","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5371, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 344, '{"id":5371,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":344,"q":"Most common bone for which nailing is done","o":["Radius","Ulna","Tibia","Humerus"],"a":2,"e":"Answer- C. Tibia Most common bones for which intramedullary nailing is done are Tibia and femur.","pyqMatches":[{"year":"2012","no":1275,"q":"Most common bone for which nailing is done","o":["Radius","Ulna","Tibia","Humerus"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5372, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 345, '{"id":5372,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":345,"q":"Why fracture shaft femur is early stabilised","o":["To prevent blood loss","ARDS","Non union","Compartment syndrome"],"a":0,"e":"Answer- A. To prevent blood loss Fracture shaft femur can cause upto 2L of blood loss and severe hypotension, if not immoblized early. the fracture shaft femur should be immoblized early. This can be temporary immobilization by TT splint followed by surgery or can be by immediate surgery.","pyqMatches":[{"year":"2012","no":1277,"q":"Why fracture shaft femur is early stabilised","o":["To prevent blood loss","ARDS","Non union","Compartment syndrome"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5373, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 346, '{"id":5373,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":346,"q":"Drug used in osteoarthritis","o":["Methotrexate","Glucosamine","Sulfasalizine","All"],"a":1,"e":"Answer- B. Glucosamine Chondroitin sufate Disease modifying anti-osteoarthritis drugs (DMAOAD) Diacerin (IL- 1 antagonist), Licofelone (combined COX-LOX inhibitors) Steroids (in acute exacerbations).","pyqMatches":[{"year":"2012","no":1278,"q":"Drug used in osteoarthritis","o":["Methotrexate","Glucosamine","Sulfasalizine","All"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5374, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 347, '{"id":5374,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":347,"q":"Pannus is seen in","o":["OA","RA","Gout","None"],"a":1,"e":"Answer- B. RA Pannus is seen in rheumatoid arthritis. It is neoplasm-like growth of inflammed synovial tissue that leads to destruction of joint structures. The articular cartilage at pannus interface appear to undergo chondrolysis. Pannus appear to develop within and around the synovium, subsequently creeping into and over the articular cartilage and enveloping it and the underlying bone in a deathlike grasp.","pyqMatches":[{"year":"2012","no":1279,"q":"Pannus is seen in","o":["OA","RA","Gout","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5375, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 348, '{"id":5375,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":348,"q":"Sausage digits is seen in","o":["Lyme arthritis","Osteoarthritis","Psoriatic arthritis","None"],"a":2,"e":"Answer- C. Psoriatic arthritis Sausage digit refers to diffuse fusiform swelling of the digit due to soft tissue inflammation from underlying arthritis or dactylitis. Causes are :- Psoriatic arthritis Osteomyelitis Sickle cell anemia Sarcoidosis Tubercular dactylitis (spina ventosa)","pyqMatches":[{"year":"2012","no":1280,"q":"Sausage digits is seen in","o":["Lyme arthritis","Osteoarthritis","Psoriatic arthritis","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5376, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 349, '{"id":5376,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":349,"q":"Green stick fracture is","o":["Fracture in adults","Complete fracture","Incomplete fracture","Fracture spine"],"a":2,"e":"Answer- C. Incomplete fracture A greenstick fracture is an incomplete transverse fracture pattern seen in children.","pyqMatches":[{"year":"2012","no":1281,"q":"Green stick fracture is","o":["Fracture in adults","Complete fracture","Incomplete fracture","Fracture spine"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5377, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 350, '{"id":5377,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":350,"q":"Resorption of distal phalanx is seen in","o":["Scleroderma","Hyperparathyroidism","Reiter''s syndrome","All"],"a":3,"e":"Answer- D. All Acro-osteolysis is the term used to describe resorption of the distal phalangeal tufts. Causes are : -","pyqMatches":[{"year":"2012","no":1282,"q":"Resorption of distal phalanx is seen in","o":["Scleroderma","Hyperparathyroidism","Reiter''s syndrome","All"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5378, 'Orthopedics', 'Lower Limb', 'Easy', 'Orthopedics', 351, '{"id":5378,"subject":"Orthopedics","chapter":"Lower Limb","difficulty":"Easy","source":"Orthopedics","sourceNo":351,"q":"Foot drop is caused by injury to which nerve involvement:","o":["Femoral nerve","Tibial nerve","Common peroneal nerve","Sciatic nerve"],"a":2,"e":"Answer C) Common Peroneal Nerve Foot drop, sometimes called drop foot, is a general term for difficulty lifting the front part of the foot. Causes Foot drop is caused by weakness or paralysis of the muscles involved in lifting the front part of the foot. Causes of foot drop might include:","pyqMatches":[{"year":"2019","no":193,"q":"Foot drop is caused by injury to which nerve involvement:","o":["Femoral nerve","Tibial nerve","Common peroneal nerve","Sciatic nerve"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5379, 'Orthopedics', 'Miscellaneous', 'Easy', 'Orthopedics', 352, '{"id":5379,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Easy","source":"Orthopedics","sourceNo":352,"q":"Muscles affected in De quervain tenosynovitis -","o":["Abductor pollicis longus and extensor pollicis brevis","Adductor pollicis longus and extensor pollicis brevis","Abductor pollicis longus and Flexor pollicis brevis","Adductor pollicis longus and Flexor pollicis brevis"],"a":0,"e":"Ans. A. Abductor pollicis longus and extensor pollicis brevis De Quervain syndrome, is a tenosynovitis of the sheath or tunnel that surrounds two tendons that control movement of the thumb. De Quervain syndrome involves non-inflammatory thickening of the tendons and the synovial sheaths that the tendons run through. The two tendons concerned are those of the extensor pollicis brevis and abductor pollicis longus muscles.","pyqMatches":[{"year":"2018","no":162,"q":"Muscles affected in De quervain tenosynovitis","o":["Abductor pollicis longus and extensor pollicis brevis","Adductor pollicis longus and extensor pollicis brevis","Abductor pollicis longus and Flexor pollicis brevis","Adductor pollicis longus and Flexor pollicis brevis"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5380, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 353, '{"id":5380,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":353,"q":"What is meant by Perilunate dislocations ?","o":["Lower radius,scaphoid and lunate and capitate all in same plane","Lower radius,scaphoid and capitate in alignment,lunate alone out of plane","Lower radius,scaphoid and Lunate in alignment ,capitate alone is out of plane","Both lunate and capitate are out of plane"],"a":1,"e":"Ans. B.Lower radius,scaphoid and capitate in alignment,lunate alone out of plane Perilunate dislocation and perilunate fracture dislocation are injuries that involve traumatic rupture of the radioscaphocapitate (RSC) ligament, the scapholunate interosseous ligament, and the lunotriquetral interosseous ligament. Lateral radiographs will reveal loss of collinearity between the capitate, lunate, and radius Typically the capitate is located dorsal to the lunate and is aligned with the radius","pyqMatches":[{"year":"2018","no":163,"q":"What is meant by Perilunate dislocations ?","o":["Lower radius,scaphoid and lunate and capitate all in same plane","Lower radius,scaphoid and capitate in alignment,lunate alone out of plane","Lower radius,scaphoid and Lunate in alignment ,capitate alone is out of plane","Both lunate and capitate are out of plane"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5381, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 354, '{"id":5381,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":354,"q":"Fallen fragment sign -","o":["Simple bone cyst","Osteosarcoma","Adamantinoma","Aneurysmal bone cyst"],"a":0,"e":"Ans. A. Simple bone cyst The fallen fragment sign refers to the presence of a bone fracture fragment resting dependently in a cystic bone lesion. This finding is said to be pathognomonic for a simple (unicameral) bone cyst following a pathological fracture. Although it has occasionally been reported with other cystic lesions, e.g. eosinophilic granuloma","pyqMatches":[{"year":"2018","no":164,"q":"Fallen fragment sign","o":["Simple bone cyst","Osteosarcoma","Adamantinoma","Aneurysmal bone cyst"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5382, 'Orthopedics', 'Trauma & Fractures', 'Hard', 'Orthopedics', 355, '{"id":5382,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Hard","source":"Orthopedics","sourceNo":355,"q":"You are posted as an intern in causality.Which among the following patients with fracture will be your 1st priority to call ortho PG and inform?","o":["Patient''s finger is blackening","Patient can''t extend his arm","A 10 cm abrasion","Intra articular fracture of Elbow Joint"],"a":0,"e":"Ans. A. Patient''s finger is blackening Blackening of finger after Fracture is an indication of cut of of blood supply that may lead to severe complication like gangrene. So this should be the first Priority to treat among all the above options","pyqMatches":[{"year":"2018","no":165,"q":"You are posted as an intern in causality.Which among the following patients with fracture will be your 1st priority to call ortho PG and inform?","o":["Patient''s finger is blackening","Patient can''t extend his arm","A 10 cm abrasion","Intra articular fracture of Elbow Joint"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5383, 'Orthopedics', 'Arthritis & Joint Disease', 'Easy', 'Orthopedics', 356, '{"id":5383,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Easy","source":"Orthopedics","sourceNo":356,"q":"In Rheumatoid arthritis, which type of cells are prominently present ?","o":["B cells","T cells","Macrophages","Dendritic cells"],"a":2,"e":"Ans. C. Macrophages Synovial lining or intimal layer: Normally, this layer is only 1-3 cells thick. In RA, this lining is greatly hypertrophied (8-10 cells thick). Primary cell populations in this layer are fibroblasts and macrophages.","pyqMatches":[{"year":"2018","no":166,"q":"In Rheumatoid arthritis, which type of cells are prominently present ?","o":["B cells","T cells","Macrophages","Dendritic cells"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5384, 'Orthopedics', 'Spine', 'Easy', 'Orthopedics', 357, '{"id":5384,"subject":"Orthopedics","chapter":"Spine","difficulty":"Easy","source":"Orthopedics","sourceNo":357,"q":"8th and 9th rib costal cartilage forms which type of joint?","o":["Costochondral joint","Interchondral joint","Synovial joint","Costovertebral joint"],"a":2,"e":"Ans. C. Synovial joint The sixth, seventh, eighth, ninth and tenth costal cartilages are jointed with each other along the borders by synovial joints. Costochondral joint means the joint between the rib and its costal cartilage. The first costal cartilage of both sides attach to the manubrium sterni. At this joint, no movement is possible. The second costal cartilage articulates with the body of sternum and the manubrium sterni by a synovial joint where movement is possible. The third to seventh costal cartilages articulate with lateral border of the body of sternum at mobile synovial joints.","pyqMatches":[{"year":"2018","no":167,"q":"8th and 9th rib costal cartilage forms which type of joint?","o":["Costochondral joint","Interchondral joint","Synovial joint","Costovertebral joint"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5385, 'Orthopedics', 'Trauma & Fractures', 'Easy', 'Orthopedics', 358, '{"id":5385,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Easy","source":"Orthopedics","sourceNo":358,"q":"Tom smith septic arthritis is-","o":["Acute Gonococcal arthritis","Smallpox arthritis","Septic arthritis of infancy","Chronic pyogenic arthritis"],"a":2,"e":"Ans. C. Septic arthritis of infancy Septic arthritis of infancy (Tom smith septic arthritis) It is a septic arthritis of hip seen in infants The onset is acute with rapid abscess formation, which may burst out or be incised and heals rapidly. Telescope test is positive Clinically this condition resembles a congenital dislocation of hip","pyqMatches":[{"year":"2018","no":168,"q":"Tom smith septic arthritis is","o":["Acute Gonococcal arthritis","Smallpox arthritis","Septic arthritis of infancy","Chronic pyogenic arthritis"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5386, 'Orthopedics', 'Miscellaneous', 'Moderate', 'Orthopedics', 359, '{"id":5386,"subject":"Orthopedics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Orthopedics","sourceNo":359,"q":"A woman developed pain and crawling sensation on her legs at night. Clinical history of restless leg syndrome. Drug of choice?.","o":["Pramipexole","Gabapentin","Vitamin B12","Iron tablets"],"a":0,"e":"Ans.a pramipexole Restless leg syndrome : Subjective sensation \"creepy-crawly\" feeling in the limbs, and irresistible urge to move the legs when at rest or while trying to fall asleep. When the individual is lying in bed and relaxing, he or she is disturbed by these sensations. Then he or she moves the legs and again tries to fall asleep. This cycle sometimes continues for hours and results in profound insomnia. Treatment: The dopaminergic agonists’ pramipexole and ropinirole are FDA approved and represent the treatments of choice. Ref. Kaplan and Sadock''s Synopsis of Psychiatry - 11th Edition (Page no 559)","pyqMatches":[{"year":"2020","no":206,"q":"A woman developed pain and crawling sensation on her legs at night. Clinical history of restless leg syndrome. Drug of choice?.","o":["Pramipexole","Gabapentin","Vitamin B12","Iron tablets"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5387, 'Orthopedics', 'Arthritis & Joint Disease', 'Hard', 'Orthopedics', 360, '{"id":5387,"subject":"Orthopedics","chapter":"Arthritis & Joint Disease","difficulty":"Hard","source":"Orthopedics","sourceNo":360,"q":"History of Arthritis involving 1st MCP joint, other PIP & DIP joints, spares wrist and ankle. What could be the diagnosis","o":["Osteoarthritis","Rheumatoid arthritis","Psoriatic arthritis","Gout"],"a":0,"e":"Ans: a.Osteoarthritis >The distal interphalangeal (DIP) joint is actually the most common location on the body for osteoarthritis (OA). >The frequency of hand arthritis, OA at the DIP joint occurs in approximately 58% of individuals. >The symptoms of OA at the DIP joint commonly include pain and changes to the size and shape of the joint. https://www.3pointproducts.com/blog/health-arthritis-finger- and-toe-conditions/dip-joint-osteoarthritis-how-to-treat-this- common-form-of-arthritis","pyqMatches":[{"year":"2020","no":207,"q":"History of Arthritis involving 1st MCP joint, other PIP & DIP joints, spares wrist and ankle. What could be the diagnosis","o":["Osteoarthritis","Rheumatoid arthritis","Psoriatic arthritis","Gout"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5388, 'Orthopedics', 'Trauma & Fractures', 'Hard', 'Orthopedics', 361, '{"id":5388,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Hard","source":"Orthopedics","sourceNo":361,"q":"12 yr old Child admitted to ICU with blunt trauma and femur fracture- Pao2 60% despite 100%o2 and rebreather mask, CXR shows lung fields clear but the patient remains confused. What is most likely the diagnosis -","o":["Pulmonary contusion.","Fat embolism syndrome.","Hypovolaemic shock.","Pulmonary embolism."],"a":1,"e":"Ans: b. Fat embolism. In this patient, based on the case presentation there is Respiratory System involved as pao2 is 60, and CNS involvement as he is in a confused state. >So, the diagnosis here is Fat embolism syndrome. >Embolized fat within capillary beds cause direct tissue damage as well as induce a systemic inflammatory response resulting in pulmonary, cutaneous, neurological, and retinal symptoms. >Gurd''s clinical description of the FES renewed interest in studying this syndrome https://www.ncbi.nlm.nih.gov/pmc/articles/PMC3665122/","pyqMatches":[{"year":"2020","no":208,"q":"12 yr old Child admitted to ICU with blunt trauma and femur fracture- Pao2 60% despite 100%o2 and rebreather mask, CXR shows lung fields clear but the patient remains confused. What is most likely the diagnosis","o":["Pulmonary contusion.","Fat embolism syndrome.","Hypovolaemic shock.","Pulmonary embolism."],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5389, 'Orthopedics', 'Trauma & Fractures', 'Hard', 'Orthopedics', 362, '{"id":5389,"subject":"Orthopedics","chapter":"Trauma & Fractures","difficulty":"Hard","source":"Orthopedics","sourceNo":362,"q":"A 4 yr old child while playing suddenly spun around his elbow from her servant maid''s hand and now continuously crying not allowing anyone to touch his elbow. He is keeping his elbow extended .what is most likely the diagnosis -","o":["Radial head fracture","Pulled elbow","supra condylar fracture","Elbow dislocation"],"a":1,"e":"Ans: b. Pulled elbow >Pulled elbow, also called nursemaid’s elbow, is a radial head subluxation caused by axial traction or a sudden pull of the extended pronated arm, and it is a very common phenomenon. >In this case of pulled elbow, the child usually avoids moving the affected arm, holding it close to his or her body, without considerable pain, and no obvious swelling or deformity can be seen. >While a fracture should be excluded, the pulled elbow can usually be identified based on this presentation. https://www.ncbi.nlm.nih.gov/pmc/articles/PMC5999240/","pyqMatches":[{"year":"2020","no":209,"q":"A 4 yr old child while playing suddenly spun around his elbow from her servant maid''s hand and now continuously crying not allowing anyone to touch his elbow. He is keeping his elbow extended .what is most likely the diagnosis","o":["Radial head fracture","Pulled elbow","supra condylar fracture","Elbow dislocation"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5390, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 1, '{"id":5390,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":1,"q":"Savlon contains","o":["Cetrimide + Chlorhexidine","Cetrimide + Chlorhexidine + butyl alcohol","Cetrimide + butyl alcohol","Cetrimide + Cetavlon"],"a":0,"e":"Ans : A.Cetrimide + chlorhexidine [Ref KDT pharmacology 6/e, p 861, 860; Park 20/e, p 117] Savlon contains - Chlorhexidine gluconate (hibitane) + Cetrimide (cetavlon) in various percentages Savlon liquid antiseptic - chlorhexidine gluconate 1.5% + cetrimide 3% Savlon cream - chlorhexidine HC1 0.1% + cetrimide 0.5% Savlon hospital concentrate - chlorhexidine gluconate 7.5% + cetrimide 15% Other antiseptic and disinfectants of importance: Betadine - povidone (polyvinylpyrrolidone) iodine Dettol - chloroxylenol 4.8% in 9% terpinol & 13% alcohol Dakin''s solution - Diluted sodium hypochlorite solution buffered with boric acid. Available chlorine is 0.5%. Eusol - Solution of chlorinated lime (1.25%) + boric acid (L25%) 0.4% available chlorine Dakin''s solution & Eusol dissolve pus & necrotic tissue in addition to being germicidal. So used in cleaning of infected wound.","pyqMatches":[{"year":"2016","no":687,"q":"Savlon contains","o":["Cetrimide + Chlorhexidine","Cetrimide + Chlorhexidine + butyl alcohol","Cetrimide + butyl alcohol","Cetrimide + Cetavlon"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5391, 'PSM', 'Demography & Family Planning', 'Moderate', 'Preventive_&_Social_Medicine', 2, '{"id":5391,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":2,"q":"True about ASHA are all except","o":["One per 1000 rural population","Mobiliser of antenatal care","Female voluntary worker","Skilled birth attendant"],"a":3,"e":"skilled birth attendant /Ref: Park 20/e, p 380-381 (19k, p 365)1 Ref. littp://molifw.nic.in/NRHM/stakeholders.htm ASHA is the central component of the National Rural Health Mission (NRHM) National Rural Health Mission (NRHM) was launched to address the health needs of rural population, especially the vulnerable sections of society One of the key components of the National Rural Health Mission is to provide every village in the country with a trained female community health activist — `ASHA'' or Accredited Social Health Activist. Selected from the villa itself and accountable to it, the ASHA will he trained to work as an interface between the community and the public e health system. Following are the key components of ASHA: ASHA must primarily be a woman resident of the village — married/ widowed/ divorced, preferably in the age group of 25 to 45 years. She should be a literate woman with formal education up to class eight. This may be relaxed only if no suitable person with this qualification is available. ASHA will be the first port of call for any health related demands of deprived sections of the population, especially women and children, who find it difficult to access health services ASHA will be a health activist in the community who will create awareness on health and its social determinantsand mobilize the community towards local health planning and incareased utilization and accountability of the existing health services. She would be a promoter of good health practices. She will counsel women on birth preparedness, importance of safe delivery, breastfeeding and complementary feeding, immunization, contraception and prevention of common infections including Reproductive Tract Infection/Sexually Transmitted Infection (RT1s/STIs) and care of the young child The gynaecomastia causing drugs can he categorized into : The first type are drugs that act exactly like estrogens, such as diethylstilbestrol, birth control pills, digitalis, and estrogen containing cosmetics. The second type is drugs that enhance endogenous estrogen formation such as gonadotropins and clomiphene. The third type is drugs that inhibit testosterone synthesis and action such as spironolactone, ketoconazole, metronidazole and cimetidine. The final type is drugs that act by unknown mechanisms such as isoniazid, methyldopa, captopril, tricyclic antidepressants, diazepam and heroin. Also know, Testosterone also causes Gynaecomastia","pyqMatches":[{"year":"2015","no":914,"q":"True about ASHA are all except","o":["One per 1000 rural population","Mobiliser of antenatal care","Female voluntary worker","Skilled birth attendant"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5392, 'PSM', 'Demography & Family Planning', 'Moderate', 'Preventive_&_Social_Medicine', 3, '{"id":5392,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":3,"q":"To eradicate measles the percentage of population to be vaccinated is at least............%","o":["70","80","85","95"],"a":3,"e":"95","pyqMatches":[{"year":"2012","no":801,"q":"To eradicate measles the percentage of population to be vaccinated is at least............%","o":["70","80","85","95"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5393, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 4, '{"id":5393,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":4,"q":"Which of the following trace element has vitamin E like action:","o":["Selenium","Cheomycin","Copper","Zinc"],"a":0,"e":"Selenium","pyqMatches":[{"year":"2013","no":347,"q":"Which of the following trace element has vitamin E like action:","o":["Selenium","Cheomycin","Copper","Zinc"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5394, 'PSM', 'National Health Programmes', 'Moderate', 'Preventive_&_Social_Medicine', 5, '{"id":5394,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":5,"q":"True about NPCDCS is all, EXCEPT:","o":["Separate centre for stroke, DM","Implementation in some 5 states over 10 district","CHC has facilities for diagnosis and treatment of CVD, Diabetes","Day care facilities are available at subcentre"],"a":2,"e":"The NPCDCS program has two components viz. (i) Cancer & (ii) Diabetes, CVDs & stroke. These two components have been integrated at different levels as far as possible for optimal utilization of the resource. The activities at State, District, CHC and Sub Centre level have been planned under the programme and will be closely monitored through NCD cell at different levels. The strategies proposed will be implemented in 20,000 Sub Centres and 700 Community Health Centre in 100 Districts across 21 States during 2010-12 Early diagnosis of diabetes, CVDs, Stroke and Cancer is done at District Hospital, not at CHC. Ref: NPCDCS Operational Guidelines, DGHS, GOI, Page 6; http:/health.bih.nic.in/Docs/Guidelines-NPCDCS.pdf.","pyqMatches":[{"year":"2016","no":881,"q":"True about NPCDCS is all, EXCEPT:","o":["Separate centre for stroke, DM","Implementation in some 5 states over 10 district","CHC has facilities for diagnosis and treatment of CVD, Diabetes","Day care facilities are available at subcentre"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5395, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 6, '{"id":5395,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":6,"q":"Cluster testing technique is useful in which of the following conditions?","o":["Sexually Transmitted Diseases","Poliomyelitis","Measles","Smallpox"],"a":0,"e":"Explanation: Following methods are used for case detection of STD: • CONTACT TRACING: Contact tracing is the term used for the technique by which the sexual partners of diagnosed patients are identified, located, investigated, and treated. • CLUSTER TESTING: Here the patients are asked name other persons of either sex who move in the same socio-sexual environment. These persons are then screened. Ref: Park’s textbook of Preventive and Social Medicine, 21stedition, Page 313","pyqMatches":[{"year":"2014","no":972,"q":"Cluster testing technique is useful in which of the following conditions?","o":["Sexually Transmitted Diseases","Poliomyelitis","Measles","Smallpox"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5396, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 7, '{"id":5396,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":7,"q":"Which of the following is false about intra- uterine devices (IUDs)?","o":["Multiload Cu-375 is a third generation intra-uterine device (IUD)","Copper devices are effective as post-coital contraceptives","LNG-20 (Mirena) has an effective life of 5 years","Pregnancy rates of Lippes Loop and T Cu-200 are similar"],"a":0,"e":"Multioad Cu-375 is a newer copper intra-uterine device (IUD). The copper devices comprise the second generation IUDs. The non-medicated or inert devices are the first generation IUDs and the hormone-releasing devices are the third generation IUDs Ref: Park’s Textbook Of Preventive And Social Medicine, By K. Park, 19th Edition, Pages 393-395.","pyqMatches":[{"year":"2016","no":853,"q":"Which of the following is false about intra-uterine devices (IUDs)?","o":["Multiload Cu-375 is a third generation intra-uterine device (IUD)","Copper devices are effective as post-coital contraceptives","LNG-20 (Mirena) has an effective life of 5 years","Pregnancy rates of Lippes Loop and T Cu-200 are similar"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5397, 'PSM', 'Demography & Family Planning', 'Moderate', 'Preventive_&_Social_Medicine', 8, '{"id":5397,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":8,"q":"Which of the following statements about ''Late Expanding Phase of Demographic Cycle'' is TRUE?","o":["Birth Rate is lower than Death Rate","High Death Rate and High Birth Rate","Death Rate declines more than Birth Rate","Death Rate begins to decline while Birth Rate remains unchanged"],"a":2,"e":"In late expanding phase of demographic cycle death rates declines faster than the birth rate and there is a steady decrease in the demographic gap. In this state population grow at a steadily decreasing rate. Most of the developing countries are now at early expanding and late expanding stages of demographic cycle. Ref: Park’s Textbook of Preventive and Social Medicine By K. Park, 19th Edition, Page 379; Foundations of Community Medicine By Dhaar, 2nd Edition, Page 667","pyqMatches":[{"year":"2012","no":838,"q":"Which of the following statements about ''Late Expanding Phase of Demographic Cycle'' is TRUE?","o":["Birth Rate is lower than Death Rate","High Death Rate and High Birth Rate","Death Rate declines more than Birth Rate","Death Rate begins to decline while Birth Rate remains unchanged"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5398, 'PSM', 'National Health Programmes', 'Easy', 'Preventive_&_Social_Medicine', 9, '{"id":5398,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":9,"q":"The number of Anganwadi workers supervised by a Mukhyasevika is:","o":["10","15","25","30"],"a":2,"e":"MukhyaSevika is a middle level supervisor. She supervises 20 to 25 Anganwadi workers. She is required to be a graduate in social work or home science or a related field. She is trained for three months. Ref: Health policies and programmes in India, D.K. Taneja 11th edition page: 312","pyqMatches":[{"year":"2016","no":876,"q":"The number of Anganwadi workers supervised by a Mukhyasevika is:","o":["10","15","25","30"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5399, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 10, '{"id":5399,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":10,"q":"Minamata disease is caused by toxicity of:","o":["Arsenic","Antimony","Lead","Mercury"],"a":3,"e":"A significant example of mercury exposure affecting public health occurred in Minamata, Japan, between 1932 and 1968, where a factory producing acetic acid discharged waste liquid into Minamata Bay. The discharge included high concentrations of methylmercury. The bay was rich in fish and shellfish, providing the main livelihood for local residents and fishermen from other areas. For many years, no one realised that the fish were contaminated with mercury, and that it was causing a strange disease in the local community and in other districts. At least 50 000 people were affected to some extent and more than 2 000 cases of Minamata disease were certified. Minamata disease peaked in the 1950s, with severe cases suffering brain damage, paralysis, incoherent speech and delirium. Ref : http://www.who.int/mediacentre/factsheets/fs361/en/index.html","pyqMatches":[{"year":"2013","no":1324,"q":"Minamata disease is caused by toxicity of:","o":["Arsenic","Antimony","Lead","Mercury"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5400, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 11, '{"id":5400,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":11,"q":"International Red Cross was founded by:","o":["Henry Dunant","John D Rockfeller","Marie Curie","None of the above"],"a":0,"e":"The Red Cross is a non-political international humanitarian organisation founded by Swiss businessman Henry Dunant. Ref: Park 21st edition page: 858.","pyqMatches":[{"year":"2016","no":882,"q":"International Red Cross was founded by:","o":["Henry Dunant","John D Rockfeller","Marie Curie","None of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5401, 'PSM', 'Immunization', 'Moderate', 'Preventive_&_Social_Medicine', 12, '{"id":5401,"subject":"PSM","chapter":"Immunization","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":12,"q":"According to the congenital rubella syndrome eradication program, the first priority for rubella vaccination is offered to which of the following group?","o":["All female children at one year","All non pregnant women","All non pregnant women of age 15 to 34","All adolescent non pregnant girls 15 to 24 years of age"],"a":2,"e":"The first and foremost priority has been given to the group of all non-pregnant women between the ages 15 and 34 for rubella vaccination. The other three options are suitable age groups. Ref: Park’s Textbook of Preventive and Social Medicine 19th edition; pages 130 - 131.","pyqMatches":[{"year":"2016","no":1159,"q":"According to the congenital rubella syndrome eradication program, the first priority for rubella vaccination is offered to which of the following group?","o":["All female children at one year","All non pregnant women","All non pregnant women of age 15 to 34","All adolescent non pregnant girls 15 to 24 years of age"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5402, 'PSM', 'National Health Programmes', 'Easy', 'Preventive_&_Social_Medicine', 13, '{"id":5402,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":13,"q":"Swajaldhara programme is associated with:","o":["Provision of safe drinking water","Provision of food supplements for destitute women","Provision of relief for victim of sexual abuse","Provision of health care for sick tribals"],"a":0,"e":"Swajaldhara is a community lead participatory programme, which aims at provision of safe drinking water in rural areas with the full ownership of the community. Swajaldhara has 2 components: Swajaldhara I – for a Grama Panjayath or a group of Panjayath Swajaldhara II – for a district as such Ref: Park, Edition 21, Page - 419","pyqMatches":[{"year":"2015","no":917,"q":"Swajaldhara programme is associated with:","o":["Provision of safe drinking water","Provision of food supplements for destitute women","Provision of relief for victim of sexual abuse","Provision of health care for sick tribals"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5403, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 14, '{"id":5403,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":14,"q":"Which of the following screening methods is used under RNTCP?","o":["Active","Passive","Mass","All of the above"],"a":1,"e":"Under RNTCP, active case finding is not pursued. Case finding is passive. Patients presenting themselves with symptoms suggesting tuberculosis are screened with two sputum smear examinations. Ref: Park 21st edition, page 381.","pyqMatches":[{"year":"2015","no":921,"q":"Which of the following screening methods is used under RNTCP?","o":["Active","Passive","Mass","All of the above"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5404, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 15, '{"id":5404,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":15,"q":"A temporary, provisional view held by the people on a point of view is:","o":["Opinion","Belief","Practice","Attitude"],"a":0,"e":"Opinion are views held by people on a point of dispute. They are based on evidence available at the time. Opinions by definition are temporary, provisional. They can be looked on as beliefs for the time being. Ref: Park’s Textbook of Preventive and Social Medicine, 19th edition, Page 542.","pyqMatches":[{"year":"2013","no":959,"q":"A temporary, provisional view held by the people on a point of view is:","o":["Opinion","Belief","Practice","Attitude"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5405, 'PSM', 'Environment & Occupational Health', 'Easy', 'Preventive_&_Social_Medicine', 16, '{"id":5405,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":16,"q":"Low glycemic index is classified as value less than:","o":["25","45","55","65"],"a":2,"e":"Concept of glycemic index has utility in management of diabetes and obesity. Classification GI range Example Low GI 55 or less Most fruits and vegetables except potatoes and water melon, pasta beans, lentils Medium GI 56-69 Sucrose, brown rice, basmati rice High GI 70 or more Corn flakes, white bread, candy bar Ref: Park 22nd edition, page 568","pyqMatches":[{"year":"2012","no":916,"q":"Low glycemic index is classified as value less than:","o":["25","45","55","65"],"a":2,"source":"NEET_2012_Paper.pdf"},{"year":"2015","no":891,"q":"Low glycemic index is classified as value less than:","o":["25","45","55","65"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2012","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5406, 'PSM', 'Communicable Diseases', 'Easy', 'Preventive_&_Social_Medicine', 17, '{"id":5406,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":17,"q":"As per RNTCP guidelines, Multi drug resistance (MDR) TB is defined as resistance to:","o":["Rifampicin","Rifampicin and isoniazide","Rifampicin, isoniazide and ethambutol","None of the above"],"a":1,"e":"Confirmed MDR-TB case: MDR-TB suspect is one who is sputum culture positive and whose TB is due to Mycobacterium tuberculosis that are resistant in-vitro to at least isoniazid and rifampicin (the culture and DST result being from an RNTCP accredited laboratory). Ref: Park 21st edition, page 178. http://health.bih.nic.in/Docs/Guidelines-DOTS-Plus.pdf.","pyqMatches":[{"year":"2012","no":805,"q":"As per RNTCP guidelines, Multi drug resistance (MDR) TB is defined as resistance to:","o":["Rifampicin","Rifampicin and isoniazide","Rifampicin, isoniazide and ethambutol","None of the above"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5407, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 18, '{"id":5407,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":18,"q":"What is the commonest form of plague?","o":["Bubonic plague","Pneumonic plague","Septicaemic plague","Hemorrhagic plague"],"a":0,"e":"The commonest form of plague is bubonic plague. Pneumonic plague occurs in less than 5% of patients. Septicaemic plague occurs rarely except for accidental laboratory infections. Ref: Park 21st edition, page 270.","pyqMatches":[{"year":"2016","no":846,"q":"What is the commonest form of plague?","o":["Bubonic plague","Pneumonic plague","Septicaemic plague","Hemorrhagic plague"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5408, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 19, '{"id":5408,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":19,"q":"Dose of oseltamivir in a child aged 9 months is:","o":["2mg/ kg twice daily for 5 days","2.5 mg/ kg twice daily for 5 days","3 mg/ kg twice daily for 5 days","3.5 mg/ kg twice daily for 5 days"],"a":2,"e":"Age groups Recommended dose of oseltamivir 0 to 1 month 2mg/ kg twice daily for 5 days >1 month to 3 months 2.5mg/ kg twice daily for 5 days >3 months to 12 months 3mg/ kg twice daily for 5 days Ref: Park 21st edition, page 148 Chapter: Epidemiology in communicable diseases.","pyqMatches":[{"year":"2012","no":574,"q":"Dose of oseltamivir in a child aged 9 months is:","o":["2mg/ kg twice daily for 5 days","2.5 mg/ kg twice daily for 5 days","3 mg/ kg twice daily for 5 days","3.5 mg/ kg twice daily for 5 days"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5409, 'PSM', 'Immunization', 'Moderate', 'Preventive_&_Social_Medicine', 20, '{"id":5409,"subject":"PSM","chapter":"Immunization","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":20,"q":"Rotavirus vaccine doses should not be initiated beyond which age to prevent complications:","o":["6 weeks","10 weeks","12 weeks","32 weeks"],"a":2,"e":"Two live attenuated oral rotavirus vaccines have been licensed for use rotateq and rotarix. The first dose of these vaccines should be given no later than 12 weeks. In case of rotarix, vaccination must be completed by 24 weeks. In case of rotate, last dose of vaccine should be administered by 32 weeks. Risk of intussusceptions increase if first dose is administered beyond 12 weeks. Ref: Park 21st edition, page 205.","pyqMatches":[{"year":"2016","no":832,"q":"Rotavirus vaccine doses should not be initiated beyond which age to prevent complications:","o":["6 weeks","10 weeks","12 weeks","32 weeks"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5410, 'PSM', 'Communicable Diseases', 'Easy', 'Preventive_&_Social_Medicine', 21, '{"id":5410,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":21,"q":"Dukoral is:","o":["Oral cholera vaccine","Oral rotavirus vaccine","Oral typhoid vaccine","Ready to use therapeutic food"],"a":0,"e":"Dukoral is a monovalent cholera vaccine based on formalin and heat killed whole cells of vibrio cholerae 01 plus recombinant cholera toxin B subunit. Ref: Park 21st edition, page 211.","pyqMatches":[{"year":"2013","no":839,"q":"Dukoral is:","o":["Oral cholera vaccine","Oral rotavirus vaccine","Oral typhoid vaccine","Ready to use therapeutic food"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5411, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 22, '{"id":5411,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":22,"q":"Skin fold thickness is measured in all of the following places, EXCEPT:","o":["Mid triceps","Biceps","Supra pubic","Supra iliac"],"a":2,"e":"Harpenden callipers are used to measure skin fold thickness. Skin fold thickness is measured in mid triceps, biceps, supra iliac and sub scapular areas. The sum of these measurements should be less than 40 mm in boys and 50 mm in girls. Ref: Park 21st edition, page 369.","pyqMatches":[{"year":"2015","no":894,"q":"Skin fold thickness is measured in all of the following places, EXCEPT:","o":["Mid triceps","Biceps","Supra pubic","Supra iliac"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5412, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 23, '{"id":5412,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":23,"q":"Quality of life is defined as?","o":["Standard of living","Level of living","Subjective feeling of well being","All of the above"],"a":2,"e":"Ans. is ''c'' i.e., Subjective feeling of well being Ouality of life * The level of living and standard of living are objective criteria of well being, while quality of life comprises the individual''s own subjective evaluation of these. * Recent definition of quality of life is as follows \"a composite measure of physical mental and social well being as perceived by each individual or group of individuals.\" * WHO definition is as follows \"the condition of life resulting from the combination of the effects of the complete range of factors such as those determining health, happiness, education, etc.\"","pyqMatches":[{"year":"2013","no":850,"q":"Quality of life is defined as?","o":["Standard of living","Level of living","Subjective feeling of well being","All of the above"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5413, 'PSM', 'Biostatistics', 'Moderate', 'Preventive_&_Social_Medicine', 24, '{"id":5413,"subject":"PSM","chapter":"Biostatistics","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":24,"q":"Web Causation of disease is most appropriate ?","o":["Mostly applicable for common disease","Better for all the related factors associated with causation of disease","Epidemiological ratio","Helps to interrupt the risk of transmission"],"a":1,"e":"Ans. is ''b'' i.e., Better for all the related factors associated with causation of disease Web of causation o This model is ideally suited in the study of chronic disease, where the disease agent is often not known but is the outcome of interaction of multiple factors. o The \"web of causation\" considers all the predisposing factors of any type and their complex relationship with each other. o The causal web provides a model which shows a variety of possible interventions that could be taken which might reduce the occurrence of disease (e.g. MI) o The web of causation does not imply that the disease cannot be controlled unless all the multiple causes or chains of causation or at least a number of them are appropriately controlled. This is not the case. Sometimes removal or elimination of just only one link or chain may be sufficient to control disease, provided that link is sufficiently important in the pathogenic process. o Therefore, in a multifactorial event, individual factors are by no means all of the equal weight.","pyqMatches":[{"year":"2012","no":772,"q":"Web Causation of disease is most appropriate ?","o":["Mostly applicable for common disease","Better for all the related factors associated with causation of disease","Epidemiological ratio","Helps to interrupt the risk of transmission"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5414, 'PSM', 'Nutrition', 'Moderate', 'Preventive_&_Social_Medicine', 25, '{"id":5414,"subject":"PSM","chapter":"Nutrition","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":25,"q":"BEINGS Model of disease causation does not include","o":["Spiritual factors","Social factors","Religious factors","Nutritional factors"],"a":2,"e":"Ans. is ''c'' i.e., Religious factors One way of remembering the categories of cause for the disease is an acronym used in the model (BEINGS model):​ B: Biological factors and behavioral factors. E: Environmental factors. I: Immunological factors. N: Nutritional factors. G: Genetic factors. S: Services, social, spiritual factors.","pyqMatches":[{"year":"2013","no":845,"q":"BEINGS Model of disease causation does not include","o":["Spiritual factors","Social factors","Religious factors","Nutritional factors"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5415, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 26, '{"id":5415,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":26,"q":"Definition of disease control is?","o":["Agent is eliminated from community","Agent persists in community without causing health problem","Agent persists in community and causing pulic health problems","Any of the above"],"a":1,"e":"Ans. is ''b'' i.e., Agent persists in community without causing health problem * In disease control, the disease agent is permitted to persist in the community at a level where it cease to be a public health problem according to the tolerance of local population. * A state of equilibrium becomes established between the disease agent, host and environment components of the disease process.","pyqMatches":[{"year":"2013","no":851,"q":"Definition of disease control is?","o":["Agent is eliminated from community","Agent persists in community without causing health problem","Agent persists in community and causing pulic health problems","Any of the above"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5416, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 27, '{"id":5416,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":27,"q":"Iodized salt in iodine deficiency control programme is?","o":["Primary prevention","Secondary prevention","Teriary prevention","None"],"a":0,"e":"Ans. is ''a'' i.e., Primary prevention Fortification of food e.g. iodized salt is primary prevention. Primary prevention has two main components:- i) Health promotion ii) Specific protection Mode of the intervention of Primary prevention Health promotion Specific protection","pyqMatches":[{"year":"2012","no":773,"q":"Iodized salt in iodine deficiency control programme is?","o":["Primary prevention","Secondary prevention","Teriary prevention","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5417, 'PSM', 'Concept of Health & Disease', 'Hard', 'Preventive_&_Social_Medicine', 28, '{"id":5417,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":28,"q":"A patient prescribed crutches for residual paralysis in poliomyelitis is a type of -","o":["Primary prevention","Primordial prevention","Disability limitation","Rehabilitation"],"a":3,"e":"Ans. is ''d'' i.e., Rehabilitation Provision of aids for crippled is rehabilitation, e.g. prescription of crutches for PRPP. It is a type of tertiary prevention.","pyqMatches":[{"year":"2013","no":852,"q":"A patient prescribed crutches for residual paralysis in poliomyelitis is a type of","o":["Primary prevention","Primordial prevention","Disability limitation","Rehabilitation"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5418, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 29, '{"id":5418,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":29,"q":"A person has lost his leg in an accident because of which he is not able to walk. This is -","o":["Disease","Disability","Impairment","Handicap"],"a":1,"e":"Ans. is ''b'' i.e., Disability * This question is slightly different from previous one. * Patient in this question is not able to walk (due to lost leg). This is called disability. * Remember that the patient in this question also has impairment, i.e. loss of leg. (But the examiner is asking about inability to walk, in this question).","pyqMatches":[{"year":"2013","no":855,"q":"A person has lost his leg in an accident because of which he is not able to walk. This is","o":["Disease","Disability","Impairment","Handicap"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5419, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 30, '{"id":5419,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":30,"q":"International disease surveillance is for ?","o":["Hepatitis","Polio","TB","Leprosy"],"a":1,"e":"Ans. is ''b'' i.e., Polio","pyqMatches":[{"year":"2012","no":794,"q":"International disease surveillance is for ?","o":["Hepatitis","Polio","TB","Leprosy"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5420, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 31, '{"id":5420,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":31,"q":"HIV prevalence can be assessed by-","o":["Sentinel surveillance","Active","Passive","Register"],"a":0,"e":"Ans. is ''a'' i.e., Sentinel surveillance o Sentinel surveillance in India is done in national AIDS control programme.","pyqMatches":[{"year":"2012","no":831,"q":"HIV prevalence can be assessed by","o":["Sentinel surveillance","Active","Passive","Register"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5421, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 32, '{"id":5421,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":32,"q":"Principle for chinese medicine -","o":["Yang","Vin","Both","None"],"a":2,"e":"Ans. is ''c'' i.e., Both * Chinese medicine is based on two principles:- i) Yang : Active masculine principle ii) Vin : Negative feminine principle * The balance of these two opposing forces meant good health. * The Chinese were early pioneers of immunization. They practised variolation to prevent smallpox. * The Chinese system of ''bare-foot doctors'' and accupuncture have attracted worldwide attention in recent years.","pyqMatches":[{"year":"2013","no":844,"q":"Principle for chinese medicine","o":["Yang","Vin","Both","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5422, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 33, '{"id":5422,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":33,"q":"Father of public health -","o":["Cholera","Plague","Leptospirosis","Anthrox"],"a":0,"e":"Ans. is ''a'' i.e., Cholera History of cholera o Father of public health is a disease, not a person. o Father of public health is cholera. o John Snow (1813-1858) found the link between cholera and contaminated drinking water in 1854, using spot map. o Robert Koch indified V. cholerae (1885). Cholera morbus - Used in 19th & early 20th centuries for both non- epidemic cholera and other gastrointestinal diseases that resembled cholera.","pyqMatches":[{"year":"2012","no":767,"q":"Father of public health","o":["Cholera","Plague","Leptospirosis","Anthrox"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5423, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 34, '{"id":5423,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":34,"q":"The lawyer who designed the Public Health Act 1848 was ?","o":["John snow","Edwin Chadwick","Joseph Lister","William Fan"],"a":1,"e":"Ans. is ''b'' i.e., Edwin Chadwick * The great cholera epidemic of 1832 led Edwin Chadwick (1800- 1890), a lawyer in England, to investigate the health of the inhabitants of large towns with a view to improve the conditions under which they live. * Chadwick''s report on \"The Sanitary Conditions of the Labouring Population in Great Britain\", a landmark in the history of public health, set London and other cities on the way to improve housing and working conditions. * Filth was recognized as man''s greatest enemy and with this began an anti-filth crusade, the \"great sanitary awakening\", which led to the enactment of ''Public Health Act 1948'' in England.","pyqMatches":[{"year":"2013","no":843,"q":"The lawyer who designed the Public Health Act 1848 was ?","o":["John snow","Edwin Chadwick","Joseph Lister","William Fan"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5424, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 35, '{"id":5424,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":35,"q":"One of the following is not true of International Classification of Disease -","o":["It is revised once in 10 years","It was devised by UNICEF","The 10th revision consists of 21 major chapters","It is accepted for National and International use"],"a":1,"e":"Ans. is ''b'' i.e., It was devised by UNICEF ICD was devised by WHO.","pyqMatches":[{"year":"2016","no":892,"q":"One of the following is not true of International Classification of Disease","o":["It is revised once in 10 years","It was devised by UNICEF","The 10th revision consists of 21 major chapters","It is accepted for National and International use"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5425, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 36, '{"id":5425,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":36,"q":"Most important component of level of living is","o":["Health","Education","Occupation","Housing"],"a":0,"e":"Ans. is ''a'' i.e., Health Health is the most important component because its impairment always means impairment of level of living.","pyqMatches":[{"year":"2013","no":849,"q":"Most important component of level of living is","o":["Health","Education","Occupation","Housing"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5426, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 37, '{"id":5426,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":37,"q":"Simplest measure of mortality ?","o":["Crude death rate","Case fatality rate","Proportional mortality rate","Specific death rate"],"a":0,"e":"Ans. is ''a'' i.e., Crude death rate o The simplest measure of mortality is the crude death rate.","pyqMatches":[{"year":"2012","no":911,"q":"Simplest measure of mortality ?","o":["Crude death rate","Case fatality rate","Proportional mortality rate","Specific death rate"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5427, 'PSM', 'Concept of Health & Disease', 'Hard', 'Preventive_&_Social_Medicine', 38, '{"id":5427,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":38,"q":"Limitation of case fatality rate-","o":["Not useful in acute infectious disease","Not related to virulence","Time period not specified","It is not related to survival rate"],"a":2,"e":"Ans. is ''c'' i.e., Time period not specified o Limitations of case fatality rate is that time period is not specified. o CFR is typically used in acute infectious disease and is related to virulence of organism. o Case fatality rate is the complement of survival rate.","pyqMatches":[{"year":"2013","no":858,"q":"Limitation of case fatality rate","o":["Not useful in acute infectious disease","Not related to virulence","Time period not specified","It is not related to survival rate"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5428, 'PSM', 'Epidemiology', 'Moderate', 'Preventive_&_Social_Medicine', 39, '{"id":5428,"subject":"PSM","chapter":"Epidemiology","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":39,"q":"All are true about incidence, except-","o":["Numerator includes new cases","Denominator includes population at risk","Does not include unit of time","It is a rate"],"a":2,"e":"Ans. is ''c'' i.e., Does not include unit of time o Incidence rate must include the unit of time used in the final expression. If you write 16.7 per 1000, this would be inadequate.The correct expression is 16.7 per 100 per year. o All other options are correct.","pyqMatches":[{"year":"2013","no":859,"q":"All are true about incidence, except","o":["Numerator includes new cases","Denominator includes population at risk","Does not include unit of time","It is a rate"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5429, 'PSM', 'Epidemiology', 'Moderate', 'Preventive_&_Social_Medicine', 40, '{"id":5429,"subject":"PSM","chapter":"Epidemiology","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":40,"q":"Which one of the following is not a special incidence rate-","o":["Attack rate","Secondary attack rate","Hospital admission rate","Standardized mortality rate"],"a":3,"e":"Ans. is ''d'' i.e., Standardized mortality rate Special incidence rates i) Attack rate (case rate) ii) Secondary attack rate iii) Hospital admission rate","pyqMatches":[{"year":"2012","no":784,"q":"Which one of the following is not a special incidence rate","o":["Attack rate","Secondary attack rate","Hospital admission rate","Standardized mortality rate"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5430, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 41, '{"id":5430,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":41,"q":"For calculation of incidence denominator is taken as?","o":["Mid year population","Population at risk","Total number of cases","Total number of deaths"],"a":1,"e":"Ans. is ''b'' i.e., Population at risk Denominator for calculating incidence is population at risk","pyqMatches":[{"year":"2012","no":783,"q":"For calculation of incidence denominator is taken as?","o":["Mid year population","Population at risk","Total number of cases","Total number of deaths"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5431, 'PSM', 'Epidemiology', 'Hard', 'Preventive_&_Social_Medicine', 42, '{"id":5431,"subject":"PSM","chapter":"Epidemiology","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":42,"q":"All of the following are characteristics of case control study except -","o":["Quick results are obtained","Measures incidence rate","Proceeds from effect to cause","Inexpensive study"],"a":1,"e":"Ans. is ''b'' i.e., Measures incidence rate o Incidence rate can not be measured by case-control study as denominator (population at risk is not available).","pyqMatches":[{"year":"2012","no":779,"q":"All of the following are characteristics of case control study except","o":["Quick results are obtained","Measures incidence rate","Proceeds from effect to cause","Inexpensive study"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5432, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 43, '{"id":5432,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":43,"q":"Attributable risk means","o":["Fatality of a disease","Disease risk ratio between exposed and non-exposed","Risk difference between exposed and non-exposed","Communicability of a disease"],"a":2,"e":"Ans. is ''c'' i.e., Risk difference between exposed and non-exposed -Attributable risk (AR) is the difference in incidence rates of disease or death between an exposed and non-exposed group. - It is expressed in percentage and gives the extent to which the disease can be attributed to the exposure in a cohort study.","pyqMatches":[{"year":"2012","no":785,"q":"Attributable risk means","o":["Fatality of a disease","Disease risk ratio between exposed and non-exposed","Risk difference between exposed and non-exposed","Communicability of a disease"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5433, 'PSM', 'Epidemiology', 'Hard', 'Preventive_&_Social_Medicine', 44, '{"id":5433,"subject":"PSM","chapter":"Epidemiology","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":44,"q":"Advantage of case-control over a cohort study ?","o":["Attributable risk can be calculated","Odd''s ratio can be calculated","For rare disease","b and c"],"a":3,"e":"Ans. is ''b'' i.e., Odd''s ratio can be calculated & c i.e., For rare disease o A cohort study is more reliable than a case-control study for an association between a suspected risk factor and subsequent disease because relative risk can be estimated by cohort study, while case-control study measures only an estimate of relative risk (odds ratio). Why the Case-Control Study is suitable for a rare disease but not Cohort Study? o In the cohort study, we proceed from effect to cause and if the study is for the rare disease we may get very few cases or no case at the end of the study. For example, if a rare disease has an incidence rate. 01 per 1000 (1 per 100000) population and we take a sample of 100 people to expose the risk factor, there will be very few cases at the end of the study as the disease is very rare and has a low incidence of 1 per 100000 population. (you can expect, How low will be the incidence in a sample of 100 people). o On the other hand, in the case-control study, we can choose controls for the few available cases and the history of possible/suspected exposure (s) can be explored.","pyqMatches":[{"year":"2015","no":832,"q":"Advantage of case-control over a cohort study ?","o":["Attributable risk can be calculated","Odd''s ratio can be calculated","For rare disease","b and c"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5434, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 45, '{"id":5434,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":45,"q":"Berkesonian bias is a type of ?","o":["Selection bias","Interviever bias","Information bias","Recell bias"],"a":0,"e":"Ans. is ''a'' i.e., Selection bias Berksonian bias is a type of selection bias. Bias o It is any systemic error in the analysis of study that results in a mistaken estimate of an exposure''s effect on the risk of disease. o Mainly biases are of following types.","pyqMatches":[{"year":"2012","no":778,"q":"Berkesonian bias is a type of ?","o":["Selection bias","Interviever bias","Information bias","Recell bias"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2016","no":798,"q":"Berkesonian bias is a type of ?","o":["Admission rate bias","Interviever bias","Information bias","Recall bias"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2012","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5435, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 46, '{"id":5435,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":46,"q":"Problem of bias is maximum with -","o":["Cohort study","Case study","Case control study","Experimental study"],"a":2,"e":"Ans. is ''c'' i.e., Case control study","pyqMatches":[{"year":"2012","no":777,"q":"Problem of bias is maximum with","o":["Cohort study","Case study","Case control study","Experimental study"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5436, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 47, '{"id":5436,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":47,"q":"Randomization is done to reduce ?","o":["Recall bias","Selection bias","Berksonian bias","Reporting bias"],"a":1,"e":"Ans. is ''b'' i.e., Selection bias","pyqMatches":[{"year":"2013","no":857,"q":"Randomization is done to reduce ?","o":["Recall bias","Selection bias","Berksonian bias","Reporting bias"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2015","no":818,"q":"Randomization is done to reduce ?","o":["Recall bias","Selection bias","Berksonian bias","Reporting bias"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2013","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5437, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 48, '{"id":5437,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":48,"q":"Suspected cause preceding the observed effect is an example for -","o":["Temporal association","Consistency of association","Strength of association","Coherence of association"],"a":0,"e":"Ans. is ''a'' i.e., Temporal association Temporal association o It implies cause preceds effect or effect follows cause, i.e., suspected cause preceding the observed effect. o It is the most important criteria for causal association o It is best established by concurrent cohort study. Strength of association o It implies how strongly exposure is associated with disease. o It is determined by i) Relative risk (In Cohort study) I Have been explained ii) Odds ratio (In case-control study) iii) Dose-response relationship With increasing level of exposure to the risk factor, on increasing ris in incidence is found. iv) Cessation of exposure (Reversibility) —> Removal of possible cause reduces risk of disease. Consistency of association o The association is consistent if the results are replicated when studies in different settings and by different methods. o For example, different studies in different settings have proved smoking as one of the cause for lung cancer —> Smoking has consistent association with lung cancer. Coherence of association o The causal association must be coherent (supported by) with relevant facts. o For example : - The death rates due to lung cancer increasing more rapidly in females comparison to males. The relevant fact ---> This increasing rate is due to more recent adoption of cigarrete smoking by women.","pyqMatches":[{"year":"2012","no":781,"q":"Suspected cause preceding the observed effect is an example for","o":["Temporal association","Consistency of association","Strength of association","Coherence of association"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5438, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 49, '{"id":5438,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":49,"q":"The difference between contamination and infection is that in infection-","o":["Infectious agent is on body surface or on non​human objects","Infectious agent is in the body of human","Arthropods on the body surface","None"],"a":1,"e":"Ans. is ''b'' i.e., Infectious agent is in the body of human o Infection --> Infectious agent in the body. o Contamination ---> Infectious agent on body surface or on objects. o Infestation --> Arthropods on body surface.","pyqMatches":[{"year":"2013","no":860,"q":"The difference between contamination and infection is that in infection","o":["Infectious agent is on body surface or on non​human objects","Infectious agent is in the body of human","Arthropods on the body surface","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5439, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 50, '{"id":5439,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":50,"q":"Following are examples of human \"dead end\" disease except -","o":["Bubonic plague","Japanies ecephalitis","Hydatid disease","Leishmaniasis"],"a":3,"e":"Ans. is ''d'' i.e., Leishmaniasis Dead and host o A dead end host is an infected person from which infectious agents are not transmitted to other susceptible host or from which a parasite cannot escape to continue its life cycle. o The diseases in which human acts as dead end host, i.e., dead and disease : ?","pyqMatches":[{"year":"2012","no":792,"q":"Following are examples of human \"dead end\" disease except","o":["Bubonic plague","Japanies ecephalitis","Hydatid disease","Leishmaniasis"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5440, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 51, '{"id":5440,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":51,"q":"Secondary attack rate is a measure of-","o":["Communicability","Lethality","Strength of association","None"],"a":0,"e":"Ans. is ''a'' i.e., Communicability SAR is an important measure of communicability. Higher secondary attack rate means, more numbers of susceptible contacts are developing the disease after exposure to primary case. So, higher the SAR higher is the communicability (infectiousness) of disease. One term related to secondary attack rate is attack rate and requires specific mention here (Has been explained in brief previously) Attack Rate: When new cases occur rapidly over a short period of time in a well defined population the attack rate is used. o It is usually expressed as a percentage. new cases occuring during a short period of time Attack Rate = _________________________________________________________ 100 population at risk at the beginning of the time perion The attack rate is also called cumulative incidence rate. It differs from the conventional incidence rate in that it tends to describe disease or events that affect a larger proportion of the population of interest interest. Attack rate is used when \"population is exposed to riskfor a limited period of time, Such as epidemic.\" Attack rate effects the extent of epidemic. Attack rate vs secondary attack rate Attack rate includes new cases during a specific period of time (which is usually short) and it includes all the cases during that period, i.e. primary as well as secondary cases. On the other hand secondary attack rate includes new cases which develop within the range of incubation period after exposure to primary case, i.e. it includes only secondary case (not primary cases).","pyqMatches":[{"year":"2016","no":795,"q":"Secondary attack rate is a measure of","o":["Communicability","Lethality","Strength of association","None"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5441, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 52, '{"id":5441,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":52,"q":"Transovarian transmission is seen in-","o":["Rickettesial diseases","Malaria","Filaria","None"],"a":0,"e":"Ans. is ''a'' i.e., Rickettesial diseases o Transovarial transmission is seen in Rickettesial disease (scrub typhus, Rickettsial pox, RMSF, ITT, Q fever).","pyqMatches":[{"year":"2013","no":915,"q":"Transovarian transmission is seen in","o":["Rickettesial diseases","Malaria","Filaria","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5442, 'PSM', 'Immunization', 'Moderate', 'Preventive_&_Social_Medicine', 53, '{"id":5442,"subject":"PSM","chapter":"Immunization","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":53,"q":"Active and passive immunity should be given together in all except -","o":["Tetanus","Rabies","Measles","Hepatitis B"],"a":2,"e":"Ans. is `c'' i.e., Measles First see the difference between active and passive immunity. Active immunity o Active immunity develops because of active participation of immuniological system of the host. o That means, after antigenic stimulation, the host develops antibodies or cellular immune response against that antigen due to activation of self B and/or cells. o Antigenic stimulation may be : ? i) Clinical infection ii) Subclinical infection iii) Vaccination (live attenuated vaccine or killed vaccine or toxoid). Passive immunity o The host''s immune system does not take active participation but depends on ready-made antibodies or T cells to be transferred to it. o Examples : i) Administeration of immunoglobulin or antiserum ii) Transplancental transfer of antibodies from mother to fetus. iii) Administration of lymphocytes. Coming back to question o In some diseases passive immunization is often undertaken in conjunction with inactivated vaccine products, to provide both : ? i) Immediate (but temporary) passive immunity. ii) Slowly developing long lasting active immunity. o The disease in which simultaneous active and passive immunization are used : ? i) Tetanus iii) Diphtheria ii) Rabies iv) Hepatitis B o In measles also, both active and passive immunization are used, but not simultaneously. Because the antibody response to live attenuated measles vaccine is diminished in persons who receive immunoglobulin can currently. o So, the person passively immunized should be given live measles vaccine 8-12 weeks later. So, both active and passive immunity are used : ? i) Simultaneously —> Tetanus, rabies, Diphtheria, Hepatitis B. At different time —> Measles.","pyqMatches":[{"year":"2014","no":905,"q":"Active and passive immunity should be given together in all except","o":["Tetanus","Rabies","Measles","Hepatitis B"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5443, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 54, '{"id":5443,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":54,"q":"Post-exposure prophylaxis is indicated in ?","o":["HBV","Rabies","Diphtheria","All"],"a":3,"e":"Ans. is ''a'' i.e., HBV; ''b'' i.e., Rabies; ''c'' i.e., Diphtheria Read the question carefully, examinar is asking about postexposure prophylaxis (not post-exposure immunization). o In previous explanation, I have explained the diseases for which post-exposure prophylaxis is done by immunization (vaccine or immunoglobulin or both). In some diseases post-exposure prophylaxis is done by drugs, i.e., post-exposure chemoprophylaxis : - HIV → Antiretroviral therapy Herpes → Famciclovir Diphtheria Miningococcal meningitis","pyqMatches":[{"year":"2016","no":834,"q":"Post-exposure prophylaxis is indicated in ?","o":["HBV","Rabies","Diphtheria","All"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5444, 'PSM', 'Maternal & Child Health', 'Moderate', 'Preventive_&_Social_Medicine', 55, '{"id":5444,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":55,"q":"Congenital acquired immunity is NOT found in -","o":["Pertussis","Mumps","Rubella","Measles"],"a":0,"e":"Ans. is ''a'' i.e., Pertussis Congenital passive immunity (maternal passive immunity) o Maternal passive immunity is a type of naturally acquired passive immunity. o It refers to antibody-mediated immunity conveyed to a fetus by its mother during pregnancy. o Important infection, against which immunity is transferred from mother to child ? 1) Chicken pox 3) Rubella 5) Diphtheria 2) Measles 4) Mumps 6) Polio o Important diseases for which there is no maternal passive immunity ? 1) Pertussis (whooping cough) 3) Hepatitis B 2) TB","pyqMatches":[{"year":"2013","no":863,"q":"Congenital acquired immunity is NOT found in","o":["Pertussis","Mumps","Rubella","Measles"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5445, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 56, '{"id":5445,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":56,"q":"Name of mumps vaccine is -","o":["Jeryl Lynn","Edmonshon zagreb","Schwatz","Moraten"],"a":0,"e":"Ans. is ''a'' i.e., Jeryl lynn o Mumps vaccine strain is Jeryll Lynn strain. o Other three strains are of measles vaccine.","pyqMatches":[{"year":"2012","no":787,"q":"Name of mumps vaccine is","o":["Jeryl Lynn","Edmonshon zagreb","Schwatz","Moraten"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5446, 'PSM', 'Immunization', 'Moderate', 'Preventive_&_Social_Medicine', 57, '{"id":5446,"subject":"PSM","chapter":"Immunization","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":57,"q":"All vaccines are given in disaster,except ?","o":["Cholera","Influenza","Measles","Tetanus"],"a":0,"e":"Ans. is ''a'' i.e., Cholera Vaccines recommended in disasters o Following vaccines are recommended 1) Children < 10 years :- DPT, inactivated polio (IPV), H.influenzae type b (Hib), hepatitis B, pneumococcal conjugate vaccine (PCV), measles-mumps-rubella (MMR), varicella vaccine, influenza, hepatitis A and rotavirus. 2) Children and adolescents (11-18 years):- Tetanus, diphtheria, pertussis, meningococcal conjugate vaccine (MCV), Influenza. 3) Adults (>18 years):- Tetanus, diphtheria, pertussis, pneumococcal polysaccharide vaccine (PPSV23), and influenza. o Vaccination against typhoid and cholera is not recommended.","pyqMatches":[{"year":"2013","no":868,"q":"All vaccines are given in disaster,except ?","o":["Cholera","Influenza","Measles","Tetanus"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5447, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 58, '{"id":5447,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":58,"q":"6th month immunization given is -","o":["Measles","DPT","BCG","All"],"a":0,"e":"Ans. is ''a'' i.e., Measles o Measles vaccine is given at 6 month.","pyqMatches":[{"year":"2013","no":869,"q":"6th month immunization given is","o":["Measles","DPT","BCG","All"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5448, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 59, '{"id":5448,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":59,"q":"Mass vaccination is ineffective in -","o":["Measles","Polio","Tetanus","None"],"a":3,"e":"Ans. is ''None'' o Mass vaccination is used in all the three given options.","pyqMatches":[{"year":"2012","no":795,"q":"Mass vaccination is ineffective in","o":["Measles","Polio","Tetanus","None"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5449, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 60, '{"id":5449,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":60,"q":"The amount of bleaching powder necessary to disinfect choleric stools, is -","o":["50 gm/lit","75 gm/lit","90 gm/lit","100 gm/lit"],"a":0,"e":"Ans. is ''a'' i.e., 50gm/lit","pyqMatches":[{"year":"2012","no":877,"q":"The amount of bleaching powder necessary to disinfect choleric stools, is","o":["50 gm/lit","75 gm/lit","90 gm/lit","100 gm/lit"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5450, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 61, '{"id":5450,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":61,"q":"Time between infection and maximum infectivity is known as?","o":["Incubation period","Serial interval","Generation time","Communicable period"],"a":2,"e":"Ans. is ''c'' i.e., Generation time Generation time o Interval between receipt of infection by host and maximal infectivity of the host. o Generation time is roughly equal to the incubation period. Ref: PARK 22nd edition pg96","pyqMatches":[{"year":"2012","no":788,"q":"Time between infection and maximum infectivity is known as?","o":["Incubation period","Serial interval","Generation time","Communicable period"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5451, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 62, '{"id":5451,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":62,"q":"Recall bias is most commonly associated with which study design -","o":["Case control study","Cohort study","Cohort case control study","Cross-sectional study"],"a":0,"e":"Ans. is ''a'' i.e., Case control Study Recall bias (Memory bias) : This type of bias may occur when cases and controls are asked to recall certain events, and subjects in one group are more likely to remember the event than those in the other group. For example people take aspirin commonly and for many reasons, but patients diagnosed as having peptic ulcer disease may recall the ingestion of aspirin in greater accuracy than those without G1 problems. Also patients who have had an MI are more likely to recall and remember certain habits (like eating habit) with greater accuracy than those who have not had an MI.","pyqMatches":[{"year":"2016","no":811,"q":"Recall bias is most commonly associated with which study design","o":["Case control study","Cohort study","Cohort case control study","Cross-sectional study"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5452, 'PSM', 'Immunization', 'Moderate', 'Preventive_&_Social_Medicine', 63, '{"id":5452,"subject":"PSM","chapter":"Immunization","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":63,"q":"Chronic carrier state is not seen in all except ?","o":["Poliomyelitis","Measles","Malaria","Tetanus"],"a":2,"e":"Ans. is ''c'' i.e., Malaria","pyqMatches":[{"year":"2012","no":791,"q":"Chronic carrier state is not seen in all except ?","o":["Poliomyelitis","Measles","Malaria","Tetanus"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5453, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 64, '{"id":5453,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":64,"q":"Screening for condition recommended when ?","o":["Low case fatality rate","Diagnostic tools not available","No effective treatment available","Early diagnosis can change disease course because of effective treatment"],"a":3,"e":"Ans. is ''d'' i.e., Early diagnosis can change disease course because of effective treatment Criteria for screening o The criteria for screening are based on two consideration. i) Disease to be screened ii) Screening test to be applied o Disease to be screened The disease to be screened should fulfil the following criteria before it is considered suitable for screening.","pyqMatches":[{"year":"2013","no":870,"q":"Screening for condition recommended when ?","o":["Low case fatality rate","Diagnostic tools not available","No effective treatment available","Early diagnosis can change disease course because of effective treatment"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5454, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 65, '{"id":5454,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":65,"q":"If prevalence of a disease increases, what is true?","o":["PPV increases","PPV decreases","No effect on PPV","PPV may increase or decrease"],"a":0,"e":"Ans. is ''a'' i.e., PPV increase","pyqMatches":[{"year":"2012","no":796,"q":"If prevalence of a disease increases, what is true?","o":["PPV increases","PPV decreases","No effect on PPV","PPV may increase or decrease"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5455, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 66, '{"id":5455,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":66,"q":"High sensitive -","o":["Low false positive","Low false negative","Low true negative","Low true positive"],"a":1,"e":"Ans. is ''b'' i.e., Low False negative True positive is directly related to sensitivity o False negative is inversely related to sensitivity True negative is directly related to specificity o False positive is inversely related to specificity o If a test has high sensitivity —> more true positive, less false negative, and also more false positive. o If a test has high specificity —> more true negative, less false positive and also more false negative.","pyqMatches":[{"year":"2012","no":798,"q":"High sensitive","o":["Low false positive","Low false negative","Low true negative","Low true positive"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5456, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 67, '{"id":5456,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":67,"q":"Screening procedure is best for Ca of -","o":["Prostate","Colon","Gastric","None"],"a":1,"e":"Ans. is ''b'' i.e., Colon o Two most important cancers, which can be prevented by screening are carcinoma of colon and cervix.","pyqMatches":[{"year":"2012","no":797,"q":"Screening procedure is best for Ca of","o":["Prostate","Colon","Gastric","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5457, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 68, '{"id":5457,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":68,"q":"Most reliable test for screening of diabetes mellitus?","o":["Random sugar","Fasting sugar","Glucose tolerance test","Urine sugar"],"a":1,"e":"Ans. is ''b'' i.e., Fasting sugar \"The best screening test for diabetes, the fasting plasma glucose (FPG), is also a component of gnostic testing\" diabetesjournals.org o The fasting plasma glucose test and the 75g oral glucose tolerance test (GTT) are both suitable tests for screening of diabetes. o However, the FPG test is preferred in clinical settings because it is easier and faster to perform, more convenient and acceptable to patients, and less expensive. \"Fasting plasma glucose level is the most reliable and convenient test\" Problem oriented patient management","pyqMatches":[{"year":"2012","no":799,"q":"Most reliable test for screening of diabetes mellitus?","o":["Random sugar","Fasting sugar","Glucose tolerance test","Urine sugar"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5458, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 69, '{"id":5458,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":69,"q":"Multiphasic screening means-","o":["Application of the two or more screening tests in combination at one time","Application of two or more screening tests in combination at different time","Application of two or more screening tests in combination at different geographical areas","Application of separate screening tests for different diseases"],"a":0,"e":"Ans. is ''A'' i.e., Application of the two or more screening tests in combination at one time Multiphasic screening It has defined the application of two or more screening tests in combination with a large number of people at one time than to carry out separate screening tests for a single disease. It increases the cost of health services without any observable benefit.Example-Annual Health Checkups High-risk or selective screening is done on high-risk groups example- MRI screening of breast done annually in 25-year old women with BRCA 1, BRCA 2 mutations in first-degree relative","pyqMatches":[{"year":"2015","no":817,"q":"Multiphasic screening means","o":["Application of the two or more screening tests in combination at one time","Application of two or more screening tests in combination at different time","Application of two or more screening tests in combination at different geographical areas","Application of separate screening tests for different diseases"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5459, 'PSM', 'Biostatistics', 'Easy', 'Preventive_&_Social_Medicine', 70, '{"id":5459,"subject":"PSM","chapter":"Biostatistics","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":70,"q":"The frequently occurring value in a data is -","o":["Median","Mode","Standard deviation","Mean"],"a":1,"e":"Ans. is ''b'' i.e., Mode","pyqMatches":[{"year":"2012","no":902,"q":"The frequently occurring value in a data is","o":["Median","Mode","Standard deviation","Mean"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5460, 'PSM', 'Biostatistics', 'Easy', 'Preventive_&_Social_Medicine', 71, '{"id":5460,"subject":"PSM","chapter":"Biostatistics","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":71,"q":"Most common deviation used in social medicine is-","o":["Mean","Range","Variance","Standard deviation"],"a":3,"e":"Ans. is ''d'' i.e., Standard deviation \"Standard deviation is most common and generally most appropriate measure of dispersion (variation)\".","pyqMatches":[{"year":"2012","no":901,"q":"Most common deviation used in social medicine is","o":["Mean","Range","Variance","Standard deviation"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5461, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 72, '{"id":5461,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":72,"q":"Shape of normal distribution curve?","o":["J shape","U shape","Bell shape","None"],"a":2,"e":"Ans. is ''c'' i.e., Bell shape o Standard normal curve (Gaussian distribution) is bell shape curve.","pyqMatches":[{"year":"2013","no":962,"q":"Shape of normal distribution curve?","o":["J shape","U shape","Bell shape","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5462, 'PSM', 'Biostatistics', 'Easy', 'Preventive_&_Social_Medicine', 73, '{"id":5462,"subject":"PSM","chapter":"Biostatistics","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":73,"q":"One standard deviation in normal standard curve includes value-","o":["50%","68%","95%","100%"],"a":1,"e":"Ans. is ''b'' i.e., 68% o 1 SD includes ----> 68% of values o 2 SD includes ----> 95% of values o 3 SD includes ----> 99.7% of values","pyqMatches":[{"year":"2013","no":963,"q":"One standard deviation in normal standard curve includes value","o":["50%","68%","95%","100%"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5463, 'PSM', 'Biostatistics', 'Easy', 'Preventive_&_Social_Medicine', 74, '{"id":5463,"subject":"PSM","chapter":"Biostatistics","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":74,"q":"Height to weight is a/an -","o":["Association","Correlation","Proportion","Index"],"a":0,"e":"Ans. is ''a'' i.e., Association First read about these two related terms :? o Association ---> Association may be defined as the concurrence of two variables more often than would be expected by chance. That mean 2 variables exist simultaneously. o Correlation —> Correlation indicates the degree (strength) of association between two variables, i.e. relationship between two quantitative variables. o Height to weight is an association and the strength of this association is indicated by correlation.","pyqMatches":[{"year":"2012","no":897,"q":"Height to weight is a/an","o":["Association","Correlation","Proportion","Index"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5464, 'PSM', 'Biostatistics', 'Moderate', 'Preventive_&_Social_Medicine', 75, '{"id":5464,"subject":"PSM","chapter":"Biostatistics","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":75,"q":"If correlation between weight and heights are very strong what will be the correlation coefficient ?","o":["+1","> 1","0","None"],"a":0,"e":"Ans. is ''a'' i.e., +1 o A correlation simply expresses the strength and direction of the relationship between two variables in terms of a correlation coefficient, signified by `r''. o Values of r varies from -1 to +1.; o The strength of the relationship is indicated by the size of the coefficient , whereas its direction is indicated by the sign(+ or -) o A plus sign (+) means : That there is a positive correlation between the two variables - high values of one variable (such as salt intake ) are associated with high value of the other variable ( such as blood pressure) i.e salt intake is directly proportional to blood pressure. o A negative sign (-) means : That there is a negative correlation between the two variables - high values of one variables (such as cigarette consumption ) are associated with low values of the other ( such as life expectancy). Cigarette consumption is inversely proportional to life expectancy o If there is a perfect linear relationship between the two variables so that it is possible to know the exact value of one variable from the knowledge of other variable, the correlation coefficient ( r) will be exactly + or - 1.00 ( +1 or -1 ). exactly + or 1.00 ( +1 or 1 ). o If there is absolutely no relationship between the two variables so that it is impossible to know anything about one variable on the basis of knowledge of the other variable. Then the coefficient will be 0. Strength of correlation o The strength of linear relationship between two random variables X and Y is based on the value of correlation coefficient and is often summarized according to the following guidelines:- For Positive Correlation For negative correlation Interpretation r<0. 30 - 0.30 r very weak linear relationship 0.30 5 r < 0.50 - 0.50 < r 5 - 0.30 weak linear relationship 0.50 _. r < or 0.80 - 0.80 <r - 0.50 moderate linear relationship 0.80 5..r< 0.90 - 0.90 <r- 0.80 strong linear relationship r 0.90 1.5.-0.90 very strong linear relationship o If you have difficulty in interpreting above table, I am giving in very simple language:– A. Positive Correlation i) Correlation coefficient less than 0.30 Very weak positive correlation. ii) Correlation coefficient 0.30 to 0.49 --) Weak Positive correlation iii) Correlation coefficient 0.50 to 0.79 Moderate Positive correlation iv) Correlation coefficient 0.80 to 0.89 —)Strong Positive correlation v) Correlation Coefficient equal to or greater than 0.90—> very strong positive correlation. B. Negative Correlation i) Correlation coefficient more than - 0.30 Very weak negative correlation ii) Correlation coefficient - 0.30 to - 0.497-> Weak negative correlation iii) Correlation coefficient - 0.50 to - 0.79 —> Moderate negative correlation iv) Correlation coefficient - 0.80 to - 0.89 Strong negative correlation. v) Correlation coefficient equal or less then - 0.90 —> very strong negative correlation Note: you should keep in mind that for negative values, more means towards more positive side and less means towards more negative side. For example; if we are saying, more than - 0.30, that mean - 0.29, - 0.28, - 0.27 .... so on; and if we are saying less than - 0.90 that means - 0.91, - 0.92 .... so on.","pyqMatches":[{"year":"2013","no":966,"q":"If correlation between weight and heights are very strong what will be the correlation coefficient ?","o":["+1","> 1","0","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5465, 'PSM', 'Biostatistics', 'Easy', 'Preventive_&_Social_Medicine', 76, '{"id":5465,"subject":"PSM","chapter":"Biostatistics","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":76,"q":"Correlation in height & weight are measured by?","o":["Coefficient of variation","Range of variation","Correlation coefficient","None"],"a":2,"e":"Ans. is ''c'' i.e., Correlation Coefficient","pyqMatches":[{"year":"2012","no":898,"q":"Correlation in height & weight are measured by?","o":["Coefficient of variation","Range of variation","Correlation coefficient","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5466, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 77, '{"id":5466,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":77,"q":"Trends can be represented by -","o":["Line diagram","Bar diagram","Scatter diagram","None"],"a":0,"e":"Ans. is ''a'' i.e., Line diagram Line diagram (Line chart/Line graph) o It is used to show the trend of events with passage of time and shows how the frequency of a particular event or variable vary over time.","pyqMatches":[{"year":"2012","no":900,"q":"Trends can be represented by","o":["Line diagram","Bar diagram","Scatter diagram","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5467, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 78, '{"id":5467,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":78,"q":"People are separated into groups, from each group people are selected randomly. What type of sampling is this -","o":["Simple random","Stratified random","Systemic random","Cluster"],"a":1,"e":"Ans. is ''b'' i.e., Stratified random o Separation of people in groups followed by random sampling from those groups is stratified random sampling.","pyqMatches":[{"year":"2013","no":968,"q":"People are separated into groups, from each group people are selected randomly. What type of sampling is this","o":["Simple random","Stratified random","Systemic random","Cluster"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
