INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5469, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 80, '{"id":5469,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":80,"q":"Sample registration system is done once in ?","o":["6 months","1 year","2 years","5 years"],"a":0,"e":"Ans. is ''a'' i.e., 6 Months","pyqMatches":[{"year":"2015","no":876,"q":"Sample registration system is done once in ?","o":["6 months","1 year","2 years","5 years"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5470, 'PSM', 'Biostatistics', 'Easy', 'Preventive_&_Social_Medicine', 81, '{"id":5470,"subject":"PSM","chapter":"Biostatistics","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":81,"q":"In a Left skewed curve, true statement is?","o":["Mean = Median","Mean < Mode","Mean>Mode","Mean = Mode"],"a":1,"e":"Ans. is ''b'' i.e., Mean < Mode","pyqMatches":[{"year":"2012","no":899,"q":"In a Left skewed curve, true statement is?","o":["Mean = Median","Mean < Mode","Mean>Mode","Mean = Mode"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5471, 'PSM', 'Biostatistics', 'Easy', 'Preventive_&_Social_Medicine', 82, '{"id":5471,"subject":"PSM","chapter":"Biostatistics","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":82,"q":"Chi-square test is for?","o":["Standard error of Mean","Standard error of Proportion","Standard error of difference between 2 Means","Standard error of difference between Proportions"],"a":3,"e":"Ans. is ''d'' i.e., Standard error of difference between Proportions Chi-square test measures the significance of difference between two proportions by testing, whether the observed frequencies differ significantly from the expected frequencies.","pyqMatches":[{"year":"2016","no":873,"q":"Chi-square test is for?","o":["Standard error of Mean","Standard error of Proportion","Standard error of difference between 2 Means","Standard error of difference between Proportions"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5472, 'PSM', 'Biostatistics', 'Moderate', 'Preventive_&_Social_Medicine', 83, '{"id":5472,"subject":"PSM","chapter":"Biostatistics","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":83,"q":"All are non-parametric tests except -","o":["Chi-square test","Sign test","Fisher exact test","Student t-test"],"a":3,"e":"Ans. is ''d'' i.e., Student t-test","pyqMatches":[{"year":"2016","no":875,"q":"All are non-parametric tests except","o":["Chi-square test","Sign test","Fisher exact test","Student t-test"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5473, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 84, '{"id":5473,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":84,"q":"Incubation period of influenza -","o":["18 - 72 hrs","1 - 6 hrs","5 - 10 days","< 1 hrs"],"a":0,"e":"Ans. is ''a'' i.e., 18 - 72 hrs","pyqMatches":[{"year":"2014","no":964,"q":"Incubation period of influenza","o":["18 - 72 hrs","1 - 6 hrs","5 - 10 days","< 1 hrs"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5474, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 85, '{"id":5474,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":85,"q":"Rash of chickenpox can be differentiated from the rash of small pox by all except ?","o":["Pleomorphic","Centripetal","Deep-seated","Unilocular"],"a":2,"e":"Ans. is ''c'' i.e., Deep-seated Rash of chickenpox is superficial (not deep seated).","pyqMatches":[{"year":"2013","no":872,"q":"Rash of chickenpox can be differentiated from the rash of small pox by all except ?","o":["Pleomorphic","Centripetal","Deep-seated","Unilocular"],"a":2,"source":"NEET_2013_Paper.pdf"},{"year":"2016","no":744,"q":"Rash of chickenpox can be differentiated from the rash of small pox by all except ?","o":["Pleomorphic","Centripetal","Deep-seated","Unilocular"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2013","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5475, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 86, '{"id":5475,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":86,"q":"Chicken pox vaccine is -","o":["Live vaccine","Killed vaccine","Conjugated vaccine","None"],"a":0,"e":"Ans. is ''a'' i.e., Live vaccine Prevention of chickenpox o For prevention of chickenpox following are used? i) Varicella zoster immunoglobulin (VZIG) VZIG is given within 72 hours of exposure in exposed susceptible individuals. It is given intramuscular with a repeat dose in 3 weeks. Because VZIG bind to varicella vaccine, the two should not be given concomitantly. ii) Vaccine Varicella vaccine is live attenuated vaccine and is recommended for children between 12-18 months of age. Efficacy of vaccine is 90 - 95% and duration of immunity is probably 10 years. Two doses are recommended in person older than 12 years of age.","pyqMatches":[{"year":"2012","no":809,"q":"Chicken pox vaccine is","o":["Live vaccine","Killed vaccine","Conjugated vaccine","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5476, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 87, '{"id":5476,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":87,"q":"Reconstituted measles vaccine should be used with in -","o":["1 hour","3 hour","6 hour","12 hour"],"a":0,"e":"Ans. is ''a'' i.e., 1 hour \"The reconstituted vaccine should be kept on ice and used within one hour \". —Park Measles vaccine : Type: Live attenuated, lyophilized (Freeze dried) vaccine, Measles vaccine is live attenuated, lypholized (Freez dried) vaccine. Strains of virus used to prepare vaccine are Edmonston Zagreb strain (most common), Schwartz strain and Moraten strain. It is given subcutaneously in to middle one-third of antero-lateral aspect of thigh. It is given at the age of 9 months (age can be lowerered to 6 months in epidemics & malnutrition) and is repeated at 16-24 months of age. It has protective efficacy (sero-conversion) of 95%. Vaccination provide life long immunity. Incubation period of vaccine induced measles is 7 days. In post-exposure prophylaxis, measles vaccine should be given within 2-3 days of exposure. Incubation period of measles virus is 10 days. Incubation period of live attenuated measles virus of live vaccine is 7 days. Thus, if the vaccine is given within 2-3 days of exposure, the replication of vaccine virus takes preference over replication of wild virus. Diluent used for measles vaccine reconstitution is distilled water or sterile water. Reconstituted vaccine should be used within 1 hour. Usual temperature for cold chain storage is +2 to +8°C.","pyqMatches":[{"year":"2016","no":842,"q":"Reconstituted measles vaccine should be used with in","o":["1 hour","3 hour","6 hour","12 hour"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5477, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 88, '{"id":5477,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":88,"q":"India started 2-dose vaccination strategy for measles, in -","o":["2008","2009","2010","2011"],"a":2,"e":"Ans. is ''c'' i.e., 2010 o In the year 2010, the world''s two most populous countries made promising advances in measles control :- i) China held the largest ever SIA, vaccinating more than 103 million children. India started implementation of 2-dose vaccination startegy.","pyqMatches":[{"year":"2013","no":862,"q":"India started 2-dose vaccination strategy for measles, in","o":["2008","2009","2010","2011"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5478, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 89, '{"id":5478,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":89,"q":"Measles vaccination is given at -","o":["9 months","At birth","4 weeks","8 weeks"],"a":0,"e":"Ans. is ''a'' i.e., 9 months o The WHO expanded programme on immunization recommends immunization at 9 months of age. o Now, second dose of measles is also given at 16-24 months in National Immunization Schedule.","pyqMatches":[{"year":"2012","no":803,"q":"Measles vaccination is given at","o":["9 months","At birth","4 weeks","8 weeks"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5479, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 90, '{"id":5479,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":90,"q":"In measeles vaccine can be given within-","o":["3 months","5 months","7 months","6 months"],"a":3,"e":"Ans. is ''d'' i.e., 6th months o The best age for measles vaccination is 9 months. o The age can be lowered to 6 months if there is measles outbreak in the community. For infants immunized between 6 months and 9 months of age, a second dose should be administered as soon as possible after the child reaches the age of 9 months provided that at least 4 weeks have elapsed since the last dose.","pyqMatches":[{"year":"2012","no":802,"q":"In measeles vaccine can be given within","o":["3 months","5 months","7 months","6 months"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5480, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 91, '{"id":5480,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":91,"q":"Incubation period of swine flu -","o":["1-3 days","2-3 weeks","10-15 days","5 weeks"],"a":0,"e":"Ans. is ''a'' i.e., 1-3 days Swine flu o Swine flu, also called swine influenza, or pig influenza, is caused by influenza virus. o It is mainly occurs in swines (pigs) and occasionally transmitted to human. o It is usually caused by influenza virus type A (H1-N1). o Incubation period is about 1-3 days and the symptoms of swine flu in humans are similar to most influenza infections, e.g. fever, cough, rhinorrhea, fatigue and headache.","pyqMatches":[{"year":"2012","no":804,"q":"Incubation period of swine flu","o":["1-3 days","2-3 weeks","10-15 days","5 weeks"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5481, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 92, '{"id":5481,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":92,"q":"Ideal temperature for DPT storage ?","o":["Room temperature","4 to 8°C","0 to - 20°C","None"],"a":1,"e":"Ans. is ''b'' i.e., 4 to 8°C o Storage --> DPT / DT vaccine should not be frozen, they should be stored in a refrigerator between 4 to 8°C. o Optimum age EPI has recommended that DPT vaccine can safely and effectively administered as early as 6 weeks after birth. o Number of doses Three doses are considered to be optimal for primary immunization. o Interval between doses —> The current recommendation is to allow an interval of 4 weeks between 3 doses, with a booster injection at 11/2 to 2 years, followed by another booster (DT only) at the age of 5-6 years. Dose Age DPTJ 6 weeks of age DPT2 10 weeks of age DPT3 14 weeks of age DPT300,, 16-24 months of age DT 5 years of age Booster o Mode and site of administration ---> IM at upper & outer quadrant of gluteal region. Also know o Since the severity of pertussis infection decreases with age the o S ce t e se e ty o pe tuss s ect o dec eases t age t e pertussis component in DPT vaccine is not usually recommended after the age of 6 years. o Therefore, children over the age of 5 years who have not received DPT, need only 2 doses of DT vaccine 4 weeks apart, with a booster dose 6 months to 1 year later. Those children who received the primary course of DPT earlier, should receive only DT as booster at 5-6 years or at school entry. o For immunizing children over 12 years of age and adults, the preparation of choice is DT —> 2 doses at an interval of 4 to 6 weeks, followed by a booster 6 to 12 months after the second dose.","pyqMatches":[{"year":"2013","no":865,"q":"Ideal temperature for DPT storage ?","o":["Room temperature","4 to 8°C","0 to - 20°C","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5482, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 93, '{"id":5482,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":93,"q":"According to EVINCE fast breathing in 5 mth child is defined as -","o":[">30/min","40","50","60"],"a":2,"e":"Ans. is ''c'' i.e., 50","pyqMatches":[{"year":"2012","no":812,"q":"According to EVINCE fast breathing in 5 mth child is defined as","o":[">30/min","40","50","60"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5483, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 94, '{"id":5483,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":94,"q":"Most important feature to diagnose severeb pneumonia-","o":["Cyanosis","Chest indrawing","Nasal flaring","Fast breathing"],"a":1,"e":"Ans. is ''b'' i.e., Chest indrawing o The only sign for severe pneumonia is chest indrawing.","pyqMatches":[{"year":"2013","no":1263,"q":"Most important feature to diagnose severeb pneumonia","o":["Cyanosis","Chest indrawing","Nasal flaring","Fast breathing"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5484, 'PSM', 'Communicable Diseases', 'Hard', 'Preventive_&_Social_Medicine', 95, '{"id":5484,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":95,"q":"Why a TB patient is recommend a regimen of 4 drugs on 1st visit -","o":["To avoid emergence of persistors","To avoid side effects","To cure early","None"],"a":0,"e":"Ans. is ''a'' i.e., To avoid emergence of persistors Two phase chemotheraphv o There are two phase of treatment of tuberculosis i) Intensive phase This is short phase in the early course of treatment and lasts for 1- 3 months. Three or more drugs are given to kill as many bacilli as possible, which prevents emergence of persisters. The risk of relapse is also lessened. Continuation phase It is aimed at sterilizing the smaller number of dormant or persisting bacilli.","pyqMatches":[{"year":"2012","no":806,"q":"Why a TB patient is recommend a regimen of 4 drugs on 1st visit","o":["To avoid emergence of persistors","To avoid side effects","To cure early","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5485, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 96, '{"id":5485,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":96,"q":"TB multidrug regimen is given to-","o":["Prevent resistance","Broad spectrum","Prevent side effects","None"],"a":0,"e":"Ans. is ''a'' i.e., Prevent resistance o Multidrug treatment in TB is given to ? i) Prevent emergence of persisters ii) Prevent relapse iii) Prevent emergence of resistance iv) shorten the duration of treatment","pyqMatches":[{"year":"2012","no":807,"q":"TB multidrug regimen is given to","o":["Prevent resistance","Broad spectrum","Prevent side effects","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5486, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 97, '{"id":5486,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":97,"q":"4 drugs in AKT used because -","o":["Decrease in resistance by mutation","Decrease in resistance by conjugation","To cure disease early","None"],"a":0,"e":"Ans. is ''a'' i.e., Decrease in resistance by mutation o Most common method for production of resistance against ATT is mutation. o Multidrug treatment prevents emergence of resistance. Thus, multidrug treatment prevent emergence of resistance due to mutation.","pyqMatches":[{"year":"2012","no":808,"q":"4 drugs in AKT used because","o":["Decrease in resistance by mutation","Decrease in resistance by conjugation","To cure disease early","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5487, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 98, '{"id":5487,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":98,"q":"The direct BCG vaccination in India is given upto age of-","o":["10 year","15 year","20 year","None"],"a":3,"e":"Ans. is ''None'' First you should know what does direct vaccination mean Direct BCG vaccination When BCG vaccination is given without prior mantoux test, it is referred as direct BCG vaccination. It is recommended upto 1 year of age. Indirect BCG vaccination o When BCG vaccination is given after mantoux test, it is referred as indirect BCG vaccination. It is recommended beyond the age of 1 year.","pyqMatches":[{"year":"2013","no":881,"q":"The direct BCG vaccination in India is given upto age of","o":["10 year","15 year","20 year","None"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5488, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 99, '{"id":5488,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":99,"q":"Polio virus is shed in stool upto-","o":["6 weeks","8 weeks","10 weeks","12 weeks"],"a":3,"e":"Ans. is ''d'' i.e., 12 weeks In the faces, the virus is excreted commonly for 2 to 3 weeks, sometimes as long as 3 to 4 months.","pyqMatches":[{"year":"2016","no":755,"q":"Polio virus is shed in stool upto","o":["6 weeks","8 weeks","10 weeks","12 weeks"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5489, 'PSM', 'Biostatistics', 'Moderate', 'Preventive_&_Social_Medicine', 100, '{"id":5489,"subject":"PSM","chapter":"Biostatistics","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":100,"q":"All are true about polio, except -","o":["99% non paralytic","Flaccid paralysis","Exaggerated tendon reflexes","Aseptic meningitis"],"a":2,"e":"Ans. is ''c'' i.e., Exaggerated tendon reflexes o There are absent tendon reflexes (not exaggerated). o Paralytic polio occurs in only 1% cases (that means 99% is non- paralytic). o There is flaccid paralysis. o Aspetic meningitis occurs in 1% of cases.","pyqMatches":[{"year":"2013","no":885,"q":"All are true about polio, except","o":["99% non paralytic","Flaccid paralysis","Exaggerated tendon reflexes","Aseptic meningitis"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5490, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 101, '{"id":5490,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":101,"q":"Trivalent oral polio vaccine contains, type 3 virus -","o":["100,000 TCID 50","200,000 TCID 50","300,000 TCID 50","400,000 TCID 50"],"a":2,"e":"Ans. is ''c'' i.e., 300,000 TCID 50 Oral (sabin) polio vaccine It contains live attenuated viruss (type 1, 2 and 3) grown in primary monkey kidney or human diploid cell culture. o The vaccine contains :- i) Over 300,000 TCID 50 of type 1 poliovirus ii) Over 100,000 TCID 50 of type 2 poliovirus iii) Over 300,000 TCID 50 of type 3 poliovirus o Dose 2 drop (0.1 ml) Schedule in National Immunization Programme of India. Dose Age OPV-0 (Zero dose) At birth OPV-1 6 weeks OPV-2 10 weeks OPV-3 14 weeks OPV-B (Booster dose) 16-24 months o Development of immunity --> OPV induces local intestinal immunity by production of secretory IgA as well as humoral immunity by inducing production of serum antibodies (IgG). So, it gives protection from paralysis and also prevents infection of the gut by wild viruses.","pyqMatches":[{"year":"2012","no":815,"q":"Trivalent oral polio vaccine contains, type 3 virus","o":["100,000 TCID 50","200,000 TCID 50","300,000 TCID 50","400,000 TCID 50"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5491, 'PSM', 'Immunization', 'Moderate', 'Preventive_&_Social_Medicine', 102, '{"id":5491,"subject":"PSM","chapter":"Immunization","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":102,"q":"Criteria for defining polio epidemic are all except ?","o":["2 or more cases","Cases should occur in same locality","Caused by same virus type","Cases occurring during 6 month period"],"a":3,"e":"Ans. is ''d'' i.e., Cases occuring during 6 month period o An epidemic of polio is defined as 2 or more local cases caused by same virus type in any 4 week period. So, it has following features - i) 2 or more cases of polio ii) Caused by same virus type iii) Within 4 week period","pyqMatches":[{"year":"2013","no":886,"q":"Criteria for defining polio epidemic are all except ?","o":["2 or more cases","Cases should occur in same locality","Caused by same virus type","Cases occurring during 6 month period"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5492, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 103, '{"id":5492,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":103,"q":"Which is cholera vaccine -","o":["Ty21 A","HGD -103","WC-rBS","None"],"a":2,"e":"Ans. is ''c'' i.e., WC-r BS Cholera Vaccine Killed vaccines Dukoral (WC-rBS) Sanchol and mORC VAX","pyqMatches":[{"year":"2012","no":814,"q":"Which is cholera vaccine","o":["Ty21 A","HGD -103","WC-rBS","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5493, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 104, '{"id":5493,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":104,"q":"ORS contains 75 mEq/l-","o":["Sodium","Potassium","Glucose","Chloride"],"a":0,"e":"Ans. is ''a'' i.e., Sodium Glucose should at least equal that of sodium but should not exceed 111 mmol/l Sodium should be within the range of 60-90 mEq/l Potassiumshould be within the range of 15-25 mEq/l Citrate should be within the range of 8-12 mmol/l Chloride should be within the range of 50-80 mEq/l","pyqMatches":[{"year":"2012","no":816,"q":"ORS contains 75 mEq/l","o":["Sodium","Potassium","Glucose","Chloride"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5494, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 105, '{"id":5494,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":105,"q":"ORS new osmolarity is -","o":["270","245","290","310"],"a":1,"e":"Ans. is ''b'' i.e., 245 o Osmolarity of new ORS (reduced osmolarity ORS) is 245 mmol/litre.","pyqMatches":[{"year":"2012","no":817,"q":"ORS new osmolarity is","o":["270","245","290","310"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5495, 'PSM', 'Communicable Diseases', 'Easy', 'Preventive_&_Social_Medicine', 106, '{"id":5495,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":106,"q":"In typhoid a permanent carrier is one who excretes bacilli for more than -","o":["3 months","6 months","1 year","3 years"],"a":2,"e":"Ans. is ''c'' i.e., 1 year Convalescent carriers shed the bacilli in feces for three weeks to three months post-infection. Temporary carriers shed the bacilli for between three and twelve months, and chronic carriers shed the bacilli for more than one year Bacilli presist in the gall bladder or kidney and are eliminated in the feces (fecal carriers) or urine (Urinary carrier), respectively. o The development of the carrier state is more common in women and in older age groups ( over 40 yrs) o Carriers are the more frequent source of infection than cases. o Urinary carriage is less frequent but more dangerous than intestinal carriers. o Note —> Permanent carriers are amongst the chronic carriers.","pyqMatches":[{"year":"2013","no":887,"q":"In typhoid a permanent carrier is one who excretes bacilli for more than","o":["3 months","6 months","1 year","3 years"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5496, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 107, '{"id":5496,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":107,"q":"Incubation period of plasmodium vivax is-","o":["5-7 days","7-10 days","10-14 days","15-30 days"],"a":2,"e":"Ans. is ''c'' i.e., 10-14 days","pyqMatches":[{"year":"2015","no":863,"q":"Incubation period of plasmodium vivax is","o":["5-7 days","7-10 days","10-14 days","15-30 days"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5497, 'PSM', 'Communicable Diseases', 'Easy', 'Preventive_&_Social_Medicine', 108, '{"id":5497,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":108,"q":"Malaria is transmitted in Rural areas by ?","o":["Anopheles stephensi","Anopheles dirus","Anopheles culicifacies","None"],"a":2,"e":"Ans. is ''c'' i.e., Anopheles culicifacies","pyqMatches":[{"year":"2013","no":890,"q":"Malaria is transmitted in Rural areas by ?","o":["Anopheles stephensi","Anopheles dirus","Anopheles culicifacies","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5498, 'PSM', 'Communicable Diseases', 'Easy', 'Preventive_&_Social_Medicine', 109, '{"id":5498,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":109,"q":"Most common anopheles mosquito for malaria in India-","o":["Anopheles stephensi","Anopheles subpictus","Anopheles fluviatilis","Anopheles dims"],"a":0,"e":"Ans. is ''a'' i.e., Anopheles stephensi \"Anopheles stephensi is the major malaria vector in India ______________ Foundation of Community Medicine","pyqMatches":[{"year":"2013","no":891,"q":"Most common anopheles mosquito for malaria in India","o":["Anopheles stephensi","Anopheles subpictus","Anopheles fluviatilis","Anopheles dims"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5499, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 110, '{"id":5499,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":110,"q":"Dose of chloroquine at 4-8 year -","o":["150 mg","300 mg","450 mg.","600 mg."],"a":1,"e":"Ans. is ''b'' i.e., 300 mg o 2 tablets of 150 mg are given. Chloroquine tablests as per age groups Chloroquine tablets 150 mg base Age in years Day 1 Day 2 Day 3 < 1 Y2 ''A 1/4 1-4 1 1 ''A 5-8 2 2 1 9-14 3 3 1V2 15 & above 4 4 2 Dose ofprimaquine for P falciparum (single dose) < 1 year Contraindicated 1 - 4 years 7.5 mg. 5 - 8 years 15 mg. 9 - 14 years 30 mg. 15 years 45 mg. Daily dose ofprimaquine for P vivax (for 14 days) < 1 year Contraindicated 1 - 4 years 2.5 mg 5 - 8 years 5 mg 9 - 14 years 10 mg 15 years 15 mg Note : Single dose ofprimaquine for P.falciparum is 3 times the daily dose ofprimaquine for P. vivax.","pyqMatches":[{"year":"2013","no":893,"q":"Dose of chloroquine at 4-8 year","o":["150 mg","300 mg","450 mg.","600 mg."],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5500, 'PSM', 'Communicable Diseases', 'Moderate', 'Preventive_&_Social_Medicine', 111, '{"id":5500,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":111,"q":"Prophaylaxis for malaria not used-","o":["Doxycycline","Artesunate","Chloroquine","Mefloquine"],"a":1,"e":"Ans. is ''b'' i.e., Artesunate o Drugs used for prophylaxis of malaria are chloroquine, proguanil, doxycycline, mefloquine and hydroxychloroquine.","pyqMatches":[{"year":"2012","no":818,"q":"Prophaylaxis for malaria not used","o":["Doxycycline","Artesunate","Chloroquine","Mefloquine"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5501, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 112, '{"id":5501,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":112,"q":"Chemoprohylaxis of chloroquine includes -","o":["300 mg BD/week","600 mg OD/week","600 mg/week","300 mg OD/week"],"a":3,"e":"Ans. is `d'' i.e., 300 mg OD/week Drug Dose for chemoprophylaxis Chloroquine 300 mg (3 tablets of 100 mg or 2 tablets of 150 mg) once a week or 100 mg/day for 6 day every week Proguanil 400 mg per day (2 tablets of 200 mg) Mefloquine 250 mg once a week Doxycycline 100 mg per day.","pyqMatches":[{"year":"2012","no":821,"q":"Chemoprohylaxis of chloroquine includes","o":["300 mg BD/week","600 mg OD/week","600 mg/week","300 mg OD/week"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5502, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 113, '{"id":5502,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":113,"q":"Maximum density of microfilariasis in blood is reported to be between -","o":["9 pm to 11 pm","11 pm to 2 am","8 pm to 10 pm","2 am to 5 am"],"a":1,"e":"Ans. is ''B'' i.e., 11 pm to 2 am The microfilaria of W. bancrofti and B. malayi occurring in India display a nocturnal periodicity, i.e., they appear in large numbers at night and retreat from the bloodstream during the day. This is a biological adaptation to the nocturnal biting habits of vector mosquitoes. The maximum density of microfilaria in the blood is reported between 10 pm and 2 am. When the sleeping habits of the host are altered, a reversal in periodicity has been observed.","pyqMatches":[{"year":"2013","no":909,"q":"Maximum density of microfilariasis in blood is reported to be between","o":["9 pm to 11 pm","11 pm to 2 am","8 pm to 10 pm","2 am to 5 am"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5503, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 114, '{"id":5503,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":114,"q":"Concentration of diethylcarbomazine in DEC medicated salt in endemic filariasis is","o":["2-4 gm/kg","3-6 gm/kg","5- 1 0 gm/kg","10- 15 gm/kg"],"a":0,"e":"Ans. is ''a'' i.e., 2-4 gm/kg o The use of DEC-medicated salt is a special form of mass treatment using very low doses of drug over a long period of time. o Common salt medicated with 1-4g of DEC per kg has been used for filariasis control in endemic areas of W. bancrofti and B malayi, particularly in Lakshadweep islands. o Treatment should be continued for at least 6-9 months.","pyqMatches":[{"year":"2013","no":900,"q":"Concentration of diethylcarbomazine in DEC medicated salt in endemic filariasis is","o":["2-4 gm/kg","3-6 gm/kg","5- 1 0 gm/kg","10- 15 gm/kg"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5504, 'PSM', 'National Health Programmes', 'Moderate', 'Preventive_&_Social_Medicine', 115, '{"id":5504,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":115,"q":"Based on the type of life cycle, zoonoses are classified into all of the following except -","o":["Cyclo-zoonoses","Meta-zoonoses","Anthropozoonoses","Sporozoonoses"],"a":2,"e":"Ans. is ''c'' i.e., Anthropozoonoses Classification of zoonoses 1) Based on direction of transmission : (i) Anthropozoonoses, (ii) Zoonthroponoses, and (iii) Amphixenoses 2) Based on type of life cycle : (i) Direct zoonoses, (ii) Cyclo- zoonoses, (iii) Meta-zoonoses, and (iv) Sporo​zoonoses.","pyqMatches":[{"year":"2013","no":902,"q":"Based on the type of life cycle, zoonoses are classified into all of the following except","o":["Cyclo-zoonoses","Meta-zoonoses","Anthropozoonoses","Sporozoonoses"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5505, 'PSM', 'Communicable Diseases', 'Moderate', 'Preventive_&_Social_Medicine', 116, '{"id":5505,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":116,"q":"Which of the following is a zoonotic disease ?","o":["Hydatid cyst","Malaria","Filariasis","dengue fever"],"a":0,"e":"Ans. is ''a'' i.e., Hydatid cyst Important zoonoses I. Bacterial –4 Anthrax, Brucellosis, Ornithoses, Q-fever, Leptospirosis, TB, Plague, Tularemia, Salmonellosis.","pyqMatches":[{"year":"2012","no":829,"q":"Which of the following is a zoonotic disease ?","o":["Hydatid cyst","Malaria","Filariasis","dengue fever"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5506, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 117, '{"id":5506,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":117,"q":"Which virus is used to produce rabies vaccine ?","o":["Wild","Street","Fixed","Live Attenuated"],"a":2,"e":"Ans. is ''c'' i.e., Fixed o There are two strains of rabies virus : ? i) Street virus - This the virus, responsible for natural rabies and is isolated from natural human or animal infection. ii) Fixed virus - It is isolated after several serial intracerebral passage in rabbit. It is used to prepare rabies vaccine.","pyqMatches":[{"year":"2012","no":826,"q":"Which virus is used to produce rabies vaccine ?","o":["Wild","Street","Fixed","Live Attenuated"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5507, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 118, '{"id":5507,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":118,"q":"Schedule of intradermal rabies vaccine is ?","o":["2-2-0-1-0-1","8-0-4-0-1-1","8-4-4-1-0-1","2-0-2-0-0"],"a":3,"e":"Ans. is ''d'' i.e., 2-0-2-0-0 WHO-recommended and alternative pre-exposure prophylactic regimens PrEP regimen Duration of course Number of injection sites per clinic visit (days 0, 3, 7, 14, 21–28) WHO-recommended intradermal regimen Two visits 7 days 2-0-2-0-0 WHO-recommended intramuscular regimen Two visits 7 days 1-0-1-0-0 PrEP under specific circumstances Single visit, intradermal 1 day 2-0-0-0-0 Single visit, intramuscular 1 day 1-0-0-0-0","pyqMatches":[{"year":"2013","no":798,"q":"Schedule of intradermal rabies vaccine is ?","o":["2-2-0-1-0-1","8-0-4-0-1-1","8-4-4-1-0-1","2-0-2-0-0"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5508, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 119, '{"id":5508,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":119,"q":"Site for injection of cell culture rabies vaccine-","o":["Gluteus","Subcutaneous","Deltoid","Anterior abdominal wall"],"a":2,"e":"Ans. is ''c'' i.e., Deltoid o Rabies vaccine is given by either of two routes:? i) Intramuscular : Deltoid (most preferred) and/or thigh (in children < 2 years, anterolateral thigh is preferred). ii)Intradermal : Over deltoid and/or thigh. o In intramuscular regimen, injection is given into deltoid, while in intradermal regimen, injection is given intradermally over deltoid.","pyqMatches":[{"year":"2013","no":799,"q":"Site for injection of cell culture rabies vaccine","o":["Gluteus","Subcutaneous","Deltoid","Anterior abdominal wall"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5509, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 120, '{"id":5509,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":120,"q":"Yellow fever aedes agypti index should be ?","o":["<1%","< 5%","<10%","< 20%"],"a":0,"e":"Ans. is ''a'' i.e., < 1%","pyqMatches":[{"year":"2012","no":819,"q":"Yellow fever aedes agypti index should be ?","o":["<1%","< 5%","<10%","< 20%"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
