INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5511, 'PSM', 'Immunization', 'Moderate', 'Preventive_&_Social_Medicine', 122, '{"id":5511,"subject":"PSM","chapter":"Immunization","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":122,"q":"The international quarantine period for yellow fever as approved by the Government of India is ?","o":["6 days","9 days","10 days","12 days"],"a":0,"e":"Ans. is ''a'' i.e., 6 days o Quarantine period --> 6 days from the date of leaving an infected area. o Validity of certificate —> Starts 10 days after the date of vaccination.","pyqMatches":[{"year":"2013","no":897,"q":"The international quarantine period for yellow fever as approved by the Government of India is ?","o":["6 days","9 days","10 days","12 days"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5512, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 123, '{"id":5512,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":123,"q":"Mucocutaneous leishmaniasis is caused by -","o":["L-braziliensis","L. tropica","L. donovani","L-orientalis"],"a":0,"e":"Ans. is ''a'' i.e., L. braziliensis Leishmaniasis o Visceral leishmaniasis (Kala azar) -L. donovani Cutaneous Leishmaniasis a) Oriental sore - L. tropica b) Mucocutaneous leishmaniasis (Espundia) -L. brasiliensis","pyqMatches":[{"year":"2014","no":842,"q":"Mucocutaneous leishmaniasis is caused by","o":["L-braziliensis","L. tropica","L. donovani","L-orientalis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5513, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 124, '{"id":5513,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":124,"q":"Epidemic typhus cause & vector -","o":["Rickettessiae prowazki & Louse","R. typhi & mite","R. conorii & tick","R. akari & mite"],"a":0,"e":"Ans. is ''a'' i.e., Rickettessiae prowazki & Louse","pyqMatches":[{"year":"2012","no":822,"q":"Epidemic typhus cause & vector","o":["Rickettessiae prowazki & Louse","R. typhi & mite","R. conorii & tick","R. akari & mite"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5514, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 125, '{"id":5514,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":125,"q":"Vector of scrub typhus in man ?","o":["O. tsutsugamushi","Leptotrombidium deliense","Lice","Pediculous humanus"],"a":1,"e":"Ans. is ''b'' i.e., Leptotrombidium deliense o For scrub typhus :- Causative agent R. tsutsugamushi Vector trombiculid mite (Leptotrombidium delinese and L. akamushi)","pyqMatches":[{"year":"2012","no":823,"q":"Vector of scrub typhus in man ?","o":["O. tsutsugamushi","Leptotrombidium deliense","Lice","Pediculous humanus"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5515, 'PSM', 'Epidemiology', 'Moderate', 'Preventive_&_Social_Medicine', 126, '{"id":5515,"subject":"PSM","chapter":"Epidemiology","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":126,"q":"To achieve neonatal tetanus elimination, incidence of neonatal tetanus per 1000 live births should be reduced to less than -","o":["0.1","02","0.5","1.0"],"a":0,"e":"Ans. is `a'' i.e., 0.1 o Districts are being classified into three categories, depending on neonatal tetanus incidence rate, immunization coverage in pregnant women, and proportion of clean deliveries by trained personnel.","pyqMatches":[{"year":"2013","no":904,"q":"To achieve neonatal tetanus elimination, incidence of neonatal tetanus per 1000 live births should be reduced to less than","o":["0.1","02","0.5","1.0"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5516, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 127, '{"id":5516,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":127,"q":"\"Multibacillary\" is a spectrum of disease, seen in-","o":["Leprosy","TB","Tetanus","Trachoma"],"a":0,"e":"Ans. is ''a'' i.e., Leprosy","pyqMatches":[{"year":"2012","no":824,"q":"\"Multibacillary\" is a spectrum of disease, seen in","o":["Leprosy","TB","Tetanus","Trachoma"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
