INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5518, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 129, '{"id":5518,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":129,"q":"Life span of cut380a -","o":["10 yrs","20 yrs","1 yrs","None"],"a":0,"e":"Ans. is ''a'' i.e., 10 years","pyqMatches":[{"year":"2012","no":845,"q":"Life span of cut380a","o":["10 yrs","20 yrs","1 yrs","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5519, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 130, '{"id":5519,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":130,"q":"Copper T is ideally inserted at-","o":["Just before menstruation","On the 26th day","Just after menstruation","On the 14th day"],"a":2,"e":"Ans. is ''c'' i.e., Just after menstruation Timing of insertion Although the loop can be inserted at almost anytime during a woman''s reproductive years (except during pregnancy), the most propitious time for loop insertion is during mensturation or within 10 days of the beginning of a menstural period. o During this period, insertion is technically easy because the diameter of the cervical canal is greater at this time than during the secretory phase. o The uterus is relaxed and myometrial contractions which might tend to cause expulsion are at a minimum. o In addition, the risk that a woman is pregnant is remote at this time.","pyqMatches":[{"year":"2013","no":926,"q":"Copper T is ideally inserted at","o":["Just before menstruation","On the 26th day","Just after menstruation","On the 14th day"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5520, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 131, '{"id":5520,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":131,"q":"Absolute contraindication for IUD (Intra Uterine Contraceptive Device) are all except ?","o":["Pregnancy","Undiagnosed vaginal bleeding","Pelvic inflammatory disease","Uterine malformation"],"a":3,"e":"Ans. is ''d i.e., Uterine malformation Contraindications ABSOLUTE: a) Suspected pregnancy b) Pelvic inflammatory disease c) Vaginal bleeding of undiagnosed etiology d) Cancer of the cervix, uterus or adnexa and other pelvic tumours e) Previous ectopic pregnancy RELATIVE : a) Anaemia b) Menorrhagia c) History of PID(Pelvic Inflammatory Disease) since last pregnancy d) Purulent cervical discharge e) Distortions of the uterine cavity due to congenital malformations, fibroid f) Unmotivated person","pyqMatches":[{"year":"2015","no":1526,"q":"Absolute contraindication for IUD (Intra Uterine Contraceptive Device) are all except ?","o":["Pregnancy","Undiagnosed vaginal bleeding","Pelvic inflammatory disease","Uterine malformation"],"a":3,"source":"NEET_2015_Paper.pdf"},{"year":"2020","no":117,"q":"Absolute contraindication for IUD (Intra Uterine Contraceptive Device) are all except –","o":["Pregnancy","Undiagnosed vaginal bleeding","Pelvic inflammatory disease","Uterine malformation"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2015","2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5521, 'PSM', 'Demography & Family Planning', 'Moderate', 'Preventive_&_Social_Medicine', 132, '{"id":5521,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":132,"q":"All of the following are postcoital contraception methods except-","o":["Mifepristone","IUD","Levonorgestrol","Barrier methods"],"a":3,"e":"Ans. is ''d'' i.e., Barrier methods","pyqMatches":[{"year":"2013","no":923,"q":"All of the following are postcoital contraception methods except","o":["Mifepristone","IUD","Levonorgestrol","Barrier methods"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5522, 'PSM', 'Biostatistics', 'Easy', 'Preventive_&_Social_Medicine', 133, '{"id":5522,"subject":"PSM","chapter":"Biostatistics","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":133,"q":"Mean birth weight in India -","o":["2.0 - 2.4 kg","2.4 - 2.5 kg","2.5 - 2.9 kg","> 3.0 kg"],"a":2,"e":"Ans. is ''c'' i.e., 2.5 - 2.9 kg Mean birth weight in Different parts of the world Region Mean birth weight North America, Western Europe, Australia 3.5 - 3.6 kg Eastern Europe 3.1 - 3.3 kg Africa and East Asia 2.9 - 3.1 kg South Asian countries 2.7 kg o In India, mean birth weight ranges from 24.9 kg to 28.8 kg.","pyqMatches":[{"year":"2012","no":842,"q":"Mean birth weight in India","o":["2.0 - 2.4 kg","2.4 - 2.5 kg","2.5 - 2.9 kg","> 3.0 kg"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5523, 'PSM', 'Maternal & Child Health', 'Easy', 'Preventive_&_Social_Medicine', 134, '{"id":5523,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":134,"q":"MCH care is assessed by -","o":["Death rate","Birth rate","Maternal mortality rate","Anemia in mother"],"a":2,"e":"Ans. is ''c'' i.e., Maternal mortality rate Important MCH indicators","pyqMatches":[{"year":"2012","no":848,"q":"MCH care is assessed by","o":["Death rate","Birth rate","Maternal mortality rate","Anemia in mother"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5524, 'PSM', 'Maternal & Child Health', 'Easy', 'Preventive_&_Social_Medicine', 135, '{"id":5524,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":135,"q":"Quarter of postnatal mother death is caused by ?","o":["Infection","Bleeding","Eclampsia","Anemia"],"a":1,"e":"Ans. is `b'' i.e., Bleeding o 25% of maternal death are caused by severe bleeding, generally occuring post-partum.","pyqMatches":[{"year":"2013","no":932,"q":"Quarter of postnatal mother death is caused by ?","o":["Infection","Bleeding","Eclampsia","Anemia"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5525, 'PSM', 'Maternal & Child Health', 'Easy', 'Preventive_&_Social_Medicine', 136, '{"id":5525,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":136,"q":"Maternal mortality is maximum in which period","o":["Antepartum","Peripartum","Postpartum","None"],"a":1,"e":"Ans. is ''b'' i.e., Peripartum o Maternal death mostly occur from the third trimester to the first week after birth. Studies show that mortality risks for mothers are particularly elevated in the first two days after birth.","pyqMatches":[{"year":"2012","no":853,"q":"Maternal mortality is maximum in which period","o":["Antepartum","Peripartum","Postpartum","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5526, 'PSM', 'Maternal & Child Health', 'Easy', 'Preventive_&_Social_Medicine', 137, '{"id":5526,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":137,"q":"Maximum maternal mortality during peripartum period occurs at -","o":["Last trimester","During labor","Immediate post-partum","Delayed post-partum"],"a":2,"e":"Ans. is ''c'' i.e., Immediate post-partum o Studies show that mortality risks for mother are particularly elevated in the first two days after birth, i.e. immediate post-partum period. o A women is most vulnearble at post-partum period. About 50-70% maternal death occuring in the post-partum period of which 45% deaths occur in first 24 hours after delivery and more than two-third druing the first week.","pyqMatches":[{"year":"2013","no":933,"q":"Maximum maternal mortality during peripartum period occurs at","o":["Last trimester","During labor","Immediate post-partum","Delayed post-partum"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5527, 'PSM', 'Demography & Family Planning', 'Moderate', 'Preventive_&_Social_Medicine', 138, '{"id":5527,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":138,"q":"Calculate IMR if in a population of 100000 there are 3000 live births in a year and 150 infant deaths in the same year -","o":["75","18","5","50"],"a":3,"e":"Ans. is `d'' i.e., 50","pyqMatches":[{"year":"2015","no":823,"q":"Calculate IMR if in a population of 100000 there are 3000 live births in a year and 150 infant deaths in the same year","o":["75","18","5","50"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5528, 'PSM', 'Maternal & Child Health', 'Easy', 'Preventive_&_Social_Medicine', 139, '{"id":5528,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":139,"q":"Which is the least common cause among these of infant mortality in India -","o":["Infections","Prematurity","Birth injuries","Congenital malformations"],"a":2,"e":"Ans. is ''c'' i.e., Birth injuries","pyqMatches":[{"year":"2012","no":847,"q":"Which is the least common cause among these of infant mortality in India","o":["Infections","Prematurity","Birth injuries","Congenital malformations"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5529, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 140, '{"id":5529,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":140,"q":"Best indicator of availability,utilisation & effectiveness of health services-","o":["IMR","MMR","Hospital bed OCR","DALY"],"a":0,"e":"Ans. is ''a'' i.e., IMR","pyqMatches":[{"year":"2012","no":850,"q":"Best indicator of availability,utilisation & effectiveness of health services","o":["IMR","MMR","Hospital bed OCR","DALY"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5530, 'PSM', 'Maternal & Child Health', 'Easy', 'Preventive_&_Social_Medicine', 141, '{"id":5530,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":141,"q":"Most common cause of infant mortality?","o":["LBW","Injury","ART","Tetanus"],"a":0,"e":"Ans. is ''a'' i.e., LBW","pyqMatches":[{"year":"2013","no":936,"q":"Most common cause of infant mortality?","o":["LBW","Injury","ART","Tetanus"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5531, 'PSM', 'Maternal & Child Health', 'Easy', 'Preventive_&_Social_Medicine', 142, '{"id":5531,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":142,"q":"Perinatal mortality rate include which of the following?","o":["Abortions + Still birth early neonatal deaths","Still birth + early neonatal deaths","Abortions + early neonatal deaths","Deaths up to 42 dys after birth"],"a":1,"e":"Ans. is b'' i.e., Still birth + early neonatal death","pyqMatches":[{"year":"2016","no":854,"q":"Perinatal mortality rate include which of the following?","o":["Abortions + Still birth early neonatal deaths","Still birth + early neonatal deaths","Abortions + early neonatal deaths","Deaths up to 42 dys after birth"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5532, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 143, '{"id":5532,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":143,"q":"Human milk with respect to cow milk has -","o":["Less fat","Less protein","Less carbohydrate","a and b"],"a":3,"e":"Ans. is ''a'' i.e., Less fat; `b'' Less protein Human milk has less fat, less protein, more carbohydrates and less calcium, in comparison to cow milk. Human milk has less sodium, potassium and chloride. However, these substances are in correct amount (though less) in human milk. Salts (meq/L)Cow''s milk Human milk Sodium 25 (too much)6.5 (correct amount) Chloride 29 (too much)12 (correct amount) Potassium 35 (too much)14 (correct amount)","pyqMatches":[{"year":"2016","no":860,"q":"Human milk with respect to cow milk has","o":["Less fat","Less protein","Less carbohydrate","a and b"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5533, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 144, '{"id":5533,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":144,"q":"What is absent in breast milk ?","o":["Vit K","Vit C","Lactose","Vit A"],"a":0,"e":"Ans. is ''a'' i.e., Vitamin K o Milks from the mother whose diet is sufficient and properly balanced will supply all the necessary nutrients except fluoride and Vitamin D. o The iron content of human milk is low, but most normal term infants have sufficient iron stores for the first 4-6 months. Human milk iron is well absorbed. Nonetheless, by 6 months the breast-fed infant''s diet should be supplemented with iron fortified complementary foods. o The Vitamin K content of human milk is low and may cause hemorrhagic disease of newborn.","pyqMatches":[{"year":"2012","no":912,"q":"What is absent in breast milk ?","o":["Vit K","Vit C","Lactose","Vit A"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5534, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 145, '{"id":5534,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":145,"q":"Colostrums has in compared to normal milk ?","o":["Decreased K","Decreased Na","Increased proteins","Increased calories"],"a":2,"e":"Ans. is ''c'' i.e., Increased proteins","pyqMatches":[{"year":"2012","no":852,"q":"Colostrums has in compared to normal milk ?","o":["Decreased K","Decreased Na","Increased proteins","Increased calories"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5535, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 146, '{"id":5535,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":146,"q":"In normal delivery, breast feeding should be started?","o":["6 hour after delivary","2 hour after delivary","4 hour after delivary","None"],"a":3,"e":"Ans is d None o Breast feeding should be initiated within 30 min. of a normal vaginal delivery. o Breast feeding should be initiated within 4 hrs of delivery by caesarian section.","pyqMatches":[{"year":"2012","no":849,"q":"In normal delivery, breast feeding should be started?","o":["6 hour after delivary","2 hour after delivary","4 hour after delivary","None"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5536, 'PSM', 'National Health Programmes', 'Easy', 'Preventive_&_Social_Medicine', 147, '{"id":5536,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":147,"q":"ICDS was launched at-","o":["Community development block","Town level","City level","District level"],"a":0,"e":"Ans. is ''a'' i.e., Community development block o ICDS was launched on 2\"d October 1975 in 33 Community development block. o ICDS programme is a globally recognized community based early child care programme, which addresses the basic interrelated needs of yound children, expectant and nursing mothers and adolescent girls across the life cycle, in a holistic manner.","pyqMatches":[{"year":"2012","no":894,"q":"ICDS was launched at","o":["Community development block","Town level","City level","District level"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5537, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 148, '{"id":5537,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":148,"q":"Nutritional supplement for two year old child under ICDS scheme is -","o":["200 Calorie","300 Calorie","400 Calorie","500 Calorie"],"a":3,"e":"Ans. is ''d'' i.e., 500 calories o Under ICDS Scheme supplementary nutrition is given to: Children below 6 yrs Nursing mothers Expectant mothers o The aim is to supplement nutritional intake for 1) Each child 6-72 months of age —) 500 calories and 12-15 grams of protein (financial norm of Rs 6.00 per child per day). 2) Severely malnourished child 6-72 months of age --> 800 calories and 20-25 grams protein (financial norm of Rs 6.00 per child per day). 3) Each pregnant and nursing woman 600 calories and 18-20 grams of protein (financial norm of Rs 5.00 per beneficiary per day). Under the revised nutritional and feeding norms for supplementary nutrition, State governments/UTs have been mandated to provide more than one meal to the children who come to AWCs, which include providing a morning snack in the form of milk/banana/egg/seasonal fruit/micronutrient fortified food followed by a hot cooked meal. For children below 3 years of age and pregnant & lactating mothers, \"take home ration\" is to be provided. o Supplementary nutrition is given for 300 days a year.","pyqMatches":[{"year":"2012","no":917,"q":"Nutritional supplement for two year old child under ICDS scheme is","o":["200 Calorie","300 Calorie","400 Calorie","500 Calorie"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5538, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 149, '{"id":5538,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":149,"q":"Direct cash transfer scheme to adolescent girls is covered under -","o":["Indira Gandhi scheme","Rajiv Gandhi scheme","CSSM","RCH"],"a":1,"e":"Ans. is ''b'' i.e., Rajiv Gandhi Scheme o Direct cash transfer scheme to adolescent girls comes under \"Rajiv Gandhi Scheme for Empowerment of Adolescent Girls\"","pyqMatches":[{"year":"2012","no":908,"q":"Direct cash transfer scheme to adolescent girls is covered under","o":["Indira Gandhi scheme","Rajiv Gandhi scheme","CSSM","RCH"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5539, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 150, '{"id":5539,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":150,"q":"Child protection scheme is under which ministry -","o":["Ministry of health and family welfare","Ministry of Social welfare","Ministry of women and child development","Ministry of education"],"a":2,"e":"Ans. is ''c'' i.e., Ministry of women and child development o In 2006 the Ministry of Women and Child Development (MWCD) proposed adoption of Integrated Child Protection Scheme (ICPS). o In 2009 the central government take the scheme its approval and has begun the extensive task of providing children with a protective and safe environment to develop and florish. o The purpose of the scheme is to provide for children in difficult circumstances, as well as to reduce the risks and vulnerabilities children have in various situations and actions that lead to abuse, neglect, exploitation, abondonment and separation of children.","pyqMatches":[{"year":"2012","no":770,"q":"Child protection scheme is under which ministry","o":["Ministry of health and family welfare","Ministry of Social welfare","Ministry of women and child development","Ministry of education"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5540, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 151, '{"id":5540,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":151,"q":"Homes where children are placed under the care of doctors and psychiatrists are called -","o":["Foster homes","Borstals","Remand homes","Child guidance clinics"],"a":2,"e":"Ans. is ''c'' i.e., Remand homes Child placement : o Orphanages : For children who have no home or cannot be taken care of by their parents. o Foster Homes : Several types of facilities for rearing children other than in natural families. o Adoption : Legal adoption confers upon child and the adoptive parents, rights and responsibilities similar to that of natural parents. o Remand Homes : Child is placed under the care of doctors, psychiatrists and other trained personnel to improve the mental and physical well being of the child.","pyqMatches":[{"year":"2012","no":841,"q":"Homes where children are placed under the care of doctors and psychiatrists are called","o":["Foster homes","Borstals","Remand homes","Child guidance clinics"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5541, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 152, '{"id":5541,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":152,"q":"Ujjwala is for -","o":["Child abuse","Child trafficking","Child labour","None"],"a":1,"e":"Ans. is ''b'' i.e., Child trafficking o The ''Ministry of women & child Development'' has formulated a new comprehensive scheme for prevention of trafficking and rescue, rehabilitation and reintegration of victims of trafficking and commercial sexual exploitation. o The new scheme has been conceived primarily for the purpose preventing trafficking on the one hand and rescue and rehabilitation of victims on the other. o Target group includes - i) Women & children who are vulnerable to trafficking for commercial sexual exploitation. ii) Women & children who are victims of trafficking for commercial sexual exploitation.","pyqMatches":[{"year":"2012","no":906,"q":"Ujjwala is for","o":["Child abuse","Child trafficking","Child labour","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5542, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 153, '{"id":5542,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":153,"q":"Perinatal mortality includes deaths-","o":["After 28 weeks of gestation","First 7 days after birth","Both","From period of viability"],"a":2,"e":"Ans. is ''c'' i.e., Both","pyqMatches":[{"year":"2012","no":851,"q":"Perinatal mortality includes deaths","o":["After 28 weeks of gestation","First 7 days after birth","Both","From period of viability"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5543, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 154, '{"id":5543,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":154,"q":"Energy requirement in late pregnancy -","o":["2500 cal","1400 cal","1000 cal","1000 cal"],"a":0,"e":"Ans. is ''a'' i.e., 2500 Cal","pyqMatches":[{"year":"2012","no":854,"q":"Energy requirement in late pregnancy","o":["2500 cal","1400 cal","1000 cal","1000 cal"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5544, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 155, '{"id":5544,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":155,"q":"Protein quality assessment is best done by ?","o":["NPU","Biological value","Digestibillity coefficient","Amino acid score"],"a":0,"e":"Ans. is ''a'' i.e., NPU o Net protein utilization is considered to be most practile because it is the product of biological value and digestibility coefficient divided by 100.","pyqMatches":[{"year":"2015","no":888,"q":"Protein quality assessment is best done by ?","o":["NPU","Biological value","Digestibillity coefficient","Amino acid score"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5545, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 156, '{"id":5545,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":156,"q":"The highest concentrations of Vitamin A is seen in -","o":["Polar bear liver","Cod liver oil","Shark liver oil","Papaya"],"a":1,"e":"Ans. is ''b'' i.e., Codliver oil Amongst the given options, cod liver oil has highest concentration.","pyqMatches":[{"year":"2013","no":941,"q":"The highest concentrations of Vitamin A is seen in","o":["Polar bear liver","Cod liver oil","Shark liver oil","Papaya"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5546, 'PSM', 'Maternal & Child Health', 'Easy', 'Preventive_&_Social_Medicine', 157, '{"id":5546,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":157,"q":"''Vitamin A requirement in infant is-","o":["350 g","600 g","800 g","1000 g"],"a":0,"e":"Ans. is ''a'' i.e., 350 g","pyqMatches":[{"year":"2012","no":855,"q":"''Vitamin A requirement in infant is","o":["350 g","600 g","800 g","1000 g"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5547, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 158, '{"id":5547,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":158,"q":"Jowar is Pellogerogenic due to excess of -","o":["Leucine","Lysine","Tryptophan","Methioninc"],"a":0,"e":"Ans. is ''a'' i.e., Leucine o Similar to maize, Jowar also Contains excess of leucine. o Leucine interferes with conversion of tryptophan to niacin. o Pellagra has been reported in India in Telangana area of Andhra Pradesh because of Sower (Sorghum vulgare) consumption.","pyqMatches":[{"year":"2012","no":861,"q":"Jowar is Pellogerogenic due to excess of","o":["Leucine","Lysine","Tryptophan","Methioninc"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5548, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 159, '{"id":5548,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":159,"q":"For every 100 kilocalories, vitamin B, required is -","o":["0.05 mg","0.5 mg","5.0 mg","1.0 gn"],"a":0,"e":"Ans. is ‘a'' i.e., 0.05 rug Thiamine is required 0.5 mg per 1000 K. cal of energy intake, i.e., 0.05 mg per 100 Kcal.","pyqMatches":[{"year":"2016","no":857,"q":"For every 100 kilocalories, vitamin B, required is","o":["0.05 mg","0.5 mg","5.0 mg","1.0 gn"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5549, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 160, '{"id":5549,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":160,"q":"Daily iron requirement in healthy Indian male is-","o":["35 mg","17 mg","10 mg","5 mg"],"a":1,"e":"Ans. is ''b i.e., 17 mg Group Iron absorbed/day(mg) Recommended intake Adult male 0.84 17 Adult female (mensturating) 1.65 21 Pregnant woman 2.80 (extra 1.15) 35 (extra 14 mg/day) Lactating woman (0-6 months) 1.65 21 Infant (6-12 months) 0.7 S Adolescent boys (13-15 years) 1.6 32 Adolescent girls (13-15 years) 1.36 27","pyqMatches":[{"year":"2016","no":863,"q":"Daily iron requirement in healthy Indian male is","o":["35 mg","17 mg","10 mg","5 mg"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5550, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 161, '{"id":5550,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":161,"q":"Iodine RDA is -","o":["300 microgram","500 microgram","150 microgram","50 microgram"],"a":2,"e":"Ans. is `c\" i.e., 150 microgratn o The RDA of iodine for adults is 150 microgram.","pyqMatches":[{"year":"2012","no":858,"q":"Iodine RDA is","o":["300 microgram","500 microgram","150 microgram","50 microgram"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5551, 'PSM', 'National Health Programmes', 'Easy', 'Preventive_&_Social_Medicine', 162, '{"id":5551,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":162,"q":"Iodine deficiency control programme ?","o":["Health education","Water testing","Fortification of salt","None"],"a":2,"e":"Ans. is ''c'' i.e., Fortification of salt Iodized salt (salt fortified with iodine) is most economical, convenient and effective means of mass prophylaxis in endemic area.","pyqMatches":[{"year":"2012","no":869,"q":"Iodine deficiency control programme ?","o":["Health education","Water testing","Fortification of salt","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5552, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 163, '{"id":5552,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":163,"q":"Iodine comes in iodine salt. Req uirm en t at production and consumer level respectively -","o":["20 & 10 PPNI","30 & 10 PPM","30& 15 PPM","30 & 20 PPM"],"a":2,"e":"Ans. is \"c'' i.e., 30 & 15 PPM","pyqMatches":[{"year":"2012","no":859,"q":"Iodine comes in iodine salt. Req uirm en t at production and consumer level respectively","o":["20 & 10 PPNI","30 & 10 PPM","30& 15 PPM","30 & 20 PPM"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5553, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 164, '{"id":5553,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":164,"q":"Maximum calcium is seen in -","o":["Jowar","Bajara","Ragi","None"],"a":2,"e":"Ans. is ''c'' i.e., Ragi Millets o The term \"millet\" is used for smaller grains : - i) Jowar (Sorghum) ii) Bajara (Pearl millet) iii) Ragi o Amongst millets Maximum protein Bajra Maximum fat Bajra Maximum carbohydrate Jowar Maximum minerals & Calcium Ragi Maximum vit B complex Jowar Maximum energy Bajra Maximum iron Bajra","pyqMatches":[{"year":"2013","no":937,"q":"Maximum calcium is seen in","o":["Jowar","Bajara","Ragi","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5554, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 165, '{"id":5554,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":165,"q":"Which nut has highest protein content -","o":["Walnut","Groundnut","Almond","Coconut"],"a":1,"e":"Ans. is ''b'' i.e., Groundnut o Nuts commonly consumed in India are coconut, groundnut, cashew nut, walnut and almond. o Groundnut has maximum protein contents. o There is no need to remember this table. I am summarizing it for you. Groundnut has maximum protein and Carbohydrate. Coconut has minimum protein. Walnut has maximum fat. Groundnut has minimum fat. o Almond has minimum carbohydrate. Almond has maximum minerals. Coconut has minimum minerals.","pyqMatches":[{"year":"2013","no":939,"q":"Which nut has highest protein content","o":["Walnut","Groundnut","Almond","Coconut"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5555, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 166, '{"id":5555,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":166,"q":"Students receive how much cereal /day in mid day meal prog -","o":["50 gm","100 gm","150 gm","75 gm"],"a":3,"e":"Ans. is ''d'' i.e., 75 gm","pyqMatches":[{"year":"2012","no":915,"q":"Students receive how much cereal /day in mid day meal prog","o":["50 gm","100 gm","150 gm","75 gm"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5556, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 167, '{"id":5556,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":167,"q":"Mid day meal programme comes under ?","o":["Ministry of Social Welfare","Ministry of education","Ministry of Human Resources Developments","None"],"a":1,"e":"Ans. is ''b'' i.e., Ministry of education It is also called as National Programme of Nutritional Support to Primary Education. It was launched in 1995. Mid-day meal should provide 1/3 of total energy and 1/2 of total protein requirements.","pyqMatches":[{"year":"2012","no":910,"q":"Mid day meal programme comes under ?","o":["Ministry of Social Welfare","Ministry of education","Ministry of Human Resources Developments","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5557, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 168, '{"id":5557,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":168,"q":"Calcium requirement above the normal during the first six month of lactation is -","o":["400Mgiday","550mg/day","600mg/day","750mg/day"],"a":2,"e":"Ans. is ''c'' i.e., 600 mg","pyqMatches":[{"year":"2012","no":857,"q":"Calcium requirement above the normal during the first six month of lactation is","o":["400Mgiday","550mg/day","600mg/day","750mg/day"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5558, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 169, '{"id":5558,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":169,"q":"Adult non-pregnant female requires, Calcium per day -","o":["400 mg","600 mg","800 mg","1000 mg"],"a":1,"e":"Ans. is ''b'' i.e., 600 mg o Adult non-pregnant female requires 600 mg calcium per day.","pyqMatches":[{"year":"2012","no":856,"q":"Adult non-pregnant female requires, Calcium per day","o":["400 mg","600 mg","800 mg","1000 mg"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5559, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 170, '{"id":5559,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":170,"q":"The ICDS scheme is sponsored by","o":["Ministry of health & family welfare","Ministry of Social welfare","Ministry of education","None"],"a":1,"e":"Ans. is ''b'' i.e., Ministry of social welfare","pyqMatches":[{"year":"2016","no":880,"q":"The ICDS scheme is sponsored by","o":["Ministry of health & family welfare","Ministry of Social welfare","Ministry of education","None"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5560, 'PSM', 'Environment & Occupational Health', 'Easy', 'Preventive_&_Social_Medicine', 171, '{"id":5560,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":171,"q":"Most common cause of pollution of drinking water","o":["Domestic waste","Industrial waste","Radioactive substances","Agricultural pollutants"],"a":1,"e":"Ans. is ''b'' i.e., Industrial waste o Two most common causes of water pollution i) Domestic sewage ii) Industrial wastes Among these two industrial wastes are the most common","pyqMatches":[{"year":"2013","no":945,"q":"Most common cause of pollution of drinking water","o":["Domestic waste","Industrial waste","Radioactive substances","Agricultural pollutants"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5561, 'PSM', 'Communicable Diseases', 'Easy', 'Preventive_&_Social_Medicine', 172, '{"id":5561,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":172,"q":"Which of the following is water-related disease","o":["Yellow fever","Scabies","Cholera","Dysentery"],"a":0,"e":"Ans. is ''a'' i.e., Yellow fever * Water can cause disease not only by drinking but also by various other modes, directly or indirectly. * Depending upon the type of transmission, the diseases are classified. * Public Health Classification of Waterborne diseases * Waterborne diseases: Occur due to drinking contaminated water, transmitted by the faeco-oral route. Examples: Typhoid, Cholera. Dysentery, Viral Hepatitis A * Water washed diseases: Include infections of the outer body surface which occur due to inadequate use of water or improper hygiene. Examples: Scabies, Trachoma, Typhus, Bacillary dysentery, Amoebic dysentery * Water-based diseases: Refers to infections transmitted through an aquatic invertebrate animal. Examples: Schistosomiasis. Dracunculiasis ( Guinea worm disease) * Water-related diseases (Water breeding diseases): Are infections spread by insects that depend on water. Examples: Malaria, Filariasis, Dengue, Yellow fever, Onchocerciasis","pyqMatches":[{"year":"2020","no":118,"q":"Which of the following is water-related disease","o":["Yellow fever","Scabies","Cholera","Dysentery"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5562, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 173, '{"id":5562,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":173,"q":"True about slow sand filter is","o":["Occupies less space","More expensive","Requires longer duration","Sand size 0.4 - 0.7 mm"],"a":2,"e":"Ans. is ''c'' i.e., Requires longer duration The slow sand filter requires more time (duration). The size of the sand is smaller (0.2-0.3 mm). Slow sand filter occupies a large area (more space). The cost of construction is cheaper for the slow sand filter.","pyqMatches":[{"year":"2013","no":947,"q":"True about slow sand filter is","o":["Occupies less space","More expensive","Requires longer duration","Sand size 0.4 - 0.7 mm"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5563, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 174, '{"id":5563,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":174,"q":"Test for coliform count ?","o":["Eijkman test","Casoni''s test","Nitrate test","Urease test"],"a":0,"e":"Ans. is ''a'' i.e., Eijkman test Adler analysing presumptive coliform count, E coli count is cofirmed by other tests like Eijk m an t test and indole production.","pyqMatches":[{"year":"2012","no":761,"q":"Test for coliform count ?","o":["Eijkman test","Casoni''s test","Nitrate test","Urease test"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2016","no":867,"q":"Test for coliform count ?","o":["Eijkman test","Casoni''s test","Nitrate test","Urease test"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2012","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5564, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 175, '{"id":5564,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":175,"q":"Above which level of heat stress index it is not possible to work comfortably -","o":["20 - 40","40 - 60","60 - 80","80 - 100"],"a":1,"e":"Ans. is b''., 40-60 o HSI 40-60 causes severe heat strain and it is not possible to work comfortably.","pyqMatches":[{"year":"2012","no":914,"q":"Above which level of heat stress index it is not possible to work comfortably","o":["20 - 40","40 - 60","60 - 80","80 - 100"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5565, 'PSM', 'Environment & Occupational Health', 'Moderate', 'Preventive_&_Social_Medicine', 176, '{"id":5565,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":176,"q":"Which of the following is not a indoor air pollutant?","o":["Carbon monoxide","Nitrous oxide","Radon","Mercury"],"a":3,"e":"Ans. is ''d i.e., Mercury Indoor air pollution refers to chemical. biological and physical contamination of indoor air, i.e. the pollution of air with in and around building and structures. As most of the people work, study, eat, drink and sleep in enclosed environments (i.e. indoor) where air circulation may be restricted —> Most people spend large portion of time indoors, as much as 80- 90% of their lives. Therefore, more people suffer from indoor air pollution than outdoor pollution. Basic Information on Pollutants and Sources of Indoor Air Pollution Asbestos Biological Pollutants Carbon Monoxide (CO) Formaldehyde/Pressed Wood Products Lead (Pb) Nitrogen Dioxide (NO2) Pesticides Radon (Rn) Indoor Particulate Matter Secondhand Smoke/ Environmental Tobacco Smoke Stoves, Heaters, Fireplaces and Chimneys Volatile Organic Compounds (VOCs)","pyqMatches":[{"year":"2016","no":869,"q":"Which of the following is not a indoor air pollutant?","o":["Carbon monoxide","Nitrous oxide","Radon","Mercury"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5566, 'PSM', 'National Health Programmes', 'Easy', 'Preventive_&_Social_Medicine', 177, '{"id":5566,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":177,"q":"Which agency monitors air quality in India ?","o":["Central pollution control board","Central air quality board","Central public works dept","None"],"a":0,"e":"Ans. is ''a'' i.e., Central pollution control board The National Air Quality Monitoring Programme, sponsored by the Central Pollution Control Board (CPCB) since 1990, has generated database over last 14 years in 10 major Indian cities.","pyqMatches":[{"year":"2012","no":768,"q":"Which agency monitors air quality in India ?","o":["Central pollution control board","Central air quality board","Central public works dept","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5567, 'PSM', 'Environment & Occupational Health', 'Moderate', 'Preventive_&_Social_Medicine', 178, '{"id":5567,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":178,"q":"In winter, water vapours and pollutants comes to lie in the lowermost layer of atmosphere by -","o":["Acid rain","Greenhouse effect","Temperature inversion","None"],"a":2,"e":"Ans. is `c'' i.e., Temperature inversion A temperature inversion is a thin layer of the atmosphere where the normal decrease in temperature with height swithees to the temperature increasing with height. An inversion can lead to pollution such as smog being trapped close to the grand (lower layers of atmosphere). Temperature inversion may occur during the passage of a cold front or result from the invasion of sea air by a cooler onshore breeze. o Overnight radiative cooling of surface air often results in a nocturnal temperature inversion that is dissipated after sunrise by the warming of air near the ground.","pyqMatches":[{"year":"2012","no":874,"q":"In winter, water vapours and pollutants comes to lie in the lowermost layer of atmosphere by","o":["Acid rain","Greenhouse effect","Temperature inversion","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5568, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 179, '{"id":5568,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":179,"q":"The source of endogenous radiation is","o":["Radon","Potassium","Thorium","Uranium"],"a":1,"e":"Ans. is ''b'' i.e.. Potassium o Radiation is part of man''s environment.","pyqMatches":[{"year":"2016","no":870,"q":"The source of endogenous radiation is","o":["Radon","Potassium","Thorium","Uranium"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5569, 'PSM', 'Environment & Occupational Health', 'Easy', 'Preventive_&_Social_Medicine', 180, '{"id":5569,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":180,"q":"The maximum permissible level of occupational exposure to radiation is...per year -","o":["5 rad","2 rad.","10 rad","50 rad"],"a":0,"e":"Ans. is ''a'' i.e., 5 Rad The amount of radiation received from outer space and background radiation has been estimated to be 0.1 rad a year. Apparently, this does not at present constitute a hazard. The additional permissible dose from man made sources should not exceed 5 rad a year.","pyqMatches":[{"year":"2016","no":1733,"q":"The maximum permissible level of occupational exposure to radiation is...per year","o":["5 rad","2 rad.","10 rad","50 rad"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5570, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 181, '{"id":5570,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":181,"q":"Psychrometer Psychrometer is used to measure -","o":["Humidity","Air velocity","Room temperature","Radiant temperature"],"a":0,"e":"Ans. is ''a'' i.e., Humidity Humidity is measured by o Dry and wet Bulb hygrometer o Sling psychrometer o Assmann psychrometer o Air velocity is measured by anemometer. o Radiant temprature is measured by Globe thermometer. o Room temprature is measured by bulb thermometer.","pyqMatches":[{"year":"2013","no":946,"q":"Psychrometer Psychrometer is used to measure","o":["Humidity","Air velocity","Room temperature","Radiant temperature"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5571, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 182, '{"id":5571,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":182,"q":"Not safe disposal but gelid for soil building -","o":["Incineration","Controlled tipping","Composting","None"],"a":2,"e":"Ans. is ''c'' i.e., Composting Composting C''ompostig is a method of combined disposal of refuse and nightsoil or sluge. o It is process of nature whereby orgaic matter breaks down under bacterial action resulting in the formation of relatively stable humus-like material, called the compost which has considerable manurial value for the soil. o Compost contains no or few disease producing organisms and is a good soil builder containing small amounts of the major plant nutrients such as nitrates and phosphates. o There are following two methods of composting. i) Bangalore method (Anaerobic method) ii)Mechanical composting (Aaerobic method).","pyqMatches":[{"year":"2012","no":873,"q":"Not safe disposal but gelid for soil building","o":["Incineration","Controlled tipping","Composting","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5572, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 183, '{"id":5572,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":183,"q":"The heart to the activated sludge process is ?","o":["Primary sedimentation tank","Sludge digester","Aeration tank","Final settling tank"],"a":2,"e":"Ans. is ''c'' i.e., Aeration tank o The heart of the activated sludge process is aeration tank.","pyqMatches":[{"year":"2012","no":864,"q":"The heart to the activated sludge process is ?","o":["Primary sedimentation tank","Sludge digester","Aeration tank","Final settling tank"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5573, 'PSM', 'National Health Programmes', 'Easy', 'Preventive_&_Social_Medicine', 184, '{"id":5573,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":184,"q":"Transovarian transmission of infection occurs in -","o":["Fleas","Ticks","Mosquitoes","b and c"],"a":3,"e":"Ans. is ''b'' i.e., Ticks; ''c'' i.e., Mosquitoes","pyqMatches":[{"year":"2012","no":790,"q":"Transovarian transmission of infection occurs in","o":["Fleas","Ticks","Mosquitoes","b and c"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5574, 'PSM', 'National Health Programmes', 'Easy', 'Preventive_&_Social_Medicine', 185, '{"id":5574,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":185,"q":"Transovarian transmission Is seen in which infection -","o":["Plague","Guinea","Yellow fever","All"],"a":2,"e":"Ans. is ''c'' i.e.. Yellow fever","pyqMatches":[{"year":"2012","no":789,"q":"Transovarian transmission Is seen in which infection","o":["Plague","Guinea","Yellow fever","All"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5575, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 186, '{"id":5575,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":186,"q":"Study of physical, social and cultural history of man is known as?","o":["Social science","Anthropology","Acculturation","Sociology"],"a":1,"e":"Ans. is ''b i.e. Anthropology o Anthropology is study of physical, social and cultural history of man. o Anthropology may be: (i) Physical anthropology: Study of human evolution, racial differences, inheritance of bodily traits, growth and decay of human organisms (ii) Social anthropology: Study of the development and various types of social life. (iii) Cultural anthropology: Study of total way of life of contemporary primitive man. his way of thinking, feeling and action. (iv) Medical anthropology: Deals with the cultural component in the ecology of health and disease.","pyqMatches":[{"year":"2012","no":880,"q":"Study of physical, social and cultural history of man is known as?","o":["Social science","Anthropology","Acculturation","Sociology"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5576, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 187, '{"id":5576,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":187,"q":"Sociology -","o":["Study of human relationship","Study of behavior","Both","None"],"a":2,"e":"Ans. is ''c'' i.e., Both o Sociology deals with the study of human relationships and of human behaviour.","pyqMatches":[{"year":"2012","no":879,"q":"Sociology","o":["Study of human relationship","Study of behavior","Both","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5577, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 188, '{"id":5577,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":188,"q":"Study of person to person inter- relationship in a society - Economics","o":["Economics","Suciology","Psychology","Anthropology"],"a":1,"e":"Ans. is ''b'' i.e., Sociology","pyqMatches":[{"year":"2013","no":957,"q":"Study of person to person inter- relationship in a society - Economics","o":["Economics","Suciology","Psychology","Anthropology"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5578, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 189, '{"id":5578,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":189,"q":"Custom is defined as -","o":["Established pattern of behavior","Prescribed order of cremony","Ban to a particular activity","None"],"a":0,"e":"Ans. is ''a'' i.e., Established pattern of behavior","pyqMatches":[{"year":"2013","no":956,"q":"Custom is defined as","o":["Established pattern of behavior","Prescribed order of cremony","Ban to a particular activity","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5579, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 190, '{"id":5579,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":190,"q":"Chronological age 10yrs, mental age 4yrs. What that person called as?","o":["Idiot","Imbecile","Normal","Genius"],"a":1,"e":"Ans. is ''b'' i.e., Imbecile","pyqMatches":[{"year":"2012","no":883,"q":"Chronological age 10yrs, mental age 4yrs. What that person called as?","o":["Idiot","Imbecile","Normal","Genius"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5580, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 191, '{"id":5580,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":191,"q":"Objectives of National Mental Health programme are all accept -","o":["Promote community participation","Promote application of mental health knowledge","Provides free antipsychotic drugs to all","Provide accessibility of mental health care"],"a":2,"e":"Ans. is ''c'' i.e., Provides free antipsychotic drugs to all National Mental Health Prim-amine (NMIIPI The (io% eminent of India has lauched the National Mental Health Programme in 1982, with the following objectives: a) To ensure availability and accessibility of minimum mental healthcare for all in the foreseeable future, particularly to the most vulnerable and underprivileged section of the population. b) To encourage the application of mental health knowledge in general healthcare and in social development. c) To promote community participation in the mental health service development. o The District Mental Health Programme (DM H P) was launched under NMHP in the year 1996, which was based on ''Bellary Model'' with the following components. a) Early detection and treatment. b) Training of general phvsians and health workers. c) IEC'' : Public awareness generation. d) Monitoring (for simple record keeping). o The NMHP was re-strategized in year 2003 with following components:? 1) Extension of DMHP to 100 districts. 2) Upgradation of psychiatric wing in medical colleges/General hospitals. 3) Modernization of state mental hospitals. 4) IEC 5) Monitoring and evalutation.","pyqMatches":[{"year":"2013","no":985,"q":"Objectives of National Mental Health programme are all accept","o":["Promote community participation","Promote application of mental health knowledge","Provides free antipsychotic drugs to all","Provide accessibility of mental health care"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5581, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 192, '{"id":5581,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":192,"q":"Effect of environment on genes is called?","o":["Positive Eugenics","Negative Eugenics","Euthenics","Enthenics"],"a":2,"e":"Ans. is ''c'' i.e., Euthenics Eugenics Science which aims to improve the genetic endoment of human population. o That is improving the quality of the human species or a human population by genetic manipulation. o Eugenis may be :","pyqMatches":[{"year":"2012","no":887,"q":"Effect of environment on genes is called?","o":["Positive Eugenics","Negative Eugenics","Euthenics","Enthenics"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5582, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 193, '{"id":5582,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":193,"q":"Hardly-weinberg law is related to-","o":["Population genetics","Health economics","Social medicine","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Population genetics Hardly-Weinberg law The hardly-weinherg law states that \"The relative frequencies of each gene allele tends to remain constant from generation to generation\". o Thus, the study of gene frequencies, and the influences which operate to alter the \"gene pool\" and their long term consequences is the central theme in population genetics.","pyqMatches":[{"year":"2012","no":888,"q":"Hardly-weinberg law is related to","o":["Population genetics","Health economics","Social medicine","None of the above"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5583, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 194, '{"id":5583,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":194,"q":"Acculturation is?","o":["Traige","Cultural changes due to socialisation","Attitude","Belief"],"a":1,"e":"Ans. is ''b'' i.e., Cultural changes due to socialisation Acculturation is a process of social, psychological, and cultural change that stems from the balancing of two cultures while adapting to the prevailing culture of the society. Acculturation is a process in which an individual adopts, acquires and adjusts to a new cultural environment.","pyqMatches":[{"year":"2012","no":882,"q":"Acculturation is?","o":["Traige","Cultural changes due to socialisation","Attitude","Belief"],"a":1,"source":"NEET_2012_Paper.pdf"},{"year":"2016","no":879,"q":"Acculturation is?","o":["Traige","Cultural changes due to socialisation","Attitude","Belief"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2012","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5584, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 195, '{"id":5584,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":195,"q":"Amount of waste infectious produced in hospitals?","o":["45%","65%","80%","100%"],"a":0,"e":"Ans. is ''a'' i.e., 45%","pyqMatches":[{"year":"2012","no":891,"q":"Amount of waste infectious produced in hospitals?","o":["45%","65%","80%","100%"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5585, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 196, '{"id":5585,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":196,"q":"Which waste cannot be incinerated -","o":["Anatomic waste","Microbiology waste","Halogenated plastic","Infectious waste"],"a":2,"e":"Ans. is ''c'' i.e., Halogenated plastic","pyqMatches":[{"year":"2013","no":972,"q":"Which waste cannot be incinerated","o":["Anatomic waste","Microbiology waste","Halogenated plastic","Infectious waste"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5586, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 197, '{"id":5586,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":197,"q":"Best for Incineration of infectiouswaste ?","o":["Double - chamber","Single - chamber","Triple - chamber","None"],"a":0,"e":"Ans. is ''a'' i.e., Double-chamber o Three basic kinds of incineration technology are of interest for treatment of healh care wastes : i) Double-chamber pyrolytic incinerators which may be especially designed to burn infectious health care waste. ii) Single-chamber furnaces with static grate, which should be used only if pyrolytic incinerators are not affordable. iii) Rotary kilns operating at high temperatures, capable of causing decomposition of genotoxic substances and heat-resistant chemicals.","pyqMatches":[{"year":"2012","no":892,"q":"Best for Incineration of infectiouswaste ?","o":["Double - chamber","Single - chamber","Triple - chamber","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5587, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 198, '{"id":5587,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":198,"q":"Which is the calamity with most amount of damage -","o":["Flood","Earthquake","Landslides","Volcanoes"],"a":0,"e":"Ans. is ''a'' i.e., Floods","pyqMatches":[{"year":"2013","no":974,"q":"Which is the calamity with most amount of damage","o":["Flood","Earthquake","Landslides","Volcanoes"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5588, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 199, '{"id":5588,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":199,"q":"True about triage -","o":["Yellow-least priority","Red -morbidity","Green-ambulatory","Blue-ambulatory"],"a":2,"e":"Ans. is ''c'' i.e., Green ambulatory","pyqMatches":[{"year":"2012","no":890,"q":"True about triage","o":["Yellow-least priority","Red -morbidity","Green-ambulatory","Blue-ambulatory"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5589, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 200, '{"id":5589,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":200,"q":"High priority in triage is for -","o":["Red color","Yellow color","Green color","Black color"],"a":0,"e":"Ans. is ''a'' i.e., Red colour","pyqMatches":[{"year":"2013","no":971,"q":"High priority in triage is for","o":["Red color","Yellow color","Green color","Black color"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5590, 'PSM', 'Health Management & Services', 'Hard', 'Preventive_&_Social_Medicine', 201, '{"id":5590,"subject":"PSM","chapter":"Health Management & Services","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":201,"q":"Which of the following is the nodal centre for disaster management","o":["PHC","CHC","Control room","None"],"a":2,"e":"Ans. is `C'' i.e., Control room o The control room is the nodal center in terms of disaster management. o The control room plays a vital role in disaster management activation. o It coordinates the flow of information with respect to activities associated with relief operations. During normal times it maintains systematic data-based information of the resources available, important Government and non-Government officials, local bodies and NGOs. During a crisis (disaster) it is expected to function as a center for decision making and to keep constant touch with the affected areas to provide organized relief and rescue operations immediately after occurrence or receipt warning of disaster. o There will be separate control rooms at the block level.","pyqMatches":[{"year":"2013","no":973,"q":"Which of the following is the nodal centre for disaster management","o":["PHC","CHC","Control room","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5591, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 202, '{"id":5591,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":202,"q":"Black color in triage -","o":["Death","Transfer","High priority","Low priority"],"a":0,"e":"Ans. is ''a'' i.e., Death","pyqMatches":[{"year":"2012","no":889,"q":"Black color in triage","o":["Death","Transfer","High priority","Low priority"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5592, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 203, '{"id":5592,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":203,"q":"Propaganda Is defined as -","o":["Forcing of knowledge into mind","Active aquiring of knowledge","Requiring knowledge after thinking","Training of people to use judgment before acting"],"a":0,"e":"Ans. is ''a'' i.e., Forcing of knowledge into mind","pyqMatches":[{"year":"2013","no":975,"q":"Propaganda Is defined as","o":["Forcing of knowledge into mind","Active aquiring of knowledge","Requiring knowledge after thinking","Training of people to use judgment before acting"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5593, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 204, '{"id":5593,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":204,"q":"All are true about panel discussion except ?","o":["Two way discussion","6 to 20 members participates","Chief members initiates","Each one prepares the topic of discussion"],"a":1,"e":"Ans. is ''b'' i.e., 6-20 members participates Panel discussion o It is a two way communication. 4 - 8 persons who are qualified to talk about a topic and discuss a given problem in front of a large group or audience. o The panel comprises a chairman. o The chairman opens the meeting, welcomes the group and introduces the panel speakers. o He indroduces topic briefly and invite the panel speakers to present their point of view. o After the main aspects of subject are explored by panel speakers, the audience is invited to take part. o If members of the panel are unacquainted with this method, they may have a preliminary meeting, prepare the material on the subject and decide upon the method and plan of presentation.","pyqMatches":[{"year":"2012","no":893,"q":"All are true about panel discussion except ?","o":["Two way discussion","6 to 20 members participates","Chief members initiates","Each one prepares the topic of discussion"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5594, 'PSM', 'Health Management & Services', 'Easy', 'Preventive_&_Social_Medicine', 205, '{"id":5594,"subject":"PSM","chapter":"Health Management & Services","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":205,"q":"Multi-purpose worker scheme in India was introduced following the recommendation of ?","o":["Srivastava Committee","Bhore Committee","Kartar Singh Committee","fsludaliar Committee"],"a":2,"e":"Ans. is ''c'' i.e., Kartar Singh committee Health Planning in India The guide lines for national health planning were provided by a number of committees. o These committees were appointed by the Government of India from time to time to review the existing health situation and recommend measures for further action.","pyqMatches":[{"year":"2012","no":909,"q":"Multi-purpose worker scheme in India was introduced following the recommendation of ?","o":["Srivastava Committee","Bhore Committee","Kartar Singh Committee","fsludaliar Committee"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5595, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 206, '{"id":5595,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":206,"q":"Bajaj committee in 1986 proposed?","o":["Multipurpose health worker","Manpower and planning","Rural Health Service","Integrated health services"],"a":1,"e":"Ans. is ''b'' i.e., Manpower and planning","pyqMatches":[{"year":"2012","no":904,"q":"Bajaj committee in 1986 proposed?","o":["Multipurpose health worker","Manpower and planning","Rural Health Service","Integrated health services"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5596, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 207, '{"id":5596,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":207,"q":"Millennium developmental goal for HIV/ AIDS ?","o":["6","3","8","1"],"a":0,"e":"Ans. is `a'' i.e., 6 o Goal 6 is to combat HIV/AIDS; malaria and other diseases.","pyqMatches":[{"year":"2013","no":847,"q":"Millennium developmental goal for HIV/ AIDS ?","o":["6","3","8","1"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5597, 'PSM', 'Health Management & Services', 'Easy', 'Preventive_&_Social_Medicine', 208, '{"id":5597,"subject":"PSM","chapter":"Health Management & Services","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":208,"q":"A trained dal caters for a population of -","o":["1000","2000","3000","4000"],"a":0,"e":"Ans. is ''a'' i.e., 1000 Local dais (Traditional birth attendants) Under Rural Health Scheme, all categories of local dies are trained to improve their knowledge in the elementry concepts of : - i) MCH ii) Sterilization (Small family norm) Training Training is for 30 working days. o They are paid a stipend o/ Rs. 300 during training period. o Training is given for 2 days in a week at PHC, subcentre or MHC centre. o On the remaining four days of the week they accompany the health worker female. o During her training period each dai is required to conduct at least 2 deliveries under the supervision of health worker. The national target is to train one local dai in each village. Note : One village is equivalent to 1000 rural population.","pyqMatches":[{"year":"2012","no":896,"q":"A trained dal caters for a population of","o":["1000","2000","3000","4000"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5598, 'PSM', 'Health Management & Services', 'Easy', 'Preventive_&_Social_Medicine', 209, '{"id":5598,"subject":"PSM","chapter":"Health Management & Services","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":209,"q":"Kit B is given at -","o":["PHC","Subccnter","CHC","FRU level"],"a":1,"e":"Ans. is ''b'' i.e., Subcenter","pyqMatches":[{"year":"2012","no":895,"q":"Kit B is given at","o":["PHC","Subccnter","CHC","FRU level"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5599, 'PSM', 'Health Management & Services', 'Moderate', 'Preventive_&_Social_Medicine', 210, '{"id":5599,"subject":"PSM","chapter":"Health Management & Services","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":210,"q":"All are principles of primary health care except?","o":["Intersectoral coordination","Community participation","Appropriate technology","Decentralised approach"],"a":3,"e":"Ans. is ''d'' i.e., Decentralised approach o There are 4 main principles of primary health care : 1) Equitable distribution 2)Community participation 3)Intersectorial coordination 4) A ppro priate technology","pyqMatches":[{"year":"2015","no":919,"q":"All are principles of primary health care except?","o":["Intersectoral coordination","Community participation","Appropriate technology","Decentralised approach"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5600, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 211, '{"id":5600,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":211,"q":"NVBDCP includes all except?","o":["Malaria","Filarial","Kala azar","Chikungunya"],"a":3,"e":"Ans. is d i.e., Chikungunya o National Vector Borne Disease control programme (NVBDCP) includes malaria, dengue,filaria, JE and kala-azar. Health programmes in India o Since India become indepedent, several measures have been undertaken by National Government to improve the health of the people. o Prominant among these measures are the NATIONAL HEALTH PROGRAMMES which have been launched by the central Government for control/eradication of the communicable diseases, improvement of environmental sanitation, raising the standard of nutrition, control of populattion and improving rural health. National Health Programmes curently working in India : ?","pyqMatches":[{"year":"2013","no":981,"q":"NVBDCP includes all except?","o":["Malaria","Filarial","Kala azar","Chikungunya"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5601, 'PSM', 'National Health Programmes', 'Easy', 'Preventive_&_Social_Medicine', 212, '{"id":5601,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":212,"q":"National Leprosy Eradication Programme was started in -","o":["1949","1955","1973","1983"],"a":3,"e":"Ans. is ''d'' i.e., 1983","pyqMatches":[{"year":"2012","no":907,"q":"National Leprosy Eradication Programme was started in","o":["1949","1955","1973","1983"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5602, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 213, '{"id":5602,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":213,"q":"Revised strategy for NPCB includes all except ?","o":["Fixed facility surgery","IOL implantation for cataract","Mobile surgical camps","Uniform distribution"],"a":2,"e":"Ans. is ''c'' i.e. Mobile surgical camps NATIONAL PROGRAMME FOR CONTROL OF BLINDNESS (NPCB) The national program for Control of Blindness (NPCB) has been re- designated recently as the National Programme for Control of Blindness and Visual Impairment Launched in 1976, It is a 100% centrally sponsored scheme. Its objective is to reduce the prevalence of eye diseases in general, and the prevalence of blindness from 1.40% to 0.3% by 2000 AD. Apex Centre (National Eye Institute) is Dr. Rajendra Prasad Centre for Ophthalmic Sciences (New Delhi, AIIMS). Revised strategies of NPCB a) To make NPCB more comprehensive by strengthening services for other causes of blindness like corneal blindness(requiring transplantation of donated eyes), refractive errors in school-going children, improving follow-up services of cataract operated persons and treating other causes of blindness like glaucoma; To shift from the eye camp approach to a fixed facility surgical approach and from conventional surgery to IOL implantation for better quality of post- operative vision in operated patients. b) To expand the World Bank project activities like construction of dedicated eye operation theatres, eye wards at the district level, training of eye surgeons in modern cataract surgery and other eye surgeries and supply of ophthalmic equipment, etc. to the whole country. c) To strengthen the participation of Voluntary Organizations in the program and to earmark geographic areas to NGOs and Government Hospitals to avoid duplication of effort and improve the performance of Government Units like Medical Colleges, District Hospitals, Sub Divisional Hospitals, Community Health Centres, Primary Health Centres. d) To enhance the coverage of eye care services in tribal and other under-served areas (uniform distribution) through the identification of bilateral blind patients, preparation of village-wise blind register and giving preference to bilateral blind patients for cataract surgery.","pyqMatches":[{"year":"2014","no":1058,"q":"Revised strategy for NPCB includes all except ?","o":["Fixed facility surgery","IOL implantation for cataract","Mobile surgical camps","Uniform distribution"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5603, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 214, '{"id":5603,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":214,"q":"Under RCH programme, intervention done in selected districts -","o":["Immunization","Treatment of STD","ORS therapy","Vitamin A supplementation"],"a":1,"e":"Ans. is ''b'' i.e.. Treatment of STD o Interventions in all Districts o Child survival interventions i.e., immunization, vitamin A (to prevent blindness), oral rehydration therapy and prevention of deaths due to pneumonia. Safe motherhood interventions e.g., antenatal check up, immunization for tetanus, safe delivery, anaemia control programme. Implementation of Target Free Approach High quality training at all levels IEC activities. Specially designed RCH package for urban slums and tribal areas. District sub-projects under local capacity enhancement. RTI/STD clinics at District Hospitals (where not available). Facility for safe abortions at PHCs by providing equipment, contractual doctors etc. Enhanced community participation through Panchayats, Women''s Groups and NGOs. Adolescent health and reproductive hygiene. o jnten.ent ions in selected States/Distts. a Screening and treatment of RTI/STD at sub-divisional level. Emergency obstetric care at selected FRUs by providing drugs. Essential obstetric care by providing drugs and PHN/Staff Nurse at PHCs. Additional ANM at sub-centres in the weak districts for ensuring MCH care. Improved delivery services and emergency care by providing equipment kits. IUD insertions and ANM kits at sub-centres. Facility of referral transport for pregnant women during emergency to the nearest referral centre through Panchayat in weak districts. a Enhanced community participation through Panchayats, Women''s Groups and NGOs. u Adolescent health and reproductive hygiene. o Interventions in selected States/Distts. Screening and treatment of RTI/STD at sub-divisional level. Emergency obstetric care at selected FRUs by providing drugs. Essential obstetric care by providing drugs and PHN/Staff Nurse at PHCs. Additional ANM at sub-centres in the weak districts for ensuring MCH care. Improved delivery services and emergency care by providing equipment kits, IUD insertions and ANM kits at sub-centres. Facility of referral transport for pregnant women during emergency to the nearest referral centre through Panchayat in weak districts. Enhanced community participation through Panchayats, Women''s Groups and NGOs. Adolescent health and reproductive hygiene. o Interventions in selected States/Distts. Screening and treatment of RTI/STD at sub-divisional level. Emergency obstetric care at selected FRUs by providing drugs. Essential obstetric care by providing drugs and PHN/Staff Nurse at PHCs. Additional ANM at sub-centres in the weak districts for ensuring MCH care. Improved delivery services and emergency care by providing equipment kits, IUD insertions and ANM kits at sub-centres. Facility of referral transport for pregnant women during emergency to the nearest referral centre through Panchayat in weak districts.","pyqMatches":[{"year":"2012","no":905,"q":"Under RCH programme, intervention done in selected districts","o":["Immunization","Treatment of STD","ORS therapy","Vitamin A supplementation"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5604, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 215, '{"id":5604,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":215,"q":"IMNCI target group -","o":["Upto 5yrs","Upto 10 yrs","Upto 15 yrs","Upto 20 yrs"],"a":0,"e":"Ans. is ''a'' i.e., Upto 5 years","pyqMatches":[{"year":"2012","no":913,"q":"IMNCI target group","o":["Upto 5yrs","Upto 10 yrs","Upto 15 yrs","Upto 20 yrs"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5605, 'PSM', 'Immunization', 'Moderate', 'Preventive_&_Social_Medicine', 216, '{"id":5605,"subject":"PSM","chapter":"Immunization","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":216,"q":"ASHA gets remuneration on all except ?","o":["Institutional delivery","Zero dose of OPV and BCG","Recording birth weight","Birth registration"],"a":1,"e":"Ans. is ''b'' i.e., Zero dose of OPV and BCG","pyqMatches":[{"year":"2015","no":916,"q":"ASHA gets remuneration on all except ?","o":["Institutional delivery","Zero dose of OPV and BCG","Recording birth weight","Birth registration"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5606, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 217, '{"id":5606,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":217,"q":"Indira Gandhi Matritva Sahyog Yojana is for ?","o":["> 65 years old","> 50 years old","> 30 years old","> 19 years old"],"a":3,"e":"Ans. is d i.e., > 19 years old o The Indira Gandhi Matritva Sahyog Yojana (IGMSY) is a flagship program of the government of India introduced in 2010 under the Ministry of Women and Child Development. o It is a conditional cash transfer scheme that targets pregnant and lactating women 19 years of age and older who have two children. Its goal is to partly compensate them for wage-loss during childbirth and childcare and to provide conditions for sale delivery and good nutrition and feeding practices.","pyqMatches":[{"year":"2013","no":987,"q":"Indira Gandhi Matritva Sahyog Yojana is for ?","o":["> 65 years old","> 50 years old","> 30 years old","> 19 years old"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5607, 'PSM', 'National Health Programmes', 'Easy', 'Preventive_&_Social_Medicine', 218, '{"id":5607,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":218,"q":"Under National Cancer control Programme, oncology wings were sanctioned to -","o":["Regional Cancer institutes","District Hospitals","Medical college Hospitals","Voluntary Agenecies treating cancer patients"],"a":2,"e":"Ans. is ''c'' i.e., Medical college Hospital o Government hospital and government medical colleges are provided with a grant of Rs 3.00 crores for the development of oncology wing.","pyqMatches":[{"year":"2014","no":1060,"q":"Under National Cancer control Programme, oncology wings were sanctioned to","o":["Regional Cancer institutes","District Hospitals","Medical college Hospitals","Voluntary Agenecies treating cancer patients"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5608, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 219, '{"id":5608,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":219,"q":"What is the BMI for an obese person:","o":["Less than 18.5","18.5-24.9","25-29.9","More than 30"],"a":3,"e":"Ans. D: More than 30 BMI is an estimate of total body fat mass and is probably the most useful scale to define obesity. Obesity has been defined as a BMI >30.0 kg/m2 in the World Health Organization (WHO) classification Body mass index (BMI), calculated from measured weight and height, was classified using the World Health Organization categories of underweight (BMI < 18.5 kg/m2), normal weight (BMI 18.5 to 24.9 kg/m2), pre-obesity (BMI 25 to 29.9 kg/m2) and obesity (BMI 30+ kg/m2)","pyqMatches":[{"year":"2013","no":920,"q":"What is the BMI for an obese person:","o":["Less than 18.5","18.5-24.9","25-29.9","More than 30"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5609, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 220, '{"id":5609,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":220,"q":"True for epidemiological triad","o":["Time, place, person","Agent, host, environment","Disease, prevention, treatment","Agent, man, disease"],"a":1,"e":"Ans: B i.e. Agent, host, environment Epidemiological triad The occurrence and manifestations of any disease, whether communicable or noncommunicable, are determined by the interaction of the following three factors.","pyqMatches":[{"year":"2016","no":789,"q":"True for epidemiological triad","o":["Time, place, person","Agent, host, environment","Disease, prevention, treatment","Agent, man, disease"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5610, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 221, '{"id":5610,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":221,"q":"BCG vaccine is diluted with: September 2005","o":["Normal saline","Distilled water","Dextrose","Colloids"],"a":0,"e":"Ans. A: Normal saline BCG Vaccine (Freeze-Dried) for intracutaneous administration, as prepared by Connaught Laboratories Limited, is made from a culture of an attenuated strain of living bovine tubercle bacillus (Bacillus Calmette-Guerin). It is supplied as a freeze-dried product ready for immediate use following reconstitution with the accompanying diluent, which consists of sterile phosphate-buffered normal saline. Distilled water may cause irritation.","pyqMatches":[{"year":"2013","no":867,"q":"BCG vaccine is diluted with: September 2005","o":["Normal saline","Distilled water","Dextrose","Colloids"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5611, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 222, '{"id":5611,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":222,"q":"Measles is infective for: March 2009","o":["One day before and 4 days after rash","Four days before and five days after rash","Entire incubation period","Only during scabs falling"],"a":1,"e":"Ans. B: Four days before and five days after rash Measles/English Measles is spread through respiration (contact with fluids from an infected person''s nose and mouth, either directly or through aerosol transmission), and is highly contagious — 90% of people without immunity sharing a house with an infected person will catch it. The infection has an average incubation period of 14 days (range 6- 19 days) and Period of communicability in measles is approximately 4 days before and 5 days after the appearance of the rash. Measles is an infection of the respiratory system caused by a virus, specifically a paramyxovirus of the genus Morbillivirus. Morbilliviruses, like other paramyxoviruses, are enveloped, single- stranded, negative-sense RNA viruses. Symptoms include fever, cough, runny nose, red eyes and a generalized, maculopapular, erythematous rash.","pyqMatches":[{"year":"2015","no":812,"q":"Measles is infective for: March 2009","o":["One day before and 4 days after rash","Four days before and five days after rash","Entire incubation period","Only during scabs falling"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5612, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 223, '{"id":5612,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":223,"q":"Denominator for calculating perinatal mortality rate is: September 2009","o":["1000 births","1000 live births","1000 still births","1000 population"],"a":1,"e":"Ans. B: 1000 live births","pyqMatches":[{"year":"2013","no":935,"q":"Denominator for calculating perinatal mortality rate is: September 2009","o":["1000 births","1000 live births","1000 still births","1000 population"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5613, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 224, '{"id":5613,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":224,"q":"Richest source of vitamin D is: September 2003","o":["Fish","Soyabean","Halibut liver oil","Vegetables"],"a":2,"e":"Ans. C i.e. Halibut liver","pyqMatches":[{"year":"2013","no":940,"q":"Richest source of vitamin D is: September 2003","o":["Fish","Soyabean","Halibut liver oil","Vegetables"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5614, 'PSM', 'Nutrition', 'Moderate', 'Preventive_&_Social_Medicine', 225, '{"id":5614,"subject":"PSM","chapter":"Nutrition","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":225,"q":"Differences between human milk and cow milk are all of the following except: September 2005","o":["Cow milk has comparatively more fat","Cow milk has comparatively more protein","Cow milk has comparatively more calcium","Cow milk is iron deficient"],"a":3,"e":"Ans. D: Cow milk is iron deficient Cow milk has comparatively more energy, fat, protein, minerals, iron and calcium Human milk has comparatively more of lactose and vitamin C but is deficient of iron.","pyqMatches":[{"year":"2015","no":893,"q":"Differences between human milk and cow milk are all of the following except: September 2005","o":["Cow milk has comparatively more fat","Cow milk has comparatively more protein","Cow milk has comparatively more calcium","Cow milk is iron deficient"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5615, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 226, '{"id":5615,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":226,"q":"Amount of proteins in human milk (in gms): September 2007","o":["1.1","2.2","3.3","4.4"],"a":0,"e":"Ans. A: 1.1 Each 100 grams of breast milk yields approximately: 65 Kilocalories 88 g water 7.4 g carbohydrates (primarily lactose) 3.4 g fat 1.1 g protein","pyqMatches":[{"year":"2012","no":870,"q":"Amount of proteins in human milk (in gms): September 2007","o":["1.1","2.2","3.3","4.4"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5616, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 227, '{"id":5616,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":227,"q":"Vitamin K is required for: March 2005","o":["Chelation","Transamination","Carboxylation","None of the above"],"a":2,"e":"Ans. C: Carboxylation The function of vitamin K in the cell is to convert glutamate in proteins to gamma-carboxyglutamate (gla). Within the cell, vitamin K undergoes electron reduction to a reduced form of vitamin K (called vitamin K hydroquinone) by the enzyme vitamin K epoxide reductase (or VKOR). Another enzyme then oxidizes vitamin K hydroquinone to allow carboxylation of Glutamate to gamma carboxyglutamate; this enzyme is called the gamma-glutamyl carboxylase or the vitamin K- dependent carboxylase. The carboxylation reaction will only proceed if the carboxylase enzyme is able to oxidize vitamin K hydroquinone to vitamin K epoxide at the same time; the carboxylation and epoxidation reactions are said to be coupled reactions.","pyqMatches":[{"year":"2012","no":361,"q":"Vitamin K is required for: March 2005","o":["Chelation","Transamination","Carboxylation","None of the above"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5617, 'PSM', 'Health Management & Services', 'Moderate', 'Preventive_&_Social_Medicine', 228, '{"id":5617,"subject":"PSM","chapter":"Health Management & Services","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":228,"q":"All are true for ASHA worker EXCEPT: March 2013","o":["Informs about birth and deaths in her village to PHC","Education atleast till 4th class or higher","Local resident","Works per 1000 people of an area"],"a":1,"e":"Ans. B i.e. Education atleast till 4th class or higher ASHA/Accredited Social Health Activists (ASHAs) ASHAs must primarily be female residents of the village that they have been selected to serve, who are likely to remain in that village for the foreseeable future. Married, widowed or divorced women are preferred over women who have yet to marry since Indian cultural norms dictate that upon marriage a woman leaves her village and migrates to that of her husband. ASHAs must have class eight education or higher, preferably be between the ages of 25 and 45, and are selected by and accountable to the gram panchayat (local government).","pyqMatches":[{"year":"2015","no":913,"q":"All are true for ASHA worker EXCEPT: March 2013","o":["Informs about birth and deaths in her village to PHC","Education atleast till 4th class or higher","Local resident","Works per 1000 people of an area"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5618, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 229, '{"id":5618,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":229,"q":"A continuous quantitative data can be depicted with the help of: September 2009","o":["Bar diagram","Pie chart","Histogram","Pictogram"],"a":2,"e":"Ans. C: Histogram Numerical data/quantitative data is data measured or identified on a numerical scale. Numerical data can be analyzed using statistical methods, and results can be displayed using tables, charts, histograms and graphs. For example, a researcher will ask a questions to a participant that include words how often, how many or percentage. The answers from the questions will be numerical. Examples of quantitative data would be: ''there are 643 dots on the ceiling'' or ''there are 735 pieces of bubble gum''. or ''there are 8 planets in the solar system''","pyqMatches":[{"year":"2012","no":750,"q":"A continuous quantitative data can be depicted with the help of: September 2009","o":["Bar diagram","Pie chart","Histogram","Pictogram"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5619, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 230, '{"id":5619,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":230,"q":"Group of 4-8 experts talking in front of a large group of audience is known as: September 2011","o":["Symposium","Workshop","Seminar","Panel discussion"],"a":3,"e":"Ans. D: Panel Discussion In a panel discussion, 4-8 persons who are qualified to talk about the topic sit and discuss a given problem, or the topic, in front of a large group of audience Panel Discussion A panel consists of a small group of four or eight persons, who carry on a guided and informal discussion before an audience as if the panel were meeting alone. The proceedings of the panel should be the same as those described for informal discussion: volunteering of facts, asking questions, stating opinions-all expressed with geniality, with respect for the contributions of other members, without speech making, and without making invidious personal references. This primary function should occupy approximately two-thirds of the allotted time-say forty minutes of an hour''s meeting. The secondary function of the panel is to answer questions from the audience. This discussion method is suitable for use when a relatively large di i ti i t d audience is anticipated. The disadvantage of the method is that it confines most of the discussion to the panel itself. The audience listens and is given a chance to ask questions, but for the most part is passive and receptive. Panel discussions, if well conducted, are usually more interesting to the audience than is the single-speaker forum. They provide sufficiently varied clash of opinion and presentation of facts to give even the quiet members of the audience a feeling of vicarious participation. Quality and tasks of leadership in panel discussion are similar to those described for informal discussion. The leader must in addition take special care to select panel members who can think and speak effectively. He must also be sure that they prepare themselves to discuss the subject. During the discussion by the panel the leader has substantially the same duties as in informal discussion except that he should keep himself more in the background as chairman of the panel. He can do so because each member of the panel is in reality an assistant to the leader and is responsible for specific contributions to the proceedings. When the subject is thrown open to the house, it is the leader''s job to recognize appropriate questions and to reject those not bearing on the subject or involving personalities. Some questions he may answer himself, but usually he should repeat the question and call upon one of the panel to answer it. By preliminary announcement the leader may also tell the audience that they may direct questions at particular members of the panel if they choose. In any case, during the question period the leader needs to maintain strict control.On many occasions this may be the toughest part of his assignment to carry off efficiently and with good humor. While it is customary to confine audience questions to a specific period, some leaders permit questions from the floor at any time. Unless very carefully limited by the leader, this practice may interfere with effective discussion by the panel. Arranging the panel properly will lend effectiveness to this form of g g p p p y discussion.The members should face the audience.It is important that each panel member adjust his chair so that he can see every other member without effort the chairman will also find that the best places for his readiest speakers are at the extreme ends of the table.He should keep the more reticent members close to, him so that he can readily draw them out with direct questions. If the quieter ones sit on the fringes of the panel, the more voluble members are quite likely to monopolize the discussion.","pyqMatches":[{"year":"2015","no":918,"q":"Group of 4-8 experts talking in front of a large group of audience is known as: September 2011","o":["Symposium","Workshop","Seminar","Panel discussion"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5620, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 231, '{"id":5620,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":231,"q":"Preobesity is defined as a BMI of:","o":["18.5-24.9","25-29.9","35-39.9","40-44.9"],"a":1,"e":"Ans. B: 25-29.9 BMI is an estimate of total body fat mass and is probably the most useful scale to define obesity. Obesity has been defined as a BMI >30.0 kg/m2 in the World Health Organization (WHO) classification Body mass index (BMI), calculated from measured weight and height, was classified using the World Health Organization categories of underweight (BMI < 18.5 kg/m2), normal weight (BMI 18.5 to 24.9 kg/m2), pre-obesity (BMI 25 to 29.9 kg/m2) and obesity (BMI 30+ kg/m2)","pyqMatches":[{"year":"2013","no":919,"q":"Preobesity is defined as a BMI of:","o":["18.5-24.9","25-29.9","35-39.9","40-44.9"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5621, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 232, '{"id":5621,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":232,"q":"Which of the following is Amphixenoses ?","o":["Anthrax","Rabies","Trypanosoma cruzi","Salmonella"],"a":2,"e":"Ans. is ''C'' i.e., Trypanosoma cruzi Zoonoses Zoonoses are diseases and infections which are naturally transmitted between vertebrate animal and man. The zoonoses may be classified according to the direction of transmission of disease :","pyqMatches":[{"year":"2014","no":889,"q":"Which of the following is Amphixenoses ?","o":["Anthrax","Rabies","Trypanosoma cruzi","Salmonella"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5622, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 233, '{"id":5622,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":233,"q":"Health index characteristics are all except ?","o":["Validity","Reliability","Affordability","Feasibility"],"a":2,"e":"Ans. is ''c'' i.e., Affordability There has been some confusion over terminology: health indicator as compared to health index (plural: indices or indexes). It has been suggested that in relation to health trends, the term indicator is to be preferred to index, whereas health index is generally considered to be an amalgamation of health indicators (56). Characteristics of indicators Indicators have been given scientific respectability: for example ideal indicators. Should be valid, i.e., they should actually measure what they are supposed to measure; Should be reliable and objective, i.e., the answers should be the same if measured by different people in similar circumstances. Should be sensitive, i.e., they should be sensitive to changes in the situation concerned. Should be specific, i.e., they should reflect changes only in the situation concerned, Should be feasible, i.e., they should have the ability to obtain data needed, and; Should be relevant, i.e., they should contribute to the understanding of the phenomenon of interest.","pyqMatches":[{"year":"2016","no":788,"q":"Health index characteristics are all except ?","o":["Validity","Reliability","Affordability","Feasibility"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5623, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 234, '{"id":5623,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":234,"q":"Screening is a type of ?","o":["Primordial prevention","Secondary prevention","Primary prevention","Tertiary prevention"],"a":1,"e":"Ans. is ''b i.e., Secondary prevention In secondary prevention, action halts the progress of a disease at its incipient stage and prevents complication. Screening tests (e.g. - Pap smear), helps in diagnosis at early stage so that adequate treatment can halt disease progression and prevent complication.","pyqMatches":[{"year":"2014","no":900,"q":"Screening is a type of ?","o":["Primordial prevention","Secondary prevention","Primary prevention","Tertiary prevention"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5624, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 235, '{"id":5624,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":235,"q":"Net reproduction rate is ?","o":["Number of live births per 1000 mid-year population","Number of live birth per 1000 women of child bearing age","Number of daughters a newborn girl will have during life time","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., Number of daughters a newborn girl will have during life time Net reproduction rate Net reproductive rate is defined as \"The no. of daughters a new born girl will bear during her lifetime assuming fixed age specific fertility and mortality rates\" It is the only fertility related statistics which also takes mortality rates into consideration. NRR of one is equivalent to attaining approximately the two child norms. Goal of NRR=1 can be achieved only if atleast 60%* of the eligible couples are effectively practicing family planning.","pyqMatches":[{"year":"2012","no":840,"q":"Net reproduction rate is ?","o":["Number of live births per 1000 mid-year population","Number of live birth per 1000 women of child bearing age","Number of daughters a newborn girl will have during life time","None of the above"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5625, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 236, '{"id":5625,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":236,"q":"Third generation IUCD ?","o":["Mirena","Nova-T","Lippe''s loop","CuT-200"],"a":0,"e":"Ans. is ''a'' i.e., Mirena","pyqMatches":[{"year":"2013","no":584,"q":"Third generation IUCD ?","o":["Mirena","Nova-T","Lippe''s loop","CuT-200"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5626, 'PSM', 'Biostatistics', 'Easy', 'Preventive_&_Social_Medicine', 237, '{"id":5626,"subject":"PSM","chapter":"Biostatistics","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":237,"q":"In positively skewed deviation ?","o":["Mean = Median = Mode","Mean > Medians > Mode","Mode > Median > Mean","None of the above"],"a":1,"e":"Ans. is ''b'' i.e., Mean > Medians > Mode","pyqMatches":[{"year":"2016","no":872,"q":"In positively skewed deviation ?","o":["Mean = Median = Mode","Mean > Medians > Mode","Mode > Median > Mean","None of the above"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5627, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 238, '{"id":5627,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":238,"q":"Influenza pandemic is","o":["Seasonal trend","Cyclical trend","Secular tred","None of the above"],"a":1,"e":"Ans. is ''b'' i.e., Cyclical trend Diseases occurring in cycles spread over a short period show cyclical trends of time distribution. - It is a type of periodic fluctuation. - Examples: -Influenza pandemic: every 7–10 years due to antigenic variations. - Measles: every 2-3 years in the prevaccination era. - Rubella: 6-9 years in the prevaccination era. -Non-infectious conditions can also show cyclical trends.","pyqMatches":[{"year":"2014","no":821,"q":"Influenza pandemic is","o":["Seasonal trend","Cyclical trend","Secular tred","None of the above"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5628, 'PSM', 'Demography & Family Planning', 'Moderate', 'Preventive_&_Social_Medicine', 239, '{"id":5628,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":239,"q":"Not true about population pyramid ?","o":["India has broad base","India has narrow base","India has narrow apex","Developing countries have bulge in the center"],"a":1,"e":"Ans. is ''b'' i.e., India has narrow base In countries with high birth rates as ours, population pyramid is broad based conical (narrow apex) because of high birth rate and tapering of population with increase in age. The pyramid of developing country (e.g. India) has a broad base and a tapering top. In developed countries, the pyramid generally shows a bulge in the middle and has a narrower base (as in figure given in the question).","pyqMatches":[{"year":"2012","no":839,"q":"Not true about population pyramid ?","o":["India has broad base","India has narrow base","India has narrow apex","Developing countries have bulge in the center"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5629, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 240, '{"id":5629,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":240,"q":"In malaria control, insecticide used for insectiside treated bed nets (ITBN)-","o":["Deltamethrin","Malathion","Lindone","Fenitrothion"],"a":0,"e":"Ans. is ''a'' i.e., Deltamethrin Insecticide Treated Bed Nets (ITBN) Programme (esp. deltamethrin) has resulted in significant decline in malaria incidence and API","pyqMatches":[{"year":"2016","no":866,"q":"In malaria control, insecticide used for insectiside treated bed nets (ITBN)","o":["Deltamethrin","Malathion","Lindone","Fenitrothion"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5630, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 241, '{"id":5630,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":241,"q":"Kanawati index is used for ?","o":["Air population","PEM","Obesity definition","Infectivity"],"a":1,"e":"Ans. is ''b'' i.e., PEM Kanawati index is used to classify protein energy malnutrition (PEM).","pyqMatches":[{"year":"2016","no":859,"q":"Kanawati index is used for ?","o":["Air population","PEM","Obesity definition","Infectivity"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5631, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 242, '{"id":5631,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":242,"q":"Gomez classification is based on ?","o":["Weight retardation","Height retardation","Mid arm circumference","Stunting"],"a":0,"e":"Ans. is ''a'' i.e., Weight retardation","pyqMatches":[{"year":"2016","no":858,"q":"Gomez classification is based on ?","o":["Weight retardation","Height retardation","Mid arm circumference","Stunting"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5632, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 243, '{"id":5632,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":243,"q":"Human anatomical wastes are treated/disposed by ?","o":["Autoclaving","Chemical disinfection","Incineration","Microwaving"],"a":2,"e":"Ans. is ''c'' i.e., Incineration Human anatomical wastes such as human tissues, organs, and body parts are classified as Waste Category No. I They are disposed in ''plastic bags'' with a ''yellow color code'' and treated by ''Incineration or deep burial''.","pyqMatches":[{"year":"2014","no":1049,"q":"Human anatomical wastes are treated/disposed by ?","o":["Autoclaving","Chemical disinfection","Incineration","Microwaving"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5633, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 244, '{"id":5633,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":244,"q":"Cytotoxic drugs are treated/disposed by ?","o":["Autoclaving","Chemical disinfection","Incineration","Microwaving"],"a":2,"e":"Ans. is ''c'' i.e., Incineration Cytotoxic drugs are category No. 5 wastes which are destroyed by incineration and disposed by secured landfills.","pyqMatches":[{"year":"2014","no":1051,"q":"Cytotoxic drugs are treated/disposed by ?","o":["Autoclaving","Chemical disinfection","Incineration","Microwaving"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5634, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 245, '{"id":5634,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":245,"q":"In calendar method of contraception, first day of fertile period is?","o":["10th day of shortest menstural cycle","18th day of shortest menstural cycle","10th day of longest menstural cycle","18th day of longest menstural cycle"],"a":0,"e":"Ans. is ''a'' i.e. 10th day of shortest menstural cycle Safe Period (rhythm method) This is also known as the calendar method first described by Ogino. The method is based upon the fact that ovulation occurs from 12 to 16 days before the onset of mensturation. Calculation is as follows : The shortest cycle minus 18 days gives the first day of the fertile period. The longest cycle minus 10 days gives the last day of fertile period. For example, if a woman''s menstural cycle varies from 28-31 days, the fertile period during which she should not have intercourse would be from the 10th day to 21st day of the menstural cycle, counting day one as the first day of the menstural period. Thus, the 1st day of fertile period is 10th day of shortest cycle.","pyqMatches":[{"year":"2014","no":996,"q":"In calendar method of contraception, first day of fertile period is?","o":["10th day of shortest menstural cycle","18th day of shortest menstural cycle","10th day of longest menstural cycle","18th day of longest menstural cycle"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5635, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 246, '{"id":5635,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":246,"q":"Most common type of polio is ?","o":["Non-paralytic polio","Paralytic polio","Abortive illness","Inapparent infection"],"a":3,"e":"Ans. is `d'' i.e., Inapparent infection","pyqMatches":[{"year":"2014","no":969,"q":"Most common type of polio is ?","o":["Non-paralytic polio","Paralytic polio","Abortive illness","Inapparent infection"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5636, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 247, '{"id":5636,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":247,"q":"Mortality of rabies is ?","o":["25%","50%","75%","100%"],"a":3,"e":"Ans. is ''d'' i.e., 100% Rabies Rabies is primarily a zoonotic disease of warm-blooded animals, particularly carnivorous such as dogs, Cats, Jackals and wolves.","pyqMatches":[{"year":"2014","no":970,"q":"Mortality of rabies is ?","o":["25%","50%","75%","100%"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5637, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 248, '{"id":5637,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":248,"q":"Kala-azar is transmitted by ?","o":["Reduvid bug","Sandfly","Tsetse fly","Mosquito"],"a":1,"e":"Ans. is ''b'' i.e., Sandfly","pyqMatches":[{"year":"2014","no":1043,"q":"Kala-azar is transmitted by ?","o":["Reduvid bug","Sandfly","Tsetse fly","Mosquito"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5638, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 249, '{"id":5638,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":249,"q":"Fluoride helps in ?","o":["Vision","Dentition","Myelination","Joint stability"],"a":1,"e":"Ans. is ''b'' i.e., Dentition","pyqMatches":[{"year":"2014","no":1015,"q":"Fluoride helps in ?","o":["Vision","Dentition","Myelination","Joint stability"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5639, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 250, '{"id":5639,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":250,"q":"Cholera vaccination is indicated ?","o":["To control epidemics","For travellers","In endemic areas","In Neonates"],"a":2,"e":"Ans. is ''c'' i.e., In endemic areas Cholera vaccination should be considered in areas where cholera is endemic. However, it should always be done in conjunction with implementation of safe water, sanitation and hygiene promotion programme. In resource poor areas, vaccination should be targeted at children aged 2 years. Cholera vaccine has not been recommended in outbreak/epidemic settings or complex humanitarian emergencies because of the logistical challanges of administering 2-dose vaccine, and concern that long-scale vaccination would divert limited resources from higher priority measures. As it does not prevent epidemic cholera transmission, it is not recommended for general population. Cholera transmission is not recommended for travelers, as counseling about risk avoidance is more cost effective than vaccination.","pyqMatches":[{"year":"2014","no":975,"q":"Cholera vaccination is indicated ?","o":["To control epidemics","For travellers","In endemic areas","In Neonates"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5640, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 251, '{"id":5640,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":251,"q":"Screening is not recommended if ?","o":["Prevalence of disease is high","Life expectancy can be prolonged by early diagnosis","Diagnostic test should be available","Diseases with no latent period"],"a":3,"e":"Ans. is ''d'' i.e., Disease with no latent period The disease to be screened should fulfil the following criteria before it is considered suitable for screening:?","pyqMatches":[{"year":"2014","no":937,"q":"Screening is not recommended if ?","o":["Prevalence of disease is high","Life expectancy can be prolonged by early diagnosis","Diagnostic test should be available","Diseases with no latent period"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5641, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 252, '{"id":5641,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":252,"q":"To determine the endemicity of hepatitis B, what should be measured ?","o":["HBsAg","HBcAg","HBeAg","Anti-HBeAg"],"a":0,"e":"Ans. is ''a'' i.e., HBsAg HBsAg testing is widely used as a marker of HBV infection in epidemiological surveys. Serological markers for HBV Serological markers for HBV infection are :? HBs Ag (surface antigen or Australia antigen) : It is the first marker which appears in the serum. It is the epidemiological marker for HBV infection. HBc Ag (core antigen) : It is not demonstrable in serum because it is enclosed by HBsAg coat. HBe Ag (envelope antigen) : It is marker of active replication and high infectivity. It is qualitative marker of replication. HBs Ag carrier mothers who are HBe Ag positive almost invariably (> 90%) transmit hepatitis B infection to their offspring, where as HBs Ag carrier mothers with anti HBe rarely (10 to 15%) infect their offspring. Anti-HBc Ag : It is the first antibody appears in serum. IgM anti-HBc Ag is a marker of acute or recent infection. IgG anti-HBc Ag indicates remote infection. Anti-HBs Ag : It is protective antibody. It is the only serological marker present after vaccination. After an infection, its presence indicates recovery and end of period of communicability. Anti-HBe Ag : Its presence indicate stopage of replication and low infectivity. HBV DNA : It is quantitative marker of HBV replication.","pyqMatches":[{"year":"2014","no":977,"q":"To determine the endemicity of hepatitis B, what should be measured ?","o":["HBsAg","HBcAg","HBeAg","Anti-HBeAg"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5642, 'PSM', 'Epidemiology', 'Moderate', 'Preventive_&_Social_Medicine', 253, '{"id":5642,"subject":"PSM","chapter":"Epidemiology","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":253,"q":"An epidemiologist visits a village and wants to collect data for recent parasitic activity. What should be measure ?","o":["Spleen rate","Infant parasite rate","Slide positivity rate","Slide falciparum rate"],"a":1,"e":"Ans. is ''b'' i.e., Infant parasite rate MEASUREMENT OF MALARIA In the pre-eradication era, the magnitude of the malaria problem in a country used to be determined mostly from the reports of the clinically diagnosed malaria cases and the classical malariometric measures, e.g., spleen rate, parasite rate etc. On the other hand, during eradication era, the microscopic diagnosis of malaria cases became the main method of diagnosis and the parameters used are mostly parasitological in nature e.g., API, ABER, SPR and SFR. Measurements of malaria in the pre eradication era a) Spleen rate: Defined as the percentage of children between 2 & 10 years of age showing enlargement of spleen. Spleen rate is widely used for measuring the endemicity of malaria in a community. b) Av. enlarged spleen : A refinement of spleen rate , denoting the average size of spleen. c) Parasite rate : Defined as on the percentage of children between the ages of 2 & 10 yrs showing malarial parsites in their blood films. d) Parasite density index : Average degree of parasitimia e) Infant parasite rate Percentage of infants showing malarial parasites in their blood films. It is the most sensitive index of recent transmission of malaria in a locality. If the infant parasite rate is zero for three consecutive years in a locality, it is regarded as absence of malaria transmission even though, the Anopheline vectors responsible for previous transmissions may remain. Eradication Era a) Annual Parasite Incidence (API)* = (Confirmed cases during one year / population under surveillance) x 1000 b) Annual Blood Examination Rate = (No. of slides examined/population) x 100 ABER is an index of operational efficiency. In the modified plan of operation, the minimum prescribed is 10 percent of the population in a year c) Annual falciparum index d) Slide positivity rate Slide positivity rate is the percentage of slides found positive for malarial parasite, irrespective of the type of species. Slide falciparum rate It is the percentage of slides positive for P. falciparum.","pyqMatches":[{"year":"2014","no":978,"q":"An epidemiologist visits a village and wants to collect data for recent parasitic activity. What should be measure ?","o":["Spleen rate","Infant parasite rate","Slide positivity rate","Slide falciparum rate"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5643, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 254, '{"id":5643,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":254,"q":"Recommended daily dietary requirment of folate (folic acid) in children ?","o":["80-120 μg","200 μg","400 μg","600 μg"],"a":0,"e":"Ans. is ''a'' i.e., 80-120 μg Recommended daily allowances of folic acid are:- a. Healthy adults → 200 micro gm.(mcg) b. Pregnancy → 500 mcg c. Lactation → 300 mcg d. Children → 80-120 mcg","pyqMatches":[{"year":"2014","no":1019,"q":"Recommended daily dietary requirment of folate (folic acid) in children ?","o":["80-120 μg","200 μg","400 μg","600 μg"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5644, 'PSM', 'Maternal & Child Health', 'Moderate', 'Preventive_&_Social_Medicine', 255, '{"id":5644,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":255,"q":"Minimum number of ANC visits required as per 2010 MOHFW (Ministry of Health and Family Welfare) guidelines ?","o":["1","2","3","4"],"a":3,"e":"Ans. is ''d'' i.e., 4 Now, at least 4 antenatal visits, during pregnancy, are recommended.","pyqMatches":[{"year":"2014","no":1003,"q":"Minimum number of ANC visits required as per 2010 MOHFW (Ministry of Health and Family Welfare) guidelines ?","o":["1","2","3","4"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5645, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 256, '{"id":5645,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":256,"q":"WHO defines adolescent age between ?","o":["10-19 years of age","10-14 years of age","10-25 years of age","9-14 years of age"],"a":0,"e":"Ans. is ''a'' i.e., 10 - 19 Years of age","pyqMatches":[{"year":"2014","no":1013,"q":"WHO defines adolescent age between ?","o":["10-19 years of age","10-14 years of age","10-25 years of age","9-14 years of age"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5646, 'PSM', 'Communicable Diseases', 'Moderate', 'Preventive_&_Social_Medicine', 257, '{"id":5646,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":257,"q":"All are true about DOTS, except ?","o":["Short course of chemotherapy","Drugs are given free of cost","Supervised drugs intake in intensive phase","Daily treatment is recommended"],"a":3,"e":"Ans. is ''d'' i.e., Daily treatment is recommended Directly observed treatment short course (DOTS) In the Revised National Tuberculosis Control Programme (RNTCP), patients are provided short course chemotherapy as DOTS. All patients are provided short-course chemotherapy free of charge. During the intensive phase of treatment a health worker watches as the patient swallows the drug in his presence. o During continuation phase, the patient is issued medicine for one week in a multiblister combipack of which the first dose is swallowed by the patient in the presence of health worker. The consumption of medicine in the continuation phase is also checked by return of empty multiblister combipack when the patient comes to collect medicine for the next week. In this programme, alternate day treatment is given. Under RNTCP, active case finding is no longer pursued. Case finding is passive. Patients presenting themselves with symptoms suspicious of tuberculosis are treated with DOTS therapy. The colour of boxes (containing the drugs for full course of treatment) is according to the category of regimen? i. Category I patients → Red i. Category II patients → Blue i. Category III patients → Green","pyqMatches":[{"year":"2014","no":950,"q":"All are true about DOTS, except ?","o":["Short course of chemotherapy","Drugs are given free of cost","Supervised drugs intake in intensive phase","Daily treatment is recommended"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5647, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 258, '{"id":5647,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":258,"q":"India causing maximum death ?","o":["Drowning","Road traffic accident","Burns","Poisoning"],"a":1,"e":"Ans. is ''b'' i.e., Road traffic accident Among the accidental deaths, maximum deaths are caused by traffic accidents, followed by drowning (2nd m.c. cause) and poisoning (3rd m.c. cause).","pyqMatches":[{"year":"2014","no":893,"q":"India causing maximum death ?","o":["Drowning","Road traffic accident","Burns","Poisoning"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5648, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 259, '{"id":5648,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":259,"q":"Hepatitis A vaccine available ?","o":["Live attenuated","Killed (Inactivated)","Both live and inactivated","Subunit vaccine"],"a":2,"e":"Ans. is ''c'' i.e., Both live and inactivated Two types of hepatitis A vaccines are used :-","pyqMatches":[{"year":"2014","no":912,"q":"Hepatitis A vaccine available ?","o":["Live attenuated","Killed (Inactivated)","Both live and inactivated","Subunit vaccine"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5649, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 260, '{"id":5649,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":260,"q":"Extra energy, needed per day during pregnancy?","o":["150 Kcal","200 Kcal","300 Kcal","350 Kcal"],"a":3,"e":"Ans. is ''d'' i.e., 350 Kcal","pyqMatches":[{"year":"2014","no":1020,"q":"Extra energy, needed per day during pregnancy?","o":["150 Kcal","200 Kcal","300 Kcal","350 Kcal"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5650, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 261, '{"id":5650,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":261,"q":"Vagabond disease is transmitted by ?","o":["Louse","Mite","Tick","Black Fly"],"a":0,"e":"Ans. is ''a'' i.e., Louse Vagabond''s disease is pediculosis corporis, caused by body louse.","pyqMatches":[{"year":"2012","no":875,"q":"Vagabond disease is transmitted by ?","o":["Louse","Mite","Tick","Black Fly"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":1045,"q":"Vagabond disease is transmitted by ?","o":["Louse","Mite","Tick","Black Fly"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5651, 'PSM', 'National Health Programmes', 'Easy', 'Preventive_&_Social_Medicine', 262, '{"id":5651,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":262,"q":"Recommended content of Iodine in salt at production level ?","o":["10 ppm","15 ppm","20 ppm","30 ppm"],"a":3,"e":"Ans. is ''d'' i.e., 30 ppm Goitre control There are following essential components of national goitre control programme.","pyqMatches":[{"year":"2014","no":1021,"q":"Recommended content of Iodine in salt at production level ?","o":["10 ppm","15 ppm","20 ppm","30 ppm"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5652, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 263, '{"id":5652,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":263,"q":"False about transmission of Rubella ?","o":["Droplet infection","Vertical transmission","Infection in early pregnancy causes milder disease","Fetus affected in late pregnancy may have only deafness"],"a":2,"e":"Ans. is ''c'' i.e., Infection in early pregnancy causes milder disease","pyqMatches":[{"year":"2014","no":980,"q":"False about transmission of Rubella ?","o":["Droplet infection","Vertical transmission","Infection in early pregnancy causes milder disease","Fetus affected in late pregnancy may have only deafness"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5653, 'PSM', 'Concept of Health & Disease', 'Hard', 'Preventive_&_Social_Medicine', 264, '{"id":5653,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":264,"q":"Interval between primary and secondary cases ?","o":["Latent period","Communicable period","Serial interval","Generation time"],"a":2,"e":"Ans. is ''c'' i.e., Serial interval Latent period, serial interval and generation time, all are approximate measure of incubation period, i.e., these period can give some idea about incubation period. Latent period The period from disease initiation to disease detection. It is used in non-infectious disease as the equivalent of incubation period in infectious disease. Serial interval The gap time between onset of primary case and secondary case. By collecting information about a whole series of such onset, we get a distribution of secondary cases from which we can guess the incubation period. Generation time Interval between receipt of infecton by host and maximal infectivity of the host. Generation time is roughly equal to the incubation period. About option ''b'' Communicable period The time during which an infectious agent may be transferred directly or indirectly from an infected person to another person. The period of communicability has no relation with incubation period, it merely reflects the duration when the infectious agent may be transferred. This may occur during incubation period, during actual illness or during convalsescence. Generally communicable diseaes are not communicable in incubation period except - measles, Chicken pox, Pertussis hepatitis A, i.e., these diseases are communicable during their late incubation period.","pyqMatches":[{"year":"2014","no":915,"q":"Interval between primary and secondary cases ?","o":["Latent period","Communicable period","Serial interval","Generation time"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5654, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 265, '{"id":5654,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":265,"q":"Best way to dispose e-waste is?","o":["Burning","Incineration","In a landfill","Recycling"],"a":3,"e":"Ans. is ''d'' i.e., Recycling E-Waste E-waste is a popular, informal name for electronic products nearing the end of their \"useful life. \"E-wastes are considered dangerous, as certain components of some electronics products contain materials that are hazardous, depending on their condition and density. The hazardous content of these materials pose a threat to human health and environment. Discarded computers, television, VCRs, stereos, copiers, fax machines, electric lamps, cell phones, audio equiopment and batteries if improperly disposed can leach lead and other substances into soil and groundwater. Many of these products can be reused, refurbished, or recycled, or recyled in an environmentally sound manner so that they are less harmful to the ecosystem. Managment of E-Waste In industries management of e-waste should begin at the point of generation. This can be done by waste minimization techniques and by sustainable product design. Waste minimization in industries involves adopting:","pyqMatches":[{"year":"2014","no":1054,"q":"Best way to dispose e-waste is?","o":["Burning","Incineration","In a landfill","Recycling"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5655, 'PSM', 'National Health Programmes', 'Easy', 'Preventive_&_Social_Medicine', 266, '{"id":5655,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":266,"q":"Vector for transmission of sleeping sickness ?","o":["Sandfly","Black fly","Tse-tse fly","Hard tick"],"a":2,"e":"Ans. is ''c'' i.e., Tse-tse fly","pyqMatches":[{"year":"2014","no":1044,"q":"Vector for transmission of sleeping sickness ?","o":["Sandfly","Black fly","Tse-tse fly","Hard tick"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5656, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 267, '{"id":5656,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":267,"q":"Definition of relapse in TB ?","o":["A patient who returns sputum positive after leaving treatment for at least 2 months.","A pateint who returns sputum positive which was cured by previous treatment","A patient who remains sputum positive after 5 months of treatment","None of the above"],"a":1,"e":"Ans. is ''b'' i.e., A pateint who returns sputum postive which was curved by previous treatment Some definitions of tuberculosis cases and treatment Case of tuberculosis : A patient in whom tuberculosis has been confirmed by bacteriology or diagnosed by a clinician. Sputum smear examination - Laboratory technique to screen sputum for tuberculosis, where acid fast bacilli (AFB) are stained red by the Ziehl Neelsen method, and then identified and counted. using microscopy. Smear positive tuberculosis - At least one initial sputum smears positive for AFB or one AFB positive. Smear negative tuberculosis - At least two negative smears, but tuberculosis suggestive symptoms and X-ray abnormalities or positive culture. Adherence - Person takes appropriate drug regimen for required time (also known as compliance). New case - A patient with sputum positive pulmonary tuberculosis who has never had treatment for tuberculosis or has taken anti - tuberculosis drugs for less than 4 weeks. Relapse - A patient who returns smear positive having previously been treated for tuberculosis and declared cured after the completion of his treatment. Failure case - A patient who was initially smear positive, who began treatment and who remained or became mear positive again at five months or later during the course of treatment. Return after default - A patient who returns sputum smear positive, after having left treatment for at least two months. Transfer in - A patient recorded in another administrative area register and transferred into another area to continue treatment (treatment results should be reported to the district where the patient was initially registered). Transfer out - A patient who has been transferred to another area register and treatment results are not known. Cured - Initially smear positive patient who completed treatment and had negative smear result on at least two occasions (one at treatment completion). Treatment completed - Initially smear negative patient who received full course of treatment, or smear positive who completed treatment, with negative smear at the end of initial phase, but no or only one negative smear during continuation and none at treatment end. Cohort - A group of patients in whom TB has been diagnosed, and who were registered for treatment during a specified time period (e.g. the cohort of new smear-positive cases registered in the calender year 2003). This group forms the denominator for calculating treatment outcomes. The sum of the treatment outcomes, plus any case for which no outcome is recorded (eg. still on treatment) should equal the number of cases registered. Case detection rate : - The case detection rate is calculated as the number of notification of new and relapse cases in a year divided by the estimated incidence of such cases in the same year.","pyqMatches":[{"year":"2014","no":956,"q":"Definition of relapse in TB ?","o":["A patient who returns sputum positive after leaving treatment for at least 2 months.","A pateint who returns sputum positive which was cured by previous treatment","A patient who remains sputum positive after 5 months of treatment","None of the above"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5657, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 268, '{"id":5657,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":268,"q":"According to DOTS-PLUS guidelines 2013 treatment of multidrug resistance TB includes all except ?","o":["Total duration 24-27 months","Intensive phase - 6 drugs","Continutation phase - 2 drugs","Intensive phase 6-9 months"],"a":2,"e":"Ans. is ''c'' i.e., Continutation phase-2 drgus Treatment of multidrug resistance (MDR) TB MDR-TB is defined as resistance to at least both INH and rifampicin. Previously it was classified as Category IV under DOTS (DOTS- PLUS). The treatment is given in two phases, the intestive phase (IP) and the continuation phase (CP). The total duration of treatment for regimen for MDR-TB is 24-27 months, depending on the IP duration. o Treatment regimen comprises :- i. Intensive phase (6-9 months) : Six drugs : Kanamycin (Km), levofloxacin (Lvx), ethionamide (Eto), pyrazinamide (Z), ethambutol (E), and cycloserine (Cs). i. Continuation phase (18 months) : Four drugs : Levofloxaxcin, ethionamide, ethambutol and cycloserine. i. Total duration of treatment is 24-27 months. Treatment of extensive drug resistance (XDR) TB XDR-TB is defined as resistance to any fluoroquinolone and at least one of the following three second-line drugs (capreomycin, kanamycin, amikacin), in addition to multidrug resistance. The Regimen for XDR-TB would be of 24-30 months duration, with 6-12 months Intensive Phase (IP) and 18 months Continuation Phase (CP). Regimen is :- i. Intensive phase (6-12 months) : Seven drugs : Capreomycin, PAS, moxifloxacin, high dose INH, clofazimine, Linezolid, amoxyclay. i. Continuation phase (18 months) : Six drugs : PAS, moxifloxacin, high dose INH, clofazimine, linezolid, amoxyclay.","pyqMatches":[{"year":"2014","no":953,"q":"According to DOTS-PLUS guidelines 2013 treatment of multidrug resistance TB includes all except ?","o":["Total duration 24-27 months","Intensive phase - 6 drugs","Continutation phase - 2 drugs","Intensive phase 6-9 months"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5658, 'PSM', 'Communicable Diseases', 'Moderate', 'Preventive_&_Social_Medicine', 269, '{"id":5658,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":269,"q":"Notifiable diseases to WHO are all except ?","o":["Cholera","Plague","Yellow fever","Tuberculosis"],"a":3,"e":"Ans. is ''d'' i.e., Tuberculosis","pyqMatches":[{"year":"2014","no":908,"q":"Notifiable diseases to WHO are all except ?","o":["Cholera","Plague","Yellow fever","Tuberculosis"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5659, 'PSM', 'Environment & Occupational Health', 'Easy', 'Preventive_&_Social_Medicine', 270, '{"id":5659,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":270,"q":"Continuous scrutiny of health related factors is called ?","o":["Isolation","Surveillancec","Monitoring","Quarntine"],"a":1,"e":"Ans. is ''b'' i.e., Surveillance Monitoring Monitoring is the performance and analysis of routine measurements aimed at detecting changes in the environment or health status of population, e.g. monitoring of air pollution, water quality, and growth & nutritional status. Surveillance Surveillance is the continuous scrutiny of the factors that determine the occurrence and distribution of disease and other conditions of ill health. In simple words \"surveillance is systemic ongoing collection, collation and analysis of data and the timely dissemination of information to those who need to know so that action can be taken\". According to above definition, monitoring becomes one specific and essential part of the broader concept embraced by surveillance. Following example will help to differentiate these two ? In tobacco control - Surveillance includes collection of data about prevalence of tobacco use, its health and enconomic consequences, its socio-cultural determinats and tobacco control policy responses and tobacco industry activities. By collecting all these information effective tobacco control interventions can be taken. Monitoring will continously oversight the activities of this tobacco control interventions, to ensure that they are proceeding according to plan. It keeps track of achievement, resources supply and utilization, staff movement, etc, so that if anything goes wrong, immediate corrective measure can be taken. So,","pyqMatches":[{"year":"2014","no":918,"q":"Continuous scrutiny of health related factors is called ?","o":["Isolation","Surveillancec","Monitoring","Quarntine"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5660, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 271, '{"id":5660,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":271,"q":"Natural history of disease is studied with ?","o":["Longitudinal studies","Cross-sectional studies","Both","None"],"a":0,"e":"Ans. is ''a'' i.e., Longitudinal studies Longitudinal studies In this type of study, observations are repeated in the same population over a prolonged period using follow up examinations. They are useful to","pyqMatches":[{"year":"2012","no":776,"q":"Natural history of disease is studied with ?","o":["Longitudinal studies","Cross-sectional studies","Both","None"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":925,"q":"Natural history of disease is studied with ?","o":["Longitudinal studies","Cross-sectional studies","Both","None"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5661, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 272, '{"id":5661,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":272,"q":"India belongs to which stage of the demographic cycle ?","o":["Slow stationary","High stationary","Early stationary","Late expanding"],"a":3,"e":"Ans. is ''d'' i.e., Late expanding Demographic process Fertility Mortality Marriage Migration Social Mobility Demographic cycle Stage 1 : High stationary High birth rate and high death rate render the population stationary. Narrow demographic gap. Stage 2 : Early expanding Death rate declines and birth rate remains unchanged The demographic gap starts increasing and then becomes maximum Stage 3 : Late expanding Death rate decline further and birth rate falls India is in this stage, currently The demographic gap starts declining Stage 4 : Low stationary Low birth rate and low death rate renders the population stationary Narrow demographic gap Stage 5 : Declining Population begins to decline as birth rate is lower than death rate The demographic gap is negative","pyqMatches":[{"year":"2014","no":1004,"q":"India belongs to which stage of the demographic cycle ?","o":["Slow stationary","High stationary","Early stationary","Late expanding"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5662, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 273, '{"id":5662,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":273,"q":"RCH-II major strategies are all except ?","o":["Essential obstetric care","Emergency obstetric care","Family planning","Strengthening referral system"],"a":2,"e":"Ans. is ''c'' i.e., Family planning 4 components of RCH programme are (i) Family planning; (ii) Child survival and safe motherhood; (iii) Client approach to health care, and (iv) Prevention of RTI/STD/AIDS. Reproductive and Child health Programme RCH programme was launched in October 1997. Reproductive and child health approach has been defined as : -","pyqMatches":[{"year":"2014","no":1061,"q":"RCH-II major strategies are all except ?","o":["Essential obstetric care","Emergency obstetric care","Family planning","Strengthening referral system"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5663, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 274, '{"id":5663,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":274,"q":"Disability adjusted life year (DALY) is a measure of ?","o":["Life expectancy","Effectiveness of treatment","Quality of life","Human development"],"a":1,"e":"Ans. is ''b'' i.e., Effectiveness of treatment Disability - adjusted life year (DALY) DALY is a measure of :- The burden of disease in a defined population The effectiveness of interventions It expresses years lost to premature death and years lived with disability adjusted for the severity of the disability. That means, DALY measures both mortality and disability together (in contrast to sullivan''s index which is related to disability only). One DALY is one lost year of healthy life. DALY combines following : - Years of lost life (YLL). Years lost to disability (YLD) DALY = YLL + YLD Japanese life expectancy statistics are used as a standard for measuring premature death, as Japanese have the longest life expectancy. Health - adjusted life expectancy (HALE) HALE is the indicator used to measure healthy life expectancy. HALE is based on the life expectancy at birth but includes an adjustment for time spent in poor health. It is the equivalent number of years in full health that a newborn can expect to live based on current rates of ill health and mortality.","pyqMatches":[{"year":"2014","no":897,"q":"Disability adjusted life year (DALY) is a measure of ?","o":["Life expectancy","Effectiveness of treatment","Quality of life","Human development"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5664, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 275, '{"id":5664,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":275,"q":"Which of the following is used to represent continuous (quantitative) data ?","o":["Bar diagram","Pie chart","Histogram","Map diagram"],"a":2,"e":"Ans. is `c'' i.e., Histogram","pyqMatches":[{"year":"2014","no":1074,"q":"Which of the following is used to represent continuous (quantitative) data ?","o":["Bar diagram","Pie chart","Histogram","Map diagram"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5665, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 276, '{"id":5665,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":276,"q":"Amino acid deficient in both Wheat and Maize ?","o":["Lysine","Threonine","Tryptophan","Methionine"],"a":0,"e":"Ans. is ''a'' i.e., Lysine Wheat Next to rice, wheat is the most important cereal. The limiting amino acids in wheat proteins are lysine and threonine.","pyqMatches":[{"year":"2014","no":1023,"q":"Amino acid deficient in both Wheat and Maize ?","o":["Lysine","Threonine","Tryptophan","Methionine"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5666, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 277, '{"id":5666,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":277,"q":"Risk period for maximum fetal damage by congenital rubella ?","o":["First trimester of pregnancy","Second trimester of pregnancy","Third trimester of pregnancy","Risk is same throughout the pregnancy"],"a":0,"e":"Ans. is ''a'' i.e., First trimester of pregnancy In general, the earlier in pregnancy infection occurs, the greater the damage to the fetus. Maximum damage to the fetus occurs when infection is acquired in the first trimester of pregnancy.","pyqMatches":[{"year":"2014","no":981,"q":"Risk period for maximum fetal damage by congenital rubella ?","o":["First trimester of pregnancy","Second trimester of pregnancy","Third trimester of pregnancy","Risk is same throughout the pregnancy"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5667, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 278, '{"id":5667,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":278,"q":"Medical audit is done ?","o":["To improve patients care","For doctor''s benefit","For hospital staff management","For decreasing cost of treatment"],"a":0,"e":"Ans. is ''a'' i.e., To improve patients care Medical audit An objective and systematic way of evaluating the physicians performance is known \"MEDICAL AUDIT\" The Evaluation of the \"PROCESS\" of medical care is carried out by comparing with a pre-determined standard. Medical audit is the professional review of services provided by the hospital against given standard. It is defined as the retrospective evaluation of quality of medical care through the scientific analysis of medical records. Medical audit is an important component of quality assurance, which in turn is an essential part of any management process.","pyqMatches":[{"year":"2014","no":895,"q":"Medical audit is done ?","o":["To improve patients care","For doctor''s benefit","For hospital staff management","For decreasing cost of treatment"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5668, 'PSM', 'Immunization', 'Moderate', 'Preventive_&_Social_Medicine', 279, '{"id":5668,"subject":"PSM","chapter":"Immunization","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":279,"q":"Post exposure prophylaxis is given in all except ?","o":["Rabies","Chickenpox","Measles","Typhoid"],"a":3,"e":"Ans. is ''d'' i.e., Typhoid Post-exposure immunization Post exposure immunization is prophylactic immunization immediately after exposure to a pathogen, in order to prevent infection by the pathogen and the development of disease. Post exposure immunization is given for - i. Varicella (chicken pox) i. Measles i. Rabies v. Tetanus v. Hepatitis i. Meningococcal meningitis","pyqMatches":[{"year":"2014","no":906,"q":"Post exposure prophylaxis is given in all except ?","o":["Rabies","Chickenpox","Measles","Typhoid"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5669, 'PSM', 'Nutrition', 'Moderate', 'Preventive_&_Social_Medicine', 280, '{"id":5669,"subject":"PSM","chapter":"Nutrition","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":280,"q":"Good sources of vitamin ''C'' are all except ?","o":["Amala","Lime","Guava","Egg"],"a":3,"e":"Ans. is ''d'' i.e., Egg Vitamin C Also known as ascorbic acid. It is the most sensitive of all vitamins to heat. Man, monkey and guinea pigs are the perhaps the only species known to require vitamin ''C'' in their diet. The richest source of vitamin C is Indian goosebery (Amla). Important sources of vitamin C in decreasing order : ? Amla > Guava > Cabbage > Amaranth > Lime > Cauliflower > Orange > Spinach > Tomato > Potato","pyqMatches":[{"year":"2014","no":1024,"q":"Good sources of vitamin ''C'' are all except ?","o":["Amala","Lime","Guava","Egg"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5670, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 281, '{"id":5670,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":281,"q":"The validity of a test denotes ?","o":["Precision","Accuracy","Reproducibility","Reliability"],"a":1,"e":"Ans. is ''b'' i.e., Accuracy Screening test to be applied The screening test to be applied should fulfill the following important criteria before it is considered suitable for screening : - 1.Acceptability The test should be acceptable to the people at whom it is aimed. In general painful or embarrassing tests e.g., per rectal or vaginal examination are not likely to be acceptable. 2.Repeatability (reliability) Repeatability means the test must give consistent results when it is repeated more than once on the same individual under the same conditions. That means the results of the test are precise (exact), So repeatability is sometimes called precision, reliability or reproducibility.","pyqMatches":[{"year":"2014","no":938,"q":"The validity of a test denotes ?","o":["Precision","Accuracy","Reproducibility","Reliability"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5671, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 282, '{"id":5671,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":282,"q":"Maximum protein is found in ?","o":["Egg","Soyabean","Rice","Wheat"],"a":1,"e":"Ans. is ''b'' i.e., Soyabean","pyqMatches":[{"year":"2014","no":1025,"q":"Maximum protein is found in ?","o":["Egg","Soyabean","Rice","Wheat"],"a":1,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":882,"q":"Maximum protein is found in ?","o":["Egg","Soyabean","Rice","Wheat"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5672, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 283, '{"id":5672,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":283,"q":"STOP TB Strategy was lauched in ?","o":["2002","2006","2010","2013"],"a":1,"e":"Ans. is ''b'' i.e., 2006 STOP TB Strategy In 2006, WHO launched the new Stop TB Strategy. The core of this strategy is DOTS. The strategy is to be implemented over the next 10 years as described in the Global Plan to Stop TB 2006-2015. The targets and indicators for TB control are as defined within the framework of MDGs. These will be used to measure the progress made under the stop TB strategy. It focuses onthe five principal indicators that are used to measure the implementation and impact of TB control. They are : case detection, treatment success, incidence, prevalence and deaths. The global targets for case detection and treatment success have been set by WHO''s World Health Assembly. i. By 2015: The global burden of TB (prevalence and death rates) will be reduced by 50% relative to 1990 levels. This means reducing prevalence to 150 per 100,000 or lower and deaths to 15 per 100,000 per year or lower by 2015 (including TB cases coinfected with HIV). The number of people dying from TB in 2015 should be less than approximately 1 million, including those coinfected with HIV. i. By 2050 : The global incidence of TB disease will be less than or equal to 1 case per million population per year.","pyqMatches":[{"year":"2014","no":952,"q":"STOP TB Strategy was lauched in ?","o":["2002","2006","2010","2013"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5673, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 284, '{"id":5673,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":284,"q":"One TB unit is recommended for how much population in Hilly areas ?","o":["50,000","100,000","150,000","250,000"],"a":3,"e":"Ans. is ''d'' i.e., 250,000","pyqMatches":[{"year":"2014","no":955,"q":"One TB unit is recommended for how much population in Hilly areas ?","o":["50,000","100,000","150,000","250,000"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5674, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 285, '{"id":5674,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":285,"q":"Durkheim work was related to ?","o":["Recommendation of multipurpose worker","Management in Health manpower","Division of labor","Integratation of medical and health services"],"a":2,"e":"Ans. is ''c'' i.e., Division of labor Four major works of Durkheim are :?","pyqMatches":[{"year":"2014","no":894,"q":"Durkheim work was related to ?","o":["Recommendation of multipurpose worker","Management in Health manpower","Division of labor","Integratation of medical and health services"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5675, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 286, '{"id":5675,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":286,"q":"AFP surveillance registry indicator is ?","o":["Number of AFP cases reported","Number of wild polio-virus positive cases","Number of non-polio AFP < 5 years","Number of non-polio AFP < 15 years"],"a":0,"e":"Ans. is ''a'' i.e., Number of AFP cases reported The number of AFP cases reported each year is used as an indicator of a country''s ability to detect polio, even in countries where the disease no longer occurs. Polio surveillance It is the most important part of whole polio eradication intiative. It has two components:? Acute flaccid paralysis (AFP) surveillance Acute flaccid paralysis is defined as acute onset (< 4 weeks) of flaccid paralysis (reduced tone) without other obvious cause in children WHO recommends the immediate reporting and investigation of every case of AFP in children less than 15 years.","pyqMatches":[{"year":"2014","no":982,"q":"AFP surveillance registry indicator is ?","o":["Number of AFP cases reported","Number of wild polio-virus positive cases","Number of non-polio AFP < 5 years","Number of non-polio AFP < 15 years"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5676, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 287, '{"id":5676,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":287,"q":"The most common cause of blindness in India is ?","o":["Cataract","Trachoma","Refractive errors","Vitamin A deficiency"],"a":0,"e":"Ans. is ''a'' i.e., Cataract","pyqMatches":[{"year":"2014","no":1059,"q":"The most common cause of blindness in India is ?","o":["Cataract","Trachoma","Refractive errors","Vitamin A deficiency"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5677, 'PSM', 'Environment & Occupational Health', 'Moderate', 'Preventive_&_Social_Medicine', 288, '{"id":5677,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":288,"q":"All are true about epidemiological features of cholera except ?","o":["Epidemic is self limiting","Poor sanitation is a cause of epidemic","El Tor biotype has decreased endemicity","Onset of epidemic is abrupt"],"a":2,"e":"The El Tor biotypes have greater endemic tendency than its classical counterpart in that it causes a higher infection-to-case ratio (i.e. more inapparent infections and mild cases). About other options Cholera epidemic has an abrupt onset. It starts as common source epidemic and often treat an acute health problem. Then it continues as a propagated epidemics as cases become the source for the other persons. Cholera epidemic in a community is self-limiting. This is attributed to the acquisition of temporary immunity, as well as due to the occurrence of a large number of subclinical cases. Poor environmental sanitation is the most important predisposing factor for epidemic","pyqMatches":[{"year":"2014","no":976,"q":"All are true about epidemiological features of cholera except ?","o":["Epidemic is self limiting","Poor sanitation is a cause of epidemic","El Tor biotype has decreased endemicity","Onset of epidemic is abrupt"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5678, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 289, '{"id":5678,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":289,"q":"Incidence is calculated by ?","o":["Cross sectional study","Cohort study","Case control study","None"],"a":1,"e":"Ans. is ''b'' i.e., Cohort study","pyqMatches":[{"year":"2014","no":926,"q":"Incidence is calculated by ?","o":["Cross sectional study","Cohort study","Case control study","None"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5679, 'PSM', 'Communicable Diseases', 'Easy', 'Preventive_&_Social_Medicine', 290, '{"id":5679,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":290,"q":"A problem village is one where ?","o":["Source of water > 1.6 km away","Water available > 15 meters depth","Excess of fluoride in water","All of the above"],"a":3,"e":"Ans. is `d'' i.e., All of the above A problem village has been defined as one Where no source of safe water is available within a distance of 1.6 km, or Where water is available at a depth of more than 15 meters, or Where water source has excess salinity, iron, fluorides and other toxic elements, or Where water is exposed to the risk of cholera.","pyqMatches":[{"year":"2014","no":1062,"q":"A problem village is one where ?","o":["Source of water > 1.6 km away","Water available > 15 meters depth","Excess of fluoride in water","All of the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5680, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 291, '{"id":5680,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":291,"q":"Most common presentation of mumps ?","o":["Pain and lacrimation of eye","Pain and swelling of parotid glands","Pain and swelling of submandibular and sublingual glands","Aseptic meningitis"],"a":1,"e":"Ans. is ''b'' i.e., Pain and swelling of parotid glands","pyqMatches":[{"year":"2014","no":967,"q":"Most common presentation of mumps ?","o":["Pain and lacrimation of eye","Pain and swelling of parotid glands","Pain and swelling of submandibular and sublingual glands","Aseptic meningitis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5681, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 292, '{"id":5681,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":292,"q":"Prevalence of Influenza in India ?","o":["10 per 10000 population","10 per 100000 population","10 per 1000 population","Data regarding prevalence of influenza is not adequate"],"a":3,"e":"Ans. is ''d'' i.e., Data regarding prevalence of influenza is not adequate","pyqMatches":[{"year":"2014","no":965,"q":"Prevalence of Influenza in India ?","o":["10 per 10000 population","10 per 100000 population","10 per 1000 population","Data regarding prevalence of influenza is not adequate"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5682, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 293, '{"id":5682,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":293,"q":"Billings method of contraception is based on ?","o":["Change in temperature","Change in cervical mucus","Safe period (calendar method)","Coitus interruptus"],"a":1,"e":"Ans. is ''b'' i.e., Change in cervical mucus Miscellaneous methods of contraceptions These are (i) Abstinence, (ii) Coitus interruptus, (iii) Safe period (rhythm method), and (iv) Natural family planning methods. Abstinence There is complete abstinence from sexual intercourse. It is not used and can hardly be considered as a method of contraception to be advocated for the masses. Coitus interruptus It is the oldest method of voluntary fertility control. The male withdraws before ejaculation and thereby tries to prevent the deposition of semen into the vagina. The failure rate is very high at 25%. Natural family planning methods These are :? Basal body temperature (BBT) method: It is based on the principle that there is a rise BBT at or just before ovulation. Cervical mucus method (Billings method or ovulation method) : It is based on the observation that at the time of ovulation cervical mucus becomes watery clear resembling raw egg white, smooth, slippery and profuse. Symptothermic method: This method combines temperature, cervical mucus, and safe period (calendar method) methods.","pyqMatches":[{"year":"2014","no":997,"q":"Billings method of contraception is based on ?","o":["Change in temperature","Change in cervical mucus","Safe period (calendar method)","Coitus interruptus"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5683, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 294, '{"id":5683,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":294,"q":"In epidemics measles vaccine is to be given within how many days of exposure ?","o":["3 days","7 days","10 days","15 days"],"a":0,"e":"Ans. is ''a'' i.e., 3 days Incubation period of measles virus is 10 days. Incubation period of live attenuated measles virus of live vaccine is 7 days. Thus, if the vaccine is given within 2-3 days of exposure, the replication of vaccine virus takes preference over replication of wild virus. \"Susceptible contacts over the age of 9-12 months may be protected against measles with measles vaccine, provided that this is given within 3 days of exposure. This is because, the incubation period of measles induced by vaccine is about 7 days, compaired with 10 days for the naturally acquird measles.\" — Park","pyqMatches":[{"year":"2014","no":966,"q":"In epidemics measles vaccine is to be given within how many days of exposure ?","o":["3 days","7 days","10 days","15 days"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5684, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 295, '{"id":5684,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":295,"q":"Yellow bag is used for -","o":["Waste sharp","Cytotoxic drugs","Animal waste","Chemical waste"],"a":2,"e":"Ans. is ''c'' i.e., Animal waste","pyqMatches":[{"year":"2014","no":1052,"q":"Yellow bag is used for","o":["Waste sharp","Cytotoxic drugs","Animal waste","Chemical waste"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5685, 'PSM', 'Immunization', 'Moderate', 'Preventive_&_Social_Medicine', 296, '{"id":5685,"subject":"PSM","chapter":"Immunization","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":296,"q":"Isolation is not done in ?","o":["Cholera","Diphtheria","Mumps","Hepatitis"],"a":2,"e":":D Ans. is (D) Hepatitis (C) Mumps Isolation has a distinctive value in the control of some infectious diseases, e.g., diphtheria, cholera, streptococcal respiratory disease, pneumonic plague. In some diseaes where there is a large component of subclinical infection and carrier state, even the most rigid isolation will not prevent the spread of disease, e.g., polio, hepatitis and typhoid fever. Mumps is highly infectious before it is diagnosed hence isolation for most cases of mumps has proved futile - Park. Measles is also highly infectious during prodromal period, isolation is most useful if diagnosis can be established in the prodromal/catarrhal stage. But most cases of measles are diagnosed with the appearance of rash when communicability begins to decline. Isolation in measles is therefore not likely to be very effective.","pyqMatches":[{"year":"2014","no":907,"q":"Isolation is not done in ?","o":["Cholera","Diphtheria","Mumps","Hepatitis"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5686, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 297, '{"id":5686,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":297,"q":"Association of Two variables explained by 3rd variable is ?","o":["Spurious association","Indirect association","Direct association","Causal association"],"a":1,"e":"Ans. is ''b'' i.e., Indirect association Association Descriptive studies help to suggest an aetiological hypothesis. Analytic and experimental studies test the hypothesis, derived from descriptive studies and confirm or refute the observed association between suspected causes and disease. Association may be defined as the concurrence of two variables more often than would be expected by chance. In other words, events are said to be associated when they occur more frequently togeher than one would expect by chance. Association can be of following types : - 1 .Spurious association Observed association between a disease and suspected factor is spurious, i.e., not real. In other words there is an observed association when none actually exists. 2.Indirect association The indirect association is a statistical association between a variable of interest and a disease due to the presence of another factor, known or unknown, that is common to both the variable and the disease. This third factor (i.e., the common factor) is also known as the confounding variable. For example, endemic goitre (disease) is found at high altitudes (variable), showing thereby an association between altitude and endemic goitre. But it is due to iodine deficiency which is common at high altitude. So, iodine deficiency acts as a confounding factor as it is associated with both high altitude and endemic goitre. 3.Direct (causal) association a) One to one causal relationship Two variables are stated to be causally related if change in one is followed by change in other. If It does not, then their relationship cannot be causal. b) Multifactorial causation The causal thinking is different in non-communicable disease (e.g., CHD) where the etiology is multifactorial, i.e., more than one factors are associated with disease causation.","pyqMatches":[{"year":"2014","no":919,"q":"Association of Two variables explained by 3rd variable is ?","o":["Spurious association","Indirect association","Direct association","Causal association"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5687, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 298, '{"id":5687,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":298,"q":"Numerator in negative predictive value ?","o":["True positive","False positive","True negative","False negative"],"a":2,"e":"Ans. is ''c'' i.e., True negative specificity = True negatives/True negatives+False positives Sensitivity=True Positives/True positives+False negatives Positive predictive value = True positives/(true+false) positives Negative predictive value = True negatives/(true+false) negatives","pyqMatches":[{"year":"2014","no":940,"q":"Numerator in negative predictive value ?","o":["True positive","False positive","True negative","False negative"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5688, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 299, '{"id":5688,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":299,"q":"Stage of contraction of family starts at ?","o":["Marriage","Birth of first child","Birth of last child","Leaving home of first child"],"a":3,"e":"Ans. is `d'' i.e., Leaving home of first child","pyqMatches":[{"year":"2013","no":955,"q":"Stage of contraction of family starts at ?","o":["Marriage","Birth of first child","Birth of last child","Leaving home of first child"],"a":3,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":1014,"q":"Stage of contraction of family starts at ?","o":["Marriage","Birth of first child","Birth of last child","Leaving home of first child"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5689, 'PSM', 'Biostatistics', 'Easy', 'Preventive_&_Social_Medicine', 300, '{"id":5689,"subject":"PSM","chapter":"Biostatistics","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":300,"q":"Clinical audit means ?","o":["Measuring hospital records","Measuring current patients care against explicit criteria","Measuring input-output analysis","Measuring shortest time needed to complete task"],"a":1,"e":"Ans. is ''b'' i.e., Measuring current patients care against explicit criteria Clinical audit is a quality improving process, in which patients care is improved. In this, current patients outcome and outcomes are measured against explicit audit criteria (against reference standards).","pyqMatches":[{"year":"2014","no":896,"q":"Clinical audit means ?","o":["Measuring hospital records","Measuring current patients care against explicit criteria","Measuring input-output analysis","Measuring shortest time needed to complete task"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5690, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 301, '{"id":5690,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":301,"q":"Nutrient which is lost maximum in polished rice?","o":["Proteins","Thiamine","Ascorbic acid","Calcitriol"],"a":1,"e":"Ans. is ''b'' i.e., Thiamine Effect of milling on rice The milling process deprives the rice grain of its valuable nutritive elements","pyqMatches":[{"year":"2014","no":1033,"q":"Nutrient which is lost maximum in polished rice?","o":["Proteins","Thiamine","Ascorbic acid","Calcitriol"],"a":1,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":889,"q":"Nutrient which is lost maximum in polished rice?","o":["Proteins","Thiamine","Ascorbic acid","Calcitriol"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5691, 'PSM', 'Maternal & Child Health', 'Easy', 'Preventive_&_Social_Medicine', 302, '{"id":5691,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":302,"q":"Zinc supplement given in 12 month baby -","o":["lgm/day","10 mg/day","5 mg/day","15 mg/day"],"a":2,"e":"Ans. is ''c'' i.e., 5 mg/day The requirements for infants range between 3.5 - 5.0 mg/day.","pyqMatches":[{"year":"2014","no":1034,"q":"Zinc supplement given in 12 month baby","o":["lgm/day","10 mg/day","5 mg/day","15 mg/day"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5692, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 303, '{"id":5692,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":303,"q":"Which line of death certificate represent major antecedent cause of death -","o":["Ia","Ib","Ic","II"],"a":2,"e":"Ans. is ''c'' i.e., Ic International death certificate The basis of mortality data is death certificate. For ensuring national and international comparability, it is necessary to have a uniform and standardized system of recording and classifying deaths. For this purpose WHO has recommended international death certificate. Consist of four lines:","pyqMatches":[{"year":"2014","no":651,"q":"Which line of death certificate represent major antecedent cause of death","o":["Ia","Ib","Ic","II"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5693, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 304, '{"id":5693,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":304,"q":"Biological value of protein is","o":["Increase in weight per unit protein consumed","Percentage of ingested protein retained inside the body","Percentage of absorbed nitrogen retained","Percentage of energy provided by a protein of food"],"a":2,"e":"Ans. is ''c'' i.e., Percentage of absorbed nitrogen retained Assessment of proteins Protein can be assessed qualitatively or quantitatively:? 1) Protein quantity It is assessed by the protein-energy ratio. 2) Protein quality It is assessed by amino-acid score, biological value, net protein utilization, protein efficiency ratio, and protein digestibility corrected amino acid score. Protein energy Ratio (Protein-energy percentage) It is a quantitative measure for assessment of protein. It measures the percentage of energy that is provided by the protein in the food.","pyqMatches":[{"year":"2014","no":1036,"q":"Biological value of protein is","o":["Increase in weight per unit protein consumed","Percentage of ingested protein retained inside the body","Percentage of absorbed nitrogen retained","Percentage of energy provided by a protein of food"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5694, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 305, '{"id":5694,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":305,"q":"RDA of zinc in a child ?","o":["10 mg","20 mg","6-8 mg","4-5 mg"],"a":2,"e":"Ans. is ''c'' i.e., 6-8 mg RDA of Zinc in children 1 - 3 years —> 3mg 4 - 8 years -5 5 mg 9 years and above (male) —> 8 - 11 mg 9 years and above (female) --> 8 mg","pyqMatches":[{"year":"2014","no":1035,"q":"RDA of zinc in a child ?","o":["10 mg","20 mg","6-8 mg","4-5 mg"],"a":2,"source":"NEET_2014_Paper.pdf"},{"year":"2016","no":1366,"q":"RDA of zinc in a child ?","o":["10 mg","20 mg","6-8 mg","4-5 mg"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2014","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5695, 'PSM', 'National Health Programmes', 'Easy', 'Preventive_&_Social_Medicine', 306, '{"id":5695,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":306,"q":"Mental health programme was started in?","o":["1982","1987","1990","1995"],"a":0,"e":"Ans. is ''a'' i.e., 1982 The Government of India has launched the National Mental Health Programme (NMHP) in 1982. Also know Mental health act was started in 1987.","pyqMatches":[{"year":"2014","no":1063,"q":"Mental health programme was started in?","o":["1982","1987","1990","1995"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5696, 'PSM', 'Biostatistics', 'Easy', 'Preventive_&_Social_Medicine', 307, '{"id":5696,"subject":"PSM","chapter":"Biostatistics","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":307,"q":"Test used to assess quantitative observations before and after an intervention ?","o":["Unpaired T-test","Paired T-test","Chi-square test","Fisher-T-test"],"a":1,"e":"Ans. is ''b'' i.e., Paired T-test A paired t-test is used to compare two population means where you have two samples in which observations in one sample can be paired with observations in the other sample this might occur in: • Before-and-after observations on the same subjects (e.g. students’ diagnostic test results before and after a particular module or course). • A comparison of two different methods of measurement or two different treat ments where the measurements/treatments are applied to the same subjects (e.g. blood pressure measurements using a stethoscope and a dynamap). Paired test : Is applied to paired data, when each individual gives a pair of observations such as : when observations are made before and after the play of a factor e.g. pulse rate before and after a drug. Further, it proceeds similar to the unpaired test.","pyqMatches":[{"year":"2014","no":1076,"q":"Test used to assess quantitative observations before and after an intervention ?","o":["Unpaired T-test","Paired T-test","Chi-square test","Fisher-T-test"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5697, 'PSM', 'Immunization', 'Moderate', 'Preventive_&_Social_Medicine', 308, '{"id":5697,"subject":"PSM","chapter":"Immunization","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":308,"q":"Virus not sensitive to disinfection by chlorination","o":["Rotavirus","Norwalk virus","Poliovirus","None"],"a":2,"e":"Ans. is ''c'' i.e., Poliovirus Chlorination Chlorination is one of the greatest advances in water purification. Chlorine kills pathogenic bacteria, but has no effect on spores, certain viruses (e.g., polio, viral hepatitis) and cyst of E.histolytica, in usual doses. Mechanism of action When chlorine is added to water, there is the formation of hypochloric and hypochlorous acid The hypochloric acid is neutralized by the alkalinity of the water. The hypochlorous acid ionizes to form hydrogen ions and hypochlorite ions. The disinfecting action of chlorine is mainly due to the hypochlorous acid and to a small extent due to the hypochlorite ions. The hypochlorous acid is the most effective form of chlorine for water disinfection, it is 70-80 times more effective than hypochlorite ion.","pyqMatches":[{"year":"2014","no":1048,"q":"Virus not sensitive to disinfection by chlorination","o":["Rotavirus","Norwalk virus","Poliovirus","None"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5698, 'PSM', 'Immunization', 'Moderate', 'Preventive_&_Social_Medicine', 309, '{"id":5698,"subject":"PSM","chapter":"Immunization","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":309,"q":"Vaccine which should not be frozen -","o":["OPV","Measles","HBV","Yellow fever"],"a":2,"e":"Ans. is ''c'' i.e., HBV OPV and measles vaccines are stored in deep freezers. (Note : Yellow fever vaccine is also freez dried, but is not used in India). Vaccine which must be stored in the cold part but never allowed to freez. Typhoid DPT TT Hepatitis B DT BCG Diluents","pyqMatches":[{"year":"2014","no":909,"q":"Vaccine which should not be frozen","o":["OPV","Measles","HBV","Yellow fever"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5699, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 310, '{"id":5699,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":310,"q":"Koplik spot is pathognomic of which infection ?","o":["Rubella","Influenza","Mumps","Measles"],"a":3,"e":"Ans. is ''d'' i.e., Measles","pyqMatches":[{"year":"2014","no":948,"q":"Koplik spot is pathognomic of which infection ?","o":["Rubella","Influenza","Mumps","Measles"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5700, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 311, '{"id":5700,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":311,"q":"Spread of chicken pox is maximum ?","o":["After formation of scab","Just before and after onset of rash","One week before onset of rash","During convelescence"],"a":1,"e":"Ans. is ''b'' i.e., Just before and after onset of rash Communicable period (period of maximum infectivity) in chicken pox is 2 days before to 5 days after onset of rash.","pyqMatches":[{"year":"2014","no":962,"q":"Spread of chicken pox is maximum ?","o":["After formation of scab","Just before and after onset of rash","One week before onset of rash","During convelescence"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5701, 'PSM', 'Maternal & Child Health', 'Easy', 'Preventive_&_Social_Medicine', 312, '{"id":5701,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":312,"q":"Breast milk is deficient in which vitamin","o":["Vitamin A","Vitamin B1","Vitamin K","Vitamin C"],"a":2,"e":"Ans. is ''c'' i.e., Vitamin K Exclusive breasfed infants may have following deficiencies -","pyqMatches":[{"year":"2014","no":1037,"q":"Breast milk is deficient in which vitamin","o":["Vitamin A","Vitamin B1","Vitamin K","Vitamin C"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5702, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 313, '{"id":5702,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":313,"q":"Percentage of women 15-24 years age group in India ?","o":["10%","20%","30%","40%"],"a":1,"e":"Ans. is ''b'' i.e., 20% In India percentage of women in 15-24 years age group.","pyqMatches":[{"year":"2014","no":1005,"q":"Percentage of women 15-24 years age group in India ?","o":["10%","20%","30%","40%"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5703, 'PSM', 'National Health Programmes', 'Easy', 'Preventive_&_Social_Medicine', 314, '{"id":5703,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":314,"q":"Under MCH programme, adult IFA tablet contains ?","o":["100 mg elemental iron and 0.1 mg FA","100 mg elemental iron and 0.5 mg FA","20 mg elemental iron and 0.1 mg FA","20 mg elemental iron and 0-5 mg FA"],"a":1,"e":"Ans. is ''b'' i.e., 100 mg elemental iron and 0.5 mg FA Iron and Folic Acid content per IFA tablet: Adult tablet: 100 mg elemental iron and 500 mcg folic acid Pediatric tablet: 20 mg elemental iron and 100 mcg folic acid For preterm infants, recommended Iron and Folic Acid content per IFA tablet: Pediatric tablet: 10 — 15 mg elemental iron and 100 mcg folic acid.","pyqMatches":[{"year":"2014","no":1042,"q":"Under MCH programme, adult IFA tablet contains ?","o":["100 mg elemental iron and 0.1 mg FA","100 mg elemental iron and 0.5 mg FA","20 mg elemental iron and 0.1 mg FA","20 mg elemental iron and 0-5 mg FA"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5704, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 315, '{"id":5704,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":315,"q":"Amplifier for Japanese encephalitis ?","o":["Horse","Pigs","Dogs","Monkey"],"a":1,"e":"Ans. is ''b'' i.e., Pigs","pyqMatches":[{"year":"2014","no":986,"q":"Amplifier for Japanese encephalitis ?","o":["Horse","Pigs","Dogs","Monkey"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5705, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 316, '{"id":5705,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":316,"q":"IQ in mild mental retardation is","o":["50-70","35-49","20-34","< 20"],"a":0,"e":"Ans. is ''a'' i.e., 50-70","pyqMatches":[{"year":"2015","no":1365,"q":"IQ in mild mental retardation is","o":["50-70","35-49","20-34","< 20"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5706, 'PSM', 'Biostatistics', 'Easy', 'Preventive_&_Social_Medicine', 317, '{"id":5706,"subject":"PSM","chapter":"Biostatistics","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":317,"q":"Most common type of mental retardation ?","o":["Mild","Moderate","Severe","Profound"],"a":0,"e":"Ans. is ''a'' i.e., Mild","pyqMatches":[{"year":"2013","no":960,"q":"Most common type of mental retardation ?","o":["Mild","Moderate","Severe","Profound"],"a":0,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":1064,"q":"Most common type of mental retardation ?","o":["Mild","Moderate","Severe","Profound"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5707, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 318, '{"id":5707,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":318,"q":"Disease associated with excessive maize diet ?","o":["Wernicke''s encephalopathy","Pellagra","Beri-Beri","Scurvy"],"a":1,"e":"Ans. is ''b'' i.e., Pellagra Excess of Leucine interferes in conversion of Tryptophan into Niacin, and aggravates the pallagrogenic action of maize. Similar to maize, Jowar also contains excess of leucine. Leucine interferes with conversion of tryptophan to niacin. Pellagra has been reported in India in Telangana area of Andhra Pradesh because of Jower (Sorghum vulgare) consumption.","pyqMatches":[{"year":"2014","no":1038,"q":"Disease associated with excessive maize diet ?","o":["Wernicke''s encephalopathy","Pellagra","Beri-Beri","Scurvy"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5708, 'PSM', 'Epidemiology', 'Moderate', 'Preventive_&_Social_Medicine', 319, '{"id":5708,"subject":"PSM","chapter":"Epidemiology","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":319,"q":"Prevalence of HIV infection in antenatal women is less than 1% and in high risk population is less than 5%. The state belongs to ?","o":["Group I","Group II","Group III","Group IV"],"a":2,"e":"Ans. is `c'' i.e., Group III Based on sentinel surveillance data HIV prevalence in adult population can be broadly classified in three groups of state / UT sin the country.","pyqMatches":[{"year":"2014","no":973,"q":"Prevalence of HIV infection in antenatal women is less than 1% and in high risk population is less than 5%. The state belongs to ?","o":["Group I","Group II","Group III","Group IV"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5709, 'PSM', 'National Health Programmes', 'Moderate', 'Preventive_&_Social_Medicine', 320, '{"id":5709,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":320,"q":"In AIDs control programme, For treatment of STDs, blue colored pack is used for treatment of-","o":["Urethral discharge","Scrotal swelling","Genital ulcers","Ano-rectal discharge"],"a":2,"e":"Ans. is ''c'' i.e., Genital ulcer NACO centers providing ART (as of sept 2006) The National AIDS control organization (NACO) has increased the numbers of centres providing ART from 54 to 91 centres with another 9 more centres also getting operational soon. All the 9lcentres have specially appointed and trained doctors, counsellors and laboratory technicians to help initiate patients on ART and follow them regularly. At these 91 centres medicines for treating 85000 patients have been made available. The ART is a combination of three potent drugs, which is being given to the persons with advanced stage of AIDS. Apart from providing free treatment, all the ART centres are providing counselling to the infected persons so that they maintain regularly of their medication. ACO has branded the STI/RTI services as \"Suraksha clinic\" and has developed a communication strategy for generating demand for these services.","pyqMatches":[{"year":"2014","no":974,"q":"In AIDs control programme, For treatment of STDs, blue colored pack is used for treatment of","o":["Urethral discharge","Scrotal swelling","Genital ulcers","Ano-rectal discharge"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5710, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 321, '{"id":5710,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":321,"q":"Not true about vaccines ?","o":["Two live vaccines can be given at same time at different sites","Two live vaccines at same site should be given at least 3 weeks apart","In vaccine vial monitor if the color of inner square is same as outer background, vaccine is good for use","Live and killed vaccines can be given together"],"a":2,"e":"Ans. is ''c'' i.e., In vaccine vial monitor if the color of inner square is same as outer background, vaccine is good for use Vaccine Vial monitor An important improvement in PPI during 1998 has been the use of vaccine vial monitor. Colour monitors or labels are put on vaccine bottles. Each label has a circle of deep blue colour. Inside it is a white square which changes colour and gradually becomes blue, if vaccine bottle is exposed to higher temprature. When the colour of the white square becomes blue like that of surrounding circle, the vaccine should be consid​ered ineffective. Thereby, the health worker can easily ascertain that the vaccine being given is effective or not.","pyqMatches":[{"year":"2014","no":910,"q":"Not true about vaccines ?","o":["Two live vaccines can be given at same time at different sites","Two live vaccines at same site should be given at least 3 weeks apart","In vaccine vial monitor if the color of inner square is same as outer background, vaccine is good for use","Live and killed vaccines can be given together"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5711, 'PSM', 'Concept of Health & Disease', 'Hard', 'Preventive_&_Social_Medicine', 322, '{"id":5711,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":322,"q":"A patient comes with CLW on knee 10x2 cm, 12 hours old. He had taken TT 6 months back for another injury. What should be done ?","o":["Nothing should be done","One dose of TT with immunoglobulin","Full course of TT","Full course of TT with immunoglobulin"],"a":1,"e":"Ans. is ''b'' i.e., One dose of TT with immunoglobulin Prevention of tetanus after injury All wounds must be thoroughly cleaned soon after injury - removal of foreign bodies, soil dust, necrotic tissue. This procedure will abolish anaerobic conditions which favour germination of tetanus spore.","pyqMatches":[{"year":"2014","no":987,"q":"A patient comes with CLW on knee 10x2 cm, 12 hours old. He had taken TT 6 months back for another injury. What should be done ?","o":["Nothing should be done","One dose of TT with immunoglobulin","Full course of TT","Full course of TT with immunoglobulin"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5712, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 323, '{"id":5712,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":323,"q":"Lack of ability of a part to do normal function is called as ?","o":["Impairment","Disease","Disability","Handicap"],"a":2,"e":"Ans. is ''c'' i.e., Disability According to WHO definitions, Disease: Any abnormal condition of an individual that impairs function Impairment: Any loss or abnormality of psychological, physiological or anatomical structure or function Disability: (Because of impairment,) any restriction or inability to perform an activity in a range considered normal for a human being","pyqMatches":[{"year":"2014","no":901,"q":"Lack of ability of a part to do normal function is called as ?","o":["Impairment","Disease","Disability","Handicap"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5713, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 324, '{"id":5713,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":324,"q":"ICDS meals for pregnant women provides ?","o":["300 calories & 10 grams protein","500 calories & 15 grams protein","600 calories & 10 grams protein","600 calories & 20 grams protein"],"a":3,"e":"Ans. is d i.e., 600 calories & 20 grams protein Under ICDS Scheme supplementary nutrition is given to: Children below 6 yrs Nursing mothers Expectant mothers The aim is to supplement nutritional intake for","pyqMatches":[{"year":"2014","no":1039,"q":"ICDS meals for pregnant women provides ?","o":["300 calories & 10 grams protein","500 calories & 15 grams protein","600 calories & 10 grams protein","600 calories & 20 grams protein"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5714, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 325, '{"id":5714,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":325,"q":"Mid-day meals provided in schools provide ?","o":["1/2 of total calories & 1/2 of protein","1/3 of total calories & 1/2 of protein","1/2 of total calories & 1/3 of protein","1/3 of total calories & 1/4 of protein"],"a":1,"e":"Ans. is `b'' i.e., 1/3rd of total calories & 1/2 of daily protein requirement","pyqMatches":[{"year":"2014","no":1040,"q":"Mid-day meals provided in schools provide ?","o":["1/2 of total calories & 1/2 of protein","1/3 of total calories & 1/2 of protein","1/2 of total calories & 1/3 of protein","1/3 of total calories & 1/4 of protein"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5715, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 326, '{"id":5715,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":326,"q":"Which drug is not included in RNTCP regime for MDR TB ?","o":["Cycloserine","Ethionamide","Levofloxacin","PAS"],"a":3,"e":"Ans. is `d'' i.e., PAS","pyqMatches":[{"year":"2014","no":954,"q":"Which drug is not included in RNTCP regime for MDR TB ?","o":["Cycloserine","Ethionamide","Levofloxacin","PAS"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5716, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 327, '{"id":5716,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":327,"q":"Primordial prevention is done to prevent development of ?","o":["Disease","Risk factors","Impairment","Disability"],"a":1,"e":"Ans. is ''b'' i.e., Risk factors LEVELS OF PREVENTION There are four levels of prevention :?","pyqMatches":[{"year":"2014","no":899,"q":"Primordial prevention is done to prevent development of ?","o":["Disease","Risk factors","Impairment","Disability"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5717, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 328, '{"id":5717,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":328,"q":"First step in epidemic done by an epidemiologist?","o":["Identity the cases","Confirm the diagnosis","Identify the prone people","Identify the causative factors"],"a":1,"e":"Ans. is ''b'' i.e., Confirmation of diagnosis Steps for Investigation of Epidemic : Verification of diagnosis : Is the first step in investigation of an epidemic'' Confirmation of existence of an epidemic: Compare with disease frequencies during same period in previous years Epidemic threshold: An arbitrary limit of ''2 standard errors from the endemic occurrence'' Defining the population at risk: Obtaining the map of the area Calculation of ''appropriate denominator of population at risk'' Rapid search for all cases and their characteristics: Medical survey Epidemiological case sheet Searching for more cases: Search for new cases is carried out everyday, till the area is declared free of epidemic; this period is usually taken as ''twice the incubation period of the disease since the occurrence of last case'' Data analysis: Formulation of hypothesis Testing of hypothesis Evaluation of ecological factors Further investigation of population at risk Writing the report","pyqMatches":[{"year":"2014","no":921,"q":"First step in epidemic done by an epidemiologist?","o":["Identity the cases","Confirm the diagnosis","Identify the prone people","Identify the causative factors"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5718, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 329, '{"id":5718,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":329,"q":"Formula to calculate sensitivity of a screening test ?","o":["True positive/true positive + false negative","True negative/true positive + false negative","True positive/true negative + false positive","True negative/true negative + false positive"],"a":0,"e":"Ans. is ''a'' i.e., True positive/true positive + false negative The formula for the positive likelihood ratio (\"LR+\") considers both sensitivity and specificity: it''s sensitivity divided by (1- specificity), or the true positive rate divided by the false positives. This shows how much more likely is a person with the disease to score positive than a person without the disease.","pyqMatches":[{"year":"2014","no":941,"q":"Formula to calculate sensitivity of a screening test ?","o":["True positive/true positive + false negative","True negative/true positive + false negative","True positive/true negative + false positive","True negative/true negative + false positive"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5719, 'PSM', 'Environment & Occupational Health', 'Easy', 'Preventive_&_Social_Medicine', 330, '{"id":5719,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":330,"q":"False regarding larvae of anopheles ?","o":["Long siphon tube","Parallel to water","Palmate hairs","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Long siphon tube","pyqMatches":[{"year":"2014","no":1047,"q":"False regarding larvae of anopheles ?","o":["Long siphon tube","Parallel to water","Palmate hairs","None of the above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5720, 'PSM', 'Environment & Occupational Health', 'Easy', 'Preventive_&_Social_Medicine', 331, '{"id":5720,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":331,"q":"Recommended level of fluoride in drinking water?","o":["0.2-0.5 mg/L","0-5-0.8 mg/L","0.8-1.2 mg/L","1.2-2.0 mg/L"],"a":1,"e":"Ans. is ''b'' i.e., 0.5 - 0.8 mg/L The recommended level of fluoride in drinking water in the country is accepted as 0.5 to 0.8 mg/ Liter. -Park Maximum permissible limit is 1.5 mg/Lit.","pyqMatches":[{"year":"2014","no":1016,"q":"Recommended level of fluoride in drinking water?","o":["0.2-0.5 mg/L","0-5-0.8 mg/L","0.8-1.2 mg/L","1.2-2.0 mg/L"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5721, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 332, '{"id":5721,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":332,"q":"Dental fluorosis occurs if fluoride level is more than","o":["0.5 mg/dl","1-5 mg/dl","3 mg/dl","6 mg/dl"],"a":1,"e":"Ans. is ''b'' i.e., 1-5 mg/dl Dental fluorosis → > 1.5 mg/L (PPM) Skeletal fluorosis → 3-6 mg/L (PPM) Crippling fluorosis → > 10 mg/L (PPM)","pyqMatches":[{"year":"2014","no":1017,"q":"Dental fluorosis occurs if fluoride level is more than","o":["0.5 mg/dl","1-5 mg/dl","3 mg/dl","6 mg/dl"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5722, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 333, '{"id":5722,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":333,"q":"Most common cancer in males in India ?","o":["Ca rectum","Ca oral cavity","Ca testis","Ca bladder"],"a":1,"e":"Ans. is ''b'' i.e., Ca oral cavity Most common cancer in males in India : Lip/oral cavity","pyqMatches":[{"year":"2014","no":1055,"q":"Most common cancer in males in India ?","o":["Ca rectum","Ca oral cavity","Ca testis","Ca bladder"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5723, 'PSM', 'National Health Programmes', 'Easy', 'Preventive_&_Social_Medicine', 334, '{"id":5723,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":334,"q":"Blindness criteria in India ?","o":["Vision < 3/60","Vision < 6/60","Vision < 12/60","Vision < 18/60"],"a":1,"e":"Ans. is ''b'' i.e., Vision < 6/60 National programme for control of blindness (NPCB), India defines blindness as visual acuity of < 6/60 in better eve with best possible correction In contrast to WHO, which defines blindness as visual acuity of < 3/60).","pyqMatches":[{"year":"2014","no":1056,"q":"Blindness criteria in India ?","o":["Vision < 3/60","Vision < 6/60","Vision < 12/60","Vision < 18/60"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5724, 'PSM', 'Communicable Diseases', 'Moderate', 'Preventive_&_Social_Medicine', 335, '{"id":5724,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":335,"q":"Basic laboratory service is not available at PHC for which disease ?","o":["TB","Malaria","Syphilis","Leprosy"],"a":3,"e":"Ans. is ''d'' i.e., Leprosy Basic laboratory services at PHC i. Routine urine, stool and blood tests. i. Bleeding time, clotting time. i. Diagnosis of RT1/STDs with wet mounting, Grama stain, etc. v. Sputum testing for tuberculosis (if designated as a microscopy center under RNTCP). v. Blood smear examination for malarial parasite. i. Rapid tests for pregnancy. i. RPR test for Syphilis/YAWS surveillance. i. Rapid diagnostic tests for typhoid (Typhi Dot) and malaria. x. Raid test kit for faecal contamination of water. x. Estimation of chlorine level of water using orthotoludine reagent.","pyqMatches":[{"year":"2014","no":1065,"q":"Basic laboratory service is not available at PHC for which disease ?","o":["TB","Malaria","Syphilis","Leprosy"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5725, 'PSM', 'Immunization', 'Hard', 'Preventive_&_Social_Medicine', 336, '{"id":5725,"subject":"PSM","chapter":"Immunization","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":336,"q":"Polio is said to be eradicated if no case of polio by wild poliovirus occurs in an area for ?","o":["1 year","2 years","3 years","4 years"],"a":2,"e":"Ans. is ''c'' i.e., 3 years Certification of polio eradication is conducted an regional bases. Each region can consider certification only when all countries in the area demonstrate the absence of wild poliovirus transmission for at least three consecutive years.","pyqMatches":[{"year":"2014","no":983,"q":"Polio is said to be eradicated if no case of polio by wild poliovirus occurs in an area for ?","o":["1 year","2 years","3 years","4 years"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5726, 'PSM', 'Communicable Diseases', 'Easy', 'Preventive_&_Social_Medicine', 337, '{"id":5726,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":337,"q":"Dose of rabies immunoglobulin for post- exposure prophylaxis ?","o":["10 IU/kg","20 IU/kg","30 IU/kg","40 1U/kg"],"a":1,"e":"Ans. is ''b'' i.e., 20 IU/kg Dose of rabies immunoglobulin (equine immunoglobulin) → 20 IU/kg body weight. Dose of F (ab)2 products → 40 IU/kg body weight.","pyqMatches":[{"year":"2014","no":984,"q":"Dose of rabies immunoglobulin for post- exposure prophylaxis ?","o":["10 IU/kg","20 IU/kg","30 IU/kg","40 1U/kg"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5727, 'PSM', 'Immunization', 'Moderate', 'Preventive_&_Social_Medicine', 338, '{"id":5727,"subject":"PSM","chapter":"Immunization","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":338,"q":"An american wants prophylaxis for Hepatitis-A before coming to India for 10 days. What should be given ?","o":["Two dose of HAV vaccine","immunoglobulin","Antiviral drug prophylaxis","Nothing is required"],"a":1,"e":"Ans. is ''b'' i.e., Immunoglobulin Advice for travellers Some of the recommendation pertain to the following :?","pyqMatches":[{"year":"2014","no":985,"q":"An american wants prophylaxis for Hepatitis-A before coming to India for 10 days. What should be given ?","o":["Two dose of HAV vaccine","immunoglobulin","Antiviral drug prophylaxis","Nothing is required"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5728, 'PSM', 'Maternal & Child Health', 'Easy', 'Preventive_&_Social_Medicine', 339, '{"id":5728,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":339,"q":"Least Neonatal mortality rate is seen in -","o":["Delhi","Tamil Nadu","Karnataka","Maharashtra"],"a":1,"e":"Ans. is ''b'' i.e., Tamil Nadu Overall, least neonatal mortality is recorded in Kerala. However, among the given options Tamilnadu has minimum neonatal mortaltiy.","pyqMatches":[{"year":"2014","no":1006,"q":"Least Neonatal mortality rate is seen in","o":["Delhi","Tamil Nadu","Karnataka","Maharashtra"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5729, 'PSM', 'Communicable Diseases', 'Hard', 'Preventive_&_Social_Medicine', 340, '{"id":5729,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":340,"q":"As per RNTCP guidelines first do in TB suspect case ?","o":["Chest X-ray","Sputum culture","Sputum microscopy","Start short-course chemotherapy"],"a":2,"e":"Ans. is ''c'' i.e., Sputum microscopy Treatment stratgics in RNTCP Under the RNTCP active case finding is not prusued. Case finding is passive. Patients presenting thremselves with symptoms suspicious of tuberculosis are screened through 2 sputum smear examination. Sputum microscopic examination is done in designated RNTCP microscopy centres. It is essential to examine 2 sputum specimens of each patient before a conclusive diagnosis can be made. If only 1 sputum smear is positive, chest x-ray helps in diagnosis. Once the diagnosis is confirmed, treatment is started according to DOTS (Directly observed therapy short term). Patient are expected to collect drugs once a month (not daily) on fixed dates from the nearest treatment centre.","pyqMatches":[{"year":"2014","no":951,"q":"As per RNTCP guidelines first do in TB suspect case ?","o":["Chest X-ray","Sputum culture","Sputum microscopy","Start short-course chemotherapy"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5730, 'PSM', 'Epidemiology', 'Hard', 'Preventive_&_Social_Medicine', 341, '{"id":5730,"subject":"PSM","chapter":"Epidemiology","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":341,"q":"Case control study is an example of ?","o":["Prospective study","Retrospective study","Combined retrospective and prospective study","Study at one point of time"],"a":1,"e":"Ans. is ''b'' i.e., Retrospective study","pyqMatches":[{"year":"2014","no":927,"q":"Case control study is an example of ?","o":["Prospective study","Retrospective study","Combined retrospective and prospective study","Study at one point of time"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5731, 'PSM', 'Epidemiology', 'Hard', 'Preventive_&_Social_Medicine', 342, '{"id":5731,"subject":"PSM","chapter":"Epidemiology","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":342,"q":"Example of case control study (risk factor and disease/outcome) ?","o":["Maternal smoking and congenital malformation","Vaginal adenocarcinoma and intrauterine exposure to DES","Thalidomide exposure and teratogenicity","All of the above"],"a":3,"e":"Ans. is `d'' i.e., All of the above Important risk factors and their outcomes/diseases which have been studied by case-control study are :- i. Cigarette smoking and lung cancer. i. Maternal smoking and congenital malformation. i. Radiation and leukemia. v. OCP used and hepatocellular carcinoma. v. Herpes-simplex and Bells palsy. i. Artificial sweeteners and bladder cancer. i. DES exposure in fetal life and vaginal adenocarcinoma. i. OCP use and thromboembolic disease. x. Thalidomide use in pregnancy and teratogenicity.","pyqMatches":[{"year":"2014","no":928,"q":"Example of case control study (risk factor and disease/outcome) ?","o":["Maternal smoking and congenital malformation","Vaginal adenocarcinoma and intrauterine exposure to DES","Thalidomide exposure and teratogenicity","All of the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5732, 'PSM', 'National Health Programmes', 'Moderate', 'Preventive_&_Social_Medicine', 343, '{"id":5732,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":343,"q":"Not true about propagated epidemics ?","o":["Gradual rise","Gradual fall","Person to person transmission","No secondary wave"],"a":3,"e":"Ans. is ''d'' i.e., No secondary wave","pyqMatches":[{"year":"2014","no":933,"q":"Not true about propagated epidemics ?","o":["Gradual rise","Gradual fall","Person to person transmission","No secondary wave"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5733, 'PSM', 'Nutrition', 'Moderate', 'Preventive_&_Social_Medicine', 344, '{"id":5733,"subject":"PSM","chapter":"Nutrition","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":344,"q":"Pulses contain all except ?","o":["Lysine","Cystein","Arginin","Protein"],"a":1,"e":"Ans. is `b'' i.e., Cystein Pulses Pulses comprise a variety of grams, also known as dhal. Pulses contain 20 to 25% of protein, which is double that found in wheat and three times that found in Rice. In fact, pulses contain more protein than eggs, fish or flesh food. But in regard to quality, pulse proteins are inferior to animal proteins. Pulse proteins are poor in methionine and to a lesser extent of cystein. On the other hand pulse proteins are rich in lysine. Soyabeam is exceptionally rich in protein. Pulses are rich in minerals and B-group vitamins such as riboflavin and thiamin. In dry state pulses do not contain vitamin ''C''. However, Germinating pulses contain higher concentration of vitamin ''C'' and ''B'' vitamins. Fermentation also modifies the nutritive value of pulses in that vitamin content of riboflavin, thiamine and niacin is enhanced. Pulse are called \"poor man''s meat\".","pyqMatches":[{"year":"2014","no":1022,"q":"Pulses contain all except ?","o":["Lysine","Cystein","Arginin","Protein"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5734, 'PSM', 'Immunization', 'Moderate', 'Preventive_&_Social_Medicine', 345, '{"id":5734,"subject":"PSM","chapter":"Immunization","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":345,"q":"True about measles are all except ?","o":["Koplik''s spots is pathognomonic","Source is a case","Infectivity is low","Affect age group 1 to 3 years"],"a":2,"e":"Ans. is ''c'' i.e., Infectivity is low Measles has high infectivity with secondary attack rate of 80%. Other options are correct.","pyqMatches":[{"year":"2014","no":947,"q":"True about measles are all except ?","o":["Koplik''s spots is pathognomonic","Source is a case","Infectivity is low","Affect age group 1 to 3 years"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5735, 'PSM', 'Immunization', 'Moderate', 'Preventive_&_Social_Medicine', 346, '{"id":5735,"subject":"PSM","chapter":"Immunization","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":346,"q":"Which of the following is not a killed vaccine ?","o":["Polio","HBV","HAV","Yellow fever vaccine"],"a":3,"e":"Ans. is ''d'' i.e., Yellow fever vaccine Yellow fever vaccine is a killed vaccine.","pyqMatches":[{"year":"2014","no":911,"q":"Which of the following is not a killed vaccine ?","o":["Polio","HBV","HAV","Yellow fever vaccine"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5736, 'PSM', 'Biostatistics', 'Easy', 'Preventive_&_Social_Medicine', 347, '{"id":5736,"subject":"PSM","chapter":"Biostatistics","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":347,"q":"Most important measure to prevent hospital infection ?","o":["Use of antibiotics","Use of antiseptics","Proper hand washing","Formalin fumigation"],"a":2,"e":"Ans. is ''c'' i.e., Proper hand washing There are following types of modes of transmission of hospital- acquired infections : 1) Contact transmission i. It is the most common and most preventable means of transmission. It is divided into two types - i. Direct contact : It involves contact of body surface to body surface with a physical transfer of microorganisms. Hand contact is most common mode of transmission. i. Indirect contact : It involves body surface contact with a contaminated intermediate object. As hand contact is the most common mode of transmission, the best preventive measure of nosocomial infection is proper hand hygiene. 2) Droplet transmission It occurs when droplet containing microorganisms from an infected person are propelled through the air (e.g. coughing, sneezing) and land on the mouth, eyes or nose of another person. 3) Airborne transmission It results when a droplet containing microorganisms evaporates and remains suspended in air for a long time (this should not be confused with droplet infection, in which transmission is immediate and droplets do not remains suspended in the air). Airborne transmission also occurs by dust particles containing microorganism. 4) Vehicle transmission It refers to transmission of infection by contaminated items such as food, water, medications, devices and equipment.","pyqMatches":[{"year":"2014","no":1066,"q":"Most important measure to prevent hospital infection ?","o":["Use of antibiotics","Use of antiseptics","Proper hand washing","Formalin fumigation"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5737, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 348, '{"id":5737,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":348,"q":"Absolute contraindication for insertion of IUD","o":["History of PID","Congenital uterine malformation","Undiagnosed vaginal bleeding","Purulent cervical discharge"],"a":2,"e":"Ans. is ''c'' i.e., Undiagnosed vaginal bleeding Contraindications ABSOLUTE: a. Suspected pregnancy b. Pelvic inflammatory disease c. Vaginal bleeding of undiagnosed etiology d. Cancer of the cervix, uterus or adnexa and other pelvic tumours e. Previous ectopic pregnancy RELATIVE : a. Anaemia b. Menorrhagia c. History of PID since last pregnancy d. Purulent cervical discharge e. Distortions of the uterine cavity due to congenital malformations, fibroid f. Unmotivated person","pyqMatches":[{"year":"2014","no":999,"q":"Absolute contraindication for insertion of IUD","o":["History of PID","Congenital uterine malformation","Undiagnosed vaginal bleeding","Purulent cervical discharge"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5738, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 349, '{"id":5738,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":349,"q":"Rabies vaccine was first developed by ?","o":["Robert Koch","Louis Pasteur","Edward Jenner","Loeffler"],"a":1,"e":"Ans. is ''b'' i.e., Louis pasteur Louis pasteur is associated with : Development of live vaccine (first was anthrax) Development of vaccine for rabies (hydrophobia) Introduction of technique of sterilization Disprove the theory of spontaneous generation (abiogenesis) Established the different growth need of different bacteria (helped in complex media) Coined the term vaccine","pyqMatches":[{"year":"2014","no":991,"q":"Rabies vaccine was first developed by ?","o":["Robert Koch","Louis Pasteur","Edward Jenner","Loeffler"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5739, 'PSM', 'Biostatistics', 'Moderate', 'Preventive_&_Social_Medicine', 350, '{"id":5739,"subject":"PSM","chapter":"Biostatistics","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":350,"q":"Human development index includes all except ?","o":["Longevity","Knowledge","Income","Literacy rate"],"a":3,"e":"Ans. is ''d'' i.e., Literacy rate Human development index HDI is a composite index combining indicators representing three dimensions. i. Longevity : Life expectancy at birth. i. Knowledge : Mean years of schooling (gross enrolment ratio) and expected year of schooling. (In older editions of Park, i.e., 21st/e and older than that, it was adult literacy rate instead of expected year schooling). i. Income : GNI Per Capita (In older editions of Park, it was GDP per capita instead of GNI per capita).","pyqMatches":[{"year":"2014","no":898,"q":"Human development index includes all except ?","o":["Longevity","Knowledge","Income","Literacy rate"],"a":3,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":809,"q":"Human development index includes all except ?","o":["Longevity","Knowledge","Income","Literacy rate"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5740, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 351, '{"id":5740,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":351,"q":"True about influenza ?","o":["Incubation period 2-3 weeks","Most infections are subclinical","Type-A virus causes Reye''s syndrome","Pandemic is caused by Type-B virus"],"a":1,"e":"Ans. is ''b'' i.e., Most infections are subclinical Influenza Influenza virus a RNA virus, belongs to orthomyxovirus. There are three viral subtypes : i) Type A (causes all pandemics and most epidemics); type B; and type C (not circulating currently). Currently the influenza viruses circulating in the world are : 111 N, of type A (causes swine flu); H2 N2 of type A; H3 N2 of type A ; H5 NI of type A (causes birdflu or avian influenza); H7 N9 of type A (caused epidemic of avian influenza in China in 2013); and type B. Influenza shows cyclic trend with epidemic occuring every 2-3 years in case of influenza - A and every 4-7 years in case of influenza-B. Pandemics are caused by only influenza - A every 10-15 years. Influenza affects all ages and both sexes. Source of infection of influenza is a clinical case or subclinical case. Major reservoir of influenza virus exists in animal and birds. Incubation period is 18-72 hours. Most of the infections are subclinical. Clinical cases present with cough, fever, myalgia and headache.","pyqMatches":[{"year":"2014","no":992,"q":"True about influenza ?","o":["Incubation period 2-3 weeks","Most infections are subclinical","Type-A virus causes Reye''s syndrome","Pandemic is caused by Type-B virus"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5741, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 352, '{"id":5741,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":352,"q":"Aedes aegypti index near ports should be less than -","o":["1%","5%","8%","10%"],"a":0,"e":"Ans. is ''a'' i.e., 1% For the surveillance of Aedes mosquitoes, the WHO uses an index known as Aedes aegypti index. This is a house index and is defined as \"The percentage of houses and their premises, in a limited well-defined area, showing actual breeding of Aedes aegypti larvae\". This index should not be more than 1% in towns and seaports in endeic areas to ensure freedom from yellow fever. International health regulation for yellow fever Measures designed to restrict the spread of yellow fever are specified in the \"International health regulation\" of WHO. These are implemented by the Govt of India through stringent aerial and maritime traffic regulations. Broadly these comprise : - i) Travellers All travellers (including infants) exposed to yellow fever or passing through endemic zones of yellow fever must posses a valid international certificate fo vaccination against yellow fever before they are allowed to enter yellow fever receptive areas like India. The validity of the certificate begins 10 days after the date of vaccination and extends up to 10 years. Revaccination performed before the end of the validity of certicicate renders the certificate valid for a further period of 10 years starting on the day of revaccination. If no such certificate fo vaccination is available, the travellar is placed on quarantine for 6 days from the date of leaving an infected area. ii) Mosquitoes The aircraft and ships arriving from endemic areas are subjected to aerosol spraying with prescribed insecticides. Airports and Seaports are kept free from the breeding of insect vectors over an area extending at least 400 metres around their perimeters. The \"aedes aegypti index\" is kept below 1.","pyqMatches":[{"year":"2014","no":993,"q":"Aedes aegypti index near ports should be less than","o":["1%","5%","8%","10%"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5742, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 353, '{"id":5742,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":353,"q":"Multifactorial causation of disease theory was proposed by","o":["Louis Pasteur","Pettenkofer","Robert koch","Aristotle"],"a":1,"e":"Ans. is ''b'' i.e., Pettenkofer Multifactorial causation of disease theory was proposed by Pettenkofer.","pyqMatches":[{"year":"2014","no":917,"q":"Multifactorial causation of disease theory was proposed by","o":["Louis Pasteur","Pettenkofer","Robert koch","Aristotle"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5743, 'PSM', 'Miscellaneous', 'Hard', 'Preventive_&_Social_Medicine', 354, '{"id":5743,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":354,"q":"Major sign for AIDS surveillance in WHO case definition ?","o":["> 10% weight loss","Cough > 1 month","Generalized lymphadenopathy","Disseminated Herpes"],"a":0,"e":"Ans. is ''a'' i.e., > 10% weight loss WHO case definition for AIDS surveillance For the purpose of AIDS surveillance an adult or adolescent (six years of age) is considered to have AIDS if at least 2 of the following major signs are present in combination with one minor sign. Major Signs Weight loss > 10 % of body weight Chronic diarrhoea for more than 1 month Prolonged fever for more than 1 month Minor signs Persistent cough for more than one month Generalized pruritic dermatitis History of herpes zoster Chronic progressive or disseminated herpes simplex infection Generalized lymphadenopathy Oropharyngeal Candidiasis. Expanded WHO case definition for AIDS surveillance For the purpose of surveillance on adult or adolescent (>12 years of age) is considered to have AIDS if a test for HIV antibody gives a positive result and one or more of the following conditions are present : >10% body weight loss or cachexia, with diarrhoea or fever or both, for at least 1 month, not known to be due to a condition unrelated to HIV infection.","pyqMatches":[{"year":"2013","no":1482,"q":"Major sign for AIDS surveillance in WHO case definition ?","o":["> 10% weight loss","Cough > 1 month","Generalized lymphadenopathy","Disseminated Herpes"],"a":0,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":988,"q":"Major sign for AIDS surveillance in WHO case definition ?","o":["> 10% weight loss","Cough > 1 month","Generalized lymphadenopathy","Disseminated Herpes"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5744, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 355, '{"id":5744,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":355,"q":"Not a copper containing IUD ?","o":["CuT-200","Nova -T","Multiload-250","LNG-20"],"a":3,"e":"Ans. is `d i.e., LNG-20 LNG-20 is third generation IUD which does not contain cooper. Other three options are 2\"d generation (copper containing) IUDs.","pyqMatches":[{"year":"2014","no":998,"q":"Not a copper containing IUD ?","o":["CuT-200","Nova -T","Multiload-250","LNG-20"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5745, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 356, '{"id":5745,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":356,"q":"Current MMR in India is (per 1 lac live births) ?","o":["400","280","180","110"],"a":2,"e":"Ans. is ''c'' i.e., 180","pyqMatches":[{"year":"2014","no":1008,"q":"Current MMR in India is (per 1 lac live births) ?","o":["400","280","180","110"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5746, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 357, '{"id":5746,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":357,"q":"Not a baby friendly hospital recommendation ?","o":["Breast feeding with half-hour of birth","Breast feeding on demand","Use of artificial teats when required","No oral feed other than breast milk"],"a":2,"e":"Ans. is ''c'' i.e., Use of artificial teats when required Baby friendly hospital initiatives Baby friendly hospital initiative (BFHI) was launched for promotion, protection and support of breastfeeding. It was launched by WHO and UNICEF. BFHI has listed following ten steps, which the hospital must fulfill.","pyqMatches":[{"year":"2014","no":1010,"q":"Not a baby friendly hospital recommendation ?","o":["Breast feeding with half-hour of birth","Breast feeding on demand","Use of artificial teats when required","No oral feed other than breast milk"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5747, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 358, '{"id":5747,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":358,"q":"Goal of NPCB was to reduce prevalence of blindness to ?","o":["< 0.3% by 2000","< 0.3% by 2005","< 0.5% by 2010","< 0.5% by 2015"],"a":0,"e":"Ans. is ''a'' i.e., < 0.3% by 2000 NATIONAL PROGRAMME FOR CONTROL OF BLINDNESS (NPCB) The national program for Control of Blindness (NPCB) has been re-designated recently as the National Programme for Control of Blindness and Visual Impairment Launched in 1976 Its objective is to reduce the prevalence of eye diseases in general, and the prevalence of blindness from 1.40% to 0.3% by 2000 AD. Apex Centre (National Eye Institute) is Dr. Rajendra Prasad Centre for Ophthalmic Sciences (New Delhi, AIIMS). Revised strategies of NPCB a) To make NPCB more comprehensive by strengthening services for other causes of blindness like corneal blindness(requiring transplantation of donated eyes), refractive errors in school-going children, improving follow-up services of cataract operated persons and treating other causes of blindness like glaucoma; To shift from the eye camp approach to a fixed facility surgical approach and from conventional surgery to IOL implantation for better quality of post- operative vision in operated patients. b) To expand the World Bank project activities like construction of dedicated eye operation theatres, eye wards at the district level, training of eye surgeons in modern cataract surgery and other eye surgeries and supply of ophthalmic equipment, etc. to the whole country. c) To strengthen the participation of Voluntary Organizations in the program and to earmark geographic areas to NGOs and Government Hospitals to avoid duplication of effort and improve the performance of Government Units like Medical Colleges, District Hospitals, Sub Divisional Hospitals, Community Health Centres, Primary Health Centres. d) To enhance the coverage of eye care services in tribal and other under-served areas through the identification of bilateral blind patients, preparation of village-wise blind register and giving preference to bilateral blind patients for cataract surgery.","pyqMatches":[{"year":"2014","no":1057,"q":"Goal of NPCB was to reduce prevalence of blindness to ?","o":["< 0.3% by 2000","< 0.3% by 2005","< 0.5% by 2010","< 0.5% by 2015"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5748, 'PSM', 'National Health Programmes', 'Moderate', 'Preventive_&_Social_Medicine', 359, '{"id":5748,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":359,"q":"True about critical path method are all except","o":["Network analysis","Longest path","Cannot be delayed","Shortest path"],"a":3,"e":"Ans. is ''d'' i.e., Shortest path Network analysis A network analysis is a graphic of all events and activities to be completed in order to reach an end objective. It brings greater discipline in planning. The two common types of network technique are : a) Programme Evaluation and Review technique (PERT) b) Critical Path method (CPM) Programme Evaluation and Review technique (PERT) PERT is a management technique which makes possible more detailed planing and more comprehensive supervision. PERT is method to analyze the involved tasks in completing a given project, especially the time needed to complete each task, and identifying the minimum time needed to complete the total project. The essence of PERT is to construct an arrow diagram, which represents the logical sequence in which events must take place. It is possible with such a diagram to calculate the time by which each activity must be completed, and to identify those activities that are critical. Critical path method (CPM) The longest path of the network is called the critical path. Critical path method determines the activities of a project which are critical and are given longest path. Other activities are total float, i.e. they can be delayed without making the project longer. Any delay in activity on the critical path results in delay of the project. o In the above figure, the longest path is from equipment ordered to equipment installed. That means, this is the critical path and installating of equiment is the most critical step (taking 10 months). o Other activities are total float, i.e. they can be delayed for sometimes without delaying the project.","pyqMatches":[{"year":"2014","no":1067,"q":"True about critical path method are all except","o":["Network analysis","Longest path","Cannot be delayed","Shortest path"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5749, 'PSM', 'Concept of Health & Disease', 'Hard', 'Preventive_&_Social_Medicine', 360, '{"id":5749,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":360,"q":"Total number of TB cases in a community of 6000 population 150. Number death due to TB are 30. What is the TB specific death rate (per 1000 population) ?","o":["20","10","5","0-5"],"a":3,"e":"Ans. is ''d'' i.e., 0-5 Specific death rates When analysis is planned to throw light on etiology, it is essential to use specific death rates. The specified death rate helps identify particular ''at risk'' group (s) for prevention. It also permits comparison between different causes within same population. The specific death rates may be ? a) Cause or disease specific, e.g. TB, cancer, accident. b) Related to specific groups - e.g. age specific, sex specific.","pyqMatches":[{"year":"2014","no":934,"q":"Total number of TB cases in a community of 6000 population 150. Number death due to TB are 30. What is the TB specific death rate (per 1000 population) ?","o":["20","10","5","0-5"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5750, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 361, '{"id":5750,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":361,"q":"Average daily breast milk output during first 6 months ?","o":["100-200 ml","200-300 ml","300-400 ml","500-600 ml"],"a":3,"e":"Ans. is ''d'' i.e., 500-600 ml Under normal conditions, Indian mothers secrete 450 - 600 ml of milk daily Maximum output of milk is at 5 - 6 months (730 ml/ day) after which the output constantly declines. At 12 months the output is 525 ml/day -Park p. 455","pyqMatches":[{"year":"2014","no":1011,"q":"Average daily breast milk output during first 6 months ?","o":["100-200 ml","200-300 ml","300-400 ml","500-600 ml"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5751, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 362, '{"id":5751,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":362,"q":"Which stage of larva of housefly is voracious feeder -","o":["1","2","3","4"],"a":0,"e":"Ans. is ''a'' i.e., 1 The larva of housefly (maggot) moults twice, i.e. there are three instar stages. The first instar larva is a varacious feeder, feeding mainly on decomposing liquid organic matter.","pyqMatches":[{"year":"2014","no":1046,"q":"Which stage of larva of housefly is voracious feeder","o":["1","2","3","4"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5752, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 363, '{"id":5752,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":363,"q":"True about carriers ?","o":["Infection with clinical symptoms","Serves as source of infection","More infectious than cases","Less dangerous than cases"],"a":1,"e":"Ans. is ''b'' i.e., Serves as source of infection A carrier is defined as \"an infected person or animal that harbours a specific infectious agent in the absence of clinical disease and serves as a potential source of infection\". As a rule carriers are less infectious than cases, but epidemiologically they are more dangerous than cases because they escape recognition, and continuing as they do to live a normal life among the population or comunity, they readily infect the susceptible individuals over a wider area and longer period of time.","pyqMatches":[{"year":"2014","no":913,"q":"True about carriers ?","o":["Infection with clinical symptoms","Serves as source of infection","More infectious than cases","Less dangerous than cases"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5753, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 364, '{"id":5753,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":364,"q":"Typhoid oral vaccine is given ?","o":["1, 3, 5 days","1, 2, 3 days","1, 2, 4 days","1, 7, 14 days"],"a":0,"e":"Ans. is ''a'' i.e., 1, 3, 5 days ANTI-TYPHOID VACCINES The old parenteral killed whole-cell vaccine was effective but produced strong side-effects. So, they are not used now. Two safe and effective vaccines are now licensed and available : - 1.The Vi polysachharide vaccine","pyqMatches":[{"year":"2014","no":989,"q":"Typhoid oral vaccine is given ?","o":["1, 3, 5 days","1, 2, 3 days","1, 2, 4 days","1, 7, 14 days"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5754, 'PSM', 'Immunization', 'Moderate', 'Preventive_&_Social_Medicine', 365, '{"id":5754,"subject":"PSM","chapter":"Immunization","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":365,"q":"True about typhoid vaccines are all except ?","o":["Vi polysaccharide vaccine is given in single dose","Storage temperature is +2 to +8°C","Typhoral vaccine is given in 3 doses","Typhoral vaccine cannot be given with other live vaccines"],"a":3,"e":"Ans. is ''d'' i.e., Typhoral vaccine cannot be given with other live vaccines","pyqMatches":[{"year":"2014","no":990,"q":"True about typhoid vaccines are all except ?","o":["Vi polysaccharide vaccine is given in single dose","Storage temperature is +2 to +8°C","Typhoral vaccine is given in 3 doses","Typhoral vaccine cannot be given with other live vaccines"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5755, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 366, '{"id":5755,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":366,"q":"Transmission of microfilaria in mosquito is ?","o":["Cyclo-developmental","Cyclo-propagative","Propagative","Cyclical"],"a":0,"e":"Ans. is ''a'' i.e., Cyclodevelopmental In vector born diseases, an arthropod or any living carrier (e.g., snail) acts as a vector and transports an infectious agent to a susceptible individual. Transmission by a vector may be of following types : ? A. Mechanical transmission The infectious agent is mechanically transported by vector, e.g., through souling of feet of flying arthropod. There is no development or multiplication of infectious agent within the vector. B. Biological transmission The infectious agent undergoes replication (change in number) or development (change in form) or both in vector. So, inectious agent requires an incubation period (extrinsic incubation period) before vector can transmit it to host. This type of transmission is of three types : - i) Propagative Agent undergoes multiplication (change in number) in the vector. There is no development → No change in form. Example → Plague bacilli in rate fleas. ii) Cyclo-developmental Agent undergoes only development → Change in form. No multiplication → No change in number. Example → Micorfilaria in mosquito. iii) Cyclo-propagative Agent undergoes both development and multiplication → Change in form and number. Example → Malaria parasite (plasmodium sp.) in mosquito.","pyqMatches":[{"year":"2014","no":916,"q":"Transmission of microfilaria in mosquito is ?","o":["Cyclo-developmental","Cyclo-propagative","Propagative","Cyclical"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5756, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 367, '{"id":5756,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":367,"q":"Denominator in perinatal mortality rate ?","o":["Total births","Total live births","Live births + Still birth","Total number of newborns"],"a":1,"e":"Ans. is ''b'' i.e., Total live births","pyqMatches":[{"year":"2014","no":1007,"q":"Denominator in perinatal mortality rate ?","o":["Total births","Total live births","Live births + Still birth","Total number of newborns"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5757, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 368, '{"id":5757,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":368,"q":"Iron content of MALA-D ?","o":["10 mg","19-5 mg","29.5 mg","40 mg"],"a":1,"e":"Ans. is ''b'' i.e., 19-5 mg MALA-D contains - i) 30 ug (0.03 mg) of ethinyl estradiol. ii) 0.15 mg of desogestrel (D-norgestrel). Each brown coloured film coated tablet contains 60 mg ferrous fumarate equivalent to ferrous iron 19.5 mg.","pyqMatches":[{"year":"2014","no":1002,"q":"Iron content of MALA-D ?","o":["10 mg","19-5 mg","29.5 mg","40 mg"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5758, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 369, '{"id":5758,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":369,"q":"Protein requirement in adult male ?","o":["0.5 gm/kg/day","1 gm/kg/day","1.5 gm/kg/day","2 gm/kg/day"],"a":1,"e":"Ans. is ''b'' i.e., 1 gm/kg/day","pyqMatches":[{"year":"2014","no":1032,"q":"Protein requirement in adult male ?","o":["0.5 gm/kg/day","1 gm/kg/day","1.5 gm/kg/day","2 gm/kg/day"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5759, 'PSM', 'Demography & Family Planning', 'Moderate', 'Preventive_&_Social_Medicine', 370, '{"id":5759,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":370,"q":"People are arranged alphabetically by their names and then every 3rd person is chosen for study. The type of sampling is ?","o":["Stratified random","Systematic random","Simple random","None of the above"],"a":1,"e":"Ans. is ''b'' i.e., Systematic random Simple random sampling Simple random sampling, also, known as ''unrestricted random sampling''; is applicable for small, homogenous, readily available population and is used in clinical trials. In simple random sampling each individual is chosen randomly and entirely by chance. So, each individual has the same probability of being chosen at any stage during the sampling process. For example Let us assume you had a school with 1000 students, divided equally into boys and girls, and you wanted to select 100 of them for further study. You might put all their names in a bucket and then pull 100 names out. Not only does each person have an equal chance of being selected, we can also easily calculate the probaility of","pyqMatches":[{"year":"2014","no":1077,"q":"People are arranged alphabetically by their names and then every 3rd person is chosen for study. The type of sampling is ?","o":["Stratified random","Systematic random","Simple random","None of the above"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5760, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 371, '{"id":5760,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":371,"q":"Protein content in F-75 milk formula ?","o":["0.5 gm per 100 ml","0-9 gm per 100 ml","1-5 gm per 100 ml","2.0 gm per 100 ml"],"a":1,"e":"Ans. is `b'' i.e., 0.9 gm per 100 ml","pyqMatches":[{"year":"2014","no":1012,"q":"Protein content in F-75 milk formula ?","o":["0.5 gm per 100 ml","0-9 gm per 100 ml","1-5 gm per 100 ml","2.0 gm per 100 ml"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5761, 'PSM', 'Epidemiology', 'Moderate', 'Preventive_&_Social_Medicine', 372, '{"id":5761,"subject":"PSM","chapter":"Epidemiology","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":372,"q":"Measles elimination criteria are all except ?","o":["Absence of endemic measles","For more than 12 months","Incidence < 1 per 1 lac population","Transmission at low level"],"a":3,"e":"Ans. is ''d'' i.e., Transmission at low level WHO defines elimination of measles as the absence of endemic measles for a period of 12 months in the presence of adequate surveillance. One indicater of measles elimination is a sustained measles incidence < 1/100, 000 population. In 2005, the World Health Assembly set a goal of achieving a 90% reduction in global measles mortality by 2010 as compared with level in 2000.","pyqMatches":[{"year":"2014","no":946,"q":"Measles elimination criteria are all except ?","o":["Absence of endemic measles","For more than 12 months","Incidence < 1 per 1 lac population","Transmission at low level"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5762, 'PSM', 'Communicable Diseases', 'Easy', 'Preventive_&_Social_Medicine', 373, '{"id":5762,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":373,"q":"In Revised National Tuberculosis Control programme the silent features are to achieve ?","o":["Cure rate 85% & diagnosis 85%","Cure rate 85% & diagnosis rate 70%","Cure rate 80% & diagnosis 85%","Cure rate 80% & diagnosis rate 80%"],"a":1,"e":"Ans. is ''b'' i.e., Cure rate 85% & diagnosis rate 70% Revised National Tuberculosis Control Programme The Government of India, WHO and World Bank together reviewed the NTP in the year 1992. Based on the findings a revised strategy for NTP was evolved. The salient features of this strategy are : - Achievement of at least 85 percent cure rate of infectious cases through supervised Short Course Chemotherapy involving peripheral health functionaries. Augmentation of case finding activities through quality sputum microscopy to detect at least 70 percent estimated cases; and Involvement of NG0s; Information, Education and communication and improved operational research. For a \"TB - free India\" following objectives have been proposed : i. To achieve 90% notification rate i. To achieve 90% success rate for all new cases and 85% for retreatment cases i. To significantly improve the successful outcomes of treatment of drug resistant TB cases v. To decrease morbidity and mortality of HIV associated TB v. To improve outcomes of TB care in the private sector","pyqMatches":[{"year":"2014","no":958,"q":"In Revised National Tuberculosis Control programme the silent features are to achieve ?","o":["Cure rate 85% & diagnosis 85%","Cure rate 85% & diagnosis rate 70%","Cure rate 80% & diagnosis 85%","Cure rate 80% & diagnosis rate 80%"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5763, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 374, '{"id":5763,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":374,"q":"Proportional mortality rate is ?","o":["Number of death due to a particular cause","Number of death during that year","Number of death in one month","None"],"a":0,"e":"Ans. is ''a'' i.e., Number of death due to a particular cause Proportional mortality rate (ratio) Proportional mortality rate measures the proportion of total death due to specific cause or proportion of deaths in a particular age group. It is defined as \"number of deaths due to a particular cause (or in specific age group) per 100 total deaths\". It is the ''simplest measure of estimating the burden of disears'' in the community. It is a useful ''health Status indicator''; indicates magnitude of preventable mortality. It is used when population data is not available. It does not indicate the risk of members of population contracting or dying from the disease.","pyqMatches":[{"year":"2012","no":786,"q":"Proportional mortality rate is ?","o":["Number of death due to a particular cause","Number of death during that year","Number of death in one month","None"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":922,"q":"Proportional mortality rate is ?","o":["Number of death due to a particular cause","Number of death during that year","Number of death in one month","None"],"a":0,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":825,"q":"Proportional mortality rate is ?","o":["Number of death due to a particular cause","Number of death during that year","Number of death in one month","None"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2012","2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5764, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 375, '{"id":5764,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":375,"q":"Best indicator for burden of disease ?","o":["Incidence","Crude death rate","Cause specific death rate","Proportional mortality rate"],"a":3,"e":"Ans. is ''d'' i.e., Proportional mortality rate","pyqMatches":[{"year":"2014","no":923,"q":"Best indicator for burden of disease ?","o":["Incidence","Crude death rate","Cause specific death rate","Proportional mortality rate"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5765, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 376, '{"id":5765,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":376,"q":"Pearls index?","o":["Per 100 woman years","Per 10 woman years","Per 1000 woman years","Per 50 woman years"],"a":0,"e":"Ans. is ''a'' i.e., Per 100 woman years","pyqMatches":[{"year":"2013","no":928,"q":"Pearls index?","o":["Per 100 woman years","Per 10 woman years","Per 1000 woman years","Per 50 woman years"],"a":0,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":1001,"q":"Pearls index?","o":["Per 100 woman years","Per 10 woman years","Per 1000 woman years","Per 50 woman years"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5766, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 377, '{"id":5766,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":377,"q":"Neurolathyrism is due to ?","o":["Argemone oil","Jhunjhunia","Khesari dal","None"],"a":2,"e":"Ans. is ''c'' i.e., Khesari dal","pyqMatches":[{"year":"2014","no":1018,"q":"Neurolathyrism is due to ?","o":["Argemone oil","Jhunjhunia","Khesari dal","None"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5767, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 378, '{"id":5767,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":378,"q":"NFHS-3 was conducted in ?","o":["1992-93","1998-99","2005-06","2009-10"],"a":2,"e":"Ans. is ''c'' i.e., 2005-06 National family health survey (NFHS) Is a large-scale, multi-round survey conducted in a representative sample of households throughout India. 3 rounds of the survey have been conducted till date.","pyqMatches":[{"year":"2014","no":1068,"q":"NFHS-3 was conducted in ?","o":["1992-93","1998-99","2005-06","2009-10"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5768, 'PSM', 'Health Management & Services', 'Moderate', 'Preventive_&_Social_Medicine', 379, '{"id":5768,"subject":"PSM","chapter":"Health Management & Services","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":379,"q":"Not true about Alma-Ata declaration ?","o":["Was held in 1978","Community participation","Health for all","Best approach for health for all is basic health care"],"a":3,"e":"Ans. is ''d'' i.e., Best approach for health for al is basic health care The Declaration of Alma-Ata (1978) by emphasizing the need for \"individual and community participation\" gave a new meaning and direction to the practice of health education. In 1978, the Alma-Ata International conference on Primary Health Care reaffirmed Health for All as the major social goal fo governments, and stated that the best approach to achieve the goal of HFA is by providing primary health care, especially to the vast majority of underserved rural people and urban poor. It was envisaged that by the year 2000, at least essential health care should be accessible to all individuals and families in an acceptable and affordable way, with their full participation. The Alma-Ata Conference called on all governments to formulate national policies, strategies and plans of action to launch and sustain primary health care as part of a national health system. It is left to each country to develop its norms and indicators for providing primary health care according to its own circumstances.","pyqMatches":[{"year":"2014","no":903,"q":"Not true about Alma-Ata declaration ?","o":["Was held in 1978","Community participation","Health for all","Best approach for health for all is basic health care"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5769, 'PSM', 'Biostatistics', 'Easy', 'Preventive_&_Social_Medicine', 380, '{"id":5769,"subject":"PSM","chapter":"Biostatistics","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":380,"q":"Level of Hardness if the value is 50-150 mg/L ?","o":["Soft water","Moderately hard water","Hard water","Very hard water"],"a":1,"e":"Ans. is ''b'' i.e., Moterately hard water","pyqMatches":[{"year":"2014","no":1050,"q":"Level of Hardness if the value is 50-150 mg/L ?","o":["Soft water","Moderately hard water","Hard water","Very hard water"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5770, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 381, '{"id":5770,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":381,"q":"Mental Health Act was passed in ?","o":["1982","1987","1971","1950"],"a":1,"e":"Ans. is ''b'' i.e., 1987","pyqMatches":[{"year":"2013","no":989,"q":"Mental Health Act was passed in ?","o":["1982","1987","1971","1950"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5771, 'PSM', 'Health Management & Services', 'Moderate', 'Preventive_&_Social_Medicine', 382, '{"id":5771,"subject":"PSM","chapter":"Health Management & Services","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":382,"q":"All are components of ''Health for all'' except ?","o":["Adequacy","Acceptibility","Equity","Resource allocation"],"a":3,"e":"Ans. is ''d'' i.e., Resource allocation Health for All Health for all'' is defined as \"attainment of a level of health that will enable every individual to lead a socially and economically productive life\". The fundamental principle of HFA strategy is equity, that is, an equal, health status for people and countries, ensured by an equitable distribution of health resources. The best approach to achieve the goal for HFA is by providing primary health care. At least essential health care should be accessible to all individuals in an acceptable and affordable way. The seven principles of health for all outline by WHO i. The right to health i. Health promotion i. Equity in health ( equitable distribution) v. Primary health care v. Community participation i. Intersectoral cooporation i. Intersectoral collaboration Primary health care (PHC) is one of the most important component. The basic requirments for PHC are (8A''s and 3C''s) - Appropriateness Availability Adequacy Accessibility Acceptibility Affordability Assessability Accountability Completeness Comprehensiveness Continuity","pyqMatches":[{"year":"2014","no":1069,"q":"All are components of ''Health for all'' except ?","o":["Adequacy","Acceptibility","Equity","Resource allocation"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5772, 'PSM', 'Epidemiology', 'Moderate', 'Preventive_&_Social_Medicine', 383, '{"id":5772,"subject":"PSM","chapter":"Epidemiology","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":383,"q":"Randomized study is done in people who are volunteer for the study. Which type of bias may occur ?","o":["Hawthorne bias","Berkesonian bias","Selection bias","Attention bias"],"a":2,"e":"Ans. is ''c'' i.e., Selection bias","pyqMatches":[{"year":"2014","no":932,"q":"Randomized study is done in people who are volunteer for the study. Which type of bias may occur ?","o":["Hawthorne bias","Berkesonian bias","Selection bias","Attention bias"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5773, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 384, '{"id":5773,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":384,"q":"In a child who is allergic to egg, which vaccine should be avoided ?","o":["Measles","MMR","Influenza","DPT"],"a":2,"e":"Ans. is ''c'' i.e., Influenza","pyqMatches":[{"year":"2014","no":904,"q":"In a child who is allergic to egg, which vaccine should be avoided ?","o":["Measles","MMR","Influenza","DPT"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5774, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 385, '{"id":5774,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":385,"q":"\"3 by 5\" initiative in AIDS control programme is ?","o":["Providing 3 million people treatment by end of 2005","Providing treatment to 3 out of 5 patients","Reducing incidence of AIDS by 3% by 2005","All of the above"],"a":0,"e":"Ans. is ''a'' i.e., Providing 3 million people treatment by end of 2005 3 by 5 target On 1st December 2003, WHO and UNAIDS announced a detailed plan to reach the \"3 by 5 target\" of providing antiretroviral treatment (ART) to three million people living with HIV/AIDS in the developing countries by the end of 2005. Ultimate goal of this strategy is to provide universal access to ART to anyone who needs it. It has five Pillars (focus areas of concerns) :?","pyqMatches":[{"year":"2014","no":1070,"q":"\"3 by 5\" initiative in AIDS control programme is ?","o":["Providing 3 million people treatment by end of 2005","Providing treatment to 3 out of 5 patients","Reducing incidence of AIDS by 3% by 2005","All of the above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5775, 'PSM', 'Maternal & Child Health', 'Easy', 'Preventive_&_Social_Medicine', 386, '{"id":5775,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":386,"q":"Index of operational efficiency of Malaria ?","o":["API","ABER","Infant parasite rate","Spleen rate"],"a":1,"e":"Ans. is ''b'' i.e., ABER Annual blood examination rate (ABER) is an index of operational efficiency.","pyqMatches":[{"year":"2014","no":979,"q":"Index of operational efficiency of Malaria ?","o":["API","ABER","Infant parasite rate","Spleen rate"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5776, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 387, '{"id":5776,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":387,"q":"Impact indicator for ASHA ?","o":["Number of ASHA trained","Infant mortality rate","% of institutional deliveries","% of JSY claims made to ASHA"],"a":1,"e":"Ans. is ''b'' i.e., Infant mortality rate Monitoring and Evaluation of ASHA''s work Government of India has set up following indicators for monitoring ASHA (41). 1.Process Indicators a) Number of ASHAs selected by due process b) Number of ASHAs trained; and c) % of ASHAs attending review meeting after one year 2.Outcome Indicators a) % of newborn who were weighed and families counseled. b) % of children with diarrhoea who received ORS. c) % of deliveries with skilled assistance. d) % of institutional deliveries. e) % of JSY claims made to ASHA f) % of completely immunized in 12 to 23 months age group. g) % of unmet need for spacing contraception among BPL. h) % of fever cases who received chloroquine with in first week in a malaria endemic area. 3.Impact Indicators a) IMR b) Child malnutrition rates c) Number of cases of TB/leprosy detected as compared to previous year year.","pyqMatches":[{"year":"2014","no":1071,"q":"Impact indicator for ASHA ?","o":["Number of ASHA trained","Infant mortality rate","% of institutional deliveries","% of JSY claims made to ASHA"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5777, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 388, '{"id":5777,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":388,"q":"Iodized salt is given to prevent goitre to ?","o":["All population","Population of Himalayan belt","Population of Hilly areas","Population of village area"],"a":0,"e":"Ans. is ''a'' i.e., All population In India, the entire population is prone to IDD due to deficiency of iodine in the soil of the subcontinent consequently the food derived from it. The iodization of salt is now the most widely used prophylactic public health measure against endemic goitre. In India the level of iodization is fixed under the Prevention of food adulteration (PFA) act and is not less than 30 ppm at the production point and not less than 15 ppm of iodine at the consumer level.","pyqMatches":[{"year":"2014","no":1031,"q":"Iodized salt is given to prevent goitre to ?","o":["All population","Population of Himalayan belt","Population of Hilly areas","Population of village area"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5778, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 389, '{"id":5778,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":389,"q":"Ujjwala scheme does not include ?","o":["Rescue","Rehabilitation","Reintegration","Reward"],"a":3,"e":"Ans. is `d'' i.e., Reward","pyqMatches":[{"year":"2014","no":1072,"q":"Ujjwala scheme does not include ?","o":["Rescue","Rehabilitation","Reintegration","Reward"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5779, 'PSM', 'Maternal & Child Health', 'Easy', 'Preventive_&_Social_Medicine', 390, '{"id":5779,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":390,"q":"Positive mortality indicator is ?","o":["IMR","Child mortality rate","MMR","Life expectancy"],"a":3,"e":"Ans. is ''d'' i.e., Life expectancy Mortality indicators These are :? i. Crude death rate i. Maternal mortality rate i. Expectation of life (life expectancy) v. Disease specific mortality rate v. Infant mortality rate i. Age specific death rate i. Child mortality rate i. Adult mortality rate x. Under-5 proportional mortality rate x. Years of potential life lost Among these only life expectancy is a positive mortality indicator, i.e. increase life expectancy means improvement in health. All other are ''negative'' health indicators, i.e. increase value of these indicators implies poor health of community.","pyqMatches":[{"year":"2014","no":942,"q":"Positive mortality indicator is ?","o":["IMR","Child mortality rate","MMR","Life expectancy"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5780, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 391, '{"id":5780,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":391,"q":"Most common manifestation of mumps in adult males -","o":["Aseptic meningitis","Encephalitis","Orchitis","Sinusitis"],"a":2,"e":"Ans. is ''c'' i.e., Orchitis Orchitis is the most common manifestation of mumps among postpubertal males.","pyqMatches":[{"year":"2014","no":968,"q":"Most common manifestation of mumps in adult males","o":["Aseptic meningitis","Encephalitis","Orchitis","Sinusitis"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5781, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 392, '{"id":5781,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":392,"q":"Incineration is done for waste category ?","o":["Category 7","Category 9","Category 6","Category 5"],"a":2,"e":"Ans. is ''c'' i.e., Category 6","pyqMatches":[{"year":"2014","no":1053,"q":"Incineration is done for waste category ?","o":["Category 7","Category 9","Category 6","Category 5"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5782, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 393, '{"id":5782,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":393,"q":"What is the route of administration of avian influenza vaccine?","o":["Intranasal","Intramuscular","Subcutaneous","Intradermal"],"a":1,"e":"Ans. is ''b'' i.e., Intramuscular Vaccine Avian Influenza: On April 17, 2007, FDA licensed the first vaccine in the United States for the prevention of H5N1 influenza, commonly referred to as avian influenza or \"bird flu\". This inactivated influenza virus vaccine is for use in people 18 through 64 years of age who are at increased risk of exposure to the H5N 1 influenza virus subtype contained in the vaccine. This vaccine is derived from the A/Vietnam/1203/2004 influenza virus. It is administered as a two-dose regimen. One 90 microgram dose is given intramuscularly, in the upper arm, and a second 90 microgram dose is given in the same manner, 28 days later.","pyqMatches":[{"year":"2014","no":943,"q":"What is the route of administration of avian influenza vaccine?","o":["Intranasal","Intramuscular","Subcutaneous","Intradermal"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5783, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 394, '{"id":5783,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":394,"q":"Contraception with increased risk of actinomycosis ?","o":["OCPs","Condom","IUCD","Vaginal"],"a":2,"e":"Ans. is `c'' i.e., IUCD","pyqMatches":[{"year":"2014","no":1000,"q":"Contraception with increased risk of actinomycosis ?","o":["OCPs","Condom","IUCD","Vaginal"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5784, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 395, '{"id":5784,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":395,"q":"Healthy carrier are not seen in","o":["Salmonella","Diphtheria","Measles","Cholera"],"a":2,"e":"Ans. is ''c'' i.e., Measles The infectious agent is shed by the infected host as it multiplies in them but the host does not manifest signs of the disease. Subclinical infection does not occur in measles","pyqMatches":[{"year":"2014","no":914,"q":"Healthy carrier are not seen in","o":["Salmonella","Diphtheria","Measles","Cholera"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5785, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 396, '{"id":5785,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":396,"q":"True about Indian reference female","o":["Height 161 cm","Weight 60 kg.","BMI 22","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Height 161 cm Reference man and woman Energy intake recommendations are formulated for a \"reference man\" and a \"reference woman\" whose profiles are described, and then necessary adjustment are made for subjects deviate from he standard reference. 1.Indian reference man He is between 18-29 years of age. He weights 60 kg. His height is 1.73 meter and BMI is 20.3 He is free from disease and physically fit for active work. On each working day he is employed for 8 hours in occupation that usually involves moderate activity. Spends 8 hours in bed, 4 to 6 hours sitting and moving around and 2 hours in walking and in active recreation or household duties. 2.An Indian reference woman She is between 18-29 years of age She weights 55 kg. Her height is 1.61 meter and BMI is 21.2 She is engaged for 8 hours in houshold work, in light industry or in other moderate activity. Spends 8 hours in bed, 4 to 6 hours sitting and moving around and 2 hours in walking and in active recreation or household duties.","pyqMatches":[{"year":"2014","no":1027,"q":"True about Indian reference female","o":["Height 161 cm","Weight 60 kg.","BMI 22","None of the above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5786, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 397, '{"id":5786,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":397,"q":"Byssinosis is due to exposure of ?","o":["Coal dust","Cotton dust","Sugarcane dust","Silica"],"a":1,"e":"Ans. is ''b'' i.e., Cotton dust Byssinosis is due to exposure to cotton dust in textile industries.","pyqMatches":[{"year":"2014","no":1073,"q":"Byssinosis is due to exposure of ?","o":["Coal dust","Cotton dust","Sugarcane dust","Silica"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5787, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 398, '{"id":5787,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":398,"q":"Best epidemiological study is -","o":["RCT","Meta-analysis","Cohort study","Case-control study"],"a":1,"e":"Ans. is ''b'' i.e., Meta-analysis Here are the different epidemiological studies with decreasing order of accuracy to test the association between risk factor and disease :?","pyqMatches":[{"year":"2014","no":930,"q":"Best epidemiological study is","o":["RCT","Meta-analysis","Cohort study","Case-control study"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5788, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 399, '{"id":5788,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":399,"q":"Secondary attack rate of chickenpox ?","o":["70%","90%","65%","80%"],"a":1,"e":"Ans. is `b'' i.e., 9%","pyqMatches":[{"year":"2014","no":960,"q":"Secondary attack rate of chickenpox ?","o":["70%","90%","65%","80%"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5789, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 400, '{"id":5789,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":400,"q":"True about rash of chicken pox ?","o":["Deep seated","Centripetal","Affects palm & sole","Slow evolution"],"a":1,"e":"Ans. is ''b'' i.e., Centripetal","pyqMatches":[{"year":"2014","no":961,"q":"True about rash of chicken pox ?","o":["Deep seated","Centripetal","Affects palm & sole","Slow evolution"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5790, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 401, '{"id":5790,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":401,"q":"Mortality rate in measles encephalitis is -","o":["1-2%","10-20%","20-30%","30-40%"],"a":1,"e":"Ans. is ''b i.e., 10-20% \"The mortality rate in encephalitis associated with measles is about 10-20 %\" — Park \"Case fatality rate in acute measles encephalitis is 15%\" wwwcdc.gov.","pyqMatches":[{"year":"2014","no":944,"q":"Mortality rate in measles encephalitis is","o":["1-2%","10-20%","20-30%","30-40%"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5791, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 402, '{"id":5791,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":402,"q":"Mortality rate of measles in developing countries?","o":["10%","20%","30%","40%"],"a":0,"e":"Ans. is ''a'' i.e., 10% Measles-associated mortality is usually higher among the very young and very old. Mortality in developing countries may be as high as 10 to 15% due to one or several factors, including the early age of infection, malnutrition, diarrhea, concomitant/secondary bacterial infections, and lack of access to good medical care. Most common cause of death is pneumonia in children and encephalitis in adults.","pyqMatches":[{"year":"2014","no":945,"q":"Mortality rate of measles in developing countries?","o":["10%","20%","30%","40%"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5792, 'PSM', 'Epidemiology', 'Moderate', 'Preventive_&_Social_Medicine', 403, '{"id":5792,"subject":"PSM","chapter":"Epidemiology","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":403,"q":"Matching is not required in which epidemiological study?","o":["Case control study","Cohort study","Case report","Randomized control trial"],"a":2,"e":"Ans. is `c'' i.e., Case report Case report: In medicine, a case report is a detailed report of the symptoms, signs, diagnosis, treatment, and follow-up of an individual patient. Case reports may contain a demographic profile of the patient, but usually describe an unusual or novel occurrence. Since it involves information on single case it does not require matching. Others i. e. case control study, cohort study and randomized control trials are based on the comparative study of two groups. To decrease the bias in the observations in the two groups under consideration it is essential that the groups be matched for all the characteristics except for the one under study. Thus matching is essential in these epidemiological studies.","pyqMatches":[{"year":"2014","no":931,"q":"Matching is not required in which epidemiological study?","o":["Case control study","Cohort study","Case report","Randomized control trial"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5793, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 404, '{"id":5793,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":404,"q":"Weight of an indian reference woman is ?","o":["45 kg","50 kg","55 kg","60 kg"],"a":2,"e":"Ans. is ''c'' i.e., 55 kg","pyqMatches":[{"year":"2014","no":1028,"q":"Weight of an indian reference woman is ?","o":["45 kg","50 kg","55 kg","60 kg"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5794, 'PSM', 'Concept of Health & Disease', 'Hard', 'Preventive_&_Social_Medicine', 405, '{"id":5794,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":405,"q":"Missing cases are detected by ?","o":["Active surveillance","Passive surveillance","Sentinel surveillance","Prevalence rate"],"a":2,"e":"Ans. is ''c'' i.e., Sentinel surveillance Surveillance Surveillance is defined as \"the continous scrutiny of the factors that determine the occurrence and distribution of disease and other conditions of ill health\". Surveillance may be of following types :? 1) Passive surveillance Data is reported itself to health system, e.g. a patient (clinical case) is coming to a doctor. Most of the national health programmes in India rely on passive surveillance for data collection. 2) Active surveillance Data is collected actively by health system, e.g. collection of blood slides every fortnight from house to house to control malaria. Active surveillance in India is done in :-","pyqMatches":[{"year":"2014","no":920,"q":"Missing cases are detected by ?","o":["Active surveillance","Passive surveillance","Sentinel surveillance","Prevalence rate"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5795, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 406, '{"id":5795,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":406,"q":"Study suitable for rare diseases ?","o":["Cohort study","Case-control study","Both of the above","None of the above"],"a":1,"e":"Ans. is ''b'' i.e., Case-control study","pyqMatches":[{"year":"2014","no":929,"q":"Study suitable for rare diseases ?","o":["Cohort study","Case-control study","Both of the above","None of the above"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5796, 'PSM', 'Maternal & Child Health', 'Easy', 'Preventive_&_Social_Medicine', 407, '{"id":5796,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":407,"q":"In MCH programme, best indicator for mother and child health ?","o":["MMR","IMR","Still birth rate","Neonatal mortality rate"],"a":1,"e":"Ans. is ''b'' i.e., IMR IMR is best indicator for:-","pyqMatches":[{"year":"2014","no":1009,"q":"In MCH programme, best indicator for mother and child health ?","o":["MMR","IMR","Still birth rate","Neonatal mortality rate"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5797, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 408, '{"id":5797,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":408,"q":"First ocular sign of Vitamin A deficiency ?","o":["Bitot''s spot","Conjunctival xerosis","Night blindness","Keratomalacia"],"a":1,"e":"Ans. is ''b'' i.e., Conjunctival xerosis","pyqMatches":[{"year":"2014","no":1030,"q":"First ocular sign of Vitamin A deficiency ?","o":["Bitot''s spot","Conjunctival xerosis","Night blindness","Keratomalacia"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5798, 'PSM', 'Communicable Diseases', 'Easy', 'Preventive_&_Social_Medicine', 409, '{"id":5798,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":409,"q":"Quarantine period of cholera ?","o":["1 day","2 days","5 days","10 days"],"a":2,"e":"Ans. is ''c'' i.e., 5 days","pyqMatches":[{"year":"2014","no":902,"q":"Quarantine period of cholera ?","o":["1 day","2 days","5 days","10 days"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5799, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 410, '{"id":5799,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":410,"q":"Endemic typhus is transmitted by ?","o":["Louse","Fleac","Tick","Mite"],"a":1,"e":"Ans. is ''b'' i.e., Flea","pyqMatches":[{"year":"2014","no":995,"q":"Endemic typhus is transmitted by ?","o":["Louse","Fleac","Tick","Mite"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5800, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 411, '{"id":5800,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":411,"q":"An infectious disease shows iceberg phenomenon. That means it has ?","o":["More case fatality rate","More SAR","More subclinical cases","More complications"],"a":2,"e":"Ans. is ''C'' i.e., More subclinical cases Iceberg of disease Disease in a community may be compared with an iceberg. The floating tip of the iceberg represents what the physician sees in the community, i.e. clinical cases (Diagnosed case, symptomatic case of the clinically apparent case). The vast submerged portion of the iceberg represents the hidden mass of disease, i.e. latent, inapparent, presymptomatic and undiagnosed cases and carriers in the community. The \"waterline\" represents the demarcation between apparent and inapparent disease. An epidemiologist is concerned with the hidden portion of the iceberg whereas the clinician is concerned with the tip of the iceberg. Screening is done for a Hidden portion of the iceberg whereas diagnosis is done for the tip of the iceberg. The iceberg phenomenon of disease is not shown by Rabies, Tetanus, Rubella, and Measles. The clinician concerned only with the tip of iceberg, i.e symptomatic cases that are seen in clinical treatment, this can result in inaccurate view of the nature and causes of a disease results because the minority of the cases are studied (hidden cases:- submerged portion of iceberg is not studied) → Clinician''s Fallacy Diseases with a great deal of subclinical infection (therefore have iceberg phenomenon) are :","pyqMatches":[{"year":"2014","no":935,"q":"An infectious disease shows iceberg phenomenon. That means it has ?","o":["More case fatality rate","More SAR","More subclinical cases","More complications"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5801, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 412, '{"id":5801,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":412,"q":"Which of the following is not related to epidemiology ?","o":["Promotion of health","Identification of etiology of disease","To collect data of magnitude of health problem","To teach a medical student how to conduct safe delivery"],"a":3,"e":"Ans. is ''d'' i.e., To teach a medical student how to conduct safe delivery According to the International Epidemiological Association (IEA), epidemiology has three main aims : a) To describe the distribution and magnitude of health and disease problems in human populations. b) To identify aetiological factors (risk factors) in the pathogenesis of disease; and c) To provide the data essential to the planning, implementation and evaluation of services for the prevention, control and treatment of disease and to the setting up of priorities among those services. In order to fulfil these aims, three rather different classes of epidemiological studies may be mentioned : descriptive studies, analytical studies, and experimental or intervention studies. The ultimate aim of epidemiology is to lead to effective action : a) To eliminate or reduce the health problem or its consequences; and b) To promote the health and well-being of society as a whole.","pyqMatches":[{"year":"2014","no":892,"q":"Which of the following is not related to epidemiology ?","o":["Promotion of health","Identification of etiology of disease","To collect data of magnitude of health problem","To teach a medical student how to conduct safe delivery"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5802, 'PSM', 'Communicable Diseases', 'Hard', 'Preventive_&_Social_Medicine', 413, '{"id":5802,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":413,"q":"Most rapid diagnosis of pulmonary TB can be done by ?","o":["Sputum culture","Sputum microscopy","Radiometric BACTEC method","Genexpert"],"a":1,"e":"Ans. is ''b'' i.e., Sputum microscopy Sputum smear microscopy is the quickest and easiest procedure. But it lacks both sensitivity and specificity. Sputum culture is sensitive and most specific. But it takes 2-8 weeks for culture on routine L.J. media (solid medium). M tuberculosis produces visible colonies on solid media (L.J. media) in 4-8 weeks. Studies have shown that the rate of Isolation of positive cultures was significantly faster with the Bactec method with 87% of the positives being obtained at 7 days and 96% by 14 days. Gene XPert should be used as the initial diagnostic test in individuals suspected of having MDR-TB or HIV-associated TB (strong recommendation),\" and \"Xpert may be used as a follow-on test to microscopy where MDR and/or HIV are of lesser concern, especially in smear-negative specimens (conditional recommendation). The GeneXpert MTB/RIF assay is a novel integrated diagnostic device for the diagnosis of tuberculosis and rapid detection of RIF resistance in clinical specimens.","pyqMatches":[{"year":"2014","no":949,"q":"Most rapid diagnosis of pulmonary TB can be done by ?","o":["Sputum culture","Sputum microscopy","Radiometric BACTEC method","Genexpert"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5803, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 414, '{"id":5803,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":414,"q":"Which of the following anti-leprotic drug is not given under supervision ?","o":["Rifampicin","Clofazimine","Dapsone","All are given supervised"],"a":2,"e":"Ans. is ''c'' i.e., Dapsone","pyqMatches":[{"year":"2014","no":959,"q":"Which of the following anti-leprotic drug is not given under supervision ?","o":["Rifampicin","Clofazimine","Dapsone","All are given supervised"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5804, 'PSM', 'Miscellaneous', 'Hard', 'Preventive_&_Social_Medicine', 415, '{"id":5804,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":415,"q":"Case fatality rate is a ?","o":["Rate","Ratio","Proportion","None"],"a":2,"e":"Ans. is ''c'' i.e., Proportion","pyqMatches":[{"year":"2014","no":924,"q":"Case fatality rate is a ?","o":["Rate","Ratio","Proportion","None"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5805, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 416, '{"id":5805,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":416,"q":"Daily dose of INH for TB ?","o":["600 mg","300 mg","150 mg","1500 mg"],"a":1,"e":"Ans. is ''b'' i.e., 300 mg","pyqMatches":[{"year":"2014","no":957,"q":"Daily dose of INH for TB ?","o":["600 mg","300 mg","150 mg","1500 mg"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5806, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 417, '{"id":5806,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":417,"q":"RDA of vitamin A in an adolescent female ?","o":["400 mcg","350 mcg","600 mcg","800 mcg"],"a":2,"e":"Ans. is ''c'' i.e., 600 mcg","pyqMatches":[{"year":"2014","no":1029,"q":"RDA of vitamin A in an adolescent female ?","o":["400 mcg","350 mcg","600 mcg","800 mcg"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5807, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 418, '{"id":5807,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":418,"q":"Population attributable risk is defined as the difference between:","o":["Incidence in exposed and incidence in non-exposed compared with incidence in non-exposed","Incidence in population and incidence in exposed compared with incidence in population","Incidence in population and incidence in non-exposed compared with incidence in population","Incidence in population and incidence in exposed compared with incidence in non-exposed"],"a":2,"e":"Ans. c. Incidence in population and incidence in non-exposed compared with incidence in population population attributable risk is defined as the difference between incidence in population and incidence in non-exposed compared with incidence in population.","pyqMatches":[{"year":"2015","no":826,"q":"Population attributable risk is defined as the difference between:","o":["Incidence in exposed and incidence in non-exposed compared with incidence in non-exposed","Incidence in population and incidence in exposed compared with incidence in population","Incidence in population and incidence in non-exposed compared with incidence in population","Incidence in population and incidence in exposed compared with incidence in non-exposed"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5808, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 419, '{"id":5808,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":419,"q":"Screening under RNTCP emphasizes on:","o":["Sputum microscopy","Chest X-ray","PCR","Sputum culture"],"a":0,"e":"Ans. a. Sputum microscopy Over-reliance on chesl X-ray was a draw back of National Tuberculosis Programme (NTP) which was over come by Revised National Tuberculosis Control Programme(RNTCP) which started diagnosing patient by sputum microscopy ''A nation-wide network of RNTCP qaality assured designated sputum smear microscopy laboratories has been set up, providing appropriate, available, affordable and accessible diagnostic services for TB suspects and cases.","pyqMatches":[{"year":"2015","no":920,"q":"Screening under RNTCP emphasizes on:","o":["Sputum microscopy","Chest X-ray","PCR","Sputum culture"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5809, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 420, '{"id":5809,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":420,"q":"Positive predictive value is a function of sensitivity,specificity and","o":["Absolute risk","Relative risk","Incidence","Prevalence"],"a":3,"e":"Ans. d. Prevalence The predictive value of a positive result falls as the disease prevalence declines. Positive Predictive Value In addition to sensitivity and specificity, the performance of a screening test is measured by its ''predictive value'', which reflects the diagnostic power of the test. The predictive accuracy depends upon sensitivity, specificity and disease prevalence. The predictive value of a positive test indicates the probability that a patient with a positive test result, has, in fact, the disease in questions. The more prevalent a disease in the given population, the more accurate will be the predictive value of a positive screening test. The predictive value of a positive result falls as the disease prevalence declines","pyqMatches":[{"year":"2014","no":939,"q":"Positive predictive value is a function of sensitivity,specificity and","o":["Absolute risk","Relative risk","Incidence","Prevalence"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5810, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 421, '{"id":5810,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":421,"q":"Consumer protection act includes all, except ?","o":["Passed in 1986","Decision within 3-6 months","ESI hospitals not included","Right to safety"],"a":2,"e":"Ans. is ''c'' i.e., ESI hospitals not included Consumer protection act For the first time in India, the Consumer Protection Act 1986 provided consumers a forum for speedy redressal of their grievances against medical services. According to this act, the decision should be taken within 3-6 months. There is no court fee payment and the person can plead his own case. Recently even ESI hospitals have been brought within the ambit of this act. COPRA is a piece of comprehensive legislation and recognizes six rights of consumer:-","pyqMatches":[{"year":"2013","no":982,"q":"Consumer protection act includes all, except ?","o":["Passed in 1986","Decision within 3-6 months","ESI hospitals not included","Right to safety"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5811, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 422, '{"id":5811,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":422,"q":"Father of Indian Surgery is ?","o":["Dhanvantari","Charaka","Susruta","Atreya"],"a":2,"e":"Ans. is ''c'' i.e., Susruta Father of (Modern) Medicine : Hippocrates Father of Indian Medicine : Charaka Hindu God of Medicine : Dhanvantari Father of (Modern) Surgery : Ambroise Pare Father of Indian Surgery : Sushruta Father of Epidemiology/Modern Epidemiology : John Snow Father of Bacteriology : Louis Pasteur Father of Biology : Gregor Mendel Father of (Modern) Anatomy : Vesalius Father of Physiology : Claude Bernard Father of Psychoanalysis : Sigmund Freud Father of Homeopathy : Semuel Hahneman Father of Anti-sepsis : Joseph Lister","pyqMatches":[{"year":"2013","no":841,"q":"Father of Indian Surgery is ?","o":["Dhanvantari","Charaka","Susruta","Atreya"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5812, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 423, '{"id":5812,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":423,"q":"Threshold level of herd immunity for Pertussis is?","o":["80%","70%","90%","50%"],"a":2,"e":"Ans. is ''c'' i.e., 90% Herd immunity It is the level of resistance of a community or group of people to a particular disease. It occurs when the vaccination of a portion of the population (or herd) provides protection to unprotected (non? vaccinated) individuals. Advantage of herd immunity It is not necessary to achieve 100% immunization to control a disease by providing herd immunity. When a certain percentage of population, is vaccinated, the spread of disease is effectively stopped. This critical percentage is referred to as herd immunity threshold. Disease Herd immunity threshod Diphtheria → 85% Measles → 83-94% Mumps → 75-86% Pertussis → 92-94% Polio → 80-86% Rubella → 80-85% Small pox → 83-85%","pyqMatches":[{"year":"2013","no":861,"q":"Threshold level of herd immunity for Pertussis is?","o":["80%","70%","90%","50%"],"a":2,"source":"NEET_2013_Paper.pdf"},{"year":"2016","no":845,"q":"Threshold level of herd immunity for Pertussis is?","o":["80%","70%","90%","50%"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2013","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5813, 'PSM', 'Maternal & Child Health', 'Easy', 'Preventive_&_Social_Medicine', 424, '{"id":5813,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":424,"q":"\"Second\" most common cause of maternal mortality in India is ?","o":["Toxemia","Anemia","Maternal hemmorrhage","Sepsis"],"a":1,"e":"Ans. is ''b'' i.e., Anemia Most common cause → Severe bleeding (25%). Second most common cause → Anemia (19%). Third most common cause → Infection/Sepsis (15%). Direct cause of maternal mortality in India Severe bleeding (25%) Infection (15%) Eclampsia (12%) Obstructed labour (8%) Unsafe abortion (13%) Other direct causes → Ectopic pregnancy, Embolism, Anaesthesia related. Indirect causes contribute Anaemia (19%) Malaria Heart diseases","pyqMatches":[{"year":"2013","no":931,"q":"\"Second\" most common cause of maternal mortality in India is ?","o":["Toxemia","Anemia","Maternal hemmorrhage","Sepsis"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5814, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 425, '{"id":5814,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":425,"q":"Most effective natural barrier to rabies","o":["Heat","Humidity","Water","None"],"a":2,"e":"Ans. is ''c'' i.e., Water Rabies is primarily a zoonotic disease of warm-blooded animals, particularly carnivorous such as dogs, Cats, Jackals and wolves. It is transmitted to man usually by bites or licks of rabid animals. It is the communicable disease which is always fatal. Rabies is an enzootic and epizootic disease of world-wide importance. Geographic boundries play an important role in the distribution of rabies. Water appears to be the most effective natural barriers to rabies → So, In India, Lakshadweep and Andman & Nicobar islands are free of the disease. A Rabies free area has been defined as one in which no case of indigenously acquired rabies has occurred in man or any animal species for 2 years. Countries where rabies is not found → Australia, china (Taiwan), Cyprus, Iceland, Ireland, Malta, Japan, Newzealand, Britain.","pyqMatches":[{"year":"2013","no":908,"q":"Most effective natural barrier to rabies","o":["Heat","Humidity","Water","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5815, 'PSM', 'Biostatistics', 'Easy', 'Preventive_&_Social_Medicine', 426, '{"id":5815,"subject":"PSM","chapter":"Biostatistics","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":426,"q":"A person is obese if he has weight for height","o":["1 SD from median weight for height","2 SD from median weight for height","3 SD form median weight for height","None"],"a":1,"e":"Ans. is ''b'' i.e., 2 SD from median weight for height Obesity Obesity is a medical condition in which excess body fat has accumulated to the extent that it may have an adverse effect on health, leading to reduced life expectancy. Body mass index (BMI) is used to define obesity. BMI define a person overweight when his BMI is between 25 - 30 kg/m2 and obese when his BMI is greater than 30 kg/m2. Body weight, though not an accurate measure of excess fat, is a widely used index. In epidemiological studies it is conventional to accept +2SD (standard deviations) from the median weight for height as a cut-of fpoint for obesity.","pyqMatches":[{"year":"2013","no":916,"q":"A person is obese if he has weight for height","o":["1 SD from median weight for height","2 SD from median weight for height","3 SD form median weight for height","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5816, 'PSM', 'Immunization', 'Hard', 'Preventive_&_Social_Medicine', 427, '{"id":5816,"subject":"PSM","chapter":"Immunization","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":427,"q":"Polio case definition for AFP surveillance ?","o":["Onset of AFP","Residual paralysis","Stool specimen positive for virus","All of the above"],"a":3,"e":"Ans. is `d'' i.e., All of the above AFP Surveillance Acute flaccid paralysis (AFP) surveillance is carried out to identify all remaining infected areas, monitor progress towards eradication and target supplementary immunization appropriately. The term AFP means paralysis of acute onset involving limbs leading to flaccidity. Poliomylelitis is most important etiology of AFP, other causes are - GBS (Guillain-Barre syndrome), transverse myelitis and traumatic neuritis. AFP surveillance aims at detecting cases of AFP and reporting them immediately to district immunization officer. Surveillance is carried out for all cases of AFP and not just for poliomyelitis. All cases of AFP are reported, regardless of the final diagnosis. As paralytic poliomyelitis is one cause of AFP, maintaining a high sensitivity of AFP reporting will ensure that all cases of paralytic poliomyelitis are detected, reported and investigated, resulting in preventive central measures to interrupt the transmission of disease. The aim of AFP surveillance is to detect polio virus transmission, and the earlier the stool is collected, the greater the chance of detecting polio virus. WHO recommends the immediate reporting and investigation of every case of AFP in children less than 15 yrs (As AFP in a person > 15 yrs is unlikely to be polio. Still, AFP surveillance must be flexible enough to report any case of AFP in an adult, if suspected to be due to poliomyelitis) Cases ofAFP are classified as Polio if : Wild polio virus is isolated from any stool specimen. Cases of AFP without isolation of wild polio virus may be classified as ''polio compatible'' if : Stool specimens were inadequate and Residual weakness was present 60 days after onset of paralysis or 60-day follow-up was not done (due to death or absence) and ''Expert review'' concludes that these cases could not be discarded as ''non-polio'' based on available data.","pyqMatches":[{"year":"2013","no":884,"q":"Polio case definition for AFP surveillance ?","o":["Onset of AFP","Residual paralysis","Stool specimen positive for virus","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5817, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 428, '{"id":5817,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":428,"q":"Service applied, staff recruitement, staff trained, Equipment ordered, equipment installed, product delivered which is the critical step","o":["Staff recruitment","Staff trained","Equipment ordered","Equipment installed"],"a":3,"e":"Ans. is ''d'' i.e., Equipment installed","pyqMatches":[{"year":"2013","no":980,"q":"Service applied, staff recruitement, staff trained, Equipment ordered, equipment installed, product delivered which is the critical step","o":["Staff recruitment","Staff trained","Equipment ordered","Equipment installed"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5818, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 429, '{"id":5818,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":429,"q":"Which of the following is seen in the recovery phase after a disaster except","o":["Rehabilitation","Reconstruction","Response","Preparedness"],"a":3,"e":"Ans. is ''d'' i.e., Preparedness Disaster Management includes three aspects:","pyqMatches":[{"year":"2013","no":969,"q":"Which of the following is seen in the recovery phase after a disaster except","o":["Rehabilitation","Reconstruction","Response","Preparedness"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5819, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 430, '{"id":5819,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":430,"q":"Dowry prohibition act 1986, punishment is ?","o":["Tyr, Rs 25000","Tyr Rs 15000","5yr, Rs 25000","5yr Rs 15000"],"a":3,"e":"Ans. is ''d'' i.e., 5yr Rs 15000 According to \"The Dowary Prohibition Act, 1961 (Amended 1986)\", if any person violates the act may be punished with the imprisonment for a term not less than 5 years and with a fine which shall not less than Rs. 15000 or amount of the value of such dowry which ever is more. Also know According to section 304 B IPC, the punishment for dowry death is imprisonment for a term of minimum 7 years, which may be extended to life imprisomment.","pyqMatches":[{"year":"2013","no":984,"q":"Dowry prohibition act 1986, punishment is ?","o":["Tyr, Rs 25000","Tyr Rs 15000","5yr, Rs 25000","5yr Rs 15000"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5820, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 431, '{"id":5820,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":431,"q":"Consumer protection act was passed in ?","o":["1977","1986","1993","1998"],"a":1,"e":"Ans. is ''b'' i.e., 1986 Consumer protection act was passed in 1986.","pyqMatches":[{"year":"2013","no":983,"q":"Consumer protection act was passed in ?","o":["1977","1986","1993","1998"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5821, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 432, '{"id":5821,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":432,"q":"Natural family planning method ?","o":["Abstinence","Coitus interruptus","BBT","Safe peroid"],"a":2,"e":"Ans. is ''c'' i.e., BBT Miscellaneous methods of contraceptions These are (i) Abstinence, (ii) Coitus interruptus, (iii) Safe period (rhyth method), and (iv) Natural family planning methods. Abstinence There is complete abstinence from sexual intercourse. It is not used and can hardly be considered as a method of contraception to be advocated to the masses. Coitus interruptus It is the oldest method of voluntary fertility control. The male withdraws before ejaculation, and thereby tries to prevent deposition of semen into vagina. Failure rate is very high 25%. Natural family planning methods These are :?","pyqMatches":[{"year":"2013","no":921,"q":"Natural family planning method ?","o":["Abstinence","Coitus interruptus","BBT","Safe peroid"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5822, 'PSM', 'Biostatistics', 'Easy', 'Preventive_&_Social_Medicine', 433, '{"id":5822,"subject":"PSM","chapter":"Biostatistics","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":433,"q":"Significant value of `p'' is ?","o":["0.01","0.02","0.04","0.05"],"a":3,"e":"Ans. is ''d'' i.e., 0.05 P is the probability that the difference seen between 2 samples occurs due to chance\". If p . .05 it is considered statistically significant. It means that There is 5% probability that the result could have been obtained by chance. or The investigator can be 95% sure that the result was not obtained by chance.","pyqMatches":[{"year":"2013","no":964,"q":"Significant value of `p'' is ?","o":["0.01","0.02","0.04","0.05"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5823, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 434, '{"id":5823,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":434,"q":"AIDS day is ?","o":["7 April","3 May","5 June","1 December"],"a":3,"e":"Ans. is ''d'' i.e., 1 December","pyqMatches":[{"year":"2013","no":842,"q":"AIDS day is ?","o":["7 April","3 May","5 June","1 December"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5824, 'PSM', 'Environment & Occupational Health', 'Easy', 'Preventive_&_Social_Medicine', 435, '{"id":5824,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":435,"q":"In rural area, cattle sheds should be ..... away from the houses ?","o":["5 feet","10 feet","20 feet","25 feet"],"a":3,"e":"Ans. is ''d'' i.e., 25 feet Rural housing In rural areas, the ''approved'' standards may be lower than in towns. The following minimum standards have been suggested : There should be at least two living rooms. Ample verandah space may be provided. The built-up area should not exceed one-third of the total area. There should be a separate kitchen with a paved sink or platform for washing utensils. The house should be provided with a sanitary latrine. The window area should be at least 10 percent of the floor area. There should be a sanitary well or a tube well within a quarter of a mile from the house. It is insanitary to keep cattle and livestock in dwelling houses. Cattle sheds should be at least 25 feet away from dwelling houses. A cattle shed should be open on all sides; an area 8 fit 4 fit is sufficient for each head of cattle. There should be adequate arrangement for the disposal of waste water, refuse and garbage.","pyqMatches":[{"year":"2013","no":943,"q":"In rural area, cattle sheds should be ..... away from the houses ?","o":["5 feet","10 feet","20 feet","25 feet"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5825, 'PSM', 'National Health Programmes', 'Easy', 'Preventive_&_Social_Medicine', 436, '{"id":5825,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":436,"q":"Operational efficiency of malaria control programme?","o":["Infant parasite rate","Slide positivity rate","Mosquito bite rate","Annual blood examination rate"],"a":3,"e":"Ans. is ''d'' i.e., Annual blood examination rate MEASUREMENTOFMALAR1A In the pre-eradication era, the magnitude of the malaria problem in a country used to be determined mostly from the reports of the clinically diagnosed malaria cases and the classical malariometric measures, e.g., spleen rate, parasite rate etc. On the other hand, during eradication era, the microscopic diagnosis of malaria cases became the main method of diagnosis and the parameters used are mostly parasitological in nature e.g., API, ABER, SPR and SFR. Measurements of malaria in the pre eradication era Spleen rate: Defined as the percentage of children between 2 & 10 years of age showing enlargement of spleen. Spleen rate is widely used for measuring the endemicity of malaria in a community. Av. enlarged spleen : A refinement of spleen rate , denoting the average size of spleen. Parasite rate Defined as on the percentage of children between the ages of 2 & 10 yrs showing malarial parsites in their blood films. Parasite density index Average degree of parasitimia Infant parasite rate Percentage of infants showing malarial parasites in their blood films. It is the most sensitive index of recent transmission of malaria in a locality. If the infant parasite rate is zero for three consecutive years in a locality, it is regarded as absence of malaria transmission even though, the Anopheline vectors responsible for previous transmissions may remain. Eradication Era Annual Parasite Incidence (API)* = (Confirmed cases during one year / population under surveillance) x 1000 Annual Blood Examination Rate = (No. of slides examined/population) x 100 ABER is an index of operational efficiency. In the modified plan of operation, the minimum prescribed is 10 percent of the population in a year. Annual falciparum index Slide positivity rate Slide positivity rate is the percentage of slides found positive for malarial parasite, irrespective of the type of species. Slide falciparum rate It is the percentage of slides positive for P. falciparum.","pyqMatches":[{"year":"2013","no":892,"q":"Operational efficiency of malaria control programme?","o":["Infant parasite rate","Slide positivity rate","Mosquito bite rate","Annual blood examination rate"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5826, 'PSM', 'Concept of Health & Disease', 'Hard', 'Preventive_&_Social_Medicine', 437, '{"id":5826,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":437,"q":"2 months old child having birth weight 2kg, with poor feeding, very sleepy and wheezing. The diagnosis is?","o":["No pneumonia","Severe pneumonia","Very severe disease","None"],"a":2,"e":"Ans. is ''c'' i.e., Very severe disease","pyqMatches":[{"year":"2013","no":873,"q":"2 months old child having birth weight 2kg, with poor feeding, very sleepy and wheezing. The diagnosis is?","o":["No pneumonia","Severe pneumonia","Very severe disease","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5827, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 438, '{"id":5827,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":438,"q":"Most common source of Diphtheria","o":["Case","Carrier","Both","None"],"a":1,"e":"Ans. is ''b'' i.e., Carrier Diphtheria is an acute infectious disease caused by toxigenic strains of corynebacterium diphtheriae. Source of infection cases or carriers; carriers are common sources of infection, their ratio is estimated to be 95 carriers for 5 clinical cases. Infective period → 14 - 28 days from the onset of disease. Age group → 1 to 5 years Sex → Both sexes Incubation period → 2 - 6 days","pyqMatches":[{"year":"2016","no":847,"q":"Most common source of Diphtheria","o":["Case","Carrier","Both","None"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5828, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 439, '{"id":5828,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":439,"q":"All are features of yellow fever except ?","o":["IP 3-6 days","1 attack gives life long immunity","Caused by vector aedes","Validity of vaccination begins immediately after vaccination"],"a":3,"e":"Ans. is ''d'' i.e., Validity of vaccination begins immediately after vaccination Yellow fever Yellow fever is a zoonotic disease caused by ar abro-virus. It affects principally monkeys. Agent → Flavivirus fibricus a group B arbovirus of togavirus family. Vector → Aedes aegypti mosquito. Reservoir → Monkeys and forest mosquitoes. Transavarian transmission of the virus in mosquitoes has been shown to occur in adverse conditions (e.g., during extended dry seasons), in the absence of susceptible hosts. o There is no evidence that yellow fever has ever been present in Asia. Environmental factor for yellow fever. A temprature of 24°C or more is required for the multiplication of the virus in the mosquito. It should be accompnied by a relative humidity of over 60% for the mosquitoes to live long. Urbanization is leading to extension of yellow fever in Africa. Measures designed to restrict the spread of yellow fever are specified in the \"International health regulation\" of WHO. These are implemented by the Govt of India through stringent aerial and maritime traffic regulations. Broadly these comprise : - i. Travellers All travellers (including infants) exposed to yellow fever or passing through endemic zones of yellow fever must posses a valid international certificate fo vaccination against yellow fever before they are allowed to enter yellow fever receptive areas like India. The validity of the certificate begins 10 days after the date of vaccination and extends up to 10 years. Revaccination performed before the end of the validity of certicicate renders the certificate valid for a further period of 10 years starting on the day of revaccination. If no such certificate fo vaccination is available, the travellar is placed on quarantine for 6 days from the date of leaving an infected area. ii. Mosquitoes The aircraft and ships arriving from endemic areas are subjected to aerosol spraying with prescribed insecticides. Airports and Seaports are kept free from the breeding of insect vectors over an area extending at least 400 metres around their perimeters. The \"aedes aegypti index\" is kept below 1.","pyqMatches":[{"year":"2013","no":896,"q":"All are features of yellow fever except ?","o":["IP 3-6 days","1 attack gives life long immunity","Caused by vector aedes","Validity of vaccination begins immediately after vaccination"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5829, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 440, '{"id":5829,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":440,"q":"Criteria for slaughter house ?","o":["Glass area should be 25% of floor area","Window ledes sloped 25°","Doorways 1 meter high","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Glass area should be 25% of floor area","pyqMatches":[{"year":"2013","no":944,"q":"Criteria for slaughter house ?","o":["Glass area should be 25% of floor area","Window ledes sloped 25°","Doorways 1 meter high","None of the above"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5830, 'PSM', 'Concept of Health & Disease', 'Hard', 'Preventive_&_Social_Medicine', 441, '{"id":5830,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":441,"q":"A patient had injury to right leg by road traffic accident and his leg was amputated. This is ?","o":["Disease","Disability","Impairment","Handicap"],"a":2,"e":"Ans. is ''c'' i.e., Impairment Any loss of anatomical structure (e.g. loss of leg in this question) is called as impairment. According to WHO definitions, Disease: Any abnormal condition of an individual that impairs function Impairment: Any loss or abnormality of psychological, physiological or anatomical structure or function Disability: (Because of impairment,) any restriction or inability to perform an activity in a range considered normal for a human being Handicap: A disadvantage for a given individual, resulting from an impairment/disability, that limits/prevents fulfillment of a role considered normal (depending on age, sex, social, cultural factors) for that individual For example, Event ClassificationInterpretation Accident Disease Impairs function of a person Loss of foot Impairment Loss of anatomical structure in the form of foot Cannot Walk Disability Walking is a normal routine daily activity of a human being Walk y of a human being UnemployedHandicap Loses out his job because he cannot walk, so cannot fulfill his role in the society, i.e, earning for his family members","pyqMatches":[{"year":"2013","no":854,"q":"A patient had injury to right leg by road traffic accident and his leg was amputated. This is ?","o":["Disease","Disability","Impairment","Handicap"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5831, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 442, '{"id":5831,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":442,"q":"Unmet needs of contraception to met according to NFH S-3","o":["Women < 20 years","Women after puperium","Women after 1'' week delivery","After illegal abortion"],"a":0,"e":"Ans. is ''a'' i.e., Women < 20 years Many women who are sexually active would prefer to avoid pregnancy, but nevertheless are not using any method of contraception. These women are considered to have ''unmet need'' for family planning. The concept is usually applied to married women. According to the National Family Health Survey-3, Unmet need for family planning is highest (27.1%) among women below 20 years age and is almost entirely for spacing the births rather than for limiting the births. It is also relatively high for women in age group 20-24 years (21.1%) with 75% need for spacing and 25% for limiting the birth. Unmet need for contraception among women aged 30 years and above are mostly for limiting birth. Age group Unmet need of contraception for < 20 years For spacing the birth 20-24 yearsFor spacing (75%) and for limiting birth (25%) 30 years For limiting birth","pyqMatches":[{"year":"2013","no":922,"q":"Unmet needs of contraception to met according to NFH S-3","o":["Women < 20 years","Women after puperium","Women after 1'' week delivery","After illegal abortion"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5832, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 443, '{"id":5832,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":443,"q":"Infectivity period of chickenpox is ?","o":["1 day before and 4 days after appearance of rash","4 days before and 5 day after appearance of rash","Only when scab falls","Entire incubation period"],"a":0,"e":"Ans. is ''a'' i.e., 1 day before and 4 days after appearance of rash Period of communicability: Chicken pox: 1 – 2 days before to 4 – 5 days after appearance of rash Measles: 4 days before to 5 days after appearance of rash Rubella: 7 days before symptoms to 7 days after appearance of rash Mumps: 4 – 6 days before symptoms to 7 days thereafter Influenza: 1 – 2 days before to 1 – 2 days after onset of symptoms Diphtheria: 14 – 28 days from disease onset Pertussis: 7 days after exposure to 3 weeks after paroxysmal stage Poliomyelitis: 7 – 10 days before and after onset of symptoms Hepatitis A: 2 weeks before to 1 week after onset of jaundice Hepatitis B: Till disappearance of HBs Ag & appearance of anti-HBs Meningococcal: Until absent from nasal and throat discharge Tuberculosis: As long as not treated","pyqMatches":[{"year":"2013","no":882,"q":"Infectivity period of chickenpox is ?","o":["1 day before and 4 days after appearance of rash","4 days before and 5 day after appearance of rash","Only when scab falls","Entire incubation period"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5833, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 444, '{"id":5833,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":444,"q":"Gas causing green house effect ?","o":["CO2","Methane","Sulfur hexafluoride","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above","pyqMatches":[{"year":"2013","no":953,"q":"Gas causing green house effect ?","o":["CO2","Methane","Sulfur hexafluoride","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5834, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 445, '{"id":5834,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":445,"q":"All are present in mild dehydration, except ?","o":["Thirst","Restlessness","Dry tongue","Normal BP"],"a":2,"e":"Ans. is ''c'' i.e., Dry tongue","pyqMatches":[{"year":"2013","no":888,"q":"All are present in mild dehydration, except ?","o":["Thirst","Restlessness","Dry tongue","Normal BP"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5835, 'PSM', 'Concept of Health & Disease', 'Hard', 'Preventive_&_Social_Medicine', 446, '{"id":5835,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":446,"q":"3 months old infant, no chest indrawing with respiratory rate 52/minute. Diagnosis is","o":["No pneumonia","Pneumonia","Severe pneumonia","Very severe disease"],"a":1,"e":"Ans. is ''b'' i.e., Pneumonia This infant has:?","pyqMatches":[{"year":"2013","no":874,"q":"3 months old infant, no chest indrawing with respiratory rate 52/minute. Diagnosis is","o":["No pneumonia","Pneumonia","Severe pneumonia","Very severe disease"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5836, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 447, '{"id":5836,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":447,"q":"ORS required during first 4 hours in a 20 kg child?","o":["200-400 ml","400-600 ml","600-800 ml","1200-2200 ml"],"a":3,"e":"Ans. is ''d'' i.e., 1200-2200 ml Weight between 16-29.9 kg → ORS requirment is 1200-2200 ml during first 4 hours. Guidelines for ORS therapy during first four hours Age < 4 mth 4- I 1 mths 1-2 yrs 2-4 yrs 5-14 yrs 15 yrs Weight (Kg) < 5 5-7.9 8-10.9 11-15.9 16-29.9 30 or over ORS (ml) 200-400 400-600 600- 800 800- 1200 1200- 2200 2200-4000","pyqMatches":[{"year":"2013","no":889,"q":"ORS required during first 4 hours in a 20 kg child?","o":["200-400 ml","400-600 ml","600-800 ml","1200-2200 ml"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5837, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 448, '{"id":5837,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":448,"q":"Descending order of cancer prevalance in males?","o":["Lung > oral > pharynx > esophagus","Oral > lung > pharynx > esophagus","Pharynx > lung > oral > esophagus","Esophagus > oral > stomach > lung"],"a":1,"e":"Ans. is ''b'' i.e., Oral > lung > pharynx > esophagus Most common cancer in males in India is oral cancer followed by lung cancer. Cancers in decreasing order in males (in India) : Oral cavity > Lung > Pharynx > Esophagus > Stomach. Note : Some textbooks have mentioned that lung cancer is the most common cancer in men in India, followed by oral cavity cancer as the 2\"4 most common cancer. But most of the textbooks have mentioned oral cavity as the most common site of cancer in men in India. So, according to me''oral cavity is the most common site. Cancers in decreasing order in females (in India) : cervix > breast > ovary cavity > esophagus. Most common cancer in males in India → Oro-pharyngeal Ca (Aero-digestive Ca). Most common cancer in males in world → Lung Ca. Most common cancer in females in India → Cervical cancer. Most common cancer in females in world → Brast Ca. Most common overall cancer in the world (combined male & female) → Lung cancer. Most common cancer related death in males in India & in world → Ca lung. Most common cancer related death in females in India & in world → Breast cancer.","pyqMatches":[{"year":"2013","no":917,"q":"Descending order of cancer prevalance in males?","o":["Lung > oral > pharynx > esophagus","Oral > lung > pharynx > esophagus","Pharynx > lung > oral > esophagus","Esophagus > oral > stomach > lung"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5838, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 449, '{"id":5838,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":449,"q":"NSABP stands for ?","o":["National surgical adjuvant for breast project","National surgical adjuvant for breast and bowel project","National surgical adjuvant for brain and breast","National surgical adjuvant for bowel and brain"],"a":1,"e":"Ans. is ''b'' i.e., National surgical adjuvant for breast and bowel project The National Surgical Adjuvant Breast and Bowel Project (NSABP) is a clinical trials cooperative group supported since its inception by national cancer institute (NCI).","pyqMatches":[{"year":"2013","no":988,"q":"NSABP stands for ?","o":["National surgical adjuvant for breast project","National surgical adjuvant for breast and bowel project","National surgical adjuvant for brain and breast","National surgical adjuvant for bowel and brain"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5839, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 450, '{"id":5839,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":450,"q":"According to ''Biomedical concept'' health is","o":["Relative absence of pain and discomfort","Absence of disease","A sound mind in sound body, in a sound family, in sound environment","None"],"a":1,"e":"Ans. is ''b'' i.e., Absence of disease According to biomedical concept health is defined as \"absence of disease\", and has the basis in the \"germ theory of disease\"","pyqMatches":[{"year":"2013","no":848,"q":"According to ''Biomedical concept'' health is","o":["Relative absence of pain and discomfort","Absence of disease","A sound mind in sound body, in a sound family, in sound environment","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5840, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 451, '{"id":5840,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":451,"q":"Spot map is used for ?","o":["Local distribution of disease","Rural-urban variation","National variation","None"],"a":0,"e":"Ans. is ''a'' i.e., Local distribution of disease Inner and outer city variations in disease frequency are well known. These variations are best studied with the aid of \"spot maps\" or \"shaded maps\". These maps show at a glance areas of high and low frequency, the boundaries and distribution. For example, if the map shows \"clustering\" of cases, it may suggest a common source of infection or a common risk factor shared by all the cases. The classical example of use of spot maps was by John snow for cholera epidemic in 1854.","pyqMatches":[{"year":"2013","no":965,"q":"Spot map is used for ?","o":["Local distribution of disease","Rural-urban variation","National variation","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5841, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 452, '{"id":5841,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":452,"q":"Screening is useful in disease which has?","o":["Short lead time","Long lead time","Both a & b","No relation with lead time"],"a":1,"e":"Ans. is ''b'' i.e., Long lead time","pyqMatches":[{"year":"2013","no":871,"q":"Screening is useful in disease which has?","o":["Short lead time","Long lead time","Both a & b","No relation with lead time"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5842, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 453, '{"id":5842,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":453,"q":"Iron requirment in a normal mensturating adult female","o":["15 mg/day","20 mg/day","30 mg/day","35 mg/day"],"a":1,"e":"Ans. is ''b'' i.e., 20 mg/day","pyqMatches":[{"year":"2013","no":938,"q":"Iron requirment in a normal mensturating adult female","o":["15 mg/day","20 mg/day","30 mg/day","35 mg/day"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5843, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 454, '{"id":5843,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":454,"q":"The following is not a Nerve gas ?","o":["Sarin","Tabun","Soman","Pyrolan"],"a":3,"e":"Ans. is ''d'' i.e., Pyrolan Nerve gases are a class of organophosphates that act by inhibiting enzyme acetylcholinesteraze, an enzyme that destroys acetylcholine. The classical examples are tabun, sarin, soman and cyclosarin. These are used as chemical weapons in wars, i.e. chemical warfare.","pyqMatches":[{"year":"2013","no":954,"q":"The following is not a Nerve gas ?","o":["Sarin","Tabun","Soman","Pyrolan"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5844, 'PSM', 'Concept of Health & Disease', 'Hard', 'Preventive_&_Social_Medicine', 455, '{"id":5844,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":455,"q":"Moribund patient, triage color ?","o":["Red","Black","Yellow","Green"],"a":1,"e":"Ans. is ''b'' i.e., Black Triage When the quantity and severity of injuries overwhelm the operative capacity of health facilities, a different approach to medical treatment must be adopted. The usual principle of first come, first treated\", is not followed in mass emergencies. Triage consists of rapidly classifying the injured and the likelyhood of their survival with prompt medical intervention. Higher priority is granted to victims whose immediate or long-term prognosis can be dramatically affected by simple intensive care. Moribund patients who require a great deal of attention, with questionable benefit have the lowest priority. The most common triage classification system used international is four colour code system. Red -,High priority treatment or transfer Yellow Medium priority Green Ambulatory patients Black Dead or moribund patients","pyqMatches":[{"year":"2013","no":970,"q":"Moribund patient, triage color ?","o":["Red","Black","Yellow","Green"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5845, 'PSM', 'Communicable Diseases', 'Moderate', 'Preventive_&_Social_Medicine', 456, '{"id":5845,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":456,"q":"Disease not covered under Integrated disease surveillance project (IDSP) is ?","o":["Meningococcal disease","Tuberculosis","Herpes zoster","Cholera"],"a":2,"e":"Ans. is ''c'' i.e., Herpes zoster Integrated disease surveillance project (IDSP) IDSP is a decentralized state based surveillance system intended to detect early warning signals of impending outbreaks and helps initiate an effective response in a timely manner in urban and rural areas. It will also provide essential data to monitor progress of on-going disease control programme and help allocate health resources more efficiently. It is a 5 years project and was launched in November 2004. The core conditions under surveillance in IDSP are: A. Regular Surveillance Vector borne disease -p Malaria Water borne disease -3 Acute diarrheal disease (cholera), Typhoid Respiratory disease→ TB Vaccine preventable disease Measles Disease under eradication→ Polio Other conditions → Road traffic accidents Other inernational commitments Plague Unusual clinical syndromes Men ingoencephalitis, Respiratory distress, hemorrhagic fever B. Sentinel surveillance STD/blood borne disease -p HIV/HBV, HCV, water quality monitoring Other conditions→ Outdoor air quality C. Regular periodic surveys NCD risk factors → Anthropometry, Physical activity, BP, tobacco, nutrition D. Additional state priorities Each state may identify up to five additional conditions for surveillance. These are (above described) are the conditions (diseases) which are under surveillance in IDSP. There are some clinical syndrome under surveillance in IDSP to pick up all priority diseases listed in regular surveillance (above)","pyqMatches":[{"year":"2013","no":912,"q":"Disease not covered under Integrated disease surveillance project (IDSP) is ?","o":["Meningococcal disease","Tuberculosis","Herpes zoster","Cholera"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5846, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 457, '{"id":5846,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":457,"q":"Performance of components of PQLI is counted between","o":["-1 to +1","0 to 1","0 to 100","None"],"a":2,"e":"Ans. is ''c'' i.e., 0 to 100 The subjective component of well being-4 Quality of life While \"level of living\" is an objective component, \"quality of life\" comprises the individual''s own subjective evaluation. The index for quality of life is \"Physical quality of life index (PQLI)\". The PQLI is an attempt to measure the quality of life or well-being of a country. Physical quality of life index consolidates three indicators:?","pyqMatches":[{"year":"2015","no":808,"q":"Performance of components of PQLI is counted between","o":["1 to +1","0 to 1","0 to 100","None"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5847, 'PSM', 'Demography & Family Planning', 'Moderate', 'Preventive_&_Social_Medicine', 458, '{"id":5847,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":458,"q":"Type of sampling, if random sample is taken from a characteristic population, eg. Hindus, Muslims, Christians etc?","o":["Simple random","Systemic random","Stratified random","Cluster"],"a":2,"e":"Ans. is ''c'' i.e., Stratified random Stratified random sampling is particularly useful where one is interested in analysing the data by a certain characteristic of the population, viz Hindus, Muslims, Christians, age group etc, - as we know these groups are not equally distributed in the population.\" ............... Park Simple random sampling Simple random sampling, also, known as ''unrestricted random sampling''; is applicable for small, homogenous, readily available population and is used in clinical trials. In simple random sampling each individual is chosen randomly and entirely by chance. So, each individual has the same probability of being chosen at any stage during the sampling process. For example : ? Let us assume you had a school with 1000 students, divided equally into boys and girls, and you wanted to select 100 of them for further study. You might put all their names in a bucket and then pull 100 names out. Not only does each person have an equal chance of being selected, we can also easily calculate the probaility of a given person being chosen, since we know the sample size (n) and population (N) and it becomes a simple matter of division → n/N or 100/1000 = 0.10 (10%). This means that every student in the school has a 10% or 1 in 10 chance of being selected using this method. Systematic random sampling In order to do systematic random sampling, the individuals in a population are arranged in a certain way (for example, alphabetically). A random starting point is selected and then every nth (for example 10th or 15th) individual is selected for the sample. That is, after arranging the individuals in certain pattern (e.g., alpabetically) a starting point is chosen at random, and choices thereafter at regular intervals. For example, suppose you want to sample 8 houses from a street of 120 houses. 120/8 = 15, So every 15th house is chosen after a random starting point between 1 and 15. If the random starting point is 11, then the houses selected are→ 11, 26, 41, 56, 71, 86, 101, and 116. In contrast to simple random sampling, some houses have a larger selection probabily e.g., in this question 11, 26, 41, 56, 71, 86, 100 and 116. While the remaining number can not be selected. Stratified random sampling When sub-populations vary considerably, it is advantageous to sample each subpopulation (stratum) independently. Stratification is the process of grouping members of the population into relative hemogenous subgroups before sampling. The strata should be mutually exclusive, every element in the population must be assigned to only one stratum. Then systematic random sampling method is applied within each stratum. Population → Stratification → Systematic random sampling → Sample. This often improves the representativeness of the sample by reducing sampling error. For example, suppose in a population of 1000, sample of 100 is to be drawn for Hb estimation, first convert the population into homogenous striata (e.g., 700 males and 300 females), then draw 70 males and 30 females by doing systematic random sampling.","pyqMatches":[{"year":"2013","no":967,"q":"Type of sampling, if random sample is taken from a characteristic population, eg. Hindus, Muslims, Christians etc?","o":["Simple random","Systemic random","Stratified random","Cluster"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5848, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 459, '{"id":5848,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":459,"q":"Tablet for supplementation of iron and folic acid for adult contains ?","o":["20 mg iron, 5001,tg folic aci","40 mg iron, 250 folic acid","100 mg iron, 500 lig folic acid","100 mg iron, 100 hg folic acid"],"a":2,"e":"Ans. is ''c'' i.e., 100 mg iron, 500 jig folic acid","pyqMatches":[{"year":"2015","no":883,"q":"Tablet for supplementation of iron and folic acid for adult contains ?","o":["20 mg iron, 5001,tg folic aci","40 mg iron, 250 folic acid","100 mg iron, 500 lig folic acid","100 mg iron, 100 hg folic acid"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5849, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 460, '{"id":5849,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":460,"q":"According to immunization schedule, children should receive influenza vaccine ?","o":["2 doses at 1 month interval","3doses at 1month interval","2 doses at one month interval with one booster dose later","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., 2 doses at one month interval with one booster dose later 2 doses of vaccine, separated by an interval of 3-4 weeks are considered necessary to induce satisfactory antibodies level. The protective value is 70-90% and immunity lasts for 6-12 months. Revaccination on an annual basis is recommended. Influenza vaccines","pyqMatches":[{"year":"2013","no":880,"q":"According to immunization schedule, children should receive influenza vaccine ?","o":["2 doses at 1 month interval","3doses at 1month interval","2 doses at one month interval with one booster dose later","None of the above"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5850, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 461, '{"id":5850,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":461,"q":"Most important feature to diagnose severe pneumonia?","o":["Cyanosis","Chest indrawing","Nasal flaring","Fast breathing"],"a":1,"e":"Ans. is ''b'' i.e., Chest indrawing The only sign for severe pneumonia is chest indrawing","pyqMatches":[{"year":"2013","no":875,"q":"Most important feature to diagnose severe pneumonia?","o":["Cyanosis","Chest indrawing","Nasal flaring","Fast breathing"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5851, 'PSM', 'Maternal & Child Health', 'Easy', 'Preventive_&_Social_Medicine', 462, '{"id":5851,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":462,"q":"Infant mortality rate in India is, per 1000 live births?","o":["25","34","55","60"],"a":1,"e":"Ans. is `b'' i.e.,34 The value for Mortality rate, infant (per 1,000 live births) in India was 37 as of 2015. IMR of India has declined by three points (8% decline), from 37 per 1000 live births in 2015 to 34 per 1000 live births in 2016.","pyqMatches":[{"year":"2013","no":929,"q":"Infant mortality rate in India is, per 1000 live births?","o":["25","34","55","60"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5852, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 463, '{"id":5852,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":463,"q":"Sullivan''s index indicates","o":["Life free of disability","Pregnancy rate per HW","Hook worm eggs/gm of stool","Standard of living"],"a":0,"e":"Ans. is ''a'' i.e., Life free of disability Sullivan''s index Sullivan''s index is the expectation of life free of disability. It is computed by subtracting from the life expectancy the probable duration of bed disability and inability to perform major activities. Sullivan''s index = life expectancy— Duration ofbed disability & Inability to perform minor work It is a direct indicator of health and well being in a community. t is one of the most advanced health indicators currently available.","pyqMatches":[{"year":"2013","no":856,"q":"Sullivan''s index indicates","o":["Life free of disability","Pregnancy rate per HW","Hook worm eggs/gm of stool","Standard of living"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5853, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 464, '{"id":5853,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":464,"q":"Which vaccine is contraindicated pregnancy","o":["Cholera vaccine","Typhoid vaccine","Meningococcal vaccine","Measles vaccine"],"a":3,"e":"Ans. is `d'' i.e., Measles vaccine As a rule of thumb the vaccination with live viral or bacterial vaccine is contraindicated in pregnancy. The important ones are : - Measles Mumps Poliomyelitis Rubella Yellow fever Varicella BCG","pyqMatches":[{"year":"2013","no":864,"q":"Which vaccine is contraindicated pregnancy","o":["Cholera vaccine","Typhoid vaccine","Meningococcal vaccine","Measles vaccine"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5854, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 465, '{"id":5854,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":465,"q":"Juvenile justice act defines a juvenile which is","o":["Male below 16 years","Female below 16 years","Male below 18 years","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., Male below 18 years","pyqMatches":[{"year":"2012","no":591,"q":"Juvenile justice act defines a juvenile which is","o":["Male below 16 years","Female below 16 years","Male below 18 years","None of the above"],"a":2,"source":"NEET_2012_Paper.pdf"},{"year":"2013","no":986,"q":"Juvenile justice act defines a juvenile which is","o":["Male below 16 years","Female below 16 years","Male below 18 years","None of the above"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2012","2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5855, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 466, '{"id":5855,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":466,"q":"Secondary level of prevention is important in all of the following except ?","o":["Coronary heart disease","TB","Leprosy","None"],"a":0,"e":"Ans. is ''a'' i.e., Coronary heart disease For non-communicable disease (e.g. CHD), primordial prevention is best intervention.","pyqMatches":[{"year":"2013","no":853,"q":"Secondary level of prevention is important in all of the following except ?","o":["Coronary heart disease","TB","Leprosy","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5856, 'PSM', 'Demography & Family Planning', 'Moderate', 'Preventive_&_Social_Medicine', 467, '{"id":5856,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":467,"q":"If annual growth rate of a population is 1.5-2%, what number ofyears will be required to double the population?","o":["70-47 years","47-35 years","35-28 years","28-23"],"a":1,"e":"Ans. is ''b'' i.e. 47-35 years","pyqMatches":[{"year":"2013","no":924,"q":"If annual growth rate of a population is 1.5-2%, what number ofyears will be required to double the population?","o":["70-47 years","47-35 years","35-28 years","28-23"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5857, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 468, '{"id":5857,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":468,"q":"One PHC covers how much population in hilly area?","o":["10000","20000","30000","50000"],"a":1,"e":"Ans. is ''b'' i.e., 20000","pyqMatches":[{"year":"2013","no":977,"q":"One PHC covers how much population in hilly area?","o":["10000","20000","30000","50000"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5858, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 469, '{"id":5858,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":469,"q":"Most common cause of post-measles death ?","o":["Diarrhea","RTI","SSPE","Myocarditis"],"a":1,"e":"Ans. is ''b'' i.e., RTI Respiratory tract infection (RTI) is the most common cause of death. \"Pneumonia is the most common life-threatening complication\"_______________________ Park","pyqMatches":[{"year":"2013","no":877,"q":"Most common cause of post-measles death ?","o":["Diarrhea","RTI","SSPE","Myocarditis"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5859, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 470, '{"id":5859,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":470,"q":"Shortest incubation period is of which infection ?","o":["Chicken pox","Measles","Rubella","Influenza"],"a":3,"e":"Ans. is ''d'' i.e., Influenza","pyqMatches":[{"year":"2013","no":883,"q":"Shortest incubation period is of which infection ?","o":["Chicken pox","Measles","Rubella","Influenza"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5860, 'PSM', 'Communicable Diseases', 'Hard', 'Preventive_&_Social_Medicine', 471, '{"id":5860,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":471,"q":"A person is considered as a case of tuberculosis if -","o":["Has cough","Sputum positive","X-ray signs","Mantoux positive"],"a":1,"e":"Ans. is `b'' i.e., Sputum positive Case of tubuculosis is defined as, either any of the two : -","pyqMatches":[{"year":"2013","no":878,"q":"A person is considered as a case of tuberculosis if","o":["Has cough","Sputum positive","X-ray signs","Mantoux positive"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5861, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 472, '{"id":5861,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":472,"q":"All of the following are anthropozoonosis except","o":["Rabies","Plaque","Anthrax","Schistosomiasis"],"a":3,"e":"Ans. is ''d'' i.e., Schistosomiasis Zoonoses Zoonoses are diseases and infections which are naturally transmitted between vertebrate animal and man. The zoonoses may be classified according to the direction of transmission of disease : ? l. Anthropozoonoses Infection is transmitted to man from lower vertebrate animals. Examples -4 Rabies, plague, hydatid disease, anthrax, trichinosis.","pyqMatches":[{"year":"2013","no":903,"q":"All of the following are anthropozoonosis except","o":["Rabies","Plaque","Anthrax","Schistosomiasis"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5862, 'PSM', 'Communicable Diseases', 'Easy', 'Preventive_&_Social_Medicine', 473, '{"id":5862,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":473,"q":"Night blood survey is done in ?","o":["Filaria","Typhoid","Malaria","Kala-azar"],"a":0,"e":"Ans. is ''a'' i.e., Filaria The microfilariae of W. bancrofti and B. malayi occuring in India display a nocturnal periodicity, i.e., they appear in large number at night and retreat from the blood stream during the day. This is a biological adaptation to the nocturnal biting habits of vector mosquitoes. The maximum density of microfilariae in blood is reported between 10 pm and 2am. When the sleeping habits of the host are altered, a reversal in periodicity has been observed","pyqMatches":[{"year":"2013","no":910,"q":"Night blood survey is done in ?","o":["Filaria","Typhoid","Malaria","Kala-azar"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5863, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 474, '{"id":5863,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":474,"q":"Population explosion (explosive growth) is defined as the growth rate ?","o":["0.5-1.0","1-1.5","1.5-2","> 2"],"a":3,"e":"Ans. is `d'' i.e., > 2 Rate/Phase Stationary population Slow growth Moderate growth Rapid growth Very Raped growth Explosive growth Annual rate of growth in % No growth <5 0.5 to 0.1 1.0 to 1.5 1.5 to 2.0 > 2.0","pyqMatches":[{"year":"2013","no":925,"q":"Population explosion (explosive growth) is defined as the growth rate ?","o":["0.5-1.0","1-1.5","1.5-2","> 2"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5864, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 475, '{"id":5864,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":475,"q":"Protein content in 100 grams of cow milk","o":["4.3","3.2","2.2","1.2"],"a":1,"e":"Ans. is ''b'' i.e., 3.2","pyqMatches":[{"year":"2014","no":1026,"q":"Protein content in 100 grams of cow milk","o":["4.3","3.2","2.2","1.2"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5865, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 476, '{"id":5865,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":476,"q":"One criteria for prudent diet?","o":["Fat intake 35-40% of total energy","Dietary cholesterole < 300 mg/1000Kcal per day","Salt intake <10 g/day","Saturated futs < 10% of total energy"],"a":3,"e":"Ans. is ''d'' i.e., Saturated fats < 10% of total energy Dietary goals prescribed by WHO expert committee prudent diet 3 Dietary modification is the principal preventive strategy in the prevention of CHD. The WHO Expert Committee (1) considered the following dietary changes to be appropriate for high incidence populations. Reduction of fat intake to 20-30 percent of total energy intake Consumption of saturated fats must be limited to less than 10 percent of total energy intake, some of the reduction in saturated fat may be made up by mono and poly-unsaturated fats. A reduction of dietary cholesterol to below 100 mg per 1000 kcal per day. An increase in complex carbohydrate consumption (i.e. vegetables, fruits, whole grains and legumes) Avoidance of alcohol consumption, reduction of salt intake to 5 g daily or less. Other specific interventions as part of primordial prevention of coronary heart disease To achieve a smoke free society Reduction of Blood pressure through prudent diet. Regular exercise, weight control & cessation of smoking. Regular Physical Activity.","pyqMatches":[{"year":"2013","no":942,"q":"One criteria for prudent diet?","o":["Fat intake 35-40% of total energy","Dietary cholesterole < 300 mg/1000Kcal per day","Salt intake <10 g/day","Saturated futs < 10% of total energy"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5866, 'PSM', 'Communicable Diseases', 'Hard', 'Preventive_&_Social_Medicine', 477, '{"id":5866,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":477,"q":"If a claw hand develops in a patient with Leprosy, th deformity is ?","o":["Grade 0","Grade I","Grade II","Grade III"],"a":2,"e":"Ans. is `c'' i.e., Grade II","pyqMatches":[{"year":"2013","no":905,"q":"If a claw hand develops in a patient with Leprosy, th deformity is ?","o":["Grade 0","Grade I","Grade II","Grade III"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5867, 'PSM', 'Nutrition', 'Moderate', 'Preventive_&_Social_Medicine', 478, '{"id":5867,"subject":"PSM","chapter":"Nutrition","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":478,"q":"All of the following are required more during lactation as compared to pregnancy, except ?","o":["Iron","Vitamin A","Niacin","Energy"],"a":0,"e":"Ans. is ''a'' i.e., Iron Required more during lactation as compared to pregnancy : Energy, Vitamin A, thiamin, riboflavin, Vitamin C, niacin, and Vitamin B12. Required more during pregnancy : Iron, protein, and folate. Same requirment in pregnancy and lactation : Fat, calcium, zinc, magnesium, and vitamin B6.","pyqMatches":[{"year":"2013","no":934,"q":"All of the following are required more during lactation as compared to pregnancy, except ?","o":["Iron","Vitamin A","Niacin","Energy"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5868, 'PSM', 'National Health Programmes', 'Moderate', 'Preventive_&_Social_Medicine', 479, '{"id":5868,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":479,"q":"All of the following are related to plague except ?","o":["Aedes aegypti index","Total flea index","Burrow index","Cheopis index"],"a":0,"e":"Ans. is ''a'' i.e., Aedes aegypti index Aedes aegypti index is used for yellow fever. In plague, flea indices are used. Flea indices Flea indices are useful measurments of the density of fleas. They are also useful in evaluating the efectiveness of a spraying programme. The following indices are widely used in rat flea surveys : -","pyqMatches":[{"year":"2013","no":899,"q":"All of the following are related to plague except ?","o":["Aedes aegypti index","Total flea index","Burrow index","Cheopis index"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5869, 'PSM', 'Communicable Diseases', 'Easy', 'Preventive_&_Social_Medicine', 480, '{"id":5869,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":480,"q":"Drug for prophylaxis of malaria in chloroquine resistant P.falciparum ?","o":["Mefloquine","Quinine","Halofantrine","Artesunate"],"a":0,"e":"Ans. is ''a'' i.e., Mefloquine Chemoprophylaxis of malaria Chemoprophylaxis is recommended for travellers from non-endemic areas, and as a short term measure for soldiers, police and labour forces serving in highly endemic areas. Chemoprophylaxis should begin a week before arrival in malarious area and continued for at least 4 weeks or preferably 6 weeks after leaving malarious area. Drugs used are : ? Chloroquine → DOC for chemoprophylaxis in chloroquine sensitive P. falciparum areas. Atovaquone/Proguanil → Used in areas with chloroquine or mefloquine resistant P. falciparum. Doxycycline → Used in areas with chloroquine or mefloquine resistant P. falciparum. Mefloquine → Used in areas with chloroquine resistant P. falciparum Hydroxychloroquine → Alternative to chloroquine in areas with chloroquine sensitive P. falciparum","pyqMatches":[{"year":"2013","no":894,"q":"Drug for prophylaxis of malaria in chloroquine resistant P.falciparum ?","o":["Mefloquine","Quinine","Halofantrine","Artesunate"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5870, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 481, '{"id":5870,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":481,"q":"An Englishman travels to a place which isresistant to chloroquine and mefloquine. What should he take as prophylaxis ?","o":["Primaquine","Hydrchlorquine","Proguanil","Artesunate"],"a":2,"e":"Ans. is ''c'' i.e., Proguanil","pyqMatches":[{"year":"2013","no":895,"q":"An Englishman travels to a place which isresistant to chloroquine and mefloquine. What should he take as prophylaxis ?","o":["Primaquine","Hydrchlorquine","Proguanil","Artesunate"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5871, 'PSM', 'Communicable Diseases', 'Easy', 'Preventive_&_Social_Medicine', 482, '{"id":5871,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":482,"q":"Annual infection rate of tuberculosis is defined as ?","o":["Percentage of total patients positive for tuberculin test","Percentage of new patients positive for tuberculin test","Percentage of sputum positive total patients","Percentage of sputum positive new patients"],"a":1,"e":"Ans. is ''b'' i.e., Percentage of new patients positive for tuberculin test Epidemiological indices of tuberculosis Indices or parameters are needed to measure the tuberculosis problem in a community as well as for planning and evaluation of control measures. The following epidemiological-indices are used in tuberculosis problem measurement and programme strategy :?","pyqMatches":[{"year":"2013","no":879,"q":"Annual infection rate of tuberculosis is defined as ?","o":["Percentage of total patients positive for tuberculin test","Percentage of new patients positive for tuberculin test","Percentage of sputum positive total patients","Percentage of sputum positive new patients"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5872, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 483, '{"id":5872,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":483,"q":"Present \"General fertility rates\" ?","o":["84","118","128","138"],"a":0,"e":"Ans. is ''a'' i.e., 84","pyqMatches":[{"year":"2013","no":930,"q":"Present \"General fertility rates\" ?","o":["84","118","128","138"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5873, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 484, '{"id":5873,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":484,"q":"D.latum transmitted by ?","o":["Cercaria through cyclops","Cercaria through fish meal","Plerocercoid through fish meal","Metacercaria in cyclops"],"a":2,"e":"Ans. is ''c'' i.e., Plerocercoid through fish meal","pyqMatches":[{"year":"2013","no":911,"q":"D.latum transmitted by ?","o":["Cercaria through cyclops","Cercaria through fish meal","Plerocercoid through fish meal","Metacercaria in cyclops"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5874, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 485, '{"id":5874,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":485,"q":"Patterns of Inter-relationships between persons in a society is ?","o":["Social structure","Social psychology","Herd structure","Social science"],"a":0,"e":"Ans. is ''a'' i.e., Social structure Patterns of inter-relationships between persons in a society is called social structure. Note - Study of human inter-relationship is called sociology.","pyqMatches":[{"year":"2013","no":958,"q":"Patterns of Inter-relationships between persons in a society is ?","o":["Social structure","Social psychology","Herd structure","Social science"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5875, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 486, '{"id":5875,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":486,"q":"Rash is absent in ?","o":["Scrub typhus","Epidemic typhus","Q. fever","Endemic typhus"],"a":2,"e":"Ans. is ''C'' i.e., Q. fever Q fever is caused by the bacterium Coxiella burnetii, commonly found in sheep, goats and cattle. The bacterium can also infect pets, including cats, dogs and rabbits. These animals transmit the bacteria through their urine, feces, milk and birthing products — such as the placenta and amniotic fluid. When these substances dry, the bacteria in them become part of the barnyard dust that floats in the air. The infection is usually transmitted to humans through their lungs, when they inhale contaminated barnyard dust,the organism can also gain entry into the body,through abrasions,conjuctivae or ingestion of contaminated food. Q fever is usually a mild disease with flu-like symptoms.In acute onset fever,chills,general malaise and headache ,There is no rash or local lesion. Rare complications includes Endocarditis. endocarditis can severely damage your heart valves. Endocarditis is the most deadly of Q fever''s complications. Lung issues. Some people who have Q fever develop pneumonia. This can lead to acute respiratory distress. Liver damage. Some people who have Q fever develop hepatitis. Encephalitis. Prevention can be done by Pasteurisation Prevention can be done by Pasteurisation","pyqMatches":[{"year":"2013","no":901,"q":"Rash is absent in ?","o":["Scrub typhus","Epidemic typhus","Q. fever","Endemic typhus"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5876, 'PSM', 'Environment & Occupational Health', 'Easy', 'Preventive_&_Social_Medicine', 487, '{"id":5876,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":487,"q":"Minimum contact period required during Chlorination?","o":["30 minutes","1 hrs.","2 hrs","4 hrs"],"a":1,"e":"Ans. is ''b'' i.e., 1 hrs. Principles of chlorination Water should be clear and free from turbidity. Turbidity impedes efficient chlorination. The chlorine demand of the water should be estimated. It is the amount of chlorine that is needed to destroy bacteria and to oxidize all the organic matter and ammoniacal substances present in water. Chlorine demand of water is the difference between the amount of chlorine added to the water and the amount of residual chlorine remaining at the end of a specific period of contact (usually 60 minutes) at a given temperature and pH of the water. The point at which the chlorine demand of the water is met is called breakpoint chlorination. If further chlorine is added beyond breakpoint, free chlorine begins to appear in water. The presence of free residual chlorine for a contact period of at least one hour is essential to kill bacteria and viruses. The minimum recommended concentration of free chlorine is 0.5mg/I for one hour. This free residual chlorine provides a margin of safety against subsequent microbial contamination. The sum of the chlorine demand of the specific water plus the free residual chlorine of .5 mg/L constitutes the correct dose of chlorine to be applied. It is worth noting here that recommended residual chlorine level for drinking water is 0.5 mg/ litre, while for swimming pool sanitation it is 1.0 mg/ litre and for water bodies & post disaster it is 0.7 mg/litre.","pyqMatches":[{"year":"2013","no":948,"q":"Minimum contact period required during Chlorination?","o":["30 minutes","1 hrs.","2 hrs","4 hrs"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5877, 'PSM', 'Environment & Occupational Health', 'Moderate', 'Preventive_&_Social_Medicine', 488, '{"id":5877,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":488,"q":"Sandfly transmits all, except ?","o":["Oriental sore","Leishmaniasis","Kala-azar","Relapsing fever"],"a":3,"e":"Ans. is ''d'' i.e., Relapsing fever Sandfly:? Habitats: Holes and crevices in walls, holes in trees, dark rooms, stables, and storerooms. Sanitation measures are carried out for a distance of 50 feet. Insecticide of choice: DDT (1 -2 gm/m2 single application) DDT is sprayed up to a height of 4 - 6 feet of wallsQ: as Sandfly cannot fly, it only hops Sandfly Sandfly species Diseases transmitted Phlebotomus argentipes Kala-azar (Visceral Leishmaniasis) Phlebotomus papatasi Sandfly fever, Oriental sore (Cutaneous Leishmaniasis) Phlebotomus sergenti Oriental sore (Cutaneous Leishmaniasis) Sergentomyia punjabensis Sandfly fever","pyqMatches":[{"year":"2013","no":949,"q":"Sandfly transmits all, except ?","o":["Oriental sore","Leishmaniasis","Kala-azar","Relapsing fever"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5878, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 489, '{"id":5878,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":489,"q":"Antiserum is available for passive immunization against ?","o":["Rabies","Typhoid","Meales","Mumps"],"a":0,"e":"Ans. is ''a'' i.e., Rabies For passive immunization A. Antiserum Rabies Tetanus Diphtheria B. Human normal immunoglobulins Rabies Tetanus Hepatitis A Measles Mumps C. Human specific immunoglobulins Diphtheria Hepatitis B Varicella","pyqMatches":[{"year":"2013","no":913,"q":"Antiserum is available for passive immunization against ?","o":["Rabies","Typhoid","Meales","Mumps"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5879, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 490, '{"id":5879,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":490,"q":"Oncherciasis elimination, operational definition ?","o":["O.volvulus transmission has reduced below a particular point","Intervention has stoped","No recrudescence","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above Oncherciasis elimination The reduction of infection and transmission to the extent that interventions can be stopped, but post-intervention surveillance is still necessary. Operational definition includes ? Intervention have reduced O.volvulus infection and transmission below the point where the parasite population is beilved to be irreversibly moving to its demise/extinction in a defined geographical area. Intervention have been stopped. Post-interventional surveillance for an appropriate period has demonstrated no recrudescence of transmission to a level suggesting recovery of O.volvulus population. Additional surveillance is still necessary for timely detection of recurrent infection, if a risk of reintroduction of infection from other area remains.","pyqMatches":[{"year":"2013","no":914,"q":"Oncherciasis elimination, operational definition ?","o":["O.volvulus transmission has reduced below a particular point","Intervention has stoped","No recrudescence","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5880, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 491, '{"id":5880,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":491,"q":"In ESI progamme central, state, Govt. employee contribute to the fund. Employer''s contribution is ?","o":["5.75%","4.75 %","3.75%","2.75%"],"a":1,"e":"Ans. is ''b'' i.e., 4.75% Finance of ESI scheme The scheme is run by contribution by employees and employers and grants from central and state governments -","pyqMatches":[{"year":"2013","no":961,"q":"In ESI progamme central, state, Govt. employee contribute to the fund. Employer''s contribution is ?","o":["5.75%","4.75 %","3.75%","2.75%"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5881, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 492, '{"id":5881,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":492,"q":"All insects have developed resistance to DDT except?","o":["Mosquito","Flea","Tsetse flies","Ticks"],"a":2,"e":"Ans. is ''c'' i.e., Tsetse flies Arthropods showing resistance to DDT → Arthropods showing no resistance to DDT Houseflies (e.g., Musca domestica) Moquito (Culex, Anopheles, Aedes) Flea (rat flea, Sand flea) Lice (Pediculus capitis/corporis, Phthirus pubis) Ticks & Mites Sandlies (Phlebotomus) Tsetse flies (Gluossianae)","pyqMatches":[{"year":"2013","no":950,"q":"All insects have developed resistance to DDT except?","o":["Mosquito","Flea","Tsetse flies","Ticks"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5882, 'PSM', 'Health Management & Services', 'Easy', 'Preventive_&_Social_Medicine', 493, '{"id":5882,"subject":"PSM","chapter":"Health Management & Services","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":493,"q":"Highest level of health care system in India -","o":["Primary health care","Secondary health care","Tertiary health care","All are same"],"a":2,"e":"Ans. is ''c'' i.e., Tertirary health care Levels of health care It is customary to describe health care service at 3 levels, viz. primary, secondary and tertiary care levels. o These levels represent different types of care involving varying degrees of complexity.","pyqMatches":[{"year":"2013","no":978,"q":"Highest level of health care system in India","o":["Primary health care","Secondary health care","Tertiary health care","All are same"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5883, 'PSM', 'Health Management & Services', 'Easy', 'Preventive_&_Social_Medicine', 494, '{"id":5883,"subject":"PSM","chapter":"Health Management & Services","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":494,"q":"Most basic level of Health Care System in India -","o":["Primary health care","Secondary health care","Tertiary health care","All are same"],"a":0,"e":"Ans. is ''a'' i.e., Primary health care","pyqMatches":[{"year":"2013","no":979,"q":"Most basic level of Health Care System in India","o":["Primary health care","Secondary health care","Tertiary health care","All are same"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5884, 'PSM', 'Immunization', 'Moderate', 'Preventive_&_Social_Medicine', 495, '{"id":5884,"subject":"PSM","chapter":"Immunization","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":495,"q":"Pre-exposure prophylaxis dose schedule for rabies vaccine given in all days except ?","o":["Day 0","Day 3","Day 7","Day 28"],"a":1,"e":"Ans. is ''b'' i.e., Day 3 Prevention of rabies Prevention of rabies may be of following types Post exposure prophylaxis Preexposure prophylaxis Post-exposure treatment of persons who have been vaccinated previously. Schedules of vaccination for post exposure prophylaxis A. Intramuscular schedules Routine shedule→ 6 doses on 0, 3, 7, 14 and 28 days with a booster on day 90. Abbreviated multisite schedule -4 2-1-1 regimen one dose is given in the right arm and one in left arm on day 0 after that one dose is given on day 7 and 21. B. Intradremal schedules 2-site intradermal schedule One dose of vaccine is given at each of two sites on days 0, 3, 7 and 28. 8-site intradermal schedule→ On day \"0\" vaccine is give at 8 sites, on day 7 vaccine is given at 4 sites, and on days 28 and 90 vaccine is given at one site. Pre-exposure prophylaxis Persons who run a high risk of repeated exposure such as laboratory staff working with rabies virus, veterinarian, animal handlers and wild -life officers should be protected by pre-exposure immunization. Cell-culture vaccine given on days 0, 7 and 21 or 28 (Total 3 doses) Further booster should be given at intervals of 2 years. In post-exposure prophylaxis of immunized patient 2 day intradermal regimen ( 1 site) → Day 0 and day 3 Intramuscular regimen → Day 0 4 site intradermal regimen_ (single-visit) → Day 0","pyqMatches":[{"year":"2013","no":906,"q":"Pre-exposure prophylaxis dose schedule for rabies vaccine given in all days except ?","o":["Day 0","Day 3","Day 7","Day 28"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5885, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 496, '{"id":5885,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":496,"q":"Encephalopathy can occur as complication of which vaccine ?","o":["OPV","Rubella","Measles","BCG"],"a":2,"e":"Ans. is ''c'' i.e., Measles","pyqMatches":[{"year":"2013","no":866,"q":"Encephalopathy can occur as complication of which vaccine ?","o":["OPV","Rubella","Measles","BCG"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5886, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 497, '{"id":5886,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":497,"q":"Population pyramid indicates ?","o":["Life expectancy","Fertility pattern","Sex ratio","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above Population pyramid The age and sex distribution of a population is best represented by population pyramid In countries with high birth rates as ours, it is broad based conical pyramid because of high birth rate and tapering of population with increase in age. In developed countries with low birth rate, the pyramid swells in the middle and is narrow at the base and is not so conical at the top. (dumb bell shaped). Utility of population pyramid Shape of population pyramid indicates fertility pattern","pyqMatches":[{"year":"2013","no":927,"q":"Population pyramid indicates ?","o":["Life expectancy","Fertility pattern","Sex ratio","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5887, 'PSM', 'Concept of Health & Disease', 'Hard', 'Preventive_&_Social_Medicine', 498, '{"id":5887,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":498,"q":"Green colour of triage is for which patient ?","o":["Low priority","Morbidity","Ambulatory","High priority"],"a":2,"e":"Ans. C. Ambulatory Triage When the quantity and severity of injuries overwhelm the operative capacity of health facilities, a different approach to medical treatment must be adopted. The usual principle of first come, first treated”, is not followed in mass emergencies. Triage consists of rapidly classifying the injured and the likelihood of their survival with prompt medical intervention. Higher priority is granted to victims whose immediate or long-term prognosis can be dramatically affected by simple intensive care. Moribund patients who require a great deal of attention, with questionable benefit have the lowest priority. The most common triage classification system used international is four colour code system. Red High priority treatment or transfer Yellow Medium priority Green Ambulatory patients Black Dead or moribund patients","pyqMatches":[{"year":"2019","no":126,"q":"Green colour of triage is for which patient ?","o":["Low priority","Morbidity","Ambulatory","High priority"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5888, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 499, '{"id":5888,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":499,"q":"Concurrent list of Indian Constitution includes which of the following?","o":["International immigration rule for quarantine","Prevention of extension of communicable disease from one unit to another","Mines and oilfield workers rules","Establishment and maintenance of drug standards"],"a":1,"e":"Ans. B. Prevention of extension of communicable disease from one unit to another The functions of the Union Health Ministry are set out in the seventh schedule of Article 246 of the constitution of India under three lists.","pyqMatches":[{"year":"2019","no":127,"q":"Concurrent list of Indian Constitution includes which of the following?","o":["International immigration rule for quarantine","Prevention of extension of communicable disease from one unit to another","Mines and oilfield workers rules","Establishment and maintenance of drug standards"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5889, 'PSM', 'Maternal & Child Health', 'Easy', 'Preventive_&_Social_Medicine', 500, '{"id":5889,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":500,"q":"Last point where reproductive and child health programme are include :","o":["Sub-centre","Anganwadi","District","Taluka"],"a":2,"e":"Ans.C. District The various activities of Reproductive and child Health Programme (RCH) arc targeted at the district level. “The RCH programme is based on a di iThrential approach. Inputs in all the districts have not been kept uniform. While the care component are the same for all districts, the weaker districts will get more support and sophisticated facilities are proposed for relatively advanced districts. On the basis of crude birth rate and female literacy rate – all the districts have been divided into three categories ‘A, B, & C’ All the districts will be covered in a phased manner over a period of three years.”","pyqMatches":[{"year":"2019","no":128,"q":"Last point where reproductive and child health programme are include :","o":["Sub-centre","Anganwadi","District","Taluka"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5890, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 501, '{"id":5890,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":501,"q":"Diagnostic power of a test to correctly diagnose a disease is-","o":["Negative predictive value","Positive predictive value","Sensitivity","Specificity"],"a":1,"e":"Ans.B. Positive predictive value Positive predictive value is the ability of a test to correctly diagnose the proportion of cases in which persons with a positive screening test result have the disease in question. Negative predictive value is the proportion of cases in which people with negative test result do not have the disease in question. Sensitivity is defined as the ability of the test to identify correctly all those who have the disease, i.e. true positive. Specificity is defined as the ability of the test to identify correctly those who do not have the disease, i.e. true negative.","pyqMatches":[{"year":"2019","no":130,"q":"Diagnostic power of a test to correctly diagnose a disease is","o":["Negative predictive value","Positive predictive value","Sensitivity","Specificity"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5891, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 502, '{"id":5891,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":502,"q":"Paradoxical carriers are-","o":["A person who acquires the microorganism due to his contact with the patient.","A person who acquires the microorganism another carrier.","A person who is clinically recovered from an infectious disease but still capable of transmitting the infectious agent to others.","None"],"a":1,"e":"Ans. B.A person who acquires the microorganism another carrier. Paradoxical carrier are defined as person who acquires the microorganism another carrier.","pyqMatches":[{"year":"2019","no":131,"q":"Paradoxical carriers are","o":["A person who acquires the microorganism due to his contact with the patient.","A person who acquires the microorganism another carrier.","A person who is clinically recovered from an infectious disease but still capable of transmitting the infectious agent to others.","None"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5892, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 503, '{"id":5892,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":503,"q":"According to IMNCI, a baby of 6 month age, criteria for fast breathing is more than _____/min","o":["60","50","40","30"],"a":1,"e":"Ans. B. 50 As the children get older, their breathing rate slows down. Therefore, the cut-off point has fast breathing will depend on the age of the child. o Fast breathing is present when the respiratory rate is :? Child less than 2 months of age : 60 breaths per minute Child aged 2 months upto 12 months:50 breaths per minute Child aged 12 months upto 5 years : 40 breaths per minute","pyqMatches":[{"year":"2019","no":132,"q":"According to IMNCI, a baby of 6 month age, criteria for fast breathing is more than _____/min","o":["60","50","40","30"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5893, 'PSM', 'Nutrition', 'Moderate', 'Preventive_&_Social_Medicine', 504, '{"id":5893,"subject":"PSM","chapter":"Nutrition","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":504,"q":"All of the following are examples of Dietary fibre except-","o":["Pectin","Lignin","Cellulose","Gums"],"a":3,"e":"Ans. D. Gums Dietary fibre consists of unabsorbable cell wall and other constituents of vegetable food like cellulose, lignin, hemicellulose, gums, pectins, glycoproteins and other polysaccharides. Dietary fibre absorbs water in the intestine, swells, increase bulk of stood by increasing water content of faeces and soften it, decreases transit time by facilitating colonic transit. “The presence of fibre shortens the transit times and increases the stool bulk” Dietary fibre is of two types:","pyqMatches":[{"year":"2019","no":133,"q":"All of the following are examples of Dietary fibre except","o":["Pectin","Lignin","Cellulose","Gums"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5894, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 505, '{"id":5894,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":505,"q":"Cross product ratio is determined by which study ?","o":["Case control","Cohort","Cross sectional","RCT"],"a":0,"e":"Ans.A. Case control study Cross product ratio : Risk in case control study is calculated by odds ratio (cross product ratio).","pyqMatches":[{"year":"2019","no":134,"q":"Cross product ratio is determined by which study ?","o":["Case control","Cohort","Cross sectional","RCT"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5895, 'PSM', 'Biostatistics', 'Easy', 'Preventive_&_Social_Medicine', 506, '{"id":5895,"subject":"PSM","chapter":"Biostatistics","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":506,"q":"In a normal curve what is the area that comes under 1 standard deviation-","o":["50%","68%","95%","100%"],"a":1,"e":"Ans. B. 68% 1 SD includes → 68% of values 2 SD includes → 95% of values 3 SD includes → 99.7% of values","pyqMatches":[{"year":"2019","no":135,"q":"In a normal curve what is the area that comes under 1 standard deviation","o":["50%","68%","95%","100%"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5896, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 507, '{"id":5896,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":507,"q":"2 year old boy of weight 12 kg with vitamin A deficiency what is oral dose of vitamin A","o":["50, 000 I.U","1 lakh I.U.","1.5 lakh I.U","2 lakh I.U"],"a":3,"e":"Ans.D. 2 lakh I.U Treatment: Oral therapy: The oral regimen of vitamin A is 200,000 IU on day of presentation, next day, and 2-4 weeks later. Children less than 1 year of age or less than 8 kg should receive half the dose of the above dose. Repeat 200,000 IU every 6 months up to 6 years of age to prevent recurrence. Parenteral therapy: If the patient has severe disease, is unable to take oral feeds, or has malabsorption, the preferable dose is 100,000 IU of vitamin A given intramuscularly. Children with severe measles should also receive vitamin A as they are very likely to be benefited from such therapy both in terms of saving sight and reducing case fatality. Prevention Prophylaxis consists of periodic administration of Vitamin A supplements. WHO recommended schedule, which is universally recommended is as follows: Infants 6–12 months old and any older children weighing less than 8 kg – 100,000 IU orally every 3–6 months Children over 1 year and under 6 years of age – 200,000 IU orally every 6 months Infants less than 6 months old, who are not being breastfed – 50,000 IU orally should be given before they attain the age of 6 months","pyqMatches":[{"year":"2014","no":1681,"q":"2 year old boy of weight 12 kg with vitamin A deficiency what is oral dose of vitamin A","o":["50, 000 I.U","1 lakh I.U.","1.5 lakh I.U","2 lakh I.U"],"a":3,"source":"NEET_2014_Paper.pdf"},{"year":"2019","no":136,"q":"2 year old boy of weight 12 kg with vitamin A deficiency what is oral dose of vitamin A","o":["50, 000 I.U","1 lakh I.U.","1.5 lakh I.U","2 lakh I.U"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2014","2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5897, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 508, '{"id":5897,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":508,"q":"Not a personal protective equipment","o":["Goggles","Badges for detecting radiation","Gloves","Lab coat"],"a":1,"e":"Ans. B.Badges for detecting radiation","pyqMatches":[{"year":"2019","no":137,"q":"Not a personal protective equipment","o":["Goggles","Badges for detecting radiation","Gloves","Lab coat"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5898, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 509, '{"id":5898,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":509,"q":"Confounding factor is defined as","o":["Factor associated with both the exposure and the disease and is distributed unequally in study and control groups.","Factor associated with exposure only and is distributed unequally in study and control groups.","Factor associated with both the exposure and the disease and is distributed equally in study and control groups","Factor associated with the disease and is distributed equally in study and control groups."],"a":0,"e":"Ans. A. Factor associated with both the exposure and the disease and is distributed unequally in study and control groups. Epidemiological studies search for the causes of diseases, based on associations with various risk factors that are measured in the study. In addition to the exposures that the study is investigating, there may be other factors that are associated with the exposure and are also risk factors for the disease. If the prevalence of these other factors differs between groups being compared, they will distort the observed association between the disease and exposure under study. Such variables may partially or completely account for any apparent association between an exposure variable and disease. These distorting factors are called confounding factors or variables. Thus a Confounding factor is defined as one which is associated with both the exposure and the disease and is distributed unequally in study and control groups. It is itself a risk.factor.for the disease.","pyqMatches":[{"year":"2019","no":138,"q":"Confounding factor is defined as","o":["Factor associated with both the exposure and the disease and is distributed unequally in study and control groups.","Factor associated with exposure only and is distributed unequally in study and control groups.","Factor associated with both the exposure and the disease and is distributed equally in study and control groups","Factor associated with the disease and is distributed equally in study and control groups."],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5899, 'PSM', 'Biostatistics', 'Easy', 'Preventive_&_Social_Medicine', 510, '{"id":5899,"subject":"PSM","chapter":"Biostatistics","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":510,"q":"Paired T test is defined as-","o":["Test used to assess quantitative observations before and after an intervention","Test that is used when the observation are in the form of proportions (for qualitative data)","Test applied when separate observations are made on individuals of two separate groups, and these need to be compared","None"],"a":0,"e":"Ans. A. Test used to assess quantitative observations before and after an intervention Paired t-tests The paired t-test is used to compare the values of means from two related samples, for example in a ‘before and after’ scenario. The difference between the means of the samples is unlikely to be equal to zero (due to sampling variation) and the hypothesis test is designed to answer the question “Is the observed difference sufficiently large enough to indicate that the alternative hypothesis is true”. The answer comes in the form of a probability – the p-value.","pyqMatches":[{"year":"2019","no":140,"q":"Paired T test is defined as","o":["Test used to assess quantitative observations before and after an intervention","Test that is used when the observation are in the form of proportions (for qualitative data)","Test applied when separate observations are made on individuals of two separate groups, and these need to be compared","None"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5900, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 511, '{"id":5900,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":511,"q":"Best representative of incidence of disease in different timeline-","o":["Histogram","Line diagram","Scattered diagram","Bar diagram"],"a":1,"e":"Ans. B. Line diagram Line diagrams are used to show the trend of events with passage of time. It is used to show the trend of events with passage of time and shows how the frequency of a particular event or variable vary over time.","pyqMatches":[{"year":"2019","no":141,"q":"Best representative of incidence of disease in different timeline","o":["Histogram","Line diagram","Scattered diagram","Bar diagram"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5901, 'PSM', 'Demography & Family Planning', 'Moderate', 'Preventive_&_Social_Medicine', 512, '{"id":5901,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":512,"q":"For trench type of sanitary filling the amount of land required for 2 meter deep trench for 10000 population is-","o":["1 acre","2 acre","3 acre","4 acre"],"a":0,"e":"Ans. A. 1 acre General WHO Guidelines for Shallow Trenches is 3-5 Metre for 100 People . So About 300-500 Meter of Shallow Trenches for 10,000 People. Also there should be a perimeter of 30 m around the trench. Now 1 Acre = 4046 Sq Meter [200 m X 200 m ] Hence Answer is 1 Acre.","pyqMatches":[{"year":"2019","no":142,"q":"For trench type of sanitary filling the amount of land required for 2 meter deep trench for 10000 population is","o":["1 acre","2 acre","3 acre","4 acre"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5902, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 513, '{"id":5902,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":513,"q":"Risk of genetic diseases in consanguineous marriage between first cousins?","o":["1-2%","4-8%","8-10%","12-14%"],"a":1,"e":"Ans. B.4-8% Consanguinity is a marriage between relatives and has various degrees. Closely related individuals have a higher chance of carrying the same alleles than those less closely related and therefore children from consanguineous marriages are more frequently homozygous for various alleles than those from non- consanguineous unions. Generally speaking, frequency of congenital malformations among newborns of first cousin unions is about 2 times the frequency among the general population. In other words instead of a rate of 2- 3% of birth defects in the general population, the risk to first cousin couples is around 4-6%.","pyqMatches":[{"year":"2019","no":143,"q":"Risk of genetic diseases in consanguineous marriage between first cousins?","o":["1-2%","4-8%","8-10%","12-14%"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5903, 'PSM', 'Epidemiology', 'Moderate', 'Preventive_&_Social_Medicine', 514, '{"id":5903,"subject":"PSM","chapter":"Epidemiology","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":514,"q":"Which is not a epidemiological indicator?","o":["ABER","Annual parasite index","Annual falciparum incidence","None of the Above"],"a":0,"e":"Answer – A. ABER ABER or Annual Blood Examination Rate is not an epidemiological indicator but an indicator of operational efficiency of Malaria Control Programme.","pyqMatches":[{"year":"2019","no":144,"q":"Which is not a epidemiological indicator?","o":["ABER","Annual parasite index","Annual falciparum incidence","None of the Above"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5904, 'PSM', 'Maternal & Child Health', 'Hard', 'Preventive_&_Social_Medicine', 515, '{"id":5904,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":515,"q":"Health center in remotest area for planning and management of schemes:","o":["Anganwadi","Block centre","Sub-centre","PHC"],"a":2,"e":"Ans.C. Sub-centre The Sub-Centre is the most peripheral and first contact point between the primary health care system and the community. Sub- Centres are assigned tasks relating to interpersonal communication in order to bring about behavioral change and provide services in relation to maternal and child health, family welfare, nutrition, immunization, diarrhoea control and control of communicable diseases programmes. The Sub-Centres are provided with basic drugs for minor ailments needed for taking care of essential health needs of men, women and children.","pyqMatches":[{"year":"2019","no":129,"q":"Health center in remotest area for planning and management of schemes:","o":["Anganwadi","Block centre","Sub-centre","PHC"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5905, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 516, '{"id":5905,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":516,"q":"Dose of diphtheria antitoxin is-","o":["1000 to 5000 IU","10000 to 100000 IU","1000 to 2000 IU","None"],"a":1,"e":"Ans. B. 10000 to 100000 IU DAT manufactured by Instituto Butantan is a sterile, transparent (clear) serum solution supplied in 10 mL ampoules containing 10,000 IU each. DAT must be stored in the refrigerator at 2 – 8°C (36 – 46°F). DO NOT FREEZE. Once an ampoule is opened, the DAT serum solution should be used immediately.","pyqMatches":[{"year":"2019","no":145,"q":"Dose of diphtheria antitoxin is","o":["1000 to 5000 IU","10000 to 100000 IU","1000 to 2000 IU","None"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5906, 'PSM', 'Maternal & Child Health', 'Easy', 'Preventive_&_Social_Medicine', 517, '{"id":5906,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":517,"q":"Vertical transmission of HIV is highest with-","o":["Elective caesarean section","High viral RNA load","Breast feeding","Term delivery"],"a":1,"e":"Ans. B. High viral RNA load Vaginal and emergency caesarean section deliveries, prematurity, and low CD4 cell count were most strongly associated with infant‚s infection status in univariate analyses . Children delivered vaginally or by emergency caesarean section were more likely to be infected than those delivered by elective caesarean section, with a reduction in risk of 79% associated with the latter (P<0.001). Similarly, infants delivered before 37 weeks were more than twice as likely to be infected than infants who were not premature. Caesarean section before onset of labour and rupture of membranes approximately halves the risk of mother-to-child transmission. Transmission rate: During pregnancy: 5–10% During labour and delivery:10–15% During breastfeeding:5–20% Overall without breastfeeding:15–25% Overall with breastfeeding to six months:20–35% Overall with breastfeeding to 18–24 months:30–45%","pyqMatches":[{"year":"2019","no":146,"q":"Vertical transmission of HIV is highest with","o":["Elective caesarean section","High viral RNA load","Breast feeding","Term delivery"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5907, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 518, '{"id":5907,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":518,"q":"Screening is not useful in which carcinoma","o":["Carcinoma prostate","Carcinoma colon","Carcinoma breast","Testicular tumor"],"a":3,"e":"Ans: D. Testicular tumor Screening is not useful in testicular tumors. Screening Recommendations for Asymptomatic Subjects: Breast: Self-examination. Clinical examination. Mammography. MRI. Cervical: Pap test (cytology). HPV test Colorectal: Sigmoidoscopy Fecal occult blood testing (FOBT) Colonoscopy Fecal DNA testing Fecal immunochemical testing (FIT) CT colonography Lung: Low-dose computed tomography (CT) scan Ovarian CA: CA marker-125 Transvaginal ultrasound Prostate: Prostate-specific antigen (PSA) Digital rectal examination (DRE) Skin: Complete skin examination","pyqMatches":[{"year":"2020","no":121,"q":"Screening is not useful in which carcinoma","o":["Carcinoma prostate","Carcinoma colon","Carcinoma breast","Testicular tumor"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5908, 'PSM', 'Concept of Health & Disease', 'Hard', 'Preventive_&_Social_Medicine', 519, '{"id":5908,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":519,"q":"CA-125 is a marker for the screening of ovarian cancer. To characterize this test, histopathological confirmation of ovarian cancer was done in a cohort of patients. 60/100 women who tested positive for this test had ovarian cancer and 20/100 women who tested negative had ovarian cancer. What is the negative predictive value of this test?","o":["20/100","40/100","60/100","80/100"],"a":3,"e":"Ans: D. 80/100 Negative predictive value (NPV): Ability of a screening test to identify correctly all those who don''t have the disease, out of all those who test negative on a screening test. Negative Predictive Value (NPV) = Number of true negatives/(Number of true negatives + number of false negatives). Disease presentDisease absent Test Positive 60 (a: TP) 40 (b: FP) Test Negative20 (c: FN) 80 (d: TN) Total 80 120 True negatives = 80 Total negatives = 100 Negative predictive value = 80/100 = 80%.","pyqMatches":[{"year":"2020","no":120,"q":"CA-125 is a marker for the screening of ovarian cancer. To characterize this test, histopathological confirmation of ovarian cancer was done in a cohort of patients. 60/100 women who tested positive for this test had ovarian cancer and 20/100 women who tested negative had ovarian cancer. What is the negative predictive value of this test?","o":["20/100","40/100","60/100","80/100"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5909, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 520, '{"id":5909,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":520,"q":"All of the following are duties of an ASHA worker except:","o":["Primary screening for prevalence of non-communica​ble diseases","Administering zero dose of DPT and OPV","Assessing the success of national programs under ANM","All"],"a":1,"e":"Ans: C. Administering zero dose of DPT and OPV Ref: Park 24Ie p936, 23Ie p449, 22Ie p414; Ministry of Health anti Family Welfare (MoHFW). (2005b). Reading Material for ASHA. Government of India) ASHA does''nt receive financial remuneration for administering zero dose of DPT and OPV is not the function of ASHA. ASHA Payments under Janani Suraksha Yojana (JSY): On 45th Day: 6 visits in institutional deliveries (Day 3, 7, 14, 21, 28, 7 visits in home deliveries (Day 1, 3, 7, 14, 21, 28, 42). Birth weight record Immunized with BCG, first dose of OPV & DPT Birth registration Mother & child are safe","pyqMatches":[{"year":"2015","no":915,"q":"All of the following are duties of an ASHA worker except:","o":["Primary screening for prevalence of non-communica​ble diseases","Administering zero dose of DPT and OPV","Assessing the success of national programs under ANM","All"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5910, 'PSM', 'Demography & Family Planning', 'Moderate', 'Preventive_&_Social_Medicine', 521, '{"id":5910,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":521,"q":"Which of the following conditions must be fulfilled for a PHC to become a first referral unit ?","o":["4-6 beds","15 workers","Emergency obsteric care","Basic laboratory services"],"a":2,"e":"Ans. is ''c'' i.e., Emergency obsteric care [Ref Textbook of Indian Health care - 728] Critical determinants of a first feferral unit 24-hour delivery services including normal and assisted deliveries Emergency obstetric care including surgical interventions like caesarean sections and other medical interventions, New-born care, Emergency care of sick children, Full range of family planning services including laproscopic services, Safe abortion services, Treatment of STI / RTI, Blood storage facility, Essential laboratory services, Referral (transport) services.","pyqMatches":[{"year":"2016","no":878,"q":"Which of the following conditions must be fulfilled for a PHC to become a first referral unit ?","o":["4-6 beds","15 workers","Emergency obsteric care","Basic laboratory services"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5911, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 522, '{"id":5911,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":522,"q":"Which of the following has responsibility of data collection for active malaria surveillance at PHC level ?","o":["DHO [District Health Officer]","MPW [Multipurpose worker]","MO-PHC [Medical Officer-PHC]","DMO [District Medical Officer]"],"a":2,"e":"Ans. is ''c'' i.e., MO-PHC [Medical Officer-PHC] [Ref Park 24\"/e p. 433] \"The Medical Officer-PHC has the overall responsibility for surveillance and laboratory services, and also supervices the spray\".","pyqMatches":[{"year":"2016","no":877,"q":"Which of the following has responsibility of data collection for active malaria surveillance at PHC level ?","o":["DHO [District Health Officer]","MPW [Multipurpose worker]","MO-PHC [Medical Officer-PHC]","DMO [District Medical Officer]"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5912, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 523, '{"id":5912,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":523,"q":"Endemic disease is defined as -","o":["Disease occuring regularly in expected frequency","Disease occuring irregularly","Disease occuring in excess of expected freqency","Disease affecting a large population"],"a":0,"e":"Ans. is ''a'' i.e., Disease occuring regularly in expected frequency [Ref Park 23\"/e p. 93 & 22\"/e p. 89] Sporadic → Disease occuring irregularly from time to time. Endemic → Disease occuring regularly in expected frequency. Epidemic → Disease occuring in excess of expected frequency. Pandemic → Epidemic affecting a large proportion of population over a wide geographic area.","pyqMatches":[{"year":"2016","no":792,"q":"Endemic disease is defined as","o":["Disease occuring regularly in expected frequency","Disease occuring irregularly","Disease occuring in excess of expected freqency","Disease affecting a large population"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5913, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 524, '{"id":5913,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":524,"q":"True about cohort study","o":["Descriptive study","Incidence study","Proceeds from effect to cause","All are correct"],"a":1,"e":"A cohort study is a type of analytic observational study Cohort study proceeds forward from cause to effect, i.e., the disease has not occurred in subjects (In contrast to case-control study which proceeds backward from effect to cause). It is also known as Prospective study, longitudinal study, Incidence study, forward-looking study. The features of cohort studies are : The cohorts are identified before the appearance of the disease under investigation. The study groups, so defined, are observed over some time to determine the frequency of disease among them. The study proceeds forward from cause to effect.","pyqMatches":[{"year":"2016","no":815,"q":"True about cohort study","o":["Descriptive study","Incidence study","Proceeds from effect to cause","All are correct"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5914, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 525, '{"id":5914,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":525,"q":"Secondary prevention is applicable to","o":["Causal factors","Early stage of disease","Late stage of disease","None of the above"],"a":1,"e":"Ans. is ''b'' i.e., Early stage of disease Primordial prevention → Before risk factor present. Primary prevention → Before onset of disease (risk factor present). Secondary prevention → In early stage of disease. Tertiary prevention → Late stage of disease.","pyqMatches":[{"year":"2012","no":774,"q":"Secondary prevention is applicable to","o":["Causal factors","Early stage of disease","Late stage of disease","None of the above"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5915, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 526, '{"id":5915,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":526,"q":"Relationship between positive predictive value and prevalence ?","o":["PPV α Prevalence","PPV α 1/Prevalence","PPV x Prevalence = 1","PPV = 1/Prevalence"],"a":0,"e":"Ans. is ''a'' i.e., PPV α Prevalence Prevalence affects the PPV the most. PPV is directly proportional to the prevalence of the disease in the population. However, both sensitivity and specificity can change the predictive value. The prevalence of a disease in a population is high, the more accurate will be the positive predictive value of a screening test. If the prevalence declines, the PPV will be low. NPV varies inversely with the prevalence","pyqMatches":[{"year":"2014","no":936,"q":"Relationship between positive predictive value and prevalence ?","o":["PPV α Prevalence","PPV α 1/Prevalence","PPV x Prevalence = 1","PPV = 1/Prevalence"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5916, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 527, '{"id":5916,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":527,"q":"HIV screening for blood transfusion is done by -","o":["NACO","ASHA","Ministry of education","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., NACO [Ref Park 23rd/e p. 437] Access to safe blood for the needy is the primary responsibility of NACO (National AIDS control organization). Guidelines for blood bank, blood donors and dialysis unit have been formulated. The strategy is to ensure safe collection, processing, storage and distribution of blood and blood products. Testing of every unit of blood is mandatory for HIV, HBV, HCV, malaria, syphilis.","pyqMatches":[{"year":"2014","no":971,"q":"HIV screening for blood transfusion is done by","o":["NACO","ASHA","Ministry of education","None of the above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5917, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 528, '{"id":5917,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":528,"q":"Vitamin deficient in Famines ?","o":["A","D","B12","B6"],"a":0,"e":"Ans. is ''a'' i.e.,A [Ref Food scarcity and Famine p. 100] In times of food scarcity and famine, the most important deficiency disease is xerophthalmia (vitamin A deficiency), which can cause permanent blindness and may also contribute to increased incidence, severity and duration of infectious diseases like measles, diarrhea and respiratory tract infection. Where people are totally dependent on food aid rations, other deficiency diseases may also develop :-","pyqMatches":[{"year":"2014","no":1041,"q":"Vitamin deficient in Famines ?","o":["A","D","B12","B6"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5918, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 529, '{"id":5918,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":529,"q":"Which is best to represent the data of following table - Year 1991199219931994 Number of LBW bodies 75 125 50 25","o":["Bar chart","Histogram","Frequency polygone","Scatter diagram"],"a":0,"e":"Ans. is ''a'' i.e.,Bar chart We can plot the low birth statistics of a hospital on Bar chart, histogram or frequency polygon depending on what type of data we want. To know the total number of LBW neonates in different years and compare the frequencies Bar chart. To know the number of LBW neonates in different range of weights at a given time -) Histogram or frequency polygone.","pyqMatches":[{"year":"2014","no":1075,"q":"Which is best to represent the data of following table - Year 1991199219931994 Number of LBW bodies 75 125 50 25","o":["Bar chart","Histogram","Frequency polygone","Scatter diagram"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5919, 'PSM', 'National Health Programmes', 'Easy', 'Preventive_&_Social_Medicine', 530, '{"id":5919,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":530,"q":"Observation under nursing care for 24 hours in an hospital is defined as ?","o":["Inpatient","Outpatient","Observation status patient","Urgent care patient"],"a":2,"e":"Ans. is ''c'' i.e., Observation status patient Observation status patients : These are neither inpatients nor outpatients. These patients are placed in a hospital bed (often in an inpatient unit) after displaying signs/symptoms that require additional work-up. Observational stay is usually limited to 24 hours then the physician must determine whether patient''s condition warrants inpatient addmission or discharge. If the patient is discharged it is called observation status pedient, however if the patient is admitted to the hospital then status is changed to inpatient. Inpatient : A patient is admitted in hospital room for an overnight or more than that. Outpatient : A patient receives a diagnosis and/or treatment but does not stay overnight.","pyqMatches":[{"year":"2015","no":927,"q":"Observation under nursing care for 24 hours in an hospital is defined as ?","o":["Inpatient","Outpatient","Observation status patient","Urgent care patient"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5920, 'PSM', 'Epidemiology', 'Moderate', 'Preventive_&_Social_Medicine', 531, '{"id":5920,"subject":"PSM","chapter":"Epidemiology","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":531,"q":"Not true about strategic plan for malaria control 2012​2017 ?","o":["Objective is API < 1 per 10,000","50% reduction in mortality by 2017","Annual incidence < 10 per 1000 by 2017","Complete treatment to at least 80% of patients"],"a":2,"e":"Ans. is ''c'' i.e., Annual incidence < 10 per 1000 by 2017 Strategic action plan for malaria control in India : 2012-2017 Objective of plan is to achieve API < 1 per 10,000 population by the end of 2017. Goals of strategic plan are :","pyqMatches":[{"year":"2015","no":926,"q":"Not true about strategic plan for malaria control 2012​2017 ?","o":["Objective is API < 1 per 10,000","50% reduction in mortality by 2017","Annual incidence < 10 per 1000 by 2017","Complete treatment to at least 80% of patients"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5921, 'PSM', 'Communicable Diseases', 'Easy', 'Preventive_&_Social_Medicine', 532, '{"id":5921,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":532,"q":"A problem village is defined as if water source is ?","o":["> 0.5 km","> 1 km","> 1.6 km","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., > 1.6 km [Ref Park 22\"`I le p. 428 & 21\"/e p. 418] A problem village has been defined as one Where no source of safe water is available within a distance of 1.6 km, or Where water is available at a depth of more than 15 meters, or Where water source has excess salinity, iron, fluorides and other toxic elements, or Where water is exposed to the risk of cholera.","pyqMatches":[{"year":"2015","no":925,"q":"A problem village is defined as if water source is ?","o":["> 0.5 km","> 1 km","> 1.6 km","None of the above"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5922, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 533, '{"id":5922,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":533,"q":"Human, animal, fomite or objects from which infective organism enters the host is called ?","o":["Source","Reservoir","Carrier","None"],"a":0,"e":"Ans. is ''a'' i.e., Source [Ref: Park 23rdle p.92-97] Source is ''the person, animal, object or substance from which infectious agent passes to host'', i.e. man acquires infection from source. Reservoir is ''any person, animal, insect, plant, soil or substance in which an infectious agent lives and multiplies''. Infectious agent is dependent on reservoir for survival. From reservoir it can be transmitted to susceptible host. Thus a reservoir may act as a source of infection when a person acquires infection directly from a reservoir.","pyqMatches":[{"year":"2015","no":810,"q":"Human, animal, fomite or objects from which infective organism enters the host is called ?","o":["Source","Reservoir","Carrier","None"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5923, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 534, '{"id":5923,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":534,"q":"Reservoir is defined as ?","o":["Person, animal or object from which infectious agent is transmitted to host","Person, animal or substance in which infectious agent lives and multiplies","Person or animal in which infectious agent causes a disease","None of the above"],"a":1,"e":"Ans. is ''b'' i.e., Person, animal or substance in which infectious agent lives and multiplies.","pyqMatches":[{"year":"2015","no":811,"q":"Reservoir is defined as ?","o":["Person, animal or object from which infectious agent is transmitted to host","Person, animal or substance in which infectious agent lives and multiplies","Person or animal in which infectious agent causes a disease","None of the above"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5924, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 535, '{"id":5924,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":535,"q":"All are included in sleep hygiene except ?","o":["Healthy diet","Sleeping on time","Sleeping in dark room","Exercise before sleep"],"a":3,"e":"Ans. is ''d'' i.e.,Exercise before sleep [Ref Comprehensive Guide for sleep p.173] Sleep hygiene can be considered the cornerstone of environmental modification and consists of developing good sleep habits and an environment that is conducive to sleep. Sleep hygiene includes the physical sleep setting, sleep schedule and sleep practices (e.g. pre-bedtime routine), all of which influence effective sleep. The principles of sleep hygiene include ?","pyqMatches":[{"year":"2015","no":924,"q":"All are included in sleep hygiene except ?","o":["Healthy diet","Sleeping on time","Sleeping in dark room","Exercise before sleep"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5925, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 536, '{"id":5925,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":536,"q":"Not included in Bradford Hill''s criteria ?","o":["Strength of association","Consistency of association","Specificity of association","Lack of temporal association"],"a":3,"e":"Ans. is ''d'' i.e., Lack of temporal association [Ref Park 23\"/e p. 88-89] It is the presence of temporal association (not lack or absence) that forms a criteria for causal relationship. Criteria that suggest causal relationship (Bradford Hill''s criteria) Likehood of a causal relationship is increased by the presence of the following criteria :?","pyqMatches":[{"year":"2015","no":813,"q":"Not included in Bradford Hill''s criteria ?","o":["Strength of association","Consistency of association","Specificity of association","Lack of temporal association"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5926, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 537, '{"id":5926,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":537,"q":"Regarding PPV vaccine following is true ?","o":["Given at birth","Obtained from cell wall polysaccharide","Indicated in sickle cell disease","Commonly used"],"a":2,"e":"Ans. is ''c'' i.e., Indicated in sickle cell disease [Ref Essentials of microbiology ydie p. 391] Pneumococcal polysaccharide vaccine (PPV or PPSV) is prepared from capsular (not cell wall) polysaccharide. It is not given before 2 years of age It is not for general use, but given in conditions which predispose to pneumococcal infection, like sickle cell anemia.","pyqMatches":[{"year":"2015","no":923,"q":"Regarding PPV vaccine following is true ?","o":["Given at birth","Obtained from cell wall polysaccharide","Indicated in sickle cell disease","Commonly used"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5927, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 538, '{"id":5927,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":538,"q":"Most important criterian in causal relationship hypothesis ?","o":["Temporal association","Coherence of association","Specificity of association","Strength of association"],"a":0,"e":"Ans. is ''a'' i.e., Temporal association [Ref Park 23rd/e p.89] Most important criteria → temporal association Weakest and most difficult criteria to establish → specificity of association","pyqMatches":[{"year":"2015","no":814,"q":"Most important criterian in causal relationship hypothesis ?","o":["Temporal association","Coherence of association","Specificity of association","Strength of association"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5928, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 539, '{"id":5928,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":539,"q":"The weakest criterian in causal relatianship hypothesis?","o":["Temporal association","Coherence of association","Specificity of association","Strength of association"],"a":2,"e":"Ans. is ''c'' i.e., Specificity of association","pyqMatches":[{"year":"2015","no":815,"q":"The weakest criterian in causal relatianship hypothesis?","o":["Temporal association","Coherence of association","Specificity of association","Strength of association"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5929, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 540, '{"id":5929,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":540,"q":"Benefit of screening is ?","o":["Prevention of disease/cancer","Early treatment of disease","Provide rehabilitation","Diagnosing all the missing cases"],"a":1,"e":"Ans. is ''b'' i.e., Early treatment of disease Screening is the active search for the disease among apparently healthy people. Screening intends to identify healthy person those likely to have a disease or at increased risk of a disease understudy, thus enabling earlier intervention and management in the hope to reduce mortality and suffering from a disease. Screening is a type of secondary prevention → Early diagnosis, treatment","pyqMatches":[{"year":"2015","no":816,"q":"Benefit of screening is ?","o":["Prevention of disease/cancer","Early treatment of disease","Provide rehabilitation","Diagnosing all the missing cases"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5930, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 541, '{"id":5930,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":541,"q":"Benefit of RCT ?","o":["Faster study","Cheaper study","No selection bias","Suitable for rare disease"],"a":2,"e":"Ans. is ''c'' i.e., No selection bias [Ref Park 23rdle p.81-83] Randomization is the heart of RCT. Randomization is a statistical procedure by which the participants are allocated into study group (in which intervention is given) and control group/reference group (in which intervention is not given). It is worth noting that randomisation is done while dividing the participants into study group and control (reference) group, and not while selecting subjects for study, i.e. randomization is done after the sample of subjects has already been selected. Therefor, each participant has ''equal and known chance'' of falling into either study group or control group. Randomization is an attempt to eliminate bias and allow comparability. It will give the greatest confidence that the groups are comparable so that \"like\" can be compared with \"like\". It ensures that the investigator has no control over allocation of participants to either study or control group, thus eliminating what is known as selection bias.","pyqMatches":[{"year":"2015","no":819,"q":"Benefit of RCT ?","o":["Faster study","Cheaper study","No selection bias","Suitable for rare disease"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5931, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 542, '{"id":5931,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":542,"q":"As per ICDS scheme, there should be one Anganwadi centre for a population of ?","o":["1000-1500","2000-25000","400-800","100-200"],"a":2,"e":"Ans. is ''c'' i.e.,400-800 The recommendations of Anganwadi center are :?","pyqMatches":[{"year":"2015","no":912,"q":"As per ICDS scheme, there should be one Anganwadi centre for a population of ?","o":["1000-1500","2000-25000","400-800","100-200"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5932, 'PSM', 'Demography & Family Planning', 'Moderate', 'Preventive_&_Social_Medicine', 543, '{"id":5932,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":543,"q":"True about Anganwadi worker is all except ?","o":["Mostly female","Training for 4 months","Under ICDS scheme","Covers a population of 2000"],"a":3,"e":"Ans. is ''D'' i.e., Covers a population of 2000 Anganwadi center is mainly managed by Anganwadi worker. Mostly Anganwadi worker is a female worker. She is a health worker chosen from the community and given 4 months training in health, nutrition and childcare. one AWC is for 400-800 population","pyqMatches":[{"year":"2015","no":911,"q":"True about Anganwadi worker is all except ?","o":["Mostly female","Training for 4 months","Under ICDS scheme","Covers a population of 2000"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5933, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 544, '{"id":5933,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":544,"q":"Most commonly used blinding technique in epidemiological studies ?","o":["Single blinding","Double blinding","Triple blinding","None of the above"],"a":1,"e":":C Ans. is ''b > c'' i.e., Double blinding > Triple blinding [Ref Statistics and epidemiology 3''/e p.46] Most commonly used blinding is double blinding, i.e. most of the epidemiological studies are started as double blinded. But more aften than not it becomes triple blinded as more than two people in the study are blinded → for example the statician (analyzer) performing the analysis is often blinded in addition to doctor (investigator) and patient (study subject).","pyqMatches":[{"year":"2015","no":820,"q":"Most commonly used blinding technique in epidemiological studies ?","o":["Single blinding","Double blinding","Triple blinding","None of the above"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5934, 'PSM', 'Immunization', 'Hard', 'Preventive_&_Social_Medicine', 545, '{"id":5934,"subject":"PSM","chapter":"Immunization","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":545,"q":"In disaster management following are practiced except","o":["Triage","Rehabilitation","Mass vaccination","Disaster response"],"a":2,"e":"Ans. is ''c'' i.e., Mass vaccination Disaster Management includes three aspects:","pyqMatches":[{"year":"2015","no":910,"q":"In disaster management following are practiced except","o":["Triage","Rehabilitation","Mass vaccination","Disaster response"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5935, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 546, '{"id":5935,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":546,"q":"Most effective blinding technique ?","o":["Single blinding","Double blinding","Triple blinding","Any of the above"],"a":2,"e":"Ans. is ''c'' i.e., Triple blinding [Ref Read below] Most commonly use blinding → Double blinding Best blinding technique to eliminate bias → Triple blinding","pyqMatches":[{"year":"2015","no":821,"q":"Most effective blinding technique ?","o":["Single blinding","Double blinding","Triple blinding","Any of the above"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5936, 'PSM', 'Miscellaneous', 'Hard', 'Preventive_&_Social_Medicine', 547, '{"id":5936,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":547,"q":"In disaster management all are true except","o":["Mitigation before a disaster strikes","Response in pre-disaster phase","Yellow colour is for medium priority","Gastroenteritis is commonest infection after disaster"],"a":1,"e":"Ans. is ''B'' i.e., Response in pre-disaster phase Disaster management Disaster Impact Most injuries are sustained during the impact, and thus the greatest need for emergency care occurs in the first few hours. The management can be divided into:- Search, rescue and first aid: Most immediate help comes from uninjured survivors. Field care: As many injured patients come simultaneously, emergency services should be proper in terms of priority and numbers of facilities. Triage: Triage consists of classifying the injured based on the severity of injuries and the likelihood of their survival with prompt medical intervention. The most common triage classification system used internationally is four colour code system:?","pyqMatches":[{"year":"2015","no":909,"q":"In disaster management all are true except","o":["Mitigation before a disaster strikes","Response in pre-disaster phase","Yellow colour is for medium priority","Gastroenteritis is commonest infection after disaster"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5937, 'PSM', 'Demography & Family Planning', 'Moderate', 'Preventive_&_Social_Medicine', 548, '{"id":5937,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":548,"q":"Which of one of the following is NOT a utilization rate?","o":["Population bed ratio","Bed occupancy rate","Bed turnover ratio","Average length of stay"],"a":0,"e":"Ans. is ''a'' i.e., Population bed ratio [Ref Park 23rd/e p. 26 & 22\"d/e p. 25]","pyqMatches":[{"year":"2015","no":822,"q":"Which of one of the following is NOT a utilization rate?","o":["Population bed ratio","Bed occupancy rate","Bed turnover ratio","Average length of stay"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5938, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 549, '{"id":5938,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":549,"q":"True about combined prospective- retrospective study true is ?","o":["Exposure (+) nt, disease (+) nt","Exposure (+) nt, disease (-) nt","Exposure (-) nt, disease (+) nt","Exposure (-) nt, disease (-) nt"],"a":0,"e":"Ans. is ''a'' i.e., Exposure (+) nt, disease (+) nt [Ref Park 23\"''/e p. 79-85] There are following types of cohort study:? A) Prospective cohort study Outcome has not yet occurred when the study has begun: Only exposure has occurred; we look for development of same disease in both exposed and non-exposed groups B) Retrospective cohort study Both exposure as well as outcome have occurred when the study has begun: First we go back in time and take only exposure into consideration (cohorts identified from past hospital/ college records), then look for development of same disease in both exposed and non-exposed groups C) Combined prospective-retrospective cohort study Both exposure as well as outcome have occurred when the study has begun: First we go back in time and take only exposure into consideration (cohorts identified from past hospital/ college records), then look for development of same disease in both exposed and non-exposed groups; later cohort is followed prospectively into future for outcome.","pyqMatches":[{"year":"2015","no":824,"q":"True about combined prospective- retrospective study true is ?","o":["Exposure (+) nt, disease (+) nt","Exposure (+) nt, disease (-) nt","Exposure (-) nt, disease (+) nt","Exposure (-) nt, disease (-) nt"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5939, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 550, '{"id":5939,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":550,"q":"Micropolysopora faeni causes ?","o":["Baggasosis","Farmer''s lung","Suberosis","Sequousis"],"a":1,"e":"Ans. is ''B'' i.e., Farmer''s lung Micropolyspora faeni in Hay or grain dust causes farmer''s lung. Anthracosis Silicosis Siderosis Byssinosis Farmer''s lung Sequousis Suberosis Coal dust Silica Iron Cotton dust (textile industry) Hay or grain dust (micropolyspora faeni) Detergent worker''s lung Baggassosis Moldy red wood saw dust Moldy cork dust Enzyme additives Sugarcane dust (thermoactinomyces sacchari)","pyqMatches":[{"year":"2015","no":908,"q":"Micropolysopora faeni causes ?","o":["Baggasosis","Farmer''s lung","Suberosis","Sequousis"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5940, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 551, '{"id":5940,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":551,"q":"Slection bias occurs during ?","o":["Recruitment","Treatment","Analysis","Observation"],"a":0,"e":"Ans. is ''a'' i.e., Recruitment [Ref: Essentials of epidemiology in Public Health p.270] Selection biases are distortion that result from procedure used to select subjects and from factors that influence study participation. Groups to be compared are differentially susceptible to the outcome even before the experimental maneuver is performed. Selection bias usually occurs at the Stage of recruitment of participants. Selection biases is less likely to occur in a cohort study compared to case-control or cross-sectional study because study participant are selected before the outcome occurs. Randomized control trials do not have selection bias as randomization eliminates selection (investigator) bias.","pyqMatches":[{"year":"2015","no":827,"q":"Slection bias occurs during ?","o":["Recruitment","Treatment","Analysis","Observation"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5941, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 552, '{"id":5941,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":552,"q":"Incineration is used for which category of waste ?","o":["Category 1","Category 7","Category 4","Category 10"],"a":0,"e":"Ans. is ''a'' i.e., Category 1 [Ref Park 23`ale p.793-794] Incineration is done for category 1,2,3 & 6","pyqMatches":[{"year":"2015","no":907,"q":"Incineration is used for which category of waste ?","o":["Category 1","Category 7","Category 4","Category 10"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5942, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 553, '{"id":5942,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":553,"q":"Selection bias occurs mainly in","o":["Cohort study","Case-control study","RCT","All have equal chances"],"a":1,"e":"Ans. is ''b'' i.e., Case-control study Case-control study > cross-sectional study > Retrospective cohort study > Prospective cohort study > RCT Selection bias: Cases and controls may not be representative of the population or there may be systematic differences between both.","pyqMatches":[{"year":"2015","no":828,"q":"Selection bias occurs mainly in","o":["Cohort study","Case-control study","RCT","All have equal chances"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5943, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 554, '{"id":5943,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":554,"q":"All are incinerated except ?","o":["Human anatomical waste","Animal waste","Infected solid waste","Broken thermometers"],"a":3,"e":"Ans. is ''d'' i.e.,Broken thermometers [Ref: Park 23\"1/e p. 791 & 22\"/e p. 738] \"Waste types not to be incinerated are: (a) pressurized gas container; (b) large amount of reactive chemical wastes; (c) silver salts and photographic or radiographic wastes; (d) Halogenated plastics such as PVC; (e) waste with high mercury or cadmium content, such as broken thermometers, used batteries, and lead- lined wooden panels; and (J) sealed ampules or ampules containing heavy metals\"","pyqMatches":[{"year":"2015","no":906,"q":"All are incinerated except ?","o":["Human anatomical waste","Animal waste","Infected solid waste","Broken thermometers"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5944, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 555, '{"id":5944,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":555,"q":"Best study technique to study the occurence of rare adverse effects of drug ?","o":["Case-control study","Cohort study","Clinical trial/experimental study","Cross-sectional study"],"a":2,"e":"Ans. is ''c'' i.e., Clinical trial/experimental study [Ref Clinical Research for medicine 2009/e p.62] Experimental epidemiology is also called trial. Broadly speaking, a trial refers to putting something to a test. This allows the term to be used in reference to a test of a treatment for the sick or a test of a preventive measure intended to avert illness, injury or disease. Therefore, the defining feature of an experimental study is its ability to allocate or assign interventions or treatment to experiment unit. In simple words, the study of a treatment (Drugs, surgical intervention) or preventive measure (e.g. vaccination) on living subjects is known as experimental study or trial.","pyqMatches":[{"year":"2015","no":829,"q":"Best study technique to study the occurence of rare adverse effects of drug ?","o":["Case-control study","Cohort study","Clinical trial/experimental study","Cross-sectional study"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5945, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 556, '{"id":5945,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":556,"q":"Which category waste is disposed in red bags ?","o":["Category 1","Category 2","Category 3","Category 10"],"a":2,"e":"Ans. is ''c'' i.e.,Category 3 [Ref Park 23''/e p.793, 794]","pyqMatches":[{"year":"2015","no":905,"q":"Which category waste is disposed in red bags ?","o":["Category 1","Category 2","Category 3","Category 10"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5946, 'PSM', 'Epidemiology', 'Moderate', 'Preventive_&_Social_Medicine', 557, '{"id":5946,"subject":"PSM","chapter":"Epidemiology","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":557,"q":"Bladder cancer can occur in those who are working in chimney for 25 years. Which is the best study for this relationship ?","o":["Meta-analysis","Cross-sectional study","Randomized control trial with double blinding","Cohort study"],"a":0,"e":"Ans. is ''a'' i.e., Meta-analysis As a single study unit, double blind RCT is the best: \"The efficacy of new interventions are most readily accepted if the results are from randomized controled trial\" Peer Review & Biomedical publication However, overall meta-analysis is a better study since it combines the data from multiple RCT and also from other types of study. \"Randomized controlled trials (RCT) provide the stongest, most relevant evidence to inform practice. Some evidence hierarchies place systematic review and meta-analysis above RCTs since these often combine data from multiple RCTs, and possibly from other study type as well\" – Epidemiology at a glance So, systematic review and meta-analysis of RCTs are the best epidemiological studies.","pyqMatches":[{"year":"2015","no":830,"q":"Bladder cancer can occur in those who are working in chimney for 25 years. Which is the best study for this relationship ?","o":["Meta-analysis","Cross-sectional study","Randomized control trial with double blinding","Cohort study"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5947, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 558, '{"id":5947,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":558,"q":"Waste Sharps should be disposed in ?","o":["Black bag","Yellow bag","Blue bag","None of these"],"a":2,"e":"Ans. is ''c'' i.e.,Blue bag [Ref Park 23''/e p. 793-794]","pyqMatches":[{"year":"2015","no":904,"q":"Waste Sharps should be disposed in ?","o":["Black bag","Yellow bag","Blue bag","None of these"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5948, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 559, '{"id":5948,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":559,"q":"SI unit of luminal intesity is -","o":["Candela","Lumen","Lux","Coulomb"],"a":0,"e":"Ans. is ''a'' i.e., Candela [Ref BASAK p.4] Candela is the SI base unit of luminous intensity, i.e. luminous power per unit solid angle emitted by a point light source in a particular direction. SI unit of luminous intensity -÷ Candela SI unit of luminous flux -± Lumen SI unit of illuminance -÷ Lux","pyqMatches":[{"year":"2015","no":903,"q":"SI unit of luminal intesity is","o":["Candela","Lumen","Lux","Coulomb"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5949, 'PSM', 'Epidemiology', 'Hard', 'Preventive_&_Social_Medicine', 560, '{"id":5949,"subject":"PSM","chapter":"Epidemiology","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":560,"q":"Which is an example of case control study ?","o":["Thalidomide and teratogenicity","Framingham heart study","PVC and angiosarcoma of liver","Doll & Hill Study"],"a":0,"e":"Ans. is ''a'' i.e., Thalidomide and teratogenicity [Ref: Park 23rd /e p. 74, 75]","pyqMatches":[{"year":"2015","no":831,"q":"Which is an example of case control study ?","o":["Thalidomide and teratogenicity","Framingham heart study","PVC and angiosarcoma of liver","Doll & Hill Study"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5950, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 561, '{"id":5950,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":561,"q":"Anemometer measures ?","o":["Humidity","Air velocity","Room temperature","Radiant temperature"],"a":1,"e":"Ans. is ''b'' i.e., Air velocity [Ref Park 23''/e p. 749 & 22\"d/e p. 695]","pyqMatches":[{"year":"2015","no":902,"q":"Anemometer measures ?","o":["Humidity","Air velocity","Room temperature","Radiant temperature"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5951, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 562, '{"id":5951,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":562,"q":"Immunity starts after how many days of yellow fever vaccination ?","o":["7-10 days","2-3 weeks","4-5 weeks","2-3 months"],"a":0,"e":"Ans. is ''a'' i.e., 7-10 days [Ref Park 23rd /e p. 283] Yellow fever vaccine It is a live attenuated freez dried (lyophilized) vaccine, prepared from 17 D strain. It is given by subcutaneous route at insertion of deltoid. Immunity lasts from 7 days of vaccination till 35 years. The validity of the vaccination certificate begins 10 days after the date of vaccination and extends upto 10 years. Diluent used for reconstitution is cold physiological saline and reconstituted vaccine should be used within 30 minutes. Cold chain temperature for storage is -30° to +5°C. Yellow fever vaccine is the only live vaccine that can be given in pregnancy, if required. Yellow fever and cholera vaccine cannot be given together, a minimum gap of 3 weeks is required between the two.","pyqMatches":[{"year":"2015","no":833,"q":"Immunity starts after how many days of yellow fever vaccination ?","o":["7-10 days","2-3 weeks","4-5 weeks","2-3 months"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5952, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 563, '{"id":5952,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":563,"q":"Daylight factor in the kitchen should be ?","o":["5%","8%","10%","15%"],"a":2,"e":"Ans. is ''c'' i.e.,10% [Ref Park 22\"d /e p. 687, 688] Minimum recommended day light factor : Living room → 8% Kitchens → 10%","pyqMatches":[{"year":"2015","no":901,"q":"Daylight factor in the kitchen should be ?","o":["5%","8%","10%","15%"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5953, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 564, '{"id":5953,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":564,"q":"Which Dipheria vaccine is recommended in a 14 years old girl ?","o":["DPT","DT","Tdap","None"],"a":2,"e":"Ans. is ''c'' i.e., Tdap [Ref: www.tapcoi.com] According to IAP (Indian Academy of Paediatricians) Tdap is recommended for adolescents (10-18 years). (Note Tdap contains a lower concentration of diphtheria and pertusis toxoids than DtaP) Note: DPT → Diphtheria, Cellular pertussis, Tetanu, used before 7 years DtaP → Diphtheria, Tetanus, acellular pertussis Tdap → Tetanus, diphtheria (low dose), acellular pertussis (low dose) -> used in adolescents.","pyqMatches":[{"year":"2015","no":834,"q":"Which Dipheria vaccine is recommended in a 14 years old girl ?","o":["DPT","DT","Tdap","None"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5954, 'PSM', 'Environment & Occupational Health', 'Hard', 'Preventive_&_Social_Medicine', 565, '{"id":5954,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":565,"q":"In water testing from a well [containing 75000 litres of water] by Horrock''s apparatus, there is blue colour from 4th cup onwards. What is the amount of bleaching powder required to disinfect the water ?","o":["1000 gm","1300 gm","1600 gm","2000 gm"],"a":1,"e":"Ans. is ''b'' i.e.,1300 gm In Horrock''s apparatus, 6 cups are filled with water and indicator (starch iodine) is added in increasing quantity in each cup (1 unit in 1st, 2 units in 2nd, 3 units in third and so on). The first cup which shows the blue color is multiplied by 2, for example, if the 2nd cup shows a blue colour than 4 grams (2 x 2) of bleaching powder will be required to disinfect 455 litre of water. Bleaching powder required=8*75000/455=1318","pyqMatches":[{"year":"2015","no":900,"q":"In water testing from a well [containing 75000 litres of water] by Horrock''s apparatus, there is blue colour from 4th cup onwards. What is the amount of bleaching powder required to disinfect the water ?","o":["1000 gm","1300 gm","1600 gm","2000 gm"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5955, 'PSM', 'Environment & Occupational Health', 'Easy', 'Preventive_&_Social_Medicine', 566, '{"id":5955,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":566,"q":"Indicator used in Horroch''s apparatus ?","o":["Bleaching powder","Soda-lime","Potassium permagnate","Starch iodine"],"a":3,"e":"Ans. is ''d'' i.e., Starch iodine [Ref Park 23''/e p. 717] In Horrock''s apparatus, 6 cups are filled with water and indicator (starch iodine) is added in increasing quantity in each cup (1 unit in lst, 2 units in 2nd, 3 units in third and so on). The first cup which shows the blue color is multiplied by 2, for example if 2nd cup shows blue colour than 4 grams (2 x 2) of bleaching powder will required to disinfect 455 litre of water.","pyqMatches":[{"year":"2015","no":899,"q":"Indicator used in Horroch''s apparatus ?","o":["Bleaching powder","Soda-lime","Potassium permagnate","Starch iodine"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5956, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 567, '{"id":5956,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":567,"q":"Droplet nuclei is a type of ?","o":["Vertical transmission","Direct transmission","Indirect transmission","Biological transmission"],"a":1,"e":"Ans. is ''b'' i.e., Direct transmission [Ref Park 23\"1/e p.97-100, 768] Communicable disease may be transmitted from the reservoir or source of infection to a susceptible host in many different ways. Modes of transmission may be :?","pyqMatches":[{"year":"2015","no":835,"q":"Droplet nuclei is a type of ?","o":["Vertical transmission","Direct transmission","Indirect transmission","Biological transmission"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5957, 'PSM', 'National Health Programmes', 'Moderate', 'Preventive_&_Social_Medicine', 568, '{"id":5957,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":568,"q":"Which is not a direct transmission ?","o":["Droplet infection","Vertical transmission","Transmission by mosquito","Soil contact"],"a":2,"e":"Ans. is ''c'' i.e., Transmission by mosquito","pyqMatches":[{"year":"2015","no":836,"q":"Which is not a direct transmission ?","o":["Droplet infection","Vertical transmission","Transmission by mosquito","Soil contact"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5958, 'PSM', 'Environment & Occupational Health', 'Easy', 'Preventive_&_Social_Medicine', 569, '{"id":5958,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":569,"q":"Horrock''s apparatus is used to measure ?","o":["Wind velocity","Humidity","Chlorine demand","Cooling power"],"a":2,"e":"Ans. is ''c'' i.e., Chlorine demand -Chlorine demand for water can be estimated by Horrock''s apparatus. -Chlorine demand of water is the amount of chlorine that is needed to destroy bacteria and to oxidize all the organic matter and ammoniacal substances present in water. -It is the difference between the amount of chlorine added to the water, and the amount of residual chlorine remaining at the end of a specific period of contact (usually 1 hr), at a given temperature and pH of the water","pyqMatches":[{"year":"2015","no":898,"q":"Horrock''s apparatus is used to measure ?","o":["Wind velocity","Humidity","Chlorine demand","Cooling power"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5959, 'PSM', 'Immunization', 'Moderate', 'Preventive_&_Social_Medicine', 570, '{"id":5959,"subject":"PSM","chapter":"Immunization","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":570,"q":"After taking MMR live vaccine, conception should not occur within ?","o":["2 weeks","4 weeks","8 weeks","10 weeks"],"a":1,"e":"Ans. is ''b'' i.e., 4 weeks [Ref CDC guidlines of vaccination in pregnancy] Measles-mumps-rubella (MMR) vaccine and its component vaccines should not be administered to women known to be pregnant. Because a risk to be fetus from administration of these live virus vaccines cannot be excluded for theoretical reasons, women should be counseled to avoid becoming pregnant for 28 days after vaccination with MMR vaccine or its component vaccines or varicella vaccine.","pyqMatches":[{"year":"2015","no":837,"q":"After taking MMR live vaccine, conception should not occur within ?","o":["2 weeks","4 weeks","8 weeks","10 weeks"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5960, 'PSM', 'Environment & Occupational Health', 'Easy', 'Preventive_&_Social_Medicine', 571, '{"id":5960,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":571,"q":"True about culex larvae ?","o":["Rest parallel to surface water","Long Palmate hair","Siphon tube present","All are true"],"a":2,"e":"Ans. is ''c'' i.e., Siphon tube present [Ref Park 23''/e p. 769 & 22\"d/e p. 714]","pyqMatches":[{"year":"2015","no":897,"q":"True about culex larvae ?","o":["Rest parallel to surface water","Long Palmate hair","Siphon tube present","All are true"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5961, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 572, '{"id":5961,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":572,"q":"Disinfection of urine is which type of disinfection ?","o":["Precurrent","Concurrent","Preconcurrent","Terminal"],"a":1,"e":"Ans. is ''b'' i.e., Concurrent [Ref Park 23\"1/e p.127] Types of disinfection There are following types of disinfection :? 1) Precurrent (prophylactic) disinfection It is done as a preventive method before illness, i.e. person is not ill, for example chlorination of water, pasteurization of milk, and handwashing. 2) Concurrent disinfection It is done when person is ill. It is the application of disinfective measures as soon as possible after the discharge of infectious material from the body of patient or after the soiling of articles with such material, i.e., the disease agent is destroyed as soon as it is released from the body, and in this way further spread of the agent is stopped. e.g., disinfection of urine, faeces, vomit, contaminated linen, clothes, hands, dressing, aprons, gloves etc. 3) Terminal disinfection It is the application of disinfective measures after the patient has taken discharge from hospital or he/she has died. e.g., disinfection of hospital rooms & floor, burning or burial of soiled material.","pyqMatches":[{"year":"2015","no":838,"q":"Disinfection of urine is which type of disinfection ?","o":["Precurrent","Concurrent","Preconcurrent","Terminal"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5962, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 573, '{"id":5962,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":573,"q":"Which is not an aryl organophosphate ?","o":["Malathion","Parathion","Chlorthion","Diazinon"],"a":0,"e":"Ans. is ''a'' i.e., Malathion Organophosphates Aryl Diazinon Parathion Chlorpyrifos Chlorthion Paraoxon Alkyl Malathion Sulfotepp Demeton Triclorfon HETP TEPP","pyqMatches":[{"year":"2015","no":896,"q":"Which is not an aryl organophosphate ?","o":["Malathion","Parathion","Chlorthion","Diazinon"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5963, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 574, '{"id":5963,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":574,"q":"Which is true of pathogenic mosquitoes ?","o":["Anopheles has spotted abdomen","Mansoni lays eggs singly","Culex cause yellow fever","Aedes has stripped yellow scales"],"a":3,"e":"Ans. is ''d'' i.e., Aedes has stripped yellow scales [Ref Park 23rdie p. 769 & 22nd/e p. 714] Aedes mosquitoes are easily distinguished by white stripes on a black body. Because of the striped or banded Character of their legs they are sometimes referred to as tiger mosquito. Anopheles has spotted wings (not spotted abdomen). Mansoni lays eggs in clusters. Yellow fever is caused by aedes mosquito (not culex).","pyqMatches":[{"year":"2015","no":895,"q":"Which is true of pathogenic mosquitoes ?","o":["Anopheles has spotted abdomen","Mansoni lays eggs singly","Culex cause yellow fever","Aedes has stripped yellow scales"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5964, 'PSM', 'Immunization', 'Moderate', 'Preventive_&_Social_Medicine', 575, '{"id":5964,"subject":"PSM","chapter":"Immunization","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":575,"q":"Not a freeze dried vaccine ?","o":["OPV","Measles","DPT","Rubella"],"a":2,"e":"Ans. is ''c'' i.e., DPT [Ref: Park 23\"/e p. 109 & 22\"d/e p. 104] Vaccine which must be stored in the cold part but never allowed to freez. TyphoidDPT TT Hepatitis B DT BCGDiluents","pyqMatches":[{"year":"2015","no":839,"q":"Not a freeze dried vaccine ?","o":["OPV","Measles","DPT","Rubella"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5965, 'PSM', 'Biostatistics', 'Easy', 'Preventive_&_Social_Medicine', 576, '{"id":5965,"subject":"PSM","chapter":"Biostatistics","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":576,"q":"Caloric requirement in an adult male for heavy work?","o":["1800 k cal/d","2300 k cal/d","3000 k cal/d","3500 k cal/d"],"a":3,"e":"Ans. is `d'' i.e., 3500 k cal/d [Ref Park 23rd le p.634] Indian Reference Indian Reference Energy requirementsMan Woman Light work 2320 kcal/day1900 kcal/day Moderate work 2730 kcal/day2230 kcal/day Heavy work 3490 kcal/day2850 kcal/day","pyqMatches":[{"year":"2015","no":892,"q":"Caloric requirement in an adult male for heavy work?","o":["1800 k cal/d","2300 k cal/d","3000 k cal/d","3500 k cal/d"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5966, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 577, '{"id":5966,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":577,"q":"Most widely used vaccine, beside OPV ?","o":["BCG","TT","Influenza","Pneumococcal"],"a":0,"e":"Ans. is ''a'' i.e., BCG [Ref www.ncbi.nlm.mih.] \"Making wider use of the world''s most widely used vaccine : Bacille calmette-Guerine revaccination reconsidered\" \"The bacille calmette-Guerin (BCG) vaccine has existed for 80 years and is one of the most widely used of all current vaccines, reading > 80% of neonates and infants in counteries where it is part of the national childhood immunization programme","pyqMatches":[{"year":"2015","no":840,"q":"Most widely used vaccine, beside OPV ?","o":["BCG","TT","Influenza","Pneumococcal"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5967, 'PSM', 'Environment & Occupational Health', 'Easy', 'Preventive_&_Social_Medicine', 578, '{"id":5967,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":578,"q":"Village Health and Nutrition Day (VHND) is observed ?","o":["Every week","Every month","Every 6 month","Every year"],"a":1,"e":"Ans. is ''B'' i.e., Every month The Village-Health and Nutrition day (VHND) is to be organized once every month on a fixed day (such as the second Saturday). The day can be decided by the VHWSC (village health and water sanitation committee) in each village at anyone of the Anganwadi centers (AWCs) in that village, preferably, all the AWCs should be covered by rotation. On that day, Anganwadi worker and other VHWSC members will mobilize villagers to assemble in AWC.","pyqMatches":[{"year":"2015","no":886,"q":"Village Health and Nutrition Day (VHND) is observed ?","o":["Every week","Every month","Every 6 month","Every year"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5968, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 579, '{"id":5968,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":579,"q":"Vanaspati Ghee is fortified with ?","o":["Iodine","Vitamin A","Iron","Calcium"],"a":1,"e":"Ans. is ''b'' i.e., Vitamin A Examples of food fortification : -","pyqMatches":[{"year":"2015","no":885,"q":"Vanaspati Ghee is fortified with ?","o":["Iodine","Vitamin A","Iron","Calcium"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5969, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 580, '{"id":5969,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":580,"q":"True about chicken pox ?","o":["Caused by Herpes simplex type-7","SAR is 90%","Infectious perios is 7 days prior to 7 days after onset of rash","Affects commonly 10-15 years old"],"a":1,"e":"Ans. is ''b'' i.e., SAR is 90% [Ref Park 23\"/e p.144] The causative agent of chicken pox is Varicella - Zoster virus (Herpes simplex type III). It is an acute respiratory infection with incubation period 10-21 days. Infection is acquired through respiratory tract via air droplets or rarely from conjunctiva. Infectious period (communicable period) for chicken pox is 2 days prior to 5 days after onset of rash, with a very high secondary attack rate of 90%. Chicken-pox usually affects children of age group 5-9 years.","pyqMatches":[{"year":"2015","no":841,"q":"True about chicken pox ?","o":["Caused by Herpes simplex type-7","SAR is 90%","Infectious perios is 7 days prior to 7 days after onset of rash","Affects commonly 10-15 years old"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5970, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 581, '{"id":5970,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":581,"q":"Chickenpox rash does not involve ?","o":["Trunk","Axilla","Palms & soles","Back"],"a":2,"e":"Ans. is ''c'' i.e., Palms & soles [Ref Park 23''/e p.144] Rash of chicken pox : Superficial, unilocular, centripetal, pleomorphic, symmetrical, affects flexor surfaces and axilla, spares palms and sales, has inflammation around, rapid evolution and dew- drop on rose petal appearnace.","pyqMatches":[{"year":"2015","no":842,"q":"Chickenpox rash does not involve ?","o":["Trunk","Axilla","Palms & soles","Back"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5971, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 582, '{"id":5971,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":582,"q":"Limiting amino acid in cereals ?","o":["Methionine","Tryptophan","Lysine","Cysteine"],"a":2,"e":"Ans. is ''c'' i.e., Lysine Food Deficiency Cereals Lysine & threonine Wheat Lysine & threonine Maize Tryptophan & lysine Pulses Methionine & cysteine SoybeanMethionine","pyqMatches":[{"year":"2015","no":884,"q":"Limiting amino acid in cereals ?","o":["Methionine","Tryptophan","Lysine","Cysteine"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5972, 'PSM', 'Immunization', 'Hard', 'Preventive_&_Social_Medicine', 583, '{"id":5972,"subject":"PSM","chapter":"Immunization","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":583,"q":"95% carrier and 5% cases are seen in ?","o":["Measles","Diphtheria","Rabies","Hepatitis B"],"a":1,"e":"Ans. is ''b'' i.e., Diphtheria [Ref: Park 23rd/e p.160] Diphtheria is caused by Corynebacterium diphtheriae, a gram- positive bacterium. Source of infection is either case or carrier, with carriers being the most common sources of infection, their ratio is estimated to be 95 carriers for 5 clinical cases. Nasal carriers are more dangerous than throat carriers. Inmunuzation does not prevent carrier state.","pyqMatches":[{"year":"2015","no":843,"q":"95% carrier and 5% cases are seen in ?","o":["Measles","Diphtheria","Rabies","Hepatitis B"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5973, 'PSM', 'National Health Programmes', 'Easy', 'Preventive_&_Social_Medicine', 584, '{"id":5973,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":584,"q":"Mid-day meal provides ?","o":["1/2 of energy","1/3 of protein","30 gm pulse/day","All are correct"],"a":2,"e":"Ans. is ''c'' i.e., 30 gm pulse/day [Ref Park 23\"Ve p.662] Mid-day Meal Programme It is also known as ''School Lunch Programme''. It was launched in 1961 under Ministry of Education. The features of programme are :","pyqMatches":[{"year":"2015","no":881,"q":"Mid-day meal provides ?","o":["1/2 of energy","1/3 of protein","30 gm pulse/day","All are correct"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5974, 'PSM', 'Environment & Occupational Health', 'Easy', 'Preventive_&_Social_Medicine', 585, '{"id":5974,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":585,"q":"Skeletal fluorosis occurs with fluoride level in water?","o":["< 1.5 mg/L","1.5-3 mg/L","3-6 mg/L","> 10 mg/L"],"a":2,"e":"Ans. is ''C'' i.e., 3-6 mg/L Dental fluorosis → > 1.5 mg/L (PPM) Skeletal fluorosis → 3-6 mg/L (PPM) Crippling fluorosis → > 10 mg/L (PPM)","pyqMatches":[{"year":"2015","no":880,"q":"Skeletal fluorosis occurs with fluoride level in water?","o":["< 1.5 mg/L","1.5-3 mg/L","3-6 mg/L","> 10 mg/L"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5975, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 586, '{"id":5975,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":586,"q":"Following is Hib conjugate vaccine ?","o":["Capsular polysaccharide","Cell wall polysaccheride","Capsular polysaccheride with carrier","PRP with carrier"],"a":2,"e":":D Ans. is ''d > c'' i.e., PRP with carrier > Capsular polysaccheride with carrier [Ref Pariza 4th/e p.3401 Conjugated Hib vaccine include PRP (polyribosyl ribitol phasphate) covalently linked to carrier protein. PRP is the Capsular polysaccaride of H influenzae type B (Hib). Currently three types of Hib (H influenzae type B) vaccines are available. These vary in ?","pyqMatches":[{"year":"2015","no":844,"q":"Following is Hib conjugate vaccine ?","o":["Capsular polysaccharide","Cell wall polysaccheride","Capsular polysaccheride with carrier","PRP with carrier"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5976, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 587, '{"id":5976,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":587,"q":"True about Pertussis is ?","o":["Most of the infections are subclinical","Most infective stage is Paroxysmal stage","Drug of choice is Erythromycin","Cerebellar ataxia may be a complication"],"a":2,"e":"Ans. is ''c'' i.e., Drug of choice is Erythromycin [Ref Park 23''/e p.161] Pertussis (Whooping cough) Pertussis, also called ''100 day cough'', is caused by Bordetella pertussis (only 5% cases are caused by B. parapertussis). Source of infection is a case of pertussis. There is no subclinical case or chronic carrier state. Period of infectivity (communicability) extends from a week after exposuse to about 3 weeks after the onset of paroxysmal stage. Catarrhal stage is most infective. Secondary attack rate is high, i.e. 90%. For diagnosis, gold standard is isolation of organism in culture from nasopharyngeal secretion. Erythromycin is the drug of choice for treatment of cases as well as for contacts. Isolation period is 4 weeks or until paroxysms cease.","pyqMatches":[{"year":"2015","no":845,"q":"True about Pertussis is ?","o":["Most of the infections are subclinical","Most infective stage is Paroxysmal stage","Drug of choice is Erythromycin","Cerebellar ataxia may be a complication"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5977, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 588, '{"id":5977,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":588,"q":"True about influenza infectivity ?","o":["Communicable period is 5 days before to 5 days after the onset of symptoms","Source of infection is clinical case","There are no subclinical cases","All are correct"],"a":1,"e":"Ans. is ''b'' i.e., Source of infection is clinical case [Ref Park 23rdie p.154] Influenza Influenza virus a RNA virus, belongs to orthomyxovirus. Source of infection of influenza is a clinical case or subclinical case. Major reservoir of influenza virus exists in animal and birds. Incubation period is 18-72 hours. Most of the infections are subclinical. Clinical cases present with cough, fever, myalgia and headache. Complications include pneumonia, encephalitis, Reye''s syndrome (with type-B virus); GB syndrome and gastric flu/GIT symptoms (with type-B virus). Period of Communicability is 1-2 days before to 1-2 days after onset of symptoms.","pyqMatches":[{"year":"2015","no":846,"q":"True about influenza infectivity ?","o":["Communicable period is 5 days before to 5 days after the onset of symptoms","Source of infection is clinical case","There are no subclinical cases","All are correct"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5978, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 589, '{"id":5978,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":589,"q":"What is common in H5N1 and H7N7 strains of influenza ?","o":["Frequent endemic infection in man","Have same frequency of antigenic variation","Strains of avian influenza","All are correct"],"a":2,"e":"Ans. is ''c'' i.e., Strains of avian influenza [Ref Essentials of microbiology p.701; Harrison 18th/e p.1494; Park 23rd/e p.153] Avian influenza (Bird flu) It is caused mostly by H5 N, strain of influenza - A. It was detected in Hongkong in 1997 during a pandemic in poultry. It is a pandemic with high mortality rate (60%). Other types of influenza viruses which have been observed to cause avian influenza are H7 N7 and H9 N2 of influenza - A. Recently an outbreak of avian influenza was caused by 112 INT, in China, in 2013. Drug of choice for avian influenza is oseltamivir.","pyqMatches":[{"year":"2015","no":847,"q":"What is common in H5N1 and H7N7 strains of influenza ?","o":["Frequent endemic infection in man","Have same frequency of antigenic variation","Strains of avian influenza","All are correct"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5979, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 590, '{"id":5979,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":590,"q":"NPU for egg is ?","o":["70","80","85","100"],"a":3,"e":"Ans. is ''d'' i.e., 100 The net protein utilization, or NPU, is the ratio of amino acid mass converted to proteins to the mass of amino acids supplied. NPU for egg: 100Wheat: 51 Fish: 77 NPU for meat: 80Pulses: 45-50 Rice: 65 NPU for milk: 81 Soyabean: 55","pyqMatches":[{"year":"2015","no":879,"q":"NPU for egg is ?","o":["70","80","85","100"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5980, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 591, '{"id":5980,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":591,"q":"Not used for treatment and/or prophylaxis of seasonal influenza -","o":["Amantidine","Rimantidine","Oseltamivir","Acyclovir"],"a":3,"e":"Ans. is ''d'' i.e., Acyclovir Two classes of antiviral drugs are available for the treatment and prevention of influenza.","pyqMatches":[{"year":"2015","no":848,"q":"Not used for treatment and/or prophylaxis of seasonal influenza","o":["Amantidine","Rimantidine","Oseltamivir","Acyclovir"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5981, 'PSM', 'Immunization', 'Moderate', 'Preventive_&_Social_Medicine', 592, '{"id":5981,"subject":"PSM","chapter":"Immunization","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":592,"q":"Capsular polysaccharide derived vaccine is available for all meningocci except ?","o":["Group A","Group B","Group C","Group Y"],"a":1,"e":"Ans. is ''b'' i.e., Group B [Ref Park 23rdie p. 166] Meningococcal vaccine is prepared from Capsular polysaccharide. Vaccines are availabe for group A, C, Y and W-135. Bivalent (A, C), trivalent (A, C, W135) and tetravalent (A, C, Y, W135) vaccines are available. Meningoccal group B vaccine was not available for last two decades. Recently, group B vaccine has also been developed in many countries (UK, Ireland) and is a part of routine immunization schedule. Now, you must be thinking that why the answer of this question is group B meningococci. This is because meningococcal vaccine is not prepared from capsular polysaccharide.","pyqMatches":[{"year":"2015","no":849,"q":"Capsular polysaccharide derived vaccine is available for all meningocci except ?","o":["Group A","Group B","Group C","Group Y"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5982, 'PSM', 'Maternal & Child Health', 'Easy', 'Preventive_&_Social_Medicine', 593, '{"id":5982,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":593,"q":"Maternal mortality rate is defined as ?","o":["Maternal death per 1000 total births","Maternal death per 1000 live births","Maternal death per 1000 women","Maternal death per 1000 women of reproductive age"],"a":3,"e":"Ans. is ''d'' i.e., Maternal death per 1000 women of reproductive age [Ref Park 23rd /e p.558-559] Maternal mortality rate=Total no. of female death due to complication of pregnancy childbirth or within 42 days of delivery / Total no. of women of reproductive age x1000","pyqMatches":[{"year":"2015","no":878,"q":"Maternal mortality rate is defined as ?","o":["Maternal death per 1000 total births","Maternal death per 1000 live births","Maternal death per 1000 women","Maternal death per 1000 women of reproductive age"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5983, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 594, '{"id":5983,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":594,"q":"Vaccine derived polio virus outbreaks are due to ?","o":["Type-2 virus","Type-3 virus","Type-1 virus","All of the above"],"a":0,"e":"Ans. is ''a'' i.e., Type-2 virus \"The main cause of vaccine derived poliovirus (VDPV) out breaks is currently type-2 component of OPV\" ...Park 23rd/e \"Currently, the type-2 component contained in trivalent OPV accounts for more than 90% of all CVDPV cases\" .","pyqMatches":[{"year":"2015","no":850,"q":"Vaccine derived polio virus outbreaks are due to ?","o":["Type-2 virus","Type-3 virus","Type-1 virus","All of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5984, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 595, '{"id":5984,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":595,"q":"False regarding polio vaccination ?","o":["Both killed and live vaccines are available","First OPV is given at 4 weeks","OPV induces both humoral and intestinal immunity","IPV is given intramuscularly"],"a":1,"e":"Ans. is ''b'' i.e., First OPV is given at 4 weeks [Ref Park 23rd/e p.206-210] First OPV (zero dose) is given at birth. There are two polio vaccines : killed (IPV) and live attenuated (OPV) OPV induces both humoral and intestinal immunity, whereas IPV induces only humoral immunity. IPV is given intramuscularly (preferrable) or subcutaneously.","pyqMatches":[{"year":"2015","no":851,"q":"False regarding polio vaccination ?","o":["Both killed and live vaccines are available","First OPV is given at 4 weeks","OPV induces both humoral and intestinal immunity","IPV is given intramuscularly"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5985, 'PSM', 'Communicable Diseases', 'Easy', 'Preventive_&_Social_Medicine', 596, '{"id":5985,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":596,"q":"Reservoir of infection in enteric fever ?","o":["Birds","Cow","Cattle","Man"],"a":3,"e":"Ans. is ''d'' i.e., Man [Ref Park 23rdle p.235] Typhoid fever is the result of systemic infection mainly by S.typhi found only in man. The term enteric fever include both typhoid fever (caused by S. typhi) and paratyphoid fever (caused by S. Paratyphi & ''C''). Reservoir - Man is the only reservoir. Carriers are more important than cases. Source of infection Primary Feces, Urine Secondary - Water, food, fingers, flies.","pyqMatches":[{"year":"2015","no":852,"q":"Reservoir of infection in enteric fever ?","o":["Birds","Cow","Cattle","Man"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5986, 'PSM', 'Communicable Diseases', 'Easy', 'Preventive_&_Social_Medicine', 597, '{"id":5986,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":597,"q":"Rideal-walker coefficient for disinfectant used for cholera stool should be ?","o":["2","4","7","10"],"a":3,"e":"Ans. is ''d'' i.e., 10 [Ref Park 23''1/4 p. 129-30 & 22\"/e p. 120] For cholera stool : ? \"The most effective disinfectant for general use is a coal-tar disinfectant with a Rideal-Walker (RW) coefficient of 10 or more such as cresol\". - Park 250","pyqMatches":[{"year":"2015","no":853,"q":"Rideal-walker coefficient for disinfectant used for cholera stool should be ?","o":["2","4","7","10"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5987, 'PSM', 'Demography & Family Planning', 'Moderate', 'Preventive_&_Social_Medicine', 598, '{"id":5987,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":598,"q":"In a community of 1000000 population 105 children were born in a year out of which 5 was still births, and 4 died within 6 months after birth. The IMR is ?","o":["40","90","120","150"],"a":0,"e":"Ans. is ''a'' i.e., 40 [Ref: Read below] In the given question out of 105 deliveries, 5 were still births -3 Thus, live births are 100. Infant deaths are 4.","pyqMatches":[{"year":"2015","no":877,"q":"In a community of 1000000 population 105 children were born in a year out of which 5 was still births, and 4 died within 6 months after birth. The IMR is ?","o":["40","90","120","150"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5988, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 599, '{"id":5988,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":599,"q":"Women traveling from Bihar to Delhi is suspecting to have Kala-azar. Suitable investigation is ?","o":["P24 antigen","Rk-39 test","Combo RDT","HRP-2 antigen"],"a":1,"e":"Ans. is ''b'' i.e., rk-39 test [Ref Park 23rd le p.305, 306; Essentials of microbiology p.785] Laboratory diagnosis of Kala-azar The demonstration of parasite LD bodies in the aspirates of the spleen, liver, bone marrow or lymph node is only way to confirm visceral leishmaniasis. Hematological findings : T ESR, anaemia, reversed albumin-globulin ratio & leucopenia. Aldehyde test of Napier is a simple test widely used in India for the diagnosis of Kala-azar. Serological test : Direct agglutination test, rk 39 dipstick test, ELISA & Indirect fluorescent antibody test. Leishmanin test : This test is based on skin reaction.","pyqMatches":[{"year":"2015","no":854,"q":"Women traveling from Bihar to Delhi is suspecting to have Kala-azar. Suitable investigation is ?","o":["P24 antigen","Rk-39 test","Combo RDT","HRP-2 antigen"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5989, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 600, '{"id":5989,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":600,"q":"What is exponential growth ?","o":["Rapid growth in population that leads to disbalance in birth and deaths","Slow growth rate","Growth limited by limiting factors","None"],"a":0,"e":"Ans. is ''a'' i.e., Rapid growth in population that leads to dysbalance in birth and deaths [Ref O.P. Ghai 7Ve p. 93] Exponentional Vs logistic population growth The population growth of a species is regulated by limiting factors (resources) that exist within the species environment. Population growth maintains equilibrium in all species under normal conditions bacause of these limiting factors. A populations overall growth rate is affected by the birth rate and death rate. The rate of increase within a populations is represented by the birth rate minus death rate. When the growth rate in a population is represented by the birth rate minus the death rate, the population remains at a constant level.","pyqMatches":[{"year":"2015","no":875,"q":"What is exponential growth ?","o":["Rapid growth in population that leads to disbalance in birth and deaths","Slow growth rate","Growth limited by limiting factors","None"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5990, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 601, '{"id":5990,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":601,"q":"Vital statistics in a population are ?","o":["Sex ratio","Age composition","Birth rate","Dependency ratio"],"a":2,"e":"Ans. is ''c'' i.e., Birth rate Vital statistics are statistics concerning the important events in humon life, such as birth, death, marriages and migration. These are - Birth rates Death rates Infant mortality rate Fertility rate Mortalility rates (perinatal mortality rate, MMR, CMR etc)","pyqMatches":[{"year":"2015","no":874,"q":"Vital statistics in a population are ?","o":["Sex ratio","Age composition","Birth rate","Dependency ratio"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5991, 'PSM', 'Miscellaneous', 'Hard', 'Preventive_&_Social_Medicine', 602, '{"id":5991,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":602,"q":"In a town there are 2500 live birth within six month. During same period 5 women died due to peripartum infection, 5 died due to electrocution, 2 died due to obstructed labor and 3 died due to PPH. What is the MMR ?","o":["4 per 1000 live birth","6 per 1000 live birth","40 per 1000 live birth","60 per 1000 live birth"],"a":0,"e":"Ans. is ''a'' i.e., 4 per 1000 live birth [Ref Park 23rd/e p.559] In this question, pregnancy related deaths are 10 (infection, obstructed labor and PPH). Electrocution is not a pregnancy/ labor related death so excluded from numerator..","pyqMatches":[{"year":"2015","no":873,"q":"In a town there are 2500 live birth within six month. During same period 5 women died due to peripartum infection, 5 died due to electrocution, 2 died due to obstructed labor and 3 died due to PPH. What is the MMR ?","o":["4 per 1000 live birth","6 per 1000 live birth","40 per 1000 live birth","60 per 1000 live birth"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5992, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 603, '{"id":5992,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":603,"q":"Gross reproduction rate is ?","o":["Number of girls born to a mother in her reproductive age","Number of boys born to a mother in her reproductive age","Number of total children born to a mother in her reproductive age","Number of lives births per 1000 women"],"a":0,"e":"Ans. is ''a'' i.e., Number of girls born to a mother in her reproductive age [Ref Park 23''/e p.489] Gross reproduction rate Average number of girls that would be born to a married woman if she experiences the current fertility pattern throughout her reproductive span (15-44 or 49 year) assuming no mortality. GRR in India is 1.1 (1.2 in rural areas and 0.8 in urban areas).","pyqMatches":[{"year":"2015","no":872,"q":"Gross reproduction rate is ?","o":["Number of girls born to a mother in her reproductive age","Number of boys born to a mother in her reproductive age","Number of total children born to a mother in her reproductive age","Number of lives births per 1000 women"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5993, 'PSM', 'Biostatistics', 'Easy', 'Preventive_&_Social_Medicine', 604, '{"id":5993,"subject":"PSM","chapter":"Biostatistics","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":604,"q":"Most common route of nosocomial infection [Hospital-acquired infection] ?","o":["Droplet transmission","Direct contact","Indirect contact","Vehicle transmission"],"a":1,"e":"Ans. is `B'' i.e., Direct contact [Ref Textbook of Environmental microbiology p.819] There are following types of modes of transmission of hospital- acquired infections. Contact transmission It is the most common and most preventable means of transmission. It is divided into two types - Direct contact : It involves contact of body surface to body surface with a physical transfer of microorganisms. Hand contact is most common mode of transmission. Indirect contact : It involves body surface contact with a contaminated intermediate object.","pyqMatches":[{"year":"2015","no":855,"q":"Most common route of nosocomial infection [Hospital-acquired infection] ?","o":["Droplet transmission","Direct contact","Indirect contact","Vehicle transmission"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5994, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 605, '{"id":5994,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":605,"q":"Which state has lowest IMR ?","o":["Uttar Pradesh","Kerala","Maharashtra","Tamil Nadu"],"a":1,"e":"Ans. is ''b'' i.e., Kerala [Ref Park 23rd/e p.563-561 Kerala has lowest -","pyqMatches":[{"year":"2015","no":871,"q":"Which state has lowest IMR ?","o":["Uttar Pradesh","Kerala","Maharashtra","Tamil Nadu"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5995, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 606, '{"id":5995,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":606,"q":"Behavioral surveillance survey is done in ?","o":["Malaria","Filaria","AIDS","TB"],"a":2,"e":"Ans. is ''c'' i.e.,AIDS [Ref www.cdc.gov/hiv] Behavioral surveillance survey is done in persons who are at high risk for HIV infection. Surveillance is conducted in rotating, annual cycles in three different populations at increased risk for HIV :?","pyqMatches":[{"year":"2015","no":856,"q":"Behavioral surveillance survey is done in ?","o":["Malaria","Filaria","AIDS","TB"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5996, 'PSM', 'National Health Programmes', 'Easy', 'Preventive_&_Social_Medicine', 607, '{"id":5996,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":607,"q":"Drug of choice for Mass therapy under filaria control Programme ?","o":["Albendazole","Ivermectin","DEC","Mebendazole"],"a":2,"e":"Ans. is ''c'' i.e.,DEC [Ref nvbdcp.gov.in] Every person above 2 years of age living in the endemic area (except for pregnent women & seriously ill person) should be given Diethylcarbamazine citrate (DEC) tablets. 0-2 years N.1. t.,2-5 years 1 tablet of 100 mg 6-14 years 2 tablets of 100 mg 15 years 3 tablets of 100 mg","pyqMatches":[{"year":"2015","no":857,"q":"Drug of choice for Mass therapy under filaria control Programme ?","o":["Albendazole","Ivermectin","DEC","Mebendazole"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5997, 'PSM', 'National Health Programmes', 'Easy', 'Preventive_&_Social_Medicine', 608, '{"id":5997,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":608,"q":"Which of the following larvicide is used under urban Malaria Scheme ?","o":["Malathion","Parathion","DDT","Abate"],"a":3,"e":"Ans. is ''d'' i.e., Abate [Ref nvbdcp.gov.in] Following chemical larvicides are used in the Urban Malaria Scheme Programme","pyqMatches":[{"year":"2015","no":858,"q":"Which of the following larvicide is used under urban Malaria Scheme ?","o":["Malathion","Parathion","DDT","Abate"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5998, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 609, '{"id":5998,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":609,"q":"Regular insectisidal spray is done when API is ?","o":["> 1","> 2","< 1","< 2"],"a":1,"e":"Ans. is ''b'' i.e., > 2 [Ref: Park 20 le p.384] Area with API <2→ focal spaying Area with API >2 → regular spray Areas having Annual Parasite Index (API) > 2 Regular 2 rounds of insecticidal spray with DDT/Malathion/Synthetic Pyrethroids at the dose of 1, 2, 0.5 mg/sq meter respectively. Entomological assessment for vector behavior and development of insecticidal resistance Active and passive surveillance is carried outon regular basis every fortnight. Presumptive Treatment to all fever cases and radical treatment to all slide positive cases is given","pyqMatches":[{"year":"2015","no":859,"q":"Regular insectisidal spray is done when API is ?","o":["> 1","> 2","< 1","< 2"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (5999, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 610, '{"id":5999,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":610,"q":"Main function of sodium citrate in ORS ?","o":["To increase absorption of glucose by cotransport","To correct electrolyte imbalance","To correct Acidosis","To correct dehydration"],"a":2,"e":"Ans. is ''c'' i.e., To correct Acidosis The main function of sodium citrate is to correct acidosis ? \"The citrate in ORS is needed for the treatment of acidosis, which frequently occurs with dehydration\" \"Efficacy of sodium citrate equals to sodium bicarbonate for correction of acidosis in diarrhea\"","pyqMatches":[{"year":"2015","no":860,"q":"Main function of sodium citrate in ORS ?","o":["To increase absorption of glucose by cotransport","To correct electrolyte imbalance","To correct Acidosis","To correct dehydration"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6000, 'PSM', 'National Health Programmes', 'Easy', 'Preventive_&_Social_Medicine', 611, '{"id":6000,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":611,"q":"For post exposure prophylaxis for HIV the regimen is ?","o":["Zidovodin + lamivudin for 4 weeks","Lamivudin + ritonavir for 4 weeks","Zidovudin + lamivudin + Indinavir for 4 weeks","Single dose zidovudin + lamivudin + Indinavir"],"a":2,"e":"Ans. is ''c'' i.e., Zidovudin + lamivudin + Indinavir for 4 weeks Postexposure prophylaxis Anti-retroviral drug for post-exposure prophylaxis should be initiated as soon as possible after the exposure within the first few hours and no later than 72 hours. Usually combination of two nucleoside reverse transcriptase inhibitors (zidovudin and lamivudin) plus a protease inhibitor (ritonavir or indinavir) is given for 4 weeks. To provent mother to child transmission, the preferred regimen is single dose of nevirapine to mother at onset of labour and to child within 72 hours of birth. Zidovudine is also used, but requires multiple dosage. Caesarean section reduces the risk of transmission by 50%.","pyqMatches":[{"year":"2015","no":861,"q":"For post exposure prophylaxis for HIV the regimen is ?","o":["Zidovodin + lamivudin for 4 weeks","Lamivudin + ritonavir for 4 weeks","Zidovudin + lamivudin + Indinavir for 4 weeks","Single dose zidovudin + lamivudin + Indinavir"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6001, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 612, '{"id":6001,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":612,"q":"According female sterlization 2014 guidelines, eligibility criteria for female sterilization are all except?","o":["Age between 22-49 years","Should have at least 1 child","Unmarried woman","Partner is not sterilized"],"a":2,"e":"Ans. is ''c'' i.e.,Unmarried woman [Ref www.tvhealth.org] Following are the eligibility criteria for female sterilization (2014) ?","pyqMatches":[{"year":"2015","no":870,"q":"According female sterlization 2014 guidelines, eligibility criteria for female sterilization are all except?","o":["Age between 22-49 years","Should have at least 1 child","Unmarried woman","Partner is not sterilized"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6002, 'PSM', 'National Health Programmes', 'Easy', 'Preventive_&_Social_Medicine', 613, '{"id":6002,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":613,"q":"True about post-exposure prophylaxis in HIV ?","o":["Should be given in 5 days of exposure","Single dose nevirapine prevents mother to child transmission","Given for 2 weeks","Standard protocol is to use Any Two NRTIs with no other drugs"],"a":1,"e":"Ans. is ''b'' i.e., Single dose nevirapine prevents mother to child transmission [Ref Has been explained]","pyqMatches":[{"year":"2015","no":862,"q":"True about post-exposure prophylaxis in HIV ?","o":["Should be given in 5 days of exposure","Single dose nevirapine prevents mother to child transmission","Given for 2 weeks","Standard protocol is to use Any Two NRTIs with no other drugs"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6003, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 614, '{"id":6003,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":614,"q":"Smoking is preventive for ?","o":["Lung cancer","Chronic bronchitis","Ulcerative colitis","CHD"],"a":2,"e":"Ans. is ''c'' i.e.,Ulcerative colitis Smoking has been shown to have some protective effect in -","pyqMatches":[{"year":"2015","no":869,"q":"Smoking is preventive for ?","o":["Lung cancer","Chronic bronchitis","Ulcerative colitis","CHD"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6004, 'PSM', 'Health Management & Services', 'Easy', 'Preventive_&_Social_Medicine', 615, '{"id":6004,"subject":"PSM","chapter":"Health Management & Services","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":615,"q":"Newborn care corner is present in ?","o":["NICU","OPD","Labour room","Wards side room"],"a":2,"e":"Ans. is ''c'' i.e., Labour room [Ref dghs.gov.bd] Newborn care corner is a space within the delivery room where immediate care is provided to all newborns Health facility MCH level I: PHC, Subcentre MCH level 11: CHC, First referral unit (FRU) MCH level District hospital All newborns at birth Newborn care corner (NBCC) in labour room NBCC in labour room and operation theatre NBCC in labour room and operation theatre Sick newborns Prompt referral Newborn stabilization unit (NBSU) Special newborn care unit (SNCU)","pyqMatches":[{"year":"2015","no":868,"q":"Newborn care corner is present in ?","o":["NICU","OPD","Labour room","Wards side room"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6005, 'PSM', 'Biostatistics', 'Easy', 'Preventive_&_Social_Medicine', 616, '{"id":6005,"subject":"PSM","chapter":"Biostatistics","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":616,"q":"Total communication means ?","o":["Use of all methods of communication for advertisment","Use of all methods of communication for school teaching","Use of all methods of communication for community participation","Using every communication option to teach deaf child"],"a":3,"e":"Ans. is ''d'' i.e., Using every communication option to teach deaf child [Ref Development - behavioral pediatrics p.392] Total communication is philosophy of educating children with hearing loss (deaf children) that incorporates all means of communication, i.e. formal signs, natural gestures, fingerspelling, body language, listening, lipreading and speech.","pyqMatches":[{"year":"2015","no":867,"q":"Total communication means ?","o":["Use of all methods of communication for advertisment","Use of all methods of communication for school teaching","Use of all methods of communication for community participation","Using every communication option to teach deaf child"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6006, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 617, '{"id":6006,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":617,"q":"Rule of Halves is related to ?","o":["Obesity","Burns","Blindness","Hypertension"],"a":3,"e":"Ans. is ''d'' i.e.,Hypertension [Ref Park 23''/e p.376] Rule of Halves: Hypertension is an ''Iceberg disease''. Only about half of hypertensive subjects in general population of most of the developed countries are aware of condition, only half of those aware of the problem were being treated and only half of those treated were considered adequately treated.","pyqMatches":[{"year":"2015","no":866,"q":"Rule of Halves is related to ?","o":["Obesity","Burns","Blindness","Hypertension"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6007, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 618, '{"id":6007,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":618,"q":"Maximum relative risk attributed by obesity to which condition ?","o":["Hypertension","CHD","DM","Cancer"],"a":2,"e":"Ans. is ''c'' i.e., DM [Ref Obesity clinical management p.712] \"Recently, a meta-analysis of 89 studies examining the relative risk of obesity-related co-morbidities showed that the strongest association was with type 2 diabetes mellitus\" \"Proportion of type II diabetes that is attributable to obesity was approximately 61% whereas the proportion of CHD that wast attributable to obesity was approximately 17%\"","pyqMatches":[{"year":"2015","no":865,"q":"Maximum relative risk attributed by obesity to which condition ?","o":["Hypertension","CHD","DM","Cancer"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6008, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 619, '{"id":6008,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":619,"q":"According to MDG child mortality has to be reduced by how, much by 2015 ?","o":["One third","Half","Two third","One fourth"],"a":2,"e":"Ans. is ''c'' i.e., Two third [Ref Park 20th/e p. 834] 3 of 8 goals of MDG (Goal 4, 5, 6), 8 of 18 targets and 18 of 48 indicators are ''directly'' health related.","pyqMatches":[{"year":"2013","no":846,"q":"According to MDG child mortality has to be reduced by how, much by 2015 ?","o":["One third","Half","Two third","One fourth"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6009, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 620, '{"id":6009,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":620,"q":"SA-14-14-2 ?","o":["Diploid cell inactivated","Killed vaccine","Live vaccine","Primary immunization 2 doses"],"a":2,"e":"Ans. is ''c'' i.e., Live vaccine[Ref Park 22\"/e p. 260,261; Environmental medicine p.1812] SA-14-142 is a cell-culture-derived live attenuated vaccine for IE. Primary immunization is given by a single dose followed by a booster after 1 years. I am not sure about option c, because no textbook has mentioned whether, SA-14-14-2 vaccine provides life long immunity or not. But, almost all live attenuated vaccines provide life long immunity, therefore it may provide life long immunity. \"Protection for 10-12 years may be achieved with a single dose of this vaccine\".","pyqMatches":[{"year":"2013","no":907,"q":"SA-14-14-2 ?","o":["Diploid cell inactivated","Killed vaccine","Live vaccine","Primary immunization 2 doses"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6010, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 621, '{"id":6010,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":621,"q":"CAD primodial prevention is by?","o":["Lifestyle change","Coronary bypass","Treatment of CAD","None"],"a":0,"e":"Ans. is ''a'' i.e., Lifestyle change [Ref Park 22\"dle p. 339-341] Primordial/primary prevention is the best policy for CHD as well as other non-communicable diseases. It includes following :","pyqMatches":[{"year":"2013","no":918,"q":"CAD primodial prevention is by?","o":["Lifestyle change","Coronary bypass","Treatment of CAD","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6011, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 622, '{"id":6011,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":622,"q":"Which of the following is a stomach poison ?","o":["DDT","Pyrethrum","Paris green","Malathion"],"a":2,"e":"Ans. is ''c'' i.e.,Paris green [Ref Park 22\"/e p. 728] Inectisides are divided into :?","pyqMatches":[{"year":"2013","no":951,"q":"Which of the following is a stomach poison ?","o":["DDT","Pyrethrum","Paris green","Malathion"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6012, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 623, '{"id":6012,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":623,"q":"The number of times the air in a living room should be recycled is ?","o":["2-3 times","More than 6 times","4 times","None"],"a":0,"e":"Ans. is ''a'' i.e., 2-3 times [Ref Park 22\"d/e p. 685] Standards of ventilation Cubic space:- Fresh air supply 3000 cubic feet per person per hour (range is 300-3000 c.ft). Air change:- 2 to 3 times per hour in living room and 4 to 6 times per hour in work rooms and assemblies. Floor space:- 50-100 Sq. ft. per person (heights over 10 to 12 feet are not taken into account).","pyqMatches":[{"year":"2013","no":952,"q":"The number of times the air in a living room should be recycled is ?","o":["2-3 times","More than 6 times","4 times","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6013, 'PSM', 'Health Management & Services', 'Hard', 'Preventive_&_Social_Medicine', 624, '{"id":6013,"subject":"PSM","chapter":"Health Management & Services","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":624,"q":"No of inpatient beds in PHC ?","o":["6","10","20","25"],"a":0,"e":"Ans. is ''a'' i.e., 6 [Ref Park 22\"d/e p. 845] PHC 6 beds CHC → 30 beds","pyqMatches":[{"year":"2013","no":976,"q":"No of inpatient beds in PHC ?","o":["6","10","20","25"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6014, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 625, '{"id":6014,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":625,"q":"PQLI is","o":["Objective component of level of living","Subjective component of level of living","Objective component of quality of life","Subjective component of quality of life"],"a":3,"e":"Ans. is ''d'' i.e., Subjective component of quality of life Subjective component The subjective component of well being is quality of life. The level of living and standard of living are objective criteria of well being, while the quality of life comprises the individual''s subjective evaluation of these. The recent definition of quality of life is as follows \"a composite measure of physical mental and social well being as perceived by each individual or group of individuals.\" WHO definition is as follows \"the condition of life resulting from the combination of the effects of the complete range of factors such as those determining health, happiness, education, etc.\" The index for quality of life is \"Physical quality of life index (PQLI)\". The PQLI is an attempt to measure the quality of life or well-being of a country. Physical quality of life index consolidates three indicators:- Literacy rate Infant mortality rate Life expectancy at age 1 year (LEI) PQLI ranges from 0 to 100. PQLI in India is 65.","pyqMatches":[{"year":"2016","no":790,"q":"PQLI is","o":["Objective component of level of living","Subjective component of level of living","Objective component of quality of life","Subjective component of quality of life"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6015, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 626, '{"id":6015,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":626,"q":"Only disease which is eradicated worldwide ?","o":["Small pox","Polio","Diphtheria","Measles"],"a":0,"e":"Ans. is ''a'' i.e., Small pox Eradication implies termination of all transmission of infection by extermination of infectious agent. It is an absolute process, i.e. all or none phenomenon. It literally means \"tearing out by roots\". Eradication is a \"global term\" used only cessation of infection from the whole world. Smallpox is the only disease that has been eradicated. Other diseases which are candidates for global eradication Polio, measles, dracunculiasis, diphtheria.","pyqMatches":[{"year":"2016","no":791,"q":"Only disease which is eradicated worldwide ?","o":["Small pox","Polio","Diphtheria","Measles"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6016, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 627, '{"id":6016,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":627,"q":"Category 4 biomedical waste include ?","o":["Human anatomical waste","Animal waste","Cytotoxic drug","Waste sharps"],"a":3,"e":"Ans. is ''d'' i.e., Waste sharps [Ref Park 23\"1/e p. 793-794] BMWs in India are managed under ''Biomedical Waste Management and Handling Rules 1998'' with exercising powers 6, 8, 25 of Environmental Protection Act 1986 (under Ministry of Environment and Forests). Schedules are :-","pyqMatches":[{"year":"2016","no":891,"q":"Category 4 biomedical waste include ?","o":["Human anatomical waste","Animal waste","Cytotoxic drug","Waste sharps"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6017, 'PSM', 'Biostatistics', 'Easy', 'Preventive_&_Social_Medicine', 628, '{"id":6017,"subject":"PSM","chapter":"Biostatistics","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":628,"q":"Median incubation period is ?","o":["Maximum time from exposure to development of symptoms in all cases","Minimum time from exposure to development of symptoms in all cases","Time from exposure to development in 50% of cases","None of the above"],"a":2,"e":"Ans. is ''c'' i.e., Time from exposure to development in 50% of cases Incubation period is the time interval between invasion by an infectious agent and appearnace of the first sign and symptom. ''Median incubation period'' is the time required for 50% cases to occur following exposure.","pyqMatches":[{"year":"2016","no":793,"q":"Median incubation period is ?","o":["Maximum time from exposure to development of symptoms in all cases","Minimum time from exposure to development of symptoms in all cases","Time from exposure to development in 50% of cases","None of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6018, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 629, '{"id":6018,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":629,"q":"Safety officer is recommended where factory has how many workers [In factory Act] ?","o":["250 or more","500 or more","1000 or more","2000 or more"],"a":2,"e":"Ans. is ''c'' i.e., 1000 or more [Ref Park 24th/e p. 852] Following standards are recommended :","pyqMatches":[{"year":"2016","no":890,"q":"Safety officer is recommended where factory has how many workers [In factory Act] ?","o":["250 or more","500 or more","1000 or more","2000 or more"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6019, 'PSM', 'Environment & Occupational Health', 'Easy', 'Preventive_&_Social_Medicine', 630, '{"id":6019,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":630,"q":"Standpipe in rural oreas is an example of which principle of primary health care?","o":["Equitable distribution","Community porticipation","Intersectoral coordination","Appropriate technology"],"a":2,"e":"Ans. is ''c'' i.e., Inter-sectoral coordination [Ref Primary heath care online; Park 23''/e p. 742] Public works, eg. ensuring an adequate supply of safe water (Stand pipe) and basic sanitation, comes under inter-sectoral coordination (multi-sectoral approach). Intersectoral coordination The primary health care is not provided by health sector alone. It involves all other related sectors of national and community development, in particular agriculture, animal husbandry, food, industry, education, housing, public works (e.g. an adequate supply of safe water and basic sanitation), communication and other sectors.","pyqMatches":[{"year":"2016","no":794,"q":"Standpipe in rural oreas is an example of which principle of primary health care?","o":["Equitable distribution","Community porticipation","Intersectoral coordination","Appropriate technology"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6020, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 632, '{"id":6020,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":632,"q":"Minimum floor space recommended for worker according to Factories Act?","o":["1000 Cu ft","500 Cu ft","200 Cu ft","100 Cu ft"],"a":1,"e":"Ans. is ''b'' i.e., 500 Cu ft [Ref Park 24th /e p. 852] The first Indian Factories act dates as for back as 1881. The act was revised and amended several times, the lates being the factories (Amendment) act, 1987. Following standards are recommended","pyqMatches":[{"year":"2016","no":889,"q":"Minimum floor space recommended for worker according to Factories Act?","o":["1000 Cu ft","500 Cu ft","200 Cu ft","100 Cu ft"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6021, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 633, '{"id":6021,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":633,"q":"Denominator in under -5 proportional mortality rate?","o":["Number of death under 5 years of age","Mid-year under - 5 population","Total deaths","Mid- year population"],"a":2,"e":"Ans. is ''c'' i.e., Total deaths","pyqMatches":[{"year":"2016","no":797,"q":"Denominator in under -5 proportional mortality rate?","o":["Number of death under 5 years of age","Mid-year under - 5 population","Total deaths","Mid- year population"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6022, 'PSM', 'Communicable Diseases', 'Easy', 'Preventive_&_Social_Medicine', 634, '{"id":6022,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":634,"q":"World heart day is celebrated on ?","o":["29th September","28th September","8th September","1st December"],"a":0,"e":"Ans. is ''a'' i.e., 29th September [Ref Internet] 29th September → World heart day 28th September → World rabies day 8th September → World literacy day Ph December → World AIDS day","pyqMatches":[{"year":"2016","no":888,"q":"World heart day is celebrated on ?","o":["29th September","28th September","8th September","1st December"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6023, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 635, '{"id":6023,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":635,"q":"Berkesonian bias is a type of ?","o":["Admission rate bias","Interviever bias","Information bias","Recall bias"],"a":0,"e":"Ans. is ''a'' i.e., Admission rate bias [Ref: Park 24thle p. 78-79] Berkesonian bias Berksonian bias results from the greater probability of hospital admission for people with two or more disease than for people with one disease. So, it is also known as admission rate bias.","pyqMatches":[{"year":"2012","no":778,"q":"Berkesonian bias is a type of ?","o":["Selection bias","Interviever bias","Information bias","Recell bias"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2016","no":798,"q":"Berkesonian bias is a type of ?","o":["Admission rate bias","Interviever bias","Information bias","Recall bias"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2012","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6024, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 636, '{"id":6024,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":636,"q":"True about iceberg of disease ?","o":["Clinician is concerned with hidden portion of iceberg","Tip of the iceberg represent clinical cases","Tetanus is classical example","Screening is done for Tip of the iceberg"],"a":1,"e":"Ans. is ''b'' i.e., Tip of the iceberg represent clinical cases Iceberg of disease * Disease in a community may be compared with an iceberg. * The floating tip of the iceberg represents what the physician sees in the community, i.e. clinical cases (Diagnosed case, symptomatic case of the clinically apparent case). * The vast submerged portion of the iceberg represents the hidden mass of disease, i.e. latent, inapparent, presymptomatic and undiagnosed cases and carriers in the community. - The \"waterline\" represents the demarcation between apparent and inapparent disease. - An epidemiologist is concerned with the hidden portion of the iceberg whereas the clinician is concerned with the tip of the iceberg. - Screening is done for a Hidden portion of the iceberg whereas diagnosis is done for the tip of the iceberg. * The iceberg phenomenon of disease is not shown by Rabies, Tetanus, Rubella, and Measles. * The clinician concerned only with the tip of iceberg, i.e symptomatic cases that are seen in clinical treatment, this can result in inaccurate view of the nature and causes of a disease results because the minority of the cases are studied (hidden cases:- submerged portion of iceberg is not studied) --> Clinician''s Fallacy.","pyqMatches":[{"year":"2016","no":799,"q":"True about iceberg of disease ?","o":["Clinician is concerned with hidden portion of iceberg","Tip of the iceberg represent clinical cases","Tetanus is classical example","Screening is done for Tip of the iceberg"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6025, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 637, '{"id":6025,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":637,"q":"Which of the following is Socratic method of communication?","o":["Lectures","Group discussion","Group discussion","Mass media"],"a":1,"e":"Ans. is ''b'' i.e., Group discussion [Ref Park 24th le p. 892 Two-way communication (socratic method) It is method of communication in which both the communicator and the audience take part and the information is transferred in both direction. Examples→ Group discussion, Panel discussion, symposium, workshop, conferences.","pyqMatches":[{"year":"2016","no":887,"q":"Which of the following is Socratic method of communication?","o":["Lectures","Group discussion","Group discussion","Mass media"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6026, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 638, '{"id":6026,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":638,"q":"Live influenza vaccine is given by which route ?","o":["Intradermal","Subcutaneous","Intramuscular","Intra nasal"],"a":3,"e":"Ans. is ''d'' i.e., Intranasal [Ref Park 24thie p. 168] The routes of important vaccines are :? Subcutaneous : Measles, rubella, killed influenza, killed cholera, IPV, yellow fever. Intramuscular : Mumps, killed influenza, typhoid Vi-polysaccharide, DPT (deep intramuscular), rabies, IPV. iii)Intradermal : BCG, rabies. Nasal : Live influenza. Oral : OPV, oral cholera, oral typhoid (typhoral).","pyqMatches":[{"year":"2016","no":800,"q":"Live influenza vaccine is given by which route ?","o":["Intradermal","Subcutaneous","Intramuscular","Intra nasal"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6027, 'PSM', 'Miscellaneous', 'Hard', 'Preventive_&_Social_Medicine', 639, '{"id":6027,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":639,"q":"PERT is which type of management technique?","o":["Based on behavioral science","Qualitative","Quantitative","None of the above"],"a":2,"e":"Ans. is ''c'' i.e.,Quantitative Management in human organization activity is simply the act of getting people together to accomplish desired goals and objectives. There are two major types of methods of management.","pyqMatches":[{"year":"2016","no":886,"q":"PERT is which type of management technique?","o":["Based on behavioral science","Qualitative","Quantitative","None of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6028, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 640, '{"id":6028,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":640,"q":"Which of the following is true ?","o":["Two live vaccines should not be given together","Live and killed vaccine should not be given together","Immunoglobolin should not be given for at least 6 weeks when a live vaccine is administered","Live vaccine should not be given for 12 weeks if immunoglobin has been given"],"a":3,"e":"Ans. is ''d'' i.e., Live vaccine should not be given for 12 weeks if immunoglobin has been given. Two live vaccines can be given simultaneously, but they should be given at different sites. Otherwise they should be given at an interval of at least 3 weeks (if administered at same site). Live and killed vaccine can be given together. Live vaccines should not normally be given for 12 weeks after an injection of normal human Ig and if a live vaccine has already been given, Human Ig injection should be deferred for 2 weeks.","pyqMatches":[{"year":"2012","no":351,"q":"Which of the following is true ?","o":["Glucokinase has high affinity for glucose","Hexokinase has low affinity for glucose","Glucokinase has low affinity for glucose","Hexokinase is induced by insulin"],"a":2,"source":"NEET_2012_Paper.pdf"},{"year":"2015","no":556,"q":"Which of the following is true?","o":["Glucocorticoids upregulate MHC expression","Glucocorticoids activate T-helper cells","Glucocorticoids activate cytotoxic T cells","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"},{"year":"2016","no":801,"q":"Which of the following is true ?","o":["Two live vaccines should not be given together","Live and killed vaccine should not be given together","Immunoglobolin should not be given for at least 6 weeks when a live vaccine is administered","Live vaccine should not be given for 12 weeks if immunoglobin has been given"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2012","2015","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6029, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 641, '{"id":6029,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":641,"q":"In RNTCP microscopic center is recommended for how much population ?","o":["5000","10000","50000","100000"],"a":3,"e":"Ans. is ''d'' i.e., 100000 The RNTCP designated ''Microscopy centre'' is established for 100000 population in planes (50000 in hilly and moutain areas). For every 5 microscopy centers (500000 population), there is one Senior TB laboratory supervisor (STLS). STLS rechecks all positive slides and 10% of all negative slides. Sputum microscopic examination during case finding is done in designated miroscopy centers. One tuberculosis unit is established for 500000 population in planes (250000 population in hilly/tribal areas). There is one state drug store (SDS) for every 50 million population.","pyqMatches":[{"year":"2016","no":885,"q":"In RNTCP microscopic center is recommended for how much population ?","o":["5000","10000","50000","100000"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6030, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 642, '{"id":6030,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":642,"q":"HALE is used to measure","o":["Disability adjusted life expectancy","Healthy life expectancy","Quality adjusted life expectancy","Expectancy free of disability"],"a":1,"e":"Ans. is ''b'' i.e., Healthy life expectancy Health-Adjusted life expectancy (HALE) HALE is the indicator used to measure a healthy life expectancy. HALE is based on the life expectancy at birth but includes an adjustment for time spent in poor health. It is the equivalent number of years in full health that a newborn can expect to live based on current rates of ill health and mortality.","pyqMatches":[{"year":"2016","no":802,"q":"HALE is used to measure","o":["Disability adjusted life expectancy","Healthy life expectancy","Quality adjusted life expectancy","Expectancy free of disability"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6031, 'PSM', 'Biostatistics', 'Easy', 'Preventive_&_Social_Medicine', 643, '{"id":6031,"subject":"PSM","chapter":"Biostatistics","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":643,"q":"During investigation of an epidemic, the area is declared free of epidemic when?","o":["Twice the incubation period of the disease since occurrence of the last case","Thrice the incubation period of the disease since occurrence of the last case","The longest incubation period for the disease","Incubation period for the disease plus two standard deviations"],"a":0,"e":"Ans. is ''a'' i.e., Twice the incubation period of the disease since occurrence of the last case [Ref Park 22\"d /e p. 123] There are following steps in the investigation of an epidemic :?","pyqMatches":[{"year":"2016","no":803,"q":"During investigation of an epidemic, the area is declared free of epidemic when?","o":["Twice the incubation period of the disease since occurrence of the last case","Thrice the incubation period of the disease since occurrence of the last case","The longest incubation period for the disease","Incubation period for the disease plus two standard deviations"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6032, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 644, '{"id":6032,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":644,"q":"Colored kit for STD treatment is which type of approach?","o":["Preventive","Symptomatic","Syndromic","Rehabilitative"],"a":2,"e":"Ans. is ''c'' i.e., Syndromic [Ref Park 23'' /e. p. 332-336] In 1988, World Health Organization introduced the concept of Syndromic management''. In syndromic management, diagnosis and treatment is not based on specific diseases identified by testing but rather on syndromes, which is a group of clinical findings. Treatment is generally given for all or at least most commonly seen diseases or organisms that could cause that syndrome. Pre-packed colour coded STI/RTI kits have been provided for free supply to all designated STI/RTI clinics. Kit 1 → Grey, for urethral discharge, ano-rectal discharge, cervicitis. Kit 2 → Green, for vaginitis Kit 3 → White, for genital ulcers Kit 4 → Blue, for genital ulcers Kit 5 → Red, for genital ulcers Kit 6 → Yellow, for lower abdominal pain Kit 7 → Black, for scortal swelling.","pyqMatches":[{"year":"2016","no":884,"q":"Colored kit for STD treatment is which type of approach?","o":["Preventive","Symptomatic","Syndromic","Rehabilitative"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6033, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 645, '{"id":6033,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":645,"q":"Specific content in malaria vaccine is?","o":["Gametocytic protein","Polysaccharide sheath","Sporozoite protein","Lipoprotein envelop"],"a":2,"e":"Ans. is ''c'' i.e., Sporozoite protein [Ref Internet] Circumsporozoite protein (CSP) is a secreted protein of the sporozoite stage of the malaria parasite (plasmodium sp) and the antigenic target of RTS,S, a pre-erythrocytic malaria vaccine currently undergoing clinical trails. The amino- acid sequence of CSP consists of an immunodominant central repeat region flanked by conserved motifs at the N-and C-termini that are implicated in protein processing as the parasite travels from the mosquito to the mammalian vector. The structure and function of CSP is highly conserved across the various strains of malaria that infect humans non-human primates and rodents. It can first be detected in large quantities as sporozoites are forming within oocysts residing the midgut walls of infected mosquitoes Upon egression from mature oocysts, sporozoits begin migrating to the salivary glands, and CSP is known to be an important mediator of this process. Additionally CSP is involved in hepatocyte binding in the mammalian host. Here the N-terminus and central repeat region initially facilate parasite binding. Once the hepatocyte surface proteolytic cleavage at region 1 of the N-terminus exposes the adhesive domian of the C- terminus, thereby priming the parasites for invasion of the liver.","pyqMatches":[{"year":"2016","no":804,"q":"Specific content in malaria vaccine is?","o":["Gametocytic protein","Polysaccharide sheath","Sporozoite protein","Lipoprotein envelop"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6034, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 646, '{"id":6034,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":646,"q":"Jai Vigyan National Mission is for?","o":["Adolescent girls health","Mother & child health [MCH]","Science & technology","Child labour prevention"],"a":2,"e":"Ans. is ''c'' i.e., Science & technology [Ref Information p. 1997- 98] The Union Minister for human resource Development, Dr. Murli Manohar Joshi, has said that scientific Institutions would take up 21 important development projects as part of the Jai Vigyan National Mission with focus on science and technology. These projects would be in areas such as food security, energy conservations, health care, disaster management and bio-diversity. Scientific and R and D institutions would take up one project in 1999. All the projects would be given green channel treatment with procedures relaxed he said while participating at the annual sessions of the 86t5 Indian Science Congress in Chennal on Jan.3. The minister said he had directed the department of Bio-technology to institute 10 awards every year for outstanding young scientists in biosciences. This would encourage high quality research of excellence and relevance. As achieving excellence was dependent in innovative talents which in turn needed identification and nurturing from an early age, a new scheme to select under 18 youngsters of outstanding talent and to provide them with necessary ambience and opportunities for harnessing their talent and been instituted.","pyqMatches":[{"year":"2016","no":883,"q":"Jai Vigyan National Mission is for?","o":["Adolescent girls health","Mother & child health [MCH]","Science & technology","Child labour prevention"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6035, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 647, '{"id":6035,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":647,"q":"Role of magnesium [Mg] in OPV?","o":["Adjuvant","Preservative","Stabilizar","Antiinfective"],"a":2,"e":"Ans. is ''c'' i.e., Stabilizer [Ref www.who.int] \"Polio Sabin (oral) vaccine is a magnesium chloride stabilized preparation of live attenuated polio viruses of sabin strains type 1, 2, er 3\" Stabilizers These are used to confirm product quality or stability. Examples are potassium or sodium salts, lactose, human serum albumin, gelatin and bovine serum albumin","pyqMatches":[{"year":"2016","no":805,"q":"Role of magnesium [Mg] in OPV?","o":["Adjuvant","Preservative","Stabilizar","Antiinfective"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6036, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 648, '{"id":6036,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":648,"q":"The difference between descriptive and analytic studies?","o":["Descriptive studies are used to test hypothesis","Analytic studies are used to formulate a hypothesis","Descriptive studies are first phase in epidemiology","Analytic studies observe distribution of disease"],"a":2,"e":"Ans. is ''c'' i.e., Descriptive studies are first phase in epidemiology [Ref Park 24thie p. 67-75] Descriptive studies are first phase of an epidemiological investigation. These studies are concerned with observing the distrubution of disease in time, place and person. Descriptive studies are used to formulate eitological hypothesis. Analytical studies are the second major type of epidemiological studies (after descriptive studies). It contrast to descriptive studies that look at entire population, in analytic studies, the subject of interest is the individual within the population (except in ecological study). The object is not to formulate, but to test hypothesis. In experimental studies, epidemiologist actively intervene to change a disease determinant or progression of disease. Experimental studies are used for testing hypothesis.","pyqMatches":[{"year":"2016","no":806,"q":"The difference between descriptive and analytic studies?","o":["Descriptive studies are used to test hypothesis","Analytic studies are used to formulate a hypothesis","Descriptive studies are first phase in epidemiology","Analytic studies observe distribution of disease"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6037, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 649, '{"id":6037,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":649,"q":"Which of the following defines movement across scioeconomic status.","o":["Social equality","Social upliftment","Social mobility","Social insurance"],"a":2,"e":"Ans. is ''c'' i.e., Social Mobility [Ref Park 23'' le p. 688 & 22\"d/e p. 639] Social mobility is the degree to which an individual''s family or group''s social status can change throughout the course of their life through a system of social hierarechy, i.e. Social mobility refers to movement of individuals/families across different socioeconomic levels.","pyqMatches":[{"year":"2016","no":874,"q":"Which of the following defines movement across scioeconomic status.","o":["Social equality","Social upliftment","Social mobility","Social insurance"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6038, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 650, '{"id":6038,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":650,"q":"Strength of association of outcome and risk factor is measured by?","o":["Relative risk","Attributable risk","Population attributable risk","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Relative risk [Ref: Park 24`Ve p. 83] Relative risk is a direct measure of the strength of association between suspected cause and effect. For example a relative risk of 2 means that the incidence rate is 2 times higher in the exposed group as compared with unexposed -> i.e., a 100% increase in risk. On the other hand, attributable risk indicates the extent which is attributed by risk factor (exposure) to disease. For example attributable risk of 90% means 90 percent of disease among exposed is due to exposure to risk factor. In simple words :? Relative risk indicates the increased percentage of risk of developing a disease, if person is exposed to risk factor. Attributable risk indicates the percentage of disease which is attributed by risk factor among the exposed. Relative risk is a better index than is attributable risk for assessing the etiological role of a factor in disease.","pyqMatches":[{"year":"2016","no":807,"q":"Strength of association of outcome and risk factor is measured by?","o":["Relative risk","Attributable risk","Population attributable risk","None of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6039, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 651, '{"id":6039,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":651,"q":"Important measure for National health policy?","o":["Relative risk","Odds ratio","Incidence","Attributable risk"],"a":3,"e":"Ans. is ''d'' i.e.,Attributable risk [Ref Park 24th/e p. 83] Relative risk Vs Attributable risk Relative risk is a direct measure of the strength of association between suspected cause and effect. For example a relative risk of 2 means that the incidence rate is 2 times higher in the exposed group as compared with unexposed - i.e., a 100% increase in risk. On the other hand, attributable risk indicates the extent which is attributed by risk factor (exposure) to disease. For example attributable risk of 90% means 90 percent of disease among exposed is due to exposure to risk factor. In simple words :- Relative risk indicates the increased percentage of risk of developing a disease, if person is exposed to risk factor. Attributable risk indicates the percentage of disease which is attributed by risk factor among the exposed. Relative risk is a better index than is attributable risk for assessing the etiological role of a factor in disease. On the other hand, attributable risk gives a better idea than does relative risk of the impact of successful preventive or public health programme might have in reducing the problem. That means attributable risk reflect the public health importance better than relative risk.","pyqMatches":[{"year":"2016","no":808,"q":"Important measure for National health policy?","o":["Relative risk","Odds ratio","Incidence","Attributable risk"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6040, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 652, '{"id":6040,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":652,"q":"Range of flight of Aedes mosquito is ?","o":["1 km","Less than 100 m","400 m","10 kms"],"a":1,"e":"Ans. is ''b'' i.e., Less than 100 m [Ref Park 23''/e p. 771 & 22\"d/e p. 715] Aedes do not fly over long distances; usually less than 100 metres (110 yards). Anopheles → 3 - 5 Kms Culex → 11 Kms Aedes → 100 m","pyqMatches":[{"year":"2016","no":871,"q":"Range of flight of Aedes mosquito is ?","o":["1 km","Less than 100 m","400 m","10 kms"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6041, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 653, '{"id":6041,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":653,"q":"A study that gives the prevalence of delusion in the elderly at a given point of time?","o":["Case-control study","Cohort study","Cross-sectional study","Ecological study"],"a":2,"e":"Ans. is ''c'' i.e., Cross-sectional study Cross-sectional studies A cross-sectional study is the simplest form of an observational study. It is also known as a prevalence study. It is based on a single examination of a cross-section of the population at one point of time. The results of this examination can be projected on the whole population. The cross-sectional study tells about the distribution of a disease rather than its etiology. Cross-sectional studies can be thought of as providing a snapshot of the frequency and characteristic of a disease in a population at a particular point in time. A cross-sectional study is more useful for chronic disease, as the population is studied at once, no follow-up is required.","pyqMatches":[{"year":"2016","no":809,"q":"A study that gives the prevalence of delusion in the elderly at a given point of time?","o":["Case-control study","Cohort study","Cross-sectional study","Ecological study"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6042, 'PSM', 'Epidemiology', 'Hard', 'Preventive_&_Social_Medicine', 654, '{"id":6042,"subject":"PSM","chapter":"Epidemiology","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":654,"q":"100 individuals are diagnosed with lung cancer in a population of 100000. Out of 100 patients, 80 were smokers and 20000 were smokers in totals population. What is PAR?","o":["60","75","80","90"],"a":1,"e":"Ans. is ''b'' i.e., 75 [Ref Park 241th le p. 83] In the given question : Incidence in total population = 100 per 1 lac Number of exposed = 20000 ( All exposed) Number of non-exposed = 80000 (100000 - 20000) Non-exposed having lung cancer=20 (out of 100 patients 80 were smoker. Thus 20 are noneexposed) Incidence among non-exposed = 20 per 80000 or 25 per 100000","pyqMatches":[{"year":"2016","no":810,"q":"100 individuals are diagnosed with lung cancer in a population of 100000. Out of 100 patients, 80 were smokers and 20000 were smokers in totals population. What is PAR?","o":["60","75","80","90"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6043, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 655, '{"id":6043,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":655,"q":"Number of holes in mosquito net [per sq. inch] ?","o":["50","150","100","200"],"a":1,"e":"Ans. is ''b'' i.e., 150 [Ref Park 24th/e p. 810 & 23''/e p. 773] The best pattern of mosquito net is the rectangular net. There should not be a single rent in the net. The Size of openings in the net is of utmost importance, the size should not exceed 0.0475 inch in any diameter. The number of holes in one square inch in usually 150.","pyqMatches":[{"year":"2016","no":865,"q":"Number of holes in mosquito net [per sq. inch] ?","o":["50","150","100","200"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6044, 'PSM', 'Environment & Occupational Health', 'Moderate', 'Preventive_&_Social_Medicine', 656, '{"id":6044,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":656,"q":"Not a primary air pollutant?","o":["SO2","CO,","Ozon","VOCs"],"a":2,"e":"Ans. is ''c'' i.e.,Ozone [Ref Park 24tVe p. 770] Air pollution is the introduction of chemicals particulate matter, or biological material into the atmosphere that cause harm or discomfort to humans or other living organisms, or damages the natural environment. An air pollutant is known as a substance in the air that can cause harm to humans and the-environment.","pyqMatches":[{"year":"2016","no":864,"q":"Not a primary air pollutant?","o":["SO2","CO,","Ozon","VOCs"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6045, 'PSM', 'Epidemiology', 'Moderate', 'Preventive_&_Social_Medicine', 657, '{"id":6045,"subject":"PSM","chapter":"Epidemiology","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":657,"q":"True about standardization are all except?","o":["Most commonly used for age differences","Direct standardization is used when population is large","Age specific rates are required in indirect standardization","All are correct"],"a":2,"e":"Ans. is ''c'' i.e., Age specific rates are required in indirect standardization [Ref: Park 23\"/e p. 58] Indirect standardization When the population is small (or outcome is rare) the number of events observed can be small. In that circumstance, indirect standardized methods can be used to produce a standardized mortality rate (SMR) or a standardized incidence rate (SIR). In indirect standardization, one computes the number of events (mortality) that would have been expected if the event rates (mortality rate) from the standard population had applied in the study population, i.e. age specific rates of standard population are applied to study population (opposite to direct standardization). Study population is used to provide age specific death rates. Within each age stratum, one multiplies the age specific rate of standard population by the number of people in the study population to determine the number of cases that would have expected if that were the rate in the study group These expected numbers are added up across all age groups and divided into the observed number to yield the SMR. Advantage of indirect standardization is that age specific rates of study population are not required.","pyqMatches":[{"year":"2016","no":812,"q":"True about standardization are all except?","o":["Most commonly used for age differences","Direct standardization is used when population is large","Age specific rates are required in indirect standardization","All are correct"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6046, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 658, '{"id":6046,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":658,"q":"Standardization is most important for?","o":["Sex distribution","Age distribution","Disease distribution","None of the above"],"a":1,"e":"Ans. is ''b'' i.e., Age distribution [Ref Park 23rale p. 58] Standardization is most commonly used for age. A standardizated death rate (ASDR) is the best mortality indicator. ''Crude death rate'' is to be standardized for age for comparison of two population, as age composition is different.","pyqMatches":[{"year":"2016","no":813,"q":"Standardization is most important for?","o":["Sex distribution","Age distribution","Disease distribution","None of the above"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6047, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 659, '{"id":6047,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":659,"q":"Standardized death rates are used because health?","o":["For valid comparisom of two groups of different health determinants","Calculations are more accurate","To avoid selection bias","All of the above"],"a":0,"e":"Ans. is ''a'' i.e., For valid comparison of two groups of different health determinants [Ref Park 23rd /e p. 58] Standardization (or adjustment) of rates is used to unable the valid comparison of groups that differ regarding an important health determinant (most commonly age). For example, if we want to compare the death rates of two different populations with different age composition, the crude death rate is not right yardstick because rates are only comparable if the populations upon which they are based are comparable.","pyqMatches":[{"year":"2016","no":814,"q":"Standardized death rates are used because health?","o":["For valid comparisom of two groups of different health determinants","Calculations are more accurate","To avoid selection bias","All of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6048, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 660, '{"id":6048,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":660,"q":"Pulses are deficient in ?","o":["Methionirfe","Lysine","Threonine","All"],"a":0,"e":"Ans. is ''a'' i.e.,Methionine [Ref : Park 23''/e p. 628 & 21\"/e p. 578] Some amino acids are deficient in a particular food, called limiting amino acids. For example, cereals and wheat are deficient in threonine and lysine, pulses are mainly deficient in methionine and cysteine, and maize is deficient in tryptophan and lysine. Supplementary action of proteins : If two or more food items eaten together, their proteins supplement the deficient amino acid of each other. For example cereals are deficient in threonine and lysine, whereas pulses are deficient in methionine and cystein. If both are taken together, their proteins complement each other and provide a more balanced and complete protein intake.","pyqMatches":[{"year":"2016","no":862,"q":"Pulses are deficient in ?","o":["Methionirfe","Lysine","Threonine","All"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6049, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 661, '{"id":6049,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":661,"q":"All are true about natural experiments, except?","o":["Researcher has no control over the allocation of subjects","James lind experiment is an example","Includes Randomized controlled trials [RCTs]","All are correct"],"a":2,"e":"Ans. is ''c'' i.e., Includes Randomized controlled trials [RCTs] [Ref Modern epidemiology p. 397] Natural experiments are those in which exposure to the event or intervention of interest has not been manipulated by researcher. The individuals exposed to the experimental and control conditions are determined by nature or by other factors outside the control of the investigators. When a naturally occurring event or situation is exploited by a researcher to help answer a research question, it is called a natural experiment. The researcher has little or no control over the situation that is being observed. A good example of natural experiment is one by James Lind in 1747 on the prevention of scurvy among sailors. He compared the effects of different acidic substances, ranging from vinegar to cidr, on grups of afflicted sailors, and found that the group who from vinegar to cidr, on groups of afflicted sailors, and found that the group who were given oranges and lemons had largely recovered from scurvy after 6 days. Other important example is John Snow''s natural experiment on cholera linked with contaminated water. RCT is not natural experiment as researcher allocate the individuals in study and control group by randomization.","pyqMatches":[{"year":"2016","no":816,"q":"All are true about natural experiments, except?","o":["Researcher has no control over the allocation of subjects","James lind experiment is an example","Includes Randomized controlled trials [RCTs]","All are correct"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6050, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 662, '{"id":6050,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":662,"q":"Most common nutritional problem in India?","o":["Low birth weight","Fluorosis","Iran deficiency anemia","Vitamin A deficiency"],"a":2,"e":"Ans. is ''c'' i.e.,Iron deficiency anemia [Ref Park 24thle p. 677, 661- 667] The major nutritional problem in India are :","pyqMatches":[{"year":"2016","no":861,"q":"Most common nutritional problem in India?","o":["Low birth weight","Fluorosis","Iran deficiency anemia","Vitamin A deficiency"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6051, 'PSM', 'Miscellaneous', 'Hard', 'Preventive_&_Social_Medicine', 663, '{"id":6051,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":663,"q":"In a study a patient does not know the nature of drug [whether a placebo or curative drug] he is taking. The researcher knows the drug type to be given to the individuals in study. Types of blinding in this study is ?","o":["Single","Double","Triple","Combined double /triple"],"a":0,"e":"Ans. is ''a'' i.e., Single [Ref Park 24''1* p. 78] Single blinding Double blinding Triple blinding Study subjects are not aware of the treatment they are receiving Study subjects as well as investigator are not aware of the treatment study subjects are receiving Study subjects, investigator as well as analyzer are not aware of the treatmc study subjects are receiving","pyqMatches":[{"year":"2016","no":817,"q":"In a study a patient does not know the nature of drug [whether a placebo or curative drug] he is taking. The researcher knows the drug type to be given to the individuals in study. Types of blinding in this study is ?","o":["Single","Double","Triple","Combined double /triple"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6052, 'PSM', 'Nutrition', 'Moderate', 'Preventive_&_Social_Medicine', 664, '{"id":6052,"subject":"PSM","chapter":"Nutrition","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":664,"q":"An 70 kg farmer is consuming 56 grams proteins, 275 grams carbohydrate and 60 grams lipids. He consuming?","o":["Less calories","More calories","Adequate calories","Connot be commented"],"a":0,"e":"Ans. is ''a'' i.e., Less calories [Ref Read below] Protein and carbohydrate both provide 4 cal per gram and fat provides 9 cal per gram. Thus the farmer is taking (cal or Kcal per day) = (56 x 4) + (275 x 4) + (60 x 9) = 1864","pyqMatches":[{"year":"2016","no":856,"q":"An 70 kg farmer is consuming 56 grams proteins, 275 grams carbohydrate and 60 grams lipids. He consuming?","o":["Less calories","More calories","Adequate calories","Connot be commented"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6053, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 665, '{"id":6053,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":665,"q":"Mid year population is estimated on ?","o":["1st March","1st July","1st April","15th August"],"a":1,"e":"Ans. is ''b'' i.e., 1St July [Ref Park 22\"/e p. 58 & 21\"/e p. 52] Denominator in crude death rate is mid year population, which is estimated on first of July of an year.","pyqMatches":[{"year":"2016","no":819,"q":"Mid year population is estimated on ?","o":["1st March","1st July","1st April","15th August"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6054, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 666, '{"id":6054,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":666,"q":"Poor man''s iron source is?","o":["Almond","Grapes","Soya","Jaggery"],"a":3,"e":"Ans. is ''d'' i.e., Jaggery [Ref Park 24th/e p. 661 & 23rd/e p. 623] There are two major forms of iron :? 1) Haem-iron It is better absorbed but is less important source of iron in Indian diet. It is mainly found in foods of animal origin, e.g. liver, meat, poultry and fish. 2) Non-haem iron It is poorly absorbed but is the important source of iron in Indian diet. It is mainly found in foods of vegetable origin, e.g. cereales, green leafy vetetables, legumes, nuts, oilseeds, juggery, and dried fruits. Among dry fruits, cashew nut has maximum iron (9%) followed by almonds (7%), and pistachos (7%). Iron of milk is low in all mammalian species. Jaggery is considered as poor man''s iron source. It contains a good amount of iron along with vitamin-A.","pyqMatches":[{"year":"2016","no":855,"q":"Poor man''s iron source is?","o":["Almond","Grapes","Soya","Jaggery"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6055, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 667, '{"id":6055,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":667,"q":"Meningococcal vaccine contains ?","o":["50 mcg of polysccharide of each strain","100 mcg of polysccharide of each strain","1000 mcg of polysccharide of each strain","5000 mcg of polysccharide of each strain"],"a":0,"e":"Ans. is ''a'' i.e., 50 mcg of polysaccharide of each strain [Ref Park 24th/e p. 176] Vaccines are available for group A, C, Y and W-125. There is no group B vaccine available at present. Vaccines are prepared from capsular polysaccharide. Bivalent (A, C), trivalent (A, C, W135), and tetravalent (A, C, W135, Y) vaccines are available. The vaccines contain 50 mcg of polysaccharide of each individual strain.","pyqMatches":[{"year":"2016","no":820,"q":"Meningococcal vaccine contains ?","o":["50 mcg of polysccharide of each strain","100 mcg of polysccharide of each strain","1000 mcg of polysccharide of each strain","5000 mcg of polysccharide of each strain"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6056, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 668, '{"id":6056,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":668,"q":"Dual record system is useful for estimation of?","o":["Literacy","Fertility","Population density","Sex ratio"],"a":1,"e":"Ans. is ''b'' i.e., Fertility [Ref Park 24th/e p. 878] Sample registration system (SRS), initiated in mid 1960s provides reliable estimates of birth (fertility) and death (mortality) rates at state and national levels. It is a dual record system,consisting of continuous enumeration of birth and death by an enumerator and an independent survey every 6 months by an investigator supervisor. Main objective of SRS is to provide reliable estimates of birth rate, death rate and infant mortality rate at the natural division level for rural areas and at state level for urban areas. Infant mortality rate is the decisive indicator for estimation of sample size at natural division. Sample design for SRS is uni-stage stratified simple random sample. SRS now covers entire country.","pyqMatches":[{"year":"2016","no":852,"q":"Dual record system is useful for estimation of?","o":["Literacy","Fertility","Population density","Sex ratio"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6057, 'PSM', 'Maternal & Child Health', 'Easy', 'Preventive_&_Social_Medicine', 669, '{"id":6057,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":669,"q":"How many doses of monovalent meningococcal ''C'' vaccine is given in Infants ?","o":["One","Two","Three","Four"],"a":1,"e":"Ans. is ''b'' i.e., Two [Ref Park 24th/e p. 176] Monovalent Men A conjugate vaccine should be given as a single dose to individuals 1-29 years of age. For monovalent Men C conjugate vaccine, one single intramuscular dose is recommended for children aged > 12 months, teenagers and adults. Children 2-11 months of age require 2 dose administration at an interval of at least 2 months and a booster about 1 year thereather. Quadrivalent vaccines are administered as a single dose to individuals aged 2 years.","pyqMatches":[{"year":"2016","no":821,"q":"How many doses of monovalent meningococcal ''C'' vaccine is given in Infants ?","o":["One","Two","Three","Four"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6058, 'PSM', 'Maternal & Child Health', 'Moderate', 'Preventive_&_Social_Medicine', 670, '{"id":6058,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":670,"q":"Which does not have Live births as denominator?","o":["Infant mortality rate","Neonatal mortality rate","Child mortality rate","Child death rate"],"a":3,"e":"Ans. is ''d'' i.e., Child death rate [Ref Park 24thle p. 608-612] CDR = No. of deaths of children aged 1-4 years / Total No. of children aged 1-4 years.","pyqMatches":[{"year":"2016","no":851,"q":"Which does not have Live births as denominator?","o":["Infant mortality rate","Neonatal mortality rate","Child mortality rate","Child death rate"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6059, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 671, '{"id":6059,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":671,"q":"Secondary attack rate of mumps:?","o":["75%","85%","95%","< 50%"],"a":1,"e":"Ans. is ''b'' i.e., 85% [Ref Park 23''/e p. 147 & 22\"d/e p. 139- 140] SAR of some important infectious diseases Measles 80% Rubella 90 - 95% Chicken pox 90% Pertussis 90% Mumps 86%","pyqMatches":[{"year":"2016","no":822,"q":"Secondary attack rate of mumps:?","o":["75%","85%","95%","< 50%"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6060, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 672, '{"id":6060,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":672,"q":"Jai Vigyan Mission mode project in India is for?","o":["Measles","TB","Rheumatic fever","STD"],"a":2,"e":"Ans. is ''c'' i.e., Rheumatic fever [Ref Park 24tVe p. 397] Jai Vigyan Mission Mode project on Community Control of RF/RHD in India is being carried out with four main components, viz. to study the epidemiology of streptococcal sore throats, establish registries for RF and RHD, vaccine development for streptococcal infection and conducting advanced studies on pathological aspects of RF and RHD.","pyqMatches":[{"year":"2016","no":850,"q":"Jai Vigyan Mission mode project in India is for?","o":["Measles","TB","Rheumatic fever","STD"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6061, 'PSM', 'Communicable Diseases', 'Easy', 'Preventive_&_Social_Medicine', 673, '{"id":6061,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":673,"q":"Isolation period of TB ?","o":["2 days after treatment","1 week after treatment","2 weeks after treatment","3 weeks after treatment"],"a":3,"e":"Ans. is ''d'' i.e., 3 weeks after treatment [Ref Park 24th/e p. 129] Period of isolation recommended Tuberculosis (sputum +) → 2 weeks adult, 6 weeks paediatric.","pyqMatches":[{"year":"2016","no":823,"q":"Isolation period of TB ?","o":["2 days after treatment","1 week after treatment","2 weeks after treatment","3 weeks after treatment"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6062, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 674, '{"id":6062,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":674,"q":"Prevalence of RHD in India in 5-15 years age group?","o":["1-2 per 1000","5-7 per 1000","10-12 per 1000","13-15 per 1000"],"a":1,"e":"Ans. is ''b'' i.e., 5-7 per 1000 [Ref Park 24th/e p. 397] In India, RHD is prevalent in the range of 5-7 per thousand in 5-15 years age group and there are about 1 million RHD cases in India. RHD constitutes 20-30% of hospital admissions due to CVD in India. Streptococcal infections are very common especially in children living in under -privileged conditions, and RF is reported to occur in 1-3 per cent of those infections.","pyqMatches":[{"year":"2016","no":849,"q":"Prevalence of RHD in India in 5-15 years age group?","o":["1-2 per 1000","5-7 per 1000","10-12 per 1000","13-15 per 1000"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6063, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 675, '{"id":6063,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":675,"q":"Sensitivity of a screening test tells about","o":["Percentage of disease people among those with a positive test","Percentage of disease people among those with a negative test","Percentage of healthy people among those with a negative test","Percentage of healthy people among those with a positive test"],"a":0,"e":"Ans. is ''a'' i.e., Percentage of disease people among those with a positive test Sensitivity: Ability of a screening test to identify correctly all those who have the disease (Cases). Specificity: Ability of a screening test to identify correctly all those who don''t have the disease (healthy). Positive predictive value (PPV): Ability of a screening test to identify correctly all those who have the disease, out of all those who test positive on a screening test. Negative predictive value (NPV): Ability of a screening test to identify correctly all those who don''t have the disease, out of all those who test negative on a screening test. When a screening test is used to diagnose a disease, the test outcome can be positive (diseased) or negative (healthy), while the actual health status of the person may be different. In that setting : True positive → Diseased people correctly diagnosed as diseased. False positive → Healthy people wrongly identified as diseased. True negative → Healthy people correctly identified as healthy. False negative → Diseased people wrongly identified as healthy.","pyqMatches":[{"year":"2016","no":824,"q":"Sensitivity of a screening test tells about","o":["Percentage of disease people among those with a positive test","Percentage of disease people among those with a negative test","Percentage of healthy people among those with a negative test","Percentage of healthy people among those with a positive test"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6064, 'PSM', 'Epidemiology', 'Moderate', 'Preventive_&_Social_Medicine', 676, '{"id":6064,"subject":"PSM","chapter":"Epidemiology","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":676,"q":"If effective treatment for a disease is introduced in a community, what will be the effect on incidence [I] and prevalence [P] ?","o":["No change in P & I","Both P & I will decrease","P will decrease & I will increase","P will decrease & I will remains the same"],"a":3,"e":"Ans. is ''d'' i.e.,P will decrease & I will remains the same [Ref Park 24th/e p. 66 & 23rdie p. 62] New effective treatment will cure the patient and thereby decrease the duration of disease. So, new effective treatment will affect the duration of disease. Incidence measures the rate at which new cases are occurring in a population, It is not influenced by duration. So, new effective treatment will have no effect on incidence. On the other hand, prevalence will decrease due to decrease in duration of disease.","pyqMatches":[{"year":"2016","no":825,"q":"If effective treatment for a disease is introduced in a community, what will be the effect on incidence [I] and prevalence [P] ?","o":["No change in P & I","Both P & I will decrease","P will decrease & I will increase","P will decrease & I will remains the same"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6065, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 677, '{"id":6065,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":677,"q":"WHO VISION 2020 initiative includes ?","o":["Corneal ulcer","Trachoma blindness","Diabetic retinopathy","Vernal kerato Conjunctivitis"],"a":1,"e":"Ans. is ''b'' i.e., Trachoma blindness After the realization that unless blindness control efforts are intensified, the prevalence of blindness will double by 2020 AD, the WHO along with an International Partnership committee launched the Vision 2020 Initiative in 1995. The diseases identified for global elimination include : ?","pyqMatches":[{"year":"2016","no":848,"q":"WHO VISION 2020 initiative includes ?","o":["Corneal ulcer","Trachoma blindness","Diabetic retinopathy","Vernal kerato Conjunctivitis"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6066, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 678, '{"id":6066,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":678,"q":"A screening test has sensitivity of 90% and specificity of 99%. The prevalence of disease under investigation is 5 per 1000 population. What is the PPV of the given screening test?","o":["10","70","33","99"],"a":2,"e":"Ans. is ''c'' i.e.,33 [Ref Park 23rd/e p. 139 & 22\"dle p. 132; Hopefield biostatistics 4thle p. 49] Positive predictive value is related to sensitivity specificity and prevalence. This relationship is represented by Baye''s theorem : -","pyqMatches":[{"year":"2016","no":826,"q":"A screening test has sensitivity of 90% and specificity of 99%. The prevalence of disease under investigation is 5 per 1000 population. What is the PPV of the given screening test?","o":["10","70","33","99"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6067, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 679, '{"id":6067,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":679,"q":"Major reservoir of KFD ?","o":["Human","Squirrels","Cattle","Monkey"],"a":1,"e":"Ans. is ''b'' i.e.,Squirrels KFD, also known as ''monkey disease'' is a hemorrhagic fever caused by flavivirus belonging to group-B arbovirus. Disease is common in four districts of Karnataka : Shimoga, North Kannda, South Kanada and Chikamagaloor. KFD was first recognized in 1957 in Shimoga district of Karnataka. Major vector for transmission of KFD is hard tick (Haemophysalis spinigera and H. turtura). But, soft tick can also transmit the disease, especially outside the India. Rats and squirrels are the major reservoir. Monkey acts as amplifying host and man is incidental dead-end host, there is no man-to-man transmission.","pyqMatches":[{"year":"2016","no":844,"q":"Major reservoir of KFD ?","o":["Human","Squirrels","Cattle","Monkey"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6068, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 680, '{"id":6068,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":680,"q":"Color of box containing drugs for treatment of category I of TB -","o":["Red","Blue","Yellow","Green"],"a":0,"e":"Ans. is ''a'' i.e.,Red [Ref Park 24th/e p. 199]","pyqMatches":[{"year":"2016","no":843,"q":"Color of box containing drugs for treatment of category I of TB","o":["Red","Blue","Yellow","Green"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6069, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 681, '{"id":6069,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":681,"q":"Best indicator for spread of TB in a community?","o":["Annual infection rate","Prevalence of infection","Case rate","Incidence of new cases"],"a":0,"e":"Ans. is ''a'' i.e., Annual infection rate [Ref Park 24thle p. 191-195 & 23''/e p. 177] The following epidemiological-indices are used in tuberculosis problem measurement and programme strategy","pyqMatches":[{"year":"2016","no":827,"q":"Best indicator for spread of TB in a community?","o":["Annual infection rate","Prevalence of infection","Case rate","Incidence of new cases"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6070, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 682, '{"id":6070,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":682,"q":"Antiboiotic of choice for severe pneumonia in 1 year all child?","o":["Cotrimoxazole","Ciprofloxacin","Benzyl penicillin","Tetracycline"],"a":2,"e":"Ans. is ''c'' i.e., Benzyl penicillin [Ref Park 24`h/e p. 181,182] Antibiotics of choice for treatment of acute respiratory infections in children aged 2 months - 5years","pyqMatches":[{"year":"2016","no":841,"q":"Antiboiotic of choice for severe pneumonia in 1 year all child?","o":["Cotrimoxazole","Ciprofloxacin","Benzyl penicillin","Tetracycline"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6071, 'PSM', 'Communicable Diseases', 'Easy', 'Preventive_&_Social_Medicine', 683, '{"id":6071,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":683,"q":"Healthy carrier is seen in?","o":["Measles","Rubella","Meningococcal meningits","Influanza"],"a":2,"e":"Ans. is ''c'' i.e., Meningococcal meningitis [Ref Park 24th/e p. 103- 106 & 23\"1/e p. 95, 96] Temporary carrier Temporary carriers shed the infectious agent for short period of time. This category may include Incubatory carriers : Measles, mumps, polio, pertussis (whooping cough), influenza, diphtheria, Hepatitis B. Convalescent carriers : Typhoid, cholera, diphtheria, Pertussis (whooping cough), dysentery. Healthy carriers : Polio, Cholera, meningococcal meningitis, Salmonellosis, diphtheria Chronic carrier Chornic carriers excrete the infectious agent for indefinite period. Examples : Typhoid, hepatitis B, dysentery, malaria, gonorrhoea, cerebrospinal menigitis, Diphtheria.","pyqMatches":[{"year":"2016","no":835,"q":"Healthy carrier is seen in?","o":["Measles","Rubella","Meningococcal meningits","Influanza"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6072, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 684, '{"id":6072,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":684,"q":"Infectivity of convalescent carrier of cholera lasts for?","o":["1-5 days","1-2 weeks","2-3 weeks","4-5 weeks"],"a":2,"e":"Ans. is ''c'' i.e., 2-3 weeks There are following types of carrier in cholera : Incubatory : Shed vibrios only in the brief incubation period of 1-5 days. Convalescent : Shed vibrios for 2-3 weeks. Healthy or contact carrier : Has had subclinical infection and shed vibrios for less than 10 days. Chronic carriers : Can shed vibrios for months or years and may have persistent infection in gall bladder","pyqMatches":[{"year":"2016","no":836,"q":"Infectivity of convalescent carrier of cholera lasts for?","o":["1-5 days","1-2 weeks","2-3 weeks","4-5 weeks"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6073, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 685, '{"id":6073,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":685,"q":"Which vaccine is used to prevent death from pneumonia in children?","o":["Measles vaccine","Rubella vaccine","Chickenpox vaccine","Influenza viral vaccine"],"a":0,"e":"Ans. is ''a'' i.e.,Measles vaccine [Ref Park 24th/e p. 182] Three vaccines have potential of reducing death from pneumonia :- Measles vaccine HIB vaccine (Haemophilus influenzee type B) Pneumococcal vaccine These vaccines work to reduce the incidence of bacterial pneumonia.","pyqMatches":[{"year":"2016","no":840,"q":"Which vaccine is used to prevent death from pneumonia in children?","o":["Measles vaccine","Rubella vaccine","Chickenpox vaccine","Influenza viral vaccine"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6074, 'PSM', 'Miscellaneous', 'Hard', 'Preventive_&_Social_Medicine', 686, '{"id":6074,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":686,"q":"Diagnosis of filariasis is confirmed most commonly?","o":["Clinical features","Detection of microfilariae","PCR","Seralogical test"],"a":1,"e":"Ans. is ''b'' i.e., Detection of microfilariae [Ref Essentials of clinical microbiology - 188] Detection of microfilariae (MO The most commonly used method for diagnosis of filariasis is detection of microfilariae in blood smear. The blood collection should be done at night because of nocturnal periodicity of microfilariae The microfilariae of W. bancrofti and B. malayi occuring in India display a nocturnal periodicity, i.e., they appear in large number at night and retreat from the blood stream during the day. This is a biological adaptation to the nocturnal biting habits of vector mosquitoes. The maximum density of microfilariae in blood is reported between 10 pm and 2 am. When the sleeping habits of the host are altered, a reversal in periodicity has been observed. Thick film is most commonly used method for detection of microfilariae. Concentration technique by membrane filter concentration (MFC) method is the most sensitive method which can detect low density of microfilariae in blood.","pyqMatches":[{"year":"2016","no":837,"q":"Diagnosis of filariasis is confirmed most commonly?","o":["Clinical features","Detection of microfilariae","PCR","Seralogical test"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6075, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 687, '{"id":6075,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":687,"q":"Maximum spread of malaria occurs in which month?","o":["March-April","January-February","April-May","September - October"],"a":3,"e":"Ans. is ''d'' i.e., September - October [Ref Park 24th/e p. 272-276] Malaria is a protozoal disease caused by infection with parasite of genus plasmodium and transmitted to man by certain species of infected female Anopheline mosquito. Definitive host - Mosquito (sexual life cycle). Intermediate host Man (Asexual cycle). Season In India maximum prevalence is from July to November. Reservoir - With possible exception of chimpanzees in tropical Africa, which may carry the infection with P.malariae, no other animal reservoir is known to exist. Man harbouring sexual forms (gametocytes) is the only reservoir. Extrinsic incubation period (in mosquito) 10 to 20 days. It is the period of time required for the development of parasite from gametocyte to sporozoite stage (infective stage to man) in the body of mosquito.","pyqMatches":[{"year":"2016","no":838,"q":"Maximum spread of malaria occurs in which month?","o":["March-April","January-February","April-May","September - October"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6076, 'PSM', 'Immunization', 'Moderate', 'Preventive_&_Social_Medicine', 688, '{"id":6076,"subject":"PSM","chapter":"Immunization","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":688,"q":"Not true about diphtheria vaccine?","o":["Can be given as pentavalent vaccine","For infant DPT is the vaccine of choice","First dose is given at 6 weeks of age","all of these"],"a":3,"e":"Ans. is ''D All of these, [Ref Park 24thie p. 172] Diphtheria vaccine is a toxoid. It is given as trivalent vaccine DPT - Preparation of choice for immunization of infant First dose is given at 6 weeks of age Pentavalent vaccine provides protection to a child from 5 life threatening disease-diphtheria, pertussis, tetanus, hepatitis B and haemophilus influenza type b (Hib). Giving pentavalent vaccine reduces the number of pricks to a child. When used, it replaces Hepatitis B and DPT primary vaccination schedule at 6, 10 and 14 weeks in the immunization programme, except that the birth dose of hepatitis B and booster doses of DPT are continued.","pyqMatches":[{"year":"2016","no":839,"q":"Not true about diphtheria vaccine?","o":["Can be given as pentavalent vaccine","For infant DPT is the vaccine of choice","First dose is given at 6 weeks of age","all of these"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6077, 'PSM', 'Miscellaneous', 'Hard', 'Preventive_&_Social_Medicine', 689, '{"id":6077,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":689,"q":"For diagnosis of TB, Sputum microscopy has ?","o":["High sensitivity & high specificity","High sensitivity & low specificity","Low sensitivity & high specificity","Low sensitivity & low specificity"],"a":3,"e":"Ans. is ''d'' i.e.,Low sensitivity & low specificity Most rapid method of diagnosis for TB Sputum microscopy. But, sputum microscopy has low sensitivity and specificity. Most reliable method for diagnosis of TB -> Culture of tubercular bacilli.","pyqMatches":[{"year":"2016","no":828,"q":"For diagnosis of TB, Sputum microscopy has ?","o":["High sensitivity & high specificity","High sensitivity & low specificity","Low sensitivity & high specificity","Low sensitivity & low specificity"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6078, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 690, '{"id":6078,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":690,"q":"Varicella zoster virus infection is more likely to occur in which of the following month?","o":["March","August","October","November"],"a":0,"e":"Ans. is ''a'' i.e., March [Ref: CECIL Vol. 1, p.1840] \"Varicella occurs most commonly during the late winter and spring months, the peak being about in March\"","pyqMatches":[{"year":"2016","no":829,"q":"Varicella zoster virus infection is more likely to occur in which of the following month?","o":["March","August","October","November"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6079, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 691, '{"id":6079,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":691,"q":"Most common influenza virus causing disease?","o":["Type A","Type B","Type C","Type D"],"a":0,"e":"Ans. is ''a'' i.e., Type A [Ref Park 24th/e p. 163-166] There are three viral subtypes : Type A (causes all pandemics and most epidemics); type B; and type C (not circulating currently). Currently the influenza viruses circulating in the world are : H, N, of type A (causes swine flu); H2N2 of type A; H3N2 of type A ; H5N, of type A (causes birdflu or avian influenza); 117 N9of type A (caused epidemic of avian influenza in China in 2013); and type B. Influenza shows cyclic trend with epidemic occuring every 2-3 years in case of influenza - A and every 4-7 years in case of influenza-B. Pandemics are caused by only influenza - A every 10-15 years. Influenza affects all ages and both sexes. Source of infection of influenza is a clinical case or subclinical case. Major reservoir of influenza virus exists in animal and birds.","pyqMatches":[{"year":"2016","no":830,"q":"Most common influenza virus causing disease?","o":["Type A","Type B","Type C","Type D"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6080, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 692, '{"id":6080,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":692,"q":"Minimum accepted interval between two doses of DPT vaccine?","o":["2 weeks","4 weeks","6 weeks","8 weeks"],"a":1,"e":"Ans. is ''b'' i.e., 4 weeks [Ref Park 24th/e p. 172] Total three doses are given in primarly immunization with an interval of 4 weeks between three doses. First booster is given at 16-24 months with second booster at 5-6 years. DPT, → 6 weeks of age DPT, → 10 weeks of age DPT, → 14 weeks of age DPTim,, → 16-24 months of age ter DPTB → 5 years of age","pyqMatches":[{"year":"2016","no":833,"q":"Minimum accepted interval between two doses of DPT vaccine?","o":["2 weeks","4 weeks","6 weeks","8 weeks"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6081, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 693, '{"id":6081,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":693,"q":"Mammalian reservoir for R. prowazekii ?","o":["Rodents","Dog","Cattle","Humans"],"a":3,"e":"Ans. is ''d'' i.e., Humans [Ref Park 24th/e p. 316, 319] Disease Agent Insect vector Mammalian reservoir Typhus group a) Epidemic typhus b) Murine typhus (Endemic typhus) c) Scrub typhus R. prowazekii R. typhi R. Tsutsugamushi Louse Flea Mite Humans Rodents Rodents","pyqMatches":[{"year":"2016","no":831,"q":"Mammalian reservoir for R. prowazekii ?","o":["Rodents","Dog","Cattle","Humans"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6082, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 694, '{"id":6082,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":694,"q":"''Secrete of national health lies in the homes of people'' statement by ?","o":["Indira Gandhi","Abhraham lincon","Bhore","Florence Nightingale"],"a":3,"e":"Ans. is ''d'' i.e., Florence Nightingale [Ref Housing and planning review p. 35] Florence Nighingale pointed out nearly a hundrade years ago, \"the secret of national health lies in the homes of people\".","pyqMatches":[{"year":"2012","no":766,"q":"''Secrete of national health lies in the homes of people'' statement by ?","o":["Indira Gandhi","Abhraham lincon","Bhore","Florence Nightingale"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6083, 'PSM', 'Environment & Occupational Health', 'Easy', 'Preventive_&_Social_Medicine', 695, '{"id":6083,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":695,"q":"Which occupational exposure may cause sterility in females ?","o":["Lead","Carbon monoxide","Mercury","Agricultural insecticides"],"a":3,"e":"Ans. is ''d'' i.e.,Agricultural insecticides [Ref Handbook of pesticide toxicology p. 787 Pesticides exposure can cause -","pyqMatches":[{"year":"2012","no":886,"q":"Which occupational exposure may cause sterility in females ?","o":["Lead","Carbon monoxide","Mercury","Agricultural insecticides"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6084, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 696, '{"id":6084,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":696,"q":"Work sampling ?","o":["Sampling done for individual work","Assessment of time spent by workers in work","Done in very short period","None"],"a":1,"e":"Ans. is ''b'' i.e., Assessment of time spent by workers in work Work sampling is a technique used to investigate the proportion of total time devoted to the various activities that constitute a job or work situation.","pyqMatches":[{"year":"2012","no":769,"q":"Work sampling ?","o":["Sampling done for individual work","Assessment of time spent by workers in work","Done in very short period","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6085, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 697, '{"id":6085,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":697,"q":"School health checkup comes under -","o":["Disrict hospital","PHC","CHC","School health committee"],"a":3,"e":"Ans. is ''d'' i.e., School health committee [Ref Park 22\"d/e p. 534, 535] The school health committee (1961) in India recommended medical examination of children at the time of entry and thereafter every 4 years.","pyqMatches":[{"year":"2012","no":771,"q":"School health checkup comes under","o":["Disrict hospital","PHC","CHC","School health committee"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6086, 'PSM', 'Environment & Occupational Health', 'Moderate', 'Preventive_&_Social_Medicine', 698, '{"id":6086,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":698,"q":"All are occupational cancers except ?","o":["Lung","Bladder","Breast","Liver"],"a":2,"e":"Ans. is ''c'' i.e.,Breast Asbestos → Mesotheliom a Arsenic → Skin, Lung, Liver Benzene → Leukemia Benzidine → Urinary bladder Berylium → Lung Cadmium → Lung Chromium → Nasal Sinus, Lung","pyqMatches":[{"year":"2012","no":885,"q":"All are occupational cancers except ?","o":["Lung","Bladder","Breast","Liver"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6087, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 699, '{"id":6087,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":699,"q":"M/C Heavy Metal poisoning in The World?","o":["Lead","Arsenic","Mercury","Cadmium"],"a":0,"e":"Ans. is ''a'' i.e.,Lead [Ref Park 22\"''Ile p. 752] More industrial workers are exposed to lead than any other toxic metal.","pyqMatches":[{"year":"2012","no":884,"q":"M/C Heavy Metal poisoning in The World?","o":["Lead","Arsenic","Mercury","Cadmium"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6088, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 700, '{"id":6088,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":700,"q":"Organized group of people with social relationship?","o":["Community","Association","Society","None"],"a":2,"e":"Ans. is ''c'' i.e. Society [Ref Park 22''/e p. 622] A society is a body of individuals of species, generally seen as a community or group, that is outlined by the bounds of functional interdependence, comprising also possible characters or conditions such as cultural identity, social solidarity or eusociality. Human societies are characterized by patterns of relationships between individuals that share a distinctive culture or institution. The importance of society lies in the fact that it controls and regulates the behaviour of the individual both by law and customs.","pyqMatches":[{"year":"2012","no":881,"q":"Organized group of people with social relationship?","o":["Community","Association","Society","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6089, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 701, '{"id":6089,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":701,"q":"DALE is replaced by ?","o":["DALY","HALE","OALY","None"],"a":1,"e":"Ans. is ''b'' i.e., HALE [Ref Park 20th/e p. 24] HALE (Health - Adjusted life expectancy) :- The name of the indicator used to measure healthy life expectancy has been changed from disability adjusted life expectancy (DALE) to health adjusted life expectancy (HALE). HALE is based on the life expectancy at birth but includes and adjustment for time spent in poor health. It is most easily understood as the equivalent number of years in full health that a newborn can expect to live based on current rates of ill health and mortality.","pyqMatches":[{"year":"2012","no":775,"q":"DALE is replaced by ?","o":["DALY","HALE","OALY","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6090, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 702, '{"id":6090,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":702,"q":"Social psychology is ?","o":["Human relationships & behaviour","Psychology of individuals in society","Cultural history of man","None"],"a":1,"e":"Ans. is ''b'' i.e.,Psychology of individuals in society [Ref: Park 22\"/e p. 622] Study of human relationships and human behaviour → Sociology Psychology of individuals living in human society → Social psychology Study of physical, social and cultural history of man → Anthropology","pyqMatches":[{"year":"2012","no":878,"q":"Social psychology is ?","o":["Human relationships & behaviour","Psychology of individuals in society","Cultural history of man","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6091, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 703, '{"id":6091,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":703,"q":"Best study for definitive cause of disease ?","o":["Case-control","Cohort","Ecological","Cross-sectional"],"a":1,"e":"Ans. is ''b'' i.e., Cohort Amongst the given options Cohort study is best to test the association between risk factor and disease. Here are the different epidemiological studies with decreasing order of accuracy to test the association between risk factor and disease :- Systematic review and meta-analysis --> Overall most reliable Randomized controlled trials (controlled clinical trails) --> Most reliable individual study. Retrospective (Non-concurrent/historic) Cohort study. Prospective (concurrent) Cohort study. Case control study Cross-sectional study Ecological study","pyqMatches":[{"year":"2012","no":780,"q":"Best study for definitive cause of disease ?","o":["Case-control","Cohort","Ecological","Cross-sectional"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6092, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 704, '{"id":6092,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":704,"q":"Results of any study are better defined in ?","o":["Cost effectiveness","Cost benefit","Both are same","None"],"a":0,"e":"Ans. is ''a'' i.e., Cost effectiveness [Ref. Park 22\"dle p. 814] The study results can be evaluated by cost-benefit analysis and cost-effectiveness analysis. In cost-benefit analysis all costs and benefits are evaluated in terms of money, i.e. economic benefits of the programme/ study are compared with the cost of programme. The main drawback with this technique is that the benefits in the health field canot always be expressed in monetary term. For example birth or death prevented, or illness avoided etc. Hence the scope of applying this method is rather vague. Cost-effective analysis is more promising tool for application in the health field. It evaluates how best to spend a given amount of money to achieve specific goals, i.e. benefits are expressed in terms of results achieved, e.g. number of lives saved, or the number of days free from disease.","pyqMatches":[{"year":"2012","no":782,"q":"Results of any study are better defined in ?","o":["Cost effectiveness","Cost benefit","Both are same","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6093, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 705, '{"id":6093,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":705,"q":"Source of environmental radiation are all except?","o":["CO","Radium","Uranium","Radon"],"a":0,"e":"Ans. is ''a'' i.e., CO [Ref Park 22''/e p. 690] Environmental ratiation are of two types ?","pyqMatches":[{"year":"2012","no":876,"q":"Source of environmental radiation are all except?","o":["CO","Radium","Uranium","Radon"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6094, 'PSM', 'Communicable Diseases', 'Easy', 'Preventive_&_Social_Medicine', 706, '{"id":6094,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":706,"q":"Propagative cycle is seen in ?","o":["Plague","Filaria","Malaria","All"],"a":0,"e":"Ans. is ''a'' i.e., Plague [Ref Park 22\"/e p. 94] Propagative → Plague bacilli in rat fleas Cyclo-developmental → Micorfilaria in mosquito. Cyclo-propagative → Malarial parasite in mosquito.","pyqMatches":[{"year":"2012","no":793,"q":"Propagative cycle is seen in ?","o":["Plague","Filaria","Malaria","All"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6095, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 707, '{"id":6095,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":707,"q":"Fenthion is ?","o":["Space spray","Residual spray","Stomach poison","Fumgant"],"a":0,"e":"Ans. is ''a'' i.e., Space spray [Ref Park 22\"d le p. 727] Residual sprapy In residual spray, spraying of houses with residual insectisides is done. Residual insectisides remains active over extended periods i.e., they have residual action even after the time of spray. Commonly used residual insectisides are → Malathion, DDT, Lindane, propoxure (OMS-33) Space spray Space sprays are those where the insecticidal formation is sprayed into the atmosphere in the form of a mist or fog to kill insect. Action is short lived and temporary since there is no. residual action. The most commonly used space spray insecticide is Pyrethrum. Now residual insectisides are also being used as residual spray by new equipment for ultra-low volume (ULV) space spraying. Melathion and fenthion are used for this purpose.","pyqMatches":[{"year":"2012","no":872,"q":"Fenthion is ?","o":["Space spray","Residual spray","Stomach poison","Fumgant"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6096, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 708, '{"id":6096,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":708,"q":"It waste contain toxic substances, organic load is measured by ?","o":["Biological oxygen demand","Chemical oxygen demand","Suspended solid","None"],"a":1,"e":"Ans. is ''b'' i.e., Chemical oxygen demand [Ref Park 22\"d/e p. 708] \" The strength of sewage is expressed in terms of :","pyqMatches":[{"year":"2012","no":871,"q":"It waste contain toxic substances, organic load is measured by ?","o":["Biological oxygen demand","Chemical oxygen demand","Suspended solid","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6097, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 709, '{"id":6097,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":709,"q":"Argemain oil contamination of mustard oil can be detected by ?","o":["Phosphatase test","Nitric acid test","Coliform cunel","Methylene blue test"],"a":1,"e":"Ans. is ''b'' i.e., Nitric acid test [Ref. Park 22\"d/e p. 610] Detection of Argemone oil :","pyqMatches":[{"year":"2012","no":868,"q":"Argemain oil contamination of mustard oil can be detected by ?","o":["Phosphatase test","Nitric acid test","Coliform cunel","Methylene blue test"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6098, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 710, '{"id":6098,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":710,"q":"Avidin has affinity for ?","o":["Folic acid","Thiamine","Biotin","Riboflavin"],"a":2,"e":"Ans. is ''c'' i.e., Biotin [Ref. Harper 29iVe p. 539] People who eat abnormally large amount of uncooked egg white may have biotin deficiency because it contains avidin, a protein that binds biotin and prevents its absorption","pyqMatches":[{"year":"2012","no":867,"q":"Avidin has affinity for ?","o":["Folic acid","Thiamine","Biotin","Riboflavin"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6099, 'PSM', 'Nutrition', 'Easy', 'Preventive_&_Social_Medicine', 711, '{"id":6099,"subject":"PSM","chapter":"Nutrition","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":711,"q":"Daly requirment of vitamin K ?","o":["3 mg/kg","0.3 mg/kg","0.03 mg/kg","1 mg/kg"],"a":2,"e":"Ans. is ''c'' i.e., 0.03 mg/kg [Ref. Park 22\"d/e p. 572] Vitamin A→ 600 mcg retinol Vitamin B7 (Thiamine)--> 0.5 mg per 1000 Kcal of energy intake Vitamin B, (Riboflavin) → 0.6 mg per 1000 Kcal of energy intake Vitamin B, (Niacin) → 6.0 mg per 1000 Kcal of energy intake Vitamin 135 (Pantothenic Acid) → 10 mg Vitamin B6 (Pyridoxine) →2 mg Vitamin B, (Folic Acid) →200 mcg Vitamin B12(Cobalamin) →1 mcg Vitamin D 100 IU (2.5 mcg calciferol) Vitamin E (Tocopherol) ⇒ → 0.8 mg per gm of essential fatty acids Vitamin K → 0.03 mg per kg","pyqMatches":[{"year":"2012","no":866,"q":"Daly requirment of vitamin K ?","o":["3 mg/kg","0.3 mg/kg","0.03 mg/kg","1 mg/kg"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6100, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 712, '{"id":6100,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":712,"q":"Maximum linolenic acid is present in ?","o":["Coconut oil","Soyabean oil","Groundnut oil","S afflower oil"],"a":3,"e":"Ans. is ''d'' i.e., Safflower oil [Ref Park 22\"d /e p. 566] The richest source of linoleic acid is safflower oil. Sources of linoleic acid in decreasing order are safflower oil > cornoil > Sunflower oil > Soyabean oil > Sesame oil > ground nut oil.","pyqMatches":[{"year":"2012","no":863,"q":"Maximum linolenic acid is present in ?","o":["Coconut oil","Soyabean oil","Groundnut oil","S afflower oil"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6101, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 713, '{"id":6101,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":713,"q":"Bitot''s spot prevalence as public health problem -","o":["> 1%","> 2%","> 0.5%","None"],"a":2,"e":"Ans. is i.e., c. > 0.5% [Ref Park 22\"d/e p. 571] Night blindness Bitot''s spots > 0.5% Corneal xerosis/corneal ulceration/keratomalacia > 0.01% Corneal ulcer > 0.05% Serum retinol (less than 10 mcg/dl) > 5%","pyqMatches":[{"year":"2012","no":860,"q":"Bitot''s spot prevalence as public health problem","o":["> 1%","> 2%","> 0.5%","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6102, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 714, '{"id":6102,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":714,"q":"Blood screening is not done for ?","o":["HIV","HBV","EBV","HCV"],"a":2,"e":"Ans. is ''c'' i.e.,EBV Screening recommended in all countries Selective screening in some countries HIV Malaria HBV HTLV HCV CMV Syphilis Chagas disease","pyqMatches":[{"year":"2012","no":800,"q":"Blood screening is not done for ?","o":["HIV","HBV","EBV","HCV"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6103, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 715, '{"id":6103,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":715,"q":"Most common method of sterilisation practised in India ?","o":["Female sterilization","Male sterilization","Both","None"],"a":0,"e":"Ans. is ''a'' i.e., Female sterilization [Ref Park 22\"/e p. 454] During 2010-2011 Total sterilization - 5.0 million Female sterilization (tubectomy) 4.78 million Male sterilization (vasectomy) 0. 219 million","pyqMatches":[{"year":"2012","no":844,"q":"Most common method of sterilisation practised in India ?","o":["Female sterilization","Male sterilization","Both","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6104, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 716, '{"id":6104,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":716,"q":"Amount of diphtheria toxoid in DT is ?","o":["5 Lf","10 Lf","15 Lf","25 Lf"],"a":3,"e":"Ans. is ''d'' i.e., 25 Lf [Ref. Park 22\"dle p. 153] Oridinary (Pediatric) DPT/DT vaccines contain 25 Lf of diphtheria toxin. For immunizing adults and older children (>12 years), dT is used which contains 2 Lf of diphtheria toxin. DPT vaccine It contains components for immunization against three diseases, i.e., toxoid of diphtheria and tetanus, and killed B. pertussis. Pertussis component enhances the potency of diphtheria toxoid. Aluminium salts (hydroxide or phosphate) are used as adjuvant to increase immunogenicity. Thiomersal is used as preservative. Usual storage temperature for DPT vaccine in cold chain is +2 to +8°C, stored in refrigerator. It should never be stored in deep freezer (should not be frozen) and if it gets frozen accidently, vaccine should be discarded. Exposure to sunlight should be avoided. Open vials which have not been fully used should be discarded at the end of session. Vaccine is given by intramuscular route in the middle third of anterolateral aspect of thigh. Optimum age to start DPT vaccination is 6 weeks after birth. Total three doses are given in primarly immunization with an interval of 4 weeks between three doses. First booster is given at 16-24 months with second booster at 5-6 years.","pyqMatches":[{"year":"2012","no":810,"q":"Amount of diphtheria toxoid in DT is ?","o":["5 Lf","10 Lf","15 Lf","25 Lf"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6105, 'PSM', 'Maternal & Child Health', 'Easy', 'Preventive_&_Social_Medicine', 717, '{"id":6105,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":717,"q":"Highest funding for reproductive health is by -","o":["UNFPA","UNICEF","ILO","None"],"a":0,"e":"Ans. is ''a'' i.e., UNFPA [Ref Maternal health fifth report session 2007-2008] UNFPA works with a range of partners to promote reproductive health in India. It pools a significant proportion of its country programme resources in the reproductive and child health II (RCH II) programme, aimed at reducing maternal mortality and child mortality, as well as provision of range of contraceptive services. UNFPA also delivers technical assistance for effective implementation of RCH-II programme at the national as well as state level particularly in the state of Rajasthan, M.P. Maharashtra, Orrisa and Bihar.","pyqMatches":[{"year":"2012","no":843,"q":"Highest funding for reproductive health is by","o":["UNFPA","UNICEF","ILO","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6106, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 718, '{"id":6106,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":718,"q":"1955 Hepatitis outbreak in Delhi ?","o":["A","B","C","E"],"a":3,"e":"Ans. is ''d'' i.e., E [Ref Internet] Hepatitis E was first documented in New Delhi in 1955 when 29000 cases of icteric hepatitis occured.","pyqMatches":[{"year":"2012","no":813,"q":"1955 Hepatitis outbreak in Delhi ?","o":["A","B","C","E"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6107, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 719, '{"id":6107,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":719,"q":"For Asian population B.M.I. true is ?","o":["Different from international values to define obesity","Increased morbidity at lower values","Increased morbidity at higher values","Obesity is > 25 kg/m2"],"a":1,"e":"Ans. is ''b'' i.e., Increased morbidity at lower values [Ref WHO expert consultation] A WHO expert consulation addressed the debate about interpretation of recommended body-mass index (BMI) cut-off points for determining overweight and obesity in Asian populations, and considered whether population specific cut-off points for BMI are necessary. They reviewed scientific evidence that suggests that Asian populations have different associations between BMI, percentage of body fat and health risks than do European population. The consultation concluded that the proportion of Asian population with a high risk of type 2 diabetes and cardiovascular disease is substantial at BMI, lower than existing WHO cut-off points for overweight ( 25mg/kg2). And Asians generally have a higher percentage of body fat in comparison to white people of that same age, sex and BMI. However, available data do not necessarily indicate a clear BMI cut- off part for all Asians for overweight or obesity. The cut-off point for observed risk varies from 22 kg/m2 to 25 kg/m2 in different Asian population, for high risk it varies from 26 kg/m2 to 31 kg/m2. For many Asian populations, additiond trigger points for public health action were identified as -","pyqMatches":[{"year":"2012","no":837,"q":"For Asian population B.M.I. true is ?","o":["Different from international values to define obesity","Increased morbidity at lower values","Increased morbidity at higher values","Obesity is > 25 kg/m2"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6108, 'PSM', 'Communicable Diseases', 'Easy', 'Preventive_&_Social_Medicine', 720, '{"id":6108,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":720,"q":"Which is the main vector of Dengue ?","o":["A. aegypti","A schleri","Culex","Anopheles"],"a":0,"e":"Ans. is ''a'' i.e., A. aegypti [Ref Park 22\"/e p. 225] Dengue fever is caused by arboviruses (at least 4 serotypes have been recognized) It is transmitted by Aedes (Aedes aegypti is the main vector). The reservoir of infection is both man and mosquito. The transmission cycle is Man-mosquito-man Dengue fever occurs both epidemically and endemically. Epidemics starts in rainy season and are usually explosive. Aedes mosquito becomes infective by feeding on a patient from the day before onset to the 5th day of illness","pyqMatches":[{"year":"2012","no":820,"q":"Which is the main vector of Dengue ?","o":["A. aegypti","A schleri","Culex","Anopheles"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6109, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 721, '{"id":6109,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":721,"q":"Nicotine responsible for oral cancer is ?","o":["10%","40%","90%","60%"],"a":2,"e":"Ans. is ''c'' i.e., 90% [Ref Park 22\"/e p. 358] Approximately 90% of oral cancers in South East Asia are linked to tobacco chewing and tobacco smoking\" -- Park","pyqMatches":[],"pyqYears":[]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6110, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 722, '{"id":6110,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":722,"q":"Second most common STD after gonococcus ?","o":["Chylamydia","HSV","HIV","Syphilis"],"a":0,"e":"Ans. is ''a'' i.e., Chlamydia [Ref Park 2151/e p. 304] Five classical STDs are syphilis (T. pallidum), gonorrhoea (N. gonorrhoeae), chanchroid (H. ducreyi), lymphogranuloma venerum (chlamydia trachomatis), and donovanosis (calymmatobacterium granulomatosis). Most common STD in India is herpes genitalis (20%) followed by chancroid (11%), viral warts/HPV (11%), syphilis (11%) and gonorrhoea (9%). Overall (in world) most common STD is chlamydia followed by gonorrhoea.","pyqMatches":[{"year":"2012","no":827,"q":"Second most common STD after gonococcus ?","o":["Chylamydia","HSV","HIV","Syphilis"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6111, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 723, '{"id":6111,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":723,"q":"Which of the following studies have given coronary risk factor ?","o":["Framingham","Stanford study","North Kerala","MONICA"],"a":0,"e":"Ans. is ''a'' i.e.,Framingham [Ref Park 22\"die p. 342] Option a, b & c all three are risk factor intervention trials. However, option a is the best answer :? \"Since 1951, one of the best known large prospective studies, the Framingham study, has played a major role in establishing the nature of CHD risk factors and their relative importance. Standford-three community study .→ To determine whether community health education can reduce the risk of cardiovascular disease, this study was undertaken in 1972. The North Kerelia Project: → This is a multiple risk factor intervention trial establish the nature of CHD risk factors and their relative importance. Largest prospective study which started since","pyqMatches":[{"year":"2012","no":834,"q":"Which of the following studies have given coronary risk factor ?","o":["Framingham","Stanford study","North Kerala","MONICA"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6112, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 724, '{"id":6112,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":724,"q":"Chandlers index for Hookworm, when it is health problem ?","o":["> 300","> 200","> 100","> 50"],"a":0,"e":"Ans. is ''a'' i.e., > 300 [Ref Park 21\"/e p. 221] Below 200 → Hookworm infection is not much of significance 200 - 250 → Potential danger 250 - 300 -- Minor public health problem Above 300 → Important public health problem","pyqMatches":[{"year":"2012","no":828,"q":"Chandlers index for Hookworm, when it is health problem ?","o":["> 300","> 200","> 100","> 50"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6113, 'PSM', 'Epidemiology', 'Moderate', 'Preventive_&_Social_Medicine', 725, '{"id":6113,"subject":"PSM","chapter":"Epidemiology","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":725,"q":"Which index of obesity does not include height?","o":["BMI","Ponderal''s index","Broca''s index","Corpulence index"],"a":3,"e":"Ans. is i.e., D. Corpulence index [Ref Park 22nd le p. 369, 370] Different indices use to determine obesity are i) Body mass index (Qetelet''s index) It is used internationally as reference standard for assessing the prevalence of obesity. It is dependent both on height and weight (has been explained earlier). ii) Ponderal index It is dependent both on height and weight. It is defined as height (cm) divided by cube root of weight (kg). iii) Broca indexà deal weight = Height (cms) - 100 iv) Corpulence indexà It is dependent only on weight (height independent. It should be 1.2.","pyqMatches":[{"year":"2012","no":833,"q":"Which index of obesity does not include height?","o":["BMI","Ponderal''s index","Broca''s index","Corpulence index"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6114, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 726, '{"id":6114,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":726,"q":"HIV post exposure prophylaxis should be started within?","o":["1-2 hrs","14 hrs","18 hrs","72 hrs"],"a":0,"e":"Ans. is ''a'' i.e., 1-2 hrs Anti-retroviral drug for post-exposure prophylaxis should be initiated as soon as possible after the exposure within the first few hours and no later than 72 hours. So, the best answer here is 1-2 hours (first few hours).","pyqMatches":[{"year":"2012","no":830,"q":"HIV post exposure prophylaxis should be started within?","o":["1-2 hrs","14 hrs","18 hrs","72 hrs"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6115, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 727, '{"id":6115,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":727,"q":"What should be the value of BMI to be considered as “Lethal” in men?","o":["12","18","13","14"],"a":2,"e":"Answer: C – 13 BMI Value of 13 is considered as “Lethal” in men. Body mass index (BMI) is an estimate of total body fat mass Simply an index of weight for height. Formula: Weight in kilograms divided by the square of height in meters. Body mass index = Weight (kg)/(Height)2 (m) Uses: Used to classify and define underweight, overweight & obesity in adults. Classification & Metrics: World Health organization categorized BMI values into: Classification BMI value Normal weight 18.5 to 24.9 kg/m2 Underweight <18.5 Pre-obesity (Pre-OB) 25 to 29.9 kg/m2 Obesity (OB) Class I obesity Class II obesity > 30 kg/m2 30.0 - 34.9 kg/m2 Class III obesity (Morbid form) 35.0 - 39.9 kg/m2 More than 40 kg/m2 BMI value considered lethal for Men is 13 Females withstand and survive even at lower BMI rate up to 11.","pyqMatches":[{"year":"2018","no":11,"q":"What should be the value of BMI to be considered as “Lethal” in men?","o":["12","18","13","14"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6116, 'PSM', 'Epidemiology', 'Moderate', 'Preventive_&_Social_Medicine', 728, '{"id":6116,"subject":"PSM","chapter":"Epidemiology","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":728,"q":"Incidence of a disease is 4 per 1000 of population with duration of 2 years. Calculate the prevalence?","o":["8/1000","4/1000","2/1000","6/1000"],"a":0,"e":"Ans. A. 8/1000 Prevalence = (Incidence Rate) x (Average Duration of Disease)","pyqMatches":[{"year":"2018","no":104,"q":"Incidence of a disease is 4 per 1000 of population with duration of 2 years. Calculate the prevalence?","o":["8/1000","4/1000","2/1000","6/1000"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6117, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 729, '{"id":6117,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":729,"q":"Cytotoxic and expired drug disposal is done by which method?","o":["Dumping","Autoclave","Landfill","Burning"],"a":2,"e":"Ans.C. Landfill Colour coding Type of Container Waste Category Treatment options Yellow Plastic Bags Human and animal wastes, Microbial and Biological wastes and soiled wastes (Cat 1,2,3 and 6) Incineration/ Deep Burial Red Disinfected container/ Plastic bags Microbiological and Biological wastes, Soiled wastes, Solid wastes (Cat 3,6,7) Autoclave/ Microwave/ Chemical Treatment) Blue/ White/ Transparent Plastic bag, Puncture proof container Waste sharps and solid waste ( Cat 4 &7) Autoclave/ Microwave/ Chemical Treatment Destruction and Shredding Discarded Black Plastic bag medicines, Cytotoxic drugs, Incineration ash and chemical waste (Cat 5,9 & 10) Disposal in secured land fills Green Plastic Container General waste such as office waste, food waste & garden waste Disposed in secured landfills","pyqMatches":[{"year":"2018","no":105,"q":"Cytotoxic and expired drug disposal is done by which method?","o":["Dumping","Autoclave","Landfill","Burning"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6118, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 730, '{"id":6118,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":730,"q":"For NRR to be 1 couple protection rate should be?","o":["50%","60%","55%","75%"],"a":1,"e":"Ans. B. 60% Couple Protection Rate (CPR) It is an indicator of the prevalence of contraceptive practice in the community Definition: the percentage of eligible couples effectively protected against childbirth by one or the other approved methods of family planning Sterilization IUD Condom OCP’s NRR = 1 can be achieved only if the CPR > 60%","pyqMatches":[{"year":"2018","no":106,"q":"For NRR to be 1 couple protection rate should be?","o":["50%","60%","55%","75%"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6119, 'PSM', 'Communicable Diseases', 'Easy', 'Preventive_&_Social_Medicine', 731, '{"id":6119,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":731,"q":"New RNTCP software online to monitor TB control programme is-","o":["NIKSHAY","NICHAY","E- DOTS","NIRBHAI"],"a":0,"e":"Ans. A.NIKSHAY To keep a track of the TB patients across the country, the Government of India has introduced a system called NIKSHAY. The word is combination of two Hindi words NI and KSHAY meaning eradication of tuberculosis. NIKSHAY (www.nikshay.gov.in) is a web enabled application, which facilitates monitoring of universal access to TB patients data by all concerned. The system has been developed jointly by the Central TB Division of the Ministry of Health and Family Welfare and National Informatics Centre (NIC) and it was launched by the Government of India in June 2012 with issue of required administrative directions from Central TB Division for use of NIKSHAY","pyqMatches":[{"year":"2018","no":107,"q":"New RNTCP software online to monitor TB control programme is","o":["NIKSHAY","NICHAY","E- DOTS","NIRBHAI"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6120, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 732, '{"id":6120,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":732,"q":"Study unit of ecological study is","o":["Population","Patient","Community","Case"],"a":0,"e":"Ans. A.Population In ecological studies the unit of observation is the population or community. Disease rates and exposures are measured in each of a series of populations and their relation is examined. Often the information about disease and exposure is abstracted from published statistics.","pyqMatches":[{"year":"2018","no":108,"q":"Study unit of ecological study is","o":["Population","Patient","Community","Case"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6121, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 733, '{"id":6121,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":733,"q":"In a screening test for DM out of 1000 population, 90 were positive. Then the gold standard test was done in which 100 were positive. Calculate the sensitivity?","o":["90/100","100/110","80/100","100/100"],"a":0,"e":"Ans. A. 90/100 So, True positive (a)= 90 False negative(c)=10 Sensitivity = a/(a+c)=90/100","pyqMatches":[{"year":"2018","no":109,"q":"In a screening test for DM out of 1000 population, 90 were positive. Then the gold standard test was done in which 100 were positive. Calculate the sensitivity?","o":["90/100","100/110","80/100","100/100"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6122, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 734, '{"id":6122,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":734,"q":"What is the mass chemoprophylaxis for meningococcal meningitis ?","o":["Rifampicin","Chloramphenicol","Tetracycline","Penicillin"],"a":0,"e":"Ans. A.Rifampicin Recommended Chemoprophylaxis for High-Risk Close Contacts: Age Dose Duration Cautions RIFAMPICIN: <1 month 5 mg/kg Oral every 12 hrs 2 days >1 month 10 mg/kg Oral every 12 hrs 2 day Not recommended for use in pregnancy CEFTRIAXONE: <15 years 125mg IM single dose >15 years 250 mg IM single dose CIPROFLOXACIN >18 years 500 mg Oral single dose Not recommended for use in pregnancy","pyqMatches":[{"year":"2018","no":110,"q":"What is the mass chemoprophylaxis for meningococcal meningitis ?","o":["Rifampicin","Chloramphenicol","Tetracycline","Penicillin"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6123, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 735, '{"id":6123,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":735,"q":"Which among the following is an active form of chlorination?","o":["Hypochlorite ion","Hydrogen chloride","Hypochlorous acid","Chloride ion"],"a":2,"e":"Ans. C. Hypochlorous acid The disinfecting action of chlorine is predominantly due to hypochlorous acid. Hypochlorous acid is the most effective form of chlorine and it is almost 70-80 times more effective than hypochlorite ions.","pyqMatches":[{"year":"2018","no":111,"q":"Which among the following is an active form of chlorination?","o":["Hypochlorite ion","Hydrogen chloride","Hypochlorous acid","Chloride ion"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6124, 'PSM', 'Miscellaneous', 'Moderate', 'Preventive_&_Social_Medicine', 736, '{"id":6124,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":736,"q":"Kala-Azar is found in all endemic areas except.","o":["West Bengal","UP","Bihar","Assam"],"a":3,"e":"Ans. D. Assam UP , West Bengal Bihar And Jharkhand are the endemic states of kala Azar","pyqMatches":[{"year":"2018","no":112,"q":"Kala-Azar is found in all endemic areas except.","o":["West Bengal","UP","Bihar","Assam"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6125, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 737, '{"id":6125,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":737,"q":"Risk among exposed to risk among non exposed is defined to be –","o":["Relative risk","Odds ratio","Attributable risk","None of the above"],"a":0,"e":"Ans.A. Relative risk RR=P event when exposed P event when not exposed In statistic and epidemiology , relative risk or risk ratio (RR) is the ratio of the probability of an event occurring (for example, developing a disease, being injured) in an exposed group to the probability of the event occurring in a comparison, non-exposed group. RR = 1 means that exposure does not affect the outcome RR < 1 means that the risk of the outcome is decreased by the exposure RR > 1 means that the risk of the outcome is increased by the exposure","pyqMatches":[{"year":"2018","no":113,"q":"Risk among exposed to risk among non exposed is defined to be –","o":["Relative risk","Odds ratio","Attributable risk","None of the above"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6126, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 738, '{"id":6126,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":738,"q":"Pasteurization is done at-","o":["73 oC For 20 min","63 oC For 30 min","72 oC For 30 seconds","63oC For 30 seconds"],"a":1,"e":"Ans.B. 63 oC For 30 min Pasteurization of milk, widely practiced in several countries, notably the United States, requires temperatures of about 63° C (145° F) maintained for 30 minutes or, alternatively, heating to a higher temperature, 72° C (162° F), and holding for 15 seconds (and yet higher temperatures for shorter periods of time).","pyqMatches":[{"year":"2018","no":114,"q":"Pasteurization is done at","o":["73 oC For 20 min","63 oC For 30 min","72 oC For 30 seconds","63oC For 30 seconds"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6127, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 739, '{"id":6127,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":739,"q":"Ideal time gap between 2 live vaccination -","o":["2 weeks","4 weeks","8 weeks","12 weeks"],"a":1,"e":"Ans.B.4 weeks If live parenteral (injected) vaccines (MMR, MMRV, varicella, zoster, and yellow fever) and live intranasal influenza vaccine (LAIV) are not administered at the same visit, they should be separated by at least 4 weeks.","pyqMatches":[{"year":"2018","no":115,"q":"Ideal time gap between 2 live vaccination","o":["2 weeks","4 weeks","8 weeks","12 weeks"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6128, 'PSM', 'Concept of Health & Disease', 'Hard', 'Preventive_&_Social_Medicine', 740, '{"id":6128,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":740,"q":"Susceptible person developed disease within range of IP after coming in contact with primary case -","o":["Secondary attack rate","Case fatality rate","Primary attack rate","Tertiary attack rate"],"a":0,"e":"Ans. A. Secondary attack rate Secondary Attack Rate (SAR) Number of exposed persons developing the disease within the range of the incubation period, following exposure to primary case.","pyqMatches":[{"year":"2018","no":116,"q":"Susceptible person developed disease within range of IP after coming in contact with primary case","o":["Secondary attack rate","Case fatality rate","Primary attack rate","Tertiary attack rate"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6129, 'PSM', 'Demography & Family Planning', 'Moderate', 'Preventive_&_Social_Medicine', 741, '{"id":6129,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":741,"q":"Out of 100 women who were offered ocp for contraception 10 women got pregnant when followed for 24 months. What is Pearl''s index?","o":["10","5","4","2"],"a":1,"e":"Ans. B. 5 Pearl-Index=Number of Pregnancies *12 *100 Number of Women * Number of Months Pearl Index=10x12x100/100x24= 5","pyqMatches":[{"year":"2018","no":117,"q":"Out of 100 women who were offered ocp for contraception 10 women got pregnant when followed for 24 months. What is Pearl''s index?","o":["10","5","4","2"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6130, 'PSM', 'Environment & Occupational Health', 'Moderate', 'Preventive_&_Social_Medicine', 742, '{"id":6130,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":742,"q":"Which of the following do not cause hardness of water ?","o":["Calcium carbonate","Calcium sulphate","Calcium bicarbonate","Magnesium bicarbonate"],"a":0,"e":"Ans. A.Calcium carbonate Temporary hardness is a type of water hardness caused by the presence of dissolved bicarbonate minerals (calcium bicarbonate and magnesium bicarbonate). Permanent hardness is caused by dissolved calcium sulfate (which is not removed by boiling).","pyqMatches":[{"year":"2018","no":118,"q":"Which of the following do not cause hardness of water ?","o":["Calcium carbonate","Calcium sulphate","Calcium bicarbonate","Magnesium bicarbonate"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6131, 'PSM', 'Concept of Health & Disease', 'Moderate', 'Preventive_&_Social_Medicine', 743, '{"id":6131,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":743,"q":"Which of the following is not an example of direct transmission in communicable diseases ?","o":["Transplacental (vertical)","Soil","Respiratory","STD"],"a":2,"e":"Ans. C. Respiratory The modes of transmission of infectious diseases can be classified as: Direct Transmission. Direct contact; Droplet infection; Contact with soil; Inoculation into skin or mucosa; Transplacental (vertical)transmission. Indirect Transmission. Vehicle-borne; Water; food/milk; Vector- borne. Mechanical; Biological. Airborne.","pyqMatches":[{"year":"2018","no":119,"q":"Which of the following is not an example of direct transmission in communicable diseases ?","o":["Transplacental (vertical)","Soil","Respiratory","STD"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6132, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 744, '{"id":6132,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":744,"q":"Which of the following statement is false about MR vaccination campaign launched by WHO?","o":["Children from 9 months to less than 15 vaccinated","Congenital rubella syndrome (CRS), responsible for irreversible birth defects","India has not yet launched this campaign","Will replace routine immunization for measles vaccine"],"a":2,"e":"Answer: C. India has not yet launched this campaign One of the world’s largest vaccination campaign against measles, a major childhood killer disease, and congenital rubella syndrome (CRS), responsible for irreversible birth defects. India, along with ten other WHO South East Asia Region member countries, have resolved to eliminate measles and control rubella/congenital rubella syndrome (CRS) by 2020 All children from 9 months to less than 15 years of age will be given a single shot of Measles-Rubella (MR) vaccination during the campaign Following the campaign, MR vaccine will become a part of routine immunization and will replace measles vaccine, currently given at 9- 12 months and 16-24 months of age of child. For those children who have already received such vaccination, the campaign dose would provide additional boosting to them.","pyqMatches":[{"year":"2017","no":275,"q":"Which of the following statement is false about MR vaccination campaign launched by WHO?","o":["Children from 9 months to less than 15 vaccinated","Congenital rubella syndrome (CRS), responsible for irreversible birth defects","India has not yet launched this campaign","Will replace routine immunization for measles vaccine"],"a":2,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":260,"q":"Which of the following statement is false about MR vaccination campaign launched by WHO?","o":["Children from 9 months to less than 15 vaccinated","Congenital rubella syndrome (CRS), responsible for irreversible birth defects","India has not yet launched this campaign","Will replace routine immunization for measles vaccine"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6133, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 745, '{"id":6133,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":745,"q":"Under RNTCP, DOTS provider gets how much honorarium after completion of treatment ?","o":["150 Rs","250 Rs","500 Rs","1000 Rs"],"a":1,"e":"Ans. is ''b i.e., 250 Rs [Ref www.pbnrhm.org] Honorarium to DOT provider for cure or completed TB patient treatment is 250 Rs per care.","pyqMatches":[{"year":"2015","no":928,"q":"Under RNTCP, DOTS provider gets how much honorarium after completion of treatment ?","o":["150 Rs","250 Rs","500 Rs","1000 Rs"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6134, 'PSM', 'Communicable Diseases', 'Easy', 'Preventive_&_Social_Medicine', 746, '{"id":6134,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":746,"q":"Black death","o":["Plague","Dengue","TB","Cholera"],"a":0,"e":"Answer-A. Plague White disease → AIDS Poverty disease → Cholera Hundred day cough: Pertussis (Whooping cough) 5 day fever: Trench fever 8\" day disease: Tetanus Black sickness: Kala azar Black death: Plague","pyqMatches":[{"year":"2012","no":918,"q":"Black death","o":["Plague","Dengue","TB","Cholera"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6135, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 747, '{"id":6135,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":747,"q":"Where will you put chemical liquid biomedical waste","o":["White","Yellow","Blue","Red"],"a":1,"e":"Ans. B yellow Chemical waste is categorized into the yellow category. the hazardous chemical and cytotoxic waste is a yellow category with a special sign of “CYTOTOXIC” waste. Another liquid waste as body secretions is categorized into the yellow category of biomedical waste guidelines, 2016 Park’s PSM 24th ed. Page no. 831","pyqMatches":[{"year":"2020","no":94,"q":"Where will you put chemical liquid biomedical waste","o":["White","Yellow","Blue","Red"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6136, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 748, '{"id":6136,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":748,"q":"Maximum work hours for a person including overtime under the factories act:","o":["48","50","60","100"],"a":2,"e":"Ans: C. 60 hours. Factories act permits work for 48 hours per week with 2 hours of overtime every day. making it approximately 60 hours of maximum work as per the factories act of India Park’s PSM 24th ed. Page no. 852","pyqMatches":[{"year":"2020","no":95,"q":"Maximum work hours for a person including overtime under the factories act:","o":["48","50","60","100"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6137, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 749, '{"id":6137,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":749,"q":"The vaccine to be given after disaster","o":["vaccination against typhoid","vaccination against cholera","vaccination against typhoid and cholera","vaccination against tetanus"],"a":3,"e":"Ans. D. vaccination against tetanus. The major concern for anyone exposed to unsanitary conditions is that they should be up to date with the tetanus-containing vaccine because if they are injured (as is common in disaster settings) the injury is likely to be contaminated. Routinely recommended vaccines are recommended for evacuees, just like they are for everyone else. Cholera and typhoid vaccine do not have any evidence for mass vaccination due to the low level of exposure and prevention Tetanus and HepB vaccine is required.","pyqMatches":[{"year":"2020","no":96,"q":"The vaccine to be given after disaster","o":["vaccination against typhoid","vaccination against cholera","vaccination against typhoid and cholera","vaccination against tetanus"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6138, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 750, '{"id":6138,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":750,"q":"What is the MONICA project?","o":["Multinational monitoring of trends and determinants in Cardiovascular Disease","Multinational of trends and determinants in cerebrovascular disease","Multinational monitoring of trends and determinants in diabetes","Multinational monitoring of trends and determinants in congenital heart disease"],"a":0,"e":"Ans: A. Multinational monitoring of trends and determinants in Cardiovascular Disease The WHO has completed a project known as MONICA \" (multinational monitoring of trends and determinants in cardiovascular diseases)\" to elucidate this issue. Forty-one centers in 26 countries were participating in this project, which was planned to continue for a 10 year period ending in 1994. Park’s PSM 24th ed. Page no. 385","pyqMatches":[{"year":"2020","no":97,"q":"What is the MONICA project?","o":["Multinational monitoring of trends and determinants in Cardiovascular Disease","Multinational of trends and determinants in cerebrovascular disease","Multinational monitoring of trends and determinants in diabetes","Multinational monitoring of trends and determinants in congenital heart disease"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6139, 'PSM', 'Communicable Diseases', 'Easy', 'Preventive_&_Social_Medicine', 751, '{"id":6139,"subject":"PSM","chapter":"Communicable Diseases","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":751,"q":"Extended sickness benefit for tuberculosis under the ESI Act is:","o":["91 days","1-year","2 years","4 years"],"a":2,"e":"Ans. C. 2 years EXTENDED SICKNESS BENEFIT: In addition to 91 days of sickness benefit insured persons suffering from certain long-term diseases are entitled to Extended Sickness Benefit as shown below, for a maximum period of two years. Extended Sickness Benefit with effect from 1.1.2000 is payable, in the case where the insured person has been in continuous employment for 2 years Tuberculosis Park’s PSM 24th ed. Page no. 854","pyqMatches":[{"year":"2020","no":98,"q":"Extended sickness benefit for tuberculosis under the ESI Act is:","o":["91 days","1-year","2 years","4 years"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6140, 'PSM', 'Immunization', 'Hard', 'Preventive_&_Social_Medicine', 752, '{"id":6140,"subject":"PSM","chapter":"Immunization","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":752,"q":"A person reports 4 hours after having a clean wound without laceration. He had taken TT 10 years before. the next step in management is:","o":["Full course Tetanus vaccine to be given","Full dose TT with TIG","Single-dose TT","No need for any vaccine"],"a":2,"e":"Ans. C. Single-dose TT A patient with wound less than 6 hours old if clean, non-penetrating and with negligible tissue damage if had a complete course of toxoid or a booster dose more than 10 years ago(category C) should be treated with Toxoid 1 dose. Park’s PSM 24th ed. Page no. 331","pyqMatches":[{"year":"2020","no":99,"q":"A person reports 4 hours after having a clean wound without laceration. He had taken TT 10 years before. the next step in management is:","o":["Full course Tetanus vaccine to be given","Full dose TT with TIG","Single-dose TT","No need for any vaccine"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6141, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 753, '{"id":6141,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":753,"q":"Recent Influenza Pandemic was due to:","o":["H1N1","H5N1","H7N7","H3N2"],"a":0,"e":"Ans. A. H1N1 H1N1 – swine flu – cause the major flu Pandemic (1918 and 2009) H5N1 – avian influenza. may cause sporadic outbreaks or epidemics. It is associated with high mortality.","pyqMatches":[{"year":"2020","no":100,"q":"Recent Influenza Pandemic was due to:","o":["H1N1","H5N1","H7N7","H3N2"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6142, 'PSM', 'Immunization', 'Easy', 'Preventive_&_Social_Medicine', 754, '{"id":6142,"subject":"PSM","chapter":"Immunization","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":754,"q":"Mission Indradhanush is for:","o":["Non-communicable diseases","Universal immunization","Family planning","Safe water and sanitation"],"a":1,"e":"Ans. B. Universal immunization The Ministry of Health & Family Welfare has launched \" Mission Indra Dhanush\", depicting seven colours of the rainbow in December 2014, to fully immunize more than 89 lakh children who are either unvaccinated or partially vaccinated; those that have not been covered during the rounds of routine immunization for various reasons. They will be fully immunized against seven life-threatening vaccine- preventable diseases which include diphtheria, whooping cough, tetanus, polio, tuberculosis, measles, and hepatitis-B. In addition, vaccination against Japanese Encephalitis and Haemophilus influenza type B will be provided in selected districts/states of the country. Pregnant women will also be immunized against tetanus. Ref. Park’s PSM 24th ed. Page 462","pyqMatches":[{"year":"2020","no":101,"q":"Mission Indradhanush is for:","o":["Non-communicable diseases","Universal immunization","Family planning","Safe water and sanitation"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6143, 'PSM', 'Biostatistics', 'Moderate', 'Preventive_&_Social_Medicine', 755, '{"id":6143,"subject":"PSM","chapter":"Biostatistics","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":755,"q":"A study had a normal distribution with the median value as 200 and standard deviation 20. 68 % will fall between","o":["160-240","170-230","180-220","190-210"],"a":2,"e":"Ans. C. 180-220 As the median value is 200 and the standard deviation is 20, the normal distribution is: 68% of the population will have values between – median +/- 1 SD = 220 +/- 20 = 180-220 95% of the population will have values between – median +/- 2 SD = 220 +/- 40 = 160-240 Note: in the MCQ, as the data shows a normal distribution, the median will be equal to mean and the mode. Park’s PSM Ed. 24th page no. 885","pyqMatches":[{"year":"2020","no":102,"q":"A study had a normal distribution with the median value as 200 and standard deviation 20. 68 % will fall between","o":["160-240","170-230","180-220","190-210"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6144, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 756, '{"id":6144,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":756,"q":"Which of the following is a technique/method based on behavioural sciences","o":["Management by objectives","Network analysis","Systems analysis","Decision making"],"a":0,"e":"Ans. A. Management by objectives The methods based on behavioural sciences include organizational design personal management Management by objectives information systems communication The Quantitative methods include: cost-benefit analysis cost-effective analysis input-output analysis network analysis as PERT and CPM Planning programming budgeting systems decision making Ref: Park’s 25ed, PAge no. 934","pyqMatches":[{"year":"2020","no":103,"q":"Which of the following is a technique/method based on behavioural sciences","o":["Management by objectives","Network analysis","Systems analysis","Decision making"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6145, 'PSM', 'Maternal & Child Health', 'Moderate', 'Preventive_&_Social_Medicine', 757, '{"id":6145,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":757,"q":"As per the sustainable development goals, The target for MMR is to achieve maternal deaths of","o":["< 70 / Lac live births","< 100 / lac live births","< 7 / 1000 live births","< 10 / 1000 live births"],"a":0,"e":"Ans: A. < 70 / Lac live births By 2030, reduce the global maternal mortality ratio to less than 70 per 100,000 live births. Park’s PSM 24th ed. Page no. 28 Table: 4","pyqMatches":[{"year":"2020","no":104,"q":"As per the sustainable development goals, The target for MMR is to achieve maternal deaths of","o":["< 70 / Lac live births","< 100 / lac live births","< 7 / 1000 live births","< 10 / 1000 live births"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6146, 'PSM', 'Environment & Occupational Health', 'Easy', 'Preventive_&_Social_Medicine', 758, '{"id":6146,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":758,"q":"The best method for routine monitoring of air pollution","o":["Sulphur dioxide, smoke, and particulate matter","Sulphur dioxide, Hydrogen sulphide, carbon monoxide","Carbon dioxide, hydrogen sulphide, lead","Sulphur dioxide, Lead and particulate matter"],"a":3,"e":"Ans. D Sulphur dioxide, Lead and particulate matter Air quality index consists of: Particulate matter (less than 2.5 micrometers and 10 micrometer – PM2.5 and PM10) Nitrogen dioxide (NO2) Sulphur dioxide (SO2) Carbon monoxide (CO) Ozone (O3) Ammonia (NH3) Lead (Pb) Reference: https://pib.gov.in/newsite/PrintRelease.aspx? relid=110654","pyqMatches":[{"year":"2020","no":105,"q":"The best method for routine monitoring of air pollution","o":["Sulphur dioxide, smoke, and particulate matter","Sulphur dioxide, Hydrogen sulphide, carbon monoxide","Carbon dioxide, hydrogen sulphide, lead","Sulphur dioxide, Lead and particulate matter"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6147, 'PSM', 'Biostatistics', 'Moderate', 'Preventive_&_Social_Medicine', 759, '{"id":6147,"subject":"PSM","chapter":"Biostatistics","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":759,"q":"The variation in data is compared with another data set by:","o":["Variance","Coefficient of variation","The standard error of mean","Standard deviation"],"a":1,"e":"Ans. B. Coefficient of variation Variance: Is the square of SD which tells about the standard deviation Coefficient of variation: It may help by comparing the variations in the data set The standard error of the mean: It is to compare the means of the data sets which have a different sample size, central tendency, and standard deviations Standard deviation: It is the deviation of values from the mean Ref. Fundamentals of Biostatistics - 7th Edition (Pg 20, 21)","pyqMatches":[{"year":"2020","no":106,"q":"The variation in data is compared with another data set by:","o":["Variance","Coefficient of variation","The standard error of mean","Standard deviation"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6148, 'PSM', 'Miscellaneous', 'Hard', 'Preventive_&_Social_Medicine', 760, '{"id":6148,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":760,"q":"In which of the following methods of management is the benefit measured in natural units?","o":["Program budgeting system","Network analysis","Cost-effective analysis","Cost-benefit analysis"],"a":2,"e":"Ans. C. Cost-effective Analysis In cost-effective analysis (CEA), benefits are measured in natural units of the outcomes of the programs (life-years gained, cases prevented, etc.) and the costs are measured in monetary units. The most comprehensive indicator of CEA is Quality-Adjusted Life Years (QALYs). Park’s PSM 24th ed. Page no. 908","pyqMatches":[{"year":"2020","no":107,"q":"In which of the following methods of management is the benefit measured in natural units?","o":["Program budgeting system","Network analysis","Cost-effective analysis","Cost-benefit analysis"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6149, 'PSM', 'Epidemiology', 'Moderate', 'Preventive_&_Social_Medicine', 761, '{"id":6149,"subject":"PSM","chapter":"Epidemiology","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":761,"q":"The difference between the incidence in the exposed and non-exposed group is best given by:","o":["Relative risk","Attributable risk","Population attributable risk","Odds ratio"],"a":1,"e":"Ans. B Attributable Risk Attributable Risk Attributable Risk is the difference in incidence rates or proportions of disease or death between an exposed and non-exposed group. It is expressed in percentage and gives the extent to which the disease can be attributed to the exposure in a cohort study. Reference: Park 25th Edition, page no:86","pyqMatches":[{"year":"2020","no":108,"q":"The difference between the incidence in the exposed and non-exposed group is best given by:","o":["Relative risk","Attributable risk","Population attributable risk","Odds ratio"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6150, 'PSM', 'Biostatistics', 'Moderate', 'Preventive_&_Social_Medicine', 762, '{"id":6150,"subject":"PSM","chapter":"Biostatistics","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":762,"q":"If one variable is given then you can find another variable by","o":["Coefficient of variation","Coefficient of correlation","Coefficient of regression","Coefficient of determination"],"a":2,"e":"Ans. C. Coefficient of regression The coefficient of correlation tells about the strength of association but not about quantity. On the other hand, the coefficient of regression is used for quantification. If we wish to know in an individual case the value of one variable, knowing the value of the other, we calculate what is known as the regression coefficient of one measurement to the other. It is customary to denote the independent variable by x and the dependent variable by y.","pyqMatches":[{"year":"2020","no":109,"q":"If one variable is given then you can find another variable by","o":["Coefficient of variation","Coefficient of correlation","Coefficient of regression","Coefficient of determination"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6151, 'PSM', 'Concept of Health & Disease', 'Hard', 'Preventive_&_Social_Medicine', 763, '{"id":6151,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":763,"q":"Prospective screening is done in case of?","o":["Neonate for thyroid diseases","Immigrant screening","Pap smear for 45-year female","Diabetes mellitus for 40-year male"],"a":1,"e":"Ans. B. Immigrant Screening Screening of immigrants to a country is an example of prospective screening. Prospective screening: People screened for others benefit The essential purpose is case detection Requested for screening for disease control; specific request from the authority","pyqMatches":[{"year":"2020","no":110,"q":"Prospective screening is done in case of?","o":["Neonate for thyroid diseases","Immigrant screening","Pap smear for 45-year female","Diabetes mellitus for 40-year male"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6152, 'PSM', 'Demography & Family Planning', 'Hard', 'Preventive_&_Social_Medicine', 764, '{"id":6152,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":764,"q":"A researcher wanted to prove the relation between COPD and smoking. He collected patients records from government hospitals and records of cigarette sales from the finance and taxation department. This is an example of which study design:","o":["Cross-sectional","Posological study","Ecological study","Operations research"],"a":2,"e":"Ans. C. Ecological study design This is an example of an ecological study. An ecological study is a type of Observational study where information is collected on a group (or population) rather than on individual members and then analyzed. Here the association between a summary measure of sale of cigarettes (risk factor) and a summary measure of the number of cases of COPD(outcome) is studied.","pyqMatches":[{"year":"2020","no":111,"q":"A researcher wanted to prove the relation between COPD and smoking. He collected patients records from government hospitals and records of cigarette sales from the finance and taxation department. This is an example of which study design:","o":["Cross-sectional","Posological study","Ecological study","Operations research"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6153, 'PSM', 'Nutrition', 'Hard', 'Preventive_&_Social_Medicine', 765, '{"id":6153,"subject":"PSM","chapter":"Nutrition","difficulty":"Hard","source":"Preventive_&_Social_Medicine","sourceNo":765,"q":"A study was done to assess malnutrition among young children. 100 children were selected each from rural and urban areas. Out of these, 30 among rural and 20 among urban were found to be malnourished. which of the following statistical test is used to compare the data sets?","o":["Paired t-test","Chi-square","The standard error of mean","ANOVA"],"a":1,"e":"Ans. B. Chi-square test Chi-square (x 2 ) Test offers an alternate method of testing the significance of the difference between two proportions. It has the advantage that it can also be used when more than two groups are to be compared. Park’s PSM 24th ed. Page no. 889","pyqMatches":[{"year":"2020","no":112,"q":"A study was done to assess malnutrition among young children. 100 children were selected each from rural and urban areas. Out of these, 30 among rural and 20 among urban were found to be malnourished. which of the following statistical test is used to compare the data sets?","o":["Paired t-test","Chi-square","The standard error of mean","ANOVA"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6154, 'PSM', 'Environment & Occupational Health', 'Easy', 'Preventive_&_Social_Medicine', 766, '{"id":6154,"subject":"PSM","chapter":"Environment & Occupational Health","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":766,"q":"The active disinfectant property of bleaching powder is due to:","o":["Chlorine","Hypochloric acid","Hypochlorous acid","Chloramines"],"a":2,"e":"Ans. C. Hypochlorous acid Hypochlorous acid is the most effective form of chlorine for water disinfection. The active component of bleaching powder, CaOCl2, is hypochlorous acid. The disinfecting action of chlorine is mainly due to hypochlorous acid, and to a small extent due to the hypochlorite ions. Park’s PSM 24th ed. Page no. 138","pyqMatches":[{"year":"2020","no":113,"q":"The active disinfectant property of bleaching powder is due to:","o":["Chlorine","Hypochloric acid","Hypochlorous acid","Chloramines"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6155, 'PSM', 'Maternal & Child Health', 'Moderate', 'Preventive_&_Social_Medicine', 767, '{"id":6155,"subject":"PSM","chapter":"Maternal & Child Health","difficulty":"Moderate","source":"Preventive_&_Social_Medicine","sourceNo":767,"q":"Mother does not transmit what antibody to the baby –","o":["Polio","Diphtheria","Diphtheria","Tetanus"],"a":0,"e":"Ans. A. Polio When given during pregnancy, the Tdap vaccine boosts antibodies in the mother, which are transferred to her developing baby. Early third-trimester administration optimizes neonatal antibody levels. Ref. https://www.ncbi.nlm.nih.gov/pmc/articles/PMC4168293/pdf/ci 1)","pyqMatches":[{"year":"2020","no":114,"q":"Mother does not transmit what antibody to the baby –","o":["Polio","Diphtheria","Diphtheria","Tetanus"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6156, 'PSM', 'National Health Programmes', 'Easy', 'Preventive_&_Social_Medicine', 768, '{"id":6156,"subject":"PSM","chapter":"National Health Programmes","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":768,"q":"Voluntary admission can be done maximum up to how much time according to MHA 2017","o":["48 hrs","7 Days","30 Days","90 Days"],"a":3,"e":"Ans. D. 90 Days If admission requires more than 30 days or readmission within 7 days (section 90), they should be examined by two psychiatrists and can be admitted for a maximum period of 90 days if they satisfy norms as per this section of the act and have to inform the board for permission, taking account of AD and consent should be reviewed fortnightly along with planning for community-based treatment. http://www.amhonline.org/article.asp?issn=2589- 9171;year=2018;volume=19;issue=1;spage=9;epage=14;aulast=Ner","pyqMatches":[{"year":"2020","no":115,"q":"Voluntary admission can be done maximum up to how much time according to MHA 2017","o":["48 hrs","7 Days","30 Days","90 Days"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6157, 'PSM', 'Miscellaneous', 'Easy', 'Preventive_&_Social_Medicine', 769, '{"id":6157,"subject":"PSM","chapter":"Miscellaneous","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":769,"q":"Blood bags are disposed of in","o":["Yellow bag","Black bag","Red bag","White bag"],"a":2,"e":"Ans : C. Red bag The black bag is used for collecting dry waste material which is not infectious. Materials like paper, plastics, cardboard boxes, and other dry waste generated in the hospital office or in the wards are disposed of in this bag. This is not biomedical waste. The red bag is used for the disposal of plastics collected from operation theaters, ICUs and wards. The yellow bag is used for highly infectious items like a pathological waste, human anatomical waste such as body parts, amputated parts/organs, tumors, placentas, aborted or dead fetuses, blood- soaked cotton bandages, animal tissues, organs, carcasses, etc. Blue or White opaque bag is used for collecting the segregated metal sharps such as needles, blades, saws, scalpels, and glass pieces. Ref Park 23''/e p. 793-794]","pyqMatches":[{"year":"2020","no":116,"q":"Blood bags are disposed of in","o":["Yellow bag","Black bag","Red bag","White bag"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6158, 'PSM', 'Demography & Family Planning', 'Easy', 'Preventive_&_Social_Medicine', 771, '{"id":6158,"subject":"PSM","chapter":"Demography & Family Planning","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":771,"q":"In Vision 2020, the target for Secondary Sevice center is for how much population –","o":["10000","50000","1 lac","5 lac"],"a":3,"e":"Ans is ''d'' i.e. 5 lac Vision 2020: The Right to Sight, is a global initiative launched by WHO in 1999 in a broad coalition with a ''Task Force of International Non-Governmental Organisations (NGOs)'' to combat the gigantic problem of blindness in the world. The objective is to eliminate avoidable blindness by the year 2020 and to reduce the global burden of blindness. The government of India has adopted ''Vision 2020: Right to Sight'' under the National Programme for Control of Blindness. Based on the recommendations of WHO, there is a need to develop the infrastructure pyramid which includes I. Primary level Vision Centres There is a need to develop 20000 vision centers, An Each with one Ophthalmic Assistant or equivalent (Community- based MLOP), Covering a population of 50000.","pyqMatches":[{"year":"2020","no":119,"q":"In Vision 2020, the target for Secondary Sevice center is for how much population –","o":["10000","50000","1 lac","5 lac"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6159, 'PSM', 'Epidemiology', 'Easy', 'Preventive_&_Social_Medicine', 772, '{"id":6159,"subject":"PSM","chapter":"Epidemiology","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":772,"q":"Admission rate bias is?","o":["Reporting bias","Response bias","Berkesonian bias","None"],"a":2,"e":"Ans. is ''c'' i.e., Berkesonian bias Selection bias Selection bias is distortion that results from the procedure used to select subjects and from factors that influence study participation. Groups to be compared are differentially susceptible to the outcome even before the experimental maneuver is performed. Selection bias may be of the following types.","pyqMatches":[{"year":"2020","no":122,"q":"Admission rate bias is?","o":["Reporting bias","Response bias","Berkesonian bias","None"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6160, 'PSM', 'Concept of Health & Disease', 'Easy', 'Preventive_&_Social_Medicine', 2017, '{"id":6160,"subject":"PSM","chapter":"Concept of Health & Disease","difficulty":"Easy","source":"Preventive_&_Social_Medicine","sourceNo":2017,"q":"Other 28 children developed chickenpox within next 2 week what is the SAR of chickenpox?","o":["60%","70%","80%","90%"],"a":2,"e":"Ans. is ''c'' i.e., 80% [Ref: Park Mlle p. 105-107 & 23ra/e p.100] Primary cases in the question → 5 (developing chickenpox on same day) Immune children → 10 Susceptible contacts → Total children - (Primary cases + immunized children) = 50 - ( 5+10) = 35 No. of susceptible developing desease = 28 No of susceptible developing disease x 100 = 80% Total number of susceptiblesx","pyqMatches":[{"year":"2016","no":2017,"q":"Other 28 children developed chickenpox within next 2 week what is the SAR of chickenpox?","o":["60%","70%","80%","90%"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6161, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 1, '{"id":6161,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":1,"q":"Which is not a tumor suppressor gene ?","o":["WT-1","Rb","p53","RAS"],"a":3,"e":"RAS [Ref. Robbins 7th/e p 295] RAS is not a tumour suppressor gene, it is an oncogene. Normal growth and cell division is under the control of two types of genes: (i) Protooncogenes (ii) Tumour suppressor genes Protooncogenes are the genes that normally control how often a cell divides and the degree to which it differentiates. They allow cell division at a controlled rate. When a protooncogene mutates into, an oncogene it becomes permanently \"turned on\" or activated even when it is not supposed to be. When this occurs, cell divides too quickly which causes cancer. Tumour suppressor genes are normal genes that slow cell division. A tumour suppressor gene is like the brake pedal on a car, it normally keeps the cell from dividing too quickly just as a brake keeps a car from going too fast. When it mutates, cell division can get out of control. Functions of tumour suppressor gene:- Repression of genes that is essential for the continuing of the cell cycle. An important function of tumour suppression gene is repairing DNA damage. Every time a cell prepares to divide into 2 new cells it must duplicate its DNA. This process is not perfect and copying error sometimes occurs. Fortunately, cells have DNA repair genes which make proteins that proofread DNA. But if the genes responsible for the repair are faulty then the DNA can develop abnormalities that may lead to cancer. If there is too much damage to a cell''s DNA to be fixed by the DNA repair genes, the tumour suppressor gene is responsible for destroying the cell by a process called Apoptosis. If the tumour suppressor gene is not working. cells with DNA damage will continue to grow and can eventually become cancerous. Examples of Tumour suppressor gene GeneCancer associated • TGF Preceptor Carcinoma of stomach • E-cadherin Carcinoma of colon • NF-1 Neuroblastomas • NF-2 Schwannoma and meningiomas • APC/13 catenin Carcinoma of stomach colon, pancreas, melanoma • PTEN Endometrial and prostate carcinoma • SMAD 2 and Colon, pancreas tumour • SMAD 4 • RB Retinoblastoma, osteosarcoma carcinoma of breast, colon and Lung. • P 53 Most human cancers • WT-1 Wilms Tumour • P16 Pancreatic, breast and h l esophageal cancers • BRCA 1 and Unknown • BRCA 2 • KLF 6 Prostate","pyqMatches":[{"year":"2015","no":428,"q":"Which is not a tumor suppressor gene ?","o":["WT-1","Rb","p53","RAS"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6162, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 2, '{"id":6162,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":2,"q":"Michaelis Gutmann bodies are seen in","o":[">Xanthogranulomatous",">pyelonephritis",">Malakoplakia","Nail patella syndrome"],"a":2,"e":"Malakoplakia [Ref. Robbins 7th/e p 1027-1028] Malakoplakia is a variant of cystitis, it is related to chronic bacterial infection mostly by E.coli or occasionally by proteus species. It is characterized by unusual appearing macrophages and giant phagosomes. It points to defect in phagocytic or degradative function of macrophage. It is a peculiar pattern of vesical inflammatory reaction characterized microscopically by soft, yellow, slightly raised mucosal plaques 3-4 cm in diameter. Histologically it is characterized by infiltration with large foamy macrophages with occasional multinucleate giant cells and interspersed lymphocytes. \" The macrophages have an abundant granular cytoplasm and the granularity is PAS positive. In addition to these histological changes, malakoplokia is also characterized by Michaelis Guttman bodies. - Michalies Guttman bodies are Laminated mineralized concretions resulting from deposition of calcium in enlarged lysosomes. - They are typically present both within the macrophages and between cells. - They demonstrate positive results using PAS stain and are diastase resistance diastase resistance. - They stain with Kossa, stain for calcium and perls Prussian blue stain for iron. - Immunchistochemical studies demonstrates positive results for CD68 antibodies. Malakoplakia occurs with increased frequency in itnmunosuppressed transplant recipients.","pyqMatches":[{"year":"2013","no":442,"q":"Michaelis Gutmann bodies are seen in","o":[">Xanthogranulomatous",">pyelonephritis",">Malakoplakia","Nail patella syndrome"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6163, 'Pathology', 'Hematology', 'Easy', 'Pathology', 3, '{"id":6163,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":3,"q":"D.I.C. is seen in :","o":[">Acute promyelocytic leukemia",">Acute myelomonocytic leukemia",">CMC",">Autoimmune hemolytic anemia"],"a":0,"e":"Acute promyelocytic leukemia [Ref. Harrison 16''11/e p 636] Disseminated intravascular coagulation is associated with promyelocytic leukemia Acute promyelocytic leukemia (AML-M3) constitutes 5-10% of all cases of AML The leukemic cells of these type of anemia are hypergranular. Granules of these leukemic cells (promyelocytes) contain thromboplastin like material resulting in widespread disseminated intravascular coagulation. Also know Majority of M3 cases demonstrate a reciprocal translocation involving chromosome 15 and 17, t (15 ; 17)","pyqMatches":[{"year":"2012","no":471,"q":"D.I.C. is seen in :","o":[">Acute promyelocytic leukemia",">Acute myelomonocytic leukemia",">CMC",">Autoimmune hemolytic anemia"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6164, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 4, '{"id":6164,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":4,"q":"Interleukin responsible for Pyrexia is:","o":["IL1","IL3","IL4","IL8"],"a":0,"e":"IL1","pyqMatches":[{"year":"2015","no":404,"q":"Interleukin responsible for Pyrexia is:","o":["IL1","IL3","IL4","IL8"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6165, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 5, '{"id":6165,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":5,"q":"Liquefactive necrosis is seen in:","o":["Heart","Brain","Lungs","Spleen"],"a":1,"e":"Brain","pyqMatches":[{"year":"2015","no":389,"q":"Liquefactive necrosis is seen in:","o":["Heart","Brain","Lungs","Spleen"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6166, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 6, '{"id":6166,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":6,"q":"Process of migration of leukocytes through the endothelium is through:","o":["Phagocytosis","Pinocytosis","Diapedesis","Apoptosis"],"a":2,"e":"The next step in the process of leukocyte recruitment is migration of the leukocytes through the endothelium, called transmigration or diapedesis. Transmigration of leukocytes occurs mainly in post-capillary venules. Chemokines act on the adherent leukocytes and stimulate the cells to migrate through interendothelial spaces toward the chemical concentration gradient, that is, toward the site of injury or infection where the chemokines are being produced. Ref: Robbins 8th edition, Chapter 2.","pyqMatches":[{"year":"2015","no":406,"q":"Process of migration of leukocytes through the endothelium is through:","o":["Phagocytosis","Pinocytosis","Diapedesis","Apoptosis"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6167, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 7, '{"id":6167,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":7,"q":"Bridging necrosis is characteristically seen in:","o":["Acute hepatitis","Chronic hepatitis","Both of the above","None of the above"],"a":2,"e":"Ans: C. Both of the above Bridging necrosis is a more severe form of hepatocellular injury in acute viral hepatitis and may progress to fulminant hepatitis or chronic hepatitis. Bridging necrosis is characterized by bands of necrosis linking portal tracts to central hepatic veins, one central hepatic vein to another, or a portal tract to another tract. In severe cases of acute hepatitis, confluent necrosis of hepatocytes may lead to bridging necrosis connecting portal-to-portal, central-to- central, or portal-to-central regions of adjacent lobules. Hepatocyte swelling and regeneration compress sinusoids, and the more or less radial array of hepatocyte plates around terminal hepatic veins are lost. Bridging fibrosis is an important component of severe examples of chronic viral hepatitis and steatohepatitis.","pyqMatches":[{"year":"2016","no":463,"q":"Bridging necrosis is characteristically seen in:","o":["Acute hepatitis","Chronic hepatitis","Both of the above","None of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6168, 'Pathology', 'Inflammation', 'Moderate', 'Pathology', 8, '{"id":6168,"subject":"Pathology","chapter":"Inflammation","difficulty":"Moderate","source":"Pathology","sourceNo":8,"q":"Which of the following would be the best morphological feature to distinguish ulcerative colitis from Crohn''s disease?","o":["Diffuse distributions of pseudopolyps","Mucosal edema","Crypt abscesses","Lymphoid aggregates in the mucosa"],"a":0,"e":"Pseudopolyps are more commonly found in ulcerative colitis than Crohn''s disease. These are discrete areas resulting from surviving islands of mucosa or heaped up granulation tissue. Since in ulcerative colitis there is diffuse mucosal inflammation these pseudopolyps are diffusely distributed. Distinguishing features between Ulcerative colitis and Crohn''s disease: Ulcerative colitis Crohn’s disease Rectal involvement Yes Variable Distribution Diffuse Segmental or diffuse Terminal ileum Backwash ileitis Thickened and stenosis Serosa Normal Creeping fat Mucosa Hemorrhagic Cobblestone and linear ulcers Pseudopolyps Frequent Less common Strictures No Common Fistulas No Common Lymphoid hyperplasia Infrequent Common Crypt abscess Extensive Focal Ref: Pediatric Inflammatory Bowel Disease By Petar Mamula page 227.","pyqMatches":[{"year":"2016","no":479,"q":"Which of the following would be the best morphological feature to distinguish ulcerative colitis from Crohn''s disease?","o":["Diffuse distributions of pseudopolyps","Mucosal edema","Crypt abscesses","Lymphoid aggregates in the mucosa"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6169, 'Pathology', 'Organ System Pathology', 'Moderate', 'Pathology', 9, '{"id":6169,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Moderate","source":"Pathology","sourceNo":9,"q":"Autosomal recessive polycystic kidney disease is characterised by the altered expression of:","o":["Polycystin","Nephrocystin","Uromodulin","Fibrocystin"],"a":3,"e":"Fibrocystin (polyductin) gene mutation is seen in autosomal recessive polycystic kidney disease. Note: Polycystin mutation is associated with autosomal dominant polycystic kidney disease. Nephrocystin is related to nephronophthisis. Uromodulin mutation is seen in medullary cystic kidney disease. Ref: Harrisons principles of internal medicine, 18th edition, Page: 2356.","pyqMatches":[{"year":"2016","no":1094,"q":"Autosomal recessive polycystic kidney disease is characterised by the altered expression of:","o":["Polycystin","Nephrocystin","Uromodulin","Fibrocystin"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6170, 'Pathology', 'Immunopathology', 'Hard', 'Pathology', 10, '{"id":6170,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Hard","source":"Pathology","sourceNo":10,"q":"More than 90% patients of CREST syndrome with the limited cutaneous form of this disorder make which of the following autoantibodies?","o":["Anti-centromere","Anti-DNA topoisomerase l","Anti-double-stranded DNA","Anti-Golgi"],"a":0,"e":"All forms of scleroderma are thought to have a strong autoimmune component, and glucocorticoids and azathioprine are used to suppress the inflammatory complications of scleroderma. (Other drugs that can be used in therapy include penicillamine, which inhibits collagen cross-linking, NSAIDS for pain, and ACE inhibitors to protect the kidney if hypertension or renal damage occurs). The anti-centromere antibody is quite specific for CREST syndrome (96% of cases), and is only seen in a minority of patients with diffuse scleroderma (mainly those with Raynaud''s phenomenon) and rarely in systemic lupus erythematosus and mixed connective tissue disease. Also know: Anti-DNA topoisomerase I , also called anti-Scl-70 occurs commonly (64-75%) in diffuse scleroderma, but only rarely in CREST syndrome. Anti-double-stranded DNA is fairly specific for systemic lupus erythematosus, although it only occurs in 50-60% of lupus cases. Anti-Golgi antibodies are seen most often in systemic lupus erythematosus and Sjögren syndrome. Ref: Hellmann D.B., Imboden Jr. J.B. (2013). Chapter 20. Musculoskeletal & Immunologic Disorders. In M.A. Papadakis, S.J. McPhee, M.W. Rabow (Eds),CURRENT Medical Diagnosis & Treatment 2013.","pyqMatches":[{"year":"2016","no":391,"q":"More than 90% patients of CREST syndrome with the limited cutaneous form of this disorder make which of the following autoantibodies?","o":["Anti-centromere","Anti-DNA topoisomerase l","Anti-double-stranded DNA","Anti-Golgi"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6171, 'Pathology', 'Hematology', 'Easy', 'Pathology', 11, '{"id":6171,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":11,"q":"1 to 2 mm haemorrhages in skin are known as:","o":["Micro bleed","Petechiae","Purpura","None of the above"],"a":1,"e":"Minute 1- to 2-mm hemorrhages into skin, mucous membranes, or serosal surfaces are called petechiae. These are most commonly associated with locally increased intravascular pressure, low platelet counts (thrombocytopenia), or defective platelet function (as in uremia). Ref: Robbins 8th edition Chapter 4.","pyqMatches":[{"year":"2016","no":1033,"q":"1 to 2 mm haemorrhages in skin are known as:","o":["Micro bleed","Petechiae","Purpura","None of the above"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6172, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 12, '{"id":6172,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":12,"q":"''Flare'' in Triple response is mediated by :","o":["Axon reflex","Arteriolar dilation","Histamine release","Local hormones"],"a":0,"e":"A i.e. Axon reflex","pyqMatches":[{"year":"2015","no":482,"q":"''Flare'' in Triple response is mediated by :","o":["Axon reflex","Arteriolar dilation","Histamine release","Local hormones"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6173, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 13, '{"id":6173,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":13,"q":"Medial calcification is seen in -","o":["Atherosclerosis","Arteriolosclerosis","Monckebergs sclerosis","Dissecting aneurysm"],"a":2,"e":"Ans. is ''c'' i.e., Monckebergs sclerosis First see types of arteries Based on their size and structural features, arteries are divided into three types. Large or Elastic arteries Aorta Its large branches, eg. - Innominate, Subclavian, common carotid, iliac. Pulmonary arteries. Medium sized or muscular arteries Small branches of aorta → Coronary, Renal Small arteries and arterioles Within substance of the tissue Now see their affection ? Arteriosclerosis Dont get confuse with atherosclerosis. Arteriosclerosis means hardening of arteries by thickening and loss of elasticity of arterial wall. o There are three patterns of arteriosclerosis. Atherosclerosis Characterized by intimal lesions, i.e. atheromas, which project into vascular lumen and may obstruct it. o This is the most common pattern of arteriosclerosis. It involves elastic arteries, and large & medium size muscular arteries. Arteriolosclerosis Seen in arterioles of patiens with hypertension and diabetes. Two anatomic variants are common —> hyaline and hyperplastic arteriolosclerosis. Monkeberg medial calcific sclerosis It is seen in small and medium sized muscular arteries. It is a degenerative and apparently non-inflammatory disease. Media of these arteries becomes calcified. It occurs in patients older than 50 years.","pyqMatches":[{"year":"2012","no":449,"q":"Medial calcification is seen in","o":["Atherosclerosis","Arteriolosclerosis","Monckebergs sclerosis","Dissecting aneurysm"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6174, 'Pathology', 'Cell Injury & Adaptation', 'Moderate', 'Pathology', 14, '{"id":6174,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Moderate","source":"Pathology","sourceNo":14,"q":"Changes seen in atherosclerotic plaque at the time of rupture are all except -","o":["Thin fibrosis cap","Multiple foam cap","Smooth muscle cell hypertrophy","Cell debris"],"a":2,"e":"Ans. is ''c'' i.e., Smooth muscle cell hypertrophy Rupture occurs in advanced atherosclerotic lesion. In advanced atheroma, smooth muscle cells undergo apoptosis and advanced atheromatous plaque often have mostly fibrous character with lack of smooth muscle cells that are seen in less advanced lesion.","pyqMatches":[{"year":"2013","no":389,"q":"Changes seen in atherosclerotic plaque at the time of rupture are all except","o":["Thin fibrosis cap","Multiple foam cap","Smooth muscle cell hypertrophy","Cell debris"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6175, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 15, '{"id":6175,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":15,"q":"Atheromatous changes of blood vessels affects early in -","o":["Kidney","Heart","Liver","Spleen"],"a":1,"e":"Ans. is ''b'' i.e., Heart Sites of Atherosclerosis Atherosclerotic plaques develop primarily in elastic arteries (e.g., aorta, carotid and iliac arteries), and large & medium sized muscular arteries (e.g., coronary artery and poplitial arteries). In descending order, the vessels most commonly involved are - Abdominal aorta (most common) → Causing aneurysm Coronary arteries (heart) → Causing MI Popliteal arteries → Causing ischemic gangrene of lower limbs. Internal carotid arteries → Causing stroke a Circle of willis Vessels usually spared are Vessels of upper extremities Mesentric and renal vessels, except at their ostia.","pyqMatches":[{"year":"2012","no":443,"q":"Atheromatous changes of blood vessels affects early in","o":["Kidney","Heart","Liver","Spleen"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6176, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 16, '{"id":6176,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":16,"q":"Which of the following is a non-modifiable risk factor for CHD -","o":["Diabetes","Smoking","Hypertension","Old age"],"a":3,"e":"Ans. is ''d'' i.e., Old age","pyqMatches":[{"year":"2013","no":390,"q":"Which of the following is a non- modifiable risk factor for CHD","o":["Diabetes","Smoking","Hypertension","Old age"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6177, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 17, '{"id":6177,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":17,"q":"Most common cause of dissecting hematoma is because of -","o":["Hypertension","Marfan''s","Iatrogenic","Kawasaki"],"a":0,"e":"Ans. is ''a'' i.e., Hyertension More than 90% of dissections occur in men between the ages of 40 and 60 with antecedent hypertension.","pyqMatches":[{"year":"2012","no":446,"q":"Most common cause of dissecting hematoma is because of","o":["Hypertension","Marfan''s","Iatrogenic","Kawasaki"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6178, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 18, '{"id":6178,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":18,"q":"Cystic medial necrosis is seen in-","o":["Marfans syndrome","Friedrichs ataxia Pattern","Downs syndrome","Kawasaki disease"],"a":0,"e":"Ans. is ''a'' i.e., Marfan''s syndrome Cystic medial necrosis (CMN) is a disorder of large arteries, characterized by an accumulation of a basophilic ground substance in the media with cyst-like lesions. It is known to occur in certain connective tissue diseases such as Marfan syndrome, Ehlers-Danlos syndrome, and annuloaortic ectasia, which usually result from degenerative changes in the aortic wall. The relationships between CMN and congenital heart defects as well as other disorders have been evidenced. The mechanisms are still controversial, even though many molecular studies have been conducted it is characterized by elastic tissue fragmentation and separation of the elastic and fibromuscular elements of the tunica media by small cleft like spaces where the normal elastic tissue is lost; these areas are filled with the amorphous extracellular matrix of connective tissue and resemble but are not truly cysts.","pyqMatches":[{"year":"2012","no":448,"q":"Cystic medial necrosis is seen in","o":["Marfans syndrome","Friedrichs ataxia Pattern","Downs syndrome","Kawasaki disease"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6179, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 19, '{"id":6179,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":19,"q":"Small vessel vasculitis are -","o":["Classical PAN","Wegner''s granulomatosis","Giant cell arteritis","All"],"a":1,"e":"Ans. is `b'' i.e., Wegner''s granulomatosis Inflammation of vessel wall is called vasculitis. o Of these systemic necrotizing vasculitis, several types affect the aorta and medium sized vessels, but most affect small vessels, such as arterioles, venules, and capillaries —> small vessel vasculitis. Large vessel vasculitis Medium vessel vasculitis Small vessel vasculitis o Giant cell arteritis o Polyarteritis nodosa ANACA positive ANCA negative (Temporal arteritis) o Kawasaki disease o Wegner''s granulomatosis o Bechet''s syndrome o Takayasu arteritis o Buerger''s disease o Microscopic polyangitis o Hypersensitivity o Cogan syndrome o Churg strauss syndrome o Urticarial vasculitis o Drug induced Following information have been added in Pie of Robbins o Following are small vessels vasculitis and are immune-complex mediated :","pyqMatches":[{"year":"2015","no":439,"q":"Small vessel vasculitis are","o":["Classical PAN","Wegner''s granulomatosis","Giant cell arteritis","All"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6180, 'Pathology', 'Inflammation', 'Moderate', 'Pathology', 20, '{"id":6180,"subject":"Pathology","chapter":"Inflammation","difficulty":"Moderate","source":"Pathology","sourceNo":20,"q":"All is true about Giant cell arteritis except ?","o":["Involves large to small sized areteries","Granulomatous inflammation","Most commonly involved artery is abdominal aorta","Segmental nature of the involvement"],"a":2,"e":"Ans. is ''c'' i.e., Most commonly involved artery is abdominal aorta It is the most common form of systemic vasculitis in adults, is an acute and chronic, often granulomatous, inflammation of arteries of large to small size. It affects principally the arteries in the head-especially the temporal arteries— but also the vertebral and ophthalmic arteries and the aorta, where it may cause thoracic aortic aneurysm","pyqMatches":[{"year":"2012","no":445,"q":"All is true about Giant cell arteritis except ?","o":["Involves large to small sized areteries","Granulomatous inflammation","Most commonly involved artery is abdominal aorta","Segmental nature of the involvement"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6181, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 21, '{"id":6181,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":21,"q":"Raynaud''s phenomenon what change is seen in vessels initial stage -","o":["No change (Fibrinoid, Thrombosis)","Thrombosis","Fibrinoid necrosis","Hyaline sclerosis"],"a":0,"e":"Ans. is ''a'' i.e., No change Structural changes in the arterial walls are absent except late in the course, when intimal thickening can appear.","pyqMatches":[{"year":"2012","no":451,"q":"Raynaud''s phenomenon what change is seen in vessels initial stage","o":["No change (Fibrinoid, Thrombosis)","Thrombosis","Fibrinoid necrosis","Hyaline sclerosis"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6182, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 22, '{"id":6182,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":22,"q":"The tissue of origin of the Kaposi''s sarcoma is ?","o":["Lymphoid","Vascular","Neural","Muscular"],"a":1,"e":"Ans is ''b'' i.e., Vascular Kaposi Sarcoma Kaposi sarcoma is an intermediate grade, multicentric vascular, tumour * The pathogenesis of kaposi sarcoma is complex, fundamentally it is an angioproliferative disease that is not a true neoplastic sarcoma. It is a manifestation of excessive proliferation of spindle cells that are believed to be of vascular origin and have features in common with endothelial and smooth muscle cells. * Grossly-Three stages of the disease can be identified Patch (1st stage) Plaque (intermediate stage) LI Nodule (last stage) * Histologically-The changes are nonspecific in the early patch stage and more characteristic in the nodular stage which show sheets of plump proliferating spindle cells and endothelial in the dermis or subcutanous tissue","pyqMatches":[{"year":"2015","no":1131,"q":"The tissue of origin of the Kaposi''s sarcoma is ?","o":["Lymphoid","Vascular","Neural","Muscular"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6183, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 23, '{"id":6183,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":23,"q":"Concentric hypertrophy of left ventricle is seen in -","o":["Cong. bicuspid aortic valve","MS","AR","HOCM"],"a":0,"e":"Ans. is ''a'' i.e., Cong-Bicuspid aortic valve Aortic stenosis causes pressure overload that results in concentric hypertrophy. o Congenital bicuspic aortic valve causes valvular aortic stenosis.","pyqMatches":[{"year":"2013","no":400,"q":"Concentric hypertrophy of left ventricle is seen in?","o":["Mitral stenosis","Hypertension","Aortic regurgitation","None"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2015","no":443,"q":"Concentric hypertrophy of left ventricle is seen in","o":["Cong. bicuspid aortic valve","MS","AR","HOCM"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2013","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6184, 'Pathology', 'Organ System Pathology', 'Moderate', 'Pathology', 24, '{"id":6184,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Moderate","source":"Pathology","sourceNo":24,"q":"Which one of the following sets of components of cigarette smoke is a causal agent of coronary artery disease -","o":["Tar and nicotine","Nicotine and carbon monoxide and tar","Carbon monoxide and Tar","Carbon dioxide"],"a":1,"e":"Ans. is `b'' i.e., Nicotine and carbon monoxide and tar Mechanisms for smoking-induced Coronary heart disease Carbon monoxide induces atherogenesis. Nicotine stimulation of adrenergic drive raising both BP and myocardial oxygen demand. Lipid metabolism with fall in protective high-density lipoproteins. Note : Tar is associated with carcinogenesis (not atherosclerosis). But amongst the given options option b is the best answer as it consists of both nicotine and CO.","pyqMatches":[{"year":"2012","no":444,"q":"Which one of the following sets of components of cigarette smoke is a causal agent of coronary artery disease","o":["Tar and nicotine","Nicotine and carbon monoxide and tar","Carbon monoxide and Tar","Carbon dioxide"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6185, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 25, '{"id":6185,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":25,"q":"Earliest histological change in MI -","o":["Macrophage infiltration","Neutrophilic infiltration","Waviness of fibers","Coagulative necrosis"],"a":2,"e":"Ans. is ''c'' i.e., Waviness of fibers Variable waviness of fibres at border is the earliest histological finding (see tables of previous explanation).","pyqMatches":[{"year":"2013","no":394,"q":"Earliest histological change in MI","o":["Macrophage infiltration","Neutrophilic infiltration","Waviness of fibers","Coagulative necrosis"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6186, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 26, '{"id":6186,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":26,"q":"7 day old MI the most sensitive biochemical marker","o":["Troponin I T","CPK MB","LDH","Myoglobin"],"a":0,"e":"Ans. is ''a'' i.e., Troponin I T Troponin T or I is a sensitive member and return to normal after 7-10 days (see previous explanations).","pyqMatches":[{"year":"2012","no":441,"q":"7 day old MI the most sensitive biochemical marker","o":["Troponin I T","CPK MB","LDH","Myoglobin"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6187, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 27, '{"id":6187,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":27,"q":"Which is not seen in Aschoff bodies -","o":["Giant cells","Aschoff cells","Fibroblasts","Polymorphonuclear cells"],"a":3,"e":"Ans. is d i.e., Polymorphonuclear cells Aschoff bodies : * Aschoff bodies are focal inflammatory lesions seen during acute rheumatic fever * They consist of foci of swollen eosinophillic collagen surrounded by Lymphocytes (primarily T cells) Occasional plasma cells Aschoff giant cells (macrophages of rheumatic fever) Antitschkow cells (Antischkow cells are modified macrophages with abundant cytoplasm and central round to ovoid nuclei in which the chromatin is disposed in the central, slender wavy ribbon like pattern-caterpillar cells) Histiocytes Fibroblasts","pyqMatches":[{"year":"2013","no":398,"q":"Which is not seen in Aschoff bodies","o":["Giant cells","Aschoff cells","Fibroblasts","Polymorphonuclear cells"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6188, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 28, '{"id":6188,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":28,"q":"Vegetations in libman sacendocarditis are ?","o":["Large and fragile","Small warty along the line of closure of valve","Small or medium sized on either or both sides of valve","Small bland vegetations"],"a":2,"e":"Ans. is ''c'' i.e., Small or medium sized on either or both sides of valve SLE, mitral and tricuspid valvulitis with small, sterile vegetations, called Libman-Sacks endocarditis is occasionally encountered. The lesions are small single or multiple, sterile, granular pink vegetations ranging from 1 to 4 mm in diameter. The lesions may be located on the undersurfaces of the atrioventricular valves, on the valvular endocardium, on the cords, or on the mural endocardium of atria or ventricles. An intense valvulitis may be present, characterized by fibrinoid necrosis of the valve substance that is often contiguous with the vegetation. Subsequent fibrosis and serious deformity can result that resemble chronic RHD and require surgery.","pyqMatches":[{"year":"2012","no":442,"q":"Vegetations in libman sacendocarditis are ?","o":["Large and fragile","Small warty along the line of closure of valve","Small or medium sized on either or both sides of valve","Small bland vegetations"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6189, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 29, '{"id":6189,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":29,"q":"Causes of constrictive pericarditis is/are ?","o":["T.B.","SLE","Brucellosis","a and b"],"a":3,"e":"Ans. is ''a'' i.e., T.B.; b'' i.e., SLE Causes of constrictive pericarditis * Tuberculosis (most common cause) * Pericardial malignancies (especially breast, lung) * Post-viral pericarditis (especially hemorrhagic) * Drugs (e.g. Hydralazine, Procainamide, minoxidil, phenytoin) * Bacterial (purulent) pericarditis * Trauma / post - cardiac surgery → haemopericardium * Fungal pericarditis (Histoplasmosis) * Connective tissue disorders (e.g. SLE, RA, Sarcoidosis) * Parasitic pericarditis (toxoplasmosis, trichonosis) * Dressler syndrome * Mediastinal radiotherapy * Renal failure","pyqMatches":[{"year":"2016","no":415,"q":"Causes of constrictive pericarditis is/are ?","o":["T.B.","SLE","Brucellosis","a and b"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6190, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 30, '{"id":6190,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":30,"q":"Hypertrophy is -","o":["Increase in cell number","Increase in cell size","Decrease in cell number","Decrease in cell size"],"a":1,"e":"Ans. is ''B'' i.e., Increase in cell size Hypertrophy * Hypertrophy refers to an increase in the size of cells without increase in the number, resulting in an increase in the size of tissue. * Hypertrophy involves cell enlargement without cell division. * So, hypertrophied organ has just larger cells, but no new cells (by contrast, in hyperplasia there is increase in number of new cells without increase in size). * Nuclei in hypertrophied cells have a higher DNA content than in normal cells because the cells arrest in the cell cycle without undergoing mitosis. * Myocardium (heart muscle) and skeletal muscle undergo hypertrophy. * The most common stimulus for hypertrophy is increased workload. Mechanism of hypertrophy * The increase in cell size is due to synthesis of more structural proteins. * The genes that are induced during hypertrophy include those encoding transcription factors (C-fos, C-jun), growth factors (TGF-(3, TGF- 1, FGF); and vasoactive agents (a-agonists, endothelin-1, angiotensin II). * There may also be a switch of contractile proteins from adult to fetal or neonatal forms, e.g., during myocardial hypertrophy, the a- myosin heavy chain is replaced by 13-form of the myosin heavy chain, which leads to decrease myosine ATPase activity and a slower, more energetically economical contraction. * In addition, some genes that are expressed only in embryonic life are re-expressed in hypertrophied myocardium, e.g., in the embryonic heart, the gene for Atrial natriuratic peptide (ANP) is expressed in both atrium and ventricle. After birth, ventricular regulation of the gene is down regulated. Myocardial hypertrophy is associated with reinduction of ANF gene expression. ANP induces salt excretion by kidney L blood volume & pressure, decrease work load. Why do these changes occur ? * As already explained, the most common stimulus for myocardial hypertrophy is increased workload. * All the above morphological changes that occur in hypertrophy either increase muscle activity (to handle the increased workload) or decrease the workload to heart.","pyqMatches":[{"year":"2014","no":374,"q":"Hypertrophy is","o":["Increase in cell number","Increase in cell size","Decrease in cell number","Decrease in cell size"],"a":1,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":378,"q":"Hypertrophy is","o":["Increase in cell number","Increase in cell size","Decrease in cell number","Decrease in cell size"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6191, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 31, '{"id":6191,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":31,"q":"Physiological hyperplasia and hypertrophy are seen simultaneously in -","o":["Uterus in pregnancy","Skeletal muscle in atheleteas","Breast at puberty","a and c"],"a":3,"e":"Ans. is ''a > c'' i.e., Uterus in pregnancy > Breast at puberty Physiological hypertrophy and hyperplasia * Examples of physiologically increased growth of tissues include : - - Skeletal muscle hypertrophy in atheletes, both in the skeletal muscle of limbs (as a response to increased muscle activity) and in left ventricle of heart (as a response to sustained outflow resistance). - Hyperplasia of bone marrow cells producing red blood cells in individuals living at high altitude; this is stimulated by increased production of the erythropoietin. - Hyperplasia of breast at puberty, and in pregnancy and lactation, under the influence of estrogen, progesterone, prolactin and human placental lactogen. - Hypertrophy and hyperplasia of uterine smooth muscle in pregnancy, stimulated by estrogen. - Thyroid hyperplasia as a consequence of the increased metabolic demand of puberty and pregnancy. For option ''c'' - \"Hormonal hyperplasia is well illustrated by the proliferation of the glandular epithelium of the female breast at puberty and during pregnancy, usually accompanied by enlargement (hypertrophy) of the glandular epithelial cell\" - * However, I am not sure about this statement of Robbin''s, as no other text book has mentioned that breast at puberty undergo both hyperplasia and hypertrophy.","pyqMatches":[{"year":"2016","no":355,"q":"Physiological hyperplasia and hypertrophy are seen simultaneously in","o":["Uterus in pregnancy","Skeletal muscle in atheleteas","Breast at puberty","a and c"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6192, 'Pathology', 'Organ System Pathology', 'Hard', 'Pathology', 32, '{"id":6192,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Hard","source":"Pathology","sourceNo":32,"q":"The sign of reversible injury in a case of alcoholic liver disease -","o":["Loss of cell membrane","Nuclear karyolysis","Cytoplasmic vacuole","Pyknosis"],"a":2,"e":"Ans. is ''c'' i.e., Cytoplasmic vacuole o Fatty changes occur in alcoholic steatosis (fatty liver). It is manifested by appearence of lipid vacuole in the cytoplasm, which is a sign of reversible injury. o Other three options (loss of cell membrane, nuclear karyolysis and pyknosis) are signs of irreversible injury","pyqMatches":[{"year":"2013","no":381,"q":"The sign of reversible injury in a case of alcoholic liver disease","o":["Loss of cell membrane","Nuclear karyolysis","Cytoplasmic vacuole","Pyknosis"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6193, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 33, '{"id":6193,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":33,"q":"In cell death, myelin figures, are derived from-","o":["Nucleus","Cell membrane","Cytoplasm","Mitochondria"],"a":1,"e":"Ans. is ''b'' i.e., Cell membrane Myeline figures are cytoplasmic bodies composed of concentric whorls of membranes, derived from damage cell membrane. Myelin figures appear during reversible injury but they are more pronounced in irreversible injury.","pyqMatches":[{"year":"2015","no":382,"q":"In cell death, myelin figures, are derived from","o":["Nucleus","Cell membrane","Cytoplasm","Mitochondria"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6194, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 34, '{"id":6194,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":34,"q":"Enzyme that protects the brain from free radical injury is -","o":["Myeloperoxidase","Superoxide dismutase","MAO","Hydroxylase"],"a":1,"e":"Ans. is ''b'' i.e., Superoxide dismutase Antioxidant mechanisms Cells have multiple mechanisms to remove free radicals and thereby minimizing injury. Several nonenzymatic and enzymatic systems contribute to the inactivation of free radical reactions. A. Non-enzymatic system o Antioxidants (Vit ''E'', Vit A, Vit C, glutathione and Cysteine) block the initiation of free radical formation and inactivate free radicals. o Tissue proteins (transferrin, ferritin, lactoferrin, and ceruloplasmin). As already explained, iron and copper can catalyze the formation of free radicals, these transport and storage proteins decrease the reactive free iron and copper, thereby minimizing the free radical formation. B. Enzymatic system o A series of enzymes act as free radical-scavenging systems and breakdown hydrogen peroxide and superoxide anion.","pyqMatches":[{"year":"2014","no":380,"q":"Enzyme that protects the brain from free radical injury is","o":["Myeloperoxidase","Superoxide dismutase","MAO","Hydroxylase"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6195, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 35, '{"id":6195,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":35,"q":"MI is a type of -","o":["Coagulative necrosis","Liquefactive necrosis","Caseous necrosis","Fat necrosis"],"a":0,"e":"Ans. is ''a'' i.e., Coagulative necrosis Coagulative necrosis * This is most common type of necrosis. * This type of necrosis is most frequently caused by sudden cessation of blood flow (ischemia) in organs such as heart (MI), Kidney (ATN), adrenal gland, and spleen. Note : Brain is the only exception, i.e.,. It is the only solid organ in which ischemia leads to liquifactive necrosis not coagulative necrosis. * It is also seen with other types of injury e.g., liver necrosis in viral hepatitis, Coagulative necrosis of skin after burns (Thermal injury). * Why there is predominant protein denaturation and no enzymatic digestion ? Hypoxia causes intracellular acidosis (has been explained earlier) — > .t pH results in denaturation ofproteins which includes not only structural proteins hut also enzymes So, there is no enzymatic digestion. o The necrotic cells retain their cellular outline for several days. Liquefactive necrosis * It is the necrotic degradation of tissue that rapidly undergo softening and liquefaction because of the action of hydrolytic enzymes. * It occurs after * It occurs after 1.Infection i.e., suppurative inflammation (most common). 2.Ischemic necrosis in brain. Note : Brain lacks any substantial supportive stroma, so ischemic necrosis in brain is liquifactive unlike other organs where it is coagulative. * Mechanism of liquefactive necrosis —> Microbes stimulates accumulation of inflammatory cells and these cells release lysosomal enzymes. Caseous necrosis * It is a variant of coagulative necrosis. * It is most commonly encountered when cell death is attributable to certain organisms e.g., mycobacterium tuberculosis (TB) and fungi (Histoplasma, Coccidioidomycosis). Why is it called caseous necrosis, not coagulative necrosis ? * In contrast to coagulative necrosis where tissue architecture is maintained, in caseous necrosis, the tissue architecture is completely obliterated. So, it has been called caseous because of its cheesy white appearance of the area of necrosis.","pyqMatches":[{"year":"2015","no":391,"q":"MI is a type of","o":["Coagulative necrosis","Liquefactive necrosis","Caseous necrosis","Fat necrosis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6196, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 36, '{"id":6196,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":36,"q":"Fat necrosis is common in -","o":["Omentum","Breast","Retroperitoneal fat","All of the above"],"a":3,"e":"There are 2 Types of Fat Necrosis","pyqMatches":[{"year":"2015","no":387,"q":"Fat necrosis is common in","o":["Omentum","Breast","Retroperitoneal fat","All of the above"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6197, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 37, '{"id":6197,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":37,"q":"Programmed cell death is known as-","o":["Cytolysis","Apoptosis","Necrosis","Proptosis"],"a":1,"e":"Ans. is ''b'' i.e., Apoptosis * Programmed cell death is apoptosis. * But remember this important fact that not all apoptosis are programmed cell death (read text below) Apoptosis * Apoptosis is pathway of cell death that is induced by a tightly regulated intracellular program in which cell destined to die activate enzymes that degrade the cell''s own nuclear DNA, and nuclear & cytoplasmic proteins. * Apoptosis generally involves single cells in contrast to necrosis that usually involve a group of cells. o Apoptosis may be of two types ? A. Physiological (most of the time) Programmed cell death. B. Pathological Unprogrammed cell death. A.Physiological apoptosis * Death by apoptosis is a normal phenomenon that serves to eliminate cells that are no longer needed. o It is important in the following physiologic situation :?","pyqMatches":[{"year":"2015","no":380,"q":"Programmed cell death is known as","o":["Cytolysis","Apoptosis","Necrosis","Proptosis"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6198, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 38, '{"id":6198,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":38,"q":"In apoptosis, cytochrome C acts through -","o":["Apaf 1","Bcl-2","FADD","TNF"],"a":0,"e":"Ans. is ''a'' i.e., Apaf 1 One of these proteins is cytochrome c, well known for its role in mitochondrial respiration. In the cytosol, cytochrome C binds to a protein called Apaf-1 (apoptosis activating factor-1), and the complex activates caspase-9. (Bc1-2 and Bcl-x may also directly inhibit Apaf-1 activation, and their loss from cells may permit activation of Apaf-1).","pyqMatches":[{"year":"2012","no":417,"q":"In apoptosis, cytochrome C acts through","o":["Apaf 1","Bcl-2","FADD","TNF"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6199, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 39, '{"id":6199,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":39,"q":"Which is activated for nuclear fragmentation in apoptosis -","o":["Caspases","Apaf - 1","Oxygen free radicals","All"],"a":0,"e":"Ans is ''a'' i.e., Caspases Caspases and endonuclease cause chromatin fragmentation in apoptosis. They are inactive, so first they should be activated. Cytochrome ''c'' binds with Apaf-1 and this complex activates caspases. Caspases cause fragmentation of chromatin and also activate endonuclease. About option ''b'' Though Apaf-1 helps in activation of caspases, it has no role in chromatin framentation and It does not have two seprate forms active or inactive. It just forms complex with cytochrome ''C'' to activate caspases.","pyqMatches":[{"year":"2015","no":381,"q":"Which is activated for nuclear fragmentation in apoptosis","o":["Caspases","Apaf - 1","Oxygen free radicals","All"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6200, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 40, '{"id":6200,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":40,"q":"In apoptosis which is/are involved -","o":["Apaf-1","Bc12","Caspases","All"],"a":3,"e":"Ans. is ''a'' i.e., Apaf-1; ''b'' i.e., BCl2; ''c'' i.e., Caspases Proapoptotic genes : Apaf-1, Cytochrome C, Bak, Bax, Bim, AIF, P53, Caspases, TNFRI, FAS (CD95), FADD, BH3 only proteins (Bim, Bid, Bad), Smac/DIABLO.","pyqMatches":[{"year":"2015","no":385,"q":"In apoptosis which is/are involved","o":["Apaf-1","Bc12","Caspases","All"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6201, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 41, '{"id":6201,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":41,"q":"Annexin Visa marker of","o":["Apoptosis","Necrosis","Artherosclerosis","Inflammation"],"a":0,"e":"Ans. is ''a'' i.e., Apoptosis o Annexin V assays provides simple and effective method to detect apoptosis at a very early stage. o This assay makes advantage of the fact that phosphatidylserine (PS) is translocated from the inner (cytoplasmic) leaflet of the plasma membrane to the outer (cell surface) leaflet soon after the induction of apoptosis and that the annexin V protein has strong specific affinity for phosphatidyl serine. o Phosphatidyl serine on the outer leaflet is available to bind labelled annexin V providing the basis for a simple staining assay. o All of the annexin proteins share the property of binding calcium and phospholipids. o Annexin V is a cause of syndrome called antiphospholipid antibody syndrome. o Annexin V normally forms a shield around certain phospholipid molecules that blocks their entry into coagulation (clotting) reactions. o In the antiphospholipid antibody syndrome; the formation of the shield is disrupted by the abnormal antibodies. Without the shield, there is an increased quantity of phospholipid molecules on cell membranes speeding up coagulation reactions and causing the abnormal blood clotting characteristic of antiphospholipid antibody syndrome.","pyqMatches":[{"year":"2014","no":372,"q":"Annexin Visa marker of","o":["Apoptosis","Necrosis","Artherosclerosis","Inflammation"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6202, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 42, '{"id":6202,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":42,"q":"Dystrophic calcification is seen in ?","o":["Milk alkali syndrome","Atheromatous plaque","Hyperparathyroidism","Vitamin A intoxication"],"a":1,"e":"Ans. is ''b'' i.e., Atheromatous plaque Dystrophic calcification * When pathological calcification takes place in dead, dying or degenerated tissue, it is called dystrophic calcification. o Calcium metabolism is not altered and serum calcium level is normal. Dystrophic calcification in dead tissues 1.In caseous necrosis of tuberculosis (most common which may be in lymph nodes) 2.Chronic abscess in liquifactive necrosis 3.Fungal granuloma 4.Infarct 5.Thrombi 6.Haematomas 7.Dead parasites- Cystecercosis/Toxoplasma Hydatid/Schistosoma 8.In fat necrosis of breast & other tissues Dystrophic calcification in degenerated tissues","pyqMatches":[{"year":"2013","no":387,"q":"Dystrophic calcification is seen in ?","o":["Milk alkali syndrome","Atheromatous plaque","Hyperparathyroidism","Vitamin A intoxication"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2016","no":357,"q":"Dystrophic calcification is seen in ?","o":["Milk alkali syndrome","Atheromatous plaque","Hyperparathyroidism","Vitamin A intoxication"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2013","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6203, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 43, '{"id":6203,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":43,"q":"Calcification of soft tissues without any distrubance of calcium metabolism is called -","o":["Ionotrophic calcification","Monotrophic calcification","Dystrophic calcification","Calcium induced calcification"],"a":2,"e":"Ans. is ''c'' i.e., Dystrophic calcification","pyqMatches":[{"year":"2014","no":376,"q":"Calcification of soft tissues without any distrubance of calcium metabolism is called","o":["Ionotrophic calcification","Monotrophic calcification","Dystrophic calcification","Calcium induced calcification"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6204, 'Pathology', 'Hematology', 'Easy', 'Pathology', 44, '{"id":6204,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":44,"q":"True about gastric lymphoma -","o":["Non Hodgkins lymphoma commonest variety","Diagnosis is made by biopsy","H-Pylori has direct relationship","All"],"a":3,"e":"Ans. is ''a'' i.e., Non Hodgkins lymphoma commonest variety; ''b'' i.e., Diagnosis is made by biopsy; `c'' i.e., H-Pylori has direct relationship Gastric lymphoma The stomach is the most common site for extranodal lymphoma. o Nearly all gastric lymphomas are B-cell lymphomas of mucosa- associated lymphoid tissue (MALT lymphoma) o Majority of cases (80%) are associated with chronic gastritis and H. Pylori infection. o The most striking evidence linking H. Pylori gastritis to MALToma is that eradication of infection by antibiotics induces durable remission with low rate of recurrence. o Gastric lymphoma represents 5% of all gastric malignancies. It is most prevalent is sixth decade of life. o Like other tumors of mature B cells, MALTomas express B-cell markers CD 19 and CD 20. They do not express CD 5, CD 10 and CD 23. o Diagnosis is made by endoscopic biopsy. o Gastric lymphomas are chemosensitive and chemotherapy alone or along with surgery is used for the treatment of gastric lymphoma. About option ''a'' o Most common variety of gastric lymphoma is NHL (MALToma). Very rarely, Hodgkin''s lymphoma may also occur in stomach.","pyqMatches":[{"year":"2014","no":470,"q":"True about gastric lymphoma","o":["Non Hodgkins lymphoma commonest variety","Diagnosis is made by biopsy","H-Pylori has direct relationship","All"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6205, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 45, '{"id":6205,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":45,"q":"Most common site of GIST is -","o":["Ileum","Esophagus","Colon","Stomach"],"a":3,"e":"Ans. is ''d'' i.e., Stomach • Stomach --> 50- 70% • Small intestine --> 20- 30% Colon & rectum -3 5- 15% Esophagus --->< 5%","pyqMatches":[{"year":"2012","no":489,"q":"Most common site of GIST is","o":["Ileum","Esophagus","Colon","Stomach"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6206, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 46, '{"id":6206,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":46,"q":"Which of the following markers is specific for gastro-intestinal stomal tumor (GIST) -","o":["CD 117","CD 34","CD 23","S-100"],"a":0,"e":"Ans. is ''a'' i.e., CD 117 lmmunohistochemistry o Following markers are present in GISTs: i) CD 117 (c kit) —>95% ii) CD 34 —> 70% iii) Smooth muscle actin 5% CD 117 (c kit) is considered the most specific marker o CD 117 (c kit) immunoreactivity is the best defining feature of GISTs distinguishing them from true smooth muscle tumors (leiomyoma) and tumors arising from neural crest. o Although CD 117 (c kit) is considered the most specific marker for GIST, it is not pathognomonic of GIST as other tumors may also express CD 117. These tumors include mast cell tumor, germ cell tumors (seminomas), leukemias, malignant melanoma, angiolipomas, and some sarcomas.","pyqMatches":[{"year":"2015","no":493,"q":"Which of the following markers is specific for gastro-intestinal stomal tumor (GIST)","o":["CD 117","CD 34","CD 23","S-100"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6207, 'Pathology', 'Cell Injury & Adaptation', 'Hard', 'Pathology', 47, '{"id":6207,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Hard","source":"Pathology","sourceNo":47,"q":"Aganglionic segment is encountered in which part of colon in case of Hirschsprung disease ?","o":["Distal to dilated segment","In Whole colon","Proximal to dilated segment","In the dilated segment"],"a":0,"e":"Ans. is ''a'' i.e., Distal to dilated segment Congenital aganglionic megcolon (Hirschsprung disease) o Hirshsprung disease a congenital disorder characterized by aganglionosis of a portion of the intestinal tract. o An intestinal segment lacks both Meissner submucosal and Auerbach myenteric plexuses. This leads to func​tional obstruction and intestinal dilation Proximal to the affected segment. o Histological findings are :- (i) Absence of ganglion cells and ganglia in the muscle wall and submucosa of the affected segment. (ii) Thickening and hypertrophy of nerve trunk. o Rectum is always affected with involvement of more proximal colon to variable extent --> most cases involve the rectum and sigmoid only. o Proximal to the aganglionic segment, the colon undergoes progressive dilation and hypertrophy. o With time, the proximal innervated colon may become massively distended --> megacolon.","pyqMatches":[{"year":"2014","no":1559,"q":"Aganglionic segment is encountered in which part of colon in case of Hirschsprung disease ?","o":["Distal to dilated segment","In Whole colon","Proximal to dilated segment","In the dilated segment"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6208, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 48, '{"id":6208,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":48,"q":"Multiple epidermoid cysts are seen in -","o":["Turcot''s syndrome","Gardner''s syndrome","Peutz-Jegher syndrome","Familial polyposis coli"],"a":1,"e":"Ans. is ''b'' i.e., Gardner''s syndrome o Gardner syndrome includes adenomatous polyps of the gastrointestinal tract, desmoid tumours, osteomas, epidermoid cysts, lipomas, dental abnormalities and periampullary carcinomas.","pyqMatches":[{"year":"2013","no":470,"q":"Multiple epidermoid cysts are seen in","o":["Turcot''s syndrome","Gardner''s syndrome","Peutz-Jegher syndrome","Familial polyposis coli"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6209, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 49, '{"id":6209,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":49,"q":"Features of Peutz-Jeghers syndrome are all except?","o":["Autosomal dominant","Mucocutaneous pigmentation","Hamartomatous polyp","High risk of malignacy"],"a":3,"e":"Ans. is ''d'' i.e., High risk of malignacy o Malignancy is rare in harmartomatous polyps of Peutz-Jeghers syndrome. Other three options are correct (see previous explanation).","pyqMatches":[{"year":"2013","no":471,"q":"Features of Peutz-Jeghers syndrome are all except?","o":["Autosomal dominant","Mucocutaneous pigmentation","Hamartomatous polyp","High risk of malignacy"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6210, 'Pathology', 'Hematology', 'Moderate', 'Pathology', 50, '{"id":6210,"subject":"Pathology","chapter":"Hematology","difficulty":"Moderate","source":"Pathology","sourceNo":50,"q":"The features of crohns disease are all except ?","o":["Lymphoid hyperplasia","Skin lesion","Transmural involvement","Crypt Abscess"],"a":0,"e":"Ans. is ''a'' i.e., Lymphoid hyperplasia Intermittent mild diarrhea, fever, abdominal pain (MC) Right lower quadrant mass, weight loss, anemia Sometimes mimics appendicitis or bowel perforation Anal complaints (fissure, fistula, abscess) – frequent Fat/vitamin malabsorption present Recurrence after surgery common Malignancy (most common cause) + with colon involvement String sign of Kantor is seen in Crohn''s Disease. Creeping fat is a feature of Crohn''s Disease.","pyqMatches":[{"year":"2016","no":1278,"q":"The features of crohns disease are all except ?","o":["Lymphoid hyperplasia","Skin lesion","Transmural involvement","Crypt Abscess"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6211, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 51, '{"id":6211,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":51,"q":"Female is affected, male is not. Disease is autosomal dominant, what is the chance in children?","o":["50% affected","25% affected","75% affected","All affected"],"a":0,"e":"Ans. is ''a'' i.e., 50% Affected If one of the parent (mother or father) is affected in autosomal dominant disorder, every child has 50% of chance of having the disease and 50% of chance not having the disease.","pyqMatches":[{"year":"2012","no":434,"q":"Female is affected, male is not. Disease is autosomal dominant, what is the chance in children?","o":["50% affected","25% affected","75% affected","All affected"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6212, 'Pathology', 'Genetic Disorders', 'Easy', 'Pathology', 52, '{"id":6212,"subject":"Pathology","chapter":"Genetic Disorders","difficulty":"Easy","source":"Pathology","sourceNo":52,"q":"Chance of having cystic fibrosis if only one parent is affected and other is normal -","o":["25%","50%","70%","80%"],"a":1,"e":"Ans. is ''b'' i.e., 50% Cystic fibrosis is an autosomal recessive disorder. Thus, in the given scenorio (question) there are two possibilities:-1) One parent affected and the other is genotypically normal. In this condition, no child will be affected and all will be carrier. 2) One parent affected and the other is genotypically carrier (normal phenotypically). In this condition, 50% of child will be affected","pyqMatches":[{"year":"2013","no":423,"q":"Chance of having cystic fibrosis if only one parent is affected and other is normal","o":["25%","50%","70%","80%"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6213, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 53, '{"id":6213,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":53,"q":"True statement about inheritence of an X linked recessive trait is -","o":["50% of boys of carrier mother are affected","50% of girls of diseased father are carrier","Father transmits disease to the son","Mother transmits the disease to the daughter"],"a":0,"e":"Ans. is ''a'' i.e., 50% of boys of carrier mother are affected all X-linked disorders are X-linked recessive. As male has only one X-chromosome, the male with affected gene on X-chromosome will always manifest the disease. On the other hand, female has 2 X-chromosomes, heterozyogous female will be carrier because of expression of normal allel on the other X-chromosome. 50% boys of the carrier mother will be affected. Father will not transmitt the disease to son as boys do not inherit X- chromosome from father.","pyqMatches":[{"year":"2012","no":430,"q":"True statement about inheritence of an X linked recessive trait is","o":["50% of boys of carrier mother are affected","50% of girls of diseased father are carrier","Father transmits disease to the son","Mother transmits the disease to the daughter"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6214, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 54, '{"id":6214,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":54,"q":"Normal female, whose father was color blind married a normal man. What are the chances of color blindness in son -","o":["25%","50%","75%","No chance"],"a":1,"e":"Ans. is ''b'' i.e., 50% * Father of the female was color blind; that means she has received mutated X-chromosome from her father and she is carrier for colour blindness. If this female gives birth to a male child there is 50% chance that he will get the disease because the carrier female is carrying one normal X-chromosome and one mutated X-chromosome. Note ? * Here I would like to mention one important fact that this question has been asked specifically for the chances of disease in a son. The question can be framed in following different ways. i) How many children will have the disease. ii) What are the chances of son getting the disease. iii) What are the chances of daughter getting the disease. iv) How many son will have the disease. * Thus :? i) 25% of children will have disease. ii) 50% of son (1 out of 2) will have disease. iii) No daughter will have disease. iv) Chances that son will have disease is 50% (1 out of 2 male child can get the disease).","pyqMatches":[{"year":"2013","no":425,"q":"Normal female, whose father was color blind married a normal man. What are the chances of color blindness in son","o":["25%","50%","75%","No chance"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6215, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 55, '{"id":6215,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":55,"q":"The inheritance pattern of familial Retinoblastomas is -","o":["Autosomal recessive","Autosomal dominant","X-linked dominant","X-linked recessive"],"a":1,"e":"Ans. is ''b'' i.e., Autosomal dominant Huntington disease Neurofibro-matosis Myotonic dys-trohy Tuberous scle-rosis Retinoblastoma","pyqMatches":[{"year":"2014","no":420,"q":"The inheritance pattern of familial Retinoblastomas is","o":["Autosomal recessive","Autosomal dominant","X-linked dominant","X-linked recessive"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6216, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 56, '{"id":6216,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":56,"q":"Male to male transmission is seen in -","o":["Autosomal dominant diseases","Autosomal recessive","X-linked dominant","M itochondrial disease"],"a":0,"e":"Ans. is ''a'' i.e., Autosomal dominant disease X chromosome is not transmitted from father to son (option c is excluded) and mitochondrial disorders are always maternally inherited (option d is excluded). Autosomal recessive disorder can be transmitted from father to son, but only if the mother is also affected or at least she is carrier. If only male is affected, autosomal recessive disorder cannot be transmitted to son. Autosomal dominant disorder can be transmitted in any direction :- From father to son or daughter. From mother to son or daughter.","pyqMatches":[{"year":"2012","no":433,"q":"Male to male transmission is seen in","o":["Autosomal dominant diseases","Autosomal recessive","X-linked dominant","M itochondrial disease"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6217, 'Pathology', 'Genetic Disorders', 'Moderate', 'Pathology', 57, '{"id":6217,"subject":"Pathology","chapter":"Genetic Disorders","difficulty":"Moderate","source":"Pathology","sourceNo":57,"q":"Single gene disorder which does not follow mendelian inheritance -","o":["Sickle cell anemia","Down syndrome","Fragile X-syndrome","Retinoblastoma"],"a":2,"e":"Ans. is ''c'' i.e., Fragile X-Synd. Transmission of certain single-gene disorders does not follow classical mendelian principles. This group of disorder can be classified into following categories ?","pyqMatches":[{"year":"2016","no":1393,"q":"Single gene disorder which does not follow mendelian inheritance","o":["Sickle cell anemia","Down syndrome","Fragile X-syndrome","Retinoblastoma"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6218, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 58, '{"id":6218,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":58,"q":"Transport of lipids from the intestine to other tissues is by -","o":["Chylomicrons","LDL","HDL","VI DL"],"a":0,"e":"Ans. is ''a'' i.e., Chylomicrons Transport of lipids o There are two pathways of lipid transport in the body ?","pyqMatches":[{"year":"2015","no":317,"q":"Transport of lipids from the intestine to other tissues is by","o":["Chylomicrons","LDL","HDL","VI DL"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6219, 'Pathology', 'Hematology', 'Moderate', 'Pathology', 59, '{"id":6219,"subject":"Pathology","chapter":"Hematology","difficulty":"Moderate","source":"Pathology","sourceNo":59,"q":"Which is not a feature of Downs syndrome","o":["Clinodactyly","Pigmented birth marks","Hypotonia","Respiratory tract Infections"],"a":1,"e":"Ans. is ''b'' i.e., Pigmented birth marks Other clinical features include :? 1) General :- Mental retardation, short stature 2) Cranio-facial Brachycephaly, epicanthic fold, protruding tongue, small ears, upward sloping palpebral fissures (Mongoloid slant), strabismus, nystagmus, Brushfied spots in iris. 3) Limbs :- Fifth finger clinodactyly, single palmar crease (simian crease), wide gap between first and second toes (sandle gap). 4) Congenital heart disease :- Common AV canal, ASD (most common), VSD, PDA, fallot tetralogy. 5) GIT :- Anal atresia, Duodenal atresia, Hirschsprung disease, annular pancreas. 6) Increased incidence of leukemia (1%). Leukemias common are ALL (most common), AML (M7-AML) transient myeloproliferative disorders, and Juvenil CML.","pyqMatches":[{"year":"2014","no":428,"q":"Which is not a feature of Downs syndrome","o":["Clinodactyly","Pigmented birth marks","Hypotonia","Respiratory tract Infections"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6220, 'Pathology', 'Hematology', 'Easy', 'Pathology', 60, '{"id":6220,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":60,"q":"Following injury to a blood vessel, immediate haemostasis is achieved by -","o":["Fibrin deposition","Vasoconstriction","Platelet adhesion","Thrombosis"],"a":1,"e":"Ans. is ''b'' i.e., Vasoconstriction Hemostasis * Hemostasis is a physiological process where by bleeding is halted, thus protecting the integrity of the vascular system after tissue injury. * It is responsible for minimizing blood loss. * It is commonly referred to as stoppage of bleeding. The hemostatic mechanisms have several functions : ? * l. Maintain blood in fluid state while circulating within the vascular system. * Arrest bleeding at the site of injury by formation of hemostatic plug. * Ensure the removal of hemostatic plug when healing is complete. The components of normal hemostasis include : ? - Blood vessels (endothelium) - Platelets - Plasma coagulation factors and their inhibitors. - Fibrinolytic system. When a blood vessel is injured, several steps occur in hemostasis at the site of injury : ? Vasoconstriction * After initial injury, there is a brief period arteriolar vasoconstriction, minimizing vessel diameter and slowing bleeding. * This is due to reflex neurogenic mechanism and augmented by a potent endothelium derived vasoconstrictor endothelin. * However this effect is transient, bleeding would resume if there will no activation of platelet and coagulation system. Primary hemostasis * Endothelial injury exposes highly thrombogenic subendothelial extracellular matrix to bind (adhere) with collegen of ECM. * Binding of platelets activates these cells and platelets release secretory granules. * These secretory products (from secretory granules) recruite additional platelets to (platelet plug). C. Secondary hemostasis * Coagulation system is activated and thrombin is generated. * Thrombin converts fibrinogen to fibrin. * Ultimately these events forms an ireversibly fused mass of platelets, thrombin RBCs and fibrinogen —> Definitive secondary hemostatic plug. D. Repair of vessels and dissolution of clot * The clot attracts and stimulates the growth of fibroblast and smooth muscle cells within the vessel wall, and begins repair process. * At this stage fibrinolytic system is also activated, resulting in dissolution of the clot.","pyqMatches":[{"year":"2012","no":424,"q":"Following injury to a blood vessel, immediate haemostasis is achieved by","o":["Fibrin deposition","Vasoconstriction","Platelet adhesion","Thrombosis"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6221, 'Pathology', 'Hematology', 'Easy', 'Pathology', 61, '{"id":6221,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":61,"q":"Lines of Zahn occur in -","o":["Postmortem clot","Infarct","Embolus","Coralline thrombus"],"a":3,"e":"Ans. is ''d'' i.e., Coralline thrombus It is seen in Primary platelet thrombi.","pyqMatches":[{"year":"2012","no":420,"q":"Lines of Zahn occur in","o":["Postmortem clot","Infarct","Embolus","Coralline thrombus"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6222, 'Pathology', 'Hematology', 'Easy', 'Pathology', 62, '{"id":6222,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":62,"q":"Anemia with reticulocytosis is seen in -","o":["Hemolysis","Iron deficiency anemia","Vitamin B12 deficiency","Aplastic anemia"],"a":0,"e":"Ans. is ''a'' i.e., Hemolysis Conditions Acute blood loss or hemorrhage Postsplenectomy Microangiopathic anemia Autoimmune hemolytic anemia Hemoglobulinopathy (Sickle cell anemia and thalassemia) Post anemia treatment like folate supplementation, iron supplementation & vitamin B12,supplementation","pyqMatches":[{"year":"2013","no":455,"q":"Anemia with reticulocytosis is seen in","o":["Hemolysis","Iron deficiency anemia","Vitamin B12 deficiency","Aplastic anemia"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6223, 'Pathology', 'Hematology', 'Easy', 'Pathology', 63, '{"id":6223,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":63,"q":"Intravascular hemolysis occurs in -","o":["Hereditary spherocytosis","Acute G6PD","Sickle cell ds","b and c"],"a":3,"e":"Ans. is ''b'' i.e., Acute G6PD; ''c'' i.e., Sickle cell dis Extravascular hemolysis Hereditary spherocytosis Thalassemia Sickle cell anemia Autoimmune hemolytic anemia 3 Drug induced immune hemolytic anemia G-6-PD deficiency Intravascular hemolysis Paroxysmal nocturnal hemoglobinuria o G-6-PD deficiency Clostridial toxin Falciparum malaria Mechanical injury to red cells Defective cardiac valves Thrombin in microcirculation Sickle cell anemia (minor) Note : - In G-6-PD deficiency both extravascular and intravascular hemolysis occur. In Sickle cell anemia, usually there is extravascular hemolysis but intravascular hemolysis can also occur.","pyqMatches":[{"year":"2012","no":479,"q":"Intravascular hemolysis occurs in","o":["Hereditary spherocytosis","Acute G6PD","Sickle cell ds","b and c"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6224, 'Pathology', 'Hematology', 'Easy', 'Pathology', 64, '{"id":6224,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":64,"q":"Maximum spherocytes is seen in -","o":["Autoimmune haemolytic anemia","Vit B12 deficiency","Aplastic anemia","None"],"a":0,"e":"Ans. is ''a'' i.e., Autoimmune hemolytic anemia Most common cause of spherocytes is immunehemolytic anemia.","pyqMatches":[{"year":"2012","no":484,"q":"Maximum spherocytes is seen in","o":["Autoimmune haemolytic anemia","Vit B12 deficiency","Aplastic anemia","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6225, 'Pathology', 'Hematology', 'Easy', 'Pathology', 65, '{"id":6225,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":65,"q":"The primary defect which leads to sickle cell anemia is -","o":["An abnormality in porphyrin part of hemoglobin","Replacement of glutamate by valine in n-chain of HbA","A nonsence mutation in the I3-chain of HbA","Substitution of valine by glutamate in the a-chain of HbA"],"a":1,"e":"Ans. is ''b'' i.e., Replacement of glutamate by valine in 13 chain of HBA Sickle cell anemia Sickle cell anemia is a hereditary hemoglobinopathy, i.e., the type of disease characterized by production of defective hemoglobin. Sickle cell anemia results from mutation in 13-globin gene. It is caused by a point mutation at the sixth position of the f3-globin chain leading to subsitution of a valine residue for a glutamic acid residue resulting in sickle hemoglobin (HbS). Sickle cell anemia is an autosomal recessive disorder. o If an individual is homozygous for the sickle cell mutation, almost all the hemoglobin in the red cell is HbS. o In heterozyogotes, only about 40% of the hemoglobin is HbS, the remainder being normal hemoglobins.","pyqMatches":[{"year":"2012","no":478,"q":"The primary defect which leads to sickle cell anemia is","o":["An abnormality in porphyrin part of hemoglobin","Replacement of glutamate by valine in n-chain of HbA","A nonsence mutation in the I3-chain of HbA","Substitution of valine by glutamate in the a-chain of HbA"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6226, 'Pathology', 'Hematology', 'Moderate', 'Pathology', 66, '{"id":6226,"subject":"Pathology","chapter":"Hematology","difficulty":"Moderate","source":"Pathology","sourceNo":66,"q":"Which is not a feature of paroxysmal nocturnal hemoglobinuria -","o":["Increased LAP score","Thrombosis","Thrombocytopenia","Hemolysis"],"a":0,"e":"Ans. is ''a'' i.e., Increased LAP score Clinical features of PNH A. Intravascular hemolysis * The main feature of PNH is increased intravascular hemolysis that results in - Hemoglobinemia Increased urine urobilinogen Hemoglobinuria Decreased serum haptoglobin Hemosiderinuria Increased serum LDH Increased serum bilirubin The hemolysis is paroxysmal and usually occurs in the night because during sleep the pH of blood gets slightly reduced and acidic medium leads to activation of the complement. B. Thrombosis In PNH there is epsodic thrombosis due to absence of CD-59 on platelets, this results in externilization of phosphotidylserine, a site for prothrombinase complexes and thus increase the propensity for thrombosis. * Intrabdominal veins are the most common sites of thrombosis that may result in Budd chiary syndrome due to hepatic vein thrombosis. C. Other features Thrombocytopenia Granulocytopenia * Decreased LAP score * Normoblastic hyperplasia of bone marrow * PNH patients are also at increased risk for developing acute myelogenous leukemia and aplastic anemia.","pyqMatches":[{"year":"2013","no":451,"q":"Which is not a feature of paroxysmal nocturnal hemoglobinuria","o":["Increased LAP score","Thrombosis","Thrombocytopenia","Hemolysis"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6227, 'Pathology', 'Hematology', 'Easy', 'Pathology', 67, '{"id":6227,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":67,"q":"Cold agglutinin is -","o":["IgG","IgM","IgA","IgD"],"a":1,"e":"Ans. is ''b'' i.e., IgM Cold agglutinin hemolytic anemia This form of hemolytic anemia is caused by cold agglutinin IgM antibodies. Antibodies react with RBC at 0° to 4°C. Both intravascular and extravascular hemolysis may occur. IgM antibody bind to RBC and fix complement on RBC before complement mediated hemolysis occur. This transient reaction with IgM deposit C3b on RBC. C3b acts as an opsonin is that enhances the phagocytosis of RBCs in mononuclear phagocytic system of liver and spleen → extravascular hemolysis. However if IgM remains attached to RBC, sustained activation of complement results in formation of large amount of membrane - attack complex that destroys RBC directly --> Intravascular hemolysis. Causes of cold agglutinin immunohemolytic anemia : - Mycoplasma infection, I MN, CMV, Influenza, HIV, Malignant lymphoma","pyqMatches":[{"year":"2012","no":482,"q":"Cold agglutinin is","o":["IgG","IgM","IgA","IgD"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6228, 'Pathology', 'Hematology', 'Moderate', 'Pathology', 68, '{"id":6228,"subject":"Pathology","chapter":"Hematology","difficulty":"Moderate","source":"Pathology","sourceNo":68,"q":"Response to iron in iron deficiency anemia is denoted by-","o":["Restoration of enzymes","Reticulocytosis","Increase in iron binding capacity","Increase in hemoglobin"],"a":1,"e":"Ans. is ''b'' i.e., Reticulocytosis Response to iron therapy o When specific iron therapy is given, patients often show rapid subjective improvement, with disappearance or marked diminution of fatigue, lassitude, and other non-specific symptoms. This response may occur before any improvment in anemia is observed. The earliest hematological evidence of recovery is increase reticulocytes and their hemoglobin content. The reticulocytes attain a maximal value on the 5th to 10th day after institution of therapy and thereafter gradually return to normal. The reticulocyte response may not be detectable in mild iron deficiency anemia. The blood hemoglobin level is the most accurate measure of the degree of anemia in iron deficiency anemia. During the response to therapy, the red cell count may increase temporarily to values above normal, but the hemoglobin value lags behind. The red cell indices may remain abnormal for some time after the normal hemoglobin level is restored. As recovery occurs, a normocytic cell population gradually replaces the microcytic population; and one of the early signs of response to therapy is an increase in RBW from pretreatment level. When treatment is fully effective, hemoglobin reaches normal levels by 2 months after therapy is initiated, regard​less of starting values. Of the epithelial lesions in iron deficiency, those affecting the tongue and nails are the most responsive to treatment.","pyqMatches":[{"year":"2013","no":463,"q":"Response to iron in iron deficiency anemia is denoted by","o":["Restoration of enzymes","Reticulocytosis","Increase in iron binding capacity","Increase in hemoglobin"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6229, 'Pathology', 'Hematology', 'Easy', 'Pathology', 69, '{"id":6229,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":69,"q":"Megaloblastic anemia is seen in ?","o":["ileal resection","Crohn''s disease","Intestinal lymphatic ectasia","a and b"],"a":3,"e":"Ans. is ''a'' i.e., ileal resection ''b'' i.e., Crohn''s disease","pyqMatches":[{"year":"2013","no":1313,"q":"Megaloblastic anemia is seen in ?","o":["ileal resection","Crohn''s disease","Intestinal lymphatic ectasia","a and b"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6230, 'Pathology', 'Hematology', 'Easy', 'Pathology', 70, '{"id":6230,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":70,"q":"The anaemia associated with leukaemia is ?","o":["Iron deficiency","Megaloblastic type","Myelophthisic type","All of above"],"a":2,"e":"Ans. is ''c'' i.e., Myelophthisis type Myelophthisic anemia Space - occupying lesions that destroy significant amount of bone marrow or disturb the marrow architecture, depress its productive capacity. This form of anemia is referred to as myelophthisic anemia. Characteristically, immature erythroid and myeloid progenitors appears in the peripheral blood —> Leukoerythroblastosis. Causes are Metastatic cancer (M.C. cause) Granulomatous disease infiltrating bone marrow. Myeloproliferative disorders (such as myeloid leukemia) Myelofibrosis","pyqMatches":[{"year":"2012","no":483,"q":"The anaemia associated with leukaemia is ?","o":["Iron deficiency","Megaloblastic type","Myelophthisic type","All of above"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6231, 'Pathology', 'Hematology', 'Easy', 'Pathology', 71, '{"id":6231,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":71,"q":"Schistocyte is/are found in -","o":["TTP","DIC","Severe iron deficiency","All"],"a":3,"e":"Ans. is all Schistocytes A schistocyte is defined as an irregularly shaped erythrocyte fragment caused by mechanical trauma or an intrinsic abnormality of erythrocytes. Schistocytes : Mechanisms and Diseases Shearing by fibrin strands: Microangiopathic hemolytic anemia Disseminated intravascular coagulation Hemangiosarcoma o Glomerulonephritis o Myelofibrosis Hemolytic uremic syndrome Hyperspleenism Turbulent blood flow Congestive heart failure o Valvular stenosis Caval syndrome in heart worm disease Hemangiosarcoma Intrinsic abnormalities Chronic doxorubicin toxicosis evere iron deficiency anemia Pyruvate kinase deficiency Congenital and acquired dyserythropoiesis Microangiopathic hemolytic anemia can occur in :- o External impact : March hemoglobinuria Cardiac hemolysis : Prosthetic cardiac valves Fibrin deposit in microvasculature: TTP, DIC, HUS","pyqMatches":[{"year":"2012","no":473,"q":"Schistocyte is/are found in","o":["TTP","DIC","Severe iron deficiency","All"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6232, 'Pathology', 'Hematology', 'Easy', 'Pathology', 72, '{"id":6232,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":72,"q":"Helmet cells are characteristic of anemia of?","o":["Hemolytic uremic syndrome","Polysplenia","Spherocytosis","Acanthocytosis"],"a":0,"e":"Ans. is ''a'' i.e., Hemolytic uremic syndrome Schistocytes, helment cells, triangle cells, burr cells are seen in microangiopathic hemolytic anemia (MAHA). Changes in erythrocyte morphology","pyqMatches":[{"year":"2012","no":472,"q":"Helmet cells are characteristic of anemia of?","o":["Hemolytic uremic syndrome","Polysplenia","Spherocytosis","Acanthocytosis"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6233, 'Pathology', 'Hematology', 'Moderate', 'Pathology', 73, '{"id":6233,"subject":"Pathology","chapter":"Hematology","difficulty":"Moderate","source":"Pathology","sourceNo":73,"q":"Gamma gandy bodies are seen in all except ?","o":["Cirrhosis with portal hypertension","Chronic myeloid leukemia","Sickle cell anemia","Thalassemia"],"a":3,"e":"Ans. is ''d'' i.e., Thalassemia Gandy-Gamma bodies are foci of fibrosis containing iron and calcium salts deposits on connective tissue and elastic fibres. Gandy-Gamma bodies are seen in congestive splenomegaly e.g., in sickle cell anemia, CML and liver cirrhosis.","pyqMatches":[{"year":"2016","no":438,"q":"Gamma gandy bodies are seen in all except ?","o":["Cirrhosis with portal hypertension","Chronic myeloid leukemia","Sickle cell anemia","Thalassemia"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6234, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 74, '{"id":6234,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":74,"q":"Increased permeability in acute inflammation is due to-","o":["Histamine","IL-2","TGF-P","FGF"],"a":0,"e":"Ans. is ''a'' i.e., Histamine * Formation of endothelial gaps in venules, i.e. immediate transient response is the most common mechanism causing increased vascular permeability in acute inflammation. * Mediators involved in this mechanism are :- i) Immediate (more important) : Histamine, bradykinin, leukotrienes, neuropeptide substance P. Somewhat delayed : IL-1, TNF, IFN-y","pyqMatches":[{"year":"2013","no":405,"q":"Increased permeability in acute inflammation is due to","o":["Histamine","IL-2","TGF-P","FGF"],"a":0,"source":"NEET_2013_Paper.pdf"},{"year":"2013","no":407,"q":"Increased permeability in acute inflammation is due to?","o":["Histamine","IL-2","TGF-(3","FGF"],"a":0,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":402,"q":"Increased permeability in acute inflammation is due to?","o":["Histamine","IL-2","TGF-(3","FGF"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6235, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 75, '{"id":6235,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":75,"q":"which of the following doesnot belong to the family of selectin?","o":["P selectin","L selectin","A selectin","E selectin"],"a":2,"e":"Ans. is ''c'' i.e., A selectin Leukocyte and endothelial adhesion molecules Leukocyte adhesion and transmigration are regulated largely by binding of complementary adhesion molecules on the leukocyte & endothelial surface, and by chemical mediators. Cytokines affect these processes by modulating the expression of adhesion molecules so that leukocytes can firmly adhere to endothelium. There are four molecular families of adhesion receptors.","pyqMatches":[{"year":"2012","no":422,"q":"which of the following doesnot belong to the family of selectin?","o":["P selectin","L selectin","A selectin","E selectin"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6236, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 76, '{"id":6236,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":76,"q":"Cell-matrix adhesions are mediated by?","o":["Cadherins","Integrins","Selectins","Calmodulin"],"a":1,"e":"Ans. is ''b'' i.e., Integrins Cell-matrix adhesions, are usually mediated by intergrins Cell-cell adhesions in Anchoring junctions are mediated by cadherins.","pyqMatches":[{"year":"2012","no":423,"q":"Cell-matrix adhesions are mediated by?","o":["Cadherins","Integrins","Selectins","Calmodulin"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6237, 'Pathology', 'Cell Injury & Adaptation', 'Moderate', 'Pathology', 77, '{"id":6237,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Moderate","source":"Pathology","sourceNo":77,"q":"All are true regarding transforming growth factor? p except-","o":["Proliferation for fibroblast","Proliferation of endothelial cells","Chemotaxis of fibroblasts","Activation of macrophages"],"a":3,"e":"Ans. is `d'' i.e., Activation of macrophages Also see above explanation. Growth factors and cytokines involved in regeneration and wound healing Growth factor Epidermal growth a Transforming growth factor a Heparin-binding EGF Hepatocyte growth factor/scatter factor Vascular endothelial cell growth factor (isoforms A,B,C,D) Platelet-derived growth factor (isoforms A,B,C,D) Fibroblast growth factor 1 (acidic), 2 (basic), and family Transforming growth factor 13 (isoforms 1,2, 3); other members of the family are BMPs and activin Functions Mitogenic keratinocytes and fibroblasts; stimulates keratinocyte migration and granulation tissue formation Similar to EGF; stimulates replication of hepatocytes and most epithelial cells Keratinocyte replication Enhances proliferation of hepatocytes, epithelial cells, and endothelial cells; increases cell motility, keratinocyte replication Increases vascular permeability; mitogenic for endothelial cells; angiogenesis Chemotactic for PMNs, macrophages, fibroblasts, and smooth muscle cells; activates PMNs, macrophages and fibroblasts; mitogenic for fibroblasts, endothelial cells, and smooth muscle cells; stimulates production of MMPs, fibronectin, and HA; stimulates angiogenesis and wound contraction Chemotactic for fibroblasts; mitogenic for fibroblasts and keratinocytes; stimulates keratinocyte migration, angiogenesis, wound contraction and matrix deposition Chemotactic for PMNs, macrophages, lymphocytes fibroblasts and smooth muscle cells; stimulates TIMP synthesis, angiogenesis and fibroplasia; inhibits production of MMPs and keratinocyte proliferation Keratinocyte growth Ka Fibroblasts Stimulates keratinocyte migration, proliferation factor (also called and differentiation FGF-7) Tumor necrosis factor TNF Macrophages mast cells, Activates macrophages; regulates other T lymphocytes cytokines, multiple functions","pyqMatches":[{"year":"2013","no":415,"q":"All are true regarding transforming growth factor? p except","o":["Proliferation for fibroblast","Proliferation of endothelial cells","Chemotaxis of fibroblasts","Activation of macrophages"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6238, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 78, '{"id":6238,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":78,"q":"Maximum collagen in wound healing is seen at -","o":["End of first week","End of second week","End of third week","End of 2 months"],"a":1,"e":"Ans. is ''b'' i.e., End of second week During second week there is continued accumulation of collagen and proliferation of fibroblast. Maximum collagen is seen in second week.","pyqMatches":[{"year":"2012","no":425,"q":"Maximum collagen in wound healing is seen at","o":["End of first week","End of second week","End of third week","End of 2 months"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6239, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 79, '{"id":6239,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":79,"q":"Chemotaxis is mediated by-","o":["Histamine","Leukotriene B4 and C5a","Leukotriene C4 and C3a","Bradykinin"],"a":1,"e":"Ans. is ''b'' i.e., Leukotriene B4 and C5a Chemotaxis is unidirectional locomotion of leukocytes towards the site of injury, oriented along a chemical gradient. This chemical gradient is created by substances called chemoattractants (chemotactic agents), which may be exogenous (bacterial products) or endogenous (C5a, LTB-4, IL-I, TNF, IL-8). C5a is the most powerful chemo-attractant (chemokine).","pyqMatches":[{"year":"2015","no":402,"q":"Chemotaxis is mediated by","o":["Histamine","Leukotriene B4 and C5a","Leukotriene C4 and C3a","Bradykinin"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6240, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 80, '{"id":6240,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":80,"q":"Following injection of lymphokines, the same class of immunoglobulin are produced. This is to be referred as -","o":["Group switching","Clonal selection","Hybridisation","Class switching"],"a":1,"e":"Ans. is ''b'' i.e., Clonal selection * B-cells are able to make a specific antibody against a specific antigen. * It is due to present of specific receptor on B-cells - B-cell receptor (BCR), that is usually an immunoglobulin Ig M or Ig D. * An antigen interacts with B-cell that shows best fit by virtue of its BCR. * The antigen binds to this receptor, and the B-cell is stimulated to divide and form a clone (clonal selection). * This clone of cells will become plasma cells that will secretes antibody of a particular specificity and same class. * Although, B-cells are the major source of antibodies (after their conversion into plasma cells), Helper - T cells are alsoimportant. * Helper T-cells activate B-cells by secreting cytokines (lymphokines). o In antibody formation T-cells are involved earlier than B-cells. Antigen exposure Antigen presenting cells present this antigen to helper T cells T cells are activated Secretion of lymphokine by T-cells B-cells that carry BCR specific to that antigen are, stimulated (clonal selection) B-cells proliferate and differentiate in to plasma cells Plasma cells synthesize an immunoglobulin of same specificity as that carried by the B-cell precursors Also know Class switching * Isotype or class switching is a biological process that changes an antibody from one class to another. For example from Ig M (in primary response) to Ig G (in secondary response).","pyqMatches":[{"year":"2015","no":411,"q":"Following injection of lymphokines, the same class of immunoglobulin are produced. This is to be referred as","o":["Group switching","Clonal selection","Hybridisation","Class switching"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6241, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 81, '{"id":6241,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":81,"q":"Most potent stimulator of Naive T-cells -","o":["Mature dentritic cells","Follicular dentritic cells","Macrophages","B-cell"],"a":0,"e":"Mature Dendritic cells Mature B-cells and T-cells before antigenic exposure are called naive-B and T cells respectively. Sequence of events in activation of naive T cells. Immature dendritic cells in the epidermis are called langerhans cell. These immature dendritic cells (langerhans cells) capture the antigen in the epidermis. After capturing the antigen these cells secrete cytokines. These cytokines cause loss of adhesiveness of langerhans cells. Langerhans cells separate from each other and migrate into lymphatic vessels. In lymphatic vessel, maturation of langerhans cells takes place. Then these mature langerhans dendritic cells reach to naive T cells in the lymph nodes and present antigen to these cells and activate them.","pyqMatches":[{"year":"2012","no":426,"q":"Most potent stimulator of Naive T-cells","o":["Mature dentritic cells","Follicular dentritic cells","Macrophages","B-cell"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6242, 'Pathology', 'Hematology', 'Easy', 'Pathology', 82, '{"id":6242,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":82,"q":"True about MHC-class II -","o":["Not involved in innate immunity","Cytotoxic T-cell involved","Present in nucleated cells","All"],"a":0,"e":"Ans. is ''a'' i.e., NOT involved in innate immunity o MHC I and II are part of adaptive immunity. A major function of the MHC molecule is to present the antigen to T cell that is part of adaptive immunity. Cytotoxic T cells are MHC - class I restricted. MHC class II complex is found only on cells of the immune system (class I is found on all nucleated cells and platelets.) The antigens binding with MHC II molecule are presented to CD4+ T cells. As discussed earlier, helper T cells/CD4 T cells are MHC II- restricted. B cells have both MHC class I and II complexes.","pyqMatches":[{"year":"2016","no":382,"q":"True about MHC-class II","o":["Not involved in innate immunity","Cytotoxic T-cell involved","Present in nucleated cells","All"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6243, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 83, '{"id":6243,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":83,"q":"Common variable hypogammaglobulinemia shows ?","o":["Decreased B cell count","Increased B cell count","Compliment opsinization","Neutropenia"],"a":2,"e":"Ans. is ''c'' i.e., Normal B cells Most patients with common variable immunodeficiency have normal or near-normal numbers of B cells in the blood and lymphoid tissues. These B cells, however, are not able to differentiate into plasma cells. The clinical manifestations are caused by antibody deficiency. The feature common to all patients is hypogammaglobulinemia, generally affecting all the antibody classes but sometimes only IgG.","pyqMatches":[{"year":"2012","no":427,"q":"Common variable hypogammaglobulinemia shows ?","o":["Decreased B cell count","Increased B cell count","Compliment opsinization","Neutropenia"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6244, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 84, '{"id":6244,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":84,"q":"Major fibril protein in Primary Amyloidosis is -","o":["AL","AA","Transthyretin","Procalcitonin"],"a":0,"e":"Ans. is ''a'' i.e., AL Classification of amyloidosis o The amyloid can be classified in to following two broad groups ?","pyqMatches":[{"year":"2013","no":420,"q":"Major fibril protein in Primary Amyloidosis is","o":["AL","AA","Transthyretin","Procalcitonin"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6245, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 85, '{"id":6245,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":85,"q":"Which type ofAmyloidosis is caused by mutation of the transthyretin protein ?","o":["Familial Mediterranean fever","Familial amyloidotic polyneuropathy","Dialysis associated amyloidosis","Prion protein associated amyloidosis"],"a":1,"e":"Ans. is ''b'' i.e., Familial amyloidotic polyneuropathy Transthyretin (TTR) is normal serum protein that binds and transport thyroxine and retinol. TTR can cause following types of amyloidosis :? Mutant TTR : - Mutation in TTR can cause syndrome of familial amyloidotic polyneuropathy or familial amylodotic cardiomyopathy. Wild (non-mutant) TTR : - There is no mutation of TTR and wild type TTR forms fibrils which results in senile systemic amyloidosis (senile cardiac amyloidosis).","pyqMatches":[{"year":"2012","no":429,"q":"Which type ofAmyloidosis is caused by mutation of the transthyretin protein ?","o":["Familial Mediterranean fever","Familial amyloidotic polyneuropathy","Dialysis associated amyloidosis","Prion protein associated amyloidosis"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6246, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 86, '{"id":6246,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":86,"q":"Amyloidosis is most commonly seen in ?","o":["Maturity onset DM","Type I DM","Type II DM","HTN"],"a":2,"e":"Ans. is ''c'' i.e., Type II DM The two best examples of localized amyloidosis are Alzheimer''s disease and type 2 diabetes mellitus. Localized amyloid deposition results from the production of a unique polypeptide, which contains an amyloidogenic sequence and is capable of forming a beta-pleated sheet structure necessary for these deposits to aggregate. In type 2 diabetes it is the islet amyloid polypeptide (IAPP) also known as amylin. In Alzheimer''s the unique peptide is the beta-amyloid protein (A beta).","pyqMatches":[{"year":"2012","no":428,"q":"Amyloidosis is most commonly seen in ?","o":["Maturity onset DM","Type I DM","Type II DM","HTN"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6247, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 87, '{"id":6247,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":87,"q":"Serum amyloid associated protein, found in ?","o":["Alzheimer''s disease","Chronic inflammatory states","Chronic renal failure","Malignant hypertension"],"a":1,"e":"Ans. is ''b'' i.e., Chronic inflammatory states a) Chronic inflammatory conditions like RA (most common), TB & leprosy, osteomyelitis, ankylosing spondylitis, IBD (Crohn''s disease, UC), bronchiectasis. Some tumors like Renal cell carcinoma (hypernephroma), Hodgkins lymphoma","pyqMatches":[{"year":"2015","no":409,"q":"Serum amyloid associated protein, found in ?","o":["Alzheimer''s disease","Chronic inflammatory states","Chronic renal failure","Malignant hypertension"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6248, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 88, '{"id":6248,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":88,"q":"Hamartoma is-","o":["Malignant tumor","Metastatic tissue","Development malformation","Hemorrhage in vessel"],"a":2,"e":"Ans. is ''c'' i.e., Development malformation Hamartoma A hamartoma is a benign (noncancerous) tumor-like growth consisting of a disorganized mixture of cells and tissues normally found in the area of body where the growth occurs. * For example, hamartoma of lung contains cartilage, blood vessels, bronchial type of structures and lymphoid tissues. * It is a focal development malformation that resembles a neoplasm in the tissue of origin. * But, it is not a neoplasm because it grows at the same rate as the surrounding tissues unlike neoplasm whose growth exceeds the growth of surrounding tissue. Choristoma * Choristoma is the ectopic rest of normal tissue, i.e., the normal tissue is present at a different anatomical site of the body. * For example, presence of pancreatic tissue in mucosa of small intestine. * Normally arranged tissue at a different anatomical site (ectopic site) --> Choristoma. * Abnormally arranged tissue present at normal site -Hamartoma","pyqMatches":[{"year":"2013","no":428,"q":"Hamartoma is","o":["Malignant tumor","Metastatic tissue","Development malformation","Hemorrhage in vessel"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6249, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 89, '{"id":6249,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":89,"q":"Overgrowth of a skin structure at a localised region -","o":["Hamartoma","Malignant tumor","Choriostoma","All"],"a":0,"e":"Ans. is ''a'' i.e., Hamartoma Aberrant differentiation may produce a mass of disorganized but mature specialized cells or tissue indigenous to the particular site, referred to as a hamartoma. An ectopic rest of normal tissue is called a choristoma. eg a rest of adrenal cells under the kidney capsule. When a neoplasm, benign or malignant, produces a macroscopically visible projection above a mucosal surface and projects, it is termed a polyp.","pyqMatches":[{"year":"2012","no":435,"q":"Overgrowth of a skin structure at a localised region","o":["Hamartoma","Malignant tumor","Choriostoma","All"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6250, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 90, '{"id":6250,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":90,"q":"Excessive fibrosis in tumor in called -","o":["Anaplasia","Metaplasia","Desmoplasia","Dysplasia"],"a":2,"e":"Ans. is ''c'' i.e., Desmoplasia In some tumors, parenchymal cells stimulate the formation of an abundant collagenous stroma, referred to as desmoplasia, eg scirrhous carcinoma of breast.","pyqMatches":[{"year":"2014","no":443,"q":"Excessive fibrosis in tumor in called","o":["Anaplasia","Metaplasia","Desmoplasia","Dysplasia"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6251, 'Pathology', 'Cell Injury & Adaptation', 'Moderate', 'Pathology', 91, '{"id":6251,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Moderate","source":"Pathology","sourceNo":91,"q":"When stem cells transforms to form cells characteristic of other tissues, the process is called as -","o":["De-differentiation","Re-differentiation","Trans-differentiation","Sub-differentiation"],"a":2,"e":"Ans. is ''c'' i.e., Trans-differentiation Transdifferentiation * Transdifferentiation takes place when a non-stem cell transform into a different type of cell, or when an already differentiated stem cell creates cells outside its already estabilished differentiation. * Remember very important fact that it is the non-stem cell or already differentiated stem cell (i.e. mature cell) that is transformed into other type of cell. It is not stem cell that is transforming. * Transdifferentiation is a type of metaplasia. * Then, what is the difference between transdifferentiation and metaplasia. * In Transdifferentiation only differentiated stem cell is transformed into other cell type, while in metaplasia any of the two, either stem cell or differentiated cell can transform into other cell type. * So, all transdifferentiation processes are metaplasia, but not all metaplasia are transdifferentiation. o Most likely question has been wrongly framed here, there should be non-stem cell instead of stem cell in the question. Anyways answer remains the same, as no other option is related to this type of transformation.","pyqMatches":[{"year":"2012","no":418,"q":"When stem cells transforms to form cells characteristic of other tissues, the process is called as","o":["De-differentiation","Re-differentiation","Trans-differentiation","Sub-differentiation"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6252, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 92, '{"id":6252,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":92,"q":"Carcinoma of lung, breast marker is -","o":["CEA","AFP","11CG","CA-15-3"],"a":0,"e":"Ans. is ''a'' i.e., CEA Carcinoembryonic antigen is a marker in cancer of colon, pancreas, lung, breast, and ovary.","pyqMatches":[{"year":"2012","no":439,"q":"Carcinoma of lung, breast marker is","o":["CEA","AFP","11CG","CA-15-3"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6253, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 93, '{"id":6253,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":93,"q":"AFP is raised in-","o":["Yolk sac tumor","Seminoma","Teratoma","a and c"],"a":3,"e":"Ans. is ''a'' i.e., Yolk sac tumor; ''c'' i.e., teratoma AFP is a glycoprotein synthesized normally early in fetal life by yolk sac, fetal liver and fetal GIT. It is structurally and genetically related to albumin. AFP is raised in liver cancer (hepatocellular carcinoma), lung carcinoma, pancreatic carcinoma,colon carcinoma, and non​‐ seminoma germ cell tumor of testis/ovary (yolk sac tumor/endodermal sinus tumor, embryonal carcinoma, teratoma).","pyqMatches":[{"year":"2016","no":412,"q":"AFP is raised in","o":["Yolk sac tumor","Seminoma","Teratoma","a and c"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6254, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 94, '{"id":6254,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":94,"q":"Elevated CA-125 are seen in -","o":["Abdominal TB","Ca cervix","Endometriosis","All"],"a":3,"e":"Ans. is ''a'' i.e.,Abdominal TB; ''b'' i.e., Ca cervix; ''c'' i.e., Endometriosis Elevated level of CA-125 is seen in * Epithelial ovarian Cancer * Non ovarian tumors :- Cancers of endometrium, cervix, fallopian tubes, pancreas, breast, lung and colon. * Non malignant conditions:- Pregnancy, mensturation, peritonitis, endometriosis, pelvic inflammatory disease (abdominal TB) and uterine fibroids.","pyqMatches":[{"year":"2016","no":404,"q":"Elevated CA-125 are seen in","o":["Abdominal TB","Ca cervix","Endometriosis","All"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6255, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 95, '{"id":6255,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":95,"q":"The tumor suppressor gene P53 induces cell arrest at-","o":["M phase","S - G2 phase","G1 - S phase","Go - phase"],"a":2,"e":"Ans. is ''c'' i.e., G1 - S phase Factors acting at G, S point are :? Stimulator of cycle : Cyclin D-CDK4 (phosphorylate RB gene); cyclin E-CDK-2. Inhibitors of cycle : The Cip/kip family (p21, p27, p57); INK4a/ARF family (p16 INK4a, p14 ARF, p16, p17, p18, p19","pyqMatches":[{"year":"2012","no":432,"q":"The tumor suppressor gene P53 induces cell arrest at","o":["M phase","S - G2 phase","G1 - S phase","Go - phase"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6256, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 96, '{"id":6256,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":96,"q":"Major contribution to cachexia with advanced cancer?","o":["Clathrin","Histamine","Interferon","Tumor-necrosis-factor (TNF)"],"a":3,"e":"Ans. is ''d'' i.e., Turnor-necrosis factor (TNF) Patients with cancer commonly suffer progressive loss of body fat which is accompnied by profound weakness anorexia, and anemia. This wasting syndrome is referred to as cachexia. o TNF produced by macrophages or some tumor cells is the most important mediator of cachexia.","pyqMatches":[{"year":"2015","no":434,"q":"Major contribution to cachexia with advanced cancer?","o":["Clathrin","Histamine","Interferon","Tumor-necrosis-factor (TNF)"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6257, 'Pathology', 'Hematology', 'Easy', 'Pathology', 97, '{"id":6257,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":97,"q":"Hemolytic Uremic Syndrome is characterized by ?","o":["Microangiopathic haemolytic anaemia","Positive Coomb''s test","Thrombocytopenia","a and c"],"a":3,"e":"Ans is ''a'' i.e., Microangiopathic hemolytic anemia; ''c'' i.e., Thromhocytopenia Hemolytic uremic syndrome * Hemolytic uremic syndrome is characterized by the triad of : - Anemia (microangiopathic hemolytic anemia). - Renal failure (microangiopathy of kidney involving glomerular capillaries and arterioles). - Thrombocytopenia (due to platelet consumption). * Hemolytic uremic syndrome is most common is children under 2 years of age. * It usually follows an episode of acute gastroenterities, often triggered by E coli. * The prodrome is usually of abdominal pain, diarrhoea and vomiting. * Shortly thereafter, signs and symptoms of acute hemolytic anemia, thrombocytopenia and acute renal failure ensue. o Sometimes neurological findings also occur. (But usually absent and differentiate HUS from TTP.) o Rarely HUS may follow respiratory tract infection. Etiology * Gastrointestinal infection in infants with the following organism : * E coli, Shigella dysenteriae, Streptococouus pneumoniae Hematological findings in a case of microangiopathic hemolytic anemia : * Presence of schistocytes (fragmented red cells). This is the hallmark of microangiopathic hemolytic anemia. o Neutrophil leukocytosis. * Thrombocytopenia. * Hemoglobinuria is mild to moderate with hemosiderinuria. * Blood urea and serum creatinine levels are high. * PT and APTT normal. * Elevated serum LDH","pyqMatches":[{"year":"2016","no":433,"q":"Hemolytic Uremic Syndrome is characterized by ?","o":["Microangiopathic haemolytic anaemia","Positive Coomb''s test","Thrombocytopenia","a and c"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6258, 'Pathology', 'Hematology', 'Moderate', 'Pathology', 98, '{"id":6258,"subject":"Pathology","chapter":"Hematology","difficulty":"Moderate","source":"Pathology","sourceNo":98,"q":"All are features of haemolytic uremic syndrome, except-","o":["Hyperkalemia","Anaemia","Renal microthrombi","Neuro psychiatric disturbances"],"a":3,"e":"Ans. is ''d'' i.e., neuropsychiatric manifestations Hyperkalemia is seen in hemolytic urenic syndrome as a result of renal failure. ABOUT NEUROPSYCHIATRIC MANIFESTATIONS * Neurological manifestations are used to distinguish between Hemolytic uremic syndrome and Thrombotic Throm bocytopenic Purpura. * H.U.S. is distinguished from T.T.P by the absence of neurological symptoms and the prominence of acute renal failure. * Recent studies, however have tended to blurr these clinical distinctions. Many adult patients with \"T. T.P. lack one or more of the five criteria and patients with \"HUS\" have fever and neurological dysfunction.","pyqMatches":[{"year":"2013","no":438,"q":"All are features of haemolytic uremic syndrome, except","o":["Hyperkalemia","Anaemia","Renal microthrombi","Neuro psychiatric disturbances"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6259, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 99, '{"id":6259,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":99,"q":"In DIC, following are seen except -","o":["Fibrinogen decreased","Thrombocytopenia","Normal APTT","PT elevation"],"a":2,"e":"Ans. is ''c'' i.e., Normal APTT","pyqMatches":[{"year":"2012","no":485,"q":"In DIC, following are seen except","o":["Fibrinogen decreased","Thrombocytopenia","Normal APTT","PT elevation"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6260, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 100, '{"id":6260,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":100,"q":"Shelf life of blood with CPDA -","o":["2 weeks","3 weeks","5 weeks","8 weeks"],"a":2,"e":"Ans. is ''c'' i.e., 5 weeks * Once blood is removed from the donor, it starts a sequences of in vitro changes that change its physiological properties. * Ensuring the blood and its products transfusion safe, their storage is a must. * The main aim is to minimize damage to store blood. * Addition of some additive solutions increases the viability of blood, particularly RBCs: Additive Shelf life of RBC Acid-citrate-dextrose (ACD) 21 days Citrate phosphate dextrose (CPD) 21 days Citrate phosphate dextrose-adenine (CPD-A) 35 days Saline-adenine-Glucose-Mannitol (SAG-M) 42 days","pyqMatches":[{"year":"2013","no":465,"q":"Shelf life of blood with CPDA","o":["2 weeks","3 weeks","5 weeks","8 weeks"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6261, 'Pathology', 'Infectious Diseases', 'Moderate', 'Pathology', 101, '{"id":6261,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Moderate","source":"Pathology","sourceNo":101,"q":"Not true regarding fresh frozen plasma ?","o":["Supplies major coagulation factors","ABO match not required","Should be used in replacement of factors in DIC/trauma","To be used within 30 minutes of having trauma"],"a":3,"e":"Ans. is ''d'' i.e., To be used within 30 minutes of having trauma Fresh frozen plasma contains components of the coagulation, fibrinolytic and complement systems and other proteins. FFP can be given without blood type-matched although agglutination reactions are possible, though very rare. o There is no mention of time period within which FFP should be given after trauma. The risks of FFP include disease transmission, anaphylactoid reactions, alloimmunization, and excessive intravascular volume, as well as transfusion related acute lung injury and an increase in infections","pyqMatches":[{"year":"2012","no":486,"q":"Not true regarding fresh frozen plasma ?","o":["Supplies major coagulation factors","ABO match not required","Should be used in replacement of factors in DIC/trauma","To be used within 30 minutes of having trauma"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6262, 'Pathology', 'Hematology', 'Easy', 'Pathology', 102, '{"id":6262,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":102,"q":"Starry sky appearance is seen in -","o":["Burkitts lymphoma","CIL","Diffuse large B cell lymphoma","ALCL"],"a":0,"e":"Ans. is ''a'' i.e., Burkitts lymphoma Burkitts lymphoma It includes (1) African (endemic) Burkitt lymphoma, (2) sporadic (nonendemic) Burkitt lymphoma, and (3) a subset of aggressive lymphomas occurring in individuals infected with HIV. The involved tissues are effaced by a diffuse infiltrate of intermediate-sized lymphoid cells containing round or oval nuclei with coarse chromatin, several nucleoli, and a moderate amount of faintly basophilic or amphophilic cytoplasm . The nuclear size approximates that of benign macrophages within the tumor. A high mitotic index is typical, as is apoptotic tumor cell death, accounting for the presence of numerous tissue macrophages with ingested nuclear debris. These benign macrophages are diffusely distributed among the tumor cells and have abundant clear cytoplasm, creating a characteristic \"starry sky\" pattern. All forms of Burkitt lymphoma are associated with translocations of the c-MYC gene on chromosome 8. The partner in the translocation is usually the IgH locus (t(8;14)) but may also be the ic (t(2;8)) or y (t(8;22)) light chain locus. Essentially all endemic tumors are latently infected with EBV.","pyqMatches":[{"year":"2012","no":468,"q":"Starry sky appearance is seen in","o":["Burkitts lymphoma","CIL","Diffuse large B cell lymphoma","ALCL"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6263, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 103, '{"id":6263,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":103,"q":"B ALL iS due to -","o":["T cells","Immature B cells","Immature T cells","Both T & B cells"],"a":1,"e":"Ans. is ''b'' i.e., Immature B cells In B ALL, precursor cells are arrested at stages preceding surface expression of lg. The leukemic blasts almost always express the pan B-cell molecules CD 19 and CD 10. In very early pre-B cell ALL; CD 19 is the only B cell-specific marker present. Early pre-B ALL is distinguished from late pre-B ALL by the absence of cytoplasmic IgM heavy chain in the former.","pyqMatches":[{"year":"2012","no":469,"q":"B ALL iS due to","o":["T cells","Immature B cells","Immature T cells","Both T & B cells"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6264, 'Pathology', 'Genetic Disorders', 'Easy', 'Pathology', 104, '{"id":6264,"subject":"Pathology","chapter":"Genetic Disorders","difficulty":"Easy","source":"Pathology","sourceNo":104,"q":"What is the chromosomal translocation in AML M3 -","o":["T (18,21)","T (15,17)","T (8, 21)","T (9,11)"],"a":1,"e":"Ans. is ''b'' i.e., T(15,17) Class Chromosomal abnormalities Mz t (8 : 21) M3 t (15: 17) M4 inv (16)","pyqMatches":[{"year":"2012","no":470,"q":"What is the chromosomal translocation in AML M3","o":["T (18,21)","T (15,17)","T (8, 21)","T (9,11)"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6265, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 105, '{"id":6265,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":105,"q":"Russell bodies are found in -","o":["Multiple Myeloma","Gonadal tumor","Parkinsonism","Intracranial neoplasms"],"a":0,"e":"Ans. is ''a'' i.e., Multiple Myeloma Plasma cell tumours are characterized by dysregulated synthesis and secretion of immunoglobulin. This sometimes leads to intracellular accumulation of intact or partially degraded immunoglobulins. This produces certain variants of plasma cells which are : Flame cells Characterized by presence of fiery red cytoplasm. MOTT cells Characterized by presence of multiple blue grape like cytoplasmic droplets. Besides these there are cells containing variety of other inclusions including. Fibrils Russel bodies (cytoplasmic) Crystalline rods. Dutcher bodies (nuclear)","pyqMatches":[{"year":"2012","no":475,"q":"Russell bodies are found in","o":["Multiple Myeloma","Gonadal tumor","Parkinsonism","Intracranial neoplasms"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6266, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 106, '{"id":6266,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":106,"q":"CD marker of histiocytosis is -","o":["CD1A","CD 1B","CDIC","CD1D"],"a":0,"e":"Ans. is ''a'' i.e., CD1A o CHIA is a T cell surface antigen important in dendritic cell presentation of glycolipids and lipopeptide antigens. o It is used to diagnose Langerhans cell histiocytosis.","pyqMatches":[{"year":"2012","no":476,"q":"CD marker of histiocytosis is","o":["CD1A","CD 1B","CDIC","CD1D"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6267, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 107, '{"id":6267,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":107,"q":"Dohle bodies -","o":["Dilated Endoplasmic Reticulum in Neutrophils","Mitochondria","Golgi apparatus","Lysosomes"],"a":0,"e":"Ans. is ''a'' i.e., Dilated endoplasmic reticulum in neutrophils Dohle bodies are light blue gray, bosophilic inclusions in the peripheral cytoplasm of neutrophils. o They are thought to be remnants of the rough endoplasmic reticulum containing RNA.","pyqMatches":[{"year":"2012","no":421,"q":"Dohle bodies","o":["Dilated Endoplasmic Reticulum in Neutrophils","Mitochondria","Golgi apparatus","Lysosomes"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6268, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 108, '{"id":6268,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":108,"q":"Basophillic leucocytosis occurs in -","o":["AML","ALL","CML","CLL"],"a":2,"e":"Ans. is ''c'' i.e., CML","pyqMatches":[{"year":"2016","no":443,"q":"Basophillic leucocytosis occurs in","o":["AML","ALL","CML","CLL"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6269, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 109, '{"id":6269,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":109,"q":"Nutmeg liver is seen in -","o":["Right sided heart failure","Left sided heart, failure","Increased pulmonary pressure","Decreased pulmonary pressure"],"a":0,"e":"Ans. is ''a'' i.e., Right sided heart failure o The combination of hypoperfusion and retrograde congestion (Chronic passive congestion) acts synergistically to generate centrilobular hemorrhagic necrosis. The liver takes on a variegated mottled appearance reflecting hemorrhage and necrosis in the centrilobular regions, know as nutmeg liver. o Chronic passive congestion is seen in RHF.","pyqMatches":[{"year":"2012","no":494,"q":"Nutmeg liver is seen in","o":["Right sided heart failure","Left sided heart, failure","Increased pulmonary pressure","Decreased pulmonary pressure"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6270, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 110, '{"id":6270,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":110,"q":"Histopathology of chronic hepatitis -","o":["Ball oning","Councilman bodies","Bridging necrosis","All"],"a":2,"e":"Ans. is ''c'' i.e., Bridging necrosis . Portal tracts show severe chronic inflammation with inflammatory cells extending into the liver lobules disrupting the limiting plate of hepatocytes. - Piecemeal necrosis - Portal fibrosis . Bridging necrosis - Interface hepatitis","pyqMatches":[{"year":"2012","no":496,"q":"Histopathology of chronic hepatitis","o":["Ball oning","Councilman bodies","Bridging necrosis","All"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6271, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 111, '{"id":6271,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":111,"q":"Councilman bodies are seen ill-","o":["Alcoholic cirrhosis","Wilson''s disease","Acute viral hepatitis","Autoimmune hepatitis"],"a":2,"e":"Ans. is ''c'' i.e., Acute viral hepatitis Pathological features of acute viral hepatitis 1) Panlobular infiltration of mononuclear cells This mononuclear infiltration primarily consists of —> Lymphocytes, Plasma cells, Eosinophils Inflammatory infiltrate may spill over into the adjacent parenchyma to cause necrosis of periportal hepatocytes 4 interface hepatitis, can occur in both acute and chronic hepatitis. 2) Hepatic cell damage - It consits of a) Hepatic cell necrosis - The necrosis is usually focal or centirzonal. Sometimes severe necrosis such as bridging or subacute hepatic necorsis occurs. b) Ballooning of cells - Damaged cells show diffuse swelling known as ballooning degeneration. c) Acidophilic degeneration of hepatocytes - In this single necrotic liver cell has coagulated pink cytoplasm and it shows pyknosis or karyolysis. These are called councilman bodies.","pyqMatches":[{"year":"2013","no":476,"q":"Councilman bodies are seen ill","o":["Alcoholic cirrhosis","Wilson''s disease","Acute viral hepatitis","Autoimmune hepatitis"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6272, 'Pathology', 'Cell Injury & Adaptation', 'Moderate', 'Pathology', 112, '{"id":6272,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Moderate","source":"Pathology","sourceNo":112,"q":"Pathological manifestation of chronic alcoholism include all of the following except -","o":["Piecemeal necrosis","Balloning degeneration","Microvesicular fatty changes","Central hyaline sclerosis"],"a":0,"e":"Ans. is ''a'' i.e., Piecemeal necrosis Steatosis (fatty liver) • Microvesicular fatty change • Later changes to macrovesicular fatty change Alcoholic hepatitis • Hepatocellular necrosis • Ballooning degeneration • Mallory bodies • Neutrophilic infiltration • Perivenular and perisinusoidol fibrosis —> central hyaline Alcoholic cirrhosis • Nodularity • Fibrosis","pyqMatches":[{"year":"2012","no":490,"q":"Pathological manifestation of chronic alcoholism include all of the following except","o":["Piecemeal necrosis","Balloning degeneration","Microvesicular fatty changes","Central hyaline sclerosis"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6273, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 113, '{"id":6273,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":113,"q":"Wilson''s disease is characterized by -","o":["Increased serum ceruloplasmin","Decreased copper excretion in urine","Increased copper in liver","Autosomal dominant"],"a":2,"e":"Ans. is ''c'' i.e., Increased copper in liver Diagnosis of Wilson disease The gold standard for diagnosis is liver biopsy with quantitative copper assay --> concentration of copper in a liver biopsy sample > 200 mg/g dry weight. Other tests are ? Serum ceruloplasmin level --> low o Urine copper excretion --> increased KF rings o DNA Haplotype analysis.","pyqMatches":[{"year":"2012","no":1034,"q":"Wilson''s disease is characterized by","o":["Increased serum ceruloplasmin","Decreased copper excretion in urine","Increased copper in liver","Autosomal dominant"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6274, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 114, '{"id":6274,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":114,"q":"Klatskin tumor is -","o":["Nodular type of cholangiocarcinoma","Fibrolamellar hepatocellular carcinoma","Gall bladder carcinoma","Hepatocellular carcinoma"],"a":0,"e":"Ans. is ''a'' i.e., Nodular type of cholangiocarcinoma o According to their localization, cholongiocarcinomas are classified into","pyqMatches":[{"year":"2012","no":492,"q":"Klatskin tumor is","o":["Nodular type of cholangiocarcinoma","Fibrolamellar hepatocellular carcinoma","Gall bladder carcinoma","Hepatocellular carcinoma"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6275, 'Pathology', 'Hematology', 'Easy', 'Pathology', 115, '{"id":6275,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":115,"q":"Gall stones in hemolytic anaemia are -","o":["Pigment","Mixed","Cholesterol","Any type"],"a":0,"e":"Ans. is ''a'' i.e., Pigment","pyqMatches":[{"year":"2016","no":427,"q":"Gall stones in hemolytic anaemia are","o":["Pigment","Mixed","Cholesterol","Any type"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6276, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 116, '{"id":6276,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":116,"q":"Collapse of lung is called -","o":["Emphysema","Bronchiactasis","Atelectasis","Bronchitis"],"a":2,"e":"Ans. is ''c'' i.e., Atelectasis Atelectasis (collapse) Atelectasis refers to:-","pyqMatches":[{"year":"2012","no":458,"q":"Collapse of lung is called","o":["Emphysema","Bronchiactasis","Atelectasis","Bronchitis"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6277, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 117, '{"id":6277,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":117,"q":"Curshmann''s crystals are seen in ?","o":["Bronchial asthma","Bronchiectasis","Chronic bronchitis","Wegners granulomatosis"],"a":0,"e":"Ans. is ''a'' i.e., Bronchial asthma Pathology of Asthma Gross ? * Lungs are overdistended because of overinflation and there may be small area of atelactasis. * The most striking macroscopic finding is occlusion of bronchi and bronchioles by thick tenacious mucus plugs. Histology ? * Characterized by presence of numerous eosinophils and neutrophils. Curschntan spiral - Whorls of shed epithelium in mucus plugs. Charcot -leyden crystals - Collection of crystalloids made up of eosinophilic membrane protein. The other characteristic histological finding of Asthma is collectively called Airway remodelling, it includes ? * Thickening of the basement membrane of the bronchial epithelium. * Edema and an inflammatory infiltrate in the bronchial walls with a prominence of eosinophils and mast cells. * An increase in the size of submucosal glands. * Hypertrophy of bronchial wall muscle. The \"airway remodelling\" contributes to airflow obstruction.","pyqMatches":[{"year":"2013","no":432,"q":"Curshmann''s crystals are seen in ?","o":["Bronchial asthma","Bronchiectasis","Chronic bronchitis","Wegners granulomatosis"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6278, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 118, '{"id":6278,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":118,"q":"Creola bodies are seen in -","o":["Bronchial asthma","Chronic bronchitis","Emphysema","Bronchiectatsis"],"a":0,"e":"Ans. is ''a'' i.e., Bronchial asthma Creola bodies are a histopathologic finding indicative of bronchial asthma. Found in a patient''s sputum, they are ciliated columnar cells sloughed from the bronchial mucosa of a patient with asthma. Other common findings in the sputum of asthma patients include Charcot-Leyden crystals, Curschntann''s Spirals, and eosinophils.","pyqMatches":[{"year":"2012","no":453,"q":"Creola bodies are seen in","o":["Bronchial asthma","Chronic bronchitis","Emphysema","Bronchiectatsis"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6279, 'Pathology', 'Genetic Disorders', 'Moderate', 'Pathology', 119, '{"id":6279,"subject":"Pathology","chapter":"Genetic Disorders","difficulty":"Moderate","source":"Pathology","sourceNo":119,"q":"Cystic fibrosis is associated with all except ?","o":["Infertility","Azoospermia","Nasal polyps","Renal failure"],"a":3,"e":"Ans. is d i.e., Renal failure Thick viscid plugs of mucus may also be found in the small intestine of infants. Sometimes these cause small-bowel obstruction, known as meconium ileus. Chronic sinopulmonary disease manifested by : Persistent colonization/infection with typical cystic fibrosis pathogens, including Staphylococcus aureus, non typeable Hemophilus influenzae, mucoid and nonmucoid Pseudomonas aeruginosa, Burkholderia cepacia; Chronic cough and sputum production, nasal polyps. Azoospermia and infertility are found in 95% of the males who survive to adulthood; congenital bilateral absence of the vas deferens is a frequent finding in these patients.","pyqMatches":[{"year":"2012","no":455,"q":"Cystic fibrosis is associated with all except ?","o":["Infertility","Azoospermia","Nasal polyps","Renal failure"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6280, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 120, '{"id":6280,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":120,"q":"Anthracosis is due to inhalation of-","o":["Coal dust","Asbestos","Silica dust","Berylium dust"],"a":0,"e":"Ans. is ''a'' i.e., Coal dust Coal worker''s pneumoconiosis (Black lung) Black lung disease, also known as coal worker''s pneumoconiosis (CWP), is caused by long exposure to coal dust. o Coal worker''s pneumoconiosis has following spectrum.","pyqMatches":[{"year":"2016","no":457,"q":"Anthracosis is due to inhalation of","o":["Coal dust","Asbestos","Silica dust","Berylium dust"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6281, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 121, '{"id":6281,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":121,"q":"True Statement about silicosis -","o":["Produces pleural plaque","Associated with tuberculosis","Lower lobe infiltration","All"],"a":1,"e":"Ans. is ''b'' i.e., Associated with tuberculosis Silicosis 3 Silicosis is a lung disease caused by inhalation of crystalline silicon dioxide (silica). * Currently, it is the most prevalent occupational disease in the world. * Silicosis is a slowly progressive disease, usually presenting after decades of exposure as slowly progressive nodular fibrosing pneumoconiosis. * Silica occurs in both crystalline and amorphous forms but crystalline forms are much more fibrogenic. The crystalline form are quartz, crystobalite. * Silicosis is characterized in its early stages by nodules in the upper zones of the lung. As the disease progresses these nodules may coalesce into hard collagenous scars. * Fibrotic lesions occur in the hilar lymph node and pleura. Sometimes thin sheets of calcification occur in the lymph nodes and are seen radiographically as eeg shell calcification i.e. (calcium surrounding a zone lacking calcification. * It the disease continues to progress, expansion and coalescence of lesions produce progressive massive fibrosis. o Histologically the lesions of silicosis consists of concentric layers of hyalinized collagen surrounded by a dense capsule of more condensed collagen. * Examination of the nodules by polarized microscopy reveals the birefringent silica particles. * Silicosis is associated with an increased susceptibility to T.B. It is postulated that silicosis results in depression of cell mediated immunity and the crystalline silica may inhibit the ability of pulmonary macrophages to kill phagocytosed mycobacteria. * Nodules of silicotuberculosis often display a central zone of caseation.","pyqMatches":[{"year":"2016","no":454,"q":"True Statement about silicosis","o":["Produces pleural plaque","Associated with tuberculosis","Lower lobe infiltration","All"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6282, 'Pathology', 'Hemodynamics', 'Moderate', 'Pathology', 122, '{"id":6282,"subject":"Pathology","chapter":"Hemodynamics","difficulty":"Moderate","source":"Pathology","sourceNo":122,"q":"Pulmonary infarction occurs with all except -","o":["Saddle embolus at bifurcation","Blockage of 2nd and 3rd gen end arteries","Arterioles are blocked","None"],"a":3,"e":"Ans. is ''d'' i.e., None The morphologic consequences of embolic occlusion of the pulmonary arteries depend on the size of the embolic mass and the general state of the circulation. Large emboli may impact in the main pulmonary artery or its major branches or lodge at the bifurcation as a saddle embolus. Sudden death often ensues, owing largely to the blockage of blood flow through the lungs. Death may also be caused by acute failure of the right side of the heart (acute cor pulmonale). Smaller emboli can travel out into the more peripheral vessels, where they may cause infarction. In patients with adequate cardiovascular function, the bronchial arterial supply can often sustain the lung parenchyma despite obstruction to the pulmonary arterial system. Under these circumstances, hemorrhages may occur, but there is no infarction of the underlying lung parenchyma. Only about 10% of emboli actually cause infarction. Although the underlying pulmonary architecture may be obscured by the suffusion of blood, hemorrhages are distinguished by the preservation of the pulmonary alveolar architecture; in such cases, resorption of the blood permits reconstitution of the preexisting architecture.","pyqMatches":[{"year":"2012","no":452,"q":"Pulmonary infarction occurs with all except","o":["Saddle embolus at bifurcation","Blockage of 2nd and 3rd gen end arteries","Arterioles are blocked","None"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6283, 'Pathology', 'Hemodynamics', 'Easy', 'Pathology', 123, '{"id":6283,"subject":"Pathology","chapter":"Hemodynamics","difficulty":"Easy","source":"Pathology","sourceNo":123,"q":"In the stage of Grey hepatization -","o":["WBC''s fill the alveoli","RBC''s fill the alveoli","Organisms fill the alveoli","Accumulation of fibrin"],"a":3,"e":"Ans. is ''d'' i.e., Accumulation of fibrin Pathological changes of bacterial pneumonia A.Lobar pneumonia Large confluent area of the lung or entire lobes are consolidated. The lower lobes are affected most commonly. There are four stages of the inflammatory response (Laennec''s stages) ? Stage of congestion (initial phase) The affected lobe is enlarged, heavy, dark red and congested. Cut surface exudes blood-stained frothy fluid. There is dilatation and congestion of alveolar capillaries. There are few neutrophils and numerous bacteria in the alveolar fluid. Stage of red hepatization (early consolidation) The term hepatization refers to liver-like consistency of the affected lobe on cut section. o The affected lobe is red and firm. The edema fluid of preceding stage is replaced by strands of fibrin. There is marked cellular exudate of neutrophils with extravasation of red cells. Stage of gray hepatization (late consolidation) The affected lobe is grayish brown, firm and dry. The fibrin strand are dense and more numerous. There is progressive disintigration of red cells and neutrophils. The macrophages begin to appear in the exudate. The organisms are less numerous and appear as degenerated forms. Resolution The previously solid and fibrinous constituent is liquefied by enzymatic action. Granular and fragmented strands of fibrin in the alveolar spaces are seen due to progressive enzymatic digestion. There is progressive removal of fluid content as well as cellular exudate from the air spaces, resulting in restoration of normal lung parenchyma with areation. B.Bronchopneumonia Patchy areas of red or grey consolidation, more often multilobar and frequently bilateral and basal (lower zones) because of tendency of secretions to gravitate into lower lobes. There is suppurative exudate, consisting chiefly neutrophils, filling bronchi, bronchioles and adjacent alveolar spaces. Alveolar septa thicken due to congested capillaries and leucocytic infiltration.","pyqMatches":[{"year":"2012","no":456,"q":"In the stage of Grey hepatization","o":["WBC''s fill the alveoli","RBC''s fill the alveoli","Organisms fill the alveoli","Accumulation of fibrin"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6284, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 124, '{"id":6284,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":124,"q":"Marker of small cell cancer of lung is -","o":["Chromogranin","Cytokeratin","Desmin","Vimentin"],"a":0,"e":"Ans. is ''a'' i.e., Chromogranin Small cell carcinoma contains. Polypeptide hormore e.g. PTH like peptide. Neuroendocrine markers -4 chromogranin, Synaptophysin, Leu7","pyqMatches":[{"year":"2012","no":457,"q":"Marker of small cell cancer of lung is","o":["Chromogranin","Cytokeratin","Desmin","Vimentin"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6285, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 125, '{"id":6285,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":125,"q":"Primary pleural tumor is","o":["Mesothelioma","Myxoma","Lipoma","All"],"a":0,"e":"Ans. is ''a'' i.e., Mesothelioma Pleural tumors * The pleura may be involved by primary or secondary tumors. Primary tumors * Benign --> Solitary fibrous tumor (benign fibrous mesothelioma or benign mesothelioma or pleural fibroma). * Malignant —> Malignant mesothelioma. Secondary tumors * More common than primary tumors. * Most common primary sites are lung and breast.","pyqMatches":[{"year":"2013","no":434,"q":"Primary pleural tumor is","o":["Mesothelioma","Myxoma","Lipoma","All"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6286, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 126, '{"id":6286,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":126,"q":"Bronchogenic sequestration is seen in which lobe -","o":["Left lower lobe","Right upper lobe","Left middle lobe","Left upper lobe"],"a":0,"e":"Ans. is ''a'' i.e., Left lower lobe Bronchogenic sequestration refers to the presence of a discrete mass of lung tissue without any normal connection to the airway system. Intralobar sequestrations are found most frequently in the posterior basal segment of the left lower lobe. Blood supply to the sequestered area arises not from the pulmonary arteries but from the aorta or its branches. Extralobar sequestrations are external to the lung. Found most commonly in infants as abnormal mass lesions, they may be associated with other congenital anomalies. Intralobar sequestrations are found within the lung substance and are usually associated with recurrent localized infection or bronchiectasis.","pyqMatches":[{"year":"2012","no":454,"q":"Bronchogenic sequestration is seen in which lobe","o":["Left lower lobe","Right upper lobe","Left middle lobe","Left upper lobe"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6287, 'Pathology', 'Hematology', 'Easy', 'Pathology', 127, '{"id":6287,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":127,"q":"Most common mediastinal tumor is?","o":["Neurogenic tumor","Pericardial cyst","Hernia","Teratoma"],"a":0,"e":"Ans. is ''a'' i.e., Neurogenic tumors o Overall most common mediastinal masses are neurogenic tumors (20%) followed by thymomas (19%), primary cysts (18%), lymphomas (13%) and germ cell tumors (10%). o Most of the mediastinal masses are located in the anterior mediastinum followed by the posterior (25%) and middle (19%).","pyqMatches":[{"year":"2013","no":491,"q":"Most common mediastinal tumor is?","o":["Neurogenic tumor","Pericardial cyst","Hernia","Teratoma"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6288, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 128, '{"id":6288,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":128,"q":"Podocytes are seen in -","o":["Bowman''s capsule","Proximal convoluted tubule","Distal convoluted tubule","Collecting tubule of the kidney"],"a":0,"e":"Ans. is ''a'' i.e., Bowman''s capsule The Bowman''s capsule (capsula glomeruli/glomerular capsule) is a cup-like sac at the beginning of tubular component of a nephron. A glomerulus is enclosed in the sac (Bowman''s capsule). Fluids from blood in the glomerulus are collected in Bowman''s capsule (i.e. glomerular filtrate) and further processed along the nephron to form urine. Outside the Bowman''s capsule there are two poles. Vascular pole → The side with afferent and efferent arterioles. Urinary pole → The side with proximal convuluted tubule. Inside the Bowman''s capsule, the layers are as follows, from inside to outside ? Thin layer of fenestrated endothelium Glomerular basement membrane Part of the glomerulus Visceral epithelium (Podocytes) Parietal epithelium","pyqMatches":[{"year":"2012","no":465,"q":"Podocytes are seen in","o":["Bowman''s capsule","Proximal convoluted tubule","Distal convoluted tubule","Collecting tubule of the kidney"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6289, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 129, '{"id":6289,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":129,"q":"Most common cause of nephritic syndrome in adults?","o":["Membranoproliferative glomerulonephritis","FSGN","Membranous glomerulonephritis","None"],"a":3,"e":"Ans. is None Most common cause of Nephritic syndrome is rapidly progressive glomerulonephritis (Poststreptococcal and nonstreptococcal glomerulonephritis). Membranous glomeruulonephritis is the most common cause of nephrotic syndrome (not nephritic syndrome) in adults. Minimal change disease is the most common cause of nephrotic syndrome in children. Causes of Acute Nephritic Syndrome Primary Glomerulonephritis Systemic Disease","pyqMatches":[{"year":"2012","no":464,"q":"Most common cause of nephritic syndrome in adults?","o":["Membranoproliferative glomerulonephritis","FSGN","Membranous glomerulonephritis","None"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6290, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 130, '{"id":6290,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":130,"q":"The pathogenesis of acute proliferative glomerulonephritis -","o":["Cytotoxic T-cell mediated","Immune complex mediated","Antibody mediated","Cell-mediated (Typer IV)"],"a":1,"e":"Ans. is ''b'' i.e., Immune complex mediated * Postinfectious acute proliferative glomerulonephritis is due to immune-complex mediated (Type III) hypersensitivity.","pyqMatches":[{"year":"2013","no":436,"q":"The pathogenesis of acute proliferative glomerulonephritis","o":["Cytotoxic T-cell mediated","Immune complex mediated","Antibody mediated","Cell-mediated (Typer IV)"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6291, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 131, '{"id":6291,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":131,"q":"Crescents are derived from -","o":["Epithelial cells + fibrin + macrophage","Mesangium + fibrin + macrophage","Tubule + mesangiaum + fibrin","Mesangiaum + fibrin"],"a":0,"e":"Ans. is ''a'' i.e., Epithelial cells + fibrin+macrophage Renal features in RPGN Crescent formation - crescents are forms by ? * Cells → Parietal epithelial cells + WBCs (monocytes and macrophages) * Fibrin strands → are prominent between the cellular layers in the crescents. - Rupture of GBM - Subepithelial deposits in type II RPGN - Linear deposits in the GBM in type I RPGN.","pyqMatches":[{"year":"2012","no":466,"q":"Crescents are derived from","o":["Epithelial cells + fibrin + macrophage","Mesangium + fibrin + macrophage","Tubule + mesangiaum + fibrin","Mesangiaum + fibrin"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6292, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 132, '{"id":6292,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":132,"q":"Most common cause of nephrotic syndrome in adults?","o":["Membranous glomerulonephritis","Minimal change disease","Acute GN","Focal GN"],"a":0,"e":"Ans. is ''a'' i.e., Membranous glomerulonephritis Most common cause of Nephrotic syndrome In adults → membranous glomerulonephritis In children → minimal change disease (lipoid nephrosis) Causes of Nephrotic syndrome I. Primary Glomerulonephritis V Malignancy","pyqMatches":[{"year":"2012","no":463,"q":"Most common cause of nephrotic syndrome in adults?","o":["Membranous glomerulonephritis","Minimal change disease","Acute GN","Focal GN"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6293, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 133, '{"id":6293,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":133,"q":"Frequency of renal involvement in HSP ?","o":["20-40%",">80%","40-60%","10%"],"a":2,"e":"Ans. is ''c'' i.e., 40-60% The reported incidence of renal involvement in HSP varies considerably between different studies. This may be because of the different criteria used to describe the involvement & the variability of the length used to follow up. In different studies incidence of pediatric renal involvement in HSP was between 20-56% and in adults 50-78%","pyqMatches":[{"year":"2012","no":459,"q":"Frequency of renal involvement in HSP ?","o":["20-40%",">80%","40-60%","10%"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6294, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 134, '{"id":6294,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":134,"q":"According to WHO, membranous glomerulonephritis seen in SLE, is -","o":["Class II","Class III","Class IV","Class V"],"a":3,"e":"Ans. is ''d'' i.e., Class V There are several versions of WHO classification of lupus nephritis ? 1) Minimal or no detectable abnormalities (class 1) 2) Mesangial lupus glomerulonephritis (class II) 3) Focal proliferative glomerulonephritis (class III) 4) Diffuse proliferative glomerulonephritis (class IV) 5) Membranous glomerulonephritis (class V)","pyqMatches":[{"year":"2013","no":437,"q":"According to WHO, membranous glomerulonephritis seen in SLE, is","o":["Class II","Class III","Class IV","Class V"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6295, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 135, '{"id":6295,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":135,"q":"Subepithelial deposits in kidney are seen in-","o":["MPGN-1","GPS","PSGN","All"],"a":2,"e":"Ans. is ''c'' i.e., PSGN Glomerular deposits : (i) Subepithelial: o Acute GN (like PSGN) o Membranous GN o Heyman GN o RPGN (ii) Sub endothelial : (iii) Basement membrane : (iv) Mesangium : MPGN (Type- I) SLE o Acute ON (H'' 1583) o MPGN (Type II) o Good pasture syndrome o IgA nephropathy, HSP Remember o Anionic antigens form subendothelial deposits o Cationic antigens form subepithelial deposits o Neutral antigens form mesangial deposits","pyqMatches":[{"year":"2015","no":471,"q":"Subepithelial deposits in kidney are seen in","o":["MPGN-1","GPS","PSGN","All"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6296, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 136, '{"id":6296,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":136,"q":"Not true about Alport''s syndrome -","o":["X-linked","Autosomal dominant","Nerve deafness","Glomerulonephritis"],"a":1,"e":"Ans. is ''b'' i.e., Autosomal dominant o Autosomal dominant form also exist, but it is very rare. Thus, among the given options, it is the best answer. o Other three options are classical features of Alport''s syndrome (see previous explanations).","pyqMatches":[{"year":"2013","no":441,"q":"Not true about Alport''s syndrome ?","o":["X-linked","Autosomal dominant","Nerve deafness","Glomerulonephritis"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2015","no":470,"q":"Not true about Alport''s syndrome","o":["X-linked","Autosomal dominant","Nerve deafness","Glomerulonephritis"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2013","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6297, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 137, '{"id":6297,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":137,"q":"Renal cell carcinoma is related to gene located on chromosome -","o":["3","X","22","20"],"a":0,"e":"Ans. is ''a'' i.e., 3 o Clear cell carcinoma is the most common renal cell carcinoma and is associated with 3p deletion.","pyqMatches":[{"year":"2013","no":435,"q":"Renal cell carcinoma is related to gene located on chromosome","o":["3","X","22","20"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6298, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 138, '{"id":6298,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":138,"q":"Oncocytic carcinoma arises from -","o":["Perivascular","Glomerulus","Loop of henle","Collecting duct"],"a":3,"e":"Ans. is ''d'' i.e., Collecting ducts Oncocytic or Chromophobe renal carcinoma represents 5% of renal cell cancers. It is composed of cells with prominent cell membranes and pale eosinophilic cytoplasm, usually with a halo around the nucleus. They are, like the benign oncocytoma, thought to grow from intercalated cells of collecting ducts. o They have an excellent prognosis compared with that of the clear cell and papillary cancers.","pyqMatches":[{"year":"2012","no":462,"q":"Oncocytic carcinoma arises from","o":["Perivascular","Glomerulus","Loop of henle","Collecting duct"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6299, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 139, '{"id":6299,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":139,"q":"Histopathology showing large cells with plant like apperance with perinuclear halo is seen in which type of renal cell carcinoma ?","o":["Onchocytoma","Granular cell carcinoma","Angiosarcoma","Chromophobic"],"a":3,"e":"Ans. is ''d'' i.e., Chromophobic Histopathological findings of perinuclear halo and plant cell appearance are seen in chromophobe cell carcinoma ofRCC. Electron microscopic finding consisting of numerous 150-300 nm microvesicles is the single most distinctive and defining feature of chromophobe cell ca.","pyqMatches":[{"year":"2016","no":459,"q":"Histopathology showing large cells with plant like apperance with perinuclear halo is seen in which type of renal cell carcinoma ?","o":["Onchocytoma","Granular cell carcinoma","Angiosarcoma","Chromophobic"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6300, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 140, '{"id":6300,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":140,"q":"Transitional cell carcinoma bladder caused by-","o":["Schistosomiasis","Ascariasis","Malaria","None"],"a":0,"e":"Ans. is ''a'' i.e., Schistosomiasis Transitional cell carcinoma (TCC). This is the commonest cancer of the bladder. More than 90% of bladder tumors arise from transitional epithelial (urothelium) lining of the bladder in continuity with the epithelial lining of the renal pelvis, ureters, and the major part of the urethra. etiology: Industrial occupations: Workers in industries that produce aniline dyes, rubber, plastic, textiles, and cable have a high incidence of bladder cancer. Schistosomiasis: There is an increased risk of bladder cancer, particularly squamous cell carcinoma, in patients having bilharzial infestation (Schistosoma haematobium) of the bladder. Dietary factors: Certain carcinogenic metabolites of tryptophan are excreted in the urine of patients with bladder cancer. Local lesions: Several local lesions in the bladder predispose to the development of bladder cancer. These include ectopia vesicae (atrophied bladder), vesical diverticulum, leukoplakia of the bladder mucosa and urinary diversion in the defunctionalized bladder. Smoking: Tobacco smoking is associated with a 2 to 3 fold increased risk of developing bladder cancer, probably due to increased urinary excretion of carcinogenic substances. Drugs: Immunosuppressive therapy with cyclophosphamide and patients having analgesic-abuse (phenacetin-) nephropathy have a high risk of developing bladder cancer.","pyqMatches":[{"year":"2012","no":467,"q":"Transitional cell carcinoma bladder caused by","o":["Schistosomiasis","Ascariasis","Malaria","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6301, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 141, '{"id":6301,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":141,"q":"All are germ cell tumors except ?","o":["Seminoma","Leydig cell tumor","Embryonal carcinoma","Endodermal sinus"],"a":1,"e":"Ans. is ''b'' i.e., Leydig cell tumor Testicular tumor * Testicular tumors are divided into two major catogaries : ? Germ cell tumors * Seminoma * Embryonal carcinoma * Yolk sac (endodermal sinus) tumor Spermatocytic seminoma Choriocarcinoma Teratoma Sex cord tumors Leydig cells tumor Sertoli cell tumor * Approximately 95% of testicular tumors are germ cell tumors.","pyqMatches":[{"year":"2013","no":484,"q":"All are germ cell tumors except ?","o":["Seminoma","Leydig cell tumor","Embryonal carcinoma","Endodermal sinus"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6302, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 142, '{"id":6302,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":142,"q":"Which of the following germ cell tumor is malignant ?","o":["Leydig cell tumor","Sertoli cell tumor","Seminoma","Dermoid cyst"],"a":2,"e":"Ans. is ''c'' i.e., Seminoma o Among the given options only options c & d are germ cell tumors. Seminoma is malignant while dermoid cyst is benign. Germ cell tumors o Malignant - Germinoma (seminoma, dysgerminoma), embryonal carcinoma, endodermal sinus tumor (yolk sac tumor), choriocarcinoma, immature teratoma. Benign - Mature teratoma, dermoid cyst.","pyqMatches":[{"year":"2012","no":508,"q":"Which of the following germ cell tumor is malignant ?","o":["Leydig cell tumor","Sertoli cell tumor","Seminoma","Dermoid cyst"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6303, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 143, '{"id":6303,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":143,"q":"Commonest infantile testicular tumour is ?","o":["Seminoma","Teratoma","Yolk sac tumor","Dysgerminoma"],"a":2,"e":"Ans. is ''c'' i.e., Yolk sac tumor o Most common tumor of testis Seminoma. o Most common tumor of testis in childhood ---> yolk sac tumor (endodermal sinus tumor or infantile embryonal carcinoma).","pyqMatches":[{"year":"2015","no":1354,"q":"Commonest infantile testicular tumour is ?","o":["Seminoma","Teratoma","Yolk sac tumor","Dysgerminoma"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6304, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 144, '{"id":6304,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":144,"q":"Tennis racket cells is seen in -","o":["Sarcoma botyroides","Vaginal adenocarcinoma","Leiomyoma uterus","Seminoma"],"a":0,"e":"Ans. is ''a'' i.e., Sarcoma botryoids o Tumor cells of sarcoma botryoids are small and have oval nuclei, with small protrusions of cytoplasm from one end, so they resemble a tennis racket.","pyqMatches":[{"year":"2015","no":702,"q":"Tennis racket cells is seen in","o":["Sarcoma botyroides","Vaginal adenocarcinoma","Leiomyoma uterus","Seminoma"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6305, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 145, '{"id":6305,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":145,"q":"Which is not a risk factor of endometrial carcinoma -","o":["Obesity","Smoking","Infertility","Tamoxifen"],"a":1,"e":"Ans. is ''b'' i.e., Smoking Endometrial carcinoma Endometrial carcinoma is the most common invasive cancer of the female genital tract and accounts for 7% of all invasive cancer in women. The peak incidence is in the 55- to 65-year-old woman. Clinicopathological studies & molecular analysis support its classification into two major broad categories. Type-I Carcinoma Most common type. Majority are well differentiated & mimic proliferative endometetrial glands. They are associated with- obesity, diabetes, hypertension, infertility and unopposed estrogen stimulation. Tamoxifen also increases the risk of endometrial cancer. Endometrial hyperplasia is a precursor to endometroid carcinoma. Mutation in PTEN tumor suppressor gene have been seen in 30- 80% of endometeriod carcinoma & 20% patients with endometrial hyperplasia. Additional molecular changes that are common are microsatellite instability & mutations in KRAS & beta catenin oncogenes. Type-H Carcinoma These occur in women a decade later than type I carcinoma. These usually arise in setting of endometrial atropy. They are poorly differentiated. The most common subtype is serous carcinoma, clear cell type & malignant mixed mullerian tumor. The most frequent alteration described is mutation in p53 tumor suppressor gene.","pyqMatches":[{"year":"2012","no":507,"q":"Which is not a risk factor of endometrial carcinoma","o":["Obesity","Smoking","Infertility","Tamoxifen"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6306, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 146, '{"id":6306,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":146,"q":"Rokitanski protruberences are seen in -","o":["Mucinous carcinoma","Teratoma","Epidermal cystoids adenoma","Papillary carcinoma"],"a":1,"e":"Ans. is ''b'' i.e., Teratoma Teratoma o Teratomas are divided into three categories: (1) Mature (benign): Most benign teratomas are cystic and are known as dermoid cysts. These neoplasms are presumably derived from the ectodermal differentiation of totipotential cells. They are bilateral in 10% to 15% of cases. Characteristically, they are unilocular cysts containing hair and cheesy sebaceous material. On section, they reveal a thin wall lined by an opaque, gray-white, wrinkled, apparent epidermis. Generally, in one area of the cyst wall, a solid prominence is seen known as Rokitansky''s protuberance where tissue elements such as tooth, bone, cartilage & various other odd tissues are present. On histologic examination, the cyst wall is composed of stratified squamous epithelium with underlying sebaceous glands, hair shafts, and other skin adnexal structures. In most cases, structures from other germ layers can be identified, such as cartilage, bone, thyroid tissue, and other organoid formations. Dermoid cysts are sometimes incorporated within the wall of a mucinous cystadenoma. About 1% of the dermoids undergo malignant transformation of any one of the component elements ( but most commonly, squamous cell carcinoma). (2) Monodermal or Specialized Teratomas The rare group of tumors, the most common of which are struma ovarii and carcinoid. They are always unilateral, although a contralateral teratoma may be present. Struma ovarii is composed entirely of mature thyroid tissue. Interestingly, these thyroidal neoplasms may hyperfunction, causing hyperthyroidism. The ovarian carcinoid, which presumably arises from intestinal epithelium in a teratoma, might in fact be functioning, particularly in large tumors, producing 5-hydroxytryptamine and the carcinoid syndrome. (3) Immature Malignant Teratomas These are rare tumors that differ from benign teratomas in that the component tissue resembles that observed in the fetus or embryo rather than in the adult. The tumor is found chiefly in prepubertal adolescents and young women. These grow rapidly and frequently penetrate the capsule with local spread or metastases. On microscopy, there are varying amounts of immature tissue differentiating toward cartilage, glands, bone, muscle, nerve, and others. An important risk for subsequent extraovarian spread is the histologic grade of tumor, which is based on the proportion of tissue containing immature neuroepithelium.","pyqMatches":[{"year":"2012","no":506,"q":"Rokitanski protruberences are seen in","o":["Mucinous carcinoma","Teratoma","Epidermal cystoids adenoma","Papillary carcinoma"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6307, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 147, '{"id":6307,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":147,"q":"Proliferating breast mass is -","o":["Duct ectasia","Fibroadenoma","Adenosis","Papilloma"],"a":3,"e":"Ans. is ''d'' i.e., Papilloma Examples include atypical ductal hyperplasia, atypical lobular hyperplasia, and intraductal papillomas.","pyqMatches":[{"year":"2012","no":510,"q":"Proliferating breast mass is","o":["Duct ectasia","Fibroadenoma","Adenosis","Papilloma"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6308, 'Pathology', 'Inflammation', 'Moderate', 'Pathology', 148, '{"id":6308,"subject":"Pathology","chapter":"Inflammation","difficulty":"Moderate","source":"Pathology","sourceNo":148,"q":"Granulomatous mastitis is caused by all except -","o":["TB","Fungus","Staphylococcus","Antibodies to milk antigens"],"a":2,"e":"Ans. is ''c'' i.e., Staphylococcus Granulomatous mastitis * Granulomatous inflammation is present in less than 1% of all breast biopsy specimens. * The causes include systemic granulomatous disease (e.g., Wegener granulomatosis or sarcoidosis) that occasionally involve the breast, and granulomatous infections caused by mycobacteria or fungi. * Infections of this type are most common in immunocompromised patients or adjacent to foreign objects such as breast prostheses or nipple piercings. * Granulomatous lobular mastitis is an uncommon breast-limited disease that only occurs in parous women. * The granulomatous inflammation is confined to the lobules, suggesting that it is caused by a hypersensitivity reaction to antigens expressed by lobular epithelium during lactation.","pyqMatches":[{"year":"2013","no":486,"q":"Granulomatous mastitis is caused by all except","o":["TB","Fungus","Staphylococcus","Antibodies to milk antigens"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6309, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 149, '{"id":6309,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":149,"q":"Type of DCIS resulting in palpable abnormality?","o":["Comedocarcinoma","Non comedo DCIS","Paget''s disease","None"],"a":2,"e":"Ans. is ''c'' i.e., Paget''s disease \"A palpable mass is present in 50% to 60% of women with Paget disease, and almost all of these women have an underlying invasive carcinoma. In contrast, the majority of women without a palpable mass have only DCIS\". — Robbin''s * Actually the question has been framed wrongly as Paget''s disease is not a type of DCIS. It is a different lesion. But, it has been explained along with morphology of DCIS.","pyqMatches":[{"year":"2013","no":487,"q":"Type of DCIS resulting in palpable abnormality?","o":["Comedocarcinoma","Non comedo DCIS","Paget''s disease","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6310, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 150, '{"id":6310,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":150,"q":"ER positive status in Ca Breast indicates -","o":["Prognosis","Etiology","Site","None"],"a":0,"e":"Ans. is ''a'' i.e., Prognosis o Estrogen receptor (ER) positive breast carcinomas are generally slow growing and respond well to hormonal treatment. o Gene expression prolifing, which can measure the relative quantities of mRNA for essentially every gene, has identified five major patterns of gene expression in invasive ductal carcinoma. Luminal A o This is the largest group (40-55%) which has characteristics of normal luminal cells. o This type is ER positive and HER2/neu negative. o These cancers are generally slow growing and respond to hormonal treatment. Conversely only a small number will respond to standard chemotherapy Luminal B o These tumors are ER positive, has a higher proliferative rate and overexpresses HER2/neu ---> Triple-positive cancer. o They compose a major group of ER-positive cancers that are more likely to have lymphnode metastases and may respond to standard chemotherapy. Normal breast line o These are ERpositive, HER2/neu negative and characterized by the similarity of their gene expression pattern to normal tissue. Basal line o These are ER negative, PR negative, HER2/neu negative Triple negative. o These are characterized by expression of markers typical of myoepithelial cells (e.g., basal keratins, P​codherins, p63, or laminin), progenitor cells, or putative stem cells (e.g. cytokeratins 5 and 6). o Many carcinoma arising in women with BRAC I mutations are of this type. o These are aggressive tumors, frequent metastasis to viscera and brain can be seen ---> have poor prognosis. HER2 positive o These are ER negative and overexpress HER 2/neu protein.","pyqMatches":[{"year":"2012","no":509,"q":"ER positive status in Ca Breast indicates","o":["Prognosis","Etiology","Site","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6311, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 151, '{"id":6311,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":151,"q":"Modified Bloom Richardson criteria for Carcinoma Breast includes -","o":["Desmoplasia","Lymphovenous embolism","Mitotic rate","All"],"a":2,"e":"Ans. is ''c'' i.e. mitotic rate Grading of breast cancer o Presently, most methods for grading use the previously cited three-tiered systems for describing tumor structure in terms of tubule formation, nuclear grade and mitotic count, with the latter usually expressed as the number of mitosis per 10 high- magnification field. o Each element is scored on a scale from 1 to 3 according to criteria of the specific grading system, and the final grade is determined by the sum of mitosis. o Totals of 3 to 5 indicate a well-differentiated or low-grade tumor; 6 to 7, a moderately differentiated or intermediate-grade tumor; and 8 to 9 , a poorly differentiated or high-grade tumor. o This method of scoring is known as the Nottingham combined histologic grade of Elston-Ellis modification of the Scarff-Bloom- Richardson grading system, often reported as a modified Scaff- Bloom-Richardson grade. Modified Bloom-Richarson histological grading Tubule formation o Score 1 :- >75% of tumor has tubules Score 2 :- 10-75% of tumor has tubules o Score 3 :- < 10% of tumor has tubules Nuclear size ( nuclear polymorphism) o Score 1 :- tumor nuclei similar to normal duct nuclei (2-3 x RBC) Score 2 :- Intermediate size nuclei Score 3 :- very large nuclei, usually vesicular with prominent nucleoli Mitotic count o Score 1 :- 0-7 mitosis o Score 2 :- 8-14 mitosis o Score 3 :- > 15 mitosis","pyqMatches":[{"year":"2014","no":442,"q":"Modified Bloom Richardson criteria for Carcinoma Breast includes","o":["Desmoplasia","Lymphovenous embolism","Mitotic rate","All"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6312, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 152, '{"id":6312,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":152,"q":"Most common malignant bone tumor-","o":["Osteogenic sarcoma","Secondaries","Osteoma","Enchondroma"],"a":1,"e":"Ans. is ''b'' i.e., Secondaries o Secondaries are most common malignant bone tumor. o Osteogenic sarcoma is the most common primary malignant bone tumor. o Osteoma is most common benign bone tumor.","pyqMatches":[{"year":"2016","no":1470,"q":"Most common malignant bone tumor","o":["Osteogenic sarcoma","Secondaries","Osteoma","Enchondroma"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6313, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 153, '{"id":6313,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":153,"q":"Ewings sarcoma arises from -","o":["G cells","Totipotent cells","Neuroectodermal cells","Neurons"],"a":2,"e":"Ans. is c i.e., Neuroectodermal cells o Histologically, Ewing''s sarcoma has a certain resemblance to primitive neuroectodermal cells, and the tumor arises from such cells. o It is a rare malignancy primarily affecting children and adolescents. It arises mainly in bone and less commonly in soft tissues. o In these, there is a characteristic reciprocal chromosomal translocation, which leads to an in-frame fusion between the EWS gene and one of the ETS family gene members.","pyqMatches":[{"year":"2012","no":513,"q":"Ewings sarcoma arises from","o":["G cells","Totipotent cells","Neuroectodermal cells","Neurons"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6314, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 154, '{"id":6314,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":154,"q":"Which of the following is the most common mutation in Ewing''s sarcoma -","o":["Translocation X : 18","Translocation 11; 22","Activative mutation of G5a,p, surface protein","Missense mutation in EXTI"],"a":1,"e":"Ans. is ''b'' i.e., Translocation 11; 22 Ewing''s sarcoma is typically charachterized by a translocation t (11; 22) (q 24; q12) in upto 90% of patients.","pyqMatches":[{"year":"2016","no":486,"q":"Which of the following is the most common mutation in Ewing''s sarcoma","o":["Translocation X : 18","Translocation 11; 22","Activative mutation of G5a,p, surface protein","Missense mutation in EXTI"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6315, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 155, '{"id":6315,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":155,"q":"Tadpole cells comma shaped cells on histopathology are seen in -","o":["Trichoepithelioma","Spideroma","Rhabdomyosarcoma","Histiocytoma"],"a":2,"e":"Ans. is ''c'' i.e., Rhabdomyosarcoma Histology of rhabdomvosarcoma The diagnostic cell of rhabdomyosarcoma is rhabdomyoblast. Rhabdomyoblast contains eccentric eosinophilic granular cytoplasm rich in thick and thin filaments. o The rhabdomyoblasts may be ? i) Round Elongated Tadpole or Strap cells. It has three variants ii) Embryonal Alveolar iii) Pleomorphic Rhabdomyoblasts are positive for desmin, MYOD1 and Myogenin.","pyqMatches":[{"year":"2012","no":511,"q":"Tadpole cells comma shaped cells on histopathology are seen in","o":["Trichoepithelioma","Spideroma","Rhabdomyosarcoma","Histiocytoma"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6316, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 156, '{"id":6316,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":156,"q":"Perivascular lymphocytes & microglial nodules are seen in -","o":["Multiple sclerosis","HIV encephalitis","CMV meningitis","Bacterial meningitis"],"a":1,"e":"Ans. is ''b'' i.e., HIV encephalitis o Perivascular infiltrate of lymphocytes (and macrophages) with microglial nodules is seen in HIV encephalitis. o Perivascular infiltrate of lymphocytes (and monocytes) is also seen in multiple sclerosis. But, microglial nodules are characteristic of HIV encephalitis.","pyqMatches":[{"year":"2012","no":516,"q":"Perivascular lymphocytes & microglial nodules are seen in","o":["Multiple sclerosis","HIV encephalitis","CMV meningitis","Bacterial meningitis"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6317, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 157, '{"id":6317,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":157,"q":"Regarding Dandy-Walker syndrome, all are seen except-","o":["Hydrocephalus","Archnoid cyst","Posterior fossa cyst","Cerebellar vermis deficiency"],"a":1,"e":"Ans. is ''b'' i.e., Arachnoid cyst Dandy-walker malformation o The Dandy-Walker malformation consists of a cystic expansion of the 4th ventricle in the posterior fossa and midline cerebellar hypoplasia. o There is : ? o Hydrocephalus (90% of cases) o Agenesis of the cerebellar vermis and corpus callosum. o Rapid increase in head size with prominent occiput.","pyqMatches":[{"year":"2013","no":1454,"q":"Regarding Dandy-Walker syndrome, all are seen except","o":["Hydrocephalus","Archnoid cyst","Posterior fossa cyst","Cerebellar vermis deficiency"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6318, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 158, '{"id":6318,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":158,"q":"Neurofibromatosis true all, except-","o":["Autosomal recessive","Associated with cataract","Scoliosis","Multiple fibroma"],"a":0,"e":"Ans. is ''a'' i.e., Autosomal recessive Neurofibromatosis comprises of two distinct disorders - * Neurofibromatosis I * Neurofibromatosis II * The genes for these are located on different chromosomes. * Both are inherited in an autosomal dominant pattern. * The classical form of the disease with multiple neuromas is called Neurofibromatosis I and is caused by a mutation of the gene neurofibromin on chromosome 17","pyqMatches":[{"year":"2012","no":431,"q":"Neurofibromatosis true all, except","o":["Autosomal recessive","Associated with cataract","Scoliosis","Multiple fibroma"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6319, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 159, '{"id":6319,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":159,"q":"Which of the following tumors is not derived from meninges -","o":["Hemangioblastoma","Meningioma","Fibrous tumor","Hemangiopericytoma"],"a":0,"e":"Ans. is ''a'' i.e., Haemangioblastoma Meningeal tumors o Meningothelial tumor : Meningioma (most common meningeal tumor). o Mesenchymal non-meningothelial tumors : Meningeal solitary fibrous tumor, hemangiopericytoma, meningeal sarcoma, fibrous histiocytoma, meningeal melanocytoma, (melanocytic tumor).","pyqMatches":[{"year":"2012","no":499,"q":"Which of the following tumors is not derived from meninges","o":["Hemangioblastoma","Meningioma","Fibrous tumor","Hemangiopericytoma"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6320, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 160, '{"id":6320,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":160,"q":"Most common cerebellar tumor in children?","o":["Astrocytoma","Medulloblastoma","Ependymoma","DNET"],"a":0,"e":"Ans. is ''a'' i.e., Astrocytoma o The most common cerebellar tumor in adults is metastasis, whereas in children the most common tumor is an astrocytoma.","pyqMatches":[{"year":"2012","no":1173,"q":"Most common cerebellar tumor in children?","o":["Astrocytoma","Medulloblastoma","Ependymoma","DNET"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6321, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 161, '{"id":6321,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":161,"q":"Medulloblastoma most common metastasis is to ?","o":["Lung","CNS","Liver","Spleen"],"a":1,"e":"Ans. is ''b'' i.e., CNS o Medullablastoma spread through CSF and frequently metastasizes to different locations in the brain and spine. o Extraneural metastasis to the rest of the body is rare.","pyqMatches":[{"year":"2012","no":514,"q":"Medulloblastoma most common metastasis is to ?","o":["Lung","CNS","Liver","Spleen"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6322, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 162, '{"id":6322,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":162,"q":"Most common site for medulloblastoma is-","o":["Cerebellum","Pituitary","Cerebrum","Pineal gland"],"a":0,"e":"Ans. is ''a'' i.e., Cerebellum o Medulloblastoma is an infratentorial tumor and occurs exclusively in cerebellum.","pyqMatches":[{"year":"2012","no":519,"q":"Most common site for medulloblastoma is","o":["Cerebellum","Pituitary","Cerebrum","Pineal gland"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6323, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 163, '{"id":6323,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":163,"q":"Spongiform degeneration of cerebral cortex occurs in -","o":["Creutzfeldt-Jakob disease","Subacute sclerosing panencephalitis","Fatal familial insomnia","Cerebral toxoplasmosis"],"a":0,"e":"Ans. is ''a'' i.e., Creutzfeldt-Jakob disease o On microscopic examination, in Creutzfeldt-Jakob disease the pathognomonic finding is a spongiform transformation of the cerebral cortex and, often, deep gray matter structures (caudate, putamen); this consists of a multifocal process that results in the uneven formation of small, apparently empty, microscopic vacuoles of varying sizes within the neuropil and sometimes in the perikaryon of neurons. In advanced cases, there is severe neuronal loss, reactive gliosis, and sometimes expansion of the vacuolated areas into cystlike spaces (\"status spongiosus\"). o Kuru plaques are extracellular deposits of aggregated abnormal protein; they are Congo red-positive as well as PAS-positive and occur in the cerebellum in cases of Gerstmann-Striiussler-Scheinker syndrome; they are present in abundance in the cerebral cortex in cases of variant CJD. o In all forms of prion disease, immunohistochemical staining demonstrates the presence of proteinase-K-resistant PrPsc in tissue. o Fatal familial insomnia does not show spongiform pathology. Instead, the most striking alteration is neuronal loss and reactive gliosis in the anterior ventral and dorsomedial nuclei of the thalamus; neuronal loss is also prominent in the inferior olivary nuclei.","pyqMatches":[{"year":"2012","no":497,"q":"Spongiform degeneration of cerebral cortex occurs in","o":["Creutzfeldt-Jakob disease","Subacute sclerosing panencephalitis","Fatal familial insomnia","Cerebral toxoplasmosis"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6324, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 164, '{"id":6324,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":164,"q":"What is the histological appearance of brain in Creutzfeldt-Jakob disease -","o":["Neuronophagia","Spongiform change in brain","Microabscesses","Demyelination"],"a":1,"e":"Ans. is ''b'' i.e., Spongiform change in brain o The classic histologic appearance in Creutzfeldt-Jakob disease is spongiform change in the gray matter : in all six cortical layers in the cerebral cortex or with diffuse involvement of the cerebellar molecular layer. These vacuoles appear glassy or eosinophilic and may coalesce. Neuronal loss and gliosis are also seen.","pyqMatches":[{"year":"2012","no":498,"q":"What is the histological appearance of brain in Creutzfeldt-Jakob disease","o":["Neuronophagia","Spongiform change in brain","Microabscesses","Demyelination"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6325, 'Pathology', 'Immunopathology', 'Moderate', 'Pathology', 165, '{"id":6325,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Moderate","source":"Pathology","sourceNo":165,"q":"Autoimmune thyroiditis is associated with all except -","o":["DM","Mysthenia gravis","Sly","Psoriasis"],"a":3,"e":"Ans. is ''d'' i.e., Psoriasis * Autoimmune thyroiditis (Hashimoto thyroiditis) patients are at increased risk for developing other autoimmune disease :- i) Endocrine : Type 1 DM, autoimmune adrenalitis. ii) Non-endocrine : SLE, mysthenia gravis, sjogren syndrome. * These patients are also at increased risk for development of B-cell non-Hodgkin lymphoma, especially marginal cell lymphoma of MALT lymphoma.","pyqMatches":[{"year":"2013","no":482,"q":"Autoimmune thyroiditis is associated with all except","o":["DM","Mysthenia gravis","Sly","Psoriasis"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6326, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 166, '{"id":6326,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":166,"q":"Orphan annie eye nuclei appearance is characteristic of -","o":["Papillary carcinoma thyroid","Carcinoma pituitary","Paraganglioma","Meningioma"],"a":0,"e":"Ans. is ''a'' i.e., Papillary carcinoma thyroid o The nuclei of papillary carcinoma cells contain finely dispersed chromatin, which imparts an optically clear or empty appearance, giving rise to the designation ground glass or Orphan Annie eye nuclei.","pyqMatches":[{"year":"2012","no":504,"q":"Orphan annie eye nuclei appearance is characteristic of","o":["Papillary carcinoma thyroid","Carcinoma pituitary","Paraganglioma","Meningioma"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6327, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 167, '{"id":6327,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":167,"q":"True about Psammoma bodies are all except ?","o":["Seen in meningioma","Concentric whorled appearance","Contains Calcium deposits","Seen in teratoma"],"a":3,"e":"Ans. is ''d'' i.e., Seen in teratoma o Psammoma bodies represent a process of dystrophic calcification. o Single necrotic cells may constitute seed crystals that become encrusted by the mineral deposits. The progressive acquisition of outer layers may create lamellated configurations, called psammoma bodies because of their resemblance to grains of sand. o Psammoma bodies are seen in : papillary cancer of thyroid, meningioma, papillary serous cystadenocarcinoma of ovary.","pyqMatches":[{"year":"2012","no":502,"q":"True about Psammoma bodies are all except ?","o":["Seen in meningioma","Concentric whorled appearance","Contains Calcium deposits","Seen in teratoma"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6328, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 168, '{"id":6328,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":168,"q":"Tumor that follows rule of 10 is-","o":["Pheochromocytoma","Oncocytoma","Lymphoma","Renal cell carcinoma"],"a":0,"e":"Ans. is ''a'' i.e., Pheochromocytoma o Pheochromocytomas usually subscribe to a convenient \"rule of 10s\" :- 10% of pheochromocytomas arise in association with one of several familial syndromes. These include the MEN-2A & MEN-2B syndromes, type I neurofibromatosis, von Hippel-Lindau syndrome & Sturge-Weber syndrome. 10% of pheochromocytomas are extra-adrenal, occurring in sites such as organ of Zuckerkandl & carotid body, where these chromaffin-negative tumors are usually called paragangliomas to distinguish them from pheochromocytomas. 10% of nonfamilial adrenal pheochromocytomas are bilateral; this figure may rise to 70% in cases that are associated with familial syndromes. 10% of adrenal pheochromocytomas are biologically malignant, although the associated hypertension represents a serious & potentially lethal complication of even \"benign\" tumors. 10% of adrenal pheochromocytomas arise in childhood, usually the familial subtypes, and with a strong male preponderance. The nonfamilial pheochromocytomas most often occur in adults between 40 & 60 years of age, with a slight female preponderance.","pyqMatches":[{"year":"2012","no":501,"q":"Tumor that follows rule of 10 is","o":["Pheochromocytoma","Oncocytoma","Lymphoma","Renal cell carcinoma"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6329, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 169, '{"id":6329,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":169,"q":"Which of the following is most reliable feature of malignant transformation of pheochromocytoma ?","o":["Presence of mitotic figures","Capsular invasion","Vascular invasion","None"],"a":3,"e":"Ans. is None \"Because benign and malignant pheochromocytomas may have an identical histological appearance, the only absolute criterion of malignancy is metastasis.\" \"The diagnosis of malignant pheochromocytoma is made only when metastasis is demonstrated.\"","pyqMatches":[{"year":"2012","no":500,"q":"Which of the following is most reliable feature of malignant transformation of pheochromocytoma ?","o":["Presence of mitotic figures","Capsular invasion","Vascular invasion","None"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6330, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 170, '{"id":6330,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":170,"q":"Tertiary hyperparathyroidism is-","o":["High PO4 level with metastasis","Secondary hyperparathyroidism with CRF","Primary hyperparathyroidism with low Ca\" levels","Secondary hyperparathyroidism with chief cell adenoma"],"a":3,"e":"Ans. is ''d'' i.e., Secondary hyperparathyroidism with chief cell adenoma Davidson states \"In very small proportion of cases of secondary hyperparathyroidism continuous stimulation of the parathyroid may result in adenoma formation and autonomous PTH secretion. This is known as tertiary hyperparathyroidism\".","pyqMatches":[{"year":"2016","no":1140,"q":"Tertiary hyperparathyroidism is","o":["High PO4 level with metastasis","Secondary hyperparathyroidism with CRF","Primary hyperparathyroidism with low Ca\" levels","Secondary hyperparathyroidism with chief cell adenoma"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6331, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 171, '{"id":6331,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":171,"q":"Mutation in malignant melanoma-","o":["N-myc","CDK2A","RET","None"],"a":1,"e":"Ans. is ''b'' i.e., CDK2A \"In melanoma cells, numbers of mutations and/or dysregulated expression of B-Rof N-Ras, CDK2A, MDM2, PTEN, p53 have been recognized\".","pyqMatches":[{"year":"2012","no":515,"q":"Mutation in malignant melanoma","o":["N-myc","CDK2A","RET","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6332, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 172, '{"id":6332,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":172,"q":"Which of the following is not true about amoebiasis?","o":["ALA in 10% causes in tropics","Portal system efficient filter","Abscess due to suppuration","Abscess wall good for culture"],"a":2,"e":"Ans. is ''c'' i.e., Abscess due to suppuration Amebic liver abscess Pus in amoebic liver abscess is not due to suppuration, but is a mixture of sloughed liver tissue and blood. It is chocolate brown in colour and thick in consistency (anchovy sauce pus) In the tropics 2-10% of the individuals infected with entamoeba histolytica suffer from hepatic complications. The trophozoites are carried from the large intestine to the liver by portal vein. In the liver the capillary system acts as efficient filter and holds these parasites. In case of amoebic liver abscess the diagnostic aspiration is done from the abscess wall because the trophozoites are confined to the periphery.","pyqMatches":[{"year":"2016","no":1103,"q":"Which of the following is not true about amoebiasis?","o":["ALA in 10% causes in tropics","Portal system efficient filter","Abscess due to suppuration","Abscess wall good for culture"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6333, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 173, '{"id":6333,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":173,"q":"Most important prognostic factor of wilms tumour -","o":["Histopathology","Ploidy of cells","Age < 1 yr","Mutation, of clp gene"],"a":0,"e":"Ans. is ''a'' i.e., Histopathology Anaplastic nuclear change is the only criterion of \"unfavourable\" histology in Wilm''s tumor and all Wilm''s tumor lacking this feature are designated as having \"favourable histology\". Anaplastic nuclear change reflects extreme polypoidy & is usually apparent under low magnification. \"Anaplastic histology remains a critical determinant of adverse prognosis. Even anaplasia restricted to kidney confers an increased risk of recurrence & death, underscoring the need for correctly identifying this histologic features.\"","pyqMatches":[{"year":"2012","no":460,"q":"Most important prognostic factor of wilms tumour","o":["Histopathology","Ploidy of cells","Age < 1 yr","Mutation, of clp gene"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6334, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 174, '{"id":6334,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":174,"q":"Which of the following porphyrias is not inherited as an Autosomal Dominant disorder-","o":["Acute Intermittent Porphyria","Congenital Erythropoietic Porphyria","Porphyria Cutanea Tarda","Hereditary Coproporphyria"],"a":1,"e":"Ans. is ''b'' i.e., Congenital erythropoietic porphyria Inheritance of Porphyrias Autosomal dominant Autosomal Recessive X-linked o Acute intermittent porphyria (AIP) o ALA dehydratase deficiency o X-linked protoporphyria o Porphyria cutanea Tarda (PCT) o Congenital erythropoietic porphyria o Hereditary coproporphyria (HCP) o Erythropoietic protoporphyria o Variegate porphyria (VP)","pyqMatches":[{"year":"2013","no":1695,"q":"Which of the following porphyrias is not inherited as an Autosomal Dominant disorder","o":["Acute Intermittent Porphyria","Congenital Erythropoietic Porphyria","Porphyria Cutanea Tarda","Hereditary Coproporphyria"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6335, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 175, '{"id":6335,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":175,"q":"Glomus tumor is seen in -","o":["Retroperitoneum","Soft tissue","Distal portion of digits","Proximal portion of digits"],"a":2,"e":"Ans. is ''c'' i.e., Distal portion of digits o It is a benign but painful tumor that arises from the modified smooth muscle cells of the glomus body, a specialized arteriovenous anastomosis that is involved in thermoregulation. o They are most commonly found in the distal portion of the digits, especially under the fingernails.","pyqMatches":[{"year":"2012","no":512,"q":"Glomus tumor is seen in","o":["Retroperitoneum","Soft tissue","Distal portion of digits","Proximal portion of digits"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6336, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 176, '{"id":6336,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":176,"q":"All of the following are true about Gout, except:-","o":["Occurs due to accumulation of urate crystals in joint","Can be pptd by pyrazinamide","Birefringement crystals are present in joint","Occurs more in females"],"a":3,"e":"Answer is D (Occurs more in females): Gout is more widespread in men than in women. Women represent only 5-20% of patients with gout. Women are seldom affected until after menopause.","pyqMatches":[{"year":"2015","no":1180,"q":"All of the following are true about Gout, except:","o":["Occurs due to accumulation of urate crystals in joint","Can be pptd by pyrazinamide","Birefringement crystals are present in joint","Occurs more in females"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6337, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 177, '{"id":6337,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":177,"q":"First change seen in acute inflammation is: September 2009","o":["Increased permeability","Vasodilation","Neutrophil migration","Vasoconstriction"],"a":3,"e":"Ans. D: Vasoconstriction Cardinal signs: Rubor (redness) due to dilatation of arterioles Calor (heat) Dolor (pain) due to pressure on nerve endings by edema fluid and chemical mediator bradykinine Tumor (swelling) due to edema. Functio laesa (loss of function) due to inhibition of movement by pain and tissue necrosis.","pyqMatches":[{"year":"2014","no":382,"q":"First change seen in acute inflammation is: September 2009","o":["Increased permeability","Vasodilation","Neutrophil migration","Vasoconstriction"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6338, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 178, '{"id":6338,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":178,"q":"Portal hypertension is said to be present if portal venous pressure is more than: March 2010","o":["3-5 mm Hg","5-8 mm Hg","10-12 mm Hg","15-20 mm Hg"],"a":2,"e":"Ans. C: 10-12 mm Hg Normal portal pressure is generally defined between 5 and 10 mm Hg. Portal hypertension results when the portal pressure rises to 12 mm Hg or greater and complications can arise, such as varices and ascites. Many conditions are associated with portal hypertension, of which cirrhosis is the most common cause","pyqMatches":[{"year":"2016","no":1098,"q":"Portal hypertension is said to be present if portal venous pressure is more than: March 2010","o":["3-5 mm Hg","5-8 mm Hg","10-12 mm Hg","15-20 mm Hg"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6339, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 179, '{"id":6339,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":179,"q":"Most common site of hypertensive intraparenchymal hemorrhage in brain: March 2013","o":["Pons","Thalamus","Putamen","Cerebellum"],"a":2,"e":"Ans. C i.e. Putamen Sites of intracerebral hemorrhage includes putamen (55%), thalamus (20-3-%), cerebrllum (10%), pons (5-7%) and subcortical white matter (10-15%)","pyqMatches":[{"year":"2015","no":1156,"q":"Most common site of hypertensive intraparenchymal hemorrhage in brain: March 2013","o":["Pons","Thalamus","Putamen","Cerebellum"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6340, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 180, '{"id":6340,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":180,"q":"Negri bodies are characteristic of: September 2008, March 2013","o":["Tetanus","Rabies","Polio","AIDS"],"a":1,"e":"Ans. B: Rabies Since first described by Negri in 1903, the presence of the Negri bodies are practically pathognomic for rabies and are an important diagnostic finding. Negri bodies are discrete, intracytoplasmic, deeply eosinophilic inclusions that measure several microns in diameter. In about 75% of cases of rabies these can be seen on hematoxylin and eosin stained sections. They occur in neurons of the brain stem, particularly those in the hippocampus, and in the Purkinje cells of the cerebellum. Ultrastructural studies have shown that Negri body consists of a mass of nucleocapsids surrounded by viral particles budding from intracytoplasmic membranes. Those bodies can be seen in axons, and it is in this way that virus spreads from the central nervous system to many organs of the body. Because Negri bodies are usually seen in intact neurons, they are found away from the inflammatory, nonspecific lesions. Rabies viral antigens can be demonstrated in infected cells by means of fluorescent antibody technique. Antigens can be shown to be present in cells in the absence of Negri bodies, and hence this technique is much more sensitive than the search of sections of brain for the pathognomonic cytoplasmic inclusions.","pyqMatches":[{"year":"2016","no":757,"q":"Negri bodies are characteristic of: September 2008, March 2013","o":["Tetanus","Rabies","Polio","AIDS"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6341, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 181, '{"id":6341,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":181,"q":"Most common location of gastrinoma is: September 2007","o":["Pancreas","Duodenum","Jejunum","Gall bladder"],"a":1,"e":"Ans. B: Duodenum Zollinger-Ellison syndrome is a disorder where increased levels of the hormone gastrin are produced, causing the stomach to produce excess hydrochloric acid. Often the cause is a tumor (gastrinoma) of the duodenum or pancreas producing the hormone gastrin. Gastrin then causes an excessive production of acid which can lead to peptic ulcers in almost 95% of patients. Gastrinomas may occur as single tumors or as multiple, small tumors. About one-half to two-thirds of single gastrinomas are malignant tumors that most commonly spread to the liver and lymph nodes near the pancreas and small bowel. Nearly 25 percent of patients with gastrinomas have multiple tumors as part of a condition called multiple endocrine neoplasia type I (MEN I). MEN I patients have tumors in their pituitary gland and parathyroid glands in addition to tumors of the pancreas.","pyqMatches":[{"year":"2013","no":472,"q":"Most common location of gastrinoma is: September 2007","o":["Pancreas","Duodenum","Jejunum","Gall bladder"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6342, 'Pathology', 'Hematology', 'Easy', 'Pathology', 182, '{"id":6342,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":182,"q":"Lacunar cells is seen in which type of Hodgkins Lymphoma: September 2010","o":["Mixed cellularity type","Lymphocyte predominant","Nodular Sclerosis Type","All of the above"],"a":2,"e":"Ans. C: Nodular Sclerosis Type Reed-Sternberg cells (also known as lacunar histiocytes for certain types) are different giant cells found on light microscopy in biopsies from individuals with Hodgkin''s lymphoma (aka Hodgkin''s disease; a type of lymphoma), and certain other disorders. They are usually derived from B lymphocytes.","pyqMatches":[{"year":"2012","no":474,"q":"Lacunar cells is seen in which type of Hodgkins Lymphoma: September 2010","o":["Mixed cellularity type","Lymphocyte predominant","Nodular Sclerosis Type","All of the above"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6343, 'Pathology', 'Hemodynamics', 'Moderate', 'Pathology', 183, '{"id":6343,"subject":"Pathology","chapter":"Hemodynamics","difficulty":"Moderate","source":"Pathology","sourceNo":183,"q":"Following are seen in polycythemia vera except:","o":["Most common cause of polycythemia","Increased erythropoietin","Erythropoietin independent growth of red cell progenitors","Intrinsic abnormality of hematopoietic precursors"],"a":1,"e":"Polycythaemia vera (PV) is a clonal disorder characterized by increased production of all myeloid elements resulting in pancytosis (i.e increased red cells, granulocytes, platelets) in the absence of any recognizable cause. The term ‘polycythemia vera’ or ‘polycythemia rubra vera’ is used for primary or idiopathic polycythemia only and is the most common of all the myeloproliferative disorders. Secondary polycythemia or erythrocytosis, on the other hand, may occur secondary to several causes e.g. high altitude, cardiovascular disease, a pulmonary disease with alveolar hypoventilation, heavy smoking, inappropriate increase in erythropoietin (renal cell carcinoma, hydronephrosis, hepatocellular carcinoma, cerebellar hemangioblastoma, massive uterine leiomyoma); clinical features: headache, vertigo, tinnitus, visual alterations syncope or even coma. Increased risk of thrombosis due to accelerated atherosclerosis. Increased risk of hemorrhages due to increased blood volume and intrinsic platelet dysfunction e.g. epistaxis, peptic ulcer disease Splenomegaly producing abdominal fullness. Pruritus, especially after a bath","pyqMatches":[{"year":"2015","no":457,"q":"Following are seen in polycythemia vera except:","o":["Most common cause of polycythemia","Increased erythropoietin","Erythropoietin independent growth of red cell progenitors","Intrinsic abnormality of hematopoietic precursors"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6344, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 184, '{"id":6344,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":184,"q":"Most common lung cancer in non- smokers is:","o":["Adenocarcinoma","Squamous cell carcinoma","Oat cell carcinoma","None of the above"],"a":0,"e":"Ans. A: Adenocarcinoma Adenocarcinoma accounts for 40% of non-small cell lung cancers. It usually originates in peripheral lung tissue. Most cases of adenocarcinoma are associated with smoking; however, among people who have never smoked (\"never-smokers\"), adenocarcinoma is the most common form of lung cancer. A subtype of adenocarcinoma, the bronchioloalveolar carcinoma, is more common in female never-smokers, and may have different responses to treatment.","pyqMatches":[{"year":"2015","no":463,"q":"Most common lung cancer in non- smokers is:","o":["Adenocarcinoma","Squamous cell carcinoma","Oat cell carcinoma","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6345, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 185, '{"id":6345,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":185,"q":"Most common feature of sarcoidosis on chest X-ray is: March 2011, March 2013","o":["Pleural effusion","Cavitation","Bilateral hilar lymphadenopathy","Pneumothorax"],"a":2,"e":"Ans. C: Bilateral hilar lymphadenopathy Sarcoidosis may be discovered unexpectedly on routine chest films as bilateral hilar lymphadenopathy Sarcoidosis/Sarcoid/Besnier-Boeck disease/Besnier-Boeck- Schaumann disease It is a disease in which abnormal collections of chronic inflammatory cells (granulomas) form as nodules in multiple organs. The combination of erythema nodosum, bilateral hilar lymphadenopathy and arthralgia is called Lofgren syndrome. This syndrome has a relatively good prognosis Chest X-ray changes are divided into four stages","pyqMatches":[{"year":"2013","no":1761,"q":"Most common feature of sarcoidosis on chest X-ray is: March 2011, March 2013","o":["Pleural effusion","Cavitation","Bilateral hilar lymphadenopathy","Pneumothorax"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6346, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 186, '{"id":6346,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":186,"q":"Multiple sinuses from infection of great toe is mainly caused by: September 2007","o":["Tuberculosis","Actinomycetes","Trichosporum","Histoplasmosis"],"a":1,"e":"Ans. B: Actinomycetes Mycetoma is a chronic localized granulomatous inflammatory lesion common in the tropics and sub-tropics. Multiple siAuses, soft tissue swelling and discharge of coloured granules characterize a mycetoma foot. Chronic sinuses discharging granules are caused by (1) Eumycetes (true fungi), (2) Schizomycetes, which includes Actinomycosis (aerobic higher filamentous bacteria) and Botryomycosis (bacterial infection). - Actinomycosis is often caused by Actinomadura or Nocardia species wherein it gains entry after penetrating trauma (splinter, gravel or thorn prick). Young males are commonly affected and 75% of the lesions occur in the lower limbs. The disease slowly progresses from a nodule to multiple sinuses discharging coloured granules. Involvement of bone is late following dermal and soft tissue spread. - Botryomycosis (a misnomer), a chronic suppurative infection is caused by bacteria involving skin or viscera . This rare condition mimics a deep mycotic infection and is often caused by mimics a deep mycotic infection and is often caused by Staphylococcus or Pseudomonas species of bacteria. The feet and hands are commonly affected and penetrating trauma may be a predisposing factor. It usually presents as a nodule, sinus or ulcer, which is initially localized. The diagnosis of actinomycosis is based on clinical findings, demonstration of characteristic granules and culture of the organism from a deep tissue biopsy. Immunological studies (counter immuno electrophoresis and ELISA) are also used. Botryomycosis is diagnosed based on a positive gram''s stain and culture; negative fungal cultures and demonstration of the characteristic botryomycotic granules at histopathology from a deep biopsy. In endemic areas, subcutaneous swelling with sinuses should be considered as mycetoma unless proved otherwise. The differential diagnosis includes chronic osteomyelitis, tuberculosis and chronic abscesses.","pyqMatches":[{"year":"2012","no":117,"q":"Multiple sinuses from infection of great toe is mainly caused by: September 2007","o":["Tuberculosis","Actinomycetes","Trichosporum","Histoplasmosis"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6347, 'Pathology', 'Genetic Disorders', 'Moderate', 'Pathology', 187, '{"id":6347,"subject":"Pathology","chapter":"Genetic Disorders","difficulty":"Moderate","source":"Pathology","sourceNo":187,"q":"Barr body is NOT seen in: PGI 07; WB 08","o":["Turner syndrome","Klinefelter syndrome","Down''s syndrome","Marfan''s syndrome"],"a":0,"e":"Ans. Turner syndrome Barr body (Sex - chromatin) It is a densely staining inactivated condensed ''X'' chromosome that is present in each somatic cells of female. o It is found in the nucleus. It is used as a test of genetic femaleness -4 it is possible to determine the genetic sex of an individual according as to whether there is a chromatin mass present on the inner surface of the nuclear membrane of cells with resting or intermitent nuclei. Remember following fact and the question will seem very easy. Chromatid body (Barr body or sex chromatin) is derived from one of the two X-chromosomes which becomes inactivated. The numer of Barr bodies is thus one less than the number of X- chromosomes.","pyqMatches":[{"year":"2014","no":422,"q":"Barr body is NOT seen in: PGI 07; WB 08","o":["Turner syndrome","Klinefelter syndrome","Down''s syndrome","Marfan''s syndrome"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6348, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 188, '{"id":6348,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":188,"q":"Compensatory mechanism in acute hemorrhage?","o":["Decreased myocardial contractility","Decreased heart rate","Increased heart rate","Increased respiratory rate"],"a":2,"e":"Ans. is ''c'' i.e., Increased heart rate Compensatory mechanisms in acute hemorrhage In acute hemorrhage there is compensatory sympathetic stimulation which causes :? 1) Generalized vasoconstriction with increased total peripheral resistance (TFR). 2) Increased heart rate (tachycardia). 3) Increased cardiac contractility. 4) Increased renin release causing sodium and water retention through RAA system. 5) Shift of fluid from intracellular and interstitial space into vascular space.","pyqMatches":[{"year":"2014","no":143,"q":"Compensatory mechanism in acute hemorrhage?","o":["Decreased myocardial contractility","Decreased heart rate","Increased heart rate","Increased respiratory rate"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6349, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 189, '{"id":6349,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":189,"q":"Prostaglandins are produced by ?","o":["Neutrophils","Endothelium","Macrophages","All of the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above","pyqMatches":[{"year":"2014","no":185,"q":"Prostaglandins are produced by ?","o":["Neutrophils","Endothelium","Macrophages","All of the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6350, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 190, '{"id":6350,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":190,"q":"Sirtuins are associated with ?","o":["Antioxidant mechanism in body","Logetivity of life span","Regeneration of liver after partial resection","Carcinogenesis in human"],"a":1,"e":"Ans. is ''b'' i.e., Logetivity of life span","pyqMatches":[{"year":"2013","no":244,"q":"Sirtuins are associated with ?","o":["Memory","Metabolism","Vision","Olfaction"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":233,"q":"Sirtuins are associated with ?","o":["Memory","Metabolism","Vision","Olfaction"],"a":1,"source":"NEET_2014_Paper.pdf"},{"year":"2014","no":234,"q":"Sirtuins are associated with ?","o":["Antioxidant mechanism in body","Logetivity of life span","Regeneration of liver after partial resection","Carcinogenesis in human"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6351, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 191, '{"id":6351,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":191,"q":"Receptor for BDNF ?","o":["TrK-A","TrK-B","TrK-C","None"],"a":1,"e":"Ans. is ''B'' i.e., TrK-B","pyqMatches":[{"year":"2014","no":180,"q":"Receptor for BDNF ?","o":["TrK-A","TrK-B","TrK-C","None"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6352, 'Pathology', 'Hematology', 'Easy', 'Pathology', 192, '{"id":6352,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":192,"q":"Leukocyte migration through endothelium is induced by ?","o":["Selectin","N CAM","C CAM","PECAM"],"a":3,"e":"Ans. is ''d'' i.e., PECAM Migration of the leukocytes through the endothelium is called transmigration or diapedesis. Transmigration of leukocytes occurs mainly in postcapillaryvenules. The molecules involved in transmigration are member of the immunoglobulin superfamily called CD31 or PECAM-1 (platelet endothelial cell adhesion molecule).","pyqMatches":[{"year":"2014","no":406,"q":"Leukocyte migration through endothelium is induced by ?","o":["Selectin","N CAM","C CAM","PECAM"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6353, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 193, '{"id":6353,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":193,"q":"Large granular lymphocytes are ?","o":["B cells","NK cells","T cell","Plasma cells"],"a":1,"e":"Ans. is ''b'' NK cells Null cells (Large granular lymphocytes) Null cells are called so because they lack features of surface markers of both B and T lymphocytes. The account for 5 to 10% of peripheral blood lymphocytes. They are also called \"large granular lymphocytes (LGL)\" as they contain large azurophilic cytoplasmic granules. Members of this group are: a) Antibody dependent cytotoxic cells (ADCC) b) Natural killer cells (NK Cells)","pyqMatches":[{"year":"2014","no":399,"q":"Large granular lymphocytes are ?","o":["B cells","NK cells","T cell","Plasma cells"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6354, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 194, '{"id":6354,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":194,"q":"Thymic hyperplasia is seen in ?","o":["Thymoma","Thymic lymphoma","Myasthenia gravis","Scleroderma"],"a":2,"e":"Ans. is ''c'' i.e., Mysthenia gravis Thymic hvperplasia The term thymic hyperplasia usually applies to the appearance of B- cell germinal centers within the thymus, a finding that is referred to as thymic follicular hyperplasia. Such B-cell follicles are present in only small numbers in the normal thymus. It can occur in a number of chronic inflammatory and immunologic states, but it is most frequently encountered in myasthenia gravis (65% to 75% of cases). Similar thymic changes are sometimes encountered in Graves disease, systemic lupus erythematosus, scleroderma, rheumatoid arthritis, and other autoimmune disorders.","pyqMatches":[{"year":"2016","no":489,"q":"Thymic hyperplasia is seen in ?","o":["Thymoma","Thymic lymphoma","Myasthenia gravis","Scleroderma"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6355, 'Pathology', 'Inflammation', 'Moderate', 'Pathology', 195, '{"id":6355,"subject":"Pathology","chapter":"Inflammation","difficulty":"Moderate","source":"Pathology","sourceNo":195,"q":"Which one of the following statements is correct regarding chronic granulomatous disease ?","o":["It is an autosomal dominant disease","It is characterized by abnormal bacterial phagocytosis","Recurrent streptococcal infections are usual in this disease","Nitrobluetetrazolium test is useful for screening"],"a":3,"e":"Ans. is ''d'' i.e., Nitrobluetetrazolium test is useful for screening Leukocytes from the patients of chronic granulomatous disease fail to reduce nitroblue tetrazolium (NBT) during phagocytosis. This property has been used as a screening method (NBT test) for the diagnosis of chronic granulomatous disease. Chronic granulomatous disease (CGD) It is a group of disorders of granulocyte and monocyte oxidative metabolism. Inheritance X-linked (Most common) Autosomal recessive Phagocytosis is normal but leukocytes do not undergo degranulation following phagocytosis. The diminished H202 production appears to be the major reason for defective bactericidal defect. Mutation in the genes for the four proteins that assemble at the plasma membrane account for all patients with CGD: Two proteins form the heterodimer cytochrome b - 558 in the plasma membrane. Two other proteins interact with cytochrome after cell activation to form NADPH oxidase required for Hydrogen peroxide production. The bacteria involved in recurrent infections are catalase positive pyogenic pathogens such as staphylococci and coliforms. Catalase negative pathogens such as streptococci and pneumococci are handled normally. There is excessive inflammation with granulomas formation.","pyqMatches":[{"year":"2016","no":370,"q":"Which one of the following statements is correct regarding chronic granulomatous disease ?","o":["It is an autosomal dominant disease","It is characterized by abnormal bacterial phagocytosis","Recurrent streptococcal infections are usual in this disease","Nitrobluetetrazolium test is useful for screening"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6356, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 196, '{"id":6356,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":196,"q":"Lacunar type of reed sternberg cell is seen in ?","o":["Nodular sclerosis","Lymphocyte predominance","Mixed cellularity","Lymphocyte depletion"],"a":0,"e":"Ans. is ''a'' i.e., Nodular sclerosis","pyqMatches":[{"year":"2014","no":463,"q":"Lacunar type of reed sternberg cell is seen in ?","o":["Nodular sclerosis","Lymphocyte predominance","Mixed cellularity","Lymphocyte depletion"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6357, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 197, '{"id":6357,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":197,"q":"Activation of naïve B lymphocytes by protein an​tigens is?","o":["T Cell independent","NK cell dependent","NK cell independent","T cell dependent"],"a":3,"e":"Ans. is d i.e., T cell dependent Upon activation, B lymphocytes proliferate and then differentiate into plasma cells that secrete different classes of antibodies with distinct functions. Antibody responses to most protein antigens require T cell help and are said to be T-dependent. Many polysaccharide and lipid antigens cannot be recognized by T cells but have multiple identical antigenic determinants (epitopes) that are able to engage many antigen receptor molecules on each B cell and initiate the process of B-cell activation; these responses are said to be T-independent.","pyqMatches":[{"year":"2014","no":391,"q":"Activation of naïve B lymphocytes by protein an​tigens is?","o":["T Cell independent","NK cell dependent","NK cell independent","T cell dependent"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6358, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 198, '{"id":6358,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":198,"q":"Mantoux test is based on which hypersensitivity?","o":["Type 1","Type 2","Type 3","Type 4"],"a":3,"e":"Ans. is ''d'' i.e., Type 4 Following are the examples of type 4 hypersensitivity reactions :- Type 1 diabetes mellitus Hashimoto thyroiditis Crohn''s disease Multiple sclerosis Contact dermatitis Mantoux test","pyqMatches":[{"year":"2014","no":392,"q":"Mantoux test is based on which hypersensitivity?","o":["Type 1","Type 2","Type 3","Type 4"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6359, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 199, '{"id":6359,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":199,"q":"Ladder tears are ?","o":["Spiral tears of aortic intima","Vertical tears of aortic intima","Horizontal tears of aortic intima","Oblique tears of aortic intima"],"a":2,"e":"Ans. is ''c'' i.e., Horizontal tears of aortic intima Ladder tears are the horizontal tears of intima It is injury to aorta due to deceleration. It is so called be cause it resembles the rungs of a ladder.","pyqMatches":[{"year":"2014","no":450,"q":"Ladder tears are ?","o":["Spiral tears of aortic intima","Vertical tears of aortic intima","Horizontal tears of aortic intima","Oblique tears of aortic intima"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6360, 'Pathology', 'Genetic Disorders', 'Easy', 'Pathology', 200, '{"id":6360,"subject":"Pathology","chapter":"Genetic Disorders","difficulty":"Easy","source":"Pathology","sourceNo":200,"q":"Pendred syndrome due to mutation of ?","o":["Bartillin","Pendrin","Fibrillin","Reticulin"],"a":1,"e":"Ans. is `b'' i.e., Pendrin Pendred syndrome or Pendred disease :? Pendred syndrome or Pendred disease is a genetic disorder leading to congenital bilateral (both sides) senso​rineural hearing loss and goitre with occasional hypothyroidism. It has been linked to mutations in the PDSgene, which codes for the pendrin protein (solute carrier family 26, member 4, SLC26A4). The gene is located on the long arm of chromosome 7 (7q31). It is an autosomal recessive disorder.","pyqMatches":[{"year":"2014","no":417,"q":"Pendred syndrome due to mutation of ?","o":["Bartillin","Pendrin","Fibrillin","Reticulin"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6361, 'Pathology', 'Hematology', 'Moderate', 'Pathology', 201, '{"id":6361,"subject":"Pathology","chapter":"Hematology","difficulty":"Moderate","source":"Pathology","sourceNo":201,"q":"Which of the following is not true about idiopathic thrombocytopenic purpura?","o":["Antibodies of IgM class","Autoantibodies to Gp IIb/ Ilia or IB IX","Increased megakaryocytes in bone marrow","Spleen is normal in size"],"a":0,"e":"Ans. is ''a'' i.e., Antibodies of IgM class I dopathic thrombocytopenic purpura :? There are two clinical subtypes of primary I.T.P, acute and chronic both are autoimmune disorders in which platelet destruction results from formation of antiplatelet antibodies. Pathogenesis Chronic ITP is caused by the formation of autoantibodies against platelet membrane glycoproteins most often Hb-lIla or Ib-IX. In overwhelming majority of cases the antiplatelet antibodies are of the .IgL, class. The mechanism of platelet destruction is similar to that seen in autoimmune hemolytic anemias. Opsonized platelets are rendered susceptible to phagocytosis by the cells of the mononuclear phagocyte system. The spleen is the major site of the destruction of platelets. Pathology The principal morphologic lesions of thrombocytopenic purpura are found in the spleen and bone marrow but they are not diagnostic. The point to stress is that despite the increased destruction of platelets in spleen, the spleen size remains normal. On histological examination there is congestion of the sinusoids and hyperactivity and enlargement of the splenic follicles manifested by the formation of prominent germinal centres. Sometimes scattered megakaryocytes are found within the sinuses and sinusoidal walls. This represents a very mild form of extramedullary hematopoiesis. These splenic findings are not sufficiently distinctive to be considered diagnostic. Bone Marrow Bone marrow reveals a modestly increased number of megakaryocytes. These findings are not specific for autoimmune thrombocytopenic purpura, but merely reflect accelerated thrombopoiesis, being found in most forms of thrombocytopenia resulting from increased platelet destruction. The importance of bone marrow examination is to rule out thrombocytopenias resulting from bone marrow failure. A decrease in the number of megakaryocytes goes against the diagnosis of I.T.P.","pyqMatches":[{"year":"2014","no":471,"q":"Which of the following is not true about idiopathic thrombocytopenic purpura?","o":["Antibodies of IgM class","Autoantibodies to Gp IIb/ Ilia or IB IX","Increased megakaryocytes in bone marrow","Spleen is normal in size"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6362, 'Pathology', 'Infectious Diseases', 'Moderate', 'Pathology', 202, '{"id":6362,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Moderate","source":"Pathology","sourceNo":202,"q":"Macrophage activation syndrome characterized by all except ?","o":["Activation of CD 8 + T cells","Presence of cytokine storm","It is the other name for hemophagocytic lymphohistiocytosis","Low levels of plasma ferretin"],"a":3,"e":"Ans. is ''d'' i.e., Low levels of plasma ferretin Hemophagocytic Lymphohistiocytosis Hemophagocytic lymphohistiocytosis (HLH) is a reactive condition marked by cytopenias and signs and symp​toms of systemic inflammation related to macrophage activation. For this reason, it is also sometimes referred to as macrophage activation syndrome. Pathogenesis The common feature of all forms of HLH is systemic activation of macrophages and CD8+ cytotoxic T cells. The activated macrophages phagocytose blood cell progenitors in the marrow and formed elements in the periph​eral tissues, while the \"stew\"of mediators released from macrophages and lymphocytes suppress hematopoiesis and produce symptoms of systemic inflammation. These effects lead to cytopenias and a shock-like picture, sometimes referred to as \"cytokine storm\" or the systemic inflammatory response syndrome. Familial forms of HLH are associated with several different mutations, all of which impact the ability of cytotoxic T cells and NK to properly form or deploy cytotoxic granules. The most common trigger for HLH is infection, particularly with Epstein-Barr virus (EBV). Clinical Features Most patients present with an acute febrile illness associated with splenomegaly and hepatomegaly. Hemophagocytosis is usually seen on bone marrow examination, but is neither sufficient nor required to make the diagnosis. Laboratory studies typically reveal anemia, thrombocytopenia, and very high levels of plasma ferritin and soluble IL-2 receptor, both indicative of severe inflammation, as well as elevated liver function tests and triglyceride levels, both related to hepatitis. Coagulation studies may show evidence of disseminated intravascular coagulation. If untreated, this picture can progress rapidly to multiorgan failure, shock, and death. Treatment Involves the use of immunosuppressive drugs and \"mild\" chemotherapy. Patients with germline mutations that cause HLH or who have persistent/resistant disease are candidates for hematopoietic stem cell transplantation. Without treatment, the prognosis is grim, particularly in those with familial forms of the disease, who typically survive for less than 2 months.","pyqMatches":[{"year":"2014","no":394,"q":"Macrophage activation syndrome characterized by all except ?","o":["Activation of CD 8 + T cells","Presence of cytokine storm","It is the other name for hemophagocytic lymphohistiocytosis","Low levels of plasma ferretin"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6363, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 203, '{"id":6363,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":203,"q":"HLA associated with rheumatoid arthritis is ?","o":["HLA B27","HLA DR 4","HLABI9","HLA DR2"],"a":1,"e":"Ans. is `b'' i.e. HLA DR4 Associated with the development of Rheumatoid arthritis • HLA - DR 4 • HLA - DR 10 • HLA - DR 9 Protects against the development of Rheumatoid arthritis • HLA - DR 5 • HLA - DR 2 • HLA - DR 3","pyqMatches":[{"year":"2014","no":395,"q":"HLA associated with rheumatoid arthritis is ?","o":["HLA B27","HLA DR 4","HLABI9","HLA DR2"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6364, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 204, '{"id":6364,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":204,"q":"Hepatitis B associated with ?","o":["Wegener''s granulomatosis","Systemic lupus erythmatosus","Polyarteritis nodosa","Sjogren syndrome"],"a":2,"e":"Ans. is ''c'' i.e., Polyatrteritis nodosa The hepatitis B surface antigen is present in 25% of patients with Polyarteritis Nodosa. Hepatitis C antibody is present in patients with essential mixed cryoglobinuria and rarely in patients with poly arteritis nodosa.","pyqMatches":[{"year":"2014","no":451,"q":"Hepatitis B associated with ?","o":["Wegener''s granulomatosis","Systemic lupus erythmatosus","Polyarteritis nodosa","Sjogren syndrome"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6365, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 205, '{"id":6365,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":205,"q":"Normal upper limit of CA - 125 is ?","o":["25 U/ ml","45 U/ ml","65 U/ ml","85 U/ ml"],"a":0,"e":"Ans. is `a'' i.e., 25 U/ ml The normal value is less than 35 U/mL 1) Carcinoembryonic antigen (CEA) It is a glycoprotein produced by fetal gut, pancreas and liver. It is used as tumor marker for colorectal cancer (major use), lung cancer, breast cancer and ovarian cancer. It is also increased in non-neoplastic conditions like alcoholic cirrhosis, hepatitis, IBD (CD, UC), smoking and pancreatitis. In colorectal cancer it is used for screening; response and follow up after surgery (CEA should diseapper in 6 weeks after resection), prognosis (higher levels suggests high tumor burden) and to see recurrence on follow up. CEA antigen has no correlation with hepatic metastasis. CEA lacks sensitivity as well as specificity, hence cannot be used to confirm the diagnosis. 2) Alpha-feto protein (AFP) It is a glycoprotein synthesized normally early in fetal life by yolk sac, fetal liver and fetal GIT. It is structurally and genetically related to albumin. AFP is raised in liver cancer (hepatocellular carcinoma), lung carcinoma, pancreatic carcinoma, colon carcinoma, and non- seminoma germ cell tumor of testis/ovary (yolk sac tumor/endodermal sinus tumor, embryonal carcinoma, teratoma). AFP is also raised in some non-neoplastic conditions like cirrhosis, hepatitis, and pregnancy. 3) Human chorionic gonadotropin (HCG) It is a placental hormone synthesized by syncytiotrophoblasts. It is glycoprotein with two subunits (dimer) : a-subunit and /3-subunit. But only the P subunit of HCG is typically measured as a tumour marker because of specificity of the 13 subunit. The i3 subunit of HCG has unique sequences that are not shared with other human glycoprotein hormones. It is detected by radioimmunoassay using antibodies to the 13 chain. a-HCG is not used as tumour marker because a unit of the FSH, LH and TSH are identical. So there can be cross reactivity between a subunits of these hormone. That is why in case of testicular tumours the patients also undergo simultaneous assay of LH to be certain that the marker detected is 13 HCG. HCG (13-HCG) is raised in gestational trophoblastic disease (hydatidiform moles), gonadal germ cell tumor (embryonal carcinoma, choriocarcinoma), and pregnancy. 4) CA-125 Most important cancer with elevated CA-125 is epithelial ovarian cancer. CA-125 is also elevated in cancers of endometrium, cervix, fallopian tubes, pancreas, breast, lung and colon. Non-neoplastic conditions causing elevation of CA-125 are pregnancy, mensturation, endometriosis, PID, abdominal TB, peritonitis and uterine fibroid. Tumor markers for testicular/ovarian tumor","pyqMatches":[{"year":"2014","no":431,"q":"Normal upper limit of CA - 125 is ?","o":["25 U/ ml","45 U/ ml","65 U/ ml","85 U/ ml"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6366, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 206, '{"id":6366,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":206,"q":"Which of the following interleukin is secreted by T helper 2 cells?","o":["IL 11","IL 7","IL 1","IL 13"],"a":3,"e":"Ans. is ''d'' i.e., IL 13 A) T helper - 1 (TF,'') secretes 4 IL-2 and interferon - y B) T helper - 2 (T0 2) secretes -> IL-4, IL-5, IL-6, IL-13","pyqMatches":[{"year":"2014","no":396,"q":"Which of the following interleukin is secreted by T helper 2 cells?","o":["IL 11","IL 7","IL 1","IL 13"],"a":3,"source":"NEET_2014_Paper.pdf"},{"year":"2016","no":386,"q":"Which of the following interleukin is secreted by T helper 2 cells?","o":["IL 11","IL 7","IL 1","IL 13"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2014","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6367, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 207, '{"id":6367,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":207,"q":"Atopy in hypersensitivity is ?","o":["Systemic type I hypersensitivity","Local type I hypersensitivity","Systemic type II hypersensitivity","Local type II hypersensitivity"],"a":1,"e":"Ans. is `b'' i.e., Local type I hypersensitivity Anaphylaxis -3 Acute, potentially fatal, systemic. Atopy -›Chronic, Nonfatal, Localized.","pyqMatches":[{"year":"2014","no":393,"q":"Atopy in hypersensitivity is ?","o":["Systemic type I hypersensitivity","Local type I hypersensitivity","Systemic type II hypersensitivity","Local type II hypersensitivity"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6368, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 208, '{"id":6368,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":208,"q":"Inheritance pattern of myotonic dystrophy is ?","o":["Autosomal recessive","Autosomal dominant","X linked dominant","X linked recessive"],"a":1,"e":"Ans. is `b'' i.e., Autosomal dominant Myotonic dystrophy Myotonic dystrophy is an autosomal dominant multisys- tem disorder associated with skeletal muscle weakness, cataracts, endocrinopathy, and cardiomyopathy","pyqMatches":[{"year":"2014","no":418,"q":"Inheritance pattern of myotonic dystrophy is ?","o":["Autosomal recessive","Autosomal dominant","X linked dominant","X linked recessive"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6369, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 209, '{"id":6369,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":209,"q":"Gene responsible for Wilson disease is situated on which chromosome?","o":["Chromosome 11","Chromosome 12","Chromosome 13","Chromosome 14"],"a":2,"e":"Ans. is ''c'' i.e., Chromosome 13 Wilson disease is an autosomal recessive disorder caused by mutation of the ATP7B gene, resulting in impaired copper excretion into bile & failure to incorporate copper into ceruloplasmin. The ATP 7 B gene is located on chromosome 13.","pyqMatches":[{"year":"2014","no":421,"q":"Gene responsible for Wilson disease is situated on which chromosome?","o":["Chromosome 11","Chromosome 12","Chromosome 13","Chromosome 14"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6370, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 210, '{"id":6370,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":210,"q":"Antischkow cells are ?","o":["Modified macrophages","Modified neutrophils","Modified B cells","Modified RBCs"],"a":0,"e":"Ans. is ''a'' i.e., Modified macrophages Pathologic Features of Acute Rheumatic Fever Aschoff bodies focal inflammatory lesions seen in acute rheumatic fever consisting of foci of T lymphocytes, occasional plasma cells, and plump activated macrophages. These activated macrophages called Anitschkow cells (pathognomonic for Rheumatic Fever) have abundant cytoplasm and central round-to- ovoid nuclei (occasionally binucleate) in which the chromatin condenses into a central, slender, wavy ribbon (hence also called \"caterpillar cells\"). Pancarditis - During acute RF, diffuse inflammation and Aschoff bodies may be found in any of the three layers of the heart, resulting in pericarditis, myocarditis, or endocarditis Verrucae are small (1 to 2 mm) vegetations overlying necrotic foci and along the lines of closure of valves. o MacCallum plaques are irregularly thickened subendocardial lesions usually in the left atrium. o Mitral stenosis - Fish Mouth or Button - Hole stenosis.","pyqMatches":[{"year":"2014","no":456,"q":"Antischkow cells are ?","o":["Modified macrophages","Modified neutrophils","Modified B cells","Modified RBCs"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6371, 'Pathology', 'Organ System Pathology', 'Hard', 'Pathology', 211, '{"id":6371,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Hard","source":"Pathology","sourceNo":211,"q":"Patient with chronic hypertension will show fol​lowing changes on histology of kidney","o":["Hyaline arteriosclerosis","Hyperplastic arteriosclerosis","Onion skin lesions","Vessel lumen dilatation"],"a":0,"e":"Ans. is ''a'' i.e., Hyaline arteriosclerosis Hypertension is associated with two forms of small blood vessels disease ?","pyqMatches":[{"year":"2014","no":453,"q":"Patient with chronic hypertension will show fol​lowing changes on histology of kidney","o":["Hyaline arteriosclerosis","Hyperplastic arteriosclerosis","Onion skin lesions","Vessel lumen dilatation"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6372, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 212, '{"id":6372,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":212,"q":"NK cell shows presence of ?","o":["CD 44","CD 16","CD 54","CD 32"],"a":1,"e":"Ans. is ''b'' i.e., CD 16 These cells possess cytotoxic activity against virus infected cells, tumor cells and transplanted foreign cells. Cytotoxicity of NK cells is neither antibody dependent nor MHC restricted. Activity is nonimmune as it does not require antigenic stimulation. NK-cells are positive for CD16 and CD56. NK cells are usually negative for CD3, but a subset is positive for CD3 called NK/T-cells.","pyqMatches":[{"year":"2014","no":400,"q":"NK cell shows presence of ?","o":["CD 44","CD 16","CD 54","CD 32"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6373, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 213, '{"id":6373,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":213,"q":"Non professional antigen presenting cell is A/E ?","o":["Endothelial cell","Epidermal cell","Fibroblasts","Red blood cells"],"a":3,"e":"Ans. is ''d'' i.e., Red blood cells Non-professional antigenpresenting cell A non-professional APC does not constitutively express the Major Histocompatibility Complex class II (MHC class II) proteins required for interaction with naive T cells; these are expressed only upon stimulation of the non? professional APC by certain cytokines such as IFN-y. All nucleated cells express the Major Histocompatibility Complex class I necessary to be considered a non​professional APC. As erythrocytes do not have a nucleus, they are one of the few cells in the body that cannot display antigens.","pyqMatches":[{"year":"2014","no":398,"q":"Non professional antigen presenting cell is A/E ?","o":["Endothelial cell","Epidermal cell","Fibroblasts","Red blood cells"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6374, 'Pathology', 'Hematology', 'Easy', 'Pathology', 214, '{"id":6374,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":214,"q":"Blood is stored at what temperature in blood bank?","o":["-2 to -4 degrees Celsius","-2 to 0 degrees Celsius","1 to 6 degrees Celsius","6 to 12 degrees Celsius"],"a":2,"e":"Ans. is ''c'' i.e., 1 to 6 degrees Celsius Storage temperature of blood : 1-6°C Storage temperature of packed RBCs : 40°C Storage temperature of FFP : -20°C Storage temperature of platelets: 20-24°C","pyqMatches":[{"year":"2014","no":478,"q":"Blood is stored at what temperature in blood bank?","o":["2 to -4 degrees Celsius","2 to 0 degrees Celsius","1 to 6 degrees Celsius","6 to 12 degrees Celsius"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6375, 'Pathology', 'Hematology', 'Easy', 'Pathology', 215, '{"id":6375,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":215,"q":"Birbeck granules in cytoplasm is seen in ?","o":["Langerhans cell histiocytosis","Hodgkin''s lymphoma","Non hodgkins lymphoma","Gastrointestinal stromal tumor"],"a":0,"e":"Ans. is ''a'' i.e., Langerhans cell histiocytosis Birbeck granules are characteristic of langerhans cell histiocytosis Tumour cells in the langerhan''s cell histiocvtosis are derived from dendritic cells and express :​ S-100 CD1a HLA-DR These cells are characterized by the presence of birbeck granules in their cytoplasm unde rthe electron micro​scope, Birbeck granules have pentalaminar, rodlike tuular appearance and sometimes a dilated terminal end (tennis-racket appearance)","pyqMatches":[{"year":"2014","no":465,"q":"Birbeck granules in cytoplasm is seen in ?","o":["Langerhans cell histiocytosis","Hodgkin''s lymphoma","Non hodgkins lymphoma","Gastrointestinal stromal tumor"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6376, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 216, '{"id":6376,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":216,"q":"Reticulocytes are stained by ?","o":["Supravital stain","Purssian blue stain","H and E stain","Reticulin stain"],"a":0,"e":"Ans. is ''a'' i.e., Supravital stain Usually supravital stains (methylene blue and Brilliant cresyl blue) are used for reticulocytes.","pyqMatches":[],"pyqYears":[]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6377, 'Pathology', 'Hematology', 'Easy', 'Pathology', 217, '{"id":6377,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":217,"q":"Most common type of hodgkins lymphoma is ?","o":["Lymphocyte predominant","Lymphocyte depletion","Nodular sclerosis","Mixed cellularity"],"a":2,"e":"Ans. is ''c'' i.e., Nodular sclerosis Best Prognosis Worst prognosis Most common HL Most common type HL in India Least common type HL Lymphocytic predominance type. —> Lymphocytic depletion type. — > Nodular sclerosis type. —> Mixed cellularity type. Lymphocytic depletion type","pyqMatches":[{"year":"2014","no":462,"q":"Most common type of hodgkins lymphoma is ?","o":["Lymphocyte predominant","Lymphocyte depletion","Nodular sclerosis","Mixed cellularity"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6378, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 218, '{"id":6378,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":218,"q":"Most common site for eosinophilic granuloma is?","o":["Radius","Skull","Lumbar vertebra","Femur"],"a":1,"e":"Ans. is ''b'' i.e., Skull The most common sites are skull bones, long bones, spinal vertebrae, mastoid and mandible.","pyqMatches":[{"year":"2014","no":467,"q":"Most common site for eosinophilic granuloma is?","o":["Radius","Skull","Lumbar vertebra","Femur"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6379, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 219, '{"id":6379,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":219,"q":"Replacement of columnar epithelium in respiratory tract to squamous epithelium is ?","o":["Hyperplasia","Hypoplasia","Metaplasia","None of the above"],"a":2,"e":"Ans. is `c'' i.e., Metaplasia Metaplasia Metaplasia is a reversible change in which one differentiated cell type is replaced by another differentiated cell type. Metaplasia represents an adaptive substitution of cells that are sensitive to stress by cell types better able to withstand the adverse environment.","pyqMatches":[{"year":"2014","no":368,"q":"Replacement of columnar epithelium in respiratory tract to squamous epithelium is ?","o":["Hyperplasia","Hypoplasia","Metaplasia","None of the above"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6380, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 220, '{"id":6380,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":220,"q":"Which is the best marker of SLE ?","o":["Anti Sm antibodies","Anti dsDNA antibodies","Anti histone antibodies","Anti Ro Antibodies"],"a":1,"e":"Ans. is ''b'' i.e., Anti dsDNA antibodies Antibodies to double - stranded DNA and the Smith (Sm) antigen are virtually diagnostic of SLE\".","pyqMatches":[{"year":"2014","no":416,"q":"Which is the best marker of SLE ?","o":["Anti Sm antibodies","Anti dsDNA antibodies","Anti histone antibodies","Anti Ro Antibodies"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6381, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 221, '{"id":6381,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":221,"q":"Most common cause of death in amyloidosis is ?","o":["Heart failure","Renal failure","Sepsis","None"],"a":0,"e":"Ans. is ''a'' i.e., Heart Failure `Most common cause of death is heart failure and/or abnormal cardiac rhythm'' Essentials pathology","pyqMatches":[{"year":"2014","no":413,"q":"Most common cause of death in amyloidosis is ?","o":["Heart failure","Renal failure","Sepsis","None"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6382, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 222, '{"id":6382,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":222,"q":"What is true about ulcerative colitis ?","o":["Involves rectum and then whole colon backwards","Involves only colon","Skip lesions seen","Ileum not involved"],"a":0,"e":"Ans. is- A. Involves rectum and then whole colon backwards Ulcerative colitis (UC) is a long-term condition that results in inflammation and ulcers of the colon and rectum.","pyqMatches":[{"year":"2014","no":1336,"q":"What is true about ulcerative colitis ?","o":["Involves rectum and then whole colon backwards","Involves only colon","Skip lesions seen","Ileum not involved"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6383, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 223, '{"id":6383,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":223,"q":"Execution caspases of apoptosis are ?","o":["Caspase 1 & 3","Caspase 3 & 5","Caspase 1 & 5","Caspase 3 & 7"],"a":3,"e":"Ans. is ''d'' i.e., Caspase 3 & 7","pyqMatches":[{"year":"2014","no":370,"q":"Execution caspases of apoptosis are","o":["Caspase 1 & 3","Caspase 3 & 5","Caspase 1 & 5","Caspase 3 & 7"],"a":3,"source":"NEET_2014_Paper.pdf"},{"year":"2014","no":371,"q":"Execution caspases of apoptosis are ?","o":["Caspase 1 & 3","Caspase 3 & 5","Caspase 1 & 5","Caspase 3 & 7"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6384, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 224, '{"id":6384,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":224,"q":"Neurofibromatosis shows which of the following mode of inheritance ?","o":["AD","AR","X linked dominant","X linked recessive"],"a":0,"e":"Ans. is ''a'' i.e., AD Neurofibromatosis shows autosomal dominant inheritance pattern Single gene disorders (Mendelian disorders) typically follow one of the three patterns of inharitance ? a. Autosomal dominance b. Autosomal recessive c. X-linked Autosomal dominant disorders Normally a gene pair has two alleles. When one allele becomes abnormal due to mutation it is called heterozygous state. When both the alleles become abnormal due to mutation it is called homozygous state. Autosomal dominant disorders are manifested in heterozygous state, i.e. only if one allel is abnormal the disease will be manifested.","pyqMatches":[{"year":"2014","no":419,"q":"Neurofibromatosis shows which of the following mode of inheritance ?","o":["AD","AR","X linked dominant","X linked recessive"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6385, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 225, '{"id":6385,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":225,"q":"Most common site of glomus tumor is ?","o":["Under fingernails","Under toenails","Neck","Axilla"],"a":0,"e":"Ans. is ''a'' i.e., Under fingernails Glomus tumor (Glomangioma) Benign tumor arising from the smooth muscle cells of the glomus body which is an arteriovenous anastomosis involved in thermoregulation. Most commonly present in the distal portion of the digits (under fingernails). Histologically, there is presence of branching vascular channels and stroma containing nests/aggregates of glomus cells arranged around vessels.","pyqMatches":[{"year":"2014","no":461,"q":"Most common site of glomus tumor is ?","o":["Under fingernails","Under toenails","Neck","Axilla"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6386, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 226, '{"id":6386,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":226,"q":"Normal reticulocyte count in newborn is -","o":["0 - 1%","1 - 1.5%","3 - 6%","6 - 9 %"],"a":2,"e":"Ans. is ''c'' i.e., 3 - 6% Normal reticulocyte count in adults is 1 - 1.5% and in newborns is 3 - 6 %","pyqMatches":[{"year":"2014","no":479,"q":"Normal reticulocyte count in newborn is","o":["0 - 1%","1 - 1.5%","3 - 6%","6 - 9 %"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6387, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 227, '{"id":6387,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":227,"q":"BRCA2 not associated with","o":["breast cancer","Prostate cancer","Ovarian cancer","Vulval cancer"],"a":3,"e":"Ans. is ''d'' i.e., Vulval cancer BRCA-1 er BRCA-2 are commonly associated with —> Carcinomas of ovary and breast. Less commonly BRAC-2 is also associated with —> Carcinomas of colon, prostate and pancreas. [Ref Robbin''s Vie p. 1076; Clinical Surgery by Michal M. Henry & Jeremy N. Thompson 2\"a/e p. 453]","pyqMatches":[{"year":"2014","no":441,"q":"BRCA2 not associated with","o":["breast cancer","Prostate cancer","Ovarian cancer","Vulval cancer"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6388, 'Pathology', 'Inflammation', 'Moderate', 'Pathology', 228, '{"id":6388,"subject":"Pathology","chapter":"Inflammation","difficulty":"Moderate","source":"Pathology","sourceNo":228,"q":"Which of the following is not a large vessel vasculitiis ?","o":["Takayasu arteritis","Cogan syndrome","Chrug strauss syndrome","Giant cell arteritis"],"a":2,"e":"Ans. is ''c'' i.e., Churg strauss syndrome Large vessel vasculitis : Giant cell arteritis (temporal arteritis), Takayasu arteritis, Cogan syndrome. Medium vessel vasculitis : PAN (classical PAN), kawasaki disease, Buerger''s disease. Small vessel vasculitis : HSP, Wegner''s granulomatosis, microscopic polyangitis, churg strauss syndrome, Cryoglobulinemia, SLE, idiopathic crescentic glomerulonephritis, Bechet''s syndrome, renal limited vasculitis.","pyqMatches":[{"year":"2014","no":460,"q":"Which of the following is not a large vessel vasculitiis ?","o":["Takayasu arteritis","Cogan syndrome","Chrug strauss syndrome","Giant cell arteritis"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6389, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 229, '{"id":6389,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":229,"q":"Trauma to breast causes which type of necrosis ?","o":["Coagualtive necrosis","Liquefactive necrosis","Caseous necrosis","Fat necrosis"],"a":3,"e":"Ans. is ''d'' i.e., Fat necrosis Fat necrosis Fat necrosis may be of two types : ? Enzymatic fat necrosis This is due to action of lipase on adipose tissue. It occurs most frequently in acute pancreatitis due to leakage of lipase. Depending on the severity of acute pancreatitis, fat necrosis may occur in : - a Adipose tissue contiguous to pancrease, retroperitoneal fat. Adipose tissue in anterior mediastinum. Bone marrow Omental and abdominal fat Nonenzymatic or Traumatic fat necrosis Occurs due to trauma Is seen in subcutaneous tissue of breast, thigh, and abdomen.","pyqMatches":[{"year":"2014","no":412,"q":"Trauma to breast causes which type of necrosis ?","o":["Coagualtive necrosis","Liquefactive necrosis","Caseous necrosis","Fat necrosis"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6390, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 230, '{"id":6390,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":230,"q":"Inhibin is tumor marker for ?","o":["Granulosa cell tumor","Malignant melanoma","Prolactinoma","Breast carcinoma"],"a":0,"e":"Ans. is ''a'' i.e., Granulosa cell tumor Granulosa cell tumor is positive for vimentin, inhibin, CD99.","pyqMatches":[{"year":"2014","no":434,"q":"Inhibin is tumor marker for ?","o":["Granulosa cell tumor","Malignant melanoma","Prolactinoma","Breast carcinoma"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6391, 'Pathology', 'Miscellaneous', 'Hard', 'Pathology', 231, '{"id":6391,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Hard","source":"Pathology","sourceNo":231,"q":"Following statement is true for hemophilia patients?","o":["All Females are carriers and all males are affected","All Males are carriers and all females are affected","Females are mostly carriers and all males are affected","Males are mostly carriers and all females are affected"],"a":2,"e":"Ans. is ''c'' i.e., Females are mostly carriers and all males are affected Hemophilia is an X-linked recessive hemorrhagic disease due to mutations in the F8 gene (hemophilia A or classic hemophilia) or F9 gene (hemophilia B). The disease affects I in 10,000 males worldwide, in all ethnic groups; hemophilia A represents 80% of all cases. Male subjects are clinically affected; women, who carry a single mutated gene, are generally asymptomatic. Family history of the disease is absent in 30% of cases and in these cases, 80% of the mothers are carriers of the de novo mutated allele.","pyqMatches":[{"year":"2014","no":477,"q":"Following statement is true for hemophilia patients?","o":["All Females are carriers and all males are affected","All Males are carriers and all females are affected","Females are mostly carriers and all males are affected","Males are mostly carriers and all females are affected"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6392, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 232, '{"id":6392,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":232,"q":"Which worm causes myocarditis ?","o":["Trichuris","Trichinella","Enterobius","Strogyloides"],"a":1,"e":"Ans. is ''b'' i.e., Trichinella Trichinosis is the most common helminthic disease causing myocarditis.","pyqMatches":[{"year":"2014","no":458,"q":"Which worm causes myocarditis ?","o":["Trichuris","Trichinella","Enterobius","Strogyloides"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6393, 'Pathology', 'Hematology', 'Easy', 'Pathology', 233, '{"id":6393,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":233,"q":"Giant platelets are seen in ?","o":["Bernard soulier syndrome","vWD","Polycythemia rubra vera","Leukemia"],"a":0,"e":"Ans. is ''a'' i.e., Bernard soulier syndrome Bernad Soulier disease - Defect in the platelet GpIb-IX complex BT, mild thrombocytopenia, deficient or low levels of platelet GpIb-IX complex by flowcytometry Ristocetin aggregation test is defective","pyqMatches":[{"year":"2014","no":473,"q":"Giant platelets are seen in ?","o":["Bernard soulier syndrome","vWD","Polycythemia rubra vera","Leukemia"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6394, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 234, '{"id":6394,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":234,"q":"LE cell is seen in ?","o":["Lupus erythmatosus","Lupus vulgaris","HNPCC","Medullary carcinoma of thyroid"],"a":0,"e":"Ans. is ''a'' i.e., Lupus erythematousus In SLE, antinuclear antibodies (AN Ps) can not penetrate intact cells. However, nuclei are exposed, ANA can bind to them. In tissues, nuclei of damaged cells react with ANAs, lose their chromatin pattern, and become homogeneous, to produce lupus - erythematous (LE) bodies or hemotoxylin bodies. When these LE bodies are engulfed by phagocytic cells (neutrophil or macrophage/monocyte), the phagocytic cells are called LE cells.","pyqMatches":[{"year":"2014","no":401,"q":"LE cell is seen in ?","o":["Lupus erythmatosus","Lupus vulgaris","HNPCC","Medullary carcinoma of thyroid"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6395, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 235, '{"id":6395,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":235,"q":"Pelger Huet anamoly shows presence of ?","o":["Hyposegmented neutrophil","Hypersegmented neutrophil","Unsegmented neutrophil","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Hyposegmented neutrophil Pelger Huet anomaly It is a genetic disorder with an autosomal dominant inheritance pattern. It is a blood laminopathy associated with the lamin B receptor. It is characterized by a white blood cell type known as a neutrophil whose nucleus is hyposegmented. Heterozygotes are clinically normal, although their neutrophils may be mistaken for immature cells, which may cause mistreatment in a clinical setting. Homozygotes tend to have neutrophils with rounded nuclei that do have some functional problems.","pyqMatches":[{"year":"2014","no":468,"q":"Pelger Huet anamoly shows presence of ?","o":["Hyposegmented neutrophil","Hypersegmented neutrophil","Unsegmented neutrophil","None of the above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6396, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 236, '{"id":6396,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":236,"q":"Sentinel lymph node biopsy is used for ?","o":["Melanoma","Basal cell carcinoma","Squamous cell carcionoma","Thyroid carcinoma"],"a":0,"e":"Ans. is ''a'' i.e., Melanoma Sentinel lymph node biopsy is used for breast carcinoma and melanoma.","pyqMatches":[{"year":"2014","no":445,"q":"Sentinel lymph node biopsy is used for ?","o":["Melanoma","Basal cell carcinoma","Squamous cell carcionoma","Thyroid carcinoma"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6397, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 237, '{"id":6397,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":237,"q":"Interleukin 2 is produced by","o":["T helper cells 1","T helper cells 2","Natural killer cells","Basophils"],"a":0,"e":"Ans. is ''a'' i.e., T helper cells 1 A) T helper - 1 (TF,'') secretes 4 IL-2 and interferon - y B) T helper - 2 (T0 2) secretes -> IL-4, IL-5, IL-6, IL-13","pyqMatches":[{"year":"2014","no":397,"q":"Interleukin 2 is produced by","o":["T helper cells 1","T helper cells 2","Natural killer cells","Basophils"],"a":0,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":405,"q":"Interleukin 2 is produced by","o":["T helper cells 1","T helper cells 2","Natural killer cells","Basophils"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6398, 'Pathology', 'Hematology', 'Easy', 'Pathology', 238, '{"id":6398,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":238,"q":"Popcorn cells are seen in which variety of hodgkin''s disease ?","o":["Nodular sclerosis","Mixed cellularity","Lymphocyte predominant","Lymphocyte depletion"],"a":2,"e":"Ans. is ''c'' i.e., Lymphocyte predominant Popcorn cells are found in lymphocytic predominant type of Hodgkin''s Lymphoma.","pyqMatches":[{"year":"2014","no":464,"q":"Popcorn cells are seen in which variety of hodgkin''s disease ?","o":["Nodular sclerosis","Mixed cellularity","Lymphocyte predominant","Lymphocyte depletion"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6399, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 239, '{"id":6399,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":239,"q":"Shape of birbeck granules is ?","o":["Tennis racket","Hockey stick","Bat","Ball"],"a":0,"e":"Ans. is ''a'' i.e., Tennis racket Under the electron microscope, Birbeck granules have a pentalaminar, rodlike, tubular appearance and some​times a dilated terminal end resembling tennis-racket appearance.","pyqMatches":[{"year":"2012","no":477,"q":"Shape of birbeck granules is ?","o":["Tennis racket","Hockey stick","Bat","Ball"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":466,"q":"Shape of birbeck granules is ?","o":["Tennis racket","Hockey stick","Bat","Ball"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6400, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 240, '{"id":6400,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":240,"q":"Lipid peroxidation of polyunsaturated lipids of subcellular membranes produces ?","o":["Lipofuscin","Hemosiderin","Both of above","None of above"],"a":0,"e":"Ans. is ''a'' i.e., Lipofuscin Lipofuscin is an insoluble pigment, also known as lipochrome or wear-and-tear pigment. Lipofuscin is composed of polymers of lipids and phospholipids in complex with protein, suggesting that it is derived through lipid peroxi- dation of polyunsaturated lipids of subcellular membranes.","pyqMatches":[{"year":"2014","no":373,"q":"Lipid peroxidation of polyunsaturated lipids of subcellular membranes produces ?","o":["Lipofuscin","Hemosiderin","Both of above","None of above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6401, 'Pathology', 'Hematology', 'Moderate', 'Pathology', 241, '{"id":6401,"subject":"Pathology","chapter":"Hematology","difficulty":"Moderate","source":"Pathology","sourceNo":241,"q":"Paraneoplastic syndrome Hypercalcemia of malignancy, is produced due to ectopic production of which hormone by lymphomas ?","o":["PTHrP","1,25 dihydroxyvitamin D","PGE2","Parathormone"],"a":1,"e":"Ans. is ''b'' i.e., 1, 25 dihydroxyvitamin D Parathyroid hormone-related protein (PTHrP) 1,25 dihydroxyvitamin D Parathyroid hormone (PTH) (rare) Prostaglandin E2 (PGE2) (rare)","pyqMatches":[{"year":"2014","no":447,"q":"Paraneoplastic syndrome Hypercalcemia of malignancy, is produced due to ectopic production of which hormone by lymphomas ?","o":["PTHrP","1,25 dihydroxyvitamin D","PGE2","Parathormone"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6402, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 242, '{"id":6402,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":242,"q":"HLA B51 is associated with ?","o":["Behcet''s disease","Chrug strauss syndrome","Microscopic polyangitis","Polyarteritis nodosa"],"a":0,"e":"Ans. is ''a'' i.e., Behcet''s disease Behcet''s disease :? Behcet disease is a small- to medium-vessel neutrophilic vasculitis that classically presents as a clinical triad of recurrent oral aphthous ulcers, genital ulcers, and uveitis. There can also be gastrointestinal and pulmonary manifestations, with disease mortality related to severe neuro​logic involvement or rupture of vascular aneurysms. There is an association with certain HLA haplotypes (HLA​B51, in particular)","pyqMatches":[{"year":"2014","no":410,"q":"HLA B51 is associated with ?","o":["Behcet''s disease","Chrug strauss syndrome","Microscopic polyangitis","Polyarteritis nodosa"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6403, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 243, '{"id":6403,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":243,"q":"PT is used to test ?","o":["Extrinsic and common pathway","Intrinsic and common pathway","Intrinsic pathway","Extrinsic pathwa"],"a":0,"e":"Ans. is ''a'' i.e., Extrinsic and common pathway Patients with hemophilia have deficiency of factor VIII that results in prolonged PTT.","pyqMatches":[{"year":"2014","no":474,"q":"PT is used to test ?","o":["Extrinsic and common pathway","Intrinsic and common pathway","Intrinsic pathway","Extrinsic pathwa"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6404, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 244, '{"id":6404,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":244,"q":"Which of the following is not a hereditary disease?","o":["Neurofibromatosis","Cretinism","Huntingtons disease","Hereditary spherocytosis"],"a":1,"e":"Ans. is ''b'' i.e., Cretinism Cretinism :? Cretinism is a condition of severely stunted physical and mental growth due to untreated congenital deficiency of thyroid hormones (congenital hypothyroidism) usually due to maternal hypothyroidism. Thus cretinism is a non hereditary condition.","pyqMatches":[{"year":"2014","no":423,"q":"Which of the following is not a hereditary disease?","o":["Neurofibromatosis","Cretinism","Huntingtons disease","Hereditary spherocytosis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6405, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 245, '{"id":6405,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":245,"q":"Point mutaton in which protooncogene is responsible for the development of gastrointestinal stromal tumor","o":["KIT","ALK","RET","FLT3"],"a":0,"e":"Ans. is ''a'' i.e., KIT Approximately 75% to 80% of all GISTs have oncogenic, gain-of- function mutations of gene encoding the tyrosine kinase c-KIT. Approximately 8% of GISTs have mutations that activate a related tyrosine kinase, platelet derived growth factor receptor a (PDGFRA). Consitutively active c-KIT or PDGFRA receptor tyrosine kinases activate RAS and P13K/AKT pathways and thereby promote tumor cell proliferation.","pyqMatches":[{"year":"2014","no":446,"q":"Point mutaton in which protooncogene is responsible for the development of gastrointestinal stromal tumor","o":["KIT","ALK","RET","FLT3"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6406, 'Pathology', 'Hematology', 'Easy', 'Pathology', 246, '{"id":6406,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":246,"q":"Carcinoembryonic antigen is raised in which of the following non neoplastic conditions -","o":["Hepatitis","Pancreatitis","Hemolytic anemia","Ulcerative colitis"],"a":1,"e":"Ans. is ''b'' i.e., Pancreatitis 1) Neoplastic conditions with raised CEA —> Colorectal cancer, lung cancer, breast cancer, ovarian cancer. 2) Non-neoplastic conditions with raised CEA —> Alcoholic cirrhosis, hepatitis, IBD (UC, CD), smoking, pancreatitis and hemolytic anemia.","pyqMatches":[{"year":"2014","no":432,"q":"Carcinoembryonic antigen is raised in which of the following non neoplastic conditions","o":["Hepatitis","Pancreatitis","Hemolytic anemia","Ulcerative colitis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6407, 'Pathology', 'Infectious Diseases', 'Moderate', 'Pathology', 247, '{"id":6407,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Moderate","source":"Pathology","sourceNo":247,"q":"Under Blood safety programme compulsory tests done are all except ?","o":["HIV","VDRL","Malaria","Hepatitis E"],"a":3,"e":"Ans. is ''d'' i.e., Hepatitis E Blood safety :? Under Blood Safety Programme all the blood banks have to ensure that before transfusion of blood to the patient the mandatory tests for HIV, VDRL, Hepatitis B, Hepatitis C and Malaria are done.","pyqMatches":[{"year":"2014","no":476,"q":"Under Blood safety programme compulsory tests done are all except ?","o":["HIV","VDRL","Malaria","Hepatitis E"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6408, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 248, '{"id":6408,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":248,"q":"EBV receptor mimics ?","o":["CD 20","CD 21","CD 22","CD 23"],"a":1,"e":"Ans. is ''b'' i.e., CD 21 CD 21 -> EBV receptor : Mature B cells and follicular dendritic cells.","pyqMatches":[{"year":"2014","no":411,"q":"EBV receptor mimics ?","o":["CD 20","CD 21","CD 22","CD 23"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6409, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 249, '{"id":6409,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":249,"q":"Leukocyte adhesion to endothelium is mediated by all except ?","o":["L selectin","E selectin","VCAM 1","VCAM 4"],"a":3,"e":"Ans. is ''d'' i.e., VCAM 4 Endothelial molecule P-selectin E-selectin ICAM- 1 VCAM-1 Glycam-1 CD 31 (PECAM)","pyqMatches":[{"year":"2014","no":383,"q":"Leukocyte adhesion to endothelium is mediated by all except ?","o":["L selectin","E selectin","VCAM 1","VCAM 4"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6410, 'Pathology', 'Genetic Disorders', 'Easy', 'Pathology', 250, '{"id":6410,"subject":"Pathology","chapter":"Genetic Disorders","difficulty":"Easy","source":"Pathology","sourceNo":250,"q":"Boys are more likely to be affected by which genetic disorders ?","o":["AD","AR","X linked dominant","X linked recessive"],"a":3,"e":"Ans. is ''d'' i.e., X linked recessive X-linked disorders Except for a few conditions, all X-linked disorders are X-linked recessive. As male has only one X-chromosome, the male with affected gene on X-chromosome will always manifest the disease. On the other hand, female has 2 X-chromosomes, heterozyogous female will be carrier because of expression of normal allel on the other X-chromosome. So a boy has more probability to manifest X linked recessive as compared to girls","pyqMatches":[{"year":"2014","no":424,"q":"Boys are more likely to be affected by which genetic disorders ?","o":["AD","AR","X linked dominant","X linked recessive"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6411, 'Pathology', 'Hemodynamics', 'Easy', 'Pathology', 251, '{"id":6411,"subject":"Pathology","chapter":"Hemodynamics","difficulty":"Easy","source":"Pathology","sourceNo":251,"q":"Inceased accumulation of fluid in the interstitial space is described as ?","o":["Edema","Effusion","Transudate","Exudate"],"a":0,"e":"Ans. is ''a'' i.e., Edema Edema: accumulation of fluid in the interstitial space Effusion: accumulation of fluid in the body cavities","pyqMatches":[{"year":"2014","no":403,"q":"Inceased accumulation of fluid in the interstitial space is described as ?","o":["Edema","Effusion","Transudate","Exudate"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6412, 'Pathology', 'Hematology', 'Easy', 'Pathology', 252, '{"id":6412,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":252,"q":"Classic example of missense mutation ?","o":["Thalassemia","Sickle cell disease","Sideroblastic anemia","Hemochromatosis"],"a":1,"e":"Ans. is ''b'' i.e., Sickle cell disease In sickle cell anemia there is missense type of point mutation. Mutations A mutation is apermanant change in the DNA. Mutations that affect genii cells (sperm or ovum) are transmitted to progeny and may give rise to inherited disease. Mutations that affect somatic cells arc not transmitted to progeny but are important in the genesis of cancers and congenital malformations. Mutations may be classified into three categories ?","pyqMatches":[{"year":"2014","no":425,"q":"Classic example of missense mutation ?","o":["Thalassemia","Sickle cell disease","Sideroblastic anemia","Hemochromatosis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6413, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 253, '{"id":6413,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":253,"q":"Matrix metalloproteinases is ?","o":["Cathepsin","Zn metalloproteinases","Cu metalloproteinases","Cd metalloproteinases"],"a":0,"e":"Ans. is b i.e., Zn metalloproteinases The outcome of the repair process of tissues is influenced by a balance between synthesis and degradation of ECM proteins. After its deposition, the connective tissue in the scar continues to be modified and remodeled. The degradation of collagens and other ECM components is accomplished by a family of matrix metalloproteinases (MMPs), so called because they are dependent on metal ions (e.g., zinc) for their activity. MMPs include interstitial collagenases, which cleave fibrillar collagen (MMP-1, -2 and -3); gelatinases (MMP-2 and 9), which degrade amorphous collagen and fibronectin; and stromelysins (MMP-3, -10, and ,11), which degrade a variety of ECM constituents, including proteo- glycans, laminin, fibronectin, and amorphous collagen.","pyqMatches":[{"year":"2014","no":385,"q":"Matrix metalloproteinases is ?","o":["Cathepsin","Zn metalloproteinases","Cu metalloproteinases","Cd metalloproteinases"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6414, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 254, '{"id":6414,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":254,"q":"Tau protein seen in ?","o":["Alzhiemer''s disease","Lewy body dementia","Picks disease","Amylodosis"],"a":0,"e":"Ans. is `a'' i.e., Alzheimer''s disease Alzhiemer''s disease :? There is atrophy of frontal and temporal lobes to variable extent and severity. The pattern of atrophy can often be predicted in part by the clinical symptomatology. The atrophic regions of cortex are marked by neuronal loss, gliosis, and the presence of tau-containing neu​rofibrillary tangles","pyqMatches":[{"year":"2015","no":474,"q":"Tau protein seen in ?","o":["Alzhiemer''s disease","Lewy body dementia","Picks disease","Amylodosis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6415, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 255, '{"id":6415,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":255,"q":"The phenomenon by which the cancer cells are able to sustain and proliferate under adverse conditions of hypoxia is ?","o":["Warburg","Wanton","Wormian","Wolf"],"a":0,"e":"Ans. is ''a'' i.e., Warburg Otto Warburg described the bioenergetics and metabolic features that permit cancer cells to survive under adverse conditions such as hypoxia and enable their proliferation, progression, invasiveness, and subsequent distant metastasis. This phenomenon is thus called the growth promoting Warburg phenomenon.","pyqMatches":[{"year":"2014","no":449,"q":"The phenomenon by which the cancer cells are able to sustain and proliferate under adverse conditions of hypoxia is ?","o":["Warburg","Wanton","Wormian","Wolf"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6416, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 256, '{"id":6416,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":256,"q":"Defect of glanzmann''s thrombosthenia is ?","o":["Gp1Ib-IlIa","GpIIIa-I lb","GpIla-Illb","Gpfilb-I la"],"a":0,"e":"Ans. is ''a'' i.e., GpI1b-IlIa Defect in Glanzmann''s trombsthenia Gp IIb/IIIa Defect in Bernard soulier syndrome Gp Ib/IX","pyqMatches":[{"year":"2014","no":472,"q":"Defect of glanzmann''s thrombosthenia is ?","o":["Gp1Ib-IlIa","GpIIIa-I lb","GpIla-Illb","Gpfilb-I la"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6417, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 257, '{"id":6417,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":257,"q":"Metastatic calcification is characterized by ?","o":["Hypercalcemia","Hypocalcemia","Eucalcemia","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Hypercalcemia Pathologic calcifications Dystrophic calcification: Deposition of calcium at sites of cell injury and necrosis. Metastatic calcification: Deposition of calcium in normal tissues, caused by hypercalcemia (usually a consequence of parathyroid hormone excess)","pyqMatches":[{"year":"2014","no":375,"q":"Metastatic calcification is characterized by ?","o":["Hypercalcemia","Hypocalcemia","Eucalcemia","None of the above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6418, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 258, '{"id":6418,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":258,"q":"Most important growth factors in angiogenesis ?","o":["PDGF","TGF alpha","TGF beta","VEGF"],"a":3,"e":"Ans. is ''d i.e., VEGF Two most important angiogenic factors are : i) Vascular endothelial growth factor (VEGF) —> most important. ii) Basic fibroblast growth factor (FGF-2).","pyqMatches":[{"year":"2014","no":415,"q":"Most important growth factors in angiogenesis ?","o":["PDGF","TGF alpha","TGF beta","VEGF"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6419, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 259, '{"id":6419,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":259,"q":"Necrosis with cell bodies retained as ghost cells is ?","o":["Coagulative necrosis","Liquefactive","Caseous","None"],"a":0,"e":"Ans. is ''a'' i.e., Coagulative necrosis The microscopic anatomy of coagulative necrosis shows a lighter staining tissue containing no nuclei with very little structural damage, giving the appearance often quoted as \"Ghost cells\" -> outlines of cells are retained so that the cell type can still be identified but their cytoplasmic and nuclear details are lost.","pyqMatches":[{"year":"2014","no":377,"q":"Necrosis with cell bodies retained as ghost cells is ?","o":["Coagulative necrosis","Liquefactive","Caseous","None"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6420, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 260, '{"id":6420,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":260,"q":"Cells responsible for GVHD is ?","o":["Immunocompetent T cell donor","Immunocompetent T Cell recipient","Immunocompetent B cell donor","Immunocompetent B cell donor"],"a":0,"e":"Ans. is ''a'' i.e., Immunocompetent T-cell donor Graft- versus-host disease (GVHD) :? GVHD occurs when immunologically competent cells (T cells) or their precursors are transplanted into immunologically crippled recipients, and the transferred cells recognize alloantigens in the host and attack host tissues. Most commonly involved tissues in Graft versus host disease :- Liver Skin Gut","pyqMatches":[{"year":"2014","no":405,"q":"Cells responsible for GVHD is ?","o":["Immunocompetent T cell donor","Immunocompetent T Cell recipient","Immunocompetent B cell donor","Immunocompetent B cell donor"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6421, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 261, '{"id":6421,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":261,"q":"Flow cytometry is done on","o":["Polycythemia","Thrombocytosis","Basophil","Lymphocytes"],"a":3,"e":"Ans. d. Lymphocytes \"Flow cytometry can rapidly and quantitatively measure several individual cell characteristics, such as membrane antigens and the DNA content of tumor cells. Flow cytometry has also proved useful in the identification and classification of tumors arising from T and B lymphocytes and from mononuclear-phagocytic cells.\"- Robbins 8/e p324","pyqMatches":[{"year":"2016","no":332,"q":"Flow cytometry is done on","o":["Polycythemia","Thrombocytosis","Basophil","Lymphocytes"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6422, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 262, '{"id":6422,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":262,"q":"Person having heterozygous sickle cell trait is protected from infection of:","o":["P. falciparum","P. vivax","Pneumococcus","Salmonella"],"a":0,"e":"Ans. a. P. falciparum Person having heterozygous sickle cell trait is protected from infection of P. falciparum. \"People who are heterozygous for the sickle cell trait (HbS) become infected with P. falciparum, but they are less likely to die from infection°. The HbS trait causes the parasites to grow poorly or die because of the low oxygen concentrations°.\" - Robbins 8/e p387 Host Resistance to Plasmodium Two general mechanisms of host resistance to Plasmodium: Inherited alterations in red cells make people resistant to Plasmodium°. Repeated or prolonged exposure to Plasmodium species stimulates an immune response that reduces the severity People who are heterozygous for the sickle cell trait (HbS) become infected with P. falciparum, but the yare less likely to die from infection°. The HbS trait causes the parasites to grow poorly or die because of the low oxygen concentrations°. The geographic distribution of the HbS trait is similar to that of P. falciparum°, suggesting evolutionary selection of the HbS trait in people by the parasite HbC, another common hemoglobin mutation, also protects against severe malaria by reducing parasite proliferation°. Host Resistance to Plasmodium. People can also be resistant to malaria due to the absence of proteins to which the parasites bind°. P. vivax enters red cells by binding to the Duffy blood group antigen°. Many Africans, including most Gambians, are not susceptible to infection by P. vivax because they do not have the Duffy antigen°. Antibodies and T lymphocytes specific for Plasmodium reduce disease manifestations. Cytotoxic lymphocytes may also be important in resistance to P. falciparum","pyqMatches":[{"year":"2013","no":459,"q":"Person having heterozygous sickle cell trait is protected from infection of:","o":["P. falciparum","P. vivax","Pneumococcus","Salmonella"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6423, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 263, '{"id":6423,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":263,"q":"Sequence of events in acute inflammation ?","o":["Vasodilatation → Stasis → Transient vasoconstriction → Increased permeability","Transient vasoconstriction → Stasis → Vasodilatation → Increased permeability","Transient vasoconstriction → Vasodilatation → Stasis → Increased permeability","Transient vasoconstriction →Vasodilatation → Increased permeability → Stasis"],"a":3,"e":"Ans. is ''d'' i.e., Transient vasoconstriction → Vasodilatation → Increased permeability → Stasis 1) Changes in vascular caliber (vasodilatation) Vasodilatation is one of the earliest manifestations of acute inflammation. Sometimes, it follows a transient constriction of arterioles, (vasoconstrictions) lasting for a few seconds - > Though vasodilatation is the earliest manifestation of acute inflammation, it follows a transient period of vasoconstriction. 2) Change in vascular permeability Vasodilatation is quickly followed by increased vascular permeability. Increased vascular permeabily is the hallmark of acute inflammation. This leads to escape of protein rich fluid (exudate) and leukocytes into extravascular space 3) Change in vascular flow (Stasis) The loss of fluid results in concentration of red cells and increased viscosity of blood - Slower blood flow - Stasis.","pyqMatches":[{"year":"2013","no":404,"q":"Sequence of events in acute inflammation ?","o":["Vasodilatation → Stasis → Transient vasoconstriction → Increased permeability","Transient vasoconstriction → Stasis → Vasodilatation → Increased permeability","Transient vasoconstriction → Vasodilatation → Stasis → Increased permeability","Transient vasoconstriction →Vasodilatation → Increased permeability → Stasis"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6424, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 264, '{"id":6424,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":264,"q":"Gene silencing RNA ?","o":["rRNA","tRNA","miRNA","None"],"a":2,"e":"Ans. is ''c'' i.e., miRNA According to recent sudies a very large number of genes do not encode proteins. Instead, their products play important regulatory functions. The most recently discovered among this class of genes are that encode for gene-silencing RNAs, i.e. RNAs that do not encode proteins but instead inhibit gene expression (unlike classical RNAs which encode for proteins) Two gene-silencing RNAs are:","pyqMatches":[{"year":"2013","no":422,"q":"Gene silencing RNA ?","o":["rRNA","tRNA","miRNA","None"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6425, 'Pathology', 'Organ System Pathology', 'Moderate', 'Pathology', 265, '{"id":6425,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Moderate","source":"Pathology","sourceNo":265,"q":"All are obstructive lung disease except -","o":["Emphysema","Interstitial fibrosis","Asthma","Bronchitis"],"a":1,"e":"Ans. is ''b'' i.e., Interstitial fibrosis Diffuse pulmonary diseases are divided into two categories - Obstructive disease (airway disease) Obstructive disease is characterized by an increase in resistance to airflow owing to partial or complete obstruction at any level, from the trachea to the respiratory bronchioles. Examples are chronic obstructive lung disease (COPD - Emphysema, bronchitis), bronchiectasis, and asthma. Restrictive disease Restrictive disease is characterized by reduced expansion of lung parenchyma, with decreased total lung capacity. o It may occur due to two types of disorders - Chest wall disorders in the presence of Normal lungs Neuromuscular disorders, e.g.polio, severe obesity, pleural disease, kyphoscoliosis. Interstitial and infiltrative diseases of lung Pneumoconiosis, interstitial fibrosis.","pyqMatches":[{"year":"2013","no":431,"q":"All are obstructive lung disease except","o":["Emphysema","Interstitial fibrosis","Asthma","Bronchitis"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6426, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 266, '{"id":6426,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":266,"q":"Centrilobular necrosis of liver may be seen with?","o":["Phosphorus","Arsenic","CCI4","Ethanol"],"a":2,"e":"Ans. is ''c'' i.e., CC14 Zonal necrosis . Identical regions of all liver lobules are involved. It is divided into :- i) Centrizonal (centrilobular) necrosis Necrosis is seen around central hepatic vein. It is seen in cardiac failure/shock, chloroform toxicity, carbon tetra chloride (ccl4) toxicity, halothane and viral hepatitis. ii) Peripheral zonal (periportal) necrosis Necrosis is seen around portal tracts. It is seen in eclampsia and phosphorus poisoning. iii) Midzonal necrosis It is rare and is seen in yellow fever.","pyqMatches":[{"year":"2013","no":474,"q":"Centrilobular necrosis of liver may be seen with?","o":["Phosphorus","Arsenic","CCI4","Ethanol"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6427, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 267, '{"id":6427,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":267,"q":"During angiogenesis recruitment of pericytes and periendothelial cells is due to","o":["VEGF & PDGF","Angiopoietins, TGF & PDGF","TGF, VEFG & PDGF","VEGF, IL-6"],"a":1,"e":"Ans. is ''b'' i.e., Angiopoietins, TGF & PDGF Angiogenesis Blood vessels formation in adults is known as angiogenesis or neovascularization. It can occur by two ways:?","pyqMatches":[{"year":"2013","no":406,"q":"During angiogenesis recruitment of pericytes and periendothelial cells is due to","o":["VEGF & PDGF","Angiopoietins, TGF & PDGF","TGF, VEFG & PDGF","VEGF, IL-6"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6428, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 268, '{"id":6428,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":268,"q":"Heart failure cells are ?","o":["Lipofuscin granules in cardiac cells","Pigmented alveolar macrophages","Pigmented pancreatic acinar cells","Pigment cells seen in liver"],"a":1,"e":"Ans. is `B'' i.e., Pigmented alveolar macrophages Heart failure cells (siderophages) are hemosiderin containing macrophages in alveoli that are seen in left ventricular failure and denote previous episodes of pulmonary edema. Left sided heart failure The major morphological and clinical effects of LVF are due increased back pressure in pulmonary circulation and the consequences of diminished peripheral blood pressure and flow. The extracardiac organs involved commonly are ?","pyqMatches":[{"year":"2013","no":391,"q":"Heart failure cells are ?","o":["Lipofuscin granules in cardiac cells","Pigmented alveolar macrophages","Pigmented pancreatic acinar cells","Pigment cells seen in liver"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2015","no":440,"q":"Heart failure cells are","o":["Neutrophils","Macrophages","Lymphocytes","Basophils"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2013","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6429, 'Pathology', 'Hematology', 'Moderate', 'Pathology', 269, '{"id":6429,"subject":"Pathology","chapter":"Hematology","difficulty":"Moderate","source":"Pathology","sourceNo":269,"q":"All are true about Polycythemia vera except","o":["Increased vit B12","Decrease LAP score","Leucocytosis","Increased platelets"],"a":1,"e":"Ans. is ''b'' i.e., Decrease LAP score Polycythemia vera Polycythemia vera is a neoplasm arising in a multipotent myeloid sterm cell that is characterized by increased marrow production of erythroid, granulocytic and megakaryocytic elements. This leads to erythrocytosis (polycythemia), granulocytosis, and thrombocytosis in the peripheral blood. Polycythemia is responsible for most of the clinical symptoms of polycythemia vera. Polycythemia vera progenitor cells have markedly decreased requirements for erythropoietin and other hematopoietic growth factors. Accordingly serum erythropoietin levels in polvuthemia vera are very low, whereas almost all other forms of absolute polycythemia are caused by elevated ervthropoietin levels. Clinical manifestations","pyqMatches":[{"year":"2013","no":444,"q":"All are true about Polycythemia vera except","o":["Increased vit B12","Decrease LAP score","Leucocytosis","Increased platelets"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6430, 'Pathology', 'Hematology', 'Easy', 'Pathology', 270, '{"id":6430,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":270,"q":"Intracorpuscular hemolytic anemia is seen in ?","o":["Autoimmune hemolytic anemia","TIP","Thalassemia","Infection"],"a":2,"e":"Ans. is `c'' i.e., Thalassemia Intracorpuscular hemolysis : Hereditary sphlerocytosis, G6PD deficiency, thalassemia, sickle cell anemia, PNH. Extracorpuscular hemolysis : Microangiopathic hemolytic anemia (TTP, HUS, DIC), infection (malaria), prosthetic valve, immunohemolytic anemia and hyperplenism.","pyqMatches":[{"year":"2013","no":456,"q":"Intracorpuscular hemolytic anemia is seen in ?","o":["Autoimmune hemolytic anemia","TIP","Thalassemia","Infection"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6431, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 271, '{"id":6431,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":271,"q":"Gilbert syndrome, true all except ?","o":["Causes cirrhosis","Autosomal dominant","Normal liver function test","Normal histology"],"a":0,"e":"Ans. is ''a'' i.e., Causes cirrhosis Gilbert''s Syndrome: ? o It is an autosomal dominant condition. o It is characterized by unconjugated hyperbilirubinemia (normally the bilirubin is transported into liver cells by intracellular proteins. In the liver bilirubin is conjugated. This conjugation is brought about by certain enzymes. In Gilbert''s syndrome these enzymes are absent which cause unconjugated hyperbilirubinemia). The hyperbilirubinemia is usually precipitated by following conditions – Stress, Fatigue, Alcohol use, reduced calorie intake, intercurrent illness. The hepatic biochemical tests are normal except for elevated bilirubin level (serum bilirubin concentration are usually < 3mg/dl) Embryonal carcinomaThe hepatic histology is normal There is no association with cirrhosis.","pyqMatches":[{"year":"2013","no":475,"q":"Gilbert syndrome, true all except ?","o":["Causes cirrhosis","Autosomal dominant","Normal liver function test","Normal histology"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6432, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 272, '{"id":6432,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":272,"q":"Flexner-Wintersteiner rossette is seen in-","o":["Hepatoblastoma","Nephroblastoma","Neuroblastoma","Retinoblastoma"],"a":3,"e":"Ans. is ''d'' i.e., Retinoblastoma Rosettes Rosettes are pathological findings characterized by a halo or spoke wheel arrangement of cells surrounding a central core or hub. Type of Rosette","pyqMatches":[{"year":"2013","no":489,"q":"Flexner-Wintersteiner rossette is seen in","o":["Hepatoblastoma","Nephroblastoma","Neuroblastoma","Retinoblastoma"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6433, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 273, '{"id":6433,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":273,"q":"Band test is done in ?","o":["RA","SLE","Scleroderma","PAN"],"a":1,"e":"Ans. is ''b'' i.e., SLE Band test (Lupus band test) Lupus band test is done upon skin biopsy, with direct immunofluorescence staining, in which, if positive, IgG and complement depositions are found at the dermoepidermal junction. This test can be helpful in distinguishing systemic lupus erythematosus (SLE) from cutaneous lupus, because in SLE the lupus band test will be positive in both involved and uninvolved skin, whereas with cutaneous lupus only the involved skin will be positive. The minimum criteria for positivity are: In sun-exposed skin : Presence of a band of deposits of IgM along the epidermal basement membrane in 50% of the biopsy, intermediate (2+) intensity or more. In sun protected skin : Presence of interrupted (i.e. less than 50%) deposits of IgM along the epidermal basement membrane, intermediate (2+) intensity or more. The presence of other immunoglobulins (especially IgA) and/or complement proteins (especially C4) increases the specificity of a positive test.","pyqMatches":[{"year":"2013","no":412,"q":"Band test is done in ?","o":["RA","SLE","Scleroderma","PAN"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6434, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 274, '{"id":6434,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":274,"q":"Angelman syndrome is due to -","o":["Digenic inheritence","Inversion","Uniparental disomy","Mitochondrial disorder"],"a":2,"e":"Ans. is ''c'' i.e., Uniparental disomy Prader Willi syndrome Angleman syndrome Paternal deletion (Paternal genomic imprinting) Maternal deletion (maternal genomic imprinting) Maternal uniparental disomy Paternal uniparental disomy","pyqMatches":[{"year":"2013","no":424,"q":"Angelman syndrome is due to","o":["Digenic inheritence","Inversion","Uniparental disomy","Mitochondrial disorder"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6435, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 275, '{"id":6435,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":275,"q":"Organelle where H202 is produced and destroyed is?","o":["Peroxisome","Lysosome","Golgi body","Ribosome"],"a":0,"e":"Ans. is ''a'' i.e., Peroxisome Peroxisome is a membrane bound organellel found in all eukaryotic cells. \"Peroxisomes contain a group of enzymes that oxidize a variety of substrates and thereby form hydrogen peroxide. The H202 thus formed is efficiently decomposed within the organelle by catalase which is present in high concentration\". Lysosomes can only form H,02 - They cannot degrade H202. Remember H202 is produced as well as destroyed in mitochondria and cytosol. It is produced from superoxide by enzyme SOD. It is destroyed by glutathione peroxidase.","pyqMatches":[{"year":"2013","no":382,"q":"Organelle where H202 is produced and destroyed is?","o":["Peroxisome","Lysosome","Golgi body","Ribosome"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6436, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 276, '{"id":6436,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":276,"q":"Increased permeability in acute inflammation is due to?","o":["Histamine","IL-2","TGF-(3","FGF"],"a":0,"e":"Ans. is ''a'' i.e., Histamine Formation of endothelial gaps in venules, i.e. immediate transient response is the most common mechanism causing increased vascular permeability in acute inflammation. Mediators involved in this mechanism are :- Immediate (more important) : Histamine, bradykinin, leukotrienes, neuropeptide substance P. Somewhat delayed: IL-1, TNF, IFN-y","pyqMatches":[{"year":"2013","no":405,"q":"Increased permeability in acute inflammation is due to","o":["Histamine","IL-2","TGF-P","FGF"],"a":0,"source":"NEET_2013_Paper.pdf"},{"year":"2013","no":407,"q":"Increased permeability in acute inflammation is due to?","o":["Histamine","IL-2","TGF-(3","FGF"],"a":0,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":402,"q":"Increased permeability in acute inflammation is due to?","o":["Histamine","IL-2","TGF-(3","FGF"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6437, 'Pathology', 'Hematology', 'Moderate', 'Pathology', 277, '{"id":6437,"subject":"Pathology","chapter":"Hematology","difficulty":"Moderate","source":"Pathology","sourceNo":277,"q":"Not true about hereditary spherocytosis","o":["Defect in ankyrin","Decreased MCV","Decreased MCHC","Reticulocytosis"],"a":2,"e":"Ans. is ''c'' i.e., Decreased MCHC Laboratory findings Spherocytosis 4 Peripheral smear shows microspherocytes which are small RBCs without central pallor (Normally central 1/3 pallor is present in red cells). MCV • Reticulocytosis -) As seen with any type of hemolytic anemia. MCHC T • Hemoglobin Increased unconjugate bilirubin • Serum Heptoglobin Normal to decreased. Urine urobilinogen T • Increased osmotic fragility. Stool stercobilinogen T","pyqMatches":[{"year":"2013","no":457,"q":"Not true about hereditary spherocytosis","o":["Defect in ankyrin","Decreased MCV","Decreased MCHC","Reticulocytosis"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6438, 'Pathology', 'Hematology', 'Moderate', 'Pathology', 278, '{"id":6438,"subject":"Pathology","chapter":"Hematology","difficulty":"Moderate","source":"Pathology","sourceNo":278,"q":"Mantle cell lymphomas are positive for all of the following, except ?","o":["CD 23","CD 20","CD 5","CD 43"],"a":0,"e":"Ans. is ''a'' i.e., CD 23 Mantle cell lymphoma Mantle cell lymphoma is a type of non-Hodgkin lymphoma characterized by the presence of tumor cells that closely resemble the normal mantle zone of B-cells that surround germinal centers. Immunophenotype of mantle cell lymphoma Mantle cell lymphoma is a neoplasm of B cells. Therefore it expresses B cell marker: CD19, CD20 Surface immunoglobulin heavy chain (IgM and IgD). Either c or X light chain. As the tumor cells are derived from the Mantle zone, they are positive for B cell marker of mantle zone i.e., CD-5. Mantle cell lymphoma is CD23 negative, this feature distinguishes it from chronic lymphocytic leukemia (CLL) which is positive for both CD5 and CD23. The other characteristic marker of mantle cell lymphoma is cyclin DI. Cytogenetic abnormalities: Mantle cell lymphoma is associated with an 11: 14 translocation involving the IgH locus on chromosome 14 and the cyclin D1 locus on chromosome 11. This leads to increased expression of cyclin D1, which promotes GI to S phase progression during the cell cycle. 65 years old man with splenomegaly, lymphadenopathy CD-23 negative and CD-5 positive B-cell suggest the diagnosis of mantle cell lymphoma. Clinical features of mantle cell lymphoma: It is usually present in the fifth to a sixth decade with male preponderance. The most common presentation is painless lymphadenopathy. Splenomegaly may occur. Occasionally, multifocal mucosal involvement of the small bowel and colon produces lymphomatoid polyposis→ of all forms of NHL, mantle cell lymphoma is most likely to spread in this fashion.","pyqMatches":[{"year":"2013","no":445,"q":"Mantle cell lymphomas are positive for all of the following, except ?","o":["CD 23","CD 20","CD 5","CD 43"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6439, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 279, '{"id":6439,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":279,"q":"Gastric carcinoma is associated with all EXCEPT ?","o":["Inactivation of p53","Over expression of C-erb","Over expression of C-met","Activation of RAS"],"a":3,"e":"Ans. is ''d'' Activation of RAS In the course of multi-step stomach carcinogenesis, various genetic and epigenetic alterations of oncogenes, tumor-suppressor genes, DNA repair genes, cell cycle regulators and cell adhesion molecules are involved. Genetic alteration in gastric cancer include: Intestinal type gastric cancer: K-ras mutation, APC mutation, pS2 methylation, HMLH1 methylation, p I ema methylation, p 73 deletion and C-erb B-2 amplification.","pyqMatches":[{"year":"2013","no":467,"q":"Gastric carcinoma is associated with all EXCEPT ?","o":["Inactivation of p53","Over expression of C-erb","Over expression of C-met","Activation of RAS"],"a":3,"source":"NEET_2013_Paper.pdf"},{"year":"2015","no":1263,"q":"Gastric carcinoma is associated with all EXCEPT ?","o":["Inactivation of p53","Over expression of C-erb","Over expression of C-met","Activation of RAS"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2013","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6440, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 280, '{"id":6440,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":280,"q":"Irreversible injury in myocardium occurs at ?","o":["2 minutes","30 minutes","2 hours","5 hours"],"a":1,"e":"Ans. is ''b'' i.e., 30 minutes The metabolic rate of the heart is high, and its stores of substrate are low. So, heart is critically dependent on a continuous supply of oxygen and nutrients. Ischemia of myocardium induces profound functional, biochemical and morphological consequences. Myocardial function is more sensitive to isc_hemia (loss of contractility occurs within 60 seconds) than myocardial structure (irreversible injury occurs in 20-40 minutes, thus myocardial necrosis begins at approximately 30 minutes after coronary occlusion. Key events in ischemic cardiac myocytes Feature Time Onset of ATP depletionSeconds Loss of contractility < 2 minutes ATP reduced to 50% 10 minutes ATP reduced to 10% 40 minutes Irrversible injury 2040 min Microvascular injury > 1 hr","pyqMatches":[{"year":"2013","no":392,"q":"Irreversible injury in myocardium occurs at ?","o":["2 minutes","30 minutes","2 hours","5 hours"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6441, 'Pathology', 'Hematology', 'Easy', 'Pathology', 281, '{"id":6441,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":281,"q":"Bone marrow finding in myelofibrosis ?","o":["Dry tap (hypocellular)","Megaloblastic cells","Microcytic cells","Thrombocytosis18"],"a":0,"e":"Ans. is ''a'' i.e., Dry tap (hypocellular) Myelofibrosis The hallmark of primary myelofibrosis is rapid development of obliterative marrow fibrosis. Myelofibrosis suppresses bone marrow hematopoiesis, leading to peripheral blood cytopenias. This results in extensive extramedullary hematopoiesis in the spleen, liver and lymphnode —> Splenomegaly and hepatomegaly. Blood cell production from sites of extramedullary hematopoisis is disordered and ineffective —> Persistent cytopenia. Peripheral blood picture Leukoerythroblastosis —> Presence of erythroid and granulocytic precursors in the peripheral blood. Tear-drop erythrocytes (dacrocytes) —> Fibrotic marrow distorts and damages the membranes of erythroid proginators. Bone marrow findings Initially marrow is hypercellular. With progression marrow becomes hypocellular and diffusely fibrotic —> Bone marrow aspiration is a dry tap. There is increase laying down of reticulin fibril network. Cellularity of bone marrow is decreased, but megakaryocytes are increased and demonstrate features of dysmegakaryopoiesis. Dilated marrow sinusoids.","pyqMatches":[{"year":"2013","no":446,"q":"Bone marrow finding in myelofibrosis ?","o":["Dry tap (hypocellular)","Megaloblastic cells","Microcytic cells","Thrombocytosis18"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6442, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 282, '{"id":6442,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":282,"q":"Schiller- Duval bodies is seen in","o":["Choriocarcinoma","Embryonal cell Ca","Endodermal sinus tumour","Immature teratoma"],"a":2,"e":"Ans. is ''c'' i.e., Endodermal sinus tumor Yolk sac tumor (endodermal sinus tumor or infantile embryonal carcinoma) —> Schiller - Duval bodies. Leydig (interstitial) cell tumor -3 Reinke crystalloids. Note : - Rienke crystals are also seen in the hilus cell tumor of ovary.","pyqMatches":[{"year":"2013","no":485,"q":"Schiller- Duval bodies is seen in","o":["Choriocarcinoma","Embryonal cell Ca","Endodermal sinus tumour","Immature teratoma"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6443, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 283, '{"id":6443,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":283,"q":"A/E are involved in MEN type II A ?","o":["Parathyroid","Adrenal","Thyroid","Pituitary"],"a":3,"e":"Ans. is ''d'' i.e., Pituitary MEN type 2A (Sipple syndrome) Autosomal dominant It is characterised by medullary carcinoma of thyroid, pheochromocytoma and hyperparathyroidism. It is caused by mutation of the RET proto-oncogene in codon 634. Mapped to chromosome 10. Mutated codon- cysteine codon Type 2A has 3 variants- a) MEN 2A with familial medullary carcinoma thyroid (1st feature of type 2A) b) MEN 2A with cutaneous lichen amyloidosis c) MEN 2A with Hirschsprung disease","pyqMatches":[{"year":"2013","no":481,"q":"A/E are involved in MEN type II A ?","o":["Parathyroid","Adrenal","Thyroid","Pituitary"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6444, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 284, '{"id":6444,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":284,"q":"All are good prognostic factors for neuroblastoma except -","o":["Trk-A expression absent","Absence of 1 p loss","Absence of 17 p gain","Absence of 11 q loss"],"a":0,"e":"Ans. is ''a'' i.e., Trk-A expression absent Intratumoral calcification DNA ploidy- Hyperdiploid or near-triploid Trk-A Expression CD-44 Expression","pyqMatches":[{"year":"2013","no":488,"q":"All are good prognostic factors for neuroblastoma except","o":["Trk-A expression absent","Absence of 1 p loss","Absence of 17 p gain","Absence of 11 q loss"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6445, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 285, '{"id":6445,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":285,"q":"Eosinophilia in necrosed tissue is due to","o":["Coagulation of proteins","Denaturation of enzymes","Denaturation of protein","Mitochondrial damage"],"a":2,"e":"Ans. is ''c'' i.e., Denaturation of protein Necrotic cells show increased eosinophilia in hematoxylin and eosin (H & E) stains. It is due to -","pyqMatches":[{"year":"2013","no":383,"q":"Eosinophilia in necrosed tissue is due to","o":["Coagulation of proteins","Denaturation of enzymes","Denaturation of protein","Mitochondrial damage"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6446, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 286, '{"id":6446,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":286,"q":"Macrophages are converted to epitheloid cells by which cytokine ?","o":["IL-2","IFN-y","TNF-a","TGF-(3"],"a":1,"e":"Ans. is ''b'' i.e., IFN-y A granuloma is a focus of chronic inflammation consisting of a microscopic aggregation of macrophages that are transformed into epithelium like cells (epithelioid cells) surrounded by a Collor of mononuclear leukocytes, principally lymphocytes and occasionally plasma cells. Frequently, these epitheloid cells fuse to form giant cells in the periphery or some times in the center of granuloma. Pathogenesis of granuloma Immune granuloma (most common type of granuloma) is a type IV hypersensitivity that involved CD-4 helper T cell. On-exposure to particulate antigen macrophages process and present this antigen to Helper T cells and also secretes IL-2. T-cells are activated on contact with this antigen and by IL-2. Activated T-cells (helper) produce IFN-y, the major cytokine of granulomatous inflammation. IFN-y has the following effects It is the most important activator of macrophages. It induce granuloma formation by conversion of activated macrophages into epitheliod cells and formation of giant cell. Augment the differentiation of T-cells. Finally there is formation of granuloma induced by IFN-y. Remember Foreign body (Nonimmune) granuloma consist almost entirely of epitheloid cells and multinucleated giant cells but no lymphocytes. Granulomas induced by parasites contain a large component of eosinophils. In lymphogranuloma venerum and Cat scratch disease granulomas have a characteristic central neutrophilic abscess surrounded by macrophages and other mononuclear cells.","pyqMatches":[{"year":"2013","no":408,"q":"Macrophages are converted to epitheloid cells by which cytokine ?","o":["IL-2","IFN-y","TNF-a","TGF-(3"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6447, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 287, '{"id":6447,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":287,"q":"The professional antigen presenting cells ?","o":["B cells","Dendritic cells","T cells","NK cells"],"a":1,"e":"Ans. is ''b'' i.e., Dendritic cells Dendritic cells are the most potent and effective antigen presenting cells in the body - Harrison 2024 Mature B-cells and T-cells before antigenic exposure are called naive-B and T cells respectively. Sequence of events in activation of naive T cells. Immature dendritic cells in the epidermis are called langerhans cell. These immature dendritic cells (langerhans cells) capture the antigen in the epidermis. After capturing the antigen these cells secrete cytokines. These cytokines cause loss of adhesiveness of langerhans cells. Langerhans cells separate from each other and migrate into lymphatic vessels. In lymphatic vessel, maturation of langerhans cells takes place. Then these mature langerhans dendritic cells reach to naive T cells in the lymph nodes and present antigen to these cells and activate them.","pyqMatches":[{"year":"2013","no":413,"q":"The professional antigen presenting cells ?","o":["B cells","Dendritic cells","T cells","NK cells"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6448, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 288, '{"id":6448,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":288,"q":"All are growth promoting oncogenes except ?","o":["FGF","TGF-a","TGF-p","PDGF"],"a":2,"e":"Ans. is ''c'' i.e.TGF-p Growth factor genes: SIS, HST-1, INT-2, TGFa, FGF.","pyqMatches":[{"year":"2013","no":429,"q":"All are growth promoting oncogenes except ?","o":["FGF","TGF-a","TGF-p","PDGF"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6449, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 289, '{"id":6449,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":289,"q":"Hyperplastic arteriolitis with nerotizing arteriolitis is seen in ?","o":["Buerger''s disease","Benign hypertension","Malignant hypertension","Diabetes"],"a":2,"e":"Ans. is ''c'' i.e., Malignant hypertension Hyperplastic arteriosclerosis is characteristically pathologic change seen in vessels of the patient suffering from malignant hypertension. Arterioles of all the organs in the body can affected but favoured sites are","pyqMatches":[{"year":"2013","no":393,"q":"Hyperplastic arteriolitis with nerotizing arteriolitis is seen in ?","o":["Buerger''s disease","Benign hypertension","Malignant hypertension","Diabetes"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6450, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 290, '{"id":6450,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":290,"q":"Fibrosis is due to ?","o":["TGF-","TNF -","IL - 7","IL - 10"],"a":0,"e":"Ans. is ''a'' i.e., TGF- 13 \"TFG-b is practically always involved as an important fibrogenic agent\" — Robbins Mediaters involved in fibrosis :? i) Growth factors :- TGF-(3, PDGF, FGF ii) Cytokines : IL-1, IL-4, TNF, IL-13","pyqMatches":[{"year":"2014","no":414,"q":"Fibrosis is due to ?","o":["TGF","TNF","IL - 7","IL - 10"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6451, 'Pathology', 'Hematology', 'Moderate', 'Pathology', 291, '{"id":6451,"subject":"Pathology","chapter":"Hematology","difficulty":"Moderate","source":"Pathology","sourceNo":291,"q":"In sickle cell anemia all are true except -","o":["Sickle cells","Target cells","Howell jolly bodies","Ringed sideroblast"],"a":3,"e":"Ans. is ''d'' i.e., Ringed sideroblast Laboratory findings of sickle cell anemia :? Moderate to severe anaemia. Peripheral smear will show Sickle cells Target cells Howell-Jolly bodies because of autosplenctomy. A postive sickling test with a reducing substance like sodium metabisulfite. Sickle cell anemia is caused by replacement of normal Hemoglobin by sickled hemoglobin (HbS). HbS is formed by replacement of Glutamine by Valine at position 6 This substitution replaces the polar Glutamine residue with a nonpolar Valine. The replacement of Glutamine by Valine generates a sticky patch on the surface of HBS. The sticky patch is present on both oxygenated and deoxygenated HbS The deoxygenated HbS also contains a complementary site for the sticky patch. In oxygenated hemoglobin this complementary site is masked. When HbS is deoxygenated the sticky patch present on its surface binds to the complementary patch on another deoxygenated HbS molecules. This binding leads to polymerization of deoxyhemoglobin S forming long fibrous precipitates. These extend throughout the erythrocyte and mechanically distort it, causing lysis and multiple secondary clinical effect. So, if HbS can be maintained in an oxygenated state or if the concentration of deoxygenated HbS can be minimized, formation of these polymers will not occur and sickling can be prevented (Remember the complementary site for the sticky patch remains masked in case of Oxygenated HbS). Role of HbA in polymerization Unlike HbS, HbA does not contain any sticky patch, but it does have a binding site for the sticky patch of HbS. Thus it can bind to HbS through its receptor site but this binding cannot extend the polymer because HbA does not contain any sticky patch to promote binding to still another hemoglobin molecule. So HbA interferes with the polymerisation and aggreation of HbS and reduces the intensity of sickle cell anemia.","pyqMatches":[{"year":"2013","no":458,"q":"In sickle cell anemia all are true except","o":["Sickle cells","Target cells","Howell jolly bodies","Ringed sideroblast"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6452, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 292, '{"id":6452,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":292,"q":"Linitis plastica is a type of ?","o":["Plastic like lining of stomach","Diffuse carcinoma of stomach","Benign ulcer","GIST"],"a":1,"e":"Ans. is `b'' i.e., Diffuse carcinoma of stomach Linitis plastica Involvement of a broad region of the gastric wall or entire stomach by diffuse stomach cancer cause linitis plastica. It is also known as Brinton''s disease. The appearance of stomach is like leather bottle. The other cause of linitis plastica are Lye ingestion Metastatic infiltration of stomach Syphilis Sarcoidosis Non -hodgkin lymphoma of stomach","pyqMatches":[{"year":"2013","no":468,"q":"Linitis plastica is a type of ?","o":["Plastic like lining of stomach","Diffuse carcinoma of stomach","Benign ulcer","GIST"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":1538,"q":"Linitis plastica is a type of :","o":["Gastric ulcer","Ca stomach","Duodenal ulcer","None of the above"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6453, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 293, '{"id":6453,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":293,"q":"Microvesicular fatty liver is caused by ?","o":["DM","Valproate","Starvation","IBD"],"a":1,"e":"Ans. is ''b'' i.e., Valproate Steatosis Accumulation of triglyceride fat droplets within the heaptocytes is known as steatosis or fatty liver. It may be of two types ?","pyqMatches":[{"year":"2013","no":477,"q":"Microvesicular fatty liver is caused by ?","o":["DM","Valproate","Starvation","IBD"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6454, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 294, '{"id":6454,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":294,"q":"Localised langerhans cells histiocytosis affecting head & neck is ?","o":["Letterer-siwe disease","Pulmonary langerhans cell histiocytosis","Hand-schuller-christian disease","Eosinophilic granuloma"],"a":3,"e":"Ans. is `d i.e., Eosinophilic granuloma Clinical manifestations of Langerhans cell histiocvtosis (Histocvtosis-X1 1.Letterer Siwe disease (multifocal, multisystem LCH) Most frequently present before 2 years of age. Characterized by involvement of multiple system. Most common presentation is cutaneous lesions resembling seborrheic dermatitis. Others are hepatosplenomegaly, lymphadenopathy pulmonary lesions and destructive bone lesions. Extensive bone marrow infiltration leads to pancytopenia. 2.Eosinophilic granuloma (Unifocal and multifocal unisystem LCH) Involvement is restricted to a single system i.e., skeletal system which may be unifocal or multifical. Most commonly effected bones are skull, vertebrae, ribs, clavicle, and femur. 3.Hand-Schuller-Christian disease Characterized by triad of claviral bone defects, diabetes insipidus, and exophthalmos.","pyqMatches":[{"year":"2013","no":450,"q":"Localised langerhans cells histiocytosis affecting head & neck is ?","o":["Letterer-siwe disease","Pulmonary langerhans cell histiocytosis","Hand-schuller-christian disease","Eosinophilic granuloma"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6455, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 295, '{"id":6455,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":295,"q":"Which cytokine activate macrophages ?","o":["IL-8","IFN-y","PAF","Leukotriene B4"],"a":1,"e":"Ans. is ''b'' i.e., IFN-''y Activated macrophages Recent studies show that there are two types of activated macrophages : ?","pyqMatches":[{"year":"2013","no":414,"q":"Which cytokine activate macrophages ?","o":["IL-8","IFN-y","PAF","Leukotriene B4"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6456, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 296, '{"id":6456,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":296,"q":"Syphilitic aneurysm mostly involve ?","o":["Arch of aorta","Descending aorta","Abdominal aorta above the renal arteries","Abdominal aorta below the renal arteries"],"a":0,"e":"Ans. A. Arch of aorta The ascending aorta is the segment most commonly affected (50%), followed by the arch (35%) and the descending aorta (15%)","pyqMatches":[{"year":"2013","no":395,"q":"Syphilitic aneurysm mostly involve ?","o":["Arch of aorta","Descending aorta","Abdominal aorta above the renal arteries","Abdominal aorta below the renal arteries"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6457, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 297, '{"id":6457,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":297,"q":"Hurthle cell carcinoma is a variant of ?","o":["Medullary carcinoma","Papillary carcinoma","Follicular carcinoma","Anaplastic carcinoma"],"a":2,"e":"Ans. is ''c'' i.e., Follicular carcinoma Follicular carcinoma Second most common type of thyroid cancer. Hurthle cells are seen. Differentiated from follicular adenoma by capsular and/or vascular invasion. Unlike in papillary carcinoma, lymphatic spread is rare, and vascular invasion is common in follicular cancers. Hurthle cell or oncocytic carcinoma is a varriant of follicular carcinoma. Papillary thyroid carcinoma It is the most common type of thyroid cancer. Carcinoma cells have nuclei which contain finely dispersed chromatin, which imparts optically clear or empty appearance, giving rise to the ground glass or Orphan Annie eye nuclei. Invagination of cytoplasm may give rise to the appearance of intranuclear inclusins (Pseudoinclusions) or intranuclear grooves → the diagnosis of papillary carcinoma is based on these nuclear features. Psammoma bodies are present Lymphatic metastasis may be seen but involvement of blood vessels is rare. The nuclei of papillary carcinoma cells contain finely dispersed chromatin, which imparts an optically clear or empty appearance, giving rise to the designation ground glass or Orphan Annie eye nuclei.","pyqMatches":[{"year":"2013","no":483,"q":"Hurthle cell carcinoma is a variant of ?","o":["Medullary carcinoma","Papillary carcinoma","Follicular carcinoma","Anaplastic carcinoma"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6458, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 298, '{"id":6458,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":298,"q":"HLA is located on ?","o":["Short arm of chr-6","Long arm of chr-6","Short arm of chr-3","Long arm of chr-3"],"a":0,"e":"Ans. is ''a'' i.e., Short arm of chr- 6 HLA complex (MHC) gene is located on the short arm of chromosome 6. The histocompatibility antigens (human leukocyte antigens - HLA) are cell surface antigens that induce an immune response leading to rejection of allografts. The principal physiologic function of the cell surface histocompatibility molecules is to bind peptide fragments of foreign proteins for presentation to antigen specific T cells. The histocompatibility antigens are encoded by a closely linked multiallelic cluster of genes→Major histocompatibility complex (MHC) or Human leukocyte antigens complex (HLA complex). HLA complex of genes is located on the short arm of chromosome 6.","pyqMatches":[{"year":"2013","no":416,"q":"HLA is located on ?","o":["Short arm of chr-6","Long arm of chr-6","Short arm of chr-3","Long arm of chr-3"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6459, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 299, '{"id":6459,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":299,"q":"Classification of aortic dissection depends upon?","o":["Cause of dissection","Level of aorta affected","Percentage of aorta affected","None"],"a":1,"e":"Ans. is ''b'' i.e., Level of aorta affected Classification of Aortic dissection The risk and nature of serious complications of dissection depend strongly on the level of aorta affected, with the most serious complications occuring from the aortic valve to the arch. Thus aortic dissections are generally classified into two types ? Proximal lesion (Type A) More common and more dangerous. Involve either the ascending portion only or both ascending and the descending portion of aorta. Distal lesion (Type B) Involve only discending part distal to subclavian artery.","pyqMatches":[{"year":"2013","no":396,"q":"Classification of aortic dissection depends upon?","o":["Cause of dissection","Level of aorta affected","Percentage of aorta affected","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6460, 'Pathology', 'Hematology', 'Easy', 'Pathology', 300, '{"id":6460,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":300,"q":"Thalassemia gives protection against ?","o":["Filaria","Kala-azar","Malaria","Leptospirosis"],"a":2,"e":"Ans. is ''c'' i.e., Malaria Types of anemia that have protective effect against P. falciparum malaria : - G6PD deficiency, Sickle cell anemia, Thalassemia, HbC, Pyruvate kinase deficiency","pyqMatches":[{"year":"2013","no":460,"q":"Thalassemia gives protection against ?","o":["Filaria","Kala-azar","Malaria","Leptospirosis"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6461, 'Pathology', 'Hematology', 'Easy', 'Pathology', 301, '{"id":6461,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":301,"q":"Maltoma is positive for?","o":["CD 3","CD 10","CD 23","CD 5"],"a":2,"e":"Ans. is ''c'' i.e., CD 23 Mantle cell lymphoma- • Surface immunoglobulin heavy chain (IgM & IgD) • CD19'', CD20* • CD5 (+)ve & CD 23 (-)ve differentiating feature from CLL • Cyclin D1","pyqMatches":[{"year":"2013","no":447,"q":"Maltoma is positive for?","o":["CD 3","CD 10","CD 23","CD 5"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6462, 'Pathology', 'Hemodynamics', 'Easy', 'Pathology', 302, '{"id":6462,"subject":"Pathology","chapter":"Hemodynamics","difficulty":"Easy","source":"Pathology","sourceNo":302,"q":"Terminal stage of pneumonia is","o":["Congestion","Red hepatization","Gray hepatization","Resolution"],"a":3,"e":"Ans. is ''d'' i.e., Resolution In the usual course of pneumonia, final stage is resolution. However, in some neglected cases following complications may develop - Abscess formation Pleural effusion, pleuritis Empyema Becteremic dissemination Brain abscess, endocarditis, meningitis, Organization supurrative arthritis. Pathological changes of bacterial pneumonia A.Lobar pneumonia Large confluent area of the lung or entire lobes are consolidated. The lower lobes are affected most commonly. There are four stages of the inflammatory response (Laennec''s stages) ?","pyqMatches":[{"year":"2013","no":433,"q":"Terminal stage of pneumonia is","o":["Congestion","Red hepatization","Gray hepatization","Resolution"],"a":3,"source":"NEET_2013_Paper.pdf"},{"year":"2016","no":446,"q":"Terminal stage of pneumonia is","o":["Congestion","Red hepatization","Gray hepatization","Resolution"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2013","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6463, 'Pathology', 'Hematology', 'Easy', 'Pathology', 303, '{"id":6463,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":303,"q":"Intestinal angiodysplasia involves ?","o":["AV malformation","Cavernous hemangioma","Capillary hemangioma","Malignant tumor"],"a":0,"e":"Ans. is ''a'' i.e., AV malformation Angiodvsplasia Angiodysplasia is characterized by malformed submucosal blood vessels (AV malformation). Lesions of angiodysplasia are ectatic nest of tortuous veins, venules and capillaries. Most common site is caecum and right colon. Usually occurs after 6th decade of life. Major presentation is bleeding (intestinal bleeding). Pathogenesis of angiodysplasia has been linked to mechanical and congenital factors :?","pyqMatches":[{"year":"2013","no":469,"q":"Intestinal angiodysplasia involves ?","o":["AV malformation","Cavernous hemangioma","Capillary hemangioma","Malignant tumor"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6464, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 304, '{"id":6464,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":304,"q":"Perifascicular atropy of muscle fibres is seen in?","o":["Steroid myopathy","Dermatomyositis","Inclusion body myositis","Nemaline myopathy"],"a":1,"e":"Ans. is ''b'' i.e., Dermatomyositis Dermatomyositis is a connective-tissue disease related to polymyositis that is characterized by inflammation of the muscles and the skin. It is a systemic disorder that may also affect the joints, the esophagus, the lungs, and, less commonly, the heart. On the muscle biopsy, there are two classic microscopic findings of dermatomyositis. They are : mixed B- & T-cell perivascular inflammatory infiltrate and perifascicular muscle fiber atrophy. It is associated with autoantibodies, especially anti-Jol antibody.","pyqMatches":[{"year":"2013","no":480,"q":"Perifascicular atropy of muscle fibres is seen in?","o":["Steroid myopathy","Dermatomyositis","Inclusion body myositis","Nemaline myopathy"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6465, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 305, '{"id":6465,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":305,"q":"Marker of glomus tumor?","o":["CD-57","Cytokeratin","S-100","CD-34"],"a":0,"e":"Ans. is ''a'' i.e., CD-57 Glomus tumor is a benign mesenchymal neoplasm of the subcutaneous tissue of the distal extremities and head & neck region. Immunohistochemistry shows smooth muscle actin, vimentin, collagen IV and CD-57, with little to no expression of neuroendocrine, endothelial or epithelial markers. Markers that have been proved consistently negative include cytokeratin, synaptophysin, chromogranin A, CD-31 and S-100 protein. Glomangioma (Glomuvenous malformation) Glomangioma is a variant of glomus tumor It is characterized by multiple tumors resembling cavernous hemangioma, lined by glomus cells. Glomangioma is blue-red, extremely painful vascular neoplasm. It involves a glomeriform arteriovenous anastomosis (glomus body) It may be found anywhere in the skin, most often in the distal portion offingers and toes, especially beneath the nails (subungal). Secondary thrombosis and phlebolith formation may occur in these lesions.","pyqMatches":[{"year":"2013","no":490,"q":"Marker of glomus tumor?","o":["CD-57","Cytokeratin","S-100","CD-34"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6466, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 306, '{"id":6466,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":306,"q":"False about wound healing ?","o":["Inhibited by infection","Inhibited by DM","Inhibited by hematoma","Inhibited by foreign body"],"a":2,"e":"Ans. is ''c'' i.e., Inhibited by hematoma Factors causing impairment of wound healing A. Systemic factors Poor nutrition (protein deficiency, vitamin C deficiency). Metabolic abnormalities (Diabetes mellitus). Poor circulatory status (Inadequate blood supply). Hormones, e.g. glucocorticoids. B. Local factors Infection is the single most important factor. Mechanical factors, e.g. early mobilization. Foreign bodies (unnecessary sutures, fragments of steel or glass). Wound in poorly vacularized area, e.g. foot.","pyqMatches":[{"year":"2013","no":411,"q":"False about wound healing ?","o":["Inhibited by infection","Inhibited by DM","Inhibited by hematoma","Inhibited by foreign body"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6467, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 307, '{"id":6467,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":307,"q":"Chromosome 22 deletion syndrome is ?","o":["Down syndrome","Di George syndrome","Turner syndrome","Klinefelter syndrome"],"a":1,"e":"Ans. is ''b'' i.e., Di George syndrome Chromosome 22q 11.2 deletion syndrome This syndrome encompasses a spectrum of disorders that result from a small deletion of band q 11.2 on long arm of chromosome 22. Clinical features are considered to represent two different disorders :? 1 Di George syndrome These patients have thymic hypoplasia with resultant T-cell immunodeficiency. Other features include parathyroid hypoplasia (causing hypocalcemia), cardiac malformations & facial anomalies. TBX-1 gene (a T-box transcription factor) is most closely associated with this syndrome. The target of TBX-1 include PAX 9, a gene that controls the development of the palate, parathyroid and thymus. 2 Velo cardio facial sndrome This syndrome is characterized by facial dysmorphism (prominant nose, retrognathia), cleft palate, cardiovascular anomalies, and learning disabilities.","pyqMatches":[{"year":"2013","no":427,"q":"Chromosome 22 deletion syndrome is ?","o":["Down syndrome","Di George syndrome","Turner syndrome","Klinefelter syndrome"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6468, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 308, '{"id":6468,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":308,"q":"Creatinine kinase is elevated in MI after -","o":["2 - 4 hrs.","4 - 8 hrs.","12 - 24 hrs","> 24 hrs."],"a":0,"e":"Ans. is ''a'' i.e., 2 - 4 hrs Enzyme Initiation of rise Peak Return to baseline CK-MB 2-4 hours 24 hours 48-72 hours Troponin T and I (TnT Tnl) 2-4 hours 48 hours 7-10 days AST/SGOT In 12 hours 48 hours 4-5 days LDH 24 hours 3-6 days 2 weeks","pyqMatches":[{"year":"2013","no":397,"q":"Creatinine kinase is elevated in MI after","o":["2 - 4 hrs.","4 - 8 hrs.","12 - 24 hrs","> 24 hrs."],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6469, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 309, '{"id":6469,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":309,"q":"Blood when stored at 4°C can be kept for ?","o":["7 days","14 days","21 days","28 days"],"a":2,"e":"Ans. is `c'' i.e., 21 days The recommend temperature for storage of blood is 1-6°C. Actually blood can be stored for more than 21 days, depending upon the type of additive used. \"Routine blood storage is limited to 21 days at 1-6°C when treated with acid-citrate-dextrose (ACD) or citrate​phosphate-dextrose (CPD); and 35 days when treated with citrate-phosposphate- dextrose-adenine (CPD-A); and 42 days when treated with saline- adenine-glucose-mannital (SAG-M)\" So, correct answer of this question can be:","pyqMatches":[{"year":"2013","no":466,"q":"Blood when stored at 4°C can be kept for ?","o":["7 days","14 days","21 days","28 days"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6470, 'Pathology', 'Hematology', 'Easy', 'Pathology', 310, '{"id":6470,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":310,"q":"AML causing Gum hypertrophy ?","o":["M1","M2","M3","M4"],"a":3,"e":"Ans. is ''d'' i.e., M4 In acute leukemias the clinical features are primarily seen because of : Replacement of normal cells of bone marrow by leukemic cells resulting in anemia, thrombocytopenia, neutropenia. Infiltration of leukemic cell in various extramedullary organs causing, hepalomegaly, splenomegaly. Gum hypertrophy due to infiltration of gums by leukemic cells is one such feature. It is characteristically associated with AML-M5 and AML-M4 i.e. (acute monocytic leukemia).","pyqMatches":[{"year":"2013","no":448,"q":"AML causing Gum hypertrophy ?","o":["M1","M2","M3","M4"],"a":3,"source":"NEET_2013_Paper.pdf"},{"year":"2015","no":461,"q":"AML causing Gum hypertrophy ?","o":["M1","M2","M3","M4"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2013","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6471, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 311, '{"id":6471,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":311,"q":"Type of necrosis in pancreatitis ?","o":["Fibrinoid","Coagulative","Fat","Caseous"],"a":2,"e":"Ans. is ''c'' i.e., Fat Fat necrosis is seen most frequently in acute pancreatitis due to leakage of lipase. Fat necrosis Fat necrosis may be of two types : ?","pyqMatches":[{"year":"2013","no":385,"q":"Type of necrosis in pancreatitis ?","o":["Fibrinoid","Coagulative","Fat","Caseous"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6472, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 312, '{"id":6472,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":312,"q":"Resolution of inflammation caused by ?","o":["TNF Alfa, IL-1 and CRP","TNF beta, IL-6 and CRP","TNF Alfa, IL 10 and IL 1 receptor antagonist","TNF gamma"],"a":2,"e":"Ans. is '' c'' i.e., TNF Alfa, IL-10 and IL 1 receptor antagonist Actually no option is absolutely correct: IL-10 is an anti-inflammatory cytokine Cause resolution of inflammation IL-1 is a pro-inflammatory cytokine → IL-1 receptor antagonism will cause resolution of inflammation TNF-a is an pro-inflammatory cytokine → causes inflammation So, in option C, two mediators are correct and one is incorrect regarding resolution of inflammation. However, among the given options only option C is the closest one. Proinflammatory cytokines Major :- IL-1, TNF- alpha, IL-6 Other :- IL-2, IL-4, IL-5, IL-6, IL-8, IL-11, IL-12, IL-15, IL-21, IL-23, ITN- gamma, GM-CSF Anti-inflammatory cytokines IL-4, IL-10, IL-13 Here, you can consider IL-4 as pro-inflammatory cytokine ( as more than one options can be correct in PGI​chandigarh).","pyqMatches":[{"year":"2013","no":409,"q":"Resolution of inflammation caused by ?","o":["TNF Alfa, IL-1 and CRP","TNF beta, IL-6 and CRP","TNF Alfa, IL 10 and IL 1 receptor antagonist","TNF gamma"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6473, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 313, '{"id":6473,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":313,"q":"Not a carcinogen for bladder cancer?","o":["Benzidine","Isopropyl alcohol","Acrolein","Phenacetin"],"a":1,"e":"Ans. is ''b'' i.e., Isopropyl alcohol Risk factors for transitional cell carcinoma (TCC) of bladder ? Smoking -4 Major etiological factor. Occupational exposure to chemicals → Nephthylamine benzidine, aniline dyes, acrolein. Schistosoma haematobium (Bilharziasis)→ It is a risk factor for both TCC & SCC. Drugs —> Phenacetin Cyclophosphamide therapy Pelvic irradiations","pyqMatches":[{"year":"2013","no":443,"q":"Not a carcinogen for bladder cancer?","o":["Benzidine","Isopropyl alcohol","Acrolein","Phenacetin"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6474, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 314, '{"id":6474,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":314,"q":"Drug induced lupus antibodies are found in ?","o":["Anti-Rho","Ds-DNA","Anti-Sm","Anti-histone antibody"],"a":3,"e":"Ans. is ''d'' i.e., Anti Histone antibody Drug induced lupus erythematosus A lupus like syndrome may develop in patients receiving a variety of drugs. Procainamide and hydralazine are most common offenders. Most patients do not have symptoms of lupus erythematosus. Anti ds DNA antibody is rare There is an extremely high frequency of antihistone antibodies. Although multiple organs may be affected renal and CNS involvement, usually does not occur.","pyqMatches":[{"year":"2013","no":417,"q":"Drug induced lupus antibodies are found in ?","o":["Anti-Rho","Ds-DNA","Anti-Sm","Anti-histone antibody"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6475, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 315, '{"id":6475,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":315,"q":"Donath landsteiner antibody is seen in?","o":["PNH","Waldenstrom''s macroglobulinemia","Paroxysmal cold hemoglobinuri","Malaria"],"a":2,"e":"Ans. is ''c'' i.e., Paroxysmal cold hemoglobinuria Paroxysmal cold hemogjobinuria (PCH) PCH is characterized by intermittent massive intravascular hemolysis frequently with hemoglobinuria at low temprature. The autoantibodies are of IgG class, also known as Donath- Landsteiner antibody. These antibodies are directed against P-antigen on RBC. Antigen antibody complex on the red blood cell activates complement. As a result, large amount of membrane attack complex forms which destroys red cells directly → intravascular hemolysis. Causes are : - Syphilis, Mycoplasma, Mumps, Measles, Flu syndrome","pyqMatches":[{"year":"2013","no":461,"q":"Donath landsteiner antibody is seen in?","o":["PNH","Waldenstrom''s macroglobulinemia","Paroxysmal cold hemoglobinuri","Malaria"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6476, 'Pathology', 'Hematology', 'Easy', 'Pathology', 316, '{"id":6476,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":316,"q":"Cryoprecipitate is useful in?","o":["Hemophilia A","Thrombosthenia","A fibrogenemi a","Warfarin reversal"],"a":2,"e":"Ans. is ''c'' i.e., Afibrogenemia Cryoprecipitate was originally developed for the treatment of hemophilia A. It is no longer the treatment of choice for that disorder because less infectious alternatives are available. At the present time, Cryoprecipitate is most often used for correction of hypofibrinogenemia in bleeding patients.","pyqMatches":[{"year":"2013","no":493,"q":"Cryoprecipitate is useful in?","o":["Hemophilia A","Thrombosthenia","A fibrogenemi a","Warfarin reversal"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6477, 'Pathology', 'Hematology', 'Easy', 'Pathology', 317, '{"id":6477,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":317,"q":"DIC is common in which AML -","o":["Nonocytic (M5)","Promyelo cytic (M3)","Erythrocytic (M6)","Megakaryocytic (M7)"],"a":1,"e":"Ans. is ''b'' i.e., Promyelocytic Tumor cells in acute promyelocytic leukemia (M3) release procoagulant and fibrinolytic factors that cause disseminated intravascular coagulation (DIC).","pyqMatches":[{"year":"2013","no":449,"q":"DIC is common in which AML","o":["Nonocytic (M5)","Promyelo cytic (M3)","Erythrocytic (M6)","Megakaryocytic (M7)"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6478, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 318, '{"id":6478,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":318,"q":"Example ofApoptosis is?","o":["Councilman Bodies","Gamma Gandy Body","Russell bodies","None"],"a":0,"e":"Ans. is ''a'' i.e., Councilman bodies Apoptotic body One of the murphological hallmark of apoptosis is the apoptotic body which is eosinophilic and may contain some karryorhectic nuclear bebris. It is a result of shrinkage of cytoplasm and nuclear disruption. First there is surface blebbing and margination of chromatin which is followed by cell shrinkage and breakup into smaller apoptotic bodies. These apoptotic bodies are taken up by surrounding cells and digested. Since the process was seen for a long time before the mechanism was understood, apoptotic bodies in particular situations attracted specific names:","pyqMatches":[{"year":"2013","no":386,"q":"Example ofApoptosis is?","o":["Councilman Bodies","Gamma Gandy Body","Russell bodies","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6479, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 319, '{"id":6479,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":319,"q":"Fibrinoid necorsis with neutrophilic infiltration is seen in ?","o":["PAN","Giant cell arteritis","Takayasu arteritis","Wegener''s granulomatosis"],"a":0,"e":"Ans. is ''a'' i.e., PAN Among the given options, PAN is predominantly necrotizing vasculitis, characterized by fibrinoid necrosis. During acute phase of PAN, there is transmural inflammation with mixed infiltrate of neutrophils, eosinophils and mononuclear cells with accompanied fibrinoid necrosis. Other three options are predominantly granulomatous vasculitis.","pyqMatches":[{"year":"2013","no":401,"q":"Fibrinoid necorsis with neutrophilic infiltration is seen in ?","o":["PAN","Giant cell arteritis","Takayasu arteritis","Wegener''s granulomatosis"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6480, 'Pathology', 'Hematology', 'Easy', 'Pathology', 320, '{"id":6480,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":320,"q":"Most common ocular lymphoma ?","o":["T-cell lymphoma","Hodgkin''s lymphoma","B-cell NHL","Pre T-cell lymphoma"],"a":2,"e":"Ans. is ''c'' i.e., B-cell NHL non-Hodgkin lymphoma (NHL) is the most common type of ocular lymphoma.","pyqMatches":[{"year":"2013","no":492,"q":"Most common ocular lymphoma ?","o":["T-cell lymphoma","Hodgkin''s lymphoma","B-cell NHL","Pre T-cell lymphoma"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6481, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 321, '{"id":6481,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":321,"q":"Cytokine causing fever -","o":["IL-6","IFN-y","IL-18","IL-4"],"a":0,"e":"Ans. is ''a'' i.e., IL-6 Pvrogenes Pyrogenes are substances that cause fever. Pyrogens may be exogenous or endogenous Exogenous → Bacterial toxins Endogenous → IL-1, TNF-a, IL-6, Interferons, Ciliory''s neurotropic factor These pyrogenes increase the level ofPGE2 in the hypothalamus that elevates the thermoregulatory set point and causes fever.","pyqMatches":[{"year":"2013","no":410,"q":"Cytokine causing fever","o":["IL-6","IFN-y","IL-18","IL-4"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6482, 'Pathology', 'Hematology', 'Easy', 'Pathology', 322, '{"id":6482,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":322,"q":"Normal transferrin is saturated with iron ?","o":["20%","35%","50%","70%"],"a":1,"e":"Ans. is ''b'' i.e., 35% In normal individuals, transferrin is about one third saturated with iron, yielding serum iron levels that average 120 g/dl in men and 100 g/dl in women. Serum ferritin Most of the ferritin is stored is different organs (liver, spleen, bone marrow). Very small amounts of ferritin normally circulate in the plasma. Since plasma ferritin is derived largely form the storage pool of body iron, its level correlate well with body iron stores. i.e., when there is iron depletion, body store of iron is reduced that inturn leads to decrease in plasma ferritin. Transferrin saturation and iron binding capacity Iron is transported in the plasma by transferrin. Normally transferrin is 33% saturated (77% free) with iron, yield serum iron levels that average 100-120 g/dl. So, if serum transferrin will be 100% saturated the serum iron will be 300 g/dl. that means the total iron binding capacity of transferrin is 300 to 350 g/dl. When iron store is depleted e.g., in iron dificiency anemia, there is increased synthesis of transferrin that results in increased total iron binding capacity. When iron store is repleted e.g., anemia of chronic disease, there is decreased synthesis of transferrin that results in decreased total iron binding capacity. Serum transferrin receptors Erythroid precursors have receptors for transferrin by which they recieve iron from transferrin that is utilized for hemoglobin synthesis. When erythroid precursors mature, these receptors are shed into plasma and can be masured as serum transferrin receptors concentration. In iron deficiency state, there is increased erythropoisis in bone marrow→ T concentration of erythroid precursor that results in increased total number of transferrin receptor —> T serum transferrin receptor concentration.","pyqMatches":[{"year":"2013","no":462,"q":"Normal transferrin is saturated with iron ?","o":["20%","35%","50%","70%"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6483, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 323, '{"id":6483,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":323,"q":"All of the following immunohistochemical markers are positive in the neoplatic cells of granulocytic sarcoma, except ?","o":["CD45 RO","CD 43","Myeloperoxidase","Lysozyme"],"a":0,"e":"Ans. is ''a'' i.e., CD 45 RO Granulocytic sarcoms (Chloroma or myeloblastoma) Granulocytic sarcoms or chloroma is a solid tumor composed of myeloblasts. A chloroma is an extramedullary manifestation of AML, i.e., it is a solid collection of leukemic cells occuring outsited of the bone marrow. These tumor often have a green tint due to the presence of myeloperoxidase. Chloromas are more common in monocytic differentiation (M4 & M5 type) AML. Though chloromas occurs most commonly in patients with AML, they may also occur in patient with : ? Myelodysplastic syndrome Myeloproliferative syndromes Myelofibrosis, CML, Polycythemia vera, Essential thrombocytosis in) Without concomitant disease, i.e., Primary chloroma. Chloromas are positive for : ? CD 68 CD 20 CD 117 Lysozyme CD 43 CD 34 Myeloperoxidase","pyqMatches":[{"year":"2013","no":452,"q":"All of the following immunohistochemical markers are positive in the neoplatic cells of granulocytic sarcoma, except ?","o":["CD45 RO","CD 43","Myeloperoxidase","Lysozyme"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6484, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 324, '{"id":6484,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":324,"q":"In glomerulus subendothelial deposits are seen in?","o":["Good pasture syndrome","IgA nephropathy","MPGN type I","MPGN type II"],"a":2,"e":"Ans. is ''c'' i.e., MPGN type I Sub endothelial - MPGN (Type-1), SLE, Acute ON","pyqMatches":[{"year":"2013","no":440,"q":"In glomerulus subendothelial deposits are seen in?","o":["Good pasture syndrome","IgA nephropathy","MPGN type I","MPGN type II"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6485, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 325, '{"id":6485,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":325,"q":"Thromboangitis obliterans is associated with ?","o":["HLA B27","HLA - DR4","HLA - B5","HLA - DR2"],"a":2,"e":"Ans. is ''c'' i.e., HLA - B5 Thromboangitis obliterans (Berger disease) Thrombangitis obliterans is a distinctive disease that is characterized by segmental, thrombosing acute and chronic inflammation of medium sized and small sized arteries, and sometimes secondarily extending to veins and nerves. Thromboangitis obliterans occurs almost exclusively among heavy- cigarrete-smoking persons. It is more common in men but incidence is increasing in women because of increasing smoking habit in women. o Buerger disease is associated with HLA B-5 and HLA-A9. In thrombongitis obliterans there is acute and chronic segmental inflammation of vessels with accompanied thrombosis in the lumen. Typically, the thrombus contains microabscesses with a central focus of neutrophils surrounded by gran u lomatous inflammation. Later, the inflammatory process extends into contiguous veins and nerves and in time all three structures (arteries, veins and nerves) become encased in fibrous tissue, a characterstic that is very rare with other form of vasculitis. Clinical manifestations Thrombangitis obliterans affects vessels of upper and lower extremities. Symptoms are due to vascular insufficiency, i.e. Ischemia of toes, feet and fingers that can lead to ulcer and frank gangrene. Due to neural involvement, there may be severe pain, even at rest.","pyqMatches":[{"year":"2013","no":402,"q":"Thromboangitis obliterans is associated with ?","o":["HLA B27","HLA - DR4","HLA - B5","HLA - DR2"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6486, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 326, '{"id":6486,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":326,"q":"Which antibodies in mother with SLE is responsible for congenital heart disease in child?","o":["Anti-histone","Anti-Ro & Anti-LA","Anti ds DNA","Anti-centromere"],"a":1,"e":"Ans. is ''b'' i.e., Anti-Ro & Anti-LA Most sensitive Antinuclear antibody (ANA) Most specific Antidouble stranded anitbody and the antibody against smith (Sm) Associted with neonatal Anti Ro, AntiLA antibody lupus and congenital heart block Associated with lupus Anti P antibody psychosis","pyqMatches":[{"year":"2013","no":418,"q":"Which antibodies in mother with SLE is responsible for congenital heart disease in child?","o":["Anti-histone","Anti-Ro & Anti-LA","Anti ds DNA","Anti-centromere"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6487, 'Pathology', 'Immunopathology', 'Moderate', 'Pathology', 327, '{"id":6487,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Moderate","source":"Pathology","sourceNo":327,"q":"Xerostomia is seen in all except ?","o":["Sjogren syndrome","RA","Sarcoidosis","Midline granuloma"],"a":3,"e":"Ans. is ''d'' i.e., Midline granuloma Sjogren syndrome Sjogren syndrome is a chronic disease characterized by dry eyes (keratoconjuctivitis sicca) and dry mouth (xerostomia) resulting from immunological mediated destruction of the lacrimal and salivary glands. o It occurs in two forms ? Primary form (SICCA SYNDROME)→ Occurs as an isolated disorder. Secondry form When it occurs in association with other autoimmune disorder. It is more common. o Autoimmune diseases associated with sjogren syndrome Rheumatoid arthritis Primary biliary cirrhosis Thyroiditis SLE Mixed connective tissue disease Sarcoidosis Polymyositis Vasculitis Scleroderma Chronic active hepatitis Amongst these, Sjogren syndrome is associated most commonly with RA.","pyqMatches":[{"year":"2013","no":419,"q":"Xerostomia is seen in all except ?","o":["Sjogren syndrome","RA","Sarcoidosis","Midline granuloma"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6488, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 328, '{"id":6488,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":328,"q":"True regarding fibromuscular dysplasia are all except -","o":["Medium size vessels","OCPs predispose","Aneurysm may occur","Irregular hyperplasia"],"a":1,"e":"Ans. is ''b'' i.e., OCPs predispose Fibromuscular dysplasia It is focal irregular thickening of the walls of medium and large muscular arteries, including renal, carotid, splanchnic, and vertebral vessels. Segments of vessel wall are focally thickened by a combination of irregular medial and intimal hyperplasia and fibrosis, causing luminal stenosis. In renal vessels, it may cause renovascular hypertension. Aneurysm may develop in the vessel segment with attenuated media, and can rupture in some cases. There is no association with use of oral contraceptives or sex hormone abnormalities.","pyqMatches":[{"year":"2013","no":403,"q":"True regarding fibromuscular dysplasia are all except","o":["Medium size vessels","OCPs predispose","Aneurysm may occur","Irregular hyperplasia"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6489, 'Pathology', 'Immunopathology', 'Moderate', 'Pathology', 330, '{"id":6489,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Moderate","source":"Pathology","sourceNo":330,"q":"Peliosis hepatis is caused by all except?","o":["Analgesics","Anabolic steroids","OC pills","Danazol"],"a":0,"e":"Ans. is ''a'' i.e., Analgesics Peliosis hepatitis is a rare condition in which there is primarily sinusoidal dilatation. The liver contains blood filled cystic spaces, either unlined or lined with sinusoidal endothelial cells. Peliosis hepatitis is associated with many diseases including cancer, TB, AIDS or post transplantation immunodeficiency. It is also associated with exposure to anabolic steroids and rarely, oral contraceptives and danazol.","pyqMatches":[{"year":"2013","no":478,"q":"Peliosis hepatis is caused by all except?","o":["Analgesics","Anabolic steroids","OC pills","Danazol"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6490, 'Pathology', 'Hematology', 'Easy', 'Pathology', 331, '{"id":6490,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":331,"q":"Pseudo-Pelger-Huet cells or seen in","o":["Hairy cell leukemia","Multiple myeloma","Mylodysplastic syndrome","Hodgkin''s lymphoma"],"a":2,"e":"Ans. is ''c'' i.e., Myelodysplastic syndrome Peripheral blood shows the presence of Pseudo- Pelger-Huet cells, giant platelets, macrocytes, poikilocytes and monocytosis. Clinical features are seen in only 50% patients including weakness, infection and hemorrhage due to pancytopenia. Usually patients are of an old age (mean age of onset is > 60 years). The prognosis is poor.","pyqMatches":[{"year":"2013","no":453,"q":"Pseudo-Pelger-Huet cells or seen in","o":["Hairy cell leukemia","Multiple myeloma","Mylodysplastic syndrome","Hodgkin''s lymphoma"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6491, 'Pathology', 'Inflammation', 'Moderate', 'Pathology', 332, '{"id":6491,"subject":"Pathology","chapter":"Inflammation","difficulty":"Moderate","source":"Pathology","sourceNo":332,"q":"Acute phase reactants are all except ?","o":["C-reactive protein","Haptaglobulin","Endothelin","Fibrinogen"],"a":2,"e":"Ans. is ''c'' i.e., Endothelin Acute phase proteins (reactants) Acute phase reactants are a class of proteins whose plasma concentration increases or decreases in response to inflammation. This response is called the acute phase reaction (acute phase response) It should be noted that acute phase proteins not only increase in response to inflammation ; some decrease also","pyqMatches":[{"year":"2013","no":823,"q":"Acute phase reactants are all except ?","o":["C-reactive protein","Haptaglobulin","Endothelin","Fibrinogen"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6492, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 333, '{"id":6492,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":333,"q":"All are true about non-bacterial thrombotic endocarditis, except ?","o":["Cause emboli","Vegetation > 5 mm","No inflammatory reaction","Locally nondestructive"],"a":1,"e":"Ans. is ''b'' i.e., Vegetation > 5 mm Nonbacterial thrombotic endocarditis (NBTE) NBTE is characterized by the deposition of small sterile thrombi on the leaflets of the cardiac valves. The lesions are small, ranging from 1 mm to 5 mm. They occur singly or multiply along the lines of closure of leaflet or cusps. They are composed of bland thrombi that are loosely attached to the underlying valve. The vegetations are not invasive and do not elicit any inflammatory reaction. Thus, the local effect of vegetations is usually unimportant but they may be the source of systemic emboli. NBTE is often encountered in debilitated patients. It is seen in hypercoagulable states, e.g. cancer, promyelocytic leukemia, mutinous adinocarcinomas and increased estrogenic state.","pyqMatches":[{"year":"2013","no":399,"q":"All are true about non-bacterial thrombotic endocarditis, except ?","o":["Cause emboli","Vegetation > 5 mm","No inflammatory reaction","Locally nondestructive"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6493, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 334, '{"id":6493,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":334,"q":"Which one of the following stains is specific forAmyloid?","o":["Periodic Acid schif (PAS)","Alzerian red","Congo red","Von - Kossa"],"a":2,"e":"Ans. is ''c'' i.e., Congo Red \"To differentiate amyloid from other hyaline deposits (eg. Collagen and fibrin), a variety of histochemical techniques are used, of which the most widely used is Congo Red\" - Robbins 7''/e p. 259 Staining for Amyloid Congo red : It is the most widely used specific stain for amyloid. Iodine staining : It is used for unfixed specimen or histological section. Amyloid stains mahogany brown and if sulfuric acid is added, it turns violet. Thioflavin ''T'' and `S'' give secondary immunoflurescence with ultraviolet light. Thioflavin T is more useful for demonstrating juxtalomerular apparatus of the kidney. Metachromatic stains like crystal violet and methyl violet give rose pink appearance. Amyloid is PAS positive.","pyqMatches":[{"year":"2013","no":421,"q":"Which one of the following stains is specific forAmyloid?","o":["Periodic Acid schif (PAS)","Alzerian red","Congo red","Von - Kossa"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6494, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 335, '{"id":6494,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":335,"q":"All are true about Fragile X syndrome except ?","o":["Large head","Large nose","Large ear","Large testis"],"a":1,"e":"Ans. is ''b'' i.e., Large nose Fragile - X syndrome Fragile - X syndrome is the prototype of diseases in which the mutation is characterized by a long repeating sequence of three nucleotides. In fragile X syndrome,trinucleotidc repeat mutation involve CGG on non coding region. Clinical features of fragile - X syndrome Mental retardation q Long face with large mandible q Hyperexntesible joint q Mitral valve prolapse Large everted ears q Large testis (macro-orchidism) High arched palate Fragile X syndrome is the second most common cause of mental retardation, after Downs syndrome.","pyqMatches":[{"year":"2013","no":426,"q":"All are true about Fragile X syndrome except ?","o":["Large head","Large nose","Large ear","Large testis"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6495, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 336, '{"id":6495,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":336,"q":"Concentric hypertrophy of left ventricle is seen in?","o":["Mitral stenosis","Hypertension","Aortic regurgitation","None"],"a":1,"e":"Ans. is ''b'' i.e., Hypertension Concentric hypertrophy —> In pressure overload, e.g. hypertension and aortic stenosis. o Eccentric hypertrophy → In volume overload, e.g. in aortic regurgitation. Adaptations in heart The cardiac myocyte is terminally differentiated cell that is not able to divide. Myocardium cannot undergo hyperplasia, i.e. increase in the number of myocyte. So, myocardium can adapt by increasing the size (i.e. hypertrophy) of the myocyte in response to stress. There are two types of stresses to heart","pyqMatches":[{"year":"2013","no":400,"q":"Concentric hypertrophy of left ventricle is seen in?","o":["Mitral stenosis","Hypertension","Aortic regurgitation","None"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2015","no":443,"q":"Concentric hypertrophy of left ventricle is seen in","o":["Cong. bicuspid aortic valve","MS","AR","HOCM"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2013","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6496, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 337, '{"id":6496,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":337,"q":"Which does not cause sideroblastic anaemia?","o":["INH","Chloramphenicol","Myelodysplastic anaemia","Mercury"],"a":3,"e":"Ans. is ''d'' i.e., Mercury","pyqMatches":[{"year":"2013","no":464,"q":"Which does not cause sideroblastic anaemia?","o":["INH","Chloramphenicol","Myelodysplastic anaemia","Mercury"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6497, 'Pathology', 'Hematology', 'Moderate', 'Pathology', 338, '{"id":6497,"subject":"Pathology","chapter":"Hematology","difficulty":"Moderate","source":"Pathology","sourceNo":338,"q":"Which of the following is not a myeloproliferative disease ?","o":["Polycythemia vers","Acute myeloid leukemia","Chronic myeloid leukemia","Essential thrombocytosis"],"a":1,"e":"Ans. is ''b'' i.e., Acute myeloid leukemia Chronic myeloproliferative disorders The disorders in this group are ? Chronic myeloid leukemia Essential thrombocytosis Polycythemia vera Primary myelofibrosis These disease are characterized by neoplastic proliferation of multipotent progenitor cell that is capable of giving rise to mature erythrocytes, platelets, granulocytes, monocytes and lymphocytes. An important feature of myeloproliferative disorders is that in their terminal phase they are characterized by marrow fibrosis and peripheral blood cytopenia. All of them can progress over time to acute leukemia, but only CML does so invariably. Remember CML, Polycythemia vera and essential thrombocytosis can progress to myelofibrosis in terminal stage.","pyqMatches":[{"year":"2013","no":454,"q":"Which of the following is not a myeloproliferative disease ?","o":["Polycythemia vers","Acute myeloid leukemia","Chronic myeloid leukemia","Essential thrombocytosis"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6498, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 339, '{"id":6498,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":339,"q":"All of the following are associated with carcinoma colon except ?","o":["Smoking","Alcohol","Fibre diet","Fatty food"],"a":2,"e":"Ans. is ''c'' i.e., Fibre diet Fibre diet is protective against colon cancer (see previous explanations). Risk factors for Colon cancer","pyqMatches":[{"year":"2013","no":473,"q":"All of the following are associated with carcinoma colon except ?","o":["Smoking","Alcohol","Fibre diet","Fatty food"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6499, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 340, '{"id":6499,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":340,"q":"Which of the following is labile cell ?","o":["Cardiac cell","Liver parenchymal cell","Vascular endothelial cells","Surface epithelium"],"a":3,"e":"Ans. is ''d'' i.e., Surface epithelium When a cell proliferates, it pass through a cell cycle. Cell cycle has a series of phases : G phase → Rest phase (Presynthetic phase) S phase → Synthetic phase in which synthesis of DNA takes place. G2phase → Resting phase (Postsynthetic or postmitotic phase). M phase → Mitotic phase in which mitosis takes place. Go phase → When cell is not proliferating, it remains in quiescent phase (Go). Based on their proliferative capacity, cells are divided into S Go G,","pyqMatches":[{"year":"2013","no":388,"q":"Which of the following is labile cell ?","o":["Cardiac cell","Liver parenchymal cell","Vascular endothelial cells","Surface epithelium"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6500, 'Pathology', 'Hematology', 'Easy', 'Pathology', 341, '{"id":6500,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":341,"q":"Glanzmann thrombasthenia is due to","o":["Decreased GpIb","Decreased GpIIb/IIIa","Anti-GpIIb/IIIa antibodies","Inhibition or deficiency of ADAMTS 13"],"a":1,"e":"Ans. is. b. Decreased GpIIb/IIIa Glanzmann thrombasthenia is an autosomal recessive disorder. There is a failure of primary platelet aggregation with ADP or collagen due to inherited deficiency of two platelets membrane glycoproteins. It is caused due to deficiency of glycoprotein IIb- IIIa.","pyqMatches":[{"year":"2019","no":51,"q":"Glanzmann thrombasthenia is due to","o":["Decreased GpIb","Decreased GpIIb/IIIa","Anti-GpIIb/IIIa antibodies","Inhibition or deficiency of ADAMTS 13"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6501, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 342, '{"id":6501,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":342,"q":"Vitamin A is stored in","o":["Cells of Ito","Hepatocyte","Endothelial cell","Kupffer cell"],"a":0,"e":"Answer A – Cells of Ito HSCs (hepatic stellate cells) (also called vitamin A-storing cells, lipocytes, interstitial cells, fat-storing cells or Ito cells) exist in the space between parenchymal cells and liver sinusoidal endothelial cells of the hepatic lobule and store 50-80% of vitamin A in the whole body as retinyl palmitate in lipid droplets in the cytoplasm.","pyqMatches":[{"year":"2019","no":50,"q":"Vitamin A is stored in","o":["Cells of Ito","Hepatocyte","Endothelial cell","Kupffer cell"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6502, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 343, '{"id":6502,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":343,"q":"Apoptotic gene is-","o":["Bax","Bcl2","Bclx","Mcl"],"a":1,"e":"Answer-B. Bcl2 Regulation is primarily by the Bcl-2 family of genes located on chromosome 18. Some members of this family like bak, bid, bin, Bcl-xs (to remember, S for stimulating apoptosis) stimulate apoptosis whereas others like Bcl-2, Bcl-xl (to remember, L for lower apoptosis), etc inhibit apoptosis. Gene families such as caspases, inhibitor of apoptosis proteins, B cell lymphoma (Bcl)-2 family of genes, tumor necrosis factor (TNF) receptor gene superfamily, or p53 gene are involved, and/or collaborate in the process of apoptosis.","pyqMatches":[{"year":"2019","no":52,"q":"Apoptotic gene is","o":["Bax","Bcl2","Bclx","Mcl"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6503, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 344, '{"id":6503,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":344,"q":"Alpha one anti trypsin works by","o":["inhibition of trypsin","inhibition of trypsinogen","inhibition of elastase","inhibition of chymotrypsin"],"a":2,"e":"Answer- C (inhibition of elastase) Explanation- Alpha-1 antitrypsin (A1AT) is produced in the liver, and one of its functions is to protect the lungs from neutrophil elastase, an enzyme that can disrupt connective tissue.","pyqMatches":[{"year":"2019","no":53,"q":"Alpha one anti trypsin works by","o":["inhibition of trypsin","inhibition of trypsinogen","inhibition of elastase","inhibition of chymotrypsin"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6504, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 345, '{"id":6504,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":345,"q":"Which one of the following is an autosomal recessive disorder?","o":["Albinism","Huntington’s syndrome","Marfan’s syndrome","Neurofibromatosis-1"],"a":0,"e":"Answer-A. Albinism Explanation- Albinism is caused by mutations in one of several genes, and most types are inherited in an autosomal recessive manner.","pyqMatches":[{"year":"2019","no":54,"q":"Which one of the following is an autosomal recessive disorder?","o":["Albinism","Huntington’s syndrome","Marfan’s syndrome","Neurofibromatosis-1"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6505, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 346, '{"id":6505,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":346,"q":"Fish mouth appearance of valve in RHD is due to-","o":["Rupture of valve","Calcification & fibrosis","Hypertrophy of ventricular wall","None of the above"],"a":1,"e":"Answer- B.Calcification & fibrosis In rheumatic heart disease, an autoimmune attack on the mitral valve produces thickening of the valve leaflets. The mitral valve is often described as having a “fish-mouth” appearance.","pyqMatches":[{"year":"2019","no":55,"q":"Fish mouth appearance of valve in RHD is due to","o":["Rupture of valve","Calcification & fibrosis","Hypertrophy of ventricular wall","None of the above"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6506, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 347, '{"id":6506,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":347,"q":"Follicular lymphoma positivity?","o":["Bcl-1","Bcl-6","Bcl- 2","None of the above"],"a":2,"e":"Answer-C. Bcl-2 A translocation between chromosome 14 and 18 results in the overexpression of the bcl-2 gene.As the bcl-2 protein is normally involved in preventing apoptosis, cells with an overexpression of this protein are basically immortal. The bcl-2 gene is normally found on chromosome 18, and the translocation moves the gene near to the site of the immunoglobulin heavy chain enhancer element on chromosome 14.","pyqMatches":[{"year":"2019","no":56,"q":"Follicular lymphoma positivity?","o":["Bcl-1","Bcl-6","Bcl- 2","None of the above"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6507, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 348, '{"id":6507,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":348,"q":"what is the histological difference between them in Ulcerative colitis & Crohn’s disease?","o":["Diffuse distribution of pseudopolyps","Mucosal edema","Crypt abscess","Lymphoid aggregates in the mucosa"],"a":2,"e":"differences between ulcerative colitis and Crohn''s disease are as follows: ulcerative colitis Crohns disease common site ileocolitis with rectal sparing procolitis, rectum protective factor no factors Smoking Appendicectomy common risk factors antibiotic during the first year of life, turner syndrome antibiotic during the first year of life, turner syndrome risk factor OCP, Smoking α-Methyldopa, Wiskott– Aldrich Syndrome, T cell involved TH1 TH2 Earliest macroscopic finding Aphthous Ulcer Erythematous mucosa with a fine granular surface Wall involved Transmural mucosa & submucosa Pseudopolyp less common most common type of ulcer serpentine Collar-button ulcers cobblestone t t t cobb esto e appearance present not present skin lesions seen not seen Creeping fat seen not seen Granuloma non-caseating granuloma seen not seen Fistula classical- perinatal (enterocutaneous) not seen strictures common not common Toxic megacolon not seen seen Crypt abscess and destruction less marked more marked Rose thorn appearance seen not seen metaplasia Pyloric metaplasia is a clinical marker paneth cell metaplasia Renal calculi calcium oxalate not present Extraintestinal manifestations uveitis, migratory polyarthritis, sacroiliitis, ankylosing spondylitis, erythema nodosum, clubbing, Primary sclerosing cholangitis Similar to Crohn disease Named criteria to assess the severity -------- True Love Witt’s criteria-UC","pyqMatches":[{"year":"2019","no":57,"q":"what is the histological difference between them in Ulcerative colitis & Crohn’s disease?","o":["Diffuse distribution of pseudopolyps","Mucosal edema","Crypt abscess","Lymphoid aggregates in the mucosa"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6508, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 349, '{"id":6508,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":349,"q":"What is the cause of intracorpuscular defects in hemolysis?","o":["Uremic syndrome","PCH","PNH","Portal hypertension"],"a":2,"e":"Answer-C. PNH","pyqMatches":[{"year":"2019","no":58,"q":"What is the cause of intracorpuscular defects in hemolysis?","o":["Uremic syndrome","PCH","PNH","Portal hypertension"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6509, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 350, '{"id":6509,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":350,"q":"Type of necrosis seen in blood vessels due to immune reactions-","o":["Coagulation","Liquefaction","Fibrinoid","None"],"a":2,"e":"Answer- C (Fibrinoid) In small vessel vasculitis, fibrin plugs frequently occur in the vessel lumen, but the term fibrinoid is usually used to refer to material outside the lumen of a vessel.Fibrinoid necrosis also occurs in the walls of arterioles in malignant hypertension.","pyqMatches":[{"year":"2019","no":59,"q":"Type of necrosis seen in blood vessels due to immune reactions","o":["Coagulation","Liquefaction","Fibrinoid","None"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6510, 'Pathology', 'Miscellaneous', 'Hard', 'Pathology', 351, '{"id":6510,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Hard","source":"Pathology","sourceNo":351,"q":"In a patient with lipoprotein lipase deficiency, which of the following is increased following a fatty meal?","o":["Chylomicron","LDL","HDL","Apo-A"],"a":0,"e":"Answer- A. Chylomicron Lipoprotein lipase deficiency (Type I hyperlipoproteinemia): is a rare, autosomal recessive disorder caused by a deficiency of lipoprotein lipase.Resulting in fasting chylomicronemia and hypertriglycerolemia.There is slow clearance of chylomicrons and VLDL. Low levels of LDL and HDL. There is no increased risk of coronary disease.","pyqMatches":[{"year":"2019","no":60,"q":"In a patient with lipoprotein lipase deficiency, which of the following is increased following a fatty meal?","o":["Chylomicron","LDL","HDL","Apo-A"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6511, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 352, '{"id":6511,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":352,"q":"In Wilson’s disease, there is less urinary excretion of-","o":["Phosphorus","Methyl- Histidine","Phosphotyrosine","Serine"],"a":1,"e":"Answer-B. Methyl- Histidine Essentials of Diagnosis & Typical Features of Wilson disease: Acute or chronic liver disease Deteriorating neurologic status Kayser-Fleischer rings Elevated liver copper Abnormalities in levels of ceruloplasmin and serum and urine copper.","pyqMatches":[{"year":"2019","no":61,"q":"In Wilson’s disease, there is less urinary excretion of","o":["Phosphorus","Methyl- Histidine","Phosphotyrosine","Serine"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6512, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 353, '{"id":6512,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":353,"q":"What is the function of IL1?","o":["Enhances hematopoiesis","Stimulates mast cells","Has antiviral properties","Endogenous pyrogen"],"a":3,"e":"Answer- D (Endogenous pyrogen) was formerly known as lymphocyte-activating factor (LAF). augments the activity of many cell types, especially T cells. is an endogenous pyrogen (EP). induces an increase in acute phase reactants. is a heat-stable and pH-stable peptide with a molecular weight of 17.5 kd. occurs in two forms: IL-1Î± and IL-1Î².","pyqMatches":[{"year":"2019","no":62,"q":"What is the function of IL1?","o":["Enhances hematopoiesis","Stimulates mast cells","Has antiviral properties","Endogenous pyrogen"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6513, 'Pathology', 'Hemodynamics', 'Easy', 'Pathology', 354, '{"id":6513,"subject":"Pathology","chapter":"Hemodynamics","difficulty":"Easy","source":"Pathology","sourceNo":354,"q":"CEAP score indicates-","o":["Atrial disorders","Venous disorder","Neurological disorde","Trauma disorder"],"a":1,"e":"Answer- B. ( Venous disorder) Comprehensive Classification System for Chronic Venous Disorders (CEAP) CEAP classification of chronic venous disease Clinical classification C3 Edema C4a Pigmentation or eczema C4b Lipodermatosclerosis or athrophie blanche C5 Healed venous ulcer","pyqMatches":[{"year":"2019","no":63,"q":"CEAP score indicates","o":["Atrial disorders","Venous disorder","Neurological disorde","Trauma disorder"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6514, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 355, '{"id":6514,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":355,"q":"IL- 1 activated by-","o":["Capsase 1","Capsase 3","Capsase 8","Capsase 5"],"a":0,"e":"Answer- A (Capsase 1) The two inflammatory cytokines activated by Caspase-1 are excreted from the cell to further induce the inflammatory response in neighboring cells.","pyqMatches":[{"year":"2019","no":64,"q":"IL- 1 activated by","o":["Capsase 1","Capsase 3","Capsase 8","Capsase 5"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6515, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 356, '{"id":6515,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":356,"q":"Parotid mass mixed consistency","o":["Pleomorphic adenoma","Sebaceous cyst","Dermoid cyst","All"],"a":0,"e":"Answer- A (Pleomorphic adenoma) It is also known as “Mixed tumor, salivary gland type”, which refers to its dual origin from epithelial and myoepithelial elements as opposed to its pleomorphic appearance.","pyqMatches":[{"year":"2019","no":65,"q":"Parotid mass mixed consistency","o":["Pleomorphic adenoma","Sebaceous cyst","Dermoid cyst","All"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6516, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 357, '{"id":6516,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":357,"q":"Krabbe’s disease is-","o":["Deficiency of Beta- galactosylcermidase","Deficiency of aryl sulphatase","Alpha galactosidase","Acid lipase"],"a":0,"e":"Answer- A (Deficiency of Beta- galactosylcermidase) Krabbe disease is caused by mutations in the GALC gene located on chromosome 14 (14q31),which is inherited in an autosomal recessive manner. Mutations in the GALC gene cause a deficiency of an enzyme called galactosylceramidase.","pyqMatches":[{"year":"2019","no":66,"q":"Krabbe’s disease is","o":["Deficiency of Beta- galactosylcermidase","Deficiency of aryl sulphatase","Alpha galactosidase","Acid lipase"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6517, 'Pathology', 'Hematology', 'Easy', 'Pathology', 358, '{"id":6517,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":358,"q":"What is the choice of treatment for idiopathic thrombocytopenia purpura (ITP)?","o":["Blood transfusion","Spontaneous recovery","IV infusion","Splenectomy"],"a":3,"e":"Answer- D (Splenectomy) Beneficial effects of splenectomy in chronic ITP are due to both removal of the major site of platelet destruction and the major source of autoantibody synthesis.","pyqMatches":[{"year":"2019","no":67,"q":"What is the choice of treatment for idiopathic thrombocytopenia purpura (ITP)?","o":["Blood transfusion","Spontaneous recovery","IV infusion","Splenectomy"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6518, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 359, '{"id":6518,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":359,"q":"Most common nephropathy associated with malignaneN is:","o":["Focal segmental glomerulosclerosis (FSGS)","Minimal change disease","IgA nephropathy","Membranous glomerulonephritis"],"a":3,"e":"Ans: D. Membranous glomerulonephritis Most common nephropathy associated with malignancy - Membranous glomerulonephritis. In 25-30% - Associated with malignancy (solid tumors of breast, lung, colon), infection (hepatitis B, malaria, Schistosomiasis), or rheumatologic disorders like lupus or rarely rheumatoid arthritis. Histopathology: Electron-dense deposits along the epithelial side of the basement membrane with effacement of foot processes overlying deposits. (Ref Robbins 9/e p917-918; Harrison 19/e p1843).","pyqMatches":[{"year":"2015","no":468,"q":"Most common nephropathy associated with malignaneN is:","o":["Focal segmental glomerulosclerosis (FSGS)","Minimal change disease","IgA nephropathy","Membranous glomerulonephritis"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6519, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 360, '{"id":6519,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":360,"q":"Which of the following complement factors is a marker of humoral rejection?","o":["C3d","C3b","C4d","C5a"],"a":2,"e":"Ans: C. C4d (Ref: Robbins 9/e p234) C4d factor is a marker for humoral rejection. Acute antibody-mediated rejection is manifested mainly by damage to glomeruli and small blood vessels. Typically, the lesions consist of inflammation of glomeruli and peritubular capillaries, associated with deposition of the complement breakdown product C4d, which is produced during activation of the complement system by the antibody- dependent classical pathway. Small vessels may also show focal thrombosis.","pyqMatches":[{"year":"2015","no":780,"q":"Which of the following complement factors is a marker of humoral rejection?","o":["C3d","C3b","C4d","C5a"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6520, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 361, '{"id":6520,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":361,"q":"Most reactive free radical is:","o":["Peroxide","Carboxyl","Hydroxyl","Superoxide"],"a":2,"e":"Ans: C. Hydroxyl (Ref Robbins 9/e p480) Hydroxyl radical (*OH) is the most potent reactive oxygen species. Most reactive oxygen-derived free radical. Principal ROS responsible for damaging lipids proteins & DNA.","pyqMatches":[{"year":"2015","no":394,"q":"Most reactive free radical is:","o":["Peroxide","Carboxyl","Hydroxyl","Superoxide"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6521, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 362, '{"id":6521,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":362,"q":"Alpha-fetoprotein is a tumor marker for","o":["Hepato cellular carcinoma","Multiple myeloma","Seminoma","Breast carcinoma"],"a":0,"e":"Answer- A. Hepato cellular carcinoma Alpha-feto protein (AFP) AFP is a well estabilished tumor marker It is a glycoprofein synthesized normaily early in fetal life by the yolk sac, fetal liver and fetal GIT. AFP is raised in - Carcinomas > Liver Ca, Lung Ca, Colon Ca, Pancreatic Ca, Non- seminoma germ cell tumor of testis. Non-neoplastic conditions > Cirrhosis, Hepatitis, Pregnancy","pyqMatches":[{"year":"2014","no":433,"q":"Alpha-fetoprotein is a tumor marker for","o":["Hepato cellular carcinoma","Multiple myeloma","Seminoma","Breast carcinoma"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6522, 'Pathology', 'Inflammation', 'Moderate', 'Pathology', 363, '{"id":6522,"subject":"Pathology","chapter":"Inflammation","difficulty":"Moderate","source":"Pathology","sourceNo":363,"q":"Hypercalcemia in sarcoidosis all are true except?","o":["Parathormone level is increased","PTHrP level is increased","Calcitriol level is increased","Oral steroids are useful"],"a":0,"e":"Answer- A. Parathormone level is increased Extrarenal synthesis of calcitriol [1,25(OH)2D3] is central to the pathogenesis of abnormal calcium metabolism in sarcoidosis. Sarcoidosis causes an increase in l, 25-dihydroxy vitamin D, the active metabolite of vitamin D, which is usually hydrorylated within the kidney, but in sarcoidosis patients hydroxylation of vitamin D can occur outside the kidneys, mainly inside the immune cells found in the granulomas and produces 1 alpha, 25(OH)2D3, which is the main cause for hypercalcemia in sarcoidosis. PTH release is inhibited by hypercalcaemia and high levels of calcitriol, so PTH level is suppressed in sarcoidosis.","pyqMatches":[{"year":"2013","no":364,"q":"Hypercalcemia in sarcoidosis all are true except?","o":["Parathormone level is increased","PTHrP level is increased","Calcitriol level is increased","Oral steroids are useful"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6523, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 364, '{"id":6523,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":364,"q":"Toll like receptors are seen on?","o":["Macrophages","Natural killer cells","Endothelial cells","All of the above"],"a":3,"e":"Answer-D. All of the above The Toll-like receptors are rnembrane proteins that recognize avariety of microbe-derived molecules and stimulate innate immune responses against the microbes. The Toll-like receptors are expressed on many different cell types that participate in innate immune responses including ,macrophages, dendritic cells, neutrophils, NKs cells, mucosal epithelial cells and endothelial cells.","pyqMatches":[{"year":"2016","no":388,"q":"Toll like receptors are seen on?","o":["Macrophages","Natural killer cells","Endothelial cells","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6524, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 365, '{"id":6524,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":365,"q":"Reversible change from on cell type to other is known as -","o":["Hyperplesia","Hypertrophy","Metaplesia","Dysplasia"],"a":2,"e":"Ans. is ''c'' i.e., Metaplesia [Ref: Robbin''s 9th/e p. 37 6,stye p 10] Metaplasia is an adaptive change in which one adult (mature) cell type is replaced by another adult (mature) cell. It is completely reversible","pyqMatches":[{"year":"2015","no":427,"q":"Reversible change from on cell type to other is known as","o":["Hyperplesia","Hypertrophy","Metaplesia","Dysplasia"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6525, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 366, '{"id":6525,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":366,"q":"Gaseous necrosis is seen in -","o":["CMV infection","Staphylococcal infection","Treponemal infection","HSV infection"],"a":2,"e":"Ans. is ''c'' i.e., Treponemal infection [Ref Robbin''s 9`\"/e p. 43; Anderson''s 10thie p. 375] Caseous necrosis is a feature of syphilis which is caused by tremonemal infection. Gaseous necrosis It is a variant of coagulative necrosis. It is most commonly encountered when cell death is attributable to ertain organisms e.g., mycobacterium tuberculosis (TB), syphilis and fungi (Histoplasma, Coccidioidomycosis).","pyqMatches":[{"year":"2013","no":384,"q":"Gaseous necrosis is seen in","o":["CMV infection","Staphylococcal infection","Treponemal infection","HSV infection"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6526, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 367, '{"id":6526,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":367,"q":"Substance playing a role in tumor metastasis cascade is","o":["Collagenase IV","TNF-alpha","CD99","NM23"],"a":0,"e":"Ans is ''a'' i.e. Collagenase IV Various steps of metastasis and molecules involved","pyqMatches":[{"year":"2015","no":399,"q":"Substance playing a role in tumor metastasis cascade is","o":["Collagenase IV","TNF-alpha","CD99","NM23"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6527, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 368, '{"id":6527,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":368,"q":"Rb gene is located on which chromosome?","o":["6","9","13","21"],"a":2,"e":"Ans. is ''c'' i.e.,13 [Ref Robbin''s 9tVe p. 290] Retinoblastoma gene (RB gene) is located on 14 band on the long arm of chromosome 13 (13q14). RB gene is a tumor supressor gene. Retinoblastoma develops when both the normal alleles of the RB genes are inactive or altered. It is typical example of Knudson''s two hit hypothesis.","pyqMatches":[{"year":"2014","no":426,"q":"Rb gene is located on which chromosome?","o":["6","9","13","21"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6528, 'Pathology', 'Genetic Disorders', 'Easy', 'Pathology', 369, '{"id":6528,"subject":"Pathology","chapter":"Genetic Disorders","difficulty":"Easy","source":"Pathology","sourceNo":369,"q":"Absence of Ultra hepatic bile duct leads to which syndrome?","o":["Von Meyenburg Complexes","Polycystic Liver Disease","Caroli Disease","Alagille Syndrome"],"a":3,"e":"Answer- D. Alagille Syndrome It is an autosomal recessive condition characterized by absence of bile ducts in portal tract Also called arterio hepatic dysplasia Characteristic features: Genetic disorder with vascular, biliary and other anomalies. Absence of intrahepatic bile ducts with clinical severity ranging from severe neonatal cholestasis mimicking biliary atresia to childhood intermittent jaundice. Progression to cirrhosis is rare.","pyqMatches":[{"year":"2015","no":1228,"q":"Absence of Ultra hepatic bile duct leads to which syndrome?","o":["Von Meyenburg Complexes","Polycystic Liver Disease","Caroli Disease","Alagille Syndrome"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6529, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 370, '{"id":6529,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":370,"q":"True about Dentigerous cyst:","o":["Arises in relation to unerupted teeth","It most commonly encroaches maxillary antrum","Mandibular third molar is common site","Common in mandible e) All"],"a":0,"e":":C:D Answer- A,Arises in relation to unerupted teeth C,Mandibular third molar is common site D,Common in mandible Common in lower jaw (mandible) in women 30-40 years. It occurs in relation to unerupted, permanent, molar tooth, most commonly the upper or lower third molar.","pyqMatches":[{"year":"2015","no":1325,"q":"True about Dentigerous cyst:","o":["Arises in relation to unerupted teeth","It most commonly encroaches maxillary antrum","Mandibular third molar is common site","Common in mandible e) All"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6530, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 371, '{"id":6530,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":371,"q":"Vitamin A deficiency leads to metaplasia of?","o":["Squamous epithelium","Columnar epithelium","Both","None"],"a":0,"e":"Answer- A. Squamous metaplasia It occurs most frequently in respiratory tract as a result of chronic irritation by cigarette smoking. The columnar epithelium is replaced by squamous epithelium. This squamous metaplasia represents an attempt by the host to repair or prepare an epithelial tissue that has been damaged by environmental toxicants with a more resistant tissue. Squamous metaplasia is also encountered in other location such as pancreatic duct (Vit A deficiency, stones in pancreatic duct), gall bladder (gall stones), urinary bladder (bladder calculi, Schistosomiasis), and in endocervix. Though the metaplasia is reversible, if the influences that predispose to metaplasia is persistent, malignant transformation may occur in metaplastic epithelium.","pyqMatches":[{"year":"2016","no":354,"q":"Vitamin A deficiency leads to metaplasia of?","o":["Squamous epithelium","Columnar epithelium","Both","None"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6531, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 372, '{"id":6531,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":372,"q":"Nuclei are arranged at the cell periphery in which type of cell?","o":["Langhans giant cell","Merkel cells","NK cells","Neutrophils"],"a":0,"e":"Answer- A. Langhans giant cell Peripheral nuclei are seen in Langhans type giant cells Langhans giant cells are large cells found in granulomatous conditions. They are formed by the fusion of epithelioid cells (macrophages) and contain nuclei arranged in a horseshoe-shaped pattern in the cell periphery. These cells contain 3-5 nuclei. Nuclei are arranged around the periphery in the form of a horseshoe. These cells may also act as precursors of foreign body giant cells. These cells are seen in TB & sarcoidosis.","pyqMatches":[{"year":"2016","no":361,"q":"Nuclei are arranged at the cell periphery in which type of cell?","o":["Langhans giant cell","Merkel cells","NK cells","Neutrophils"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6532, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 373, '{"id":6532,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":373,"q":"Not true about VEGF is -","o":["Highly specific for endothelium","Hypoxia potentiates its expression","Inhibits angiogenesis","Helps in tumor metastasis"],"a":2,"e":"Answer- C. Inhibits angiogenesis Vascular endothelial growth factor (VEGF) is a potent angiogenic factor and was first described as an essential growth factor for vascular endothelial cells. VEGF is up-regulated in many tumors and its contribution to tumor angiogenesis is well defined. In addition to endothelial cells, VEGF receptors are expressed on numerous non-endothelial cells including tumor cells. Binds to endo-specific receptors Flt-1 and Flk-1 (of the tyrosine kinase family). Expression of VEGF potentiated by hypoxia and inactivation of p53. The two most important angiogenic factors in a tumor are VEGF and basic fibroblast growth factor (bFGF), thus helping in tumor metastasis.","pyqMatches":[{"year":"2016","no":362,"q":"Not true about VEGF is","o":["Highly specific for endothelium","Hypoxia potentiates its expression","Inhibits angiogenesis","Helps in tumor metastasis"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6533, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 374, '{"id":6533,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":374,"q":"Acute phase reactants are stimulated by -","o":["IL-6","IL-1","TNF-a","All of the above"],"a":3,"e":"Answer- D. All of the above In response to injury, local inflammatory cells (neutrophil granulocytes and macrophages) secrete a number of cytokines into the bloodstream, most notable of which are the interleukins IL6 and IL8, and TNFa. The liver responds by producing a large number of acute-phase reactants.","pyqMatches":[{"year":"2016","no":364,"q":"Acute phase reactants are stimulated by","o":["IL-6","IL-1","TNF-a","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6534, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 375, '{"id":6534,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":375,"q":"Lymphotactin is which type of chemokine?","o":["C","C- C","C-X-C","C-X3-C"],"a":2,"e":"Answer- C. C-X-C C - chemokines :- They are specific for lymphocytes, e.g. lymphotactin.","pyqMatches":[{"year":"2016","no":366,"q":"Lymphotactin is which type of chemokine?","o":["C","C- C","C-X-C","C-X3-C"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6535, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 376, '{"id":6535,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":376,"q":"Active compound secreted by neutrophills against pathogen is known as?","o":["Major basic protein","Myeloperoxidase","Hydrolase","Proteoglycans"],"a":1,"e":"Answer- B. Myeloperoxidase The azurophilic granules of neutrophils contain the enzyme myeloperoxidase (MPO), which In the presence of a halide such as Cl-, convertes H202 to hypochlorite (HoC1).","pyqMatches":[{"year":"2016","no":368,"q":"Active compound secreted by neutrophills against pathogen is known as?","o":["Major basic protein","Myeloperoxidase","Hydrolase","Proteoglycans"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6536, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 377, '{"id":6536,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":377,"q":"Hydroxyl ions are destroyed in the body by?","o":["Vitamin C","Vitamin A","Vitamin K","Vitamin D"],"a":0,"e":"Answer- A. Vitamin C \"Vitamin C and other water soluble compounds, such as uric acid, thiols including glutathione and dihydrolipoic acid and possibly other substances such as metallothionein, serve to defend against hydroxyl radicals. Vitamin E, in contrast, is less effective in eliminating hydroxyl radicals.","pyqMatches":[{"year":"2016","no":502,"q":"Hydroxyl ions are destroyed in the body by?","o":["Vitamin C","Vitamin A","Vitamin K","Vitamin D"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6537, 'Pathology', 'Neoplasia', 'Hard', 'Pathology', 378, '{"id":6537,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Hard","source":"Pathology","sourceNo":378,"q":"Most common cancer to occur in organ transplant patient is?","o":["Squamous cell carcinoma","Melanoma","Lung cancer","Colorectal cancer"],"a":0,"e":"Answer- A. Squamous cell carcinoma most common tumors after transplant Non melanoma skin cancer (SCC >BCC) (most common) NHL (2nd most common) Lung carcinoma Kaposi''s sarcoma HCC Cervical carcinoma","pyqMatches":[{"year":"2016","no":501,"q":"Most common cancer to occur in organ transplant patient is?","o":["Squamous cell carcinoma","Melanoma","Lung cancer","Colorectal cancer"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6538, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 379, '{"id":6538,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":379,"q":"Example of coagulative necrosis is -","o":["Acute tubular necrosis","Stroke","Malignant hypertension","Acute pancreatitis"],"a":0,"e":"Answer- A. Acute tubular necrosis The causes of coagulative necrosis are :","pyqMatches":[{"year":"2016","no":356,"q":"Example of coagulative necrosis is","o":["Acute tubular necrosis","Stroke","Malignant hypertension","Acute pancreatitis"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6539, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 380, '{"id":6539,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":380,"q":"Trilateral retinoblastoma is?","o":["Bilateral Retinoblastoma plus medulloblastoma","Bilateral retinoblastoma plus pineoblastoma","Bilateral retinoblastoma plus neuroblastoma","Bilateral retinoblastoma plus ependymoma"],"a":1,"e":"Answer- B. Bilateral retinoblastoma plus pineoblastoma Trilateral retinoblastoma (TRb) refers to the combination of retinoblastoma (usually bilateral) and pineoblastoma. This relationship highlights the close relationship between these highly aggressive small round blue cell tumors.","pyqMatches":[{"year":"2016","no":500,"q":"Trilateral retinoblastoma is?","o":["Bilateral Retinoblastoma plus medulloblastoma","Bilateral retinoblastoma plus pineoblastoma","Bilateral retinoblastoma plus neuroblastoma","Bilateral retinoblastoma plus ependymoma"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6540, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 381, '{"id":6540,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":381,"q":"What is the first sign of injury?","o":["Mitochondrial dysfunction","Membrane damage","Diminished ATP","Release of lysosomal enzymes"],"a":0,"e":"Answer- A. Mitochondrial dysfunction hypoxia is the most common cause of cell injury. Oxygen is an important requirement of mitochondria for the formation of ATP; therefore, hypoxia will result in the earliest involvement of mitochondria resulting in decreased formation of ATP. Diminished ATP constitutes the critical mechanism of the cellular injury which leads to: a. Intracellular accumulation of Ca+2 b. Mitochondrial dysfunction c. Membrane damage d. Release of lysosomal (hydrolytic) enzymes","pyqMatches":[{"year":"2016","no":358,"q":"What is the first sign of injury?","o":["Mitochondrial dysfunction","Membrane damage","Diminished ATP","Release of lysosomal enzymes"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6541, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 382, '{"id":6541,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":382,"q":"Salivary schintigraphy is useful in?","o":["Monomorphic adenoma","Pleomorphic adenoma","Sialidinitis","Sjogren syndrome"],"a":3,"e":"Answer- D. Sjogren syndrome Technitium pertechnetate scans (Salivary scintigraphy) tests the size, shape and function of the salivary glands. It is useful.","pyqMatches":[{"year":"2016","no":499,"q":"Salivary schintigraphy is useful in?","o":["Monomorphic adenoma","Pleomorphic adenoma","Sialidinitis","Sjogren syndrome"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6542, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 383, '{"id":6542,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":383,"q":"Most common site for ectopic thyroid tissue is?","o":["Ovaries","Lingual","In front of hyoid bone","Stomach"],"a":1,"e":"Answer- B. Lingual By far the most common location is near its embryological origin at the foramen caecum, resulting in a lingual thyroid. This accounts for 90% of all cases of ectopic thyroids.","pyqMatches":[{"year":"2016","no":498,"q":"Most common site for ectopic thyroid tissue is?","o":["Ovaries","Lingual","In front of hyoid bone","Stomach"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6543, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 384, '{"id":6543,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":384,"q":"Blebs are found in which type of injury?","o":["Reversible","Irreversible","Both","None"],"a":0,"e":"Answer- A. Reversible Pathological features of reversible cell injury are : Cellular swelling (earliest); loss of microvilli; cytoplasmic membrane blebs; ER swelling; Myeline figures; detachment of ribosome from ER; cytoplasmic (lipid) vacuole; clumping of chromatin.","pyqMatches":[{"year":"2016","no":359,"q":"Blebs are found in which type of injury?","o":["Reversible","Irreversible","Both","None"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6544, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 385, '{"id":6544,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":385,"q":"Hydropic change is due to -","o":["Accumulation of water intracellularly","Fat accumulation intracellularly","Lysozyme degeneration","Glycogen accumulation intracellularly"],"a":0,"e":"Answer- A> Accumulation of water intracellulary Hydropic change (abominoid degeneration, hydropic degeneration, parenchymatous degeneration, cloudy swelling) of a cell is degenerative change, in which the cells swell due to injury to the membrane affecting Ionic transfer, causing the cytoplasm to appear cloudy and water to accumulate between the cells, with resultant Swelling of the tissue. Cellular swelling (hydropic change) is the earliest change in cell injury (reversible).","pyqMatches":[{"year":"2016","no":360,"q":"Hydropic change is due to","o":["Accumulation of water intracellularly","Fat accumulation intracellularly","Lysozyme degeneration","Glycogen accumulation intracellularly"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6545, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 386, '{"id":6545,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":386,"q":"Sphenoid dysplasia is seen in?","o":["NF-1","Tuberous sclerosis","Sturge-Weber syndrome","Creutzfeldt-Jakob disease"],"a":0,"e":"Answer- A. NF-1 NF-1 is diagnosed if two of following sevens are present :","pyqMatches":[{"year":"2016","no":496,"q":"Sphenoid dysplasia is seen in?","o":["NF-1","Tuberous sclerosis","Sturge-Weber syndrome","Creutzfeldt-Jakob disease"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6546, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 387, '{"id":6546,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":387,"q":"Hob nail appearance is seen in","o":["Clear cell carcinoma","Endodermal sinus tumor","HCC","Choriocarcinoma"],"a":0,"e":"Answer- A. Clear cell carcinoma Hobnail cell is a cell with a characteristic appearance, including a bulbous nucleus and nuclear projections into the cytoplasm. Hobnail cells are found in clear cell ovarian adenocarcinoma, collecting duct carcinoma, and in end-stage cirrhosis","pyqMatches":[{"year":"2016","no":495,"q":"Hob nail appearance is seen in","o":["Clear cell carcinoma","Endodermal sinus tumor","HCC","Choriocarcinoma"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6547, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 388, '{"id":6547,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":388,"q":"Chromosome for MEN2 gene is","o":["11q13","13q11","10811.2","11q10-2"],"a":2,"e":"Answer- C. 10811.2 Multiple endocrine neoplasia type 1 MEN1 11813 Multiple endocrine neoplasia type 2a RET 10811.2","pyqMatches":[{"year":"2016","no":494,"q":"Chromosome for MEN2 gene is","o":["11q13","13q11","10811.2","11q10-2"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6548, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 389, '{"id":6548,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":389,"q":"X-linked adrenoleukodystrophy is","o":["Fatty acid disorder","Lysosomal storage disorder","Mucoplysaccharridoses","Glycogen defect disorder"],"a":0,"e":"Answer- A. Fatty acid disorder X-linked adrenoleukodystrophy(ALD/X-ALD) is a disease is caused by mutations in ABCD1, a gene located on the X chromosome, that codes for ALD, a peroxisomal membrane transporter protein.","pyqMatches":[{"year":"2016","no":493,"q":"X-linked adrenoleukodystrophy is","o":["Fatty acid disorder","Lysosomal storage disorder","Mucoplysaccharridoses","Glycogen defect disorder"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6549, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 390, '{"id":6549,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":390,"q":"Endothelial molecule involved in rolling is -","o":["ICAM 1","VCAM 1","CD 31","CD 34"],"a":3,"e":"Answer- D. CD 34 Endothelial molecule- Major Role P-selectin- Rolling E-selectin- Rolling and adhesion GlyCam- 1, CD34- Rolling ICAM-1 (Immunoglobulin family)- Adhesion, arrest, transmigration VCAM-1 (Immunoglobulin family)- Adhesion PECAM-1 (CD-31)- Diapedesis (transmigration)","pyqMatches":[{"year":"2016","no":363,"q":"Endothelial molecule involved in rolling is","o":["ICAM 1","VCAM 1","CD 31","CD 34"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6550, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 391, '{"id":6550,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":391,"q":"Stain used for tubulin is","o":["Luna stain","Cajal stain","SiR stain","Masson''s trichrome"],"a":2,"e":"Answer- C. SiR stain fluorescent stains (SiR-Actin and SiR-Tubulin) are cell permeable compounds which stain F-actin and microtubules, respectively.","pyqMatches":[{"year":"2016","no":492,"q":"Stain used for tubulin is","o":["Luna stain","Cajal stain","SiR stain","Masson''s trichrome"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6551, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 392, '{"id":6551,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":392,"q":"Folding defect is associated with which disease","o":["Parkinson''s disease","Marfan syndrome","Acute intermittent porphyria","Wermer syndrome"],"a":0,"e":"Answer- A. Parkinson''s disease Defective protein folding disorders (DPFDs) are a group of diverse neurological and systemic diseases in which the hallmark pathological event is the misfolding, aggregation and accumulation of a protein in different organs, inducing cellular apoptosis, tissue damage and organ dysfunction . Includes Alzheimer''s disease, transmissible spongiform encephalopathies, serpin-deficiency disorders, sickle cell anemia, Huntington''s disease, diabetes type II, amyotrophic lateral sclerosis, Parkinson''s disease, dialysis-related amyloidosis, spinocerebellar ataxias, secondary or reactive amyloidosis, cystic fibrosis and prion diseases.","pyqMatches":[{"year":"2016","no":491,"q":"Folding defect is associated with which disease","o":["Parkinson''s disease","Marfan syndrome","Acute intermittent porphyria","Wermer syndrome"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6552, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 393, '{"id":6552,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":393,"q":"Marker for neuroblastoma among the following is?","o":["NMP 22","Chromogranin A","LDH","32 microglobulin"],"a":1,"e":"Answer- B. Chromogranin A Neuroendocrine markers of neuroblastoma :- i) CD-56 ii) Chromogranin-A iii) Synaptophysin","pyqMatches":[{"year":"2016","no":488,"q":"Marker for neuroblastoma among the following is?","o":["NMP 22","Chromogranin A","LDH","32 microglobulin"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6553, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 394, '{"id":6553,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":394,"q":"Vasodilatation following endothelial damage is due to ?","o":["Histamine","IL-2","TGF-3","FGF"],"a":0,"e":"Answer- A. Histamine Vasodilatation :- Histamine, prostaglandins (PG D2, PGE2), prostacyclins, serotonin, Nitric oxide, bradykinin","pyqMatches":[{"year":"2016","no":365,"q":"Vasodilatation following endothelial damage is due to ?","o":["Histamine","IL-2","TGF-3","FGF"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6554, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 395, '{"id":6554,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":395,"q":"Least desmoplastic breast carcinoma is","o":["Ductal","Lobular","Tubular","Medullary"],"a":1,"e":"Answer- B. Lobular \"Invasive lobular carcinoma has a tendency to spread diffusely or between the collagen fibers of the breast and produces desmoplastic response\"","pyqMatches":[{"year":"2016","no":487,"q":"Least desmoplastic breast carcinoma is","o":["Ductal","Lobular","Tubular","Medullary"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6555, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 396, '{"id":6555,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":396,"q":"Metastasis to thyroid comes from which primary site of malignancy?","o":["Liver","Testis","Prostate","Kidney"],"a":3,"e":"Answer- D. Kidney Most common primary sites are kidney, breast, lung, uterus, and melanoma.","pyqMatches":[{"year":"2016","no":485,"q":"Metastasis to thyroid comes from which primary site of malignancy?","o":["Liver","Testis","Prostate","Kidney"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6556, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 397, '{"id":6556,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":397,"q":"Choroid metastasis is associated most commonly with?","o":["Gastric carcinoma","Renal carcinoma","Brain tumor","Bone tumor"],"a":1,"e":"Answer- B. Renal carcinoma Tumors most likely to metastasize to the choroid plexus are renal cell carcinoma and lung cancer. Other tumors with documented spread to the choroid plexus include colon, gastric, breast, thyroid, and bladder cancers, melanoma and lymphoma.","pyqMatches":[{"year":"2016","no":483,"q":"Choroid metastasis is associated most commonly with?","o":["Gastric carcinoma","Renal carcinoma","Brain tumor","Bone tumor"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6557, 'Pathology', 'Infectious Diseases', 'Moderate', 'Pathology', 398, '{"id":6557,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Moderate","source":"Pathology","sourceNo":398,"q":"All are associated with diabetic gangrene except?","o":["Wet gangrene","Dry gangrene","Gas gangrene","Fournier''s gangrene"],"a":2,"e":"Answer- C. Gas gangrene It is a bacterial infection that produces gas within tissues. It can be caused by Clostridium, most commonly alpha toxin producing Clostridium perfringens, or various non-clostridial species.","pyqMatches":[{"year":"2016","no":482,"q":"All are associated with diabetic gangrene except?","o":["Wet gangrene","Dry gangrene","Gas gangrene","Fournier''s gangrene"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6558, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 399, '{"id":6558,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":399,"q":"Stain used for staining the nucleus is?","o":["Safranin","Fast green","Hematoxylin","Erythrosine"],"a":2,"e":"Answer- C. Hematoxylin Hematoxylin stains the cell nucleus and other acidic structures (such as RNA-rich portions of the cytoplasm and the matrix of hyaline cartilage) blue, while eosin stains cytoplasm, connective tissue and other extracellular substances pink or red.","pyqMatches":[{"year":"2016","no":481,"q":"Stain used for staining the nucleus is?","o":["Safranin","Fast green","Hematoxylin","Erythrosine"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6559, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 400, '{"id":6559,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":400,"q":"Primary granules contain which enzyme?","o":["Myeloperoxidase","Hydrolases","Lactoferrin","Phospholipase A2"],"a":0,"e":"Answer- A. Myeloperoxidase Myeloperoxidase Lysozyme Acid hydrolases Elasases Nonspecific collegenase Bacterial permeability protein Defensin (BPI) Cathepsin G Phospholipase A2","pyqMatches":[{"year":"2016","no":367,"q":"Primary granules contain which enzyme?","o":["Myeloperoxidase","Hydrolases","Lactoferrin","Phospholipase A2"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6560, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 401, '{"id":6560,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":401,"q":"Peroxidase enzyme found in neutrophills is used for -","o":["Macrophage activation","Chemotactic agent","Microbial killing","Vasodilatation"],"a":2,"e":"Answer- C. Microbial killing Peroxidase (myeloperoxidase) is involved in phagocytosis (microbial killing).","pyqMatches":[{"year":"2016","no":369,"q":"Peroxidase enzyme found in neutrophills is used for","o":["Macrophage activation","Chemotactic agent","Microbial killing","Vasodilatation"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6561, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 402, '{"id":6561,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":402,"q":"Penile carcinoma is usually?","o":["Squamous cell carcinoma","Basal cell carcinoma","Adenocarcinoma","Small cell carcinoma"],"a":0,"e":"Answer- A. Squamous cell carcinoma Most of penile cancers are squamous cell carcinoma and arise on glans or inner surface of prepuce.","pyqMatches":[{"year":"2016","no":480,"q":"Penile carcinoma is usually?","o":["Squamous cell carcinoma","Basal cell carcinoma","Adenocarcinoma","Small cell carcinoma"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6562, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 403, '{"id":6562,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":403,"q":"Delayed umbilical cord detachment leukocytosis is seen in?","o":["Leukocyte adhesion deficiency","Chronic granulomatous disease","Severe combined immunodeficiency","None of the above"],"a":0,"e":"Answer- A. Leukocyte adhesion deficiency Leukocyte adhesion deficiency type 1 is a disorder that causes the immune system to malfunction, resulting in a form of immunodeficiency One of the first signs of leukocyte adhesion deficiency type 1 is a delay in the detachment of the umbilical cord stump after birth. In newborns, the stump normally falls off within the first two weeks of life; but, in infants with leukocyte adhesion deficiency type 1, this separation usually occurs three weeks or later. Also, affected infants often have inflammation of the umbilical cord stump (omphalitis) due to a bacterial infection. It''s due to the absence of CD 18 antigen that''s necessary for the formation of integrins, the substances that are responsible for the second step of leukocyte migration: adhesion. Because the leukocytes cannot efficiently reach the site of insult, they cannot engulf the offending substance, and no pus will be evident. Also, as a compensatory mechanism, there may be excessive leukocytosis.","pyqMatches":[{"year":"2016","no":372,"q":"Delayed umbilical cord detachment leukocytosis is seen in?","o":["Leukocyte adhesion deficiency","Chronic granulomatous disease","Severe combined immunodeficiency","None of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6563, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 404, '{"id":6563,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":404,"q":"Collar button ulcer is found in?","o":["Ulcerative colitis","Crohn''s disease","Shigella","All of the above"],"a":3,"e":"Answer- D. All of the above \"Collar button ulcers\", a radiological sign, are manifestations of inflammatory processes within the bowel. Collar button ulcers have also been observed in the setting of other inflammatory bowel processes, such as Crohn''s disease, ischemic colitis, and shigellosis.","pyqMatches":[{"year":"2016","no":478,"q":"Collar button ulcer is found in?","o":["Ulcerative colitis","Crohn''s disease","Shigella","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6564, 'Pathology', 'Hematology', 'Easy', 'Pathology', 405, '{"id":6564,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":405,"q":"Phlegmonous gastritis occurs due to?","o":["H. pylori","E. coli","C. jejuni","Cl. Tetani"],"a":1,"e":"Answer- B. E. coli Most cases of phlegmonous gastritis are due to alpha-hemolytic streptococci, although pneumococci, staphylococci, Escherichia coli, and rarely, Proteus Vulgaris and Clostridium welchii can be the causative organisms.","pyqMatches":[{"year":"2016","no":477,"q":"Phlegmonous gastritis occurs due to?","o":["H. pylori","E. coli","C. jejuni","Cl. Tetani"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6565, 'Pathology', 'Hemodynamics', 'Easy', 'Pathology', 406, '{"id":6565,"subject":"Pathology","chapter":"Hemodynamics","difficulty":"Easy","source":"Pathology","sourceNo":406,"q":"Decrease in plasma osmotic pressure is cause of edema in?","o":["CHF","DVT","Nephrotic syndrome","None"],"a":2,"e":"Answer- C. Nephrotic syndrome Decreased plasma osmotic pressure of capillaries : It causes decreases in inward drivingforce. It results from Hypoproteinemia. When total plasma protein is below 5 gm/dl (normal 6-8 gm/d1) or albumin is below 2.5 gm/dl (normal 3.5-5 gm/dl) edema takes place. Conditions causing hypoproteinemia are nephrotic syndrome, liver cirrhosis, protein losing enteropathy, and PEM.","pyqMatches":[{"year":"2016","no":373,"q":"Decrease in plasma osmotic pressure is cause of edema in?","o":["CHF","DVT","Nephrotic syndrome","None"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6566, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 407, '{"id":6566,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":407,"q":"False about Patterson-Kelly-Brown syndrome is?","o":["Anemia","Esophageal webs","Glossitis","Risk factor for adenocarcinoma"],"a":3,"e":"Answer- D. Risk factor for adenocarcinoma Plummer-Vinson syndrome (PVS) (Paterson-Brown-Kelly syndrome or sideropenic dysphagia), is characterized by difficulty in swallowing, iron deficiency anemia ,glossitis, chielosis, and esophageal webs.","pyqMatches":[{"year":"2016","no":474,"q":"False about Patterson-Kelly-Brown syndrome is?","o":["Anemia","Esophageal webs","Glossitis","Risk factor for adenocarcinoma"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6567, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 408, '{"id":6567,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":408,"q":"Normal time taken for scar formation after injury is?","o":["2 weeks","3 weeks","4 weeks","5 weeks"],"a":2,"e":"Answer- C. 4 weeks Immediately after incision : Incision is filled with blood clot containing fibin and blood cells (including ), dehydration of surface clot forms scab on surface. Within 24 hours : Neutrophils appear at the margin of wound, which is filled with blood clot. 24-48 hours : Epithelial cells move from wound edges and fuse in the midline beneath the surface scab, producing a continuous but thin epithelium layer that closes the wound. Day 3 : Neutrophils are replaced by macrophages, granulation tissue appears, collagen fibers are present in the margin but do not bridge the incision. Day 5 : Abundant granulation tissue, maximum neovascularization, abundant collagen which bridges the incision, the epidermis recovers its normal thickness. 2nd week : Diappearance of leukocytes and edema, presence of fibroblasts (derived from local mesenchyme) and maximum collagen. End of 1 month : There is scar which is made up of cellular connective tissue devoid of inflammatory infiltrate covered now by intact epidermis. There is replacement of collagen type III with collagen type I.","pyqMatches":[{"year":"2016","no":374,"q":"Normal time taken for scar formation after injury is?","o":["2 weeks","3 weeks","4 weeks","5 weeks"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6568, 'Pathology', 'Genetic Disorders', 'Easy', 'Pathology', 409, '{"id":6568,"subject":"Pathology","chapter":"Genetic Disorders","difficulty":"Easy","source":"Pathology","sourceNo":409,"q":"Vitamin deficiency associated with cystic fibrosis is","o":["K","B6","C","B12"],"a":3,"e":"Answer- D. B12 Patients with cystic fibrosis (CF) are at risk of developing deficiencies of fat-soluble vitamins (A, D, E, and K) because of pancreatic insufficiency, hepatobiliary disease, or both.","pyqMatches":[{"year":"2016","no":473,"q":"Vitamin deficiency associated with cystic fibrosis is","o":["K","B6","C","B12"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6569, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 410, '{"id":6569,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":410,"q":"Which type of healing occurs in an incisional wound with infection?","o":["Primary","Delayed primary","Secondary","Tertiary"],"a":2,"e":"Answer- C. Secondary Its produced by sharp cutting instruments- knife,razor,blade,swords,chopper,axe etc. Secondary healing occurs in an incisional wound with infection.","pyqMatches":[{"year":"2016","no":375,"q":"Which type of healing occurs in an incisional wound with infection?","o":["Primary","Delayed primary","Secondary","Tertiary"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6570, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 411, '{"id":6570,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":411,"q":"APC gene is involved in?","o":["Colorectal carcinoma","Gastric carcinoma","Gastric lymphoma","Esophageal adenocarcinoma"],"a":0,"e":"Answer- A. Colorectal carcinoma The APC protein is a negative regulator that controls beta- catenin concentrations and interacts with E-cadherin, which are involved in cell adhesion. Mutations in the APC gene may result in colorectal cancer","pyqMatches":[{"year":"2016","no":472,"q":"APC gene is involved in?","o":["Colorectal carcinoma","Gastric carcinoma","Gastric lymphoma","Esophageal adenocarcinoma"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6571, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 412, '{"id":6571,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":412,"q":"Gene for embryogenic stem cell is -","o":["Oct-4","Nanog","GJA I","All of the above"],"a":3,"e":"Answer- D. All of the above A common subset of 92 genes was identified that included Nanog, GTCM-1, connexin 43 (GJA1), oct-4, and TDGF1 (cripto).\"","pyqMatches":[{"year":"2016","no":377,"q":"Gene for embryogenic stem cell is","o":["Oct-4","Nanog","GJA I","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6572, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 413, '{"id":6572,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":413,"q":"Complement mediated hypersensitivity reaction is?","o":["Type -1 hypersensitivity","Type -2 hypersensitivity","Type -4 hypersensitivity","None"],"a":1,"e":"Answer- B. Type -2 hypersensitivity Type II reactions (Antibody mediated) → Involve immunoglobulin G or Immunoglobulin M bound to cell surface antigen, with subsequent complement fixation.","pyqMatches":[{"year":"2016","no":378,"q":"Complement mediated hypersensitivity reaction is?","o":["Type -1 hypersensitivity","Type -2 hypersensitivity","Type -4 hypersensitivity","None"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6573, 'Pathology', 'Hematology', 'Easy', 'Pathology', 414, '{"id":6573,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":414,"q":"T-cell mediated disease is?","o":["Asthma","Myasthenia gravis","SLE","Sarcoidosis"],"a":3,"e":"Answer- D. Sarcoidosis Type I (IgE mediated) Eczema Hay fever Asthma Atopy Urticaria Anaphylactic shock Acute dermatitis Theobald smith phenomenon Prausnitz Kusnter (PK) reaction Casonis test Schultz-Dale phenomenon Type II (IgG, IgM and complement mediated) Blood transfusion reactions Erythroblastosis fetalis Autoimmune hemolytic anemia or thrombocytopenia or agrnulocytosis4 Pemphigus vulgaris Good pasture syndrome Bullous pemphigoid Pernicious anemia Acute rheumatic fever Diabetes mellitus Graves disease Myasthenia gravis Type III (IgG, IgM, complement and leucocyte mediated) Local-Arthus reaction Systemic-serum sickness Schick test Polyarteritis nodosa (PAN) Rheumatoid arthritis SLE Acute viral hepatitis Penicillamine toxicity Hyperacute graft rejection","pyqMatches":[{"year":"2016","no":379,"q":"T-cell mediated disease is?","o":["Asthma","Myasthenia gravis","SLE","Sarcoidosis"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6574, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 415, '{"id":6574,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":415,"q":"Type 4 hypersensitivity reaction to TB antigen is similar to which of the following?","o":["Serum sickness","Asthma","Myasthenia gravis","Temporal arteritis"],"a":3,"e":"Answer- D. Temporal arteritis Type IV (T-Cell mediated) Tuberculin test Lepromin test Sarcoidosis Tuberculosis Contact dermatitis Granulomatous inflammation Type I lepra reaction Patch test Temporal arteritis Jones mote reaction (cutaneous basophilic HSN) Graft rejection Fairleys test Frie''s test","pyqMatches":[{"year":"2016","no":380,"q":"Type 4 hypersensitivity reaction to TB antigen is similar to which of the following?","o":["Serum sickness","Asthma","Myasthenia gravis","Temporal arteritis"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6575, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 416, '{"id":6575,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":416,"q":"Non IgE mediated anaphylactic reaction includes -","o":["Ig G","Ig M","Compliments","All of the above"],"a":3,"e":"Answer- D. All of the above Cytotoxic reactions can also cause anaphylaxis, via complement activation. Antibodies (IgG and IgM) against red blood cells, as occurs in a mismatched blood transfusion reaction, activate complement. This reaction causes agglutination and lysis of red blood cells and perturbation of mast cells resulting in anaphylaxis","pyqMatches":[{"year":"2016","no":381,"q":"Non IgE mediated anaphylactic reaction includes","o":["Ig G","Ig M","Compliments","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6576, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 417, '{"id":6576,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":417,"q":"Total colonic aganglionosis is a variant of?","o":["Crohn''s disease","Ulcerative colitis","Hirschsprung''s disease","Tropical sprue"],"a":2,"e":"Answer- C. Hirschsprung''s disease Hirschprung disease (Congenital aganglonic megacolon) is caused by defective migration of neural crest into the mesodermal layer of gut. There is aganglionosis (absence of ganglions) in a portion of intestinal tract. Intestinal segment lacks both Meissner submucosal and Auerbach myenteric plexuses.","pyqMatches":[{"year":"2016","no":471,"q":"Total colonic aganglionosis is a variant of?","o":["Crohn''s disease","Ulcerative colitis","Hirschsprung''s disease","Tropical sprue"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6577, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 418, '{"id":6577,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":418,"q":"MHC1 is involved in?","o":["Tumor lysis","Mixed leukocyte reaction","Autoimmune disease susceptibility","All of the above"],"a":0,"e":"Answer- A. Tumor lysis MHC class I molecules are present on all nucleated cells, all virus- infected cells can be detected and eliminated by CD8+Cytotoxic T lymphocytes. MHC class I is responsible for graft rejection and cell-mediated cytolysis of viral infected or tumor cells.","pyqMatches":[{"year":"2016","no":383,"q":"MHC1 is involved in?","o":["Tumor lysis","Mixed leukocyte reaction","Autoimmune disease susceptibility","All of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6578, 'Pathology', 'Hematology', 'Easy', 'Pathology', 419, '{"id":6578,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":419,"q":"Which disease is diagnosed by jejunal biopsy?","o":["Celiac disease","Intestinal lymphoma","Argentaffinoma of intestine","Tropical sprue"],"a":1,"e":"Answer- B. Intestinal lymphoma the jejunal biopsy is useful in the diagnosis of the following disorders: Intestinal lymphoma Intestinal lymphangiectasia Eosinophilic gastroenteritis Amyloidosis Crohn''s disease Infection by one or more microorganisms Mastocytosis Whipple''s disease","pyqMatches":[{"year":"2016","no":469,"q":"Which disease is diagnosed by jejunal biopsy?","o":["Celiac disease","Intestinal lymphoma","Argentaffinoma of intestine","Tropical sprue"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6579, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 420, '{"id":6579,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":420,"q":"CD4 is associated with HLA?","o":["HLA 1","HLA 2","HLA 3","All of the above"],"a":1,"e":"Answer- B. HLA 2 MHC-II recognizes exogenous antigen (extracellular microbes, soluble proteins) and present it to CD4 helper T cells (MHC-II restricted). MHC class I present antigen to cytotoxic CD-8 T cells (MHC-I restricted).","pyqMatches":[{"year":"2016","no":384,"q":"CD4 is associated with HLA?","o":["HLA 1","HLA 2","HLA 3","All of the above"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6580, 'Pathology', 'Infectious Diseases', 'Moderate', 'Pathology', 421, '{"id":6580,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Moderate","source":"Pathology","sourceNo":421,"q":"All are true about Toll like receptors except?","o":["Recognize microbial molecules","Activation of immune system","Regulation of calcium channel","Activation of transcription factors"],"a":2,"e":"Answer- C. Regulation of calcium channel Toll-like receptors (TLRs) are microbial sensors that are named for the founding member called Toll, which was discovered in Drosophila. There are ten mammalian TLRs, which recognize products of bacteria (such as endotoxin and bacterial DNA), viruses (such as double-stranded RNA), and other pathogens (Fig. 2–3, A). TLRs are located in plasma membranes and endosomes, so they can detect extracellular and ingested microbes. They are complemented by cytoplasmic and membrane molecules, from several other families, that also recognize microbial products. TLRs and the other receptors recognize products of different types of microbes and thus provide defense against essentially all classes of infectious pathogens. Recognition of microbes by these receptors activates transcription factors that stimulate the production of several secreted and membrane proteins. These proteins include mediators of inflammation, antiviral cytokines (interferons), and proteins that promote lymphocyte activation and even more potent immune responses.","pyqMatches":[{"year":"2016","no":387,"q":"All are true about Toll like receptors except?","o":["Recognize microbial molecules","Activation of immune system","Regulation of calcium channel","Activation of transcription factors"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6581, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 422, '{"id":6581,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":422,"q":"Blood group most commonly associated with gastric carcinoma is?","o":["Blood Group 0","Blood group A","Blood group AB","Blood group B"],"a":1,"e":"Answer- B. Blood group A Genetic factors : Blood group A, Hereditary nonpolyposis colon cancer syndrome (HNPCC) and Familial gastric cancer syndrome (E-cadherin mutation).","pyqMatches":[{"year":"2016","no":468,"q":"Blood group most commonly associated with gastric carcinoma is?","o":["Blood Group 0","Blood group A","Blood group AB","Blood group B"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6582, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 423, '{"id":6582,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":423,"q":"The most common organ to be involved in the acute phase of Graft vs host disease is?","o":["Bone marrow","Skin","Liver","Gut"],"a":1,"e":"Answer- B. Skin Acute Graft vs host disease (occurring days to weeks after transplantation) causes epithelial cell necrosis in three principal target organs: liver, skin, and gut. Destruction of small bile ducts gives rise to jaundice, and mucosal ulceration of the gut results in bloody diarrhea. Cutaneous involvement is manifested by a generalized(maculopapular) rash. Histological findings are-","pyqMatches":[{"year":"2016","no":389,"q":"The most common organ to be involved in the acute phase of Graft vs host disease is?","o":["Bone marrow","Skin","Liver","Gut"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6583, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 424, '{"id":6583,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":424,"q":"Autoimmune gastritis is associated with deficiency of vitamin?","o":["A","B12","C","D"],"a":1,"e":"Answer- B. B12 In autoimmune gastritis, two important auto antibodies causing damage are anti-parietal cell antibodies (most common) and antibodies against intrinsic factor; anti-IF (most specific). Vitamin B-12 deficiency and pernicious anemia : Due to deficiency of IF cells (secreted by parietal cells) as well as damage of IF by anti-IF antibodies.","pyqMatches":[{"year":"2016","no":467,"q":"Autoimmune gastritis is associated with deficiency of vitamin?","o":["A","B12","C","D"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6584, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 425, '{"id":6584,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":425,"q":"Normal value of CD4:CD8 ratio is -","o":["0.5","1","1.5","2"],"a":3,"e":"Answer- D. 2 A normal CD4/CD8 ratio is 2.0, with CD4 lymphocytes equal to or greater than 400/mm3 and CD8 lymphocytes equal to 200 to 800/mm3.","pyqMatches":[{"year":"2016","no":390,"q":"Normal value of CD4:CD8 ratio is","o":["0.5","1","1.5","2"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6585, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 426, '{"id":6585,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":426,"q":"Normally squamo-columnar junction is usually located at","o":["Distal 2-3 cms of esophagus","Proximal 2-3 cms of stomach","In esophagus more than 3cms proximal to GEJ","None of the above"],"a":1,"e":"Answer- A. Distal 2-3 cms of esophagus Proximal extension of the squamocolumnar junction beyond the distal 2-3 cms of oesphagus is abnormal and is suggestive of Barrett''s esophagus.","pyqMatches":[{"year":"2016","no":465,"q":"Normally squamo-columnar junction is usually located at","o":["Distal 2-3 cms of esophagus","Proximal 2-3 cms of stomach","In esophagus more than 3cms proximal to GEJ","None of the above"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6586, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 427, '{"id":6586,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":427,"q":"Carcinoma associated most commonly with upper one third of esophagus is","o":["Adenocarcinoma","Squamous cell Carcinoma","Adeno-squamous Carcinoma","Leiomyosarcoma"],"a":1,"e":"Answer- B. Squamous cell Carcinoma Squamous cell carcinoma is the most common type of esophageal carcinoma worldwide and in India. It usually occurs in middle 1/3rd (mot common) and upper 1/3'' of esophagus. Some may also arise in lower 1/3","pyqMatches":[{"year":"2016","no":466,"q":"Carcinoma associated most commonly with upper one third of esophagus is","o":["Adenocarcinoma","Squamous cell Carcinoma","Adeno-squamous Carcinoma","Leiomyosarcoma"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6587, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 428, '{"id":6587,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":428,"q":"Anti Jo-1 antibodies are a feature associated with?","o":["SLE","Systemic sclerosis","Polymyositis","Rheumatoid arthritis"],"a":2,"e":"Answer- C. Polymyositis Anti-Jo-1 antibody is a myositis specific autoantibody most commonly found in patients with idiopathic inflammatory myopathies (UM).","pyqMatches":[{"year":"2016","no":392,"q":"Anti Jo-1 antibodies are a feature associated with?","o":["SLE","Systemic sclerosis","Polymyositis","Rheumatoid arthritis"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6588, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 429, '{"id":6588,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":429,"q":"HLA marker associated with diabetes mellitus type 1 is -","o":["B 7","DR 4","DQ 3","DQ 4"],"a":1,"e":"Answer- B. DR 4 HLA associated with DM1 are DR3, DR4, DR8, DQ8.","pyqMatches":[{"year":"2016","no":393,"q":"HLA marker associated with diabetes mellitus type 1 is","o":["B 7","DR 4","DQ 3","DQ 4"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6589, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 430, '{"id":6589,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":430,"q":"The zonal necrosis most commonly affected in chronic passive hepatic congestion is?","o":["Central","Peripheral","Mid zonal","None"],"a":0,"e":"Answer- A. Central Centrilobular hemorrhagic necrosis is caused by chronic passive congestion (CPC) due to right heart failure.","pyqMatches":[{"year":"2016","no":464,"q":"The zonal necrosis most commonly affected in chronic passive hepatic congestion is?","o":["Central","Peripheral","Mid zonal","None"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6590, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 431, '{"id":6590,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":431,"q":"What is responsible for regeneration of liver cells?","o":["HGF","VEGF","TGF-13","IFN-y"],"a":0,"e":"Answer- A. HGF Hepatocyte growth factor (HGF/scatter factor) levels rise to high levels soon after partial hepatectomy. This is the only factor tested that acts by itself as a potent mitogen for isolated hepatocytes cultured in vitro. This factor is also of critical importance in development of the liver, as target deletions of its gene lead to fetal death due to hepatic insufficiency.","pyqMatches":[{"year":"2016","no":462,"q":"What is responsible for regeneration of liver cells?","o":["HGF","VEGF","TGF-13","IFN-y"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6591, 'Pathology', 'Genetic Disorders', 'Easy', 'Pathology', 432, '{"id":6591,"subject":"Pathology","chapter":"Genetic Disorders","difficulty":"Easy","source":"Pathology","sourceNo":432,"q":"Expression of a gene is known as?","o":["Genotype","Phenotype","Genome","Morphology"],"a":1,"e":"Answer- B. Phenotype The genotype (The genetic makeup of an individual) of an organism is the inherited map it carries within its genetic code. The genotype is the part (DNA sequence) of the genetic makeup of a cell. Genotype is one of three factors that determine phenotype, the other two being inherited epigenetic factors, and non-inherited environmental factors.","pyqMatches":[{"year":"2016","no":394,"q":"Expression of a gene is known as?","o":["Genotype","Phenotype","Genome","Morphology"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6592, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 433, '{"id":6592,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":433,"q":"Group-D chromosome is?","o":["Chromosome 3","Chromosome 6","Chromosome 12","Chromosome 15"],"a":3,"e":"Answer- D. Chromosome 15 13-15- Six chromosomes slightly smaller than the C group with the kinetochores in a near terminal position.","pyqMatches":[{"year":"2016","no":395,"q":"Group-D chromosome is?","o":["Chromosome 3","Chromosome 6","Chromosome 12","Chromosome 15"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6593, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 434, '{"id":6593,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":434,"q":"Acute intermittent porphyria is associated with which type of inheritance?","o":["Autosomal dominant","Autosomal recessive","X-linked dominant","X-linked recessive"],"a":0,"e":"Answer- A. Autosomal dominant Metabolic Familial hypercho-lesterolemia Acute intermittent porphyria","pyqMatches":[{"year":"2016","no":396,"q":"Acute intermittent porphyria is associated with which type of inheritance?","o":["Autosomal dominant","Autosomal recessive","X-linked dominant","X-linked recessive"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6594, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 435, '{"id":6594,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":435,"q":"Strawberry gall bladder is seen in","o":["Cholesterosis","Primary sclerosing cholangitis","Cholestasis","Primary billiary cirrhosis"],"a":0,"e":"Answer- A. Cholesterosis In Cholesterosis, there are deposits of cholesterol in the epithelial cells and in the submucosal macrophages. This gives appearance of multiple small yellow spots on a red hyperplastic muscosa, the straberry gallbladder.","pyqMatches":[{"year":"2016","no":461,"q":"Strawberry gall bladder is seen in","o":["Cholesterosis","Primary sclerosing cholangitis","Cholestasis","Primary billiary cirrhosis"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6595, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 436, '{"id":6595,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":436,"q":"Inheritance associated with congenital adrenal hyperplasia -","o":["AR","AD","XR","XD"],"a":0,"e":"Answer- A. AR Endocrine- Congenital adrenal hyperplasia Albinism","pyqMatches":[{"year":"2016","no":397,"q":"Inheritance associated with congenital adrenal hyperplasia","o":["AR","AD","XR","XD"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6596, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 437, '{"id":6596,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":437,"q":"True about RCC is?","o":["Most common site is lower lobe of kidney","Most common variety is papillary type","Invasion of renal vein is more common than renal artery","Most common site of metastasis is lymph nodes"],"a":2,"e":"Answer- C. Invasion of renal vein is more common than renal artery Renal cell carcinoma is the most common malignant tumor of kidney. It occurs usually in 6th and 7th decade of life. There is male preponderance. Important risk factors for RCC are smoking (most significant), obesity, hypertension, asbestos exposure, estrogen therapy, CRF, tuberous sclerosis and familial conditions (Von Hippel-Lindau syndrome). RCC is an adenocarcinoma and most commonly arises from upper pole. The one of the striking characteristics of RCC is to invade renal vein and is associated with poor prognosis.","pyqMatches":[{"year":"2016","no":460,"q":"True about RCC is?","o":["Most common site is lower lobe of kidney","Most common variety is papillary type","Invasion of renal vein is more common than renal artery","Most common site of metastasis is lymph nodes"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6597, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 438, '{"id":6597,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":438,"q":"Chronic bronchitis is associated with?","o":["Increase in number of glands without any change in size","Bronchiolitis obliterans","Decrease in Reid index","Only large airways are involved"],"a":1,"e":"Answer- B. Bronchiolitis obliterans The earliest feature of chronic bronchitis is hypersecretion of mucus in the larger airways, associated with hypertrophy of submucosal gland of trachea and bronchi. Later, small airways (small bronchi and bronchioles) are also involved and show goblet cell hyperplasia, and intraluminal and peribronchial fibrosis. In most severe cases, there may be oblitration of lumen due to fibrosis → Bronchiolitis obliterans.","pyqMatches":[{"year":"2016","no":458,"q":"Chronic bronchitis is associated with?","o":["Increase in number of glands without any change in size","Bronchiolitis obliterans","Decrease in Reid index","Only large airways are involved"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6598, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 439, '{"id":6598,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":439,"q":"On polarising microscopy, refractile body in the centre of granuloma is seen in?","o":["Sarcoidosis","Silicosis","Tuberculosis","Asbestosis"],"a":1,"e":"Answer- B. Silicosis Histologically the lesions of silicosis consist of concentric layers of hyalinized collagen surrounded by a dense capsule of more condensed collagen. Examination of the nodules by polarized microscopy reveals the birefringent silica particles.","pyqMatches":[{"year":"2016","no":456,"q":"On polarising microscopy, refractile body in the centre of granuloma is seen in?","o":["Sarcoidosis","Silicosis","Tuberculosis","Asbestosis"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6599, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 440, '{"id":6599,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":440,"q":"Most common type of pneumoconiosis, associated with TB is?","o":["Silicosis","Bysinosis","Asbestosis","Baggassosis"],"a":0,"e":"Answer- A. Silicosis Silicosis is associated with increased susceptibility to T.B. It is postulated that silicosis results in a depression of cell-mediated immunity, and crystalline silica may inhibit the ability of pulmonary macrophages to kill phagocytosed mycobacteria. Nodules of silicotuberculosis often contain a central zone of caseation.","pyqMatches":[{"year":"2016","no":455,"q":"Most common type of pneumoconiosis, associated with TB is?","o":["Silicosis","Bysinosis","Asbestosis","Baggassosis"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6600, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 441, '{"id":6600,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":441,"q":"Most common cause of chylothorax is?","o":["Trauma","Lymphoma","Left-sided heart failure","Infections"],"a":1,"e":"Answer- B. Lymphoma Chylothorax is a pleural collection of a milky lymphatic fluid containing micro globules of lipid. It results from lymph formed in the digestive system called chyle accumulating in the pleural cavity due to either disruption or obstruction of the thoracic duct. The total volume of fluid may not be large, but chylothorax is always significant because it implies obstruction of the major lymph ducts, usually by intrathoracic cancer like primary or secondary mediastinal neoplasm, such as lymphoma.","pyqMatches":[{"year":"2012","no":1148,"q":"Most common cause of chylothorax is?","o":["Trauma","Lymphoma","Left-sided heart failure","Infections"],"a":1,"source":"NEET_2012_Paper.pdf"},{"year":"2016","no":453,"q":"Most common cause of chylothorax is?","o":["Trauma","Lymphoma","Left-sided heart failure","Infections"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2012","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6601, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 442, '{"id":6601,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":442,"q":"Inheritance associated with fragile X- syndrome is-","o":["Autosomal dominant","Autosomal recessive","X-linked dominant","X-linked recessive"],"a":2,"e":"Answer- C. X-linked dominant ''None > c'' i.e., X-linked dominant The unstable triplet is transmitted in an X-linked inheritance but the probabilities of different phenotypes are far from traditional X-linked inheritance.","pyqMatches":[{"year":"2016","no":398,"q":"Inheritance associated with fragile X- syndrome is","o":["Autosomal dominant","Autosomal recessive","X-linked dominant","X-linked recessive"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6602, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 443, '{"id":6602,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":443,"q":"Which type of paraneoplastic syndrome is most commonly associated with lung carcinoma?","o":["SIADH","Gynaecomastia","Acanthosis nigricans","Hypocalcaemia"],"a":0,"e":"Answer- A. SIADH SIADH is the most common paraneoplastic syndrome associated with lung carcinoma as Small cell carcinoma is the most common type of lung cancer associated with ectopic hormone production and paraneoplastic syndrome and ADH (Causing SIADH), ACTH (Causing cushingsyndrome) production are predominantly associated small cell carcinoma.","pyqMatches":[{"year":"2016","no":452,"q":"Which type of paraneoplastic syndrome is most commonly associated with lung carcinoma?","o":["SIADH","Gynaecomastia","Acanthosis nigricans","Hypocalcaemia"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6603, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 444, '{"id":6603,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":444,"q":"Metastasis to lungs come most commonly from","o":["Breast carcinoma","Brain carcinoma","Bone carcinoma","Melanoma"],"a":0,"e":"Answer- A. Breast carcinoma Metastatic tumor to lung originate from carcinoma in the breast, colon, stomach, pancreas, kidney, prostate, liver, thyroid, adrenal, male genital tract and female genital tract.","pyqMatches":[{"year":"2016","no":451,"q":"Metastasis to lungs come most commonly from","o":["Breast carcinoma","Brain carcinoma","Bone carcinoma","Melanoma"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6604, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 445, '{"id":6604,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":445,"q":"Deficiency of p53 mutation is maximum in which lung carcinoma?","o":["Small cell carcinoma","Squamous cell carcinoma","Adenocarcinoma","Lymphoma"],"a":1,"e":"Answer- B. Squamous cell carcinoma -MYC and RB - small cell cancer RAS and p16 - non-small cell cancer p53 - both small and non-small cell, but highest in squamous cell carcinoma K-RAS –adenocarcinoma","pyqMatches":[{"year":"2016","no":450,"q":"Deficiency of p53 mutation is maximum in which lung carcinoma?","o":["Small cell carcinoma","Squamous cell carcinoma","Adenocarcinoma","Lymphoma"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6605, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 446, '{"id":6605,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":446,"q":"In allergic bronchopulmonary aspergillosis, the location of lesions is","o":["Pleura","Bronchi and bronchioles","Alveoli","All of the above"],"a":1,"e":"Answer- B. Bronchi and bronchioles Allergic bronchopulmonary aspergillosis (ABPA) is a condition characterized by a hypersensitivity response to the Aspergillus (most commonly Aspergillus fumigatus). An allergic bronchopulmonary aspergillosis is a form of lung disease that occurs in some people who are allergic to Aspergillus. With ABPA, this allergic reaction causes the immune system to overreact to Aspergillus leading to lung inflammation. ABPA causes bronchospasm (tightening of airway muscles) and mucus buildup resulting in coughing, breathing difficulty and airway obstruction. it also causes airway inflammation, leading to bronchiectasis—a condition marked by abnormal dilation of the bronchi and bronchioles.","pyqMatches":[{"year":"2016","no":449,"q":"In allergic bronchopulmonary aspergillosis, the location of lesions is","o":["Pleura","Bronchi and bronchioles","Alveoli","All of the above"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6606, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 447, '{"id":6606,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":447,"q":"HOX gene is associated with","o":["Cranio-caudal development","Brain development","Teeth formation","All of the above"],"a":0,"e":"Answer- A. Cranio-caudal development HOX genes (a subset of homeotic genes) are a group of related genes that control the body plan of an embryo along the cranio¬caudal (head-tail) axis.","pyqMatches":[{"year":"2016","no":399,"q":"HOX gene is associated with","o":["Cranio-caudal development","Brain development","Teeth formation","All of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6607, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 448, '{"id":6607,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":448,"q":"Most common cancer found in coal mine workers","o":["Anal canal","Testicular","Lung","Liver"],"a":2,"e":"Answer- C. Lung Among coal worker pneumoconiosis patients standard incidence ratio of various important carcinomas : ovary (2.0) > esophagus (1.76) Lung > (1.45) > Stomach (1.42) > Liver (1.18) > kidney (1.06) > prostate (1.02) > colorectal (1.00) > urinary bladder (0.91) > head & neck (0.87)","pyqMatches":[{"year":"2016","no":448,"q":"Most common cancer found in coal mine workers","o":["Anal canal","Testicular","Lung","Liver"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6608, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 449, '{"id":6608,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":449,"q":"Chromosome for ABO gene is?","o":["9q","10p","11 q","12p"],"a":0,"e":"Answer- A. 9q The ABO gene (Histo-blood group ABO system transferase enzyme) resides on chromosome 9 at the band 9q34.2. Histo-blood group ABO system transferase is an enzyme with glycosyltransferase activity, which is encoded by the ABO gene in humans. It is ubiquitously expressed in many tissues and cell types.","pyqMatches":[{"year":"2016","no":400,"q":"Chromosome for ABO gene is?","o":["9q","10p","11 q","12p"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6609, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 450, '{"id":6609,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":450,"q":"Pink puffers are associated with?","o":["Emphysema","Chronic bronchitis","Pneumonia","Bronchiectasis"],"a":0,"e":"Answer- A. Emphysema A \"pink puffer\" is a person where emphysema is the primary underlying pathology In emphysema, not only there is less surface area for gas exchange, there is also less vascular bed for gas exchange. . The body then has to compensate by hyperventilation (the \"puffer\"). Have less hypoxemia (compared to blue bloaters) and appear to have a \"pink\" complexion and hence \"pink puffer\".","pyqMatches":[{"year":"2016","no":447,"q":"Pink puffers are associated with?","o":["Emphysema","Chronic bronchitis","Pneumonia","Bronchiectasis"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6610, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 451, '{"id":6610,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":451,"q":"Granulomatous lung disease is caused by?","o":["Hypersensitivity pneumonitis","Sarcoma","Bronchogenic carcinoma","Bronchogenic cyst"],"a":0,"e":"Answer- A. Hypersensitivity pneumonitis Granulomatous lung disease refers to a broad group of infectious and well as noninfectious conditions characterized by the formation of granulomas. Infectious : Mycobacterial (TB & Non-TB); Fungal infection (cryptococcus, Histoplasma, Blastomycosis, Coccidioidomycosis, Aspergillosis); Parasitic Infections. Non-infectious: Sarcoidosis; Wegner granulomatosis; Churg Strauss syndrome; Chronic granulomatous disease; Hypersensitivity pneumonitis; RA; Chronic Aspiration Pneumonitis; Langerhans Cell Histiocytosis; substances (Talc Granulomatosis, Berylliosis)","pyqMatches":[{"year":"2016","no":445,"q":"Granulomatous lung disease is caused by?","o":["Hypersensitivity pneumonitis","Sarcoma","Bronchogenic carcinoma","Bronchogenic cyst"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6611, 'Pathology', 'Hematology', 'Easy', 'Pathology', 452, '{"id":6611,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":452,"q":"TEL-AML 1 fusion is associated with?","o":["CLL","CML","ALL","AML"],"a":2,"e":"Answer- C. ALL TEL-AML 1 gene fusion is the most common genetic alteration in childhood acute lymphoblastic leukemia. It is created by balanced translocation t (12 : 21). Cytogenetic abnormalities associated with ALL are gain of function mutation in NOTCH-1 gene in T-cell ALL.","pyqMatches":[{"year":"2016","no":444,"q":"TEL-AML 1 fusion is associated with?","o":["CLL","CML","ALL","AML"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6612, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 453, '{"id":6612,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":453,"q":"Cag A gene is associated with","o":["Hepatocellular carcinoma","Esophageal carcinoma","MALT lymphoma","Lung carcinoma"],"a":2,"e":"Answer- C. MALT lymphoma CagA, A gene that codes for an immunodominant antigen, is present only in Helicobacter pylori strains that are associated with severe forms of the gastroduodenal disease (type I strains). Helicobacter pylori is a microaerophilic spiral-shaped lophotrichous Gram-negative bacterium that colonizes the gastric lumen of primates, including humans. H pylori was identified as the cause of chronic active gastritis and peptic ulcer disease in humans and is considered to be a risk factor for the development of gastric adenocarcinoma and MALT lymphoma","pyqMatches":[{"year":"2016","no":441,"q":"Cag A gene is associated with","o":["Hepatocellular carcinoma","Esophageal carcinoma","MALT lymphoma","Lung carcinoma"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6613, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 454, '{"id":6613,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":454,"q":"Dutcher bodies are seen in?","o":["Brain","Liver","Spleen","Bone marrow"],"a":3,"e":"Answer- D. Bone marrow Dutcher bodies, which are attributed to immunoglobulin filled cytoplasm invaginating into the nucleus creating the appearance of an intranuclear inclusion. Dutcher bodies are described as intranuclear inclusions in patients with Waldenstrom’s macroglobulinemia. The inclusions are positive on a periodic acid-Schiff reaction and were present in the cytoplasm as well as the nucleus. They identified the inclusions as glycoprotein and postulated that they might be chemically identical to the macroglobulin in the plasma.","pyqMatches":[{"year":"2016","no":437,"q":"Dutcher bodies are seen in?","o":["Brain","Liver","Spleen","Bone marrow"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6614, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 455, '{"id":6614,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":455,"q":"Trinucleotide sequence associated with spino-cerebellar ataxia is?","o":["CTG","CUG","GGG","CAG"],"a":3,"e":"Answer- D. CAG Huntington''s disease (CAG repeat), Spinocerebellar ataxia (CAG repeat), Friedreich ataxia (GAA repeat), Fragile-X-syndrome (GGG or GCC repeat), Dystrophia myotonica (CTG/CUG repeat)","pyqMatches":[{"year":"2016","no":402,"q":"Trinucleotide sequence associated with spino-cerebellar ataxia is?","o":["CTG","CUG","GGG","CAG"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6615, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 456, '{"id":6615,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":456,"q":"CA-125 is?","o":["Mucin glycoprotein","Carcinoma transmigration antigen","Mucopolysaccharide","Lipid"],"a":0,"e":"Answer- A. Mucin glycoprotein * CA-125, which stands for “Cancer Antigen 125” also known as mucin 16 or MUC16 is a protein that in humans is encoded by the MUC16 which is a member of the mucin family glycoproteins. * It is found in high amounts in the blood of patients with ovarian cancer. * CA-125 is produced on the surface of cells and is released in the bloodstream. * It is among the blood tests that may be ordered by a doctor if ovarian cancer is suspected. * CA-125 is also elevated in cancers of endometrium, cervix, fallopian tubes, pancreas, breast, lung and colon. * Non-neoplastic conditions causing elevation of CA-125 are pregnancy, menstruation, endometriosis, PID, abdominal TB, peritonitis and uterine fibroid. * reference range: CA 125 is 0-35 units/mL (0-35 kU/L).","pyqMatches":[{"year":"2016","no":403,"q":"CA-125 is?","o":["Mucin glycoprotein","Carcinoma transmigration antigen","Mucopolysaccharide","Lipid"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6616, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 457, '{"id":6616,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":457,"q":"Li-fraumani syndrome occurs due to mutation in gene?","o":["p53","p16","p41","p12"],"a":0,"e":"Answer- A. p53 Li-Fraumeni syndrome is due to germ line mutation in p-53 gene.","pyqMatches":[{"year":"2016","no":405,"q":"Li-fraumani syndrome occurs due to mutation in gene?","o":["p53","p16","p41","p12"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6617, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 458, '{"id":6617,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":458,"q":"Most common tumor suppressor gene involved in cancer genesis is?","o":["Rb","p53","p16","p73"],"a":1,"e":"Answer- B. p53 p-53 is the most common target for genetic alteration in human tumors; A little over 50% of human tumors contain mutation in this gene.","pyqMatches":[{"year":"2016","no":407,"q":"Most common tumor suppressor gene involved in cancer genesis is?","o":["Rb","p53","p16","p73"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6618, 'Pathology', 'Hematology', 'Easy', 'Pathology', 459, '{"id":6618,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":459,"q":"Left side shift in Arneth''s count is seen in?","o":["Megaloblastic anemia","Septicemia","TB","Liver disease"],"a":2,"e":"Answer- C. TB Shift to left (hyperactive bone marrow) Individuals who have a larger percentage of neutrophills with fewer lobes (mainly NI & N2) have a left shift which can be indicative of disease processes such as infections (pyogenic and TB), malignant tumors, hemolytic crises, myocardial infarction, acidosis, irradiation etc.","pyqMatches":[{"year":"2016","no":435,"q":"Left side shift in Arneth''s count is seen in?","o":["Megaloblastic anemia","Septicemia","TB","Liver disease"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6619, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 460, '{"id":6619,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":460,"q":"All are pre-malignant conditions except -","o":["Anaplasia","Metaplasia","Hamartoma","Dysplasia"],"a":2,"e":"A precancerous condition is a condition or lesion involving abnormal cells that are associated with an increased risk of developing into cancer. Clinically, precancerous conditions encompass a variety of conditions or lesions with an increased risk of developing into cancer. Dysplasia is a broad term that refers to the abnormal development of cells within tissues or organs. It can lead to a wide range of conditions that involve enlarged tissue or pre-cancerous cells. Anaplasia is a condition of cells with poor cellular differentiation, losing the morphological characteristics of mature cells and their orientation concerning each other and to endothelial cells. The term also refers to a group of morphological changes in a cell (nuclear pleomorphism, altered nuclear-cytoplasmic ratio, presence of nucleoli, high proliferation index) that point to a possible malignant transformation. Such loss of structural differentiation is especially seen in most, but not all, malignant neoplasms. A hamartoma is a benign (noncancerous) tumorlike malformation made up of an abnormal mixture of cells and tissues found in areas of the body where growth occurs. It is considered a developmental error and can occur at several sites. considering the above terms hamartoma is not a precancerous condition","pyqMatches":[{"year":"2016","no":408,"q":"All are pre-malignant conditions except","o":["Anaplasia","Metaplasia","Hamartoma","Dysplasia"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6620, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 461, '{"id":6620,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":461,"q":"Maximum life of transfused RBCs is","o":["110-120 days","80-100 days","60-80 days","50-60 days"],"a":1,"e":"Answer- B. 80-100 days Normal average life span of red blood cells in adults is about 120 days, whereas that of transfused RBCs is about 50-60 days\" After an RBC transfusion, the mean potential life span of RBC is 85 days with a mean half life of 43 ± 11 days.","pyqMatches":[{"year":"2016","no":432,"q":"Maximum life of transfused RBCs is","o":["110-120 days","80-100 days","60-80 days","50-60 days"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6621, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 462, '{"id":6621,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":462,"q":"Soft wood exposure leads to -","o":["Nasal adenocarcinoma","Skin cancer","Liver cancer","Bladder cancer"],"a":0,"e":"Answer- A. Nasal adenocarcinoma \"There is little doubt that exposure to hard wood dusts (especially that of beech 6, oak) in the furniture industry, as well as some domestic softwood outside the industry, is associated with sino- nasal cancers. Among the neoplasias, nasal adenocarcinoma is the cancer most commonly found in wood workers.\"","pyqMatches":[{"year":"2016","no":409,"q":"Soft wood exposure leads to","o":["Nasal adenocarcinoma","Skin cancer","Liver cancer","Bladder cancer"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6622, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 463, '{"id":6622,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":463,"q":"Which test is used for both intrinsic and common clotting pathways?","o":["Thrombin time","Partial thromboplastin time","Ristocetin agglutination test","FDPs"],"a":1,"e":"Answer- B. Partial thromboplastin time 1) Partial thromboplastin time (PTT) : It tests the intrinsic and common coagulation pathways. So, a prolonged PTT can results from deficiency of factor V, VIII (factor VIIIc, Von willebrand factor), IX, X, XI, XII, prothrombin or fibrinogen.","pyqMatches":[{"year":"2016","no":431,"q":"Which test is used for both intrinsic and common clotting pathways?","o":["Thrombin time","Partial thromboplastin time","Ristocetin agglutination test","FDPs"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6623, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 464, '{"id":6623,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":464,"q":"At which cell cycle checkpoint is the cell cycle halted if the cell''s DNA is damaged?","o":["G I - S","S - G2","G2 - M","GO - GI"],"a":0,"e":":C Answer- (A) G I - S (C) G2 - M The S phase is the point of no return in the cell cycle, and before the cell makes the final commitment to replicate, the G ,/S checkpoint checks for DNA damage. If DNA damage is present, the DNA repair machinery and mechanisms that arrest the cell cycle are put in motion. This causes delay at G iS checkpoint. This check point in used for the repair of the DNA which is damaged after its replication","pyqMatches":[{"year":"2016","no":410,"q":"At which cell cycle checkpoint is the cell cycle halted if the cell''s DNA is damaged?","o":["G I - S","S - G2","G2 - M","GO - GI"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6624, 'Pathology', 'Hematology', 'Easy', 'Pathology', 465, '{"id":6624,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":465,"q":"Which of the following is a pro- coagulant?","o":["Thrombomodulin","Protein C","Protein S","Thrombin"],"a":3,"e":"Answer- D. Thrombin Various factors involved in coagulation cascodes are factor I (fibrinogen); factor II (prothrombin); factor III (thromboplastin or tissue factor); factor IV (calcium ions or Ca\"); factor V (labile factor); factor VI (accclerin); factor VII (stable factor or preaccelerin); factor VIII (antihemophilic factor); factor IX (christmas factor); factor X (stuart-prower factor); factor XI (plasma thromboplastin antecedent or PTA); factor XII (Hageman factor); factor XIII (fibrin stabilizing factor or Laki Lorand factor); HMWK (high molecular weight kinogen); prekallikrein; kallikrein; and platelet phospholipids.","pyqMatches":[{"year":"2016","no":430,"q":"Which of the following is a pro- coagulant?","o":["Thrombomodulin","Protein C","Protein S","Thrombin"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6625, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 466, '{"id":6625,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":466,"q":"Immunohistochemical marker for sentinel node biopsy for breast carcinoma is?","o":["Cytokeratin","Vimentin","Calretinin","CD45"],"a":0,"e":"Answer- A. Cytokeratin Cytokeratin - Carcinoma","pyqMatches":[{"year":"2016","no":413,"q":"Immunohistochemical marker for sentinel node biopsy for breast carcinoma is?","o":["Cytokeratin","Vimentin","Calretinin","CD45"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6626, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 467, '{"id":6626,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":467,"q":"Scavenger receptors are for?","o":["Oxidized LDL","Reduced LDL","HDL","VLDL"],"a":0,"e":"Answer- A. Oxidized LDL Oxidized LDL has following effects","pyqMatches":[{"year":"2016","no":414,"q":"Scavenger receptors are for?","o":["Oxidized LDL","Reduced LDL","HDL","VLDL"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6627, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 468, '{"id":6627,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":468,"q":"Characteristic histopathological feature of rheumatic heart failure is -","o":["Aschoff''s nodule","Mc Callumn patch","Bread & butter pericarditis","Shaggy vegetation"],"a":0,"e":"Answer- A. Aschoff''s nodule Microscopically, Aschoff bodies are areas of inflammation of the connective tissue of the heart, or focal interstitial inflammation. Fully developed Aschoff bodies are granulomatous structures consisting of fibrinoid change, lymphocytic infiltration, occasional plasma cells, and characteristically abnormal macrophages surrounding necrotic centers. Some of these macrophages may fuse to form multinucleated giant cells. Others may become Anitschkow cells or \"caterpillar cells,\" so named because of the appearance of their chromatin. Myocardium involvement results in myocarditis with Aschoff bodies. Endocardium involvement leads to the formation of small warty projections (verrucae) along the line of closure of valvular leaflets, mostly on the mitral valve. They are pathognomic foci of fibrinoid necrosis found in many sites, most often the myocardium. Initially, they are surrounded by lymphocytes, macrophages, and a few plasma cells, but they are slowly replaced by a fibrous scar. Aschoff bodies are found in all the three layers of the heart, the least chance in the pericardium.","pyqMatches":[{"year":"2016","no":416,"q":"Characteristic histopathological feature of rheumatic heart failure is","o":["Aschoff''s nodule","Mc Callumn patch","Bread & butter pericarditis","Shaggy vegetation"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6628, 'Pathology', 'Hematology', 'Moderate', 'Pathology', 469, '{"id":6628,"subject":"Pathology","chapter":"Hematology","difficulty":"Moderate","source":"Pathology","sourceNo":469,"q":"Not a feature of G-6PD deficiency?","o":["Intravascular hemolysis","Oxidative stress","Membrane defect","Bite cells"],"a":2,"e":"Answer- C. Membrane defect * Among the defects in hexose monophosphate shunt, the most common is G6PD deficiency. * G6PD gene is located on the X chromosome and its deficiency is, therefore, a sex (X)-linked trait affecting males, while the females are carriers and are asymptomatic. * PATHOGENESIS: Normally, red blood cells are well protected against oxidant stress because of an adequate generation of reduced glutathione via the hexose monophosphate shunt. * Individuals with inherited deficiency of G6PD, an enzyme required for hexose monophosphate shunt for glucose metabolism, fail to develop adequate levels of reduced glutathione in their red cells. * The clinical manifestations are those of acute hemolytic anemia within hours of exposure to oxidant stress. * The hemolysis is, however, self-limiting even if the exposure to the oxidant is continued since it affects the older red cells only.","pyqMatches":[{"year":"2016","no":426,"q":"Not a feature of G-6PD deficiency?","o":["Intravascular hemolysis","Oxidative stress","Membrane defect","Bite cells"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6629, 'Pathology', 'Hematology', 'Easy', 'Pathology', 470, '{"id":6629,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":470,"q":"Prosthetic valves are predisposed to -","o":["Thromboembolism","Infection","Hemolysis","All of the above"],"a":3,"e":"Answer- D. All of the above Thrombo- embolic events Bleeding Prosthetic heart valve obstruction or stenosis Prosthetic heart valve regurgitation (valvular and paravalvular) Infective endocarditis Hemolytic anemia Patient-prosthesis mismatch.","pyqMatches":[{"year":"2016","no":417,"q":"Prosthetic valves are predisposed to","o":["Thromboembolism","Infection","Hemolysis","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6630, 'Pathology', 'Hemodynamics', 'Moderate', 'Pathology', 471, '{"id":6630,"subject":"Pathology","chapter":"Hemodynamics","difficulty":"Moderate","source":"Pathology","sourceNo":471,"q":"Most frequent time period between myocardial infarction and subsequent myocardial rupture is -","o":["3-4 days","4-8 days","1-3 weeks","3-6 weeks"],"a":0,"e":"Answer- A. 3-4 days Myocardial rupture may occur almost anytime during 3 weeks after acute myocardial infarction, but is most common between the first and fourth days, when the infracted wall is weakest.","pyqMatches":[{"year":"2016","no":418,"q":"Most frequent time period between myocardial infarction and subsequent myocardial rupture is","o":["3-4 days","4-8 days","1-3 weeks","3-6 weeks"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6631, 'Pathology', 'Hematology', 'Easy', 'Pathology', 472, '{"id":6631,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":472,"q":"Heinz bodies are removed by?","o":["Macrophages","Lymphocytes","Neutrophils","Fibroblasts"],"a":0,"e":"Answer- A. Macrophages * The unstable hemoglobins are those hemoglobin variants that undergo denaturation and precipitation within the red cells as Heinz bodies. * They give rise to what is known as congenital non-spherocytic hemolytic anemia or congenital Heinz body hemolytic anemia. * These disorders have either autosomal dominant inheritance or develop from spontaneous mutations. * The unstable hemoglobins arise from either a single amino acid substitution in the globin chain or due to deletion of one or more amino acids within the β- globin chain so that the firm bonding of the haem group within the molecule is disturbed leading to the formation of methemoglobin and precipitation of globin chains as Heinz bodies. * Heinz bodies are not seen after the first one or two days since they are removed by the spleen, leading to the formation of ‘bite cells’ and fragmented red cells. * Macrophages detect the antigen and remove the damaged portions of the cell, its damaged membrane, and the denatured hemoglobin. * These are associated clinically with congenital hemolytic anemia, G6PD deficiency, hemolytic anemia secondary to drugs such as phenacetin, some hemoglobinopathies (thalassemia), and after splenectomy.","pyqMatches":[{"year":"2016","no":425,"q":"Heinz bodies are removed by?","o":["Macrophages","Lymphocytes","Neutrophils","Fibroblasts"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6632, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 473, '{"id":6632,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":473,"q":"Strawberry gums are seen in","o":["Goodpasteur''s syndrome","Classic polyarteritis nodosa","Wegener''s granulomatosis","Kawasaki syndrome"],"a":2,"e":"Answer- C. Wegener''s granulomatosis Strawberry gums are seen in Wegner''s granulomatosis. Strawberry tongue is seen in Kawasaki disease.","pyqMatches":[{"year":"2016","no":423,"q":"Strawberry gums are seen in","o":["Goodpasteur''s syndrome","Classic polyarteritis nodosa","Wegener''s granulomatosis","Kawasaki syndrome"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6633, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 474, '{"id":6633,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":474,"q":"Mutation in protein associated with restrictive cardiomyopathy?","o":["Myosin regulatory proteins","Myosin binding protein-C","Troponin I","Tropomyosin"],"a":2,"e":"Answer- C. Troponin I RCM-associated mutations have been reported in four genes that encode key sarcomeric proteins/myofilaments","pyqMatches":[{"year":"2016","no":421,"q":"Mutation in protein associated with restrictive cardiomyopathy?","o":["Myosin regulatory proteins","Myosin binding protein-C","Troponin I","Tropomyosin"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6634, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 475, '{"id":6634,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":475,"q":"In apoptosis, protein hydrolysis is due to activation of","o":["lipases","Transcarboxylase","Catalase","Caspases"],"a":3,"e":"Answer- D. Caspases The execution phase of apoptosis In this phase, initiate caspases (Caspase - 8 & 9) activate other caspases known as execution Caspases (Caspases- 3 & 7). After being activated the caspases act on many cellular components. In the nucleus, the target of caspase activation includes proteins involved in transcription, DNA replication, and DNA repair. Caspases activate endonucleases (DNAases) that causes double-stranded breaks in DNA.","pyqMatches":[{"year":"2014","no":369,"q":"In apoptosis, protein hydrolysis is due to activation of","o":["lipases","Transcarboxylase","Catalase","Caspases"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6635, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 477, '{"id":6635,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":477,"q":"Which of the following is not a free radical scavenger -","o":["Glutathione peroxidase","Superoxide dismutase","Catalase","Xanthine oxidase"],"a":3,"e":"Answer- D. Xanthine oxidase Free radical scavgers (anti-oxidants) in body","pyqMatches":[{"year":"2014","no":379,"q":"Which of the following is not a free radical scavenger","o":["Glutathione peroxidase","Superoxide dismutase","Catalase","Xanthine oxidase"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6636, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 478, '{"id":6636,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":478,"q":"Cellular swelling with blebs and myelin figures are the changes seen in","o":["Reversible cell injury","Irreversible cell injury","Metaplasia","Anaplasia"],"a":0,"e":"Answer- A. Reversible cell injury Pathological features of reversible cell injury are : Cellular swelling (earliest); loss of microvilli; cytoplasmic membrane blebs; ER swelling; Myeline figures; detachment of ribosome from ER; cytoplasmic (lipid) vacuole; clumping of chromatin.","pyqMatches":[{"year":"2014","no":381,"q":"Cellular swelling with blebs and myelin figures are the changes seen in","o":["Reversible cell injury","Irreversible cell injury","Metaplasia","Anaplasia"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6637, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 479, '{"id":6637,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":479,"q":"Endothelial molecule participating in rolling is","o":["CD 34","CD 65","CD 56","CD 100"],"a":0,"e":"Answer- A. CD 34 Adhesion molecules involved in Rolling :","pyqMatches":[{"year":"2014","no":384,"q":"Endothelial molecule participating in rolling is","o":["CD 34","CD 65","CD 56","CD 100"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6638, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 480, '{"id":6638,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":480,"q":"What generates intracellular signals when cells are subjected to shear stress","o":["Cadherins","Selectins","Integrins","Focal adhesion molecules"],"a":3,"e":"Answer- D. Focal adhesion molecules Focal adhesion complexes are large (>100 proteins) macromolecular complexes that can be localized at hemidesmosomes, and include proteins that can generate intracellular signals when cells are subjected to increased shear stress, such as endothelium in the bloodstream, or cardiac myocytes in a failing heart.","pyqMatches":[{"year":"2014","no":386,"q":"What generates intracellular signals when cells are subjected to shear stress","o":["Cadherins","Selectins","Integrins","Focal adhesion molecules"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6639, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 481, '{"id":6639,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":481,"q":"True about wound healing with primary intention is","o":["By day 5 epidermis recovers its normal thickness","Intense inflammatory reaction","Wound contraction occurs","Abundant granulation tissue grows"],"a":0,"e":"Answer- A. By day 5 epidermis recovers its normal thickness Healing by primary intention It occurs in wounds with opposed edges, e.g., surgical incision. The healing process follows a series of sequential steps : - Immediate after incision Incisional space filled with blood containing fibrin and blood cells. Dehydration of the surface clot forms scab that covers the wound. Within 24 hours Neutrophils appear at the margins of wound. In 24-48 hours Epithelial cells move from the wound edges along the cut margin of dermis, depositing basement membrane components as they move. They fuse in the midline beneath the surface scab, producing a continuous but thin epithelium layer that closes the wound. By day 3 Neutrophils are largely replaced by macrophages. Granulation tissue progressively invades the incision space. Collegen fibers now present in the margin but do not bridge the incision. By day 5 Incisional space is largely filled with granulation tissue. Neovascularization is maximum. Collegen fibrils become more abundant and begin to bridge the incision. The epidermis recovers its normal thickness. During second week Leukocytes and edema have disappeared. There is continued accumulation of collegen and proliferation of fibroblast. By the end of first month Scar is made up of a cellular connective tissue devoid of inflammatory infiltrate covered now by intact epidermis.","pyqMatches":[{"year":"2014","no":387,"q":"True about wound healing with primary intention is","o":["By day 5 epidermis recovers its normal thickness","Intense inflammatory reaction","Wound contraction occurs","Abundant granulation tissue grows"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6640, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 482, '{"id":6640,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":482,"q":"The definition of exudate is","o":["Extravascular fluid that has a high protein concentration and contains cellular debris","Extravascular fluid that has a low protein concentration","Extravascular fluid with high glucose concentration","Extravascular fluid with low glucose concentration"],"a":0,"e":"Answer- A. Extravascular fluid that has a high protein concentration and contains cellular debris Exudate is an inflammatory fluid that contains high protein content, cellular debris, and specific gravity >1.020. It occurs due to increased vascular permeability.","pyqMatches":[{"year":"2014","no":388,"q":"The definition of exudate is","o":["Extravascular fluid that has a high protein concentration and contains cellular debris","Extravascular fluid that has a low protein concentration","Extravascular fluid with high glucose concentration","Extravascular fluid with low glucose concentration"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6641, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 483, '{"id":6641,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":483,"q":"In tuberculosis the cytokine causing fever is","o":["ILI","IL2","IL3","IL4"],"a":0,"e":"Answer- A. ILI Pyrogenes Pyrogenes are substances that cause fever. Pyrogens may be exogenous or endogenous Exogenous -4 Bacterial toxins Endogenous → IL-1, TNF-a, IL-6, Interferons, Ciliory''s neurotropic factor","pyqMatches":[{"year":"2014","no":389,"q":"In tuberculosis the cytokine causing fever is","o":["ILI","IL2","IL3","IL4"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6642, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 484, '{"id":6642,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":484,"q":"Which acute phase reactant induces rouleaux formation","o":["C reactive protein","Fibrinogen","Serum amyloid A","IL 1"],"a":1,"e":"Answer- B. Fibrinogen Fibrinogen binds to red cells and causes them to form stacks (rouleatix) that sediment more rapidly at unit gravity than do individual red cells.","pyqMatches":[{"year":"2014","no":390,"q":"Which acute phase reactant induces rouleaux formation","o":["C reactive protein","Fibrinogen","Serum amyloid A","IL 1"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6643, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 485, '{"id":6643,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":485,"q":"Hyperimmune IgE syndrome is also called","o":["Jobs syndrome","Wiscott Aldrich syndrome","Chediak-Higashi syndrome","Digeorge syndrome"],"a":0,"e":"Answer- A. Jobs syndrome Job''s syndrome, also called Hyper-IgE syndrome or Hyperimmunoglobulin E syndrome, is an autosomal dominant disorder due to mutations in Signal Transducer and Activator of Transcription-3 (STAT-3). There is defect in phagocytosis. IgE levels are elevated. Other immunoglobulins are normal.","pyqMatches":[{"year":"2014","no":404,"q":"Hyperimmune IgE syndrome is also called","o":["Jobs syndrome","Wiscott Aldrich syndrome","Chediak-Higashi syndrome","Digeorge syndrome"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6644, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 486, '{"id":6644,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":486,"q":"Complement CI synthesized from -","o":["Liver","Macrophage","Intestinal epithelium","Endothelium"],"a":2,"e":"Answer- C. Intestinal epithelium CI is synthesized in intestine; C2 and C4 are synthesized by macrophages; C5 and C8 are synthesized in spleen; and C3, C6 and C9 are synthesized in liver. [Ref: Short textbook of medical microbiology by Satish Gupte p. 92]","pyqMatches":[{"year":"2014","no":407,"q":"Complement CI synthesized from","o":["Liver","Macrophage","Intestinal epithelium","Endothelium"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6645, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 487, '{"id":6645,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":487,"q":"Perform are produced by","o":["NK cell","Cytotoxic T cell","Plasma cell","Monocyte"],"a":0,"e":"Answer- A. NK cell Perforins are hole forming proteins, cause transmembrane pores through which cytotoxic factors enter the cell and destroy it by apoptosis. Perforins are produced by: N.K. Cells [Ananthanarayan 126]","pyqMatches":[{"year":"2014","no":409,"q":"Perform are produced by","o":["NK cell","Cytotoxic T cell","Plasma cell","Monocyte"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6646, 'Pathology', 'Genetic Disorders', 'Easy', 'Pathology', 488, '{"id":6646,"subject":"Pathology","chapter":"Genetic Disorders","difficulty":"Easy","source":"Pathology","sourceNo":488,"q":"Most common known causes of congenital anamolies in humans are","o":["Chromosomal aberrations","Maternal infections","Drugs","Irradiation"],"a":0,"e":"Answer- A. Chromosomal aberrations Genetic Chromosomal aberrations- 10-15 Mendelian inheritance Environmental Maternal/placental infections- 2-3 Maternal disease states- 6-8 Drugs and chemicals- 1 Irradiations Multifactorial 20-25 Unknown- 40-60","pyqMatches":[{"year":"2014","no":427,"q":"Most common known causes of congenital anamolies in humans are","o":["Chromosomal aberrations","Maternal infections","Drugs","Irradiation"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6647, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 489, '{"id":6647,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":489,"q":"Mesothelioma is positive for which intermediate filament","o":["Vimentin","Cytokeratin","GFAP","Desmin"],"a":1,"e":"Answer- B. Cytokeratin Cytokeratin- Carcinoma, mesothelioma, Non-seminoma GCT","pyqMatches":[{"year":"2014","no":435,"q":"Mesothelioma is positive for which intermediate filament","o":["Vimentin","Cytokeratin","GFAP","Desmin"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6648, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 490, '{"id":6648,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":490,"q":"Calretinin is used in","o":["Mesothelioma","Hamartoma","Choristoma","Chordoma"],"a":0,"e":"Answer- A. Mesothelioma Calretinin and cytokeratin are positive in cases of malignant mesothelioma.","pyqMatches":[{"year":"2014","no":436,"q":"Calretinin is used in","o":["Mesothelioma","Hamartoma","Choristoma","Chordoma"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6649, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 491, '{"id":6649,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":491,"q":"Marker of angiosarcoma is","o":["CD 31","Cytokeratin","Vimentin","CD 55"],"a":0,"e":"Answer- A. CD 31 The endothelial origin of these tumors can be demonstrated by immunohistochemical staining for CD31 or von Willebrand factor.","pyqMatches":[{"year":"2014","no":437,"q":"Marker of angiosarcoma is","o":["CD 31","Cytokeratin","Vimentin","CD 55"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6650, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 492, '{"id":6650,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":492,"q":"Keratinization and pearl formation is characteristic of","o":["Squamous cell carcinoma","Basal cell carcinoma","Melanoma","Lymphoma"],"a":0,"e":"Answer- A. Squamous cell carcinoma Histologically, squamous cell carcinoma is characterized by the presence of keratinization and/or intercellular bridges. Keratinization may take the form of squamous pearls or individual cells with markedly eosinophilic dense cytoplasm","pyqMatches":[{"year":"2014","no":438,"q":"Keratinization and pearl formation is characteristic of","o":["Squamous cell carcinoma","Basal cell carcinoma","Melanoma","Lymphoma"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6651, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 493, '{"id":6651,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":493,"q":"Grade of tumor denotes","o":["Degree of differentiation","Degree of anaplasia","Stage of disease","Vascular invasion"],"a":0,"e":"Answer- A. Degree of differentiation Grading is based on the degree of differentiation of tumor cells and the number of mitosis within the tumor.","pyqMatches":[{"year":"2014","no":439,"q":"Grade of tumor denotes","o":["Degree of differentiation","Degree of anaplasia","Stage of disease","Vascular invasion"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6652, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 494, '{"id":6652,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":494,"q":"Carcinoma due to inherited mutation of p53 protooncogene","o":["Li fraumeni syndrome","Familial adenomatous polyposis","Retinoblastoma","Osteosarcoma"],"a":0,"e":"Answer- A. Li fraumeni syndrome Li-Fraumeni syndrome is due to mutation in p-53 gene.","pyqMatches":[{"year":"2014","no":440,"q":"Carcinoma due to inherited mutation of p53 protooncogene","o":["Li fraumeni syndrome","Familial adenomatous polyposis","Retinoblastoma","Osteosarcoma"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6653, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 495, '{"id":6653,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":495,"q":"K ras mutation is seen in","o":["Pancreatic carcinoma","Prostate carcinoma","Gastric carcinoma","Hepatic carcinoma"],"a":0,"e":"Answer- A. Pancreatic carcinoma K - RAS point mutation : Cancers of colon, lung and Pancreas. H - RAS point mutation : Cancers of kidney and bladder N - RAS point mutation : Melanoma and hematological malignancies [Ref Robbin''s 8thie p. 279 & 7h/e p. 295]","pyqMatches":[{"year":"2014","no":444,"q":"K ras mutation is seen in","o":["Pancreatic carcinoma","Prostate carcinoma","Gastric carcinoma","Hepatic carcinoma"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6654, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 496, '{"id":6654,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":496,"q":"DIC is seen in all except","o":["Carcinoma pancreas","Carcinoma prostate","Carcinoma lung","Carcinoma kidney"],"a":3,"e":"Answer- D. Carcinoma kidney Cancers associated with DIC Ca pancreas Ca lung Acute promyelocytic leukemia Ca prostate Ca Stomach","pyqMatches":[{"year":"2014","no":448,"q":"DIC is seen in all except","o":["Carcinoma pancreas","Carcinoma prostate","Carcinoma lung","Carcinoma kidney"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6655, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 497, '{"id":6655,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":497,"q":"Histologic finding in hyperplastic arteriosclerosis","o":["Concentric layer onion skin lesion","Mucinous intimal thickening","Fibrinoid atherosclerosis","All the above"],"a":3,"e":"Answer- D. All the above It is characteristic of malignant hypertension. There is concentrentic, laminated thickening of arteriolar wall onion skinning. There is mucinous intimal thickening and fibrous intimal thickening. There may be accompanied fibrinoid deposits with necrosis of the vessels wall fibrinoid necrosis.","pyqMatches":[{"year":"2014","no":454,"q":"Histologic finding in hyperplastic arteriosclerosis","o":["Concentric layer onion skin lesion","Mucinous intimal thickening","Fibrinoid atherosclerosis","All the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6656, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 498, '{"id":6656,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":498,"q":"Obliterative endarteritis of the vasa vasorum of aorta is seen in","o":["Syphilis","Wegener''s","Chrug strauss","Cold hemoglobinuria"],"a":0,"e":"Answer- A. Syphilis Syphilitic aneurysm is due to obliterative endarteritis that involves vaso vasorum of aorta in the tertiary stage of syphilis.","pyqMatches":[{"year":"2014","no":455,"q":"Obliterative endarteritis of the vasa vasorum of aorta is seen in","o":["Syphilis","Wegener''s","Chrug strauss","Cold hemoglobinuria"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6657, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 499, '{"id":6657,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":499,"q":"Which isoenzyme of LDH is seen in heart","o":["LDH1","LDH2","LDH3","LDH4"],"a":0,"e":"Answer- A. LDH1 Most prominent isoenzymed in heart muscle is LDH-1. LDH-2 is 2nd most prominent form (after LDH 1)","pyqMatches":[{"year":"2014","no":457,"q":"Which isoenzyme of LDH is seen in heart","o":["LDH1","LDH2","LDH3","LDH4"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6658, 'Pathology', 'Hematology', 'Easy', 'Pathology', 500, '{"id":6658,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":500,"q":"MALToma is located in which layer of gastrointestinal tract","o":["Lamina propria","Submucosa","Muscularispropria","Serosa"],"a":0,"e":"Answer- A. Lamina propria Extranodal marginal zone lymphoma or mucosa-associated lymphoid tissue lymphoma (MALToma). It is the most common form of marginal zone lymphoma. MALT lymphoma (MALToma) is divided into gastric (arising in stomach) and non-gastric (arising in small intestine, salivary gland, thyroid etc). Gastric MALToma has been associated with H.pylori infection. Immunophenotype of MALTomas shows positivity for CD 20 and CD","pyqMatches":[{"year":"2014","no":469,"q":"MALToma is located in which layer of gastrointestinal tract","o":["Lamina propria","Submucosa","Muscularispropria","Serosa"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6659, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 501, '{"id":6659,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":501,"q":"Not an irreversible injury-","o":["Pyknosis","Pyknosis","Karyolysis","Bleb formation"],"a":3,"e":"Answer- D. Bleb formation Damage to nucleus can be of three forms- Pkynosis- nuclear shrinkage & chromatin condensation and clumping. Karyorrhexis- Nuclear fragmentation. Karyolysis- decreased basophilia due to dissolution of nucleus.","pyqMatches":[{"year":"2015","no":377,"q":"Not an irreversible injury","o":["Pyknosis","Pyknosis","Karyolysis","Bleb formation"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6660, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 502, '{"id":6660,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":502,"q":"Hyaline degeneration is found in -","o":["MI","Parkinson''s'' disease","Yellow fever hepatitis","Basophilic cell of pituitary"],"a":2,"e":"Answer- C. Yellow fever hepatitis 1) Intracellular hyaline :councilman bodies in yellow fever 2) Extracellular hyaline :n Corpora amylacea are round masse of hyaline seen in prostate in elderly, brain and spinal cord of old people and old infarcts of lung.","pyqMatches":[{"year":"2015","no":379,"q":"Hyaline degeneration is found in","o":["MI","Parkinson''s'' disease","Yellow fever hepatitis","Basophilic cell of pituitary"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6661, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 503, '{"id":6661,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":503,"q":"Lipofuscin is","o":["Wear and tear pigment","Fat deposits","Blood pigment","Form of calcification"],"a":0,"e":"Answer- A. Wear and tear pigment It is an insoluble pigment, also known as I and wear or tear or aging pigment. Lipofuscin is not injurious to the cell or its functions. Its importance lies in being the tell-tale sign of free radical injury and lipid peroxidation.","pyqMatches":[{"year":"2015","no":383,"q":"Lipofuscin is","o":["Wear and tear pigment","Fat deposits","Blood pigment","Form of calcification"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6662, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 504, '{"id":6662,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":504,"q":"Antiapoptotic gene","o":["FLIP","P53","BAX","BIM"],"a":0,"e":"Answer- A. FLIP Proapoptotic genes : Apaf-1, Cytochrome C, Bak, Bax, Bim, AIF, P53, Caspases, TNFRI, FAS (CD95), FADD, BH3 only proteins (Bim, Bid, Bad), Smac/DIABLO. Antiapoptotic genes : BCL-2, BCL-X, Mcl-1, IAPs, FLIP","pyqMatches":[{"year":"2015","no":384,"q":"Antiapoptotic gene","o":["FLIP","P53","BAX","BIM"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6663, 'Pathology', 'Inflammation', 'Hard', 'Pathology', 505, '{"id":6663,"subject":"Pathology","chapter":"Inflammation","difficulty":"Hard","source":"Pathology","sourceNo":505,"q":"Skin involvement along with collar stud ulceration in intestine on radiography. Diagnosis is -","o":["TB intestine","Ulcerative colitis","Intestinal Amebiasis","Crohn''s disease"],"a":1,"e":"Answer- B. Ulcerative colitis Skin involvement can occur in Inflammatory bowel disease i.e. both Crohn''s disease and Ulcerative colitis. Collar stud ulceration is radiographical sign of Ulcerative colitis. ULCERATIVE COLITIS : PATHOLOGY: Colonic mucosal inflammation; rectum almost always involved, with inflammation extending continuously (no skip areas) proximally for a variable extent; histologic features include epithelial damage, inflammation, crypt abscesses, loss of goblet cells. CLINICAL MANIFESTATIONS Bloody diarrhea, mucus, fever, abdominal pain, tenesmus, weight loss; the spectrum of severity (a majority of cases are mild, limited to rectosigmoid). In severe cases, dehydration, anemia, hypokalemia, hypoalbuminemia. COMPLICATIONS Toxic megacolon, colonic perforation; cancer risk related to extent and duration of colitis; often preceded by or coincident with dysplasia, which may be detected on surveillance colonoscopic biopsies. biopsies. DIAGNOSIS Sigmoidoscopy/colonoscopy: mucosal erythema, granularity, friability, exudate, hemorrhage, ulcers, inflammatory polyps (pseudopolyps). Barium enema: loss of haustrations, mucosal irregularity, ulcerations.","pyqMatches":[{"year":"2015","no":492,"q":"Skin involvement along with collar stud ulceration in intestine on radiography. Diagnosis is","o":["TB intestine","Ulcerative colitis","Intestinal Amebiasis","Crohn''s disease"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6664, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 506, '{"id":6664,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":506,"q":"Solution currently used for liver preservation for transplant is -","o":["UW solution","IGL solution","Kyoto ET solution","Ross Marshal Citrate solution"],"a":0,"e":"Answer- A. UW solution UW solution has become the gold standard liver transplantation for many years.\"","pyqMatches":[{"year":"2015","no":491,"q":"Solution currently used for liver preservation for transplant is","o":["UW solution","IGL solution","Kyoto ET solution","Ross Marshal Citrate solution"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6665, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 507, '{"id":6665,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":507,"q":"Fibrosis associated with liver cirrhosis is mediated by -","o":["PDGF","IFN-y","ICAM-1","PcAM-l"],"a":0,"e":"Answer- A. PDGF Most important mediators involved in liver fibrosis - PDGF, PAF, MMPs, TNF-a, TGF-13 ,IL-1.","pyqMatches":[{"year":"2015","no":490,"q":"Fibrosis associated with liver cirrhosis is mediated by","o":["PDGF","IFN-y","ICAM-1","PcAM-l"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6666, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 508, '{"id":6666,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":508,"q":"Not a apoptotic gene","o":["P53","Bax","Mcl-1","n-myc"],"a":3,"e":"Answer- D. n-myc Proapoptotic genes : Apaf-1, Cytochrome C, Bak, Bax, Bim, AIF, P53, Caspases, TNFRI, FAS (CD95), FADD, BH3 only proteins (Bim, Bid, Bad), Smac/DIABLO.","pyqMatches":[{"year":"2015","no":386,"q":"Not a apoptotic gene","o":["P53","Bax","Mcl-1","n-myc"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6667, 'Pathology', 'Hemodynamics', 'Easy', 'Pathology', 509, '{"id":6667,"subject":"Pathology","chapter":"Hemodynamics","difficulty":"Easy","source":"Pathology","sourceNo":509,"q":"Which of the following is false regarding carcinoid tumor ?","o":["Neuroendocrine tumor","Most common site is lung","Associated with serotonin production","Potentially malignant tumor"],"a":1,"e":"Answer- B. Most common site is lung Carcinoid tumors arise from the neuroendocrine cells (Argentaffin cells or Kulchitsky cells). The majority are foundn GI tract, and more than 40% in small intestine (jejunum & ileum). The tracheobronchial tree and lungs are the next common sites involved. Carcinoid tumors may rarely arise from the ovary or thymus Carcinoid tumors are the most common malignancy of the appendix. All carcinoids are considered to have malignant potential. About 10% of carcinoids secrete excessive levels of a range of hormones, most notably serotonin (5-HT), leading to carcinoid syndrome. It is characterized by Flushing, Diarrhea, Wheezing, Abdominal cramping, Peripheral edema","pyqMatches":[{"year":"2015","no":489,"q":"Which of the following is false regarding carcinoid tumor ?","o":["Neuroendocrine tumor","Most common site is lung","Associated with serotonin production","Potentially malignant tumor"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6668, 'Pathology', 'Organ System Pathology', 'Hard', 'Pathology', 510, '{"id":6668,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Hard","source":"Pathology","sourceNo":510,"q":"Caseating necrosis occurs in","o":["Brain","liver","kidney","lung"],"a":3,"e":"Answer- D. lung Gaseous necrosis, a variant of coagulative necrosis can be encountered in any organ where cell death is attributable to certain organisms e.g., mycobacterium tuberculosis (TB), syphilis and fungi (Histoplasma, Coccidioidomycosis). Pulmonary tuberculosis is the most common cause of caseous necrosis. Therefore answer should be \"lung\".","pyqMatches":[{"year":"2015","no":388,"q":"Caseating necrosis occurs in","o":["Brain","liver","kidney","lung"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6669, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 511, '{"id":6669,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":511,"q":"Spread of infection causes","o":["Fibrinoid necrosis","Fat necrosis","Liquifactive necrosis","Coagulative necrosis"],"a":2,"e":"Answer- C. Liquifactive necrosis Liquefactive or colliquative necrosis occurs due to lysosomal permeability and enzymes of leukocytes digest the tissue transforming the tissue into liquid viscous mass. Tissue architecture is lost. Examples are- Infarct brain and abscess cavity.","pyqMatches":[{"year":"2015","no":390,"q":"Spread of infection causes","o":["Fibrinoid necrosis","Fat necrosis","Liquifactive necrosis","Coagulative necrosis"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6670, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 512, '{"id":6670,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":512,"q":"COXtype 3 is a product of-","o":["COX I gene","COX2gene","COX 3 gene","None ofthe above"],"a":0,"e":"Answer- A. COX I gene The COX-3 isozyme is encoded by the same gene as COX-1 (PTGS1 gene), with the difference that COX-3 retains an intron that is not retained in COX-1. It is not functional in humans.","pyqMatches":[{"year":"2015","no":488,"q":"COXtype 3 is a product of","o":["COX I gene","COX2gene","COX 3 gene","None ofthe above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6671, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 513, '{"id":6671,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":513,"q":"Diabetic foot is associated with following type of gangrene -","o":["Dry gangrene","Wet gangrene","Gas gangrene","Fournier''s gangrene"],"a":1,"e":"Answer- B. Wet gangrene When overlying skin of dry gangrenous tissue is devitalized, bacterial infection is superimposed and the coagulative necrosis is modified by liquifactive necrosis. More commonly due to venous occlusion then arterial occlusion. Occurs in diabetic foot and bed sores","pyqMatches":[{"year":"2015","no":392,"q":"Diabetic foot is associated with following type of gangrene","o":["Dry gangrene","Wet gangrene","Gas gangrene","Fournier''s gangrene"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6672, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 514, '{"id":6672,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":514,"q":"Unfolded protein metabolism is associated with","o":["Endoplasmic reticulum","Golgi apparatus","Mitochondria","None of the above"],"a":0,"e":"Answer- A. Endoplasmic reticulum The unfolded protein response (UPR) is a cellular stress response related to the endoplasmic reticulum (ER). Diseases amenable to UPR inhibition include Creutzfeldt-Jakob disease, Alzheimer''s disease, Parkinson''s disease, and Huntington''s disease.","pyqMatches":[{"year":"2015","no":393,"q":"Unfolded protein metabolism is associated with","o":["Endoplasmic reticulum","Golgi apparatus","Mitochondria","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6673, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 515, '{"id":6673,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":515,"q":"Not an example of excess tissue growth","o":["Granulation tissue","Neoplasia","Hyperplasia","Fibrosis"],"a":0,"e":"Answer- A. Granulation tissue Granulation tissue is a hallmark of healing. It is characterized by formation of new small blood vessels (angiogenesis or neovascularization) and proliferation of fibroblasts","pyqMatches":[{"year":"2015","no":395,"q":"Not an example of excess tissue growth","o":["Granulation tissue","Neoplasia","Hyperplasia","Fibrosis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6674, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 516, '{"id":6674,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":516,"q":"1st mediator of inflammation to be released is","o":["Nitric oxide","PAF","Histamine","IL-1"],"a":2,"e":"Answer- C. Histamine Vasoactive amines are present in preformed stores in cells and are therefore among the first mediators to be released during inflammation The two amines are especially important. These are :- (i) Histamine and (ii) Serotonin","pyqMatches":[{"year":"2015","no":396,"q":"1st mediator of inflammation to be released is","o":["Nitric oxide","PAF","Histamine","IL-1"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6675, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 517, '{"id":6675,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":517,"q":"Which of the following is potassium Channelopathy -","o":["Hypokalemic periodic paralysis","Hyperkalemic periodic paralysis","Episodic ataxia I","Long QT-syndrome"],"a":0,"e":"Answer- A. Hypokalemic periodic paralysis Dent''s disease (X linked proteinuria & Kidney stones) Osteopetrosis (recessive or dominant) Barter syndrome type III Barter syndrome type IV (associated with sensorineural deafness) Hyperkplexia (startle disease) Juvenile myoclonus epilepsy Epilepsy","pyqMatches":[{"year":"2015","no":487,"q":"Which of the following is potassium Channelopathy","o":["Hypokalemic periodic paralysis","Hyperkalemic periodic paralysis","Episodic ataxia I","Long QT-syndrome"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6676, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 518, '{"id":6676,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":518,"q":"Rolling of leucocytes on endothelial cells is mediated by","o":["ICAM-1","(3, integrin","IL-8","P- selectin"],"a":3,"e":"Answer- D. P- selectin Rolling & adhesion- It is brought by- P selectin or CD 62 PECAM- 1 involved in leucocyte migration from endothelial surface.","pyqMatches":[{"year":"2015","no":397,"q":"Rolling of leucocytes on endothelial cells is mediated by","o":["ICAM-1","(3, integrin","IL-8","P- selectin"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6677, 'Pathology', 'Hemodynamics', 'Easy', 'Pathology', 519, '{"id":6677,"subject":"Pathology","chapter":"Hemodynamics","difficulty":"Easy","source":"Pathology","sourceNo":519,"q":"Perioperative shock is an example of","o":["Hypovolemic shock","Septic shock","Cardiogenic shock","Neurogenic shock"],"a":0,"e":"Answer- A. Hypovolemic shock \"Most common cause of hypovolemic shock is hemorrhage which may be intraoperative or postoperative.\"","pyqMatches":[{"year":"2015","no":398,"q":"Perioperative shock is an example of","o":["Hypovolemic shock","Septic shock","Cardiogenic shock","Neurogenic shock"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6678, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 520, '{"id":6678,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":520,"q":"Which of the following is not a part of ECM ?","o":["Lectin","Fibronectin","Laminin","Proteoglycans"],"a":0,"e":"Answer- A. Lectin Basement membrane (BM):- PAS positive amorphous structure which lie underneath epithelia of different organs and endothelial cells. Components of BM are laminin, fibronectin, tenascin, collagen type IV, enatactin (nidogen), proteoglycan & perlecan (heparan sulphate).","pyqMatches":[{"year":"2015","no":400,"q":"Which of the following is not a part of ECM ?","o":["Lectin","Fibronectin","Laminin","Proteoglycans"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6679, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 521, '{"id":6679,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":521,"q":"Calrexin and calreticulin are -","o":["Glycoproteins","Chaperons","Tumor markers","Enzymes"],"a":1,"e":"Answer- B. Chaperons Calreticulin & calrexin are major Ca2+ binding (storage) chaperones in the endoplasmic reticulum.","pyqMatches":[{"year":"2015","no":486,"q":"Calrexin and calreticulin are","o":["Glycoproteins","Chaperons","Tumor markers","Enzymes"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6680, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 522, '{"id":6680,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":522,"q":"Which of the following is derived from fibroblast cells ?","o":["TGF-13","MMP2","Collagen","Angiopoietin"],"a":2,"e":"Answer- C. Collagen Fibroblasts produce the glycosaminoglycans, collagens, elastic fibers, reticular fibres and glycoproteins that can be seen in the extracellular matrix. They also produce cytokineTSLP.","pyqMatches":[{"year":"2015","no":401,"q":"Which of the following is derived from fibroblast cells ?","o":["TGF-13","MMP2","Collagen","Angiopoietin"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6681, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 523, '{"id":6681,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":523,"q":"HDL receptor is -","o":["SR-BI","LDLR","HDLR","SR-82"],"a":0,"e":"Answer- A. SR-BI HDL is removed by HDL receptors scavenger receptor BI (SR-BI), which mediate the selective uptake of cholesterol from HDL. This receptor is most abundant in liver, ovaries and adrenal glands.","pyqMatches":[{"year":"2015","no":483,"q":"HDL receptor is","o":["SR-BI","LDLR","HDLR","SR-82"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6682, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 524, '{"id":6682,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":524,"q":"Which of the following enhances acute phase response ?","o":["a-2 microglobulin","Transferrin","Albumin","Retinal binding protein"],"a":0,"e":"Answer- A. a-2 microglobulin a) Positive acute phase proteins These proteins are increased during inflammation. Important examples are C-reactive protein : CRP (f31- globulin), a-1 antitrypsin,fibrinogen, ferritin, serum amyloid A, hepatoglobulin, ceruloplasmin, and a-2 microglobulin. b) Negative acute phase proteins These proteins are decreased during inflammation. Important examples are albumin, prealbumin, transferrin, transcortin, transthyretin and retinal binding protein. Generally, positive acute phase proteins are considered as acute phase proteins.","pyqMatches":[{"year":"2015","no":403,"q":"Which of the following enhances acute phase response ?","o":["a-2 microglobulin","Transferrin","Albumin","Retinal binding protein"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6683, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 525, '{"id":6683,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":525,"q":"IFN-gamma is produced by","o":["Neutrophills","Macrophages","T - cells","B - cells"],"a":2,"e":"Answer- C. T - cells Activated T-cells (helper) produce IFN-y, the major cytokine of granulomatous inflammation. IFN-y Helper T-cells are activated by IL-2 and produce IFN-y, the major cytokine of granulomatous inflammation Finally there is formation of granuloma induced by IFN-y.","pyqMatches":[{"year":"2015","no":407,"q":"IFN-gamma is produced by","o":["Neutrophills","Macrophages","T - cells","B - cells"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6684, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 526, '{"id":6684,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":526,"q":"Homer rosette is seen in -","o":["Neurobastoma","Nephroblastoma","Hepatoma","Ependymoma"],"a":0,"e":"Answer- A. Neurobastoma Homer Wright rosettes Homer-Wright rosettes are characteristic of neuroblastomas and medulloblastomas. May also be seen in -4 Primitive neuroectodermal tumors (PNET), Pineoblastomas, Retinoblastomas","pyqMatches":[{"year":"2015","no":480,"q":"Homer rosette is seen in","o":["Neurobastoma","Nephroblastoma","Hepatoma","Ependymoma"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6685, 'Pathology', 'Hemodynamics', 'Easy', 'Pathology', 527, '{"id":6685,"subject":"Pathology","chapter":"Hemodynamics","difficulty":"Easy","source":"Pathology","sourceNo":527,"q":"Extremities are warm in which type of shock","o":["Hypovolemic shock","Neurogenic shock","Anaphylactic shock","Cardiogenic shock"],"a":1,"e":"Answer- B. Neurogenic shock In hyperdynamic stage of septic shock and in neurogenic shock, extremities are warm due to vasodilatation.","pyqMatches":[{"year":"2015","no":408,"q":"Extremities are warm in which type of shock","o":["Hypovolemic shock","Neurogenic shock","Anaphylactic shock","Cardiogenic shock"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6686, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 528, '{"id":6686,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":528,"q":"Lysosome with undigested particle inside is known as -","o":["Residual body","Phagosome","Phagolysosome","Autophagosome"],"a":0,"e":"Answer- A. Residual body The lysosomes that pinched off from Golgi complex are called primary lysosomes. After a primary lysosome has fused with the vacuole or vesicle containing the material to be digested, it forms the secondary lysosome. After the process of digestion has been completed, a secondary lysosome forms the residual body.","pyqMatches":[{"year":"2015","no":478,"q":"Lysosome with undigested particle inside is known as","o":["Residual body","Phagosome","Phagolysosome","Autophagosome"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6687, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 529, '{"id":6687,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":529,"q":"HLA-Cw6 is associated with","o":["Myatshenia gravis","Behcet''s disease","Pemphigus vulgaris","Psoriasis vulgaris"],"a":3,"e":"Answer- D. Psoriasis vulgaris HLA association in psoriasis Psoriasis vulgaris - Cw6, B13, B17, DRB1*0701/2, B37 Psoriatic arthritis - B27 Generalized pustular psoriasis and acrodermatitis continua of Hallopeau- B27, B8 Pustolosis of palms and soles - Aw19, Bw35","pyqMatches":[{"year":"2015","no":410,"q":"HLA-Cw6 is associated with","o":["Myatshenia gravis","Behcet''s disease","Pemphigus vulgaris","Psoriasis vulgaris"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6688, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 530, '{"id":6688,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":530,"q":"Prusian blue detects?","o":["Ferric iron","Ferrous iron","Glycogen","Lipids"],"a":0,"e":"Answer- A. Ferric iron It is the classic method for demonstrating iron in tissues. The section is treated with dilute hydrochloric acid to release ferric ions from binding proteins","pyqMatches":[{"year":"2015","no":477,"q":"Prusian blue detects?","o":["Ferric iron","Ferrous iron","Glycogen","Lipids"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6689, 'Pathology', 'Hematology', 'Easy', 'Pathology', 531, '{"id":6689,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":531,"q":"Sezary cells show which tlpe of nucleus -","o":["Pleomorphic","Round","Eosinophillic","Cerebriform"],"a":3,"e":"Answer- D. Cerebriform Sezary cells are neoplastic T-cells found in sezary syndrome (cutaneous T-cell lymphoma).","pyqMatches":[{"year":"2015","no":476,"q":"Sezary cells show which tlpe of nucleus","o":["Pleomorphic","Round","Eosinophillic","Cerebriform"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6690, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 532, '{"id":6690,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":532,"q":"MHC-2 is present in all except","o":["Cortical macrophages","Medullary m acrophages","Cortical epithelial cells","Medullary epithelial cells"],"a":1,"e":"Answer- B. Medullary m acrophages Cortical macrophages, epithelial cells and dendritic cells express high level of class II MHC molecule. Medullary macrophages express only class I MHC, while medullary epithelial cells and dendritic cells express both class I & II MHC molecules.","pyqMatches":[{"year":"2015","no":413,"q":"MHC-2 is present in all except","o":["Cortical macrophages","Medullary m acrophages","Cortical epithelial cells","Medullary epithelial cells"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6691, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 533, '{"id":6691,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":533,"q":"B cells are located in which region of lymph nodes","o":["Paracortical region","Cortical follicles","Medullar sinuses","Subcapsular region"],"a":1,"e":"Answer- B. Cortical follicles Location of immune cells in lymph node :","pyqMatches":[{"year":"2015","no":414,"q":"B cells are located in which region of lymph nodes","o":["Paracortical region","Cortical follicles","Medullar sinuses","Subcapsular region"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6692, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 534, '{"id":6692,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":534,"q":"PSGN is an example of which type of hyper sensitivity","o":["Type -1 hypersensitivity","Type -2 hypersensitivity","Type -3 hypersensitivity","Type -4 hypersensitivity"],"a":2,"e":"Answer- C. Type -3 hypersensitivity Glomerulonephritis (PSGN : Post-streptococal GN) is a type III hypersensitivity.","pyqMatches":[{"year":"2015","no":415,"q":"PSGN is an example of which type of hyper sensitivity","o":["Type -1 hypersensitivity","Type -2 hypersensitivity","Type -3 hypersensitivity","Type -4 hypersensitivity"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6693, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 535, '{"id":6693,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":535,"q":"Number of criteria for HLA matching are","o":["10","4","16","22"],"a":0,"e":"Answer- A. 10 At least 8 HLA markers for these minimum requirements: two A markers, two B markers, two C markers, and two DRB1 markers. Sometimes an additional marker, called DQ, is also matched making it 10 markers.","pyqMatches":[{"year":"2015","no":416,"q":"Number of criteria for HLA matching are","o":["10","4","16","22"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6694, 'Pathology', 'Inflammation', 'Moderate', 'Pathology', 536, '{"id":6694,"subject":"Pathology","chapter":"Inflammation","difficulty":"Moderate","source":"Pathology","sourceNo":536,"q":"All of the following are features of granulomatous thyroiditis except?","o":["Hyperthyroidism","Hypothyroidism","Painless","Giant cells on histology"],"a":2,"e":"Answer- C. Painless Clinical Features- Painful enlarged thyroid, fever Hypothyroidism Malaise Sore throat, pain referred to the jaw or ear. Subacute thyroiditis is a self-limited thyroid condition associated with a triphasic clinical course of hyperthyroidism, hypothyroidism, and return to normal thyroid function","pyqMatches":[{"year":"2015","no":475,"q":"All of the following are features of granulomatous thyroiditis except?","o":["Hyperthyroidism","Hypothyroidism","Painless","Giant cells on histology"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6695, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 537, '{"id":6695,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":537,"q":"Organ with least chance of rejection","o":["Blood","Kidney","Heart","Liver"],"a":3,"e":"Answer- D. Liver HLA matching play a very minimal role in liver transplant therefore immune rejection is less common in liver transplant.","pyqMatches":[{"year":"2015","no":417,"q":"Organ with least chance of rejection","o":["Blood","Kidney","Heart","Liver"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6696, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 538, '{"id":6696,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":538,"q":"Mc type of graft rejection is","o":["Hyperacute","Acute","Chronic","Acute on chronic"],"a":2,"e":"Answer- C. Chronic \"Acute graft rejection is the most common form\"","pyqMatches":[{"year":"2015","no":418,"q":"Mc type of graft rejection is","o":["Hyperacute","Acute","Chronic","Acute on chronic"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6697, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 539, '{"id":6697,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":539,"q":"In follicular carcinoma chromosomal translocation is?","o":["PAXS - PPARTI","RET - PTC","ALK - NMPI","IAK - TEL"],"a":0,"e":"Answer- A. PAXS - PPARTI Follicular - PAX8- PPARrl translocation","pyqMatches":[{"year":"2015","no":473,"q":"In follicular carcinoma chromosomal translocation is?","o":["PAXS - PPARTI","RET - PTC","ALK - NMPI","IAK - TEL"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6698, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 540, '{"id":6698,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":540,"q":"True about serum sickness is","o":["Type 2 hypersensitivity","Can lead to leukocytoclastic vasculitis","Hypercomplementemia","Can occur due to homologous antigen"],"a":1,"e":"Answe- B. Can lead to leukocytoclastic vasculitis Serum sickness is a type III hypersensitivity (immune complex mediated) reaction that results from the injection of heterologous or foreign protein or serum. When an antiserum is given, the human immune system can mistake the proteins present for harmful antigens. The body produces antibodies, which combine with these proteins to form immune complexes. These complexes precipitate, enter the walls of blood vessels, and activate the complement cascade, initiating an inflammatory response and consuming much of the available complement component 3 (C3). The result is a leukocytoclastic vasculitis.","pyqMatches":[{"year":"2015","no":419,"q":"True about serum sickness is","o":["Type 2 hypersensitivity","Can lead to leukocytoclastic vasculitis","Hypercomplementemia","Can occur due to homologous antigen"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6699, 'Pathology', 'Genetic Disorders', 'Easy', 'Pathology', 541, '{"id":6699,"subject":"Pathology","chapter":"Genetic Disorders","difficulty":"Easy","source":"Pathology","sourceNo":541,"q":"Most lethal combination is","o":["Autosomal monosomy","Chromosomal monosomy","Autosomal trisomy","Chromosomal trisomy"],"a":0,"e":"Answer- A. Autosomal monosomy Autosomal monosomies (loss of one autosome) are incompatible with fetal development and are not found in live births. Only monosomy compatible with live birth is due to involvement of sex chromosome, i.e. Turner syndrome (45 X).","pyqMatches":[{"year":"2015","no":420,"q":"Most lethal combination is","o":["Autosomal monosomy","Chromosomal monosomy","Autosomal trisomy","Chromosomal trisomy"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6700, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 542, '{"id":6700,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":542,"q":"NotafeatureofPSGN -","o":["HTN","Increased urea","Increased creatinine","Normal C3 level"],"a":3,"e":"Answer- D. Normal C3 level Complement level is decreased in PSGN. Other options are correct.","pyqMatches":[{"year":"2015","no":472,"q":"NotafeatureofPSGN","o":["HTN","Increased urea","Increased creatinine","Normal C3 level"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6701, 'Pathology', 'Genetic Disorders', 'Moderate', 'Pathology', 543, '{"id":6701,"subject":"Pathology","chapter":"Genetic Disorders","difficulty":"Moderate","source":"Pathology","sourceNo":543,"q":"All of the following are true about Down syndrome except","o":["Incidence of Robertsonian translocation is 1:1000","Extra chromosome is of maternal origin","Most common cause is trisomy 21","Mosaicism 21 has no association with maternal age"],"a":0,"e":"Answer- A. Incidence of Robertsonian translocation is 1:1000 Cytogenetics in Down''s syndrome","pyqMatches":[{"year":"2015","no":421,"q":"All of the following are true about Down syndrome except","o":["Incidence of Robertsonian translocation is 1:1000","Extra chromosome is of maternal origin","Most common cause is trisomy 21","Mosaicism 21 has no association with maternal age"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6702, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 544, '{"id":6702,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":544,"q":"Hypophosphatemic rickets is","o":["AR","AD","XR","XD"],"a":3,"e":"Answer- D. XD X-linked dominant disorders Vitamine D resistant (X-linked hypophosphatemic) Rickets. Familial hypophosphatemia. Fragile X-syndrome. Incontinentia pigmenti. Rett syndrome.","pyqMatches":[{"year":"2015","no":422,"q":"Hypophosphatemic rickets is","o":["AR","AD","XR","XD"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6703, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 545, '{"id":6703,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":545,"q":"Irregular scarred kidney with pelvic dilatation is seen with -","o":["Chronicpyelonephritis","Polycystickidney","Renalarterystenosis","Tuberculosisofkidney"],"a":0,"e":"Answer- A. Chronicpyelonephritis Pathological changes of chronic pyelonephritis are :","pyqMatches":[{"year":"2015","no":469,"q":"Irregular scarred kidney with pelvic dilatation is seen with","o":["Chronicpyelonephritis","Polycystickidney","Renalarterystenosis","Tuberculosisofkidney"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6704, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 546, '{"id":6704,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":546,"q":"Structure of chromosomes is studied by?","o":["C-banding","G-banding","Q-banding","Brd V-staining"],"a":1,"e":"Answer- B. G-banding Metaphase cells are then fixed with methanol/glacial acetic acid mixture and stained by one of the several banding techniques :-","pyqMatches":[{"year":"2015","no":424,"q":"Structure of chromosomes is studied by?","o":["C-banding","G-banding","Q-banding","Brd V-staining"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6705, 'Pathology', 'Genetic Disorders', 'Easy', 'Pathology', 547, '{"id":6705,"subject":"Pathology","chapter":"Genetic Disorders","difficulty":"Easy","source":"Pathology","sourceNo":547,"q":"Location of gene on chromosome is identified by","o":["Karyotyping","Genetic mapping","Microarray","Genomic imprinting"],"a":1,"e":"Answer- B. Genetic mapping A map of the human genome allows to understand where genes are located.","pyqMatches":[{"year":"2015","no":425,"q":"Location of gene on chromosome is identified by","o":["Karyotyping","Genetic mapping","Microarray","Genomic imprinting"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6706, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 548, '{"id":6706,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":548,"q":"Tyrosine kinase receptor is associated with proto¬oncogene -","o":["RAS","MYC","RET","RB"],"a":2,"e":"Answer- C. RET It is a growth factor receptor (receptor tyrosine kinase). RET protein is a receptor for glial cell lined derived neurotrophic factor. RET is normally expressed in parafollicular ''C'' cells of thyroid, adrenal medulla andparathyroid cell precursons. Point mutation in RET protooncogenes is associated with MEN-2A, MEN-2B, medullary thyroid carcinoma and Hirschsprung disease.","pyqMatches":[{"year":"2015","no":426,"q":"Tyrosine kinase receptor is associated with proto¬oncogene","o":["RAS","MYC","RET","RB"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6707, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 549, '{"id":6707,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":549,"q":"IgA nephropathyis not associatedwith?","o":["Focal Mesengial proliferation","Gross hematuria within 1-2 daYs","On immunofluorescence deposits contain both IgA and IgG","Increased compliment level"],"a":3,"e":"Answer- D. Increased compliment level Compliment level is normal in IgA nephropathy. It is common in children. Gross hematuria is seen in 1-2 days. It is a type of mesangioproliferative (not membranoproliferative) GN. It is the most common type of glomerulonephritis world wide.","pyqMatches":[{"year":"2015","no":467,"q":"IgA nephropathyis not associatedwith?","o":["Focal Mesengial proliferation","Gross hematuria within 1-2 daYs","On immunofluorescence deposits contain both IgA and IgG","Increased compliment level"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6708, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 550, '{"id":6708,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":550,"q":"Characteristic feature of IgA nephropathy -","o":["Serum compliment level is normal","More common in old age","It is a tFpe of membranoproliferative GN","Gross hematuria presents after l0 days"],"a":0,"e":"Answer- A. Serum compliment level is normal Compliment level is normal in IgA nephropathy. It is common in children. Gross hematuria is seen in 1-2 days. It is a type of mesangioproliferative (not membranoproliferative) GN. It is the most common type of glomerulonephritis world wide.","pyqMatches":[{"year":"2015","no":466,"q":"Characteristic feature of IgA nephropathy","o":["Serum compliment level is normal","More common in old age","It is a tFpe of membranoproliferative GN","Gross hematuria presents after l0 days"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6709, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 551, '{"id":6709,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":551,"q":"Which of the following has tumor promoting effect?","o":["BRAC","RB","MYC","p16"],"a":2,"e":"Answer- C. MYC RAS, Mitogen-activated protein kinase kinase, VEGF, or Akt","pyqMatches":[{"year":"2015","no":429,"q":"Which of the following has tumor promoting effect?","o":["BRAC","RB","MYC","p16"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6710, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 552, '{"id":6710,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":552,"q":"CEA is","o":["Hormone","Glycoprotein","Enzyme","Tumor associated protein"],"a":1,"e":"Answer- B. Glycoprotein Carcinoembryonic protein (CEA) is a glycoprotein.","pyqMatches":[{"year":"2015","no":430,"q":"CEA is","o":["Hormone","Glycoprotein","Enzyme","Tumor associated protein"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6711, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 553, '{"id":6711,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":553,"q":"CEA is increased in which non- neoplastic condition","o":["Hemolytic anemia","Pancreatitis","BPH","Pregnancy"],"a":0,"e":":B CEA-Carcinoembryonic antigen (CEA): CEA is also a glycoprotein normally synthesized in embryonic tissue of the gut, pancreas, and liver. Their serum levels are high in cancers of the gastrointestinal tract, pancreas, ovarian cancer and breast. CEA levels are also elevated in certain non-neoplastic conditions e.g. in ulcerative colitis, Crohn’s disease, hepatitis, and chronic bronchitis, Alcoholic cirrhosis, smoking, pancreatitis, hemolytic anemia","pyqMatches":[{"year":"2015","no":431,"q":"CEA is increased in which non- neoplastic condition","o":["Hemolytic anemia","Pancreatitis","BPH","Pregnancy"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6712, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 554, '{"id":6712,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":554,"q":"Most common tnre of renal carcinoma is -","o":["Clear cell type","Chromophobe type","Papillarytype","Tubulartype"],"a":0,"e":"Answer- A. Clear cell type Clear cell carcinoma is the most common type of renal cancer accounting for about 70% to 80% of the renal cell cancer.","pyqMatches":[{"year":"2015","no":465,"q":"Most common tnre of renal carcinoma is","o":["Clear cell type","Chromophobe type","Papillarytype","Tubulartype"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6713, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 555, '{"id":6713,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":555,"q":"Carcinoma originating from glands is called","o":["Basal cell carcinoma","Squamous cell carcinoma","Adenocarcinoma","Fibrosarcoma"],"a":2,"e":"Answer- C. Adenocarcinoma Benign tumor of glands → Adenoma. Malignant tumor of gland → Adenocarcinoma.","pyqMatches":[{"year":"2015","no":432,"q":"Carcinoma originating from glands is called","o":["Basal cell carcinoma","Squamous cell carcinoma","Adenocarcinoma","Fibrosarcoma"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6714, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 556, '{"id":6714,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":556,"q":"Most common histological form of lung Ca that metastasizes is -","o":["Squamous cell CA","Adenocarcinoma","Alveolar-carcinoma","Small cell carcinoma"],"a":0,"e":"Answer- A. Squamous cell CA Small cell carcinomas are the most aggressive of lung tumors, metastasize widely and are virtually incurable by surgical means.","pyqMatches":[{"year":"2015","no":464,"q":"Most common histological form of lung Ca that metastasizes is","o":["Squamous cell CA","Adenocarcinoma","Alveolar-carcinoma","Small cell carcinoma"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6715, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 557, '{"id":6715,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":557,"q":"Hematological carcinoma is commonly linked to","o":["Nicotine","Benzene","Lithium","Alcohol"],"a":1,"e":"Answer- B. Benzene Benzene exposure is associated with leukemia.","pyqMatches":[{"year":"2015","no":433,"q":"Hematological carcinoma is commonly linked to","o":["Nicotine","Benzene","Lithium","Alcohol"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6716, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 558, '{"id":6716,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":558,"q":"Elastic fibers of tunica media are secreted by","o":["Fibroblast","Endothelium","Smooth muscle","External lamina"],"a":2,"e":"Amswer- C. Smooth muscle The blood vessels are made of three layers, called from the luminal side outward, the tunica intima, the tunica media and the tunica adventitia.","pyqMatches":[{"year":"2015","no":435,"q":"Elastic fibers of tunica media are secreted by","o":["Fibroblast","Endothelium","Smooth muscle","External lamina"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6717, 'Pathology', 'Organ System Pathology', 'Moderate', 'Pathology', 559, '{"id":6717,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Moderate","source":"Pathology","sourceNo":559,"q":"Level of which of the following is not elevated in heart disease","o":["LDH","5-nucleotidase","SGOT","ALP"],"a":1,"e":"Answer- B. 5-nucleotidase 5-nucleotidase is elevated in liver disease, bone disease and pregnancy. ALP (alkaline phosphatase) is raised in congestive heart failure","pyqMatches":[{"year":"2015","no":436,"q":"Level of which of the following is not elevated in heart disease","o":["LDH","5-nucleotidase","SGOT","ALP"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6718, 'Pathology', 'Miscellaneous', 'Moderate', 'Pathology', 560, '{"id":6718,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pathology","sourceNo":560,"q":"Radiotherapy induced radiation pneumonitis mediated by all of the following except -","o":["TNF-c","PAF","TGF-p","NF-kB"],"a":1,"e":"Answer- B. PAF Important mediators of Radiation induced pneumonitis are TNF-a, TGF-I3 and Th2 cells cytokines (IL-4, IL-5, IL-6 & IL-13). ml response(II,-2, IFN-y) is suppressed during radiation pneumonitis","pyqMatches":[{"year":"2015","no":462,"q":"Radiotherapy induced radiation pneumonitis mediated by all of the following except","o":["TNF-c","PAF","TGF-p","NF-kB"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6719, 'Pathology', 'Hematology', 'Moderate', 'Pathology', 561, '{"id":6719,"subject":"Pathology","chapter":"Hematology","difficulty":"Moderate","source":"Pathology","sourceNo":561,"q":"Which of the following does not predispose to leukemia?","o":["Genetic disorder","Alcohol","Smoking","Chemical exposure"],"a":1,"e":"Answer- B. Alcohol Etiological agents are radiation, chemicals (benzene, ethylene oxide), smoking and drugs (alkylating agents, topoisomerase II inhibitors).","pyqMatches":[{"year":"2015","no":458,"q":"Which of the following does not predispose to leukemia?","o":["Genetic disorder","Alcohol","Smoking","Chemical exposure"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6720, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 562, '{"id":6720,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":562,"q":"Routine Rh typing includes testing?","o":["A antigen","B antigen","C antigen","D antigen"],"a":3,"e":"Answer- D. D antigen After ABO, the most important antigen in transfusion practice is D. The D antigen is a member of the Rh system.","pyqMatches":[{"year":"2015","no":456,"q":"Routine Rh typing includes testing?","o":["A antigen","B antigen","C antigen","D antigen"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6721, 'Pathology', 'Hematology', 'Easy', 'Pathology', 563, '{"id":6721,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":563,"q":"Ristocetin testing von Willebrand disease shows?","o":["Increased agglutination","Decreasedagglutination","Normalagglutination","No agglutination"],"a":1,"e":"Answer- B. Decreasedagglutination Adding ristocetin at a final concentration of 1.25 g/1 to platelet rich plasma (PRP) of a patient with von Willebrand disease (VWD) almost invariably results in a reduced agglutination of the platelets compared to a normal PRP.","pyqMatches":[{"year":"2015","no":454,"q":"Ristocetin testing von Willebrand disease shows?","o":["Increased agglutination","Decreasedagglutination","Normalagglutination","No agglutination"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6722, 'Pathology', 'Hematology', 'Easy', 'Pathology', 564, '{"id":6722,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":564,"q":"Osmotic fragility test is commonly used for -","o":["Iron deficienry anemia","Megaloblastic anemia","Hereditary spherocYtosis","Aplastic anemia"],"a":2,"e":"Answer- C. Hereditary spherocYtosis Increased Osmotic fragility- Hereditary spherocytosis Hemolytic anemia (acquired immune) Malaria Severe pyruvate kinase dificiency","pyqMatches":[{"year":"2015","no":452,"q":"Osmotic fragility test is commonly used for","o":["Iron deficienry anemia","Megaloblastic anemia","Hereditary spherocYtosis","Aplastic anemia"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6723, 'Pathology', 'Hematology', 'Easy', 'Pathology', 565, '{"id":6723,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":565,"q":"Warm antibody in AIHA is -","o":["IgE","IgM","IgG","IgD"],"a":2,"e":"Answer- C. IgG Warm antibody autoimmune hemolytic anemia is the most common form of autoimmune hemolytic anemia. Most causative antibodies are of the IgG class, sometimes IgA antibodies are culprit.","pyqMatches":[{"year":"2015","no":451,"q":"Warm antibody in AIHA is","o":["IgE","IgM","IgG","IgD"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6724, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 566, '{"id":6724,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":566,"q":"What is true about sickle cell -","o":["Sickling occurs both in heterozygous and homozygous state","Fetal hemoglobin facilitates Sickling","Sickling is reversible with oxygenation","Sickling Leads to decreased MCHC"],"a":2,"e":"Answer- C. Sickling is reversible with oxygenation Sickling of red cells is reversible initially, i.e., with oxygenation, HbS depolymerizes and cell shape normalizes. Repeated episodes of deoxygenation and sickling, membrane damage occurs and cells become irreversibly sickled, and retain their abnormal shape even when full oxygenated.","pyqMatches":[{"year":"2015","no":450,"q":"What is true about sickle cell","o":["Sickling occurs both in heterozygous and homozygous state","Fetal hemoglobin facilitates Sickling","Sickling is reversible with oxygenation","Sickling Leads to decreased MCHC"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6725, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 567, '{"id":6725,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":567,"q":"Distinguishing feature of reticulocyte is -","o":["Constitute 10% of the red cells","No nucleus","Smaller in size then RBCs","Mature in lymPh nodes"],"a":1,"e":"Answer- B. No nucleus Reticulocytes are immature red blood cells Reticulocytes do not have a nucleus.","pyqMatches":[{"year":"2015","no":448,"q":"Distinguishing feature of reticulocyte is","o":["Constitute 10% of the red cells","No nucleus","Smaller in size then RBCs","Mature in lymPh nodes"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6726, 'Pathology', 'Hematology', 'Easy', 'Pathology', 568, '{"id":6726,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":568,"q":"Normal Myeloid - erythroid ratio is -","o":["l:l","2:l","3:l","4:1"],"a":2,"e":"Answer- C. 3:l Bone marrow is the major source of all hematopoietic cells (proginator hematopoietic cells) in post-natal life. In normal adults, ratio of fat cells to hematopoietic cells is 1:1. Ratio of myeloid to erythroid is 3 : 1. Ratio of fat cells to erythroid cells is 4: I.","pyqMatches":[{"year":"2015","no":447,"q":"Normal Myeloid - erythroid ratio is","o":["l:l","2:l","3:l","4:1"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6727, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 569, '{"id":6727,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":569,"q":"hL/h blood group-","o":["lacks H- antigen","lacks A-antigen","lacks B- antigen","Alloftheabove"],"a":3,"e":"Answer- D. Alloftheabove In Bombay blood group(h/h or Oh blood group) the precursor antigen (H antigen) is absent, consequently A and B antigens which are derived from modification of H antigen are not formed. Thus, Bombay blood group lacks H, A and B antigen.","pyqMatches":[{"year":"2015","no":446,"q":"hL/h blood group","o":["lacks H- antigen","lacks A-antigen","lacks B- antigen","Alloftheabove"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6728, 'Pathology', 'Hemodynamics', 'Easy', 'Pathology', 570, '{"id":6728,"subject":"Pathology","chapter":"Hemodynamics","difficulty":"Easy","source":"Pathology","sourceNo":570,"q":"Amount of blood loss in Stage I of hemorrhagic shock is -","o":["<10%","<20%","<30%","<40%"],"a":1,"e":"Answer- B. <20% Mild hypovolemia (stage 1)(< 20% volume loss) : Only mild tachycardia is there with normal BP Rapid loss of up to 20% of the blood volume, or slow losses of even larger amounts, may have little impact in healthy adults; greater losses, however, can cause hemorrhagic (hypovolemic) shock","pyqMatches":[{"year":"2015","no":445,"q":"Amount of blood loss in Stage I of hemorrhagic shock is","o":["<10%","<20%","<30%","<40%"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6729, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 571, '{"id":6729,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":571,"q":"Which type of artery is most commonly involved in PAN?","o":["Muscular","Pulmonary","Skin","GIT"],"a":0,"e":"Answer- A. Muscular Polyarteritis nodosa or classical polyarteritis nodosa is systemic necrotizing vasculitis of medium sized muscular arteries, but does not involve small vessels i.e., arterioles, venules or capillaries. It typically spares the pulmonary circulation. Renal artery involvement is the major cause of death.","pyqMatches":[{"year":"2015","no":444,"q":"Which type of artery is most commonly involved in PAN?","o":["Muscular","Pulmonary","Skin","GIT"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6730, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 572, '{"id":6730,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":572,"q":"Obliterative endarteritis in vasa vasorum is seen in -","o":["Hypertension","Tuberculosis","Syphilis","SLE"],"a":2,"e":"Answer- C. Syphilis Obliterative endarteritis that involves vaso vasorum of aortais seen in the tertiary stage of syphilis. It may lead to syphilitic aneursym (leuetic aneurysm). It usually affects the proximal ascending aorta, particularly the aortic ring. Syphilitic aortitis may occasionaly involve the aortic arch or descending aorta.","pyqMatches":[{"year":"2015","no":442,"q":"Obliterative endarteritis in vasa vasorum is seen in","o":["Hypertension","Tuberculosis","Syphilis","SLE"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6731, 'Pathology', 'Hemodynamics', 'Easy', 'Pathology', 573, '{"id":6731,"subject":"Pathology","chapter":"Hemodynamics","difficulty":"Easy","source":"Pathology","sourceNo":573,"q":"Heart failure cells are seen in -","o":["Pulmonary edema","Pulmonary infarction","Pulmonary abscess","PulmonaryTB"],"a":0,"e":"Answer- A. Pulmonary edema Pulmonary edema & pulmonary infarction can be differentiated by the presence of heart failure cells in pulmonary edema. Heart failure cells are Hemosiderin laden alveolar macrophages. Heart failure cells are a manifestation of pulmonary congestion and edema (as seen in heart failure).","pyqMatches":[{"year":"2015","no":441,"q":"Heart failure cells are seen in","o":["Pulmonary edema","Pulmonary infarction","Pulmonary abscess","PulmonaryTB"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6732, 'Pathology', 'Hemodynamics', 'Easy', 'Pathology', 574, '{"id":6732,"subject":"Pathology","chapter":"Hemodynamics","difficulty":"Easy","source":"Pathology","sourceNo":574,"q":"Heart failure cells are","o":["Neutrophils","Macrophages","Lymphocytes","Basophils"],"a":1,"e":"Answer- B. Macrophages Heart failure cells are Hemosiderin laden alveolar macrophages. Heart failure cells are a manifestation of pulmonary congestion and edema (as seen in heart failure). Rupture of dilated and congested capillaries may result in minute intra-alveolar hemorrhages. The breakdown of erythrocytes liberates haemosiderin pigment which is taken up by alveolar macrophages, so-called heart failure cells, seen in the alveolar lumina.","pyqMatches":[{"year":"2013","no":391,"q":"Heart failure cells are ?","o":["Lipofuscin granules in cardiac cells","Pigmented alveolar macrophages","Pigmented pancreatic acinar cells","Pigment cells seen in liver"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2015","no":440,"q":"Heart failure cells are","o":["Neutrophils","Macrophages","Lymphocytes","Basophils"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2013","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6733, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 575, '{"id":6733,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":575,"q":"Lines of Zahn are seen in -","o":["Heart","Lung","Liver","Kidney"],"a":0,"e":"Answer- A. Heart Lines of Zohn → Characteristic of thrombi that is formed in heart or aorta. They have visible and microscopic laminations produced by alternating pale layer of platelets mixed with fibrin and darker layer containing red blood cells.","pyqMatches":[{"year":"2015","no":438,"q":"Lines of Zahn are seen in","o":["Heart","Lung","Liver","Kidney"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6734, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 576, '{"id":6734,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":576,"q":"Which protein is defective in dialated cardiomyopathy?","o":["Myosin","Troponin","Tropomysoin","Dystrophin"],"a":3,"e":"Answer- D. Dystrophin Dialated cardiomyopathy occus due to defective cytoskeleton proteins. Most important protein inovolved is dystrophin. Other proteins affected are : (1) Desmin; (2) MLP Protein and (3) aP crystalline proteins","pyqMatches":[{"year":"2015","no":437,"q":"Which protein is defective in dialated cardiomyopathy?","o":["Myosin","Troponin","Tropomysoin","Dystrophin"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6735, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 577, '{"id":6735,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":577,"q":"Which of the following is seen in young''s syndrome ?","o":["Azoospermia","Bronchiectasis","Infertility","All of the above"],"a":3,"e":"Answer- D. All of the above Young''s syndrome is characterized by :","pyqMatches":[{"year":"2013","no":375,"q":"Which of the following is seen in young''s syndrome ?","o":["Azoospermia","Bronchiectasis","Infertility","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6736, 'Pathology', 'Infectious Diseases', 'Moderate', 'Pathology', 578, '{"id":6736,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Moderate","source":"Pathology","sourceNo":578,"q":"Amyloidosis occurs in all except","o":["Tuberculosis","Chronic bronchitis","Osteomyelitis","Bronchiectasis"],"a":1,"e":"Answer- B. Chronic bronchitis Secondory amyloidosis It occurs secondary to an associated inflammatory conditions like","pyqMatches":[{"year":"2013","no":376,"q":"Amyloidosis occurs in all except","o":["Tuberculosis","Chronic bronchitis","Osteomyelitis","Bronchiectasis"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6737, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 579, '{"id":6737,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":579,"q":"Most common cause of death in SLE in children","o":["Lupus nephritis","Lupus cerebrits","Libman sacks endocarditis","Anemia and infections"],"a":0,"e":"Answer- A. Lupus nephritis Major causes of death in pediatric SLE include :","pyqMatches":[{"year":"2013","no":377,"q":"Most common cause of death in SLE in children","o":["Lupus nephritis","Lupus cerebrits","Libman sacks endocarditis","Anemia and infections"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6738, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 580, '{"id":6738,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":580,"q":"Small posterior fossa seen in ?","o":["Arnold chiari malformation","Dandy walker","Medulloblastoma","Schizencephaly"],"a":0,"e":"Answer- A. Arnold chiari malformation Small posterior fossa → arnold chiari malformation. Large posterior fossa → dondy walker molformation","pyqMatches":[{"year":"2013","no":378,"q":"Small posterior fossa seen in ?","o":["Arnold chiari malformation","Dandy walker","Medulloblastoma","Schizencephaly"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6739, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 581, '{"id":6739,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":581,"q":"Incorrect about HIV associated nephropathy ?","o":["Proteinuria","Shrunken kidneys","15% cases show mesengial proliferation","Develops when CD4<200"],"a":1,"e":"Answer- B. Shrunken kidneys Most common (80%) kidney lesion in AIDS is FSGS (especially collapsing variant i.e. collapsing glomerulopathy). It is termed as HIV associated nephropathy (HIVAN). Mesangioproliferative (mesangial proliferation) GN is 2nd most kidney lesion Other kidney lesions are diffuse proliferative GN, MPGN, IgA nephropathy, membranous GN and minimal change disease.","pyqMatches":[{"year":"2013","no":380,"q":"Incorrect about HIV associated nephropathy ?","o":["Proteinuria","Shrunken kidneys","15% cases show mesengial proliferation","Develops when CD4<200"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6740, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 582, '{"id":6740,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":582,"q":"Pyogenic granulom true A/E","o":["Bacterial infection","Bleeding","Benign tumour","Capillary hemangioma"],"a":0,"e":"Answer- A. Bacterial infection Pyogenic granuloma (PG) or labular capillary hemangioma is a benign vascular tumour of the skin or mucous membrane characterized by rapid growth and friable surface. Angiogenic growth factors such as vascular endothelial growth factors (VEGE) and decorin,transcription factors, and signal transduction pathways (MAPK) are overexpressed in pyogenic granulomas","pyqMatches":[{"year":"2012","no":447,"q":"Pyogenic granulom true A/E","o":["Bacterial infection","Bleeding","Benign tumour","Capillary hemangioma"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6741, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 583, '{"id":6741,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":583,"q":"Visceral aneurysm is most commonly seen in","o":["Splenic","Renal","Hepatic","Coronary"],"a":0,"e":"Answer- A. Splenic Most common visceral artery aneurysm is splenic artery aneurysm. 2nd most common visceral artery aneurysm is hepatic artery aneurysm.","pyqMatches":[{"year":"2012","no":450,"q":"Visceral aneurysm is most commonly seen in","o":["Splenic","Renal","Hepatic","Coronary"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6742, 'Pathology', 'Hematology', 'Moderate', 'Pathology', 584, '{"id":6742,"subject":"Pathology","chapter":"Hematology","difficulty":"Moderate","source":"Pathology","sourceNo":584,"q":"All of the following provide protection against malaria except -","o":["Duffy blood group","Sickle cell anemia","Hereditary spherocytosis","PNH"],"a":3,"e":"Answer- D. PNH PNH is a hemolytic anemia caused by an acquired intrinsic defect in the cell membrane. PNH results from acquired mutation that inhibits the synthesis of Glycosylphospatidylinositol (GPI).","pyqMatches":[{"year":"2012","no":480,"q":"All of the following provide protection against malaria except","o":["Duffy blood group","Sickle cell anemia","Hereditary spherocytosis","PNH"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6743, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 585, '{"id":6743,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":585,"q":"Thorium induced tumor","o":["Angiosarcoma of liver","Renal cell carcinoma","Lymphoma","Astrocytoma"],"a":0,"e":"Answer- A. Angiosarcoma of liver Thorotrost (thorium dioxide) is commonly associated with liver neoplasm. The most common liver neoplasm associated with thorium exposure Angiosarcoma of the liver Cholangiocarcinoma Hepatocellular carcinoma","pyqMatches":[{"year":"2012","no":491,"q":"Thorium induced tumor","o":["Angiosarcoma of liver","Renal cell carcinoma","Lymphoma","Astrocytoma"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6744, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 586, '{"id":6744,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":586,"q":"Most common malignancy of fallopian tube","o":["SCC","Serous CA","Teratoma","Chorioca"],"a":1,"e":"Answer- B. Serous CA Serous - 49.5% - 83.3%","pyqMatches":[{"year":"2012","no":505,"q":"Most common malignancy of fallopian tube","o":["SCC","Serous CA","Teratoma","Chorioca"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6745, 'Pathology', 'Hematology', 'Easy', 'Pathology', 587, '{"id":6745,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":587,"q":"Warthin finkeldey cells are seen in","o":["Measles","Rubella","Rabies","Typhoid"],"a":0,"e":"Answer: A. Measles Multinucleated cells like Warthin Finkeldey are seen in Measles Measles virus infects by invasion of respiratory epithelium. Local multiplication leads to viremia (day 2-3), then spread to RE system. Two types of Multinucleated giant cells in both epidermis & oral epithelium by 7-11 days. Warthin Finkeldey cells of reticuloendothelial system Epithelial giant cells of respiratory & other epithelia. Warthin–Finkeldey cell: Type of giant multinucleate cell found in hyperplastic lymph nodes early in the course of measles Under the light microscope, these cells consist of a large, grape-like cluster of nuclei. Also with HIV-infected individuals and Kimura disease . Rarely in neoplastic (e.g. lymphoma) & non-neoplastic lymph node disorders. Unknown origin; Reports of staining with markers similar to follicular dendritic cells, including CD21.","pyqMatches":[{"year":"2018","no":34,"q":"Warthin finkeldey cells are seen in","o":["Measles","Rubella","Rabies","Typhoid"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6746, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 588, '{"id":6746,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":588,"q":"CD59 marker of which disease","o":["PNH","PTEN","BRR","Cowden syndrome"],"a":0,"e":"Answer: A. Paroxysmal nocturnal hemoglobinuria (PNH) Paroxysmal nocturnal hemoglobinuria (PNH) is a disease, due to acquired mutations in “Phosphatidylinositol GlycanComplementation Group A” gene (PIGA).. Associated with deficiency of glycosylphosphatidylinositol (GPI) anchor proteins along with absence of external surface membrane proteins attaching to it. CD55 (DAF) and CD59 (MIRL) are two such complement defence proteins CD59 deficiency: Common finding in RBCs & WBCs of patients with chronic hemolysis suffering from PNH Diagnosis: The definite diagnosis based on demonstration of a substantial proportion of patient’s RBC having increased susceptibility to complement (C), due to the deficiency on their surface of proteins (particularly CD59 & CD55)","pyqMatches":[{"year":"2018","no":35,"q":"CD59 marker of which disease","o":["PNH","PTEN","BRR","Cowden syndrome"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6747, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 589, '{"id":6747,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":589,"q":"Opsonin is","o":["C3a","C3b","C5a","C6"],"a":1,"e":"Answer: B. C3b The process of coating a foreign particle targeting & preparing it for phagocytosis process is “Opsonization”. Substances involved are opsonins. Main opsonins from complement system is C3 Examples of opsonins include: Antibodies: IgG and IgA Components of the complement system: C3b, C4b, and iC3b Mannose Binding Lectin (MBL): Initiates the formation of C3b Membrane Attack Complex (MAC) Includes C5b, C6, C7, C8 & polymeric C9 Opsonization & complement proteins: Mainly C3b, iC3b & C4b C3: Most abundant protein of all complementary proteins, Cleaves into C3a and C3b C3a - Binds and activates mast cells & basophils, release histamine. C3b - Most critical component in both classical & alternative pathway C3b attaches to bacterial surfaces for opsonization by phagocytes","pyqMatches":[{"year":"2018","no":36,"q":"Opsonin is","o":["C3a","C3b","C5a","C6"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6748, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 590, '{"id":6748,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":590,"q":"Bernard–Soulier syndrome due to deficiency of","o":["Gp 2b/3a","Gp 1b","vWf","TNF"],"a":1,"e":"Answer: B. Gp 1b Bernard–Soulier syndrome (BSS) / Hemorrhagic Parous Thrombocytic Dystrophy Rare autosomal recessive coagulopathy Causes a deficiency of glycoprotein 1b (Gp1b), receptor for von Willebrand factor.","pyqMatches":[{"year":"2018","no":37,"q":"Bernard–Soulier syndrome due to deficiency of","o":["Gp 2b/3a","Gp 1b","vWf","TNF"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6749, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 591, '{"id":6749,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":591,"q":"Cowden syndrome","o":["P53","PTEN","Rb","Ras"],"a":1,"e":"Answer: B. PTEN “Phosphatase and Tensin” homolog (PTEN)- protein in humans encoded by the PTEN gene. Gene mutations promotes development of cancers. Cowden’s disease / Multiple Hamartoma Syndrome - Part of PTEN hamartoma tumor syndrome An autosomal dominant syndrome Trichilemmomas - Numerous tumors of hair follicles in face Multiple hamartomatous polyps in GI tract. Very high risk of breast & thyroid carcinoma Treatment: B/L mastectomies recommended Contraindicated are mammography & other radiation exposure of breast tissue","pyqMatches":[{"year":"2018","no":38,"q":"Cowden syndrome","o":["P53","PTEN","Rb","Ras"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6750, 'Pathology', 'Cell Injury & Adaptation', 'Easy', 'Pathology', 592, '{"id":6750,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Easy","source":"Pathology","sourceNo":592,"q":"Chromosome involved in myotonic dystrophy is","o":["Chromosome 19","Chromosome 20","Chromosome 21","Chromosome 22"],"a":0,"e":"Answer: A - Chromosome 19 Myotonic dystrophy is transmitted by mutation in an ''unstable trinucleotide repeat sequence'' in gene 19q 133. Features: An autosomal dominant disorder Most common adult muscular dystrophy Characteristics feature: Myopathy is distal (in contrast to other myopathies - mostly proximal). Muscle atrophy selectively involves type I fibres only Appears by 5 years, causes a slow relaxation of hand grip following a forced voluntary closure.","pyqMatches":[{"year":"2018","no":39,"q":"Chromosome involved in myotonic dystrophy is","o":["Chromosome 19","Chromosome 20","Chromosome 21","Chromosome 22"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6751, 'Pathology', 'Hemodynamics', 'Easy', 'Pathology', 593, '{"id":6751,"subject":"Pathology","chapter":"Hemodynamics","difficulty":"Easy","source":"Pathology","sourceNo":593,"q":"TRALI occurs within how many hours of transfusion?","o":["48 Hrs","72 Hrs","6 Hrs","12 Hrs"],"a":2,"e":"Answer: C - 6 Hrs Transfusion-Related Acute Lung Injury (TRALI) - Syndrome characterized by acute respiratory distress following transfusion. Symptoms: Typically develop during, or within 6 hours of transfusion. Rapid onset of dyspnea & tachypnea. Associated fever, cyanosis, & hypotension. Clinical examination: Reveals respiratory distress. Pulmo​nary crackles may be present with no signs of CHF or volume overload. CXR - Evidence of B/L pulmonary edema unrelated to CHF (non- cardiogenic pulmonary edema), Bilat​eral patchy infiltrates rapidly progressing to complete \"white out\" indistinguishable from Acute Respi​ratory Distress Syndrome (ARDS).","pyqMatches":[{"year":"2018","no":40,"q":"TRALI occurs within how many hours of transfusion?","o":["48 Hrs","72 Hrs","6 Hrs","12 Hrs"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6752, 'Pathology', 'Hemodynamics', 'Easy', 'Pathology', 594, '{"id":6752,"subject":"Pathology","chapter":"Hemodynamics","difficulty":"Easy","source":"Pathology","sourceNo":594,"q":"Kidney responds to shock by","o":["Decreases renal blood flow","Increases afferent arteriole resistance","GFR remains unaltered","Perfusion of kidney increases"],"a":1,"e":"Answer: B - Increases afferent arteriole resistance Kidney utilizes the following mechanisms as a response to shock: Release of aldosterone from hypoxic kidney Release of ADH due to decreased effective circulating blood volume. Reduced GFR due to arteriole constriction Tissue fluid shift into plasma due to lowered hydrostatic pressure (Hypotension)","pyqMatches":[{"year":"2018","no":41,"q":"Kidney responds to shock by","o":["Decreases renal blood flow","Increases afferent arteriole resistance","GFR remains unaltered","Perfusion of kidney increases"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6753, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 595, '{"id":6753,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":595,"q":"Which of the following is epithelial tumor of stomach?","o":["Carcinoid","Lymphoma","GIST","Gastric adenocarcinoma"],"a":3,"e":"Answer: D - Gastric adenocarcinoma Malignant epithelial tumor originating from glandular epithelium of gastric mucosa. Aggressively invade the gastric wall. Lauren classification: Two types of gastric adenocarcinoma are present. Intestinal type Diffuse type Intestinal type - Irregular tubular structures Diffuse type - Mucinous & colloidal “Leather-bottle stomach”","pyqMatches":[{"year":"2018","no":42,"q":"Which of the following is epithelial tumor of stomach?","o":["Carcinoid","Lymphoma","GIST","Gastric adenocarcinoma"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6754, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 596, '{"id":6754,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":596,"q":"Identify an X linked disorder?","o":["Color blindness","Thalassemia","Azoospermia","Retinitis Pigmentosa"],"a":0,"e":"Answer: A - Color blindness Hereditary color blindness/ Achromatopsia The ability to appreciate one or more primary color is defective (anomalous) or absent (anopia) Due to mutations in X chromosome Red & green pigment cones coded by X chromosome; Blue coded on chromosome 7 More common in males than females Acquired - (Optic nerve/ macular damage) Ishihara chart - Test red/ green color blindness - Farnsworth 100 hue test Other s: Azoospermia&Retinitis Pigmentosa - Y-chromosome linked disorder Thalassemia - Inherited (Autosomal recessive pattern) blood disorders characterized by abnormal hemoglobin production. Genes in Chromosome 11 and 16 involved.","pyqMatches":[{"year":"2018","no":43,"q":"Identify an X linked disorder?","o":["Color blindness","Thalassemia","Azoospermia","Retinitis Pigmentosa"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6755, 'Pathology', 'Hematology', 'Easy', 'Pathology', 597, '{"id":6755,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":597,"q":"H And L variety seen in","o":["Mixed cellularity hodgkin","Lymphocyte depleted","Lymphocyte predominance","Nodular sclerosis"],"a":2,"e":"Answer: C - Lymphocyte predominance Hodgkin lymphoma (HL) - common “Malignant Lymphomas” 2 entities: Classical HL (cHL) Nodular Lymphocyte–predominant HL (NLPHL). Cells : Classical HL - Hodgkin and Reed/Sternberg (HRS) cells Nodular Lymphocyte predominant HL - Lymphocytic & Histiocytic (L&H) cells","pyqMatches":[{"year":"2018","no":44,"q":"H And L variety seen in","o":["Mixed cellularity hodgkin","Lymphocyte depleted","Lymphocyte predominance","Nodular sclerosis"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6756, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 598, '{"id":6756,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":598,"q":"Stellate granuloma seen in","o":["Sarcoidosis","Cat scratch disease","Cryptococcosis","Histoplasmosis"],"a":1,"e":"Answer: B - Cat scratch disease Bacterial infection causes by Bartonella henselae Acquired infected cat/kitten scratch Histology: Characterized by granulomatous inflammation of lymph nodes. Skin lesion demonstrates a circumscribed focus of necrosis Regional lymph nodes demonstrate follicular hyperplasia with central stellate necrosis with neutrophils, surrounded by palisading histiocytes (suppurative granulomas) & sinuses packed with monocytoid B cells, usually without perifollicular and intrafollicular epithelioid cells.","pyqMatches":[{"year":"2018","no":45,"q":"Stellate granuloma seen in","o":["Sarcoidosis","Cat scratch disease","Cryptococcosis","Histoplasmosis"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6757, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 599, '{"id":6757,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":599,"q":"Which best explains “Flipping effect”?","o":["LDH 1 > LDH 2","LDH2 > LDH1","LDH 2 > LDH 3","LDH 3 > LDH 2"],"a":0,"e":"Answer: A - LDH 1 > LDH 2 Lactate dehydrogenase, tetrameric enzyme with 4 subunits, 4 Subunits with 2 isoforms - H isoform (Heart) & M isoform (Muscle) Heart & RBCs - LDH-1 (4H); Reticuloendothelial system - LDH-2 (3H1M) Lungs - LDH-3 (2H2M) Kidneys, placenta, & pancreas - LDH-4 (1H3M) Liver & striated muscle - LDH-5 (4M) Uses: LDH levels are more in RBC Helpful in assessment of Hemolysis / Tissue breakdown Flipping effect: Usually LDH 2 in predominant in serum & LDH 1 is predominant in heart Higher levels of LDH 1 than LDH 2 (Flipped pattern) is suggestive of myocardial infarction Damaged cardiac tissues release LDH 1 into bloodstream.","pyqMatches":[{"year":"2018","no":46,"q":"Which best explains “Flipping effect”?","o":["LDH 1 > LDH 2","LDH2 > LDH1","LDH 2 > LDH 3","LDH 3 > LDH 2"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6758, 'Pathology', 'Immunopathology', 'Moderate', 'Pathology', 600, '{"id":6758,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Moderate","source":"Pathology","sourceNo":600,"q":"Nude mice is not resistant to xenograft due to absence of","o":["B cell","T cell","Both b and t cell","None"],"a":1,"e":"Answer: B - T cell Nude mice lacks “Thymus” & cannot generate mature T lymphocytes. Absence of T-lymphocytes makes it unable to mount adaptive immune responsesrequiring CD4, helper T cells, CD8 and cytotoxic T cells. Adaptive immune responses that remain unresponsive to nude mice include: Antibody formation (CD4 + helper T cells) Cell-mediated immune responses (CD4+ and/or CD8+ T cells) Delayed-type hypersensitivity responses (CD4+ T cells) Killing of virus-infected or malignant cells (CD8 + cytotoxic T cells) Graft rejection (both CD4+ & CD8+ T cells) Uses: Laboratory study animal - Insights into immune system, leukemia, solid tumors, AIDS & other immune deficiency diseases. Absence of functioning T cells prevents them rejecting the allografts & Xenografts.","pyqMatches":[{"year":"2018","no":47,"q":"Nude mice is not resistant to xenograft due to absence of","o":["B cell","T cell","Both b and t cell","None"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6759, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 601, '{"id":6759,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":601,"q":"Anaplasia is","o":["Changing one type of epithelium to another","Nuclear chromatin","Lack of differentiation","Morphological changes"],"a":2,"e":"Answer: C - Lack of differentiation Refers to a lack of differentiation in neoplastic cells. Well-differentiated tumors resemble their tissue of origin Poorly-differentiated or undifferentiated (anaplastic) tumor cells appear primitive and lack specialization along any particular cell line.","pyqMatches":[{"year":"2018","no":48,"q":"Anaplasia is","o":["Changing one type of epithelium to another","Nuclear chromatin","Lack of differentiation","Morphological changes"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6760, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 602, '{"id":6760,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":602,"q":"Which level of prolactin definitely suggest prolactinoma?","o":["300 ng/ml","150 ng/ml","200 ng/ml","100 ng/ml"],"a":2,"e":"Answer: C - 200 ng/ml Prolactinomas are the most common type of hyperfunctioning pituitary adenoma. Benign tumors of pituitary gland producing prolactin. Hyperprolactinemia causes amenorrhea, galactorrhea, loss of libido, and infertility. Because many manifestations of hyperprolactinemia (e.g., amenorrhea) are more obvious in premenopausal women than in men or postmenopausal women, prolactinomas usually are diagnosed at an earlier stage in women of reproductive age than in other persons so affected. Higher blood prolactin concentrations are seen. mild elevations of serum prolactin (less than 200 μg/L) in a patient with a pituitary adenoma do not necessarily indicate a prolactin- secreting neoplasm.","pyqMatches":[{"year":"2018","no":49,"q":"Which level of prolactin definitely suggest prolactinoma?","o":["300 ng/ml","150 ng/ml","200 ng/ml","100 ng/ml"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6761, 'Pathology', 'Organ System Pathology', 'Easy', 'Pathology', 603, '{"id":6761,"subject":"Pathology","chapter":"Organ System Pathology","difficulty":"Easy","source":"Pathology","sourceNo":603,"q":"Laxative abuse causes which of the following renal stones ?","o":["Uric acid","Ammonium urate","Struvite","Ca oxalate"],"a":1,"e":"Answer: B - Ammonium urate Based on the chemical nature two types of kidney stones: Calcium oxalate (majority). Others include Uric acid, Struvite (Infected stones), and Cystine stones (rare hereditary metabolic disorder Characteristic stone formation in laxative abuse: Laxative abuse acts a factor in kidney stone formation. Laxative abuse causes potassium loss As a compensation mechanism kidney produces large amount of ammonium. Resulting in formation of uncommon stone type - ammonium acid urate.","pyqMatches":[{"year":"2018","no":50,"q":"Laxative abuse causes which of the following renal stones ?","o":["Uric acid","Ammonium urate","Struvite","Ca oxalate"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6762, 'Pathology', 'Hematology', 'Easy', 'Pathology', 604, '{"id":6762,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":604,"q":"Which of the following can result in dactylitis","o":["Hemophilia","Von willebrand disease 1","Measles","Sickle Cell Anemia"],"a":3,"e":"Answer: D - Sickle Cell Anemia Dactylitis (Hand-Foot Syndrome) is seen in sickle cell anemia Severe pain affecting the bones of hands, feet, or both. Often 1st symptom of sickle cell anemia in babies.","pyqMatches":[{"year":"2018","no":51,"q":"Which of the following can result in dactylitis","o":["Hemophilia","Von willebrand disease 1","Measles","Sickle Cell Anemia"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6763, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 605, '{"id":6763,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":605,"q":"Which chromosome is responsible for the production of MIF?","o":["Chromosome 16","Chromosome 22","X Chromosome","Y chromosome"],"a":3,"e":"Answer: D - Y Chromosome Anti-Mullerian Hormone (AMH) / Mullerian Inhibiting Factor (MIF); Mullerian-inhibiting Hormone (MIH) / Mullerian-inhibiting Substance (MIS). AMH - Downstream genes regulated by SRY pathway SRY - Gene in “Sex determining region” - short arm of Y chromosome - Testis determining factor. Secreted by Sertoli cells of the testes. The production of AMH is controlled by two autosomal gene loci. Hormone code Receptor code. Glycoprotein hormone Related to inhibin & activin Member of the transforming growth factor-β (TGF-β) Key roles are in growth differentiation and folliculogenesis.","pyqMatches":[{"year":"2018","no":52,"q":"Which chromosome is responsible for the production of MIF?","o":["Chromosome 16","Chromosome 22","X Chromosome","Y chromosome"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6764, 'Pathology', 'Infectious Diseases', 'Moderate', 'Pathology', 606, '{"id":6764,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Moderate","source":"Pathology","sourceNo":606,"q":"Which of the following condition is NOT caused by Parvovirus B19?","o":["Roseola infantum","Aplastic anemia in sickle cell disease","Fetal hydrops","Erythema infectiosum"],"a":0,"e":"Answer: A. Roseola infantum Primary infection by parvovirus B19 often produces an acute, severe, and sometimes fatal anemia manifested as a rapid fall in red blood cell count and hemoglobin. These patients may present initially with no clinical symptoms other than fever; this is commonly referred to as aplastic crisis. Erythema infectiosum (also referred to as fifth disease or academy rash) is a more common disease that is clearly attributable to parvovirus B19. Active transplacental transmission of parvovirus B19 can occur during primary infections in the first 20 weeks of pregnancy, sometimes resulting in stillbirth of fetuses that are profoundly anemic. The progress can be so severe that hypoxic damage to the heart, liver, and other tissues leads to extensive edema (hydrops fetalis).","pyqMatches":[{"year":"2018","no":286,"q":"Which of the following condition is NOT caused by Parvovirus B19?","o":["Roseola infantum","Aplastic anemia in sickle cell disease","Fetal hydrops","Erythema infectiosum"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6765, 'Pathology', 'Hematology', 'Easy', 'Pathology', 607, '{"id":6765,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":607,"q":"Which is true regarding ataxia telangiectasia:","o":["Increase in AFP","Increases the risk of squamous cell carcinoma","Autosomal dominant","None of above"],"a":0,"e":"Answer: A - Increase in AFP Increase in alpha-fetoprotein is observed in Ataxia telangiectasia Ataxia-telangiectasia / Ataxia-telangiectasia syndrome / Louis-Bar syndrome Rare, neurodegenerative, autosomal recessive disorder causing severe disability. Ataxia refers to poor coordination; Telangiectasia refers to small dilated blood vessels. Parts affected: Cerebellum - movement & coordination difficulties Immune system - Predisposing to infections. Genetic repair system - Preventing process for repairing DNA - Cancer risk Features: Increased incidence of lymphoma & Leukemia Increased alpha-Fetoprotein levels Oculomotor apraxia (difficulty in coordination between head & eye movements) Dysarthria","pyqMatches":[{"year":"2018","no":290,"q":"Which is true regarding ataxia telangiectasia:","o":["Increase in AFP","Increases the risk of squamous cell carcinoma","Autosomal dominant","None of above"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6766, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 608, '{"id":6766,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":608,"q":"Term pathology refers to:","o":["Work","Function","Details","Explains"],"a":0,"e":"Ans. A. Work Pathology is the medical term for the way a disease works. The science of the causes and effects of diseases, especially the branch of medicine that deals with the laboratory examination of samples of body tissue for diagnostic or forensic purposes.","pyqMatches":[{"year":"2018","no":250,"q":"Term pathology refers to:","o":["Work","Function","Details","Explains"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6767, 'Pathology', 'Genetic Disorders', 'Moderate', 'Pathology', 609, '{"id":6767,"subject":"Pathology","chapter":"Genetic Disorders","difficulty":"Moderate","source":"Pathology","sourceNo":609,"q":"Leiden thrombophilia is caused by mutational deficiency of which of the following factors?","o":["Factor V","Factor VII","Factor IX","Factor X"],"a":0,"e":"Ans. A. Factor V Factor V Leiden thrombophilia is an inherited disorder of blood clotting. Factor V Leiden is the name of a specific mutation (genetic alteration) that results in thrombophilia, or an increased tendency to form abnormal blood clots in blood vessels. Factor V Leiden is the most common inherited form of thrombophilia.","pyqMatches":[{"year":"2018","no":293,"q":"Leiden thrombophilia is caused by mutational deficiency of which of the following factors?","o":["Factor V","Factor VII","Factor IX","Factor X"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6768, 'Pathology', 'Hematology', 'Moderate', 'Pathology', 610, '{"id":6768,"subject":"Pathology","chapter":"Hematology","difficulty":"Moderate","source":"Pathology","sourceNo":610,"q":"A boy presented with multiple non suppurative osteomyelitis with sickle cell anaemia. What will be the causative organism?","o":["Salmonella","S. aureus","H. influenzae","Enterobacter species"],"a":0,"e":"Ans. A. Salmonella Following are the various micro -organism involved in osteomyelitis Age group Most common organisms Newborns (younger than 4 mo) S. aureus, Enterobacter species, and group A and B Streptococcus species Children (aged 4 mo to 4 y) S. aureus, group A Streptococcus species, Haemophilus influenzae, and Enterobacter species Children, adolescents (aged 4 y to adult) S. aureus (80%), group A Streptococcus species, H. influenzae, and Enterobacter species Adult S. aureus and occasionally Enterobacter or Streptococcus species Sickle cell anemia patients Salmonella species are most common in patients with sickle cell disease","pyqMatches":[{"year":"2018","no":249,"q":"A boy presented with multiple non suppurative osteomyelitis with sickle cell anaemia. What will be the causative organism?","o":["Salmonella","S. aureus","H. influenzae","Enterobacter species"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6769, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 611, '{"id":6769,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":611,"q":"Positive acid schiff macrophages seen in ?","o":["Whipples disease","Crohns disease","AIDS","None of the above"],"a":0,"e":"Answer : A> Whipples disease. The traditional laboratory diagnosis is based on light microscopy, which shows diastase-resistant, periodic acid-Schiff (PAS)-positive, non-acid-fast granules in ..... The distinction could be made by acid-fast staining, which is positive for patients infected with M. avium and negative for those with Whipple''s disease.","pyqMatches":[{"year":"2018","no":248,"q":"Positive acid schiff macrophages seen in ?","o":["Whipples disease","Crohns disease","AIDS","None of the above"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6770, 'Pathology', 'Hemodynamics', 'Easy', 'Pathology', 612, '{"id":6770,"subject":"Pathology","chapter":"Hemodynamics","difficulty":"Easy","source":"Pathology","sourceNo":612,"q":"What is the cause of myocardial shock other than MI ?","o":["acute mitral regurgitation","ventricular septal rupture","isolated right ventricular shock","all of the above"],"a":3,"e":"Answer : D> All of the above Left ventricular dysfunction (LVD) - Most frequent cause of cardiogenic shock Followed by, Acute mitral valve regurgitation Ventricular septal defect Isolated right ventricular shock Tamponade/ cardiac rupture","pyqMatches":[{"year":"2017","no":287,"q":"What is the cause of myocardial shock other than MI ?","o":["acute mitral regurgitation","ventricular septal rupture","isolated right ventricular shock","all of the above"],"a":3,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":246,"q":"What is the cause of myocardial shock other than MI ?","o":["acute mitral regurgitation","ventricular septal rupture","isolated right ventricular shock","all of the above"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6771, 'Pathology', 'Inflammation', 'Moderate', 'Pathology', 613, '{"id":6771,"subject":"Pathology","chapter":"Inflammation","difficulty":"Moderate","source":"Pathology","sourceNo":613,"q":"WHICH IS NOT CORRECT:","o":["MRI needed to access haemorrhage","GCS assessment helps in prognosis","Haematoma must be operated","all of the above"],"a":2,"e":"Answer- C. Haematoma must be operated Treatment of hematoma depends on the location, symptoms, and the clinical situation. Some may require no treatment at all while others may be deemed a medical emergency. Simple therapies at home may be utilized in treating superficial (under the skin) hematomas. Most injuries and bruises can be treated with resting, icing, compression, and elevating the area. This is remembered by the acronym RICE. These measures usually help to reduce inflammation and diminish its symptoms. Rest Ice (Apply the ice or cold pack for 20 minutes at a time, 4 to 8 times a day.) Compress (Compression can be achieved by using elastic bandages.) Elevate (Elevation of the injured area above the level of the heart is recommended.) Medical treatment for a hematoma For certain small and symptom-free hematomas no medical treatment may be necessary. On the other hand, symptomatic hematomas or those located in certain locations sometimes require medical or surgical treatment. Even though no specific mediation is available for the treatment of hematomas, management of any related symptoms can be achieved by medications. For example, pain from a hematoma can be treated with pain medications such as acetaminophen (Tylenol). Surgical drainage is a common method of treatment for certain hematomas.","pyqMatches":[{"year":"2017","no":285,"q":"WHICH IS NOT CORRECT:","o":["MRI needed to access haemorrhage","GCS assessment helps in prognosis","Haematoma must be operated","all of the above"],"a":2,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":244,"q":"WHICH IS NOT CORRECT:","o":["MRI needed to access haemorrhage","GCS assessment helps in prognosis","Haematoma must be operated","all of the above"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6772, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 614, '{"id":6772,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":614,"q":"Genital warts are caused by which virus?","o":["Herpes simplex","Human papilloma","Cytomegalovirus","Varicella zoster"],"a":1,"e":"Ans. B.Human papilloma Genital warts are soft growths that appear on the genitals. Genital warts are a sexually transmitted infection (STI) caused by certain strains of the human papillomavirus (HPV). These skin growths can cause pain, discomfort, and itching.","pyqMatches":[{"year":"2018","no":278,"q":"Genital warts are caused by which virus?","o":["Herpes simplex","Human papilloma","Cytomegalovirus","Varicella zoster"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6773, 'Pathology', 'Miscellaneous', 'Easy', 'Pathology', 615, '{"id":6773,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pathology","sourceNo":615,"q":"Which metal results in “Saturnine gout” formation?","o":["Cadmium","Lead","Beryllium","Mercury"],"a":1,"e":"Answer: B. Lead One manifestation of chronic lead toxicity is the rheumatologic entity known as saturnine gout. Illicitly distilled beverages may inadvertently contain harmful toxins, like metallic lead. Lead has been known to play a role in purine metabolism & renal insufficiency","pyqMatches":[{"year":"2018","no":241,"q":"Which metal results in “Saturnine gout” formation?","o":["Cadmium","Lead","Beryllium","Mercury"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6774, 'Pathology', 'Hematology', 'Easy', 'Pathology', 616, '{"id":6774,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":616,"q":"Reed sternberg cells are found in","o":["Hodgkin''s disease","Sickle cell anaemia","Thalassemia","CML"],"a":0,"e":"Reed Sternberg cells are you derived from B lymphocytes, classically considered crippled germinal center B cells, Seen against a sea of B cells which give the tissue a moth-eaten appearance. They are large and are either multinucleated or have a bibbed nucleus (thus resembling an \"owl''s eye\" appearance) with prominent eosinophilic inclusion-like nucleoli. They are CD30 and CD15 positive, usually negative for CD20 and CD45. The presence of these cells is necessary for the diagnosis of Hodgkin''s lymphoma - the absence of Reed-Sternberg cells has very high negative predictive value. They can also be found in reactive lymphadenopathy (such as infectious mononucleosis, carbamazepine associated lymphadenopathy) and very often in other types of non-Hodgkin lymphomas.","pyqMatches":[{"year":"2017","no":278,"q":"Reed sternberg cells are found in","o":["Hodgkin''s disease","Sickle cell anaemia","Thalassemia","CML"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":263,"q":"Reed sternberg cells are found in","o":["Hodgkin''s disease","Sickle cell anaemia","Thalassemia","CML"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6775, 'Pathology', 'Hematology', 'Easy', 'Pathology', 617, '{"id":6775,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":617,"q":"Marked bleeding is seen in which of following conditions?","o":["VMA disease","Haemophilia A","Haemophilia B","ALL"],"a":3,"e":"Answer: D. ALL Bleeding disorders can be inherited or acquired. Inherited disorders are passed down through genetics. Acquired disorders can develop or spontaneously occur later in life. Some bleeding disorders can result in severe bleeding following an accident or injury. In other disorders, heavy bleeding can happen suddenly and for no reason. There are numerous different bleeding disorders, but the following are the most common ones: Hemophilia A and B are conditions that occur when there are low levels of clotting factors in your blood. It causes heavy or unusual bleeding into the joints. Though hemophilia is rare, it can have life- threatening complications. Factor II, V, VII, X, or XII deficiencies are bleeding disorders related to blood clotting problems or abnormal bleeding problems. von Willebrand''s disease is the most common inherited bleeding disorder. It develops when the blood lacks von Willebrand factor, which helps the blood to clot.","pyqMatches":[{"year":"2017","no":277,"q":"Marked bleeding is seen in which of following conditions?","o":["VMA disease","Haemophilia A","Haemophilia B","ALL"],"a":3,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":262,"q":"Marked bleeding is seen in which of following conditions?","o":["VMA disease","Haemophilia A","Haemophilia B","ALL"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6776, 'Pathology', 'Hematology', 'Easy', 'Pathology', 618, '{"id":6776,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":618,"q":"Which of the following true regarding Hemophilia A","o":["Serum levels of factor VIII are decreased","Deficiency of factor IX","PT increased","FIT decreased"],"a":0,"e":"Answer: A. Serum levels of factor VIII are decreased Hemophilia is an X linked disorder of coagulation caused by the deficiency in a circulating plasma protein. Hemophilia A is caused by the deficiency of factor VIII, and hemophilia B is caused by the deficiency of factor IX. It is PTT which is affected (increased) and not PT (unaffected). Factor VIII is involved in the intrinsic pathway which is measured by PTT and not in extrinsic pathway which is measured as PT. Bleeding is the common manifestation of hemophilia and the common bleeding manifestations are hemarthoses, hematomas, mucocutaneous bleeding, intracranial bleeding, hematuria and pseudotumor.","pyqMatches":[{"year":"2018","no":261,"q":"Which of the following true regarding Hemophilia A","o":["Serum levels of factor VIII are decreased","Deficiency of factor IX","PT increased","FIT decreased"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6777, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 619, '{"id":6777,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":619,"q":"Which of the following is seen in seropositive rheumatoid arthritis?","o":["Multiple joints affected","Symmetrical joint symptoms","Joint pain and swelling","All"],"a":3,"e":"Answer: D. All Positive for Rheumatoid factor in blood is seropositivity. Patients with positive rheumatoid factor usually present with symptoms like Joint deformities & disability Symmetrical involvement of joints Inflammation Swelling and painful in multiple joints, especially of hands and feet. Morning stiffness (short term) Development of firm lumps near joints - “Rheumatoid nodules” Deterioration of bone & cartilage (X- ray findings)","pyqMatches":[{"year":"2018","no":266,"q":"Which of the following is seen in seropositive rheumatoid arthritis?","o":["Multiple joints affected","Symmetrical joint symptoms","Joint pain and swelling","All"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6778, 'Pathology', 'Neoplasia', 'Moderate', 'Pathology', 620, '{"id":6778,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Moderate","source":"Pathology","sourceNo":620,"q":"Which of the following is not seen in Anterior mediastinum","o":["Thyroid tumour","Thymoma","Lymphoma","Neurogenic tumor"],"a":3,"e":"Answer: D. Neurogenic tumor The anterior mediastinum is the portion of the mediastinum anterior to the pericardium and below the thoracic plane. It forms the anterior part of the inferior mediastinum contains the thymus, lymph nodes, and may contain the portions of a retrosternal thyroid. Mediastinal Tumors and Other Masses Superior Mediastinum Anterior Mediastinum Posterior Mediastinum Middle Mediastinum Lymphoma Thymoma Neurogenic tumors Bronchogenic cyst Thymoma Teratoma Lymphoma Pericardial cyst Thyroid lesions Lymphoma Gastroenteric hernia Lymphoma Metastatic carcinoma Thyroid lesions Parathyroid tumors Parathyroid tumors","pyqMatches":[{"year":"2018","no":267,"q":"Which of the following is not seen in Anterior mediastinum","o":["Thyroid tumour","Thymoma","Lymphoma","Neurogenic tumor"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6779, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 621, '{"id":6779,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":621,"q":"Struvite stone is caused by which metal?","o":["Magnesium","Calcium","sodium & potassium","both (a) & (b)"],"a":0,"e":"Ans. A. Magnesium Struvite, a crystalline substance is composed of magnesium ammonium phosphate (MgNH4PO4 · 6H2O). Struvite urinary stones have also been referred to as “infection stones” and “triple phosphate” stones. Struvite stones can be caused by alkaline urine, steroid therapy, abnormal retention of urine, a urinary tract infection, or another disorder of the urinary tract. There are five primary types of commonly encountered urinary stones, i.e., calcium oxalate, calcium phosphate, magnesium ammonium phosphate, uric acid, and cystine.","pyqMatches":[{"year":"2018","no":268,"q":"Struvite stone is caused by which metal?","o":["Magnesium","Calcium","sodium & potassium","both (a) & (b)"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6780, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 622, '{"id":6780,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":622,"q":"Which of the following statements about Graves disease is false?","o":["Results in hyperthyroidism","Autoimmune disorder","Common in Male","Referred as Toxic diffuse goitre"],"a":2,"e":"Ans. C - Common in male Graves'' disease: Autoimmune system disorder Both men and women get affected; Yet, 10 times more common in women than men Affects younger women < 40 years Results in overproduction of thyroid hormones (hyperthyroidism). Signs and symptoms: Anxiety Irritability Heat sensitivity Increased perspiration/ warm and moist skin Weight loss Goiter (Glandular enlargement) Menstrual cycle changes Erectile dysfunction/ reduced libido Graves Ophthalmopathy - Bulging eyes - Exophthalmos Graves dermopathy - Thick, red skin on shins / top of feet. Antibody for graves disease - Thyrotropin receptor antibody (TRAb) acts on the regulatory pituitary hormone interfering the normal secretion of thyroxine. TRAb overrides normal regulation causing an overproduction of thyroid hormones (hyperthyroidism).","pyqMatches":[{"year":"2018","no":269,"q":"Which of the following statements about Graves disease is false?","o":["Results in hyperthyroidism","Autoimmune disorder","Common in Male","Referred as Toxic diffuse goitre"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6781, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 623, '{"id":6781,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":623,"q":"Which of the following is false about Alzheimer''s disease?","o":["One in 10 people age 65 and older has Alzheimer’s disease","Alzheimer’s disease is curable","Cause dementia","All of the above"],"a":1,"e":"Ans. B. Alzheimer’s disease is curable Alzheimer''s disease Also called: senile dementia. A progressive disease that destroys memory and other important mental functions. Memory loss and confusion are the main symptoms. Currently, there is no cure for Alzheimer''s. But drug and non-drug treatments may help with both cognitive and behavioral symptoms. The treatments available for Alzheimer’s do not slow or stop the progression of the disease, but they may help with the symptoms for a time. There are three cholinesterase inhibitors to treat Alzheimer’s: Donepezil (Aricept) Rivastigmine (Exelon) Galantamine (Reminyl) People may experience: Cognitive: mental decline, difficulty thinking and understanding, confusion in the evening hours, delusion, disorientation, forgetfulness, making things up, mental confusion, difficulty concentrating, inability to create new memories, inability to do simple maths, or inability to recognise common things Behavioural: aggression, agitation, difficulty with self care, irritability, meaningless repetition of own words, personality changes, restlessness, lack of restraint, or wandering and getting lost Mood: anger, apathy, general discontent, loneliness, or mood swings Psychological: depression, hallucination, or paranoia Also common: behavioral symptoms, inability to combine muscle movements, jumbled speech, or loss of appetite","pyqMatches":[{"year":"2018","no":271,"q":"Which of the following is false about Alzheimer''s disease?","o":["One in 10 people age 65 and older has Alzheimer’s disease","Alzheimer’s disease is curable","Cause dementia","All of the above"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6782, 'Pathology', 'Infectious Diseases', 'Moderate', 'Pathology', 624, '{"id":6782,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Moderate","source":"Pathology","sourceNo":624,"q":"Which is not included in AIDS related complex?","o":["Ectopic pregnancy","Recurrent genital candidiasis","Generalised lymphadenopathy","Chronic diarrhea"],"a":0,"e":"Answer- A. Ectopic pregnancy HIV symptoms: AIDS related complex (ARC) It belongs to class B of HIV symptoms. The patients at this stage have various diseases that occur because the HI virus has weakened the immune system. The following HIV signs may have patients with ARC: Long-lasting diarrhea (over four weeks) Unintended heavy weight loss Long lasting fever Night sweats Bacterial infections caused by bacteria Bacterial blood poisoning (sepsis) Phthisis Herpes zoster Oral hairy leukoplakia (whitish changes on the lateral tongue border) Fungi caused by fungi HIV symptoms – Women: vaginal inflammation caused by fungi, malignant changes in the cervix","pyqMatches":[{"year":"2018","no":275,"q":"Which is not included in AIDS related complex?","o":["Ectopic pregnancy","Recurrent genital candidiasis","Generalised lymphadenopathy","Chronic diarrhea"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6783, 'Pathology', 'Immunopathology', 'Easy', 'Pathology', 625, '{"id":6783,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Easy","source":"Pathology","sourceNo":625,"q":"Which of the following are the risk factor for cutaneous lymphoma?","o":["Age","Gender","Weakened immune system","All"],"a":3,"e":"Answer:D . All Risk Factors for Lymphoma of the Skin Age Age is an important risk factor for this disease, with most cases occurring in people in their 50s and 60s. But some types of skin lymphoma can appear in younger people, even in children. Gender and race Most (but not all) types of skin lymphoma are more common in men than in women. Most also tend to be more common in African-Americans than in whites. The reasons for this are not known. Weakened immune systemSkin lymphomas may be more common in people with acquired immunodeficiency syndrome (AIDS), who have a weakened immune system. They may also be more common in people who have had an organ transplant such as a heart, kidney or liver transplant. These people must take drugs that suppress their immune system, which may raise the risk of skin lymphoma (or lymphomas in other parts of the body). Infections Infection with the human immunodeficiency virus (HIV), the virus that causes AIDS, may increase a person’s risk of skin lymphoma.","pyqMatches":[{"year":"2017","no":271,"q":"Which of the following are the risk factor for cutaneous lymphoma?","o":["Age","Gender","Weakened immune system","All"],"a":3,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":274,"q":"Which of the following are the risk factor for cutaneous lymphoma?","o":["Age","Gender","Weakened immune system","All"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6784, 'Pathology', 'Cell Injury & Adaptation', 'Hard', 'Pathology', 626, '{"id":6784,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Hard","source":"Pathology","sourceNo":626,"q":"A 30-year-old male came with complaints of swelling around the knee joint. Histopathological examination of the swelling demonstrated many giant cells interspersed with mononuclear cells. What is the probable diagnosis","o":["Osteosarcoma","Ewing''s sarcoma","Giant cell tumour","Chondrosarcoma"],"a":2,"e":"Correct ans: C GCTs are large and red-brown and often show cystic degeneration. They are composed of uniform oval mononuclear cells and scattered osteoclast-type giant cells containing 100 or more nuclei. Mitotic figures are typically frequent. Necrosis, hemorrhage, and reactive bone formation also are commonly present. Ref Robbin’s basics of pathology 9th edition page no.781","pyqMatches":[{"year":"2020","no":39,"q":"A 30-year-old male came with complaints of swelling around the knee joint. Histopathological examination of the swelling demonstrated many giant cells interspersed with mononuclear cells. What is the probable diagnosis","o":["Osteosarcoma","Ewing''s sarcoma","Giant cell tumour","Chondrosarcoma"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6785, 'Pathology', 'Neoplasia', 'Hard', 'Pathology', 627, '{"id":6785,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Hard","source":"Pathology","sourceNo":627,"q":"30 years old came with complaints of easy fatigability, exertional dyspnea, and weight loss. She also complains of frequent falls. physical examination revealed there was a bilateral decrease in vibration sense. Her hemoglobin levels were 8.2g%. She was treated with folate. Her anemia improved but neurological symptoms worsened. Which of the following is the most probable reason for her condition?","o":["Folate not absorbed","Unmasked pyridoxine deficiency","Deficiency of folate reductase in CNS","Folate therapy caused rapid use of Vit B12 stores aggravating symptoms"],"a":3,"e":"Ans: D. Folate therapy caused rapid use of Vit B12 stores aggravating symptoms Vitamin B12 is required for the recycling of tetrahydrofolate, the form of folate that is needed for DNA synthesis. In keeping with this relationship, the anemia of vitamin B12 deficiency is reversed with the administration of folate. By contrast, folate administration does not prevent and may, in fact, worsen the neurologic symptoms","pyqMatches":[{"year":"2020","no":40,"q":"30 years old came with complaints of easy fatigability, exertional dyspnea, and weight loss. She also complains of frequent falls. physical examination revealed there was a bilateral decrease in vibration sense. Her hemoglobin levels were 8.2g%. She was treated with folate. Her anemia improved but neurological symptoms worsened. Which of the following is the most probable reason for her condition?","o":["Folate not absorbed","Unmasked pyridoxine deficiency","Deficiency of folate reductase in CNS","Folate therapy caused rapid use of Vit B12 stores aggravating symptoms"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6786, 'Pathology', 'Immunopathology', 'Hard', 'Pathology', 628, '{"id":6786,"subject":"Pathology","chapter":"Immunopathology","difficulty":"Hard","source":"Pathology","sourceNo":628,"q":"A 30-year-old woman presents with thyroid swelling. On investigations, her TSH levels are found to be elevated. Postoperative reports showed lymphocytic infiltration and hurthle cells. A most probable diagnosis is?","o":["Graves disease","Hashimoto''s thyroiditis","Follicular carcinoma","Medullary carcinoma thyroid"],"a":1,"e":"Ans: B. Hashimoto''s thyroiditis Hashimoto thyroiditis is the most common cause of hypothyroidism which is characterized by gradual thyroid failure secondary to the autoimmune destruction of the thyroid gland. It is most prevalent between the ages of 45 and 65 years and is more common in women than in men, ultimately leading to a varying degree of fibrosis and thyroid enlargement. The thyroid usually is diffusely and symmetrically enlarged The cut surface is pale and gray-tan in appearance, and the tissue is firm and somewhat friable. Microscopic examination reveals the widespread infiltration of the parenchyma by a mononuclear inflammatory infiltrate containing small lymphocytes, plasma cells, and well-developed germinal centers. The thyroid follicles are atrophic and are lined in many areas by epithelial cells distinguished by the presence of abundant eosinophilic, granular cytoplasm, termed Hurthle, or oxyphil cells.","pyqMatches":[{"year":"2020","no":42,"q":"A 30-year-old woman presents with thyroid swelling. On investigations, her TSH levels are found to be elevated. Postoperative reports showed lymphocytic infiltration and hurthle cells. A most probable diagnosis is?","o":["Graves disease","Hashimoto''s thyroiditis","Follicular carcinoma","Medullary carcinoma thyroid"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6787, 'Pathology', 'Cell Injury & Adaptation', 'Hard', 'Pathology', 629, '{"id":6787,"subject":"Pathology","chapter":"Cell Injury & Adaptation","difficulty":"Hard","source":"Pathology","sourceNo":629,"q":"Which of the following will be seen on cardiac biopsy of a patient who had a post MI reperfusion injury?","o":["Waviness of fibres","Eosinophilic contraction bands","Neutrophils in cardiac cells","Swelling of cells"],"a":1,"e":"Ans: B. Eosinophilic contraction bands Microscopically, irreversibly damaged myocytes subject to reperfusion show contraction band necrosis; In this pathologic process, intense eosinophilic bands of hypercontracted sarcomeres are created by an influx of calcium across plasma membranes that enhances actin-myosin interactions.","pyqMatches":[{"year":"2020","no":43,"q":"Which of the following will be seen on cardiac biopsy of a patient who had a post MI reperfusion injury?","o":["Waviness of fibres","Eosinophilic contraction bands","Neutrophils in cardiac cells","Swelling of cells"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6788, 'Pathology', 'Miscellaneous', 'Hard', 'Pathology', 630, '{"id":6788,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Hard","source":"Pathology","sourceNo":630,"q":"Loss of foot process is classical in case of?","o":["Membranous glomerulitis","Segmental glomerulosclerosis","IgA nephropathy","Diabetic nephropathy"],"a":1,"e":"Ans: B. Segmental glomerulosclerosis Focal segmental glomerulosclerosis (FSGS) is characterized by sclerosis, hyalinosis, adhesions/synechiae formation, resulting in segmental obliteration of glomerular capillaries. On EM, foot process effacement is the predominant finding without significant basement membrane abnormalities. Immunofluorescence shows staining for IgM and C3 in sclerotic areas. Juxtamedullary nephrons are affected first and hence inadequate sampling may miss focal lesions. https://www.ncbi.nlm.nih.gov/books/NBK532272/","pyqMatches":[{"year":"2020","no":44,"q":"Loss of foot process is classical in case of?","o":["Membranous glomerulitis","Segmental glomerulosclerosis","IgA nephropathy","Diabetic nephropathy"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6789, 'Pathology', 'Hematology', 'Easy', 'Pathology', 631, '{"id":6789,"subject":"Pathology","chapter":"Hematology","difficulty":"Easy","source":"Pathology","sourceNo":631,"q":"Which of the following factors play a major role in the initiation of thrombus formation?","o":["Vasoconstriction","Coagulation cascade activation","Platelets activation","Endothelial injury"],"a":3,"e":"Ans: D. Endothelial injury The three primary abnormalities that lead to thrombus formation (called Virchow''s triad) are (1) endothelial injury, (2) stasis or turbulent blood flow, and (3) hypercoagulability of the blood. Ref: robbins 9th edition chapter 4","pyqMatches":[{"year":"2020","no":45,"q":"Which of the following factors play a major role in the initiation of thrombus formation?","o":["Vasoconstriction","Coagulation cascade activation","Platelets activation","Endothelial injury"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6790, 'Pathology', 'Miscellaneous', 'Hard', 'Pathology', 632, '{"id":6790,"subject":"Pathology","chapter":"Miscellaneous","difficulty":"Hard","source":"Pathology","sourceNo":632,"q":"A 33-year-old man presents with a 5- week history of calf pain, swelling, and low-grade fever. Serum levels of creatinine kinase are elevated. A muscle biopsy reveals numerous eosinophils also she had peripheral blood eosinophilia. Which of the following interleukins is primarily responsible for the increase in eosinophils in this patient?","o":["IL 2","IL 4","IL 1","IL6"],"a":1,"e":"Ans: B. IL 4","pyqMatches":[{"year":"2020","no":46,"q":"A 33-year-old man presents with a 5-week history of calf pain, swelling, and low- grade fever. Serum levels of creatinine kinase are elevated. A muscle biopsy reveals numerous eosinophils also she had peripheral blood eosinophilia. Which of the following interleukins is primarily responsible for the increase in eosinophils in this patient?","o":["IL 2","IL 4","IL 1","IL6"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6791, 'Pathology', 'Infectious Diseases', 'Easy', 'Pathology', 633, '{"id":6791,"subject":"Pathology","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pathology","sourceNo":633,"q":"Which of the following is true about PAN?","o":["Microscopy shows fibrinoid necrosis in large arteries","ANCA is positive","30% of people have HbsAg positive","Patient have hypogammaglobulinemia"],"a":2,"e":"Ans: C. 30% of people have HbsAg positive Polyarteritis nodosa (PAN) is a necrotizing vasculitis involving small and medium-sized muscular arteries of multiple organs and tissues. The disease occurs more commonly in adult males than females. Most commonly affected organs, in descending order of frequency of involvement, are the kidneys, heart, gastrointestinal tract, kidneys, and muscle. The condition results from immunologic response to an identifiable antigen that may be bacteria (e.g. streptococci, staphylococci, mycobacteria), viruses (e.g. hepatitis B virus, influenza virus, CMV), malarial parasite, certain drugs, and chemicals. There is no association with ANCA,[7] but about 30% of people with PAN have chronic hepatitis B and deposits containing HBsAg- HBsAb complexes in affected blood vessels, indicating an immune complex-mediated cause in that subset. Infection with the Hepatitis C virus and HIV are occasionally discovered in people affected by PAN. Leukocytoclastic vasculitis, characterized by fibrinoid necrosis with neutrophilic infiltrate in the vessel wall. Many of the neutrophils are fragmented. This form is found in vasculitis caused by deposits of immune complexes.","pyqMatches":[{"year":"2020","no":47,"q":"Which of the following is true about PAN?","o":["Microscopy shows fibrinoid necrosis in large arteries","ANCA is positive","30% of people have HbsAg positive","Patient have hypogammaglobulinemia"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6792, 'Pathology', 'Hematology', 'Hard', 'Pathology', 634, '{"id":6792,"subject":"Pathology","chapter":"Hematology","difficulty":"Hard","source":"Pathology","sourceNo":634,"q":"A 23-year-old male presented with a history of fatigue and tiredness. On investigation, he was found to have Hb values of 9gm%, MCV of 101 FL. peripheral smear examination showed microcytic RBC and hypersegmented neutrophils. Which is most probable etiology","o":["Lead poisoning","Iron deficiency anemia","Chronic alcoholism","Hemolytic anemia"],"a":0,"e":"Ans: A. Lead poisoning Findings Microcytic Anemia - Iron Deficiency Hypersegmented Neutrophils - B12 and Folic Acid Deficiency Young & No H/o Of Alcohol Consumption [Patient came with a history of Fatigue and Tiredness] - Chronic Alcoholism can be ruled out Hemolytic Anemia - may demonstrate red blood cell fragments called schistocytes, red blood cells that look like spheres (spherocytes), and/or red blood cells missing small pieces (bite cells). An increased number of newly made red blood cells (reticulocytes) may also be a sign of bone marrow compensation for anemia. So Most Probable Answer would be Lead Poisoning [Tiredness & Fatigue]","pyqMatches":[{"year":"2020","no":48,"q":"A 23-year-old male presented with a history of fatigue and tiredness. On investigation, he was found to have Hb values of 9gm%, MCV of 101 FL. peripheral smear examination showed microcytic RBC and hypersegmented neutrophils. Which is most probable etiology","o":["Lead poisoning","Iron deficiency anemia","Chronic alcoholism","Hemolytic anemia"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6793, 'Pathology', 'Inflammation', 'Easy', 'Pathology', 635, '{"id":6793,"subject":"Pathology","chapter":"Inflammation","difficulty":"Easy","source":"Pathology","sourceNo":635,"q":"What is the main feature of chemotaxis as observed in white blood cells?","o":["Increased random movement of neutrophils","Increased adhesiveness to intima","Increased phagocytosis","Unidirectional locomotion of neutrophils"],"a":3,"e":"Ans: D. Unidirectional locomotion of neutrophils Chemotaxis is defined as a unidirectional movement of leukocytes up to a concentration gradient of chemotactic molecules. All granulocytes, monocytes and to a lesser extent lymphocytes respond to chemotactic stimuli with varying rates of speed. Chemoattractants are exogenous or endogenous. Exogenous agents are bacterial products. Endogenous mediators are: Components of complement pathway C5a Products of lipoxygenase pathway LTB4 Cytokines particularly those of chemokine families.","pyqMatches":[{"year":"2020","no":49,"q":"What is the main feature of chemotaxis as observed in white blood cells?","o":["Increased random movement of neutrophils","Increased adhesiveness to intima","Increased phagocytosis","Unidirectional locomotion of neutrophils"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6794, 'Pathology', 'Neoplasia', 'Easy', 'Pathology', 636, '{"id":6794,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Easy","source":"Pathology","sourceNo":636,"q":"Which of the following anticancer drugs are competitive inhibitors of tyrosine kinase –","o":["Imatinib and sunitinib","Letrozole","Bicalutamide","Fulvestrant"],"a":0,"e":"Ans. is ''a'' i.e., Imatinib and sunitinib Molecular targeted agents Tyrosine kinase inhibitors Competitive inhibitors → Imatinib, Nilotinib, Sunitinib, Dasatinib, Erlotinib, Gefitinib, Lapatinib, Sorafenib (Remember all end with '' nib''). Monoclonal antibodies → Cetuximab, panitumumab. HER2/neu (ERB B2) inhibitors Monoclonal antibody - Trastuzumab. Targeted antibody → Gemtuzumab (anti CD-33), Rituximab (anti - CD20), Alemtuzumab (anti CD-52). Vascular endothelial growth factor (VEGF) inhibitor → Monoclonal antibody - Bevacizumab. Proteosome inhibitors → Bortezomib. Histone deacetylase inhibitor → Vorinostat DNA - methyltransferase inhibitor → 5-azacytidine, 2-deoxy-5 azacytidine. All - trans-retinoic acid. Biological response modifier - Recombinant IL-2 (aldesleukin, denileukin).","pyqMatches":[{"year":"2014","no":628,"q":"Which of the following anticancer drugs are competitive inhibitors of tyrosine kinase ?","o":["Imatinib and sunitinib","Letrozole","Bicalutamide","Fulvestrant"],"a":0,"source":"NEET_2014_Paper.pdf"},{"year":"2020","no":50,"q":"Which of the following anticancer drugs are competitive inhibitors of tyrosine kinase –","o":["Imatinib and sunitinib","Letrozole","Bicalutamide","Fulvestrant"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"},{"year":"2020","no":70,"q":"Which of the following anticancer drugs are competitive inhibitors of tyrosine kinase –","o":["Imatinib and sunitinib","Letrozole","Bicalutamide","Fulvestrant"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2014","2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6795, 'Pathology', 'Neoplasia', 'Hard', 'Pathology', 637, '{"id":6795,"subject":"Pathology","chapter":"Neoplasia","difficulty":"Hard","source":"Pathology","sourceNo":637,"q":"20 years old man presented with the complaint of swelling of the wrist for the last two years. histopathological examination showed spindle-shaped cells and verocay bodies what is the diagnosis?","o":["Lipoma","Dermoid cyst","Neuro fibroma","Schwannoma"],"a":3,"e":"Ans: D. Schwannoma spindle cells and verocay bodies are seen in schwannoma is a tumor of the tissue that covers nerves, called the nerve sheath. These tumors develop from a type of cell called a Schwann cell, which gives them their name. Schwannomas are often not cancerous (benign). The most common type of schwannoma is vestibular schwannoma. It affects the nerve responsible for balance (also called the vestibular nerve). It can cause inner ear deafness because the hearing and balance nerve run together, and as the tumor grows it damages the hearing nerve (cochlear nerve). Because of this doctor used to call them acoustic neuromas. Microscopically, the tumor is composed of fibrocellular bundles forming the whorled pattern. There are areas of dense and compact cellularity (Antoni A pattern) alternating with loose acellular areas (Antoni B pattern). Areas of Antoni A pattern show palisaded nuclei called Verocay bodies. Nerve fibers are usually found stretched over the capsule but not within the tumor. Areas of degeneration contain haemosiderin and lipid-laden macrophages. Schwann cells characteristically express S-100 protein. A schwannoma rarely ever becomes malignant.","pyqMatches":[{"year":"2020","no":155,"q":"20 years old man presented with the complaint of swelling of the wrist for the last two years. histopathological examination showed spindle-shaped cells and verocay bodies what is the diagnosis?","o":["Lipoma","Dermoid cyst","Neuro fibroma","Schwannoma"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6796, 'Pediatrics', 'Neonatology', 'Moderate', 'Pediatrics (1)', 1, '{"id":6796,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":1,"q":"All of the following are true about Kernicterus EXCEPT:","o":["Kernicterus is due to Unconjugated Hyperbilirubinemia","Yellowish staining of Basal Ganglia is seen","Prematurity is a risk factor","Not associated with increased morbidity"],"a":3,"e":"Not associated with increased morbidity REF: Nelson 171h edition page 687 KERNICTERUS OR BILIRUBIN ENCEPHALOPATHY: Kernicterus, or bilirubin encephalopathy, is a neurologic syndrome resulting from the deposition of unconjugated bilirubin in the basal ganglia and brainstem nuclei. The greatest risk associated with hyperbilirubinemia is the development of kernicterus (bilirubin encephalopathy) at high indirect serum bilirubin levels. The level of serum bilirubin associated with kernicterus is dependent in part on the cause of the jaundice. Kernicterus has developed when bilirubin levels exceed 30 mg/dL, although the range is wide (21-50 mg/dL). Its onset is usually in the 1st wk of life, but it may_be delayed to the 2nd-3rd wk. Kernicterus develops at lower bilirubin levels in preterm infants and in the presence of asphyxia, intraventricular hemorrhage, hemolysis, or drugs that displace bilirubin from albumin. The exact serum bilirubin level that is harmful for VLBW infants is unclear. Kernicterus does occur in patients with breast milk jaundice but is very uncommon. The surface of the brain is usually pale yellow. On cutting, certain regions are characteristically stained yellow by unconjugated bilirubin Overt neurologic signs have a grave prognosis; 75% or more of such infants die, and 80% of affected survivors have bilateral choreoathetosis with involuntary muscle spasms. Mental retardation, deafness, and spastic quadriplegia are common. Infants at risk should have screening hearing tests.","pyqMatches":[{"year":"2013","no":1461,"q":"All of the following are true about Kernicterus EXCEPT:","o":["Kernicterus is due to Unconjugated Hyperbilirubinemia","Yellowish staining of Basal Ganglia is seen","Prematurity is a risk factor","Not associated with increased morbidity"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6797, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 2, '{"id":6797,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":2,"q":"Definition of childhood is under what age?","o":["8 years","10 years","12 years","16 years"],"a":2,"e":"12 years REF: Nelson Textbook of Paediatrics 17th edition different pages Infancy 0-1 yr Toddlerhood 1-3 yr Early childhood (toddlerhood and some time afterwards) 1-4 yr Middle Childhood (School Age) 6-12 yr Preschool 2-5 yr Adolescence (onset of puberty to maturity) 12-20 yr Adulthood (full physical and intellectual maturity) 20-21 yr onwards","pyqMatches":[{"year":"2016","no":1403,"q":"Definition of childhood is under what age?","o":["8 years","10 years","12 years","16 years"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6798, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 3, '{"id":6798,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":3,"q":"A baby has stated to get his first milk teeth. His age is approximately:","o":["3 months","6 months","9 months","12 months"],"a":1,"e":"Most babies have their first primary (milk) teeth erupt at age 6 month of age and first secondary teeth erupt at age 6 years. The teeth in the upper jaw erupt earlier than those in the lower jaw, except for lower central incisors. The lower central incisors appear, commonly, between the ages of 5 and 8 months. The upper central incisors appear a month later and the lateral incisors usually within the next three months. The first molar teeth appear around the age of 12-15 months, preceding the eruption of canine teeth by 6 months, which appear between the age of 18 and 21 months. The second molars are out at the age of 21 to 24 months. Note: Permanent teeth eruption is in the following order: 1st molar - 6 years; central and lateral incisors - 6-8 years; canines and premolars - 9-12 years; second molars - 12 years; third molars - 18 years or later. Ref: Ghai Essential Pediatrics by O P Ghai, 6th edition, Page 6 ; Nelson Textbook of Paediatrics 17th edition page 18 & 37","pyqMatches":[{"year":"2016","no":635,"q":"A baby has stated to get his first milk teeth. His age is approximately:","o":["3 months","6 months","9 months","12 months"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6799, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 4, '{"id":6799,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":4,"q":"Which of the following statement is true for physiological jaundice in neonate?","o":["Occurs in the first 6 hours of delivery","Neurological sequelae are common","Best treated by phototherapy","Starts on 2nd day of life"],"a":3,"e":"Most neonates develop visible jaundice due to elevation of unconjugated bilirubin concentration during their first week. This common condition is called Physiological jaundice. It lasts for 5 days in term infants & 7 days in preterm infants. It doesnot require any treatment & disappers spontaneously. In pathological jaundice clinical jaundice will appear in the first 24hrs of life. Ref: Nelson, 18th Edition, Pages 760-761; O P Ghai, 6th Edition, Pages 170-171.","pyqMatches":[{"year":"2016","no":1360,"q":"Which of the following statement is true for physiological jaundice in neonate?","o":["Occurs in the first 6 hours of delivery","Neurological sequelae are common","Best treated by phototherapy","Starts on 2nd day of life"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6800, 'Pediatrics', 'Rheumatology', 'Moderate', 'Pediatrics (1)', 5, '{"id":6800,"subject":"Pediatrics","chapter":"Rheumatology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":5,"q":"Which of the following is not a feature of Juvenile Idiopathic Arthritis?","o":["Rheumatoid nodules","Spikes of high fever","Uveitis","Raynaud''s phenomenon"],"a":3,"e":"Raynaud''s Phenomenon is not mentioned in association with Juvenile Idiopathic Arthritis (JIA). Ref: Current Diagnosis and Treatment in Rheumatology, 2nd Edition, Pages 196-197; Nelson’s Textbook of Pediatrics, 18th Edition, Page 1003; Primer on The Rheumatic Diseases By John H. Klippel, Page 145","pyqMatches":[{"year":"2015","no":1414,"q":"Which of the following is not a feature of Juvenile Idiopathic Arthritis?","o":["Rheumatoid nodules","Spikes of high fever","Uveitis","Raynaud''s phenomenon"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6801, 'Pediatrics', 'Nephrology', 'Moderate', 'Pediatrics (1)', 6, '{"id":6801,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":6,"q":"Which one of the following statements is false about Xanthogranulomatous pyelonephritis in children?","o":["Often affects those younger than 8 years of age","It affects the kidney focally more frequently than diffusely","Clinical presentation in children is same as in adults","Boys are affected more frequently"],"a":3,"e":"It is most frequently affected in females compared to males. It is an unusual form of chronic pyelonephritis characterized by granulomatous abscess formation, severe kidney destruction, and a clinical picture that may resemble renal cell carcinoma and other inflammatory renal parenchymal diseases. Xanthogranulomatous pyelonephritis is a form of chronic pyelonephritis characterised by destruction of renal parenchyma and the presence of granulomas, abscesses and collection of lipid laden foamy macrophages (foam cells). Xanthogranulomatous pvelonephritis in children * Age of presentation ranges from infancy to 16 years. * Focal firm being more common in children Appear healthy. * Those who affected diffusely, present with non-specific symptoms of chronic infection. i) Weight loss ii) Fever iii) Lethargy iv) Failure to thrive * Proteus is the most common causative organism. Ref: By James Pattison, David Goldsmith, Barrie Hartley, Fernando C. Fervenza and Joseph P. Grande (2004), Chapter 6, “Renal Infections and Structural Abnormalities”, In the book, “A Colour Handbook of Renal Medicine”, UK, Page 100.","pyqMatches":[{"year":"2015","no":1410,"q":"Which one of the following statements is false about Xanthogranulomatous pyelonephritis in children?","o":["Often affects those younger than 8 years of age","It affects the kidney focally more frequently than diffusely","Clinical presentation in children is same as in adults","Boys are affected more frequently"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6802, 'Pediatrics', 'Infectious Diseases', 'Moderate', 'Pediatrics (1)', 7, '{"id":6802,"subject":"Pediatrics","chapter":"Infectious Diseases","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":7,"q":"Which of the following agents is most commonly associated with recurrent meningitis due to CSF leaks?","o":["Meningococci","Pneumococci","Hemophilus Influenza","E. Coli"],"a":1,"e":"Intracranial CSF leaks cause bacterial meningitis, about 80% are caused by S. Pneumoniae. Other causative organisms are meningococcus, Hemophilus species and S.aurues. Ref: Clinical Pediatric Neurology By Ronald B. David, Page 217","pyqMatches":[{"year":"2016","no":726,"q":"Which of the following agents is most commonly associated with recurrent meningitis due to CSF leaks?","o":["Meningococci","Pneumococci","Hemophilus Influenza","E. Coli"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6803, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 8, '{"id":6803,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":8,"q":"Which of the following is a marker for neural tube defects?","o":["↑Phosphatidylesterase","↑Pseudocholinesterase","↑Acetylcholinesterase","↑Butyrylcholinesterase"],"a":2,"e":"Neural tube defects are associated with high levels of Acetylcholinesterase. Ref: Genetic disorders and Fetus, 4th Edition, Page 673; Ian Donald''s Practical Obstetric Problem By Renu Misra, 6th Edition, Page 44 * In intra embryonic life, neural tube is open at both end and freely communicate with amniotic cavity. Failure of closure of neural tube results in persistent of this communication. This allows excretion of following fetal substances into amniotic cavity ? - Alpha - fetoprotein - Acetylcholinesterase * These serve as biochemical markers for NTDs for prenatal diagnosis.","pyqMatches":[{"year":"2016","no":1364,"q":"Which of the following is a marker for neural tube defects?","o":["↑Phosphatidylesterase","↑Pseudocholinesterase","↑Acetylcholinesterase","↑Butyrylcholinesterase"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6804, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 9, '{"id":6804,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":9,"q":"Child draws triangle at what age ?","o":["3 years","5 years","6 years","7 years"],"a":1,"e":"Ans. is ''b'' i.e., 5 years Age Milestone 12-24 months Tries to scribble spontaneously 2 years Draws a vertical or horizontal line 3 years Draws a circle 4 years Draws a cross (plus sign) and draws a rectangle 5 years Draws a triangle","pyqMatches":[{"year":"2013","no":1421,"q":"Child draws triangle at what age ?","o":["3 years","5 years","6 years","7 years"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6805, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 10, '{"id":6805,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":10,"q":"A child is able to build blocks of 5 Cubes developmental age is -","o":["12 months","15 months","18 months","24 months"],"a":2,"e":"Ans. is ''c'' i.e., 18 month Bang 2 cube - 8 month Tower of 2 cubes - 15 month 4 cubes - 18 month 6 cubes - 22 month","pyqMatches":[{"year":"2012","no":1178,"q":"A child is able to build blocks of 5 Cubes developmental age is","o":["12 months","15 months","18 months","24 months"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6806, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 11, '{"id":6806,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":11,"q":"A child is able to say short sentences of 6 words -","o":["2 years","3 years","4 years","5 years"],"a":2,"e":"Ans. is ''c'' i.e., 4 years o 2 word sentences = 19 month o 6 word sentences = 48 month o 10 word sentences = 60 month","pyqMatches":[{"year":"2012","no":1179,"q":"A child is able to say short sentences of 6 words","o":["2 years","3 years","4 years","5 years"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6807, 'Pediatrics', 'Nutrition', 'Moderate', 'Pediatrics (1)', 12, '{"id":6807,"subject":"Pediatrics","chapter":"Nutrition","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":12,"q":"Delayed dentition is seen in all/except ?","o":["Down syndrome","Congenital hypothyroidism","Rickets","All of above"],"a":3,"e":"Ans. is ''d'' i.e., All of above Causes of delay in tooth eruption : 1) Impacted teeth 4) Cong hypothyroidsm 2) Down syndrome 5) Gaucher Cleidocranial dysplasia 6) Osteo petrosis","pyqMatches":[{"year":"2012","no":1183,"q":"Delayed dentition is seen in all/except ?","o":["Down syndrome","Congenital hypothyroidism","Rickets","All of above"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6808, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 13, '{"id":6808,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":13,"q":"When ICF and ECF of child becomes equal to adult person -","o":["1 year","2 year","3 year","4 year"],"a":0,"e":"Ans. is ''a'' i.e., 1 year o In fetus, ECF is much larger than ICF. o By the age of 1 year, ratio of ICF to the ECF volume approaches adult level.","pyqMatches":[{"year":"2013","no":1427,"q":"When ICF and ECF of child becomes equal to adult person","o":["1 year","2 year","3 year","4 year"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6809, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 14, '{"id":6809,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":14,"q":"Upper segment to lower segment ratio in 3 yr age child is -","o":["12","1.3","1.4","1.6"],"a":1,"e":"Ans. is ''b'' i.e., 1.3 o The lower segment extends from the symphysis pubis to the heels. o The lower segment grows rapidly after birth as compared to upper segment giving rise to the gradual reduction in the upper segment/lower segment ratio with the progression of age. Age Upper segment : Lower segment ratio At birth 1.7 : 1.0 3 years 1.3 -1.0 At 7 years 1.0 : 1.0 Thereafter 1.0:1.1","pyqMatches":[{"year":"2012","no":1181,"q":"Upper segment to lower segment ratio in 3 yr age child is","o":["12","1.3","1.4","1.6"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6810, 'Pediatrics', 'Neonatology', 'Moderate', 'Pediatrics (1)', 15, '{"id":6810,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":15,"q":"A newborn baby has a head circumference of 35 ems. at birth, His optimal head circumference will be 43 ems at -","o":["4 months of age","6 months of age","8 months of age","12 months of age"],"a":1,"e":"Ans. is ''b'' i.e., 6 months of age o At 6 month of age head circumference is between 40.0-43.5cm.","pyqMatches":[{"year":"2015","no":1374,"q":"A newborn baby has a head circumference of 35 ems. at birth, His optimal head circumference will be 43 ems at","o":["4 months of age","6 months of age","8 months of age","12 months of age"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6811, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 16, '{"id":6811,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":16,"q":"Vocabulary of 1.5 year old child is -","o":["1-10 words","10-20 words","20-30 words","30-40 words"],"a":1,"e":"Ans. is ''b'' i.e., 10-20 words At 18 months, the child can use 10 words with meaning. Other milestones asked in the question are achieved in children older than 18 months :? Making a tower of 9 cubes - 30 months Turn pages of book one at a time - 2 years Ride tricycle - 3 years","pyqMatches":[{"year":"2016","no":1414,"q":"Vocabulary of 1.5 year old child is","o":["1-10 words","10-20 words","20-30 words","30-40 words"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6812, 'Pediatrics', 'Growth & Development', 'Moderate', 'Pediatrics (1)', 17, '{"id":6812,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":17,"q":"All of the following are essential features of attention deficit hyperactive disease (ADHD) except -","o":["Lack of concentration","Impulsivity","Mental retardation","Hyperactivity"],"a":2,"e":"Ans. is ''c'' i.e., Mental Retardation Inattentive This must include at least 6 of the following symptoms of inattention that must have persisted for at least 6 months to a degree that is maladaptive and inconsistent with developmental level: Often fails to give close attention to details or makes careless mistakes in schoolwork, work, or other activities Often has difficulty sustaining attention in tasks or play activities Often does not seem to listen to what is being said Often does not follow through on instructions and fails to finish schoolwork, chores, or duties in the workplace (not due to oppositional behavior or failure to understand instructions) Often has difficulties organizing tasks and activities Often avoids or strongly dislikes tasks (such as schoolwork or homework) that require sustained mental effort Often loses things necessary for tasks or activities (school assignments, pencils, books, tools, or toys) Often is easily distracted by extraneous stimuli Often forgetful in daily activities Hyperactivity/impulsivity This must include at least 6 of the following symptoms of hyperactivity-impulsivity that must have persisted for at least 6 months to a degree that is maladaptive and inconsistent with developmental level: Fidgeting with or tapping hands or feet, squirming in seat Leaving seat in classroom or in other situations in which remaining seated is expected Running about or climbing excessively in situations where this behavior is inappropriate (in adolescents or adults, this may be limited to subjective feelings of restlessness) Difficulty playing or engaging in leisure activities quietly Unable to be or uncomfortable being still for extended periods of time (may be experienced by others as “on the go” or difficult to keep up with) Excessive talking Blurting out answers to questions before the questions have been completed Difficulty waiting in lines or awaiting turn in games or group situations Interrupting or intruding on others (for adolescents and adults, may intrude into or take over what others are doing) Other Onset is no later than age 12 years Symptoms must be present in 2 or more situations, such as school, work, or home The disturbance causes clinically significant distress or impairment in social, academic, or occupational functioning Disorder does not occur exclusively during the course of schizophrenia or other psychotic disorder and is not better accounted for by mood, anxiety, dissociative, personality disorder or substance intoxication or withdrawal","pyqMatches":[{"year":"2015","no":1687,"q":"All of the following are essential features of attention deficit hyperactive disease (ADHD) except","o":["Lack of concentration","Impulsivity","Mental retardation","Hyperactivity"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6813, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 18, '{"id":6813,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":18,"q":"Drugs used in ADHD are -","o":["Atomoxetine","Methylphenidate","Dextro-amphetamine","All"],"a":3,"e":"Ans. is ''a'' i.e., Atomoxetine; ''b'' i.e., Methylphenidate; ''c'' i.e., Dextro- amphetamine Some common stimulants used to treat ADHD include: Adderall (amphetamine) Ritalin (methylphenidate) Concerta (methylphenidate) Focalin (dexmethylphenidate) Daytrana (methylphenidate patch) Metadate or Methylin (methylphenidate) Dexedrine or Dextrostat (dextroamphetamine) Vyvanse (lisdexamfetamine dimesylate)","pyqMatches":[{"year":"2014","no":2098,"q":"Drugs used in ADHD are","o":["Atomoxetine","Methylphenidate","Dextro-amphetamine","All"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6814, 'Pediatrics', 'Growth & Development', 'Hard', 'Pediatrics (1)', 19, '{"id":6814,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":19,"q":"A 3 year old boy with normal developmental milestones with delayed speech and difficulty in communication and concentration. He is not making friends. Most probable diagnosis is ?","o":["Autism","ADHD","Mental retardation","Specific learning disability"],"a":0,"e":"Ans. is ''A'' i.e., Autism Delayed speech, difficulty in communication and concentration in a 3 year old child suggests the diagnosis of autism. Autism is characterized by impaired social interaction and communication, and by restricted and repetitive behavior. These signs all begin before a child is three years old. Autism affects information processing in the brain by altering how nerve cells and their synapses connect and organize It is one of three recognized disorders in the autism spectrum, the other two being Asperger syndrome, which lacks delays in cognitive development and language, and pervasive developmental Disorder- not otherwise specified (commonly abbreviated as PDD-NOS)","pyqMatches":[{"year":"2014","no":2107,"q":"A 3 year old boy with normal developmental milestones with delayed speech and difficulty in communication and concentration. He is not making friends. Most probable diagnosis is ?","o":["Autism","ADHD","Mental retardation","Specific learning disability"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6815, 'Pediatrics', 'Growth & Development', 'Moderate', 'Pediatrics (1)', 20, '{"id":6815,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":20,"q":"The following are characteristic of autism except -","o":["Onset after 6 years of age","Repetitive behaviour","Delayed language development","Severe deficit in social interaction"],"a":0,"e":"Ans. is ''a'' i.e., Onset after 6 years of age Autism Autism is a neurologic disroder characterized by ?","pyqMatches":[{"year":"2013","no":1430,"q":"The following are characteristic of autism except","o":["Onset after 6 years of age","Repetitive behaviour","Delayed language development","Severe deficit in social interaction"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6816, 'Pediatrics', 'Nephrology', 'Easy', 'Pediatrics (1)', 21, '{"id":6816,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":21,"q":"5 year old child bed wetting Rx of choice ?","o":["No treatment","Imipramin","Desmopressin","Motivational therapy"],"a":0,"e":"Ans. is ''a'' i.e., No treatment o No treatment is given to children below 6 years of age because of high spontaneous cure rate. o After 6 years treatment include. t) Behavioral therapy : This is the treatment of choice. it) Pharmacological treatment : It is used when non-pharmacological (behavioral) therapy fails. Desmopressin is the drug of choice. Other drugs used are impramine and oxybutinin.","pyqMatches":[{"year":"2012","no":1184,"q":"5 year old child bed wetting Rx of choice ?","o":["No treatment","Imipramin","Desmopressin","Motivational therapy"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6817, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 22, '{"id":6817,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":22,"q":"What is thelarche -","o":["Pubertal breast enlargement in boys","Breast enlargement in pregnancy","Hormone related breast enlargement in girls","Post hormonal therapy breast enlargement in postmenopausal females"],"a":2,"e":"Ans. is ''c'' i.e., Hormone related breast enlargement in girls Thelarche o Definition :- Begining of secondary (Post natal) breast development at onset of puberty in girls. Tanner stage 2 breast development Usually after 8 years of age Because of rising level of estradiol Breast development during puberty in male termed as gynaecomastia not thelarche.","pyqMatches":[{"year":"2012","no":1186,"q":"What is thelarche","o":["Pubertal breast enlargement in boys","Breast enlargement in pregnancy","Hormone related breast enlargement in girls","Post hormonal therapy breast enlargement in postmenopausal females"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6818, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 23, '{"id":6818,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":23,"q":"Selenium deficiency is seen in -","o":["Keshan disease","Wilson disease","Acrodermatitis enteropathica","None of above"],"a":0,"e":"Ans. is ''a'' i.e., Keshan disease o Keshan disease ---> Disorder of Se metabolism o Wilson''s disease ---> Disorder of Cu metabolism o Acrodermatitis enteropathica --> Disorder of Zn metabolism","pyqMatches":[{"year":"2012","no":1189,"q":"Selenium deficiency is seen in","o":["Keshan disease","Wilson disease","Acrodermatitis enteropathica","None of above"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6819, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 24, '{"id":6819,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":24,"q":"Diarrhoea in a child of 12 month, dose of Zinc is ?","o":["1 mg / 10 - 14 day","10 mg / 10 - 14 day","15 mg/ 10- 14 day","20 mg / 10 - 14 day"],"a":3,"e":"Ans. is ''d'' i.e., 20 mg/10-14 days According to WHO guidlines Dose of Zinc 2 month - 6 month = 10 mg / day x 14 days > 6 months = 20 mg/day x 14 days","pyqMatches":[{"year":"2012","no":1188,"q":"Diarrhoea in a child of 12 month, dose of Zinc is ?","o":["1 mg / 10 - 14 day","10 mg / 10 - 14 day","15 mg/ 10- 14 day","20 mg / 10 - 14 day"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6820, 'Pediatrics', 'Nutrition', 'Easy', 'Pediatrics (1)', 25, '{"id":6820,"subject":"Pediatrics","chapter":"Nutrition","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":25,"q":"Phrynoderma is due to ...deficiency-","o":["Vitamin D","Niacin","Vitamin A","Essential fatty acid"],"a":3,"e":"Ans. is ''d'' i.e., Essential fatty acid In vitamin ''A'' deficiency there is toad like skin also known as phrynoderma. o But this is due to associated deficiency of essential fatty acids.","pyqMatches":[{"year":"2012","no":1384,"q":"Phrynoderma is due to ...deficiency","o":["Vitamin D","Niacin","Vitamin A","Essential fatty acid"],"a":3,"source":"NEET_2012_Paper.pdf"},{"year":"2015","no":887,"q":"Phrynoderma is due to ...deficiency","o":["Vitamin D","Niacin","Vitamin A","Essential fatty acid"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2012","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6821, 'Pediatrics', 'Neonatology', 'Moderate', 'Pediatrics (1)', 26, '{"id":6821,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":26,"q":"All of the following are features of prematurity in a neonate, except -","o":["No creases on sole","Abundant lanugo","Thick ear cartilage","Empty scrotum"],"a":2,"e":"Ans. is ''c'' i.e., Thick ear cartilage The ears in a premature neonate are soft and flat with ear cartilage being deficient and pliant (and not thick) Features of prematurity in a Neonate : o Baby is small in size usually less than 47 cm long. o Head is relatively large, sutures are widely separated and fontanelle are large o Face is small and buccal pad of fat is minimal Skin is thin and pinkish and appears shiny due to generalized edema. Skin is covered with abundant lanugo and there is little vernix caseosa. Subcutaneous fat is reduced o The breast nodule is less than 5 mm wide o The ears are soft and flat with ear cartilage being deficient and pliant o Testes are not descended into scrotal sac. (Empty scrotum) Scrotal sac is poorly pigmented and has less rugosities. o In females labia majora appears widely separated, exposing the labia minora and the clitoris. o Deep creases are not well developed in the sole. (There may be a single deep crease over the anterior one third of the sole) o Neonatal reflexes such as Moro, Suckling & Swallowing are sluggish. o There is hypotonia with a poor recoil of flexed forearm when extended.","pyqMatches":[{"year":"2013","no":1435,"q":"All of the following are features of prematurity in a neonate, except","o":["No creases on sole","Abundant lanugo","Thick ear cartilage","Empty scrotum"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6822, 'Pediatrics', 'Miscellaneous', 'Hard', 'Pediatrics (1)', 27, '{"id":6822,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":27,"q":"A baby is born at 27 weeks of gestation required mechanical ventilation for next 4 weeks & 02 for next 1 week. He maintained at room temperature subsequently. As per new Bronchopulmonary dysplasia definition, he has which of the following ?","o":["Mild BPD","Moderate BPD","Severe BPD","No BPD"],"a":0,"e":"Mild Supplement O2 (for 28 days) and < 32 weeks GA Breathing room air at 36 weeks at birth corrected GA or at discharge (whichever comes first). . 32 weeks GA Breathing room air by 56 days at birth postnatal age or at discharge (whichever comes first). • The baby in question falls in category < 32 weeks gestation age at birth. • Simply looking at question, answer seems to be sever BPD as mechanical ventilation (positive pressure ventilation) has included only in diagnostic criteria of sever BPD. • But, This baby was born at 27 weeks of gestation and required mechanical ventilation for 4 more weeks, i.e. upto 31 weeks corrected gestational age. After that he maintained at room air. Thus, at 36 weeks corrected gestaional age, baby is breathing at room air —> diagnostic criteria of mild BPD.","pyqMatches":[{"year":"2012","no":1195,"q":"A baby is born at 27 weeks of gestation required mechanical ventilation for next 4 weeks & 02 for next 1 week. He maintained at room temperature subsequently. As per new Bronchopulmonary dysplasia definition, he has which of the following ?","o":["Mild BPD","Moderate BPD","Severe BPD","No BPD"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6823, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 28, '{"id":6823,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":28,"q":"Which of the following is the principal mode of heat exchange in an infant incubator ?","o":["Radiation","Evaporation","Convection","Conduction"],"a":2,"e":"Ans. is ''c'' i.e., Convection \"Convection warmed incubators are being routinely used for thermal regulation of the premature neonate''s ambient air\" - Ghai 6''/e 154","pyqMatches":[{"year":"2013","no":1437,"q":"Which of the following is the principal mode of heat exchange in an infant incubator ?","o":["Radiation","Evaporation","Convection","Conduction"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6824, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 29, '{"id":6824,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":29,"q":"Dose of i.v. adrenaline in term infant is during neonatal resuscitation -","o":["0.1 - 0.3 ml/kg in 1:1000","0.3 - 0.5 ml/kg in 1:1000","0.1-0.3 ml/kg in 1:10,000","0.3 - 0.5 ml/kg in 1:10,000"],"a":2,"e":"Ans. is c i.e., 0.1-0.3 mUkg in 1:10,000 Dose or adrenlaine ? 0.1 ml/kg to 0.3 inlikg diluted (1: I0,000) Routs : (1) Intravenous (umbilical vein) or (2) Endotracheal Indication ? HR < 60/min after 30 sec. of positive pressure ventilation & chest compression","pyqMatches":[{"year":"2012","no":1168,"q":"Dose of i.v. adrenaline in term infant is during neonatal resuscitation","o":["0.1 - 0.3 ml/kg in 1:1000","0.3 - 0.5 ml/kg in 1:1000","0.1-0.3 ml/kg in 1:10,000","0.3 - 0.5 ml/kg in 1:10,000"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6825, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 30, '{"id":6825,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":30,"q":"Causes of conjugated hyperbilirubinemia is ?","o":["Rotor syndrome","Breast milk jaundice","Crigler najjar","Gilbert syndrome"],"a":0,"e":"Ans. is ''a'' i.e., Rotor syndrome Conjugated hyperbilirubinemia is seen when ? i) Impaired secretion of conjugated bilirubin into bile -> Dubin Johnson syndrome, Rotor syndrome. ii) Impaired bile flow —> Obstructive jaundice, primary biliary cirrhosis, Neonatal cholestasis, e.g. Extrahepatic biliary atresia/neonate idiopathic hepatitis, Choledocal cyst, Sclerosing cholangitis, Caroli disease, Metabolic (Tyrosinemia, Wolman disease, Nieman pick disease, Galactosemia, Fructosemia).","pyqMatches":[{"year":"2012","no":1210,"q":"Causes of conjugated hyperbilirubinemia is ?","o":["Rotor syndrome","Breast milk jaundice","Crigler najjar","Gilbert syndrome"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6826, 'Pediatrics', 'Neonatology', 'Moderate', 'Pediatrics (1)', 31, '{"id":6826,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":31,"q":"Maximum concentration of dextrose that can be given through peripheral vascular line in neonate -","o":["5","10","12.5","25"],"a":2,"e":"Ans. is ''c'' i.e., 12.5 o Hypoglycemia in neonates is blood sugar < 40 mg/dl o Common in preteen, IUGR, infant of diabetic mothers o Treated by breast feed, formula feed & I.V. dextrose solution In symptomatic hypoglycemia 2 ml/g 10% Dx IV bolus given then increase dextrose contents of intravenous fluid. Don''t give > 12.5% dextrose infusion through peripheral line because of risk of thrombophlebitis. (Prefer central line)","pyqMatches":[{"year":"2012","no":1170,"q":"Maximum concentration of dextrose that can be given through peripheral vascular line in neonate","o":["5","10","12.5","25"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6827, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 32, '{"id":6827,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":32,"q":"Hyperglycemia in Neonate if blood sugar is above ?","o":["150 mg/dl","125 mg/dl","180 mg/dl","100 mg/dl"],"a":1,"e":"Ans. is ''b'' i.e., 125 mg/dl o No established definition of neonatal hyperglycemia and upper safe limit of blood glucose has been determined o Various researches has suggested Whole blood glucose > 125 mg/dl Plasma glucose > 150 mg/dl","pyqMatches":[{"year":"2012","no":1196,"q":"Hyperglycemia in Neonate if blood sugar is above ?","o":["150 mg/dl","125 mg/dl","180 mg/dl","100 mg/dl"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6828, 'Pediatrics', 'Neurology', 'Easy', 'Pediatrics (1)', 33, '{"id":6828,"subject":"Pediatrics","chapter":"Neurology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":33,"q":"Hypoxic Ischemic encephalopathy true is ?","o":["Lower limbs affected more than upper limbs","Prox. Muscles > distal muscles","Seizure","Trunk involved"],"a":2,"e":"Ans. is ''c'' i.e., Seizure Clinical features of hvpoxic ischemic encephalopath'' o Encephalopathy progress over time ? 1) Birth to 12 hours —> Decreased level of conciousness, poor tone, decreased spontaneous movement, periodic breathing or apnea, seizures. 2) 12-24 hours -4 More seizuers, Apneic spells, jitteriness, weakness. 3) After 24 hours —> Hypotonia, conciousness, poor feeding, brainstem signs (oculomotor) and pupillary disturbances.","pyqMatches":[{"year":"2015","no":1402,"q":"Hypoxic Ischemic encephalopathy true is ?","o":["Lower limbs affected more than upper limbs","Prox. Muscles > distal muscles","Seizure","Trunk involved"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6829, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 34, '{"id":6829,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":34,"q":"Grasp reflex develops by -","o":["20 weeks","24 weeks","28 weeks","32 weeks"],"a":2,"e":"Ans. is ''c'' i.e., 28 weeks Reflex- Age of appearance 32 - Age of disappearance (after birth)","pyqMatches":[{"year":"2016","no":1349,"q":"Grasp reflex develops by","o":["20 weeks","24 weeks","28 weeks","32 weeks"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6830, 'Pediatrics', 'Neonatology', 'Moderate', 'Pediatrics (1)', 35, '{"id":6830,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":35,"q":"Which of the following is best for transport of the newborn with maintainance of warm temperature ?","o":["Kangaroo Mother Care (KMC)","Transport incubator","Thermacol box","Hot bottle"],"a":0,"e":"Ans is ''a'' i.e., Kangaroo Mother Care (KMC) \"Preferably mother should accompany and baby can be transported in KMC position. Even father can provide KMC during transport if mother can not acompany.\"","pyqMatches":[{"year":"2013","no":1466,"q":"Which of the following is best for transport of the newborn with maintainance of warm temperature ?","o":["Kangaroo Mother Care (KMC)","Transport incubator","Thermacol box","Hot bottle"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6831, 'Pediatrics', 'Cardiology', 'Moderate', 'Pediatrics (1)', 36, '{"id":6831,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":36,"q":"Commonest type of cong. cyanotic heart disease is -","o":["ASD","SD","TOF","PDA"],"a":2,"e":"Ans. is ''c'' i.e., TOF Tetralogy of fallot is the commonest cyanotic congenital heart disease. Cyanotic Congenitial heart diseases o Cyanotic CHDs are Right to Left shunts. o These are further divided into : ? 1) Cyanotic CHD with decreased pulmonary blood flow. This group includes TOF, Pulmonary atresia with intact septum, tricuspid atresia, total anomalous pulmonary venous return with obstruction. These lesions have following components : - a)Obstruction to pulmonary blood flow at tricuspid right ventricular or pulmonary valve level. b)A pathway by which systemic venous blood enters the systemic circulation via a patent foramen ovale or ASD or VSD. Degree of cyanosis depends on the degree of obstruction to pulmonary blood flow : - i) Mild obstruction Cyanosis is precipitaed by stress, but may be absent at rest. ii) Severe obstruction Pulmonary blood flow is dependent on patency of the ductus arteriosus. When the ductus closes (10-21 days), the neonate experience profound hypoxemia, cyanosis and shock. 2) Cyanotic CHD with increased pulmonary blood flow. This group of lesions is not associated with obstruction to pulmonary blood flow. Cyanosis caused by any of the following mechanisms. i) Abnormal ventricular-arterial connection (e.g., Transposition of great vessels) In this, aorta arises from rt ventricle, So that systemic venous blood returning to the right atrium is pumped directly back to the body, and oxygenated blood returning from lung is pumped back into the lungs. ii) Total mixing of systemic venous and pulmonary venous blood (e.g., total anomalous pulmonary venous return, truncus arteriosus, a common atrium or ventricle) Deoxygenated systemic venous blood and oxygenated pulmonary venous blood mix completely in the heart and, as a result, oxygen saturation is equal in the pulmonary artery and aorta. If pulmonary blood flow is not obstructed, these infants have a combination of Cyanosis and heart failure. In Contrast, if pulmonary stenosis is present, these infants have cyanosis alone.","pyqMatches":[{"year":"2013","no":1444,"q":"Commonest type of cong. cyanotic heart disease is","o":["ASD","SD","TOF","PDA"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6832, 'Pediatrics', 'Growth & Development', 'Moderate', 'Pediatrics (1)', 37, '{"id":6832,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":37,"q":"ASD is associated with all except ?","o":["Infective endocarditis","Stroke","Arrhythemia","Pulmonary hypertension"],"a":0,"e":"Ans. is ''a'' i.e., Infective endocarditis o ASD is usually subtle and not having significant problem except mild growth disturbance. o Ostium secundun ASD is M.C. type of ASD. o Ostium secundum ASD usually associated with mitral valve prolopse or stenosis (Lutembacher''s Syndrome). o Complication usually develop in 4thclecade and include : I) Pulmonary hypertension 2) Rt. sided heart failure 3) Stroke 4)Eisenmenger''s syndrome Infective endocarditis is very rare in ASD and not require any antibiotic prophylaxis.","pyqMatches":[{"year":"2012","no":1201,"q":"ASD is associated with all except ?","o":["Infective endocarditis","Stroke","Arrhythemia","Pulmonary hypertension"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6833, 'Pediatrics', 'Cardiology', 'Moderate', 'Pediatrics (1)', 38, '{"id":6833,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":38,"q":"The following features are true for tetralogy of Fallot, except -","o":["Ventricular septal defect","Right ventricular hypertrophy","Atrial septal defect","Pulmonary stenosis"],"a":2,"e":"Ans. is ''c'' i.e., ASD Tetralogy of Fallot * The classical example of cyanotic patients with pulmonic stenosis is tetralogy of fallot. * TOF is the commonest congenital heart disease. * Constituents of TOF Ventricular septal defect Overriding or dextroposed aorta Pulmonic stenosis Right ventricular hypertrophy.","pyqMatches":[{"year":"2016","no":1357,"q":"The following features are true for tetralogy of Fallot, except","o":["Ventricular septal defect","Right ventricular hypertrophy","Atrial septal defect","Pulmonary stenosis"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6834, 'Pediatrics', 'Cardiology', 'Moderate', 'Pediatrics (1)', 39, '{"id":6834,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":39,"q":"All of the following are characteristic features of Tricuspid Atresia except -","o":["Left Axis deviation","Right ventricular hypoplasia","Pulmonary vascularity is diminished","Splitting of S2"],"a":3,"e":"Ans. is ''d'' i.e., Spliting of S2 Atresia of the tricuspid valve results in the absence of a communication between the right atrium and right ventricle therefore the right ventricle is underdeveloped the inflow portion being absent. The only exit for systemic venous blood coming to the right atrium is by way ofAtrial Septa! defect. Through this the blood goes to left atrium from where it enters left ventricle. A ventricular septal defect provides communication between the left ventricle and the outflow portion of the right ventricle. The left ventricle therefore maintain both the systemic as well as the pulmonary circulation thus there is hypertrophy of the left ventricle which is reflected by left axis deviation in ECG. The pulmonary blood flow is dependent on the size of the ventricular defect, the smaller the VSD, the lesser the pulmonary blood flow. 90% patients of Triscuspid Atresia have diminished pulmonary blood flow. o Auscultatory finding in case of Tricuspid Atresia S1 -Normal S2 - Single Murmur grade II to grade III / VI","pyqMatches":[{"year":"2016","no":1052,"q":"All of the following are characteristic features of Tricuspid Atresia except","o":["Left Axis deviation","Right ventricular hypoplasia","Pulmonary vascularity is diminished","Splitting of S2"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6835, 'Pediatrics', 'Cardiology', 'Easy', 'Pediatrics (1)', 40, '{"id":6835,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":40,"q":"True about Ebstein anomaly is?","o":["Right ventricular dilatation","Right atrial dilatation","Left ventricular dilatation","Left atrial dilatation"],"a":1,"e":"Ans. is ''b'' i.e., Right atrial dilatation Ebstein''s anomaly Ebstein anomaly consists of downward displacement of an abnormal tricuspid valve into the right ventricle. o Normally tricuspid valve has three leaflets Anterior, posterior and septal. Fixed end of these leaflets is attached to valve ring in tricuspid area. In Ebstein anomaly, anterior leaflet is attached to valve ring as normal, but the other two leaflets (posterior and septal) are displaced downward and are attached to the wall of left ventricle. The portion of right ventricle above he tricuspid valve becomes a part of right atrium —÷ atrialized right ventricle. Hemodynamics The tricuspid valve anomaly results in obstruction of blood flow as well as regurgitation of blood from the right ventricle into the right atrium → Dilatation and hypertrophy of right atrium due to volume overload. Blood flows right atrium to left atrium through patent foramen ovale or ASD → Right to left shunt and cyanosis. Clinical manifestations","pyqMatches":[{"year":"2013","no":1440,"q":"True about Ebstein anomaly is?","o":["Right ventricular dilatation","Right atrial dilatation","Left ventricular dilatation","Left atrial dilatation"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":1605,"q":"True about Ebstein anomaly is?","o":["Right ventricular dilatation","Right atrial dilatation","Left ventricular dilatation","Left atrial dilatation"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6836, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 41, '{"id":6836,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":41,"q":"Steroids are given in rheumatic fever when there is-","o":["Carditis","Chorea","Subcutaneous nodules","All"],"a":0,"e":"Ans. is ''a'' i.e., Carditis Suppressive therapy of RF o If patient has carditis with CHF —> Steroids If patients has carditis without CHF —> Steroids or aspirin (steroids are preferred) If patient does not have carditis —> Aspirin The total duration of suppressive therapy is 12 weeks.","pyqMatches":[{"year":"2013","no":1419,"q":"Steroids are given in rheumatic fever when there is","o":["Carditis","Chorea","Subcutaneous nodules","All"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6837, 'Pediatrics', 'Cardiology', 'Easy', 'Pediatrics (1)', 42, '{"id":6837,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":42,"q":"In which of the following differential cyanosis found?","o":["VSD with reversal of shunt","PDA with reversal of shunt","ASD with reversal of shunt","Tetralogy of Fallot"],"a":1,"e":"Ans. is ''b'' i.e., PDA with reversal of shunt Differential cyanosis o When one extremity is pink and the other extremity is cyanotic, it is referred to as differential cyanosis.","pyqMatches":[{"year":"2013","no":1448,"q":"In which of the following differential cyanosis found?","o":["VSD with reversal of shunt","PDA with reversal of shunt","ASD with reversal of shunt","Tetralogy of Fallot"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6838, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 43, '{"id":6838,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":43,"q":"In child, foreign body in lung -","o":["Rigid bronchoscopy","Chest x-ray","Flexible endoscopy","Direct laryngoscopy"],"a":0,"e":"Ans. is ''a'' i.e., Rigid bronchoscopy o Treatment of choice is removal of foreign body by rigid bronchoscope with appropriate antibiotics.","pyqMatches":[{"year":"2013","no":1458,"q":"In child, foreign body in lung","o":["Rigid bronchoscopy","Chest x-ray","Flexible endoscopy","Direct laryngoscopy"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6839, 'Pediatrics', 'Cardiology', 'Easy', 'Pediatrics (1)', 44, '{"id":6839,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":44,"q":"In which disease, symptoms improve with crying -","o":["Tetralogy of fallot","Choanal atresia","Bronchial asthma","All of above"],"a":1,"e":"Ans. is ''b'' i.e., Choanal atresia o Bilateral choanal atresia is a very serious life-threatening condition because the baby is unable to breath directly after birth as neonates are obligate nasal breathers. o In some cases, this may present as cyanosis while the baby is feeding because the oral air passages are blocked by the tongue. o The cyanosis may improve when the baby cries, as the oral airway is used at this time. o These babies may require airway resuscitation soon after birth.","pyqMatches":[{"year":"2013","no":1459,"q":"In which disease, symptoms improve with crying","o":["Tetralogy of fallot","Choanal atresia","Bronchial asthma","All of above"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6840, 'Pediatrics', 'Gastroenterology', 'Easy', 'Pediatrics (1)', 45, '{"id":6840,"subject":"Pediatrics","chapter":"Gastroenterology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":45,"q":"3 month infants with abdominal palpable mass & non bilious vomiting -","o":["Hypertrophic biliary stenosis","Hypertrophic pyloric stenosis","Tracheoesophageal fistula","Duodenal atresia"],"a":1,"e":"Ans. is ''b'' i.e., Hypertrophic pyloric stenosis Hypertophic pyloric stenosis Most common cause of nonbilious vomiting is Hypertrophic pyloric stenosis. Male > female. Vomiting starts with 3 week of age. Palpable mass is seen in epigastric region. Visible peristalsis is seen soon after feeding. Confirmed by USG abdomen. Contrast study shows : . Shoulder sign . Double tract sign. Treatment surgery = Ramstedt procedure.","pyqMatches":[{"year":"2012","no":1209,"q":"3 month infants with abdominal palpable mass & non bilious vomiting","o":["Hypertrophic biliary stenosis","Hypertrophic pyloric stenosis","Tracheoesophageal fistula","Duodenal atresia"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6841, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 46, '{"id":6841,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":46,"q":"Hirschsprung disease is confirmed by ?","o":["Rectal biopsy","Per/Rectal examination","Rectal manometry","X-ray abdomen"],"a":0,"e":"Ans. is ''a'' i.e., Rectal biopsy o Rectal suction biopsy is procedure of choice.","pyqMatches":[{"year":"2012","no":1213,"q":"Hirschsprung disease is confirmed by ?","o":["Rectal biopsy","Per/Rectal examination","Rectal manometry","X-ray abdomen"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6842, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 47, '{"id":6842,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":47,"q":"Skip granulomatous lesions are seen in ?","o":["Ulcerative colitis","Crohn''s disease","Whipple''s disease","Reiter''s disease"],"a":1,"e":"Ans. is ''b'' i.e., Crohn''s Disease Features of CD In the affected segment, mesentric fat wraps around the bowel surface —> creeping fat o The intestinal wall is rubbery and thick, as a consequence of edema, inflammation, fibrosis, and hypertrophy of the muscularis propria —> lumen is almost always narrowed --> string sign on barium meal. o A classic feature of CD is the sharp demarcation of diseased bowel segments from adjucent uninvolved bowel. o When multiple bowel segments are involved, the intervening bowel is normal —> skip lesions. o There are serpentine linear ulcer along the axis of bowel. As the intervening mucosa tends to be relatively spared, the mucosa acquires a coarsely textured Cobblestone appearance. o Narrow fissures develop between the folds of the mucosa. Fissures can penetrate deeply through the bowel wall and leading to bowel adhesions and serositis. o Further extension of fissures leads to fistula or sinus tract formation. o There is transmural inflammation affecting all layers of bowel wall. Sarcoid like noncaseating granulomas may be present in all tissue layers. o Neutrophilic infiltration into the crypts results in formation of crypt o Neutrophilic infiltration into the crypts results in formation of crypt abscess. o Fibrosis of the submucosa, muscularis propria, and mucosa eventually leads to stricture formation. There is an increased incidence of cancer of GIT in patients with long-standing CD, but the risk of cancer in CD is considerably less than in patients with chronic UC.","pyqMatches":[{"year":"2014","no":1289,"q":"Skip granulomatous lesions are seen in ?","o":["Ulcerative colitis","Crohn''s disease","Whipple''s disease","Reiter''s disease"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6843, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 48, '{"id":6843,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":48,"q":"Most common cause of severe hematemesis in a child is-","o":["Portal hypetension","Peptic ulcer","Mallory weiss syndrome","None of the above"],"a":0,"e":"Ans. is ''a'' i.e., Portal hypertension \"Massive hematemesis in a child is almost always due to variceal bleeding\". Variceal bleeding is due to portal hypertension.","pyqMatches":[{"year":"2016","no":1372,"q":"Most common cause of severe hematemesis in a child is","o":["Portal hypetension","Peptic ulcer","Mallory weiss syndrome","None of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6844, 'Pediatrics', 'Neurology', 'Easy', 'Pediatrics (1)', 49, '{"id":6844,"subject":"Pediatrics","chapter":"Neurology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":49,"q":"Chronic constipation in children is seen in all A/E?","o":["Hirschspring disease","Jejunal polyp","Hypothyroidism","Stricture"],"a":1,"e":"Ans. is ''b'' i.e., Jejunal polyp Organic causes of constipation are : i) Intestinal: Hirschprung disease, Anal/rectal stenosis, Anal fissure, anteriorly displaced anal opening, strictures. ii) Drugs: Narcotics, vincristine, Psychotropics. iii) Metabolic/endocrine: Cystic fibrosis, hypothyroidism, Panhypopituitrism iv) Neuromuscular: Cerebral palsy, Psychomotor retardation, spinal cord lesions, Myotonic dystophy, Neuropathy or myopathy of GIT v) Other causes: Low fibre diet, Milk protein allergy.","pyqMatches":[{"year":"2012","no":1208,"q":"Chronic constipation in children is seen in all A/E?","o":["Hirschspring disease","Jejunal polyp","Hypothyroidism","Stricture"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6845, 'Pediatrics', 'Nephrology', 'Easy', 'Pediatrics (1)', 50, '{"id":6845,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":50,"q":"\"Potter''s syndrome\" is associated with -","o":["Renal anomalies","Severe oligohydramnio''s","Flattened nose","All the above"],"a":3,"e":"Ans. is ''d'' i.e., All of the above Potter syndrome Potter syndrome is characterized by - i) Bilateral renal agenesis ii) Pulmonary hypoplasia iii) Potter facies --> widely separated eyes with epicanthic folds, low set ears, broad compressed flat nose, receding chin. * This condition is incompatible with life, death occurs shortly after birth from pulmonary hypoplasia. * Maternal USG demonstrates - i) Oligohydramnios ii) Nonvisulization of bladder iii) Absent kidney","pyqMatches":[{"year":"2015","no":1375,"q":"\"Potter''s syndrome\" is associated with","o":["Renal anomalies","Severe oligohydramnio''s","Flattened nose","All the above"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6846, 'Pediatrics', 'Nephrology', 'Moderate', 'Pediatrics (1)', 51, '{"id":6846,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":51,"q":"Not true about chronic pyelonephritis in children -","o":["Associated with Ureteric reflux","Associated with Intrarenal reflux","Associated with renal scarring","Males are more affected than female"],"a":3,"e":"Ans. is ''d'' i.e., Males are more affected than female o 3 basic forms of UTI - (1) Pyelonephritis (2) Cystitis (3) Asymptomatic bacteremia Chronic Pyelonephritis :- Characterised by renal inflammation & fibrosts induced by recurrent or persistent renal infection, vesicoureteric reflux or other causes of UTI. Progressive renal scarring which leads to end stage renal diseaes. In reflex nephropathy, Intrarenal reflex of infected urine induces renal injury which heals by renal scarring. Being - straight, short & wide urethra, recurrent UTI is more common in female, so CPN is also twice as common is female than male.","pyqMatches":[{"year":"2012","no":1216,"q":"Not true about chronic pyelonephritis in children","o":["Associated with Ureteric reflux","Associated with Intrarenal reflux","Associated with renal scarring","Males are more affected than female"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6847, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 52, '{"id":6847,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":52,"q":"Drug of choice for infantile spasm is?","o":["Vigabatrin","Adrenocorticotropic hormone (ACTH)","Ethosuximide","Carbamazepine"],"a":0,"e":"Ans. ''a'' i.e., Vigabatrin Vigabatrin (drug of choice), ACTH (2nd choice) and corticosteroids are used for treatment.","pyqMatches":[{"year":"2013","no":1450,"q":"Drug of choice for infantile spasm is?","o":["Vigabatrin","Adrenocorticotropic hormone (ACTH)","Ethosuximide","Carbamazepine"],"a":0,"source":"NEET_2013_Paper.pdf"},{"year":"2016","no":1369,"q":"Drug of choice for infantile spasm is?","o":["Vigabatrin","Adrenocorticotropic hormone (ACTH)","Ethosuximide","Carbamazepine"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2013","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6848, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 53, '{"id":6848,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":53,"q":"Most common cause of neonatal meningitis -","o":["Staphylococcus","E. coli","H. influenze","Pneumococcus"],"a":1,"e":"Ans. is ''b'' i.e., E. coli \"Group B streptococcus followed by E.coli are the two most common causes of neonatal meningitis\". Most common cause of neonatal meningitis —› Group B streptococcus (Str. agalactiae) Second most common cause of neonatal meningitis -- E.coli","pyqMatches":[{"year":"2013","no":1452,"q":"Most common cause of neonatal meningitis","o":["Staphylococcus","E. coli","H. influenze","Pneumococcus"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6849, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 54, '{"id":6849,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":54,"q":"The most common cause of meningitis in children aged 5 yrs is-","o":["H influnzae","N. meningitides","Staphylococcus","E.coli"],"a":1,"e":"Ans. is ''b'' i.e., N. meningitides Commonest causes of meningitis Neonatal - Group B streptococcus most common, E.coli second most common. 2 months to 3 years • Pneumococci > Meningococci > H. influenzae 3 years to 20 years Meningococcus > 20 years • Pneumococci","pyqMatches":[{"year":"2013","no":1451,"q":"The most common cause of meningitis in children aged 5 yrs is","o":["H influnzae","N. meningitides","Staphylococcus","E.coli"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6850, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 55, '{"id":6850,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":55,"q":"Which is MC genetic cause of mental retardation -","o":["Tuberous sclerosis","Cri-du-chat syndrome","Fragile-x-syndrome","Angel''s syndrome"],"a":2,"e":"Ans. is ''c'' i.e., Fragile-X-syndrome o Down''s syndrome is the most common genetic cause of mental retardation, and fragile-X is second to Down''s. Also know o Most common inherited cause of mental retardation is fragile-X- syndrome (because down''s syndrome is congenital cause but not inherited).","pyqMatches":[{"year":"2012","no":1160,"q":"Which is MC genetic cause of mental retardation","o":["Tuberous sclerosis","Cri-du-chat syndrome","Fragile-x-syndrome","Angel''s syndrome"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6851, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 56, '{"id":6851,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":56,"q":"Decorticate child - Flase statement is ?","o":["Acute Brain injurys","Susthalamic, CT & frontal lobe lesion","More dangerous than decerebrate lesion","Flexion of arm & extension of lower limb"],"a":2,"e":"Ans. is ''c'' i.e., More dangerous than decerebrate lesion Decortical Posture o Also known as flexor posturing or Mummy baby o Arms flexed/bent over chest, hand fisted, leg extended & rotated inward o Damage to area in cerebral hemisphere, internal capsule, thalamus & upper part of brain. o Decorticate posture is ominous sign of severe brain damage. Decerebrate posture o Also known as extensor posturing o Extension of upper limb & lower limb (ELBOW EXTENDED) o Indicates brain stem damage (Below level of red nucleus) o Decerebrate posture is more ominous than decortical posture","pyqMatches":[{"year":"2012","no":1205,"q":"Decorticate child - Flase statement is ?","o":["Acute Brain injurys","Susthalamic, CT & frontal lobe lesion","More dangerous than decerebrate lesion","Flexion of arm & extension of lower limb"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6852, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 57, '{"id":6852,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":57,"q":"Which one of the following is the most common tumor associated with type I neurofibromatosis ?","o":["Optic nerve glioma","Meningioma","Acoustic schwannoma","Low grade astrocytoma"],"a":0,"e":"Ans. is ''a'' i.e., Optic nerve glioma Neurofibromatosis type I (Von-Recklinghewsen disease) o NF-1 is diagnosed when any two of the following seven signs are present.","pyqMatches":[{"year":"2013","no":479,"q":"Which one of the following is the most common tumor associated with type I neurofibromatosis ?","o":["Optic nerve glioma","Meningioma","Acoustic schwannoma","Low grade astrocytoma"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6853, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 58, '{"id":6853,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":58,"q":"All of the following are features of juvenile CML except -","o":["Thrombocytopenia","Fetal Hb is increased","Philadelphia chromosome is positive","Lymphadenopathy"],"a":2,"e":"Ans. is ''c'' i.e., Philadelphia chromosome is positive Juvenile CML is mostly seen in children below 2 years of age. Philadelphia chromosome is negative and leukocyte count is less than 100''000/mm3. Features Adult CML Juvenile CML Age 10-12 years < 2 years Bleeding manifestation Absent Frequent Thrombocytopenia Uncommon Frequent Rash Absent Frequent Lymphadenopathy Rare Frequent Splenomegaly Marked Variable WBC count at diagnosis > 100''000 < 100''000 WBC type Granulocyte Monocyte Normoblastic Unusual Common HbF Normal Increased Immunoglobulins Normal Increased Muramidase levels Normal Increased Response to Busulphan Good Poor Survival 2.5-3 years 9 months","pyqMatches":[{"year":"2012","no":1174,"q":"All of the following are features of juvenile CML except","o":["Thrombocytopenia","Fetal Hb is increased","Philadelphia chromosome is positive","Lymphadenopathy"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6854, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 59, '{"id":6854,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":59,"q":"Commonest tumor of face in chidren is-","o":["Rhabdomyosarcoma","Sq. cell carcinoma","Basal cell carcinoma","Mixed parotid tumor"],"a":0,"e":"Ans. is ''a'' i.e., Rhabdomyosarcoma Rhabdomyosarcoma o The most common soft tissue sarcoma in children is rhabdomyosarcoma. o The common site of involvement are : - o Head & Neck (25%) 2\"d most common Extremities Genitourinary (22%) —> 2nd most common Retroperitoneum","pyqMatches":[{"year":"2012","no":518,"q":"Commonest tumor of face in chidren is","o":["Rhabdomyosarcoma","Sq. cell carcinoma","Basal cell carcinoma","Mixed parotid tumor"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6855, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 60, '{"id":6855,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":60,"q":"Highest cure rate is of -","o":["Wilm''s Tumor","Retinoblastoma","Rhabdomyosarcoma","All"],"a":1,"e":"Ans. is ''b'' i.e., Retinoblastoma Tumor 5 years survival rate Retinoblastoma 97% Wilms tumor 88% Rhabdomyosarcoma 61%","pyqMatches":[{"year":"2012","no":1218,"q":"Highest cure rate is of","o":["Wilm''s Tumor","Retinoblastoma","Rhabdomyosarcoma","All"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6856, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 61, '{"id":6856,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":61,"q":"Most common benign tumours during infancy is-","o":["Lymphangioma","Hemangioma","Cystic hygroma","Lipoma"],"a":1,"e":"Ans. is ''b'' i.e., Hemangioma o Hemangiomas, the most common benign tumors of infancy, occur in 10% of term infants.","pyqMatches":[{"year":"2012","no":1175,"q":"Most common benign tumours during infancy is","o":["Lymphangioma","Hemangioma","Cystic hygroma","Lipoma"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6857, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 62, '{"id":6857,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":62,"q":"Male pseudohermaphroditism is seen in ?","o":["5-a reductase deficiency","21 hydroxylase deficiency","17 hydroxylase deficiency","a and c"],"a":3,"e":"Ans. is ''a'' i.e., 5-a reductase deficiency; ''c'' i.e., 17 hydroxylase deficiency Male pseudohermaphroditism Genotype is XY External genitalia are female Causes of Male Pseudohermaphroditism A. Defect in testicular differentiation","pyqMatches":[{"year":"2013","no":1473,"q":"Male pseudohermaphroditism is seen in ?","o":["5-a reductase deficiency","21 hydroxylase deficiency","17 hydroxylase deficiency","a and c"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6858, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 63, '{"id":6858,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":63,"q":"Gonads to testes differentiation -","o":["SRY gene","WNT-4 gene","DAX1 gene","None"],"a":0,"e":"Ans. is ''a'' i.e., SRY gene o 46 XX chromosome with genetic factor such as DAX1 and signalling molecule WNT-4 are necessary for development of ovary. o Y chromosome contains SRY gene which differentiates gonads to testes.","pyqMatches":[{"year":"2013","no":1477,"q":"Gonads to testes differentiation","o":["SRY gene","WNT-4 gene","DAX1 gene","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6859, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 64, '{"id":6859,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":64,"q":"What stimulates the gonads in male at 8 week to secret testosterone -","o":["Inhibin from corpus luteum","GnRH from hypothalamus of baby","Placental HCG","All of above"],"a":2,"e":"Ans. is ''c'' i.e., Placental HCG During embryogenesis, In male embryo, at 6-7 week of gestatin, secretion of first anti-mullerian hormone (also k/o mullerian inhibiting substance) causes regression of mullerian duct. Then at 8-12 week, under influence of Placental HCG, testes started producing testosterone.","pyqMatches":[{"year":"2012","no":1154,"q":"What stimulates the gonads in male at 8 week to secret testosterone","o":["Inhibin from corpus luteum","GnRH from hypothalamus of baby","Placental HCG","All of above"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6860, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 65, '{"id":6860,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":65,"q":"Precocious puberty is seen in -","o":["Hypothyroidism","CNS irridation","Mc cune-Albright syndrome","All"],"a":3,"e":"Ans. is ''a'' i.e., Hypothyroidism; ''b'' i.e., CNS irradiation; ''c'' i.e., Mc Cune Albright syndrome Precocious puberty o Puberty before the age of 8 years in girls or 9 years in boys is considered precocious puberty. o Menarche before the age of 10 years in girls is also considered as precocious. o Precocious puberty is of two types","pyqMatches":[{"year":"2014","no":1652,"q":"Precocious puberty is seen in","o":["Hypothyroidism","CNS irridation","Mc cune-Albright syndrome","All"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6861, 'Pediatrics', 'Neonatology', 'Moderate', 'Pediatrics (1)', 66, '{"id":6861,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":66,"q":"Features of hypothyroidism in infancy include the following except-","o":["Premature closure of posterior fontanelle","Coarse facies","Umbilical hernia","Constipation"],"a":0,"e":"Ans. is ''a'' i.e., Premature closure of posterior fontanelle o There is delayed closure of posterior fontanelle.","pyqMatches":[{"year":"2013","no":1476,"q":"Features of hypothyroidism in infancy include the following except","o":["Premature closure of posterior fontanelle","Coarse facies","Umbilical hernia","Constipation"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6862, 'Pediatrics', 'Nephrology', 'Easy', 'Pediatrics (1)', 67, '{"id":6862,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":67,"q":"The sodium content of ReSoMal (rehydration solution for malnourished children) is -","o":["90 mmol/L","60 mmol/L","45 mmoUL","30 mmol/L"],"a":2,"e":"Ans. is ''c'' i.e., 45 mmol/L","pyqMatches":[{"year":"2013","no":1479,"q":"The sodium content of ReSoMal (rehydration solution for malnourished children) is","o":["90 mmol/L","60 mmol/L","45 mmoUL","30 mmol/L"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6863, 'Pediatrics', 'Cardiology', 'Easy', 'Pediatrics (1)', 68, '{"id":6863,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":68,"q":"Turner syndrome is maximally associated with ?","o":["Horseshoe kidney","Coarctation of aorta","VSD","ASD"],"a":1,"e":"Ans. is ''b'' i.e., Coarctation of aorta Among the given options Aortic coarctation is most common. Turner''s syndrome is commonly associated with congenital heart diseases. The most common anomaly associated is bicuspid Aortic valves in one third to one half of the patients (50%). Other congential anomalies associated with Turner''s syndrome —> Aortic coarctation (30%), Aortic stenosis, Mitral valve prolapse, Anomalous pulmonary venous drainage.","pyqMatches":[{"year":"2014","no":1242,"q":"Turner syndrome is maximally associated with ?","o":["Horseshoe kidney","Coarctation of aorta","VSD","ASD"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6864, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 69, '{"id":6864,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":69,"q":"Barr body is absent in female having ?","o":["46 XX genome","45 X0 genome","47 XXX","All of above"],"a":1,"e":"Ans. is ''b'' i.e., 45 X0 genome Barr body (Sex - chromatin) o It is a densely staining inactivated condensed ''X'' chromosome that is present in each somatic cells of female. o It is found in the nucleus. o It is used as a test of genetic femaleness it is possible to determine the genetic sex of an individual according as to whether there is a chromatin mass present on the inner surface of the nuclear membrane of cells with resting or intermitent nuclei. Remember following fact and the question will seem very easy. Chromatid body (Barr body or sex chromatin) is derived from one of the two X-chromosomes which becomes inactivated. The numer of Barr bodies is thus one less than the number of X- chromosomes. Note - o Barr body is found in female But - o Kleinefelter syndrome is male with Barr body. o Turner syndrome is female without Barr body.","pyqMatches":[{"year":"2012","no":1161,"q":"Barr body is absent in female having ?","o":["46 XX genome","45 X0 genome","47 XXX","All of above"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6865, 'Pediatrics', 'Infectious Diseases', 'Moderate', 'Pediatrics (1)', 70, '{"id":6865,"subject":"Pediatrics","chapter":"Infectious Diseases","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":70,"q":"Rubella causes all except","o":["Microcephaly","VSD","Conduction defect","All"],"a":1,"e":"Ans. is ''b'' i.e., VSD Organ of corti : Sensorineural hearing loss (Most common clinical finding of congenital rubella). Heart : PDA (Most common CHD in congenital rubella), PS, VSD, ASD TOF, pulmonary artery hypoplasia. Eye : Cataract, retinopathy, microphthalmia, myopia, glaucoma. CNS : Mental retardation, spastic diplegia, microcephaly, seizures, behavioral disorders. Other : IDDM, thyroid disorders, inguinal hernia, cryptorchidism, interstitial pneumonia.","pyqMatches":[{"year":"2012","no":1164,"q":"Rubella causes all except","o":["Microcephaly","VSD","Conduction defect","All"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6866, 'Pediatrics', 'Hematology', 'Moderate', 'Pediatrics (1)', 71, '{"id":6866,"subject":"Pediatrics","chapter":"Hematology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":71,"q":"Dengue shock syndrome is characterized by the following except -","o":["Hepatomegaly","Pleural effusion","Thrombocytopenia","Decreased haemoglobin"],"a":3,"e":"Ans. is ''d'' i.e., Decreased hemoglobin Dengue hemorrhagic fever Fever Minor or Major hemorrhgic manifestations Hepatomegaly Thrombocytopenia 100,000/mm3 Hypoalbuminemia Objective evidence of increased capillary permeability (hematocrit 20%.) Pleural effusion (by chest radiograph) [Nelson, 17/e, p 1093] Criteria for Dengue shock syndrome It includes those for dengue hemorrhagic fever plus, Hypotension or narrow pulse.","pyqMatches":[{"year":"2016","no":1164,"q":"Dengue shock syndrome is characterized by the following except","o":["Hepatomegaly","Pleural effusion","Thrombocytopenia","Decreased haemoglobin"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6867, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 72, '{"id":6867,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":72,"q":"Retinopathy of prematurity is commonly predisposed by-","o":["Less gestation age","Low birth weight","O2 toxicity","Carbohydrate excess"],"a":0,"e":"Ans. is ''a'' i.e., Less gestation age","pyqMatches":[{"year":"2015","no":1046,"q":"Retinopathy of prematurity is commonly predisposed by","o":["Less gestation age","Low birth weight","O2 toxicity","Carbohydrate excess"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6868, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 73, '{"id":6868,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":73,"q":"Head control/ neck holding is possible in an infant by: September 2012","o":["1 month","2 months","3 months","6 months"],"a":2,"e":"Ans. C i.e. 3 months When a child is tried to pull to sit :- i) Head lag --> Age is less than 4 weeks ii) Partial head lag —> 2-3 months iii) Head (Neck) Control ---> 3 months. iv) Lifting of head up --> 5 months.","pyqMatches":[{"year":"2013","no":1422,"q":"Head control/ neck holding is possible in an infant by: September 2012","o":["1 month","2 months","3 months","6 months"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6869, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 74, '{"id":6869,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":74,"q":"Nocturnal enuresis may be considered normal upto: March 2005","o":["3 years","4 years","5 years","6 years"],"a":3,"e":"Ans. D: 6 years Nocturnal enuresis is normal upto 6 years while its normal upto the age of 4 years for daytime.","pyqMatches":[{"year":"2013","no":1429,"q":"Nocturnal enuresis may be considered normal upto: March 2005","o":["3 years","4 years","5 years","6 years"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6870, 'Pediatrics', 'Nutrition', 'Easy', 'Pediatrics (1)', 75, '{"id":6870,"subject":"Pediatrics","chapter":"Nutrition","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":75,"q":"Acute malnutrition in a child is clinically assessed by: September 2005","o":["Body mass index","Weight for age","Height for age","Weight for height"],"a":3,"e":"Ans. D: Weight for height An indicator known as weight-for-height is used to determine whether a child is acutely malnourished or not. The child''s weight is compared to the ''normal'' weight for that height. Based on this information, the World Health Organisation (WHO) has developed charts known as international standards for expected growth. If a child''s weight falls within the range considered normal for his/her height, the child is found to be well-nourished. If the weight is less than the international standards, the child is considered acutely malnourished or wasted. WHO has created cut-off points to indicate the severity of the malnutrition. If a child''s weight-for-height is less than -2 z-scores (or standard deviations) of normal children, s/he is considered to suffer from moderate acute malnutrition or wasting. If the child''s weight-for-height is less than -3 z-scores (standard deviations) of normal children s/he suffers from severe acute malnutrition and is considered to be severely wasted. Another measurement used to determine a child''s nutritional status is the mid-upper arm circumference (MUAC) measurement. is the mid upper arm circumference (MUAC) measurement. Because MUAC measurements require a simple, colour-coded measuring band rather than weighing scales and height boards, they are often used during crisis situations. Useful for children between six months and five years of age, a MUAC measurement of less than 12.5 cm indicates that a child is suffering from moderate acute malnutrition. If the MUAC measurement is under 11.0 cm, however, the under- five child''s life may be in danger as he or she is suffering from severe acute malnutrition. Although no anthropometric measure is a perfect marker of acute malnutrition, in the past, there has been a tendency to view W/H measures as the gold-standard anthropometric measure to diagnose acute malnutrition in emergencies. Discrepancies between MUAC and W/H have therefore been explained by MUAC being a poor indicator of nutritional status. A third way of diagnosing acute malnutrition is by testing for the presence of oedema. Oedema affects a child''s appearance, giving him or her a puffy, swollen look in either lower limbs and feet or face. It can be detected by small pits or indentations remaining in the child''s lower ankles or feet, after pressing lightly with the thumbs. The presence of oedema in both feet and lower legs is always considered a sign of severe acute malnutrition.","pyqMatches":[{"year":"2014","no":1630,"q":"Acute malnutrition in a child is clinically assessed by: September 2005","o":["Body mass index","Weight for age","Height for age","Weight for height"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6871, 'Pediatrics', 'Cardiology', 'Easy', 'Pediatrics (1)', 76, '{"id":6871,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":76,"q":"All of the following are true for Turners syndrome ex​cept: March 2012","o":["Height is more than 145 cm","Webbing of neck","Increased carrying angle","Coarctation of aorta may be seen"],"a":0,"e":"Ans: A i.e. Height is more than 145 Turner syndrome Adult stature in Turner syndrome patients is less than 145 cm Associated congenital defects are common in heart (coarctation of aorta) Lymphedema, Short stature, Webbed neck, Low posterior hairline, Cubitus valgus (increased carrying angle), Finger deformities, Short 4th metacarpal, 45 X0 karyotype Down syndrome MC trisomy, Brachycephalic skull, Hypotonia, Palpebral fissure slopes upwards, Marked epicanthic folds, Brushfield''s spots, Increased nuchal fold thickness, Iliac index less than 60, Simian crease (single palmar crease), MC associated cardiac lesions: VSD Duodenal atresia, CML & transient myeloproliferative disorders are seen May be associated with Alzheimer''s dementia, MC cause of down syndrome: Maternal non-disjunction Klinefelter syndrome 47 XXY MC cause of hypergonadotrophic hypogonadism, Subnormal intelligence Fragile X syndrome Large forehead, Large head, Macro-orchidism, Moderately to severely retarded","pyqMatches":[{"year":"2014","no":429,"q":"All of the following are true for Turners syndrome ex​cept: March 2012","o":["Height is more than 145 cm","Webbing of neck","Increased carrying angle","Coarctation of aorta may be seen"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6872, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 77, '{"id":6872,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":77,"q":"Prophylactic dose of vitamin K given to new born infants at delivery is ?","o":["1mg","5mg","10mg","15mg"],"a":0,"e":"Ans. is ''a'' i.e., 1 mg Vitamin K Deficiency in Newborns The symptoms of vitamin K deficiency are due to hemorrhage Newborns are particularly susceptible to vitamin K deficiency because of low fat stores, low breast milk levels of vitamin K, sterility of the infantile intestinal tract, liver immaturity, and poor placental transport. Intracranial bleeding, as well as gastrointestinal and skin bleeding, can occur in vitamin K-deficient infants 1​7 days after birth. Thus, vitamin K (1 mg IM) is given prophylactically at the time of delivery.","pyqMatches":[{"year":"2012","no":565,"q":"Prophylactic dose of vitamin K given to new born infants at delivery is ?","o":["1mg","5mg","10mg","15mg"],"a":0,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":599,"q":"Prophylactic dose of vitamin K given to new born infants at delivery is ?","o":["1mg","5mg","10mg","15mg"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6873, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 78, '{"id":6873,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":78,"q":"Cat bites in child treatment - false is","o":["Cleaning the wound thoroughly","Puncture wound most common","May require rabies vaccination","All of above"],"a":3,"e":"Ans. is `d'' i.e., All of above The most common type of injury from cat and rat bites is a puncture wound. Cat bites often penetrate to deep tissue Infection is the most common complication of any type of bite injuries. Treatment includes cleansing of wound, debridement, wound culture, tetanus and antirabies immunization, and initiation of antibiotics. A moxicillin-clavulanate is an excellent choice for empirical oral therapy for human and animal bite wounds because of its activity against most of the strains of bacteria that have been isolated from infected bite injuries.","pyqMatches":[{"year":"2014","no":1665,"q":"Cat bites in child treatment - false is","o":["Cleaning the wound thoroughly","Puncture wound most common","May require rabies vaccination","All of above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6874, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 79, '{"id":6874,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":79,"q":"Most common GI malignancy of childhood","o":["Adenocarcinoma","Lymphoma","Sarcoma","carcinoid"],"a":1,"e":"Ans. is ''b'' i.e., Lymphoma Over all hemangioma is most common Tumor in infant. Hemangioma is usually benign in Nature. Leukemia is most common malignancy in pediatric age gyp. 2\"'' most common is CNS Tumor = Lymphoma is the most common malignancy of the gastrointestinal tract in children. About 30% of children with non-Hodgkin lymphoma present with abdominal tumors.","pyqMatches":[{"year":"2014","no":1643,"q":"Most common GI malignancy of childhood","o":["Adenocarcinoma","Lymphoma","Sarcoma","carcinoid"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6875, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 80, '{"id":6875,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":80,"q":"Swallowing breathing reflex - not seen in fetus for ?","o":["14 weeks","12 weeks","16 weeks","Appear in all above period"],"a":1,"e":"Ans. is ''b'' i.e., 12 weeks Behavioural deveopment in intrauterine life Muscle contractions first appear around 8 wk, soon followed by lateral flexion movements. By 13-14 wk, breathing and swallowing motions appear and tactile stimulation elicits graceful movements. o The grasp reflex appears at 17 wk and is well developed by 27 wk. Eye opening occurs around 26 wk. During the 3rd trimester, fetuses respond to external stimuli with heart rate elevation and body movements","pyqMatches":[{"year":"2014","no":1625,"q":"Swallowing breathing reflex - not seen in fetus for ?","o":["14 weeks","12 weeks","16 weeks","Appear in all above period"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6876, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 81, '{"id":6876,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":81,"q":"Most common site of extra - pulmonary TB in children is ?","o":["Abdominal","Genitourinary","Lymphnode","Congenital"],"a":2,"e":"Ans. is ''c'' i.e., Lymphnode Most common site of extra pulmonary TB is lymphnode Most children who develop tuberculosis disease experience pulmonary manifestations 25 to 35 percent of children have an extrapulmonary presentation. The most common extrapulmonary form of tuberculosis is lymphatic disease accounting for about two thirds of cases of extrapulmonary tuberculosis. the second most common form is meningeal disease occurring in 13% of patients","pyqMatches":[{"year":"2014","no":1666,"q":"Most common site of extra - pulmonary TB in children is ?","o":["Abdominal","Genitourinary","Lymphnode","Congenital"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6877, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 82, '{"id":6877,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":82,"q":"Characteristics of SMR-2 in boys ?","o":["Appearance of pubic hair","Appearance of axillary hair","Enlargement of scrotum","All of above"],"a":2,"e":"Ans. is ''c'' i.e., Enlargement of scrotum Scanty & long pubic hair appear at SMR-2. Enlargement of scrotum is there at SMR-2.","pyqMatches":[{"year":"2014","no":1626,"q":"Characteristics of SMR-2 in boys ?","o":["Appearance of pubic hair","Appearance of axillary hair","Enlargement of scrotum","All of above"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6878, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 83, '{"id":6878,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":83,"q":"Pedigree analysis chart?","o":["Used for growth monitoring","To assess side effect during chemotherapy","Used to see gentic transmission","To assess developmental delay in infant"],"a":2,"e":"Ans. is ''c'' i.e., Used to see genetic transmission Pedigree Provide graphic depiction of a family structure medical history. Person providing information is formed as proband. Special symbol is used for each designation. Three generation pedigree should be made. Closer the relationship of proband to the person, greater is change of shared genetic component.","pyqMatches":[{"year":"2014","no":1646,"q":"Pedigree analysis chart?","o":["Used for growth monitoring","To assess side effect during chemotherapy","Used to see gentic transmission","To assess developmental delay in infant"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6879, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 84, '{"id":6879,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":84,"q":"21-Hydroxylase deficiency - false is ?","o":["Most common cause of congenital adrenal hyperlasia","Autosomal recessive","Femal pseudo hermaphroditism","Male pseudo hermephroditism"],"a":3,"e":"Ans. is ''d'' i.e., Male pseudo hermephroditism Congenital adrenal hvperplasia (CAH) Group of AR disorder MC adrenal disorder in childhood Most common 21-hydroxylase deficiency =There is elevated level of pregenolone, 17 -OH pergenelone DHEA and decreas level of progesterone, deoxycortisol,and estradiol so 21 hydroxylase deficiency causes female pseudoher​maphroditism.","pyqMatches":[{"year":"2014","no":1650,"q":"21-Hydroxylase deficiency - false is ?","o":["Most common cause of congenital adrenal hyperlasia","Autosomal recessive","Femal pseudo hermaphroditism","Male pseudo hermephroditism"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6880, 'Pediatrics', 'Hematology', 'Easy', 'Pediatrics (1)', 85, '{"id":6880,"subject":"Pediatrics","chapter":"Hematology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":85,"q":"AML best prognosis is seen with ?","o":["Acute myelo monocytic leukemia.","Acute monocytic leukemia.","Acute promyeloblastic lukemia (M.3).","Erythro leukemia"],"a":2,"e":"Ans. is ''c'' i.e., Acute promyeloblastic leukemia (M.3) Acute promycloblastic leukemia Also known as M-3 Associated with t(15:17) DIC, chloromas common Very responsine to retinoic acid combined with anthracylines. M.7 (acute megakaryocytic leukemia) mostly seen in down syndrome. French-American-British (FAB) Classification of Acute Myelogenous Leukemia","pyqMatches":[{"year":"2015","no":460,"q":"AML best prognosis is seen with ?","o":["Acute myelo monocytic leukemia.","Acute monocytic leukemia.","Acute promyeloblastic lukemia (M.3).","Erythro leukemia"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6881, 'Pediatrics', 'Hematology', 'Easy', 'Pediatrics (1)', 86, '{"id":6881,"subject":"Pediatrics","chapter":"Hematology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":86,"q":"Ideal time to start Iron therapy in a marasamic child with fever and hemoglobin 7 gm% is","o":["Immedietly","At discharge","When fever goes down","At any time"],"a":2,"e":"Ans. is ''c'' i.e., When fever goes down Iron at 3 mg/kg 1 day should started when child gaining weight once stabilisation phase is over. o The core of the accepted WHO management protocol is 10 steps in two phases ?","pyqMatches":[{"year":"2014","no":1668,"q":"Ideal time to start Iron therapy in a marasamic child with fever and hemoglobin 7 gm% is","o":["Immedietly","At discharge","When fever goes down","At any time"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6882, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 87, '{"id":6882,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":87,"q":"Most common cardio vascular abnormality in down syndrome is ?","o":["VSD","Endocardial cushion defect","TOF","COA"],"a":1,"e":"Ans. is ''b'' i.e., Endocardial cushion defect About 40% of down syndrome have CHD. Endocardial cushion Atrio ventricular septal defect account for 40- 60% of cases. Other feature in down syndrome. Hypotonia, flat face, upward and slanted palpebral fissures and epicanthic folds, speckled irises (Brushfield spot);varying degrees of mental and growth retardation;dysplasia of the pelvis, cardiac malformations, and simian crease;short, broad hands, hypoplasia of middle phalanx of 5th finger, duodenal atresia, and high arched palate;5% of patients with Down syndrome are the result of a translocation-t(14q21q), t(15q21q), and t(13q21q)-in which the phenotype is the same as trisomy 21. Other feature ?","pyqMatches":[{"year":"2014","no":1607,"q":"Most common cardio vascular abnormality in down syndrome is ?","o":["VSD","Endocardial cushion defect","TOF","COA"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6883, 'Pediatrics', 'Infectious Diseases', 'Easy', 'Pediatrics (1)', 88, '{"id":6883,"subject":"Pediatrics","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":88,"q":"Most common cause of lower respiratory tract infection in 3 year old child is","o":["Klebsella","H-influenza","Streptococcal pneumonia","Staphe aureus"],"a":2,"e":"Ans. is ''c'' i.e., Streptococcal pneumonia Most common cause of paediatric pneumonia is respiratory syncytial virus (RSV). Other viruses causing pneumonia are influenza virus (2^d most common virus), adenovirus, rhinovirus, and parainfluenza virus. Most common bacterial cause of pediatric pneumonia is streptococus pneumoniae (pneumococcus). Bacteria causing atypical pneumonia commonly are mycoplasma and chlamydia.","pyqMatches":[{"year":"2014","no":1635,"q":"Most common cause of lower respiratory tract infection in 3 year old child is","o":["Klebsella","H-influenza","Streptococcal pneumonia","Staphe aureus"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6884, 'Pediatrics', 'Neurology', 'Easy', 'Pediatrics (1)', 89, '{"id":6884,"subject":"Pediatrics","chapter":"Neurology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":89,"q":"Non-obstructive hydrocephalus - true is ?","o":["Also kin communicating hydrocephalus","Due to obliteration of subarachrod cistemae or malfunction of arachnoid villi","Dilatation of all 4 ventricle","All of above"],"a":3,"e":"Ans. is ''d'' i.e., All of above H hy_LQggPllalus is not a specific disease; rather, it represents a diverse group of conditions that result from impaired circulation and absorption of CSF or, in the rare circumstance, from increased production by a choroid plexus papilloma flyLk.QCSPLlalus resulting from obstruction within the ventricular system is called obstructive or noncommunicating hydrocephalus The CSF circulates from the basal cisterns posteriorly through the cistern system and over the convexities of the cerebral hemispheres. CSF is absorbed primarily by the arachnoid villi through tight junctions of their endothelium by the pressure forces that were noted earlier. CSF is absorbed to a much lesser extent by the lymphatic channels directed to the paranasal sinuses, along nerve root sleeves, and by the choroid plexus itself. Hydrocephalus resulting from obliteration of the subarachnoid cisterns or malfunction of the arachnoid villi is called nonobstructive or communicating hydrocephalus","pyqMatches":[{"year":"2014","no":1669,"q":"Non-obstructive hydrocephalus - true is ?","o":["Also kin communicating hydrocephalus","Due to obliteration of subarachrod cistemae or malfunction of arachnoid villi","Dilatation of all 4 ventricle","All of above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6885, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 90, '{"id":6885,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":90,"q":"Prader willi syndrome, chromosomal defect?","o":["Chromosome 15","Chromosome 5","Chromosome 10","Chromosome 21"],"a":0,"e":"Ans. is ''a'' i.e., Chromosome 15 Prader-Willi syndrome is a complex genetic condition that affects many parts of the body. In infancy, this condition is characterized by weak muscle tone (hypotonia), feeding difficulties, poor growth, and delayed development. Beginning in childhood, affected individuals develop an insatiable appetite, which leads to chronic overeating (hyperphagia) and obesity. Some people with Prader-Willi syndrome, particularly those with obesity, also develop type 2 diabetes mellitus (the most common form of diabetes). People with Prader-Willi syndrome typically have mild to moderate intellectual impairment and learning disabilities. o Behavioral problems are common, including temper outbursts, stubbornness, and compulsive behavior such as picking at the skin. Sleep abnormalities can also occur. Additional features of this condition include distinctive facial features such as a narrow forehead, almond-shaped eyes, and a triangular mouth; short stature; and small hands and feet. Some people with Prader-Willi syndrome have unusually fair skin and light-colored hair. Both affected males and affected females have underdeveloped genitals. Puberty is delayed or incomplete, and most affected individuals are unable to have children (infertile).","pyqMatches":[{"year":"2014","no":1647,"q":"Prader willi syndrome, chromosomal defect?","o":["Chromosome 15","Chromosome 5","Chromosome 10","Chromosome 21"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6886, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 91, '{"id":6886,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":91,"q":"Minimum interval between 2 live vaccine immunization ?","o":["2 weeks","4 weeks","6 week","8 weeks"],"a":1,"e":"Ans. is ''b'' i.e., 4 weeks Basic principle of immunization Minimum 4 week interval recommended between 2 live vaccine administration except OPV and oral typhoid. Two or more killed vaccine may be administrated simultaneously or at any given interval A live and killed vaccine given simultaneously but at different site. If immunisation status unknown, give age appropriate vaccine Mixing of vaccine in same syringe not recommended Live vaccine should be avoided in AIDS,","pyqMatches":[{"year":"2014","no":1674,"q":"Minimum interval between 2 live vaccine immunization ?","o":["2 weeks","4 weeks","6 week","8 weeks"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6887, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 92, '{"id":6887,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":92,"q":"Fanconi''s anemia - false is ?","o":["Autosomal recessive","Pancytopenia","Type I RTA","All are true"],"a":2,"e":"Ans. is ''c'' i.e., Type I RTA Fanconi anemia Autosomal recessive Pancytopenia Hyper pigmentation of trunk, neck, and inlertriginous area. Growth failure Fanconi facies (small head, small eyes) Renal abormality Proximal RTA (type II RTA) Renal tubular acidosis 3 types Distal RTA (type I) Proximal RTA (type II) Hyperkalemic RTA (type IV)","pyqMatches":[{"year":"2014","no":1656,"q":"Fanconi''s anemia - false is ?","o":["Autosomal recessive","Pancytopenia","Type I RTA","All are true"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6888, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 93, '{"id":6888,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":93,"q":"In marasmus wasting is due to ?","o":["Prolonge dietery deficiency of calori","Prolonge dietery deficiency of protein","Excess catabolism of fat & muscle mass to provide energy","All of above"],"a":3,"e":"Ans. is ''d'' i.e., All of above Marasmus Prolonge deficiency of calory & protein due to starvation. Monkey facies- loss of buccal fat. Baggy pants appearance- loose skin of the buttocks hanging down. Loss of axillary fat. Appetite is preserved. No edema.","pyqMatches":[{"year":"2014","no":1628,"q":"In marasmus wasting is due to ?","o":["Prolonge dietery deficiency of calori","Prolonge dietery deficiency of protein","Excess catabolism of fat & muscle mass to provide energy","All of above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6889, 'Pediatrics', 'Nephrology', 'Moderate', 'Pediatrics (1)', 94, '{"id":6889,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":94,"q":"A child having H/0 profuse watery diarrhoea not taking oraly and not passed urine since 2 days, what to be given","o":["Milk","ORS","I.V. fluid","I.V. antibiotic"],"a":2,"e":"Ans. is ''c'' i.e., I.V. fluid Child having history of profuse watery diarrhoea with poor oral intake and not passed urine since 2 days is suffering from diarrhoea with dehydration and probably acute renal failure of pre renal types. Here best choice is intravenous I.V. fluid If I.V. access not possible, then you can give feed through Ryle''s tube or intra osseous fluid.","pyqMatches":[{"year":"2014","no":1675,"q":"A child having H/0 profuse watery diarrhoea not taking oraly and not passed urine since 2 days, what to be given","o":["Milk","ORS","I.V. fluid","I.V. antibiotic"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6890, 'Pediatrics', 'Neurology', 'Easy', 'Pediatrics (1)', 95, '{"id":6890,"subject":"Pediatrics","chapter":"Neurology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":95,"q":"Febrile seizure most common - age groups?","o":["1 month to 1 year","6 month to 5 year","6 month to 2 year","2 month to 5 year"],"a":1,"e":"Ans. is ''b'' i.e., 6 month to 5 year Febrile convulsion :- Commonest provoked seizure Between 6 months to 5 year Neurologically normal child Occurs when temp rise abruptly Simple benign febrile convulsion Fits occur within 24 hour of onset of fever. Duration less than 10 min. Usually single per febrile episode Generalised type of convulsion Atypical febrile seizures Presence of family history of epilepsy Neurodevelopmental retardation Focal neurological deficit.","pyqMatches":[{"year":"2014","no":1670,"q":"Febrile seizure most common - age groups?","o":["1 month to 1 year","6 month to 5 year","6 month to 2 year","2 month to 5 year"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6891, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 96, '{"id":6891,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":96,"q":"Erythroposis starts in fetal liver during ?","o":["2-4 weeks","4-6 weeks","6-8 weeks","8-10 weeks"],"a":2,"e":"Ans. is ''c'' i.e., 6-8 weeks Developmental hematopoiesis occurs in three anatomic stages:?","pyqMatches":[{"year":"2014","no":1677,"q":"Erythroposis starts in fetal liver during ?","o":["2-4 weeks","4-6 weeks","6-8 weeks","8-10 weeks"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6892, 'Pediatrics', 'Nephrology', 'Easy', 'Pediatrics (1)', 97, '{"id":6892,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":97,"q":"Fluid of choice in child with burn < 24 hour is","o":["Fresh frozen plasma","Isolye-P","Ringer lactate","Platlet tranfusion"],"a":2,"e":"Ans. is ''c'' i.e., Ringer lactate Fluid resuscitation in burn injury Parkland formulaa a. Initial 24 hours: Ringer''s lactated (RL) solution 4 ml/kg/% burn for adults and 3 ml/kg/% burn for children. RL solution is added for maintenance for children: a. 4 ml/kg/hour for children weighing 0-10 kg b. 40 ml/hour +2 ml/hour for children weighing 10-20 kg c. 60 ml/hour + 1 ml/kg/hour for children weighing 20 kg or higher This formula recommends no colloid in the initial 24 hours. b Next 24 hours: Colloids given as 20-60% of calculated plasma volume. No crystalloids. Glucose in water is added in amounts required to maintain a urinary output of 0.5-1 ml/hour in adults and 1 ml/hour in children.","pyqMatches":[{"year":"2014","no":1676,"q":"Fluid of choice in child with burn < 24 hour is","o":["Fresh frozen plasma","Isolye-P","Ringer lactate","Platlet tranfusion"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6893, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 98, '{"id":6893,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":98,"q":"Antiendomysial antibody is used in screening of ?","o":["Myasthenia gravis","Auto immune hepatitis","Coeliac diseases","Graves disease"],"a":0,"e":"Ans. is ''a'' i.e., Coeliac diseases Coeliac disea.se (CD) is a permanent intolerance of the small intestine to gluten, characterized by gluten-dependent changes in villous morphology and/or signs of immunological activation detectable in the lamina propria of intestinal mucosa. The presence of serum anti-endomysial antibodies (EMA) is generally considered to be highly suggestive for CD because of their high values of sensitivity and specificity. Other antibodies used for diagnosis Tissue transglutaminase, Antigliadin antibodies Treatment is Gluten-free diet","pyqMatches":[{"year":"2014","no":1678,"q":"Antiendomysial antibody is used in screening of ?","o":["Myasthenia gravis","Auto immune hepatitis","Coeliac diseases","Graves disease"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6894, 'Pediatrics', 'Nephrology', 'Easy', 'Pediatrics (1)', 99, '{"id":6894,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":99,"q":"In congenital adrenal hyperplasia precocious puberty in male is due to ?","o":["21 alpha hydroxylase deficiency","11(3 hydroxylase deficiency)","Both","None"],"a":2,"e":"Ans. is ''c'' i.e., Both 21 hydroxylase and 3-13-HSD • Salt losing • Virilization of female (Female pseudohermaphroditism) • Precocious puberty in male","pyqMatches":[{"year":"2014","no":1651,"q":"In congenital adrenal hyperplasia precocious puberty in male is due to ?","o":["21 alpha hydroxylase deficiency","11(3 hydroxylase deficiency)","Both","None"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6895, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 100, '{"id":6895,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":100,"q":"First sign of puberty in female ?","o":["Tanner stage I","Tanner stage II","Pubic hair","Axillary hair"],"a":1,"e":"Ans. is `b'' i.e., Tanner stage 11 Thelarche- first sign of puberty in Girl around age of 10 year in Girl Definition :- Begining of secondary (Post natal) breast development at onset of puberty in girls. Tanner stage 2 breast development. Because of rising level of estradiol Breast development during puberty in male termed as gynecomastia not thelarche.","pyqMatches":[{"year":"2014","no":1627,"q":"First sign of puberty in female ?","o":["Tanner stage I","Tanner stage II","Pubic hair","Axillary hair"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6896, 'Pediatrics', 'Neonatology', 'Moderate', 'Pediatrics (1)', 101, '{"id":6896,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":101,"q":"True about bartter''s syndrome are all except ?","o":["Hyperkalemic alkalosis","Presents in neonate with ototoxicity have bartin gene mutation","Decreased K+ assorption from thick descending loop","Autosomal recessive"],"a":0,"e":"Ans. is ''a'' i.e., Hyperkalemic alkalosis Antibodies in coeliac disease are anti-endomysian, antigliadin and anti-transglutaminase.","pyqMatches":[{"year":"2014","no":1679,"q":"True about bartter''s syndrome are all except ?","o":["Hyperkalemic alkalosis","Presents in neonate with ototoxicity have bartin gene mutation","Decreased K+ assorption from thick descending loop","Autosomal recessive"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6897, 'Pediatrics', 'Cardiology', 'Easy', 'Pediatrics (1)', 102, '{"id":6897,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":102,"q":"Drug used in congenital heart disease to keep PDA patent","o":["PGEi","PGE2","PGI2","Indomethacin"],"a":0,"e":"Ans. is ''a'' i.e., PGE, Prostaglandin El (PGE1) infusion usually effective in keeping the ductus arteriosus open before surgical intervention to reduce hypoxemia and acidemia before surgery in ductus dependent lesion like. Pulmonary atresia TOF with severe PS TOF with pulmonary atresia Transposition of great arteries with VSD and PS Indomethacin is used for ductal closure","pyqMatches":[{"year":"2014","no":1610,"q":"Drug used in congenital heart disease to keep PDA patent","o":["PGEi","PGE2","PGI2","Indomethacin"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6898, 'Pediatrics', 'Cardiology', 'Easy', 'Pediatrics (1)', 103, '{"id":6898,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":103,"q":"Figure of 8 in chest X-ray ?","o":["Supracardiac TAPVC","Tetralogy of fallot","TGA","None of above"],"a":0,"e":"Ans. is ''a'' Supracardiac TAPVC Tertralogy of fallot—* boot shaped heart Transposition of great vessel-* egg on side TPVC (supracardioe) --> snownan or figure of 8 configuration","pyqMatches":[{"year":"2014","no":1608,"q":"Figure of 8 in chest X-ray ?","o":["Supracardiac TAPVC","Tetralogy of fallot","TGA","None of above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6899, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 104, '{"id":6899,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":104,"q":"False regarding croup is ?","o":["Disease include epiglottis, laryngitis, laryngotrachictis","Brassy cough is main presenting feature","Causes upper airway obstruction","All of above"],"a":2,"e":"Ans. is ''c'' i.e., Causes upper airway obstruction Croup is variety of condition which include acute epiglottis, laryngitis, trachiobronchitis. Infection of lower respiratory tract. Brassy cough main presenting feature. Treatment Humidified I.V. fluid Antibiotics Nebulisation Steroid.","pyqMatches":[{"year":"2014","no":1636,"q":"False regarding croup is ?","o":["Disease include epiglottis, laryngitis, laryngotrachictis","Brassy cough is main presenting feature","Causes upper airway obstruction","All of above"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6900, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 105, '{"id":6900,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":105,"q":"Most common intra abdominal solid organ tumor in child is ?","o":["Neuroblastoma","Rhabdomyoblastoma","Wilm''s tumor","Hypernephroma"],"a":0,"e":"Ans. is ''a'' i.e., Neuro blastoma Most common abdominal cancer of childhood. Most common cancer of infancy. Most common extracranial solid tumor of childhood (most common solid tumor of childhood is brain tumor).","pyqMatches":[{"year":"2013","no":1468,"q":"Most common intra abdominal solid organ tumor in child is ?","o":["Neuroblastoma","Rhabdomyoblastoma","Wilm''s tumor","Hypernephroma"],"a":0,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":1644,"q":"Most common intra abdominal solid organ tumor in child is ?","o":["Neuroblastoma","Rhabdomyoblastoma","Wilm''s tumor","Hypernephroma"],"a":0,"source":"NEET_2014_Paper.pdf"},{"year":"2016","no":1382,"q":"Most common intra abdominal solid organ tumor in child is ?","o":["Neuroblastoma","Rhabdomyoblastoma","Wilm''s tumor","Hypernephroma"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2013","2014","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6901, 'Pediatrics', 'Infectious Diseases', 'Easy', 'Pediatrics (1)', 106, '{"id":6901,"subject":"Pediatrics","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":106,"q":"Koplik spot true is ?","o":["Pathognomic of measls","Present on buccal mucosa opposite P'' molar","Always present","All of above"],"a":0,"e":"Ans. is ''a'' i.e., Pathognomic of measls Measle Caused by RNA virus. Highly contagious droplet spread from secretion of nose and throat 4 day before and 5 days after rash. Secondary attack rate >90% in contact. Prodromal phase - characterized by fever, rhinorrhea, conjuctival congestion and dry hackig cough. Koplik spots-bluish-gray specks or \"grains of sand\" on a red base- develop on the buccal mucosa opposite the second molars Generally appear 1-2 days before the rash and last 3-5 days Pathognomonic for measles, but not always present Rash appears on D4 first behind pinna on neck the spread of face, thrunk and abdomen. SSPE is long term complication seen in measls.","pyqMatches":[{"year":"2014","no":1637,"q":"Koplik spot true is ?","o":["Pathognomic of measls","Present on buccal mucosa opposite P'' molar","Always present","All of above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6902, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 107, '{"id":6902,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":107,"q":"Exchange blood transfusion what is used ?","o":["Whole blood","EPP","Serum","Pack cell"],"a":0,"e":"Ans. is ''a'' i.e., Whole blood Exchange transfusion is the process of slowly removing patient blood and replacing with fresh donor whole blood.","pyqMatches":[{"year":"2014","no":1657,"q":"Exchange blood transfusion what is used ?","o":["Whole blood","EPP","Serum","Pack cell"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6903, 'Pediatrics', 'Cardiology', 'Easy', 'Pediatrics (1)', 108, '{"id":6903,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":108,"q":"Large PDA leads to ?","o":["Endocardial valvulitis","Eisenmenger syndrome","CHF","All of above"],"a":3,"e":"Ans. is ''d'' i.e., All of above Patent ductus arteriosus (PDA) Small PDA may not cause any complication but large defect if untread may leads to : Pulmonary hypertension Left to Right shunt leads to too much circulation of blood in lung which leads to pulmonary hypertension. Eisenmenger''s syndrome - Large standing pulmonary hypertension leads to permanent lung damage and causes Right to Left shunt. Endocarditis. Arrhythmia Enlargement of heart due to PDA increase risk of arrhythmias","pyqMatches":[{"year":"2012","no":1200,"q":"Large PDA leads to ?","o":["Endocardial valvulitis","Eisenmenger syndrome","CHF","All of above"],"a":3,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":1609,"q":"Large PDA leads to ?","o":["Endocardial valvulitis","Eisenmenger syndrome","CHF","All of above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6904, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 109, '{"id":6904,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":109,"q":"ITP false is ?","o":["Plattet transfusion should be avoided","Anticedent history of febrile illness","Overactive immune system","Steroid should be avoided"],"a":3,"e":"Ans. is ''d'' i.e., Steroid should be avoided Idiopathic thrombocytopenic purpura (ITP) Commonest bleeding disorder presenting in children between 1-7 year of age. ITP is proposed to be occur due to over active immune response. Antecedent H/o febrile illness present. Treatment Platlet transfusion should be avoided IVIG or steroid.","pyqMatches":[{"year":"2014","no":1658,"q":"ITP false is ?","o":["Plattet transfusion should be avoided","Anticedent history of febrile illness","Overactive immune system","Steroid should be avoided"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6905, 'Pediatrics', 'Nephrology', 'Easy', 'Pediatrics (1)', 110, '{"id":6905,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":110,"q":"Posterior urethral valve - true A/E ?","o":["Palpable bladder","Hydronephrosis","Painful stress incontinence","Recurrent UTI"],"a":2,"e":"Ans. is `c'' i.e., Painful stress incontinence Posterior urethral valve Most common cause of severe obstructive uropathy in children. 30% of children experienced end stage renal disease/CRF Dilated prostatic urethra. Hypertrophy of bladder muscle Vesicouretic reflux seen in 50% of cases. Back pressure change: Hydronephrosis Distended bladder Thin urinary stream Recurent UTI because of urinary stasis","pyqMatches":[{"year":"2012","no":1215,"q":"Posterior urethral valve - true A/E ?","o":["Palpable bladder","Hydronephrosis","Painful stress incontinence","Recurrent UTI"],"a":2,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":1680,"q":"Posterior urethral valve - true A/E ?","o":["Palpable bladder","Hydronephrosis","Painful stress incontinence","Recurrent UTI"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6906, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 111, '{"id":6906,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":111,"q":"In infant, bone marrow biopsy is done from ?","o":["Sternum","Iliac crest","Tibia","All of above"],"a":2,"e":"Ans. is ''c'' i.e., Tibia Sternum : —> Hematopoitically active Site in cooperative patient like adult Ilium : Apprehesive patient Useful in older children & adult Tibia : Useful in newborn & infant and children below 2 year of age.","pyqMatches":[{"year":"2014","no":1659,"q":"In infant, bone marrow biopsy is done from ?","o":["Sternum","Iliac crest","Tibia","All of above"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6907, 'Pediatrics', 'Hematology', 'Easy', 'Pediatrics (1)', 112, '{"id":6907,"subject":"Pediatrics","chapter":"Hematology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":112,"q":"Most common malignancy in children is ?","o":["ALL","AML","Neuroblastoma","Wilm''s tumor"],"a":0,"e":"Ans. is ''a'' i.e., ALL Leukemia is most common malignancy in pediatric age group. o Leukemia / lymphoma = 40% (ALL is more common than AML) CNS Tumor= 30% Embryonal & Sarcoma =10% 2nd most common is CNS Tumor (30%)","pyqMatches":[{"year":"2014","no":1645,"q":"Most common malignancy in children is ?","o":["ALL","AML","Neuroblastoma","Wilm''s tumor"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6908, 'Pediatrics', 'Miscellaneous', 'Hard', 'Pediatrics (1)', 113, '{"id":6908,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":113,"q":"Alopecia thin brittle nail, sparse hair with thin enamel diagnosis is ?","o":["Ectodermal dysplasia","Alopecia aerata","Alopica congenita","None of above"],"a":0,"e":"Ans. is ''a'' i.e., Ectodermal dysplasia Ectodermal dysplasia Group of syndrome All derived from ectodemal structure Abnormalities of two or more ectodermal structure such as Hair Teeth Nail Sweat gland Cranio facial structure Digit","pyqMatches":[{"year":"2014","no":1682,"q":"Alopecia thin brittle nail, sparse hair with thin enamel diagnosis is ?","o":["Ectodermal dysplasia","Alopecia aerata","Alopica congenita","None of above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6909, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 114, '{"id":6909,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":114,"q":"Most common ASD is ?","o":["Ostium primum","Patent foramen ovale","Ostium secondum","Sinus venosus"],"a":2,"e":"Ans. is ''c'' i.e., Osteum secondum ASD can occur in any portion of atrial septum - Secundum Primum Sinus venosus Absent atrial septum (leads to single atrium) Ostium secondum defect Defect in region of fossa ovalis Most common form of ASD","pyqMatches":[{"year":"2014","no":1606,"q":"Most common ASD is ?","o":["Ostium primum","Patent foramen ovale","Ostium secondum","Sinus venosus"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6910, 'Pediatrics', 'Cardiology', 'Easy', 'Pediatrics (1)', 115, '{"id":6910,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":115,"q":"Most common ASD in down syndrome is ?","o":["Ostium primum","Ostium secundum","Absent atrial septum","Sinus venosus"],"a":0,"e":"Ans. is ''a'' i.e., Ostium primum About 40% children with down syndrome have congenital heart disease. Endocardial cushion defect (ASD with ostium primum) account for 40-60% of cases.","pyqMatches":[{"year":"2013","no":1446,"q":"Most common ASD in down syndrome is ?","o":["Ostium primum","Ostium secundum","Absent atrial septum","Sinus venosus"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6911, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 116, '{"id":6911,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":116,"q":"Sitting without support is appear at which month","o":["5 month","6 month","7 month","8 month"],"a":1,"e":"Ans. is ''b'' i.e., 6 month 3 month Neck holding 5 month Roll over 6 month Sits in tripod position 8 month Sitting without support 9 month Stand with support","pyqMatches":[{"year":"2014","no":1619,"q":"Sitting without support is appear at which month","o":["5 month","6 month","7 month","8 month"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6912, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 117, '{"id":6912,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":117,"q":"Weight of child is 70% of normal according to IAP classification, categorised in ?","o":["Mild","Moderate","Severe","Normal"],"a":1,"e":"Ans. is `b'' i.e., Moderate","pyqMatches":[{"year":"2014","no":1634,"q":"Weight of child is 70% of normal according to IAP classification, categorised in ?","o":["Mild","Moderate","Severe","Normal"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6913, 'Pediatrics', 'Neurology', 'Easy', 'Pediatrics (1)', 118, '{"id":6913,"subject":"Pediatrics","chapter":"Neurology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":118,"q":"Influenza vaccine cause ?","o":["Local swelling","Fever","Itching","All of above"],"a":3,"e":"Ans. is ''d'' i.e., All of above Mild problems following inactivated flu vaccine: Soreness, redness, or swelling where the shot was given Hoarseness Sore, red or itchy eyes Cough Fever Aches Headache Itching Fatigue If these problems occur, they usually begin soon after the shot and last 1 or 2 days. Moderate problems following inactivated flu vaccine: Young children who get inactivated flu vaccine and pneumococcal vaccine (PCV13) at the same time may be at increased risk for seizures caused by fever. Ask your doctor for more information. Tell your doctor if a child who is getting flu vaccine has ever had a seizure. Problems that could happen after any vaccine: Brief fainting spells can happen after any medical procedure, including vaccination. Sitting or lying down for about 15 minutes can help prevent fainting, and injuries caused by a fall. Tell your doctor if you feel dizzy, or have vision changes or ringing in the ears. Severe shoulder pain and reduced range of motion in the arm where a shot was given can happen, very rarely, after a vaccination. Severe allergic reactions from a vaccine are very rare, estimated at less than 1 in a million doses. If one were to occur, it would usually be within a few minutes to a few hours after the vaccination.","pyqMatches":[{"year":"2014","no":1639,"q":"Influenza vaccine cause ?","o":["Local swelling","Fever","Itching","All of above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6914, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 119, '{"id":6914,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":119,"q":"Hair an syndrome is consists of ?","o":["Hyperandrogenism","Acanthosis nigricans","Insulin resistance","All of above"],"a":3,"e":"Ans. is ''d'' i.e., All of above HAIR-AN syndrome consists of hyperandrogenism (HA), insulin resistance (IR), and acanthosis nigricans (AN). It is a subset of polycystic ovary syndrome","pyqMatches":[{"year":"2014","no":1683,"q":"Hair an syndrome is consists of ?","o":["Hyperandrogenism","Acanthosis nigricans","Insulin resistance","All of above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6915, 'Pediatrics', 'Nephrology', 'Moderate', 'Pediatrics (1)', 120, '{"id":6915,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":120,"q":"Renal tubuler acidosis with ABG value pH = 7.24 P02=80; PaCO2= 36 Na = 131; HCO3 = 14 C1= 90; BE = -13 Glucose = 135 above ABG picture suggest ?","o":["Metabolic acidosis","Respiratory acidosis","Respiratory alkalosis","Metabolic alkalosis"],"a":0,"e":"Ans. is ''a'' i.e., Metabolic acidosis The given values have low pH, and low HCo2- Indicate metabolic acidosis PCO2 in lower normal range (normal value 35-45 mm/hg)","pyqMatches":[{"year":"2014","no":1684,"q":"Renal tubuler acidosis with ABG value pH = 7.24 P02=80; PaCO2= 36 Na = 131; HCO3 = 14 C1= 90; BE = -13 Glucose = 135 above ABG picture suggest ?","o":["Metabolic acidosis","Respiratory acidosis","Respiratory alkalosis","Metabolic alkalosis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6916, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 121, '{"id":6916,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":121,"q":"Grimace with APGAR score -","o":["0","1","2","3"],"a":1,"e":"Ans. is `b i.e., 1","pyqMatches":[{"year":"2013","no":1455,"q":"Grimace with APGAR score","o":["0","1","2","3"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":1685,"q":"Grimace with APGAR score","o":["0","1","2","3"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6917, 'Pediatrics', 'Cardiology', 'Moderate', 'Pediatrics (1)', 122, '{"id":6917,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":122,"q":"PDA true is all except ?","o":["More common in preterm baby","Left to right shunt","Acyanotic congenital heart disease","More common in term baby"],"a":3,"e":"Ans. is ''d i.e., More common in term baby During fetal life, most of the pulmonary arterial blood is shunted through the ductus arteriosus into the aorta . Functional closure of the ductus normally occurs soon after birth, but if the ductus remains patent when pulmonary vascular resistance falls, aortic blood is shunted into the pulmonary artery. The aortic end of the ductus is just distal to the origin of the left subclavian artery, and the ductus enters the pulmonary artery at its bifurcation Female patients with PDA outnumber males 2 : 1. PDA is also associated with maternal rubella infection during early pregnancy. It is a common problem in premature infants, where it can cause severe hemodynamic derangements and several major sequelae","pyqMatches":[{"year":"2014","no":1611,"q":"PDA true is all except ?","o":["More common in preterm baby","Left to right shunt","Acyanotic congenital heart disease","More common in term baby"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6918, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 123, '{"id":6918,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":123,"q":"Most common presentation of wilm''s tumor ?","o":["Hematuria","Asymptomatic abdominal mass","Abdominal pain","Headache"],"a":1,"e":"Ans. is `b'' i.e., Asymptomatic abdominal mass Wilm''s tumor (Nephroblastoma) Most common malignant tumor of kidney. 80% of tumor present below 5 year of age. Presention :? Asymptomatic abdominal mass (M.C.). Haematuria (10-25%). Hypertension (25%). Abdominal pain (30%). Fever (20%).","pyqMatches":[{"year":"2012","no":1214,"q":"Most common presentation of wilm''s tumor ?","o":["Hematuria","Asymptomatic abdominal mass","Abdominal pain","Headache"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6919, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 124, '{"id":6919,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":124,"q":"Confirmation of male intersex by?","o":["USG abdomen","Genetic testing","Hormonal study","All of above"],"a":1,"e":"Ans. is ''b'' i.e., Genetic testing Intersex :(DSD) Discrepancy between morphology of gonads and that of extemal genitalia Now Disorder of Sex development (DSD) is preferred instead of intersex Distinctly not defined as male or female Intersex trait not always manitest at both Some as not aware of intersex and it is confirned by Genetic testing Most common is virilisation of female 46 XX DSD. 46 XX DSD - Phenotype is xx & gonads are ovary but external genitalia is virilised. (due to lack of antimullerian hormone (AMH)) Most common is congenital adrenal hyper plasia (CAH) Most commonly 21 a hydroxylase & 11[3 - Hydroxylase deficiency.","pyqMatches":[{"year":"2014","no":1687,"q":"Confirmation of male intersex by?","o":["USG abdomen","Genetic testing","Hormonal study","All of above"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6920, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 125, '{"id":6920,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":125,"q":"Post term baby with tachypnea - commonest cause?","o":["Transient tachypnea of newborn","Meconium aspiration syndrome","Hyaline membrane disease","Infection"],"a":1,"e":"Ans. is ''b'' i.e., meconium aspiration syndrome Transient Tachypnea of the Newborn Transient tachypnea of the newborn is the most common cause of neonatal respiratory distress, constituting more than 40 percent of cases.1 A benign condition, it occurs when residual pulmonary fluid remains in fetal lung tissue after delivery o Respiratory Distress Syndrome Respiratory distress syndrome of the newborn, also called hyaline membrane disease, is the most common cause of respiratory distress in premature infants Immature type II alveolar cells produce less surfactant, causing an increase in alveolar surface tension and a decrease in compliant Meconium Aspiration Syndrome Meconium-stained amniotic fluid occurs in approximately 15 percent of deliveries, causing meconium aspiration syndrome in the infant in 10 to 15 percent of those cases, typically in term and post-term infants Infection Bacterial infection is another possible cause of neonatal respiratory distress. Common pathogens include group B streptococci (GBS), Staphylococcus aureus, Streptococcus pneumoniae, and gram- negative enteric rods. Pneumonia and sepsis have various manifestations, including the typical signs of distress as well as temperature instability","pyqMatches":[{"year":"2014","no":1638,"q":"Post term baby with tachypnea - commonest cause?","o":["Transient tachypnea of newborn","Meconium aspiration syndrome","Hyaline membrane disease","Infection"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6921, 'Pediatrics', 'Rheumatology', 'Easy', 'Pediatrics (1)', 126, '{"id":6921,"subject":"Pediatrics","chapter":"Rheumatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":126,"q":"Major criteria for rheumatic fever - AJE","o":["Carditis","Arthralgia","Erythema marginatum","Subcutaneous nodule"],"a":1,"e":"Ans. is ''b'' i.e., Arthralgia Jone''s criteria Major criteria are : Carditis, arthritis, subcutaneous natule, chorea, and erythema marginatum","pyqMatches":[{"year":"2014","no":1613,"q":"Major criteria for rheumatic fever - AJE","o":["Carditis","Arthralgia","Erythema marginatum","Subcutaneous nodule"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6922, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 127, '{"id":6922,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":127,"q":"0.9% NaCI contains True as?","o":["0.9 gm of Nacl in 1000 ml of fluid","77 meg of sodium is 1000 ml of fluid","154 meg of chloride in 1000 ml of fluid","30 meg of sodium in 1000 ml of fluid."],"a":2,"e":"Ans. is ''c'' i.e., 154 meq of chloride in 1000 ml of fluid Nomal saline (Isotonic saline) Contains - 9 gms of Nacl in 1000 ml of fluid 154 meq/sodium in 1000 ml of fluid 154 meq Chloride in 1000 ml of fluid","pyqMatches":[{"year":"2014","no":1686,"q":"0.9% NaCI contains True as?","o":["0.9 gm of Nacl in 1000 ml of fluid","77 meg of sodium is 1000 ml of fluid","154 meg of chloride in 1000 ml of fluid","30 meg of sodium in 1000 ml of fluid."],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6923, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 128, '{"id":6923,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":128,"q":"Handedness develops by age of?","o":["2 years","3 years","4 years","5 years"],"a":1,"e":"Ans. is ''b'' i.e., 3 year Handedness is usually established by the 3rd yr. Frustration may result from attempts to change children''s hand preference. Variations in fine motor development reflect both individual proclivities and different opportunities for learning. Children who are seldom allowed to use crayons, for example, develop a mature pencil grasp later","pyqMatches":[{"year":"2014","no":1621,"q":"Handedness develops by age of?","o":["2 years","3 years","4 years","5 years"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6924, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 129, '{"id":6924,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":129,"q":"Drug used in neonatal resuscitation","o":["Adrenaline","Soda bi carbonate","Naloxone","All of above"],"a":3,"e":"Ans. is ''d'' i.e., All of above Drug used during neonatal resuscitation Epinephrine./Adrenalin NS or RL Naloxone Sodium-by-carbonate","pyqMatches":[{"year":"2014","no":1688,"q":"Drug used in neonatal resuscitation","o":["Adrenaline","Soda bi carbonate","Naloxone","All of above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6925, 'Pediatrics', 'Nephrology', 'Easy', 'Pediatrics (1)', 130, '{"id":6925,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":130,"q":"Delayed puberty in female?","o":["No breast budding in 10 years","Menarche > 16 year","menarche > 1 year of brean budding","FSH"],"a":1,"e":"Ans. is ''b'' i.e., Menarche > 16 year Delayed Puberty More common in boy than girl Most common cause in constitutional delay Girls-Delayed puberty is defined as Lack of secondary sexual character by age of 17 years Absence of menarche by age of 16 year 5 year after pubertal onset. Boys-Lack of pubertal changes by the age of 14 years.","pyqMatches":[{"year":"2014","no":1653,"q":"Delayed puberty in female?","o":["No breast budding in 10 years","Menarche > 16 year","menarche > 1 year of brean budding","FSH"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6926, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 131, '{"id":6926,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":131,"q":"Reye syndrome false is?","o":["Associated with salicylate ingestion","Hepatomegaly","Jaundice","Hypoglycemia"],"a":2,"e":"Ans. is ''c'' i.e., Jaundice Reve syndrome Detrimental effects to many organs, especially the brain and liver, as well as causing low blood sugar and increase ammonia level. Secondary Mitochondria hepatopathy H/o viral injection (Influenza, varicella) & salicylate interactions. Higher mortality rate. The disease causes fatty liver with minimal inflammation and cerebral edema (swelling of the brain). Jaundice is not usually present. With raised enzyme with normal bilirubin. Children of ages 4 to 12 are most commonly afflicted. Early diagnosis is vital; although most children recover with supportive therapy, it may lead to severe brain injury and death","pyqMatches":[{"year":"2014","no":1689,"q":"Reye syndrome false is?","o":["Associated with salicylate ingestion","Hepatomegaly","Jaundice","Hypoglycemia"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6927, 'Pediatrics', 'Gastroenterology', 'Hard', 'Pediatrics (1)', 132, '{"id":6927,"subject":"Pediatrics","chapter":"Gastroenterology","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":132,"q":"3 year old child come in ER with H/o vomiting, loose watey motion for 3 days. on examination, child was drowsy, sunken eye. Hypothermia and skin pinch take time to revert back, diagnosis?","o":["No dehydration","Mild dehydration","Some dehydration","Severe dehydration"],"a":3,"e":"Ans. is ''d'' i.e., Severe dehydration A child with severe dehydration will have at least two of the following four signs : sensorium is abnormally sleepy or lethargic, sunken eyes, drinking poorly or not at all, and a very slow skin pinch. A child with some signs of dehydration will have two of the following : restlessness or irritability, sunken eyes, drinking eagerly or slow skin pinch. A child with either one or none of these signs is classified as having no signs of dehydration.","pyqMatches":[{"year":"2014","no":1690,"q":"3 year old child come in ER with H/o vomiting, loose watey motion for 3 days. on examination, child was drowsy, sunken eye. Hypothermia and skin pinch take time to revert back, diagnosis?","o":["No dehydration","Mild dehydration","Some dehydration","Severe dehydration"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6928, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 133, '{"id":6928,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":133,"q":"In duschene the knee jerk ?","o":["Exaggerrated","Decrease","May be normal initially lateron increase","May be normal initially lateron decrease"],"a":3,"e":"Ans. is ''d'' i.e., May be normal initially lateron decrease Duchenne and Becker''s muscular dystrophy. X-like recessive So expression of gene is essentially confirmed in males. Females are affected only if X-chromosome carrying the normal allele is lost or inactivated Becker is milder form with late onset and slow progression. In duchenni, onset is early with deloyed misection. Pseudohypertrophy of calf muscle, glutei, deltiod, Gower sign may positive at age of 3 year. Cardiac involvement started at 10 year of age. Deep tendon reflexes remain normal or are decreased in patients with DMD. Ankle jerks are relatively preserved until the terminal stages, while the knee jerk reflex is less brisk than the ankles by age six, but is eventually lost. Histopathology shows diffuse degeneration & regeneration of muscle fibre. Serum CPX are markedly high.","pyqMatches":[{"year":"2014","no":1691,"q":"In duschene the knee jerk ?","o":["Exaggerrated","Decrease","May be normal initially lateron increase","May be normal initially lateron decrease"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6929, 'Pediatrics', 'Nephrology', 'Hard', 'Pediatrics (1)', 134, '{"id":6929,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":134,"q":"Intra uterine hydronephrosis of 32-34 weeks-management?","o":["Intrauterine drainage","Wait until 3 weeks","Immediate delivery","Require serial USG and other associated anomalies"],"a":3,"e":"Ans. is `d'' i.e., Require serial USG and other associated anomalies Antenatal hydronephrosis (ANH) is transient and resolves by the third trimester in almost one-half cases. The presence of oligohydramnios and additional renal or extrarenal anomalies suggests significant pathology. o All patients with ANH should undergo postnatal ultrasonography The intensity of subsequent evaluation depends on anteroposterior diameter (APD) of the renal pelvis and/or Society for Fetal Urology (SFU) grading. Patients with postnatal APD exceeding 10 mm and/or SFU grade 3- 4 should be screened for upper or lower urinary tract obstruction and vesicoureteric reflux. Surgery is considered in patients with increasing renal pelvic APD and/or an obstructed renogram with differential renal function <35- 40% or its subsequent decline.","pyqMatches":[{"year":"2014","no":1692,"q":"Intra uterine hydronephrosis of 32-34 weeks-management?","o":["Intrauterine drainage","Wait until 3 weeks","Immediate delivery","Require serial USG and other associated anomalies"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6930, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 135, '{"id":6930,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":135,"q":"Child knows his/her sex by age of?","o":["2 year","3 year","4 year","5 year"],"a":1,"e":"Ans. is ''b'' i.e., 3 year Rides tricycle Stands momentarily on one foot. Draws a circle Can dress or undress himself completely Builds tower of 10 cubes Knows his age and sex. Repeat a sentence of 6 syllables Has a vocabulary of 250 words. Counts 3 objects correctly. Can withhold and postpone bowel movement.","pyqMatches":[{"year":"2014","no":1620,"q":"Child knows his/her sex by age of?","o":["2 year","3 year","4 year","5 year"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6931, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 136, '{"id":6931,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":136,"q":"True about SLE is?","o":["Autoimmune disease","Childhood SLE had poor prognosis than adult SLE","Presence of ANA","All are true"],"a":3,"e":"Ans. is ''d'' i.e., All are true SLE (sytemic lupus Erythematosus) Autoimmune disorder Inflammation of blood vessel Childhood SLE had poor pnognosis than adult SLE Hall mark of SLE is presence of antinuclean antibody (ANA) More common in female. Malar rash in pathognomic of SLE Non - erosive arthritis Nephritis Encephalopathy Pleuritis / Pericarditis Cytopenia","pyqMatches":[{"year":"2014","no":1695,"q":"True about SLE is?","o":["Autoimmune disease","Childhood SLE had poor prognosis than adult SLE","Presence of ANA","All are true"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6932, 'Pediatrics', 'Neonatology', 'Hard', 'Pediatrics (1)', 137, '{"id":6932,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":137,"q":"Case of hemorrhagic disease of newborn bleed on 2nd day?","o":["2, 7, 9, 10","3, 7, 9, 10","2, 8, 9, 10","2, 5, 9, 10"],"a":0,"e":"Ans. is ''a'' i.e., 2, 7, 9, 10 Hemorrhagic disease of newborn is due to deficiency of Vitamin K dependent factors —> II, VII, IX and X.","pyqMatches":[{"year":"2014","no":1660,"q":"Case of hemorrhagic disease of newborn bleed on 2nd day?","o":["2, 7, 9, 10","3, 7, 9, 10","2, 8, 9, 10","2, 5, 9, 10"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6933, 'Pediatrics', 'Nephrology', 'Easy', 'Pediatrics (1)', 138, '{"id":6933,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":138,"q":"8 year old child with hematuria in 5 days after throat infection?","o":["Post streptococcal nephropathy","Ig A nephropathy","Nephrotic syndrome","can be a or b"],"a":1,"e":"Ans. is ''b''i.e., Ig A Nephnopathy IgA nephropathy Predominant deposition of IgA in glomeruli. RECURRENT episode of gross rematuria that also precipitation by URTI in last 2-5 days. PSGN Acute GN following infection by group A - -hemolytic streptococci. Common in school age children. o Streptococcal infection usually of throat (4 or 12 strain) or skin (strain 49) by 1-4 week prior to AGN. Edema, oliguria, hypertension, ARF, hematurea of abrupt onset.","pyqMatches":[{"year":"2014","no":1696,"q":"8 year old child with hematuria in 5 days after throat infection?","o":["Post streptococcal nephropathy","Ig A nephropathy","Nephrotic syndrome","can be a or b"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6934, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 139, '{"id":6934,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":139,"q":"Hemophilia X-linked?","o":["Hemophilia A","Hemophilia B","Hemophilia C","Both A & B"],"a":3,"e":"Ans. is ''D'' i.e., Both a & b Hemophilia A (also known as classic hemophilia or factor VIII deficiency) and hemophilia B (also known as Christmas disease or factor IX deficiency) are inherited in an X-linked recessive pattern. Haemophilia C is caused by a deficiency of coagulation factor XI and is distinguished from haemophilia A and B by the fact it does not lead to bleeding into the joints. Furthermore, it has autosomal recessive inheritance","pyqMatches":[{"year":"2014","no":1648,"q":"Hemophilia X-linked?","o":["Hemophilia A","Hemophilia B","Hemophilia C","Both A & B"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6935, 'Pediatrics', 'Growth & Development', 'Moderate', 'Pediatrics (1)', 140, '{"id":6935,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":140,"q":"Kwashiorkor not true is?","o":["Apathy","Flaky paint dermatosis","Increased transaminase","Voracious appetit"],"a":3,"e":"Ans. is ''d'' i.e., Voracious appetite There is decreased appetite in kwasiorkor (not varacious appetite). Kwashiorkar Kwashiorkar represents the uncompensated phase of PEM. It is characterized by classical ''triad'' of edema (Due to hypoalbuminemia), markedly retarded growth, and psychomotor (mental) changes","pyqMatches":[{"year":"2014","no":1629,"q":"Kwashiorkor not true is?","o":["Apathy","Flaky paint dermatosis","Increased transaminase","Voracious appetit"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6936, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 141, '{"id":6936,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":141,"q":"Most common cardiac defect in Turner syndrome","o":["Coartaction of aorta","VSD","ASD","TOF"],"a":0,"e":"Ans. is ''a'' i.e., Coartaction of aorta Disorders Associated with Turner Syndrome Short stature Congenital lymphedema Horseshoe kidney Patella dislocation Increased carrying angle of elbow Madelung deformity (chondrodysplasia of distal radial epiphysis) Congenital hip dislocation Scoliosis Widespread nipples Shield chest Redundant nuchal skin (in utero cystic hygroma) Low posterior hairline Coarctation of aorta Bicuspid aortic valve Cardiac conduction abnormalities Hypoplastic left heart syndrome Gonadal dysgenesis (infertility, primary amenorrhea) Gonadoblastoma (if Y chromosome material present) Learning disabilities (nonverbal perceptual motor and visuospatial skills) [in 70%] Developmental delay (in 10%) Social awkwardness Hypothyroidism (acquired in 15-30%) Type 2 diabetes mellitus (insulin resistance) Strabismus Cataract Red-green colorblindness (as in males) Recurrent otitis media Sensorineural hearing loss Inflammatory bowel disease Celiac disease","pyqMatches":[{"year":"2014","no":1615,"q":"Most common cardiac defect in Turner syndrome","o":["Coartaction of aorta","VSD","ASD","TOF"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6937, 'Pediatrics', 'Nephrology', 'Easy', 'Pediatrics (1)', 142, '{"id":6937,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":142,"q":"In HSP gross hematurea is seen in what % of children?","o":["5 - 10%","10 - 20%","20 - 30%","30 - 40%"],"a":2,"e":"Ans. is ''c'' i.e., 20 - 30% Henoch-schonlein_purpura (HSP) Small vessel vasculitis Purpuric rash Arthritis Abdominal pain Glomerulonephritis Gross hematuria is seen in 20-30% of cases","pyqMatches":[{"year":"2014","no":1698,"q":"In HSP gross hematurea is seen in what % of children?","o":["5 - 10%","10 - 20%","20 - 30%","30 - 40%"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6938, 'Pediatrics', 'Miscellaneous', 'Hard', 'Pediatrics (1)', 143, '{"id":6938,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":143,"q":"Child has lesion on buttocks since 2 year spreading peripherally with central scarring non symptomatic diagnosis?","o":["Erythema annular cetrifugam","Erythema migrains","Erythema marginatum","Erythema Gyratum"],"a":0,"e":"Ans. is ''a'' i.e., Erythema annulase cetrifugam Erythema annulare centrifugum : an asymptomatic or pruritic eruption of variable duration. The eruption may be associated with an underlying disease (eg, infection, malignancy, sarcoidosis, other systemic illness) The eruption begins as erythematous papules that spread peripherally while clearing centrally. These lesions enlarge at a rate of approximately 2-5 mm/d to produce annular, arcuate, figurate, circinate, or polycyclic plaques Lesions demonstrate a predilection for the thighs and the legs, but they may occur on the upper extremities, the trunk, or the face. The palms and the soles are spared. Erythema migrans: These lesions are typically less numerous, less circinate in configuration, and often accompanied by a history of a tick bite. Erythema gyratum repens: EAC can be distinguished from this condition by its slower rate of spread and by its less bizarre configuration. Also, erythema gyratum repens is almost always associated with an underlying malignancy. Erythema marginatum rheumaticum: This is a nonscaling gyrate erythema that by definition is found in association with rheumatic fever (10-18% of patients with rheumatic fever).","pyqMatches":[{"year":"2014","no":1699,"q":"Child has lesion on buttocks since 2 year spreading peripherally with central scarring non symptomatic diagnosis?","o":["Erythema annular cetrifugam","Erythema migrains","Erythema marginatum","Erythema Gyratum"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6939, 'Pediatrics', 'Infectious Diseases', 'Hard', 'Pediatrics (1)', 144, '{"id":6939,"subject":"Pediatrics","chapter":"Infectious Diseases","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":144,"q":"Infant has fever, one episode of febrile convulsions admitted for observation, fever than subsided and followed by rash on abdomen & chest, maculo​papular erythematous-what is the cause?","o":["Chickenpox","Measles","Typhoid","Dengue"],"a":0,"e":"Ans. is ''a'' i.e., Chickenpox In this question, infant had develop rash on first day offever & distribution of rash is in favour of chickenpox, or varicella. Mnemonic for Day of appearance of rash in a febrile patient is Very Sick Person Must Take Double Tablets Very - Varicella (day 1) Sick - Scarlet fever (day 2) Person - Pox-small pox (day 3) Must - Measles (day 4) Take - Typhus (day 5) Double - Dengue (day 6) Tablets - Typhoid (day 7) Chicken pox (Varicella ): Caused by virus Child develop fever with rash Rash are macular, maculo-papular, vesicular (pleomorphic) Distribution is usually centripetal Complication include - more seen in immunocompromised child. a. Mild thrombocytopenia b. Hematurea c. GI Bledding d. Encephalitis e. Pneumonia","pyqMatches":[{"year":"2014","no":1641,"q":"Infant has fever, one episode of febrile convulsions admitted for observation, fever than subsided and followed by rash on abdomen & chest, maculo​‐ papular erythematous-what is the cause?","o":["Chickenpox","Measles","Typhoid","Dengue"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6940, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 145, '{"id":6940,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":145,"q":"7 year old boy is ill and has fever. what is the caloric requirement?","o":["1200 kcal/d","1500 kcal/d","1900 kcal/d","2200 kcal/d"],"a":2,"e":"Ans. is ''c'' i.e., 1900 kcal/day Children 6 year 7 -> 1690 9 year -> 1950","pyqMatches":[{"year":"2014","no":1700,"q":"7 year old boy is ill and has fever. what is the caloric requirement?","o":["1200 kcal/d","1500 kcal/d","1900 kcal/d","2200 kcal/d"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6941, 'Pediatrics', 'Growth & Development', 'Hard', 'Pediatrics (1)', 146, '{"id":6941,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":146,"q":"Boy power school preference no spoken at school, normal speech at other place, IQ assessment normal diagnosis is?","o":["Selective mutism","ADHD","Autism","Dyslexia"],"a":0,"e":"Ans. is ''a'' i.e., Selective mutism Autism typically diagnosed before 36 month of age. Autism is a neurodevelopmental disorder of unknown etiology, but with a strong genetic basis. It develops and is typically diagnosed before 36 mo of age. It is characterized by a behavioral phenotype that includes qualitative impairment in the areas of language development or communication skills, social interactions and reciprocity, and imagination and play. Selective mutism is defined as a failure to speak in specific social situations, despite speaking in other situations; it is typically a symptom of an underlying anxiety disorder. Children with selective mutism can speak normally in certain settings, such as within their home or when they are alone with their parents, but do not speak in other social settings, such as at school or at other places outside their home. Attention-deficit/hyperactivity disorder (ADHD) is the most common neurobehavioral disorder of childhood, 1 of the most prevalent chronic health conditions affecting school-aged children. ADHD is characterized by: Inattention, including increased distractibility and difficulty sustaining attention. Poor impulse control and decreased self-inhibitory capacity Motor overactivity and motor restlessness. Dyslexia is characterized by an unexpected difficulty in reading in children and adults who otherwise possess the intelligence, motivation, and opportunities to learn considered necessary for accurate and fluent reading. Dyslexia is the most common and most comprehensively studied of the learning disabilities","pyqMatches":[{"year":"2014","no":1701,"q":"Boy power school preference no spoken at school, normal speech at other place, IQ assessment normal diagnosis is?","o":["Selective mutism","ADHD","Autism","Dyslexia"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6942, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 147, '{"id":6942,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":147,"q":"Kangaroo mother care - False is?","o":["Can also be given by father","Especially for low birth weight body","Effective thermal control","All of above"],"a":0,"e":"Ans.:A.)Can also be given by father KANGAROO MOTHER CARE • KMC is care of preterm or LBW infants by placing skin-to-skin contact with the mother • Position: vertical position between the mother''s breasts and under her clothes • The position is maintained until the infant no longer tolerates it (indicated by sweating or baby refuses to stay in KMC position) • Kangaroo nutrition: exclusive breast feeding • Continuous KMC is an alternative to minimal care in an incubator for infants who have already overcome major problems while adapting to extra-uterine life Able to suck and swallow properly Thriving in neutral thermal environment • Intermittent KMC (atleast 1-2 hour) when continuous KMC is not possible • All mothers can provide KMC irrespective of age, parity, education, culture or religion • Initiated in a facility and continued at home Clinical benefits • Significantly increases milk production in mothers • Increases exclusive breast feeding rates • Reduces incidence of respiratory tract and nosocomial infection • Better cardiorespiratory stability • Fewer apneic episodes • Improved weight gain • Improves thermal protection in infants and there is a reduced chance of hypothermia • Improves emotional bonding between the infant and mothers • Reduces the duration of hospital stay • Improved survival in low resource setting Criteria for eligibility for KMC • Indicated in all stable LBW babies • Very sick babies needing special care should be cared for under radiant warmer initially. KMC should be started after the baby is hemodynamically stable • Short KMC sessions can be initiated during recovery with ongoing medical treatment • KMC can be provided while the baby is being fed via orogastric tube or on oxygen therapy • BW > 1800g: generally stable at birth and KMC initiated soon after birth • BW 1200 — 1799 g: many babies have significant neonatal problems. It might take a few days to start KMC • BW < 1200g: it might take days to weeks before initiating KMC When to stop KMC • When the baby attains a weight of 2500g and a gestation of 37 weeks • A baby who upon being put in kangaroo position, tends to wriggle out, pull limbs out or cries, is not in need of KMC any more","pyqMatches":[{"year":"2014","no":1702,"q":"Kangaroo mother care - False is?","o":["Can also be given by father","Especially for low birth weight body","Effective thermal control","All of above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6943, 'Pediatrics', 'Hematology', 'Easy', 'Pediatrics (1)', 148, '{"id":6943,"subject":"Pediatrics","chapter":"Hematology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":148,"q":"Child having long history of hemoglobin 5 gm% next step?","o":["Blood transfusion","CBC,reti count with periphesal smear.","Start Iron","Hb elechophoresis"],"a":1,"e":"Ans. is ''b'' i.e., CBC,reti count with peripheral smear In above question, if child is stable, then no need to give blood transfusion. Before starting Iron, we have to rule out types of anemia as Iron is indicated only in nutritioral anemia. Hb ele ctrophoresis is indicated if there is featuer of hemolytic anemia (thalassemia) so over all our next step is complete hemogram with manual peripheral smear examination. (obtion b).","pyqMatches":[{"year":"2014","no":1661,"q":"Child having long history of hemoglobin 5 gm% next step?","o":["Blood transfusion","CBC,reti count with periphesal smear.","Start Iron","Hb elechophoresis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6944, 'Pediatrics', 'Nutrition', 'Moderate', 'Pediatrics (1)', 149, '{"id":6944,"subject":"Pediatrics","chapter":"Nutrition","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":149,"q":"3 year old child with normal height for age, abnormal weight for age and abnormal weight for height, what It is not be?","o":["Acute malnutrition","Chronic Malnutrition","Acute on chronic","None of above"],"a":1,"e":"Ans. is ''b'' i.e., Chronic malnutrition For this purpose wasting and stunting are measured :- i) Wasting (deficit in weight for height) 4 Acute malnutrition. ii) Stunting (deficit in height for age) - Chronic malnutrition. iii) Wasting and stunting - Acute on chronic malnutrition.","pyqMatches":[{"year":"2014","no":1631,"q":"3 year old child with normal height for age, abnormal weight for age and abnormal weight for height, what It is not be?","o":["Acute malnutrition","Chronic Malnutrition","Acute on chronic","None of above"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6945, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 150, '{"id":6945,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":150,"q":"Hypergonadotropic hypogonadism is sean in all except?","o":["Turner syndrome","Down syndrome","Klinefelter syndrome","Swyer''s syndrome"],"a":1,"e":"Ans. is ''b'' i.e., Down syndrome Hypergonadotropic hypogonadism Also K/a primary or peripheral hypogonadism. Characterised by hypogonadism due to an impaired response of the gonads to the gonadotropin, FSH and LH. In turn a lack of sex steroid production and elevated gonadotropin level. Causes : Chromosomal abnormalitis Turner''s syndrome Klinefelter syndrome Swyer''s syndrome Enzyme defect 17 , hydroxylase 17, 20 lyase deficiency","pyqMatches":[{"year":"2014","no":1654,"q":"Hypergonadotropic hypogonadism is sean in all except?","o":["Turner syndrome","Down syndrome","Klinefelter syndrome","Swyer''s syndrome"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6946, 'Pediatrics', 'Nephrology', 'Easy', 'Pediatrics (1)', 151, '{"id":6946,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":151,"q":"Turner syndrome - karyotyping is?","o":["45, X0","46 X0","47 XXX","Trisomy 21"],"a":0,"e":"Ans. is ''a'' i.e., 45 XO 45X0 Lymphadema of dorsum of hand & fat Loose skin fold at nape of neck Short stature Short Neck (with webbing of neck) Anomalies ear Broad shield like chest with widely spaced small nipple Renal anomalies (Horse-shoe, souble or cleft renal pelvis) Coart of aorta","pyqMatches":[{"year":"2014","no":1649,"q":"Turner syndrome - karyotyping is?","o":["45, X0","46 X0","47 XXX","Trisomy 21"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6947, 'Pediatrics', 'Neonatology', 'Moderate', 'Pediatrics (1)', 152, '{"id":6947,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":152,"q":"Not a finding in potter syndrome?","o":["Bilateral renal agenesis","Polyhydromnios","Pulmonary Hyperplasia","Flat chain"],"a":1,"e":"Ans. is ''b'' i.e., Poly hydromnios Potter syndrome Bilateral renal agenesis is incompatible with extrauterine life and is termed Potter syndrome. Death occurs shortly after birth from pulmonary hypoplasia. The newborn has a characteristic facial appearance, termed Potter facies. The eyes are widely separated withepicanthic folds, the ears are low set, the nose is broad and compressed flat, the chin is receding, and there arelimb anomalies. Bilateral renal agenesis should be suspected when maternal ultrasonography demonstrates oligohydramnios,nonvisualization of the bladder, and absent kidneys.","pyqMatches":[{"year":"2014","no":1618,"q":"Not a finding in potter syndrome?","o":["Bilateral renal agenesis","Polyhydromnios","Pulmonary Hyperplasia","Flat chain"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6948, 'Pediatrics', 'Neurology', 'Easy', 'Pediatrics (1)', 153, '{"id":6948,"subject":"Pediatrics","chapter":"Neurology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":153,"q":"Drug used for absence seizure?","o":["Lamotrigine","Carbamazepine","Phenytoin","Vigabatrine"],"a":0,"e":"Ans. is ''a'' i.e., Lamotrigine Drug of choice for absence seizures is Valproate (Previously it was ethosuxamide). Other drugs used are lamotrigine and clonazepam.","pyqMatches":[{"year":"2014","no":1672,"q":"Drug used for absence seizure?","o":["Lamotrigine","Carbamazepine","Phenytoin","Vigabatrine"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6949, 'Pediatrics', 'Rheumatology', 'Easy', 'Pediatrics (1)', 154, '{"id":6949,"subject":"Pediatrics","chapter":"Rheumatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":154,"q":"Most common cause of acquired heart disease in children","o":["Acute rheuamatic fever","Kawasaki","Takayasu","Diabetes"],"a":0,"e":"Ans. is ''a'' i.e., Acute Rheumatic fever Acute rheumatic fever Most common cause of acquired heart disease in children. Caused by group A f3 hemolytic streptococci Usually seen in school going children Jones criteria = very impotrant Mitral valve most common followed by aortic valve In acute phase - MR seen In RI-ID MS seen","pyqMatches":[{"year":"2014","no":1616,"q":"Most common cause of acquired heart disease in children","o":["Acute rheuamatic fever","Kawasaki","Takayasu","Diabetes"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6950, 'Pediatrics', 'Hematology', 'Easy', 'Pediatrics (1)', 155, '{"id":6950,"subject":"Pediatrics","chapter":"Hematology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":155,"q":"Mildly elevated bilirubin, normal liver enzymes are seen in?","o":["Malaria","Thalassemia","G-6 PD deficie","All of above"],"a":3,"e":"Ans. is ''d'' i.e., All of above Mildly elevated bilirubin especially indirect and normal liver enzyme seen in hemolytic anemia. In above question all causes hemolytic anemia.","pyqMatches":[{"year":"2014","no":1662,"q":"Mildly elevated bilirubin, normal liver enzymes are seen in?","o":["Malaria","Thalassemia","G-6 PD deficie","All of above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6951, 'Pediatrics', 'Cardiology', 'Easy', 'Pediatrics (1)', 156, '{"id":6951,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":156,"q":"Single umblical artery is associated with?","o":["NTD","Hydrops fetalis","Congenital heart disease","In utero death"],"a":2,"e":"Ans. is `c''i.e., Congenital heart disease Approximately 30% of infants with a single umbilical artery have congenital abnormalities. Trisomy 18 is one of the more frequent abnormalities. The most common congenital anomalies in chromosomally normal fetuses and neonates were. Genitourinary (6.48%) Cardiovascular (6.25%) Musculoskeletal (5.44%).","pyqMatches":[{"year":"2014","no":1617,"q":"Single umblical artery is associated with?","o":["NTD","Hydrops fetalis","Congenital heart disease","In utero death"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6952, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 157, '{"id":6952,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":157,"q":"Hypocalcemia in a child may be associated with","o":["Digeorge syndrome","Hypo parathyroidism","Magnesium deficiency","All of above"],"a":3,"e":"Ans. is ''d'' i.e., All of above Causes of hypocakemia Hypo parathyroidism Digeorge syndrome PTH receptor defect (pseudo hypoparathyroidism) Magnesium dificiency Exogenous organic phosphate excess Vit D difeciency","pyqMatches":[{"year":"2014","no":1703,"q":"Hypocalcemia in a child may be associated with","o":["Digeorge syndrome","Hypo parathyroidism","Magnesium deficiency","All of above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6953, 'Pediatrics', 'Nephrology', 'Easy', 'Pediatrics (1)', 158, '{"id":6953,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":158,"q":"Female hermaphrodite is?","o":["Female sexual characterstic with testes","Male sexual charaterstic with ovary","XY","Female sexual characteristic with both testes & ovary"],"a":1,"e":"Ans. is ''b'' i.e., Male sexual characteristc with ovary Female pseudo hermaphroditism Have internal genitalia female type Katy() type XX Masculinisation of external genitalia Most common - CAN Congenital adrenal hyperplasia M-C. 21 hydroxylase deficiency Other cause excess maternal androgen due to - o Maternal ovarian tumor. Maternal drug intake Treatment Hormonal therapy","pyqMatches":[{"year":"2014","no":1655,"q":"Female hermaphrodite is?","o":["Female sexual characterstic with testes","Male sexual charaterstic with ovary","XY","Female sexual characteristic with both testes & ovary"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6954, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 159, '{"id":6954,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":159,"q":"Baby ''0* positive, blood group, mother Rh negative, cord bilirubin 7 mg%, conjugated I now treatment is?","o":["Nothing","Stop breast feeding for 48 hours","Continue breast feeding and phototherapy","Stop breast feed and prepare for exchange blood transfusion"],"a":3,"e":"Ans. is ''d'' i.e., Stop breast tad and prepare for exchange blood transfusion · In hemolytic disease, immediate exchange transfusion indication : a) Cord bilirubin is > 4.5 mg/dl and Hb < 11 gm% b) Bilirubin rising > 1 mg/dl/hour despite phototherapy c) Hb level 11-13 gm/dl and bilirubin rising more than 0.5 mg/dl/hour d) Bilirubin is rising inspite of phototherapy","pyqMatches":[{"year":"2014","no":1663,"q":"Baby ''0* positive, blood group, mother Rh negative, cord bilirubin 7 mg%, conjugated I now treatment is?","o":["Nothing","Stop breast feeding for 48 hours","Continue breast feeding and phototherapy","Stop breast feed and prepare for exchange blood transfusion"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6955, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 160, '{"id":6955,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":160,"q":"3 days old newborn with unknown inborn error of metabolism, hyperammonemia in blood.","o":["Maple syrup urine disease","Urea cycle enzyme dificiency","Organic acidurea","Phenyl ketonuria"],"a":1,"e":"Ans. is ''b'' i.e., Urea cycle enzyme deficiency Urea cycle enzyme defect Catabolism of amino acid leads to free ammonia which is highly toxic Free ammonia is converted into urea by group of 5 enzyme Newborn is usually asymphomatic but leter on become symptomatic after giving protein Treatment is dietery protein restriction MSUD (maple syrup urine disease) Defective decorboxglation of branch chain amino acid (leucine, Isoleuvine, valine) Autosomal recessine Smell of maple syrup in urine. Phenyl ketonuria Autosomal recessive Deficiency of phenylalanine hydroxylase. Defect in conversion of phenylalanine to tyrosine. This leads to increase level of phenylalanine. This increase phenlylalanine converted into phenylpyruvate and phenyl acetate. This phenyl acetate gives mousy or musty odour in urine/body. Other point to remember? Sweaty feat odour -Isovaleric academia In Alkaptanuria - Urine become darkish brown when exposed to air while purplish brown in porphyria. Smoky sweat - MSUD Mousy or Musty - Phenylketonuria Boiled cabbage - Tyrosinemia","pyqMatches":[{"year":"2014","no":1704,"q":"3 days old newborn with unknown inborn error of metabolism, hyperammonemia in blood.","o":["Maple syrup urine disease","Urea cycle enzyme dificiency","Organic acidurea","Phenyl ketonuria"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6956, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 161, '{"id":6956,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":161,"q":"10 month old child can not perform?","o":["Standing with support","Pincer group","Walking with suppor","Two words with meaning"],"a":3,"e":"Ans. is ''d'' i.e., Two words with meaning o A child can transfer the objects from one hand to another by 5-7 months. o A child can build a tower of 6 cubes by 21 months o A child can pull himself up by the age of 10 months. o A child makes a simple sentence first time by the age of 2 years. o Pincer grasp develops by 9 months.","pyqMatches":[{"year":"2014","no":1622,"q":"10 month old child can not perform?","o":["Standing with support","Pincer group","Walking with suppor","Two words with meaning"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6957, 'Pediatrics', 'Neurology', 'Easy', 'Pediatrics (1)', 162, '{"id":6957,"subject":"Pediatrics","chapter":"Neurology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":162,"q":"Child comes with blood sugar 32 mg/dl with convulsions Treatment is?","o":["5% dextrose 2 ml/kg","10% dextrose 2 ml/kg bolus","10% dextrose 4 ml/kg","5% Dextrose 4 ml/kg"],"a":2,"e":"Ans. is ''c'' i.e., 10% Dextrose 4 ml/kg Symtomatic Hypoglycemia (<40mg/d1) should be managed with 10% IV Dextrose. In seizures, dose of 10% dextrose is 4 ml/kg.","pyqMatches":[{"year":"2014","no":1673,"q":"Child comes with blood sugar 32 mg/dl with convulsions Treatment is?","o":["5% dextrose 2 ml/kg","10% dextrose 2 ml/kg bolus","10% dextrose 4 ml/kg","5% Dextrose 4 ml/kg"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6958, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 163, '{"id":6958,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":163,"q":"Omalizumab True statement is?","o":["Anti-IgE","Used as add on therapy in moderate to severe asthma prophylaxis","Givn subcutaneously","All o above"],"a":3,"e":"Ans. is ''d'' i.e., All of above Anti-IgE (Omalizumab). Omalizumab is a humanized monoclonal antibody that binds IgE, thereby preventing its binding to the high-affinity IgE receptor and blocking IgE-mediated allergic responses and inflammation. approved for patients >12 yr old with moderate to severe asthma, It is given every 2-4 wk subcutaneously based on body weight and serum IgE levels. Its clinical efficacy as an \"add-on\" therapy for patients with moderate to severe allergic asthma It is generally well tolerated, although local injection site reactions can occur","pyqMatches":[{"year":"2013","no":495,"q":"Omalizumab True statement is?","o":["Anti-IgE","Used as add on therapy in moderate to severe asthma prophylaxis","Givn subcutaneously","All o above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6959, 'Pediatrics', 'Gastroenterology', 'Easy', 'Pediatrics (1)', 164, '{"id":6959,"subject":"Pediatrics","chapter":"Gastroenterology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":164,"q":"Pigmentation and growth retardation is seen in?","o":["Zinc deficiency","Riboflavin deficiency","Niacin deficiency","Vit A deficiency"],"a":0,"e":"Ans. is ''a'' i.e., Zinc dificiency Dwarfism (growth retardation) Diarrhea Dermatitis Hepatosplenomegaly Iron deficiency anemia Acrodermatitis enteropathica Hyperpigmentation","pyqMatches":[{"year":"2014","no":1632,"q":"Pigmentation and growth retardation is seen in?","o":["Zinc deficiency","Riboflavin deficiency","Niacin deficiency","Vit A deficiency"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6960, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 165, '{"id":6960,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":165,"q":"Not included in modified Jones criteria?","o":["Polyarthalgia","Carditis","Chorea","Erythema marginatum"],"a":0,"e":"Ans. is ''a'' i.e., Polyarthalgia All the given options are included in modified Jones criteria. Carditis, chorea and erythema marginatum are major criteria. Only polyarthralgia (arthralgia) is minor criterian.","pyqMatches":[{"year":"2014","no":1614,"q":"Not included in modified Jones criteria?","o":["Polyarthalgia","Carditis","Chorea","Erythema marginatum"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6961, 'Pediatrics', 'Nutrition', 'Easy', 'Pediatrics (1)', 166, '{"id":6961,"subject":"Pediatrics","chapter":"Nutrition","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":166,"q":"True about foremilk & hind milk?","o":["Foremilk has fat","Hind milk relieve hunger","Fore milk relieve hunger","Hind milk is rich in protein"],"a":1,"e":"Ans. is ''b'' i.e., Hind milk relive hunger The foremilk (the milk \"in front\"); is produced at the beginning of each feeding. It contains water, vitamins, and protein and relieve thurst. The hindmilk ; is pushed out latter, it is heavier, richer in lipid and satisfy hunger.","pyqMatches":[{"year":"2014","no":1642,"q":"True about foremilk & hind milk?","o":["Foremilk has fat","Hind milk relieve hunger","Fore milk relieve hunger","Hind milk is rich in protein"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6962, 'Pediatrics', 'Infectious Diseases', 'Moderate', 'Pediatrics (1)', 167, '{"id":6962,"subject":"Pediatrics","chapter":"Infectious Diseases","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":167,"q":"13 year old female having sudden onset high grade fever with delirium. CT. finding s/o involvement of limbic system & medial temporal lobe - Dx is","o":["Subarachnoid hemorrhage","Herpes simplex encephalitis","Pyomeningitis","Cerebral malaria"],"a":1,"e":"Ans. is ''b'' i.e., Herpes simplex encephalitis Herpes simplex encephalitis Acute necrotising infection involving frontal, temporal lobe & limbic system. Feature Non specific - fever, headache, nuchal rigidity. convulsion, altered sensorium. Confirmed by CSF examin & radio imaging. Treatment supportive and Acyclovir","pyqMatches":[{"year":"2014","no":1705,"q":"13 year old female having sudden onset high grade fever with delirium. CT. finding s/o involvement of limbic system & medial temporal lobe - Dx is","o":["Subarachnoid hemorrhage","Herpes simplex encephalitis","Pyomeningitis","Cerebral malaria"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6963, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 168, '{"id":6963,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":168,"q":"Height of child acquire 100 cm in?","o":["2.5 year","3.5 year","4.5 year","5.5 year"],"a":2,"e":"Ans. is ''c'' i.e., 4.5 year 1 Year- 75 cm 2 Year- 90 cm 4 1/2 Year- 100 cm","pyqMatches":[{"year":"2014","no":1624,"q":"Height of child acquire 100 cm in?","o":["2.5 year","3.5 year","4.5 year","5.5 year"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6964, 'Pediatrics', 'Growth & Development', 'Moderate', 'Pediatrics (1)', 169, '{"id":6964,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":169,"q":"mental retardation can be proved if delayed milestones and slow or retarded growth seen upto which age (in year)?","o":["12","16","18","20"],"a":2,"e":"Ans. is ''c'' i.e., 18 year a) Significantly sub-average intellectual functioning:an IQ score of 70 or below on an individually administered IQ test (for infants, a clinical judgment of significantly sub-average intellectual functioning).","pyqMatches":[{"year":"2014","no":1623,"q":"mental retardation can be proved if delayed milestones and slow or retarded growth seen upto which age (in year)?","o":["12","16","18","20"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6965, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 170, '{"id":6965,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":170,"q":"Most common organ involved in congenital Tb is?","o":["Liver","Pancreas","Kidney","Lung"],"a":0,"e":"Ans. is ''a'' i.e., Liver Congenital tuberculosis Although it is rare as mother having tuberculosis primarily present with infertility. Tuberculous bacilli sometimes pass throgh umblical vein and may develop focus in liver (hepatic complex). When neonate aspirate amniotic fluid containing bacilli then develop GI tuberculosis or lung infection. Neonate usually present as respiratory distress, hepatosplenomegaly lymphadenopathy. Overall liver is most commonly involved in congenital tuberculosis","pyqMatches":[{"year":"2014","no":1667,"q":"Most common organ involved in congenital Tb is?","o":["Liver","Pancreas","Kidney","Lung"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6966, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 171, '{"id":6966,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":171,"q":"Bivalent meningococcal vaccine is ?","o":["A Y","A C","C y","A W-I35"],"a":1,"e":"Ans. is ''b'' i.e., A C Two type of meningococcal vaccine develop Unconjugated polysaccharide vaccine. Conjugated group C vaccine. Polysaccharide vaccines Internationally marketed meningococcal polysaccharide vaccines are o Bivalent (A and C), Trivalent (A, C and W-135) Tetravalent (A, C, Y and W-135). The vaccines are purified, heat-stable, lyophilized capsular polysaccharides from meningococci of the respective serogroups. A protective antibody response occurs within 10 days of vaccination. In schoolchildren and adults, one dose of these polysaccharide vaccines appears to provide protection for at least 3 years, but in children under 4 years of age the levels of specific antibodies decline rapidly after 2-3 years.","pyqMatches":[{"year":"2012","no":811,"q":"Bivalent meningococcal vaccine is ?","o":["A Y","A C","C y","A W-I35"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6967, 'Pediatrics', 'Cardiology', 'Easy', 'Pediatrics (1)', 172, '{"id":6967,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":172,"q":"Apnea of prematurity ?","o":["> 10 sec","> 15 sec","20 sec","> 30 sec"],"a":2,"e":"Ans. is ''c'' i.e., 20 sec Apnea of prematurity defined as sudden stoppage of breathing that lasts for 20 sec or is associated with brady​cardia or cyanosis. Apnea of prematurity should be differentiated from periodic breathing which is normal phenomenon is preterm neonate","pyqMatches":[{"year":"2013","no":1434,"q":"Apnea of prematurity ?","o":["> 10 sec","> 15 sec","20 sec","> 30 sec"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6968, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 173, '{"id":6968,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":173,"q":"Down syndrome - all are seen except -","o":["t (14; 21)","t (11: 14)","Trisomy 21","t (15: 21)"],"a":1,"e":"Ans. is ''b'' i.e., t (11: 14) In 95% of cases of Down syndrome-trisomy of 21:- Extra chromosome is of maternal in origin. I% have mosaic with some all have 46 chromosome. 4% have robertsonian translocation. t (13 : 21) t (14 : 21) t (15 : 21) Very rarely long arm of chromosome 21 is triplicate (Partial trisomy).","pyqMatches":[{"year":"2012","no":1162,"q":"Down syndrome - all are seen except","o":["t (14; 21)","t (11: 14)","Trisomy 21","t (15: 21)"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6969, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 174, '{"id":6969,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":174,"q":"Bidextrous grip is seen at what age?","o":["4 months","5 months","6 months","7 months"],"a":0,"e":"Ans. A. 4 months FINE MOTOR MILESTONES: Age Milestone 4 months Bidextrous reach 6 months Unidextrous reach 9 months Immature pincer grasp 12monthsMature pincer grasp 15monthsImitates scribbling, tower of 2 blocks 18monthsScribbles, tower of 3 blocks 2 years Tower of 6 blocks, vertical & circular stroke 3 years Tower of 9 blocks, copies circle 4 years Copies cross, bridge with blocks 5 years Copies triangle","pyqMatches":[{"year":"2019","no":187,"q":"Bidextrous grip is seen at what age?","o":["4 months","5 months","6 months","7 months"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6970, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 175, '{"id":6970,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":175,"q":"Which vaccine to be given every year ?","o":["Hepatitis A","Hepatitis B","Influenza","Chicken pox"],"a":2,"e":"Ans. C. Influenza Influenza (Flu): The flu vaccine is recommended every year for children 6 months and older: Kids younger than 9 who get the flu vaccine for the first time (or who have only had one dose before July 2017) will get it in two separate doses at least a month apart. Those younger than 9 who have had at least two doses of flu vaccine previously (in the same or different seasons) will only need one dose. Kids older than 9 only need one dose. The vaccine is given by injection with a needle (the flu shot) or by nasal spray. The flu shot is preferred for children of all ages because it has been shown to be safe and effective. Although the nasal spray was not used in recent years, a changed version of it is now recommended (for the 2018–2019 flu season) for kids who may otherwise not get a flu shot. The nasal spray is only for healthy people ages 2 through 49. People with weakened immune systems or some health conditions (such as asthma) and pregnant women should not get the nasal spray vaccine.","pyqMatches":[{"year":"2019","no":188,"q":"Which vaccine to be given every year ?","o":["Hepatitis A","Hepatitis B","Influenza","Chicken pox"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6971, 'Pediatrics', 'Cardiology', 'Easy', 'Pediatrics (1)', 176, '{"id":6971,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":176,"q":"APGAR score 3 at 1 minute indicates:","o":["Mildly depressed","Further resuscitation not needed","Severely depressed","Normal"],"a":2,"e":"Ans. C. Severely depressed APGAR CRITERIA: Score of 0 Score of 1 Score of 2 Component of backronym Skin color blue or pale all over blue at extremities body pink (acrocyanosis) no cyanosis body and extremities pink Appearance Pulse rate absent < 100 beats per minute > 100 beats per minute Pulse Reflex irritability grimace no response to stimulation grimace on suction or aggressive stimulation cry on stimulation Grimace Activity none some flexion flexed arms and legs that resist extension Activity Respiratory effort absent weak, irregular, gasping strong, robust cry Respiration INTERPRETATION: The test is generally done at 1 and 5 minutes after birth and may be repeated later if the score is and remains low. Scores 7 and above are generally normal Score 4 to 6, fairly low Score:3 and below are generally regarded as critically low and cause for immediate resuscitative efforts.","pyqMatches":[{"year":"2019","no":189,"q":"APGAR score 3 at 1 minute indicates:","o":["Mildly depressed","Further resuscitation not needed","Severely depressed","Normal"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"},{"year":"2020","no":205,"q":"APGAR score 3 at 1 minute indicates:","o":["Mildly depressed","Further resuscitation not needed","Severely depressed","Normal"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2019","2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6972, 'Pediatrics', 'Nutrition', 'Easy', 'Pediatrics (1)', 177, '{"id":6972,"subject":"Pediatrics","chapter":"Nutrition","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":177,"q":"Severe acute malnutrition as per WHO criteria-","o":["Weight for age less than median plus – 2 SD","Weight for height less than median plus 2 SD","Weight for age less than median plus 3 SD","Weight for height less than median minus -3SD"],"a":3,"e":"Ans. D.Weight for height less than median minus -3SD Severe acute malnutrition is defined by a very low weight for height (below -3z scores of the median WHO growth standards), by visible severe wasting, or by the presence of nutritional oedema. World Health Organization (WHO) classification of nutritional status of infants and children: Nutritional status Age: birth to 5 years Obese Weight-for-length/height or BMI-for-age >3 standard deviations (SD) of the median Overweight Weight-for-length/height or BMI-for-age >2 SD and ≤3 SD of the median Moderately underweight Weight-for-age Severely underweight Weight-for-age Moderate acute malnutrition Weight-for-length/height or BMI-for-age ≤–2 SD and ≥–3 SD of the median, or mid-upper arm circumference ≥115 mm and Severe acute malnutrition Weight-for-length/height or BMI-for-age Moderately stunted Moderately stunted (moderate chronic malnutrition) Length/height-for-age ≤–2 SD and ≥–3 SD of the median Severely stunted (severe chronic malnutrition) Length/height-for-age Moderately wasted Weight-for-length/height ≤–2 SD and ≥–3 SD of the median Severely wasted Weight-for-length/height","pyqMatches":[{"year":"2019","no":190,"q":"Severe acute malnutrition as per WHO criteria","o":["Weight for age less than median plus – 2 SD","Weight for height less than median plus 2 SD","Weight for age less than median plus 3 SD","Weight for height less than median minus -3SD"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6973, 'Pediatrics', 'Cardiology', 'Easy', 'Pediatrics (1)', 178, '{"id":6973,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":178,"q":"Where to look for pre-ductal O2 saturation in PDA in a 3 minute born infant?","o":["Fetal left Upper limb","Fetal left lower limb","Fetal right Upper limb","Fetal right lower limb"],"a":2,"e":"Ans. C. Fetal right Upper limb A simpler way to detect this right-to-left shunting is to use two pulse oximeters and measure preductal and postductal SpO2. In one study it was found that arterial saturation in the right arm (preductal) of at least 3%above the lower limb (postductal) is evidence of right- to-left ductal shunting.","pyqMatches":[{"year":"2019","no":191,"q":"Where to look for pre-ductal O2 saturation in PDA in a 3 minute born infant?","o":["Fetal left Upper limb","Fetal left lower limb","Fetal right Upper limb","Fetal right lower limb"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6974, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 179, '{"id":6974,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":179,"q":"True about Fragile X syndrome is-","o":["Triple nucleotide CAG Sequence mutation","10% Female carriers mentally retarded","Males have IQ 20-40","Gain of function mutation"],"a":2,"e":"Ans. C. Males have IQ 20-40 Fragile X Syndrome Fragile X syndrome is associated with a fragile site on chromosome X (Xq 29.3) Triple nucleotide CGG Sequence mutation About 20% of women who are carriers for the fragile X premutation are affected by fragile X-related primary ovarian insufficiency. Individuals with FXS may present anywhere on a continuum from learning disabilities in the context of a normal intelligence quotient (IQ) to severe intellectual disability, with an average IQ of 40 in males who have complete silencing of the FMR1 gene. Fragile sites are regions of chromosomes that show a tendency to separation breakage or attenuation tinder particular growth conditions. Inheritance Inheritance does not follow the usual Mendelian single gene patterns It is due to Allelic expansion. Clinical Manifestations : The main clinical manifestations are :","pyqMatches":[{"year":"2019","no":192,"q":"True about Fragile X syndrome is","o":["Triple nucleotide CAG Sequence mutation","10% Female carriers mentally retarded","Males have IQ 20-40","Gain of function mutation"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6975, 'Pediatrics', 'Neurology', 'Easy', 'Pediatrics (1)', 180, '{"id":6975,"subject":"Pediatrics","chapter":"Neurology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":180,"q":"True about RETT Syndrome –","o":["Macrocephaly","Cardiac arrhythmia","Seizures","Mental retardation e) Autistic behaviour"],"a":1,"e":":C:D:E Ans. is''b''i.e., Cardiac arrhythmia,''c''i.e., Seizures,''d''i.e., Mental retardation &''e''i.e., Autistic behaviour Rett''s Syndrome This is the characteristic features, that they begin to loose their acquired skills, e.g., cognitive and head growth is normal during early period after which there is an arrest of growth. Acquired microcephaly Most children develop peculiar sighing respirations with intermittent periods of apnea that may be associated with cyanosis → Breath holding spells. Autistic behaviour → Impaired social interaction, language and communication. Generalized tonic-clonic convulsions occur in the majority. Feeding disorder and poor weight gain","pyqMatches":[{"year":"2014","no":2091,"q":"True about RETT Syndrome –","o":["Macrocephaly","Cardiac arrhythmia","Seizures","Mental retardation e) Autistic behaviour"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6976, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 181, '{"id":6976,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":181,"q":"True about Asperger syndrome:","o":["More common in girl","Repetitive activity pattern","Subnormal intelligence is consistent feature","Severe language impairments is characteristic e) All"],"a":1,"e":"Ans. b. Repetitive activity pattern Asperger syndrome: It is four times more likely to occur in males than in females and usually is first diagnosed in children between the ages of 2 and 6. The common characteristics include average or above average intelligence\" There is no clinically significant general delay in spoken or receptive language or cognitive development. Self'' help skills, adaptive behaviour, and curiosity about the environment during the first 3 years should be at a level consistent with normal intellectual development","pyqMatches":[{"year":"2016","no":1402,"q":"True about Asperger syndrome:","o":["More common in girl","Repetitive activity pattern","Subnormal intelligence is consistent feature","Severe language impairments is characteristic e) All"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6977, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 182, '{"id":6977,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":182,"q":"Which of the following is present in a XY child but not in a XX child ?","o":["Epoophoron","Paroophoron","Cowper''s glands","Gartner''s duct"],"a":2,"e":"Answer- C. Cowper''s glands Bulbourethral gland (Cowper''s gland) are found in males (XY) and are homologous to Bartholin''s gland in females (XX). [Ref : \"Differentiation of the urogenital sinus in males\". Embryology]","pyqMatches":[{"year":"2015","no":1427,"q":"Which of the following is present in a XY child but not in a XX child ?","o":["Epoophoron","Paroophoron","Cowper''s glands","Gartner''s duct"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6978, 'Pediatrics', 'Nephrology', 'Moderate', 'Pediatrics (1)', 183, '{"id":6978,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":183,"q":"Therepeutic phlebotomy is not done in which of the following conditions ?","o":["CML","Polycythemia vera","Hemochromatosis","Porphyria cutanea tarda"],"a":0,"e":"Answer- A. CML Indications for therepeutic phlebotomy- Polycythemia vera Hemochromatosis Secondary polycythemia Porphyria cutanea tarda [Ref Current applications of therapeutic phlebotomy Tarek Bou Assi and Elizabeth Baz. Blood Transfus. 2014 Jan; 12(Suppl 1): s75-s83]","pyqMatches":[{"year":"2015","no":1426,"q":"Therepeutic phlebotomy is not done in which of the following conditions ?","o":["CML","Polycythemia vera","Hemochromatosis","Porphyria cutanea tarda"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6979, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 184, '{"id":6979,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":184,"q":"What is the IQ of a borderline deficiency?","o":["70 - 80","50 - 69","20 - 49","0 - 20"],"a":0,"e":"Answer- A. 70 - 80 IQ Range IQ Classification 70 and BelowExtremely Low 71 -79 Borderline 80 -89 Low Average 90 -110 Average 111 -120 Bright 121 -130 Very Bright 131 and OverExtremely Bright","pyqMatches":[{"year":"2015","no":1366,"q":"What is the IQ of a borderline deficiency?","o":["70 - 80","50 - 69","20 - 49","0 - 20"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6980, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 185, '{"id":6980,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":185,"q":"Which is false about development milestones at 6 months of age?","o":["Watching self in mirror","Sitting in tripod position","Pincer grasp","Monosyllable sounds"],"a":0,"e":"Answer- A. Watching self in mirror Milestones at 6 months of age In prone position lifts his head and greater part of his chest while supporting weight on extended arms. Produces monosyllable sounds like da, ma. Enjoys watching his own image in the mirror. Binocular vision develops (between 3-6 months). Purposeful movements in space (6-8 months). Sits in tripod position.","pyqMatches":[{"year":"2015","no":1368,"q":"Which is false about development milestones at 6 months of age?","o":["Watching self in mirror","Sitting in tripod position","Pincer grasp","Monosyllable sounds"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6981, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 186, '{"id":6981,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":186,"q":"At what age child begins to use past and present tense","o":["1 Years","2 Years","18 Months","30 Months"],"a":3,"e":"Answer- D. 30 Months Begin to identify objects from a group by their function and parts (ie. \"which one has wheels\", \"which one can we eat\") Begin to use verbs with \"ing\" endings (i.e. \"eating\"); Early concepts such as \"big, little\" are identified; Child will use \"no, not\" and answer \"where\" questions","pyqMatches":[{"year":"2015","no":1369,"q":"At what age child begins to use past and present tense","o":["1 Years","2 Years","18 Months","30 Months"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6982, 'Pediatrics', 'Nephrology', 'Moderate', 'Pediatrics (1)', 187, '{"id":6982,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":187,"q":"Reduced osmolarity ORS does not contain which of the following ion -","o":["Sodium","Potassium","Lactate","Citrate"],"a":2,"e":"Answer- C. Lactate Table 1: Composition of standard and reduced osmolarity ORS solutions ORS → StandardReduced Osmolarity Contents↓mEq/L mEq/L Glucose 111 75 Sodium 90 75 Choride 80 65 Potassium20 20 Citrate 10 10 Osmoarity 311 245 30 mmol/l of bicarbonate instead of 10 mmol/l of citrate","pyqMatches":[{"year":"2015","no":1424,"q":"Reduced osmolarity ORS does not contain which of the following ion","o":["Sodium","Potassium","Lactate","Citrate"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6983, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 188, '{"id":6983,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":188,"q":"Most common site for bone marrow aspiration in neonates is -","o":["Anterior superior iliac crest","Posterior superior iliac crest","Sternum","Anteromedial tibia"],"a":3,"e":"Answer- D. Anteromedial tibia Preferred site for bone marrow aspiration in children - Posterior superior iliac crest. In children < 18 month of age → Anteromedial tibia is preferred.","pyqMatches":[{"year":"2015","no":1423,"q":"Most common site for bone marrow aspiration in neonates is","o":["Anterior superior iliac crest","Posterior superior iliac crest","Sternum","Anteromedial tibia"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6984, 'Pediatrics', 'Growth & Development', 'Moderate', 'Pediatrics (1)', 189, '{"id":6984,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":189,"q":"Milestones at 1 year of age are all except","o":["Playing a simple ball game","Using 2 words that are meaningful","Spontaneous scribbling","Walking upstairs 1 step at a time"],"a":3,"e":"Answer- D. Walking upstairs 1 step at a time Tries to remove his coat and attempts to wear his socks or shoes without success. Does mimicry. Plays a simple ball game Can use 2 words with meaning Tries to build a Tower of 2 cubes Tries to scribble spontaneously (between 12-24 months).","pyqMatches":[{"year":"2015","no":1370,"q":"Milestones at 1 year of age are all except","o":["Playing a simple ball game","Using 2 words that are meaningful","Spontaneous scribbling","Walking upstairs 1 step at a time"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6985, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 190, '{"id":6985,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":190,"q":"Floor of nasal cavity in children is made of -","o":["Palatine bone and vomer","Sphenoid and ethmoid","Nasal bone and maxilla","Palatine bone and maxilla"],"a":3,"e":"Answer- D. Palatine bone and maxilla \"The floor of the nasal cavities, which also form the roof of the mouth, is made up by the bones of the hard palate: the horizontal plate of the palatine bone posteriorly and the palatine process of the maxilla anteriorly.\" [Ref Moore, Keith L; Dailey, Arthur F. (1999). Clinically Oriented Anatomy. Lippincott Williams er Wilkins.]","pyqMatches":[{"year":"2015","no":1422,"q":"Floor of nasal cavity in children is made of","o":["Palatine bone and vomer","Sphenoid and ethmoid","Nasal bone and maxilla","Palatine bone and maxilla"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6986, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 191, '{"id":6986,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":191,"q":"Stranger anxiety develops at","o":["3 months","4 months","7 months","11 months"],"a":2,"e":"Answer- C. 7 months Milestones at month Holds the objects with crude grasp from palm (palmar grasp) Pivots Shows strangers anxiety Resists if a toy is pulled from his hand. Babbles","pyqMatches":[{"year":"2015","no":1371,"q":"Stranger anxiety develops at","o":["3 months","4 months","7 months","11 months"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6987, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 192, '{"id":6987,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":192,"q":"Consanguinous marriages increase risk of diseases -","o":["Autosomal dominant disease","Autosomal recessive disease","X linked dominant diseases","Environmental diseases"],"a":1,"e":"Answer- B. Autosomal recessive disease Increases risk of - autosomal recessive disease No change in risk of - autosomal dominant, X linked recessive (if neither parent affected) Not Proven - complex late onset diseases like diabetes, schizophrenia, cardiovascular diseases","pyqMatches":[{"year":"2015","no":1421,"q":"Consanguinous marriages increase risk of diseases","o":["Autosomal dominant disease","Autosomal recessive disease","X linked dominant diseases","Environmental diseases"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6988, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 193, '{"id":6988,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":193,"q":"What is the average weight gain of the neonate per day","o":["5-10 g","25-30 g","50-60g","100-150g"],"a":1,"e":"Answer- B. 25-30 g They gain weight at a rate of approximately 25 to 30 gm per day for the first 3 months of life. Thereafter they gain about 400 gm of weight every month for the remaining part of first year. [Ref Ghai 7th/e p. 6]","pyqMatches":[{"year":"2015","no":1372,"q":"What is the average weight gain of the neonate per day","o":["5-10 g","25-30 g","50-60g","100-150g"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6989, 'Pediatrics', 'Nephrology', 'Easy', 'Pediatrics (1)', 194, '{"id":6989,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":194,"q":"Japanese encephalitis vaccine in routine schedule is given in how many doses -","o":["Two doses 1 month apart with a booster after 1-2 years if needed","Single dose vaccine","Three doses 1 month apart followed by a booster if needed","Three doses with the second dose 1 month and 3'' dose 6 months after the first dose"],"a":0,"e":"Answer- A. Two doses 1 month apart with a booster after 1-2 years if needed A Vero cell-derived, inactivated and alum-adjuvanted JE vaccine based on the SA 14-14-2 strain is used. The primary two doses are administered 4 weeks apart. A booster dose is recommended 1-2 years after the primary immunization","pyqMatches":[{"year":"2015","no":1420,"q":"Japanese encephalitis vaccine in routine schedule is given in how many doses","o":["Two doses 1 month apart with a booster after 1-2 years if needed","Single dose vaccine","Three doses 1 month apart followed by a booster if needed","Three doses with the second dose 1 month and 3'' dose 6 months after the first dose"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6990, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 195, '{"id":6990,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":195,"q":"Newborn loses how much weight in first week?","o":["5 -10%","1-2%","10-20%","None"],"a":0,"e":"Answer- A. 5 -10% The average birth weight of neonates is about 3 Kg. During first few days after birth, the newborn loses extracellular fluid equivalent to about 10% of the body weight.","pyqMatches":[{"year":"2015","no":1373,"q":"Newborn loses how much weight in first week?","o":["5 -10%","1-2%","10-20%","None"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6991, 'Pediatrics', 'Gastroenterology', 'Easy', 'Pediatrics (1)', 196, '{"id":6991,"subject":"Pediatrics","chapter":"Gastroenterology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":196,"q":"In acute diarrhea following is used to decrease duration and severity -","o":["Zn","Mg","Fe","Ca"],"a":0,"e":"Answer- A. Zn Recent studies suggest that administration of zinc along with new low osmolarity oral rehydration solutions / salts (ORS), can reduce the duration and severity of diarrheal episodes for up to three months. [Ref Sachdev HP, Mittal NK, Yadav HS. Oral zinc supplementation in persistent diarrhea in infants. Ann Trop Paediatr. 1990;10:63-9.]","pyqMatches":[{"year":"2015","no":1419,"q":"In acute diarrhea following is used to decrease duration and severity","o":["Zn","Mg","Fe","Ca"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6992, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 197, '{"id":6992,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":197,"q":"What is the cardiothoracic ratio in children is -","o":["30-35%","40-45%","50-55%","60-65%"],"a":2,"e":"Answer- C. 50-55% \" The cardiac silhouette occupies 50-55% of the chest width. Cardiomegaly is present when the cardiothoracic (CT) ratio is more than 55%.\"","pyqMatches":[{"year":"2015","no":1376,"q":"What is the cardiothoracic ratio in children is","o":["30-35%","40-45%","50-55%","60-65%"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6993, 'Pediatrics', 'Nephrology', 'Easy', 'Pediatrics (1)', 198, '{"id":6993,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":198,"q":"Eyelid papules and hoarse cry in a child is suggestive of -","o":["Congenital syphilis","Croup","Lipoid proteinosis","Acrodermatitis enterohepatica"],"a":2,"e":"Answer- C. Lipoid proteinosis Lipoid proteinosis also known as hyalinosis cutis et mucosa or Urbach-Weithe disease is a rare autosomal recessive disorder. characterized clinically by a myriad signs and symptoms that include hoarseness of the voice, beaded eyelid papules (Moniliform blepharosis), yellowish-white mucocutaneous infiltrates, and atrophic pock-like scars.","pyqMatches":[{"year":"2015","no":1418,"q":"Eyelid papules and hoarse cry in a child is suggestive of","o":["Congenital syphilis","Croup","Lipoid proteinosis","Acrodermatitis enterohepatica"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6994, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 199, '{"id":6994,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":199,"q":"The fetal circulation changes to normal circulation at birth with","o":["Closure of patent ductus arteriosus","Closure of ductus venosus","Increased activity of right Ventricle","Opening of fossa Ovalis"],"a":0,"e":"Answer- A. Closure of patent ductus arteriosus The increase in the concentration of oxygen in the blood leads to a decrease in prostaglandins, causing closure of the ductus arteriosus. These closures prevent blood from bypassing pulmonary circulation, and therefore allow the neonate''s blood to become oxygenated in the newly operational lungs.","pyqMatches":[{"year":"2015","no":1377,"q":"The fetal circulation changes to normal circulation at birth with","o":["Closure of patent ductus arteriosus","Closure of ductus venosus","Increased activity of right Ventricle","Opening of fossa Ovalis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6995, 'Pediatrics', 'Infectious Diseases', 'Easy', 'Pediatrics (1)', 200, '{"id":6995,"subject":"Pediatrics","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":200,"q":"Most common cause of pneumonia in early onset sepsis a neonate is","o":["Pnemococcus","S. Pyogens","E Coli","S. Aureus"],"a":2,"e":"Answer- C. E Coli Early onset sepsis It is caused by organisms prevalent in the genital tract or in the labor room and maternity operation theatre. In the west it is mostly caused by group B streptococcus and E.coli. In our country it is mostly due to gram negative organisms-E.coli, ldebsiella and enterobactor sp.","pyqMatches":[{"year":"2015","no":1378,"q":"Most common cause of pneumonia in early onset sepsis a neonate is","o":["Pnemococcus","S. Pyogens","E Coli","S. Aureus"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6996, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 201, '{"id":6996,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":201,"q":"Test done to diagnose syphilis in newborn if mother is syphilitic -","o":["Syphilis Capita M test","Detection of IgG","ZN staining","Fluoroescent antigen test"],"a":0,"e":"Answer- A. Syphilis Capita M test The tests to detect IgM are -","pyqMatches":[{"year":"2015","no":1417,"q":"Test done to diagnose syphilis in newborn if mother is syphilitic","o":["Syphilis Capita M test","Detection of IgG","ZN staining","Fluoroescent antigen test"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6997, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 202, '{"id":6997,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":202,"q":"Inotropic support for severely dehydrated child with dopamine is done at what rate -","o":["0.1-0-5 microgram/kg/min","1-5 microgram/kg/min","1-5 mg/kg/min","10-15 mg/kg/min"],"a":1,"e":"Answer- B. 1-5 microgram/kg/min In high doses, it acts on alpha-adrenergic receptors to increase systemic vascular resistance and raise blood pressure. 1-5 mcg/kg/min IV, increased to 5-20 mcg/kg/min; not to exceed 50 mcg/kg/min.","pyqMatches":[{"year":"2015","no":1416,"q":"Inotropic support for severely dehydrated child with dopamine is done at what rate","o":["0.1-0-5 microgram/kg/min","1-5 microgram/kg/min","1-5 mg/kg/min","10-15 mg/kg/min"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6998, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 203, '{"id":6998,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":203,"q":"Neonatal resuscitation - which of the following drugs is used ?","o":["Dopamine","Sodium Bicarbonate","Noradrenaline","Dobutamine"],"a":1,"e":"Answer- B. Sodium Bicarbonate Important drugs used for neonatal resuscitation are Epinephrine (adrenaline), Normal saline or ringer lactate, Naloxone and Soda bicarbonate.","pyqMatches":[{"year":"2015","no":1379,"q":"Neonatal resuscitation - which of the following drugs is used ?","o":["Dopamine","Sodium Bicarbonate","Noradrenaline","Dobutamine"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (6999, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 204, '{"id":6999,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":204,"q":"Which of the following is correct about shock in child?","o":["Tachycardia is a very sensitive indicator of depletion of intravascular volume","Mottling of extremities is seen in early shock","Confusion, stupor and coma are early signs","Respiratory rate is more sensitive than heart rate as an indicator of early shock"],"a":0,"e":"Answer- A. Tachycardia is a very sensitive indicator of depletion of intravascular volume Hypovolemic shock in children may have following stages : - i) Early compensated Immediately after hypovolemia, body tries to maintain the BP to maintain adequate perfusion to vital organs through a compensatory mechanisms. An increase in heart rate (Tachycardia) is the earliest and most sensitive indicator for intravascular volume reduction ii) Late uncompensated If shock state continues or the compensatory mechanisms are not enough to maintain the metabolic needs of the tissue, the shock, goes into uncompensated phase.","pyqMatches":[{"year":"2015","no":1415,"q":"Which of the following is correct about shock in child?","o":["Tachycardia is a very sensitive indicator of depletion of intravascular volume","Mottling of extremities is seen in early shock","Confusion, stupor and coma are early signs","Respiratory rate is more sensitive than heart rate as an indicator of early shock"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7000, 'Pediatrics', 'Cardiology', 'Moderate', 'Pediatrics (1)', 205, '{"id":7000,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":205,"q":"When does crying stop in cyanotic spells ?","o":["Forced Expiration","Forced inspiration","Mid inspiration","Crying is continuous"],"a":0,"e":"Answer- A. Forced Expiration Cyanotic form (cyanotic spells) This is more common and is provoked in response to frustration and anger precipitated by upsetting or scolding infant/child. Cyanotic spells are due to central sympathetic overactivity. Clinical features include generalized cyanosis, apnea, forced expiration(crying stops) , opisthotonus, shrill cry and bradycardia. Seizures may occur due to cerebral hypoxia, but antiepileptics are not required. The only treatment is support and reassurance to parents","pyqMatches":[{"year":"2015","no":1380,"q":"When does crying stop in cyanotic spells ?","o":["Forced Expiration","Forced inspiration","Mid inspiration","Crying is continuous"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7001, 'Pediatrics', 'Gastroenterology', 'Easy', 'Pediatrics (1)', 206, '{"id":7001,"subject":"Pediatrics","chapter":"Gastroenterology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":206,"q":"Abdominal pain in Henoch Schonlein purpura is due to -","o":["Mucosal erosions and swelling of the GI mucosa","Gastrointestinal hemorrhage","Volvulus","Associated pancreatic inflammation"],"a":0,"e":"Answer- A. Mucosal erosions and swelling of the GI mucosa The second most frequent symptom of Henoch-SchOnlein purpura is abdominal pain, which occurs in up to 65 percent of cases. The most common complaint is colicky abdominal pain, which may be severe and associated with vomiting. Endoscopic evaluation often shows mucosal erosions and swelling.","pyqMatches":[{"year":"2015","no":1413,"q":"Abdominal pain in Henoch Schonlein purpura is due to","o":["Mucosal erosions and swelling of the GI mucosa","Gastrointestinal hemorrhage","Volvulus","Associated pancreatic inflammation"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7002, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 207, '{"id":7002,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":207,"q":"Treatment of choice for symptomatic neonatal hypoglycemia is","o":["Dextrose normal saline","5% dextrose","10% dextrose","25% dextrose"],"a":2,"e":"Answer- C. 10% dextrose Symptomatic or asymptomatic with blood glucose < 20 mg/dl Bolus 10% dextrose 2 ml/kg is given IV. Followed by continuous infusion of 6 mg/kg/minute. If normoglycemia is not achieved within 24 hours, glucocorticoids (prednisone or hydrocortisone) should be administered. For intractable hypoglycemia, glucagon, epinephrine or diazoxide can be given. In hypoglycemic seizures, dose of 10% dextrose is 4 ml/kg","pyqMatches":[{"year":"2015","no":1381,"q":"Treatment of choice for symptomatic neonatal hypoglycemia is","o":["Dextrose normal saline","5% dextrose","10% dextrose","25% dextrose"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7003, 'Pediatrics', 'Neonatology', 'Moderate', 'Pediatrics (1)', 208, '{"id":7003,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":208,"q":"ALL of the following are causes of neonatal bradycardia except","o":["Hypoxia","Hypothermia","Head injury","BCG Vaccine"],"a":3,"e":"Answer- D. BCG Vaccine Neonatal bradycardia is defined as a decrease in heart by 30 bpm from baseline. Regarding neonatal resuscitation, bradycardia is concerning when the heart rate is less than 100 bpm.","pyqMatches":[{"year":"2015","no":1382,"q":"ALL of the following are causes of neonatal bradycardia except","o":["Hypoxia","Hypothermia","Head injury","BCG Vaccine"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7004, 'Pediatrics', 'Nephrology', 'Easy', 'Pediatrics (1)', 209, '{"id":7004,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":209,"q":"Investigation of choice for CONFIRMING Henoch Schonlein purpura is -","o":["Serum IgA levels","CRP levels","Renal Biopsy","DTPA"],"a":2,"e":"Amswer= C. Renal Biopsy Biopsy of the kidney may be performed both to establish the diagnosis or to assess the severity of already suspected kidney disease.","pyqMatches":[{"year":"2015","no":1412,"q":"Investigation of choice for CONFIRMING Henoch Schonlein purpura is","o":["Serum IgA levels","CRP levels","Renal Biopsy","DTPA"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7005, 'Pediatrics', 'Neonatology', 'Moderate', 'Pediatrics (1)', 210, '{"id":7005,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":210,"q":"Which of the following is not a cause of neonatal anaemia?","o":["Subgaleal Hemorrhage","Abruptio placentae","Diamond Blackfan syndeome","Wilson''s Disease"],"a":3,"e":"Answer- D. Wilson''s Disease Internal hemorrhage such as intracranial hemorrhage, subgaleal hemorrhage, cephalohematoma, adrenal hemorrhage, subcapsular hematoma of liver or ruptured viscus Obstetrical causes: placental abruption, placenta previa, trauma to placenta or umbilical cord during delivery and rupture of anomalous placental vessels Twin-twin transfusion RBC destruction RBC production","pyqMatches":[{"year":"2015","no":1383,"q":"Which of the following is not a cause of neonatal anaemia?","o":["Subgaleal Hemorrhage","Abruptio placentae","Diamond Blackfan syndeome","Wilson''s Disease"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7006, 'Pediatrics', 'Growth & Development', 'Moderate', 'Pediatrics (1)', 211, '{"id":7006,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":211,"q":"Autosomal recessive Polycystic kidneys - all are true except -","o":["Seen in adults","Defective gene is PKHD1","Both kidneys show innumerable cysts","USG shows salt and pepper appearance"],"a":0,"e":"Amswer- A. Seen in adults Childhood polycystic kidney disease has autosomal recessive inheritance, therefore it is also known as autosomal recessive polycystic kidney disease. Defective gene is the PKHD1 (Polycystic Kidney and Hepatic Disease1) which codes for a protein fibrocystin Both kidneys are markedly enlarged and show innumerable cysts radiating from medulla the cortex. MRI of kidney shows radially arranged fusiform dilated collecting ducts. Prenatal USG shows a salt and pepper appearance of kidney.","pyqMatches":[{"year":"2015","no":1411,"q":"Autosomal recessive Polycystic kidneys - all are true except","o":["Seen in adults","Defective gene is PKHD1","Both kidneys show innumerable cysts","USG shows salt and pepper appearance"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7007, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 212, '{"id":7007,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":212,"q":"3 month old child with indrawing chest with respitratory rate 52/min classified as","o":["SIRS","Respiratory distress","Tachypnoea","ARDS"],"a":1,"e":"Answer- B. Respiratory distress Tachypnea (fast breathing) : Fast breathing is defined as :-","pyqMatches":[{"year":"2015","no":1384,"q":"3 month old child with indrawing chest with respitratory rate 52/min classified as","o":["SIRS","Respiratory distress","Tachypnoea","ARDS"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7008, 'Pediatrics', 'Neurology', 'Hard', 'Pediatrics (1)', 213, '{"id":7008,"subject":"Pediatrics","chapter":"Neurology","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":213,"q":"45 day old infant presents with seizures. Examination reveals he is icteric, having bulging fontanelles and opisthotonic posture. Treatment is all except","o":["Phototherapy","Exchange Transfusion","Phenobarbitone","Chlorpromazine"],"a":3,"e":"Answer- D. Chlorpromazine Chlorpromazine is not used in hyperbilirubinemia. Treatment of hyperbilirubinemia includes","pyqMatches":[{"year":"2015","no":1385,"q":"45 day old infant presents with seizures. Examination reveals he is icteric, having bulging fontanelles and opisthotonic posture. Treatment is all except","o":["Phototherapy","Exchange Transfusion","Phenobarbitone","Chlorpromazine"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7009, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 214, '{"id":7009,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":214,"q":"Most common site for opening of TAPVC is -","o":["Supracardiac","Cardiac","Infracardiac","Multiple"],"a":0,"e":"Answer- A. Supracardiac Type I (Supra Cardiac) TAPVC Most common 45% Type II (Cardiac level) TAPVC - 25% Type III (Infra Cardiac) TAPVC - 25% Type IV (Multiple level) TAPVC 4 5%","pyqMatches":[{"year":"2015","no":1409,"q":"Most common site for opening of TAPVC is","o":["Supracardiac","Cardiac","Infracardiac","Multiple"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7010, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 215, '{"id":7010,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":215,"q":"Chronic lung disease in a infancy is defined as","o":["Need for supplemental oxygen at 36 weeks after conception","Tachypnoea > 50 breaths/ min within 1 week of birth","Presence of bilateral infiltrates on chest Xray for 2 weeks","Reticulogranular pattern on chest Xray for 6 weeks"],"a":0,"e":"Answer- A. Need for supplemental oxygen at 36 weeks after conception Chronic lung disease of infancy was formerly called bronchopulmonary dysplasia. Bronchopulmonary dysplasia is usually defined as a need for supplemental oxygen at 36 weeks after conception. Bronchopulmonary dysplasia is usually defined as a need for supplemental oxygen at 36 weeks after conception. BPD is usually defined as a need for supplemental oxygen at 36 wk after conception. BPD is a result of lung injury in infants requiring mechanical ventilation and supplemental oxygen.","pyqMatches":[{"year":"2015","no":1386,"q":"Chronic lung disease in a infancy is defined as","o":["Need for supplemental oxygen at 36 weeks after conception","Tachypnoea > 50 breaths/ min within 1 week of birth","Presence of bilateral infiltrates on chest Xray for 2 weeks","Reticulogranular pattern on chest Xray for 6 weeks"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7011, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 216, '{"id":7011,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":216,"q":"Most common antigen involved in erythroblastosis fetalis is","o":["C antigen in Rh group","D antigen in Rh group","E antigen in Rh group","Duffy antigen"],"a":1,"e":"Answer- B. D antigen in Rh group RBC antigens are capable of eliciting an antibody response, significant disease is associated primarily D antigen of Rh group and with ABO incompatibility","pyqMatches":[{"year":"2015","no":1387,"q":"Most common antigen involved in erythroblastosis fetalis is","o":["C antigen in Rh group","D antigen in Rh group","E antigen in Rh group","Duffy antigen"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7012, 'Pediatrics', 'Neonatology', 'Hard', 'Pediatrics (1)', 217, '{"id":7012,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":217,"q":"Eryhtematous blotchy rash is seen on the abdomen, trunk and face of a 3 day old child along with yellowish papules. However the child feels well. What is the management ?","o":["Steroid and antibiotic lotion","No treatment","Steroid cream","Urgent intravenous antibiotics"],"a":1,"e":"Answer- B. No treatment Erythema toxicum neonatorum is a benign self-limited eruption occurring primarily in healthy newborns in the early neonatal period. It is characterized by Erythematous papules on trunk & face. They appear on 2nd & 3rd day and disappear spontaneously.","pyqMatches":[{"year":"2015","no":1388,"q":"Eryhtematous blotchy rash is seen on the abdomen, trunk and face of a 3 day old child along with yellowish papules. However the child feels well. What is the management ?","o":["Steroid and antibiotic lotion","No treatment","Steroid cream","Urgent intravenous antibiotics"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7013, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 218, '{"id":7013,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":218,"q":"Further investigation is essential in a newborn with which condition?","o":["Erythema toxicum","Vaginal bleed","Subconjunctival hemorrhage","Lens opacity"],"a":3,"e":"Answer- D. Lens opacity The problems are","pyqMatches":[{"year":"2015","no":1389,"q":"Further investigation is essential in a newborn with which condition?","o":["Erythema toxicum","Vaginal bleed","Subconjunctival hemorrhage","Lens opacity"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7014, 'Pediatrics', 'Neonatology', 'Hard', 'Pediatrics (1)', 219, '{"id":7014,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":219,"q":"A newborn presents with subconjunctival hemorrhage. The treatment is","o":["No treatment","Antibiotic eye drops","Aspitation","Antibiotic and steroid drops"],"a":0,"e":"Answer- A. No treatment Subconjunctival hemorrhage in newborn is a normal phenomenom which disappears spontaneously.","pyqMatches":[{"year":"2015","no":1390,"q":"A newborn presents with subconjunctival hemorrhage. The treatment is","o":["No treatment","Antibiotic eye drops","Aspitation","Antibiotic and steroid drops"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7015, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 220, '{"id":7015,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":220,"q":"What is the shape of caecum in the newborn ?","o":["Ovoid","Trapezoid","Globular","Conical"],"a":3,"e":"Answer- D. Conical The shape of the caecum in an infant is conical with the appendix borne at the base of the cone.","pyqMatches":[{"year":"2015","no":1391,"q":"What is the shape of caecum in the newborn ?","o":["Ovoid","Trapezoid","Globular","Conical"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7016, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 221, '{"id":7016,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":221,"q":"Most common complication of Meckel''s Diverticulum lit children","o":["Abdominal pain","Peptic ulcers","Intestinal obstruction","Painless Rectal bleeding"],"a":3,"e":"Answer- D. Painless Rectal bleeding Most comnmon presentation of Meckel''s Diverticulum in children is painless rectal Bleeding. [Ref Alemayehu H, Hall M, Desai AA, St Peter SD, Snyder CL. Demographic disparities of children presenting with symptomatic Meckel''s diverticulum in children''s hospitals. Pediatric Surgery International. 2014 Jun 30. 6:649-653]","pyqMatches":[{"year":"2015","no":1392,"q":"Most common complication of Meckel''s Diverticulum lit children","o":["Abdominal pain","Peptic ulcers","Intestinal obstruction","Painless Rectal bleeding"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7017, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 222, '{"id":7017,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":222,"q":"Which of the following is a X linked metabolic disorder?","o":["Fabry''s disease","Sandoff s disease","Pompe disease","Gaucher disease"],"a":0,"e":"Answer- A. Fabry''s disease All lysosomal disorders are `autosomal recessive'' except for Hunter''s syndrome and Fabry''s disease, which are X-linked recessive. Thus Hunter''s syndrome and Fabry''s disease affect only male.","pyqMatches":[{"year":"2015","no":1393,"q":"Which of the following is a X linked metabolic disorder?","o":["Fabry''s disease","Sandoff s disease","Pompe disease","Gaucher disease"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7018, 'Pediatrics', 'Growth & Development', 'Moderate', 'Pediatrics (1)', 223, '{"id":7018,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":223,"q":"Testes are not palpable in","o":["SRY deletion","DAX 1 deletion","WNT- 4 gene mutation","RSPO-1 gene mutation"],"a":0,"e":"Answer- A. SRY deletion SRY gene is involved in development of male gonds (testes) from primitive (bipotential gonads). DAX-1, WNT-4 and RSPO1 genes are involved in development of female gonads (ovary).","pyqMatches":[{"year":"2015","no":1394,"q":"Testes are not palpable in","o":["SRY deletion","DAX 1 deletion","WNT- 4 gene mutation","RSPO-1 gene mutation"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7019, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 224, '{"id":7019,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":224,"q":"What is the maintainance fluid requirement in a 6 kg child ?","o":["240 ml/day","600 ml/day","300 ml/day","1200 ml/day"],"a":1,"e":"Answer- B. 600 ml/day Fluid Requirements in: Infants and Children HOLLIDAY - SEGAR METHOD First 10 kgl100ml/kg (4ml/kg/hr) Na+3 10-20kg 1000ml + 50ml/kg for each Kg>10kg (40ml/hr+2ml/kg/hr(wt-10kg) K+2 >20kg 1500ml + 20ml/kg for each Kg>20kg (60ml/hr + 1ml/kg/hr(wt-20 kg) Cl-2","pyqMatches":[{"year":"2015","no":1408,"q":"What is the maintainance fluid requirement in a 6 kg child ?","o":["240 ml/day","600 ml/day","300 ml/day","1200 ml/day"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7020, 'Pediatrics', 'Growth & Development', 'Moderate', 'Pediatrics (1)', 225, '{"id":7020,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":225,"q":"Kwashiorkor- Triad includes all except -","o":["Psychomotor changes","Hypoglycemia","Edema","Growth retardation"],"a":1,"e":"Answer- B. Hypoglycemia Classical triad of kwashiorkor is markedly retarded growth, psychomotor (mental) changes and edema.","pyqMatches":[{"year":"2015","no":1407,"q":"Kwashiorkor- Triad includes all except","o":["Psychomotor changes","Hypoglycemia","Edema","Growth retardation"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7021, 'Pediatrics', 'Gastroenterology', 'Hard', 'Pediatrics (1)', 226, '{"id":7021,"subject":"Pediatrics","chapter":"Gastroenterology","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":226,"q":"Child with 10 episodes of diarrhea in last 24 hours with sunken dry eyes, very slow skin pinch, and absent tears. Management is","o":["ORS solution","breast feeding","Start 10% dextrose","Start Ringer''s lactate"],"a":3,"e":"Answer- D. Start Ringer''s lactate This is a case of severe dehydration. Severe Dehydration Start IV fluids immediately Best IV fluid solution is Ringer lactate Normal saline can be used Dextrose is not effective 100 ml/kg is to be given as shown below: AGE FIRST THEN <12 months 30 nil/kg in I hours70 ml/kg 5 hours 12 months to 5 yrs.30 minutes 21/2 hrs","pyqMatches":[{"year":"2015","no":1395,"q":"Child with 10 episodes of diarrhea in last 24 hours with sunken dry eyes, very slow skin pinch, and absent tears. Management is","o":["ORS solution","breast feeding","Start 10% dextrose","Start Ringer''s lactate"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7022, 'Pediatrics', 'Gastroenterology', 'Hard', 'Pediatrics (1)', 227, '{"id":7022,"subject":"Pediatrics","chapter":"Gastroenterology","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":227,"q":"1 year old child with multiple episodes of diarrhea presents with sunken dry eyes, depressed fontanelles, very slow skin pinch. The amount of fluid to be given in the first 6 hours is","o":["600 ml","900 ml","1200 ml","1500 ml"],"a":1,"e":"Answer- B. 900 ml The approximate weight of a 1 year old child is 9kg (ie thrice the birth weight) The description of dehydration given above is consistent with severe dehydration. T","pyqMatches":[{"year":"2015","no":1396,"q":"1 year old child with multiple episodes of diarrhea presents with sunken dry eyes, depressed fontanelles, very slow skin pinch. The amount of fluid to be given in the first 6 hours is","o":["600 ml","900 ml","1200 ml","1500 ml"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7023, 'Pediatrics', 'Nephrology', 'Hard', 'Pediatrics (1)', 228, '{"id":7023,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":228,"q":"A 6 year old child presents with an abdominal mass, fever, bone pain and IVC thrombosis , the diagnosis could be -","o":["Wilm''s tumour","Neuroblastoma","Langerhans cell Histiocytosis","Gastric lymphoma"],"a":1,"e":"Amswer- B. Neuroblastoma Renal vein invasion is more characteristic of neuroblastoma (it is rare in wilms tumor).","pyqMatches":[{"year":"2015","no":1406,"q":"A 6 year old child presents with an abdominal mass, fever, bone pain and IVC thrombosis , the diagnosis could be","o":["Wilm''s tumour","Neuroblastoma","Langerhans cell Histiocytosis","Gastric lymphoma"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7024, 'Pediatrics', 'Gastroenterology', 'Easy', 'Pediatrics (1)', 229, '{"id":7024,"subject":"Pediatrics","chapter":"Gastroenterology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":229,"q":"What is the first line treatment of a 4 year old child presenting with intussusception ?","o":["Conservative management with wait and watch policy","Immediate attempt to reduction using barium edema","Surgical correction","Exploratory laparotomy with resection of the affected segment"],"a":1,"e":"Answer- B. Immediate attempt to reduction using barium edema Correction of intussusception by barium enema is the initial management of choice. If it fails, surgical correction is done.","pyqMatches":[{"year":"2015","no":1397,"q":"What is the first line treatment of a 4 year old child presenting with intussusception ?","o":["Conservative management with wait and watch policy","Immediate attempt to reduction using barium edema","Surgical correction","Exploratory laparotomy with resection of the affected segment"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7025, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 230, '{"id":7025,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":230,"q":"Hutchison''s Triad is seen in","o":["Congenital Syphilis","Tertiary syphilis","Secondary Syphilis","Primary syphilis"],"a":0,"e":"Answer- A. Congenital Syphilis Hutchinson''s triad is a common pattern of presentation of Congenital syphilis. It consists of three phenomena :","pyqMatches":[{"year":"2015","no":1398,"q":"Hutchison''s Triad is seen in","o":["Congenital Syphilis","Tertiary syphilis","Secondary Syphilis","Primary syphilis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7026, 'Pediatrics', 'Growth & Development', 'Hard', 'Pediatrics (1)', 231, '{"id":7026,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":231,"q":"A 8 year old child presents with a mass in the lumbar region with abdominal pain with excruciating bone pain. Possible diagnosis is -","o":["Neuroblastoma","Wilm''s Tumour","Lymphoma","Angiomyolipoma"],"a":0,"e":"Amswer- A. Neuroblastoma This is a case of neuroblastoma that has metastatized Metastasis is present in 60-70% at the time of diagnosis. Commonest site of metastasis is skeletal system and neuroblastoma is the most common childhood malignancy metastasizes to bone.","pyqMatches":[{"year":"2015","no":1405,"q":"A 8 year old child presents with a mass in the lumbar region with abdominal pain with excruciating bone pain. Possible diagnosis is","o":["Neuroblastoma","Wilm''s Tumour","Lymphoma","Angiomyolipoma"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7027, 'Pediatrics', 'Neurology', 'Moderate', 'Pediatrics (1)', 232, '{"id":7027,"subject":"Pediatrics","chapter":"Neurology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":232,"q":"Triad of normal pressure hydrocephalus includes all except -","o":["Dementia","Gait disturbance","Urinary incontinence","Browache"],"a":3,"e":"Answer- D. Browache Triad of normal pressure hydrocephalus/Adam''s triad/Hakim''s triad Dementia Gait disturbance Urinary incontinece (wet, wacky and wobbly)","pyqMatches":[{"year":"2015","no":1400,"q":"Triad of normal pressure hydrocephalus includes all except","o":["Dementia","Gait disturbance","Urinary incontinence","Browache"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7028, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 233, '{"id":7028,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":233,"q":"True about cephalhematoma is -","o":["It is hemorrhage between the skull and periosteum","It is hemorrhage within the subcutaneous tissue around the skull","It is type of subdural hemorrhage","It is extraperiosteal bleeding in the skull"],"a":0,"e":"Amswer- A. It is hemorrhage between the skull and periosteum Cephalhematoma is subperiosteal bleeding, i.e. between skull bone and periosteum.","pyqMatches":[{"year":"2015","no":1404,"q":"True about cephalhematoma is","o":["It is hemorrhage between the skull and periosteum","It is hemorrhage within the subcutaneous tissue around the skull","It is type of subdural hemorrhage","It is extraperiosteal bleeding in the skull"],"a":0,"source":"NEET_2015_Paper.pdf"},{"year":"2016","no":1580,"q":"True about cephalhematoma is :","o":["Crosses the suture lines","Always present at birth","Ventouse delivery is a risk factor","All of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2015","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7029, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 234, '{"id":7029,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":234,"q":"Medulloblatoma arises exclusively from the cells of","o":["Immature embryonal cells","Ependymal cells","Neurons","Spindle shaped cells"],"a":0,"e":"Answer- A. Immature embryonal cells Medulloblastoma is the most common PNET (primitive neuroectodermal tumor) located in posterior cranial fossa. [Ref Hinz, Chris; Hesser, Deneen. Focusing On Brain Tumors: Medulloblastoma. American Brain Tumor Association]","pyqMatches":[{"year":"2015","no":1401,"q":"Medulloblatoma arises exclusively from the cells of","o":["Immature embryonal cells","Ependymal cells","Neurons","Spindle shaped cells"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7030, 'Pediatrics', 'Neurology', 'Moderate', 'Pediatrics (1)', 235, '{"id":7030,"subject":"Pediatrics","chapter":"Neurology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":235,"q":"Which of the following is not true about encephalocoele?","o":["It is a neural tube defect","Common in the frontal region","Can be associated with hydrocephalus","It is protrusion of neural tissue through a defect"],"a":0,"e":"Answer- A. It is a neural tube defect Perinatal asphyxia, more appropriately known as hypoxic-ischemic encephalopathy (HIE), is characterized by clinical and laboratory evidence of acute or subacute brain injury due to asphyxia. The primary causes of this condition are systemic hypoxemia and/or reduced cerebral blood flow (CBF)","pyqMatches":[{"year":"2015","no":1403,"q":"Which of the following is not true about encephalocoele?","o":["It is a neural tube defect","Common in the frontal region","Can be associated with hydrocephalus","It is protrusion of neural tissue through a defect"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7031, 'Pediatrics', 'Cardiology', 'Moderate', 'Pediatrics (1)', 236, '{"id":7031,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":236,"q":"Most common conotruncal anomaly","o":["TGA","Tetralogy of fallot","Truncus arteriosus","Double oulet right ventricle"],"a":0,"e":"Answer- A. TGA Conotruncal defects are abnormalities of outflow tract septation or ectomesenchymal tissue migration abnormalities. Most common conotructal defect is transposition of great arteries (TGA).","pyqMatches":[{"year":"2014","no":1603,"q":"Most common conotruncal anomaly","o":["TGA","Tetralogy of fallot","Truncus arteriosus","Double oulet right ventricle"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7032, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 237, '{"id":7032,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":237,"q":"Meconium can passed upto → days in healthy bady -","o":["1","3","5","7"],"a":1,"e":"Answer- B. 3 Meconium is passed within → 24 hours of birth. Meconium stools are passed → upto 3 days. Transition stools are passed → zith & 5th days. Regular milk stools are passed → After 5 days.","pyqMatches":[{"year":"2014","no":1697,"q":"Meconium can passed upto → days in healthy bady","o":["1","3","5","7"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7033, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 238, '{"id":7033,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":238,"q":"Fallot physiology includes all except","o":["TOF","Eisenmenger complex","TGA","Tricuspid atresia"],"a":1,"e":"Answer- B. Eisenmenger complex These includes","pyqMatches":[{"year":"2014","no":1604,"q":"Fallot physiology includes all except","o":["TOF","Eisenmenger complex","TGA","Tricuspid atresia"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7034, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 239, '{"id":7034,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":239,"q":"Pulmonary plethora is seen with - all except","o":["TGA","Hypoplastic left heart syndrome","Ebstein anomalis","Double outlet right ventricle"],"a":2,"e":"Answer- C. Ebstein anomalis Pulmonary oligamia TOF TA Ebstein''s anomaly Pulmonary atresia","pyqMatches":[{"year":"2014","no":1612,"q":"Pulmonary plethora is seen with - all except","o":["TGA","Hypoplastic left heart syndrome","Ebstein anomalis","Double outlet right ventricle"],"a":2,"source":"NEET_2014_Paper.pdf"},{"year":"2020","no":154,"q":"Pulmonary plethora is seen with all except:","o":["TGS","Ebstein anomalies","Hypoplastic left heart syndrome","Double outlet right ventricle"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2014","2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7035, 'Pediatrics', 'Infectious Diseases', 'Easy', 'Pediatrics (1)', 240, '{"id":7035,"subject":"Pediatrics","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":240,"q":"Child with rash- wrong is","o":["Typhus - day 5","Varicella - day 1","Typhoid - day 5","Measles - day 4"],"a":2,"e":"Answer- C. Typhoid - day 5 Very Sick Person Must Take Double Tablets Very Varicella (day 1) Sick Scarlet fever (day 2) Person Pox-small pox (day 3) Must Measles (day 4) Take Typhus (day 5) Double Dengue (day 6) Tablets Typhoid (day 7)","pyqMatches":[{"year":"2014","no":1640,"q":"Child with rash- wrong is","o":["Typhus - day 5","Varicella - day 1","Typhoid - day 5","Measles - day 4"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7036, 'Pediatrics', 'Neurology', 'Easy', 'Pediatrics (1)', 241, '{"id":7036,"subject":"Pediatrics","chapter":"Neurology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":241,"q":"What is recurrence of febrile seizure -","o":["10-20%","20-30%","30-50%","50-70%"],"a":2,"e":"Answer- C. 30-50% Recurrent febrile seizures occur in 30-50% of cases. More than 90% of febrile seizures are generalized. Acute respiratory illness are most commonly associated with febrile seizures.","pyqMatches":[{"year":"2014","no":1671,"q":"What is recurrence of febrile seizure","o":["10-20%","20-30%","30-50%","50-70%"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7037, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 242, '{"id":7037,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":242,"q":"In neonate, intra muscular injection given at -","o":["Deltoid","Gluteal","Thigh","Abdomen"],"a":2,"e":"Answer- C. Thigh Anterolateral aspect of thigh because of lack of important blood vessel & nerve is preferred site upto 12 month of age.","pyqMatches":[{"year":"2014","no":1664,"q":"In neonate, intra muscular injection given at","o":["Deltoid","Gluteal","Thigh","Abdomen"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7038, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 243, '{"id":7038,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":243,"q":"Sitting in Tripod position at which month ?","o":["5 months","6 months","8 months","9 months"],"a":1,"e":"Answer- B. 6 months 6 Month → Sit with support, sits in tripod position 8 Month → Sit without support 9 Month → Stand with support 12 Month → Stand without support Walk with support 15 Month → Walk alone, creep upstair","pyqMatches":[{"year":"2013","no":1423,"q":"Sitting in Tripod position at which month ?","o":["5 months","6 months","8 months","9 months"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7039, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 244, '{"id":7039,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":244,"q":"Weight of newborn quadruplets by -","o":["9 months","12 months","2 year","3 years"],"a":2,"e":"Answer- C. 2 year Triple- 1 yr Four times- 2 yrs Five times- 3 yrs","pyqMatches":[{"year":"2013","no":1424,"q":"Weight of newborn quadruplets by","o":["9 months","12 months","2 year","3 years"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7040, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 245, '{"id":7040,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":245,"q":"From 6 weeks to 12 weeks... Infant weight increases at rate of -","o":["30 g/d","40 g/d","50 g/d","60 g/d"],"a":0,"e":"Answer- A. 30 g/d Average weight of New born baby is 3 kg. Newborn loses extracellular fluid about 10% of body weight and start gaining weight and become equal to birth weight at day 10 of life. Subsequently, they gain weight at a rate of approximately 25 to 30 gm per day for the first 3 month of life.","pyqMatches":[{"year":"2013","no":1425,"q":"From 6 weeks to 12 weeks... Infant weight increases at rate of","o":["30 g/d","40 g/d","50 g/d","60 g/d"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7041, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 246, '{"id":7041,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":246,"q":"Arm span and height become same at what age (year) -","o":["9","11","13","15"],"a":1,"e":"Answer- B. 11 In under-5 children , arm span is 1 to 2 cm smaller than body length. During 10-12 years of age , arm span = height. In adults arm span is more in adults by 2 cm. Abnormally large arm span is seen in patients with : (1) Arachnodactyly (Marfan syndrome) (2) Eunuchoidism (3) Klinefelter''s Syndrome (4) Coarctation of aorta.","pyqMatches":[{"year":"2013","no":1426,"q":"Arm span and height become same at what age (year)","o":["9","11","13","15"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7042, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 247, '{"id":7042,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":247,"q":"In protein deficiency all are seen except -","o":["Flaky paint like skin","Glossitis","Nail change","Cherry like skin"],"a":3,"e":"Answer- D. Cherry like skin redness on the skin, brittle nails, thin hair Glossitis Risk of infections Fatty liver Protein deficiency may leave its mark on the skin, hair and nails.","pyqMatches":[{"year":"2013","no":1431,"q":"In protein deficiency all are seen except","o":["Flaky paint like skin","Glossitis","Nail change","Cherry like skin"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7043, 'Pediatrics', 'Growth & Development', 'Hard', 'Pediatrics (1)', 248, '{"id":7043,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":248,"q":"In a child having diarrhoea with perianal moist crust. The diagnosis is -","o":["Acrodermatitis enteropathica","Riboflavin dificiency","Pellagra","None of above"],"a":0,"e":"Answer- A'' Acrodermatitis enteropathica Acrodermatitis enteropathica is a rare autosomal recessive disorder caused by an inability to absorb sufficient Zinc from the diet. Associated manifestations :- Chronic diarrhoea, stomatitis, glossitis, Paronychia, Nail dystrophy, Growth retardation, irritability, delayed wound healing, Bacterial & candidal infection.","pyqMatches":[{"year":"2013","no":1432,"q":"In a child having diarrhoea with perianal moist crust. The diagnosis is","o":["Acrodermatitis enteropathica","Riboflavin dificiency","Pellagra","None of above"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7044, 'Pediatrics', 'Neurology', 'Easy', 'Pediatrics (1)', 249, '{"id":7044,"subject":"Pediatrics","chapter":"Neurology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":249,"q":"Vitamin B6 is used in treatment of -","o":["Homocystinuria","Xanthourenic aciduria","Cystathionuria","All of above"],"a":3,"e":"Answer- D. All of above Vit B6 dependent convulsion. Vit B6 responsive anemia. Xanthurenic acidmia Cystathioninuria Homocystinuria","pyqMatches":[{"year":"2013","no":1433,"q":"Vitamin B6 is used in treatment of","o":["Homocystinuria","Xanthourenic aciduria","Cystathionuria","All of above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7045, 'Pediatrics', 'Cardiology', 'Easy', 'Pediatrics (1)', 250, '{"id":7045,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":250,"q":"Prostaglandin analogue used in PDA is -","o":["Anaprastone","Misoprost","Danaprostone","PGE-2"],"a":1,"e":"Answer- B. Misoprost Prostaglandin inhibitor such as indomethacin and special form of ibuprofen are used for duct closure in preterm. PGE-1 used to keep open duct are Alprostadil or misoprostol.","pyqMatches":[{"year":"2013","no":1438,"q":"Prostaglandin analogue used in PDA is","o":["Anaprastone","Misoprost","Danaprostone","PGE-2"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7046, 'Pediatrics', 'Cardiology', 'Easy', 'Pediatrics (1)', 251, '{"id":7046,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":251,"q":"Drug used to keep PDA open -","o":["PGE1","PGI2","PGE","PGH2"],"a":0,"e":"Answer- A. PGE1 Prostaglandin nt 1fbe,; infusion usually efective in keeping the ductus arteriosus open before surgical intervention to reduce hypoxemia and acidemia before surgery in ductus dependent lesion like.","pyqMatches":[{"year":"2013","no":1439,"q":"Drug used to keep PDA open","o":["PGE1","PGI2","PGE","PGH2"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7047, 'Pediatrics', 'Cardiology', 'Easy', 'Pediatrics (1)', 252, '{"id":7047,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":252,"q":"WPW syndrome is associated with -","o":["Ebstein anomaly","TOF","VSD","TAPVC"],"a":0,"e":"Answer- A. Ebstein anomaly Wolff-Parkinson-White syndrome (WPW) is one of several disorders of the conduction system of the heart that are commonly referred to as pre-excitation syndromes. People with WPW may have more than one accessory pathway seen in individuals with Ebstein''s anomaly.","pyqMatches":[{"year":"2013","no":1443,"q":"WPW syndrome is associated with","o":["Ebstein anomaly","TOF","VSD","TAPVC"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7048, 'Pediatrics', 'Cardiology', 'Easy', 'Pediatrics (1)', 253, '{"id":7048,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":253,"q":"Most common syndrome associated with A-V canal defect -","o":["Down syndrome","Klinfilter syndrome","Turner syndrome","Marfan syndrome"],"a":0,"e":"Answer- A. Down syndrome It is also called as atrioventricular canal defect (AVCD) or endocardial cushion defect. It covers a spectrum of congenital heart malformation characterized by contiguous atrial and ventricular septal defects with markedly abnormal AV valve. AVSD may be :-","pyqMatches":[{"year":"2013","no":1445,"q":"Most common syndrome associated with A-V canal defect","o":["Down syndrome","Klinfilter syndrome","Turner syndrome","Marfan syndrome"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7049, 'Pediatrics', 'Neurology', 'Easy', 'Pediatrics (1)', 254, '{"id":7049,"subject":"Pediatrics","chapter":"Neurology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":254,"q":"% of children with simple febrile seizure developing epilepsy is -","o":["1-2 %","2-5 %","5-10 %","10-15 %"],"a":0,"e":"Answer- A. 1-2 % Between 2% to 7% of all children with febrile seizures develop epilepsy if followed upto the age of 25 years. Risk depends on type of febrile seizure :","pyqMatches":[{"year":"2013","no":1449,"q":"% of children with simple febrile seizure developing epilepsy is","o":["1-2 %","2-5 %","5-10 %","10-15 %"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7050, 'Pediatrics', 'Neurology', 'Easy', 'Pediatrics (1)', 255, '{"id":7050,"subject":"Pediatrics","chapter":"Neurology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":255,"q":"Common deformity in chiari H malformation is -","o":["Syringomyelia","Meningo myelocele","Hydrocephalus","All of above"],"a":3,"e":"Answer- D. All of above Chiari malformation is divided into :","pyqMatches":[{"year":"2013","no":1453,"q":"Common deformity in chiari H malformation is","o":["Syringomyelia","Meningo myelocele","Hydrocephalus","All of above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7051, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 256, '{"id":7051,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":256,"q":"A child of less than one year with asthma treatment -","o":["MDI with Spacer","MDI with Mask","MDI with Spacer with Mask","MPI with mask"],"a":2,"e":"Answer- C. MDI with Spacer with Mask MDI alone require better press and breath co-ordination so used above 12 years of age. MDI with spacer overcome breath co-ordination so used above 4 years of age. MDI with spacer with mask can be used successfully in children below 4 years of age.","pyqMatches":[{"year":"2013","no":1456,"q":"A child of less than one year with asthma treatment","o":["MDI with Spacer","MDI with Mask","MDI with Spacer with Mask","MPI with mask"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7052, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 257, '{"id":7052,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":257,"q":"Treatment of bronchiolitis includes all except -","o":["Macrolides","Humid oxygen","Bronchodilator","All of above"],"a":0,"e":"Answer- A. Macrolides Bronchiolitis is predominantly a viral disease.","pyqMatches":[{"year":"2013","no":1457,"q":"Treatment of bronchiolitis includes all except","o":["Macrolides","Humid oxygen","Bronchodilator","All of above"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7053, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 258, '{"id":7053,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":258,"q":"Most common pulmonary tumor in children is -","o":["Carcinoid","Small cell carcinoma","Adeno carcinoma","Squamous cell carcinoma"],"a":0,"e":"Answer- A. Carcinoid The most common tumor types are carcinoid , inflammatory myofibroblastic tumor , and pleuropulmonary blastoma Rare pediatric lung tumors including small cell carcinoma, adenocarcinoma, and pulmonary capillary hemangiomatosis were also seen.","pyqMatches":[{"year":"2013","no":1460,"q":"Most common pulmonary tumor in children is","o":["Carcinoid","Small cell carcinoma","Adeno carcinoma","Squamous cell carcinoma"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7054, 'Pediatrics', 'Gastroenterology', 'Easy', 'Pediatrics (1)', 259, '{"id":7054,"subject":"Pediatrics","chapter":"Gastroenterology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":259,"q":"Most common cause of per rectal bleeding in infant is -","o":["Anal fissure","Rectal polyp","Intussusception","Hypertension"],"a":0,"e":"Answer- A. Anal fissure Anal fissures are the most common cause of rectal bleeding in infants and children.","pyqMatches":[{"year":"2013","no":1462,"q":"Most common cause of per rectal bleeding in infant is","o":["Anal fissure","Rectal polyp","Intussusception","Hypertension"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7055, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 260, '{"id":7055,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":260,"q":"Most common anomaly of upper urogenital tract is -","o":["Uretero pelvic junction stenosis","Ectopic uretheral opening","Ureterocele","Ectopic ureter"],"a":0,"e":"Answer- A. Uretero pelvic junction stenosis Most common cause of urinary tract obstruction in children - Posterior urethral valves. Most common cause of lower urinary tract obstruction in children -> Posterior urethral valves. Most common cause of upper urinary tract obstruction in children 4 PUJ obstruction.","pyqMatches":[{"year":"2013","no":1463,"q":"Most common anomaly of upper urogenital tract is","o":["Uretero pelvic junction stenosis","Ectopic uretheral opening","Ureterocele","Ectopic ureter"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7056, 'Pediatrics', 'Nephrology', 'Easy', 'Pediatrics (1)', 261, '{"id":7056,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":261,"q":"Features of cystinuria are","o":["Impaired proximal tubular reabsorption of cystine","Autosomal recessive","Recurrent renal stone","All of the above"],"a":3,"e":"Answer- D. All of the above Cystinuria Biochemical Defect: An autosomal recessive disorder that results in the formation of a defective amino acid transporter in the renal tubule and intestinal epithelial cells. Pathophysiology: The amino acid transporter is responsible for transporting cystine, ornithine, lysine, and arginine. Defective tubular reabsorption of these amino acids in the kidneys results in increased cysteine in the urine, which can precipitate and cause kidney stones. Clinical Manifestations: Cysteine kidney stones presenting with severe, intermittent flank pain and hematuria. Lab findings: Increased urinary excretion of cystine, ornithine, arginine, and lysine on urine amino acid chromatography; hematuria and cysteine crystals (hexagonal) on the cooling of acidified urine sediment. Imaging: Radiopaque kidney stones on CT scan. The most specific test is the cyanide–nitroprusside test Treatment: Low-methionine diet; increased fluid intake; acetazolamide to alkalinize the urine. If this fails then patients are usually started on chelating therapy with penicillamine.","pyqMatches":[{"year":"2013","no":1465,"q":"Features of cystinuria are","o":["Impaired proximal tubular reabsorption of cystine","Autosomal recessive","Recurrent renal stone","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7057, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 262, '{"id":7057,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":262,"q":"Second degree consanguineous marriage, baby with diarrhoea, perianal diaper area redness -","o":["Lactose intolerance","Shigella diarrhoea","Salmonella","Fungal"],"a":0,"e":"Answer- A. Lactose intolerance In Lactose intolerance, there is deficiency of enzyme lactase. So No natural breakdown of lactose - a carbohydrate present in milk. This causes diarrhoea. Stool contains reducing sugar which causes perianal excoriation.","pyqMatches":[{"year":"2013","no":1467,"q":"Second degree consanguineous marriage, baby with diarrhoea, perianal diaper area redness","o":["Lactose intolerance","Shigella diarrhoea","Salmonella","Fungal"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7058, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 263, '{"id":7058,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":263,"q":"On USG a mass was found in abdomen which was displacing the kidney laterally in 1 year old child -","o":["Neuroblastoma","Nephroblastoma","RCC","All of the above"],"a":0,"e":"Answer- A. Neuroblastoma The commonest intra-abdominal tumor in first two years of life Neuroblastoma","pyqMatches":[{"year":"2013","no":1469,"q":"On USG a mass was found in abdomen which was displacing the kidney laterally in 1 year old child","o":["Neuroblastoma","Nephroblastoma","RCC","All of the above"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7059, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 264, '{"id":7059,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":264,"q":"Drugs used in ALL in child are all except -","o":["Methotrexate","Vincristine","Vinblastine","Cyclophosphamids"],"a":2,"e":"Answer- C. Vinblastine Treatment of ALL is divided into 4 stages. The total duration of treatment ranges between 2 and 2% years.","pyqMatches":[{"year":"2013","no":1471,"q":"Drugs used in ALL in child are all except","o":["Methotrexate","Vincristine","Vinblastine","Cyclophosphamids"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7060, 'Pediatrics', 'Hematology', 'Hard', 'Pediatrics (1)', 265, '{"id":7060,"subject":"Pediatrics","chapter":"Hematology","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":265,"q":"34 week primigravida punjabi khatri comes with history of consanguineous marriage, with history of repeated blood transfusion to her sibling since 8 months of age. The first diagnostic test is -","o":["HPLC","Blood smear","Bone marrow","Hb electrophoresis"],"a":1,"e":"Answer- B. Blood smear Type of hemoglobin is detected by Hb electrophoresis. In this case, Hb electrophoresis of the woman should be done. If she comes positive for abnormal hemoglobin, she should be counselled about termination of pregnancy.","pyqMatches":[{"year":"2013","no":1472,"q":"34 week primigravida punjabi khatri comes with history of consanguineous marriage, with history of repeated blood transfusion to her sibling since 8 months of age. The first diagnostic test is","o":["HPLC","Blood smear","Bone marrow","Hb electrophoresis"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7061, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 266, '{"id":7061,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":266,"q":"3 beta hydroxysteroid dehydrogenase deficiency causes increase production of -","o":["DHEA","Progesterone","Deoxycortisol","Estradiol"],"a":0,"e":"Answer- A. DHEA There is elevated level of pregenolone, 17a-OH pergenelone DHEA and decreas level of progesterone, deoxycortisol and estradiol.","pyqMatches":[{"year":"2013","no":1474,"q":"3 beta hydroxysteroid dehydrogenase deficiency causes increase production of","o":["DHEA","Progesterone","Deoxycortisol","Estradiol"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7062, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 267, '{"id":7062,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":267,"q":"2-5 year old child with DM, target HbA, C is -","o":["< 8 %","< 7 %","< 9 %","< 6 %"],"a":2,"e":"Answer- C. < 9 % In children below 5 year of age, target HBA1C is 7.5 - 9%.","pyqMatches":[{"year":"2013","no":1478,"q":"2-5 year old child with DM, target HbA, C is","o":["< 8 %","< 7 %","< 9 %","< 6 %"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7063, 'Pediatrics', 'Miscellaneous', 'Hard', 'Pediatrics (1)', 268, '{"id":7063,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":268,"q":"Prenatal diagnosis of Down Syndrome is by -","o":["Karyo typing","Triple test","Fetal ultrasonography","All of above"],"a":3,"e":"Answer- D. All of above Following methods are used :","pyqMatches":[{"year":"2013","no":1480,"q":"Prenatal diagnosis of Down Syndrome is by","o":["Karyo typing","Triple test","Fetal ultrasonography","All of above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7064, 'Pediatrics', 'Infectious Diseases', 'Hard', 'Pediatrics (1)', 269, '{"id":7064,"subject":"Pediatrics","chapter":"Infectious Diseases","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":269,"q":"5 year old child develop fever and rash on first day and rash disappear, after few days develop child develop ataxia. Most probable diagnosis is -","o":["Measles","Fifth disease","Chicken pox","Rocky mountain spotted fever"],"a":0,"e":"Answer- A. Measles Information :","pyqMatches":[{"year":"2013","no":1481,"q":"5 year old child develop fever and rash on first day and rash disappear, after few days develop child develop ataxia. Most probable diagnosis is","o":["Measles","Fifth disease","Chicken pox","Rocky mountain spotted fever"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7065, 'Pediatrics', 'Gastroenterology', 'Easy', 'Pediatrics (1)', 270, '{"id":7065,"subject":"Pediatrics","chapter":"Gastroenterology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":270,"q":"MC symptom of AIDS in infant is -","o":["GI infection","Persistent cough","Failure to thrive","Lymphadenopathy"],"a":0,"e":"Answer- A. GI infection Features in older children - Growth failure Fever Diarrhea Secondary infection","pyqMatches":[{"year":"2013","no":1483,"q":"MC symptom of AIDS in infant is","o":["GI infection","Persistent cough","Failure to thrive","Lymphadenopathy"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7066, 'Pediatrics', 'Neonatology', 'Hard', 'Pediatrics (1)', 271, '{"id":7066,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":271,"q":"Baby borne to patient suspected of chlamydial infection sample to be taken for diagnosis -","o":["Conjunctival","Urethral","Urine sample","Blood"],"a":0,"e":"Answer- A. Conjunctival About 70% of baby born to positive chlamydal infection develop conjuctivitis at day 5 of life so sample taken for diagnosis is conjuctival. Chlamydal infection is most common cause of conjuctivitis in newborn. Chlamydal infection causes watering dischange form eye (unlike purulent dischange in Gonococcal). [Ref Debbie-Metal Newborn & Infant Nursing Review (NAINR 2004)]","pyqMatches":[{"year":"2013","no":1484,"q":"Baby borne to patient suspected of chlamydial infection sample to be taken for diagnosis","o":["Conjunctival","Urethral","Urine sample","Blood"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7067, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 272, '{"id":7067,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":272,"q":"Features of Refsum disease are all except -","o":["Ataxia","CCF","Ichthiois","Retinitis pigmentosa"],"a":1,"e":"Answer- B. CCF Peroxisomal disorder. Defective enzyme - phytonoyl CoA oxidase. Clinical feature includes","pyqMatches":[{"year":"2013","no":1485,"q":"Features of Refsum disease are all except","o":["Ataxia","CCF","Ichthiois","Retinitis pigmentosa"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7068, 'Pediatrics', 'Cardiology', 'Hard', 'Pediatrics (1)', 273, '{"id":7068,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":273,"q":"Young child with laughing spells. Diagnosis -","o":["Hypothalamic hamartoma","Tetralogy of fallot","Nitrous oxide poisoning","None of the above"],"a":0,"e":"Answer- A. Hypothalamic hamartoma Laughing spills (also know as Gelastic seizure) Gelastic seizures are epileptic events characterized by bouts of laughter. Laughter-like vocalization is usually combined with facial contraction in the form of a smile. Autonomic features such as flushing, tachycardia, and altered respiration are widely recognized. Gelastic seizures have been associated classically to hypothalamic hamartomas.","pyqMatches":[{"year":"2013","no":1487,"q":"Young child with laughing spells. Diagnosis","o":["Hypothalamic hamartoma","Tetralogy of fallot","Nitrous oxide poisoning","None of the above"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7069, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 274, '{"id":7069,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":274,"q":"Thirteen pair of Ribs are seen in ?","o":["Down syndrome","Holt oram","Turner","Fibrous dysplasia"],"a":0,"e":"Answer- A. Down syndrome 7 pair Trisomy 21, cleidocranial dysplasia 11 pair Trisomy 18,21 13 pair Trisomy 21 14 pair VATER Syndrome [Ref Abnormal number of fetal ribs in USG by Liat Gindes et.al.]","pyqMatches":[{"year":"2013","no":1489,"q":"Thirteen pair of Ribs are seen in ?","o":["Down syndrome","Holt oram","Turner","Fibrous dysplasia"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7070, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 275, '{"id":7070,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":275,"q":"What is the age of the child who draws a circle and builds tower of 7 cubes?","o":["1 year","2 years","21/2 years","3 years"],"a":3,"e":"Answer- D. 3 years Age Milestone Age Number of cubes of tower 12-24 Tries to scribble 12 months 2 spontaneously months 3 2 years Draws a vertical or horizontal line 15 months 4 3 years Draws a circle 18 months 6 4 years Draws a cross (plus sign) and draws a rectangle 21 months 24 months 7 5 years Draws a triangle 30 months 9 36 months 10","pyqMatches":[{"year":"2016","no":1407,"q":"What is the age of the child who draws a circle and builds tower of 7 cubes?","o":["1 year","2 years","21/2 years","3 years"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7071, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 276, '{"id":7071,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":276,"q":"By what age is the milestone of climbing steps with alternate feet achieved?","o":["2 years","3 years","4 years","5 years"],"a":1,"e":"Answer- B. 3 years Walk independently- 1 year unwell, climbing upstairs and going downstairs with one step at a time- 2 years Ride tricycle; climbing upstairs with alternate feet- 3 years Hopping; going downstairs with alternate feet- 4 years Skipping- 5 years","pyqMatches":[{"year":"2016","no":1408,"q":"By what age is the milestone of climbing steps with alternate feet achieved?","o":["2 years","3 years","4 years","5 years"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7072, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 277, '{"id":7072,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":277,"q":"Mature finger grip comes at what age?","o":["5 months","7 months","9 months","1 year"],"a":2,"e":"Answer- C. 9 months 6 months → Drops one object when another is offered 7 months → Transfers object & unidextrous approach 9 months → -p Pincer grasp 12 — 13 months → Casting appear, mouthing disappear 15 months → Feeds himself with cup, slight spillage","pyqMatches":[{"year":"2016","no":1409,"q":"Mature finger grip comes at what age?","o":["5 months","7 months","9 months","1 year"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7073, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 278, '{"id":7073,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":278,"q":"Social smile is attained at what age?","o":["2 months","5 months","9 months","1 year"],"a":0,"e":"Answer- A. 2 months Social smile develops at 2 months.","pyqMatches":[{"year":"2016","no":1410,"q":"Social smile is attained at what age?","o":["2 months","5 months","9 months","1 year"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7074, 'Pediatrics', 'Growth & Development', 'Moderate', 'Pediatrics (1)', 279, '{"id":7074,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":279,"q":"Arrange the following milestones in the correct order of their attainment I. Build tower of 4 cubes II. Make simple sentences III. Drawing a circle IV. Drawing a rectangle","o":["II → III → IV → I","I → II → III → IV","II → I → III → IV","I → II → IV → III"],"a":1,"e":"Answer- B. I → II → III → IV The age of attainment of the milestones is :- Builds a tower of 4 cubes →18 months Makes simple sentences → 2 years Drawing a circle → 3 years Drawing a rectangle → 4 years","pyqMatches":[{"year":"2016","no":1411,"q":"Arrange the following milestones in the correct order of their attainment I. Build tower of 4 cubes II. Make simple sentences III. Drawing a circle IV. Drawing a rectangle","o":["II → III → IV → I","I → II → III → IV","II → I → III → IV","I → II → IV → III"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7075, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 280, '{"id":7075,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":280,"q":"By what age can a newborn recognize mother?","o":["2 months","3 months","6 months","7 months"],"a":1,"e":"Answer- B. 3 months Head control Starts cooing Recognizes mother Can follow an object upto 180° On pulling the child to sit, head lags partially (between 2-3 months). After 3 months head control develops.","pyqMatches":[{"year":"2016","no":1412,"q":"By what age can a newborn recognize mother?","o":["2 months","3 months","6 months","7 months"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7076, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 281, '{"id":7076,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":281,"q":"Which of the following can be done by an 18 months old baby?","o":["Making tower of 9 cubes","Can use 10 words with meaning","Ride tricycle","Turn pages of book one at a time"],"a":1,"e":"Answer- B. Can use 10 words with meaning At 18 months, the child can use 10 words with meaning.","pyqMatches":[{"year":"2016","no":1413,"q":"Which of the following can be done by an 18 months old baby?","o":["Making tower of 9 cubes","Can use 10 words with meaning","Ride tricycle","Turn pages of book one at a time"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7077, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 282, '{"id":7077,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":282,"q":"A child of 5 years can use sentences of around how many words?","o":["6 words","10 words","100 words","250 words"],"a":1,"e":"Answer- B. 10 words Although a child has a vocabulary of 250 words at 3 years, the child can use sentence of 10 words at 5 years.","pyqMatches":[{"year":"2016","no":1415,"q":"A child of 5 years can use sentences of around how many words?","o":["6 words","10 words","100 words","250 words"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7078, 'Pediatrics', 'Growth & Development', 'Moderate', 'Pediatrics (1)', 283, '{"id":7078,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":283,"q":"Milestones achieved by a 10 months old child are all except -","o":["Pincer grasp","Waving bye - bye","Standing without support","Plays a peek - a - boo game"],"a":2,"e":"Answer- C. Standing without support Baby stands without support by 1 year of age. Pincer grasp → 9 months Waving bye - bye → 9 months Plays a peek - a - boo game → 10 months","pyqMatches":[{"year":"2016","no":1416,"q":"Milestones achieved by a 10 months old child are all except","o":["Pincer grasp","Waving bye - bye","Standing without support","Plays a peek - a - boo game"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7079, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 284, '{"id":7079,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":284,"q":"What is the age of a child who can identify 4 colours and draw a triangle?","o":["21/2 years","3 years","4 years","5 years"],"a":3,"e":"Answer- D. 5 years A child learns to draw a triangle at the age of 5 years. Identification of four colours is attained at the age of 4 years.","pyqMatches":[{"year":"2016","no":1417,"q":"What is the age of a child who can identify 4 colours and draw a triangle?","o":["21/2 years","3 years","4 years","5 years"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7080, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 285, '{"id":7080,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":285,"q":"Weight of an infant doubles by what age?","o":["6 months","1 year","2 years","3 years"],"a":2,"e":"Answer- C. 2 years Weight of an infant doubles by 5 months and quadruples by 2 years of age.","pyqMatches":[{"year":"2016","no":1418,"q":"Weight of an infant doubles by what age?","o":["6 months","1 year","2 years","3 years"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7081, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 286, '{"id":7081,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":286,"q":"Growth of head circumference in 1st 3 months of life is by","o":["2 cm","3 cm","5 cm","10 cm"],"a":2,"e":"Answer- C. 5 cm Head circumference is measured from the occipital protuberance to the supraorbital ridge of forehead which is the maximum occipito frontal diameter of skull. The head circumference in utero grows by 0.5 cm in first 2 weeks, 0.75 cm in 3rd week and after that 1 cm/week till birth.","pyqMatches":[{"year":"2016","no":1419,"q":"Growth of head circumference in 1st 3 months of life is by","o":["2 cm","3 cm","5 cm","10 cm"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7082, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 287, '{"id":7082,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":287,"q":"Delayed eruption is failure of teeth to appear by","o":["6 months","13 months","25 months","37 months"],"a":1,"e":"Answer- B. 13 months Delayed eruption is usually considered when there are no teeth by approximately 13 months of age (mean + 3 SD). Common causes of delayed eruption of teeth include :- Idiopathic (Most common). Hypothyroid Hypoparathyroid Familial","pyqMatches":[{"year":"2016","no":1420,"q":"Delayed eruption is failure of teeth to appear by","o":["6 months","13 months","25 months","37 months"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7083, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 288, '{"id":7083,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":288,"q":"Breast milk protects from infections as it contains all of the following except:","o":["IgE","Lactoferrin","Bifidus factor","PABA"],"a":0,"e":"Answer- A. IgE Breast milk contains several antiinfective factors","pyqMatches":[{"year":"2016","no":1421,"q":"Breast milk protects from infections as it contains all of the following except:","o":["IgE","Lactoferrin","Bifidus factor","PABA"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7084, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 289, '{"id":7084,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":289,"q":"Which of the following is true regarding premature milk as compared to mature milk?","o":["Less lactose","Less iron","Less immunoglobulins","Less sodium"],"a":0,"e":"Answer- A. Less lactose Preterm milk The milk of mother who delivers prematurely differs from the milk of a mother who delivers at term. Preterm milk contains : Less lactose (in comparison to term milk). Contains more protein S, sodium, iron, immunoglobins and calories as they are needed by the preterm baby.","pyqMatches":[{"year":"2016","no":1422,"q":"Which of the following is true regarding premature milk as compared to mature milk?","o":["Less lactose","Less iron","Less immunoglobulins","Less sodium"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7085, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 290, '{"id":7085,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":290,"q":"All of the following are true regarding breast milk as compared to cow''s milk except","o":["Contains more lactose","More amount of proteins","Less amount of fat content","Minerals and salts is less"],"a":1,"e":"Answer- B. More amount of proteins In comparison to cow milk, human milk contains less amount of : Proteins (1 gm/ 100 ml), salts (sodium, chloride, potassium), fat (3.4 gm/100 ml), and minerals (calcium, phosphate) & more : Lactose (7g/100 ml or 7%).","pyqMatches":[{"year":"2016","no":1423,"q":"All of the following are true regarding breast milk as compared to cow''s milk except","o":["Contains more lactose","More amount of proteins","Less amount of fat content","Minerals and salts is less"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7086, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 291, '{"id":7086,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":291,"q":"Which of the following is the best reference for growth monitoring in children?","o":["ICMR","NCHS","Boston","IAP"],"a":1,"e":"Answer- B. NCHS WHO reference values (NCHS standards) These are most commonly used and best available reference values for international use. These values are based on the data assembled by United States National Centre for Health Statistics (NCHS). Classification of PEM is based on these standards","pyqMatches":[{"year":"2016","no":1424,"q":"Which of the following is the best reference for growth monitoring in children?","o":["ICMR","NCHS","Boston","IAP"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7087, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 292, '{"id":7087,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":292,"q":"Kwashiorkar is due to deficiency of","o":["Calories","Minerals","Vitamins","Zinc"],"a":0,"e":"Answer- A. Calories Marasmus and kwashiorkor are due to deficiency of proteins and calories. It is characterized by classical ''triad'' of edema (Due to hypoalbuminemia), markedly retarded growth and psychomotor (mental) changes.","pyqMatches":[{"year":"2016","no":1425,"q":"Kwashiorkar is due to deficiency of","o":["Calories","Minerals","Vitamins","Zinc"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7088, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 293, '{"id":7088,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":293,"q":"Features of marasmus are all except :","o":["Absence of anasarca","Increased appetite","Excessive catabolism of adipose tissue and muscle protein","Uncompensated phase of PEM"],"a":3,"e":"Answer- D. Uncompensated phase of PEM It is due to prolong deficiency of calories and proteins. Thus there is exessive catabolism of adipose tissue and muscle protein. It is characterized by gross wasting of muscle and subcutaneous tissues resulting in emaciation and marked stunting. Child may show voracious appetite. Marasmus represents the compensated phase of PEM.","pyqMatches":[{"year":"2016","no":1337,"q":"Features of marasmus are all except :","o":["Absence of anasarca","Increased appetite","Excessive catabolism of adipose tissue and muscle protein","Uncompensated phase of PEM"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7089, 'Pediatrics', 'Rheumatology', 'Moderate', 'Pediatrics (1)', 294, '{"id":7089,"subject":"Pediatrics","chapter":"Rheumatology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":294,"q":"All of the following are causes of pseudoparalysis except","o":["Osteomyelitis","Scurvy","Septic arthritis","Polio"],"a":3,"e":"Answer- D. Polio Causes of pseudoparalysis","pyqMatches":[{"year":"2016","no":1338,"q":"All of the following are causes of pseudoparalysis except","o":["Osteomyelitis","Scurvy","Septic arthritis","Polio"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7090, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 295, '{"id":7090,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":295,"q":"Which of the following can lead to regression of developmental milestones","o":["Rett''s syndrome","Autism","Neuromuscular diseases","All of the above"],"a":3,"e":"Answer- D. All of the above The hallmark of many degenerative disorders is neurological regression. Loss of only language skills – autism – suspected. Regression of both language and motor milestones → Rett''s syndrome.","pyqMatches":[{"year":"2016","no":1339,"q":"Which of the following can lead to regression of developmental milestones","o":["Rett''s syndrome","Autism","Neuromuscular diseases","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7091, 'Pediatrics', 'Growth & Development', 'Moderate', 'Pediatrics (1)', 296, '{"id":7091,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":296,"q":"All of the following are features of Rett''s syndrome except","o":["Microcephaly","Regression of milestones","Cardia arrhythmias","Focal Convulsions"],"a":3,"e":"Answer- D. Focal Convulsions This is the characteristic features, that they begin to loose their acquired skills, e.g., cognitive and head growth is normal during early period after which there is an arrest of growth. Acquired microcephaly (Decleration of head growth due to significantly reduced brain weight). Most children develop peculiar sighing respirations with intermittent periods of apnea that may be associated with cyanosis -4 Breath holding spells.","pyqMatches":[{"year":"2016","no":1340,"q":"All of the following are features of Rett''s syndrome except","o":["Microcephaly","Regression of milestones","Cardia arrhythmias","Focal Convulsions"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7092, 'Pediatrics', 'Neurology', 'Hard', 'Pediatrics (1)', 297, '{"id":7092,"subject":"Pediatrics","chapter":"Neurology","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":297,"q":"Child while playing has sudden loss of consciousness and appears pale. There is no significant medical history and the child was otherwise healthy. Which of the following is the most probable diagnosis?","o":["Attention deficit hyperkinetic disorder","Breath holding spell","Autism","Rett''s syndrome"],"a":1,"e":"Answer- B. Breath holding spell Pallid form (Pallid spells) These are initiated by painful experience, e.g falling and striking the head. Pallid spells are due to excessive central parasympethetic activity. Clinical features include pallor, apnea, loss of consciousness, hypotonia, seizures and bradycarda. Treatment includes support and reassurance of parents. Atropine may be used in refractory cases","pyqMatches":[{"year":"2016","no":1341,"q":"Child while playing has sudden loss of consciousness and appears pale. There is no significant medical history and the child was otherwise healthy. Which of the following is the most probable diagnosis?","o":["Attention deficit hyperkinetic disorder","Breath holding spell","Autism","Rett''s syndrome"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7093, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 298, '{"id":7093,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":298,"q":"Infantile body proportion in adults is seen in all except-","o":["Achondroplasia","Hypothyroidism","Klinefelter''s syndrome","Cretinism"],"a":2,"e":"Answer- C. Klinefelter''s syndrome Infantile type body porportion Achondroplasia Juvenile myxedema (hypothyroidism) Cretinism","pyqMatches":[{"year":"2016","no":1342,"q":"Infantile body proportion in adults is seen in all except","o":["Achondroplasia","Hypothyroidism","Klinefelter''s syndrome","Cretinism"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7094, 'Pediatrics', 'Growth & Development', 'Moderate', 'Pediatrics (1)', 299, '{"id":7094,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":299,"q":"If chronological age > skeletal age with normal growth velocity, then the final height that is expected to be achieved is","o":["Normal","Less because of small bones","More than expected","Less because of epiphyseal closure due to accelerated growth velocity"],"a":0,"e":"Answer- A. Normal If the growth velocity is normal but the chronological age is more than the bone age, then the diagnosis is Constitutional delay in growth. Constitutional delay in growth It is the most common cause of short stature in mid childhood period but the ultimate height is normal. Their birth weight and height are normal. Strong family history of parents having short stature in childhood with delay in onset of puberty is usually present.","pyqMatches":[{"year":"2016","no":1343,"q":"If chronological age > skeletal age with normal growth velocity, then the final height that is expected to be achieved is","o":["Normal","Less because of small bones","More than expected","Less because of epiphyseal closure due to accelerated growth velocity"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7095, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 300, '{"id":7095,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":300,"q":"Which of the following about hormone levels in a malnourished child is true?","o":["Increased insulin levels","Decreased cortisol levels","Increased growth hormone","All of the above"],"a":2,"e":"Answer- C. Increased growth hormone changes in PEM Decreased insulin levels Increased cortisol Increased growth hormone","pyqMatches":[{"year":"2016","no":1344,"q":"Which of the following about hormone levels in a malnourished child is true?","o":["Increased insulin levels","Decreased cortisol levels","Increased growth hormone","All of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7096, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 301, '{"id":7096,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":301,"q":"A 9 month old child with respiratory rate 53/min and presence of cough is classified as :","o":["SIRS","Respiratory distress","Tachypnoea","ARDS"],"a":2,"e":"Answer- C. Tachypnoea Tachypnea (fast breathing) : Fast breathing is defined as:","pyqMatches":[{"year":"2016","no":1345,"q":"A 9 month old child with respiratory rate 53/min and presence of cough is classified as :","o":["SIRS","Respiratory distress","Tachypnoea","ARDS"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7097, 'Pediatrics', 'Neonatology', 'Hard', 'Pediatrics (1)', 302, '{"id":7097,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":302,"q":"A newborn after prolonged labour is not breathing well and after 30 seconds of receiving 100% oxygen by bag and mask, heart rate is 88 beats per min, what is the next step in management?","o":["Discontinue oxygen and ventilation","Discontinue oxygen, continue ventilation","Continue oxygen and ventilation","Start chest compressions"],"a":2,"e":"Answer- C. Continue oxygen and ventilation After the infant has received 30 seconds of ventilation with 100% oxygen by bag and mask, evaluation of heart rate should be done - HR >100 → Discontinue ventilation if spontaneous respiration is present. HR 60 to 100 → Continue ventilation Below 60 → Continue ventilation + chest compressions After 30 seconds of chest compressions, the heart rate is checked. HR < 60 → Continue chest compression and bag & mask ventilation + initiate medications. HR > 60 → Discontinue chest compression but continue bag & mask ventilation until the heart rate is above 100. [Ref: O.P.Ghai 7th/e p. 98]","pyqMatches":[{"year":"2016","no":1346,"q":"A newborn after prolonged labour is not breathing well and after 30 seconds of receiving 100% oxygen by bag and mask, heart rate is 88 beats per min, what is the next step in management?","o":["Discontinue oxygen and ventilation","Discontinue oxygen, continue ventilation","Continue oxygen and ventilation","Start chest compressions"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7098, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 303, '{"id":7098,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":303,"q":"How are chest compressions given in a newborn?","o":["Using palm on the lower third of sternum","Using two fingers on the middle third of sternum","Using the two thumbs on the lower third of sternum","Using three fingers on the lower third of sternum"],"a":2,"e":"Answer- C. Using the two thumbs on the lower third of sternum Two - finger technique The tips of the middle finger and either the index finger or ring finger of one hand are used to compress the sternum. The other hand is used to support the infant''s back, unless the infant is on a very firm surface.","pyqMatches":[{"year":"2016","no":1347,"q":"How are chest compressions given in a newborn?","o":["Using palm on the lower third of sternum","Using two fingers on the middle third of sternum","Using the two thumbs on the lower third of sternum","Using three fingers on the lower third of sternum"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7099, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 304, '{"id":7099,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":304,"q":"Asymmetric tonic neck reflex disappears at what age?","o":["2 months","3 months","6 months","8 months"],"a":2,"e":"Answer- C. 6 months Assymmetic tonic neck- wks of gestation 4-6 → 6-7 months","pyqMatches":[{"year":"2016","no":1350,"q":"Asymmetric tonic neck reflex disappears at what age?","o":["2 months","3 months","6 months","8 months"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7100, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 305, '{"id":7100,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":305,"q":"True about tonic neck reflex is","o":["Extension of arm on ipsilateral side, flexion on contralateral side","Extension of arm on contralateral side, flexion on ipsilateral side","Extension of arms on both sides","Flexion of arms on both sides"],"a":0,"e":"Answer- A. Extension of arm on ipsilateral side, flexion on contralateral side The tonic neck reflex is produced by manually rotating the infant''s head to 1 side and observing for the characteristic fencing posture (extension of the arm on the side to which the face is rotated and flexion of the contralateral arm). An obligatory tonic neck response, in which the infant becomes \"stuck\" in the fencing posture, is always abnormal and implies a CNS disorder.","pyqMatches":[{"year":"2016","no":1351,"q":"True about tonic neck reflex is","o":["Extension of arm on ipsilateral side, flexion on contralateral side","Extension of arm on contralateral side, flexion on ipsilateral side","Extension of arms on both sides","Flexion of arms on both sides"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7101, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 306, '{"id":7101,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":306,"q":"Closure of patent ductus arteriosus is stimulated by?","o":["Prostaglandin F2a","Cycloxygenase","Increase in 02 tension at birth","Hypercarbia"],"a":2,"e":"Answer- C. Increase in 02 tension at birth The mechanism producing the initial constriction of ductus arteriosus is not completely understood, but the increase in arterial 02 tension plays an important role. One more factor which helps in closure of the ductus arteriosus is the decrease in concentration of prostaglandins at the time of birth.","pyqMatches":[],"pyqYears":[]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7102, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 307, '{"id":7102,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":307,"q":"False about PDA is","o":["More common in females","Anatomical closure takes 21 hours after birth","PGE maintains patency of ductus","Dilatation of ascending aorta"],"a":1,"e":"Answer- B. Anatomical closure takes 21 hours after birth Patent ductus arteriosus is a communication between the pulmonary artery and aorta. ''Functional closure'' takes place within 15 hours of birth. ''Anatomic closure'' of ductus arteriosus occurs 10-21 days after birth. Prostaglandins maintain the patency of ductus. The persistence of function of ductus arteriosus beyond 24 hours after birth is considered as PDA in term neonate, i.e. if functional closure does not take place in 24 hours after birth, it is considered as PDA.","pyqMatches":[{"year":"2016","no":1354,"q":"False about PDA is","o":["More common in females","Anatomical closure takes 21 hours after birth","PGE maintains patency of ductus","Dilatation of ascending aorta"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7103, 'Pediatrics', 'Cardiology', 'Moderate', 'Pediatrics (1)', 308, '{"id":7103,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":308,"q":"Which of the following is not seen in patent ductus arteriosus?","o":["Left atrial hypertrophy","Left ventricular enlargement","Continuous murmur","Attenuated SI"],"a":3,"e":"Answer- D. Attenuated SI Increased flow after passing through lung reaches the left atrium and causes volume overload → Left atrial dilatation and hypertrophy. Increased blood volume passes from left atrium to left ventricle through mitral valve, i.e., increased flow through mitral valve → Accentuation of S1 and delayed diastolic murmur. Left ventricle receives larger amount of blood that results in volume overload → Left ventricle enlargement.","pyqMatches":[{"year":"2016","no":1355,"q":"Which of the following is not seen in patent ductus arteriosus?","o":["Left atrial hypertrophy","Left ventricular enlargement","Continuous murmur","Attenuated SI"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7104, 'Pediatrics', 'Cardiology', 'Easy', 'Pediatrics (1)', 309, '{"id":7104,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":309,"q":"Which of the following congenital anomalies leads to heart failure at birth?","o":["Total anomalous pulmonary venous connection","Transposition of great arteries","Pulmonary atresia","Coarctation of aorta"],"a":2,"e":"Answer- C. Pulmonary atresia Timing of CHF in congenital heart diseases- Pulmonary, mitral and aortic atresias Hypoplastic left and right heart syndromes, transposition and malposition of great ate ries.","pyqMatches":[{"year":"2016","no":1356,"q":"Which of the following congenital anomalies leads to heart failure at birth?","o":["Total anomalous pulmonary venous connection","Transposition of great arteries","Pulmonary atresia","Coarctation of aorta"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7105, 'Pediatrics', 'Cardiology', 'Easy', 'Pediatrics (1)', 310, '{"id":7105,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":310,"q":"Most important prognostic marker of tetralogy of fallot","o":["VSD","Pulmonary stenosis","Overriding of aorta","Right ventricular hypertrophy"],"a":1,"e":"Answer- B. Pulmonary stenosis Tetrology of fallot has 4 components:","pyqMatches":[{"year":"2016","no":1358,"q":"Most important prognostic marker of tetralogy of fallot","o":["VSD","Pulmonary stenosis","Overriding of aorta","Right ventricular hypertrophy"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7106, 'Pediatrics', 'Infectious Diseases', 'Moderate', 'Pediatrics (1)', 311, '{"id":7106,"subject":"Pediatrics","chapter":"Infectious Diseases","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":311,"q":"Microcephaly is common in children of mothers with all except","o":["Alcohol intake","Warfarin intake","Warfarin intake","Varicella"],"a":1,"e":"Answer- B. Warfarin intake Secondary Structural defects : Neural tube defects (anencephaly, encephalocele). Metabolic disorders : Rhenylketonuria, citrullinemia, methylmalonic aciduria. Congenital infections : Rubella, CMV, HSV, toxoplasmosis, syphilis, varicella. Teratogens : Alcohol, tobacco, cocaine, heroin. Others : Maternal diabetes, maternal phenylketonuria, hypothyroidism, hypopituitrism, adrenal insufficiency.","pyqMatches":[{"year":"2016","no":1359,"q":"Microcephaly is common in children of mothers with all except","o":["Alcohol intake","Warfarin intake","Warfarin intake","Varicella"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7107, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 312, '{"id":7107,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":312,"q":"What is the capacity of stomach at birth","o":["5 ml","25 ml","50 ml","100 ml"],"a":2,"e":"Answer- C. 50 ml Day 1 5 - 7 ml. Size of cherry Day 3 22 - 27 ml. Size of walnut One week 45 - 60 ml. Size of an apricot One month 80 - 150 ml. Size of a large egg","pyqMatches":[{"year":"2016","no":1361,"q":"What is the capacity of stomach at birth","o":["5 ml","25 ml","50 ml","100 ml"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7108, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 313, '{"id":7108,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":313,"q":"Colour of stools in breastfed new born is -","o":["Red","Green","Black","Golden"],"a":3,"e":"Answer- D. Golden Colour of stools in neonate Meconium (first stool) is passed within 24 hours. After that meconium stools (black tarry) can be passed upto 3 days. On 4th-5th days transitional stools (greenish) are passed. After 5 days regular milk stools (golden yellow) are passed. There is golden discoloration of stool.","pyqMatches":[{"year":"2016","no":1362,"q":"Colour of stools in breastfed new born is","o":["Red","Green","Black","Golden"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7109, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 314, '{"id":7109,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":314,"q":"Trigonocephaly is due to premature closure of which suture?","o":["Sagittal suture","Metopic suture","Lambdoid suture","Coronal suture"],"a":1,"e":"Answer- B. Metopic suture Trigonocephal- Metopic suture Keel shaped forehead Hypotelorism Abnormalities of forebrain","pyqMatches":[{"year":"2016","no":1363,"q":"Trigonocephaly is due to premature closure of which suture?","o":["Sagittal suture","Metopic suture","Lambdoid suture","Coronal suture"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7110, 'Pediatrics', 'Nephrology', 'Moderate', 'Pediatrics (1)', 315, '{"id":7110,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":315,"q":"Which of the following is not a feature of Minimal change disease?","o":["Hypertension","Edema","Proteinuria","Responsive to steroid therapy"],"a":0,"e":"Answer- A. Hypertension Minimal Change Disease is the most common cause of Nephrotic syndrome in children. Edema and Selective proteinuria are features of nephrotic syndrome. Fever may be present on account of increased susceptibility to infection. Minimal change disease prsents with insidious onset of nephrotic syndrome in children below 6 years of age. Hypertension is not a feature of nephrotic syndrome and is rare in Minimal change disease. Hematuria (a finding of nephritic syndrome) is also rare.","pyqMatches":[{"year":"2016","no":1367,"q":"Which of the following is not a feature of Minimal change disease?","o":["Hypertension","Edema","Proteinuria","Responsive to steroid therapy"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7111, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 316, '{"id":7111,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":316,"q":"What is the rate of CSF formation in children?","o":["0.3 ml/min","1 ml/min","3 ml/min","20 ml/min"],"a":0,"e":"Answer- A. 0.3 ml/min The rate of CSF formation in children and adults is :- 0.3 to 0.4 ml/min OR 18 to 20 ml/hour","pyqMatches":[{"year":"2016","no":1370,"q":"What is the rate of CSF formation in children?","o":["0.3 ml/min","1 ml/min","3 ml/min","20 ml/min"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7112, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 317, '{"id":7112,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":317,"q":"Most common cause of cranial irradiation in children is","o":["Small cell lung Ca","ALL","AML","Craniopharyngioma"],"a":1,"e":"Answer- B. ALL ALL and small cell lung Ca are two major indications for cranial irradiation, even prophylactically to prevent brain metastasis. In children, ALL is the most common cause.","pyqMatches":[{"year":"2016","no":1371,"q":"Most common cause of cranial irradiation in children is","o":["Small cell lung Ca","ALL","AML","Craniopharyngioma"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7113, 'Pediatrics', 'Hematology', 'Moderate', 'Pediatrics (1)', 318, '{"id":7113,"subject":"Pediatrics","chapter":"Hematology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":318,"q":"Which of the following is not a feature of physiological anaemia of infancy?","o":["Term infant hemoglobin 7 gm%","Preterm infant hemoglobin 7 gm%","Term infant hemoglobin 9 gm%","Preterm infant hemoglobin 9 gm%"],"a":0,"e":"Answer- A. Term infant hemoglobin 7 gm% Physiologic Anemia of Infancy","pyqMatches":[{"year":"2016","no":1373,"q":"Which of the following is not a feature of physiological anaemia of infancy?","o":["Term infant hemoglobin 7 gm%","Preterm infant hemoglobin 7 gm%","Term infant hemoglobin 9 gm%","Preterm infant hemoglobin 9 gm%"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7114, 'Pediatrics', 'Hematology', 'Easy', 'Pediatrics (1)', 319, '{"id":7114,"subject":"Pediatrics","chapter":"Hematology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":319,"q":"Mean hemoglobin in a 1 year old child is","o":["18.5 g/dl","16.5 g/d1","14 g/c11","12 g/dl"],"a":3,"e":"Answer- D. 12 g/dl Hb level (g/L) Prevalence (%) Age (mo) N MeamSE Mild anemia (Hb<110 g/L) Moderate to Severe anemia (Hb<80 g/L) 0-5 6-11 12-23 24-60 Totel 56 88 128 251 523 9.8 10.08 10.04 10.18 10.09 0.21 0.17 0.21 0.13 0.09 78.1 75.3 63.3 68.3 69.3 5.2 5.8 11.9 8.1 8.3 Hb, hemoglobin a. Means and frequencies are weighted.","pyqMatches":[{"year":"2016","no":1374,"q":"Mean hemoglobin in a 1 year old child is","o":["18.5 g/dl","16.5 g/d1","14 g/c11","12 g/dl"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7115, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 320, '{"id":7115,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":320,"q":"Amino acid metabolism is implicated in which disease?","o":["Maple syrup urine disease","Reye''s syndrome","Von Gierke''s disease","McArdle''s disease"],"a":0,"e":"Answer- A. Maple syrup urine disease It is due to deficiency of enzyme that catalyzes the second reaction in these amino acids metabolism i.e. branched chain-a keto acid dehydrogenase which catalyses decarboxylation of branched chain amino acids.","pyqMatches":[{"year":"2016","no":1377,"q":"Amino acid metabolism is implicated in which disease?","o":["Maple syrup urine disease","Reye''s syndrome","Von Gierke''s disease","McArdle''s disease"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7116, 'Pediatrics', 'Gastroenterology', 'Hard', 'Pediatrics (1)', 321, '{"id":7116,"subject":"Pediatrics","chapter":"Gastroenterology","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":321,"q":"A 3 months old child was started on supplemental foods alongwith breastmilk. The child was fed with fruit pulp and sweetened cereals. Soon the child developed bloating of abdomen, vomiting, lethargy, irritability. On investigation, there was hyperbilirunemia and elevated transaminase levels. The child is suffering from which of the following enzyme deficiencies?","o":["Fructokinase","Aldolase B","Gal actokinase","Galactose - 1 - phosphate uridyl transferase"],"a":1,"e":"Answer- B. Aldolase B Symptoms occur when foods or formulas containing these sugars are introduced into the diet. Clinical manifestations resemble galactosemia and include jaundice, hepatomegaly, vomiting, lethargy, irritability, and convulsions. Laboratory findings include a prolonged clotting time, hypo- albuminemia, elevation of bilirubin and transaminase levels, and proximal tubular dysfunction.","pyqMatches":[{"year":"2016","no":1378,"q":"A 3 months old child was started on supplemental foods alongwith breastmilk. The child was fed with fruit pulp and sweetened cereals. Soon the child developed bloating of abdomen, vomiting, lethargy, irritability. On investigation, there was hyperbilirunemia and elevated transaminase levels. The child is suffering from which of the following enzyme deficiencies?","o":["Fructokinase","Aldolase B","Gal actokinase","Galactose - 1 - phosphate uridyl transferase"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7117, 'Pediatrics', 'Neonatology', 'Moderate', 'Pediatrics (1)', 322, '{"id":7117,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":322,"q":"All are true about sacrococcygeal teratoma except","o":["Not associated with increased serum markers","In most cases is not visible externally","If associated with hydrops, should be resected antenatally","Most common tumor of fetus"],"a":1,"e":"Answer- B. In most cases is not visible externally Ureters may be partially obstructed resulting in hydro-ureter and hydronephrosis. Sacrococcygeal Teratoma (SCT) is the most common neoplasm in the fetus and newborn Most common tumor in fetus and neonate sacrococcygeal teratoma Most common tumor in infancy neuroblastoma. They are not associated with elevated markers unless malignancy is present. Sacrococcygeal teratoma with hydrops :- Treatment - Inutero resection or catheter directed vessel obliteration","pyqMatches":[{"year":"2016","no":1380,"q":"All are true about sacrococcygeal teratoma except","o":["Not associated with increased serum markers","In most cases is not visible externally","If associated with hydrops, should be resected antenatally","Most common tumor of fetus"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7118, 'Pediatrics', 'Infectious Diseases', 'Easy', 'Pediatrics (1)', 323, '{"id":7118,"subject":"Pediatrics","chapter":"Infectious Diseases","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":323,"q":"Most common sign of LRTI [Lower respiratory tract infection] in children is","o":["Chest indrawing","Tachypnea","Nasal flaring","Failure to feed well"],"a":1,"e":"Answer- B. Tachypnea Tachypnea is the most consistent manifestation of pneumonia. Pneumonia is an inflammation of the parenchyma of lungs, and mostly caused by bacterial or viral infection. Most common cause of paediatric pneumonia is respiratory syncytial virus (RSV). Other viruses causing pneumonia are influenza virus (2\"° most common virus), adenovirus, rhinovirus, and parainfluenza virus.","pyqMatches":[{"year":"2016","no":1381,"q":"Most common sign of LRTI [Lower respiratory tract infection] in children is","o":["Chest indrawing","Tachypnea","Nasal flaring","Failure to feed well"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7119, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 324, '{"id":7119,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":324,"q":"Which of the following is not a sign of severe dehydration?","o":["Tachycardia","Anuria","Increased thirst","Delayed capillary refill [>3 sec]"],"a":2,"e":"Answer- C. Increased thirst Peripheral pulses either rapid and weak or absent Decreased blood pressure No urine output Very sunken eyes and fontanel No tears Parched mucous membrane Delayed elasticity (poor skin turgor) Very delayed capillary refill (> 3 sec) Cold and mottled Limp Depressed consciousness","pyqMatches":[{"year":"2016","no":1383,"q":"Which of the following is not a sign of severe dehydration?","o":["Tachycardia","Anuria","Increased thirst","Delayed capillary refill [>3 sec]"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7120, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 325, '{"id":7120,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":325,"q":"What is the grade of dehydration if a child demonstrates excessive thirst and decreased urine output?","o":["No dehydration","Mild dehydration","Moderate dehydration","Severe dehydration"],"a":1,"e":"Answer- B. Mild dehydration Normal or increased pulse Decreased urine output Thirsty Normal physical findings","pyqMatches":[{"year":"2016","no":1384,"q":"What is the grade of dehydration if a child demonstrates excessive thirst and decreased urine output?","o":["No dehydration","Mild dehydration","Moderate dehydration","Severe dehydration"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7121, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 326, '{"id":7121,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":326,"q":"Which of the following cannot be used to detect HIV status in early infancy?","o":["DNA - PCR","HIV culture","ELISA","P - 24 antigen assay"],"a":2,"e":"Answer- C. ELISA ELISA or Western blot test are not as reliable in young infants. In older infants (> 6 months), detection of anti-HIV IgA antibodies by ELISA is diagnostic. In children (> 18 months) demonstration of anti-HIV IgG antibodies by ELISA is used.","pyqMatches":[{"year":"2016","no":1386,"q":"Which of the following cannot be used to detect HIV status in early infancy?","o":["DNA - PCR","HIV culture","ELISA","P - 24 antigen assay"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7122, 'Pediatrics', 'Cardiology', 'Easy', 'Pediatrics (1)', 327, '{"id":7122,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":327,"q":"Teratology is a study of","o":["Congenital heart defect","Congenital abnormalities","Wounds and injuries","None of the above"],"a":1,"e":"Answer- B. Congenital abnormalities Study of Congenital heart defects is a part of the broad spectrum of congenital abnormalities, the study of which is known as Teratology","pyqMatches":[{"year":"2016","no":1387,"q":"Teratology is a study of","o":["Congenital heart defect","Congenital abnormalities","Wounds and injuries","None of the above"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7123, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 328, '{"id":7123,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":328,"q":"Russell silver syndrome is associated with which of the following?","o":["Autosomal inheritance","X - linked inheritance","Sporadic gene mutation","Uniparental disomy"],"a":3,"e":"Answer- D. Uniparental disomy Angelman syndrome Prader Willi syndrome Pseudohypoparathyroidism Ib Transient neonatal diabetes mellitus Beckwith - Wiedemann syndrome Russell silver syndrome Wang syndrome Temple syndrome","pyqMatches":[{"year":"2016","no":1388,"q":"Russell silver syndrome is associated with which of the following?","o":["Autosomal inheritance","X - linked inheritance","Sporadic gene mutation","Uniparental disomy"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7124, 'Pediatrics', 'Hematology', 'Moderate', 'Pediatrics (1)', 329, '{"id":7124,"subject":"Pediatrics","chapter":"Hematology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":329,"q":"Which of the following is not a feature of Down''s syndrome?","o":["Hypotonia","Infections","Female infertility","Early onset Alzheimer''s disease"],"a":2,"e":"Answer- C. Female infertility GIT :- Anal atresia, Duodenal atresia, Hirschsprung disease, annular pancreas. Increased incidence of leukemia (1%). Leukemias common are ALL (most common), AML (M7-AML) transient myeloproliferative disorders, and Juvenil CML. Others : Early onset of Alzheimer''s disease, Decreased immunity with recurrent infections, obesity, DM, Hypothyroidism (most common endocrine abnormality).","pyqMatches":[{"year":"2016","no":1389,"q":"Which of the following is not a feature of Down''s syndrome?","o":["Hypotonia","Infections","Female infertility","Early onset Alzheimer''s disease"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7125, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 330, '{"id":7125,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":330,"q":"Which of the following is not a feature of Turner''s syndrome?","o":["Cubitus valgus","Cryptorchidism","Short fourth metacarpal","Shield chest"],"a":1,"e":"Answer- B. Cryptorchidism Clinical features in adolescents are short stature, webbed neck, low posterior hair line, widely spaced nipples with broad chest (shield chest), hypertelorism, epicanthus, slanted palpebral fissure, ptosis, micrognathia, cubitus valgus (increared carrying angle), sensorineural hearing loss, short fourth metacarpal, hypothyroidism, streak ovaries, and sexual infantilism. Turner syndrome is the most important cause of primary amenorrhea.","pyqMatches":[{"year":"2016","no":1390,"q":"Which of the following is not a feature of Turner''s syndrome?","o":["Cubitus valgus","Cryptorchidism","Short fourth metacarpal","Shield chest"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7126, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 331, '{"id":7126,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":331,"q":"Which of the following is true regarding Turner''s syndrome?","o":["Cubitus valgus","Autosomal dominant","Monosomy of chromosome 12","Sensorineural hearing loss"],"a":0,"e":"Answer- A. Cubitus valgus Turner syndrome is a monosomy of sex chromosome (not autosomal dominant). Cubitus valgus is a feature of Turner syndrome. SNHL is not a feature.","pyqMatches":[{"year":"2016","no":1392,"q":"Which of the following is true regarding Turner''s syndrome?","o":["Cubitus valgus","Autosomal dominant","Monosomy of chromosome 12","Sensorineural hearing loss"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7127, 'Pediatrics', 'Nephrology', 'Easy', 'Pediatrics (1)', 332, '{"id":7127,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":332,"q":"Most common cause of shock in child","o":["Septic shock","Hypovolemic shock","Cardiogenic shock","Anaphylactic shock"],"a":1,"e":"Answer- B. Hypovolemic shock Hypovolemia is the most common cause of shock in children. The 2nd most common cause - Septic or distributive shock . 3rd most common - Cardiogenic shock","pyqMatches":[{"year":"2016","no":1394,"q":"Most common cause of shock in child","o":["Septic shock","Hypovolemic shock","Cardiogenic shock","Anaphylactic shock"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7128, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 333, '{"id":7128,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":333,"q":"Which is the prognostic scoring system for head injury in children?","o":["CCS","AUDIT","Injury severity score","Pediatric Trauma Score"],"a":0,"e":"Answer- A. CCS Table 1: Children Coma Score (CC S) < 2 years\" Ocular Response 4 Pursuit 3 Extra ocular muscles intact reactive pupils 2 Fixed pupils and EOM impaired 1 Fixed pupils and EOM paralyzed Verbal response 3 Cries 2 Spontaneous respiration 1 Apneic Motor responses 4 Flexes and extends 3 Withdraws from painful stimuli 2 Hypertonic 1 Flaccid Total Max. Score 11 Total Min Score","pyqMatches":[{"year":"2016","no":1395,"q":"Which is the prognostic scoring system for head injury in children?","o":["CCS","AUDIT","Injury severity score","Pediatric Trauma Score"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7129, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 334, '{"id":7129,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":334,"q":"Which of the following is a criteria for clinical Stage II of AIDS in children?","o":["Lymphadenopathy","Oral candidiasis","Hepatosplenomegaly","Oesophageal candidiasis"],"a":2,"e":"Answer- C. Hepatosplenomegaly Clinical Stage 2 Hepatosplenomegaly Papular pruritic eruptions Seborrhoeic dermatitis Extensive human papilloma virus infection Extensive molluscum contagiosum Fungal nail infections Recurrent oral ulcerations Lineal gingival erythema (LGE) Angular cheilitis Parotid enlargement Herpes zoster","pyqMatches":[{"year":"2016","no":1396,"q":"Which of the following is a criteria for clinical Stage II of AIDS in children?","o":["Lymphadenopathy","Oral candidiasis","Hepatosplenomegaly","Oesophageal candidiasis"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7130, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 335, '{"id":7130,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":335,"q":"Which of the following is closed at birth?","o":["Foramen ovale","Posterior fontanelle","Ductus venosus","Anterior fontanelle"],"a":1,"e":"Answer- B. Posterior fontanelle Posterior fontanelle Posterior fontanelle generally closes by 2-4 months after birth. Posterior fontanelle usually closes by the age of 1-4 months. But sometime it may be ossified (closes) at birth. Thus, it is the best answer among the given choices.","pyqMatches":[{"year":"2016","no":1397,"q":"Which of the following is closed at birth?","o":["Foramen ovale","Posterior fontanelle","Ductus venosus","Anterior fontanelle"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7131, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 336, '{"id":7131,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":336,"q":"Harlequin skin change is seen due to mutation of which gene?","o":["ABCA 12","FAD","Keratin 1","ALOXE 3"],"a":0,"e":"Answer- A. ABCA 12 Harlequin ichthyosis (HI) is caused by mutations in the ABCAl2 gene. Mutation in the gene leads to defective lipid transport and ABCAl2 activity is required for the generation of long-chain ceramides that are essential for the development of the normal skin barrier. It is inherited by autosomal recessive mode of inheritance.","pyqMatches":[{"year":"2016","no":1398,"q":"Harlequin skin change is seen due to mutation of which gene?","o":["ABCA 12","FAD","Keratin 1","ALOXE 3"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7132, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 337, '{"id":7132,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":337,"q":"Ritter disease is a disease caused by -","o":["Infection","Autoimmune","Genetic","Metabolic disorder"],"a":0,"e":"Answer- A. Infection Staphylococcal scalded skin syndrome is caused predominantly by phage group 2 staphylococci, particularly strains 71 and 55, which are present at localized sites of infection.","pyqMatches":[{"year":"2016","no":1399,"q":"Ritter disease is a disease caused by","o":["Infection","Autoimmune","Genetic","Metabolic disorder"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7133, 'Pediatrics', 'Nutrition', 'Easy', 'Pediatrics (1)', 338, '{"id":7133,"subject":"Pediatrics","chapter":"Nutrition","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":338,"q":"Pink color in the IMNCI chart is suggestive of","o":["Normal zone of weight for age","Undernutrition (Upto - 2SD)","Severely underweight zone (Upto - 3SD)","Very severely undernourished (Upto - 5SD)"],"a":2,"e":"Answer- C. Severely underweight zone (Upto - 3SD) Green - Normal zone of weight for age Yellow - Undernutrition (upto - 2SD) Pink - Severely underweight zone (upto - 3 SD)","pyqMatches":[{"year":"2016","no":1400,"q":"Pink color in the IMNCI chart is suggestive of","o":["Normal zone of weight for age","Undernutrition (Upto - 2SD)","Severely underweight zone (Upto - 3SD)","Very severely undernourished (Upto - 5SD)"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7134, 'Pediatrics', 'Growth & Development', 'Easy', 'Pediatrics (1)', 339, '{"id":7134,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":339,"q":"5DHT is necessary for development of which of the following?","o":["External genitalia","Internal genitalia","Mullerian structures","Wollfian structures"],"a":0,"e":"Answer- A. External genitalia Virilization of the wolffian duct is caused by the action of testosterone itself. Masculinization of the urogenital sinus and external genitals depends on the action of DHT (Dehydrotestosterone) during the critical period of fetal masculinization.","pyqMatches":[{"year":"2016","no":1401,"q":"5DHT is necessary for development of which of the following?","o":["External genitalia","Internal genitalia","Mullerian structures","Wollfian structures"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7135, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 340, '{"id":7135,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":340,"q":"Prevalence of omphalocele at birth is","o":["1 in 100 live births","1 in 2000 live births","1 in 4000 live births","1 in 10,000 live births"],"a":2,"e":"Answer- C. 1 in 4000 live births Incidence of omphalocele at 11 - 14 weeks gestation - 1 in 1100 pregnancies. Prevalence at birth - 1 in 4000 - 6000 live births. This indicates sudden mortality most likely due to in utero fetal demise from associated chromosomal anomalies as well as elective termination after the diagnosis","pyqMatches":[{"year":"2016","no":1404,"q":"Prevalence of omphalocele at birth is","o":["1 in 100 live births","1 in 2000 live births","1 in 4000 live births","1 in 10,000 live births"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7136, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 341, '{"id":7136,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":341,"q":"Pectus excavatum is","o":["Protrusion of sternum","Sternal depression","Sternal cleft","Lateral displacement of sternum"],"a":1,"e":"Answer- B. Sternal depression Pectus excavatum (funnel chest) is midline narrowing of thoracic cavity due to sternal depression. May occur in isolation or may be associated with a connective tissue disorder, Marfan or Ehlers-Danlos syndrome. Secondary to chronic lung disease, neuromuscular disease, or trauma.","pyqMatches":[{"year":"2016","no":1405,"q":"Pectus excavatum is","o":["Protrusion of sternum","Sternal depression","Sternal cleft","Lateral displacement of sternum"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7137, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 342, '{"id":7137,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":342,"q":"A child aged 7 years has how many teeth","o":["15","20","26","32"],"a":2,"e":"Answer- C. 26 Permanent teeth that appear : 1st molars :- 4 Central incisors :- 2 Temporary teeth :- 20 (since molars are superadded permanent teeth and central incisors are replaced). So in all 26 teeth ( Range 24 to 26) - at 7 years of age.","pyqMatches":[{"year":"2016","no":1406,"q":"A child aged 7 years has how many teeth","o":["15","20","26","32"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7138, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 343, '{"id":7138,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":343,"q":"Child starts monosyllables speech in which age","o":["4 months","6 months","8 months","10 months"],"a":1,"e":"Answer- B. 6 months 3 months- Starts cooing 6 months- Produces monosyllable sounds like da, ma 9 months- Produces bisyllable sound like baba, mania","pyqMatches":[{"year":"2012","no":1180,"q":"Child starts monosyllables speech in which age","o":["4 months","6 months","8 months","10 months"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7139, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 344, '{"id":7139,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":344,"q":"Nocturnal enuresis best t/t is","o":["Positive reinforcement","Punishment","Bed alarm","Desmopressin"],"a":0,"e":"Answer- A. Positive reinforcement Consistent dry bed training with positive reinforcement has a success rate of 85% and bed and pad alarm systems have a success rate of approximately 75% with relapse rate that are lower than those with pharmacotherapy.","pyqMatches":[{"year":"2012","no":1185,"q":"Nocturnal enuresis best t/t is","o":["Positive reinforcement","Punishment","Bed alarm","Desmopressin"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7140, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 345, '{"id":7140,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":345,"q":"Neonatal lupus -","o":["Heart block","Thrombocytopenia","Cutaneous lesion","All of above"],"a":3,"e":"Answer- D. All of above Neonatal lupus Age of onset newborn to 6 month Skin lesion include : Annular erythematous scaly plaque. Seen on sun exposed = head, neck May be associated with heart block/thrombocytopenia Diagnosed by: ANA Anti RO antibodies","pyqMatches":[{"year":"2012","no":1172,"q":"Neonatal lupus","o":["Heart block","Thrombocytopenia","Cutaneous lesion","All of above"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7141, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 346, '{"id":7141,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":346,"q":"In Precocious puberty age limit of girls is-","o":["8 year","10 year","9 year","11 year"],"a":0,"e":"Answer- A.�8 year Precocious puberty�in a girl is the appearance of any of the secondary sexual characteristics before the age of 8 years or the occurrence of menarche before the age of 10 years. Precocious puberty�in boys is the onset of secondary sexual characteristics before the age of nine years.�","pyqMatches":[{"year":"2012","no":1187,"q":"In Precocious puberty age limit of girls is","o":["8 year","10 year","9 year","11 year"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7142, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 347, '{"id":7142,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":347,"q":"Malnourished child minimum weight gain","o":["5 gm/kg/day","10 gm/kg/day","15 gm/kg/day","20 gm/kg/day"],"a":0,"e":"Answer- A. 5 gm/kg/day In malnourish child if there > 10 gm/kg/day = good weight gain 5-10 gm/kg/day = moderate weight gain < 5 gm/kg/day = poor weight gain","pyqMatches":[{"year":"2012","no":1190,"q":"Malnourished child minimum weight gain","o":["5 gm/kg/day","10 gm/kg/day","15 gm/kg/day","20 gm/kg/day"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7143, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 348, '{"id":7143,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":348,"q":"CPR with 2 candidate is done at rate of (in infant) -","o":["15 : 2","30 : 2","1 : 3","1 : 5"],"a":0,"e":"Answer- A. 15 : 2 In infant children with two resuscitator = 15 : 2 In adult with two resuscitator - 30 : 2 In single resuscitator chest compresion ventilation ratio in all age group i.e. Infant, children & adult = 30 :","pyqMatches":[{"year":"2012","no":1171,"q":"CPR with 2 candidate is done at rate of (in infant)","o":["15 : 2","30 : 2","1 : 3","1 : 5"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7144, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 349, '{"id":7144,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":349,"q":"Preterm baby have","o":["Continue extramedullary hematopoesis","Greater risk of hypothermia","Greater risk of hypoglycemia","All of above"],"a":3,"e":"Answer- D. All of above Preterm baby (< 37 week of gestation). Have high risk for RDS (HMD) Broncho pulmonary dysplasia (BPD) PDA Anemia (early & late) IVH Sepsis NEC Jaundice Hypoglycemia, hypokalemia, hypothermia IVH ROP (Retinopathy of prematurity).","pyqMatches":[{"year":"2012","no":1191,"q":"Preterm baby have","o":["Continue extramedullary hematopoesis","Greater risk of hypothermia","Greater risk of hypoglycemia","All of above"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7145, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 350, '{"id":7145,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":350,"q":"Pica refers to -","o":["Ice sucking","Thumb sucking","Foreign object being put in the mouth","None of above"],"a":2,"e":"Answer- C. Foreign object being put in the mouth Pica involves repeated or chronic ingestion of non-nutritive substances, which include plaster, charcoal, clay, wool, ashes, paint & earth.","pyqMatches":[{"year":"2012","no":1169,"q":"Pica refers to","o":["Ice sucking","Thumb sucking","Foreign object being put in the mouth","None of above"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7146, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 351, '{"id":7146,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":351,"q":"Low glucose level in premature","o":["Increased brain to body ratio","Decreased glycogen stores","Decreased action of pyruvate carboxylase","All of above"],"a":3,"e":"Answer- D. All of above Hypoglycemia is common in pretem & IUGR babies b/c all three reason","pyqMatches":[{"year":"2012","no":1192,"q":"Low glucose level in premature","o":["Increased brain to body ratio","Decreased glycogen stores","Decreased action of pyruvate carboxylase","All of above"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7147, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 352, '{"id":7147,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":352,"q":"Temperature of NICU is","o":["20-22° C","22-26° C","26-30° C","30-35°C"],"a":1,"e":"Answer- B. 22-26° C Standards for NICU thermal invornment Specify 72-76° F (22-26° C) as acceptable range for air temperature.","pyqMatches":[{"year":"2012","no":1193,"q":"Temperature of NICU is","o":["20-22° C","22-26° C","26-30° C","30-35°C"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7148, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 353, '{"id":7148,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":353,"q":"GBS in a child treatment -","o":["IV Ig","Ventilation","Plasmapharesis","All of above"],"a":3,"e":"Answer- D. All of above Treatment of Guillain-barre syndrome - Self limited in majority of cases. Intravenous immunoglobin shows good response. Plasma pharesis - Removal of autoantibodies. Assisted ventilation - If patient had respiratory muscle paralysis. Physiotherapy.","pyqMatches":[{"year":"2012","no":1167,"q":"GBS in a child treatment","o":["IV Ig","Ventilation","Plasmapharesis","All of above"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7149, 'Pediatrics', 'Hematology', 'Easy', 'Pediatrics (1)', 354, '{"id":7149,"subject":"Pediatrics","chapter":"Hematology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":354,"q":"Anemia of prematurity - True is","o":["Marginal reticulocytosis","<10 gm criteria (Hb level)","10 ml/kg packed cell","Microcytic hypo chromic type"],"a":1,"e":"Answer- B. <10 gm criteria (Hb level) Normocytic, normochromic, hyporegenerative anemia with EPO level. AOP usually resolve spontaneously within 3-6 months. Aetiology","pyqMatches":[{"year":"2012","no":1194,"q":"Anemia of prematurity - True is","o":["Marginal reticulocytosis","<10 gm criteria (Hb level)","10 ml/kg packed cell","Microcytic hypo chromic type"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7150, 'Pediatrics', 'Growth & Development', 'Moderate', 'Pediatrics (1)', 355, '{"id":7150,"subject":"Pediatrics","chapter":"Growth & Development","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":355,"q":"LEOPARD syndrome includes all except -","o":["Growth retardation","ECG changes","Hypertelorism","Hypergonadism"],"a":3,"e":"Answer- D. Hypergonadism LEOPARD syndrome Lentigines Electrocardiographic conduction abnormalities Ocular hypertelorism Pulmonary stenosis Abnormal genitalia Retarded growth Deafness","pyqMatches":[{"year":"2012","no":1166,"q":"LEOPARD syndrome includes all except","o":["Growth retardation","ECG changes","Hypertelorism","Hypergonadism"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7151, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 356, '{"id":7151,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":356,"q":"Blood transfusion to neonate rate of","o":["1-5 ml/min-5 ml/min.","5-10 ml/min","10-15 ml/min","15-20 ml/min"],"a":1,"e":"Answer- B. 5-10 ml/min A) Exchange transfusion For term infant = 80-160 ml/kg For pre term = 100-200 ml/kg B) Top-up transfusion Desired Hb (glds) - actual hb x kg x 3 (usually 10-20 ml/kg). Rate of transfusion 5-10 ml/min.","pyqMatches":[{"year":"2012","no":1197,"q":"Blood transfusion to neonate rate of","o":["1-5 ml/min-5 ml/min.","5-10 ml/min","10-15 ml/min","15-20 ml/min"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7152, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 357, '{"id":7152,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":357,"q":"TB in children, most common is -","o":["Abscess","Consolidation","Hilar adenopathy","CNS tuberculosis"],"a":2,"e":"Answer- C. Hilar adenopathy \"Most common form of primary TB in children is pulmonary TB. This could be in the form of hilar lymphadenopathy with or without lung parenchymal involvement\".","pyqMatches":[{"year":"2012","no":1165,"q":"TB in children, most common is","o":["Abscess","Consolidation","Hilar adenopathy","CNS tuberculosis"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7153, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 358, '{"id":7153,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":358,"q":"In children, CHF (congestion heart failure) is diagnosed by","o":["Raised JVP","Pedal edema","Tender hepatomegaly","Basal crepts"],"a":2,"e":"Answer- C. Tender hepatomegaly Heart failure in infants & children results some degree of hepatemegaly which is usually tender & sometimes splenomegaly. Peripheral edema is age dependent : In infants, edema usually eye & over flank. Older childern & adolescent shows both periorbital edema & pedal edema and occurs late.","pyqMatches":[{"year":"2012","no":1199,"q":"In children, CHF (congestion heart failure) is diagnosed by","o":["Raised JVP","Pedal edema","Tender hepatomegaly","Basal crepts"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7154, 'Pediatrics', 'Cardiology', 'Easy', 'Pediatrics (1)', 359, '{"id":7154,"subject":"Pediatrics","chapter":"Cardiology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":359,"q":"Double arch aorta is seen in","o":["CATCH 22","Digeorge syndrome","Sphrintzen velo cardio facial syndrome","None of above"],"a":0,"e":"Answer- A. CATCH 22 CATCH 22 stands for Cardiac defect - double arch aorta. VSD, pulmonary atresia. Cleft palate Abnormal facies Hypocalcemia Thymic hypoplasia","pyqMatches":[{"year":"2012","no":1204,"q":"Double arch aorta is seen in","o":["CATCH 22","Digeorge syndrome","Sphrintzen velo cardio facial syndrome","None of above"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7155, 'Pediatrics', 'Miscellaneous', 'Moderate', 'Pediatrics (1)', 360, '{"id":7155,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":360,"q":"Simian crease is not seen in -","o":["Down","Trisomy 13","Atopic dermatitis","Noonan syndrome"],"a":2,"e":"Answer- C. Atopic dermatitis Simian crease Single transverse palmer crease Resembles non-human-simian so known as simian crease. It is seen in :","pyqMatches":[{"year":"2012","no":1163,"q":"Simian crease is not seen in","o":["Down","Trisomy 13","Atopic dermatitis","Noonan syndrome"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7156, 'Pediatrics', 'Neurology', 'Easy', 'Pediatrics (1)', 361, '{"id":7156,"subject":"Pediatrics","chapter":"Neurology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":361,"q":"Treatment of simple febrile convulsion is based on","o":["Control of fever","Rectal diazepam","CSF finding","Blood reports"],"a":0,"e":"Answer- A. Control of fever Prompt reduction of temperature by hydrotherapy (sponging) and antipyretics (paracetamole, ibuprofen) is the most important measure. If seizures lasts for more than 5 minutes, diazepam (rectal or IV) is the anticonvulsant of choice. Phenobarbitone is an alternative","pyqMatches":[{"year":"2012","no":1206,"q":"Treatment of simple febrile convulsion is based on","o":["Control of fever","Rectal diazepam","CSF finding","Blood reports"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7157, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 362, '{"id":7157,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":362,"q":"Rehydration therapy in a 2 year old severely dehydrated child is -","o":["30 ml/kg in 1 hour, 70 ml in 5 hours","30 ml/kg in 30 min, 70 ml/kg in 2''/2 hours","20 ml/kg in 30 min, 80 ml/kg in 2''/2","75 ml/kg in 4 hours"],"a":1,"e":"Answer- B. 30 ml/kg in 30 min, 70 ml/kg in 2''/2 hours 12 Month - 5 year 30 ml/Kg in 30 min 70 ml/Kg in 2.30 hour","pyqMatches":[{"year":"2012","no":1159,"q":"Rehydration therapy in a 2 year old severely dehydrated child is","o":["30 ml/kg in 1 hour, 70 ml in 5 hours","30 ml/kg in 30 min, 70 ml/kg in 2''/2 hours","20 ml/kg in 30 min, 80 ml/kg in 2''/2","75 ml/kg in 4 hours"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7158, 'Pediatrics', 'Neurology', 'Easy', 'Pediatrics (1)', 363, '{"id":7158,"subject":"Pediatrics","chapter":"Neurology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":363,"q":"What is correct about febrile seizures","o":["Normal EEG","Focal deficits","Repeated seizure","Abnormal EEG"],"a":0,"e":"Answer- A. Normal EEG Spontaneous remmission occurs with no postictal neurological deficit and EEG changes few days after the seizure is normal. Recurrent febrile seizures occur in 30-50% of cases. More than 90% of febrile seizures are generalized. Acute respiratory illness are most commonly associated with febrile seizures.","pyqMatches":[{"year":"2012","no":1207,"q":"What is correct about febrile seizures","o":["Normal EEG","Focal deficits","Repeated seizure","Abnormal EEG"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7159, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 364, '{"id":7159,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":364,"q":"Cause of neonatal hyperbilirubinemia ?","o":["Inefficient erythropoiesis","RBC hemolysis","Immature liver enzyme","All of above"],"a":3,"e":"Answer- D. All of above Impaired bile flow → Obstructive jaundice, primary biliary cirrhosis, Neonatal cholestasis, e.g. Extrahepatic biliary atresia/neonate idiopathic hepatitis, Choledocal cyst, Sclerosing cholangitis, Caroli disease, Metabolic (Tyrosinemia, Wolman disease, Nieman pick disease, Galactosemia, Fructosemia).","pyqMatches":[{"year":"2012","no":1211,"q":"Cause of neonatal hyperbilirubinemia ?","o":["Inefficient erythropoiesis","RBC hemolysis","Immature liver enzyme","All of above"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7160, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 365, '{"id":7160,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":365,"q":"Dosage of intravenous fluid for 2 month old child in diarrhoea with severe dehydration -","o":["100 ml/Kg in 6 hour","50 ml/Kg in 6 hour","75 ml/Kg in 6 hour","80 ml/Kg in 6 hour"],"a":0,"e":"Answer- A. 100 ml/Kg in 6 hour So total fluid to be given 100 ml/Kg in 6 hour.","pyqMatches":[{"year":"2012","no":1158,"q":"Dosage of intravenous fluid for 2 month old child in diarrhoea with severe dehydration","o":["100 ml/Kg in 6 hour","50 ml/Kg in 6 hour","75 ml/Kg in 6 hour","80 ml/Kg in 6 hour"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7161, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 366, '{"id":7161,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":366,"q":"In Diapragmatic Hernia. Most common anomaly is seen in","o":["Cardiovascular anomalies","Urinary tract","Craniofacial anomaly","Skull anomaly"],"a":0,"e":"Answer- A. Cardiovascular anomalies Diaphragmatic Hernia is defined as a communication between abdominal & thoracic cavities with or without abdominal contents in thorax. Females are affected more than males. More common on left side and is posterolateral. Associated anomalies may be seen 30% of cases CNS lesions, esophageal atresia, omphalocele and CVS lesions. Most cases are sporadic. Cardiac anomalis is MC anomalis.","pyqMatches":[{"year":"2012","no":1212,"q":"In Diapragmatic Hernia. Most common anomaly is seen in","o":["Cardiovascular anomalies","Urinary tract","Craniofacial anomaly","Skull anomaly"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7162, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 367, '{"id":7162,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":367,"q":"Causes of mental retardation in congenital hypothyroidism is -","o":["Decrease cerebral growth","Decrease myelination of CNS neuron","Decrease growth hormone by pitutary glands","Decreae production of neurotransmitters"],"a":0,"e":"Answer- A. Decrease cerebral growth is ''a'' i.e., Decrease cerebral growth [Ref : Ghai 7h/e p. 481; Jornal of Americal Physiological Review] Thyroid hormone has major effect on brain in utero & neonatal period, deficiency cause diminsh axonal growth, dendritic arborisation, delay proliferation & migration of granule cell so it decrease cerebral growth.","pyqMatches":[{"year":"2012","no":1157,"q":"Causes of mental retardation in congenital hypothyroidism is","o":["Decrease cerebral growth","Decrease myelination of CNS neuron","Decrease growth hormone by pitutary glands","Decreae production of neurotransmitters"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7163, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 368, '{"id":7163,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":368,"q":"Mousy urine in a child due to defect in phenylalamine to","o":["Tyrosine","Homogentisic acid","Phenyl acetate","Phenylpyruvate"],"a":0,"e":"Answer- A. Tyrosine Phenylketonuria: Autosomal recessive Deficiency of phenylalanine hydroxylase. Defect in conversion of phenylalanine to tyrosine. This leads to increase level of phenylalanine. This increase phenlylalanine converted into phenylpyruvate and phenyl acetate. This phenyl acetate gives mousy or musty odour in urine/body.","pyqMatches":[{"year":"2012","no":1217,"q":"Mousy urine in a child due to defect in phenylalamine to","o":["Tyrosine","Homogentisic acid","Phenyl acetate","Phenylpyruvate"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7164, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 369, '{"id":7164,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":369,"q":"Most common site of extramedullary relapse of ALL in 6 year old is","o":["Testes","Liver","Lung","None"],"a":0,"e":"Answer- A. Testes The common sites of relapse of ALL after complete remission are : Bone marrow (mc), CNS (2 mc) and testis.","pyqMatches":[{"year":"2012","no":1219,"q":"Most common site of extramedullary relapse of ALL in 6 year old is","o":["Testes","Liver","Lung","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7165, 'Pediatrics', 'Nephrology', 'Easy', 'Pediatrics (1)', 370, '{"id":7165,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":370,"q":"Male pseudohermaphrodism most common cause -","o":["Congenital adrenal hyperplasia","Adrenocortical tumor","Chromosomal abnormalities","Cytogenetic abnormalities"],"a":3,"e":"Answer- D. Cytogenetic abnormalities Most common cause of female pseudohermaphroditism - CAH due to 21 hydroxylase deficiency. Most common cause of male pseudohermaphroditism - Gonadal dysgenesis and defect in androgen action.","pyqMatches":[{"year":"2012","no":1156,"q":"Male pseudohermaphrodism most common cause","o":["Congenital adrenal hyperplasia","Adrenocortical tumor","Chromosomal abnormalities","Cytogenetic abnormalities"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7166, 'Pediatrics', 'Hematology', 'Easy', 'Pediatrics (1)', 371, '{"id":7166,"subject":"Pediatrics","chapter":"Hematology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":371,"q":"Enzyme used as treatment for sickle cell anemia","o":["Chymotrypsin","Glucose 6-phosphatase","Trypsin","None of above"],"a":0,"e":"Answer- A. Chymotrypsin Chymotrypsis used in Sickle cell disease.","pyqMatches":[{"year":"2012","no":1177,"q":"Enzyme used as treatment for sickle cell anemia","o":["Chymotrypsin","Glucose 6-phosphatase","Trypsin","None of above"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7167, 'Pediatrics', 'Nephrology', 'Easy', 'Pediatrics (1)', 372, '{"id":7167,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":372,"q":"XX baby presenting with penis & scrotum cause -","o":["High level of testosterone in maternal blood","Klinfilter syndrome","Turner syndrome","None of above"],"a":0,"e":"Answer- A. High level of testosterone in maternal blood This is a case of female pseudohermaphroditism i.e. XX karyotype with virilized external genitalia. Maternal androgen (testosterone) is the cause of this. Female pseudohermaphroditism Genotype is XX. Internal gonad is ovary but external genitalia are virilized (male differentiation). Congenital adrenal hyperplasia (CAH) due to 21-hydroxylase deficiency is the commonest cause. Other causes are maternal virilizing tumor (arrhenoblastoma),maternal androgen administration, CAH due to 11-beta hydroxylase deficiency, fetal placental aromatase deficiency, and WNT-4 gene mutation.","pyqMatches":[{"year":"2012","no":1155,"q":"XX baby presenting with penis & scrotum cause","o":["High level of testosterone in maternal blood","Klinfilter syndrome","Turner syndrome","None of above"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7168, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 373, '{"id":7168,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":373,"q":"Which of the fontanelle is the last to close?","o":["Anterolateral","Anterior","Lateral","Occipital"],"a":1,"e":"Ans. B. Anterior The posterior fontanelle normally closes 2 to 3 months after birth The sphenoidal fontanelle is the next to close around 6 months after birth The mastoid fontanelle closes next from 6 to 18 months after birth; The anterior fontanelle is generally the last to close between 18–24 months.","pyqMatches":[{"year":"2018","no":158,"q":"Which of the fontanelle is the last to close?","o":["Anterolateral","Anterior","Lateral","Occipital"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7169, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 374, '{"id":7169,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":374,"q":"Which enzyme deficiency causesLesch– Nyhan syndrome ?","o":["Hypoxanthine-guanine phosphoribosyltransferase (HGPRT)","Xanthine oxidase","Adenine phosphoribosyltransferase (APRT)","AMP deaminase"],"a":0,"e":"Ans. A.Hypoxanthine-guanine phosphoribosyltransferase (HGPRT) Lesch–Nyhan syndrome (LNS), also known as juvenile gout, is a rare inherited disorder caused by a deficiency of the enzyme hypoxanthine-guanine phosphoribosyltransferase (HGPRT), produced by mutations in the HPRT gene located on the X chromosome","pyqMatches":[{"year":"2018","no":159,"q":"Which enzyme deficiency causesLesch– Nyhan syndrome ?","o":["Hypoxanthine-guanine phosphoribosyltransferase (HGPRT)","Xanthine oxidase","Adenine phosphoribosyltransferase (APRT)","AMP deaminase"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7170, 'Pediatrics', 'Infectious Diseases', 'Moderate', 'Pediatrics (1)', 375, '{"id":7170,"subject":"Pediatrics","chapter":"Infectious Diseases","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":375,"q":"Which vaccine is not include in indradhanush mission?","o":["Tuberculosis","Measles","Japanese Encephalitis","Diphtheria"],"a":2,"e":"Ans. C. Japanese Encephalitis The Mission Indradhanush, depicting seven colours of the rainbow, targets to immunize all children against seven vaccine preventable diseases namely: Diphtheria Pertussis Tetanus Childhood Tuberculosis Polio Hepatitis B Measles.","pyqMatches":[{"year":"2018","no":160,"q":"Which vaccine is not include in indradhanush mission?","o":["Tuberculosis","Measles","Japanese Encephalitis","Diphtheria"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7171, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 376, '{"id":7171,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":376,"q":"Which among the following is the Most common cause for neonatal blindness?","o":["Neisseria gonorrhoeae","Chlamydia trachomatis","Klebsiella","Enterobacter"],"a":0,"e":"Ans. A. Neisseria gonorrhoeae Ophthalmia neonatorum (ON) is defined as a purulent conjunctivitis occurring during the first four weeks of life. The two most common causative agents are Neisseria gonorrhoeae and Chlamydia trachomatis, the former being of more concern here because of its propensity to cause blindness.","pyqMatches":[{"year":"2018","no":161,"q":"Which among the following is the Most common cause for neonatal blindness?","o":["Neisseria gonorrhoeae","Chlamydia trachomatis","Klebsiella","Enterobacter"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7172, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 377, '{"id":7172,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":377,"q":"True hermaphroditism karyotype:","o":["45 X0 streaked gonads","46 XX Ovotestis","47 XY+9","47 XX"],"a":1,"e":"Ans. B.46XX Ovotestis True hermaphrodite or ovotesticular disorder of sexual differentiation (OVO-DSD) is one of the rarest variety of all inter sex anomalies. In about 90% of cases, patients have 46 XX karyotype. Rarely, 46 XY/46 XX mosaicism may occur.","pyqMatches":[{"year":"2018","no":181,"q":"True hermaphroditism karyotype:","o":["45 X0 streaked gonads","46 XX Ovotestis","47 XY+9","47 XX"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"},{"year":"2020","no":204,"q":"True hermaphroditism karyotype:","o":["45 X0 streaked gonads","46 XX Ovotestis","47 XY+9","47 XX"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2018","2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7173, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 378, '{"id":7173,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":378,"q":"When can one diagnose acute respiratory distress in a child ?","o":["Within 7 days of known clinical insult","Respiratory failure not fully explained","Left ventricular dysfunction","All of the above"],"a":3,"e":"Ans: D. All of the above Pediatric Critical Care Medicine 2015 Age Exclude patients with 1:m11-natal related lung disease Iiming Within 7 days of known clinical Insult origin of Edema Respiratory failure not fully explained by cardiac failure or fluid overload Chest Chest Imaging imaging findings of new infiltrate(siconsigent with acute pulmonary Oxygenation Non invasive mechanical ventilation lovas i ve mechanical ventilation- PARRS (No severity gratification) Mild Moderate Severe Full face-mask bi-level ventilation or CPAP z5 crn HA a PF ratios 300 SF ratio 5 2E4 I 4501c8 Ss09.c7.51 EK 01 < 16 7.5 OSI <12.31 O1 t16 CiSt 1233 Specia- l Populations tandard Criteria above for age, timing, origin of edema Cyanotic Heart Disease and chest imaging with an acute deterioration In oxygenation not explained by underlying cardiac disease. Chronic Lung Disease standard Criteria above for age, timing, and origin of edema with chest imaging consistent with new infiltrate and acute deterioration in oxygenation from baseline which meet oxygenation criteria above_ Left Ventricular dysfunction Standard Criteria for age, timing and origin of edema with chest imaging changes consistent with new infiltrate and acute deterioration in oxygenation which meet criteria above not explained by left ventricular dysfunction.","pyqMatches":[{"year":"2018","no":257,"q":"When can one diagnose acute respiratory distress in a child ?","o":["Within 7 days of known clinical insult","Respiratory failure not fully explained","Left ventricular dysfunction","All of the above"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7174, 'Pediatrics', 'Neonatology', 'Moderate', 'Pediatrics (1)', 379, '{"id":7174,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Moderate","source":"Pediatrics (1)","sourceNo":379,"q":"New born baby with heart rate less than 60 beats per minute can be resuscitated by all except","o":["chest compression","oxygen therapy","tactile stimulation","slapping the back"],"a":3,"e":"Ans: D.slapping the back The first three s are indicated while slapping the back is not recommended in a newborn who has Heart rate less than 60 beats per minute.","pyqMatches":[{"year":"2018","no":255,"q":"New born baby with heart rate less than 60 beats per minute can be resuscitated by all except","o":["chest compression","oxygen therapy","tactile stimulation","slapping the back"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7175, 'Pediatrics', 'Nephrology', 'Easy', 'Pediatrics (1)', 380, '{"id":7175,"subject":"Pediatrics","chapter":"Nephrology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":380,"q":"Which condition is associated with Congenital adrenal hypoplasia?","o":["Male pseudohermaphroditism","Female pseudohermaphroditism","True pseudohermaphroditism","Sequential pseudohermaphroditism"],"a":1,"e":"Answer - B - Congenital Adrenal Hyperplasia: This is the most common cause of androgenic excess in fetuses with female pseudohermaphroditism. The hyperplastic glands synthesize defective enzymes that cause impaired cortisol synthesis. This leads to excessive pituitary ACTH the secretion of the fetal adrenal glands with secretion of large amounts of cortisol precursors, including androgenic prehormones. These prehormones, for example, androstenedione, are converted to testosterone in fetal extra-adrenal tissues.","pyqMatches":[{"year":"2018","no":289,"q":"Which condition is associated with Congenital adrenal hypoplasia?","o":["Male pseudohermaphroditism","Female pseudohermaphroditism","True pseudohermaphroditism","Sequential pseudohermaphroditism"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7176, 'Pediatrics', 'Miscellaneous', 'Hard', 'Pediatrics (1)', 381, '{"id":7176,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":381,"q":"1 yr child weighing 6 kg is suffering from Acute Gastroenteritis along with signs of sunken eyes & skin pinch going back to normal very rapidly. What will be your management?","o":["RL infusion 120 ml in the first hour followed by 360 ml in the next 5 hours","RL INFUSION 180 ml in the first hour followed by 420 ml in the next 5 hours","RL INFUSION 180 ML IN the first hour followed by 480 ml in the next 5 hours","RL INFUSION 240 ml in the first hour followed by 360 ml in the next 5 hours"],"a":1,"e":"Ans. B.RL INFUSION 180 ml in the first hour followed by 420 ml in the next 5 hours Severe dehydration constitutes a medical emergency requiring immediate resuscitation with intravenous fluids. Intravenous access should be obtained, and patients should be administered a bolus of 20-30 mL/kg lactated Ringer''s (LR) or normal saline (NS). If pulse, perfusion, and/or mental status do not improve, a second bolus should be administered. After this, the patient should be given an infusion of 70 mL/kg LR or NS over 5 hours (children < 12 months) or 2.5 hours (older children). If no peripheral veins are available, an intraosseous line should be placed. Serum electrolytes, bicarbonate, urea/creatinine, and p y glucose levels should be sent.","pyqMatches":[{"year":"2018","no":251,"q":"1 yr child weighing 6 kg is suffering from Acute Gastroenteritis along with signs of sunken eyes & skin pinch going back to normal very rapidly. What will be your management?","o":["RL infusion 120 ml in the first hour followed by 360 ml in the next 5 hours","RL INFUSION 180 ml in the first hour followed by 420 ml in the next 5 hours","RL INFUSION 180 ML IN the first hour followed by 480 ml in the next 5 hours","RL INFUSION 240 ml in the first hour followed by 360 ml in the next 5 hours"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7177, 'Pediatrics', 'Nutrition', 'Easy', 'Pediatrics (1)', 382, '{"id":7177,"subject":"Pediatrics","chapter":"Nutrition","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":382,"q":"Which parameter conclusively rules out malnutrition?","o":["Edema","Lean body mass","Skinfold thickness","Normal ECF volume"],"a":1,"e":"Ans. B. Lean body mass Measuring weight and height is the most common way of assessing malnutrition in a given population. Such use of measurements of dimensions of the human body is known as anthropometry. Anthropometry is a widely used, inexpensive and noninvasive measure of the general nutritional status of an individual or a population group. The three commonly used anthropometric indices are : - Weight-for-Age {WFA). - Length-for-Age or Height-For-Age (HFA). - Weight-for-Length or Weight-for-Height {WFH). PEM reduces growth in children Energy expenditure in excess of consumption leads to metabolizing nutrition reserves in the form of stored body fat. Lean body mass in the form of muscle and even organ tissue will also be consumed if PEM persists. it serves as a reliable indicator for PEM Weight loss accompanies the initial stages of inadequate energy intake but, if prolonged, is followed by wasting, called in its severe clinical form, marasmus. In children, PEM delays or permanently stunts growth and increases morbidity and mortality. Ref. Park PSM ed. 24th Page no. 677","pyqMatches":[{"year":"2020","no":199,"q":"Which parameter conclusively rules out malnutrition?","o":["Edema","Lean body mass","Skinfold thickness","Normal ECF volume"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7178, 'Pediatrics', 'Nutrition', 'Hard', 'Pediatrics (1)', 383, '{"id":7178,"subject":"Pediatrics","chapter":"Nutrition","difficulty":"Hard","source":"Pediatrics (1)","sourceNo":383,"q":"A 2 years baby with 6.7 kg, Hb%- 6 mg/dl total protein 3mg/dL, low albumin with distended stomach but no proteinuria. What will be the diagnosis?","o":["Marasmus","Kwashiorkor","Indian childhood cirrhosis","None"],"a":1,"e":"Ans. B. Kwashiorkor Kwashiorkor is a form of severe acute malnutrition (SAM) characterized by edema and apathy. Edema is most likely to appear first on the feet and then in the lower legs. It can develop into generalized edema affecting the hands, arms, and face. Moon face Skin changes include depigmentation of skin, dermatoses, dark, cracked peeling patches (flaky paint dermatosis) with pale skin underneath that is easily infected. Hair is sparse, easily pulled out, and may turn reddish. Flag sign: alternating bands of hypopigmented and normal pigmented areas on the hair strand The liver is often enlarged with fat (fatty Liver). The children are miserable and apathetic and often refuse to eat. Muscle wasting and growth failure are seen. Villous atrophy of small intestine and diarrhea. Nelson Textbook of Pediatrics 20th Edition Page:301","pyqMatches":[{"year":"2020","no":200,"q":"A 2 years baby with 6.7 kg, Hb%- 6 mg/dl total protein 3mg/dL, low albumin with distended stomach but no proteinuria. What will be the diagnosis?","o":["Marasmus","Kwashiorkor","Indian childhood cirrhosis","None"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7179, 'Pediatrics', 'Miscellaneous', 'Easy', 'Pediatrics (1)', 384, '{"id":7179,"subject":"Pediatrics","chapter":"Miscellaneous","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":384,"q":"In RDS in a child, which cells are found defective?","o":["Type 1 pneumocytes","Type 2 pneumocytes","Bronchial epithelium","None"],"a":1,"e":"Ans. B. Type 2 pneumocytes Type I cells form the alveolar wall while the Type II cells synthesize and secrete surfactant DPCC. The defect in the biosynthesis of Dipalmitoylphosphatidylcholine (DPPC), also known as dipalmitoyl lecithin leads to Respiratory distress syndrome. Ref. https://www.ncbi.nlm.nih.gov/pmc/articles/PMC2880575/","pyqMatches":[{"year":"2020","no":201,"q":"In RDS in a child, which cells are found defective?","o":["Type 1 pneumocytes","Type 2 pneumocytes","Bronchial epithelium","None"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7180, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 385, '{"id":7180,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":385,"q":"Cause of greenish-black stool in a neonate -","o":["Meconium","Biliverdin","Bilirubin","Urochrome"],"a":1,"e":"Ans. B. Biliverdin Fetal bowel contents consist of various products of secretion, such as glycerophospholipids from the lung, desquamated fetal cells, lanugo, scalp hair, and vernix. It also contains undigested debris from the swallowed amnionic fluid. The dark greenish-black is caused by pigments, especially biliverdin. Ref. Williams Obstetrics Ed. 24th Page no. 141","pyqMatches":[{"year":"2020","no":202,"q":"Cause of greenish-black stool in a neonate","o":["Meconium","Biliverdin","Bilirubin","Urochrome"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7181, 'Pediatrics', 'Neonatology', 'Easy', 'Pediatrics (1)', 386, '{"id":7181,"subject":"Pediatrics","chapter":"Neonatology","difficulty":"Easy","source":"Pediatrics (1)","sourceNo":386,"q":"A term baby on breastfeeding with bilirubin 14mg/dL which of the following is true?","o":["Exchange transfusion","Continue to breastfeed","Phototherapy","None"],"a":1,"e":"Ans. B. Continue to breastfeed Compared with formula-fed newborns, breastfed infants are three to six times more likely to experience moderate jaundice (total serum bilirubin level above 12 mg per dL) or severe jaundice (total serum bilirubin level above 15 mg per dL. In a breastfed newborn with early-onset hyperbilirubinemia, the frequency of feedings needs to be increased to more than 10 per day. If the infant has a decline in weight gain, delayed stooling, and continued poor caloric intake, formula supplementation may be necessary, but breastfeeding should be continued to maintain breast milk production. Phototherapy usually not recommended when the total serum bilirubin level is below 15 mg per dL. Ref: https://www.aafp.org/afp/2002/0215/p599.html","pyqMatches":[{"year":"2020","no":203,"q":"A term baby on breastfeeding with bilirubin 14mg/dL which of the following is true?","o":["Exchange transfusion","Continue to breastfeed","Phototherapy","None"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7182, 'Pharmacology', 'Antimicrobials', 'Easy', 'Pharmacology', 1, '{"id":7182,"subject":"Pharmacology","chapter":"Antimicrobials","difficulty":"Easy","source":"Pharmacology","sourceNo":1,"q":"Mechanism of action of quinolones is?","o":["DNA gyrase inhibitors","Bind to 30 s unit","Bind to bacterial cell membrane","Bind to tetrahydofolate reductase"],"a":3,"e":"DNA gyrase inhibitors REF: Goodman Gillman''s 11th ed p. 722 The quinolone antibiotics target bacterial DNA gyrase and topoisomerase IV. For many gram positive bacteria, topoisomerase IV is the primary target. For many gram-negative bacteria, DNA gyrase is the primary quinolone target.","pyqMatches":[{"year":"2012","no":570,"q":"Mechanism of action of quinolones is?","o":["DNA gyrase inhibitors","Bind to 30 s unit","Bind to bacterial cell membrane","Bind to tetrahydofolate reductase"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7183, 'Pharmacology', 'Autonomic Nervous System', 'Moderate', 'Pharmacology', 2, '{"id":7183,"subject":"Pharmacology","chapter":"Autonomic Nervous System","difficulty":"Moderate","source":"Pharmacology","sourceNo":2,"q":"Drug NOT used in pulmonary hypertension ‑","o":["Calcium channel blocker","Endothelin receptor antagonist","Alpha blocker","Prostacyclin"],"a":2,"e":"alpha blockers [Ref- Harrison 17th/e p 1577, 1578] Pulmonary hypertension General management Diuretic therapy may be useful as it relieves pulmonary edema. Anticoagulant therapy is advocated for all patients. Specific management Calcium channel blockers Patients who have substantial reductions in pulmonary arterial pressure in response to short acting vasodilators at the time of cardiac catheterization should he initially treated with calcium channel blockers. Endothelin receptor antagonist Bostenan is a non-selective endothelium receptor antagonist, is an approved t/t ,for patients who are NYHA .functional classes III and IV. Phosphodiesterase-5 inhibitors Slidenafil is used for patients who are NYHA functional classes II and Prostacyclins Iloprost is a prostacyclin analogue used in PAH patients who are NYHA functional classes III and IV. Pulmonary circulation is unique in that it accommodates a blood flow that is almost equal to that of all the other organs of body but still maintains low pressure. The factors responsible for low pressure in pulmonary circulation (even with large volume of blood) are:- - Larger diameter of pulmonary vessels due to thin wall of pulmonary artery and arterioles. - Greater compliance (distensibility) of pulmonary vessels. numoral factors responsible for maintaining pulmonary circulation:? Normally NO causes vosodilation and proliferation of smooth muscles by r in the conc. of cGMP —) this increases the diameter of pulmonary vessels. causes vosodilation and decreased proliferation of smooth muscles by increasing the conc. of cAMPincrease in the diameter of pulmonary vessels. Prostaglandin also decreases coagulation. Endothelin causes vasoconstriction and increase smooth muscle proliferation si lumen of pulmonary vessels. - Normally the vasodilators and antiprolifeave effects of NO and PGI7 dominate In Pulmonary hypertension There is l production of NO (and cGMP) and PGI2 (and cAMP), t vasoconstriction and proliferation of smooth muscles, st lumen of pulmonary vessel. Decreased production of PGI2 also causes increased coagulation. There is T production of endothelin, /vasoconstriction and smooth muscle proliferation, .1 lumen. Drug therapy in puhnonan, hypertension is targetted at these growth factor pathways which are involved in the pathogenesis of pulmonary hypertension: Endothelium receptor antagonist Bostenan is an endothelin receptor antagonist. It prevents endothelin mediated contraction of vessels. Phosphodiesterase-5 inhibitors Nitric oxide mediates its action through increasing cGMP concentration. Increased cGMP relaxes the vessels. cGMP is degraded by an enzyme phosphodiesterase-5 (PDE-5). - Slidenafanil is a phosphodiesterase 5 inhibitor. It reduces the degradation of cGMP, thus causing vascular relaxation and reducing pulmonary hypertension. Prostacyclins In pulmonary hypertension, the level of prostacycline is reduced. This causes pulmonary constriction as prostacyclin causes dilatation of pulmonary vessels.","pyqMatches":[{"year":"2015","no":922,"q":"Drug NOT used in pulmonary hypertension ‑","o":["Calcium channel blocker","Endothelin receptor antagonist","Alpha blocker","Prostacyclin"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7184, 'Pharmacology', 'Miscellaneous', 'Moderate', 'Pharmacology', 3, '{"id":7184,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pharmacology","sourceNo":3,"q":"Regarding efficacy and potency of a drug, all are true, EXCEPT:","o":["In a clinical setup, efficacy is more important than potency","In the log dose response curve, the height of the curve corresponds with efficacy","ED50 of the drug corresponds to efficacy","Drugs that produce a similar pharmacological effect can have different levels of efficacy"],"a":2,"e":"ED50 refers to Effective Dose of a drug needed to produce a particular response in 50% of population. It is a quantitative measure of the potency of a drug. Smaller the ED50 value, more potent is the drug. Ref: Encyclopedia of Psychopharmacology By Ian P. Stolerman, Volume 2, Page 456","pyqMatches":[{"year":"2015","no":501,"q":"Regarding efficacy and potency of a drug, all are true, EXCEPT:","o":["In a clinical setup, efficacy is more important than potency","In the log dose response curve, the height of the curve corresponds with efficacy","ED50 of the drug corresponds to efficacy","Drugs that produce a similar pharmacological effect can have different levels of efficacy"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7185, 'Pharmacology', 'General Pharmacology', 'Easy', 'Pharmacology', 4, '{"id":7185,"subject":"Pharmacology","chapter":"General Pharmacology","difficulty":"Easy","source":"Pharmacology","sourceNo":4,"q":"Zero-order kinetics is otherwise known as saturation kinetics. It is independent of:","o":["Plasma concentration","Clearance","Volume of distribution","Half life"],"a":0,"e":"Ans. A. Plasma concentration In zero-order kinetics or saturation kinetics, elimination mechanisms become saturated and unable to process more drugs when drug concentrations rise. Consequently, for drugs that are eliminated by zero-order kinetics, a constant amount of drug is eliminated per unit time regardless of drug plasma concentration.","pyqMatches":[{"year":"2020","no":69,"q":"Zero-order kinetics is otherwise known as saturation kinetics. It is independent of:","o":["Plasma concentration","Clearance","Volume of distribution","Half life"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7186, 'Pharmacology', 'Hematology & Blood', 'Easy', 'Pharmacology', 5, '{"id":7186,"subject":"Pharmacology","chapter":"Hematology & Blood","difficulty":"Easy","source":"Pharmacology","sourceNo":5,"q":"Filgrastim is used in treatment of:","o":["Anemia","Neutropenia","Malaria","Filarial"],"a":1,"e":"Ans. is. B. Neutropenia Filgrastim is a recombinant human granulocyte colony stimulating factor (G-CSF) which is a 175 - aminoacid glyco-protein. It differs from the natural granulocyte stimulating factor due to its lack in glycosylation and the presence of an extra N-terminal methionine. It has proved to be effective in the treatment of severe neutropenia. Ref: Goodman and Gilman''s The Pharmacological Basis of Therapeutics, 11th Edition, Pages 1429-32; Immunopharmacology By Manzoor M. Khan, Pages 49-50","pyqMatches":[{"year":"2019","no":94,"q":"Filgrastim is used in treatment of:","o":["Anemia","Neutropenia","Malaria","Filarial"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7187, 'Pharmacology', 'Autonomic Nervous System', 'Easy', 'Pharmacology', 6, '{"id":7187,"subject":"Pharmacology","chapter":"Autonomic Nervous System","difficulty":"Easy","source":"Pharmacology","sourceNo":6,"q":"Guanethidine is used in the treatment of which of the following condition?","o":["Thyrotoxic ophthalmopathy","Ptosis","Bell’s palsy","Horner’s syndrome"],"a":0,"e":"Guanethidine (10%) eye drops is useful in decreasing lid retraction in Thyrotoxic ophthalmopathy. It is an adrenergic neuron blocker which acts by inhibiting the release of noradrenaline in response to nerve stimulation.","pyqMatches":[{"year":"2012","no":530,"q":"Guanethidine is used in the treatment of which of the following condition?","o":["Thyrotoxic ophthalmopathy","Ptosis","Bell’s palsy","Horner’s syndrome"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7188, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 7, '{"id":7188,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":7,"q":"Finasteride is a:","o":["5 alpha reductase inhibitor","PDE inhibitor","Alpha la blocker","Androgen receptor blocker"],"a":0,"e":"Finasteride is a competitive inhibitor of the enzyme 5-alpha reductase which is responsible for the conversion of testosterone into a more active dihydrotestosterone responsible for the androgen action. When used in benign prostatic hypertrophy, it reduces the prostate size and increased peak urinary flow rate. It is also used in male pattern baldness and as a palliative treatment in prostatic carcinoma. Ref: K D Tripathi Textbook of Pharmacology, 5th Edition, Page 272","pyqMatches":[{"year":"2012","no":557,"q":"Finasteride is a:","o":["5 alpha reductase inhibitor","PDE inhibitor","Alpha la blocker","Androgen receptor blocker"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7189, 'Pharmacology', 'Endocrine Pharmacology', 'Hard', 'Pharmacology', 8, '{"id":7189,"subject":"Pharmacology","chapter":"Endocrine Pharmacology","difficulty":"Hard","source":"Pharmacology","sourceNo":8,"q":"A 47-year-old woman presents with complaints of nervousness and increased sensitivity to hot weather. She is diagnosed with hyperthyroidism and prescribed propylthiouracil. What is the principal mechanism by which this drug acts?","o":["Decreasing the efficacy of TSH binding to the thyroid TSH receptor","Decreasing the rate of proteolysis of thyroglobulin","Increasing the amount of 3,3'',5''-triiodothyronine (reverse T3; rT3)","Inhibiting deiodination of thyroxine (T4)"],"a":3,"e":"Propylthiouracil works primarily by inhibiting the peripheral conversion of T4 to T3. The thyroid extracts iodide from the plasma and, in an oxidative process, iodinated tyrosine residues in thyroglobulin molecules. Monoiodotyrosine and diiodotyrosine are formed and then coupled to produce either thyroxine (tetraiodothyronine, T4) or triiodothyronine (T3). Proteolytic cleavage of thyroglobulin molecules leads to free T3 or T4, which is then released into the circulation; T3 is several times more potent than T4. Peripheral deiodination of T4 at the 5'' position leads to T3 formation (mainly in the liver); this step is inhibited by propylthiouracil. Decreasing the efficacy of TSH binding, decreasing the rate of thyroglobulin proteolysis, increasing the amount of rT3 formation, and inhibiting the uptake of iodide into the thyroid, would all tend to decrease the formation of thyroid hormones in the thyroid itself.","pyqMatches":[{"year":"2015","no":558,"q":"A 47-year-old woman presents with complaints of nervousness and increased sensitivity to hot weather. She is diagnosed with hyperthyroidism and prescribed propylthiouracil. What is the principal mechanism by which this drug acts?","o":["Decreasing the efficacy of TSH binding to the thyroid TSH receptor","Decreasing the rate of proteolysis of thyroglobulin","Increasing the amount of 3,3'',5''-triiodothyronine (reverse T3; rT3)","Inhibiting deiodination of thyroxine (T4)"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7190, 'Pharmacology', 'Autonomic Nervous System', 'Moderate', 'Pharmacology', 9, '{"id":7190,"subject":"Pharmacology","chapter":"Autonomic Nervous System","difficulty":"Moderate","source":"Pharmacology","sourceNo":9,"q":"Spironolactone should NOT be given with the following pharmacological agent:","o":["Chlorothiazide","b-blocker","ACE inhibitors","Amlodipine"],"a":2,"e":"Unlike most other diuretics, K+-sparing diuretics reduce urinary excretion of K+ and can cause mild, moderate, or even life-threatening hyperkalemia. The risk of this complication is greatly increased by renal disease (in which maximal K+ excretion may be reduced) or by the use of other drugs that reduce or inhibit renin (beta blockers, NSAIDs, aliskiren) or angiotensin II activity (angiotensin- converting enzyme inhibitors, angiotensin receptor inhibitors). Since most other diuretic agents lead to K+ losses, hyperkalemia is more common when K+-sparing diuretics are used as the sole diuretic agent, especially in patients with renal insufficiency. Ref: Ives H.E. (2012). Chapter 15. Diuretic Agents. In B.G. Katzung, S.B. Masters, A.J. Trevor (Eds), Basic & Clinical Pharmacology, 12e.","pyqMatches":[{"year":"2015","no":540,"q":"Spironolactone should NOT be given with the following pharmacological agent:","o":["Chlorothiazide","b-blocker","ACE inhibitors","Amlodipine"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7191, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 10, '{"id":7191,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":10,"q":"Maximum plasma protein bound drug is ?","o":["NTG","Verapamil","Aspirin","GTN"],"a":1,"e":"Ans. is ''b'' i.e., Verapamil o Among the given options only verapamil has significant plasma protein binding (see text of the chapter).","pyqMatches":[{"year":"2013","no":502,"q":"Maximum plasma protein bound drug is ?","o":["NTG","Verapamil","Aspirin","GTN"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7192, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 11, '{"id":7192,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":11,"q":"CYP3A inhibitors is/are -","o":["Ritonavir","Amiodarone","Verapamil","a and c"],"a":3,"e":"Ans. is ''a'' i.e., Ritonavir; ''c'' i.e., Verapamil CYP3A4/3A5 inhibitors are o Ritonavir o Erythromycin o Itraconazole o Troieandomycin o Verapamil o Clarithromycin o Azamulin o Diltiazem o Ketoconazole o Grapefruit juice (Furano coumarins)","pyqMatches":[{"year":"2015","no":500,"q":"CYP3A inhibitors is/are","o":["Ritonavir","Amiodarone","Verapamil","a and c"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7193, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 12, '{"id":7193,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":12,"q":"In the metabolism of alcohol, high doses of aspirin & phenytoin, mechanism is ?","o":["First pass kinetics","First order kinetics","Zero order kinetics","Second order kinetics"],"a":2,"e":"Ans. is ''c'' i.e., Zero order kinetics","pyqMatches":[{"year":"2013","no":500,"q":"In the metabolism of alcohol, high doses of aspirin & phenytoin, mechanism is ?","o":["First pass kinetics","First order kinetics","Zero order kinetics","Second order kinetics"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7194, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 13, '{"id":7194,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":13,"q":"Type B adverse drug reaction -","o":["Augmented effect of drug","Unpredictable Bizzare reaction","Effect seen on chronic use of drug","Delayed effect of drug"],"a":1,"e":"Ans. is ''b'' i.e., Unpredictable Bizzare reaction Types of adverse drug reaction","pyqMatches":[{"year":"2012","no":520,"q":"Type B adverse drug reaction","o":["Augmented effect of drug","Unpredictable Bizzare reaction","Effect seen on chronic use of drug","Delayed effect of drug"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7195, 'Pharmacology', 'Autonomic Nervous System', 'Easy', 'Pharmacology', 14, '{"id":7195,"subject":"Pharmacology","chapter":"Autonomic Nervous System","difficulty":"Easy","source":"Pharmacology","sourceNo":14,"q":"Urinary bladder spasmolytic having local anaesthetic property-","o":["Tamsulosin","Terazosin","Oxybutynin","Yohimbine"],"a":2,"e":"Ans. is ''c'' i.e., Oxybutynin o Oxybutynin, a newer antimuscarinic, has high affinity for receptors in urinary bladder and salivary glands alongwith additional smooth muscle relaxant and local anaesthetic properties.","pyqMatches":[{"year":"2013","no":514,"q":"Urinary bladder spasmolytic having local anaesthetic property","o":["Tamsulosin","Terazosin","Oxybutynin","Yohimbine"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7196, 'Pharmacology', 'Autonomic Nervous System', 'Moderate', 'Pharmacology', 15, '{"id":7196,"subject":"Pharmacology","chapter":"Autonomic Nervous System","difficulty":"Moderate","source":"Pharmacology","sourceNo":15,"q":"Dopamine all of the following is true Except?","o":["Causes increase in GI Isehemia","Positive ionotropic","Improves renal perfusion","Causes Vasoconstriction"],"a":0,"e":"Ans. is ''a'' i.e., Causes increase in GI Ischemia o Dopamine acts on dopamine (Di & D2) and adrenergic (a1 + a2 + [31) receptors, with no action on p, receptors. o At lowest effective dose it stimulates D1 receptors in renal & mesentric blood vessels —> improves renal and mesentric perfusion. o At moderately high doses it acts as 13, agonist --> positive ionotropic. o At high doses it activates a-adrenoreceptors —> vasoconstriction.","pyqMatches":[{"year":"2012","no":521,"q":"Dopamine all of the following is true Except?","o":["Causes increase in GI Isehemia","Positive ionotropic","Improves renal perfusion","Causes Vasoconstriction"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7197, 'Pharmacology', 'Miscellaneous', 'Moderate', 'Pharmacology', 16, '{"id":7197,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pharmacology","sourceNo":16,"q":"All are alpha-blocker except?","o":["Atenolol","Prazosin","Indoramine","Idazoxan"],"a":0,"e":"Ans. is ''a'' i.e., Atenolol","pyqMatches":[{"year":"2012","no":522,"q":"All are alpha-blocker except?","o":["Atenolol","Prazosin","Indoramine","Idazoxan"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7198, 'Pharmacology', 'Miscellaneous', 'Moderate', 'Pharmacology', 17, '{"id":7198,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pharmacology","sourceNo":17,"q":"The side effects of digitalis are all except ?","o":["Ventricular tachycardia","Vasodilatation","Nausea and vomiting","Ventricular Bigemini"],"a":1,"e":"Ans. is ''b'' i.e., Vasodilatation Digitalis causes mild vasoconstriction (not vasodilatation).","pyqMatches":[{"year":"2013","no":522,"q":"The side effects of digitalis are all except ?","o":["Ventricular tachycardia","Vasodilatation","Nausea and vomiting","Ventricular Bigemini"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7199, 'Pharmacology', 'Cardiovascular Drugs', 'Easy', 'Pharmacology', 18, '{"id":7199,"subject":"Pharmacology","chapter":"Cardiovascular Drugs","difficulty":"Easy","source":"Pharmacology","sourceNo":18,"q":"Which of the following potassium sparing diuretic alters cardiac mortality-","o":["Spironolactone","Amiloride","Triamterene","Epleronone"],"a":0,"e":"Ans. is ''a'' i.e., Spironolactone o Among potassium sparing diuretics, aldosterone antagonists (Spironolactone, eplerenone) reduce mortality in CHF.","pyqMatches":[{"year":"2012","no":523,"q":"Which of the following potassium sparing diuretic alters cardiac mortality","o":["Spironolactone","Amiloride","Triamterene","Epleronone"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7200, 'Pharmacology', 'Cardiovascular Drugs', 'Easy', 'Pharmacology', 19, '{"id":7200,"subject":"Pharmacology","chapter":"Cardiovascular Drugs","difficulty":"Easy","source":"Pharmacology","sourceNo":19,"q":"Anti androgen used in heart failure ?","o":["Carvedilol","Sampatrilat","Spironolactone","Abiraterone"],"a":2,"e":"Ans. is ''c'' i.e., Spironolactone o Spironolactone and eplerenone are the aldosterone antagonists. They are used as potassium sparing diuretics. Their diurectic effect is quite feeble, but in CHF these drugs reduce the mortality (at doses lower than diuretic doses) by antagonizing the effect of aldosterone (reversal of remodelling). Spironolactone also possesses anti- androgenic effects.","pyqMatches":[{"year":"2012","no":524,"q":"Anti androgen used in heart failure ?","o":["Carvedilol","Sampatrilat","Spironolactone","Abiraterone"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7201, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 20, '{"id":7201,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":20,"q":"Iodine content in amiodarone -","o":["10 - 20%","20 - 40%","40 - 60%","60 - 80%"],"a":1,"e":"Ans. is ''b'' i.e., 20 - 40%","pyqMatches":[{"year":"2012","no":526,"q":"Iodine content in amiodarone","o":["10 - 20%","20 - 40%","40 - 60%","60 - 80%"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7202, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 21, '{"id":7202,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":21,"q":"Which is true about calcium channel blockers -","o":["Verapamil causes reflex tachycardia","Diltiazam causes reflex tachycardia","Nifedipine causes reflex tachycardia","Nifedipine has longer t1/2 than felodipine"],"a":2,"e":"Ans. is ''c'' i.e., Nifedipine causes reflex tachycardia DHPs (nifedipine) cause reflex tachycardia. o Felodipine - it differs from nifedipine in having greater vascular selectivity, large tissue distribution and longer t1/2.","pyqMatches":[{"year":"2013","no":527,"q":"Which is true about calcium channel blockers","o":["Verapamil causes reflex tachycardia","Diltiazam causes reflex tachycardia","Nifedipine causes reflex tachycardia","Nifedipine has longer t1/2 than felodipine"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7203, 'Pharmacology', 'Cardiovascular Drugs', 'Easy', 'Pharmacology', 22, '{"id":7203,"subject":"Pharmacology","chapter":"Cardiovascular Drugs","difficulty":"Easy","source":"Pharmacology","sourceNo":22,"q":"Centrally acting antihypertensive drug is ?","o":["Phenoxybenzamine","Methy ldopa","Propanolol","Prazosin"],"a":1,"e":"Ans. is ''b'' i.e., Methyldopa o Centrally acting sympatholytic antihypertensives are clonidine, methyldopa, guanabenz, guanfacine, moxonidine and rilmenidine.","pyqMatches":[{"year":"2012","no":528,"q":"Centrally acting antihypertensive drug is ?","o":["Phenoxybenzamine","Methy ldopa","Propanolol","Prazosin"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7204, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 23, '{"id":7204,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":23,"q":"Wrong about clonidine is -","o":["Alpha 2 receptor agonist","First line for AMID","Sudden withdrawal causes rebound hypertension","Controls loose motions due to diabetic neuropathy"],"a":1,"e":"Ans. is ''b'' i.e., First line for ADHD * Behavioural therapy is the first line therapy for the treatment of ADHD. The first line drug for ADHD is Methylpheni date. * Clonidine is a partial agonist with high affinity and high intrinsic activity at α2 receptors. Sudden withdrawal of clonidine may cause life threatening hypertensive crisis. * Clonidine is used to control loose motions due to diabetic neuropathy. It may be acting by α2 receptor mediated enhancement of salt absorption in gut mucosa.","pyqMatches":[{"year":"2013","no":512,"q":"Wrong about clonidine is","o":["Alpha 2 receptor agonist","First line for AMID","Sudden withdrawal causes rebound hypertension","Controls loose motions due to diabetic neuropathy"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7205, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 24, '{"id":7205,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":24,"q":"Which of the following causes increased rennin on prolonged use ?","o":["Clonidine","Enalapril","Methyldopa","Blocker"],"a":1,"e":"Ans. is ''b i.e., Enalapril","pyqMatches":[{"year":"2012","no":527,"q":"Which of the following causes increased rennin on prolonged use ?","o":["Clonidine","Enalapril","Methyldopa","Blocker"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7206, 'Pharmacology', 'Cardiovascular Drugs', 'Moderate', 'Pharmacology', 25, '{"id":7206,"subject":"Pharmacology","chapter":"Cardiovascular Drugs","difficulty":"Moderate","source":"Pharmacology","sourceNo":25,"q":"Side effect of thiazide diuretics are all except ?","o":["Hyponatremia","Hypokalemia","Erectile dysfunction","Hypocalcemia"],"a":0,"e":"Ans. is ''A'' i.e., Hypocalcemia Thiazides cause hypercalcemia (see above explanation).","pyqMatches":[{"year":"2012","no":541,"q":"Side effect of thiazide diuretics are all except ?","o":["Hyponatremia","Hypokalemia","Erectile dysfunction","Hypocalcemia"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7207, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 26, '{"id":7207,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":26,"q":"Desmopressin is preferred over vasopressin because desmopressin -","o":["More potent","More selective for Vireceptor","Has little vasconstrictor activity","a and c"],"a":3,"e":"Ans. is ''a'' i.e., More potent; ''c'' i.e., Has little vasconstrictor activity o Desmopressin is longer acting o Desmopressin is V2 selective —) No V, mediated vasoconstriction. o Desmopressin is 12 times more potent than vasopressin.","pyqMatches":[{"year":"2012","no":542,"q":"Desmopressin is preferred over vasopressin because desmopressin","o":["More potent","More selective for Vireceptor","Has little vasconstrictor activity","a and c"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7208, 'Pharmacology', 'Cardiovascular Drugs', 'Easy', 'Pharmacology', 27, '{"id":7208,"subject":"Pharmacology","chapter":"Cardiovascular Drugs","difficulty":"Easy","source":"Pharmacology","sourceNo":27,"q":"In diabetes insipidus, diuretic showing paradoxical antiduretic activity -","o":["Thiazide","Triamterene","Spironolactone","Furosemide"],"a":0,"e":"Ans. is ''a'' i.e., Thiazide Thiazide diuretics paradoxically decrease urine output in DI due to formation of cAMP in distal tubules effective in both central and nephrogenic DI.","pyqMatches":[{"year":"2012","no":540,"q":"In diabetes insipidus, diuretic showing paradoxical antiduretic activity","o":["Thiazide","Triamterene","Spironolactone","Furosemide"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7209, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 28, '{"id":7209,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":28,"q":"True regarding Conivaptan is -","o":["Vasopressin Antagonist","V2 selective action","Given orally","All"],"a":0,"e":"Ans. is ''a'' i.e., Vasopressin Antagonist","pyqMatches":[{"year":"2012","no":529,"q":"True regarding Conivaptan is","o":["Vasopressin Antagonist","V2 selective action","Given orally","All"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7210, 'Pharmacology', 'CNS Pharmacology', 'Easy', 'Pharmacology', 29, '{"id":7210,"subject":"Pharmacology","chapter":"CNS Pharmacology","difficulty":"Easy","source":"Pharmacology","sourceNo":29,"q":"5 HT 1 agonists used as ?(","o":["Anti anxiety drugs","Antipsychotic drugs","GERD","Chemotherapy induced vomiting"],"a":0,"e":"Ans. is ''a'' i.e., Anti anxiety drugs 5-HT IA agonists (Buspiron, ipsapirone) act as antianxiety drugs.","pyqMatches":[{"year":"2012","no":531,"q":"5 HT 1 agonists used as ?(","o":["Anti anxiety drugs","Antipsychotic drugs","GERD","Chemotherapy induced vomiting"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7211, 'Pharmacology', 'Miscellaneous', 'Moderate', 'Pharmacology', 30, '{"id":7211,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pharmacology","sourceNo":30,"q":"PGE2 cause all except -","o":["Water retention","Uterine contraction","Flushing","None"],"a":0,"e":"Ans. is ''a'' i.e., Water retention o PGE2 causes increase in water excretion by inhibiting ADH action.","pyqMatches":[{"year":"2012","no":537,"q":"PGE2 cause all except","o":["Water retention","Uterine contraction","Flushing","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7212, 'Pharmacology', 'Miscellaneous', 'Moderate', 'Pharmacology', 31, '{"id":7212,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pharmacology","sourceNo":31,"q":"All are the following are the functions of PGEl except-","o":["Erectile dysfunction","Erectile dysfunction","Induction of puberty","PDA"],"a":2,"e":"Ans. is ''c'' i.e., Induction of puberty","pyqMatches":[{"year":"2013","no":534,"q":"All are the following are the functions of PGEl except","o":["Erectile dysfunction","Erectile dysfunction","Induction of puberty","PDA"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7213, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 32, '{"id":7213,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":32,"q":"Dinoprost is -","o":["PG El","PGE2","PGF2 alpha","PGI2"],"a":2,"e":"Ans. is ''c'' i.e., PG F2 alpha o Dinoprost - PG F2 alpha, intraamniotically for midterm abortion. o Dinoprostone - PG E2, intravaginally for midterm abortion.","pyqMatches":[{"year":"2012","no":538,"q":"Dinoprost is","o":["PG El","PGE2","PGF2 alpha","PGI2"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7214, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 33, '{"id":7214,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":33,"q":"Which enzyme is irreversibly inhibited by aspirin?","o":["Lipooxygenase","Cyclooxygenase","Thromboxane synthase","Phospholipase"],"a":1,"e":"Ans. is ''b'' i.e., Cyclooxygenase","pyqMatches":[{"year":"2012","no":539,"q":"Which enzyme is irreversibly inhibited by aspirin?","o":["Lipooxygenase","Cyclooxygenase","Thromboxane synthase","Phospholipase"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7215, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 34, '{"id":7215,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":34,"q":"Which drug doesn''t include DMARD:","o":["Chloroquine","Vincristine","Azathioprine","Leflunomide"],"a":1,"e":"Ans. is ''b'' i.e., Vincristine o Disease modifying antirheumatic drugs (DMARDs) :?","pyqMatches":[{"year":"2012","no":535,"q":"Which drug doesn''t include DMARD:","o":["Chloroquine","Vincristine","Azathioprine","Leflunomide"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7216, 'Pharmacology', 'Endocrine Pharmacology', 'Easy', 'Pharmacology', 35, '{"id":7216,"subject":"Pharmacology","chapter":"Endocrine Pharmacology","difficulty":"Easy","source":"Pharmacology","sourceNo":35,"q":"Which of the following drugs is useful in acute attack of gout ?","o":["Furosemide","Sulfinpyrazone","Allopurinol","Piroxicam"],"a":3,"e":"Ans. is ''d'' i.e., Piroxicam Drugs used in acute gout i) NSAIDs Drug of choice ii) Colehicine iii) Corticosteroids","pyqMatches":[{"year":"2013","no":1317,"q":"Which of the following drugs is useful in acute attack of gout ?","o":["Furosemide","Sulfinpyrazone","Allopurinol","Piroxicam"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7217, 'Pharmacology', 'Endocrine Pharmacology', 'Easy', 'Pharmacology', 36, '{"id":7217,"subject":"Pharmacology","chapter":"Endocrine Pharmacology","difficulty":"Easy","source":"Pharmacology","sourceNo":36,"q":"Efficacy of salmeterol is increased if it is given along with -","o":["Theophylline","Corticosteroid","Ipratropium","Sodium cromoglycate"],"a":1,"e":"Ans. is ''b'' i.e., Corticosteroid o Concurrent use of inhaled salmeterol with inhaled glucocorticoid produces effects equivalent to double dose of the corticoid alone.","pyqMatches":[{"year":"2012","no":534,"q":"Efficacy of salmeterol is increased if it is given along with","o":["Theophylline","Corticosteroid","Ipratropium","Sodium cromoglycate"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7218, 'Pharmacology', 'Endocrine Pharmacology', 'Easy', 'Pharmacology', 37, '{"id":7218,"subject":"Pharmacology","chapter":"Endocrine Pharmacology","difficulty":"Easy","source":"Pharmacology","sourceNo":37,"q":"Which is an intermediate acting insulin?","o":["Insulin lispro","Regular insuin","NPH insulin","Insulin glargine"],"a":2,"e":"Ans. is ''c'' i.e., NPH insulin","pyqMatches":[{"year":"2012","no":550,"q":"Which is an intermediate acting insulin?","o":["Insulin lispro","Regular insuin","NPH insulin","Insulin glargine"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7219, 'Pharmacology', 'Endocrine Pharmacology', 'Easy', 'Pharmacology', 38, '{"id":7219,"subject":"Pharmacology","chapter":"Endocrine Pharmacology","difficulty":"Easy","source":"Pharmacology","sourceNo":38,"q":"HbA1C is decreased most by?","o":["Biguanides","Sulfonylureas","Thiazolidinediones","Acarbosc"],"a":1,"e":"Ans. is ''b'' i.e., Sulfonylureas Effect of oral hypoglycemic in lowering blood glucose can be measured by reduction in HbAlC level i) Oral hypoglycemic with maximum decrease in HbAlc sulfonylureas. ii)Oral hypoglycemic with minimum decrease in HbAIC Glucosidase inhibitors (Acrarbose, Migital)","pyqMatches":[{"year":"2014","no":606,"q":"HbA1C is decreased most by?","o":["Biguanides","Sulfonylureas","Thiazolidinediones","Acarbosc"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7220, 'Pharmacology', 'Endocrine Pharmacology', 'Easy', 'Pharmacology', 39, '{"id":7220,"subject":"Pharmacology","chapter":"Endocrine Pharmacology","difficulty":"Easy","source":"Pharmacology","sourceNo":39,"q":"Which antidiabetic drug is used both for type I & II DM-","o":["Sulphonylureas","Metformin","Acarbose","Pramlinitide"],"a":3,"e":"Ans. is ''d'' i.e., Pramlinitide o Pramlinide is the only approved drug, beside insulin, to be used in both type-I and type-2 DM.","pyqMatches":[{"year":"2013","no":570,"q":"Which antidiabetic drug is used both for type I & II DM","o":["Sulphonylureas","Metformin","Acarbose","Pramlinitide"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7221, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 40, '{"id":7221,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":40,"q":"Least glucocorticoid action is seen with ?","o":["Fludrocortisone","Cortisone","Dexamethasone","Betamethasone"],"a":1,"e":"Ans. is ''b'' i.e., Cortisone Least potent glucocorticoid —> Cortisone","pyqMatches":[{"year":"2012","no":552,"q":"Least glucocorticoid action is seen with ?","o":["Fludrocortisone","Cortisone","Dexamethasone","Betamethasone"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7222, 'Pharmacology', 'Miscellaneous', 'Moderate', 'Pharmacology', 41, '{"id":7222,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pharmacology","sourceNo":41,"q":"Steroid ingested for long time leads to all of the following except -","o":["Avascular necrosis of head of femur","Cataract","Glaucoma","Growth retardation"],"a":2,"e":"Ans. is ''c'' i.e., Glaucoma Glaucoma occurs after topical therapy (not systemic)","pyqMatches":[{"year":"2012","no":551,"q":"Steroid ingested for long time leads to all of the following except","o":["Avascular necrosis of head of femur","Cataract","Glaucoma","Growth retardation"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7223, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 42, '{"id":7223,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":42,"q":"Which of the following is a synthetic estrogen ?","o":["Estrone","Estriol","Estradiol","Diethylstibestrol"],"a":3,"e":"Ans. is ''d'' i.e., Diethylstibestrol Synthetic progesterones","pyqMatches":[{"year":"2012","no":558,"q":"Which of the following is a synthetic estrogen ?","o":["Estrone","Estriol","Estradiol","Diethylstibestrol"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7224, 'Pharmacology', 'Chemotherapy', 'Easy', 'Pharmacology', 43, '{"id":7224,"subject":"Pharmacology","chapter":"Chemotherapy","difficulty":"Easy","source":"Pharmacology","sourceNo":43,"q":"Which of the following is an aromatase inhibitor?","o":["Tamoxifen","Letrozole","Danazol","Taxane"],"a":1,"e":"Ans. is ''b'' i.e. Letrozole Aromatase inhibitors are of two types o Type I (steroidal) aromatase inhibitor - They cause irreversible inhibition of aromatase, e.g. Exmestane, formestane. o Type II (non- steroidal) aromatase inhibitor - They cause reversible inhibition of aromatasxe e.g. Anastrazole, Letrozole, vorozale.","pyqMatches":[{"year":"2015","no":559,"q":"Which of the following is an aromatase inhibitor?","o":["Tamoxifen","Letrozole","Danazol","Taxane"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7225, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 44, '{"id":7225,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":44,"q":"Which of the following is a selective progesterone receptor modulator-","o":["Onapristone","Ulipristal","Nomegestrol","Toremifene"],"a":1,"e":"Ans. is ''b'' i.e., Ulipristal o Ulipristal is a SPRM approved for use as an Emergency Contraceptive. o SPRM (selective progesterone receptor modulators) : Asoprisnil, ul ipristal, onapristone, mifepristone.","pyqMatches":[{"year":"2012","no":555,"q":"Which of the following is a selective progesterone receptor modulator","o":["Onapristone","Ulipristal","Nomegestrol","Toremifene"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7226, 'Pharmacology', 'Miscellaneous', 'Moderate', 'Pharmacology', 45, '{"id":7226,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pharmacology","sourceNo":45,"q":"Side effect of oxytocin is all except ?","o":["Placental abruption","Fetal distress","Peripheral vascular disease","Water intoxication"],"a":2,"e":"Ans. is ''c'' i.e., Peripheral vascular disease o Side effects of Oxytocin are due to : i) ADH like action - Water intoxication ii) Excessive uterine contractions, prior to labour - Fetal distress, Placental abruption, Uterine rupture.","pyqMatches":[{"year":"2012","no":559,"q":"Side effect of oxytocin is all except ?","o":["Placental abruption","Fetal distress","Peripheral vascular disease","Water intoxication"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7227, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 46, '{"id":7227,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":46,"q":"Short acting non delpolarizing blocker ?","o":["Rocurorium","Suxamethonium","Mivacurium","Pancuronium"],"a":2,"e":"Ans. is ''c'' i.e., Mivacurium","pyqMatches":[{"year":"2012","no":549,"q":"Short acting non delpolarizing blocker ?","o":["Rocurorium","Suxamethonium","Mivacurium","Pancuronium"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7228, 'Pharmacology', 'CNS Pharmacology', 'Easy', 'Pharmacology', 47, '{"id":7228,"subject":"Pharmacology","chapter":"CNS Pharmacology","difficulty":"Easy","source":"Pharmacology","sourceNo":47,"q":"Drug of choice in lignocaine toxicity -","o":["Bretylium","Amiodarone","Isoprenaline","Diazepan"],"a":3,"e":"Ans. is `d'' i.e., Diazepan If lignocaine toxicity is suspected, stop the injection immediately. Ensure adequate oxygenation, whether by face mask or by intubation. Anticonvulsants such as benzodiazepines and barbiturates are the drug of choice for seizure control. o Succinylcholine is sometimes also used to terminate the neuromuscular effects of seizures. If CVS symptoms occur (cardiac depression and hypotension), IV fluid and vasopressor agents may be required. If metabolic acidosis develops, use of sodium bicarbonate can be considered, although, as in other instances of acute metabolic acidosis, this is controversial.","pyqMatches":[{"year":"2013","no":1743,"q":"Drug of choice in lignocaine toxicity","o":["Bretylium","Amiodarone","Isoprenaline","Diazepan"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7229, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 48, '{"id":7229,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":48,"q":"Cardiotoxicity of bupivacaine -","o":["Depressed pacemaker activity","Toxic compound damaging myocardial cells","Depressed neural control on heart","Vascular thrombosis and Myocardial ischemia"],"a":0,"e":"Ans. is ''a'' i.e., Depressed pacemaker activity o Local anaesthetics block cardiac sodium channels and thus depress abnormal cardiac pacemaker activity, excitability, and conduction. At extremely high concentrations, local anaesthetics can also block calcium channels.","pyqMatches":[{"year":"2012","no":548,"q":"Cardiotoxicity of bupivacaine","o":["Depressed pacemaker activity","Toxic compound damaging myocardial cells","Depressed neural control on heart","Vascular thrombosis and Myocardial ischemia"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7230, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 49, '{"id":7230,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":49,"q":"Local anaesthetic injected directly into the tissue ?","o":["Infiltration anaesthesia","Nerve block","Field block","Bier''s block"],"a":0,"e":"Ans. is ''a'' i.e., Infiltration anaesthesia o Infiltration anaesthesia is the injection of local anaesthetic directly into tissue without taking into consideration the course of cutaneous nerve.","pyqMatches":[{"year":"2015","no":1633,"q":"Local anaesthetic injected directly into the tissue ?","o":["Infiltration anaesthesia","Nerve block","Field block","Bier''s block"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7231, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 50, '{"id":7231,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":50,"q":"Which one of the following agents sensitizes the myocardium to catecholamines -","o":["Isoflurane","Ether","Halothane","Propofol"],"a":2,"e":"Ans. is ''c'' i.e., Halothane o Halothane tends to sensitize the heart to arrhythmogenic action of adrenaline - contraindicated in pheochromocytoma.","pyqMatches":[{"year":"2015","no":1619,"q":"Which one of the following agents sensitizes the myocardium to catecholamines","o":["Isoflurane","Ether","Halothane","Propofol"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7232, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 51, '{"id":7232,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":51,"q":"Trilene when used with Sodalime causes ?","o":["Renal damage","ARDS","Myocardial depression","Hepatitis"],"a":1,"e":"Ans. is ''b'' i.e., ARDS o Following agents react with soda lime : Sevoflurane is degraded by contact with CO2 absorbant (soda lime) in anaesthesia machine, yielding a vinyl ether called Compound A which can cause renal damage. Trilene produces phosgene (causing ARDS) and dicholoro acetylene (causes neurotoxicity) when used with sodalime.","pyqMatches":[{"year":"2012","no":547,"q":"Trilene when used with Sodalime causes ?","o":["Renal damage","ARDS","Myocardial depression","Hepatitis"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7233, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 52, '{"id":7233,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":52,"q":"Dissociative anaesthesia is produced by -","o":["Ketamine","Etomidate","Propofol","Thiopentone"],"a":0,"e":"Ans. is ''a'' i.e., Ketamine Dissociative anaesthesia is characterized by profound analgesia, immobility, amnesia with light sleep and feeling of dissociation from once own body and the surroundings Cataleptic state. o Ketamine (phencyclidine) induces dissociative anaesthesia.","pyqMatches":[{"year":"2013","no":1724,"q":"Dissociative anaesthesia is produced by","o":["Ketamine","Etomidate","Propofol","Thiopentone"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7234, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 53, '{"id":7234,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":53,"q":"The drug for OPD analgesia is -","o":["Morphine","Pethidine","Fentanyl","Alfentanil"],"a":3,"e":"Ans. is ''d'' i.e., Alfentanil Drugs useful for day care surgery o Propofol o Sevoflurane, desflurane & isoflurane o Midazolam o Mivacurium o Alfantanil","pyqMatches":[{"year":"2012","no":1410,"q":"The drug for OPD analgesia is","o":["Morphine","Pethidine","Fentanyl","Alfentanil"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7235, 'Pharmacology', 'Respiratory & GI Drugs', 'Easy', 'Pharmacology', 54, '{"id":7235,"subject":"Pharmacology","chapter":"Respiratory & GI Drugs","difficulty":"Easy","source":"Pharmacology","sourceNo":54,"q":"Inducing agent of choice in shock ?","o":["Isoflurane","Desflurane","Ketamine","Thiopentone"],"a":2,"e":"Ans. is ''c'' i.e., Ketamine Inducing agent of choice in Asthma & COPD → Ketamine. Inhalational agent of choice in Asthma & COPD → Halothane.","pyqMatches":[{"year":"2012","no":1403,"q":"Inducing agent of choice in shock ?","o":["Isoflurane","Desflurane","Ketamine","Thiopentone"],"a":2,"source":"NEET_2012_Paper.pdf"},{"year":"2013","no":1725,"q":"Inducing agent of choice in shock ?","o":["Isoflurane","Desflurane","Ketamine","Thiopentone"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2012","2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7236, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 55, '{"id":7236,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":55,"q":"Fosphenytoin different from phenytoin in which of the following-","o":["Can be used in absence seizures","Can be mixed with saline","Can be given orally","It is the drug of choice for myoclonic seizures"],"a":1,"e":"Ans. ''b'' i.e., Can be mixed with saline While phenytoin cannot be injected in a drip of glucose solution, fosphenytoin can be injected with saline and glucose.","pyqMatches":[{"year":"2012","no":525,"q":"Fosphenytoin different from phenytoin in which of the following","o":["Can be used in absence seizures","Can be mixed with saline","Can be given orally","It is the drug of choice for myoclonic seizures"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7237, 'Pharmacology', 'CNS Pharmacology', 'Easy', 'Pharmacology', 56, '{"id":7237,"subject":"Pharmacology","chapter":"CNS Pharmacology","difficulty":"Easy","source":"Pharmacology","sourceNo":56,"q":"Toxic dose of lithium -","o":["0.6","12","2.6","<0.6"],"a":2,"e":"Ans. is ''c'' i.e., 2.6","pyqMatches":[{"year":"2012","no":545,"q":"Toxic dose of lithium","o":["0.6","12","2.6","<0.6"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7238, 'Pharmacology', 'CNS Pharmacology', 'Moderate', 'Pharmacology', 57, '{"id":7238,"subject":"Pharmacology","chapter":"CNS Pharmacology","difficulty":"Moderate","source":"Pharmacology","sourceNo":57,"q":"Lithium causes all except-","o":["Polyuria","Nephropathy","Ebstein''s anomaly","Hyperthyroidism"],"a":3,"e":"Ans. is d i.e., Hyperthyroidism Lithium is known to exacerbate psoriasis and cause acne. It is known to cause Ebstein''s anomaly in children. It also causes thyroid dysfunction, hypothyroidism and not hyperthyroidism. Lithium nephrotoxicity is well known.","pyqMatches":[{"year":"2015","no":546,"q":"Lithium causes all except","o":["Polyuria","Nephropathy","Ebstein''s anomaly","Hyperthyroidism"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7239, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 58, '{"id":7239,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":58,"q":"Which of the following is a selective serotonin & nor epinephrine reuptake inhibitor ?","o":["Fluoxetine","Venlafaxine","Sertaline","Arnoxipine"],"a":1,"e":"Ans. is ''b'' i.e., Venlafaxine o Important SNRIs are :- Venalafaxine, Milnacipram, desvenalafaxine, Duloxetine.","pyqMatches":[{"year":"2012","no":543,"q":"Which of the following is a selective serotonin & nor epinephrine reuptake inhibitor ?","o":["Fluoxetine","Venlafaxine","Sertaline","Arnoxipine"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7240, 'Pharmacology', 'CNS Pharmacology', 'Moderate', 'Pharmacology', 59, '{"id":7240,"subject":"Pharmacology","chapter":"CNS Pharmacology","difficulty":"Moderate","source":"Pharmacology","sourceNo":59,"q":"All of the following are CNS stimulants except?","o":["Amphetamines","Benzodiazepines","Cocaine","Methylphenidate"],"a":1,"e":"Ans. is ''b'' i.e., Benzodiazepines CNS stimulants are amphetamine, methylphenidate, atomoxetine, modafinil, cocaine, pemoline and caffeine.","pyqMatches":[{"year":"2016","no":671,"q":"All of the following are CNS stimulants except?","o":["Amphetamines","Benzodiazepines","Cocaine","Methylphenidate"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7241, 'Pharmacology', 'Antimicrobials', 'Moderate', 'Pharmacology', 60, '{"id":7241,"subject":"Pharmacology","chapter":"Antimicrobials","difficulty":"Moderate","source":"Pharmacology","sourceNo":60,"q":"All of the following have interaction with warfarin except-","o":["Barbiturate","Oral contraceptive","Cephalosporins","Benzodiazepens"],"a":3,"e":"Ans. is ''d'' i.e., Benzodiazepenes","pyqMatches":[{"year":"2012","no":567,"q":"All of the following have interaction with warfarin except","o":["Barbiturate","Oral contraceptive","Cephalosporins","Benzodiazepens"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7242, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 61, '{"id":7242,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":61,"q":"Which prevents plasminogen activators?","o":["Streptokinase","Aminocaproic acid","Reteplase","Clopidogrel"],"a":1,"e":"Ans. is ''b'' i.e., Aminocaproic acid o Epsilon amino caproic acid (EACA) competitively inhibits plasminogen activation.","pyqMatches":[{"year":"2013","no":598,"q":"Which prevents plasminogen activators?","o":["Streptokinase","Aminocaproic acid","Reteplase","Clopidogrel"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7243, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 62, '{"id":7243,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":62,"q":"Clopidogrel mechanism of action -","o":["Thromboxane A2 inhibition","Inhibit ADP mediated cAMP activation","GP IIb/Ina inhibitors","None"],"a":1,"e":"Ans. is ''b'' i.e., Inhibit ADP mediated cAMP activation","pyqMatches":[{"year":"2012","no":568,"q":"Clopidogrel mechanism of action","o":["Thromboxane A2 inhibition","Inhibit ADP mediated cAMP activation","GP IIb/Ina inhibitors","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7244, 'Pharmacology', 'Cardiovascular Drugs', 'Easy', 'Pharmacology', 63, '{"id":7244,"subject":"Pharmacology","chapter":"Cardiovascular Drugs","difficulty":"Easy","source":"Pharmacology","sourceNo":63,"q":"Most potent statin -","o":["Simvastatin","Pravastatin","Rosuvastatin","Simvastatin"],"a":2,"e":"Ans. is ''c'' i.e., Rosuvastatin o Two most potent statins are Pitavastatin (most potent) and rosuvastatin most potent).","pyqMatches":[{"year":"2012","no":563,"q":"Most potent statin","o":["Simvastatin","Pravastatin","Rosuvastatin","Simvastatin"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7245, 'Pharmacology', 'Cardiovascular Drugs', 'Easy', 'Pharmacology', 64, '{"id":7245,"subject":"Pharmacology","chapter":"Cardiovascular Drugs","difficulty":"Easy","source":"Pharmacology","sourceNo":64,"q":"Antilipidemic drugs that prevent hypercholestero​lemia by inhibiting absorption -","o":["Ezetimibe","Orlistat","Cholestyramine","Statins"],"a":0,"e":"Ans. is ''a'' i.e., Ezetimibe Ezetimibe inhibits the absorption of cholesterol by bidning to transporter [NPC-1L1 (Niemann Pick Cl, likel) SR​Bl, 145 KDa] located in intestinal brush border. Note: Orlistat also reduces cholesterol absorption, but it is an anti-obesity drug (not an antilipidemic drug).","pyqMatches":[{"year":"2012","no":561,"q":"Antilipidemic drugs that prevent hypercholestero​lemia by inhibiting absorption","o":["Ezetimibe","Orlistat","Cholestyramine","Statins"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7246, 'Pharmacology', 'Miscellaneous', 'Moderate', 'Pharmacology', 65, '{"id":7246,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pharmacology","sourceNo":65,"q":"Which is not a S/E of Cimetidine ?","o":["Impotence","Gynaecomastia","Atrophic gastritis","Galactorrhea"],"a":2,"e":"Ans. is ''c'' i.e., Atrophic gastritis","pyqMatches":[{"year":"2012","no":560,"q":"Which is not a S/E of Cimetidine ?","o":["Impotence","Gynaecomastia","Atrophic gastritis","Galactorrhea"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7247, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 66, '{"id":7247,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":66,"q":"The commonest side-effect of Cisapride is -","o":["Abdominal cramps","Diarrhea","Headache","Convulsions"],"a":1,"e":"Ans. is ''b'' i.e., Diarrhea Cisapride is a prokinetic agent and often produces loose stools (diarrhea is thus the commonest side effect)","pyqMatches":[{"year":"2014","no":585,"q":"The commonest side-effect of Cisapride is","o":["Abdominal cramps","Diarrhea","Headache","Convulsions"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7248, 'Pharmacology', 'Antimicrobials', 'Moderate', 'Pharmacology', 67, '{"id":7248,"subject":"Pharmacology","chapter":"Antimicrobials","difficulty":"Moderate","source":"Pharmacology","sourceNo":67,"q":"Drug inhibiting bacterial protein synthesis are all except-","o":["Aminoglycosides","Chloramphenicol","Clindamycin","Sulfonamides"],"a":3,"e":"Ans. is `d'' i.e., Sulfonamides o Sulfonamides affect intermediary metabolism by inhibiting folate synthase.","pyqMatches":[{"year":"2012","no":571,"q":"Drug inhibiting bacterial protein synthesis are all except","o":["Aminoglycosides","Chloramphenicol","Clindamycin","Sulfonamides"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7249, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 68, '{"id":7249,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":68,"q":"Multiple drug resistance is transferred through -","o":["Transduction","Transformation","Conjugation","Mutation"],"a":2,"e":"Ans. is ''c'' i.e., Conjugation Resistance to multiple drugs is transmitted by R factor (plasmid) - R factor is transferred from one bacterium to other by conjugation. - Transduction and mutation usually cause resistance to one drug. - Transformation is not involved significantly in drug resistance.","pyqMatches":[{"year":"2015","no":687,"q":"Multiple drug resistance is transferred through","o":["Transduction","Transformation","Conjugation","Mutation"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7250, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 69, '{"id":7250,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":69,"q":"Longest acting sulphonamide is -","o":["Sulfadiazine","Sulphadoxine","Sulfamethoxazole","Sulfamethiazole"],"a":1,"e":"Ans. is ''b'' i.e., Sulfadoxine Sulfadoxine and sulfamethopyrazine are long acting sulfonamides.","pyqMatches":[{"year":"2012","no":572,"q":"Longest acting sulphonamide is","o":["Sulfadiazine","Sulphadoxine","Sulfamethoxazole","Sulfamethiazole"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7251, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 70, '{"id":7251,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":70,"q":"Sulphonamide injection causes decrease in folic acid by?","o":["Competitive inhibition","Non competitive inhibition","Uncompetitive inhibition","Allosteric inhibition"],"a":0,"e":"Ans. is ''a'' i.e., Competitive inhibition Bacteria synthesize their own folic acid of which para aminobenzoic acid (PABA) is a constituent - Sulfonamides, being structural analogues of PABA, inhibit bacterial folate synthase competitively.","pyqMatches":[{"year":"2012","no":579,"q":"Sulphonamide injection causes decrease in folic acid by?","o":["Competitive inhibition","Non competitive inhibition","Uncompetitive inhibition","Allosteric inhibition"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7252, 'Pharmacology', 'Antimicrobials', 'Moderate', 'Pharmacology', 71, '{"id":7252,"subject":"Pharmacology","chapter":"Antimicrobials","difficulty":"Moderate","source":"Pharmacology","sourceNo":71,"q":"All are true about ciprofloxacin except ?","o":["C/I in pregnancy","DNA inhibition","Most potent 1st generation fluoroquinolone","More active at acidic pH"],"a":3,"e":"Ans. is ''d'' i.e., More active at acidic pH Ciprofloxacin is the most potent first generation FQ. o Ciprofloxacin inhibit DNA gyrase and is contraindicated in pregnancy. It is less active at acidic pH.","pyqMatches":[{"year":"2012","no":580,"q":"All are true about ciprofloxacin except ?","o":["C/I in pregnancy","DNA inhibition","Most potent 1st generation fluoroquinolone","More active at acidic pH"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7253, 'Pharmacology', 'Miscellaneous', 'Moderate', 'Pharmacology', 72, '{"id":7253,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pharmacology","sourceNo":72,"q":"Which of the following is not mechanism for resistance to MRSA -","o":["Resistance is chromosomally mediated","Produced mainly by alteration in PBPs","MRSA resistance is absolutely beta-lactamase independent","Intrinsic resistance is known"],"a":2,"e":"Ans. is ''c'' i.e., MRSA resistance is absolutely beta-lactamhhase independent","pyqMatches":[{"year":"2016","no":700,"q":"Which of the following is not mechanism for resistance to MRSA","o":["Resistance is chromosomally mediated","Produced mainly by alteration in PBPs","MRSA resistance is absolutely beta-lactamase independent","Intrinsic resistance is known"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7254, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 73, '{"id":7254,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":73,"q":"Bleeding is seen with the use of -","o":["Cefaloridine","Cefazolin","Moxalactum","Ceftazidime"],"a":2,"e":"Ans. is ''c'' i.e., Moxalactam o Ceftriaxone, cefoperazone, moxalactam & cefamandole can cause hypoprothrmbinemia and bleeding.","pyqMatches":[{"year":"2012","no":578,"q":"Bleeding is seen with the use of","o":["Cefaloridine","Cefazolin","Moxalactum","Ceftazidime"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7255, 'Pharmacology', 'Antimicrobials', 'Easy', 'Pharmacology', 74, '{"id":7255,"subject":"Pharmacology","chapter":"Antimicrobials","difficulty":"Easy","source":"Pharmacology","sourceNo":74,"q":"Widest spectrum aminoglycoside is -","o":["Streptomycin","Amikacin","Framycetin","Netilmicin"],"a":1,"e":"Ans. is ''b'' i.e., Amikacin","pyqMatches":[{"year":"2012","no":573,"q":"Widest spectrum aminoglycoside is","o":["Streptomycin","Amikacin","Framycetin","Netilmicin"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7256, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 75, '{"id":7256,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":75,"q":"Red man syndrome is due to -","o":["Vancomycin","Polymyxin","Rifampicin","Teicoplanin"],"a":0,"e":"Ans. is ''a'' i.e., Vancomycin Vancomycin can cause red men syndrome.","pyqMatches":[{"year":"2012","no":577,"q":"Red man syndrome is due to","o":["Vancomycin","Polymyxin","Rifampicin","Teicoplanin"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7257, 'Pharmacology', 'Miscellaneous', 'Moderate', 'Pharmacology', 76, '{"id":7257,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pharmacology","sourceNo":76,"q":"Not true about clofazamine ?","o":["Used in DLE","Causes ichthyosis and hyperpigmentation","Interferes DNA synthesis","Used in lepra reaction"],"a":0,"e":"Ans. is ''a'' i.e., Used in DLE o Clofazimine interferes with template function of DNA, is used in lepra reaction and can cause icthyosis and hyperpigmentation.","pyqMatches":[{"year":"2013","no":608,"q":"Not true about clofazamine ?","o":["Used in DLE","Causes ichthyosis and hyperpigmentation","Interferes DNA synthesis","Used in lepra reaction"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7258, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 77, '{"id":7258,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":77,"q":"Drug used in hepatitis B infection is -","o":["Entecavir","Astacavir","Zanamivir","Abacavir"],"a":0,"e":"Ans. is ''a'' i.e., Entecavir o Entecavir is the DOC for chronic hepatitis B infection.","pyqMatches":[{"year":"2013","no":610,"q":"Drug used in hepatitis B infection is","o":["Entecavir","Astacavir","Zanamivir","Abacavir"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7259, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 78, '{"id":7259,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":78,"q":"Which of the following antimalarial is a slow acting schizonticide-","o":["Artemether","Mefloquine","Pyrimethamine","Quinine"],"a":2,"e":"Ans. is ''c'' i.e., Pyrimethamine o Antimalarials that act on erythrocytic phase of schizogony are called erythrocytic schizontocides. The available drugs can be divided into ?","pyqMatches":[{"year":"2012","no":576,"q":"Which of the following antimalarial is a slow acting schizonticide","o":["Artemether","Mefloquine","Pyrimethamine","Quinine"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7260, 'Pharmacology', 'Miscellaneous', 'Moderate', 'Pharmacology', 79, '{"id":7260,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pharmacology","sourceNo":79,"q":"Which of the following is not used as treatment for lymphatic filariasis -","o":["Ivermectin","DEC","Praziquantel","Albendazole"],"a":2,"e":"Ans. is ''c'' i.e., Praziquantel o Drugs used in lymphatic filiriasis are DEC, ivermectin, albendazale and doxycycline.","pyqMatches":[{"year":"2012","no":581,"q":"Which of the following is not used as treatment for lymphatic filariasis","o":["Ivermectin","DEC","Praziquantel","Albendazole"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7261, 'Pharmacology', 'Antimicrobials', 'Easy', 'Pharmacology', 80, '{"id":7261,"subject":"Pharmacology","chapter":"Antimicrobials","difficulty":"Easy","source":"Pharmacology","sourceNo":80,"q":"Drug that can cause hypertrophic pyloric stenosis is?","o":["Tertacyclin","Erythromycin","Ampicillin","Rifampicin"],"a":1,"e":"Ans. is ''b'' i.e., Erythromycin o Maternal and infant use of erythromycin and other macrolide antibiotics have been reported as risk factors for infantile hypertrophic pyloric stenosis (IHPS).","pyqMatches":[{"year":"2015","no":606,"q":"Drug that can cause hypertrophic pyloric stenosis is?","o":["Tertacyclin","Erythromycin","Ampicillin","Rifampicin"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7262, 'Pharmacology', 'Chemotherapy', 'Easy', 'Pharmacology', 81, '{"id":7262,"subject":"Pharmacology","chapter":"Chemotherapy","difficulty":"Easy","source":"Pharmacology","sourceNo":81,"q":"Resistance to Methotrexate develops due to?","o":["Rapid Cancer cell multiplication","Deficiency of thymidylate kinase","Deficiency of thymidylate synthetase","Increased production of dihydrofolate reductase"],"a":3,"e":"Ans. is ''d'' i.e., Increased production of dihydrofolate reductase Methotrexate resistance o Methotrexate resistance may be due to any of the following mechanism :? i) Defective transport into cells ii) Production of altered form of DHFR that have decreased affinity for methotrexate iii) Increased concentrations of intracellular DHFR through gene amplification or altered gene regulation iv) Decreased ability to synthesize methotrexate polyglutamates v) Increased expression of a drug efflux transporter, of the MRP (multidrug resistance protein) class","pyqMatches":[{"year":"2012","no":585,"q":"Resistance to Methotrexate develops due to?","o":["Rapid Cancer cell multiplication","Deficiency of thymidylate kinase","Deficiency of thymidylate synthetase","Increased production of dihydrofolate reductase"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7263, 'Pharmacology', 'Chemotherapy', 'Easy', 'Pharmacology', 82, '{"id":7263,"subject":"Pharmacology","chapter":"Chemotherapy","difficulty":"Easy","source":"Pharmacology","sourceNo":82,"q":"Which one of the following statements is false regarding vincristine -","o":["It is an alkaloid","Its use is associated with neurotoxicity","It does not cause alopecia","It is a useful drug for induction of remission in acute lymphoblastic leukaemia"],"a":2,"e":"Ans. is ''c'' i.e., It does not cause alopecia * Vincristine belongs to the plant alkaloid group of anticancer. * Useful for inducing remission in childhood ALL (not useful in maintenance therapy) * It can also be used for pediatric solid tumors (Wilm''s tumor, neuroblastoma, rhabdomyosarcoma) and lymphomas. * Prominent adverse effects? * Peripheral neuropathy Alopecia SIADH","pyqMatches":[{"year":"2013","no":621,"q":"Which one of the following statements is false regarding vincristine","o":["It is an alkaloid","Its use is associated with neurotoxicity","It does not cause alopecia","It is a useful drug for induction of remission in acute lymphoblastic leukaemia"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7264, 'Pharmacology', 'Chemotherapy', 'Easy', 'Pharmacology', 83, '{"id":7264,"subject":"Pharmacology","chapter":"Chemotherapy","difficulty":"Easy","source":"Pharmacology","sourceNo":83,"q":"About vinca alkaloids true is ?","o":["Inhibits mitotic spindle","Enhances polymerization of tubulin","Inhibits topoisomerase I","Inhibits topoisomerase II"],"a":0,"e":"Ans. is ''a'' i.e., Inhibits mitotic spindle Vinca alkaloids (vincristine) inhibit mitotic spindles by preventing polymerization of tubulin","pyqMatches":[{"year":"2012","no":582,"q":"About vinca alkaloids true is ?","o":["Inhibits mitotic spindle","Enhances polymerization of tubulin","Inhibits topoisomerase I","Inhibits topoisomerase II"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7265, 'Pharmacology', 'Miscellaneous', 'Moderate', 'Pharmacology', 84, '{"id":7265,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Pharmacology","sourceNo":84,"q":"All are true regarding Sunitinib except -","o":["It inhibits tyrosine kinase receptors","It is used for renal cell carcinoma","It is used for the treatment of GIST","It is excreted primarily in urine"],"a":3,"e":"Ans. is ''d'' i.e., It is excreted primarily in urine Sunitinib inhibits multiple Tyrosine kinase receptors. It inhibits PDGF, VEGF and c-kit. o Sunitinib and sorafinib are used in renal cell carcinoma (in RCC there is overexpression of VEGF) and GIST (in GIST there is over expression of C-Kit & PDGF). o It is eliminated primarily by hepatic route with excretion in faeces.","pyqMatches":[{"year":"2012","no":587,"q":"All are true regarding Sunitinib except","o":["It inhibits tyrosine kinase receptors","It is used for renal cell carcinoma","It is used for the treatment of GIST","It is excreted primarily in urine"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7266, 'Pharmacology', 'Chemotherapy', 'Moderate', 'Pharmacology', 85, '{"id":7266,"subject":"Pharmacology","chapter":"Chemotherapy","difficulty":"Moderate","source":"Pharmacology","sourceNo":85,"q":"Which of the following Anti neoplastic drugs SHOULD NOT be given by rapid IV infusion?","o":["Cyclophosphamide","Cisplatin","Bleomycin","Cytosine arabinoside"],"a":1,"e":"Ans. is `b '' i.e., Cisplatin o Cisplatin is the most common culprit causing chemotherapy induced nausea and vomiting, therefore cisplatin is given as slow i.v. infusion(never bolus) to prevent vomiting.","pyqMatches":[{"year":"2012","no":583,"q":"Which of the following Anti neoplastic drugs SHOULD NOT be given by rapid IV infusion?","o":["Cyclophosphamide","Cisplatin","Bleomycin","Cytosine arabinoside"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7267, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 86, '{"id":7267,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":86,"q":"Mode of action of azathioprine ?","o":["↑ IL-2","T-cell blockade","Decreased lymphophagocytic activity","Wide-spread antitumor activity"],"a":1,"e":"Ans. is ''b'' i.e., T-cell blockade","pyqMatches":[{"year":"2012","no":584,"q":"Mode of action of azathioprine ?","o":["↑ IL-2","T-cell blockade","Decreased lymphophagocytic activity","Wide-spread antitumor activity"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
