INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (7269, 'Pharmacology', 'Miscellaneous', 'Easy', 'Pharmacology', 88, '{"id":7269,"subject":"Pharmacology","chapter":"Miscellaneous","difficulty":"Easy","source":"Pharmacology","sourceNo":88,"q":"Which of the following drug causes hirsutism?","o":["Phenytoin","Valproate","Carbamazepine","Phenobarbitone"],"a":0,"e":"Ans. is ''a'' i.e., Phenytoin","pyqMatches":[{"year":"2012","no":588,"q":"Which of the following drug causes hirsutism?","o":["Phenytoin","Valproate","Carbamazepine","Phenobarbitone"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
