INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8443, 'Psychiatry', 'Miscellaneous', 'Moderate', 'Psychiatry', 11, '{"id":8443,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Psychiatry","sourceNo":11,"q":"All are true regarding somatization dosorder except:","o":["Maintain sick role","4-Pain symptoms","1-Sexual symptom","1-Pseudo neurological symptom"],"a":0,"e":"A i.e. Maintain sick role","pyqMatches":[{"year":"2012","no":1463,"q":"All are true regarding somatization dosorder except:","o":["Maintain sick role","4-Pain symptoms","1-Sexual symptom","1-Pseudo neurological symptom"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8444, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 12, '{"id":8444,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":12,"q":"La belle indifference is seen in","o":["Conversion Reaction","Schizophrenia","Mania","Depression"],"a":0,"e":"A i.e. Conversion reaction La belle indifferenceQ is in-appropiate attitude of calm or lack of concern about one''s disability. It is seen in conversion (dissociative) disorderQ (but not specific), physical illness etc.","pyqMatches":[{"year":"2014","no":2093,"q":"La belle indifference is seen in","o":["Conversion Reaction","Schizophrenia","Mania","Depression"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8445, 'Psychiatry', 'Miscellaneous', 'Moderate', 'Psychiatry', 13, '{"id":8445,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Psychiatry","sourceNo":13,"q":"Markedly inappropriate sensitivity, self importance and suspiciousness are clinical features of","o":["Aantisocial","Historic","Schizoid","Paranoid"],"a":3,"e":"D i.e. Paranoid P","pyqMatches":[{"year":"2014","no":2078,"q":"Markedly inappropriate sensitivity, self importance and suspiciousness are clinical features of","o":["Aantisocial","Historic","Schizoid","Paranoid"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8446, 'Psychiatry', 'ECT & Biological Treatments', 'Easy', 'Psychiatry', 14, '{"id":8446,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Easy","source":"Psychiatry","sourceNo":14,"q":"Antidepressant drug used in nocturnal eneuresis is:","o":["Imipramine","Fluoxetine","Trazdone","Sertaline"],"a":0,"e":"A i.e. Imipramine Adverse effects ofTCAs l. Anticholinergic - Dry mouth, bad taste, urinary retention, blurred vision, palpitation, constiPation.","pyqMatches":[{"year":"2015","no":549,"q":"Antidepressant drug used in nocturnal eneuresis is:","o":["Imipramine","Fluoxetine","Trazdone","Sertaline"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8447, 'Psychiatry', 'General Psychiatry', 'Moderate', 'Psychiatry', 15, '{"id":8447,"subject":"Psychiatry","chapter":"General Psychiatry","difficulty":"Moderate","source":"Psychiatry","sourceNo":15,"q":"Not a feature of Wernicke''s Korsakoff Syndrome","o":["Ataxia","Psychosis","Normal pupillary response","Opthalmoplegia"],"a":2,"e":"C i.e. Normal pupillary response","pyqMatches":[{"year":"2016","no":1174,"q":"Not a feature of Wernicke''s Korsakoff Syndrome","o":["Ataxia","Psychosis","Normal pupillary response","Opthalmoplegia"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8448, 'Psychiatry', 'General Psychiatry', 'Easy', 'Psychiatry', 16, '{"id":8448,"subject":"Psychiatry","chapter":"General Psychiatry","difficulty":"Easy","source":"Psychiatry","sourceNo":16,"q":"The site of lesion in Korsakoff''s psychosis is","o":["Frontal lobe","Corpus striatum","Mammilary Body","Cingulate gyrus"],"a":2,"e":"C i.e. Mammilary body","pyqMatches":[{"year":"2015","no":1681,"q":"The site of lesion in Korsakoff''s psychosis is","o":["Frontal lobe","Corpus striatum","Mammilary Body","Cingulate gyrus"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8449, 'Psychiatry', 'General Psychiatry', 'Moderate', 'Psychiatry', 17, '{"id":8449,"subject":"Psychiatry","chapter":"General Psychiatry","difficulty":"Moderate","source":"Psychiatry","sourceNo":17,"q":"Not involved in Wernicke - Korsakoff syndrome:","o":["Mammilary body","Thalamus","Periventricular grey matter","Hippocampus"],"a":2,"e":"C i.e. Periventricular grey matter Korsakoff''s Psychosis (K P) It is the commonest cause of organic amnestic syndrome. It is also k/ a Wernicke - Korsakov syndrome, because it often follows an acute neurological syndrome called Wernicke''s encephalopathy comprising delirium, ataxia, opthalmoplegia, nystagmus & peripheral neuropathy. It is a potentially reversible conditionQ caused by thiamine deficiency most commonly associated with chronic alcohol abuse malnutrition. But other causes of malnutrition eg. starvation, hyperemesis gravidarum, dialysis, cancer, AIDS, gastric plication or prolonged IV hyperalimentation, alone can also result in thiamine deficiency & KP. Neuropathological lesion caused by thiamine deficiency is usually widespread but most consistent changes are seen in bilateral dorsomedial (& anterior) nucleus of thalamus, mammillary bodies, and hippocampus, in form of small vessels hyperplasia; petechial hemorrhages, astrocytic hypertrophy & degenerationQ. It disrupts a critical circuit between hippocampus & frontal lobes. The changes are also seen in periventricular (around 3rd ventricle), periaqueductal grey matter, cerebellum, and brain stem (midbrain, pons, medulla fornix) as symmetrical lesions. The cardinal feature is a profound deficit of episodic memory, confabulation and lack of insight into the amnesiaQ. It presents as : Change in personality (frontal lobe like) such that they display lack of initiative, interest or concern & diminished spontaneity. - Executive function deficits involving attention, planning, set shifting, & inferential reasoning. - Apathy, passivity & confabulationQ are often prominent. There is disorientation for time, emotional blunting, & inertia. - There is little impairment in implicit memory and their ability to perform (complete) complex motor procedures remain intactQ. Typically general intelligence, perceptual skills & language remain relatively normalQ. Memory disorder - Profound deficit of episodic type explicit (declarative) memory 1/t loss of autobiographic information (often extending back for many years). Severe anterograde amnesia (learning defect) for verbal & visual material with a lack of insight into the amnesia. Events are recalled immediately after they occur, but forgotten a few minutes later. Thus digit span, testing the short term memory store, is normal. Storage is mildly impaired but retrieval & learning are severely impairedQ. When patients learn new material they will forget it at a normal rate, but learning the new material is extremely difficult, and in severe cases new learning is impossible. So these patients have difficult encoding & consolidating explicit memory. - Retrograde amnesia back to the onset of illness, is as severe as anterograde loss; but the overall retrograde memory impairment (i.e. before the onset of illness) is not as severe as that of anterograde memory. New learning & recent memory is grossly defective but retrograde (remote) memory is relatively (variably) preserved, and show a temporal gradient, with older memories better preserved. As a result these patients retain more distant memories dramatically more proficiently than they learn new material. - Although remote memory is surprisingly intact, patients are unable to organize them in a temporal context. So they distort the relationship between facts and fill the remote memory gaps by confabulationQ (a vivid & wholly fictitious account of recent activities which the patient believes to be true).","pyqMatches":[{"year":"2014","no":2112,"q":"Not involved in Wernicke - Korsakoff syndrome:","o":["Mammilary body","Thalamus","Periventricular grey matter","Hippocampus"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8450, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 18, '{"id":8450,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":18,"q":"Most common cause dementia in adult:","o":["Alzheimer''s","Multiinfrct","Pick'' disease","Metabolic cause"],"a":0,"e":"A i.e. Alzheimer''s","pyqMatches":[{"year":"2014","no":2104,"q":"Most common cause dementia in adult:","o":["Alzheimer''s","Multiinfrct","Pick'' disease","Metabolic cause"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8451, 'Psychiatry', 'ECT & Biological Treatments', 'Moderate', 'Psychiatry', 19, '{"id":8451,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Moderate","source":"Psychiatry","sourceNo":19,"q":"In Alzheimer''s disease (AD) which of the following is not seen:","o":["Aphasia","Acalculia","Agnosia","Apraxia"],"a":2,"e":"Ans. None > C. Agnosia tRej. Kaplan anal Jaadock s Synopsis of Psychiatry 10/c pi-t? Aphasia, Apraxia, Acalculia and Agnosia may all be seen in Alzheimer''s Dementia. Agnosia in Alzheimer''s disease usually presents late in the disease and is not included in the ICD-10 Diagnostic criteria for dementia in Alzheimer''s disease with early onset and hence may be selected as the single best answer by exclusion","pyqMatches":[{"year":"2015","no":1169,"q":"In Alzheimer''s disease (AD) which of the following is not seen:","o":["Aphasia","Acalculia","Agnosia","Apraxia"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8452, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 20, '{"id":8452,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":20,"q":"Mania is characterized by:","o":["Paranoid delusion","Loss of orientation","High self esteem","All"],"a":2,"e":"C i.e. High self esteem","pyqMatches":[{"year":"2014","no":2115,"q":"Mania is characterized by:","o":["Paranoid delusion","Loss of orientation","High self esteem","All"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8453, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 21, '{"id":8453,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":21,"q":"Lithium is treatment of choice for","o":["Unipolar MDP prophylaxis","Bipolar MDP prophylaxis","Schizophrenia","Acute mania"],"a":1,"e":"B i.e. Bipolar MDP prophylaxis Lithium: Indications: Established indications: Treatment of acute mania Prophylaxis of bipolar mood disorder. Possible clinical indications: Treatment of the schizo-affective disorder Prophylaxis of unipolar mood ilisorder treatment of cyclothymia Treatment if acute depression(as an adjuvant for refractory depression) Treatment of chronic akoholism(in presence of significant depressive symptoms) 6 psychoactive use disorders(e''g cocaine dePendence) Treatment of impulsive aggression. Treatment of Keine-Levin syndrome","pyqMatches":[{"year":"2014","no":2110,"q":"Lithium is treatment of choice for","o":["Unipolar MDP prophylaxis","Bipolar MDP prophylaxis","Schizophrenia","Acute mania"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8454, 'Psychiatry', 'Schizophrenia & Psychosis', 'Moderate', 'Psychiatry', 22, '{"id":8454,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Moderate","source":"Psychiatry","sourceNo":22,"q":"Features like increased psychomotor acitivity, waxy flexinbility at time are seen classically in :","o":["Simple schizophrenia","Hebephrenic schizophrenia","Catatonic schizophrenia","None of the above"],"a":2,"e":"C. i.e. Catatonic schizophrenia","pyqMatches":[{"year":"2015","no":1691,"q":"Features like increased psychomotor acitivity, waxy flexinbility at time are seen classically in :","o":["Simple schizophrenia","Hebephrenic schizophrenia","Catatonic schizophrenia","None of the above"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8455, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 23, '{"id":8455,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":23,"q":"Post traumatic stress disorder (PTSD) is differentiated from all other disorders by:","o":["Nightmares about events","Autonomic arrousal and anxiety","Recall of events and avoidance of similar experiences in PTSD","Depression"],"a":2,"e":"C i.e. Recall of events and avoidance of similar experiences in PTSD - PTSD arises as response to traumatic event (criteria A) that is characterized by persistent re-experience (criteria B), persistent avoidance and numbness (C), hyperarousal (D), of > 1 month duration (criteria E) causing significant distress & impaired functioning (criteria F)Q. The onset may be delayed (6 months to years after event). - PTSD arises as a delayed/protracted response to an exceptionally stressful or catastrophic life event or situation which is likely to cause pervasive distress in almost any person (eg. disaster, war, rape, torture, serious accident). It may develop even after 6 months to years after stressorQ. - PTSD is characterized by peristent/recurrent intrusive distressing recollections of stressful event either in flashbacks (images, thoughts or perceptions), dreams, reliving experiences, illusions, hallucinations or distress/ physiological reactivity on exposure to reminders of traumatic events. There is marked (persistent) avoidance of stimuli/events or situations that arouse recollection of stressful events and increased arousal (hyperarousal) and numbing of general responsivenessQ. Partial amnesia for some aspects of stressful events, anhedonia (inability to experience pleasure) and alexithymia (characterized by inability to identify & articulate feelings) may be present.","pyqMatches":[{"year":"2014","no":2084,"q":"Post traumatic stress disorder (PTSD) is differentiated from all other disorders by:","o":["Nightmares about events","Autonomic arrousal and anxiety","Recall of events and avoidance of similar experiences in PTSD","Depression"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8456, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 24, '{"id":8456,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":24,"q":"Catatonia is a type of: September 2007","o":["Schizophrenia","Phobia","Depression","OCD"],"a":0,"e":"Ans. A: Schizophrenia Schizophrenia is a severe, persistent, debilitating, and poorly understood psychiatric disorder that probably consists of several separate illnesses. Symptoms include disturbances in thoughts (or cognitions), mood (or affects), perceptions, and relationships with others. The hallmark symptoms of schizophrenia are auditory hallucinations and delusions, which are fixed false beliefs. The symptoms of schizophrenia may be divided into the following 4 domains: Positive symptoms: These include psychotic symptoms, such as hallucinations, which are usually auditory; delusions; and disorganized speech and behavior. Negative symptoms: These include a decrease in emotional range, poverty of speech, loss of interests, and loss of drive. Cognitive symptoms: These include neurocognitive deficits, such as deficits in working memory and attention and executive functions such as the ability to organize and abstract. Mood symptoms: Schizophrenia patients often seem cheerful or sad in a way that does not make sense to others. They often are depressed. Catatonia Schizophrenia This syndrome occurs in children, adolescents, and adults; is associated with a heterogeneous group of comorbid conditions; and is characterized by a variety of symptoms and signs of impairment of the expression of voluntary thoughts and movements. Typically, the syndrome of catatonia is episodic, with periods of remission. It can presents in three clinical forms: Excited catatonia Stuporous catatonia Catatonia alternating between excitement and stupor.","pyqMatches":[{"year":"2014","no":2085,"q":"Catatonia is a type of: September 2007","o":["Schizophrenia","Phobia","Depression","OCD"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8457, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 25, '{"id":8457,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":25,"q":"Suicidal tendencies are most commonly seen in: March 2003","o":["Female","Younger age","Severe depression","All of the above"],"a":2,"e":"Ans. C i.e. Severe depression","pyqMatches":[{"year":"2012","no":1457,"q":"Suicidal tendencies are most commonly seen in: March 2003","o":["Female","Younger age","Severe depression","All of the above"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8458, 'Psychiatry', 'ECT & Biological Treatments', 'Easy', 'Psychiatry', 26, '{"id":8458,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Easy","source":"Psychiatry","sourceNo":26,"q":"Sexual stimulation obtained through some inanimate object is known as: September 2003","o":["Transvestism","Fetichism","Voyeurism","Zoophilia"],"a":1,"e":"Ans. B i.e. Fetichism","pyqMatches":[{"year":"2016","no":658,"q":"Sexual stimulation obtained through some inanimate object is known as: September 2003","o":["Transvestism","Fetichism","Voyeurism","Zoophilia"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8459, 'Psychiatry', 'Schizophrenia & Psychosis', 'Moderate', 'Psychiatry', 27, '{"id":8459,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Moderate","source":"Psychiatry","sourceNo":27,"q":"All of the following are formal thought disorder EXCEPT: March 2013 (b, c, h)","o":["Schizophrenia","Delusion","Loosening of association","Mania"],"a":1,"e":"Ans. B i.e. Delusion Delusion is a disorder of thought content (NOT a formal thought disorder/disorder of thought process) Delusion Disorder of thought; False unshaken belief not amenable to reasoning Hallucination Disorder of perception; Perception in the absence of external stimuli; Not dependent of will of observer Illusion Misinterpretation of external stimuli","pyqMatches":[{"year":"2014","no":2074,"q":"All of the following are formal thought disorder EXCEPT: March 2013 (b, c, h)","o":["Schizophrenia","Delusion","Loosening of association","Mania"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8460, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 28, '{"id":8460,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":28,"q":"Illusion is: September 2007","o":["A false unshaken belief not keeping one''s sociao​cultural background","Perception without stimuli","Abnormal perception by a sensory misinterpretation of actual stimulus","Fear of closed spaces"],"a":2,"e":"Ans. C: Abnormal perception by a sensory misinterpretation of actual stimulus Illusion is an abnormal perception caused by a sensory misinterpretation of actual stimulus, sometimes precipitated by strong emotion, e.g. fear provoking a person to imagine they have seen an intruder in the shadows.","pyqMatches":[{"year":"2015","no":1675,"q":"Illusion is: September 2007","o":["A false unshaken belief not keeping one''s sociao​cultural background","Perception without stimuli","Abnormal perception by a sensory misinterpretation of actual stimulus","Fear of closed spaces"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8461, 'Psychiatry', 'Miscellaneous', 'Moderate', 'Psychiatry', 29, '{"id":8461,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Psychiatry","sourceNo":29,"q":"Which of the following is not associated with dementia: March 2011","o":["Forgetfulness","Alteration of consciousness","Reduced personal care","Loss of neurons in brain"],"a":1,"e":"Ans. B: Alteration of consciousness There is impairment of judgement and impulse control, and also impairment of abstract thinking There is however usually no impairment of consciousness in dementia (unlike in delirium) Dementia: Chronic onset No disturbance of consciousness Cognitive impairment Personality alteration Impaired memory Impaired judgment Absent diurnal variation","pyqMatches":[{"year":"2015","no":1684,"q":"Which of the following is not associated with dementia: March 2011","o":["Forgetfulness","Alteration of consciousness","Reduced personal care","Loss of neurons in brain"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8462, 'Psychiatry', 'Child & Adolescent Psychiatry', 'Easy', 'Psychiatry', 30, '{"id":8462,"subject":"Psychiatry","chapter":"Child & Adolescent Psychiatry","difficulty":"Easy","source":"Psychiatry","sourceNo":30,"q":"According to Wechsler intelligence scale scoring, average IQ of a normal child is:","o":["50","75","90","111"],"a":2,"e":"Ans. c. 90","pyqMatches":[{"year":"2015","no":1367,"q":"According to Wechsler intelligence scale scoring, average IQ of a normal child is:","o":["50","75","90","111"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8463, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 31, '{"id":8463,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":31,"q":"Well dressed man came for feeling of women trapped in man body is suffering from ?","o":["Paraphilia","Transverium","Gender identity disorder","Protterurism"],"a":2,"e":"Ans. is ''c'' i.e., Gender identity disorder Gender identity disorder These disorders are characterized by disturbance in gender identity, i.e., the sense of one''s masculinity or faminity is disturbed. Gender identity disorders has following two characteristics : ?","pyqMatches":[{"year":"2013","no":1793,"q":"Well dressed man came for feeling of women trapped in man body is suffering from ?","o":["Paraphilia","Transverium","Gender identity disorder","Protterurism"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8464, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 32, '{"id":8464,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":32,"q":"Folie-a-deux means ?","o":["Delusion of persecution","Sharing of delusion","Delusion of double","None"],"a":1,"e":"Ans. is ''b'' i.e., Sharing of delusion It is also known as shared psychotic disorder or symbiotic psychosis. It is characterized by sharing of delusions between two person (Folie a deux) or rarely between more individuals (Folie a trois, Folie a quatre, Folie a famine). There is a dominant (active) person who induces delusions into the other (passive receptor or dependent person) -4 Dependent person accepts the delusion of dominant person. On separation of two, dependent person may give up his delusions, however the active (dominant) person often requires treatment","pyqMatches":[{"year":"2013","no":1829,"q":"Folie-a-deux means ?","o":["Delusion of persecution","Sharing of delusion","Delusion of double","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8465, 'Psychiatry', 'Miscellaneous', 'Moderate', 'Psychiatry', 33, '{"id":8465,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Psychiatry","sourceNo":33,"q":"REM sleep is associated with all except ?","o":["Dreams","Delta waves","Loss of muscle tone","Increased BP"],"a":1,"e":"Ans. is ''b'' i.e., Delta wave Stages of Sleep Sleep is basically divided into two phases : ? Non-REM (NREM) or slow-wave sleep : - It is called Non-REM sleep because no rapid eye movement (REM) is there on eletrooculogram, rather there is slow or quiscent eye movement. It is also referred as S-sleep (synchronized sleep) or quiet sleep or orthodox sleep because there diminished physiological functions and a low level of overall activity. It is further divided into : ?","pyqMatches":[{"year":"2013","no":1850,"q":"REM sleep is associated with all except ?","o":["Dreams","Delta waves","Loss of muscle tone","Increased BP"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8466, 'Psychiatry', 'General Psychiatry', 'Hard', 'Psychiatry', 34, '{"id":8466,"subject":"Psychiatry","chapter":"General Psychiatry","difficulty":"Hard","source":"Psychiatry","sourceNo":34,"q":"For diagnosis of mania symptoms should be-","o":["> 1 week","> 3 weeks",">2 week","> 4 weeks"],"a":0,"e":"Ans. is ''a'' i.e., > 1 Week Diagnostic criteria for Mania Three or more of the following for at least 1 week : -","pyqMatches":[{"year":"2013","no":1824,"q":"For diagnosis of mania symptoms should be","o":["> 1 week","> 3 weeks",">2 week","> 4 weeks"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8467, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 35, '{"id":8467,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":35,"q":"Acute and transient psychotic disorder, onset of symptoms ?","o":["< 1 weeks","< 2 weeks","< 3 weeks","< 4 weeks"],"a":1,"e":"Ans. is ''b'' i.e., < 2 weeks Acute and transient psychotic disorder These psychotic disorders are characterized by an abrupt (less than 48 hours) or an acute (Less than 2 weeks) onset of symptoms. Three types have been recognized (according to ICD-10).","pyqMatches":[{"year":"2013","no":1833,"q":"Acute and transient psychotic disorder, onset of symptoms ?","o":["< 1 weeks","< 2 weeks","< 3 weeks","< 4 weeks"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8468, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 36, '{"id":8468,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":36,"q":"Ataxia abasia is seen in ?","o":["Conversion disorder","PTSD","Depression","Manic"],"a":0,"e":"Ans. is ''a'' i.e., Conversion disorder Symptoms of conversion disorder Sensory symptoms (in ICD -10 dissociative anesthesia & Sensory loss): - Anaesthesia andparesthesia are common, especially of extremities. All sensory modilities (Pain, temperature, touch, proprioception) are affected at same level, and the disturbance is not consistent to the distribution of dermatomes. Thus, clinicians may see the characteristic glove and stocking anaesthesia of hands or feet or hemianesthesia of body beginning precisely along the midline. Deafness, blindness or contracted visual fields (tubular or tunnel vision). Motor symptoms (In ICD-10 Dissociative motor disorder) : - Abnormal movement, paralysis, Weakness, gait disturbances (ataxia-abasia), Aphonia, Torticollis, Opisthotonus, blepherospasm. Seizure symptoms (In ICD-10 Dissociative convulsions) : - Earlier known as hysterical fits or pseudoseizures, dissociative convulsions are characterized by convulsive movements and partial loss of consciousness. Dissociative convulsions should be differentiated from true convulsions : -","pyqMatches":[{"year":"2013","no":1839,"q":"Ataxia abasia is seen in ?","o":["Conversion disorder","PTSD","Depression","Manic"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8469, 'Psychiatry', 'General Psychiatry', 'Moderate', 'Psychiatry', 37, '{"id":8469,"subject":"Psychiatry","chapter":"General Psychiatry","difficulty":"Moderate","source":"Psychiatry","sourceNo":37,"q":"True about anorexia nervosa is all except ?","o":["Binge eating is common","Unknown in male","Ammenorrhoea starts before severe loss of weight","Self-induced vomiting"],"a":1,"e":"Ans. is ''b'' i.e., Unknown in male Anorexia nervosa is less common in male, but can be seen. There is binge eating and self induced vomiting. \"Amenorrhea often precedes severe weight loss\" – Essentials of psychiatry ANOREXIA NERVOSA The term ''`anorexia nervosa\" is a misnomer as loss of appetite is a rare symptom. This disorder is characterized by self imposed dietary restrictions leading to malnutrition and severe weight loss. Clinical features Females are far more commonly affected than males. Onset usually occurs between the age of 10-30 years, usually in mid adolescence. A deliberate and persistent restriction of food is usually the earliest presenting symptom. There is intense fear of becoming of obese, even if body becomes very thin and underweight. There is a body-image disturbance. The person is unable to perceive the body size accurately. Some patients cannot continuously control their voluntary restriction of food intake and So have eating binges. These binges usually occur secretly and often at night and are frequently followed by self- induced vomiting. Patients abuse laxatives and even diuretics to lose weight, and ritualistic exercising, extensive cycling, walking, jogging and running are common activities. Patients with anorexia nervosa exhibit peculiar behavior about food. They hide food all over the house, frequently carry large quantities of candies in their pockets and purses. They try to dispose of food in their napkins or hide in their pockets, while eating meals. They cut their meat into very small pieces and spend a great deal of time rearranging the pieces on their plates. There is significant weight loss and patient is underweight. Amenorrhea is seen in almost all women and loss of libido may occur in male patients. There may be poor sexual adjustment. Obsessive compulsive neurosis, depression and anxiety like psychiatric illness may coexist. Complications of malnutrition may occur, e.g., hypoglycemia, hypothermia, low BP, bradycardia, leucopenia, endocrine changes (raised GH and Cortisol, reduced gonadotrophin), and appearance of lanugo hair.","pyqMatches":[{"year":"2014","no":2102,"q":"True about anorexia nervosa is all except ?","o":["Binge eating is common","Unknown in male","Ammenorrhoea starts before severe loss of weight","Self-induced vomiting"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8470, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 38, '{"id":8470,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":38,"q":"Loosening of association is an example of","o":["Formal thought disorder","Schneider''s first symptoms","Perseveration","Concrete thinking"],"a":0,"e":"Ans. is ''a'' i.e., Formal thought disorder Thought disorders Formal thought disorders (Disorders of thought process) Disorders of thought process Racing thoughts :- Anxiety, Schizophrenia Retarded thoughts :- Depression Circumstantiality :- Mania, Schizophrenia Thought blocking :- Schizophrenia, Severe anxiety Perseveration :- Organic brain disease, Schizophrenia (occasionally Loosening of association :- Delusion :- Psychosis (Schizophrenia mania, depression & others Obsession Compulsion Preoccupations Phobias Depersonalization & Derealization Schizophrenia Flight of ideas :- Mania Tangentiality Clunging & punning :- Mania & schizophrenia Neologism, word salad, Echolalia :- Schizophrenia In schizophrenia and mood disorders (depression, mania) all parts of the thought (thought process as well as content) are involved. However, schizophrenia is conventionally referred as formal thought disorder.","pyqMatches":[{"year":"2015","no":1697,"q":"Loosening of association is an example of","o":["Formal thought disorder","Schneider''s first symptoms","Perseveration","Concrete thinking"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8471, 'Psychiatry', 'Substance Use Disorders', 'Easy', 'Psychiatry', 39, '{"id":8471,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":39,"q":"False regarding delirium tremens ?","o":["Tremors","Opthalmoplegia","Visual hallucination","Clouding of consciousness"],"a":1,"e":"Ans. is ''b'' i.e., Ophthalmoplegia Delirium tremens Delirium tremens is the most severe alcohol withdrawal syndrome. It occurs usually within 2-4 days of complete or significant alcohol abstinence. This is an acute organic brain syndrome (delirium) with characteristic features of delirium.","pyqMatches":[{"year":"2013","no":1803,"q":"False regarding delirium tremens ?","o":["Tremors","Opthalmoplegia","Visual hallucination","Clouding of consciousness"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8472, 'Psychiatry', 'ECT & Biological Treatments', 'Moderate', 'Psychiatry', 40, '{"id":8472,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Moderate","source":"Psychiatry","sourceNo":40,"q":"Not used for erectile dysfunction ?","o":["Beta blockers","Siledenafil","PG-E,","Papaverine"],"a":0,"e":"Ans. is ''a'' i.e., Beta blockers Drugs used for erectile dysfunction","pyqMatches":[{"year":"2013","no":1835,"q":"Not used for erectile dysfunction ?","o":["Beta blockers","Siledenafil","PG-E,","Papaverine"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8473, 'Psychiatry', 'Anxiety & Related Disorders', 'Easy', 'Psychiatry', 41, '{"id":8473,"subject":"Psychiatry","chapter":"Anxiety & Related Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":41,"q":"A student unable to deliver speech beforeaudience is suffering from ?","o":["Social phobia","OCD","Agoraphobia","Claustrophobia"],"a":0,"e":"Ans. is ''a'' i.e., Social phobia Phobic disorders Phobia is persistent and morbid fear of specific situation, object or activity. The fear is morbid because : ?","pyqMatches":[{"year":"2013","no":1838,"q":"A student unable to deliver speech beforeaudience is suffering from ?","o":["Social phobia","OCD","Agoraphobia","Claustrophobia"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8474, 'Psychiatry', 'Substance Use Disorders', 'Easy', 'Psychiatry', 42, '{"id":8474,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":42,"q":"Suicide is most common in ?","o":["Depression","Alcohol dependence","Dementia","Schizophrenia"],"a":0,"e":"Ans. is ''a'' i.e., Depression Causes/Risk factors for suicide Psychiatric disorders : - Depression (most common), alcoholism (2nd mc), Drug/Substance dependence, Schizophrenia, Dementia. Physical illness : - Cancer, AIDS, Multiple sclerosis, Head trauma. Psychosocial factors : - Failure in love, marital difficulties, family dispute, illegitimate pregnancy. Biological factors : - Decrease in serotonin Other - Male sex, Age > 40 years, Single (Unmarried, divorced or widowed), previous suicide attempt, social isolation.","pyqMatches":[{"year":"2013","no":1828,"q":"Suicide is most common in ?","o":["Depression","Alcohol dependence","Dementia","Schizophrenia"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8475, 'Psychiatry', 'Substance Use Disorders', 'Easy', 'Psychiatry', 43, '{"id":8475,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":43,"q":"Which of the following can cause delirium ?","o":["Hypoxia","Barbiturates","Alcohol withdrawal","All of the above"],"a":0,"e":"Ans. is `d'' i.e., All of the above Important causes of delirium","pyqMatches":[{"year":"2013","no":1800,"q":"Which of the following can cause delirium ?","o":["Hypoxia","Barbiturates","Alcohol withdrawal","All of the above"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8476, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 44, '{"id":8476,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":44,"q":"Total score in Mini Mental Status Examination (MMSE) is ?","o":["25","30","32","35"],"a":1,"e":"Ans. is ''b'' i.e., 30","pyqMatches":[{"year":"2013","no":1801,"q":"Total score in Mini Mental Status Examination (MMSE) is ?","o":["25","30","32","35"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8477, 'Psychiatry', 'Mood Disorders', 'Moderate', 'Psychiatry', 45, '{"id":8477,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Moderate","source":"Psychiatry","sourceNo":45,"q":"18 year old girl with circumscribed bald patch with no organic disease & no behavioural disorder has ?","o":["Depression","Trichotillomania","OCD","Phobia"],"a":1,"e":"Ans. is ''b'' i.e., Trichotillomania As there is no organic or behavioral disorders, this girl is suffering with impulse control disorder of compulsive hair pulling, known as Trichotillomania. Impulse control disorder These disorders are characterized by failure to resist an impulsive behavior that may be harmful to self or others. There may be a feeling of release of tension by doing the act and a feeling of guilt after the act is over. Important impulse control disorder are : -","pyqMatches":[{"year":"2013","no":1847,"q":"18 year old girl with circumscribed bald patch with no organic disease & no behavioural disorder has ?","o":["Depression","Trichotillomania","OCD","Phobia"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8478, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 46, '{"id":8478,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":46,"q":"Pyromania refers to an irresistible urge to ?","o":["Set things on fire","Eat out of proportion","Sleep for long periods","None"],"a":0,"e":"Ans. is ''a'' i.e., Set things on fire","pyqMatches":[{"year":"2013","no":1849,"q":"Pyromania refers to an irresistible urge to ?","o":["Set things on fire","Eat out of proportion","Sleep for long periods","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8479, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 47, '{"id":8479,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":47,"q":"The deliusion which involves replacement of a familiar person by someone else is ?","o":["Capgras syndrome","Cotard syndrome","Othello syndrome","None"],"a":0,"e":"Ans. is ''a'' i.e., Capgras syndrome DSM is characterized by misidentification delusions of other or self. Four main syndromes are differentiated : ?","pyqMatches":[{"year":"2013","no":1831,"q":"The deliusion which involves replacement of a familiar person by someone else is ?","o":["Capgras syndrome","Cotard syndrome","Othello syndrome","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8480, 'Psychiatry', 'Substance Use Disorders', 'Moderate', 'Psychiatry', 48, '{"id":8480,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Moderate","source":"Psychiatry","sourceNo":48,"q":"In personality disorder, features are all except","o":["Ego dystonia","Starts in childhood","Behavior is maladaptive","Disorder results in personal distress"],"a":0,"e":"Ans. ''A'' i.e., Ego dystonia Features of personality disorders Most often the first sign of a personality disorder appears in late childhood or adolescence and continues during adulthood. Someone with a personality disorder holds attitudes and behaves in ways that can cause considerable problems for themselves and others. Behaviour is long-standing (not limited to an episode of mental illness). Behaviour is pervasive and maladaptive. Disorder results in personal distress and social or occupational dysfunction. Behavior is fixed and inflexible. Personality disorders are ego-syntonic. They are not due to a direct result of disease or substance.","pyqMatches":[{"year":"2013","no":1841,"q":"In personality disorder, features are all except","o":["Ego dystonia","Starts in childhood","Behavior is maladaptive","Disorder results in personal distress"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8481, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 49, '{"id":8481,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":49,"q":"Sleep walking is seen in which stage of sleep ?","o":["REM","Stage 1-2 NREM","Stage 2-3 NREM","Stage 3-4 NREM"],"a":3,"e":"Ans. is ''d'' i.e., Stage 3-4 NREM Important events occuring during sleep Deep sleep/slow wave sleep disorder : - These events occur during stage 3 & 4 of NREM. Important disorders are : ?","pyqMatches":[{"year":"2013","no":1851,"q":"Sleep walking is seen in which stage of sleep ?","o":["REM","Stage 1-2 NREM","Stage 2-3 NREM","Stage 3-4 NREM"],"a":3,"source":"NEET_2013_Paper.pdf"},{"year":"2015","no":193,"q":"Sleep walking is seen in which stage of sleep ?","o":["REM","Stage 1-2 NREM","Stage 2-3 NREM","Stage 3-4 NREM"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2013","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8482, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 50, '{"id":8482,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":50,"q":"Quod Hanc means ?","o":["Passive partner in sexual intercourse","Women having high sexual desire","Sexual parterner in pedophilia","Male impotent to particular women"],"a":3,"e":"Ans. is ''d'' i.e., Male impotent to particular women","pyqMatches":[{"year":"2013","no":705,"q":"Quod Hanc means ?","o":["Passive partner in sexual intercourse","Women having high sexual desire","Sexual parterner in pedophilia","Male impotent to particular women"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8483, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 51, '{"id":8483,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":51,"q":"Pagophagia involves eating ?","o":["Ice","Sand","Clay","Salt"],"a":0,"e":"Ans. is ''a'' i.e., Ice Geophagia Eating clay Pagophagia Eating ice Plambophagia Eating lead Amylophagia Eating starch Coprophagia Eating feces Cautopyreiophagia Eating burnt matches Tricophagia Eating hair Lithophagia Eating stones Geomelophagia Eating raw potatoes","pyqMatches":[{"year":"2013","no":1862,"q":"Pagophagia involves eating ?","o":["Ice","Sand","Clay","Salt"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8484, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 52, '{"id":8484,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":52,"q":"Doppelganger is-","o":["Shadow following person","Feeling of double of oneself","Indentification of stranger as familiar","None of the above"],"a":1,"e":"Ans. is `b'' i.e., Feeling of double of oneself Doppelgangers (subjective double) is the delusion that there is double of oneself. A person feels that double of himself exists elswhere.","pyqMatches":[{"year":"2013","no":1832,"q":"Doppelganger is","o":["Shadow following person","Feeling of double of oneself","Indentification of stranger as familiar","None of the above"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8485, 'Psychiatry', 'ECT & Biological Treatments', 'Easy', 'Psychiatry', 53, '{"id":8485,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Easy","source":"Psychiatry","sourceNo":53,"q":"What is contraindication for ECT ?","o":["Arrthmia","Epilepsy","HIV","Cerebral aneurysm"],"a":3,"e":"Ans. is ''d'' i.e., Cerebral aneurysm Contraindications of ECT Absolute : - Increased intracranial tension.cerebrovascular response to ECT include marked increased in cerebral blood flow and blood flow velocity. Cerebral oxygen consumption increases as well. The rapid increase in systemic blood pressure may transiently overwhelm cerebral autoregulation and may result in increased in intracranial pressure. Therefore, the use of ECT is prohibited in patients with known space occupying lesion (brain tumor) or head injury, cerebral (intracranial) aneurysm. Relative : - Recent myocardial infarction, severe hypertension, cerebrovascular accident, severe pulmonary disease, Retinal detachment, Pheochromocytoma.","pyqMatches":[{"year":"2013","no":1859,"q":"What is contraindication for ECT ?","o":["Arrthmia","Epilepsy","HIV","Cerebral aneurysm"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8486, 'Psychiatry', 'General Psychiatry', 'Hard', 'Psychiatry', 54, '{"id":8486,"subject":"Psychiatry","chapter":"General Psychiatry","difficulty":"Hard","source":"Psychiatry","sourceNo":54,"q":"A patient is known alcoholic since last 20 yrs, suddenly he develops restless tremors, agitation. Diagnosis ?","o":["Delirium tremens","Psychosis","Wernicke''s encephalopathy","Kursakoff''s syndrome"],"a":0,"e":"Ans. is ''a'' i.e., Delirium tremens","pyqMatches":[{"year":"2013","no":1804,"q":"A patient is known alcoholic since last 20 yrs, suddenly he develops restless tremors, agitation. Diagnosis ?","o":["Delirium tremens","Psychosis","Wernicke''s encephalopathy","Kursakoff''s syndrome"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8487, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 55, '{"id":8487,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":55,"q":"Which of the following is delusion ?","o":["Othello syndrome","Declerambault''s syndrome","Pyromania","None"],"a":0,"e":"Ans. is ''a'' i.e., Othello syndrome & ''la'' i.e., Declerambault''s syndrome Delusional disorders (Persistent delusional disorders) Delusional disorder, previously called as paranoid disorder, is a group of disorders where long standing delusions are the primary or only manifestation of illness. Persistent delusions must be present for at least 3 months (ICD-10) or for at least 1 month (DSM - IV). Depending on the content following type of delusions may occur.","pyqMatches":[{"year":"2013","no":1830,"q":"Which of the following is delusion ?","o":["Othello syndrome","Declerambault''s syndrome","Pyromania","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8488, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 56, '{"id":8488,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":56,"q":"Flooding is a treatment modality used in ?","o":["Phobia","Depression","Mania","Schizophrenia"],"a":0,"e":"Ans. is ''a'' i.e., Phobia","pyqMatches":[{"year":"2013","no":1855,"q":"Flooding is a treatment modality used in ?","o":["Phobia","Depression","Mania","Schizophrenia"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8489, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 57, '{"id":8489,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":57,"q":"Schizophrenia is more common in which socio​economic strata ?","o":["Middle","Upper","Low","Upper middle"],"a":2,"e":"Ans. is ''c'' i.e., Low ''Schizophrenia is more prevalent in patients having a lower socioeconomic status\". - Namboodiri Etiology of Schizophrenia The exact etiology is not clear. Experts think schizophrenia is caused by several factors.","pyqMatches":[{"year":"2013","no":1818,"q":"Schizophrenia is more common in which socio​economic strata ?","o":["Middle","Upper","Low","Upper middle"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8490, 'Psychiatry', 'ECT & Biological Treatments', 'Easy', 'Psychiatry', 58, '{"id":8490,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Easy","source":"Psychiatry","sourceNo":58,"q":"ECT is contraindicated in -","o":["Very ill patients","Raised ICT","Heart disease","Pregnancy"],"a":1,"e":"Ans. is ''b'' i.e., Raised ICT","pyqMatches":[{"year":"2013","no":1860,"q":"ECT is contraindicated in","o":["Very ill patients","Raised ICT","Heart disease","Pregnancy"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":2100,"q":"ECT is contraindicated in","o":["Very ill patients","Raised ICT","Heart disease","Pregnancy"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8491, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 59, '{"id":8491,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":59,"q":"Good prognostic factor for schizophrenia is ?","o":["Blunted affect","Early onset","Presence of depression","Male sex"],"a":2,"e":"Ans. is ''c'' i.e., Presence of depression Good prognostic factors :- Acute onset; late onset (onset after 35 years of age); Presence of precipitating stressor; Good premorbid adjustment; catatonic (best prognosis) & Paranoid (2nd best); short duration (< 6 months); Married; Positive symptoms; Presence of depression; family history of mood disorder; first episode; pyknic (fat) physique; female sex; good treatment compliance & good response to treatment; good social support; presence of confusion or perplexity; normal brain CT Scan; outpatient treatment.","pyqMatches":[{"year":"2013","no":1816,"q":"Good prognostic factor for schizophrenia is ?","o":["Blunted affect","Early onset","Presence of depression","Male sex"],"a":2,"source":"NEET_2013_Paper.pdf"},{"year":"2015","no":1693,"q":"Good prognostic factor for schizophrenia is ?","o":["Blunted affect","Early onset","Presence of depression","Male sex"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2013","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8492, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 60, '{"id":8492,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":60,"q":"Time interval between acute and persistent psychotic disease is ?","o":["1 week","2 week","3 week","1 months"],"a":3,"e":"Ans. is `d'' i.e., 1 months If symtoms are for less than 1 months, it is transient psychotic disorder and if there are for more than 1 months, it is persistent psychotic disorder (persistent delusional disorder). Note:- Diagnosic criteria for delusional disorder (Persistent delusion disorder) has different durations in DSM IV and ICD-10 :-","pyqMatches":[{"year":"2013","no":1834,"q":"Time interval between acute and persistent psychotic disease is ?","o":["1 week","2 week","3 week","1 months"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8493, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 61, '{"id":8493,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":61,"q":"Alpha waves in EEG represent ?","o":["Eye closed with active mind","Eye open, fully awake and alert","Deep sleep","None"],"a":0,"e":"Ans. is ''a'' i.e., Eye closed with active mind EEG rhythms and sleep wake cycle Following EEG rhythms (Berger''s rhythm) are important in relation to sleep wake cycle : ?","pyqMatches":[{"year":"2013","no":1854,"q":"Alpha waves in EEG represent ?","o":["Eye closed with active mind","Eye open, fully awake and alert","Deep sleep","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8494, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 62, '{"id":8494,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":62,"q":"Poor prognostic factor for Schizophrenia-","o":["Presence of depression","Female sex","Presence of stressor","Early onset"],"a":3,"e":"Ans. is ''d'' i.e., Early onset Poor prognostic factors :- Insidious onset, early onset (before 20 years of age); absence of precipitating stressor; poor premorbid adjustment; hebephrenic subtype (worst prognosis), simple, undifferentiated and chronic catatonic subtype; long duration (chronic course —> >2 years); single / divorced; Negative symptoms; absence of depression; family history of schizophrenia; past history of schizophrenia; asthenic (thin) physique; male sex; poor treatment compliance & poor response to treatment; poor social support; flat or blunted affect; ventricular enlargement on brain CT scan; hospitalization & indoor treatment","pyqMatches":[{"year":"2013","no":1817,"q":"Poor prognostic factor for Schizophrenia","o":["Presence of depression","Female sex","Presence of stressor","Early onset"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8495, 'Psychiatry', 'General Psychiatry', 'Easy', 'Psychiatry', 63, '{"id":8495,"subject":"Psychiatry","chapter":"General Psychiatry","difficulty":"Easy","source":"Psychiatry","sourceNo":63,"q":"Pathognonomic of maniac episode is ?","o":["Elevated mood","Grandiosity","Decreased appetite","Increased sleep"],"a":1,"e":"Ans. is ''b'' i.e., Grandiosity Option ''a'' is confusing one. Yes, elevated mood is one of the most classical symptom of mania. But it is not pathognomonic. Pathognomonic means a symptom which can be used for diagnosis. Elevated mood is not a symptom of diagnostic criteria of mania. Diagnostic criteria for mania Three or more of the following for at least 1 week :-","pyqMatches":[{"year":"2013","no":1825,"q":"Pathognonomic of maniac episode is ?","o":["Elevated mood","Grandiosity","Decreased appetite","Increased sleep"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8496, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 64, '{"id":8496,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":64,"q":"Father of modern psychiatry is ?","o":["Bleuler","Freud","Pinel","Kraepel in"],"a":2,"e":"Ans. is ''c'' i.e., Pinel Father of psychoanalysis → Sigmund freud Father of modern psychiatry → Phileppel pinel","pyqMatches":[{"year":"2013","no":1866,"q":"Father of modern psychiatry is ?","o":["Bleuler","Freud","Pinel","Kraepel in"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8497, 'Psychiatry', 'General Psychiatry', 'Easy', 'Psychiatry', 65, '{"id":8497,"subject":"Psychiatry","chapter":"General Psychiatry","difficulty":"Easy","source":"Psychiatry","sourceNo":65,"q":"Classical triad of global confusion, ataxia and ophthalmoplegia is seen in ?","o":["Alzheimer''s disease","Delerium tremors","Wernicke''s encephalopathy","Korsakoff psychosis"],"a":2,"e":"Ans. is ''c'' i.e., Wernicke''s encephalopathy","pyqMatches":[{"year":"2013","no":1807,"q":"Classical triad of global confusion, ataxia and ophthalmoplegia is seen in ?","o":["Alzheimer''s disease","Delerium tremors","Wernicke''s encephalopathy","Korsakoff psychosis"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8498, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 66, '{"id":8498,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":66,"q":"Borderline personality disorder ?","o":["Chronic feeling of emptiness","Unstable interpersonal relationship","Grandiosity","Low self esteem"],"a":1,"e":"Ans. is ''b'' i.e., Unstable interpersonl relationship Borderline personality disorder The central feature of borderline personality disorder is a pervasive pattern of unstable and intense interpersonal relationship, self perception and mood. The patient make recurrent suicidal threats and gesture and a small proportion of patients carry out the act or self multilation like cutting or burning. The patients have difficulty in controlling their anger and impulsitivity. There is uncertainty about personal identity.","pyqMatches":[{"year":"2013","no":1843,"q":"Borderline personality disorder ?","o":["Chronic feeling of emptiness","Unstable interpersonal relationship","Grandiosity","Low self esteem"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8499, 'Psychiatry', 'Psychotherapy & Behavioral Sciences', 'Easy', 'Psychiatry', 67, '{"id":8499,"subject":"Psychiatry","chapter":"Psychotherapy & Behavioral Sciences","difficulty":"Easy","source":"Psychiatry","sourceNo":67,"q":"Personality associated bipolar disorder -","o":["Antisocial","Anakastic","Borderline","Narcissistic"],"a":3,"e":"Ans. is ''d'' i.e., Narcissistic Symptoms of Narcissistic personality disorder can be confused with manic phase of bipolar disorder\". Narcissistic personality disorder Narcissistic patients are grandiose and require admiration from other. This is characterized by Ideas of grandiosity & inflated sense of self importance; lack of empathy with others; attention seeking behavior; exploitation of others; and an arrogant, haughty attitude.","pyqMatches":[{"year":"2013","no":1844,"q":"Personality associated bipolar disorder","o":["Antisocial","Anakastic","Borderline","Narcissistic"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8500, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 68, '{"id":8500,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":68,"q":"Bruxism is seen in ?","o":["NREM stage 1,2","NREM stage 3,4","REM","Any of the above"],"a":1,"e":"Ans. is ''b'' i.e., NREM stage 3, 4 Slow wave sleep (stage 3 & 4 of NREM sleep) disorders :- Sleep walking (somnambulism), night terror (sleep terror or pavornocturnus), Nocturnal enuresis, Bruxism (teeth grinding), and sleep talking (somniloquy). REM sleep events/disorder :- Nightmares, nocturnal penile tumescence, Narcolepsy.","pyqMatches":[{"year":"2013","no":1852,"q":"Bruxism is seen in ?","o":["NREM stage 1,2","NREM stage 3,4","REM","Any of the above"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8501, 'Psychiatry', 'General Psychiatry', 'Hard', 'Psychiatry', 69, '{"id":8501,"subject":"Psychiatry","chapter":"General Psychiatry","difficulty":"Hard","source":"Psychiatry","sourceNo":69,"q":"Child wakes up at night sweating and terrified does not remember the episode- diagnosis?","o":["Narcolepsy","Nightmares","Night terrors","Somnambulism"],"a":2,"e":"Ans. is ''c'' i.e., Night terrors Sleep terror or night terrors (pavor nocturnus) : - The patient suddenly gets up screaming, with autonomic arousal (tachycardia, sweating). Sleep terrors are rarely remembered in the morning (in contrast to night mares). No treatment is required only reassurance is required. However, in severe cases benzodiazepine can be used.","pyqMatches":[{"year":"2013","no":1853,"q":"Child wakes up at night sweating and terrified does not remember the episode-diagnosis?","o":["Narcolepsy","Nightmares","Night terrors","Somnambulism"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8502, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 70, '{"id":8502,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":70,"q":"Trichotillomania?","o":["Irresistable desire to set fire","Irresistable desire to steal things","Compulsive hair pulling","Pathological gambling"],"a":2,"e":"Ans. is ''c'' i.e., Compulsive hair pulling","pyqMatches":[{"year":"2013","no":1848,"q":"Trichotillomania?","o":["Irresistable desire to set fire","Irresistable desire to steal things","Compulsive hair pulling","Pathological gambling"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8503, 'Psychiatry', 'Anxiety & Related Disorders', 'Easy', 'Psychiatry', 71, '{"id":8503,"subject":"Psychiatry","chapter":"Anxiety & Related Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":71,"q":"OCD is associated with which personality?","o":["Anakastic","Borderline","Narcissistic","Histrionic"],"a":0,"e":"Ans. is ''a'' i.e., Anankastic Obsessive-Compulsive (anankastic) personality disorder : - People with obsessive-compulsive personality disorder are markedly preoccupied with orderliness, perfectionism, and control. They lack flexibility or openness. Their preoccupations interfere with their efficiency despite their focus on tasks. They are often stingy as well as stuborn.","pyqMatches":[{"year":"2013","no":1845,"q":"OCD is associated with which personality?","o":["Anakastic","Borderline","Narcissistic","Histrionic"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8504, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 72, '{"id":8504,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":72,"q":"Neurotransmitter in mania -","o":["Increased dopaine","Decreased dopamine","Increased norepinephrine","Decreased norepinephrine"],"a":2,"e":"Ans. is ''c'' i.e., Increased norepinephrine Neurotransmitters in mood disorders Most accepted biochemical hypothesis for mood disorders is the monoamine hypothesis, according to which serotinin and norepinephrine are the major neurotransmitters involved in mood disorders : -","pyqMatches":[{"year":"2013","no":1823,"q":"Neurotransmitter in mania","o":["Increased dopaine","Decreased dopamine","Increased norepinephrine","Decreased norepinephrine"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8505, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 73, '{"id":8505,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":73,"q":"Schizophrenia results with ?","o":["Increased GABA","Decreased norepinephrine","Increased dopaminergic activity","Decreased dopaminergic activity"],"a":2,"e":"Ans. is ''c'' i.e., Increased dopaminergic activity Dopamine hypothesis is the most accepted hypothesis for schizophrenia. There is hyperactivity of dopaminergic system. This hypothesis is supported by: 1) Amphetamine and cocaine which release dopamine in central synapses induce schizophrenia like symptoms; and 2) Antipsychotic drugs control the schizophrenic symptoms by blocking dopamine (D,) receptors. However, the dipamine hypothesis has been questioned also as Homo vanillic acid (HVA the principal metabolite of dopamine) is not elevated and prolactin level is not decreased (Dopamine has inhibitory action on prolactin release). Other neurotransmitters involved are : - Increased serotonin, Decreased GABA, variable change (Increased or decreased) glutamate, and increased norepinephrine.","pyqMatches":[{"year":"2013","no":1819,"q":"Schizophrenia results with ?","o":["Increased GABA","Decreased norepinephrine","Increased dopaminergic activity","Decreased dopaminergic activity"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8506, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 74, '{"id":8506,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":74,"q":"Capgras syndrome is ?","o":["Sharing of delusion","Delusion of double","Erotomania","Hypochondriacal delusions"],"a":1,"e":"Ans. is ''B'' i.e., Delusion of double Capgras syndrome is a delusion of double. The delusional misidentification syndrome (DSM) DSM is characterized by misidentification delusions of others or self. Four main syndromes are differentiated : ?","pyqMatches":[{"year":"2015","no":1689,"q":"Capgras syndrome is ?","o":["Sharing of delusion","Delusion of double","Erotomania","Hypochondriacal delusions"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8507, 'Psychiatry', 'Substance Use Disorders', 'Easy', 'Psychiatry', 75, '{"id":8507,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":75,"q":"Drug used for cocaine withdrawal symptoms is-","o":["Floxetine","Lorazepam","Phenobarbital","No drug"],"a":3,"e":"Ans. is ''d'' i.e., No drug \"Tolerance develops swiftly but there are no withdrawal symptoms. Treament, if needed, is symptomatic. Often no medicines are needed and the user can stop its use by himself when he is coerced to do so by the court or the employer\" - Namboodiri \"No pharmacological agents reliably reduce the intensity of withdrawal, but recovery over a weak or two is generally uneventful\" - Kaplan & Saddock","pyqMatches":[{"year":"2013","no":1808,"q":"Drug used for cocaine withdrawal symptoms is","o":["Floxetine","Lorazepam","Phenobarbital","No drug"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8508, 'Psychiatry', 'Schizophrenia & Psychosis', 'Moderate', 'Psychiatry', 76, '{"id":8508,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Moderate","source":"Psychiatry","sourceNo":76,"q":"In stupor catatonia, all are seen except -","o":["Agitation","Catalepsy","Mutism","Akinesia"],"a":0,"e":"Ans. is ''a'' i.e., Agitation Agitation is seen in excited catatonia (not is stupor catatonia). Features of catatonic schizophrenia may be :?","pyqMatches":[{"year":"2013","no":1820,"q":"In stupor catatonia, all are seen except","o":["Agitation","Catalepsy","Mutism","Akinesia"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8509, 'Psychiatry', 'Anxiety & Related Disorders', 'Easy', 'Psychiatry', 77, '{"id":8509,"subject":"Psychiatry","chapter":"Anxiety & Related Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":77,"q":"Psychosurgery is used in ?","o":["Phobia","Generalized anxiety","OCD","Depression"],"a":2,"e":"Ans. is ''c'' i.e., OCD","pyqMatches":[{"year":"2013","no":1856,"q":"Psychosurgery is used in ?","o":["Phobia","Generalized anxiety","OCD","Depression"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8510, 'Psychiatry', 'Substance Use Disorders', 'Easy', 'Psychiatry', 78, '{"id":8510,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":78,"q":"Role of marijuana in AIDS related cachexia?","o":["Euphoric","Pschostimulator","Increases appetite","Decrease emetic feeling"],"a":2,"e":"Ans. is ''c'' i.e., Increases appetite Mari-juana or cannabis sativa contains the active principle tetrahydrocannabinol (THC), which as an appetite stimulant effect.","pyqMatches":[{"year":"2013","no":1810,"q":"Role of marijuana in AIDS related cachexia?","o":["Euphoric","Pschostimulator","Increases appetite","Decrease emetic feeling"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8511, 'Psychiatry', 'Miscellaneous', 'Moderate', 'Psychiatry', 79, '{"id":8511,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Psychiatry","sourceNo":79,"q":"All are used in treatment of nocturnal eneuresis except ?","o":["Imipramine","Alarm setup","Voiding of urine before sleeping","Maintainence of calendar of day night wetting"],"a":3,"e":"Ans. is ''d i.e Maintainence of calendar of day night wetting All are used. Treatment of nocturnal eneuresis It consists of :?","pyqMatches":[{"year":"2013","no":1863,"q":"All are used in treatment of nocturnal eneuresis except ?","o":["Imipramine","Alarm setup","Voiding of urine before sleeping","Maintainence of calendar of day night wetting"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8512, 'Psychiatry', 'Miscellaneous', 'Moderate', 'Psychiatry', 80, '{"id":8512,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Psychiatry","sourceNo":80,"q":"Repressed information can be brought into conscious mind by all except ?","o":["Dream","Focused attention","Hypnosis","Somatic stimulation"],"a":1,"e":"Ans. is ''b'' i.e., Focused attention Preconcious thoughts are readily accessible to conciousness by focused attention, but not unconscious thoughts which contains repressed memory. Freud advanced the ''topographic theory of mind'' in the year 1900 in the book ''the interpretation of dreams''. It divides the mind into three divisions :?","pyqMatches":[{"year":"2013","no":1861,"q":"Repressed information can be brought into conscious mind by all except ?","o":["Dream","Focused attention","Hypnosis","Somatic stimulation"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8513, 'Psychiatry', 'Child & Adolescent Psychiatry', 'Moderate', 'Psychiatry', 81, '{"id":8513,"subject":"Psychiatry","chapter":"Child & Adolescent Psychiatry","difficulty":"Moderate","source":"Psychiatry","sourceNo":81,"q":"All of the following are used to improve attention deficit in children except ?","o":["Cognitive enhancement therapy","Cognitive behavioural therapy","Cognitive remeditation therapy","Flooding"],"a":3,"e":"Ans. is ''d. i.e., Flooding In attention deficit following can be used :","pyqMatches":[{"year":"2013","no":1864,"q":"All of the following are used to improve attention deficit in children except ?","o":["Cognitive enhancement therapy","Cognitive behavioural therapy","Cognitive remeditation therapy","Flooding"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8514, 'Psychiatry', 'Schizophrenia & Psychosis', 'Moderate', 'Psychiatry', 82, '{"id":8514,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Moderate","source":"Psychiatry","sourceNo":82,"q":"Indications for ECT are all except ?","o":["Severe depression with suicidal risk","Catatonic schizophrenia","Severe psychosis","Sever manic attack"],"a":3,"e":"Ans. is ''d'' i.e., Sever manic attack Indications of ECT Severe depression with suicial risk or with psychotic features or with stupor. Some types of schizophrenia (catatonic or paranoid) Schizophrenic or depressive stupor Severe catatonia with stupor Severe psychoses (schizophrenia or mania) with risk of suicide or homicide or physical assault.","pyqMatches":[{"year":"2013","no":1858,"q":"Indications for ECT are all except ?","o":["Severe depression with suicidal risk","Catatonic schizophrenia","Severe psychosis","Sever manic attack"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8515, 'Psychiatry', 'Child & Adolescent Psychiatry', 'Easy', 'Psychiatry', 83, '{"id":8515,"subject":"Psychiatry","chapter":"Child & Adolescent Psychiatry","difficulty":"Easy","source":"Psychiatry","sourceNo":83,"q":"Concrete thinking stage of cognitive development?","o":["0-2 years","2-5 years","5-10 years","10-15 years"],"a":2,"e":"Ans. is ''c'' i.e., 5-10 years Cognitive development stages Children are not little adults. Until they reach the age of 15 or so they are not capable of reasoning as an adult. Jean Piget described four major stages of intellectual (cognitive) development which are related to major development in brain growth.","pyqMatches":[{"year":"2013","no":1868,"q":"Concrete thinking stage of cognitive development?","o":["0-2 years","2-5 years","5-10 years","10-15 years"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8516, 'Psychiatry', 'Substance Use Disorders', 'Moderate', 'Psychiatry', 84, '{"id":8516,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Moderate","source":"Psychiatry","sourceNo":84,"q":"Delusions are features of all except ?","o":["Delirium","Schizophrenic","OCD","Alcohol withdrawal"],"a":2,"e":"Ans. is ''c'' i.e., OCD Delusions are seen in psychotic disorders Organic","pyqMatches":[{"year":"2013","no":1811,"q":"Delusions are features of all except ?","o":["Delirium","Schizophrenic","OCD","Alcohol withdrawal"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8517, 'Psychiatry', 'ECT & Biological Treatments', 'Easy', 'Psychiatry', 85, '{"id":8517,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Easy","source":"Psychiatry","sourceNo":85,"q":"Psychoanalysis was started by ?","o":["Eugen Bleuler","Sigmund Freud","Bleuler","Erikson"],"a":1,"e":"Ans. is ''b'' i.e., Sigmund freud Name Contribution Sigmund Freud Psychoanalysis, free association, (oedipus & electra complex), cocaine in psychiatry, Repression, ego-defence mechanisms, psychodynamic theory. Phillippe Pinel Moral and humane treatment of mentally ill Jones Maxwell Propagated therapeutic community concept. Kuble Ross Erik Classified five stages of death. Erikson Divided life cycle in 8 stages","pyqMatches":[{"year":"2013","no":1794,"q":"Psychoanalysis was started by ?","o":["Eugen Bleuler","Sigmund Freud","Bleuler","Erikson"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8518, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 86, '{"id":8518,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":86,"q":"Hallucinations, true is ?","o":["Perceived in the inner subjective space","There is misinterpretation of external stimulus","There is no external stimulus","Can be controlled by voluntary effort"],"a":2,"e":"Ans. is ''c'' i.e., There is no external stimulus Characteristics of Hallucinations :?","pyqMatches":[{"year":"2013","no":1796,"q":"Hallucinations, true is ?","o":["Perceived in the inner subjective space","There is misinterpretation of external stimulus","There is no external stimulus","Can be controlled by voluntary effort"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8519, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 87, '{"id":8519,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":87,"q":"Cotard''s syndrome has ?","o":["Persecutory delusions","Religious delusions","Nihilistic delusions","Hypochondrical delusions"],"a":2,"e":"Ans. is ''c'' i.e., Nihilistic delusions Types of delsions Based on the contents of delusions, they are divided into :-","pyqMatches":[{"year":"2013","no":1797,"q":"Cotard''s syndrome has ?","o":["Persecutory delusions","Religious delusions","Nihilistic delusions","Hypochondrical delusions"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8520, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 88, '{"id":8520,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":88,"q":"Oedipus complex is related to which phase of psychosexual development ?","o":["Oral","Anal","Genital","Phallic"],"a":3,"e":"Ans. is `d'' i.e., Phallic","pyqMatches":[{"year":"2013","no":1867,"q":"Oedipus complex is related to which phase of psychosexual development ?","o":["Oral","Anal","Genital","Phallic"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8521, 'Psychiatry', 'Psychotherapy & Behavioral Sciences', 'Easy', 'Psychiatry', 89, '{"id":8521,"subject":"Psychiatry","chapter":"Psychotherapy & Behavioral Sciences","difficulty":"Easy","source":"Psychiatry","sourceNo":89,"q":"Most effective treatment in borderline personality disorders?","o":["Pharmacotherapy","Behaviour therapy","Combination of both pharmacotherapy and behavioural therapy","None"],"a":1,"e":"Ans. is ''b'' i.e., Behaviour therapy \"Dialectical behavioral therapy (DBT), a type of cognitive behavioral therapy (CBT), has been developed specifically for the treatment of borderline personality disorder, and it appear to be the most effective treatment for this condition\".","pyqMatches":[{"year":"2013","no":1846,"q":"Most effective treatment in borderline personality disorders?","o":["Pharmacotherapy","Behaviour therapy","Combination of both pharmacotherapy and behavioural therapy","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8522, 'Psychiatry', 'Mood Disorders', 'Moderate', 'Psychiatry', 90, '{"id":8522,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Moderate","source":"Psychiatry","sourceNo":90,"q":"All are reversible causes of dementia except","o":["Hypothyroidism","Hydrocephalus","Meningoencephalitis","Alzheimer''s disease"],"a":3,"e":"Ans. ''D'' i.e., Alzheimer''s disease Reversible causes of dementia 1) Surgically treatable:- Normal pressure hydrocephalus, brain tumors (frontal lobe tumor), meningioma, subdural hematoma due to head injury, hydrocephalus. 2) Medically treatable:- Depression, hypothyroidism, alcohol abuse, vitamin B 12/folate/Niacin deficiency, any metabolic or endocrine disturbance, neurosyphilis, Hashimoto''s encephalopathy, Wilson''s disease, celiac disease, Whipple''s disease, chronic meningoencephalitis, drugs and toxin (toxic dementia). Irreversible causes of dementia:- Alzheimer''s disease, vascular (multi-infarct) dementia, Parkinsonism, Huntington''s chorea, Lewy body dementia, Pick''s disease.","pyqMatches":[{"year":"2015","no":1683,"q":"All are reversible causes of dementia except","o":["Hypothyroidism","Hydrocephalus","Meningoencephalitis","Alzheimer''s disease"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8523, 'Psychiatry', 'Schizophrenia & Psychosis', 'Moderate', 'Psychiatry', 91, '{"id":8523,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Moderate","source":"Psychiatry","sourceNo":91,"q":"Visual hallucinations are seen in all except ?","o":["Delirium","Depression","Schizophrenia","Alcohol withdrawal"],"a":1,"e":"Ans. is ''b'' i.e., Depression Type of hallucination Causes Auditory Schizophrenia, Organic brain syndrome, Alcoholic hallucinosis manic-depressive illness, Brain lesions →Pontine or temporal lobe lesions. Visual Organic brain disturbances : - Delirium, delirium tremens, occipital lobe tumors, epilepsy, dementia Intoxication (LSD, amphetamines, Alcohol, mescaline), alcohol withdrawal. Brain lesions","pyqMatches":[{"year":"2013","no":1799,"q":"Visual hallucinations are seen in all except ?","o":["Delirium","Depression","Schizophrenia","Alcohol withdrawal"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8524, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 92, '{"id":8524,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":92,"q":"Waxy flexibility is a feature of ?","o":["Echopraxia","Catatonia","Stereotype","Mannerism"],"a":1,"e":"Ans. ''B'' i.e., Catatonia Catatonia may be of following types:- Catatonic excitement:- Excited, uncontrolled motor activity, not influenced by external stimuli. Catatonic posturing:- Voluntary adoption of an unusual or bizarre position that is then maintained for some time. Catatonic rigidity:- Maintaining a fixed position and rigidity resisting all attempts to be moved. Waxy flexibility (flexibility cerea or catalepsy): - Maintaining of particular posture imposed on the patient by the examiner, even if the posture is bizarre and uncomfortable, i.e., the patient can be molded like wax into a position that is then maintained. Catatonic stupor:- Patient is mute and immobile (akinetic mutism) but fully conscious. Catatonic negativism .- A seemingly motiveless resistance to all instructions or attempts to be moved. Automatic obedience:- Exactly reverse to negativism, i.e., unhesitating compliance to all instructions without apparent conscious control.","pyqMatches":[{"year":"2013","no":1798,"q":"Waxy flexibility is a feature of ?","o":["Echopraxia","Catatonia","Stereotype","Mannerism"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8525, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 93, '{"id":8525,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":93,"q":"Term Psychiatry was coined by ?","o":["Moral","Johann reil","Bleuler","Pinel"],"a":1,"e":"Ans. is ''b'' i.e., Johann reil IMPORTANT CONTRIBUTORS IN PSYCHIATRY Term Coined by Demence precoce Dementia precox Catatonia, cyclotymia Hebephrenia Schizophrenia Ambivalence Free association Psychoanalysis, Psychodynamics Id, ego, Superego Psychiatry Moral Emil Kraepelin Kahlbaum Hecker Eugen Bleuler Eugen Bleuler Sigmund Freud Sigmunnd Freud Sigmund Freud Johann christion Reil","pyqMatches":[{"year":"2013","no":1795,"q":"Term Psychiatry was coined by ?","o":["Moral","Johann reil","Bleuler","Pinel"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8526, 'Psychiatry', 'ECT & Biological Treatments', 'Moderate', 'Psychiatry', 94, '{"id":8526,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Moderate","source":"Psychiatry","sourceNo":94,"q":"All are features of Korsakoff syndrome except","o":["Antegrade amnesia","Retrograde amnesia","Ataxia","Confabulation"],"a":2,"e":"Ans. ''C'' i.e., Ataxia Korsakoff syndrome Korsakoff''s syndrome is the chronic amnestic syndrome that follows Wernicke''s encephalopathy, and the two syndromes are believed to be pathophysiologically related. Korsakoff''s syndrome is characterized by severe and irreversible memory impairments and confabulation behaviour in the absence of intellectual decline or attention deficit. Important clinical features are:?","pyqMatches":[{"year":"2013","no":1869,"q":"All are features of Korsakoff syndrome except","o":["Antegrade amnesia","Retrograde amnesia","Ataxia","Confabulation"],"a":2,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":2113,"q":"All are features of Korsakoff syndrome except","o":["Antegrade amnesia","Retrograde amnesia","Ataxia","Confabulation"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8527, 'Psychiatry', 'Substance Use Disorders', 'Moderate', 'Psychiatry', 95, '{"id":8527,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Moderate","source":"Psychiatry","sourceNo":95,"q":"Diagnostic criteria for drug dependence includes all except -","o":["Tolerance","Withdrawal symptoms","Early completion of tasks","Larger dose than usual"],"a":0,"e":"Ans. is ''c'' i.e., Early completion of tasks Diagnostic criteria for substance abuse To make a diagnosis of dependence, three or more of the following criteria should be present. Tolerance :- Same dose produces markedly diminished effect on continuous use, therefore increased doses are required to produce same effect. Withdrawal symptoms on abstinence. Substance is taken in larger amount or longer period than was intended. Persistent desire (craving) or sense of compulsion to take the substance. A great deal of time spent to obtain the substance, to use substance or to recover from its effect. Neglect of important social, occupational and recreational activities. Continued substance use despite clear evidence of overtly harmful consequences","pyqMatches":[{"year":"2013","no":1802,"q":"Diagnostic criteria for drug dependence includes all except","o":["Tolerance","Withdrawal symptoms","Early completion of tasks","Larger dose than usual"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8528, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 96, '{"id":8528,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":96,"q":"Suspiciousness is a characteristic feature of ?","o":["Paranoid personality disorder","Schizoid personality disorder","Schizotypal personality disorder","Anankastic personality disorder"],"a":0,"e":"Ans. is ''a'' i.e., Paranoid personality disorder Paranoid personality disorder It is characterized by generalised mistrust and Suspiciousness about the motives and actions of others and a tendency to interpret them as malevolent. The patient believes that :-","pyqMatches":[{"year":"2013","no":1842,"q":"Suspiciousness is a characteristic feature of ?","o":["Paranoid personality disorder","Schizoid personality disorder","Schizotypal personality disorder","Anankastic personality disorder"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8529, 'Psychiatry', 'Miscellaneous', 'Moderate', 'Psychiatry', 97, '{"id":8529,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Psychiatry","sourceNo":97,"q":"Earliest symptom showing improvement from classical triad of Wernicke''s incephalopathv. to thiamine therapy ?","o":["Ataxia","Ophthalmoplegia","Confusion","All are equally responsive"],"a":1,"e":"Ans. is ''b'' i.e., Ophthalmoplegia Response to thiamine treatment in Wernicke''s encephalopathy Ocular symptoms :- Earliest to respond, ophthalmoplegia (ocular palsies) improves within hours of thiamine administration. However, horizontal nystagmus may persist. Ataxia :- Ataxia responds more slowly than ocular palsies and half the patients recover incompletely with a residual ataxia. Encephalopathy :- Confusion and other CNS symptoms improve more slowly. As the symptoms of encephalopathy improve, Korsakoff''s syndrome may become apparent in some patients","pyqMatches":[{"year":"2013","no":1805,"q":"Earliest symptom showing improvement from classical triad of Wernicke''s incephalopathv. to thiamine therapy ?","o":["Ataxia","Ophthalmoplegia","Confusion","All are equally responsive"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8530, 'Psychiatry', 'Substance Use Disorders', 'Moderate', 'Psychiatry', 98, '{"id":8530,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Moderate","source":"Psychiatry","sourceNo":98,"q":"All are symptoms of morphine withdrawal except?","o":["Mydriasis","Yawning","Lacrimation","Fall in BP"],"a":3,"e":"Ans. is ''d'' i.e., Fall in BP Morphine withdrawal Manifestations of morphine withdrawl","pyqMatches":[{"year":"2013","no":1806,"q":"All are symptoms of morphine withdrawal except?","o":["Mydriasis","Yawning","Lacrimation","Fall in BP"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8531, 'Psychiatry', 'Mood Disorders', 'Moderate', 'Psychiatry', 99, '{"id":8531,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Moderate","source":"Psychiatry","sourceNo":99,"q":"All are required to diagnose major depression except ?","o":["Depressed mood","Isomnia","Nihlistic ideas","Decreased concentration"],"a":2,"e":"Ans. is ''c'' i.e., Nihlistic ideas Diagnostic criteria for major depression 5 or more of following symptoms should be present most of the day for at least 2 weeks: ?","pyqMatches":[{"year":"2013","no":1827,"q":"All are required to diagnose major depression except ?","o":["Depressed mood","Isomnia","Nihlistic ideas","Decreased concentration"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8532, 'Psychiatry', 'General Psychiatry', 'Moderate', 'Psychiatry', 100, '{"id":8532,"subject":"Psychiatry","chapter":"General Psychiatry","difficulty":"Moderate","source":"Psychiatry","sourceNo":100,"q":"All are features of psychosis except ?","o":["Loss of insight","Presence of delusions","Preserved contact with reality","Personality disturbances"],"a":2,"e":"Ans. is ''c'' i.e., Preserved contact with reality Psychosis Psychosis is a mental state involving the loss of contact with reality, causing deterioration of normal social functioning. The characteristic features of psychosis are : -","pyqMatches":[{"year":"2013","no":1812,"q":"All are features of psychosis except ?","o":["Loss of insight","Presence of delusions","Preserved contact with reality","Personality disturbances"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8533, 'Psychiatry', 'Anxiety & Related Disorders', 'Easy', 'Psychiatry', 101, '{"id":8533,"subject":"Psychiatry","chapter":"Anxiety & Related Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":101,"q":"Ganser syndrome is a feature of ?","o":["OCD","Conversion disorder","Dissociative disorder","Schizoid personality disorder"],"a":2,"e":"Ans. is ''c'' i.e., Dissociative disorder Dissociative disorder The essential feature of the dissociative disorder is a disruption in the usually integrated functions of consciousness, memory, identity or perception of the environment. Dissociative disorder are :-","pyqMatches":[{"year":"2013","no":1822,"q":"Ganser syndrome is a feature of ?","o":["OCD","Conversion disorder","Dissociative disorder","Schizoid personality disorder"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8534, 'Psychiatry', 'Anxiety & Related Disorders', 'Easy', 'Psychiatry', 102, '{"id":8534,"subject":"Psychiatry","chapter":"Anxiety & Related Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":102,"q":"Repetitive irresesistable thought to do something","o":["Phobia","Obsession","Compulsion","Anxiety"],"a":1,"e":"Ans. is ''b'' i.e., Obsession Obsessive compulsive disorder (OCD) OCD is an anxiety disorder which is characterized by recurrent, unwanted thoughts (Obsessions) and repettive behaviors (compulsions). An obsession has following characteristic : -","pyqMatches":[{"year":"2012","no":1458,"q":"Repetitive irresesistable thought to do something","o":["Phobia","Obsession","Compulsion","Anxiety"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8535, 'Psychiatry', 'General Psychiatry', 'Moderate', 'Psychiatry', 103, '{"id":8535,"subject":"Psychiatry","chapter":"General Psychiatry","difficulty":"Moderate","source":"Psychiatry","sourceNo":103,"q":"All are features of neurosis except ?","o":["Symptoms cause subjective distress","Contact with reality preserved","Personality disturbances","Insight is maintained"],"a":2,"e":"Ans. is ''c'' i.e., Personality disturbances","pyqMatches":[{"year":"2013","no":1813,"q":"All are features of neurosis except ?","o":["Symptoms cause subjective distress","Contact with reality preserved","Personality disturbances","Insight is maintained"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8536, 'Psychiatry', 'Substance Use Disorders', 'Moderate', 'Psychiatry', 104, '{"id":8536,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Moderate","source":"Psychiatry","sourceNo":104,"q":"All are seen in nicotine withdrawal except ?","o":["Hyperhydrosis","Anxiety","Bradycardia","Insomnia"],"a":0,"e":"Ans. is ''a'' i.e., Hyperhydrosis","pyqMatches":[{"year":"2013","no":1809,"q":"All are seen in nicotine withdrawal except ?","o":["Hyperhydrosis","Anxiety","Bradycardia","Insomnia"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8537, 'Psychiatry', 'Miscellaneous', 'Moderate', 'Psychiatry', 105, '{"id":8537,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Psychiatry","sourceNo":105,"q":"All are included in diagnostic criteria of somatization disorder except ?","o":["Sexual symptom","Pain symptom","GI symptom","Visual symptoms"],"a":3,"e":"Ans. is ''d'' i.e., Visual symptoms Somatization disorder The essential features of somatization disorder are multiple recurrent somatic symptoms of long duration (chronic) that are caused by psychological basis and no physical illness can be found. The disorder begins before the age of 30 years and then has a chronic course (over a period of several years). Diagnostic criteria for somatization disorder Each of the following should be present : ?","pyqMatches":[{"year":"2013","no":1840,"q":"All are included in diagnostic criteria of somatization disorder except ?","o":["Sexual symptom","Pain symptom","GI symptom","Visual symptoms"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8538, 'Psychiatry', 'Schizophrenia & Psychosis', 'Moderate', 'Psychiatry', 106, '{"id":8538,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Moderate","source":"Psychiatry","sourceNo":106,"q":"Bleuler''s symptoms for schizophrenia are all except?","o":["Loosening of association","Affect disturbances","Autism","Hallucinations"],"a":3,"e":"Ans. is ''d'' i.e., Hallucinations Eugen Bleuler renamed dementia precox as Schizophrenia. He recognized that schizophrenia is a group of disorders rather than a distinct entity. Therefore, he used the term, a group of schizophrenias. Bleuler described the characteristic symptoms (fundamental symptoms) for schizophrenia which are also known as 4 ''A''s of Bleuler :?","pyqMatches":[{"year":"2013","no":1814,"q":"Bleuler''s symptoms for schizophrenia are all except?","o":["Loosening of association","Affect disturbances","Autism","Hallucinations"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8539, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 107, '{"id":8539,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":107,"q":"Negative symptom of schizophrenia ?","o":["Hallucination","Delusion","Ambivalance","Motor hyperactivity"],"a":2,"e":"Ans. is ''c'' i.e., Ambivalance Symptoms of schizophrenia can be divided into :?","pyqMatches":[{"year":"2012","no":1452,"q":"Negative symptom of schizophrenia ?","o":["Hallucination","Delusion","Ambivalance","Motor hyperactivity"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8540, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 108, '{"id":8540,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":108,"q":"Cyclothymia is a type of ?","o":["Bipolar mood disorder","Major depression","Dysthymia","Persistant mood disorder"],"a":3,"e":"Ans. is ''d'' i.e., Persistant mood disorder Persistent mood disorder Mood disorders may run a chronic course over years with fluctuation of mood interposed with symptom free intervals. If symptoms persist for more than 2 years, they are referred to as persistent mood disorders. Two most important persistant mood disorders are :?","pyqMatches":[{"year":"2013","no":1826,"q":"Cyclothymia is a type of ?","o":["Bipolar mood disorder","Major depression","Dysthymia","Persistant mood disorder"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8541, 'Psychiatry', 'Anxiety & Related Disorders', 'Moderate', 'Psychiatry', 109, '{"id":8541,"subject":"Psychiatry","chapter":"Anxiety & Related Disorders","difficulty":"Moderate","source":"Psychiatry","sourceNo":109,"q":"All are anxiety disorders except ?","o":["Phobias","OCD","Conversion reaction","PTSD"],"a":2,"e":"Ans. is ''c'' i.e., Conversion reaction Anxiety disorders are :-","pyqMatches":[{"year":"2013","no":1836,"q":"All are anxiety disorders except ?","o":["Phobias","OCD","Conversion reaction","PTSD"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8542, 'Psychiatry', 'Schizophrenia & Psychosis', 'Moderate', 'Psychiatry', 110, '{"id":8542,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Moderate","source":"Psychiatry","sourceNo":110,"q":"All are diagnostic symptoms of schizophrenia except?","o":["Catatonia","Hallucinations","Disorganized speech","Social withdrawal"],"a":3,"e":"Ans. is ''d'' i.e., Social withdrawal Diagnostic criteria for schizophrenia Characteristic symptoms :- Two (or more) of the following for a 1 months duration (or less if successfully treated) :?","pyqMatches":[{"year":"2013","no":1815,"q":"All are diagnostic symptoms of schizophrenia except?","o":["Catatonia","Hallucinations","Disorganized speech","Social withdrawal"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8543, 'Psychiatry', 'Schizophrenia & Psychosis', 'Moderate', 'Psychiatry', 111, '{"id":8543,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Moderate","source":"Psychiatry","sourceNo":111,"q":"All are true about type 1 schizophrenia except?","o":["Acute illness","Good prognosis","Negative symptoms","Intellect maintained"],"a":2,"e":"Ans. is ''c'' i.e., Negative symptoms Type I (Reactive or acute schizophrenia) Type II (Process schizophrenia) Characteristic symptoms Type of illness Response to neuroleptics Outcome Intellectual impairment Etiology Positive symptoms (Hallucination,Acute Delusion, Thought) Good Reversible Absent Dopamine overactivity Good Negative symptoms (Affect flattening, poverity of speech loss of drive Chronic Poor Long standing Sometimes present Structural changes in brain (dilated ventricle on CT scan Poor","pyqMatches":[{"year":"2013","no":1821,"q":"All are true about type 1 schizophrenia except?","o":["Acute illness","Good prognosis","Negative symptoms","Intellect maintained"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8544, 'Psychiatry', 'ECT & Biological Treatments', 'Easy', 'Psychiatry', 112, '{"id":8544,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Easy","source":"Psychiatry","sourceNo":112,"q":"Drug of choice for generalized anxiety ?","o":["3-blocker","Alprazolam","Buspirone","Phenytoin"],"a":1,"e":"Ans. is ''b'' i.e., Alprazolam Treatment of generalized anxiety Benzodiazepines are the drug of choice. Drugs in this group are diazepam, Lorazepam, Alprazolam, Oxazepam, chlordiazepoxide. Other drugs used are buspirone; TCA (amptriptyline, imipramine, clomipramine, desipramine); SSRIs (Fluoxetine, Sertaline, Paroxetine, Citalopram); SNRIs (Venalafaxine), 13-blockers. Anticonvulsants with GABAergic properties may also be effective against anxiety, e.g., Gabapentin, Oxcarbazepine, Tiagabine, pregabalin, and Valproate (divalporex).","pyqMatches":[{"year":"2013","no":1837,"q":"Drug of choice for generalized anxiety ?","o":["3-blocker","Alprazolam","Buspirone","Phenytoin"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8545, 'Psychiatry', 'Anxiety & Related Disorders', 'Easy', 'Psychiatry', 113, '{"id":8545,"subject":"Psychiatry","chapter":"Anxiety & Related Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":113,"q":"Persistent preoccupation with serious illness and normal body function is called ?","o":["Obsession","Somatization","Hypochondriasis","Conversion disorder"],"a":2,"e":"Ans. is ''c'' i.e., Hypochondriasis Hvpochondriasis (hypochondriacal disorder) The primary feature of hypochondriasis is persistent preoccupation with excessive fear of a serious (e.g., cancer) or incurable (e.g., AIDS) disease, which is based on person''s own interpretation of physical symptoms or sensation, i.e., misinterpretation of physical symptoms or sensations, for example an occasional change in heart rate will lead a person with hypochondriasis to fear of heart disease. Therefore, Hypochondriasis is abnormal preoccupation about normal body function, i.e., body functioning is normal but patient thinks it as abnormal. The preoccupation with the presence of a feared illness persists inspite of normal medical assessment and investigations. Patient goes from one doctor to another for a consultation. People with hypochondriasis are able to acknowledge that their fears are unrealistic (insight is present), but this intellectual realization is not enough to reduce their anxiety. Two important facts differentiate hypochondriasis from somatization disorder : -","pyqMatches":[{"year":"2012","no":1462,"q":"Persistent preoccupation with serious illness and normal body function is called ?","o":["Obsession","Somatization","Hypochondriasis","Conversion disorder"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8546, 'Psychiatry', 'Miscellaneous', 'Moderate', 'Psychiatry', 114, '{"id":8546,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Psychiatry","sourceNo":114,"q":"Not true about somnambulism among the following is?","o":["Sleep walking.","Patient consciousness is preserved.","Disorder of sleep arousal.","Low level motor skill/function is present"],"a":3,"e":"Ans: D. Low level motor skill/function is present. Sleep walking (somnambulism): The patients may carry out a range of activities for which he doesn''t have any memory later on. It may include leaving the bed and walking about and also activities like dressing, moving around or even driving.","pyqMatches":[{"year":"2019","no":235,"q":"Not true about somnambulism among the following is?","o":["Sleep walking.","Patient consciousness is preserved.","Disorder of sleep arousal.","Low level motor skill/function is present"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8547, 'Psychiatry', 'ECT & Biological Treatments', 'Moderate', 'Psychiatry', 115, '{"id":8547,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Moderate","source":"Psychiatry","sourceNo":115,"q":"Test based on the principle of suspect’s reaction, if he witnesses an event then he behaves in a certain way is?","o":["Narcoanalysis","Brain mapping","Truth serum testing","Polygraph"],"a":3,"e":"Ans:D. Polygraph","pyqMatches":[{"year":"2019","no":238,"q":"Test based on the principle of suspect’s reaction, if he witnesses an event then he behaves in a certain way is?","o":["Narcoanalysis","Brain mapping","Truth serum testing","Polygraph"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8548, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 116, '{"id":8548,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":116,"q":"Intense depression & misery without any cause is?","o":["Melancholia","Major depressive disorder","Mania","Schizophrenia"],"a":0,"e":"Ans:A. Melancholia","pyqMatches":[{"year":"2019","no":239,"q":"Intense depression & misery without any cause is?","o":["Melancholia","Major depressive disorder","Mania","Schizophrenia"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8549, 'Psychiatry', 'Schizophrenia & Psychosis', 'Moderate', 'Psychiatry', 117, '{"id":8549,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Moderate","source":"Psychiatry","sourceNo":117,"q":"Which of the following is not true regarding delusional disorder?","o":["Held with absolute conviction","Usually false","Not amenable to reasoning","Occurs at early age"],"a":3,"e":"Ans:D. Occurs at early age. Delusional disorder may account for 1–2% of admissions to inpatient psychiatric hospitals. Age at onset ranges from 18–90 years, with a mean age of 40 years","pyqMatches":[{"year":"2019","no":240,"q":"Which of the following is not true regarding delusional disorder?","o":["Held with absolute conviction","Usually false","Not amenable to reasoning","Occurs at early age"],"a":3,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8550, 'Psychiatry', 'Substance Use Disorders', 'Easy', 'Psychiatry', 118, '{"id":8550,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":118,"q":"Key symptom in alcohol withdrawal syndrome is:","o":["Sleep disturbance","Visual hallucinations","Tremors","Delirium"],"a":2,"e":"Ans: C. Tremors Key symptom - Tremor. Withdrawal Syndromes SubstanceFeatures Opioid Yawning°, Insomnia, Dysphoric mood Water loss from different orifices° (Lacrimation°, sweating°, diarrhea°, vomiting, Increased vitals° (BP, Pulse, RR, Temperature)° Pupillary dilation, piloerection° Alcohol Hang over (MC)° Hallucinations° (usually auditory) and illusions° Insomnia° Tremors/Seizures (Alcoholic seizures/Rum fits): Classic sign Delirium tremens: Occurs within 5 days° of complete or significant abstinence° from heavy alcohol Recovery occurs within 7 days Characteristic features are clouding of consciousness°, disorientation°, hallucinations (mostly visual and auditory)°, illusion°, autonomic disturbances°, agitation° and insomnia°. Cocaine Increased or decreased Sleep (hypersomnia° or insomnia) Psychomotor activity Vivid unpleasant dreams° Increased apetite and fatigue","pyqMatches":[{"year":"2014","no":2109,"q":"Key symptom in alcohol withdrawal syndrome is:","o":["Sleep disturbance","Visual hallucinations","Tremors","Delirium"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8551, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 119, '{"id":8551,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":119,"q":"What is produced by the supersensitivity of Dopamine receptors ?","o":["Dyskinesia","Hyperphagia","Hyperpathia","Hypomania"],"a":0,"e":"Ans. is ''a'' i.e., Dyskinesia (Ref: Pathophysiology, pharmacology and biochemistry of dyskinesia p. 195) Increased neostriatal dopamine receptor density and dopaminergic supersensitivity in the neuroendocrine system are associated with the development of tardive dyskinesia.","pyqMatches":[{"year":"2014","no":2069,"q":"What is produced by the supersensitivity of Dopamine receptors ?","o":["Dyskinesia","Hyperphagia","Hyperpathia","Hypomania"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8552, 'Psychiatry', 'Anxiety & Related Disorders', 'Easy', 'Psychiatry', 120, '{"id":8552,"subject":"Psychiatry","chapter":"Anxiety & Related Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":120,"q":"Following are the major symptoms of obsessive compulsive disorders ?","o":["Contamination","Pathological doubts","Intrusive thoughts","All the above"],"a":3,"e":"Ans. is''d''i.e., AII the above [Rl Kaplan & Saddock''s |tr/e p. 605) OCD has four major symptom patterns :- Contamination : - Contamination is the most common pattern of an obsession followed by washing (washer) Pathological doubts : - Doubts is the second most common pattern of an obsession, followed by a compulsive checking (checkers). Intrusive thoughts (Pure obsessions) : - In this third most common pattern, there are intrusive obsessional thoughts without a compulsion. Such obsessions are usually r4re titious thoughts of a sexual or aggressive act that is reprehensible to the patient. Symmetry: - This is the fourth most common pattern in which there is an obsession for symmetry or precision, which can lead to compulsion of slowness. Patients can literally take hours to shave their faces or to eat a meal.","pyqMatches":[{"year":"2014","no":2105,"q":"Following are the major symptoms of obsessive compulsive disorders ?","o":["Contamination","Pathological doubts","Intrusive thoughts","All the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8553, 'Psychiatry', 'Schizophrenia & Psychosis', 'Moderate', 'Psychiatry', 121, '{"id":8553,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Moderate","source":"Psychiatry","sourceNo":121,"q":"All are true about narcolepsy except:","o":["Day dreaming","Hypnagogic hallucinations","Cataplexy","Sudden sleep e) Decreased REM latency"],"a":0,"e":"Ans. (A) Day dreaming [Ref Neeraj Ahuja 7th/ I j8-39; Kaplan & Sailockls Textbook of psychiatry 11th/547-50; Harrison 19th/189, t7th/172- ZB; CMDT 2016/1072] Narcolepsy: Disorder characterized by excessive daytime sleepiness often distributed night time sleep and disturbances in REM sleep. Hallmark of this disorder is decreased REM latency, I.e. decreased latent period before the first REM period occurs. Normal REM latency is 90- 100 minutes, in narcolepsy, REM sleep occurs within 10 minutes of the onset of sleep. Classical tetrad of symptoms: Sleep attacks (MC) Cataplexy Hallucinations at sleep onset (Hypnagogic) and upon waking (Hypnopompic) Sleep paralysis.","pyqMatches":[{"year":"2014","no":2082,"q":"All are true about narcolepsy except:","o":["Day dreaming","Hypnagogic hallucinations","Cataplexy","Sudden sleep e) Decreased REM latency"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8554, 'Psychiatry', 'Schizophrenia & Psychosis', 'Moderate', 'Psychiatry', 122, '{"id":8554,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Moderate","source":"Psychiatry","sourceNo":122,"q":"Which of the following is not a side effect of quetiapine?","o":["Dry mouth","Hair loss","Sudden cardiac death","Dyspepsia"],"a":1,"e":"Ans. B. Hair loss [Ref Goodman & Gilman li''Ve p. 463-466] Quetiapine is an atypical antipsychotic used for the treatment of schizophrenia, bipolar disorder, and major depressive disorder. Very Common Less common Rare Dry mouth High blood pressure Prolonged QT interval Dizziness Orthostatic hypotension Sudden cardiac death Headache High blood cholesterol Syncope Somnolence Elevated serum triglycerides Diabetic ketoacidosis Nausea Abdominal pain Restless legs syndrome Vomiting Constipation Hyponatraemia, low blood sodium. Increased appetite Increased appetite Jaundice Sore throat Increased liver enzymes Pancreatitis Trouble moving Backache Agranulocytosis Rapid heartbeat Insomnia Seizure Weakness Fatigue Cardiomyopathy Pain Suicidal ideation Dyspepsia (Indigestion) Priapism Peripheral edema Neuroleptic malignant syndrome Dysphagia Tardive Dyskinesia. Weight gain","pyqMatches":[{"year":"2016","no":1783,"q":"Which of the following is not a side effect of quetiapine?","o":["Dry mouth","Hair loss","Sudden cardiac death","Dyspepsia"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8555, 'Psychiatry', 'Schizophrenia & Psychosis', 'Hard', 'Psychiatry', 123, '{"id":8555,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Hard","source":"Psychiatry","sourceNo":123,"q":"DOC for schizophrenic patient with poor oral absorption is?","o":["Clozapine","Fluphenazine","Sulpride","Penfluridol"],"a":1,"e":"Ans. B. Fluphenazine [Ref: Ther Adv Psychopharmacol. 2014 Oct; 4(5): 198-219.doi: 10.1177/2045125314540297] Long-acting injectable (LAI) antipsychotics (APs) (LAI APs) have proved effective in schizophrenia and other severe psychotic disorders because they assure stable blood levels, leading to a reduction of the risk of relapse. LAIs bypass the initial deactivating process by avoiding first-pass metabolism in the liver.","pyqMatches":[{"year":"2016","no":1782,"q":"DOC for schizophrenic patient with poor oral absorption is?","o":["Clozapine","Fluphenazine","Sulpride","Penfluridol"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8556, 'Psychiatry', 'Miscellaneous', 'Moderate', 'Psychiatry', 124, '{"id":8556,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Psychiatry","sourceNo":124,"q":"TCAs are contraindicated in all of the following except?","o":["Narrow angle glaucoma","Prostate hypertrophy","A patient on MOA inhibitors","Impaired renal function"],"a":3,"e":"Ans. D. Impaired renal function [Ref Lippincott p. 81] Common Contraindications of TCAs","pyqMatches":[{"year":"2016","no":1781,"q":"TCAs are contraindicated in all of the following except?","o":["Narrow angle glaucoma","Prostate hypertrophy","A patient on MOA inhibitors","Impaired renal function"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8557, 'Psychiatry', 'Substance Use Disorders', 'Easy', 'Psychiatry', 125, '{"id":8557,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":125,"q":"Loading dose of diazepam for alcohol withdrawal is?","o":["80mg","50mg","40mg","20mg"],"a":3,"e":"Ans. D. 20mg Rigid: 10 mg four times daily Flexible: 10 mg every 4-6 hours asneeded based on symptoms to a maximum of 60 mg/day Front loading: 20 mg every 2-4 hours until sedation is achieved; then 10 mg every 4-6 hours as needed to a maximum of 60 mg/day","pyqMatches":[{"year":"2016","no":1780,"q":"Loading dose of diazepam for alcohol withdrawal is?","o":["80mg","50mg","40mg","20mg"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8558, 'Psychiatry', 'ECT & Biological Treatments', 'Easy', 'Psychiatry', 126, '{"id":8558,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Easy","source":"Psychiatry","sourceNo":126,"q":"Confabulation is?","o":["A state of confusion where patient is not able to describe the details","Purposefully fabricating stories to project a certain image","Filling up to gaps by fabrication to cover lapses in memory","A feeling of strangeness to familiar situations or events."],"a":2,"e":"Ans. C. Filling up to gaps by fabrication to cover lapses in memory [Ref Kaplan & Sadock''s 10th/e p. 275] Confabulation It is a type of Paramnesia (Distorted or falsified recall of events in relation to details or their temporal relationships) Unintentional filling of gaps of memory with material which are untrue and fanciful.","pyqMatches":[{"year":"2016","no":1757,"q":"Confabulation is?","o":["A state of confusion where patient is not able to describe the details","Purposefully fabricating stories to project a certain image","Filling up to gaps by fabrication to cover lapses in memory","A feeling of strangeness to familiar situations or events."],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8559, 'Psychiatry', 'Substance Use Disorders', 'Moderate', 'Psychiatry', 127, '{"id":8559,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Moderate","source":"Psychiatry","sourceNo":127,"q":"Alcohol withdrawal is not associated with?","o":["Seizure","Amnesia","Tremers","Delirium"],"a":1,"e":"Ans. B. Amnesia [Ref: Niraj Ahuja 6th/e p. 41] Amnesia occurs during acute intoxication (not during withdrawal).","pyqMatches":[{"year":"2016","no":1758,"q":"Alcohol withdrawal is not associated with?","o":["Seizure","Amnesia","Tremers","Delirium"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8560, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 128, '{"id":8560,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":128,"q":"Drug of choice for Tourette syndrome is?","o":["Haloperidol","Amantidine","Propanolol","Diazepam"],"a":0,"e":"Ans. A. Haloperidol [Ref Kaplan & Saddock 10`Ve p. 557] Medication for tic suppression (Tourrete syndrome) Neuroleptics - Pimozide, along with haloperidol and fluphenazine are the medications with the most proven efficacy in controlling tics.","pyqMatches":[{"year":"2016","no":1779,"q":"Drug of choice for Tourette syndrome is?","o":["Haloperidol","Amantidine","Propanolol","Diazepam"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8561, 'Psychiatry', 'ECT & Biological Treatments', 'Easy', 'Psychiatry', 129, '{"id":8561,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Easy","source":"Psychiatry","sourceNo":129,"q":"Scatologia is?","o":["Eating disorder","Sleep disorder","Paraphilia","Defense mechanism"],"a":2,"e":"Ans. C. Paraphilia [Ref: Niraj Ahuja 6th/e p. 133, 134] Scatologia, also called Coprolalia, is a deviant sexual practice in which sexual pleasure is obtained through the compulsive use of obscene language. The affected person commonly satisfies his desires through obscene telephone calls, usually to strangers.","pyqMatches":[{"year":"2016","no":1778,"q":"Scatologia is?","o":["Eating disorder","Sleep disorder","Paraphilia","Defense mechanism"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8562, 'Psychiatry', 'Miscellaneous', 'Hard', 'Psychiatry', 130, '{"id":8562,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Hard","source":"Psychiatry","sourceNo":130,"q":"A 40 year old married male thinks that he is multitalented and is always overconfident. He never listens to his family or friends. Infact whenever anyone gives him any advice, he thinks that they have some motive against him. He is always suspicious of his wife. All these are feature of?","o":["Borderline personality disorder","Schizoid personality disorder","Paranoid personality disorder","Histrionic personality disorder"],"a":2,"e":"Ans. C. Paranoid personality disorder [Ref Namboodiri 3rdle p. 303; Niraj Ahuja ele p. 123] Paranoid personality disorder: It is characterized by generalized mistrust and suspiciousness about the motives and actions of others and a tendency to interpret them as malevolent. The patient believes that:","pyqMatches":[{"year":"2016","no":1759,"q":"A 40 year old married male thinks that he is multitalented and is always overconfident. He never listens to his family or friends. Infact whenever anyone gives him any advice, he thinks that they have some motive against him. He is always suspicious of his wife. All these are feature of?","o":["Borderline personality disorder","Schizoid personality disorder","Paranoid personality disorder","Histrionic personality disorder"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8563, 'Psychiatry', 'Miscellaneous', 'Moderate', 'Psychiatry', 131, '{"id":8563,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Psychiatry","sourceNo":131,"q":"A 25 years old male is not happy with its gender and is always in distress due to this. He wants to change sex and have vagina. It comes under?","o":["Transsexualism","Dual role transvestism","Gender dysphoria","Sexual maturation"],"a":2,"e":"Ans. C. Gender dysphoria [Ref Encyclopedia of relationships across the life span p.191] * Gender dysphoria (formerly Gender Identity Disorder) - It is defined by strong, persistent feelings of identification with the opposite gender and discomforts with one''s own assigned sex that results in significant distress or impairment. - In these cases, the assigned sex and gender do not match the person''s gender identity, and the person is transgender.","pyqMatches":[{"year":"2016","no":1777,"q":"A 25 years old male is not happy with its gender and is always in distress due to this. He wants to change sex and have vagina. It comes under?","o":["Transsexualism","Dual role transvestism","Gender dysphoria","Sexual maturation"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8564, 'Psychiatry', 'Psychotherapy & Behavioral Sciences', 'Easy', 'Psychiatry', 132, '{"id":8564,"subject":"Psychiatry","chapter":"Psychotherapy & Behavioral Sciences","difficulty":"Easy","source":"Psychiatry","sourceNo":132,"q":"Characteristic of histrionic personality disorder is?","o":["Violation of rules of society","Attention - seeking behavior","Unstable interpersonal relationship","Grandiose behavior"],"a":1,"e":"Ans. B. Attention - seeking behavior [Ref Niraj Ahuja 6''\"/e p. 122] Patients with histrionic personality disorder display excessive emotionality and attention-seeking behavior. Other options Violation of rules of society → antisocial personality disorder Unstable interpersonal relationship → borderline personality disorder Grandiose behavior → narcissistic personality disorder","pyqMatches":[{"year":"2016","no":1760,"q":"Characteristic of histrionic personality disorder is?","o":["Violation of rules of society","Attention - seeking behavior","Unstable interpersonal relationship","Grandiose behavior"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8565, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 133, '{"id":8565,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":133,"q":"Personality type seen in schizophrenia is?","o":["Schizoid","Paranoid","Borderline","All of the above"],"a":3,"e":"Ans. D. All of the above [Ref Niraj Ahuja 6th/e p. 125 & Internet] Schizophrenia is associated with 3 types of personality disorders i.e. schizoid, borderline and paranoid.","pyqMatches":[{"year":"2016","no":1761,"q":"Personality type seen in schizophrenia is?","o":["Schizoid","Paranoid","Borderline","All of the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8566, 'Psychiatry', 'Psychotherapy & Behavioral Sciences', 'Easy', 'Psychiatry', 134, '{"id":8566,"subject":"Psychiatry","chapter":"Psychotherapy & Behavioral Sciences","difficulty":"Easy","source":"Psychiatry","sourceNo":134,"q":"Irresistible urge to drink alcohol is called?","o":["Kleptomania","Pyromania","Dipsomania","Trichotillomania"],"a":2,"e":"Ans. C. Dipsomania [Ref Peculiarities of behavior] Dipsomania is characterized by periodic bouts of uncontrollable craving for alcohol.","pyqMatches":[{"year":"2016","no":1762,"q":"Irresistible urge to drink alcohol is called?","o":["Kleptomania","Pyromania","Dipsomania","Trichotillomania"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8567, 'Psychiatry', 'Miscellaneous', 'Moderate', 'Psychiatry', 135, '{"id":8567,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Psychiatry","sourceNo":135,"q":"Which of the following is not a culture bound syndrome?","o":["Amok","Latah","Dhat","Von-Gogh"],"a":3,"e":"Ans. D. Von-Gogh [Ref Niraj Ahuja 6''/e p. 65] Important culture-bound syndromes Ataque de nervios Dhat syndrome Khyal cap Ghost sickness Kufungisisa Maladi moun Nervios Shenjing shuairuo Taijin kyofusho Susto Amok Koro Latah Windigo","pyqMatches":[{"year":"2016","no":1776,"q":"Which of the following is not a culture bound syndrome?","o":["Amok","Latah","Dhat","Von-Gogh"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8568, 'Psychiatry', 'General Psychiatry', 'Hard', 'Psychiatry', 136, '{"id":8568,"subject":"Psychiatry","chapter":"General Psychiatry","difficulty":"Hard","source":"Psychiatry","sourceNo":136,"q":"A 39 years old male patient presents with waxy flexibility, negativism and rigidity. Most probable diagnosis is?","o":["Excitatory catatonia","Stuporous catatonia","Paranoid schizophrenia","None"],"a":1,"e":"Ans. B. Stuporous catatonia [Ref Neeraj Ahuja &hie p. 62, 63] Stuporous (retarded) catatonia : Characterized by extreme retardation of psychomotor function, which includes mutism, rigidity, negativism, posturing, echolalia, Echopraxia, Catalepsy (waxy flexibility), ambitendency, gegenhalten, streotypies, stupor, Mannerism, Grimicing, Automatic obedience, and verbigeration.","pyqMatches":[{"year":"2016","no":1763,"q":"A 39 years old male patient presents with waxy flexibility, negativism and rigidity. Most probable diagnosis is?","o":["Excitatory catatonia","Stuporous catatonia","Paranoid schizophrenia","None"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8569, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 137, '{"id":8569,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":137,"q":"Suicide rate in India is?","o":["10.5 /100,000","12.5/ 100,000","14.5/ 100,000","18/ 100,000"],"a":0,"e":"Ans. A. 10.5 /100,000 [Ref Internet; Indian 1 Psychiatry. 2012 Oct-Dec; 54(4): 304- 319.doi:10.4103/0019-5545.104793] India ranks 43rd in descending order of rates of suicide with a rate of 10.6/100,000 reported in 2009 (WHO suicide rates). In the most recent National Crime Records Bureau (NCRB; Ministry of Home Affairs) report the rate in 2010 rose to 11.4 per 100,000 population. The male: female suicide ratio was 1.78 in India in 2008 and 2009.","pyqMatches":[{"year":"2016","no":1775,"q":"Suicide rate in India is?","o":["10.5 /100,000","12.5/ 100,000","14.5/ 100,000","18/ 100,000"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8570, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 138, '{"id":8570,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":138,"q":"DHAT syndrome is?","o":["Passage of blood in urine","Passage of semen in urine","Passage of pus in urine","None"],"a":1,"e":"Ans. B. Passage of semen in urine [Ref Encyclopedia of multicultural psychology p. 135] Dhat syndrome is a culture-bound syndrome prevalent in Indian subcontinent in which male patients report that they suffer from premature ejaculation or impotence, and believe that they are passage of semen (dhat) in urine. The condition has no known organic cause.","pyqMatches":[{"year":"2016","no":1774,"q":"DHAT syndrome is?","o":["Passage of blood in urine","Passage of semen in urine","Passage of pus in urine","None"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8571, 'Psychiatry', 'Child & Adolescent Psychiatry', 'Moderate', 'Psychiatry', 139, '{"id":8571,"subject":"Psychiatry","chapter":"Child & Adolescent Psychiatry","difficulty":"Moderate","source":"Psychiatry","sourceNo":139,"q":"Most appropriate test for child psychologist to evaluate the intellectual ability of a 3 year old is?","o":["Stanford Binet scale","Denver development scale","Alexander''s pass along test","Rorschach inkblot test"],"a":0,"e":"Ans. A. Stanford Binet scale [Ref Psychological testing p. 101] Stanford-Binet Intelligence Scale The Stanford-Binet Intelligence Scale is an individually administered standardized test that measures intelligence and cognitive abilities in children and adults, from age two through mature adulthood. The Stanford-Binet Intelligence Scale is now in its fifth edition (SB5) and was released in 2003. It is a cognitive ability and intelligence test that is used to diagnose developmental or intellectual deficiencies in young children.","pyqMatches":[{"year":"2016","no":1764,"q":"Most appropriate test for child psychologist to evaluate the intellectual ability of a 3 year old is?","o":["Stanford Binet scale","Denver development scale","Alexander''s pass along test","Rorschach inkblot test"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8572, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 140, '{"id":8572,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":140,"q":"Treatment of choice for akathesia is?","o":["Phenytoin","Propranolol","Dantrolene","Lithium"],"a":1,"e":"Ans. B. Propranolol [Ref Kaplan & Saddock''s 10th le p. 1020] \"The first line drug for akathisia is most commonly alpha-blocker\".","pyqMatches":[{"year":"2016","no":1765,"q":"Treatment of choice for akathesia is?","o":["Phenytoin","Propranolol","Dantrolene","Lithium"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8573, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 141, '{"id":8573,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":141,"q":"Functional somatic disorder is?","o":["Somatization disorder","Chronic fatigue syndrome","Hypochondriasis","Body dysmorphic disorder"],"a":1,"e":"Ans. B. Chronic fatigue syndrome Functional somatic syndromes: They are characterized more by symptoms, suffering and disability than by disease specific, demonstrable abnormalities of structure or function, i.e. There is reporting of somatic symptoms and resultant disability rather than on the evidence of underlying convention disease process Three most common functional somatic syndromes are fibromyalgia, Irritable bowel syndrome and chronic fatigue syndrome.","pyqMatches":[{"year":"2016","no":1773,"q":"Functional somatic disorder is?","o":["Somatization disorder","Chronic fatigue syndrome","Hypochondriasis","Body dysmorphic disorder"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8574, 'Psychiatry', 'Psychotherapy & Behavioral Sciences', 'Easy', 'Psychiatry', 142, '{"id":8574,"subject":"Psychiatry","chapter":"Psychotherapy & Behavioral Sciences","difficulty":"Easy","source":"Psychiatry","sourceNo":142,"q":"Cardinal element of behavior therapy is?","o":["Modeling","Learning","Conditioning","Guidance"],"a":1,"e":"Ans.B. Learning [Ref Niraj Ahuja 6''1* p. 220] Behavior therapy is based on the assumption that all behaviors (normal or abnormal) are learning response. Normal and abnormal behaviors are subject to the laws of learning and the same laws can be used to change them. Behavior therapy is based on theories of learning and aims at changing the maladaptive behavior and substituting it with adaptive behavior.","pyqMatches":[{"year":"2016","no":1766,"q":"Cardinal element of behavior therapy is?","o":["Modeling","Learning","Conditioning","Guidance"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8575, 'Psychiatry', 'Substance Use Disorders', 'Easy', 'Psychiatry', 143, '{"id":8575,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":143,"q":"Tolerance is seen in?","o":["Alcohol dependent syndrome","Schizophrenia","OCD","All of the above"],"a":0,"e":"Ans. A. Alcohol dependent syndrome [Ref Kaplan & Saddock''s 10thle p. 382] Alcohol dependent syndrome Alcohol dependent syndrome uses the same criteria for dependence for other substances, i.e., three or more of the following : -","pyqMatches":[{"year":"2016","no":1767,"q":"Tolerance is seen in?","o":["Alcohol dependent syndrome","Schizophrenia","OCD","All of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8576, 'Psychiatry', 'Anxiety & Related Disorders', 'Easy', 'Psychiatry', 144, '{"id":8576,"subject":"Psychiatry","chapter":"Anxiety & Related Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":144,"q":"Treatment of choice for generalized anxiety disorder is?","o":["Benzodiazepines","Neuroleptics","Beta blockers","Barbiturates"],"a":0,"e":"Ans. A. Benzodiazepines [Ref Harrison 17th/e p. 2712; Kaplan & Saddock''s 10th/e p. 626] Treatment of generalized anxiety disorder Benzodiazepines are the drug of choice. Drugs in this group are diazepam, Lorazepam, Alprazolam, Oxazepam, chlordiazepoxide.","pyqMatches":[{"year":"2016","no":1768,"q":"Treatment of choice for generalized anxiety disorder is?","o":["Benzodiazepines","Neuroleptics","Beta blockers","Barbiturates"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8577, 'Psychiatry', 'Anxiety & Related Disorders', 'Easy', 'Psychiatry', 145, '{"id":8577,"subject":"Psychiatry","chapter":"Anxiety & Related Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":145,"q":"Generalized anxiety disorder is diagnosed when anxiety and worry continues for at least?","o":["2 months","4 months","6 months","8 months"],"a":2,"e":"Ans. C. 6 months [Ref Harrison 17\"/e p. 2712; Kaplan & Saddock''s 10th/e p. 626] GENERALIZED ANXIETY DISORDER This is characterized by excessive anxiety and worry which are persistent & generalized and not restricted to any specific situation or object. Excessive anxiety worry occur for at least 6 months.","pyqMatches":[{"year":"2016","no":1769,"q":"Generalized anxiety disorder is diagnosed when anxiety and worry continues for at least?","o":["2 months","4 months","6 months","8 months"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8578, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 146, '{"id":8578,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":146,"q":"Most important receptors involved with schizophrenia are?","o":["GABAA","GABA,,","DZd","5-HT"],"a":2,"e":"Ans. C. DZd [Ref Kaplan & Saddock''s 10th le p. 470] Dopamine hypothesis is the most accepted hypothesis for schizophrenia. There is hyperactivity of dopaminergic system. This hypothesis is supported by :","pyqMatches":[{"year":"2016","no":1772,"q":"Most important receptors involved with schizophrenia are?","o":["GABAA","GABA,,","DZd","5-HT"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8579, 'Psychiatry', 'Substance Use Disorders', 'Easy', 'Psychiatry', 147, '{"id":8579,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":147,"q":"Risk factor for suicide is?","o":["Increased serotonin","Drug abuse","Female sex","Married person"],"a":1,"e":"Ans.B. Drug abuse [Ref: Niraj Ahuja ele p. 236, 237; Essentials of psychiatry 4th/e p. 734] Causes/Risk factors for suicide Psychiatric disorders: - Depression (most common), alcoholism (2nd mc), Drug/Substance dependence, Schizophrenia, Dementia. Physical illness: - Cancer, AIDS, Multiple sclerosis, Head trauma. Psychosocial factors: - Failure in love, marital difficulties, family dispute, illegitimate pregnancy. Biological factors: - Decrease in serotonin Other - Male sex, Age > 40 years, Single (Unmarried, divorced or widowed), previous suicide attempt, social isolation.","pyqMatches":[{"year":"2016","no":1770,"q":"Risk factor for suicide is?","o":["Increased serotonin","Drug abuse","Female sex","Married person"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8580, 'Psychiatry', 'Miscellaneous', 'Hard', 'Psychiatry', 148, '{"id":8580,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Hard","source":"Psychiatry","sourceNo":148,"q":"A 25 years old male c/o recurrent abdominal pain but biochemical assays and ultrasound abdomen is normal. He also complains of constant headaches. He suddenly complains of loss of vision of bilateral eyes. Ophthalmologist finds nothing on examination. Symptoms are most probably due to","o":["Bilateral optic neuritis","Posterior inferior cerebellar artery infarct","Malingering","Factitious disorder"],"a":3,"e":"Ans. D. Factitious disorder Factitious disorder It is also known as Hospital addiction, hospital hoboes, or Professional patient. The term Munchausen syndrome is used for those patients who repeatedly simulate or fake diseases (intentionally) for the sole purpose of obtaining medical attention. There is no other recognizable motive (in contrast to malingering). The typical presentation of Munchausen syndrome is characterized by a restless journey from doctor to doctor and hospital to hospital, an ever-changing list of complaints and symptoms. The patient tries to maintain the sick role to obtain medical attention. There may be evidence of earlier treatment usually surgical procedure, for example, multiple surgical scars (gridiron abdomen).","pyqMatches":[{"year":"2016","no":1771,"q":"A 25 years old male c/o recurrent abdominal pain but biochemical assays and ultrasound abdomen is normal. He also complains of constant headaches. He suddenly complains of loss of vision of bilateral eyes. Ophthalmologist finds nothing on examination. Symptoms are most probably due to","o":["Bilateral optic neuritis","Posterior inferior cerebellar artery infarct","Malingering","Factitious disorder"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8581, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 149, '{"id":8581,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":149,"q":"Emile Durkheim is linked with work on which condition in psychiatry?","o":["Suicide","Obsessive compulsive disorder","Anxiety disorder","Schizophrenia"],"a":0,"e":"Ans. A. Suicide Suicide (French: Le Suicide) It was a groundbreaking book in the field of sociology. It was written by French sociologistEmile Durliiheim and pubtshed in","pyqMatches":[{"year":"2014","no":2056,"q":"Emile Durkheim is linked with work on which condition in psychiatry?","o":["Suicide","Obsessive compulsive disorder","Anxiety disorder","Schizophrenia"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8582, 'Psychiatry', 'Psychotherapy & Behavioral Sciences', 'Easy', 'Psychiatry', 150, '{"id":8582,"subject":"Psychiatry","chapter":"Psychotherapy & Behavioral Sciences","difficulty":"Easy","source":"Psychiatry","sourceNo":150,"q":"Highest insight is ?","o":["Intellectual","Emotional","Psychological","Affective"],"a":1,"e":"Ans. b. Emotional Neziroglu and Stevens proposed four different levels of insights: True emotional insight Intellectual insight Partial internally and externally based insight Denial of illness True emotional insight is representative of the highest level of insight possible. In it the patients'' awareness and understanding of their own thoughts, feelings and motives can be used to change behavior.","pyqMatches":[{"year":"2014","no":2057,"q":"Highest insight is ?","o":["Intellectual","Emotional","Psychological","Affective"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8583, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 151, '{"id":8583,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":151,"q":"Extracampine hallucinations term was given by ?","o":["Eugene Bleuler","William Harvey","Robert Macinoff","Eden Speroff"],"a":0,"e":"Ans. A. Eugene Bleuler Extracampine hallucinations The term extracampine is indebted to Latin words extra - outside and campaneus - field. It was introduced in or shortly before 1903 by Swiss Psychiatrist Eugene Bleuler to denote a hallucination that is experienced by affected individual as being outside the range of normal perception.","pyqMatches":[{"year":"2014","no":2058,"q":"Extracampine hallucinations term was given by ?","o":["Eugene Bleuler","William Harvey","Robert Macinoff","Eden Speroff"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8584, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 152, '{"id":8584,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":152,"q":"Hypomimia is ?","o":["Decreased ability to copy","Decreased execution","Deficit of expression by gesture","Deficit of fluent speech"],"a":2,"e":"Ans. C. Deficit of expression by gesture Hypomimia Hypomimia or amimia is a deficit or absence of expression by gesture or mimicry. This is usually most obvious as a lack of facial expressive mobility (mask - like facies). This is a feature of frontal subcortical disease.","pyqMatches":[{"year":"2014","no":2059,"q":"Hypomimia is ?","o":["Decreased ability to copy","Decreased execution","Deficit of expression by gesture","Deficit of fluent speech"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8585, 'Psychiatry', 'General Psychiatry', 'Easy', 'Psychiatry', 153, '{"id":8585,"subject":"Psychiatry","chapter":"General Psychiatry","difficulty":"Easy","source":"Psychiatry","sourceNo":153,"q":"Serial 7 substraction is used to test ?","o":["Working memory","Long term memory","Mathematical ability","Recall power"],"a":0,"e":"Ans. A. Working memory Serial sevens substraction test Serial sevens, counting down from one hundred by sevens, is a clinical test used to test mental function; for example, to help assess mental status after possible head injury or in suspected cases of dementia. This well-known test, in active documented use since at least l944,was adopted as part of the mini-mental state examination. The test is also used in determining when a patient is becoming unconscious under anaesthetic, for example prior to major dental surgery.","pyqMatches":[{"year":"2014","no":2060,"q":"Serial 7 substraction is used to test ?","o":["Working memory","Long term memory","Mathematical ability","Recall power"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8586, 'Psychiatry', 'General Psychiatry', 'Easy', 'Psychiatry', 154, '{"id":8586,"subject":"Psychiatry","chapter":"General Psychiatry","difficulty":"Easy","source":"Psychiatry","sourceNo":154,"q":"Which of the following are sections of mental state examination?","o":["Mood and affect","Speech and language","Cognition","All the above"],"a":3,"e":"Ans. D. All the above","pyqMatches":[{"year":"2014","no":2061,"q":"Which of the following are sections of mental state examination?","o":["Mood and affect","Speech and language","Cognition","All the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8587, 'Psychiatry', 'Psychotherapy & Behavioral Sciences', 'Moderate', 'Psychiatry', 155, '{"id":8587,"subject":"Psychiatry","chapter":"Psychotherapy & Behavioral Sciences","difficulty":"Moderate","source":"Psychiatry","sourceNo":155,"q":"Obsessive attention by an individual towards another person is called ?","o":["Stalking","Percieving","Following","Pressurizing"],"a":0,"e":"Ans. A. Stalking Stalking Stalking is unwanted or obsessive attention by an individual or group toward another Person. Stalking behaviors are related to harassment and intimidation and may include following the victim in person or monitoring them. The word stalking is used, with some differing meanings, in psychology and psychiatry and also in some legal jurisdictions as a term for a criminal offense.","pyqMatches":[{"year":"2014","no":2062,"q":"Obsessive attention by an individual towards another person is called ?","o":["Stalking","Percieving","Following","Pressurizing"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8588, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 156, '{"id":8588,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":156,"q":"Most common of all psychiatric disorders are -","o":["Anxiety disorder","Schizophrenia","Depression","Mania"],"a":0,"e":"Ans. A. Anxiety disorder Most common psychiatric disorder > Anxiety disorders. 2d most common psychiatric disorder > Depression.","pyqMatches":[{"year":"2014","no":2063,"q":"Most common of all psychiatric disorders are","o":["Anxiety disorder","Schizophrenia","Depression","Mania"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8589, 'Psychiatry', 'Schizophrenia & Psychosis', 'Hard', 'Psychiatry', 157, '{"id":8589,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Hard","source":"Psychiatry","sourceNo":157,"q":"Patient wants to scratch for itching in his amputated limb is an example of ?","o":["Illusion","Pseudohallucination","Phantom limb hallucination","Autoscopy hallucination"],"a":2,"e":"Ans. C. Phantom limb hallucination Phantom limb hallucination - The person feels his body parts intact in their respective places even after they are lost through amputation or injury. In the question given patient feels itching in the amputated limb and tries to scratch the limb. Thus it is an example of phantom limb hallucination.","pyqMatches":[{"year":"2014","no":2064,"q":"Patient wants to scratch for itching in his amputated limb is an example of ?","o":["Illusion","Pseudohallucination","Phantom limb hallucination","Autoscopy hallucination"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8590, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 158, '{"id":8590,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":158,"q":"Myxedema madness includes ?","o":["Auditory hallucinations and paranoia","Visual hallucinations and depression","Auditory hallucinations and depression","Paranoia and depression"],"a":0,"e":"Ans. A. Auditory hallucinations and paranoia Psychiatric disorders in hypothyroidism These include depressed mood, apathy, impaired memory and other cognitive defects. Hypothyroidism can contribute to the development of treatment refractory depression. Myxedema madness consisting of auditory hallucinations and paranoia is seen in some Patients.","pyqMatches":[{"year":"2014","no":2065,"q":"Myxedema madness includes ?","o":["Auditory hallucinations and paranoia","Visual hallucinations and depression","Auditory hallucinations and depression","Paranoia and depression"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8591, 'Psychiatry', 'Miscellaneous', 'Moderate', 'Psychiatry', 159, '{"id":8591,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Psychiatry","sourceNo":159,"q":"APACHE II does not include ?","o":["Acute physiology score","Age","Sex","Chronic health evaluation"],"a":2,"e":"Ans. C. Sex Acute physiology and chronic health evaluation Knaus et al (1981) introduced the first the Acute Physiology and Chronic Health Evaluation (APACHE) model in 1981 and revised it to APACHE II in 1985. APACHE III was presented in 1991 but as the regression analysis modelling is not in the public domain its uptake has been slow. APACHE II is made up of four basic comPonents: 1) Acute physiology score; 2) Chronic health evaluation; 3) Age; 4) Urgency of admission to critical care","pyqMatches":[{"year":"2014","no":2066,"q":"APACHE II does not include ?","o":["Acute physiology score","Age","Sex","Chronic health evaluation"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8592, 'Psychiatry', 'Mood Disorders', 'Hard', 'Psychiatry', 160, '{"id":8592,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Hard","source":"Psychiatry","sourceNo":160,"q":"SSRIs should be carefully used in the young for the management of depression due to increase in?","o":["Nihilism ideation","Guilt ideation","Suicidal ideation","Envious ideation"],"a":2,"e":"Ans. C. Suicidal ideation In 2003, th UK Medicine and Health Care products regulatory agency concluded that all SSNs, with the exception of fluoxetine, were contraindicated in the treatment of depression in young people due to increase in suicidal ideation and dubious efficacy.","pyqMatches":[{"year":"2014","no":2067,"q":"SSRIs should be carefully used in the young for the management of depression due to increase in?","o":["Nihilism ideation","Guilt ideation","Suicidal ideation","Envious ideation"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8593, 'Psychiatry', 'ECT & Biological Treatments', 'Moderate', 'Psychiatry', 161, '{"id":8593,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Moderate","source":"Psychiatry","sourceNo":161,"q":"If a person is asked, \"what will he do if he sees a house on fire\"?, Then what is being tested in that person ?","o":["Social judgement","Test judgement","Response judgement","None of the above"],"a":1,"e":"AnS. B. Test judgement Judgement It is the ability to assess a situation correctly and act appropriately within that situation'' Social judgement: is observed during the hospital stay and during the interview session. It includes evaluation of personal judgement. Test Judgement: is assessed by asking the patient what he would do in certain test situations like - house on fire, man lying on road. It is rated as good/ intact normal or poor/ impaired/abnormal''","pyqMatches":[{"year":"2014","no":2068,"q":"If a person is asked, \"what will he do if he sees a house on fire\"?, Then what is being tested in that person ?","o":["Social judgement","Test judgement","Response judgement","None of the above"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8594, 'Psychiatry', 'ECT & Biological Treatments', 'Easy', 'Psychiatry', 162, '{"id":8594,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Easy","source":"Psychiatry","sourceNo":162,"q":"Illusion is a disorder of ?","o":["Thought","Perception","Affect","Emotion"],"a":1,"e":"Ans, B. Perception Disorders of perception","pyqMatches":[{"year":"2014","no":2071,"q":"Illusion is a disorder of ?","o":["Thought","Perception","Affect","Emotion"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8595, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 163, '{"id":8595,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":163,"q":"Rope seen as snake is an example of -","o":["Illusion","Hallucination","Delusion","Pseudohallucination"],"a":0,"e":"Ans. A. Illusion llusions are altered perception in which a real eternal object is combined with imagery to produce false internal percept. In simple words, illusion is misinterpretation of an actual sensory input. For example: -","pyqMatches":[{"year":"2014","no":2072,"q":"Rope seen as snake is an example of","o":["Illusion","Hallucination","Delusion","Pseudohallucination"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8596, 'Psychiatry', 'Schizophrenia & Psychosis', 'Hard', 'Psychiatry', 164, '{"id":8596,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Hard","source":"Psychiatry","sourceNo":164,"q":"Woman firmly and persistently feels her husband is cheating on her and she disapproves to accePt any proof given in the husbands support'' The other family members do not supportherbelief. This is anexample of-","o":["Illusion","Delusion","Hallucination","Perversion"],"a":1,"e":"Ans. B. Delusion In the question given the woman has a false unshakable belief that her husband is cheating on her and she disapproves all her relatives and proofs in support of her husband. Thus this is an example of delusion.","pyqMatches":[{"year":"2014","no":2073,"q":"Woman firmly and persistently feels her husband is cheating on her and she disapproves to accePt any proof given in the husbands support'' The other family members do not supportherbelief. This is anexample of","o":["Illusion","Delusion","Hallucination","Perversion"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8597, 'Psychiatry', 'Substance Use Disorders', 'Easy', 'Psychiatry', 165, '{"id":8597,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":165,"q":"Withdrawal of which of the following causes piloerecton?","o":["Morphine","Cannabis","Smoking","Alcohol"],"a":0,"e":"Ans. A. Morphine Manifestations of morphine withdrawal Lacrimation Anxiety & fear Sweating Restlessness r Yawning Gooseflash (Piloerection).","pyqMatches":[{"year":"2014","no":2075,"q":"Withdrawal of which of the following causes piloerecton?","o":["Morphine","Cannabis","Smoking","Alcohol"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8598, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 166, '{"id":8598,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":166,"q":"Schizotypal personality belongs to which cluster of personality disorders?","o":["A","B","C","D"],"a":0,"e":"Ans. A. A Cluster A: Paranoid, Schizoid, Schizotypal. Cluster B: Antisocial (Dissocial), Histrionic, Narcissistic, Borderline. Cluster C: Anxious (avoidant), Dependent, obsessive - compulsive (anankastic).","pyqMatches":[{"year":"2014","no":2076,"q":"Schizotypal personality belongs to which cluster of personality disorders?","o":["A","B","C","D"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8599, 'Psychiatry', 'Psychotherapy & Behavioral Sciences', 'Easy', 'Psychiatry', 167, '{"id":8599,"subject":"Psychiatry","chapter":"Psychotherapy & Behavioral Sciences","difficulty":"Easy","source":"Psychiatry","sourceNo":167,"q":"Cardinal feature of antisocial personality -","o":["Violation of rules of society","Attention - seeking behavior","Unstable interpersonal relationship","Grandiose behaviour"],"a":0,"e":"Ans. A. Violation of rules of society The essential features of antisocial personality disorder are a disregard for and violation of the rights of the other and the rules of the society.","pyqMatches":[{"year":"2014","no":2077,"q":"Cardinal feature of antisocial personality","o":["Violation of rules of society","Attention - seeking behavior","Unstable interpersonal relationship","Grandiose behaviour"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8600, 'Psychiatry', 'Child & Adolescent Psychiatry', 'Easy', 'Psychiatry', 168, '{"id":8600,"subject":"Psychiatry","chapter":"Child & Adolescent Psychiatry","difficulty":"Easy","source":"Psychiatry","sourceNo":168,"q":"Which personality disorder/s can be a part of autistic sPectrum of disorders?","o":["Schizoid","Schizotypical","Borderline","All the above"],"a":3,"e":"Ans. D. All the above Following personality disorders can be diagnosed later in life in patients with childhood autistic spectrum of disorders: Borderline, Obsessive compulsive, narcissitic, paranoid, schizotypical and, avoidant, personality.","pyqMatches":[{"year":"2014","no":2079,"q":"Which personality disorder/s can be a part of autistic sPectrum of disorders?","o":["Schizoid","Schizotypical","Borderline","All the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8601, 'Psychiatry', 'Miscellaneous', 'Hard', 'Psychiatry', 169, '{"id":8601,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Hard","source":"Psychiatry","sourceNo":169,"q":"Patients who are grandiose and require admiration from others has which type of personality?","o":["Narcissistic","Histrionic","Borderline","Antisocial"],"a":0,"e":"Ans. A. Narcissistic Grandiosity and admiration from others are feature of Narcissistic personality disorder.","pyqMatches":[{"year":"2014","no":2080,"q":"Patients who are grandiose and require admiration from others has which type of personality?","o":["Narcissistic","Histrionic","Borderline","Antisocial"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8602, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 170, '{"id":8602,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":170,"q":"Max duration of time spent is in NREM stage?","o":["I","II","III","IV"],"a":1,"e":"Ans, B. II REM sleep occupies 20-30% of total sleep and NREM sleep ocupies 60-70% (state I: 5-70%, stage II : 40-50%, stage III & IV : 15_20%)","pyqMatches":[{"year":"2012","no":1466,"q":"Max duration of time spent is in NREM stage ?","o":["I","II","III","IV"],"a":1,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":2081,"q":"Max duration of time spent is in NREM stage?","o":["I","II","III","IV"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8603, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 171, '{"id":8603,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":171,"q":"Spouse jealousy is a feature of ?","o":["Othello syndrome","Chronic alcoholism","Stockholm syndrome","Clerambault''s syndrome"],"a":0,"e":"Ans. A. Othello syndrome Othello Syndrome: When the content of delusions is predominantly jealousy (infidelity) involving the spouse, person feels an unreasonable fear that a partner has been unfaithful, is presently unfaithful, or plans to be unfaithful, it is called as Othello Syndrome or conjugal paranoia. Elaborate steps are taken to prevent the spouse to go outside (Locks the spouse, not allowing her to go outside).","pyqMatches":[{"year":"2014","no":2086,"q":"Spouse jealousy is a feature of ?","o":["Othello syndrome","Chronic alcoholism","Stockholm syndrome","Clerambault''s syndrome"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8604, 'Psychiatry', 'Schizophrenia & Psychosis', 'Moderate', 'Psychiatry', 172, '{"id":8604,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Moderate","source":"Psychiatry","sourceNo":172,"q":"All of the following are true about pseudohalluci​nations except ?","o":["Arises in inner subjective self","Patient describes the sensations being perceived by mind eye","Are under voluntary control","Distressing flashback of PTSD is a n example"],"a":2,"e":"Ans.C. Are under voluntary control Pseudohallucination Pseudohallucination is a perceptual experience, which differs from a hallucination in that it appears to arise in the inner subjective space, not through one of the external sensory organs. Patients tend to describe these sensations as being perceived with the ''inner eye'' or ''mind eye'' (or ear). However, like true hallucinations pseudohallucinations are not under voluntary control. Example include: Distressing flashbacks in post-traumatic stress disorder or the recently bereaved widow waking up to briefly ''see'' her husband sitting at the foot of the bed,","pyqMatches":[{"year":"2014","no":2087,"q":"All of the following are true about pseudohalluci​nations except ?","o":["Arises in inner subjective self","Patient describes the sensations being perceived by mind eye","Are under voluntary control","Distressing flashback of PTSD is a n example"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8605, 'Psychiatry', 'ECT & Biological Treatments', 'Easy', 'Psychiatry', 173, '{"id":8605,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Easy","source":"Psychiatry","sourceNo":173,"q":"Delirium is defined as ?","o":["Acute onset of disturbed consciousness","Chronic onset of disturbed consciousness","Progressive generalized impairment of intellectual functions and memory without impairment of consciousness","Disorientation without clouding of consciousness"],"a":0,"e":"Ans. A. Acute onset of disturbed consciousness Delirium is defined by the acute onset of fluctuating cognitive impairment and a disturbance of consciousness. It is also referred to as acute confusional state or acute organic brain syndrome.","pyqMatches":[{"year":"2014","no":2088,"q":"Delirium is defined as ?","o":["Acute onset of disturbed consciousness","Chronic onset of disturbed consciousness","Progressive generalized impairment of intellectual functions and memory without impairment of consciousness","Disorientation without clouding of consciousness"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8606, 'Psychiatry', 'Substance Use Disorders', 'Hard', 'Psychiatry', 174, '{"id":8606,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Hard","source":"Psychiatry","sourceNo":174,"q":"All the following drugs are used to prevent relapse and maintain abstinence in cases of alcohol withdrawal except ?","o":["Disulfiram","Acamprosate","Naltrexone","Propranolol"],"a":3,"e":"Ans. D. Propranolol Detoxification (treatment of withdrawal):- BZDs are the drugs of choice, e.g. chlordiazepoxiile (Id choice), Diazepam (2nd choice). Maintenance after detoxification (to prevent relapse and maintenance of abstinence):-","pyqMatches":[{"year":"2014","no":2089,"q":"All the following drugs are used to prevent relapse and maintain abstinence in cases of alcohol withdrawal except ?","o":["Disulfiram","Acamprosate","Naltrexone","Propranolol"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8607, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 175, '{"id":8607,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":175,"q":"Which is the most common type of persistent delusional disorder ?","o":["Delusion of persecution","Somatic delusion","Delusion of jealousy","Delusion of grandeur"],"a":0,"e":"Ans. A. Delusion of persecution Delusion of persecution is the most common type of persistent delusional disorder.","pyqMatches":[{"year":"2014","no":2094,"q":"Which is the most common type of persistent delusional disorder ?","o":["Delusion of persecution","Somatic delusion","Delusion of jealousy","Delusion of grandeur"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8608, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 176, '{"id":8608,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":176,"q":"Dysthymia is ?","o":["Chronic depression","Chronic mania","Bipolar disorder","Personality disorder"],"a":0,"e":"Ans. A. Chronic depression Persistent depressive disorder (Dysthymia) Depression may run a chronic course over years with fluctuation of mood interposed with symptom free intervals (less than 2 months). If symptoms persist for more than 2 years, they are referred to as persistent depressive disorder or dysthymia.","pyqMatches":[{"year":"2014","no":2095,"q":"Dysthymia is ?","o":["Chronic depression","Chronic mania","Bipolar disorder","Personality disorder"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8609, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 177, '{"id":8609,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":177,"q":"Bipolar II disorder includes ?","o":["Cyclothymic disorder","Dysthymia","Single maniac episode","Major depression and hypomania"],"a":3,"e":"Ans. D. Major depression and hypomania Bipolar II: One or more major depressive episodes together with at least 1 hypomanic episode.","pyqMatches":[{"year":"2014","no":2096,"q":"Bipolar II disorder includes ?","o":["Cyclothymic disorder","Dysthymia","Single maniac episode","Major depression and hypomania"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8610, 'Psychiatry', 'ECT & Biological Treatments', 'Hard', 'Psychiatry', 178, '{"id":8610,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Hard","source":"Psychiatry","sourceNo":178,"q":"Psychotic patient on antipsychotic drugs develops torticollis within 4 days of therapy. what is the treatment?","o":["Central anticholinergic","Peripheral anticholinergic","Beta blocker","Dantrolene"],"a":0,"e":"Ans. A. Central anticholinergic This is a case of drug induced muscular dystonia, which is treated by central anticholinergic. Drug of choice for antipsychotic induced extrapyramidal side effects","pyqMatches":[{"year":"2014","no":2099,"q":"Psychotic patient on antipsychotic drugs develops torticollis within 4 days of therapy. what is the treatment?","o":["Central anticholinergic","Peripheral anticholinergic","Beta blocker","Dantrolene"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8611, 'Psychiatry', 'Child & Adolescent Psychiatry', 'Moderate', 'Psychiatry', 179, '{"id":8611,"subject":"Psychiatry","chapter":"Child & Adolescent Psychiatry","difficulty":"Moderate","source":"Psychiatry","sourceNo":179,"q":"Eugene Blueler''s 4As include following except ?","o":["Autism","Affect","Anhedonia","Association"],"a":2,"e":"Ans. C. Anhedonia Bleuler''s 4 ''As'' are: (l) Ambivalence (2) Autism; (3) Affect disturbances (inappropriate affect); and (4) Association disturbances (loosening of association, thought disorder).","pyqMatches":[{"year":"2014","no":2108,"q":"Eugene Blueler''s 4As include following except ?","o":["Autism","Affect","Anhedonia","Association"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8612, 'Psychiatry', 'Substance Use Disorders', 'Easy', 'Psychiatry', 180, '{"id":8612,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":180,"q":"Appetite for nonnutritive substances is called ?","o":["Pica","Apprepritant","Bulimia","Bolean"],"a":0,"e":"Ans. A. Pica Pica is characterized by an appetite for substances that are largely non-nutritive, such as paper, clay, metal, chalk, soil, glass, or sand.","pyqMatches":[{"year":"2014","no":2111,"q":"Appetite for nonnutritive substances is called ?","o":["Pica","Apprepritant","Bulimia","Bolean"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8613, 'Psychiatry', 'Substance Use Disorders', 'Easy', 'Psychiatry', 181, '{"id":8613,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":181,"q":"Bad trip is seen with ?","o":["Cocaine","Cannabis","LSD","Heroin"],"a":2,"e":"Ans. C. LSD Acute panic reaction with loss of control on onself, called Bad trip, is characteristic of LSD or otJrer hallocinogens.","pyqMatches":[{"year":"2014","no":2114,"q":"Bad trip is seen with ?","o":["Cocaine","Cannabis","LSD","Heroin"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8614, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 182, '{"id":8614,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":182,"q":"Antipsychotic drug causing retinal pigment disorder is?","o":["Thiaoridazine","Clozapine","Chlorpromazine","None of the above"],"a":0,"e":"Ans. A. Thiaoridazine Blue pigmentation of skin, corneal and lenticular opacities, retinal degenration can occur with thioridazine.","pyqMatches":[{"year":"2014","no":2116,"q":"Antipsychotic drug causing retinal pigment disorder is?","o":["Thiaoridazine","Clozapine","Chlorpromazine","None of the above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8615, 'Psychiatry', 'ECT & Biological Treatments', 'Easy', 'Psychiatry', 183, '{"id":8615,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Easy","source":"Psychiatry","sourceNo":183,"q":"Antipsychotic drug with least extra pyramidal symptoms?","o":["Pimozide","Thioridazone","Clozapine","Flupromazine"],"a":2,"e":"Ans. C. Clozapine Antipsychotics with no extrapyramidal side effects clozapine, aripiprazole, quetiapine. Amongst typical antipsychotics, thioridazone has least extrapyramial side effects.","pyqMatches":[{"year":"2014","no":2117,"q":"Antipsychotic drug with least extra pyramidal symptoms?","o":["Pimozide","Thioridazone","Clozapine","Flupromazine"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8616, 'Psychiatry', 'Substance Use Disorders', 'Moderate', 'Psychiatry', 184, '{"id":8616,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Moderate","source":"Psychiatry","sourceNo":184,"q":"Following is true about alcoholic dependence syndrome except -","o":["No tolerance","Withdrawal symptoms","CAGE questionnaire","Physical dependence"],"a":0,"e":"Ans. A. No tolerance Alcohol dependence has following criteria:- (i) Tolerance; (ii) Withdrawal symptoms; (iii) Taken in larger amount or longer duration; (iv) Persistent craving (desire) to take alcohol; (v) A great deal of time spent to obtain alcohol or to use it; (vi) Neglect of other activities (social, occupational); and (vii) Continued use despite clear evidence of overtly harmful consequences. The CAGE questionnaire is a tool used to assess individuals for potential alcohol problems, including dependence. Alcohol produces both physical as well as psychological dependence.","pyqMatches":[{"year":"2014","no":2118,"q":"Following is true about alcoholic dependence syndrome except","o":["No tolerance","Withdrawal symptoms","CAGE questionnaire","Physical dependence"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8617, 'Psychiatry', 'General Psychiatry', 'Easy', 'Psychiatry', 185, '{"id":8617,"subject":"Psychiatry","chapter":"General Psychiatry","difficulty":"Easy","source":"Psychiatry","sourceNo":185,"q":"DSM IV criterion for depression is?","o":["1 week","2 weeks","3 weeks","4 weeks"],"a":1,"e":"Ans. B. 2 weeks For the diagnosis of minor depression 2-4 and for major depression > 5 DSM IV symptoms are required for at least for a two week period.","pyqMatches":[{"year":"2012","no":1476,"q":"DSM IV criterion for depression is?","o":["1 week","2 weeks","3 weeks","4 weeks"],"a":1,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":2119,"q":"DSM IV criterion for depression is?","o":["1 week","2 weeks","3 weeks","4 weeks"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8618, 'Psychiatry', 'ECT & Biological Treatments', 'Easy', 'Psychiatry', 186, '{"id":8618,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Easy","source":"Psychiatry","sourceNo":186,"q":"The clinical effects of the antidepressant drugs is mainly based on ?","o":["Change in neurotransmitter receptor sensitivity","Decreased level of neurotransmitters","Change in efficacy of neurotransmitters","None of the above"],"a":0,"e":"Ans. A. Change in neurotransmitter receptor sensitivity Temporal correlation of clinical effects with changes in receptor sensitivity has given rise to hypothesis that changes in neurotransmitter receptor sensitivity may actually mediate the clinical effects of antidepressant drugs. These clinical effects include not only antidepressant and anxiolytic actions but also the development of tolerance to the acute side effects of antidepressant drugs.","pyqMatches":[{"year":"2014","no":2120,"q":"The clinical effects of the antidepressant drugs is mainly based on ?","o":["Change in neurotransmitter receptor sensitivity","Decreased level of neurotransmitters","Change in efficacy of neurotransmitters","None of the above"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8619, 'Psychiatry', 'Psychotherapy & Behavioral Sciences', 'Easy', 'Psychiatry', 187, '{"id":8619,"subject":"Psychiatry","chapter":"Psychotherapy & Behavioral Sciences","difficulty":"Easy","source":"Psychiatry","sourceNo":187,"q":"Theory of human motivation was given by ?","o":["Pavlov","Abraham Maslow","Alios Alzheimer","Aaron Beck"],"a":1,"e":"Ans. B. Abraham Maslow Maslords hierarchy of needs is a theory in psyehslag proposed by Abraham Maslow in his 1943 paper. \"A Theory Of Human Motivation\" in Psychological Review. Maslow subsequently extended to include his observations of humans innate curiosity''. His theories parallel many other theories of human developmental psychology, some of which focus on describing the stages of growth in humans. Maslow used the terms \"physiological\", \"safety'', \"beloftingness\" and love, esteem, self-actualization\", and \"self-transcendence\" to describe the pattern that human motivations generally have through.","pyqMatches":[{"year":"2015","no":1674,"q":"Theory of human motivation was given by ?","o":["Pavlov","Abraham Maslow","Alios Alzheimer","Aaron Beck"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8620, 'Psychiatry', 'ECT & Biological Treatments', 'Easy', 'Psychiatry', 188, '{"id":8620,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Easy","source":"Psychiatry","sourceNo":188,"q":"Mechanism of action of duloxetine is ?","o":["Selective Inhibition of serotonin reuptake","Selective inhibition of nor-epinephrine reuptake","Selective inhibition of both serotonin and nor-epinephrine reuptake","None of the above"],"a":2,"e":"Ans. C. Selective inhibition of both serotonin and nor- epinephrine reuptake Duloxetine, is a drug classified under serotonin-norepinephrine reuptake inhibitors (sNRJs). At lower doses it is more prominent serotonin reuptake inhibitor. Whereas at higher doses it is more prominent inhibitor of nor- epinephrine reuptake. It has minimal dopamine agonist action.","pyqMatches":[{"year":"2015","no":1725,"q":"Mechanism of action of duloxetine is ?","o":["Selective Inhibition of serotonin reuptake","Selective inhibition of nor-epinephrine reuptake","Selective inhibition of both serotonin and nor-epinephrine reuptake","None of the above"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8621, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 189, '{"id":8621,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":189,"q":"Medical treatment for paraphillia includes ?","o":["SSRIs","Benzodiazepines","Opioids","Barbiturates"],"a":0,"e":"Ans. A. SSRIs Medical treatment for paraphillia - Antidepressants, such as lithium and various selective serotonin reuptake inhibitors (SSRIs) Long-acting gonadotropin-releasing hormones (ie, medical castration), such as leuprolide acetate and triptorelin Antiandrogens (to lower sex drive)'' such as medroxyprogesteroneacetate (10 mgqt2hr, with the dosage doubled every3 days to a maximum of 200 mg/day, then maintained for I month and adjusted as necessary). Phenothiazines, such as fluphenazine Mood stabilizers","pyqMatches":[{"year":"2015","no":1676,"q":"Medical treatment for paraphillia includes ?","o":["SSRIs","Benzodiazepines","Opioids","Barbiturates"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8622, 'Psychiatry', 'Schizophrenia & Psychosis', 'Hard', 'Psychiatry', 190, '{"id":8622,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Hard","source":"Psychiatry","sourceNo":190,"q":"Husband having suspicion that his wife is having affair with another man, diagnosis is ?","o":["Illusion","Delusion","Hallucination","Delirium"],"a":1,"e":"Ans. B. Delusion A delusion is false, firm (unshakeable) beliefthat is not accepted by other members of patient''s culture and society. Above is an example of delusion of infedility (morbid jealousy, othello syndrome) i.e-. False belief that one’s lover has been unfaithful.","pyqMatches":[{"year":"2015","no":1677,"q":"Husband having suspicion that his wife is having affair with another man, diagnosis is ?","o":["Illusion","Delusion","Hallucination","Delirium"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8623, 'Psychiatry', 'Child & Adolescent Psychiatry', 'Moderate', 'Psychiatry', 191, '{"id":8623,"subject":"Psychiatry","chapter":"Child & Adolescent Psychiatry","difficulty":"Moderate","source":"Psychiatry","sourceNo":191,"q":"Causes of neuroregression in a child can be all except ?","o":["Wilson''s disease","Vitamin B12 deficiency","ADHD","Ataxia telengiectasia"],"a":2,"e":"Ans. C. ADHD Causes of neuroregression Inherited A. GreY matter involvement- With visceromegaly :- Niemann pick disease, Sandholf disease (GM2), sialidosis, Goucherdisease, Mucopolyschharidoses (MPS) Without visceromegaly :- TaySach Disease, Rett syndrome, Menke’s kinky hair disease B. White matter involvement:- Leukodystrophies :- Metachromatic leukodystrophy, Krebbe''s disease, Adrenoleukodytrophy, Alexander disease, Cannavan disease . Acquired/Demyelinating:- Multiplesclerosis,schilder''sdisease,Devicdisease C. Basal ganglia involvement - Wilson’s disease, Dystonia muscular deformans, Huntington''s disease D. Spinocerebeller :- Friedrich''s ataxia, Ataxia telengiectasis E. Acquired Infections:- SSPE, progressive rubella syndrome, HIV Metabolic:Chronicleadpoisoning,Hypothyoidism,VitB12&Edeficienry,Dru","pyqMatches":[{"year":"2015","no":1724,"q":"Causes of neuroregression in a child can be all except ?","o":["Wilson''s disease","Vitamin B12 deficiency","ADHD","Ataxia telengiectasia"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8624, 'Psychiatry', 'General Psychiatry', 'Hard', 'Psychiatry', 192, '{"id":8624,"subject":"Psychiatry","chapter":"General Psychiatry","difficulty":"Hard","source":"Psychiatry","sourceNo":192,"q":"A 25 year old male believes that his penis is decreasing in size everyday and one day it will disappear one day and he will die. Diagnosis is ?","o":["Obsession","Somatization","Hypochondriasis","Delusion disorder"],"a":3,"e":"Ans. D. Delusion disorder Description given in the question is of Koro syndrome, a delusional disorder. Koro syndrome Koro is a culture-specific syndrome delusional disorder in which an individual has an overpowering belief that one’s genitalia are retracting and will disappear, despite the lack of any true longstanding changes to the genitals. Koro is also known as shrinking penis. The syndrome is commonly known as genital retraction syndrome.","pyqMatches":[{"year":"2015","no":1678,"q":"A 25 year old male believes that his penis is decreasing in size everyday and one day it will disappear one day and he will die. Diagnosis is ?","o":["Obsession","Somatization","Hypochondriasis","Delusion disorder"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8625, 'Psychiatry', 'ECT & Biological Treatments', 'Easy', 'Psychiatry', 193, '{"id":8625,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Easy","source":"Psychiatry","sourceNo":193,"q":"Haloperidol induced extarpyramidal side effects are treated by ?","o":["Benzodiazepines","Barbiturates","Anticholinergic drugs","SSRIs"],"a":2,"e":"Ans. C. Anticholinergic drugs Commonly used medications for extra-pyramidal symptoms are anticholinergic agents such as Benztropine, Diphenhydramine and trihexyphenidyl. Another common course of treatment includes dopamine agonist agents such as pramipexole.","pyqMatches":[{"year":"2015","no":1722,"q":"Haloperidol induced extarpyramidal side effects are treated by ?","o":["Benzodiazepines","Barbiturates","Anticholinergic drugs","SSRIs"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8626, 'Psychiatry', 'Substance Use Disorders', 'Easy', 'Psychiatry', 194, '{"id":8626,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":194,"q":"Most common substance of abuse in India ?","o":["Cannabis","Tobacco","Alcohol","Opium"],"a":1,"e":"Ans.B. Tobacco National Household Survey of Drug and Alcohol Abuse in India – Estimated users: (2001)","pyqMatches":[{"year":"2015","no":1679,"q":"Most common substance of abuse in India ?","o":["Cannabis","Tobacco","Alcohol","Opium"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8627, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 195, '{"id":8627,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":195,"q":"In Neuroleptic malignant syndrome, cause of death is ?","o":["Respiratory failure","Liver failure","Drug toxicity","None of the above"],"a":0,"e":"Ans. A. Respiratory failure Causes of death in NMS Respiratory failure Renal failure Pneumonia Thromboembolism Cardiac failure","pyqMatches":[{"year":"2015","no":1680,"q":"In Neuroleptic malignant syndrome, cause of death is ?","o":["Respiratory failure","Liver failure","Drug toxicity","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8628, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 196, '{"id":8628,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":196,"q":"Drug with no mood stabilizing property is -","o":["Lithium","Lamotrigine","Imipramine","Carbamazepine"],"a":2,"e":"Ans. C. Imipramine The 5 individual drugs that can be used as mood stabilizers are:","pyqMatches":[{"year":"2015","no":1721,"q":"Drug with no mood stabilizing property is","o":["Lithium","Lamotrigine","Imipramine","Carbamazepine"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8629, 'Psychiatry', 'ECT & Biological Treatments', 'Easy', 'Psychiatry', 197, '{"id":8629,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Easy","source":"Psychiatry","sourceNo":197,"q":"Sex reassignment surgery is done in ?","o":["Gender identity disorder","Premature ejaculation","Erectile dysfunction","Orgasmic dysfunction"],"a":0,"e":"Ans. A. Gender identity disorder Many persons with gender identity disorder have sought sex- reassignment surgery, that is, physical change that is constant with their cross sexual identity.","pyqMatches":[{"year":"2015","no":1682,"q":"Sex reassignment surgery is done in ?","o":["Gender identity disorder","Premature ejaculation","Erectile dysfunction","Orgasmic dysfunction"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8630, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 198, '{"id":8630,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":198,"q":"Modafinil is used for the treatment of ?","o":["Narcolepsy","Sexual dysfunction","Depression","Anxiety"],"a":0,"e":"Ans. A. Narcolepsy Modafinil is a wakefulness-promoting agent (or eugeroic) used for treatment of disorders such as narcolepsy,shift work sleep disorder, and excessive daytime sleepiness associated with obstructive sleep apnea''","pyqMatches":[{"year":"2015","no":1720,"q":"Modafinil is used for the treatment of ?","o":["Narcolepsy","Sexual dysfunction","Depression","Anxiety"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8631, 'Psychiatry', 'General Psychiatry', 'Hard', 'Psychiatry', 199, '{"id":8631,"subject":"Psychiatry","chapter":"General Psychiatry","difficulty":"Hard","source":"Psychiatry","sourceNo":199,"q":"A girl with bad behavior like smashing and throwing objects was admitted in the hospital. There also she was behaving very badly with staff & abusing nurses. But she behaves very well with a one very good looking resident doctor. Diagnosis is?","o":["Bipolar disorder","Schizoaffective disorder","Borderline personality disorder","Antisocial personality"],"a":3,"e":"Ans. D. Antisocial personality Antisocial (Dissocial) personality disorder The essential features of antisocial personality disorder are a disregard for and violation of the rights of the other and the ruIes of the society. It is characterized by repeated violation of the law and rules of the society (drug abuse); physical aggressiveness; Reckless disregard for safety of self or others; consistent irresponsibility in work and family environment and lack of remorse. This disorder is synonymous with previously used terms like psychopath or sociopath.","pyqMatches":[{"year":"2015","no":1685,"q":"A girl with bad behavior like smashing and throwing objects was admitted in the hospital. There also she was behaving very badly with staff & abusing nurses. But she behaves very well with a one very good looking resident doctor. Diagnosis is?","o":["Bipolar disorder","Schizoaffective disorder","Borderline personality disorder","Antisocial personality"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8632, 'Psychiatry', 'Mood Disorders', 'Moderate', 'Psychiatry', 200, '{"id":8632,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Moderate","source":"Psychiatry","sourceNo":200,"q":"All of the following are associated increased REM latency, except ?","o":["First night effect","SSRIs","Narcolepsy","Restless leg syndrome"],"a":2,"e":"Ans. C. Narcolepsy Increased REM latency - PTSD Restless leg syndrome. First night effect SSRI’s TCA’s Ethanol Lithium","pyqMatches":[{"year":"2015","no":1719,"q":"All of the following are associated increased REM latency, except ?","o":["First night effect","SSRIs","Narcolepsy","Restless leg syndrome"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8633, 'Psychiatry', 'Child & Adolescent Psychiatry', 'Easy', 'Psychiatry', 201, '{"id":8633,"subject":"Psychiatry","chapter":"Child & Adolescent Psychiatry","difficulty":"Easy","source":"Psychiatry","sourceNo":201,"q":"Sign of oppositionalism in a young child is due to?","o":["Mental retardation","Organic mental disorder","Mental distress","All of the above"],"a":2,"e":"Ans. C. Mental distress “Oppositionalism, temper tantrums and breath holding spells are not unusual during 1st years of life and are age typical expression of frustration and anger”","pyqMatches":[{"year":"2015","no":1718,"q":"Sign of oppositionalism in a young child is due to?","o":["Mental retardation","Organic mental disorder","Mental distress","All of the above"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8634, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 202, '{"id":8634,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":202,"q":"Trichophagia is characterized by?","o":["Compulsive pulling of hair","Compulsive eating of hair","Compulsive shopping","Compulsive stealing"],"a":1,"e":"Ans. B. Compulsive eating of hair Trichophagia is compulsive eating of hair and is usually associated with trichotillomania i.e. compulsive pulling of hair.","pyqMatches":[{"year":"2015","no":1686,"q":"Trichophagia is characterized by?","o":["Compulsive pulling of hair","Compulsive eating of hair","Compulsive shopping","Compulsive stealing"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8635, 'Psychiatry', 'ECT & Biological Treatments', 'Easy', 'Psychiatry', 203, '{"id":8635,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Easy","source":"Psychiatry","sourceNo":203,"q":"MC cause of delirium ?","o":["Infection","Liver failure","Belladonna poisoning","None of the above"],"a":0,"e":"Ans. A. Infection Infection is one of the most common causes of delirium.","pyqMatches":[{"year":"2015","no":1688,"q":"MC cause of delirium ?","o":["Infection","Liver failure","Belladonna poisoning","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8636, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 204, '{"id":8636,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":204,"q":"General paralysis of insane is associated with ?","o":["Neurosyphillis","Alzheimer''s disease","Parkinson''s disease","None of the above"],"a":0,"e":"Ans, A. Neurosyphillis General paresis, also known as general paralysis ofthe insane or paralytic dementia, is a severe neuropsychiatric disorder, classified as an organic mental disorder and caused by the chronic meningoencephalitis that leads to cerebral atrophy in late- stagesyphilis. Degenerative changes are associated primarily with the frontal and temporal lobar cortex- General paralysis of the Insane (GPI) is progressive deterioration of the whole mental and physical personality. Symptoms included exaggeratedkneejerk, Iack ofreaction ofthe pupils to light, an inabilityto pay attention, a''clouding''of consciousness, poor short-term memory, tremulous voice, reflex disturbances, and retinal anomalies'' and diminished skin sensation. Patients were often recognizable by their striking ''delusions of grandeur”","pyqMatches":[{"year":"2015","no":1717,"q":"General paralysis of insane is associated with ?","o":["Neurosyphillis","Alzheimer''s disease","Parkinson''s disease","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8637, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 205, '{"id":8637,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":205,"q":"Jamais vu is -","o":["Illusion that what one is hearing, one has heard previously","A unfamiliar thought regarded as repetition of a previous thought","Unfamiliar situations or events feel strangely familiar","Feeling of strangeness to familiar situation"],"a":3,"e":"Ans. D. Feeling of strangeness to familiar situation famais vu :- A feeling of strangeness to familiar situations or events.","pyqMatches":[{"year":"2015","no":1690,"q":"Jamais vu is","o":["Illusion that what one is hearing, one has heard previously","A unfamiliar thought regarded as repetition of a previous thought","Unfamiliar situations or events feel strangely familiar","Feeling of strangeness to familiar situation"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8638, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 206, '{"id":8638,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":206,"q":"Conventional drug used in the treatment of delirium is?","o":["Haloperidol","Lithium","SSRIs","Morphine"],"a":0,"e":"Ans. A. Haloperidol Drugs used for delirium: Typical antipsychotics: - Haloperidol (Doc), Thioridazine, chlorpromazine. Atypical antipsychotics: - Risperidone, quetiapine, olanzapine. Benzndiazepines (for delirium tremens): - Chlordiazepoxide, Diazepam, Lorazepam, Clonazepam.","pyqMatches":[{"year":"2015","no":1716,"q":"Conventional drug used in the treatment of delirium is?","o":["Haloperidol","Lithium","SSRIs","Morphine"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8639, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 207, '{"id":8639,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":207,"q":"Characteristic hallucination of schizophrenia is","o":["Auditory hallucinations commanding the patient","Auditory hallucinations giving running commentary","Auditory hallucinations criticizing the patient","Auditory hallucinations talking to patient"],"a":1,"e":"Ans. B. Auditory hallucinations giving running commentary Third-person hallucinations, e.g. voices heard arguing, commenting or discussing the patient or giving a running commentary on one''s action; are characteristic of schizophrenia. In schizophrenia auditory hallucinations are the most common type of hallucinations.","pyqMatches":[{"year":"2015","no":1692,"q":"Characteristic hallucination of schizophrenia is","o":["Auditory hallucinations commanding the patient","Auditory hallucinations giving running commentary","Auditory hallucinations criticizing the patient","Auditory hallucinations talking to patient"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8640, 'Psychiatry', 'Miscellaneous', 'Moderate', 'Psychiatry', 208, '{"id":8640,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Psychiatry","sourceNo":208,"q":"Which of the following typical antipsychotic drug is not available in depot form ?","o":["Haloperidol","Risperidone","Olanzapine","Chlorpromazine"],"a":3,"e":"Ans. D. Chlorpromazine Antipsychotic drugs with depot preparations are risperidone, poliperidone, halopetidol, fluphenazine, flupenthixol, zuclopenthixol, olannpine, clozapine, imipramine and quetiapine.","pyqMatches":[{"year":"2015","no":1715,"q":"Which of the following typical antipsychotic drug is not available in depot form ?","o":["Haloperidol","Risperidone","Olanzapine","Chlorpromazine"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8641, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 209, '{"id":8641,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":209,"q":"Self mutilation is a feature of ?","o":["Von-Gogh syndrome","Catatonic schizophrenia","Paranoid schizophrenia","None of the above"],"a":0,"e":"Ans. A. Von-Gogh syndrome Dramatic self-mutilation occurring in schizophrenia has also been called Von-Gogh syndrome''","pyqMatches":[{"year":"2015","no":1694,"q":"Self mutilation is a feature of ?","o":["Von-Gogh syndrome","Catatonic schizophrenia","Paranoid schizophrenia","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8642, 'Psychiatry', 'General Psychiatry', 'Hard', 'Psychiatry', 210, '{"id":8642,"subject":"Psychiatry","chapter":"General Psychiatry","difficulty":"Hard","source":"Psychiatry","sourceNo":210,"q":"A patient inventing new words, is a feature of ?","o":["Neurosis","Schizophrenia","OCD","Von-Gogh syndrome"],"a":1,"e":"Ans B. Schizophrenia Neologism: - New words or condensations of several words that are not readily understood by others. Neologism is seen in schizophrenia and organic brain syndrome.","pyqMatches":[{"year":"2015","no":1695,"q":"A patient inventing new words, is a feature of ?","o":["Neurosis","Schizophrenia","OCD","Von-Gogh syndrome"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8643, 'Psychiatry', 'Substance Use Disorders', 'Easy', 'Psychiatry', 211, '{"id":8643,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":211,"q":"True about flumazenil is ?","o":["Can be used in barbiturate poisoning","Specific antidote for opiate overdose","Can be used in benzodiazepine overdose","All of the above"],"a":2,"e":"Ans. C. Can be used in benzodiazepine overdose Fumazenil is an imidazobenzodiazepine derivative and a potent benzodiazepine recePtor antagonist that competitively inhibits the activity at the benzodiazepine recognition site on the GABA benzodiazepine receptor complex thereby reversing the effects of benzodiazepine on the central nervous system. Flumazenil does not antagonize the central nervous system effects of drugs affecting GABA-ergic neurons by means other than the benzodiazepine receptor (including ethanol, barbiturates, or general anesthetics) and does not reverse the effects of opioids.","pyqMatches":[{"year":"2015","no":1714,"q":"True about flumazenil is ?","o":["Can be used in barbiturate poisoning","Specific antidote for opiate overdose","Can be used in benzodiazepine overdose","All of the above"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8644, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 212, '{"id":8644,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":212,"q":"Increased dopamine levels are associated ?","o":["Depression","Mania","Delirium","Schizophrenia"],"a":3,"e":"Ans. D. Schizophrenia Dopamine hypothesis is the most accepted hypothesis for schizophrenia. There is hyperactivity of dopaminergic system. Other neurotransmitters involved are : - Increased serotonin, Decreased GABA, variable change (Increased or decreased) glutamate, and increased norepinephrine.","pyqMatches":[{"year":"2015","no":1696,"q":"Increased dopamine levels are associated ?","o":["Depression","Mania","Delirium","Schizophrenia"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8645, 'Psychiatry', 'Child & Adolescent Psychiatry', 'Easy', 'Psychiatry', 213, '{"id":8645,"subject":"Psychiatry","chapter":"Child & Adolescent Psychiatry","difficulty":"Easy","source":"Psychiatry","sourceNo":213,"q":"Tourette syndrome is a type of ?","o":["Tic disorder","Mental retardation disorder","Seizure disorder","None of the above"],"a":0,"e":"Ans. A. Tic disorder Tourette syndrome (also called Tourette''s syndrome, Tourette''s disorder, Gilles de la Tourette syndrome, GTS or, more commonly, simply Tourette''s or TS) is an inherited neuropsychiatric disorder with onset in childhood, characterized by multiple physical (motor) tics and at least one vocal (phonic) tic. Average onset between the ages of 3 and 9 years. Males are affected about three to four times more often than females. Common associations are ADHD and OCD.","pyqMatches":[{"year":"2015","no":1713,"q":"Tourette syndrome is a type of ?","o":["Tic disorder","Mental retardation disorder","Seizure disorder","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8646, 'Psychiatry', 'Anxiety & Related Disorders', 'Easy', 'Psychiatry', 214, '{"id":8646,"subject":"Psychiatry","chapter":"Anxiety & Related Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":214,"q":"Treatment of choice for acute panic attacks is ?","o":["Barbiturates","Benzodiazepines","TCAs","MAO inhibitors"],"a":1,"e":"Ans. B. Benzodiazepines DOC for Panic disorders - SSRI’s DOC for acute panic attack - Benzodiazepines.","pyqMatches":[{"year":"2015","no":1699,"q":"Treatment of choice for acute panic attacks is ?","o":["Barbiturates","Benzodiazepines","TCAs","MAO inhibitors"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8647, 'Psychiatry', 'Child & Adolescent Psychiatry', 'Easy', 'Psychiatry', 215, '{"id":8647,"subject":"Psychiatry","chapter":"Child & Adolescent Psychiatry","difficulty":"Easy","source":"Psychiatry","sourceNo":215,"q":"Characterized by chronic, multiple tics ?","o":["Parkinson''s disease","Wilson''s disease","Shy-Drager syndrome","Tourette''s syndrome"],"a":3,"e":"Ans. D. Tourette''s syndrome Tourette syndrome (also called Tourette''s syndrome, Tourette''s disorder, Gilles de la Tourette syndrome, GTS or, more commonly, simply Tourette''s or TS) is an inherited neuropsychiatric disorder with onset in childhood, characterized by multiple physical (motor) tics and at least one vocal (phonic) tic.","pyqMatches":[{"year":"2015","no":1712,"q":"Characterized by chronic, multiple tics ?","o":["Parkinson''s disease","Wilson''s disease","Shy-Drager syndrome","Tourette''s syndrome"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8648, 'Psychiatry', 'Miscellaneous', 'Moderate', 'Psychiatry', 216, '{"id":8648,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Psychiatry","sourceNo":216,"q":"Which of the following is not true about sleep ?","o":["REM sleep comes earlier than NREM sleep","REM sleep is also called paradoxical sleep","Sleep walking comes in NREM sleep","Dreams come in REM sleep"],"a":0,"e":"Ans. A. REM sleep comes earlier than NREM sleep The NREM (with its four stages) and REM sleep repeat several times a night in cyclic manner, 4-6 times depending on the length of sleep. A typical cycle starts with stage I of the NREM sleep which is followed by second, third and fourth stages. REM sleep occupies 20-30% of total sleep and NREM sleep occupies 60-70% (Stage I occupies 5- 10%; Stage 2 occupies 40- 50% ;Stage 3 occupies 15-20%","pyqMatches":[{"year":"2015","no":1700,"q":"Which of the following is not true about sleep ?","o":["REM sleep comes earlier than NREM sleep","REM sleep is also called paradoxical sleep","Sleep walking comes in NREM sleep","Dreams come in REM sleep"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8649, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 217, '{"id":8649,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":217,"q":"Gamma waves of REM sleep in sleep cycle are associated with ?","o":["Intense attention","Subconscious thinking","Deep subconscious thinking","Deep sleep"],"a":0,"e":"Ans. A. Intense attention Beta and gamma waves (20-80Hz) occur spontaneously during REM sleep and waking and are evoked by intense attention, conditioned responses, tasks requiring fine movements and sensory stimulus","pyqMatches":[{"year":"2015","no":1701,"q":"Gamma waves of REM sleep in sleep cycle are associated with ?","o":["Intense attention","Subconscious thinking","Deep subconscious thinking","Deep sleep"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8650, 'Psychiatry', 'Mood Disorders', 'Moderate', 'Psychiatry', 218, '{"id":8650,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Moderate","source":"Psychiatry","sourceNo":218,"q":"Drug not used in prophylaxis of MD P ?","o":["Haloperidol","Lithium","Carbamazepine","Valproate"],"a":0,"e":"Ans. A. Haloperidol Prophylactic treatment for bipolar disorder:","pyqMatches":[{"year":"2015","no":1711,"q":"Drug not used in prophylaxis of MD P ?","o":["Haloperidol","Lithium","Carbamazepine","Valproate"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8651, 'Psychiatry', 'Anxiety & Related Disorders', 'Easy', 'Psychiatry', 219, '{"id":8651,"subject":"Psychiatry","chapter":"Anxiety & Related Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":219,"q":"Behavioral therapy is done in ?","o":["Schizophrenia","Agoraphobia","Delirium","Neurotic depression"],"a":1,"e":"Ans. B. Agoraphobia Most important use of behavioral therapy - Phobia & OCD. Other users are - Other anxiety disorders (including panic), Eating disorders, Autism, ADHD, some personality disorder, sexual dysfunctions, depression.","pyqMatches":[{"year":"2015","no":1702,"q":"Behavioral therapy is done in ?","o":["Schizophrenia","Agoraphobia","Delirium","Neurotic depression"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8652, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 220, '{"id":8652,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":220,"q":"Feature associated with mania is ?","o":["Neologism","Perseveration","Echolalia","Flights of ideas"],"a":3,"e":"Ans. D. Flights of ideas Diagnostic criteria for mania Three or more of the following for at least 1 week:-","pyqMatches":[{"year":"2015","no":1710,"q":"Feature associated with mania is ?","o":["Neologism","Perseveration","Echolalia","Flights of ideas"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8653, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 221, '{"id":8653,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":221,"q":"Eating disorder with normal weight is?","o":["Anorexia nervosa","Bulimia nervosa","Binge eating disorder","None of the above"],"a":1,"e":"Ans. B. Bulimia nervosa Anorexia nervosa - Under weight Bulimia nervosa - Normal Weight Binge eating disorder - Over weight.","pyqMatches":[{"year":"2015","no":1705,"q":"Eating disorder with normal weight is?","o":["Anorexia nervosa","Bulimia nervosa","Binge eating disorder","None of the above"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8654, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 222, '{"id":8654,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":222,"q":"Phototherapy is used in the treatment of ?","o":["Anorexia nervosa","Seasonal affective disorder","Schizophrenia","Obsessive compulsive disorder"],"a":1,"e":"Ans. B. Seasonal affective disorder Phototherapy is primarily indicated in the treatment of seasonal depressions. In addition to seasonal depression, the other major indication for phototherapy may be in sleep disorders.","pyqMatches":[{"year":"2015","no":1709,"q":"Phototherapy is used in the treatment of ?","o":["Anorexia nervosa","Seasonal affective disorder","Schizophrenia","Obsessive compulsive disorder"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8655, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 223, '{"id":8655,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":223,"q":"Binge eating disorder is characterized by ?","o":["Normal weight","Weight loss","Obesity","Self induced vomiting"],"a":2,"e":"Ans. C. Obesity Binge eating disorder (BED) is characterized by insatiable cravings that can occur any time day or night, usually secretive, and filled with shame. There are no comPensatory mechanisms associated with the binge to get rid of calories, so individulas with BED are more likely to be overweight or obese, while patients with bulimia nervosa may be underweight, normal weight.","pyqMatches":[{"year":"2015","no":1706,"q":"Binge eating disorder is characterized by ?","o":["Normal weight","Weight loss","Obesity","Self induced vomiting"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8656, 'Psychiatry', 'ECT & Biological Treatments', 'Moderate', 'Psychiatry', 224, '{"id":8656,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Moderate","source":"Psychiatry","sourceNo":224,"q":"Tricyclic antidepressants have all of the following actions except ?","o":["Anticholinergic action","MAO inhibition","Block 5-HT or NE reuptake","Causes sedation"],"a":1,"e":"Ans- B. MAO inhibition Tricyclic antidepressants (TCAS) are either NA + 5HT reuptake inhibitors (e.g. - Imipramine, Amitriptyline) or predominantly NA reuptake inhibitors (e.g. Desipramine, nortriptyline). TCAs are not MAO inhibitors. Adverse effects of TCFs are : anticholinergic side effects, sedatior, mental confusion, weakness, increase appetite & weight gain, sweating & fine tremor, postural hypotension and cardiac arrhythmia.","pyqMatches":[{"year":"2015","no":1707,"q":"Tricyclic antidepressants have all of the following actions except ?","o":["Anticholinergic action","MAO inhibition","Block 5-HT or NE reuptake","Causes sedation"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8657, 'Psychiatry', 'Substance Use Disorders', 'Easy', 'Psychiatry', 225, '{"id":8657,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":225,"q":"Which of the following is a feature of opioid withdrawal?","o":["Tremors","Goose flesh","Dry nose and mouth","Constipation"],"a":1,"e":"Ans. B. Goose flesh Manifestations of morphine withdrawal - Lacrimation Sweating Yawning Gooseflash(Piloerection) Mydriasis Anxiety & fear Restlessness Insomnia Abdominal colic Diarrhea Dehydration Hypertension Palpitation Rapid weight loss","pyqMatches":[{"year":"2015","no":1708,"q":"Which of the following is a feature of opioid withdrawal?","o":["Tremors","Goose flesh","Dry nose and mouth","Constipation"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8658, 'Psychiatry', 'Psychotherapy & Behavioral Sciences', 'Hard', 'Psychiatry', 226, '{"id":8658,"subject":"Psychiatry","chapter":"Psychotherapy & Behavioral Sciences","difficulty":"Hard","source":"Psychiatry","sourceNo":226,"q":"Patient and Psychotherapis, both participate actively in?","o":["Psychoanalysis","Psychoanalytic psychotherapy","Psycodynamic psychotherapy","All of the above"],"a":1,"e":"Ans. B. Psychoanalytic psychotherapy Psychoanalytic (psychodynamic) psychotherapy is a much more direct from of psychonalysis. The patient and therapist sit face to face. However therapist usually talks quite a lot, compared to silence in psychoanalysis. Treatment is an interactive process between the patient and therapist.","pyqMatches":[{"year":"2013","no":1857,"q":"Patient and Psychotherapis, both participate actively in?","o":["Psychoanalysis","Psychoanalytic psychotherapy","Psycodynamic psychotherapy","All of the above"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8659, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 227, '{"id":8659,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":227,"q":"The maximum DALY loss is for the following disease -","o":["Schizophrenia","Unipolar depression","Bipolar depression","Mania"],"a":1,"e":"Ans. B. Unipolar depression Amongst the psychiatric disorders maximum DALY loss is caused by major depression.","pyqMatches":[{"year":"2012","no":1442,"q":"The maximum DALY loss is for the following disease","o":["Schizophrenia","Unipolar depression","Bipolar depression","Mania"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8660, 'Psychiatry', 'General Psychiatry', 'Easy', 'Psychiatry', 228, '{"id":8660,"subject":"Psychiatry","chapter":"General Psychiatry","difficulty":"Easy","source":"Psychiatry","sourceNo":228,"q":"Etheromanias refer to ?","o":["Acute psychosis post ether anaesthesia","Ether addiction","Excessive ether use drug anaesthesia","None"],"a":1,"e":"Ans, B. Ether addiction Ether addiction or etheromania is the addiction to inhalation or drinking of diethyl ether.","pyqMatches":[{"year":"2012","no":1443,"q":"Etheromanias refer to ?","o":["Acute psychosis post ether anaesthesia","Ether addiction","Excessive ether use drug anaesthesia","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8661, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 229, '{"id":8661,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":229,"q":"The term \"Dementia precox\" was coined by ?","o":["Freud","Bleuler","Kraepelin","Schneider"],"a":2,"e":"Ans. C. Kraepelin","pyqMatches":[{"year":"2012","no":1444,"q":"The term \"Dementia precox\" was coined by ?","o":["Freud","Bleuler","Kraepelin","Schneider"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8662, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 230, '{"id":8662,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":230,"q":"The term ''id'' was coined by ?","o":["Freud","Skinner","Wayker","Blueler"],"a":0,"e":"Ans, A. Freud Structural theory of mind(theid, ego and superego) was given by sigmund freud.","pyqMatches":[{"year":"2012","no":1445,"q":"The term ''id'' was coined by ?","o":["Freud","Skinner","Wayker","Blueler"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8663, 'Psychiatry', 'Miscellaneous', 'Moderate', 'Psychiatry', 231, '{"id":8663,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Moderate","source":"Psychiatry","sourceNo":231,"q":"Subcortical dementia is seen in all except ?","o":["Parkinsonism","Alzheimer''s disease","Wilson''s disease","Huntingtons chorea"],"a":1,"e":"Ans.B. Alzheimer''s disease Subcortical dementia is seen in parkinsonism, Huntington''s disease, wilson''s disease, progressive supranuclear palsy, idiopathic basal ganglion calcification (Fahr''s disease), thalamic lesions, multiple sclerosis, HIV associated dementia and multisYstem atroPhY. Alzheimer''s disease causes cortical dementia.","pyqMatches":[{"year":"2012","no":1446,"q":"Subcortical dementia is seen in all except ?","o":["Parkinsonism","Alzheimer''s disease","Wilson''s disease","Huntingtons chorea"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8664, 'Psychiatry', 'Substance Use Disorders', 'Easy', 'Psychiatry', 232, '{"id":8664,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":232,"q":"Formication is seen with ?","o":["Acute amphetamine intoxication","Chronic use of amhetamine","Alcohol withdrawal","Cannabis poisoning"],"a":1,"e":"Ans. B. Chronic use of amhetamine Magnan’s syndrome (also called formication) is seen in chronic cocaine and chronic amphetamine abuse.","pyqMatches":[{"year":"2012","no":1447,"q":"Formication is seen with ?","o":["Acute amphetamine intoxication","Chronic use of amhetamine","Alcohol withdrawal","Cannabis poisoning"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8665, 'Psychiatry', 'Substance Use Disorders', 'Easy', 'Psychiatry', 233, '{"id":8665,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":233,"q":"Hangover following alcohol consumption can be treated with ?","o":["Pyridoxine","Thiamine","Riboflavin","Niacin"],"a":1,"e":"ANs. B. Thiamine Thiamine helps prevent the buildup of glutarate in the brain, which may be associated with part of the headache associated with hangover.","pyqMatches":[{"year":"2012","no":1448,"q":"Hangover following alcohol consumption can be treated with ?","o":["Pyridoxine","Thiamine","Riboflavin","Niacin"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8666, 'Psychiatry', 'Substance Use Disorders', 'Easy', 'Psychiatry', 234, '{"id":8666,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":234,"q":"Most commonly abused opioid -","o":["Morphine","Diacetylmorphine","Oxycodine","Bupremorphine"],"a":1,"e":"Ans, B. Diacetylmorphine Diacetylmorphine (heroin) is the most commonly abused opioid.","pyqMatches":[{"year":"2012","no":1449,"q":"Most commonly abused opioid","o":["Morphine","Diacetylmorphine","Oxycodine","Bupremorphine"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8667, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 235, '{"id":8667,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":235,"q":"Hallucinations are produced by?","o":["Amphetamine","Morphine","Paraxetine","Chlorpromazine"],"a":0,"e":"Ans, A. Amphetamine Amphetamine psychosis mimic paranoid schizophrenia. There may be deleusions and hallucinations.","pyqMatches":[{"year":"2012","no":1450,"q":"Hallucinations are produced by?","o":["Amphetamine","Morphine","Paraxetine","Chlorpromazine"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8668, 'Psychiatry', 'General Psychiatry', 'Easy', 'Psychiatry', 236, '{"id":8668,"subject":"Psychiatry","chapter":"General Psychiatry","difficulty":"Easy","source":"Psychiatry","sourceNo":236,"q":"Anxiety is ?","o":["Neurosis","Psychosis","Personality disorder","None"],"a":0,"e":"Ans., A. Neurosis Important neurotic disorders are Anxiety disorders (Panic), Phobia (Phobic anxiety disorder), obsessive compulsive Disorder & Dissociative conversion disorder.","pyqMatches":[{"year":"2012","no":1451,"q":"Anxiety is ?","o":["Neurosis","Psychosis","Personality disorder","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8669, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 237, '{"id":8669,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":237,"q":"In depressions, there is deficiency of ?","o":["5-HT","Acetylcholine","Dopamine","GABA"],"a":0,"e":"Ans. A. 5-HT Depression = Decrease in serotonin and norepinephrine. Serotonin is the most imPortant neurotransmitter in depression. Mania= Increased of norepipherine.","pyqMatches":[{"year":"2012","no":1455,"q":"In depressions, there is deficiency of ?","o":["5-HT","Acetylcholine","Dopamine","GABA"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8670, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 238, '{"id":8670,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":238,"q":"The aminoacid derived neurotransmitter used for treating depression is ?","o":["Serotonine","Histamine","acetylcholine","none"],"a":0,"e":"Ans. A. Serotonine The three main neurotransmitters involved in depression are dopamine, norepinephrine and serotonin (s-HT). When brain Ievels of one or more neurotransmitter are low or unbalanced, depression can result. Generally, antidepressant drugs work by increasing production or decreasing the breakdown of one or more of these neurotransmitters.","pyqMatches":[{"year":"2012","no":1456,"q":"The aminoacid derived neurotransmitter used for treating depression is ?","o":["Serotonine","Histamine","acetylcholine","none"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8671, 'Psychiatry', 'Psychotherapy & Behavioral Sciences', 'Easy', 'Psychiatry', 239, '{"id":8671,"subject":"Psychiatry","chapter":"Psychotherapy & Behavioral Sciences","difficulty":"Easy","source":"Psychiatry","sourceNo":239,"q":"Repetitive times work doing for premonition of ?","o":["Obscession","Compulsion","Anxiety","None"],"a":1,"e":"Ans. B. Compulsion Repetitive irresistable thoughts > Obsession. Repetitive purposeful behavior (work doing) > compulsion.","pyqMatches":[{"year":"2012","no":1459,"q":"Repetitive times work doing for premonition of ?","o":["Obscession","Compulsion","Anxiety","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8672, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 240, '{"id":8672,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":240,"q":"Derelation & depersonalisation seen in which type of disorder ?","o":["Dissociative disorder","Personality disorders","Mania","None"],"a":0,"e":"Ans. A. Dissociative disorder","pyqMatches":[{"year":"2012","no":1460,"q":"Derelation & depersonalisation seen in which type of disorder ?","o":["Dissociative disorder","Personality disorders","Mania","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8673, 'Psychiatry', 'ECT & Biological Treatments', 'Moderate', 'Psychiatry', 241, '{"id":8673,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Moderate","source":"Psychiatry","sourceNo":241,"q":"Schizoid personality disorder all are seen except?","o":["Aloof & detached","Prone to fantasy","Suspicious","Introspective"],"a":2,"e":"Ans. C. Suspicious Suspiciousness is seen in paranoid personality disorder.","pyqMatches":[{"year":"2012","no":1464,"q":"Schizoid personality disorder all are seen except?","o":["Aloof & detached","Prone to fantasy","Suspicious","Introspective"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8674, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 242, '{"id":8674,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":242,"q":"Narcolepsy is due to abnormality in ?","o":["Hypothalamus","Neocortex","Cerebellum","Medulla oblongata"],"a":0,"e":"Ans. A. Hypothalamus Narcolepsy is unique in that those who suffer from it tyPicaly fall almost instantaneously into REM sleep. It is thought that narcolepsy is caused by a malfunctioning of the hypothalamus in brain.","pyqMatches":[{"year":"2012","no":1465,"q":"Narcolepsy is due to abnormality in ?","o":["Hypothalamus","Neocortex","Cerebellum","Medulla oblongata"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8675, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 244, '{"id":8675,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":244,"q":"NREM Sleep true is ?","o":["Teeth grinding","Narcolepsy","Nightmares","Sleep paralysis"],"a":0,"e":"Ans. A. Teeth grinding Slow wave sleep (stage 3 & 4 of NREM sleep) disorders r Sleep walking (somnambulism), night terror (sleep terror or pavornocturnus), Nocturnal enuresis, Bruxism (teeth grinning), and sleep talking (somniloquy). REM sleep events/disorder:- Nightmares, nocturnal penile tumescence, Narcolepsy.","pyqMatches":[{"year":"2012","no":1467,"q":"NREM Sleep true is ?","o":["Teeth grinding","Narcolepsy","Nightmares","Sleep paralysis"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8676, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 245, '{"id":8676,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":245,"q":"Bruxism is ?","o":["Walking during sleep","Nocturnal enuresis","Grinding of teeth during sleep","Sleep apnoea"],"a":2,"e":"Ans. C. Grinding of teeth during sleep","pyqMatches":[{"year":"2012","no":1468,"q":"Bruxism is ?","o":["Walking during sleep","Nocturnal enuresis","Grinding of teeth during sleep","Sleep apnoea"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8677, 'Psychiatry', 'Schizophrenia & Psychosis', 'Moderate', 'Psychiatry', 246, '{"id":8677,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Moderate","source":"Psychiatry","sourceNo":246,"q":"Narcolepsy, not true ?","o":["Cataplexy","Sleep architecture normal","Loss of muscle tone","Hallucination"],"a":1,"e":"Ans. B. Sleep architecture normal There is disturbed REM sleep. Cataplexy (sudden loss of muscle tone) is the most common accessory symPtom. There may be hallucinations.","pyqMatches":[{"year":"2012","no":1469,"q":"Narcolepsy, not true ?","o":["Cataplexy","Sleep architecture normal","Loss of muscle tone","Hallucination"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8678, 'Psychiatry', 'ECT & Biological Treatments', 'Easy', 'Psychiatry', 247, '{"id":8678,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Easy","source":"Psychiatry","sourceNo":247,"q":"How to differentiate between psychological and organic erectile dysfunction ?","o":["Nocturnal penile tumescence","PIPE therapy","Sildenafil induced erection","Squeeze technique"],"a":0,"e":"Ans. A. Nocturnal penile tumescence One of the important method to distinguish psychogenic impotence from organic imPotence is nocturnal penile tumsescence & early morning erection which are preserved in psychogenic impotence but not in organic cause of impotence.","pyqMatches":[{"year":"2012","no":1470,"q":"How to differentiate between psychological and organic erectile dysfunction ?","o":["Nocturnal penile tumescence","PIPE therapy","Sildenafil induced erection","Squeeze technique"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8679, 'Psychiatry', 'Psychotherapy & Behavioral Sciences', 'Easy', 'Psychiatry', 248, '{"id":8679,"subject":"Psychiatry","chapter":"Psychotherapy & Behavioral Sciences","difficulty":"Easy","source":"Psychiatry","sourceNo":248,"q":"Desensitization is a type of ?","o":["Psychotherapy","Psychoanalysis","Behavioral therapy","None"],"a":2,"e":"Ans.C. Behavioral therapy Types of behavioral therapy are : - Systemic desensitization, therapeutic graded exPosure, exPosure & response prevention, flooding, aversion therapy, and operant conditioning.","pyqMatches":[{"year":"2012","no":1471,"q":"Desensitization is a type of ?","o":["Psychotherapy","Psychoanalysis","Behavioral therapy","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8680, 'Psychiatry', 'Child & Adolescent Psychiatry', 'Easy', 'Psychiatry', 249, '{"id":8680,"subject":"Psychiatry","chapter":"Child & Adolescent Psychiatry","difficulty":"Easy","source":"Psychiatry","sourceNo":249,"q":"Stimulant drug is given to child for ?","o":["Conduct disorder","Speech developmental disorder","Pervasive disorder","ADHD"],"a":3,"e":"Ans.D. ADHD Stimulants (like methylphenidate, dextramphetamine) are the drugs of choice for ADHD.","pyqMatches":[{"year":"2012","no":1472,"q":"Stimulant drug is given to child for ?","o":["Conduct disorder","Speech developmental disorder","Pervasive disorder","ADHD"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8681, 'Psychiatry', 'Mood Disorders', 'Easy', 'Psychiatry', 250, '{"id":8681,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":250,"q":"Klein levin syndrome ?","o":["Insomnia","Anxiety","Depression","Hypersomnia"],"a":3,"e":"Ans. D. Hypersomnia Kleine levin syadrome or sleeping beauty syndrome is a neurological disorder of recurring periods of excessive amounts of sleeping and eating.","pyqMatches":[{"year":"2012","no":1473,"q":"Klein levin syndrome ?","o":["Insomnia","Anxiety","Depression","Hypersomnia"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8682, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 251, '{"id":8682,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":251,"q":"According to recent rounds by DSM what code is given to psychiatric diseases in ICD 10 ?","o":["E","F","P","G"],"a":1,"e":"Ans. B. F ICD -10 is WHO classification for all diseases and health problems (and not only psychiatric disorders). ICD-10 uses alpha numeric code made of an alphabet à in contrast DSM-IV uses numerical coding) à ''F'' is for mental disorders. There are l0 main categories denoted by digits 0 to 9.","pyqMatches":[{"year":"2012","no":1474,"q":"According to recent rounds by DSM what code is given to psychiatric diseases in ICD 10 ?","o":["E","F","P","G"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8683, 'Psychiatry', 'Anxiety & Related Disorders', 'Easy', 'Psychiatry', 252, '{"id":8683,"subject":"Psychiatry","chapter":"Anxiety & Related Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":252,"q":"Which of the following is the poor prognostic factor for OCD?","o":["Magical thinking","Dirt contamination","Pathological doubt","Hoarding"],"a":1,"e":"Ans: B. Dirt contamination. OCD - Clinical features & symptoms: Contamination – Most common obsession. Obsession of contamination → compulsive avoiding of contaminated objects → excessive cleaning --> inability to leave there homes (due to germs fear, shame & disgust from feces, urine, dust & germs). Pathological doubt – 2nd most common. Obsession of doubt → compulsive checking → most danger of violence → forgetting to turn off the stove, or not locking the door, some patient can travel back home several times. Obsession of self-doubt → feeling guilty about issues Intrusive thoughts – 3rd most common. Intrusive obsessional thoughts without compulsion (repetitive sexual or aggressive acts, patients obsessed of there thoughts, may think that they suppose to report them to the police or to make a confession to the priest . Symmetry – 4th most common. Need for symmetry of precision → compulsion of slowness, patient can take an hour to eat a meal or shave their faces.","pyqMatches":[{"year":"2019","no":237,"q":"Which of the following is the poor prognostic factor for OCD?","o":["Magical thinking","Dirt contamination","Pathological doubt","Hoarding"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8684, 'Psychiatry', 'ECT & Biological Treatments', 'Easy', 'Psychiatry', 253, '{"id":8684,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Easy","source":"Psychiatry","sourceNo":253,"q":"Semen squeeze","o":["Erectile dysfunction","Premature ejaculation","Retrograde ejaculation","Antegrade ejaculation"],"a":1,"e":"Answer: B- Premature Ejaculation Squeeze Technique: Variation of the Masters and Johnson method. As a man approaches climax, either he or his partner squeezes the tip of the penis just below the head of the penis as he approaches the point of climax. Pressure is held there until the sensation of impending orgasm diminishes. This pressure can even be held until there is some reduction in erection. The process can then be started over again so that over time a man prolongs the time period until he reaches ejaculation. Useful to treat cases of premature ejaculation","pyqMatches":[{"year":"2018","no":201,"q":"Semen squeeze","o":["Erectile dysfunction","Premature ejaculation","Retrograde ejaculation","Antegrade ejaculation"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8685, 'Psychiatry', 'Anxiety & Related Disorders', 'Hard', 'Psychiatry', 254, '{"id":8685,"subject":"Psychiatry","chapter":"Anxiety & Related Disorders","difficulty":"Hard","source":"Psychiatry","sourceNo":254,"q":"A patient with a history of RTA before 2 months presents with complaints of dreams of accidents. He is able to visualize the same scene whenever he visits the place. Hence is afraid to go back to the accident site. Identify the type of disorder that he might be suffering from?","o":["Adjustment disorder","PTSD","Anxiety disorder","OCD"],"a":1,"e":"Answer: B - Post-traumatic Stress disorder Post-traumatic stress disorder, basically a type of anxiety disorder Though it shares features with other anxiety disorders, has its own specific characteristics in presentation. Criteria 1: Etiologically significant trauma should be present to be classified under this condition. Criteria 2: “Intentionality” or “aboutness”, an important factor in PTSD. PTSD concerns with memory intrusion of past stressors into present. Nightmares, flashbacks, or reliving experiences should be related to the past experience. Criteria 3: Avoid a stimulus or activity that provokes the memory of past event.","pyqMatches":[{"year":"2018","no":202,"q":"A patient with a history of RTA before 2 months presents with complaints of dreams of accidents. He is able to visualize the same scene whenever he visits the place. Hence is afraid to go back to the accident site. Identify the type of disorder that he might be suffering from?","o":["Adjustment disorder","PTSD","Anxiety disorder","OCD"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8686, 'Psychiatry', 'Psychotherapy & Behavioral Sciences', 'Moderate', 'Psychiatry', 255, '{"id":8686,"subject":"Psychiatry","chapter":"Psychotherapy & Behavioral Sciences","difficulty":"Moderate","source":"Psychiatry","sourceNo":255,"q":"Freud’s theory of dream includes all except:","o":["Displacement","Condensation","Symbolisation","Correlation"],"a":3,"e":"Answer: -D - Correlation Sigmund Freud theory of dream: Dream work involves the process of condensation, displacement, and secondary elaboration. Concept of unconscious mind: Primary assumption of Freudian theory is that the unconscious mind governs behavior to a greater degree than people suspect. Goal of psychoanalysis is to make the unconscious, conscious. Theory of dream: Freud theory of dream elaborates the state of unconscious mind with respect to dream interpretation, Process involved include condensation, displacement, and secondary elaboration. Displacement takes place when we transform the person or object we are really concerned about to someone else. The process of condensation is the joining of two or more ideas/images into one.","pyqMatches":[{"year":"2018","no":203,"q":"Freud’s theory of dream includes all except:","o":["Displacement","Condensation","Symbolisation","Correlation"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8687, 'Psychiatry', 'Miscellaneous', 'Easy', 'Psychiatry', 256, '{"id":8687,"subject":"Psychiatry","chapter":"Miscellaneous","difficulty":"Easy","source":"Psychiatry","sourceNo":256,"q":"Expression and consequent release of previously repressed emotion is called as","o":["Regression","Dissociation","Abreaction","All of the above"],"a":2,"e":"Answer: C - Abreaction The expression and consequent release of a previously repressed emotion, achieved through reliving the experience that caused it. Done typically through Hypnosis Suggestion","pyqMatches":[{"year":"2018","no":204,"q":"Expression and consequent release of previously repressed emotion is called as","o":["Regression","Dissociation","Abreaction","All of the above"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8688, 'Psychiatry', 'Mood Disorders', 'Moderate', 'Psychiatry', 257, '{"id":8688,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Moderate","source":"Psychiatry","sourceNo":257,"q":"All are habit disorder except","o":["Nail biting","Thumb sucking","Temper tantrum","Tics"],"a":2,"e":"Answer: C- Temper tantrum Definition: Habit disorder is a term used to describe several related disorders linked by the presence of repetitive and relatively stable behaviour that seem to occur beyond the awareness of the person performing the behaviour. The first group of habit disorder includes “Tic Disorder” Tics are involuntary movements, sounds, or words that are sudden, rapid, recurrent and non-rhythmic” In addition to TD’s, body-focussed behaviours, Recurrent hair pulling - Trichotillomania (TTM) Skin picking (SP) Nail biting , are included within habit disorders. Head banging, rocking of body, teeth grinding & thumb sucking are repetitive disorders. Seen in children between age group of 6 months to 2 years. Benign & self-limited. The movements serve a means of tension discharging in children. As children become older, they learn to inhibit some of their rhythmic patterns. Undue attention by parents can lead to aggravation of these problems.","pyqMatches":[{"year":"2018","no":205,"q":"All are habit disorder except","o":["Nail biting","Thumb sucking","Temper tantrum","Tics"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8689, 'Psychiatry', 'ECT & Biological Treatments', 'Easy', 'Psychiatry', 258, '{"id":8689,"subject":"Psychiatry","chapter":"ECT & Biological Treatments","difficulty":"Easy","source":"Psychiatry","sourceNo":258,"q":"New name of mental retardation according to American Association of Mental Retardation","o":["Feeble Mindedness","Madness","Intellectual disability","Mentally unstable"],"a":2,"e":"Answer: C - Intellectual disability Intellectual disability (ID), also known as general learning disability, Mental retardation (MR), is a generalized neurodevelopmental disorder characterized by significantly impaired intellectual and adaptive functioning.","pyqMatches":[{"year":"2018","no":206,"q":"New name of mental retardation according to American Association of Mental Retardation","o":["Feeble Mindedness","Madness","Intellectual disability","Mentally unstable"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8690, 'Psychiatry', 'Child & Adolescent Psychiatry', 'Easy', 'Psychiatry', 259, '{"id":8690,"subject":"Psychiatry","chapter":"Child & Adolescent Psychiatry","difficulty":"Easy","source":"Psychiatry","sourceNo":259,"q":"Now-a-days Down syndrome Is referred to as.","o":["Submental disorder","Oligophrenia","Madness","Mentally unstable"],"a":0,"e":"Answer: A - Submental disorder Majority of children with Down syndrome function in mild to moderate range of mental retardation. Down syndrome / Trisomy 21 - Genetic disorder caused by presence of all or part of a third copy ofchromosome 21. Typically associated with physical growth delays, characteristic facial features and mild to moderate intellectual disability.","pyqMatches":[{"year":"2018","no":207,"q":"Now-a-days Down syndrome Is referred to as.","o":["Submental disorder","Oligophrenia","Madness","Mentally unstable"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8691, 'Psychiatry', 'General Psychiatry', 'Hard', 'Psychiatry', 260, '{"id":8691,"subject":"Psychiatry","chapter":"General Psychiatry","difficulty":"Hard","source":"Psychiatry","sourceNo":260,"q":"A 55 years aged chronic alcoholic male, presented with irrelevant talks, tremor and sweating. He had his last drink 3 days back. What will the probable diagnosis?","o":["Delirium tremens","Korsakoff psychosis","Post-Acute withdrawal syndrome","Discontinuation syndrome"],"a":0,"e":"Answer: A - Delirium Tremens The description of symptoms is related to the condition “Delirium Tremens” Delirium Tremens / Alcohol Withdrawal Delirium (AWD): Most severe form of ethanol withdrawal manifested by, Altered mental status (Global confusion) Autonomic hyperactivity (Sympathetic overdrive) Mechanism: Alcohol abuse affects neurotransmitter systems in brain mainly by, Loss of GABA inhibitory mechanism - Reduces chloride ion influx. Alcohol acts as NMDA receptor antagonist - Withdrawal increases the excitatory neurotransmitter. The clinical manifestations of ethanol withdrawal are combination effects of GABA & NMDA receptor activity. Thus causing tremors, diaphoresis, tachycardia, anxiety & in severe cases Seizure.","pyqMatches":[{"year":"2018","no":208,"q":"A 55 years aged chronic alcoholic male, presented with irrelevant talks, tremor and sweating. He had his last drink 3 days back. What will the probable diagnosis?","o":["Delirium tremens","Korsakoff psychosis","Post-Acute withdrawal syndrome","Discontinuation syndrome"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8692, 'Psychiatry', 'Schizophrenia & Psychosis', 'Easy', 'Psychiatry', 261, '{"id":8692,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Easy","source":"Psychiatry","sourceNo":261,"q":"What differentiates delirium from dementia?","o":["Confusion","Difficulty in communicating","Hallucination","Sudden change"],"a":3,"e":"Answer: D. Sudden change Delirium Also called the acute confusional state, delirium is a medical condition that results in confusion and other disruptions in thinking and behavior, including changes in perception, attention, mood and activity level. In dementia, changes in memory and intellect are slowly evident over months or years. Delirium is a more abrupt confusion, emerging over days or weeks, and represents a suddenchange from the person’s previous course of dementia. Thinking becomes more disorganized, and maintaining a coherent conversation may not be possible. The hallmark separating delirium from underlying dementia is inattention. The individual simply cannot focus on one idea or task.","pyqMatches":[{"year":"2018","no":277,"q":"What differentiates delirium from dementia?","o":["Confusion","Difficulty in communicating","Hallucination","Sudden change"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8693, 'Psychiatry', 'Substance Use Disorders', 'Easy', 'Psychiatry', 262, '{"id":8693,"subject":"Psychiatry","chapter":"Substance Use Disorders","difficulty":"Easy","source":"Psychiatry","sourceNo":262,"q":"Most common DRUG causing dependence?","o":["Cannabis","Cocaine","Heroin","Amphetamine"],"a":0,"e":"ANS - A.Cannabis Cannabis- 9 million users,192 million users(Acc. To WHO Drug report 2018) Heroin (opioid derivative) -2.5 lakh users It is estimated that 275 million people used illicit drugs, such as cannabis, amphetamines, opioids, and cocaine, in 2016 which translates into an annual prevalence of illicit drug use of 5.6%. Cannabis is most used with 192 million users. Some 31 million people who use drugs suffer from drug use disorders.-(WHO Drug report 2018) Ref: ARVIND ARORA review of psychiatry p:64, WHO Drug report(2018)","pyqMatches":[{"year":"2020","no":236,"q":"Most common DRUG causing dependence?","o":["Cannabis","Cocaine","Heroin","Amphetamine"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8694, 'Psychiatry', 'General Psychiatry', 'Hard', 'Psychiatry', 263, '{"id":8694,"subject":"Psychiatry","chapter":"General Psychiatry","difficulty":"Hard","source":"Psychiatry","sourceNo":263,"q":"MBBS student she was choking with dyspnea, chest tightness, anxiety and an impending sense of doom on examination all systemic conditions were found normal, then she went to psychiatry. What is the probable diagnosis of the condition?","o":["Panic disorder","Depression","Epilepsy","Asthma"],"a":0,"e":"ANS - A. Panic disorder Panic disorder-severe anxiety with choking, chest pain and palpitations. Depression- low mood and lost interest in activities Epilepsy-neurological disorder with whole-body fatigue and muscle spasms An asthma-respiratory disorder associated with symptoms of cough, wheezing, etc Ref: ARVIND ARORA review of psychiatry p:131","pyqMatches":[{"year":"2020","no":237,"q":"MBBS student she was choking with dyspnea, chest tightness, anxiety and an impending sense of doom on examination all systemic conditions were found normal, then she went to psychiatry. What is the probable diagnosis of the condition?","o":["Panic disorder","Depression","Epilepsy","Asthma"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8695, 'Psychiatry', 'Mood Disorders', 'Hard', 'Psychiatry', 264, '{"id":8695,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Hard","source":"Psychiatry","sourceNo":264,"q":"A patient with depression was given Imipramine for 2 weeks. Relatives noticed increased excitement, colourful clothes, increased talking. What is the next step in management?","o":["Antipsychotic with Imipramine continued","Discontinue Imipramine and start Valproate","Continue Imipramine alone","Manage with Valproate alone"],"a":0,"e":"ANS-A. Antipsychotic with Imipramine continued The condition from which the patient above is suffering is a bipolar disorder which includes both depression and mania. So in order to treat both antidepressant i.e imipramine is continued along with an antipsychotic such as phenothiazines, thioxanthenes, etc. Antipsychotic or valproate alone cannot reduce the depression and Imipramine alone cannot reduce the mania. Ref: ARVIND ARORA review of psychiatry p.no:111","pyqMatches":[{"year":"2020","no":238,"q":"A patient with depression was given Imipramine for 2 weeks. Relatives noticed increased excitement, colourful clothes, increased talking. What is the next step in management?","o":["Antipsychotic with Imipramine continued","Discontinue Imipramine and start Valproate","Continue Imipramine alone","Manage with Valproate alone"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8696, 'Psychiatry', 'Psychotherapy & Behavioral Sciences', 'Hard', 'Psychiatry', 265, '{"id":8696,"subject":"Psychiatry","chapter":"Psychotherapy & Behavioral Sciences","difficulty":"Hard","source":"Psychiatry","sourceNo":265,"q":"A Patient falls down often with behavioral change and enuresis. What is the condition associated with him?","o":["Frontotemporal dementia","Normal pressure hydrocephalus","Parkinson''s disease","Alzheimer''s disease"],"a":1,"e":"Ans- B. Normal pressure hydrocephalus Frontotemporal dementia - Associated with poor behavioral control, decision making, and language. Normal-pressure hydrocephalus - Associated with gait disturbance, behavioural change, enuresis, and dementia. Parkinson’s disease - Associated with tremor and muscular stiffness Alzheimer’s disease-Associated mainly with memory loss and confusion Ref: Normal Pressure Hydrocephalus By Michael J. Fritsch, Uwe Kehler, Ullrich Meier P .16; Oxford textbook of neurological surgery by Adel Helmy P.94","pyqMatches":[{"year":"2020","no":239,"q":"A Patient falls down often with behavioral change and enuresis. What is the condition associated with him?","o":["Frontotemporal dementia","Normal pressure hydrocephalus","Parkinson''s disease","Alzheimer''s disease"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8697, 'Psychiatry', 'Schizophrenia & Psychosis', 'Hard', 'Psychiatry', 266, '{"id":8697,"subject":"Psychiatry","chapter":"Schizophrenia & Psychosis","difficulty":"Hard","source":"Psychiatry","sourceNo":266,"q":"A Patient with depressive symptoms for 6 months and associated with auditory hallucinations for 2 weeks. What is the probable diagnosis of the condition?","o":["Psychotic depression","Schizoaffective disorder","Mania depressive illness","Schizophrenia"],"a":0,"e":"Ans- A. Psychotic depression Psychotic depression- Depression along with psychotic symptoms such as hallucinations, delusions, etc. Schizoaffective disorder-Symptoms of schizophrenia and mood disturbances occur together. Mania depressive illness - Mania depression along with psychotic symptoms. Schizophrenia includes all the symptoms of schizophrenia Ref: Arvind Arora review of Psychiatry page. 103","pyqMatches":[{"year":"2020","no":240,"q":"A Patient with depressive symptoms for 6 months and associated with auditory hallucinations for 2 weeks. What is the probable diagnosis of the condition?","o":["Psychotic depression","Schizoaffective disorder","Mania depressive illness","Schizophrenia"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8698, 'Radiology', 'Abdominal Radiology', 'Easy', 'Radiology', 1, '{"id":8698,"subject":"Radiology","chapter":"Abdominal Radiology","difficulty":"Easy","source":"Radiology","sourceNo":1,"q":"Coffee bean sign is seen in?","o":["Gastric volvulus","Sigmoid volvulus","Hypertrophic pyloric stenosis","Midgut volvulus"],"a":1,"e":"Sigmoid volvulus REF: Wofganag 5th e p. 846/748 Sign Disease Rat tail appearance Carcinoma esophagus Bird beak appearance Achalasia Beak sign/double track/ tram track Hypertrophic pyloric stenosis Medusa head colonies on CT Round worm Pincer/claw/coiled spring/target/meniscus sign Intussception Coffee bean sign Sigmoid volvulous Lead pipe appearance Ulcerative colitis String of kantor/bull''s eye Chron''s disease Thumb printing sign Ischemic colitis Saw tooth appeance on barium enema Diverticulosis Apple core sign Carcinoma colon Cork screw appearance Diffuse esophageal spasm String sign Hypertrophic pyloric stenosis","pyqMatches":[{"year":"2014","no":2024,"q":"Coffee bean sign is seen in?","o":["Gastric volvulus","Sigmoid volvulus","Hypertrophic pyloric stenosis","Midgut volvulus"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8699, 'Radiology', 'GI Radiology', 'Easy', 'Radiology', 2, '{"id":8699,"subject":"Radiology","chapter":"GI Radiology","difficulty":"Easy","source":"Radiology","sourceNo":2,"q":"Rat tail appearance in contrast radiography is seen in?","o":["Achalasia cardia","Carcinoma esophagus","Cork screw esophagus","Diffuse esophageal spasms"],"a":1,"e":"Carcinoma esophagus REF: sabiston''s 18'' edition chapter 41 See table in the previous question \"Rat-tail\" appearance on barium study is seen in carcinoma esophagus.","pyqMatches":[{"year":"2012","no":1426,"q":"Rat tail appearance in contrast radiography is seen in?","o":["Achalasia cardia","Carcinoma esophagus","Cork screw esophagus","Diffuse esophageal spasms"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8700, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 3, '{"id":8700,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":3,"q":"Which chamber enlargement shows a double right heart border with a wide subcarinal angle?","o":["Left atrium","Left ventricle","Right atrium","Right ventricle"],"a":0,"e":"Answer- A- Left atrium Radiological signs of left atrial enlargement: A ''double'' right heart border Elevation of the left main bronchus Splaying of the carina Enlargement of the left atrial appendage The prominence of the portion of the left heart border at the level of the left main bronchus","pyqMatches":[{"year":"2012","no":1424,"q":"Which chamber enlargement shows a double right heart border with a wide subcarinal angle?","o":["Left atrium","Left ventricle","Right atrium","Right ventricle"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8701, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 4, '{"id":8701,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":4,"q":"Mercedes Benz sign is seen in:","o":["Gall stone","Bladder stone","Renal stones","Foreign body bronchus"],"a":0,"e":"Gall stone REF: Sutton''s textbook of radiology, Th edition, volume 1 page 713 Mercedes Benz sign/Seagull sign/Crow feet sign: Gall bladder stone if radiopaque has a stellate faceted appearance with gas containing fissures on the plain radiograph and is called as Mercedes Benz sign/Seagull sign or Crow feet sign","pyqMatches":[{"year":"2014","no":2023,"q":"Mercedes Benz sign is seen in:","o":["Gall stone","Bladder stone","Renal stones","Foreign body bronchus"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8702, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 5, '{"id":8702,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":5,"q":"Chain of lakes appearance is seen in?","o":["Chronic pancreatitis","Acute pancreatitis","Gall stone ileus","Sub-acute intestinal obstruction"],"a":0,"e":"Chronic pancreatitis REF: Sutton''s Radiology 7th edition volume 1 page 798, Sabiston textbook of surgery 18th ed chapter 5 Chronic pancreatitis is characterized by irregularities of the pancreatic ducts, ductal strictures, and areas of duct dilation. The major as well as the side-branch ducts may be involved. For unexplained reasons, some patients with chronic pancreatitis develop dilated main pancreatic ducts (large duct disease), whereas others retain ducts of normal or even smaller than normal caliber (small duct disease). Some patients with chronic pancreatitis can be shown to have major ducts that have the appearance of a \"chain of lakes\" or a \"string of pearls\" that is the result of segments of dilated duct separated by areas of ductal stricture","pyqMatches":[{"year":"2016","no":1752,"q":"Chain of lakes appearance is seen in?","o":["Chronic pancreatitis","Acute pancreatitis","Gall stone ileus","Sub-acute intestinal obstruction"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8703, 'Radiology', 'Abdominal Radiology', 'Easy', 'Radiology', 6, '{"id":8703,"subject":"Radiology","chapter":"Abdominal Radiology","difficulty":"Easy","source":"Radiology","sourceNo":6,"q":"\"Cork screw appearance\" is characteristic of?","o":["Carcinoma esophagus","Hypertrophic pyloric stenosis","Diffuse esophageal spasm","Sigmoid volvulous"],"a":2,"e":"Diffuse esophageal spasm REF: Wofganag 5th e p. 846/748 Sign Disease Rat tail appearance Carcinoma esophagus Bird beak appearance Achalasia Beak sign/ double track/ tram track Hypertrophic pyloric stenosis Medusa head colonies on CT Round worm Pincer/claw/coiled spring/target/ meniscus sign Intussception Coffee bean sign Sigmoid volvulous Lead pipe appearance Ulcerative colitis String of kantor/bull''s eye Chron''s disease Thumb printing sign Ischemic colitis Saw tooth appeance on barium enema Diverticulosis Apple core sign Carcinoma colon Cork screw appearance Diffuse esophageal spasm String sign Hypertrophic pyloric stenosis","pyqMatches":[{"year":"2014","no":1560,"q":"\"Cork screw appearance\" is characteristic of?","o":["Carcinoma esophagus","Hypertrophic pyloric stenosis","Diffuse esophageal spasm","Sigmoid volvulous"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8704, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 7, '{"id":8704,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":7,"q":"An absolute contraindication of MRI is:","o":["Pacemaker","Prosthetic cardiac valves","Insulin pump","Choclear implants"],"a":0,"e":"Pacemaker [Ref: Harrison 17/e p2494; Grainger Diagnostic Radiology 4/e p122; various websites-http://www.mr-tip.com/servl.php?ope=dbl &dbs=Prosthetic%20Heart%20Valves http://www. imrser.org/PDF/Shellock.HeartValves.JMRLpdf; http ://www. mr​tip. com/se ry 1.php ?type = dh 1 &dbs= Prosthetic %20Heart %20Valves ;and journal- _RadioGraphic s 2004 ;24 : 1257- 1267 MR is considered among the safest imaging modalities for patients, even at very high field strengths, more than 3-4 tesla. But Ferromagnetic objects under magnetic field can be vulnerable to 4 adverse effects: Movement (causing structural injury), Current conduction (potentially causing electrical shock), Heating (possibly causing burn injury), and Artifact generation Serious injuries can be caused by attraction of ferromagnetic objects into the magnet, which would act as missiles if brought too close to the magnet. Ferromagnetic implants, such as aneurysm clips, may torque (turn or twist) due to the magnetic field, causing damage to vessels and even death. Metallic foreign bodies in the eye have moved and caused intraocular hemorrhage. Pacemakers and pacemaker leads are a contraindication, as the pacemaker can malfunction and cause arrhythmia or even death. However with growing expansion of MR, increasing number of implant medical devices are being MR safe. So newer pacemaker and aneurysm clips are being made which are MR safe. Absolute Contraindications for the MRI scan: Electronically, magnetically, and mechanically activated implants Ferromagnetic or electronically operated active devices like automatic cardioverter defibrillators Cardiac pacemakers Metallic splinters in the eye Ferromagnetic haemostatic clips in the central nervous system (CNS) Patients with an implanted cardiac pacemaker have been scanned on rare occasions, but pacemakers are generally considered an absolute contraindication. Relative Contraindications for the MRI scan: Cochlear implants Other pacemakers, e.g. for the carotid sinus Insulin pumps and nerve stimulators Lend wires or similar wires (MRI Safety risk) Prosthetic heart valves (in high .fields, if dehiscence is suspected) Haemostatic clips (body) Nonierromagnetic stapedial implants Women with a.first-trimester pregnancy Tattoos (only a problem in higher-strength magnetic .field i.e. more than 3 tesla) 1Reflittp://www.mr-tip.com/se ry 1 .php?type=dbl &dbs= Prosthetic %20Heart%20Valvesi","pyqMatches":[{"year":"2014","no":2008,"q":"An absolute contraindication of MRI is:","o":["Pacemaker","Prosthetic cardiac valves","Insulin pump","Choclear implants"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8705, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 8, '{"id":8705,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":8,"q":"Floating water lily sign is seen in","o":["Aspergillosis","Hamartoma","Hydatid cyst","Cavitating metastasis"],"a":2,"e":"Hydatid cyst [Ref Radiology Review Manual by Dahnert 5/e, p 699; vviviv.emedicine.00In/Ined/TOPIC629.htn] Separated membranes floating with the cyst give the appearance of water lily. It is pathognomonic of hydatid cyst.","pyqMatches":[{"year":"2014","no":2036,"q":"Floating water lily sign is seen in","o":["Aspergillosis","Hamartoma","Hydatid cyst","Cavitating metastasis"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8706, 'Radiology', 'Imaging Principles & Contrast', 'Moderate', 'Radiology', 9, '{"id":8706,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Moderate","source":"Radiology","sourceNo":9,"q":"The scan with highest sensitivity to detect adrenal metastasis due to bronchogenic carcinoma is:","o":["Contrast Enhanced CT abdomen with Adrenal protocol","PET scan","MRI scan","Radionuclide scan"],"a":1,"e":"Scans to differentiate adrenal adenoma from adrenal metastasis are: CECT - Chemical shift MRI FDG-PET PETscan has almost 100 % sensitivity for detecting adrenal metastasis, so a negative study excludes the possibility of adrenal mets. But adenomas can give false positive test. Ref: Fundamentals of Diagnostic Radiology, Edition - 4, Page - 427.","pyqMatches":[{"year":"2012","no":1421,"q":"The scan with highest sensitivity to detect adrenal metastasis due to bronchogenic carcinoma is:","o":["Contrast Enhanced CT abdomen with Adrenal protocol","PET scan","MRI scan","Radionuclide scan"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8707, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 10, '{"id":8707,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":10,"q":"Which of the following agents is used to measure Glomerular Filtration Rate (GFR)?","o":["Iodohippurate","Tc99m-DTPA","Tc99m-MAG3","Tc99m-DMSA"],"a":1,"e":"Tc99m-Diethylene Triamine Pentothenic Acid (DTPA) is an agent of choice widely used in measuring GFR. Ref: Renal Disease: Techniques and Protocols By Michael S Goligorsky, Page 87; Paediatric Uroradiology By Richard Fotter, ALbert L Baert, Page 47","pyqMatches":[{"year":"2015","no":1661,"q":"Which of the following agents is used to measure Glomerular Filtration Rate (GFR)?","o":["Iodohippurate","Tc99m-DTPA","Tc99m-MAG3","Tc99m-DMSA"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8708, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 11, '{"id":8708,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":11,"q":"The CT severity index in acute pancreatitis is described by:","o":["Balthazar","Mengini","Chapman","Napelon"],"a":0,"e":"The CT severity index (CTSI)-described by Balthazar Balthazar CT Severity Index CT Grade Score A. Normal- 0 B. Enlarged gland -1 C. Peri-pancreatic inflammation- 2 D. One fluid collection- 3 E. Two or more collections- 4 Necrosis Score 30%-50%- (4) >50% -(6) Ref: ACR Appropriateness Criteria,Acute Pancreatitis.","pyqMatches":[{"year":"2013","no":1408,"q":"The CT severity index in acute pancreatitis is described by:","o":["Balthazar","Mengini","Chapman","Napelon"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8709, 'Radiology', 'Imaging Principles & Contrast', 'Moderate', 'Radiology', 12, '{"id":8709,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Moderate","source":"Radiology","sourceNo":12,"q":"Radiocontrast is contraindicated in all of the following conditions except?","o":["Renal failure","Patient on metformin","Dehydration","Obesity"],"a":3,"e":"Obesity is not a contra-indication for the administration of radio-contrast agent. Ref: Radiologic Technology at a Glance By Theresa S. Reid-Paul; pages 66.","pyqMatches":[{"year":"2014","no":2009,"q":"Radiocontrast is contraindicated in all of the following conditions except?","o":["Renal failure","Patient on metformin","Dehydration","Obesity"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8710, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 13, '{"id":8710,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":13,"q":"A PET scan uses which of the following tracer materials?","o":["FDG","CDF","ADP","MIBG"],"a":0,"e":"Positron emission tomography (PET) uses positron-emitting radioisotope (tracer) - 18F-FDG A PET scan uses a small amount of a radioactive drug, or tracer, to show differences between healthy tissue and diseased tissue. The most commonly used tracer is called FDG (fluorodeoxyglucose), so the test is sometimes called an FDG-PET scan. Very expensive. Better contrast and spatial resolution","pyqMatches":[{"year":"2014","no":2006,"q":"A PET scan uses which of the following tracer materials?","o":["FDG","CDF","ADP","MIBG"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8711, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 14, '{"id":8711,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":14,"q":"Which one of the following has the maximum ionization potential?","o":["Proton","Electron","Helium ion","Gamma (y) – Photon"],"a":2,"e":"Helium ion has maximum ionizing potential. The ionizing potential of atoms ranges from a few eV for alkali elements to 24.6eV for helium which has the maximum ionizing potential. Ref: Radiation Physics for Medical Physicists By Ervin B. Podgoršak, Page 7","pyqMatches":[{"year":"2013","no":1789,"q":"Which one of the following has the maximum ionization potential?","o":["Proton","Electron","Helium ion","Gamma (y) – Photon"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8712, 'Radiology', 'Imaging Principles & Contrast', 'Moderate', 'Radiology', 15, '{"id":8712,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Moderate","source":"Radiology","sourceNo":15,"q":"All of the following about MRI are correct except:","o":["MRI is contraindicated in patients with pacemakers","MRI is useful for evaluating bone marrow","MRI is better for calcified lesions","MRI is useful for localizing small lesione in the brain"],"a":2,"e":"C i.e. MRI is better for calcified lesions * MRI is very poor in detection of calcification. It is inferior to CT scan, mammography and x-ray in detecting calcification. That is why it lags behind mammography in early detection of noninvasive ductal carcinoma in situ (DCIS)Q, which most commonly has microcalcification as its only presenting feature. And similarly it has a very limited role in detection of renal stones and gall stonesQ. However, it is important to note that only upto 60% of gall stones have enough calcium density (more than that of bile) to get visualized on CT. Becaus of its superior calcification detection abilities, MDCT is used in Agatston scoring (Coronary calcium scoring) of calcified plaques of coronary artery using coronary calcium as a surrogate marker to detect the presence and measure the amount of coronary atherosclerosis. Because with exception of patients with renal failure calcification of arteries occurs exclusively in context of atherosclerosis. Similarly nonenhanced helical CT is superior to all other imaging modalities in diagnosis of urinary tract calculiQ but at the cost of higher radiation exposure. Now there is no need to say that MRI is better that CT for evaluation of bone marrow, small brain lesions, meniscus/ ligament injuries, soft tissue tumors and meningeal pathology. But MRI is very poor in detection of calcification.","pyqMatches":[{"year":"2014","no":2007,"q":"All of the following about MRI are correct except:","o":["MRI is contraindicated in patients with pacemakers","MRI is useful for evaluating bone marrow","MRI is better for calcified lesions","MRI is useful for localizing small lesione in the brain"],"a":2,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":1638,"q":"All of the following about MRI are correct except:","o":["MRI is contraindicated in patients with pacemakers","MRI is useful for evaluating bone marrow","MRI is better for calcified lesions","MRI is useful for localizing small lesione in the brain"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8713, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 16, '{"id":8713,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":16,"q":"Tufting of distal phalanx is characteristically seen in","o":["Gout","Hyperkalemia","Hypoparathyroidism","Hyperparathyroidism"],"a":3,"e":"Ans. is. D. Hyperparathyroidism Acro-osteolysis is the term used to describe resorption of the distal phalangeal tufts. Causes are : -","pyqMatches":[{"year":"2014","no":2021,"q":"Tufting of distal phalanx is characteristically seen in","o":["Gout","Hyperkalemia","Hypoparathyroidism","Hyperparathyroidism"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8714, 'Radiology', 'Musculoskeletal Radiology', 'Easy', 'Radiology', 17, '{"id":8714,"subject":"Radiology","chapter":"Musculoskeletal Radiology","difficulty":"Easy","source":"Radiology","sourceNo":17,"q":"Calcification of Intervertebral Disc is seen in","o":["Gout","Rheumatoid","Alkaptonuria","Psoriasis"],"a":2,"e":"C i.e. Alkaptonuria FeaturesDisease Fish Mouth Vertebrae - Sickel Cell AnemiaQ HomocystinuriaQ Cod Fish Vertebra (Biconcave vertebra) - Osteomalacia, Osteoporosis, Hyperparathyroid Rugger jersey spine (sclerosis of upper & lower spine borders) - CRF induced osteomalaciaQ - Osteopterosis (marbel bone disease) Calcification of Intervertebral disc - Alkaptonuria (m.c.) Picture Frame vertebrae - Paget''s disease Vertebrae plana - Eosinophilic granulomaQ","pyqMatches":[{"year":"2012","no":1441,"q":"Calcification of Intervertebral Disc is seen in","o":["Gout","Rheumatoid","Alkaptonuria","Psoriasis"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8715, 'Radiology', 'Chest Radiology', 'Easy', 'Radiology', 18, '{"id":8715,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Easy","source":"Radiology","sourceNo":18,"q":"Schober''s sign is for :","o":["Flexion of lumbar spine","Chest expansion","Pain with motion of hip","Neck pain and stiffness"],"a":0,"e":"A i.e. Flexion of lumber spine Schober''s test is measure of flexion on lumber spineQ. This test is done in ankylosing spondylitisQ","pyqMatches":[{"year":"2014","no":1372,"q":"Schober''s sign is for :","o":["Flexion of lumbar spine","Chest expansion","Pain with motion of hip","Neck pain and stiffness"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8716, 'Radiology', 'Musculoskeletal Radiology', 'Easy', 'Radiology', 19, '{"id":8716,"subject":"Radiology","chapter":"Musculoskeletal Radiology","difficulty":"Easy","source":"Radiology","sourceNo":19,"q":"Bone within bone appearance is seen in?","o":["CML","Osteoporosis","Osteopetrosis","Bone infarct"],"a":2,"e":"C i.e. Osteopetrosis In osteopetrosis, there is reduced osteoclastic bone resorption resulting in diffuse symmetrical skeleton sclerosis. Also k/a marble bone disease d/t its stone like quality of bones; however the bones are abnormally brittle & fracture like a piece of chalk. It can present radiologically as? Sclerosis of all bones more prominent at base of skullQ. Sclerosis of vertebral end plate 1/t characteristic sandwitch or broad stripped (rugby jersey spine) Q Bone in bone appearanceQ d/t sclerotic foci within the bone.","pyqMatches":[{"year":"2012","no":1435,"q":"Bone within bone appearance is seen in?","o":["CML","Osteoporosis","Osteopetrosis","Bone infarct"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8717, 'Radiology', 'Chest Radiology', 'Easy', 'Radiology', 20, '{"id":8717,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Easy","source":"Radiology","sourceNo":20,"q":"\"Sunray appearance\" on X-rays is suggestive of:","o":["A Chondrosarcoma","A metastatic tumour in the bone","An Osteogenic sarcoma","An Ewing''s sarcoma"],"a":2,"e":"C i.e. Osteogenic Sarcoma Sunray appearance is classically seen in osteosarcoma. It may also occur in metastases, Ewings sarcoma, Haemang oma, Meningioma and tuberculosis.","pyqMatches":[{"year":"2012","no":1434,"q":"\"Sunray appearance\" on X-rays is suggestive of:","o":["A Chondrosarcoma","A metastatic tumour in the bone","An Osteogenic sarcoma","An Ewing''s sarcoma"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8718, 'Radiology', 'Imaging Principles & Contrast', 'Moderate', 'Radiology', 21, '{"id":8718,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Moderate","source":"Radiology","sourceNo":21,"q":"Inferior rib notching is seen in","o":["Coarctation of aorta","Rickets","ASD","Multiple myeloma"],"a":0,"e":"A i.e. Coarctation of aorta Inferior rib notching in coarctation of aorta is d/t pressure erosion of intercostal arteriesQ It usually takes several years to develop, so is unusual before 10 years of age.","pyqMatches":[{"year":"2013","no":1762,"q":"Inferior rib notching is seen in","o":["Coarctation of aorta","Rickets","ASD","Multiple myeloma"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8719, 'Radiology', 'Chest Radiology', 'Moderate', 'Radiology', 22, '{"id":8719,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Moderate","source":"Radiology","sourceNo":22,"q":"Flask shaped heart is seen in following except:","o":["Ebstein anomaly","Pericardial effusion","TOF","TAPVC"],"a":3,"e":"D i.e. TAPVC Due to dilation of SVC (superior vena cava) & left vertical vein, TAPVC (total anomalous pulmonary venous connection / return) of supra diaphragmatic variety shows double contour/ \"Figger of 8\"/ Snowman configuration of cardiac silhouetteQ.","pyqMatches":[{"year":"2013","no":1766,"q":"Flask shaped heart is seen in following except:","o":["Ebstein anomaly","Pericardial effusion","TOF","TAPVC"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8720, 'Radiology', 'Chest Radiology', 'Easy', 'Radiology', 23, '{"id":8720,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Easy","source":"Radiology","sourceNo":23,"q":"Soap Bubble appearance in X-ray is seen in","o":["Multiple cystic Kidney","Neuroblastoma","Cystic lymphagiectasis","Meconium ileus"],"a":3,"e":"D i.e. Meconium ileus Soap bubble appearance in X ray is seen in meconium ileus due to admixture of gas with meconium.","pyqMatches":[{"year":"2014","no":2022,"q":"Soap Bubble appearance in X-ray is seen in","o":["Multiple cystic Kidney","Neuroblastoma","Cystic lymphagiectasis","Meconium ileus"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8721, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 24, '{"id":8721,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":24,"q":"Rim sign in IVP is seen in","o":["Polycystic Kidney","Hydronephrosis","Chronic pyelonephritis","Hypernephroma"],"a":1,"e":"B i.e. Hydronephrosis Rim Sign in Nephrogram-","pyqMatches":[{"year":"2012","no":1430,"q":"Rim sign in IVP is seen in","o":["Polycystic Kidney","Hydronephrosis","Chronic pyelonephritis","Hypernephroma"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8722, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 25, '{"id":8722,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":25,"q":"The most accurate investigation for assessing ventricular function is:","o":["Multislice CT","Echocardiography","Nuclear scan","MRI"],"a":1,"e":"B i.e. Echocardiography Transthoracic echocardiography is the most commonly used cardiac imaging examination after the chest X-ray and probably approaches the electrocardiogram in its clinical utility. It is harmless and relatively comfortable for the patient and is the first-line technique for evaluating most abnormalities of the cardiac chambers, valves and great vessels. Diagnotic utility Chest X-ray Transthoracic echocardiogram Transesophageal echocardiogram Nuclear medicine technique Multislic CT Anatomy Myocardium+ ++ +++ + ++ Valves + ++ +++ 0 + Coronaries 0 0 + 0 ++ Pericardium + + + 0 ++ Pulmonary vessels +++ 0 0 0 +++ Calcification +++ + + 0 +++ Function Myocardium++ ++ +++ ++ + Valves + ++ +++ 0 + Coronaries 0 0 + ++ ++ Limitations Radiation hazard - 0 0 - - Risk/ discomfort 0 0 - - - - Spatial resolution - - - Temporal resolution - - Operator skill - - - - - Cost -- +++ = Major utility; ++ = moderate utility, + = minor utility; 0 = no utility/no limitations; - = minor limitation-- - = moderate limitation; - - - major limitation","pyqMatches":[{"year":"2013","no":1246,"q":"The most accurate investigation for assessing ventricular function is:","o":["Multislice CT","Echocardiography","Nuclear scan","MRI"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8723, 'Radiology', 'Chest Radiology', 'Hard', 'Radiology', 26, '{"id":8723,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Hard","source":"Radiology","sourceNo":26,"q":"In patient with high clinical suspicion of pulmonary thromboembolism, best investigation would be?","o":["D-dimer","CT angiography","Catheter angiography","Color Doppler"],"a":1,"e":"B i.e. CT angiography Spiral or helical chest CT scan with intravenous contrast (CT pulmonary angiography) is the principal imaging test for the diagnosis of pulmonary embolsmQ. It acquires image with < 1 m resolution and visualizes up to 6th order branches and small peripheral emboli with a resolution superior to conventional invasive contrast pulmonary angiography. It obtains excellent images of right & left ventricle and can be used for diagnosis as well as risk stratification. In patients with pulmonary embolism, RV enlargement indicates 5 times more likelihood of death within next 30 days. Inadequate breath holding can impair the image quality b/o change in arterial flow rates and motion artefact during breathing. The advent of multidetector CT (MDCT) allows examination of whole lung during single breath -hold. It is noninvasive. Ventilation - perfusion lung scanning is now second line diagnostic testa for PE, and mostly used in patients who cannot tolerate intravenous contrast. Its utility is greatest when accompanied with a normal chest x-ray implying that a ventilation - perfusion mismatch is not due to parenchymal disease. High probability (>80%) scan have 2 large segmental V-P mismatches (perfusion defects & normal ventilation) with a normal chest radiograph. And very low probability scans have microparticles (10 - 100 1.1 m) of Tc99 micro - aggregate albumin (MAA) in patients lying supine. Ventilation scintigraphy is performed by inhalating Krypton - 81, (best), Xenon 133, Tc99 - diethylenetriamine penta acetic acid (DTPA), or technegas. Last two can''t be administered during perfusion scan as both are labelled with Tc99. Eight images (anterior, posterior, obtique & lateral on both sides) are aquired. Conventional pulmonary angiography: Non invasive CT with contrast have virtually replaced invasive pulmonary angiography as a diagnostic tool. However, it remains the gold standard testa.","pyqMatches":[{"year":"2013","no":1757,"q":"In patient with high clinical suspicion of pulmonary thromboembolism, best investigation would be?","o":["D-dimer","CT angiography","Catheter angiography","Color Doppler"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8724, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 27, '{"id":8724,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":27,"q":"Investigation of choice for studying Renal Cortical mass","o":["99 Tc DTPA","53 Cr Study","99 Tc DMSA","99 Tc Pyrophosphate"],"a":2,"e":"C i.e. 99 - Tc - DMSA DTPA (Renogram) DMSA (Isotope Scanning) - DTPA is freely filtered at glomerulus with no - Tc.99 DMSA is used for renal morphological tubular reabsorption or excretion (i.e. GFR =(anatomic) imagine Excretory function) - This compound gets fixed in renal tubules & images - DTPA is useful for evaluating perfusion and may be obtained after 1-2 hours of injection. Lesions excretory function of each kidneyQ such as tumors & benign lesions as cysts show filling - Indications:defectQ","pyqMatches":[{"year":"2012","no":1429,"q":"Investigation of choice for studying Renal Cortical mass","o":["99 Tc DTPA","53 Cr Study","99 Tc DMSA","99 Tc Pyrophosphate"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8725, 'Radiology', 'Ultrasound & Doppler', 'Easy', 'Radiology', 28, '{"id":8725,"subject":"Radiology","chapter":"Ultrasound & Doppler","difficulty":"Easy","source":"Radiology","sourceNo":28,"q":"Investigation of choice for screening of proximal internal carotid artery stenosis is :","o":["Doppler flow USG","CT substraction angiography","MRI","Angiography (DSA)"],"a":0,"e":"Answer is A (Doppler flow USG): ''Stenosis at the origin of the internal carotid Artery can be identified and quantified reliably by ultrasonography that combines B mode ultrasound image with a Doppler ultrasound assessment of flow velocity.''","pyqMatches":[{"year":"2012","no":1433,"q":"Investigation of choice for screening of proximal internal carotid artery stenosis is :","o":["Doppler flow USG","CT substraction angiography","MRI","Angiography (DSA)"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8726, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 29, '{"id":8726,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":29,"q":"Roentgen is the unit of: March 2010","o":["Radioactivity","Radiation exposure","Absorbed dose","None of the above"],"a":1,"e":"Ans. B: Radiation Exposure The curie, named after scientist Marie Curie, is a unit of measurement used to measure how radioactive an object is, or how much radiation it produces. This is done by examining how fast its atoms disintegrate and measuring their disintegration per second. Roentgen, on the other hand, is a radiation unit that indicates how much radiation is present in the air of a specific environment. This is used to show how much radiation may be absorbed by standing in a particular place for a certain amount of time. One roentgen of gamma- or X-ray exposure produces approximately 1 rad (0.01 gray) tissue dose. More common than these two are the rad and the rem. These two units can measure any type of ionizing radiation, including alpha, beta, neutron, gamma and \"X,\" and deal with how much radiation is absorbed by objects. Rad stands for \"radiation absorbed dose.\" One rad equals 100 ergs (an energy unit) absorbed by 1 g of material. Rads are used to show how much radiation any object, especially things like metal and stone, has absorbed. Rem (dose equivalent)is a strictly biological measurement, and stands for \"roentgen equivalent man,\" meaning that it is the same essential measurement as a roentgen, only applied to the human body, although this works only with gamma and \"X\" types of radiation. Rem is used to define limits of exposure for people who work in nuclear power plants. Rem is often divided in millirems and assigned a length of time, such as millirems per hour. Curie/ becquerel is the unit of radioactivity.","pyqMatches":[{"year":"2016","no":1740,"q":"Roentgen is the unit of: March 2010","o":["Radioactivity","Radiation exposure","Absorbed dose","None of the above"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8727, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 30, '{"id":8727,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":30,"q":"Adder head appearance is seen in: March 2011","o":["Posterior urethral valve","Uretrocoele","Bladder tumour","Horse shoe kidney"],"a":1,"e":"Ans. B: Ureterocoele The ''adder head'' on excretory urography is typical of ureterocoele Ureterocele is a cystic dilatation of the distal ureter. Cobra head or Adder head appearance is diagnostic of ureterocele. Spider leg appearance in polycystic kidney. Ref: Bailey & Love, 25th Edition, Page 1290","pyqMatches":[{"year":"2014","no":2015,"q":"Adder head appearance is seen in: March 2011","o":["Posterior urethral valve","Uretrocoele","Bladder tumour","Horse shoe kidney"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8728, 'Radiology', 'Musculoskeletal Radiology', 'Easy', 'Radiology', 31, '{"id":8728,"subject":"Radiology","chapter":"Musculoskeletal Radiology","difficulty":"Easy","source":"Radiology","sourceNo":31,"q":"White line of Frenkel is seen in: September 2008","o":["Osteoporosis","Osteomalacia","Scurvy","Beri-Beri"],"a":2,"e":"Ans. C: Scurvy Clinical symptoms and signs of infantile scurvy, in order of frequency are irritability, tenderness and weakness of lower extremities, a scorbutic rosary of the legs, bleeding of the gums (usually where teeth have erupted), and fever. Radiographic findings of scurvy: Dense metaphyseal line-This is due to an intensification of the zone of preparatory calcification, resulting from matrix formation failing, is has been referred to as the white line of Frenkel, but is non-specific, as it is also seen in healing rickets, and lead or phosphorus poisoning. Ground glass osteoporosis: This appears at the end of the shaft with blurring or disappearance of trabecular markings. Halo ossification centre: Also called the Wimberger''s ring, it is the same effect that produces the white line of Frenkel, affecting the epiphyseal ossification center. Corner sign-Seen due to subepiphyseal infarction, or separation of the epiphysis from the metaphysis. Lateral spurs-These metaphyseal spurs project at right angles to the axis of the shaft, they may be seen due to mushrooming of epiphysis on the metaphysis, or may represent earliest calcification of periosteum elevated by a subperiosteal hemorrhage. Subperiosteal hematomas-These occur at the end of long bones, seen after about 2 weeks of onset of clinical symptoms; it is not the periosteal hemorrhage that calcifies, but the elevated periosteum, secondary to resumption of bone formation. Metaphyseal fractures-Subperiosteal comminuted fractures at the end of long bones, extending only partially through the width of the bone. Atrophy scurvy line-A radiolucent zone on the shaft side of Frenkel''s white line, it has been referred to as the Trummerfeld Zone.","pyqMatches":[{"year":"2012","no":1436,"q":"White line of Frenkel is seen in: September 2008","o":["Osteoporosis","Osteomalacia","Scurvy","Beri-Beri"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8729, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 32, '{"id":8729,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":32,"q":"SI unit of radioactivity is: March 2013 (c, f)","o":["Rem","Rad","Becuerel","Curie e) None"],"a":2,"e":"Ans. C i.e. Becquerel Old unit of radioactivity is Curie and new unit (SI) is Becquerel.","pyqMatches":[{"year":"2016","no":1741,"q":"SI unit of radioactivity is: March 2013 (c, f)","o":["Rem","Rad","Becuerel","Curie e) None"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8730, 'Radiology', 'Musculoskeletal Radiology', 'Easy', 'Radiology', 33, '{"id":8730,"subject":"Radiology","chapter":"Musculoskeletal Radiology","difficulty":"Easy","source":"Radiology","sourceNo":33,"q":"CSF on MRI appears:","o":["Hyperintense on T1 weighed image and hypointense on T2 weighed image","Hypointense on T1 weighed image and hyperintense on T2 weighed image","Hyperintense on T1 and T2 weighed images","Hypointense on T1 and T2 weighed images"],"a":1,"e":"Ans. Hypointense on T1 weighed image and hyperintense on T2 weighed image Fluid- Edema, Urine, Bile, CSF- T1 weighted signal low & T2 weighted signal high","pyqMatches":[{"year":"2016","no":1729,"q":"CSF on MRI appears:","o":["Hyperintense on T1 weighed image and hypointense on T2 weighed image","Hypointense on T1 weighed image and hyperintense on T2 weighed image","Hyperintense on T1 and T2 weighed images","Hypointense on T1 and T2 weighed images"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8731, 'Radiology', 'Imaging Principles & Contrast', 'Hard', 'Radiology', 34, '{"id":8731,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Hard","source":"Radiology","sourceNo":34,"q":"Best imaging modality in patients with breast implants is:","o":["MRI scan","CT scan","Mammography","Radionuclide scan"],"a":0,"e":"Ans. MRI scan It is the best imaging modality for the breasts of women with implants. MRI can be usefirl to distinguish scar from recurrence in women who have had previous breast conservation therapy for cancer","pyqMatches":[{"year":"2014","no":2051,"q":"Best imaging modality in patients with breast implants is:","o":["MRI scan","CT scan","Mammography","Radionuclide scan"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8732, 'Radiology', 'Chest Radiology', 'Moderate', 'Radiology', 35, '{"id":8732,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Moderate","source":"Radiology","sourceNo":35,"q":"Well defined rounded opacity is the lung with cause irregular calcification is a feature of:","o":["Hamartoma","Hydatid cyst","Amoebic abscess","Ca lung"],"a":0,"e":"Ans. Hamartoma Irregular central calcification (Popcorn calcification) is characteristic of hamartoma.","pyqMatches":[{"year":"2014","no":2055,"q":"Well defined rounded opacity is the lung with cause irregular calcification is a feature of:","o":["Hamartoma","Hydatid cyst","Amoebic abscess","Ca lung"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8733, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 36, '{"id":8733,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":36,"q":"Commonly used type of radiation in radiotherapy is:","o":["Alpha rays","Beta rays","Gamma rays","X-rays"],"a":2,"e":"Ans. Gamma rays Radioiodine generates both beta and gamma rays but predominantly beta rays.","pyqMatches":[{"year":"2016","no":1753,"q":"Commonly used type of radiation in radiotherapy is:","o":["Alpha rays","Beta rays","Gamma rays","X-rays"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8734, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 37, '{"id":8734,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":37,"q":"Radiation protection shields are made up of:","o":["Copper","Silver","Lead","Tin"],"a":2,"e":"Ans. Lead","pyqMatches":[{"year":"2016","no":1726,"q":"Radiation protection shields are made up of:","o":["Copper","Silver","Lead","Tin"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8735, 'Radiology', 'Chest Radiology', 'Easy', 'Radiology', 38, '{"id":8735,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Easy","source":"Radiology","sourceNo":38,"q":"The photosensitive material used in X- rays films consist of:","o":["Cellulose","Silver bromide","Zinc sulphide","Cadmium tungstate"],"a":1,"e":"Ans. Silver bromide After the image has been developed, the resultant image is then fixed by a fixer (Hypo-sodium thiosulphate) which removes unused silver halide, which would make the film appear milky or cloudy. X- ray film should be developed in dark room, otherwise light will spoil the film (x-ray film has photosensitive silver bromide). Blue and green light are most sensitive whereas yellow and red light are least.","pyqMatches":[{"year":"2016","no":1754,"q":"The photosensitive material used in X- rays films consist of:","o":["Cellulose","Silver bromide","Zinc sulphide","Cadmium tungstate"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8736, 'Radiology', 'Imaging Principles & Contrast', 'Moderate', 'Radiology', 39, '{"id":8736,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Moderate","source":"Radiology","sourceNo":39,"q":"Among the causes of rib notching are:","o":["Coarctation of aorta","Congenital interruption of aorta","Chronic superior venacava obstruction","All of the above"],"a":3,"e":"Ans. All of the above","pyqMatches":[{"year":"2013","no":1763,"q":"Among the causes of rib notching are:","o":["Coarctation of aorta","Congenital interruption of aorta","Chronic superior venacava obstruction","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8737, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 40, '{"id":8737,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":40,"q":"Thickness of lead apron to prevent radiation:","o":["1 mm","3 mm","0.5 mm","7 mm"],"a":2,"e":"Ans. C. 0.5 mm \"It is recommended that for general purpose radiography the minimal thickness of lead equivalent in the protective apparel should be 0.5mm.\" - Textbook of Radiology Physics p. 39 Lead apron of 0.5mm thickness reduce intensity of scattered X-rays by over 90%.","pyqMatches":[{"year":"2012","no":865,"q":"Thickness of lead apron to prevent radiation:","o":["1 mm","3 mm","0.5 mm","7 mm"],"a":2,"source":"NEET_2012_Paper.pdf"},{"year":"2016","no":1725,"q":"Thickness of lead apron to prevent radiation:","o":["1 mm","3 mm","0.5 mm","7 mm"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2012","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8738, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 41, '{"id":8738,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":41,"q":"Hilar dance on fluoroscopy is seen in:","o":["ASD","TOF","VSD","TGV"],"a":0,"e":"Ans. ASD Fluoroscopic examination done in a patient with ASD shows hilar dance sign due to pulsation of central pulmonary artery. CXR features of ASD: There is no enlargement of left atrium except in few cases of Lutembacher syndrome. The heart in ASD is sometimes displaced to the left. The ascending aorta and its arch tends to appear smaller than normal, probably due to rotation of the ascending aorta by enlarged right atrium and right ventricle causing sagittal alignment of the aortic arch. Kerley B lines in a patient with ASD should always suggest an associated mitral valve abnormality(Lutembacher syndrome). The Goose neck deformity is seen in ASD on cardioangiography. Ref: Clinical Diagnosis of Congenital Heart Disease By M. Satpathy page 78, Radiodiagnosis, Nuclear Medicine, Radiotherapy and Radiation Oncology By Bipin Valchandji Daga page 139.","pyqMatches":[{"year":"2013","no":1442,"q":"Hilar dance on fluoroscopy is seen in:","o":["ASD","TOF","VSD","TGV"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8739, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 42, '{"id":8739,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":42,"q":"Half life of Technetium 99 is:","o":["2 hours","6 hours","12 hours","24 hours"],"a":1,"e":"Ans. 6 hours Tc-99 - Technitium - 6 hours Half life (tin) of radium (Ra226)is 1602-1626 years (longest)Q; Cesium (137Cs) is 30 yearsQ; Cobalt (60Co) is 5.2 yearsQ; iridium (1921r)is 74.5 daysQ; Iodine (P31)is 8 daysQ; 1123 is 13 hoursQ; technitium (Tc99) is 6 hoursQ; and 1132 is 2.3 hoursQ.","pyqMatches":[{"year":"2016","no":1747,"q":"Half life of Technetium 99 is:","o":["2 hours","6 hours","12 hours","24 hours"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8740, 'Radiology', 'Chest Radiology', 'Easy', 'Radiology', 43, '{"id":8740,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Easy","source":"Radiology","sourceNo":43,"q":"Popcorn calcification is seen in:","o":["Pulmonary hamartoma","Fungal infection","Metastasis","Tuberculosis"],"a":0,"e":"Ans. Pulmonary hamartoma Popcorn calcification o Popcorn calcification is a cluster of sharply defined, irregularly lobulated, calcification, usually in a pulmonary nodule. o Popcorn calcification is characteristic of hamartoma on chest X-ray examination. o It may also be seen in mediastinal lymph nodes of acute histoplasmosis. Egg-shell calcification o Egg-shell calcification means peripheral rim calcification of lymph nodes: o It is seen in: N Silicosis (most common cause) (vi) Histoplasmosis (vii) Tuberculosis (ii) Coal worker pneumoconiosis (v) Sarcoidosis (viii) Coccidiodomycosis (iii) Lymphoma following radiotherapy (vi) Progressive massive fibrosis","pyqMatches":[{"year":"2012","no":1438,"q":"Popcorn calcification is seen in:","o":["Pulmonary hamartoma","Fungal infection","Metastasis","Tuberculosis"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8741, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 44, '{"id":8741,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":44,"q":"The principle used in radiotherapy is:","o":["Cytoplasmic coagulation","Ionising the molecules","DNA damage","Low dose causes tissue necrosis"],"a":2,"e":"Ans. DNA damage Radiotherapy is the treatment of cancer with ionizing radiation. It works by damaging the DNA within the tumor cells, making them unable to divide and grow. The goal of radiation therapy is to maximize the dose to tumor cells while minimizing exposure to normal, healthy cells. Ref: Emami B et al. 1991","pyqMatches":[{"year":"2014","no":2014,"q":"The principle used in radiotherapy is:","o":["Cytoplasmic coagulation","Ionising the molecules","DNA damage","Low dose causes tissue necrosis"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8742, 'Radiology', 'Ultrasound & Doppler', 'Hard', 'Radiology', 45, '{"id":8742,"subject":"Radiology","chapter":"Ultrasound & Doppler","difficulty":"Hard","source":"Radiology","sourceNo":45,"q":"In a patient with renal cell carcinoma with a thrombus in IVC renal vein, which is the best investigation for diagnosis?","o":["CT scan","Angiography","Colour doppler imaging","IVP"],"a":0,"e":"Ans. CT scan Investigation of choice in RCC-CT scan.","pyqMatches":[{"year":"2015","no":1301,"q":"In a patient with renal cell carcinoma with a thrombus in IVC renal vein, which is the best investigation for diagnosis?","o":["CT scan","Angiography","Colour doppler imaging","IVP"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8743, 'Radiology', 'Chest Radiology', 'Easy', 'Radiology', 46, '{"id":8743,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Easy","source":"Radiology","sourceNo":46,"q":"The X-ray view for supra orbital fissure is:","o":["Towne''s","Caldwell","AP","nasal"],"a":1,"e":"Ans. Caldwell Superior orbital fissure can also be seen on water''s view, but best is caldwell view. \"The superior orbital fissure can easily indentified and normally has a slightly concave lateral appearacne\" - Text book of oral radiology","pyqMatches":[{"year":"2013","no":1790,"q":"The X-ray view for supra orbital fissure is:","o":["Towne''s","Caldwell","AP","nasal"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8744, 'Radiology', 'Ultrasound & Doppler', 'Easy', 'Radiology', 47, '{"id":8744,"subject":"Radiology","chapter":"Ultrasound & Doppler","difficulty":"Easy","source":"Radiology","sourceNo":47,"q":"Which of the following techniques uses piezoelectric crystals?","o":["Ultrasonography","NMR imaging","X-ray diffraction","Xeroradiography"],"a":0,"e":"Ans. Ultrasonography Ultrasonography is based on piezoelectric effect. MRI is based on gyeromagnetic property of proton (IP).","pyqMatches":[{"year":"2012","no":1419,"q":"Which of the following techniques uses piezoelectric crystals?","o":["Ultrasonography","NMR imaging","X-ray diffraction","Xeroradiography"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8745, 'Radiology', 'Chest Radiology', 'Easy', 'Radiology', 48, '{"id":8745,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Easy","source":"Radiology","sourceNo":48,"q":"\"String of beads\" appearance on horizontal abdominal view X-ray is suggestive of:","o":["Intussusception","Sigmoid volvulus","Small bowel obstruction","Large bowel obstruction"],"a":2,"e":"Ans. Small bowel obstruction String of beads sign is virtually diagnostic of small bowel obstruction","pyqMatches":[{"year":"2013","no":1774,"q":"\"String of beads\" appearance on horizontal abdominal view X-ray is suggestive of:","o":["Intussusception","Sigmoid volvulus","Small bowel obstruction","Large bowel obstruction"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8746, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 49, '{"id":8746,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":49,"q":"Puff of smoke appearance on cerebral angiography is seen in:","o":["ACA aneurysm","Cavernous sinus thrombosis","Moyamoya disease","Vein of Galen malformation"],"a":2,"e":"Ans. c. Moyamoya disease Moyamoya disease is an idiopathic, non inflammatory, non atherosclerotic progressive vasculo-occlusive disease involving the circle of Willis, typically the supraclinoid internal carotid arteries. Small abnormal net-like vessels proliferate giving the characteristic \"puff of smoke\" appearance on direct angiography. CTA and MRA is not always able to demonstrate this appearance on account of lower flow and spatial resolution.","pyqMatches":[{"year":"2015","no":1429,"q":"Puff of smoke appearance on cerebral angiography is seen in:","o":["ACA aneurysm","Cavernous sinus thrombosis","Moyamoya disease","Vein of Galen malformation"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8747, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 50, '{"id":8747,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":50,"q":"Which of the following is water soluble contrast?","o":["Barium","Iodine","Bromium","Calcium"],"a":1,"e":"Answer-B. Iodine Radiocontrast agents are typically iodine, barium-sulphate or gadolinium based compounds.","pyqMatches":[{"year":"2019","no":233,"q":"Which of the following is water soluble contrast?","o":["Barium","Iodine","Bromium","Calcium"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8748, 'Radiology', 'Musculoskeletal Radiology', 'Easy', 'Radiology', 51, '{"id":8748,"subject":"Radiology","chapter":"Musculoskeletal Radiology","difficulty":"Easy","source":"Radiology","sourceNo":51,"q":"Solitary lytic lesions seen in","o":["Atherosclerosis","Multiple myeloma","Mitral stenosis","Osteoblast"],"a":1,"e":"Answer- B. Multiple myeloma F: fibrous dysplasia (FD) or fibrous cortical defect (FCD) O: osteoblastoma G: giant cell tumor (GCT) M: metastasis(es)/myeloma A: aneurysmal bone cyst (ABC) C: chondroblastoma or chondromyxoid fibroma H: hyperparathyroidism (brown tumor) I: infection (osteomyelitis) N: non-ossifying fibroma (NOF) E: enchondroma or eosinophilic granuloma (EG) S: simple (unicameral) bone cyst","pyqMatches":[{"year":"2019","no":234,"q":"Solitary lytic lesions seen in","o":["Atherosclerosis","Multiple myeloma","Mitral stenosis","Osteoblast"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8749, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 52, '{"id":8749,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":52,"q":"Confusion assessment scale used for which of the following?","o":["Schizophrenia","Delirium","Dementia","Depression"],"a":1,"e":"Ans:B. Delirium Confusion Assessment Method (CAM), a widely-used instrument and diagnostic algorithm for identification of delirium. The CAM instrument assesses the presence, severity, and fluctuation of 9 delirium features: Acute onset Inattention Disorganized thinking Altered level of consciousness Disorientation Memory impairment Perceptual disturbances Psychomotor agitation or retardation Altered sleep-wake cycle. The CAM diagnostic algorithm is based on four cardinal features of delirium: Acute onset and fluctuating course Inattention Disorganized thinking Altered level of consciousness.","pyqMatches":[{"year":"2019","no":236,"q":"Confusion assessment scale used for which of the following?","o":["Schizophrenia","Delirium","Dementia","Depression"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8750, 'Radiology', 'Neuroradiology', 'Easy', 'Radiology', 53, '{"id":8750,"subject":"Radiology","chapter":"Neuroradiology","difficulty":"Easy","source":"Radiology","sourceNo":53,"q":"Hummingbird sign in brain MRI is seen in ?","o":["Multiple sclerosis","Progressive supranuclear palsy","Parkinson''s disease","Alzheimer disease"],"a":1,"e":"Ans. is ''b'' i.e., Progressive supranuclear palsy [Ref Clinical neurology - 113] Hummingbird sign on brain MRI is a radiological sign of progressive supranuclear palsy.","pyqMatches":[{"year":"2014","no":2053,"q":"Hummingbird sign in brain MRI is seen in ?","o":["Multiple sclerosis","Progressive supranuclear palsy","Parkinson''s disease","Alzheimer disease"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8751, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 54, '{"id":8751,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":54,"q":"Tigriod pattern on MRI is seen in -","o":["Wilson''s disease","Metachromatic leukodystrophy","Parkinsonism","GB syndrome"],"a":1,"e":"Answer- B. Metachromatic leukodystrophy It is characteristically seen in - Metachromatic leukodystrophy Pelizaeus-Merzbacher disease Autosomal recessive spastic ataxia of charlevoix.","pyqMatches":[{"year":"2015","no":1673,"q":"Tigriod pattern on MRI is seen in","o":["Wilson''s disease","Metachromatic leukodystrophy","Parkinsonism","GB syndrome"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8752, 'Radiology', 'Imaging Principles & Contrast', 'Moderate', 'Radiology', 55, '{"id":8752,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Moderate","source":"Radiology","sourceNo":55,"q":"Which of the following is not a contraindication of MRI","o":["Cardiac pacemaker","Cochlear implant","Ryle''s tube","Metallic splinter in eye"],"a":2,"e":"Answer- C. Ryle''s tube Contraindications for MRI A) Absolute Electronically, magnetically, and mechanically activated implants. Ferromagnetic or electronically operated active devices like automatic cardioverter defibrillators. Cardiac pacemaker Metallic splinters in the eye. Ferromagnetic haemostatic clips in the CNS. B) Relative contraindications Cochlear implants Prosthetic heart valves Other pacemakers, e.g., for Carotid sinus Haemostatic clips Insulin pumps and nerve stimulators Non-ferromagentic stapedial implants Lead wires or similar wires Women with a first - trimester pregnancy","pyqMatches":[{"year":"2015","no":1639,"q":"Which of the following is not a contraindication of MRI","o":["Cardiac pacemaker","Cochlear implant","Ryle''s tube","Metallic splinter in eye"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8753, 'Radiology', 'Imaging Principles & Contrast', 'Hard', 'Radiology', 56, '{"id":8753,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Hard","source":"Radiology","sourceNo":56,"q":"All are done to minimize radiation, exposure to the patient under fluroscopy, except","o":["Decrease in field of view","Increasing the Kv of radiation","Decreasing fluroscopic time","Using low dose of radiation"],"a":0,"e":"Answer- A. Decrease in field of view Decreasing the field of view during fluroscopy increase the radiation dose rate :-","pyqMatches":[{"year":"2015","no":1640,"q":"All are done to minimize radiation, exposure to the patient under fluroscopy, except","o":["Decrease in field of view","Increasing the Kv of radiation","Decreasing fluroscopic time","Using low dose of radiation"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8754, 'Radiology', 'Ultrasound & Doppler', 'Easy', 'Radiology', 57, '{"id":8754,"subject":"Radiology","chapter":"Ultrasound & Doppler","difficulty":"Easy","source":"Radiology","sourceNo":57,"q":"Investigation of choice for soft tissue sarcoma is -","o":["CT","MRI","Ultrasound","X-ray"],"a":1,"e":"Answer- B. MRI \"Any patient with a suspected STS should be referred to a diagnostic centre for triple assessment with clinical history, imaging and biopsy. Whilst the preferred method of imaging is MRI, other options including computerized tomography (CT) or ultrasound may be appropriate depending on local expertise.\"","pyqMatches":[{"year":"2015","no":1672,"q":"Investigation of choice for soft tissue sarcoma is","o":["CT","MRI","Ultrasound","X-ray"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8755, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 58, '{"id":8755,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":58,"q":"Amount of radiation exposure in 1 CT- scan of chest is","o":["1 mSv","3 mSv","5 mSv","7 mSv"],"a":3,"e":"Answer- D. 7 mSv CT chest causes radiation exposure of 7mSv. CT abdomen-pelvis causes radiation exposure of 10 mSv. CT head causes radiation exposure of 2 mSv.","pyqMatches":[{"year":"2015","no":1641,"q":"Amount of radiation exposure in 1 CT- scan of chest is","o":["1 mSv","3 mSv","5 mSv","7 mSv"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8756, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 59, '{"id":8756,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":59,"q":"Which of the following is a late severe adverse effect of radiation therapy","o":["Nausea","Erythema","Anemia","Osteoradionecrosis"],"a":3,"e":"Answer- D. Osteoradionecrosis Osteoradionecrosis is a late complication of radiation while nausea, erythema and anemia are early complications.","pyqMatches":[{"year":"2015","no":1642,"q":"Which of the following is a late severe adverse effect of radiation therapy","o":["Nausea","Erythema","Anemia","Osteoradionecrosis"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8757, 'Radiology', 'Musculoskeletal Radiology', 'Easy', 'Radiology', 60, '{"id":8757,"subject":"Radiology","chapter":"Musculoskeletal Radiology","difficulty":"Easy","source":"Radiology","sourceNo":60,"q":"Skyline view X-ray is useful in diagnosing -","o":["Patellofemoral problem","Radioulnars problem","Tibiofibular problem","Skull fracture"],"a":0,"e":"Answer- A. Patellofemoral problem A ''Skyline'' or ''Sunrise'' or ''sunset'' or ''axial'' or ''tangential'' or ''mountain view'' gives most information about patellofemoral joint.","pyqMatches":[{"year":"2015","no":1670,"q":"Skyline view X-ray is useful in diagnosing","o":["Patellofemoral problem","Radioulnars problem","Tibiofibular problem","Skull fracture"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8758, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 61, '{"id":8758,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":61,"q":"Substance used for PET scan is","o":["18FPCT","Gadolinium","Gastrogarfin","Iodine"],"a":0,"e":"Answer- A. 18FPCT Fluorine-18-labeled 2Ali-carbomethoxy-3AY-(4-chloropheny1)-8-(-3- fluoropropyl) nortropane (FPCT) has been synthesized as a new dopamine transporter imaging agent. Other substances used for PET scan are :","pyqMatches":[{"year":"2015","no":1643,"q":"Substance used for PET scan is","o":["18FPCT","Gadolinium","Gastrogarfin","Iodine"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8759, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 62, '{"id":8759,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":62,"q":"Sausage finger appearance is seen in -","o":["Psoriatic arthritis","Rickets","Hyperthyroidism","Addison''s disease"],"a":0,"e":"Answer- A. Psoriatic arthritis The common causes of sausage digit are : Psoriatic arthropathy. Ankylosing spondylitis Tuberculosis Osteomyelitis. Sickle cell disease Leprosy","pyqMatches":[{"year":"2015","no":1669,"q":"Sausage finger appearance is seen in","o":["Psoriatic arthritis","Rickets","Hyperthyroidism","Addison''s disease"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8760, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 63, '{"id":8760,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":63,"q":"Which common tracer in PET is usually administered in the form of a glucose sugar","o":["Oxygen 15","Fluorine 18","Saccharide - 12","Aluminum - 12"],"a":1,"e":"Answer- B. Fluorine 18 Fluorine-18 is used in the form of FDG in PET scan. The most common tracer has a complicated name but is mostly known as FDG (which stands for 2-[18F]fluoro-2-deoxy-D-glucose). The biologically active molecule most commonly used for PET is 2- deoxy-2-18F-fluoro-β-D-glucose (18F-FDG), an analogue of glucose, for early detection of tumors.","pyqMatches":[{"year":"2015","no":1644,"q":"Which common tracer in PET is usually administered in the form of a glucose sugar","o":["Oxygen 15","Fluorine 18","Saccharide - 12","Aluminum - 12"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8761, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 64, '{"id":8761,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":64,"q":"Investigation of choice for acute subarachnoid hemorrhage is -","o":["MRI","CT scan","Enhance MRI","Angiography"],"a":1,"e":"Answer- B. CT scan Investigation of choice for acute SAH - CT scan Investigation of choice for chronic SAH - MRI","pyqMatches":[{"year":"2015","no":1668,"q":"Investigation of choice for acute subarachnoid hemorrhage is","o":["MRI","CT scan","Enhance MRI","Angiography"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8762, 'Radiology', 'Abdominal Radiology', 'Easy', 'Radiology', 65, '{"id":8762,"subject":"Radiology","chapter":"Abdominal Radiology","difficulty":"Easy","source":"Radiology","sourceNo":65,"q":"Intraoperative radiotherapy is used in","o":["Gastric cancer","Colon carcinoma","Pancreatic carcinoma","All of the above"],"a":3,"e":"Answer- D. All of the above Intraoperative radiotherapy can be used In -","pyqMatches":[{"year":"2015","no":1645,"q":"Intraoperative radiotherapy is used in","o":["Gastric cancer","Colon carcinoma","Pancreatic carcinoma","All of the above"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8763, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 66, '{"id":8763,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":66,"q":"Precisely directed high dose radiation is used in","o":["IMRT","EBRT","Stereotectic radiosurgery","None of the above"],"a":0,"e":"Answer- A. IMRT Intensity modulated radiation therapy (IMRT) is an advanced mode of high precision radiotherapy that utilizes computer controlled X-ray accelerators to deliver precise radiation doses to a malignant tumour or specific areas within the tumour.","pyqMatches":[{"year":"2015","no":1646,"q":"Precisely directed high dose radiation is used in","o":["IMRT","EBRT","Stereotectic radiosurgery","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8764, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 67, '{"id":8764,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":67,"q":"Epidural hematoma on CT scan shows -","o":["Crescent shaped hyperdense lesion","Biconvex hyperdense lesion","Biconcave hyperdense lesion","Crescent shaped hypodense lesion"],"a":1,"e":"Answer- B. Biconvex hyperdense lesion Acute extradural (epidural) hematoma is biconvex hyperdense or mixed density lesion. Extradural (epidural) hematoma appearance radiolgically :- Biconvex (lens shaped or lenticular) In Acute cases 4 Hyperdense (2/3) or mixed density (1/3). In chronic cases 4 Hypodense","pyqMatches":[{"year":"2015","no":1667,"q":"Epidural hematoma on CT scan shows","o":["Crescent shaped hyperdense lesion","Biconvex hyperdense lesion","Biconcave hyperdense lesion","Crescent shaped hypodense lesion"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8765, 'Radiology', 'Miscellaneous', 'Moderate', 'Radiology', 68, '{"id":8765,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Moderate","source":"Radiology","sourceNo":68,"q":"Not used for internal radiotherapy","o":["Iodine-125","Iodine-131","Cobalt-60","Iridium-192"],"a":1,"e":"Answer- B. Iodine-131 lsotpes used for internal radiotherapy (brachy therapy) A) Interstitial brachytherapy Permanent implants of interstitial brachytherapy :- Cesium - 131, Yttrium, Gold - 198 (Au - 198), 125I, Radon - 222 (Rn - 222), Pallidum - 103 (Pd - 103). Temporary implants of Interstitial brachytherapy :- Iridium - 192 (Ir - 192), Cesium - 137 (Cs - 137), Cobalt - 60 (Co -60), Californium, Radium - 226 (Ra - 226), Tantolum.","pyqMatches":[{"year":"2015","no":1648,"q":"Not used for internal radiotherapy","o":["Iodine-125","Iodine-131","Cobalt-60","Iridium-192"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8766, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 69, '{"id":8766,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":69,"q":"Radioiodine generates which type of radiation","o":["X-rays","Alpha and beta rays","Beta and gamma rays","Alpha and beta rays"],"a":2,"e":"Answer- C. Beta and gamma rays Radioiodine generates both beta and gamma rays but predominantly beta rays.","pyqMatches":[{"year":"2015","no":1649,"q":"Radioiodine generates which type of radiation","o":["X-rays","Alpha and beta rays","Beta and gamma rays","Alpha and beta rays"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8767, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 70, '{"id":8767,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":70,"q":"Radioactive iodine is administered through which route","o":["Intravenous","Subcutaneous","Oral","All of the above"],"a":3,"e":"Answer- D. All of the above Radioactive iodine is administered orally as well as parentrally i.e. IV, SC & IM.","pyqMatches":[{"year":"2015","no":1650,"q":"Radioactive iodine is administered through which route","o":["Intravenous","Subcutaneous","Oral","All of the above"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8768, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 71, '{"id":8768,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":71,"q":"Investigation of choice for acute intracerebral hemorrhage is -","o":["NCCT","MRI","PET scan","None of the above"],"a":0,"e":"Answer- A. NCCT \"NCCT remains the main stay of emergency imaging of stroke in order to exclude intracranial hemorrhage\". \"In investigation of stroke with delayed presentation gradient-echo MRI is the investigation of choice for exclusion of old hemorrhage\".","pyqMatches":[{"year":"2015","no":1666,"q":"Investigation of choice for acute intracerebral hemorrhage is","o":["NCCT","MRI","PET scan","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8769, 'Radiology', 'Chest Radiology', 'Easy', 'Radiology', 72, '{"id":8769,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Easy","source":"Radiology","sourceNo":72,"q":"\"Tree in bud appearance\" on CT is seen in","o":["Pulmonary tuberculosis","Silicosis","Pulmonary hydatid cyst","Small cell carcinoma"],"a":0,"e":"Answer- A. Pulmonary tuberculosis It is usually visible on standard CT, however, it is best seen on HRCT chest. Typically the centrilobular nodules are 2-4 mm in diameter and peripheral, within 5 mm of the pleural surface. The connection to opacified or thickened branching structures extends proximally (representing the dilated and opacified bronchioles or inflamed arterioles) Associated CT findings of bronchiolitis are seen in about 70% of patients with bronchiectasis. Small centrilobular nodular and linear branching opacities (tree-in-bud sign) express inflammatory and infectious bronchiolitis Pathogenesis- The tree-in-bud sign occurs as a result of a number of processes, although often they co- exist in the same condition: a. bronchioles filled with pus or inflammatory exudate e.g. pulmonary tuberculosis, aspiration bronchopneumonia b. bronchiolitis: thickening of bronchiolar walls and bronchovascular bundle e.g. cytomegalovirus pneumonitis, obliterative bronchiolitis c. bronchiectasis with mucus plugging e.g. cystic fibrosis d. tumor emboli to centrilobular arteries (or carcinomatous endarteritis) e.g. breast cancer, stomach cancer e. bronchovascular interstitial infiltration e.g. sarcoidosis, lymphoma, leukemia","pyqMatches":[{"year":"2015","no":1651,"q":"\"Tree in bud appearance\" on CT is seen in","o":["Pulmonary tuberculosis","Silicosis","Pulmonary hydatid cyst","Small cell carcinoma"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8770, 'Radiology', 'Musculoskeletal Radiology', 'Easy', 'Radiology', 73, '{"id":8770,"subject":"Radiology","chapter":"Musculoskeletal Radiology","difficulty":"Easy","source":"Radiology","sourceNo":73,"q":"Investigation of choice to evaluate intracranial hemorrhage of less than 48 hours is -","o":["CT scan","MRI","PET","SPECT"],"a":0,"e":"Answer- A. CT scan Primary procedure of choice for evaluating intracranial complications of acute head injury 4 CT scan. Best modality for assessing fractures of the skull base, calvarium and facial bone 4 CT scan. Investigation of choice for demyelinating disorders 4 MRI.","pyqMatches":[{"year":"2015","no":1665,"q":"Investigation of choice to evaluate intracranial hemorrhage of less than 48 hours is","o":["CT scan","MRI","PET","SPECT"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8771, 'Radiology', 'Chest Radiology', 'Easy', 'Radiology', 74, '{"id":8771,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Easy","source":"Radiology","sourceNo":74,"q":"Investigation of choice for lung abscess is","o":["Chest X-ray","CECT scan","MRI","Ultrasound"],"a":1,"e":"Answer- B. CECT scan Contrast enhanced CT in usually considered to be investigation of choice for lung abscess, showing a cavity with thick walls and central mobile fluid. It helps to differentiate abscess from empyma, necrotizing pneumonia, sequestration, pneumatocele or underlying congenital abnormalities such as bronchogenic cyst.","pyqMatches":[{"year":"2015","no":1652,"q":"Investigation of choice for lung abscess is","o":["Chest X-ray","CECT scan","MRI","Ultrasound"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8772, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 75, '{"id":8772,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":75,"q":"CT of gastric Volvulus shows -","o":["Shortened twisted stomach","Enlarged twisted stomach","Normal twisted stomach","None of the above"],"a":1,"e":"Answer- B. Enlarged twisted stomach CT scan of gastric Volvulus shows enlarged twisted stomach in thorax with one or more sites of torsion. It is useful in showing the sites of ischemia.","pyqMatches":[{"year":"2015","no":1664,"q":"CT of gastric Volvulus shows","o":["Shortened twisted stomach","Enlarged twisted stomach","Normal twisted stomach","None of the above"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8773, 'Radiology', 'Chest Radiology', 'Moderate', 'Radiology', 76, '{"id":8773,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Moderate","source":"Radiology","sourceNo":76,"q":"On CT chest ''halo sign'' is noted in","o":["Pulmonary hydatid cyst","Invasive pulmonary aspergilossis","Round pneumonia","Bronchiectasis"],"a":1,"e":"Answer- B. Invasive pulmonary aspergilossis The halo sign (HS) in chest imaging is a feature seen on lung window settings (typically HRCT), ground glass opacity surrounding a pulmonary nodule or mass and represents hemorrhage. It is typically seen in angioinvasive aspergillosis.","pyqMatches":[{"year":"2015","no":1653,"q":"On CT chest ''halo sign'' is noted in","o":["Pulmonary hydatid cyst","Invasive pulmonary aspergilossis","Round pneumonia","Bronchiectasis"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8774, 'Radiology', 'Chest Radiology', 'Hard', 'Radiology', 77, '{"id":8774,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Hard","source":"Radiology","sourceNo":77,"q":"A 50 year old male presents with fever and malaise for 4 months& pain in the knees and ankles. Blood tests are normal apart from a raised ESR. Chest x-ray shows bilateral hilar adenopathy and pulmonary infiltrates most severe in the upper and mid zones. Mantoux test is negative. What is the most likely diagnosis","o":["Tuberculosis","Sarcoidosis","Asbestosis","Berylliosis"],"a":1,"e":"Answer- B. Sarcoidosis Sarcoidosis is the most likely diagnosis given the presentation with malaise, arthralgia and a chest x-ray showing bilateral hilar adenopathy. \"The characteristic radiological finding in patients with pulmonary sarcoidosis is bilateral hilar lymphadenopathy\"","pyqMatches":[{"year":"2015","no":1654,"q":"A 50 year old male presents with fever and malaise for 4 months& pain in the knees and ankles. Blood tests are normal apart from a raised ESR. Chest x-ray shows bilateral hilar adenopathy and pulmonary infiltrates most severe in the upper and mid zones. Mantoux test is negative. What is the most likely diagnosis","o":["Tuberculosis","Sarcoidosis","Asbestosis","Berylliosis"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8775, 'Radiology', 'Ultrasound & Doppler', 'Moderate', 'Radiology', 78, '{"id":8775,"subject":"Radiology","chapter":"Ultrasound & Doppler","difficulty":"Moderate","source":"Radiology","sourceNo":78,"q":"Ultrasonographic finding of autosomal recessive polycystic kidney disease [ARPKD] are all except","o":["Cysts more than 2 cm","Corticomedullary differentiation is eventually lost","Enlarged kidney","Oligohydramnios"],"a":0,"e":"Answer- A. Cysts more than 2 cm On antenatal ultrasound associated oligohydramnios may be identified Cysts Initially too small to resolve but with time may become discernible Unlike ADPKD the cysts rarely exceed 1-2 cm in diameter The kidneys appear enlarged and echogenic but usually retain a reniform shape Medullary pyramids","pyqMatches":[{"year":"2015","no":1662,"q":"Ultrasonographic finding of autosomal recessive polycystic kidney disease [ARPKD] are all except","o":["Cysts more than 2 cm","Corticomedullary differentiation is eventually lost","Enlarged kidney","Oligohydramnios"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8776, 'Radiology', 'Abdominal Radiology', 'Hard', 'Radiology', 79, '{"id":8776,"subject":"Radiology","chapter":"Abdominal Radiology","difficulty":"Hard","source":"Radiology","sourceNo":79,"q":"22-year-old women presents to the emergency department with a chief complaint of severe left upper quadrant [LUQ] pain after being punched by her husband. Her blood pressure is 110/76, her pulse is 80 bpm, and her respiration rate is 24 breaths per minute. The best means to establish a diagnosis is which of the following ?","o":["Four-quadrant tap of the abdomen","CT of the abdomen","Peritoneal lavage","Upper gastrointestinal [GI] series"],"a":1,"e":"Answer- B. CT of the abdomen Clinical picture of the patient in above question indicates that patient is hemodynamically stable. Therefore best mode of evaluation should be CT scan of abdomen to see the extent of injury. If the patients is hemodynamically stable and can be shifted - CT scan","pyqMatches":[{"year":"2015","no":1655,"q":"22-year-old women presents to the emergency department with a chief complaint of severe left upper quadrant [LUQ] pain after being punched by her husband. Her blood pressure is 110/76, her pulse is 80 bpm, and her respiration rate is 24 breaths per minute. The best means to establish a diagnosis is which of the following ?","o":["Four-quadrant tap of the abdomen","CT of the abdomen","Peritoneal lavage","Upper gastrointestinal [GI] series"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8777, 'Radiology', 'Chest Radiology', 'Hard', 'Radiology', 80, '{"id":8777,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Hard","source":"Radiology","sourceNo":80,"q":"A 35 year-old female presented to the emergency department with the sudden onset of severe epigastric pain. She had a history of heart burn and dyspeptic symptoms for past 10 years. On physical exam, she had a temperature of 101.4°F, a pulse of 118 and a blood pressure of 128/72. Abdomen was tender & rigid. Expected finding on X-ray will be","o":["Blood under diaphragm","Air under diaphragm","Hazy lung fields","Prominent markings"],"a":1,"e":"Answer- B. Air under diaphragm Above clinical picture is suggestive of perforated peptic ulcer, Which is the most common cause of pneumoperitoneum (air under diaphragm). Perforation results in pneumoperitoneum and the best view to see pneumoperitoneum is chest x-ray in erect position which detects air under the domes of diaphragm.","pyqMatches":[{"year":"2015","no":1656,"q":"A 35 year-old female presented to the emergency department with the sudden onset of severe epigastric pain. She had a history of heart burn and dyspeptic symptoms for past 10 years. On physical exam, she had a temperature of 101.4°F, a pulse of 118 and a blood pressure of 128/72. Abdomen was tender & rigid. Expected finding on X- ray will be","o":["Blood under diaphragm","Air under diaphragm","Hazy lung fields","Prominent markings"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8778, 'Radiology', 'Chest Radiology', 'Easy', 'Radiology', 81, '{"id":8778,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Easy","source":"Radiology","sourceNo":81,"q":"Following X-ray finding is associated with Chilaiditi syndrome -","o":["Pseudopneumoperitoneum","Pseudopneumothorax","Pneumothorax","Hydropneumothorax"],"a":0,"e":"Answer- A. Pseudopneumoperitoneum Chilaiditi syndrome is the anterior interposition of the colon (usually tranverse colon) to the liver reaching the under-surface of the right hemidiaphragm with associated upper abdominal pain. It is one ofthe causes ofpseudopneumoperitoneum","pyqMatches":[{"year":"2015","no":1660,"q":"Following X-ray finding is associated with Chilaiditi syndrome","o":["Pseudopneumoperitoneum","Pseudopneumothorax","Pneumothorax","Hydropneumothorax"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8779, 'Radiology', 'Chest Radiology', 'Hard', 'Radiology', 82, '{"id":8779,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Hard","source":"Radiology","sourceNo":82,"q":"A 50 year-old chronic alcoholic male patient, after a large binge of alcohol, presented to the emergency department in subconscious state. He vomited several times, few of them mixed with blood. He had a history of heart burn and dyspeptic symptoms for past few tears. On physical exam, he had a temperature of 102°F, a pulse of 110, respiratory rate of 20 per minute and a blood pressure of 90/60. On physical examination there was abdominal guarding and tenderness. A plane erect chest X-ray reveals air under diaphragm. Probable diagnosis is","o":["Perforated peptic ulcer","Acute MI","Dissected abdominal aorta","None of the above"],"a":0,"e":"Answer- A. Perforated peptic ulcer History of heart burn and dyspepsia, acute onset of bloody vomiting after binge alcohol, general and physical examination findings and air under diaphragm on chest X-ray, all these indicate towards the perforation of peptic ulcer perforation of peptic ulcer.","pyqMatches":[{"year":"2015","no":1657,"q":"A 50 year-old chronic alcoholic male patient, after a large binge of alcohol, presented to the emergency department in subconscious state. He vomited several times, few of them mixed with blood. He had a history of heart burn and dyspeptic symptoms for past few tears. On physical exam, he had a temperature of 102°F, a pulse of 110, respiratory rate of 20 per minute and a blood pressure of 90/60. On physical examination there was abdominal guarding and tenderness. A plane erect chest X-ray reveals air under diaphragm. Probable diagnosis is","o":["Perforated peptic ulcer","Acute MI","Dissected abdominal aorta","None of the above"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8780, 'Radiology', 'Neuroradiology', 'Easy', 'Radiology', 83, '{"id":8780,"subject":"Radiology","chapter":"Neuroradiology","difficulty":"Easy","source":"Radiology","sourceNo":83,"q":"Ring enhancing lesion on CT is a feature of","o":["Toxoplasmsis","Intracranial hemorrhage","Cysts","Hamartoma"],"a":0,"e":"Answer- A. Toxoplasmsis Ring enhancing brain lesions","pyqMatches":[{"year":"2015","no":1658,"q":"Ring enhancing lesion on CT is a feature of","o":["Toxoplasmsis","Intracranial hemorrhage","Cysts","Hamartoma"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8781, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 84, '{"id":8781,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":84,"q":"About lipoma, radiologically true is -","o":["Low attenuation on CT","Anechoic on US","Hypo-intense on T1 -MRI","Hypo-intense on T2-MRI"],"a":0,"e":"Answer- A. Low attenuation on CT Lipomas are benign fat tumors which show Variable echos on US Hyper-intense shadows on both T1 & T2 MRI Low attenuation on CT.","pyqMatches":[{"year":"2015","no":1659,"q":"About lipoma, radiologically true is","o":["Low attenuation on CT","Anechoic on US","Hypo-intense on T1 -MRI","Hypo-intense on T2-MRI"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8782, 'Radiology', 'Musculoskeletal Radiology', 'Moderate', 'Radiology', 85, '{"id":8782,"subject":"Radiology","chapter":"Musculoskeletal Radiology","difficulty":"Moderate","source":"Radiology","sourceNo":85,"q":"USG is done to visualize all except -","o":["Fluid","Bile","Blood flow","Bone"],"a":3,"e":"Answer- D. Bone USG is done to visualize soft tissues and fluids. But not for bone.","pyqMatches":[{"year":"2014","no":2004,"q":"USG is done to visualize all except","o":["Fluid","Bile","Blood flow","Bone"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8783, 'Radiology', 'Chest Radiology', 'Moderate', 'Radiology', 86, '{"id":8783,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Moderate","source":"Radiology","sourceNo":86,"q":"Regarding HRCT, all are true except -","o":["Means high reconstruction CT imaging","Has narrow beam collimation","Investigation of choice for interstitial lung disease","Has small field of vision"],"a":0,"e":"Answer- A. Means high reconstruction CT imaging Principles of HRCT (High resolution CT) are :","pyqMatches":[{"year":"2014","no":2005,"q":"Regarding HRCT, all are true except","o":["Means high reconstruction CT imaging","Has narrow beam collimation","Investigation of choice for interstitial lung disease","Has small field of vision"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8784, 'Radiology', 'Imaging Principles & Contrast', 'Moderate', 'Radiology', 87, '{"id":8784,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Moderate","source":"Radiology","sourceNo":87,"q":"All of the following are true about neutron contrast study except -","o":["Provides spatial resolution","Hydrogen and boron have high neutron cross section","Allows visualization of light elements inside heavy metallic objects","Is an example of destructive testing"],"a":3,"e":"Answer- D. Is an example of destructive testing Neutrons interact with matter in a way that is quite complementary to X-rays, and so neutron imaging and neutron radiography are important techniques for non-destructive testing, most suited for visualization of light elements in the interior of (heavy) metallic objects. Examples of high absorption cross- section materials include hydrogen and boron while iron has lower neutron cross-section.","pyqMatches":[{"year":"2014","no":2010,"q":"All of the following are true about neutron contrast study except","o":["Provides spatial resolution","Hydrogen and boron have high neutron cross section","Allows visualization of light elements inside heavy metallic objects","Is an example of destructive testing"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8785, 'Radiology', 'Chest Radiology', 'Easy', 'Radiology', 88, '{"id":8785,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Easy","source":"Radiology","sourceNo":88,"q":"In normal X-ray of shoulder which is superior most structure -","o":["Greater tubercle","Surgical neck of humerus","Coracoid process","Head of humerus"],"a":2,"e":"Answer- C. Coracoid process From superior to inferior (important structure on X-ray sholder) :- Clavicle : Acromian : Coracoid : Superior margin of humeral head : greater tubercle : anatomical neck : surgical neck.","pyqMatches":[{"year":"2014","no":2011,"q":"In normal X-ray of shoulder which is superior most structure","o":["Greater tubercle","Surgical neck of humerus","Coracoid process","Head of humerus"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8786, 'Radiology', 'Musculoskeletal Radiology', 'Easy', 'Radiology', 89, '{"id":8786,"subject":"Radiology","chapter":"Musculoskeletal Radiology","difficulty":"Easy","source":"Radiology","sourceNo":89,"q":"Maximal valve of HU Unit -","o":["Water","Fat","Soft tissue","Bone"],"a":3,"e":"Answer- D. Bone Bone has maximum HU → +1000","pyqMatches":[{"year":"2014","no":2012,"q":"Maximal valve of HU Unit","o":["Water","Fat","Soft tissue","Bone"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8787, 'Radiology', 'Ultrasound & Doppler', 'Easy', 'Radiology', 90, '{"id":8787,"subject":"Radiology","chapter":"Ultrasound & Doppler","difficulty":"Easy","source":"Radiology","sourceNo":90,"q":"Piezoelectric crystal most widely used in ultrasonography probes is -","o":["Quartz","Molybdenum","Titanium","Lead zircona tetitanate"],"a":3,"e":"Answer- D. Lead zircona tetitanate Lead zirconate titanate (PZT) is the most widely used material in the ultrasound transducers / probes replacing the firstly discovered barium titanate.","pyqMatches":[{"year":"2014","no":2013,"q":"Piezoelectric crystal most widely used in ultrasonography probes is","o":["Quartz","Molybdenum","Titanium","Lead zircona tetitanate"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8788, 'Radiology', 'Chest Radiology', 'Easy', 'Radiology', 91, '{"id":8788,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Easy","source":"Radiology","sourceNo":91,"q":"Most sensitive investigation for minimum gas in abdomen is -","o":["Chest X-ray AP View","CT Scan","X-ray abdomen in supine position","X-ray abdomen in erect position"],"a":1,"e":"Answer- B. CT Scan CT Scan is superior to plain radiographs in detection of minute quatities of pneumoperitoneum Thus CT Scan is regarded as the most sensitive investigation for detection of minute quantities of intraperitoneal gas. Best radiographic view for pneumoperitoneum is Chest x-ray. It is usually the first investigation of choice.","pyqMatches":[{"year":"2014","no":2016,"q":"Most sensitive investigation for minimum gas in abdomen is","o":["Chest X-ray AP View","CT Scan","X-ray abdomen in supine position","X-ray abdomen in erect position"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8789, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 92, '{"id":8789,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":92,"q":"Cotton wool skull is a radiological feature of -","o":["Pagets disease","Eosinophilic granuloma","Fibrous dysplasia","Fibrous dysplasia"],"a":0,"e":"Answer- A. Pagets disease Cotton wool skull-Paget''s disease Groundglass skull- Fibrous dysplasia Punched out/Raindrop lesion of skull- Multiple myeloma Geographic skull- Eosinophilic granuloma","pyqMatches":[{"year":"2014","no":2017,"q":"Cotton wool skull is a radiological feature of","o":["Pagets disease","Eosinophilic granuloma","Fibrous dysplasia","Fibrous dysplasia"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8790, 'Radiology', 'Imaging Principles & Contrast', 'Hard', 'Radiology', 93, '{"id":8790,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Hard","source":"Radiology","sourceNo":93,"q":"The most sensitive imaging modality for diagnosis of ureteric stone in patient with acute renal colic is -","o":["X ray KUB","USG","Non contrast CT abdomen","Contrast enhanced CT abdomen"],"a":2,"e":"Answer- C. Non contrast CT abdomen Non-contrast spiral CT has now become the investigation of choice to diagnose renal and ureteric stones. Investigation of choice for renal and ureteric stones non - contrast spiral CT","pyqMatches":[{"year":"2014","no":2018,"q":"The most sensitive imaging modality for diagnosis of ureteric stone in patient with acute renal colic is","o":["X ray KUB","USG","Non contrast CT abdomen","Contrast enhanced CT abdomen"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8791, 'Radiology', 'Chest Radiology', 'Easy', 'Radiology', 94, '{"id":8791,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Easy","source":"Radiology","sourceNo":94,"q":"Radiological features of coarctation of aorta is/ are -","o":["Reverse figure of 3 sign","Dock sign","Double aortic knuckle","All of the above"],"a":3,"e":"Answer- D. All of the above Radiological signs of COA are : i) Reverse figure of 3 sign (double bulge sign or E sign), ii) Dock''s sign; iii) Double aortic knuckle. Globular heart with oligemic lung fields Reverse figure of ''3'' sign Double aortic knuckle","pyqMatches":[{"year":"2014","no":2019,"q":"Radiological features of coarctation of aorta is/ are","o":["Reverse figure of 3 sign","Dock sign","Double aortic knuckle","All of the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8792, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 95, '{"id":8792,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":95,"q":"Eye of tiger appearance is seen in -","o":["Halle vorden Spatza","Suparanuclear palsy","Levodopa-responsive","All"],"a":3,"e":"Answer- D. All This appearance can be seen in:","pyqMatches":[{"year":"2014","no":2020,"q":"Eye of tiger appearance is seen in","o":["Halle vorden Spatza","Suparanuclear palsy","Levodopa-responsive","All"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8793, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 96, '{"id":8793,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":96,"q":"Following are suggestive of benign lesion on mammogram -","o":["Macrocalcification","Floating calcification","Tramline calcification","All the above"],"a":3,"e":"Answer- D. All the above Calcification patterns in benign lesions of breast on mammography:","pyqMatches":[{"year":"2014","no":2025,"q":"Following are suggestive of benign lesion on mammogram","o":["Macrocalcification","Floating calcification","Tramline calcification","All the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8794, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 97, '{"id":8794,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":97,"q":"Anamoly scan done at how many weeks of gestation -","o":["14","16","18","20"],"a":3,"e":"Answer- D. 20 Anamoly Scan is done between 18-21 weeks of pregnancy. It is also called as mid pregnancy or 20-week scan.","pyqMatches":[{"year":"2014","no":2026,"q":"Anamoly scan done at how many weeks of gestation","o":["14","16","18","20"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8795, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 98, '{"id":8795,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":98,"q":"Flowing wax appearance on anterior and posterior borders of vertebrae is seen in -","o":["Ankylosing spondylitis","DISH","Psoriatic arthropathy","Rheumatoid arthritis"],"a":1,"e":"Answer- B. DISH Diffuse idiopathic skeletal hyperostosis : DISH (hyperostotic spondylosis, Forestier''s disease) is a multifocal entity of older people characterized by ''flowing ossifications of the spine\" involving four or more contiguous vertebrae and hyperostosis of some ligamentous attachments.","pyqMatches":[{"year":"2014","no":2027,"q":"Flowing wax appearance on anterior and posterior borders of vertebrae is seen in","o":["Ankylosing spondylitis","DISH","Psoriatic arthropathy","Rheumatoid arthritis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8796, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 99, '{"id":8796,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":99,"q":"Radiological view which best shows maxillary sinus and orbit is -","o":["Water''s view","Caldwell view","Lateral view","Towne view"],"a":0,"e":"Answer- A. Water''s view Best view for maxillary sinus → Water''s view (occipito-mental view) Best view for frontal sinus → Caldwell view (occipito-frontal view) Best view for sphenoid sinus → Basal view (submentovertical view)","pyqMatches":[{"year":"2014","no":2029,"q":"Radiological view which best shows maxillary sinus and orbit is","o":["Water''s view","Caldwell view","Lateral view","Towne view"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8797, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 100, '{"id":8797,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":100,"q":"Best view for sphenoid sinus is -","o":["Water''s view","Caldwell view","Basal view","Towne''s view"],"a":2,"e":"Answer- C. Basal view Best view for maxillary sinus → Water''s view (occipito-mental view) Best view for frontal sinus → Caldwell view (occipito-frontal view) Best view for sphenoid sinus → Basal view (submentovertical view)","pyqMatches":[{"year":"2014","no":2030,"q":"Best view for sphenoid sinus is","o":["Water''s view","Caldwell view","Basal view","Towne''s view"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8798, 'Radiology', 'Abdominal Radiology', 'Moderate', 'Radiology', 101, '{"id":8798,"subject":"Radiology","chapter":"Abdominal Radiology","difficulty":"Moderate","source":"Radiology","sourceNo":101,"q":"Following are the indications of barium meal X-ray except -","o":["Duodenal ulcer","Carcinoma stomach","Carcinoma head of pancreas","Ischemic Colitis"],"a":3,"e":"Answer- D. Ischemic Colitis Indications for Barium meal X-ray Duodenal ulcer Periampulary carcinoma Psendocyst of pancreas Carcinoma stomach Chronic duodenal ileus Carcinoma head of pancreas Duodenal diverticula","pyqMatches":[{"year":"2014","no":2031,"q":"Following are the indications of barium meal X-ray except","o":["Duodenal ulcer","Carcinoma stomach","Carcinoma head of pancreas","Ischemic Colitis"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8799, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 102, '{"id":8799,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":102,"q":"In a children ectopic kidneys can be diagnosed by -","o":["DTPA","DMSA","MAG 3","None of the above"],"a":1,"e":"Answer- B. DMSA Indications for static renal scintigraphy (Tc - 99m - DMSA) :","pyqMatches":[{"year":"2014","no":2032,"q":"In a children ectopic kidneys can be diagnosed by","o":["DTPA","DMSA","MAG 3","None of the above"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8800, 'Radiology', 'Ultrasound & Doppler', 'Easy', 'Radiology', 103, '{"id":8800,"subject":"Radiology","chapter":"Ultrasound & Doppler","difficulty":"Easy","source":"Radiology","sourceNo":103,"q":"First line investigation for deep venous thrombosis is -","o":["Ultrasonography","Venography","MRI","Nuclear imaging"],"a":0,"e":"Answer- A. Ultrasonography Ultrasonography is the current first-line imaging examination for DVT because of its relative ease of use.","pyqMatches":[{"year":"2014","no":2034,"q":"First line investigation for deep venous thrombosis is","o":["Ultrasonography","Venography","MRI","Nuclear imaging"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8801, 'Radiology', 'GI Radiology', 'Moderate', 'Radiology', 104, '{"id":8801,"subject":"Radiology","chapter":"GI Radiology","difficulty":"Moderate","source":"Radiology","sourceNo":104,"q":"Which of the following is not a chest radiographic feature of left atrial enlargement?","o":["Double left heart border","Elevated left main bronchous","Splaying of carina","Enlargement of left atrila appendage"],"a":0,"e":"Answer- A. Double left heart border Sings of left atrial enlargement Straightening of left heart border (due to enlargement of left atrial appendage). Elevation of left main bronchus with widening (Splaying) of carina. Double density (atrial) sign. Posterior displacement of esophagus on barium swallow.","pyqMatches":[{"year":"2014","no":2035,"q":"Which of the following is not a chest radiographic feature of left atrial enlargement?","o":["Double left heart border","Elevated left main bronchous","Splaying of carina","Enlargement of left atrila appendage"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8802, 'Radiology', 'Chest Radiology', 'Moderate', 'Radiology', 105, '{"id":8802,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Moderate","source":"Radiology","sourceNo":105,"q":"HRCT features of interstitial pneumonia are all except -","o":["Reticular opacities","Honeycombing","Ground glass opacities","No bronchieactatic features"],"a":3,"e":"Answer- D. No bronchieactatic features Classical HRCT features of interstitial pneumonia are:","pyqMatches":[{"year":"2014","no":2037,"q":"HRCT features of interstitial pneumonia are all except","o":["Reticular opacities","Honeycombing","Ground glass opacities","No bronchieactatic features"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8803, 'Radiology', 'Chest Radiology', 'Moderate', 'Radiology', 106, '{"id":8803,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Moderate","source":"Radiology","sourceNo":106,"q":"Following are the causes of cavity in lungs except -","o":["Staphylococcus","Wegeners","Hydatid","Sarcoidosis"],"a":3,"e":"Answer- D. Sarcoidosis Causes of lung cavities are : 1) Necrotizing infections 2) Vascular : Pulmonary infarction. 3) Neoplastic :","pyqMatches":[{"year":"2014","no":2038,"q":"Following are the causes of cavity in lungs except","o":["Staphylococcus","Wegeners","Hydatid","Sarcoidosis"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8804, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 107, '{"id":8804,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":107,"q":"Beaded lumen with fimbrial fluid is seen in -","o":["TB of fallopian tube","TB of endometrium","TB of Ovary","None"],"a":0,"e":"Answer- A. TB of fallopian tube Fallopian tube is the most common site of female genital tract which is affected in tuberculosis. On hysterosalpingography, the fallopian tube often show ragged outlines with multiple strictures, giving a beaded appearance; in some patients the entire tube appears rigid and may exhibit small terminal sacculation of the ampullary end.","pyqMatches":[{"year":"2014","no":2039,"q":"Beaded lumen with fimbrial fluid is seen in","o":["TB of fallopian tube","TB of endometrium","TB of Ovary","None"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8805, 'Radiology', 'Musculoskeletal Radiology', 'Moderate', 'Radiology', 108, '{"id":8805,"subject":"Radiology","chapter":"Musculoskeletal Radiology","difficulty":"Moderate","source":"Radiology","sourceNo":108,"q":"Following are radiological findings in rheumatoid arthritis except -","o":["Symmetrical involvement","Juxta-articiular osteopenia","Marginal erosion","Subchondral sclerosis"],"a":3,"e":"Answer- D. Subchondral sclerosis Rheumatoid arthritis Bilateral symmetrical involvement Marginal erosion Ankylosis Periarticular soft tissue swelling Subchondral cysts Subluxation or dislocation Juxta - articular osteopenia Narrowing of joint space (Later) Arthritis multilans (late)","pyqMatches":[{"year":"2014","no":2040,"q":"Following are radiological findings in rheumatoid arthritis except","o":["Symmetrical involvement","Juxta-articiular osteopenia","Marginal erosion","Subchondral sclerosis"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8806, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 109, '{"id":8806,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":109,"q":"Which of the following is/are radiological features of fluorosis?","o":["Osteosclerosis","Cortical thickening","Enthesopathy","All the above"],"a":3,"e":"Answer- D. All the above Radiological features of fluorosis are : Osteosclerosis - particularly affecting the axial skeleton. Cortical thickening with encroachment on medullary cavity. Enthesopathy with ligamentous ossification. Large spinal osteophytes.","pyqMatches":[{"year":"2014","no":2041,"q":"Which of the following is/are radiological features of fluorosis?","o":["Osteosclerosis","Cortical thickening","Enthesopathy","All the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8807, 'Radiology', 'Ultrasound & Doppler', 'Easy', 'Radiology', 110, '{"id":8807,"subject":"Radiology","chapter":"Ultrasound & Doppler","difficulty":"Easy","source":"Radiology","sourceNo":110,"q":"Depth of gastric carcinomas is assessed by -","o":["Abdominal ultrasound","Barium meal","Endoluminal ultrasound","Laproscopy"],"a":2,"e":"Answer- C. Endoluminal ultrasound Five layers of the gastric wall can be identified by endoluminal ultrasound and the depth of invasion of tumor can be assessed by exquisite accuracy.","pyqMatches":[{"year":"2014","no":2042,"q":"Depth of gastric carcinomas is assessed by","o":["Abdominal ultrasound","Barium meal","Endoluminal ultrasound","Laproscopy"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8808, 'Radiology', 'Abdominal Radiology', 'Easy', 'Radiology', 111, '{"id":8808,"subject":"Radiology","chapter":"Abdominal Radiology","difficulty":"Easy","source":"Radiology","sourceNo":111,"q":"Radiological signs of acute pancreatitis on plain radiography are -","o":["Sentinel loop sign","Colon cut off sign","Renal halo sign","All the above"],"a":3,"e":"Answer- D. All the above Radiological features of acute pancreatitis :-","pyqMatches":[{"year":"2014","no":2043,"q":"Radiological signs of acute pancreatitis on plain radiography are","o":["Sentinel loop sign","Colon cut off sign","Renal halo sign","All the above"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8809, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 112, '{"id":8809,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":112,"q":"Most sensitive investigation for Diffuse axonal injury is -","o":["MRI","CT","X ray","PET scan"],"a":0,"e":"Answer- A. MRI MRI is the most sensitive investigation for diffuse axonal injuries. It shows multiple small faces of increased intensity on T,IAT and decreased intensity on Ty.","pyqMatches":[{"year":"2014","no":2045,"q":"Most sensitive investigation for Diffuse axonal injury is","o":["MRI","CT","X ray","PET scan"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8810, 'Radiology', 'Chest Radiology', 'Easy', 'Radiology', 113, '{"id":8810,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Easy","source":"Radiology","sourceNo":113,"q":"Most common view used for X-ray chest -","o":["PA view","AP view","Lateral view","Oblique view"],"a":0,"e":"Answer- A. PA view Important views for chest x-ray are :","pyqMatches":[{"year":"2014","no":2046,"q":"Most common view used for X-ray chest","o":["PA view","AP view","Lateral view","Oblique view"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8811, 'Radiology', 'Musculoskeletal Radiology', 'Easy', 'Radiology', 114, '{"id":8811,"subject":"Radiology","chapter":"Musculoskeletal Radiology","difficulty":"Easy","source":"Radiology","sourceNo":114,"q":"Best investigation for bone metastases is -","o":["MRI","CT","Bone Scan","X Ray"],"a":2,"e":"Answer- C. Bone Scan Bone scan (scintigraphy) is the investigation of choice for bone metastasis.","pyqMatches":[{"year":"2014","no":2047,"q":"Best investigation for bone metastases is","o":["MRI","CT","Bone Scan","X Ray"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8812, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 115, '{"id":8812,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":115,"q":"Double track sign is seen in -","o":["Duodenal atresia","CHPS","Gastric ulcer","Achalasia"],"a":1,"e":"Answer- B. CHPS Double/triple track sign is seen in congenital hypertrophic pyloric stenosis.","pyqMatches":[{"year":"2012","no":1428,"q":"Double track sign is seen in","o":["Duodenal atresia","CHPS","Gastric ulcer","Achalasia"],"a":1,"source":"NEET_2012_Paper.pdf"},{"year":"2014","no":2048,"q":"Double track sign is seen in","o":["Duodenal atresia","CHPS","Gastric ulcer","Achalasia"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2012","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8813, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 116, '{"id":8813,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":116,"q":"Half life of Ra-226 -","o":["8 days","28 years","16-22 years","38 years"],"a":2,"e":"Answer- C. 16-22 years Half life of Ra-226 is 16-22 years.","pyqMatches":[{"year":"2014","no":2049,"q":"Half life of Ra-226","o":["8 days","28 years","16-22 years","38 years"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8814, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 117, '{"id":8814,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":117,"q":"Which view is taken for aortic window -","o":["AP","LAO","RAO","LPO"],"a":1,"e":"Answer- B. LAO `A left anterior oblique (LAO) view is useful to assess thoracic aorta, aortic window and the chamber of heart\". Clinicalradiology Aortic window is the space between ascending and descending thoracic aorta.","pyqMatches":[{"year":"2014","no":2050,"q":"Which view is taken for aortic window","o":["AP","LAO","RAO","LPO"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8815, 'Radiology', 'Ultrasound & Doppler', 'Easy', 'Radiology', 118, '{"id":8815,"subject":"Radiology","chapter":"Ultrasound & Doppler","difficulty":"Easy","source":"Radiology","sourceNo":118,"q":"The primary diagnostic evaluation for developmental dyslasia of hip is -","o":["Clinical examination","X-ray","USG","CT Scan"],"a":2,"e":"Answer- C. USG Ultrasonography is now the primary imaging technique in the diagnosis and follow up of DDH and has been shown to be more accurate than clinical and radiological assessment with a sensitivity of 100% and specificity of 98%.","pyqMatches":[{"year":"2014","no":2052,"q":"The primary diagnostic evaluation for developmental dyslasia of hip is","o":["Clinical examination","X-ray","USG","CT Scan"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8816, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 119, '{"id":8816,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":119,"q":"Investigation of choice for pancoast tumor is -","o":["MRI","HRCT","CECT","Bronchography"],"a":0,"e":"Answer- A. MRI Radiological investigation of choice for pubnonary malignencies is CT scan excep in superior sulcus (pancoast tumor) where MRI is preferred.","pyqMatches":[{"year":"2014","no":2054,"q":"Investigation of choice for pancoast tumor is","o":["MRI","HRCT","CECT","Bronchography"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8817, 'Radiology', 'Ultrasound & Doppler', 'Easy', 'Radiology', 120, '{"id":8817,"subject":"Radiology","chapter":"Ultrasound & Doppler","difficulty":"Easy","source":"Radiology","sourceNo":120,"q":"Doppler effect results from change in -","o":["Amplitude of sound","Frequency of sound","Direction of sound","None of the above"],"a":1,"e":"Answer- B. Frequency of sound The Doppler effect results from an apparent shift in sound frequency as sound wave are reflected from moving targets, usually blood cells. If motion is toward the transducer, the frequency of returning echo is higher that of the transmitted sound.","pyqMatches":[{"year":"2013","no":1748,"q":"Doppler effect results from change in","o":["Amplitude of sound","Frequency of sound","Direction of sound","None of the above"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8818, 'Radiology', 'Chest Radiology', 'Easy', 'Radiology', 121, '{"id":8818,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Easy","source":"Radiology","sourceNo":121,"q":"X-ray Artifact is -","o":["A radiolucent area","Any abnormal opacity in the radiograph","Produced when patient moves while taking the shoot","All the above"],"a":2,"e":"Answer- C. Produced when patient moves while taking the shoot Artifacts can present in a variety of ways including abnormal shadow noted on a radiograph or degraded image quality and have been produced by artificial means from hardware failure, operator error and software (post-processing) artifacts. Common causes :- Improper handling of the films Errors while processing the films Patient movement while taking the shoot","pyqMatches":[{"year":"2013","no":1749,"q":"X-ray Artifact is","o":["A radiolucent area","Any abnormal opacity in the radiograph","Produced when patient moves while taking the shoot","All the above"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8819, 'Radiology', 'Ultrasound & Doppler', 'Easy', 'Radiology', 122, '{"id":8819,"subject":"Radiology","chapter":"Ultrasound & Doppler","difficulty":"Easy","source":"Radiology","sourceNo":122,"q":"Frequency of ultrasound waves in USG -","o":["2000 Hz","5000 Hz","< 2 MHz",">2 MHz"],"a":3,"e":"Answer- D. >2 MHz The ultrasound machine emits high-frequency sound waves, ranging from 2-15 MHz. Whose frequencies are considerably above the upper limit of human ear''s audible range, i.e., greater than 20000 Hz. Speed of these sound waves in the body is 1540 m/s (in comparison to air, where velocity of sound wave is 330m/s).","pyqMatches":[{"year":"2013","no":1750,"q":"Frequency of ultrasound waves in USG","o":["2000 Hz","5000 Hz","< 2 MHz",">2 MHz"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8820, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 123, '{"id":8820,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":123,"q":"Gyromagnetic property of proton is seen in -","o":["MRI","CT","PET scan","USG"],"a":0,"e":"Answer- A. MRI Ultrasonography is based on piezoelectric effect. MRI is based on gyeromagnetic property of proton W9.","pyqMatches":[{"year":"2013","no":1751,"q":"Gyromagnetic property of proton is seen in","o":["MRI","CT","PET scan","USG"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8821, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 124, '{"id":8821,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":124,"q":"Enhancement in CT contrast is due to -","o":["Iodine","Gadolinium","Silver","Mercury"],"a":0,"e":"Answer- A. Iodine Iodinated contrasts are the most commonly used radiocontrast media in radiography and CT. Gadolinium is the most commonly used MR contrast agent.","pyqMatches":[{"year":"2013","no":1752,"q":"Enhancement in CT contrast is due to","o":["Iodine","Gadolinium","Silver","Mercury"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8822, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 125, '{"id":8822,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":125,"q":"Which delivers highest dose of radiation -","o":["Cardiac perfusion scan","CT chest","CT brain","Mammogram"],"a":0,"e":"Answer- A. Cardiac perfusion scan Medical diagnostic imaging is a major source of radiation exposure to clinitians and the patients. Following table depicts the radiation exposure through the routine medical imaging.","pyqMatches":[{"year":"2013","no":1753,"q":"Which delivers highest dose of radiation","o":["Cardiac perfusion scan","CT chest","CT brain","Mammogram"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8823, 'Radiology', 'Chest Radiology', 'Easy', 'Radiology', 126, '{"id":8823,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Easy","source":"Radiology","sourceNo":126,"q":"Best view for collapse of middle lobe lung is -","o":["Lateral","AP","Oblique","Lordotic"],"a":3,"e":"Answer- D. Lordotic The lordotic view is also useful for recognizing collapse of lingula or middle lobe when these areas become very thin and cast minimal shadow on the PA view.","pyqMatches":[{"year":"2013","no":1754,"q":"Best view for collapse of middle lobe lung is","o":["Lateral","AP","Oblique","Lordotic"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8824, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 127, '{"id":8824,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":127,"q":"Double shadow behind right atrium and straightening of left main bronchus indicates -","o":["Right atrium enlargement","Right ventricle enlargement","Left atrium enlargement","Left ventricle enlargement"],"a":2,"e":"Answer- C. Left atrium enlargement Left atrium enlargement Ref Sutton 7h/e p. 280-350]","pyqMatches":[{"year":"2013","no":1755,"q":"Double shadow behind right atrium and straightening of left main bronchus indicates","o":["Right atrium enlargement","Right ventricle enlargement","Left atrium enlargement","Left ventricle enlargement"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8825, 'Radiology', 'GI Radiology', 'Easy', 'Radiology', 128, '{"id":8825,"subject":"Radiology","chapter":"GI Radiology","difficulty":"Easy","source":"Radiology","sourceNo":128,"q":"Left atrial enlargement is seen in -","o":["Mitral stenosis","Tricuspid regurgitation","AR","None"],"a":0,"e":"Answer- A. Mitral stenosis Due to left atrial enlargement :- Straightening of left heart border, elevation of left main bronchus with widening of carina, double atrial shadow (Double density sign), posterior displacement of esophagus on barium swallow, Prominent posterosuperior part of cardiac shadow.","pyqMatches":[{"year":"2013","no":1756,"q":"Left atrial enlargement is seen in","o":["Mitral stenosis","Tricuspid regurgitation","AR","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8826, 'Radiology', 'Chest Radiology', 'Moderate', 'Radiology', 129, '{"id":8826,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Moderate","source":"Radiology","sourceNo":129,"q":"Air bronchogram on chest Xray denotes -","o":["Intrapulmonary lesion","Extrapulmonary lesion","Intrathoracic lesion","Extrathoracic lesion"],"a":0,"e":"Answer- A. Intrapulmonary lesion Air in bronchi is visualized it is called air bronchogram. Air bronchogram indicates intrapulmonary pathology, It excludes any pleural or mediastinal pathology.","pyqMatches":[{"year":"2013","no":1758,"q":"Air bronchogram on chest Xray denotes","o":["Intrapulmonary lesion","Extrapulmonary lesion","Intrathoracic lesion","Extrathoracic lesion"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8827, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 130, '{"id":8827,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":130,"q":"Calcified pulmonary metastasis is seen in which carcinoma -","o":["Pancreatic carcinoma","Thyroid carcinoma","Endometrial carcinoma","None"],"a":1,"e":"Answer- B. Thyroid carcinoma Differential diagnosis of calcified pulmonary metastasis :-","pyqMatches":[{"year":"2013","no":1759,"q":"Calcified pulmonary metastasis is seen in which carcinoma","o":["Pancreatic carcinoma","Thyroid carcinoma","Endometrial carcinoma","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8828, 'Radiology', 'Chest Radiology', 'Hard', 'Radiology', 131, '{"id":8828,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Hard","source":"Radiology","sourceNo":131,"q":"Differential diagnosis of solitary pulmonary nodule are all except -","o":["Bronchogenic carcinoma","Mycetoma","Tuberculoma","Hamartoma"],"a":1,"e":"Answer- B. Mycetoma Granulomas : - Tuberculoma (most common cause), Histoplasma, Coccidioidomycosis, cryptococcosis. Other infections : - Organizing pneumonia, hydatid cyst. Benign neoplams : - Hamartoma, Fibroma, Neurofibroma, Carcinoid tumours, Lipoma, Bronchial adenoma Malignant neoplasm : - Carcinoma bronchus, Alveolar cell carcinoma, metastasis (from breast, Sarcoma, Renal cell carcinoma, Seminoma), Pulmonary blastoma, Pulmonary sarcoma. Inflammatory - Wegener''s granulomatosis, rheumatoid arthritis, Sarcoidosis. Congenital : - Sequestration, Bronchogenic cyst, AV malformation. Miscellaneous : - Pulmonary infarct, Rounded atelectasis, Mucoid impaction.","pyqMatches":[{"year":"2013","no":1760,"q":"Differential diagnosis of solitary pulmonary nodule are all except","o":["Bronchogenic carcinoma","Mycetoma","Tuberculoma","Hamartoma"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8829, 'Radiology', 'Chest Radiology', 'Hard', 'Radiology', 132, '{"id":8829,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Hard","source":"Radiology","sourceNo":132,"q":"The sign with patch of dullness beneath the angle of left scapula in a patient with pericardial effusion is named as -","o":["Carvallo''s sign","Ewart''s sign","Homan''s sign","Hoffmann''s sign"],"a":1,"e":"Answer- B. Ewart''s sign Heart sounds become faint - The apex impulse vanishes; but sometimes it remains palpable, medial to the left border of cardiac dullness. The base of the left lung may be compressed by pericardial fluid, producing Ewart''s sign, a patch of dullness beneath the angle of the left scapula. The chest roentgenogram may show a \"water bottle\" or \"flask shaped\" configuration of the cardiac silhouette","pyqMatches":[{"year":"2013","no":1764,"q":"The sign with patch of dullness beneath the angle of left scapula in a patient with pericardial effusion is named as","o":["Carvallo''s sign","Ewart''s sign","Homan''s sign","Hoffmann''s sign"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8830, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 133, '{"id":8830,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":133,"q":"Water bottle heart is seen in -","o":["PDA","Chronic emphysema","Pericardial effusion","Constrictive pericarditis"],"a":2,"e":"Answer- C. Pericardial effusion \"Water-bottle\" or flasked shaped or money bag heart - Pericardial effusion, hypothyroidism","pyqMatches":[{"year":"2013","no":1765,"q":"Water bottle heart is seen in","o":["PDA","Chronic emphysema","Pericardial effusion","Constrictive pericarditis"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8831, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 134, '{"id":8831,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":134,"q":"For pericardial calcifications, which is the best investigation -","o":["MRI","Transesophageal echocardiography","USG","CT scan"],"a":3,"e":"Answer- D. CT scan CT is the best method for depiction of pericardial calcification, a finding suggestive of constrictive pericarditis in the appropriate clinical setting.","pyqMatches":[{"year":"2013","no":1767,"q":"For pericardial calcifications, which is the best investigation","o":["MRI","Transesophageal echocardiography","USG","CT scan"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8832, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 135, '{"id":8832,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":135,"q":"Fluorescin angiography is used to examine -","o":["Ciliary vasculature","Retinal vasculature","Corneal vasculature","Conjuctival vasculature"],"a":1,"e":"Answer- B. Retinal vasculature Fluorescein angiography is a radiological examination of retinal vasculature after the administration of a fluorescein dye.","pyqMatches":[{"year":"2013","no":1769,"q":"Fluorescin angiography is used to examine","o":["Ciliary vasculature","Retinal vasculature","Corneal vasculature","Conjuctival vasculature"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8833, 'Radiology', 'Abdominal Radiology', 'Easy', 'Radiology', 136, '{"id":8833,"subject":"Radiology","chapter":"Abdominal Radiology","difficulty":"Easy","source":"Radiology","sourceNo":136,"q":"Barium swallow is used for -","o":["Colon","Esophagus","Duodenum","Jejunum"],"a":1,"e":"Answer- B. Esophagus Barium swallow -Mainly for esophagus","pyqMatches":[{"year":"2013","no":1770,"q":"Barium swallow is used for","o":["Colon","Esophagus","Duodenum","Jejunum"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8834, 'Radiology', 'Abdominal Radiology', 'Easy', 'Radiology', 137, '{"id":8834,"subject":"Radiology","chapter":"Abdominal Radiology","difficulty":"Easy","source":"Radiology","sourceNo":137,"q":"Pulled up cecum is seen in -","o":["Ileocecal TB","Carcinoma cecum","Intussuption","Carcinoma"],"a":0,"e":"Answer- A. Ileocecal TB Conical cecum or Amputed cecum Cecum is shrunken in size and pulled out of the iliac fossa due fibrosis and contraction of mesocolon. Stierlin sign :- Narrowing of terminal ileum with rapid emptying into a shortened, rigid or obliterated cecum. String sign","pyqMatches":[{"year":"2013","no":1772,"q":"Pulled up cecum is seen in","o":["Ileocecal TB","Carcinoma cecum","Intussuption","Carcinoma"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8835, 'Radiology', 'GI Radiology', 'Easy', 'Radiology', 138, '{"id":8835,"subject":"Radiology","chapter":"GI Radiology","difficulty":"Easy","source":"Radiology","sourceNo":138,"q":"The study using barium for small intestine is known as -","o":["Barium meal follow through","Barium swallow","Barium enema","None of the above"],"a":0,"e":"Answer- A. Barium meal follow through In most cases the jejunum and Ileum are examined following the barium examination of the upper gastrointestinal tract, referred to as the \"barium meal and follow through\" or simply \"barium follow through\".","pyqMatches":[{"year":"2013","no":1773,"q":"The study using barium for small intestine is known as","o":["Barium meal follow through","Barium swallow","Barium enema","None of the above"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8836, 'Radiology', 'Imaging Principles & Contrast', 'Hard', 'Radiology', 139, '{"id":8836,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Hard","source":"Radiology","sourceNo":139,"q":"Investigation with least radiation dose in the diagnosis Meckel''s diverticulum is -","o":["CT","MRI","Contrast radiography","Technetium -99m scanning"],"a":2,"e":"Answer- C. Contrast radiography It is a general rule that the ascending order of the radiation dose is MRI < X- ray < CT - Scan. Technetium - 99m has the radiation exposure more than X - ray but less than CT - Scan. So contrast radiography will have the minimum radiation exposure as it involves taking a radiograph after small bowel enema for diagnosis of meckel''s diverticulum.","pyqMatches":[{"year":"2013","no":1777,"q":"Investigation with least radiation dose in the diagnosis Meckel''s diverticulum is","o":["CT","MRI","Contrast radiography","Technetium -99m scanning"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8837, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 140, '{"id":8837,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":140,"q":"Endoscopic USG criteria for chronic pancreatitis, when echogenic lesion is -","o":["> 1 mm","1.5 mm","> 2 mm","> 3 mm"],"a":3,"e":"Answer- D.�> 3 mm Parenchymal features Echo-poor lesion Echo-rich lesion (> 3 mm in diameter) Accenuation of lobular pattern Gland size, cyst Ductal features Increased duct wall echogenicity Narrowing, dilatation Calculi","pyqMatches":[{"year":"2013","no":1778,"q":"Endoscopic USG criteria for chronic pancreatitis, when echogenic lesion is","o":["> 1 mm","1.5 mm","> 2 mm","> 3 mm"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8838, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 141, '{"id":8838,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":141,"q":"Most sensitive test to detect early renal TB is -","o":["Intravenous urography","CT","MRI","USG"],"a":0,"e":"Answer- A. Intravenous urography IVP remains the primary modality used to image the patients with renal, ureteric, and bladder tuberculosis. Early findings are best detected on IVP. It is the investigation of choice for urinary TB.","pyqMatches":[{"year":"2013","no":1779,"q":"Most sensitive test to detect early renal TB is","o":["Intravenous urography","CT","MRI","USG"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8839, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 142, '{"id":8839,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":142,"q":"Investigation of choice for focal neurologic deficit in emergency room is -","o":["CT","MRI","Lumbar puncture","CECT"],"a":0,"e":"Answer- A. CT In Indian set up CT Scan is the investigation of choice in the emergency room to screen patients of acute focal neurologic deficit.","pyqMatches":[{"year":"2013","no":1780,"q":"Investigation of choice for focal neurologic deficit in emergency room is","o":["CT","MRI","Lumbar puncture","CECT"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8840, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 143, '{"id":8840,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":143,"q":"CT Scan finding in carotid cavernous sinus fistula is -","o":["Enlarged superior ophthalmic vein","Enlarged inferior ophthalmic vein","Enlarged superior ophthalmic artery","Enlarged inferior ophthalmic artery"],"a":0,"e":"Answer- A. Enlarged superior ophthalmic vein Contrast-enhanced CT scan and MRI will demonstrate a dilated superior ophthalmic vein and cavernous sinus. Ultrasonography may also demonstrate superior ophthalmic vein engorgement. Magnetic resonance angiography (MRA) is also very useful in identifying fistulas as well as particular vessel involvement.","pyqMatches":[{"year":"2013","no":1781,"q":"CT Scan finding in carotid cavernous sinus fistula is","o":["Enlarged superior ophthalmic vein","Enlarged inferior ophthalmic vein","Enlarged superior ophthalmic artery","Enlarged inferior ophthalmic artery"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8841, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 144, '{"id":8841,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":144,"q":"On imagning diffuse axonal injury is characterized by -","o":["Multiple small petechial hemorrhage","Patch ill defined low density lesion mixed with small hyperdens of petechial hemorrhage","Crescentic extra-axial hematoma","White matter lucencies"],"a":0,"e":"Answer- A. Multiple small petechial hemorrhage Multiple small petechial hemorrhage <2cm diameter in cerebral hemisphere.","pyqMatches":[{"year":"2013","no":1782,"q":"On imagning diffuse axonal injury is characterized by","o":["Multiple small petechial hemorrhage","Patch ill defined low density lesion mixed with small hyperdens of petechial hemorrhage","Crescentic extra-axial hematoma","White matter lucencies"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8842, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 145, '{"id":8842,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":145,"q":"Rhese view is used for -","o":["Superior orbital foramen","Inferior orbital foramen","Optic foramen","Sella turcica"],"a":2,"e":"Answer- C. Optic foramen Optic foramen- Rhese view","pyqMatches":[{"year":"2013","no":1783,"q":"Rhese view is used for","o":["Superior orbital foramen","Inferior orbital foramen","Optic foramen","Sella turcica"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8843, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 146, '{"id":8843,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":146,"q":"Prevertebral space thickness in adult is -","o":["7mm","14mm","22mm","30mm"],"a":0,"e":":C Answer- A & C. 22mm (A) 7mm < 7mm at C1 level < 5mm at C3 - C9level < 22mm at C6 level","pyqMatches":[{"year":"2013","no":1784,"q":"Prevertebral space thickness in adult is","o":["7mm","14mm","22mm","30mm"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8844, 'Radiology', 'Chest Radiology', 'Easy', 'Radiology', 147, '{"id":8844,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Easy","source":"Radiology","sourceNo":147,"q":"Osteolytic metastasis is seen with -","o":["Lung","Kidney","Thyroid","All of the above"],"a":3,"e":"Answer- D. All of the above Osteolytic, characterized by destruction of normal bone, present in multiple myeloma (MM), renal cell carcinoma, melanoma, non-small cell lung cancer, non-hodgkin lymphoma, thyroid cancer or langerhans-cell histiocytosis.","pyqMatches":[{"year":"2013","no":1785,"q":"Osteolytic metastasis is seen with","o":["Lung","Kidney","Thyroid","All of the above"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8845, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 148, '{"id":8845,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":148,"q":"Investigation of choice in whole body imaging in metastasis is -","o":["Magnetic Resonance Imaging","Angiography","Venography","CT Scan"],"a":0,"e":"Answer- A. Magnetic Resonance Imaging Whole-body MR imaging with use of a rolling table platform in conjunction with fast T2-weighted turbo spin-echo and 3D gradient- echo sequences is a time-saving and accurate alternative to conventional multimodality evaluation of patients with tumors for metastases.","pyqMatches":[{"year":"2013","no":1786,"q":"Investigation of choice in whole body imaging in metastasis is","o":["Magnetic Resonance Imaging","Angiography","Venography","CT Scan"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8846, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 149, '{"id":8846,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":149,"q":"T sign is seen in -","o":["Genital TB","Membrane in twin pregnancy","Molar pregnancy","Choriocarcinoma"],"a":1,"e":"Answer- B. Membrane in twin pregnancy ''T sign'' refers to appearance of the inter-twin membrane in a monochorionic twin pregnancy.","pyqMatches":[{"year":"2013","no":1787,"q":"T sign is seen in","o":["Genital TB","Membrane in twin pregnancy","Molar pregnancy","Choriocarcinoma"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8847, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 150, '{"id":8847,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":150,"q":"Investigation of choice in congenital uterine anamoly is -","o":["MRI","CT","HSG","Hysteroscopy"],"a":3,"e":"Answer- D. Hysteroscopy Hysteroscopy is the gold standard in the diagnosis as well as therapeutic management.","pyqMatches":[{"year":"2013","no":1788,"q":"Investigation of choice in congenital uterine anamoly is","o":["MRI","CT","HSG","Hysteroscopy"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8848, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 151, '{"id":8848,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":151,"q":"Maximum radiation dose tolerable tissue is -","o":["Hemopoietic tissue","Testis","Ovary","Bone"],"a":3,"e":"Answer- D. Bone Highly radiosensitive Lymphoid tissue Bone marrow GIT epithelium Gonads (Testis, ovary) Embryonic tissue","pyqMatches":[{"year":"2013","no":1791,"q":"Maximum radiation dose tolerable tissue is","o":["Hemopoietic tissue","Testis","Ovary","Bone"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8849, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 152, '{"id":8849,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":152,"q":"Epidermoid cyst can be differentiated from arachnoid cyst by -","o":["MRI","USG","Myelography","CT scan"],"a":0,"e":"Answer- A. MRI Myelography cannot differentiate reliably between an epidermoid cyst and a noncommunicating arachnoid cyst. It has largely been replaced by MRI.","pyqMatches":[{"year":"2013","no":1792,"q":"Epidermoid cyst can be differentiated from arachnoid cyst by","o":["MRI","USG","Myelography","CT scan"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8850, 'Radiology', 'Neuroradiology', 'Easy', 'Radiology', 153, '{"id":8850,"subject":"Radiology","chapter":"Neuroradiology","difficulty":"Easy","source":"Radiology","sourceNo":153,"q":"Soap bubble appearance on MRI brain is characteristic of?","o":["Tubercular meningitis","Neurocysticercosis","Cryptococcal cysts","Ependymoma"],"a":2,"e":"Answer- C. Cryptococcal cysts Cryptococcomas T1: low signal T2 / FLAIR: high signal T1 C+ (Gd): variable, ranging from no enhancement to peripheral nodular enhancement. Gelatinous pseudocysts caused by Cryptococcus tend to give a \"soap bubble\" appearance on MRI. MRI findings in neural cryptococcosis.","pyqMatches":[{"year":"2016","no":1727,"q":"Soap bubble appearance on MRI brain is characteristic of?","o":["Tubercular meningitis","Neurocysticercosis","Cryptococcal cysts","Ependymoma"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8851, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 154, '{"id":8851,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":154,"q":"T2 image in MRI is -","o":["Good to detect pathology","Good to detect anatomy","Good for both","Good for none"],"a":0,"e":"Answer- A. Good to detect pathology Many pulse-sequence techniques are used in MRI, but most classic are T1 and T2 weighted images. As a general rule, TI-weighted images are good for viewing anatomy, and T2 weighted images are good for detecting pathology. [Ref Fundamentals of diagnostic radiology p. 18]","pyqMatches":[{"year":"2016","no":1728,"q":"T2 image in MRI is","o":["Good to detect pathology","Good to detect anatomy","Good for both","Good for none"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8852, 'Radiology', 'Ultrasound & Doppler', 'Easy', 'Radiology', 155, '{"id":8852,"subject":"Radiology","chapter":"Ultrasound & Doppler","difficulty":"Easy","source":"Radiology","sourceNo":155,"q":"Keyhole sign on ultrasound is seen in -","o":["Polycystic kidney","Hydronephrosis","Chronic pyelonephritis","Posterior urethral valves"],"a":3,"e":"Answer- D. Posterior urethral valves The keyhole sign is an ultrasonographic sign seen in boys with posterior urethral valves. lt refers to the appearance of the proximal urethra (which is dilated) and associated thick walled distended bladder which on ultrasound may resemble a key hole.","pyqMatches":[{"year":"2016","no":1730,"q":"Keyhole sign on ultrasound is seen in","o":["Polycystic kidney","Hydronephrosis","Chronic pyelonephritis","Posterior urethral valves"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8853, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 156, '{"id":8853,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":156,"q":"MIBG dose is -","o":["40-80MBq","80-100MBq","100-120MBq","120-150MBq"],"a":0,"e":"Answer- A. 40-80MBq MIBG scan is a scintigraphic study that uses metaiodobenzylguanidine labeled to Iodine- 123 or Iodine- 131. The activity administered to adults should be: for 131I-mIBG: 40-80 MBq (1.2 - 2.2 mCi); for 123ImIBG: 400 MBq (10.8 mCi). For minimum and maximum recommended activities in children one should consult the Guidelines for Radioiodinated MIBG Scintigraphy in Children (minimum activity 20 MBqfor 123I-mIBG and 35 MBqfor 131I-nIBG; maximum activity 400 MBqfor 123I-mIBG and 80 MBqfor 131I-mIBG).","pyqMatches":[{"year":"2016","no":1731,"q":"MIBG dose is","o":["40-80MBq","80-100MBq","100-120MBq","120-150MBq"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8854, 'Radiology', 'Abdominal Radiology', 'Easy', 'Radiology', 157, '{"id":8854,"subject":"Radiology","chapter":"Abdominal Radiology","difficulty":"Easy","source":"Radiology","sourceNo":157,"q":"Barium meal follow through is helpful in diagnosing -","o":["Colonic stricture","Ileal stricture","Rectal stricture","Esophageal stricture"],"a":1,"e":"Answer- B. Ileal stricture Following abnormalities of small intestine can be identified:-","pyqMatches":[{"year":"2016","no":1732,"q":"Barium meal follow through is helpful in diagnosing","o":["Colonic stricture","Ileal stricture","Rectal stricture","Esophageal stricture"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8855, 'Radiology', 'Chest Radiology', 'Easy', 'Radiology', 158, '{"id":8855,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Easy","source":"Radiology","sourceNo":158,"q":"Radiographic sign characteristic of pulmonary edema is -","o":["Westermark''s sign","Hampton''s hump","Palla sign","Bat wing sign"],"a":3,"e":"Answer- D. Bat wing sign Acute pulmonary edema : - Acute pulmonary edema is characterized by centrally located alveolar sign, with hazy or fluffy increased density in perihilar distribution, creating a bat-wing or angel-wing paftern. There is relative sparing of the more peripheral zones of lung fields. Air bronchogram become evident as edema becomes more opaque.","pyqMatches":[{"year":"2016","no":1735,"q":"Radiographic sign characteristic of pulmonary edema is","o":["Westermark''s sign","Hampton''s hump","Palla sign","Bat wing sign"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8856, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 159, '{"id":8856,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":159,"q":"Gamma knife utilizes -","o":["Strontium 89","1-131","Cobalt -60","P-32"],"a":2,"e":"Answer- C. Cobalt -60 Gamma knife contains Cobalt-60 sources of approximately 30 curis placed in circular array in a heavily shielded unit. The unit directs the gamma rirys to the target.","pyqMatches":[{"year":"2016","no":1736,"q":"Gamma knife utilizes","o":["Strontium 89","1-131","Cobalt -60","P-32"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8857, 'Radiology', 'Chest Radiology', 'Easy', 'Radiology', 160, '{"id":8857,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Easy","source":"Radiology","sourceNo":160,"q":"Snow storm appearance on chest X-ray is seen in -","o":["Anthracosis","Byssinosis","Silicosis","Bagassosis"],"a":2,"e":"Answer- C. Silicosis Simple form z- Multiple small rounded (nodular) opacities in the lung parenchyna (snow stonn appeoraace). These nodules tend to be located predominantly in the middle and upper lung fields with relative sparing of lower lung fields (Though Iower lung fields can also be involved later in disease process). There is bilateral hilar lymphadenopathy with characteristic egg shell calcification.","pyqMatches":[{"year":"2016","no":1737,"q":"Snow storm appearance on chest X-ray is seen in","o":["Anthracosis","Byssinosis","Silicosis","Bagassosis"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8858, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 161, '{"id":8858,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":161,"q":"\"Droop lily sign\" is seen in -","o":["\"Droop lily sign\" is seen in","Duplicated collecting system","Chronic pyelonephritis","Hypernephroma"],"a":1,"e":"Answer- B. Duplicated collecting system The drooping lily srgl (dropping flower sign) is a urographic sign in some patients with a duplicated collecting system. It refers to the inferolateral displacement of the opacified lower pole moiety due to an obstructed (and unopacified) upper pole moeity.","pyqMatches":[{"year":"2016","no":1738,"q":"\"Droop lily sign\" is seen in","o":["\"Droop lily sign\" is seen in","Duplicated collecting system","Chronic pyelonephritis","Hypernephroma"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8859, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 162, '{"id":8859,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":162,"q":"Sonographic appearance of hydatid cyst is -","o":["Hyperechoic aseptate lesion","Hypoechoic aseptate lesion","Hyperechoic septate lesion","Hypoechoic septate lesion"],"a":3,"e":"Answer- D. Hypoechoic septate lesion Type I (Simple cyst):- Single (solitary) hnrcechoic/anechoic aseptate (without septa) lesion. The diagnosis of hydatid cyst may be considered when focal thickening of wall is present or when hlperechoic spots, due to hydatid sand, appear in the dependent areas.","pyqMatches":[{"year":"2016","no":1739,"q":"Sonographic appearance of hydatid cyst is","o":["Hyperechoic aseptate lesion","Hypoechoic aseptate lesion","Hyperechoic septate lesion","Hypoechoic septate lesion"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8860, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 163, '{"id":8860,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":163,"q":"SI unit of absorbed dose is -","o":["Becquerel","Columb/cm","Gray","Sievert [Sv]"],"a":2,"e":"Answer- C. Gray Old unit of absorbed dose is Rad and new unit (SI) is Gray.","pyqMatches":[{"year":"2016","no":1742,"q":"SI unit of absorbed dose is","o":["Becquerel","Columb/cm","Gray","Sievert [Sv]"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8861, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 164, '{"id":8861,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":164,"q":"Stenver''s view is used for -","o":["Superior orbital foramen","Inferior orbital foramen","Internal auditory canal","Sella turcica"],"a":2,"e":"Answer- C. Internal auditory canal Skull trauma (sella turcica) (pituitary fossa)- Lateral view Internal auditory view (both side)- Stenver''s view","pyqMatches":[{"year":"2016","no":1743,"q":"Stenver''s view is used for","o":["Superior orbital foramen","Inferior orbital foramen","Internal auditory canal","Sella turcica"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8862, 'Radiology', 'Chest Radiology', 'Easy', 'Radiology', 165, '{"id":8862,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Easy","source":"Radiology","sourceNo":165,"q":"Acute myocarditis schintigraphy is done with -","o":["Thallium","Technetium","Gallium","None"],"a":2,"e":"Answer- C. Gallium Gallium-67 uptake is increased in inflamed myocardium. Gallium-67 citrate injected intravenously binds to transferrin, and it is incorporated into the transferrin receptor of inflammatory cells or malignant tumor cells. Gallium-67 scintigraphy is useful for examination of heart disease including cardiac sarcoidosis and acute myocarditis","pyqMatches":[{"year":"2016","no":1744,"q":"Acute myocarditis schintigraphy is done with","o":["Thallium","Technetium","Gallium","None"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8863, 'Radiology', 'Imaging Principles & Contrast', 'Hard', 'Radiology', 166, '{"id":8863,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Hard","source":"Radiology","sourceNo":166,"q":"Radiation used most commonly for pain management due to bone metastasis is -","o":["Co60","Iridium 192","Tritium","Tin-117"],"a":0,"e":"Answer- A. Co60 Radiopharmaceuticals (radioactive isotopes) used for metastatic bone pain are strontium (Sr89), Samarium (Sm153), rhenium (Re186), Phosphorus-32 and Tin-117 (Sn-177).","pyqMatches":[{"year":"2016","no":1745,"q":"Radiation used most commonly for pain management due to bone metastasis is","o":["Co60","Iridium 192","Tritium","Tin-117"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8864, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 167, '{"id":8864,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":167,"q":"Minimum radiation dose which may lead to oligospermia is -","o":["<1 Gy","2-3 Gy","7-10 Gy","15 Gy"],"a":0,"e":"Answer- A. <1 Gy Fractionated doses 0.7-0.9 Gy lead to oligospermia/azoospermia but with frequent recovery at 1-1.5 years. Permanent azoospermia may occur after fractionated doses as low as 1.2 Gy, and is likely >2 Gy.","pyqMatches":[{"year":"2016","no":1746,"q":"Minimum radiation dose which may lead to oligospermia is","o":["<1 Gy","2-3 Gy","7-10 Gy","15 Gy"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8865, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 168, '{"id":8865,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":168,"q":"Half life of tritium is -","o":["10.2 years","12.3 years","15.5 years","20.7 years"],"a":1,"e":"Answer- B. 12.3 years Tritium (hydrogen-3) is a radioactive isotope of hydrogen. The nucleus of tritium (sometimes called a triton) contains one proton and two neutrons. Whereas the nucleus of protium contains one proton and no neutrons. Tritium has a half-life of 12.3 years","pyqMatches":[{"year":"2016","no":1748,"q":"Half life of tritium is","o":["10.2 years","12.3 years","15.5 years","20.7 years"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8866, 'Radiology', 'Chest Radiology', 'Easy', 'Radiology', 169, '{"id":8866,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Easy","source":"Radiology","sourceNo":169,"q":"Safe light in radiographic dark room is ideally should be of following color -","o":["Red","Yellow","Purple","Blue"],"a":0,"e":"Answer- A. Red Red- Some blue sensitive materials, most phototypesetting materials, most blue and most green sensitive medical x-ray films (used in darkroom). Dark amber- Color negative papers and materials, panchromatic black and white papers. Amber- Color negative papers, panchromatic black and white papers","pyqMatches":[{"year":"2016","no":1751,"q":"Safe light in radiographic dark room is ideally should be of following color","o":["Red","Yellow","Purple","Blue"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8867, 'Radiology', 'Chest Radiology', 'Easy', 'Radiology', 170, '{"id":8867,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Easy","source":"Radiology","sourceNo":170,"q":"Least penetrating power among following mentioned rays is in -","o":["Alpha rays","Beta rays","Gamma rays","X-ray"],"a":0,"e":"Answer- A. Alpha rays Penetration power : Gamma rays> X rays > Beta particle > Alpha particle (or helium ion) Ionizing & damaging power : Alpha particle (or helium ion) > Beta particle > X ray> Gamma ray Alpha particles (Helium nuclei) have highest ionizing power because they have a large charge. Alpha particles have the highest damaging power as they are relatively slow and heavy.","pyqMatches":[{"year":"2016","no":1755,"q":"Least penetrating power among following mentioned rays is in","o":["Alpha rays","Beta rays","Gamma rays","X-ray"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8868, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 171, '{"id":8868,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":171,"q":"Non - ionizing radiation among the following is -","o":["MRI","CT Scan","X-ray","Position emission scintigraphy"],"a":0,"e":"Answer- A. MRI Non- ionizing radiation- USG MRI Thermography (infrared rays) UV rays Radiofrequency waves Microwaves","pyqMatches":[{"year":"2016","no":1756,"q":"Non - ionizing radiation among the following is","o":["MRI","CT Scan","X-ray","Position emission scintigraphy"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8869, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 172, '{"id":8869,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":172,"q":"Mechanism of heat loss in modern X-ray tube is","o":["Radiation","Evaporation","Conduction","Convection"],"a":0,"e":"Ans. A. Radiation The mechanism of heat loss in the modern X-ray tube is radiation. Classical X-ray tube: The outer tube is made up of glass. Cathode- tungsten filament. An anode is the target and is made of tungsten. The mechanism of heat loss is conduction. The atomic number of tungsten is 74. Modern X-ray tube: The outer tube is made up of stainless steel Cathode- tungsten + thorium Anode- tungsten + 10% rhenium. An anode is rotating and the mechanism of heat loss is radiation.","pyqMatches":[{"year":"2012","no":228,"q":"Mechanism of heat loss in modern X-ray tube is","o":["Radiation","Evaporation","Conduction","Convection"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8870, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 173, '{"id":8870,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":173,"q":"Nonionic dye is","o":["Ioxaglate","lohexol","Iothalamate","None"],"a":1,"e":"Answer- B. Iohexol Iohexol is a nonionic monomer contrast agent. The non-iodine radicals at positions 1, 3 and 5 (including the ionic carboxyl radical) were replaced by long amino hydrocarbons that provide adequate solubility without ionizing. Examples of this type of compound are iopromide, iohexol, iopamidol, ioversol, iopentol, iobitridol, and iomeprol.","pyqMatches":[{"year":"2012","no":1417,"q":"Nonionic dye is","o":["Ioxaglate","lohexol","Iothalamate","None"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8871, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 174, '{"id":8871,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":174,"q":"HU is measure of","o":["CT","MRI","PET","USG"],"a":0,"e":"Answer- A. CT Hounsfield''s contribution is memorialized in the Hounsfield scale, which is used to measure the x-ray attenuation in CT scanning. Water is arbitrarily assigned a value of 0 Hounsfield units (HU). [Ref Essential radiology p. 86]","pyqMatches":[{"year":"2012","no":1418,"q":"HU is measure of","o":["CT","MRI","PET","USG"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8872, 'Radiology', 'Musculoskeletal Radiology', 'Easy', 'Radiology', 175, '{"id":8872,"subject":"Radiology","chapter":"Musculoskeletal Radiology","difficulty":"Easy","source":"Radiology","sourceNo":175,"q":"Which looks same on Ti & T2 on MRI","o":["Gall bladder","Fat","Kidney","CSF"],"a":1,"e":"Answer- B. Fat Fat (adipose tissue) has high signal intensity on both T1 & T2 images. Other three options have low signal intesity on T1 and high signal intensity on T2 images.","pyqMatches":[{"year":"2012","no":1420,"q":"Which looks same on Ti & T2 on MRI","o":["Gall bladder","Fat","Kidney","CSF"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8873, 'Radiology', 'Chest Radiology', 'Moderate', 'Radiology', 176, '{"id":8873,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Moderate","source":"Radiology","sourceNo":176,"q":"Hypertranslucent chest X-ray is seen in all except","o":["Mcleod syndrome","Emphysema","Pneumonectomy","Poland syndrome"],"a":2,"e":"Answer- C. Pneumonectomy Causes of opaque hemithorax Technical : - Rotation, Scoliosis. Pleural : - Pleural effusion, Pleural thickening, Mesothelioma. Surgical : - Pneumonectomy, Thoracoplasty. Congenital : - Pulmonary agenesis. Mediastinal : - Gross cardiomegaly, tumors. Pulmonary : - Collapse, Consolidation, fibrosis, Foreign body. Diaphragmatic hernia","pyqMatches":[{"year":"2012","no":1422,"q":"Hypertranslucent chest X-ray is seen in all except","o":["Mcleod syndrome","Emphysema","Pneumonectomy","Poland syndrome"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8874, 'Radiology', 'Chest Radiology', 'Moderate', 'Radiology', 177, '{"id":8874,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Moderate","source":"Radiology","sourceNo":177,"q":"What is not seen on chest X-ray in pulmonary artery hypertension","o":["Enlargement of central arteries","Peripheral prunning","Narrowing of central arteries","None"],"a":2,"e":"Answer- C. Narrowing of central arteries Characteristic radiological feature of pulmonary hypertension is enlargement of central arteries with peripheral prunning. Increased pulmonary artery pressure and pulmonary vascular resistance characterize pulmonary hypertension. PAH is defined as systolic pressure in the pulmonary artery exceeding 30 mm Hg.","pyqMatches":[{"year":"2012","no":1423,"q":"What is not seen on chest X-ray in pulmonary artery hypertension","o":["Enlargement of central arteries","Peripheral prunning","Narrowing of central arteries","None"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8875, 'Radiology', 'Chest Radiology', 'Easy', 'Radiology', 178, '{"id":8875,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Easy","source":"Radiology","sourceNo":178,"q":"Colon is identified on X-ray","o":["Haustra","Valvulae conniventes","String of beads sign","More number of loops"],"a":0,"e":"Answer- A. Haustra Haustra (incomplete band across the bowel gas shadow) are seen in colon.","pyqMatches":[{"year":"2012","no":1427,"q":"Colon is identified on X-ray","o":["Haustra","Valvulae conniventes","String of beads sign","More number of loops"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8876, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 180, '{"id":8876,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":180,"q":"Investigation of choice for multiple sclerosis","o":["CT","MRI","USG","PET"],"a":1,"e":"Answer- B. MRI MRI is the investigation of choice for demyelinating disorder, e.g. multiple sclerosis.","pyqMatches":[{"year":"2012","no":1431,"q":"Investigation of choice for multiple sclerosis","o":["CT","MRI","USG","PET"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8877, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 181, '{"id":8877,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":181,"q":"Investigation of choice for intramedullary SOL is -","o":["MRI","USG","CT","X-ray"],"a":0,"e":"Answer- A. MRI Investigation of choice for intramedullary space occupy lesion is MRI.","pyqMatches":[{"year":"2012","no":1432,"q":"Investigation of choice for intramedullary SOL is","o":["MRI","USG","CT","X-ray"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8878, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 182, '{"id":8878,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":182,"q":"Von Rosen''s view is for","o":["CDH","Perthe''s disease","CTEV","None"],"a":0,"e":"Answer- A. CDH In Von Rosen''s view is used in DDH/CDH.","pyqMatches":[{"year":"2012","no":1437,"q":"Von Rosen''s view is for","o":["CDH","Perthe''s disease","CTEV","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8879, 'Radiology', 'Musculoskeletal Radiology', 'Easy', 'Radiology', 183, '{"id":8879,"subject":"Radiology","chapter":"Musculoskeletal Radiology","difficulty":"Easy","source":"Radiology","sourceNo":183,"q":"Nuchal translucency is used in","o":["Head scan","MRI neck","ANC USG","Anthropometry"],"a":2,"e":"Answer- C. ANC USG Nuchal translucency is used for screening of down syndrome in antenatal USG.","pyqMatches":[{"year":"2012","no":1439,"q":"Nuchal translucency is used in","o":["Head scan","MRI neck","ANC USG","Anthropometry"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8880, 'Radiology', 'Miscellaneous', 'Easy', 'Radiology', 184, '{"id":8880,"subject":"Radiology","chapter":"Miscellaneous","difficulty":"Easy","source":"Radiology","sourceNo":184,"q":"Half-life of Iodine 131 is","o":["8 hours","8 days","8 weeks","8 months"],"a":1,"e":"Answer- B. 8 days Iodine - 131 Half life 8 days Iodine - 123 -3 Half life 13 hours Iodine - 132 Half life 2.3 hours","pyqMatches":[{"year":"2012","no":1440,"q":"Half-life of Iodine 131 is","o":["8 hours","8 days","8 weeks","8 months"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8881, 'Radiology', 'Imaging Principles & Contrast', 'Hard', 'Radiology', 185, '{"id":8881,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Hard","source":"Radiology","sourceNo":185,"q":"Dye used in diagnosis of esophageal perforation:","o":["Iohexol","Barium sulphate","Gadolinium","Iodine dye"],"a":1,"e":"Answer-B. Barium sulphate Barium sulfate in suspension is frequently used medically as a radiocontrast agent for X-ray imaging and other diagnostic procedures. It is most often used in imaging of the GI tract during what is colloquially known as a \"barium meal\". Fluoroscopy most sensitive within the first 24 hours. patient examined semi-supine (~20 degrees) on fluoroscopy table a water-soluble agent should be used initially as barium can cause mediastinitis esophageal perforation may be represented as mucosal irregularity or gross extraluminal contrast extravasation some authors suggest the use of small amounts of low or high concentrations of barium if no leak is evident on initial screening with water soluble contrast Iohexol, trade names Omnipaque among others, is a contrast agent used during X-rays.This includes when visualizing arteries, veins, ventricles of the brain, the urinary system, and joints, as well as during computer tomography. It is given by mouth, injection into a vein, or into a body cavity.","pyqMatches":[{"year":"2017","no":219,"q":"Dye used in diagnosis of esophageal perforation:","o":["Iohexol","Barium sulphate","Gadolinium","Iodine dye"],"a":1,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":197,"q":"Dye used in diagnosis of esophageal perforation:","o":["Iohexol","Barium sulphate","Gadolinium","Iodine dye"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8882, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 186, '{"id":8882,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":186,"q":"Bragg peak effect pronounced in:","o":["X ray","Proton","Neutron","Electron"],"a":1,"e":"Answer- B. Proton Nowadays proton therapy (PT) represents an established alternative to photon radiotherapy for the treatment of specific types of cancer. The therapeutic use of proton beams (and of charged particles in general) is motivated primarily by their inverted depth-dose profile compared to photons, being characterized by the so-called Bragg peak. Several beams of different energy can then be combined in order to achieve the prescribed dose in a region as large as the target volume, resulting in the production of what is defined as the Spread- Out Bragg Peak (SOBP).","pyqMatches":[{"year":"2017","no":220,"q":"Bragg peak effect pronounced in:","o":["X ray","Proton","Neutron","Electron"],"a":1,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":198,"q":"Bragg peak effect pronounced in:","o":["X ray","Proton","Neutron","Electron"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8883, 'Radiology', 'Chest Radiology', 'Easy', 'Radiology', 187, '{"id":8883,"subject":"Radiology","chapter":"Chest Radiology","difficulty":"Easy","source":"Radiology","sourceNo":187,"q":"Salt and Pepper pot appearance of skull seen in:","o":["Hyperparathyroidism","Multiple myeloma","Hyperthyroidism","Pseudo hyperparathyroidism"],"a":0,"e":"Answer- A. Hyperparathyroidism Pepperpot skull is occasionally used in place of salt and pepper skull to describe the typical radiographic appearance of multiple small radiolucent lesions of the skull vault. In primary hyperparathyroidism, extensive resorption bone in the skull in combination with cystic areas of osteopenia are termed pepper pot skull. Classically seen in hyperparathyroidism, and is occasionally used (inaccurately) to describe the raindrop skull of multiple myeloma. : Sull X-ray with a typical \"pepper-pot\" appearance","pyqMatches":[{"year":"2017","no":221,"q":"Salt and Pepper pot appearance of skull seen in:","o":["Hyperparathyroidism","Multiple myeloma","Hyperthyroidism","Pseudo hyperparathyroidism"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":199,"q":"Salt and Pepper pot appearance of skull seen in:","o":["Hyperparathyroidism","Multiple myeloma","Hyperthyroidism","Pseudo hyperparathyroidism"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8884, 'Radiology', 'Ultrasound & Doppler', 'Moderate', 'Radiology', 188, '{"id":8884,"subject":"Radiology","chapter":"Ultrasound & Doppler","difficulty":"Moderate","source":"Radiology","sourceNo":188,"q":"Imaging techniques used in Uterus anomalies EXCEPT:","o":["HSG","MRI guided HSG","CT guided HSG","USG"],"a":2,"e":"Answer C. CT guided HSG Imaging studies, such as a hysterosalpingogram (HSG) and ultrasound, or an MRI are required to visualise the uterus and confirm that a congenital uterine anomaly is present. A hysterosalpingogram is not considered as useful due to the inability of the technique to evaluate the exterior contour of the uterus and distinguish between a bicornuate and septate uterus. In addition,laparoscopy and/orhysteroscopy may be indicated.","pyqMatches":[{"year":"2018","no":200,"q":"Imaging techniques used in Uterus anomalies EXCEPT:","o":["HSG","MRI guided HSG","CT guided HSG","USG"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8885, 'Radiology', 'Imaging Principles & Contrast', 'Easy', 'Radiology', 189, '{"id":8885,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Easy","source":"Radiology","sourceNo":189,"q":"Which is the treatment of choice for irradiation in Chordoma?","o":["Protons","Electrons","Gamma radiation","3D - CRT"],"a":0,"e":"Answer: A - Proton Therapy Chordoma: Slow-growing neoplasm Arising from cellular remnants of notochord. Arise from bone in skull base and along spinal cord. Most common locations - Cranially at clivus In sacrum at bottom of spine Radiation therapy: Are relatively radioresistant High doses of radiation required to control. Hence, high focus radiation like proton therapy and carbon ion therapy are preferred than conventional radiation methods. Close proximity to vital structures like brain stem, requires high precision and accuracy for any planned surgical resection. Radiation with high accuracy and minimal damage with maximal safety is delivered.","pyqMatches":[{"year":"2018","no":276,"q":"Which is the treatment of choice for irradiation in Chordoma?","o":["Protons","Electrons","Gamma radiation","3D - CRT"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8886, 'Radiology', 'Imaging Principles & Contrast', 'Hard', 'Radiology', 190, '{"id":8886,"subject":"Radiology","chapter":"Imaging Principles & Contrast","difficulty":"Hard","source":"Radiology","sourceNo":190,"q":"Cancer patient undergoes radiotherapy, pick the true statement for radiosensitivity of tissues?","o":["Rapidly dividing cells are resistant to radiation","GI mucosa is one of the most radioresistant tissues in the body","The intensity of radiation is inversely proportional to the square of distance from the source","Small blood vessels are least resistant to radiation"],"a":2,"e":"Answer- C- The intensity of radiation is inversely proportional to the square of distance from the source The inverse square law describes the principle of dose reduction as the distance from the source increases. The dose is proportional to the inverse of the square of the radius. Thus if you double the distance you reduce the dose by a factor of four. Ref- 1. Shafiei SA, Hasanzadeh H, Shafiei SA. A simple calculation method for determination of equivalent square field. J Med Phys. 2012;37 (2): 107-11. DOI:10.4103/0971- 6203.94746 - Free text at PubMed - Pubmed citation","pyqMatches":[{"year":"2020","no":235,"q":"Cancer patient undergoes radiotherapy, pick the true statement for radiosensitivity of tissues?","o":["Rapidly dividing cells are resistant to radiation","GI mucosa is one of the most radioresistant tissues in the body","The intensity of radiation is inversely proportional to the square of distance from the source","Small blood vessels are least resistant to radiation"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8887, 'Surgery', 'Transplantation', 'Hard', 'Surgery', 1, '{"id":8887,"subject":"Surgery","chapter":"Transplantation","difficulty":"Hard","source":"Surgery","sourceNo":1,"q":"Post-transplantation hypertension can be caused by:I. Rejection. II. Cyclosporine nephrotoxicity.III. Renal transplant artery stenosis (RTAS).IV. Recurrent disease in the allograft.","o":["I,II,III,IV are correct","I,II,IV are correct.","I & III are correct","None of the above is correct."],"a":0,"e":"Both acute and chronic rejection may result in hypertension. The former causes acute fluid retention and plugging of peritubular capillaries with inflammatory cells. This may progress to intimal swelling and medial necrosis and eventuate in ischemia secondary to endothelial proliferation and obliteration of small vessels. Chronic rejection, thought to be related to protracted humoral injury, results in obliteration of capillaries via the development of intimal hyperplasia. Cyclosporine has a vasoconstrictive effect which, through activation of the renin-angiotensin system, may lead to hypertension. RTAS is responsible for hypertension in 4% to 12% of renal allograft recipients. It responds well to percutaneous angioplasty. A careful trial of angiotensin-converting enzyme inhibitors may be diagnostic of RTAS. Recurrent disease such as membranoproliferative glomerulonephritis and focal glomerular sclerosis may result in significant hypertension in renal allograft recipients.","pyqMatches":[{"year":"2015","no":603,"q":"Post-transplantation hypertension can be caused by:I. Rejection. II. Cyclosporine nephrotoxicity.III. Renal transplant artery stenosis (RTAS).IV. Recurrent disease in the allograft.","o":["I,II,III,IV are correct","I,II,IV are correct.","I & III are correct","None of the above is correct."],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8888, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 2, '{"id":8888,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":2,"q":"Most common cause of small intestine obstruction is?","o":["Intussception","Idiopathic adhesions Tumors","Tumors","Postoperative adhesions"],"a":3,"e":"Postoperative adhesions REF: Bailey & Love 25th edition page 1188, http://emedicine.medscape.com/article/774140​overview \"The most common cause of small-bowel obstruction (SBO) is postsurgical adhesions\" The most common causes of intestinal obstruction in adults are: Intestinal adhesions — bands of fibrous tissue in the abdominal cavity that can form after abdominal or pelvic surgery In children, the most common cause of intestinal obstruction is telescoping of the intestine (intussusception).","pyqMatches":[{"year":"2014","no":1576,"q":"Most common cause of small intestine obstruction is?","o":["Intussception","Idiopathic adhesions Tumors","Tumors","Postoperative adhesions"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8889, 'Surgery', 'Hepatobiliary & Pancreas', 'Easy', 'Surgery', 3, '{"id":8889,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Easy","source":"Surgery","sourceNo":3,"q":"Best method to treat a large port-wine hemangioma is?","o":["Radiotherapy","Tatooing","Excision with skin grafting","Pulsed dye Laser"],"a":3,"e":"Pulsed dye Laser REF: Roxburgh''s common Skin Diseases 17th edition page 194 & 205, Clinical Dermatology by John Hunter, John Savin & Mark Dahl 3'' edition page 275 \"Selective Photothermolysis or Pulsed dye laser is the treatment of choice for Portwine hemangioma\" Port-wine stains are crimson blotches in which there is marked capillary dilatation compared to a capillary angioma, which is a red nodule or plaque containing proliferating endothelial cells. The latter tend to flatten and disappear at puberty. Larger ones may cause problems from bleeding and/or erosion. Cavernous haemangiomata are larger and compressible, containing large vascular spaces. Occasionally a port-wine stain of the trigeminal area is associated with a vascular malformation of the leptomeninges on the same side, which may cause epilepsy or hemiparesis (the Sturge​Weber syndrome), or with glaucoma. Excellent results have been obtained with careful and time- consuming treatment with a 585-nm flashlamp-pumped pulsed dye laser. Treatment sessions can begin in babies and anaesthesia is not always necessary. If a trial patch is satisfactory, 40-50 pulses can be delivered in a session and the procedure can be repeated at 3-monthly intervals.","pyqMatches":[{"year":"2012","no":1101,"q":"Best method to treat a large port-wine hemangioma is?","o":["Radiotherapy","Tatooing","Excision with skin grafting","Pulsed dye Laser"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8890, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 4, '{"id":8890,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":4,"q":"Cock''s peculiar tumor is","o":["Basal cell CA","Squamous cell CA","Ulcerated sebaceous cyst","Cylindroma"],"a":2,"e":"Ulcerated sebaceous cyst [Ref. Love & Bailey 23/e page 173, 595; Das text book of Surgery3/e p81] Repeat from May 04 Cock''s peculiar tumour is a sebaceous cyst linked growth that can resemble a squamous cell carcinoma. The proliferating cyst is usually solitary, but it often arises from a simple trichilemmal cysts in the hair follicle epithelium.","pyqMatches":[{"year":"2014","no":1519,"q":"Cock''s peculiar tumor is","o":["Basal cell CA","Squamous cell CA","Ulcerated sebaceous cyst","Cylindroma"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8891, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 5, '{"id":8891,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":5,"q":"False about Gastric lymphoma is:","o":["Stomach is the most common site","Asosciate with H. pylori infection","Total gastrectomy with adjuvant chemotherapy is the treatment of choice","5 yr survival rate after treatment is 60%."],"a":2,"e":"Total gastrectomy with adjuvant chemotherapy is the treatment of choice [Ref: Sabiston 18/e p1269 (17/c p1312); Harrison 17/e, p 573; Schwartz 9/e p935 (8/e, p981)] Stomach is the most common extranodal site of lymphoma. It is of two types - Primary & Secondary Primary gastric lymphoma - is lymphoma of the stomach which exhibits no evidence of liver, spleen, mediastinal lymph nodes or bone marrow involvement at the time of diagnosis (regional lymph node involvement may be present) Primary gastric lymphoma is mainly (>95%) Non-Hodgkin''s lymphoma of B cell origin. Most of the primary lymphomas (about 60%) arise in MALT (mucosa associated lymphoid tissue). MALT is usually associated with chronic H. pylori infection. So low-grade MALT lymphomas are thought to arise because of chronic H. pylori infection. These low grade lymphomas may later on degenerate to high grade lymphomas Immunodeficiency and H. pylori infection are risk factors for B cell lymphoma. Most common site of involvement (like that of adenocarcinoma) is gastric antrum. Secondary gastric lymphoma Stomach is the most common extranodal site of systemic lymphoma. Almost all of them are Non-Hodgkins types Treatment The role of gastric resection is controversial. Recent studies have shown similar disease free 5 year survival rates in patients treated with surgery+chemotherapy+radiotherapy and patients treated with chemotherapy+ radiation therapy alone. (Most patients with high grade gastric lymphomas are now treated with chemoradiation alone, without surgical resection. For disease limited to the stomach and regional nodes, radical subtotal gastrectomy may be performed, especially for bulky tumors with bleeding and/or obstruction.) Most common chemotherapeutic regimen is – CHOP plus rituximab [CHOP stands for cyclophosphamide, doxorubicin,vincristine,& prednisone] about option d i.e. (5 yr survival rate after treatment is 60%.) Harrison 17/e writes- \"Subtotal gastrectomy, usually followed by combination chemotherapy, has led to 5-year survival rates of 40- 60% in patients with localized high-grade lymphomas.\"","pyqMatches":[{"year":"2015","no":1297,"q":"False about Gastric lymphoma is:","o":["Stomach is the most common site","Asosciate with H. pylori infection","Total gastrectomy with adjuvant chemotherapy is the treatment of choice","5 yr survival rate after treatment is 60%."],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8892, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 6, '{"id":8892,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":6,"q":"Which one of the following preservative is used while packing catgut suture?","o":["Isopropyl alcohol","Colloidal iodine","Glutaraldehyde","Hydrogen peroxide"],"a":0,"e":"10% isopropyl alcohol is the routine packing fluid used in packing catgut sutures. Catgut is available in glass tubes containing isopropyl alcohol and small quantity of water. Catgut is prepared from the intestine of sheep. Ref: Pharmaceutics By Dr. R. S. Gaud, Page 196; Veterinary Medicine/small animal clinician, Volume 72, Issues 1-6, Page 835.","pyqMatches":[{"year":"2013","no":1395,"q":"Which one of the following preservative is used while packing catgut suture?","o":["Isopropyl alcohol","Colloidal iodine","Glutaraldehyde","Hydrogen peroxide"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8893, 'Surgery', 'Endocrine Surgery', 'Moderate', 'Surgery', 7, '{"id":8893,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":7,"q":"Primary hyperparathyroidism, phaeochromocytoma may be associated with which type of thyroid cancer?","o":["Medullary carcinoma of the thyroid","Papillary carcinoma of the thyroid","Anaplastic carcinoma of the thyroid","Follicular carcinoma of the thyroid"],"a":0,"e":"It is characterized clinically by medullary thyroid carcinoma (MTC), pheochromocytoma, and hyperparathyroidism. Approximately 70- 95% of individuals with MEN 2A develop MTC, 50% develop pheochromocytoma, and 15-30% develop hyperparathyroidism. Ref: Bailey and Love’s Short Practice of Surgery, 24th Edition, Page 802; Harissons Internal Medicine, 18th Edition, Chapter 351.","pyqMatches":[{"year":"2015","no":494,"q":"Primary hyperparathyroidism, phaeochromocytoma may be associated with which type of thyroid cancer?","o":["Medullary carcinoma of the thyroid","Papillary carcinoma of the thyroid","Anaplastic carcinoma of the thyroid","Follicular carcinoma of the thyroid"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8894, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 8, '{"id":8894,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":8,"q":"The treatment of choice for squamous cell anal cancer?","o":["Laser fulgaration","Chemoradiotherapy","Abdominoperennial resection","Platinum-based chemotherapy"],"a":1,"e":"Squamous cell anal cancer is rare but associated with Human papilloma virus infection (HPV), Anal intra-epithelial neoplasia (AIN) and immunosuppression. The current treatment of anal canal carcinoma is chemoradiotherapy (combined modality therapy). Chemotherapy include a combination of 5-FU with mitomycin C or Cisplatin. Ref: Bailey and Love Short Practice of Surgery, 25th Edition, Page 1269; The MD Anderson Manual of Medical Oncology, 2nd Edition, Chapter 22.","pyqMatches":[{"year":"2013","no":1362,"q":"The treatment of choice for squamous cell anal cancer?","o":["Laser fulgaration","Chemoradiotherapy","Abdominoperennial resection","Platinum-based chemotherapy"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8895, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 9, '{"id":8895,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":9,"q":"Meconium ileus is associated with:","o":["Cystic fibrosis","Infant of diabetic mother","Hypothyroidism","None of the above"],"a":0,"e":"Infants with cystic fibrosis have characteristic pancreatic enzyme deficiencies and abnormal chloride secretion in the intestine that result in the production of viscous, water-poor meconium. Meconium ileus occurs when this thick, highly viscous meconium becomes impacted in the ileum and leads to high-grade intestinal obstruction. Ref: Schwartz’s principle of surgery 9th edition, chapter 39.","pyqMatches":[{"year":"2016","no":1365,"q":"Meconium ileus is associated with:","o":["Cystic fibrosis","Infant of diabetic mother","Hypothyroidism","None of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8896, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 10, '{"id":8896,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":10,"q":"Commonest type of anal canal carcinoma is?","o":["Squamous cell carcinoma","Adenocarcinoma","Adenoacanthoma","Papillary type"],"a":0,"e":"Squamous cell carcinoma is the most common type of anal cancer. This cancer begins in the outer lining of the anal canal. Mainly three types of malignant neoplasm are seen in anal canal Squamous cell carcinoma (most common) Basal cell carcinoma (2nd most common) Melanoma Also remember: Most common type of rectal and colon cancer Adenocarcinoma Ref: S. Das textbook of surgery 3/e, Page 1078.","pyqMatches":[{"year":"2014","no":1529,"q":"Commonest type of anal canal carcinoma is?","o":["Squamous cell carcinoma","Adenocarcinoma","Adenoacanthoma","Papillary type"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8897, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 11, '{"id":8897,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":11,"q":"Which of the following nerve is commonly damaged during McBurney''s incision?","o":["Subcostal nerve","10th thoracic nerve","11th thoracic nerve","Iliohypogastric nerve"],"a":3,"e":"The nerve commonly damaged during McBurney''s incision is Iliohypogastric Nerve. Damage to this nerve result in the development of right inguinal hernia. Mc Burney’s incision/ grid iron incision is commonly done for appendectomy. In this an oblique incision is made in the right iliac fossa about 5cm above and medial to the anterior superior iliac spine at right angle to the spino umbilical line. Ref: Anatomy of Abdomen and Lower Limb By Singh, Page 46.","pyqMatches":[{"year":"2013","no":1401,"q":"Which of the following nerve is commonly damaged during McBurney''s incision?","o":["Subcostal nerve","10th thoracic nerve","11th thoracic nerve","Iliohypogastric nerve"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8898, 'Surgery', 'Vascular Surgery', 'Easy', 'Surgery', 12, '{"id":8898,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Easy","source":"Surgery","sourceNo":12,"q":"Dysphagia lusoria is due to?","o":["Esophageal diverticulum","Aneurysm of aorta","Esophageal web","Compression by aberrant blood vessel"],"a":3,"e":"Dysphagia lusoria is a disorder of swallowing caused due to vascular anomalies and includes: A right aortic arch A double aortic arch A vascular constricting ring formed by a PDA or a ligamentum arteriosum and pulmonary artery or aortic arch An abnormal right subclavian artery An abnormal innominate artery Diagnosis is made by lipoidal swallow or arteriography. Ref: Bailey and Love 24/e, Page 995","pyqMatches":[{"year":"2014","no":1543,"q":"Dysphagia lusoria is due to?","o":["Esophageal diverticulum","Aneurysm of aorta","Esophageal web","Compression by aberrant blood vessel"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8899, 'Surgery', 'Hepatobiliary & Pancreas', 'Moderate', 'Surgery', 13, '{"id":8899,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Moderate","source":"Surgery","sourceNo":13,"q":"All of the following are causes of hemobilia, EXCEPT:","o":["Trauma to Abdomen","Malignancy","Rupture of hepatic artery aneurysm","Hepatitis"],"a":3,"e":"Hemobilia presents with the triad of biliary colic, obstructive jaundice, and occult or gross intestinal bleeding. Causes are, Hepatic trauma Ductal parasitism (Ascaris lumbricoides) Oriental cholangiohepatitis Hepatic neoplasms Rupture of a hepatic artery aneurysm Hepatic abscess Choledocholithiasis The diagnosis may be suspected from a technetium-99m-labeled red blood cell scan, but an arteriogram is usually required for diagnosis and planning of therapy. Ref: Doherty G.M. (2010). Chapter 25. Biliary Tract. In G.M. Doherty (Ed), CURRENT Diagnosis & Treatment: Surgery, 13e.","pyqMatches":[{"year":"2013","no":1403,"q":"All of the following are causes of hemobilia, EXCEPT:","o":["Trauma to Abdomen","Malignancy","Rupture of hepatic artery aneurysm","Hepatitis"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8900, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 14, '{"id":8900,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":14,"q":"Linitis plastica is a type of :","o":["Gastric ulcer","Ca stomach","Duodenal ulcer","None of the above"],"a":1,"e":"Linitis plastica is a type of adenocarcinoma. Adenocarcinoma is the most common form of stomach cancer. Linitis plastica spreads to the muscles of the stomach wall and makes it thicker and more rigid. Linitis plastica is a subtype of gastric cancer that is characterized by diffuse infiltrating adenocarcinoma without obvious carters and ulcers. It is thought to originate from parietal cell portion of gastric mucosa. Because of its diffuse nature ,this form of gastric cancer ususally involves the whole stomach. Ref : Clinical Scenarios in Surgical Oncology edited by Vijay P. Khatri","pyqMatches":[{"year":"2013","no":468,"q":"Linitis plastica is a type of ?","o":["Plastic like lining of stomach","Diffuse carcinoma of stomach","Benign ulcer","GIST"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":1538,"q":"Linitis plastica is a type of :","o":["Gastric ulcer","Ca stomach","Duodenal ulcer","None of the above"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8901, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 15, '{"id":8901,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":15,"q":"Surgery for undescended testis is recommended at what age?","o":["6 months","12 months","24 months","36 months"],"a":0,"e":"Optimum age for surgery in case of undescended testis is 6 months. The surgical procedure done is called orchidopexy. Earlier intervention (Six months of age) should be considered in order to theoretically prevent the complications of crytorchidism that may be manifested before 1 year of age. Ref: Nursing care of the pediatric surgical patient By Nancy Tkacz Browne, Page 147-8; CPDT, 20th Edition, Page 974; Campbell''s Urology, 9th Edition, Page 3775","pyqMatches":[{"year":"2015","no":1223,"q":"Surgery for undescended testis is recommended at what age?","o":["6 months","12 months","24 months","36 months"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8902, 'Surgery', 'Urology', 'Hard', 'Surgery', 16, '{"id":8902,"subject":"Surgery","chapter":"Urology","difficulty":"Hard","source":"Surgery","sourceNo":16,"q":"A patient who has fallen over a loose manhole cover is brought to the clinic. On examination a perineal hematoma and blood in the external meatus is noted. Rupture of which of the following structure has resulted in perineal hematoma?","o":["Rupture of membranous urethra","Rupture of bulbar urethra","Pelvic organ blunt trauma","Rupture of bladder"],"a":1,"e":"The bulbar urethra is crushed upwards onto pubic bone, typically with significant bruising. Cycling accidents, loose manhole cover and gymnasium accidents astride the beam account for numbr of cases. CLINICAL FEATURES The signs of a ruptured bulbar urethra are perineal bruising and haematoma, typically with a butterfly distribution'' There is usually bleeding irom the urethral meatus and retenrion of urine is also typically present. Rupture of the membranous urethra typically occurs in association with a fractured pelvis and may be associated with an extraperitoneal rupture of the bladder. The most common causes of pelvic fracture are road traffic accidents, severe crush injuries and falls. The clinical fearures include urinary retention, blood at the urethral meatus. There is typically marked bruising of the pubic area, scrorum and penis.","pyqMatches":[{"year":"2013","no":1378,"q":"A patient who has fallen over a loose manhole cover is brought to the clinic. On examination a perineal hematoma and blood in the external meatus is noted. Rupture of which of the following structure has resulted in perineal hematoma?","o":["Rupture of membranous urethra","Rupture of bulbar urethra","Pelvic organ blunt trauma","Rupture of bladder"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8903, 'Surgery', 'Hepatobiliary & Pancreas', 'Easy', 'Surgery', 17, '{"id":8903,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Easy","source":"Surgery","sourceNo":17,"q":"Commonest carcinoma that can cause splenic metastasis is which of the following?","o":["Ca. Pancreas","Ca. Stomach","Ca. Ovary","Ca. Cervix"],"a":2,"e":"Although isolated metastasis to spleen is rare, studies found the most common primary neoplasms with splenic metastasis to be gynecologic (61%), with majority being ovarian, colorectal (15%), lung (9%), and stomach (4%). Ref: CT and MRI of the Abdomen and Pelvis: A Teaching File edited by Pablo R. Ros, Koenraad J. Mortele, 2006, Page 218.","pyqMatches":[{"year":"2016","no":476,"q":"Commonest carcinoma that can cause splenic metastasis is which of the following?","o":["Ca. Pancreas","Ca. Stomach","Ca. Ovary","Ca. Cervix"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8904, 'Surgery', 'Hepatobiliary & Pancreas', 'Easy', 'Surgery', 18, '{"id":8904,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Easy","source":"Surgery","sourceNo":18,"q":"Spleniculi are seen most commonly in:","o":["Colon","Hilum","Liver","Lungs"],"a":1,"e":"Spleniculi or accessory spleens are most commonly ( about 80% ) seen at the hilum of the spleen. Also know: Location of accessory spleen in decreasing order are: Splenic hilum Gastrocolic ligament Tail of pancreas Greater omentum Greater curvature of stomach Splenocolic ligament Small and large bowel mesentery Left broad ligament of women Left spermatic cord in men Ref: Schwartz 9/e, Page 1246; Bailey & Love 25/e, Page 25/e, Page 1103","pyqMatches":[{"year":"2015","no":155,"q":"Spleniculi are seen most commonly in:","o":["Colon","Hilum","Liver","Lungs"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8905, 'Surgery', 'Breast Surgery', 'Hard', 'Surgery', 19, '{"id":8905,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Hard","source":"Surgery","sourceNo":19,"q":"Which of the following stage of Breast Ca corresponds with following feature? Breast mass of 6 x 3 cm. size Ipsilateral supraclavicular lymph node Distant metastasis cannot be assessed","o":["T4 N3 MX","T4 N1 M1","T4 N0 M0","T3 N3c MX"],"a":3,"e":"According to TNM staging system for breast cancer, T3: Tumor >5 cm in greatest dimension N3c: Metastasis in ipsilateral supraclavicular lymph node(s) MX: Distant metastasis cannot be assessed Ref: Hunt K.K., Newman L.A., Copeland E.M., Bland K.I. (2010). Chapter 17. The Breast. In F.C. Brunicardi, D.K. Andersen, T.R. Billiar, D.L. Dunn, J.G. Hunter, J.B. Matthews, R.E. Pollock (Eds), Schwartz''s Principles of Surgery, 9e.","pyqMatches":[{"year":"2013","no":1383,"q":"Which of the following stage of Breast Ca corresponds with following feature? Breast mass of 6 x 3 cm. size Ipsilateral supraclavicular lymph node Distant metastasis cannot be assessed","o":["T4 N3 MX","T4 N1 M1","T4 N0 M0","T3 N3c MX"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8906, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 20, '{"id":8906,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":20,"q":"Dacron vascular graft is a:","o":["Textile biologic","Textile synthetic","Nontextile biologic","Nontextile synthetic"],"a":1,"e":"Dacron graft is a type of textile synthetic graft. It is associated with increased risk of thrombosis due to low flow rates. They are pre coated with collagen, which eliminates the need for pre-clotting. It is now reserved for aortic and high pressure, large diameter bypass grafts or used as aortic endografts. Ref: Diabetic Foot: Lower Extremity Arterial Disease and Limb Salvage, Anton N. Sidawy, 2006 Edition, Chapter 22, Page 234; Mastery of Vascular and Endovascular Surgery By Gerald B. Zelenock, 2006 Edition, Chapter 50, Page 414; Vascular Access: Principles and Practice By Samuel Eric Wilson, 5th Edition, Page 115; Vascular Surgery By Alun H. Davies, Page 135.","pyqMatches":[{"year":"2013","no":1348,"q":"Dacron vascular graft is a:","o":["Textile biologic","Textile synthetic","Nontextile biologic","Nontextile synthetic"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8907, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 21, '{"id":8907,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":21,"q":"The MOST common type of dislocation of elbow joint is:","o":["Posterior","Posterolateral","Posteromedial","Lateral"],"a":0,"e":"In adults, the elbow is the second most frequently dislocated major joint, after the shoulder. It is the most commonly dislocated joint in children. More than 90% of all elbow dislocations are posterior dislocations. This injury entails disengagement of the coronoid process of the ulna from the trochlea of the humerus with movement posteriorly. The mechanism of injury is typically a fall onto an outstretched hand with the elbow in extension upon impact.","pyqMatches":[{"year":"2012","no":1225,"q":"The MOST common type of dislocation of elbow joint is:","o":["Posterior","Posterolateral","Posteromedial","Lateral"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8908, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 22, '{"id":8908,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":22,"q":"Which of the following gas is most commonly used in laproscopy?","o":["CO2","N2O","O2","Helium"],"a":0,"e":"CO2 is used in laproscopy because it is common to the human body and can be absorbed by tissue and removed by the respiratory system. It is also non-flammable, which is important because electrosurgical devices are commonly used in laparoscopic procedures.","pyqMatches":[{"year":"2015","no":1298,"q":"Which of the following gas is most commonly used in laproscopy?","o":["CO2","N2O","O2","Helium"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8909, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 23, '{"id":8909,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":23,"q":"What is the most common position of appendix?","o":["Pelvic","Paracolic","Retrocaecal","Retroperitoneal"],"a":2,"e":"Retrocecal is the most common position of the appendix. Positions of appendix: Retrocecal: 74% Subcecal: 1.5% Pelvic: 21% Post-ileal: 0.5% Pre-ileal/retro-ileal: 1%","pyqMatches":[{"year":"2015","no":1266,"q":"What is the most common position of appendix?","o":["Pelvic","Paracolic","Retrocaecal","Retroperitoneal"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8910, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 24, '{"id":8910,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":24,"q":"Most common primary bone tumour of hand is:","o":["Osteoma","Osteochondroma","Enchondroma","None of the above"],"a":2,"e":"Enchondromas arise from cartilage and are the most common primary bone tumors of the hand. These lesions account for >90% of bone tumors seen in the hand. Ref: Schwartz’s principle of surgery 9th edition, chapter 44. Commonest bone malignancies -> Secondaries (metastases) Commonest primary malignant tumor > Multiple myeloma Commonest primary malignant tumor o long bones Osteosarcoma Commonest benign tumor of bonne - Osteochondroma (Osteochondroma is not ture neoplasm since its growth stops with cessation of growth at the epiphyseal plate) Commonest true benign tumor of bone -> Osteroid osteoma Commonest benign tumor of hand - Enchondroma","pyqMatches":[{"year":"2016","no":1469,"q":"Most common primary bone tumour of hand is:","o":["Osteoma","Osteochondroma","Enchondroma","None of the above"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8911, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'Surgery', 25, '{"id":8911,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":25,"q":"Which of the following Vitamin deficiency is seen in short bowel syndrome with ileal resection ?","o":["Vitamin K","Vitamin B 12","Vitamin B1","Folic acid"],"a":1,"e":"Answer- B (Vitamin B12) Short-bowel syndrome is a disorder clinically defined by malabsorption, diarrhea, steatorrhea, fluid and electrolyte disturbances, and malnutrition. Changes seen in Terminal Ileal Resection Malabsorption of bile salts and vitamin B12 (which are normally absorbed in this region) Vitamin B12 Malabsorption → Megaloblastic anemia Bile salts Malabsorption → Unabsorbed bile salts escape into the colon and stimulate fluid secretion from the colon → watery diarrhea Decreased bile salts in the bile → Cholesterol gall stones","pyqMatches":[{"year":"2015","no":1246,"q":"Which of the following Vitamin deficiency is seen in short bowel syndrome with ileal resection ?","o":["Vitamin K","Vitamin B 12","Vitamin B1","Folic acid"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8912, 'Surgery', 'Hepatobiliary & Pancreas', 'Easy', 'Surgery', 26, '{"id":8912,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Easy","source":"Surgery","sourceNo":26,"q":"Double bubble sign seen in :","o":["Duodenal atresia","Duodenal stenosis","Volvulus","All"],"a":3,"e":"Ans. is D ''a'', ''b'' & ''c'' i.e. Duodenal atresia, Duodenal stenosis and Volvulus Double bubble sign is seen in duodenal atresia, duodenal web, deudenal stenosis, Ladd''s band, Annular pancreas, Malrotation of gut, preduodenal vein. Distal gas is more often seen with midgut volvulus, duodenal stenosis and duodenal web","pyqMatches":[{"year":"2013","no":1775,"q":"Double bubble sign seen in :","o":["Duodenal atresia","Duodenal stenosis","Volvulus","All"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8913, 'Surgery', 'General Principles & Wounds', 'Moderate', 'Surgery', 27, '{"id":8913,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Moderate","source":"Surgery","sourceNo":27,"q":"In gastrectomy following occurs except -","o":["Calcium deficiency","Steatorrhoea","Fe. deficiency","Fluid loss"],"a":3,"e":"Answer is ''d'' i.e. Fluid loss Postgastrectomy complications Anemia as a result of vitamin B12 or iron malabsorption and osteoporosis. Iron deficiency anemia develops because removal of the stomach often leads to a marked decrease in the production of gastric acid. Osteoporosis develops as a result of poor calcium absorption, another problem that occurs after gastric surgery. Dumping syndrome Diarrhoea- may be due to different reasons. associated with dumping syndrome post-vagotomy diarrhoea associated with fat malabsorption. Fat malabsorption leading to steatorrhoea occurs due to acid inactivation of pancreatic enzymes or poorly coordinated mixing of food & digestive juices. Fat malabsorption leads to malabsorption of fat soluble vitamins i.e. A,D,E & K. Pushing food from your stomach to your small bowel too quickly (dumping syndrome) Acid reflux Chest infections, including bronchitis and pneumonia Internal bleeding Nausea and vomiting Stomach acid leaking into your esophagus, causing scarring and narrowing (stricture) Vitamin deficiencies Weight loss","pyqMatches":[{"year":"2012","no":1107,"q":"In gastrectomy following occurs except","o":["Calcium deficiency","Steatorrhoea","Fe. deficiency","Fluid loss"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8914, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'Surgery', 28, '{"id":8914,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":28,"q":"All of the following are features of Zollinger Ellison syndrome except","o":["Intractable peptic ulcers","Severe diarrhoea","Beta cell tumors of the pancreas","Very high acid output."],"a":2,"e":"Ans. is ''c'' i.e., Beta cell tumours of pancrease Gastrinoma or Zollinger Ellison syndrome is a non 13 cell neuroendocrine tumour of the pancreas It secretes gastrin Pathophysiology of Gastrinoma Gastrinoma —> Increase secretion of gastrin —> marked gastric acid hypersecretion peptic ulcer Pancreatic Neuroendocrine Tumors Tumour Biologically active peptide secreted Tumour location Malignant percentage Main symptoms and signs Gastrinoma (non 13 cell tumour) Gastrin Duodenum (70%) Pancreas (25%) other sites (5%) 60-90 - •Pain (79 100%) - ''Diarrhoea (30 73%) • GERD (30- 35%) • Peptic ulcer Insulinoma (f3 cell tumour) Insulin Pancreas > 99% (Insulinomas are distributed equally on head body and tail of pancrease) < 10 • Symptoms of hypoglycemia • Symptoms releive on administration of glucose VIPOMA (Verner- Morrison syndrome, pancreatic cholera, WDHA) Vasoactive intestinal peptide Pancreas 90% 40-70 • Watery diarrhoea (90-100%) • - Hypokalemia (80 100%) • Hypochlorhydria • Dehydration (83%) • Flushing (20%) Glucagonoma Glucagon Pancreas 100% (usually occursusuall singly in pancreatic tail) 50-80% • Dermatitis (migratory necrolytic erythema) 67-90% • Glucose intolerance (40-90%) • Weight loss (66 to 96%) • Anemia (33- 85%) • Diarrhoea (15- 29%) • Thromboembolism","pyqMatches":[{"year":"2015","no":1278,"q":"All of the following are features of Zollinger Ellison syndrome except","o":["Intractable peptic ulcers","Severe diarrhoea","Beta cell tumors of the pancreas","Very high acid output."],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8915, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 29, '{"id":8915,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":29,"q":"Curlings ulcer is seen in -","o":["Burn patients","Patients with head injuries","Zollinger Ellison syndrome","Analgesic drug abuse"],"a":0,"e":"Ans. is ''a'' i.e., Burn patients Curling ulcers: are stress ulcers associated with burns and most commonly found in the first part of duodenum.","pyqMatches":[{"year":"2014","no":1585,"q":"Curlings ulcer is seen in","o":["Burn patients","Patients with head injuries","Zollinger Ellison syndrome","Analgesic drug abuse"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8916, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 30, '{"id":8916,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":30,"q":"The most commonly practiced operative procedure for a perforated duodenal ulcer is -","o":["Vagotomy and pyloroplasty","Vagotomy and antrectomy","Vagotomy and perforation closure","Graham''s omentum patch repair"],"a":3,"e":"Ans. is ''d'' i.e., Graham''s omentum patch repair","pyqMatches":[{"year":"2016","no":1275,"q":"The most commonly practiced operative procedure for a perforated duodenal ulcer is","o":["Vagotomy and pyloroplasty","Vagotomy and antrectomy","Vagotomy and perforation closure","Graham''s omentum patch repair"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8917, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 31, '{"id":8917,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":31,"q":"Prepyloric or channel ulcer in the stomach is termed as -","o":["type 1","type 2","type 3","type 4"],"a":2,"e":"Ans. is ''c'' i.e., Type 3 . Situated in prepyloric region . Associated with gastric acid hypersecretion","pyqMatches":[{"year":"2013","no":1365,"q":"Prepyloric or channel ulcer in the stomach is termed as","o":["type 1","type 2","type 3","type 4"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8918, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 32, '{"id":8918,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":32,"q":"Commonest cause of pyogenic liver abscess ?","o":["Stricture of CBD","Biliary Colic","Appendicitis","Sigmoid Diverticulitis"],"a":0,"e":"Ans is ''a'' ie Stricture of CBD Most common route of infection to liver is along the bile duct. It may be due to : - i) Stone impacted in CBD. ii) Benign or malignant stricture of CBD. Most common infecting organisms are E.coli and Klebsiella pneumonia","pyqMatches":[{"year":"2014","no":1583,"q":"Commonest cause of pyogenic liver abscess ?","o":["Stricture of CBD","Biliary Colic","Appendicitis","Sigmoid Diverticulitis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8919, 'Surgery', 'Hepatobiliary & Pancreas', 'Moderate', 'Surgery', 33, '{"id":8919,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Moderate","source":"Surgery","sourceNo":33,"q":"All are true about amoebic liver abscess except:","o":["More common in females","More common in left lobe of liver","Metronidazole is mainstay of treatment","a and b"],"a":3,"e":"Ans is D a i.e. More common in females & b i.e. More common in left lobe of liver “Male preponderance of greater than 10:1 has been reported in all studies” The right lobe of the liver is more commonly affected than the left lobe. amebic liver abscess is 7-12 times more common in men than in women, with a predominance among men aged 18-50 years. Metronidazole 800 mg TDS for 5–10 days Aspiration Repeated imaging of liver","pyqMatches":[{"year":"2014","no":1531,"q":"All are true about amoebic liver abscess except:","o":["More common in females","More common in left lobe of liver","Metronidazole is mainstay of treatment","a and b"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8920, 'Surgery', 'Hepatobiliary & Pancreas', 'Easy', 'Surgery', 34, '{"id":8920,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Easy","source":"Surgery","sourceNo":34,"q":"False about hydatid cyst of liver:","o":["Mostly asymptomatic","Most commonly located in right lobe of liver","Most common causative organism is echinococcus granulosus","Hepatic resection is never done"],"a":3,"e":"Ans is ''d'' i.e. Hepatic resection is never done Laparoscopic aspiration, unroofing and evacuation of the hepatic hydatid cysts can be done.","pyqMatches":[{"year":"2014","no":1532,"q":"False about hydatid cyst of liver:","o":["Mostly asymptomatic","Most commonly located in right lobe of liver","Most common causative organism is echinococcus granulosus","Hepatic resection is never done"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8921, 'Surgery', 'General Principles & Wounds', 'Moderate', 'Surgery', 35, '{"id":8921,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Moderate","source":"Surgery","sourceNo":35,"q":"Indications of Liver transplantation are All/Except","o":["Biliary atresia","Sclerosing cholangitis","Hepatitis A","Cirrhosis"],"a":2,"e":"Ans. is ''c'' i.e. Hepatitis A Liver transplantation is indicated for those children and adults, who in the absence of contraindications suffer from severe, irreversible liver disease for which alternative medical or surgical treatments have been exhausted or are unavailable. Most common indication in children ________ Biliary atresia in adults --> Cirrhosis Harrison 17/e writes- \"Currently, chronic hepatitis C and alcoholic liver disease are the most common indications for liver transplantation, accounting for over 40% of all adult candidates who undergo the procedure.\" Indications for ver Transplantation Adults Children Biliary atresia Primary biliary cirrhosis Neonatal hepatitis Secondary biliary cirrhosis Congenital hepatic fibrosis Primary sclerosing cholangitis Alagille''s disease Autoimmune hepatitis Alagille s disease Autoimmune hepatitis Byler''s disease Caroli''s disease al- antitrypsin deficiency Cryptogenic cirrhosis Inherited disorders of metabolism Chronic hepatitis with cirrhosis Wilson''s disease Hepatic vein thrombosis Tyrosinemia Fulminant hepatitis Glycogen storage diseases Alcoholic cirrhosis Lysosomal storage diseases Chronic viral hepatitis Protoporphyria Primary hepatocellular malignancies Crigler-Najjar disease type I Hepatic adenomas Familial hypercholesterolemia Nonalcoholic steatohepatitis Primary hyperoxaluria type I Familial amyloid polyneuropathy Hemophilia Contraindications to Liver Transplantation Absolute Relative Uncontrolled extrahepatobiliary infection Age >70 Active, untreated sepsis Prior extensive hepatobiliary surgery Uncorrectable, life-limiting congenital anomalies Portal vein thrombosis Active substance or alcohol abuse Renal failure Advanced cardiopulmonary disease Previous extrahepatic malignancy (not including nonmelanoma skin cancer) E t h t bili li S b it Extrahepatobiliary malignancy (not including nonmelanoma skin cancer) Severe obesity Metastatic malignancy to the liver Severe malnutrition/wasting Cholangiocarcinoma Medical noncompliance AIDS HIV seropositivity Life-threatening systemic diseases Intrahepatic sepsis Severe hypoxemia secondary to right-to-left intrapulmonary shunts (P02 < 50 mmHg) Severe pulmonary hypertension (mean PA pressure >35 mmHg) Uncontrolled psychiatric disorder","pyqMatches":[{"year":"2014","no":1518,"q":"Indications of Liver transplantation are All/Except","o":["Biliary atresia","Sclerosing cholangitis","Hepatitis A","Cirrhosis"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8922, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 36, '{"id":8922,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":36,"q":"Kehr''s sign seen in splenic rupture is -","o":["Pain over left shoulder","Pain over right scapula","Periumbilical pain","Pain over renal angle"],"a":0,"e":"Ans. is ''A'' i.e., Pain over left shoulder In splenic rupture the pain may be referred to the tip of the left shoulder. This is known as Kehr''s sign. It occurs due to irritation of the undersurface of the diaphragm with blood and the pain is referred to the shoulder through the affected fibres of phrenic nerve (C4 and C5). Kehr''s sign can be elicited by bimaual compression of the left upper quadrant after the patient has been in Trendelenburg''s position for about 10 minutes prior to the manoeuvre.","pyqMatches":[{"year":"2013","no":1409,"q":"Kehr''s sign seen in splenic rupture is","o":["Pain over left shoulder","Pain over right scapula","Periumbilical pain","Pain over renal angle"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8923, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 37, '{"id":8923,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":37,"q":"In which condition, medical treatment of gall stone is indicated -","o":["Stone is < 15 mm size","Radio opaque stone","Calcium bilirubinate stone","Non functioning gall bladder"],"a":0,"e":"Ans is ''a'' is Stone is < 15 mm size Medical treatments for gallstones, used alone or in combination, include the following- Oral bile salt therapy (ursodeoxycholic acid) (particularly for x-ray- negative cholesterol gallstones in patients with normal gallbladder function) Extracorporeal shockwave lithotripsy (particularly for noncalcified cholesterol gallstones in patients with normal gallbladder function) Medical management is more effective in patients with good gallbladder function who have small stones (< 1 cm) with a high cholesterol content. Bile salt therapy may be required for more than 6 months and has a success rate of less than 50%.","pyqMatches":[{"year":"2016","no":1245,"q":"In which condition, medical treatment of gall stone is indicated","o":["Stone is < 15 mm size","Radio opaque stone","Calcium bilirubinate stone","Non functioning gall bladder"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8924, 'Surgery', 'Gastrointestinal Surgery', 'Hard', 'Surgery', 38, '{"id":8924,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Hard","source":"Surgery","sourceNo":38,"q":"In a patient of acute cholecystitis, referred pain to the shoulder is k/a","o":["Murphy''s sign","Gray Turner sign","Boa''s sign","Cullen''s sign"],"a":2,"e":"Ans is ''c'' i.e. Boas'' sign Boas'' sign: In cases of acute cholecystitis pain radiates to the tip of the right shoulder and an area of skin below the scapula is found to be hypersensitive. This is k/a Boas'' sign. Sensitivity is quite less. Also Know: Murphy''s sign: Seen in acute cholecystitis. Murphy''s sign is elicited by asking the patient to breathe out and then gently placing the hand below the costal margin on the right side at the mid-clavicular line (the approximate location of the gallbladder). The patient is then instructed to inspire (breathe in). Normally, during inspiration, the abdominal contents are pushed downward as the diaphragm moves down (and lungs expand). If the patient stops breathing in (as the gallbladder is tender and, in moving downward, comes in contact with the examiner''s .fingers) and winces with a ''catch'' in breath, the test is considered positive. In order for the test to be considered positive, the same maneuver must not elicit pain when performed on the left side. Grey Turner & Cullen''s sign: positive in severe necrotizing pancreatitis. Grey Turners sign is bluish discolouration seen at the flanks. Bluish discolouration around the umbilicus is known as Cullen''s sign.","pyqMatches":[{"year":"2012","no":1135,"q":"In a patient of acute cholecystitis, referred pain to the shoulder is k/a","o":["Murphy''s sign","Gray Turner sign","Boa''s sign","Cullen''s sign"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8925, 'Surgery', 'Breast Surgery', 'Moderate', 'Surgery', 39, '{"id":8925,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":39,"q":"In Patey''s mastectomy the step not done is","o":["Nipple and areola removed","Surrounding normal tissue of tumor is removed.","Pectoralis major removed","Pectoralis minor removed"],"a":2,"e":"Ans. is ''c'' i.e. (Pectoralis major removed) Lets see the nomenclature of various surgeries on breast Simple or Total mastectomy * it removes all breast tissue, the nipple-areola complex, and skin. Extended simple mastectomy * Simple mastectomy + removal of level I axillary lymph nodes. Modified radical mastectomy it removes all breast tissue, the nipple-areola complex, skin and the level I and level II axillary lymph nodes. Halstead''s Radical mastectomy removes all breast tissue and skin, the nipple areola complex, the pectoralis major and minor muscles and the level I, II and III axillary lymph nodes. Modified Radical Mastectomy Two forms of modified radical mastectomy are in use Auchincloss (pronounced as ''aushincloss'') procedure * Here both the pectoralis major and minor muscles are preserved with removal of level I and II axillary lymph nodes Patey''s Procedure here the pectoralis minor muscle is removed to allow complete dissection of level III axillary lymph nodes Scanlon''s modification of Patey''s procedure * here the pectoralis minor muscle is divided instead of removing. Division of pectoralis minor muscle allows complete removal of level III lymph nodes Halstead Radical Mastectomy In this operation following structures are removed. i) the whole breast ii) the portion of skin overlying the tumor, which includes the nipple-areola complex. iii) the subcutaneous fat and the deep fascia vertically from the lower border of the clavicle upto the upper quarter of the sheath of the rectus abdominis and horizontally from the strenum to the anterior border of lattissimus dorsi iv) pectoralis major muscle v) pectoralis minor muscle and clavipectoral fascia vi) upper part of the aponeurosis of the external oblique and anterior parts of a few digitations of the serratus anterior muscle vii) all fatty and loose areolar tissue along with level I, II & III axillary lymph nodes Structures saved are : i) the axillary vein and the cephalic vein ii) the long thoracic nerve of Bell (Nerve to serratus anterior). The nerve to latissimus dorsi may be sacrified if required. Also know Extended Radical Mastectomy - Radical mastectomy + removal of internal mammary lymph nodes Super Radical Mastectomy - Radical mastectomy + removal of internal mammary, mediastinal and supraclavicular lymph nodes.","pyqMatches":[{"year":"2015","no":1331,"q":"In Patey''s mastectomy the step not done is","o":["Nipple and areola removed","Surrounding normal tissue of tumor is removed.","Pectoralis major removed","Pectoralis minor removed"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8926, 'Surgery', 'Breast Surgery', 'Moderate', 'Surgery', 40, '{"id":8926,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":40,"q":"Breast conservation surgery not indicated ?","o":["Large pendular breast","SLE","Diffuse microcalcification","All"],"a":3,"e":"Answer (a) Large pendular breast; (b) SLE ; (c) Diffuse microcalcification","pyqMatches":[{"year":"2014","no":1510,"q":"Breast conservation surgery not indicated ?","o":["Large pendular breast","SLE","Diffuse microcalcification","All"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8927, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 41, '{"id":8927,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":41,"q":"In breast carcinoma metastasis, prognosis depends best upon -","o":["Estrogen receptor status","Axillary lymphnode status","Size of tumour","Site of tumour"],"a":0,"e":"Ans is ''a'' i.e., Estrogen receptor status In case of metastasis, the prognosis no more depends upon the lymph node status. The lymph node status is the most important prognostic indicator for tumor localized to breast, as the presence of nodal metastasis implies systemic dissemination of cancer and hence a bad prognosis. But once a metastasis is discovered, the lymph node status is of little significance. Metastatic disease confers the breast tumor TNM stage IV status, with worst prognosis. Currently stage IV diseases are not curative. Schwartz 9/e writes - \"Treatment for stage IV breast cancer is not curative, but may prolong survival and enhance a women''s quality of life. Hormonal therapies that are associated with minimal toxicity are preferred to cytotoxic chemotherapy. Appropriate candidates for initial hormonal therapy include women with hormone receptor- positive cancers; women with bone or soft tissue metastasis only; and women with limited and asymptomatic visceral metastasis. About hormone receptors, CSDT 11/e, p 329 writes - \"the presence or absence of estrogen and progesterone receptors in the cytoplasm of tumor cells is of paramount importance in managing all patients with breast cancer, especially those with recurrent or metastatic disease. They are of proved value in determining adjuvant therapy and therapy for patients with advanced disease. Upto 60% of patients with metastatic breast cancer will respond to hormonal manipulation if their tumors contain estrogen receptors. However fewer than 5% of patients with metastatic ER-negative tumors can be successfully treated with hormonal manipulation.\"","pyqMatches":[{"year":"2014","no":1598,"q":"In breast carcinoma metastasis, prognosis depends best upon","o":["Estrogen receptor status","Axillary lymphnode status","Size of tumour","Site of tumour"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8928, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 42, '{"id":8928,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":42,"q":"What is true about HER2/neu overexpression in Ca breast:","o":["Good prognosis","Responds well to taxanes","Responds well to monoclonal antibodies","Seen only in breast cancer"],"a":2,"e":"Ans is ''c'' i.e. Responds well to monoclonal antibodies The HER2 receptor (previously called HER2/neu, or ERBB-2 receptor) belongs to the epidermal growth factor receptor (EGFR) family of receptors, which are critical in the activation of subcellular signal transduction pathways controlling epithelial cell growth and differentiation and possibly angiogenesis. Amplification of HER2 or overexpression of its protein product is observed in 18 to 20 percent of human breast cancers. HER2 overexpression is also noted in other tumors such as esophagogastric tumors, lung, ovary & head and neck squamous cell ca. (In all of these sites, HER2 overexpression has been identified as a negative prognostic factor.) Following points are to be noted about HER2 overexpression in breast Ca: Prognostic value of HER2 — HER2 overexpression is a poor prognostic marker. HER2 overexpression is associated with high rates of disease recurrence and death in the absence of adjuvant systemic therapy. Predictive value of HER2 — HER2 status predicts response to specific therapies: Patients with high levels of HER2 expression benefit from treatment with agents that target HER2, such as trastuzumab (a monoclonal antibody) and lapatinib. HER2 status appears to predict resistance or sensitivity to different types of chemotherapeutic agents, including anthracyclines and taxanes. Women whose tumors overexpress HER2 appear to derive greater benefit from anthracycline-based adjuvant therapy than from adjuvant therapy that is alkylating agent-based, such as CMF (cycl ophosphami de, methotrexate, fluorouracil). Relationship between HER2 overexpression and taxanes is still under study with various studies giving conflicting reports. HER-2 positivity is associated with resistance to endocrine therapies. Scoring of HER-2 Immunohistochemistry Assays Score HER-2 Status Staining Pattern 0 Negative No staining or membrane staining in <10% of tumor cells° 1+ Negative • A faint barely perceptible membrane staining is detected in >10% of tumor cells. The cells are only stained in part of the membrane°. 2+ Equivocal • Weak to moderate complete membrane staining is seen in >10% of tumor cells or <30% with strong staininga 3+ Positive • Strong complete membrane staining is seen in >30% of tumor cells°","pyqMatches":[{"year":"2012","no":1124,"q":"What is true about HER2/neu overexpression in Ca breast:","o":["Good prognosis","Responds well to taxanes","Responds well to monoclonal antibodies","Seen only in breast cancer"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8929, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 43, '{"id":8929,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":43,"q":"Mondor''s disease is ?","o":["Thrombophlebitis of the Superficial veins of Breast","Carcinoma of the breast","Premalignant condition of the breast","Filariasis of the breast"],"a":0,"e":"Ans is ''a'' i.e., Thrombophlebitis of Superficial veins of Breast Mondor''s disease is thrombophlebitis of the superficial veins of anterior chest wall and breast although it has also been seen in the arm. frequently involved veins are lateral thoracic vein, thoracoepigastric vein and superficial epigastric veins. aetiology is unknown also known as ''string phlebitis'', it presents as a tender cord-like structure. The women may present with acute pain in the lateral asepct of breast or the anterior chest wall. A tender cord-like superficial thrombosed vein is formed and when the skin over the breast is stretched by raising the arm, a narrow shallow subcutaneous groove alongside the cord becomes apparent. rarely it may be bilateral. Management it''s a benign self-limited disorder The differential diagnosis is lymphatic permeation from an occult carcinoma of breast When the diagnosis is uncertain or a mass is present near the cord, a biopsy may be done. Treatment antiinflammatory drugs and warm compresses restricted arm movements as well as brassiere support of breast it usually resolves within 4 to 6 weeks. When symptoms persists or are refractory to treatment, the involved vein segment may be excised.","pyqMatches":[{"year":"2014","no":1526,"q":"Mondor''s disease is ?","o":["Thrombophlebitis of the Superficial veins of Breast","Carcinoma of the breast","Premalignant condition of the breast","Filariasis of the breast"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8930, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 44, '{"id":8930,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":44,"q":"Flap commonly used in breast reconstruction is?","o":["Serratus anterior","TRAM","Flap from arm","Delto pectoral flap"],"a":1,"e":"Ans. is ''b'' i.e. TRAM (Most common) Single Pedicle Double Pedicle Free flap Deep inferior epigastric perforator flap","pyqMatches":[{"year":"2014","no":1574,"q":"Flap commonly used in breast reconstruction is?","o":["Serratus anterior","TRAM","Flap from arm","Delto pectoral flap"],"a":1,"source":"NEET_2014_Paper.pdf"},{"year":"2020","no":195,"q":"Flap commonly used in breast reconstruction is?","o":["DIEP based on deep inferior epigastric vessels","TRAM based on superior gluteal vessels","Gluteal flap based on thoracodorsal artery","Latissimus dorsi flap based on the inferior epigastric artery"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2014","2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8931, 'Surgery', 'Endocrine Surgery', 'Easy', 'Surgery', 45, '{"id":8931,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Easy","source":"Surgery","sourceNo":45,"q":"Lateral aberrant thyroid refers to -","o":["Congenital thyroid abnormality","Metastatic focus in lymph nodes","Struma ovarii","Lingual thyroid"],"a":1,"e":"Ans is \"B\" i.e. Metastatic focus in lymph nodes Lateral aberrant thyroid refers to a metastatic focus in lymph nodes. Lateral aberrant thyroid is a misnomer and always refers to the presence of metastatic thyroid carcinoma (papillary) in cervical lymph nodes. It does not indicate the presence of ectopic thyroid tissue as the name suggests.","pyqMatches":[{"year":"2015","no":1280,"q":"Lateral aberrant thyroid refers to","o":["Congenital thyroid abnormality","Metastatic focus in lymph nodes","Struma ovarii","Lingual thyroid"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8932, 'Surgery', 'Endocrine Surgery', 'Easy', 'Surgery', 46, '{"id":8932,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Easy","source":"Surgery","sourceNo":46,"q":"Treatment of choice for medullary carcinoma of thyroid is:","o":["Total thyroidectomy","Partial thyroidectomy","1131 ablation","Hemithyroidectomy"],"a":0,"e":"Ans. is ''a'' i.e. Total thyroidectomy Treatment of thyroid malignancies is as follows :- (Note- this is a very important and often repeated topic in PG exams, so if time permits one must turn the pages of Schwartz Sx or any other standard book for detailed study). Papillary Thyroid Carcinoma (PCT) High-risk tumors or bilateral tumors - Total thyroidectomy (or near total thyroidectomy). Low risk - The treatment is controversial. Conservative approach advocates hemithyroidectomy (lobectomy + isthmusectomy). - More radical approach advocates total thyroidectomy (or near total thyroidectomy). - Schwartz Sx and Devita''s Oncology are in favour of radical approach. (High and Low risk decided by any one of the many classification systems) If enlarged lymph nodes are found - Modified radical neck dissection is done of the affected side. When patients are found to have a minimal papillary thyroid carcinoma in a thyroid specimen removed for other reasons, unilateral thyroid lobectomy and isthmusectomy is usually considered to be adequate treatment, unless the tumor has evidence of angioinvasion, multifocality, or positive margins. Follicular Thyroid Carcinoma (FTC) FNA biopsy is unable to distinguish benign follicular lesions from follicular carcinomas therefore, preoperative diagnosis of cancer is difficult unless distant metastases are present. Patients diagnosed by FNA biopsy as follicular lesions should undergo thyroid lobectomy + isthmusectomy (because at least 80% of these patients will have benign adenomas). The resected lobe is subjected to histology (intraoperative frozen – section examination, though usually not helpful should be performed in high risk cases).","pyqMatches":[{"year":"2013","no":1389,"q":"Treatment of choice for medullary carcinoma of thyroid is:","o":["Total thyroidectomy","Partial thyroidectomy","1131 ablation","Hemithyroidectomy"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8933, 'Surgery', 'Endocrine Surgery', 'Hard', 'Surgery', 47, '{"id":8933,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Hard","source":"Surgery","sourceNo":47,"q":"In case of hypothyroidism which investigation is most informative and most commonly used ?","o":["Serum TSH Level","Serum T3, T4 Level","Serum Calcitonin assay","Serum T3 level"],"a":0,"e":"Ans is A ie Serum TSH Level \"A normal TSH Level excludes primary (but not secondary) hypothyrodism. If the TSH is elevated a free T4 level is needed to confirm the presence of clinical hypothyrodism, but free T4 is inferior to TSH when used as a screening test, as it will not detect subclinical or mild hypothyroidism. Circulating free T3 levels are normal in about 25% of the patients, reflecting adaptive respose to hypothyroidism. T3 measurements are therefore not indicated.\" - Harrison \"Among the various available serum thyroid function tests, TSH is the most useful to assess gland dysfunction.\" ? Endocrine Surgery of Head & Neck, p 83.","pyqMatches":[{"year":"2016","no":1135,"q":"In case of hypothyroidism which investigation is most informative and most commonly used ?","o":["Serum TSH Level","Serum T3, T4 Level","Serum Calcitonin assay","Serum T3 level"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8934, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 48, '{"id":8934,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":48,"q":"M.C. site of CA oesophagus is -","o":["Middle 1/3rd","Upper 1/3rd","Lower 1/3rd","Lower end of esophagus"],"a":0,"e":"Ans is (a) ie Middle 1/3rd Well, I am not quite sure of the answer. Esophageal Carcinoma is of two common histological types i) Squamous cell Ca - the MC type in world (-95% according to Sabiston) ii) Adenocarcinoma - where incidence is increasing at a rapid rate and is now the MC type in USA (Ref. Harrison, Schwartz) Distribution of Squamous Cell Ca. Upper 1/3 10% Middle 113 60% Lower 1/3 30% Adenocarcinoma is mainly located in lower 1/3. Nowhere, I could get the MC site of esophageal carcinoma overall (including both squamous and adeno variety). [Harrison writes the MC site to be lower 1/3, but it gives incidence for US population only, not for the whole world] But one thing is sure - squamous cell Ca is the MC type of esophageal cancer in world [(Ref: Bailey & Love, 25/e p1026 (24/e p1009); Robbins 8/e p772 (7/e p806); Sabiston I8/e p1090 (I7/e p1118)] So I presume that the overall MC site would be the MC site involved by the MC type of esophageal cancer i.e. -* Middle 1/3 So remember MC type of esophageal Ca in world -> Squamous Cell Ca (--95%) MC site -> Middle 1/3","pyqMatches":[{"year":"2014","no":1577,"q":"M.C. site of CA oesophagus is","o":["Middle 1/3rd","Upper 1/3rd","Lower 1/3rd","Lower end of esophagus"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8935, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 49, '{"id":8935,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":49,"q":"Which is M.C. site for iatrogenic oesophageal perforation -","o":["Abdominal portion","Cervical portion","Above arch of aorta","Below arch of aorta"],"a":1,"e":"Ans is ''b'' ie Cervical portion Oesophageal perforation is of two types Iatrogenic (MC) : - Common site is cervical esophagus Just above the upper sphinctcr. Spontaneous rupture : as seen in Boerhaaves syndrome (Rupture of esophagus after vomitting) - common in the lower 1/3 of esophagus.","pyqMatches":[{"year":"2014","no":1572,"q":"Which is M.C. site for iatrogenic oesophageal perforation","o":["Abdominal portion","Cervical portion","Above arch of aorta","Below arch of aorta"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8936, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 50, '{"id":8936,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":50,"q":"Corkscrew esophagus is seen in which of the following conditions ?","o":["Carcinoma esophagus","Scleroderma","Achalasia cardia","Diffuse esophagus spasm"],"a":3,"e":"Ans. is d i.e., Diffuse Esophageal spasm Radiological appearances of diffuse esophageal spasm have been described as: curling esophagus Corkscrew esophagus or - pseudodiverticulosis Diffuse esophageal spasm is a motor disorder of esophagus characterized by repetitive simultaneous non-peristaltic contractions. Symptoms are substernal chest pain and/or dysphagia Diagnosed by manometry Also know Nutcracker esophagus also known as ''supersqueezer'' esophagus - it is characterized by extremely high-amplitude peristaltic contraction - Symptoms are pain and dysphagia Diagnosed by manometry study which shows peristaltic esophageal contractions with peak amplitudes greater than two standard deviations above the normal values.","pyqMatches":[{"year":"2012","no":1425,"q":"Corkscrew esophagus is seen in which of the following conditions ?","o":["Carcinoma esophagus","Scleroderma","Achalasia cardia","Diffuse esophagus spasm"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8937, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 51, '{"id":8937,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":51,"q":"The most common type of Tracheo- Oesophageal Fistula is -","o":["Esophageal atresia without tracheoesophageal fistula","Esophageal atresia with proximal tracheoesophageal fistula","Esophageal atresia with distal tracheoesophageal fistula","Esophageal atresia with proximal and distal fistula"],"a":2,"e":"Ans. is ''c'' i.e., Esophageal atresia with distal tracheoesophageal fistula TEF is classified into five types based on presence of esophageal atresia and location of fistula:? 1) Type A : There is esophageal atresia without TEF. There is no gas in abdomen. It is 2''d most common type. 2) Type B : There is proximal TEF. There is no gas in abdomen. 3) Type C : There is proximal esophageal atresia with distal TEF. Gas in abdomen is present. It is most common. 4) Type D : Both proximal and distal fistula are present. Gas in abdomen is present. It is least common. 5) Type E : Isolated TEF (H or N type) is there.","pyqMatches":[{"year":"2014","no":1573,"q":"The most common type of Tracheo- Oesophageal Fistula is","o":["Esophageal atresia without tracheoesophageal fistula","Esophageal atresia with proximal tracheoesophageal fistula","Esophageal atresia with distal tracheoesophageal fistula","Esophageal atresia with proximal and distal fistula"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8938, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 52, '{"id":8938,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":52,"q":"commonest benign tumor of the esophagus?","o":["Leiomyoma","Papilloma","Adenoma","Hemangioma"],"a":0,"e":"Ans is a. i.e. Leiomyoma \"Leiomyomas constitute more than 50% of benign esophageal tumors \"-Schwartz","pyqMatches":[{"year":"2016","no":470,"q":"commonest benign tumor of the esophagus?","o":["Leiomyoma","Papilloma","Adenoma","Hemangioma"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8939, 'Surgery', 'Urology', 'Moderate', 'Surgery', 53, '{"id":8939,"subject":"Surgery","chapter":"Urology","difficulty":"Moderate","source":"Surgery","sourceNo":53,"q":"All of the following are risk factors for carcinoma gall bladder, EXCEPT -","o":["Typhoid carriers","Adenomatous gall bladder polyps","Choledochal cysts","Oral contraceptives"],"a":3,"e":"Ans. is d i.e., Oral Contraceptives Risk factors for Ca Gall bladder are : i) Gall stones ii) Adenomatous gall bladder polyps (particularly polyps larger than 10 mm) iii) Calcified (porcelain) gall bladder iv) Choleduochal cyst v) Estrogens vi) Anomalous pancreaticobiliary duct junction vii) Exposure to carcinogens (azotoulene, nitrosamine) viii) Typhoid carriers ix) Sclerosing cholangitis","pyqMatches":[{"year":"2012","no":493,"q":"All of the following are risk factors for carcinoma gall bladder, EXCEPT","o":["Typhoid carriers","Adenomatous gall bladder polyps","Choledochal cysts","Oral contraceptives"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8940, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 54, '{"id":8940,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":54,"q":"Regarding Ca gallbladder -","o":["Squamous cell ca is the most common","Present with jaundice","Good prognosis","All"],"a":1,"e":"Answer (b) Presents with jaundice Biliary tract cancers tend to be slow-growing tumours that invade locally and metastasise to local lymph nodes. Distant metastases to the peritoneal cavity, liver and lung do occur. Jaundice is the most common presenting feature. Abdominal pain, early satiety and weight loss are also commonly seen. On examination, jaundice is evident, cachexia often noticeable and a palpable gall bladder is present if the obstruction is in the distal common bile duct (Courvoisier''s sign).","pyqMatches":[{"year":"2016","no":1246,"q":"Regarding Ca gallbladder","o":["Squamous cell ca is the most common","Present with jaundice","Good prognosis","All"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8941, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 55, '{"id":8941,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":55,"q":"The Gall stone pain is referred to the shoulder through which of the following nerves:","o":["C2-C8","T1-T4","T8-T12","C3-05"],"a":3,"e":"Ans is ''d'' i.e. C3-05 Gallstone disease may refer pain to the right shoulder tip (k/a Kehr''s sign). This is because, an inflamed gallbladder irritates the diaphragm which is supplied by the phrenic nerve (C3-05). These cervical nerve roots, also provide sensory supply to the right shoulder through supraclavicular nerves. Hence the gallbladder pain is referred to the right shoulder through the C3-05 nerve roots. Kehr''s sign is a classic example of referred pain: irritation of the diaphragm is signaled by the phrenic nerve as pain in the area above the collarbone. This is because the supraclavicular nerves have the same cervical nerves origin as the phrenic nerve, C3 and C4. Boas'' sign can also indicate stomach and duodenal disease. When the transverse processes of thoracic vertebrae T10-T12 are pressed or effleuraged with the bottom of the hand, pain can appear at left of spinous processes (in stomach''s lesser curvature ulcer) or at right (in pyloric or duodenal ulcer). Boas'' or Boas''s sign is hyperaesthesia (increased or altered sensitivity) below the right scapula can be a symptom in acute cholecystitis (inflammation of the gallbladder). cholecystitis (inflammation of the gallbladder).","pyqMatches":[{"year":"2016","no":1243,"q":"The Gall stone pain is referred to the shoulder through which of the following nerves:","o":["C2-C8","T1-T4","T8-T12","C3-05"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8942, 'Surgery', 'Hepatobiliary & Pancreas', 'Easy', 'Surgery', 56, '{"id":8942,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Easy","source":"Surgery","sourceNo":56,"q":"The best investigative modality for gall bladder stones -","o":["Oral cholecystogram","Percutaneous transhepatic cholangiography","Ultrasound","Intravenous cholangiogram"],"a":2,"e":"Ans. is ''c'' i.e. Ultrasound Ultrasonography: - This is the investigation of choice for the detection of gallstones, and obstructive jaundice. USG shows echogenic focus with posterior acoustic shadowing. The most specific sign of a contracted, stone-filled gallbladder is a hypoechoic wall superficial to a curvilinear echo from the stones and an acoustic shadow:- WES triad (Wall, Echo, Shadow) or the \"Double arc shadow sign\". IOC for diagnosis of gallstone- acute cholecystitis, acute acalculous cholecystitis, chronic cholecystitis is Ultrasound","pyqMatches":[{"year":"2013","no":1771,"q":"The best investigative modality for gall bladder stones","o":["Oral cholecystogram","Percutaneous transhepatic cholangiography","Ultrasound","Intravenous cholangiogram"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8943, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 57, '{"id":8943,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":57,"q":"Strawberry gallbladder is seen in ?","o":["Gangrene of gallbladder","Porcelain gall bladder","Adenomatosis","Cholesterosis"],"a":3,"e":"Ans. is'' i.e. Cholesterosis Cholecystosis is the chronic inflammatory condition of the gallbladder with cholesterol deposits. Types I. Aggregations of cholesterol crystals in the mucosa or submucosa —cholesterosis (Strawberry gallbladder). Lipoid contents are present in large foamy cells that have phagocytosed cholesterol. Here cystic duct is normal. The disease occurs only in gallbladder. It is a premalignant condition. II. Cholesterol laden polypoid projections in the mucosa — cholesterol polyposis (Gallbladder polyp). III. Granulomatous thickening and hyperplasia of the gallbladder — cholecystitis glandularis proliferans. IV. Diverticula formation in the wall of the gallbladder— diverticulosis of gallbladder. V. Gallbladder wall fistula.","pyqMatches":[{"year":"2015","no":1299,"q":"Strawberry gallbladder is seen in ?","o":["Gangrene of gallbladder","Porcelain gall bladder","Adenomatosis","Cholesterosis"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8944, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 58, '{"id":8944,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":58,"q":"VIPoma is associated with which syndrome:","o":["Zollinger Ellison","Verner Morrison","Carcinoid syndrome","Cushing''s syndrome"],"a":1,"e":"Ans is ''b'' i.e. Verner Morrison VlPomas are endocrine tumors that secrete excessive amounts of vasoactive intestinal peptide (VIP), Excessive VIP causes a distinct syndrome characterized by large- volume diarrhea, hypokalemia, and dehydration. This syndrome also is called Verner-Morrison syndrome, pancreatic cholera, and WDHA syndrome for watery diarrhea, hypokalemia, and achlorhydria. The principal symptoms are large-volume diarrhea (100%) severe enough to cause hypokalemia (80-100%), dehydration (83%), hypochlorhydria (54-76%), and flushing (20%). In adults 80-90% of VlPomas are pancreatic in location, with the rest due to VIP-secreting pheochromocytomas,","pyqMatches":[{"year":"2012","no":1143,"q":"VIPoma is associated with which syndrome:","o":["Zollinger Ellison","Verner Morrison","Carcinoid syndrome","Cushing''s syndrome"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8945, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'Surgery', 59, '{"id":8945,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":59,"q":"All are resected in whipples operation except ?","o":["Duodenum","Head of pancreas","Neck of pancreas","Common bile duct"],"a":2,"e":"Ans is ''c'' Whipples operation (Pancreaticoduodenectomy) is the most commonly performed operation for carcinoma of head of pancreas. It includes resection of: - distal stomach - duodenum - gall bladder - proximal jejunum - CBD - regional lymphatics - head of pancreas Restoration of gastrointestinal continuity requires - pancreaticojejunostomy choledochojejunostomy & - gastrojejunostomy","pyqMatches":[{"year":"2015","no":1328,"q":"All are resected in whipples operation except ?","o":["Duodenum","Head of pancreas","Neck of pancreas","Common bile duct"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8946, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'Surgery', 60, '{"id":8946,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":60,"q":"Following genetic counselling in a family for Familial polyposis coli (FPC) next screening test is","o":["Flexible sigmoidoscopy","Colonoscopy","Occult blood in stools","APC gene"],"a":3,"e":"Ans. is ''d'' i.e. APC gene Schwartz writes - \"Flexible sigmoidoscopy of first-degree relatives of FAP (Familial adenomatous polyposis) patients beginning at age 10 to 15 years has been the traditional mainstay of screening. Today following genetic counselling, APC gene testing may be used to screen family members providing an APC mutation has been identified in a family member.\" Familial adenomatous polyposis (FAP) is a dominantly inherited colon cancer syndrome due to germline mutations in the adenomatous polyposis coli (APC) tumor suppressor gene on chromosome 5. Patients with this syndrome develop hundreds to thousands of adenomas in the colon which if left untreated will eventually develop into colon cancer. Each of the FAP adenomas has lost the normal remaining allele of APC gene but has not yet accumulated the required additional mutations to generate fully malignant cells. In due course of time many of these adenomas acquire further genetic abnormalities and develop into fully malignant cancers. APC gene is thus considered to be a gatekeeper for colon tumorigenesis. The detection of APC gene mutation in family members of a FAP patient helps in making a definitive diagnosis before the development of polyps.","pyqMatches":[{"year":"2016","no":406,"q":"Following genetic counselling in a family for Familial polyposis coli (FPC) next screening test is","o":["Flexible sigmoidoscopy","Colonoscopy","Occult blood in stools","APC gene"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8947, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 61, '{"id":8947,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":61,"q":"The tendency of colonic carcinoma to metastasize is best assessed by -","o":["Size of tumor","Carcinoembryonic antigen (CEA) levels","Depth of penetration of bowel wall","Proportion of bowel circumference involved."],"a":2,"e":"Ans. is c) i.e. depth of penetration of bowel walls Schwartz writes \"Regional lymph node involvement is the most common form of spread of colorectal carcinoma and usually preceeds distant metastasis or the development of carcinomatosis. the T stage (depth of invasion) is the single most significant predictor of lymph node spread.\" From the above given lines ''depth of penetration of bowel wall'' appears to be predictor of distant metastases as well. CEA level is a marker for recurrance of colorectal ca after surgical resection. Though its preoperative levels has some prognostic significance, it is not a predictor for distant metastasis. CEA level is used to follow up post operative cases of colorectal cancer, for early detection of recurrance.","pyqMatches":[{"year":"2014","no":1569,"q":"The tendency of colonic carcinoma to metastasize is best assessed by","o":["Size of tumor","Carcinoembryonic antigen (CEA) levels","Depth of penetration of bowel wall","Proportion of bowel circumference involved."],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8948, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 62, '{"id":8948,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":62,"q":"Following is least common about angiodyplasia of colon -","o":["Involvement of cecum","Involvement of rectum in 50% of cases","Affecting age group > 40 yrs.","Cause of troublesome lower G.I. hemorrhage"],"a":1,"e":"Ans. is ''b'' i.e., Involvement of rectum in 50% cases Site: Occur most commonly in the ascending colon and caecum; however they can also occure in rest of colon and small bowel. Clinical features Anemia - most common presentation Hemoatochezia Malena There is an association with aortic stenosis (heyd''s syndrome).","pyqMatches":[{"year":"2014","no":1584,"q":"Following is least common about angiodyplasia of colon","o":["Involvement of cecum","Involvement of rectum in 50% of cases","Affecting age group > 40 yrs.","Cause of troublesome lower G.I. hemorrhage"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8949, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 63, '{"id":8949,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":63,"q":"Most common type of Intussusception is -","o":["Ileocolic","ileoileal","Colo-colic","Caeco-colic"],"a":0,"e":"Ans. is ''a'' i.e., Ileocolic Ileo-ileo-colic (-12) Ileoileal (-5%) Colocolic (-2%) Multiple (1%) Retrograde The most common type of intussusception is ileocolic (also known as ileocecal) (90%).","pyqMatches":[{"year":"2012","no":1116,"q":"Most common type of Intussusception is","o":["Ileocolic","ileoileal","Colo-colic","Caeco-colic"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8950, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 64, '{"id":8950,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":64,"q":"Features of intestinal obstruction : clinically/ investigation by :","o":["Abdominal distension","Vomiting","Fluid level in X-ray > 4","a and b"],"a":3,"e":"Ans. is ''a'' & ''b'' i.e. Abdominal distension & Vomiting About option ''c'' > 5 air-fluid levels in x-ray abdomen suggest intestinal obstruction Grainger''s Diagnostic radiology writes - \"3 to 5 fluid levels less than 2.5 cm in length may be seen, particularly in the right lower quadrant, without any evidence of intestinal obstruction or paralytic ileus.\"","pyqMatches":[{"year":"2013","no":1372,"q":"Features of intestinal obstruction : clinically/ investigation by :","o":["Abdominal distension","Vomiting","Fluid level in X-ray > 4","a and b"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8951, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 65, '{"id":8951,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":65,"q":"Commonest cause of intussusception is -","o":["Submucous lipoma","Meckel''s diverticulum","Hypertrophy of submucous peyer''s patches","Polyp"],"a":2,"e":"Ans. is ''c'' i.e., Hypertrophy of submucosa peyer''s patches","pyqMatches":[{"year":"2015","no":1269,"q":"Commonest cause of intussusception is","o":["Submucous lipoma","Meckel''s diverticulum","Hypertrophy of submucous peyer''s patches","Polyp"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8952, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 66, '{"id":8952,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":66,"q":"What is the T/t of pt with carcinoid tumor of appendix of size more than 2 cm -","o":["Right hemicolectomy","Appendicectomy","Appendicectomy + abdominal CT scan","Appendicectomy + 24 hrs urinary HIAA"],"a":0,"e":"Ans is ''a'' ie. Right hemicolectiomy","pyqMatches":[{"year":"2015","no":1249,"q":"What is the T/t of pt with carcinoid tumor of appendix of size more than 2 cm","o":["Right hemicolectomy","Appendicectomy","Appendicectomy + abdominal CT scan","Appendicectomy + 24 hrs urinary HIAA"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8953, 'Surgery', 'Gastrointestinal Surgery', 'Hard', 'Surgery', 67, '{"id":8953,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Hard","source":"Surgery","sourceNo":67,"q":"A 25 year old man presents with 3 days history of pain in the right lower abdomen and vomitings. patient''s general condition is satisfactory and clinical examination reveals a tender lump in right iliac fossa. The most appropriate management in this case would be","o":["Immediate appendicectomy","Exploratory laprotomy","Oschner Sherren regimen","External drainage"],"a":2,"e":"Ans. is ''c'' i.e., Oschner Sherren regimen The patient is presenting with typical clinical features of appendical mass. If an appendix mass is present and the condition of the patient is satisfactory, the standard treatment is the conservative Ochs​ner- Sherren regimen. This strategy is used as the inflammatory process is already localised and that inadvertent surgery is dificult and may be dan​‐ gerous. It may be impossible to find the appendix and, occasionally, a faecal fistula may form. For these reasons, it is wise to observe a non-operative programme but to be prepared to operate should clinical deterioration","pyqMatches":[{"year":"2014","no":1547,"q":"A 25 year old man presents with 3 days history of pain in the right lower abdomen and vomitings. patient''s general condition is satisfactory and clinical examination reveals a tender lump in right iliac fossa. The most appropriate management in this case would be","o":["Immediate appendicectomy","Exploratory laprotomy","Oschner Sherren regimen","External drainage"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8954, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'Surgery', 68, '{"id":8954,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":68,"q":"Which of the following is not a sign seen in acute apendicitis","o":["Rovsing''s","Rosenstein''s sign","Boa''s sign","Hamburger sign"],"a":2,"e":"Ans. is ''C'' Accessory signs of appendicitis Aure-Rozanova''s sign: Increased pain on palpation with finger in right Petit triangle (can be a positive Shchetkin-Bloomberg''s). Bartomier-Michelson''s sign: Increased pain on palpation at the right iliac region as the person being examined lies on his or her left side compared to when he/she lies on the back. Dunphy''s sign: Increased pain in the right lower quadrant with coughing. Hamburger sign: The patient refuses to eat (anorexia is 80% specific for appendicitis) Kocher''s (Kosher''s) sign: From the person''s medical history, the start of pain in the umbilical region with a subsequent shift to the right iliac region. Massouh sign: Developed in and popular in southwest England, the examiner performs a firm swish with his or her index and middle finger across the abdomen from the xiphoid process to the left and the right iliac fossa. A positive Massouh sign is a grimace of the person being examined upon a right sided (and not left) sweep. Obturator sign: The person being evaluated lies on her or his back with the hip and knee both flexed at ninety degrees. The examiner holds the person''s ankle with one hand and knee with the other hand. The examiner rotates the hip by moving the person''s ankle away from his or her body while allowing the knee to move only inward. A positive test is pain with internal rotation of the hip. Psoas sign, also known as \"Obraztsova''s sign\", is right lower- quadrant pain that is produced with either the passive extension of the right hip or by the active flexion of the person''s right hip while supine. The pain that is elicited is due to inflammation of the peritoneum overlying the iliopsoas muscles and inflammation of the psoas muscles themselves. Straightening out the leg causes pain because it stretches these muscles, while flexing the hip activates the iliopsoas and causes pain. Rovsing''s sign: Pain in the lower right abdominal quadrant with continuous deep palpation starting from the left iliac fossa upwards (counterclockwise along the colon). The thought is there will be increased pressure around the appendix by pushing bowel contents and air toward the ileocaecal valve provoking right-sided abdominal pain. Sitkovskiy (Rosenstein)''s sign: Increased pain in the right iliac region as the person is being examined lies on his/her left side","pyqMatches":[{"year":"2014","no":1565,"q":"Which of the following is not a sign seen in acute apendicitis","o":["Rovsing''s","Rosenstein''s sign","Boa''s sign","Hamburger sign"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8955, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 69, '{"id":8955,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":69,"q":"In carcinoma of anus distal margin of clearance of anal canal of at least","o":["2 cm","5 cm","4 cm","7 cm"],"a":0,"e":"Ans. is ''a'' i.e., 2 cm [Ref Bailey & Love 25th/e p. 1233]","pyqMatches":[{"year":"2014","no":1505,"q":"In carcinoma of anus distal margin of clearance of anal canal of at least","o":["2 cm","5 cm","4 cm","7 cm"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8956, 'Surgery', 'Gastrointestinal Surgery', 'Hard', 'Surgery', 70, '{"id":8956,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Hard","source":"Surgery","sourceNo":70,"q":"In case of female commonest hernia is ?","o":["Direct inguinal hernia","Indirect inguinal hernia","Femoral Hernia","Incisional hernia"],"a":1,"e":"Ans is ''b'' ie Indirect Inguinal hernia In Indirect inguinal hernia the contents of the abdomen enter the deep inguinal ring and traverse the whole length of the inguinal canal to come out through the superficial inguinal ring. It is the most common of all forms of hernia. It is most common in the young (cf a direct hernia is most common in the old) Femoral hernias occur most commonly in women but lower incidence overall than inguinal hernias.","pyqMatches":[{"year":"2016","no":1289,"q":"In case of female commonest hernia is ?","o":["Direct inguinal hernia","Indirect inguinal hernia","Femoral Hernia","Incisional hernia"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8957, 'Surgery', 'Vascular Surgery', 'Moderate', 'Surgery', 71, '{"id":8957,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":71,"q":"Triangle of Doom is bounded by all of the following except:","o":["Cooper''s ligament","Vas deferens","Gonadal vessels","Peritoneal reflection"],"a":0,"e":"Ans is a i.e. Cooper''s ligament The triangle of doom is bounded Medially by the vas deferens Laterally by the vessels of the spermatic cord (gonadal vessels) Inferiorly by peritoneal reflection Apex oriented superiorly at internal ring. The contents of the space include External iliac vessels Deep circumflex iliac vein Femoral nerve Genital branch of the genitofemoral nerve","pyqMatches":[{"year":"2014","no":1528,"q":"Triangle of Doom is bounded by all of the following except:","o":["Cooper''s ligament","Vas deferens","Gonadal vessels","Peritoneal reflection"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8958, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 72, '{"id":8958,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":72,"q":"Regarding desmoid tumour which is not correct ?","o":["Often seen below the umbilicus","Unencapsulated","More common in women","Highly radiosensitive"],"a":3,"e":"Ans. is `d'' i.e., Highly radiosensitive Desmoid tumour is an aggressive fibromatosis or musculoaponeurotic fibromatosis is a monoclonal fibroblastic proliferation arising in musculoaponeurotic structures. Histologically these tumours are consist of spindle shaped cells in collagenous matrix and lack the pleomorphic, atypical or hyperchromatic nuclei of malignancy. A minority of desmoid tumours are associated with Gardener syndrome and mutations of familial adenomatous polyposis (FAP) gene. Most spontaneous desmoid tumours are associated with mutations of beta-catenin gene.","pyqMatches":[{"year":"2012","no":438,"q":"Regarding desmoid tumour which is not correct ?","o":["Often seen below the umbilicus","Unencapsulated","More common in women","Highly radiosensitive"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8959, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 73, '{"id":8959,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":73,"q":"Burst abdomen most commonly occurs on the","o":["2nd day","3rd day","7th day","9th day"],"a":2,"e":"Ans. is ''c'' i.e., 7\"'' day Burst abdomen occurs mostly between the 7\" and 10th day after operation (but may occur anytime after surgery from 1 to more than 20 days)(ref Sabiston 18/e )","pyqMatches":[{"year":"2014","no":1495,"q":"Burst abdomen most commonly occurs on the","o":["2nd day","3rd day","7th day","9th day"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8960, 'Surgery', 'Vascular Surgery', 'Easy', 'Surgery', 74, '{"id":8960,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Easy","source":"Surgery","sourceNo":74,"q":"False regarding hypernephroma is -","o":["Radiosensitive","Arise from cortex usually from pre existing adenoma","May present with rapidly developing varicocele","Usually adenocarcinoma"],"a":0,"e":"Ans. is ''a'' i.e., Radiosensitive RCC or hypernephroma is one of the most radioresistant and chemoresistant tumors. In men rapidly developing varicocele is rare but impressive sign for RCC occuring most often on the left side. It occurs because left gonadal vein is obstructed where it joins the left renal vein. As already stated RCC originates in the cortex and tends to grow out into perinephric tissue causing characteristic bulge or mass effect. About adenomas Adenomas are the most common benign renal parenchymal lesions. - Despite the classification of adenoma as a benign tumor, no clinical, histologic or immunohistochemical criteria can differentiate renal adenoma from renal carcinoma. Smith''s Urology writes about adenomas ? - \"Previously, all renal tumors less than 3 cm were considered adenomas. However, even such small tumors can metastasize and are now classified as renal cell carcinoma. Adenomas of any size should be treated as a fortuitous finding representative of an early renal cancer, and the patient should be evaluated and treated appropriately.\"","pyqMatches":[{"year":"2015","no":1349,"q":"False regarding hypernephroma is","o":["Radiosensitive","Arise from cortex usually from pre existing adenoma","May present with rapidly developing varicocele","Usually adenocarcinoma"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8961, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 75, '{"id":8961,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":75,"q":"The posterior urethra is best visualized by ?","o":["Static cystogram","Retrograde urethrogram","Voiding cystogram","CT cystogram"],"a":2,"e":"Ans. is ''c'' i.e., Voiding Cystogram Voiding cystourethrography is the best method to visualize posterior urethra. Remember, Urethra can be imaged radiographically in two ways. Anterograde techniques —> Best for visualization of posterior urethra. (This is done along with voiding cystourethrography or with voiding following excretory urography) Retrograde technique —> Best for examining the anterior (penile) urethra (Contrast is injected through tip of urethra).","pyqMatches":[{"year":"2015","no":1351,"q":"The posterior urethra is best visualized by ?","o":["Static cystogram","Retrograde urethrogram","Voiding cystogram","CT cystogram"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8962, 'Surgery', 'Vascular Surgery', 'Easy', 'Surgery', 76, '{"id":8962,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Easy","source":"Surgery","sourceNo":76,"q":"The Grayhack shunt is established between:","o":["Corpora cavernosa and dorsal vein","Corpora cavernosa and saphenous vein","Corpora cavernosa and glans","Corpora cavernosa and corpora spongiosa"],"a":1,"e":"Ans is ''b'' i.e. Corpora cavernosa and saphenous vein The Grayhack shunt is a surgical shunt between corpora cavernosa and the saphenous vein done for the treatment of ischemic priapism. Priapism is an uncommon condition of prolonged erection. It is usually painful for the patient, and no sexual excitement or desire is present. Priapism may be classified into high- and low-flow types (Nonischemic and ischemic). Nonischemic (High flow) priapism: Nonischemic priapism, also termed arterial or high-flow priapism, features elevated vascular flow through the corpora cavernosa. It usually occurs secondary to perineal trauma, which injures the central penile arteries and results in loss of penile blood-flow regulation. Aspiration of penile blood for blood-gas determination demonstrates high oxygen and normal carbondioxide levels. Arteriography is useful to demonstrate aneurysms that will respond to embolization. Erectile function is usually preserved. Ischemic (low-flow) priapism: Ischemic priapism, also termed veno-occlusive or low-flow priapism, features little or absent intracorporal blood flow. It represents a true compartment syndrome involving the penis, needing emergency management. It is typically painful. The corpora cavernosa is tense with congested blood and tender to palpation. The glans penis and corpus spongiosum are soft and uninvolved in the process. The current theories regarding the mechanism of priapism remain in debate, but most authorities believe the major abnormality to be physiologic obstruction of the venous drainage. This obstruction causes buildup of highly viscous, poorly oxygenated blood (low 02, high CO2) within the corpora cavernosa. If the process continues for several days, interstitial edema and fibrosis of the corpora cavernosa will develop, causing impotence. Treatment Ischernic priapism is a urologic emergency. - First-line treatment consists of aspiration of blood and irrigation of the corpora cavernosa (via a needle put in the corpora cavernosa) along with intracavernous injection of an a-adrenergic sympathomimetic agent (phenylephrine) .(Sympathomimetic agents can be expected to exert contractile effects on the cavernous tissue and thus facilitate detumescence.) - Surgical shunting is needed when the intracavernous treatment fails. A surgical shunt has the objective of facilitating blood drainage from the corpora cavernosa, bypassing the veno​occlusive mechanism of these structures. A variety of shunt procedures may be performed. A distal cavernoglanular (corporoglanular) shunt is the first choice.","pyqMatches":[{"year":"2015","no":1341,"q":"The Grayhack shunt is established between:","o":["Corpora cavernosa and dorsal vein","Corpora cavernosa and saphenous vein","Corpora cavernosa and glans","Corpora cavernosa and corpora spongiosa"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8963, 'Surgery', 'Urology', 'Easy', 'Surgery', 77, '{"id":8963,"subject":"Surgery","chapter":"Urology","difficulty":"Easy","source":"Surgery","sourceNo":77,"q":"Which of the following urethral anomaly is the most common -","o":["Hypospadias","Pin hole meatus","Epispadias","Stricture urethra"],"a":0,"e":"Ans. is ''a'' i.e., Hypospadias Hypospadias is a condition in which the urethral meatus opens on the underside of penis* or the perineum (i.e. ventral surface of penis) proximal to the tip of the glans penis. Hypospadias is the most common* congenital malformation of the urethra. (also know that the most common congenital malformatio of the urinary tract is Duplication of renal pelvis*) Occurs in 1:250 male births.","pyqMatches":[{"year":"2015","no":1235,"q":"Which of the following urethral anomaly is the most common","o":["Hypospadias","Pin hole meatus","Epispadias","Stricture urethra"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8964, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 78, '{"id":8964,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":78,"q":"All the features of membranous urethral injury except","o":["blood of meatus","Retention of urine","Pelvic fracture","Perineal butterfly hematoma"],"a":3,"e":"Ans. is ''d''","pyqMatches":[{"year":"2015","no":1241,"q":"All the features of membranous urethral injury except","o":["blood of meatus","Retention of urine","Pelvic fracture","Perineal butterfly hematoma"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8965, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 79, '{"id":8965,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":79,"q":"Congenital hydrocele is best t/t by -","o":["Eversion of sac","Excision of sac","Lords procedure","herniotomy"],"a":3,"e":"Ans. is ''d'' ie. Herniotomy Bailey writes ? \"Congenital hydrocele are a special form of indirect inguinal hernia and are treated by herniotomy.\" Congenital hydrocele In this conditon the processus vaginalis remain patent so there is direct communication of the tunica vaginalis with the peritoneal cavity. The communicating orifice at the deep inguinal ring is too small for the development of hernia. It is present since birth*. In contradication to assumption. congenital hydrocele is not easily reducible* due to narrowness of the deep inguinal ring but when the child lies supine, it disappears.","pyqMatches":[{"year":"2015","no":1348,"q":"Congenital hydrocele is best t/t by","o":["Eversion of sac","Excision of sac","Lords procedure","herniotomy"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8966, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 80, '{"id":8966,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":80,"q":"Which one of the following statement is true of undescended testis -","o":["Usually descends spontaneously at puberty","Orchipexy to be done if no descent by puberty","Has a higher incidence of malignancy","Maintains normal sperm production"],"a":2,"e":"Ans. is ''c'' i.e., Has a higher incidence of malignancy TREATMENT- * Orchidopexy done before 6 months of age * Orchidectomy- patient with incomplete descended testis is atrophic, past puberty and normal testis * Ombredanne’s operation in bilateral cases * HCG or GnRH- cryptorchidism associated with hypogenitalism and obesity * Approximately UDT spontaneously descend by 3 months of age * Secondary sexual characterstics are normal","pyqMatches":[{"year":"2016","no":1298,"q":"Which one of the following statement is true of undescended testis","o":["Usually descends spontaneously at puberty","Orchipexy to be done if no descent by puberty","Has a higher incidence of malignancy","Maintains normal sperm production"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8967, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 81, '{"id":8967,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":81,"q":"What is oliguria -","o":["Excretion of less than 300m1 in 24 hrs","Excretion of less than 500m1 in 24 hrs","Excretion of less than 300 ml. in 12 hrs","Excretion of less than 100 ml. in 24 hrs"],"a":1,"e":"Ans. is ''b'' i.e., Excretion of less than 500 ml in 24 hrs (Note that Bailey & Love 25/e p1279 (24/e p 1300 & 23/e p 1168) write Oliguria to be less than 300 ml in 24 hrs, but we would follow Harrison & CMDT; Note that Smith''s Urology 17/e p531 (16/e, p538) write it to < 400 ml/day!! what an utter confusion.)","pyqMatches":[{"year":"2016","no":1091,"q":"What is oliguria","o":["Excretion of less than 300m1 in 24 hrs","Excretion of less than 500m1 in 24 hrs","Excretion of less than 300 ml. in 12 hrs","Excretion of less than 100 ml. in 24 hrs"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8968, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 82, '{"id":8968,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":82,"q":"Tissue suturing glue contains:","o":["Cyanoacrylate","Ethanolamine oleate","Methacrylate","Polychloroprene"],"a":0,"e":"Ans is ''a'' i.e. Cyanoacrylate Most tissue adhesives or glue are cyanoacrylate polymers, such as n-butyl-2-cyanoacrylate (eg, Histoacryl®, PeriAcryl®) or 2-octyl cyanoacrylate (eg, Dermabond®, Surgiseal). Cyanoacrylate tissue adhesives are liquid monomers that undergo an exothermic reaction on exposure to moisture (eg, on the skin surface), changing to polymers that form a strong tissue bond. When applied to a laceration, the polymer binds the wound edges together to allow normal healing of the underlying tissue. Compared with wounds closed with sutures, the tensile strength of wounds closed by tissue adhesives is less at the time of initial application, but equalizes by one week post-repair. Advantages: Less painful application, and sometimes no need for local anesthetic injection More rapid application and repair time Cosmetically similar results at 12 months post-repair Waterproof barrier Antimicrobial properties Better acceptance by patients No need for suture removal or follow-up Indications and contraindications: For use of tissue adhesives the wound needs to be clean, dry with near perfect hemostasis and under no tension. Complex stellate lesions or crush injuries should not be closed with tissue adhesives since good wound approximation is difficult to achieve. Tissue adhesives are not recommended for lacerations of the hands, feet, or joints, since repetitive movements could cause the adhesive bond to break before sufficient tensile strength is achieved. Tissue adhesives are not recommended for the oral mucosa or other mucosal surfaces or areas of high moisture such as the axillae and perineum. Lacerations involving the hairline or vermilion border require more precision, and should be repaired with traditional sutures.","pyqMatches":[{"year":"2014","no":1542,"q":"Tissue suturing glue contains:","o":["Cyanoacrylate","Ethanolamine oleate","Methacrylate","Polychloroprene"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8969, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 83, '{"id":8969,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":83,"q":"The tensile strength of wound reaches that of tissue by ?","o":["6 weeks","2 months","4 months","None"],"a":3,"e":"Ans. is ''None'' It never equals the tensile strength of unwounded skin. Robbin''s writes- \"How long does it take for a skin wound to achieve its maximal strength? When sutures are removed from an incisional surgical wound, usually at the end of the first week, wound strength is approximately 10% that of unwounded skin. Wound strength increases rapidly over the next 4 weeks, slows down at approximately the third month after the original incision, and reaches a plateau at about 70% to 80% of the tensile strength of unwounded skin.\"","pyqMatches":[{"year":"2013","no":1344,"q":"The tensile strength of wound reaches that of tissue by ?","o":["6 weeks","2 months","4 months","None"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8970, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 84, '{"id":8970,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":84,"q":"The following statement about keloid is true ?","o":["They do not extend into normal skin","Local recurrence is common after excision","They often undergo malignant change","They are more common in whites than in blacks"],"a":1,"e":"Ans. is ''b'' i.e., Local recurrence is common after excision A keloid scar is defined as excessive scar tissue that extends beyond the boundaries of the original incision or wound. Features- It continues to get worse even after 1 year and up to a few years. Severe itching is present Margin is tender Vascular, red, erythematous (immature blood vessels) Extends to normal tissues, has a claw-like process. Hence the name. Risk factors- Black race Tuberculosis patients Incision over the sternum, ear lobe Equal in both sexes Hereditary and familial Vaccination sites, injection sites Treatment- Injection of steroid preparation such as triamcinolone acetate (Kenacort) has been found to be extremely useful. It flattens the keloid. Intra keloidal excision and skin grafting are to be tried last. Recurrence is common. (Any form of excision has a high chance of recurrence) Care should be taken not to extend the incision on to the normal surrounding tissues. Silicone application Topical retinoids","pyqMatches":[{"year":"2012","no":1097,"q":"The following statement about keloid is true ?","o":["They do not extend into normal skin","Local recurrence is common after excision","They often undergo malignant change","They are more common in whites than in blacks"],"a":1,"source":"NEET_2012_Paper.pdf"},{"year":"2018","no":150,"q":"The following statement about Keloid is true","o":["It contain growth factor","Extended excision is the treatment of choice","It do not extend beyond the wound","None of the above"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2012","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8971, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 85, '{"id":8971,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":85,"q":"The Vitamin which has inhibitory effect on wound healing is -","o":["Vitamin -A","Vitamin - E","Vitamin -C","Vitamin B-complex"],"a":1,"e":"Ans. is ''b'' i.e., Vitamin-E. Systemic vitamin E and glucocorticoids inhibit the inflammatory response and collagen synthesis, thereby possibly impeding the healing process.","pyqMatches":[{"year":"2015","no":1204,"q":"The Vitamin which has inhibitory effect on wound healing is","o":["Vitamin -A","Vitamin - E","Vitamin -C","Vitamin B-complex"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8972, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 86, '{"id":8972,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":86,"q":"Best skin disinfectant for central line insertion is:","o":["Povione iodine","Alcohol","Cetrimide","Chlorhexidine"],"a":3,"e":"Ans is ''d'' i.e. Chlorhexidine \"Chlorhexidine is now the disinfectant recommended for all catheter placement procedures and for routine site cleansing during dressing changes.\"- Comprehensive Hospital Medicine: An Evidence-Based And Systems Approach By Mark V. Williams, Scott A. Flanders, p320 \"Use of antiseptic solution for skin disinfection at the catheter insertion site helps prevent catheter-related infection. Chlorhexidine- based solutions appear to be superior to both aqueous and alcohol- based povidone-iodine in reducing the risk for catheter colonization and catheter-related bloodstream infection. If there is a contraindication to chlorhexidine, tincture of iodine, an iodophor or 70 percent alcohol can be used as alternatives\"-uptodate.com","pyqMatches":[{"year":"2012","no":1095,"q":"Best skin disinfectant for central line insertion is:","o":["Povione iodine","Alcohol","Cetrimide","Chlorhexidine"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8973, 'Surgery', 'Hepatobiliary & Pancreas', 'Easy', 'Surgery', 87, '{"id":8973,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Easy","source":"Surgery","sourceNo":87,"q":"Complication of total parenteral nutrition include ?","o":["Hyperglycemia","Hyperkalemia","Hyperosmolar dehydration","a and b"],"a":3,"e":"Ans. is ''a'' i.e. Hyperglycemia, ''b'' i.e. Hyperkalemia Metabolic complication Azotemia Essential fatty acid def. Fluid overload Metabolic bone ds. Liver dysfunction Glucose imbalance (Hyperglycemia, hypoglycemia) Trace elements & vitamin deficiency Electrolyte abnormalities n Hypernatremia, hyponatremia n Hyperkalemia, hypokalemia a Hyperphosphatemia, hypophosphatemia n Hypermagnesemia, hypomagnesemia n Hypercalcemia, hypocalcemia n High serum zinc, low serum zinc n High serum copper, low serum copper","pyqMatches":[{"year":"2013","no":1354,"q":"Complication of total parenteral nutrition include ?","o":["Hyperglycemia","Hyperkalemia","Hyperosmolar dehydration","a and b"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8974, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 88, '{"id":8974,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":88,"q":"Content of Na'' in ringer lactate is meq/1-","o":["154","12","130","144"],"a":2,"e":"Ans. is ''c'' i.e., 130","pyqMatches":[{"year":"2016","no":1385,"q":"Content of Na'' in ringer lactate is meq/1","o":["154","12","130","144"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8975, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 89, '{"id":8975,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":89,"q":"Actinomycosis is sensitive to ?","o":["Streptomycin","Nystatin","PenciIlin","Iodox - uridine"],"a":2,"e":"Ans. is ''c'' i.e., Pencillin","pyqMatches":[{"year":"2012","no":697,"q":"Actinomycosis is sensitive to ?","o":["Streptomycin","Nystatin","PenciIlin","Iodox - uridine"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8976, 'Surgery', 'Transplantation', 'Easy', 'Surgery', 90, '{"id":8976,"subject":"Surgery","chapter":"Transplantation","difficulty":"Easy","source":"Surgery","sourceNo":90,"q":"Liver transplantation was first done by ?","o":["Starzl","Huggins","Carrel","Christian Benard"],"a":0,"e":"Ans. is ''a'' i.e., Starzl The first human liver transplant was performed in 1963 by Dr. Thomas Starzl.","pyqMatches":[{"year":"2014","no":1540,"q":"Liver transplantation was first done by ?","o":["Starzl","Huggins","Carrel","Christian Benard"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8977, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 91, '{"id":8977,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":91,"q":"True about Marjolins ulcer -","o":["Develops in long standing scar","Sq cell Ca develops","Slow growing lesion","All"],"a":3,"e":"Ans is ''a'' i.e. Develops in long standing scar; ''b'' i.e. sq cell Ca develops; ''c'' i.e. Slow growing lesion Baghdad sore or oriental sore or Delhi boil is caused by Leishmania Tropica.","pyqMatches":[{"year":"2013","no":1394,"q":"True about Marjolins ulcer","o":["Develops in long standing scar","Sq cell Ca develops","Slow growing lesion","All"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8978, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 92, '{"id":8978,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":92,"q":"Ainhum is seen in ?","o":["Base of great toe","Base of fingers tips","Base of toe","Ankle"],"a":2,"e":"Ans. is ''c'' i.e., Base of Toe Ainhum : is a condition usually affecting Negro males (but some females) who have run barefoot in child hood. Clinical Features : A fissure appears at interphalangeal joint of toe - usually the fifth. This fissure becomes a fibrous band, encircles the digit and causes necrosis.","pyqMatches":[{"year":"2015","no":1317,"q":"Ainhum is seen in ?","o":["Base of great toe","Base of fingers tips","Base of toe","Ankle"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8979, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 93, '{"id":8979,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":93,"q":"How much length is increased in Z plasty when it is done at 60 degrees?","o":["25%","50%","75%","100%"],"a":2,"e":"Ans is ''c'' i.e. 75% Z-plasty is a very common interposition surgical technique utilized in plastic and reconstructive surgery to revise scars. In general, the greater the angle, the greater the gain in wound length. Tissue Lengthening with Z-Plasty Type of Z-Plasty Increase in Length of Central Limb (%) 50 Simple 45-degree Simple 60-degree 75 Simple 90-degree 100 Four-flap with 60-degree angles 150 Double-opposing 75 Five-flap 125 Or Angles compared to gain in length are as follows: 30-degree angle results in a 25% gain in length 45-degree angle results in a 50% gain in length 60-degree angle results in a 75% gain in length 75-degree angle results in a 100% gain in length 90-degree angle results in a 125% gain in length","pyqMatches":[{"year":"2012","no":1090,"q":"How much length is increased in Z plasty when it is done at 60 degrees?","o":["25%","50%","75%","100%"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8980, 'Surgery', 'Vascular Surgery', 'Easy', 'Surgery', 94, '{"id":8980,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Easy","source":"Surgery","sourceNo":94,"q":"The procedure of choice for the evaluation of aortic aneurysm is -","o":["Ultasonography","Computed tomography","Magnetic resonance imaging","Arteriography"],"a":1,"e":"Ans. is ''b'' i.e. Computed tomography \"CT is the most precise test for imaging aortic aneurysm\" - Sabiston ''As a preoperative scanning tool, CT scan is the gold standard. Angiography has largely been replaced by contrast CT scanning\" - Schwartz","pyqMatches":[{"year":"2013","no":1357,"q":"The procedure of choice for the evaluation of aortic aneurysm is","o":["Ultasonography","Computed tomography","Magnetic resonance imaging","Arteriography"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8981, 'Surgery', 'Endocrine Surgery', 'Easy', 'Surgery', 95, '{"id":8981,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Easy","source":"Surgery","sourceNo":95,"q":"Pseudoclaudication is caused by","o":["Femoral Artery stenosis","Popliteal Artery stenosis","Lumbar canal stenosis","Radial Artery stenosis"],"a":2,"e":"Ans is C i.e. Lumbar Canal Stenosis Pseudoclaudication is the term used for neurogenic claudication caused due to lumbar canal stenosis. Its symptoms mimic intermittent claudication of PVD. Neurogenic claudication, consists of back and buttock or leg pain induced by walking or standing and relieved by sitting or changing posture. Symptoms in the legs are usually bilateral. Unlike vascular claudication, symptoms are often provoked by standing without walking. Spinal stenosis can be acquired, congenital, or due to a combination of these factors. Congenital causes include achondroplasia, idiopathic. Acquired causes are degenerative diseases (spondylosis, spondylolisthesis, scoliosis), trauma, spine surgery, metabolic or endocrine disorders (epidural lipomatosis, osteoporosis, acromegaly, renal osteodystrophy, hypoparathyroidism), and Paget''s disease. Difference between Vascular and Neurogenic claudication Patients with vascular claudication always have pain when they walk a relatively constant distance on level ground; they do not have variable days when they can walk for considerably greater distances without pain. Patients of vascular claudication, often know exactly how far or for how long they can walk before the symptoms will occur. This is in contrast to patients with neurogenic claudication where the symptoms occasionally occur at rest or at with highly variable walking distances. Pain in neurogenic claudication can even occur on standing. Pain of vascular claudication gets relieved on stopping within few minutes, and this resolution of pain occurs even if the patient simply stops and stands in place. Patients with neurogenic claudication usually have to sit down to relieve their pain. Neurogenic claudication pain gets relieved by changing posture and leaning forwards. Patients with neurogenic claudication often can walk further on an incline, whereas vascular claudication is marked worsened if the patient is on an incline.","pyqMatches":[{"year":"2015","no":1224,"q":"Pseudoclaudication is caused by","o":["Femoral Artery stenosis","Popliteal Artery stenosis","Lumbar canal stenosis","Radial Artery stenosis"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8982, 'Surgery', 'Neurosurgery', 'Easy', 'Surgery', 96, '{"id":8982,"subject":"Surgery","chapter":"Neurosurgery","difficulty":"Easy","source":"Surgery","sourceNo":96,"q":"Kaposi sarcoma is commonly seen in ?","o":["Upper limbs","Lower limbs","Head and Neck","Trunk"],"a":1,"e":"Ans. is ''b'' i.e., Lower limbs \" It occurs predominantly on the skin and can involve virtually any organ, perhaps except the brain. The initially described form, now known as classic KS, predominantly involves the lower extremities of elderly men. KS is now the most common tumor seen in HIV- infected patients\"- Devita''s Oncology","pyqMatches":[{"year":"2015","no":1177,"q":"Kaposi sarcoma is commonly seen in ?","o":["Upper limbs","Lower limbs","Head and Neck","Trunk"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8983, 'Surgery', 'Vascular Surgery', 'Moderate', 'Surgery', 97, '{"id":8983,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":97,"q":"All of the following are risk factors for deep vein thrombosis (DVT) except -","o":["Duration of surgery more than thirty minutes","Obesity","Age less than forty years","Use of the oestrogen-progesterone contraceptive pills"],"a":2,"e":"Ans. is ''c'' i.e., Age less than 40 years","pyqMatches":[{"year":"2012","no":1092,"q":"All of the following are risk factors for deep vein thrombosis (DVT) except","o":["Duration of surgery more than thirty minutes","Obesity","Age less than forty years","Use of the oestrogen-progesterone contraceptive pills"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8984, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 98, '{"id":8984,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":98,"q":"DVT, investigation of choice is -","o":["Doppler","Plethysmography","Venography","X-ray"],"a":0,"e":"Answer is ''a'' i.e. Doppler Doppler USG is the first investigation of choice for DVT.","pyqMatches":[{"year":"2013","no":1768,"q":"DVT, investigation of choice is","o":["Doppler","Plethysmography","Venography","X-ray"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8985, 'Surgery', 'Vascular Surgery', 'Moderate', 'Surgery', 99, '{"id":8985,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":99,"q":"Surgery in varicose veins is NOT attempted in presence of -","o":["Deep vein thrombosis","Multiple incompetent perforators","Varicose veins with leg ulcer","All of the above"],"a":0,"e":"Ans. is ''a'' i.e., Deep vein thrombosis Deep vein thrombosis is a contraindication for varicose veins. Varicose vein surgery should never be attempted in a case where deep vein thrombosis exists along with varicose veins, because in these cases superficial veins are the only valved venous pathway and excising them will only aggravate the condition.","pyqMatches":[{"year":"2013","no":1360,"q":"Surgery in varicose veins is NOT attempted in presence of","o":["Deep vein thrombosis","Multiple incompetent perforators","Varicose veins with leg ulcer","All of the above"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8986, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 100, '{"id":8986,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":100,"q":"Treatment of rib fracture ?","o":["Immediate thoracotomy","IPPV","Analgesics","b and c"],"a":2,"e":"Answer is ''c'' i.e. Analgeic Rib fractures are the most common injuries after blunt chest trauma. Ribs 4 to 10 are usually fractured. Management of # rib - Pain control with oral or i.v. analgesics or intercostal nerve blocks or epidural analgesia.(Poor pain control significantly contributes to complications such as atelectasis and pneumonia) - Chest strapping is no longer advised. Management of flail chest, as mentioned in previous question, may need IPPV.","pyqMatches":[{"year":"2014","no":1527,"q":"Treatment of rib fracture ?","o":["Immediate thoracotomy","IPPV","Analgesics","b and c"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8987, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 101, '{"id":8987,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":101,"q":"Trauma and Injury Severity Score (TRISS) includes:","o":["GCS + BP + RR","RTS + ISS + Age","RTS + ISS + GCS","RTS + GCS + Age"],"a":1,"e":"Ans is `b'' i.e. RTS + ISS + Age TRISS (Trauma and Injury Severity Score) : Injury Severity Score Revised Trauma Score Age Mechanism of Injury (blunt/penetrating)","pyqMatches":[{"year":"2015","no":1360,"q":"Trauma and Injury Severity Score (TRISS) includes:","o":["GCS + BP + RR","RTS + ISS + Age","RTS + ISS + GCS","RTS + GCS + Age"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8988, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 102, '{"id":8988,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":102,"q":"Treatment of choice for stab injury caecum ?","o":["Caecostomy","Ileo-transverse anastomosis","Transverse colostomy","Sigmoid colostomy"],"a":1,"e":"Ans. is ''b'' i.e., ileo-transverse anastomosis Stab and low-velocity injuries to the colon with minimal contamination and hemodynamical stability can be managed by primary repair mechanisms like ileotransverse anastomosis.","pyqMatches":[{"year":"2016","no":649,"q":"Treatment of choice for stab injury caecum ?","o":["Caecostomy","Ileo-transverse anastomosis","Transverse colostomy","Sigmoid colostomy"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8989, 'Surgery', 'Vascular Surgery', 'Moderate', 'Surgery', 103, '{"id":8989,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":103,"q":"Brain abscess in cyanotic heart disease is commonly located in","o":["Cerebellar hemisphere","Thalamus","Temporal lobe","Parietal lobe"],"a":3,"e":"Ans. is ''d'' i.e. Parietal lobe Brain abscesses in congenital cyanotic heart diseases occur due to hematogenous seeding of bloodborne bacteria. These blood borne bacteria bypass the pulmonary capillary bed d/t right to left shunt. They commonly infect parietal & frontal lobes (territory of middle cerebral artery). Location of Brain Abscesses Etiology Location Otitis media, mastoiditis Temporal lobe > Cerebellum Paranasal sinusitis, dental inf. Frontal lobes Hematogenous Parietal lobe, post-frontal lobes (MCA territory)","pyqMatches":[{"year":"2013","no":1447,"q":"Brain abscess in cyanotic heart disease is commonly located in","o":["Cerebellar hemisphere","Thalamus","Temporal lobe","Parietal lobe"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8990, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 104, '{"id":8990,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":104,"q":"All are true about carcinoma palate, except -","o":["Slow growing","Bilateral lymphatic spread","Adenocarcinoma","Presents with pain"],"a":3,"e":"Ans. is ''d'' i.e., Presents with pain","pyqMatches":[{"year":"2015","no":1336,"q":"All are true about carcinoma palate, except","o":["Slow growing","Bilateral lymphatic spread","Adenocarcinoma","Presents with pain"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8991, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 105, '{"id":8991,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":105,"q":"Epulis arises from -","o":["Enamel","Root of teeth","Gingiva","Pulp"],"a":2,"e":"Answer is ''c'' i.e. Gingiva Epulis literally means ''upon the gum''. Thus it is a swelling situated on the gum. It can originate from the mucous membrane, the periosteum or the bone giving rise to different varieties of Epulis.","pyqMatches":[{"year":"2012","no":1133,"q":"Epulis arises from","o":["Enamel","Root of teeth","Gingiva","Pulp"],"a":2,"source":"NEET_2012_Paper.pdf"},{"year":"2015","no":1363,"q":"Epulis arises from","o":["Enamel","Root of teeth","Gingiva","Pulp"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2012","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8992, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 106, '{"id":8992,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":106,"q":"Commonest site of carcinoma tongue -","o":["Apical","Lateral borders","Dorsum","Posterior 1/3"],"a":1,"e":"Ans. is ''b'' i.e., Lateral borders Most common site is middle of the lateral border or the ventral aspect of the tongue.","pyqMatches":[{"year":"2013","no":1398,"q":"Commonest site of carcinoma tongue","o":["Apical","Lateral borders","Dorsum","Posterior 1/3"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8993, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 107, '{"id":8993,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":107,"q":"In case of benign mixed parotid tumours T/t of choice is -","o":["Superficial Parotidectomy","Total parotidectomy","Leave facial nerve and remove all gland","Radical Parotidectomy"],"a":0,"e":"Ans is ''a'' ie Superficial parotidectomy Schwartz writes - \"Treatment of benign neoplasms is surgical excision of the affected gland or, in the case of the parotid, excision of the superficial lobe with facial nerve dissection and preservation. The minimal surgical procedure for neoplasms of the parotid is superficial parotidectomy with preservation of the facial nerve. ''Shelling out'' of the tumor mass is not recommended because of the risk of incomplete excision and tumor spillage.\" Superficial parotidectomy is the treatment of choice for most benign tumors in the superficial lobe.","pyqMatches":[{"year":"2014","no":1537,"q":"In case of benign mixed parotid tumours T/t of choice is","o":["Superficial Parotidectomy","Total parotidectomy","Leave facial nerve and remove all gland","Radical Parotidectomy"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8994, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 108, '{"id":8994,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":108,"q":"True regarding cystic hygroma is -","o":["Non transilluminant","Lined by columnar epithelium epithelium","Develops from jugular lymphatic sequestration","All"],"a":2,"e":"Ans. is c i.e., Develops from jugular lymphatic sequestration Cystic hygroma Cystic hygroma is a swelling usually occuring in the lower third of the neck It is most commonly seen in posterior triangle of the neck, but may also occur in axilla, groin & mediastinum It results due to sequestration of a portion of the jugular lymph sac from the lymphatic system. It usually manifests in the neonate or in early infancy (occasionally present at birth) The swelling is soft and partially compressible and invariably increases in size when the child coughs or cries. The characteristic that distinguishes it from all other neck swellings is that it is brilliantly translucent. The cysts are filled with clear lymph and are lined by endothelium. Mostly these are multiple cysts but occasionally they can be unilocular. It may show spontaneous regression. Treatment [Ref.: Sabiston 18/e p2053; Schwartz 9/e p1415] There are two methods of treatment: Surgical excision & Sclerotherapy Sabiston writes- \"Complete surgical excision is the preferred treatment; however, this may be impossible because of the hygroma infiltrating within and around important neurovascular structures. Because hygromas are not neoplastic tumors, radical resection with removal of major blood vessels and nerves is not indicated. Injection of sclerosing agents such as bleomycin or the derivative of Streptococcus pvogenes OK-432 have also been reported to be effective in the management of cystic hygromas. Intracystic injection of sclerosants appears to be most effective for macrocystic hygromas, as opposed to the microcystic variety.\" \"The modern management of most cystic hygromas includes the combination of surgical excision and image-guided sclerotherapy.\"- Schwartz","pyqMatches":[{"year":"2015","no":1283,"q":"True regarding cystic hygroma is","o":["Non transilluminant","Lined by columnar epithelium epithelium","Develops from jugular lymphatic sequestration","All"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8995, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 109, '{"id":8995,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":109,"q":"The best treatment for cystic hygroma is -","o":["Surgical excision","Radiotherapy","Sclerotherapy","Chemotherapy"],"a":0,"e":"Ans. is ''a'' i.e., Surgical Excision Definitive treatment is complete excision of the cyst at an early age.","pyqMatches":[{"year":"2016","no":1318,"q":"The best treatment for cystic hygroma is","o":["Surgical excision","Radiotherapy","Sclerotherapy","Chemotherapy"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8996, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 110, '{"id":8996,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":110,"q":"Sistrunk''s operation is used in","o":["Parotid tumour","Thyroglossal fistula","Thyroglossal cyst","b and c"],"a":3,"e":"Ans. Two options are correct i.e., ''b'' i.e. Thyroglossal fistula & ''c'' i.e. Thyroglossal cyst Sistrunk procedure is used for excision of thyroglossal duct cyst","pyqMatches":[{"year":"2013","no":1391,"q":"Sistrunk''s operation is used in","o":["Parotid tumour","Thyroglossal fistula","Thyroglossal cyst","b and c"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8997, 'Surgery', 'Vascular Surgery', 'Easy', 'Surgery', 111, '{"id":8997,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Easy","source":"Surgery","sourceNo":111,"q":"Adson''s test is positive in -","o":["Cervical rib","Cervical spondylosis","Cervical fracture","Cervical dislocation"],"a":0,"e":"Ans. is ''a'' i.e., Cervical rib Adson''s test is a provocative test for Thoracic Outlet Syndrome accompanied by compression of the Subclavian artery by a cervical rib or tightened anterior and middle scalene muscles.","pyqMatches":[{"year":"2015","no":1230,"q":"Adson''s test is positive in","o":["Cervical rib","Cervical spondylosis","Cervical fracture","Cervical dislocation"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8998, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 112, '{"id":8998,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":112,"q":"Neuroblastomas - good prognositc factor is ?","o":["N-myc amplification","RAS oncogene","Hyperdiploidy","Translocations"],"a":2,"e":"Answer is ''c'' i.e. Hyperdiploidy","pyqMatches":[{"year":"2015","no":481,"q":"Neuroblastomas - good prognositc factor is ?","o":["N-myc amplification","RAS oncogene","Hyperdiploidy","Translocations"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (8999, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 113, '{"id":8999,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":113,"q":"Opsoclonus - Myoclonus is a phenomenon seen in ?","o":["Wilms tumor","Neuroblastoma","Meningioma","Cortical tuberculoma"],"a":1,"e":"Ans. is ''b'' i.e., Neuroblastoma Opsoclonus is a disorder of eye movement characterized by involuntary, chaotic saccades that occur in all directions of gaze. It is frequently associated with myoclonus and ataxia. Opsoclonus-myoclonus may be cancer-related or idiopathic. When the cause is paraneoplastic, the tumors involved are usually cancer of the lung and breast in adults and neuroblastoma in children.","pyqMatches":[{"year":"2012","no":1176,"q":"Opsoclonus - Myoclonus is a phenomenon seen in ?","o":["Wilms tumor","Neuroblastoma","Meningioma","Cortical tuberculoma"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9000, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 114, '{"id":9000,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":114,"q":"In thymoma, all are seen except -","o":["Hypogamma globulinemia","Hyperalbuminemia","Red cell aplasia","Myaesthenia Gravis"],"a":1,"e":"Ans is (b) i.e. hyperalbuminemia Thymoma is the most common Anterior mediastinal mass. Thymomas are seen to be associated with Myasthenia gravis Acquired hypogammaglobulinemia Pure red cell aplasia Grave''s ds - Pernicious anemia - Dermatomyositis-polymyositis - Cushing syndrome","pyqMatches":[{"year":"2012","no":503,"q":"In thymoma, all are seen except","o":["Hypogamma globulinemia","Hyperalbuminemia","Red cell aplasia","Myaesthenia Gravis"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9001, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 115, '{"id":9001,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":115,"q":"Intralobar sequestration of lung takes its blood supply from -","o":["Internal mammary artery","Descending abdominal aorta","Pulmonary artery","None of the above"],"a":1,"e":"Ans. is ''b'' i.e., Descending abdominal aorta A sequestration consists of normally developed bronchioles and alveoli supplied by systemic rather than pulmonary arteries. This blood supply is from the Aorta either above or below the diaphragm. Mostly (approx 95%) this is from the descending thoracic aorta. Other characteristic features of sequestration - They occur most commonly in the lower lobes, L > R . Lung sequestrations are of two types","pyqMatches":[{"year":"2014","no":1535,"q":"Intralobar sequestration of lung takes its blood supply from","o":["Internal mammary artery","Descending abdominal aorta","Pulmonary artery","None of the above"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9002, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 116, '{"id":9002,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":116,"q":"Foreign body aspiration in supine position causes which of the following parts of the lung commonly to be affected -","o":["Apical left lobe","Apical lobe of right lung","Apical part of the lower lobe","Posterobasal segment of left lung"],"a":2,"e":"Ans. is ''c'' i.e. Apical part of right lower lobe Right upper lobe - posterior segment Right lower lobe - superior segment Left lower lobe - superior segment Right basilar segments (of lower lobe)","pyqMatches":[{"year":"2014","no":1534,"q":"Foreign body aspiration in supine position causes which of the following parts of the lung commonly to be affected","o":["Apical left lobe","Apical lobe of right lung","Apical part of the lower lobe","Posterobasal segment of left lung"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9003, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 117, '{"id":9003,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":117,"q":"IVC filter is used in following except -","o":["To reduces symptoms","Negligible size of emboli","To prolong life","To prevent progress of native blood vessel disease"],"a":1,"e":"Answer is ''b'' i.e. Negligible size of emboli","pyqMatches":[{"year":"2012","no":53,"q":"IVC filter is used in following except","o":["To reduces symptoms","Negligible size of emboli","To prolong life","To prevent progress of native blood vessel disease"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9004, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 118, '{"id":9004,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":118,"q":"Empyema necessitans is defined as so when ?","o":["Plural empyema is under pressure","Pleural empyema has ruptured into bronchus","Pleural empyema has ruptured into the pericardium","Pleural empyema is showing extension to the subcutaneous tissue"],"a":3,"e":"Ans. is ''d'' i.e., Pleural empyema is showing extension to the subcutaneous tissue","pyqMatches":[{"year":"2016","no":1083,"q":"Empyema necessitans is defined as so when ?","o":["Plural empyema is under pressure","Pleural empyema has ruptured into bronchus","Pleural empyema has ruptured into the pericardium","Pleural empyema is showing extension to the subcutaneous tissue"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9005, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'Surgery', 119, '{"id":9005,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":119,"q":"All of the following about Gastrointestinal carcinoid tumors are true, Except:","o":["Small intestine and appendix account for almost 60% of all gastrointestinal carcinoid","5 year survival for carcinoid tumors is >60%","Rectum is spared","Appendicial carcinoids are more common in females than males"],"a":2,"e":"Ans is ''c'' i.e. Rectum is spared Rectum is not spared, but is infact a common site for carinoid tumor. About other options: 5 year survival for carcinoid tumors is >60% Sabiston writes-\" Carcinoid tumors have the best prognosis of all small bowel tumors, whether the disease is localized or metastatic. Resection of a carcinoid tumor localized to its primary site approaches a 100% survival rate. Five-year survival rates are about 65% among patients with regional disease and 25% to 35% among those with distant metastasis.\" Appendicial carcinoids are more common in females than males \"Appendicial carcinoids are more common in females. Two to three cases of appendecial carcinoids are female.\"- Sleisenger and Fordtran''s Gastrointestinal and Liver Disease 8/e p609 Small intestine and appendix account for almost 60% of all gastrointestinal carcinoid Data from various books vary but as far as the question goes this can be taken to be true as option ''c'' is definitely wrong. In GIT small intestine and the appendix are the most common sites. Infact small intestine is the 2nd most common site in body after bronchus. [Note that several textbooks including Schwartz and Sabiston, mention Appendix as the most common site of GI carcinoids, which is not true according SEER data (given in Harrison)]","pyqMatches":[{"year":"2015","no":1353,"q":"All of the following about Gastrointestinal carcinoid tumors are true, Except:","o":["Small intestine and appendix account for almost 60% of all gastrointestinal carcinoid","5 year survival for carcinoid tumors is >60%","Rectum is spared","Appendicial carcinoids are more common in females than males"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9006, 'Surgery', 'Breast Surgery', 'Moderate', 'Surgery', 120, '{"id":9006,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":120,"q":"Radiation exposure during infancy has been linked to which one of the following carcinoma -","o":["Breast","Melanoma","Thyroid","Lung"],"a":2,"e":"Ans. is ''c'' i.e., Thyroid \"Differentiated thyroid carcinoma particularly papillary variety frequently follows accidental irradiation of thyroid in infancy and childhood\" - Bailey Radiation induced cancers Radiation may induce some non-lethal changes in DNA sequences which may cause malignant transformation","pyqMatches":[{"year":"2012","no":436,"q":"Radiation exposure during infancy has been linked to which one of the following carcinoma","o":["Breast","Melanoma","Thyroid","Lung"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9007, 'Surgery', 'Urology', 'Moderate', 'Surgery', 121, '{"id":9007,"subject":"Surgery","chapter":"Urology","difficulty":"Moderate","source":"Surgery","sourceNo":121,"q":"Smoking may be associated with all of the following cancers, except:","o":["Ca Larynx","Ca Nasopharynx","Ca Bladder","None"],"a":3,"e":"Ans is None > Ca Nasopharynx All the given options are mentioned by Harrison: Harrison 17/e p2737 writes- \"Tobacco smoking causes cancer of the lung, oral cavity, naso-, oro-, and hypopharynx, nasal cavity and paranasal sinuses, larynx, esophagus, stomach, pancreas, liver, kidney (body and pelvis), ureter, urinary bladder, and uterine cervix and also causes myeloid leukemia. There is evidence suggesting that cigarette smoking may play a role in increasing the risk of colorectal and possibly premenopausal breast cancer, but there is no association with postmenopausal breast cancer. There does not appear to be a causal link between cigarette smoking and cancer of the endometrium, and there is a lower risk of uterine cancer among postmenopausal women who smoke.\" Thus the answer should be none, however Nasopharyngeal carcinoma is found to be least associated with smoking. Head & Neck Cancers by Enslow Jacobs 2003e p492 writes-\"Association between smoking and nasopharyngeal carcinoma has been shown only by a few studies. If the association of tobacco and NPC is real, the possible mechanism of tumor induction would be the nitrosamines and its precursors in tobacco.\"","pyqMatches":[{"year":"2015","no":1200,"q":"Smoking may be associated with all of the following cancers, except:","o":["Ca Larynx","Ca Nasopharynx","Ca Bladder","None"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9008, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 122, '{"id":9008,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":122,"q":"What is the treatment of choice in desmoid tumors ?","o":["Irradiation","Wide excision","Local excision","Local excision following radiation"],"a":1,"e":"Ans. is ''b'' i.e., Wide excision","pyqMatches":[{"year":"2015","no":1324,"q":"What is the treatment of choice in desmoid tumors ?","o":["Irradiation","Wide excision","Local excision","Local excision following radiation"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9009, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 123, '{"id":9009,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":123,"q":"The commando operation is -","o":["Abdomino-perineal resection of the rectum for carcinoma","Disarticulation of the hip for gas gangrene of the leg","Extended radical mastectomy","Excision of carcinoma of the tongue, the floor of the mouth, part of the jaw and lymph nodes enbloc"],"a":3,"e":"Ans. is ''d'' i.e., Excision of carcinoma of the tongue, the floor of the mouth, part of the jaw and lymph nodes enbloc","pyqMatches":[{"year":"2013","no":1347,"q":"The commando operation is","o":["Abdomino-perineal resection of the rectum for carcinoma","Disarticulation of the hip for gas gangrene of the leg","Extended radical mastectomy","Excision of carcinoma of the tongue, the floor of the mouth, part of the jaw and lymph nodes enbloc"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9010, 'Surgery', 'Urology', 'Easy', 'Surgery', 124, '{"id":9010,"subject":"Surgery","chapter":"Urology","difficulty":"Easy","source":"Surgery","sourceNo":124,"q":"Corpora amylaciae is seen in -","o":["Thymus","Lymph node","Spleen","Prostate"],"a":3,"e":"Ans. is ''d'' i.e., Prostate","pyqMatches":[{"year":"2012","no":28,"q":"Corpora amylaciae is seen in","o":["Thymus","Lymph node","Spleen","Prostate"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9011, 'Surgery', 'Neurosurgery', 'Easy', 'Surgery', 125, '{"id":9011,"subject":"Surgery","chapter":"Neurosurgery","difficulty":"Easy","source":"Surgery","sourceNo":125,"q":"Stereotactic radiosurgery is done for -","o":["Glioblastoma multiforme","Medulloblastoma spinal cord","Ependymoma","AV malformation of brain"],"a":3,"e":"Ans. is ''D'' i.e., AV malformation of brain It is also used for-","pyqMatches":[{"year":"2015","no":1647,"q":"Stereotactic radiosurgery is done for","o":["Glioblastoma multiforme","Medulloblastoma spinal cord","Ependymoma","AV malformation of brain"],"a":3,"source":"NEET_2015_Paper.pdf"},{"year":"2016","no":1749,"q":"Stereotactic radiosurgery is done for","o":["Glioblastoma multiforme","Medulloblastoma spinal cord","Ependymoma","AV malformation of brain"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2015","2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9012, 'Surgery', 'Hepatobiliary & Pancreas', 'Moderate', 'Surgery', 126, '{"id":9012,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Moderate","source":"Surgery","sourceNo":126,"q":"In which one of the following conditions is gas under diaphragm not seen-","o":["Perforated duodenal ulcer","Typhoid perforation","After laparotomy","Spontaneous rupture of oesophagus"],"a":3,"e":"Ans. is ''d'' i.e., Spontaneous rupture of oesophagus Chilaiditi''s syndrome : Condition characterised by inter position of small or large bowel between liver and right diaphragm. Radiologically it gives gas under diaphragm. Iatrogenic pneumoperitoneum : Certain procedure like peritoneal dialysis, Iatrogenically air pushed before putting PD cannula to avoid injury of viscera in such case gas under diaphragm can be seen. All cases when intestine or viscera preforat we can get gas under diaphragm.","pyqMatches":[{"year":"2013","no":1486,"q":"In which one of the following conditions is gas under diaphragm not seen","o":["Perforated duodenal ulcer","Typhoid perforation","After laparotomy","Spontaneous rupture of oesophagus"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9013, 'Surgery', 'General Principles & Wounds', 'Hard', 'Surgery', 127, '{"id":9013,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Hard","source":"Surgery","sourceNo":127,"q":"All of the following are true regarding fluid resuscitation in burn patients except:","o":["Consider intravenous resuscitation in children with burns greater than 15% TBSA","Oral fluids must contain salts","Most preferred fluid is Ringer''s lactate","Half of the calculated volume of fluid should be given in first 8 hours"],"a":0,"e":"Ans. A: Consider intravenous resuscitation in children with burns greater than 15% TBSA In children with burns over 10% TBSA and adults with 15% TBS, consider the need for intravenous fluid resuscitation. If oral resuscitation is to be commenced, it is important that the water given is not salt free. Preferred fluid: Lactated Ringer''s Solution, because it is: * Isotonic * Cheap * Easily stored - Resuscitation formulas: Parkland formula most commonly used - Fluid calculation: 4 x weight in kg x %TBSA burn - Give 1/2 of that volume in the first 8 hours. Give other 1/2 in next 16 hours - TBSA: Total burns surface area.","pyqMatches":[{"year":"2016","no":1317,"q":"All of the following are true regarding fluid resuscitation in burn patients except:","o":["Consider intravenous resuscitation in children with burns greater than 15% TBSA","Oral fluids must contain salts","Most preferred fluid is Ringer''s lactate","Half of the calculated volume of fluid should be given in first 8 hours"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9014, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 128, '{"id":9014,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":128,"q":"The following is the commonest site for venous ulcer: March 2013 (a, e)","o":["Lower third of leg and ankle","Instep of foot","Lower 2/ 3rd of leg","Middle 1/3rd of leg"],"a":0,"e":"Ans. A i.e. Lower third of leg and ankle Venous ulcers usually lie just proximal to the medial or lateral malleolus. Venous ulcers are accompanied by lipodermatosclerosis and hemosiderosis (if these are not present then the ulcer is probably not of venous origin).","pyqMatches":[{"year":"2014","no":1552,"q":"The following is the commonest site for venous ulcer: March 2013 (a, e)","o":["Lower third of leg and ankle","Instep of foot","Lower 2/ 3rd of leg","Middle 1/3rd of leg"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9015, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 129, '{"id":9015,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":129,"q":"Which of the following is spared in lumbar sympathectomy: September 2009","o":["L1","L2","L3","L4"],"a":0,"e":"Ans. A: Ll To preserve sexual functions, Ll is preserved.","pyqMatches":[{"year":"2016","no":1333,"q":"Which of the following is spared in lumbar sympathectomy: September 2009","o":["L1","L2","L3","L4"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9016, 'Surgery', 'Vascular Surgery', 'Easy', 'Surgery', 130, '{"id":9016,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Easy","source":"Surgery","sourceNo":130,"q":"Brodie-Trendelenburg test is positive in:","o":["Deep vein thrombosis","Sapheno-femoral incompetence","Thromboangiitis obliterans","Below-knee perforators incompetence"],"a":1,"e":"Ans. B: Sapheno-femoral Incompetence A test to assess the competence of the saphenofemoral junction. The Brodie-Trendelenburg test is used to detect venous incompetence and to differentiate between perforator and GSV incompetence. The Brodie-Trendelenburg test is highly sensitive for the identification of superficial and perforator reflux. SFJ (saphenofemoral junction) incompetence is diagnosed if the distal veins fill rapidly upon release of the tourniquet. Some textbooks refer to the Trendelenburg test and the tourniquet test interchangeably.","pyqMatches":[{"year":"2015","no":1461,"q":"Brodie-Trendelenburg test is positive in:","o":["Deep vein thrombosis","Sapheno-femoral incompetence","Thromboangiitis obliterans","Below-knee perforators incompetence"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9017, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 131, '{"id":9017,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":131,"q":"Cullen''s sign is seen in: March 2004","o":["Acute cholecystitis","Acute hepatitis","Acute pancreatitis","Blunt injury abdomen"],"a":2,"e":"Ans. C i.e. Acute pancreatitis","pyqMatches":[{"year":"2016","no":1256,"q":"Cullen''s sign is seen in: March 2004","o":["Acute cholecystitis","Acute hepatitis","Acute pancreatitis","Blunt injury abdomen"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9018, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'Surgery', 132, '{"id":9018,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":132,"q":"Acute pancreatitis causes all of the following except: March 2005, March 2013 (g)","o":["Hypercalcemia","Increased amylase level","Subcutaneous fat necrosis","Hyperlipidemia"],"a":0,"e":"Ans. A: Hypercalcemia Complications of acute pancreatitis: Intra-abdominal: Pancreatic \"collections\": Phlegmon Pseudocyst Abscess Necrosis Intestinal: Paralytic ileus Gastrointestinal haemorrhage - from stress ulceration, gastric varices due to splenic vein obstruction, or rupture of pseudoaneurysm Necrotising obstruction or fistulisation of colon * Hepatic - obstructive jaundice due to oedematous narrowing of common bile duct * Renal - hydronephrosis and hydroureter of right kidney due to peripancreatic inflammation in perirenal space * Spleen - rupture or haematoma, from spread of peripancreatic inflammation Systemic complications range from minor pyrexia to rapidly fatal, multiple organ-system failure. They include: * Circulatory shock - kinin activation, haemorrhage * Disseminated intravascular coagulation * Respiratory insufficiency: Mild e.g. hypoxaemia, atelectasis, pleural effusion Severe e.g. adult respiratory distress syndrome * Acute renal failure * Metabolic: Hypocalcaemia Hyperglycaemia / diabetes mellitus Hypertriglyceridaemia * Pancreatic encephalopathy - confusions, delusions, coma * Retinal arteriolar obstruction causing sudden blindness Purtscher''s retinopathy * Metastatic fat necrosis A serum level three to four times above normal serum amylase level, is indicative of acute pancreatitis, but a normal level does not exclude the disease.","pyqMatches":[{"year":"2015","no":1273,"q":"Acute pancreatitis causes all of the following except: March 2005, March 2013 (g)","o":["Hypercalcemia","Increased amylase level","Subcutaneous fat necrosis","Hyperlipidemia"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9019, 'Surgery', 'Hepatobiliary & Pancreas', 'Moderate', 'Surgery', 133, '{"id":9019,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Moderate","source":"Surgery","sourceNo":133,"q":"Charcot''s triad is defined by all of the following except: September 2007, March 2009","o":["Fever","Gall stones","Jaundice","Pain"],"a":1,"e":"Ans. B: Gall stones Cholangitis is due to partial or complete obstruction of the biliary tree with resulting bile stasis and secondary bacterial or microbial infection of the biliary tree Causes ? Common bile duct stones Benign biliary stricture (primary sclerosing cholangitis) Malignancy (head of pancreas adenocarcinoma, ampulla of Vater, bile duct tumors) Chronic pancreatitis Prosthesis or stents in the common bile duct Features: Charcot''s triad - right upper quadrant pain, fever, jaundice Reynolds'' pentad - right upper quadrant pain, fever, jaundice, hypotension, and mental status changes (delirium, anxiety, and coma) Nausea and/or vomiting Right upper quadrant tenderness (mild to moderate)","pyqMatches":[{"year":"2014","no":1599,"q":"Charcot''s triad is defined by all of the following except: September 2007, March 2009","o":["Fever","Gall stones","Jaundice","Pain"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9020, 'Surgery', 'Hepatobiliary & Pancreas', 'Moderate', 'Surgery', 134, '{"id":9020,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Moderate","source":"Surgery","sourceNo":134,"q":"Most sensitive and specific for acute pancreatitis amongst the following is: September 2008","o":["S.amylase","S.Alanine transaminase","S.lipase","C-reactive protein"],"a":2,"e":"Ans. C: S.lipase Serum markers for diagnosis of acute pancreatitis: Alanine transaminase-Associated with gallstone pancreatitis; three fold elevation or greater in the presence of acute pancreatitis has a positive predictive value of 95 percent in diagnosing acute gallstone pancreatitis Amylase Most accurate when at least twice the upper limit of normal; amylase levels and sensitivity decrease with time from onset of symptoms C-reactive protein Late marker; high levels associated with pancreatic necrosis Lipase Increased sensitivity in alcohol-induced pancreatitis; more specific and sensitive than amylase for detecting acute pancreatitis Phospholipase A2 Associated with development of pancreatic necrosis and pulmonary failure Procalcitonin Early detection of severity; high concentrations in infected necrosis Trypsinogen activation peptide Early marker for acute pancreatitis and close correlation to severity","pyqMatches":[{"year":"2016","no":1248,"q":"Most sensitive and specific for acute pancreatitis amongst the following is: September 2008","o":["S.amylase","S.Alanine transaminase","S.lipase","C-reactive protein"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9021, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'Surgery', 135, '{"id":9021,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":135,"q":"Treatment of an incidentally detected Appendicular carcinoid measuring 2.5 cm is: September 2002","o":["Right hemicolectomy","Limited resection of the right colon","Total colectomy","Appendicectomy"],"a":0,"e":"Ans. A i.e. Right hemicolectomy","pyqMatches":[{"year":"2012","no":81,"q":"Treatment of an incidentally detected Appendicular carcinoid measuring 2.5 cm is: September 2002","o":["Right hemicolectomy","Limited resection of the right colon","Total colectomy","Appendicectomy"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9022, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 136, '{"id":9022,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":136,"q":"Heller''s myotomy is done for: September 2007, 2009, 2010","o":["Esophageal carcinoma","Pyloric hypertrophy","Achalasia cardia","Inguinal hernia"],"a":2,"e":"Ans. C: Achalasia cardia Achalasia is associated with loss of ganglion cells in the esophageal myenteric plexus. These important inhibitory neurons induce LES relaxation and coordinate proximal-to-distal peristaltic contraction of the esophagus Achalasia is an esophageal motor disorder characterized by increased lower esophageal sphincter (LES) pressure, diminished- to-absent peristalsis in the distal portion of the esophagus composed of smooth muscle, and lack of a coordinated LES relaxation in response to swallowing. Barium radiology may show ''bird''s beak'' appearance. Esophageal (Heller) myotomy is a surgical procedure that is performed with minimally invasive techniques. The laparoscopic approach appears to be most appropriate.","pyqMatches":[{"year":"2014","no":1554,"q":"Heller''s myotomy is done for: September 2007, 2009, 2010","o":["Esophageal carcinoma","Pyloric hypertrophy","Achalasia cardia","Inguinal hernia"],"a":2,"source":"NEET_2014_Paper.pdf"},{"year":"2015","no":1274,"q":"Heller''s myotomy is done for: September 2007, 2009, 2010","o":["Esophageal carcinoma","Pyloric hypertrophy","Achalasia cardia","Inguinal hernia"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2014","2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9023, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 137, '{"id":9023,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":137,"q":"All of the following testicular tumours are germ cell tumours EXCEPT: March 2013 (b)","o":["Seminoma","Teratoma","Choriocarcinoma","Sertoli cell tumour"],"a":3,"e":"Ans. D i.e. Sertoli cell tumour Testicular carcinoma Bilateral in 10% of cases, Abdominal cryptorchid testes are at higher risk as compared to inguinal cryptorchid testes Testicular feminization syndrome increases the risk of testicular germ cell tumour MC Ca of testes in young: Seminoma MC Ca in elderly: Lymphoma MC Ca in infants: Yolk sac tumour Seminoma Radiosensitive, Corresponds to dysgerminoma of ovary & Treatment of choice is: Surgery Germ Cell Tumors Precursor lesion Intratubular germ cell neoplasm, unclassified Intratubular germ cell neoplasm, specific type Tumors of 1 histologic type Seminoma Variant: Seminoma with syncytiotrophoblastic cells Partially regressed tumor showing seminoma with scar Spermatocytic seminomaEmbryonal carcinoma Variant: Spermatocytic seminoma with a sarcomatous component Yolk sac tumor ChoriocarcinomaPlacental site trophoblastic tumor Variant: \"Monophasic\" type Trophoblastic tumor, unclassified Teratoma With a secondary somatic type malignant component Monodermal variants Carcinoid Primitive neuroectodermal tumor Others","pyqMatches":[{"year":"2015","no":1340,"q":"All of the following testicular tumours are germ cell tumours EXCEPT: March 2013 (b)","o":["Seminoma","Teratoma","Choriocarcinoma","Sertoli cell tumour"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9024, 'Surgery', 'Urology', 'Easy', 'Surgery', 138, '{"id":9024,"subject":"Surgery","chapter":"Urology","difficulty":"Easy","source":"Surgery","sourceNo":138,"q":"Cobra head appearance on excretory urography is suggestive of: March 2010","o":["Horseshoe kidney","Duplication of renal pelvis","Simple cyst of kidney","Ureterocele"],"a":3,"e":"Ans. D: Ureterocele The term ureterocele denotes a cystic ballooning of the distal end of the ureter. This type of ureterocele is also termed orthotopic, since it arises from a ureter with a normal insertion into the trigone. An intravesical ureterocele results from the prolapse of the mucosa of the terminal segment of the ureter through the ureterovesical orifice into the bladder. This prolapsed ureteral mucosa carries with it a portion of the continuous sheet of the bladder mucosa around the orifice. The prolapsed segment thus has a wall that consists of a thin layer of muscle and collagen interposed between the bladder uroepithelium and the ureter uroepithelium. Since the terminal ureteral orifice is usually narrowed and partially obstructed, and since there is no muscle support for the double mucosal walls of the prolapsed segment, it dilates. This dilated segment fills with urine and protrudes into the bladder. On excretory urography, cobra head sign is classically seen with an intravesical ureterocele.","pyqMatches":[{"year":"2015","no":1663,"q":"Cobra head appearance on excretory urography is suggestive of: March 2010","o":["Horseshoe kidney","Duplication of renal pelvis","Simple cyst of kidney","Ureterocele"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9025, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 139, '{"id":9025,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":139,"q":"Orchidopexy for incompletely descended testis is done after the age of: September 2011","o":["At birth","1 year","2 years","5 years"],"a":1,"e":"Ans. B: 1 year Orchidopexy is usually performed after the age of 1 year to avoid the risk of operating on a tiny patient Remember: Incomplete descent of testes may increased liability to malignant change All types of malignant testicular tumours are more common in incompletely descended testes even if they have been brought down surgically","pyqMatches":[{"year":"2014","no":1501,"q":"Orchidopexy for incompletely descended testis is done after the age of: September 2011","o":["At birth","1 year","2 years","5 years"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9026, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 140, '{"id":9026,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":140,"q":"MC site for thyroglossal cyst is:","o":["Beneath the foramen caecum","Floor of mouth","Above hyoid","Subhyoid"],"a":3,"e":"Ans. D i.e. Subhyoid Sites of thyroglossal cyst","pyqMatches":[{"year":"2016","no":1237,"q":"MC site for thyroglossal cyst is:","o":["Beneath the foramen caecum","Floor of mouth","Above hyoid","Subhyoid"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9027, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 141, '{"id":9027,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":141,"q":"True about Branchial cyst is: March 2013 (h)","o":["Cysts are more common than sinuses","Mostly arises from 2nd branchial system","Causes dysphagia and hoarseness","Sinus should always be operated"],"a":1,"e":"Ans. B i.e. Mostly arises from 2nd branchial system","pyqMatches":[{"year":"2015","no":135,"q":"True about Branchial cyst is: March 2013 (h)","o":["Cysts are more common than sinuses","Mostly arises from 2nd branchial system","Causes dysphagia and hoarseness","Sinus should always be operated"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9028, 'Surgery', 'Hepatobiliary & Pancreas', 'Moderate', 'Surgery', 142, '{"id":9028,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Moderate","source":"Surgery","sourceNo":142,"q":"All of the following are false for Gall Bladder carcinoma except: March 2005","o":["Carries a good prognosis","Gallstones may be a predisposing factor","Commonly squamous cell carcinoma","Jaundice is rare"],"a":1,"e":"Ans. B: Gallstones may be a predisposing factor Primary carcinoma of the gallbladder is an uncommon, aggressive malignancy that affects women more frequently than men. Older age groups are most often affected, and coexisting gallstones are present in the vast majority of cases. The symptoms at presentation are vague and are most often related to adjacent organ invasion. Imaging studies may reveal a mass replacing the normal gallbladder, diffuse or focal thickening of the gallbladder wall, or a polypoid mass within the gallbladder lumen. Adjacent organ invasion, most commonly involving the liver, is typically present at diagnosis, as is biliary obstruction. Periportal and peripancreatic lymphadenopathy, hematogenous metastases, and peritoneal metastases may also be seen. The vast majority of gallbladder carcinomas are adenocarcinomas. Because most patients present with advanced disease, the prognosis is poor. The radiologic differential diagnosis includes the more frequently encountered inflammatory conditions of the gallbladder, xanthogranulomatous cholecystitis, adenomyomatosis, other hepatobiliary malignancies, and metastatic disease. hepatobiliary malignancies, and metastatic disease. The prevalence of lymphatic spread is high in gallbladder carcinoma. Lymphatic metastases progress from the gallbladder fossa through the hepatoduodenal ligament to nodal stations near the head of the pancreas. Three pathways of lymphatic drainage have been suggested: the cholecystoretropancreatic pathway, the cholecystoceliac pathway, and the cholecystomesenteric pathway. The cystic and pericholedochal lymph nodes are the most commonly involved at surgery and are a critical pathway to involvement of the celiac, superior mesenteric, and para-aortic lymph nodes.","pyqMatches":[{"year":"2015","no":1257,"q":"All of the following are false for Gall Bladder carcinoma except: March 2005","o":["Carries a good prognosis","Gallstones may be a predisposing factor","Commonly squamous cell carcinoma","Jaundice is rare"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9029, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 143, '{"id":9029,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":143,"q":"Cryoprecipitate contains: March 2009","o":["Factor II","Factor V","Factor VIII","Factor IX"],"a":2,"e":"Ans. C: Factor VIII Cryoprecipitate is prepared from plasma and contains fibrinogen, von Willebrand factor, factor VIII, factor XIII and fibronectin. Cryoprecipitate is the only adequate fibrinogen concentrate available for intravenous use. Cryoprecipitate is indicated for bleeding or immediately prior to an invasive procedure in patients with significant hypofibrinogenemia ( Cryoprecipitate should not be used for patients with von Willebrand disease or Hemophilia A (Factor VIII deficiency). It is not usually given for Factor XIII deficiency, as there are virus-inactivated concentrates of this protein available. Cryoprecipitate is sometimes useful if platelet dysfunction associated with renal failure does not respond to dialysis.","pyqMatches":[{"year":"2016","no":429,"q":"Cryoprecipitate contains: March 2009","o":["Factor II","Factor V","Factor VIII","Factor IX"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9030, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 144, '{"id":9030,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":144,"q":"Adson test is positive in: September 2007","o":["Cervical spondylosis","Cervical rib","Cervical vertebra fracture","Superior vena cava syndrome"],"a":1,"e":"Ans. B: Cervical rib Adson''s test is used to assess for the presence of Thoracic Outlet Syndrome (cervical rib) at the scalene triangle. Process The patient is placed in a sitting position, hands resting on thighs. The examiner palpates radial pulse on side being tested Patient actively rotates head to ipsilateral side being tested while the examiner laterally rotates and extends the patient''s shoulder Patient takes a deep breath and is instructed to hold it The examiner palpates the radial pulse while moving the upper extremity in abduction, extension, and external rotation. The patient then is asked to rotate her head toward the involved side while taking a deep breath and holding it. A positive exam will result in a diminished or absent radial pulse.","pyqMatches":[{"year":"2013","no":1379,"q":"Adson test is positive in: September 2007","o":["Cervical spondylosis","Cervical rib","Cervical vertebra fracture","Superior vena cava syndrome"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9031, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'Surgery', 145, '{"id":9031,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":145,"q":"Drugs for paralytic ileus for bowel resection surgery are all except ?","o":["Alvinopam","Dihydroergotamine","Naloxone","Methylnaltrexone"],"a":2,"e":"Ans. is ''c'' i.e., Naloxone Pharmacologic Management of Post op paralytic ileus (P01): Minimizing the sympathetic inhibition of gastrointestinal motility, decreasing inflammation and stimulation of gastrointestinal 11-opioid receptors are the ultimate goals of pharmacologic management. A) Minimizing sympathetic inhibition Both propranolol, a nonspecific 13-receptor antagonist, and dihydroergotamine, an a-receptor antagonist, have been investigated for treatment of POI. Neostigmine is an acetylcholinsterase inhibitor that causes an increase in cholinergic (parasympathetic) activity in the gut wall, which is believed to thereby stimulate colonic motility. Use of edrophonium chloride and bethanechol chloride, which competitively inhibit acetylcholine on the binding site of acetylcholinesterase, has been reported to show improvement of POI. Cisapride is a serotonin (5-HT)4 receptor antagonist that promotes acetylcholine release from postganglionic nerve endings in the myenteric plexus and is thought to indirectly improve gastrointestinal motility. Metocloprimide is suspected to enhance gastrointestinal motility without stimulating gastric secretion, but its use has not been substantiated for POI. B) Decreasing inflammation Decreasing inflammation may be indicated in patients who are about to undergo major intestinal surgery, as this is thought to be an important contributing factor to POI. Nonsteroidal anti-inflammatory (NSAIDs) agents can be used in conjunction with opioid analgesics for their dual effects on pain control and inflammatory inhibition. C) Stimulation of gastrointestinal iii-opioid receptors Stimulation of gastrointestinal .1-opioid receptors can theoretically influence gastrointestinal motility directly; therefore, blocking the peripheral gastrointestinal effects of centrally acting opioids used for analgesia may help prevent POI. Two novel drugs are being investigated for this reason: alvimopan and methylnaltrexone. Both drugs are If-opioid receptor antagonists, and both appear to offer promising results for preventing prolonged POI. Opioid therapy for postoperative or chronic pain is frequently associated with adverse effects, the most common being dose- limiting and debilitating bowel dysfunction, so alvimopan and methylnaltrexone may also be useful in the treatment of chronic opioid bowel dysfunction. The currently available opioid antagonists such as naloxone are of limited use because they also act at central opioid receptors to reverse analgesia and elicit opioid withdrawal. Alvimopan and methylnaltrexone are peripherally acting if-opioid receptor antagonists that have been studied in patients undergoing abdominal and pelvic surgery and have been shown in several studies to significantly accelerate gastrointestinal recovery. Alvimopan received FDA approval for the treatment of POI on May 20, 2008. D) Alternative medications Bisacodyl administration versus placebo twice daily starting on postoperative day 1, patients who received bisacodyl had significantly earlier bowel movements than those who received placebo (25 h v. 56 h), but further studies are needed to assess the effect of laxatives on POI.","pyqMatches":[{"year":"2014","no":583,"q":"Drugs for paralytic ileus for bowel resection surgery are all except ?","o":["Alvinopam","Dihydroergotamine","Naloxone","Methylnaltrexone"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9032, 'Surgery', 'Vascular Surgery', 'Hard', 'Surgery', 146, '{"id":9032,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Hard","source":"Surgery","sourceNo":146,"q":"An adult hypertensive male presented with sudden onset severe headache and vomiting. On examination, there is marked neck rigidity and no focal neurological deficit was found. The symptoms are most likely due to:","o":["Intracerebral parenchymal hemorrhage","Ischemic stroke","Meningitis","Subarachnoid hemorrhage"],"a":3,"e":"Ans. d. Subarachnoid hemorrhage The most likely diagnosis here is a subarachnoid bleed (SAH). The most common cause is trauma and is managed conservatively. The second most common cause is a rupture of a berry aneurysm. The typical presentation of a subarachnoid hemorrhage includes a ‘thunderclap’ headache. Meningitic features of neck stiffness and photophobia often develop over hours. Computed tomography (CT) is the investigation of choice. Lumbar puncture should be performed if the CT scan fails to establish the diagnosis of SAH; it shows a xanthochromic blood picture. Delayed ischemic neurological deficit (DIND) is attributed to vasospasm of the cerebral vasculature typically developing 3–10 days following ictus. It is the main cause of a poor outcome. Endovascular treatment (\"coiling\") is generally preferred over craniotomy and clipping for aneurysms amenable to this approach.","pyqMatches":[{"year":"2012","no":1046,"q":"An adult hypertensive male presented with sudden onset severe headache and vomiting. On examination, there is marked neck rigidity and no focal neurological deficit was found. The symptoms are most likely due to:","o":["Intracerebral parenchymal hemorrhage","Ischemic stroke","Meningitis","Subarachnoid hemorrhage"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9033, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 147, '{"id":9033,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":147,"q":"Gasless abdomen seen in-","o":["Ulcerative colitis","Acute pancreatitis","Intussusception","Necrotising enterocolitis"],"a":1,"e":"Answer- B (acute pancreatitis) Common causes include: In adult: -High obstruction. -Ascites. -Acute pancreatitis due to excess vomiting. -Fluid filled intestine. -Large abdominal mass. ACUTE PANCREATITIS - radiology signs renal halo sign gasless abdomen ground glass appearance colon cut off sign sentinel loop","pyqMatches":[{"year":"2019","no":186,"q":"Gasless abdomen seen in","o":["Ulcerative colitis","Acute pancreatitis","Intussusception","Necrotising enterocolitis"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9034, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 148, '{"id":9034,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":148,"q":"Dohlman procedure for-","o":["Meckel’s diverticulum","Zenker’s diverticulum","Dermatomyositis","Menetrier’s disease"],"a":1,"e":"Answer- B (Zenker’s diverticulum) The treatment of pharyngeal pouches (Zenker’s Diverticulum) may be by either open surgical or endoscopic techniques. The endoscopic Dohlman’s procedure is an ideal technique in the elderly.","pyqMatches":[{"year":"2016","no":1261,"q":"Dohlman procedure for","o":["Meckel’s diverticulum","Zenker’s diverticulum","Dermatomyositis","Menetrier’s disease"],"a":1,"source":"NEET_2016_Paper.pdf"},{"year":"2019","no":179,"q":"Dohlman procedure for","o":["Meckel’s diverticulum","Zenker’s diverticulum","Dermatomyositis","Menetrier’s disease"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2016","2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9035, 'Surgery', 'Transplantation', 'Easy', 'Surgery', 149, '{"id":9035,"subject":"Surgery","chapter":"Transplantation","difficulty":"Easy","source":"Surgery","sourceNo":149,"q":"If a mother is donating kidney to her son is an example-","o":["Isograft","Allograft","Autograft","Xenograft"],"a":1,"e":"Answer- B (Allograft) Allograft – Grafting between two non-identical member of same species but not same genotypes. It includes the transplantation of heart, kidney, lung etc, from a members who donate their organs. Anti – rejection drugs or immunosuppressant need to be taken to prevent the body from rejecting a transplanted organ. Most human tissue and organ transplants are allografts.","pyqMatches":[{"year":"2019","no":180,"q":"If a mother is donating kidney to her son is an example","o":["Isograft","Allograft","Autograft","Xenograft"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9036, 'Surgery', 'Urology', 'Easy', 'Surgery', 150, '{"id":9036,"subject":"Surgery","chapter":"Urology","difficulty":"Easy","source":"Surgery","sourceNo":150,"q":"Uvula vesicae is produced by which prostate lobe?","o":["Anterior lobe","Post lobe","Median lobe","Lateral lobe"],"a":2,"e":"Answer- C (median lobe) The mucous membrane immediately behind the internal urethral orifice presents a slight elevation, the uvula of urinary bladder, caused by the median lobe of the prostate. It is often enlarged in benign prostatic hypertrophy.","pyqMatches":[{"year":"2019","no":181,"q":"Uvula vesicae is produced by which prostate lobe?","o":["Anterior lobe","Post lobe","Median lobe","Lateral lobe"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9037, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'Surgery', 151, '{"id":9037,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":151,"q":"True about Barrett’s esophagus are all of the following except:","o":["Causes adenocarcinoma","Patient is usually asymptomatic","Histology of the lesion shows mucus secreting goblet cells","Chronic gastroesophageal reflux is a predisposing factor"],"a":0,"e":"Answer- Barrett esophagus is a premalignant condition that involves the distal esophagus and appears to be related to chronic gastroesophageal reflux (GORD). There is metaplastic change in the lining mucosa of esophagus. Patient is usually asymptomatic in a case of Barrett''s Esophagus. Histology of the lesion in a case of Barrett''s esophagus shows mucus secreting goblet cells. Diagnosis of Barrett''s esophagus is made by demons​tration of columnar mucosa, which on histopathology shows Intestinal type of metaplasia Chronic reflux is a casue of Barrett''s Esophagus.","pyqMatches":[{"year":"2019","no":182,"q":"True about Barrett’s esophagus are all of the following except:","o":["Causes adenocarcinoma","Patient is usually asymptomatic","Histology of the lesion shows mucus secreting goblet cells","Chronic gastroesophageal reflux is a predisposing factor"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9038, 'Surgery', 'Endocrine Surgery', 'Easy', 'Surgery', 152, '{"id":9038,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Easy","source":"Surgery","sourceNo":152,"q":"Parathyroid autoimplantation takes place in which of the muscle?","o":["Biceps","Triceps","Brachioradialis","Sartorius"],"a":2,"e":"Answer- C (Brachioradialis) A total parathyroidectomy with a forearm autograft involves removal of all parathyroid tissue in the neck, with reimplantation of a small amount of morcellated tissue within a pocket formed in the brachioradialis muscle.","pyqMatches":[{"year":"2019","no":183,"q":"Parathyroid autoimplantation takes place in which of the muscle?","o":["Biceps","Triceps","Brachioradialis","Sartorius"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9039, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 153, '{"id":9039,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":153,"q":"Bell’s palsy is associated with the lesion in which of the nerve?","o":["11th cranial nerve","7th cranial nerve","9th cranial nerve","3rd cranial nerve"],"a":1,"e":"Answer- B (7th cranial nerve) Bell’s palsy occurs due to a malfunction of the facial nerve (VII cranial nerve), which controls the muscles of the face. Facial palsyis typified by inability to control movement in the muscles of facial expression.","pyqMatches":[{"year":"2019","no":184,"q":"Bell’s palsy is associated with the lesion in which of the nerve?","o":["11th cranial nerve","7th cranial nerve","9th cranial nerve","3rd cranial nerve"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9040, 'Surgery', 'Neurosurgery', 'Hard', 'Surgery', 154, '{"id":9040,"subject":"Surgery","chapter":"Neurosurgery","difficulty":"Hard","source":"Surgery","sourceNo":154,"q":"Cushing ulcer is seen in case of-","o":["Burns","Head injury","Cell necrosis","Stress"],"a":1,"e":"Answer- B (Head injury) Cushing ulcers are associated with a brain tumor or head injury and typically are single, deep ulcers that are prone to perforation. It is a gastric ulcer associated with elevated intracranial pressure. It is also called von Rokitansky–Cushing syndrome. The mechanism of development of Cushing ulcers is thought to be due to direct stimulation of vagal nuclei as a result of increased intracranial pressure. Brain tumors, traumatic head injury, and other intracranial processes including infections, can cause increased intracranial pressure and lead to overstimulation of the vagus nerve.","pyqMatches":[{"year":"2019","no":185,"q":"Cushing ulcer is seen in case of","o":["Burns","Head injury","Cell necrosis","Stress"],"a":1,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9041, 'Surgery', 'Hepatobiliary & Pancreas', 'Easy', 'Surgery', 155, '{"id":9041,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Easy","source":"Surgery","sourceNo":155,"q":"Most common indication for liver transplant in children-","o":["Biliary atresia","Cirrhosis","Hepatitis","Drug reactions"],"a":0,"e":"Answer- A (Biliary atresia) Indications for liver transplantation in infants and children include acute liver failure (ALF), chronic liver failure with pruritus, complications of cholestasis and failure to thrive. In young children, the most common liver disease leading to transplantation is biliary atresia","pyqMatches":[{"year":"2019","no":175,"q":"Most common indication for liver transplant in children","o":["Biliary atresia","Cirrhosis","Hepatitis","Drug reactions"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9042, 'Surgery', 'Hepatobiliary & Pancreas', 'Easy', 'Surgery', 156, '{"id":9042,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Easy","source":"Surgery","sourceNo":156,"q":"Most common type of gallstone is-","o":["Mixed stones","Pure cholesterol stones","Pigment stones","Calcium bilirubinate"],"a":0,"e":"Answer- A Mixed- Between 4% and 20% of stones are mixed. Pigment- Between 2% and 30% of stones are bilirubin stones. Cholesterol- Between 35% and 90% of stones are cholesterol stones. The most common type of gallstones was mixed cholesterol type gallstones with 67.5% followed by black pigment and brown pigment types as 23.83% and 5.89%, respectively. Mixed stones are 90% common. It contains cholesterol, calcium salts of phosphate carbonate, palmitate, proteins, and are multiple faceted.","pyqMatches":[{"year":"2019","no":176,"q":"Most common type of gallstone is","o":["Mixed stones","Pure cholesterol stones","Pigment stones","Calcium bilirubinate"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9043, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 157, '{"id":9043,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":157,"q":"Serpiginous ulcer distal esophagus-","o":["CMV","Herpes","Pill","Corrosive"],"a":0,"e":"Answer- A (CMV) CMV classically causes serpiginous ulcers in the distal esophagus that may coalesce to form giant ulcers.","pyqMatches":[{"year":"2019","no":177,"q":"Serpiginous ulcer distal esophagus","o":["CMV","Herpes","Pill","Corrosive"],"a":0,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9044, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 158, '{"id":9044,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":158,"q":"Omphalocele is caused by?","o":["Duplications of intestinal loops","Abnormal rotation of the intestinal loop","Failure of gut to return to the body cavity from its physiological herniation","Reversed rotation of the intestinal loop"],"a":2,"e":"Answer- C (Failure of gut to return to the body cavity from its physiological herniation) Failure of gut to return to the body cavity from its physiological herniation. Exomphalos(omphalocele) is herniation of abdominal viscera through an enlarged umbilical ring. The viscera, which may include liver, small and large intestines, stomach, spleen, or bladder, are covered by amnion. The origin of omphalocele is a failure of the bowel to return to the body cavity from its physiological herniation during the 6th to 10th weeks.","pyqMatches":[{"year":"2019","no":178,"q":"Omphalocele is caused by?","o":["Duplications of intestinal loops","Abnormal rotation of the intestinal loop","Failure of gut to return to the body cavity from its physiological herniation","Reversed rotation of the intestinal loop"],"a":2,"source":"NEET_Jan_2019_Paper.pdf"}],"pyqYears":["2019"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9045, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 159, '{"id":9045,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":159,"q":"Which of the following is true about coeliac plexus block?","o":["Located retroperitoneally at the level of L3","Usually done unilaterally","Useful for the painful conditions of lower abdomen","Most common side effect is diarrhea and hypotension"],"a":3,"e":"Answer- D (Most common side effect is diarrhea and hypotension) Celiac Plexus Block: Located retroperitoneally at the level of Ll Usually done bilaterallv Useful for the painful conditions of upper abdomen Most common side effect is diarrhea and hvpotension","pyqMatches":[{"year":"2012","no":88,"q":"Which of the following is true about coeliac plexus block?","o":["Located retroperitoneally at the level of L3","Usually done unilaterally","Useful for the painful conditions of lower abdomen","Most common side effect is diarrhea and hypotension"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9046, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 160, '{"id":9046,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":160,"q":"Most commonly performed and acceptable method of bariatric surgery is:","o":["Biliopancreatic diversion","Biliopancreatic diversion with ilcostomy","Laparoscopic gastric banding","Roux-en-Y gastric bypass."],"a":3,"e":"Ans: D. Roux-en-Y gastric bypass. (Ref. Sabiston 20/e p1187, 19/e p363; Schwartz 10/e p1112, 9/952; Harrison 19/p2398). Roux-en-Y gastric bypass: Most commonly performed & acceptable method of bariatric surgery. 3 restrictive-malabsorptive bypass procedures: Combine elements of gastric restriction & selective malabsorption. Procedures include Roux-en-Y gastric bypass, biliopancreatic diversion & biliopancreatic diversion with duodenal switch. Roux-en-Y: Most commonly undertaken & most accepted bypass procedure. Performed with an open incision or by laparoscopy.","pyqMatches":[{"year":"2016","no":1334,"q":"Most commonly performed and acceptable method of bariatric surgery is:","o":["Biliopancreatic diversion","Biliopancreatic diversion with ilcostomy","Laparoscopic gastric banding","Roux-en-Y gastric bypass."],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9047, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 161, '{"id":9047,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":161,"q":"A patient after road traffic accident presented with tension pneumothorax. What is the first line of management?","o":["Insert wide bore needle in 2nd intercostal space","Immediate chest X-ray","CT scanEmergency thoracotomy","Emergency thoracotomy"],"a":0,"e":"Answer- A. Insert wide bore needle in 2nd intercostal space First line of management in tension pneumothorax: Insert wide bore needle in 2nd intercostal space.","pyqMatches":[{"year":"2016","no":1319,"q":"A patient after road traffic accident presented with tension pneumothorax. What is the first line of management?","o":["Insert wide bore needle in 2nd intercostal space","Immediate chest X-ray","CT scanEmergency thoracotomy","Emergency thoracotomy"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9048, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 162, '{"id":9048,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":162,"q":"Prehn sign is positive in","o":["Acute epidydimoorchitis","Chronic orchitis","Testicular torsion","None"],"a":0,"e":"Answer- A. Acute epidydimoorchitis On elevation of testis the- Pain is not relieved in torsion (test is negative) Pain relieved in epidydimoorchitis (test is positive)","pyqMatches":[{"year":"2013","no":1397,"q":"Prehn sign is positive in","o":["Acute epidydimoorchitis","Chronic orchitis","Testicular torsion","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9049, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 163, '{"id":9049,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":163,"q":"Definitive surgery is a part of which stage of damage control surgery?","o":["I","II","III","IV"],"a":3,"e":"Answer- D. IV Following major injury, protracted surgery in the physiologically unstable patient with the ''deadly triad'' - the combination of hypothermia, acidosis and coagulopathy ''Damage control'' or ''damage limitation surgery'' is a concept that originated from naval architecture, whereby a ship was designed to have areas sealed off in the case of damage, to limit flooding. Stages-","pyqMatches":[{"year":"2016","no":1205,"q":"Definitive surgery is a part of which stage of damage control surgery?","o":["I","II","III","IV"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9050, 'Surgery', 'General Principles & Wounds', 'Moderate', 'Surgery', 164, '{"id":9050,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Moderate","source":"Surgery","sourceNo":164,"q":"Which of the following is not true about Boerhaave syndrome?","o":["Perforation of the esophagus due to barotrauma","Most common site is left posteromedial aspect 3 - 5 cms above the gastroesophageal junction","Pain is the early manifestation","Most cases follow a bout of heavy eating or drinking"],"a":1,"e":"Answer- B. Most common site is left posteromedial aspect 3 - 5 cms above the gastroesophageal junction Vomiting is thought to be the most common cause, other causes include weightlifting, defecation, epileptic seizures, abdominal trauma, compressed air injury, and childbirth, all of which can increase the pressure in the esophagus and cause a barogenic esophageal rupture. Two common risk factors include alcoholism and excessive indulgence in food. Rupture occurs most commonly in the left posterolateral wall of the distal third of the esophagus with extension into the left pleural cavity. Symptoms consist of vomiting, lower thoracic pain, and subcutaneous emphysema. Typically, the patient will present with pain at the site of perforation, usually in the neck, chest, epigastric region, or upper abdomen.","pyqMatches":[{"year":"2015","no":1261,"q":"Which of the following is not true about Boerhaave syndrome?","o":["Perforation of the esophagus due to barotrauma","Most common site is left posteromedial aspect 3 - 5 cms above the gastroesophageal junction","Pain is the early manifestation","Most cases follow a bout of heavy eating or drinking"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9051, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 165, '{"id":9051,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":165,"q":"All of the following are indications for bariatric surgery except -","o":["BMI>40 kg/m2","BMI> 35 kg/m2 with atleast one comorbidity","BMI>30 with long standing diabetes","Failure of other methods of weight loss"],"a":2,"e":"Answer- C. BMI>30 with long standing diabetes Indications for bariatric swgery BMI > 40kg/m2 BMI > 35 kg/m2 with atleast one comorbidity Patient at high risk of obesity associated morbidity and mortality Failure of other methods of wight loss","pyqMatches":[{"year":"2016","no":1212,"q":"All of the following are indications for bariatric surgery except","o":["BMI>40 kg/m2","BMI> 35 kg/m2 with atleast one comorbidity","BMI>30 with long standing diabetes","Failure of other methods of weight loss"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9052, 'Surgery', 'General Principles & Wounds', 'Moderate', 'Surgery', 166, '{"id":9052,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Moderate","source":"Surgery","sourceNo":166,"q":"Indications for emergency thoracotomy are all of the following except","o":["Major tracheobronchial injuries","Cardiac tamponade","Penetrating injuries to anterior chest","Tension Pneumothorax"],"a":3,"e":"Answer- D. Tension Pneumothorax Emergency thoracotomy is indicated after chest trauma in following conditions : Cardiac arrest (resuscitative thoractomy) Massive hemoththorax (>1500 mL of blood through the chest tube acutely or > 200-300 ml/hr after initial drainage. Penetrating injuries of the anterior aspect of the chest with cardiac tamponade. Large open wounds of the thoracic cage. Major thoracic vascular injuries in the presence of hemodynamic instability","pyqMatches":[{"year":"2012","no":1098,"q":"Indications for emergency thoracotomy are all of the following except","o":["Major tracheobronchial injuries","Cardiac tamponade","Penetrating injuries to anterior chest","Tension Pneumothorax"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9053, 'Surgery', 'Breast Surgery', 'Moderate', 'Surgery', 167, '{"id":9053,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":167,"q":"A female undergone surgery for left breast cancer 3 yrs back now developed blue nodule on same side","o":["Lymphangiosarcoma","Recurrence","Hemangioma","Cellulitis"],"a":0,"e":"Answer- A. Lymphangiosarcoma Angiosarcoma is a vascular tumor which may arise de novo in the breast or as a complication of the radiation therapy.","pyqMatches":[{"year":"2016","no":1227,"q":"A female undergone surgery for left breast cancer 3 yrs back now developed blue nodule on same side","o":["Lymphangiosarcoma","Recurrence","Hemangioma","Cellulitis"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9054, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 168, '{"id":9054,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":168,"q":"Blood loss in class III hemorrhagic shock -","o":["< 750 ml","750 - 1500 ml","1500-2000 ml","> 2000 ml"],"a":2,"e":"Ans. is ''c'' i.e.,1500-2000 ml Parameters Class I Class II Class III Class IV Blood Loss (mL) Up to 750 750–1500 1500–2000 > 2000 Blood Loss (%BV) Up to 15% 15–30% 30–40% > 40% Pulse rate (beats/min) < 100 > 100 > 120 > 140 Blood Pressure Normal Minimal decrease Decreased Significantly decreased Pulse Pressure Normal Narrowed Narrowed Unobtainable or very narrow Hourly urine output ≥ 0.5 mL/kg ≥ 0.5 mL/kg < 0.5 cc/kg Minimal CNS/Mental status Slightly anxious Mildly anxious Anxious and confused Confused or lethargic","pyqMatches":[{"year":"2013","no":1416,"q":"Blood loss in class III hemorrhagic shock","o":["< 750 ml","750 - 1500 ml","1500-2000 ml","> 2000 ml"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9055, 'Surgery', 'Urology', 'Easy', 'Surgery', 169, '{"id":9055,"subject":"Surgery","chapter":"Urology","difficulty":"Easy","source":"Surgery","sourceNo":169,"q":"Most common cancer in men is","o":["Bladder cancer","Colorectal cancer","Prostate cancer","Oral cancer"],"a":2,"e":"Answer- C. Prostate cancer Cancers in males in India: Lip / oralcavity > Prostate > Colorectum > Pharynx (other than nssopharynx) > Larynx Lung cancer was the most common cancer in men worldwide, contributing 15.5% of the total number of new cases diagnosed in","pyqMatches":[{"year":"2012","no":832,"q":"Most common cancer in men is","o":["Bladder cancer","Colorectal cancer","Prostate cancer","Oral cancer"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9056, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 170, '{"id":9056,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":170,"q":"A nerve injured in radical neck dissection leads to loss of sensation in medial side of the arm, nerve injured is?","o":["Long thoracic nerve","Thoracodorsal nerve","Dorsal scapular nerve","Medial cutaneous nerve of arm"],"a":3,"e":"Answer- D. Medial cutaneous nerve of arm The medial cutaneous nerve of the arm is the smallest and most medial branch of he brachial plexus, and arises from the medial cord. It pierces the deep fascia at the midpoint of the upper arm to supply the skin over the medial aspect of the distal third of the upper arm.","pyqMatches":[{"year":"2015","no":30,"q":"A nerve injured in radical neck dissection leads to loss of sensation in medial side of the arm, nerve injured is?","o":["Long thoracic nerve","Thoracodorsal nerve","Dorsal scapular nerve","Medial cutaneous nerve of arm"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9057, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 171, '{"id":9057,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":171,"q":"Gold standard investigation for chronic pancreatitis?","o":["MRI","ERCP","Pancreatic function tests","Fecal fat estimation"],"a":1,"e":"Answer- B. ERCP ERCP has been considered the most sensitive radiologic test for the diagnosis of chronic pancreatitis, with specific ERCP findings that are highly correlative with the degree or stage of chronic disease.","pyqMatches":[{"year":"2014","no":2044,"q":"Gold standard investigation for chronic pancreatitis?","o":["MRI","ERCP","Pancreatic function tests","Fecal fat estimation"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9058, 'Surgery', 'Gastrointestinal Surgery', 'Hard', 'Surgery', 172, '{"id":9058,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Hard","source":"Surgery","sourceNo":172,"q":"Most accurate method for the diagnosis Gastroesophageal Reflux Disease (GERD) is","o":["Histological study","Manometry","24-hour pH recording and electrical impedance measurement","Barium swallow studies e) Upper GI endoscopy"],"a":2,"e":"Answer- C. 24-hour pH recording and electrical impedance measurement The most sensitive test for diagnosis of GERD is 24-h ambulatory pH monitoring. Endoscopy is indicated in patients with reflux symptoms refractory to antisecretory therapy; in those with alarming symptoms such as dysphagia, weight loss, or gastrointestinal bleeding; and in those with recurrent dyspepsia after treatment that is not clearly due to reflux on clinical grounds alone pH was less than 4","pyqMatches":[{"year":"2016","no":1272,"q":"Most accurate method for the diagnosis Gastroesophageal Reflux Disease (GERD) is","o":["Histological study","Manometry","24-hour pH recording and electrical impedance measurement","Barium swallow studies e) Upper GI endoscopy"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9059, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 173, '{"id":9059,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":173,"q":"All are features of SIRS except-","o":["RR> 24 & Paco2 <22mm hg","WBC >11 or <4","Temperature <36 and >38","PR >90"],"a":0,"e":"Answer- A. RR> 24 & Paco2 <22mm hg","pyqMatches":[{"year":"2016","no":1161,"q":"All are features of SIRS except","o":["RR> 24 & Paco2 <22mm hg","WBC >11 or <4","Temperature <36 and >38","PR >90"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9060, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 174, '{"id":9060,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":174,"q":"Which of the following primarily governs the uptake of Tc-99m MDP in body?","o":["Amount of osteogenic activity","Amount of iodine uptake","Amount of calcium uptake","Amount of catecholamine activity"],"a":0,"e":"Answer- A. Amount of osteogenic activity Technetium 99-m is a commonly used radiopharmaceutical. Technetium 99-m methylene diphosphonate (Tc-99mMDP), desirable for the gamma carmera imaging is the commonly used form. Tc-99mMDP can be prepared from a kit containing, sodium pertechnitate (NaTcO4) vial, MDP, stabilizers and stannous ion.","pyqMatches":[{"year":"2016","no":1190,"q":"Which of the following primarily governs the uptake of Tc-99m MDP in body?","o":["Amount of osteogenic activity","Amount of iodine uptake","Amount of calcium uptake","Amount of catecholamine activity"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9061, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 175, '{"id":9061,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":175,"q":"Technitium-99m pertechnetate labelled methylene diphosphonate is structurally similar to","o":["Calcium phosphate","Phosphorus","Sodium bicarbonate","Magnesiumsulfate"],"a":0,"e":"Answer- A. Calcium phosphate The radionucletide administered is Technitium- 99m pertechnetate labeled methylene diphosphonate is an analog of calcium phosphate.","pyqMatches":[{"year":"2016","no":1191,"q":"Technitium-99m pertechnetate labelled methylene diphosphonate is structurally similar to","o":["Calcium phosphate","Phosphorus","Sodium bicarbonate","Magnesiumsulfate"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9062, 'Surgery', 'Neurosurgery', 'Hard', 'Surgery', 176, '{"id":9062,"subject":"Surgery","chapter":"Neurosurgery","difficulty":"Hard","source":"Surgery","sourceNo":176,"q":"Neuroimaging features of neurocysticercosis are considered as criteria for definitive diagnosis -","o":["Major","Minor","Probable","Absolute"],"a":0,"e":"Answer- A. Major Evidence of lesions highly suggestive of neurocysticercosis on neuroimaging studies Positive serum immunoblot for the detection of anticysticercal antibodies Resolution of intracranial cystic lesions after therapy with albendazole or praziquantel Spontaneous resolution of small single enhancing lesions.","pyqMatches":[{"year":"2016","no":1336,"q":"Neuroimaging features of neurocysticercosis are considered as criteria for definitive diagnosis","o":["Major","Minor","Probable","Absolute"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9063, 'Surgery', 'Hepatobiliary & Pancreas', 'Hard', 'Surgery', 177, '{"id":9063,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Hard","source":"Surgery","sourceNo":177,"q":"Laproscopic procedure patient develops shoulder pain due to","o":["Subphrenic abscess","Positional pain during surgery","Subdiaphragmatic migration of gas","Injury to liver"],"a":2,"e":"Answer- C. Subdiaphragmatic migration of gas One type of pain that is unique to laparoscopy is the post laparoscopy shoulder pain due to the phrenic nerve irritation to the diaphragm caused by the CO, gas that remains in the abdomen at the end of the procedure. When the patient sits up, the gas moves upwards to the diaphragm and irritates it leading to referred pain C3- C%.","pyqMatches":[{"year":"2016","no":1192,"q":"Laproscopic procedure patient develops shoulder pain due to","o":["Subphrenic abscess","Positional pain during surgery","Subdiaphragmatic migration of gas","Injury to liver"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9064, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 178, '{"id":9064,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":178,"q":"A patient comes with a complaint of shoulder pain after laparoscopic surgery. What should be the next step in management?","o":["Oral paracetamol for 2 - 3 days","USG of shoulder region","Diagnostic shoulder arthroscopy","Intraarticular lignocaine injection"],"a":0,"e":"Answer- A. Oral paracetamol for 2 - 3 days Shoulder tip pain The patient should be warned about this preoperatively and told that the pain is referred from the diaphragm and not due to a local problem in the shoulders. It can be at its worst 24 hours after the operation. It usually settles within 2-3 days and is relieved by simple analgesics, such as paracetamol.","pyqMatches":[{"year":"2016","no":1193,"q":"A patient comes with a complaint of shoulder pain after laparoscopic surgery. What should be the next step in management?","o":["Oral paracetamol for 2 - 3 days","USG of shoulder region","Diagnostic shoulder arthroscopy","Intraarticular lignocaine injection"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9065, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 179, '{"id":9065,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":179,"q":"Which of the following should be done for an acute onset painful scrotal swelling in 12 years old male?","o":["Doppler stethoscope evaluation","Administer analgesics","Advise bed rest","Administer antibiotics"],"a":0,"e":"Answer- A. Doppler stethoscope evaluation Acute onset painful scrotal swelling in 12 years old preadolescent male is most probably due to torsion of testis. In suspected cases of torsion of testis or testicular appendage a doppler stethoscope should be used to evaluate blood flow to the testicles.","pyqMatches":[{"year":"2016","no":1194,"q":"Which of the following should be done for an acute onset painful scrotal swelling in 12 years old male?","o":["Doppler stethoscope evaluation","Administer analgesics","Advise bed rest","Administer antibiotics"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9066, 'Surgery', 'Neurosurgery', 'Easy', 'Surgery', 180, '{"id":9066,"subject":"Surgery","chapter":"Neurosurgery","difficulty":"Easy","source":"Surgery","sourceNo":180,"q":"Which of the following electrolyte abnormalities can be seen after brain injury?","o":["Hyponatremia","Hyperkalemia","Hypomagnesemia","All the above"],"a":0,"e":"Answer- A Electrolyte abnormalities occur in 60% of the patients with head injury. Patients with brain injury are at a high risk for the development of electrolyte imbalance including hyponatremia, hypocalemia, hypophosphatemia as well as hypokalemia and (to a lesser degree) Hypomagnesemia. So the appropriate answer will be hyponatremia.","pyqMatches":[{"year":"2016","no":1335,"q":"Which of the following electrolyte abnormalities can be seen after brain injury?","o":["Hyponatremia","Hyperkalemia","Hypomagnesemia","All the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9067, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 181, '{"id":9067,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":181,"q":"Earliest hematological change following spleenectomy is","o":["Leukocytosis and thrombocytosis","Presence of Heinz bodies","Evidence of Howell Jolly bodies","Poikilocytosis"],"a":0,"e":"Answer- A. Leukocytosis and thrombocytosis In the immediate postsplenectomy period, leukocytosis (up to 25,000/4) and thrombocytosis (up to 1.106/4) develop, but within 2-3 weeks, blood cell counts and survival of each cell lineage are usually normal.","pyqMatches":[{"year":"2016","no":1195,"q":"Earliest hematological change following spleenectomy is","o":["Leukocytosis and thrombocytosis","Presence of Heinz bodies","Evidence of Howell Jolly bodies","Poikilocytosis"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9068, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 182, '{"id":9068,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":182,"q":"Percuteneous chemical lumbar sympathectomy is practised using -","o":["Phenol","Ethanol","Formalin","Acetic acid"],"a":0,"e":"Answer- A. Phenol Chemical sympathectomy requires the injection of small quantities of dilute aqueous phenol into the lumbar sympathetic chain under radiographic control.","pyqMatches":[{"year":"2016","no":1332,"q":"Percuteneous chemical lumbar sympathectomy is practised using","o":["Phenol","Ethanol","Formalin","Acetic acid"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9069, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 183, '{"id":9069,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":183,"q":"Typical of rectus sheath hematoma is -","o":["Severe tenderness","Bluish discoloration","Firm painful mass","Ecchymosis"],"a":2,"e":"Answer- C. Firm painful mass Clinical features of rectus sheath hematoma A) Symptoms Common historical features of rectus sheath hematoma (RSH) include acute abdominal pain, fever, nausea, and vomiting. B) Signs i) Vital signs A low-grade fever is common in rectus sheath hematoma. The hematoma can be large enough to compromise intravascular volume, with resultant signs of hypovolemic shock including hypotension, tachycardia, and tachypnea. ii) Abdominal examination Typically, the abdominal examination reveals a palpable, painful, firm, nonpulsatile abdominal mass corresponding to the rectus sheath. The mass may be bilobar with a central groove. The mass does not move with respiration. Because the hematoma is deep to the subcutaneous tissue and rectus muscles, the mass is not always palpable, particularly in obese patients.","pyqMatches":[{"year":"2016","no":1331,"q":"Typical of rectus sheath hematoma is","o":["Severe tenderness","Bluish discoloration","Firm painful mass","Ecchymosis"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9070, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 184, '{"id":9070,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":184,"q":"Burr hole is done for -","o":["Chronic SDH","EDH","SAH","Contusion"],"a":0,"e":"Answer- A. Chronic SDH Liquefied SDHs are commonly treated with drainage through one or two burr holes placed over the thickest aspects of the hematoma. Many surgeons place frontal and parietal burr holes that later can be incorporated into a frontotemporoparietal craniotomy, if needed.","pyqMatches":[{"year":"2016","no":1330,"q":"Burr hole is done for","o":["Chronic SDH","EDH","SAH","Contusion"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9071, 'Surgery', 'General Principles & Wounds', 'Hard', 'Surgery', 185, '{"id":9071,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Hard","source":"Surgery","sourceNo":185,"q":"Following road traffic accident patient suffers polytrauma and is evaluated in the emergency section of the hospital. His pulse rate is 116, respiratory rate is 24, blood pressure of 122/78 mm of Hg and patient is mildly anxious. What is the approximate blood loss patient has following trauma?","o":["<750 ml","750 - 1500 ml","1500 - 2000 ml",">2000 ml"],"a":1,"e":"Answer- B. 750 - 1500 ml","pyqMatches":[{"year":"2016","no":1196,"q":"Following road traffic accident patient suffers polytrauma and is evaluated in the emergency section of the hospital. His pulse rate is 116, respiratory rate is 24, blood pressure of 122/78 mm of Hg and patient is mildly anxious. What is the approximate blood loss patient has following trauma?","o":["<750 ml","750 - 1500 ml","1500 - 2000 ml",">2000 ml"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9072, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 186, '{"id":9072,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":186,"q":"Sebaceous cyst occurs occur in all the following locations in body except","o":["Palms and soles","Axilla","Back","Pubic area"],"a":0,"e":"Answer- A. Palms and soles The scalp, scrotum, shoulders, neck, and back are the common sites, but they can occur wherever there are sebaceous glands. There are no sebaceous glands on the palms of the hands and soles of the feet, thus sebaceous cysts are not found in these locations.","pyqMatches":[{"year":"2016","no":1197,"q":"Sebaceous cyst occurs occur in all the following locations in body except","o":["Palms and soles","Axilla","Back","Pubic area"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9073, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 187, '{"id":9073,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":187,"q":"Cortisol levels remain elevated for how many week/s following hemorrhage?","o":["1","2","3","4"],"a":0,"e":"Answer- A. 1 Burn patients have demonstrated elevated circulating cortisol levels for upto 4 weeks, while soft tissue injury and hemorrhage may sustain elevated cortisol levels for as long as 1 week.","pyqMatches":[{"year":"2016","no":1198,"q":"Cortisol levels remain elevated for how many week/s following hemorrhage?","o":["1","2","3","4"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9074, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 188, '{"id":9074,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":188,"q":"A child swallowed a watch battery containing alkaline content. What next -","o":["Immediate X-ray measurements","Remove surgically immediately","CT abdomen","Laxatives"],"a":0,"e":"Answer- A. Immediate X-ray measurements Alkaline dry cell batteries contain : Sodium hydroxide Potassium hydroxide","pyqMatches":[{"year":"2016","no":1329,"q":"A child swallowed a watch battery containing alkaline content. What next","o":["Immediate X-ray measurements","Remove surgically immediately","CT abdomen","Laxatives"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9075, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'Surgery', 189, '{"id":9075,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":189,"q":"Surgical treatment of congenital hydrocele recommended if it fails to resolve by what age?","o":["1 year","2 years","3 years","4 years"],"a":1,"e":"Answer- B. 2 years A patent processusvaginalis that is too narrow to prevent the development of an inguinal hernia may nevertheless allow peritoneal fluid to track down around the testis to form a congenital hydrocele. The majority resolve spontaneously as the processus continues to obliterate but surgical ligation is recommended in boys older than 2 years if they do not resolve spontaneously.","pyqMatches":[{"year":"2016","no":1199,"q":"Surgical treatment of congenital hydrocele recommended if it fails to resolve by what age?","o":["1 year","2 years","3 years","4 years"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9076, 'Surgery', 'Hepatobiliary & Pancreas', 'Easy', 'Surgery', 190, '{"id":9076,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Easy","source":"Surgery","sourceNo":190,"q":"What percentage of gall stones are radio opaque?","o":["10- 20","30 - 40","50 - 60","70 - 80"],"a":0,"e":"Answer- A. 10- 20 Cholelithiasis is a common cause of epigastric or right upper quadrant pain in middle aged obese female patients. Only 15 - 20% of the gall stones are radio-opaque. Gallstones are the most common biliary pathology. It is estimated that gallstones are present in 10-15% of the adult population in the USA.","pyqMatches":[{"year":"2016","no":1200,"q":"What percentage of gall stones are radio opaque?","o":["10- 20","30 - 40","50 - 60","70 - 80"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9077, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 191, '{"id":9077,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":191,"q":"Hemorrhage commonly seen with trivial trauma in elderly -","o":["Subdural hemorrhage","Extradural hemorrhage","Subarachnoid hemorrhage","Intraparenchymal hemorrhage"],"a":0,"e":"Answer- A. Subdural hemorrhage Subdural hemorrhage frequently occurs in older adults, after apparently trivial trauma and is often related to a fall in which there is no direct trauma to the head. Recurrent trivial trauma in elderly is the most common cause of subdural hemorrhage developing.","pyqMatches":[{"year":"2016","no":1326,"q":"Hemorrhage commonly seen with trivial trauma in elderly","o":["Subdural hemorrhage","Extradural hemorrhage","Subarachnoid hemorrhage","Intraparenchymal hemorrhage"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9078, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 192, '{"id":9078,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":192,"q":"Which of the following provides excellent details about the chemodectomas?","o":["Xray","CT angiography","MRI","PET SCAN"],"a":2,"e":"Answer- C. MRI MRI scanning provides excellent detail in most cases of chemodectomas.","pyqMatches":[{"year":"2016","no":1325,"q":"Which of the following provides excellent details about the chemodectomas?","o":["Xray","CT angiography","MRI","PET SCAN"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9079, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 193, '{"id":9079,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":193,"q":"Acral lentigines type of malignant melanoma occurs in -","o":["Face","Nape of neck","Mucosa","Sun exposed areas"],"a":2,"e":"Answer- C. Mucosa Acral lentiginous- Least common with worst prognosis MC site- sole, mucosa","pyqMatches":[{"year":"2016","no":1324,"q":"Acral lentigines type of malignant melanoma occurs in","o":["Face","Nape of neck","Mucosa","Sun exposed areas"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9080, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 194, '{"id":9080,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":194,"q":"Hoarseness of voice in lung carcinoma is due to invasion of which structure?","o":["Recurrent laryngeal nerve","Internal laryngeal nerve","Glossopharyngeal nerve","Vagus nerve"],"a":0,"e":"Answer- A. Recurrent laryngeal nerve Hoarseness- Recurrent laryngeal nerve invasion","pyqMatches":[{"year":"2016","no":1323,"q":"Hoarseness of voice in lung carcinoma is due to invasion of which structure?","o":["Recurrent laryngeal nerve","Internal laryngeal nerve","Glossopharyngeal nerve","Vagus nerve"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9081, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 195, '{"id":9081,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":195,"q":"Percentage of renal stones that are radio-opaque","o":["20","40","60","80"],"a":3,"e":"Answer- D. 80 Routine use of noncontast CT Scan has completely revolutionized to imaging evaluation of renal stone disease, nearly completely replacing plain radigrpahs and X urography for diagnosis of acute ureteral obstruction by renal stones. Nephrolithiasis refers to the presence of calculi in the renal collecting system. Nearly 10 % of the population will form a renal stone in their lifetime. Sufficient calcium oxalate and phosphate is present in 80 % of the renal calculi for them to be radio-opaque on the plain radiographs.","pyqMatches":[{"year":"2016","no":1201,"q":"Percentage of renal stones that are radio-opaque","o":["20","40","60","80"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9082, 'Surgery', 'General Principles & Wounds', 'Moderate', 'Surgery', 196, '{"id":9082,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Moderate","source":"Surgery","sourceNo":196,"q":"Indications of thoracotomy in blunt chest trauma include all except","o":["Initial drainage of > 500 ml of fresh blood","Rupture of bronchous","Continued bleeding of > 200 ml/ hr for >/= 3hrs","Unsuccesful attempt at drainage of cardiac tamponade"],"a":0,"e":"Answer- A. Initial drainage of > 500 ml of fresh blood Continued bleeding of > 200 ml/hr for > 3 hrs Rupture of bronchus, aorta, esophagus or diaphragm. Cardiac tamponade (if needle aspiration unsuccessful).","pyqMatches":[{"year":"2016","no":1202,"q":"Indications of thoracotomy in blunt chest trauma include all except","o":["Initial drainage of > 500 ml of fresh blood","Rupture of bronchous","Continued bleeding of > 200 ml/ hr for >/= 3hrs","Unsuccesful attempt at drainage of cardiac tamponade"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9083, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 197, '{"id":9083,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":197,"q":"Visual examination is used as screening test for","o":["Melanoma","Breast cancer","Thyroid cancer","Testicular cancer"],"a":0,"e":"Answer- A. Melanoma Visual examination is the only screening test for melanoma or skin cancer. For lesions with suspicion of head and neck melanoma, dermatologists visual examination screening is 89 -97% sensitive with 35 - 75% positive predictive value.","pyqMatches":[{"year":"2016","no":1203,"q":"Visual examination is used as screening test for","o":["Melanoma","Breast cancer","Thyroid cancer","Testicular cancer"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9084, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 198, '{"id":9084,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":198,"q":"Embolisation of tumors is done using","o":["Polyvinyl alcohol","Autologous blood clots","Absolute ethanol","All the above"],"a":3,"e":"Answer- D. All the above The following are the embolic materials commonly used for trans-arterial embolization: Gelatin sponge particles Microspheres Autologous blood clots Polyvinyl alcohol n- butylcyanoacrylate glue Absolute ethanol","pyqMatches":[{"year":"2016","no":1204,"q":"Embolisation of tumors is done using","o":["Polyvinyl alcohol","Autologous blood clots","Absolute ethanol","All the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9085, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 199, '{"id":9085,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":199,"q":"Upto Level III lymph node dissection is done for which nodal status of oropharyngeal cancer?","o":["N1","N2","N3","N4"],"a":0,"e":"Answer- A. N1 Management of neck NO Selective neck dissection Oral Cavity at least levels l-lll Oropharynx at least levels ll-lV N1-N2a-c Selective or comprehensive neck Level Vl Subglottic laryngeal cancers","pyqMatches":[{"year":"2016","no":1322,"q":"Upto Level III lymph node dissection is done for which nodal status of oropharyngeal cancer?","o":["N1","N2","N3","N4"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9086, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 200, '{"id":9086,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":200,"q":"Breast surgery is considered under what category of cardiac risk?","o":["> 10 %","5 - 10 %","1 - 5 %","<1%"],"a":3,"e":"Answer- D. <1% Low (reported cardia risk < 1%)- Endoscopic procedures Superficial proccdure Cataract surgery Breast surgery Ambulatory surgery","pyqMatches":[{"year":"2016","no":1206,"q":"Breast surgery is considered under what category of cardiac risk?","o":["> 10 %","5 - 10 %","1 - 5 %","<1%"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9087, 'Surgery', 'General Principles & Wounds', 'Moderate', 'Surgery', 201, '{"id":9087,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Moderate","source":"Surgery","sourceNo":201,"q":"What is the order of disorientation, which a person goes through after an event of trauma to head?","o":["First time, then place followed by person","First place, then time followed by person","First person, then time followed by place","First time, then person followed by place"],"a":0,"e":"Answer- A. First time, then place followed by person Orientation refers to the cleints recognition of person, place and time - that is knowing who and where e or she is and the correct day, date and year. This is commonly documented as \"oriented X 3\". Absence of correct information about person, place and time is referred to as disortientation.","pyqMatches":[{"year":"2016","no":1207,"q":"What is the order of disorientation, which a person goes through after an event of trauma to head?","o":["First time, then place followed by person","First place, then time followed by person","First person, then time followed by place","First time, then person followed by place"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9088, 'Surgery', 'Vascular Surgery', 'Hard', 'Surgery', 202, '{"id":9088,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Hard","source":"Surgery","sourceNo":202,"q":"Which of the following is the preferred route of access for total parenteral nutrition in a patient who requires the same for <14 days and there is otherwise no indication for use of central catheter?","o":["Internal jugular vein","External jugular vein","Periphaeral vein","PICC line"],"a":2,"e":"Answer- C. Periphaeral vein Administration of parenteral nutrition via a peripheral venous catheter should be considered for patients who are likely to need short-term parenteral nutrition (less than 14 days) who have no need for central access for other reasons. Care should be taken in catheter choice, and in attention to pH, tonicity and long-term compatibility of the parenteral nutrition formulations in order to avoid administration or stability problems.","pyqMatches":[{"year":"2016","no":1208,"q":"Which of the following is the preferred route of access for total parenteral nutrition in a patient who requires the same for <14 days and there is otherwise no indication for use of central catheter?","o":["Internal jugular vein","External jugular vein","Periphaeral vein","PICC line"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9089, 'Surgery', 'Vascular Surgery', 'Moderate', 'Surgery', 203, '{"id":9089,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":203,"q":"Which of the following is not true about use of graft in vascular surgery","o":["Autologus saphenous vein achieves superior patency rates to prosthetic materials especially in femorodistal bypass","The patency of the PTFE grafts may be improved by interposition of a vein cuff at proximal anastomosis","Doppler ultrasound assessment is the method of choice for quality assuarance on completion of operative procedure","In the absence of specific contraindications aspirin should be prescribed for all the patients of peripheral vascular disease"],"a":1,"e":"Answer- B. The patency of the PTFE grafts may be improved by interposition of a vein cuff at proximal anastomosis Autologous saphenous vein achieves superior patency rates to prosthetic materials, especially in femorodistal bypass. In situ and reversed vein graft bypasses perform equally well and the choice of technique should be based upon anatomical considerations that are specific to individual patients. In the absence of saphenous vein, no convencing studies exist to suggest the preferred prosthetic alternative. The patency of PTFE grafts may be improved by interposition of a vein cuff at the distal anastomosis. Patency rates associated with pre-cuffed PTFE, grafts are comparable to that obtained from standard PTFE grafts with an interposition vein cuff. There is no justification for the routine use of adjuvant distal arterivenous fistulae.","pyqMatches":[{"year":"2016","no":1209,"q":"Which of the following is not true about use of graft in vascular surgery","o":["Autologus saphenous vein achieves superior patency rates to prosthetic materials especially in femorodistal bypass","The patency of the PTFE grafts may be improved by interposition of a vein cuff at proximal anastomosis","Doppler ultrasound assessment is the method of choice for quality assuarance on completion of operative procedure","In the absence of specific contraindications aspirin should be prescribed for all the patients of peripheral vascular disease"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9090, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 204, '{"id":9090,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":204,"q":"For lower lip carcinoma of <1cm in size. The treatment of choice will be-","o":["Radiation","Chemotherapy","Excision","Radiation and chemotherapy"],"a":2,"e":"Answer- C. Excision Small tumors (T1 & T2) (<2cm) - If 1/3rd or less than 1/3rd lip involved- V or W-shaped excision + primary closure. Excision of lower lip upto 1/3rd can be sutured primarily in 3 layers – mucosa, muscle, and skin keeping vermillion border in proper apposition.","pyqMatches":[{"year":"2016","no":1321,"q":"For lower lip carcinoma of <1cm in size. The treatment of choice will be","o":["Radiation","Chemotherapy","Excision","Radiation and chemotherapy"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9091, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 205, '{"id":9091,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":205,"q":"Preferred treatment for oral tongue carcinoma which infiltrates the local cortical bone is -","o":["Subtotal glossectomy","Subtotal glossectomy + selective neck dissection","Subtotal glossectomy + selective neck dissection + mandibulectomy","Total glossectomy + selective neck dissection + mandibulectomy"],"a":2,"e":"Answer- C. Subtotal glossectomy + selective neck dissection + mandibulectomy The management plan for locally advanced tongue carcinomas includes subtotal glossectomy + selective neck dissection + mandibulectomy. Advanced tumors (T3 and T4) often encroach upon the floor of the mouth and, occasionally, the mandible. In these circumstances, a resection of the tongue and floor of the mouth and mandible is required.","pyqMatches":[{"year":"2016","no":1320,"q":"Preferred treatment for oral tongue carcinoma which infiltrates the local cortical bone is","o":["Subtotal glossectomy","Subtotal glossectomy + selective neck dissection","Subtotal glossectomy + selective neck dissection + mandibulectomy","Total glossectomy + selective neck dissection + mandibulectomy"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9092, 'Surgery', 'Neurosurgery', 'Moderate', 'Surgery', 206, '{"id":9092,"subject":"Surgery","chapter":"Neurosurgery","difficulty":"Moderate","source":"Surgery","sourceNo":206,"q":"Intracranial pressure is not raised during","o":["Hyperventilation","Status epilepticus","Head injury","Subdural hematoma"],"a":0,"e":"Answer- A. Hyperventilation Hyperventilation is used as a treatment with raised intracranial pressure. Hyperventilation causes decreased PaCO2 which subsequently leads to arterial vasoconstriction thus lowering cerebral blood flow (CBF), cerebral blood volume, and intracranial pressure","pyqMatches":[{"year":"2016","no":1210,"q":"Intracranial pressure is not raised during","o":["Hyperventilation","Status epilepticus","Head injury","Subdural hematoma"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9093, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 207, '{"id":9093,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":207,"q":"Outcome of burns depends on -","o":["Extent of burns","Type of resuscitation fluid","Maintenance of airway","Skin grafting"],"a":0,"e":"Answer- A. Extent of burns The various factors influencing the outcome of burns are : Extent of burns Depth of burns Timing of first Escharectomy (removes devitalized tissue and hence source of infection) Age and medical comorbidities","pyqMatches":[{"year":"2016","no":1316,"q":"Outcome of burns depends on","o":["Extent of burns","Type of resuscitation fluid","Maintenance of airway","Skin grafting"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9094, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 208, '{"id":9094,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":208,"q":"Immediate physiological response to sudden decrease in blood volume is","o":["Release of epinephrine","Shift of fluid from intracellular to interstitial compartment","Release of angiotensin","Release of thyroxine"],"a":0,"e":"Answer- A. Release of epinephrine The major hemodynamic abnormality in hypovolemic shock is decrease in preload. The immediate physiological response of the body to the sudden decrease in volume (preload), is a release of catecholamines (epinephrine, norepinephrine). The subsequent increase in heart rate and contractility help maintain cardiac output.","pyqMatches":[{"year":"2016","no":1211,"q":"Immediate physiological response to sudden decrease in blood volume is","o":["Release of epinephrine","Shift of fluid from intracellular to interstitial compartment","Release of angiotensin","Release of thyroxine"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9095, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 209, '{"id":9095,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":209,"q":"Cardinal rule for dressing of pressure ulcer is to -","o":["Keep ulcer tissue dry and surrounding intact tissue dry","Keep ulcer tissue dry and surrounding intact tissue moist","Keep ulcer tissue moist and surrounding intact tissue dry","Keep the ulcer tissue moist and surrounding intact tissue moist"],"a":2,"e":"Answer- C. Keep ulcer tissue moist and surrounding intact tissue dry An ideal dressing should protect the wound, be biocompatible and provide ideal hydration. The type of the ulcer bed and the desired dressing function determine the type of dressing needed. The cardinal rule is to keep the ulcer tissue moist and the surrounding intact tissue dry.","pyqMatches":[{"year":"2016","no":1315,"q":"Cardinal rule for dressing of pressure ulcer is to","o":["Keep ulcer tissue dry and surrounding intact tissue dry","Keep ulcer tissue dry and surrounding intact tissue moist","Keep ulcer tissue moist and surrounding intact tissue dry","Keep the ulcer tissue moist and surrounding intact tissue moist"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9096, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 210, '{"id":9096,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":210,"q":"What is the meaning of the French word \"Debridement\"","o":["Unleash or Cut Open","Debulk","Sanitize","Rehydration"],"a":0,"e":"Answer- A. Unleash or Cut Open Taken from the French meaning to ''unleash or cut open'', debridement has come to mean more than simply the laying open of tissues. It plays a crucial part in the management of trauma.","pyqMatches":[{"year":"2016","no":1314,"q":"What is the meaning of the French word \"Debridement\"","o":["Unleash or Cut Open","Debulk","Sanitize","Rehydration"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9097, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 211, '{"id":9097,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":211,"q":"Slip sign is seen in","o":["Lipoma","Desmoid tumor","Sebaceous cyst","Hernia"],"a":0,"e":"Answer- A. Lipoma A characteristic \"slippage sign\" may be elicited by gently sliding the fingers off the edge of the tumor. The tumor will be felt to slip out from under, as opposed to a sebaceous cyst or an abscess that is tethered by surrounding induration.","pyqMatches":[{"year":"2016","no":1213,"q":"Slip sign is seen in","o":["Lipoma","Desmoid tumor","Sebaceous cyst","Hernia"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9098, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 212, '{"id":9098,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":212,"q":"For reimplantation digits are stored in","o":["Ice packs","Deep freeze","Cold saline","Plastic bags with ice"],"a":3,"e":"Answer- D. Plastic bags with ice The amputated part should be wrapped in moistened gauze and placed in a sealed plastic bag. This bag should then be placed in an ice water bath. Do not use dry ice and do not allow the part to contact ice directly; frostbite can occur in the amputated part, which will decrease its chance of survival after replantation. Bleeding should be controlled in the proximal stump by as minimal a means as necessary, and the stump dressed with a nonadherent gauze and bulky dressing.\"","pyqMatches":[{"year":"2016","no":1214,"q":"For reimplantation digits are stored in","o":["Ice packs","Deep freeze","Cold saline","Plastic bags with ice"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9099, 'Surgery', 'Vascular Surgery', 'Easy', 'Surgery', 213, '{"id":9099,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Easy","source":"Surgery","sourceNo":213,"q":"Characteristic site for development of venous leg ulcers is","o":["Skin of gaiter region","Behind lateral malleolus","Shin of tibia","Medial aspect of knee"],"a":0,"e":"Answer- A. Skin of gaiter region The venous ulcer of the leg characteristically develops in the skin of the gaiter region, the area between the muscles of the calf and the ankle. This is the region where many of the Cockett perforators join the posterior tibial vein to the surface vein, known as the posterior arch vein The majority of ulcers develop on the medial side of the calf but ulcers associated with lesser saphenous incompetence often develop on the lateral side of the leg. Ulcers can develop on any part of the calf skin in patients with post- thrombotic legs; however, venous ulcers rarely extend on to the foot or into the upper calf and, if there is ulceration at these sites, other diagnoses should be seriously considered.","pyqMatches":[{"year":"2016","no":1215,"q":"Characteristic site for development of venous leg ulcers is","o":["Skin of gaiter region","Behind lateral malleolus","Shin of tibia","Medial aspect of knee"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9100, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 214, '{"id":9100,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":214,"q":"Which of the following is true about the management of venous ulcer of lower limb?","o":["Initial treatment is debridement and surgery","Compression dressings should ideally be applied on twice weekly basis","Antibiotics do not speed up the ulcer healing","Biological dressings do not have potential to improve healing"],"a":2,"e":"Answer- C. Antibiotics do not speed up the ulcer healing Patients are initially treated by a compression bandaging regimen. Alternative to these bandaging regimens is to apply a bland absorbent leak-proof dressing beneath a graduated elastic compression stocking (class II). Biopsies are indicated if malignancy is suspected and it is important to remember that a Marjolin''s type of ulcer (a squamous cell or basal cell carcinoma) can develop in a chronic longstanding venous ulcer. Consideration must be given to healing the ulcer by excision and grafting. Biological dressings have been developed, including fetal keratinocytes and collagen meshes Pinch grafts and ulcer excision with mesh grafting have been shown to provide good early healing with moderate long-term results","pyqMatches":[{"year":"2016","no":1216,"q":"Which of the following is true about the management of venous ulcer of lower limb?","o":["Initial treatment is debridement and surgery","Compression dressings should ideally be applied on twice weekly basis","Antibiotics do not speed up the ulcer healing","Biological dressings do not have potential to improve healing"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9101, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 215, '{"id":9101,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":215,"q":"Which of the following suture has max tensile strength and minimum tissue reaction","o":["Poliglecaprone","Polypropylene","Polygalctine","Polydioxanone"],"a":1,"e":"Answer- B. Polypropylene Polypropylene sutures are non-absorbable and provide permanent wound support. Polypropylene sutures are blue colored for easy identification during surgery. Polypropylene sutures have excellent tensile strength and are used for orthopaedic, plastic and micro surgeries, general closure and cardiovascular surgeries","pyqMatches":[{"year":"2016","no":1217,"q":"Which of the following suture has max tensile strength and minimum tissue reaction","o":["Poliglecaprone","Polypropylene","Polygalctine","Polydioxanone"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9102, 'Surgery', 'General Principles & Wounds', 'Hard', 'Surgery', 216, '{"id":9102,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Hard","source":"Surgery","sourceNo":216,"q":"Blunt trauma exploratory laparotomy done nonexpansile swelling found on mesenteric border of intestine, management","o":["Resection and anastomosis","Ligation","Excision of swelling","None"],"a":3,"e":"Answer- D. None Non Expansile swelling on mesenteric border of intestine is almost always due to mesenteric adenitis and it is an incidental finding, hence warranting no surgical intervention.","pyqMatches":[{"year":"2016","no":1218,"q":"Blunt trauma exploratory laparotomy done nonexpansile swelling found on mesenteric border of intestine, management","o":["Resection and anastomosis","Ligation","Excision of swelling","None"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9103, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 217, '{"id":9103,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":217,"q":"In SVC syndrome for non small cell carcinoma of lung management done","o":["Radiotherapy","Immunotherapy","Chemotherapy","Surgery"],"a":0,"e":"Answer- A. Radiotherapy In patients with SVCS secondary to non–small-cell carcinoma of the lung, radiotherapy is the primary treatment. The likelihood of patients benefiting from such therapy is high, but the overall prognosis of these patients is poor Small cell carcinoma of lung presenting as SVC syndrome - Combination of chemotherapy and radiotherapy. Non Small cell carcinoma of lung presenting as SVC syndrome- Radiotherpy alone.","pyqMatches":[{"year":"2016","no":1219,"q":"In SVC syndrome for non small cell carcinoma of lung management done","o":["Radiotherapy","Immunotherapy","Chemotherapy","Surgery"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9104, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 218, '{"id":9104,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":218,"q":"Hadfields operation is performed for which of the following pathology?","o":["Duct ectasia","Fibroadenoma","Mondors disease","Inflammatory breast carcinoma"],"a":0,"e":"Answer- A. Duct ectasia TREATMENT- Stop smoking Hadfield’s operation- excision of all major ducts Antibiotics- amoxiclav and metronidazole","pyqMatches":[{"year":"2016","no":1220,"q":"Hadfields operation is performed for which of the following pathology?","o":["Duct ectasia","Fibroadenoma","Mondors disease","Inflammatory breast carcinoma"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9105, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 219, '{"id":9105,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":219,"q":"Microdochotomy is treatment for","o":["Duct ectasia","Breast abscess","Duct papilloma","DCIS"],"a":2,"e":"Answer- C. Duct papilloma The final diagnosis is made by excising the involved duct (Microdochotomy) and any underlying mass if present and subjecting them for a histopathological diagnosis","pyqMatches":[{"year":"2016","no":1221,"q":"Microdochotomy is treatment for","o":["Duct ectasia","Breast abscess","Duct papilloma","DCIS"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9106, 'Surgery', 'Breast Surgery', 'Moderate', 'Surgery', 220, '{"id":9106,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":220,"q":"Previous radition therapy for which disease particulary increases the risk of breast carcinoma development?","o":["Hodgkins lymphoma","Mantle cell lymphoma","Nasopharyngeal carcinoma","Lung carcinoma"],"a":0,"e":"Answer- A. Hodgkins lymphoma A real problem in women who have been treated with mantle radiotherapy as part of the management of Hodgkin''s disease, in which significant doses of radiation to the breast are received.","pyqMatches":[{"year":"2016","no":1222,"q":"Previous radition therapy for which disease particulary increases the risk of breast carcinoma development?","o":["Hodgkins lymphoma","Mantle cell lymphoma","Nasopharyngeal carcinoma","Lung carcinoma"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9107, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 221, '{"id":9107,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":221,"q":"LAHSAL code is used to represent congenital malformation of -","o":["Lip","Alveolus","Hard and soft palate","All the above"],"a":3,"e":"Answer- D. All the above","pyqMatches":[{"year":"2016","no":1313,"q":"LAHSAL code is used to represent congenital malformation of","o":["Lip","Alveolus","Hard and soft palate","All the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9108, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 222, '{"id":9108,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":222,"q":"Which of the following histological type of breast carcinoma worst prognosis?","o":["Tubular","Colloid","Papillary","Scirrhous"],"a":3,"e":"Answer- D. Scirrhous MC type of breast carcinoma is invasive ductal carcinoma (schirrhous). MC form seen (60- 75%) Hard lump, whitish yellow, non capsulated, irregular with cartilaginous consistency Retraction of nipple","pyqMatches":[{"year":"2016","no":1223,"q":"Which of the following histological type of breast carcinoma worst prognosis?","o":["Tubular","Colloid","Papillary","Scirrhous"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9109, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 223, '{"id":9109,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":223,"q":"Kernahen''s striped ''Y'' classification, Main reference point is -","o":["Incisive foramen","Soft palate","Hard palate","Third molar"],"a":0,"e":"Answer- A. Incisive foramen Kernahen''s striped ''Y'' classification It is used to classify cleft lip and cleft palate The incisive foramen is taken as reference point","pyqMatches":[{"year":"2016","no":1312,"q":"Kernahen''s striped ''Y'' classification, Main reference point is","o":["Incisive foramen","Soft palate","Hard palate","Third molar"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9110, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 224, '{"id":9110,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":224,"q":"The most commonly used myocutaneous pedicle graft for pelvis surgeries contains muscle segments from -","o":["Rectus abdominis muscle","External oblique muscle","Internal oblique muscle","Transversus abdominis muscle"],"a":0,"e":"Answer- A. Rectus abdominis muscle The most frequently used myocutneous pedicle grafts contain, muscle segments from the rectus abdominis muscle of the anterior abdominal wall, gracialis muscle of the inner thigh, bulbocavernosus muscle of the vulva, the tensor fascia lata muscle of the lateral thigh, and gluteus maximus muscle.","pyqMatches":[{"year":"2016","no":1311,"q":"The most commonly used myocutaneous pedicle graft for pelvis surgeries contains muscle segments from","o":["Rectus abdominis muscle","External oblique muscle","Internal oblique muscle","Transversus abdominis muscle"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9111, 'Surgery', 'Breast Surgery', 'Hard', 'Surgery', 225, '{"id":9111,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Hard","source":"Surgery","sourceNo":225,"q":"52 years female patient presents with 4 cm diameter diagnosed breast cancer lesion with ipsilateral axillary and contralateral supraclavicular lymphadenopathy. As per AJCC system, patient belongs to which stage of breast cancer?","o":["Ilia","None","IIIc","IV"],"a":3,"e":"Answer- D. IV","pyqMatches":[{"year":"2016","no":1224,"q":"52 years female patient presents with 4 cm diameter diagnosed breast cancer lesion with ipsilateral axillary and contralateral supraclavicular lymphadenopathy. As per AJCC system, patient belongs to which stage of breast cancer?","o":["Ilia","None","IIIc","IV"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9112, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 226, '{"id":9112,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":226,"q":"Revascularization and angiogenesis process after skin grafting is seen after how many days after the procedure?","o":["4","5","6","7"],"a":1,"e":"Answer- B. 5 Revascularization or angiogenesis After approx 5 days, revascularization occurs and the graft demonstrates both arterial inflow and venous outflow.","pyqMatches":[{"year":"2016","no":1310,"q":"Revascularization and angiogenesis process after skin grafting is seen after how many days after the procedure?","o":["4","5","6","7"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9113, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 227, '{"id":9113,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":227,"q":"Best prognosis for carcinoma breast is seen with which of the following?","o":["<1cm size, nodes -ye , ER/ PR +ve, her 2/ neu -ye","<1cm size, nodes -ye , ER/ PR -ye, her 2/ neu +ve","<2cm size, nodes -ye , ER/ PR +ve, her 2/ neu -ye","<2cm size, nodes -ye , ER/ PR -ye, her 2/ neu +ve"],"a":0,"e":"Answer- A. <1cm size, nodes -ye , ER/ PR +ve, her 2/ neu -ye Molecular changes in the tumor are also useful. Tumors that overexpress erbB2 (HER2/neu) or have a mutated p53 gene have a worse prognosis. Tumors that overexpress erbB2 are more likely to respond to higher doses of doxorubicin- containing regimens and predict those tumors that will respond to HER2/neu antibodies (trastuzumab) (herceptin) and HER2/ neu kinase inhibitors.","pyqMatches":[{"year":"2016","no":1225,"q":"Best prognosis for carcinoma breast is seen with which of the following?","o":["<1cm size, nodes -ye , ER/ PR +ve, her 2/ neu -ye","<1cm size, nodes -ye , ER/ PR -ye, her 2/ neu +ve","<2cm size, nodes -ye , ER/ PR +ve, her 2/ neu -ye","<2cm size, nodes -ye , ER/ PR -ye, her 2/ neu +ve"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9114, 'Surgery', 'Breast Surgery', 'Moderate', 'Surgery', 228, '{"id":9114,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":228,"q":"Favorable prognosis with > 90% 5 year survival rate for carcinoma breast is seen in which of the following?","o":["Screen detected ductal carcinoma in situ","Screen detected lobular carcinoma in situ","Node negative tumor with favourable histology","None of the above"],"a":0,"e":"Answer- A. Screen detected ductal carcinoma in situ Intraductal carcinoma (malignant mammary ductal epithelial cells) without any invasion into basement membrane.","pyqMatches":[{"year":"2016","no":1226,"q":"Favorable prognosis with > 90% 5 year survival rate for carcinoma breast is seen in which of the following?","o":["Screen detected ductal carcinoma in situ","Screen detected lobular carcinoma in situ","Node negative tumor with favourable histology","None of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9115, 'Surgery', 'Breast Surgery', 'Moderate', 'Surgery', 229, '{"id":9115,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":229,"q":"What percentage of reduction in dying from breast cancer can be achieved with annual screening after age of 50 yrs with mammography?","o":["15- 20 %","20- 25 %","25- 30 %","30- 35 %"],"a":2,"e":"Answer- C. 25- 30 % Meta-analysis examining outcomes from every randomized trial of mammography conclusively shows a 25-30% reduction in the chance of dying from breast cancer with annual screening after age 50 years.","pyqMatches":[{"year":"2016","no":1228,"q":"What percentage of reduction in dying from breast cancer can be achieved with annual screening after age of 50 yrs with mammography?","o":["15- 20 %","20- 25 %","25- 30 %","30- 35 %"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9116, 'Surgery', 'Breast Surgery', 'Moderate', 'Surgery', 230, '{"id":9116,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":230,"q":"Which of the following hormonal levels influence the development of benign breast disease?","o":["Estrogen","Progesterone","Lutenizing hormone","Testosterone"],"a":0,"e":":B Answer- A.Estrogen & B. Progesterone Etiology/Pathogenesis Hormonal: Responsiveness of breast tissue to monthly changes of estrogen and progesterone play an important role in pathogenesis of benign breast disease. They may be related to excess hormonal stimulation or hypersensitivity of breast tissue.","pyqMatches":[{"year":"2016","no":1229,"q":"Which of the following hormonal levels influence the development of benign breast disease?","o":["Estrogen","Progesterone","Lutenizing hormone","Testosterone"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9117, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 231, '{"id":9117,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":231,"q":"Which of the following is true about breast reconstruction surgery","o":["Easiest reconstruction is done using silicon gel implant","TRAM flap gives better cosmetic results than LD flap","Radiotherapy in post op period does not influence the outcome after breast reconstruction","Nipple reconstruction cannot be performed under local anesthesia"],"a":0,"e":"Answer- A. Easiest reconstruction is done using silicon gel implant The easiest type of reconstruction is using a silicone gel implant under the pectoralis major muscle. This may be combined with prior tissue expansion using an expandable saline prosthesis first (or a combined device), which creates some ptosis of the new breast. If the skin at the mastectomy site is poor (e.g. following radiotherapy) or if a larger volume of tissue is required, a musculocutaneous flap can be constructed either from the latissimusdorsi muscle (an LD flap) or using the transversusabdominis muscle (a TRAM flap as). The latter gives an excellent cosmetic result in experienced hands but is a lengthy procedure and requires careful patient selection. It is now usually performed as a free transfer using microvascular anastomosis, although the pedicled TRAM from the contralateral side is still used. Variations on the TRAM flap requiring less muscle harvesting, such as the DIEP flap (based on deep inferior epigastric vessels), are increasingly being used. Impediments to immediate reconstruction include insufficient theatre time and a lack of experienced reconstructive surgeons. In addition, if a patient is likely to need postoperative radiotherapy then a delayed reconstruction using a flap often gives a better result. Radiotherapy onto a prosthesis often leads to a high incidence of capsular contracture and unacceptable results. Nipple reconstruction is a relatively simple procedure that can be performed under a local anaesthetic.","pyqMatches":[{"year":"2016","no":1230,"q":"Which of the following is true about breast reconstruction surgery","o":["Easiest reconstruction is done using silicon gel implant","TRAM flap gives better cosmetic results than LD flap","Radiotherapy in post op period does not influence the outcome after breast reconstruction","Nipple reconstruction cannot be performed under local anesthesia"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9118, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 232, '{"id":9118,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":232,"q":"Treatment of large omphalocele defect can be done by","o":["Primary closure","Staged closure using PTFE mesh","Painting intact sac daily with antiseptic solution","All the above"],"a":3,"e":"Answer- D. All the above Large defects present a more substantial problem and four techniques have been described: non-operative therapy, skin flap closure, staged closure and primary closure","pyqMatches":[{"year":"2016","no":1231,"q":"Treatment of large omphalocele defect can be done by","o":["Primary closure","Staged closure using PTFE mesh","Painting intact sac daily with antiseptic solution","All the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9119, 'Surgery', 'Breast Surgery', 'Moderate', 'Surgery', 233, '{"id":9119,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":233,"q":"Which of the following is not true about Pateys mastectomy","o":["It is also called modified radical mastectomy","Intercosto brachial nerves are usually preserved","All lymph nodes of axilla are removed","Pectoralis muscle is either divided or retracted"],"a":1,"e":"Answer- B. Intercosto brachial nerves are usually preserved It is also called modified radical mastectomy and is a commonly performed procedure. The intercostal brachial nerves are usually divided in this operation and the patient should be warned about sensation changes postoperatively. The wound is drained using a wide-bore suction tube. Early mobilisation of the arm is encouraged and physiotherapy helps normal function to return very quickly","pyqMatches":[{"year":"2016","no":1232,"q":"Which of the following is not true about Pateys mastectomy","o":["It is also called modified radical mastectomy","Intercosto brachial nerves are usually preserved","All lymph nodes of axilla are removed","Pectoralis muscle is either divided or retracted"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9120, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 234, '{"id":9120,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":234,"q":"Dermoepidermal burn is what degree of burn -","o":["I","II","III","IV"],"a":1,"e":"Answer- B. II Dermoepidermal burns are Superficial II degree burns.","pyqMatches":[{"year":"2016","no":1309,"q":"Dermoepidermal burn is what degree of burn","o":["I","II","III","IV"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9121, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 235, '{"id":9121,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":235,"q":"Macroprolactinoma ideal treatment is","o":["Excision","Bromocriptine","Stereotactic radio surgery","Observation"],"a":1,"e":"Answer- B Bromocriptine (BEC) is generally considered to be the agent of choice in the treatment of prolactinoma because of its long track record and safety.","pyqMatches":[{"year":"2016","no":1233,"q":"Macroprolactinoma ideal treatment is","o":["Excision","Bromocriptine","Stereotactic radio surgery","Observation"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9122, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 236, '{"id":9122,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":236,"q":"Initial treatment for most patient of growth hormone secreting pituitary adenoma is","o":["Transphenoidal surgical resection","Somatostatin analogs","GH rector antagonists","Dopamine agonists"],"a":0,"e":"Answer- A. Transphenoidal surgical resection Transsphenoidal surgical resection by an experienced surgeon is the preferred primary treatment for both microadenomas (cure rate -70%) and macroadenomas (<50% cured).","pyqMatches":[{"year":"2016","no":1234,"q":"Initial treatment for most patient of growth hormone secreting pituitary adenoma is","o":["Transphenoidal surgical resection","Somatostatin analogs","GH rector antagonists","Dopamine agonists"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9123, 'Surgery', 'Endocrine Surgery', 'Easy', 'Surgery', 237, '{"id":9123,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Easy","source":"Surgery","sourceNo":237,"q":"Radioiodine preferred in treatment in","o":["Young patients","Pregnancy","Recent onset of toxic goiter","Post surgery for papillary thyroid cancer"],"a":2,"e":"Answer- C. Recent onset of toxic goiter The main indications for RAI therapy include the following conditions","pyqMatches":[{"year":"2016","no":1235,"q":"Radioiodine preferred in treatment in","o":["Young patients","Pregnancy","Recent onset of toxic goiter","Post surgery for papillary thyroid cancer"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9124, 'Surgery', 'Endocrine Surgery', 'Hard', 'Surgery', 238, '{"id":9124,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Hard","source":"Surgery","sourceNo":238,"q":"Parathyroid adenomas account for how much percentage of patients with primary hyperpara-thyroidism?","o":["50%","60%","70%","80%"],"a":3,"e":"Answer- D. 80% Solitary adenomas, A single abnormal gland, is the cause in -80% of patients; the abnormality in the gland is usually a benign neoplasm or adenoma and rarely a parathyroid carcinoma.","pyqMatches":[{"year":"2016","no":1236,"q":"Parathyroid adenomas account for how much percentage of patients with primary hyperpara-thyroidism?","o":["50%","60%","70%","80%"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9125, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 239, '{"id":9125,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":239,"q":"Investigation of choice for hepatic metastasis form stomach cancer is","o":["MRI","CECT","USG","HIDA"],"a":1,"e":"Answer- B. CECT CT is the imaging modality of choice for evaluating liver metastases. This preference is largely attributable to the effects of the dual blood supply on the enhancement characteristics of metastases, as compared with normal liver parenchyma.","pyqMatches":[{"year":"2016","no":1238,"q":"Investigation of choice for hepatic metastasis form stomach cancer is","o":["MRI","CECT","USG","HIDA"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9126, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 240, '{"id":9126,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":240,"q":"Normal urine flow rate in healthy adults in urodynamic study is -","o":["10 ml/sec","20 ml/sec","25 ml/sec","5 ml/sec"],"a":1,"e":"Answer- B. 20 ml/sec Ages 14 to 45 -- The average flow rate for males is 21 mL/sec. The average flow rate for females is 18 mL/sec. Ages 46 to 65 -- The average flow rate for males is 12 mL/sec. The average flow rate for females is 18 mL/sec. Ages 66 to 80 -- The average flow rate for males is 9 mL/sec. The average flow rate for females is 18 mL/sec.","pyqMatches":[{"year":"2016","no":1308,"q":"Normal urine flow rate in healthy adults in urodynamic study is","o":["10 ml/sec","20 ml/sec","25 ml/sec","5 ml/sec"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9127, 'Surgery', 'Endocrine Surgery', 'Moderate', 'Surgery', 241, '{"id":9127,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":241,"q":"Radical nephrectomy involves resection of the following except -","o":["Gerotas fascia","Ipsilateral adrenal gland","Surrounding hilar lymph nodes","Proximal para-aortic lymph nodes"],"a":3,"e":"Answer- D. Proximal para-aortic lymph nodes The standard management for stage I or II tumors and selected cases of stage III disease is radical nephrectomy. This procedure involves en bloc removal of Gerota''s fascia and its contents, including the kidney, the ipsilateral adrenal gland, and adjacent hilar lymph nodes.","pyqMatches":[{"year":"2016","no":1307,"q":"Radical nephrectomy involves resection of the following except","o":["Gerotas fascia","Ipsilateral adrenal gland","Surrounding hilar lymph nodes","Proximal para-aortic lymph nodes"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9128, 'Surgery', 'Hepatobiliary & Pancreas', 'Easy', 'Surgery', 242, '{"id":9128,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Easy","source":"Surgery","sourceNo":242,"q":"Prognosis of surgery for liver secondaries is best for which cancer?","o":["Colorectal","Neuroendocrine","Genitourinary","Esophageal"],"a":2,"e":"Answer- C. Genitourinary For noncolorectal, nonneuroendocrine tumors, metastases from genitourinary primaries have the best prognosis following hepatic metastatectomy.","pyqMatches":[{"year":"2016","no":1239,"q":"Prognosis of surgery for liver secondaries is best for which cancer?","o":["Colorectal","Neuroendocrine","Genitourinary","Esophageal"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9129, 'Surgery', 'Transplantation', 'Moderate', 'Surgery', 243, '{"id":9129,"subject":"Surgery","chapter":"Transplantation","difficulty":"Moderate","source":"Surgery","sourceNo":243,"q":"Indicatons of liver transplant in PCM poisoning are all except","o":["SGPT increase","PT/INR","High creatinine","Encephalopathy"],"a":0,"e":"Answer- A. SGPT increase Indication poor prognosis and hence necessitate a transplant in such patients-","pyqMatches":[{"year":"2016","no":1240,"q":"Indicatons of liver transplant in PCM poisoning are all except","o":["SGPT increase","PT/INR","High creatinine","Encephalopathy"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9130, 'Surgery', 'Urology', 'Easy', 'Surgery', 244, '{"id":9130,"subject":"Surgery","chapter":"Urology","difficulty":"Easy","source":"Surgery","sourceNo":244,"q":"Harder renal stone having less satisfactory results with ECWL is -","o":["Oxalate stone","Phosphate stone","Urate stone","Cystine stone"],"a":3,"e":"Answer- D. Cystine stone Extracorporeal Shockwave Lithotripsy (ECWL): A urinary calculus has a crystalline structure. Bombarded with shock waves of sufficient energy it disintegrates into fragments. The clearance of stone from the kidney using ESWL will depend upon the consistency of the stone and its site. Most oxalate and phosphate stones fragment well.","pyqMatches":[{"year":"2016","no":1306,"q":"Harder renal stone having less satisfactory results with ECWL is","o":["Oxalate stone","Phosphate stone","Urate stone","Cystine stone"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9131, 'Surgery', 'Transplantation', 'Easy', 'Surgery', 245, '{"id":9131,"subject":"Surgery","chapter":"Transplantation","difficulty":"Easy","source":"Surgery","sourceNo":245,"q":"Milan criteria is for","o":["Selecting patients for Liver transplantation","Selecting patients for Lung transplantation","Selecting patients for Kidney transplantation","Selecting patients for heart trnasplantation"],"a":0,"e":"Answer- A. Selecting patients for Liver transplantation The Milan criteria state that a patient is selected for transplantation when he or she has:","pyqMatches":[{"year":"2016","no":1241,"q":"Milan criteria is for","o":["Selecting patients for Liver transplantation","Selecting patients for Lung transplantation","Selecting patients for Kidney transplantation","Selecting patients for heart trnasplantation"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9132, 'Surgery', 'Urology', 'Hard', 'Surgery', 246, '{"id":9132,"subject":"Surgery","chapter":"Urology","difficulty":"Hard","source":"Surgery","sourceNo":246,"q":"What should be the plan of management for a patient for whom while undergoing simple cholecystectomy T2 gall bladder carcinoma is discovered?","o":["Resection of 4b-5 segement, dissection of the N1-2 nodes and excision of port sites","Post operative adjuvant chemotherapy","Radical cholecystectomy","Whipples procedure"],"a":0,"e":"Answer- A. Resection of 4b-5 segement, dissection of the N1-2 nodes and excision of port sites Stage I and II - simple cholecystectomy Stage III – cholecystectomy + adjacent hepatic resection (atleast 2cm depth) + regional lymphadenectomy Poor prognosis","pyqMatches":[{"year":"2016","no":1242,"q":"What should be the plan of management for a patient for whom while undergoing simple cholecystectomy T2 gall bladder carcinoma is discovered?","o":["Resection of 4b-5 segement, dissection of the N1-2 nodes and excision of port sites","Post operative adjuvant chemotherapy","Radical cholecystectomy","Whipples procedure"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9133, 'Surgery', 'Urology', 'Easy', 'Surgery', 247, '{"id":9133,"subject":"Surgery","chapter":"Urology","difficulty":"Easy","source":"Surgery","sourceNo":247,"q":"Following are the sign/s suggestive of obstruction of urinary tract on CT Scan","o":["Hyroureter","Perinephric stranding","Thickening of the lateroconal fascia","All the above"],"a":3,"e":"Answer- D. All the above Nonenhanced CT has been accepted as the imaging modality of choice in the radiologic evaluation of patients suspected of having urolithiasis. CT is superior to other imaging modalities in the diagnostic accuracy and assessment of their characteristics. The most direct sign of ureterolithiasis is the stone within the ureteral lumen, with proximal ureteral dilatation and normal distal caliber. Other favorable secondary signs at CT are: Hydroureter, hydronephrosis, perinephric stranding, periureteral edema and unilateral renal enlargement.","pyqMatches":[{"year":"2016","no":1305,"q":"Following are the sign/s suggestive of obstruction of urinary tract on CT Scan","o":["Hyroureter","Perinephric stranding","Thickening of the lateroconal fascia","All the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9134, 'Surgery', 'Urology', 'Easy', 'Surgery', 248, '{"id":9134,"subject":"Surgery","chapter":"Urology","difficulty":"Easy","source":"Surgery","sourceNo":248,"q":"Treatment of choice for bladder stone","o":["Transurethral litholapaxy","Percutaneous suprapubic litholapaxy","Vesicotomy and stone retrieval","Intravenous antibiotics"],"a":0,"e":"Answer- A. Transurethral litholapaxy TREATMENT- A transurethral cystolitholapaxy is the most common procedure used to treat adults with bladder stones. Small stone- Ultrasound lithotripsy Large stone- laser lithotripsy Litholapaxy- cystoscopic lithotrite Suprapubic cystolithotomy","pyqMatches":[{"year":"2016","no":1304,"q":"Treatment of choice for bladder stone","o":["Transurethral litholapaxy","Percutaneous suprapubic litholapaxy","Vesicotomy and stone retrieval","Intravenous antibiotics"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9135, 'Surgery', 'Urology', 'Easy', 'Surgery', 249, '{"id":9135,"subject":"Surgery","chapter":"Urology","difficulty":"Easy","source":"Surgery","sourceNo":249,"q":"3cm stone in cystic duct near the ampulla of vater, The Method of removal is a","o":["Transduodenal approach","Supraduodenal approach","Lithotripsy","Chemical dissolution"],"a":0,"e":"Answer- A. Transduodenal approach According to Maingot''s \"The methods of surgical drainage include transduodenal sphincterotomy, choledochoduodenotomy, and choledochojejunostomy.\"","pyqMatches":[{"year":"2016","no":1244,"q":"3cm stone in cystic duct near the ampulla of vater, The Method of removal is a","o":["Transduodenal approach","Supraduodenal approach","Lithotripsy","Chemical dissolution"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9136, 'Surgery', 'Urology', 'Hard', 'Surgery', 250, '{"id":9136,"subject":"Surgery","chapter":"Urology","difficulty":"Hard","source":"Surgery","sourceNo":250,"q":"40 years old male complains of loin pain since 1 month. Patient''s complaint of pain has severely increased over last 2 hours and pain now radiates from loin and to groin and anterior thigh and patient is writhing in bed for comfort. What is the most probable etiology?","o":["Bladder calculus","Ureteric calculus","Vesico ureteric reflux","Hydronephrosis"],"a":1,"e":"Answer- B. Ureteric calculus There is a pattern of severe exacerbation on a background of continuing pain Radiates to the groin, penis, scrotum or labium as the stone progresses down the ureter The severity of pain is not related to the size of the stone The pain is almost invariably associated with haematuria There may be few physical signs","pyqMatches":[{"year":"2016","no":1303,"q":"40 years old male complains of loin pain since 1 month. Patient''s complaint of pain has severely increased over last 2 hours and pain now radiates from loin and to groin and anterior thigh and patient is writhing in bed for comfort. What is the most probable etiology?","o":["Bladder calculus","Ureteric calculus","Vesico ureteric reflux","Hydronephrosis"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9137, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 251, '{"id":9137,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":251,"q":"What is the main hazard of ectopic testis -","o":["Impotence","Carcinoma development","Liable to injury","Hernia development"],"a":2,"e":"Answer- C. Liable to injury The main hazard is liability to injury.","pyqMatches":[{"year":"2016","no":1302,"q":"What is the main hazard of ectopic testis","o":["Impotence","Carcinoma development","Liable to injury","Hernia development"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9138, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 252, '{"id":9138,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":252,"q":"Traditionally scrotal carcinoma is associated with which of the following occupations?","o":["Chimney sweeps","Mule spinners","Coal worker","Wood workers"],"a":0,"e":"Answer- (A) Chimney sweeps Carcinoma of the scrotum. It is traditionally recognized as an occupational hazard for chimney sweeps and mule spinners. It was described by Potts. It was the first cancer linked to occupational exposure when, in 1775, Perivall Pott described it in chimney sweeps in England. Other occupations that had a preponderance of the disease included people who worked with the distillates of coal and men exposed to mineral oil.","pyqMatches":[{"year":"2016","no":1301,"q":"Traditionally scrotal carcinoma is associated with which of the following occupations?","o":["Chimney sweeps","Mule spinners","Coal worker","Wood workers"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9139, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 253, '{"id":9139,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":253,"q":"Which of the following are the treatment options for cystocele?","o":["Anterior colporrhaphy","Transvaginal tape","Transobturator tape","All the above"],"a":3,"e":"Answer- D. All the above Traditionally; an anterior vaginal wall repair (anterior colporrhaphy) was performed vaginally; now replaced by vaginally inserted tape [transvaginal tape (TVT) or transobturator tape (TOT)] or mesh slings.","pyqMatches":[{"year":"2016","no":1300,"q":"Which of the following are the treatment options for cystocele?","o":["Anterior colporrhaphy","Transvaginal tape","Transobturator tape","All the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9140, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 254, '{"id":9140,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":254,"q":"Most common site of penile carcinoma is -","o":["Glans","Prepuce","Shaft","Coronal sulcus"],"a":0,"e":"Answer- A. Glans When it occurs on the glans penis, it is known as erythroplasia of Queyrat and when it occurs on the shaft of the penis it is called Bowen''s disease. Carcinoma of the penis is most typically a squamous cell carcinoma arising in the skin of the glans penis or the prepuce. MC orginates from glans > sulcus > prepuce > shaft","pyqMatches":[{"year":"2016","no":1299,"q":"Most common site of penile carcinoma is","o":["Glans","Prepuce","Shaft","Coronal sulcus"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9141, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 255, '{"id":9141,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":255,"q":"Best time for surgery of hypospadias is at what age -","o":["0 - 4 months","4 - 6 months","6 - 10 months","> 2 years"],"a":2,"e":"Answer- C. 6 - 10 months Operations for hypospadiasis are routinely performed when the patient is between 6 and 18 months of age. The infant has good tolerance to surgery and anesthesia by the age of 6 months. The child is well aware of his genitalia and toilet training by the age of 18 months. So, the most suitable age for the operation of hypospadias is between 6 and 18 months. The degree of hypospadias dictates the need for repair. If the opening is glanular or coronal (85% of patients), the penis is usually functional both for micturition and procreation and repair is done primarily for cosmetic reasons. Openings that are more proximal on the shaft require correction to allow voiding while standing, normal erection, and proper sperm deposition during intercourse. The commonest procedure for distal hypospadias is the ‘tubularized incised plate’ urethroplasty, while techniques that utilize the foreskin are commonly used for more proximal hypospadias. Complications of hypospadias surgery: urethrocutaneous fistula (most common) Recurrence of chordee Urethral stricture Meatal stenosis Infection","pyqMatches":[{"year":"2016","no":1297,"q":"Best time for surgery of hypospadias is at what age","o":["0 - 4 months","4 - 6 months","6 - 10 months","> 2 years"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9142, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 256, '{"id":9142,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":256,"q":"Commonest site of hypospadias is -","o":["Just proximal to glans","In the meid of penis","Scrotum","Perineum"],"a":0,"e":"Answer- A. Just proximal to glans Hypospadias is a condition in which the urethral meatus opens on the underside of penis or the perineum (i.e. ventral surface of penis) proximal to the tip of the glans penis.","pyqMatches":[{"year":"2016","no":1296,"q":"Commonest site of hypospadias is","o":["Just proximal to glans","In the meid of penis","Scrotum","Perineum"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9143, 'Surgery', 'Hepatobiliary & Pancreas', 'Easy', 'Surgery', 257, '{"id":9143,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Easy","source":"Surgery","sourceNo":257,"q":"Which enzyme is of diagnostic importance in chronic pancreatitis","o":["Amylase","Pancreatic polypeptide","Lipase","Serum Interleukin 6 levels"],"a":2,"e":"Answer- C. Lipase Elevated lipase levels are more specific to the pancreas than elevated amylase levels. Lipase levels remain high for 12 days. In patients with chronic pancreatitis (usually caused by alcohol abuse), lipase levels may be elevated in the presence of a normal serum amylase level.","pyqMatches":[{"year":"2016","no":1249,"q":"Which enzyme is of diagnostic importance in chronic pancreatitis","o":["Amylase","Pancreatic polypeptide","Lipase","Serum Interleukin 6 levels"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9144, 'Surgery', 'Urology', 'Easy', 'Surgery', 258, '{"id":9144,"subject":"Surgery","chapter":"Urology","difficulty":"Easy","source":"Surgery","sourceNo":258,"q":"Most common screening test for acute pancreatitis -","o":["Serum amylase","Serum lipase","Urine trypsinogen","Insulin"],"a":2,"e":"Answer- C. Urine trypsinogen Rapid measurement of urinary trypsinogen - 2 level is useful in the emergency department as a screening test for acute pancreatitis.","pyqMatches":[{"year":"2016","no":1250,"q":"Most common screening test for acute pancreatitis","o":["Serum amylase","Serum lipase","Urine trypsinogen","Insulin"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9145, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 259, '{"id":9145,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":259,"q":"Physiological adhesions between foreskin and glans penis persist until years of age -","o":["4","5","6","7"],"a":2,"e":"Answer- C. 6 Phimosis is a condition in which the foreskin of the penis cannot be pulled back past the glans. The physiological adhesions between the foreskin and the glans penis may persist until 6 years of age or more, giving the false impression that the prepuce will not retract.","pyqMatches":[{"year":"2016","no":1295,"q":"Physiological adhesions between foreskin and glans penis persist until years of age","o":["4","5","6","7"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9146, 'Surgery', 'Hepatobiliary & Pancreas', 'Moderate', 'Surgery', 260, '{"id":9146,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Moderate","source":"Surgery","sourceNo":260,"q":"Which of the following is/ are the imaging criteria for unresectable carcinoma of pancreas?","o":["Metastatic spread to vertebrae","Invasion in duodenal wall","Irregular increase in density of omental fat","All the above"],"a":3,"e":"Answer- D. All the above Metastatic spred outside the pancreas makes tumor irresectable. Tumor invasion into adjacent organs significs unresectability.","pyqMatches":[{"year":"2016","no":1251,"q":"Which of the following is/ are the imaging criteria for unresectable carcinoma of pancreas?","o":["Metastatic spread to vertebrae","Invasion in duodenal wall","Irregular increase in density of omental fat","All the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9147, 'Surgery', 'Gastrointestinal Surgery', 'Hard', 'Surgery', 261, '{"id":9147,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Hard","source":"Surgery","sourceNo":261,"q":"A 10 years old male presents a smooth swelling near superficial inguinal ring, which moves downwards when the testicle is pulled downwards. Diagnosis -","o":["Inguinal hernia","Congenital hydrocele","Encysted hydrocele of the cord","Varicocele"],"a":2,"e":"Answer- C. Encysted hydrocele of the cord A hydrocoele develops in a remnant of the processus vaginalis somewhere along the course of the spermatic cord. This hydrocoele also transilluminates, and is known as an encysted hydrocoele of the cord. The swelling moves downwards and becomes less mobile if the testis is pulled gently downwards. In females, a multicystic hydrocoele of the canal of Nuck sometimes presents as a swelling in the groin.","pyqMatches":[{"year":"2016","no":1294,"q":"A 10 years old male presents a smooth swelling near superficial inguinal ring, which moves downwards when the testicle is pulled downwards. Diagnosis","o":["Inguinal hernia","Congenital hydrocele","Encysted hydrocele of the cord","Varicocele"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9148, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 262, '{"id":9148,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":262,"q":"Drug of choice for palliative treatment of pancreatic carcinoma","o":["Erlotinib","Gemcitabine","Paclitaxel","Cyclophosphomide"],"a":1,"e":"Answer- B. Gemcitabine A) Inoperable locally advanced disease- Gemcitabine is used a the treatment of choice for these patients. B) Metastatic Disease Gemcitabine is the standard treatment with a median survival of 6 months and a 1-year survival rate of only 20%. Capecitabine, an oral fluoropyrimidine, has been combined with gemcitabine (GEM-CAP) in a phase III trial that showed an improvement in response rate and progression-free survival over single-agent gemcitabine, but no survival benefit.","pyqMatches":[{"year":"2016","no":1252,"q":"Drug of choice for palliative treatment of pancreatic carcinoma","o":["Erlotinib","Gemcitabine","Paclitaxel","Cyclophosphomide"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9149, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 263, '{"id":9149,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":263,"q":"Modified-Kaush Whipple operation is devised to preserve which part of stomach?","o":["Fundus","Body","Lesser curvature","Pyloric antrum"],"a":3,"e":"Answer- D. Pyloric antrum This procedure is also called pylorus preserving pancreaticoduodenectomy (PPPD or pp-Kaush Whipple procedure). It is the procedure of choice for most adenocarcinomas of the head of pancreas. The original pancreato- duodenectomy as proposed by Whipple included resection of the gastric antrum. The Whipple procedure is now reserved for situations in which the entire duodenum has to be removed (e.g. in FAP) or where the tumour encroaches on the first part of the duodenum or the distal stomach and a PPPD would not achieve a clear resection margin.","pyqMatches":[{"year":"2016","no":1253,"q":"Modified-Kaush Whipple operation is devised to preserve which part of stomach?","o":["Fundus","Body","Lesser curvature","Pyloric antrum"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9150, 'Surgery', 'Hepatobiliary & Pancreas', 'Moderate', 'Surgery', 264, '{"id":9150,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Moderate","source":"Surgery","sourceNo":264,"q":"Which of the following causes of acute pancreatitis can cause recurrent bouts without any obvious pathology","o":["Sphincter Oddi dysfunction","Pancreas divisum","Hypertriglyceridemia","All the above"],"a":3,"e":"Answer- D. All the above Etiology- Gall stones (most common) Alcohol abuse is the second cause of acute pancreatitis. Occult disease of the biliary tree or pancreatic ducts, especially microlithiasis, sludge. Hypertriglyceridemia Pancreas divisum Pancreatic cancer Sphincter of Oddi dysfunction Cystic fibrosis Drugs- Steroids, Azathioprine, Valproate, Estrogens, L- Asparaginase, 6-mercaptopurine, Sulfonamides, Tetracycline, Anti- retroviral agents, Thiazide diuretics Familial or genetic Hyperparathyroidism Hypercalemia Post ERCP Most common causes in children: blunt abdominal injuries, multisystem disease (hemolytic uremic syndrome and inflammatory bowel disease) biliary stones or microlithiasis (sludging), and drug toxicity","pyqMatches":[{"year":"2016","no":1254,"q":"Which of the following causes of acute pancreatitis can cause recurrent bouts without any obvious pathology","o":["Sphincter Oddi dysfunction","Pancreas divisum","Hypertriglyceridemia","All the above"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9151, 'Surgery', 'Hepatobiliary & Pancreas', 'Moderate', 'Surgery', 265, '{"id":9151,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Moderate","source":"Surgery","sourceNo":265,"q":"Pseudocyst pancreas is developed in how much duration following an attack of acute pancreatitis?","o":["Less than 1 week","Less than 2 weeks","3 or more weeks","4 or more weeks"],"a":3,"e":"Answer- D. 4 or more weeks Pseudocysts typically arise following an attack of mild acute pancreatitis, lie outside the pancreas, and represent an APFC that has not resolved and matured. Formation of a pseudocyst requires 4 weeks or more from the onset of acute pancreatitis.","pyqMatches":[{"year":"2016","no":1255,"q":"Pseudocyst pancreas is developed in how much duration following an attack of acute pancreatitis?","o":["Less than 1 week","Less than 2 weeks","3 or more weeks","4 or more weeks"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9152, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 266, '{"id":9152,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":266,"q":"True of umbilical hernia -","o":["Most common content is large intestine","Most of the umbilical hernias disappear spontaneously","Males are affected more than females","Uncomplicated herenias are repaired at 1 year of age through an infraumbilical incision."],"a":1,"e":"Answer- B. Most of the umbilical hernias disappear spontaneously Umbilical hernia develops due to either absence of umbilical fascia or incomplete closure of umbilical defect in infants. Umbilical hernia (paraumbilical hernia) is a protusion or herniation through linea alba just above or below umbilicus. Weakest part is umbilical cicatrix. Contents are- greater omentum, small intestine and transverse colon. CLINICAL FEATURES- Females in 5th decade Swelling has smooth surface, distinct edges resonant with dragging pain. Expansile impulse on patient coughing Surgical treatment is indicated if Hernia persists at 2 years of age or older. If the defect is mor than 2 cm in size. If it is associate with complications. Heriorrhaphy (surgery for repair of hernia) is done through an infraumbilical incision. Defect is closed with interrupted sutures after ligating the sac.","pyqMatches":[{"year":"2016","no":1293,"q":"True of umbilical hernia","o":["Most common content is large intestine","Most of the umbilical hernias disappear spontaneously","Males are affected more than females","Uncomplicated herenias are repaired at 1 year of age through an infraumbilical incision."],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9153, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 267, '{"id":9153,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":267,"q":"Treatment of congenital hydrocephalus is -","o":["Ventriculoperitoneal shunt","Sterestactic radio surgery","Diuretics","Radiotherapy"],"a":0,"e":"Answer- A. Ventriculoperitoneal shunt Congenital Hydrocephalus - Treatment Options","pyqMatches":[{"year":"2016","no":1292,"q":"Treatment of congenital hydrocephalus is","o":["Ventriculoperitoneal shunt","Sterestactic radio surgery","Diuretics","Radiotherapy"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9154, 'Surgery', 'Gastrointestinal Surgery', 'Hard', 'Surgery', 268, '{"id":9154,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Hard","source":"Surgery","sourceNo":268,"q":"Scrotal swelling non reducible but disappears when the child wakes up from sleep is most likely to be -","o":["Congenital hydrocele","Varicocele","Indirect inguinal hernia","None of the above"],"a":0,"e":"Answer- A. Congenital hydrocele In congenital hydrocele the communication with peritoneal cavity is usually too small to allow herniation of intra-abdominal contents. Usually hydrocele is a non reducible swelling but congenital hydrocele can passively get drained through intact tunics vaginalis due to gravity while sleeping. Both varicocele and indirect inguinal hernia are reducible scotal swelling. So the most probable answer is Congenital hydrocele","pyqMatches":[{"year":"2016","no":1291,"q":"Scrotal swelling non reducible but disappears when the child wakes up from sleep is most likely to be","o":["Congenital hydrocele","Varicocele","Indirect inguinal hernia","None of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9155, 'Surgery', 'General Principles & Wounds', 'Moderate', 'Surgery', 269, '{"id":9155,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Moderate","source":"Surgery","sourceNo":269,"q":"How much percentage of the blunt trauma injuries to spleen in adults are currently managed non operatively?","o":["30%","50%","80%","90%"],"a":2,"e":"Answer- C. 80% Spleen is the intra-abdominal organ most commonly injured in a blunt trauma to the abdomen. Up to 80% of blunt splenic injuries can be managed non- operatively. It can be managed in 2 ways : i) Non-operatively This is now the order of the day and currently > 70% of adults with blunt splenic injuries are managed non-operatively. But the primary requirement for it is - hemodynamic stability. ii) Operative management Patients who are hemodynamically unstable or are failing non- operative management (eg. require continuing transfusion) should undergo operative treatment.","pyqMatches":[{"year":"2016","no":1257,"q":"How much percentage of the blunt trauma injuries to spleen in adults are currently managed non operatively?","o":["30%","50%","80%","90%"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9156, 'Surgery', 'Gastrointestinal Surgery', 'Hard', 'Surgery', 270, '{"id":9156,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Hard","source":"Surgery","sourceNo":270,"q":"40 years male presents with translucent scrotal swelling in which it is possible to get above the swelling on examination. What is the most probable diagnosis?","o":["Hydrocele","Indirect inguinal hernia","Varicocele","Sebaceous cyst"],"a":0,"e":"Answer- A. Hydrocele Hydroceles are typically translucent and it is possible to ''get above the swelling'' on examination of the scrotum. A hydrocele is an abnormal collection of serious fluid in a part of the processus vaginalis, usually the tunica. Encysted hydrocele of the cord is a smooth oval swelling near the spermatic cord, which is liable to be mistaken for an inguinal hernia. The swelling moves downwards and becomes less mobile if the testis is pulled gently downwards","pyqMatches":[{"year":"2016","no":1290,"q":"40 years male presents with translucent scrotal swelling in which it is possible to get above the swelling on examination. What is the most probable diagnosis?","o":["Hydrocele","Indirect inguinal hernia","Varicocele","Sebaceous cyst"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9157, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 271, '{"id":9157,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":271,"q":"Most prevalent symptom in patients of leiomyoma of esophagus is","o":["Pain","Pyrosis","Dysphagia","Weight loss"],"a":2,"e":"Answer- C. Dysphagia CLINICAL FEATURES- Asymptomatic (<5cm) Dysphagia, pain More common in males Location- 2/3rd of oesophagus","pyqMatches":[{"year":"2016","no":1258,"q":"Most prevalent symptom in patients of leiomyoma of esophagus is","o":["Pain","Pyrosis","Dysphagia","Weight loss"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9158, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'Surgery', 272, '{"id":9158,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":272,"q":"Which of the following famous personalities had hydrocele associated with hernia, which proved to be fatal?","o":["Edward Gibbon","Thomas Edison","Miley Wright","Neil Armstrong"],"a":0,"e":"Answer- A. Edward Gibbon Edward gibbon (1737-1794), english historian had large hydrocele. The hydrocele was associated with a large scrotal hernia which probably was punctured.","pyqMatches":[{"year":"2016","no":1288,"q":"Which of the following famous personalities had hydrocele associated with hernia, which proved to be fatal?","o":["Edward Gibbon","Thomas Edison","Miley Wright","Neil Armstrong"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9159, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 273, '{"id":9159,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":273,"q":"Following is not true about traction diverticulum of esophagus -","o":["Produced due to the extraluminal forces","It is not a true diverticulum","The outpouching is usually small and conical","May develop tracheoesophageal fistula"],"a":1,"e":"Answer- B. It is not a true diverticulum In traction diverticula extraluminal forces (like inflammed & scarred peribronchial & mediastinal lymph nodes) pull the full thickness of the esophagus out, creating a true diverticula. Traction diverticula are much less common. They are mostly a consequence of chronic granulomatous disease affecting the tracheobronchial lymph nodes due to tuberculosis, atypical mycobacteria or histoplasmosis. Fibrotic healing of the lymph nodes exerts traction on the oesophageal wall and produces a focal outpouching that is usually small and has a conical shape","pyqMatches":[{"year":"2016","no":1259,"q":"Following is not true about traction diverticulum of esophagus","o":["Produced due to the extraluminal forces","It is not a true diverticulum","The outpouching is usually small and conical","May develop tracheoesophageal fistula"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9160, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 274, '{"id":9160,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":274,"q":"Which of the following is false about zenkers diverticulum","o":["Most patients are above 50 years of age","It is the most common esophageal diverticulum","Mucosal outpouching through the killians triangle","Cervical webs can be associated with zenkers diverticulum in 80% of the patients"],"a":3,"e":"Answer- D. Cervical webs can be associated with zenkers diverticulum in 80% of the patients Zenker diverticulum originates from the posterior wall of the esophagus in a triangular area of weakness, limited inferiorly by the cricopharyngeus muscle and superiorly by the inferior constrictor muscles (ie, the Killian triangle). Zenker''s diverticulum, also pharyngoesophageal diverticulum, also pharyngeal pouch, also hypopharyngeal diverticulum, is a diverticulum of the mucosa of the pharynx, just above the cricopharyngeal muscle (i.e. above the upper sphincter of the esophagus). It is a pseudo diverticulum (not involving all layers of the esophageal wall). Seen in 50years old.","pyqMatches":[{"year":"2016","no":1260,"q":"Which of the following is false about zenkers diverticulum","o":["Most patients are above 50 years of age","It is the most common esophageal diverticulum","Mucosal outpouching through the killians triangle","Cervical webs can be associated with zenkers diverticulum in 80% of the patients"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9161, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 275, '{"id":9161,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":275,"q":"True about esophageal carcinoma is","o":["More lethal than the colorectal cancers","These show an increasing trend towards the number of squamous cell carcinomas","Smaller size esophageal lesions have better survival","Asymptomatic benign lesions should be excised immediately"],"a":0,"e":"Answer- A. More lethal than the colorectal cancers Etiology: alcohol and smoking: for squamous cell carcinoma and adenocarcinoma achalasia asbestosis Barrett oesophagus: for adenocarcinoma coeliac disease ionising radiation caustic stricture/lye stricture Plummer-Vinson syndrome Even when detected as a small lesion, esophageal cancer has poor survival because of the abundant esophageal lymphatics leading to regional lymph node metastases.","pyqMatches":[{"year":"2016","no":1262,"q":"True about esophageal carcinoma is","o":["More lethal than the colorectal cancers","These show an increasing trend towards the number of squamous cell carcinomas","Smaller size esophageal lesions have better survival","Asymptomatic benign lesions should be excised immediately"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9162, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 276, '{"id":9162,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":276,"q":"Patient complains of intermittent dysphagia which is equal both for solids and liquids, which of the following is the most probable diagnosis?","o":["Achalasia cardia","Esophageal stricture","Carcinoma esophagus","Diffuse esophageal spasm"],"a":3,"e":"Answer- D. Diffuse esophageal spasm Clinical features- Hypertrophy of circular muscles Dysphagia Chest pain","pyqMatches":[{"year":"2016","no":1263,"q":"Patient complains of intermittent dysphagia which is equal both for solids and liquids, which of the following is the most probable diagnosis?","o":["Achalasia cardia","Esophageal stricture","Carcinoma esophagus","Diffuse esophageal spasm"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9163, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 277, '{"id":9163,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":277,"q":"Early and late suspected instrumental perforation of oesophagus should first be assessed using","o":["Water soluble contrast swallow","CT Scan","Dilute barium swallon","MRI"],"a":0,"e":"Answer- A. Water soluble contrast swallow If this is negative, a dilute barium swallow should be considered. A CT scan can be used to replace a contrast swallow or as an adjunct to accurately delineate specific fluid collections.","pyqMatches":[{"year":"2016","no":1264,"q":"Early and late suspected instrumental perforation of oesophagus should first be assessed using","o":["Water soluble contrast swallow","CT Scan","Dilute barium swallon","MRI"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9164, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 278, '{"id":9164,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":278,"q":"Downhill esophagus varices develop as a result of obstruction of seen in","o":["Portal vein","Hepatic vein","Superior vena cava","Inferior vena cava"],"a":2,"e":"Answer- C. Superior vena cava Downhill varicesare produced by the obstruction of the superior vena cava, which results in collateral drainage from the head, neck and upper extremity venous systems into the veins surrounding the mid and upper thoracic esophagus and into the azygous vein. On CT varices appear as enhancing tubular regions in the periesophageal region. This density is equal to the venous blood pool.","pyqMatches":[{"year":"2016","no":1265,"q":"Downhill esophagus varices develop as a result of obstruction of seen in","o":["Portal vein","Hepatic vein","Superior vena cava","Inferior vena cava"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9165, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 279, '{"id":9165,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":279,"q":"Most common impacted foreign body in esophagus in children is","o":["Coin","Food product","Krayon","Marble"],"a":0,"e":"Answer- A. Coin Coins are the most commonly impacted foreign bodies in children in esophagus and oropharynx followed by the food products","pyqMatches":[{"year":"2016","no":1266,"q":"Most common impacted foreign body in esophagus in children is","o":["Coin","Food product","Krayon","Marble"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9166, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 280, '{"id":9166,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":280,"q":"Pantaloon hernia is also called as -","o":["Dual hernia","Saddle bag hernia","Bochdaleks hernia","Retrosternal hernia"],"a":1,"e":"Answer- B. Saddle bag hernia It is also called dual or saddle bag hernia. This type of hernia consists of two sacs that straddle the inferior epigastric artery, one sac being medial and the other lateral to this vessel.","pyqMatches":[{"year":"2016","no":1287,"q":"Pantaloon hernia is also called as","o":["Dual hernia","Saddle bag hernia","Bochdaleks hernia","Retrosternal hernia"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9167, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 281, '{"id":9167,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":281,"q":"Rolled up omentum is seen in cases of -","o":["Peritoneal tuberculosis","Peritoneal metastases","Perforation peritonitis","Malrotation of gut"],"a":0,"e":"Answer- A. Peritoneal tuberculosis The classic appearance of greyish white military nodules scattered over the peritoneum. In addition fibrous bands and adhesions are common. The omentum may become thickened presenting as a transversely placed mass (rolled up omentum). Clinically the most frequent presentation of the peritoneal disease is ascites.","pyqMatches":[{"year":"2016","no":1286,"q":"Rolled up omentum is seen in cases of","o":["Peritoneal tuberculosis","Peritoneal metastases","Perforation peritonitis","Malrotation of gut"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9168, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 282, '{"id":9168,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":282,"q":"Staging of rectal carcinoma is best done by -","o":["CT Scan","MRI","TRUS","All the above"],"a":1,"e":"Answer-B 90% of rectal growths can be felt by per-rectal examination High-resolution phased array external MRI is the investigation of choice for local issues in the primary staging of rectal cancer (best investigation for staging) as well as for restaging after NACT-RT. It provides the highest accuracy for issues in pretreatment local staging Investigation of choice – rigid sigmoidoscopy and biopsy To assess local spread – TRUS (Endoluminal ultrasound) For local staging and assessment of proposed circumferential resection margin – MRI (CT is not accurate in local staging)","pyqMatches":[{"year":"2016","no":1285,"q":"Staging of rectal carcinoma is best done by","o":["CT Scan","MRI","TRUS","All the above"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9169, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 283, '{"id":9169,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":283,"q":"Treatment of choice for low fistula in ano is -","o":["Fistulotomy","Intravenous antibiotics","Staged surgical resection","None of the above"],"a":0,"e":"Answer- A. Fistulotomy It is divided into 2 types - high & low, according to whether their internal openings is below or above the anorectal ring. The importance of deciding whether a fistula is a low or a high type is that a low level can be treated by fistulotomy (opening the tract) without causing damage to the sphincter.","pyqMatches":[{"year":"2016","no":1284,"q":"Treatment of choice for low fistula in ano is","o":["Fistulotomy","Intravenous antibiotics","Staged surgical resection","None of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9170, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 284, '{"id":9170,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":284,"q":"Exception to Goodsals rule is considered when the anterior external opening is more situated more than cms from anal margin -","o":["2","3","4","5"],"a":1,"e":"Answer- B. 3 Goodsall''s Rule Is used to determine the location of internal opening According to it : Fistulas with external opening anterior to horizontal imaginary line drawn across the mid point of anus connect to the internal opening by short straight tract. Fistulas with external opening posterior to the horizontal line - run a curvilinear course and open internally into the posterior midline.","pyqMatches":[{"year":"2016","no":1283,"q":"Exception to Goodsals rule is considered when the anterior external opening is more situated more than cms from anal margin","o":["2","3","4","5"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9171, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 285, '{"id":9171,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":285,"q":"Which of the following is not true about medical management of uncomplicated GERD?","o":["PPIs are the most effective drug treatment for GORD","Household measure of tilting the bed is efficatious","Long term PPI therapy increases risk of malignant changes","Adequate dose of PPI for 8 weeks is the recommended treatment"],"a":2,"e":"Answer- C. Long term PPI therapy increases risk of malignant changes Treatment-","pyqMatches":[{"year":"2016","no":1267,"q":"Which of the following is not true about medical management of uncomplicated GERD?","o":["PPIs are the most effective drug treatment for GORD","Household measure of tilting the bed is efficatious","Long term PPI therapy increases risk of malignant changes","Adequate dose of PPI for 8 weeks is the recommended treatment"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9172, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 286, '{"id":9172,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":286,"q":"Single drug regimen for carcinoma esophagus which shows significant decrease in tumor size in 15 - 20% of patients incorporates which drug?","o":["Cisplatin","Bleomycin","Doxorubicin","Vincristine"],"a":0,"e":"Answer- A. Cisplatin Significant reductions in the size of measurable tumor masses have been reported in 15-25% of patients given single-agent cisplatin treatment and in 30-60% of patients treated with drug combinations that include cisplatin.","pyqMatches":[{"year":"2016","no":1268,"q":"Single drug regimen for carcinoma esophagus which shows significant decrease in tumor size in 15 - 20% of patients incorporates which drug?","o":["Cisplatin","Bleomycin","Doxorubicin","Vincristine"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9173, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'Surgery', 287, '{"id":9173,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":287,"q":"Critical diameter of caecum when perforation is considered eminent in pseudo-obstruction is -","o":[">7 cm",">8 cm",">9 cm",">10 cm"],"a":2,"e":"Answer- C. >9 cm It is defined as large bowel distention resulting from chronic impairment of motility. The degree of colonic distention may be severe enough to cause caecal perforation. Imminenet perforation of caecum is considered when the caecal diameter exceeds the critical diameter of 9cm (>9cm).","pyqMatches":[{"year":"2016","no":1282,"q":"Critical diameter of caecum when perforation is considered eminent in pseudo-obstruction is","o":[">7 cm",">8 cm",">9 cm",">10 cm"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9174, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 288, '{"id":9174,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":288,"q":"Most common type of Hiatal hernia is","o":["Sliding","Rolling","Mixed","None of the above"],"a":0,"e":"Answer- A. Sliding There are 4 types of hiatal hernia Type I : Sliding hernia (most common type - 70 - 80%) Type II : Paraesophageal or rolling hernia Type III : Mixed Type IV : Tese hernias are distinguished by the presence of other abdominal viscera wihin the defect i.e. omentum, transverse colon.","pyqMatches":[{"year":"2016","no":1269,"q":"Most common type of Hiatal hernia is","o":["Sliding","Rolling","Mixed","None of the above"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9175, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 289, '{"id":9175,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":289,"q":"In corrosive injury of esophagus correct statement is all except","o":["Alkalis are usually ingested in larger volumes","Alkalis cause more gastic damage than acids","Alkalis form fibrous scar","Acids form eschar"],"a":1,"e":"Answer- B. Alkalis cause more gastic damage than acids In general, alkalis are relatively odourless and tasteless, making them more likely to be ingested in large volume. Alkalis cause liquefaction, saponification of fats, dehydration and thrombosis of blood vessels that usually leads to fibrous scarring. Acids cause coagulative necrosis with eschar formation, and this coagulant may limit penetration to deeper layers of the oesophageal wall. Acids also cause more gastric damage than alkalis because of the induction of intense pylorospasm with pooling in the antrum.","pyqMatches":[{"year":"2016","no":1270,"q":"In corrosive injury of esophagus correct statement is all except","o":["Alkalis are usually ingested in larger volumes","Alkalis cause more gastic damage than acids","Alkalis form fibrous scar","Acids form eschar"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9176, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'Surgery', 290, '{"id":9176,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":290,"q":"Colonoscopy is are not indicated in -","o":["MEN 2B","FAP","HNPCC","Cornkite canada syndrome"],"a":0,"e":"Answer- A. MEN 2B MEN 2B does not predispose to colon cancer. FAP, HNPCC, Cronkite Canada Syndrome predispose to Colon Cancer and hence screening with colonoscopy is needed","pyqMatches":[{"year":"2016","no":1281,"q":"Colonoscopy is are not indicated in","o":["MEN 2B","FAP","HNPCC","Cornkite canada syndrome"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9177, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 291, '{"id":9177,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":291,"q":"An individual of age 40 yrs presents with dysphagia to both solids and liquids with symptoms of regurgitation. Patient also complaints of chest pain and weight loss. Which of the following is the preferred investigation for diagnosis of this pathology?","o":["Barium swallow X-ray","Barium swallow X-ray with esophageal manometry","Barium swallow X-ray woith esophageal manometry with endoscopy","None of the above"],"a":1,"e":"Answer- B. Barium swallow X-ray with esophageal manometry Barium swallow- shows cucumber oesophagus or birds beak or pencil tip deformity. Oesophageal manometry- Characteristics of achalasia cardia Hypertensive LOS Aperistalsis in the body of oesophagus Barium swallow shows a dilated esophagus with tapering narrowing in the terminal end of esophagus, described as ‘BIRD BEAK’ appearance.","pyqMatches":[{"year":"2016","no":1271,"q":"An individual of age 40 yrs presents with dysphagia to both solids and liquids with symptoms of regurgitation. Patient also complaints of chest pain and weight loss. Which of the following is the preferred investigation for diagnosis of this pathology?","o":["Barium swallow X-ray","Barium swallow X-ray with esophageal manometry","Barium swallow X-ray woith esophageal manometry with endoscopy","None of the above"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9178, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'Surgery', 292, '{"id":9178,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":292,"q":"Contraindication for colostomy planning are all except -","o":["Age > 60 yrs","Stoma near skin creases and bony prominences","Poorly motivated patient for elective stomy","Stomas through previous scars"],"a":0,"e":"Answer- A. Age > 60 yrs The patient must be explained the procedure and properly motivated for taking care of the stoma The stoma should preferably be through rectus abdominis ( to prevent prolapse and parastomal hernias) It should be through flat surface of abdomen It should avoid skin creases and bony prominences It should be away from previous scars","pyqMatches":[{"year":"2016","no":1280,"q":"Contraindication for colostomy planning are all except","o":["Age > 60 yrs","Stoma near skin creases and bony prominences","Poorly motivated patient for elective stomy","Stomas through previous scars"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9179, 'Surgery', 'Gastrointestinal Surgery', 'Hard', 'Surgery', 293, '{"id":9179,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Hard","source":"Surgery","sourceNo":293,"q":"Which of the following tumors most commonly presents with upper gastrointestinal bleeding?","o":["Primary gastric cancer","Esophageal carcinoma","Metastases to stomach","Hepatic adenocarcinoma"],"a":0,"e":"Answer- A. Primary gastric cancer Tumor bleeding accounts for up to 5% of upper gastrointestinal bleeding (UGIB) cases.","pyqMatches":[{"year":"2016","no":1273,"q":"Which of the following tumors most commonly presents with upper gastrointestinal bleeding?","o":["Primary gastric cancer","Esophageal carcinoma","Metastases to stomach","Hepatic adenocarcinoma"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9180, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 294, '{"id":9180,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":294,"q":"True about small intestinal tumor is -","o":["Lymphomas are the most common small intestinal tumors","Carcinoids are more common in the duodenum and jejunum","Adenomatous polyps are more common in the terminal ileum","Risk of developing small bowel tumor correlates positively with colorectal cancer"],"a":3,"e":"Answer- D. Risk of developing small bowel tumor correlates positively with colorectal cancer The second most common small bowel tumor is carcinoid accounting for35% of all small bowel carcinomas, 90% of which are located in the ileum. Lymphomas account for the third most common tumors of the small bowel. Adenomatous polyps tend to occur in the periampullary region and proximal jejunum, close to the entrance of bile and pancreatic secretions into small intestine.","pyqMatches":[{"year":"2016","no":1279,"q":"True about small intestinal tumor is","o":["Lymphomas are the most common small intestinal tumors","Carcinoids are more common in the duodenum and jejunum","Adenomatous polyps are more common in the terminal ileum","Risk of developing small bowel tumor correlates positively with colorectal cancer"],"a":3,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9181, 'Surgery', 'Hepatobiliary & Pancreas', 'Hard', 'Surgery', 295, '{"id":9181,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Hard","source":"Surgery","sourceNo":295,"q":"Simplest investigation to be performed in suspected cases of gastric cancer is -","o":["Double contrast radiography","Plain radiography","CT Scan","Endoscopy"],"a":2,"e":"Answer- C Ct scan Investigation for diagnosis of gastric cancer: * Ultrasound and CT scan - To rule out secondaries in the liver. - To look for enlarged coeliac nodes. - Can detect ascites-guided fluid tap and cell cytology. - To detect Krukenberg tumour (pelvic CT). - Useful in detecting metastatic disease.","pyqMatches":[{"year":"2016","no":1277,"q":"Simplest investigation to be performed in suspected cases of gastric cancer is","o":["Double contrast radiography","Plain radiography","CT Scan","Endoscopy"],"a":2,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9182, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 296, '{"id":9182,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":296,"q":"Which of the following is true about gastric ulcer but not the duodenal ulcer?","o":["Pain rarely occurs at night","Melena is more common than hematemesis","Usually occurs in 40 - 50 yrs of age","Pain is relieved with ingestion of food"],"a":0,"e":"Answer- A. Pain rarely occurs at night","pyqMatches":[{"year":"2016","no":1274,"q":"Which of the following is true about gastric ulcer but not the duodenal ulcer?","o":["Pain rarely occurs at night","Melena is more common than hematemesis","Usually occurs in 40 - 50 yrs of age","Pain is relieved with ingestion of food"],"a":0,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9183, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'Surgery', 297, '{"id":9183,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":297,"q":"Not true about highly selective vagotomy -","o":["It is also known parietal cell vagotomy","Nerves of Latarjet are sacrifised","Recurrence rates are higher than vagotomy and drainage and vagotomy and antrestomy.","Entire gastric reservoir capacity is preserved"],"a":1,"e":"Answer- B. Nerves of Latarjet are sacrifised In Highly selective vagotomy (also known as parietal cell vagotomy or proximal gastric vagotomy) the vagal innervation to the antrum and pylorus (nerves of Latarjet) are preserved, only the vagal supply to the proximal two-thirds of stomach (where essentially all the parietal cells are located) is cut. This preserves gastric motility.","pyqMatches":[{"year":"2016","no":1276,"q":"Not true about highly selective vagotomy","o":["It is also known parietal cell vagotomy","Nerves of Latarjet are sacrifised","Recurrence rates are higher than vagotomy and drainage and vagotomy and antrestomy.","Entire gastric reservoir capacity is preserved"],"a":1,"source":"NEET_2016_Paper.pdf"}],"pyqYears":["2016"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9184, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 298, '{"id":9184,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":298,"q":"Bowel punctured during laproscopy","o":["Trocar kept","trocar removal","trocar repositioned","None"],"a":0,"e":"Answer- A. Trocar kept To assist in identifying the precise site of injuty.","pyqMatches":[{"year":"2014","no":1492,"q":"Bowel punctured during laproscopy","o":["Trocar kept","trocar removal","trocar repositioned","None"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9185, 'Surgery', 'General Principles & Wounds', 'Hard', 'Surgery', 299, '{"id":9185,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Hard","source":"Surgery","sourceNo":299,"q":"What is not done in case of puncture wound of left colon","o":["Primary suture","Hemicolectomy","Externalization","Resection and anastomosis"],"a":1,"e":"Answer- B. Hemicolectomy Small wound are repaired primarily by simple suturing. More extensive wound are treated by resection and anastomosis. Some may require colostomy (externalization) [Ref Bailey er Love 25th/e p. 1184]","pyqMatches":[{"year":"2014","no":1493,"q":"What is not done in case of puncture wound of left colon","o":["Primary suture","Hemicolectomy","Externalization","Resection and anastomosis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9186, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 300, '{"id":9186,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":300,"q":"What is the percentage body surface area involved in head + face in burns","o":["13","15","17","09"],"a":3,"e":"Answer- D. 09 According to rule of 9 (Wallace''s formula), burn surface area is calculated as :","pyqMatches":[{"year":"2014","no":1494,"q":"What is the percentage body surface area involved in head + face in burns","o":["13","15","17","09"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9187, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 301, '{"id":9187,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":301,"q":"Plunging Ranula is","o":["Cystic growth of sublingual gland","Lymph node","A tumor in floor of mouth","None"],"a":0,"e":"Answer- A. Cystic growth of the sublingual gland Plunging ranula is a rare form of mucous retention cyst that arises from the sublingual salivary glands. Mucus collects below the gland and perforates through the mylohyoid muscle diaphragm to enter the neck.","pyqMatches":[{"year":"2014","no":1496,"q":"Plunging Ranula is","o":["Cystic growth of sublingual gland","Lymph node","A tumor in floor of mouth","None"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9188, 'Surgery', 'Urology', 'Easy', 'Surgery', 302, '{"id":9188,"subject":"Surgery","chapter":"Urology","difficulty":"Easy","source":"Surgery","sourceNo":302,"q":"Sialolithiasis is most commonly seen in which gland","o":["Parotid","Sublingual","Submandibular","Minor salivary gland"],"a":2,"e":"Answer- C. Submandibular Most common site for salivary gland stone (Sialolithiasis) is submandibular gland, especially duct of submandibular gland (Wharton''s duct).","pyqMatches":[{"year":"2014","no":1497,"q":"Sialolithiasis is most commonly seen in which gland","o":["Parotid","Sublingual","Submandibular","Minor salivary gland"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9189, 'Surgery', 'Breast Surgery', 'Moderate', 'Surgery', 303, '{"id":9189,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":303,"q":"Which structure is not preserved in modified radical mastectomy","o":["Cephalic vein","Pectoralis minor","Pectoralis major","Branches of lntercostobrachial N."],"a":0,"e":"Answer- A In the modified radical mastectomy, the procedure involves removal of the breast but preservation of the pectoralis major muscle. The extent of preservation of the pectoralis minor and axillary nodes varies. Preserve thoracodorsal nerve/vessels.","pyqMatches":[{"year":"2014","no":1498,"q":"Which structure is not preserved in modified radical mastectomy","o":["Cephalic vein","Pectoralis minor","Pectoralis major","Branches of lntercostobrachial N."],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9190, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 304, '{"id":9190,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":304,"q":"Duputyrens and peyonies are both type of","o":["Fibromatosis","Fibroblastic hyperplesia","Burn contracture","Myalgias"],"a":1,"e":"Answer- B. Fibroblastic hyperplesia Dupuytren contracture and Peyranie''s diseases are fibroblastic hyperplasia. Dupuytren''s contracture is characterized in the established phase by flexion contracture of one or more fingers from thickening and shortening of palmar oponeurosis.","pyqMatches":[{"year":"2014","no":1499,"q":"Duputyrens and peyonies are both type of","o":["Fibromatosis","Fibroblastic hyperplesia","Burn contracture","Myalgias"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9191, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 305, '{"id":9191,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":305,"q":"Mid gut Volvulus symptoms appear at","o":["1\" week","3rd weeks","2\" weeks","4th weeks"],"a":0,"e":"Answer- A. 1\" week Midgut volvulus can happen at any age, but most commonly occurs during the first few weeks of life. Bilious emesis is usually the first sign of volvulus.","pyqMatches":[{"year":"2014","no":1500,"q":"Mid gut Volvulus symptoms appear at","o":["1\" week","3rd weeks","2\" weeks","4th weeks"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9192, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 306, '{"id":9192,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":306,"q":"Most common nerve damaged during hernia repair","o":["ilioinguinal nerve","Iliohypogastric","Genitofumoral","None"],"a":0,"e":"Answer- A. ilioinguinal nerve There nerves are exposed to injury during inguinal hernia repair.","pyqMatches":[{"year":"2014","no":1503,"q":"Most common nerve damaged during hernia repair","o":["ilioinguinal nerve","Iliohypogastric","Genitofumoral","None"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9193, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 307, '{"id":9193,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":307,"q":"Progressive dysphagia is seen in all except","o":["CA esophagus","Diffuse esophageal spasm","Stricture","Achalasia cardia"],"a":1,"e":"Answer- B. Diffuse esophageal spasm Propgressive dysphagis is seen in CA esophagus Stricture Achalasia cardia Dysphagia equal for both solids and liquids from onset:","pyqMatches":[{"year":"2014","no":1504,"q":"Progressive dysphagia is seen in all except","o":["CA esophagus","Diffuse esophageal spasm","Stricture","Achalasia cardia"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9194, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 308, '{"id":9194,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":308,"q":"Kher sign is seen in","o":["Splenic trauma","Hepatic trauma","Renal trauma","Pacreatic trauma"],"a":0,"e":"Answer- A. Splenic trauma In splenic rupture the pain may be referred to the tip of the left shoulder. This is known as Kehr''s sign. It occurs due to irritation of the undersurface of the diaphragm with blood and the pain is referred to the shoulder through the affected fibres of phrenic nerve (C4 and C5).","pyqMatches":[{"year":"2014","no":1506,"q":"Kher sign is seen in","o":["Splenic trauma","Hepatic trauma","Renal trauma","Pacreatic trauma"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9195, 'Surgery', 'Vascular Surgery', 'Easy', 'Surgery', 309, '{"id":9195,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Easy","source":"Surgery","sourceNo":309,"q":"ABPI of imminent necrosis","o":["< 0.3","0.3","< 0.6","> 0-6"],"a":0,"e":"Answer- A. < 0.3 Lower ABPI is an indication of peripheral vascular disease of lower limb. Critical ischemia (restpain or tissue necrosis) most commonly is associated with an ABI < 0.4.","pyqMatches":[{"year":"2014","no":1507,"q":"ABPI of imminent necrosis","o":["< 0.3","0.3","< 0.6","> 0-6"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9196, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 310, '{"id":9196,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":310,"q":"Ankle brachial pressure index is","o":["1.0","10","01","None"],"a":0,"e":"Answer- A. 1.0 Ankle - brachial pressure index (ABPI) is the ratio of BP in ankle to BP in arm (upper limb). Normal ABPI is around 1 (0.9 - 1.2).","pyqMatches":[{"year":"2014","no":1508,"q":"Ankle brachial pressure index is","o":["1.0","10","01","None"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9197, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 311, '{"id":9197,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":311,"q":"In Ainhum, constriction develops usually at the level of interphalangeal joint of","o":["Great toe","2nd toe","Little toe","None"],"a":2,"e":"Answer- C. Little toe Ainhum is bilateral painful constriction at the base of 5th toe (little toe). This leads to bilateral autoamputation of little toes.","pyqMatches":[{"year":"2014","no":1509,"q":"In Ainhum, constriction develops usually at the level of interphalangeal joint of","o":["Great toe","2nd toe","Little toe","None"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9198, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 312, '{"id":9198,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":312,"q":"True about carcinoma of male breast is","o":["Invasive lobular Ca is most common","Estrogen receptor negative","Seen in young males","BRCA2 mutation is associated with increased risk"],"a":3,"e":"Answer- D. BRCA2 mutation is associated with increased risk The average age of men diagnosed with breast cancer is 68 years (old age). Breast cancers in male have estrogen receptors and high estorgen level is a risk factor for breast carcinoma in males. Men who inherit abnormal BRCA-1 and BRCA-2 genes have an increased risk for male breast cancer. Most breast cancers in men are ductal carcinomas.","pyqMatches":[{"year":"2014","no":1511,"q":"True about carcinoma of male breast is","o":["Invasive lobular Ca is most common","Estrogen receptor negative","Seen in young males","BRCA2 mutation is associated with increased risk"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9199, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 313, '{"id":9199,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":313,"q":"Most common carcinoma breast in male s","o":["Lobular carcinoma in situ","Ductal carcinoma in situ","Infiltrating ductal Ca","None"],"a":2,"e":"Answer- C. Infiltrating ductal Ca Most breast cancers in men are ductal carcinomas.","pyqMatches":[{"year":"2014","no":1512,"q":"Most common carcinoma breast in male s","o":["Lobular carcinoma in situ","Ductal carcinoma in situ","Infiltrating ductal Ca","None"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9200, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 314, '{"id":9200,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":314,"q":"Pressure in laproscopy is","o":["10-12 mmHg","12-14 mmHg","14-16 mmHg","16-18 mmHg"],"a":1,"e":"Answer- B. 12-14 mmHg In laproscopy with standard pressure pneumoperitoneum, the gas pressure is 12-14 mmHg.","pyqMatches":[{"year":"2014","no":1513,"q":"Pressure in laproscopy is","o":["10-12 mmHg","12-14 mmHg","14-16 mmHg","16-18 mmHg"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9201, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 315, '{"id":9201,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":315,"q":"Most common site of direct hernia","o":["Hesselbach''s triangle","Femoral gland","No site predilection","None"],"a":0,"e":"Answer- A. Hesselbach''s triangle It enters the canal through inguinal triangle of Hesselbach. Common in elderly Always acquired Herniation through posterior wall of the inguinal canal Globular/round in shape; descends directly forward bulge. Truss cannot prevent progression of Sliding type of inguinal hernia","pyqMatches":[{"year":"2014","no":1514,"q":"Most common site of direct hernia","o":["Hesselbach''s triangle","Femoral gland","No site predilection","None"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9202, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 316, '{"id":9202,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":316,"q":"Lymph drainage is increased from lower limbs by","o":["Massasaging","Running","Cycling","Sleeping"],"a":0,"e":"Answer- A. Massasaging In the healthy limb, lymph flow is largely due to intrinsic lymphatic contractility, although this is augmented by exercise, limb movement and external compresion (massaging). Lymphatic pump/suction pump :","pyqMatches":[{"year":"2014","no":1515,"q":"Lymph drainage is increased from lower limbs by","o":["Massasaging","Running","Cycling","Sleeping"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9203, 'Surgery', 'Endocrine Surgery', 'Easy', 'Surgery', 317, '{"id":9203,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Easy","source":"Surgery","sourceNo":317,"q":"Nodule on thyroid with lymphadenopathy","o":["Radiation","Chemotherapy","Excision of nodule","Total thyroidectomy + MRND"],"a":3,"e":"Answer- D. Total thyroidectomy + MRND Total Thyroidectomy is the treatment of choice for patients with MTC because of high incidence of multicentricity. In patients with palpable cervical nodes or involved central neck nodes, ipsilateral or bilateral modified radical neck dissection is recommended.","pyqMatches":[{"year":"2014","no":1516,"q":"Nodule on thyroid with lymphadenopathy","o":["Radiation","Chemotherapy","Excision of nodule","Total thyroidectomy + MRND"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9204, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 318, '{"id":9204,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":318,"q":"Treatment of contaminated wound of leg","o":["Debridement and antibiotics","Hyperbaric oxygen","Amputation","None"],"a":0,"e":"Answer- A. Debridement and antibiotics After debridement, wound is reassessed and further management depends on the type of wound.","pyqMatches":[{"year":"2014","no":1517,"q":"Treatment of contaminated wound of leg","o":["Debridement and antibiotics","Hyperbaric oxygen","Amputation","None"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9205, 'Surgery', 'Hepatobiliary & Pancreas', 'Easy', 'Surgery', 319, '{"id":9205,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Easy","source":"Surgery","sourceNo":319,"q":"Most important diagnostic feature of congenital hypertrophic pyloric stenosis","o":["Metabolic alkalosis","Non bilious vomiting","Jaundice","Fever"],"a":1,"e":"Answer- B. Non bilious vomiting metabolik alkalosis also occurs, non-bilious vomiting is the most important feature of CHPS.","pyqMatches":[{"year":"2014","no":1520,"q":"Most important diagnostic feature of congenital hypertrophic pyloric stenosis","o":["Metabolic alkalosis","Non bilious vomiting","Jaundice","Fever"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9206, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 320, '{"id":9206,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":320,"q":"Criteria for viability of muscle are all except","o":["Colour","Intact fascia","Contractability","Bleeding when cut"],"a":1,"e":"Answer- B. Intact fascia Non viable muscle can be identified by 4cs - Color ? Consistency Contraction, and ? Circulation (bleeding on cut)","pyqMatches":[{"year":"2014","no":1521,"q":"Criteria for viability of muscle are all except","o":["Colour","Intact fascia","Contractability","Bleeding when cut"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9207, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 321, '{"id":9207,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":321,"q":"Gall stone impacted causing intestinal obstruction","o":["Raynods pentad","Hepatitis","Gallstone ileus","Obstructive jaundice"],"a":2,"e":"Answer- C. Gallstone ileus Gallstone ileus refers to mechanical intestinal obstruction resulting from the passage of a large gallstone into the bowel lumen. The stone enters the duodenum through a cholecystoenteric fistula. The site of obstruction by the impacted Gall stones is usually the terminal end of the ileum provided that the more proximal small bowel is of normal caliber.","pyqMatches":[{"year":"2014","no":1522,"q":"Gall stone impacted causing intestinal obstruction","o":["Raynods pentad","Hepatitis","Gallstone ileus","Obstructive jaundice"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9208, 'Surgery', 'General Principles & Wounds', 'Hard', 'Surgery', 322, '{"id":9208,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Hard","source":"Surgery","sourceNo":322,"q":"A middle aged male complains of ache and mumbness and sensated of fatigus over his calf muscles that develops on exercise and is relieved on rest; this condition is not associated with","o":["Smoking","Hypocalcemia","Peripheral arterial disease","Hypertension and diabetes"],"a":1,"e":"Answer- B. Hypocalcemia Hyperlipidemia Diabetes Hypertension Cigarette smoking Alcohol, lipoprotein (a) Chlamydia pneumonae Physcial inactivity Herpes virus CMV infection","pyqMatches":[{"year":"2014","no":1523,"q":"A middle aged male complains of ache and mumbness and sensated of fatigus over his calf muscles that develops on exercise and is relieved on rest; this condition is not associated with","o":["Smoking","Hypocalcemia","Peripheral arterial disease","Hypertension and diabetes"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9209, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 323, '{"id":9209,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":323,"q":"Seton used in fistula in ano is","o":["Draining seton","Cutting seton","Dissolving seton","None"],"a":1,"e":"Answer- B. Cutting seton seton (Tight seton) : Made up of silk/prolene/monofilament nylon and used in fistula in ano It promotes slow transection of external sphincter muscle as a result of pressure necrosis with minimum separation of ds. cut a fistula.","pyqMatches":[{"year":"2014","no":1524,"q":"Seton used in fistula in ano is","o":["Draining seton","Cutting seton","Dissolving seton","None"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9210, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 324, '{"id":9210,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":324,"q":"Multiple air fluid levels in X-ray of abdomen is seen in","o":["Hollow viscera perforation","Pyoperitoneum","Intestinal obstruction","None"],"a":2,"e":"Answer- C. Intestinal obstruction The obstruction may be due to adhesion, hernia, neoplasm, foreign body etc. A normal person has on average 4 air fluid levels. Most of them are seen in the colon. For the diagnosis of small intestinal obstruction, we should see more than 2 air fluid levels among the dilated loops of small bowel.","pyqMatches":[{"year":"2014","no":1525,"q":"Multiple air fluid levels in X-ray of abdomen is seen in","o":["Hollow viscera perforation","Pyoperitoneum","Intestinal obstruction","None"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9211, 'Surgery', 'General Principles & Wounds', 'Hard', 'Surgery', 325, '{"id":9211,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Hard","source":"Surgery","sourceNo":325,"q":"Blunt trauma chest, first step in management after initial resuscitation is","o":["CT scan","Angiography","X-ray chest","USG"],"a":2,"e":"Answer- C. X-ray chest First investigation of choice in any type of chest injury is chest X-ray.","pyqMatches":[{"year":"2014","no":1530,"q":"Blunt trauma chest, first step in management after initial resuscitation is","o":["CT scan","Angiography","X-ray chest","USG"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9212, 'Surgery', 'Endocrine Surgery', 'Easy', 'Surgery', 326, '{"id":9212,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Easy","source":"Surgery","sourceNo":326,"q":"Hemorrhage after thyroidectomy is due to","o":["External carotid artery","Internal carotid artey","Superior thyroid artery","Inferior thyroid artery"],"a":2,"e":"Answer C. Superior thyroid artery Is usually due to slipping of ligature on the superior thyroid artery. Hematomas may cause airway compromise and must be evacuated immediately.","pyqMatches":[{"year":"2014","no":1533,"q":"Hemorrhage after thyroidectomy is due to","o":["External carotid artery","Internal carotid artey","Superior thyroid artery","Inferior thyroid artery"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9213, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 327, '{"id":9213,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":327,"q":"True about blind loop syndrome, all except","o":["Syndrome of bacterial overgrowth","Steatorrhea, mayeloblastic anemia & deficiency of fat soluble vitamins","Surgery is not indicated","14C-xylose or 14C-cholyglycine breath tests are indirect tests for bacterial overgrowth"],"a":2,"e":"Answer- C. Surgery is not indicated Features Diarrhea Steatorrhea Megaloblastic anemia (vit. B12 deficiency) Weight loss Abdominal pain Fat soluble vitamin deficiency Treatment Parentral vit. B1, therapy Broad spectrum antibiotics :","pyqMatches":[{"year":"2014","no":1539,"q":"True about blind loop syndrome, all except","o":["Syndrome of bacterial overgrowth","Steatorrhea, mayeloblastic anemia & deficiency of fat soluble vitamins","Surgery is not indicated","14C-xylose or 14C-cholyglycine breath tests are indirect tests for bacterial overgrowth"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9214, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 328, '{"id":9214,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":328,"q":"% of malignancy in duct ectasia is","o":["No risk","1.5:1","7:1","10:1"],"a":0,"e":"Answer- A. No risk Duct ectasia Cysts Apocrine metaplasia Apocrine metaplasia Mild hyperplasia A denosis Fibroadenoma (without atypia) No increased risk for cancer","pyqMatches":[{"year":"2014","no":1541,"q":"% of malignancy in duct ectasia is","o":["No risk","1.5:1","7:1","10:1"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9215, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'Surgery', 329, '{"id":9215,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":329,"q":"Recurrent anal fistula, most appropriate investigation is","o":["Endorectal US","Colonoscopy","MRI","Proctoscopy"],"a":2,"e":"Answer- C. MRI MRI is most accurate investigation for determining presence and course of recurrent anal fistulae.","pyqMatches":[{"year":"2014","no":1544,"q":"Recurrent anal fistula, most appropriate investigation is","o":["Endorectal US","Colonoscopy","MRI","Proctoscopy"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9216, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 330, '{"id":9216,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":330,"q":"Anal fissure diagnosed by","o":["TRUS","Colonoscopy","Clinical examination","Ba enema"],"a":2,"e":"Answer- C. Colonoscopy Anal fissure is a linear ulcer of the lower half of the anal canal, thus can be diagnosed by visually inspecting the anal verge with gentle separation of the gluteal cleft. The history is typical of pain and bleeding with defecation","pyqMatches":[{"year":"2014","no":1545,"q":"Anal fissure diagnosed by","o":["TRUS","Colonoscopy","Clinical examination","Ba enema"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9217, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 331, '{"id":9217,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":331,"q":"70 yr old female with bleeding from proximal colon","o":["Colitis","Polyp","Diverticulitis","Ca colon"],"a":3,"e":"Answer- D. Ca colon Bleeding per rectum in old age suggests the diagnosis of colorectal carcinoma. Symptoms of colorectal carcinoma are non-specific and generally develop when the cancer is locally advanced. Symptoms vary with the anatomic location of the tumor. Abd. pain Anemia (microcytic hypochronic anemia indicative of iron def.) Fatigue, palpitation and even angina pectoris Mass in right iliac fossa A cecal carcinoma can act as lead point in intussusception","pyqMatches":[{"year":"2014","no":1546,"q":"70 yr old female with bleeding from proximal colon","o":["Colitis","Polyp","Diverticulitis","Ca colon"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9218, 'Surgery', 'Vascular Surgery', 'Hard', 'Surgery', 332, '{"id":9218,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Hard","source":"Surgery","sourceNo":332,"q":"A 27 year old patient presented with left sided abdominal pain 6 hours after RTA. He was hemodynamically stable and FAST positive. CT scan showed grade III splenic injury. What will be appropriate treatment","o":["Splenectomy","Splenorrhaphy","Splenic artery embolization","Conservative management"],"a":3,"e":"Answer- D. Conservative management \"In early reports, most investigators expressed extreme caution regarding nonoperative management of grades III and IV, even with hemodynamic stability. As experience has accumulated, most feel comfortable with observing stable grade III injuries, and many have begun observing grade IV and V injuries\". --Sabiston","pyqMatches":[{"year":"2014","no":1548,"q":"A 27 year old patient presented with left sided abdominal pain 6 hours after RTA. He was hemodynamically stable and FAST positive. CT scan showed grade III splenic injury. What will be appropriate treatment","o":["Splenectomy","Splenorrhaphy","Splenic artery embolization","Conservative management"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9219, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 333, '{"id":9219,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":333,"q":"Retraction ball seen in","o":["Burns","Acute pancreatitis","Diffuse axonal injury","Tracheobronchial injury"],"a":2,"e":"Answer- C. Diffuse axonal injury At the distal tip of the amputated axon there is often and enlarged ball shaped collection of cytoplasm termed a ''retraction ball''. Axonal retraction balls- The Hallmark of Diffuse Axonal Injury.","pyqMatches":[{"year":"2014","no":1549,"q":"Retraction ball seen in","o":["Burns","Acute pancreatitis","Diffuse axonal injury","Tracheobronchial injury"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9220, 'Surgery', 'Endocrine Surgery', 'Easy', 'Surgery', 334, '{"id":9220,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Easy","source":"Surgery","sourceNo":334,"q":"Prophylactic thyroidectomy is indicated in","o":["Hashimoto thyroiditis","MEN type 2","Riedel thyroiditis","De-Quervain''s thyroiditis"],"a":1,"e":"Answer- B. MEN type 2 MEN type 2 syndrome consists of medullary carcinoma thyroid, for patients in low to high-risk groups, prophylactic thyroidectomy is recommended by age 5. Prophylactic thyroidectomy is indicated in MEN 2B syndrome. Medullary thyroid carcinoma (MTC) can be inherited as familial MTC, MEN 2A or MEN 2B syndromes. These conditions are autosomal dominant and occur due to RET proto-oncogene mutation. Individuals with RET mutation are very likely to develop MTC at a younger age. Once the mutation is confirmed, it is advised to undergo prophylactic thyroidectomy.","pyqMatches":[{"year":"2014","no":1550,"q":"Prophylactic thyroidectomy is indicated in","o":["Hashimoto thyroiditis","MEN type 2","Riedel thyroiditis","De-Quervain''s thyroiditis"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9221, 'Surgery', 'Endocrine Surgery', 'Easy', 'Surgery', 335, '{"id":9221,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Easy","source":"Surgery","sourceNo":335,"q":"Prophylactic Thyroidectomy for MEN 2 is recommended at age of","o":["5 years","Before 1 year","When detected","Any time"],"a":0,"e":"Answer- A. 5 years MEN type 2 syndrome consists of medullary carcinoma thyroid, for patients in low to high risk groups, prophylactic thyroidectomy is recommended by age 5.","pyqMatches":[{"year":"2014","no":1551,"q":"Prophylactic Thyroidectomy for MEN 2 is recommended at age of","o":["5 years","Before 1 year","When detected","Any time"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9222, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 336, '{"id":9222,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":336,"q":"Cleft palate is ideally repaired at","o":["5 month of age","1 year of age","Before going to school","6-8 years of age"],"a":1,"e":"Answer- B. 1 year of age Timing of Repair of Cleft Palate According to Sabiston - before 12 months According to Schwartz - at 9 to 12 months of age According to Bailey & Love - between 6 and 18 months","pyqMatches":[{"year":"2014","no":1553,"q":"Cleft palate is ideally repaired at","o":["5 month of age","1 year of age","Before going to school","6-8 years of age"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9223, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 337, '{"id":9223,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":337,"q":"Radiofrequency ablation is","o":["Derived from AC current","Used to separate fascial planes during surgery","Uses microwave","Used for hemostasis"],"a":0,"e":"Answer- A. Derived from AC current Radiofrequency ablation is a medical procedure in which part of the electrical conduction system of the heart, tumor or other dysfunctional tissue is ablated using the heat generation from high frequency alternating current (in the range of 350-500 KHz).","pyqMatches":[{"year":"2014","no":1555,"q":"Radiofrequency ablation is","o":["Derived from AC current","Used to separate fascial planes during surgery","Uses microwave","Used for hemostasis"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9224, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 338, '{"id":9224,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":338,"q":"Malignant melanoma false is","o":["Radiosensitive","Surgery is the treatment of choice","Acral lentiginous has worst prognosis","Treatment is mide local excision"],"a":0,"e":"Answer- A. Radiosensitive Melanoma are among the most radioresistant tumors. There are 4 common type of melanoma (these are in order of decreasing frequency)","pyqMatches":[{"year":"2014","no":1556,"q":"Malignant melanoma false is","o":["Radiosensitive","Surgery is the treatment of choice","Acral lentiginous has worst prognosis","Treatment is mide local excision"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9225, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 339, '{"id":9225,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":339,"q":"DVT not common causes","o":["Prolonged immobilizationa","Extensive pelvic sx of > 30 minutes","Obesity","Age less than 40"],"a":3,"e":"Answer- D. Age less than 40 A) Venous Thrombosis","pyqMatches":[{"year":"2014","no":1557,"q":"DVT not common causes","o":["Prolonged immobilizationa","Extensive pelvic sx of > 30 minutes","Obesity","Age less than 40"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9226, 'Surgery', 'Vascular Surgery', 'Easy', 'Surgery', 340, '{"id":9226,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Easy","source":"Surgery","sourceNo":340,"q":"Fogarty''s catheter is used for","o":["Embolization","Embolectomy","Radiofrequency ablation","Angiography"],"a":1,"e":"Answer- B. Embolectomy Fogarty''s catheter is an embolectomy catheter indicated for the removal of fresh, soft emboli and thrombi from vessels in the arterial system. The Fogarty embolectomy catheter has been found useful in minimizing blood loss in large surgical procedures about the hip and pelvis. Its utility lies in the ability to achieve temporary intraluminal occlusion of the common iliac artery while the proposed surgical procedure is being carried out.","pyqMatches":[{"year":"2014","no":1558,"q":"Fogarty''s catheter is used for","o":["Embolization","Embolectomy","Radiofrequency ablation","Angiography"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9227, 'Surgery', 'Hepatobiliary & Pancreas', 'Easy', 'Surgery', 341, '{"id":9227,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Easy","source":"Surgery","sourceNo":341,"q":"Choledochal cyst is dilatation of","o":["Gall bladder","CBD","Hepatic duct","Bile duct"],"a":3,"e":"Answer- D. Bile duct A choledochal cyst is an isolated or combined congenital dilatation of the extrahepatic or intrahepatic biliary tree.","pyqMatches":[{"year":"2014","no":1561,"q":"Choledochal cyst is dilatation of","o":["Gall bladder","CBD","Hepatic duct","Bile duct"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9228, 'Surgery', 'Urology', 'Easy', 'Surgery', 342, '{"id":9228,"subject":"Surgery","chapter":"Urology","difficulty":"Easy","source":"Surgery","sourceNo":342,"q":"False about retroperitoneal fibrosis is","o":["Ureter is most commonly involved","More common in females","Primary idiopathic form is called ormond''s disease","Corticosteroids are mainstay of treatment"],"a":1,"e":"Answer- B. More common in females RETROPERITONEAL FIBROSIS (ORMOND’S DISEASE) RPF is an uncommon inflammatory condition characteristed by proliferation of fibrous tissue in the retroperitoneum. The major structure involved are-","pyqMatches":[{"year":"2014","no":1562,"q":"False about retroperitoneal fibrosis is","o":["Ureter is most commonly involved","More common in females","Primary idiopathic form is called ormond''s disease","Corticosteroids are mainstay of treatment"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9229, 'Surgery', 'Urology', 'Easy', 'Surgery', 343, '{"id":9229,"subject":"Surgery","chapter":"Urology","difficulty":"Easy","source":"Surgery","sourceNo":343,"q":"Most commonly affected in ormond''s disease","o":["Aorta","IVC","Ureter","Gonadal vessels"],"a":2,"e":"Answer- C. Ureter The major structure involved are-","pyqMatches":[{"year":"2014","no":1563,"q":"Most commonly affected in ormond''s disease","o":["Aorta","IVC","Ureter","Gonadal vessels"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9230, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 344, '{"id":9230,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":344,"q":"Mucocele of gall bladder, false statement is","o":["Complication of gall stones","Treatment is early cholecystectomy","Obstruction at neck of gall bladder","Gall bladder is never palpable"],"a":3,"e":"Answer- D. Gall bladder is never palpable It is one of the complications of Gall stones. Caused due to obstruction of the stone at the neck of the bladder. The t/t is early cholycystectomy.","pyqMatches":[{"year":"2014","no":1564,"q":"Mucocele of gall bladder, false statement is","o":["Complication of gall stones","Treatment is early cholecystectomy","Obstruction at neck of gall bladder","Gall bladder is never palpable"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9231, 'Surgery', 'Gastrointestinal Surgery', 'Hard', 'Surgery', 345, '{"id":9231,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Hard","source":"Surgery","sourceNo":345,"q":"Investigation of choice for 74 yr old male patient scanty bleeding per rectum irregular bowel habits","o":["Sigmoidoscopy","Barium enema","Colonoscopy","Barium meal follow through"],"a":1,"e":"Answer- B. Barium enema The clinical features suggest diagnosis of diverticulosis. They are mainly found in the colon (mainly the left side of colon) with sigmoid colon being the most common site. Colonic diverticulosis is best diagnosed by Barium enema.","pyqMatches":[{"year":"2014","no":1566,"q":"Investigation of choice for 74 yr old male patient scanty bleeding per rectum irregular bowel habits","o":["Sigmoidoscopy","Barium enema","Colonoscopy","Barium meal follow through"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9232, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 346, '{"id":9232,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":346,"q":"Obstruction and dilatation of large intestine in absence of any mechanical obstruction","o":["Ogilve syndrome","Hirschsprung disease","Chagas disease","None"],"a":0,"e":"Answer- A. Ogilve syndrome Ogilvie syndrome, or acute colonic pseudo-obstruction (ACPO), is a clinical disorder with the signs, symptoms, and radiographic appearance of an acute large bowel obstruction with no evidence of actual physical cause of the obstruction.","pyqMatches":[{"year":"2014","no":1567,"q":"Obstruction and dilatation of large intestine in absence of any mechanical obstruction","o":["Ogilve syndrome","Hirschsprung disease","Chagas disease","None"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9233, 'Surgery', 'Endocrine Surgery', 'Easy', 'Surgery', 347, '{"id":9233,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Easy","source":"Surgery","sourceNo":347,"q":"Thyroid nodule increased radioisotope uptake IOC is","o":["Biopsy","Thyroid scan","FNAC","None"],"a":2,"e":"Answer- C. FNAC isotope scanning a thyroid nodule can be ''hot, ''warm'' or ''cold''. FNAC is the investigation of choice for solitary thyroid nodule.","pyqMatches":[{"year":"2014","no":1568,"q":"Thyroid nodule increased radioisotope uptake IOC is","o":["Biopsy","Thyroid scan","FNAC","None"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9234, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 348, '{"id":9234,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":348,"q":"What is intussuscepiens","o":["The entire complex of intussusception","The entering layer","The outer layer","The process of reducing the intussusception"],"a":2,"e":"Answer- C. The outer layer An intussusception is composed of three parts : The entering or inner tube - intussusceptum The returning or middle tube The sheath or outer tube - intussuscipiens","pyqMatches":[{"year":"2014","no":1570,"q":"What is intussuscepiens","o":["The entire complex of intussusception","The entering layer","The outer layer","The process of reducing the intussusception"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9235, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 349, '{"id":9235,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":349,"q":"Gum tumor with 5 cm in dimension and contralateral lymph node enlargement of 2 cm. There is no distant metasis. The stage of tumor :","o":["T3N2M0","T2N2M0","T1N2Mo","T3N3M0"],"a":0,"e":"Answer- A. T3N2M0 TNM STAGING OF ORAL CARCINOMA Primary tumor, as follows: T0 - No primary tumor Tis - Carcinoma in situ T1 - Tumor 2 cm or smaller T2 - Tumor 4 cm or smaller T3 - Tumor larger than 4 cm T4 - Tumor larger than 4 cm and deep invasion to muscle, bone, or deep structures (eg, antrum) Lymphatic node involvement, as follows: N0: No regional lymph node metastasis N1: Metastasis in a single ipsilateral lymph node N2a: Metastasis in a single ipsilateral lymph node >3 cm but not > 6 cm N2b: Metastasis in multiple ipsilateral lymph nodes, none >6 cm in greatest dimension N2c: Metastasis in bilateral or contralateral lymph nodes, none >6 cm in greatest dimension N3: Metastasis in any lymph node >6 cm Tumor metastasis(M), as follows: M0 - No metastasis M1 - Metastasis noted Staging Stage I : T1, N0, M0. Stage II : T2, N0, M0. Stage III : T3, N0, M0 T1, T2, T3, N1, M0 Stage IV : T4, N0, M0 Any T, N2 or N3, M0 Any T, any N, any M","pyqMatches":[{"year":"2014","no":1571,"q":"Gum tumor with 5 cm in dimension and contralateral lymph node enlargement of 2 cm. There is no distant metasis. The stage of tumor :","o":["T3N2M0","T2N2M0","T1N2Mo","T3N3M0"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9236, 'Surgery', 'Hepatobiliary & Pancreas', 'Easy', 'Surgery', 350, '{"id":9236,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Easy","source":"Surgery","sourceNo":350,"q":"Most common cause of duodenal obstruction in adults","o":["Lymphoma","Ca pancreas","Ca liver","Ca gall bladder"],"a":1,"e":"Answer- B. Ca pancreas Most common cause of duodenal obstruction (gastric outlet obstruction) in adults → Peptic ulcer disease. Most common cause of gastric outlet obstruction → Pyloric stenosis Most common cancer causing duodenal obstruction → Pancreatic cancer.","pyqMatches":[{"year":"2014","no":1575,"q":"Most common cause of duodenal obstruction in adults","o":["Lymphoma","Ca pancreas","Ca liver","Ca gall bladder"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9237, 'Surgery', 'Hepatobiliary & Pancreas', 'Hard', 'Surgery', 351, '{"id":9237,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Hard","source":"Surgery","sourceNo":351,"q":"Case of diagnosed cholecystitis presentation acute pain sharp going to the back diagnosis","o":["Acute pancreatitis","Cholecystitis","Appendicitis","Aortic aneurysm"],"a":0,"e":"Answer- A. Acute pancreatitis Clinical features- Acute severe, refractory, upper abdominal pain radiating to back Some patients may gain relief by sitting or leaning forwards Icterus can be caused by biliary obstruction in gallstone pancreatitis Grey turner''s sign – bluish discolouration of the flanks Cullen''s sign – bluish discoloration around umbilicus Fox sign – discoloration below inguinal ligament Shock, acute renal failure, ARDS, MODS Left sided pleural effusion","pyqMatches":[{"year":"2014","no":1578,"q":"Case of diagnosed cholecystitis presentation acute pain sharp going to the back diagnosis","o":["Acute pancreatitis","Cholecystitis","Appendicitis","Aortic aneurysm"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9238, 'Surgery', 'Hepatobiliary & Pancreas', 'Moderate', 'Surgery', 352, '{"id":9238,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Moderate","source":"Surgery","sourceNo":352,"q":"Man presented with acute abdomen, when man was put in knee chest position helped to relieve the pain what might be the cause.","o":["Acute pancreatitis","Cholecystitis","Superior mesenteric artery ischemia","Renal"],"a":0,"e":"Answer- A. Acute pancreatitis Acute severe, refractory, upper abdominal pain radiating to back Some patients may gain relief by sitting or leaning forwards Icterus can be caused by biliary obstruction in gallstone pancreatitis Grey turner''s sign – bluish discolouration of the flanks Cullen''s sign – bluish discoloration around umbilicus Fox sign – discoloration below inguinal ligament Shock, acute renal failure, ARDS, MODS Left sided pleural effusion","pyqMatches":[{"year":"2014","no":1579,"q":"Man presented with acute abdomen, when man was put in knee chest position helped to relieve the pain what might be the cause.","o":["Acute pancreatitis","Cholecystitis","Superior mesenteric artery ischemia","Renal"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9239, 'Surgery', 'General Principles & Wounds', 'Moderate', 'Surgery', 353, '{"id":9239,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Moderate","source":"Surgery","sourceNo":353,"q":"Man gunshot wound in thorax chest tube 1900 ml blood, 200 ml of blood lost per hr. next step","o":["Blood transfusion","Thoracotomy","PPV","FFP"],"a":1,"e":"Answer- B. Thoracotomy Initial drainage of more than 1500 ml blood or on going hemorrhage of more than 200 ml/hr over 3-4 hours is generally con¬sidered an indication for thoracotomy.","pyqMatches":[{"year":"2014","no":1580,"q":"Man gunshot wound in thorax chest tube 1900 ml blood, 200 ml of blood lost per hr. next step","o":["Blood transfusion","Thoracotomy","PPV","FFP"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9240, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 354, '{"id":9240,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":354,"q":"Most common cause of acute abdomen in young girl","o":["Acute appendicitis","ovarian torsion","Mitzschmerz","Renal colic"],"a":0,"e":"Answer- A. Acute appendicitis Most common cause of acute abdomen in yound women is acute appendicitis. Other causes are intestinal obstruction, diverticulitis, adnexal torsion, ovarian cyst rupture/hemorrhage, PID, endometriosis and dysmenorrhea.","pyqMatches":[{"year":"2014","no":1581,"q":"Most common cause of acute abdomen in young girl","o":["Acute appendicitis","ovarian torsion","Mitzschmerz","Renal colic"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9241, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 355, '{"id":9241,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":355,"q":"Decubitus ulcer is","o":["Venous ulcer","Wet gangrene","Trophic ulcer","Post thrombotic ulcer"],"a":2,"e":"Aswer- C. Trophic ulcer Trophic ulcers are neurogenic ulcers which are caused by various factors such as impairment of nutrition of the tissues, inadequate blood supply and neurological deficit.","pyqMatches":[{"year":"2013","no":1632,"q":"Decubitus ulcer is ?","o":["Due to trauma","Due to venous congestion","Due to friction created by thighs","Due to"],"a":1,"source":"NEET_2013_Paper.pdf"},{"year":"2014","no":1586,"q":"Decubitus ulcer is","o":["Venous ulcer","Wet gangrene","Trophic ulcer","Post thrombotic ulcer"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2013","2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9242, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 356, '{"id":9242,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":356,"q":"Lateral border of tongue carcinoma after resection","o":["Chemotherapy","Radiotherapy","Observation","Neck dissection"],"a":3,"e":"Answer- D. Neck dissection If regional lymphnodes are involved- Modified radical neck dissection or selective neck dissection is done. Indications for postoperative radiation therapy include evidence of perineural or angiolymphatic spread or positive nodal disease.","pyqMatches":[{"year":"2014","no":1582,"q":"Lateral border of tongue carcinoma after resection","o":["Chemotherapy","Radiotherapy","Observation","Neck dissection"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9243, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 357, '{"id":9243,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":357,"q":"Maximum weight reduction is by which surgery","o":["BPD","Roux en Y gastric bypass","Sleeve gastrectomy","Gastric banding"],"a":0,"e":"Answer- A. BPD Mixed procedures","pyqMatches":[{"year":"2014","no":1587,"q":"Maximum weight reduction is by which surgery","o":["BPD","Roux en Y gastric bypass","Sleeve gastrectomy","Gastric banding"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9244, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 358, '{"id":9244,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":358,"q":"Most common organism associated with breast abscess","o":["Streptococcus","Staphylococcus aureus","Klebsiella","None"],"a":1,"e":"Answer- B. Staphylococcus aureus Staphylococcus aureus is the most common cause of breast abscess. Most are caused by S. aureus and, if hospital-acquired, are likely to be penicillin-resistant. Staphylococcus aureus causes the clotting of milk in the blocked duct and multiply. Duct initially gets blocked by epithelial debris or by the retracted nipple.","pyqMatches":[{"year":"2014","no":1588,"q":"Most common organism associated with breast abscess","o":["Streptococcus","Staphylococcus aureus","Klebsiella","None"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9245, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 359, '{"id":9245,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":359,"q":"All is true about skull fracture except","o":["Puppes rule gives the sequence of fracture","Pond fracture is a mild depressed fracture","Fissured fracture is most common","Skull fractures are due to traction"],"a":1,"e":"Answer- B. Pond fracture is a mild depressed fracture Types of Skull fracture-","pyqMatches":[{"year":"2014","no":1589,"q":"All is true about skull fracture except","o":["Puppes rule gives the sequence of fracture","Pond fracture is a mild depressed fracture","Fissured fracture is most common","Skull fractures are due to traction"],"a":1,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9246, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 360, '{"id":9246,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":360,"q":"Cecum forms the posterior wall of which hernia","o":["Sliding hernia","Rolling hernia","Incisional hernia","Hiatus hernia"],"a":0,"e":"Answer- A. Sliding hernia Sliding hernia is defined as any hernia in which part of the sac (usually the posterior) is formed by the wall of a viscus. Cecum is involved on the right side and sigmoid colon is involved on left side. It should be clearly understood that the caecum, appendix or part of colon wholly within a hernial sac does not constitute a sliding hernia (The viscera must form a wall of the sac to be termed as sliding hernia). [Ref: Bailey & Love 26th/e p. 956]","pyqMatches":[{"year":"2014","no":1592,"q":"Cecum forms the posterior wall of which hernia","o":["Sliding hernia","Rolling hernia","Incisional hernia","Hiatus hernia"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9247, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 361, '{"id":9247,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":361,"q":"In last decade, duodenal ulcer and its morbidity is reduced due to","o":["Life style modification","Eradication of H pylori","Proton pump inhibitors","None"],"a":2,"e":"Answer- C. Proton pump inhibitors In last decades, with the introduction of proton pump inhibitors and increased knowledge of perforated pectic ulcer (PPU) etiology the incidence of PPU has reportedly decreased in western countries.","pyqMatches":[{"year":"2014","no":1593,"q":"In last decade, duodenal ulcer and its morbidity is reduced due to","o":["Life style modification","Eradication of H pylori","Proton pump inhibitors","None"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9248, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 362, '{"id":9248,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":362,"q":"Posterior duodenal ulcer is related to","o":["Gartoduodenal artery","Spleenic artery","Left gastric Artery","Sup mesentric artery"],"a":0,"e":"Answer- A. Gartoduodenal artery Gastroduodenal artery is the most common artery involved in duodenal ulcer haemorrhage. Also remember Peptic ulcer is the most common cause of massive upper gastrointestinal bleed (Duodenal ulcers > Gastric ulcer)","pyqMatches":[{"year":"2014","no":1594,"q":"Posterior duodenal ulcer is related to","o":["Gartoduodenal artery","Spleenic artery","Left gastric Artery","Sup mesentric artery"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9249, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 363, '{"id":9249,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":363,"q":"Postion in surgery for pilonidal sinus","o":["Sim''s","Tredelenberg","Lithotomy","Jack knife"],"a":3,"e":"Answer- D. Jack knife For most procedures, patient is placed in prone jack knife position with slight trendelenburg. Jack knife position An anatomical position in which the patient is placed on the stomach with the hips flexed and the knees bent at a 90° angle and the arm outstretached in front of the patient.","pyqMatches":[{"year":"2014","no":1595,"q":"Postion in surgery for pilonidal sinus","o":["Sim''s","Tredelenberg","Lithotomy","Jack knife"],"a":3,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9250, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 364, '{"id":9250,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":364,"q":"Length of flexible sigmoidoscope","o":["30 cm","40 cm","60 cm","70 cm"],"a":2,"e":"Answer- C. 60 cm The length of rigid sigmoidoscope is 25 cm, where as flexible sigmoidoscope are 60 cm long. [Ref Bailey & Love 25th/e p.1221; www.medicinenet.com]","pyqMatches":[{"year":"2014","no":1596,"q":"Length of flexible sigmoidoscope","o":["30 cm","40 cm","60 cm","70 cm"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9251, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 365, '{"id":9251,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":365,"q":"Hernia common in children","o":["Umbilical","Bockdelac","Morgagni","Inguinal"],"a":0,"e":"Answer- A. Umbilical \"Congenital umbilical hernias represent the most common abdominal wall defect in infant and children\". The incidence of umblical hernias is 5-10% in white children and may be as high as 25-50% in black children.","pyqMatches":[{"year":"2014","no":1600,"q":"Hernia common in children","o":["Umbilical","Bockdelac","Morgagni","Inguinal"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9252, 'Surgery', 'Vascular Surgery', 'Moderate', 'Surgery', 366, '{"id":9252,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":366,"q":"Gangrene not caused by","o":["Frost bite","Burger''s disease","Varicose veins","Atherosclerosis"],"a":2,"e":"Answer- C. Varicose veins Important causes of gangrene Diabetes PVD (Buerger''s disease) Trauma Obesity Atherosclerosis Raynaud''s disease Frostibite","pyqMatches":[{"year":"2014","no":1601,"q":"Gangrene not caused by","o":["Frost bite","Burger''s disease","Varicose veins","Atherosclerosis"],"a":2,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9253, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 367, '{"id":9253,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":367,"q":"Bilateral breast carcinoma","o":["Invasive lobular","Infiltractive ductal","Ductal ca in situ","None"],"a":0,"e":"Answer- A. Invasive lobular Lobular carcinoma (invasive) is frequently bilateral. Histologic hallmark : pattern of single infiltrating tumor cells often only one cell in width or in loose clusters or sheets. Signet ring cells common. Lobular carcinoma have a different pattern of metastasis compared to other breast cancers.","pyqMatches":[{"year":"2014","no":1602,"q":"Bilateral breast carcinoma","o":["Invasive lobular","Infiltractive ductal","Ductal ca in situ","None"],"a":0,"source":"NEET_2014_Paper.pdf"}],"pyqYears":["2014"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9254, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 368, '{"id":9254,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":368,"q":"Drainage of cervical abscess is an example of -","o":["Clean contaminated wound","Clean uncontaminated wound","Unclean uncontaminated wound","Dirty infected wound"],"a":3,"e":"Answer- D. Dirty infected wound Class IV: This class of wound is considered dirty-contaminated. These include wounds that have been exposed to fecal material. Cervical drainage abscess is an example of Class IV wound.","pyqMatches":[{"year":"2015","no":1218,"q":"Drainage of cervical abscess is an example of","o":["Clean contaminated wound","Clean uncontaminated wound","Unclean uncontaminated wound","Dirty infected wound"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9255, 'Surgery', 'Endocrine Surgery', 'Easy', 'Surgery', 369, '{"id":9255,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Easy","source":"Surgery","sourceNo":369,"q":"Most common location of ectopic salivary gland is -","o":["Cervical lymph nodes","Anterior mediastinum","Posterior triangle","Parathyroid gland"],"a":0,"e":"Answer- A. Cervical lymph nodes Salivary gland heterotopia is where salivary gland acini cells are present in an abnormal location without any duct system. The most common location is the cervical lymph nodes. Other reported sites of heterotopic salivary gland tissue are the middle ear, parathyroid glands, thyroid gland, pituitary gland, cerebellar pontine angle, soft tissue medial to sternocleidomastoid, stomach, rectum and vulva","pyqMatches":[{"year":"2015","no":1219,"q":"Most common location of ectopic salivary gland is","o":["Cervical lymph nodes","Anterior mediastinum","Posterior triangle","Parathyroid gland"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9256, 'Surgery', 'Hepatobiliary & Pancreas', 'Moderate', 'Surgery', 370, '{"id":9256,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Moderate","source":"Surgery","sourceNo":370,"q":"All of the following are paraneoplastic syndromes for renal cell carcinoma except -","o":["Fever","Anaemia","Amyloidosis","Acanthosis Nigricans"],"a":3,"e":"Answer- D. Acanthosis Nigricans Hypertension Abnormal liver function (Stauffers syndrome ie non metastatic hepatic dysfunction) Hypercalcemia Neuromyopathy Amyloidosis Increased ESR (MC paraneoplastic syndrome) Dysfibrogenemia Galactorrhoea Feminization and masculanization","pyqMatches":[{"year":"2015","no":1221,"q":"All of the following are paraneoplastic syndromes for renal cell carcinoma except","o":["Fever","Anaemia","Amyloidosis","Acanthosis Nigricans"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9257, 'Surgery', 'Urology', 'Easy', 'Surgery', 371, '{"id":9257,"subject":"Surgery","chapter":"Urology","difficulty":"Easy","source":"Surgery","sourceNo":371,"q":"ESWL is contraindicated in which of the following stones -","o":["Cysteine stones","Oxalate Stones","Urate stones","Phosphate stones"],"a":0,"e":"Answer- A. Cysteine stones Contraindications for ESWL -","pyqMatches":[{"year":"2015","no":1222,"q":"ESWL is contraindicated in which of the following stones","o":["Cysteine stones","Oxalate Stones","Urate stones","Phosphate stones"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9258, 'Surgery', 'Neurosurgery', 'Moderate', 'Surgery', 372, '{"id":9258,"subject":"Surgery","chapter":"Neurosurgery","difficulty":"Moderate","source":"Surgery","sourceNo":372,"q":"Traumatic optic neuropathy due to closed head trauma commonly affects which part of optic nerve -","o":["Optic canal","Intra ocular part","Intracranial part","Optic tract"],"a":0,"e":"Answer- A. Optic canal Indirect optic nerve injury Studies have shown that forces applied to the frontal bone and malar eminences are transferred and concentrated in the area near the optic canal. The tight adherence of the optic nerve''s dural sheath to the periosteum within the optic canal is also thought to contribute to this segment of the nerve being extremely susceptible to the deformative stresses of the skull bones. Such injury leads to ischemic injury to the retinal ganglion cells within the optic canal.","pyqMatches":[{"year":"2015","no":1364,"q":"Traumatic optic neuropathy due to closed head trauma commonly affects which part of optic nerve","o":["Optic canal","Intra ocular part","Intracranial part","Optic tract"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9259, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 373, '{"id":9259,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":373,"q":"All of the following are medical uses of erythropoietin except -","o":["Treatment of anaemia associated with renal disease","Chemotherapy induced anemia","Anaemia Associated with Crohn''s Disease","Megaloblastic Anaemis"],"a":3,"e":"Answer- D. Megaloblastic Anaemis Uses of erythropoetin Anaemia of renal failure. Anaemia associated with chemotherapy for diseases like mylodysplasia. Anaemia associated with inflammatory bowel disease.","pyqMatches":[{"year":"2015","no":1362,"q":"All of the following are medical uses of erythropoietin except","o":["Treatment of anaemia associated with renal disease","Chemotherapy induced anemia","Anaemia Associated with Crohn''s Disease","Megaloblastic Anaemis"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9260, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 374, '{"id":9260,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":374,"q":"Which of the following is the most conservative neck dissection -","o":["Supraomohyoid neck dissection","Radical neck dissection","Modified radical neck dissection","All are conservative"],"a":0,"e":"Answer- A. Supraomohyoid neck dissection Selective neck dissection - Preservation of any of the levels I through V during neck dissection is known as Selective neck dissection - The principle behind preservation of certain nodal groups is that specific primary sites preferentially drain their lymphatics in a predictable pattern. Types of SND include the supraomohyoid neck dissection, the lateral neck dissection, and the posterolateral neck dissection.","pyqMatches":[{"year":"2015","no":1225,"q":"Which of the following is the most conservative neck dissection","o":["Supraomohyoid neck dissection","Radical neck dissection","Modified radical neck dissection","All are conservative"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9261, 'Surgery', 'Neurosurgery', 'Easy', 'Surgery', 375, '{"id":9261,"subject":"Surgery","chapter":"Neurosurgery","difficulty":"Easy","source":"Surgery","sourceNo":375,"q":"Which of the following is most malignant tumor?","o":["Glioblastoma Multiforme","Meningioma","Osteochondroma","Giant cell tumor"],"a":0,"e":"Answer- A. Glioblastoma Multiforme Primary Brain Tumours","pyqMatches":[{"year":"2015","no":1361,"q":"Which of the following is most malignant tumor?","o":["Glioblastoma Multiforme","Meningioma","Osteochondroma","Giant cell tumor"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9262, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 376, '{"id":9262,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":376,"q":"Most tissue reaction is seen with","o":["Plain Catgut","Polydiaxonone","Silk","Chromic catgut"],"a":2,"e":"Answer- C. Silk Reaction to catgut depends on the stage of absorption and is mainly histocytic in type. Nonabsorbable sutures are encapsulated by a rim of connective tissue, while near the suture histocytes, giant cells and lymphocytes are found. This is most marked with silk and cotton, less so with Dacron, and least with nylon and wire.","pyqMatches":[{"year":"2015","no":1359,"q":"Most tissue reaction is seen with","o":["Plain Catgut","Polydiaxonone","Silk","Chromic catgut"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9263, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 377, '{"id":9263,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":377,"q":"Supraomohyoid dissection is a type of -","o":["Selective neck dissection","Modified radical neck dissection","Radical neck dissection","Posterolateral dissection"],"a":0,"e":"Answer- A. Selective neck dissection Selective neck dissection - Preservation of any of the levels I through V during neck dissection is known as Selective neck dissection - The principle behind preservation of certain nodal groups is that specific primary sites preferentially drain their lymphatics in a predictable pattern. Types of SND include the supraomohyoid neck dissection, the lateral neck dissection, and the posterolateral neck dissection.","pyqMatches":[{"year":"2015","no":1226,"q":"Supraomohyoid dissection is a type of","o":["Selective neck dissection","Modified radical neck dissection","Radical neck dissection","Posterolateral dissection"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9264, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 378, '{"id":9264,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":378,"q":"Polydiaxonone suture is normally absorbed in","o":["2 weeks","4 weeks","6 weeks","6 months"],"a":3,"e":"Answer- D. 6 months Retains 70% of its original tensile strength at 2 weeks, 50% at 4 weeks, and 25% at 6 weeks. Prolonged dermal support for at least 6 months has been associated with decreased scar spreading","pyqMatches":[{"year":"2015","no":1358,"q":"Polydiaxonone suture is normally absorbed in","o":["2 weeks","4 weeks","6 weeks","6 months"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9265, 'Surgery', 'Hepatobiliary & Pancreas', 'Moderate', 'Surgery', 379, '{"id":9265,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Moderate","source":"Surgery","sourceNo":379,"q":"Alagille syndrome- all of the following are true except -","o":["Mutation in JAG 1 And Notch2 gene are seen","Can Cause Autoimmune hepatitis","Autosomal Recessive Disease","Valvular anomalis of heart seen"],"a":2,"e":"Answer C. Autosomal Recessive Disease Autosomal dominant disease JAG I and NOTCH 2 mutation Affects the liver and Heart Heart Pulmonary stenosis Tetralogy of Fallot VSD Overriding aorta","pyqMatches":[{"year":"2015","no":1227,"q":"Alagille syndrome- all of the following are true except","o":["Mutation in JAG 1 And Notch2 gene are seen","Can Cause Autoimmune hepatitis","Autosomal Recessive Disease","Valvular anomalis of heart seen"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9266, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 380, '{"id":9266,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":380,"q":"Which of the following is an absorbable suture","o":["Polyglactin","Silk","Polyester","Ethilon"],"a":0,"e":"Answer- A. Polyglactin Absorbable sutures-","pyqMatches":[{"year":"2015","no":1357,"q":"Which of the following is an absorbable suture","o":["Polyglactin","Silk","Polyester","Ethilon"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9267, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 381, '{"id":9267,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":381,"q":"Which is the investigation of choice for staging of a lower limb sarcoma ?","o":["MRI","CT Scan","PET Scan","PET CT"],"a":0,"e":"Answer- A. MRI MRI : Investigation of choice for soft tissue sarcomas in extremities. CT SCAN : Investigation of choice for retroperitoneal sarcomas.","pyqMatches":[{"year":"2015","no":1356,"q":"Which is the investigation of choice for staging of a lower limb sarcoma ?","o":["MRI","CT Scan","PET Scan","PET CT"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9268, 'Surgery', 'General Principles & Wounds', 'Moderate', 'Surgery', 382, '{"id":9268,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Moderate","source":"Surgery","sourceNo":382,"q":"All of the following are true about the bare area of the liver except","o":["Infection can spread from the abdominal to thoracic cavity at this area","It is not a site of portocaval anastomosis","Formed by the reflections of coronary ligaments","It is triangular in shape"],"a":1,"e":"Answer- B. It is not a site of portocaval anastomosis The coronary ligaments represent reflections of the visceral peritoneum covering the liver onto the diaphragm. As such, between the two layers of the coronary ligament lies the bare area of the liver, and is attached to the diaphragm byareolar tissue. The bare area of the liver is still covered by Glisson''s capsule, the fibrous capsule that sheathes the entire liver. Bare area is a site of portocaval anastomoses","pyqMatches":[{"year":"2015","no":1355,"q":"All of the following are true about the bare area of the liver except","o":["Infection can spread from the abdominal to thoracic cavity at this area","It is not a site of portocaval anastomosis","Formed by the reflections of coronary ligaments","It is triangular in shape"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9269, 'Surgery', 'General Principles & Wounds', 'Moderate', 'Surgery', 383, '{"id":9269,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Moderate","source":"Surgery","sourceNo":383,"q":"All of the following are premalignant conditions except -","o":["Bowen''s Disease","Senile Keratosis","Xeroderma Pigmentosum","Pyoderma Gangrenosum"],"a":3,"e":"Answer- D. Pyoderma Gangrenosum Bowen''s Disease Lupus vulgaris Actinic Keratosis Long standing chronic ulcer (e.g. marjolin''s ulcers) Xeroderma pigmentosum Following burn, venous ulcer, old scar etc. Senile Keratosis","pyqMatches":[{"year":"2015","no":1229,"q":"All of the following are premalignant conditions except","o":["Bowen''s Disease","Senile Keratosis","Xeroderma Pigmentosum","Pyoderma Gangrenosum"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9270, 'Surgery', 'Urology', 'Easy', 'Surgery', 384, '{"id":9270,"subject":"Surgery","chapter":"Urology","difficulty":"Easy","source":"Surgery","sourceNo":384,"q":"Early stage of non small cell lung cancer can be treated by","o":["Surgical resection","Surgical resection with adjuvant chemotherapy","Radiotherapy","Immunotherapy"],"a":2,"e":"Answer- C. Radiotherapy Cystoscopy is endoscopy of the urinary bladder via the urethra. It is carried out with a cystoscope.","pyqMatches":[{"year":"2015","no":1352,"q":"Early stage of non small cell lung cancer can be treated by","o":["Surgical resection","Surgical resection with adjuvant chemotherapy","Radiotherapy","Immunotherapy"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9271, 'Surgery', 'Hepatobiliary & Pancreas', 'Easy', 'Surgery', 385, '{"id":9271,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Easy","source":"Surgery","sourceNo":385,"q":"Chimeric chemotherapy is being investigated for the treatment of which malignancy ?","o":["Leukemia","Renal Cell Carcinoma","CA Pancreas","Glioblastoma Multiforme"],"a":0,"e":"Answer- A. Leukemia Artificial T cell receptors (also known as chimeric T cell receptors, chimeric immunoreceptors, chimeric antigen receptors (CARs)) are engineered receptors, which graft an arbitrary specificity onto an immune effector cell. Typically, these receptors are used to graft the specificity of a monoclonal antibody onto a T cell. Two CAR-T therapies have been granted three total FDA approval for the treatment of patients with hematologic malignancies. The most advanced data to date concern CAR T therapies for the treatment of patients with multiple myeloma and chronic lymphocytic leukemia. Among the first studies investigating anti-CD19 CAR T therapeutic efficacy was a case report treating a patient with CLL.","pyqMatches":[{"year":"2015","no":1231,"q":"Chimeric chemotherapy is being investigated for the treatment of which malignancy ?","o":["Leukemia","Renal Cell Carcinoma","CA Pancreas","Glioblastoma Multiforme"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9272, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 386, '{"id":9272,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":386,"q":"Anterior Mediastinal nodes are included in which level of lymphnodes -","o":["I","III","V","VII"],"a":3,"e":"Answer- D. VII Levels of neck lymphnodes Level I, submental and submandibular group Level II, upper jugular group Level III, middle jugular group Level IV, lower jugular group Level V, posterior trian- gle group Level VI, anterior compartment. Level VII, anterior and superior mediastinal","pyqMatches":[{"year":"2015","no":1232,"q":"Anterior Mediastinal nodes are included in which level of lymphnodes","o":["I","III","V","VII"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9273, 'Surgery', 'Vascular Surgery', 'Easy', 'Surgery', 387, '{"id":9273,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Easy","source":"Surgery","sourceNo":387,"q":"In Celiac artery compression syndrome which structure is the main cause of compression -","o":["Median Arcuate Ligament","Rectus Sheath","Deep Inferior Epigastric artery","Lacunar Ligament"],"a":0,"e":"Answer- A. Median Arcuate Ligament Median arcuate ligament syndrome (MALS, also known as celiac artery compression syndrome, celiac axis syndrome, celiac trunk compression syndrome or Dunbar syndrome) is a condition characterized byabdominal pain attributed to compression of the celiac artery and possibly the celiac ganglia by the median arcuate ligament. The abdominal pain may be related to meals, may be accompanied by weight loss, and may be associated with an abdominal bruit heard by a clinician. It is also called celiac artery compression syndrome.","pyqMatches":[{"year":"2015","no":1233,"q":"In Celiac artery compression syndrome which structure is the main cause of compression","o":["Median Arcuate Ligament","Rectus Sheath","Deep Inferior Epigastric artery","Lacunar Ligament"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9274, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 388, '{"id":9274,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":388,"q":"The Bipolar cautery is preferred over monopolar cautery in the following surgeries except","o":["Hand Surgery","Surgery around Penis","Surgery of the Hip","Surgery around the face"],"a":2,"e":"Answer- C. Surgery of the Hip Bipolar cautery preferred in : Hand surgery Surgery around appendages like penis Surgery around the face","pyqMatches":[{"year":"2015","no":1350,"q":"The Bipolar cautery is preferred over monopolar cautery in the following surgeries except","o":["Hand Surgery","Surgery around Penis","Surgery of the Hip","Surgery around the face"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9275, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'Surgery', 389, '{"id":9275,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":389,"q":"All of the following are true about Nissen Fundoplication except","o":["It is done for GERD","Reinforcment is done only in the anterior half","Upper part of stomach is plicated around the lower esophagus","It is done for paraesophagal hiatus hernia"],"a":1,"e":"Answer- B. Reinforcment is done only in the anterior half In a fundoplication, the gastric fundus (upper part) of the stomach is wrapped, or plicated, around the lower end of the esophagus and stitched in place, reinforcing the closing function of the lower esophageal sphincter. The esophageal hiatus is also narrowed down by sutures to prevent or treat concurrent hiatal hernia, in which the fundus slides up through the enlargedesophageal hiatus of the diaphragm. In a Nissen fundoplication, also called a complete fundoplication, the fundus is wrapped all the way 360 degrees around the esophagus.","pyqMatches":[{"year":"2015","no":1347,"q":"All of the following are true about Nissen Fundoplication except","o":["It is done for GERD","Reinforcment is done only in the anterior half","Upper part of stomach is plicated around the lower esophagus","It is done for paraesophagal hiatus hernia"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9276, 'Surgery', 'General Principles & Wounds', 'Moderate', 'Surgery', 390, '{"id":9276,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Moderate","source":"Surgery","sourceNo":390,"q":"A 65 year old male presenting with acure pancreatitis is now having refractory hypoxia. The X RAY of chest would show","o":["Bilateral infiltrates","Pneumatocoeles","Ground glass appearances","Hilar lymphadenopathy"],"a":0,"e":"Answer- A. Bilateral infiltrates Systemic complications of pancreatitis Hypovolemic shock DIC ARDS Diabetes","pyqMatches":[{"year":"2015","no":1346,"q":"A 65 year old male presenting with acure pancreatitis is now having refractory hypoxia. The X RAY of chest would show","o":["Bilateral infiltrates","Pneumatocoeles","Ground glass appearances","Hilar lymphadenopathy"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9277, 'Surgery', 'Urology', 'Easy', 'Surgery', 391, '{"id":9277,"subject":"Surgery","chapter":"Urology","difficulty":"Easy","source":"Surgery","sourceNo":391,"q":"Which Is False about stress urinary incontinence -","o":["More common in men","It occurs during increased abdominal pressure","It is due to weakening of pelvic floor muscles","Prostate surgery may be a cause"],"a":0,"e":"Answer- A. More common in men Leaking urine upon sudden increase in abdominal pressure. It is most common type in women. Causes are Weakening of pelvic floor muscles / urethra / sphincter muscles. BPH, CA prostate or prostate surgery.","pyqMatches":[{"year":"2015","no":1234,"q":"Which Is False about stress urinary incontinence","o":["More common in men","It occurs during increased abdominal pressure","It is due to weakening of pelvic floor muscles","Prostate surgery may be a cause"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9278, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 392, '{"id":9278,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":392,"q":"Which of the following types of shock wiil usually have warm peripheral extremities ?","o":["Hypovolemic Shock","Neurogenic Shock","Cardiogenic Shock","Anaphylactic Shock"],"a":1,"e":"Answer- B. Neurogenic Shock Bradycardia Hypothermia Loss of sympathetic tone --> arterious & venous vasodilation Warm and dry skin (the heart rate slows down, as well as warm, dry, and flushed skin due to venous pooling secondary to loss of vascular tone) Others all shock have cold extremities (anaphylatic, cardiogenic and hypovolemic)","pyqMatches":[{"year":"2015","no":1236,"q":"Which of the following types of shock wiil usually have warm peripheral extremities ?","o":["Hypovolemic Shock","Neurogenic Shock","Cardiogenic Shock","Anaphylactic Shock"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9279, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 393, '{"id":9279,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":393,"q":"Antibiotic prophylaxis is best given -","o":["1 day before surgery","2 hours before surgery","Before the time of incision","Only postoperatively"],"a":2,"e":"Answer- C. Before the time of incision About prophylactic antibiotics points to know are ? By definition prophylaxis is limited to the time prior to and during the operative procedure. be most effective the prophylactic antibiotic agent should be administered intravenously before the incision is made so that the tissue levels are present at the time the wound is created and exposed to the bacterial contamination.","pyqMatches":[{"year":"2015","no":1237,"q":"Antibiotic prophylaxis is best given","o":["1 day before surgery","2 hours before surgery","Before the time of incision","Only postoperatively"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9280, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 394, '{"id":9280,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":394,"q":"Which of the following is a feature of crush syndrome -","o":["Hypokalemia","Hypercalcemia","Myoglobinuria","Hypophosphatemia"],"a":2,"e":"Answer- C. Myoglobinuria Features of crush syndrome : Hyperkalemia Hypocalcemia Hyperphosphatemia Hyperuricemia Lactic acidosis Myoglobinuria Increased BUN & creatinine.","pyqMatches":[{"year":"2015","no":1238,"q":"Which of the following is a feature of crush syndrome","o":["Hypokalemia","Hypercalcemia","Myoglobinuria","Hypophosphatemia"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9281, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 395, '{"id":9281,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":395,"q":"A young male presents with a testicular mass on the right side. The AFP is elevated while the HCG is normal. The most appropriate next step is","o":["Biopsy","USG","Orchidectomy","Wait and Watch"],"a":1,"e":"Answer- B A painless testicular mass is pathognomic for a testicular malignancy. USG of the testis is indicated whenever a testicular malignancy is considered and for persistent or painful testicular swelling.","pyqMatches":[{"year":"2015","no":1345,"q":"A young male presents with a testicular mass on the right side. The AFP is elevated while the HCG is normal. The most appropriate next step is","o":["Biopsy","USG","Orchidectomy","Wait and Watch"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9282, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 396, '{"id":9282,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":396,"q":"Crush Syndrome is associated with all of the following features except -","o":["Hypercalcemia","Hyperkalemia","Increased serum creatinine","Myoglobinuria"],"a":0,"e":"Answer- A. Hypercalcemia Features of crush syndrome : Hyperkalemia Hypocalcemia Hyperphosphatemia Hyperuricemia Lactic acidosis Myoglobinuria Increased BUN & creatinine.","pyqMatches":[{"year":"2015","no":1239,"q":"Crush Syndrome is associated with all of the following features except","o":["Hypercalcemia","Hyperkalemia","Increased serum creatinine","Myoglobinuria"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9283, 'Surgery', 'Urology', 'Moderate', 'Surgery', 397, '{"id":9283,"subject":"Surgery","chapter":"Urology","difficulty":"Moderate","source":"Surgery","sourceNo":397,"q":"A 45 year old male presenting with penile cancer extending upto the glans penis is treated with","o":["Partial Penectomy with 2 cm margin","Circumcision","Partial penectomy with Inguinal nodes exploration","Partial penectomy with 4 cm margin"],"a":0,"e":"Answer- A. Partial Penectomy with 2 cm margin The goal of t/t in invasive penile carcinomas is complete excision with adequate margins: a) For lesion involving the prepuce Simple circumcision is effective. b) For lesion of glans or distal shaft Partial penectomy with a 2 cm margin (less aggressive surgical resections such as Mohs micrographic surgery and local excisions directed at penile preservation can be done). c) For lesion involving the proximal shaft or when partial penectomy results in a penile stump of insufficient length for sexual function or directing the urinary stream Total penectomy with perineal urethrostomy","pyqMatches":[{"year":"2015","no":1344,"q":"A 45 year old male presenting with penile cancer extending upto the glans penis is treated with","o":["Partial Penectomy with 2 cm margin","Circumcision","Partial penectomy with Inguinal nodes exploration","Partial penectomy with 4 cm margin"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9284, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 398, '{"id":9284,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":398,"q":"Which of the following stones are common with infection ?","o":["Struvite","Xanthine Stones","Cysteine stones","Calcium Oxalate stones"],"a":0,"e":"Answer- A. Struvite Calcium phosphate can be combined with ammonium and magnesium to form the triple phosphate calculus ie Calcium amnomium magnesium phosphate also k/a struvite stones. Smooth and dirty white and soltitary. Seen in alkaline urine esp with proteus infection which split urea to ammonia.","pyqMatches":[{"year":"2015","no":1240,"q":"Which of the following stones are common with infection ?","o":["Struvite","Xanthine Stones","Cysteine stones","Calcium Oxalate stones"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9285, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 399, '{"id":9285,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":399,"q":"A 45 year old male is diagnosed with carcinoma penis. The surgeon must look out for which lymphnodes","o":["Para aortic","External iliac","Internal Iliac","Inguinal"],"a":3,"e":"Answer- D. Inguinal More than 50% of patients present with enlarged inguinal lymph nodes (but half of these are reactive enlargement d/t sepsis). The presence and the extent of metastasis to the inguinal region is the most important prognostic factor for survival in patients with Ca Penis.","pyqMatches":[{"year":"2015","no":1343,"q":"A 45 year old male is diagnosed with carcinoma penis. The surgeon must look out for which lymphnodes","o":["Para aortic","External iliac","Internal Iliac","Inguinal"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9286, 'Surgery', 'Urology', 'Easy', 'Surgery', 400, '{"id":9286,"subject":"Surgery","chapter":"Urology","difficulty":"Easy","source":"Surgery","sourceNo":400,"q":"High Flying prostate is a sign of -","o":["Extraperitoneal Bladder rupture","Intraperitoneal Bladder Rupture","Membranous Urethral Injury","Bulbar Urethral Injury"],"a":2,"e":"Answer- C. Membranous Urethral Injury The prostate is attached to pubis by puboprostatic ligament and disruption of the puboprostatic ligament with a complete rupture of the urethra can lead to a floating prostate—Vermooten’s sign (high fly prostate). Based on ascending urethrogram, posterior urethral injury is classified as (McCallum-Colapinto classification).","pyqMatches":[{"year":"2015","no":1242,"q":"High Flying prostate is a sign of","o":["Extraperitoneal Bladder rupture","Intraperitoneal Bladder Rupture","Membranous Urethral Injury","Bulbar Urethral Injury"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9287, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 401, '{"id":9287,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":401,"q":"Which of the following is false about undescended testis ?","o":["More common on the right side","Hormonal therapy is effective","Increased risk of malignancy","Secondary sexual characteristics are normal"],"a":1,"e":"Answer- B. Hormonal therapy is effective In undescended testis - the testes is arrested in some part of its path to the scrotum. In Ectopic testis - the testis is abnormally placed outside its path. Retractile testis - in infancy 80% of inapparent testis are retractile testis and require no t/t. Approx 70-77% of cryptorchid testes will spontaneously descend, usually by 3 months of age. More common in preterm, small for gestational age, LBW & twin neonates. More common on Rt. Side Secondary sexual characterstics are normal","pyqMatches":[{"year":"2015","no":1342,"q":"Which of the following is false about undescended testis ?","o":["More common on the right side","Hormonal therapy is effective","Increased risk of malignancy","Secondary sexual characteristics are normal"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9288, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 402, '{"id":9288,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":402,"q":"RPLND and Chemotherapy may be used in management of","o":["Non seminomatous Germ cell tumours of testis","Non germ cell tumours","Seminomatous Germ cell tumours","Lymphoma testis"],"a":0,"e":"Answer- A. Non seminomatous Germ cell tumours of testis RPLND retroperitoneal lymph node dissection Extra gonadal Germ cell tumors Infrequently GCTs arise from an extra gonadal site. They have poor prognosis. They are treated by chemotherapy.","pyqMatches":[{"year":"2015","no":1339,"q":"RPLND and Chemotherapy may be used in management of","o":["Non seminomatous Germ cell tumours of testis","Non germ cell tumours","Seminomatous Germ cell tumours","Lymphoma testis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9289, 'Surgery', 'Urology', 'Easy', 'Surgery', 403, '{"id":9289,"subject":"Surgery","chapter":"Urology","difficulty":"Easy","source":"Surgery","sourceNo":403,"q":"BPH involves -","o":["Central zone","Peripheral zone","Transitional zone","Prostate capsule"],"a":2,"e":"Answer- C. Transitional zone Carcinoma of prostate arises most commonly in the peripheral zone Benign prostatic hyperplasia originates in the transition zone BPH typically affects the submucous group of glands in the transitional zone, forming a nodular enlargement. Eventually, this overgrowth compresses the PZ glands into a false capsule and causes the appearance of the typical ''lateral''lobes. Ref- Bailey and Love Volume-1/ Edition 27th","pyqMatches":[{"year":"2015","no":1243,"q":"BPH involves","o":["Central zone","Peripheral zone","Transitional zone","Prostate capsule"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9290, 'Surgery', 'Urology', 'Easy', 'Surgery', 404, '{"id":9290,"subject":"Surgery","chapter":"Urology","difficulty":"Easy","source":"Surgery","sourceNo":404,"q":"Which of the following is a tumour marker for bladder cancer ?","o":["AFP","CEA","Bladder surface protein","Nuclear Matrix protein 22"],"a":3,"e":"Answer- D. Nuclear Matrix protein 22 Tumour markers in CA Bladder Nuclear matrix protein 22 BTA TRAK","pyqMatches":[{"year":"2015","no":1338,"q":"Which of the following is a tumour marker for bladder cancer ?","o":["AFP","CEA","Bladder surface protein","Nuclear Matrix protein 22"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9291, 'Surgery', 'Gastrointestinal Surgery', 'Hard', 'Surgery', 405, '{"id":9291,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Hard","source":"Surgery","sourceNo":405,"q":"A 45 year old lawyer presents with pain in the abdomen more so in the epigastric region that worsens with eating spicy food and is relieved by bending forward. Complications of the above mentioned condition could be all except","o":["Perforation","Bleeding","Gastric Outlet Obstruction","Splenic Vein Thrombosis"],"a":3,"e":"Ans. - D. Splenic Vein Thrombosis Bleeding, perforation and gastric outlet obstruction are the complications of peptic ulcer. Perforation: This allows stomach contents to escape into the peritoneum, causing peritonitis. It is more common in duodenal than in gastric ulcers. Gastric outlet obstruction: The most common cause is an ulcer near the pylorus, but occasional cases are due to antral cancer or adult hypertrophic pyloric stenosis. Bleeding","pyqMatches":[{"year":"2015","no":1337,"q":"A 45 year old lawyer presents with pain in the abdomen more so in the epigastric region that worsens with eating spicy food and is relieved by bending forward. Complications of the above mentioned condition could be all except","o":["Perforation","Bleeding","Gastric Outlet Obstruction","Splenic Vein Thrombosis"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9292, 'Surgery', 'Urology', 'Moderate', 'Surgery', 406, '{"id":9292,"subject":"Surgery","chapter":"Urology","difficulty":"Moderate","source":"Surgery","sourceNo":406,"q":"Prostate cancer that is limited to the capsule and not the urethra would be satged as -","o":["Tx","T1","T2","T3"],"a":2,"e":"Answer- C. T2","pyqMatches":[{"year":"2015","no":1244,"q":"Prostate cancer that is limited to the capsule and not the urethra would be satged as","o":["Tx","T1","T2","T3"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9293, 'Surgery', 'Urology', 'Hard', 'Surgery', 407, '{"id":9293,"subject":"Surgery","chapter":"Urology","difficulty":"Hard","source":"Surgery","sourceNo":407,"q":"A 65 year old male presents with CA prostate. The tumour is limited to the capsule and it is palpable on PR examination. The patient is diagnosed as stage T1b. The best treatment would be -","o":["Radical prostatectomy","Chemotherapy","Palliative radiotherapy","Orchidectomy"],"a":0,"e":"Answer- A. Radical prostatectomy T1b T1c, T2 Radical prostactectomy or radiotherapy External beam radiotherapy- T1 or low T2 disease Branchytherapy- low T1 disease","pyqMatches":[{"year":"2015","no":1245,"q":"A 65 year old male presents with CA prostate. The tumour is limited to the capsule and it is palpable on PR examination. The patient is diagnosed as stage T1b. The best treatment would be","o":["Radical prostatectomy","Chemotherapy","Palliative radiotherapy","Orchidectomy"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9294, 'Surgery', 'Urology', 'Hard', 'Surgery', 408, '{"id":9294,"subject":"Surgery","chapter":"Urology","difficulty":"Hard","source":"Surgery","sourceNo":408,"q":"A 55 years old male with a knoen history of gall stones presents with chief complints of severe abdominal pain and elevated levels of serum lipase with periumbilical ecchymosis. All of the following are prognostic criteria to predict severity of the condition except","o":["Age","Serum LDH","Base deficit","Serum GGT"],"a":3,"e":"Answer- D. Serum GGT","pyqMatches":[{"year":"2015","no":1335,"q":"A 55 years old male with a knoen history of gall stones presents with chief complints of severe abdominal pain and elevated levels of serum lipase with periumbilical ecchymosis. All of the following are prognostic criteria to predict severity of the condition except","o":["Age","Serum LDH","Base deficit","Serum GGT"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9295, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'Surgery', 409, '{"id":9295,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":409,"q":"If 90% of jejunum and ilium is removed then all of the following features will be seen excePt -","o":["Steatorrhoea","Diarrhoea","Weight gain","Megaloblastic anemia"],"a":2,"e":"Answer- C. Weight gain Changes seen in Terminal ileal resection Resection of terminal ileum results in malabsorption of bile salts and Vit. B12 which are normally absorbed in this region Vit BIZ Malabsorption : Megaloblastic anemia Bile salts malabsorption :- Unabsorbed bile salts escape into colon where they stimulate fluid secretion from the colon, resulting in watery diarrhoea. Reduction in bile salt pool lead to steatorrhea and malabsorption of fat soluble vitamins (due to malabsorption of fat). Unabsorbed fatty acids bind with calcium, and thus lead to increased concentration of free oxalates (oxalates bind with calcium normally and therefore escape without intestinal absorption) Free oxalates are absorbed. Increased conc. of body oxalates lead to oxalate kidney stones.","pyqMatches":[{"year":"2015","no":1247,"q":"If 90% of jejunum and ilium is removed then all of the following features will be seen excePt","o":["Steatorrhoea","Diarrhoea","Weight gain","Megaloblastic anemia"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9296, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 410, '{"id":9296,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":410,"q":"Most common location of breast cancer is","o":["Lower inner quadrant","Nipple","Upper inner quadrant","Upper outer quadrant"],"a":3,"e":"Answer- D. Upper outer quadrant Breast cancer is found most frequently in the upper outer quadrant. Least frequently in lower inner quadrant.","pyqMatches":[{"year":"2015","no":1334,"q":"Most common location of breast cancer is","o":["Lower inner quadrant","Nipple","Upper inner quadrant","Upper outer quadrant"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9297, 'Surgery', 'Breast Surgery', 'Hard', 'Surgery', 411, '{"id":9297,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Hard","source":"Surgery","sourceNo":411,"q":"A 22 year old woman comes with a non progressive mass in a left breast since 6 months. There are no associated symptoms. Examination shows a mobile mass not attached to the overlying skin or underlying tissue. The possible diagnosis is","o":["Fibroadenoma","Cystasarcoma Phylloides","Scirrhous Carcinoma","Fibroadenosis"],"a":0,"e":"Answer- A. Fibroadenoma Clinically, they present as firm masses that are easily movable. (MOUSE IN THE BREAST) They slide easily under the examining fingers and may be lobulated or smooth. Mammography is of little help in discriminating between cysts and fibroadenomas; however, ultrasonography can readily distinguish between them because each has specific characteristics. FNA biopsy can also be used to confirm the imaging findings","pyqMatches":[{"year":"2015","no":1333,"q":"A 22 year old woman comes with a non progressive mass in a left breast since 6 months. There are no associated symptoms. Examination shows a mobile mass not attached to the overlying skin or underlying tissue. The possible diagnosis is","o":["Fibroadenoma","Cystasarcoma Phylloides","Scirrhous Carcinoma","Fibroadenosis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9298, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 412, '{"id":9298,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":412,"q":"Perihepatic fibrosis occurring in Fitz Hugh Curtis Syndrome is due to -","o":["Pelvic Inflammatory Disease","Bile Duct Injry","Chronic Alcoholism","Viral Hepatitis"],"a":0,"e":"Answer- A. Pelvic Inflammatory Disease It is thought to result from direct intraperitoneal spread of infection towards the perihepatic region from initial pelvic inflammation/infection Trichomonas vaginalis, Ureaplasma urealyticum and Mycoplasma hominis may also cause FHCS.","pyqMatches":[{"year":"2015","no":1248,"q":"Perihepatic fibrosis occurring in Fitz Hugh Curtis Syndrome is due to","o":["Pelvic Inflammatory Disease","Bile Duct Injry","Chronic Alcoholism","Viral Hepatitis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9299, 'Surgery', 'Breast Surgery', 'Hard', 'Surgery', 413, '{"id":9299,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Hard","source":"Surgery","sourceNo":413,"q":"45 year old female underwent modified radical mastectomy with axillary clearance for CA breast. After surgery she could not lift her arm above head. Which nerve is likely to be injured ?","o":["Intercostobrachial nerve","Long thorasic nerve of Bell","Nerve to latissimus Dorsi","Lateral Pectoral nerve"],"a":1,"e":"Answer- B. Long thorasic nerve of Bell Overhead abduction is caused by :-","pyqMatches":[{"year":"2015","no":1332,"q":"45 year old female underwent modified radical mastectomy with axillary clearance for CA breast. After surgery she could not lift her arm above head. Which nerve is likely to be injured ?","o":["Intercostobrachial nerve","Long thorasic nerve of Bell","Nerve to latissimus Dorsi","Lateral Pectoral nerve"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9300, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 414, '{"id":9300,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":414,"q":"Which is the most common type of male breast cancer?","o":["Infiltrating Ductal Carcinoma","Lobular Carcinoma","Mucinous Carcinoma","Colloid Carcinoma"],"a":0,"e":"Answer- A. Infiltrating Ductal Carcinoma It tends to present as a lump and is most commonly an infiltrating ductal carcinoma. More than 90% of cases are infiltrating duct carcinoma, about 10% are ductal carcinoma in situ (DCIS). The known predisposing causes include gynecomastia and excess endogenous or exogenous estrogen.","pyqMatches":[{"year":"2015","no":1330,"q":"Which is the most common type of male breast cancer?","o":["Infiltrating Ductal Carcinoma","Lobular Carcinoma","Mucinous Carcinoma","Colloid Carcinoma"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9301, 'Surgery', 'General Principles & Wounds', 'Hard', 'Surgery', 415, '{"id":9301,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Hard","source":"Surgery","sourceNo":415,"q":"A 25 year old male is receiving conservative management for an appendicular mass since 3 days now presents with a rising pulse rate, tachycardia and fever. The mode of management must be -","o":["Ochsner sherren regimen","Continue conservative management","Proceed to laparotomy and appendicectomy","Intravenous antibiotics"],"a":2,"e":"Answer- C. Proceed to laparotomy and appendicectomy If an appendix mass is present and the condition of the patient is satisfactory, the standard treatment is the conservative Ochsner– Sherren regimen. 10-20% need emergency operation due to spreading infection.","pyqMatches":[{"year":"2015","no":1250,"q":"A 25 year old male is receiving conservative management for an appendicular mass since 3 days now presents with a rising pulse rate, tachycardia and fever. The mode of management must be","o":["Ochsner sherren regimen","Continue conservative management","Proceed to laparotomy and appendicectomy","Intravenous antibiotics"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9302, 'Surgery', 'Breast Surgery', 'Moderate', 'Surgery', 416, '{"id":9302,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":416,"q":"CA Breast may locally spread to all of the following muscles except","o":["Pectoralis Major","Pectoralis Minor","Latissimus Dorsi","Serratus Anterior"],"a":2,"e":"Answer- C. Latissimus Dorsi latissimus Dorsi is used for breast reconstruction and may rarely be involved in CA Breast local Spread'' Muscles involved in breast cancer","pyqMatches":[{"year":"2015","no":1329,"q":"CA Breast may locally spread to all of the following muscles except","o":["Pectoralis Major","Pectoralis Minor","Latissimus Dorsi","Serratus Anterior"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9303, 'Surgery', 'Gastrointestinal Surgery', 'Hard', 'Surgery', 417, '{"id":9303,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Hard","source":"Surgery","sourceNo":417,"q":"Under what guidelines is treatment started for a patient presenting with appendicular mass on CT Scan ?","o":["Ochsner Sherren Regimen","Conservative management and discharge","Immediate Laprotomy","Kocher''s Regimen"],"a":0,"e":"Answer- A. Ochsner Sherren Regimen Ochsner Sherren regimen is the expectant management giving to a patient with an appendix mass. It is expectant because it is expected that the symptoms and signs the patient presented with will improve during the course of the management and the patient may later be scheduled for elective/interval appendicectomy.","pyqMatches":[{"year":"2015","no":1251,"q":"Under what guidelines is treatment started for a patient presenting with appendicular mass on CT Scan ?","o":["Ochsner Sherren Regimen","Conservative management and discharge","Immediate Laprotomy","Kocher''s Regimen"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9304, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 418, '{"id":9304,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":418,"q":"Which of the following is true about menetrier''s disease","o":["It is premalignant condition","There is increased gastric acid secretion","Atrophied mucosal folds are seen","Affects the stomach and small intestines"],"a":0,"e":"Answer- A. It is premalignant condition Ménétrier disease is a rare, acquired, premalignant disease of the stomach characterized by massive gastric folds, excessive mucous production with resultant protein loss, and little or no acid production. The disorder is associated with excessive secretion of transforming growth factor alpha (TGF-α).","pyqMatches":[{"year":"2015","no":1327,"q":"Which of the following is true about menetrier''s disease","o":["It is premalignant condition","There is increased gastric acid secretion","Atrophied mucosal folds are seen","Affects the stomach and small intestines"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9305, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 419, '{"id":9305,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":419,"q":"A patient presents with difficulty with swallowing liquids but not solids. The best investigation to make a diagnosis is","o":["Endoscopy","Endoscopic ultrasound","Manometry","PET CT"],"a":2,"e":"Answer- C. Manometry H/O of dysphagia with more to liquids than solids suggests achalasia cardia. In all other obstructive causes of esophagus, dysphagia for solids is seen first Manometry is used for diagnosis.","pyqMatches":[{"year":"2015","no":1326,"q":"A patient presents with difficulty with swallowing liquids but not solids. The best investigation to make a diagnosis is","o":["Endoscopy","Endoscopic ultrasound","Manometry","PET CT"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9306, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 420, '{"id":9306,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":420,"q":"Spontaneous esophageal rupture is most common in","o":["Below the diagphragmatic aperture","Pharyngoesophagal junction","Above the diagphragmatic aperture","At the crossing of the arch of aorta"],"a":2,"e":"Answer C. Above the diagphragmatic aperture Instrumental perforation is common in the pharynx or distal esophagus. Spontaneous rupture may occur just above the diaphragm in the posterolateral wall of the esophagus.","pyqMatches":[{"year":"2015","no":1323,"q":"Spontaneous esophageal rupture is most common in","o":["Below the diagphragmatic aperture","Pharyngoesophagal junction","Above the diagphragmatic aperture","At the crossing of the arch of aorta"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9307, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 421, '{"id":9307,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":421,"q":"Aneurysmal dilation of the small bowel is seen in","o":["Small bowel Lymphoma","Gall Stone Ileus","Duodenal Atresia","Sjogrens Syndrome"],"a":0,"e":"Answer- A. Small bowel Lymphoma Aneurysmal dilatation: 30%, it occurs due to replacement of muscularis by tumour or infiltration of myenteric nerve plexus Despite the extensive involvement, small bowel obstruction is uncommon because of lack of desmoplastic reaction, and perforation is rare","pyqMatches":[{"year":"2015","no":1322,"q":"Aneurysmal dilation of the small bowel is seen in","o":["Small bowel Lymphoma","Gall Stone Ileus","Duodenal Atresia","Sjogrens Syndrome"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9308, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 422, '{"id":9308,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":422,"q":"Which is the main contraindication for a liver biopsy?","o":["Thrombocytopenia","Hemangioma","Ascites","All"],"a":3,"e":"Answer- D Contraindications for liver biopsy include the following: Increased prothrombin time (PT), international normalized ratio (INR) greater than 1.6 Thrombocytopenia, platelet count lower than 60,000/μL Ascites ( transjugular route preferred) [10] Difficult body habitus (transjugular route preferred) Suspected hemangioma Suspected echinococcal infection Uncooperative patient","pyqMatches":[{"year":"2015","no":1321,"q":"Which is the main contraindication for a liver biopsy?","o":["Thrombocytopenia","Hemangioma","Ascites","All"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9309, 'Surgery', 'Hepatobiliary & Pancreas', 'Moderate', 'Surgery', 423, '{"id":9309,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Moderate","source":"Surgery","sourceNo":423,"q":"Treatment of choice of mucinous carcinoma of Gall Bladder confined to the lamina propria is -","o":["Simple cholecystectomy","Extended cholecystectomy","Cholecystectomy with wedge resection of liver","Chemotherapy only"],"a":0,"e":"Answer- A. Simple cholecystectomy Treatment- Stage I and II - simple cholecystectomy Stage III – cholecystectomy + adjacent hepatic resection (atleast 2cm depth) + regional lymphadenectomy Poor prognosis","pyqMatches":[{"year":"2015","no":1252,"q":"Treatment of choice of mucinous carcinoma of Gall Bladder confined to the lamina propria is","o":["Simple cholecystectomy","Extended cholecystectomy","Cholecystectomy with wedge resection of liver","Chemotherapy only"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9310, 'Surgery', 'General Principles & Wounds', 'Moderate', 'Surgery', 424, '{"id":9310,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Moderate","source":"Surgery","sourceNo":424,"q":"All of the following are principles of negative pressure wound therapy except","o":["Stabilization of wound environment","Clearance of infection","Macrodeformation of the wound","Decreased edema"],"a":1,"e":"Answer- B. Clearance of infection Four primary effects of NPWT on wound healing: Macro-deformation - drawing the wound edges together leading to contraction. Stabilisation of the wound environment-ensuring it is protected from outside microorganisms in a warm and moist environment. Reduced oedema - with removal of soft tissue exudates. Micro-deformation- leading to cellular proliferation on the wound surface.","pyqMatches":[{"year":"2015","no":1320,"q":"All of the following are principles of negative pressure wound therapy except","o":["Stabilization of wound environment","Clearance of infection","Macrodeformation of the wound","Decreased edema"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9311, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 425, '{"id":9311,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":425,"q":"Most common precipitant of Raynaud''s phenomenon is","o":["Exposure to cold","Exposure to heat","Psychosocial triggers","Exertion"],"a":0,"e":"Answer- A. Exposure to cold Is ds of young women (F:M ratio is 5:1) Commonly the upper limbs are affected specially the fingers (the thumb is generally escaped) Exposure to cold is main trigger","pyqMatches":[{"year":"2015","no":1319,"q":"Most common precipitant of Raynaud''s phenomenon is","o":["Exposure to cold","Exposure to heat","Psychosocial triggers","Exertion"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9312, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 426, '{"id":9312,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":426,"q":"Nigro Regimen is used for -","o":["Anal Carcinoma","Rectal Carcinoma","Sigmoid Colon Carcinoma","Duodenal Carcinoma"],"a":0,"e":"Answer- A. Anal Carcinoma Nigro regimen refers to combined chemotherapy and radiotherapy for primary treatment of malignant tumors of the anal canal.","pyqMatches":[{"year":"2015","no":1253,"q":"Nigro Regimen is used for","o":["Anal Carcinoma","Rectal Carcinoma","Sigmoid Colon Carcinoma","Duodenal Carcinoma"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9313, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 427, '{"id":9313,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":427,"q":"The investigation of choice for dysphagia is","o":["Endoscopy","Manometric Study","Ct Scan","Barium Swallow"],"a":0,"e":"Answer- A. Endoscopy The investigation of choice in is endoscopy. Barium swallow is the first investigation.","pyqMatches":[{"year":"2015","no":1318,"q":"The investigation of choice for dysphagia is","o":["Endoscopy","Manometric Study","Ct Scan","Barium Swallow"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9314, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 428, '{"id":9314,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":428,"q":"A 54 year old woman is diagnosed as having carcinoma of the renal pelvis of size less than 4 cm without any metastasis. The best treatment option is","o":["Partial nephrectomy","Radical Nephrectomy","Chemotherapy and immunaotherapy","Palliative Radiotherapy"],"a":0,"e":"Answer- A. Partial nephrectomy Partial nephrectomy is now being used as primary surgical therapy for patients with tumour less than 4 cm in size, earlier Radical nephrectomy was the t/t of choice for tumor of any size.","pyqMatches":[{"year":"2015","no":1316,"q":"A 54 year old woman is diagnosed as having carcinoma of the renal pelvis of size less than 4 cm without any metastasis. The best treatment option is","o":["Partial nephrectomy","Radical Nephrectomy","Chemotherapy and immunaotherapy","Palliative Radiotherapy"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9315, 'Surgery', 'Hepatobiliary & Pancreas', 'Hard', 'Surgery', 429, '{"id":9315,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Hard","source":"Surgery","sourceNo":429,"q":"A 35 year old male came with jaundice, palpable mass in the right hypochondrium not associated with pain. The probable diagnosis is -","o":["Carcinoma Ampulla of Vater","Acute cholecystitis","Chronic Cholecystitis","Chronic Pancreatitis"],"a":0,"e":"Answer- A. Carcinoma Ampulla of Vater Courvoisier''s law states that in the presence of an enlarged gall bladder which is nontender and accompanied with jaundice the cause is unlikely to be gallstones. This is because gall stones are formed over a longer period of time, and this result in a shrunken, fibrotic gall bladder which does not distend easily.","pyqMatches":[{"year":"2015","no":1254,"q":"A 35 year old male came with jaundice, palpable mass in the right hypochondrium not associated with pain. The probable diagnosis is","o":["Carcinoma Ampulla of Vater","Acute cholecystitis","Chronic Cholecystitis","Chronic Pancreatitis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9316, 'Surgery', 'Hepatobiliary & Pancreas', 'Hard', 'Surgery', 430, '{"id":9316,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Hard","source":"Surgery","sourceNo":430,"q":"A 60 year male presented with jaundice, pale stools, dark urine and mass in the epigastric region. Which of the following diagnosis in unlikely ?","o":["Pancreatic cancer","Biliary Cancer","Periampullary Cancer","Chronic Cholecystitis"],"a":3,"e":"Answer- D. Chronic Cholecystitis Chronic cholecystitis is characterized by repeated attacks of pain (biliary colic) that occur when gallstones periodically block the cystic duct.","pyqMatches":[{"year":"2015","no":1255,"q":"A 60 year male presented with jaundice, pale stools, dark urine and mass in the epigastric region. Which of the following diagnosis in unlikely ?","o":["Pancreatic cancer","Biliary Cancer","Periampullary Cancer","Chronic Cholecystitis"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9317, 'Surgery', 'General Principles & Wounds', 'Moderate', 'Surgery', 431, '{"id":9317,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Moderate","source":"Surgery","sourceNo":431,"q":"All of the following may lead to a gall bladder carcinoma except -","o":["Gall Bladder Polyps","Typhoid carriers","Exposure to carcinogens like nitrosamine","Echinococcus Granulosus Infection"],"a":3,"e":"Answer- D. Echinococcus Granulosus Infection Risk factors for gall bladder","pyqMatches":[{"year":"2015","no":1256,"q":"All of the following may lead to a gall bladder carcinoma except","o":["Gall Bladder Polyps","Typhoid carriers","Exposure to carcinogens like nitrosamine","Echinococcus Granulosus Infection"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9318, 'Surgery', 'General Principles & Wounds', 'Moderate', 'Surgery', 432, '{"id":9318,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Moderate","source":"Surgery","sourceNo":432,"q":"All of the following may lead to pneumatocele formation except","o":["Staphylococcal pneumonia","Positive pressure ventilation","Hydrocarbon inhalation","ARDS"],"a":3,"e":"Answer-D Pneumatocele formation occurs as a sequela to acute pneumonia, commonly caused by Staphylococcus aureus. However, pneumatocele formation also occurs with other agents, including Streptococcus pneumoniae, Haemophilus influenzae, Escherichia coli, group A streptococci, Serratia marcescens, Klebsiella pneumonia, adenovirus, and tuberculosis. Noninfectious etiologies include hydrocarbon ingestion, trauma, and positive pressure ventilation. In premature infants with respiratory distress syndrome, pneumatoceles result mostly from ventilator-induced lung injury.","pyqMatches":[{"year":"2015","no":1315,"q":"All of the following may lead to pneumatocele formation except","o":["Staphylococcal pneumonia","Positive pressure ventilation","Hydrocarbon inhalation","ARDS"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9319, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 433, '{"id":9319,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":433,"q":"Which of the following stoma is formed in Hartman''s procedure ?","o":["End Colostomy","End Iliostomy","Loop Iliostomy","Caecostomy"],"a":0,"e":"Answer- A. End Colostomy Hartman''s procedure This is a compromise type of resection in which the rectum and/or sigmoid colon are resected and an end colostomy done. Anastomosis and perineal dissection of the distal rectum and perineum are not done.","pyqMatches":[{"year":"2015","no":1258,"q":"Which of the following stoma is formed in Hartman''s procedure ?","o":["End Colostomy","End Iliostomy","Loop Iliostomy","Caecostomy"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9320, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 434, '{"id":9320,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":434,"q":"Most common site of colorectal carcinoma is -","o":["Rectum","Sigmoid Colon","Ascending Colon","Descending Colon"],"a":0,"e":"Answer- A. Rectum Rectosigmoid region is the most common site for colorectal carcinoma. Rectum is involved in 38% of cases and sigmoid colon is involved in 21% cases.","pyqMatches":[{"year":"2015","no":1259,"q":"Most common site of colorectal carcinoma is","o":["Rectum","Sigmoid Colon","Ascending Colon","Descending Colon"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9321, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 435, '{"id":9321,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":435,"q":"Which of the following stages of lip carcinoma do not have nodal involvement ?","o":["T2N1","T3NO","T1N1","T2N2"],"a":1,"e":"Answer- B. T3NO","pyqMatches":[{"year":"2015","no":1314,"q":"Which of the following stages of lip carcinoma do not have nodal involvement ?","o":["T2N1","T3NO","T1N1","T2N2"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9322, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 436, '{"id":9322,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":436,"q":"Which of the following is true about Mallory Weiss tear -","o":["It is a mucosal tear not extending through the muscle layer","It is more common in women than men","It is common in young individuals","It is associated with achalasia cardia"],"a":0,"e":"Answer- A. It is a mucosal tear not extending through the muscle layer A Mallory -Weiss tear (MWT) is forceful or retching vomiting may produce a longitudinal mucosal tear immediately below squamo columnar junction at the cardia or gastroesophageal junction mainly and also in oesophagus. Seen in males, alcholics and pregnant females. The mean age is more than 60 and 80% are men. Hyperemesis gravidarum, which is severe morning sickness associated with vomiting and retching in pregnancy, is also a known cause of Mallory-Weiss tear.","pyqMatches":[{"year":"2015","no":1262,"q":"Which of the following is true about Mallory Weiss tear","o":["It is a mucosal tear not extending through the muscle layer","It is more common in women than men","It is common in young individuals","It is associated with achalasia cardia"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9323, 'Surgery', 'General Principles & Wounds', 'Hard', 'Surgery', 437, '{"id":9323,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Hard","source":"Surgery","sourceNo":437,"q":"A 40 year old male presented with a penetrating trauma to chest. He is dyspnoeic with distended neck veins with hypotension and mediastinum is shifted to opposite side. There is a sucking wound over the chest. The most appropriate management would be","o":["Insertion of a large bore needle in the 2\" ICS in the mid clavicular line","Fluid Resuscitation","Starting Inotropic support","Endotracheal Intubation"],"a":0,"e":"Answer- A. Insertion of a large bore needle in the 2\" ICS in the mid clavicular line This is a case of tension pneumothorax. Treatment consists of immediate decompression, initially by rapid insertion of a large-bore needle into the second intercostal space in the midcalvicular line of the affected hemithorax, and then followed by insertion of a chest tube through the fifth intercostal space in the anterior axillary line.","pyqMatches":[{"year":"2015","no":1313,"q":"A 40 year old male presented with a penetrating trauma to chest. He is dyspnoeic with distended neck veins with hypotension and mediastinum is shifted to opposite side. There is a sucking wound over the chest. The most appropriate management would be","o":["Insertion of a large bore needle in the 2\" ICS in the mid clavicular line","Fluid Resuscitation","Starting Inotropic support","Endotracheal Intubation"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9324, 'Surgery', 'General Principles & Wounds', 'Hard', 'Surgery', 438, '{"id":9324,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Hard","source":"Surgery","sourceNo":438,"q":"A 40 year old male with chest trauma presents with breathlessness, decreased respiratory sounds on the right side, hyperresonance on percussion and distended neck veins. The possible diagnosis is","o":["Tension Pneumothorax","Cardiac Tamonade","Flail Chest","Myocardial Infarction"],"a":0,"e":"Answer- A. Tension Pneumothorax Tension pneumothorax occurs when air becomes trapped in the pleural space under pressure. It develops when a ''one-way valve'' air leak occurs either from the lung or through the chest wall. causes are Penetrating chest trauma, Blunt chest trauma, Iatrogenic lung punctures (e.g. due to subclavian central venepuncture) and Mechanical positive-pressure ventilation Clinical Clinical signs and symptoms include dyspnea, tachypnea, hypotension, diaphoresis, and distended neck veins.","pyqMatches":[{"year":"2015","no":1312,"q":"A 40 year old male with chest trauma presents with breathlessness, decreased respiratory sounds on the right side, hyperresonance on percussion and distended neck veins. The possible diagnosis is","o":["Tension Pneumothorax","Cardiac Tamonade","Flail Chest","Myocardial Infarction"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9325, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 439, '{"id":9325,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":439,"q":"Which of the following is an indication for thoracotomy in case of hemothorax ?","o":["Persistant drainage of 250 ml/hr","Total output of 1000m1 of blood","Falling blood pressure","Shift of mediastimum to the opposite side"],"a":0,"e":"Answer- A. Persistant drainage of 250 ml/hr It is classified according to the amount of blood. Minimal hemothorax 350 ml Moderate hemothorax 350-1500 ml Massive hemothorax 1500 ml or more Total hemorrhagic output exceeds 1500 ml of blood","pyqMatches":[{"year":"2015","no":1311,"q":"Which of the following is an indication for thoracotomy in case of hemothorax ?","o":["Persistant drainage of 250 ml/hr","Total output of 1000m1 of blood","Falling blood pressure","Shift of mediastimum to the opposite side"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9326, 'Surgery', 'Hepatobiliary & Pancreas', 'Hard', 'Surgery', 440, '{"id":9326,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Hard","source":"Surgery","sourceNo":440,"q":"A 55 year old woman presented with history of recurrent episodes of right upper abdominal pain for the last one year. She presented to emergency with history of jaundice and fever for 2 days. On examination, the patient appeared toxic and had a blood pressure of 100/60 mmHg. She was started on intravenous antibiotics. Ultrasound of the abdomen showed presence of stones in the common bile duct. What would be the best treatment option for her -","o":["ERCP and bile duct stone extraction","Laparoscopic cholecystectomy","Open surgery and bile duct stone extraction","Lithotripsy"],"a":0,"e":"Answer- A. ERCP and bile duct stone extraction Methods of biliary decompression a. ERCP with sphincterotomy and stone extraction It is the procedure of choice, Early endoscopy allows not only diagnosis by cholangiography and direct visualization of the ampulla but also permits biliary decompression by sphincterotomy and stone extraction. If the stones cannot be removed, a nasobiliary catheter or stent is inserted to decompress the biliary tract. b. Percutaneous transhepatic route (PTC) PTC is performed if The endoscopic procedure has failed or not available. If the obstruction is more proximal or perihilar. If there is a stricture in a biliary enteric anastomosis. c. Surgical biliary decompression","pyqMatches":[{"year":"2015","no":1264,"q":"A 55 year old woman presented with history of recurrent episodes of right upper abdominal pain for the last one year. She presented to emergency with history of jaundice and fever for 2 days. On examination, the patient appeared toxic and had a blood pressure of 100/60 mmHg. She was started on intravenous antibiotics. Ultrasound of the abdomen showed presence of stones in the common bile duct. What would be the best treatment option for her","o":["ERCP and bile duct stone extraction","Laparoscopic cholecystectomy","Open surgery and bile duct stone extraction","Lithotripsy"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9327, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 441, '{"id":9327,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":441,"q":"Rigler''s sign is suggestive of -","o":["Pneumothorax","Pneumoperitoneum","Peritonitis","Hemothorax"],"a":1,"e":"Answer- B. Pneumoperitoneum Both sides of bowel become visible because of free gas on an abdominal x-ray. This is known as Rigler''s Sign.","pyqMatches":[{"year":"2015","no":1265,"q":"Rigler''s sign is suggestive of","o":["Pneumothorax","Pneumoperitoneum","Peritonitis","Hemothorax"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9328, 'Surgery', 'Gastrointestinal Surgery', 'Hard', 'Surgery', 442, '{"id":9328,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Hard","source":"Surgery","sourceNo":442,"q":"A 70 year pld male complaining of per rectal bleeding was diagnosed of having rectal/anorectal cancer. The distal margin of the tumor was 5 cm from the anal verge the treatment of choice would be -","o":["Palliative Radiotherapy","Abdominoperineal recection","Low anterior resection","Local Excision"],"a":2,"e":"Answer- C. Low anterior resection Surgeries Pre-operative neo-adjuvant radiotherapy in resectable rectal cancer reduces the incidence of local recurrence Adjuvant chemotherapy improves survival in node-positive cases Anterior(low) resection: sphincter saving procedure, mid rectum Proximal 2/3rdof rectum(lesions 6cms above the dentate line/2 or more cms above anal canal) Well differentiated tumour size tumour T1/T2,NO tumours Recto sigmoid tumors and upper third rectal tumors :High anterior resection (rectum and mesorectum are taken to a margin 5cm distal to the tumour and colorectal anastomosis is performed) Tumours in the middle and lower thirds of rectum: complete removal of rectum and mesorectum (TME-total mesorectal excision) Abdomino perineal resection(Mike''s procedure)- Lower rectum Hartmann''s procedure – for elderly and unstable patients who cannot withstand long procedure of APR Colonoscopy is always performed either before (for synchronous tumours) or within a few months (for metachronous tumours) of surgical resection for tumour detection","pyqMatches":[{"year":"2015","no":1267,"q":"A 70 year pld male complaining of per rectal bleeding was diagnosed of having rectal/anorectal cancer. The distal margin of the tumor was 5 cm from the anal verge the treatment of choice would be","o":["Palliative Radiotherapy","Abdominoperineal recection","Low anterior resection","Local Excision"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9329, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'Surgery', 443, '{"id":9329,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":443,"q":"All of the following are true about Hirschsprung disease except -","o":["Absence of Ganglion cells in the involved segment","Swenson, Duhamel and Soave are surgical procedures for this condition","Mainly presents in infancy","The non peristaltic affected segment is dialted"],"a":3,"e":"Answer- D. The non peristaltic affected segment is dialted In Hirchprung''s disease the absence of ganglion cells gives rise to a contracted non peristaltic segment with a dilated hypertrophied segment of normal colon above it. Almost all cases present in infancy and childhood. Approximately half are diagnosed in the neonatal period and most of the remainder are diagnosed in early childhood. In the newborn period, most common symptoms are abdominal distention and failure to passmeconium. Older patients may experience chronic or intermittent constipation. Occasionally, infants may present with a dramatic complication of Hirschprung''s disease called enterocolitis. Surgery is always required. The basic principle is removal of most or all of the aganglionic segment and anastomosing the ganglionic bowel to the rectum","pyqMatches":[{"year":"2015","no":1268,"q":"All of the following are true about Hirschsprung disease except","o":["Absence of Ganglion cells in the involved segment","Swenson, Duhamel and Soave are surgical procedures for this condition","Mainly presents in infancy","The non peristaltic affected segment is dialted"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9330, 'Surgery', 'Endocrine Surgery', 'Easy', 'Surgery', 444, '{"id":9330,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Easy","source":"Surgery","sourceNo":444,"q":"Most common cause of goiter in India is","o":["Diffuse Endemic Goitre","Papillary Carcinoma","Toxic Multinodular Goitre","Hashimoto''s Thyroiditis"],"a":0,"e":"Answer- A. Diffuse Endemic Goitre The lack of the iodine leads to decreased synthesis of thyroid hormones and a compensatory increase in TSH, which in turn leads to follicular cell hypertrophy and hyperplasia and goitrous enlargement - Diffuse hyperplastic goiter. Mostly patients are euthyroid.","pyqMatches":[{"year":"2015","no":1310,"q":"Most common cause of goiter in India is","o":["Diffuse Endemic Goitre","Papillary Carcinoma","Toxic Multinodular Goitre","Hashimoto''s Thyroiditis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9331, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 445, '{"id":9331,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":445,"q":"All of the following are clinical features suggestive of trachea-esophagal fistula except -","o":["Choking and Coughing","Regurgitation","Cyanosis","Fever"],"a":3,"e":"Answer- D. Fever Repeated episodes of coughing, choking and cyanosis occur on feeding with TOF.","pyqMatches":[{"year":"2015","no":1270,"q":"All of the following are clinical features suggestive of trachea-esophagal fistula except","o":["Choking and Coughing","Regurgitation","Cyanosis","Fever"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9332, 'Surgery', 'Endocrine Surgery', 'Easy', 'Surgery', 446, '{"id":9332,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Easy","source":"Surgery","sourceNo":446,"q":"In Subtotal Thyroidectomy, What is true","o":["Removal of one lobe and isthmus","Removal of both lobes leaving behind 6-8 grams of tissue","Removal of entire thyroid with cervical lymphnodes","Removal of 1 lobe with isthmus and the second lobe partially"],"a":1,"e":"Answer- B. Removal of both lobes leaving behind 6-8 grams of tissue Subtotal thyroidectomy—Removal of majority of both lobes leaving behind 4-5 grams (equivalent to the size of a normal thyroid gland) of thyroid tissue on one or both sides—this used to be the most common operation for multinodular goitre.","pyqMatches":[{"year":"2015","no":1307,"q":"In Subtotal Thyroidectomy, What is true","o":["Removal of one lobe and isthmus","Removal of both lobes leaving behind 6-8 grams of tissue","Removal of entire thyroid with cervical lymphnodes","Removal of 1 lobe with isthmus and the second lobe partially"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9333, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 447, '{"id":9333,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":447,"q":"Most important presenting feature of periampullary carcinoma is -","o":["Jaundice","Pain","Weight Loss","Palpable Mass"],"a":0,"e":"Answer- A Hallmark of presentation of periampullary carcinoma is obstructive Jaundice. Jaundice secondary to obstruction of the distal bile duct is the most common symptom that draws attention to ampullary and pancreatic head tumors. It is characteristically painless jaundice but may be associated with nausea and epigastric discomfort.","pyqMatches":[{"year":"2015","no":1271,"q":"Most important presenting feature of periampullary carcinoma is","o":["Jaundice","Pain","Weight Loss","Palpable Mass"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9334, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 448, '{"id":9334,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":448,"q":"All of the following are surgical options in management of esophageal carcinoma except -","o":["Ivor Lewis Approach","Mckeown''s Approach","Transhiatal removal","Sistrunk operation"],"a":3,"e":"Answer- D. Sistrunk operation Ivor lewis operation is subtotal esophagectomy done for Ca esophagus in lower third of esophagus In transhiatal esophagectomy (THE) Esophagus is removed through the diaphragmatic hiatus by making incisions in the abdomen and the neck. McKeowns Surgery- 3 Incision Approach","pyqMatches":[{"year":"2015","no":1275,"q":"All of the following are surgical options in management of esophageal carcinoma except","o":["Ivor Lewis Approach","Mckeown''s Approach","Transhiatal removal","Sistrunk operation"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9335, 'Surgery', 'Endocrine Surgery', 'Hard', 'Surgery', 449, '{"id":9335,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Hard","source":"Surgery","sourceNo":449,"q":"A 65 year old female presents with a swelling in the neck diagnosed as a solitary thyroid nodule. The patient is investigated and a scan shows increased uptake of iodine. Serum T3 and T4 are elevated . Most probabe diagnosis is","o":["Benign Colloid Nodule","Toxic Adenoma","Follicular adenoma","Toxic Multinodular goitre"],"a":1,"e":"Answer- B. Toxic Adenoma Elavated thyroid hormone levels with a hyperfunctioning nodule is suggestive of a toxic adenoma. A cold nodule is more likely to be malignant then a hot nodule.","pyqMatches":[{"year":"2015","no":1309,"q":"A 65 year old female presents with a swelling in the neck diagnosed as a solitary thyroid nodule. The patient is investigated and a scan shows increased uptake of iodine. Serum T3 and T4 are elevated . Most probabe diagnosis is","o":["Benign Colloid Nodule","Toxic Adenoma","Follicular adenoma","Toxic Multinodular goitre"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9336, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 450, '{"id":9336,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":450,"q":"Chronic hemolytic anaemia is associated with which of the following -","o":["Brown Pigment stone of the gall bladder","Black Pigment stone of the gall bladder","Uric acid Renal Calculus","Intestinal Obstruction"],"a":1,"e":"Answer- B. Black Pigment stone of the gall bladder Hemolysis causes black pigment stone of gall bladder. Chronic hemolytic states (eg. hereditary spherocytosis, sickle cell disease).","pyqMatches":[{"year":"2015","no":1277,"q":"Chronic hemolytic anaemia is associated with which of the following","o":["Brown Pigment stone of the gall bladder","Black Pigment stone of the gall bladder","Uric acid Renal Calculus","Intestinal Obstruction"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9337, 'Surgery', 'Transplantation', 'Moderate', 'Surgery', 451, '{"id":9337,"subject":"Surgery","chapter":"Transplantation","difficulty":"Moderate","source":"Surgery","sourceNo":451,"q":"All of the following is true about heart transplantation except -","o":["Immmunosupression is started preoperatively","It is only orthotopic and not heterotopic","A Beating heart cadaver/donor is needed","High Pulmonary arterial resistance in a contra indication"],"a":1,"e":"Answer- B. It is only orthotopic and not heterotopic Types of transplant : Heterotopic Orthotopic A typical heart transplantation begins when a suitable donor heart is identified. The heart comes from a recently deceased or brain dead donor, also called a beating heart cadaver.","pyqMatches":[{"year":"2015","no":1279,"q":"All of the following is true about heart transplantation except","o":["Immmunosupression is started preoperatively","It is only orthotopic and not heterotopic","A Beating heart cadaver/donor is needed","High Pulmonary arterial resistance in a contra indication"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9338, 'Surgery', 'Endocrine Surgery', 'Hard', 'Surgery', 452, '{"id":9338,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Hard","source":"Surgery","sourceNo":452,"q":"Thyroid nodule in a 65 year old male who is clinically euthyroid is most likely to be","o":["Follicular adenoma","Follicular Carcinoma","Thyroid Cyst","Multinodular goiter"],"a":0,"e":"Answer- A. Follicular adenoma Most common solitary thyroid nodule is benign colloid nodule. 2\"d most common cause of solitary thyroid nodule is follicular adenoma.","pyqMatches":[{"year":"2015","no":1306,"q":"Thyroid nodule in a 65 year old male who is clinically euthyroid is most likely to be","o":["Follicular adenoma","Follicular Carcinoma","Thyroid Cyst","Multinodular goiter"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9339, 'Surgery', 'General Principles & Wounds', 'Hard', 'Surgery', 453, '{"id":9339,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Hard","source":"Surgery","sourceNo":453,"q":"In case of polytrauma with multiple injuries to the chest, neck and abdomen, highest priority is given to","o":["Stabilization of cervical spine","Staring of koids","Vasopressors","Assesing disability"],"a":0,"e":"Answer- A. Stabilization of cervical spine","pyqMatches":[{"year":"2015","no":1305,"q":"In case of polytrauma with multiple injuries to the chest, neck and abdomen, highest priority is given to","o":["Stabilization of cervical spine","Staring of koids","Vasopressors","Assesing disability"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9340, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 454, '{"id":9340,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":454,"q":"A child presented with blunt abdominal trauma, the first investigation to be done is -","o":["USG","CT Scan","Complete Hemogram","Abdominal Xray"],"a":0,"e":"Answer- A. USG U/S is the investigation of choice in both stable as well as unstable patients.","pyqMatches":[{"year":"2015","no":1281,"q":"A child presented with blunt abdominal trauma, the first investigation to be done is","o":["USG","CT Scan","Complete Hemogram","Abdominal Xray"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9341, 'Surgery', 'Breast Surgery', 'Moderate', 'Surgery', 455, '{"id":9341,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":455,"q":"Which of the following precancerous conditions if treated would not lead to cancer","o":["Cervical intraepithelial Neoplasia","Ductal carcinoma in situ of breast","Lobular Carcinoma in situ of breast","Vaginal intraepithelial Neoplasia"],"a":0,"e":"Answer- A. Cervical intraepithelial Neoplasia The cancers, which have well known precancerous condition, can be diagnosed and treated at pre-cancerous stage to prevent the development of cancer : -","pyqMatches":[{"year":"2015","no":1302,"q":"Which of the following precancerous conditions if treated would not lead to cancer","o":["Cervical intraepithelial Neoplasia","Ductal carcinoma in situ of breast","Lobular Carcinoma in situ of breast","Vaginal intraepithelial Neoplasia"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9342, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 456, '{"id":9342,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":456,"q":"Vacuum assisted closure is contraindicated in which of the following conditions -","o":["Chronic osteomyelitis","Large amount of necrotic tissue with eschar","Abdominal wound","Surgical wound dehiscence"],"a":1,"e":"Answer- B. Large amount of necrotic tissue with eschar Negative-pressure wound therapy (NPWT), also known as a vacuum dressing or V.A.C. dressing (\"vacuum assisted closure\"), is a therapeutic technique using a suction dressing to remove excess exudation and promote healing in acute or chronic wounds and second- and third-degree burns. Contraindications for NPWT use","pyqMatches":[{"year":"2015","no":1282,"q":"Vacuum assisted closure is contraindicated in which of the following conditions","o":["Chronic osteomyelitis","Large amount of necrotic tissue with eschar","Abdominal wound","Surgical wound dehiscence"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9343, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 457, '{"id":9343,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":457,"q":"All of the following are causes of Urothelial Carcinomas Except -","o":["Smoking","Industrial solvents","Exposure to thorotrast","Alcohol consumption"],"a":3,"e":"Answer- D. Alcohol consumption Industrial dyes or solvents Excessive analgesic intake, Balkan nephropathy, and Those exposed to Thorotrast, (a contrast agent previously used for retrograde pyelography","pyqMatches":[{"year":"2015","no":1300,"q":"All of the following are causes of Urothelial Carcinomas Except","o":["Smoking","Industrial solvents","Exposure to thorotrast","Alcohol consumption"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9344, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 458, '{"id":9344,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":458,"q":"Most common site for Cystic Hygroma is -","o":["Lower third of neck","Overlying the parotid gland","Along the Zygomatic Prominence","Post auricular"],"a":0,"e":"Answer- A. Lower third of the neck Most cystic hygromas involve the lymphatic jugular sacs and present in the posterior neck region. The other common sites are the axillary, mediastinum, inguinal, and retroperitoneal regions, and approximately 50% of them present at birth. Cystic hygromas usually present as soft cystic masses that distort the surrounding anatomy, including the airway, which can result in acute airway obstruction.","pyqMatches":[{"year":"2015","no":1284,"q":"Most common site for Cystic Hygroma is","o":["Lower third of neck","Overlying the parotid gland","Along the Zygomatic Prominence","Post auricular"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9345, 'Surgery', 'Vascular Surgery', 'Moderate', 'Surgery', 459, '{"id":9345,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":459,"q":"The size beyond which the risk of rupture of an abdominal aneurysm significantly increases is greater than -","o":["5.5 cm","6 cm","6.5 cm","7 cm"],"a":0,"e":"Answer- A. 5.5 cm High risk AAA Endovascular aneurysmal repair (EVAR) AAA repair- ≥5.5 cm/ >5cm females Symptomatic aneurysm","pyqMatches":[{"year":"2015","no":1285,"q":"The size beyond which the risk of rupture of an abdominal aneurysm significantly increases is greater than","o":["5.5 cm","6 cm","6.5 cm","7 cm"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9346, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 460, '{"id":9346,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":460,"q":"True about MALToma is","o":["They are secondary gastric lymphomas","H. Pylori infection is a risk factor","Commonly seen in gastric cardia","They are a type of T cell lymphoma"],"a":1,"e":"Answer- B. H. Pylori infection is a risk factor Stomach is the most common extranodal site of lymphoma. It is of two types - Primary & Secondary Most of the primary lymphomas (about 60%) arise in MALT (mucosa associated lymphoid tissue). MALT is usually associated with chronic H. pylori infection. So low-grade MALT lymphomas are thought to arise because of chronic H. pylori infection. These low grade lymphomas may later on degenerate to high grade lymphomas. mucosa associated lymphoid tissue. It is usually primary GI lymphoma (4% of gastric lymphoma); of non-Hodgkin’s B cell type.","pyqMatches":[{"year":"2015","no":1296,"q":"True about MALToma is","o":["They are secondary gastric lymphomas","H. Pylori infection is a risk factor","Commonly seen in gastric cardia","They are a type of T cell lymphoma"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9347, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 461, '{"id":9347,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":461,"q":"A cystic mass at the base of umbilical cord in a neonate could be","o":["Allantoic Cyst","Meckel''s Diverticulum","Ventral mesogastrium","Cystic Hygroma"],"a":0,"e":"Answer- A. Allantoic Cyst Allantoic cysts are a type of true cyst of the umbilical cord. The allantois forms from the part of the fetal yolk sac that eventually becomes the primitive hindgut (the cloaca). The cloaca divides into the hindgut posteriorly and the urogenital sinus anteriorly.","pyqMatches":[{"year":"2015","no":1295,"q":"A cystic mass at the base of umbilical cord in a neonate could be","o":["Allantoic Cyst","Meckel''s Diverticulum","Ventral mesogastrium","Cystic Hygroma"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9348, 'Surgery', 'Endocrine Surgery', 'Easy', 'Surgery', 462, '{"id":9348,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Easy","source":"Surgery","sourceNo":462,"q":"Chvostek sign could be seen after -","o":["Gastrojejunostomy","Total thyroidectomy","Subtotal Thyroidectomy","Hellers Cardiomyotomy"],"a":1,"e":"Answer- B. Total thyroidectomy Chvostek''s sign refers to the contraction of the ipsilateral facial muscles on percussion of the facial nerve below the zygoma. It is due to hypocalcemia and one common cause of hypocalcemia is a complication during thyroidectomies. The parathyroid gland produces a parathyroid hormone (PTH), and resection can lead to a decrease in PTH levels. PTH regulates calcium levels in the body; hence, a reduction in its serum level will lead to hypocalcemia. So, among the most common postoperative complications following thyroid surgery is hypocalcemia.","pyqMatches":[{"year":"2015","no":1286,"q":"Chvostek sign could be seen after","o":["Gastrojejunostomy","Total thyroidectomy","Subtotal Thyroidectomy","Hellers Cardiomyotomy"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9349, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 463, '{"id":9349,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":463,"q":"An Incisional wound heals by","o":["Primary Healing","Secondary Healing","Delayed primary Healing","Reepithelization"],"a":0,"e":"Answer- A. Primary Healing Primary Healing Primary wound healing or healing by first intention occurs within hours of repairing a full-thickness surgical incision. This surgical insult results in the mortality of a minimal number of cellular constituents.","pyqMatches":[{"year":"2015","no":1294,"q":"An Incisional wound heals by","o":["Primary Healing","Secondary Healing","Delayed primary Healing","Reepithelization"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9350, 'Surgery', 'General Principles & Wounds', 'Moderate', 'Surgery', 464, '{"id":9350,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Moderate","source":"Surgery","sourceNo":464,"q":"A full thickness wound that is not sutured heals by","o":["Primary Healing","Secondary Healing","Delayed primary Healing","Reepithelization"],"a":1,"e":"Answer- B. Secondary Healing Secondary Healing A third type of healing is known as secondary healing or healing by secondary intention. In this type of healing, a full-thickness wound is allowed to close and heal. Secondary healing results in an inflammatory response that is more intense than with primary wound healing. In addition, a larger quantity of granulomatous tissue is fabricated because of the need for wound closure. Secondary healing results in pronounced contraction of wounds.","pyqMatches":[{"year":"2015","no":1293,"q":"A full thickness wound that is not sutured heals by","o":["Primary Healing","Secondary Healing","Delayed primary Healing","Reepithelization"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9351, 'Surgery', 'Vascular Surgery', 'Moderate', 'Surgery', 465, '{"id":9351,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":465,"q":"Food can commonly get obstructed in the esophagus at all of the following locations except","o":["Crossing of left bronchus","Crossing of arch of aorta","Diagphragmatic aperture","Crossing of the hemiazygous vein"],"a":3,"e":"Answer- D. Crossing of the hemiazygous vein Pharyngoesophagal junction -6 inches 9","pyqMatches":[{"year":"2015","no":1292,"q":"Food can commonly get obstructed in the esophagus at all of the following locations except","o":["Crossing of left bronchus","Crossing of arch of aorta","Diagphragmatic aperture","Crossing of the hemiazygous vein"],"a":3,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9352, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 466, '{"id":9352,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":466,"q":"Reactionary Hemorrhage occurs due to -","o":["Dislodgement of clot","Infection","Damage to a blood vessel","Pressure necrosis"],"a":0,"e":"Answer- A. Dislodgement of clot Dislodgement of clot Ligature slip Noramlisation of BP and vasodilation","pyqMatches":[{"year":"2015","no":1287,"q":"Reactionary Hemorrhage occurs due to","o":["Dislodgement of clot","Infection","Damage to a blood vessel","Pressure necrosis"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9353, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 467, '{"id":9353,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":467,"q":"All of the following is true about congenital hypertrophic pyloric stenosis except","o":["RamStedt Pyloromyotomy is the treatment of choice","Non Bilious vomiting is seen","Metabolic acidosis occurs","More common in males"],"a":2,"e":"Answer- C. Metabolic acidosis occurs Characterstically the first born male child is affected. The conditon is most commonly seen at 4 weeks after birth ranging from the 3rd week to on rare occasion Non-bilious vomiting, becoming increasingly projectile, occurs over several days to weeks Infants develop a metabolic alkalosis with severe depletion of potassium and chloride ions. Treatment- Surgery : Fredet-Ramstedt pyloromyotomy. (In it the pyloric mass is split without cutting the mucosa)","pyqMatches":[{"year":"2015","no":1291,"q":"All of the following is true about congenital hypertrophic pyloric stenosis except","o":["RamStedt Pyloromyotomy is the treatment of choice","Non Bilious vomiting is seen","Metabolic acidosis occurs","More common in males"],"a":2,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9354, 'Surgery', 'General Principles & Wounds', 'Hard', 'Surgery', 468, '{"id":9354,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Hard","source":"Surgery","sourceNo":468,"q":"Which of the following is correct management of abdominal compartment syndrome","o":["Antihypertensives","Urgent Opening of the surgical wound and application of the Bogota bag","Urgent Fasciotomy","Wait and monitor for 24 hours"],"a":1,"e":"Answer- B. Urgent Opening of the surgical wound and application of the Bogota bag Abdominal compartment syndrome is a surgical emergency and treatment includes rapid decompression of the elevated intraabdominal pressure by opening the abdominal wound and performing a temporary closure of the abdominal wall with mesh or a plastic bag. Permanent closure is done 5 to 7 days later when the condition resolves.","pyqMatches":[{"year":"2015","no":1290,"q":"Which of the following is correct management of abdominal compartment syndrome","o":["Antihypertensives","Urgent Opening of the surgical wound and application of the Bogota bag","Urgent Fasciotomy","Wait and monitor for 24 hours"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9355, 'Surgery', 'Urology', 'Easy', 'Surgery', 469, '{"id":9355,"subject":"Surgery","chapter":"Urology","difficulty":"Easy","source":"Surgery","sourceNo":469,"q":"Transplanted kidney is relocated to which region in the recepient''s body ?","o":["Retroperitoneal rgion","Lumbar region","Epigastrium","Beside the dysfunctional Kidney"],"a":0,"e":"Answer- A. Retroperitoneal rgion The most common location for placing a kidney transplant is in retroperitoneal iliac fossai. In most cases Kidney is placed retroperitoneally and the iliac arteries and veins are used for perfusion and ureter is transplanted directly into bladder.","pyqMatches":[{"year":"2015","no":1288,"q":"Transplanted kidney is relocated to which region in the recepient''s body ?","o":["Retroperitoneal rgion","Lumbar region","Epigastrium","Beside the dysfunctional Kidney"],"a":0,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9356, 'Surgery', 'Vascular Surgery', 'Easy', 'Surgery', 470, '{"id":9356,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Easy","source":"Surgery","sourceNo":470,"q":"Claudication due to popliteofemoral incompetence is primary seen in","o":["Thigh","Calf","Buttocks","Feet"],"a":1,"e":"Answer- B. Calf Aorta and Common Iliac- Buttocks Femoral Artery- Thigh Superficial femoral artery- Calf and popliteal artery Posterior tibial Artery- Feet","pyqMatches":[{"year":"2015","no":1289,"q":"Claudication due to popliteofemoral incompetence is primary seen in","o":["Thigh","Calf","Buttocks","Feet"],"a":1,"source":"NEET_2015_Paper.pdf"}],"pyqYears":["2015"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9357, 'Surgery', 'Hepatobiliary & Pancreas', 'Easy', 'Surgery', 471, '{"id":9357,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Easy","source":"Surgery","sourceNo":471,"q":"Balthazar scoring system is used for?","o":["Acute Pancreatitis","Acute Appendicitis","Acute cholecystitis","Cholangitis"],"a":0,"e":"Answer- A. Acute Pancreatitis Balthazar score is used in the CT severity index (CTSI) for grading of acute pancreatitis which has two components. Using imaging characteristics, Balthazar and associates have established the CT severity index. This index correlates CT findings with the patient’s outcome 1) Grading of pancreatitis A: Normal pancreas → 0 B: Enlargement of pancreas → 1 C: Inflammatory changes → 2 D: Ill-defined single fluid collection -4 3 E: Two or more ill-defined fluid collections → 4 2) Pancreatic necrosis None → 0 30% → 2 > 30 - 50% 4 > 50% → 6","pyqMatches":[{"year":"2013","no":1338,"q":"Balthazar scoring system is used for?","o":["Acute Pancreatitis","Acute Appendicitis","Acute cholecystitis","Cholangitis"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9358, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 472, '{"id":9358,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":472,"q":"Triage system used for","o":["Burn","Earthquack","Polytrauma","Floods"],"a":2,"e":"Answer- C. Polytrauma The usual principle of first come, first treated\", is not followed in mass emergencies. Triage consists of rapidly classifying the injured and the likelyhood of their survival with prompt medical intervention. Higher priority is granted to victims whose immediate or long-term prognosis can be dramatically affected by simple intensive care.","pyqMatches":[{"year":"2013","no":1339,"q":"Triage system used for","o":["Burn","Earthquack","Polytrauma","Floods"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9359, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 473, '{"id":9359,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":473,"q":"Ileal obstruction due to round worm obstruction treatment is","o":["Resection with end to end anastomosis","Resection with side to side anastomosis","Enterotomy, removal of worms and primary closure","Diversion"],"a":2,"e":"Answer- C. Enterotomy, removal of worms and primary closure Diversion is the first step in case of colonic obstruction, followed by resection and anastomosis of affected segment and then closure of diversion colostomy at a later date. Intestinal luminal obstruction such as due to Bezoars or fecoliths of worm intestations are dealt with by enterotomy and removal followed by primary closure.","pyqMatches":[{"year":"2013","no":1340,"q":"Ileal obstruction due to round worm obstruction treatment is","o":["Resection with end to end anastomosis","Resection with side to side anastomosis","Enterotomy, removal of worms and primary closure","Diversion"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9360, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 474, '{"id":9360,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":474,"q":"Surgery for perforation due to round worm is","o":["Resection with end to end anastomosis","Resection with side to side anastomosis","Primary closure","Diversion"],"a":0,"e":"Answer- A. Resection with end to end anastomosis","pyqMatches":[{"year":"2013","no":1341,"q":"Surgery for perforation due to round worm is","o":["Resection with end to end anastomosis","Resection with side to side anastomosis","Primary closure","Diversion"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9361, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 475, '{"id":9361,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":475,"q":"Which is a clean surgery","o":["Hernia surgery","Gastric surgeru","Cholecystectomy","Rectal surgery"],"a":0,"e":"Answer- A. Hernia surgery Clean Wound (Class I) Include those in which no infection is present; only skin microflora potentially contaminate the wound. No hollow viscus is entered. No inflammation Examples : Hernia repair, breast biopsy","pyqMatches":[{"year":"2013","no":1342,"q":"Which is a clean surgery","o":["Hernia surgery","Gastric surgeru","Cholecystectomy","Rectal surgery"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9362, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 476, '{"id":9362,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":476,"q":"Steroid is injurious to wound when given","o":["On 1st day","< 2weeks","2-4 weeks","> 4 weeks"],"a":1,"e":"Answer- B. < 2weeks Steroids used after first 3 to 4 days post injury do not affect wound healing as severly as when used in immediate post operative period. Delay in use of such drugs for about 2 weeks post injury appears to lesser the wound healing impairment.","pyqMatches":[{"year":"2013","no":1345,"q":"Steroid is injurious to wound when given","o":["On 1st day","< 2weeks","2-4 weeks","> 4 weeks"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9363, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 477, '{"id":9363,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":477,"q":"In surgical patient malnutrition is best assessed by","o":["Serum albumin","Hb level","Mid arm circumference","Tricpes skin fold thickness"],"a":0,"e":"Answer- A. Serum albumin Serum albumin is classic method to predict postoperative complications, hospital length of stay, morbidity and mortality and might to be associate to nurtitional status and disease severity.","pyqMatches":[{"year":"2013","no":1346,"q":"In surgical patient malnutrition is best assessed by","o":["Serum albumin","Hb level","Mid arm circumference","Tricpes skin fold thickness"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9364, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 478, '{"id":9364,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":478,"q":"Abbes flap is used for","o":["Eyelid","Tongue","Lip","Ear"],"a":2,"e":"Answer- C. Lip Abbe flap, also called lip switch flap, is used for lip reconstruction.","pyqMatches":[{"year":"2013","no":1349,"q":"Abbes flap is used for","o":["Eyelid","Tongue","Lip","Ear"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9365, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 479, '{"id":9365,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":479,"q":"In LAHSHAL terminology for cleft lip & cleft palate, LAHSHAL denotes","o":["Bilateral cleft palate only","Bilateral cleft lip only","Bilateral cleft lip & palate","No cleft"],"a":2,"e":"Answer- C. Bilateral cleft lip & palate LAHSHAL classification of cleft lip and palate was proposed by Kreins 0. It is a diagrammatic classification of cleft cip & palate. According to this classification, mouth is divided into six parts. LAHSAL code indicates complete cleft with and incomp ete cleft with small latter.","pyqMatches":[{"year":"2013","no":1350,"q":"In LAHSHAL terminology for cleft lip & cleft palate, LAHSHAL denotes","o":["Bilateral cleft palate only","Bilateral cleft lip only","Bilateral cleft lip & palate","No cleft"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9366, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 480, '{"id":9366,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":480,"q":"Post operative abscess treatment of choice","o":["Hydration","IV antibiotics","Image guided aspiration","Reexploration"],"a":2,"e":"Answer- C. Image guided aspiration The diagnosis and treatment of intraabdominal abscesses have improved with the advent of imaging techniques such as ultrasonography acd CT. These advances have made minimally invassive drainage techniques available; such techniques complement traditional surgical drainage for patients with abdominal abscess cavities.","pyqMatches":[{"year":"2013","no":1351,"q":"Post operative abscess treatment of choice","o":["Hydration","IV antibiotics","Image guided aspiration","Reexploration"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9367, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 481, '{"id":9367,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":481,"q":"May thurner or cockett syndrome involves","o":["Common iliac artery obstruction","Internal iliac artery obstruction","Internal iliac vein obstruction","Left iliac vein compression"],"a":3,"e":"Answer- D. Left iliac vein compression May-Thurner syndrome/cockett syndrome/iliocaval/iliac vein compression syndrome. Occurs due to compression of left iliac vein by overriding right iliac artery. It results in left iliofemoral deep vein thrombosis.","pyqMatches":[{"year":"2013","no":1352,"q":"May thurner or cockett syndrome involves","o":["Common iliac artery obstruction","Internal iliac artery obstruction","Internal iliac vein obstruction","Left iliac vein compression"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9368, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 482, '{"id":9368,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":482,"q":"Method of reduction of inguinal hernia","o":["Kugel maneuvve","Taxis","Macvay proceedure","Stopa''s technique"],"a":1,"e":"Answer- B. Taxis Taxis (hernia reduction) was the treatment of choice for in carcirated hernia. Manual reduction of hernia is known as taxis. Taxis is an archaic term used to describe an attempt at reduction of a hernia that is acutely irreducible (incarcirated).","pyqMatches":[{"year":"2013","no":1353,"q":"Method of reduction of inguinal hernia","o":["Kugel maneuvve","Taxis","Macvay proceedure","Stopa''s technique"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9369, 'Surgery', 'Vascular Surgery', 'Easy', 'Surgery', 483, '{"id":9369,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Easy","source":"Surgery","sourceNo":483,"q":"Subclavian steal syndrome is","o":["Reversal of blood flow in the ipsilateral vertebral artery","Reversal of blood flow in the contralateral carotid artery","Reversal of blood flow in the contralateral vertebral artery","B/L reversal of blood flow in vertebral arteries"],"a":0,"e":"Answer- A. Reversal of blood flow in the ipsilateral vertebral artery Subclavian steal syndrome may occur if the first part of the subclavian artery is occluded. Arm exercise causes syncope because of reversed flow, in the vertebral artery leading to cerebral ischemia. It can be treated by angioplasty or surgery and is rare. That is the result of an ipsilateral hemodynamically significant lesion of the proximal subclavian artery.","pyqMatches":[{"year":"2013","no":1355,"q":"Subclavian steal syndrome is","o":["Reversal of blood flow in the ipsilateral vertebral artery","Reversal of blood flow in the contralateral carotid artery","Reversal of blood flow in the contralateral vertebral artery","B/L reversal of blood flow in vertebral arteries"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9370, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 484, '{"id":9370,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":484,"q":"Most common cause of acquired AV fistula is","o":["Bacterial infection","Fungal infection","Blunt trauma","Penetrating trauma"],"a":3,"e":"Answer- D. Penetrating trauma \"Penetrating injuries are the most common cause, but fistulas are sometimes seen after blunt trauma\" – CSDT","pyqMatches":[{"year":"2013","no":1356,"q":"Most common cause of acquired AV fistula is","o":["Bacterial infection","Fungal infection","Blunt trauma","Penetrating trauma"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9371, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 485, '{"id":9371,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":485,"q":"Best approach in thoracic trauma is","o":["Midline sternotomy","Parasternal thoracotomy","Anterolateral thoracotomy","Posterolateral thoracotomy"],"a":2,"e":"Answer- C. Anterolateral thoracotomy left'' anterolateral thoracotomy is the best initial operative approach for unstable patients requiring resuscitation or when the location of the intrathoracic injury is unclear.","pyqMatches":[{"year":"2013","no":1358,"q":"Best approach in thoracic trauma is","o":["Midline sternotomy","Parasternal thoracotomy","Anterolateral thoracotomy","Posterolateral thoracotomy"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9372, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 486, '{"id":9372,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":486,"q":"Venous air embolism is most common in which position in surgery","o":["Sitting","Prone","Lateral","Lithotomy"],"a":0,"e":"Answer- A. Sitting Venous air embolism is a potential hazard whenever the operative site is above the level of patients heart. The ''sitting'' position and its modification \"beach chair\" positions are associated with a greater incidence of venous air embolism","pyqMatches":[{"year":"2013","no":1359,"q":"Venous air embolism is most common in which position in surgery","o":["Sitting","Prone","Lateral","Lithotomy"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9373, 'Surgery', 'Vascular Surgery', 'Easy', 'Surgery', 487, '{"id":9373,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Easy","source":"Surgery","sourceNo":487,"q":"Fatal exsanguinations occurs mostly in","o":["Closed fracture of femur shaft","Open fracture of femur & tibia","Partial transaction of artery","Complete resection transaction of artery"],"a":2,"e":"Answer- C. Partial transaction of artery \"Bleeding is more often exsanguinating after sharp injury and partial vessel transection\".","pyqMatches":[{"year":"2013","no":1361,"q":"Fatal exsanguinations occurs mostly in","o":["Closed fracture of femur shaft","Open fracture of femur & tibia","Partial transaction of artery","Complete resection transaction of artery"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9374, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 488, '{"id":9374,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":488,"q":"Premalignant lesion for carcinoma rectum is","o":["Familial polyposis","FAP","Juvenile polyp","Adenomatous polyp"],"a":0,"e":"Answer- A. Familial polyposis Pre cancerous lesions for CA rectum","pyqMatches":[{"year":"2013","no":1363,"q":"Premalignant lesion for carcinoma rectum is","o":["Familial polyposis","FAP","Juvenile polyp","Adenomatous polyp"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9375, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 489, '{"id":9375,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":489,"q":"Most common site for anal fissure is","o":["3 O''clock","6 O''clock","2 O''clock","10 O''clock"],"a":1,"e":"Answer- B. 6 O''clock The vest majority of anal fissures occur in posterior midline. Fissure in Ano (or Anal fissure) Most common site is → mid-line posterioly MC symptom is -4 pain associated with defecation Fissure starts proximally at the dentate line","pyqMatches":[{"year":"2013","no":1364,"q":"Most common site for anal fissure is","o":["3 O''clock","6 O''clock","2 O''clock","10 O''clock"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9376, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 490, '{"id":9376,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":490,"q":"Alvarado score consist of","o":["Leucopenia","Anorexia","Diarrhea","Periumbilical pain"],"a":1,"e":"Answer- B. Anorexia The most widely used is the Alvarado score. A score of 7 or more is strongly predictive of acute appendicitis. Alvarado score Symptoms Score Migration of pain 1 Anorexia 1 Nausea & vomiting 1 Signs Tenderness in the right lower quadrant 2 Rebound tenderness 1 Elevated temperature 1 Laboratory Leucocytosis 2 A shift of white blood cell count to the left1 Total 10","pyqMatches":[{"year":"2013","no":1366,"q":"Alvarado score consist of","o":["Leucopenia","Anorexia","Diarrhea","Periumbilical pain"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9377, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 491, '{"id":9377,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":491,"q":"Most common age for intussusception is","o":["0-6 Months","6 Months -3yrs","3-5 Yrs","> 5 yrs"],"a":1,"e":"Answer- B. 6 Months -3yrs Intussusception is the telescoping of one portion of the intestine into the other. It is the most common cause of intestinal obstruction in early childhood (3 months to 6 years)","pyqMatches":[{"year":"2013","no":1367,"q":"Most common age for intussusception is","o":["0-6 Months","6 Months -3yrs","3-5 Yrs","> 5 yrs"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9378, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 492, '{"id":9378,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":492,"q":"Retrocardiac lucency with air fluid level is seen in","o":["Hiatus hernia","Distal end esophageal obstruction","Eventration of diaphragm","None"],"a":0,"e":"Answer- A. Hiatus hernia Hiatus hernia shows retrocardic lucency with air or an air-fluid level above the diaphragm.","pyqMatches":[{"year":"2013","no":1368,"q":"Retrocardiac lucency with air fluid level is seen in","o":["Hiatus hernia","Distal end esophageal obstruction","Eventration of diaphragm","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9379, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 493, '{"id":9379,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":493,"q":"Most common site for carcinoid tumor is","o":["Esophagus","Lung","Appendix","Ileum"],"a":3,"e":"Answer- D Historically, the most common site of gastrointestinal (GI) carcinoid tumors was the appendix. Currently, however, the most common site of carcinoids in the GI tract is the small intestine (30%), followed by the rectum (19.6%). In most studies, the appendix is only the third most common site of GI carcinoids, and in some studies, it is the fourth most common.","pyqMatches":[{"year":"2013","no":1369,"q":"Most common site for carcinoid tumor is","o":["Esophagus","Lung","Appendix","Ileum"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9380, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 494, '{"id":9380,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":494,"q":"Most common differential diagnosis for appendicitis in children is","o":["Gastroenteritis","Mesentric lymphadenopathy","Intussusception","Meckel''s diverticulitis"],"a":1,"e":"Answer- B. Mesentric lymphadenopathy Differential diagnosis of appendicitis in children -","pyqMatches":[{"year":"2013","no":1370,"q":"Most common differential diagnosis for appendicitis in children is","o":["Gastroenteritis","Mesentric lymphadenopathy","Intussusception","Meckel''s diverticulitis"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9381, 'Surgery', 'Hepatobiliary & Pancreas', 'Hard', 'Surgery', 495, '{"id":9381,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Hard","source":"Surgery","sourceNo":495,"q":"Abdominal surgery under LA, patient suddenly felt pain due to","o":["Liver","Gut","Parietal peritoneum","Visceral peritoneum"],"a":2,"e":"Answer- C. Parietal peritoneum Embryologically parietal peritoneum is derived from the somatopleural layer of the lateral plate mesoderm. Its blood supply and nerve supply are the same as those of the overlying body wall. Because of the somatic innervation, it is pain sensitive.\" — BDC Anatomy","pyqMatches":[{"year":"2013","no":1371,"q":"Abdominal surgery under LA, patient suddenly felt pain due to","o":["Liver","Gut","Parietal peritoneum","Visceral peritoneum"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9382, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 496, '{"id":9382,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":496,"q":"A 55 year male has history of dysphagia with vomiting of undigested food throughout the day, weight loss, emaciated & dehydrated. No mass palpable per abdomen. The modality of treatment is","o":["IV total parenteral nutrition","Endoscopic dilation","IV normal saline","pH monitoring"],"a":1,"e":"Answer- B. Endoscopic dilation The symptom & sign complex indicates diagnosis of Achalasia. One of the treatment modalities for achalasia cardia is endoscopic dilation.","pyqMatches":[{"year":"2013","no":1373,"q":"A 55 year male has history of dysphagia with vomiting of undigested food throughout the day, weight loss, emaciated & dehydrated. No mass palpable per abdomen. The modality of treatment is","o":["IV total parenteral nutrition","Endoscopic dilation","IV normal saline","pH monitoring"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9383, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 497, '{"id":9383,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":497,"q":"Hose pipe appearance of intestine is a feature of","o":["Crohns disease","Malabsorption syndrome","Ulcerative colitis","Hirsprung disease"],"a":0,"e":"Answer- A. Crohns disease Crohn''s disease has a hose pipe appearance.","pyqMatches":[{"year":"2013","no":1374,"q":"Hose pipe appearance of intestine is a feature of","o":["Crohns disease","Malabsorption syndrome","Ulcerative colitis","Hirsprung disease"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9384, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 498, '{"id":9384,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":498,"q":"In old age for rectal prolapse palliative surgery in a patient unfit for surgery is","o":["Delorme''s procedure","Well''s procedure","Thiersch''s operation","Low anterior resection"],"a":2,"e":"Answer- C. Thiersch''s operation Tightening the anus with a variety of prosthetic materials (anal encirclement)- Anal encirclement procedures generally have been abandoned. Anal encirlement has limited application and is reserved by most surgeons for patients of the highest surgical risk or limited life expectancy because it can be done under local anesthesia. The original Thiersch procedure involved placing a silver wire around the external sphincter within the ishiorectal fat. Now synthetic mesh or silicone tubes are used instead of wire. The safety of current anesthetic techniques and the low morbidity and relative functional success of perineal proctectomy have made anal encirclement, for the most part, a procedure of the past.","pyqMatches":[{"year":"2013","no":1375,"q":"In old age for rectal prolapse palliative surgery in a patient unfit for surgery is","o":["Delorme''s procedure","Well''s procedure","Thiersch''s operation","Low anterior resection"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9385, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 499, '{"id":9385,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":499,"q":"40 year old male complaints of GERD, on endoscopy shows dysplasia. Treatment","o":["Fundoplication","Esophageal resection","PPI","Dietmodification"],"a":1,"e":"Answer- B. Esophageal resection If severe dysplasia or intranural carcinoma is found on mucosal biopsy, an esophageal resection should be done.","pyqMatches":[{"year":"2013","no":1376,"q":"40 year old male complaints of GERD, on endoscopy shows dysplasia. Treatment","o":["Fundoplication","Esophageal resection","PPI","Dietmodification"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9386, 'Surgery', 'Urology', 'Easy', 'Surgery', 500, '{"id":9386,"subject":"Surgery","chapter":"Urology","difficulty":"Easy","source":"Surgery","sourceNo":500,"q":"Renal stones which are laminated and irregular in outline are","o":["Uric acid","Calcium oxalate","Struvite","Cystine"],"a":1,"e":"Answer- B. Calcium oxalate Calcium oxalate stones - Usually single, hard (aka Mulberry stone) - Dark colored d/t staining with altered blood. Spiky. On section Wavy concentric laminae. There may be secondary phosphate deposit on surface. High calcium content.","pyqMatches":[{"year":"2013","no":1377,"q":"Renal stones which are laminated and irregular in outline are","o":["Uric acid","Calcium oxalate","Struvite","Cystine"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9387, 'Surgery', 'Gastrointestinal Surgery', 'Hard', 'Surgery', 501, '{"id":9387,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Hard","source":"Surgery","sourceNo":501,"q":"In a case of perforation peritonitis, emergency lapratomy, 2nd post operative day develops oliguria. Diagnosis","o":["Severe UTI","Fluid retention","Dehydration","Catheter obstruction"],"a":2,"e":"Answer- C. Dehydration Oliguria may reflect inadequate renal artery perfusion due to hypotension, hypovolemia or low QT. It can also be a sign of intrinsic renal dysfunction.","pyqMatches":[{"year":"2013","no":1380,"q":"In a case of perforation peritonitis, emergency lapratomy, 2nd post operative day develops oliguria. Diagnosis","o":["Severe UTI","Fluid retention","Dehydration","Catheter obstruction"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9388, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 502, '{"id":9388,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":502,"q":"Etiology of bloody discharge from nipple","o":["Duct papiloma","Breast abscess","Fibroadenoma","Cyst"],"a":0,"e":"Answer- A. Duct papiloma Table 1: Causes of nipple discharge Physiologic Duct abnormalities Intraductal papilloma Duct ectasia Periductal mastitis Carcinoma Galactorrhea Hyperprolactinemia Hypothyroidism Medications: oral contraceptives, cimetidine, verapamil, phenothiazine, metoclopramide, alpha-methyldopa Conditions that may mimc nipple discharge Eczema with drainage Paget''s disease of the breast Nipple adenoma","pyqMatches":[{"year":"2013","no":1381,"q":"Etiology of bloody discharge from nipple","o":["Duct papiloma","Breast abscess","Fibroadenoma","Cyst"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9389, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 503, '{"id":9389,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":503,"q":"Carcinoma breast is least seen in","o":["Superior outer quadrant","Inferior outer quadrant","Subareolar","Lower inner quadrant"],"a":3,"e":"Answer- D. Lower inner quadrant Upper inner -+ 12 - 15% Upper outer → = 50% Lower inner → 3 - 5% Lower outer → 6 - 10% Central/areolar → 20% [Ref Love & Bailey 25th/e p. 840, S. Das 7thie p. 607]","pyqMatches":[{"year":"2013","no":1382,"q":"Carcinoma breast is least seen in","o":["Superior outer quadrant","Inferior outer quadrant","Subareolar","Lower inner quadrant"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9390, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 504, '{"id":9390,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":504,"q":"Intraoperative sentinel lymph node detection in axilla is done by using","o":["Mammography","Isosulfan blue dye","MRI","CT"],"a":1,"e":"Answer- B. Isosulfan blue dye Lymphatic mapping is performed by using isosulfan blue dye, technetium-labelled sulfur colloid albumin or a combination of both.","pyqMatches":[{"year":"2013","no":1384,"q":"Intraoperative sentinel lymph node detection in axilla is done by using","o":["Mammography","Isosulfan blue dye","MRI","CT"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9391, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 505, '{"id":9391,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":505,"q":"Sentinel lymph node biopsy in carcinoma breast is done if -","o":["LN palpable","Breast mass but no lymph node palpable","Breast lump with palpable axillary node","Metastatic CA breast"],"a":1,"e":"Answer- B. Breast mass but no lymph node palpable Axillary nodes if clinically palpable are removed by surgical dissection.","pyqMatches":[{"year":"2013","no":1385,"q":"Sentinel lymph node biopsy in carcinoma breast is done if","o":["LN palpable","Breast mass but no lymph node palpable","Breast lump with palpable axillary node","Metastatic CA breast"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9392, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 506, '{"id":9392,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":506,"q":"Indication for sentinel node biopsy is","o":["Non palpable axillary lymph node","Palpable axillary lymph node","Mass > 5cm","Metastasis"],"a":0,"e":"Answer- A. Non palpable axillary lymph node This will be of great significance in early breast carcinomas wherein lymph nodes are not clinically palpable nor detected by investigations such as ultrasound/CT scan of the axilla. . Indication: Early breast cancer with (T1 or T2 No) clinically node negative axilla.","pyqMatches":[{"year":"2013","no":1386,"q":"Indication for sentinel node biopsy is","o":["Non palpable axillary lymph node","Palpable axillary lymph node","Mass > 5cm","Metastasis"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9393, 'Surgery', 'Breast Surgery', 'Moderate', 'Surgery', 507, '{"id":9393,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":507,"q":"Breast conservation surgery is contraindicated in all except -","o":["Tumor> 4cm","Multicentric tumor","Axillary LN involvement","Diffuse microcalcifications"],"a":3,"e":"Answer- D Breast conservative surgery Indications Lump < 4 cm Clinically negative axillary nodes Mammographically detected lesion Well-differentiated tumour with low S phase Adequate sized breast to allow proper RT to breast Breast of adequate size and volume Feasibility of axillary dissection and radiotherapy to intact breast Contraindications Tumour > 4 cm Plositive axillary nodes > N1 Tumour margin is not free of tumour after breast conservative surgery needs MRM Poorly differentiated tumour Multicentric tumour Earlier breast irradiation Tumour/breast size ratio is more (centeral tumour) Tumour beneath the nipple Extensive intraductal carcinoma","pyqMatches":[{"year":"2013","no":1387,"q":"Breast conservation surgery is contraindicated in all except","o":["Tumor> 4cm","Multicentric tumor","Axillary LN involvement","Diffuse microcalcifications"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9394, 'Surgery', 'Breast Surgery', 'Moderate', 'Surgery', 508, '{"id":9394,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":508,"q":"The following are suitable for simple mastectomy except-","o":["Pagets disease","Fibroadenoma","Cystosarcoma phyllodes","None"],"a":1,"e":"Answer- B. Fibroadenoma Indications for simple mastectomy A) Without an axillary procedure","pyqMatches":[{"year":"2013","no":1388,"q":"The following are suitable for simple mastectomy except","o":["Pagets disease","Fibroadenoma","Cystosarcoma phyllodes","None"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9395, 'Surgery', 'Endocrine Surgery', 'Easy', 'Surgery', 509, '{"id":9395,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Easy","source":"Surgery","sourceNo":509,"q":"Which of the following is used in the treatment of well differentiated thyroid carcinoma","o":["I131","99m Tc","32p","MIBG"],"a":0,"e":"Answer- A. I131 I131 is the radioisotope of choice for radiotherapy of thyroid carcinoma and hyperparathyroidism.","pyqMatches":[{"year":"2013","no":1390,"q":"Which of the following is used in the treatment of well differentiated thyroid carcinoma","o":["I131","99m Tc","32p","MIBG"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9396, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 510, '{"id":9396,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":510,"q":"Treatment for malignant melanoma is","o":["Wide excision","Radiotherapy","Excision","Chemotherapy"],"a":0,"e":"Answer- A. Wide excision Management of Malignant Melanoma Wide local excision of the primary tumor is the management of choice. The recommended margin of resection depends on the thickness of the tumor.","pyqMatches":[{"year":"2013","no":1392,"q":"Treatment for malignant melanoma is","o":["Wide excision","Radiotherapy","Excision","Chemotherapy"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9397, 'Surgery', 'Vascular Surgery', 'Easy', 'Surgery', 511, '{"id":9397,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Easy","source":"Surgery","sourceNo":511,"q":"Moures sign is seen in","o":["Carcinoma","Appendicitis","Varicose vein","Pancreatitis"],"a":0,"e":"Answer- A. Carcinoma \"In normal persons, a click is felt when larynx is moved from side to side over vertebral column, this is called laryngeal click (post cricoid crepitus) It is absent in post cricoid carcinoma\". — Moure''s sign","pyqMatches":[{"year":"2013","no":1393,"q":"Moures sign is seen in","o":["Carcinoma","Appendicitis","Varicose vein","Pancreatitis"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9398, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 512, '{"id":9398,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":512,"q":"Acute orchitis all are seen except","o":["Increased local temprature","Decreased blood flow","Etythematous scrotum","Raised TLC"],"a":1,"e":"Answer- B. Decreased blood flow USG shows increased blood flow in acute stage. Ischemic orchitis may set in, in late stages resulting in reduced blood flow on USG.","pyqMatches":[{"year":"2013","no":1396,"q":"Acute orchitis all are seen except","o":["Increased local temprature","Decreased blood flow","Etythematous scrotum","Raised TLC"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9399, 'Surgery', 'Vascular Surgery', 'Moderate', 'Surgery', 513, '{"id":9399,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":513,"q":"All are true about carcinoma penis except","o":["Most common type is verrocous","Spreads by blood borne metastasis","Leads to erosion of artery","Slowly progressive"],"a":0,"e":"Answer- A. Most common type is verrocous MC type – SCC ETIOLOGY- Premalignant lesions- Genital warts- Bushke- Lowenstein tumour is a giant penile condyloma (verrucous carcinoma of penis) Erythroplasia of Queyrat or Paget’s disease of penis- precancerous lesion SPREAD- Blood spread is rare Death may occur due to erosions of femoral vessels by iguinal LN. Slowly progressive","pyqMatches":[{"year":"2013","no":1399,"q":"All are true about carcinoma penis except","o":["Most common type is verrocous","Spreads by blood borne metastasis","Leads to erosion of artery","Slowly progressive"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9400, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 514, '{"id":9400,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":514,"q":"In testicular torsion, surgery within how much time can save viability of testis","o":["6 hr","12 hr","24 hr","1 week"],"a":0,"e":"Answer- A. 6 hr \"More than 80% testes can be salvaged if surgery is performed within 6 hours\". [Ref Schwartz 9th/e p. 1469]","pyqMatches":[{"year":"2013","no":1400,"q":"In testicular torsion, surgery within how much time can save viability of testis","o":["6 hr","12 hr","24 hr","1 week"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9401, 'Surgery', 'Urology', 'Easy', 'Surgery', 515, '{"id":9401,"subject":"Surgery","chapter":"Urology","difficulty":"Easy","source":"Surgery","sourceNo":515,"q":"Investigation using dye to find out stone in salivary gland","o":["Sialography","Mammography","MR angiography","USG"],"a":0,"e":"Answer- A. Sialography Salivary duct stones & strictures Chronic sialadenitis Tumors of salivary glands","pyqMatches":[{"year":"2013","no":1402,"q":"Investigation using dye to find out stone in salivary gland","o":["Sialography","Mammography","MR angiography","USG"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9402, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'Surgery', 516, '{"id":9402,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":516,"q":"ERCP is indicated for the following except","o":["Distal CBD tumor","Hepatic porta tumor","Proximal cholangiocarcinoma","Gall stone pancreatitis"],"a":2,"e":"Answer- C. Proximal cholangiocarcinoma ERCP is not technically possible in proximal biliary obstructions.","pyqMatches":[{"year":"2013","no":1404,"q":"ERCP is indicated for the following except","o":["Distal CBD tumor","Hepatic porta tumor","Proximal cholangiocarcinoma","Gall stone pancreatitis"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9403, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 517, '{"id":9403,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":517,"q":"Alagille syndrome is","o":["Bile duct paucity","IHBR dilation","PBC","PSC"],"a":0,"e":"Answer- A. Bile duct paucity yndromic paucity of interlobular bile ducts (Alagille syndrome) is the most common form of familial intrahepatic cholestasis. Chronic cholestasis affects 95% of patients. Peripheral pulmonic stenosis is observed in approximately 90%. Vertebral arch defects are seen (e.g., butterfly vertebrae, hemivertebrae, and a decrease in the interpedicular distance). Ophthalmologic examination may reveal posterior embryotoxon, retinal pigmentation, and iris strands.","pyqMatches":[{"year":"2013","no":1405,"q":"Alagille syndrome is","o":["Bile duct paucity","IHBR dilation","PBC","PSC"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9404, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 518, '{"id":9404,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":518,"q":"Hemorrhagic pancreatitis, bluish discoloration of flank","o":["Grey turner sign","Cullen sign","Trosseue sign","None"],"a":0,"e":"Answer- A. Grey turner sign In acute pancreatitis :","pyqMatches":[{"year":"2013","no":1406,"q":"Hemorrhagic pancreatitis, bluish discoloration of flank","o":["Grey turner sign","Cullen sign","Trosseue sign","None"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9405, 'Surgery', 'Hepatobiliary & Pancreas', 'Moderate', 'Surgery', 519, '{"id":9405,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Moderate","source":"Surgery","sourceNo":519,"q":"Complication of chronic pancreatitis include all except-","o":["Renal artery thrombosis","Pseudocyst","Splenic vein thrombosis","Fistulae"],"a":0,"e":"Answer- A. Renal artery thrombosis Complications- Obstructive jaundice Carcinoma of pancreas Pseudocysts Pancreatic duct leak with ascites or fistula Thrombosis of splenic vein Abscess Perforation","pyqMatches":[{"year":"2013","no":1407,"q":"Complication of chronic pancreatitis include all except","o":["Renal artery thrombosis","Pseudocyst","Splenic vein thrombosis","Fistulae"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9406, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 520, '{"id":9406,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":520,"q":"During functional endoscopic sinus surgery the position of patient is","o":["Trendelenberg","Lateral","Reverse trendelenberg","Lithotomy"],"a":2,"e":"Answer- C. Reverse trendelenberg Using the reverse trendelenburg position during functional endoscopic sinus surgery (FESS) is safe, simple, and cost-free method that has been found to reduce intraoperative blood loss.","pyqMatches":[{"year":"2013","no":1410,"q":"During functional endoscopic sinus surgery the position of patient is","o":["Trendelenberg","Lateral","Reverse trendelenberg","Lithotomy"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9407, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 521, '{"id":9407,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":521,"q":"Head & face burn in infant is","o":["15%","18%","12%","32%"],"a":1,"e":"Answer- B. 18% \"Infants have 21% of the TBSA in the head and neck\" — Sabiston Children have a relatively larger portion of the body surface area in the head and neck which is compensated for by a relatively smaller surface area in the lower extremities. Infants have 21% of TBSA in the head and neck and 13% in each leg.","pyqMatches":[{"year":"2013","no":1411,"q":"Head & face burn in infant is","o":["15%","18%","12%","32%"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9408, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 522, '{"id":9408,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":522,"q":"Plasma expanders are used in","o":["Endotoxic shock","Neurogenic shock","Vasovagal shock","Anaphylactic shock"],"a":0,"e":"Answer- A. Endotoxic shock Uses of plasma expanders 4 to correct hypovolemia, e.g. in burns, hypovolemic and endotoxic shock, severe trauma. Contraindications - Severe anaemia, cardiac failure, pulmonary edema, renal insufficiency.","pyqMatches":[{"year":"2013","no":1412,"q":"Plasma expanders are used in","o":["Endotoxic shock","Neurogenic shock","Vasovagal shock","Anaphylactic shock"],"a":0,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9409, 'Surgery', 'Neurosurgery', 'Easy', 'Surgery', 523, '{"id":9409,"subject":"Surgery","chapter":"Neurosurgery","difficulty":"Easy","source":"Surgery","sourceNo":523,"q":"Whiplash injury is tear of which ligament","o":["Ligamenta flava","Ant. longitudinal ligament","Post. longitudinal ligament","Supraspinal ligament"],"a":1,"e":"Answer- B. Ant. longitudinal ligament Hyperextension theory describes whiplash injury. Hyperextension most commonly results in anterior cervical column injuries in the form of anterior longitudinal ligament and intervertebral disc ruptures.","pyqMatches":[{"year":"2013","no":1413,"q":"Whiplash injury is tear of which ligament","o":["Ligamenta flava","Ant. longitudinal ligament","Post. longitudinal ligament","Supraspinal ligament"],"a":1,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9410, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 524, '{"id":9410,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":524,"q":"Neurosurgery is indicated for all except","o":["SDH","EDH","Intracerebral bleed","Diffuse axonal injury"],"a":3,"e":"Answer- D. Diffuse axonal injury Diffuse axonal injury does not have any specific treatment Symptomatic treatment and stabilization of patient is required. Subdural hematoma, (SDH), epidural hematoma (EDH) and intracerebral hematoma (parenchymal hemorrhage) may require surgery","pyqMatches":[{"year":"2013","no":1415,"q":"Neurosurgery is indicated for all except","o":["SDH","EDH","Intracerebral bleed","Diffuse axonal injury"],"a":3,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9411, 'Surgery', 'General Principles & Wounds', 'Hard', 'Surgery', 525, '{"id":9411,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Hard","source":"Surgery","sourceNo":525,"q":"Young male with history of trauma having left sided testis swollen & erythematous. Other side normal diagnosis","o":["Torsion","Carcinoma","Hematoma","Hernia"],"a":2,"e":"Answer- C. Hematoma Blunt trauma to testis can cause hematoma. There is associated tenderness, swelling and ecchymosis of the hemiscrotum.","pyqMatches":[{"year":"2013","no":1417,"q":"Young male with history of trauma having left sided testis swollen & erythematous. Other side normal diagnosis","o":["Torsion","Carcinoma","Hematoma","Hernia"],"a":2,"source":"NEET_2013_Paper.pdf"}],"pyqYears":["2013"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9412, 'Surgery', 'Hepatobiliary & Pancreas', 'Easy', 'Surgery', 526, '{"id":9412,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Easy","source":"Surgery","sourceNo":526,"q":"Central stellate scar is seen in","o":["Focal nodular hyperplasia","Chronic regenerative hyperplasia","Hepatoblastoma","None"],"a":0,"e":"Answer- A. Focal nodular hyperplasia Focal nodular hyperplasia is a rare tumor-like condition predominantly found in women during to third to the fifth decade of life. Most commonly it is incidentally discovered as asymptomatic mass. The pathognomonic microscopic feature. A central stellate scar seen in liver imaging studies is a highly characteristic feature of focal nodular hyperplasia. It is also seen in Renal cell carcinoma(RCC).","pyqMatches":[{"year":"2012","no":495,"q":"Central stellate scar is seen in","o":["Focal nodular hyperplasia","Chronic regenerative hyperplasia","Hepatoblastoma","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9413, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 527, '{"id":9413,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":527,"q":". Z plasty ideal angle","o":["90°","45°","60°","75°"],"a":2,"e":"Answer- C. 60° The 60 degree Z-plasty (ie, classic Z-plasty) is most commonly used because it provides the optimal balance between lengthening and ease of closure.","pyqMatches":[{"year":"2012","no":1091,"q":". Z plasty ideal angle","o":["90°","45°","60°","75°"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9414, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 528, '{"id":9414,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":528,"q":"Lymphedema precox all are true except","o":["U/L","More common in men","Affects the legs","2-35yrs of age"],"a":1,"e":"Answer- B. More common in men Primary lymphedema with age of onset b/w ages 1 year and 35 years. MC forms of primary lymphedema. Female : Male - 10 : 1 Swelling involves foot and calf. Usually unilateral","pyqMatches":[{"year":"2012","no":1093,"q":"Lymphedema precox all are true except","o":["U/L","More common in men","Affects the legs","2-35yrs of age"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9415, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 529, '{"id":9415,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":529,"q":"RTA with multiple fractures initial treatment would be -","o":["Management of shock","Splinting of limbs","Airway management","Cervical spine protection"],"a":2,"e":"Answer- C. Airway management Management of trauma begins with primary survey. The ATLS (Advanced Trauma Life Support) defines primary survey as assessment of the `A,B,C'' i.e., Airway with cervical spine protection, Breathing and circulation.","pyqMatches":[{"year":"2012","no":1094,"q":"RTA with multiple fractures initial treatment would be","o":["Management of shock","Splinting of limbs","Airway management","Cervical spine protection"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9416, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 530, '{"id":9416,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":530,"q":"With blunt trauma all over body the amount of N2 & nitrogen end products lost/day","o":["35gm","45gm","55gm","65gm"],"a":0,"e":"Answer- A. 35gm After injury, the initial systemic proteolysis, mediated primarily by glucocorticoides increases urinary nitrogen excretion to levels in excess of 30 gm/day.","pyqMatches":[{"year":"2012","no":1096,"q":"With blunt trauma all over body the amount of N2 & nitrogen end products lost/day","o":["35gm","45gm","55gm","65gm"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9417, 'Surgery', 'Vascular Surgery', 'Easy', 'Surgery', 531, '{"id":9417,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Easy","source":"Surgery","sourceNo":531,"q":"Inverted Champagne bottle appearance is seen in","o":["Varicose veins","DVT","Lipodermatosclerosis","Venous ulceration"],"a":2,"e":"Answer- C. Lipodermatosclerosis The most commonly recognized form of lipodermatosclerosis (LDS), chronic LDS presence with induration and hyperpigmentation of the skin involving the one or both of the lower legs in a characteristic \"inverted champagne bottle\" appearance. Associated with venous insufficiency, LDS is most common in middle-aged women.","pyqMatches":[{"year":"2012","no":1099,"q":"Inverted Champagne bottle appearance is seen in","o":["Varicose veins","DVT","Lipodermatosclerosis","Venous ulceration"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9418, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 532, '{"id":9418,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":532,"q":"10 cm tumor on anterior surface of thigh, what is done to know to diagnosis","o":["Incision biopsy","Excision biopsy","FNAC","USG"],"a":0,"e":"Answer- A. Incision biopsy Incisional biopsy is indicated when tissue samples are not obtained by FNAC or core needle biopsy as in deep tumors and for superficial soft tissue tumors > 3cm. Excisional biopsy is indicated for easily accesible extremity or truncal lesions < 3cm.","pyqMatches":[{"year":"2012","no":1100,"q":"10 cm tumor on anterior surface of thigh, what is done to know to diagnosis","o":["Incision biopsy","Excision biopsy","FNAC","USG"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9419, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 533, '{"id":9419,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":533,"q":"Flash burn, tender, red & painful, which of the following type is the burn-","o":["Scalded burn","First degree burn","Second degree burn","Fourth degree burn"],"a":1,"e":"Answer- B. First degree burn First degree burn (also k/a Superficial or Epidermal burn) These burns involve only the epidermis They do not blister, Are erythematous because of dermal vasodilation Blanch to touch (i.e. show capillary refilling) Are quite painful Heal without scarring in 5 to 10 days. They result in pain and reddening of the epidermis (outer layer of the skin). The clinical fearures are blistering and/or loss of the epidermis. The underlying dermis is pink and moist. The capillary return is cleariy visible when blanched","pyqMatches":[{"year":"2012","no":1102,"q":"Flash burn, tender, red & painful, which of the following type is the burn","o":["Scalded burn","First degree burn","Second degree burn","Fourth degree burn"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9420, 'Surgery', 'Gastrointestinal Surgery', 'Hard', 'Surgery', 534, '{"id":9420,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Hard","source":"Surgery","sourceNo":534,"q":"In a female abdominal intestinal perforation operated has serous discharge on 5th day with wound gap. What is your diagnosis","o":["Wound dehiscence","Enterocutaneous fistula","Scroma","Peritonitis"],"a":0,"e":"Answer- A. Wound dehiscence Dehisence most often develops 7 to 10 days postoperatively but may occur anytime after surgery, from 1 to more than 20 days.\"- Sabiston","pyqMatches":[{"year":"2012","no":1105,"q":"In a female abdominal intestinal perforation operated has serous discharge on 5th day with wound gap. What is your diagnosis","o":["Wound dehiscence","Enterocutaneous fistula","Scroma","Peritonitis"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9421, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 535, '{"id":9421,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":535,"q":"Peritonitis","o":["Neutrophils > 250mm3","WBC < 100/m1","Ascitis lactate level < 25 mg/dl","Ascitis fluid pH > 735"],"a":0,"e":"Answer-A. Neutrophils > 250mm3 More than 250 neutrophills/cumm of ascitis fluid suggest an acute inflammatory process, the most common of which is spontaneous bacterial peritonitis. An ascites lactate level of more than 25 mg/di was found to be 100% sensitive and specific in predicting active spontaneous bacterial peritonitis.","pyqMatches":[{"year":"2012","no":1106,"q":"Peritonitis","o":["Neutrophils > 250mm3","WBC < 100/m1","Ascitis lactate level < 25 mg/dl","Ascitis fluid pH > 735"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9422, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 536, '{"id":9422,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":536,"q":"Treatment of choice in anorectal carcinoma","o":["Chemoradiation","APRCombined surgery and radiotherapy","Chemotherapy alone","All"],"a":1,"e":"Answer-B Abdominal-perineal resection with colostomy was the preferred surgical procedure for most major cancers of the anal canal,","pyqMatches":[{"year":"2012","no":1108,"q":"Treatment of choice in anorectal carcinoma","o":["Chemoradiation","APRCombined surgery and radiotherapy","Chemotherapy alone","All"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9423, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 537, '{"id":9423,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":537,"q":"Rectal prolapse surgery is","o":["Rectal mucosal stapling","Mucosal resection","Placation/wiring","Rectopexy"],"a":3,"e":"Answer- D. Rectopexy Abdominal approach","pyqMatches":[{"year":"2012","no":1109,"q":"Rectal prolapse surgery is","o":["Rectal mucosal stapling","Mucosal resection","Placation/wiring","Rectopexy"],"a":3,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9424, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 538, '{"id":9424,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":538,"q":"Crohn''s disease","o":["Continous involvement","Sinus & fistula","Mesenteric lymphadenitis","Stud ulcer"],"a":1,"e":"Answer- B. Sinus & fistula Clinical features- Intermittent mild diarrhea, fever, abdominal pain (MC) Right lower quadrant mass, weight loss, anemia Sometimes mimics appendicitis or bowel perforation Anal complaints (fissure, fistula, abscess) – frequent Fat/vitamin malabsorption present","pyqMatches":[{"year":"2012","no":1110,"q":"Crohn''s disease","o":["Continous involvement","Sinus & fistula","Mesenteric lymphadenitis","Stud ulcer"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9425, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 539, '{"id":9425,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":539,"q":"Step ladder pattern of gas shadow is seen in","o":["Duodenal obstruction","Intestinal obstruction","Gastric outlet obstruction","Sigmoid volvulus"],"a":1,"e":"Answer- B. Intestinal obstruction Stepladder sign represents the appearance of gas-fluid distended small bowel loops that appear to be stacked on top of each other, typically observed on erect abdominal radiographs in the setting of small bowel obstruction.","pyqMatches":[{"year":"2012","no":1111,"q":"Step ladder pattern of gas shadow is seen in","o":["Duodenal obstruction","Intestinal obstruction","Gastric outlet obstruction","Sigmoid volvulus"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9426, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 540, '{"id":9426,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":540,"q":"What is not seen in short bowel syndrome","o":["Hypergastrinemia & high gastric secretion is seen","Diarrhea, dehydration and malnutrition","Hirsutism","Chronic TPN dependence"],"a":2,"e":"Answer- C. Hirsutism Resection of jejunum is better tolerated than resection of ileum, as the capacity for bile salt and vitamin B12 absorption is specific to the ileum Malabsorption after massive small bowel resection is exacerbated by a characteristic hypergastrinemia​associated gastric acid hypersecretion that persists for 1 to 2 years postoperatively Short-bowel syndrome is a disorder clinically defined by malabsorption, diarrhea, steatorrhea, fluid and electrolyte disturbances, and malnutrition.","pyqMatches":[{"year":"2012","no":1112,"q":"What is not seen in short bowel syndrome","o":["Hypergastrinemia & high gastric secretion is seen","Diarrhea, dehydration and malnutrition","Hirsutism","Chronic TPN dependence"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9427, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 541, '{"id":9427,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":541,"q":"Ogilvie''s syndrome most commonly involves","o":["Stomach","Colon","Gallbladder","Small intestine"],"a":1,"e":"Answer- B. Colon Ogilvie syndrome, or acute colonic pseudo-obstruction (ACPO), is a clinical disorder with the signs, symptoms, and radiographic appearance of acute large bowel obstruction with no evidence of the actual physical cause of the obstruction. The colon may become massively dilated; if not decompressed, the patient risks perforation, peritonitis, and death. Pseudo-obstruction most commonly occurs in hospitalized patients and is associated with the use of narcotics, bed rest, and co-morbid disease. This condition describes an obstruction, usually of the colon, that occurs in the absence of a mechanical cause or acute intra- abdominal disease. Abdominal radiographs show evidence of colonic obstruction, with marked cecal distension being a common feature.","pyqMatches":[{"year":"2012","no":1114,"q":"Ogilvie''s syndrome most commonly involves","o":["Stomach","Colon","Gallbladder","Small intestine"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9428, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 542, '{"id":9428,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":542,"q":"Spigelian hernia is","o":["Through linea alba","Through lateral border of rectus abdominis","Through medial wall of iinguinal canal","Through lateral wall of inguinal canal"],"a":1,"e":"Answer- B. Through lateral border of rectus abdominis Spigelian hernias can occur anywhere along the length of the spigelian line or zone — an aponeurotic band of variable width at the lateral border of the rectus abdominis. The most frequent location of these rare hemias is at or slightly above the level of the arcuate line. Spigelian hernia occurs through the linear semilunaris which corresponds to the lateral margin of the rectus abdominis. A spigelian hernia occurs through the spigelian fascia, which is composed of the aponeurotic layer between the rectus muscle medially and the semilunar line laterally.","pyqMatches":[{"year":"2012","no":1115,"q":"Spigelian hernia is","o":["Through linea alba","Through lateral border of rectus abdominis","Through medial wall of iinguinal canal","Through lateral wall of inguinal canal"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9429, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 543, '{"id":9429,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":543,"q":"24 day neonate with projectile vomiting & failure to gain weight .what is the diagnosis","o":["CHPS","NEC","Duodenal atresia","Hirschsprung''s disease"],"a":0,"e":"Answer- A. CHPS Projectile vomiting in 4th week is quite suggestive of CHPS. In duodenal atresia the vomiting (usually bilious) is right from the 1st day of life. NEC and Hirschsprung''s disease have different clinical presentation.","pyqMatches":[{"year":"2012","no":1117,"q":"24 day neonate with projectile vomiting & failure to gain weight .what is the diagnosis","o":["CHPS","NEC","Duodenal atresia","Hirschsprung''s disease"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9430, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'Surgery', 544, '{"id":9430,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":544,"q":"Not true about Barrett''s esophagus","o":["Metaplasia of cells","Predisposes to SCC","Precancerous condition","Intestinal type is the most common type"],"a":1,"e":"Answer- B. Predisposes to SCC Barrett''s esophagus is premalignant condition for adenocarcinma esophagus and not SCC.","pyqMatches":[{"year":"2012","no":1118,"q":"Not true about Barrett''s esophagus","o":["Metaplasia of cells","Predisposes to SCC","Precancerous condition","Intestinal type is the most common type"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9431, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 545, '{"id":9431,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":545,"q":"Gastrotomy is","o":["Open the stomach closed after tube insertion","Opening the stomach","Resecting the terminal part of stomach","Resecting the proximal part of stomach"],"a":1,"e":"Answer- B. Opening the stomach Gastrostomy refers to a surgical opening into the stomach.; creation of an artificial external opening into the stomach for nutritional support or gastrointestinal compression. Typically this would include an incision in the patient''s epigastrium as part of a formal operation.","pyqMatches":[{"year":"2012","no":1119,"q":"Gastrotomy is","o":["Open the stomach closed after tube insertion","Opening the stomach","Resecting the terminal part of stomach","Resecting the proximal part of stomach"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9432, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 546, '{"id":9432,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":546,"q":"Parrot beak appearance is seen in","o":["Volvulus","Intussuption","Rectal atresia","CA colon"],"a":0,"e":"Answer- A. Volvulus Barium/gastrograffin enema - demonstrates the point of obstruction, pathognomonic \"Bird beck deformity\" or parrot beak deformity. Contrast enema is contraindicated if gangrene is suspected. \"Parrot beaked\" clawing of neils is also seen in chronic cocaine abuse.","pyqMatches":[{"year":"2012","no":1120,"q":"Parrot beak appearance is seen in","o":["Volvulus","Intussuption","Rectal atresia","CA colon"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9433, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 547, '{"id":9433,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":547,"q":"Raspberry tumor is seen in","o":["Umbilical fistula","Meckel’s diverticulum","Umbilical adenoma","Umbilical granuloma"],"a":2,"e":"Answer- C. Umbilical adenoma An umbilical adenoma is also known as “Raspberry tumor”. It is due to a partially unobliterated vitellointestinal duct. It is seen in infants. The prolapsing mucosa gives the raspberry appearance and bleeds on touch. Treatment: A ligature is tied around its base, and it falls off after a few days. Recurrence is treated with surgery.","pyqMatches":[{"year":"2012","no":1121,"q":"Raspberry tumor is seen in","o":["Umbilical fistula","Meckel’s diverticulum","Umbilical adenoma","Umbilical granuloma"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9434, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 548, '{"id":9434,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":548,"q":"After mastectomy, breast reconstruction is done by","o":["Deltopectoral","latissimus dorsi","Serratus anterior","Trapezius"],"a":1,"e":"Answer- B. latissimus dorsi If the skin at the mastectomy site is poor (e.g. following radiotherapy) or if a larger volume of tissue is required, a musculocutaneous flap can be constructed either from the latissimusdorsi muscle (an LD flap) or using the transversusabdominis muscle (a TRAM flap as). The latter gives an excellent cosmetic result in experienced hands but is a lengthy procedure and requires careful patient selection.","pyqMatches":[{"year":"2012","no":1122,"q":"After mastectomy, breast reconstruction is done by","o":["Deltopectoral","latissimus dorsi","Serratus anterior","Trapezius"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9435, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 549, '{"id":9435,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":549,"q":"Peau de orange appearance of Ca breast, what is the stage","o":["T4b","T4a","T3a","T3b"],"a":0,"e":"Answer- A. T4b Stage I : T1N0M0 Stage Ila : T0N1M0;T1N1M0;T2N0M0. Stage Ilb : T2N1M0;T3N0M0 Stage Illa : T0N2M0;T1N2M0;T2N2M0;T3N1M0;T3N2M0 Stage Illb : T4N0M0;T4N1M0;T4N2M0 Stage Illc : Any TN3M0 Stage IV : Any T,any N,M Early breast cancer___ Stage I and 11J1N1,1-2N1;13NO Locally advanced breast cancer (LABC)—Stage 111AI Metastatic breast cancer—Stage IV Primary tumor (T) TX- Primary tumor cannot be assessed T0- No evidence of primary tumor Tis- Carcinoma in situ Tis (DCIS)- Ductal carcinoma in situ Tis (Paget)- Paget disease of the nipple NOT associated with invasive carcinoma and/or carcinoma in situ (DCIS) in the underlying breast parenchyma. Carcinomas in the breast parenchyma associated with Paget disease are categorized on the basis of the size and characteristics of the parenchymal disease, although the presence of Paget disease should still be noted T1-Tumor ≤ 20 mm in greatest dimension T1mi- Tumor ≤ 1 mm in greatest dimension T1a- Tumor > 1 mm but ≤ 5 mm in greatest dimension (round any measurement >1.0-1.9 mm to 2 mm) T1b- Tumor > 5 mm but ≤ 10 mm in greatest dimension T1c- Tumor > 10 mm but ≤ 20 mm in greatest dimension T2- Tumor > 20 mm but ≤ 50 mm in greatest dimension T3- Tumor > 50 mm in greatest dimension T4- Tumor of any size with direct extension to the chest wall and/or to the skin (ulceration or skin nodules), not including invasion of dermis alone T4a- Extension to chest wall, not including only pectoralis muscle adherence/invasion T4b- Ulceration and/or ipsilateral satellite nodules and/or edema (including peau d’orange) of the skin, which do not meet the criteria for inflammatory carcinoma T4c- Both T4a and T4b T4d- Inflammatory carcinoma","pyqMatches":[{"year":"2012","no":1123,"q":"Peau de orange appearance of Ca breast, what is the stage","o":["T4b","T4a","T3a","T3b"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9436, 'Surgery', 'Breast Surgery', 'Moderate', 'Surgery', 550, '{"id":9436,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":550,"q":"Not a component of triple test in detection of Ca breast-","o":["Breast self examination","USG/ mammography","FNAC/ trucut biopsy","Clinical examination"],"a":0,"e":"Answer- A.Breast self examination Triple assessment includes examination by a clinician. Self examination is not a part of triple assessment. Bailey and Love writes — \"In any patient who presents with a breast lump or other symptoms suspicious of carcinoma, the diagnosis should be made by a combination of clinical assessment, radiological imaging and a tissue sample taken for either cytological or histological analysis, the so called triple assessment. The positive predictive value (PPV) of this combination should exceed 99.9%.\"","pyqMatches":[{"year":"2012","no":1125,"q":"Not a component of triple test in detection of Ca breast","o":["Breast self examination","USG/ mammography","FNAC/ trucut biopsy","Clinical examination"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9437, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 551, '{"id":9437,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":551,"q":"Treatment for hydroureter","o":["Antibiotic prophylaxis alone","Immediate ureterolithotomy","Endoscopic ureteral stenting","Urinary alkalization"],"a":2,"e":"Answer- C. Endoscopic ureteral stenting Hydroureter is mainly caused by intrinsic and extrinsic obstruction of ureter. Causes are - Calculi (ureteric/VVJ) - intrinsic stricture and Retroperitoneal fibrosis - extrinsic.","pyqMatches":[{"year":"2012","no":1126,"q":"Treatment for hydroureter","o":["Antibiotic prophylaxis alone","Immediate ureterolithotomy","Endoscopic ureteral stenting","Urinary alkalization"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9438, 'Surgery', 'Urology', 'Easy', 'Surgery', 552, '{"id":9438,"subject":"Surgery","chapter":"Urology","difficulty":"Easy","source":"Surgery","sourceNo":552,"q":"Diversion of urine is best done at","o":["Ileum","Jejunum","Caecum","Colon"],"a":0,"e":"Answer- A. Ileum Ileal segment is the best for urinary diversion after cystectomy. Still better method is \"Continent cutaneous diversion\" method. But the best method is \"Orthotopic neobladders\".","pyqMatches":[{"year":"2012","no":1127,"q":"Diversion of urine is best done at","o":["Ileum","Jejunum","Caecum","Colon"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9439, 'Surgery', 'Urology', 'Easy', 'Surgery', 553, '{"id":9439,"subject":"Surgery","chapter":"Urology","difficulty":"Easy","source":"Surgery","sourceNo":553,"q":"Ureterosigmoistomy","o":["Hyperchloremic with hypokalemic acidosis","Hyperkalemia","Metabolic alkalosis","Hyponatremia"],"a":0,"e":"Answer- A. Hyperchloremic with hypokalemic acidosis There is hyperchloremic metabolic acidosis with hypokalemia.","pyqMatches":[{"year":"2012","no":1128,"q":"Ureterosigmoistomy","o":["Hyperchloremic with hypokalemic acidosis","Hyperkalemia","Metabolic alkalosis","Hyponatremia"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9440, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 554, '{"id":9440,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":554,"q":"Injury to penis which of the following prevents extravasation of blood –","o":["Bucks fascia","Fascia of camper","Fascia transversalis","None"],"a":0,"e":"Answer- A. Bucks fascia Superficial to tunica albuginea there is Buck''s facia (deep layer of superficial fascia of penis), a prolongation of colle''s fascia (membranous layer of superficial fascia of perineum). If Buck''s facia remains intact, hematoma is restricted to penile shaft only causing egg-plant deformity. If Buck''s fascia is disrupted, hematoma can extend to scrotum, perineum and suprapubic regions.","pyqMatches":[{"year":"2012","no":1129,"q":"Injury to penis which of the following prevents extravasation of blood –","o":["Bucks fascia","Fascia of camper","Fascia transversalis","None"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9441, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 555, '{"id":9441,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":555,"q":"Phimosis is associated with","o":["Paraphimosis","Meatal stenosis","Balanoposthitis","Hypospadias"],"a":2,"e":"Answer- C. Balanoposthitis Phismosis caused due to chronic infection Congenital Acquired- trauma, Penis Ca and Balanitis Pathological phimosis (as opposed to the natural non-retractability of the foreskin in childhood) is rare and the causes are varied. Some cases may arise from balanitis (inflammation of the glans penis). Phimosis may occur after other types of chronic inflammation (such as balanoposthitis), repeated catheterization, or forcible foreskin retraction. Phimosis may also arise in untreated diabetics","pyqMatches":[{"year":"2012","no":1130,"q":"Phimosis is associated with","o":["Paraphimosis","Meatal stenosis","Balanoposthitis","Hypospadias"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9442, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 556, '{"id":9442,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":556,"q":"Circumcision is contraindicated in","o":["Balanitis","Hypospadias","Paraphimosis","Exostrophy of bladder"],"a":1,"e":"Answer- B. Hypospadias Circumcision is not done in patients with hypospadias as the prepuce can later be used in surgical repair. Circucision is mostly done for cultural reasons. The medical indications for circumcision are: Phimosis & Paraphimosis Recurrent balanoposthitis (i.e. inflammation of the foreskin) Recurrent urinary tract infection","pyqMatches":[{"year":"2012","no":1131,"q":"Circumcision is contraindicated in","o":["Balanitis","Hypospadias","Paraphimosis","Exostrophy of bladder"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9443, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 557, '{"id":9443,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":557,"q":"Which is not true about cancer of tongue","o":["Adenocarcinoma most common","Lateral surface involved","Deep cervical lymph nodes not involved","Tobacco is the cause"],"a":0,"e":"Answer- A. Adenocarcinoma most common SCC is the most common type of malignancy, but leiomyosarcomas and rhabdomyosarcomas are also encountered (rarely). Tumors on the tongue may occur on any surface but are most commonly seen on the lateral and ventral surfaces. The regional lymphatics of the oral cavity are to the submandibular space and the upper cervical lymph nodes. Risk factors- tobacco and alcohol.","pyqMatches":[{"year":"2012","no":1132,"q":"Which is not true about cancer of tongue","o":["Adenocarcinoma most common","Lateral surface involved","Deep cervical lymph nodes not involved","Tobacco is the cause"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9444, 'Surgery', 'Hepatobiliary & Pancreas', 'Easy', 'Surgery', 558, '{"id":9444,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Easy","source":"Surgery","sourceNo":558,"q":"Kasai operation","o":["Biliary atresia","Choledochal cyst","Hepatocellular carcinoma","Primary biliary cirrhosis"],"a":0,"e":"Answer- A. Biliary atresia Kasai operation is also known as hepatoportoenterostomy. Biliary atresia is currently MC indication for pediatric liver transplantation.","pyqMatches":[{"year":"2012","no":1134,"q":"Kasai operation","o":["Biliary atresia","Choledochal cyst","Hepatocellular carcinoma","Primary biliary cirrhosis"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9445, 'Surgery', 'Hepatobiliary & Pancreas', 'Easy', 'Surgery', 559, '{"id":9445,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Easy","source":"Surgery","sourceNo":559,"q":"False about hepatic adenoma","o":["Benign lesion","OCP use","Older females","Cold on isotope scan"],"a":2,"e":"Answer- C. Older females Hepatic adenomas are benign solid neoplasms of liver. MC seen in younger females (20-40 years of age) Usually solitary Risk factor - Prior/current use of estrogens (OCP)","pyqMatches":[{"year":"2012","no":1136,"q":"False about hepatic adenoma","o":["Benign lesion","OCP use","Older females","Cold on isotope scan"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9446, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 560, '{"id":9446,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":560,"q":"Bismuth classification in which class, hepatic duct confluence is involved","o":["Type I","Type II","Type III","Type IV"],"a":1,"e":"Answer- B. Type II Bismuth - Corlette classification is used to classify cholangiocarcinoma Type I - Common hepatic duct involvement. Type II - CHD + bifurcation/confluence of hepatic ducts. Type III- a) Extension to right secondary intrahepatic duct. b) Extension to left secondary intrahepatic duct. Type IV - Involving both right and left secondary intrahepatic ducts.","pyqMatches":[{"year":"2012","no":1137,"q":"Bismuth classification in which class, hepatic duct confluence is involved","o":["Type I","Type II","Type III","Type IV"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9447, 'Surgery', 'Endocrine Surgery', 'Easy', 'Surgery', 561, '{"id":9447,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Easy","source":"Surgery","sourceNo":561,"q":"Parathyroid glands are removed by surgery, for recurrence investigation of choice","o":["Technetium scan","SPECT","MRI","Neck ultrasound"],"a":0,"e":"Answer-A. Technetium scan Preoperative localisation tests for parathyroid glands are","pyqMatches":[{"year":"2012","no":1138,"q":"Parathyroid glands are removed by surgery, for recurrence investigation of choice","o":["Technetium scan","SPECT","MRI","Neck ultrasound"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9448, 'Surgery', 'Hepatobiliary & Pancreas', 'Moderate', 'Surgery', 562, '{"id":9448,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Moderate","source":"Surgery","sourceNo":562,"q":"Which is not a contraindication for pancreaticoduo-denectomy","o":["Metastasis","Portal vein involvement","Stage III CA head of pancrease","Invasion of superior mesentric vein"],"a":1,"e":"Answer- B. Portal vein involvement Tumor (T) TX - Primary can''t be asscessed. To - No evidence of primary tumor. T1 - Ca in situ. T1 - Limited to pancreas and 2cm. T2 - Limited to pancreas and > 2cm. T3 - Extends beyond pancreas but no involvement of celiac axis or superior mesentric artery. T4 - Involves celiac axis or Sup-mesenteric artery (unresectable primary). Regional lymph nodes (N) NX - Regional LI\\l, canot be assessed. N1 - No regional LN metastasis. N2 - Regional LN metastasis. Regional lymph nodes (N) Mx- Distant metastasis cannot be assessed. Mo- No distant metastasis. M1 - Distant metastasis.","pyqMatches":[{"year":"2012","no":1139,"q":"Which is not a contraindication for pancreaticoduo-denectomy","o":["Metastasis","Portal vein involvement","Stage III CA head of pancrease","Invasion of superior mesentric vein"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9449, 'Surgery', 'Hepatobiliary & Pancreas', 'Easy', 'Surgery', 563, '{"id":9449,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Easy","source":"Surgery","sourceNo":563,"q":"Most common cause of chronic pancreatitis","o":["Chronic alcoholism","Tropical pancreatitis","Pancreas divisium","Gall stone disease"],"a":0,"e":"Answer- A. Chronic alcoholism \"Worldwide, alcohol consumption and abuse is associated with chronic pancreatitis in up to 70% of cases \"","pyqMatches":[{"year":"2012","no":1140,"q":"Most common cause of chronic pancreatitis","o":["Chronic alcoholism","Tropical pancreatitis","Pancreas divisium","Gall stone disease"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9450, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 564, '{"id":9450,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":564,"q":"Most common cause of acute parotitis -","o":["Staphylococcus Aureus","Streptococcus Pneumonia","Klebsiella","Streptococcus Viridans"],"a":0,"e":"Answer- A. Staphylococcus Aureus MC organism is Staphylococcus Aureus >> streptococcus viridans >> pneumococcus. Acute bacterial parotitis: is most often caused by a bacterial infection of Staphylococcus aureus but may be caused by any commensal bacteria. Usually ascending infection Staphylococcus aureus Ref- Manipal Manual of Surgery 5th edition","pyqMatches":[{"year":"2012","no":1141,"q":"Most common cause of acute parotitis","o":["Staphylococcus Aureus","Streptococcus Pneumonia","Klebsiella","Streptococcus Viridans"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9451, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 565, '{"id":9451,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":565,"q":"Pre-operative prophylaxis for pheochromocytoma","o":["Alpha blockade after beta blocker","Beta blockade after alpha blocker","Alpha blocker","Beta blocker"],"a":1,"e":"Answer- B. Beta blockade after alpha blocker Beta blockers such as propanalol at doses of 10 to 40 mg every 6 to 8 hours are often needed in patients who have persistant tachycardia and arrhythmias. n-blockers should only be added after adequate a-blockade and rehydration. a-adrenergic agonists may be needed in immediate post operative period to prevent post operative hypotension and cardiovascular collapse.","pyqMatches":[{"year":"2012","no":1142,"q":"Pre-operative prophylaxis for pheochromocytoma","o":["Alpha blockade after beta blocker","Beta blockade after alpha blocker","Alpha blocker","Beta blocker"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9452, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 566, '{"id":9452,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":566,"q":"Child with polytrauma came to casualty, dose of packed cell","o":["10 ml/kg","20 ml/kg","30 ml/kg","40 ml/kg"],"a":0,"e":"Answer-A Usual dosage of packed red cells in pediatric populations is 10-15 ml/kg, but can be increased upto 20 ml/kg in cases where higher increase in HCt is needed, as in trauma. Colloid 10ml/kg Crystalloid 20ml/kg Requiring > 20 ml/Kg of PRBCs in the 1st hour of resuscitation Pediatric MTG Pack (≤ 50 Kg) • 4 Units of PRBCs • 2 Units of thawed plasma • 1 Unit of apheresis platelets","pyqMatches":[{"year":"2012","no":1144,"q":"Child with polytrauma came to casualty, dose of packed cell","o":["10 ml/kg","20 ml/kg","30 ml/kg","40 ml/kg"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9453, 'Surgery', 'General Principles & Wounds', 'Hard', 'Surgery', 567, '{"id":9453,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Hard","source":"Surgery","sourceNo":567,"q":"Polytrauma patient came to EMS, dose of crystalloid given should be","o":["500 ml RL bolus then regulated by indicators","2000 ml bolus","1000 ml bolus then regulated by clinical indicators","250 ml bolus"],"a":2,"e":"Answer- C. 1000 ml bolus then regulated by clinical indicators Fluid resuscitation begins with 1000 ml bolus of RL for adult and 20 ml/kg for a child. Response to therapy is monitored by clinical indicators as blood pressure, skin perfusion, urinary output and mental status.","pyqMatches":[{"year":"2012","no":1145,"q":"Polytrauma patient came to EMS, dose of crystalloid given should be","o":["500 ml RL bolus then regulated by indicators","2000 ml bolus","1000 ml bolus then regulated by clinical indicators","250 ml bolus"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9454, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 568, '{"id":9454,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":568,"q":"A polytrauma CT scan, CT brain shows a lesion with concave margin","o":["EDH","SDH","Contusion","Diffuse axonal injury"],"a":1,"e":"Answer- B. SDH SDH - On head CT, the clot is bright or mixed density, cresent shaped (Lunate), may have a less distinct border and does not cross midline. Contusion - The contused area appears bright on CT Scan.","pyqMatches":[{"year":"2012","no":1147,"q":"A polytrauma CT scan, CT brain shows a lesion with concave margin","o":["EDH","SDH","Contusion","Diffuse axonal injury"],"a":1,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9455, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 569, '{"id":9455,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":569,"q":"A person inhaled peanut two days back& now unable to cough it out where is the possible location","o":["Right superior lobe","Rt middle lobe","Rt lower lobe","Lt lower lobe"],"a":2,"e":"Answer- C. Rt lower lobe The most common anatomic location for a foreign body is the right main stem bronchus or the right lower lobe.","pyqMatches":[{"year":"2012","no":1150,"q":"A person inhaled peanut two days back& now unable to cough it out where is the possible location","o":["Right superior lobe","Rt middle lobe","Rt lower lobe","Lt lower lobe"],"a":2,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9456, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 570, '{"id":9456,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":570,"q":"Hernia most commonly strangulates in","o":["Indirect","Direct","Spigelian","Incisional"],"a":0,"e":"Answer- A. Indirect \"Most strangulated hernias are indirect inguinal hernias, however, femoral hernias have the highest rate of strangulation (15-20%) of all hernias\".","pyqMatches":[{"year":"2012","no":1152,"q":"Hernia most commonly strangulates in","o":["Indirect","Direct","Spigelian","Incisional"],"a":0,"source":"NEET_2012_Paper.pdf"}],"pyqYears":["2012"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9457, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 571, '{"id":9457,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":571,"q":"Van Nuys prognostic index is not based on:","o":["Age","Microcalcification","Size","ER status"],"a":3,"e":"Answer: D. ER status DCIS may be classified using the Van Nuys system, which combines the","pyqMatches":[{"year":"2018","no":148,"q":"Van Nuys prognostic index is not based on:","o":["Age","Microcalcification","Size","ER status"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9458, 'Surgery', 'Hepatobiliary & Pancreas', 'Easy', 'Surgery', 572, '{"id":9458,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Easy","source":"Surgery","sourceNo":572,"q":"Common cause of chronic pancreatitis","o":["Chronic alcohol","Chronic pancreatic calculi","pancreas divisum","Gall bladder stones"],"a":0,"e":"Answer: A. Chronic alcohol \"Worldwide, alcohol consumption and abuse is associated with chronic pancreatitis in up to 70% of cases \"​","pyqMatches":[{"year":"2018","no":149,"q":"Common cause of chronic pancreatitis","o":["Chronic alcohol","Chronic pancreatic calculi","pancreas divisum","Gall bladder stones"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9459, 'Surgery', 'General Principles & Wounds', 'Easy', 'Surgery', 573, '{"id":9459,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Easy","source":"Surgery","sourceNo":573,"q":"The following statement about Keloid is true","o":["It contain growth factor","Extended excision is the treatment of choice","It do not extend beyond the wound","None of the above"],"a":0,"e":"Answer: A. It contain growth factor Vaccinations, injections, insect bites, ear piercing, or may arise spontaneously. Keloids tend to occur 3 months to years after the initial insult, and even minor injuries can result in large lesions. They vary in size from a few millimeters to large, pedunculated lesions with a soft to rubbery or hard consistency. Although they project above surrounding skin, they rarely extend into underlying subcutaneous tissues. Certain body sites have a higher incidence of keloid formation, including the skin of the earlobe as well as the deltoid, presternal, and upper back regions. They rarely occur on eyelids, genitalia, palms, soles, or across joints. Keloids rarely involute spontaneously, whereas surgical intervention can lead to recurrence, often with a worse result.","pyqMatches":[{"year":"2012","no":1097,"q":"The following statement about keloid is true ?","o":["They do not extend into normal skin","Local recurrence is common after excision","They often undergo malignant change","They are more common in whites than in blacks"],"a":1,"source":"NEET_2012_Paper.pdf"},{"year":"2018","no":150,"q":"The following statement about Keloid is true","o":["It contain growth factor","Extended excision is the treatment of choice","It do not extend beyond the wound","None of the above"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2012","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9460, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 574, '{"id":9460,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":574,"q":"Which of the following layers are cut during fasciotomy ?","o":["Skin","Skin+subcutaneous fascia","Skin+subcutaneous tissue+Superficial fascia","Skin+subcutaneous tissue+Superficial fascia+deep fascia"],"a":3,"e":"Answer: D. Skin+subcutaneous tissue+Superficial fascia+deep fascia Fasciotomy or fasciectomy is a surgical procedure where complete opening of all fascial envelope is done to relieve tension or pressure commonly to treat the resulting loss of circulation to an area of tissue or muscle. Fasciotomy is a limb-saving procedure when used to treat acute compartment syndrome.","pyqMatches":[{"year":"2017","no":166,"q":"Which of the following layers are cut during fasciotomy ?","o":["Skin","Skin+subcutaneous fascia","Skin+subcutaneous tissue+Superficial fascia","Skin+subcutaneous tissue+Superficial fascia+deep fascia"],"a":3,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":151,"q":"Which of the following layers are cut during fasciotomy ?","o":["Skin","Skin+subcutaneous fascia","Skin+subcutaneous tissue+Superficial fascia","Skin+subcutaneous tissue+Superficial fascia+deep fascia"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9461, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'Surgery', 575, '{"id":9461,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":575,"q":"Which statement is not true regarding crohn''s disease :","o":["Rectum is not involved","Continuous lesion visualized in endoscopy","Non caseating granulomas","Cobblestone appearance"],"a":1,"e":"Answer: B. Continuous lesion visualized in endoscopy Crohn''s disease is frequently associated with \"skip lesions,\" discontinuous areas of active disease in the colon and small intestine with intervening segments that appear normal.","pyqMatches":[{"year":"2017","no":167,"q":"Which statement is not true regarding crohn''s disease :","o":["Rectum is not involved","Continuous lesion visualized in endoscopy","Non caseating granulomas","Cobblestone appearance"],"a":1,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":152,"q":"Which statement is not true regarding crohn''s disease :","o":["Rectum is not involved","Continuous lesion visualized in endoscopy","Non caseating granulomas","Cobblestone appearance"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9462, 'Surgery', 'Hepatobiliary & Pancreas', 'Easy', 'Surgery', 576, '{"id":9462,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Easy","source":"Surgery","sourceNo":576,"q":"Which is the best investigation for carcinoma head of pancreas:","o":["Guided biopsy","ERCP","Transduodenal/transperitoneal sampling","EUS"],"a":3,"e":"Answer: D Medical imaging techniques, such as computed tomography (CT scan) and endoscopic ultrasound (EUS) are used both to confirm the diagnosis and to help decide whether the tumor can be surgically removed","pyqMatches":[{"year":"2017","no":168,"q":"Which is the best investigation for carcinoma head of pancreas:","o":["Guided biopsy","ERCP","Transduodenal/transperitoneal sampling","EUS"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":153,"q":"Which is the best investigation for carcinoma head of pancreas:","o":["Guided biopsy","ERCP","Transduodenal/transperitoneal sampling","EUS"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9463, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 577, '{"id":9463,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":577,"q":"An abdominal mass is best demonstrated in congenital hypertrophic pyloric stenosis by:","o":["In palpation over the epigastrium","In left hypochondriac","Right iliac fossa","During feeding"],"a":3,"e":"Answer: D. During feeding Congenital hypertrophic pyloric stenosis Presentation Vomiting is the presenting symptom (child vomits milk and no bile is present) Immediately after vomiting the child is hungry i.e. loss of appetite does not occur. Weight loss is striking and rapidly the infant becomes emaciated and dehydrated. However, greater awareness of pyloric stenosis has led to earlier identification of patients and hence with fewer incidences of chronic malnutrition and severe dehydration - Nelson 10th/1130 The diagnosis is usually made with a test feed: In this, the baby is fed with the bottle by a nurse or mother and surgeon : IHPS/CHPS can be diagnosed clinically. During a test feed, there is visible gastric peristalsis passing from left to right across the upper abdomen and in a relaxed baby, the pyloric ''tumor'' is palpable as an ''olive'' in the right upper quadrant. The diagnosis can be confirmed by an ultrasound, which shows the thickened pyloric muscle.","pyqMatches":[{"year":"2018","no":154,"q":"An abdominal mass is best demonstrated in congenital hypertrophic pyloric stenosis by:","o":["In palpation over the epigastrium","In left hypochondriac","Right iliac fossa","During feeding"],"a":3,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9464, 'Surgery', 'Neurosurgery', 'Hard', 'Surgery', 578, '{"id":9464,"subject":"Surgery","chapter":"Neurosurgery","difficulty":"Hard","source":"Surgery","sourceNo":578,"q":"Calculate GCS of 25 year old head injury patient with following parameters confused, opening eyes in response to pain, localizing pain will be-","o":["6","11","12","7"],"a":1,"e":"Answer: B. 11 Glasgow coma scale:","pyqMatches":[{"year":"2018","no":155,"q":"Calculate GCS of 25 year old head injury patient with following parameters confused, opening eyes in response to pain, localizing pain will be","o":["6","11","12","7"],"a":1,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9465, 'Surgery', 'Endocrine Surgery', 'Easy', 'Surgery', 579, '{"id":9465,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Easy","source":"Surgery","sourceNo":579,"q":"RET proto-oncogene is associated with the development of","o":["Medullary carcinoma thyroid","Astrocytoma","Paraganglioma","Hurthle cell tumor thyroid"],"a":0,"e":"Answer: A. Medullary carcinoma thyroid RET proto-oncogene is a growth factor receptor (receptor tyrosine kinase) The RET protein is a receptor for the glial cell line-derived neurotrophic factor and structurally related proteins that promote cell survival during neural development. RET is normally expressed in the following cells Parafollicular C cells of the thyroid Adrenal medulla Medullary carcinoma may occur in combination with adrenal phaeochromocytoma and hyperparathyroidism (HPT) (usually due to hyperplasia) in the syndrome known as multiple endocrine neoplasia type 2A (MEN-2A). These are tumors of the parafollicular (C cells) derived from the neural crest rather than the cells of the thyroid follicle as are other primary thyroid carcinomas When the familial form is associated with prominent mucosal neuromas involving the lips, tongue and inner aspect of the eyelids, with a Marfanoid habitus, the syndrome is referred to as MEN type 2B. RET associations: MEN 2a, MEN 2b, Familial medullary carcinoma thyroid.","pyqMatches":[{"year":"2018","no":156,"q":"RET proto-oncogene is associated with the development of","o":["Medullary carcinoma thyroid","Astrocytoma","Paraganglioma","Hurthle cell tumor thyroid"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9466, 'Surgery', 'Vascular Surgery', 'Hard', 'Surgery', 580, '{"id":9466,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Hard","source":"Surgery","sourceNo":580,"q":"Cutoff for surgery in an abdominal aortic aneurysm in asymptomatic patients-","o":["5.5cm","6.5cm","7.5cm","8.5cm"],"a":0,"e":"Answer: A. 5.5cm Operative repair of the aneurysm with the insertion of a prosthetic graft or endovascular placement of aortic stent graft is indicated for: Abdominal aortic aneurysms of any size that are expanding rapidly or are associated with symptoms. For asymptomatic aneurysms, abdominal aortic aneurysm repair is indicated if the diameter is >5.5 cm.","pyqMatches":[{"year":"2018","no":157,"q":"Cutoff for surgery in an abdominal aortic aneurysm in asymptomatic patients","o":["5.5cm","6.5cm","7.5cm","8.5cm"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9467, 'Surgery', 'General Principles & Wounds', 'Moderate', 'Surgery', 581, '{"id":9467,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Moderate","source":"Surgery","sourceNo":581,"q":"In ACLS which drug can be given following ventricular fibrillation after cardiac arrest other than epinephrine?","o":["Amiodarone","Dopamine","Adenosine","Atropine"],"a":0,"e":"Ans. A. Amiodarone V-Fib or VF is the most common rhythm that occurs immediately after cardiac arrest. In this rhythm, the heart beats with rapid, erratic electrical impulses. Treatment: Shock / Defibrillation: every 2 minutes in a single one shock, successive, shockable increments 200 joules - Followed by immediate CPR for 2 minutes / give and circulate a drug(s) 300 joules - Followed by immediate CPR for 2 minutes / give and circulate a drug(s) 360 joules - Followed by immediate CPR for 2 minutes / give and circulate a drug(s) Drugs : Give Epinephrine 1mg of a 1:10,000 solu,on every 3 to 5 minutes [No Limit] Give either: Amiodarone [if not contraindicated, can be given 2x]: 300mg first dose / 150mg second dose at 3 to 5 minutes increments. Lidocaine: First dose: 1mg/kg or 1.5 mg/kg. Can repeat it at half the original dose up to a total of 3 mg/kg [Second and remaining doses are given at either 0.5mg/kg or 0.75mg/kg depending on your star,ng dosage.]","pyqMatches":[{"year":"2018","no":259,"q":"In ACLS which drug can be given following ventricular fibrillation after cardiac arrest other than epinephrine?","o":["Amiodarone","Dopamine","Adenosine","Atropine"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9468, 'Surgery', 'General Principles & Wounds', 'Hard', 'Surgery', 582, '{"id":9468,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Hard","source":"Surgery","sourceNo":582,"q":"A 6-year-old boy experienced life threatening shock ,his CT scan showed large amount of ascites, bowel wall thickening and poor or absent enhancement of the strangulated bowel segment, showing gangrenous bowel on surgical exploration. True about anastomosis is-","o":["Should be done by continuous layers as it takes less time","Should be Done with catgut","Should be Done by single layer seromuscular lembert sutures","Should be Done by Single layer taking submucosa"],"a":2,"e":"Ans C. Should be Done by single layer seromuscular lembert sutures Diagnosis is of congenital IH with strangulated small bowel with gangrenous small bowel Transmesenteric hernia was the most common type in older children as well as in neonates . IH results from incomplete closure of surgically created mesenteric defects, and usually acquired resulting from previous abdominal surgery especially Roux-en-Y anastomosis Anastomosis should be done by single layer seromuscular lembert sutures The Lambert suture generally is used in abdominal surgery. It is an inverting suture, that can be either continuous or interrupted, used to g , p , join two segments of an intestine without entering the lumen (the inner channel through which stomach contents flow).","pyqMatches":[{"year":"2018","no":258,"q":"A 6-year-old boy experienced life threatening shock ,his CT scan showed large amount of ascites, bowel wall thickening and poor or absent enhancement of the strangulated bowel segment, showing gangrenous bowel on surgical exploration. True about anastomosis is","o":["Should be done by continuous layers as it takes less time","Should be Done with catgut","Should be Done by single layer seromuscular lembert sutures","Should be Done by Single layer taking submucosa"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9469, 'Surgery', 'Vascular Surgery', 'Easy', 'Surgery', 583, '{"id":9469,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Easy","source":"Surgery","sourceNo":583,"q":"Which of the following is the best Stent for Femoropopliteal Bypass?","o":["Dacron","Reversed saphenous","PTFE","None"],"a":2,"e":"Answer: C- PTFE-covered self-expanding nitinol stents PTFE-covered stents are engineered with a 30–100-micron pore size to allow for the endothelial lining of the stent-graft and vessel healing. The two main graft types used for lower extremity bypasses are the great saphenous veins and polytetrafluoroethylene (PTFE) grafts. One of the most widely used stent-grafts in the treatment of chronic lower extremity ischemia is the Viabahn endoprosthesis (Gore Medical, Flagstaff, Ariz). It is constructed with expanded polytetrafluoroethylene (ePTFE) liner attached to an external nitinol stent. The inner surface is bonded with heparin.","pyqMatches":[{"year":"2018","no":281,"q":"Which of the following is the best Stent for Femoropopliteal Bypass?","o":["Dacron","Reversed saphenous","PTFE","None"],"a":2,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9470, 'Surgery', 'Neurosurgery', 'Easy', 'Surgery', 584, '{"id":9470,"subject":"Surgery","chapter":"Neurosurgery","difficulty":"Easy","source":"Surgery","sourceNo":584,"q":"Maastricht classification of donation after cardiac death.What category is stage 3 ?","o":["Awaiting cardiac arrest","Brought in dead","Unsuccessful resuscitation","Cardiac arrest after brain-stem death"],"a":0,"e":"Answer: A>Awaiting cardiac arrest The first level of definition is simple and based on whether the situation is uncontrolled (categories I and II) or controlled (categories III, IV, and V). Category I, the patient is declared \"dead on arrival\" and, Category II, there is an \"unsuccessful resuscitation\" whether it occurred out or in the hospital for both situations. Category III is the most usual situation in which the treating physician and family are \"awaiting cardiac arrest\" to declare the death of the patient. Category IV is always characterized by \"cardiac arrest during brain death.\" The special situation of the Belgian law allowing the euthanasia is elaborated Category V \"euthanasia,\" and includes patients who grant access to medically assisted circulatory death. Organ donation after euthanasia is allowed under the scope of donation after circulatory","pyqMatches":[{"year":"2017","no":286,"q":"Maastricht classification of donation after cardiac death.What category is stage 3 ?","o":["Awaiting cardiac arrest","Brought in dead","Unsuccessful resuscitation","Cardiac arrest after brain-stem death"],"a":0,"source":"Neet 2017 paper(1).pdf"},{"year":"2018","no":245,"q":"Maastricht classification of donation after cardiac death.What category is stage 3 ?","o":["Awaiting cardiac arrest","Brought in dead","Unsuccessful resuscitation","Cardiac arrest after brain-stem death"],"a":0,"source":"NEET_Jan_2018_Paper.pdf"}],"pyqYears":["2017","2018"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9471, 'Surgery', 'General Principles & Wounds', 'Hard', 'Surgery', 585, '{"id":9471,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Hard","source":"Surgery","sourceNo":585,"q":"A patient arrived in ER following an RTA with hypotension, respiratory distress and subcutaneous emphysema with no entry of air on one side. What will be the best management?","o":["Needle decompression in 5th intercostal space in the midaxillary line","Continue PPV","Shift to ICU and incubate","Secure IV line and start fluid resuscitation after insertion of the wide-bore IV line"],"a":0,"e":"Ans- A. Needle decompression in 5th intercostal space in the midaxillary line A tension pneumothorax develops when a ''one-way valve'' air leak occurs either from the lung or through the chest wall. Air is sucked into the thoracic cavity without any means of escape, completely collapsing then compressing the affected lung. Etiology- The most common causes are penetrating chest trauma, blunt chest trauma with parenchymal lung injury and air leak that did not spontaneously close, iatrogenic lung injury (e.g. due to central venepuncture) and mechanical positive pressure ventilation. C/F- The patient is increasingly restless with tachypnoea, dyspnoea and distended neck veins Treatment- Treatment consists of immediate decompression, initially by rapid insertion of a large-bore cannula into the second intercostal space in the midclavicular line of the affected side, then followed by insertion of a chest tube through the fifth intercostal space in the anterior axillary line. Ref- Bailey and Love, Short practice of surgery, 27th edition published in 2018 Pg 367, 920","pyqMatches":[{"year":"2020","no":173,"q":"A patient arrived in ER following an RTA with hypotension, respiratory distress and subcutaneous emphysema with no entry of air on one side. What will be the best management?","o":["Needle decompression in 5th intercostal space in the midaxillary line","Continue PPV","Shift to ICU and incubate","Secure IV line and start fluid resuscitation after insertion of the wide-bore IV line"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9472, 'Surgery', 'Endocrine Surgery', 'Easy', 'Surgery', 586, '{"id":9472,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Easy","source":"Surgery","sourceNo":586,"q":"Treatment of Renal cell carcinoma of less than 4 cm will be-","o":["Partial nephrectomy","Radical nephrectomy","Radical nephrectomy + postoperative radiotherapy","Radical nephrectomy + chemotherapy"],"a":0,"e":"Ans: A. Partial nephrectomy Partial nephrectomy is now being used as primary surgical therapy for patients with a tumor less than 4 cm in size. Earlier Radical nephrectomy was the treatment of choice for tumors of any size. Classic radical nephrectomy consists of removal of the kidney, perirenal fat, adrenal gland, and regional lymph nodes. Most stage I and stage II tumors. Partial nephrectomy- is indicated for patients with a T1 tumor (according to the UICC TNM staging system) and a normal contralateral kidney. Intervention should be considered for growth to >3-4cm or by >O.5cm per year. Stage T1aN0M0 Partial nephrectomy recommended. This can be done via open/laparoscopic/robotic procedures Stage T1bN0M0 PN (open/laparoscopic/robotic) in cases where technically feasible Laparoscopic RN should be offered if a PN is not feasible Open RN if laparoscopic surgery is not possible. Stage T2N0M0 RN – open/laparoscopic/robotic PN – open/laparoscopic/robotic Stage T3 RN – open, laparoscopic or robotic-assisted Resection of vascular thrombosis when applicable (usually open) Resection of all gross disease including hilar or retroperitoneal extension PN may be attempted in highly selected cases by experienced surgeons Ref- Bailey and Love, Short practice of surgery, 27th edition published in 2018 Pg 1420 https://www.researchgate.net/publication/263933944_Surgical_man","pyqMatches":[{"year":"2020","no":174,"q":"Treatment of Renal cell carcinoma of less than 4 cm will be","o":["Partial nephrectomy","Radical nephrectomy","Radical nephrectomy + postoperative radiotherapy","Radical nephrectomy + chemotherapy"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9473, 'Surgery', 'General Principles & Wounds', 'Moderate', 'Surgery', 587, '{"id":9473,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Moderate","source":"Surgery","sourceNo":587,"q":"Which is not seen in Asepsis score-","o":["Erythema","Induration","Serous discharge","Purulent exudate"],"a":1,"e":"Answer- B. Induration Criterion Points Additional treatment Antibiotics for wound infection Drainage of pus under local anaesthesia Debridement of wound under general anaesthesia 0 10 5 10 Serous discharge Daily 0-5 Erythema Daily 0-5 Purulent exudate Daily 0-10 Separation of deep tissues Daily 0-10 Isolation of bacteria from wound 10 Stay as inpatient prolonged over 14 days as result of ound infection 5 Ref- Bailey and Love, Short practice of surgery, 27th edition published in 2018 Pg 48","pyqMatches":[{"year":"2020","no":175,"q":"Which is not seen in Asepsis score","o":["Erythema","Induration","Serous discharge","Purulent exudate"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9474, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 588, '{"id":9474,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":588,"q":"Esophageal manometry was performed - it revealed panesophageal pressurization with distal contractile integrity as >450mm Hg pressure in the body. What will be the diagnosis?","o":["Type 1 achalasia","Type 2 achalasia","Type 3 achalasia","Jackhammer esophagus"],"a":2,"e":"Ans: C. Type 3 achalasia Type I achalasia (classic achalasia)- Elevated median IRP (>15 mmHg), 100% failed peristalsis (DCl <100 mmHg.s.cm) Premature contractions with DCI values <450 mmHg.s.cm satisfy criteria for failed peristalsis Type II achalasia (with esophageal compression)- Elevated median IRP (>15 mmHg), 100% failed peristalsis, panesophageal pressurisation with >20% of swallows. Contractions may be masked by oesophageal pressurization and DCI should not be calculated. Type lll achalasia (spastic achalasia) Elevated median IRP (>15 mmHg), no normal peristalsis, premature (spastic) contractions with DCI >450 mmHg.s.cm with >20% of swallows May be mixed with panesophageal pressurization ''Diffuse esophageal spasm'' and jackhammer (nutcracker) esophagus- Spastic pressures on manometry of 400-500mmHg marked hypertrophy of the circular muscle and a corkscrew esophagus on barium swallow. Ref-Bailey and Love, Short practice of surgery, 27th edition published in 2018 Pg 1096, 1099","pyqMatches":[{"year":"2020","no":176,"q":"Esophageal manometry was performed - it revealed panesophageal pressurization with distal contractile integrity as >450mm Hg pressure in the body. What will be the diagnosis?","o":["Type 1 achalasia","Type 2 achalasia","Type 3 achalasia","Jackhammer esophagus"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9475, 'Surgery', 'Vascular Surgery', 'Hard', 'Surgery', 589, '{"id":9475,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Hard","source":"Surgery","sourceNo":589,"q":"What will be the appropriate management for Abdominal aortic aneurysm-","o":["Monitor till size reaches 55mm","Immediate surgery","USG monitoring till >70mm asymptomatic","No treatment"],"a":0,"e":"Answer- A. Monitor till size reaches 55mm An asymptomatic abdominal aortic aneurysm in an otherwise fit patient should be considered for repair if >55mm in diameter (measured by ultrasonography). Regular ultrasonographic assessment is indicated for asymptomatic aneurysms <55 mm in diameter. 75% of aneurysms are suitable for endovascular (minimally invasive) repair, usually via the femoral arteries in the groin. Ruptured abdominal aortic aneurysm is a surgical emergency. Symptomatic AAA- An operation is usually indicated in patients who are otherwise reasonably fit. Pain may be a warning sign of stretching of the aneurysm sac and imminent rupture; surgery should be performed as soon as possible (usually on the next available operating list). Ref- Bailey and Love, Short practice of surgery, 27th edition published in 2018 Pg 961","pyqMatches":[{"year":"2020","no":177,"q":"What will be the appropriate management for Abdominal aortic aneurysm","o":["Monitor till size reaches 55mm","Immediate surgery","USG monitoring till >70mm asymptomatic","No treatment"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9476, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 590, '{"id":9476,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":590,"q":"What is the T stage of a 2.5cm lung carcinoma, not involving the pleura?","o":["T1a","T2","T1b","T1c"],"a":3,"e":"Ans: D. T1c Ref- Bailey and Love, Short practice of surgery, 27th edition published in 2018 Pg 927","pyqMatches":[{"year":"2020","no":178,"q":"What is the T stage of a 2.5cm lung carcinoma, not involving the pleura?","o":["T1a","T2","T1b","T1c"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9477, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 591, '{"id":9477,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":591,"q":"In, the primary survey which is not included-","o":["CECT to look for bleeding","Exposure of the whole body","ABC","Recording BP"],"a":0,"e":"Answer – A. CECT to look for bleeding The primary survey aims to identify and manage the most immediately life-threatening pathologies first and follows cABCDE.","pyqMatches":[{"year":"2020","no":179,"q":"In, the primary survey which is not included","o":["CECT to look for bleeding","Exposure of the whole body","ABC","Recording BP"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9478, 'Surgery', 'Gastrointestinal Surgery', 'Easy', 'Surgery', 592, '{"id":9478,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Easy","source":"Surgery","sourceNo":592,"q":"MC location of gastrinoma in MEN-1 syndrome?","o":["Duodenum","Jejunum","Pancreas","Ileum"],"a":0,"e":"Answer- A. Duodenum PETs occur in around 50-60Vo of MEN 1 patients. The most common functional tumour is gastrinoma in duodenum followed by insulinoma. Ref- Bailey and Love, Short practice of surgery, 27th edition published in 2018 Pg 856","pyqMatches":[{"year":"2020","no":180,"q":"MC location of gastrinoma in MEN-1 syndrome?","o":["Duodenum","Jejunum","Pancreas","Ileum"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9479, 'Surgery', 'Urology', 'Hard', 'Surgery', 593, '{"id":9479,"subject":"Surgery","chapter":"Urology","difficulty":"Hard","source":"Surgery","sourceNo":593,"q":"Patients have precancerous lesions with abdominal swelling and inguinal nodes are seen. On examination, lymphadenopathy was found. The most probable carcinoma related to this condition will be?","o":["ca penis","CaTestis","ca prostate","ca bladder"],"a":0,"e":"Answer- A. ca penis Cancer penis spreads to inguinal nodes. A mass, pruritus or discharge is common. Advanced tumours may cause fecal incontinence by the invasion of the sphincters. Anal canal tumours are palpable and irregular indurated tender ulceration. Sphincter involvement may be evident. Ref- Bailey and Love, Short practice of surgery, 27th edition published in 2018 Pg 1371","pyqMatches":[{"year":"2020","no":181,"q":"Patients have precancerous lesions with abdominal swelling and inguinal nodes are seen. On examination, lymphadenopathy was found. The most probable carcinoma related to this condition will be?","o":["ca penis","CaTestis","ca prostate","ca bladder"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9480, 'Surgery', 'General Principles & Wounds', 'Hard', 'Surgery', 594, '{"id":9480,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Hard","source":"Surgery","sourceNo":594,"q":"A man under alcohol intoxication had fallen into a manhole and had a perineal injury with swollen scrotum and upper thigh along with blood at meatus. The patient is having difficulty passing urine as well. What will be the injury associated due to this trauma?","o":["Bladder rupture","Penile fracture","Bulbar urethra","Membranous urethra"],"a":2,"e":"Answer- C. Bulbar urethra There is a history of a blow to the perineum, usually due to a fall astride injury. The bulbar urethra is crushed upwards onto the pubic bone, typically with significant bruising. Cycling accidents, loose manhole covers and gymnasium accidents astride the beam account for a number of cases.C/F The signs of a ruptured bulbar urethra are perineal bruising and hematoma, typically with a butterfly distribution. There is usually bleeding from the urethral meatus and retention of urine is also typically present. Ref- Bailey and Love, Short practice of surgery, 27th edition published in 2018 Pg 1479, 1480","pyqMatches":[{"year":"2020","no":182,"q":"A man under alcohol intoxication had fallen into a manhole and had a perineal injury with swollen scrotum and upper thigh along with blood at meatus. The patient is having difficulty passing urine as well. What will be the injury associated due to this trauma?","o":["Bladder rupture","Penile fracture","Bulbar urethra","Membranous urethra"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9481, 'Surgery', 'Vascular Surgery', 'Hard', 'Surgery', 595, '{"id":9481,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Hard","source":"Surgery","sourceNo":595,"q":"Patient with a history of carcinoma bladder presenting with dyspnoea with clinical signs of DVT and tachycardia. The risk for the patient to develop Pulmonary embolism according to WELL''s score","o":["High","Medium","Low","Cannot comment without d-dimer values"],"a":1,"e":"Ans. B. Medium Wells criteria Score High > 6.0 Moderate 2.0 to 6.0 Low < 2.0 Modified Wells criteria Score PE likely > 4.0 PE unlikely < or = 4.0 Modified Wells Criteria for DVT Variable Score Lower limb trauma or surgery or immobilisation in plaster cast 1 Bedridden for >3 days or surgery in the last 4 weeks 1 Tenderness along the line of femoral or popliteal veins 1 Entire limb swollen 1 Calf >3cm larger circumference than the other side 1 10cm below the tibial tuberosity 1 Pitting edema 1 Dilated collateral superficial veins (not varicose veins) 1 Previous DVT 1 Malignancy (including treatment up to 6 months ago) 1 Intravenous drug abuse 3 Alternative diagnosis more likely than DVT -2 Ref- Bailey and Love, Short practice of surgery, 27th edition published in 2018 Pg 988","pyqMatches":[{"year":"2020","no":183,"q":"Patient with a history of carcinoma bladder presenting with dyspnoea with clinical signs of DVT and tachycardia. The risk for the patient to develop Pulmonary embolism according to WELL''s score","o":["High","Medium","Low","Cannot comment without d-dimer values"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9482, 'Surgery', 'Transplantation', 'Hard', 'Surgery', 596, '{"id":9482,"subject":"Surgery","chapter":"Transplantation","difficulty":"Hard","source":"Surgery","sourceNo":596,"q":"After 4 months of renal transplantation, a patient can likely to develop which infection-","o":["EBV","CMV","Candida","Histoplasma"],"a":1,"e":"Answer- B. CMV Causes of allograft dysfunction","pyqMatches":[{"year":"2020","no":184,"q":"After 4 months of renal transplantation, a patient can likely to develop which infection","o":["EBV","CMV","Candida","Histoplasma"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9483, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 597, '{"id":9483,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":597,"q":"The patient is present with fecal peritonitis and during laparotomy, a diverticular perforation is seen. Which stage is classified according to Hinchey’s stage?","o":["1","2","3","4"],"a":3,"e":"Answer- D. 4 Hinchey classification of complicated diverticulitis.","pyqMatches":[{"year":"2020","no":185,"q":"The patient is present with fecal peritonitis and during laparotomy, a diverticular perforation is seen. Which stage is classified according to Hinchey’s stage?","o":["1","2","3","4"],"a":3,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9484, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 598, '{"id":9484,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":598,"q":"A young man met with a motorbike accident and had injuries to ileum and jejunum. Therefore the entire ileum and partial jejunum were resected. Which of the following would the patient suffer from","o":["Vitamin B12 deficiency","Atrophic gastritis","Constipation","None"],"a":0,"e":"Answer- A. Vitamin B12 deficiency The ileum is the only site of absorption of vitamin B12 and bile salts. Bile salts are essential for the absorption of fats and fat-soluble vitamins. Following resection of the ileum, the loss of bile salts increases and is not met by an increase in synthesis. The jejunum is the principal site for digestion and absorption of fluid, electrolytes, iron, folate, fat, protein and carbohydrate, but the absorption of bile salts and vitamin B12 only occurs in the terminal ileum, where there are specific transporters. Ref- Bailey and Love, Short practice of surgery, 27th edition published in 2018 Pg 283, 1241","pyqMatches":[{"year":"2020","no":186,"q":"A young man met with a motorbike accident and had injuries to ileum and jejunum. Therefore the entire ileum and partial jejunum were resected. Which of the following would the patient suffer from","o":["Vitamin B12 deficiency","Atrophic gastritis","Constipation","None"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9485, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 599, '{"id":9485,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":599,"q":"A patient after a heavy meal comes with epigastric pain. On examination tenderness and rigidity in the upper abdomen. X-ray showing pneumomediastinum. What can be the cause-","o":["Spontaneous esophageal rupture","Penetrating foreign body injury to esophagus","Perforated peptic ulcer","Rupture of emphysematous bulla"],"a":0,"e":"Answer- A. Spontaneous esophageal rupture This is a clinical case of spontaneous esophageal rupture/ Boerhaave’s syndrome The clinical history is usually of severe pain in the chest or upper abdomen after a meal or a bout of drinking. Mackler''s triad, which consists of (1) vomiting followed by (2) chest pain and (3) subcutaneous emphysema due to an esophageal rupture. A chest radiograph is often confirmed with air in the mediastinum, pleura or peritoneum. InvestigationsChest X-ray—shows pneumomdiastinum (‘V’ sign of Naclerio). MRI/CT chest. Total count. Ref- Bailey and Love, Short practice of surgery, 27th edition published in 2018 Pg 1073 Sriram Bhat M, SRB''s Manual of Surgery, 4th edition published in 2013, Pg 856","pyqMatches":[{"year":"2020","no":187,"q":"A patient after a heavy meal comes with epigastric pain. On examination tenderness and rigidity in the upper abdomen. X-ray showing pneumomediastinum. What can be the cause","o":["Spontaneous esophageal rupture","Penetrating foreign body injury to esophagus","Perforated peptic ulcer","Rupture of emphysematous bulla"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9486, 'Surgery', 'Transplantation', 'Easy', 'Surgery', 600, '{"id":9486,"subject":"Surgery","chapter":"Transplantation","difficulty":"Easy","source":"Surgery","sourceNo":600,"q":"Transplantation between identical twins-","o":["Isograft","Allograft","Autograft","Xenograft"],"a":0,"e":"Answer- A. Isograft Graft: It is the transfer of tissue from one area to another without its blood supply or nerve supply. Autograft: It is tissue transferred from one location to another on the same patient. Isograft: It is tissue transfer between two genetically identical individuals, i.e. between two identical twins. Allograft: It is tissue transfer between two genetically different members, e.g. kidney transplantation (Human to human) (Homograft). Xenograft: It is tissue transfer from a donor of one species to a recipient of another species (Heterograft).","pyqMatches":[{"year":"2020","no":188,"q":"Transplantation between identical twins","o":["Isograft","Allograft","Autograft","Xenograft"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9487, 'Surgery', 'Miscellaneous', 'Moderate', 'Surgery', 601, '{"id":9487,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Moderate","source":"Surgery","sourceNo":601,"q":"Thoracoscore , what is not the component","o":["ASA CLASSIFICATIONS","SURGERY PRIORITIES","Performance status","Expected complications post-surgery"],"a":1,"e":"Answer- B. SURGERY PRIORITIES The Thoracoscore is the most widely used model to assess the risk of operative mortality in thoracic patients Ref- Bailey and Love, Short practice of surgery, 27th edition published in 2018 Pg 915","pyqMatches":[{"year":"2020","no":189,"q":"Thoracoscore , what is not the component","o":["ASA CLASSIFICATIONS","SURGERY PRIORITIES","Performance status","Expected complications post-surgery"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9488, 'Surgery', 'Endocrine Surgery', 'Easy', 'Surgery', 602, '{"id":9488,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Easy","source":"Surgery","sourceNo":602,"q":"Retrosternal goiter which is true?","o":["All patients should undergo CT chest","All patients require a median sternotomy","it receives blood supply from thoracic vessels","Majority of retrosternal goitres should be operated immediately"],"a":0,"e":"Answer- A. All patients should undergo CT chest Retro sternal goitre tends to arise from the slow growth of a multinodular gland down into the mediastinum. It gets its blood supply from the mediastinum itself, not from the neck. Investigations A chest X-ray shows a soft tissue shadow under the sternum. A radioactive iodine study is diagnostic. CT scan/ MRI is useful and all patients should undergo it. Surgical removal of retrosternal thyroid is done. (TOC) Commonly it can be removed through an incision in the neck. Ref- Bailey and Love, Short practice of surgery, 27th edition published in 2018 Pg 810 Sriram Bhat M, SRB''s Manual of Surgery, 4th edition published in 2013, Pg 498","pyqMatches":[{"year":"2020","no":190,"q":"Retrosternal goiter which is true?","o":["All patients should undergo CT chest","All patients require a median sternotomy","it receives blood supply from thoracic vessels","Majority of retrosternal goitres should be operated immediately"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9489, 'Surgery', 'Hepatobiliary & Pancreas', 'Moderate', 'Surgery', 603, '{"id":9489,"subject":"Surgery","chapter":"Hepatobiliary & Pancreas","difficulty":"Moderate","source":"Surgery","sourceNo":603,"q":"True for King''s Criteria with acute fulminant liver failure except-","o":["Age","Jaundice <7days","Serum bilirubin >17.5 mg/dl","INR >3.5"],"a":1,"e":"Answer- B. Jaundice <7days King''s College criteria for liver transplantation in AHF. APAP-associated AHF- pH?<?7.3 or INR?>?6.5, serum creatinine >3.4 mg/dl, and grade III-IV encephalopathy All other causes of AHF INR >6.5 Or Three of the following variables:","pyqMatches":[{"year":"2020","no":191,"q":"True for King''s Criteria with acute fulminant liver failure except","o":["Age","Jaundice <7days","Serum bilirubin >17.5 mg/dl","INR >3.5"],"a":1,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9490, 'Surgery', 'Gastrointestinal Surgery', 'Hard', 'Surgery', 604, '{"id":9490,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Hard","source":"Surgery","sourceNo":604,"q":"A patient who was posted for elective inguinal hernia surgery has history MI for which he underwent CABG. What will you do in pre operative assessment?","o":["History + c/e + routine labs + angiography to look for stent patency","History + c/e + routine labs","History + c/e + routine labs + stress test","History +c/e + routine labs + V/Q scan"],"a":2,"e":"Answer- C. History + c/e + routine labs + stress test In the given scenario the patient had undergone CABG not an angioplasty, so the first option is ruled out. With routine lab tests, the stress test should be included to check the cardiac function as pre operative assessment","pyqMatches":[{"year":"2020","no":192,"q":"A patient who was posted for elective inguinal hernia surgery has history MI for which he underwent CABG. What will you do in pre operative assessment?","o":["History + c/e + routine labs + angiography to look for stent patency","History + c/e + routine labs","History + c/e + routine labs + stress test","History +c/e + routine labs + V/Q scan"],"a":2,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9491, 'Surgery', 'General Principles & Wounds', 'Hard', 'Surgery', 605, '{"id":9491,"subject":"Surgery","chapter":"General Principles & Wounds","difficulty":"Hard","source":"Surgery","sourceNo":605,"q":"History of trauma with a stab injury to the right lower chest with low BP and low pulse rate. It can be improved with IV fluids and after resuscitation in the trauma center patient’s BP becomes normal. A chest X-ray showed clear lung fields. What will be the next step-","o":["EFAST","Keep immediate chest tube","CECT abdomen","CECT chest"],"a":0,"e":"Answer- A. EFAST Investigations are driven by the cardiovascular status of the patient. In torso trauma, the best and most sensitive modality is a CT scan with intravenous contrast for blunt injury if the patient is stable. Routine investigation in the emergency department of injury to the chest is based on clinical examination, supplemented by chest radiography. Ultrasound can be used to differentiate between contusion and the actual presence of blood. Extended focused assessment with sonar for trauma (eFAST) is becoming the most common investigation. Ref- Bailey and Love, Short practice of surgery, 27th edition published in 2018 Pg 366, 372","pyqMatches":[{"year":"2020","no":193,"q":"History of trauma with a stab injury to the right lower chest with low BP and low pulse rate. It can be improved with IV fluids and after resuscitation in the trauma center patient’s BP becomes normal. A chest X-ray showed clear lung fields. What will be the next step","o":["EFAST","Keep immediate chest tube","CECT abdomen","CECT chest"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9492, 'Surgery', 'Endocrine Surgery', 'Hard', 'Surgery', 606, '{"id":9492,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Hard","source":"Surgery","sourceNo":606,"q":"In a patient with parathyroid adenoma, how do we confirm the removal of the correct gland after surgery?","o":["50% reduction in PTH after 10mins","50% reduction in PTH after 5mins","25% reduction in PTH after 10mins","25% reduction in PTH after 5mins"],"a":0,"e":"Answer- A. 50% reduction in PTH after 10mins Miami criteria The IOPTH values at baseline (pre-incision and pre excision) and at 5 and 10 minutes after parathyroidectomy were reviewed according to the Miami criterion (>50% drop from highest baseline IOPTH level at 10 minutes after excision), criterion 1 (>50% drop from pre- incision IOPTH level at 10 minutes), criterion 2 (>50% drop from the highest baseline IOPTH level at 10 minutes and final IOPTH level within the reference range), criterion 3 (>50% drop from the highest baseline IOPTH level at 10 minutes and final IOPTH level less than the pre-incision value), criterion 4 (>50% drop from the highest baseline IOPTH level at 5 minutes), and criterion 5 (>50% drop from pre excision IOPTH level at 10 minutes). Ref- https://www.ncbi.nlm.nih.gov/pubmed/16702520","pyqMatches":[{"year":"2020","no":194,"q":"In a patient with parathyroid adenoma, how do we confirm the removal of the correct gland after surgery?","o":["50% reduction in PTH after 10mins","50% reduction in PTH after 5mins","25% reduction in PTH after 10mins","25% reduction in PTH after 5mins"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9493, 'Surgery', 'Breast Surgery', 'Easy', 'Surgery', 607, '{"id":9493,"subject":"Surgery","chapter":"Breast Surgery","difficulty":"Easy","source":"Surgery","sourceNo":607,"q":"Flap commonly used in breast reconstruction is?","o":["DIEP based on deep inferior epigastric vessels","TRAM based on superior gluteal vessels","Gluteal flap based on thoracodorsal artery","Latissimus dorsi flap based on the inferior epigastric artery"],"a":0,"e":"Answer- A. DIEP based on deep inferior epigastric vessels DIEP flap (based on deep inferior epigastric vessels) TRAM flap based on It is either superior pedicle based on the superior epigastric vessels or inferior pedicle based on the inferior epigastric vessels. Latissimus dorsi muscle/myocutaneous flap It is based on the thoracodorsal artery, a branch of the subscapular artery Superior gluteal flap based on superior gluteal vessels. Ref- Bailey and Love, Short practice of surgery, 27th edition published in 2018 Pg 879 Sriram Bhat M, SRB''s Manual of Surgery, 4th edition published in 2013, Pg 350, 594","pyqMatches":[{"year":"2014","no":1574,"q":"Flap commonly used in breast reconstruction is?","o":["Serratus anterior","TRAM","Flap from arm","Delto pectoral flap"],"a":1,"source":"NEET_2014_Paper.pdf"},{"year":"2020","no":195,"q":"Flap commonly used in breast reconstruction is?","o":["DIEP based on deep inferior epigastric vessels","TRAM based on superior gluteal vessels","Gluteal flap based on thoracodorsal artery","Latissimus dorsi flap based on the inferior epigastric artery"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2014","2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9494, 'Surgery', 'Vascular Surgery', 'Moderate', 'Surgery', 608, '{"id":9494,"subject":"Surgery","chapter":"Vascular Surgery","difficulty":"Moderate","source":"Surgery","sourceNo":608,"q":"A 30-year-old man is presented with cramping gluteal pain after walking 500m. Which is the vessel involved during this?","o":["Arterial disease with aortoiliac involvement","Arterial disease with femoral artery involvement","Femoral venous insufficiency","None"],"a":0,"e":"Answer- A. Arterial disease with aortoiliac involvement The muscle group affected by claudication is classically one anatomical level below the level of arterial disease and is usually felt in the calf because the superficial femoral artery is the most commonly affected artery (70% of cases). Aorto-iliac disease (30% of cases) may cause thigh or buttock claudication. Buttock claudication in association with sexual impotence resulting from arterial insufficiency is eponymously called Leriche''s syndrome. It is very rare. Ref- Bailey and Love, Short practice of surgery, 27th edition published in 2018 Pg 943","pyqMatches":[{"year":"2020","no":196,"q":"A 30-year-old man is presented with cramping gluteal pain after walking 500m. Which is the vessel involved during this?","o":["Arterial disease with aortoiliac involvement","Arterial disease with femoral artery involvement","Femoral venous insufficiency","None"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9495, 'Surgery', 'Miscellaneous', 'Easy', 'Surgery', 609, '{"id":9495,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Easy","source":"Surgery","sourceNo":609,"q":"Which is the most common pancreatic endocrine neoplasm?","o":["Insulinoma","Gastrinoma","VIPoma","Glucagonoma"],"a":0,"e":"Answer- A. Insulinoma Insulinoma (70-80%) > Non functional tumours (30- 35%) > gastrinoma (20- 25%)","pyqMatches":[{"year":"2020","no":197,"q":"Which is the most common pancreatic endocrine neoplasm?","o":["Insulinoma","Gastrinoma","VIPoma","Glucagonoma"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9496, 'Surgery', 'Miscellaneous', 'Hard', 'Surgery', 610, '{"id":9496,"subject":"Surgery","chapter":"Miscellaneous","difficulty":"Hard","source":"Surgery","sourceNo":610,"q":"An elderly man with a long-standing mole over the face which is increasing in size and showing irregular borders. What will be the diagnosis?","o":["Superficial spreading melanoma","Lentigo maligna","Acral melanoma","Nodular melanoma"],"a":0,"e":"Answer- A. Superficial spreading melanoma Superficial spreading melanoma This is the most common presentation (70%) usually arising in a pre- existent naevus after several years of slow change, followed by rapid growth in the preceding months before presentation. Nodular melanoma (NM) Nodular melanoma accounts for l5% ol all MM. Typically appear as blue/black papules, l-2 cm in diameter, and because they lack the horizontal growth phase. Lentigo maligna melanoma- Presents as a slow-growing, variegated brown macule on the face, neck or hands of the elderly. Acral lentiginous melanoma (ALM)ALM affects the soles of feet and palms of hands. It usually presents as a flat, irregular macule in later life. Ref- Bailey and Love, Short practice of surgery, 27th edition published in 2018 Pg 610","pyqMatches":[{"year":"2020","no":198,"q":"An elderly man with a long-standing mole over the face which is increasing in size and showing irregular borders. What will be the diagnosis?","o":["Superficial spreading melanoma","Lentigo maligna","Acral melanoma","Nodular melanoma"],"a":0,"source":"NEET_Jan_2020_Paper.pdf"}],"pyqYears":["2020"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9497, 'Microbiology', 'Virology', 'Moderate', 'NEET PG 2023', 1, '{"id":9497,"subject":"Microbiology","chapter":"Virology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":1,"q":"A patient hailing from Delhi presents with fever, arthralgia, and extensive petechial rash for 3 days. Lab investigations revealed a hemoglobin of 9 g/ dL, a white blood cell count of 9000 cells/mm3, a platelet count of 20000 cells/mm3, and a prolonged bleeding time. The clotting time was normal. What is the most likely diagnosis?","o":["Dengue","Malaria","Scrub typhus","Typhoid"],"a":0,"e":"Correct answer: A. Dengue (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":1,"q":"A patient hailing from Delhi presents with fever, arthralgia, and extensive petechial rash for 3 days. Lab investigations revealed a hemoglobin of 9 g/ dL, a white blood cell count of 9000 cells/mm3, a platelet count of 20000 cells/mm3, and a prolonged bleeding time. The clotting time was normal. What is the most likely diagnosis?","o":["Dengue","Malaria","Scrub typhus","Typhoid"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9498, 'Microbiology', 'Parasitology', 'Moderate', 'NEET PG 2023', 2, '{"id":9498,"subject":"Microbiology","chapter":"Parasitology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":2,"q":"Which of the following statements is true about Trichomonas vaginalis?","o":["It cannot be cultured","Twitching motility is seen on wet saline mount","Cysts are seen on wet saline mount of vaginal secretions","It is not a sexually transmitted infection"],"a":1,"e":"Correct answer: B. Twitching motility is seen on wet saline mount (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":2,"q":"Which of the following statements is true about Trichomonas vaginalis?","o":["It cannot be cultured","Twitching motility is seen on wet saline mount","Cysts are seen on wet saline mount of vaginal secretions","It is not a sexually transmitted infection"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9499, 'Microbiology', 'Parasitology', 'Moderate', 'NEET PG 2023', 3, '{"id":9499,"subject":"Microbiology","chapter":"Parasitology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":3,"q":"A lady from West Rajasthan presented with an ulcer surrounded by erythema on the right leg. Microscopy of the biopsy from the edge of the ulcer showed organisms with dark staining nuclei and kinetoplast. What is the most likely causative agent?","o":["Leishmania tropica","Babesia","Trypanosoma","Histoplasma"],"a":0,"e":"Correct answer: A. Leishmania tropica (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":3,"q":"A lady from West Rajasthan presented with an ulcer surrounded by erythema on the right leg. Microscopy of the biopsy from the edge of the ulcer showed organisms with dark staining nuclei and kinetoplast. What is the most likely causative agent?","o":["Leishmania tropica","Babesia","Trypanosoma","Histoplasma"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9500, 'Microbiology', 'Virology', 'Moderate', 'NEET PG 2023', 4, '{"id":9500,"subject":"Microbiology","chapter":"Virology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":4,"q":"A child presents with a fever and a rash. Urine examination showed cells with owl''s eye appearance. What is the most likely diagnosis?","o":["Cytomegalovirus","Epstein-Barr virus","Herpes simplex virus","Toxoplasma gondii"],"a":0,"e":"Correct answer: A. Cytomegalovirus (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":4,"q":"A child presents with a fever and a rash. Urine examination showed cells with owl''s eye appearance. What is the most likely diagnosis?","o":["Cytomegalovirus","Epstein-Barr virus","Herpes simplex virus","Toxoplasma gondii"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9501, 'Microbiology', 'Parasitology', 'Moderate', 'NEET PG 2023', 5, '{"id":9501,"subject":"Microbiology","chapter":"Parasitology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":5,"q":"Infection with Clonorchis sinensis is associated with an increased risk of__?","o":["Cervical cancer","Cholangiocarcinoma","Gastric carcinoma","Bladder carcinoma"],"a":1,"e":"Correct answer: B. Cholangiocarcinoma (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":5,"q":"Infection with Clonorchis sinensis is associated with an increased risk of__?","o":["Cervical cancer","Cholangiocarcinoma","Gastric carcinoma","Bladder carcinoma"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9502, 'Microbiology', 'Mycology', 'Moderate', 'NEET PG 2023', 6, '{"id":9502,"subject":"Microbiology","chapter":"Mycology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":6,"q":"A patient presented with complaints of persistent cough and weight loss. He had a history of contact with multiple sexual partners. He was diagnosed as HIV positive 6 months back and is poorly adherent to his medications. The fungal culture of sputum was negative. On Gomori methamine silver staining, the cells showed darkly stained crescent-shaped cysts. What is the most likely causative organism?","o":["Paracoccidiodes brasiliensis","Histoplasma capsulatum","Coccidiodes immitis","Pneumocystis jerovecii"],"a":3,"e":"Correct answer: D. Pneumocystis jerovecii (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":6,"q":"A patient presented with complaints of persistent cough and weight loss. He had a history of contact with multiple sexual partners. He was diagnosed as HIV positive 6 months back and is poorly adherent to his medications. The fungal culture of sputum was negative. On Gomori methamine silver staining, the cells showed darkly stained crescent-shaped cysts. What is the most likely causative organism?","o":["Paracoccidiodes brasiliensis","Histoplasma capsulatum","Coccidiodes immitis","Pneumocystis jerovecii"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9503, 'Microbiology', 'Systemic Bacteriology', 'Moderate', 'NEET PG 2023', 7, '{"id":9503,"subject":"Microbiology","chapter":"Systemic Bacteriology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":7,"q":"A sewage worker presented with abdominal pain, jaundice, conjunctival injection, and blood in the urine for the past 5 days. Which of the following is the investigation of choice?","o":["Widal test","Microscopic agglutination test","Weil-Felix reaction","Paul-Bunnell test"],"a":1,"e":"Correct answer: B. Microscopic agglutination test (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":7,"q":"A sewage worker presented with abdominal pain, jaundice, conjunctival injection, and blood in the urine for the past 5 days. Which of the following is the investigation of choice?","o":["Widal test","Microscopic agglutination test","Weil-Felix reaction","Paul-Bunnell test"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9504, 'Microbiology', 'Virology', 'Moderate', 'NEET PG 2023', 8, '{"id":9504,"subject":"Microbiology","chapter":"Virology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":8,"q":"Which of the following laboratory test is used to diagnose rotavirus diarrhea?","o":["Antigen detection in the stool sample","Antigen detection in blood","Antibody detection in serum","Light microscopy of stool specimen"],"a":0,"e":"Correct answer: A. Antigen detection in the stool sample (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":8,"q":"Which of the following laboratory test is used to diagnose rotavirus diarrhea?","o":["Antigen detection in the stool sample","Antigen detection in blood","Antibody detection in serum","Light microscopy of stool specimen"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9505, 'Microbiology', 'Parasitology', 'Moderate', 'NEET PG 2023', 9, '{"id":9505,"subject":"Microbiology","chapter":"Parasitology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":9,"q":"A boy presented with a fever and chills. Rapid test was positive for specific antigen HRP-2. Which of the following species of Plasmodium is the most likely causative agent?","o":["Plasmodium falciparum","Plasmodium malariae","Plasmodium vivax","Plasmodium ovale"],"a":0,"e":"Correct answer: A. Plasmodium falciparum (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":9,"q":"A boy presented with a fever and chills. Rapid test was positive for specific antigen HRP-2. Which of the following species of Plasmodium is the most likely causative agent?","o":["Plasmodium falciparum","Plasmodium malariae","Plasmodium vivax","Plasmodium ovale"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9506, 'Microbiology', 'Systemic Bacteriology', 'Moderate', 'NEET PG 2023', 10, '{"id":9506,"subject":"Microbiology","chapter":"Systemic Bacteriology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":10,"q":"A child was brought with complaints of high fever, multiple seizures, headache, and neck rigidity. CSF analysis showed low glucose, high protein, and many polymorphs. The CSF culture showed pleomorphic gram-negative bacilli. What is true about the causative organism?","o":["It is bacitracin sensitive.","Produces non-lactose fermenting colonies on MacConkey agar","Exhibits satellitism around Staphylococcus aureus colonies","It exhibits alpha hemolysis on sheep blood agar"],"a":2,"e":"Correct answer: C. Exhibits satellitism around Staphylococcus aureus colonies (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":10,"q":"A child was brought with complaints of high fever, multiple seizures, headache, and neck rigidity. CSF analysis showed low glucose, high protein, and many polymorphs. The CSF culture showed pleomorphic gram-negative bacilli. What is true about the causative organism?","o":["It is bacitracin sensitive.","Produces non-lactose fermenting colonies on MacConkey agar","Exhibits satellitism around Staphylococcus aureus colonies","It exhibits alpha hemolysis on sheep blood agar"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9507, 'Microbiology', 'Systemic Bacteriology', 'Moderate', 'NEET PG 2023', 11, '{"id":9507,"subject":"Microbiology","chapter":"Systemic Bacteriology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":11,"q":"A man presents with a history of dysuria and urethral discharge after having unprotected sexual intercourse. Gram-staining of the purulent discharge is seen in the following image. What is the treatment of choice for this infection?","o":["Erythromycin","Azithromycin","Ceftriaxone","Penicillin G"],"a":2,"e":"Correct answer: C. Ceftriaxone (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":11,"q":"A man presents with a history of dysuria and urethral discharge after having unprotected sexual intercourse. Gram-staining of the purulent discharge is seen in the following image. What is the treatment of choice for this infection?","o":["Erythromycin","Azithromycin","Ceftriaxone","Penicillin G"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9508, 'Radiology', 'Head & Neck Imaging', 'Moderate', 'NEET PG 2023', 12, '{"id":9508,"subject":"Radiology","chapter":"Head & Neck Imaging","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":12,"q":"A 2-month-old infant is brought to the OPD with a parietal swelling present since birth. The X-ray image is given below. What could be the probable diagnosis?","o":["Subgaleal hematoma","Cephalhematoma","Caput succedaneum","Enecephalocele"],"a":1,"e":"Correct answer: B. Cephalhematoma (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":12,"q":"A 2-month-old infant is brought to the OPD with a parietal swelling present since birth. The X-ray image is given below. What could be the probable diagnosis?","o":["Subgaleal hematoma","Cephalhematoma","Caput succedaneum","Enecephalocele"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9509, 'Radiology', 'Genitourinary Radiology', 'Moderate', 'NEET PG 2023', 13, '{"id":9509,"subject":"Radiology","chapter":"Genitourinary Radiology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":13,"q":"A patient presented with abdominal pain and sterile pyuria, and the x-ray showed the following features. What is the likely diagnosis?","o":["Putty kidney","Nephrocalcinosis","Staghorn calculus","Psoas calcification"],"a":0,"e":"Correct answer: A. Putty kidney (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":13,"q":"A patient presented with abdominal pain and sterile pyuria, and the x-ray showed the following features. What is the likely diagnosis?","o":["Putty kidney","Nephrocalcinosis","Staghorn calculus","Psoas calcification"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9510, 'Anatomy', 'Pelvis and Perineum', 'Moderate', 'NEET PG 2023', 14, '{"id":9510,"subject":"Anatomy","chapter":"Pelvis and Perineum","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":14,"q":"A defect in which of the following forms the structure marked below?","o":["Internal oblique","External oblique","Parietal peritoneum","Fascia transversalis"],"a":3,"e":"Correct answer: D. Fascia transversalis (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":14,"q":"A defect in which of the following forms the structure marked below?","o":["Internal oblique","External oblique","Parietal peritoneum","Fascia transversalis"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9511, 'Anatomy', 'Head and Neck', 'Moderate', 'NEET PG 2023', 15, '{"id":9511,"subject":"Anatomy","chapter":"Head and Neck","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":15,"q":"A student had his jaw locked while yawning. Which of the following muscles is attached to the articular disc of the temporomandibular joint?","o":["Lateral pterygoid","Temporalis","Medial pterygoid","Masseter"],"a":0,"e":"Correct answer: A. Lateral pterygoid (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":15,"q":"A student had his jaw locked while yawning. Which of the following muscles is attached to the articular disc of the temporomandibular joint?","o":["Lateral pterygoid","Temporalis","Medial pterygoid","Masseter"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9512, 'Anatomy', 'Histology', 'Moderate', 'NEET PG 2023', 16, '{"id":9512,"subject":"Anatomy","chapter":"Histology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":16,"q":"The given histology image is of ?","o":["Leydig cells of testis","Pancreatic islet cells","Hassall''s corpuscles","Glomerulus"],"a":3,"e":"Correct answer: D. Glomerulus (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":16,"q":"The given histology image is of ?","o":["Leydig cells of testis","Pancreatic islet cells","Hassall''s corpuscles","Glomerulus"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9513, 'Anatomy', 'Thorax', 'Moderate', 'NEET PG 2023', 17, '{"id":9513,"subject":"Anatomy","chapter":"Thorax","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":17,"q":"A defect in which of the following aortic arches causes the defect shown in the image?","o":["4th right","4th left","6th right","6th left"],"a":3,"e":"Correct answer: D. 6th left (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":17,"q":"A defect in which of the following aortic arches causes the defect shown in the image?","o":["4th right","4th left","6th right","6th left"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9514, 'Anatomy', 'General Embryology', 'Moderate', 'NEET PG 2023', 18, '{"id":9514,"subject":"Anatomy","chapter":"General Embryology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":18,"q":"Which of the following structures develops from the structure marked 4?","o":["Medial umbilical ligament","Median umbilical ligament","Meckel''s diverticulum","Ligamentum teres"],"a":1,"e":"Correct answer: B. Median umbilical ligament (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":18,"q":"Which of the following structures develops from the structure marked 4?","o":["Medial umbilical ligament","Median umbilical ligament","Meckel''s diverticulum","Ligamentum teres"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9515, 'Anatomy', 'Abdomen', 'Moderate', 'NEET PG 2023', 19, '{"id":9515,"subject":"Anatomy","chapter":"Abdomen","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":19,"q":"A patient comes with abdominal pain, jaundice, and portal hypertension. Anastomosis between which of the following veins is seen?","o":["Left colic vein and middle colic veins","Esophageal veins and left gastric veins","Superior rectal and phrenic veins","Sigmoid and superior rectal veins"],"a":1,"e":"Correct answer: B. Esophageal veins and left gastric veins (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":19,"q":"A patient comes with abdominal pain, jaundice, and portal hypertension. Anastomosis between which of the following veins is seen?","o":["Left colic vein and middle colic veins","Esophageal veins and left gastric veins","Superior rectal and phrenic veins","Sigmoid and superior rectal veins"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9516, 'Biochemistry', 'Vitamins', 'Moderate', 'NEET PG 2023', 20, '{"id":9516,"subject":"Biochemistry","chapter":"Vitamins","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":20,"q":"Which of the following clotting factors is needed for gamma-glutamyl carboxylase?","o":["Factors II, VIII, IX, X","Factors II, VII, IX, and X","Factors II, VII, IX, XI","Factors II, VIII, X, XI"],"a":1,"e":"Correct answer: B. Factors II, VII, IX, and X (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":20,"q":"Which of the following clotting factors is needed for gamma-glutamyl carboxylase?","o":["Factors II, VIII, IX, X","Factors II, VII, IX, and X","Factors II, VII, IX, XI","Factors II, VIII, X, XI"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9517, 'Biochemistry', 'Vitamins', 'Moderate', 'NEET PG 2023', 21, '{"id":9517,"subject":"Biochemistry","chapter":"Vitamins","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":21,"q":"A patient presented with diarrhea, dermatitis, and dementia. Which of the following vitamin deficiencies would you suspect in this patient?","o":["Vitamin B3 deficiency","Vitamin B1 deficiency","Vitamin B6 deficiency","Vitamin B12 deficiency"],"a":0,"e":"Correct answer: A. Vitamin B3 deficiency (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":21,"q":"A patient presented with diarrhea, dermatitis, and dementia. Which of the following vitamin deficiencies would you suspect in this patient?","o":["Vitamin B3 deficiency","Vitamin B1 deficiency","Vitamin B6 deficiency","Vitamin B12 deficiency"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9518, 'Biochemistry', 'Carbohydrate Metabolism', 'Moderate', 'NEET PG 2023', 22, '{"id":9518,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":22,"q":"A young boy presents to the OPD with hypoglycemia and muscle cramps, on exertion or while playing. Then he becomes normal after resting for a while. These episodes are recurrent after a period of activity. He has decreased serum lactate and glucose levels. Which of the following diseases is he most likely to be suffering from?","o":["McArdle disease","Hers disease","Cori''s disease","Andersen disease"],"a":0,"e":"Correct answer: A. McArdle disease (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":22,"q":"A young boy presents to the OPD with hypoglycemia and muscle cramps, on exertion or while playing. Then he becomes normal after resting for a while. These episodes are recurrent after a period of activity. He has decreased serum lactate and glucose levels. Which of the following diseases is he most likely to be suffering from?","o":["McArdle disease","Hers disease","Cori''s disease","Andersen disease"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9519, 'Biochemistry', 'Vitamins', 'Moderate', 'NEET PG 2023', 23, '{"id":9519,"subject":"Biochemistry","chapter":"Vitamins","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":23,"q":"A family consumes only polished rice. Which of the following combinations of vitamin deficiency and enzymatic defect will be present in this family?","o":["Riboflavin-glutathione reductase","Thiamine-transketolase","Thiamine-transaminase","Riboflavin-transketolase"],"a":1,"e":"Correct answer: B. Thiamine-transketolase (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":23,"q":"A family consumes only polished rice. Which of the following combinations of vitamin deficiency and enzymatic defect will be present in this family?","o":["Riboflavin-glutathione reductase","Thiamine-transketolase","Thiamine-transaminase","Riboflavin-transketolase"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9520, 'Biochemistry', 'Vitamins', 'Moderate', 'NEET PG 2023', 24, '{"id":9520,"subject":"Biochemistry","chapter":"Vitamins","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":24,"q":"A chronic alcoholic patient presented to the casualty with confusion, ataxia, and painful eye movements. What could be the vitamin deficiency seen in this patient?","o":["Vitamin B deficiency","Vitamin A deficiency","Vitamin D deficiency","Vitamin C deficiency"],"a":0,"e":"Correct answer: A. Vitamin B deficiency (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":24,"q":"A chronic alcoholic patient presented to the casualty with confusion, ataxia, and painful eye movements. What could be the vitamin deficiency seen in this patient?","o":["Vitamin B deficiency","Vitamin A deficiency","Vitamin D deficiency","Vitamin C deficiency"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9521, 'Biochemistry', 'Carbohydrate Metabolism', 'Moderate', 'NEET PG 2023', 25, '{"id":9521,"subject":"Biochemistry","chapter":"Carbohydrate Metabolism","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":25,"q":"A 4-year-old child presents with easy fatigability. The mother also complains that the child has increased hunger between meals, which is relieved after food. Liver examination revealed no glycogen. The enzyme most likely deficient is?","o":["Glycogen phosphorylase","Glycogen synthase","Debranching enzyme","Glucose 6 phosphatase"],"a":1,"e":"Correct answer: B. Glycogen synthase (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":25,"q":"A 4-year-old child presents with easy fatigability. The mother also complains that the child has increased hunger between meals, which is relieved after food. Liver examination revealed no glycogen. The enzyme most likely deficient is?","o":["Glycogen phosphorylase","Glycogen synthase","Debranching enzyme","Glucose 6 phosphatase"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9522, 'Biochemistry', 'Vitamins', 'Moderate', 'NEET PG 2023', 26, '{"id":9522,"subject":"Biochemistry","chapter":"Vitamins","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":26,"q":"A child was bought with pedal edema and cheilosis. Cardiomegaly was present. What is the vitamin deficiency associated with this clinical presentation?","o":["Riboflavin","Thiamine","Pyridoxine","Niacin"],"a":1,"e":"Correct answer: B. Thiamine (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":26,"q":"A child was bought with pedal edema and cheilosis. Cardiomegaly was present. What is the vitamin deficiency associated with this clinical presentation?","o":["Riboflavin","Thiamine","Pyridoxine","Niacin"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9523, 'Biochemistry', 'Vitamins', 'Moderate', 'NEET PG 2023', 27, '{"id":9523,"subject":"Biochemistry","chapter":"Vitamins","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":27,"q":"A chronic alcoholic patient is diagnosed with gouty arthritis. What biochemical changes will be seen in this patient?","o":["Decreased NADH/NAD+ ratio","Increased urea and urate levels","Increased urate and lactate levels","Increased level of alkaline phosphatase"],"a":2,"e":"Correct answer: C. Increased urate and lactate levels (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":27,"q":"A chronic alcoholic patient is diagnosed with gouty arthritis. What biochemical changes will be seen in this patient?","o":["Decreased NADH/NAD+ ratio","Increased urea and urate levels","Increased urate and lactate levels","Increased level of alkaline phosphatase"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9524, 'Biochemistry', 'Enzymes', 'Moderate', 'NEET PG 2023', 28, '{"id":9524,"subject":"Biochemistry","chapter":"Enzymes","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":28,"q":"A child presents with erythematous scaly patches in the perioral region, mucosal ulcers, and impaired epithelial wound healing. The most likely mineral deficiency associated with this condition is?","o":["Iron deficiency","Zinc deficiency","Calcium deficiency","Copper deficiency"],"a":1,"e":"Correct answer: B. Zinc deficiency (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":28,"q":"A child presents with erythematous scaly patches in the perioral region, mucosal ulcers, and impaired epithelial wound healing. The most likely mineral deficiency associated with this condition is?","o":["Iron deficiency","Zinc deficiency","Calcium deficiency","Copper deficiency"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9525, 'Biochemistry', 'Vitamins', 'Moderate', 'NEET PG 2023', 29, '{"id":9525,"subject":"Biochemistry","chapter":"Vitamins","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":29,"q":"A patient presenting with bleeding gums and easy bruisability was diagnosed with scurvy. This is due to","o":["Low calcium","Defective collagen formation","Inhibition of clotting factors","Increased keratinization of epithelium"],"a":1,"e":"Correct answer: B. Defective collagen formation (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":29,"q":"A patient presenting with bleeding gums and easy bruisability was diagnosed with scurvy. This is due to","o":["Low calcium","Defective collagen formation","Inhibition of clotting factors","Increased keratinization of epithelium"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9526, 'Biochemistry', 'Introduction', 'Moderate', 'NEET PG 2023', 30, '{"id":9526,"subject":"Biochemistry","chapter":"Introduction","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":30,"q":"Which of the following is seen in low insulin: glucagon ratio?","o":["Activation of lipoprotein lipase","Activation of glycogen synthase","Activation of phosphofructokinase 1","Activation of hormone-sensitive lipase"],"a":3,"e":"Correct answer: D. Activation of hormone-sensitive lipase (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":30,"q":"Which of the following is seen in low insulin: glucagon ratio?","o":["Activation of lipoprotein lipase","Activation of glycogen synthase","Activation of phosphofructokinase 1","Activation of hormone-sensitive lipase"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9527, 'Biochemistry', 'Amino Acids and Proteins Chemistry', 'Moderate', 'NEET PG 2023', 31, '{"id":9527,"subject":"Biochemistry","chapter":"Amino Acids and Proteins Chemistry","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":31,"q":"An infant is brought by his parents with complaints that his urine turns black on standing. Which of the following metabolic disorders is likely?","o":["Phenylketonuria","Alkaptonuria","Homocystinuria","Maple syrup urine disease"],"a":1,"e":"Correct answer: B. Alkaptonuria (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":31,"q":"An infant is brought by his parents with complaints that his urine turns black on standing. Which of the following metabolic disorders is likely?","o":["Phenylketonuria","Alkaptonuria","Homocystinuria","Maple syrup urine disease"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9528, 'Biochemistry', 'Vitamins', 'Moderate', 'NEET PG 2023', 32, '{"id":9528,"subject":"Biochemistry","chapter":"Vitamins","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":32,"q":"A child presents with thinning of hair and scaling of the scalp. On taking further history, it is found that she consumes raw eggs in her diet regularly. The given manifestations are due to the deficiency of which of the following vitamins?","o":["Niacin","Pyridoxine","Biotin","Thiamine"],"a":2,"e":"Correct answer: C. Biotin (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":32,"q":"A child presents with thinning of hair and scaling of the scalp. On taking further history, it is found that she consumes raw eggs in her diet regularly. The given manifestations are due to the deficiency of which of the following vitamins?","o":["Niacin","Pyridoxine","Biotin","Thiamine"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9529, 'Biochemistry', 'Lipid Metabolism', 'Moderate', 'NEET PG 2023', 33, '{"id":9529,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":33,"q":"A child presents with mental retardation, bone pain, and inability to walk. On funduscopic examination, a cherry red spot is seen. There is no organomegaly. What is the most likely diagnosis?","o":["Tay-Sachs disease","Niemann-Pick disease","Hurler syndrome","Gaucher disease"],"a":0,"e":"Correct answer: A. Tay-Sachs disease (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":33,"q":"A child presents with mental retardation, bone pain, and inability to walk. On funduscopic examination, a cherry red spot is seen. There is no organomegaly. What is the most likely diagnosis?","o":["Tay-Sachs disease","Niemann-Pick disease","Hurler syndrome","Gaucher disease"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9530, 'Ophthalmology', 'Neuro Ophthalmology', 'Moderate', 'NEET PG 2023', 34, '{"id":9530,"subject":"Ophthalmology","chapter":"Neuro Ophthalmology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":34,"q":"A female presents with loss of vision in the right halves of both eyes. Where is the lesion located in the optic pathway?","o":["Left optic tract","Optic radiation","Optic chiasma","Right optic tract"],"a":0,"e":"Correct answer: A. Left optic tract (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":34,"q":"A female presents with loss of vision in the right halves of both eyes. Where is the lesion located in the optic pathway?","o":["Left optic tract","Optic radiation","Optic chiasma","Right optic tract"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9531, 'Ophthalmology', 'Diseases of Lens', 'Moderate', 'NEET PG 2023', 35, '{"id":9531,"subject":"Ophthalmology","chapter":"Diseases of Lens","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":35,"q":"A 65-year-old diabetic woman presents with painless loss of vision. The ocular findings are shown in the image below. What is the likely diagnosis and management for this patient?","o":["Zonular cataract and lensectomy","Rosette cataract and sugar control","Sunflower cataract and lesion extraction","Immature senile cataract and phacoemulsification with IOL"],"a":3,"e":"Correct answer: D. Immature senile cataract and phacoemulsification with IOL (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":35,"q":"A 65-year-old diabetic woman presents with painless loss of vision. The ocular findings are shown in the image below. What is the likely diagnosis and management for this patient?","o":["Zonular cataract and lensectomy","Rosette cataract and sugar control","Sunflower cataract and lesion extraction","Immature senile cataract and phacoemulsification with IOL"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9532, 'Ophthalmology', 'Sclera', 'Moderate', 'NEET PG 2023', 36, '{"id":9532,"subject":"Ophthalmology","chapter":"Sclera","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":36,"q":"A 5-year-old boy presents with a small nodule on the sclera as shown in the image below. What is the likely diagnosis?","o":["Pterygium","Pinguecula","Dermolipoma","Dermoid"],"a":3,"e":"Correct answer: D. Dermoid (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":36,"q":"A 5-year-old boy presents with a small nodule on the sclera as shown in the image below. What is the likely diagnosis?","o":["Pterygium","Pinguecula","Dermolipoma","Dermoid"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9533, 'Ophthalmology', 'Cornea', 'Moderate', 'NEET PG 2023', 37, '{"id":9533,"subject":"Ophthalmology","chapter":"Cornea","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":37,"q":"The eye examination of a 20-year-old male shows a golden ring on the iris. What is the next investigation to diagnose the condition?","o":["Alpha-1-antitrypsin","Alpha-fetoprotein","Serum iron","Serum ceruloplasmin"],"a":3,"e":"Correct answer: D. Serum ceruloplasmin (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":37,"q":"The eye examination of a 20-year-old male shows a golden ring on the iris. What is the next investigation to diagnose the condition?","o":["Alpha-1-antitrypsin","Alpha-fetoprotein","Serum iron","Serum ceruloplasmin"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9534, 'Ophthalmology', 'Cornea', 'Moderate', 'NEET PG 2023', 38, '{"id":9534,"subject":"Ophthalmology","chapter":"Cornea","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":38,"q":"What is the dye and filter used to diagnose corneal ulcers?","o":["Lissamine dye green filter","Lissamine dye cobalt blue filter","Fluorescein dye - visualized under green filter","Fluorescein dye - visualized under cobalt blue filter"],"a":3,"e":"Correct answer: D. Fluorescein dye - visualized under cobalt blue filter (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":38,"q":"What is the dye and filter used to diagnose corneal ulcers?","o":["Lissamine dye green filter","Lissamine dye cobalt blue filter","Fluorescein dye - visualized under green filter","Fluorescein dye - visualized under cobalt blue filter"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9535, 'Surgery', 'Urology', 'Moderate', 'NEET PG 2023', 39, '{"id":9535,"subject":"Surgery","chapter":"Urology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":39,"q":"A 55-year-old male presented with verrucous carcinoma around the glans of the penis. Examination reveals that the inguinal lymph nodes are not enlarged. What is the appropriate management for this patient?","o":["Total penectomy","CO2 laser excision","Topical 5-fluorouracil","Partial penectomy"],"a":3,"e":"Correct answer: D. Partial penectomy (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":39,"q":"A 55-year-old male presented with verrucous carcinoma around the glans of the penis. Examination reveals that the inguinal lymph nodes are not enlarged. What is the appropriate management for this patient?","o":["Total penectomy","CO2 laser excision","Topical 5-fluorouracil","Partial penectomy"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9536, 'Surgery', 'Others', 'Moderate', 'NEET PG 2023', 40, '{"id":9536,"subject":"Surgery","chapter":"Others","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":40,"q":"Identify the procedure being performed in the image given below.","o":["Intraosseous cannula for pain relief","Bone marrow aspiration","Intraosseous route access for giving IV fluids","Intraosseous abscess drainage"],"a":2,"e":"Correct answer: C. Intraosseous route access for giving IV fluids (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":40,"q":"Identify the procedure being performed in the image given below.","o":["Intraosseous cannula for pain relief","Bone marrow aspiration","Intraosseous route access for giving IV fluids","Intraosseous abscess drainage"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9537, 'Surgery', 'Urology', 'Moderate', 'NEET PG 2023', 41, '{"id":9537,"subject":"Surgery","chapter":"Urology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":41,"q":"A diabetic patient presents with sudden-onset perineal pain. On examination, foul-smelling discharge, and necrotic tissue as seen in the image is noted. Which of the following is true about the given condition?","o":["Anti-gas gangrene serum indicated for all cases","Urinary diversion is the next step","Bilateral orchidectomy must be done","Mixed aerobic and anaerobic infection"],"a":3,"e":"Correct answer: D. Mixed aerobic and anaerobic infection (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":41,"q":"A diabetic patient presents with sudden-onset perineal pain. On examination, foul-smelling discharge, and necrotic tissue as seen in the image is noted. Which of the following is true about the given condition?","o":["Anti-gas gangrene serum indicated for all cases","Urinary diversion is the next step","Bilateral orchidectomy must be done","Mixed aerobic and anaerobic infection"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9538, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'NEET PG 2023', 42, '{"id":9538,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":42,"q":"Which of the following is the most common complication following ligation of the first vessel during abdominoperineal resection for rectal carcinoma? (APR Abdominoperineal resection)","o":["Parasympathetic-bladder dysfunction and retrograde ejaculation.","Sympathetic - - bladder dysfunction and impotence.","Sympathetic- retrograde ejaculation and bladder dysfunction.","Sympathetic-Impotence and loss of cutaneous sensation in perineal region"],"a":2,"e":"Correct answer: C. Sympathetic- retrograde ejaculation and bladder dysfunction. (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":42,"q":"Which of the following is the most common complication following ligation of the first vessel during abdominoperineal resection for rectal carcinoma? (APR Abdominoperineal resection)","o":["Parasympathetic-bladder dysfunction and retrograde ejaculation.","Sympathetic - - bladder dysfunction and impotence.","Sympathetic- retrograde ejaculation and bladder dysfunction.","Sympathetic-Impotence and loss of cutaneous sensation in perineal region"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9539, 'Surgery', 'Plastic Surgery', 'Moderate', 'NEET PG 2023', 43, '{"id":9539,"subject":"Surgery","chapter":"Plastic Surgery","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":43,"q":"A patient presents to the clinic with the lesion given in the image. He had a traumatic injury to the chest one year ago. What is the most likely diagnosis?","o":["Hemangioma","Hypertrophic scar","Keloid","Neurofibroma"],"a":2,"e":"Correct answer: C. Keloid (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":43,"q":"A patient presents to the clinic with the lesion given in the image. He had a traumatic injury to the chest one year ago. What is the most likely diagnosis?","o":["Hemangioma","Hypertrophic scar","Keloid","Neurofibroma"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9540, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'NEET PG 2023', 44, '{"id":9540,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":44,"q":"A 45-year-old male underwent bilateral laparoscopic hernia repair for inguinal hernia. Postoperatively, he complained of pain in the right thigh. Which of the following nerve entrapment leads to this symptom?","o":["Ilioinguinal nerve","Iliohypogastric nerve","Femoral nerve","Lateral cutaneous nerve of thigh"],"a":3,"e":"Correct answer: D. Lateral cutaneous nerve of thigh (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":44,"q":"A 45-year-old male underwent bilateral laparoscopic hernia repair for inguinal hernia. Postoperatively, he complained of pain in the right thigh. Which of the following nerve entrapment leads to this symptom?","o":["Ilioinguinal nerve","Iliohypogastric nerve","Femoral nerve","Lateral cutaneous nerve of thigh"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9541, 'Surgery', 'Others', 'Moderate', 'NEET PG 2023', 45, '{"id":9541,"subject":"Surgery","chapter":"Others","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":45,"q":"A patient was brought to the ER following a road traffic accident. On examination, the patient opens his eyes to a painful stimulus, speaks inappropriately, and withdraws his limbs to a painful stimulus. What is his GCS score?","o":["E2V2M3","E3V3M3","E2V3M4","E3V2M2"],"a":2,"e":"Correct answer: C. E2V3M4 (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":45,"q":"A patient was brought to the ER following a road traffic accident. On examination, the patient opens his eyes to a painful stimulus, speaks inappropriately, and withdraws his limbs to a painful stimulus. What is his GCS score?","o":["E2V2M3","E3V3M3","E2V3M4","E3V2M2"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9542, 'Surgery', 'Hepatobiliary Pancreatic Surgery', 'Moderate', 'NEET PG 2023', 46, '{"id":9542,"subject":"Surgery","chapter":"Hepatobiliary Pancreatic Surgery","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":46,"q":"A patient presented with fever and abdominal pain with jaundice. Investigations showed the given findings. Which of the following statements is true regarding this condition?","o":["Surgery is mandatory","Fine-needle aspiration cytology is diagnostic","Angioembolization is the treatment of choice","Echinococcus species is involved in etiology"],"a":3,"e":"Correct answer: D. Echinococcus species is involved in etiology (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":46,"q":"A patient presented with fever and abdominal pain with jaundice. Investigations showed the given findings. Which of the following statements is true regarding this condition?","o":["Surgery is mandatory","Fine-needle aspiration cytology is diagnostic","Angioembolization is the treatment of choice","Echinococcus species is involved in etiology"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9543, 'Surgery', 'Oncology', 'Moderate', 'NEET PG 2023', 47, '{"id":9543,"subject":"Surgery","chapter":"Oncology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":47,"q":"A patient who is a known case of alcohol dependence syndrome presents with sudden and unintentional weight loss. What is the most likely diagnosis? -ALP 240 IU/L -S. Direct bilirubin - 1 mg/dL -AST/ALT -0.5 -Alpha fetoprotein- 600 ng/mL","o":["Hepatic adenoma","Cholangiocarcinoma","Hepatocellular carcinoma","Alcoholic hepatitis"],"a":2,"e":"Correct answer: C. Hepatocellular carcinoma (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":47,"q":"A patient who is a known case of alcohol dependence syndrome presents with sudden and unintentional weight loss. What is the most likely diagnosis? -ALP 240 IU/L -S. Direct bilirubin - 1 mg/dL -AST/ALT -0.5 -Alpha fetoprotein- 600 ng/mL","o":["Hepatic adenoma","Cholangiocarcinoma","Hepatocellular carcinoma","Alcoholic hepatitis"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9544, 'Dermatology', 'Miscellaneous Disorders', 'Moderate', 'NEET PG 2023', 48, '{"id":9544,"subject":"Dermatology","chapter":"Miscellaneous Disorders","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":48,"q":"A lady developed a skin reaction, as shown in the image, after using a hair dye. Which of the following chemicals is responsible for this condition?","o":["Pollen","Chromates","Balsam of Peru","p-Phenylenediamine"],"a":3,"e":"Correct answer: D. p-Phenylenediamine (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":48,"q":"A lady developed a skin reaction, as shown in the image, after using a hair dye. Which of the following chemicals is responsible for this condition?","o":["Pollen","Chromates","Balsam of Peru","p-Phenylenediamine"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9545, 'Dermatology', 'Introduction to Dermatology', 'Moderate', 'NEET PG 2023', 49, '{"id":9545,"subject":"Dermatology","chapter":"Introduction to Dermatology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":49,"q":"A female patient presented with acne that is not resolving on oral isotretinoin and antibiotics therapy. Which of the following is the next best investigation?","o":["Look for dietary triggers.","Evaluate for hyperandrogenism","Check for antibiotic resistance","Look for drug triggers"],"a":1,"e":"Correct answer: B. Evaluate for hyperandrogenism (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":49,"q":"A female patient presented with acne that is not resolving on oral isotretinoin and antibiotics therapy. Which of the following is the next best investigation?","o":["Look for dietary triggers.","Evaluate for hyperandrogenism","Check for antibiotic resistance","Look for drug triggers"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9546, 'Anaesthesia', 'Cardiopulmonary Cerebral Resuscitation', 'Moderate', 'NEET PG 2023', 50, '{"id":9546,"subject":"Anaesthesia","chapter":"Cardiopulmonary Cerebral Resuscitation","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":50,"q":"Identify the maneuver being performed in the given image.","o":["Head tilt, chin lift","Jaw thrust","Head extension","d. In-line manual stabilization"],"a":0,"e":"Correct answer: A. Head tilt, chin lift (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":50,"q":"Identify the maneuver being performed in the given image.","o":["Head tilt, chin lift","Jaw thrust","Head extension","d. In-line manual stabilization"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9547, 'Surgery', 'Hepatobiliary Pancreatic Surgery', 'Moderate', 'NEET PG 2023', 51, '{"id":9547,"subject":"Surgery","chapter":"Hepatobiliary Pancreatic Surgery","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":51,"q":"A patient presented with features of chronic pancreatitis with recurrent attacks and has a 10 mm dilatation of the pancreatic duct with intraductal calculi present. Which of the following is the surgery of choice?","o":["Pancreaticoduodenectomy","Longitudinal pancreaticojejunostomy","ERCP and sphincterotomy","Coring of pancreas head"],"a":1,"e":"Correct answer: B. Longitudinal pancreaticojejunostomy (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":51,"q":"A patient presented with features of chronic pancreatitis with recurrent attacks and has a 10 mm dilatation of the pancreatic duct with intraductal calculi present. Which of the following is the surgery of choice?","o":["Pancreaticoduodenectomy","Longitudinal pancreaticojejunostomy","ERCP and sphincterotomy","Coring of pancreas head"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9548, 'Dermatology', 'Sexually Transmitted Infections', 'Moderate', 'NEET PG 2023', 52, '{"id":9548,"subject":"Dermatology","chapter":"Sexually Transmitted Infections","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":52,"q":"A young woman complains of a painless ulcer in the genital area. It is associated with non-tender inguinal lymphadenopathy. What is the most likely diagnosis?","o":["Chancroid","Syphilis","Herpes genitalis","Granuloma inguinale"],"a":1,"e":"Correct answer: B. Syphilis (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":52,"q":"A young woman complains of a painless ulcer in the genital area. It is associated with non-tender inguinal lymphadenopathy. What is the most likely diagnosis?","o":["Chancroid","Syphilis","Herpes genitalis","Granuloma inguinale"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9549, 'Dermatology', 'Miscellaneous Disorders', 'Moderate', 'NEET PG 2023', 53, '{"id":9549,"subject":"Dermatology","chapter":"Miscellaneous Disorders","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":53,"q":"Which of the following is associated with the clinical condition shown in the image?","o":["Cataract","Glaucoma","Malignant melanoma","Basal cell carcinoma"],"a":2,"e":"Correct answer: C. Malignant melanoma (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":53,"q":"Which of the following is associated with the clinical condition shown in the image?","o":["Cataract","Glaucoma","Malignant melanoma","Basal cell carcinoma"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9550, 'Anaesthesia', 'Pre-Anaesthetic Evaluation', 'Moderate', 'NEET PG 2023', 54, '{"id":9550,"subject":"Anaesthesia","chapter":"Pre-Anaesthetic Evaluation","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":54,"q":"Which of the following is the drug of choice for preoperative antibiotic prophylaxis in a patient undergoing cardiac surgery?","o":["Penicillin G","Erythromycin","Azithromycin","Cefazolin"],"a":3,"e":"Correct answer: D. Cefazolin (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":54,"q":"Which of the following is the drug of choice for preoperative antibiotic prophylaxis in a patient undergoing cardiac surgery?","o":["Penicillin G","Erythromycin","Azithromycin","Cefazolin"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9551, 'ENT', 'Nose and Paranasal Sinuses', 'Moderate', 'NEET PG 2023', 55, '{"id":9551,"subject":"ENT","chapter":"Nose and Paranasal Sinuses","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":55,"q":"A 30-year-old male presents with nonaxial proptosis of the left eye. The patient gives a history of a road traffic accident 15 years back. The CT image is given below. What is the most likely diagnosis?","o":["Frontal mucocele","Frontal meningioma","Juvenile nasopharyngeal angiofibroma","Pseudotumor of orbit"],"a":0,"e":"Correct answer: A. Frontal mucocele (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":55,"q":"A 30-year-old male presents with nonaxial proptosis of the left eye. The patient gives a history of a road traffic accident 15 years back. The CT image is given below. What is the most likely diagnosis?","o":["Frontal mucocele","Frontal meningioma","Juvenile nasopharyngeal angiofibroma","Pseudotumor of orbit"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9552, 'Surgery', 'Endocrine Surgery', 'Moderate', 'NEET PG 2023', 56, '{"id":9552,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":56,"q":"A woman presented with a BIRADS-5 breast lesion. Which of the following is a good prognostic factor for this lesion?","o":["BRCA-1 positive","p53 positive","ER positive","High Ki-67"],"a":2,"e":"Correct answer: C. ER positive (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":56,"q":"A woman presented with a BIRADS-5 breast lesion. Which of the following is a good prognostic factor for this lesion?","o":["BRCA-1 positive","p53 positive","ER positive","High Ki-67"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9553, 'ENT', 'Larynx', 'Moderate', 'NEET PG 2023', 57, '{"id":9553,"subject":"ENT","chapter":"Larynx","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":57,"q":"A 55-year-old patient comes with hoarseness of voice and difficulty swallowing. The patient was diagnosed with laryngeal carcinoma, and surgical management was done. The post-operative image of the patient is given below. Which of the following surgery was done on this patient?","o":["Partial laryngectomy","Percutaneous tracheostomy","Standard tracheostomy","Total laryngectomy"],"a":3,"e":"Correct answer: D. Total laryngectomy (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":57,"q":"A 55-year-old patient comes with hoarseness of voice and difficulty swallowing. The patient was diagnosed with laryngeal carcinoma, and surgical management was done. The post-operative image of the patient is given below. Which of the following surgery was done on this patient?","o":["Partial laryngectomy","Percutaneous tracheostomy","Standard tracheostomy","Total laryngectomy"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9554, 'Surgery', 'Cardiothoracic Vascular Surgery', 'Moderate', 'NEET PG 2023', 58, '{"id":9554,"subject":"Surgery","chapter":"Cardiothoracic Vascular Surgery","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":58,"q":"A patient presents with sudden onset of chest pain shooting to the neck and interscapular region. X-ray shows widened mediastinum. BP is 110/90 mmHg in the right upper limb and 160/100 mmHg in the left upper limb. What is the most likely diagnosis?","o":["Acute coronary syndrome","Acute pulmonary embolism","Acute aortic dissection","Esophageal rupture"],"a":2,"e":"Correct answer: C. Acute aortic dissection (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":58,"q":"A patient presents with sudden onset of chest pain shooting to the neck and interscapular region. X-ray shows widened mediastinum. BP is 110/90 mmHg in the right upper limb and 160/100 mmHg in the left upper limb. What is the most likely diagnosis?","o":["Acute coronary syndrome","Acute pulmonary embolism","Acute aortic dissection","Esophageal rupture"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9555, 'ENT', 'Ear', 'Moderate', 'NEET PG 2023', 59, '{"id":9555,"subject":"ENT","chapter":"Ear","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":59,"q":"A female patient with hearing loss is examined and is found to be Rinne negative at 256 Hz and 512 Hz, while Rinne positive at 1024 Hz. What is the expected air conduction and bone conduction gap?","o":["30-45 dB","15-30 dB","45-60 dB",">60 dB"],"a":0,"e":"Correct answer: A. 30-45 dB (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":59,"q":"A female patient with hearing loss is examined and is found to be Rinne negative at 256 Hz and 512 Hz, while Rinne positive at 1024 Hz. What is the expected air conduction and bone conduction gap?","o":["30-45 dB","15-30 dB","45-60 dB",">60 dB"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9556, 'Surgery', 'Hepatobiliary Pancreatic Surgery', 'Moderate', 'NEET PG 2023', 60, '{"id":9556,"subject":"Surgery","chapter":"Hepatobiliary Pancreatic Surgery","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":60,"q":"A patient presented with right hypochondriac pain. He had an episode of diarrhea 1 week prior. CT scan of the abdomen reveals a liver abscess of around 25 ccs. What is the next step in management?","o":["PAIR","Surgery","Medical therapy","Percutaneous drainage"],"a":2,"e":"Correct answer: C. Medical therapy (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":60,"q":"A patient presented with right hypochondriac pain. He had an episode of diarrhea 1 week prior. CT scan of the abdomen reveals a liver abscess of around 25 ccs. What is the next step in management?","o":["PAIR","Surgery","Medical therapy","Percutaneous drainage"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9557, 'Orthopaedics', 'Pediatric Orthopedics', 'Moderate', 'NEET PG 2023', 61, '{"id":9557,"subject":"Orthopaedics","chapter":"Pediatric Orthopedics","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":61,"q":"A child was brought with bony deformities, as shown in the radiograph below. It could be due to the deficiency of which of the following?","o":["Vitamin A","Vitamin D","Vitamin K","Vitamin C"],"a":1,"e":"Correct answer: B. Vitamin D (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":61,"q":"A child was brought with bony deformities, as shown in the radiograph below. It could be due to the deficiency of which of the following?","o":["Vitamin A","Vitamin D","Vitamin K","Vitamin C"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9558, 'Surgery', 'Neurosurgery', 'Moderate', 'NEET PG 2023', 62, '{"id":9558,"subject":"Surgery","chapter":"Neurosurgery","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":62,"q":"A 50-year-old patient with a history of trauma one week back presents with confusion and ataxia. He is on treatment for alcohol dependence and his last intake was 2 weeks back. CT scan reveals the following finding. What is the diagnosis?","o":["Extradural hemorrhage","Subdural hemorrhage","Intra-parenchymal hemorrhage","Subarachnoid hemorrhage"],"a":1,"e":"Correct answer: B. Subdural hemorrhage (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":62,"q":"A 50-year-old patient with a history of trauma one week back presents with confusion and ataxia. He is on treatment for alcohol dependence and his last intake was 2 weeks back. CT scan reveals the following finding. What is the diagnosis?","o":["Extradural hemorrhage","Subdural hemorrhage","Intra-parenchymal hemorrhage","Subarachnoid hemorrhage"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9559, 'Surgery', 'Plastic Surgery', 'Moderate', 'NEET PG 2023', 63, '{"id":9559,"subject":"Surgery","chapter":"Plastic Surgery","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":63,"q":"Which of the following is false about the given condition?","o":["Repeated radical surgery every 24 hours may be required to adequately manage this condition","This is a case of Meleney''s gangrene","The condition is caused by β hemolytic streptococcus and may sometimes be polymicrobial","Hyperbaric oxygen has no role in the treatment of this condition"],"a":3,"e":"Correct answer: D. Hyperbaric oxygen has no role in the treatment of this condition (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":63,"q":"Which of the following is false about the given condition?","o":["Repeated radical surgery every 24 hours may be required to adequately manage this condition","This is a case of Meleney''s gangrene","The condition is caused by β hemolytic streptococcus and may sometimes be polymicrobial","Hyperbaric oxygen has no role in the treatment of this condition"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9560, 'Pharmacology', 'Antimicrobials : Anti Bacterial Drugs', 'Moderate', 'NEET PG 2023', 64, '{"id":9560,"subject":"Pharmacology","chapter":"Antimicrobials : Anti Bacterial Drugs","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":64,"q":"A bronchial asthma patient on inhalational steroids presented with white patchy lesions on the tongue and buccal mucosa. What is the drug that can be used to treat this condition?","o":["Clotrimazole","Griseofulvin","Terbinafine","Flucytosine"],"a":0,"e":"Correct answer: A. Clotrimazole (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":64,"q":"A bronchial asthma patient on inhalational steroids presented with white patchy lesions on the tongue and buccal mucosa. What is the drug that can be used to treat this condition?","o":["Clotrimazole","Griseofulvin","Terbinafine","Flucytosine"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9561, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'NEET PG 2023', 65, '{"id":9561,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":65,"q":"A patient presents with a swelling in the groin region and it is diagnosed as a direct inguinal hernia. Weakness in which of the following structures is most likely to cause this condition?","o":["Pectineal ligament","Conjoint tendon","Reflected part of inguinal ligament","Lacunar ligament"],"a":1,"e":"Correct answer: B. Conjoint tendon (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":65,"q":"A patient presents with a swelling in the groin region and it is diagnosed as a direct inguinal hernia. Weakness in which of the following structures is most likely to cause this condition?","o":["Pectineal ligament","Conjoint tendon","Reflected part of inguinal ligament","Lacunar ligament"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9562, 'Pharmacology', 'General Pharmacology', 'Moderate', 'NEET PG 2023', 66, '{"id":9562,"subject":"Pharmacology","chapter":"General Pharmacology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":66,"q":"A pregnant woman with a history of bronchial asthma is in the third stage of labor. Which drugs should be avoided in managing postpartum hemorrhage in this mother?","o":["Carboprost","Oxytocin","Dinoprostone","Methyl ergometrine"],"a":0,"e":"Correct answer: A. Carboprost (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":66,"q":"A pregnant woman with a history of bronchial asthma is in the third stage of labor. Which drugs should be avoided in managing postpartum hemorrhage in this mother?","o":["Carboprost","Oxytocin","Dinoprostone","Methyl ergometrine"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9563, 'Orthopaedics', 'Peripheral Nerve Injuries', 'Moderate', 'NEET PG 2023', 67, '{"id":9563,"subject":"Orthopaedics","chapter":"Peripheral Nerve Injuries","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":67,"q":"In which of the following nerve injuries is the instrument shown below used?","o":["Radial nerve","Median nerve","Ulnar nerve","Volkmann''s ischemic contracture"],"a":0,"e":"Correct answer: A. Radial nerve (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":67,"q":"In which of the following nerve injuries is the instrument shown below used?","o":["Radial nerve","Median nerve","Ulnar nerve","Volkmann''s ischemic contracture"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9564, 'Pharmacology', 'CVS Pharmacology', 'Moderate', 'NEET PG 2023', 68, '{"id":9564,"subject":"Pharmacology","chapter":"CVS Pharmacology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":68,"q":"Name the drug that acts on both the marked areas.","o":["Sacubitril","Omapatrilat","Losartan","Nesiritide"],"a":1,"e":"Correct answer: B. Omapatrilat (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":68,"q":"Name the drug that acts on both the marked areas.","o":["Sacubitril","Omapatrilat","Losartan","Nesiritide"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9565, 'Orthopaedics', 'Spine + Pelvis + Lower Limb Traumatology', 'Moderate', 'NEET PG 2023', 69, '{"id":9565,"subject":"Orthopaedics","chapter":"Spine + Pelvis + Lower Limb Traumatology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":69,"q":"A patient presented with chronic knee pain but has no history of trauma. Identify the condition shown in the radiograph below and the appropriate management.","o":["Patellar avulsion fracture, TBW","Bipartite fracture patella, X-ray of other knees","Fracture of the upper pole of the patella, Cylindrical cast","Avulsion fracture, interfragmentary screw fixation"],"a":1,"e":"Correct answer: B. Bipartite fracture patella, X-ray of other knees (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":69,"q":"A patient presented with chronic knee pain but has no history of trauma. Identify the condition shown in the radiograph below and the appropriate management.","o":["Patellar avulsion fracture, TBW","Bipartite fracture patella, X-ray of other knees","Fracture of the upper pole of the patella, Cylindrical cast","Avulsion fracture, interfragmentary screw fixation"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9566, 'Surgery', 'Cardiothoracic Vascular Surgery', 'Moderate', 'NEET PG 2023', 70, '{"id":9566,"subject":"Surgery","chapter":"Cardiothoracic Vascular Surgery","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":70,"q":"A construction worker came to the OPD complaining of white fingers. He has been working in the cement and concrete industry and has been working on heavy machinery drills, wood, and furniture polishing for 20 years. What is the most likely etiology for this condition?","o":["Candidal infection of the fingers due to continuous exposure to water","Exposure to thinners and paints","Continuous exposure to cement and concrete","Continuous exposure to drills and machines"],"a":3,"e":"Correct answer: D. Continuous exposure to drills and machines (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":70,"q":"A construction worker came to the OPD complaining of white fingers. He has been working in the cement and concrete industry and has been working on heavy machinery drills, wood, and furniture polishing for 20 years. What is the most likely etiology for this condition?","o":["Candidal infection of the fingers due to continuous exposure to water","Exposure to thinners and paints","Continuous exposure to cement and concrete","Continuous exposure to drills and machines"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9567, 'Pharmacology', 'CVS Pharmacology', 'Moderate', 'NEET PG 2023', 71, '{"id":9567,"subject":"Pharmacology","chapter":"CVS Pharmacology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":71,"q":"A patient with a previous history of myocardial infarction and ventricular arrhythmia is on treatment for a few months. He developed fatigue, dyspnea, and weight gain. He had also developed pulmonary fibrosis. Which of the following drugs is responsible for the side effects mentioned above?","o":["Amiodarone","Atenolol","Aspirin","Spironolactone"],"a":0,"e":"Correct answer: A. Amiodarone (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":71,"q":"A patient with a previous history of myocardial infarction and ventricular arrhythmia is on treatment for a few months. He developed fatigue, dyspnea, and weight gain. He had also developed pulmonary fibrosis. Which of the following drugs is responsible for the side effects mentioned above?","o":["Amiodarone","Atenolol","Aspirin","Spironolactone"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9568, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'NEET PG 2023', 72, '{"id":9568,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":72,"q":"A 5-year-old child was admitted to the hospital for prolapsing rectal mass and painless rectal bleeding. Histopathological examination reveals enlarged and inflamed glands filled with mucin. What is the likely diagnosis?","o":["Adenoma","Choristoma","Hamartoma","Carcinoma"],"a":2,"e":"Correct answer: C. Hamartoma (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":72,"q":"A 5-year-old child was admitted to the hospital for prolapsing rectal mass and painless rectal bleeding. Histopathological examination reveals enlarged and inflamed glands filled with mucin. What is the likely diagnosis?","o":["Adenoma","Choristoma","Hamartoma","Carcinoma"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9569, 'Pharmacology', 'Autacoids', 'Moderate', 'NEET PG 2023', 73, '{"id":9569,"subject":"Pharmacology","chapter":"Autacoids","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":73,"q":"A young female comes to the emergency department after consuming 100 aspirin tablets. What should be the next step in management?","o":["N-acetyl cysteine to replenish glutathione stores","Pralidoxime","Glucagon to control bradycardia and hypoglycemia","Give sodium bicarbonate to alkalize urine"],"a":3,"e":"Correct answer: D. Give sodium bicarbonate to alkalize urine (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":73,"q":"A young female comes to the emergency department after consuming 100 aspirin tablets. What should be the next step in management?","o":["N-acetyl cysteine to replenish glutathione stores","Pralidoxime","Glucagon to control bradycardia and hypoglycemia","Give sodium bicarbonate to alkalize urine"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9570, 'Pharmacology', 'CVS Pharmacology', 'Moderate', 'NEET PG 2023', 74, '{"id":9570,"subject":"Pharmacology","chapter":"CVS Pharmacology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":74,"q":"A chronic smoker was on nicotine replacement therapy and clonidine tablets for smoking de-addiction. He stopped taking clonidine tablets and now presents with a headache. What is the reason behind this condition?","o":["Postural hypotension","Receptor upregulation","Rebound hypertension","Receptor hypersensitivity"],"a":2,"e":"Correct answer: C. Rebound hypertension (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":74,"q":"A chronic smoker was on nicotine replacement therapy and clonidine tablets for smoking de-addiction. He stopped taking clonidine tablets and now presents with a headache. What is the reason behind this condition?","o":["Postural hypotension","Receptor upregulation","Rebound hypertension","Receptor hypersensitivity"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9571, 'Surgery', 'Plastic Surgery', 'Moderate', 'NEET PG 2023', 75, '{"id":9571,"subject":"Surgery","chapter":"Plastic Surgery","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":75,"q":"Identify the given condition.","o":["Venous ulcer","Malignant ulcer","Arterial ulcer","Trophic ulcer"],"a":3,"e":"Correct answer: D. Trophic ulcer (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":75,"q":"Identify the given condition.","o":["Venous ulcer","Malignant ulcer","Arterial ulcer","Trophic ulcer"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9572, 'Pharmacology', 'Autacoids', 'Moderate', 'NEET PG 2023', 76, '{"id":9572,"subject":"Pharmacology","chapter":"Autacoids","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":76,"q":"A patient with recurrent gout attacks was started on a therapy that inhibits uric acid synthesis. His symptoms were reduced after therapy. Which drug was he started on?","o":["Probenecid","Colchicine","Diclofenac","Allopurinol"],"a":3,"e":"Correct answer: D. Allopurinol (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":76,"q":"A patient with recurrent gout attacks was started on a therapy that inhibits uric acid synthesis. His symptoms were reduced after therapy. Which drug was he started on?","o":["Probenecid","Colchicine","Diclofenac","Allopurinol"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9573, 'Pharmacology', 'Drugs Affecting Blood and Blood formation', 'Moderate', 'NEET PG 2023', 77, '{"id":9573,"subject":"Pharmacology","chapter":"Drugs Affecting Blood and Blood formation","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":77,"q":"A patient with a malignancy is undergoing chemotherapy. The platelet counts were reduced after the previous cycle of chemotherapy. Which of the following drugs can be used to treat this patient?","o":["Oprelvekin (IL-11)","Filgrastim","Erythropoietin","Amifostine"],"a":0,"e":"Correct answer: A. Oprelvekin (IL-11) (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":77,"q":"A patient with a malignancy is undergoing chemotherapy. The platelet counts were reduced after the previous cycle of chemotherapy. Which of the following drugs can be used to treat this patient?","o":["Oprelvekin (IL-11)","Filgrastim","Erythropoietin","Amifostine"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9574, 'Pharmacology', 'CVS Pharmacology', 'Moderate', 'NEET PG 2023', 78, '{"id":9574,"subject":"Pharmacology","chapter":"CVS Pharmacology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":78,"q":"The true statement among the following is___","o":["The dose of telmisartan should be reduced in renal failure but not in hepatic failure.","The dose of irbesartan should be reduced in case of mild-moderate hepatic failure and renal failure.","The dose of candesartan should be reduced in mild-moderate liver failure but not in renal failure.","Losartan acts as a thromboxane A2 antagonist and inhibits platelet aggregation."],"a":3,"e":"Correct answer: D. Losartan acts as a thromboxane A2 antagonist and inhibits platelet aggregation. (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":78,"q":"The true statement among the following is___","o":["The dose of telmisartan should be reduced in renal failure but not in hepatic failure.","The dose of irbesartan should be reduced in case of mild-moderate hepatic failure and renal failure.","The dose of candesartan should be reduced in mild-moderate liver failure but not in renal failure.","Losartan acts as a thromboxane A2 antagonist and inhibits platelet aggregation."],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9575, 'Orthopaedics', 'Peripheral Nerve Injuries', 'Moderate', 'NEET PG 2023', 79, '{"id":9575,"subject":"Orthopaedics","chapter":"Peripheral Nerve Injuries","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":79,"q":"A patient at the orthopedics OPD complains of troubled sleep at night due to numbness and tingling sensation involving his lateral 3 digits. His symptoms are relieved as he lays his arms hanging from the bed. Which of the following options correctly describes his condition and the test used to assess it?","o":["Guyon''s canal syndrome, Froment''s test","Carpal tunnel syndrome, Froment''s test","Guyon''s canal syndrome, Durkan''s test","Carpal tunnel syndrome, Durkan''s test"],"a":3,"e":"Correct answer: D. Carpal tunnel syndrome, Durkan''s test (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":79,"q":"A patient at the orthopedics OPD complains of troubled sleep at night due to numbness and tingling sensation involving his lateral 3 digits. His symptoms are relieved as he lays his arms hanging from the bed. Which of the following options correctly describes his condition and the test used to assess it?","o":["Guyon''s canal syndrome, Froment''s test","Carpal tunnel syndrome, Froment''s test","Guyon''s canal syndrome, Durkan''s test","Carpal tunnel syndrome, Durkan''s test"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9576, 'Orthopaedics', 'Metabolic Disorders', 'Moderate', 'NEET PG 2023', 80, '{"id":9576,"subject":"Orthopaedics","chapter":"Metabolic Disorders","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":80,"q":"A child is brought to the orthopedics OPD with a deformity in the lower limb and hyperpigmented skin lesions. The x-ray of her thigh is shown below. What is the most likely diagnosis?","o":["Non-ossifying fibroma","Fibrous dysplasia","Paget''s disease","Osteogenesis imperfecta"],"a":1,"e":"Correct answer: B. Fibrous dysplasia (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":80,"q":"A child is brought to the orthopedics OPD with a deformity in the lower limb and hyperpigmented skin lesions. The x-ray of her thigh is shown below. What is the most likely diagnosis?","o":["Non-ossifying fibroma","Fibrous dysplasia","Paget''s disease","Osteogenesis imperfecta"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9577, 'Psychiatry', 'Schizophrenia Spectrum and Other Psychotic  Disorders', 'Moderate', 'NEET PG 2023', 81, '{"id":9577,"subject":"Psychiatry","chapter":"Schizophrenia Spectrum and Other Psychotic  Disorders","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":81,"q":"A schizophrenic patient was prescribed drug A after he did not respond to haloperidol and thioridazine. He now presents with excessive salivation, an increase in blood glucose, and hyperlipidemia. What is drug A?","o":["Ziprasidone","Risperidone","Clozapine","Aripiprazole"],"a":2,"e":"Correct answer: C. Clozapine (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":81,"q":"A schizophrenic patient was prescribed drug A after he did not respond to haloperidol and thioridazine. He now presents with excessive salivation, an increase in blood glucose, and hyperlipidemia. What is drug A?","o":["Ziprasidone","Risperidone","Clozapine","Aripiprazole"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9578, 'Orthopaedics', 'Orthopedics Oncology', 'Moderate', 'NEET PG 2023', 82, '{"id":9578,"subject":"Orthopaedics","chapter":"Orthopedics Oncology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":82,"q":"The given image is an x-ray of a 22-year-old female. What is the probable diagnosis?","o":["Chondroblastoma","Osteochondroma","Giant cell tumor","Aneurysmal bone cyst"],"a":2,"e":"Correct answer: C. Giant cell tumor (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":82,"q":"The given image is an x-ray of a 22-year-old female. What is the probable diagnosis?","o":["Chondroblastoma","Osteochondroma","Giant cell tumor","Aneurysmal bone cyst"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9579, 'Physiology', 'Respiratory System', 'Moderate', 'NEET PG 2023', 83, '{"id":9579,"subject":"Physiology","chapter":"Respiratory System","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":83,"q":"Identify the marked region in the given spirometry.","o":["Functional residual capacity","Tidal volume","Expiratory reserve volume","Expiratory capacity"],"a":0,"e":"Correct answer: A. Functional residual capacity (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":83,"q":"Identify the marked region in the given spirometry.","o":["Functional residual capacity","Tidal volume","Expiratory reserve volume","Expiratory capacity"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9580, 'Surgery', 'Cardiothoracic Vascular Surgery', 'Moderate', 'NEET PG 2023', 84, '{"id":9580,"subject":"Surgery","chapter":"Cardiothoracic Vascular Surgery","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":84,"q":"A patient with varicose veins complains of eczema over the same region. What is the stage of the clinical classification according to the CEAP guidelines? CEAP-Clinical-Aetiology-Anatomy- Pathophysiology classification of chronic venous disorders","o":["C2","C3","C4a","C4b"],"a":2,"e":"Correct answer: C. C4a (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":84,"q":"A patient with varicose veins complains of eczema over the same region. What is the stage of the clinical classification according to the CEAP guidelines? CEAP-Clinical-Aetiology-Anatomy- Pathophysiology classification of chronic venous disorders","o":["C2","C3","C4a","C4b"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9581, 'Surgery', 'Neurosurgery', 'Moderate', 'NEET PG 2023', 85, '{"id":9581,"subject":"Surgery","chapter":"Neurosurgery","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":85,"q":"A patient comes to the casualty with a severe headache. His BP was found to be 160/100 mmHg. CT scan revealed a subarachnoid hemorrhage. What is the next best step in the management of this patient?","o":["Nimodipine","Angiography","Surgery","Fibrinolytic therapy"],"a":1,"e":"Correct answer: B. Angiography (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":85,"q":"A patient comes to the casualty with a severe headache. His BP was found to be 160/100 mmHg. CT scan revealed a subarachnoid hemorrhage. What is the next best step in the management of this patient?","o":["Nimodipine","Angiography","Surgery","Fibrinolytic therapy"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9582, 'Physiology', 'General Physiology', 'Moderate', 'NEET PG 2023', 86, '{"id":9582,"subject":"Physiology","chapter":"General Physiology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":86,"q":"A man was brought to the emergency after suddenly becoming unconscious while working in the field. On examination, his temperature was 105 degrees Fahrenheit, and his skin turgor was decreased. Which of the following would not be seen in the patient?","o":["Tachypnea","Hypotension","Sweating","Red hot skin"],"a":2,"e":"Correct answer: C. Sweating (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":86,"q":"A man was brought to the emergency after suddenly becoming unconscious while working in the field. On examination, his temperature was 105 degrees Fahrenheit, and his skin turgor was decreased. Which of the following would not be seen in the patient?","o":["Tachypnea","Hypotension","Sweating","Red hot skin"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9583, 'Physiology', 'Excretory System', 'Moderate', 'NEET PG 2023', 87, '{"id":9583,"subject":"Physiology","chapter":"Excretory System","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":87,"q":"Identify the correctly matched pair of substances with their renal clearance from the graph below.","o":["A-Glucose, B-PAH, C- Bicarbonate and D - Inulin","A-Glucose, B- Bicarbonate, C-Inulin and D - PAH","A-PAH, B-Inulin, C - Glucose and D - Bicarbonate","A - Inulin, B - Glucose, C - Bicarbonate and D - PAH"],"a":1,"e":"Correct answer: B. A-Glucose, B- Bicarbonate, C-Inulin and D - PAH (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":87,"q":"Identify the correctly matched pair of substances with their renal clearance from the graph below.","o":["A-Glucose, B-PAH, C- Bicarbonate and D - Inulin","A-Glucose, B- Bicarbonate, C-Inulin and D - PAH","A-PAH, B-Inulin, C - Glucose and D - Bicarbonate","A - Inulin, B - Glucose, C - Bicarbonate and D - PAH"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9584, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'NEET PG 2023', 88, '{"id":9584,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":88,"q":"A 20-year-old female patient consumed a cleaning product containing 90% sodium hydroxide. She is having complete dysphagia. What is the best step in management?","o":["Esophagojejunostomy","Stent placement","Feeding jejunostomy","Gastrojejunostomy"],"a":2,"e":"Correct answer: C. Feeding jejunostomy (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":88,"q":"A 20-year-old female patient consumed a cleaning product containing 90% sodium hydroxide. She is having complete dysphagia. What is the best step in management?","o":["Esophagojejunostomy","Stent placement","Feeding jejunostomy","Gastrojejunostomy"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9585, 'Surgery', 'Endocrine Surgery', 'Moderate', 'NEET PG 2023', 89, '{"id":9585,"subject":"Surgery","chapter":"Endocrine Surgery","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":89,"q":"A 23-year-old male patient presents with midline swelling in the neck. The swelling moves with deglutition and protrusion of the tongue. What is the likely diagnosis?","o":["Brachial cyst","Thyroglossal cyst","Plunging ranula","Dermoid cyst"],"a":1,"e":"Correct answer: B. Thyroglossal cyst (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":89,"q":"A 23-year-old male patient presents with midline swelling in the neck. The swelling moves with deglutition and protrusion of the tongue. What is the likely diagnosis?","o":["Brachial cyst","Thyroglossal cyst","Plunging ranula","Dermoid cyst"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9586, 'Physiology', 'Nerve Muscle Physiology', 'Moderate', 'NEET PG 2023', 90, '{"id":9586,"subject":"Physiology","chapter":"Nerve Muscle Physiology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":90,"q":"Identify the true statement regarding the given nerve action potential curve?","o":["The threshold point is at A","At point E, the nerve is more excitable","Point C to D is due to the opening of Na+ and closure of K+ channels","Point B to D is a refractory period"],"a":3,"e":"Correct answer: D. Point B to D is a refractory period (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":90,"q":"Identify the true statement regarding the given nerve action potential curve?","o":["The threshold point is at A","At point E, the nerve is more excitable","Point C to D is due to the opening of Na+ and closure of K+ channels","Point B to D is a refractory period"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9587, 'Surgery', 'Others', 'Moderate', 'NEET PG 2023', 91, '{"id":9587,"subject":"Surgery","chapter":"Others","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":91,"q":"A young patient is admitted with a history of fever for 5 days. BP is 90/60 mmHg, PR-120 bpm, RR-24 breaths/ min, GCS score-10; laboratory tests show leucocytosis with neutrophilia and serum creatinine level of 2.6 mg/ dL. An intern doctor wants to calculate the qSOFA score to predict prognosis and hospitalization duration. Which of the following comprises the qSOFA score?","o":["BP, RR and CBC","Creatinine, PR, BP","RR, Body temperature, PR","SBP, RR, GCS score"],"a":3,"e":"Correct answer: D. SBP, RR, GCS score (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":91,"q":"A young patient is admitted with a history of fever for 5 days. BP is 90/60 mmHg, PR-120 bpm, RR-24 breaths/ min, GCS score-10; laboratory tests show leucocytosis with neutrophilia and serum creatinine level of 2.6 mg/ dL. An intern doctor wants to calculate the qSOFA score to predict prognosis and hospitalization duration. Which of the following comprises the qSOFA score?","o":["BP, RR and CBC","Creatinine, PR, BP","RR, Body temperature, PR","SBP, RR, GCS score"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9588, 'Physiology', 'General Physiology', 'Moderate', 'NEET PG 2023', 92, '{"id":9588,"subject":"Physiology","chapter":"General Physiology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":92,"q":"Identify the type of transport across the cell membrane given below?","o":["Simple diffusion","Facilitated diffusion","Primary active transport","Secondary active transport"],"a":1,"e":"Correct answer: B. Facilitated diffusion (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":92,"q":"Identify the type of transport across the cell membrane given below?","o":["Simple diffusion","Facilitated diffusion","Primary active transport","Secondary active transport"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9589, 'Medicine', 'Cardiology', 'Moderate', 'NEET PG 2023', 93, '{"id":9589,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":93,"q":"Identify the condition associated with the murmur in the image below.","o":["Mitral regurgitation","Aortic regurgitation","Aortic stenosis","Mitral stenosis"],"a":0,"e":"Correct answer: A. Mitral regurgitation (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":93,"q":"Identify the condition associated with the murmur in the image below.","o":["Mitral regurgitation","Aortic regurgitation","Aortic stenosis","Mitral stenosis"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9590, 'Psychiatry', 'Mood Disorders', 'Moderate', 'NEET PG 2023', 94, '{"id":9590,"subject":"Psychiatry","chapter":"Mood Disorders","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":94,"q":"A woman, who is 4 days postpartum, presented with tearfulness, mood swings, and occasional insomnia. What is the likely diagnosis?","o":["Postpartum depression","Postpartum blues","Postpartum psychosis","Postpartum anxiety"],"a":1,"e":"Correct answer: B. Postpartum blues (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":94,"q":"A woman, who is 4 days postpartum, presented with tearfulness, mood swings, and occasional insomnia. What is the likely diagnosis?","o":["Postpartum depression","Postpartum blues","Postpartum psychosis","Postpartum anxiety"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9591, 'Psychiatry', 'Neurotic, Stress-Related and Somatoform Disorders', 'Moderate', 'NEET PG 2023', 95, '{"id":9591,"subject":"Psychiatry","chapter":"Neurotic, Stress-Related and Somatoform Disorders","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":95,"q":"A 25-year-old female reported symptoms of anxiety, palpitations, sweating, breathlessness, chest pain, and a feeling of impending doom. She recalls having experienced 5-6 similar episodes in the past 6 months, each episode lasting for about 20-30 minutes. What is the likely diagnosis?","o":["Depression","Panic disorder","Generalized anxiety disorder","Phobia"],"a":1,"e":"Correct answer: B. Panic disorder (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":95,"q":"A 25-year-old female reported symptoms of anxiety, palpitations, sweating, breathlessness, chest pain, and a feeling of impending doom. She recalls having experienced 5-6 similar episodes in the past 6 months, each episode lasting for about 20-30 minutes. What is the likely diagnosis?","o":["Depression","Panic disorder","Generalized anxiety disorder","Phobia"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9592, 'Medicine', 'Rheumatology / Connective Tissue Disorder', 'Moderate', 'NEET PG 2023', 96, '{"id":9592,"subject":"Medicine","chapter":"Rheumatology / Connective Tissue Disorder","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":96,"q":"A young man came to the medical OPD with complaints of early morning backache and stiffness, which improves on exercise, and persistent red eyes. On examination, lung expansion was less than 3 cm. X-ray is shown in the image given below. What is the most probable diagnosis?","o":["Ankylosing spondylitis","Paget''s disease","Healed tuberculosis","Osteopetrosis"],"a":0,"e":"Correct answer: A. Ankylosing spondylitis (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":96,"q":"A young man came to the medical OPD with complaints of early morning backache and stiffness, which improves on exercise, and persistent red eyes. On examination, lung expansion was less than 3 cm. X-ray is shown in the image given below. What is the most probable diagnosis?","o":["Ankylosing spondylitis","Paget''s disease","Healed tuberculosis","Osteopetrosis"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9593, 'Medicine', 'Nephrology / Kidney Disease', 'Moderate', 'NEET PG 2023', 97, '{"id":9593,"subject":"Medicine","chapter":"Nephrology / Kidney Disease","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":97,"q":"A patient with hyperkalemia and elevated urea levels underwent dialysis. Towards the end of the session, she became drowsy and had a sudden seizure episode. On examination, the patient was hypotensive. What is the treatment for this condition?","o":["Bumetanide","Ethacrynic acid","Nesiritide","IV Mannitol"],"a":3,"e":"Correct answer: D. IV Mannitol (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":97,"q":"A patient with hyperkalemia and elevated urea levels underwent dialysis. Towards the end of the session, she became drowsy and had a sudden seizure episode. On examination, the patient was hypotensive. What is the treatment for this condition?","o":["Bumetanide","Ethacrynic acid","Nesiritide","IV Mannitol"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9594, 'Medicine', 'Endocrinology', 'Moderate', 'NEET PG 2023', 98, '{"id":9594,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":98,"q":"A female patient presents to the emergency department with severe restlessness, palpitations, and tremors. She is a known case of bronchial asthma. On examination, the neck looks swollen. Blood pressure is elevated, and tachycardia is noted. ECG shows atrial fibrillation. Which of the following drugs is used for immediate management in this patient?","o":["Diltiazem","Propranolol","Esmolol","Propylthiouracil"],"a":0,"e":"Correct answer: A. Diltiazem (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":98,"q":"A female patient presents to the emergency department with severe restlessness, palpitations, and tremors. She is a known case of bronchial asthma. On examination, the neck looks swollen. Blood pressure is elevated, and tachycardia is noted. ECG shows atrial fibrillation. Which of the following drugs is used for immediate management in this patient?","o":["Diltiazem","Propranolol","Esmolol","Propylthiouracil"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9595, 'Physiology', 'Respiratory System', 'Moderate', 'NEET PG 2023', 99, '{"id":9595,"subject":"Physiology","chapter":"Respiratory System","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":99,"q":"A preterm baby who was delivered at 28 weeks developed respiratory distress syndrome. Which of the following is true about surface tension and compliance in this baby?","o":["Surface tension - decreased; Compliance - increased","Surface tension - increased; Compliance - decreased","Both surface tension and compliance decreased","Both surface tension and compliance increased"],"a":1,"e":"Correct answer: B. Surface tension - increased; Compliance - decreased (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":99,"q":"A preterm baby who was delivered at 28 weeks developed respiratory distress syndrome. Which of the following is true about surface tension and compliance in this baby?","o":["Surface tension - decreased; Compliance - increased","Surface tension - increased; Compliance - decreased","Both surface tension and compliance decreased","Both surface tension and compliance increased"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9596, 'Psychiatry', 'Sexual Disorders', 'Moderate', 'NEET PG 2023', 100, '{"id":9596,"subject":"Psychiatry","chapter":"Sexual Disorders","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":100,"q":"A middle-aged man complains of very early ejaculation during intercourse. What is the non-pharmacological management that can be advised to the patient?","o":["Cognitive behavioral therapy","Exposure and response prevention therapy","Squeeze technique","Sensate focus therapy"],"a":2,"e":"Correct answer: C. Squeeze technique (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":100,"q":"A middle-aged man complains of very early ejaculation during intercourse. What is the non-pharmacological management that can be advised to the patient?","o":["Cognitive behavioral therapy","Exposure and response prevention therapy","Squeeze technique","Sensate focus therapy"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9597, 'Medicine', 'Liver', 'Moderate', 'NEET PG 2023', 101, '{"id":9597,"subject":"Medicine","chapter":"Liver","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":101,"q":"A 30-year-old male is found to be positive for HBsAg and HBeAg and is diagnosed with chronic hepatitis B. The patient’s viral load was 2x 100000 and SGPT is found to be doubled. What is the appropriate management in this patient? SGPT-Serum glutamate pyruvate transaminase","o":["Lamivudine for 30+ weeks","Tenofovir for> 40 weeks","Pegylated interferon for 52 weeks","Combined pegylated interferon with lamivudine"],"a":1,"e":"Correct answer: B. Tenofovir for> 40 weeks (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":101,"q":"A 30-year-old male is found to be positive for HBsAg and HBeAg and is diagnosed with chronic hepatitis B. The patient’s viral load was 2x 100000 and SGPT is found to be doubled. What is the appropriate management in this patient? SGPT-Serum glutamate pyruvate transaminase","o":["Lamivudine for 30+ weeks","Tenofovir for> 40 weeks","Pegylated interferon for 52 weeks","Combined pegylated interferon with lamivudine"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9598, 'Medicine', 'Endocrinology', 'Moderate', 'NEET PG 2023', 102, '{"id":9598,"subject":"Medicine","chapter":"Endocrinology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":102,"q":"A 25-year-old male patient complained of palpitations, sweating, and restlessness. He has a complaint of sweaty palms. Clinical findings are depicted in the image given below. What is the diagnostic test done on this patient?","o":["Anti-thyroglobulin antibody","Anti-thyroid peroxidase antibody","Thyroid receptor antibody","Elevated ultrasensitive thyrotropin levels"],"a":2,"e":"Correct answer: C. Thyroid receptor antibody (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":102,"q":"A 25-year-old male patient complained of palpitations, sweating, and restlessness. He has a complaint of sweaty palms. Clinical findings are depicted in the image given below. What is the diagnostic test done on this patient?","o":["Anti-thyroglobulin antibody","Anti-thyroid peroxidase antibody","Thyroid receptor antibody","Elevated ultrasensitive thyrotropin levels"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9599, 'Medicine', 'Oncology', 'Moderate', 'NEET PG 2023', 103, '{"id":9599,"subject":"Medicine","chapter":"Oncology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":103,"q":"A 50-year-old HIV patient presented with a painless lesion, as shown in the image. What is the most likely diagnosis?","o":["Basal cell carcinoma","Kaposi sarcoma","Malignant melanoma","Squamous cell carcinoma"],"a":1,"e":"Correct answer: B. Kaposi sarcoma (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":103,"q":"A 50-year-old HIV patient presented with a painless lesion, as shown in the image. What is the most likely diagnosis?","o":["Basal cell carcinoma","Kaposi sarcoma","Malignant melanoma","Squamous cell carcinoma"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9600, 'Physiology', 'Nerve Muscle Physiology', 'Moderate', 'NEET PG 2023', 104, '{"id":9600,"subject":"Physiology","chapter":"Nerve Muscle Physiology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":104,"q":"A patient came to the hospital after a road traffic accident. He had severe muscle injury, and his serum K+ level was found to be 5.5 mEq/L. What will happen to the resting membrane potential in this patient?","o":["No change","Becomes more negative","Becomes more positive","First becomes more positive then negative"],"a":2,"e":"Correct answer: C. Becomes more positive (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":104,"q":"A patient came to the hospital after a road traffic accident. He had severe muscle injury, and his serum K+ level was found to be 5.5 mEq/L. What will happen to the resting membrane potential in this patient?","o":["No change","Becomes more negative","Becomes more positive","First becomes more positive then negative"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9601, 'Pediatrics', 'Pediatric Respiratory Disorders', 'Moderate', 'NEET PG 2023', 105, '{"id":9601,"subject":"Pediatrics","chapter":"Pediatric Respiratory Disorders","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":105,"q":"A newborn presented with chest retractions, dyspnea, and lethargy. The pediatrician diagnosed the baby with respiratory distress syndrome. This occurs due to the deficiency of:","o":["Dipalmitoyl inositol","Lecithin","Sphingomyelin","Dipalmitoylphosphatidylethanolamine"],"a":1,"e":"Correct answer: B. Lecithin (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":105,"q":"A newborn presented with chest retractions, dyspnea, and lethargy. The pediatrician diagnosed the baby with respiratory distress syndrome. This occurs due to the deficiency of:","o":["Dipalmitoyl inositol","Lecithin","Sphingomyelin","Dipalmitoylphosphatidylethanolamine"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9602, 'Medicine', 'Neurology', 'Moderate', 'NEET PG 2023', 106, '{"id":9602,"subject":"Medicine","chapter":"Neurology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":106,"q":"A patient is brought to the OPD by his wife, complaining about difficulty expressing emotions and not participating in daily activities. On examination, resting tremors and rigidity are noted. Given the possible diagnosis, which part of the brain is affected in this patient?","o":["Basal ganglia","Hippocampus","Cerebellum","Premotor cortex"],"a":0,"e":"Correct answer: A. Basal ganglia (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":106,"q":"A patient is brought to the OPD by his wife, complaining about difficulty expressing emotions and not participating in daily activities. On examination, resting tremors and rigidity are noted. Given the possible diagnosis, which part of the brain is affected in this patient?","o":["Basal ganglia","Hippocampus","Cerebellum","Premotor cortex"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9603, 'Medicine', 'Infections', 'Moderate', 'NEET PG 2023', 107, '{"id":9603,"subject":"Medicine","chapter":"Infections","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":107,"q":"A 45-year-old HIV-positive male complained of persistent cough and weight loss. He has skin lesions that appear as umbilicated papules and nodules predominantly on the face, trunk, and upper extremities. Chest x-ray showed multiple bilateral nodular infiltrates. His sputum CBNAAT for tuberculosis was negative, and he has a low CD4 count. What is the probable diagnosis?","o":["HIV with disseminated histoplasmosis","HIV with disseminated cryptococcosis","HIV with molluscum contagiosum","HIV with tuberculosis"],"a":0,"e":"Correct answer: A. HIV with disseminated histoplasmosis (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":107,"q":"A 45-year-old HIV-positive male complained of persistent cough and weight loss. He has skin lesions that appear as umbilicated papules and nodules predominantly on the face, trunk, and upper extremities. Chest x-ray showed multiple bilateral nodular infiltrates. His sputum CBNAAT for tuberculosis was negative, and he has a low CD4 count. What is the probable diagnosis?","o":["HIV with disseminated histoplasmosis","HIV with disseminated cryptococcosis","HIV with molluscum contagiosum","HIV with tuberculosis"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9604, 'Physiology', 'The Nervous System', 'Moderate', 'NEET PG 2023', 108, '{"id":9604,"subject":"Physiology","chapter":"The Nervous System","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":108,"q":"A patient met with a road traffic accident and developed a cervical spine injury. The fracture fragment had pierced the lateral aspect of the dorsal column tract. Which of the following findings is seen in this patient?","o":["Absence of ipsilateral lower limb proprioception","Absence of fine motor movement of fingers","Absence of ipsilateral arm proprioception","Absence of contralateral lower limb proprioception"],"a":2,"e":"Correct answer: C. Absence of ipsilateral arm proprioception (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":108,"q":"A patient met with a road traffic accident and developed a cervical spine injury. The fracture fragment had pierced the lateral aspect of the dorsal column tract. Which of the following findings is seen in this patient?","o":["Absence of ipsilateral lower limb proprioception","Absence of fine motor movement of fingers","Absence of ipsilateral arm proprioception","Absence of contralateral lower limb proprioception"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9605, 'Medicine', 'Neurology', 'Moderate', 'NEET PG 2023', 109, '{"id":9605,"subject":"Medicine","chapter":"Neurology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":109,"q":"A male patient presented to the emergency room with seizures. He has a history of fever, headache, and confusion. An MRI brain was done, and it showed inflammation involving the bitemporal lobe. What is the most likely aetiology for this presentation?","o":["Cytomegalovirus","Toxoplasma gondii","Herpes simplex virus","Mycobacterium tuberculosis"],"a":2,"e":"Correct answer: C. Herpes simplex virus (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":109,"q":"A male patient presented to the emergency room with seizures. He has a history of fever, headache, and confusion. An MRI brain was done, and it showed inflammation involving the bitemporal lobe. What is the most likely aetiology for this presentation?","o":["Cytomegalovirus","Toxoplasma gondii","Herpes simplex virus","Mycobacterium tuberculosis"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9606, 'Physiology', 'Cardiovascular System', 'Moderate', 'NEET PG 2023', 110, '{"id":9606,"subject":"Physiology","chapter":"Cardiovascular System","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":110,"q":"Identify the true statement regarding the point marked(Red) on the myocardial action potential curve?","o":["Due to the opening of Na+ and closure of fast K+ channels","Due to the slow but prolonged opening of Ca2+ channels","Due to the closure of Na+ and opening of the slow K+ channel","Due to Na+/K+ ATPase"],"a":1,"e":"Correct answer: B. Due to the slow but prolonged opening of Ca2+ channels (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":110,"q":"Identify the true statement regarding the point marked(Red) on the myocardial action potential curve?","o":["Due to the opening of Na+ and closure of fast K+ channels","Due to the slow but prolonged opening of Ca2+ channels","Due to the closure of Na+ and opening of the slow K+ channel","Due to Na+/K+ ATPase"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9607, 'Medicine', 'Cardiology', 'Moderate', 'NEET PG 2023', 111, '{"id":9607,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":111,"q":"A male patient presents with sensory loss and weakness of limbs for 3 months. He also has angular stomatitis. On examination, there is loss of proprioception, vibration sensations, UMN type of lower limb weakness, and absent ankle reflex. What is the most probable diagnosis?","o":["Extradural cord compression","Amyotrophic lateral sclerosis","Multiple sclerosis","Subacute combined degeneration of cord"],"a":3,"e":"Correct answer: D. Subacute combined degeneration of cord (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":111,"q":"A male patient presents with sensory loss and weakness of limbs for 3 months. He also has angular stomatitis. On examination, there is loss of proprioception, vibration sensations, UMN type of lower limb weakness, and absent ankle reflex. What is the most probable diagnosis?","o":["Extradural cord compression","Amyotrophic lateral sclerosis","Multiple sclerosis","Subacute combined degeneration of cord"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9608, 'Pediatrics', 'Fluid and Electrolyte Disturbances', 'Moderate', 'NEET PG 2023', 112, '{"id":9608,"subject":"Pediatrics","chapter":"Fluid and Electrolyte Disturbances","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":112,"q":"A 10-year-old child weighing 30 kg presents with a history of loose stools for 2 days. On examination, there is severe dehydration. Laboratory investigations are as follows. What is the initial management as per ISPAD guidelines? RBS 550mg/dL pH 7.01 Na+ 158mEq/L Urine glucose 3+","o":["Manage ABC, NS 20 mL/kg and start insulin after 1 hour","Manage ABC, NS 20 mL/kg along with insulin 0.1 IU/kg/hr","Manage ABC, NS 10 mL/kg along with insulin 0.1 IU/kg/hr","Manage ABC, NS 10 mL/kg and start insulin after 1 hour"],"a":0,"e":"Correct answer: A. Manage ABC, NS 20 mL/kg and start insulin after 1 hour (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":112,"q":"A 10-year-old child weighing 30 kg presents with a history of loose stools for 2 days. On examination, there is severe dehydration. Laboratory investigations are as follows. What is the initial management as per ISPAD guidelines? RBS 550mg/dL pH 7.01 Na+ 158mEq/L Urine glucose 3+","o":["Manage ABC, NS 20 mL/kg and start insulin after 1 hour","Manage ABC, NS 20 mL/kg along with insulin 0.1 IU/kg/hr","Manage ABC, NS 10 mL/kg along with insulin 0.1 IU/kg/hr","Manage ABC, NS 10 mL/kg and start insulin after 1 hour"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9609, 'Pediatrics', 'Growth', 'Moderate', 'NEET PG 2023', 113, '{"id":9609,"subject":"Pediatrics","chapter":"Growth","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":113,"q":"Which of the following is the best sign to indicate adequate growth in an infant with a birth weight of 2.8 kg?","o":["Increase in length of 25 centimetres in the first year","Weight gain of 300 grams per month till 1 year","Anterior fontanelle closure by 6 months of age","Weight under the 75th percentile and height under the 25th percentile"],"a":0,"e":"Correct answer: A. Increase in length of 25 centimetres in the first year (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":113,"q":"Which of the following is the best sign to indicate adequate growth in an infant with a birth weight of 2.8 kg?","o":["Increase in length of 25 centimetres in the first year","Weight gain of 300 grams per month till 1 year","Anterior fontanelle closure by 6 months of age","Weight under the 75th percentile and height under the 25th percentile"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9610, 'Medicine', 'Cardiology', 'Moderate', 'NEET PG 2023', 114, '{"id":9610,"subject":"Medicine","chapter":"Cardiology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":114,"q":"A 40-year-old female patient came with complaints of chest pain, palpitation, and shortness of breath. On examination, a mid-diastolic murmur was heard, and a prominent ''a'' wave was found on JVP. What is the most likely diagnosis?","o":["Mitral stenosis","Tricuspid stenosis","Mitral regurgitation","Tricuspid regurgitation"],"a":1,"e":"Correct answer: B. Tricuspid stenosis (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":114,"q":"A 40-year-old female patient came with complaints of chest pain, palpitation, and shortness of breath. On examination, a mid-diastolic murmur was heard, and a prominent ''a'' wave was found on JVP. What is the most likely diagnosis?","o":["Mitral stenosis","Tricuspid stenosis","Mitral regurgitation","Tricuspid regurgitation"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9611, 'Pediatrics', 'Infectious Diseases', 'Moderate', 'NEET PG 2023', 115, '{"id":9611,"subject":"Pediatrics","chapter":"Infectious Diseases","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":115,"q":"A 3-month-old baby complains of deafness, cataract, and patent ductus arteriosus. Which of the following is the most likely diagnosis?","o":["Congenital herpes simplex virus infection","Congenital toxoplasmosis","Congenital cytomegalovirus infection","Congenital rubella syndrome"],"a":3,"e":"Correct answer: D. Congenital rubella syndrome (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":115,"q":"A 3-month-old baby complains of deafness, cataract, and patent ductus arteriosus. Which of the following is the most likely diagnosis?","o":["Congenital herpes simplex virus infection","Congenital toxoplasmosis","Congenital cytomegalovirus infection","Congenital rubella syndrome"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9612, 'PSM', 'Nutrition and Health', 'Moderate', 'NEET PG 2023', 116, '{"id":9612,"subject":"PSM","chapter":"Nutrition and Health","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":116,"q":"In a village, it is observed that several farmers have crossed gait and use a stick for support to stand up and walk. Due to poor yield from farms, they consume meals containing rice and pulses only. Supplementing their diet with which of the following vitamins could have prevented this?","o":["Vitamin A","Vitamin D","Vitamin C","Vitamin B"],"a":2,"e":"Correct answer: C. Vitamin C (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":116,"q":"In a village, it is observed that several farmers have crossed gait and use a stick for support to stand up and walk. Due to poor yield from farms, they consume meals containing rice and pulses only. Supplementing their diet with which of the following vitamins could have prevented this?","o":["Vitamin A","Vitamin D","Vitamin C","Vitamin B"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9613, 'PSM', 'Epidemiology', 'Moderate', 'NEET PG 2023', 117, '{"id":9613,"subject":"PSM","chapter":"Epidemiology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":117,"q":"Research is being conducted to find the association between aniline dye exposure and bladder cancer in workers who have worked in the industry for >20 years. Two groups were formed: one directly involved with dye handling and the other group consisting of office clerks not directly exposed to the dye. Years of occupation were noted from records. What type of study is being performed?","o":["Retrospective cohort study","Prospective cohort study","Case-control study","Intervention and response"],"a":0,"e":"Correct answer: A. Retrospective cohort study (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":117,"q":"Research is being conducted to find the association between aniline dye exposure and bladder cancer in workers who have worked in the industry for >20 years. Two groups were formed: one directly involved with dye handling and the other group consisting of office clerks not directly exposed to the dye. Years of occupation were noted from records. What type of study is being performed?","o":["Retrospective cohort study","Prospective cohort study","Case-control study","Intervention and response"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9614, 'Pediatrics', 'Pediatric Respiratory Disorders', 'Moderate', 'NEET PG 2023', 118, '{"id":9614,"subject":"Pediatrics","chapter":"Pediatric Respiratory Disorders","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":118,"q":"Chloride level in sweat is used in the diagnosis of which disease?","o":["Phenylketonuria","Cystic fibrosis","Gaucher''s disease","Osteogenesis imperfecta"],"a":1,"e":"Correct answer: B. Cystic fibrosis (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":118,"q":"Chloride level in sweat is used in the diagnosis of which disease?","o":["Phenylketonuria","Cystic fibrosis","Gaucher''s disease","Osteogenesis imperfecta"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9615, 'Pediatrics', 'Infectious Diseases', 'Moderate', 'NEET PG 2023', 119, '{"id":9615,"subject":"Pediatrics","chapter":"Infectious Diseases","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":119,"q":"A child presents with fever and a rash spreading from the face, behind cheeks, and buccal mucosa to other body parts. On examination, Koplik''s spot is present. What is the likely diagnosis?","o":["Measles","Rubella","Varicella","Mumps"],"a":0,"e":"Correct answer: A. Measles (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":119,"q":"A child presents with fever and a rash spreading from the face, behind cheeks, and buccal mucosa to other body parts. On examination, Koplik''s spot is present. What is the likely diagnosis?","o":["Measles","Rubella","Varicella","Mumps"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9616, 'PSM', 'Concept of Health and Disease', 'Moderate', 'NEET PG 2023', 120, '{"id":9616,"subject":"PSM","chapter":"Concept of Health and Disease","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":120,"q":"The blood pressure of a population was tracked from childhood to adulthood. It was observed that those who had lower BP in childhood had low BP in adulthood, while those who had higher BP in childhood had high BP in adulthood. This can be best described as","o":["Rule of halves","Tracking of blood pressure","STEPwise approach","Primordial approach"],"a":1,"e":"Correct answer: B. Tracking of blood pressure (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":120,"q":"The blood pressure of a population was tracked from childhood to adulthood. It was observed that those who had lower BP in childhood had low BP in adulthood, while those who had higher BP in childhood had high BP in adulthood. This can be best described as","o":["Rule of halves","Tracking of blood pressure","STEPwise approach","Primordial approach"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9617, 'Pediatrics', 'Infectious Diseases', 'Moderate', 'NEET PG 2023', 121, '{"id":9617,"subject":"Pediatrics","chapter":"Infectious Diseases","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":121,"q":"A 3-week-old infant presents with a cough and sore throat. The mother reports that the infant develops a paroxysm of cough followed by apnea. The total leucocyte count is >50,000 cells/μL. Which of the following drugs will you prescribe for this patient?","o":["Azithromycin","Amoxicillin","Cotrimoxazole","Clarithromycin"],"a":0,"e":"Correct answer: A. Azithromycin (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":121,"q":"A 3-week-old infant presents with a cough and sore throat. The mother reports that the infant develops a paroxysm of cough followed by apnea. The total leucocyte count is >50,000 cells/μL. Which of the following drugs will you prescribe for this patient?","o":["Azithromycin","Amoxicillin","Cotrimoxazole","Clarithromycin"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9618, 'PSM', 'Health Care of The Community in India', 'Moderate', 'NEET PG 2023', 122, '{"id":9618,"subject":"PSM","chapter":"Health Care of The Community in India","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":122,"q":"A 30-week primigravida complaints of reduced vision at night. She has been avoiding papaya, mango, and other fruits throughout her pregnancy as she thinks they could be abortifacients. It is the primary duty of which of the following workers to provide counseling and information to the patient?","o":["ANM","AWW","Trained birth attendant","ASHA"],"a":3,"e":"Correct answer: D. ASHA (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":122,"q":"A 30-week primigravida complaints of reduced vision at night. She has been avoiding papaya, mango, and other fruits throughout her pregnancy as she thinks they could be abortifacients. It is the primary duty of which of the following workers to provide counseling and information to the patient?","o":["ANM","AWW","Trained birth attendant","ASHA"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9619, 'ENT', 'Pharynx', 'Moderate', 'NEET PG 2023', 123, '{"id":9619,"subject":"ENT","chapter":"Pharynx","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":123,"q":"Identify the structure marked in the image.","o":["Fossa of Rosenmuller","Tubal tonsil","Opening of the Eustachian tube","Adenoid"],"a":0,"e":"Correct answer: A. Fossa of Rosenmuller (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":123,"q":"Identify the structure marked in the image.","o":["Fossa of Rosenmuller","Tubal tonsil","Opening of the Eustachian tube","Adenoid"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9620, 'PSM', 'Communicable and Non-communicable Diseases', 'Moderate', 'NEET PG 2023', 124, '{"id":9620,"subject":"PSM","chapter":"Communicable and Non-communicable Diseases","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":124,"q":"A 22-year-old female comes to the STI clinic with minimal vaginal discharge. On speculum examination, erosions are seen on the cervix. Which of the following kit should be given to this patient?","o":["Green","Red","Grey","Yellow"],"a":2,"e":"Correct answer: C. Grey (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":124,"q":"A 22-year-old female comes to the STI clinic with minimal vaginal discharge. On speculum examination, erosions are seen on the cervix. Which of the following kit should be given to this patient?","o":["Green","Red","Grey","Yellow"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9621, 'PSM', 'Concept of Health and Disease', 'Moderate', 'NEET PG 2023', 125, '{"id":9621,"subject":"PSM","chapter":"Concept of Health and Disease","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":125,"q":"The years of potential life lost could be attributed to,","o":["Years lost to morbidity","Years lost due to premature death","Years lost to disability","Years lost to poor quality of life"],"a":1,"e":"Correct answer: B. Years lost due to premature death (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":125,"q":"The years of potential life lost could be attributed to,","o":["Years lost to morbidity","Years lost due to premature death","Years lost to disability","Years lost to poor quality of life"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9622, 'ENT', 'Pharynx', 'Moderate', 'NEET PG 2023', 126, '{"id":9622,"subject":"ENT","chapter":"Pharynx","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":126,"q":"The instrument shown in the image is not used for which of the following?","o":["Airway toileting","Upper airway examination","Acute nasopharyngeal obstruction","Prolonged mechanical ventilation"],"a":1,"e":"Correct answer: B. Upper airway examination (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":126,"q":"The instrument shown in the image is not used for which of the following?","o":["Airway toileting","Upper airway examination","Acute nasopharyngeal obstruction","Prolonged mechanical ventilation"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9623, 'PSM', 'Vaccines and Cold Chain', 'Moderate', 'NEET PG 2023', 127, '{"id":9623,"subject":"PSM","chapter":"Vaccines and Cold Chain","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":127,"q":"In a 10-year-old school child, which of the following vaccines is given as a part of the school immunization program?","o":["Measles vaccine","Rotavirus vaccine","TT/Td vaccine","Hepatitis B vaccine"],"a":2,"e":"Correct answer: C. TT/Td vaccine (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":127,"q":"In a 10-year-old school child, which of the following vaccines is given as a part of the school immunization program?","o":["Measles vaccine","Rotavirus vaccine","TT/Td vaccine","Hepatitis B vaccine"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9624, 'ENT', 'Pharynx', 'Moderate', 'NEET PG 2023', 128, '{"id":9624,"subject":"ENT","chapter":"Pharynx","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":128,"q":"A 10-year-old child presents with throat pain, fever, and ear pain. He is diagnosed with recurrent tonsillitis. Which nerve is responsible for the ear pain in this patient?","o":["Tympanic branch of the glossopharyngeal nerve","Greater auricular nerve","Auriculotemporal nerve","Auricular branch of the vagus nerve"],"a":0,"e":"Correct answer: A. Tympanic branch of the glossopharyngeal nerve (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":128,"q":"A 10-year-old child presents with throat pain, fever, and ear pain. He is diagnosed with recurrent tonsillitis. Which nerve is responsible for the ear pain in this patient?","o":["Tympanic branch of the glossopharyngeal nerve","Greater auricular nerve","Auriculotemporal nerve","Auricular branch of the vagus nerve"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9625, 'PSM', 'International Health', 'Moderate', 'NEET PG 2023', 129, '{"id":9625,"subject":"PSM","chapter":"International Health","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":129,"q":"Which of the following statements is true about cancer treatment according to the Colombo plan?","o":["Help with PET scan units for diagnosis of cancer","Human resource strengthening","Setting up chemotherapy units","Setting up cobalt therapy units"],"a":3,"e":"Correct answer: D. Setting up cobalt therapy units (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":129,"q":"Which of the following statements is true about cancer treatment according to the Colombo plan?","o":["Help with PET scan units for diagnosis of cancer","Human resource strengthening","Setting up chemotherapy units","Setting up cobalt therapy units"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9626, 'PSM', 'Nutrition and Health', 'Moderate', 'NEET PG 2023', 130, '{"id":9626,"subject":"PSM","chapter":"Nutrition and Health","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":130,"q":"A poor farmer with a history of successive crop failure develops progressive spastic paraparesis, signs of upper motor neuron paralysis, and gait instability. Name the toxin responsible for this condition.","o":["Aflatoxin","Beta-oxalyl-amino-alanine","Ergot alkaloids","Fusarium toxin"],"a":1,"e":"Correct answer: B. Beta-oxalyl-amino-alanine (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":130,"q":"A poor farmer with a history of successive crop failure develops progressive spastic paraparesis, signs of upper motor neuron paralysis, and gait instability. Name the toxin responsible for this condition.","o":["Aflatoxin","Beta-oxalyl-amino-alanine","Ergot alkaloids","Fusarium toxin"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9627, 'PSM', 'Vaccines and Cold Chain', 'Moderate', 'NEET PG 2023', 131, '{"id":9627,"subject":"PSM","chapter":"Vaccines and Cold Chain","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":131,"q":"A young male came to the hospital with a clean-cut wound without any bleeding. The patient received a full course of tetanus vaccination 10 years ago. What is the best management for this patient?","o":["Human tetanus immunoglobulin and full course of vaccine","Human tetanus immunoglobulin only","Single-dose tetanus toxoid","Full course tetanus toxoid"],"a":2,"e":"Correct answer: C. Single-dose tetanus toxoid (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":131,"q":"A young male came to the hospital with a clean-cut wound without any bleeding. The patient received a full course of tetanus vaccination 10 years ago. What is the best management for this patient?","o":["Human tetanus immunoglobulin and full course of vaccine","Human tetanus immunoglobulin only","Single-dose tetanus toxoid","Full course tetanus toxoid"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9628, 'PSM', 'Environment and Health', 'Moderate', 'NEET PG 2023', 132, '{"id":9628,"subject":"PSM","chapter":"Environment and Health","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":132,"q":"How is water collected for bacteriological examination during a disease outbreak?","o":["Collect water from already leaking taps","Before collecting, let water flow for at least 1 minute","Water sample container is kept close to the tap avoid spillage","Collect from a gentle stream of water to avoid splashing"],"a":3,"e":"Correct answer: D. Collect from a gentle stream of water to avoid splashing (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":132,"q":"How is water collected for bacteriological examination during a disease outbreak?","o":["Collect water from already leaking taps","Before collecting, let water flow for at least 1 minute","Water sample container is kept close to the tap avoid spillage","Collect from a gentle stream of water to avoid splashing"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9629, 'PSM', 'Communicable and Non-communicable Diseases', 'Moderate', 'NEET PG 2023', 133, '{"id":9629,"subject":"PSM","chapter":"Communicable and Non-communicable Diseases","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":133,"q":"A boys'' hostel has an outbreak of fever cases with headache, followed by the development of pleomorphic rashes sparing palms and soles. What is the next best step in the management of suspected cases? VZIG-Varicella zoster immunoglobulin","o":["Isolate for 6 days after giving acyclovir, followed by VZIG within 72 hours of exposure.","Isolate for 12 days after giving acyclovir, followed by VZIG within 48 hours of exposure","Isolate for 6 days","Only give VZIG"],"a":2,"e":"Correct answer: C. Isolate for 6 days (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":133,"q":"A boys'' hostel has an outbreak of fever cases with headache, followed by the development of pleomorphic rashes sparing palms and soles. What is the next best step in the management of suspected cases? VZIG-Varicella zoster immunoglobulin","o":["Isolate for 6 days after giving acyclovir, followed by VZIG within 72 hours of exposure.","Isolate for 12 days after giving acyclovir, followed by VZIG within 48 hours of exposure","Isolate for 6 days","Only give VZIG"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9630, 'Medicine', 'Neurology', 'Moderate', 'NEET PG 2023', 134, '{"id":9630,"subject":"Medicine","chapter":"Neurology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":134,"q":"A patient who is a known case of hypertension on multiple anti-hypertensive medications came to OPD. His ECG finding is given below. Which of the following drugs is responsible for the ECG finding?","o":["Prazosin","Metoprolol","Hydrochlorothiazide","Spironolactone"],"a":3,"e":"Correct answer: D. Spironolactone (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":134,"q":"A patient who is a known case of hypertension on multiple anti-hypertensive medications came to OPD. His ECG finding is given below. Which of the following drugs is responsible for the ECG finding?","o":["Prazosin","Metoprolol","Hydrochlorothiazide","Spironolactone"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9631, 'Medicine', 'Neurology', 'Moderate', 'NEET PG 2023', 135, '{"id":9631,"subject":"Medicine","chapter":"Neurology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":135,"q":"A 78-year-old woman presents with a progressive decline in daily activity. She gives a history of convulsions and visual hallucinations. She does not talk to anyone and keeps looking at the sky. Pathological examination shows the presence of Lewy bodies within the neurons. What is the most probable diagnosis?","o":["Parkinson''s disease","Prion disease","Huntington''s chorea","Alzheimer''s disease"],"a":0,"e":"Correct answer: A. Parkinson''s disease (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":135,"q":"A 78-year-old woman presents with a progressive decline in daily activity. She gives a history of convulsions and visual hallucinations. She does not talk to anyone and keeps looking at the sky. Pathological examination shows the presence of Lewy bodies within the neurons. What is the most probable diagnosis?","o":["Parkinson''s disease","Prion disease","Huntington''s chorea","Alzheimer''s disease"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9632, 'Medicine', 'Neurology', 'Moderate', 'NEET PG 2023', 136, '{"id":9632,"subject":"Medicine","chapter":"Neurology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":136,"q":"A patient came to the medical OPD with complaints of polyuria. He has a history of undergoing total hypophysectomy. His Na+ levels are found to be 155 mEq/ L, urine osmolarity was 200 mOsm/L. What is the definitive management in this patient?","o":["DDAVP for 2 weeks and then discontinue","DDAVP supplementation for lifelong","Upsetting of receptors so no treatment is required","Thiazides for 2 weeks"],"a":1,"e":"Correct answer: B. DDAVP supplementation for lifelong (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":136,"q":"A patient came to the medical OPD with complaints of polyuria. He has a history of undergoing total hypophysectomy. His Na+ levels are found to be 155 mEq/ L, urine osmolarity was 200 mOsm/L. What is the definitive management in this patient?","o":["DDAVP for 2 weeks and then discontinue","DDAVP supplementation for lifelong","Upsetting of receptors so no treatment is required","Thiazides for 2 weeks"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9633, 'Medicine', 'Pulmonology', 'Moderate', 'NEET PG 2023', 137, '{"id":9633,"subject":"Medicine","chapter":"Pulmonology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":137,"q":"A 65-year-old chronic smoker came to the medicine outpatient department with complaints of upper chest discomfort and drooping of an eyelid. He also complained of pain radiating to the upper arm and a tingling sensation in the 4th and 5th digits of his left hand. The chest X-ray is given below. Which of the following is the most likely diagnosis?","o":["Pancoast tumour","Upper lobe pneumonia","Superior vena cava obstruction","Aspergilloma"],"a":0,"e":"Correct answer: A. Pancoast tumour (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":137,"q":"A 65-year-old chronic smoker came to the medicine outpatient department with complaints of upper chest discomfort and drooping of an eyelid. He also complained of pain radiating to the upper arm and a tingling sensation in the 4th and 5th digits of his left hand. The chest X-ray is given below. Which of the following is the most likely diagnosis?","o":["Pancoast tumour","Upper lobe pneumonia","Superior vena cava obstruction","Aspergilloma"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9634, 'Medicine', 'Rheumatology / Connective Tissue Disorder', 'Moderate', 'NEET PG 2023', 138, '{"id":9634,"subject":"Medicine","chapter":"Rheumatology / Connective Tissue Disorder","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":138,"q":"A chronic alcoholic patient presents with acute pain and swelling of the left great toe. There is no history of trauma. Synovial fluid analysis shows raised leukocytes. Lab investigations show normal serum uric acid levels. What is the most likely diagnosis?","o":["Pseudogout","Acute gout","Reactive arthritis","Septic arthritis"],"a":1,"e":"Correct answer: B. Acute gout (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":138,"q":"A chronic alcoholic patient presents with acute pain and swelling of the left great toe. There is no history of trauma. Synovial fluid analysis shows raised leukocytes. Lab investigations show normal serum uric acid levels. What is the most likely diagnosis?","o":["Pseudogout","Acute gout","Reactive arthritis","Septic arthritis"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9635, 'Psychiatry', 'Substance-Related and Addictive Disorders', 'Moderate', 'NEET PG 2023', 139, '{"id":9635,"subject":"Psychiatry","chapter":"Substance-Related and Addictive Disorders","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":139,"q":"A chronic alcoholic is brought to the emergency department with confusion, ataxia, and painful eye movements. The 6th cranial nerve is also involved. What is the likely diagnosis?","o":["Wernicke''s encephalopathy","Korsakoff psychosis","Delirium tremens","De Clerambault syndrome"],"a":0,"e":"Correct answer: A. Wernicke''s encephalopathy (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":139,"q":"A chronic alcoholic is brought to the emergency department with confusion, ataxia, and painful eye movements. The 6th cranial nerve is also involved. What is the likely diagnosis?","o":["Wernicke''s encephalopathy","Korsakoff psychosis","Delirium tremens","De Clerambault syndrome"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9636, 'Pharmacology', 'General Pharmacology', 'Moderate', 'NEET PG 2023', 140, '{"id":9636,"subject":"Pharmacology","chapter":"General Pharmacology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":140,"q":"A patient given digoxin started having side effects like nausea and vomiting. The serum concentration of digoxin was 4 mg/dL. The plasma therapeutic range is 1 mg/dL. If the half-life of digoxin is 40 hours, how long should one wait before resuming the treatment?","o":["40 hours","80 hours","120 hours","140-180 hours"],"a":1,"e":"Correct answer: B. 80 hours (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":140,"q":"A patient given digoxin started having side effects like nausea and vomiting. The serum concentration of digoxin was 4 mg/dL. The plasma therapeutic range is 1 mg/dL. If the half-life of digoxin is 40 hours, how long should one wait before resuming the treatment?","o":["40 hours","80 hours","120 hours","140-180 hours"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9637, 'Pharmacology', 'ANS Pharmacology', 'Moderate', 'NEET PG 2023', 141, '{"id":9637,"subject":"Pharmacology","chapter":"ANS Pharmacology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":141,"q":"A patient comes to the casualty with organophosphate poisoning. He was started on atropine infusion and pralidoxime. After 2 hours, the patient had a sudden rise in temperature. What is the likely cause of fever?","o":["Atropine toxicity","A side effect of pralidoxime","Due to organophosphate poisoning","Idiopathic"],"a":0,"e":"Correct answer: A. Atropine toxicity (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":141,"q":"A patient comes to the casualty with organophosphate poisoning. He was started on atropine infusion and pralidoxime. After 2 hours, the patient had a sudden rise in temperature. What is the likely cause of fever?","o":["Atropine toxicity","A side effect of pralidoxime","Due to organophosphate poisoning","Idiopathic"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9638, 'Gynaecology & Obstetrics', 'Obstetrics', 'Moderate', 'NEET PG 2023', 142, '{"id":9638,"subject":"Gynaecology & Obstetrics","chapter":"Obstetrics","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":142,"q":"A partogram of a woman who is in labor is shown below. Oxytocin infusion is already given. How will you manage the condition?","o":["Forceps-assisted delivery","Vacuum-assisted delivery","Oxytocin infusion","Cesarean section"],"a":3,"e":"Correct answer: D. Cesarean section (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":142,"q":"A partogram of a woman who is in labor is shown below. Oxytocin infusion is already given. How will you manage the condition?","o":["Forceps-assisted delivery","Vacuum-assisted delivery","Oxytocin infusion","Cesarean section"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9639, 'Pharmacology', 'CVS Pharmacology', 'Moderate', 'NEET PG 2023', 143, '{"id":9639,"subject":"Pharmacology","chapter":"CVS Pharmacology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":143,"q":"The mechanism of action of tissue plasminogen activator is","o":["Inhibit extrinsic pathway","Inhibits platelet aggregation","Enhance fibrin degradation","Inhibit clot formation"],"a":2,"e":"Correct answer: C. Enhance fibrin degradation (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":143,"q":"The mechanism of action of tissue plasminogen activator is","o":["Inhibit extrinsic pathway","Inhibits platelet aggregation","Enhance fibrin degradation","Inhibit clot formation"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9640, 'Gynaecology & Obstetrics', 'Obstetrics', 'Moderate', 'NEET PG 2023', 144, '{"id":9640,"subject":"Gynaecology & Obstetrics","chapter":"Obstetrics","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":144,"q":"A woman presents to you at 36 weeks of gestation with complaints of breathlessness and excessive abdominal distension. Fetal movements are normal. On examination, fetal parts are not easily felt and fetal heartbeat is heard but it is muffled. Her symphysis fundal height is 41 cm. Her abdomen is tense but not tender. What is the most likely diagnosis?","o":["Abruptio placenta","Hydrocephalus of fetus","Polyhydramnios","Fetal-maternal ascites"],"a":2,"e":"Correct answer: C. Polyhydramnios (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":144,"q":"A woman presents to you at 36 weeks of gestation with complaints of breathlessness and excessive abdominal distension. Fetal movements are normal. On examination, fetal parts are not easily felt and fetal heartbeat is heard but it is muffled. Her symphysis fundal height is 41 cm. Her abdomen is tense but not tender. What is the most likely diagnosis?","o":["Abruptio placenta","Hydrocephalus of fetus","Polyhydramnios","Fetal-maternal ascites"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9641, 'Gynaecology & Obstetrics', 'Gynecology', 'Moderate', 'NEET PG 2023', 145, '{"id":9641,"subject":"Gynaecology & Obstetrics","chapter":"Gynecology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":145,"q":"For which of the following procedures in the given OT list, can you preferably do a hysteroscopy?","o":["Tubal ligation","Asherman syndrome","Endocervical polyp","Subserosal fibroid"],"a":1,"e":"Correct answer: B. Asherman syndrome (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":145,"q":"For which of the following procedures in the given OT list, can you preferably do a hysteroscopy?","o":["Tubal ligation","Asherman syndrome","Endocervical polyp","Subserosal fibroid"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9642, 'Gynaecology & Obstetrics', 'Obstetrics', 'Moderate', 'NEET PG 2023', 146, '{"id":9642,"subject":"Gynaecology & Obstetrics","chapter":"Obstetrics","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":146,"q":"A primigravida presents to you with anemia early in her pregnancy. She is 7 weeks pregnant as seen on ultrasound. Her hemoglobin level is 9 g/dL. When should the iron supplements be started for her?","o":["10 to 12 weeks","8 to 10 weeks","After 14 weeks","After 20 weeks"],"a":1,"e":"Correct answer: B. 8 to 10 weeks (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":146,"q":"A primigravida presents to you with anemia early in her pregnancy. She is 7 weeks pregnant as seen on ultrasound. Her hemoglobin level is 9 g/dL. When should the iron supplements be started for her?","o":["10 to 12 weeks","8 to 10 weeks","After 14 weeks","After 20 weeks"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9643, 'Gynaecology & Obstetrics', 'Gynecology', 'Moderate', 'NEET PG 2023', 147, '{"id":9643,"subject":"Gynaecology & Obstetrics","chapter":"Gynecology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":147,"q":"A 23-year-old woman accompanied by her mother-in-law comes to the infertility clinic. She has been having regular intercourse for 6 months but is not able to conceive. What is the next best step?","o":["Semen analysis for husband","Reassure and review the couple after 6 months","Hysterolaparoscopy","Diagnostic hysteroscopy"],"a":1,"e":"Correct answer: B. Reassure and review the couple after 6 months (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":147,"q":"A 23-year-old woman accompanied by her mother-in-law comes to the infertility clinic. She has been having regular intercourse for 6 months but is not able to conceive. What is the next best step?","o":["Semen analysis for husband","Reassure and review the couple after 6 months","Hysterolaparoscopy","Diagnostic hysteroscopy"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9644, 'Anaesthesia', 'Cardiopulmonary Cerebral Resuscitation', 'Moderate', 'NEET PG 2023', 148, '{"id":9644,"subject":"Anaesthesia","chapter":"Cardiopulmonary Cerebral Resuscitation","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":148,"q":"During resuscitation, when is the given position indicated?","o":["Unconsciousness with pulse and breathing absent","Unconsciousness with pulse present and breathing absent","Unconsciousness with pulse and breathing present","Unconsciousness with pulse absent and breathing present"],"a":2,"e":"Correct answer: C. Unconsciousness with pulse and breathing present (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":148,"q":"During resuscitation, when is the given position indicated?","o":["Unconsciousness with pulse and breathing absent","Unconsciousness with pulse present and breathing absent","Unconsciousness with pulse and breathing present","Unconsciousness with pulse absent and breathing present"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9645, 'Gynaecology & Obstetrics', 'Gynecology', 'Moderate', 'NEET PG 2023', 149, '{"id":9645,"subject":"Gynaecology & Obstetrics","chapter":"Gynecology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":149,"q":"A 50-year-old woman presents with foul-smelling bloody discharge per vagina mixed with mucous. On examination, a necrotizing growth is seen in the cervix with lateral parametrium involvement. What is the management for this patient?","o":["Chemotherapy","Brachytherapy","Chemoradiation","Surgery"],"a":2,"e":"Correct answer: C. Chemoradiation (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":149,"q":"A 50-year-old woman presents with foul-smelling bloody discharge per vagina mixed with mucous. On examination, a necrotizing growth is seen in the cervix with lateral parametrium involvement. What is the management for this patient?","o":["Chemotherapy","Brachytherapy","Chemoradiation","Surgery"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9646, 'Gynaecology & Obstetrics', 'Gynecology', 'Moderate', 'NEET PG 2023', 150, '{"id":9646,"subject":"Gynaecology & Obstetrics","chapter":"Gynecology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":150,"q":"A 28-year-old woman with a history of multiple sexual partners presents with lower abdominal pain for 1 month. She experiences minimal discharge and complaints of intermenstrual bleeding. What is the most likely cause?","o":["Herpes simplex","Genital tuberculosis","Candida","Neisseria gonorrhoea"],"a":1,"e":"Correct answer: B. Genital tuberculosis (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":150,"q":"A 28-year-old woman with a history of multiple sexual partners presents with lower abdominal pain for 1 month. She experiences minimal discharge and complaints of intermenstrual bleeding. What is the most likely cause?","o":["Herpes simplex","Genital tuberculosis","Candida","Neisseria gonorrhoea"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9647, 'Gynaecology & Obstetrics', 'Gynecology', 'Moderate', 'NEET PG 2023', 151, '{"id":9647,"subject":"Gynaecology & Obstetrics","chapter":"Gynecology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":151,"q":"A woman is set to undergo a complete laparoscopic hysterectomy. She wants to know if there are any disadvantages to this procedure. What are the disadvantages of laproscopis over-open surgery?","o":["Prolonged recovery time","Not knowing the extent of thermal burns","Increased bleeding","Increased pain"],"a":1,"e":"Correct answer: B. Not knowing the extent of thermal burns (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":151,"q":"A woman is set to undergo a complete laparoscopic hysterectomy. She wants to know if there are any disadvantages to this procedure. What are the disadvantages of laproscopis over-open surgery?","o":["Prolonged recovery time","Not knowing the extent of thermal burns","Increased bleeding","Increased pain"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9648, 'Gynaecology & Obstetrics', 'Obstetrics', 'Moderate', 'NEET PG 2023', 152, '{"id":9648,"subject":"Gynaecology & Obstetrics","chapter":"Obstetrics","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":152,"q":"A 27-year-old pregnant G3P2L2 woman presents to you at 36+6 weeks. Ultrasound is done and shows the fetus is in a transverse lie. The liquor is adequate, the placenta is normal, and she has no risk factors. Both her previous deliveries were normal vaginal deliveries. How will you manage this patient?","o":["Cesarean section","External cephalic version","Expectant management","Induction of labor"],"a":1,"e":"Correct answer: B. External cephalic version (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":152,"q":"A 27-year-old pregnant G3P2L2 woman presents to you at 36+6 weeks. Ultrasound is done and shows the fetus is in a transverse lie. The liquor is adequate, the placenta is normal, and she has no risk factors. Both her previous deliveries were normal vaginal deliveries. How will you manage this patient?","o":["Cesarean section","External cephalic version","Expectant management","Induction of labor"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9649, 'Gynaecology & Obstetrics', 'Gynecology', 'Moderate', 'NEET PG 2023', 153, '{"id":9649,"subject":"Gynaecology & Obstetrics","chapter":"Gynecology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":153,"q":"A female presents to you with 6 weeks of amenorrhea complaining of bleeding per vagina and slight abdominal pain. The urine pregnancy test is positive and hCG level is 2800 IU/L. A mass is seen on the left adnexa measuring 3 x 2.5 cm. She is hemodynamically stable. How will you manage this patient? hCG-Human chorionic gonadotropin","o":["Oral methotrexate","Single-dose methotrexate injection","Serial methotrexate + leucovorin rescue","Salpingectomy"],"a":1,"e":"Correct answer: B. Single-dose methotrexate injection (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":153,"q":"A female presents to you with 6 weeks of amenorrhea complaining of bleeding per vagina and slight abdominal pain. The urine pregnancy test is positive and hCG level is 2800 IU/L. A mass is seen on the left adnexa measuring 3 x 2.5 cm. She is hemodynamically stable. How will you manage this patient? hCG-Human chorionic gonadotropin","o":["Oral methotrexate","Single-dose methotrexate injection","Serial methotrexate + leucovorin rescue","Salpingectomy"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9650, 'Gynaecology & Obstetrics', 'Gynecology', 'Moderate', 'NEET PG 2023', 154, '{"id":9650,"subject":"Gynaecology & Obstetrics","chapter":"Gynecology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":154,"q":"A 24-year-old woman who is being treated for infertility with human menopausal gonadotropin came with complaints of sudden abdominal pain, nausea, vomiting, and breathlessness. The finding of the ultrasound is shown below. What is the most likely diagnosis?","o":["Ovarian hyperstimulation syndrome","Polycystic ovarian syndrome","Theca lutein cysts","Granulosa cell tumor"],"a":0,"e":"Correct answer: A. Ovarian hyperstimulation syndrome (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":154,"q":"A 24-year-old woman who is being treated for infertility with human menopausal gonadotropin came with complaints of sudden abdominal pain, nausea, vomiting, and breathlessness. The finding of the ultrasound is shown below. What is the most likely diagnosis?","o":["Ovarian hyperstimulation syndrome","Polycystic ovarian syndrome","Theca lutein cysts","Granulosa cell tumor"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9651, 'Gynaecology & Obstetrics', 'Gynecology', 'Moderate', 'NEET PG 2023', 155, '{"id":9651,"subject":"Gynaecology & Obstetrics","chapter":"Gynecology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":155,"q":"During a hysteroscopic removal of a submucosal fibroid, a fluid deficit of 2000 mL is estimated in a patient. What is the immediate complication of this?","o":["Acute tubular necrosis","DIC","Pulmonary edema","Thromboembolism"],"a":2,"e":"Correct answer: C. Pulmonary edema (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":155,"q":"During a hysteroscopic removal of a submucosal fibroid, a fluid deficit of 2000 mL is estimated in a patient. What is the immediate complication of this?","o":["Acute tubular necrosis","DIC","Pulmonary edema","Thromboembolism"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9652, 'Gynaecology & Obstetrics', 'Gynecology', 'Moderate', 'NEET PG 2023', 156, '{"id":9652,"subject":"Gynaecology & Obstetrics","chapter":"Gynecology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":156,"q":"A woman comes with complaints of pain and swelling in the perineal area. She also has complaints of difficulty in walking and sitting. She gives a history of multiple sexual partners. On examination, a tender swelling is seen with redness on the labia, as shown in the image given below. What is the most likely diagnosis?","o":["Chlamydial infection","Bartholin abscess","Genital Tuberculosis","Herpes infection"],"a":1,"e":"Correct answer: B. Bartholin abscess (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":156,"q":"A woman comes with complaints of pain and swelling in the perineal area. She also has complaints of difficulty in walking and sitting. She gives a history of multiple sexual partners. On examination, a tender swelling is seen with redness on the labia, as shown in the image given below. What is the most likely diagnosis?","o":["Chlamydial infection","Bartholin abscess","Genital Tuberculosis","Herpes infection"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9653, 'Gynaecology & Obstetrics', 'Gynecology', 'Moderate', 'NEET PG 2023', 157, '{"id":9653,"subject":"Gynaecology & Obstetrics","chapter":"Gynecology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":157,"q":"A 54-year-old woman was diagnosed with advanced cervical cancer. She has a 14-year-old daughter. What advice would you give her daughter?","o":["Advise HPV vaccine","Screen for BRCA mutation","Screen for PTEN mutation","Perform cervical biopsy"],"a":0,"e":"Correct answer: A. Advise HPV vaccine (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":157,"q":"A 54-year-old woman was diagnosed with advanced cervical cancer. She has a 14-year-old daughter. What advice would you give her daughter?","o":["Advise HPV vaccine","Screen for BRCA mutation","Screen for PTEN mutation","Perform cervical biopsy"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9654, 'Gynaecology & Obstetrics', 'Gynecology', 'Moderate', 'NEET PG 2023', 158, '{"id":9654,"subject":"Gynaecology & Obstetrics","chapter":"Gynecology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":158,"q":"A 17-year-old girl is seen for primary amenorrhea. There is no development of breasts or hair in the pubic or axillary region. Her height is 155 cm, and her weight is 48 kg. She has bilateral inguinal masses. The uterus, fallopian tube, and Ovary are absent on ultrasound examination. What is the most likely diagnosis?","o":["Complete androgen insensitivity syndrome","Hypergonadotropic hypogonadism","Turner syndrome","Polycystic ovary syndrome"],"a":1,"e":"Correct answer: B. Hypergonadotropic hypogonadism (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":158,"q":"A 17-year-old girl is seen for primary amenorrhea. There is no development of breasts or hair in the pubic or axillary region. Her height is 155 cm, and her weight is 48 kg. She has bilateral inguinal masses. The uterus, fallopian tube, and Ovary are absent on ultrasound examination. What is the most likely diagnosis?","o":["Complete androgen insensitivity syndrome","Hypergonadotropic hypogonadism","Turner syndrome","Polycystic ovary syndrome"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9655, 'Surgery', 'Oncology', 'Moderate', 'NEET PG 2023', 159, '{"id":9655,"subject":"Surgery","chapter":"Oncology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":159,"q":"A 54-year-old woman presents with cervical cancer stage 2A. It is decided to give neoadjuvant chemotherapy. What does neoadjuvant chemotherapy mean?","o":["Chemotherapy is given along with radiation.","Chemotherapy is given during surgery.","Chemotherapy is given before radical surgery to reduce the bulk of the tumor","Chemotherapy is given after radical surgery for micrometastases"],"a":2,"e":"Correct answer: C. Chemotherapy is given before radical surgery to reduce the bulk of the tumor (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":159,"q":"A 54-year-old woman presents with cervical cancer stage 2A. It is decided to give neoadjuvant chemotherapy. What does neoadjuvant chemotherapy mean?","o":["Chemotherapy is given along with radiation.","Chemotherapy is given during surgery.","Chemotherapy is given before radical surgery to reduce the bulk of the tumor","Chemotherapy is given after radical surgery for micrometastases"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9656, 'Gynaecology & Obstetrics', 'Gynecology', 'Moderate', 'NEET PG 2023', 160, '{"id":9656,"subject":"Gynaecology & Obstetrics","chapter":"Gynecology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":160,"q":"A 16-year-old girl presents with cyclical pelvic pain every month. She has not achieved menarche yet. On examination, a suprapubic bulge can be seen in the lower abdomen. PR examination reveals a bulging swelling in the anterior aspect. What is the most likely diagnosis?","o":["Transverse vaginal septum above the vagina","Vaginal atresia","Imperforate hymen","Cervical agenesis"],"a":2,"e":"Correct answer: C. Imperforate hymen (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":160,"q":"A 16-year-old girl presents with cyclical pelvic pain every month. She has not achieved menarche yet. On examination, a suprapubic bulge can be seen in the lower abdomen. PR examination reveals a bulging swelling in the anterior aspect. What is the most likely diagnosis?","o":["Transverse vaginal septum above the vagina","Vaginal atresia","Imperforate hymen","Cervical agenesis"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9657, 'Gynaecology & Obstetrics', 'Obstetrics', 'Moderate', 'NEET PG 2023', 161, '{"id":9657,"subject":"Gynaecology & Obstetrics","chapter":"Obstetrics","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":161,"q":"A pregnant woman comes to the clinic. She already has twins by normal delivery. Which of the following is the correct representation of her obstetric score?","o":["G3P2","G3P1","G2P1","G2P2"],"a":2,"e":"Correct answer: C. G2P1 (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":161,"q":"A pregnant woman comes to the clinic. She already has twins by normal delivery. Which of the following is the correct representation of her obstetric score?","o":["G3P2","G3P1","G2P1","G2P2"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9658, 'Surgery', 'Gastrointestinal Surgery', 'Moderate', 'NEET PG 2023', 162, '{"id":9658,"subject":"Surgery","chapter":"Gastrointestinal Surgery","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":162,"q":"A patient presents with sudden onset of hematemesis. He has been taking aspirin for his arthritis and drinks alcohol occasionally. He gives a history of occasional abdominal pain. On examination, there is no abdominal mass or tenderness. What is the likely diagnosis?","o":["Mallory-Weiss tear","Esophagitis","Peptic ulcer","Esophageal varices"],"a":2,"e":"Correct answer: C. Peptic ulcer (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":162,"q":"A patient presents with sudden onset of hematemesis. He has been taking aspirin for his arthritis and drinks alcohol occasionally. He gives a history of occasional abdominal pain. On examination, there is no abdominal mass or tenderness. What is the likely diagnosis?","o":["Mallory-Weiss tear","Esophagitis","Peptic ulcer","Esophageal varices"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9659, 'Gynaecology & Obstetrics', 'Obstetrics', 'Moderate', 'NEET PG 2023', 163, '{"id":9659,"subject":"Gynaecology & Obstetrics","chapter":"Obstetrics","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":163,"q":"A woman presents to you at 36 weeks of gestation with complaints of feeling lightheadedness and dizziness when she lies on her back. She says she feels alright if she lies on her side or when walks. What is the most likely reason behind this? IVC- inferior vena cava","o":["Increased intracranial pressure","IVC compression","Heavy meals","Excessive venous pooling at the feet"],"a":1,"e":"Correct answer: B. IVC compression (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":163,"q":"A woman presents to you at 36 weeks of gestation with complaints of feeling lightheadedness and dizziness when she lies on her back. She says she feels alright if she lies on her side or when walks. What is the most likely reason behind this? IVC- inferior vena cava","o":["Increased intracranial pressure","IVC compression","Heavy meals","Excessive venous pooling at the feet"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9660, 'Surgery', 'Oncology', 'Moderate', 'NEET PG 2023', 164, '{"id":9660,"subject":"Surgery","chapter":"Oncology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":164,"q":"A 40-year-old male patient presents with a swelling that has been slowly growing in the past 2 years. On examination, it was variable in consistency and fully mobile. What is the most likely diagnosis?","o":["Dermoid cyst","Parotid tumor","Sebaceous cyst","Cervical lymph node"],"a":1,"e":"Correct answer: B. Parotid tumor (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":164,"q":"A 40-year-old male patient presents with a swelling that has been slowly growing in the past 2 years. On examination, it was variable in consistency and fully mobile. What is the most likely diagnosis?","o":["Dermoid cyst","Parotid tumor","Sebaceous cyst","Cervical lymph node"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9661, 'Radiology', 'Radiotherapy', 'Moderate', 'NEET PG 2023', 165, '{"id":9661,"subject":"Radiology","chapter":"Radiotherapy","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":165,"q":"A woman with endometrial carcinoma is undergoing radiotherapy. Which of the following is true?","o":["Intensity is inversely proportional to the square of the distance from the source","Small blood vessels are most radioresistant","Rapidly proliferating cells are most radioresistant","Small intestinal mucosa is most radio-resistant"],"a":0,"e":"Correct answer: A. Intensity is inversely proportional to the square of the distance from the source (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":165,"q":"A woman with endometrial carcinoma is undergoing radiotherapy. Which of the following is true?","o":["Intensity is inversely proportional to the square of the distance from the source","Small blood vessels are most radioresistant","Rapidly proliferating cells are most radioresistant","Small intestinal mucosa is most radio-resistant"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9662, 'Forensic Medicine', 'Forensic Toxicology', 'Moderate', 'NEET PG 2023', 166, '{"id":9662,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":166,"q":"A child before playing consumed fruit from the garden. After some time he developed a high fever, confusion, photophobia, and unable to urinate. What are the likely causative agent and the appropriate antidote used in this case?","o":["Datura, Pralidoxime","Datura, Physostigmine","Yellow oleander, Pralidoxime","Yellow oleander, Physostigmine"],"a":1,"e":"Correct answer: B. Datura, Physostigmine (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":166,"q":"A child before playing consumed fruit from the garden. After some time he developed a high fever, confusion, photophobia, and unable to urinate. What are the likely causative agent and the appropriate antidote used in this case?","o":["Datura, Pralidoxime","Datura, Physostigmine","Yellow oleander, Pralidoxime","Yellow oleander, Physostigmine"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9663, 'Radiology', 'Thoracic Radiology', 'Moderate', 'NEET PG 2023', 167, '{"id":9663,"subject":"Radiology","chapter":"Thoracic Radiology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":167,"q":"A patient presents with a history of fever and cough for the past 3-5 days. His examination findings reveal crepitations. Chest X-ray is given below. What is the probable diagnosis?","o":["Apical segment of Right lower lobe consolidation","Right middle lobe consolidation","Posterior segment of right lower lobe consolidation","Loculated pleural effusion"],"a":1,"e":"Correct answer: B. Right middle lobe consolidation (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":167,"q":"A patient presents with a history of fever and cough for the past 3-5 days. His examination findings reveal crepitations. Chest X-ray is given below. What is the probable diagnosis?","o":["Apical segment of Right lower lobe consolidation","Right middle lobe consolidation","Posterior segment of right lower lobe consolidation","Loculated pleural effusion"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9664, 'Anatomy', 'Lower Limb', 'Moderate', 'NEET PG 2023', 168, '{"id":9664,"subject":"Anatomy","chapter":"Lower Limb","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":168,"q":"Injury at which of the following marked sites causes failure of dorsiflexion?","o":["3","2","1","4"],"a":0,"e":"Correct answer: A. 3 (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":168,"q":"Injury at which of the following marked sites causes failure of dorsiflexion?","o":["3","2","1","4"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9665, 'Anatomy', 'Head and Neck', 'Moderate', 'NEET PG 2023', 169, '{"id":9665,"subject":"Anatomy","chapter":"Head and Neck","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":169,"q":"A patient presents with swelling under the left ear lobule and complains of pain. Which of the following structures is the likely cause of the pain?","o":["Facial nerve","Greater auricular nerve","Auriculotemporal nerve","Investing layer of deep cervical fascia"],"a":1,"e":"Correct answer: B. Greater auricular nerve (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":169,"q":"A patient presents with swelling under the left ear lobule and complains of pain. Which of the following structures is the likely cause of the pain?","o":["Facial nerve","Greater auricular nerve","Auriculotemporal nerve","Investing layer of deep cervical fascia"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9666, 'Biochemistry', 'Lipid Metabolism', 'Moderate', 'NEET PG 2023', 170, '{"id":9666,"subject":"Biochemistry","chapter":"Lipid Metabolism","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":170,"q":"A child presents with bone pain and hepatosplenomegaly. A trephine biopsy and aspirate show the following finding. Which of the following is the most likely enzyme deficient in this condition?","o":["Hexosaminidase","Glucocerebrosidase","Sphingomyelinase","Alpha 1,4-glucosidase"],"a":1,"e":"Correct answer: B. Glucocerebrosidase (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":170,"q":"A child presents with bone pain and hepatosplenomegaly. A trephine biopsy and aspirate show the following finding. Which of the following is the most likely enzyme deficient in this condition?","o":["Hexosaminidase","Glucocerebrosidase","Sphingomyelinase","Alpha 1,4-glucosidase"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9667, 'Forensic Medicine', 'Forensic Thanatology', 'Moderate', 'NEET PG 2023', 171, '{"id":9667,"subject":"Forensic Medicine","chapter":"Forensic Thanatology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":171,"q":"The method of autopsy carried out en masse to remove from tongue to prostate is.","o":["Virchow technique","Rokitansky technique","Ghon technique","Letulle technique"],"a":3,"e":"Correct answer: D. Letulle technique (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":171,"q":"The method of autopsy carried out en masse to remove from tongue to prostate is.","o":["Virchow technique","Rokitansky technique","Ghon technique","Letulle technique"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9668, 'Forensic Medicine', 'Forensic Thanatology', 'Moderate', 'NEET PG 2023', 172, '{"id":9668,"subject":"Forensic Medicine","chapter":"Forensic Thanatology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":172,"q":"A 42-year-old HIV-positive patient died, and his body was brought for post-mortem. The method of autopsy to be done is___","o":["Ghon technique","Letulle technique","Virchow technique","Rokitansky technique"],"a":3,"e":"Correct answer: D. Rokitansky technique (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":172,"q":"A 42-year-old HIV-positive patient died, and his body was brought for post-mortem. The method of autopsy to be done is___","o":["Ghon technique","Letulle technique","Virchow technique","Rokitansky technique"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9669, 'Microbiology', 'Virology', 'Moderate', 'NEET PG 2023', 173, '{"id":9669,"subject":"Microbiology","chapter":"Virology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":173,"q":"A patient presented with a high fever, altered sensorium, headache, neck rigidity, and seizures. He was diagnosed with HSV encephalitis. Which of the following tests can be used to confirm the diagnosis?","o":["IgM in CSF","Tzanck smear of CSF","CSF PCR for viral DNA","CSF culture on chick embryo lines"],"a":2,"e":"Correct answer: C. CSF PCR for viral DNA (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":173,"q":"A patient presented with a high fever, altered sensorium, headache, neck rigidity, and seizures. He was diagnosed with HSV encephalitis. Which of the following tests can be used to confirm the diagnosis?","o":["IgM in CSF","Tzanck smear of CSF","CSF PCR for viral DNA","CSF culture on chick embryo lines"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9670, 'Microbiology', 'Parasitology', 'Moderate', 'NEET PG 2023', 174, '{"id":9670,"subject":"Microbiology","chapter":"Parasitology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":174,"q":"In a patient presented with a fever and a positive filarial antigen test, what is the next appropriate method of management?","o":["Bone marrow biopsy","DEC provocation test","Detection of microfilariae in the blood smear","Ultrasound of the scrotum"],"a":2,"e":"Correct answer: C. Detection of microfilariae in the blood smear (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":174,"q":"In a patient presented with a fever and a positive filarial antigen test, what is the next appropriate method of management?","o":["Bone marrow biopsy","DEC provocation test","Detection of microfilariae in the blood smear","Ultrasound of the scrotum"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9671, 'Forensic Medicine', 'Sexual Jurisprudence', 'Moderate', 'NEET PG 2023', 175, '{"id":9671,"subject":"Forensic Medicine","chapter":"Sexual Jurisprudence","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":175,"q":"A 10-year-old male child came to the casualty with difficulty in walking and pain in the perianal region. On subjecting the specimen from the perianal region to a test, it produces yellow needle-shaped rhombic crystals with picric acid. What is the test done?","o":["Barberio test","Florence test","Teichmann test","Acid phosphatase test"],"a":0,"e":"Correct answer: A. Barberio test (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":175,"q":"A 10-year-old male child came to the casualty with difficulty in walking and pain in the perianal region. On subjecting the specimen from the perianal region to a test, it produces yellow needle-shaped rhombic crystals with picric acid. What is the test done?","o":["Barberio test","Florence test","Teichmann test","Acid phosphatase test"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9672, 'Ophthalmology', 'Optics', 'Moderate', 'NEET PG 2023', 176, '{"id":9672,"subject":"Ophthalmology","chapter":"Optics","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":176,"q":"Which of the following refractive errors is associated with the image given below?","o":["Presbyopia","Astigmatism","Hypermetropia","Myopia"],"a":1,"e":"Correct answer: B. Astigmatism (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":176,"q":"Which of the following refractive errors is associated with the image given below?","o":["Presbyopia","Astigmatism","Hypermetropia","Myopia"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9673, 'Pathology', 'Genetics', 'Moderate', 'NEET PG 2023', 177, '{"id":9673,"subject":"Pathology","chapter":"Genetics","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":177,"q":"Which of the following is true regarding the Mendelian mode of inheritance?","o":["Every 10th patient has a Y-linked disorder","1/3rd of Mendelian disorders is autosomal recessive","Every 5th patient has an X-linked recessive disorder","2/3 rd of Mendelian disorders are autosomal dominant"],"a":3,"e":"Correct answer: D. 2/3 rd of Mendelian disorders are autosomal dominant (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":177,"q":"Which of the following is true regarding the Mendelian mode of inheritance?","o":["Every 10th patient has a Y-linked disorder","1/3rd of Mendelian disorders is autosomal recessive","Every 5th patient has an X-linked recessive disorder","2/3 rd of Mendelian disorders are autosomal dominant"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9674, 'Forensic Medicine', 'Forensic Toxicology', 'Moderate', 'NEET PG 2023', 178, '{"id":9674,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":178,"q":"A patient was brought to casualty with seizures. He had multiple episodes and was taking herbal medicines for the same. He was conscious in between the episodes. During the episodes, he had arching of his back. What is the likely cause?","o":["Strychnine","Ricinus","Nerium odorum","Datura"],"a":0,"e":"Correct answer: A. Strychnine (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":178,"q":"A patient was brought to casualty with seizures. He had multiple episodes and was taking herbal medicines for the same. He was conscious in between the episodes. During the episodes, he had arching of his back. What is the likely cause?","o":["Strychnine","Ricinus","Nerium odorum","Datura"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9675, 'Ophthalmology', 'Glaucoma', 'Moderate', 'NEET PG 2023', 179, '{"id":9675,"subject":"Ophthalmology","chapter":"Glaucoma","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":179,"q":"An infant is brought with complaints of excessive watering of the eyes and photophobia. The image is given below. What is the likely diagnosis?","o":["Congenital glaucoma","Congenital cataract","Mucopolysaccharidosis","Ophthalmia neonatorum"],"a":0,"e":"Correct answer: A. Congenital glaucoma (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":179,"q":"An infant is brought with complaints of excessive watering of the eyes and photophobia. The image is given below. What is the likely diagnosis?","o":["Congenital glaucoma","Congenital cataract","Mucopolysaccharidosis","Ophthalmia neonatorum"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9676, 'Ophthalmology', 'Optics', 'Moderate', 'NEET PG 2023', 180, '{"id":9676,"subject":"Ophthalmology","chapter":"Optics","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":180,"q":"A 60-year-old patient complains of decreased distant vision but now he does not use spectacles for near vision. The image of his ocular examination is given below. What is this type of refractive error called?","o":["Index myopia","Axial myopia","Curvatural myopia","Positional myopia"],"a":0,"e":"Correct answer: A. Index myopia (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":180,"q":"A 60-year-old patient complains of decreased distant vision but now he does not use spectacles for near vision. The image of his ocular examination is given below. What is this type of refractive error called?","o":["Index myopia","Axial myopia","Curvatural myopia","Positional myopia"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9677, 'Pediatrics', 'Pediatric Respiratory Disorders', 'Moderate', 'NEET PG 2023', 181, '{"id":9677,"subject":"Pediatrics","chapter":"Pediatric Respiratory Disorders","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":181,"q":"A child is brought to the hospital with respiratory distress and biphasic stridor. The radiograph is shown below. What is the diagnosis?","o":["Acute epiglottitis","Acute laryngotracheobronchitis","Foreign body aspiration","Laryngomalacia"],"a":1,"e":"Correct answer: B. Acute laryngotracheobronchitis (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":181,"q":"A child is brought to the hospital with respiratory distress and biphasic stridor. The radiograph is shown below. What is the diagnosis?","o":["Acute epiglottitis","Acute laryngotracheobronchitis","Foreign body aspiration","Laryngomalacia"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9678, 'Pathology', 'Hematology: Red Blood Cells', 'Moderate', 'NEET PG 2023', 182, '{"id":9678,"subject":"Pathology","chapter":"Hematology: Red Blood Cells","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":182,"q":"A child presents with intermittent jaundice and splenomegaly. There is a history of similar complaints in the elder brother. Peripheral smear shows the following finding. How will you investigate this condition?","o":["Osmotic fragility test - Hereditary spherocytosis","Coombs test - AIHA","G6PD deficiency - Genetic testing","Paroxysmal nocturnal hemoglobinuria - Flow cytometry"],"a":0,"e":"Correct answer: A. Osmotic fragility test - Hereditary spherocytosis (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":182,"q":"A child presents with intermittent jaundice and splenomegaly. There is a history of similar complaints in the elder brother. Peripheral smear shows the following finding. How will you investigate this condition?","o":["Osmotic fragility test - Hereditary spherocytosis","Coombs test - AIHA","G6PD deficiency - Genetic testing","Paroxysmal nocturnal hemoglobinuria - Flow cytometry"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9679, 'Pediatrics', 'Pediatric Gastroenterology', 'Moderate', 'NEET PG 2023', 183, '{"id":9679,"subject":"Pediatrics","chapter":"Pediatric Gastroenterology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":183,"q":"A 3-month-old baby presents with jaundice and clay-coloured stools. Lab investigation reveals that the baby has conjugated hyperbilirubinemia. The liver biopsy shows periductal proliferation. What is the most likely diagnosis?","o":["Crigler-Najjar syndrome","Rotor syndrome","Dubin-Johnson syndrome","Biliary atresia"],"a":3,"e":"Correct answer: D. Biliary atresia (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":183,"q":"A 3-month-old baby presents with jaundice and clay-coloured stools. Lab investigation reveals that the baby has conjugated hyperbilirubinemia. The liver biopsy shows periductal proliferation. What is the most likely diagnosis?","o":["Crigler-Najjar syndrome","Rotor syndrome","Dubin-Johnson syndrome","Biliary atresia"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9680, 'Forensic Medicine', 'Sexual Jurisprudence', 'Moderate', 'NEET PG 2023', 184, '{"id":9680,"subject":"Forensic Medicine","chapter":"Sexual Jurisprudence","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":184,"q":"Section 314 IPC deals with","o":["Causing miscarriage with the consent of the mother","Causing miscarriage without the consent of the mother","Death of the mother by act done with intent to cause miscarriage","Causing the death of the quick unborn child by an act amounting to culpable homicide"],"a":2,"e":"Correct answer: C. Death of the mother by act done with intent to cause miscarriage (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":184,"q":"Section 314 IPC deals with","o":["Causing miscarriage with the consent of the mother","Causing miscarriage without the consent of the mother","Death of the mother by act done with intent to cause miscarriage","Causing the death of the quick unborn child by an act amounting to culpable homicide"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9681, 'Pathology', 'Hematology: White Blood Cells', 'Moderate', 'NEET PG 2023', 185, '{"id":9681,"subject":"Pathology","chapter":"Hematology: White Blood Cells","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":185,"q":"An African child is found to have a mass in the jaw. A biopsy of the mass was done, and it appears as shown in the image below. The child also had a translocation of t(8;14). What is the probable diagnosis?","o":["Acute myeloid leukemia","Follicular lymphoma","Multiple myeloma","Burkitt lymphoma"],"a":3,"e":"Correct answer: D. Burkitt lymphoma (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":185,"q":"An African child is found to have a mass in the jaw. A biopsy of the mass was done, and it appears as shown in the image below. The child also had a translocation of t(8;14). What is the probable diagnosis?","o":["Acute myeloid leukemia","Follicular lymphoma","Multiple myeloma","Burkitt lymphoma"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9682, 'Pediatrics', 'Infectious Diseases', 'Moderate', 'NEET PG 2023', 186, '{"id":9682,"subject":"Pediatrics","chapter":"Infectious Diseases","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":186,"q":"An infant presents with hepatosplenomegaly and thrombocytopenia. Neuroimaging with CT shows periventricular calcifications. What is the most likely diagnosis?","o":["Congenital rubella syndrome","Congenital herpes simplex virus infection","Congenital toxoplasmosis","Congenital cytomegalovirus infection"],"a":3,"e":"Correct answer: D. Congenital cytomegalovirus infection (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":186,"q":"An infant presents with hepatosplenomegaly and thrombocytopenia. Neuroimaging with CT shows periventricular calcifications. What is the most likely diagnosis?","o":["Congenital rubella syndrome","Congenital herpes simplex virus infection","Congenital toxoplasmosis","Congenital cytomegalovirus infection"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9683, 'Forensic Medicine', 'Forensic Thanatology', 'Moderate', 'NEET PG 2023', 187, '{"id":9683,"subject":"Forensic Medicine","chapter":"Forensic Thanatology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":187,"q":"The temperature of a body of a deceased person is found to be 39 degrees Celsius. Which of the following is the most probable reason?","o":["Cyanide poisoning","Septicemia","Corrosive poisoning","Intra-abdominal hemorrhage"],"a":1,"e":"Correct answer: B. Septicemia (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":187,"q":"The temperature of a body of a deceased person is found to be 39 degrees Celsius. Which of the following is the most probable reason?","o":["Cyanide poisoning","Septicemia","Corrosive poisoning","Intra-abdominal hemorrhage"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9684, 'Pathology', 'Renal System', 'Moderate', 'NEET PG 2023', 188, '{"id":9684,"subject":"Pathology","chapter":"Renal System","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":188,"q":"A child presented to the hospital with cola-colored urine, hypertension, and puffiness of eyes. Laboratory investigations were done, and creatinine was 2.5 mg/dL. Treatment was started, and despite treatment, the patient did not improve for the next 3 weeks. The creatinine value increased to 4.5 mg/dL. Which among the following electron microscopic findings will be seen in this patient?","o":["Subendothelial deposits","Subepithelial deposits","Crescent formation","Mesangial deposits"],"a":1,"e":"Correct answer: B. Subepithelial deposits (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":188,"q":"A child presented to the hospital with cola-colored urine, hypertension, and puffiness of eyes. Laboratory investigations were done, and creatinine was 2.5 mg/dL. Treatment was started, and despite treatment, the patient did not improve for the next 3 weeks. The creatinine value increased to 4.5 mg/dL. Which among the following electron microscopic findings will be seen in this patient?","o":["Subendothelial deposits","Subepithelial deposits","Crescent formation","Mesangial deposits"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9685, 'PSM', 'Communicable and Non-communicable Diseases', 'Moderate', 'NEET PG 2023', 189, '{"id":9685,"subject":"PSM","chapter":"Communicable and Non-communicable Diseases","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":189,"q":"A 35-year-old homeless man presented with a 1-month history of fever, cough, and weight loss. Both sputum smears turned out to be negative, but the chest x-ray ordered was suggestive of tuberculosis. According to the recent NTEP guidelines, which is the next best line of management?","o":["Repeat sputum smears","Ask for CBNAAT","Ask for line probe assay","Wait until TB culture results to start ATT"],"a":1,"e":"Correct answer: B. Ask for CBNAAT (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":189,"q":"A 35-year-old homeless man presented with a 1-month history of fever, cough, and weight loss. Both sputum smears turned out to be negative, but the chest x-ray ordered was suggestive of tuberculosis. According to the recent NTEP guidelines, which is the next best line of management?","o":["Repeat sputum smears","Ask for CBNAAT","Ask for line probe assay","Wait until TB culture results to start ATT"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9686, 'Forensic Medicine', 'Forensic Toxicology', 'Moderate', 'NEET PG 2023', 190, '{"id":9686,"subject":"Forensic Medicine","chapter":"Forensic Toxicology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":190,"q":"A farmer was sleeping in the field, and he felt a sting on his leg. He saw something moving away quickly. He then got drowsy and was taken to the hospital. He developed pain around the site and continued to bleed profusely from the wound site. The wound became red with blisters. Which of the following is the most likely cause?","o":["Viper","Cobra","Wasp bite","Scorpion"],"a":0,"e":"Correct answer: A. Viper (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":190,"q":"A farmer was sleeping in the field, and he felt a sting on his leg. He saw something moving away quickly. He then got drowsy and was taken to the hospital. He developed pain around the site and continued to bleed profusely from the wound site. The wound became red with blisters. Which of the following is the most likely cause?","o":["Viper","Cobra","Wasp bite","Scorpion"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9687, 'Pathology', 'Blood Banking and Transfusion Medicine', 'Moderate', 'NEET PG 2023', 191, '{"id":9687,"subject":"Pathology","chapter":"Blood Banking and Transfusion Medicine","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":191,"q":"A patient was transfused 4 units of blood 2 hours ago, and now she complains of chest discomfort. X-ray shows bilateral fissural thickening. Which of the following is the most probable cause?","o":["ABO incompatibility reactions","Fluid overload","Hypocalcemia","Graft-versus-host disease"],"a":1,"e":"Correct answer: B. Fluid overload (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":191,"q":"A patient was transfused 4 units of blood 2 hours ago, and now she complains of chest discomfort. X-ray shows bilateral fissural thickening. Which of the following is the most probable cause?","o":["ABO incompatibility reactions","Fluid overload","Hypocalcemia","Graft-versus-host disease"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9688, 'PSM', 'Epidemiology', 'Moderate', 'NEET PG 2023', 192, '{"id":9688,"subject":"PSM","chapter":"Epidemiology","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":192,"q":"Which of the following is the sensitive indicator to assess the availability, utilization, and effectiveness of healthcare in a community?","o":["Infant mortality rate","Maternal mortality rate","Immunization coverage","Disability-adjusted life years"],"a":0,"e":"Correct answer: A. Infant mortality rate (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":192,"q":"Which of the following is the sensitive indicator to assess the availability, utilization, and effectiveness of healthcare in a community?","o":["Infant mortality rate","Maternal mortality rate","Immunization coverage","Disability-adjusted life years"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9689, 'Pathology', 'Renal System', 'Moderate', 'NEET PG 2023', 193, '{"id":9689,"subject":"Pathology","chapter":"Renal System","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":193,"q":"A 48-year-old man presents with complaints of facial puffiness, frothy urine, and hypertension. He gives a history of infection with hepatitis B. Urine examination reveals microscopic hematuria. The histopathological image of the kidney biopsy shows a spike and dome pattern. What is the diagnosis of this condition?","o":["Minimal change disease","Membranous nephropathy","FSGS","PSGN-associated disease"],"a":1,"e":"Correct answer: B. Membranous nephropathy (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":193,"q":"A 48-year-old man presents with complaints of facial puffiness, frothy urine, and hypertension. He gives a history of infection with hepatitis B. Urine examination reveals microscopic hematuria. The histopathological image of the kidney biopsy shows a spike and dome pattern. What is the diagnosis of this condition?","o":["Minimal change disease","Membranous nephropathy","FSGS","PSGN-associated disease"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9690, 'Pathology', 'CVS, Blood Vessels and Vasculitis', 'Moderate', 'NEET PG 2023', 194, '{"id":9690,"subject":"Pathology","chapter":"CVS, Blood Vessels and Vasculitis","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":194,"q":"A 5-year-old child is brought with fever, fatigue, and left ventricular dysfunction. An endomyocardial biopsy is shown below. What is the probable diagnosis?","o":["Acute rheumatic fever","Chagas disease","Pyogenic myocarditis","Lymphocytic myocarditis"],"a":3,"e":"Correct answer: D. Lymphocytic myocarditis (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":194,"q":"A 5-year-old child is brought with fever, fatigue, and left ventricular dysfunction. An endomyocardial biopsy is shown below. What is the probable diagnosis?","o":["Acute rheumatic fever","Chagas disease","Pyogenic myocarditis","Lymphocytic myocarditis"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9691, 'Pathology', 'Respiratory System', 'Moderate', 'NEET PG 2023', 195, '{"id":9691,"subject":"Pathology","chapter":"Respiratory System","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":195,"q":"An elderly male is known as a smoker presented with chronic cough, significant weight loss, and fatigue. Serum calcium level is raised. A lung biopsy was done, and it showed large atypical cells with hyperchromasia. What is the probable diagnosis?","o":["Large cell neuroendocrine tumor","Small cell carcinoma","Adenocarcinoma","Squamous cell carcinoma"],"a":3,"e":"Correct answer: D. Squamous cell carcinoma (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":195,"q":"An elderly male is known as a smoker presented with chronic cough, significant weight loss, and fatigue. Serum calcium level is raised. A lung biopsy was done, and it showed large atypical cells with hyperchromasia. What is the probable diagnosis?","o":["Large cell neuroendocrine tumor","Small cell carcinoma","Adenocarcinoma","Squamous cell carcinoma"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9692, 'Pathology', 'Hematology: White Blood Cells', 'Moderate', 'NEET PG 2023', 196, '{"id":9692,"subject":"Pathology","chapter":"Hematology: White Blood Cells","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":196,"q":"An elderly male went for a medical examination. Laboratory investigations showed a marked elevation of lymphocytes with marked leukocytosis. The peripheral smear of the patient is given below. What is the appropriate next step for this patient?","o":["Stem cell transplantation","Bone marrow biopsy","Flow cytometry","Start high-dose chemotherapy"],"a":2,"e":"Correct answer: C. Flow cytometry (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":196,"q":"An elderly male went for a medical examination. Laboratory investigations showed a marked elevation of lymphocytes with marked leukocytosis. The peripheral smear of the patient is given below. What is the appropriate next step for this patient?","o":["Stem cell transplantation","Bone marrow biopsy","Flow cytometry","Start high-dose chemotherapy"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9693, 'Pathology', 'Platelets and Blood Transfusion', 'Moderate', 'NEET PG 2023', 197, '{"id":9693,"subject":"Pathology","chapter":"Platelets and Blood Transfusion","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":197,"q":"A 25-year-old male presented with low hemoglobin, platelet count of 25,000/mL, gum bleeding, and raised PT & aPTT. The image of his peripheral smear is given below. What is the likely diagnosis?","o":["AML with t(8;21)","AML with inv(16)","AML with t(15;17)","AML with t(11;22)"],"a":2,"e":"Correct answer: C. AML with t(15;17) (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":197,"q":"A 25-year-old male presented with low hemoglobin, platelet count of 25,000/mL, gum bleeding, and raised PT & aPTT. The image of his peripheral smear is given below. What is the likely diagnosis?","o":["AML with t(8;21)","AML with inv(16)","AML with t(15;17)","AML with t(11;22)"],"a":2,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9694, 'Pathology', 'Platelet and Bleeding Disorders', 'Moderate', 'NEET PG 2023', 198, '{"id":9694,"subject":"Pathology","chapter":"Platelet and Bleeding Disorders","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":198,"q":"A young patient presents with a large retroperitoneal hemorrhage. He also gives a frequent history of intermittent swelling of knees on strenuous exercise. There is no history of any mucosal bleeding. Which among the following clotting factors is responsible for the condition mentioned above?","o":["Factors VIII and IX","Factors XI and XII","Von Willebrand factor","Lupus anticoagulant"],"a":0,"e":"Correct answer: A. Factors VIII and IX (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":198,"q":"A young patient presents with a large retroperitoneal hemorrhage. He also gives a frequent history of intermittent swelling of knees on strenuous exercise. There is no history of any mucosal bleeding. Which among the following clotting factors is responsible for the condition mentioned above?","o":["Factors VIII and IX","Factors XI and XII","Von Willebrand factor","Lupus anticoagulant"],"a":0,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9695, 'Pathology', 'Respiratory System', 'Moderate', 'NEET PG 2023', 199, '{"id":9695,"subject":"Pathology","chapter":"Respiratory System","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":199,"q":"A chronic smoker who worked in a cement factory for 20 years developed mesothelioma. The association is likely to be due to ________.","o":["Silicosis","Asbestosis","Coal workers'' pneumoconiosis","Bagassosis"],"a":1,"e":"Correct answer: B. Asbestosis (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":199,"q":"A chronic smoker who worked in a cement factory for 20 years developed mesothelioma. The association is likely to be due to ________.","o":["Silicosis","Asbestosis","Coal workers'' pneumoconiosis","Bagassosis"],"a":1,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
INSERT OR REPLACE INTO questions (id, subject, chapter, difficulty, source, source_no, data) VALUES (9696, 'PSM', 'Nutrition and Health', 'Moderate', 'NEET PG 2023', 200, '{"id":9696,"subject":"PSM","chapter":"Nutrition and Health","difficulty":"Moderate","source":"NEET PG 2023","sourceNo":200,"q":"The average daily dietary nutrient intake level sufficient to meet the nutrient requirements of nearly all (97-98%) healthy individuals in a particular life stage and gender group is known as?","o":["Adequate intake","Dietary goal","Estimated average requirement","Recommended dietary allowance"],"a":3,"e":"Correct answer: D. Recommended dietary allowance (Answer marked in the supplied NEET-PG 2023 source.)","pyqMatches":[{"year":"2023","no":200,"q":"The average daily dietary nutrient intake level sufficient to meet the nutrient requirements of nearly all (97-98%) healthy individuals in a particular life stage and gender group is known as?","o":["Adequate intake","Dietary goal","Estimated average requirement","Recommended dietary allowance"],"a":3,"source":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf"}],"pyqYears":["2023"]}');
