INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9938, '2023', 1, 'Microbiology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":1,"q":"A patient hailing from Delhi presents with fever, arthralgia, and extensive petechial rash for 3 days. Lab investigations revealed a hemoglobin of 9 g/ dL, a white blood cell count of 9000 cells/mm3, a platelet count of 20000 cells/mm3, and a prolonged bleeding time. The clotting time was normal. What is the most likely diagnosis?","o":["Dengue","Malaria","Scrub typhus","Typhoid"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Microbiology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9939, '2023', 2, 'Microbiology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":2,"q":"Which of the following statements is true about Trichomonas vaginalis?","o":["It cannot be cultured","Twitching motility is seen on wet saline mount","Cysts are seen on wet saline mount of vaginal secretions","It is not a sexually transmitted infection"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Microbiology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9940, '2023', 3, 'Microbiology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":3,"q":"A lady from West Rajasthan presented with an ulcer surrounded by erythema on the right leg. Microscopy of the biopsy from the edge of the ulcer showed organisms with dark staining nuclei and kinetoplast. What is the most likely causative agent?","o":["Leishmania tropica","Babesia","Trypanosoma","Histoplasma"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Microbiology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9941, '2023', 4, 'Microbiology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":4,"q":"A child presents with a fever and a rash. Urine examination showed cells with owl''s eye appearance. What is the most likely diagnosis?","o":["Cytomegalovirus","Epstein-Barr virus","Herpes simplex virus","Toxoplasma gondii"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Microbiology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9942, '2023', 5, 'Microbiology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":5,"q":"Infection with Clonorchis sinensis is associated with an increased risk of__?","o":["Cervical cancer","Cholangiocarcinoma","Gastric carcinoma","Bladder carcinoma"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Microbiology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9943, '2023', 6, 'Microbiology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":6,"q":"A patient presented with complaints of persistent cough and weight loss. He had a history of contact with multiple sexual partners. He was diagnosed as HIV positive 6 months back and is poorly adherent to his medications. The fungal culture of sputum was negative. On Gomori methamine silver staining, the cells showed darkly stained crescent-shaped cysts. What is the most likely causative organism?","o":["Paracoccidiodes brasiliensis","Histoplasma capsulatum","Coccidiodes immitis","Pneumocystis jerovecii"],"a":3,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Microbiology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9944, '2023', 7, 'Microbiology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":7,"q":"A sewage worker presented with abdominal pain, jaundice, conjunctival injection, and blood in the urine for the past 5 days. Which of the following is the investigation of choice?","o":["Widal test","Microscopic agglutination test","Weil-Felix reaction","Paul-Bunnell test"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Microbiology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9945, '2023', 8, 'Microbiology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":8,"q":"Which of the following laboratory test is used to diagnose rotavirus diarrhea?","o":["Antigen detection in the stool sample","Antigen detection in blood","Antibody detection in serum","Light microscopy of stool specimen"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Microbiology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9946, '2023', 9, 'Microbiology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":9,"q":"A boy presented with a fever and chills. Rapid test was positive for specific antigen HRP-2. Which of the following species of Plasmodium is the most likely causative agent?","o":["Plasmodium falciparum","Plasmodium malariae","Plasmodium vivax","Plasmodium ovale"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Microbiology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9947, '2023', 10, 'Microbiology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":10,"q":"A child was brought with complaints of high fever, multiple seizures, headache, and neck rigidity. CSF analysis showed low glucose, high protein, and many polymorphs. The CSF culture showed pleomorphic gram-negative bacilli. What is true about the causative organism?","o":["It is bacitracin sensitive.","Produces non-lactose fermenting colonies on MacConkey agar","Exhibits satellitism around Staphylococcus aureus colonies","It exhibits alpha hemolysis on sheep blood agar"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Microbiology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9948, '2023', 11, 'Microbiology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":11,"q":"A man presents with a history of dysuria and urethral discharge after having unprotected sexual intercourse. Gram-staining of the purulent discharge is seen in the following image. What is the treatment of choice for this infection?","o":["Erythromycin","Azithromycin","Ceftriaxone","Penicillin G"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Microbiology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9949, '2023', 12, 'Radiology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":12,"q":"A 2-month-old infant is brought to the OPD with a parietal swelling present since birth. The X-ray image is given below. What could be the probable diagnosis?","o":["Subgaleal hematoma","Cephalhematoma","Caput succedaneum","Enecephalocele"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Radiology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9950, '2023', 13, 'Radiology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":13,"q":"A patient presented with abdominal pain and sterile pyuria, and the x-ray showed the following features. What is the likely diagnosis?","o":["Putty kidney","Nephrocalcinosis","Staghorn calculus","Psoas calcification"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Radiology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9951, '2023', 14, 'Anatomy', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":14,"q":"A defect in which of the following forms the structure marked below?","o":["Internal oblique","External oblique","Parietal peritoneum","Fascia transversalis"],"a":3,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Anatomy"}');
