INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9953, '2023', 16, 'Anatomy', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":16,"q":"The given histology image is of ?","o":["Leydig cells of testis","Pancreatic islet cells","Hassall''s corpuscles","Glomerulus"],"a":3,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Anatomy"}');
