INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9956, '2023', 19, 'Anatomy', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":19,"q":"A patient comes with abdominal pain, jaundice, and portal hypertension. Anastomosis between which of the following veins is seen?","o":["Left colic vein and middle colic veins","Esophageal veins and left gastric veins","Superior rectal and phrenic veins","Sigmoid and superior rectal veins"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Anatomy"}');
