INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9958, '2023', 21, 'Biochemistry', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":21,"q":"A patient presented with diarrhea, dermatitis, and dementia. Which of the following vitamin deficiencies would you suspect in this patient?","o":["Vitamin B3 deficiency","Vitamin B1 deficiency","Vitamin B6 deficiency","Vitamin B12 deficiency"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Biochemistry"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9959, '2023', 22, 'Biochemistry', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":22,"q":"A young boy presents to the OPD with hypoglycemia and muscle cramps, on exertion or while playing. Then he becomes normal after resting for a while. These episodes are recurrent after a period of activity. He has decreased serum lactate and glucose levels. Which of the following diseases is he most likely to be suffering from?","o":["McArdle disease","Hers disease","Cori''s disease","Andersen disease"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Biochemistry"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9960, '2023', 23, 'Biochemistry', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":23,"q":"A family consumes only polished rice. Which of the following combinations of vitamin deficiency and enzymatic defect will be present in this family?","o":["Riboflavin-glutathione reductase","Thiamine-transketolase","Thiamine-transaminase","Riboflavin-transketolase"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Biochemistry"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9961, '2023', 24, 'Biochemistry', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":24,"q":"A chronic alcoholic patient presented to the casualty with confusion, ataxia, and painful eye movements. What could be the vitamin deficiency seen in this patient?","o":["Vitamin B deficiency","Vitamin A deficiency","Vitamin D deficiency","Vitamin C deficiency"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Biochemistry"}');
