INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9963, '2023', 26, 'Biochemistry', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":26,"q":"A child was bought with pedal edema and cheilosis. Cardiomegaly was present. What is the vitamin deficiency associated with this clinical presentation?","o":["Riboflavin","Thiamine","Pyridoxine","Niacin"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Biochemistry"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9964, '2023', 27, 'Biochemistry', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":27,"q":"A chronic alcoholic patient is diagnosed with gouty arthritis. What biochemical changes will be seen in this patient?","o":["Decreased NADH/NAD+ ratio","Increased urea and urate levels","Increased urate and lactate levels","Increased level of alkaline phosphatase"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Biochemistry"}');
