INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9966, '2023', 29, 'Biochemistry', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":29,"q":"A patient presenting with bleeding gums and easy bruisability was diagnosed with scurvy. This is due to","o":["Low calcium","Defective collagen formation","Inhibition of clotting factors","Increased keratinization of epithelium"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Biochemistry"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9967, '2023', 30, 'Biochemistry', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":30,"q":"Which of the following is seen in low insulin: glucagon ratio?","o":["Activation of lipoprotein lipase","Activation of glycogen synthase","Activation of phosphofructokinase 1","Activation of hormone-sensitive lipase"],"a":3,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Biochemistry"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9968, '2023', 31, 'Biochemistry', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":31,"q":"An infant is brought by his parents with complaints that his urine turns black on standing. Which of the following metabolic disorders is likely?","o":["Phenylketonuria","Alkaptonuria","Homocystinuria","Maple syrup urine disease"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Biochemistry"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9969, '2023', 32, 'Biochemistry', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":32,"q":"A child presents with thinning of hair and scaling of the scalp. On taking further history, it is found that she consumes raw eggs in her diet regularly. The given manifestations are due to the deficiency of which of the following vitamins?","o":["Niacin","Pyridoxine","Biotin","Thiamine"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Biochemistry"}');
