INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9980, '2023', 43, 'Surgery', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":43,"q":"A patient presents to the clinic with the lesion given in the image. He had a traumatic injury to the chest one year ago. What is the most likely diagnosis?","o":["Hemangioma","Hypertrophic scar","Keloid","Neurofibroma"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Surgery"}');
