INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9982, '2023', 45, 'Surgery', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":45,"q":"A patient was brought to the ER following a road traffic accident. On examination, the patient opens his eyes to a painful stimulus, speaks inappropriately, and withdraws his limbs to a painful stimulus. What is his GCS score?","o":["E2V2M3","E3V3M3","E2V3M4","E3V2M2"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Surgery"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (9983, '2023', 46, 'Surgery', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":46,"q":"A patient presented with fever and abdominal pain with jaundice. Investigations showed the given findings. Which of the following statements is true regarding this condition?","o":["Surgery is mandatory","Fine-needle aspiration cytology is diagnostic","Angioembolization is the treatment of choice","Echinococcus species is involved in etiology"],"a":3,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Surgery"}');
