INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10026, '2023', 89, 'Surgery', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":89,"q":"A 23-year-old male patient presents with midline swelling in the neck. The swelling moves with deglutition and protrusion of the tongue. What is the likely diagnosis?","o":["Brachial cyst","Thyroglossal cyst","Plunging ranula","Dermoid cyst"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Surgery"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10027, '2023', 90, 'Physiology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":90,"q":"Identify the true statement regarding the given nerve action potential curve?","o":["The threshold point is at A","At point E, the nerve is more excitable","Point C to D is due to the opening of Na+ and closure of K+ channels","Point B to D is a refractory period"],"a":3,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Physiology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10028, '2023', 91, 'Surgery', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":91,"q":"A young patient is admitted with a history of fever for 5 days. BP is 90/60 mmHg, PR-120 bpm, RR-24 breaths/ min, GCS score-10; laboratory tests show leucocytosis with neutrophilia and serum creatinine level of 2.6 mg/ dL. An intern doctor wants to calculate the qSOFA score to predict prognosis and hospitalization duration. Which of the following comprises the qSOFA score?","o":["BP, RR and CBC","Creatinine, PR, BP","RR, Body temperature, PR","SBP, RR, GCS score"],"a":3,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Surgery"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10029, '2023', 92, 'Physiology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":92,"q":"Identify the type of transport across the cell membrane given below?","o":["Simple diffusion","Facilitated diffusion","Primary active transport","Secondary active transport"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Physiology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10030, '2023', 93, 'Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":93,"q":"Identify the condition associated with the murmur in the image below.","o":["Mitral regurgitation","Aortic regurgitation","Aortic stenosis","Mitral stenosis"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10031, '2023', 94, 'Psychiatry', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":94,"q":"A woman, who is 4 days postpartum, presented with tearfulness, mood swings, and occasional insomnia. What is the likely diagnosis?","o":["Postpartum depression","Postpartum blues","Postpartum psychosis","Postpartum anxiety"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Psychiatry"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10032, '2023', 95, 'Psychiatry', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":95,"q":"A 25-year-old female reported symptoms of anxiety, palpitations, sweating, breathlessness, chest pain, and a feeling of impending doom. She recalls having experienced 5-6 similar episodes in the past 6 months, each episode lasting for about 20-30 minutes. What is the likely diagnosis?","o":["Depression","Panic disorder","Generalized anxiety disorder","Phobia"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Psychiatry"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10033, '2023', 96, 'Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":96,"q":"A young man came to the medical OPD with complaints of early morning backache and stiffness, which improves on exercise, and persistent red eyes. On examination, lung expansion was less than 3 cm. X-ray is shown in the image given below. What is the most probable diagnosis?","o":["Ankylosing spondylitis","Paget''s disease","Healed tuberculosis","Osteopetrosis"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10034, '2023', 97, 'Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":97,"q":"A patient with hyperkalemia and elevated urea levels underwent dialysis. Towards the end of the session, she became drowsy and had a sudden seizure episode. On examination, the patient was hypotensive. What is the treatment for this condition?","o":["Bumetanide","Ethacrynic acid","Nesiritide","IV Mannitol"],"a":3,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10035, '2023', 98, 'Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":98,"q":"A female patient presents to the emergency department with severe restlessness, palpitations, and tremors. She is a known case of bronchial asthma. On examination, the neck looks swollen. Blood pressure is elevated, and tachycardia is noted. ECG shows atrial fibrillation. Which of the following drugs is used for immediate management in this patient?","o":["Diltiazem","Propranolol","Esmolol","Propylthiouracil"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10036, '2023', 99, 'Physiology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":99,"q":"A preterm baby who was delivered at 28 weeks developed respiratory distress syndrome. Which of the following is true about surface tension and compliance in this baby?","o":["Surface tension - decreased; Compliance - increased","Surface tension - increased; Compliance - decreased","Both surface tension and compliance decreased","Both surface tension and compliance increased"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Physiology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10037, '2023', 100, 'Psychiatry', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":100,"q":"A middle-aged man complains of very early ejaculation during intercourse. What is the non-pharmacological management that can be advised to the patient?","o":["Cognitive behavioral therapy","Exposure and response prevention therapy","Squeeze technique","Sensate focus therapy"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Psychiatry"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10038, '2023', 101, 'Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":101,"q":"A 30-year-old male is found to be positive for HBsAg and HBeAg and is diagnosed with chronic hepatitis B. The patient’s viral load was 2x 100000 and SGPT is found to be doubled. What is the appropriate management in this patient? SGPT-Serum glutamate pyruvate transaminase","o":["Lamivudine for 30+ weeks","Tenofovir for> 40 weeks","Pegylated interferon for 52 weeks","Combined pegylated interferon with lamivudine"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10039, '2023', 102, 'Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":102,"q":"A 25-year-old male patient complained of palpitations, sweating, and restlessness. He has a complaint of sweaty palms. Clinical findings are depicted in the image given below. What is the diagnostic test done on this patient?","o":["Anti-thyroglobulin antibody","Anti-thyroid peroxidase antibody","Thyroid receptor antibody","Elevated ultrasensitive thyrotropin levels"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10040, '2023', 103, 'Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":103,"q":"A 50-year-old HIV patient presented with a painless lesion, as shown in the image. What is the most likely diagnosis?","o":["Basal cell carcinoma","Kaposi sarcoma","Malignant melanoma","Squamous cell carcinoma"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10041, '2023', 104, 'Physiology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":104,"q":"A patient came to the hospital after a road traffic accident. He had severe muscle injury, and his serum K+ level was found to be 5.5 mEq/L. What will happen to the resting membrane potential in this patient?","o":["No change","Becomes more negative","Becomes more positive","First becomes more positive then negative"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Physiology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10042, '2023', 105, 'Pediatrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":105,"q":"A newborn presented with chest retractions, dyspnea, and lethargy. The pediatrician diagnosed the baby with respiratory distress syndrome. This occurs due to the deficiency of:","o":["Dipalmitoyl inositol","Lecithin","Sphingomyelin","Dipalmitoylphosphatidylethanolamine"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Pediatrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10043, '2023', 106, 'Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":106,"q":"A patient is brought to the OPD by his wife, complaining about difficulty expressing emotions and not participating in daily activities. On examination, resting tremors and rigidity are noted. Given the possible diagnosis, which part of the brain is affected in this patient?","o":["Basal ganglia","Hippocampus","Cerebellum","Premotor cortex"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10044, '2023', 107, 'Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":107,"q":"A 45-year-old HIV-positive male complained of persistent cough and weight loss. He has skin lesions that appear as umbilicated papules and nodules predominantly on the face, trunk, and upper extremities. Chest x-ray showed multiple bilateral nodular infiltrates. His sputum CBNAAT for tuberculosis was negative, and he has a low CD4 count. What is the probable diagnosis?","o":["HIV with disseminated histoplasmosis","HIV with disseminated cryptococcosis","HIV with molluscum contagiosum","HIV with tuberculosis"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10045, '2023', 108, 'Physiology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":108,"q":"A patient met with a road traffic accident and developed a cervical spine injury. The fracture fragment had pierced the lateral aspect of the dorsal column tract. Which of the following findings is seen in this patient?","o":["Absence of ipsilateral lower limb proprioception","Absence of fine motor movement of fingers","Absence of ipsilateral arm proprioception","Absence of contralateral lower limb proprioception"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Physiology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10046, '2023', 109, 'Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":109,"q":"A male patient presented to the emergency room with seizures. He has a history of fever, headache, and confusion. An MRI brain was done, and it showed inflammation involving the bitemporal lobe. What is the most likely aetiology for this presentation?","o":["Cytomegalovirus","Toxoplasma gondii","Herpes simplex virus","Mycobacterium tuberculosis"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10047, '2023', 110, 'Physiology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":110,"q":"Identify the true statement regarding the point marked(Red) on the myocardial action potential curve?","o":["Due to the opening of Na+ and closure of fast K+ channels","Due to the slow but prolonged opening of Ca2+ channels","Due to the closure of Na+ and opening of the slow K+ channel","Due to Na+/K+ ATPase"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Physiology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10048, '2023', 111, 'Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":111,"q":"A male patient presents with sensory loss and weakness of limbs for 3 months. He also has angular stomatitis. On examination, there is loss of proprioception, vibration sensations, UMN type of lower limb weakness, and absent ankle reflex. What is the most probable diagnosis?","o":["Extradural cord compression","Amyotrophic lateral sclerosis","Multiple sclerosis","Subacute combined degeneration of cord"],"a":3,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10049, '2023', 112, 'Pediatrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":112,"q":"A 10-year-old child weighing 30 kg presents with a history of loose stools for 2 days. On examination, there is severe dehydration. Laboratory investigations are as follows. What is the initial management as per ISPAD guidelines? RBS 550mg/dL pH 7.01 Na+ 158mEq/L Urine glucose 3+","o":["Manage ABC, NS 20 mL/kg and start insulin after 1 hour","Manage ABC, NS 20 mL/kg along with insulin 0.1 IU/kg/hr","Manage ABC, NS 10 mL/kg along with insulin 0.1 IU/kg/hr","Manage ABC, NS 10 mL/kg and start insulin after 1 hour"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Pediatrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10050, '2023', 113, 'Pediatrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":113,"q":"Which of the following is the best sign to indicate adequate growth in an infant with a birth weight of 2.8 kg?","o":["Increase in length of 25 centimetres in the first year","Weight gain of 300 grams per month till 1 year","Anterior fontanelle closure by 6 months of age","Weight under the 75th percentile and height under the 25th percentile"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Pediatrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10051, '2023', 114, 'Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":114,"q":"A 40-year-old female patient came with complaints of chest pain, palpitation, and shortness of breath. On examination, a mid-diastolic murmur was heard, and a prominent ''a'' wave was found on JVP. What is the most likely diagnosis?","o":["Mitral stenosis","Tricuspid stenosis","Mitral regurgitation","Tricuspid regurgitation"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10052, '2023', 115, 'Pediatrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":115,"q":"A 3-month-old baby complains of deafness, cataract, and patent ductus arteriosus. Which of the following is the most likely diagnosis?","o":["Congenital herpes simplex virus infection","Congenital toxoplasmosis","Congenital cytomegalovirus infection","Congenital rubella syndrome"],"a":3,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Pediatrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10053, '2023', 116, 'PSM', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":116,"q":"In a village, it is observed that several farmers have crossed gait and use a stick for support to stand up and walk. Due to poor yield from farms, they consume meals containing rice and pulses only. Supplementing their diet with which of the following vitamins could have prevented this?","o":["Vitamin A","Vitamin D","Vitamin C","Vitamin B"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"PSM"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10054, '2023', 117, 'PSM', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":117,"q":"Research is being conducted to find the association between aniline dye exposure and bladder cancer in workers who have worked in the industry for >20 years. Two groups were formed: one directly involved with dye handling and the other group consisting of office clerks not directly exposed to the dye. Years of occupation were noted from records. What type of study is being performed?","o":["Retrospective cohort study","Prospective cohort study","Case-control study","Intervention and response"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"PSM"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10055, '2023', 118, 'Pediatrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":118,"q":"Chloride level in sweat is used in the diagnosis of which disease?","o":["Phenylketonuria","Cystic fibrosis","Gaucher''s disease","Osteogenesis imperfecta"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Pediatrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10056, '2023', 119, 'Pediatrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":119,"q":"A child presents with fever and a rash spreading from the face, behind cheeks, and buccal mucosa to other body parts. On examination, Koplik''s spot is present. What is the likely diagnosis?","o":["Measles","Rubella","Varicella","Mumps"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Pediatrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10057, '2023', 120, 'PSM', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":120,"q":"The blood pressure of a population was tracked from childhood to adulthood. It was observed that those who had lower BP in childhood had low BP in adulthood, while those who had higher BP in childhood had high BP in adulthood. This can be best described as","o":["Rule of halves","Tracking of blood pressure","STEPwise approach","Primordial approach"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"PSM"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10058, '2023', 121, 'Pediatrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":121,"q":"A 3-week-old infant presents with a cough and sore throat. The mother reports that the infant develops a paroxysm of cough followed by apnea. The total leucocyte count is >50,000 cells/μL. Which of the following drugs will you prescribe for this patient?","o":["Azithromycin","Amoxicillin","Cotrimoxazole","Clarithromycin"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Pediatrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10059, '2023', 122, 'PSM', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":122,"q":"A 30-week primigravida complaints of reduced vision at night. She has been avoiding papaya, mango, and other fruits throughout her pregnancy as she thinks they could be abortifacients. It is the primary duty of which of the following workers to provide counseling and information to the patient?","o":["ANM","AWW","Trained birth attendant","ASHA"],"a":3,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"PSM"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10060, '2023', 123, 'ENT', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":123,"q":"Identify the structure marked in the image.","o":["Fossa of Rosenmuller","Tubal tonsil","Opening of the Eustachian tube","Adenoid"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"ENT"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10061, '2023', 124, 'PSM', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":124,"q":"A 22-year-old female comes to the STI clinic with minimal vaginal discharge. On speculum examination, erosions are seen on the cervix. Which of the following kit should be given to this patient?","o":["Green","Red","Grey","Yellow"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"PSM"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10062, '2023', 125, 'PSM', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":125,"q":"The years of potential life lost could be attributed to,","o":["Years lost to morbidity","Years lost due to premature death","Years lost to disability","Years lost to poor quality of life"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"PSM"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10063, '2023', 126, 'ENT', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":126,"q":"The instrument shown in the image is not used for which of the following?","o":["Airway toileting","Upper airway examination","Acute nasopharyngeal obstruction","Prolonged mechanical ventilation"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"ENT"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10064, '2023', 127, 'PSM', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":127,"q":"In a 10-year-old school child, which of the following vaccines is given as a part of the school immunization program?","o":["Measles vaccine","Rotavirus vaccine","TT/Td vaccine","Hepatitis B vaccine"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"PSM"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10065, '2023', 128, 'ENT', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":128,"q":"A 10-year-old child presents with throat pain, fever, and ear pain. He is diagnosed with recurrent tonsillitis. Which nerve is responsible for the ear pain in this patient?","o":["Tympanic branch of the glossopharyngeal nerve","Greater auricular nerve","Auriculotemporal nerve","Auricular branch of the vagus nerve"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"ENT"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10066, '2023', 129, 'PSM', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":129,"q":"Which of the following statements is true about cancer treatment according to the Colombo plan?","o":["Help with PET scan units for diagnosis of cancer","Human resource strengthening","Setting up chemotherapy units","Setting up cobalt therapy units"],"a":3,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"PSM"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10067, '2023', 130, 'PSM', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":130,"q":"A poor farmer with a history of successive crop failure develops progressive spastic paraparesis, signs of upper motor neuron paralysis, and gait instability. Name the toxin responsible for this condition.","o":["Aflatoxin","Beta-oxalyl-amino-alanine","Ergot alkaloids","Fusarium toxin"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"PSM"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10068, '2023', 131, 'PSM', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":131,"q":"A young male came to the hospital with a clean-cut wound without any bleeding. The patient received a full course of tetanus vaccination 10 years ago. What is the best management for this patient?","o":["Human tetanus immunoglobulin and full course of vaccine","Human tetanus immunoglobulin only","Single-dose tetanus toxoid","Full course tetanus toxoid"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"PSM"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10069, '2023', 132, 'PSM', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":132,"q":"How is water collected for bacteriological examination during a disease outbreak?","o":["Collect water from already leaking taps","Before collecting, let water flow for at least 1 minute","Water sample container is kept close to the tap avoid spillage","Collect from a gentle stream of water to avoid splashing"],"a":3,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"PSM"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10070, '2023', 133, 'PSM', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":133,"q":"A boys'' hostel has an outbreak of fever cases with headache, followed by the development of pleomorphic rashes sparing palms and soles. What is the next best step in the management of suspected cases? VZIG-Varicella zoster immunoglobulin","o":["Isolate for 6 days after giving acyclovir, followed by VZIG within 72 hours of exposure.","Isolate for 12 days after giving acyclovir, followed by VZIG within 48 hours of exposure","Isolate for 6 days","Only give VZIG"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"PSM"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10071, '2023', 134, 'Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":134,"q":"A patient who is a known case of hypertension on multiple anti-hypertensive medications came to OPD. His ECG finding is given below. Which of the following drugs is responsible for the ECG finding?","o":["Prazosin","Metoprolol","Hydrochlorothiazide","Spironolactone"],"a":3,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10072, '2023', 135, 'Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":135,"q":"A 78-year-old woman presents with a progressive decline in daily activity. She gives a history of convulsions and visual hallucinations. She does not talk to anyone and keeps looking at the sky. Pathological examination shows the presence of Lewy bodies within the neurons. What is the most probable diagnosis?","o":["Parkinson''s disease","Prion disease","Huntington''s chorea","Alzheimer''s disease"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10073, '2023', 136, 'Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":136,"q":"A patient came to the medical OPD with complaints of polyuria. He has a history of undergoing total hypophysectomy. His Na+ levels are found to be 155 mEq/ L, urine osmolarity was 200 mOsm/L. What is the definitive management in this patient?","o":["DDAVP for 2 weeks and then discontinue","DDAVP supplementation for lifelong","Upsetting of receptors so no treatment is required","Thiazides for 2 weeks"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10074, '2023', 137, 'Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":137,"q":"A 65-year-old chronic smoker came to the medicine outpatient department with complaints of upper chest discomfort and drooping of an eyelid. He also complained of pain radiating to the upper arm and a tingling sensation in the 4th and 5th digits of his left hand. The chest X-ray is given below. Which of the following is the most likely diagnosis?","o":["Pancoast tumour","Upper lobe pneumonia","Superior vena cava obstruction","Aspergilloma"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10075, '2023', 138, 'Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":138,"q":"A chronic alcoholic patient presents with acute pain and swelling of the left great toe. There is no history of trauma. Synovial fluid analysis shows raised leukocytes. Lab investigations show normal serum uric acid levels. What is the most likely diagnosis?","o":["Pseudogout","Acute gout","Reactive arthritis","Septic arthritis"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10076, '2023', 139, 'Psychiatry', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":139,"q":"A chronic alcoholic is brought to the emergency department with confusion, ataxia, and painful eye movements. The 6th cranial nerve is also involved. What is the likely diagnosis?","o":["Wernicke''s encephalopathy","Korsakoff psychosis","Delirium tremens","De Clerambault syndrome"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Psychiatry"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10077, '2023', 140, 'Pharmacology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":140,"q":"A patient given digoxin started having side effects like nausea and vomiting. The serum concentration of digoxin was 4 mg/dL. The plasma therapeutic range is 1 mg/dL. If the half-life of digoxin is 40 hours, how long should one wait before resuming the treatment?","o":["40 hours","80 hours","120 hours","140-180 hours"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Pharmacology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10078, '2023', 141, 'Pharmacology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":141,"q":"A patient comes to the casualty with organophosphate poisoning. He was started on atropine infusion and pralidoxime. After 2 hours, the patient had a sudden rise in temperature. What is the likely cause of fever?","o":["Atropine toxicity","A side effect of pralidoxime","Due to organophosphate poisoning","Idiopathic"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Pharmacology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10079, '2023', 142, 'Gynaecology & Obstetrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":142,"q":"A partogram of a woman who is in labor is shown below. Oxytocin infusion is already given. How will you manage the condition?","o":["Forceps-assisted delivery","Vacuum-assisted delivery","Oxytocin infusion","Cesarean section"],"a":3,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Gynaecology & Obstetrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10080, '2023', 143, 'Pharmacology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":143,"q":"The mechanism of action of tissue plasminogen activator is","o":["Inhibit extrinsic pathway","Inhibits platelet aggregation","Enhance fibrin degradation","Inhibit clot formation"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Pharmacology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10081, '2023', 144, 'Gynaecology & Obstetrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":144,"q":"A woman presents to you at 36 weeks of gestation with complaints of breathlessness and excessive abdominal distension. Fetal movements are normal. On examination, fetal parts are not easily felt and fetal heartbeat is heard but it is muffled. Her symphysis fundal height is 41 cm. Her abdomen is tense but not tender. What is the most likely diagnosis?","o":["Abruptio placenta","Hydrocephalus of fetus","Polyhydramnios","Fetal-maternal ascites"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Gynaecology & Obstetrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10082, '2023', 145, 'Gynaecology & Obstetrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":145,"q":"For which of the following procedures in the given OT list, can you preferably do a hysteroscopy?","o":["Tubal ligation","Asherman syndrome","Endocervical polyp","Subserosal fibroid"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Gynaecology & Obstetrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10083, '2023', 146, 'Gynaecology & Obstetrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":146,"q":"A primigravida presents to you with anemia early in her pregnancy. She is 7 weeks pregnant as seen on ultrasound. Her hemoglobin level is 9 g/dL. When should the iron supplements be started for her?","o":["10 to 12 weeks","8 to 10 weeks","After 14 weeks","After 20 weeks"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Gynaecology & Obstetrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10084, '2023', 147, 'Gynaecology & Obstetrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":147,"q":"A 23-year-old woman accompanied by her mother-in-law comes to the infertility clinic. She has been having regular intercourse for 6 months but is not able to conceive. What is the next best step?","o":["Semen analysis for husband","Reassure and review the couple after 6 months","Hysterolaparoscopy","Diagnostic hysteroscopy"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Gynaecology & Obstetrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10085, '2023', 148, 'Anaesthesia', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":148,"q":"During resuscitation, when is the given position indicated?","o":["Unconsciousness with pulse and breathing absent","Unconsciousness with pulse present and breathing absent","Unconsciousness with pulse and breathing present","Unconsciousness with pulse absent and breathing present"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Anaesthesia"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10086, '2023', 149, 'Gynaecology & Obstetrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":149,"q":"A 50-year-old woman presents with foul-smelling bloody discharge per vagina mixed with mucous. On examination, a necrotizing growth is seen in the cervix with lateral parametrium involvement. What is the management for this patient?","o":["Chemotherapy","Brachytherapy","Chemoradiation","Surgery"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Gynaecology & Obstetrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10087, '2023', 150, 'Gynaecology & Obstetrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":150,"q":"A 28-year-old woman with a history of multiple sexual partners presents with lower abdominal pain for 1 month. She experiences minimal discharge and complaints of intermenstrual bleeding. What is the most likely cause?","o":["Herpes simplex","Genital tuberculosis","Candida","Neisseria gonorrhoea"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Gynaecology & Obstetrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10088, '2023', 151, 'Gynaecology & Obstetrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":151,"q":"A woman is set to undergo a complete laparoscopic hysterectomy. She wants to know if there are any disadvantages to this procedure. What are the disadvantages of laproscopis over-open surgery?","o":["Prolonged recovery time","Not knowing the extent of thermal burns","Increased bleeding","Increased pain"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Gynaecology & Obstetrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10089, '2023', 152, 'Gynaecology & Obstetrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":152,"q":"A 27-year-old pregnant G3P2L2 woman presents to you at 36+6 weeks. Ultrasound is done and shows the fetus is in a transverse lie. The liquor is adequate, the placenta is normal, and she has no risk factors. Both her previous deliveries were normal vaginal deliveries. How will you manage this patient?","o":["Cesarean section","External cephalic version","Expectant management","Induction of labor"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Gynaecology & Obstetrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10090, '2023', 153, 'Gynaecology & Obstetrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":153,"q":"A female presents to you with 6 weeks of amenorrhea complaining of bleeding per vagina and slight abdominal pain. The urine pregnancy test is positive and hCG level is 2800 IU/L. A mass is seen on the left adnexa measuring 3 x 2.5 cm. She is hemodynamically stable. How will you manage this patient? hCG-Human chorionic gonadotropin","o":["Oral methotrexate","Single-dose methotrexate injection","Serial methotrexate + leucovorin rescue","Salpingectomy"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Gynaecology & Obstetrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10091, '2023', 154, 'Gynaecology & Obstetrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":154,"q":"A 24-year-old woman who is being treated for infertility with human menopausal gonadotropin came with complaints of sudden abdominal pain, nausea, vomiting, and breathlessness. The finding of the ultrasound is shown below. What is the most likely diagnosis?","o":["Ovarian hyperstimulation syndrome","Polycystic ovarian syndrome","Theca lutein cysts","Granulosa cell tumor"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Gynaecology & Obstetrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10092, '2023', 155, 'Gynaecology & Obstetrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":155,"q":"During a hysteroscopic removal of a submucosal fibroid, a fluid deficit of 2000 mL is estimated in a patient. What is the immediate complication of this?","o":["Acute tubular necrosis","DIC","Pulmonary edema","Thromboembolism"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Gynaecology & Obstetrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10093, '2023', 156, 'Gynaecology & Obstetrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":156,"q":"A woman comes with complaints of pain and swelling in the perineal area. She also has complaints of difficulty in walking and sitting. She gives a history of multiple sexual partners. On examination, a tender swelling is seen with redness on the labia, as shown in the image given below. What is the most likely diagnosis?","o":["Chlamydial infection","Bartholin abscess","Genital Tuberculosis","Herpes infection"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Gynaecology & Obstetrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10094, '2023', 157, 'Gynaecology & Obstetrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":157,"q":"A 54-year-old woman was diagnosed with advanced cervical cancer. She has a 14-year-old daughter. What advice would you give her daughter?","o":["Advise HPV vaccine","Screen for BRCA mutation","Screen for PTEN mutation","Perform cervical biopsy"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Gynaecology & Obstetrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10095, '2023', 158, 'Gynaecology & Obstetrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":158,"q":"A 17-year-old girl is seen for primary amenorrhea. There is no development of breasts or hair in the pubic or axillary region. Her height is 155 cm, and her weight is 48 kg. She has bilateral inguinal masses. The uterus, fallopian tube, and Ovary are absent on ultrasound examination. What is the most likely diagnosis?","o":["Complete androgen insensitivity syndrome","Hypergonadotropic hypogonadism","Turner syndrome","Polycystic ovary syndrome"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Gynaecology & Obstetrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10096, '2023', 159, 'Surgery', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":159,"q":"A 54-year-old woman presents with cervical cancer stage 2A. It is decided to give neoadjuvant chemotherapy. What does neoadjuvant chemotherapy mean?","o":["Chemotherapy is given along with radiation.","Chemotherapy is given during surgery.","Chemotherapy is given before radical surgery to reduce the bulk of the tumor","Chemotherapy is given after radical surgery for micrometastases"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Surgery"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10097, '2023', 160, 'Gynaecology & Obstetrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":160,"q":"A 16-year-old girl presents with cyclical pelvic pain every month. She has not achieved menarche yet. On examination, a suprapubic bulge can be seen in the lower abdomen. PR examination reveals a bulging swelling in the anterior aspect. What is the most likely diagnosis?","o":["Transverse vaginal septum above the vagina","Vaginal atresia","Imperforate hymen","Cervical agenesis"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Gynaecology & Obstetrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10098, '2023', 161, 'Gynaecology & Obstetrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":161,"q":"A pregnant woman comes to the clinic. She already has twins by normal delivery. Which of the following is the correct representation of her obstetric score?","o":["G3P2","G3P1","G2P1","G2P2"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Gynaecology & Obstetrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10099, '2023', 162, 'Surgery', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":162,"q":"A patient presents with sudden onset of hematemesis. He has been taking aspirin for his arthritis and drinks alcohol occasionally. He gives a history of occasional abdominal pain. On examination, there is no abdominal mass or tenderness. What is the likely diagnosis?","o":["Mallory-Weiss tear","Esophagitis","Peptic ulcer","Esophageal varices"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Surgery"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10100, '2023', 163, 'Gynaecology & Obstetrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":163,"q":"A woman presents to you at 36 weeks of gestation with complaints of feeling lightheadedness and dizziness when she lies on her back. She says she feels alright if she lies on her side or when walks. What is the most likely reason behind this? IVC- inferior vena cava","o":["Increased intracranial pressure","IVC compression","Heavy meals","Excessive venous pooling at the feet"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Gynaecology & Obstetrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10101, '2023', 164, 'Surgery', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":164,"q":"A 40-year-old male patient presents with a swelling that has been slowly growing in the past 2 years. On examination, it was variable in consistency and fully mobile. What is the most likely diagnosis?","o":["Dermoid cyst","Parotid tumor","Sebaceous cyst","Cervical lymph node"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Surgery"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10102, '2023', 165, 'Radiology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":165,"q":"A woman with endometrial carcinoma is undergoing radiotherapy. Which of the following is true?","o":["Intensity is inversely proportional to the square of the distance from the source","Small blood vessels are most radioresistant","Rapidly proliferating cells are most radioresistant","Small intestinal mucosa is most radio-resistant"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Radiology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10103, '2023', 166, 'Forensic Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":166,"q":"A child before playing consumed fruit from the garden. After some time he developed a high fever, confusion, photophobia, and unable to urinate. What are the likely causative agent and the appropriate antidote used in this case?","o":["Datura, Pralidoxime","Datura, Physostigmine","Yellow oleander, Pralidoxime","Yellow oleander, Physostigmine"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Forensic Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10104, '2023', 167, 'Radiology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":167,"q":"A patient presents with a history of fever and cough for the past 3-5 days. His examination findings reveal crepitations. Chest X-ray is given below. What is the probable diagnosis?","o":["Apical segment of Right lower lobe consolidation","Right middle lobe consolidation","Posterior segment of right lower lobe consolidation","Loculated pleural effusion"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Radiology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10105, '2023', 168, 'Anatomy', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":168,"q":"Injury at which of the following marked sites causes failure of dorsiflexion?","o":["3","2","1","4"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Anatomy"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10106, '2023', 169, 'Anatomy', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":169,"q":"A patient presents with swelling under the left ear lobule and complains of pain. Which of the following structures is the likely cause of the pain?","o":["Facial nerve","Greater auricular nerve","Auriculotemporal nerve","Investing layer of deep cervical fascia"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Anatomy"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10107, '2023', 170, 'Biochemistry', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":170,"q":"A child presents with bone pain and hepatosplenomegaly. A trephine biopsy and aspirate show the following finding. Which of the following is the most likely enzyme deficient in this condition?","o":["Hexosaminidase","Glucocerebrosidase","Sphingomyelinase","Alpha 1,4-glucosidase"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Biochemistry"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10108, '2023', 171, 'Forensic Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":171,"q":"The method of autopsy carried out en masse to remove from tongue to prostate is.","o":["Virchow technique","Rokitansky technique","Ghon technique","Letulle technique"],"a":3,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Forensic Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10109, '2023', 172, 'Forensic Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":172,"q":"A 42-year-old HIV-positive patient died, and his body was brought for post-mortem. The method of autopsy to be done is___","o":["Ghon technique","Letulle technique","Virchow technique","Rokitansky technique"],"a":3,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Forensic Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10110, '2023', 173, 'Microbiology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":173,"q":"A patient presented with a high fever, altered sensorium, headache, neck rigidity, and seizures. He was diagnosed with HSV encephalitis. Which of the following tests can be used to confirm the diagnosis?","o":["IgM in CSF","Tzanck smear of CSF","CSF PCR for viral DNA","CSF culture on chick embryo lines"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Microbiology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10111, '2023', 174, 'Microbiology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":174,"q":"In a patient presented with a fever and a positive filarial antigen test, what is the next appropriate method of management?","o":["Bone marrow biopsy","DEC provocation test","Detection of microfilariae in the blood smear","Ultrasound of the scrotum"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Microbiology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10112, '2023', 175, 'Forensic Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":175,"q":"A 10-year-old male child came to the casualty with difficulty in walking and pain in the perianal region. On subjecting the specimen from the perianal region to a test, it produces yellow needle-shaped rhombic crystals with picric acid. What is the test done?","o":["Barberio test","Florence test","Teichmann test","Acid phosphatase test"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Forensic Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10113, '2023', 176, 'Ophthalmology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":176,"q":"Which of the following refractive errors is associated with the image given below?","o":["Presbyopia","Astigmatism","Hypermetropia","Myopia"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Ophthalmology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10114, '2023', 177, 'Pathology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":177,"q":"Which of the following is true regarding the Mendelian mode of inheritance?","o":["Every 10th patient has a Y-linked disorder","1/3rd of Mendelian disorders is autosomal recessive","Every 5th patient has an X-linked recessive disorder","2/3 rd of Mendelian disorders are autosomal dominant"],"a":3,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Pathology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10115, '2023', 178, 'Forensic Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":178,"q":"A patient was brought to casualty with seizures. He had multiple episodes and was taking herbal medicines for the same. He was conscious in between the episodes. During the episodes, he had arching of his back. What is the likely cause?","o":["Strychnine","Ricinus","Nerium odorum","Datura"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Forensic Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10116, '2023', 179, 'Ophthalmology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":179,"q":"An infant is brought with complaints of excessive watering of the eyes and photophobia. The image is given below. What is the likely diagnosis?","o":["Congenital glaucoma","Congenital cataract","Mucopolysaccharidosis","Ophthalmia neonatorum"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Ophthalmology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10117, '2023', 180, 'Ophthalmology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":180,"q":"A 60-year-old patient complains of decreased distant vision but now he does not use spectacles for near vision. The image of his ocular examination is given below. What is this type of refractive error called?","o":["Index myopia","Axial myopia","Curvatural myopia","Positional myopia"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Ophthalmology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10118, '2023', 181, 'Pediatrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":181,"q":"A child is brought to the hospital with respiratory distress and biphasic stridor. The radiograph is shown below. What is the diagnosis?","o":["Acute epiglottitis","Acute laryngotracheobronchitis","Foreign body aspiration","Laryngomalacia"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Pediatrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10119, '2023', 182, 'Pathology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":182,"q":"A child presents with intermittent jaundice and splenomegaly. There is a history of similar complaints in the elder brother. Peripheral smear shows the following finding. How will you investigate this condition?","o":["Osmotic fragility test - Hereditary spherocytosis","Coombs test - AIHA","G6PD deficiency - Genetic testing","Paroxysmal nocturnal hemoglobinuria - Flow cytometry"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Pathology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10120, '2023', 183, 'Pediatrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":183,"q":"A 3-month-old baby presents with jaundice and clay-coloured stools. Lab investigation reveals that the baby has conjugated hyperbilirubinemia. The liver biopsy shows periductal proliferation. What is the most likely diagnosis?","o":["Crigler-Najjar syndrome","Rotor syndrome","Dubin-Johnson syndrome","Biliary atresia"],"a":3,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Pediatrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10121, '2023', 184, 'Forensic Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":184,"q":"Section 314 IPC deals with","o":["Causing miscarriage with the consent of the mother","Causing miscarriage without the consent of the mother","Death of the mother by act done with intent to cause miscarriage","Causing the death of the quick unborn child by an act amounting to culpable homicide"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Forensic Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10122, '2023', 185, 'Pathology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":185,"q":"An African child is found to have a mass in the jaw. A biopsy of the mass was done, and it appears as shown in the image below. The child also had a translocation of t(8;14). What is the probable diagnosis?","o":["Acute myeloid leukemia","Follicular lymphoma","Multiple myeloma","Burkitt lymphoma"],"a":3,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Pathology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10123, '2023', 186, 'Pediatrics', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":186,"q":"An infant presents with hepatosplenomegaly and thrombocytopenia. Neuroimaging with CT shows periventricular calcifications. What is the most likely diagnosis?","o":["Congenital rubella syndrome","Congenital herpes simplex virus infection","Congenital toxoplasmosis","Congenital cytomegalovirus infection"],"a":3,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Pediatrics"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10124, '2023', 187, 'Forensic Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":187,"q":"The temperature of a body of a deceased person is found to be 39 degrees Celsius. Which of the following is the most probable reason?","o":["Cyanide poisoning","Septicemia","Corrosive poisoning","Intra-abdominal hemorrhage"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Forensic Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10125, '2023', 188, 'Pathology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":188,"q":"A child presented to the hospital with cola-colored urine, hypertension, and puffiness of eyes. Laboratory investigations were done, and creatinine was 2.5 mg/dL. Treatment was started, and despite treatment, the patient did not improve for the next 3 weeks. The creatinine value increased to 4.5 mg/dL. Which among the following electron microscopic findings will be seen in this patient?","o":["Subendothelial deposits","Subepithelial deposits","Crescent formation","Mesangial deposits"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Pathology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10126, '2023', 189, 'PSM', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":189,"q":"A 35-year-old homeless man presented with a 1-month history of fever, cough, and weight loss. Both sputum smears turned out to be negative, but the chest x-ray ordered was suggestive of tuberculosis. According to the recent NTEP guidelines, which is the next best line of management?","o":["Repeat sputum smears","Ask for CBNAAT","Ask for line probe assay","Wait until TB culture results to start ATT"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"PSM"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10127, '2023', 190, 'Forensic Medicine', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":190,"q":"A farmer was sleeping in the field, and he felt a sting on his leg. He saw something moving away quickly. He then got drowsy and was taken to the hospital. He developed pain around the site and continued to bleed profusely from the wound site. The wound became red with blisters. Which of the following is the most likely cause?","o":["Viper","Cobra","Wasp bite","Scorpion"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Forensic Medicine"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10128, '2023', 191, 'Pathology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":191,"q":"A patient was transfused 4 units of blood 2 hours ago, and now she complains of chest discomfort. X-ray shows bilateral fissural thickening. Which of the following is the most probable cause?","o":["ABO incompatibility reactions","Fluid overload","Hypocalcemia","Graft-versus-host disease"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Pathology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10129, '2023', 192, 'PSM', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":192,"q":"Which of the following is the sensitive indicator to assess the availability, utilization, and effectiveness of healthcare in a community?","o":["Infant mortality rate","Maternal mortality rate","Immunization coverage","Disability-adjusted life years"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"PSM"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10130, '2023', 193, 'Pathology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":193,"q":"A 48-year-old man presents with complaints of facial puffiness, frothy urine, and hypertension. He gives a history of infection with hepatitis B. Urine examination reveals microscopic hematuria. The histopathological image of the kidney biopsy shows a spike and dome pattern. What is the diagnosis of this condition?","o":["Minimal change disease","Membranous nephropathy","FSGS","PSGN-associated disease"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Pathology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10131, '2023', 194, 'Pathology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":194,"q":"A 5-year-old child is brought with fever, fatigue, and left ventricular dysfunction. An endomyocardial biopsy is shown below. What is the probable diagnosis?","o":["Acute rheumatic fever","Chagas disease","Pyogenic myocarditis","Lymphocytic myocarditis"],"a":3,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Pathology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10132, '2023', 195, 'Pathology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":195,"q":"An elderly male is known as a smoker presented with chronic cough, significant weight loss, and fatigue. Serum calcium level is raised. A lung biopsy was done, and it showed large atypical cells with hyperchromasia. What is the probable diagnosis?","o":["Large cell neuroendocrine tumor","Small cell carcinoma","Adenocarcinoma","Squamous cell carcinoma"],"a":3,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Pathology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10133, '2023', 196, 'Pathology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":196,"q":"An elderly male went for a medical examination. Laboratory investigations showed a marked elevation of lymphocytes with marked leukocytosis. The peripheral smear of the patient is given below. What is the appropriate next step for this patient?","o":["Stem cell transplantation","Bone marrow biopsy","Flow cytometry","Start high-dose chemotherapy"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Pathology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10134, '2023', 197, 'Pathology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":197,"q":"A 25-year-old male presented with low hemoglobin, platelet count of 25,000/mL, gum bleeding, and raised PT & aPTT. The image of his peripheral smear is given below. What is the likely diagnosis?","o":["AML with t(8;21)","AML with inv(16)","AML with t(15;17)","AML with t(11;22)"],"a":2,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":true,"subject":"Pathology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10135, '2023', 198, 'Pathology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":198,"q":"A young patient presents with a large retroperitoneal hemorrhage. He also gives a frequent history of intermittent swelling of knees on strenuous exercise. There is no history of any mucosal bleeding. Which among the following clotting factors is responsible for the condition mentioned above?","o":["Factors VIII and IX","Factors XI and XII","Von Willebrand factor","Lupus anticoagulant"],"a":0,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Pathology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10136, '2023', 199, 'Pathology', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":199,"q":"A chronic smoker who worked in a cement factory for 20 years developed mesothelioma. The association is likely to be due to ________.","o":["Silicosis","Asbestosis","Coal workers'' pneumoconiosis","Bagassosis"],"a":1,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"Pathology"}');
INSERT OR REPLACE INTO pyq_questions (id, year, question_no, subject, source_file, data) VALUES (10137, '2023', 200, 'PSM', 'NEET-PG-2023-Question-Paper-With-Solutions (1).pdf', '{"no":200,"q":"The average daily dietary nutrient intake level sufficient to meet the nutrient requirements of nearly all (97-98%) healthy individuals in a particular life stage and gender group is known as?","o":["Adequate intake","Dietary goal","Estimated average requirement","Recommended dietary allowance"],"a":3,"year":"2023","source_file":"NEET-PG-2023-Question-Paper-With-Solutions (1).pdf","image_based":false,"subject":"PSM"}');
